INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1wx','一','1','yī','一','1','','[{"pinyin": "yī", "defs": [{"meaning": "(指事。“一”是汉字部首之一。本义:数词。大写作“壹”。最小的正整数。常用以表示人或事、物的最少数量)。"}, {"meaning": "同本义。", "cites": [{"t": "一,惟初太始道立于一,造分天地,化成万物。", "b": "《说文》"}, {"t": "一也者,万物之本也。", "b": "《淮南子·诠言》"}, {"t": "抱一而天下试。", "b": "《老子》"}, {"t": "故一人有事于四方。", "b": "《书·君奭》。传:“天子也。”"}, {"t": "一夫作难而七庙隳,身死人手,为天下笑。", "b": "汉·贾谊《过秦论》"}, {"t": "一夫夜呼,乱者四应。(公元九二年六月,李存莇妻刘皇后听信宦官诬告,杀死大臣郭崇韬,时谣言纷起,人心惶惶。屯驻在贝州(现河北省清河县)的军人皇甫晖勾结党羽作乱,拥立指挥使赵在礼为帅,攻入邺都(现河南省安阳市)。邢州(现河北省邢台市)、沧州驻军相继作乱。)", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "一境", "t": "一个地方"}, {"w": "一丝", "t": "一根蚕丝"}, {"w": "一碗水往平处端", "t": "办事公正不偏袒"}, {"w": "一拳正打在心窝", "t": "一下说到要害处"}, {"w": "一人做一人当", "t": "敢做就敢于承认,绝不连累别人"}, {"w": "一客不烦二主", "t": "托一人能办的事,就不再打扰第二个人"}, {"w": "一动不如一静", "t": "动不如静好"}, {"w": "一言抄百语", "t": "总而言之"}, {"w": "一缘一会", "t": "天缘凑合"}, {"w": "一路功名", "t": "仕途顺利,官运亨通"}, {"w": "一盘一盒", "t": "礼物"}, {"w": "一清如水", "t": "静悄悄地没有人影"}, {"w": "一毫不爽", "t": "一点不差"}, {"w": "一息恹恹", "t": "疾病缠身,气息微弱。"}]}, {"meaning": "序数的第一位。", "cites": [{"t": "一战而举鄢、郢。(第一仗就攻下了楚国的重要城市鄢、郢。一战,第一战。指楚顷襄王二十年即公元前279年,秦将白起攻下楚国的鄢、郢二都的战争。举,攻下。鄢,地名,在今湖北省宜城县境。郢,地名,在今湖北省江陵县境。)", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "一紧二慢三罢休", "t": "指先紧后慢、最后不了了之的官场办事作风"}, {"w": "一来二去", "t": "经过一段时间的周折"}, {"w": "一品锅", "t": "一种里面杂放鸡鸭鱼肉、山珍海味的“砂锅”"}, {"w": "一甲", "t": "科举殿试第一至第三名,赐进士及第"}, {"w": "一更", "t": ""}, {"w": "一品", "t": "犹言一等;第一等"}, {"w": "一等一", "t": "第一等中的第一名"}]}, {"meaning": "若干份中的一份或整数以外的零头。", "cites": [{"t": "先王之制,大都不过参国之一,中五之一,小九之一。", "b": "《左传》"}], "words": [{"w": "一脚", "t": "动物身体的四分之一,一条腿的部分"}, {"w": "丈一", "t": ""}, {"w": "一份", "t": "整体分为若干份的一部分"}, {"w": "一杆子", "t": "方言。犹言一部分"}, {"w": "一得", "t": "得到一件或一个"}, {"w": "一端", "t": "指物件的一头。"}]}, {"meaning": "表示动作一次或短暂。", "cites": [{"t": "一至楚。", "b": "《史记·平原君虞卿列传》"}, {"t": "初一交战。", "b": "《资治通鉴》"}, {"t": "抚尺一下。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "一拿一个着", "t": "一下子就拿住"}, {"w": "一气一个死", "t": "气得要命"}, {"w": "一忽觉转", "t": "一觉醒来"}, {"w": "一时半霎", "t": "指时间极短"}, {"w": "一个眼闪", "t": "一会儿工夫"}, {"w": "一之为甚", "t": "一次已经过分了。用来劝人不要重犯错误。"}]}, {"meaning": "全;满。", "cites": [{"t": "一肌一容(一:全部。指宫女的整个肌肤容貌)。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "传一乡。", "b": "宋·王安石《伤仲永》"}, {"t": "洞庭一湖。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "长烟一空。", "b": ""}, {"t": "欢动一城。", "b": "明·高启《书博鸡者事》"}, {"t": "通订一舟。", "b": "明·魏学《核舟记》"}], "words": [{"w": "一罟", "t": "全部;一点不留"}, {"w": "一是", "t": "全赁"}, {"w": "一凭", "t": "任凭;完全凭仗"}, {"w": "一抹", "t": "全部"}, {"w": "一听", "t": "听任"}, {"w": "一划", "t": "一派"}, {"w": "一床", "t": "全部"}, {"w": "一力", "t": "竭力"}, {"w": "一创", "t": "整个"}, {"w": "一到处", "t": "到处;四处"}, {"w": "一条提", "t": "全部;统统"}, {"w": "一抹光", "t": "一律免除或不予追究"}, {"w": "一到处", "t": "遍地里"}, {"w": "一肩儿", "t": "所承担的全部责任。"}]}, {"meaning": "统一。", "cites": [{"t": "以一中外之心,以色觊觎之望。", "b": "《子谦全传》"}, {"t": "六王毕,四海一。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "一正", "t": "统一法度政令"}, {"w": "一匡", "t": "使得到匡正"}, {"w": "一法", "t": "统一的法令"}, {"w": "一是", "t": "犹言统一的标准"}, {"w": "一量", "t": "统一度量"}, {"w": "一统天下", "t": "统一全国。"}]}, {"meaning": "专一。", "cites": [{"t": "用心一世。", "b": "《荀子·劝学》"}], "words": [{"w": "一德无暇", "t": "一心一意,没有一点虚情假意"}, {"w": "一心一计", "t": "一心一意。"}]}, {"meaning": "都,一概。", "cites": [{"t": "一匡天下。", "b": "《史记·货殖列传》"}], "words": [{"w": "一划", "t": "一律"}, {"w": "一回", "t": "一概"}, {"w": "一弄", "t": "一切;全体"}, {"w": "一抹光", "t": "全都包括在内"}, {"w": "一往", "t": "一概;一律"}, {"w": "一括", "t": "犹言总括"}, {"w": "一是", "t": "一概。"}]}, {"meaning": "一经。", "cites": [{"t": "诚一开口。", "b": "《史记·魏公子列传》"}, {"t": "俗之一改。", "b": "《史记·屈原贾生列传》"}, {"t": "黄鹤一去不复返,", "b": "唐·崔颢《黄鹤楼》"}, {"t": "禄山一出。", "b": "宋·苏轼《教战守》"}, {"t": "一出门。", "b": "《聊斋志异·促织》"}], "words": [{"w": "一膺新命", "t": "一旦接受朝廷的任命"}, {"w": "一觉", "t": "一旦"}, {"w": "一头", "t": "一旦"}, {"w": "一投", "t": "方言。一等到;一旦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2wx','乙','1','yǐ','乙','1','','[{"pinyin": "yǐ", "defs": [{"meaning": "(象形。甲骨文字形。本义:象植物屈曲生长的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "乙,草木冤曲而出也。象形。", "b": "《说文》"}, {"t": "乙者,物蕃屈有节欲出。", "b": "《白虎通》"}, {"t": "思乙乙其若抽。", "b": "陆机《文赋》。注:“抽也。”"}, {"t": "其於十母为甲乙。甲者,为万物剖符甲而出也;乙者,言万物生轧轧也。", "b": "《史记·律书》"}], "words": [{"w": "乙乙", "t": "难出之貌。"}]}, {"meaning": "天干的第二位,与地支相配,用以纪年、月、日。", "cites": [{"t": "其日甲乙。", "b": "《礼记·月令》"}, {"t": "甲乙。", "b": "《淮南子·天文》注"}, {"t": "帝乙归妹。", "b": "《易·泰》"}, {"t": "微子启帝乙之元子也。", "b": "《左传·哀公九年》"}]}, {"meaning": "某人。", "cites": [{"t": "甲乙同学。", "b": "清·周容《芋老人传》"}, {"t": "甲先得举。", "b": ""}], "words": [{"w": "某甲某乙", "t": ""}]}, {"meaning": "鱼腮骨。", "cites": [{"t": "狼去肠…鱼去乙。郑玄注:“乙,鱼体中害人者名也。今东海容鱼有骨,名乙,在目旁,状如篆乙,食之鲠不可出。”", "b": "《礼记·内则》"}]}, {"meaning": "虎两肋和尾端有骨,形如乙字,叫虎威。", "cites": [{"t": "得如虎挟乙,失若龟藏六。", "b": "宋·苏轼《寄微轩》"}]}, {"meaning": "碾压;压抑。", "cites": [{"t": "西太守,乙卯金。", "b": "《后汉书》。李贤注:“乙,轧也。述言西方太守能轧绝卯金也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3wx','二','1','èr','二','2','','[{"pinyin": "èr", "defs": [{"meaning": "(会意。古文字二用两横画表示,是原始记数符号)。"}, {"meaning": "一加一的和。", "cites": [{"t": "二,地之数也。从耦一,会意。古文又从弋。", "b": "《说文》"}, {"t": "因二以济民行。", "b": "《易·系辞》。虞注:“谓乾与坤也。后世官书以贰为之,为防奸易。”"}, {"t": "赐也闻一以知二。", "b": "《论语·公冶长》"}, {"t": "大父未死而有二十五孙。", "b": "《韩非子·五蠹》"}], "words": [{"w": "二加四得六", "t": ""}, {"w": "二府", "t": "大肠和小肠"}, {"w": "二太爷", "t": ""}, {"w": "总数为二", "t": ""}, {"w": "二形", "t": "男女两性"}, {"w": "二难", "t": "指难兄难弟,即蔡、宋两御史"}, {"w": "二仪", "t": "两仪。指天地、阴阳"}, {"w": "二纪", "t": "二十四年。一纪为十二年"}, {"w": "二氏", "t": "释教与道教"}, {"w": "二军", "t": "汉代禁卫军之南军和北军"}, {"w": "二南", "t": "原指《诗经》中的《周南》与《召南》借指淑女与君子相配"}, {"w": "二星", "t": "银子二钱。星,秤杆上的记数点"}, {"w": "二天", "t": "再嫁;嫁二夫。"}]}, {"meaning": "排列顺序中第二位的。", "cites": [{"t": "一男附书至,二男新战死。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "二手", "t": "副手,二把手"}, {"w": "二尹", "t": "知县副职县丞的别称"}, {"w": "二舍", "t": "二公子,二少爷。舍:舍人。原为官名,后用以称显贵人家子弟"}, {"w": "二甲", "t": "殿试的第二等"}, {"w": "二门", "t": "指大门内的一道总门。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4wx','十','1','shí','十','2','','[{"pinyin": "shí", "defs": [{"meaning": "(指事。甲骨文象用一根树枝代表十,金文象是结绳记数,用一个结表示十。后来一点变成了一横。本义:九加一的和)。"}, {"meaning": "同本义。", "cites": [{"t": "十,数之具也。—为东西,|为南北,则四方中央备矣。", "b": "《说文》"}, {"t": "十是数之小成。", "b": "《左传·僖公四年》疏"}, {"t": "十亩之间兮。", "b": "《诗·小雅·六月》"}, {"t": "兵也者,审于地图,谋十官。", "b": "《管子·七法》"}, {"t": "天下欲反,十室九空。", "b": "葛洪《抱朴子·用刑》"}, {"t": "与吾祖居者,今其室十无一焉。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "十里长亭", "t": "古时设在路旁的亭子,常用作送别饯行之处"}, {"w": "十番", "t": "合奏乐以十种乐器演奏的名称"}, {"w": "十牌", "t": "十户人家。牌:门牌"}, {"w": "十地", "t": "佛教称菩萨修行渐近于佛的十种境界"}, {"w": "十生九", "t": "死的歇后语"}, {"w": "十方地面", "t": "庙宇。佛教指东、西、南、北、东南、西南、东北、西北和上下"}, {"w": "十方常住", "t": "寺庙。佛教认为“不变”为常住。寺庙是不变的,故称"}, {"w": "十有九就", "t": "十成之中有九成可望成功。"}]}, {"meaning": "指十分;十份。", "cites": [{"t": "比好游者尚不能十一。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "十一", "t": "十分之一"}, {"w": "十半", "t": "十分之五。"}]}, {"meaning": "表示约数。犹言十来个。", "cites": [{"t": "辱十城之虚寿,奄咸阳以取隽。", "b": "《文选·潘岳·西征赋》"}]}, {"meaning": "序数的第十位。", "cites": [{"t": "请以赵十五城为秦王寿。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "十五删", "t": "诗韵中上平声第十五个韵目"}, {"w": "十四寒", "t": "诗韵中上平声第十四个韵目"}, {"w": "十三元", "t": "依据《佩文诗韵》“元”字列在上平声第十三位,故称。"}]}, {"meaning": "表示多;齐全;完备。", "cites": [{"t": "九十其仪。", "b": "《诗·豳风·东山》"}, {"t": "十目所视,十手所指,其严乎!", "b": "《礼记·大学》"}], "words": [{"w": "十郎八当", "t": "落花流水,七零八落"}, {"w": "十变五化", "t": "变化多端"}, {"w": "十亲九眷", "t": "众多亲戚"}, {"w": "十相具足", "t": "十分美貌"}, {"w": "十相俱足", "t": "娇妻美妾俱全"}, {"w": "十数", "t": "十多;十几,表示众多"}, {"w": "十荡十决", "t": "多次冲击均能破敌"}, {"w": "十万", "t": "数目。又形容数量极多"}, {"w": "十恶五逆", "t": "种种不可赦免的大罪"}, {"w": "十尧", "t": "圣人众多"}, {"w": "十朋", "t": "许多朋友"}, {"w": "十有八九", "t": "绝大多数。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5wx','丁','1','dīng zhēng','一','2','','[{"pinyin": "dīng", "defs": [{"meaning": "(象形。金文象俯视所见的钉头之形,小篆象侧视的钉形。本义:钉子)。"}, {"meaning": "同本义。丁为“钉”的古字。", "cites": [{"t": "丁,钻也。象形。今俗以钉为之,其质用金或竹,若木。", "b": "《说文》"}], "words": [{"w": "丁屐", "t": "底有钉齿的木鞋"}, {"w": "丁子", "t": "蝌蚪。初生头大有尾,如丁字。"}]}, {"meaning": "天干的第四位,与地支相配,用以纪年、月、日。", "cites": [{"t": "其日丙丁。", "b": "《吕氏春秋·孟夏》"}, {"t": "夏,四月,丁未,公及郑伯盟于越。", "b": "《春秋》"}]}, {"meaning": "能担任赋役的成年男子,不同于男孩。", "cites": [{"t": "无何天宝大征兵,户有三丁点一丁。", "b": "唐·白居易《新丰折臂翁》"}, {"t": "余丁传餐。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "丁粮", "t": "对男丁征收的粮食"}, {"w": "丁力", "t": "一男之力。引申为劳力"}, {"w": "丁女", "t": "能担任力役的成年女子;道家语指火神"}, {"w": "丁奴", "t": "二十岁以上的成年奴仆 ;成丁;壮丁。"}]}, {"meaning": "指从事某种劳动的人 。如 :园丁;家丁;庖丁。"}, {"meaning": "壮盛;强壮。", "cites": [{"t": "齿落复生,身气丁强。", "b": "汉·王充《论衡·无形》"}], "words": [{"w": "丁丁", "t": "壮健的样子"}, {"w": "丁人", "t": "壮健的男子"}, {"w": "丁夫", "t": "壮健的男子。"}]}, {"meaning": "当;遭逢。", "cites": [{"t": "丁,当也。", "b": "《尔雅》。注:“相当值。”"}, {"t": "宁丁我躬?", "b": "《诗·大雅·云汉》"}, {"t": "丁时逢殃。", "b": "汉·刘向《九叹·惜贤》"}, {"t": "我喜我生,独丁斯时。", "b": "《后汉书·岑彭传》"}, {"t": "丁时逢殃,孰可夸何兮。", "b": "汉·刘向《九叹·惜贤》"}], "words": [{"w": "丁辰", "t": "适逢其时"}, {"w": "丁仔", "t": "遇上,碰巧"}, {"w": "丁夫忧", "t": "遇父丧"}, {"w": "丁了母忧", "t": "遭了母丧。"}]}]}, {"pinyin": "zhēng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6wx','厂','1','chǎng ān hàn','厂','2','','[{"pinyin": "chǎng", "defs": [{"meaning": "(形声。从广(yǎn),敞声。从“广”,表示与房屋有关。本义:棚舍)。"}, {"meaning": "没有墙壁的简易房屋。", "words": [{"w": "厂屋", "t": "棚舍;无隔墙的房屋。"}]}, {"meaning": "马屋;牲口棚子。", "cites": [{"t": "架北墙为厂。", "b": "《齐民要术》"}]}, {"meaning": "工厂。", "cites": [{"t": "正德十四年,广州置铁厂。", "b": "《明史·食货志》"}], "words": [{"w": "纱厂", "t": ""}, {"w": "钢厂", "t": ""}, {"w": "面粉厂", "t": ""}, {"w": "纺织厂", "t": ""}, {"w": "造纸厂", "t": ""}]}]}, {"pinyin": "ān", "defs": [{"meaning": "多用于人名。"}]}, {"pinyin": "hàn", "defs": [{"meaning": "山边岩石突出覆盖处，人可居住的地方。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7wx','七','1','qī','一','2','','[{"pinyin": "qī", "defs": [{"meaning": "(指事。从一ㄣ。画以纪数。本义:六加一的和)。"}, {"meaning": "同本义。", "cites": [{"t": "七,阳之正也。从一,微阴从中斜出也。", "b": "《说文》"}, {"t": "其数七。", "b": "《礼记·月令》"}, {"t": "七者,天地四时人之始也。", "b": "《汉书·律历志》"}, {"t": "七主星。", "b": "《大戴礼记·易本命》"}, {"t": "七日得。", "b": "《易·既济》。虞注:“震为七。”"}, {"t": "凡攻木之工七。", "b": "《周礼·考工记》"}, {"t": "有子七人。", "b": "《诗·邶风·凯风》"}], "words": [{"w": "七宝", "t": "佛经上指金、银、琉璃、砗磲、玛璃、珍珠、玫瑰"}, {"w": "七出", "t": "旧指休妻的七种理由:无子,淫泆报会,不事舅姑,口舌,盗窃,妒忌,恶疾"}, {"w": "七年", "t": ""}, {"w": "七秩", "t": "七十大寿"}, {"w": "七雄", "t": "指战国时秦、韩、魏、楚、燕、齐、赵七国。"}]}, {"meaning": "姓(明代有七希贤)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('8wx','卜','1','bo bǔ','卜','2','','[{"pinyin": "bo", "defs": [{"meaning": "——见“萝卜”。"}]}, {"pinyin": "bǔ", "defs": [{"meaning": "(象形。甲骨文字形,象龟甲烧过后出现的裂纹形。汉字部首之一,从“卜”的字多与占卜有关。本义:占卜)。"}, {"meaning": "古人用火灼龟甲,根据裂纹来预测吉凶,叫卜。", "cites": [{"t": "问龟曰卜。", "b": "《周礼·大卜》注"}, {"t": "龟为卜,蓍为筮。", "b": "《礼记·曲礼》"}, {"t": "尔卜尔筮,体无咎言。", "b": "《诗·卫风·氓》"}, {"t": "初,晋献公欲骊姬为夫人,卜之,不吉,筮之,吉。", "b": "《左传·僖公四年》"}, {"t": "卜者知其指意。", "b": "《史记·陈涉世家》"}], "words": [{"w": "卜一课", "t": "算一卦。课:一种占卜"}, {"w": "卜正", "t": "掌管卜筮的官"}, {"w": "卜人", "t": "官名。《周礼》春官之属,掌管占卜"}, {"w": "卜师", "t": "官名。《周礼》春官之属,位次于大卜,掌占卜龟痕之事。"}]}, {"meaning": "选择。", "cites": [{"t": "系舟蛮井路,卜宅楚村墟。", "b": "杜甫《秋野》"}], "words": [{"w": "卜郊", "t": "占卜选定日期以行郊祭"}, {"w": "卜居", "t": "占卜选择居住的地方"}, {"w": "卜老", "t": "选择住地养老"}, {"w": "卜地", "t": "选择福地。"}]}, {"meaning": "赐予;给予。", "cites": [{"t": "卜尔百福,如几如式。", "b": "《诗·小雅·楚茨》"}]}, {"meaning": "推断;预料。", "cites": [{"t": "仆自卜固无取。", "b": "柳宗元《答韦中立论师道书》"}, {"t": "今南海之生死未可卜。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "卜度", "t": "推测;臆断"}, {"w": "卜揆", "t": "测度谋划。"}]}, {"meaning": "卜官,卜卦之人。", "cites": [{"t": "近乎卜祝之间。", "b": "司马迁《报任安书》"}]}, {"meaning": "元代戏曲中扮演老妇的角色。", "cites": [{"t": "卜儿哭上科。", "b": "关汉卿《窦娥冤》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('9wx','八','1','bā','八','2','','[{"pinyin": "bā", "defs": [{"meaning": "(象形。甲骨文象分开相背的样子。汉字部首之一。从“八”的字多与分解、分散、相背有关。本义:相背分开) 同本义。", "cites": [{"t": "八,别也。象分别相背之形。", "b": "《说文》。段玉裁注:“今江、浙俗语以物与人谓之八,与人则分别矣。”"}]}, {"meaning": "七加一的和。", "cites": [{"t": "八,数也。", "b": "《玉篇》"}, {"t": "陈馈八簋。", "b": "《诗·小雅·伐木》"}, {"t": "地理以八制。", "b": "《管子·五行》。注:“少阴之数。”"}, {"t": "八者,维纲也。", "b": "《大戴礼记·本命》。按,谓八方四正四隅。"}, {"t": "遇艮之八。史曰,是谓艮之随言,六二爻也。余五爻皆变。凡易用六不用八。八,少阴不变也。", "b": "《左传·襄公九年》"}, {"t": "八眉者,如八字。", "b": "《尚书大传》"}, {"t": "邹忌修八尺有余。", "b": "《战国策·齐策》"}, {"t": "八音克谐。", "b": "《书·舜典》"}, {"t": "秦王复击轲,被八创。", "b": "《战国策·燕策》"}, {"t": "八世。", "b": "《后汉书·崔实传》。注:“谓三王五帝也。”"}], "words": [{"w": "八音", "t": "中国古代对乐器的统称。通常为金、石、丝、竹、匏、土、革、木八种不同的质材所制"}, {"w": "八拜", "t": "古代世交子弟对长辈的礼节,后世将异姓结为兄弟亦称八拜。"}]}, {"meaning": "常表次第,即第八。", "cites": [{"t": "八月在宇。", "b": "《诗·豳风·七月》"}], "words": [{"w": "八世", "t": ""}, {"w": "八年", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('10wx','人','1','rén','人','2','','[{"pinyin": "rén", "defs": [{"meaning": "(象形。甲骨文字形,象侧面站立的人形。“人”是汉字部首之一。本义:能制造工具改造自然并使用语言的高等动物)。"}, {"meaning": "同本义。", "cites": [{"t": "人,天地之性最贵者也。此籀文象臂胫之形。", "b": "《说文》"}, {"t": "故人者,天地之德,阴阳之交,鬼神之会,五行之秀气也。故人者,天地之心也,五行之端也,食味,别声,被色,而生者也。", "b": "《礼记·礼运》"}, {"t": "有七尺之骸、手足之异,戴发含齿,倚而食者,谓之人。", "b": "《列子·黄帝》"}, {"t": "人未有不乐为治平之民者也。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "人王", "t": "人中之王"}, {"w": "人满", "t": "人多"}, {"w": "人寰", "t": "人世"}, {"w": "人欲", "t": "人的嗜欲"}, {"w": "人人言", "t": "人的评论"}, {"w": "人色", "t": "人的正常面色"}, {"w": "人头号令", "t": "用人头示众以示儆戒"}, {"w": "人淘里", "t": "人群里。"}]}, {"meaning": "某人;某种人;某些人。", "cites": [{"t": "劳心者治人,劳力者治于人。", "b": "《孟子·滕文公上》"}, {"t": "智伯说,又令人请地于魏。", "b": "《韩诽 子·十过》"}], "words": [{"w": "人兵", "t": "兵马"}, {"w": "猎人", "t": ""}, {"w": "主持人", "t": ""}, {"w": "盲人", "t": ""}, {"w": "工人", "t": ""}, {"w": "介绍人", "t": ""}, {"w": "行人", "t": ""}, {"w": "证人", "t": ""}, {"w": "法人", "t": ""}]}, {"meaning": "别人,他人。", "cites": [{"t": "与人罕言语。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "人去不中留", "t": "本人坚决要离去,他人要留是留不住的"}, {"w": "人皆下之", "t": "人家都瞧不起他"}, {"w": "人物", "t": "别人的东西"}, {"w": "人我", "t": "他人与我"}, {"w": "人言", "t": "别人的评议。"}]}, {"meaning": "民,百姓。", "cites": [{"t": "吴广素爱人。", "b": "《史记·陈涉世家》"}, {"t": "为天下人谋永福也。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "人帐", "t": "常人"}, {"w": "人佚", "t": "民佚"}, {"w": "人黎", "t": "平民,百姓"}, {"w": "人听", "t": "即民听,指老百姓的视听"}, {"w": "人上", "t": "众人之上"}, {"w": "人宗", "t": "众人的楷模"}, {"w": "人等", "t": "众人,许多人。"}]}, {"meaning": "指成年人。", "cites": [{"t": "以一人生三计之。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "人种", "t": "能传种接代的男人。"}]}, {"meaning": "伴侣。", "cites": [{"t": "上与神明为友,下与造化为人。", "b": "《淮南子》"}]}, {"meaning": "果仁", "cites": [{"t": "核者,人也。古曰核,今曰人。", "b": "《尔雅·释木》郝懿行义疏"}]}, {"meaning": "仁爱。", "cites": [{"t": "谓之好人。", "b": "《管子·侈靡》"}, {"t": "术礼义而情爱人。", "b": "《荀子·修身》"}, {"t": "故君子责人则以人,责己则以义。", "b": "《吕氏春秋·举难》"}]}, {"meaning": "每人  一定人群中的每一个。", "cites": [{"t": "人皆贺之。", "b": "《淮南子·人间训》"}], "words": [{"w": "人人", "t": "每个人;所有的人"}, {"w": "人不可貌相", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('11wx','入','1','rù','入','2','','[{"pinyin": "rù", "defs": [{"meaning": "(象形。甲骨文字形,象个尖头器具,尖头器具容易进入。本义:进来,进去)。"}, {"meaning": "同本义。", "cites": [{"t": "入,内也。", "b": "《说文》"}, {"t": "他人入室。", "b": "《诗·唐风·山有枢》"}, {"t": "就不欲入。", "b": "《庄子·人间世》"}, {"t": "有蛇自泉宫出,入于国。", "b": "《左传·文公十六年》"}, {"t": "君为我呼入,吾得兄事之。", "b": "《史记·项羽本纪》"}, {"t": "鲁有执长竿入城门者。", "b": "三国魏·邯郸淳《笑林》"}], "words": [{"w": "入门问讳", "t": "到别人家里,先需了解人家先祖名讳,以便谈话"}, {"w": "入对", "t": "进宫回答皇帝的问题"}, {"w": "入览", "t": "看到"}, {"w": "入迁", "t": "从外地迁到京城做官"}, {"w": "入学", "t": "童生考取秀才"}, {"w": "入口", "t": ""}, {"w": "入帘", "t": "科举时期,考官进场阅卷。"}]}, {"meaning": "参加, 加入。", "cites": [{"t": "室人入又。", "b": "《诗·小雅·宾之初筵》"}, {"t": "自四卿入军机,然后皇上与康先生之意始能少通。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "入舍布袋", "t": "上门女婿"}, {"w": "入舍女婿", "t": "入舍"}, {"w": "入释", "t": "参加佛教;进入佛门"}, {"w": "入舍", "t": "做上门女婿"}, {"w": "入脚", "t": "进身;指搭上关系"}, {"w": "入队", "t": ""}, {"w": "入伙", "t": ""}, {"w": "入金马、登玉堂", "t": "考进翰林院。金马、玉堂指汉代的金马门和玉堂殿"}, {"w": "入局", "t": "加入赌局"}, {"w": "入团", "t": ""}]}, {"meaning": "交、交纳。", "cites": [{"t": "入其社稷之臣于秦。", "b": "《战国策·秦策》"}, {"t": "岁恶不入,请卖爵子。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "入粟", "t": "交纳一定数目的钱捐取功名。"}]}, {"meaning": "接纳;采纳。", "cites": [{"t": "凡嫁子娶妻,入币纯帛,无过五两。", "b": "《周礼·地官·媒氏》"}, {"t": "其臣箴谏以不入。", "b": "《国语·吴语》"}, {"t": "野人莫敢入王。", "b": "《史记·楚世家》"}, {"t": "商君亡秦归魏,魏怒不入。", "b": "《史记·魏世家》"}, {"t": "时上颇厌兵,入其言。", "b": "罗大经《鹤林玉露》"}]}, {"meaning": "与…相适应。", "cites": [{"t": "曲直之不相入。", "b": "《淮南子·主术》。注:“中也。”"}], "words": [{"w": "入式", "t": "合乎程式"}, {"w": "入道", "t": ""}, {"w": "入彀", "t": ""}]}, {"meaning": "入朝,指属国、外国使臣或地方官员谒见天子。", "cites": [{"t": "强国请服,弱国入朝。", "b": "汉·贾谊《过秦论上》"}, {"t": "项伯即入见沛公。", "b": "《史记·项羽本纪》"}], "words": [{"w": "入阁拜相", "t": "进入内阁,成为宰相"}, {"w": "入王", "t": "入朝晋见天子"}, {"w": "入侍", "t": "入朝侍奉"}, {"w": "入见", "t": "入宫进见"}, {"w": "入宦", "t": "入官为仆隶"}, {"w": "入相", "t": "入朝为宰相"}, {"w": "入宿", "t": "入宫值宿"}, {"w": "入贺", "t": "入朝庆贺。"}]}, {"meaning": "到达。", "cites": [{"t": "寒雨连江夜入吴。", "b": "唐·王昌龄《芙蓉楼送辛渐》"}], "words": [{"w": "入月", "t": "妇女孕期足月"}, {"w": "入玄", "t": "达到玄妙的境界"}, {"w": "入来", "t": "到来;进来"}, {"w": "入脚", "t": "到临,开始"}, {"w": "入圣", "t": "达到圣人的境界。"}]}, {"meaning": "侵入。", "cites": [{"t": "获大城焉曰入之。", "b": "《左传·文公十五年》"}, {"t": "英法联军自海入侵。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "入犯", "t": ""}, {"w": "入抄", "t": "侵入抄掠。"}]}, {"meaning": "占据。", "cites": [{"t": "乃入据陈(地名)。", "b": "《史记·陈涉世家》"}], "words": [{"w": "入席", "t": ""}, {"w": "入列", "t": ""}, {"w": "入主", "t": "外族进入中原作统治者"}, {"w": "入官", "t": "从政,做官。"}]}, {"meaning": "收入,进项。", "cites": [{"t": "殚其地之出,竭其庐之入。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "岁入", "t": ""}, {"w": "入不敷出", "t": ""}]}, {"meaning": "古汉语声调之一——见“入声”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('12wx','儿','1','ér','儿','2','','[{"pinyin": "ér", "defs": [{"meaning": "(象形。甲骨文字形,下面是“人”字,上面象小儿张口哭笑。“儿”是汉字部首之一,从“儿”的字大都与“人”有关。本义:幼儿。古时男称儿,女称婴,后来孩童都称儿)。"}, {"meaning": "同本义。", "cites": [{"t": "儿,孺子也。", "b": "《说文》"}, {"t": "专气致柔,能如婴儿乎?", "b": "《老子》第九章"}, {"t": "老人儿啼。", "b": "《史记·循吏列传》"}, {"t": "男曰儿,女曰婴。", "b": "《苍颉篇》"}, {"t": "见两小儿辩斗。", "b": "《列子·汤问》"}], "words": [{"w": "儿女子", "t": "孩童"}, {"w": "儿剧", "t": "犹儿戏"}, {"w": "儿话", "t": "孩子话"}, {"w": "儿撬", "t": "拐棍儿"}, {"w": "儿拜", "t": "孩童对大人所行的礼拜"}, {"w": "儿啼", "t": "小孩哭"}, {"w": "儿孩", "t": "孩童。"}]}, {"meaning": "父母对儿子的称呼。", "cites": [{"t": "儿,子也。", "b": "《广雅·释亲》"}, {"t": "汤为儿守舍。", "b": "《汉书·张汤传》"}, {"t": "外黄令舍人儿年十三。", "b": "《汉书·项藉传》"}, {"t": "大儿锄豆溪东,中儿正织鸡笼。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "阿爷无大儿。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "儿媳", "t": "即儿媳妇"}, {"w": "儿子花", "t": "儿子的影子"}, {"w": "儿曹", "t": "儿辈"}, {"w": "儿息", "t": "子息。"}]}, {"meaning": "我。"}, {"meaning": "子女对父母的自称。", "cites": [{"t": "兰芝惭阿母:“儿实无罪过。”", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "古代年轻女子的自称。", "cites": [{"t": "送儿还故乡。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "儿家", "t": "古代年轻女子的自称;你,称女子。"}]}, {"meaning": "弟对兄的自称。", "cites": [{"t": "[帝] 乃以延宗为相国、并州刺史,总山西兵事。 谓曰∶“并州阿兄取,儿今去也。”", "b": "《北史·齐安德王延宗传》"}]}, {"meaning": "自己的  用于古代妇女称自己丈夫。", "cites": [{"t": "宣和中士女观灯者赐酒。有夫妇并游,不获同进,其妇蒙赐,辄怀酒杯,谢词曰:“归来恐被儿夫怪,愿赐金杯作证盟。”上赐之。", "b": "《月令广义》"}]}, {"meaning": "儿化。汉语后缀的“儿”不自成音节,而和前面一个音节合在一起构成带卷舌韵母r的音节。"}, {"meaning": "多用作名词后缀 表示小。如:盆儿;棍儿;小猫儿;小车儿 表示词性变化。动词名词化,如:唱儿;逗笑儿。形容词名词化,如:亮儿;零碎儿 表示具体事物抽象化。如:口儿;门儿;根儿 表示词义变化。如:白面儿(海洛因);老家儿(对人称自己或别人的父母)。"}, {"meaning": "形容词后缀。如邵雍《首尾吟》:“天听虽高只些子,人情想去没多儿。”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('13wx','匕','1','bǐ','匕','2','','[{"pinyin": "bǐ", "defs": [{"meaning": "(象形。从二匕,匕亦声。甲骨文字形,象汤匙形。汉字部首之一。本义:勺子。按:一说“匕”象反人形,“妣”之初文)。"}, {"meaning": "古代的一种取食器具,长柄浅斗,形状像汤勺。", "cites": [{"t": "先主方食,失匕箸。(箸:筷子)", "b": "《三国志·蜀志·先主传》"}], "words": [{"w": "比筋", "t": "羹匙与筷子。"}]}, {"meaning": "匕首。", "cites": [{"t": "丈人目先生,使引匕刺狼。", "b": "明·马中锡《中山狼传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('14wx','几','1','jī jǐ','几','2','','[{"pinyin": "jī", "defs": [{"meaning": "(象形。本义:古人席地而坐时有靠背的坐具)。"}, {"meaning": "同本义。", "cites": [{"t": "几,坐所以凭也。", "b": "《说文》"}, {"t": "掌五几五席之名物。", "b": "《周礼·司几筵》。注:“五几:左右玉雕彤漆素。”"}, {"t": "室中度以几,堂上度以筵。", "b": "《考工记·匠人》"}, {"t": "几杖,所以扶助衰也。", "b": "《白虎通·致仕》"}, {"t": "必操几杖以从之。", "b": "《礼记·曲礼》"}, {"t": "有司以几筵舍奠于墓左。", "b": "《礼记·檀弓》。疏:“依神也。”"}, {"t": "或肆之筵,或授之几。", "b": "《诗·大雅·行苇》"}], "words": [{"w": "几杖", "t": "供老人依靠的小桌子和支撑用的手杖。古代赐几杖,表示敬老的礼节"}, {"w": "几席", "t": "几和席,为古人凭依、坐卧的器具"}, {"w": "几榻", "t": "靠几与卧榻,常用以泛指日用器具"}, {"w": "几簟", "t": "几席。"}]}, {"meaning": "后专指有光滑平面、由腿或其它支撑物固定起来的小桌子。", "cites": [{"t": "吾妻来归。时至轩中,从余问古事,或凭几学书。", "b": "明·归有光《项脊轩志》"}, {"t": "入其舍,则密室垂帘,帘外设香几。", "b": "《聊斋志异·促织》"}], "words": [{"w": "几案", "t": "桌子。因几案用于办公,因以代表公牍文书"}, {"w": "几案之才", "t": "处理公文的才能"}, {"w": "几筵", "t": "古代称祭席与灵座;筵席,几席"}, {"w": "几上肉", "t": "案上的肉,比喻任人宰割。"}]}, {"meaning": "苗头;预兆。", "cites": [{"t": "徒有疾恶心,奈何不知几。", "b": "唐·苏涣《变律》"}], "words": [{"w": "几先", "t": "预兆,事先。"}]}, {"meaning": "政务", "cites": [{"t": "或问为政有几。", "b": "《法言·先知》。注:“要也。”"}, {"t": "心缠几务,而虚述人外。", "b": "《文心雕龙·情采》"}]}, {"meaning": "表示非常接近,相当于“几乎”、“差不多”。", "cites": [{"t": "汉之为汉,几四十年矣。", "b": "汉·贾谊《论积贮疏》"}, {"t": "几死者数矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "几自刭死。(几,“几几乎”的省略写法)", "b": "宋·文天祥《指南录后序》"}, {"t": "几为巡徼所陵迫死。(通“凌”。)", "b": "宋·文天祥《指南录后序》"}, {"t": "几欲先走。", "b": "《虞初新志·秋声诗自序》"}, {"t": "磴几不可登。", "b": "清·姚鼐《登泰山记》"}, {"t": "几自疑身外即战场。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "有朕位几不保,命康与卿及同志速设法筹救之语。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "几有", "t": "几乎有;具有"}, {"w": "几首", "t": "方言。那边"}, {"w": "几虚", "t": "几乎徒然"}, {"w": "几几乎", "t": "几几。几乎,差不多。"}]}, {"meaning": "(会意。从戌。戌,兵守也。本义:细微,隐微)。"}, {"meaning": "同本义。", "cites": [{"t": "幾,微也,殆也。", "b": "《说文》"}, {"t": "几者,动之微,吉之先见者也。", "b": "《易·系辞》传"}, {"t": "一日二日万几。", "b": "《书·皋陶谟》"}, {"t": "事父母几谏。", "b": "《论语》"}, {"t": "君子见几而作,不俟终日。", "b": "《易·系辞》"}]}, {"meaning": "危险。", "cites": [{"t": "本不固者末必几。", "b": "《墨子》"}]}, {"meaning": "接近;达到。", "cites": [{"t": "几,近也。", "b": "《尔雅》"}, {"t": "月几望。", "b": "《易·小畜》"}, {"t": "知乐则几于礼矣。", "b": "《礼记·乐记》"}, {"t": "意几乎后言。", "b": "《庄子·天地》"}, {"t": "学之所以不能几于古者,作此之由乎?", "b": "清·刘开《问说》"}, {"t": "夫工艺非细事也,西人之神明规矩亦断非一蹴可几也。", "b": "清·郑应《盛世危言·技艺》"}]}]}, {"pinyin": "jǐ", "defs": [{"meaning": "(会意,本义:微,隐微)。"}, {"meaning": "表示肯定观念,意思是“虽少但仍有一些”。", "cites": [{"t": "几家深树里,一火夜渔归。", "b": "唐·项斯《江村夜归》"}, {"t": "见哥哥如此分析,以为理之当然,绝无几微不平的意思。", "b": "《醒世姻缘传》"}], "words": [{"w": "添几件衣服;给下一个人留下几朵花;几般儿", "t": "好几样,好几种;多么地;何等地"}, {"w": "几见", "t": "极少见到"}, {"w": "几微", "t": "一点;些微"}, {"w": "几回价", "t": "几回家。几次地,多次地。"}]}, {"meaning": "表示否定概念意思是“不多”“没有多少”。", "cites": [{"t": "韩子亦无几求。", "b": "《左传·昭十六年》。注:“言所求少。”"}], "words": [{"w": "所剩无几", "t": ""}]}, {"meaning": "表示疑问,用以询问数目的多少。", "cites": [{"t": "几为之笑而不陵我?", "b": "《左传·昭公十六年》"}, {"t": "子来几日矣?", "b": "《孟子·离娄上》"}, {"t": "崔九堂前几度闻。", "b": "唐·杜甫《江南逢李龟年》"}, {"t": "几处早莺争暖树。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "其几千里。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "读书者有几。", "b": "清·袁枚《黄生借书说》"}, {"t": "几世几年,剽掠其人。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "未几,敌兵果舁炮至。(未几,没有多久,一会儿。)", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "禽兽之变诈几何哉。(禽兽的欺骗手段能有多少啊。变诈作假,欺骗。几何,多少。)", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "几里路;几天;几何", "t": "多少;若干"}, {"w": "几化", "t": "方言。多少"}, {"w": "几多", "t": "多少"}, {"w": "几许", "t": "多少,若干"}, {"w": "几数", "t": "多少。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('15wx','九','1','jiǔ','丿','2','','[{"pinyin": "jiǔ", "defs": [{"meaning": "(指事。本义:数词。比八大一的基数)。"}, {"meaning": "同本义。", "cites": [{"t": "古人造字以纪数,起于一,极于九,皆指事也。二三四为积画,余皆变化其体。", "b": "朱骏声《说文通训定声》"}, {"t": "乾玄用九,乃见天则。", "b": "《易·文言》传"}, {"t": "九者,阳之数,道之纲纪也。", "b": "《楚辞·九辨》序"}, {"t": "天道以九制。", "b": "《管子·五行》"}], "words": [{"w": "九伯", "t": "宋时把痴傻人叫九伯。也写作“九百”"}, {"w": "小九九", "t": "珠算的乘法口诀;方言中比喻算计"}, {"w": "九九", "t": "算法名。称一至九每二数相乘之数为九九;九的自乘数"}, {"w": "九地", "t": "九种土地。"}]}, {"meaning": "第九。"}, {"meaning": "《周易》以阳爻为九。", "cites": [{"t": "初九,潜龙勿用。", "b": "《易·乾》"}]}, {"meaning": "泛指多数,数量大。", "cites": [{"t": "九设攻城之机变。", "b": "《墨子·公输》"}, {"t": "墨子九距之。", "b": ""}, {"t": "九令诸侯。", "b": "《史记·货殖列传》"}, {"t": "宏兹九德。", "b": "唐·魏征《魏郑公文集·谏太宗十思疏》"}]}, {"meaning": "时间长。", "cites": [{"t": "黄軦生乎九猷。", "b": "《庄子·至乐》。《释文》:九宜为久;久,老也。猷,虫名也。?"}, {"t": "食醯黄軦(kuàng黄軦,虫名)生乎九猷。", "b": "《列子·天瑞》"}]}, {"meaning": "九月。", "cites": [{"t": "七、八、九三个月", "b": ""}]}, {"meaning": "时令名。从冬至起每九天为一“九” 。如:今日进九;数九寒天;九尽寒尽。如:九九(自冬至次日起数,每九天为一九,共历八十一日,称为九九)。"}, {"meaning": "古国名 。今河北省临漳县西南。"}, {"meaning": "纠合,聚集。", "cites": [{"t": "九杂天下之川。", "b": "《庄子·天下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('16wx','刁','1','diāo','刀','2','','[{"pinyin": "diāo", "defs": [{"meaning": "乖巧,机灵。", "cites": [{"t": "这话实在刁的,说到我心里了。", "b": "《再生缘》"}]}, {"meaning": "[方言] 稻、麦、谷、高粱等抽的穗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('17wx','了','1','liǎo le','乛','2','','[{"pinyin": "liǎo", "defs": [{"meaning": "(象形。从子,无臂。小篆字象婴儿束其两臂形。初生的婴儿,往往束其两臂而裹之。本义:束婴儿两臂)。"}, {"meaning": "手弯曲。", "cites": [{"t": "了,尥也。从子无臂象形。", "b": "《说文》。按,犹交也。手之挛曰了,胫之絷曰尥。"}, {"t": "凡物二股或一股结纠紾缚不直伸者曰了戾。", "b": "段玉裁《说文解字注》"}], "words": [{"w": "了尥", "t": "手腿弯曲,引申指二物纠结绞缠不直伸的样子。"}]}, {"meaning": "假借为“憭”、“悟”。懂得,明白其意思。", "cites": [{"t": "嫌人不了。", "b": "《尔雅·释丘》注"}, {"t": "虽神气不变,而心了其故。", "b": "《世说新语》"}], "words": [{"w": "了法", "t": "领悟法理"}, {"w": "了得事", "t": "懂行"}, {"w": "了利", "t": "清楚,明白"}, {"w": "了然", "t": "明白,清楚。"}]}, {"meaning": "结束,了结。", "cites": [{"t": "小乔初嫁了。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "了还", "t": "了却,偿还"}, {"w": "了局", "t": "结局;结束"}, {"w": "了了", "t": "了结了"}, {"w": "了劣", "t": "了账;了结"}, {"w": "了休", "t": "终止,了结。"}]}, {"meaning": "聪敏,颖慧。", "cites": [{"t": "小而聪了,大未必奇。", "b": "《后汉书·孔融传》"}, {"t": "了,快也。秦曰了。", "b": "《方言二》"}], "words": [{"w": "了慧", "t": "聪明"}, {"w": "了干", "t": "精明干练。"}]}, {"meaning": "明亮,光亮。", "cites": [{"t": "收到一片秋香,清辉了如雪。", "b": "清·纳兰性德《琵琶仙》"}]}]}, {"pinyin": "le", "defs": [{"meaning": "用在动词或形容词后面，表示动作或变化已经完成。"}, {"meaning": "用在句子的末尾或句中停顿的地方，表示变化或出现新的情况。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('18wx','刀','1','dāo','刀','2','','[{"pinyin": "dāo", "defs": [{"meaning": "(象形。小篆字形,象刀形。汉字部首之一。本义:古代兵器名)。"}, {"meaning": "同本义。", "cites": [{"t": "刀,兵也。象形。", "b": "《说文》"}, {"t": "刀,到也,以斩伐到其所乃击之也。", "b": "《释名》"}, {"t": "刀光照塞月,阵色明如昼。", "b": "唐·崔国辅《从军行》"}], "words": [{"w": "刀枪;刀兵;刀瘢", "t": "刀伤的瘢痕。"}]}, {"meaning": "泛指用来斩、割、切、削、砍、铡的工具。", "cites": [{"t": "中刑用刀锯。", "b": "《国语·鲁语》"}, {"t": "有斧钺刀墨之民。", "b": "《国语·周语》"}, {"t": "帝自捉刀立床头。", "b": "《世说新语·容上》"}, {"t": "妻乃引刀趋机而言曰。", "b": "《后汉书·列女传》"}, {"t": "屠乃奔倚其下,弛担持刀。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "刀锯", "t": "古代的刑具。割刑用刀,刖刑用锯"}, {"w": "刀环", "t": "刀头的环"}, {"w": "刀墨", "t": "古黥刑。先用刀在额头上刻划,然后再染上墨"}, {"w": "刀斧手", "t": "刽子手;又指持刀拿斧、准备捉拿后杀人的军士。"}]}, {"meaning": "即刀币 ,中国的一种古钱币,其形如刀。", "cites": [{"t": "余刀布。", "b": "《荀子·荣辱》。注:“钱也。”"}, {"t": "及金刀龟贝。", "b": "《汉书·食货志》。注:“谓钱币也。利于刀”。注:“名钱为刀者,以其利于民也。”"}], "words": [{"w": "刀儿", "t": "古代钱币的通称。因其形状如刀,故有此称。"}]}, {"meaning": "小船。", "cites": [{"t": "谁谓河广?曾不容刀。", "b": "《诗·卫风·河广》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('19wx','力','1','lì','力','2','','[{"pinyin": "lì", "defs": [{"meaning": "(象形。甲骨文字形,象耒形,有柄有尖,用以翻地。用耒表示执耒耕作需要花费力气。“力”是汉字部首之一。本义:体力,力气)。"}, {"meaning": "同本义。", "cites": [{"t": "力,筋也。像人筋之形。", "b": "《说文》。筋下曰:肉之力也。二篆为转注。筋者其体,力者其用也。"}, {"t": "其行之以货力。", "b": "《礼记·礼运》。注:“筋骸强者也。”"}, {"t": "力农数耘。", "b": "《汉书·食货志》。注:“谓勤作之也。”"}, {"t": "有力如虎,执辔如组。", "b": "《诗·邶风》"}, {"t": "力足以至焉,于人为可讥,而在己为有悔。", "b": "宋·王安石《游褒禅山记》"}, {"t": "以缚背刃,力上下,得绝。", "b": "唐·柳宗元《童区寄传》"}, {"t": "吾力足以举百钧,而不足以举一羽。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "四肢无力", "t": ""}, {"w": "力人", "t": "力气很大的人"}, {"w": "力尽神危", "t": "力气精神都疲惫到极点"}, {"w": "力软筋麻", "t": "力尽筋疲。筋疲力尽"}, {"w": "力屈", "t": "力竭"}, {"w": "力尽", "t": "力气用尽"}, {"w": "力竭", "t": "力气用尽。"}]}, {"meaning": "力量。", "cites": [{"t": "战疾力。", "b": "《汉书·灌婴传》。注:“强力也。”"}, {"t": "愿将军量力而处之。", "b": "《资治通鉴》"}, {"t": "朽蠹不胜刀锯力,匠人虽巧欲何如?", "b": "韩愈《题木居士》"}, {"t": "盛夏力作。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "力劣", "t": "力量薄弱"}, {"w": "力薄", "t": "力量薄弱。"}]}, {"meaning": "能力。", "cites": [{"t": "欲为陛下所为者甚众,顾力不能耳。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "理解力", "t": ""}, {"w": "才力", "t": "才能;能力"}, {"w": "脑力", "t": "人的记忆、理解、想像等的能力"}, {"w": "力用", "t": "能力和作用"}, {"w": "力怯", "t": "力小胆怯。"}]}, {"meaning": "威力;权势。", "cites": [{"t": "以力服人者,非心服也。", "b": "《孟子》"}], "words": [{"w": "权力", "t": "政治上的强制力量"}, {"w": "暴力", "t": "强制力;武力"}, {"w": "力征", "t": "以武力征伐"}, {"w": "力正", "t": "以武力征伐"}, {"w": "力制", "t": "以权力统御、控制"}, {"w": "力攻", "t": "以武力攻伐"}, {"w": "力役", "t": "以武力征伐"}, {"w": "力政", "t": "以武力为政,暴政。"}]}, {"meaning": "劳役;仆役。", "cites": [{"t": "为力不同科,古之道也。", "b": "《论语》"}], "words": [{"w": "力役", "t": "劳役"}, {"w": "力征", "t": "力役之征。"}]}, {"meaning": "本指制法成治之功,后泛指功劳。", "cites": [{"t": "事功曰劳,治功曰力。", "b": "《周礼》"}, {"t": "拥佑太子,颇有力焉。", "b": "《汉书》"}]}, {"meaning": "兵士。", "cites": [{"t": "率见力决战。", "b": "《宋书·谢诲传》"}]}, {"meaning": "勤;致力,努力;从事于。", "cites": [{"t": "古训是式,威仪是力。", "b": "《诗·大雅·烝民》"}, {"t": "力周公正先天下。", "b": "《汉书·王莽传》。注:“勉力也。”"}, {"t": "郡中莫不耕稼力田。", "b": "《汉书·召信臣传》"}], "words": [{"w": "力农", "t": "从事于农业"}, {"w": "力田", "t": "致力耕种"}, {"w": "力耕", "t": "努力耕作"}, {"w": "力碌碌", "t": "匆忙的样子。"}]}, {"meaning": "役使。", "cites": [{"t": "视贱躯之可力,倾尽而为。", "b": "宋·叶适《湖南运判到任谢表》"}], "words": [{"w": "力役", "t": "强制老百姓从事的一种无偿劳动,是徭役的一种;服役;干体力活"}, {"w": "力伐", "t": "力攻顽敌;力攻智取"}, {"w": "极力指摘、驳斥", "t": ""}]}, {"meaning": "尽力,竭力。", "cites": [{"t": "楼船力攻烧敌。", "b": "《汉书·南粤王传》"}, {"t": "游子常贫苦,力子天所富。", "b": "《后汉书·樊晔传》"}, {"t": "力请客。", "b": "明·魏禧《大铁椎传》"}, {"t": "力主变法。", "b": "清·梁启超《谭嗣同传》"}, {"t": "力摧豪强。", "b": "清·张廷玉《明史》"}, {"t": "力叮不释。", "b": "《聊斋志异·促织》"}], "words": [{"w": "力正", "t": "尽力匡正"}, {"w": "力子", "t": "勤勉力行的人"}, {"w": "力田", "t": "致力农耕"}, {"w": "力疾", "t": "尽力支撑着病体"}, {"w": "力战", "t": "全力作战"}, {"w": "力邓", "t": "勉强,奋力"}, {"w": "力力碌碌", "t": "勤敏的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('20wx','乃','1','nǎi','丿','2','','[{"pinyin": "nǎi", "defs": [{"meaning": "你,你的。", "cites": [{"t": "余嘉乃勋。", "b": "《左传·僖公十二年》"}, {"t": "几败乃公事。", "b": "《汉书·高帝纪上》"}, {"t": "谁谓乃公勇者?", "b": "《史记·淮南衡山传》"}, {"t": "王师北定中原日,家祭无忘告乃翁(父亲)。", "b": "陆游《示儿》"}], "words": [{"w": "乃父", "t": "乃翁。你的父亲"}, {"w": "乃祖", "t": "你的祖父;先祖"}, {"w": "乃公", "t": "你的父亲"}, {"w": "乃兄", "t": ""}]}, {"meaning": "他的。", "cites": [{"t": "乃心在咸阳。", "b": "曹操《蒿里行》"}], "words": [{"w": "乃眷", "t": "他的妻子"}, {"w": "乃尊", "t": "尊称别人的父亲"}, {"w": "乃老", "t": "他的父亲"}, {"w": "乃堂", "t": "他的母亲。"}]}, {"meaning": "此,这个。", "cites": [{"t": "吾闻之,五子不满隅,一子可满朝,非乃子耶?", "b": "《晏子春秋》"}], "words": [{"w": "乃今", "t": "如今;从今"}, {"w": "乃者", "t": "往日;从前。"}]}, {"meaning": "这样,如此。", "cites": [{"t": "子无乃称。", "b": "《庄子·德充符》"}], "words": [{"w": "因山势高峻,乃在山腰休息片刻;乃尔", "t": "如此;这样"}, {"w": "乃若", "t": "至于。"}]}, {"meaning": "是,就是。", "cites": [{"t": "以其乃华山之阳名之。", "b": "宋·王安石《游褒禅山记》"}, {"t": "吾乃与而君言,汝何为者也?", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "真乃英雄好汉;失败乃成功之母;乃是", "t": "却是。"}]}, {"meaning": "刚刚,才,表示事情发生得晚或结束得晚。", "cites": [{"t": "九月…丁巳,葬我君定公,雨,不克葬,戊午日下昃乃克葬。", "b": "《春秋经·定公十五年》"}, {"t": "乃悟前狼假寐,盖以诱敌。", "b": "《聊斋志异·狼三则》"}]}, {"meaning": "竟,竟然。", "cites": [{"t": "今其智乃反不能及,其何怪也!", "b": "唐·韩愈《师说》"}]}, {"meaning": "却。", "cites": [{"t": "乃日视便利田宅可买者。(却每天寻找可买的合适的土地房屋。)", "b": "汉·刘向《列女传》"}]}, {"meaning": "于是;就。", "cites": [{"t": "屠乃奔倚其下。", "b": "《聊斋志异·狼三则》"}, {"t": "乃令张仪佯去秦,厚币委质事楚。", "b": "《史记·屈原贾生列传》"}, {"t": "婉贞挥刀奋斫…敌乃纷退。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "乃遂", "t": "就,于是"}, {"w": "乃其", "t": "于是,就。"}]}, {"meaning": "可是,然而。", "cites": [{"t": "时夫仆具阻险行后,余亦停弗上。乃一路奇景,不觉引余独往。", "b": "《徐霞客游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('21wx','又','1','yòu','又','2','','[{"pinyin": "yòu", "defs": [{"meaning": "(象形。甲骨文字形,象右手形,本左右的“右”。从“又”的字多与手的动作有关。本义:右手) 同本义 ", "cites": [{"t": "又,手也,象形。", "b": "《说文》。段玉裁注:“此即今之右字。”"}]}, {"meaning": "复,再,再一次。", "cites": [{"t": "敝予又改为兮。", "b": "《诗·郑风·缁衣》"}, {"t": "天命不又。", "b": "《诗·小雅·小宛》"}, {"t": "又命之。", "b": "《仪礼·燕礼》"}, {"t": "又试之鸡。", "b": "《聊斋志异·促织》"}], "words": [{"w": "读了又读", "t": ""}, {"w": "又是他", "t": ""}, {"w": "又问", "t": ""}, {"w": "又起个窖儿", "t": "比喻多费了一道手续"}, {"w": "又称", "t": ""}, {"w": "又说", "t": ""}]}, {"meaning": "表示几种情况或性质同时存在。", "cites": [{"t": "东出于陶邱北,又东至于荷,又东北会于汶,又北东入于海。", "b": "《书·禹贡》"}], "words": [{"w": "又打又闹", "t": ""}, {"w": "又惊又喜", "t": ""}, {"w": "又哭又笑", "t": ""}]}, {"meaning": "而且,表示意思上更进一层。", "cites": [{"t": "未可明诏大号…又不可以使天下之民斫直、删密、锄正。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "另外。", "cites": [{"t": "周处…为乡里所患…又义兴水中有蛟…", "b": "《世说新语·自新》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('22wx','三','1','sān','一','3','','[{"pinyin": "sān", "defs": [{"meaning": "(指事。本义:数目。二加一的和)。"}, {"meaning": "同本义。", "cites": [{"t": "三,天地人之道也。从三数。", "b": "《说文》"}, {"t": "三,数名。", "b": "《广韵》"}, {"t": "二与一为三。", "b": "《庄子·齐物论》"}, {"t": "一生二,二生三,三生万物。", "b": "《老子》"}, {"t": "王三赐命。", "b": "《易·师》。荀注:“三者阳德成也。”"}, {"t": "结恨三泉。", "b": "《后汉书·袁绍传》。注:“三者数之小终。”"}, {"t": "有不速之客三人来。", "b": "《易·需》"}, {"t": "纪之以三。", "b": "《国语·周语下》"}, {"t": "狡兔有三窟,仅得免其死耳。", "b": "《战国策》"}], "words": [{"w": "三叉", "t": "三歧的道路"}, {"w": "三木", "t": "古时套在犯人颈、手、足上的刑具"}, {"w": "三节", "t": "农历二月一日中和节、三月三上巳节、九月九日重阳节"}, {"w": "三学", "t": "太学、武学、宗学;或指府学、州学、县学"}, {"w": "三衙", "t": "三次,三回"}, {"w": "三巡", "t": "斟茶或酒三次"}, {"w": "三休", "t": "三顿"}, {"w": "三脚猫", "t": "比喻虚有其名而无真本事的人"}, {"w": "三班六房", "t": "明清时地方官署中吏役的总称"}, {"w": "三已", "t": "谓三度或多次罢官"}, {"w": "三五", "t": "谓十五天;十五岁。"}]}, {"meaning": "表示多数或多次。", "cites": [{"t": "鲁仲连辞让者三。", "b": "《战国策》"}, {"t": "卷我屋上三重茅。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "一篇之中三致志焉。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "三思台", "t": "胸膛或心脏"}, {"w": "三传", "t": "指多知古事,有才学的人"}, {"w": "三江", "t": "长江流经武汉地区附近的主流与支流等众多水道的总称"}, {"w": "三汲", "t": "多次取水"}, {"w": "三反", "t": "多次往返"}, {"w": "三辟", "t": "多次征召"}, {"w": "三回五次", "t": "多次"}, {"w": "三折", "t": "多次受挫"}, {"w": "三求四告", "t": "再三求告。"}]}, {"meaning": "指三颗星。", "cites": [{"t": "三星在天。", "b": "《诗·唐风·绸缪》"}], "words": [{"w": "三台星", "t": "星官名。共六星。两两相比,称上台、中台、下台。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('23wx','干','1','gān gàn','干','3','','[{"pinyin": "gān", "defs": [{"meaning": "(象形。甲骨文字形,象叉子一类的猎具、武器,本是用于进攻的,后来用于防御。本义:盾牌)。"}, {"meaning": "同本义。", "cites": [{"t": "盾,自关而东或谓之干。", "b": "《方言》九"}, {"t": "朱干玉戚以舞大武。", "b": "《礼记·祭统》。注:“朱干,赤盾。”"}, {"t": "司干。", "b": "《周礼·春官·序官》"}, {"t": "礼义以为干橹。", "b": "《礼记·儒行》。注:“干橹,小楯大楯也。”"}, {"t": "能执干戈以卫社稷。", "b": "《礼记·檀弓下》"}, {"t": "乃修教三年,执干戚舞,有苗乃服。", "b": "《韩非子·五蠹》"}], "words": [{"w": "干羽", "t": "盾牌和雉羽,供乐舞之用"}, {"w": "干革", "t": "干即盾;革即甲胄类。泛指兵器"}, {"w": "干橹", "t": "小盾大盾"}, {"w": "干戎", "t": "兵戎。通称兵器、军队。"}]}, {"meaning": "岸;水畔。", "cites": [{"t": "鸿渐于干。", "b": "《易·渐卦》。释文引郑注:“干,水傍,故停水处。”"}, {"t": "秩秩斯干。", "b": "《诗·小雅·斯干》。朱注:“干,水涯也。”"}, {"t": "昔者吴干战。", "b": "《管子·小问》。注:“干,江边地也。”"}, {"t": "而不知干队之败。", "b": "《史记·春申君传》。索隐:“干,水边也。”"}, {"t": "坎坎伐檀兮,置之河之干兮。", "b": "《诗·魏风·伐檀》"}]}, {"meaning": "江南把山垅之间的地段叫干。故金陵有大长干、小长干、东长干。"}, {"meaning": "捍卫。", "words": [{"w": "干害", "t": "捍护。"}]}, {"meaning": "触犯;冒犯;冲犯;冲。", "cites": [{"t": "干,犯也。", "b": "《说文》"}, {"t": "轍恐犯忌而干讳。", "b": "《楚辞·七谏·谬谏》"}, {"t": "以干先王之诛。", "b": "《书·胤征》"}, {"t": "以干天祸。", "b": "《公羊传·宣公十二年》"}, {"t": "若干二命以求杀予。", "b": "《国语·晋语四》"}]}, {"meaning": "又。", "cites": [{"t": "则上下不干。", "b": ""}, {"t": "乃背晋干宋。", "b": "《史记·管蔡世家》"}, {"t": "赵孟使人以其乘车干行,献子执而戮之。", "b": "《国语·晋语五》"}, {"t": "干国之纪。", "b": "《左传·襄公二十三年》"}, {"t": "君辱贶之,其敢干大礼以自取戾。", "b": "《左传·文公四年》"}, {"t": "故吏不敢以非法遇(对待)民,民不敢犯法干法官也。", "b": "《商君书·定分》"}, {"t": "牵衣顿足拦道哭,哭声直上干云霄。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "干渎", "t": "冒犯。干:干犯;抵触;烦扰"}, {"w": "干触", "t": "冒犯;触犯"}, {"w": "干凌", "t": "干犯欺凌"}, {"w": "干典", "t": "违犯法典"}, {"w": "干命", "t": "违犯命令"}, {"w": "干行", "t": "指冲撞军列"}, {"w": "干戾", "t": "触犯法令而获罪。"}]}, {"meaning": "立,建立。", "cites": [{"t": "后知张顺干了功劳。", "b": "《水浒传》"}]}, {"meaning": "求,求取。", "cites": [{"t": "皆干赏蹈利之兵也。", "b": "《荀子·议兵》"}, {"t": "其欲干酒肉之味邪?", "b": "《庄子·徐无鬼》"}, {"t": "亦不敢服垢弊以矫俗干名,但顺吾性而已。", "b": "宋·司马光《训俭示康》"}, {"t": "时墨者东郭先生将北适中山以干仕。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "干名", "t": "求取名位"}, {"w": "干求", "t": "求取功名"}, {"w": "干谒", "t": "为谋求禄位而谒见当权者"}, {"w": "干进", "t": "营谋官职地位"}, {"w": "干索", "t": "索要;强取"}, {"w": "干进", "t": "谋求仕进"}, {"w": "干请", "t": "请托。"}]}, {"meaning": "干预;干扰。", "cites": [{"t": "皆妇人干政之所致也。", "b": "《后汉书·蔡邕传》"}, {"t": "明君使事不相干。", "b": "《韩非子·用人》"}]}, {"meaning": "关涉;牵扯。", "cites": [{"t": "新来瘦,非干病酒,不是悲秋。", "b": "宋·李清照《凤凰台上忆吹箫》"}], "words": [{"w": "干己", "t": "关系,责任"}, {"w": "干累", "t": "连累;牵连"}, {"w": "干纪", "t": "关系;职责"}, {"w": "干属", "t": "关系"}, {"w": "干惹", "t": "牵涉,关连。"}]}, {"meaning": "(形声。从乙(表示向上),倝(gàn)声。①本义:天。②引申义:没有水分或水分很少,与“湿”相对)。"}, {"meaning": "同引申义。", "cites": [{"t": "方将被发而干。", "b": "《庄子·田子方》"}, {"t": "剖其中,干若败絮。", "b": "刘基《卖柑者言》"}, {"t": "干东土。", "b": "《吕氏春秋·爱类》"}, {"t": "外强中干。", "b": "《左传·僖公十五年》"}, {"t": "然而旱干水溢。", "b": "《孟子·尽心下》"}, {"t": "床头屋漏无干处,雨脚如麻未断绝。", "b": "唐·杜甫《茅屋为秋风所破歌》诗"}], "words": [{"w": "干冬", "t": "干燥少雨的冬季"}, {"w": "干荒", "t": "干旱"}, {"w": "干烘茶", "t": "采摘后不经过揉制而直接烘干的茶叶"}, {"w": "干堆", "t": "干柴堆。比喻色迷之人。"}]}, {"meaning": "枯竭。", "cites": [{"t": "予贸得其一,剖之,如有烟扑口鼻,视其中,则干若败絮。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "干蛋", "t": "方言。穷光蛋"}, {"w": "干竭", "t": "枯竭。"}]}, {"meaning": "干亲。谓没有血缘或婚姻关系而结认的亲戚关系。", "cites": [{"t": "赵氏干娘,高皇(明太祖朱元璋)义父之妻也。", "b": "明·文林《琅琊漫抄》"}], "words": [{"w": "干爷", "t": "义父"}, {"w": "干大", "t": "方言。干爹,义父"}, {"w": "干老子", "t": "干爹"}, {"w": "干生子", "t": "干儿子"}, {"w": "干达达", "t": "干爹,义父。"}]}, {"meaning": "使干,竭尽。", "cites": [{"t": "干泽而渔。", "b": "刘向《说苑》"}]}, {"meaning": "怠慢;使对方难堪。", "cites": [{"t": "从今日起,且干着他,不理他,他两个自然有些着慌。", "b": "《儿女英雄传》"}]}, {"meaning": "又。", "cites": [{"t": "没奈何,站起身来干了人家,一句说了六个大字,道是:“多礼,我不敢当。”", "b": ""}]}, {"meaning": "加工制成的干食品。", "cites": [{"t": "人负朱六斗,卒自携五日干粮。", "b": "宋·沈括《梦溪笔谈·官政》"}], "words": [{"w": "豆腐干", "t": ""}, {"w": "萝卜干", "t": ""}, {"w": "干肉", "t": ""}, {"w": "干脯", "t": "干肉。"}]}, {"meaning": "徒然,白白地。", "cites": [{"t": "干愁漫解坐自累,与众异趣谁相亲。", "b": "唐·韩愈《感春》"}], "words": [{"w": "干落落", "t": "白白地"}, {"w": "干发虚", "t": "空有打算而不能兑现"}, {"w": "干拌", "t": "白吵;白费口舌"}, {"w": "干白", "t": "白说,白搭。"}]}, {"meaning": "虚假地,表面地。", "cites": [{"t": "晔干笑云:“罪至”而已。", "b": "《宋书·范晔传》"}], "words": [{"w": "干乔", "t": "装模作样。"}]}, {"meaning": "姓。"}]}, {"pinyin": "gàn", "defs": [{"meaning": "(形声。从木,倝(gàn)声。本义:筑墙板。筑土墙时两边所用的木板)。"}, {"meaning": "同本义。", "cites": [{"t": "榦,筑墙端木也。", "b": "《说文》。字亦俗作幹。按,植于两边者曰榦,植于两端者曰楨。散文则亦通称也。古筑墙先度其广,轮乃树楨,榦,继施横板于两边,榦内以绳束榦,实土筑之。一板竣则层累而上,五板为堵。"}, {"t": "平板榦,称畚筑。", "b": "《左传·宣公十一年》"}, {"t": "姚信、楼玄,…皆社稷之桢干,国家之良辅。", "b": "《三国志·陆凯传》"}], "words": [{"w": "榦楨", "t": "筑墙所用的主柱,竖在两旁的叫“榦”,竖在两端的叫“桢”。引申为支柱、支撑。"}]}, {"meaning": "木名。柘树。"}, {"meaning": "主干。", "cites": [{"t": "故枝不得大如榦,末不得强于本。", "b": "《淮南子·主训》"}, {"t": "柏虽大榦如臂,无不平贴石上,如苔藓然。", "b": "《徐霞客游记》"}, {"t": "魂兮归来,去君之恒干,何为四方些?", "b": "《楚辞·屈原·招魂》"}], "words": [{"w": "躯干", "t": ""}, {"w": "干子", "t": "树干"}, {"w": "干本", "t": "树木的主干"}, {"w": "干貌", "t": "体貌"}, {"w": "干力", "t": "指体力强健"}, {"w": "骨干", "t": "在总体中起主要作用的人或物"}, {"w": "干翮", "t": "主翮。翮,羽的主茎"}, {"w": "干翼", "t": "主干与辅翼"}, {"w": "干辅", "t": "主干与辅佐。"}]}, {"meaning": "引申为本质。", "cites": [{"t": "是故柔弱者,生之榦也。", "b": "《淮南子》。高诱注:“榦,质也。”"}]}, {"meaning": "胁。", "cites": [{"t": "上佐食,举尸牢胁,尸受振祭哜之。", "b": "《仪礼·少牢馈食礼》"}]}, {"meaning": "效果;用处。", "cites": [{"t": "况且朱三是穷人,讨也没干。", "b": "《二刻拍案惊奇》"}]}, {"meaning": "地位低下的官吏。", "words": [{"w": "干人", "t": "即府干。达官贵人府中的办事人员。也称“干办”"}, {"w": "干吏", "t": "干练的官吏。多指州郡衙门中的办事人员。"}]}, {"meaning": "做,从事于或忙于做某事,尤指从事某项职业。", "cites": [{"t": "宁宗庆元五年,右谏议大夫张奎言乞行下州县,保正止许干当本都贼盗、斗殴、烟火、公事,不许非泛科配。", "b": "《文献通考·职役·历代乡党版籍职役》"}], "words": [{"w": "干不的", "t": "干不了"}, {"w": "干办", "t": "办理;处理"}, {"w": "干当", "t": "承办。"}]}, {"meaning": "主管。", "cites": [{"t": "光武即位,知湛名儒旧臣,欲令干任内职,征拜尚书。", "b": "《后汉书·伏湛传》"}], "words": [{"w": "干管", "t": "主持;管理"}, {"w": "干官", "t": "古代掌管均输之官"}, {"w": "干掌", "t": "掌管,管理"}, {"w": "干运", "t": "运筹干办"}, {"w": "干当", "t": "主管;经办。"}]}, {"meaning": "护卫,遮挡。", "cites": [{"t": "赳赳武夫,公侯干城。", "b": "《诗·周南·兔罝》"}], "words": [{"w": "干夜", "t": "护卫巡夜。"}]}, {"meaning": "干练。", "cites": [{"t": "邕善书计,强记默识,以干济见知。", "b": "《北齐书·唐邕传》"}, {"t": "愿他日得志,廉干如古人某,忠孝如古人某,及为吏,以污贿不饬罢。", "b": "清·周容《芋老人传》"}], "words": [{"w": "干肃", "t": "干练而慎重"}, {"w": "干直", "t": "干练正直"}, {"w": "干绩", "t": "优异的业绩"}, {"w": "干誉", "t": "以办事干练而获得的声誉。"}]}, {"meaning": "乱。", "cites": [{"t": "治宜于时而行之,则不干。", "b": "《商君书·壹言》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('24wx','于','1','yú','二','3','','[{"pinyin": "yú", "defs": [{"meaning": "(象形。甲骨文字形,表示气出受阻而仍越过。本义:超过)。"}, {"meaning": "往;去。", "cites": [{"t": "之子于归,宜其室家。", "b": "《诗·周南·桃夭》。毛传:“于,往也。”"}, {"t": "予惟以尔庶邦于伐殷,逋播臣。", "b": "《书·大诰》"}]}, {"meaning": "取。", "cites": [{"t": "昼尔于茅,宵尔索陶。", "b": "《诗·豳风·七月》"}]}, {"meaning": "如;好像。", "cites": [{"t": "《易》曰:“介于石,不终日,贞吉。”介如石焉,宁用终日,断可识矣。", "b": "《易·系辞下》"}], "words": [{"w": "于何", "t": "如何。"}]}, {"meaning": "引进动作、行为的时间、处所,意义相当于“在”、“到”或“在…方面(上、中)”。", "cites": [{"t": "捐金于野。", "b": "《后汉书·列女传》"}, {"t": "成于机杼。", "b": ""}, {"t": "射于家圃。", "b": "宋·欧阳修《归田录》"}, {"t": "葫芦置于地。", "b": ""}, {"t": "力足以至焉,于人为可讥,而在己为有悔。", "b": "宋·王安石《游褒禅山记》"}, {"t": "于时冰皮始解,波色乍明。", "b": "明·袁宏道《满井游记》"}, {"t": "越长城之限,至于泰安。(于:介词,到。)", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "于以", "t": "在何处"}, {"w": "于兹", "t": "在此"}, {"w": "于时", "t": "在此。"}]}, {"meaning": "引进动作、行为的对象,相当于“向”、“对”、“对于”。", "cites": [{"t": "告之于帝。", "b": "《列子·汤问》"}, {"t": "何有于我。", "b": "《论语》"}, {"t": "于其身也,则耻师焉,惑矣。", "b": "唐·韩愈《师说》"}, {"t": "言于李愬。", "b": "《资治通鉴·唐纪》"}, {"t": "语于富者。", "b": "清·彭端淑《为学一首示子侄》"}]}, {"meaning": "在被动句中,引进动作、行为的主动者,相当于“被”。", "cites": [{"t": "不拘于时。", "b": "唐·韩愈《师说》"}, {"t": "苦于多疾。", "b": "宋·苏轼《教战守》"}, {"t": "伤于缚者。", "b": "清·方苞《狱中杂记》"}, {"t": "择于自然。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "引进比较对象,意思相当于“比”。", "cites": [{"t": "甚于妇人。", "b": "《战国策·赵策》"}, {"t": "毛先生以三寸之舌,强于百万之师。", "b": "《史记·平原君虞卿列传》"}, {"t": "同于真。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "同于幻。", "b": ""}, {"t": "近于自然。", "b": "蔡元培《图画》"}]}, {"meaning": "词缀。嵌在动词或形容词后面,不必译出。", "cites": [{"t": "以至于寸。", "b": "《后汉书·列女传》"}, {"t": "越于诸侯。", "b": "《国语·晋语》"}, {"t": "以免于难。", "b": ""}, {"t": "可以免于难。", "b": ""}]}, {"meaning": ""}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('25wx','亏','1','kuī','二','3','','[{"pinyin": "kuī", "defs": [{"meaning": "(形声。从亏,(hū)声。本义:气损)。"}, {"meaning": "同本义。", "cites": [{"t": "亏,气损也。", "b": "《说文》。段注:“引申凡损皆曰亏。”"}], "words": [{"w": "亏柔", "t": "犹虚弱"}, {"w": "亏退", "t": "衰退止息。"}]}, {"meaning": "欠缺,短少(应该有的而缺少)。与“盈”、“满”相对。", "cites": [{"t": "虽监门之服养不亏于此。", "b": "《韩非子·五蠹》"}, {"t": "为山九仞,巧亏一篑。", "b": "《书·旅獒》"}, {"t": "日极则仄,月满则亏。", "b": "《管子·白心》"}], "words": [{"w": "亏失", "t": "缺失"}, {"w": "亏欠", "t": "欠了人情"}, {"w": "亏累", "t": "债务;亏损"}, {"w": "亏紊", "t": "亏缺紊乱"}, {"w": "亏替", "t": "亏缺衰败。"}]}, {"meaning": "损耗,损害。", "cites": [{"t": "贿秦而力亏。", "b": "宋·苏洵《权书·六国论》"}], "words": [{"w": "亏缺", "t": "亏空"}, {"w": "亏污", "t": "亏损沾污"}, {"w": "亏误", "t": "失误"}, {"w": "亏输", "t": "失败;损失。"}]}, {"meaning": "输。", "cites": [{"t": "请与对弈,互有盈亏。", "b": "《聊斋志异》"}]}, {"meaning": "毁坏。", "cites": [{"t": "不亏不崩。", "b": "《诗·鲁颂·閟宫》"}], "words": [{"w": "亏污", "t": "亏损污染"}, {"w": "亏害", "t": "损害"}, {"w": "亏损", "t": "亏待,损害"}, {"w": "亏图", "t": "图谋损害"}, {"w": "亏名", "t": "损害名誉。"}]}, {"meaning": "减损;减少。", "cites": [{"t": "厚者亏之,薄者靡之。", "b": "《韩非子·扬权》"}], "words": [{"w": "亏成", "t": "缺损与完满;失败与成功"}, {"w": "亏全", "t": "缺损与完满。"}]}, {"meaning": "违背。", "cites": [{"t": "有善於前,有过於后,不为亏法。", "b": "《商君书·赏刑》"}], "words": [{"w": "亏负", "t": "亏待;做对不起他人的事"}, {"w": "亏心事", "t": "违背良心的事;问心有愧的事"}, {"w": "亏制", "t": "违制。放宽法度。"}]}, {"meaning": "相异;不适应。", "cites": [{"t": "其时已与先王之法亏矣。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "损失,丧失。", "cites": [{"t": "恩爱苟不亏,在远分日亲。", "b": "曹植《赠白马王彪》"}], "words": [{"w": "吃亏;使出版家受亏;自负盈亏", "t": ""}]}, {"meaning": "月相从全月到新月的时期。", "cites": [{"t": "天道亏盈。", "b": "《易·谦》"}], "words": [{"w": "亏盈", "t": "亏缺或盈满"}, {"w": "月满则亏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('26wx','工','1','gōng','工','3','','[{"pinyin": "gōng", "defs": [{"meaning": "(象形。甲骨文字形,象工具形。“工”、“巨”(矩)古同字,有“规矩”,即持有工具。本义:工匠的曲尺)。"}, {"meaning": "同本义。", "cites": [{"t": "工,巧饰也,象人有规榘也。", "b": "《说文》"}, {"t": "许君谓工象人有规榘,说颇难通,以巧饰训工,殆非朔义。以愚观之,工盖器物之名也。知者:《工部》巨下云:“规巨也,从工,象手持之。”按:工为器物,故人能以手持之,若工第为巧饰,安能手持乎…以字形考之,工象曲尺之形,盖即曲尺也。", "b": "杨树达《积微居小学述林》"}]}, {"meaning": "工匠;工人。古代对从事各种技艺的劳动者的总称;现代为工人和工人阶级的总称。", "cites": [{"t": "凡攻木之工七。", "b": "《考工记·总目》"}, {"t": "五日工事之式。", "b": "《周礼·天官·大宰》"}, {"t": "百工居肆以成其事。", "b": "《论语·子张》"}, {"t": "工欲善其事,必先利其器。", "b": "《论语·卫灵公》"}, {"t": "巫医乐师百工之人,不耻相师。", "b": "唐·韩愈《师说》"}, {"t": "得赵人徐夫人之匕首,取之百金,使工以药淬之。", "b": "《战国策·赵策》"}], "words": [{"w": "矿工", "t": ""}, {"w": "临时工", "t": ""}, {"w": "工农联盟", "t": ""}, {"w": "工民", "t": "古代从事工艺的人。"}]}, {"meaning": "古代特指乐官或乐人。", "cites": [{"t": "乐工罗程者,善弹琵琶,为第一,能变易新声。…他工辈以程艺天下无双,欲以动上意。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "工师", "t": "乐师"}, {"w": "工瞽", "t": "古代乐官。"}]}, {"meaning": "官吏;职事。", "cites": [{"t": "论百工,审时事,辨功苦,尚完剩,便备用,使雕琢文来不敢专造于家,工师之事也。", "b": "《荀子·王制》"}], "words": [{"w": "工部大堂", "t": "工部尚书。大堂:明清时对中央各院、部、司长官的恭维称谓"}, {"w": "工正", "t": "古官名。主管工艺之事"}, {"w": "工师", "t": "古代官名。掌管百工"}, {"w": "工官", "t": "周礼官名。属冬宫。汉代时负责工艺、器械、武器制造等"}, {"w": "工尹", "t": "官名。掌管百工及官营手工业。"}]}, {"meaning": "劳绩,功绩。", "cites": [{"t": "凡师不工则助牵王车。", "b": "《周礼·春官》"}], "words": [{"w": "天工", "t": "很大的功劳。"}]}, {"meaning": "成效。", "cites": [{"t": "此言多资之易为工也。", "b": "《韩非子·五蠹》"}]}, {"meaning": "精巧,精致。", "cites": [{"t": "子云相如,同工异曲。", "b": "韩愈《进学解》"}, {"t": "此非兵力之精,非计之工也。", "b": "《战国策·魏策》"}, {"t": "耻其技之不若,而去数千里,为卒三年,倘三年犹不得,既犹不归尔。其志如此,技之工又须问邪?", "b": "明·侯方域《马伶传》"}, {"t": "纵豆蔻词工,青楼梦好,难赋深情。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": " 工奇", "t": "精巧奇特"}, {"w": "工捷", "t": "精熟敏捷"}, {"w": "工楷", "t": "工整的楷书"}, {"w": "工绮", "t": "精致华丽。"}]}, {"meaning": "擅长;善于。", "cites": [{"t": "工文学者非所用。", "b": "《韩非子·五蠹》"}, {"t": "新人工织缣,故人工织素。", "b": "《乐府诗集·上山采蘼芜》"}, {"t": "宋,怀庆青华镇人,工技击。", "b": "明·魏禧《大铁椎传》"}, {"t": "善画者多工书而能诗。", "b": "蔡元培《图画》"}], "words": [{"w": "工于心计", "t": ""}, {"w": "工于书画", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('27wx','土','1','tǔ','土','3','','[{"pinyin": "tǔ", "defs": [{"meaning": "(象形。甲骨文字形,上象土块,下象地面。金文中空廓变填实,小篆又变为线条。本义:泥土,土壤)。"}, {"meaning": "同本义。沉积于地面上的泥沙混合物。潮湿时称泥土,地质学上称土壤。", "cites": [{"t": "土,地之吐生物者也。", "b": "《说文》"}, {"t": "百谷草木丽乎土。", "b": "《易·彖传》"}, {"t": "禹敷土。", "b": "《书·禹贡》"}, {"t": "辨十有二土之名物。", "b": "《周礼·大司徒》"}, {"t": "君之视臣为土芥,则臣视君如寇仇。", "b": "《孟子·离娄》"}, {"t": "焉置土石。", "b": "《列子·汤问》"}, {"t": "不若燔土。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "土膏微润。", "b": "明·袁宏道《满井游记》"}]}, {"meaning": "土地。", "cites": [{"t": "甘食其土之有。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "土工", "t": "从事挖土埋人工作的人"}, {"w": "土宇", "t": "土地住宅"}, {"w": "土田", "t": "土地田畴"}, {"w": "土功", "t": "治水土的工程"}, {"w": "土作", "t": "土木工程"}, {"w": "土薄", "t": "土地硗薄"}, {"w": "土公", "t": "土地神。"}]}, {"meaning": "领土,国土。", "cites": [{"t": "天府之土。", "b": "《三国志·诸葛亮传》"}, {"t": "北土禾平。", "b": "《资治通鉴》"}, {"t": "能守其土。", "b": "宋·苏洵《六国论》"}, {"t": "守土吏或降。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "土疆", "t": "领土"}, {"w": "土境", "t": "领土,国土。"}]}, {"meaning": "田。", "cites": [{"t": "土,田也。", "b": "《尔雅》。郝懿行义疏:土为田之大名,田为已耕之土。对文则别,散则通也。"}]}, {"meaning": "中医学上指脾。", "cites": [{"t": "不想春气渐深,肝木克了脾土,每日只吃两碗米汤,卧床不起。", "b": "《儒林外史》"}]}, {"meaning": "土地神", "cites": [{"t": "天子祭天,诸侯祭土。", "b": "《公羊传·僖公三十一年》"}]}, {"meaning": "中国少数民族之一 。自称“蒙古勒”或“蒙古尔孔”(意为蒙古人),分布在青海省及甘肃天祝等地。"}, {"meaning": "测量土地。", "cites": [{"t": "凡建邦国,以土圭土其地,而制其域。", "b": "《周礼·地宫·大司徒》"}, {"t": "土圭尺有五寸,以致日,以土地。", "b": "《周礼·考工记·玉人》。郑玄注:土,犹度也。"}, {"t": "不土其地,不分其民,明正也。", "b": "《谷梁传·僖公四年》"}]}, {"meaning": "吐。", "cites": [{"t": "土,泻也。", "b": "《广雅》。王念孙疏证:土之为言吐也。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('28wx','士','1','shì','士','3','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。从一,从十。善于做事情,从一开始,到十结束。本义:古代男子的美称)。"}, {"meaning": "同本义。", "cites": [{"t": "士,事也。", "b": "《说文》"}, {"t": "通古今,辩然不,谓之士。", "b": "《白虎通·爵》"}, {"t": "学以居位曰士。", "b": "《汉书·食货志》"}, {"t": "以才智用者谓之士。", "b": "《后汉书·仲长统传》"}, {"t": "太子晋,胄成人,能治上官,谓之士。", "b": "《周书》"}, {"t": "是以为大夫卿士。", "b": "《书·牧誓》"}, {"t": "列国之大夫,入天子之国,曰某士。", "b": "《礼记·曲礼》"}, {"t": "其士女之问桃叶渡游雨花台者,趾相错也。", "b": "《马伶传》"}, {"t": "尝试语于众曰:“某良士,某良士。”其应者必其人之与也。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "士子", "t": "男子的美称,多指年轻人;士大夫官僚阶层"}, {"w": "士夫", "t": "青年男子"}, {"w": "勇士;壮士;士三日不见,当刮目相待", "t": "男儿相别三天,就应另眼相看,极言进步之速。"}]}, {"meaning": "将领。", "cites": [{"t": "危士臣,构怨于诸侯,然后快于心与?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "士臣", "t": "将士。"}]}, {"meaning": "兵士;武士。", "cites": [{"t": "下军之士多从之。", "b": "《左传·宣公十二年》"}, {"t": "在车曰士,步曰卒。", "b": "《吕氏春秋·简选》注"}, {"t": "驱中国士众这涉江湖之间,不习水土,必生疾病。", "b": "《资治通鉴》"}, {"t": "士不敢弯弓而报怨。", "b": "汉·贾谊《过秦论上》"}, {"t": "旌蔽日兮敌若云,矢交坠兮士争先。", "b": "《楚辞·国殇》"}, {"t": "革车百乘,甲士千人。", "b": "《左传·成元年·三月作丘甲·注》"}], "words": [{"w": "士兵;士众", "t": "众士兵"}, {"w": "上士;中士;下士", "t": ""}]}, {"meaning": "古代指掌管刑狱的官员。", "cites": [{"t": "其附于刑者,归于士。", "b": "《周礼·大司徒》"}, {"t": "管夷吾举于士,孙叔敖举于海。", "b": "《孟子·告子下》"}]}, {"meaning": "士大夫(旧时指官吏或较有声望、地位的知识分子)。", "cites": [{"t": "缙绅大夫士萃于左丞相府,莫知计所出。", "b": "宋·文天祥《指南录后序》"}, {"t": "臧使者枉用三尺以仇一言之憾,固贼戾之士哉!", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "士夫", "t": "士大夫"}, {"w": "士田", "t": "古代卿、大夫、士及其子弟所领有的田地"}, {"w": "士民", "t": "古代四民之一。泛指士大夫阶层和普通读书人"}, {"w": "士行", "t": "士大夫的操行"}, {"w": "士论", "t": "士大夫的舆论、评论。"}]}, {"meaning": "中国古代社会阶层的名称。"}, {"meaning": "先秦时期贵族的最低等级,位次于大夫。", "cites": [{"t": "荆州与国相邻接,江山险固,沃野万里,士民殷富。", "b": "《资治通鉴》"}, {"t": "于是六国之士,有宁越、徐尚、苏秦、杜赫之属为之谋。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "士庶", "t": "贵族和平民。"}]}, {"meaning": "古代四民之一。指农工商以外学道艺、习武勇的人。或称“士民”以区别于“庶民”。", "cites": [{"t": "此庸夫之怒也,非士之怒也。", "b": "《战国策·魏策》"}]}, {"meaning": "知识分子的通称。", "cites": [{"t": "孙讨虏聪明仁惠,敬贤礼士,江表英豪,咸归附之。", "b": "《资治通鉴》"}, {"t": "吾社之行为士先者,为之声义。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "士子", "t": "对读书人的通称"}, {"w": "士林", "t": "学术界;知识界"}, {"w": "士品", "t": "读书人的品行"}, {"w": "士风日漓", "t": "读书的风气一天天淡薄了"}, {"w": "士流、名士;士农工商", "t": ""}]}, {"meaning": "古代诸侯士大夫对天子的自称。", "cites": [{"t": "列国之大夫入天子之国,曰某士。", "b": "《礼记》"}]}, {"meaning": "对品德好、有学识、有技艺的人的美称。", "cites": [{"t": "公子为人,仁而下士,士无贤不肖,皆谦而礼交之。", "b": "《史记·魏公子列传》"}, {"t": "风萧萧兮易水寒,壮士一去兮不复还。", "b": "《战国策·燕策》"}, {"t": "凡四方之士无有不过而拜且泣者,斯固百世之遏也。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "又如志士、勇士、谋士、医士。"}, {"meaning": "作官", "cites": [{"t": "以宅田士田贾田任近郊之地。", "b": "《周礼·地官·载师》"}, {"t": "古者匹夫五十而士。", "b": "《荀子·大略》"}, {"t": "夫不以其道进者,必不以其道士。", "b": "《风俗通义·穷通》"}, {"t": "重争士橐,非下也,权重也。", "b": "《韩非子·五蠹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('29wx','才','1','cái','扌','3','','[{"pinyin": "cái", "defs": [{"meaning": "(象形。甲骨文字形,上面一横表示土地,下面象草木的茎(嫩芽)刚刚出土,其枝叶尚未出土的样子。本义:草木初生)。"}, {"meaning": "同本义。", "cites": [{"t": "才,草木之初也。", "b": "《说文》"}]}, {"meaning": "有才能;有本领。", "cites": [{"t": "试使斗而才。", "b": "《聊斋志异·促织》"}], "words": [{"w": "才郎", "t": "有才学的郎君"}, {"w": "才哲", "t": "才智卓越的人"}, {"w": "才雄", "t": "杰出的人才"}, {"w": "才英", "t": "指才华杰出的文人"}, {"w": "才杰", "t": "杰出的人才。"}]}, {"meaning": "才力;才能。", "cites": [{"t": "任人之才。", "b": "《淮南子·主术》"}, {"t": "虽才高于世,而无骄尚之情。", "b": "《后汉书·张衡传》"}, {"t": "况刘豫州王室之胄,英才盖世。", "b": "《资治通鉴》"}], "words": [{"w": "才伐", "t": "才力门望"}, {"w": "才格", "t": "才能。一说指才能高低的程度"}, {"w": "才望", "t": "才能与名望"}, {"w": "才理", "t": "才力和思路"}, {"w": "才笔", "t": "写作的才华"}, {"w": "才义", "t": "才思和义理。"}]}, {"meaning": "人才。常写作“材”。", "cites": [{"t": "乐里多才。", "b": "《列子·仲尼》"}, {"t": "举贤才。", "b": "《论语》"}, {"t": "救时应仗出群才。", "b": "清·秋瑾《黄海舟中》"}], "words": [{"w": "唯才是举", "t": ""}, {"w": "干才", "t": ""}, {"w": "广开才路", "t": ""}, {"w": "栋梁之才", "t": ""}, {"w": "廊庙之才", "t": ""}]}, {"meaning": "从才能方面指某类人。", "cites": [{"t": "夫管子,天下之才也。", "b": "《国语·齐语》"}], "words": [{"w": "奴才", "t": ""}, {"w": "蠢才", "t": ""}, {"w": "天才", "t": ""}, {"w": "人才", "t": ""}]}, {"meaning": "材资;本能。", "cites": [{"t": "非天之降才尔殊也。", "b": "《孟子·告子上》"}, {"t": "才能不及中人。", "b": "《史记·李将军列传》"}, {"t": "西门豹治邺,民不敢欺,三子之才能,谁最贤哉?", "b": "《史记·滑稽列传》"}, {"t": "五才之用,无或可废。", "b": "《后汉书·马融传》"}, {"t": "木有用叫做“材”,物有用叫做“财”,人有用叫做“才”。故“材”、“财”、“才”三字同源。", "b": "王力《同源字典》"}, {"t": "当今乏才,以尔为柱石之用,莫倾人栋梁。", "b": "《世说新语·规箴》"}]}, {"meaning": "刚刚。", "cites": [{"t": "才数月耳。", "b": "《汉书·贾才传》"}, {"t": "远县才至,则胡又已去。", "b": "《汉书·晁错传》"}, {"t": "此印者才毕,则第二板已具。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "刚才", "t": "刚要,刚刚"}, {"w": "方才", "t": "才,刚刚。"}]}, {"meaning": "仅,只 ——表示数量少,程度低。", "cites": [{"t": "初极狭,才通人。", "b": "晋·陶渊明《桃花源记》"}, {"t": "浅草才能没马蹄。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "才属", "t": "仅能连续。"}]}, {"meaning": "表示只有在某种条件下或由于某种原因、目的而能怎么样。用于后一分句,前一小句常有“只有、必须、要、因为、由于”等词语。", "cites": [{"t": "惟正月才生魄。", "b": "《晋书·夏侯湛传昆弟诰》"}, {"t": "才小富贵,便豫人家事。", "b": "《晋书·谢混传》"}]}, {"meaning": "强调确定语气。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('30wx','下','1','xià','一','3','','[{"pinyin": "xià", "defs": [{"meaning": "(指事。据甲骨文,上面部分表示位置的界限,下面部分表示在下的意思。本义:下面,位置在下)。"}, {"meaning": "同本义。", "cites": [{"t": "下,底也。", "b": "《说文》"}, {"t": "在南山之下。", "b": "《诗·召南·殷其靁》"}, {"t": "十月蟋蟀入我床下。", "b": "《诗·豳风·七月》"}, {"t": "下声肆。", "b": "《周礼·典同》。注:“谓钟形下大。”"}, {"t": "君臣上下。", "b": "《礼记·曲礼》"}, {"t": "阴山下。", "b": "《乐府诗集·杂歌谣辞·敕勒歌》"}, {"t": "放之山下。", "b": "唐·柳宗元《三戒》"}, {"t": "愬至城下。", "b": "《资治通鉴·唐纪》"}, {"t": "奔倚其下。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "下元", "t": "道教指水中或水府"}, {"w": "下溜头", "t": "下流头。江河下游"}, {"w": "下江先生", "t": "下路客人。对长江下游一带人的敬称"}, {"w": "下眼相看", "t": "看不起人"}, {"w": "下路人", "t": "居住在长江下游地区的人。"}]}, {"meaning": "地。", "cites": [{"t": "西南四百里,曰昆仑之丘,是实为帝之下都。", "b": "《山海经·西山经》"}], "words": [{"w": "下鬼", "t": "地下之鬼;指死者"}, {"w": "下世", "t": "阴间"}, {"w": "下土", "t": "大地;天下;指人间"}, {"w": "下都", "t": "神话传说中称天帝在地上所住的都邑。"}]}, {"meaning": "臣下;百姓;群众。", "cites": [{"t": "于是乎下陵上替,能无乱乎?", "b": "《左传·昭公十八年》"}], "words": [{"w": "全国上下", "t": ""}, {"w": "下民", "t": "百姓;人民"}, {"w": "下比", "t": "属下相互勾结。"}]}, {"meaning": "方面。", "cites": [{"t": "忽然见林南下有一股子黑气,骨都都的冒将上来。", "b": "《西游记》"}]}, {"meaning": "特指湖泽。", "cites": [{"t": "帝曰:“畴若予上下草木鸟兽”。", "b": "《书·舜典》"}]}, {"meaning": "地表之下。", "cites": [{"t": "夫子疾,莫养于下,请以殉葬。", "b": "《礼记》"}]}, {"meaning": "里面。", "cites": [{"t": "众军心下大乱,不敢交战,各自奔走。", "b": "《三国演义》"}]}, {"meaning": "旧时时间单位,相当于“点”。", "cites": [{"t": "三下一刻了。", "b": "《二十年目睹之怪现状》"}]}, {"meaning": "指时间、处所、范围。", "cites": [{"t": "及郡下。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "位在下的人。", "cites": [{"t": "不耻下问。", "b": "《论语》"}, {"t": "不忍为之下。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "上下齐同。", "b": "《资治通鉴》"}, {"t": "与其群下", "b": ""}]}, {"meaning": "下来。", "cites": [{"t": "下,视其辙,登,轼而望之。", "b": "《左传》"}, {"t": "下车引之。", "b": "《世说新语·方正》"}, {"t": "下见小潭。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "客驰下。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "下世", "t": "神仙到人间去"}, {"w": "下山", "t": ""}, {"w": "下楼", "t": ""}, {"w": "下凡", "t": "神话中,神仙降至人间称“下凡”"}, {"w": "下帷", "t": "放下室内悬挂的帷幕。"}]}, {"meaning": "落下;降下。", "cites": [{"t": "下,落也。", "b": "《尔雅》"}, {"t": "飞流直下三千尺,疑是银河落九天。", "b": "李白《望庐山瀑布》"}], "words": [{"w": "下火", "t": "天气炎热"}, {"w": "下雨", "t": ""}, {"w": "下雪", "t": ""}, {"w": "下雹子", "t": ""}]}, {"meaning": "弯屈。", "cites": [{"t": "魏延平日恃功务高,人皆之下。", "b": "《三国演义》"}], "words": [{"w": "下头", "t": "低头"}, {"w": "下腰", "t": "弯腰。比喻屈服。"}]}, {"meaning": "卸下。", "cites": [{"t": "宾主下尘榻。", "b": "沈约《和谢宣城》"}, {"t": "下担捋髭须。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "下门", "t": "店铺卸下门板,谓开市。"}]}, {"meaning": "发表、宣告。", "cites": [{"t": "令初下。", "b": "《战国策·齐策》"}, {"t": "诏既下。", "b": "清·梁启超《谭嗣同传》"}, {"t": "谕旨将下", "b": ""}, {"t": "而卒不下", "b": ""}], "words": [{"w": "下制", "t": "下诏;皇帝发布诏令"}, {"w": "下指示", "t": ""}, {"w": "下令", "t": ""}, {"w": "下逐客令", "t": ""}, {"w": "下命令", "t": ""}, {"w": "下战书", "t": ""}, {"w": "下请帖", "t": ""}]}, {"meaning": "去;到。", "cites": [{"t": "便下襄阳。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "顺江东下。", "b": "《资治通鉴》"}, {"t": "水陆俱下", "b": ""}, {"t": "买舟而下。", "b": "清·彭端淑《为学一首示子侄》"}]}, {"meaning": "做饭。", "cites": [{"t": "等我里头赶着给你老炸点儿锅渣面筋,下点儿素面你吃。", "b": "《儿女英雄传》"}], "words": [{"w": "下饺子", "t": ""}, {"w": "下面条", "t": ""}, {"w": "下汤圆", "t": ""}]}, {"meaning": "夺得、攻取、占领或攻占。", "cites": [{"t": "皆下之。", "b": "《史记·陈涉世家》"}, {"t": "乐毅抉持微弱之燕,下齐七十余城。", "b": "《三国演义》"}]}, {"meaning": "又如:连下数城。"}, {"meaning": "歇宿;收留。", "cites": [{"t": "徐孺下陈蕃之榻。", "b": "王勃《滕王阁序》"}, {"t": "官人要下呵,俺这里有干净店房。", "b": "《西厢记》"}]}, {"meaning": "又如:下人(旅店安排客人住宿);下处(住所;旅店);下店。"}, {"meaning": "投降。", "cites": [{"t": "吾恐不能守矣,欲以城下,何国之可下?", "b": "《韩非子》"}]}, {"meaning": "又如:下气(说求饶的话);下腰(弯腰。比喻屈服)。"}, {"meaning": "居人之下;谦让。", "cites": [{"t": "寇恂相下之义,以济国事。", "b": "《三国志》"}, {"t": "其下圣人也亦远矣。", "b": "唐·韩愈《师说》"}]}, {"meaning": "又如:下人(居于人下);下顾(照顾;关照);下气(恭敬顺从)。"}, {"meaning": "安扎。", "cites": [{"t": "各依本方下营。", "b": "诸葛亮《兵要》"}]}, {"meaning": "拍。", "cites": [{"t": "抚尺一下。", "b": "《虞初新志·秋声诗自序》"}, {"t": "薄暮下管键。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "身分、地位低。", "cites": [{"t": "吾羞,不忍为之下。", "b": "《史记》"}], "words": [{"w": "下役", "t": "仆役;差人"}, {"w": "下一肩", "t": "次一等"}, {"w": "下作", "t": "低贱;卑微"}, {"w": "下次小的", "t": "下次孩儿。元代称仆役"}, {"w": "下番", "t": "称少数民族"}, {"w": "下人", "t": "下属。"}]}, {"meaning": "次序或时间在后。", "cites": [{"t": "上下同欲。", "b": "《孙子·谋攻》"}, {"t": "下道齐桓。", "b": "《史记·屈原贾生列传》"}, {"t": "自王以下。", "b": "《史记·魏公子列传》"}, {"t": "上下颇惊。", "b": "宋·文天祥《 后序》"}], "words": [{"w": "下稍头", "t": "后来;终了"}, {"w": "下浣", "t": "下旬"}, {"w": "下邻", "t": "右边的邻居"}, {"w": "下古", "t": "近古"}, {"w": "下半世", "t": "人的后半辈子"}, {"w": "下回", "t": "下次。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('31wx','寸','1','cùn','寸','3','','[{"pinyin": "cùn", "defs": [{"meaning": "(指事。小篆字形,从又,从一。“又”象手形,“一”指下手腕一寸之处。“寸”是汉字部首之一,从“寸”的字往往与“手”有关。本义:中医切脉,称距离手腕一寸长的部位为“寸口”,简称“寸”)。", "words": [{"w": "寸田", "t": "三丹田"}, {"w": "寸关尺", "t": "中医指寸口、关上、尺中的简称。"}]}, {"meaning": "长度单位, 1/10尺为一寸,古代计量长度单位的标准不同,寸的具体数值也有差异。", "cites": [{"t": "一丝而累,以至于寸,累寸不已,遂成丈匹。", "b": "《后汉书·列女传》"}]}, {"meaning": "引申为极短。", "cites": [{"t": "君与康先生捧诏恸哭,而皇上手无寸柄,无所为计。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "寸幅", "t": "短信"}, {"w": "寸旬", "t": "极短的时间"}, {"w": "寸铁", "t": "形容短小的兵器。"}]}, {"meaning": "协助。", "cites": [{"t": "两条棍响振天关,不见输赢皆傍寸。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('32wx','大','1','dà dài','大','3','','[{"pinyin": "dà", "defs": [{"meaning": "(象形。甲骨文字形,象人的正面形,有手有脚。“大”是汉字部首之一,从“大”的字往往与人类或人事有关。本义:大小的“大”)。"}, {"meaning": "形容体积、面积、数量、力量、规模、程度等方面超过一般或超过所比较的对象。与“小”相对。", "cites": [{"t": "大,天大地大人亦大,故大象人形。古文大也,籀文介,改古文亦象人形。凡大人、大夫、太子、太君,皆尊词。", "b": "《说文》"}, {"t": "遵彼大路兮。", "b": "《诗·郑风·遵大路》"}, {"t": "大有。", "b": "《易》。释文:“大有,包容丰富之象。”"}, {"t": "大报天而主日也。", "b": "《礼记·郊特牲》。"}, {"t": "其朝践用两大尊。", "b": "《周礼·司尊彝》。司农注:“大,古之瓦尊。”"}, {"t": "而祭大山之邑也。", "b": "《谷梁传·桓公元年》"}, {"t": "然后会于大庙。", "b": "《礼记·祭统》。注:“始祖庙也。”"}, {"t": "大,小大也。", "b": "《广韵》"}, {"t": "奠高山大川。", "b": "《书·禹贡》"}, {"t": "古田常上请爵禄而行之群臣,下大斗斛而施于百姓。", "b": "《韩非子·二柄》"}, {"t": "此不为远者小而近者大乎?", "b": "《列子·汤问》"}, {"t": "忽一人大呼。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "一只大口袋", "t": ""}, {"w": "山上的大白楼", "t": ""}, {"w": "大浸", "t": "大水"}, {"w": "大美", "t": "大功德,大功业"}, {"w": "大蔡", "t": "大龟"}, {"w": "大泉", "t": "大钱。"}]}, {"meaning": "年辈较长或排行第一的。", "cites": [{"t": "大兄言办饭,大嫂言视马。", "b": "汉乐府《孤儿行》"}, {"t": "诸葛恢大女适太尉庾亮儿。", "b": "《世说新语·方正》"}], "words": [{"w": "大妇", "t": "长子之妻"}, {"w": "大宗", "t": "宗法社会以嫡系长房为“大宗”;余子为小宗。"}]}, {"meaning": "重要,重大。", "cites": [{"t": "故临崩寄臣以大事也。", "b": "诸葛亮《出师表》"}, {"t": "愿牢定大计,莫用众人之议也!", "b": "《资治通鉴》"}], "words": [{"w": "大头脑", "t": "主脑;主旨"}, {"w": "大八丈", "t": "大人物"}, {"w": "大柄", "t": "大权"}, {"w": "大趣", "t": "大旨;主要的旨趣。"}]}, {"meaning": "德高望重的。", "cites": [{"t": "吾长见笑于大方之家。", "b": "《庄子·秋水》"}, {"t": "王年小而位大。", "b": "《世说新语·排调》"}, {"t": "利见大人。", "b": "《易·乾》"}], "words": [{"w": "大操", "t": "高尚的操守"}, {"w": "大贤", "t": "才德超群的人。"}]}, {"meaning": "超过一般。", "cites": [{"t": "陶公少有大志,家酷贫。", "b": "《世说新语·贤缓》"}]}, {"meaning": "学识渊博的。", "cites": [{"t": "大匠不为拙工改废绳墨。", "b": "《孟子·尽心上》"}]}, {"meaning": "规模大。", "cites": [{"t": "胡人大入塞。", "b": "《淮南子·人间训》"}, {"t": "公子乃置酒大会宾客。", "b": "《史记·魏公子列传》"}], "words": [{"w": "大手术", "t": ""}, {"w": "大反攻", "t": ""}]}, {"meaning": "性质严重。", "cites": [{"t": "欺君不忠,母病不孝,不忠不孝,其罪莫大。", "b": "《世说新语·政事》"}]}, {"meaning": "达到很广范围或很高程度,大肆。", "cites": [{"t": "约以连兵大举。", "b": "宋·文天祥《指南录·后序》"}, {"t": "此臣所课大患也。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "大长志气", "t": ""}, {"w": "大吃一惊", "t": ""}, {"w": "大大增加", "t": ""}, {"w": "大办农业", "t": ""}]}, {"meaning": "很,太,非常。", "cites": [{"t": "居简而行简,无乃大简乎?", "b": "《论语·雍也》"}, {"t": "大谩,愿闻其要。", "b": "《庄子·天道》"}, {"t": "告之以大古,教之以至顺。", "b": "《荀子·非十二子》"}, {"t": "少年大骇。", "b": "《聊斋志异·促织》"}, {"t": "门者答揖大喜奔出。", "b": "明·宗臣《报刘一丈书》"}, {"t": "何竟日默默在此,大类女郎也。", "b": "明·归有光《项脊轩志》。又如:不大好;不大舒服;大肯(非常愿意)"}]}, {"meaning": "大人。", "cites": [{"t": "刘道生日夕在事,大小殊快。", "b": "《世说新语·赏誉》"}, {"t": "小大稽首。", "b": "《诗·小雅·楚茨》"}]}, {"meaning": "大小。", "cites": [{"t": "今年杀诸贼奴,当取金印如斗大。", "b": "《世说新语·尤悔》"}]}, {"meaning": "长大。", "cites": [{"t": "小时了了,大未必佳。", "b": "《世说新语·言语》"}]}, {"meaning": "超过。", "cites": [{"t": "亦无大大王。", "b": "《战国策·秦策二》"}]}, {"meaning": "姓。"}]}, {"pinyin": "dài", "defs": [{"meaning": "“大夫”、“大王”。"}, {"meaning": "世代。", "cites": [{"t": "陵家历大为军将,世世从军为国征。", "b": "《敦煌变文集·李陵变文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('33wx','丈','1','zhàng','一','3','','[{"pinyin": "zhàng", "defs": [{"meaning": "(会意。小篆字形。从又(手)持“十”。十,十尺。本义:长度单位,十尺) 同本义。", "cites": [{"t": "丈,十尺也。", "b": "《说文》"}, {"t": "度五尺为墨,倍墨谓之丈。", "b": "《小尔雅》"}, {"t": "遂成丈匹。", "b": "《后汉书·列女传》"}, {"t": "白发三千丈。", "b": "唐·李白《秋浦歌》"}, {"t": "百丈冰。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "半匹红绸一丈绫,系向牛头充炭直。", "b": "唐·白居易《卖炭翁》"}, {"t": "长丈许。", "b": "明·魏禧《大铁锥传》"}], "words": [{"w": "丈尺", "t": "以丈、尺为单位来计量"}, {"w": "丈六", "t": "一丈六尺"}, {"w": "丈二", "t": "一丈二尺"}, {"w": "丈数", "t": "一丈多;丈把。"}]}, {"meaning": "古时对长辈男子的尊称。", "cites": [{"t": "丈者,长也。", "b": "《大戴礼记》"}], "words": [{"w": "丈人行", "t": "父辈;长辈"}, {"w": "丈母", "t": "丈母娘,丈妈,岳母"}, {"w": "丈丈", "t": "对尊长的敬称"}, {"w": "老丈;岳丈", "t": ""}]}, {"meaning": "扶,倚", "cites": [{"t": "丈,借为扶行之丈。老人持丈,故谓之丈人。别用杖通。", "b": "《六书正伪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('34wx','与','1','yǔ yù yú','一','3','','[{"pinyin": "yǔ", "defs": [{"meaning": "(会意。小篆字形,“一、勺”合起来,表示赐予别人东西。“與”,从与,从舁(yú),共同抬起,与,给予。合起来表偕同、朋友。本义:赐予,施予,给予)。"}, {"meaning": "同本义。", "cites": [{"t": "与,赐也,通作“与”。", "b": "《正字通》"}, {"t": "我持白璧一双,欲献项王,玉斗一双,欲与亚父。", "b": "《史记·项羽本纪》"}, {"t": "则与斗卮酒。", "b": ""}, {"t": "取与者,义之表也。", "b": "汉·司马迁《报任安书》"}, {"t": "与衣裳,吏护还之乡。", "b": "唐·柳宗元《童区寄传》"}, {"t": "有张氏藏书甚富。往借,不与,归而形诸梦。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "赠与", "t": "赠给"}, {"w": "交与", "t": "交给"}, {"w": "与人方便", "t": ""}, {"w": "与受同科", "t": "行贿和受贿的人受到同等的处罚"}, {"w": "与虎添翼", "t": "给老虎添上了翅膀。比喻给力量或才能很强的以助力,使其更强。"}]}, {"meaning": "交往;交好。", "cites": [{"t": "孰能相与无相与。", "b": "《庄子·大宗师》。释文:“犹亲也。”"}, {"t": "生与来日。", "b": "《礼记·曲礼》。按,犹交也。"}], "words": [{"w": "相与", "t": "彼此往来;相互。"}]}, {"meaning": "奖赏。", "cites": [{"t": "上以功劳与,则民战;上以《诗》《书》与,则民学问。", "b": "《商君书》"}], "words": [{"w": "与奖", "t": ""}, {"w": "与津贴", "t": ""}]}, {"meaning": "帮助;援助。", "cites": [{"t": "君不与胜者,而与不胜者。", "b": "《战国策·齐策》。注:“犹助也。”"}, {"t": "匈奴壤界兽圈,孤弱无与,此困亡之时也。", "b": "汉·桓宽《盐铁论》"}], "words": [{"w": "与助", "t": "赞助"}, {"w": "与点", "t": "谓孔子赞赏曾点的想法。后用以指长者的赞助。"}]}, {"meaning": "随从;随着。", "cites": [{"t": "桓公知天下诸侯多与己也。", "b": "《国语》"}], "words": [{"w": "与世推移", "t": "随着世道的变化而变化以合时宜"}, {"w": "与世沉浮", "t": "随波逐流"}, {"w": "与时偕行", "t": "变通逐时。"}]}, {"meaning": "等候,等待。", "cites": [{"t": "日月逝矣,岁不我与?", "b": "《论语·阳货》"}], "words": [{"w": "岁不我与", "t": ""}]}, {"meaning": "允许。", "cites": [{"t": "子曰:“与其进也,不与其退也。”", "b": "《论语》"}], "words": [{"w": "与告", "t": "准假。"}]}, {"meaning": "交付,偿还。", "cites": [{"t": "岁余不入,贷钱者多不能与其息,客奉将不给。", "b": "《史记》"}], "words": [{"w": "与利息", "t": ""}]}, {"meaning": "亲近。", "cites": [{"t": "公先与百姓而藏其兵。", "b": "《管子》"}]}, {"meaning": "党与;朋党。", "cites": [{"t": "与,党与也。从舁从与。与声。", "b": "《说文》"}, {"t": "敌多则力分,与众则兵彊。", "b": "《史记》"}, {"t": "群臣连与成朋。", "b": "《汉书》"}]}, {"meaning": "盟国,友邦。", "cites": [{"t": "王夺之人,霸夺之与,疆夺之地。", "b": "《荀子》"}], "words": [{"w": "与国", "t": "盟国;友邦。"}]}, {"meaning": "类;同类。", "cites": [{"t": "夫礼之立成者为饫,昭明光节而已,少曲与焉。", "b": "《国语》"}]}, {"meaning": "跟;和;及。", "cites": [{"t": "与臣而将四矣。", "b": "《战国策·魏策》"}, {"t": "孰与君少长。", "b": "《史记·项羽本纪》"}, {"t": "与城为殉。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "与武昌革命之役并寿。", "b": "孙文《黄花冈七十二烈士事略·序》"}]}, {"meaning": "对于;于。", "cites": [{"t": "君之始入京也,与言皇上无权…君不之信。", "b": "清·梁启超《谭嗣同传》"}]}, {"meaning": "与多用于轻微的疑问。吗。", "cites": [{"t": "求之与?抑与之与?", "b": "《论语·学而》"}, {"t": "然则师愈与?", "b": "《论语·先进》"}, {"t": "岂非士之愿与?", "b": "《史记·蔡泽传》"}, {"t": "而君逆寡人者,轻寡人与。", "b": "《战国策·魏策》"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "参与。", "cites": [{"t": "昔者仲尼与于蜡宾。", "b": "《礼运·大同》"}, {"t": "怀嬴与焉。", "b": "《左传·僖公二十三年》"}, {"t": "蹇叔之子与师。(与师,参军作战。)", "b": "《左传·僖公三十三年》"}]}]}, {"pinyin": "yú", "defs": [{"meaning": "", "cites": [{"t": "求之与?抑与之与?", "b": "《论语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('35wx','万','1','wàn mǒ','一','3','','[{"pinyin": "wàn", "defs": [{"meaning": "(形声。“萬”,甲骨文呈蝎子形。本义:蝎)。"}, {"meaning": "虫名。蝎。", "cites": [{"t": "万,虫也。", "b": "《说文》"}], "words": [{"w": "万寿", "t": "称皇帝、皇后的生日"}, {"w": "万劫", "t": "即万世。形容极长的时间"}, {"w": "万井", "t": "古代以地方一里为一井,万井即一万平方里"}, {"w": "万夫", "t": "万人"}, {"w": "万户", "t": "一万户"}, {"w": "万户侯", "t": "食邑万户之侯"}, {"w": "万顷", "t": "百万亩。百亩为一顷。"}]}, {"meaning": "古州名。"}, {"meaning": "南朝梁大同二年置。治所在石城(今四川省达县)。"}, {"meaning": "唐贞观八年改浦州置。治所在南浦(今四川省万县市)。"}, {"meaning": "明洪武元年置。治所在万安(今广东省万宁县)。"}, {"meaning": "县名 。在四川省东部长江北岸。三国吴置羊渠县,蜀汉改南浦县,元入万州,明改万县。"}, {"meaning": "倍。", "cites": [{"t": "悲苦之怀,必万常人。", "b": "宋·苏轼《与滕达道二十三首》"}]}, {"meaning": "极言其多。", "cites": [{"t": "高万仞。", "b": "《列子·汤问》"}, {"t": "万里赴戎机。", "b": "《乐府诗集·木兰诗》"}, {"t": "一片孤城万仞山。", "b": "唐·王之涣《凉州词》"}, {"t": "千朵万朵压枝低。", "b": "唐·杜甫《江畔独步寻花》"}], "words": [{"w": "万几", "t": "指全国政务"}, {"w": "万人敌", "t": "能敌万人的兵法或谋略"}, {"w": "万生院", "t": "动物园"}, {"w": "万乘", "t": "万辆马车"}, {"w": "万机", "t": "万几"}, {"w": "万仞", "t": "形容极高"}, {"w": "万年草料", "t": "骂人话。饮食寿命"}, {"w": "万国", "t": "各方诸侯。引申为全国各地;天下"}, {"w": "万寿圣节", "t": "皇帝的生日"}, {"w": "万剐凌迟", "t": "剐刑。将人断肢割喉,剔肉离骨"}, {"w": "万乘之躯", "t": "指天子;帝王。"}]}, {"meaning": "极言各不相同。", "cites": [{"t": "勃兴得李杜,万类困陵暴。", "b": "韩愈《荐士》"}, {"t": "万类霜天竞自由。", "b": "毛泽东《沁园春·长沙》"}], "words": [{"w": "万化", "t": "各种变化"}, {"w": "万劫", "t": "种种灾难"}, {"w": "万殊", "t": "各不相同。亦指各种不同的现象、事物。"}]}, {"meaning": "姓。"}]}, {"pinyin": "mǒ", "defs": [{"meaning": "原为中国古代鲜卑族部落名；后为复姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('36wx','上','1','shàng shǎng shang','一','3','','[{"pinyin": "shàng", "defs": [{"meaning": "(指事。小篆字形。下面的“一”表示位置的界线,线上一短横表示在上面的意思。本义:高处;上面)。"}, {"meaning": "同本义。", "cites": [{"t": "上,高也。", "b": "《说文》"}, {"t": "宛丘之上兮。", "b": "《诗·陈风·宛丘》"}, {"t": "施于松上。", "b": "《诗·小雅·頡弁》"}, {"t": "冬时有嗽上气疾。", "b": "《周礼·疾医》"}, {"t": "云上于天干。", "b": "《易·需》"}, {"t": "上食埃土,下饮黄泉。", "b": "《荀子·劝学》"}, {"t": "列其姓名于大堤之上。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "上荣", "t": "飞檐。屋檐两端的挑角"}, {"w": "上柽", "t": "门框上端的横梁"}, {"w": "上漏下湿", "t": "形容屋舍破旧,不蔽风雨"}, {"w": "上网", "t": "系在箭靶上方的绳子"}, {"w": "上丹田", "t": "道家谓人的两眉之间为上丹田"}, {"w": "上下肩", "t": "上边和下边,也指左右两边。"}]}, {"meaning": "上天;天帝。", "cites": [{"t": "文王在上。", "b": "《诗·大雅·文王》"}, {"t": "上下天光,一碧万顷。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "上方", "t": "天上仙界;皇帝"}, {"w": "上干天怒", "t": "惹起上天震怒"}, {"w": "上仙", "t": "天上的神仙"}, {"w": "上穹", "t": "上天;天帝"}, {"w": "上皇", "t": "天帝"}, {"w": "上神", "t": "神灵;天神"}, {"w": "上都", "t": "指天宫。"}]}, {"meaning": "上级;尊长;社会的最高层。", "cites": [{"t": "观袁守虽得民,然自喜轻上,其祸非外至也。", "b": "明·高启《书博鸡者事》"}, {"t": "陵压百姓而邀其上者,何故?", "b": "宋·苏轼《教战守》"}], "words": [{"w": "上流", "t": "上辈"}, {"w": "上蒸下报", "t": "晚辈男人和长辈女子通奸叫“蒸”或“烝”;反之,叫“报”"}, {"w": "上户", "t": "富家巨室"}, {"w": "上厅", "t": "官署"}, {"w": "上宪", "t": "上司;上级官员"}, {"w": "上上乘", "t": "等级最高的"}, {"w": "上位", "t": "高位,显达的职位;特指君位,帝位"}, {"w": "上冢", "t": "指首辅,朝廷大臣"}, {"w": "上坐,上席", "t": "受尊敬的席位。"}]}, {"meaning": "君主;皇帝。", "cites": [{"t": "上胡不法先王之法?", "b": "《吕氏春秋·察今》"}, {"t": "上使外将兵。", "b": "《史记·陈涉世家》"}], "words": [{"w": "上用", "t": "皇帝用的规格"}, {"w": "上裁", "t": "皇帝裁定"}, {"w": "上国", "t": "汉代诸侯称帝室为上国,后多指国都京城"}, {"w": "上苑", "t": "供帝王打猎、玩耍的园林"}, {"w": "上林", "t": "泛指帝王的园囿。"}]}, {"meaning": "工尺谱里的“do”称为上。"}, {"meaning": "时间,时候。", "cites": [{"t": "三岁上读得书,五岁上属得对。", "b": "宋·佚名《张协状元》"}]}, {"meaning": "方位词,边,畔。", "cites": [{"t": "送我乎淇之上矣。", "b": "《诗·鄘风·桑中》"}, {"t": "乃徙武北海上无人处,使牧羝,羝乳乃得归。", "b": "《苏武》"}, {"t": "丧出江上,白衣冠送者夹岸。", "b": "《明史·海瑞传》"}]}, {"meaning": "上等,等级高或品质良好。", "cites": [{"t": "上客从赵来。", "b": "《战国策·秦策》"}, {"t": "凡用兵之法,全国为上,破国次之。", "b": "《孙子·谋攻》"}], "words": [{"w": "上色", "t": "上等;高级"}, {"w": "上行首", "t": "色艺俱佳的妓女"}, {"w": "上风官司", "t": "占优势能打赢的官司"}, {"w": "上庠", "t": "古代的大学;太学"}, {"w": "上色徒弟", "t": "高徒;出色的徒弟"}, {"w": "上样", "t": "上等"}, {"w": "上分", "t": "上等的福分"}, {"w": "上厅行首", "t": "色艺最佳的官妓"}, {"w": "上才", "t": "上等的才能;上等的材料"}, {"w": "上卿", "t": "指大臣的最高官阶。"}]}, {"meaning": "时间或次序在前。", "cites": [{"t": "其上世之士,衣不暖肤,食不满肠。", "b": "《商君书·算地》"}, {"t": "东方千余骑,夫婿居上头。", "b": "乐府诗《陌上桑》"}], "words": [{"w": "上件因依", "t": "上述因由"}, {"w": "上项", "t": "前头"}, {"w": "上方", "t": "前面"}, {"w": "上宙", "t": "上古"}, {"w": "上叶", "t": "前代;先世"}, {"w": "上次", "t": "前次,上回"}, {"w": "上首徒弟", "t": "入室弟子,大徒弟"}, {"w": "上风头", "t": "风吹来的一方"}, {"w": "上番", "t": "初番;头回。多指植物初生。"}]}, {"meaning": "远;久远。", "cites": [{"t": "上称帝喾,下道齐桓。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "上世", "t": "远古时代"}, {"w": "上皇", "t": "太古的帝皇。"}]}, {"meaning": "广大。", "cites": [{"t": "是以能上之。", "b": "《淮南子·说山》。注:“大也。”"}], "words": [{"w": "上路", "t": "大路;通衢"}, {"w": "上道", "t": "通衢;大路。"}]}, {"meaning": "丰足。", "cites": [{"t": "从其爵而上下之。", "b": "《周礼·司仪》。注:“犹丰杀也。”"}, {"t": "与年之上下。", "b": "《礼记·礼器》。注:“丰凶也。”"}], "words": [{"w": "上收", "t": "上等年成,丰收"}, {"w": "上岁", "t": "丰年"}, {"w": "上熟", "t": "上等收成。"}]}, {"meaning": "登;上升;向上。", "cites": [{"t": "下上其音。", "b": "《诗·邶风·燕燕》"}, {"t": "由山以上五六里,有穴窈然。", "b": "宋·王安石《游褒禅山记》"}, {"t": "上堂拜阿母,阿母怒不止。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "从流石蛇行而上。", "b": "明·徐宏祖《游黄山记》"}], "words": [{"w": "上圻", "t": "上岸"}, {"w": "上升", "t": "升天"}, {"w": "上高台盘", "t": "攀高位;向上爬"}, {"w": "上仙", "t": "道家谓升天成仙"}, {"w": "上征", "t": "上升"}, {"w": "上假", "t": "上升,登天"}, {"w": "上潮", "t": "涨潮。"}]}, {"meaning": "上报;呈报。", "cites": [{"t": "凡死刑狱上,其刑者先俟于门外。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "上复", "t": "禀报;奉告"}, {"w": "上控", "t": "上诉"}, {"w": "上详", "t": "向上级呈报请示"}, {"w": "上变", "t": "向朝廷密告谋反叛乱事件"}, {"w": "上功", "t": "呈报功劳"}, {"w": "上言", "t": "进呈言辞。"}]}, {"meaning": "进献,送上。", "cites": [{"t": "上书谏寡人者,受中赏。", "b": "《战国策·齐策》"}, {"t": "入都,即伏阙上《平黎策》。", "b": "《明史·海瑞传》"}, {"t": "臣乃敢上璧。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "上本", "t": "臣下向皇帝呈送奏本"}, {"w": "上表", "t": "上奏章"}, {"w": "上章", "t": "向皇帝上书。"}]}, {"meaning": "崇尚,提倡。", "cites": [{"t": "上笃厚。", "b": "《史记·平津侯主父传》"}, {"t": "治天下者审所上而已。", "b": "《汉书·匡衡传》"}, {"t": "上慎旃哉!", "b": "《诗·魏风·陟岵》"}, {"t": "上农除末,黔首是富。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "向前;前进。", "cites": [{"t": "乘舲船余上沅兮,齐吴榜以击汰。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "上水船", "t": "逆流而上的船。"}]}, {"meaning": "去;到。", "cites": [{"t": "敬亭丧失其资略尽,贫困如故时,始复上街头理其故业。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "苔痕上阶绿,草色入帘青。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "上地", "t": "下地耕作"}, {"w": "上门怪人", "t": "到人家里去责怪人家"}, {"w": "上桩", "t": "上场;赌博"}, {"w": "上花台", "t": "戏曲俗语。逛妓院,嫖妓"}, {"w": "上城", "t": "进城"}, {"w": "上墓", "t": "扫墓"}, {"w": "上冢", "t": "上坟;扫墓"}, {"w": "上馆子", "t": "去酒楼、饭店吃喝"}, {"w": "上边", "t": "到边远的地方去。"}]}, {"meaning": "放到;放进。", "cites": [{"t": "上于盆而养之,蟹白栗黄备极护爱。", "b": "《聊斋志异·促织》"}], "words": [{"w": "上腰", "t": "装进腰包。多指赚取非分的钱财。"}]}, {"meaning": "安装;装上。", "cites": [{"t": "以枪上刺刀相搏击。", "b": "《清稗类钞·战事类》"}]}]}, {"pinyin": "shǎng", "defs": [{"meaning": "汉语声调之一，普通话上声（第三声）。"}]}, {"pinyin": "shang", "defs": [{"meaning": "用在名词后，表示在物体的表面。"}, {"meaning": "用在名词后，表示在某种事物的范围以内。"}, {"meaning": "表示某一方面。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('37wx','小','1','xiǎo','小','3','','[{"pinyin": "xiǎo", "defs": [{"meaning": "(象形。据甲骨文,象沙粒形。小篆析为会意。从八,从|。本义:细;微。与“大”相对)。"}, {"meaning": "同本义 。形容事物在体积、面积、数量、力量、强度等方面不及一般的或不及比较的对象。", "cites": [{"t": "小,物之微也。", "b": "《说文》"}, {"t": "小往大来。", "b": "《易·泰》。疏:“阴生消耗,故称小。”"}, {"t": "彼所小言尽人毒也。", "b": "《庄子·列御寇》。注:“细巧入人为小言。”?"}, {"t": "嘒彼小星。", "b": "《诗·召南·小星》"}, {"t": "受小球大球。", "b": "《诗·商颂·长发》"}, {"t": "怨不在大,亦不在小。", "b": "《书·康诰》"}], "words": [{"w": "小鹿儿", "t": "喻指因紧张而剧烈跳动的心脏"}, {"w": "小录", "t": "新科进士的题名录"}, {"w": "小伙伙", "t": "小巧,娇小"}, {"w": "小话", "t": "短小的故事或寓言"}, {"w": "小单拱儿", "t": "手推车"}, {"w": "小唱", "t": "由乐器协奏的歌曲。"}]}, {"meaning": "年幼。", "cites": [{"t": "朝廷之事,小者不毁。", "b": "《韩非子·饬令》"}, {"t": "小妹语曰。", "b": "明·归有光《项脊轩志》"}, {"t": "龙君小女。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "小孽障", "t": "小孩子"}, {"w": "小猴子", "t": "小孩"}, {"w": "小堂名", "t": "旧时为婚丧喜庆雇用的由小孩组成的乐队"}, {"w": "小娘子", "t": "侍女;侍儿"}, {"w": "小娘儿", "t": "妓女"}, {"w": "小鬼头", "t": "小孩子"}, {"w": "小妮子", "t": "婢女;女孩子。"}]}, {"meaning": "稍,略。", "cites": [{"t": "汔可小康。", "b": "《诗·大雅·民劳》"}, {"t": "汔可小安。", "b": ""}, {"t": "汔可小休。", "b": ""}, {"t": "小不如意。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "小傲怄儿", "t": "带有一点玩笑意味的抬杠"}, {"w": "小节不足", "t": "不顺心;不能称心如意"}, {"w": "小厮扑", "t": "徒手对打"}, {"w": "小意儿", "t": "小殷勤"}, {"w": "小有", "t": "稍有一些。"}]}, {"meaning": "将近。", "cites": [{"t": "归了包堆花了小一百,还剩四百来块。", "b": "老舍《骆驼祥子》"}], "words": [{"w": "小日中", "t": "将近中午的时候"}, {"w": "我今年小", "t": "奔六十了。"}]}, {"meaning": "狭隘;低窄。", "cites": [{"t": "好问则裕,自用则小。", "b": "《书·仲虺之诰》"}], "words": [{"w": "小狭", "t": "狭窄"}, {"w": "小国", "t": "地狭人少之国"}, {"w": "小榻", "t": "狭小的卧具。"}]}, {"meaning": "低微。", "cites": [{"t": "不辞小官。", "b": "《孟子》"}], "words": [{"w": "小喽罗", "t": "对绿林兵卒的称呼"}, {"w": "小道儿", "t": "不正当的途径;邪门歪道。"}]}, {"meaning": "年幼的人。引申为小辈。", "cites": [{"t": "无小无大。", "b": "《诗·鲁颂·泮水》"}, {"t": "小大稽首。", "b": "《诗·小雅·楚茨》"}], "words": [{"w": "妻小", "t": ""}, {"w": "上有老,下有小", "t": ""}]}, {"meaning": "妾,小老婆。", "cites": [{"t": "要送你到冯家去,给冯老太爷做小。", "b": "巴金《家》"}], "words": [{"w": "小老母", "t": "妾;姨太太"}, {"w": "小星", "t": "妾"}, {"w": "小娘", "t": "妾"}, {"w": "小家婆", "t": "小老婆"}, {"w": "小浑家", "t": "小老婆。"}]}, {"meaning": "微细的事物。", "cites": [{"t": "小不忍则乱大谋。", "b": "《论语·卫灵公》"}], "words": [{"w": "小关头目", "t": "无关紧要的事"}, {"w": "小隙", "t": "小矛盾;小怨。"}]}, {"meaning": "小人,品质不高的人。", "cites": [{"t": "愠于群小。", "b": "《诗·邶风·柏舟》"}, {"t": "见群小满屋,都无相避意。", "b": "《世说新语·容止》"}], "words": [{"w": "小人", "t": "指强盗。"}]}, {"meaning": "小。", "words": [{"w": "小不起", "t": "不能小看"}, {"w": "小瞧", "t": "犹小看,轻视。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('38wx','口','1','kǒu','口','3','','[{"pinyin": "kǒu", "defs": [{"meaning": "(象形。甲骨文字形,象人的口形。本义:口腔器官,嘴)。"}, {"meaning": "同本义。人类用来发声和进食的器官。", "cites": [{"t": "口,人所以言食也。", "b": "《说文》"}, {"t": "且夫口三五之门也。", "b": "《国语·晋语》"}, {"t": "口之为言达也。", "b": "《春秋·元命苞》"}, {"t": "口者心之门户。", "b": "《鬼谷子·捭阖》"}, {"t": "勺饮不入口七日。", "b": "《左传·定公四年》"}, {"t": "下有蟾蜍,张口承之。", "b": "《后汉书·张衡传》"}, {"t": "卖炭得钱何所营?身上衣裳口中食。", "b": "白居易《卖炭翁》"}], "words": [{"w": "口腹", "t": "指饮食"}, {"w": "口分", "t": "口福"}, {"w": "口滑", "t": "指吃东西失去控制;说话不谨慎"}, {"w": "口辅", "t": "面颊。辅:颊"}, {"w": "口眼弗闭", "t": "放心不下;死不瞑目"}, {"w": "口里摆菜碟儿", "t": "比喻嘴上说得很好,但无实惠。"}]}, {"meaning": "出入通过的地方。", "cites": [{"t": "山有小口。", "b": "晋·陶渊明《桃花源记》"}, {"t": "由接官亭至城门口。", "b": "《广东军务记》"}, {"t": "俱会大通口。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "彭蠡之口有石钟山焉。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "井口", "t": ""}, {"w": "矿井口", "t": ""}, {"w": "火山口", "t": ""}]}, {"meaning": "又。", "cites": [{"t": "视高曾祖时口已不下五六十倍。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "而户与口之数常处其有余也。", "b": ""}], "words": [{"w": "口赋", "t": "古时按人口征收的赋税"}, {"w": "口合不敷", "t": "口粮不够,难以度日"}, {"w": "口井", "t": "计口分田,实行井田制。"}]}, {"meaning": "口才。", "cites": [{"t": "王有女陵,慧有口。", "b": "《汉书·淮南王刘安传》"}], "words": [{"w": "口沸", "t": "说话滔滔不绝,如水之沸腾"}, {"w": "口困", "t": "说破了嘴"}, {"w": "口稳", "t": "说话谨慎"}, {"w": "口拙", "t": "不善言语"}, {"w": "口卞", "t": "口才;能言善辩"}, {"w": "口坠天花", "t": "比喻说话有声有色,非常动听"}]}, {"meaning": "刃,武器或器具上刀片的切割边。", "cites": [{"t": "刀口不捲。", "b": "《水浒传》"}]}, {"meaning": "用于某些物品、家畜及人等。", "cites": [{"t": "发炮数口。", "b": "《广东军务记》"}], "words": [{"w": "三口之家", "t": ""}, {"w": "一口井", "t": ""}, {"w": "二口猪", "t": ""}, {"w": "一口钢刀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('39wx','山','1','shān','山','3','','[{"pinyin": "shān", "defs": [{"meaning": "(象形。甲骨文和金文字形,象山峰并立的形状。“山”是汉字的一个部首。本义:地面上由土石构成的隆起部分)。"}, {"meaning": "同本义。", "cites": [{"t": "山,土有石而高。", "b": "《说文》"}, {"t": "山,土之聚也。", "b": "《国语·周语》"}, {"t": "山人取之。", "b": "《左传·昭公四年》"}, {"t": "夏后代山。", "b": "《礼记·明堂位》"}, {"t": "太行、王屋二山,方七百里,高万仞。", "b": "《列子·汤问》"}, {"t": "如山如阜,如冈如陵。", "b": "《诗·小雅·天保》"}, {"t": "生于山阜,处于室堂。", "b": "《荀子·赋》"}, {"t": "为山九仞,功亏一篑。", "b": "《书·旅獒》"}, {"t": "山重水复疑无路,柳暗花明又一村。", "b": "陆游《游山西村》"}], "words": [{"w": "山霭", "t": "山上的云气"}, {"w": "山灵", "t": "山神"}, {"w": "山阿", "t": "山中凹曲的地方"}, {"w": "山岩", "t": "山峰;山崖"}, {"w": "山隈", "t": "山角"}, {"w": "山啜", "t": "山岔"}, {"w": "山落", "t": "山岔;山角落"}, {"w": "山孤钉", "t": "小山包"}, {"w": "山头", "t": "绿林好汉占据的山寨;坟地;山墙"}, {"w": "山长", "t": "科举时代的书院主讲及总领院务者"}, {"w": "山主", "t": "寺院的主持"}, {"w": "山观", "t": "山中道观"}, {"w": "山关", "t": "依山而建的城堡。"}]}, {"meaning": "形状像山的东西。", "cites": [{"t": "刃树剑山。", "b": "《南齐书·高逸传伦》"}], "words": [{"w": "冰山", "t": ""}, {"w": "鳌山", "t": ""}, {"w": "山枕", "t": "枕头。古代枕头多用木、瓷制作,中凹,形似山"}, {"w": "山堆阜积", "t": "东西堆积得像山一样"}, {"w": "山棚", "t": "结彩的牌楼;比武台,戏台"}, {"w": "山家", "t": "佛寺。"}]}, {"meaning": "特指“五岳”。", "cites": [{"t": "奠高山大川。", "b": "《书·禹贡》。孔传:“高山,五岳。大川,四渎。”"}], "words": [{"w": "山斗", "t": "“泰山北斗”的缩略。借指卓有成就令人仰慕的人物"}, {"w": "山右", "t": "指山西省,西在太行山之右"}, {"w": "山左", "t": "山东的别称。"}]}, {"meaning": "指酒肆的楼上。", "cites": [{"t": "酒阁名曰厅院,若楼上则又或名为山,一山、二山、三山之类。牌额写过山,非特有山,谓酒力高远也。", "b": "宋·灌圃耐得翁《都城纪胜》"}]}, {"meaning": "粗俗。", "cites": [{"t": "你道山不山?中了状元一道烟。", "b": "《牡丹亭》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('40wx','巾','1','jīn','巾','3','','[{"pinyin": "jīn", "defs": [{"meaning": "(象形。甲骨文字形,象布巾下垂之形。本义:佩巾,拭布,相当于现在的手巾)。"}, {"meaning": "同本义。", "cites": [{"t": "巾,佩巾也。", "b": "《说文》"}, {"t": "沐巾一。", "b": "《仪礼·士冠礼》"}, {"t": "盥卒授巾。", "b": "《礼记·内则》"}, {"t": "布巾环幅不凿。", "b": "《仪礼·士丧礼》"}, {"t": "静其巾幂。", "b": "《仪礼·特牲馈食礼》"}, {"t": "儿女共沾巾。", "b": "《战国策·魏策》"}, {"t": "归来泪满巾。", "b": "宋·张俞《蚕妇》"}, {"t": "巾短情长。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "花巾;小丝巾;巾栉", "t": "梳洗用品,即手巾和梳子;梳洗打扮"}, {"w": "巾帚", "t": "拭巾和扫帚"}, {"w": "巾帨", "t": "毛巾。"}]}, {"meaning": "缠束或覆盖用的织物。", "cites": [{"t": "巾袖无光。", "b": "唐·李朝威《柳毅传》"}, {"t": "簌簌衣巾落枣花。", "b": "宋·苏轼《浣溪沙》"}]}, {"meaning": "头巾。", "cites": [{"t": "愆礼巾,所以饰首。", "b": "《风俗通》"}, {"t": "巾,本以拭物,后人著之于头。", "b": "《玉篇》"}, {"t": "羽扇纶巾。", "b": "苏轼《赤壁怀古》"}, {"t": "首戴方山巾。", "b": "李白《嘲鲁儒》"}, {"t": "幅巾藜杖北城头,卷地西风满眼愁。", "b": "陆游《秋晚登城北门》"}], "words": [{"w": "巾帻", "t": "头巾"}, {"w": "巾冠", "t": "巾和冠"}, {"w": "巾絮", "t": "头巾"}, {"w": "巾囊", "t": "包裹,布袋"}, {"w": "巾帽", "t": "头巾和帽子"}, {"w": "巾卷", "t": "古代士族所用的头巾和书卷。引申为士族的代称。"}]}, {"meaning": "巾箱。", "cites": [{"t": "巾卷充街。", "b": "《文选·皇太子释奠会诗》"}], "words": [{"w": "巾笈", "t": "存放巾帛、书卷的小箱子"}, {"w": "巾笥", "t": "有巾帛覆盖的箱子"}, {"w": "巾衍", "t": "放置头巾、书卷等物的小箱子"}, {"w": "巾笥", "t": "即巾箱"}, {"w": "巾箧", "t": "巾箱。"}]}, {"meaning": "包裹;覆盖。", "cites": [{"t": "巾,犹衣也。珠丛云:以衣被车谓之巾。", "b": "《周礼·巾车》注"}, {"t": "巾以文绣。(用绣巾盖着。)", "b": "《庄子》"}], "words": [{"w": "巾幂", "t": "用来覆盖礼器的布帛。引申为“覆盖”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('41wx','千','1','qiān','十','3','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从十,人声。本义:数目。十百为千) 同本义。", "cites": [{"t": "千,十百也。", "b": "《说文》"}], "words": [{"w": "千夫", "t": "一千个成年男子"}, {"w": "千门", "t": "千家"}, {"w": "千社", "t": "25家为社,千社为25000家"}, {"w": "千祀", "t": "千年,千代"}, {"w": "总数为一千", "t": ""}, {"w": "千乘", "t": "兵车千辆"}, {"w": "千载", "t": "千年。"}]}, {"meaning": "比喻数甚大;许许多多。", "cites": [{"t": "清丽千眼。", "b": "陆机《文赋》。注:光色盛貌。”"}], "words": [{"w": "千千", "t": "比喻数目很多"}, {"w": "千般", "t": "多种花样"}, {"w": "千寻", "t": "形容极高"}, {"w": "千钟", "t": "丰厚的俸禄。指富贵"}, {"w": "千万劫", "t": "很长久"}, {"w": "千式百样", "t": "各种各样"}, {"w": "成千上万", "t": ""}, {"w": "白发三千丈", "t": ""}, {"w": "千丁", "t": "很多人"}, {"w": "千人坑", "t": "指堆积大量人尸的土坑"}, {"w": "千山", "t": "极言山多"}, {"w": "千百", "t": "极言其多"}, {"w": "千帆", "t": "众多的帆船"}, {"w": "千和", "t": "多种原料合成的香"}, {"w": "千指", "t": "形容人多"}, {"w": "千品", "t": "多种品物"}, {"w": "千度", "t": "次数多"}, {"w": "千衲", "t": "众僧"}, {"w": "千骑", "t": "人马很多"}, {"w": "千颦", "t": "多愁。"}]}, {"meaning": "田间小路。", "cites": [{"t": "四政曰端险阻修封疆,正千伯。", "b": "《管子·四时》"}, {"t": "坏井田,开千伯。", "b": "《汉书·食货志上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('42wx','乞','1','qǐ','乙','3','','[{"pinyin": "qǐ", "defs": [{"meaning": "(象形。《说文》本作“气”,借云气字表示乞求义。本义:向人求讨)。"}, {"meaning": "同本义。", "cites": [{"t": "乞,谓行匄也。", "b": "《苍颉篇》"}, {"t": "郑伯乞盟。", "b": "《春秋·僖公八年》"}, {"t": "乞者,处其所而请与也。", "b": "《谷梁传》"}, {"t": "操瓢而乞者。", "b": "《庄子·盗跖》"}, {"t": "乞食于野人。", "b": "《左传·僖公二十三年》"}, {"t": "以钱币乞之。", "b": "宋·王安石《伤仲永》"}, {"t": "乞为囚虏之不暇。", "b": "宋·苏轼《教战守策》"}, {"t": "瑞亦屡疏乞休。", "b": "《明史》"}], "words": [{"w": "乞化", "t": "乞讨;化缘"}, {"w": "乞言", "t": "求取可行的善言"}, {"w": "乞邻", "t": "向邻人求取"}, {"w": "乞粮", "t": "求人济助粮食"}, {"w": "乞活", "t": "到有粮之地就食求生"}, {"w": "乞募", "t": "求募"}, {"w": "乞麾", "t": "求住地方长官"}, {"w": "乞灵", "t": "求助于神灵或某种神威"}, {"w": "乞请", "t": "乞讨。"}]}, {"meaning": "引申为请求,希望。", "cites": [{"t": "乞,求也。", "b": "《广韵》"}, {"t": "宋公使来乞师,公辞之。", "b": "《左传·隐公四年》"}], "words": [{"w": "乞匄", "t": "乞求"}, {"w": "乞免", "t": "求人赦免;自请免官"}, {"w": "乞师", "t": "求人出兵相助"}, {"w": "乞鞫", "t": "请求复审"}, {"w": "乞念", "t": "乞求考虑"}, {"w": "乞哀", "t": "乞求怜悯、饶恕"}, {"w": "乞和", "t": "求和"}, {"w": "乞命", "t": "请求宽宥生命。"}]}, {"meaning": "被;叫。", "cites": [{"t": "那和尚猛可地乞他摔住。", "b": "《清平山堂话本》"}, {"t": "乞那婆子缠不过,便道:“你放了手,我去便了。”", "b": "《水浒传》"}]}, {"meaning": "乞丐。", "cites": [{"t": "蹴尔而与之,乞人不屑也。", "b": "《孟子·告子上》"}, {"t": "余疑其为女乞而问曰:“尔有丈夫乎?”乞微笑。", "b": "袁宏道《山居小话》"}], "words": [{"w": "乞俭", "t": "乞丐。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('43wx','川','1','chuān','川','3','','[{"pinyin": "chuān", "defs": [{"meaning": "(象形。甲骨文字形,左右是岸,中间是流水,正像河流形。本义:河流)。"}, {"meaning": "同本义。", "cites": [{"t": "川,贯川通流水也。", "b": "《说文》。按,象水直达之形。"}, {"t": "水之出于他水,沟流于大水及海者,命曰川水。", "b": "《管子·度地》"}, {"t": "有川衡。", "b": "《周礼·地官》"}, {"t": "利涉大川。", "b": "《易·需》"}, {"t": "百川沸腾。", "b": "《诗·小雅·十月之交》"}, {"t": "如川之方至。", "b": "《诗·小雅·天保》"}, {"t": "川壅为泽。", "b": "《左传·宣公十二年》"}, {"t": "晴川历历汉阳树,芳草萋萋鹦鹉洲。", "b": "崔颢《黄鹤楼》"}], "words": [{"w": "川源", "t": "河川的源头"}, {"w": "顺尊", "t": "取自河川的祭品"}, {"w": "川游", "t": "游泳渡河"}, {"w": "川口", "t": "河口"}, {"w": "川水", "t": "江河之水"}, {"w": "川防", "t": "河堤"}, {"w": "川谷", "t": "河谷"}, {"w": "川坻", "t": "河岸"}, {"w": "川岗", "t": "河畔的山岗。"}]}, {"meaning": "平地;平野。", "cites": [{"t": "敕勒川,阴山下。", "b": "北朝乐府《敕勒川》"}], "words": [{"w": "平川;米粮川;川境", "t": "地域"}, {"w": "川地", "t": "平旷的地带。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('44wx','亿','1','yì','亻','3','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。左形,右声。本义:安宁)。"}, {"meaning": "安宁;安定。", "cites": [{"t": "亿,安也。", "b": "《说文》"}, {"t": "不能供亿。", "b": "《左传·隐公十年》"}, {"t": "心亿则乐。", "b": "《左传·昭公二十一年》"}, {"t": "我盍姑亿吾鬼神。", "b": "《左传·昭公三十年》"}, {"t": "亿其上下。", "b": "《国语·楚语》"}, {"t": "心亿则乐。", "b": "《左传·昭公二十一年》"}], "words": [{"w": "共亿", "t": "相安"}, {"w": "亿康", "t": "安康"}, {"w": "亿福", "t": "安宁幸福。"}]}, {"meaning": "极多;极大。", "cites": [{"t": "据亿丈之城。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "亿兆", "t": "比喻很多,难以计数"}, {"w": "亿庶", "t": "亿众。亿万众庶。"}]}, {"meaning": "满。", "cites": [{"t": "不可亿逞。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "亿盈", "t": "淆溢"}, {"w": "亿廪", "t": "亿庾。满仓。"}]}, {"meaning": "数目的名称。古代有时把十万叫亿。今以万万为亿,即以阿拉伯数字100000000标记的可数量。", "cites": [{"t": "三百亿兮。", "b": "《诗·魏风·伐檀》"}, {"t": "亿丧贝。", "b": "《易·震》。郑注:“十万曰亿。”"}, {"t": "为田九十亿亩。", "b": "《礼记·王制》"}], "words": [{"w": "亿劫", "t": "佛家说从天地形成到毁灭为“一劫”。意指时间极其久远"}, {"w": "亿载", "t": "亿年"}, {"w": "亿年", "t": "万万年。"}]}, {"meaning": "臆测,预料。", "cites": [{"t": "亿在屡中。", "b": "《论语·先进》"}, {"t": "策虑幅亿。", "b": "《汉书·陈汤传》"}, {"t": "不可亿度。", "b": "《旧唐书·李道宗传》"}], "words": [{"w": "亿中", "t": "料事能中"}, {"w": "亿出", "t": "凭臆想而得出"}, {"w": "亿度", "t": "测度;揣测。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('45wx','个','1','gè gě','人','3','','[{"pinyin": "gè", "defs": [{"meaning": "通用个体量词,表示单独的人或物。", "cites": [{"t": "个,枚也。", "b": "《集韵》"}, {"t": "俎释三个。", "b": "《仪礼·士虞礼》"}, {"t": "竹竿万个。", "b": "《史记·货殖列传》。正义:“竹曰个,木曰枚。”"}]}, {"meaning": "字亦作“箇”。", "cites": [{"t": "箇,箇数,又枚也。", "b": "《广韵》"}]}, {"meaning": "俗又作“個”。", "cites": [{"t": "只有个爹爹,十三年前上朝取应去了。", "b": "关汉卿《窦娥冤》"}, {"t": "七八个星天外,两三点雨山前。", "b": "辛弃疾《西江月·夜行黄沙道中》"}]}, {"meaning": "也可用于某些有专用量词的事物。", "cites": [{"t": "一面旗,白胡阑套住个迎霜兔。", "b": "睢景臣《哨遍·高祖还乡》"}], "words": [{"w": "一个(只)耳朵", "t": ""}, {"w": "一个(所)学校", "t": ""}]}, {"meaning": "跟动作有关的用法。"}, {"meaning": "这;那。", "cites": [{"t": "白发三千丈,缘愁似个长。", "b": "唐·李白《秋浦歌》"}], "words": [{"w": "个般", "t": "这样,这般"}, {"w": "个样", "t": "这般,这样"}, {"w": "个侬", "t": "这人,那人"}, {"w": "个时", "t": "这时"}, {"w": "个是", "t": "这是"}, {"w": "个能", "t": "这样;如许。"}]}]}, {"pinyin": "gě", "defs": [{"meaning": "用于“自个儿”(zìgěr)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('46wx','夕','1','xī','夕','3','','[{"pinyin": "xī", "defs": [{"meaning": "(指事。从月半见。本义:黄昏,傍晚)。"}, {"meaning": "同本义。", "cites": [{"t": "夕,莫也。", "b": "《说文》"}, {"t": "日之夕矣。", "b": "《诗·王风·君子于役》"}, {"t": "日东则景夕多风。", "b": "《周礼·大司徒》。司农注:“谓日跌景乃中立表之处,大东近日也。”"}, {"t": "初昏为夕。", "b": "《书·洪范·五行》注"}, {"t": "夕市,夕时而市,贩夫贩妇为主。 ", "b": "《周礼·地官·司市》"}, {"t": "瘦影写微月,疏枝横夕烟。", "b": "宋·陆游《置酒梅花下作短歌》"}, {"t": "朝晖夕阴,气象万千。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "夕晖", "t": "夕阳的余晖"}, {"w": "朝发夕至;夕霭", "t": "黄昏的云气"}, {"w": "夕市", "t": "傍晚进行的集市贸易。"}]}, {"meaning": "夜。", "cites": [{"t": "今夕何夕。", "b": "《诗·唐风·绸缪》"}, {"t": "以永今夕。", "b": "《诗·小雅·白驹》"}, {"t": "朝而不夕。", "b": "《左传·成公十二年》"}, {"t": "以朝夕燕出入。", "b": "《周礼·道仆》"}, {"t": "君子终日乾乾,夕惕若厉无咎。", "b": "《易·乾》"}, {"t": "不知天上宫阙,今夕是何年。", "b": "苏轼《水调歌头》"}], "words": [{"w": "朝乾夕惕", "t": "形容终日勤奋工作,戒勉不已"}, {"w": "终夕不寝;通夕不寐;终夕;风雨之夕;住宿一夕;除夕", "t": "一年最后一天的夜晚"}, {"w": "前夕", "t": ""}]}, {"meaning": "指一年的最后一季或一个月的下旬。", "cites": [{"t": "晡时至黄昏为日之夕;下旬为月之夕;自九月尽至十二月为岁之夕。", "b": "《洪范·五行传》注"}, {"t": "月夕卜宅。", "b": "《荀子·礼论》"}]}, {"meaning": "晚潮。", "cites": [{"t": "官赋轨符,乘四时之朝夕。", "b": "《管子·国蓄》"}]}, {"meaning": "傍晚朝见君主。", "cites": [{"t": "古者旦见曰朝,暮见曰夕。", "b": "柳宗元《朝日说》"}, {"t": "百官承事,朝而不夕。", "b": "《左传·成公十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('47wx','久','1','jiǔ','丿','3','','[{"pinyin": "jiǔ", "defs": [{"meaning": "灸灼。“灸”的古字。", "cites": [{"t": "其腹有久故瘢二所。", "b": "《睡虎地秦墓竹简》"}, {"t": "久,以后灸之,象人两胫后有距也。", "b": "《说文》"}, {"t": "皆木桁,久之。", "b": "《仪礼·既夕礼》。注:“当为灸。”"}]}, {"meaning": "支撑。", "cites": [{"t": "久诸墙以观其桡也。", "b": "《周礼·庐人》。注:“犹柱也。今本以灸为之。”"}]}, {"meaning": "堵塞。", "cites": [{"t": "幂用疏布久之。", "b": "《仪礼·士丧礼》"}]}, {"meaning": "等待。", "cites": [{"t": "轩骄之兵,则恭敬而久之。", "b": "《银雀山汉墓竹简》"}]}, {"meaning": "滞留。", "cites": [{"t": "为久也。", "b": "《公羊传·庄公八年》"}, {"t": "寡君以为盟主之故,是以久子。", "b": "《左传》。杨伯峻注:“久子,久留子于晋也。”"}]}, {"meaning": "长久,时间久(跟“暂”相对)。", "cites": [{"t": "久行怀思。", "b": "《后汉书·列女传》"}, {"t": "夜久语声绝。", "b": "唐·杜甫《石壕吏》"}, {"t": "久已病矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "不可久居。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "久羁", "t": "长期滞留"}, {"w": "久惯牢成", "t": "老于世故"}, {"w": "久淹", "t": "久居于一处。"}]}, {"meaning": "从前的、先前的。", "cites": [{"t": "取完坚,补弊久,去苦恶。", "b": "《管子·度地》"}, {"t": "时暗而久章者。", "b": "《答宾戏》。注:“久,旧也。”"}], "words": [{"w": "久德", "t": "旧时的恩惠"}, {"w": "久要", "t": "旧日的邀约"}, {"w": "久坟", "t": "旧坟"}, {"w": "久将", "t": "旧将;老将"}, {"w": "久故", "t": "故旧,老朋友。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('48wx','么','1','me','丿','3','','[{"pinyin": "me", "defs": [{"meaning": "词尾。"}, {"meaning": "助词，表示含蓄语气，用在前半句末了。"}, {"meaning": "用作歌词中的衬字。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('49wx','勺','1','sháo','勹','3','','[{"pinyin": "sháo", "defs": [{"meaning": "(象形。本义:古代舀酒器)。"}, {"meaning": "同本义。泛指舀东西的器具,有柄。", "cites": [{"t": "勺,挹取也。象形。中有实,与包同意。", "b": "《说文》"}, {"t": "勺,枓也。", "b": "《一切经音义》引《说文》"}, {"t": "勺一升。", "b": "《考工记·梓人》"}, {"t": "黄金勺。", "b": "《周礼·玉人》。注:“酒尊中勺也。”"}, {"t": "宾勺。", "b": "《仪礼·士冠礼》。注:“尊升所以處酒也。”"}], "words": [{"w": "饭勺;炒勺", "t": "炒菜用的有柄铁锅"}, {"w": "马勺;掌勺儿;勺水", "t": "一勺水。指少量的水"}, {"w": "勺铎", "t": "方言。不聪敏"}, {"w": "勺饮", "t": "一勺汤水"}, {"w": "面粉勺;谷勺;量勺", "t": ""}]}, {"meaning": "容量单位名。历代不同。", "cites": [{"t": "一勺之多。", "b": "《礼记·中庸》"}, {"t": "十撮为一抄,十抄为一勺,十勺为一合。", "b": "《孙子算经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('50wx','凡','1','fán','几','3','','[{"pinyin": "fán", "defs": [{"meaning": "(象形。金文字形,象造器之模范形。①本义:铸造器物的模子。②引申义:凡是,表示概括)。"}, {"meaning": "凡是,一切。", "cites": [{"t": "凡,皆也。", "b": "《广雅》"}, {"t": "凡,数之总名也。", "b": "《三苍》"}, {"t": "深察名号,凡者,独举其大事也。号凡而略,名目而详。", "b": "《春秋繁露》"}, {"t": "凡有辜罪。", "b": "《书·微子》。郑注:“犹皆也。”"}, {"t": "凡内女之有爵者。", "b": "《周礼·春官序》"}, {"t": "凡所应有。", "b": "《虞初新志·秋声诗自序》"}, {"t": "凡四方之士无有不过而拜且泣者。", "b": "明·张溥《五人墓碑记》"}, {"t": "凡永嘉山水,游历殆遍。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "凡有", "t": "一切;所有"}, {"w": "凡此", "t": "所有这些。"}]}, {"meaning": "总共。", "cites": [{"t": "计凡付终。", "b": "《管子·版法》"}, {"t": "凡如是十许字。", "b": "宋·洪迈《容斋续笔》"}, {"t": "轩凡四遭火。", "b": "明·归有光《项脊轩志》"}, {"t": "凡六百一十六言。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "全书凡六卷,五十章;孙中山先生致力国民革命凡四十年;凡几", "t": "共计多少。"}]}, {"meaning": "平常;普通。", "cites": [{"t": "他近日所见的这几个三等的仆妇,吃穿用度,已是不凡了。", "b": "《红楼梦》"}, {"t": "尽众人凡士。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "平凡", "t": "平常;不稀奇"}, {"w": "凡材", "t": "普通材料"}, {"w": "凡常", "t": "普通,一般"}, {"w": "凡费", "t": "平常的费用"}, {"w": "凡等", "t": "普通人"}, {"w": "凡浅", "t": "平凡浅陋。"}]}, {"meaning": "平庸。", "cites": [{"t": "巨是凡人。", "b": "《资治通鉴》"}], "words": [{"w": "凡固", "t": "平庸鄙陋"}, {"w": "凡品", "t": "平庸的人"}, {"w": "凡曹", "t": "平庸之辈"}, {"w": "凡恶", "t": "平庸低劣"}, {"w": "凡短", "t": "才能平庸,见识短浅。"}]}, {"meaning": "纲要,概括之辞。", "cites": [{"t": "请略举凡,而客自鉴其切焉。", "b": "扬雄《长杨赋》"}], "words": [{"w": "凡目", "t": "大纲与细目"}, {"w": "凡最", "t": "总目;名目"}, {"w": "凡要", "t": "簿书的纲要"}, {"w": "凡号", "t": "总括的名称。"}]}, {"meaning": "人世间,尘世。", "cites": [{"t": "仙凡路阻两难留。", "b": "司空图《携仙箓》"}], "words": [{"w": "尼姑思凡;神仙下凡;凡界", "t": "人世间"}, {"w": "凡底", "t": "人间。"}]}, {"meaning": "古国名 。姬姓。始封之君为周公之子。在今河南省辉县西南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('51wx','丸','1','wán','丿','3','','[{"pinyin": "wán", "defs": [{"meaning": "(形声。反体指事。小篆是仄的反写。本义:小而圆的物体)。"}, {"meaning": "同本义。", "cites": [{"t": "丸,圜也。", "b": "《说文》"}, {"t": "五六月累丸二不坠。", "b": "《庄子·达生》"}, {"t": "市南宜僚弄丸。", "b": "《庄子·徐无鬼》"}, {"t": "首衔铜丸。", "b": "《后汉书·张衡传》"}, {"t": "机发吐丸。", "b": ""}], "words": [{"w": "鱼丸;肉丸;丸熊", "t": "形容母善教子。唐朝柳仲郢幼年好学,其母曾和熊胆丸,让其夜嚼以助勤促学"}, {"w": "丸丹", "t": "圆粒状丹药"}, {"w": "丸散", "t": "中药的丸剂、粉剂之属"}, {"w": "丸熊", "t": "用熊胆和制的药丸"}, {"w": "丸散膏丹", "t": "中药各种型剂的总称。"}]}, {"meaning": "特指弹丸。", "cites": [{"t": "金丸落飞鸟,夜入琼楼卧。", "b": "唐·李白《少年子》"}]}, {"meaning": "量词。", "cites": [{"t": "三次,三丸俱吞了。", "b": "《西游记》"}], "words": [{"w": "一次吃三丸;此药每服两丸", "t": ""}]}, {"meaning": "指鸟卵。", "cites": [{"t": "流沙之西,丹山之南,有凤之丸,沃民所食。", "b": "《吕氏春秋·本味》"}]}, {"meaning": "揉物使成小球形。", "cites": [{"t": "行者道:“要丸药。”", "b": "《西游记》"}, {"t": "熟剂与面剂相似,方可丸擀。", "b": "沈继孙《墨法集要·锤练》"}]}, {"meaning": "完。", "cites": [{"t": "丸,完也。", "b": "《广雅》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('52wx','及','1','jí','又','3','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。甲骨文字形,从人,从手。表示后面的人赶上來用手抓住前面的人。本义:追赶上,抓住)。"}, {"meaning": "同本义。", "cites": [{"t": "及,逮也。", "b": "《说文》"}, {"t": "使人追宋义子,及之齐,杀之。", "b": "《史记`项羽本纪》"}, {"t": "无庸,将自及。", "b": "《左传隐公元年》"}], "words": [{"w": "赶不及", "t": "来不及"}, {"w": "企及", "t": "希望赶上"}, {"w": "來得及", "t": "能够赶上"}, {"w": "及面", "t": "见面"}, {"w": "及时应令", "t": "与季节令令相适应。"}]}, {"meaning": "至,达到。", "cites": [{"t": "及,至也。", "b": "《广雅》"}, {"t": "及期。", "b": "《仪礼聘礼》"}, {"t": "不及黄泉,无相見也。", "b": "《左传隐公元年》"}, {"t": "及郡下,诣太守,说如此。", "b": "陶潜《桃花源记》"}, {"t": "及诸河,则在舟中矣。", "b": "《左传僖公三十三年》"}, {"t": "汤熨之所及也。", "b": "《韩非子喻老》"}, {"t": "针石之所及也。", "b": ""}, {"t": "将有及。(还來得及。)", "b": ""}, {"t": "骇而图之,岂将有及乎?", "b": "汉·贾谊《论积贮疏》"}, {"t": "祸且及汝。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "及瓜", "t": "到了出嫁的年龄"}, {"w": "及瓜而代", "t": "指为官任职期满,由人接代"}, {"w": "及事", "t": "女子到结婚年龄"}, {"w": "及肩", "t": "高仅与肩齐,比喻相差甚远。"}]}, {"meaning": "待,等到。", "cites": [{"t": "及日中则如盘盂。", "b": "《列子汤问》"}, {"t": "及日中如探汤。", "b": ""}, {"t": "及鲁肃过寻阳。", "b": "《资治通鉴汉纪》"}, {"t": "及敌枪再击。", "b": "清·徐珂《清稗类钞战事类》"}, {"t": "及既上。(等到已经登上。及:等到。既:已经。)", "b": "清姚鼐《登泰山記》"}], "words": [{"w": "及夫", "t": "等到。"}]}, {"meaning": "遭受。", "cites": [{"t": "铁铦短者及乎敌。(及乎敌,被敌所伤,极言战争之激烈。)", "b": "《韩非子五蠹》"}], "words": [{"w": "及难", "t": "遭到灾难"}, {"w": "及祸", "t": "遭灾难"}, {"w": "及溺呼船", "t": "喻祸到临头,求救无及"}, {"w": "及身", "t": "亲身受到。"}]}, {"meaning": "比得上,能与…相比。", "cites": [{"t": "徐公何能及君也?", "b": "《战囯策齐策》"}, {"t": "郯子之徒,其贤不及孔子。", "b": "韩愈《师说》"}], "words": [{"w": "我不及他", "t": ""}]}, {"meaning": "连累;关联。", "cites": [{"t": "老吾老以及人之老。", "b": "《孟子梁惠王上》"}, {"t": "事如此,此必及我。", "b": "《汉书李广苏建传》"}], "words": [{"w": "罚不及众", "t": ""}, {"w": "城门失火,殃及池鱼", "t": ""}]}, {"meaning": "供应。", "cites": [{"t": "然则大囯内款,小囯用尽,何以及之。", "b": "《管子囯蓄》"}]}, {"meaning": "趁。", "cites": [{"t": "彼众我寡,及其未既济也,请击之。", "b": "《左传僖公二十二年》"}], "words": [{"w": "及今", "t": "趁現今之时"}, {"w": "及蚤", "t": "趁早。蚤:通“早”。"}]}, {"meaning": "和,与。", "cites": [{"t": "洄曲及诸道桥梁。", "b": "《资治通鉴唐纪》"}, {"t": "洄曲及四境。", "b": ""}, {"t": "扣其乡及姓字。", "b": "明·魏禧《大铁椎传》"}, {"t": "音乐及诗歌。", "b": "蔡元培《图画》"}], "words": [{"w": "孔子及门徒", "t": ""}]}, {"meaning": "——表示反问,相当于“岂”。", "cites": [{"t": "先君之败德,及可数乎?", "b": "《左传》"}]}, {"meaning": "——表示頻率,相当于“又”。", "cites": [{"t": "儿宽家贫,当为弟子都养;及时时间行佣赁,以给衣食。", "b": "《史记》"}]}, {"meaning": "——表示程度,相当于“极”。", "cites": [{"t": "原是本府六案孔目出身,及好刀笔。", "b": "《水浒全传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('53wx','广','1','ān guǎng','广','3','','[{"pinyin": "ān", "defs": [{"meaning": "草屋。"}]}, {"pinyin": "guǎng", "defs": [{"meaning": "(形声。从广(yǎn),黄声。从“广”,表示与房屋有关。按:“广”和“廣”本不同义:是两个字。“广”,本读yǎn,甲骨文和金文的写法象屋墙屋顶,其含义是依山崖建造的房屋。现在“广”是“廣”的简化字。本义:宽大的房屋)。"}, {"meaning": "四周无壁的大屋。", "cites": [{"t": "广,殿之大屋也。", "b": "《说文》。段玉裁注:殿谓堂无四壁…覆乎上者曰屋,无四壁而上有大覆盖,其所通者宏远矣,是曰广。朱骏声曰:“堂无四壁者。秦谓之殿,所谓堂皇也,覆以大屋曰广。”"}, {"t": "天子之堂广九雉。", "b": "《尚书大传》。注:“荣间相去也。”"}, {"t": "居天下之广居。", "b": "《孟子》"}, {"t": "是求马于唐肆也。", "b": "《庄子·田子方》。司马注:“广庭也,以唐为之。”"}, {"t": "朱涂广,夷石为堂。(涂:粉饰。夷石:平整的石头做堂基)", "b": "《汉郊祀歌》"}, {"t": "量", "b": ""}]}, {"meaning": "宽度,横向尺寸。", "cites": [{"t": "广袤丰杀,一称心力。", "b": "白居易《庐山草堂记》"}, {"t": "今蛭广有分数,长有寸度。", "b": "《论衡·福虚》"}, {"t": "沈机长二丈,广八尺。", "b": "《墨子·备城门》"}, {"t": "即连楮为巨幅,广二丈,大书一“屈”字,以两竿夹揭之。", "b": "明·高启《书博鸡者事》"}, {"t": "前有平地,轮广十丈。", "b": "唐·白居易《庐山草堂记》。轮:南北距离"}], "words": [{"w": "广运", "t": "宽广。东西距离为广,南北距离为运。"}]}, {"meaning": "广州的省称。", "cites": [{"t": "杂彩三百匹,交广市鲑珍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "广交会;广疮", "t": "性病。此病似从国外经广州传入的,故称"}, {"w": "广里", "t": "指广州。"}]}, {"meaning": "广阔,宽阔;分布广;辽阔。", "cites": [{"t": "广,阔也。", "b": "《广韵》"}, {"t": "狄之广漠。", "b": "《左传·庄公二十八年》"}, {"t": "地广而益重。", "b": "《战国策·西周策》"}, {"t": "古者圣王为大川广谷之不可济,于是利为舟楫。", "b": "《墨子·节用中》"}, {"t": "平原广野,此车骑之地。", "b": "汉·晁错《言兵当疏》"}, {"t": "汉亡广矣,不可泳思。", "b": "《诗·周南·汉广》"}, {"t": "乃为赋以自广。", "b": "《史记·屈原·贾生列传》"}], "words": [{"w": "广通", "t": "广泛传播"}, {"w": "广交声气", "t": "多方交接意气相投的朋友"}, {"w": "广平", "t": "宽阔平坦"}, {"w": "广庄", "t": "宽阔的大道"}, {"w": "广狭", "t": "宽广与狭窄。"}]}, {"meaning": "引申为大。", "cites": [{"t": "四牡修广。", "b": "《诗·小雅·六月》"}, {"t": "安得广厦千万间,大庇天下寒士俱欢颜。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "明道德之广崇,治乱之条贯,靡不毕见。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "广厦细旃", "t": "高大的房屋"}, {"w": "广车", "t": "大车"}, {"w": "广舶", "t": "大型远洋船"}, {"w": "广肆", "t": "大店铺"}, {"w": "广衢", "t": "大道"}, {"w": "广眉", "t": "大眉,厚眉"}, {"w": "广渊", "t": "弘大深远。"}]}, {"meaning": "多,众多,数目很多。", "cites": [{"t": "自迎赢于众人广坐之中。", "b": "《史记·魏公子列传》"}, {"t": "竟敢在大庭广众之中,光天化日之下,横行不法,岂不怪哉", "b": ""}], "words": [{"w": "广众;广交", "t": "交友极多"}, {"w": "广坐", "t": "众人聚会列坐的地方。"}]}, {"meaning": "普通;广泛。", "cites": [{"t": "幸可广问讯,不得便相许。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "(kuàng)。荒废,耽搁。", "cites": [{"t": "不譲事,不广闲。", "b": "《管子·大匡》"}], "words": [{"w": "广广", "t": "荒废的状况"}, {"w": "广土", "t": "荒废的土地。"}]}, {"meaning": "引申为扩大。", "cites": [{"t": "克广德心。", "b": "《诗·鲁颂·泮水》"}, {"t": "广长榆。", "b": "《史记·淮南衡山传》。集解:“谓拓大之也。”"}, {"t": "今吾以十倍之地,请广于君。", "b": "《战国策·魏策》"}, {"t": "非问无以广识。", "b": "清·刘开《问说》"}], "words": [{"w": "广额", "t": "放宽录取名额。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('54wx','亡','1','wáng wú','亠','3','','[{"pinyin": "wáng", "defs": [{"meaning": "(会意。小篆字从入,从乚。“入”是人字。乚(yǐn)隐蔽。合起来表示人到隐蔽处。本义:逃离,出走)。"}, {"meaning": "同本义。", "cites": [{"t": "亡,逃也。", "b": "《说文》"}, {"t": "晋公子生十七年而亡。", "b": "《国语·晋语四》"}, {"t": "子牟有罪而亡。", "b": "《国语·楚语上》"}, {"t": "怀其璧,从径道亡。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "今亡亦死,举大计亦死。", "b": "《史记·陈涉世家》"}, {"t": "或以为亡。", "b": ""}, {"t": "数言欲亡。", "b": ""}, {"t": "亡而入胡。", "b": "《淮南子·人间训》"}, {"t": "奴惊,各亡去。", "b": "高启《书博鸡者事》"}, {"t": "是时桓楚亡在泽中。", "b": "《史记·项羽本纪》"}], "words": [{"w": "亡归", "t": "逃回"}, {"w": "逃亡", "t": "逃走在外"}, {"w": "亡虏", "t": "逃亡的犯人"}, {"w": "亡民", "t": "逃亡在外的百姓"}, {"w": "亡子", "t": "亡人。逃亡的人"}, {"w": "亡奔", "t": "逃奔"}, {"w": "亡臣", "t": "逃亡之臣"}, {"w": "亡逸", "t": "逃亡"}, {"w": "亡匿", "t": "逃跑并躲藏起来。"}]}, {"meaning": "死。", "cites": [{"t": "存亡不可知。", "b": "《汉书·李广苏建传》"}, {"t": "刘表新亡,二子不协。", "b": "《资治通鉴》"}, {"t": "身在身亡。", "b": "宋·司马光《训俭示康》"}, {"t": "长者先亡。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "亡人", "t": "死人。骂人的话"}, {"w": "阵亡", "t": "在作战中牺牲"}, {"w": "亡醮", "t": "为死者设坛祭祷"}, {"w": "亡友", "t": "死去的友人"}, {"w": "亡死", "t": "死亡"}, {"w": "亡殁", "t": "死亡"}, {"w": "亡化", "t": "死亡;去世。"}]}, {"meaning": "丢失;丧失。", "cites": [{"t": "亡赵自危。", "b": "《战国策·秦策五》"}, {"t": "非其所以与人而与人,谓之亡。", "b": "《谷梁传·定公八年》"}, {"t": "秦无亡矢遗镞之费。", "b": "汉·贾谊《过秦论》"}, {"t": "亡其六郡。", "b": "《史记·屈原贾生列传》"}, {"t": "大道以多歧亡羊。", "b": "马中锡《中山狼传》"}, {"t": "为蛇足者,终亡其酒。", "b": "《战国策·齐策》"}, {"t": "诸侯之所亡。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "亡逸", "t": "散失"}, {"w": "亡躯", "t": "丧身"}, {"w": "亡阙", "t": "亡缺。丧失残缺"}, {"w": "亡缺", "t": "散失残缺"}, {"w": "亡家犬", "t": "丧家犬"}, {"w": "亡书", "t": "散失的书籍。"}]}, {"meaning": "灭亡。", "cites": [{"t": "国恒亡。", "b": "《孟子·告子下》"}, {"t": "大亡其则。", "b": "《韩非子·说难》"}, {"t": "彼固亡国之形也。", "b": "《韩非子·初见秦》"}, {"t": "秦饥而宛亡。", "b": "《战国策·西周策》"}, {"t": "是故燕虽小国而后亡。", "b": "苏洵《六国论》"}, {"t": "亡无日矣。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "坐而待亡。", "b": ""}], "words": [{"w": "兴亡", "t": "兴盛和灭亡"}, {"w": "亡破", "t": "国破家亡"}, {"w": "亡君", "t": "亡国之君"}, {"w": "亡绝", "t": "国家败亡,宗庙绝祀"}, {"w": "亡征", "t": "灭亡的征兆。"}]}, {"meaning": "外出;出门。", "cites": [{"t": "孔子时其亡也,而往拜之。", "b": "《论语·阳货》"}]}, {"meaning": "沉迷于宴饮。", "cites": [{"t": "乐酒无厌谓之亡。", "b": "《孟子》"}]}, {"meaning": "", "cites": [{"t": "曷维其亡?", "b": "《诗·邶风·绿衣》"}, {"t": "圣人之法死亡亲,为天下也。厚亲分也。以死亡之。", "b": "《墨子·大取》"}, {"t": "人不能自止于足,而忘其富之涯乎。", "b": "《韩非子·说林下》"}, {"t": "知而亡情,能而不为,真知真能也。", "b": "《列子·仲尼》"}, {"t": "是亡楚国之社稷,而不率吾众也。", "b": "《淮南子》"}]}, {"meaning": "过去。", "cites": [{"t": "追亡事、今不见,但山川满目泪沾衣。", "b": "《木兰花慢》"}]}]}, {"pinyin": "wú", "defs": [{"meaning": "古同“无”。"}, {"meaning": "没有。", "cites": [{"t": "河曲智叟亡以应。", "b": "《列子·汤问》"}, {"t": "予美亡此,谁与独处。", "b": "《诗·唐风·葛生》"}, {"t": "亡则以缁,长半幅。", "b": "《仪礼·士丧礼》"}, {"t": "日知其所亡,月无忘其所能,可谓好学也已矣。", "b": "《论语·子张》"}, {"t": "人莫大焉亡亲戚君臣上下。", "b": "《孟子·尽心上》"}, {"t": "自苦亡人之地。", "b": "《汉书·李广苏建传》"}, {"t": "大且亡罪夷灭。", "b": ""}, {"t": "君子积学当日知其所亡。", "b": "《后汉书·列女传》"}]}, {"meaning": "副词,通“毋”可译为“不”、“不要”等,表示否定。", "cites": [{"t": "幸亡阻我。", "b": "明·宗臣《报刘一丈书》"}, {"t": "亡论长者。", "b": ""}, {"t": "法令亡常。", "b": "《汉书·李广苏建传》"}, {"t": "亡何国变。", "b": "清·黄宗羲《柳敬亭传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('55wx','门','1','mén','门','3','','[{"pinyin": "mén", "defs": [{"meaning": "(象形。甲骨文字形,象门形。“门”是汉字的一个部首。本义:双扇门,门)。"}, {"meaning": "同本义 。房屋垣墙等建筑物,在出入通口处所设可开关转动的装置。古代门与户有别,一扇曰户,两扇曰门;又在堂室曰户,在区域曰门。", "cites": [{"t": "門,闻也。从二户相对,象形。按,一扇曰户,两扇曰门。又,在堂室曰户,在宅区域曰门。", "b": ""}, {"t": "五祀,门以闭藏自固也。", "b": "《白虎通》"}, {"t": "门常闭。", "b": "《墨子·号令》"}, {"t": "门虽设而常关。", "b": "陶渊明《归去来辞》"}], "words": [{"w": "门阑", "t": "门帘;门框"}, {"w": "门钉", "t": "大门上的圆头装饰物"}, {"w": "门楔", "t": "门榄两端靠门框竖立的短木"}, {"w": "门吊儿", "t": "门上的搭钩"}, {"w": "门坎", "t": "门槛。"}]}, {"meaning": "房屋、围墙、车船等的出入口。", "cites": [{"t": "门,人所出入也。", "b": "《玉篇》"}, {"t": "王城十二门。", "b": "《周礼·司门》注"}, {"t": "出自北门。", "b": "《诗·邶风·北门》"}, {"t": "王使甲坐于道及其门。", "b": "《左传·昭公二十七年》"}, {"t": "洞门甚隘。", "b": "《徐霞客游记·楚游日记》"}, {"t": "君竟日不出门。(竟:终)", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "门籍", "t": "古时写有朝臣姓名年纪等,凭以出入宫门的门证"}, {"w": "门不停宾", "t": "宾来即见,不须等候。言主人能礼贤下士"}, {"w": "门状", "t": "家有丧事,将死者生卒年月及殡葬日期,书写于素纸之上,贴在门首,俗称为门状。"}]}, {"meaning": "门前,门口。", "cites": [{"t": "掌扫门庭。", "b": "《周礼·天官》"}], "words": [{"w": "门墉", "t": "门口墙边"}, {"w": "门台", "t": "门口的台阶"}, {"w": "门堂", "t": "门侧的堂室。也指家"}, {"w": "门戟", "t": "门前所列之戟"}, {"w": "门塾", "t": "闾门两侧的厅堂。古代乡里多于此设立家塾以教化民众。"}]}, {"meaning": "形状或作用像门的东西。", "cites": [{"t": "灶门老婢。", "b": "欧阳修《与尹师鲁书》"}], "words": [{"w": "门旗", "t": "在阵前对称竖立的两面大旗,即指阵门"}, {"w": "电门", "t": ""}, {"w": "阀门", "t": ""}, {"w": "闸门", "t": ""}]}, {"meaning": "门径;诀窍。", "cites": [{"t": "事君而不二兮,迷不知宠之门。", "b": "《楚辞·九章》"}], "words": [{"w": "窍门", "t": "能解决困难问题的好方法"}, {"w": "这件事有门了", "t": ""}]}, {"meaning": "家;家族。", "cites": [{"t": "汝勿妄语,灭吾门也。", "b": "《三国志·先主传》"}, {"t": "至蔺相如门。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "还兄门。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "可怜光采生门户。", "b": "白居易《长恨歌》"}], "words": [{"w": "门闾", "t": "指家门"}, {"w": "门中", "t": "指家族中;称族中已亡者"}, {"w": "门功", "t": "祖先世代的功劳"}, {"w": "门地", "t": "家世地位。即门第"}, {"w": "门庇", "t": "先人的庇荫"}, {"w": "门法", "t": "家法。"}]}, {"meaning": "学术思想或宗教的派别。", "cites": [{"t": "孔门之徒。", "b": "《论衡·问孔》"}], "words": [{"w": "佛门", "t": ""}, {"w": "教门", "t": ""}, {"w": "门徒", "t": ""}]}, {"meaning": "守门。", "cites": [{"t": "宋师败绩,公伤股,门官歼焉。", "b": "《左传·僖公二十二年》"}], "words": [{"w": "门敬", "t": "送给看门人的财物"}, {"w": "门皂", "t": "旧时衙门口值守的差役"}, {"w": "门公", "t": "守门的老头"}, {"w": "宅门", "t": "深宅大院的大门"}, {"w": "门正", "t": "掌管城门关闭及出入的人"}, {"w": "门吏", "t": "守门的小官员。"}]}, {"meaning": "攻门。", "cites": [{"t": "偪阳人启门,诸侯之士门焉。", "b": "《左传·襄公十年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('56wx','丫','1','yā','丨','3','','[{"pinyin": "yā", "defs": [{"meaning": "(象形。本义:树木或物体的分叉)。"}, {"meaning": "同本义。", "cites": [{"t": "丫,象物开之形。", "b": "《广韵》。按,这是中古所造的字。泛指上端分出的东西。"}, {"t": "十个指头八个丫。", "b": "《五灯会元》"}], "words": [{"w": "丫叉", "t": "树木两枝分歧处;两手交叉"}, {"w": "丫子", "t": "物体分叉的地方"}, {"w": "丫木", "t": "上端分叉的木头"}, {"w": "丫枝", "t": "枝桠"}, {"w": "丫钯", "t": "叉草用的农具"}, {"w": "丫槎", "t": "丫叉,植物的枝丫"}, {"w": "丫路", "t": "叉路。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('57wx','义','1','yí yì','丶','3','','[{"pinyin": "yí", "defs": [{"meaning": "(“仪”的古字)。"}, {"meaning": "仪容;状貌。", "cites": [{"t": "義,已之威仪也。", "b": "《说文》"}, {"t": "说有义德之美也。", "b": "《贾子道德》"}, {"t": "尚考大室之义。", "b": "《书·大传》"}, {"t": "署行义。", "b": "《汉书·高帝纪》。注:“行状年纪也。”"}], "words": [{"w": "义淫", "t": "威仪隆盛"}, {"w": "义节", "t": "仪节"}, {"w": "义台", "t": "古行礼义之台。"}]}]}, {"pinyin": "yì", "defs": [{"meaning": "(会意。从我,从羊。“我”是兵器,又表仪仗;“羊”表祭牲。本义:正义;合宜的道德、行为或道理)。"}, {"meaning": "同本义。", "cites": [{"t": "义固不杀人。", "b": "《墨子·公输》"}, {"t": "义不杀少。", "b": ""}, {"t": "生,亦我所欲也,义,亦我所欲也,二者不可得兼,舍生而取义者也。", "b": "《孟子·告子上》"}, {"t": "引喻失义。", "b": "诸葛亮《出师表》"}, {"t": "度义而后动。", "b": "宋·王安石《答司马谏议书》"}, {"t": "燕赵之君,始有远略,能守其土,义不赂秦。(义,坚持正义。)", "b": "宋·苏洵《六国论》"}], "words": [{"w": "丈义", "t": "主持正义"}, {"w": "义断恩绝", "t": "恩情道义断绝"}, {"w": "义不容辞", "t": "道义上不容推辞。"}]}, {"meaning": "情谊。", "cites": [{"t": "违情义。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "无情无义;忘恩负义;义义合合", "t": "团结和睦"}, {"w": "义让", "t": "为顾及情谊而相让"}, {"w": "义友", "t": "结义或聚义的友辈"}, {"w": "义兄弟", "t": "结义的兄弟"}, {"w": "义气", "t": "为情谊而甘愿替别人承担风险或作自我牺牲的气度。"}]}, {"meaning": "意义;意思。", "cites": [{"t": "见义远。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "词义", "t": ""}]}, {"meaning": "名义上的。", "cites": [{"t": "隐士赵逸,来至京师,汝南王拜为义父。", "b": "《洛阳伽蓝记》"}], "words": [{"w": "义子", "t": "非亲生之子,而认作父子或母子关系"}, {"w": "义父", "t": "经拜认为父。非亲生之父,即干爹,假父。"}]}, {"meaning": "善;美。", "cites": [{"t": "宣昭义问。", "b": "《诗·大雅·文王》"}], "words": [{"w": "义问", "t": "善声;美好的声誉"}, {"w": "义荣", "t": "由于修身立德而自然具有的荣誉"}, {"w": "义心", "t": "常存节义的心境。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('58wx','之','1','zhī','丶','3','','[{"pinyin": "zhī", "defs": [{"meaning": "(会意。象艸过屮。枝茎益大。本义:出,生出,滋长)。"}, {"meaning": "同本义。", "cites": [{"t": "之,出也。象艸过屮,枝茎益大有所之,一者,地也。", "b": "《说文》"}, {"t": "如语焉而未之然。", "b": "《礼记》。俞樾平议:“此之字乃其本义。未之者,未出也。”"}]}, {"meaning": "往,朝某方向走,到…去。", "cites": [{"t": "之,适也。", "b": "《广雅》"}, {"t": "自伯之东。", "b": "《诗·卫风·伯兮》"}, {"t": "之沛公军。", "b": "《史记·项羽本纪》"}, {"t": "之虚所卖之。(“虚”同“墟”)", "b": "唐·柳宗元《童区寄传》"}, {"t": "佯狂不知所之者。", "b": "明·张溥《五人墓碑记》"}, {"t": "吾欲之南海,何如?", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "之如", "t": "前往"}, {"w": "之往", "t": "去;到"}, {"w": "之官", "t": "上任;前往任所"}, {"w": "之国", "t": "前往封地"}, {"w": "之适", "t": "前往。"}]}, {"meaning": "指示人或事物,相当于“这个”“那个”。", "cites": [{"t": "宣王说之。(之:指南郭处士来吹竽。)", "b": "《韩非子·内储说上》"}, {"t": "虎因喜,计之曰。(之:这,指上文所说驴生了气只能踢的情况。)", "b": "唐·柳宗元《三戒》"}, {"t": "当分明记之。(之:指共读情景。)", "b": "清·袁枚《祭妹文》"}, {"t": "为之,则难者亦易矣。(之:代词,指天下事。)", "b": "清·彭端淑《为学一首示子侄》"}]}, {"meaning": "指代人或事物的名称,相当于他、她、它、他们。", "cites": [{"t": "郑商人弦高将市于周,遇之。", "b": "《左传·僖公三十二年》"}]}, {"meaning": "又。", "cites": [{"t": "蹇叔哭之。", "b": ""}, {"t": "巫医乐师百工之人。(“之”是指示代词,指代“巫医乐师百工”。)", "b": "唐·韩愈《师说》"}], "words": [{"w": "取而代之", "t": ""}, {"w": "战而胜之", "t": ""}, {"w": "为之感叹", "t": ""}, {"w": "使之顺利发展", "t": ""}, {"w": "与之见面", "t": ""}]}, {"meaning": "指示代词,相当于“其”、“他的”、“其他的”。", "cites": [{"t": "纣王令推上法场,斩之老母。", "b": "《武王伐纣平话》"}]}, {"meaning": "的。"}, {"meaning": "用在定语和中心词之间,表示领属关系或一般的修饰关系。", "cites": [{"t": "谢庄少年之精技击者。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "开火者,军中发枪之号也。", "b": ""}], "words": [{"w": "钟鼓之声", "t": ""}, {"w": "一家之长", "t": ""}, {"w": "原因之一", "t": ""}, {"w": "夫子之文章", "t": ""}]}, {"meaning": "用于主谓结构之间,取消句子的独立性。", "cites": [{"t": "吾见师之出。", "b": "《左传·僖公三十二年》"}]}, {"meaning": "用于实词与介词之间。", "cites": [{"t": "口之于味,有同耆也。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('59wx','尸','1','shī','尸','3','','[{"pinyin": "shī", "defs": [{"meaning": "(象形。小篆字形,屍像卧着的人形。本义:祭祀时代表死者受祭的人)。"}, {"meaning": "同本义。", "cites": [{"t": "尸,神像也。象卧之形。", "b": "《说文》。按,凭几曰卧。"}, {"t": "神具醉止,皇尸载起。鼓钟送尸,神保聿归。", "b": "《诗·小雅·楚茨》"}, {"t": "祝延尸。", "b": "《仪礼·士虞礼》。注:“尸,主也。孝子之祭不见亲之形,象心无所系,立尸而主意焉。又,男,男尸;女,女尸,必使异姓,不使贱者。”"}, {"t": "孙可以为王父尸。", "b": "《礼记·曲礼》"}, {"t": "尸,所祭者之孙也。祖之尸则主人乃宗子。祢之尸则主人乃父道。", "b": "《仪礼·特牲礼》注"}]}, {"meaning": "神主牌,以木为之。", "cites": [{"t": "载尸集战何所急。", "b": "《楚辞·天问》"}], "words": [{"w": "载尸以行", "t": "载着神主牌而行。"}]}, {"meaning": "陈尸示众,陈列。", "cites": [{"t": "尸,陈也。", "b": "《说文》"}, {"t": "有母之尸饔。", "b": "《诗·小雅·祈父》"}, {"t": "尸之为言失也,陈也,失气亡陈,形体独陈。", "b": "《白虎通·崩薨》"}, {"t": "楚武王刑尸。", "b": "《左传·庄公四年》"}, {"t": "夫却昭子…其身尸于朝,其宗灭于绛。", "b": "《国语·晋语》"}], "words": [{"w": "尸谏", "t": "陈尸以谏。"}]}, {"meaning": "立神像或神主。", "cites": [{"t": "子胡不相与尸而祝之,社而稷之乎?", "b": "《庄子》"}]}, {"meaning": "担任;承担。", "cites": [{"t": "康王既尸天子,遂诰诸侯,作《康王之诰》。", "b": "《书·康王之诰序》"}]}, {"meaning": "执掌,主持。", "cites": [{"t": "谁其尸之?有齐季女。", "b": "《诗·召南·采蘋》"}], "words": [{"w": "尸盟", "t": "主持盟会"}, {"w": "尸祭", "t": "主祭。"}]}, {"meaning": "在其位而无所作为。", "cites": [{"t": "夫子立而天下治,而我犹尸之。", "b": "《庄子·逍遥游》"}], "words": [{"w": "尸位旷职", "t": "占据职位而不做事"}, {"w": "尸玩", "t": "玩忽职守"}, {"w": "尸素", "t": "居位食禄而不尽职"}, {"w": "尸禄素餐", "t": "空食俸禄而不尽其职,无所事事"}, {"w": "尸职", "t": "尸位,失职"}, {"w": "尸居", "t": "安居而无为。"}]}, {"meaning": "列阵。", "cites": [{"t": "四年春天三月,楚武王荆尸。", "b": "《左传·宣公十二年》"}]}, {"meaning": "尸体。", "cites": [{"t": "屍,终主也。从尸,从死。", "b": "《说文》。按,从死,尸声。许误也。"}, {"t": "以其屍与之。", "b": "《史记·周公世家》"}, {"t": "在床曰尸。", "b": "《礼记·曲礼》"}, {"t": "魂去尸长留。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "既而得其尸于井。", "b": "《聊斋志异·促织》"}], "words": [{"w": "验尸;五马分尸;尸灵", "t": "尸首;灵柩"}, {"w": "尸格", "t": "尸单。验尸单"}, {"w": "尸以祝之", "t": "立尸而祝祷之,表示崇敬"}, {"w": "尸皮子", "t": "尸皮。对衣服的贬称"}, {"w": "尸灵横骨", "t": "方言。尸体"}, {"w": "借尸还魂;尸车", "t": "载尸柩的车子"}, {"w": "尸身", "t": "尸体"}, {"w": "尸丧", "t": "尸体失落"}, {"w": "尸葬", "t": "埋葬尸体。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('60wx','己','1','jǐ','己','3','','[{"pinyin": "jǐ", "defs": [{"meaning": "(象形。甲骨文字形,象绳曲之形。“己”是古“纪”字,假借作“自己”用。①本义:丝的头绪,用以缠束丝。②自己) 自己,本人。", "cites": [{"t": "知己知彼,百战不殆。", "b": "《孙子兵法》"}, {"t": "而己亦人也。", "b": "《吕氏春秋·察今》"}, {"t": "自拟己头。", "b": "晋·干宝《搜神记》"}, {"t": "且噬己也。", "b": "唐·柳宗元《三戒》"}, {"t": "不以己悲。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "在己为有悔。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "舍己为公", "t": ""}, {"w": "异己", "t": ""}, {"w": "克己", "t": ""}, {"w": "知己", "t": ""}, {"w": "己身", "t": "自己"}, {"w": "己私", "t": "自己的欲望"}, {"w": "己里钱", "t": "血汗钱,私房钱。"}]}, {"meaning": "天干的第六位。", "cites": [{"t": "己与三相近。", "b": "《吕氏春秋·慎行论》"}], "words": [{"w": "甲乙丙丁戊己庚辛壬癸", "t": ""}]}, {"meaning": "借作“给”。", "cites": [{"t": "一二千两银子东西己人!叫他唱二万出戏我看了,己他一个!", "b": "《醒世姻缘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('61wx','已','1','yǐ','己','3','','[{"pinyin": "yǐ", "defs": [{"meaning": "(象形。象蛇形。一说原与“子”同字。本义:停止)。"}, {"meaning": "同本义。", "cites": [{"t": "鸡鸣不已。", "b": "《诗·郑风·风雨》。传:“已,止也。”"}, {"t": "德音不已。", "b": "《诗·小雅·南山有台》。传:“已,止也。”"}, {"t": "以故事得已。", "b": "《史记·项羽本纪》"}, {"t": "操蛇之神闻之,惧其不已也,告之于帝。", "b": "《列子·汤问》"}, {"t": "是亦不可以已乎?", "b": "《孟子·告子上》"}, {"t": "累寸不已,遂成丈匹。", "b": "《后汉书·列女传》"}, {"t": "非夫人之物而强假焉,必虑人逼取,而惴惴焉,摩玩之不已。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "不已", "t": ""}]}, {"meaning": "完成,完毕。", "cites": [{"t": "已,成也。", "b": "《广雅》"}, {"t": "已事遄往。", "b": "《易·损》。注:“竟也。”"}, {"t": "且曰吾已。", "b": "《左传·昭公十三年》。注:’犹决竟也。”"}, {"t": "有司已于事而竣。", "b": "《国语·齐语》。注:“毕也。”"}], "words": [{"w": "已矣", "t": "完了,逝去。"}]}, {"meaning": "治愈。", "cites": [{"t": "已大风、挛踠、瘘疠治愈大风、挛踠、瘘、疠(等重病)。大风,麻风病。挛踠,手脚弯曲不能伸展。瘘,脖子肿。疠,恶疮]。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "已经 ——表示动作变化达到的程度。", "cites": [{"t": "北向不能得日,日过午已昏。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "已装不卸", "t": "喻已成定局,无法改变。"}]}, {"meaning": "太 ——表示程度。", "cites": [{"t": "无已大康,职思其居。", "b": "《诗·唐风》"}, {"t": "死而湮没不足道者,亦已众矣。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "又 ——表示行为的频率。", "cites": [{"t": "周子居常云:“吾时月不见黄叔度,则鄙吝之心已复生矣。”", "b": "《世说新语》"}]}, {"meaning": "最终,终归。", "cites": [{"t": "其所以贯理焉,虽亿万已不足以浃万物之变。", "b": "《荀子》"}]}, {"meaning": "已而,然后。", "cites": [{"t": "庭中始为篱,已为墙。", "b": "明·归有光《项脊轩志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('62wx','巳','1','sì','巳','3','','[{"pinyin": "sì", "defs": [{"meaning": "(象形。甲骨文字形,像在胎包中生长的小儿。本义:在胎包中成长的小儿)。"}, {"meaning": "同本义。", "cites": [{"t": "巳,似也。象子在包中形,包字从之。—朱骏声《说文通训定声》", "b": ""}, {"t": "巳则生已定也。", "b": "《淮南子·天文》"}]}, {"meaning": "地支的第六位。"}, {"meaning": "与天干相配,用以纪年。如一九四一年为农历辛巳年。"}, {"meaning": "用以纪月,即农历四月。"}, {"meaning": "十二生肖属蛇。", "cites": [{"t": "巳,火也,其禽蛇也。", "b": "《论衡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('63wx','弓','1','gōng','弓','3','','[{"pinyin": "gōng", "defs": [{"meaning": "(象形。甲骨文字形,象弓形,有弓背和弓弦,后省去弓弦,只剩下弓背,隶变后变成现在的“弓”字。“弓”是汉字部首之一,从“弓”的字多与“弓箭”有关系。本义:射箭或打弹的器械)。"}, {"meaning": "同本义。", "cites": [{"t": "弓,兵也,所以发矢。", "b": "《说文》"}, {"t": "弓,揉木而弦之以发矢。", "b": "《正字通》"}, {"t": "带长剑兮挟秦弓,首身离兮心不惩。", "b": "《楚辞·九歌·国殇》"}, {"t": "良冶之子,必学为裘;良弓之子,必学为箕。", "b": "《礼记·学记》"}, {"t": "毋弛而弓,一栖两雄。", "b": "《韩非子·扬权》"}, {"t": "胡人不敢南下而牧马,士不敢弯弓而报怨。", "b": "汉·贾谊《过秦论》"}, {"t": "行人弓箭各在腰。", "b": "唐·杜甫《兵车行》"}, {"t": "一代天骄,成吉思汗,只识弯弓射大雕。", "b": "毛泽东《沁园春·雪》"}], "words": [{"w": "弓手", "t": "亦作“弓箭手”。宋元时州县统辖的负责巡逻、缉捕的兵卒"}, {"w": "弓壶", "t": "有“弓”字铭文的酒器;装弓的袋"}, {"w": "弓号", "t": "弓"}, {"w": "弓剑", "t": "弓与剑"}, {"w": "弓箕", "t": "弓和箕。喻指世传的家业技艺。"}]}, {"meaning": "形状或作用像弓的器具。", "cites": [{"t": "忽然翻出一双绣花的弓鞋来。", "b": "《范爱农》"}, {"t": "剑花寒不落,弓月晓逾明。", "b": "《乐府诗集·隋·明余庆·军行》"}], "words": [{"w": "弹弓;胡琴弓;弓小", "t": "弓形而纤小"}, {"w": "弓弯", "t": "弓鞋。指缠脚妇女穿的鞋。"}]}, {"meaning": "丈量土地的器具,用木制成,形状似弓 ,两端距离是五尺,也叫步弓。", "cites": [{"t": "侯道五十弓。", "b": "《仪礼·乡射礼记》"}, {"t": "丈地弓制不真,责之弓手。", "b": "清·黄六鸿《清文部·责经手》"}], "words": [{"w": "弓手", "t": "古代丈量地亩持步弓的人。"}]}, {"meaning": "丈量土地的计量单位,一弓为五尺、三百六十弓为一里。", "cites": [{"t": "自冢至麓,凡二百弓。", "b": "唐·陆龟蒙《送小鸡山樵人序》"}], "words": [{"w": "弓口", "t": "尺寸。弓:丈量土地的计量单位。"}]}, {"meaning": "弯曲,引申为弯身,指行礼。", "cites": [{"t": "据唐·段成式《酉阳杂俎·诺皋记》载,谓有士人醉卧,见妇人踏歌曰:“舞袖弓腰浑忘却,蛾眉空带九秋霜。”其中双鬟者问如何是弓腰?歌者笑曰:“汝不见我作弓腰乎?”乃返首髻及地,腰势如规", "b": ""}], "words": [{"w": "弓腰人", "t": "古指舞伎"}, {"w": "弓身", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('64wx','子','1','zǐ zì','子','3','','[{"pinyin": "zǐ", "defs": [{"meaning": "(象形。甲骨文字形,象小儿在襁褓中,有头、身、臂膀,两足象并起来的样子。“子”是汉字的一个部首。本义:婴儿)。"}, {"meaning": "同本义。", "cites": [{"t": "子,十一月阳气动,万物滋,人以为偁。象形。古文从巛,象发也。籀文从囟,有发、臂、胫,在几上也。", "b": "《说文》。按,象儿在襁褓中足倂也。"}, {"t": "子,子息。", "b": "《广韵》"}, {"t": "居然生子。", "b": "《诗·大雅·生民》"}, {"t": "子也者,亲之后也。", "b": "《礼记·哀公问》"}, {"t": "子者,父之合也。", "b": "《春秋繁露基义》"}, {"t": "子者,父之阴也。", "b": "《汉书·杜钦传》"}, {"t": "干、越、夷、貉之子,生而同声,长而异俗。”", "b": "《荀子》"}], "words": [{"w": "子衣", "t": "小儿的胎衣。"}]}, {"meaning": "儿女。古人称子兼男女。", "cites": [{"t": "孀妻弱子。", "b": "《列子·汤问》"}, {"t": "有子存焉。", "b": ""}, {"t": "孙又生子。", "b": ""}, {"t": "子墨衰绖。(晋襄公的丧服都染成黑色。子,指晋襄公。墨,动词,染黑。衰,通縗,丧服,粗麻布做成。绖,头巾和腰带。)", "b": "《左传·僖公三十三年》"}], "words": [{"w": "子党", "t": "儿女辈"}, {"w": "子道", "t": "儿女对父母应遵循的道德规范"}, {"w": "子姓", "t": "泛指子孙,后辈"}, {"w": "子辈", "t": "儿女。"}]}, {"meaning": "今则专指儿子,即某人直系血统的下一代男性。", "cites": [{"t": "无子,有女二人。", "b": "唐·陈玄祐《离魂记》"}], "words": [{"w": "子姪", "t": "本指子与姪。后用以通称晚辈"}, {"w": "子胤", "t": "子息,后嗣"}, {"w": "子父", "t": "父和子"}, {"w": "子母", "t": "母和子"}, {"w": "子客", "t": "儿子的宾客。"}]}, {"meaning": "子孙。"}, {"meaning": "通常指晚辈直系或旁系血亲。", "cites": [{"t": "圣王之子也,有天下之后也,执籍之所在也,天下之宗室也。", "b": "《荀子·正论》"}]}, {"meaning": "系另一人或一个共同世系的后裔;后代。", "cites": [{"t": "我本汉家子,将适单于庭。", "b": "石崇《王昭君辞》"}]}, {"meaning": "人的通称。", "cites": [{"t": "招招舟子,人涉卬否?", "b": "《诗·邶风·匏有苦叶》"}], "words": [{"w": "樵子", "t": ""}, {"w": "舟子", "t": ""}, {"w": "子马", "t": "人马"}, {"w": "子童", "t": "后妃或仙女的自称"}, {"w": "孤子", "t": "年少死了父亲的人"}, {"w": "才子", "t": "特别具有才华的人"}, {"w": "女子", "t": "女性"}, {"w": "小子", "t": "年幼的人;晚辈"}, {"w": "内子", "t": "内人,即妻子"}, {"w": "夫子", "t": "旧时对学者的称呼;旧时学生称老师"}, {"w": "孝子", "t": "对父母十分孝顺的人"}, {"w": "游子", "t": "离乡在外或久居外乡的人。"}]}, {"meaning": "中国古代士大夫的通称。", "cites": [{"t": "诸侯之上大夫卿、下大夫、上士、中士、下士凡五等。亦称“子”,若宣子、武子之类是也。", "b": "赵彦卫《云麓漫钞》"}]}, {"meaning": "中国古代对男子的通称。", "cites": [{"t": "子年少。", "b": "晋·干宝《搜神记》"}, {"t": "而独不足子所乎。", "b": "明·刘基《卖柑者言》"}, {"t": "子之说。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "子不闻藏书者乎?", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "古人对自己老师的称呼。", "cites": [{"t": "子曰:学而时习之。", "b": "《论语》"}, {"t": "子墨子闻之。", "b": "《墨子·公输》"}, {"t": "子墨子解带为城。", "b": ""}]}, {"meaning": "地支的第一位。"}, {"meaning": "与天干相配,用以纪年。", "cites": [{"t": "太岁在子日困敦。", "b": "《尔雅》"}]}, {"meaning": "用以纪月,即农历十一月。", "cites": [{"t": "子,又以纪月。", "b": "朱骏声《说文通训定声·颐部》"}]}, {"meaning": "用以纪日。", "cites": [{"t": "不辟子卯。", "b": "《仪礼·士丧礼》"}]}, {"meaning": "用以纪时,即夜半十一时至一时。", "cites": [{"t": "子时得阳气,而丑则鸡鸣。", "b": "《西游记》"}]}, {"meaning": "子夜。"}, {"meaning": "专指女儿。", "cites": [{"t": "缵女维莘,长子维行。", "b": "《诗·大雅·大明》。毛传:“长子,长女也。”"}, {"t": "曹丞相因念令先君是绝代儒宗,夫人是名公爱子,不忍埋没这白草黄云之外。", "b": "明·陈与郊《文姬入塞》"}], "words": [{"w": "子媳", "t": "女媳。"}]}, {"meaning": "加在姓氏或数词后面作为对人的尊称。", "cites": [{"t": "此三子者。", "b": "《战国策·魏策》"}, {"t": "非郑尹而快孙子。", "b": "唐·柳宗元《柳河东集》"}, {"t": "程氏子以蠹贫。", "b": "《聊斋志异·促织》"}]}, {"meaning": "小。", "cites": [{"t": "时大武军子将郝灵荃奉使在突厥。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "子将", "t": "小将"}, {"w": "子舍", "t": "小房"}, {"w": "子闩", "t": "小门闩"}, {"w": "子墙", "t": "院落内部的小墙"}, {"w": "子亭", "t": "小亭"}, {"w": "子城", "t": "大城所属的小城。"}]}, {"meaning": "幼小。", "cites": [{"t": "郫县子鱼,黄鳞赤尾。", "b": "曹操《四时食制》"}], "words": [{"w": "子鸭", "t": "幼鸭,嫩鸭"}, {"w": "子鸡", "t": "小而嫩的鸡。"}]}, {"meaning": "爱;尤指像对子女一样地爱护。", "cites": [{"t": "天迪从子保。", "b": "《书·召诰》。王引之云:“子,当读为慈。”"}, {"t": "子以爱之。", "b": "《礼记·缁衣》"}, {"t": "封建者,必私其土,子其人。", "b": "唐·柳宗元《封建论》"}], "words": [{"w": "子谅", "t": "慈爱诚信"}, {"w": "子惠", "t": "惠爱百姓"}, {"w": "子育", "t": "抚爱养育如己子。"}]}, {"meaning": "收养为子。", "cites": [{"t": "完母死,庄公令夫人齐女子之,立为太子。", "b": "《史记·卫康叔世家》"}]}, {"meaning": "结果实。", "cites": [{"t": "李性坚,实脱(晚),五岁者始子。", "b": "《齐民要术·种李》注"}]}, {"meaning": "尽儿女之道;善事父母。", "cites": [{"t": "君君,臣臣,父父,子子。", "b": "《论语》"}]}, {"meaning": "表示限制,相当于“只”。", "cites": [{"t": "睡不稳,子倚着个鲛绡枕头儿盹。", "b": "《西厢记诸宫调》"}, {"t": "也子强如你,但衣食。", "b": "《刘知远诸官调·正宫锦·缠道》"}, {"t": "子喝一声,那时唬煞。", "b": "董解元《西厢记诸宫调》"}], "words": [{"w": "子有", "t": "只有"}, {"w": "子索", "t": "只得;只索。"}]}, {"meaning": "相当于“虽然”。", "cites": [{"t": "老子老呵,犹兀自万夫难敌。", "b": "杨梓《敬德不服老》"}], "words": [{"w": "有子有", "t": "有虽然是有;虽则有。"}]}, {"meaning": "你——尊称对方,通常为男性。", "cites": [{"t": "陈亢问于伯鱼曰:“子亦有异闻乎?”", "b": "《论语》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zì", "defs": [{"meaning": "构词后缀。"}, {"meaning": "加在动词或形容词词素后。", "words": [{"w": "胖子", "t": ""}, {"w": "瘦子", "t": ""}, {"w": "垫子", "t": ""}]}, {"meaning": "个别量词后缀。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('65wx','卫','1','wèi','卩','3','','[{"pinyin": "wèi", "defs": [{"meaning": "(会意。从韋币从行。甲骨文中“卫、韦”同字。意思是在大道(行)站岗保卫(韦)。本义:保卫;防护)。"}, {"meaning": "同本义。", "cites": [{"t": "卫,宿卫也。", "b": "《说文》"}, {"t": "卫护也。", "b": "《玉篇》"}, {"t": "以卫王宫。", "b": "《战国策·赵策》"}, {"t": "备一夕之卫。", "b": "《左传·僖公三十二年》"}, {"t": "然侍卫之臣不懈于内。", "b": "诸葛亮《出师表》"}], "words": [{"w": "卫籍", "t": "军籍"}, {"w": "守卫", "t": "防守保卫"}, {"w": "自卫", "t": "保卫自己"}, {"w": "捍卫", "t": "保卫"}, {"w": "卫守", "t": "保卫防守"}, {"w": "卫助", "t": "保卫协助"}, {"w": "卫足", "t": "比喻自全或自卫"}, {"w": "卫侍", "t": "保卫侍奉"}, {"w": "卫社", "t": "保卫国家"}, {"w": "保家卫国;卫卒", "t": "护卫的兵卒"}, {"w": "卫养", "t": "保护安抚"}, {"w": "卫从", "t": "护卫侍从"}, {"w": "卫蔽", "t": "卫护遮掩。"}]}, {"meaning": "谋求。", "cites": [{"t": "有货,以卫身也。", "b": "《国语·鲁语下》"}]}, {"meaning": "担任卫护、防守之职的人。", "cites": [{"t": "文公之入也无卫,故有吕、却之难。", "b": "《左传》"}]}, {"meaning": "周代京师以外的行政区域之一。", "cites": [{"t": "过了半年,松潘卫边外生番与内地民人互市,因买卖不公,彼此吵闹起来。", "b": "《儒林外史》"}]}, {"meaning": "驴的别称。", "cites": [{"t": "南中丞卓,吴楚游学十余年,衣布缕,乘牝卫,薄游上蔡。", "b": "《云溪友议》"}]}, {"meaning": "箭羽。", "cites": [{"t": "楚熊渠子出,见寝石,以为伏虎,将弓射之,矢没其卫。", "b": "《论衡·儒增》"}]}, {"meaning": "古国名 。周武王弟康叔封地。至懿公为狄所灭。戴公野处漕邑,文公又徙居楚丘。秦始皇既统一全国,独置卫君,为附庸,至二世元年废。", "cites": [{"t": "之晋过卫。", "b": "《吕氏春秋·慎行论》"}, {"t": "宋、卫、中山。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "边陲,边远的地方。", "cites": [{"t": "侯卫之班,藩服之职。", "b": "《文选》"}]}, {"meaning": "水名 。源出河北省灵寿县东北,南流至县东南,合滹沱河。", "cites": [{"t": "恒、卫既从,大陆既作。", "b": "《书·禹贡》"}]}, {"meaning": "肢体。", "cites": [{"t": "四卫变强。", "b": "《吕氏春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('66wx','也','1','yě','乙','3','','[{"pinyin": "yě", "defs": [{"meaning": "表示选择,还是。", "cites": [{"t": "你见我府里那个门子,却是多少年纪?或是黑瘦也白净肥胖?", "b": "《水浒传》"}], "words": [{"w": "也是", "t": "还是。"}]}, {"meaning": "用在句末表示判断或肯定语气。相当于“啊”、“呀”。", "cites": [{"t": "少时之岁月为可惜也。", "b": "清·袁枚《黄生借书说》"}, {"t": "旋见一白酋…英将也。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "用在句中,表示停顿。", "cites": [{"t": "知幸与不幸,则其读书也必专。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "用在句末,表示疑问,相当于“呢”、“吗”。", "cites": [{"t": "若为佣耕,何富贵也?", "b": "《史记》"}]}, {"meaning": "用在前半句的末了,表示停顿一下,舒缓语气,后半句将对前半句加以解说。对后半句有强调作用。", "cites": [{"t": "于是人也,必先苦其心志…", "b": "《孟子·告子下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('67wx','女','1','nǚ','女','3','','[{"pinyin": "nǚ", "defs": [{"meaning": "(象形。甲骨文字形,象一个敛手跪着的人形。本义:女性, 女人,与“男”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "女,妇人也。", "b": "《说文》。王育说:“对文则处子曰女,适人曰妇。”"}, {"t": "女也不爽,士贰其行。", "b": "《诗·卫风·氓》"}, {"t": "一女不织,或受之寒。", "b": "贾谊《论积贮疏》"}, {"t": "女行无偏斜,何意致不厚。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "男女衣著。", "b": "晋·陶渊明《桃花源记》"}, {"t": "男女无别。", "b": "《韩非子·亡征》"}, {"t": "如倩女之靧。", "b": "明·袁宏道《满井游记》"}, {"t": "男女奔窜。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "女陪堂", "t": "女帮闲"}, {"w": "女先儿", "t": "女先生"}, {"w": "女红", "t": "泛指妇女干的纺织、缝纫、刺绣等"}, {"w": "女冠", "t": "女道士"}, {"w": "女兄", "t": "姐姐"}, {"w": "女伯", "t": "称父亲的姐姐"}, {"w": "女嬖", "t": "受君主宠爱的女人"}, {"w": "女隶", "t": "女官。被没入宫中为奴的女子"}, {"w": "女中丈夫", "t": "女子中有男子气概的人。"}]}, {"meaning": "引申指女儿。", "cites": [{"t": "请句践女女于王。", "b": "《国语·越语》"}, {"t": "窈窕淑女,君子好逑。", "b": "《诗·周南·关睢》"}, {"t": "何氏之女。", "b": "《后汉书·列女传》"}, {"t": "女婉贞。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "不闻爷娘唤女声。", "b": "《乐府诗集·木兰诗》"}]}, {"meaning": "又。", "cites": [{"t": "唯闻女叹息。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "问女何所思。", "b": ""}], "words": [{"w": "子女", "t": ""}]}, {"meaning": "星宿名。二十八宿之一,北方玄武七宿的第三宿。有星四颗。"}, {"meaning": "以女嫁人(此义又读nǜ)。", "cites": [{"t": "宋雍氏女于郑庄公。", "b": "《左传·桓公十一年》"}]}, {"meaning": "像姑娘。", "cites": [{"t": "君子谓宋共姬“女而不妇”。", "b": "《左传》"}]}, {"meaning": "当女奴。", "cites": [{"t": "请勾践女女于王。", "b": "《国语》"}]}, {"meaning": "柔弱。", "cites": [{"t": "猗彼女桑。", "b": "《诗·豳风·七月》"}]}, {"meaning": "雌性的。", "cites": [{"t": "女工作文采,男工作刻镂。", "b": "《墨子·辞过》"}, {"t": "山东河北人谓牡猫为女猫。", "b": "清·顾炎武《日知录》"}]}, {"meaning": "假借为“汝”。你。", "cites": [{"t": "三岁贯女。", "b": "《诗·魏风·硕鼠》"}, {"t": "子曰:由!诲女知之乎?", "b": "《论语·为政》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('68wx','刃','1','rèn','刀','3','','[{"pinyin": "rèn", "defs": [{"meaning": "(指事。小篆字形,在刀上加一点,表示刀锋所在。本义:刀口,刀锋)。"}, {"meaning": "同本义。", "cites": [{"t": "刃,刀坚也。象刀有刃之形。", "b": "《说文》。张舜徽注:“许云象形,而实指事。今俗称刀口。”"}, {"t": "锻乃戈矛,砺乃锋刃。", "b": "《书·费誓》"}, {"t": "延则若莫邪之长刃,婴之者斩。", "b": "《荀子·议兵》"}, {"t": "今臣之刀十九年矣,所解数千牛矣,而刀刃若新发于硎。", "b": "《庄子·养生主》"}], "words": [{"w": "刀刃;迎刃而解", "t": ""}]}, {"meaning": "刀剑一类利器。", "cites": [{"t": "铸金而为刃。", "b": "《淮南子·泛论》"}, {"t": "拔刃奋起,率众袭之。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "杀人以梃与刃,有以异乎?", "b": "《孟子》"}, {"t": "白刃交于前,视死若生者,烈士之勇也。", "b": "《庄子》"}], "words": [{"w": "策马露刃;刃器", "t": "刀剑之类的兵器"}, {"w": "利刃在手", "t": ""}]}, {"meaning": "长度单位。", "cites": [{"t": "浚古千刃。", "b": "《无极山碑》"}]}, {"meaning": "杀死,弄死。", "cites": [{"t": "左右欲刃相如。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "手刃对手", "t": ""}]}, {"meaning": "磨。", "cites": [{"t": "与物相刃相靡,其行尽如驰,而莫之能止。", "b": "《庄子》。闻一多校释:“刃,亦犹磨也。”"}]}, {"meaning": "柔软而坚固。", "cites": [{"t": "服与耜宜用稚材,尚柔刃也。", "b": "《周礼·地官·山虞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('69wx','飞','1','fēi','飞','3','','[{"pinyin": "fēi", "defs": [{"meaning": "(象形。小篆字形,下面象展开的双翼,上面象鸟首。本义:鸟飞)。"}, {"meaning": "同本义。", "cites": [{"t": "飛,鸟翥也。象张翼之形。", "b": "《说文》"}, {"t": "飞鸟遗之音。", "b": "《易·小过》"}, {"t": "明珠弹于飞肉。", "b": "《太玄·唐》。注:“飞肉,禽鸟也。”"}, {"t": "西塞山前白鹭飞,桃花流水鳜鱼肥。", "b": "唐·张志和《渔歌子》"}, {"t": "鸟倦飞而知还。", "b": "晋·陶渊明《归园田居》"}, {"t": "鸢飞戾天者。", "b": "吴均《与朱元思书》"}], "words": [{"w": "飞凫", "t": "飞翔的凫鸟"}, {"w": "飞翰", "t": "飞翔的小鸟"}, {"w": "飞鸿", "t": "飞翔中的鸿雁。"}]}, {"meaning": "泛指飞翔。", "cites": [{"t": "飞龙在天。", "b": "《易·乾》"}, {"t": "彗孛飞流。", "b": "《汉书·天文志》。注:“绝迹而去也。”"}], "words": [{"w": "飞虫", "t": "能飞的昆虫类"}, {"w": "飞蝗", "t": "指善飞的蝗虫"}, {"w": "飞鱼钩", "t": "叉鱼的钩子。"}]}, {"meaning": "物体随风在空中飘游浮荡。", "cites": [{"t": "桃李阴阴柳絮飞。", "b": "唐·王维《酬部给事》"}, {"t": "胡天八月即飞雪。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "茅飞渡江洒江郊。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "樯橹灰飞烟灭。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "飞絮", "t": "空中飘摇的柳絮"}, {"w": "飞天光棍", "t": "手段高强的地痞无赖"}, {"w": "飞火", "t": "爆竹的声音与火光"}, {"w": "飞星", "t": "流星般迅疾。"}]}, {"meaning": "矿物药或颜料,研成细末,置于水中以漂去其浮于水面的粗屑。", "cites": [{"t": "这些颜色,咱们淘澄飞跌着。", "b": "《红楼梦》"}]}, {"meaning": "疾速。", "cites": [{"t": "万里赴戎机,关山度若飞。", "b": "《乐府诗集·木兰诗》"}, {"t": "一夜飞渡镜湖月。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "飞风", "t": "迅速;飞快"}, {"w": "飞云掣电", "t": "形容迅疾"}, {"w": "飞骑", "t": "像飞一般奔驰的马"}, {"w": "飞报", "t": "迅速报告"}, {"w": "飞递", "t": "迅速递送"}, {"w": "飞札", "t": "飞速写成的信件或诗笺。"}]}, {"meaning": "没有根据的。", "cites": [{"t": "乃悬飞书诽谤,下狱死。", "b": "《后汉书·梁松传》"}], "words": [{"w": "飞飞扬扬", "t": "议论纷纷"}, {"w": "飞扎", "t": "凭空陷害;敲诈勒索"}, {"w": "飞言", "t": "没有根据的话。同飞语、蜚语、流言。"}]}, {"meaning": "不具姓名的。", "cites": [{"t": "飞书者,无根而至若飞来也。", "b": "《后汉书·梁松传》注"}], "words": [{"w": "飞书", "t": "不具姓名的书信。即匿名信"}, {"w": "飞章", "t": "不具姓名而诬害他人的书信。同飞书"}, {"w": "飞条", "t": "匿名信。同飞书。"}]}, {"meaning": "凌空,高。", "cites": [{"t": "燕巢于飞幕之上。", "b": "丘迟《与陈伯之书》"}], "words": [{"w": "飞陛", "t": "高耸的台阶"}, {"w": "飞观", "t": "飞阁,高耸的楼观。"}]}, {"meaning": "肌肉丰满。", "cites": [{"t": "文君为我端著兮,利飞遁以保名。", "b": "《后汉书·张衡传》"}, {"t": "飞遁离俗。", "b": "曹植《七启》"}]}, {"meaning": "奔驰的马。", "cites": [{"t": "今陛下骋六飞,驰不测山。", "b": "《汉书》。颜师古注引如淳曰:六马之疾若飞也。"}]}, {"meaning": "飞星,流星的一种。", "cites": [{"t": "彗孛飞流。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('70wx','习','1','xí','乙','3','','[{"pinyin": "xí", "defs": [{"meaning": "(会意。从羽 。从羽,与鸟飞有关。本义:小鸟反复地试飞)。"}, {"meaning": "同本义。", "cites": [{"t": "習,数飞也。", "b": "《说文》"}, {"t": "鹰乃学习。", "b": "《礼记·月令》"}, {"t": "习习笼中鸟,举翮触四隅。", "b": "晋·左思《咏史》"}]}, {"meaning": "反覆练习,钻研。", "cites": [{"t": "君子以朋友讲习。", "b": "《易·象下传》"}, {"t": "是皆习民数者也。", "b": "《国 语·周语》。注;“习,简习也。”"}, {"t": "学而时习之,不亦说乎?", "b": "《论语·学而》。皇侃义疏:“习是修故之称也。言人不学则已,既学必因仍而修习,日夜无替也。”"}], "words": [{"w": "习容", "t": "练习举止,整饬仪表"}, {"w": "习肄", "t": "犹练习"}, {"w": "习战", "t": "练习作战"}, {"w": "习非胜是", "t": "对错误的事物相习既久,无法矫正,反以为是。"}]}, {"meaning": "通晓,熟悉。", "cites": [{"t": "不习于诵。", "b": "《战国策·秦策》"}, {"t": "谁习计会,能为文收责于薛者乎?", "b": "《战国策》"}, {"t": "皆通习之。", "b": "唐·韩愈《师说》"}, {"t": "益习其声。", "b": "唐·柳宗元《三戒》"}, {"t": "不习水战。", "b": "《资治通鉴》"}, {"t": "习见习闻。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "习方俗", "b": ""}], "words": [{"w": "习流", "t": "熟悉水流。又指熟悉水战的兵士"}, {"w": "习士", "t": "熟悉法制的人"}, {"w": "习事", "t": "熟谙事理"}, {"w": "习知", "t": "熟知"}, {"w": "习水", "t": "熟习水性。"}]}, {"meaning": "学习。", "cites": [{"t": "始习于大豆。", "b": "《吕氏春秋·造父》。注:“学也。”"}, {"t": "习其句读。", "b": "唐·韩愈《师说》"}, {"t": "自幼好武术,习无不精。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "习学", "t": "学习"}, {"w": "习文练武", "t": ""}, {"w": "讲习", "t": "讲授与学习"}, {"w": "习业", "t": "攻习学业,钻研学问。"}]}, {"meaning": "习惯;习惯于,习以为常。", "cites": [{"t": "圣人者,明于治乱之道,习于人事之终始者也。", "b": "《管子》"}, {"t": "民习以力攻难,故轻死。", "b": "《商君法·战法》"}, {"t": "人习于苟且非一日。", "b": "王安石《答司马谏议书》"}, {"t": "不习水土。", "b": "《资治通鉴》"}, {"t": "家人习奢。", "b": ""}, {"t": "习于钟鼓。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "习熟", "t": "习惯熟悉"}, {"w": "习闲", "t": "游手好闲者"}, {"w": "习闻", "t": ""}, {"w": "习安", "t": "习惯于安定。"}]}, {"meaning": "训练。", "cites": [{"t": "不习,则民不可使也。", "b": "《大戴礼记》"}], "words": [{"w": "习教", "t": "犹训练"}, {"w": "习勒", "t": "严格训练"}, {"w": "习练", "t": "练习;训练"}, {"w": "习用", "t": "演习"}, {"w": "习兵", "t": "操演军事"}, {"w": "习阵", "t": "演习战阵之事。"}]}, {"meaning": "习染。", "cites": [{"t": "习善而为善,习恶而为恶也。", "b": "《论衡·本性》"}, {"t": "习其家风。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "习性;习惯。", "cites": [{"t": "性相近也,习相远也。", "b": "《论语·阳货》"}, {"t": "政教习俗,相顺而后行。", "b": "《荀子·大略》"}], "words": [{"w": "固习", "t": ""}, {"w": "陋习", "t": ""}, {"w": "恶习", "t": ""}, {"w": "习性", "t": ""}, {"w": "积习", "t": ""}]}, {"meaning": "亲信。", "cites": [{"t": "凡当涂者之于人主也,希不信爱也,又且习故。", "b": "《韩非子·孤愤》"}], "words": [{"w": "习故", "t": "亲近故旧。又指熟悉故旧的人。"}]}, {"meaning": "经常,常常。", "cites": [{"t": "自是日抱就犬,习示之,使勿动。", "b": "柳宗元《三戒》"}, {"t": "车户李旺行了多日,习见匣子沉重,晓得是银子在内。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "习洽", "t": "经常交往,关系密切"}, {"w": "习闻", "t": ""}, {"w": "习用", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('71wx','叉','1','chā chá chǎ chà','又','3','','[{"pinyin": "chā", "defs": [{"meaning": "(指事。小篆为“又”(即手)上加一点,指出叉手的动向。本义:交错,交叉)。"}, {"meaning": "手指相交错。也泛指一般的交错、交叉。", "cites": [{"t": "叉,手指相错也。", "b": "《说文》。段注:“谓手指与物相错也。凡布指错物间而取之曰叉,因之凡岐头皆曰叉。”"}, {"t": "凡八叉手而八韵成。", "b": "《全唐诗话》"}], "words": [{"w": "叉手", "t": ""}]}, {"meaning": "古代的一种兵器,头有分杈。", "cites": [{"t": "红漆了叉。", "b": "元·睢景臣《[般涉调]哨遍·高祖还乡》"}]}, {"meaning": "叉子。", "cites": [{"t": "挺叉来往。", "b": "《文选 ·潘岳·西征赋》。注:“叉,取鱼叉也。”"}], "words": [{"w": "鱼叉;粪叉;叉竿", "t": "带叉头的竿。"}]}]}, {"pinyin": "chá", "defs": [{"meaning": "挡住,卡住。", "cites": [{"t": "那大师傅就叉着门,不叫我们走。", "b": "《儿女英雄传》"}]}]}, {"pinyin": "chǎ", "defs": [{"meaning": "", "words": [{"w": "叉着腿站着;拇指和食指叉成个“八”字", "t": ""}]}]}, {"pinyin": "chà", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('72wx','马','1','mǎ','马','3','','[{"pinyin": "mǎ", "defs": [{"meaning": "(象形。早期金文字形,象马眼、马鬃、马尾之形。“马”是汉字的一个部首。本义:家畜名)。"}, {"meaning": "单蹄食草大型哺乳动物 。史前即为人类所驯化,用作驮畜、挽畜和乘骑;它和其他现存的马属和马科动物的区别是尾毛和鬃毛长,后腿飞节内下方有一块胼胝,还有一些非固定特征(如体型较大,蹄子较大,颈稍呈弓形,头小,耳短)。", "cites": [{"t": "千里马常有,而伯乐不常有。", "b": "韩愈《马说》"}], "words": [{"w": "马伯乐", "t": "相马的人"}, {"w": "马首", "t": "属马的人"}, {"w": "马牌子", "t": "官府养马的伕役,他们身上都挂有腰牌作凭证"}, {"w": "马曹", "t": "官署名。专门管马"}, {"w": "马圈", "t": "养马的地方"}, {"w": "马祭", "t": "祭祀马神"}, {"w": "马绊", "t": "系马用的绳子"}, {"w": "马褐", "t": "马的护衣"}, {"w": "马祸", "t": "马的异象。古代以为灾变之兆"}, {"w": "马图", "t": "传说中龙马背负出水的图。"}]}, {"meaning": "“码”的古字。古代用 以计算的筹码。近世也用以计数。", "cites": [{"t": "为胜者立马。", "b": "《礼记·投壶》"}], "words": [{"w": "马子", "t": "筹码。"}]}, {"meaning": "驾着马。", "cites": [{"t": "裘马过世家。", "b": "《聊斋志异·促织》"}], "words": [{"w": "裘马扬扬", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('73wx','乡','1','xiāng','乙','3','','[{"pinyin": "xiāng", "defs": [{"meaning": "(会意。据甲骨文,像二人对食形。“‘鄉’和‘饗’原本是一字…整个字像两个人相向对坐,共食一簋的情状。本义是用酒食款待别人,是“饗”的古字)。"}, {"meaning": "“乡”假借为行政区域名。", "cites": [{"t": "乡,国离邑民所封乡也。啬夫别治封圻之内六乡六卿治之。", "b": "《说文》"}, {"t": "五州为乡。", "b": "《周礼·大司徒》。注:“万二千五百家。”"}, {"t": "十邑为乡,是三千六百家为一乡。", "b": "《广雅》"}, {"t": "习乡尚齿。", "b": "《礼记·王制》"}, {"t": "行比一乡。", "b": "《庄子·逍遥游》"}, {"t": "其乡人曰:“肉食者谋之,又何间焉?”", "b": "《左传·庄公十年》"}]}, {"meaning": "乡村,城市外的区域。", "cites": [{"t": "传一乡秀才。", "b": "宋·王安石《伤仲永》"}, {"t": "遍捉乡民。", "b": "《广东军务记》"}, {"t": "各乡逆夷", "b": ""}], "words": [{"w": "乡里迓鼓", "t": "泛指民间音乐"}, {"w": "乡曲之誉", "t": "乡里的声望"}, {"w": "乡先生", "t": "辞官居乡或在乡执教的长者"}, {"w": "乡瓜子", "t": "见识少的乡下人。"}]}, {"meaning": "家乡,故乡。在客地称原籍为乡。", "cites": [{"t": "国者,乡之本也。", "b": "《管子·权修》"}, {"t": "登斯楼也,则有去国怀乡,忧谗畏讥,满目萧然,感极而悲者矣。", "b": "范仲淹《岳阳楼记》"}, {"t": "从乡之先达执经叩问。", "b": "明·宋濂《送东阳马生序》"}, {"t": "乡音无改。", "b": "唐·贺知章《回乡偶书》"}, {"t": "采吾乡。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "扣其乡。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "乡心", "t": "思念故乡的心情"}, {"w": "乡味", "t": "家乡饮食的风味"}, {"w": "乡信", "t": "家乡亲友寄来的书信。"}]}, {"meaning": "地方;处所。", "cites": [{"t": "三世居是乡。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "他乡;外乡;异乡;侨乡;帝乡", "t": "京城。"}]}, {"meaning": "用作动词,读xiàng", "cites": [{"t": "东乡坐。", "b": "《史记·田单列传》"}, {"t": "乡师而哭。", "b": "《左传·僖公三十三年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('74wx','丰','1','fēng','丨','4','','[{"pinyin": "fēng", "defs": [{"meaning": "(象形。甲骨文字形,上面象一器物盛有玉形,下面是“豆”(古代盛器)。故“豐”本是盛有贵重物品的礼器。这由“豊”字可以得到证明。古文“豐与“豊”是同一个字,《说文》:“豊,行礼之器也。”本义:古代盛酒器的托盘)。"}, {"meaning": "中国古代礼器,形状像豆,用以承酒觯。", "cites": [{"t": "豐,豆之豐满者也。", "b": "《说文》"}, {"t": "饮酒实于觯,加于丰。", "b": "《仪礼·公食大夫礼》"}]}, {"meaning": "蒲草。", "cites": [{"t": "东序西向,敷重丰席,画纯。", "b": "《书·顾命》"}]}, {"meaning": "地名。"}, {"meaning": "周国都名 。在今陕西省西安市西南。"}, {"meaning": "秦沛县之丰邑,汉置县 。今江苏省徐州市丰县。"}, {"meaning": "草木茂盛。", "cites": [{"t": "豐,茂也,盛也。", "b": "《广韵》"}, {"t": "在彼丰草。", "b": "《诗·小雅·湛露》"}, {"t": "丰殖九薮。", "b": "《国语·周语下》"}, {"t": "韭曰丰本。", "b": "《礼记·曲礼下》"}, {"t": "树木丛生,百草丰茂。", "b": "《乐府诗集·曹操·步出夏门行》"}], "words": [{"w": "丰容", "t": "草木茂盛"}, {"w": "丰彤", "t": "林木茂密的样子"}, {"w": "丰林", "t": "丰茂的林木"}, {"w": "丰荣", "t": "花木繁茂。"}]}, {"meaning": "大;高大。", "cites": [{"t": "丰,大也。", "b": "《易·丰卦》"}, {"t": "欲其丰也。", "b": "《周礼·考工记·函人》"}]}, {"meaning": "又。", "cites": [{"t": "羽丰则迟。", "b": ""}, {"t": "畜义丰功谓之仁。", "b": "《国语·周语中》"}, {"t": "其亦必有丰败也哉!", "b": "《国语·楚语上》"}, {"t": "铭功彝器,纪德丰碑。", "b": "《隋书·杨素传》"}], "words": [{"w": "丰石", "t": "高大的石碑"}, {"w": "丰岸", "t": "大堤"}, {"w": "丰居", "t": "高大的房屋"}, {"w": "丰狐", "t": "大狐狸"}, {"w": "丰祠", "t": "高大的祠堂"}, {"w": "丰堂", "t": "高大的厅堂。"}]}, {"meaning": "丰满;胖。", "cites": [{"t": "第一个肌肤微丰,身材合中。", "b": "《红楼梦》"}], "words": [{"w": "丰肌", "t": "丰润的肌肤"}, {"w": "丰壮", "t": "丰满健壮"}, {"w": "丰洁", "t": "健壮;俊美"}, {"w": "丰致", "t": "美好的容貌和举止。"}]}, {"meaning": "指农作物收成好。"}, {"meaning": "", "cites": [{"t": "稻花香里说丰年。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "丰稔", "t": "庄稼成熟、丰收"}, {"w": "丰歉", "t": "收成好坏"}, {"w": "丰成", "t": "丰收"}, {"w": "丰信", "t": "丰收的音信"}, {"w": "丰索", "t": "年成的好坏"}, {"w": "丰虚", "t": "丰收与荒歉。偏指荒歉。"}]}, {"meaning": "盛多。多指事物的数量。", "cites": [{"t": "不为丰约举。", "b": "《国语·楚语》。注:“盛也。”"}, {"t": "上好贪利,则臣下百吏乘是而后丰取刻与。", "b": "《荀子·君道》"}], "words": [{"w": "丰沛", "t": "盛多的样子"}, {"w": "丰财", "t": "多财"}, {"w": "丰融", "t": "盛多的样子"}, {"w": "丰霈", "t": "盛多的样子"}, {"w": "丰露", "t": "盛多的甘露。"}]}, {"meaning": "丰厚;富裕。", "cites": [{"t": "小人寡欲则能谨身节用,远罪丰家。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "丰利", "t": "丰厚的利益"}, {"w": "丰施", "t": "丰厚的施与"}, {"w": "丰秩", "t": "丰厚的俸禄"}, {"w": "丰禄", "t": "优厚的俸禄"}, {"w": "丰雍", "t": "丰厚雍和。"}]}, {"meaning": "富饶。", "cites": [{"t": "地沃野丰。", "b": "张衡《西京赋》"}], "words": [{"w": "丰阜", "t": "富饶"}, {"w": "丰壤", "t": "肥沃富饶的土地"}, {"w": "丰土", "t": "富饶的地方。"}]}, {"meaning": "豆器所盛丰富的。", "cites": [{"t": "故礼丰不足以效爱,而诚可以怀远。", "b": "《淮南子》"}]}, {"meaning": "增大;扩大。", "cites": [{"t": "树中天之华阙,丰冠山之朱堂。", "b": "班固《西都赋》"}]}, {"meaning": "容貌丰满美好。", "cites": [{"t": "子之丰兮,俟我乎巷兮。", "b": "《诗·郑风·丰》"}, {"t": "升长皆丰容。", "b": "谢灵运诗。注:“悦茂貌。”"}], "words": [{"w": "丰妍", "t": "丰美艳丽"}, {"w": "丰容", "t": "容貌丰润美丽。"}]}, {"meaning": "风度,风姿。", "cites": [{"t": "一少年出,丰采甚都。(美好。)", "b": "《聊斋志异》。"}], "words": [{"w": "丰雅", "t": "丰采文雅"}, {"w": "丰裁", "t": "丰采,风姿,风度"}, {"w": "丰格", "t": "风度格调"}, {"w": "丰仪", "t": "风度仪表。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('75wx','王','1','wáng wàng','王','4','','[{"pinyin": "wáng", "defs": [{"meaning": "(会意。本作“士”,是能独立任事的人,后加一横,表示在“士”之上,即人间的最高统治者,而帝 是天上的最高统治者。后“帝”、“王”同步降职,帝成了人间的皇帝,而“王”成了对臣子的最高封爵。本义:天子、君主)。"}, {"meaning": "殷周时代对帝王的称呼。", "cites": [{"t": "溥天之下,莫非王土。", "b": "《诗·小雅·北土》"}, {"t": "厉王虐,国人谤王。", "b": "《国语·周语上》"}, {"t": "王,天下所归往也。董仲舒曰:“古之造文者,三画而连其中谓之王。三者,天、地、人也;而参通之者,王也。”", "b": "《说文》"}, {"t": "王,天子也。", "b": "《释名》"}, {"t": "王,有天下曰王。帝与王一也。周衰,列国皆僭号自王。秦有天下,遂自尊为皇帝。汉有天下,因秦制称帝,封同姓为王,名始乱矣。", "b": "《六书故》"}, {"t": "故百王之法不同。", "b": "《荀子·王霸》"}, {"t": "制其守宰,不制其侯王。", "b": "柳宗元《封建论》"}, {"t": "以王命聚之。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "王公", "t": "天子与诸侯;泛指达官贵人"}, {"w": "王土", "t": "天子的土地"}, {"w": "王士", "t": "天子的士民"}, {"w": "王宇", "t": "天子的宫殿"}, {"w": "王志", "t": "天子的意向"}, {"w": "王车", "t": "王之车乘。"}]}, {"meaning": "春秋时,楚、吴、越等诸侯国国君也开始称“王”,战国时各诸侯国国君普遍称“王”。", "cites": [{"t": "越王勾践栖于会稽之上。", "b": "《国语·越语上》"}, {"t": "请勾践女女于王。", "b": ""}, {"t": "王好战,请以战喻。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "王人", "t": "国君"}, {"w": "王女", "t": "古时封王者之女"}, {"w": "王吏", "t": "天子或国君的官吏"}, {"w": "王使", "t": "天子或王侯的使者"}, {"w": "王政", "t": "国君的政令"}, {"w": "王妃", "t": "侯王、太子之配偶;帝王之妾,位次于皇后。"}]}, {"meaning": "从秦代开始,天子改称“皇帝”,“王”便成了对贵族或功臣的最高封爵,即诸侯王。", "cites": [{"t": "赐号称王。", "b": "《汉书·李广苏建传》"}, {"t": "王侯以下。", "b": "《后汉书·张衡传》"}], "words": [{"w": "西汉初,刘濞被封为吴王;韩信先被封为齐王,后改为楚王", "t": ""}]}, {"meaning": "首领;同类中最突出者。", "cites": [{"t": "王久不至。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "擒贼先擒王;乐器之王;拜他为王", "t": ""}]}, {"meaning": "中国古代对祖父母的尊称。", "cites": [{"t": "父之考为王父,父之妣为王母,王父之考为曾祖王父,王父之妣为曾祖王母,曾祖王父之考,为高祖王父…。", "b": "《尔雅》"}]}, {"meaning": "姓。"}]}, {"pinyin": "wàng", "defs": [{"meaning": "统治、领有一国或一地。", "cites": [{"t": "王此大邦,克顺克比。", "b": "《诗·大雅》"}, {"t": "欲王关中。", "b": "《史记·项羽本纪》"}, {"t": "秦地可尽王。", "b": ""}, {"t": "沛公为汉王,王巴、蜀。", "b": "《史记·留侯世家》"}]}, {"meaning": "作皇帝,称王。", "cites": [{"t": "然而不王者,未之有也。", "b": "《孟子·梁惠王上》"}, {"t": "行仁政而王,莫之能御也。", "b": "《孟子·公孙丑上》"}, {"t": "周不法商,夏不法虞,三代异势,而皆可以王。", "b": "《商君书》"}]}, {"meaning": "胜过。", "cites": [{"t": "常季曰:“彼兀者也,而王先生,其与庸亦远矣。”", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('76wx','开','1','kāi','廾','4','','[{"pinyin": "kāi", "defs": [{"meaning": "(会意。小篆字形,两边是两扇门,中间一横是门闩,下面是一双手,表示两手打开门闩之意。本义:开门)。"}, {"meaning": "同本义。", "cites": [{"t": "開,张也。", "b": "《说文》"}, {"t": "天门开阖。", "b": "《老子》十章"}, {"t": "善闭,无关楗而不可开。", "b": "《老子》"}, {"t": "开物成务。", "b": "《易·系辞上》"}, {"t": "开我东阁门。", "b": "《乐府诗集·木兰诗》"}, {"t": "遂开门纳众。", "b": "《资治通鉴·唐记》"}, {"t": "开轩面场圃。", "b": "唐·孟浩然《过故人庄》"}, {"t": "午后又开西门归德门。", "b": "《广东军务记》"}], "words": [{"w": "开城", "t": "打开城门"}, {"w": "开门钱", "t": "男家迎亲的轿子到女家,女家开门前索取的钱财。"}]}, {"meaning": "打开,开启。", "cites": [{"t": "微子开封于宋。", "b": "《荀子·议兵》"}, {"t": "公辨其声,而目不可开。", "b": "方苞《左忠毅公逸事》"}, {"t": "晶晶然如镜之新开。", "b": "明·袁宏道《满井游记》"}, {"t": "明星荧荧,开妆镜也。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "开卷有益", "t": ""}, {"w": "旗开得胜", "t": ""}, {"w": "顿开茅塞", "t": ""}, {"w": "开封", "t": "拆开书函"}, {"w": "开窗放入大江来", "t": "只要一打开窗子,那汹涌奔腾的江水就会滚滚扑来"}, {"w": "开箱", "t": "女子出嫁后第一次打开其配嫁的箱柜"}, {"w": "开着眼", "t": "睁着眼。"}]}, {"meaning": "引申为开放;舒放。", "cites": [{"t": "千树万树梨花开。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "山寺桃花始盛开。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "只在花开之数日。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "春暖花开", "t": ""}, {"w": "盛开", "t": "花开得茂盛"}, {"w": "开眉", "t": "舒展双眉。解愁、欣喜的意思"}, {"w": "开眉展眼", "t": "形容高兴的样子。应作开眼展眉。"}]}, {"meaning": "创立,建立,开创,设立。", "cites": [{"t": "欲开置县。", "b": "《海瑞传》"}, {"t": "旁开小窗", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "开工厂;开店;开茶馆;开屏", "t": "张设屏风。"}]}, {"meaning": "摆开。", "cites": [{"t": "添酒回灯重开宴。", "b": "白居易《琵琶行》"}], "words": [{"w": "开宴", "t": "摆开酒席。"}]}, {"meaning": "开掘;开通。", "cites": [{"t": "天门中断楚江开。", "b": "唐·李白《望天门山》"}], "words": [{"w": "开天辟地;开源节流;继往开来;开达", "t": "开通明达"}, {"w": "开敏", "t": "开明通达。"}]}, {"meaning": "教导,启发。", "cites": [{"t": "移风易俗之本,乃在开其心而正其精。", "b": "王符《潜夫论》"}, {"t": "便开此议。", "b": "《资治通鉴》"}], "words": [{"w": "开诱", "t": "启发诱导"}, {"w": "开晓", "t": "开导启发,让人明白"}, {"w": "开譬", "t": "开导警惕。"}]}, {"meaning": "开拓,扩展。", "cites": [{"t": "开地数千里。", "b": "《韩非子·初见秦》"}, {"t": "开荒南野际。", "b": "晋·陶渊明《归园田居》"}, {"t": "武皇开边意未已。", "b": "唐·杜甫《兵车行》"}, {"t": "诚宜开张圣听,以光先帝遗德。", "b": "诸葛亮《出师表》"}], "words": [{"w": "开封", "t": "开拓疆土"}, {"w": "开境", "t": "开拓疆域"}, {"w": "开济", "t": "开创大业,匡济时艰"}, {"w": "开边", "t": "开拓疆域"}, {"w": "开张圣听", "t": "扩大圣明的听闻。意思是要后主广泛的听取别人的意见。"}]}, {"meaning": "戏剧开场角色的说白。", "cites": [{"t": "外扮老夫人上开。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "分离,分开。", "cites": [{"t": "连月不开。", "b": "《后汉书·列女传》"}]}, {"meaning": "又如:开交(分开;解决)。"}, {"meaning": "放晴。", "cites": [{"t": "若夫霪雨霏霏,连月不开。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "若夫日出而林霏开。", "b": "欧阳修《醉翁亭记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('77wx','井','1','jǐng','二','4','','[{"pinyin": "jǐng", "defs": [{"meaning": "(象形。金文字形,外象井口,中间一点表示井里有水。本义:水井)。"}, {"meaning": "同本义。", "cites": [{"t": "改邑不改井。", "b": "《易·井》"}, {"t": "井道。", "b": "《易·杂卦》传"}, {"t": "宿息井树。", "b": "《周礼·野庐氏》。注:“井,共饮食。”"}, {"t": "为其井匽。", "b": "《周礼·官人》"}, {"t": "坐井观天,曰天小者,非天小也。", "b": "韩愈《原道》"}], "words": [{"w": "井池", "t": "井口旁储水的小池"}, {"w": "井鱼", "t": "井中的鱼。比喻见识短浅"}, {"w": "井养", "t": "井水源源不断,供人饮用。比喻领受别人的好处、恩惠"}, {"w": "井华", "t": "清早初汲的井水"}, {"w": "井干", "t": "井上木栏干。"}]}, {"meaning": "井田。", "cites": [{"t": "六里而井,井九百亩,其中为公田,八家皆私百亩,同养公田。", "b": "《孟子·滕文公下》"}], "words": [{"w": "井税", "t": "古代田税的一种"}, {"w": "井地", "t": "即井田"}, {"w": "井里制", "t": "即井田制"}, {"w": "井邑田", "t": "即井田"}, {"w": "井径", "t": "田间小路。"}]}, {"meaning": "相传古制八家为井。引申为人口聚居地;乡里;家宅。", "cites": [{"t": "背井离乡,卧雪眠霜。", "b": "马致远《汉宫秋》"}], "words": [{"w": "井里", "t": "邑里,乡里"}, {"w": "井庐", "t": "古代井田制,八家共一井,因用以指井田和房舍"}, {"w": "井曲", "t": "里巷;里弄"}, {"w": "井屋", "t": "农舍,村落。"}]}, {"meaning": "污水池 。 如: 井匽(排除污水秽物的水池和水沟)。"}, {"meaning": "比喻法度;条理。", "cites": [{"t": "井,法也。节也。言法制居人,令节其饮食,无穷竭也。", "b": "《风俗通》"}, {"t": "井,共德之地也。", "b": "《易·系辞》"}, {"t": "井井兮其有理也。", "b": "《荀子·儒效》"}], "words": [{"w": "井井", "t": "形容整齐,有条理"}, {"w": "井井有方", "t": "形容有条理、有办法"}, {"w": "井井有法", "t": "有条理、有法度"}, {"w": "井井有绪", "t": "井井有序。有条理,有秩序。"}]}, {"meaning": "市街。", "cites": [{"t": "处商必就市井。", "b": "《管子·小筐》"}, {"t": "因井为市,故言市井。", "b": "《白虎通》"}], "words": [{"w": "井邑", "t": "市井与乡里"}, {"w": "井市", "t": "做买卖的市街。古代因井为市,故称"}, {"w": "井陌", "t": "街道"}, {"w": "井闾", "t": "里井里巷。"}]}, {"meaning": "汲水于井。", "cites": [{"t": "织纺井臼。(井,用如动词;汲井水。)", "b": "清·周容《芋老人传》"}]}, {"meaning": "划定井田。", "cites": [{"t": "井衍沃。(在肥地上划定井田。)", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('78wx','天','1','tiān','大','4','','[{"pinyin": "tiān", "defs": [{"meaning": "(会意。甲骨文字形。下面是个正面的人形(大),上面指出是人头,小篆变成一横。本义:人的头顶)。"}, {"meaning": "同本义。", "cites": [{"t": "天,颠也。…颠者,人之顶也。以为凡高之称。", "b": "《说文解字注》"}], "words": [{"w": "天灵", "t": "人或其他动物的头顶骨"}, {"w": "天灵盖", "t": "头顶骨。"}]}, {"meaning": "古代的墨刑。在额头上刺字的刑罚。", "cites": [{"t": "天,刑名。剠凿其额曰天。", "b": "《集韵》"}]}, {"meaning": "《其人天且劓。——《易·睽卦》。虞注:“黥额为天。”。"}, {"meaning": "天空。", "cites": [{"t": "天,至高无上。", "b": "《说文》"}, {"t": "天,气也。", "b": "《论衡·谈天》"}, {"t": "形天与帝至此争神,帝断其首。", "b": "《神话四则·形天》"}, {"t": "天似穹庐。", "b": "《乐府诗集·杂歌谣辞·敕勒歌》"}, {"t": "天苍苍。", "b": ""}, {"t": "接天莲叶无穷碧。", "b": "宋·杨万里《晓出净慈寺送林子方》"}, {"t": "仰视天。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "天澄澄", "t": "天色澄清的样子"}, {"w": "天色", "t": "天空色"}, {"w": "天宇", "t": "天空"}, {"w": "天日", "t": "天空与太阳"}, {"w": "天角", "t": "天之一隅"}, {"w": "天盘", "t": "天际"}, {"w": "天弩", "t": "天空;天空高远。"}]}, {"meaning": "天帝,上天。古人以天为万物主宰者。", "cites": [{"t": "休祲降于天。", "b": "《战国策·魏策》"}, {"t": "有夏多罪,天命殛之。", "b": "《书·商书》"}, {"t": "天下所启。", "b": "《左传·僖公二十三年》"}, {"t": "天赐也。", "b": ""}, {"t": "天其或者将逮诸。", "b": ""}, {"t": "天将兴之,谁能废之。", "b": ""}, {"t": "此天之亡我,非战之罪也。", "b": "《史记·项羽本纪》"}, {"t": "天将降大任。", "b": "《孟子·告子下》"}, {"t": "天以卿二人赞孤也。", "b": "《资治通鉴》"}], "words": [{"w": "天可怜见", "t": "上天救助,老天保佑"}, {"w": "天庖", "t": "天帝的庖厨"}, {"w": "天马", "t": "神马;骏马的美称"}, {"w": "天丁", "t": "天兵"}, {"w": "天功", "t": "天的职任;天然形成的工巧"}, {"w": "天打雷劈;天休", "t": "天赐福佑"}, {"w": "天佑", "t": "上天佑助。"}]}, {"meaning": "天堂 。", "words": [{"w": "天居", "t": "住在天上"}, {"w": "天陛", "t": "天宫台阶。"}]}, {"meaning": "一昼夜 。", "words": [{"w": "天把", "t": "一两天,一天半天"}, {"w": "夏天天长夜短;今天;明天", "t": ""}]}, {"meaning": "比人类品质更高尚和能力更强大的存在。", "cites": [{"t": "违天不祥。", "b": "《左传·僖公三十二年》"}, {"t": "此乃天也。", "b": "《资治通鉴》"}], "words": [{"w": "天晓得;我的天", "t": ""}]}, {"meaning": "自然所生成的事物。", "cites": [{"t": "与天不老。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "巧夺天工;天性如此;天衣无缝;文章天成;天演", "t": "自然进化"}, {"w": "天巧", "t": "自然工巧"}, {"w": "天式", "t": "自然法式"}, {"w": "天光", "t": "自然的智慧之光"}, {"w": "天财", "t": "自然财富。"}]}, {"meaning": "一年里的特定时候 。", "words": [{"w": "天中节", "t": "端午节"}, {"w": "夏天;黄梅天", "t": ""}]}, {"meaning": "气象状态。", "cites": [{"t": "秋天漠漠向昏黑。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "天阴雨湿声啾啾。", "b": "唐·杜甫《兵车行》"}, {"t": "心忧炭贱愿天寒。", "b": "唐·白居易《卖炭翁》"}, {"t": "天阴黑。", "b": "《资治通鉴·唐纪》。"}], "words": [{"w": "天风馋", "t": "冷风袭人,易使人生病"}, {"w": "天变了", "t": ""}]}, {"meaning": "丈夫 。"}, {"meaning": "如:失其所天。"}, {"meaning": "指先天不足。", "cites": [{"t": "此天之所不足也。", "b": "《灵枢》"}]}, {"meaning": "古代指君王 。"}, {"meaning": "如:天颜(皇帝之面);天表(天子的仪表);天恩;天邑(帝王之都);天位(天子之位)。"}, {"meaning": "头等大事。", "cites": [{"t": "王者以民人为天,而民人以食为天。", "b": "《史记·郦生陆贾列传》"}]}, {"meaning": "人的额部 。"}, {"meaning": "如:天炙(朱水点额)。"}, {"meaning": "天然的;天生的。", "cites": [{"t": "依乎天理,批大卻,导大窾。", "b": "《庄子·庖丁解牛》"}], "words": [{"w": "天性;天资", "t": ""}]}, {"meaning": "顶上的;架空的 。", "words": [{"w": "天桥;天窗;天棚", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('79wx','夫','1','fū fú','大','4','','[{"pinyin": "fū", "defs": [{"meaning": "(象形。甲骨文字形,像站着的人形(大),上面的“一”,表示头发上插一根簪(zān),意思是成年男子,是个丈夫了。古时男子成年束发加冠才算丈夫,故加“一”做标志。本义:成年男子的通称)。"}, {"meaning": "同本义。", "cites": [{"t": "夫,丈夫也。", "b": "《说文》。按,夫从一大,会意兼象形。周制以八寸为尺,十尺为丈,人长八尺,故曰丈夫。"}, {"t": "夫也不良。", "b": "《诗·陈风·墓门》"}, {"t": "残贼之人,谓之一夫。", "b": "《孟子》。注:“将必将为匹夫。”"}, {"t": "二田为一夫。", "b": "《管子·乘马》"}, {"t": "遂率子孙荷担者三夫。", "b": "《列子·汤问》"}, {"t": "一夫不耕,或受之饥。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "夫公", "t": "古代敬称男子为夫公"}, {"w": "夫男", "t": "男人,丈夫"}, {"w": "夫家", "t": "男女。丁男无妻者谓夫,有妻者谓家。"}]}, {"meaning": "女子的正式配偶。", "cites": [{"t": "大儿初醒声,夫叱大儿声,一时齐发。", "b": "《虞初新志·秋声诗自序》"}, {"t": "使君自有妇,罗敷自有夫。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "夫主", "t": "丈夫"}, {"w": "夫室", "t": "丈夫"}, {"w": "夫党", "t": "丈夫的亲属。"}]}, {"meaning": "大丈夫。对男子的美称。", "cites": [{"t": "西川刘禅本非夫,文灿贪庸亦竖奴。", "b": "柳亚子《诸将六首》"}]}, {"meaning": "剑衣。", "cites": [{"t": "剑则启椟,盖袭之,加夫襓与剑焉。", "b": "《礼记·少仪》"}]}, {"meaning": "足背。", "cites": [{"t": "渠长丈六尺,夫长丈二尺,臂长六尺。", "b": "《墨子·备城门》"}]}, {"meaning": "再,又一次。", "cites": [{"t": "回志怯来从玄谋,获我所求夫所思?", "b": "张衡《思玄赋》"}]}]}, {"pinyin": "fú", "defs": [{"meaning": "那,那个,那些 ——表示远指。", "cites": [{"t": "故为之说,以俟夫观人风者得焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "余亦悔其随之而不得极夫游之乐也。", "b": "宋·王安石《游褒禅山记》"}]}, {"meaning": "这,这个,这些 ——表示近指。", "cites": [{"t": "夫人不言,言必有中。", "b": "《论语·先进》"}]}, {"meaning": "所有的,大家。相当于“凡”。", "cites": [{"t": "夫知保抱携持厥妇子。", "b": "《书·召诰》"}]}, {"meaning": "用于句首,有提示作用。", "cites": [{"t": "夫秦有虎狼之心。", "b": "《史记·项羽本径》"}, {"t": "夫六国与秦皆诸侯,其势弱于秦。", "b": "宋·苏洵《六国论》"}, {"t": "夫战,勇气也", "b": ""}]}, {"meaning": "用于句中,舒缓语气。", "cites": [{"t": "乃歌夫“长铗归来”者也。", "b": "《战国策·齐策》"}]}, {"meaning": "用于句尾名，表示感叹。", "cites": [{"t": "孟子曰：“术不可不慎。”信夫!", "b": "清·方苞《狱中杂记》"}, {"t": "悲夫!有如此之势，而为秦人积威之所劫。", "b": "宋·苏洵《六国论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('80wx','元','1','yuán','儿','4','','[{"pinyin": "yuán", "defs": [{"meaning": "(会意。从一,从兀。甲骨文字形。象人形。上面一横指明头的部位。上一短横是后加上去的,依汉字造字规律,顶端是一横的,其上可加一短横。本义:头)。"}, {"meaning": "同本义。", "cites": [{"t": "元,始也。", "b": "《说文》。按,当训首也。"}, {"t": "元,体之长也。", "b": "《左传·襄公九年》"}, {"t": "始加元服。", "b": "《仪礼·士冠礼》"}, {"t": "狄人归其元。", "b": "《左传·僖公三十三年》"}, {"t": "归国子之元。", "b": "《左传·哀公十一年》"}, {"t": "勇士不忘丧其元。", "b": "《孟子》"}, {"t": "牛曰一元大武。", "b": "《礼记·曲礼》。注:“头也。”"}, {"t": "吐蕃叛换方炽,敬玄失律,审礼丧元,安可更为西方生事?", "b": "《新唐书》"}], "words": [{"w": "元首", "t": "头。"}]}, {"meaning": "天。", "cites": [{"t": "执元德于心而化驰若神。", "b": "《淮南子·原道》。注:“天也。”"}], "words": [{"w": "元机", "t": "天机,指神秘的天意"}, {"w": "元神", "t": "天帝,天神"}, {"w": "元父", "t": "天帝"}, {"w": "元命", "t": "天命"}, {"w": "元天", "t": "苍天。"}]}, {"meaning": "君。", "cites": [{"t": "元首起哉。", "b": "《书·益稷》。传:“元首,君也。”"}, {"t": "元,君也。", "b": "《广雅》"}, {"t": "故国斜阳草自春,争元作相总成尘。", "b": "宋·文天祥《得儿女消息》"}], "words": [{"w": "元、恺辅舜", "t": "传说高辛氏有才子八人,叫“八元”。高阳氏有才子八人,叫“八恺”。八元八恺辅佐虞舜,把政事治理得很好"}, {"w": "元龙", "t": "皇帝"}, {"w": "元明", "t": "佛教指清净光明"}, {"w": "元后", "t": "天子;帝王的嫡妻。"}]}, {"meaning": "开始;起端。", "cites": [{"t": "元年者何?君之始年也。", "b": "《公羊传·隐公元年》"}], "words": [{"w": "元始天尊", "t": "道教所尊的最高天神。据说他生于太元之先。故名"}, {"w": "元初", "t": "起初"}, {"w": "元由", "t": "原由。事情的起始和原因"}, {"w": "元因", "t": "原因。"}]}, {"meaning": "道家所谓的道。", "cites": [{"t": "元,无所不在也。人能守元,元则舍之;人不守元,元则舍之。", "b": "《子华子·大道》"}], "words": [{"w": "元神", "t": "佛道经过修炼的灵魂。成仙得道的人,其元神可以离开肉体自由来往"}, {"w": "元君", "t": "道教对女子成仙者的尊称"}, {"w": "元龙", "t": "元阳,道教指“得道”。"}]}, {"meaning": "指帝王年号。", "cites": [{"t": "元,宜以天瑞命,不宜以一二数。", "b": "《史记》"}]}, {"meaning": "朝代名 。1206 年,成吉思汗建蒙古汗国。1271 年,忽必烈定国号为元。1279 年灭南宋,统一全国,建都大都(今北京)。1368 年,朱元璋军攻占大都,元亡。自定国号起,元凡十一帝,历时九十八年。", "cites": [{"t": "元至正间。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "又。", "cites": [{"t": "元政紊弛。", "b": ""}], "words": [{"w": "元人百种", "t": "书名。即元曲选。"}]}, {"meaning": "第一,居首位的。", "cites": [{"t": "二世元年七月。", "b": "《史记·陈涉世家》"}, {"t": "天汉元年。", "b": "《汉书·李广苏建传》"}, {"t": "阳嘉元年。", "b": "《后汉书·张衡传》"}, {"t": "隆庆元年。", "b": "《明史》"}], "words": [{"w": "元题", "t": "第一道题"}, {"w": "元辰", "t": "元旦;吉日"}, {"w": "元首", "t": "迷信占卜名称之一,六壬课中的第一课,是大吉大利,如愿的课"}, {"w": "元妃", "t": "国君或诸侯的嫡妻"}, {"w": "元子", "t": "天子和诸侯的嫡长子"}, {"w": "元女", "t": "长女。"}]}, {"meaning": "大。", "cites": [{"t": "夫基事之元命,必与天下自新。颜师古注:“元,大也。”", "b": "《汉书》"}], "words": [{"w": "元功巨勋", "t": "巨大的功勋"}, {"w": "元庸", "t": "巨大的功劳"}, {"w": "元勋", "t": "大功勋。"}]}, {"meaning": "本来;向来;原来。", "cites": [{"t": "元犹原也。", "b": "《春秋繁露 ·垂政》"}, {"t": "必先原元而本本。", "b": "《潜夫论·本训》"}], "words": [{"w": "元物", "t": "原物"}, {"w": "元金", "t": "金属"}, {"w": "元丝课", "t": "一种标准银锭"}, {"w": "元名", "t": "原名"}, {"w": "元身", "t": "原身"}, {"w": "元心", "t": "本心,本意。"}]}, {"meaning": "黑色。清朝避康熙(玄烨)皇帝的讳。改“玄”为“元”。", "cites": [{"t": "自此而元焉。", "b": "清·洪亮吉《治平篇》"}]}, {"meaning": "又。", "cites": [{"t": "至曾元时。", "b": ""}], "words": [{"w": "元黄", "t": "黑色与黄色。引申为吏治"}, {"w": "元色", "t": "黑色"}, {"w": "元玉", "t": "玄玉。黑色的玉"}, {"w": "元狐", "t": "玄狐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('81wx','无','1','mó wú','一','4','','[{"pinyin": "mó", "defs": [{"meaning": "“南无”(nāmó):佛教用语,表示对佛尊敬或皈依。"}]}, {"pinyin": "wú", "defs": [{"meaning": "(会意。据甲骨文字形,象一个人持把在跳舞。卜辞、金文中“无、舞”同字。本义:乐舞)。"}, {"meaning": "同本义。"}, {"meaning": "哲学范畴,指无形、无名、虚无等,或指物质的隐微状态。", "cites": [{"t": "天下万物生于有,有生于无。", "b": "《老子》"}]}, {"meaning": "没有,跟“有”相对。", "cites": [{"t": "无,不有也。", "b": "《玉篇》"}, {"t": "无若丹朱傲。", "b": "《书·益稷》"}, {"t": "无偏无党。", "b": "《书·洪范》"}, {"t": "无内人之疏,而外人之亲。", "b": "《荀子·法行》"}, {"t": "事不耳闻目睹而臆断其有无,可乎?", "b": "苏轼《石钟山记》"}, {"t": "无不伸颈。", "b": "《虞初新志·秋声诗自序》"}, {"t": "无不变色。", "b": ""}, {"t": "无不毕肖。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "无不惊为生人。", "b": ""}], "words": [{"w": "无颜落色", "t": "面色发白,没有颜色"}, {"w": "无头面", "t": "没有头绪"}, {"w": "无是处", "t": "毫无办法;没有一点儿好处"}, {"w": "无纤掐", "t": "没有一点"}, {"w": "无气歇", "t": "没歇一口气,没有停息"}, {"w": "无回豁", "t": "没有反应"}, {"w": "没干净", "t": "不罢休,没完没了"}, {"w": "无存济", "t": "无办法,难以应付"}, {"w": "无笆壁", "t": "无依靠;无办法"}, {"w": "无路求生;无干", "t": "没关系;不相干"}, {"w": "无方", "t": "无常;没有固定的行止、住处等"}, {"w": "无虞", "t": "无误。"}]}, {"meaning": "不,表示对动词或形容词的否定。", "cites": [{"t": "臣是以无请也。", "b": "《韩非子·喻老》"}, {"t": "请无攻宋矣。", "b": "《墨子·公输》"}, {"t": "不若无闻。", "b": "《吕氏春秋·慎行论》"}, {"t": "可以无悔矣。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "无偏无党", "t": "公正而不偏袒"}, {"w": "无何", "t": "不久"}, {"w": "无过", "t": "不过;无非;不外"}, {"w": "无厌", "t": "不满足。"}]}, {"meaning": "表示劝阻或禁止,可译为“不要”、“别”。", "cites": [{"t": "无偏无党,王道荡荡。", "b": "《书·洪范》"}, {"t": "无对靡于尔邦。", "b": "《诗·周颂·烈文》"}, {"t": "唯吾子戎车是利,无愿士宜。", "b": "《左传·成公二年》"}, {"t": "子曰:“君子食无求饱,居无求安,敏于事而慎于言…”《论语·学而》", "b": ""}, {"t": "无相忘。", "b": "《史记·陈涉世家》"}, {"t": "无望其速成。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "无怪乎其私之。", "b": "清·黄宗羲《原君》"}, {"t": "无生帝王家。", "b": ""}], "words": [{"w": "无休外", "t": "不要见外"}, {"w": "无失其时;无落", "t": "别误;不要落空"}, {"w": "无得", "t": "不得;不能"}, {"w": "无论", "t": "不要说。"}]}, {"meaning": "未,不曾,没。", "cites": [{"t": "有奇字素无备者,旋刻之。", "b": "沈括《梦溪笔谈》"}]}, {"meaning": "不必,不值得。", "cites": [{"t": "渫恶吏忍于鬻狱,无责也。", "b": "方荀《狱中杂记》"}]}, {"meaning": ""}, {"meaning": "表示不定指的人、事物、时间、处所等。", "cites": [{"t": "臣少好相人,相人多矣,无如季相。", "b": "《汉书·高帝纪》"}, {"t": "城牢粮足,不可忧也。", "b": "《资治通鉴》"}], "words": [{"w": "无移时", "t": "不一会儿;时间不久"}, {"w": "无一时", "t": "不一会儿;时间不久"}, {"w": "无明夜", "t": "不分白天黑夜"}, {"w": "无定着", "t": "没有固定的地方"}, {"w": "无倒断", "t": "没完没了"}, {"w": "无碑记", "t": "无数;不可计数"}, {"w": "无般", "t": "样样,处处。"}]}, {"meaning": "连接词组或分句,表示在任何条件或情况下都是如此,相当于“不论”、“无论”。", "cites": [{"t": "无少长皆斩之。", "b": "《汉书·高后纪》"}, {"t": "无贵无贱。", "b": "唐·韩愈《师说》"}, {"t": "无长无少。", "b": ""}], "words": [{"w": "事无大小,都有人负责;事无巨细,他都认真去干;无上无下", "t": ""}]}, {"meaning": "用在句首,无义。", "cites": [{"t": "今王公大人,虽无造为乐器,以为事乎国家。", "b": "《墨子》"}]}, {"meaning": "用在句末,表示疑问语气,可译为“吗”。", "cites": [{"t": "晚来天欲雪,能饮一杯无?", "b": "白居易《问刘十九》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('82wx','云','1','yún','二','4','','[{"pinyin": "yún", "defs": [{"meaning": "(象形。《说文》:古文字形。象云回转形。“雲”为会意字,从雨,从云。本义:云彩。这个意义后作“雲”)。"}, {"meaning": "同本义。"}, {"meaning": "大气中的水蒸气,凝聚而成小水滴或水粒,或与雨共存时肉眼可见的集合体,叫做云。", "cites": [{"t": "雲,山川气也。", "b": "《说文》"}, {"t": "地气上为云。", "b": "《素问·阴阳应象大论》"}, {"t": "有其状若悬於而赤,其名曰云。", "b": "《吕氏春秋·明理》"}, {"t": "云集响应。", "b": "汉·贾谊《过秦论》"}, {"t": "云归而岩穴瞑。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "云瞑", "t": "古乐器名"}, {"w": "云根", "t": "山石。古人认为云是从山石中产生的,故称"}, {"w": "云ń", "t": "传说中的云车"}, {"w": "云狐", "t": "用脑门和股两处的狐皮拼成云形花纹的皮衣料"}, {"w": "云轮", "t": "云车的轮子"}, {"w": "云板", "t": "佛教道场上用的一种敲击乐器"}, {"w": "云彻", "t": "像扫除残云那样干净彻底"}, {"w": "云护", "t": "画在人物周围环护的云彩"}, {"w": "云鸿", "t": "云中鸿雁,即鸿雁传书。后用指书信"}, {"w": "云霾", "t": "行云和阴霾"}, {"w": "云端里看厮杀", "t": "袖手旁观;瞧热闹"}, {"w": "云山", "t": "云雾缭绕的山"}, {"w": "云消雨散", "t": "指一切事物都如云雨一样消散不见"}, {"w": "云淡风轻;云开见日", "t": "比喻清除蒙蔽,重见光明"}, {"w": "云情雨意", "t": "指男女欢会之情意"}, {"w": "云翻雨覆", "t": "比喻反复不定。"}]}, {"meaning": "比喻轻柔舒卷如云之物。", "cites": [{"t": "云衫玉带好威仪,三洞真人入奏时。", "b": "唐·曹唐《小游仙诗》"}], "words": [{"w": "云髻", "t": "女子的发髻"}, {"w": "云鬟", "t": "形容女女的头发卷曲如云"}, {"w": "云衫", "t": "轻而薄的衣衫。"}]}, {"meaning": "借指高空。", "cites": [{"t": "灵皇皇兮既降,猋远举兮云中。", "b": "《楚辞·九歌·云中君》"}], "words": [{"w": "云中", "t": "云霄之中,高耸入云的山上"}, {"w": "云枝", "t": "高耸入云的树枝"}, {"w": "云杪", "t": "云霄,高空"}, {"w": "云扃", "t": "高山上的屋门。借指高山上的房屋。"}]}, {"meaning": "云南省的简称。"}, {"meaning": "比喻盛多。", "cites": [{"t": "齐子归止,其从如云。", "b": "《诗·齐风·敝笱》"}, {"t": "威武纷云。", "b": "《汉书·司马相如传》。颜师古云:“纷云,盛貌。”"}], "words": [{"w": "云从", "t": "比喻随从众多"}, {"w": "云会", "t": "如云聚集,比喻众多"}, {"w": "云涛", "t": "形容云起盛多如波涛汹涌。"}]}, {"meaning": "比喻高。", "cites": [{"t": "黄帝得之,以登云天。", "b": "《庄子·大宗师》"}], "words": [{"w": "云天", "t": "高天。云,极言其高"}, {"w": "云步石梯", "t": "登向高处的石阶"}, {"w": "云房", "t": "古时称隐士或僧道的住所。"}]}, {"meaning": "说。", "cites": [{"t": "我旧云刻子。", "b": "《书·微子》。马注:“云,言也。”"}, {"t": "伊谁云从?", "b": "《诗·小雅·何人斯》"}, {"t": "大旱之日短而云灾。", "b": "《公羊传·文公二年》"}, {"t": "谁云救之。", "b": "《国语·晋语》"}, {"t": "自云先世。", "b": "晋·陶渊明《桃花源记》"}, {"t": "此中人语云。", "b": ""}, {"t": "云欲自修改。", "b": "《世说新语·自新》"}, {"t": "孔子云。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "人云亦云;不知所云;诗云", "t": ""}]}, {"meaning": "有。", "cites": [{"t": "其云益乎?", "b": "《荀子·法行》"}]}, {"meaning": "为,是。", "cites": [{"t": "虽云匹夫,霸王可也。", "b": "《后汉书》"}]}, {"meaning": "旋。", "cites": [{"t": "洽比其邻,昏姻孔云。", "b": "《诗·小雅·正月》"}]}, {"meaning": "无实在意义。", "cites": [{"t": "当以训汝子孙,使知前辈之风俗云。", "b": "宋·司马光《训俭示康》"}, {"t": "宋将军云。", "b": "明·魏禧《大铁椎传》"}, {"t": "尝贻余核舟一,盖大苏泛赤壁云。", "b": "明·魏学《核舟记》"}, {"t": "谓之天门云。", "b": "清·姚鼐《登泰山记》"}, {"t": "请命西后云。", "b": "清·梁启超《谭嗣同传》"}]}, {"meaning": "如此;这样。", "cites": [{"t": "民人俗语曰“即不为河伯娶妇,水平漂没,溺其人民”云。", "b": "褚少孙《西门豹治邺》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('83wx','专','1','zhuān','一','4','','[{"pinyin": "zhuān", "defs": [{"meaning": "(会意兼形声。甲骨文字形,右边象纺塼(zhuān)形,即“叀(zhuan);左边是手(寸),合起来为用手纺织。“叀”兼作声符。本义:纺锤)。"}, {"meaning": "纺专,收丝器。", "cites": [{"t": "专,纺专。", "b": "《说文》。字亦作塼,作甎,俗作磚。"}, {"t": "载弄之瓦。", "b": "《诗·小雅·斯干》。传:“瓦,纺塼也。”按,原始的陶制纺锤。"}]}, {"meaning": "独占;独用。", "cites": [{"t": "专禄以周旋,戮也。", "b": "《左传·襄公二十六年》"}, {"t": "吴王擅鄣海泽,邓通专西山。", "b": "《盐铁论·错币》"}, {"t": "罔俾阿衡(即伊尹)专美有商。", "b": "《书·说命下》"}, {"t": "专其利三世矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "衣食所安,弗敢专也。", "b": "《左传·庄公十年》"}, {"t": "敢专承之。", "b": "《国语·晋语》"}, {"t": "与其卖而分,孰若吾得专焉?", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "专功", "t": "独占其功"}, {"w": "专道", "t": "独占道路"}, {"w": "专贵", "t": "独占尊位"}, {"w": "专美", "t": "独享美名"}, {"w": "专宠", "t": "独占宠爱"}, {"w": "专据", "t": "独占。"}]}, {"meaning": "使专一;使集中。", "cites": [{"t": "不专心致志则不得也。", "b": "《孟子·告子上》"}, {"t": "其静也专,其动也直。", "b": "《易·系辞上》"}, {"t": "则其读书也必专。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "专必", "t": "专一不易"}, {"w": "专专", "t": "用心专一"}, {"w": "专愚", "t": "用心专一而至不通事情"}, {"w": "专节", "t": "专一不变的节操"}, {"w": "专谨", "t": "专一谨慎"}, {"w": "专注", "t": "专心注意。"}]}, {"meaning": "独裁,专擅,独断独行。", "cites": [{"t": "祭仲专,郑伯患之。", "b": "《左传·桓公十五年》"}, {"t": "主弱臣强,专制擅权。", "b": "《汉书》"}, {"t": "举动自专由。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "奉事循公姥,进止敢自专。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "那得自任专。", "b": ""}, {"t": "大夫出疆,有可以安社稷、利国家,专之可也。", "b": "《三国演义》"}]}, {"meaning": "专断。", "cites": [{"t": "闻道有先后,术业有专攻。", "b": "唐·韩愈《师说》"}], "words": [{"w": "专款;专车;专程;专经", "t": "专门诵习某一种经书"}, {"w": "专摺明保", "t": "为保举某人专门上摺子经吏部奏军机处奏闻皇上"}, {"w": "专条", "t": "专门条款。"}]}, {"meaning": "狭小。", "cites": [{"t": "独守专室而不出门。", "b": "《淮南子》"}]}, {"meaning": "满。", "cites": [{"t": "专车,满一车。", "b": "吴曾祺《国语韦解补证》"}]}, {"meaning": "诚笃。", "cites": [{"t": "盖其俗朴而专,和而靖。", "b": "叶适《长溪修学记》"}]}, {"meaning": "全,都。", "cites": [{"t": "专听其大臣者,危主也。", "b": "《管子》"}]}, {"meaning": "很,非常。", "cites": [{"t": "其父常以为专愚,几不知马足。", "b": "《后汉书》"}]}, {"meaning": "仅仅,只。", "cites": [{"t": "人材不足专恃,而道术可公行也。", "b": "《淮南子》"}], "words": [{"w": "专综", "t": "独自总揽"}, {"w": "专爱", "t": "独受怜爱。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('84wx','丐','1','gài','一','4','','[{"pinyin": "gài", "defs": [{"meaning": "乞求,乞讨。", "cites": [{"t": "求愿曰匃。", "b": "《通俗文》"}, {"t": "匃,求也。", "b": "《广雅》"}, {"t": "不强丐。", "b": "《左传·昭公六年》"}, {"t": "毋或匄夺。", "b": "《左传·昭公十六年》"}, {"t": "丐沐沐我。", "b": "《史记·外戚世家》"}, {"t": "丐,乞也。", "b": "《字汇》"}, {"t": "不抽屋,不强丐。", "b": "《左传·昭公六年》"}], "words": [{"w": "丐饭;丐物;丐食;丐计", "t": "乞求计策"}, {"w": "丐施", "t": "乞求布施"}, {"w": "丐贷", "t": "乞贷"}, {"w": "丐养", "t": "给人收养为义子。"}]}, {"meaning": "求,请求。", "cites": [{"t": "邹君海滨,以所辑黄花冈烈士事略丐序于予。", "b": "孙文《序》"}], "words": [{"w": "丐命", "t": "乞命。请求饶命"}, {"w": "丐祠", "t": "请求奉祠"}, {"w": "丐退", "t": "请求辞职"}, {"w": "丐留", "t": "请求留任"}, {"w": "丐贷", "t": "请求借贷。"}]}, {"meaning": "给予;施舍,把财物给与人。", "cites": [{"t": "尽取善绘,匄诸宫人。", "b": "《汉书·广川惠王越传》。注:“遗之也。”"}, {"t": "我匄若。", "b": "《汉书·西域传》。马注:“与也。”"}, {"t": "又出库钱一千万,以丐贫民遭旱不能供税者。", "b": "韩愈《太原王公墓志铭》"}, {"t": "沾丐后人多矣。", "b": "《新唐书·赞》"}]}, {"meaning": "免除,宽免。", "cites": [{"t": "诏以州镇十一水旱,丐其田租,开仓振恤。", "b": "《北史》"}]}, {"meaning": "乞丐,以乞讨为生的人。", "cites": [{"t": "于戏,丐者,言语如斯,可编为丐论。", "b": "元结《丐论》"}], "words": [{"w": "老丐;丐头;丐人;丐夫;丐者;丐棍", "t": "以乞讨为业的无赖"}, {"w": "丐首", "t": "丐头"}, {"w": "丐帮", "t": "有组织的乞丐团伙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('85wx','扎','1','zā zhā zhá','扌','4','','[{"pinyin": "zā", "defs": [{"meaning": "捆绑;缠束;拴;系。", "cites": [{"t": "抄扎家私,分俵众军。", "b": "《水浒传》"}], "words": [{"w": "扎抹", "t": "缠绑;收拾"}, {"w": "扎爪", "t": "拴绑;缠绑"}, {"w": "扎一根红头绳;扎花环;扎包", "t": "捆在腰间的长布"}, {"w": "扎缚", "t": "捆扎;包扎"}, {"w": "扎脚", "t": "缠足"}, {"w": "扎把", "t": "成捆的草把。"}]}, {"meaning": "准备。", "cites": [{"t": "[阿里奇]传令教番兵扎掂已了,来日出密云县,与宋江交锋。", "b": "《水浒传》"}], "words": [{"w": "扎裹", "t": "修饰;打扮"}, {"w": "扎括", "t": "修饰;打扮"}, {"w": "扎扮", "t": "打扮"}, {"w": "扎掂", "t": "整装出发。"}]}]}, {"pinyin": "zhā", "defs": [{"meaning": "刺;戳。", "cites": [{"t": "不问个是和非,觑僧人便扎。", "b": "董解元《西厢记》"}], "words": [{"w": "扎艺", "t": "绣花"}, {"w": "扎心", "t": "刺心。谓可恨,痛心"}, {"w": "扎针;扎害", "t": "损害;坑害。"}]}, {"meaning": "驻扎。", "cites": [{"t": "扎下一个山寨。", "b": "《水浒传》"}], "words": [{"w": "扎火囤", "t": "预先设置圈套,诱人上当,以诈取钱财"}, {"w": "扎寨;扎寨夫人", "t": "压寨夫人。"}]}, {"meaning": "装扮。", "cites": [{"t": "看那同僚扎甚嘴脸来见我?", "b": "《醒世恒言》"}], "words": [{"w": "扎扮", "t": "装扮"}, {"w": "扎作", "t": "打扮"}, {"w": "扎括", "t": "方言。装扮"}, {"w": "扎裹", "t": "打扮,装扮。"}]}, {"meaning": "张开,揸开。", "cites": [{"t": "只见刘姥姥扎手舞脚的仰卧在床上。", "b": "《红楼梦》"}], "words": [{"w": "扎手舞脚", "t": "兴奋喜悦得将手脚随意置放"}, {"w": "扎煞", "t": "张开;伸张"}, {"w": "扎撒", "t": "张开。"}]}]}, {"pinyin": "zhá", "defs": [{"meaning": "拔。", "cites": [{"t": "贾珍一面扶拐,扎挣着腰蹲身跪下请安道乏。", "b": "《红楼梦》"}], "words": [{"w": "扎蹭", "t": "从困顿中解脱出来。"}]}, {"meaning": "书写。", "cites": [{"t": "有贾人至罗浮山,遇二道士弈。…其一笑曰:“幸托书达吾家。”许诺。即扎书付之。", "b": "宋·米芾《鲁公仙迹记》"}], "words": [{"w": "扎付", "t": "官府的下行公文"}, {"w": "扎费", "t": "给送委任信札差人的赏钱。"}]}, {"meaning": "用同“炸”。", "cites": [{"t": "将孙行者下油锅扎他一炸与我人参树报仇!", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('86wx','艺','1','yì','艹','4','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。甲骨文字形。左上是“木”,表植物;右边是人用双手操作。又写成“埶”,从坴(lù),土块;从丮(jí),拿。后繁化为“藝”。“艺”从“帅”,乙声。本义:种植) 同本义。", "cites": [{"t": "艺,种也。", "b": "《说文》"}, {"t": "艺麻之如何?衡从其亩。", "b": "《诗·齐风·南山》"}, {"t": "不能艺稷黍。", "b": "《诗·唐风·鸨羽》"}, {"t": "艺山林也。", "b": "《左传·昭公十六年》"}, {"t": "树艺五谷。", "b": "《孟子·滕文公上》"}, {"t": "以艺粟菽。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "艺蔬自给。", "b": "清·张廷玉《明史》"}], "words": [{"w": "艺植", "t": "耕种;栽植"}, {"w": "艺人", "t": "耕种的人"}, {"w": "艺圃", "t": "种植花卉园圃。"}]}, {"meaning": "技能;才能。", "cites": [{"t": "求也艺。", "b": "《论语·雍也》"}, {"t": "艺天下无双。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "艺天下第一。", "b": ""}, {"t": "惜罗程艺。", "b": ""}, {"t": "以三保勇而多艺,推为长。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "球艺;艺业", "t": "学术技艺"}, {"w": "艺高人胆大", "t": "指人才技高超,故能不惧险阻,勇往直前。"}]}, {"meaning": "指礼、乐、射、御、书、数六种古代教学科目。", "cites": [{"t": "遂通五经,贯六艺。", "b": "《后汉书·张衡传》"}]}, {"meaning": "指经籍称《诗》、《书》、《礼》、《乐》、《易》、《春秋》六经为六艺。", "cites": [{"t": "能通一艺以上,补文学掌故缺。", "b": "班固《汉书》"}], "words": [{"w": "艺学", "t": "指经学;文章典籍之学。"}]}, {"meaning": "极限。", "cites": [{"t": "骄泰奢侈,贪欲无艺。", "b": "《国语·晋语》"}], "words": [{"w": "艺极", "t": "标准,限度。"}]}, {"meaning": "标准;准则。", "cites": [{"t": "用人无艺。", "b": "《国语·越语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('87wx','木','1','mù','木','4','','[{"pinyin": "mù", "defs": [{"meaning": "(象形。甲骨文字形。象树木形。上为枝叶,下为树根。“木”是汉字的一个部首。从“木”的字表示树木或木器的名称。本义:树木)。"}, {"meaning": "同本义。", "cites": [{"t": "木,冒也。冒地而生。东方之行,从草,下象其根。", "b": "《说文》"}, {"t": "五行,木之为言触也。阳气动跃,触地而出也。", "b": "《白虎通》"}, {"t": "木者,春生之性。农之本也。", "b": "《春秋繁露》"}, {"t": "一树十获者木也。", "b": "《管子·权修》"}, {"t": "庄子行于山中,见大木,枝叶盛茂。", "b": "《庄子·山木》"}, {"t": "舜之居深山之中,与木石居,与鹿豕游。", "b": "《孟子·尽心上》"}, {"t": "草木之花。", "b": "宋·周敦颐《爱莲说》"}, {"t": "鸟兽木石。", "b": "明·魏学洢《核舟记》"}, {"t": "宋无长木。", "b": "《墨子·公输》"}, {"t": "或在木杪。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "花木", "t": "供观赏的花和树木"}, {"w": "木石", "t": "树木与岩石"}, {"w": "木化石", "t": "树木的化石"}, {"w": "木芽", "t": "草木的嫩芽"}, {"w": "木表", "t": "树木的外层;树梢"}, {"w": "木披", "t": "因果实太多而树枝折断"}, {"w": "木斧", "t": "伐木斧头。"}]}, {"meaning": "木料,木材。", "cites": [{"t": "朽木不可雕也。", "b": "《论语》"}, {"t": "我善治木,曲者中钩,直者应绳。", "b": "《庄子·马蹄》"}, {"t": "径寸之木。", "b": "明·魏学洢《核舟记》"}, {"t": "倚一横木。", "b": ""}, {"t": "木格贮之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "木为之者。", "b": ""}], "words": [{"w": "木猫", "t": "木制捕鼠器"}, {"w": "木老鸦", "t": "战船上使用的一种轻便兵器"}, {"w": "木驴", "t": "一种装有轮轴的木制刑具,可载犯人游街示众,用于剐刑"}, {"w": "木弓", "t": "木制的弓"}, {"w": "木瓦", "t": "覆屋面的木板"}, {"w": "木尺", "t": "木制尺"}, {"w": "木功", "t": "木材建筑,制作工艺。"}]}, {"meaning": "树叶。", "cites": [{"t": "无边落木萧萧下,不尽长江滚滚来。", "b": "杜甫《登高》"}], "words": [{"w": "木落", "t": "叶落"}, {"w": "木脉", "t": "叶脉"}, {"w": "木落归本", "t": ""}]}, {"meaning": "棺材。", "cites": [{"t": "原壤登木。", "b": "《礼记·檀弓》。注:“棺材也。”"}, {"t": "我二十五年矣,又如是而嫁,则就木焉。", "b": "《左传·僖公二十三年》"}], "words": [{"w": "行将就木", "t": ""}]}, {"meaning": "某些木制的器物。", "cites": [{"t": "以木讯者。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "麻木;失去知觉。", "cites": [{"t": "贾瑞听了,身上已木了半边。", "b": "《红楼梦》"}], "words": [{"w": "木木然", "t": "神情麻木的样子"}, {"w": "木木樗樗", "t": "形容呆呆的样子"}, {"w": "木立", "t": "呆立,失神站立。"}]}, {"meaning": "朴拙。", "cites": [{"t": "勃为人木强敦厚。", "b": "《史记·绛侯周勃世家》"}], "words": [{"w": "木质", "t": "天性朴拙"}, {"w": "木朴", "t": "质直,朴实"}, {"w": "木强", "t": "—jiàng,质直刚强。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('88wx','五','1','wǔ','二','4','','[{"pinyin": "wǔ", "defs": [{"meaning": "(五,会意。从二,从乂。“二”代表天地,“乂”表示互相交错。本义:交午,纵横交错) 同本义。", "cites": [{"t": "五,阴阳在天地之间交午也。", "b": "《说文》"}, {"t": "葛屦五两。", "b": "《诗·齐风·南山》"}, {"t": "羔羊之皮,素丝五紽。", "b": "《诗·召南·羔羊》"}]}, {"meaning": "四加一的和。", "cites": [{"t": "五,数也。", "b": "《广韵》"}, {"t": "五载一巡守。", "b": "《书·舜典》"}, {"t": "塞其五山。", "b": "唐·李朝威《柳毅传》"}, {"t": "五战于秦。", "b": "宋·苏洵《六国论》"}, {"t": "起则五六揖。", "b": "明·宗臣《报刘一丈书》"}, {"t": "监五室。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "古代军队编制单位,五人为伍。", "cites": [{"t": "入行间之治连以五。", "b": "《商君书》"}]}, {"meaning": "偶;相类。", "cites": [{"t": "妻与后子死者,五皆丧之三年。", "b": "《墨子》"}]}, {"meaning": "工尺谱中的音名之一,表示音阶上的一级。"}, {"meaning": "五行。", "cites": [{"t": "五,五行也。", "b": "《说文》。段玉裁注:“水火木金土,相克相生,阴阳交午也。”"}]}, {"meaning": "古军队编制,五人为伍;行列。", "cites": [{"t": "行间之治,连以五,辨之以章,束之以令。", "b": "《商君书·画策》"}, {"t": "孟贲过于河,先其五。", "b": "《吕氏春秋·必己》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('89wx','支','1','zhī','支','4','','[{"pinyin": "zhī", "defs": [{"meaning": "(会意。小篆字形,上面是“竹”的一半,下面是手(又)。《说文》:“从手持半竹。”本义:去枝的竹子)。"}, {"meaning": "同本义。", "cites": [{"t": "支,去竹之枝也。从手持半竹。", "b": "《说文》。桂馥义证:“疑作去枝之竹也。”"}]}, {"meaning": "枝条", "cites": [{"t": "芄兰之支。", "b": "《诗·卫风·芄兰》"}, {"t": "支叶茂接。", "b": "《汉书》"}, {"t": "以畅其支。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "支调", "t": "枝节"}, {"w": "支蘖", "t": "枝条,旁生树枝"}, {"w": "支辅", "t": "辅助枝叶。"}]}, {"meaning": "分支。", "cites": [{"t": "封弟子功臣自为支辅。", "b": "《史记·李斯列传》"}, {"t": "中小支。", "b": "《后汉书·吕布传》。注:“谓胡也。即今之戟旁曲支。”"}]}, {"meaning": "支流。", "cites": [{"t": "分一支为南江。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "不啻小支。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "支川", "t": ""}]}, {"meaning": "祖宗支系。", "cites": [{"t": "文王孙子,本支百世。", "b": "《诗·大雅·文王》"}], "words": [{"w": "支胄", "t": "支流、宗族的派系分支"}, {"w": "支胤", "t": "后代子孙"}, {"w": "支析", "t": "指分家"}, {"w": "支别", "t": "分支;歧出。"}]}, {"meaning": "支,线及棉纱等的粗细单位。"}, {"meaning": "地支的简称。"}, {"meaning": "", "cites": [{"t": "而畅于四支。", "b": "《易·坤》"}, {"t": "尽其四支动。", "b": "《管子·小匡》"}, {"t": "四支不勤。", "b": "《淮南子·原道》"}, {"t": "四支僵劲不能动。", "b": "明·宋濂《送东阳马生序》"}]}, {"meaning": "支撑。", "cites": [{"t": "诎有右臂支船。", "b": "魏学洢《核舟记》"}], "words": [{"w": "支当", "t": "承当"}, {"w": "支给着", "t": "一条腿抬起压在另一条腿上"}, {"w": "支仗", "t": "支撑维持"}, {"w": "支拽", "t": "支撑,维持"}, {"w": "支措", "t": "支撑筹办。"}]}, {"meaning": "支开,支派。", "cites": [{"t": "再看了看左右无人,只得两个小丫头子,便把那两个小丫头子也支使开。", "b": "《儿女英雄传》"}], "words": [{"w": "支分", "t": "支使;分派"}, {"w": "支末", "t": "支派之末"}, {"w": "支拆", "t": "分摊支付。"}]}, {"meaning": "分,分散。", "cites": [{"t": "支离分赴。", "b": "王逸《鲁灵光殿赋》。注:“分散也。”"}], "words": [{"w": "支破", "t": "支付"}, {"w": "支放", "t": "发放"}, {"w": "支动", "t": "支出;动用。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('90wx','厅','1','tīng','厂','4','','[{"pinyin": "tīng", "defs": [{"meaning": "(形声。从广(yǎn),聽(tīng)声。厅是后起字,大约产生于唐代。古作“聽”。魏晋以来加“广”。本义:堂屋)。"}, {"meaning": "同本义。", "cites": [{"t": "厅,厅屋。", "b": "《广韵》"}, {"t": "凉榭锦厅,其下可坐数百人。", "b": "《洛阳名园记》"}]}, {"meaning": "官署中听事问案之处。", "cites": [{"t": "古者治官处谓之‘听事’;后语省,直曰‘听’,故加广。", "b": "《集韵》"}], "words": [{"w": "官厅", "t": "旧时称政府机关"}, {"w": "厅宇", "t": "厅堂,厅房"}, {"w": "厅屋", "t": "包括厅堂在内的房舍"}, {"w": "厅头", "t": "守厅军士的头目。"}]}, {"meaning": "住宅中通往各房间的大或小空间。", "cites": [{"t": "鸡栖于厅。", "b": "明·归有光《项脊轩志》"}, {"t": "过前后厅。", "b": "清·林觉民《与妻书》"}, {"t": "有小厅。", "b": ""}, {"t": "厅房一室。", "b": ""}], "words": [{"w": "过厅", "t": "可以通往别的房间的厅堂"}, {"w": "三室一厅;两室一厅", "t": ""}]}, {"meaning": "一级政府部门。"}, {"meaning": "清代在府下设厅,与州、县同为地方基层行政机构。其长官为同知或通判。有直隶厅与散厅之别。"}, {"meaning": "清末内阁及各部所设掌理政务之机关。", "words": [{"w": "承宣厅、承政厅、参议厅等", "t": ""}]}, {"meaning": "民国以来,省政府之下设民政厅、财政厅、教育厅等。"}, {"meaning": "现代党政机关的办事机构 。", "words": [{"w": "办公厅", "t": ""}]}, {"meaning": "为营业而容纳多人的房屋 。", "words": [{"w": "歌厅;理发厅;咖啡厅;舞厅", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('91wx','不','1','bù','一','4','','[{"pinyin": "bù", "defs": [{"meaning": "(象形。甲骨文字形,上面象花蒂的子房,下面象花蕊下垂形。①本义:萼足。《诗·小雅·常棣》:“常棣之花,鄂不韡(wěi)。”郑笺:“承华者曰鄂。”②副词。不。《荀子》:“锲而不舍,金石可镂。”)。"}, {"meaning": "用在动词、形容词或个别副词前,表示否定。", "cites": [{"t": "医之好治不病以为功。", "b": "《韩非子·喻老》"}, {"t": "老妇不闻也。", "b": "《战国策·赵策》"}, {"t": "被驱不异犬与鸡。", "b": "唐·杜甫《兵车行》"}, {"t": "后遂不复至。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "不会", "t": ""}, {"w": "不大", "t": ""}, {"w": "不一定", "t": ""}, {"w": "不古", "t": "不古朴。意指社会风气衰落、败坏"}, {"w": "不勾", "t": "不消;不够;不到"}, {"w": "不才", "t": "没有才能。自称的谦词;不成才"}, {"w": "不才之事", "t": "不好的事情。"}]}, {"meaning": "表示事理上或情理上不需要。", "cites": [{"t": "不以累臣衅鼓。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "不客气,不客气", "t": ""}, {"w": "不谢,不谢", "t": ""}]}, {"meaning": "古疑问词。", "cites": [{"t": "句读之不知,惑之不解,或师焉,或不焉。", "b": "唐·韩愈《师说》"}, {"t": "秦王以十五城请易寡人之璧,可与不?", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "用来调整音节。", "cites": [{"t": "徒御不惊,大庖不盈。", "b": "《诗·小雅》。毛传:“不惊,惊也;不盈,盈也。”"}]}, {"meaning": "大。", "cites": [{"t": "不显不承,无射于人斯。", "b": "《诗·周颂·清庙》"}, {"t": "不有而丑天地,非天子之事也。", "b": "《管子·侈靡》"}, {"t": "道其本,至也。至不至无。", "b": "《管子·心术》"}]}, {"meaning": "注意:“不”字在第四声(去声)字前念第二声(阳平),如“不必”(bú bì);“不是”(bú shì)。本词典为方便起见,条目中的“不”字,都注第四声。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('92wx','犬','1','quǎn','犬','4','','[{"pinyin": "quǎn", "defs": [{"meaning": "(象形。“犬”是汉字部首之一。本义:狗)。"}, {"meaning": "同本义。古时特指大狗,后来犬、狗通名。", "cites": [{"t": "犬,狗之有县蹏者也。象形。孔子曰:视犬之字如画狗也。", "b": "《说文》"}, {"t": "效犬者,左牵之。", "b": "《礼记·曲礼》。疏:“大者为犬,小者为狗。”"}, {"t": "食麻与犬。", "b": "《礼记·月令》"}, {"t": "时则有犬祸。", "b": "《洪范五行传》"}, {"t": "犬坐于前。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "牧羊犬;猎犬;警犬;玩赏犬;挽曳犬;皮肉用犬;犬羊", "t": "狗和羊"}, {"w": "犬马", "t": "狗和马"}, {"w": "犬人", "t": "官名。周礼秋官之属。掌理犬牲的官员"}, {"w": "犬服", "t": "古代车上用犬皮制成的兵器袋。"}]}, {"meaning": "称自己的儿子(谦称)。", "cites": [{"t": "这是第二小犬,名叫宝玉。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('93wx','太','1','tài','大','4','','[{"pinyin": "tài", "defs": [{"meaning": "(指事。古作“大”,后语音分化,在“大”字下添加符号,成指事字。本义:过于)。"}, {"meaning": "极大。古作“大”,也作“泰”。凡言大而以为形容未尽,则作太。", "cites": [{"t": "太,大也。", "b": "《广雅·释诂一》段曰:“后世还言,而以为形容未尽,则作太。如大宰俗作太宰。大子俗作太子,周大王俗作太王是也”。"}, {"t": "太亦大也。", "b": "《白虎通·五行》"}, {"t": "易有太极。", "b": "《易·系辞》。注:“大极者。”"}, {"t": "王入太室裸。", "b": "《书·洛诰》"}, {"t": "太上贵德。", "b": "《礼记·曲礼》"}, {"t": "饮而不损兹曰太。", "b": "《后汉书·樊准传》"}], "words": [{"w": "太虚幻境", "t": "天上虚幻的境界"}, {"w": "太清", "t": "天空"}, {"w": "太乙", "t": "古代形成天地万物的元气"}, {"w": "太极", "t": "指整个世界的总和"}, {"w": "太原;太侈", "t": "骄泰奢侈"}, {"w": "太无", "t": "空旷虚无之境。"}]}, {"meaning": "身分最高或辈数更高的。", "cites": [{"t": "太史。", "b": "《汉书·光武纪》。注:“史官之长也。”"}], "words": [{"w": "太夫人;太老师;太老伯;太老爷;太母", "t": "祖母"}, {"w": "太后", "t": "帝王的母亲"}, {"w": "太翁", "t": "曾祖父。"}]}, {"meaning": "大的,广大的。", "cites": [{"t": "太牢。", "b": "《左传·桓公六年》。疏:“牢之大者。”"}], "words": [{"w": "太仓", "t": "京城里贮粮的大仓库"}, {"w": "太息", "t": "亦作“大息”。长长的叹息。"}]}, {"meaning": "古代记数有所超过称“太”。", "cites": [{"t": "汉有天下太半,而诸侯皆附之。", "b": "《史记》"}]}, {"meaning": "安宁的,秩序正常的。也作“泰”。", "cites": [{"t": "不乱离,不知太平之难。", "b": "魏源《默觚上》"}]}, {"meaning": "亨通;顺利。", "cites": [{"t": "命险太甚靡常,道离隆而匪易。", "b": "陆云《九愍》"}]}, {"meaning": "泰阶,星名,即三台。又比喻三公。", "cites": [{"t": "是以玉衡正而太阶平也。", "b": "《汉书·扬雄传下》"}, {"t": "惜乎不登太阶,以尹天下。", "b": "孔融《张俭碑》"}, {"t": "抚剑西南望,思欲赴太山。", "b": "曹植《杂诗六》"}]}, {"meaning": "过于;过分。", "cites": [{"t": "太区区。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "言其太隘。", "b": "宋·司马光《训俭示康》"}, {"t": "畏之太甚。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "又。", "cites": [{"t": "养之太过。", "b": ""}], "words": [{"w": "太半", "t": "大半,过半"}, {"w": "太甚", "t": "太过"}, {"w": "会议不要开得太长;屋里太闷热了,你出去凉凉吧;我对这个问题太没有认识了;他们待我太好了;这个问题确实是太重要了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('94wx','区','1','ōu qū','匚','4','','[{"pinyin": "ōu", "defs": [{"meaning": "一种中国古代容器。又用为容量单位。", "cites": [{"t": "齐旧四量:豆、区、釜、钟。", "b": "《左传·昭公三年》"}]}, {"meaning": "姓氏。", "cites": [{"t": "我区氏儿也。", "b": "唐·柳宗元《童区寄传》"}]}]}, {"pinyin": "qū", "defs": [{"meaning": "(会意。甲骨文字形。从品在匚中。“品”表示许多物品。“匚”(fāng),盛物的器具。本义:收藏)。"}, {"meaning": "隐匿。", "cites": [{"t": "区,踦区,藏匿也。", "b": "《说文》"}, {"t": "吾文君文王作仆区之法。", "b": "《左传·昭公七年》"}]}, {"meaning": "区别。", "cites": [{"t": "譬诸草木,区以别矣。", "b": "《论语·子张》"}], "words": [{"w": "区界", "t": "区别;界限"}, {"w": "区明", "t": "区分明晰"}, {"w": "区判", "t": "区分判别"}, {"w": "区详", "t": "区分详明。"}]}, {"meaning": "区域;地区。", "cites": [{"t": "造我区夏。", "b": "张衡《东京赋》。注:“区,域也。”"}, {"t": "茂八区而菴谒焉。", "b": "左思《蜀都赋》。注:“四方八隅也。”"}, {"t": "上下无常穷六区。", "b": "《思元赋》"}, {"t": "冰天雪海之区。", "b": "〔英〕赫胥黎著、严复译《天演论》"}], "words": [{"w": "区夏", "t": "诸夏。中原地区,指中国"}, {"w": "区宇", "t": "疆土境域"}, {"w": "商店区;山区;市区;边区;区外", "t": "域外"}, {"w": "区宇", "t": "境域;天下。"}]}, {"meaning": "行政区划单位 。如:自治区;解放区;市辖区;县辖区。亦指区政府所在地。如:他在区里开了三天会。"}, {"meaning": "特指小屋。", "cites": [{"t": "浮玉之山,北望具区。", "b": "《山海经·南山经》"}, {"t": "穿北军垒垣以为贾区。", "b": "《汉书·胡建传》。颜师古注:“区者,小室之名,若今小庵屋之类耳。”"}]}, {"meaning": "小,微小。", "cites": [{"t": "宋国区区。", "b": "《左传·襄公十七年》"}, {"t": "区区焉相乐也。", "b": "《吕氏春秋·务大》"}, {"t": "吾道知处暗,夫处明者不见暗中一物,而处暗者能见明有中区事。", "b": "《关尹子》"}], "words": [{"w": "区区", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('95wx','历','1','lì','厂','4','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从謪,厤(lì)声。从“止”,表示与脚、行走有关。本义:经过)。"}, {"meaning": "同本义。", "cites": [{"t": "历,过也。", "b": "《说文》"}, {"t": "深践戎马之地, 足历王庭,垂饵虎口。", "b": "汉·司马迁《报任少卿书》"}, {"t": "历齐河。", "b": "清·姚鼐《登泰山记》"}, {"t": "已历三世。", "b": "《三国志·诸葛亮传》"}, {"t": "身不历农亩之劳。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "历两京左右通政。", "b": "清·张廷玉《明史》"}], "words": [{"w": "身历", "t": "亲身经历"}, {"w": "历时", "t": "所经过的时间"}, {"w": "历劫", "t": "佛教用语。指世界经历多次成、住、坏、空的生灭过程。劫,为宇宙在时间上的一成一毁"}, {"w": "历岁", "t": "经过一年"}, {"w": "历载", "t": "经历多年"}, {"w": "历远", "t": "经历长久"}, {"w": "历纪", "t": "经历的世代。"}]}, {"meaning": "行;游历。", "cites": [{"t": "伏轼撙衔,横历天下。", "b": "《战国策》"}, {"t": "遍历名山,博采方术。", "b": "前蜀·杜光庭《李筌》"}], "words": [{"w": "历聘", "t": "游历天下以求聘用"}, {"w": "历国", "t": "游历各国"}, {"w": "历行", "t": "遍行,走遍"}, {"w": "历块", "t": "穿过一国如过一小块土地。比喻迅速"}, {"w": "历说", "t": "游说。"}]}, {"meaning": "超越;超过。", "cites": [{"t": "礼,朝廷不历位而相与言,不逾阶而相揖也。", "b": "《孟子》"}], "words": [{"w": "历位", "t": "逾越位次"}, {"w": "历阶", "t": "越阶而上"}, {"w": "历涉", "t": "度越。"}]}, {"meaning": "担任;先后担任各种官职。", "cites": [{"t": "历十二官,处事无纤毫过差。", "b": "唐·韩愈文"}]}, {"meaning": "发出;流露。", "cites": [{"t": "兹历情以陈辞兮,荪详聋而不闻。", "b": "《楚辞》"}]}, {"meaning": "审视;察看;推算。", "cites": [{"t": "历象日月星辰。", "b": "《汉书》"}], "words": [{"w": "历物", "t": "分别研究事物之理"}, {"w": "历家", "t": "专门观测推算历象的人。"}]}, {"meaning": "尽;遍。", "cites": [{"t": "今予其敷心腹肾肠,历吉尔百姓于朕志。", "b": "《书·盘庚下》"}, {"t": "历验各种僵石。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "历心", "t": "尽心,重视"}, {"w": "历行", "t": "遍行,走遍"}, {"w": "历问", "t": "遍问"}, {"w": "历阅", "t": "遍读。"}]}, {"meaning": "逐一;逐个地。", "cites": [{"t": "历观文囿,泛览辞林。", "b": "萧统《文选序》"}]}, {"meaning": "又历历可听;历历在目。"}, {"meaning": "分明,清晰。", "cites": [{"t": "口齿自清历。", "b": "左思《娇女》。又如:历然在目"}]}, {"meaning": "稀疏。", "cites": [{"t": "赤垆历彊肥。", "b": "《管子·地员》"}], "words": [{"w": "历齿", "t": "牙齿稀疏。"}]}, {"meaning": "历法,历术。", "cites": [{"t": "君子以治历明时。", "b": "《易·革》"}, {"t": "天文阴阳历算。", "b": "《后汉书·张衡传》"}]}, {"meaning": "历书,按当年的日、周和月顺序载有天文学等资料的出版物。", "cites": [{"t": "视历复开书,便利此月内。", "b": "《孔雀东南飞》"}], "words": [{"w": "航海历", "t": ""}]}, {"meaning": "次第,依次而定。", "cites": [{"t": "命宰历卿大夫至于庶民土田之数,而赋牺牲,以共山林名川之祀。", "b": "《礼记·月令》。注:“历,犹次也。”"}]}, {"meaning": "所有以前的、先前的。", "cites": [{"t": "持历朝圣训授君。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "历世", "t": "历代,过去的各个朝代"}, {"w": "历叶", "t": "历代;以往各代"}, {"w": "历稔", "t": "历年,连年。"}]}, {"meaning": "釜鬲。", "cites": [{"t": "铜历为棺。", "b": "《史记·滑稽列传》"}]}, {"meaning": "", "cites": [{"t": "伏历千驷。", "b": "《汉书·梅福传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('96wx','歹','1','dǎi','歹','4','','[{"pinyin": "dǎi", "defs": [{"meaning": "(象形。本作“歺”,音è。甲骨文字形,象有裂缝的残骨。隶变作“歹”。“歹”是汉字部首之一,从“歹”的字多与死、坏或不吉祥等义有关。①(è)本义:残骨。《说文》:“ 列骨之残也。” ②坏)。"}, {"meaning": "坏。与“好”相对。", "cites": [{"t": "莫怕!莫怕!我们不是歹人,我们是取经的和尚。", "b": "《西游记》"}, {"t": "父亲做歹事,误我受此重罪。", "b": "《宣和遗事》"}]}, {"meaning": "又指不健康的。", "cites": [{"t": "秦氏有几日好些,也有几日歹些。", "b": "《红楼梦》"}]}, {"meaning": "奸细,有异心的人。", "cites": [{"t": "“歹”者,北以是名反侧奸细之称。", "b": "文天祥《上江淮诗序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('97wx','友','1','yǒu','又','4','','[{"pinyin": "yǒu", "defs": [{"meaning": "(会意。甲骨文字形,象顺着一个方向的两只手,表示以手相助。本义:朋友)。"}, {"meaning": "同本义。", "cites": [{"t": "友,同志为友。", "b": "《说文》"}, {"t": "君子以朋友讲习。", "b": "《易·兑》。疏:“同门曰朋,同志曰友。”"}, {"t": "联朋友。", "b": "《周礼·大司徒》"}, {"t": "与朋友交。", "b": "《论语》"}, {"t": "太丘与友。", "b": "《世说新语·方正》"}, {"t": "洛阳亲友如相问,一片冰心在玉壶。", "b": "唐·王昌龄《芙蓉楼送辛渐》"}, {"t": "偕数友出。", "b": "明·袁宏道《满井游记》"}, {"t": "是芋视乃友。", "b": "清·周容《芋老人传》"}, {"t": "朋友之交,至于劝善规过足矣。", "b": "清·刘开《问说》"}], "words": [{"w": "挚友", "t": "亲密的朋友"}, {"w": "友生", "t": "朋友。"}]}, {"meaning": "职官名。王官之近臣。", "cites": [{"t": "王置师、友、文学各一人…友者因文王、仲尼四友之名号。", "b": "《晋书》"}], "words": [{"w": "友学", "t": "职官名。“友”与“文学”的合称。为辅佐、侍从之官。"}]}, {"meaning": "互相合作。", "cites": [{"t": "友,有也,相保有也。", "b": "《释名》"}]}, {"meaning": "结交,与…为友。", "cites": [{"t": "瓒深与先主相友。", "b": "《三国志·先主传》"}, {"t": "古之高士,不臣天子,不友诸侯,…", "b": "顾炎武《日知录》"}], "words": [{"w": "友其人;友结", "t": "结交"}, {"w": "友直", "t": "与正直的人交朋友"}, {"w": "友仁", "t": "与仁者交朋友。"}]}, {"meaning": "给予帮助或支持。", "cites": [{"t": "出人相友。", "b": "《孟子·滕文公上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('98wx','尤','1','yóu','尢','4','','[{"pinyin": "yóu", "defs": [{"meaning": "(形声,小篆字形,从乙,又声。乙象植物屈曲生长的样子,受到阻碍,则显示出它的优异。本义:最优异)。"}, {"meaning": "同本义。", "cites": [{"t": "尤,异也。", "b": "《说文》。朱骏声曰:此字当之猶之古文,犬子也。"}, {"t": "尤,怪也。", "b": "《小尔雅》"}, {"t": "尤,异也。", "b": "《广雅》"}, {"t": "夫有尤物。", "b": "《左传·昭公八年》。注:“异也。”"}, {"t": "而视之尤。", "b": "《左传·襄公二十六年》。服注:“甚也。”"}, {"t": "然有知强弱之所尤。", "b": "《管子·侈靡》。注:“殊绝也。”"}, {"t": "夫子,物之尤也。", "b": "《庄子》"}], "words": [{"w": "尤功", "t": "功绩最卓著。亦指功绩最卓著的人。"}]}, {"meaning": "惊异。", "cites": [{"t": "公饮之酒,厚酬之,赐及从者。司马亦如之。张丐尤之。", "b": "《左传》"}]}, {"meaning": "责备;怪罪。", "cites": [{"t": "尤其室。", "b": "《左传·襄公十五年》。注:“责过也。”"}, {"t": "畜君何尤。", "b": "《孟子》。注:“何尤,无过也。”"}, {"t": "不怨天,不尤人。", "b": "《论语·宪问》"}], "words": [{"w": "尤苦", "t": "苛责;污蔑"}, {"w": "尤恶", "t": "谴责和憎恶"}, {"w": "尤怨", "t": "埋怨;怨恨。"}]}, {"meaning": "过失,罪过。", "cites": [{"t": "废为残贼,莫知其尤。", "b": "《诗·小雅·四月》"}], "words": [{"w": "尤诟", "t": "过失和羞辱"}, {"w": "尤违", "t": "过失;过错"}, {"w": "尤累", "t": "过失。"}]}, {"meaning": "尤其,更加。", "cites": [{"t": "义兴人谓三横,而处尤剧。", "b": "南朝宋·刘义庆《世说新语·自新》"}, {"t": "尤致思于天文阴阳历算。", "b": "《后汉书·张衡传》"}, {"t": "近岁风俗尤为侈靡。", "b": "宋·司马光《训俭示康》"}, {"t": "然是说也,余尤疑之。", "b": "宋·苏轼《石钟山记》"}, {"t": "予此行所负之责任,尤倍重于三十年前。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "尤甚;尤妙", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('99wx','匹','1','pǐ','匚','4','','[{"pinyin": "pǐ", "defs": [{"meaning": "(会意。据金文,象以山崖的凹凸不平来比喻布的摺皱。本义:中国古代计算布帛的单位,四丈为匹)。"}, {"meaning": "量词。用于纺织品或缧马等。", "cites": [{"t": "匹,四丈也。", "b": "《说文》"}, {"t": "遂成丈匹。", "b": "《后汉书·列女传》"}, {"t": "半匹红绡一丈绫。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "匹练", "t": "一匹白绢"}, {"w": "匹帛", "t": "泛指纺织品"}, {"w": "匹段", "t": "泛指丝织品。"}]}, {"meaning": "志同道合的人;伴侣;配偶。", "cites": [{"t": "常以鳏旷多感,或谋新匹。", "b": "李朝威《柳毅传》"}], "words": [{"w": "匹夫匹妇", "t": "指平民男女。泛指常人"}, {"w": "匹夫小谅", "t": "指老百姓所抱守的小节小信"}, {"w": "匹夫沟渎", "t": "拘守普通人的小信小节"}, {"w": "匹群", "t": "犹伴侣,伙伴"}, {"w": "匹双", "t": "匹偶,配偶。"}]}, {"meaning": "同类;友辈。", "cites": [{"t": "无怨无恶,率由群匹。", "b": "《诗·大雅·假乐》"}], "words": [{"w": "匹畴,匹俦", "t": "同类"}, {"w": "匹侪", "t": "同类;同伴。"}]}, {"meaning": "匹敌,对手。", "cites": [{"t": "似此良医,世罕其匹,未可废也。", "b": "《三国演义》"}], "words": [{"w": "世无其匹", "t": ""}]}, {"meaning": "二人。", "cites": [{"t": "畴匹,二人为匹,四人为畴。", "b": "玄应《一切经音义》"}]}, {"meaning": "比喻。", "cites": [{"t": "匹诸俘伪。", "b": "魏·贾思勰《齐民要术》"}, {"t": "匹如元不到京来。", "b": "元稹《酬乐天醉别》"}]}, {"meaning": "匹敌;比得上,相当。", "cites": [{"t": "作丰伊匹。", "b": "《诗·大雅·文王有声》。传:“匹,配也。”"}, {"t": "秦晋匹也,何以卑我?", "b": "《左传·僖公二十三年》"}, {"t": "怀质抱情,独无匹兮。", "b": "《楚辞·九章·怀沙》"}], "words": [{"w": "天下谁能匹;匹休", "t": "比配;媲美"}, {"w": "匹比", "t": "比"}, {"w": "匹耦", "t": "投合"}, {"w": "匹遇", "t": "遇合"}, {"w": "匹亚", "t": "不相上下,势均力敌"}, {"w": "匹驰", "t": "并驰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('100wx','车','1','chē jū','车','4','','[{"pinyin": "chē", "defs": [{"meaning": "(象形。甲骨文有多种写法。象车形。本义:车子,陆地上有轮子的运输工具)。"}, {"meaning": "同本义。", "cites": [{"t": "車,舆论之总名。夏后时奚仲所造。象形。", "b": "《说文》。按,横视之肖,或云车少昊时驾牛,奚仲始驾马。"}, {"t": "为车。大车、柏车、羊车,皆两辕,驾牛;田车、兵车、乘车,皆一辀,驾马。大车,平地任载车,柏车、山车,羊车、善车也;田车、兵车,乘车,通谓之小车。", "b": "《考工记·舆人》"}, {"t": "车从马。", "b": "《左传·闵公元年》"}, {"t": "车斑内外。", "b": "《国语·晋语》。注:“车雷也。”"}, {"t": "车同轨,书同文字。", "b": "《史记·秦始皇本纪》"}, {"t": "晓驾炭车辗冰辙。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "开车", "t": ""}, {"w": "安步当车", "t": ""}, {"w": "杯水车薪", "t": ""}, {"w": "闭门造车", "t": ""}, {"w": "螳臂当车", "t": ""}, {"w": "车两 ", "t": "古谓车一乘为一两"}, {"w": "车盖", "t": "古代车上的伞形车篷。亦指具有此种车篷的车辆"}, {"w": "车辐", "t": "连接车轮的边缘和车轮中心的直木条"}, {"w": "车马辐辏", "t": "形容车马拥挤的情况。"}]}, {"meaning": "特指战车,兵车。", "cites": [{"t": "比至陈,车六七百乘,骑千余,卒数万人。", "b": "《史记·陈涉世家》"}, {"t": "车辚辚,马萧萧,行人弓箭各在腰。", "b": "唐·杜甫《兵车行》"}]}, {"meaning": "乘车。", "cites": [{"t": "济济群英,车的车,步的步,陆续来了。", "b": "清·心青《女界文明灯弹词》"}]}, {"meaning": "姓。"}]}, {"pinyin": "jū", "defs": [{"meaning": "国际象棋中的一种棋子,它可以顺着平行于棋盘边的路随便走多少方格,假如没有其它棋子阻挡的话。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('101wx','巨','1','jù','工','4','','[{"pinyin": "jù", "defs": [{"meaning": "(象形。金文字形,是“矩”的本字,象人持矩形。本义:画直角方形用的工具)。"}, {"meaning": "同本义", "cites": [{"t": "巨,规巨也。", "b": "《说文》"}, {"t": "是以君子有挈巨之道也。", "b": "《礼记·大学》"}, {"t": "成功之术,必有巨矱。", "b": "《管子·宙合》"}], "words": [{"w": "巨矱", "t": "法度。同“矩矱”。"}]}, {"meaning": "距离。", "cites": [{"t": "守为台城,以临羊黔,左右出巨,各二十尺。", "b": "《墨子》"}]}, {"meaning": "大;很大。", "cites": [{"t": "巨,大也。", "b": "《小尔雅》"}, {"t": "力士举巨囊。", "b": "《公羊传·哀公六年》"}, {"t": "右巨指钩弦。", "b": "《仪礼·大射仪》"}, {"t": "穹崖巨谷。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "巨石岿然。", "b": ""}, {"t": "巨幅悬之。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "巨弹堕地。", "b": ""}, {"t": "劝输巨室。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "巨响", "t": "极大的响声"}, {"w": "巨指", "t": "大指"}, {"w": "巨港", "t": "大港"}, {"w": "巨室", "t": "大厦,大屋;公卿大夫之家"}, {"w": "巨蠹", "t": "喻祸国殃民的大奸。"}]}, {"meaning": "岂,难道。", "cites": [{"t": "沛公不先破关中兵,公巨能入乎?", "b": "《汉书·高帝纪》"}], "words": [{"w": "巨能", "t": "岂能。"}]}, {"meaning": "最。", "cites": [{"t": "言不尽于此,颇难悉载,故粗举其巨怪者。", "b": "曹植《辩道论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('102wx','牙','1','yá','牙','4','','[{"pinyin": "yá", "defs": [{"meaning": "(象形。金文字形,象上下牙齿交错形。“牙”是汉字的一个部首。本义:槽牙)。"}, {"meaning": "大牙,臼齿。古时,当唇者称齿,在辅车之后者称牙。", "cites": [{"t": "牙,牡齿也。象上下相错之形。", "b": "《说文》"}, {"t": "皮草齿牙。", "b": "《左传·隐公五年》。疏:“颔上大齿谓之牙。”"}, {"t": "谁谓鼠无牙?何以穿我墉?", "b": "《诗·召南·行露》"}], "words": [{"w": "牙祭", "t": "旧指东家给伙计在每月初二、十六吃肉食"}, {"w": "牙疼咒", "t": "牙疼誓。无关紧要的咒。"}]}, {"meaning": "形状像齿的东西。", "cites": [{"t": "檐牙高啄。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "狼牙山", "t": ""}]}, {"meaning": "特指象牙。", "cites": [{"t": "牙旗缤纷。", "b": "班固《东京赋》。注:“古者天子出建大牙旗,竿上以象牙饰之。”"}], "words": [{"w": "牙樯", "t": "饰有象牙的桅杆"}, {"w": "牙牌", "t": "骨牌。用象牙、竹、木或兽骨制的赌具,也用来占卜或娱乐。共三十二张,上面刻有点数"}, {"w": "牙色", "t": "与象牙相似的淡黄颜色"}, {"w": "牙梳", "t": "象牙梳子"}, {"w": "牙章", "t": "象牙的印章。"}]}, {"meaning": "萌芽。", "cites": [{"t": "霍氏有事萌牙。", "b": "《汉书·金日磾传》"}, {"t": "繁愤未发,萌兆牙蘖。", "b": "《淮南子·俶真》"}, {"t": "外之有徒,祸乃始牙。", "b": "《管子·版法》"}]}, {"meaning": "孩童。", "cites": [{"t": "唐且华颠以悟秦,甘罗童牙而报赵。", "b": "《后汉书·崔駰传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('103wx','屯','1','tún zhūn','屮','4','','[{"pinyin": "tún", "defs": [{"meaning": "(会意。从屮贯一。屮(chè),草。一,土地。象草木初生的艰难。①(zhūn)本义:艰难。②引申义:聚集)。"}, {"meaning": "聚集。", "cites": [{"t": "屯,聚也。", "b": "《广雅·释诂三》"}, {"t": "胜广皆为屯长。", "b": "《汉书·陈胜传》。师古曰:“人所聚曰屯。”"}, {"t": "火与日,吾屯也。", "b": "《庄子·寓言》"}, {"t": "屯骑罗而星布。", "b": "张衡《思玄赋》"}], "words": [{"w": "屯聚", "t": "会合,聚集"}, {"w": "屯屯", "t": "聚集"}, {"w": "屯合", "t": "聚集"}, {"w": "屯行", "t": "集中行进"}, {"w": "屯萃", "t": "聚集"}, {"w": "屯结", "t": "聚集;集结"}, {"w": "屯塞", "t": "聚拢堵塞"}, {"w": "屯师", "t": "集结军队"}, {"w": "屯居", "t": "聚居。"}]}, {"meaning": "戍守,驻扎。", "cites": [{"t": "屯大泽乡。", "b": "《史记·陈涉世家》"}, {"t": "屯于境上。", "b": "《史记·魏公子列传》"}, {"t": "屯新野。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "屯封", "t": "屯守之地"}, {"w": "屯堡", "t": "军队戍守的保垒"}, {"w": "屯卫", "t": "派兵驻守护卫"}, {"w": "屯籍", "t": "登载屯兵的名册"}, {"w": "屯夫", "t": "守卒"}, {"w": "屯列", "t": "布防,屯驻"}, {"w": "屯次", "t": "驻扎"}, {"w": "屯防", "t": "驻兵防御"}, {"w": "屯住", "t": "屯驻。驻守"}, {"w": "屯泊", "t": "驻扎。"}]}, {"meaning": "积聚。聚集储存起来。", "cites": [{"t": "蜂屯蚁杂,不可爬搜。", "b": "唐·韩愈《送郑尚书序》"}], "words": [{"w": "屯积", "t": "积聚财货"}, {"w": "屯粮;屯积居奇", "t": "把奇货储存起来,待机高价出售"}, {"w": "屯云", "t": "积聚的云气。"}]}, {"meaning": "兵营。", "cites": [{"t": "请以令发师置屯籍农。", "b": "《管子》"}]}, {"meaning": "小山。", "cites": [{"t": "生于陵屯。", "b": "《庄子·至乐》"}]}, {"meaning": "河港靠船之处。", "cites": [{"t": "有七十二道深河港屯。", "b": "《黄花峪》"}]}, {"meaning": ",由十八个月、每月二十天构成的三百六十天的周期,并且用作再加五天的三百六十五天的马雅历长年的基础。"}]}, {"pinyin": "zhūn", "defs": [{"meaning": "艰难;困顿。", "cites": [{"t": "屯,难也。象草木之初生。屯然而难。从屮,贯一尾曲。一,地也。指事。", "b": "《说文》"}, {"t": "屯者,物之始生也。", "b": "《易·序卦》"}, {"t": "屯见而不失其居。", "b": "《易·杂卦》"}, {"t": "曰屯。刚柔始交而难生。", "b": "《易》"}, {"t": "见僧心暂静,从俗事多屯。", "b": "唐·项斯《落第后归觐喜逢僧再阳》"}], "words": [{"w": "屯穷", "t": "困顿贫穷"}, {"w": "屯邅", "t": "困顿不得志"}, {"w": "屯蹇", "t": "艰难困苦,不顺利"}, {"w": "屯謇", "t": "艰难,不顺利"}, {"w": "屯蹶", "t": "艰难困顿。"}]}, {"meaning": "吝惜。", "cites": [{"t": "屯其膏。", "b": "《易·屯》"}], "words": [{"w": "屯膏", "t": "吝于对下广施德泽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('104wx','戈','1','gē','戈','4','','[{"pinyin": "gē", "defs": [{"meaning": "(象形。甲骨文字形,象一种长柄兵器形。本义:一种兵器)。"}, {"meaning": "中国古代的主要兵器。", "cites": [{"t": "戈,平头戟也。从弋、一,横之象形。", "b": "《说文》。按,戈者,柲也,长六尺六寸,其刃横出,可勾可击,与矛专刺、殳专击者不同,亦与戟之兼刺与勾者异。"}, {"t": "执戈上刃。", "b": "《书·顾命》"}, {"t": "称尔戈。", "b": "《书·牧誓》"}, {"t": "戈广二寸。", "b": "《考工记·冶氏》"}, {"t": "操吴戈兮被犀甲,车错毂兮短兵接。", "b": "《楚辞·屈原·国殇》"}]}, {"meaning": "泛指兵器。", "cites": [{"t": "左右军士,皆全装贯带,持戈执戟而立。", "b": "《三国演义》"}, {"t": "能执干戈以卫社稷。", "b": "《礼·檀弓下》"}], "words": [{"w": "戈兵", "t": "兵器。也指战争"}, {"w": "干戈", "t": "泛指武器;喻指战争。"}]}, {"meaning": "战争;战乱。", "cites": [{"t": "偃武息戈,卑辞事汉。", "b": "《后汉书·公孙述传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('105wx','比','1','bǐ','比','4','','[{"pinyin": "bǐ", "defs": [{"meaning": "(会意。从二匕,匕亦声。甲骨文字形,象两人步调一致,比肩而行。它与“从”字同形,只是方向相反。《说文》:“二人为从,反从为比。”本义:并列;并排)。"}, {"meaning": "同本义。", "cites": [{"t": "比物四骊。", "b": "《诗·小雅·六月》"}, {"t": "南方有比翼鸟焉,不比不飞,其名谓之鹣鹣。", "b": "《尔雅·释鸟》"}, {"t": "危东六星,两两相比曰司空。", "b": "《史记·天官书》"}, {"t": "比其具。", "b": "《周礼·世妇》。注:“次也。”"}, {"t": "及献比禽。", "b": "《周礼·田仆》"}, {"t": "子比而同之,是乱天下也。", "b": "《孟子·滕文公上》"}, {"t": "比诸侯之列,给贡职如郡县。", "b": "《战国策·燕策》"}, {"t": "纳比笼中。", "b": "《聊斋志异·促织》"}], "words": [{"w": "比肩", "t": "肩碰肩,谓高矮差不多"}, {"w": "比物", "t": "排比同类事物"}, {"w": "比集", "t": "排比汇集"}, {"w": "比缀", "t": "编排连缀。"}]}, {"meaning": "连接,接近。", "cites": [{"t": "家人失火,屋比延烧。", "b": "《史记·汲黯列传》"}], "words": [{"w": "比户", "t": "比家,比舍,比屋。一家挨着一家;家家户户"}, {"w": "比屋", "t": "隔壁"}, {"w": "比里", "t": "邻里,乡里。"}]}, {"meaning": "比较;考校,核对。", "cites": [{"t": "与天地兮比寿,与日月兮齐光。", "b": "《楚辞·涉江》"}], "words": [{"w": "比量", "t": "比照"}, {"w": "比类", "t": "比照旧例"}, {"w": "比句", "t": "核对检查簿籍"}, {"w": "比次", "t": "考校"}, {"w": "比并", "t": "相比"}, {"w": "比势", "t": "较量武艺;比试"}, {"w": "比迸", "t": "比武较量。"}]}, {"meaning": "及,等到。", "cites": [{"t": "比至定陶,再破秦军。", "b": "《史记·项羽本纪》"}]}, {"meaning": "勾结;偏爱。", "cites": [{"t": "君子周而不比,小人比而不周。", "b": "《论语·为政》"}, {"t": "立其子,不为比(偏爱)。", "b": "《左传·襄公三年》"}], "words": [{"w": "朋比为奸", "t": ""}, {"w": "比周", "t": "勾结"}, {"w": "比党", "t": "拉帮结派。"}]}, {"meaning": "等同。", "cites": [{"t": "刑余之人,无所比数。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "比伍", "t": "等同,匹敌"}, {"w": "比伉", "t": "匹偶。"}]}, {"meaning": "具备。", "cites": [{"t": "比乐官,展乐器。", "b": "《周礼·大胥》"}, {"t": "及祭祀,比其具。", "b": "《周礼·世妇》"}, {"t": "以敦比其事业。", "b": "《荀子·荣辱》"}]}, {"meaning": "官府限期办好公事。", "cites": [{"t": "宰严限追比。(追征。县令严定期限,催促交纳。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "比捕", "t": "限期捉拿人犯"}, {"w": "比卯", "t": "旧时地方衙门中差役的名簿叫“卯簿”。百姓有欠粮的,按卯簿派差役去催缴,如到期不缴,拘衙受刑叫“比卯”。"}]}, {"meaning": "接近;亲近。", "cites": [{"t": "使小国事大国,大国比小国。", "b": "《周礼·夏官》"}], "words": [{"w": "比近", "t": "亲近"}, {"w": "比周", "t": "亲近"}, {"w": "比昵", "t": "亲近"}, {"w": "比善", "t": "和睦亲近"}, {"w": "比日", "t": "近日;每日"}, {"w": "比世", "t": "近世,近代"}, {"w": "比辰", "t": "近时,近日"}, {"w": "比者", "t": "近来"}, {"w": "比岁", "t": "近年"}, {"w": "比际", "t": "此时,这时。"}]}, {"meaning": "密(与“稀”、“疏”相对)。", "cites": [{"t": "比,密也。", "b": "《说文》"}, {"t": "其比如栉。", "b": "《诗·周颂·良耜》"}, {"t": "是与比周。", "b": "《左传·文公十八年》。注:“比,近也。周密也。”"}], "words": [{"w": "比甲", "t": "马甲。"}]}, {"meaning": "和谐。", "cites": [{"t": "声比则应。", "b": "班固《汉书》"}]}, {"meaning": "皆,都,同等地。", "cites": [{"t": "再战比胜。", "b": "《战国策·齐策》"}], "words": [{"w": "比隆", "t": "同等兴盛"}, {"w": "比行", "t": "并行。"}]}, {"meaning": "连续,频频。", "cites": [{"t": "比投不释。", "b": "《礼记·投壶》"}, {"t": "间者数年比不登。", "b": "《汉书·文帝纪》"}, {"t": "比年日蚀。", "b": "《汉书·张延寿传》"}, {"t": "三人比坐事死。", "b": "《汉书·公孙贺传》"}, {"t": "地比震动。", "b": "《汉书·翼奉传》"}, {"t": "比三年日蚀。", "b": "《汉书·外戚传》"}, {"t": "始至之时,岁比不登。(登:丰收)", "b": "苏轼《超然台记》"}]}, {"meaning": "近来。", "cites": [{"t": "臣比在晋也,不敢直言。", "b": "《吕氏春秋·先织》"}]}, {"meaning": "比起。", "cites": [{"t": "比吾乡邻之死则已后矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "曹操比于袁绍。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "他比你高", "t": ""}]}, {"meaning": "为;替。", "cites": [{"t": "寡人耻之,愿比死者一洒之。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "及,等到。", "cites": [{"t": "比至陈,车六七百乘,骑千余。", "b": "《史记·陈涉世家》"}, {"t": "比至南郡,而琮已降。", "b": "《资治通鉴》"}, {"t": "比去,以手阖门。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('106wx','互','1','hù','二','4','','[{"pinyin": "hù", "defs": [{"meaning": "(象形。是一种绞绳用的工具。本义:绞绳用的工具)。"}, {"meaning": "同本义。", "cites": [{"t": "段玉裁注:“今绞绳者尚有此器。从竹,象形,谓其物象工字;中象人手推握也。”", "b": ""}]}, {"meaning": "差错。", "cites": [{"t": "各有乘互。", "b": "陆法言《切韵序》"}]}, {"meaning": "古代挂肉的木架。", "cites": [{"t": "共其牛牲之互。", "b": "《周礼·牛人》。郑玄注:“互,若今屠家县肉格。”"}, {"t": "置互摆牲。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "交替;相互。", "cites": [{"t": "互,交互。", "b": "《字汇》"}, {"t": "胡笳互动。", "b": "李陵《答苏武书》"}, {"t": "以参互考日成。", "b": "《周礼·司会》"}, {"t": "宗族盘互。", "b": "《汉书·刘向传》"}, {"t": "渔歌互答。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "互芬齿颊。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "体面互见。", "b": "蔡元培《图画》"}, {"t": "更互用之。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "互易", "t": "法律名词。即当事人双方约定互相移转金钱以外财产权的契约。古代以物易物,便是互易"}, {"w": "互保", "t": "互相保证"}, {"w": "互训", "t": "两个同义词彼此互相解释"}, {"w": "互结", "t": "人民对官署,须具两个人或两家以上的店铺互相保证的信约。"}]}, {"meaning": "交接。", "cites": [{"t": "春夏相与交,秋冬相与互。", "b": "《书·尧典》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('107wx','切','1','qiē qiè','刀','4','','[{"pinyin": "qiē", "defs": [{"meaning": "台阶。", "cites": [{"t": "切皆铜沓黄金涂。", "b": "《汉书·外戚·孝成赵皇后传》"}]}, {"meaning": "(形声。从刀,七声。本义:用刀把物品分成若干部分)。"}]}, {"pinyin": "qiè", "defs": [{"meaning": "摩擦;接触。", "cites": [{"t": "切,摩也。", "b": "《广雅》"}, {"t": "不待切脉。", "b": "《史记·扁鹊仓公传》"}, {"t": "可切循把握。", "b": "《淮南子·原道》"}], "words": [{"w": "切齿", "t": "咬紧牙齿。形容痛恨"}, {"w": "切磨", "t": "摩擦;摩搓"}, {"w": "切摩", "t": "摩擦"}, {"w": "切循", "t": "抚摩。"}]}, {"meaning": "一定要。", "cites": [{"t": "诸位切不可乱动。", "b": "《老残游记》"}], "words": [{"w": "切照", "t": "依照;按照"}, {"w": "切须", "t": "必须;切要"}, {"w": "切不可骄傲;切勿吸烟;切勿", "t": "务必不要"}, {"w": "切戒", "t": "务须避免"}, {"w": "切莫", "t": "务必不要"}, {"w": "切须", "t": "务必。"}]}, {"meaning": "靠近;贴近。", "cites": [{"t": "切于身心。", "b": "清·刘开《问说》"}], "words": [{"w": "切倚", "t": "相依相偎,十分亲昵"}, {"w": "切邻", "t": "近邻"}, {"w": "切心", "t": "贴身"}, {"w": "亲切", "t": "亲近;密切。"}]}, {"meaning": "急切;急迫。", "cites": [{"t": "切问而近思。", "b": "《论语》。皇疏:“犹急也。”"}, {"t": "饥冻虽切,违己交病。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "迨诉频切。", "b": "唐·李朝威《柳毅传》"}, {"t": "其切如是。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "出国心切;激切", "t": "言语直而急"}, {"w": "心切", "t": "心情急迫"}, {"w": "切峻", "t": "急切严厉"}, {"w": "切事", "t": "迫切的事"}, {"w": "切问", "t": "急切问难"}, {"w": "切紧", "t": "迫切、要紧。"}]}, {"meaning": "深;深切。", "cites": [{"t": "切,深也。", "b": "《汉书·霍光传》注"}], "words": [{"w": "切恐", "t": "深怕"}, {"w": "切爱", "t": "深深的爱"}, {"w": "痛切", "t": "悲痛而深切"}, {"w": "切究", "t": "深究"}, {"w": "切怛", "t": "深切悲伤"}, {"w": "切谢", "t": "深切感谢。"}]}, {"meaning": "恳切;率直。", "cites": [{"t": "直言世谏。", "b": "《汉书·东方朔传》"}], "words": [{"w": "切谓", "t": "恳切地说"}, {"w": "切劝", "t": "诚恳地相劝"}, {"w": "热切", "t": "热烈恳切"}, {"w": "切至", "t": "恳切周至。"}]}, {"meaning": "严厉。", "cites": [{"t": "故为政以苛为察,以切为明…大败大裂之道也。", "b": "《文子·上礼》"}], "words": [{"w": "切责", "t": "严厉谴责"}, {"w": "切让", "t": "严厉责备"}, {"w": "切厉", "t": "严厉。"}]}, {"meaning": "激烈。", "cites": [{"t": "旋以论事过切,为宰臣所非。", "b": "韩愈《为裴相公让官表》"}], "words": [{"w": "切论", "t": "激切的议论"}, {"w": "切愕", "t": "谓激切直言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('108wx','瓦','1','wǎ wà','瓦','4','','[{"pinyin": "wǎ", "defs": [{"meaning": "(象形。象屋瓦俯仰相承的样子。“瓦”是汉字的一个部首。本义:已烧土器的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "瓦,土器已烧之总名。", "b": "《说文》"}, {"t": "神农作瓦器。", "b": "《周书》"}, {"t": "夏时昆吾作瓦。", "b": "《礼记·有虞上陶世本云》"}, {"t": "载弄之瓦。", "b": "《诗·小雅·斯干》。传:“纺砖也。”"}], "words": [{"w": "瓦大", "t": "瓦制的酒器"}, {"w": "瓦缶", "t": "口小腹大的瓦器"}, {"w": "瓦器", "t": "用泥土烧制的器皿"}, {"w": "瓦伶", "t": "陶瓦制的偶像"}, {"w": "瓦卮", "t": "陶制的盛酒器"}, {"w": "瓦豆", "t": "古代陶制的一种礼器"}, {"w": "瓦兆", "t": "瓦卜。古代占卜法之一。击瓦定吉凶"}, {"w": "瓦池", "t": "墨盆"}, {"w": "瓦盎", "t": "瓦制的盆器"}, {"w": "瓦窑", "t": "烧制砖瓦陶瓷器的灶。戏称生女孩较多的妇女,因为旧时生女叫“弄瓦”"}, {"w": "瓦木作", "t": "泥瓦工和木工"}, {"w": "瓦灶绳床", "t": "形容生活贫困"}, {"w": "瓦楞帽子", "t": "明代平民便帽"}, {"w": "瓦注", "t": "以瓦器为赌注。后喻贱物轻掷。"}]}, {"meaning": "屋瓦。", "cites": [{"t": "瓦缝参差。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "铜瓦;石绵瓦;木瓦;琉璃瓦;瓦衣", "t": "生长在屋瓦阴处的苔藓类植物"}, {"w": "瓦沼", "t": "瓦盆般的水池"}, {"w": "瓦沟", "t": "瓦楞之间的泄水沟"}, {"w": "瓦甃", "t": "屋檐。"}]}, {"meaning": "功率单位,瓦特的简称。"}, {"meaning": "盾脊,盾背拱起如覆瓦的部分。", "cites": [{"t": "齐子渊捷从泄声子,射之,中楯瓦。", "b": "《左传·昭公二十六年》"}]}, {"meaning": "宋、元时都市中的游乐、贸易场所。也称“瓦子”、“瓦舍”、“瓦肆”或“瓦市”。", "cites": [{"t": "临安中瓦在御街中,士大夫心游之地,天下术士皆聚焉。", "b": "《贵耳集·下》"}]}, {"meaning": "古八音中“土”的别称。", "cites": [{"t": "匏以宣之,瓦以赞之。", "b": "《国语》"}]}, {"meaning": "地名 。春秋时卫地,在今河南省滑县南。", "cites": [{"t": "公会晋师于瓦。", "b": "《春秋·定公八年》"}]}, {"meaning": "姓。"}]}, {"pinyin": "wà", "defs": [{"meaning": "用瓦覆盖;铺瓦。", "cites": [{"t": "瓦屋梁。", "b": "《急就篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('109wx','止','1','zhǐ','止','4','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(“趾”的本字。象形。甲骨文字形。上象脚趾头,下象脚面和脚掌。本义:脚) 同本义。", "cites": [{"t": "止,下基也。象草木出有址,故以止为足。", "b": "《说文》"}, {"t": "北止。", "b": "《仪礼·士昏礼》。注:“足也。”"}, {"t": "屦校灭止。", "b": "《易·噬嗑》"}, {"t": "举止高。", "b": "《汉书·五行志》"}, {"t": "四之日举止。", "b": "《汉书·食货志》"}, {"t": "当劓者,笞三百,当斩左止者,笞五百。", "b": "《汉书·刑法志》"}]}, {"meaning": "停住,中断进程。", "cites": [{"t": "止,停也,息也。", "b": "《广韵》"}, {"t": "亦可以止矣。", "b": "《吕氏春秋·下贤》。注:“止,休也。”"}, {"t": "树欲静而风不止,子欲养而亲不待也。", "b": "《韩诗外传》"}, {"t": "羽飞乃止。", "b": "《三国志·诸葛亮传》"}, {"t": "雪止。", "b": "《资治通鉴·唐纪》"}, {"t": "一狼得骨止,一狼仍从。", "b": "《聊斋志异·狼三则》"}, {"t": "絮絮不止。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "渐拍断止。", "b": ""}], "words": [{"w": "止步;止怒;止泻;止戈", "t": "停止干戈,平息战争"}, {"w": "止止", "t": "犹止之;停止,止住"}, {"w": "止雨", "t": "使雨停止"}, {"w": "止泊", "t": "停息"}, {"w": "止军", "t": "让军队停止前进。"}]}, {"meaning": "阻止,不让进行。", "cites": [{"t": "笑而止之。", "b": "《列子·汤问》"}, {"t": "相如止臣。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "又。", "cites": [{"t": "相如固止。", "b": ""}, {"t": "使人止晋鄙。", "b": "《史记·魏公子列传》"}, {"t": "年兄肯出一言止了此事。", "b": "清·狄夷散人《玉娇梨》"}], "words": [{"w": "止遏", "t": "阻止;抑制"}, {"w": "止哭", "t": "止住哭声"}, {"w": "止善", "t": "阻止别人做好事"}, {"w": "止节", "t": "阻塞;节制,抑制"}, {"w": "止塞", "t": "阻止,堵塞"}, {"w": "止暴", "t": "制止暴戾行为。"}]}, {"meaning": "居住。", "cites": [{"t": "邦畿千里,维民所止。", "b": "《诗·商颂·玄鸟》"}, {"t": "止文殊院。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "止息", "t": "住宿;休息"}, {"w": "止居", "t": "安居;定居"}, {"w": "止托", "t": "寄居。"}]}, {"meaning": "停留,逗留。", "cites": [{"t": "南阳西郊有一亭,人不可止,止则有祸。", "b": "《搜神记》"}, {"t": "止子路宿。(止,使……留下。)", "b": "《论语·微子》"}], "words": [{"w": "止顿", "t": "止留。停留"}, {"w": "止泊", "t": "停息"}, {"w": "止于至善", "t": "处于最完美的境界。"}]}, {"meaning": "仅;只。", "cites": [{"t": "技止此耳。", "b": "唐·柳宗元《三戒》"}, {"t": "止印二三本。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "只十有一日。", "b": "明·张溥《五人墓碑记》"}, {"t": "止增笑耳。", "b": "《聊斋志异·狼三则》"}]}, {"meaning": "又。", "cites": [{"t": "止露尻尾。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "止有剩骨", "b": ""}], "words": [{"w": "止衣", "t": "只穿"}, {"w": "止可", "t": "只能;只可"}, {"w": "止剩下一篇文章还没有抄完;止有此数了", "t": ""}]}, {"meaning": "在句末可表肯定陈述语气,相当于“呢”。", "cites": [{"t": "高山仰止,景行行止。(景行:大道。)", "b": "《诗·小雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('110wx','少','1','shǎo','小','4','','[{"pinyin": "shǎo", "defs": [{"meaning": "(会意。小篆从小,丿(piě)声。本义:不多)。"}, {"meaning": "同本义。", "cites": [{"t": "少,不多也。", "b": "《说文》"}, {"t": "少,微也。", "b": "《太玄·玄衡》"}, {"t": "夫少者,多之所贵也。", "b": "《易·略例》"}, {"t": "宾少进。", "b": "《仪礼·乡射礼》"}, {"t": "险以远,则至者少。", "b": "宋·王安石《游褒禅山记》"}, {"t": "人民少而财有余。", "b": "《韩非子·五蠹》"}], "words": [{"w": "少一时", "t": "少时,过一会儿"}, {"w": "少可", "t": "少,至少;稍好,稍愈"}, {"w": "少冗", "t": "较忙"}, {"w": "少甚么", "t": "少甚末,少是末,少甚。有的是,不少,不希罕"}, {"w": "少才", "t": "小聪明"}, {"w": "少年", "t": "不几年"}, {"w": "少好", "t": "少而精"}, {"w": "少言寡语", "t": "谓平时说话不多"}, {"w": "少说", "t": "说少一点"}, {"w": "少气", "t": "气不足。"}]}, {"meaning": "薄弱。", "cites": [{"t": "力少而不畏强。", "b": "《韩非子》"}]}, {"meaning": "", "cites": [{"t": "仲春之月,安萌芽,养幼少,存诸孤。", "b": "《礼记·月令》"}, {"t": "武王崩,成王幼少。", "b": "《淮南子·汜论》"}, {"t": "朝廷幼少,恃我而已。", "b": "《后汉书·王允传》"}, {"t": "尿不能卒出,痛引少腹。", "b": "《诸病源候论·石淋候》"}]}, {"meaning": "短缺,距原来的要求还差。", "cites": [{"t": "理无专在,而学无止境也,然则问可少耶?", "b": "清·刘开《问说》"}, {"t": "今少一人,愿君即以遂备员而行矣。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "少不的", "t": "免不了,少不了"}, {"w": "少裆无系", "t": "缺衣少穿"}, {"w": "少欠", "t": "欠下"}, {"w": "少熟", "t": "欠收,减产"}, {"w": "少下", "t": "欠下;少欠"}, {"w": "少如", "t": "少于;比…少"}, {"w": "少条失教", "t": "没规矩,无教养。"}]}, {"meaning": "使少,减少;削弱。", "cites": [{"t": "欲天下之治安,莫若众建诸侯而少其力。", "b": "贾谊《治安策》"}], "words": [{"w": "少其力", "t": "削弱它的力量"}, {"w": "看看少不少人;这里肯定少了几个字;羊群里少了几只羊;少废话;少给我装蒜", "t": ""}]}, {"meaning": "轻视,看不起。", "cites": [{"t": "儒生之徒亦自相少。", "b": "王充《论衡》"}], "words": [{"w": "相少", "t": "相互轻视。"}]}, {"meaning": "稍稍,稍微。", "cites": [{"t": "少益嗜食。", "b": "《战国策·赵策》"}]}, {"meaning": "又。", "cites": [{"t": "太后之色少解。", "b": ""}, {"t": "今予病少痊。", "b": "《庄子·徐无鬼》"}, {"t": "宾客意少舒,稍稍正坐。", "b": "《虞初新志·秋声诗自序》"}, {"t": "愿大王稍假借之,使毕使于前。", "b": "《战国策·燕策》"}], "words": [{"w": "少款", "t": "稍稍款洽,指交谈渐投机"}, {"w": "少憩", "t": "略事休息"}, {"w": "少罄", "t": "稍尽"}, {"w": "少杀", "t": "稍差些"}, {"w": "少停", "t": "多一会儿"}, {"w": "少可", "t": "略微好些"}, {"w": "少沮", "t": "略有收敛"}, {"w": "少苏", "t": "稍有缓解"}, {"w": "少怠不究", "t": "稍加放松没有追究"}, {"w": "少需", "t": "稍待"}, {"w": "少恶", "t": "稍感不适"}, {"w": "少杀", "t": "稍衰;稍差"}, {"w": "少息", "t": "稍事休息"}, {"w": "少差", "t": "稍为好转。"}]}, {"meaning": "一会儿。", "cites": [{"t": "少焉,月出于东山之上,徘徊于斗、牛之间。", "b": "宋·苏轼《前赤壁赋》"}], "words": [{"w": "请少候;少歇", "t": "休息片刻"}, {"w": "少一时", "t": "待一会儿"}, {"w": "少安", "t": "稍安"}, {"w": "少停", "t": "一会儿"}, {"w": "少息", "t": "不久。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('111wx','曰','1','yuē','曰','4','','[{"pinyin": "yuē", "defs": [{"meaning": "(指事。甲骨文字形,下象口形,加上的短横表示声气。本义:说,说道)。"}, {"meaning": "同本义。", "cites": [{"t": "曰,言也。", "b": "《广雅》"}, {"t": "子曰何其。", "b": "《诗·魏风·园有桃》"}, {"t": "女曰鸡鸣。", "b": "《诗·郑风·女曰鸡鸣》"}, {"t": "子曰。", "b": "《论语·学而》。皇疏:“发语之端也。”"}, {"t": "曰有大艰于西土。", "b": "《书·大诰》"}, {"t": "曰师曰弟子云者。", "b": "唐·韩愈《师说》"}, {"t": "若业为吾所有…曰姑俟异日观。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "子曰;国人皆曰可杀", "t": ""}]}, {"meaning": "叫做。", "cites": [{"t": "五行:一曰水,二曰火,三曰木,四曰金,五曰土。", "b": "《书·洪范》"}, {"t": "明有奇巧人曰王叔远。", "b": "明·魏学洢《核舟记》"}, {"t": "文曰天启。", "b": ""}, {"t": "文曰初平山人。", "b": ""}, {"t": "有村曰谢庄。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "树帜曰谢庄团练冯。", "b": ""}]}, {"meaning": "句首、句中助词,无实义。", "cites": [{"t": "曰归曰归,岁亦莫止。", "b": "《诗·小雅·采薇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('112wx','日','1','rì','日','4','','[{"pinyin": "rì", "defs": [{"meaning": "(象形。甲骨文和小篆字形。象太阳形。轮廓象太阳的圆形,一横或一点表示太阳的光。本义:太阳)。"}, {"meaning": "同本义。", "cites": [{"t": "日,太阳之精也。从囗一,象形。", "b": "《说文》"}, {"t": "离为日,为火。", "b": "《易·说卦》"}, {"t": "以土圭之法,正日景求地中。", "b": "《周礼·大司徒》"}, {"t": "天无二日,太阳也。", "b": "《孟子》"}, {"t": "日初出,大如车盖。", "b": "《列子·汤问》"}], "words": [{"w": "日冠", "t": "太阳上方的光体"}, {"w": "日昃", "t": "日斜,日过中午"}, {"w": "日旸儿", "t": "太阳;日光"}, {"w": "日月交食", "t": "对头;互相争斗"}, {"w": "日头搁山", "t": "太阳落山"}, {"w": "日头趖西", "t": "太阳偏西"}, {"w": "日居月诸", "t": "日落月出,一天又一天。"}]}, {"meaning": "白天,白昼。", "cites": [{"t": "夏之日。", "b": "《诗·唐风·葛生》"}, {"t": "夜以继日。", "b": "《孟子·离娄下》"}, {"t": "经三日三夜,乡里皆谓已死。", "b": "《世说新语·自新》"}], "words": [{"w": "日昳", "t": "日已过午"}, {"w": "日往月去", "t": "时间一天天过去"}, {"w": "日里", "t": "白天"}, {"w": "日里向", "t": "白天"}, {"w": "日长神倦", "t": "夏季白天长,人易困倦"}, {"w": "日旰", "t": "日暮。天色晚"}, {"w": "日昼", "t": "白天"}, {"w": "夜以继日", "t": ""}]}, {"meaning": "时节;为特殊目的而定的日子。", "cites": [{"t": "天启壬戌秋日。", "b": "魏学洢《核舟记》"}], "words": [{"w": "交租日;星期一是洗衣日;你的结婚纪念日;三百万股日;太阴日;平太阳日;日南至", "t": "冬至日"}, {"w": "日脚", "t": "日子;时间"}, {"w": "日时", "t": "一段时间"}, {"w": "日分", "t": "日子;日期。"}]}, {"meaning": "一昼夜。", "cites": [{"t": "靡日不思。", "b": "《诗·邶风·泉水》"}, {"t": "日月星辰,太阳也。岁月日时,亦即曰日。", "b": "《书·洪范》"}, {"t": "教子数日。", "b": "《礼记·内则》"}], "words": [{"w": "日力", "t": "一天的力气"}, {"w": "日完", "t": "一天所做的事情"}, {"w": "日度", "t": "一天一天地过去。"}]}, {"meaning": "时间,光阴。", "words": [{"w": "日子浅", "t": "时日短"}, {"w": "日时", "t": "一段时间"}, {"w": "旷日经年;日已昏黑;日不我与", "t": "时日不等人"}, {"w": "日刻", "t": "时间。"}]}, {"meaning": "每日,每天。", "cites": [{"t": "吾日三省吾身。", "b": "《论语·学而》"}, {"t": "今诸生学于太学,县官日有廪稍之供。", "b": "明·宋濂《送东阳马生序》"}, {"t": "于是与亮情好日密。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "日远日疏,日亲日近", "t": "常常接近自然亲热,反之就会疏远"}, {"w": "日觐天颜", "t": "每天朝见皇帝"}, {"w": "日见穷蹙", "t": "处境一天天艰难窘迫"}, {"w": "日无暇晷", "t": "整天无空闲"}, {"w": "日逐", "t": "每日;每天"}, {"w": "日逐家", "t": "每日;一天天"}, {"w": "日事钱", "t": "日工资"}, {"w": "日辰", "t": "日子"}, {"w": "日食钱", "t": "日事钱。"}]}, {"meaning": "他日,改天。", "cites": [{"t": "日与俱来,吾与若俱观之。", "b": "《列子·汤问》"}]}, {"meaning": "往日,从前。", "cites": [{"t": "日卫不睦,故取其地。", "b": "《左传·文公十年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('113wx','中','1','zhōng zhòng','丨','4','','[{"pinyin": "zhōng", "defs": [{"meaning": "(指事。甲骨文字形,中象旗杆,上下有旌旗和飘带,旗杆正中竖立。本义:中心;当中,指一定范围内部适中的位置)。"}, {"meaning": "同本义。", "cites": [{"t": "中,和也。", "b": "《说文》"}, {"t": "中离维纲。", "b": "《仪礼·大射仪》"}, {"t": "与太史数射中。", "b": "《周礼·射人》"}, {"t": "持弓矢审固,然后可以言中。故盛算之器即曰中。", "b": "《礼记·射义》"}, {"t": "古者天子地方千里,中之而为都。", "b": "《新书·属远》"}, {"t": "中有都柱。", "b": "《后汉书·张衡传》"}, {"t": "天门中断。", "b": "唐·李白《望天门山》"}, {"t": "中通外直。", "b": "宋·周敦颐《爱莲说》"}, {"t": "中轩敝者。", "b": "明·魏学洢《核舟记》"}]}, {"meaning": "又。", "cites": [{"t": "中山峨冠而多髯者。", "b": ""}], "words": [{"w": "人中", "t": "人嘴上唇当中处"}, {"w": "华中;中浣", "t": "农历每月中旬"}, {"w": "中土", "t": "中原地区。古以冀州为中土,汉以来以河南为中土;中国"}, {"w": "中天", "t": "天空的中央"}, {"w": "中夕", "t": "夜半"}, {"w": "中色", "t": "中央之色,即黄色"}, {"w": "中甸", "t": "京都"}, {"w": "中江", "t": "江流的中央"}, {"w": "中非", "t": "指非洲中部地区。"}]}, {"meaning": "内,里面。与“外”相对。", "cites": [{"t": "五帝之中无传政。", "b": "《荀子·非相》"}, {"t": "儒有衣冠中。", "b": "《礼记·儒行》"}, {"t": "皮树中、闾中、虎中、兕中、鹿中,是也。", "b": "《礼记·乡射礼记》"}, {"t": "以益中外之累。", "b": "《后汉书·列女传》"}, {"t": "中有鲁人冯三保者、精技击。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "事变中起。", "b": "清·周容《芋老人传》"}], "words": [{"w": "心中", "t": "心里"}, {"w": "内中", "t": "里头"}, {"w": "家中;水中;队伍中;中水", "t": "水中"}, {"w": "中垢", "t": "尘垢之中。"}]}, {"meaning": "半;中途;半中腰。", "cites": [{"t": "夜中,星殒如雨。", "b": "《春秋》"}], "words": [{"w": "中缀", "t": "中途停止"}, {"w": "中夕", "t": "半夜"}, {"w": "中分", "t": "从中间分开"}, {"w": "中半", "t": "对半"}, {"w": "中白", "t": "半白"}, {"w": "中判", "t": "对半分开"}, {"w": "中阪", "t": "半山坡"}, {"w": "中夜舞", "t": "夜半起舞。"}]}, {"meaning": "方位名。泛指一个地区内或一个时期内,中间;居中。", "cites": [{"t": "晋太元中,武陵人捕鱼为业。", "b": "陶渊明《桃花源记》"}], "words": [{"w": "中门", "t": "内、外门之间的门"}, {"w": "中阵", "t": "中陈、居中的阵地、营垒,一般为主帅所在地"}, {"w": "中部", "t": "居中的部分"}, {"w": "中处", "t": "适中的处所"}, {"w": "中殿", "t": "居中的宫殿。"}]}, {"meaning": "指宫禁之内。亦借指朝廷。", "cites": [{"t": "赵高用事于中。", "b": "《史记》"}, {"t": "公来自中,天子所倚。", "b": "唐·韩愈《祭董相公文》"}], "words": [{"w": "中涓", "t": "皇帝亲近的侍从官"}, {"w": "中侍", "t": "宫中的侍从官"}, {"w": "中使", "t": "宫中派出的使者"}, {"w": "中尚方", "t": "古代官署名。掌宫内营选杂作"}, {"w": "中秘书", "t": "宫廷藏书"}, {"w": "中书", "t": "皇宫中的藏书。"}]}, {"meaning": "内心。", "cites": [{"t": "忧从中来。", "b": "曹操《短歌行》"}], "words": [{"w": "中顾", "t": "内心顾念"}, {"w": "中私", "t": "内心的感情"}, {"w": "中函", "t": "藏蓄于内心。"}]}, {"meaning": "内脏。", "cites": [{"t": "五中所主,何藏最贵。", "b": "《素问》"}]}, {"meaning": "中介人。", "cites": [{"t": "中央向严乡绅借二十两银子。", "b": "《儒林外史》"}], "words": [{"w": "中见", "t": "见证人。"}]}, {"meaning": "中等。", "cites": [{"t": "受中赏。", "b": "《战国策·齐策》"}, {"t": "中家以上。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "中才", "t": "中等才能"}, {"w": "中则", "t": "中等。指田赋"}, {"w": "中知", "t": "中等的才智"}, {"w": "中币", "t": "中等品级的货币"}, {"w": "中川", "t": "中等的河流"}, {"w": "中平", "t": "中等,平常"}, {"w": "中甲", "t": "金代科举考试成绩中等者"}, {"w": "中兄", "t": "才德一般的兄长。"}]}, {"meaning": "容易。", "cites": [{"t": "我是薛家丫头,狄家媳妇,我的钱不中骗。", "b": "《醒世姻缘传》"}]}, {"meaning": "合适,适当。", "cites": [{"t": "是秦之计中,齐燕之计过矣。", "b": "《战国策·齐策二》"}, {"t": "余观君疏于世故,而谋国无不中。", "b": "宋·叶适《袁声史墓志铭》"}]}, {"meaning": "不偏不倚,正。", "cites": [{"t": "头颈必中。", "b": "《礼记·玉藻》"}, {"t": "衣冠不中,不敢以入朝。", "b": "《晏子春秋》"}]}, {"meaning": "忠诚。", "cites": [{"t": "难进而尽中。", "b": "《孝经·圣治》"}, {"t": "中和,祗庸孝友。", "b": "《周礼·春官·大司乐》"}, {"t": "中不上达。", "b": "《荀子·成相》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhòng", "defs": [{"meaning": "正对上;射中,正着目标。", "cites": [{"t": "中其茎。", "b": "《考工记·桃氏》。司农注:“谓穿之也。”"}, {"t": "敌中则夺。", "b": "《荀子·彊国》。注:“击也。”"}, {"t": "见其发矢十中八九,但微颔之。", "b": "欧阳修《卖油翁》"}, {"t": "射者中。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "中而轻发。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "幸啄不中。", "b": "《聊斋志异·促织》"}], "words": [{"w": "中靶;猜中了;命中", "t": "射中"}, {"w": "看中", "t": "经过观察,感觉合意"}, {"w": "中雀", "t": "中目"}, {"w": "中钩", "t": "上钩"}, {"w": "中的", "t": "箭射中靶子"}, {"w": "中鹄", "t": "射中靶子。"}]}, {"meaning": "受到;遭到。", "cites": [{"t": "欲中守法。", "b": "明·高启《书博鸡者事》"}, {"t": "前番我王兄误中你的诡计,在青龙山上,被你伤了十万大兵。", "b": "《说岳全传》"}], "words": [{"w": "中霜", "t": "遭受霜冻"}, {"w": "中酒", "t": "病酒;醉酒"}, {"w": "中暍", "t": "中暑"}, {"w": "中疾", "t": "生病"}, {"w": "中恶", "t": "得急病"}, {"w": "中暑;中弹;中埋伏;中煤气", "t": ""}]}, {"meaning": "造谣;中伤。", "cites": [{"t": "好事者未尝不中。", "b": "《淮南子·原道》。注:“伤也。”"}, {"t": "欲以吏事中商。", "b": "《汉书·何武传》。注:“伤之也。”"}, {"t": "或言鹿,高因阴中诸言鹿者以法。", "b": "《史记》"}], "words": [{"w": "中陷", "t": "中伤陷害"}, {"w": "中人", "t": "伤害人。"}]}, {"meaning": "合于;符合。", "cites": [{"t": "砉然向然,奏刀騞然,莫不中音。(中音,合乎音律。)", "b": "《庄子·养生主》"}, {"t": "其曲中规。(它的曲度符合圆规所画出的标准。其,代车轮,相当于“它的”。中,动词,合乎。规,圆规。)", "b": "《荀子·劝学》"}, {"t": "木直中绳。", "b": ""}, {"t": "不中于款。", "b": "《聊斋志异·促织》"}], "words": [{"w": "中节", "t": "合乎规定"}, {"w": "中墨", "t": "符合准绳"}, {"w": "中准", "t": "符合水准"}, {"w": "中水", "t": "符合水平面标准"}, {"w": "中绳", "t": "符合墨线。"}]}, {"meaning": "考取;录取。", "cites": [{"t": "后来孟沂中了进士。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "中才", "t": "科举考试的中式之才"}, {"w": "中元", "t": "高中"}, {"w": "中签", "t": "填写考中者的标签"}, {"w": "中榜", "t": "中式"}, {"w": "中眉", "t": "中榜"}, {"w": "中第", "t": "中选。"}]}, {"meaning": "得到。", "cites": [{"t": "这龟儿,就是中了头奖,什么人还想沾你一文钱吗?", "b": "沙汀《丁跛公》"}], "words": [{"w": "中失", "t": "得失。"}]}, {"meaning": "满,充满。", "cites": [{"t": "令其量中,必善美而已。", "b": "《汉书》"}], "words": [{"w": "中寿", "t": "寿满。"}]}, {"meaning": "位居第二的。", "cites": [{"t": "中春,教振旅,司马以旗致民。", "b": "《周礼·夏官·司马》"}, {"t": "中祀大交霍山。", "b": "《尚书大传·虞夏传》。注:“中,仲也。”"}, {"t": "至中冬而盛。", "b": "《春秋繁露·循天之道》"}], "words": [{"w": "中秋", "t": "秋季的第二个月"}, {"w": "中春", "t": "春季的第二个月。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('114wx','贝','1','bèi','贝','4','','[{"pinyin": "bèi", "defs": [{"meaning": "(象形。甲骨文和金文字形,象海贝形。汉字部首之一。古时以贝壳为货币,又用作装饰,故从“贝”的字多与钱财宝物、装饰品或贸易商品有关。本义:海贝)。"}, {"meaning": "牡蛎、蛤或其它软体动物中腹足类和瓣鳃类的统称。体软无节,外束膜一层曰外套膜,能分泌液质,结构成壳,名为介。"}, {"meaning": "贝壳。", "words": [{"w": "贝阁", "t": "用贝壳装饰宫门前的楼观"}, {"w": "贝阙", "t": "以贝装饰的宫门楼观"}, {"w": "贝文", "t": "贝壳的纹彩"}, {"w": "贝饰", "t": "贝制的饰物"}, {"w": "贝雕", "t": "在贝壳上雕刻或镶嵌的工艺品。包括人物、山川、花卉、动物以及家具、文具等。"}]}, {"meaning": "古代货币。", "cites": [{"t": "大贝四寸八分以上。", "b": "《汉书·食货志》"}], "words": [{"w": "贝货", "t": "古代以贝壳为货币,故称贝货"}, {"w": "贝财", "t": "货财"}, {"w": "贝币", "t": "原始货币。"}]}, {"meaning": "贝尔的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('115wx','冈','1','gāng','冂','4','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从山,网声。本义:山脊,山岭) 同本义。", "cites": [{"t": "岡,山脊也。", "b": "《说文》。俗亦误作崗。"}, {"t": "览高冈兮峣峣。", "b": "《楚辞·守志》。注:“山岭曰冈。”"}, {"t": "山脊曰冈。冈,亢也,在上之言也。", "b": "《释名》"}, {"t": "陟彼高冈,我马玄黄(病)。", "b": "《诗·周南·卷耳》"}], "words": [{"w": "山冈;冈陀", "t": "山冈"}, {"w": "冈子", "t": "低矮而坡度较小的山丘"}, {"w": "冈岑", "t": "小山峦"}, {"w": "冈崖", "t": "山岩"}, {"w": "冈岭", "t": "山岭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('116wx','内','1','nà nèi','冂','4','','[{"pinyin": "nà", "defs": [{"meaning": "(会意。甲骨文字形,从冂入。冂(jiōng)表示蒙盖,入表示进入之物,合而表示事物被蒙盖在里面。本义:入,自外面进入里面)。"}, {"meaning": "同本义。", "cites": [{"t": "内,入也。自外而入也。", "b": "《说文》"}, {"t": "主入也。", "b": "《周礼·职内》注"}, {"t": "赵不内。", "b": "《史记·屈原贾生列传》"}, {"t": "欲止不内。", "b": "《史记·项羽本纪》"}, {"t": "内所著披袄中。", "b": "明·崔铣《记王忠肃公翱三事》"}]}, {"meaning": "交入;接纳", "cites": [{"t": "无不务内。", "b": "《礼记·月令》。注:“谓收敛入之也。”"}, {"t": "夫耳内和声,而口出美言。", "b": "《国语·周语》"}, {"t": "距关,毋内诸侯。", "b": "《史记·项羽本纪》"}, {"t": "恶内诸侯客。", "b": "《史记·范雎蔡泽列传》。注:“谓收敛入之也。”"}], "words": [{"w": "内金", "t": "进贡金、银、铜等物。"}]}]}, {"pinyin": "nèi", "defs": [{"meaning": "里面。与“外”相对。", "cites": [{"t": "一室之内。", "b": "明·袁宏道《满井游记》"}, {"t": "郗犹在帐内。", "b": "《世说新语·雅量》"}, {"t": "东海家内则郝夫人之法,亲陵家内范钟夫人之礼。", "b": "《世说新语·贤媛》"}, {"t": "一板内有重复。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "数里内无树。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "海内;关内;内牵", "t": "内中传递消息者。"}]}, {"meaning": "指某一群体或某一物体的中间。常指国内或朝廷内。", "cites": [{"t": "动干戈于邦内。", "b": "《论语·季氏》"}, {"t": "商君佐之,内立法度,务耕织。(内,名词作状语,译时加介词“对”,为“对内”。)", "b": "汉·贾谊《过秦论》"}, {"t": "不宜偏私,使内外异法也。", "b": "诸葛亮《出师表》"}, {"t": "外结好孙权,内修政理。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "内叛", "t": "内部叛乱"}, {"w": "内患", "t": "国内的祸患"}, {"w": "内事", "t": "国内的事;宗庙祭祀之事"}, {"w": "内睦", "t": "使内部和睦"}, {"w": "内噬", "t": "内部攻讦相残"}, {"w": "内寇", "t": "国内变乱;外敌入侵。"}]}, {"meaning": "室,内室,房室。", "cites": [{"t": "许便回入内,既见妇,即欲出。", "b": "《世说新语·贤媛》"}, {"t": "皆拜卧内床下。", "b": "《汉书·霍光传》"}], "words": [{"w": "内帏", "t": "女子居处"}, {"w": "内舍", "t": "内室;古代妇女居于内室,因借指妻子、女眷"}, {"w": "内房", "t": "内室;女眷居住的屋子"}, {"w": "内阶", "t": "内屋的台阶"}, {"w": "内照", "t": "光照内室;光照内部"}, {"w": "内户", "t": "内宅的门"}, {"w": "内子", "t": "妻子。"}]}, {"meaning": "皇宫;帝王所居之处。", "cites": [{"t": "西宫南内多秋草。", "b": "白居易《长恨歌》"}, {"t": "侍卫之臣不懈于内,忠志之士忘身于外。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "内外异法。", "b": ""}, {"t": "酒非内法。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "妇女;女色。", "cites": [{"t": "齐侯好内。", "b": "《左传·僖公十七年》"}], "words": [{"w": "内具", "t": "妇女日常应用的佩巾、丝絮和针丝袋之类物品"}, {"w": "内治", "t": "古指对妇女进行的教育"}, {"w": "内利", "t": "国君的配偶宜室宜家,有利于邻国"}, {"w": "内幸", "t": "皇帝宠爱的姬妾"}, {"w": "内姻", "t": "女眷方面的姻亲。"}]}, {"meaning": "古代泛称妻妾。后专称妻。", "cites": [{"t": "梦里无题惟寄内。", "b": "钱惟善《送贾元英之照潭》"}], "words": [{"w": "内实", "t": "妻妾与宝物"}, {"w": "惧内", "t": "怕老婆"}, {"w": "内训", "t": "对妇女的训诫教育"}, {"w": "内父", "t": "岳父"}, {"w": "内馈", "t": "内子。指妻子"}, {"w": "内掌柜", "t": "主妇"}, {"w": "内寝", "t": "正妻之居室"}, {"w": "内媚", "t": "丈夫善于讨妻妾的欢心"}, {"w": "内娣", "t": "妻子的弟弟"}, {"w": "内妹", "t": "妻子的妹妹"}, {"w": "内主", "t": "古代诸侯的夫人"}, {"w": "内老板", "t": "老板娘。"}]}, {"meaning": "内心。", "cites": [{"t": "王平子形甚散朗,内实劲侠。", "b": "《世说新语·谗险》"}, {"t": "内怀犹豫之计。", "b": "《资治通鉴》"}], "words": [{"w": "内境", "t": "内心境界"}, {"w": "内意", "t": "内心的想法"}, {"w": "内谋", "t": "内心思虑、谋划;参与机要,谋划政事;暗中谋划"}, {"w": "内慧", "t": "内心敏慧"}, {"w": "内刚", "t": "内心刚强。"}]}, {"meaning": "内脏。", "cites": [{"t": "见此崩五内,恍惚生狂痴。", "b": "蔡琰《悲愤诗》"}], "words": [{"w": "内症", "t": "体内脏器的疾病"}, {"w": "内疽", "t": "体内脏器的毒性肿块"}, {"w": "内疾", "t": "犹言暗病。身体内部的病症。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('117wx','水','1','shuǐ','水','4','','[{"pinyin": "shuǐ", "defs": [{"meaning": "(象形。甲骨文字形。中间像水脉,两旁似流水。“水”是汉字的一个部首。从水的字,或表示江河或水利名称,或表示水的流动,或水的性质状态。本义:以雨的形式从云端降下的液体,无色无味且透明,形成河流、湖泊和海洋,分子式为 H2O,是一切生物体的主要成分)。"}, {"meaning": "同本义。", "cites": [{"t": "水,准也。", "b": "《说文》"}, {"t": "水,准也。准,平也。天下莫平于水。", "b": "《释名》"}, {"t": "积阴之寒气为水。", "b": "《淮南子·天文》"}, {"t": "五行一曰水。", "b": "《书·洪范》"}, {"t": "凡平原出水为大水。", "b": "《左传·桓公元年》"}, {"t": "水曰清滌。", "b": "《礼记·曲礼》"}, {"t": "冰,水为之,而寒于水。", "b": "《荀子·劝学》"}, {"t": "刘豫州王室之胄,英才盖世,众士慕仰,若水之归海。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "水铫", "t": "烧水用的小型器具"}, {"w": "水头儿", "t": "风波"}, {"w": "水湿", "t": "水气;潮气"}, {"w": "水蛊病", "t": "水臌病"}, {"w": "水中丞", "t": "砚台旁边用来贮水磨墨的小水盂"}, {"w": "水落归槽", "t": "比喻心里踏实安定"}, {"w": "水喷桃花", "t": "比喻脸色好看"}, {"w": "水镜先生", "t": "指三国时的司马徽,清明如水和镜"}, {"w": "水陆杂陈", "t": "水陆毕陈。山珍海味一齐陈列出来"}, {"w": "水廓", "t": "傍水之城廓"}, {"w": "水涡", "t": "水中漩涡"}, {"w": "水馆", "t": "临水的馆舍或驿站。"}]}, {"meaning": "特指河流。", "cites": [{"t": "在水之湄。", "b": "《诗·秦风·蒹葭》"}, {"t": "去来江口守空船,绕船月明江水寒。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "水口", "t": "渡口"}, {"w": "水汊", "t": "河的支流"}, {"w": "水志", "t": "记载河道水系的书籍"}, {"w": "水牒", "t": "指记述河道水系的文献"}, {"w": "水谷", "t": "山间河沟"}, {"w": "水尾", "t": "江河的末端"}, {"w": "水老鼠", "t": "专在船上偷窃的贼"}, {"w": "水事", "t": "关于江河水利的事宜"}, {"w": "水禁", "t": "有关河川方面的禁令"}, {"w": "水会", "t": "河流汇合处。"}]}, {"meaning": "泛指一切水域。", "cites": [{"t": "水府幽深,寡人暗昧,夫子不远千里,将有为乎?", "b": "唐·李朝威《柳毅传》"}, {"t": "刘备、周瑜水陆并进。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "水陆", "t": "佛教中的水陆道场"}, {"w": "水泊", "t": "湖泽"}, {"w": "水居", "t": "居住于水乡"}, {"w": "水隍", "t": "水沟"}, {"w": "水王", "t": "海的别称"}, {"w": "水伯", "t": "传说中的水神;大河流"}, {"w": "水宿", "t": "水上宿夜;水中住宿"}, {"w": "水脉", "t": "水路,地下的伏流"}, {"w": "水潦", "t": "因雨水过多而积在田地里的水或流于地面的水。"}]}, {"meaning": "大水;水灾。", "cites": [{"t": "故尧禹有九年之水,汤有七年之旱。", "b": "汉·晁错《论贵粟疏》"}, {"t": "曰:天地有法乎?曰:水旱疾疫,即天地调剂之法也。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "水备", "t": "防止水患的设施"}, {"w": "水墉", "t": "防洪墙。"}]}, {"meaning": "五行之一。", "cites": [{"t": "五行:一曰水,二曰火,三曰木,四曰金,五曰土。", "b": "《书·洪范》"}]}, {"meaning": "额外收入或附加费用。又“发水”就是“发财”。"}, {"meaning": "指水军。", "cites": [{"t": "诸人徒见操书言水步八十万而各恐慑。", "b": "宋·司马光《资治通鉴》"}]}, {"meaning": "水族 。中国少数民族之一,居住在贵州省。"}, {"meaning": "泅水,游泳。", "cites": [{"t": "假舟楫者,非能水也,而绝江河。", "b": "《荀子·劝学》"}], "words": [{"w": "水式", "t": "指游水的技能"}, {"w": "水行", "t": "谓游水"}, {"w": "水事", "t": "指驾船、泅水之类的事情。"}]}, {"meaning": "用水测平。", "cites": [{"t": "匠人建国,水地以县。", "b": "《周礼》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('118wx','见','1','jiàn xiàn','见','4','','[{"pinyin": "jiàn", "defs": [{"meaning": "(会意。甲骨文字形,上面是“目”,下面是“人”。在人的头上加只眼睛,就是为了突出眼睛的作用。本义:看见,看到)。"}, {"meaning": "同本义。", "cites": [{"t": "见,视也。", "b": "《说文》"}, {"t": "未见君子。", "b": "《诗·周南·汝坟》"}, {"t": "利见大人。", "b": "《易·乾》"}, {"t": "见龙在田。", "b": "《易·乾》"}, {"t": "视而不见,听而不闻。", "b": "《礼记·大学》"}, {"t": "见而不见,闻而不闻。", "b": "《韩非子·主道》"}, {"t": "昨夜见军帖,可汗大点兵。", "b": "《乐府诗集·木兰诗》"}, {"t": "见两小儿辩斗。", "b": "《列子·汤问》"}, {"t": "儿童相见不相识。", "b": "唐·贺知章《回乡偶书》"}, {"t": "虎见之。", "b": "唐·柳宗元《三戒》"}, {"t": "歧王宅里寻常见。", "b": "唐·杜甫《江南逢李龟年》"}], "words": [{"w": "见雌雄", "t": "看到结果"}, {"w": "见人", "t": "见证人"}, {"w": "见喜", "t": "出痘疹的忌讳说法"}, {"w": "见不过", "t": "看不惯;见不得"}, {"w": "见头知尾", "t": "比喻聪明透顶。"}]}, {"meaning": "进见;会见。", "cites": [{"t": "往见楚王。", "b": "晋·干宝《搜神记》"}, {"t": "见蔡桓公。", "b": "《韩非子·喻老》"}, {"t": "扁鹊复见。", "b": ""}, {"t": "正见清河。", "b": "《世说新语·自新》"}], "words": [{"w": "见驾", "t": "参见皇帝"}, {"w": "见面挂脚", "t": "古时风俗新娘拜见公婆和诸姑姊妹时,所奉上作为见面礼的刺绣鞋面"}, {"w": "见礼", "t": "朝见之礼。"}]}, {"meaning": "遇到;碰见。", "cites": [{"t": "宋华父督见孔父之妻于路。", "b": "《左传·桓公元年》"}], "words": [{"w": "这种药怕见光", "t": ""}, {"w": "见齿", "t": "露齿而笑"}, {"w": "见顾", "t": "光顾"}, {"w": "见难", "t": "遇到危难"}, {"w": "见礼", "t": "受到礼遇。"}]}, {"meaning": "听到。", "cites": [{"t": "君不见高阳酒徒起草中,东揖山东隆准公。", "b": "李白《梁甫吟》"}], "words": [{"w": "见说", "t": "听说"}, {"w": "见话", "t": "听说,听讲。"}]}, {"meaning": "观察;知道;了解。", "cites": [{"t": "道在不可见。", "b": "《韩非子·主道》"}, {"t": "本无辞辇意,岂见入空官。", "b": "李贺《感讽》"}], "words": [{"w": "见几", "t": "明察事物细微的倾向"}, {"w": "见知", "t": "知道"}, {"w": "见便", "t": "识相;知趣。"}]}, {"meaning": "看法,见解。", "cites": [{"t": "敢陈愚见。", "b": "《晋书·王浑传》"}], "words": [{"w": "依我之见", "t": ""}, {"w": "政见", "t": ""}, {"w": "我见", "t": ""}, {"w": "各抒己见", "t": ""}, {"w": "各执己见", "t": ""}, {"w": "固执己见", "t": ""}, {"w": "主见", "t": ""}]}, {"meaning": "表示被动,相当于“被”。", "cites": [{"t": "不见保。", "b": "《孟子·梁惠王上》"}, {"t": "见犯乃死。", "b": "《汉书·李广苏建传》"}, {"t": "诚恐见欺。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "悲独见病。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "见笑于人", "t": ""}, {"w": "见笑于人", "t": ""}, {"w": "见重于当时", "t": ""}, {"w": "见执", "t": "被捉拿"}, {"w": "见罔", "t": "被诬陷枉屈"}, {"w": "见害", "t": "被害"}, {"w": "见款", "t": "承蒙款待。"}]}, {"meaning": "用在动词前面表示对我怎么样。", "cites": [{"t": "见辱问于长者。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "见告", "t": ""}, {"w": "见示", "t": ""}, {"w": "见教", "t": ""}]}]}, {"pinyin": "xiàn", "defs": [{"meaning": "“现”的古字。显现;出现;实现。", "cites": [{"t": "见,示也。", "b": "《广雅》"}, {"t": "见龙在田。", "b": "《易·乾》。注:“出潜离隐,故曰见。”"}, {"t": "情见力屈。", "b": "《汉书·韩信传》"}, {"t": "图穷而匕首见。", "b": "《战国策·燕策》"}, {"t": "见于王。", "b": "《孟子·梁惠王上》"}, {"t": "见于孔子", "b": "《论语·季氏》"}, {"t": "其末立见。", "b": "《史记·平原君虞卿列传》"}, {"t": "有虹见于玉堂。", "b": "《三国演义》"}, {"t": "有时见日。", "b": "吴均《与朱元思书》"}, {"t": "何时眼前突兀见此屋。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "见影", "t": "现形;发觉"}, {"w": "见得", "t": "显得。"}]}, {"meaning": "介绍,推荐。", "cites": [{"t": "见其二子焉(让他两个儿子出见子路。见通“现”,使……现。焉,于之,向子路)。", "b": "《论语·微子》"}, {"t": "见我于王。", "b": "《墨子·公输》"}]}, {"meaning": "(“现”的古字)。"}, {"meaning": "现有;现成。", "cites": [{"t": "军无见粮。", "b": "《史记》"}], "words": [{"w": "见采", "t": "可以立即拿出来的赌注"}, {"w": "见钱", "t": "现钱。"}]}, {"meaning": "现在。", "cites": [{"t": "况且见赌着利物哩,他如何肯让?", "b": "《二刻拍案惊奇》"}, {"t": "供状人刘玉娘,见年三十五岁。", "b": "元·孟汉卿《魔合罗》"}], "words": [{"w": "见前", "t": "眼前"}, {"w": "见年", "t": "当年"}, {"w": "见世报", "t": "当世就受到报应。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('119wx','午','1','wǔ','十','4','','[{"pinyin": "wǔ", "defs": [{"meaning": "(象形。本义:御马索)。"}, {"meaning": "同本义。", "cites": [{"t": "[甲骨文“午”字]疑当是索形,殆驭马之辔也。", "b": "郭沫若《甲骨文字研究》"}]}, {"meaning": "地支的第七位。"}, {"meaning": "与天干相配,用以纪年。", "cites": [{"t": "太岁在午曰敦羊。", "b": "《尔雅》"}]}, {"meaning": "用以纪月。即农历五月。", "cites": [{"t": "午,五月阴气午逆阳,冒地而出。", "b": "《说文》"}]}, {"meaning": "用以纪日。", "cites": [{"t": "庚午之日,日始有谪。", "b": "《左传》"}]}, {"meaning": "用以纪时,即十一时至十三时;正午,白天十二时。", "cites": [{"t": "午战于彼。", "b": "《左传·僖公三十二年》"}, {"t": "时已过午。", "b": "《徐霞客游记·游黄山记》"}, {"t": "过午已昏。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "午枕", "t": "午睡"}, {"w": "午牌", "t": "午时"}, {"w": "午晌", "t": "晌午"}, {"w": "午炮", "t": "正午的号炮"}, {"w": "午火", "t": "正午烈日"}, {"w": "午天", "t": "中午"}, {"w": "午斋", "t": "中午的斋食"}, {"w": "午暑", "t": "中午的暑气"}, {"w": "午漏", "t": "午时滴漏"}, {"w": "午际", "t": "午初"}, {"w": "午上", "t": "中午前"}, {"w": "午潮", "t": "正午的潮水"}, {"w": "午茶", "t": "午饭后的茶水。"}]}, {"meaning": "纵横相交。", "cites": [{"t": "度尺而午。", "b": "《仪礼》。郑玄注:“一纵一横曰午。”"}], "words": [{"w": "午午", "t": "交错杂沓的样子"}, {"w": "午道", "t": "纵横交贯的要道"}, {"w": "午贯", "t": "十字形交叉贯穿"}, {"w": "午割", "t": "交叉切割。"}]}, {"meaning": "违反。", "cites": [{"t": "午其众以伐有道,求得当欲,不以其所。", "b": "《礼记·哀公问》"}, {"t": "朝臣舛午。", "b": "《汉书·刘向传》"}]}, {"meaning": "抵触,相遇。", "cites": [{"t": "视可午其军、取其将…若是则为利者不攻也。", "b": "《荀子·富国》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('120wx','牛','1','niú','牛','4','','[{"pinyin": "niú", "defs": [{"meaning": "(象形。甲骨文字形作“牜”。中间一竖表示牛面,上面两竖加弯表牛角,下面两小撇表示牛耳)。"}, {"meaning": "牛属或近缘属的成员。哺乳动物,体型粗壮,角中空,由头骨向两侧呈大弧度伸出。力大,能耕田、拉车。中国产的以黄牛、水牛为主。", "cites": [{"t": "牛,大牲也。", "b": "《说文》"}, {"t": "坤为子母牛。", "b": "《易·说卦》"}, {"t": "纯离为牛。", "b": "《左传·昭公五年》"}, {"t": "东邻杀牛。", "b": "《礼记·坊记》"}, {"t": "牛曰太牢。", "b": "《大戴礼记·曾子天圆》"}, {"t": "牛田牧田。", "b": "《周礼·载师》。司农注:“牛田以养公家之牛。”"}, {"t": "风吹草低见牛羊。", "b": "《乐府诗集·敕勒歌》"}, {"t": "系向牛头充炭直。", "b": "唐·白居易《卖炭翁》"}, {"t": "不数岁,田百顷,楼阁万椽,牛羊蹄躈各千计。", "b": "《聊斋志异·促织》"}], "words": [{"w": "耕牛", "t": "耕地用的牛"}, {"w": "牛酒", "t": "牛和酒"}, {"w": "牛旄", "t": "即旄牛尾"}, {"w": "牛性", "t": "牛的本性"}, {"w": "牛埭", "t": "用牛力拉船过堰"}, {"w": "牛领", "t": "牛的脖子"}, {"w": "牛具", "t": "耕牛和农具"}, {"w": "牛刀", "t": "宰牛的刀。常比喻大材器"}, {"w": "牛蓑", "t": "牛衣。泛指蓑衣"}, {"w": "牛骥同皂", "t": "牛与千里马同槽而食。喻愚贤不明;牛骥共牢"}, {"w": "牛后", "t": "牛的肛门。比喻从属地位"}, {"w": "牛眠地", "t": "合适的坟地。"}]}, {"meaning": "星名。牛宿的省称。", "cites": [{"t": "吴之未灭也,斗、牛之间常有紫气。", "b": "《晋书·张华传》"}]}, {"meaning": "比喻性格执拗或倔犟 。如:牛心左性(头脑顽固,性情偏执);牛劲。也喻其温顺、迟钝、笨拙、力气大。如:笨牛;大牛。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('121wx','手','1','shǒu','手','4','','[{"pinyin": "shǒu", "defs": [{"meaning": "(象形。小篆字形,象伸出五指形。本义:人体上肢的总称,一般指腕以下的部分)。"}, {"meaning": "同本义。", "cites": [{"t": "手,拳也。", "b": "《说文》。段注:“今人舒之为手,卷之为拳。其实一也。故以手与拳二篆互训。”"}, {"t": "艮为手。", "b": "《易·说卦》"}, {"t": "三阴在手。", "b": "《素问·阴阳别论》。注:“手谓气口。”"}, {"t": "则不手拜。", "b": "《礼记·少仪》。注:“手拜,手至地也。”"}, {"t": "头至手曰拜手。", "b": "《公羊传·宣公六年》注"}, {"t": "携手同行。", "b": "《诗·邶风·北风》"}, {"t": "携手同归。", "b": ""}, {"t": "执子之手,与子偕老。", "b": "《诗·邶风·击鼓》"}], "words": [{"w": "手纽", "t": "手铐"}, {"w": "手杻", "t": "手铐之类的刑具"}, {"w": "手脚了得", "t": "手脚厉害,指有武功"}, {"w": "手帕交", "t": "旧时妓女间的结拜姐妹"}, {"w": "手击子", "t": "和尚念经时手中所敲的有柄小磬"}, {"w": "手本", "t": "下属见上司所呈的名帖"}, {"w": "手式", "t": "犹手势,以手作势示意"}, {"w": "手灵", "t": "手指灵巧"}, {"w": "手械", "t": "手铐"}, {"w": "手梏", "t": "手铐"}, {"w": "手格", "t": "徒手搏斗"}, {"w": "手理", "t": "手掌的纹路。"}]}, {"meaning": "专司某事或擅长某种技艺的人。", "cites": [{"t": "得快射手八百。", "b": "《宋书·黄回传》"}], "words": [{"w": "国手;能手;助手;多面手;第一把手;水手;拖拉机手;弹药手;手作", "t": "手工业者;手艺,本领。"}]}, {"meaning": "笔迹。", "cites": [{"t": "天子识其手,问之,果为书。", "b": "《汉书·郊祀志上》"}], "words": [{"w": "手墨", "t": "亲手写的墨迹"}, {"w": "手痕", "t": "手迹;笔迹"}, {"w": "手卷", "t": "只能卷舒供案头欣赏而不能悬挂的长卷。"}]}, {"meaning": "手艺;本领。", "cites": [{"t": "却笑英雄无好手,一篙春水走曹瞒。", "b": "宋·姜夔《满江红》"}], "words": [{"w": "手爪", "t": "手艺,技艺;手指"}, {"w": "手熟", "t": "手艺纯熟"}, {"w": "手戏", "t": "百戏杂技的一种"}, {"w": "手高", "t": "手段高强"}, {"w": "手里有活", "t": "手里有些功夫"}, {"w": "手长的", "t": "手快或手段灵活的人。"}]}, {"meaning": "亲自,亲手。", "cites": [{"t": "匪手携之。", "b": "《诗·大雅·抑》"}, {"t": "今存基本不忍废,道中手自钞录。", "b": "宋·文天祥《指南录·后序》"}, {"t": "庭有枇杷树,吾妻死之年所手植也。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "手钞", "t": "亦作“手抄”。亲手抄录。"}]}, {"meaning": "拿着,执持。", "cites": [{"t": "庄公升坛,曹子手剑而从之。", "b": "《公羊传·庄公十三年》"}], "words": [{"w": "手瓮", "t": "可用手提的盛水陶器"}, {"w": "手袂", "t": "以手执人衣袖。表示离别依依不舍之情"}, {"w": "手谈", "t": "下棋"}, {"w": "手笔", "t": "谓执笔写作"}, {"w": "手照", "t": "手持的照明用具"}, {"w": "手罩", "t": "手持的风灯"}, {"w": "手磬子", "t": "僧尼所用的手持打击乐器"}, {"w": "手烛", "t": "手执之烛"}, {"w": "手镘", "t": "以手持镘。作泥水工"}, {"w": "手炮", "t": "手掷的炸药包。"}]}, {"meaning": "用手击杀。", "cites": [{"t": "博豺狼,手熊罴。", "b": "司马相如《上林赋》"}], "words": [{"w": "手格", "t": "徒手格击"}, {"w": "手战", "t": "徒手搏斗"}, {"w": "手搏", "t": "徒手搏斗。指角力、摔跤、拳击之类的搏斗。"}]}, {"meaning": "取。", "cites": [{"t": "宾载手仇。", "b": "《诗·小雅·宾之初筵》。传:“取也。”"}], "words": [{"w": "人手一册;手影戏", "t": "用手向灯取影,显出种种形象的一种技艺。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('122wx','气','1','qì','气','4','','[{"pinyin": "qì", "defs": [{"meaning": "(象形。甲骨文、小篆字形。象云气蒸腾上升的样子。“气”是汉字部首之一。本义:云气)。"}, {"meaning": "同本义。", "cites": [{"t": "气,云气也。", "b": "《说文》。按,云者,地面之气,湿热之气升而为雨,其色白,干热之气,散而为风,其色黑。”"}, {"t": "天气下降,地气上腾。", "b": "《礼记·月令》"}, {"t": "地有气。", "b": "《考工记·总目》"}, {"t": "望其气。", "b": "《史记·项羽本纪》"}, {"t": "此天子气也。", "b": ""}, {"t": "窗以达气。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "气朔", "t": "指显示吉凶的云气和每月的朔日"}, {"w": "气祲", "t": "古代泛指据以占卜吉凶的云气"}, {"w": "气纬", "t": "指云气星象"}, {"w": "气晕", "t": "日、月四周所生的晕气。"}]}, {"meaning": "气体的通称 。既没有独立的形态又没有固定的体积而趋向无限膨胀的流体。如:气蚀。又指天然气。如:气田。"}, {"meaning": "空气。", "cites": [{"t": "气谓嘘吸出入者。", "b": "《礼记·祭义》注"}], "words": [{"w": "气球", "t": "一种供游戏用的足球,用皮革制成,内充空气。"}]}, {"meaning": "气象。", "cites": [{"t": "故在天为气。", "b": "《素问·天元纪大论》。注:“谓风热温燥寒。”"}, {"t": "天有六气…六气曰阴、阳、风、雨、晦、明也。", "b": "《左传·昭公元年》"}, {"t": "山气日夕佳。", "b": "晋·陶渊明《饮酒》诗"}, {"t": "春气动。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "气味。", "cites": [{"t": "香气环旋。", "b": "唐·李朝威《柳毅传》"}, {"t": "恶气袭衣裙。", "b": "明·宗臣《报刘一丈书》"}, {"t": "与饮食之气相薄。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "气子", "t": "气味"}, {"w": "气韵", "t": ""}]}, {"meaning": "呼吸;气息。", "cites": [{"t": "武气绝半日复息。", "b": "《汉书·李广苏建传》"}, {"t": "缢即气绝。", "b": "清·方苞《狱中杂记》"}, {"t": "启时气绝。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "气命", "t": "性命"}, {"w": "气歇", "t": "缓一口气"}, {"w": "气疾", "t": "呼吸系统疾病"}, {"w": "气凑", "t": "呼吸急促。"}]}, {"meaning": "景象;气氛。", "cites": [{"t": "以达秋气。", "b": "《礼记·月令》"}]}, {"meaning": "指人的元气。", "cites": [{"t": "气者,体之充也。", "b": "《孟子》"}, {"t": "气母(元气的本原)", "b": ""}]}, {"meaning": "指精神状态,情绪。", "cites": [{"t": "恢弘志气。", "b": "诸葛亮《出师表》"}, {"t": "敢以矜气。", "b": "唐·柳宗元《柳河东集》"}, {"t": "其气浩然。", "b": "清·全祖望《梅花岭记》"}, {"t": "气叹(泄气);气不忿(不甘心;不服气);气不愤(气不忿);气合(意气相投);气志(指精神、意志)", "b": ""}]}, {"meaning": "气焰;权势。", "cites": [{"t": "一鼓作气。", "b": "《左传·庄公十年》"}, {"t": "以厉其气。", "b": "唐·柳宗元《柳河东集》"}, {"t": "气吞万里如虎。", "b": "宋·辛弃疾《京口北固亭怀古》"}, {"t": "豪民气尽。", "b": "明·高启《书博鸡者事》"}, {"t": "气沮(气势衰弱);气魄(气势)", "b": ""}]}, {"meaning": "中医学术语。指脉气和营卫。", "cites": [{"t": "五气、五声、五色。", "b": "《周礼·疾医》。注:“肺气热,心气次之,肝气凉,脾气温,肾气寒。”"}, {"t": "气疫(谓染疫气而得病);气脉(血气与脉息)", "b": ""}]}, {"meaning": "用具,工具。", "cites": [{"t": "三者本于心,然后乐气从之。", "b": "《礼记·乐记》"}]}, {"meaning": "向人求讨。", "cites": [{"t": "是若人气。", "b": "《墨子·非儒下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('123wx','毛','1','máo','毛','4','','[{"pinyin": "máo", "defs": [{"meaning": "(象形。金文字形。“毛”是汉字的一个部首,从“毛”的字多与皮毛有关。本义:眉毛、头发、兽毛)。"}, {"meaning": "同本义。", "cites": [{"t": "毛,眉发之属及兽毛也。", "b": "《说文》"}, {"t": "不获二毛。", "b": "《礼记·檀弓》。注:“二毛,鬓发斑白。”"}, {"t": "王燕则诸侯毛。", "b": "《周礼·司仪》"}, {"t": "皮毛者,肺之合也。", "b": "《素问·欬论》"}, {"t": "其动物宜毛物。", "b": "《周礼·大司徒》"}, {"t": "毛马而颁之。", "b": "《周礼·校人》"}, {"t": "以启其毛。", "b": "《诗·小雅·信南山》"}, {"t": "皮之不存,毛将焉傅?", "b": "《左传·僖公十四年》"}, {"t": "胚不生毛。", "b": "《韩非子·五蠹》"}, {"t": "与旃毛并咽。", "b": "《汉书·李广苏建传》"}, {"t": "大小毛角。", "b": "唐·李朝威《柳毅传》"}, {"t": "矢如猬毛。", "b": "《资治通鉴·唐纪》"}, {"t": "少小离家老大回,乡音无改鬓毛衰。", "b": "贺知章《回乡偶书》"}], "words": [{"w": "毛女", "t": "传说中的仙女,遍体生毛,故名"}, {"w": "毛连", "t": "用羊毛或其他毛类制成的褡裢"}, {"w": "刚毛", "t": "人或动物体上长的硬毛"}, {"w": "毫毛", "t": "人或鸟兽身上的细毛"}, {"w": "毛笔", "t": "以兽毛制成的笔"}, {"w": "毛羽", "t": "兽毛和鸟羽"}, {"w": "毛戴", "t": "寒毛竖立"}, {"w": "毛脉", "t": "须发与血脉"}, {"w": "毛悚", "t": "汗毛竖立"}, {"w": "毛蓬蓬", "t": "须发密而乱貌"}, {"w": "毛楂楂", "t": "毛发短而硬貌"}, {"w": "毛发不爽", "t": "犹毫毛不爽"}, {"w": "毛耸", "t": "毛发竖立。"}]}, {"meaning": "鸟的羽毛。", "words": [{"w": "毛芥", "t": "羽毛和芥子"}, {"w": "毛扇", "t": "羽毛扇"}, {"w": "毛翎", "t": "翎毛。借指羽翼"}, {"w": "毛质", "t": "鸟类的毛羽。"}]}, {"meaning": "草木;五谷。", "cites": [{"t": "曾不能毁山之一毛。", "b": "《列子·汤问》"}, {"t": "涧溪沼沚之毛。", "b": "《左传·隐公三年》。注:“草也。”"}, {"t": "毛泽未尽。", "b": "《谷梁传·定公元年》。注:“凡地之所生谓之毛。”"}, {"t": "锡之不毛之地。", "b": "《公羊传·宣公十二年》。注:“墝埆不生五谷曰不毛。”"}]}, {"meaning": "小,微不足道。多用于贬义。", "cites": [{"t": "你是那路毛神?", "b": "《西游记》"}], "words": [{"w": "毛神", "t": "小神。骂人的话"}, {"w": "毛路", "t": "方言。小路"}, {"w": "毛蛋蛋子", "t": "詈词。犹言小畜生"}, {"w": "毛铢", "t": "形容极微小的利益。"}]}, {"meaning": "发慌。", "cites": [{"t": "祁老爷毛了,只得退了堂。", "b": "《儒林外史》"}], "words": [{"w": "发毛", "t": "发慌"}, {"w": "吓毛了;小偷毛了;毛脚鸡", "t": "比喻行动慌里慌张。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('124wx','壬','1','rén','士','4','','[{"pinyin": "rén", "defs": [{"meaning": "(象形兼指事。像一个人挑担子。本义:挑担) 同本义。", "cites": [{"t": "壬,儋何也。上下物也,中象人儋之。", "b": "《说文通训定声》。按,经传以任为之"}, {"t": "是任是负。", "b": "《诗·大雅·生民》"}]}, {"meaning": "天干的第九位,用以纪旬。", "cites": [{"t": "夏四月壬戌,公及晋侯盟于长樗。", "b": "《春秋》"}]}, {"meaning": "巧辩。假借为“佞”。", "cites": [{"t": "何畏乎巧言令色孔壬。", "b": "《书·皋谟》"}], "words": [{"w": "壬人", "t": "壬佞,奸人。"}]}, {"meaning": "盛大;庄严。", "cites": [{"t": "百礼既至,有壬有林。", "b": "《诗·小雅·宾之初筵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('125wx','升','1','shēng','十','4','','[{"pinyin": "shēng", "defs": [{"meaning": "(象形。本义:容器名。一斗的十分之一)。"}, {"meaning": "容量单位。", "cites": [{"t": "升,十龠也。从斗,亦象形。", "b": "《说文》。按,十合也。"}, {"t": "两匊谓之升。", "b": "《小尔雅》"}, {"t": "蕃衍盈升。", "b": "《诗·唐风·椒聊》"}]}, {"meaning": "量酒的单位。", "cites": [{"t": "赐酒日二升,肉二斤。", "b": "《墨子》"}]}, {"meaning": "量器。", "cites": [{"t": "忽见石窠中有二卵大如升。", "b": "晋·陶潜《搜神后记》"}]}, {"meaning": "古代布八十缕为升。", "cites": [{"t": "冠六升,外毕。", "b": "《仪礼》"}]}, {"meaning": "上升,升起。", "cites": [{"t": "昇,日上。本亦作升。", "b": "《广韵》"}, {"t": "升假借为“登”。字亦作昇,作陞。", "b": "朱骏声《说文通训定声》"}, {"t": "聚而上者谓之升。", "b": "《易·序卦》"}, {"t": "如日之升。", "b": "《诗·小雅·天保》"}, {"t": "一人飞升,仙及鸡犬。", "b": "《聊斋志异·促织》"}], "words": [{"w": "升驾", "t": "飞升;腾云驾雾"}, {"w": "升坠罔知", "t": "不知己故者的结局如何"}, {"w": "升降揖逊", "t": "礼仪制度"}, {"w": "升冠升珠", "t": "脱下官帽和外衣"}, {"w": "升举", "t": "修炼成仙,升上天堂"}, {"w": "升仙", "t": "死亡"}, {"w": "升龙", "t": "乘龙升天"}, {"w": "回升", "t": "下降后又往上升。"}]}, {"meaning": "登,上。", "cites": [{"t": "陞,上也。", "b": "《广雅》"}, {"t": "升,元亨。", "b": "《易·升卦》。疏:“升者,登也。”"}, {"t": "道存升降。", "b": "《书·毕命》"}, {"t": "天险不可升也。", "b": "《易·习坎》"}, {"t": "由也升堂矣,未入于室也。", "b": "《论语·先进》"}], "words": [{"w": "升阶", "t": "拾级而上"}, {"w": "升车", "t": "登车"}, {"w": "升炕", "t": "上炕就坐"}, {"w": "升殿", "t": "登入宫殿理事"}, {"w": "升堂睹奥", "t": "比喻学有所成,并观察到深奥之处"}, {"w": "升陟", "t": "升登,攀登"}, {"w": "升济", "t": "升登,超度"}, {"w": "升封", "t": "登泰山封禅"}, {"w": "升屋", "t": "登上屋顶"}, {"w": "升座", "t": "登上座位。"}]}, {"meaning": "提升。", "cites": [{"t": "名因文著,位以才升。", "b": "白居易《祭卢虔文》"}, {"t": "以此遂不得升进。", "b": "《后汉书·王符传》"}, {"t": "既而胡即放宁夏知府,旋升宁夏道。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "升转", "t": "官职的提升与调动"}, {"w": "升除", "t": "提升官职。除:拜官受职"}, {"w": "升擢", "t": "提升"}, {"w": "升补", "t": "官吏的升迁与补缺"}, {"w": "升扬", "t": "提升,升迁"}, {"w": "升进", "t": "晋升官位"}, {"w": "升第", "t": "晋级或被录用"}, {"w": "升秩", "t": "升官"}, {"w": "升行", "t": "提高行辈。"}]}, {"meaning": "谷物登场,成熟。", "cites": [{"t": "旧谷既没,新谷既升。", "b": "《论语》"}]}, {"meaning": "进奉,进献。", "cites": [{"t": "是月也,农乃升谷,天子尝新,先荐寝庙。", "b": "《吕氏春秋》"}]}, {"meaning": "古州名  故治在今南京市。"}, {"meaning": "姓(如宋有昇元中)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('126wx','夭','1','ǎo yāo','大','4','','[{"pinyin": "ǎo", "defs": [{"meaning": "刚出生的兽或禽。", "cites": [{"t": "毋覆巢,毋胎夭。", "b": "《淮南子》"}, {"t": "畋不掩群,不取麛夭;不涸泽而渔,不焚林而猎。", "b": "吴伯箫《猎户》"}]}, {"meaning": "初生的草木。", "cites": [{"t": "泽不伐夭。", "b": "《国语》"}]}]}, {"pinyin": "yāo", "defs": [{"meaning": "(象形。小篆字形,象头部屈曲的样子。本义:屈,摧折) 同本义。", "cites": [{"t": "夭,屈也。", "b": "《说文》。按,从大而屈其首,指事,申者,腰之直,夭者头之曲。"}, {"t": "申申如也,夭夭如也。", "b": "《论语》"}, {"t": "毋伐木,毋夭英,毋附竿。", "b": "《管子·禁藏》"}], "words": [{"w": "夭英", "t": "折断幼苗。"}]}, {"meaning": "短命,早死。未成年而死。", "cites": [{"t": "少壮而死曰夭。", "b": "《释名》"}, {"t": "不殀夭。", "b": "《礼记·王制》"}, {"t": "夭寿不贰,修身以俟之。", "b": "《孟子·尽心上》"}, {"t": "莫寿于殇子,而彭祖为夭。", "b": "《庄子·齐物论》"}, {"t": "夭其稚枝。", "b": "清·龚自珍《病梅馆记》"}, {"t": "夭梅病梅。", "b": ""}], "words": [{"w": "夭札", "t": "遭疫病而早死"}, {"w": "夭死", "t": "早死。又称作:夭枉;夭殁;夭命;夭殂;夭促;夭逝;夭绝;夭昏;夭谢;夭短"}, {"w": "夭厉", "t": "因遭疾疫而早死。"}]}, {"meaning": "茂盛。", "cites": [{"t": "厥草惟夭,厥木惟乔。", "b": "《书·禹贡》"}], "words": [{"w": "夭秀", "t": "秀丽"}, {"w": "夭桃秾李", "t": "茂盛艳丽的桃花、李花。"}]}, {"meaning": "幼嫩;矫好。", "cites": [{"t": "夭之沃沃,乐子之无知。", "b": "《诗·桧风·隰有苌楚》"}], "words": [{"w": "夭年", "t": "盛年"}, {"w": "夭夭一对", "t": "好端端一对"}, {"w": "夭娇", "t": "夭矫"}, {"w": "夭夭折折", "t": "弯弯曲曲"}, {"w": "夭绍", "t": "轻盈多姿的样子;曲折的样子"}, {"w": "夭妍", "t": "美丽妩媚"}, {"w": "夭桃", "t": "喻少女容颜美丽"}, {"w": "夭秾", "t": "指美貌的女子"}, {"w": "夭夭灼灼", "t": "形容茂盛而艳丽鲜明的样子"}, {"w": "夭娜", "t": "婀娜。轻盈艳丽的样子"}, {"w": "夭丽", "t": "娇艳美丽"}, {"w": "夭饶", "t": "夭娆,娇艳美好"}, {"w": "夭娆", "t": "娇艳妩媚"}, {"w": "夭冶", "t": "艳丽。"}]}, {"meaning": "(yǎo)。昏暗。", "cites": [{"t": "色夭不泽,谓之难已。", "b": "《素问·玉机真藏论》。《定声》:“夭,借为杳。”"}, {"t": "五藏已败,其色必夭,夭必死矣。", "b": "《素问·三部九候论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('127wx','长','1','cháng zhǎng','长','4','','[{"pinyin": "cháng", "defs": [{"meaning": "(象形。甲骨文字形,象人披长发之形,以具体表抽象,表示长短的“长”。本义:两点距离大)。"}, {"meaning": "同本义。与“短”相对。", "cites": [{"t": "巽为长,为高。", "b": "《易·说卦》"}, {"t": "顺彼长道。", "b": "《诗·鲁颂·泮水》"}, {"t": "道阻且长。", "b": "《诗·秦风·蒹葭》"}, {"t": "长毂九百。", "b": "《左传·昭公五年》"}, {"t": "布帛长短同。", "b": "《孟子》"}, {"t": "长三尺。", "b": "《仪礼·士冠礼》"}, {"t": "长丈二尺。", "b": "《周礼·凌人》注"}, {"t": "长一身有半。", "b": "《论语》"}, {"t": "白发三千丈,缘愁似个长。", "b": "唐·李白《秋浦歌》"}], "words": [{"w": "狭长", "t": "窄而长"}, {"w": "长铗", "t": "剑的一种。刀身剑锋长的叫长铗,短的叫短铗。"}]}, {"meaning": "时间久。", "cites": [{"t": "长,久也。", "b": "《广雅》"}, {"t": "未尝闻社稷之长利。", "b": "《战国策·齐策》"}, {"t": "义有长短大小。", "b": "《礼记·表记》"}, {"t": "举手长劳劳,二情同依依。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "长宵", "t": "漫长的夜"}, {"w": "长律", "t": "长的音律。"}]}, {"meaning": "遥远。", "cites": [{"t": "溯洄从之,道阻且长。", "b": "《诗·秦风·蒹葭》"}, {"t": "酒困路长惟欲睡。", "b": "宋·苏轼《浣溪沙》"}], "words": [{"w": "长解", "t": "远距离解送犯人;押解犯人发配远方的公差。"}]}, {"meaning": "高;高大。", "cites": [{"t": "今日被驱遣,小姑如我长。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "长林", "t": "高大的树林"}, {"w": "长壮", "t": "高大而强壮。"}]}, {"meaning": "长度。", "cites": [{"t": "舟首尾长约八分有奇。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "身长", "t": ""}, {"w": "桥长 1000米", "t": ""}, {"w": "波长", "t": ""}]}, {"meaning": "长处。", "cites": [{"t": "蒹百花之长而各去其短。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "取长补短", "t": ""}, {"w": "扬长避短", "t": ""}, {"w": "一技之长,学有所长", "t": ""}, {"w": "特长", "t": ""}]}, {"meaning": "长久;永远。", "cites": [{"t": "我欲与君相知,长命无绝衰。", "b": "《乐府诗集·上邪》"}, {"t": "存者且偷生,死者长已矣!", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "长川", "t": "经常;长久"}, {"w": "长流", "t": "长久,永远。"}]}, {"meaning": "长长地。", "cites": [{"t": "长太息以掩涕兮,哀民生之多艰。", "b": "屈原《离骚》"}]}, {"meaning": "经常。", "cites": [{"t": "茅檐长扫净无苔。", "b": "王安石《题湖阴先生壁》"}]}, {"meaning": "直直地。", "cites": [{"t": "府吏长跪告。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "顺利迅速地。", "cites": [{"t": "未有长驱径入敌围者也。", "b": "陈寿《三国志》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhǎng", "defs": [{"meaning": "老,年高。", "cites": [{"t": "长,老也。", "b": "《广雅》"}, {"t": "不挟长。", "b": "《孟子》。注:“年长也。”"}, {"t": "子之年长矣,而色若孺子,何也?", "b": "《庄子》"}, {"t": "长者虽有问,役夫敢申恨?", "b": "杜甫《兵车行》"}, {"t": "齐侯长矣。", "b": "《国语》"}], "words": [{"w": "长艾", "t": "老年"}, {"w": "长没", "t": "年老而死。"}]}, {"meaning": "年长,年龄较大。", "cites": [{"t": "长子灿七岁。", "b": "明·魏禧《大铁椎传》"}, {"t": "弟辈衣食自足,不消兄长挂念。", "b": "《醒世恒言》"}], "words": [{"w": "长君", "t": "年长的君主"}, {"w": "长德", "t": "年长而有德"}, {"w": "长贤", "t": "年长而贤明"}, {"w": "长主", "t": "年长的君主"}, {"w": "长宾", "t": "年长的宾客"}, {"w": "长年", "t": "年龄较大"}, {"w": "长郎", "t": "尊称他人的长子。"}]}, {"meaning": "成年的,幼之反,成人曰长。", "cites": [{"t": "问国君之年,长,曰能从宗庙社稷之事矣;幼,曰未能从宗庙社稷之事也。", "b": "《礼记》"}], "words": [{"w": "长殇", "t": "古代男子未冠,女子未而死都称殇。"}]}, {"meaning": "排行第一。", "cites": [{"t": "阿爷无大儿,木兰无长兄。", "b": "《木兰诗》"}, {"t": "始皇有二十八子,长子扶苏以数直谏上,上使监兵上郡。", "b": "《史记·李斯列传》"}], "words": [{"w": "长弟", "t": "先后。先生为长,后生为弟"}, {"w": "长庶", "t": "庶长子。妾生的长子"}, {"w": "长嫡", "t": "正妻所生的长子或长女"}, {"w": "长杰", "t": "超群出众"}, {"w": "长妾", "t": "妾中先有子者"}, {"w": "长公主", "t": "皇帝的姊妹或皇女尊崇者的封号。"}]}, {"meaning": "辈分大;居高位者。", "cites": [{"t": "万夫之长。", "b": "《吕氏春秋·谕大》"}, {"t": "吏六百石以上,皆长吏也。", "b": "《汉书·景帝纪》"}], "words": [{"w": "长吏", "t": "官吏中俸禄高、职位尊的人"}, {"w": "长雄", "t": "领袖人物。即“雄长”"}, {"w": "长爵", "t": "高的爵位。"}]}, {"meaning": "生长;成长。", "cites": [{"t": "草木遂长。", "b": "《庄子·马蹄》"}, {"t": "暮春三月,江南草长,杂花生树。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "求木之长者。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "初长足时。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "一旦长成。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "长俊", "t": "长进;进步"}, {"w": "长成", "t": "长大成人"}, {"w": "长立", "t": "长大自立"}, {"w": "长牙", "t": ""}, {"w": "长毛", "t": ""}, {"w": "长肉", "t": ""}, {"w": "长胖", "t": ""}]}, {"meaning": "抚育;使…成长。", "cites": [{"t": "父兮生我,母兮鞠我,拊我畜我,长我育我。", "b": "《诗·小雅·蓼莪》"}], "words": [{"w": "长养", "t": "抚育培养"}, {"w": "长育", "t": "养育。"}]}, {"meaning": "滋长,助长,增长。", "cites": [{"t": "而长寇仇。", "b": "《左传·僖公三十三年》"}, {"t": "废奢长俭。", "b": "《汉书·杜钦传》"}, {"t": "日日以长。", "b": "《世说新语·自新》"}], "words": [{"w": "长托", "t": "滋补身体"}, {"w": "长美", "t": "增长美德"}, {"w": "长傲", "t": "滋长傲气"}, {"w": "长益", "t": "促进,增益"}, {"w": "长消", "t": "消长,盛衰"}, {"w": "长知识", "t": ""}, {"w": "此风不可长", "t": ""}]}, {"meaning": "崇尚。", "cites": [{"t": "今汉家承周秦之敝,宜抑文尚质,废奢长俭,表实去伪。", "b": "《汉书·杜钦传》"}]}, {"meaning": "做长官;为首领。", "cites": [{"t": "子无敢食我也。天地使我长百兽,今子食我,是逆天帝命也。", "b": "《战国策》"}]}, {"meaning": "首领;君长;领袖;各种组织的位高者。", "cites": [{"t": "世为长侯,守殷常祀。", "b": "《吕氏春秋》"}], "words": [{"w": "科长", "t": ""}, {"w": "处长", "t": ""}, {"w": "长夫", "t": "码头搬运工的工头"}, {"w": "长家", "t": "一家之长"}, {"w": "长卿", "t": "六卿之长"}, {"w": "长侯", "t": "诸侯之长。"}]}, {"meaning": "年纪较大的人。", "cites": [{"t": "长先而少从。", "b": "《庄子》"}], "words": [{"w": "长少", "t": "年长者与年少者。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('128wx','仁','1','rén','亻','4','','[{"pinyin": "rén", "defs": [{"meaning": "(会意。从人,从二。右边的二是重文。本义:博爱,人与人相互亲爱)。"}, {"meaning": "中国古代一种含义极广的道德观念。其核心指人与人相互亲爱。孔子以之作为最高的道德标准。", "cites": [{"t": "仁,亲也。", "b": "《说文》"}, {"t": "仁者,情志好生爱人,故立字二人为仁。", "b": "《春初·元命苞》"}, {"t": "上下相亲谓之仁。", "b": "《礼记·经解》"}, {"t": "温良者,仁之本也。", "b": "《礼记·儒行》"}, {"t": "仁者,谓其中心欣然爱人也。", "b": "《韩非子·解老》"}, {"t": "仁者,可以观其爱焉。", "b": "《礼记·丧服四制》"}, {"t": "岂无居人?不如叔也,洵美且仁。", "b": "《诗·郑风·叔于田》"}], "words": [{"w": "仁人", "t": "有仁德的人"}, {"w": "仁术", "t": "施行仁道、仁政的方法"}, {"w": "仁宇", "t": "在仁德的覆蔽之下"}, {"w": "仁瑞", "t": "仁德的瑞兆"}, {"w": "仁朴", "t": "仁爱朴实"}, {"w": "仁笃", "t": "仁爱笃厚"}, {"w": "仁诲", "t": "仁爱的教诲"}, {"w": "仁鄙", "t": "仁爱与鄙薄。"}]}, {"meaning": "有德者之称。"}, {"meaning": "旧指有仁德的人。", "cites": [{"t": "予尝求古仁人之心。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "仁人网", "t": "传说商汤曾让猎人网开三面。指给予一条生路"}, {"w": "仁者", "t": "有德行的人"}, {"w": "仁里", "t": "仁者住地"}, {"w": "仁士", "t": "仁人。有德行的人。"}]}, {"meaning": "指事物中有恩于万物生育者,古代常与五行等相配。", "cites": [{"t": "养之,长之,假之,仁也。", "b": "《礼记》"}]}, {"meaning": "完美的道德。", "cites": [{"t": "夫仁者,己欲立而立人,己欲达而达人。", "b": "《论语·雍也》"}]}, {"meaning": "仁政。", "cites": [{"t": "以德行仁者王。", "b": "《孟子》"}]}, {"meaning": "恩惠。", "cites": [{"t": "则民与子仁。", "b": "《论语》。皇疏:“恩也。”"}, {"t": "厚泽深仁,遂有天下。", "b": "鲁迅《伪自由书》"}]}, {"meaning": "同情, 怜悯。", "cites": [{"t": "呼而怨,欲望其哀且仁者,愈大谬矣。", "b": "柳宗元《天说》"}]}, {"meaning": "人。", "cites": [{"t": "仁者,人也。", "b": "《礼记·中庸》。注:“人也,读如相人偶之人。”"}, {"t": "仁者,人也。", "b": "《孟子·尽心下》"}, {"t": "虽告之曰:“井有仁焉。”其从之也?", "b": "《论语·雍也》"}]}, {"meaning": "古县名。", "cites": [{"t": "又并蒲、衍、首、垣,以临仁、平丘。", "b": "《史记·春申君列传》"}]}, {"meaning": "水名。", "cites": [{"t": "乌江,府东七十里;源出水西蛮界,绕府南与湘、洪、仁三江合。", "b": "顾祖禹《读史方舆纪要》"}]}, {"meaning": "等于8尺(一说7尺,也有说5.6尺或4尺的)的中国古代长度单位", "cites": [{"t": "九成之台,作于羸土,百仁之高,台(始)于足下。", "b": "《马王堆汉墓帛书·老子甲本》"}]}, {"meaning": "温润。", "cites": [{"t": "汉水重安而宜竹,江水肥仁而宜稻。", "b": "《淮南子》"}]}, {"meaning": "亲爱。", "cites": [{"t": "公子为人,仁而下士。", "b": "《史记·魏公子列传》"}, {"t": "[陛下] 有仁民爱物之意。", "b": "王安石《上时政书》"}]}, {"meaning": "同情;怜悯。", "cites": [{"t": "将大其声,疾呼而望其仁之也。", "b": "韩愈《后十九日复上书》"}]}, {"meaning": "思念。", "cites": [{"t": "郊社之义,所以仁鬼神也;…食飨之礼,所以仁宾客也。", "b": "《礼记·仲尼燕居》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('129wx','什','1','shén shí','亻','4','','[{"pinyin": "shén", "defs": [{"meaning": "代词，表示疑问", "words": [{"w": "什么", "t": "表示询问某人、某物或某事的本身或性质"}]}, {"meaning": "代词，指不确定的事物"}, {"meaning": "虚指,表示不肯定的事物 "}, {"meaning": "表示否定"}, {"meaning": "表示惊讶或激动 "}, {"meaning": "一切事物"}, {"meaning": "用在‘也’前,表示所说的范围之内无例外"}, {"meaning": "用在‘都’前,表示所说的范围之内无例外"}]}, {"pinyin": "shí", "defs": [{"meaning": "(会意。从人十。十亦声。本义:“什”是集体的十)。"}, {"meaning": "同本义。", "cites": [{"t": "什,相什保也。", "b": "《说文》"}, {"t": "会其什伍。", "b": "《周礼·官正》。注:“五人为伍,二五为十。”"}, {"t": "军旅什伍。", "b": "《礼记·祭义》。注:“士卒部曲也。”"}, {"t": "十夫为什。", "b": "《周书·大聚》"}, {"t": "十家为什。", "b": "《管子·立政》"}, {"t": "纷披风什。", "b": "《文选·沈约·谢灵运传》。注:“诗每十篇同卷,故曰什也。”"}, {"t": "王以师友处之,每有文什,必令润色,然后示人。", "b": "《北史》"}, {"t": "尝以什倍之地,百万之众,叩关而攻秦。", "b": "贾谊《过秦论》"}]}, {"meaning": "十倍。", "cites": [{"t": "使有什伯之器而不用。", "b": "《老子》"}, {"t": "或相倍蓰,或相什百。", "b": "《孟子·滕文公上》"}]}, {"meaning": "(五倍为蓰)。", "cites": [{"t": "天所不飨,什倍于前。", "b": "《汉书·谷永传》"}], "words": [{"w": "什袭", "t": ""}]}, {"meaning": "十成,十分,十分之几(古人称“什几”)。", "cites": [{"t": "其实皆什一也。", "b": "《孟子·滕文公上》"}, {"t": "会天寒,士卒堕指者什二三。", "b": "《史记·高祖本纪》"}, {"t": "逐什二以为务。", "b": "《史记·苏秦传》"}, {"t": "以为能相通者什九,不者什一。", "b": "徐光君《甘薯疏序》"}], "words": [{"w": "什一", "t": "十分之一;十分税一;以十博一"}, {"w": "什二", "t": "十分之二"}, {"w": "什九", "t": "十分之九。指绝大多数。"}]}, {"meaning": "杂;多种的。", "cites": [{"t": "什,聚也,杂也。吴楚之间谓资生杂具为什物。", "b": "《三苍》"}, {"t": "作什器于寿邱。", "b": "《史记·五帝纪》。索引:“人家常用之器非一,故以十为数,犹今云什物也。”"}, {"t": "军资什物,不曾遗弃。", "b": "《三国演义》"}], "words": [{"w": "什具", "t": "各种日用器具"}, {"w": "什面", "t": "世面。指社会上各方面的情况。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('130wx','片','1','piàn piān','片','4','','[{"pinyin": "piàn", "defs": [{"meaning": "(指事。甲骨文字形,象劈开的木片。本义:劈开树木之类)。"}, {"meaning": "同本义。", "cites": [{"t": "片,判木也,从半木。", "b": "《说文》。段注:“谓一分为二之木片。”"}], "words": [{"w": "片批", "t": "切肉的一种刀法。刀略倾斜,切之使肉成片状。"}]}, {"meaning": "扁而薄的东西。", "cites": [{"t": "雪片一冬深。", "b": "唐·杜甫《寄杨五桂州谭因州参军段子之任》"}], "words": [{"w": "唱片;画片;相片;影片;片石", "t": "片状石料"}, {"w": "木片;玉兰片;虾片;名片;瓦片;片楮", "t": "片纸。"}]}, {"meaning": "半;整体中的一小部分或较大地区内划出来的较小地区。", "cites": [{"t": "片言可以折狱者。", "b": "《论语》"}], "words": [{"w": "分片包干;片儿会;片简", "t": "片断的文字材料"}, {"w": "片断", "t": "指整体中的一部分"}, {"w": "片玉", "t": "比喻群贤之一"}, {"w": "分片负责;土地连成片;片合", "t": "两半相合。指交配。"}]}, {"meaning": "雪花。", "cites": [{"t": "密片无声急复迟,纷纷犹胜落花时。", "b": "唐·方干《叙雪寄喻凫》"}]}, {"meaning": "词的分段称分片,上段叫“上片”,下段叫“下片”。下一段的开头叫“过片”。"}, {"meaning": "微小;微少。", "cites": [{"t": "卧此片时醒。", "b": "唐·杜甫《高柟》"}], "words": [{"w": "片言折之", "t": "用三言两语去说服他"}, {"w": "片札", "t": "小简,短信"}, {"w": "片善", "t": "微小的优点"}, {"w": "片语", "t": "简短的话"}, {"w": "片霎", "t": "片刻,刹那"}, {"w": "片辞", "t": "简短的言辞"}, {"w": "片鳞半爪", "t": "喻事物的极小部分"}, {"w": "片句", "t": "简短的语句。"}]}, {"meaning": "形容薄而成片的东西。", "cites": [{"t": "两岸青山相对出,孤帆一片日边来。", "b": "唐·李白《望天门山》"}], "words": [{"w": "两片安眠药", "t": ""}]}, {"meaning": "延伸的平面或广阔区域(如陆地或水域)。", "cites": [{"t": "一片孤城万仞山。", "b": "唐·王之涣《凉州词》"}, {"t": "听取蛙声一片。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "印度南部的一片热带农村地区;两河之间的一片森林地带", "t": ""}]}]}, {"pinyin": "piān", "defs": [{"meaning": "指有图像、景物或录有声音的片子。", "words": [{"w": "唱片儿", "t": ""}, {"w": "画片儿", "t": ""}, {"w": "相片儿", "t": ""}, {"w": "影片儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('131wx','仆','1','pū pú','亻','4','','[{"pinyin": "pū", "defs": [{"meaning": "向前跌倒。", "cites": [{"t": "仆,顿也。", "b": "《说文》。朱骏声曰:“前覆曰仆,后仰曰偃。”"}, {"t": "仆表决漏。", "b": "《史记·司马穰苴传》。索隐:“卧其表也。”"}, {"t": "度水跌仆。", "b": "《素问·经脉别论》"}, {"t": "卒仆济北。", "b": "《汉书·邹阳传》。注:“僵仆也。”"}, {"t": "卫士仆地。", "b": "《史记·项羽本纪》"}], "words": [{"w": "前仆后继;仆然", "t": "扑通倒下的样子"}, {"w": "仆顿", "t": "精疲力竭而倒仆"}, {"w": "仆僵", "t": "跌倒;翻倒。"}]}, {"meaning": "下坠;倾倒。", "cites": [{"t": "距洞百余步,有碑仆道,其文漫灭。", "b": "宋·王安石《游褒禅山记》"}, {"t": "旧碑断折,其半仆地。", "b": "唐·韩愈《祭湘君夫人文》"}], "words": [{"w": "仆旗", "t": "放倒战旗。借指休战。"}]}]}, {"pinyin": "pú", "defs": [{"meaning": "(会意。从人,从菐,菐亦声。古文从臣,从菐。甲骨文字形,象一个罪人端着畚箕,从事卑贱劳动之形。本义:供役使的人。即奴隶)。"}, {"meaning": "同本义。", "cites": [{"t": "僕,给事者。", "b": "《说文》"}, {"t": "景命有仆。", "b": "《诗·大雅·既醉》"}]}, {"meaning": "又。", "cites": [{"t": "其仆维何。", "b": ""}, {"t": "隶臣僚,隶臣仆,仆臣台。", "b": "《左传·昭公七年》"}, {"t": "则是臣仆庶孽之事也。", "b": "《公羊传·宣公二十七年》"}, {"t": "仕于家曰仆。", "b": "《礼记·礼运》"}, {"t": "得僮仆贞。", "b": "《易·旅》"}], "words": [{"w": "男仆;女仆;忠仆;仆童", "t": "未成年的仆人"}, {"w": "仆斋", "t": "执役室中之仆人"}, {"w": "仆马", "t": "仆从与乘马"}, {"w": "仆乘", "t": "仆从与舆马"}, {"w": "仆旅", "t": "跟随出行的仆从"}, {"w": "仆舆", "t": "仆从与车乘。"}]}, {"meaning": "驾车的人。", "cites": [{"t": "召彼仆夫。", "b": "《诗·小雅·出车》"}], "words": [{"w": "仆御", "t": "驾车马者。"}]}, {"meaning": "驾车。", "cites": [{"t": "子适卫,冉有仆。", "b": "《论语·子路》"}], "words": [{"w": "仆夫", "t": "驾车的人"}, {"w": "仆圉", "t": "驾车养马。"}]}, {"meaning": "古时男子谦称自己。", "cites": [{"t": "今提一匕首入不测之强秦,仆所以留者,待吾客与俱。", "b": "《战国策·燕策》"}, {"t": "仆非敢如是也。", "b": "汉·司马迁《报任安书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('132wx','化','1','huà huā','亻','4','','[{"pinyin": "huà", "defs": [{"meaning": "(古字为“匕”。会意。甲骨文,从二人,象二人相倒背之形,一正一反,以示变化。本义:变化,改变)。"}, {"meaning": "同本义。", "cites": [{"t": "匕,变也。", "b": "《说文》。徐灏曰:“匕化古今字。”"}, {"t": "知变化之道。", "b": "《易·系辞传》。虞注:“在阳称变,在阴称化,四时变化。”荀注:“春夏为变,秋冬为化,坤化为物。”"}, {"t": "和故百物化焉。", "b": "《礼记·乐记》"}, {"t": "若欲其化也。", "b": "《周礼·柞氏》。注:“犹生也。”"}, {"t": "状态而实无别而为异者谓之化。", "b": "《荀子·正名》。注:“化者改旧形之名。”"}, {"t": "胜败若化。", "b": "《国语·晋语》。注:“言转化无常也。”"}, {"t": "因时而化。", "b": "《吕氏春秋·察今》"}, {"t": "终不能化。", "b": "《史记·货殖列传》"}, {"t": "身化促织。", "b": "《聊斋志异·促织》"}, {"t": "而骨化石。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "化现", "t": "变化"}, {"w": "化心", "t": "改变其心性"}, {"w": "化先", "t": "四时变化之始"}, {"w": "化治", "t": "变化治理。"}]}, {"meaning": "教化。", "cites": [{"t": "化,教行也。", "b": "《说文》。段注:“上匕之而下从匕谓之化。”"}, {"t": "以礼乐合天地之化。", "b": "《周礼·大宗伯》"}, {"t": "渐也,顺也,靡也,久也,服也,羽也,谓之化。", "b": "《荀子·七法篇》"}, {"t": "神则能化矣。", "b": "《荀子·不苟篇》"}, {"t": "变则化。", "b": "《礼记·中庸》"}, {"t": "淳淳乎纯谨畏化。", "b": "《吕氏春秋·士容》。注:“教也。”"}, {"t": "明明求仁义,常恐不能化民者,卿大夫意也。", "b": "杨恽《报孙会宗书》"}], "words": [{"w": "化声", "t": "因推行教化而有声誉"}, {"w": "化行", "t": "教化播扬于某地"}, {"w": "化诲", "t": "开导教诲"}, {"w": "化雨", "t": "比喻善于施教,犹如雨水滋润植物一样"}, {"w": "化作", "t": "化育生成"}, {"w": "化物", "t": "化育外物"}, {"w": "化胎", "t": "化育成胎"}, {"w": "化气", "t": "化育之气"}, {"w": "化光", "t": "德化光大"}, {"w": "化向", "t": "受德化而归顺"}, {"w": "化流", "t": "德化传布。"}]}, {"meaning": "感化;转变人心。", "cites": [{"t": "正月实来化我也。", "b": "《公羊传·桓公六年》。注:“行过无礼谓之化。”"}, {"t": "是以圣王制世御俗,独化于陶钧之上。", "b": "邹阳《狱中梁王书》"}], "words": [{"w": "化俗", "t": "化民成俗,改善习俗"}, {"w": "化物", "t": "感化外物"}, {"w": "化服", "t": "感化顺服"}, {"w": "化盗", "t": "感化盗贼使为良民。"}]}, {"meaning": "募化。", "cites": [{"t": "你去那里化些斋吃。", "b": "《西游记》"}], "words": [{"w": "化饭", "t": "化斋"}, {"w": "化布施", "t": "即化缘。佛教用语。募化钱粮"}, {"w": "化钱", "t": "募化钱财"}, {"w": "化斋", "t": "僧道向人募化斋饭。"}]}, {"meaning": "消化;领会,融会贯通。", "cites": [{"t": "学而不化,非学也。", "b": "杨万里《庸言》"}], "words": [{"w": "化食", "t": ""}, {"w": "食古不化", "t": ""}]}, {"meaning": "死。", "cites": [{"t": "同物既无虑,化去不复悔。", "b": "晋·陶渊明《读山海经》"}, {"t": "惟君平昔,聪明绝人,今虽化去,夫岂无物!", "b": "唐·刘禹锡《祭柳员外文》"}]}, {"meaning": "消除,去掉。", "cites": [{"t": "以化腥臊。", "b": "《韩非子·五蠹》"}]}, {"meaning": "习俗,风气。", "cites": [{"t": "伤化败俗,大乱之道也。", "b": "《汉书》"}]}, {"meaning": "造化。自然的功能。", "cites": [{"t": "修短随化。", "b": "王羲之《兰亭集序》"}], "words": [{"w": "化力", "t": "造化之力"}, {"w": "化元", "t": "造化的本原"}, {"w": "化功", "t": "造化之功"}, {"w": "化儿", "t": "造化小儿。"}]}]}, {"pinyin": "huā", "defs": [{"meaning": "用掉、耗费。", "words": [{"w": "化钱", "t": ""}, {"w": "化工夫", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('133wx','仇','1','chóu qiú','亻','4','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从人,九声。(qiú)本义:匹偶,同伴)。"}, {"meaning": "怨恨。", "cites": [{"t": "仇者,讐也。", "b": "《史记·晋世家》"}, {"t": "葛伯仇饷。", "b": "《孟子》"}, {"t": "多仇少与。", "b": "《汉书·盖宽饶传》"}, {"t": "以先国家之急而后私仇也。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "仇忌", "t": "怨恨憎恶"}, {"w": "仇嫌", "t": "怨仇;怨恨。"}]}, {"meaning": "仇恨。", "cites": [{"t": "悉以家财求客刺秦王,为韩报仇。", "b": "《史记·留侯世家》"}], "words": [{"w": "杀父之仇;仇疾", "t": "仇恨"}, {"w": "仇害", "t": "因仇恨而伤害。"}]}, {"meaning": "仇人;仇敌。", "cites": [{"t": "公子使客斩其仇头,敬进如姬。", "b": "《史记·魏公子列传》"}, {"t": "智法之士与当塗之人,不可两存之仇也。", "b": "《韩非子·孤愤》"}], "words": [{"w": "仇仇", "t": "怨敌。"}]}, {"meaning": "报复。", "cites": [{"t": "臧使者枉用三尺,以仇一言之憾,国贼戾之士哉!", "b": "高启《书博鸡者事》"}]}]}, {"pinyin": "qiú", "defs": [{"meaning": "(形声。从人,九声。本义:同伴)。"}, {"meaning": "同本义。", "cites": [{"t": "仇,雠也。", "b": "《说文》。按,谓雠也,二人相当相对之谊。"}, {"t": "仇,匹也,合也。", "b": "《尔雅·释诂》"}, {"t": "赳赳武夫,公侯好仇。", "b": "《诗·周南·无衣》"}, {"t": "公侯好仇。", "b": "《诗·周南·兔置》。笺:“怨耦曰仇。”"}, {"t": "君子好仇。", "b": "《礼记·缁衣》"}]}, {"meaning": "配偶。", "cites": [{"t": "我仇有疾,不我能即。", "b": "《易·鼎》"}, {"t": "结发辞严亲,来为君子仇。", "b": "三国魏·曹植《浮萍篇》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('134wx','币','1','bì','巾','4','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从巾,敝声。从巾表示与布帛有关。本义:古人用作礼物的丝织品)。"}, {"meaning": "同本义。", "cites": [{"t": "幣,帛也。", "b": "《说文》"}, {"t": "四曰幣贡。", "b": "《周礼·大宰》。司农注:“绣帛。”"}, {"t": "幣曰量幣。", "b": "《礼记·曲礼》"}, {"t": "用圭璧更皮幣。", "b": "《礼记·月令》"}, {"t": "事之以皮幣。", "b": "《孟子》"}, {"t": "寡君是故使吉(游吉)奉其皮幣。", "b": "《左传·襄公二十八年》"}, {"t": "请具车马皮幣。", "b": "《战国策·齐策三》"}], "words": [{"w": "皮币", "t": "兽皮和缯布"}, {"w": "币玉", "t": "帛和玉,祭祀用品"}, {"w": "币号", "t": "祭祀用的物品名称"}, {"w": "币献", "t": "进献的礼品。"}]}, {"meaning": "泛指车马皮帛玉器等礼物。", "cites": [{"t": "凡执幣者。", "b": "《仪礼·十相见礼》。疏:“玉马皮圭璧帛,皆称幣。”"}, {"t": "宋公以幣请于卫。", "b": "《左传·隐公八年》"}, {"t": "惠王患之,乃令张仪佯去秦,厚幣委质事楚。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "币马", "t": "用作礼物的马匹。"}]}, {"meaning": "泛指财物。", "cites": [{"t": "以珠玉为上幣,以黄金为中幣,以刀布为下幣。", "b": "《管子·国蓄》"}]}, {"meaning": "货币,钱。", "cites": [{"t": "有司以幣轻多奸。", "b": "《汉书·武帝纪》"}], "words": [{"w": "金币,银币;外币;纸币;硬币", "t": ""}]}, {"meaning": "破旧;弃;败坏。", "cites": [{"t": "不腆先君之币器。", "b": "《国语·鲁语上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('135wx','仍','1','réng','亻','4','','[{"pinyin": "réng", "defs": [{"meaning": "(形声。从人,乃声。本义:因袭,依旧)。"}, {"meaning": "同本义。", "cites": [{"t": "仍,因也。", "b": "《说文》"}, {"t": "彫玉仍几。", "b": "《书·顾命》"}, {"t": "仍旧贯。", "b": "《论语·先进》"}, {"t": "据行事,仍人道。", "b": "《汉书·艺文志》"}, {"t": "天灾仍重,朕甚惧焉。", "b": "《汉书·成帝纪》"}], "words": [{"w": "仍复", "t": "仍然;依旧"}, {"w": "仍前", "t": "仍按先前;照旧"}, {"w": "仍了旧贯", "t": "做了过去的事"}, {"w": "一仍其旧;仍几", "t": "保留原样的几案。"}]}, {"meaning": "接续;连续。", "cites": [{"t": "夫吉凶之相仍兮。", "b": "《文选·张衡·思玄赋》"}, {"t": "愁病相仍,剔尽寒灯梦不成。", "b": "朱淑贞《减字木兰花》"}, {"t": "旧雨仍新雨,今年胜去年。", "b": "宋·杨万里《和周仲容春日二律句》"}], "words": [{"w": "仍接", "t": "接连不断"}, {"w": "仍岁", "t": "连年;多年"}, {"w": "仍世", "t": "累世;历代"}, {"w": "仍耗", "t": "不断消耗。"}]}, {"meaning": "牵引。", "cites": [{"t": "随飘风之所仍。", "b": "《楚辞·九章·悲回风》"}]}, {"meaning": "仍旧,还是。", "cites": [{"t": "一狼仍从。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "仍然", "t": "仍旧。照前不变或恢复原状。"}]}, {"meaning": "一再;频繁。", "cites": [{"t": "今大将军仍复克获。", "b": "《汉书·武帝纪》。注:“频也。”"}], "words": [{"w": "仍叠", "t": "频繁"}, {"w": "仍重", "t": "频繁。"}]}, {"meaning": "于是;乃。", "cites": [{"t": "帝叱之,皆散,仍收药而反。", "b": "《南史·宋武帝纪》"}], "words": [{"w": "仍就", "t": "就,便"}, {"w": "仍因", "t": "依托;凭借。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('136wx','仅','1','jǐn jìn','亻','4','','[{"pinyin": "jǐn", "defs": [{"meaning": "(形声。从人,堇(qín)声。本义:仅能,只能) 同本义。", "cites": [{"t": "仅,才能也。", "b": "《说文》"}, {"t": "仅逮是月也。", "b": "《公羊传·僖公十六年》"}, {"t": "仅然后得兔。", "b": ""}, {"t": "余一人仅亦守府。", "b": "《国语·周语》"}, {"t": "仅以救亡者。", "b": "《战国策·秦策》"}, {"t": "仅得免死。", "b": "《战国策·齐策四》"}, {"t": "仅容旋马。(仅仅能够让一匹马转过身。)", "b": "宋·司马光《训俭示康》"}, {"t": "室仅方丈。", "b": "明·归有光《项脊轩志》"}, {"t": "仅循资迁。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "绝无仅有;仅有二元;仅见他三次;不仅听见它,也看见了它;他仅十岁", "t": ""}]}]}, {"pinyin": "jìn", "defs": [{"meaning": "", "words": [{"w": "山城仅百层;士卒仅千人", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('137wx','斤','1','jīn jin','斤','4','','[{"pinyin": "jīn", "defs": [{"meaning": "(象形。甲骨文字形,上面是横刃,下为曲柄,象斧斤形。本义:斧子一类的工具)。"}, {"meaning": "同本义  。一般用以砍木,与斧相似,比斧小而刃横。", "cites": [{"t": "今,斫木斧也。", "b": "《说文》。段注:“凡斫物者皆曰斧,斫木之斧,则谓之斤。”"}, {"t": "于是乎丌釿锯制焉。以釿为之。", "b": "《庄子·在宥》"}, {"t": "皆执利兵,无者执斤。", "b": "《左传·哀公二十五年》"}, {"t": "不夭斤斧。", "b": "《庄子·逍遥游》"}, {"t": "以斧斤考击而求之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "斤斧", "t": "斧头"}, {"w": "斤墨", "t": "斧头与墨斗"}, {"w": "斤凿", "t": "斧头与凿子。"}]}, {"meaning": "古代一种似锄但比锄小的农具。", "cites": [{"t": "恶金以铸锄、夷、斤…", "b": "《国语》"}]}, {"meaning": "砍削,砍杀。", "cites": [{"t": "不斤不斧。", "b": "皮日休《河桥赋》"}, {"t": "横斤山木。", "b": "《南史·宋测传》"}]}, {"meaning": "也作“觔”。中国和东南亚各国所用的各种重量单位中,均在600克左右;亦指中国在1929年规定的标准单位,等于1.1023磅或500克。", "cites": [{"t": "十六两为一斤。", "b": "《汉书·律历志》"}, {"t": "四十斤金椎。", "b": "《史记·魏公子列传》"}, {"t": "千余斤。", "b": "唐·白居易《卖炭翁》"}, {"t": "四五十斤。", "b": "明·魏禧《大铁椎传》"}, {"t": "市肉二斤。", "b": "清·张廷玉《明史》"}], "words": [{"w": "斤两", "t": "计算重量的单位"}, {"w": "斤重", "t": "重量。"}]}]}, {"pinyin": "jin", "defs": [{"meaning": "——如“千斤”(qiānjin):起重的工具。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('138wx','爪','1','zhǎo zhuǎ','爪','4','','[{"pinyin": "zhǎo", "defs": [{"meaning": "(象形。按甲骨文和小篆字形,“又”是手,两点表手爪甲形。本义:人的指甲、趾甲)。"}, {"meaning": "同本义。", "cites": [{"t": "爪,人之指叉或亦通作爪。", "b": "《六书故》"}], "words": [{"w": "爪甲", "t": "指或趾前的角质硬壳"}, {"w": "爪翦", "t": "修剪手指甲或脚趾甲。"}]}, {"meaning": "鸟兽的脚趾。", "cites": [{"t": "蚓无爪牙之利。", "b": "《荀子·劝学》"}, {"t": "虫已在爪下。", "b": "《聊斋志异·促织》"}, {"t": "鳞爪飞扬。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "虎爪;猫爪;前爪;张牙舞爪;鹰爪;爪嘴", "t": "鸟类的爪和嘴"}, {"w": "爪吻", "t": "鸷禽猛兽的爪和嘴。喻帮凶。"}]}, {"meaning": "抓,搔。", "cites": [{"t": "爪其肤以验其生柘。", "b": "唐·柳宗元《种树郭橐驼传》"}]}, {"meaning": "剪指甲或趾甲。", "cites": [{"t": "小臣爪足。", "b": "《礼记·丧大记》"}], "words": [{"w": "爪足", "t": "剪脚趾甲"}, {"w": "爪手翦须", "t": "修剪手指甲和胡须"}, {"w": "爪翦", "t": "修剪手指甲和脚趾甲。"}]}]}, {"pinyin": "zhuǎ", "defs": [{"meaning": "鸟兽的脚爪 。多用于口语。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('139wx','反','1','fǎn','又','4','','[{"pinyin": "fǎn", "defs": [{"meaning": "(象形。甲骨文字形,从又从厂。“厂”音hǎn。本义:手心翻转)。"}, {"meaning": "同本义", "cites": [{"t": "反,覆也。", "b": "《说文》"}, {"t": "以齐王,由反手也。", "b": "《孟子·公孙丑上》"}, {"t": "何以知其不反水浆邪?", "b": "《汉书·张安世传》"}]}, {"meaning": "反覆。", "cites": [{"t": "安反侧于万物。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "不思其反。", "b": "《诗·卫风·氓》"}, {"t": "成反复自念。", "b": "《聊斋志异·促织》"}], "words": [{"w": "辗转反侧", "t": ""}, {"w": "反易", "t": "颠倒"}, {"w": "反风", "t": "风向倒转。"}]}, {"meaning": "返回;回归。", "cites": [{"t": "使子路反见之。", "b": "《论语·微子》"}, {"t": "夫迷途知反,往哲是与。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "至竟而反。", "b": "《战国策·卫策》"}, {"t": "三年而反。", "b": "《墨子·鲁问》"}, {"t": "旬有五日而后反。", "b": "《庄子·逍遥游》"}, {"t": "经纶世务者,窥谷忘反。", "b": "吴均《与朱元思书》"}, {"t": "今日往而不反者,竖子也!”", "b": "《战国策·燕策》"}, {"t": "则盍反其本矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "反意", "t": "返归的念头"}, {"w": "反国", "t": "归国"}, {"w": "反真", "t": "返归淳朴"}, {"w": "反根", "t": "返回本原。"}]}, {"meaning": "未能遵守,违背。", "cites": [{"t": "天反时为灾,地物为妖,民反德为乱。", "b": "《左传》"}], "words": [{"w": "反背", "t": "背叛"}, {"w": "反德", "t": "违背事物的准则"}, {"w": "反道", "t": "违反正道"}, {"w": "反情", "t": "违反人情"}, {"w": "反古", "t": "违反古训。"}]}, {"meaning": "往返于…之间。", "cites": [{"t": "寒暑易节始一反焉。", "b": "《列子·汤问》"}], "words": [{"w": "反往", "t": "往返"}, {"w": "反报", "t": "往还,反复。"}]}, {"meaning": "反叛;造反。", "cites": [{"t": "上官桀子安与桑弘羊及燕主、盖主谋反。", "b": "《汉书·李广苏建传》"}, {"t": "日夜望将军至,岂敢反乎!", "b": "《史记·项羽本纪》"}], "words": [{"w": "反上", "t": "背叛君主"}, {"w": "反天", "t": "造反"}, {"w": "反心", "t": "背叛之心"}, {"w": "反外", "t": "背叛,离异。"}]}, {"meaning": "反省。", "cites": [{"t": "知不足,然后能自反。", "b": "《礼记·学礼》"}], "words": [{"w": "反情", "t": "内省"}, {"w": "反听", "t": "自我省察"}, {"w": "反观", "t": "反省"}, {"w": "反躬自问", "t": "反问自己。"}]}, {"meaning": "归还;送还。", "words": [{"w": "反籍", "t": "归还天子之位"}, {"w": "反璧", "t": "归还璧玉;表示不贪取财宝。"}]}, {"meaning": "类推。", "cites": [{"t": "举一隅,不以三隅反,则不复也。", "b": "《论语·述而》"}], "words": [{"w": "反隅", "t": "比喻类推。能由此而知彼"}, {"w": "反惑", "t": "释疑。"}]}, {"meaning": "贱买而贵卖。"}, {"meaning": "相反的;对立的。与“正”相对。", "cites": [{"t": "君子成人之美,不成人之恶,小人反是。", "b": "《论语·颜渊》"}, {"t": "非务相反也,时势异也。", "b": "《吕氏春秋·察今》"}, {"t": "然而成败异变,功业相反也。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "适得其反", "t": ""}, {"w": "反心内照", "t": "反过来对照一下自己"}, {"w": "反抄耳光", "t": "反手巴掌"}, {"w": "反斜面", "t": ""}, {"w": "反函数", "t": ""}, {"w": "反定理", "t": ""}, {"w": "反科学", "t": ""}, {"w": "反义", "t": ""}]}, {"meaning": "反而;相反。", "cites": [{"t": "反以我为讎。", "b": "《诗·邶风·谷风》"}, {"t": "动而见尤,欲益反损。", "b": "汉·司马迁《报任安书》"}, {"t": "今其智乃反不能及,其可怪也欤。", "b": "唐·韩愈《师说》"}, {"t": "情罪重者反出在外。", "b": "清·方苞《狱中杂记》"}, {"t": "信知生男恶,反是生女好。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "反且", "t": "反而。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('140wx','介','1','jiè','人','4','','[{"pinyin": "jiè", "defs": [{"meaning": "(象形。甲骨文字形,象人身上穿着铠甲形。中间是人,两边的四点象联在一起的铠甲片。本义:铠甲。一种用来防身的武器)。"}, {"meaning": "同本义。", "cites": [{"t": "驷介旁旁。", "b": "《诗·郑风·清人》"}, {"t": "舍尔介狄。", "b": "《诗·大雅·瞻卬》"}, {"t": "其虫介。", "b": "《淮南子·脩务》"}, {"t": "急则用介胄之士。", "b": "《史记·老庄甲韩列传》"}], "words": [{"w": "介士", "t": "穿着甲胄的兵士"}, {"w": "介卒", "t": "甲兵"}, {"w": "介胄", "t": "铠甲与头盔、披甲戴盔"}, {"w": "介人", "t": "武士,甲士"}, {"w": "介马", "t": "披甲的战马。"}]}, {"meaning": "疆界;界限", "cites": [{"t": "介,画也。", "b": "《说文》。按,八者分也。从人者,取人身之左右以见意。"}, {"t": "无此疆尔界。", "b": "《诗·周颂·思文》。陆德明释文:“界”作“介。”"}, {"t": "所得神书百七十卷,皆缥白素朱介青首朱目。", "b": "《后汉书》"}]}, {"meaning": "传宾主之言的人。古时主有傧相迎宾,宾有随从通传叫介。", "cites": [{"t": "诸侯相见,卿为介。", "b": "《荀子·大略》"}], "words": [{"w": "介绍;介宾", "t": "宾客,贵宾;古代行乡饮酒礼时辅佐宾客的人。"}]}, {"meaning": "节操;独特之行。", "cites": [{"t": "柳下惠不以三公易其介。", "b": "《孟子》"}]}, {"meaning": "披甲。", "cites": [{"t": "不介马而驰之。", "b": "《左传·成公二年》"}, {"t": "季氏介其鸡。", "b": "《左传·昭公二十五年》"}, {"t": "介者不释。", "b": "《史记》"}], "words": [{"w": "介胄", "t": "披甲戴盔"}, {"w": "介马", "t": "给战马披甲。"}]}, {"meaning": "介入;居中。", "cites": [{"t": "介居二大国之间。", "b": "《左传·襄公九年》"}], "words": [{"w": "介和", "t": "调解,说合。"}]}, {"meaning": "介绍。", "cites": [{"t": "其所以相亲也,不介而自亲。", "b": "李康《命运论》"}], "words": [{"w": "介函", "t": "介绍信。"}]}, {"meaning": "介意;留存。", "cites": [{"t": "不以介怀。", "b": "李延寿《南史》"}], "words": [{"w": "介怀", "t": "耿耿于怀"}, {"w": "介介然", "t": "形容心事重重"}, {"w": "介心", "t": "介意,把不快的事记在心里"}, {"w": "介虑", "t": "介意忧虑。"}]}, {"meaning": "间隔,隔开。", "cites": [{"t": "前乡崧高,后介大河。", "b": "《汉书·翼奉传》"}]}, {"meaning": "佐助。", "cites": [{"t": "介尔景福。", "b": "《左传》"}], "words": [{"w": "介眉", "t": "祝寿之词"}, {"w": "介贰", "t": "辅佐"}, {"w": "介寿", "t": "祝寿之词。"}]}, {"meaning": "因;凭借;依靠。", "cites": [{"t": "介人之宠,非勇也。", "b": "《左传·文公六年》"}], "words": [{"w": "介持", "t": "依凭;仗持。"}]}, {"meaning": "独;特异。", "cites": [{"t": "夫介异于人臣。", "b": "《韩非子·外储说左下》"}, {"t": "孑不群而介立。", "b": "张衡《思玄赋》"}, {"t": "介,独也。", "b": "《广雅》"}, {"t": "如有一介臣。", "b": "《书·秦誓》"}, {"t": "亦不使一介行李。", "b": "《左传·襄公八年》"}, {"t": "一介嫡女。", "b": "《国语·吴语》"}, {"t": "援纳断断之介。", "b": "《汉书·孔光传》"}]}, {"meaning": "副;次一等。", "cites": [{"t": "且冢卿无路,介卿以葬,不亦左乎?", "b": "《左传·昭公四年》"}], "words": [{"w": "介卿", "t": "次一等的卿,位于冢卿之下"}, {"w": "介弟", "t": "对别人弟弟的尊称"}, {"w": "介次", "t": "位于市井的小亭"}, {"w": "介使", "t": "副使"}, {"w": "介倅", "t": "副手;辅佐者。"}]}, {"meaning": "细微。", "cites": [{"t": "忧悔吝者存乎介。", "b": "《易·系辞上》"}, {"t": "一介不以与人,一介不以取诸人。", "b": "《孟子·万章上》"}, {"t": "无纤介之祸者。", "b": "《战国策·齐策四》"}, {"t": "不以往事为纤介。", "b": "《汉书·元后传》"}], "words": [{"w": "介丘", "t": "介邱。微小的土山"}, {"w": "介狭", "t": "心胸狭隘"}, {"w": "介焉", "t": "细微的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('141wx','父','1','fǔ fù','父','4','','[{"pinyin": "fǔ", "defs": [{"meaning": "对有才德的男子的美称,多附缀于表字后面。", "cites": [{"t": "维师尚父,时维鹰扬。", "b": "《诗·大雅》"}, {"t": "三月,公及邾仪父盟于眜。", "b": "《春秋》"}, {"t": "余弟安国平父,安上纯父。", "b": "王安石《游褒禅山记》"}]}, {"meaning": "对老年男子的尊称。", "cites": [{"t": "纵江东父老怜而王我,我何面目见之?", "b": "《史记·项羽本纪》"}, {"t": "父知之乎?(父:老先生)", "b": "《史记·张释之冯唐列传》"}], "words": [{"w": "渔父;田父", "t": ""}]}, {"meaning": "开始。", "cites": [{"t": "强梁者不得其死,吾将以为教父。", "b": "《老子·四十二章》"}], "words": [{"w": "教父", "t": "教戒的开始。"}]}, {"meaning": "天。古人以为天地生万物,故称天为“父”。", "cites": [{"t": "乾,天也,故称乎父;坤,地也,故称呼母。", "b": "《易·说卦》"}]}, {"meaning": "(bǔ)。捕捉,捉拿。", "cites": [{"t": "徒以而富(通福)之,父系而伏之。", "b": "《管子·侈靡》"}]}]}, {"pinyin": "fù", "defs": [{"meaning": "(指事。甲骨文字形,象右手持棒之形。意思是:手里举着棍棒教子女守规矩的人是家长,即父亲。本义:父亲)。"}, {"meaning": "同本义。"}, {"meaning": "某人直系血统的上一代男性。", "cites": [{"t": "父,家长举教者。", "b": "《说文》"}, {"t": "生曰父,死曰考。", "b": "《礼记·曲礼》"}]}, {"meaning": "又。", "cites": [{"t": "见父之执。疏:“父执,谓执友与父同志者也。”", "b": ""}, {"t": "父母者,人之本也。", "b": "《史记·屈原贾生列传》"}, {"t": "父至尊也。", "b": "《仪礼·丧服传》"}]}, {"meaning": "又。", "cites": [{"t": "父子手足也。", "b": ""}, {"t": "父者子之天也。", "b": ""}, {"t": "乾为父。", "b": "《易·说卦》"}, {"t": "父者,家之隆也。", "b": "《荀子·致仕》"}, {"t": "孙文举年十岁,随父到洛。", "b": "《世说新语·言语》"}], "words": [{"w": "父执", "t": "父亲的朋友"}, {"w": "父祖", "t": "父亲和祖父"}, {"w": "父宗", "t": "父亲的继承人"}, {"w": "父艰", "t": "父丧。同父忧"}, {"w": "父任", "t": "儿子因父亲任官而得官职"}, {"w": "父执", "t": "父亲的朋友"}, {"w": "父族", "t": "父亲的亲族"}, {"w": "父业", "t": "父亲的事业。"}]}, {"meaning": "指万物化生之本。", "cites": [{"t": "乾为父。", "b": "《易·说卦传》"}], "words": [{"w": "父天", "t": "以天为父"}, {"w": "父母国,父国,父母之邦", "t": "祖国。"}]}, {"meaning": "对和父亲同辈的男性亲属的称呼。如:伯父;叔父;祖父;父老。后亦以称姻亲中的长辈。如:舅父;姨父;岳父。"}, {"meaning": "古代天子、诸侯对同姓长辈的称呼。", "cites": [{"t": "以速诸父。", "b": "《诗·小雅·伐木》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('142wx','从','1','cóng','人','4','','[{"pinyin": "cóng", "defs": [{"meaning": "(会意。甲骨文字形,象二人相从形。本义:随行,跟随)。"}, {"meaning": "同本义。", "cites": [{"t": "従,随行也。", "b": "《说文》"}, {"t": "客从拜辱于朝。", "b": "《周礼·司仪》"}, {"t": "或从王事。", "b": "《易·坤》"}, {"t": "啬人不从。", "b": "《易·夏小正》"}, {"t": "从以孙子。", "b": "《诗·邶风·击鼓》"}, {"t": "禽兽可羁而从之。", "b": "《淮南子·泛论》"}, {"t": "一狼得骨止,一狼仍从。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "从龙", "t": "随从帝王创业开国"}, {"w": "从学", "t": "跟随受学"}, {"w": "从骑", "t": "骑马随从的人"}, {"w": "从嫁", "t": "陪嫁的侍婢"}, {"w": "从井救人", "t": "跟着跳下井去营救落井者。"}]}, {"meaning": "顺从;依从。", "cites": [{"t": "不昭不从。", "b": "《左传·昭公十一年》"}, {"t": "妇人从人者也。", "b": "《礼记·郊特牲》"}, {"t": "从祀先公。", "b": "《左传·定公八年》"}]}, {"meaning": "》。", "words": [{"w": "从权", "t": "依从权宜之计"}, {"w": "从时", "t": "顺合时宜"}, {"w": "从允", "t": "答应,允许"}, {"w": "从服", "t": "归附,顺从。"}]}, {"meaning": "参与其事。", "cites": [{"t": "故从事于道者。", "b": "《老子》。注:“为也。”"}], "words": [{"w": "从戎", "t": "参军"}, {"w": "从事", "t": "官名。汉以后三公和州郡长官都自设僚属,大多数为“从事”。"}]}, {"meaning": "自,由 ——用作虚词,表示起点。", "cites": [{"t": "儿童相见不相识,笑问客从何处来。", "b": "贺知章《回乡偶书》"}], "words": [{"w": "从生", "t": "所由产生"}, {"w": "从自", "t": "自从"}, {"w": "从马上猛跌下来", "t": ""}]}, {"meaning": "因由。", "cites": [{"t": "欲贵其小女,道无从。", "b": "《汉书·外戚传》"}]}, {"meaning": "堂房亲属。", "cites": [{"t": "从祖 从父从母。", "b": "《尔雅·释亲》"}], "words": [{"w": "从母", "t": "姨母,母亲的姊妹"}, {"w": "从女", "t": "侄女"}, {"w": "从子", "t": "侄子"}, {"w": "从兄", "t": "同祖伯叔的儿子而年长于自己的人。"}]}, {"meaning": "言词顺畅的。", "cites": [{"t": "贵在于意达言从,理归乎正。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('143wx','仑','1','lún','人','4','','[{"pinyin": "lún", "defs": [{"meaning": "思。", "cites": [{"t": "仑,思也。", "b": "《说文》"}]}, {"meaning": "自我反省检讨。", "cites": [{"t": "浙江令人自反省者,曰肚里仑一仑。", "b": "《新方言·释言》"}]}, {"meaning": "——见“昆仑”(Kūnlún)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('144wx','今','1','jīn','人','4','','[{"pinyin": "jīn", "defs": [{"meaning": "(会意。从佶亼(jí)。本义:现在)。"}, {"meaning": "同本义。", "cites": [{"t": "今,是时也。", "b": "《说文》"}, {"t": "今,时辞也。", "b": "《苍颉篇》"}, {"t": "迨其今兮。", "b": "《诗·召南·摽有梅》"}, {"t": "于今三年。", "b": "《诗·豳风·东山》"}, {"t": "吾今召君矣。", "b": "《史记·汲郑传》"}, {"t": "今行而无信,则秦未可亲也。", "b": "《战国策·燕策》"}, {"t": "今乃于毛先生而失之也。", "b": "《史记·平原君虞卿列传》"}, {"t": "今其室十无一焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "今之高爵显位。", "b": "明·张溥《五人墓碑记》"}, {"t": "今年四月。(指清朝光绪二十四年(1898年),即戊戌年。四月,旧历。公历是六月。)", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "今朝三明朝四", "t": "指一天天地推诿、拖延"}, {"w": "今雨", "t": "新近结交的朋友"}, {"w": "今愁古恨", "t": "今人之愁和古人之恨"}, {"w": "今下", "t": "现时,眼下"}, {"w": "今夕何夕", "t": "今夜是何夜?多用作赞叹语。谓此良辰。"}]}, {"meaning": "现代;当代。与“古”相对。", "cites": [{"t": "今之乐,犹古之乐也。", "b": "《孟子·梁惠王下》"}], "words": [{"w": "今上", "t": "帝制时代,尊称当代在位的皇帝"}, {"w": "今体", "t": "当代所通行的诗、文、书法等体裁。别于古体而言"}, {"w": "今字", "t": "指当代所使用的文字。即:楷书;隶书。"}]}, {"meaning": "比喻用计谋逃脱,如:今蝉蜕壳。"}, {"meaning": "即将;立刻;马上。", "cites": [{"t": "夺项王天下者,必沛公也,吾属今为之虏矣!", "b": "《史记·项羽本纪》"}]}, {"meaning": "假使,如果。", "cites": [{"t": "今有人于此。", "b": "《墨子·公输》"}, {"t": "今有构木钻燧于夏后氏之世者,必为鲧禹笑矣。(今,如果。)", "b": "《韩非子·五蠹》"}, {"t": "今王鼓乐。", "b": "《孟子·梁惠王下》"}, {"t": "今括一旦为将。", "b": "汉·刘向《列女传》"}, {"t": "今若断斯织。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('145wx','凶','1','xiōng','凵','4','','[{"pinyin": "xiōng", "defs": [{"meaning": "(指事。小篆字形,“凵”象地陷形,读kǎn。“乂”表示这里可陷人。“兇”是会意字,从儿(人),在凶下。本义:不吉利)。"}, {"meaning": "同本义。", "cites": [{"t": "凶,恶也。象地穿交陷其中也。", "b": "《说文》"}, {"t": "凶,咎也。", "b": "《尔雅》"}, {"t": "吉凶者,言乎其得也。", "b": "《易·系辞》"}, {"t": "一曰凶短折。", "b": "《书·洪范》"}, {"t": "日月告凶。", "b": "《诗·小雅·十月之交》。笺:“告天下以凶亡之徵也。”"}, {"t": "“此孰吉孰凶?”", "b": "《楚辞·卜居》"}], "words": [{"w": "凶兆", "t": "不祥的预兆"}, {"w": "凶宿", "t": "凶星"}, {"w": "吉凶未卜;凶星", "t": "不吉祥的星。"}]}, {"meaning": "凶恶可怕。", "cites": [{"t": "作凶事,为凶人。", "b": "《左传·昭公二年》"}, {"t": "顽凶不用。", "b": "《史记·五帝纪》"}, {"t": "向高坐者,故是凶物。", "b": "《世说新语·赏誉》"}, {"t": "除奸凶。", "b": "诸葛亮《出师表》"}], "words": [{"w": "凶人", "t": "凶恶之人"}, {"w": "凶凶", "t": "凶恶的样子"}, {"w": "凶竖", "t": "凶恶的小人"}, {"w": "凶焰", "t": "凶恶的气焰"}, {"w": "凶豪", "t": "凶恶强横"}, {"w": "凶惨", "t": "凶恶残酷。"}]}, {"meaning": "闹饥荒的,歉收的。", "cites": [{"t": "三谷不收谓之凶。", "b": "《墨子·七患》"}, {"t": "大札大凶。", "b": "《周礼·大司乐》"}, {"t": "凶荒杀礼。", "b": "《周礼·掌客》"}, {"t": "河内凶,则移其民于河东。", "b": "《孟子·梁惠王上》"}, {"t": "凶年免于死。", "b": ""}], "words": [{"w": "凶穰", "t": "歉岁与丰年"}, {"w": "凶馑", "t": "灾荒、饥馑"}, {"w": "凶乱", "t": "灾荒祸乱"}, {"w": "凶俭", "t": "灾荒"}, {"w": "凶歉", "t": "歉收,灾荒"}, {"w": "凶灾", "t": "凶年灾荒。"}]}, {"meaning": "与死人有关,丧葬。", "cites": [{"t": "乡共吉凶礼乐之器。", "b": "《周礼·乡师》。注:“凶器,若族丧器者也。”"}], "words": [{"w": "凶耗", "t": "死讯"}, {"w": "凶肆", "t": "出售丧葬用品的商铺"}, {"w": "凶具", "t": "棺材"}, {"w": "凶疚", "t": "丧事的悲痛。"}]}, {"meaning": "恐惧;骚动。", "cites": [{"t": "兇,扰恐也。", "b": "《说文》"}, {"t": "曹人兇惧。", "b": "《左传·僖公二十八年》"}, {"t": "众兇惧。", "b": "《左传·定公十年》"}, {"t": "周处年少时,兇强侠气,为乡里所犯。", "b": "《世说新语·自新》"}, {"t": "敌人而凶,救败不暇,谁能退敌。", "b": "《国语·晋语一》"}]}, {"meaning": "杀人的行为,也指行凶的人。", "cites": [{"t": "把赃物行凶刀杖封了。", "b": "《水浒传》"}], "words": [{"w": "凶徒", "t": "恶人;坏人"}, {"w": "凶渠", "t": "恶人的首领。"}]}, {"meaning": "灾祸。", "cites": [{"t": "我生之后,逢此百凶,尚寐无聪。", "b": "《诗·王风》"}], "words": [{"w": "凶患,凶祸,凶事", "t": "灾祸"}, {"w": "凶困", "t": "灾难"}, {"w": "凶咎", "t": "灾殃"}, {"w": "凶殃", "t": "灾祸。"}]}, {"meaning": "早死;夭亡。", "cites": [{"t": "六极:一曰凶短折。", "b": "《书·洪范》"}], "words": [{"w": "凶夭", "t": "死丧夭亡"}, {"w": "凶折", "t": "凶短折,凶短。短命"}, {"w": "凶候", "t": "死亡的征兆。"}]}, {"meaning": "争讼,吵闹。", "cites": [{"t": "尧曰:“吁顽凶,不用。”", "b": "《史记·五帝本纪》。张守节正义:“凶,讼也。言丹朱心既顽嚣,又好争讼,不可用之。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('146wx','分','1','fēn fèn','刀','4','','[{"pinyin": "fēn", "defs": [{"meaning": "(会意。从八,从刀。“八”就是分;从“刀”,是以刀剖物,使之分开的意思。本义:一分为二)。"}, {"meaning": "同本义。分开,分成,分出,与“合”相对。", "cites": [{"t": "分,别也。", "b": "《说文》"}, {"t": "死生分。", "b": "《礼记·月令》"}, {"t": "然则何以分之?", "b": "《荀子·礼论》"}, {"t": "以齐之分,奉之而不足。", "b": "《荀子·仲尼》"}, {"t": "三首俱烂,不可识别。乃分其汤肉葬之。", "b": "晋·干宝《搜神记》"}, {"t": "江自湖口分一支为南江。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "文官武将…分两行而入。", "b": "《三国演义》"}], "words": [{"w": "分合", "t": "分开与合并"}, {"w": "分地", "t": "分割土地;分封土地"}, {"w": "分间", "t": "分开,间隔"}, {"w": "分灶", "t": "分家度日。"}]}, {"meaning": "辨别,区分。", "cites": [{"t": "五谷不分,孰为夫子!", "b": "《论语·微子》"}, {"t": "地也,你不分好歹何为地!", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "分绝", "t": "区别;分隔"}, {"w": "分划", "t": "区分;划分"}, {"w": "分殊", "t": "区分;区别"}, {"w": "分年", "t": "区别年岁。"}]}, {"meaning": "分给,分配。", "cites": [{"t": "衣食所安,弗敢专也,必以分人。", "b": "《左传·庄公十年》"}, {"t": "而官与吏剖分矣。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "分与", "t": "分给"}, {"w": "分茅裂土", "t": "古代天子分封诸侯时,按封地方向用白茅包土给予受封者。"}]}, {"meaning": "离开;离别。", "cites": [{"t": "执手分道去,各自还家门。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "分袂", "t": "分手、离别"}, {"w": "分北", "t": "分离"}, {"w": "分首", "t": "离别"}, {"w": "分违", "t": "分隔。离别。"}]}, {"meaning": "分散。", "cites": [{"t": "倍则分之,敌则能战之。", "b": "《孙子·谋攻》"}], "words": [{"w": "分损", "t": "分散,减少"}, {"w": "分披", "t": "披散;分散。"}]}, {"meaning": "把…隔开成两半。", "cites": [{"t": "当其南北分者,古长城也。", "b": "清·姚鼐《登泰山记》"}, {"t": "自非亭午夜分,不见曦月。", "b": "郦道元《三峡》"}], "words": [{"w": "分界牌(分别阳间和阴间(生和死)的界标", "t": ""}, {"w": "分墨", "t": "中分墨线。相当于设计图的中心线。"}]}, {"meaning": "排解,调和矛盾。", "cites": [{"t": "天下未定,两虎安得私斗,今日朕分之矣。", "b": "《后汉书》"}]}, {"meaning": "分担,共同承担。", "cites": [{"t": "己乃分城而守。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "分过", "t": "分担过失、过错"}, {"w": "分谤", "t": "分担别人受到的诽谤。"}]}, {"meaning": "时间单位,等于1/60小时,或60秒。"}, {"meaning": "角度测量单位,等于1/60度或60秒。"}, {"meaning": "长度单位,寸的十分之一。", "cites": [{"t": "舟首尾长约八分有奇。", "b": "明·魏学洢《核舟记》"}]}, {"meaning": "价值等于某货币单位百分之一的单位。"}, {"meaning": "用数字表示的质量等级(如牲口或黄油的等级);常以100分为最高等级,并根据某种规定的方案,对一些指定的重要特征(如形态、皮毛的情况、香味等)分配分数,总分恰为100分。"}, {"meaning": "分头;分别。", "cites": [{"t": "吾与足下分任之。", "b": "清·梁启超《谭嗣同传》"}, {"t": "分遣贝勒及它将略定东南郡县。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "分置", "t": "分别设置"}, {"w": "分统", "t": "分别统率"}, {"w": "分掌", "t": "分管"}, {"w": "分治", "t": "分别治理。"}]}, {"meaning": "乱,杂。", "cites": [{"t": "分其师众,人既迷芒,必其将亡,亡之道也。", "b": "《管子·势》"}], "words": [{"w": "分错", "t": "纷乱错杂。"}]}]}, {"pinyin": "fèn", "defs": [{"meaning": "所分之物,整体中的一部分。", "cites": [{"t": "杀士三分之一而城不拔者,此攻城之灾也。", "b": "《孙子·谋攻》"}], "words": [{"w": "股分;部分;分资", "t": "共同送礼或办事情时每个人所分摊的钱"}, {"w": "分例", "t": "按规定或习惯分发的每人一份的钱或物"}, {"w": "分均", "t": "各分相等。"}]}, {"meaning": "分际,合适的界限。", "cites": [{"t": "两个正斗到分际。", "b": "《水浒传》"}], "words": [{"w": "分际", "t": "紧要关头;程度;地步;分毫"}, {"w": "分直", "t": "分齐。犹分际。"}]}, {"meaning": "职分;本分。", "cites": [{"t": "此臣所以报先帝,而忠陛下之职分也。", "b": "诸葛亮《出师表》"}], "words": [{"w": "本分;分守", "t": "职守"}, {"w": "分事", "t": "职分"}, {"w": "分素", "t": "职分确定。"}]}, {"meaning": "原则;原理。", "cites": [{"t": "况夫先王之道、仁义之统、诗书礼乐之分乎?", "b": "《荀子》"}]}, {"meaning": "资质。", "cites": [{"t": "夫聪明者,英之分也,不得雄之胆则说不行;胆者,雄之分也,不得英之智则事不成。", "b": "《人物志》"}]}, {"meaning": "情分。", "cites": [{"t": "恩爱苟不亏,在远分日亲。", "b": "曹植《赠白马王彪》"}], "words": [{"w": "分好", "t": "情义,友谊。"}]}, {"meaning": "甘愿;满意。", "cites": [{"t": "不分桃花红胜锦,生憎柳絮白于绵。", "b": "杜甫《送路六侍御入朝》"}], "words": [{"w": "分甘", "t": "甘愿。"}]}, {"meaning": "意料;料想。", "cites": [{"t": "自分已死久矣。", "b": "《汉书·苏武传》"}], "words": [{"w": "分定", "t": "命中注定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('147wx','乏','1','fá','丿','4','','[{"pinyin": "fá", "defs": [{"meaning": "古代射礼唱靶者用以避箭的器具,其形略似屏风。", "cites": [{"t": "乏,春秋传曰,反正为乏。", "b": "《说文》。按,容也。从反正,推事。受矢者为正,避矢者为乏。"}, {"t": "故文反正为乏。", "b": "《左传·宣公十五年》"}, {"t": "凡乏用革。", "b": "《仪礼·大射仪》"}, {"t": "乏参侯道。", "b": "《仪礼·乡射礼》。注:“容谓之乏,所以为获者御矢也。”"}]}, {"meaning": "无功伏安,电抗性伏安单位。"}, {"meaning": "假借为贬。物质财富短缺。", "cites": [{"t": "振乏绝。", "b": "《吕氏春秋·季春》。"}, {"t": "孟尝君使人给其食用,无使乏。", "b": "《战国策·齐策》"}, {"t": "农不出则乏其食,工不出则乏其事。", "b": "《史记·货殖列传序》"}, {"t": "空乏其身。", "b": "《孟子·告子下》"}], "words": [{"w": "乏资", "t": "缺乏费用"}, {"w": "乏力", "t": "缺少气力"}, {"w": "不乏其人", "t": ""}]}, {"meaning": "荒废;耽误。", "cites": [{"t": "子往矣,无乏吾事。", "b": "《庄子·天地》"}, {"t": "自严奏答无滞,不敢安寝,头目臃肿,事幸无乏。", "b": "《明史》"}]}, {"meaning": "疲乏;无力。", "cites": [{"t": "因其劳乏而乘之。", "b": "《新五代史·周德威传》"}], "words": [{"w": "乏倦", "t": "疲倦"}, {"w": "乏乏", "t": "很疲倦"}, {"w": "人困马乏", "t": ""}]}, {"meaning": "无能的,不中用的。", "cites": [{"t": "我想昭君娘娘跟那西施娘娘难道都是这种乏样子吗?", "b": "《老残游记》"}], "words": [{"w": "乏角儿", "t": "演技不高、没有名气的演员。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('148wx','公','1','gōng','八','4','','[{"pinyin": "gōng", "defs": [{"meaning": "(会意。小篆字形,上面是“八”,表示相背,下面是“厶”(“私”的本字)。合起来表示“与私相背”,即“公正无私”的意思。本义:公正,无私)。"}, {"meaning": "同本义。", "cites": [{"t": "公,平分也。", "b": "《说文》"}, {"t": "背厶谓之公,或说,分其厶以与人为公。", "b": "《韩非子·五蠹》"}, {"t": "公之为言公正无私也。", "b": "《春秋·元命苞》"}, {"t": "兼覆无私谓之公。", "b": "《贾子·道术》"}, {"t": "举公义,辟私怨。—《墨子·尚贤上》", "b": ""}, {"t": "屈平疾王听之不聪也,谗谄之蔽明也,邪曲之害公也,方正之不容也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "公气", "t": "正大,公正"}, {"w": "公素", "t": "公正质朴"}, {"w": "公洁", "t": "公正廉洁"}, {"w": "公慎", "t": "公正谨慎"}, {"w": "公诚", "t": "公正诚实。"}]}, {"meaning": "共,共同。", "cites": [{"t": "天下有公利而莫或兴之,有公害而莫或除之。", "b": "清·黄宗羲《原君》"}, {"t": "今黄生贫类予,其借书亦类予,惟予之公书与张氏之吝书若不相类。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "公患", "t": "共同的忧患,共同的祸患"}, {"w": "公拟", "t": "共同拟定"}, {"w": "公律", "t": "公认的规律。"}]}, {"meaning": "公共,公家,公众的。与“私”相对。", "cites": [{"t": "汉之为汉,凡四十年矣,公私之积,犹可哀痛。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "公中", "t": "公众;大伙儿;公家;公有的。引申为谁也不管的"}, {"w": "公揖", "t": "向众人所作的一个揖礼"}, {"w": "公本", "t": "公众的奏本"}, {"w": "公欲", "t": "公众的欲望"}, {"w": "公饯", "t": "公众举行的饯行宴。"}]}, {"meaning": "朝廷;国家。", "cites": [{"t": "是故身率妻子,戮力耕桑,灌园治产,以给公上。", "b": "《汉书·杨恽传》"}, {"t": "某姓兄弟,以把持公仓,法应立决。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "公上", "t": "朝廷;官家"}, {"w": "公币", "t": "国家铸造的货币"}, {"w": "公壤", "t": "国家公有土地"}, {"w": "公宪", "t": "国法。"}]}, {"meaning": "君王。", "cites": [{"t": "十年春,齐师伐我,公将战。", "b": "《左传·庄公十年》"}], "words": [{"w": "公邑", "t": "国君的直辖地"}, {"w": "公王", "t": "君王"}, {"w": "公府", "t": "君主之府;官府"}, {"w": "公寝", "t": "君主处理政事的宫室"}, {"w": "公庙", "t": "指国君诸侯之庙。"}]}, {"meaning": "公事;政府或机关的工作。", "cites": [{"t": "被(借作“披”,穿)之僮僮(通“童童,光洁的样子),夙夜在公。", "b": "《诗·召南·采蘩》"}, {"t": "矇瞍奏公。", "b": "《诗·大雅·灵台》"}, {"t": "王公伊濯。", "b": "《诗·大雅·文王有声》"}, {"t": "实维尔公允师。", "b": "《诗·周颂·酌》"}, {"t": "有澹台灭明者,行不由径,非公事未尝至于偃(子游名,武城宰)之室也。", "b": "《论语·雍也》"}], "words": [{"w": "公人", "t": "旧时衙门里的差役"}, {"w": "公事人", "t": "犯人"}, {"w": "公见", "t": "公务繁忙。"}]}, {"meaning": "古爵位名。", "cites": [{"t": "公,爵名,五等之首曰公;其余大国称侯;小国称伯、子、男。", "b": "《公羊传》"}, {"t": "尔公尔侯,逸豫(快乐)无期。", "b": "《诗·小雅·白驹》"}]}, {"meaning": "古代朝廷最高官位的通称 。后泛称朝中职高掌权者。", "cites": [{"t": "光凡为御史大夫丞相各再,壹为大司徒、大傅、大师,历三世居公辅位,前后十七年。", "b": "《汉书·孔光传》"}], "words": [{"w": "公卿", "t": "泛指朝廷中的高官"}, {"w": "公族", "t": "诸侯的同族,王公的子孙"}, {"w": "公徒", "t": "诸侯的步兵"}, {"w": "公令", "t": "诸侯的命令"}, {"w": "公孙", "t": "诸侯之孙。"}]}, {"meaning": "旧时对男性的长者或老人的尊称。", "cites": [{"t": "凡尊老,周晋秦陇谓之公。", "b": "《方言》六"}, {"t": "赵中大夫白公。", "b": "《汉书·沟洫志》"}, {"t": "游诸公。", "b": "《汉书·田叔传》"}, {"t": "公其怒,不敢献。公为我献之。", "b": "《史记·项羽本纪》"}, {"t": "及试,吏呼名至史公,公瞿然注视。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "张公", "t": ""}, {"w": "许孟公", "t": ""}, {"w": "公母", "t": "方言。指大爷大娘老两口"}, {"w": "公修公德,婆修婆德", "t": "修德属于个人,不得代替。"}]}, {"meaning": "父。又丈夫的父亲。", "cites": [{"t": "宋人嫁子,若公知其盗也,逐而去之。", "b": "《淮南子·汜论》"}, {"t": "便可白公姥,及时相遣归。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "公姥", "t": "指公婆;指岳父"}, {"w": "公姑", "t": "丈夫的父母,亦称“公婆”。"}]}, {"meaning": "劳绩,功绩。", "cites": [{"t": "当此之时,诸侯莫能以德,而争于公利,故以权相倾。", "b": "《盐铁论·轻重》"}, {"t": "寿张侯以公德加位特进。——汉《中常侍骑都尉樊——安碑》", "b": ""}], "words": [{"w": "无公", "t": "没有功劳"}, {"w": "肤公", "t": "微小的功绩?。"}]}, {"meaning": "公然;公开地。", "cites": [{"t": "残贼公行,莫之或止。", "b": "汉·贾谊《论积贮疏》"}, {"t": "公然抢茅入竹去,唇焦口燥呼不得。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "公讨", "t": "公开揭露声讨"}, {"w": "公言", "t": "公开谈论;公众的言论"}, {"w": "公取", "t": "谓公然夺取他人财物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('149wx','仓','1','cāng','人','4','','[{"pinyin": "cāng", "defs": [{"meaning": "(象形。甲骨文字形,上象盖儿,中间象一扇门,下面是进出的口儿,合起来表示仓库这个概念。本义:粮仓)。"}, {"meaning": "同本义。", "cites": [{"t": "仓,谷藏也,仓黄取而藏之,故谓之仓。", "b": "《说文》"}, {"t": "仓廪实而知礼节。", "b": "汉·贾谊《论积贮疏》"}, {"t": "藏帝藉之收于神仓。", "b": "《礼记·月令》。注:“藏祭祀之谷为神仓。”"}], "words": [{"w": "谷仓", "t": "粮仓"}, {"w": "仓廒", "t": "粮库"}, {"w": "仓敖", "t": "储藏米谷的地方。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('150wx','月','1','yuè','月','4','','[{"pinyin": "yuè", "defs": [{"meaning": "(象形。甲骨文字形。象半月形。“月”是汉字部首之一。本义:月亮)。"}, {"meaning": "同本义。", "cites": [{"t": "月,太阴之精也。象上下弦阙形。", "b": "《说文》"}, {"t": "月之从星,则以风雨。", "b": "《书·洪范》"}, {"t": "礼月与四渎于北门外。", "b": "《仪礼·觐礼》"}, {"t": "月虚而鱼脑减。", "b": "《淮南子·天文》"}, {"t": "如月之恒,如日之升。", "b": "《诗·小雅·天保》"}], "words": [{"w": "月满则亏,水满则盈", "t": "喻指作事应适可而止,做得过分,就会走向反面"}, {"w": "月上半阑残", "t": "指夜已深"}, {"w": "月老冰人", "t": "月下老人"}, {"w": "“月”字流觞", "t": "酒令的一种。令中必带“月”字"}, {"w": "月日", "t": "月亮和太阳"}, {"w": "月晕", "t": "月亮周围的光圈"}, {"w": "月影", "t": "映于水中或隐约如于云间的月亮影子"}, {"w": "月满", "t": "月圆"}, {"w": "月王", "t": "对月的尊称。"}]}, {"meaning": "历名。农历依月相变化的一个周期为一月;月份。", "cites": [{"t": "族庖月更刀。", "b": "《庄子·养生主》"}, {"t": "日削月割。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "月令", "t": "寿数"}, {"w": "月生", "t": "出生的月份日期"}, {"w": "月日", "t": "指几个月的日子"}, {"w": "月小", "t": "指旧历只有二十九天的月份"}, {"w": "月大", "t": "指旧历有三十天的月份"}, {"w": "月分", "t": "亦作“月份”,月限,指规定的时限。"}]}, {"meaning": "月光,月色。", "cites": [{"t": "晨兴理荒秽,带月荷锄归。", "b": "晋·陶潜《归园田居》"}], "words": [{"w": "月明千里", "t": "月光普照大地"}, {"w": "月波", "t": "指月光。月光似水,故称"}, {"w": "月径", "t": "月光下的小路"}, {"w": "月浪", "t": "月光"}, {"w": "月阴", "t": "月影。借指月光"}, {"w": "月皎", "t": "月色皎洁"}, {"w": "月明", "t": "月光明朗。"}]}, {"meaning": "指妇女的月经;月事。", "cites": [{"t": "月信不通,当归酒下。", "b": "《博济方》"}], "words": [{"w": "月闭", "t": "妇女月经不通。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('151wx','氏','1','shì zhī','氏','4','','[{"pinyin": "shì", "defs": [{"meaning": "(象形。甲骨文字形,象物体欲倾倒而将其支撑住的形象。是“支”的本字。本义:古代贵族标志宗族系统的称号)。"}, {"meaning": "同本义。", "cites": [{"t": "氏,姓氏。", "b": "《玉篇》。按,秦汉以前,“姓”和“氏”不同,“姓”为“氏”之本,“氏”自“姓”出。夏、商、周三代,氏是姓的支系,用以区别子孙之所由出生"}, {"t": "三代之前,姓氏分而为二。男子称氏,妇人称姓。氏所以别贵贱,贵者有氏。贱者有名无氏。", "b": "《通志·略·氏族》"}, {"t": "赐姓刘氏,拜为郎中。", "b": "《史记·刘敬叔孙通列传》"}]}, {"meaning": "也有以邑、官职、祖父的谥号或字为氏的。", "cites": [{"t": "姓、氏之称,自太史公始混而为一,本纪于秦始皇则曰“姓赵氏”,于汉高祖则曰“姓刘氏”。", "b": "顾炎武《日知录》"}, {"t": "丁氏穿井得一人。", "b": "《吕氏春秋·察传》"}, {"t": "日出东南隅,照我秦氏楼。", "b": "《乐府诗集·陌上桑》"}]}, {"meaning": "对学术、流派、专家、名人或宗教的称呼。", "cites": [{"t": "妙思六经,消遥百氏。", "b": "曹丕《与朝歌令吴质书》"}]}, {"meaning": "旧时放在已婚妇女的姓后,或如通常在父姓前还加上夫姓的称呼。", "cites": [{"t": "其下两冢,一为阿爷侍者朱氏,一为阿兄侍者陶氏。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "夫人李氏;王张氏", "t": ""}]}, {"meaning": "此,这。", "cites": [{"t": "今知氏大国之君。", "b": "《墨子·天志下》。俞樾云:“知”字衍文。氏、是古通用。“今氏”即“今是”也。"}, {"t": "唯氏三族之不虞。", "b": "《白虎通·宗族》"}, {"t": "氏为庄公。", "b": "《汉书·地理志》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhī", "defs": [{"meaning": "——见“月氏”(Yuèzhī):汉代西域国名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('152wx','勿','1','wù','勹','4','','[{"pinyin": "wù", "defs": [{"meaning": "(象形。据甲骨文,像一树旗。右边是柄,左边是飘带。本义:州里所建旗帜) 古代大夫、士所建旗帜,半赤半白,用来麾集人众。", "cites": [{"t": "勿,州里所建旗,…杂帛,幅半异。所以趣民。", "b": "《说文》。段玉裁注:“‘州里’当作‘士大夫’。”"}]}, {"meaning": "不。", "cites": [{"t": "欲勿予。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "贤者能勿丧。", "b": "《孟子·告子上》"}, {"t": "齐人勿附于秦。", "b": "宋·苏洵《六国论》"}, {"t": "表否定。如:勿造至于(不至于);勿适意(不舒服;身体欠佳);勿连牵(不连贯;不清楚);勿时路(不时髦;不流行);勿想(不吱声;不说话);勿述(不逆。犹言顺畅);勿庸(无庸,不必,无须);勿论(不追究;不谈);勿药(不服药);勿齿(不愿意提及);勿入调([方]∶不规矩;胡闹)", "b": ""}]}, {"meaning": "不要,别。", "cites": [{"t": "勿士行枚。", "b": "《诗·豳风·东山》"}, {"t": "虽欲勿用。", "b": "《论语·雍也》"}, {"t": "过则勿惮改。", "b": "《论语·学而》"}, {"t": "寡人敢勿轼乎?", "b": "《淮南子·脩务》"}, {"t": "必勿使反。", "b": "《战国策·赵策》"}, {"t": "愿勿遣。", "b": "汉·刘向《列女传》"}, {"t": "诸君勿复言。", "b": "《三国志·诸葛亮传》"}, {"t": "将军勿虑。", "b": "《资治通鉴》"}, {"t": "表示禁止或劝阻。如:请勿吸烟;勿用(勿动;不可有所作为);勿惮(不要怕);勿然(不要这样)", "b": ""}]}, {"meaning": "无,没有。与“有”相对 没得到;落空)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('153wx','欠','1','qiàn qian','欠','4','','[{"pinyin": "qiàn", "defs": [{"meaning": "(象形。甲骨文字形,象人张着口打呵欠。小篆字形下面是人(儿),上面象人呼出的气。本义:打呵欠)。"}, {"meaning": "同本义。", "cites": [{"t": "欠,张口气悟也。", "b": "《说文》"}, {"t": "肾为欠。", "b": "《素问·宣明五藏论》"}, {"t": "君子欠伸。", "b": "《仪礼·士相见礼》。注:“志倦则欠。体倦则伸。”"}, {"t": "惊觉欠伸。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "呵欠", "t": "哈欠。"}]}, {"meaning": "身体或身体的一部分稍微向上移动。", "cites": [{"t": "犹恐是梦,忙又将身子欠起来。", "b": "《红楼梦》"}], "words": [{"w": "欠体", "t": "欠身。"}]}, {"meaning": "亏欠;欠债。", "cites": [{"t": "须欠郑大官人典身钱。", "b": "《水浒传》"}], "words": [{"w": "拖欠", "t": "欠款不还"}, {"w": "欠折", "t": "短少;亏损"}, {"w": "欠负", "t": "谓亏欠租税等"}, {"w": "欠票", "t": "即欠据。"}]}, {"meaning": "缺少。", "cites": [{"t": "欠为人师。", "b": "唐·柳宗元《柳河东集》"}, {"t": "甚妙,但似欠四字耳。", "b": "陆游《老学庵笔记》"}, {"t": "万事俱备,只欠东风。", "b": "《三国演义》"}], "words": [{"w": "欠缺悬隔", "t": "粮食不足而距运粮地又很远"}, {"w": "缺欠", "t": "缺乏"}, {"w": "欠通", "t": "对事理不够通达。亦指文字不够通顺。"}]}, {"meaning": "不如。", "cites": [{"t": "行路少年知不知,襄阳全欠旧来时。", "b": "施肩吾《大堤新咏》"}]}, {"meaning": "想念。", "cites": [{"t": "爹爹,大娘欠你,送辣面与你吃。", "b": "《警世通言》"}], "words": [{"w": "欠挂", "t": "牵挂。"}]}, {"meaning": "痴呆。", "cites": [{"t": "君瑞真个欠,我道你,佯小心,妆大胆。", "b": "董解元《西厢记诸宫调》"}]}]}, {"pinyin": "qian", "defs": [{"meaning": "——如：“打哈欠”（dǎ hāqian）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('154wx','风','1','fēng fěng fèng','风','4','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。从虫,凡声。“风动虫生”故字从“虫”。本义:空气流动的自然现象;尤指空气与地球表面平行的自然运动)。"}, {"meaning": "同本义。", "cites": [{"t": "風,八风也。东方曰明庶风,东南曰清明风,南方曰景风,西南曰凉风,西方曰闾阖风,西北曰不周风,北方曰广莫风,东北曰融风。风动虫生,故虫八日而化。", "b": "《说文》"}, {"t": "立春条风。", "b": "《易·通卦验》"}, {"t": "东北条风。", "b": "《广雅·释天》"}, {"t": "距日冬至四十五日,条风至。", "b": "《淮南子·天文》"}, {"t": "条风居东北维,主出万物条之。言条治万物而出之。", "b": "《史记·律书》"}, {"t": "今日不鳳(風)?", "b": "《殷虚文字甲编》"}, {"t": "见事风生,无所回避。", "b": "《汉书·赵尹韩张两王传》"}, {"t": "大风起兮云飞扬。", "b": "刘邦《大风歌》"}, {"t": "山雨欲来风满楼。", "b": "许浑《咸阳城东楼》"}], "words": [{"w": "狂风", "t": "猛烈的风"}, {"w": "风信", "t": "风的大小及风向"}, {"w": "风团", "t": "旋风。比喻飞快"}, {"w": "风吹日炙", "t": "风吹日晒"}, {"w": "风雹", "t": "刮风下雹"}, {"w": "风潦", "t": "风灾和水灾"}, {"w": "风霰", "t": "风雪。"}]}, {"meaning": "风俗;风气。", "cites": [{"t": "今将移风易俗,其道诚难。", "b": "《资治通鉴》"}, {"t": "奸党散落,风俗大改。", "b": "《汉书·赵尹韩张两王传》"}, {"t": "故为之说,以俟观人风者得焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "移风易俗。", "b": "《荀子·乐论》"}], "words": [{"w": "风美", "t": "风俗淳美"}, {"w": "风纯", "t": "风俗纯朴"}, {"w": "风沦", "t": "风俗沦落败坏"}, {"w": "风习", "t": "风俗习惯"}, {"w": "风浮", "t": "风俗浮薄。"}]}, {"meaning": "风范,气度,韵致。", "cites": [{"t": "亦尝侧闻长者之遗风矣。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "风局", "t": "风范,器宇"}, {"w": "风表", "t": "风范仪表"}, {"w": "风则", "t": "风范"}, {"w": "风裁", "t": "风采,气度"}, {"w": "风期", "t": "气度,襟怀"}, {"w": "风节", "t": "气度情操。"}]}, {"meaning": "风声,消息。", "cites": [{"t": "但有知风来报的赏钱百两。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "风警", "t": "风声很紧"}, {"w": "风汛", "t": "风声;消息"}, {"w": "风音", "t": "风声"}, {"w": "风路", "t": "风声,线索"}, {"w": "闻风而动", "t": ""}]}, {"meaning": "“诗经”六义之一。指《诗经》中三种诗歌类型的一种,即《国风》中收集的民俗歌谣。", "cites": [{"t": "风有采蘩采苹。", "b": "《左传·隐公三年》"}, {"t": "乐操土风,不忘旧也。", "b": "《左传·成公九年》"}], "words": [{"w": "风赋", "t": "指“诗”六义中的风和赋"}, {"w": "风人屺岵", "t": "诗人的悲凉伤感。"}]}, {"meaning": "男女间的情爱。", "cites": [{"t": "他如今大了,渐知风月,便看上了秦钟人物风流。", "b": "《红楼梦》"}], "words": [{"w": "风月", "t": "指男女间的情爱"}, {"w": "风月常新", "t": "指情爱永久不断"}, {"w": "风月子弟", "t": "沉湎于风月场的子弟。"}]}, {"meaning": "刮风;起风。", "cites": [{"t": "风则袭裘,雨则御盖。", "b": "宋·苏轼《教战守》"}, {"t": "风雨晨昏,羁魂有伴,当不孤寂。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "走逸。", "cites": [{"t": "君处北海,寡人处南海,唯是风马牛不相及也。", "b": "《左传·僖公四年》"}, {"t": "库莫奚国有马百匹因风入境。", "b": "《北魏书》"}]}, {"meaning": "嬉戏。", "cites": [{"t": "众人忧得你苦,你却在这里风!快上山去!", "b": "《水浒全传》"}]}, {"meaning": "癫狂。", "cites": [{"t": "奈何以国家科第放此风汉及第耶?", "b": "《玉泉子·真录》"}, {"t": "你原来是个风和尚。", "b": "《西游记》"}], "words": [{"w": "风发", "t": "发疯"}, {"w": "风病", "t": "精神病"}, {"w": "风涎", "t": "患风疾的病根"}, {"w": "风欠", "t": "疯狂"}, {"w": "风风势势", "t": "举动不正常,易冲动。"}]}, {"meaning": "(fán)。大凡,大概。", "cites": [{"t": "愿先生之言其风也。", "b": "《庄子·天地》"}]}, {"meaning": "姓。"}]}, {"pinyin": "fěng", "defs": [{"meaning": "讽刺;委婉劝告", "cites": [{"t": "而王与任王后以此使人风止李太后,李太后内有淫行,亦已。", "b": "《史记·梁孝王世家》"}, {"t": "故布衣皆得风议,何况公卿之史乎?", "b": "《盐铁论》"}, {"t": "蚡乃微言太后风上。", "b": "《汉书·田蚡传》"}], "words": [{"w": "风规", "t": "讽刺规劝"}, {"w": "风谏", "t": "婉言劝谏。即讽谏"}, {"w": "风谕", "t": "讽告,婉言开导。"}]}]}, {"pinyin": "fèng", "defs": [{"meaning": "比喻感化。", "cites": [{"t": "天子于是以式终长者,故尊显以风百姓。", "b": "《史记·平准书》"}], "words": [{"w": "风民", "t": "感化、教化人民。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('155wx','丹','1','dān','丿','4','','[{"pinyin": "dān", "defs": [{"meaning": "(象形。甲骨文字形,外面框框象矿井形,里边的一横是加上的符号,表示那里有丹砂。本义:辰砂,朱砂)。"}, {"meaning": "同本义。", "cites": [{"t": "丹,巴越之赤石也。象采丹井。", "b": "《说文》"}, {"t": "砺砥砮丹。", "b": "《书·禹贡》"}, {"t": "有始州之国,有丹山。", "b": "《山海经·大荒北经》"}, {"t": "加之以丹矸。", "b": "《荀子·正论》"}, {"t": "乃丹书帛曰“陈胜王”,置入所罾鱼腹中。", "b": "《史记·陈涉世家》"}], "words": [{"w": "丹矸", "t": "丹砂"}, {"w": "丹砂", "t": "一种红色矿物,也叫“朱砂”"}, {"w": "丹砾", "t": "矿物之丹砂,可为药用"}, {"w": "丹铅", "t": "丹砂和铅粉,是古人校勘文字的用具。"}]}, {"meaning": "古代用作染色的颜料。", "cites": [{"t": "凡画者丹质。", "b": "《仪礼·乡射礼记》"}]}, {"meaning": "依成方制成的颗粒状或粉末状的中成药。", "cites": [{"t": "山海丹", "b": ""}, {"t": "灵丹妙药", "b": ""}]}, {"meaning": "红色,赤色。", "cites": [{"t": "染羽以朱湛丹秫。", "b": "《周礼·考工记》"}, {"t": "颜如渥丹。", "b": "《诗·秦风·终南》"}, {"t": "日上正赤如丹。", "b": "姚鼐《登泰山记》"}], "words": [{"w": "丹秫", "t": "赤粟"}, {"w": "丹陛云墀", "t": "雕刻着云彩的红色台阶"}, {"w": "丹阙", "t": "宫殿前两边用红色染饰的楼台"}, {"w": "丹毫", "t": "红颜色的笔"}, {"w": "丹陛", "t": "红色的台阶。"}]}, {"meaning": "涂染成红色。", "cites": [{"t": "杀卒四万,血丹野。", "b": "《新唐书》"}], "words": [{"w": "丹野", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('156wx','匀','1','yún','勹','4','','[{"pinyin": "yún", "defs": [{"meaning": "(会意。从勹(bāo)二。勹,象人曲形有所包裹,“二”表示所裹不多。本义:少)。"}, {"meaning": "假借为“均”。分,分出。", "cites": [{"t": "匀,调匀也。", "b": "《一切经音义》引《说文》"}, {"t": "不假东风次第吹,笔匀春色一枝枝。", "b": "唐·杜荀鹤《题花木障》"}], "words": [{"w": "匀滚", "t": "拉平;平均"}, {"w": "饭匀着吃;叫东村匀出一匹马来;匀摊", "t": "平均分摊。"}]}, {"meaning": "涂抹均匀。", "cites": [{"t": "向镜轻匀衬脸霞。", "b": "韩儛《咏手诗》"}], "words": [{"w": "匀注", "t": "均匀地点染;化妆"}, {"w": "匀面", "t": "化妆时用手搓脸使脂粉匀净"}, {"w": "匀红点翠", "t": "涂脂画眉。"}]}, {"meaning": "打扮。", "cites": [{"t": "小妇欲出门,隈门匀红妆。", "b": "卢仝《小妇吟》"}]}, {"meaning": "均匀。", "cites": [{"t": "态浓意远淑且真,肌理细腻骨肉匀。", "b": "杜甫《丽人行》"}], "words": [{"w": "匀衬", "t": "匀称"}, {"w": "匀清", "t": "整齐,清楚"}, {"w": "匀圆", "t": "均匀圆润"}, {"w": "匀匀", "t": "均匀的样子;广平的样子"}, {"w": "匀饬", "t": "匀称严整。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('157wx','乌','1','wū wù','丿','4','','[{"pinyin": "wū", "defs": [{"meaning": "(象形。本义:鸟名,乌鸦)。"}, {"meaning": "同本义。", "cites": [{"t": "燕雀乌鹊。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "乌鸟", "t": "乌鸦之属"}, {"w": "乌鸢", "t": "乌鸦和老鹰"}, {"w": "乌鹊", "t": "乌鸦和喜鹊"}, {"w": "乌师", "t": "在妓院教唱或伴奏的乐师"}, {"w": "乌鸦嘴", "t": "比喻说话讨厌的人。"}]}, {"meaning": "刚孵化出的幼蚕。", "cites": [{"t": "[蚕] 子初出者名蚕花,亦名蚁,又名乌。", "b": "《广蚕桑说辑补》"}]}, {"meaning": "浅黑色。", "cites": [{"t": "身披乌衣,手执耒耜,以率将士。", "b": "《三国志·邓艾传》"}], "words": [{"w": "乌衣", "t": "黑衣"}, {"w": "乌巾", "t": "黑头巾"}, {"w": "乌丸", "t": "墨的别名"}, {"w": "乌油", "t": "黑而光润"}, {"w": "乌麻", "t": "黑芝麻"}, {"w": "乌黑黑", "t": "黑压压"}, {"w": "乌丝", "t": "黑丝"}, {"w": "乌靴", "t": "古官穿的黑色靴子"}, {"w": "乌榜", "t": "用黑油涂饰的船"}, {"w": "乌云阵头", "t": "大雨将到,乌云密布的情形"}, {"w": "乌云屯集", "t": "像乌云一样密集。"}]}, {"meaning": "也作“於”。表示感叹。", "cites": [{"t": "乌见异则噪,…。", "b": "《埤雅》"}]}]}, {"pinyin": "wù", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('158wx','勾','1','gōu gòu','勹','4','','[{"pinyin": "gōu", "defs": [{"meaning": "删除或截取。", "cites": [{"t": "谢安已令吏部郎袁彦伯撰策文,文成,安辄勾点,令更治改。", "b": "《魏书·司马叡传》"}, {"t": "把报上的新词勾出来", "b": ""}], "words": [{"w": "勾除", "t": "勾销,除掉"}, {"w": "勾抹", "t": "勾除;抹掉"}, {"w": "勾却", "t": "勾销,取消。"}]}, {"meaning": "勾结。", "cites": [{"t": "都是这些和尚勾合光棍,在外诈作客商模样。", "b": "清·艾衲居《豆棚闲话》"}], "words": [{"w": "勾哄", "t": "勾结哄骗"}, {"w": "勾合", "t": "勾结;串通,结合。"}]}, {"meaning": "勾引,引诱。", "cites": [{"t": "他在王婆茶房里,和武大娘子勾搭上了。", "b": "《水浒传》"}], "words": [{"w": "勾将", "t": "引杀;纠集"}, {"w": "勾惹", "t": "引逗,挑逗"}, {"w": "勾挑", "t": "勾引挑逗"}, {"w": "勾戏", "t": "勾引调戏"}, {"w": "勾肆", "t": "勾拦瓦肆的简称。宋元时说书演戏的场所,后来也指妓院"}, {"w": "勾拽", "t": "勾引。"}]}, {"meaning": "捉拿,逮捕。", "cites": [{"t": "其实犯死罪免死充军者,以著伍后所生子孙替役,不许勾原籍子孙。", "b": "《明史·刑法志》"}], "words": [{"w": "勾提", "t": "捉拿,拘捕"}, {"w": "勾摄公事", "t": "拘捕罪犯"}, {"w": "勾追", "t": "追捕,捉拿"}, {"w": "勾取", "t": "捉拿"}, {"w": "勾致", "t": "拘捕。"}]}]}, {"pinyin": "gòu", "defs": [{"meaning": "用同“够”。足够;能够。", "cites": [{"t": "这米则有一石六斗,内中又有泥土糠皮,舂将来则勾一石多米。", "b": "《陈州粜米》"}], "words": [{"w": "你勾得着那么高吗?", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('159wx','凤','1','fèng','几','4','','[{"pinyin": "fèng", "defs": [{"meaning": "(形声。从鸟,凡声。本义:凤凰。中国古代传说中的百鸟之王。常用来象征祥瑞。雄的叫凤,雌的叫凰)。"}, {"meaning": "同本义。", "cites": [{"t": "凤,神鸟也。朋,古文凤。", "b": "《说文》"}, {"t": "凤皇来仪。", "b": "《书·益稷》"}, {"t": "凤皇于飞。", "b": "《诗·大雅·卷阿》。传:“凤皇,灵鸟仁瑞也。雄曰凤,雌曰皇。”"}, {"t": "故鸟有凤而鱼有鲲。", "b": "宋玉《对楚王问》"}], "words": [{"w": "凤求凰;凤子", "t": "绣有凤凰的轿子"}, {"w": "凤舸", "t": "雕有凤凰的大游船"}, {"w": "凤毛", "t": "凤凰的羽毛。多用以赞美人的文采俊秀,有先人遗风。"}]}, {"meaning": "古时比喻有圣德的人。", "cites": [{"t": "潘陆张左,擅侈丽之才,饰羽仪于凤穴。", "b": "《北史·文苑传序》"}], "words": [{"w": "凤穴", "t": "比喻文才荟萃的地方。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('160wx','六','1','liù lù','八','4','','[{"pinyin": "liù", "defs": [{"meaning": "五加一的和。", "cites": [{"t": "人道以六制。", "b": "《管子·五行》"}, {"t": "六日不詹。", "b": "《诗·小雅·采绿》"}, {"t": "六主律。", "b": "《易·本命》"}, {"t": "夫六中色也。", "b": "《国语·周语》"}, {"t": "六王毕,四海一。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "六礼", "t": "中国古代婚姻需备的六种礼节:纳采、问名、纳吉、纳征、请期、亲迎"}, {"w": "六味", "t": "指苦、酸、甘、辛、咸、淡等六种滋味"}, {"w": "六料", "t": "原指稻、黍、稷、粱、麦、菽六谷,后为各种谷物的泛称"}, {"w": "六儿", "t": "僮仆的泛称"}, {"w": "六丁六甲", "t": "道教称供天帝役使的阴神为六丁,阳神为六甲"}, {"w": "六街三市", "t": "泛称众多街市"}, {"w": "六曹", "t": "指功曹、仓曹、户曹、兵曹、法曹、士曹。"}]}, {"meaning": "《易》卦之阴爻称为六。", "cites": [{"t": "易之数,阴变于六,正于八,从入,从八。", "b": "《说文》"}], "words": [{"w": "初六", "t": "由下而上的第一个阴爻"}, {"w": "上六", "t": "最上一个即第六个阴爻"}, {"w": "六爻", "t": "爻,是构成《易》卦的基本符号。每三爻会成一卦。两卦即是六爻"}, {"w": "六出", "t": "雪花。因呈六角形。"}]}, {"meaning": "六次。", "cites": [{"t": "六黜清能,六进否劣。", "b": "《晋书·杜预传》"}]}, {"meaning": "工尺谱记音符号之一,表示音阶上的一级。", "cites": [{"t": "其黄钟清用“六”字。", "b": "《宋史》"}]}, {"meaning": "古国名 。周封皋陶的后代在六。在今安徽省六安县北。", "cites": [{"t": "楚人灭六。", "b": "《左传·文五年》"}]}, {"meaning": "姓。"}]}, {"pinyin": "lù", "defs": [{"meaning": "古国名 。故城在今安徽省六安县北。", "cites": [{"t": "秋,楚人灭六。", "b": "《春秋》"}]}, {"meaning": "古县名。在今安徽省六安县。", "cites": [{"t": "当阳君英布为九江王,都六。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('161wx','文','1','wén','文','4','','[{"pinyin": "wén", "defs": [{"meaning": "(象形。甲骨文此字象纹理纵横交错形。“文”是汉字的一个部首。本义:花纹;纹理)。"}, {"meaning": "同本义。", "cites": [{"t": "文,错画也。象交文。今字作纹。", "b": "《说文》"}, {"t": "五章以奉五色。", "b": "《左传·昭公二十五年》。注:“青与赤谓之文,赤与白谓之章,白与黑谓之黼,黑与青谓之黼。”"}, {"t": "美于黼黼文章。", "b": "《荀子·非相》"}, {"t": "茵席雕文。", "b": "《韩非子·十过》"}, {"t": "织文鸟章,白旆央央。", "b": "《诗·小雅·六月》"}, {"t": "斑文小鱼。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "文驾", "t": "彩车"}, {"w": "文斑", "t": "杂色的斑纹"}, {"w": "文旆", "t": "有文彩的旗帜"}, {"w": "文绣", "t": "绣有彩色花纹的丝织品;刺花图案"}, {"w": "文织", "t": "有彩色花纹的丝织品"}, {"w": "文鳞", "t": "鱼鳞形花纹。"}]}, {"meaning": "字,文字(“文”,在先秦时期就有文字的意思,“字”,到了秦朝才有此意。分别讲,“文”指独体字;“字”指合体字。笼统地说,都泛指文字)。", "cites": [{"t": "饰以篆文。", "b": "《后汉书·张衡传》"}, {"t": "分文析字。", "b": "《汉书·刘歆传》"}, {"t": "夫文,止戈为武。", "b": "《左传·宣公十二年》"}, {"t": "距洞数百步,有碑仆道,其文漫灭。", "b": "王安石《游褒禅山记》"}, {"t": "文曰“天启壬戌秋日”。", "b": "明·魏学洢《核舟记》"}, {"t": "文曰“初平山尺”。", "b": ""}], "words": [{"w": "甲骨文;金文;汉文;英文;文迹", "t": "文字所记载的事迹"}, {"w": "文书爻", "t": "有关文字、文凭之类的卦象"}, {"w": "文异", "t": "文字相异"}, {"w": "文轨", "t": "文字和车轨"}, {"w": "文狱", "t": "文字狱"}, {"w": "文钱", "t": "钱。因钱有文字,故称"}, {"w": "文状", "t": "字据,军令状"}, {"w": "文引", "t": "通行证;路凭"}, {"w": "文定", "t": "定婚。"}]}, {"meaning": "文章(遣造的词句叫做“文”,结构段落叫做 “章”)。", "cites": [{"t": "故说诗者不以文害辞。", "b": "《孟子·万章上》"}, {"t": "好古文。", "b": "唐·韩愈《师说》"}, {"t": "属予作文以记之。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "能述以文。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "摘其诗文。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "文价", "t": "文章的声誉"}, {"w": "文魔", "t": "书呆子"}, {"w": "文会", "t": "旧时读书人为了准备应试,在一起写文章、互相观摩的集会"}, {"w": "文移", "t": "旧时官府文书的代称"}, {"w": "文雄", "t": "擅长写文章的大作家"}, {"w": "文意", "t": "文章的旨趣"}, {"w": "文义", "t": "文章的义理"}, {"w": "文情", "t": "文章的词句和情思"}, {"w": "本文", "t": "所指的这篇文章"}, {"w": "作文", "t": "写文章;学习练习所写的文章"}, {"w": "文魁", "t": "文章魁首"}, {"w": "文价", "t": "文章的声价"}, {"w": "文什", "t": "文章与诗篇。"}]}, {"meaning": "美德;文德。", "cites": [{"t": "圣云继之神,神乃用文治。", "b": "杜牧《感怀诗一首》"}], "words": [{"w": "文丈", "t": "对才高德韶的老者的敬称"}, {"w": "文母", "t": "文德之母"}, {"w": "文武", "t": "文德与武功"}, {"w": "文命", "t": "文德教命"}, {"w": "文惠", "t": "文德恩惠"}, {"w": "文德", "t": "写文章的道德"}, {"w": "文薄", "t": "谓文德浅薄"}, {"w": "文昭", "t": "文德昭著。"}]}, {"meaning": "文才;才华。亦谓有文才,有才华。", "cites": [{"t": "而文采不表于后世也。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "文业", "t": "才学"}, {"w": "文英", "t": "文才出众的人"}, {"w": "文采风流", "t": "横溢的才华与潇洒的风度"}, {"w": "文郎", "t": "有才华的青少年"}, {"w": "文彦", "t": "有文才德行的人"}, {"w": "文通残锦", "t": "比喻剩下不多的才华。"}]}, {"meaning": "文献,经典;韵文。", "cites": [{"t": "儒以文乱法。", "b": "《韩非子·五蠹》"}, {"t": "言必遵修旧文而不穿凿。", "b": "《说文解字·叙》"}]}, {"meaning": "自然界的某些现象。", "cites": [{"t": "经纬天地曰文。", "b": "《左传·昭公二十八年》"}], "words": [{"w": "天文;地文;水文;文象", "t": "日月星辰变化的迹象"}, {"w": "文曜", "t": "指日月星辰;文星"}, {"w": "文昌", "t": "星座名。"}]}, {"meaning": "文治;文事;文职。与“武”相对。", "cites": [{"t": "文能取胜。", "b": "《史记·平原君虞卿列传》"}, {"t": "文不能取胜。", "b": ""}, {"t": "文武并用。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "文臣,文吏", "t": "文职官吏"}, {"w": "文席", "t": "教书先生的几席"}, {"w": "文品", "t": "文官的品阶"}, {"w": "文帅", "t": "文职官员出任或兼领统帅"}, {"w": "文烈", "t": "文治显赫"}, {"w": "文员", "t": "文职吏员"}, {"w": "文阶", "t": "文职官阶"}, {"w": "文道", "t": "文治之道"}, {"w": "文业", "t": "文事"}, {"w": "文僚", "t": "文职官吏。"}]}, {"meaning": "法令条文。", "cites": [{"t": "而刀笔吏专深文巧诋,陷人于罪。", "b": "《史记·汲黯列传》"}], "words": [{"w": "文劾", "t": "根据律令弹劾"}, {"w": "文法吏", "t": "通晓法令、执法严峻的官吏"}, {"w": "文丈", "t": "规矩;制度"}, {"w": "文移", "t": "官府文书"}, {"w": "文牓", "t": "布告;文告"}, {"w": "文宪", "t": "礼法;法制。"}]}, {"meaning": "文教;礼节仪式。", "cites": [{"t": "则修文德。", "b": "《论语·季氏》"}]}, {"meaning": "又如:文丈(崇尚礼文仪节);文俗(拘守礼法而安于习俗);文致(指礼乐);文貌(礼文仪节);文绪(文教礼乐之事);文仪(礼节仪式)。"}, {"meaning": "谥号,谥法:勤学好问叫文。", "cites": [{"t": "何以谓之文。", "b": "《论语》"}, {"t": "是以谓之文。", "b": ""}]}, {"meaning": "在肌肤上刺画花纹或图案。", "cites": [{"t": "被发文身。", "b": "《礼记·王制》。注:“谓其肌,以丹青涅之。”"}, {"t": "文绣有恒。", "b": "《礼记·月令》"}], "words": [{"w": "文笔匠", "t": "在人身上刺花的艺人"}, {"w": "文身断发", "t": "古代荆楚、南越一带的习俗。身刺花纹,截短头发,以为可避水中蛟龙的伤害。后常以指落后地区的民俗"}, {"w": "文木", "t": "刻镂以文采之木。"}]}, {"meaning": "修饰;文饰。", "cites": [{"t": "身将隐,焉用文之?", "b": "《左传·僖公二十三年》"}, {"t": "饰邪说,文奸言,以枭乱天下。", "b": "《荀子·非十二子》"}], "words": [{"w": "文过饰非;文致", "t": "粉饰;掩饰"}, {"w": "文冢", "t": "埋葬文稿之处。"}]}, {"meaning": "装饰。", "cites": [{"t": "舍其文轩。", "b": "《墨子·公输》"}, {"t": "此犹文奸。", "b": ""}, {"t": "文车二驷。", "b": "明·归有光《项脊轩志》"}, {"t": "文马四百匹。", "b": "《史记·宋世家》"}, {"t": "若将比予文木邪。", "b": "《庄子·人间世》"}], "words": [{"w": "文巧", "t": "文饰巧辩"}, {"w": "文竿", "t": "以翠羽为饰之竿"}, {"w": "文舫", "t": "装饰华丽的游艇"}, {"w": "文饰", "t": "彩饰"}, {"w": "文榭", "t": "饰以彩画的台榭"}, {"w": "文舟,文艘", "t": "装饰华丽的船"}, {"w": "文剑", "t": "装饰华丽的剑"}, {"w": "文舆", "t": "饰以彩绘的车。"}]}, {"meaning": "有文采,华丽。与“质”或“野”相对。", "cites": [{"t": "其旨远,其辞文。", "b": "《易·系辞下》"}, {"t": "晋公子广而俭,文而有礼。", "b": "《左传·僖公二十三年》"}], "words": [{"w": "文巧", "t": "华丽奇巧"}, {"w": "文朴", "t": "文华与质朴"}, {"w": "文服", "t": "华美的衣服"}, {"w": "文砌", "t": "华美的石阶"}, {"w": "文背", "t": "不文雅,粗俗"}, {"w": "文轩", "t": "华美的车子"}, {"w": "文质", "t": "文华与质朴。"}]}, {"meaning": "紊乱的。", "cites": [{"t": "惇宗将礼,称秩元祀,咸秩无文。", "b": "《书·洛诰》"}, {"t": "天子祭天下名山大川,怀柔百神,咸秩无文。", "b": "《汉书·郊祀志上》"}, {"t": "王者报功,以次秩之,无有文也。", "b": "庆劭《风俗通义·山泽》"}]}, {"meaning": "用于计算纺织物。", "cites": [{"t": "五扶为一首,五首成一文。", "b": "《后汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('162wx','亢','1','kàng','亠','4','','[{"pinyin": "kàng", "defs": [{"meaning": "(象形。小篆字形,从大(人)省,象人的颈脉形 ①(gāng)本义:人颈的前部,喉咙 ②高)。"}, {"meaning": "高。", "cites": [{"t": "故解之以牛之白颡者与豚之亢鼻者。", "b": "《庄子·人间世》"}], "words": [{"w": "亢爽", "t": "天高气爽;性格直爽"}, {"w": "亢山", "t": "高山"}, {"w": "亢言", "t": "高谈阔论"}, {"w": "亢昂", "t": "高昂;激扬。"}]}, {"meaning": "刚强。", "cites": [{"t": "恕在朝八年,其议论亢直,皆此类也。", "b": "《三国志·杜恕传》"}], "words": [{"w": "亢烈", "t": "刚毅"}, {"w": "亢亮", "t": "刚直诚信"}, {"w": "亢悍", "t": "刚烈强悍"}, {"w": "亢藏", "t": "刚直孤僻。"}]}, {"meaning": "自高,无所屈。", "cites": [{"t": "信明蹇亢,以门望自负。", "b": "《新唐书·文艺传上》"}], "words": [{"w": "亢世", "t": "傲世"}, {"w": "亢意", "t": "言恣意妄为"}, {"w": "亢龙", "t": "本指骄横无德之君。借指热衷功名,铡愎躁进之人。"}]}, {"meaning": "星名,亢宿。二十八宿之一,青龙七宿的第二宿。", "cites": [{"t": "亢宿四星。", "b": "《宋史·天文志三》"}]}, {"meaning": "极,达到最高的境界。", "cites": [{"t": "从今以后,着这楚州亢旱三年。", "b": "元·关汉卿《元曲选·窦娥冤》"}], "words": [{"w": "亢宠", "t": "居于极尊贵之位"}, {"w": "亢阳", "t": "阳气极盛;阳光过多,久不下雨,故天旱称亢阳"}, {"w": "亢龙有悔", "t": "处于极尊贵之位,当戒慎其败悔"}, {"w": "亢炎", "t": "非常炎热。"}]}, {"meaning": "抵御", "cites": [{"t": "我则为政,而亢大国之讨。", "b": "《左传·宣公十三年》"}, {"t": "诸列侯莫敢与亢礼。", "b": "《史记·魏其武安侯列传》"}], "words": [{"w": "亢衡", "t": "对立相敌。也作抗衡"}, {"w": "亢礼", "t": "彼此以平等的礼仪相待。也作“抗礼”"}, {"w": "亢答", "t": "应对。指礼仪酬答。"}]}, {"meaning": "蔽,庇护。", "cites": [{"t": "吉不能亢身,焉能抗宗?", "b": "《左传·昭公元年》"}], "words": [{"w": "亢宗", "t": "庇护宗族。后引申为光大门第。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('163wx','方','1','fāng','方','4','','[{"pinyin": "fāng", "defs": [{"meaning": "(象形。下从舟省,而上有竝头之象。故知并船为本义。本义:并行的两船;泛指并列;并行)。"}, {"meaning": "同本义。", "cites": [{"t": "方,併船也。象两舟总头形。", "b": "《说文》"}, {"t": "大夫方舟。", "b": "《尔雅》。李注:“竝两船曰方舟。”"}, {"t": "方舟而济于河。", "b": "《庄子·山木》"}, {"t": "不足方。", "b": "《仪礼·乡射礼》。注:“犹併也。”"}, {"t": "方舟设泭。", "b": "《国语·齐语》"}, {"t": "江之永矣,不可方思。", "b": "《诗·周南·汉广》"}, {"t": "操军方连战舰,首尾相接。", "b": "《资治通鉴》"}, {"t": "蜀汉之粟,方船而下。", "b": "《史记·郦食其列传》"}], "words": [{"w": "方轨", "t": "两车并排行驶"}, {"w": "方轩", "t": "并排的窗户。"}]}, {"meaning": "等同;相当。", "cites": [{"t": "梓人为侯,广与崇方。", "b": "《周礼·考工记》。郑玄注:“方,犹等也。”"}, {"t": "今者,齐、韩相方,而国围攻焉,岂有敢曰我其以三万救是者乎哉?", "b": "《战国策》"}]}, {"meaning": "比拟。", "cites": [{"t": "方丧三年。", "b": "《礼记·檀弓》。疏:“谓比方也。”"}, {"t": "赞票骑亦方此意。", "b": "《汉书·卫青霍去病传》。注:“比类也。”"}, {"t": "则三古以还年代方之,犹瀼渴之水,比诸大江。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "方天", "t": "可与上天相比"}, {"w": "方比", "t": "比较。"}]}, {"meaning": "辨别。", "cites": [{"t": "民神杂糅,不可方物。", "b": "《国语·楚语下》"}]}, {"meaning": "占有。", "cites": [{"t": "维鹊有巢,维鸠方之。", "b": "《诗·召南·鹊巢》"}]}, {"meaning": "依据;依托。", "cites": [{"t": "方天之休。", "b": "《左传·哀公十六年》"}, {"t": "维鹊有巢,维鸠方之。", "b": "《诗·召南·鹊巢》"}]}, {"meaning": "模拟。", "cites": [{"t": "方其人之习君子之说,则尊以遍矣,周於世矣。", "b": "《荀子·劝学》"}, {"t": "今世巧而民淫,方效汤武之时,而行神农之事。", "b": "《商君书·算地》"}]}, {"meaning": "指责别人的过失。", "cites": [{"t": "子贡方人。", "b": "《论语·宪问》"}, {"t": "或以方谢仁祖,不乃重者。", "b": "《世说新语》"}]}, {"meaning": "竹木编成的筏。", "cites": [{"t": "就其深矣,方之舟之。", "b": "《诗·邶风·谷风》。高亨注:“方,以筏渡;舟,以船渡。”"}]}, {"meaning": "方形。", "cites": [{"t": "形若土狗,梅花翅,方首,长胫。", "b": "《聊斋志异·促织》"}, {"t": "一个个方面大耳。", "b": "《儒林外史》"}], "words": [{"w": "方巾", "t": "明朝书生戴的帽子"}, {"w": "方裾", "t": "直衣襟"}, {"w": "方员", "t": "即方圆。指物之形体"}, {"w": "方舄", "t": "方口鞋。舄:夹底鞋。"}]}, {"meaning": "地区;地方。", "cites": [{"t": "有朋自远方来。", "b": "《论语·学而》"}, {"t": "远方之能疑者,并举而争起矣。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "方俗", "t": "地方风俗"}, {"w": "方帅", "t": "地方军事长官"}, {"w": "方贡", "t": "四方的土贡"}, {"w": "方处", "t": "地方。"}]}, {"meaning": "方面。"}, {"meaning": "指四面。", "cites": [{"t": "若事不辑,方面何所可据?", "b": "《三国演义》"}]}, {"meaning": "指四面,周围,四旁。", "cites": [{"t": "方宅十余亩,草屋八九间。", "b": "晋·陶渊明《归园田居》"}, {"t": "寻其方面,乃知震之所在。", "b": "《后汉书·张衡传》"}, {"t": "乃令史官记地动所从方起。", "b": ""}]}, {"meaning": "规律;道理。", "cites": [{"t": "吾长见笑于大方之家。(方:指学问。)", "b": "《庄子·秋水》"}, {"t": "今吾无所开吾喙,敢问其方?", "b": ""}, {"t": "是所以语大义之方,论万物之理也。", "b": ""}]}, {"meaning": "指儒家伦理道德和学问。", "cites": [{"t": "使臣下百吏莫不宿道乡方而务。", "b": "《荀子·王霸》"}, {"t": "学道立方,离法之民也,而世尊之曰文学之士。", "b": "《韩非子·六反》"}]}, {"meaning": "合成药物的配方。", "cites": [{"t": "请了多少名医修方配药,皆不见效。", "b": "《红楼梦》"}], "words": [{"w": "方诊", "t": "处方和诊察病情"}, {"w": "方脉", "t": "医方和脉象"}, {"w": "医方", "t": ""}]}, {"meaning": "品类;类别。", "cites": [{"t": "室家遂宗,食多方些。", "b": "《楚辞》"}, {"t": "故君子之朋友有乡,其恶有方。", "b": "《礼记》"}, {"t": "以死生为一化,以万物为一方,同精于太清之本。", "b": "《淮南子》"}]}, {"meaning": "以最弱可听声为零开始的响度单位,与声强的分贝标度相当,某一声音的方数等于听起来同样响时1000赫纯音的分贝数。"}, {"meaning": "方法。", "cites": [{"t": "少有连必多方钩致。", "b": "清·方苞《狱中杂记》"}, {"t": "教之以进退坐作之方。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "又如:千方百计;教导有方;方儿(方法;药方)。"}, {"meaning": "方圆。指土地面积。", "cites": [{"t": "荆之地方五千里,宋之地方五百里。", "b": "《墨子·公输》"}]}, {"meaning": "又。", "cites": [{"t": "今齐地方千里,有二十城。", "b": ""}]}, {"meaning": ""}, {"meaning": "植物种子的外皮。", "cites": [{"t": "既方既阜,既坚既好。", "b": "《诗·小雅·大田》"}]}, {"meaning": "住室。", "cites": [{"t": "周垣之高八尺,五十步一方。", "b": "《墨子·备城门》"}]}, {"meaning": "方正(人行为、品性正直无邪);正直。", "cites": [{"t": "盘石方且厚,可以卒千年。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "方刚", "t": "方正刚直"}, {"w": "方切", "t": "正直而恳切"}, {"w": "方心", "t": "方正之心"}, {"w": "方质", "t": "方正质朴。"}]}, {"meaning": "遍,广。", "cites": [{"t": "方施象刑惟明。", "b": "《书·益稷》"}, {"t": "晋国之方,偏侯也。", "b": "《国语·晋语》。注:方,大也。"}], "words": [{"w": "方行", "t": "广泛施行。"}]}, {"meaning": "方才。"}, {"meaning": "表示时间、相当于“始”“才”。", "cites": [{"t": "有五月方生者谓之晚筀。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "伐山取材,方有人见之。", "b": ""}], "words": [{"w": "如梦方醒", "t": ""}, {"w": "方当", "t": "正当,正值。"}]}, {"meaning": "表示时间,相当于“正在”。", "cites": [{"t": "守门卒方熟睡。", "b": "《资治通鉴·唐纪》"}, {"t": "余方心动欲还。", "b": "宋·苏轼《石钟山记》"}, {"t": "时予方以讨贼督师桂林。", "b": "孙文《序》"}], "words": [{"w": "方殷", "t": "正当剧盛之时。"}]}, {"meaning": "表示时间,相当于“将”。", "cites": [{"t": "今治水军八十万众,方与将军会猎于吴。", "b": "《资治通鉴·汉献帝建安十三年》"}, {"t": "余方高驰而不顾。", "b": "《楚辞·屈原·涉江》"}]}, {"meaning": "表示情态方式,相当于“一并”。", "cites": [{"t": "甲兵方起于天下。", "b": "《墨子·备城门》"}]}, {"meaning": "表示范围或程度,相当于“只”、“仅”。", "cites": [{"t": "赏有功,罚有罪,而不失其人,方在于人者也。", "b": "《韩非子》"}]}, {"meaning": "表示时间,相当于“在”、“当”。", "cites": [{"t": "方其盛时必毁。", "b": "《素问》"}, {"t": "方是时,博鸡者以义闻于东南。", "b": "明·高启《书博鸡者事》"}, {"t": "方其系燕父子以组。", "b": "宋·欧阳修《新五代史·伶官传·序》"}]}, {"meaning": "又。", "cites": [{"t": "故方其盛也,举天下之豪杰莫能与之争。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('164wx','火','1','huǒ','火','4','','[{"pinyin": "huǒ", "defs": [{"meaning": "(象形。甲骨文字形象火焰。汉字部首之一。本义:物体燃烧所发的光、焰和热)。"}, {"meaning": "同本义。", "cites": [{"t": "火,南方之行也。炎而上,象形。", "b": "《说文》"}, {"t": "火之为言委随也,故字人散二者为火也。", "b": "《春秋·元命苞》"}, {"t": "离为火。", "b": "《易·说卦》"}, {"t": "火水妃也。春秋感情符,火者阳之精也。", "b": "《左传·昭公九年》"}, {"t": "火,日气也。", "b": "《论衡·诘术》"}, {"t": "人火曰火,天火曰灾。", "b": "《左传·宣公十六年》"}, {"t": "国曰灾,邑曰火。", "b": "《谷梁传·昭公九年》"}, {"t": "大者曰灾,小者曰火。", "b": "《公羊传·襄公九年》"}, {"t": "火烧令坚。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "火令药熔。", "b": ""}], "words": [{"w": "火链", "t": "旧时打火用的火力"}, {"w": "火厝", "t": "火葬"}, {"w": "火筒", "t": "烟筒"}, {"w": "火火烛烛", "t": "火势很大"}, {"w": "火厄", "t": "火灾"}, {"w": "火备", "t": "防火设施。"}]}, {"meaning": "火灾;发生火灾。", "cites": [{"t": "凡四遭火。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "火兵", "t": "负责救火的兵"}, {"w": "火事", "t": "失火事故"}, {"w": "火殃", "t": "古时指预兆火灾的天象"}, {"w": "火所", "t": "发生火灾的地方。"}]}, {"meaning": "灯火,指灯烛或火把。", "cites": [{"t": "江船火独明。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "拥火以入。", "b": "宋·王安石《游褒禅山记》"}, {"t": "火且尽。", "b": ""}, {"t": "火尚足以明。", "b": ""}], "words": [{"w": "火鼓", "t": "火炬和战鼓"}, {"w": "渔火", "t": ""}, {"w": "火燎", "t": "竹烛;火炬。"}]}, {"meaning": "中国古代兵制单位, 十人为 “火”。", "cites": [{"t": "皆解甲,散还火伍中。", "b": "柳宗元《段太尉逸事状》"}]}, {"meaning": "火星之简称。又名大火 。司南方,主夏季。而古恒星之名,心宿二,古称“大火”,亦简称火。", "cites": [{"t": "七月流火。", "b": "《诗·豳风·七月》"}, {"t": "大火谓之大辰。", "b": "《尔雅·释天》。按:“东方之宿三星,中一星色赤而大,故命之曰火。”"}, {"t": "火为口舌之象。", "b": "《论衡·言毒》"}], "words": [{"w": "金木水火土五大行星", "t": ""}, {"w": "火角", "t": "火星芒角"}, {"w": "火官", "t": "古时掌祭火星、行火政之官"}, {"w": "火房", "t": "火星的分野。"}]}, {"meaning": "焚烧;烧毁。", "cites": [{"t": "火,燬也。", "b": "《说文》"}, {"t": "火,言毁也,物入中皆毁坏也。", "b": "《释名·释天》"}], "words": [{"w": "火人", "t": "以火烧人"}, {"w": "火库", "t": "焚烧敌方兵库"}, {"w": "火队", "t": "焚烧敌方队伍,以乱其行阵"}, {"w": "火积", "t": "焚烧敌方的储备。"}]}, {"meaning": "形容像火那样的颜色,一般指红色的。", "cites": [{"t": "朱鳞火鬣。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "火云", "t": "红云"}, {"w": "火采", "t": "红光"}, {"w": "火狐", "t": ""}, {"w": "火旆", "t": "红色的旌旗"}, {"w": "火树", "t": "形容开满红花的树。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('165wx','为','1','wéi wèi','丶','4','','[{"pinyin": "wéi", "defs": [{"meaning": "(爲的本义是母猴。象形。按字,从爪,古文下象两母猴相对形)。"}, {"meaning": "假借为“伪”。做,作,干,搞。", "cites": [{"t": "我生之初,尚无为。", "b": "《诗·王风·兔爰》"}, {"t": "子为不知,我将不墜。", "b": "《左传·定公十二年》"}, {"t": "为善者,非善也,故善无以为也。", "b": "《管子·枢言》"}, {"t": "变化则为生,为生则乱矣。", "b": "《管子·心术上》"}, {"t": "为,施也。又,成也。", "b": "《广雅》"}, {"t": "有客自云能,帝使为之。", "b": "《世说新语·巧艺》"}, {"t": "为之难。", "b": "《论语》。皇疏:“犹行也。”"}, {"t": "可以为师。", "b": "《论语》"}, {"t": "人之为学。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "推为长。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "为之者较少。", "b": "蔡元培《图画》"}], "words": [{"w": "为事", "t": "办事;成事"}, {"w": "为诈", "t": "作假"}, {"w": "为薪", "t": "取薪"}, {"w": "为善", "t": "做善事"}, {"w": "为道", "t": "学道,实践圣道"}, {"w": "为头", "t": "居首;从头开始"}, {"w": "为人", "t": "做人"}, {"w": "为后", "t": "立后"}, {"w": "为底", "t": "治足茧。"}]}, {"meaning": "制作;创作。", "cites": [{"t": "造作,为也。", "b": "《尔雅》"}, {"t": "以为乐器。", "b": "《周礼·春官·典同》。注:“为,作也。”"}, {"t": "其为衣裘何?以为冬以圉寒,夏以圉暑。", "b": "《墨子·节用上》"}, {"t": "夫仰而视其细枝,则拳曲而不可以为栋梁,俯而见其大根,则轴解而不可为棺槨。", "b": "《庄子·人间世》"}, {"t": "应声便为诗。", "b": "《世说新语·文学》"}]}, {"meaning": "治理。", "cites": [{"t": "为,治也。", "b": "《小尔雅》"}, {"t": "诸葛瑾为豫州。", "b": "《世说新语·排调》"}], "words": [{"w": "为国", "t": "治国"}, {"w": "为政", "t": "治理国家;执掌国政。"}]}, {"meaning": "变成,成为。", "cites": [{"t": "何遽不为福。", "b": "《淮南子·人间训》"}, {"t": "不能为祸。", "b": ""}, {"t": "终为忠臣。", "b": "《世说新语·自新》"}, {"t": "而改为入。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "由徒为师", "t": ""}]}, {"meaning": "是。", "cites": [{"t": "不为远者小。", "b": "《列子·汤问》"}, {"t": "不为近者热。", "b": ""}, {"t": "治不病以为功。", "b": "《韩非子·喻老》"}, {"t": "谓为三横。", "b": "蔡元培《图画》"}], "words": [{"w": "十尺为一丈", "t": ""}]}, {"meaning": "学习,研究。", "cites": [{"t": "群臣为学,门子好辩,商贾外积,小民右仗者,可亡也。", "b": "《韩非子》"}]}, {"meaning": "种植;营作。", "cites": [{"t": "东周欲为稻,西周不下水,东周患之。", "b": "《战国策》"}]}, {"meaning": "使。", "cites": [{"t": "井渫不食,为我心恻。", "b": "《易·井》"}]}, {"meaning": "以为;认为。", "cites": [{"t": "为汝多智。", "b": "《列子·汤问》"}, {"t": "惊为生人。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "我将为无人会使此法。", "b": "《大唐三藏取经诗话》"}]}, {"meaning": "被 ——引出动作行为的主动者。", "cites": [{"t": "不为酒困。", "b": "《论语·子罕》"}, {"t": "为乡里所患。", "b": "《世说新语·自新》"}, {"t": "为予群从所得。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "为操所先。", "b": "《资治通鉴》"}, {"t": "悉为逆据。", "b": "《广东军务记》"}], "words": [{"w": "不为表面现象所迷惑;为贼所盗;为敌所败", "t": ""}]}, {"meaning": "于,在 ——表示时间或处所。", "cites": [{"t": "今之时人,辞官而隐处为乡邑之下。", "b": "《淮南子》"}]}, {"meaning": "和 ——表示并列关系。", "cites": [{"t": "得之为有财,古之人皆用之。", "b": "《孟子·公孙丑下》"}, {"t": "犀首以梁为齐战于承匡而不胜。", "b": "《战国策》"}]}, {"meaning": "则,就 ——表示承接关系。", "cites": [{"t": "君子有勇而无义为乱,小人有勇而无义为盗。", "b": "《论语·阳货》"}]}, {"meaning": "如,若 ——表示假设关系。", "cites": [{"t": "今诚得治国,国治身死不恨。为死,终不得治,不如去。", "b": "《史记》"}]}, {"meaning": "或,抑 ——表示选择关系。", "cites": [{"t": "助教顾良戏之曰:“汝姓何,是荷叶之荷,为河水之河?”妥应声曰:“先生姓顾,是眷顾之顾,为新故之故?”", "b": "《北史·何妥传》"}, {"t": "《太誓》之注不解“五至”,…不知为一日五来,为当异日也。”", "b": "《诗·周颂·思文》疏"}, {"t": "不审先生梁朝出仕,为复隐居?", "b": "《太平广记》"}], "words": [{"w": "为复", "t": "还是,抑或"}, {"w": "为是", "t": "抑或;还是"}, {"w": "为当", "t": "抑或;还是。"}]}, {"meaning": "的,之 ——用于名词性偏正结构中。", "cites": [{"t": "岂弟君子,四方为则。", "b": "《后汉书》"}]}, {"meaning": "宾语前置的标志。", "cites": [{"t": "使弈秋诲二人弈,其一人专心致志,惟弈秋之为听。", "b": "《孟子》"}]}, {"meaning": "用于句尾,表示感叹。", "cites": [{"t": "予无所用天下为。", "b": "《庄子》"}, {"t": "何命焉为。", "b": "《墨子·公输》"}]}, {"meaning": "姓。"}]}, {"pinyin": "wèi", "defs": [{"meaning": "(爲字的本义是母猴。象形。按字,从爪,下象形。古文象两母猴相对形)。"}, {"meaning": "帮助;佑助。", "cites": [{"t": "福禄来为。", "b": "《诗·大雅·凫鷖》"}], "words": [{"w": "为虎添", "t": "傅翼。"}]}, {"meaning": "言说;告诉。", "cites": [{"t": "宋,所为无雉兔孤狸者也。", "b": "《墨子·公输》"}, {"t": "管仲,曾西所不为也,而子为我愿之乎?", "b": "《孟子·公孙丑上》"}, {"t": "孰为盾而忍弑其君者乎?", "b": "《谷梁传·宣公二年》"}, {"t": "太子怒,入为王泣曰…", "b": "《韩非子·外储说右上》"}]}, {"meaning": "因为,由于。", "cites": [{"t": "非为织作迟,君家妇难为(做)。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "为是", "t": "因为是,为的是"}, {"w": "为甚", "t": "为什么。"}]}, {"meaning": "替,给。", "cites": [{"t": "为王吹竽。", "b": "《韩非子·内诸说上》"}, {"t": "为长安君计短。", "b": "《战国策·赵策》"}, {"t": "为楚王作剑。", "b": "晋·干宝《搜神记》"}, {"t": "为王作剑。", "b": ""}, {"t": "为国戍轮台。", "b": "宋·陆游《十一月四日风雨大作》"}], "words": [{"w": "为容", "t": "替人美言推荐"}, {"w": "为我去商店买东西;他的律师为他处理这个事件;为人谋而不忠乎?", "t": ""}]}, {"meaning": "为了。", "cites": [{"t": "为市鞍马。", "b": "《乐府诗集·木兰诗》"}, {"t": "则众何为。", "b": "宋·王安石《答司马谏议书》"}, {"t": "不为怨者故。", "b": ""}, {"t": "生为之饱。", "b": "清·周容《芋老人传》"}], "words": [{"w": "为国捐躯", "t": "为国家献出生命"}, {"w": "为好成歉", "t": "将好事变成坏事"}, {"w": "为许", "t": "为此。"}]}, {"meaning": "表示动作行为所向,可译为“向”、“对”、“朝”。", "cites": [{"t": "为具言所闻。", "b": "晋·陶渊明《桃花源记》"}, {"t": "不足为外人道。", "b": ""}, {"t": "为弟子说前代事。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('166wx','斗','1','dǒu dòu','斗','4','','[{"pinyin": "dǒu", "defs": [{"meaning": "(象形。有柄。说文叙,俗谓人持十为斗。本义:十升)。"}, {"meaning": "同本义。", "cites": [{"t": "斗,十升也。", "b": "《说文》"}, {"t": "角斗甬。", "b": "《礼记·月令》"}, {"t": "扫除十斗归,一一以叶自彰。", "b": "邯郸淳《笑林》"}], "words": [{"w": "斗斛", "t": "十升为斗,十斗为斛。计容积的量器"}, {"w": "斗米升珠", "t": "形容粮食短缺、米价奇高。"}]}, {"meaning": "盛酒器。", "cites": [{"t": "木瓢为斗。", "b": "《通俗文》"}, {"t": "太宰持斗而御户右。", "b": "《大戴礼记·保傅》。"}, {"t": "金樽清酒斗十千。", "b": "唐·李白《行路难》"}, {"t": "玉斗一双,欲与亚父。", "b": "《史记·项羽本纪》"}], "words": [{"w": "斗瓶", "t": "酒器"}, {"w": "斗酒百篇", "t": "饮一斗酒,作百篇诗。形容能诗善饮,文思敏捷,气概豪迈。"}]}, {"meaning": "口大底小的方形或鼓形量器,多用木头或竹子制成。容量为一斗。"}, {"meaning": "指北斗七星。", "cites": [{"t": "维北有斗。", "b": "《诗·小雅·大东》"}, {"t": "日中见斗。", "b": "《易·丰》"}, {"t": "夫乘舟而惑者,不知东西,见斗极则寤矣。", "b": "《淮南子·齐俗》"}], "words": [{"w": "斗箕", "t": "斗星和箕星"}, {"w": "斗君", "t": "道家语。指北斗之神"}, {"w": "斗斋", "t": "供奉斗星之处;亦指斗星神"}, {"w": "斗魁", "t": "魁星。北斗七星中形成斗形的四颗星"}, {"w": "斗杓", "t": "北斗七星形似勺,柄上的三颗星叫杓,斗杓指向东,时令交替。"}]}, {"meaning": "容量单位。也作量词。十升等于一斗,十斗等于一石。", "cites": [{"t": "吾不能为五斗米折腰。", "b": "《晋书·陶潜传》"}]}, {"meaning": "星宿名  二十八宿之一,也称南斗。", "cites": [{"t": "月出于东山之上,徘徊于斗牛之间。", "b": "宋·苏轼《赤壁赋》"}]}, {"meaning": "陡峭", "cites": [{"t": "成山斗入海。", "b": "《史记·封禅书》"}, {"t": "二壁争高,斗耸相乱。", "b": "《水经注·谷水》"}], "words": [{"w": "斗健", "t": "峭拔刚健"}, {"w": "斗辟", "t": "孤立而偏僻"}, {"w": "斗峻", "t": "高且陡"}, {"w": "斗峭", "t": "突兀"}, {"w": "斗绝", "t": "陡峭险峻。"}]}, {"meaning": "陡然,突然。", "cites": [{"t": "吟君诗罢看双鬓,斗觉霜毛一半加。", "b": "韩愈《答张十一功曹》"}], "words": [{"w": "斗顿", "t": "忽然"}, {"w": "斗然", "t": "突然。"}]}, {"meaning": "抖动。", "cites": [{"t": "珠缨炫转星宿摇。", "b": "白居易《骠国乐》"}, {"t": "斗薮尘埃衣。", "b": "孟郊《夏日谒智远禅师》"}], "words": [{"w": "斗叟", "t": "抖动;颤斗"}, {"w": "斗薮", "t": "抖动;抖落。"}]}]}, {"pinyin": "dòu", "defs": [{"meaning": "(象形。甲骨文字形,象两人怒发对打形。本义:搏斗)。"}, {"meaning": "搏斗;引申为战斗。", "cites": [{"t": "鬥,两士相对,兵杖在后,象鬥之形。", "b": "《说文》。按,争也。"}, {"t": "二士对戟为鬥。", "b": "《古考经说》"}, {"t": "鬥,遇也。", "b": "《说文》。按,相接之意。"}, {"t": "投身大敌,与之扑斗。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "又。", "cites": [{"t": "彼此错杂,纷纭拿斗,敌枪终不能发。", "b": ""}], "words": [{"w": "拳斗;械斗;格斗", "t": "紧张激烈地搏斗"}, {"w": "斗心", "t": "战斗的意志"}, {"w": "斗臣", "t": "勇健善斗之士"}, {"w": "钩心斗角", "t": "屋角由屋心伸出来,像与屋心钩在一起。各个屋角相对,像要相互搏斗。用此比喻用尽心机,明争暗斗。"}]}, {"meaning": "较量,竞赛。", "cites": [{"t": "试与他虫斗。", "b": "《聊斋志异·促织》"}], "words": [{"w": "斗口", "t": "斗嘴;开玩笑挑逗"}, {"w": "斗靡夸多", "t": "说长道短。斗:争。靡:无;少"}, {"w": "斗锦", "t": "争奇斗艳"}, {"w": "斗花", "t": "以奇花相竞赛"}, {"w": "斗香", "t": "以名香相竞赛"}, {"w": "斗草", "t": "古代以花草相赛的一种民俗游戏。一名斗百草"}, {"w": "斗茶", "t": "比赛茶的优劣"}, {"w": "斗棋", "t": "奕棋争胜。"}]}, {"meaning": "古代天文用语,星相击。", "cites": [{"t": "十四载二月,荧惑,太白斗于毕、昂、井、鬼间,至四月乃伏。", "b": "《新唐书》"}]}, {"meaning": "斗争,争斗。", "cites": [{"t": "见两小儿辩斗。", "b": "《列子·汤问》"}, {"t": "外连衡而斗诸侯。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "斗地主;斗宠", "t": "争夺受宠"}, {"w": "斗辩", "t": "争斗;争吵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('167wx','忆','1','yì','忄','4','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从心,意声。本义:思念,回想)。"}, {"meaning": "同本义。", "cites": [{"t": "问女何所忆。", "b": "《乐府诗集·木兰诗》"}, {"t": "还思建邺水,终忆武昌鱼。", "b": "庾信《奉和永丰殿下言志》"}], "words": [{"w": "忆想", "t": "回想。"}]}, {"meaning": "留在记忆中;记住。", "cites": [{"t": "读书数行并下,过目皆忆。", "b": "《梁书》"}, {"t": "汝忆否。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "忆记", "t": "记忆"}, {"w": "忆识", "t": "记忆。"}]}, {"meaning": "回忆。", "cites": [{"t": "能不忆江南。", "b": "唐·白居易《忆江南》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('168wx','计','1','jì','讠','4','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。从言,从十。“言”有数(shǔ)的意思;“十”是整数,表示事物成一个数目。数数字,所以有计算的意思。本义:算账;总计;计算)。"}, {"meaning": "同本义。", "cites": [{"t": "計,会算也。", "b": "《说文》"}, {"t": "计数刚柔也,轻重也,大小也,实虚也,远近也,多少也,谓之计数。", "b": "《管子·七发》"}, {"t": "学书计。", "b": "《礼记·内则》"}, {"t": "命农计耦耕事。", "b": "《礼记·月令》"}, {"t": "计亿事。", "b": "《国语·郑语》。注:“算也。”"}, {"t": "计日而待。", "b": "诸葛亮《出师表》"}, {"t": "计日以还。", "b": "明·宋濂《送东阳马生序》"}, {"t": "而计其长。", "b": "明·魏学洢《核舟记》"}, {"t": "蹄躈各千计。", "b": "《聊斋志异·促织》"}], "words": [{"w": "计会", "t": "计算账目;秋后算账;谋划,部署"}, {"w": "计口", "t": "按人口计算"}, {"w": "计度", "t": "安排生活用度"}, {"w": "算计", "t": "估计。"}]}, {"meaning": "计较;关心于。", "cites": [{"t": "以六计弊群吏之治。", "b": "《周礼·太宰》"}, {"t": "主逼畏不敢计。", "b": "《资治通鉴》"}], "words": [{"w": "计惜", "t": "计较与吝惜"}, {"w": "计争", "t": "计较争执"}, {"w": "计功谋利", "t": "计较功名,谋求私利"}, {"w": "不计报酬", "t": ""}]}, {"meaning": "商议;谋划。", "cites": [{"t": "计,谋也。", "b": "《广雅》"}, {"t": "以能遂疑计恶。", "b": "《国语·吴语》。注:“虑也。”"}, {"t": "父母之爱子,则为之计深远。", "b": "《战国策·赵策》"}, {"t": "非计久长。", "b": ""}, {"t": "长安君计短。", "b": ""}, {"t": "计之曰。", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "计不得售", "t": ""}, {"w": "计处", "t": "考虑;谋划"}, {"w": "计画", "t": "计虑;谋划"}, {"w": "计开", "t": "列写出来"}, {"w": "计事", "t": "商议大事"}, {"w": "计奏", "t": "商议后奏请"}, {"w": "计办", "t": "商议办理"}, {"w": "商计", "t": ""}]}, {"meaning": "考察;审核。", "cites": [{"t": "料敌计险。", "b": "《孙子兵法·威王问》"}]}, {"meaning": "又如：计勘(审核勘验);计制(审核规格)。"}, {"meaning": "计策;计谋。", "cites": [{"t": "计者,事之本也。", "b": "《战国策·秦策》"}, {"t": "计者,所以定事也。", "b": "《韩非子·存韩》"}, {"t": "吾计已决。", "b": "汉·刘向《列女传》"}, {"t": "计无所出。", "b": "晋·干宝《搜神记》"}, {"t": "何以为计。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "计疏", "t": "计谋疏失"}, {"w": "计智", "t": "智谋"}, {"w": "缓兵之计", "t": ""}, {"w": "失计", "t": ""}, {"w": "巧计", "t": ""}, {"w": "空城计", "t": ""}, {"w": "苦肉计", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('169wx','订','1','dìng','讠','4','','[{"pinyin": "dìng", "defs": [{"meaning": "(形声。从言,丁声。本义:评议)。"}, {"meaning": "同本义。", "cites": [{"t": "订,平议也。", "b": "《说文》。按,字亦作评。"}, {"t": "订太平文王之道。", "b": "《诗·天作》笺"}, {"t": "两论相订,是非乃见。", "b": "《论衡·案书》"}], "words": [{"w": "订铨", "t": "评议衡量"}, {"w": "《订鬼篇》", "t": ""}]}, {"meaning": "改正,修正。", "cites": [{"t": "下足以订史氏之失者。", "b": "李清照《金石录后序》"}, {"t": "亦足有所订正。", "b": "《晋书·荀崧传》"}], "words": [{"w": "订顽", "t": "改正愚顽"}, {"w": "修订", "t": ""}]}, {"meaning": "预先约定  如:订购;订阅。"}, {"meaning": "把零散的纸张、书页加工成本  如:装订;订书。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('170wx','户','1','hù','户','4','','[{"pinyin": "hù", "defs": [{"meaning": "(象形。甲骨文字形,象门(門)字的一半。汉字部首之一。从“户”的多与门户有关。本义:单扇门)。"}, {"meaning": "同本义。", "cites": [{"t": "户,半门曰户。", "b": "《说文》"}, {"t": "一扇曰户,两扇曰门。又在于堂室东曰户,在于宅区域曰门。", "b": "《字书》"}, {"t": "窥其户。", "b": "《易·丰》"}, {"t": "设于户西。", "b": "《仪礼·聘礼》"}, {"t": "未有入室而不由户者。", "b": "《礼记·礼器》"}, {"t": "木兰当户织。", "b": "《乐府诗集·木兰诗》"}, {"t": "当户理红妆。", "b": ""}, {"t": "出户望南山。", "b": "晋·干宝《搜神记》"}, {"t": "出户南望。", "b": ""}, {"t": "窗户皆闭。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "户下", "t": "门边;户住的属下。多指奴婢或门客"}, {"w": "户牡", "t": "门钥"}, {"w": "户门", "t": "守门的人"}, {"w": "户钥", "t": "门上开关的锁钥。"}]}, {"meaning": "住户,人家。一家称一户。", "cites": [{"t": "其邑人三百户。", "b": "《易·讼》"}, {"t": "户说以眇论。", "b": "《史记·货殖列传》"}, {"t": "户裁及万。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "户出一男。", "b": ""}, {"t": "为一户者。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "全户人口;几百户人家;户帖", "t": "登记每户人口籍贯、名义的册子"}, {"w": "户版", "t": "登记居民户籍的簿册。"}]}, {"meaning": "屋室。", "cites": [{"t": "初九,不出户庭,无咎。", "b": "《易·节卦·象辞》"}, {"t": "不出户知天下。", "b": "《老子·四七》"}]}, {"meaning": "酒量。", "cites": [{"t": "酒户年年减,山行渐渐难。", "b": "《元稹·春游诗》"}]}, {"meaning": "洞穴。", "cites": [{"t": "蛰虫坏户。", "b": "《礼记·月令》"}, {"t": "[仲春之月]是月也,日夜分,雷乃发声,始电,蛰虫咸动,启户始出。", "b": "《礼记》。孔颖达疏:“户,谓穴也。”"}, {"t": "所以青云人,高歌在岩户。", "b": "唐·李白诗"}]}, {"meaning": "阻止。", "cites": [{"t": "王见右广,将从之乘,屈荡户之曰:“君以此始,亦必以终。”", "b": "《左传·宣公十二年》。注:“户,止也。”"}]}, {"meaning": "用以计户数。", "cites": [{"t": "徙天下豪富于咸阳十二万户。", "b": "《史记》"}], "words": [{"w": "几户人家;穷人五户", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('171wx','认','1','rèn','讠','4','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从言,忍声。本义:认识,辨明)。"}, {"meaning": "同本义。", "cites": [{"t": "你去营中寻林教头来,认他一认。", "b": "《水浒传》"}, {"t": "过了数日,待没了认色,却将去本府告赏。", "b": "《古今小说》"}], "words": [{"w": "认出他失散多年的兄弟;认记", "t": "辨认的记号"}, {"w": "认色", "t": "辨认的标记"}, {"w": "认旗", "t": "军中作为标志、信号的旗帜"}, {"w": "认领", "t": "辨认并领取"}, {"w": "认证", "t": "辨认并证实"}, {"w": "认透", "t": "看透了,识破"}, {"w": "认尸", "t": "辨认亲人的尸骨。"}]}, {"meaning": "把本无某种亲密关系的人看作有某种亲密关系。", "cites": [{"t": "赤发鬼醉卧灵官殿,晁天王认义东溪村。", "b": "《水浒传》"}], "words": [{"w": "认义", "t": "结义;结拜"}, {"w": "认亲", "t": "认作亲戚"}, {"w": "认族", "t": "把同姓不同宗的人认成同族"}, {"w": "他们认他为养子", "t": ""}]}, {"meaning": "说话谨慎。", "cites": [{"t": "外是者谓之认。", "b": "《荀子·正名》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('172wx','冗','1','rǒng','冖','4','','[{"pinyin": "rǒng", "defs": [{"meaning": "( 《说文》:“散也。从宀儿(人),人在屋下,无田事也。”儿,“人”的古文形体。本义:闲散)。"}, {"meaning": "同本义。", "cites": [{"t": "冗,散也。", "b": "《说文》"}, {"t": "掌共外内朝冗食者之食。", "b": "《周礼·槁人》"}, {"t": "流散冗食。", "b": "《汉书·谷永传》"}], "words": [{"w": "冗从", "t": "官名。散职侍从官。出则骑从,居则宿卫"}, {"w": "冗职", "t": "闲散的官职"}, {"w": "冗兵", "t": "闲散无事的军队"}, {"w": "冗食", "t": "公家给食。坐吃闲饭"}, {"w": "冗人", "t": "闲人,吃闲饭的人"}, {"w": "冗口", "t": "吃闲饭的人"}, {"w": "冗吏", "t": "无固定职事的官吏。"}]}, {"meaning": "多余。", "cites": [{"t": "要辞达而理举,故无取乎冗长。", "b": "陆机《文赋》"}, {"t": "承训罢冗费,市马益军。", "b": "《新唐书·康承训传》"}, {"t": "又裁节邮传冗费。", "b": "《明史·海瑞传》"}], "words": [{"w": "冗列", "t": "多余的官员"}, {"w": "冗局", "t": "多余的机构"}, {"w": "冗句", "t": "累赘的文句"}, {"w": "冗积", "t": "冗员积累"}, {"w": "冗僭", "t": "多余而又不称职的官吏"}, {"w": "冗辞", "t": "不当而无用的言辞"}, {"w": "冗蠹", "t": "多余而有害者。"}]}, {"meaning": "离散,向四周散开。", "cites": [{"t": "冗,民无定居。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('173wx','讥','1','jī','讠','4','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从言,幾(jì)声。本义:旁敲侧击地批评)。"}, {"meaning": "同本义。", "cites": [{"t": "讥,诽也。", "b": "《说文》"}, {"t": "此何以书讥。", "b": "《公羊传·隐公二年》。注:“犹谴也。”"}, {"t": "诛讥罢只。", "b": "《楚辞·大招》。注:“非也。”"}, {"t": "二者交讥。", "b": "《史记·游侠传》。正义:“非言也”>"}, {"t": "于人为可讥。", "b": "宋·王安石《游褒禅山记》"}, {"t": "孰能讥之乎?", "b": ""}, {"t": "公孙布被之讥。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "讥呵", "t": "责问,责难"}, {"w": "讥毁", "t": "非议诋毁"}, {"w": "讥望", "t": "责怪。"}]}, {"meaning": "讽刺;讥笑。", "cites": [{"t": "谤讥于市朝。", "b": "《战国策·齐策》"}, {"t": "列壑争讥,攒峰竦诮。", "b": "孔稚圭《北山移文》"}], "words": [{"w": "讥讪", "t": "讥刺讪笑"}, {"w": "讥言", "t": "讥讽的言论"}, {"w": "讥弄", "t": "讥笑嘲弄"}, {"w": "讥鄙", "t": "讥笑鄙视。"}]}, {"meaning": "进谏;规劝。", "cites": [{"t": "讥,谏也。", "b": "《广雅》"}, {"t": "殷有惑妇,何所讥?", "b": "《楚辞·天问》"}], "words": [{"w": "讥谏", "t": "劝谏"}, {"w": "讥绳", "t": "劝谏和纠正。"}]}, {"meaning": "查问。", "cites": [{"t": "讥,问也。", "b": "《广雅》"}, {"t": "好讥而不乱,亟变而不变,时至则为,过则去。", "b": "《管子·国准》"}, {"t": "关讥而不征。", "b": "《孟子》。注:“察也”"}, {"t": "关执禁以讥。", "b": "《礼记·王制》。注:“呵察也”"}, {"t": "几(讥)其出入。", "b": "《周礼·宫正》"}], "words": [{"w": "讥而不征", "t": "稽查外来商旅,但不征收税捐"}, {"w": "讥察使", "t": "官名。掌查究奸伪"}, {"w": "讥视", "t": "稽察"}, {"w": "讥查", "t": "盘问检查"}, {"w": "讥问", "t": "讥问。"}]}, {"meaning": "非难,指责的话。", "cites": [{"t": "忧谗畏讥。", "b": "宋·范仲淹《岳阳楼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('174wx','心','1','xīn','心','4','','[{"pinyin": "xīn", "defs": [{"meaning": "(象形。据甲骨文和小篆,中间像心;外面像心的包络。本义:心脏)。"}, {"meaning": "同本义。", "cites": [{"t": "心,人心也。在身之中,象形。", "b": "《说文》。按,在肺之下,膈膜之上,着脊第五椎。形如莲蕊,上有四系,以通四脏。心外有赤黄裹脂,谓之心包络。"}, {"t": "其祀中霤,祭先心。", "b": "《吕氏春秋》"}, {"t": "顺我,即先刺心;否则,四肢解尽,心犹不死。", "b": "方苞《狱中杂记》"}], "words": [{"w": "心腹之病", "t": "致命之祸;隐患"}, {"w": "心上刃", "t": "“忍”字的拆写"}, {"w": "心肝肐蒂", "t": "心肝宝贝"}, {"w": "心气", "t": "中医指心脏的功能"}, {"w": "心系", "t": "系悬心脏于胸腔中的筋脉"}, {"w": "心脾", "t": "心脏与脾脏。"}]}, {"meaning": "内心。", "cites": [{"t": "日月阳止,女心伤止。", "b": "《诗·小雅·杕杜》"}], "words": [{"w": "心悦情服", "t": "真心乐意地情愿或服从"}, {"w": "心香", "t": "敬事鬼神,心笃意诚,同于焚香"}, {"w": "心苗", "t": "心意;心愿。"}]}, {"meaning": "古代人以心为思维器官,故后沿用为脑的代称。", "cites": [{"t": "心之官则思。", "b": "《孟子》"}], "words": [{"w": "心猿智慧", "t": "喻头脑机敏灵活"}, {"w": "心拙口夯", "t": "心笨口笨"}, {"w": "心坌", "t": "愚笨"}, {"w": "心知", "t": "心智。"}]}, {"meaning": "思想。", "cites": [{"t": "他人有心,予忖度之。", "b": "《诗·小雅·巧言》"}, {"t": "心忧炭贱。", "b": "唐·白居易《卖炭翁》"}, {"t": "汝心之固。", "b": "《列子·汤问》"}, {"t": "心乐之。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "用心专。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "心量", "t": "志气;抱负"}, {"w": "心体", "t": "指思想"}, {"w": "心识", "t": "意识"}, {"w": "心想", "t": "思想;感情"}, {"w": "心裁", "t": "指思想,主意"}, {"w": "心用", "t": "思想行为。"}]}, {"meaning": "中心,中央。", "cites": [{"t": "东船西舫悄无言,唯见江心秋月白。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "又。", "cites": [{"t": "当心画", "b": ""}, {"t": "波心荡。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "心号", "t": "兵卒上衣前后的标志符号"}, {"w": "心经", "t": "《般若波罗密多心经》的简称。以其概括了《般若经》的核心,故称"}, {"w": "心子;心脏;江心", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('175wx','尺','1','chě chǐ','尸','4','','[{"pinyin": "chě", "defs": [{"meaning": "中国民族音乐音阶上的一级,乐谱上用做记音符号,相当于简谱的“2”,如“工尺”。"}]}, {"pinyin": "chǐ", "defs": [{"meaning": "(指事。小篆,从尸,从乙。“尸”象人卧的形象。“乙”是个标识,周制寸、咫、尺、仞、寻、常诸度,皆以人之体为法。本义:十寸)。"}, {"meaning": "同本义,量词。长度单位。", "cites": [{"t": "尺,十寸也。人手却十分动脉为寸口。十寸为尺,所以指斥规榘事也。", "b": "《说文》"}]}, {"meaning": "喻短小或狭小的。", "cites": [{"t": "尺泽之蜺也。", "b": "《后汉书·对楚五问》"}], "words": [{"w": "尺土", "t": "形容极为狭小的土地"}, {"w": "尺地", "t": "极少的土地"}, {"w": "尺铁", "t": "短小的铁制武器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('176wx','引','1','yǐn','弓','4','','[{"pinyin": "yǐn", "defs": [{"meaning": "(会意。从弓丨。丨表示箭。箭在弦上,即将射发。本义:拉开弓)。"}, {"meaning": "同本义。", "cites": [{"t": "引,开弓也。", "b": "《说文》"}, {"t": "君子引而不发,跃如也。", "b": "《孟子》"}, {"t": "引弓而射。", "b": "《淮南子·说林训》"}, {"t": "臣为王引弓,虚发而下鸟。", "b": "《战国策·楚策》"}, {"t": "长城以后,引弓之国,受命单于。", "b": "《史记·匈奴列传》"}, {"t": "丁壮者,引弦而战。", "b": "《淮南子·人间训》"}, {"t": "柄铁折叠环复…引之长丈许。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "引手", "t": "引箭手"}, {"w": "引弓", "t": "拉弓"}, {"w": "引满", "t": "拉弓至满。"}]}, {"meaning": "拉,牵挽。", "cites": [{"t": "人方引婴儿而欲投之江中。婴儿啼。", "b": "《吕氏春秋·察今》"}, {"t": "引相如去。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "引车避匿。", "b": ""}, {"t": "友人惭,下车引之。元方入门,不顾(引之),拉他(表示好感)。", "b": "《世说新语·方正》"}], "words": [{"w": "引日", "t": "拉转日轮"}, {"w": "引手", "t": "拉回手"}, {"w": "引曳", "t": "牵拉。"}]}, {"meaning": "延长;延续。", "cites": [{"t": "子子孙孙,忽替引之。", "b": "《诗·小雅·楚茨》"}], "words": [{"w": "引日", "t": "拖延时日"}, {"w": "引年", "t": "延长年寿"}, {"w": "引时", "t": "迁延时日。"}]}, {"meaning": "伸着。", "cites": [{"t": "引首顾曰。", "b": "马中锡《中山狼传》"}, {"t": "使者持刀趋前,济引颈待之。", "b": "《新唐书·卓行传·甄济》"}], "words": [{"w": "引首", "t": "伸长头颈,抬起头。形容殷切盼望"}, {"w": "引手", "t": "伸手"}, {"w": "引颈", "t": "伸长颈项"}, {"w": "引臂", "t": "伸臂。"}]}, {"meaning": "牵连;攀供。", "cites": [{"t": "果引张胜。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "引附", "t": "攀附"}, {"w": "引逮", "t": "株连捕。"}]}, {"meaning": "引导。", "cites": [{"t": "引之表仪。", "b": "《左传·文公六年》"}], "words": [{"w": "引转", "t": "扭转;转回"}, {"w": "引风吹火", "t": "引风助火势。喻指煽风点火,加重事态"}, {"w": "引商刻羽", "t": "指讲究声律、造诣很深,有很高成就的音乐演奏。"}]}, {"meaning": "带领。", "cites": [{"t": "复夜引兵。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "引奏", "t": "向帝王禀告、上书"}, {"w": "引领", "t": "带领"}, {"w": "引线", "t": "告密、引路捕人者。"}]}, {"meaning": "引决、自尽。", "cites": [{"t": "感三良之殉秦兮,甘捐生而自引。", "b": "《文选·潘岳·寡妇赋》"}], "words": [{"w": "引决", "t": "自杀"}, {"w": "引诀", "t": "引决"}, {"w": "引药", "t": "服毒自杀。"}]}, {"meaning": "援引。", "cites": [{"t": "不宜妄自菲薄,引喻失义。", "b": "诸葛亮《出师表》"}, {"t": "引入上谕中。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "引喻失义", "t": "援引例证以明理而失去大义"}, {"w": "引经据古", "t": "引用经史古籍中的文句或故事作为根据。"}]}, {"meaning": "荐举。", "cites": [{"t": "两人相为引重,其游如父子然。", "b": "《史记·魏其武安侯传》"}], "words": [{"w": "引援", "t": "推举;引荐"}, {"w": "引预", "t": "引荐,使之参与。"}]}, {"meaning": "招致。", "cites": [{"t": "必亲引问。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "又如:引纳(招致接纳);引惹(招惹)。"}, {"meaning": "退避。", "cites": [{"t": "自引而起。", "b": "《战国策·燕策》"}, {"t": "引次江北。", "b": "《资治通鉴》"}]}, {"meaning": "又如:引避(引退,回避);引遁(退却,逃走)。"}, {"meaning": "吸引。", "cites": [{"t": "引入黄婆洞。", "b": "《广东军务记》"}]}, {"meaning": "又如:引类呼朋(呼引同类);引狗入寨(比喻主动把敌人或坏人引进来);引流(导引水流)。"}, {"meaning": "举起;竖起。", "cites": [{"t": "引其匕首提秦王,不中,中柱。", "b": "《战国策·燕策》"}]}, {"meaning": "又如:引耳(竖着耳朵);引饮(举杯而饮)。"}, {"meaning": "承认。", "cites": [{"t": "权引咎责躬。", "b": "《三国志·吴志》"}]}, {"meaning": "又如:引伏(服罪);引过(承认过失);引罪(承认罪过)。"}, {"meaning": "延请。", "cites": [{"t": "公子引侯生坐上坐。", "b": "《史记·魏公子列传》"}]}, {"meaning": "取过来,拿出。", "cites": [{"t": "引佩刀。", "b": "《汉书·李广苏建传》"}, {"t": "引壶觞。", "b": "晋·陶渊明《归去来兮辞》"}]}, {"meaning": "引车前行的皮带。", "cites": [{"t": "縣縣常以结引驰外为务。", "b": "《荀子·王霸》。注:“引,读为靷。靷,引轴之物。”"}, {"t": "属引。", "b": "《仪礼·既夕礼》。注:“引,所以引柩车,在轴遁曰绋。”"}, {"t": "执引者三百人。", "b": "《周礼·大司徒》"}]}, {"meaning": "乐曲体裁之一,有序奏之意。", "cites": [{"t": "故聆曲引者,观法于节奏。", "b": "马融《长笛赋》"}], "words": [{"w": "引辞", "t": "宋元戏曲演唱时第一支曲子的泛称,用以引起剧情。"}]}, {"meaning": "指商人运销货物的凭证。", "cites": [{"t": "令客人赴官请引,自于茶园买茶…", "b": "《宣和遗事》"}], "words": [{"w": "引行公店", "t": "盐商联合经营的机构"}, {"w": "盐引;茶引", "t": ""}]}, {"meaning": "通行执照。", "cites": [{"t": "央李员外衙门上下打点使用了钱,见了大严,给引还乡。", "b": "《警世通言》"}]}, {"meaning": "长久。", "cites": [{"t": "常有高猿长啸,属引凄异。", "b": "《水经注》"}]}, {"meaning": "长度单位 。古代以十丈为一引。今为市引的简称。1公里=30引。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('177wx','丑','1','chǒu','一','4','','[{"pinyin": "chǒu", "defs": [{"meaning": "(形声。从鬼,酉声。古人以为鬼的面貌最丑,故从鬼。本义:貌丑。按:在古代,“醜”和“丑”是两个字,意义各不相同,除作地支和时辰用“丑”以外,都不能写作“丑”。现在“醜”字简化为“丑”)。"}, {"meaning": "可恶。", "cites": [{"t": "醜,可恶也。", "b": "《说文》"}, {"t": "耗土之人醜。", "b": "《大戴礼记·易本命》"}, {"t": "姱而不醜兮。", "b": "《楚辞·橘颂》"}, {"t": "亦孔之醜。", "b": "《诗·小雅·十月之交》。传:“恶也。”"}], "words": [{"w": "丑名", "t": "恶名"}, {"w": "丑言", "t": "恶劣的话"}, {"w": "丑攀谈", "t": "说粗俗话"}, {"w": "丑徒", "t": "恶徒"}, {"w": "丑语", "t": "恶劣的话。也作丑话。"}]}, {"meaning": "污秽。", "cites": [{"t": "行莫醜于辱先生。", "b": "司马迁《报任少卿书》。注:“秽也。”"}], "words": [{"w": "丑秽", "t": "丑陋污秽。"}]}, {"meaning": "众多。", "cites": [{"t": "醜,众也。", "b": "《尔雅》"}, {"t": "在醜夷不争。", "b": "《礼记·曲礼》。注:“众也。”"}], "words": [{"w": "丑虏", "t": "众多的敌人。也指丑恶的敌人"}, {"w": "丑杂", "t": "众多杂乱。"}]}, {"meaning": "类,相同。", "cites": [{"t": "比物醜类。", "b": "《礼记·学记》"}, {"t": "获匪其醜。", "b": "《易·离》"}], "words": [{"w": "丑夷", "t": "年辈相同、学业相等的人"}, {"w": "丑侪", "t": "同类,等辈。"}]}, {"meaning": "厌恶;憎恶。", "cites": [{"t": "醜类恶物。", "b": "《左传·文公十八年》"}], "words": [{"w": "丑沮", "t": "丑诋毁谤。"}]}, {"meaning": "侮辱;玷污。", "cites": [{"t": "秦昭王闻之,而欲丑之以辞。", "b": "《吕氏春秋》"}]}, {"meaning": "愤怒。", "cites": [{"t": "莫不醜于色。", "b": "《淮南子·说林》"}], "words": [{"w": "丑诋", "t": "谩骂诋毁"}, {"w": "丑辞", "t": "谩骂之言"}, {"w": "丑诋", "t": "辱骂;诋毁。"}]}, {"meaning": "惭愧。", "cites": [{"t": "寡人醜乎。", "b": "《庄子·德充符》。注:“愧也。”"}], "words": [{"w": "丑比", "t": "以曲从阿党为耻"}, {"w": "丑剌剌", "t": "方言。羞人答答"}, {"w": "丑辱", "t": "耻辱。"}]}, {"meaning": "怪异之事。", "cites": [{"t": "四曰记丑而博,五曰顺非而泽。", "b": "《荀子·宥坐》"}]}, {"meaning": "传统戏曲中的一种角色,扮演滑稽人物。"}, {"meaning": "(象形。甲骨文象爪形。①本义:爪 ②地支的第二位)。"}, {"meaning": "地支的第二位。", "cites": [{"t": "丑,纽也。十二月万物动用事。", "b": "《说文》"}]}, {"meaning": "用以纪月,即农历十二月。"}, {"meaning": "用以纪日。"}, {"meaning": "用以纪时,即早晨一时至三时。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('178wx','巴','1','bā','巳','4','','[{"pinyin": "bā", "defs": [{"meaning": "(象形。小篆象蛇形。本义:大蛇)。"}, {"meaning": "古代传说中的一种大蛇。", "cites": [{"t": "巴,巴虫也,或曰食象蛇。", "b": "《说文》"}, {"t": "巴蛇食象,三岁而出其骨。", "b": "《山海经·海内南经》。注:“说者云,长千寻。”"}, {"t": "朱卷之国,有黑蛇青象,食象。", "b": "《山海经·海内经》。注:“即巴蛇也。”"}]}, {"meaning": "古族名;古代国名,辖境在今四川省东部。", "cites": [{"t": "西南有巴国。", "b": "《山海经·海内经》。注:“今三巴是。”"}, {"t": "巴人以比翼鸟。", "b": "《周书·王会》"}, {"t": "秦西有巴戎。", "b": "《荀子·彊国》。注:“巴在西南,戎在西,皆隶属。”"}]}, {"meaning": "古时这里出产巴蛇,因此周朝分封在该地区的诸侯国叫“巴子国”。秦惠文王灭巴后,改置巴、蜀、汉中三郡。"}, {"meaning": "压强的单位,等于105帕,或105牛顿/米2,或106达因/厘米2(0.986923标准大气压)。"}, {"meaning": "盼,期待着愿望的实现。", "cites": [{"t": "暗潮巴到无人会,只有篙师识水痕。", "b": "杨万里《过沙头》"}], "words": [{"w": "巴得", "t": "盼望。"}]}, {"meaning": "靠近;贴近。", "cites": [{"t": "前不巴村,后不着店,怎生是好?", "b": "元·王晔《桃花女》"}, {"t": "我只道是谁,巴着窗户眼儿一瞧,原来宝妹妹坐在炕沿上。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('179wx','孔','1','kǒng','子','4','','[{"pinyin": "kǒng", "defs": [{"meaning": "(象形。金文字形,象小儿食乳之形。婴儿吃奶容易过量,因以表示过甚之意。本义:甚,很) 同本义。", "cites": [{"t": "其新孔嘉。", "b": "《诗·豳风·东山》"}], "words": [{"w": "孔亟", "t": "甚急"}, {"w": "孔多", "t": "很多"}, {"w": "孔明", "t": "很完备;很洁净;很鲜明"}, {"w": "孔疚", "t": "很痛苦"}, {"w": "孔虔", "t": "非常虔诚"}, {"w": "孔圣", "t": "很圣明。"}]}, {"meaning": "小窟窿。", "cites": [{"t": "孔,窍也,空也。", "b": "《玉篇》"}, {"t": "孔德之容。", "b": "《老子》二十一章"}]}, {"meaning": "王注:“孔,空也。”。", "cites": [{"t": "反古之道。", "b": "《礼记·中庸》。注:“谓晓一孔之人。”"}, {"t": "自钱孔入。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "钥匙孔;鼻孔;孔口", "t": "洞口"}, {"w": "孔窍", "t": "洞孔。"}]}, {"meaning": "孔雀的省称。", "cites": [{"t": "孔翠(翠鸟)群翔,犀象竞驰。", "b": "左思《吴都赋》"}], "words": [{"w": "孔盖", "t": "以孔雀的羽毛装饰的车盖"}, {"w": "孔翠", "t": "孔雀和翠鸟。"}]}, {"meaning": "嘉,美。", "cites": [{"t": "故古人名嘉,字子孔。", "b": "许慎《说文解字》"}]}, {"meaning": "通达。", "cites": [{"t": "辟在西南,不当孔道。", "b": "《汉书·西域传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('180wx','队','1','duì','阝','4','','[{"pinyin": "duì", "defs": [{"meaning": "(形声。本义:从高处掉下来。是“坠”的本字)。"}, {"meaning": "坠落。", "cites": [{"t": "队,从高陨也。俗字作坠。", "b": "《说文》"}, {"t": "殷亩而驰不队。", "b": "《考工记·轮人》"}, {"t": "退人若将队诸渊。", "b": "《礼记·檀弓下》"}, {"t": "公(齐襄公)惧,队于车。", "b": "《左传·庄公八年》"}, {"t": "陈入城,板队而杀人。", "b": "《左传·襄公二十三年》"}]}, {"meaning": "失。", "cites": [{"t": "俾队其师。", "b": "《左传·僖公二十八年》"}, {"t": "敬不队命。", "b": "《国语·晋语》"}]}, {"meaning": "队列。", "cites": [{"t": "乃分其骑以为四队。", "b": "《史记·项羽本纪》"}, {"t": "车按行,骑就队。", "b": "司马相如《子虚赋》"}], "words": [{"w": "排队", "t": ""}, {"w": "纵队", "t": ""}, {"w": "横队", "t": ""}]}, {"meaning": "军队或集体的编制单位。", "cites": [{"t": "分为二队。", "b": "《左传·文公十六年》"}, {"t": "以成一队。", "b": "《左传·襄公六年》。注:“百人为队。”"}, {"t": "襄子疏队而击之。", "b": "《淮南子·齐俗》"}]}, {"meaning": "注:“二百人为一队。”。", "cites": [{"t": "曲队怪重。", "b": "《汉书·杨雄传》"}], "words": [{"w": "连队", "t": ""}, {"w": "舰队", "t": ""}, {"w": "球队", "t": ""}, {"w": "生产队", "t": ""}, {"w": "军队,部队", "t": ""}, {"w": "队主", "t": "一队之主。即队长。六朝时一队军队多由将帅带领。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('181wx','办','1','bàn','力','4','','[{"pinyin": "bàn", "defs": [{"meaning": "(形声。从力,辡声。力取致力之意。本义:办理;治理)。"}, {"meaning": "同本义。", "cites": [{"t": "办,致力也。", "b": "《说文新附》"}, {"t": "卿能办之者诚决。", "b": "《资治通鉴》"}], "words": [{"w": "办案", "t": ""}, {"w": "办事", "t": ""}, {"w": "办理", "t": ""}]}, {"meaning": "做,干。", "cites": [{"t": "吾已无事可办,惟待死期耳。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "怎么办", "t": ""}]}, {"meaning": "创设,经营,管理。", "cites": [{"t": "是年,谢庄办团。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "办工厂", "t": ""}, {"w": "办学校", "t": ""}, {"w": "办报", "t": ""}, {"w": "办卖", "t": "变卖。"}]}, {"meaning": "准备,操办。", "cites": [{"t": "船、粮、战具俱办。", "b": "《资治通鉴》"}], "words": [{"w": "办酒", "t": "备办酒席"}, {"w": "办丧事", "t": ""}]}, {"meaning": "惩罚。", "cites": [{"t": "君信可人,必能办贼者也。", "b": "《三国志·费祎传》"}], "words": [{"w": "办罪", "t": ""}, {"w": "严办", "t": ""}, {"w": "首恶必办", "t": ""}]}, {"meaning": "做成;做好;能做到。", "cites": [{"t": "食未为而景仁为玄所召。", "b": "《南史·谢裕传》"}, {"t": "趋为诸将军办装。", "b": "《后汉书·彭宠传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('182wx','以','1','yǐ','人','4','','[{"pinyin": "yǐ", "defs": [{"meaning": "(象形。甲骨文字形象。金文字形,象人。本义:用)。"}, {"meaning": "同本义。有一部分现已弱化成了介词。", "cites": [{"t": "以,用也。", "b": "《说文》"}, {"t": "以,用也。", "b": "《小尔雅》"}, {"t": "凡师能左右之曰以。", "b": "《左传·僖公二十六年》"}, {"t": "封疆社稷是以。", "b": "《左传·定公十年》"}, {"t": "纯以形式。", "b": "蔡元培《图画》"}, {"t": "如或知尔,则何以哉?", "b": "《论语》"}], "words": [{"w": "以手代足", "t": "爬行。表示甘愿认错受罚"}, {"w": "以疏间亲", "t": "关系疏远的人离间关系亲密的人"}, {"w": "以耳为目", "t": "把听到的当作亲眼目睹的"}, {"w": "以指测河", "t": "用手指测量河水的深浅。比喻达不到目的。"}]}, {"meaning": "使,令。", "cites": [{"t": "向欲以齐事王攻宋也。", "b": "《战国策》"}], "words": [{"w": "以彰其慢", "t": "公开过失"}, {"w": "以介眉寿", "t": "祝寿之词"}, {"w": "以夷攻夷", "t": "使夷人自相攻伐。"}]}, {"meaning": "凭借;仗恃。", "cites": [{"t": "富国以农,距敌恃卒。", "b": "《韩非子》"}]}, {"meaning": "认为,以为。", "cites": [{"t": "我以日始出。", "b": "《列子·汤问》"}], "words": [{"w": "以众暴寡", "t": "以人多势众的一帮去欺凌、迫害人少势弱的一方。"}]}, {"meaning": "做,从事。", "cites": [{"t": "教育事业最有意义,情愿终身以之的。", "b": "叶绍钧《倪焕之》"}]}, {"meaning": "原因,缘故。", "cites": [{"t": "何其久也?必有以也。", "b": "《诗·邶风》"}]}, {"meaning": "无固定职业的人。", "cites": [{"t": "以闲民。", "b": "《拾雅》"}, {"t": "候疆候以。", "b": "《诗·周颂》"}]}, {"meaning": "把,拿 ——表示对事物的处置。", "cites": [{"t": "俱以情告。", "b": "《世说新语·自新》"}, {"t": "以刀劈狼。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "以力服人", "t": "用强制的手段使人服从。"}]}, {"meaning": "依,按,凭 ——表示动作行为的凭借或前提。犹言凭、根据。", "cites": [{"t": "何以谓之文。", "b": "《论语》"}, {"t": "以残年余力。", "b": "《列子·汤问》"}, {"t": "以我酌油知之。", "b": "宋·欧阳修《归田录》"}, {"t": "以大中丞抚吴者。", "b": "明·张溥《五人墓碑记》"}, {"t": "以乡人子谒余。", "b": "明·宋濂《送东阳马生序》"}, {"t": "以其智力为也。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "以膺大统", "t": "继承帝位"}, {"w": "以天自诿", "t": "听天由命"}, {"w": "以时", "t": "按时;依时。"}]}, {"meaning": "在,于 ——表示行动的时间、处所或范围。", "cites": [{"t": "赏以春夏而刑以秋冬。", "b": "柳宗元《断刑论》"}, {"t": "以八月十三日斩于市。", "b": "清·梁启超《谭嗣同传》"}, {"t": "余以乾隆。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "从,自,由 ——表示行动或变化的起点。", "cites": [{"t": "自古于今,上以天子,下至庶人,蔑有好利而不仁者。", "b": "《潜夫论》"}, {"t": "今以长沙,豫章往,水道多,绝难行。", "b": "《史记》"}], "words": [{"w": "以下", "t": "下等;下层"}, {"w": "以下之人", "t": "下等人;奴婢"}, {"w": "以繁调简", "t": "清代府、州、县缺,有繁有简,分为最要、要、中、简四等。如山东是繁缺,安徽是简缺,从山东到安徽,是以繁调简"}, {"w": "以郄视文", "t": "从缝隙里看杂色文采。比喻见识浅陋狭隘。"}]}, {"meaning": "因为,由于 ——表示行为产生的原因。", "cites": [{"t": "以贪勤民。", "b": "《左传·僖公三十三年》"}, {"t": "吾以捕蛇独存。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "以其求思之深而无不在也。", "b": "宋·王安石《游褒禅山记》"}, {"t": "以中有足乐者,不知口体之奉不若人也。", "b": "明·宋濂《送东阳马生序》"}, {"t": "成以其小,劣之。", "b": "《聊斋志异·促织》"}, {"t": "汝以一念之贞,遇人仳离,致孤危托落。", "b": "清·袁枚《祭妹文》"}, {"t": "以数谏故。", "b": "《史记·陈涉世家》"}, {"t": "不以物喜,不以己悲。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "以致", "t": "表示由于上文所说的情况,引出了下文的结果"}, {"w": "以人废言", "t": "由于人不好,对其言论也加以否定"}, {"w": "以利累形", "t": "因追求利禄而危害身体"}, {"w": "以私害公", "t": "谓因私情而损害公道或公德"}, {"w": "以理去官", "t": "旧指官员因正常原因卸任"}, {"w": "以噎废食", "t": "由于吃饭打噎,便不敢再进食。比喻因偶然受到挫折。就停止应做的事情"}, {"w": "以辞害意", "t": "因拘泥于辞义而误会或曲解作者的原意。"}]}, {"meaning": "和,而 ——表示并列关系。", "cites": [{"t": "夷以近。", "b": "宋·王安石《游褒禅山记》"}, {"t": "载以来。", "b": "清·周容《芋老人传》"}, {"t": "一鸡瞥来,径进以啄。", "b": "《聊斋志异·促织》"}]}, {"meaning": "则,那么 ——表示条件关系。", "cites": [{"t": "战而不胜,以亡随其后。", "b": "《战国策》"}]}, {"meaning": "才。", "cites": [{"t": "思厥先祖父,暴霜露、斩荆棘,以有尺寸之地。", "b": "宋·苏洵《六国论》"}, {"t": "以至于寸。(才达到一寸。)", "b": "《后汉书·列女传》"}]}, {"meaning": "表目的或结果等。", "cites": [{"t": "智叟无以应。", "b": "《列子·汤问》"}]}, {"meaning": "用在单纯方位词或时间词之前,表示时间、方位、数量、质量、范围之类的界限。", "cites": [{"t": "日观以西峰。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "加在句中,表示语气的舒缓或调整节奏。", "cites": [{"t": "微我无酒,以敖以游。", "b": "《诗·邶风》"}]}, {"meaning": "加在句尾,不示肯定语气。", "cites": [{"t": "夫晴蛉其小者也,黄雀因是以。", "b": "《战国策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('183wx','允','1','yǔn','儿','4','','[{"pinyin": "yǔn", "defs": [{"meaning": "(会意。甲骨文字形,上为“以”(呂)字,下为“儿”(人)字。以是任用,用人不贰就是“允”。本义:诚信)。"}, {"meaning": "同本义。", "cites": [{"t": "允,信也。", "b": "《说文》"}, {"t": "允,信也;允,诚也。", "b": "《尔雅》"}, {"t": "众允。", "b": "《易·晋》"}, {"t": "允恭克让。", "b": "《书·尧典》"}, {"t": "允也天子。", "b": "《诗·商颂·长发》"}, {"t": "命汝作纳言,风夜出纳联命,惟允。", "b": "《方言》"}], "words": [{"w": "允元", "t": "信任仁厚之人"}, {"w": "允直", "t": "诚实正真"}, {"w": "允忠", "t": "忠信。"}]}, {"meaning": "公平。", "cites": [{"t": "祖父经,为郡县狱吏,案法平允,务存宽恕。", "b": "《后汉书》"}], "words": [{"w": "允正", "t": "允当平正"}, {"w": "允切", "t": "切当"}, {"w": "允衷", "t": "恰 当"}, {"w": "允情", "t": "合乎情理"}, {"w": "允帖", "t": "妥贴,妥当。"}]}, {"meaning": "答应,许可。", "cites": [{"t": "慰留不允。", "b": "清·张廷玉《明史》"}], "words": [{"w": "允帖", "t": "旧时男家向女家求婚,女家表示同意的帖子"}, {"w": "允从", "t": "允诺,依从。"}]}, {"meaning": "使人信服;受人敬重。", "cites": [{"t": "你吃我这杯酒,应允我的话,我才起来。", "b": "《儒林外史》"}], "words": [{"w": "允孚", "t": "得人心,使人信服"}, {"w": "允赖", "t": "信赖,依靠。"}]}, {"meaning": "用,使用。", "cites": [{"t": "允厘百工。", "b": "《书·尧典》"}]}, {"meaning": "确实,果真。", "cites": [{"t": "度其夕阳,豳居允荒。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "允袭", "t": "确实相合"}, {"w": "允臧", "t": "确实好;完善"}, {"w": "允迪", "t": "认真履践或遵循。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('184wx','予','1','yú yǔ','乛','4','','[{"pinyin": "yú", "defs": [{"meaning": "“予”假借为“余”,我。", "cites": [{"t": "予独爱莲之出淤泥而不染。", "b": "宋·周敦颐《爱莲说》"}, {"t": "然而累汝至此者,未尝非予之过也。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "予知", "t": "自认为聪明"}, {"w": "予美", "t": "自己所爱的人"}, {"w": "予圣", "t": "自以为圣人"}, {"w": "予一人", "t": "古代帝王的自称"}, {"w": "予小子", "t": "古代帝王对先王或长辈的自称;常人对先辈、长者的自称"}, {"w": "予末小子", "t": "予冲人,予冲子。古代帝王对先王或长辈的自称;常人对先辈、长者的自称"}, {"w": "予取予携", "t": "予取予夺。从我处掠取"}, {"w": "予违汝弼", "t": "古代天子勖勉大臣进谏之词。言我有过失,你应匡正"}, {"w": "予智予雄", "t": "自以为聪明和英雄;形容妄自尊大。"}]}]}, {"pinyin": "yǔ", "defs": [{"meaning": "(指事。象两手相与之形。本义:授予;给予)。"}, {"meaning": "同本义。", "cites": [{"t": "予,推予也。象相予之形,谓手拔。", "b": "《说文》"}, {"t": "予,与也。", "b": "《广雅》"}, {"t": "予之与夺也。", "b": "《淮南子·本经》"}, {"t": "君子来朝,何锡予之?", "b": "《诗·小雅·干旄》"}, {"t": "怒不过夺,喜不过予。", "b": "《荀子》"}], "words": [{"w": "予宁", "t": "给丧假"}, {"w": "予齿去角", "t": "天生动物赋予齿就不赋予角。比喻事物无十全十美"}, {"w": "予赐", "t": "予告和赐告"}, {"w": "予归", "t": "准予辞官回家"}, {"w": "予夺生杀", "t": "泛指帝王掌握的生死大权"}, {"w": "予决", "t": "给予决定或裁决。"}]}, {"meaning": "赞许,称誉。", "cites": [{"t": "主盛处贤,而自予雄也。", "b": "《管子·宙合》"}, {"t": "众必予之。", "b": "《管子·小匡》"}, {"t": "天下之人唯各特意哉,然而有所共予也。言味者予易牙,言音者予师旷。", "b": "《荀子·大略》"}]}, {"meaning": "出售,卖。", "cites": [{"t": "岁适美,则市粜无予。", "b": "《管子》"}, {"t": "岁孰取谷,予之丝漆;茧出,取帛絮,予之食。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('185wx','邓','1','dèng','阝','4','','[{"pinyin": "dèng", "defs": [{"meaning": "古国名。", "cites": [{"t": "邓,曼姓之国。今属南阳。从邑,登声。", "b": "《说文》"}]}, {"meaning": "在今河南省邓县。公元前678年为楚所灭。", "cites": [{"t": "邓侯吾离来朝。", "b": "《春秋·桓公七年》"}, {"t": "申吕应邓。", "b": "《国语·郑语》"}, {"t": "袭楚至邓。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "古地名。"}, {"meaning": "春秋蔡地,后属楚。在今河南省郾城县东南。", "cites": [{"t": "蔡侯郑伯会于邓。", "b": "《春秋·桓公二年》"}]}, {"meaning": "春秋鲁地。在今山东省汶河以南、运河以北地区(清兖州府境)。"}, {"meaning": "战国楚地,秦置邓县,是故邓侯国。在今湖北省襄樊市北。"}, {"meaning": "战国魏邑,在今河南省孟县西南。"}, {"meaning": "姓(邓通:西汉人,以自铸铜钱而成为巨富,后世常用此名比喻富有。邓禹:东汉新野人,字仲华。随汉光武刘秀作战,为东汉开国功臣。邓骘:人名,东汉安帝刘祜的舅父,封为上蔡侯,任大将军)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('186wx','劝','1','quàn','力','4','','[{"pinyin": "quàn", "defs": [{"meaning": "(形声。从力,雚(guàn)声。简化字中“又”仅是一个符号。本义:勉励)。"}, {"meaning": "同本义。", "cites": [{"t": "劝,勉也。", "b": "《说文》"}, {"t": "劝防之事。", "b": "《周礼·丧祝》。司农注:“劝防引柩也。”"}, {"t": "则楚之应之也,必劝。", "b": "《战国策·秦策》。注:“进也”。"}, {"t": "子文无后,何以劝善?", "b": "《左传·宣公四年》"}, {"t": "我戮之不祥,赦之以劝事君者。", "b": "《左传·成公二年》"}, {"t": "昔尧治天下,不赏而民劝。", "b": "《庄子·天地》"}, {"t": "各劝其业。", "b": "《史记·货殖列传》"}, {"t": "太公劝其女功。", "b": ""}, {"t": "所以劝之。", "b": "唐·韩愈《朱文昌校昌黎先生集》"}], "words": [{"w": "劝进", "t": "劝勉,策进"}, {"w": "劝蚕", "t": "勉励种桑养蚕"}, {"w": "劝戒", "t": "劝勉警戒"}, {"w": "劝相", "t": "劝助,劝勉"}, {"w": "劝掖", "t": "劝勉扶持"}, {"w": "劝督", "t": "劝勉督促"}, {"w": "劝奖", "t": "劝勉鼓励"}, {"w": "劝劳", "t": "劝慰;慰劳"}, {"w": "劝农", "t": "奖励农事"}, {"w": "劝慕", "t": "因受奖勉而有所企慕、向往,多指倾心向善"}, {"w": "劝惩", "t": "奖惩。"}]}, {"meaning": "劝说。", "cites": [{"t": "劝君更尽一杯酒。", "b": "唐·王维《送元二使安西》诗"}, {"t": "肃劝权召瑜还。", "b": "《资治通鉴》"}, {"t": "劝东游。", "b": "清·梁启超《谭嗣同传》"}, {"t": "劝君东游。", "b": ""}], "words": [{"w": "劝沮", "t": "劝阻"}, {"w": "劝酬", "t": "劝酒"}, {"w": "劝杯", "t": "劝人饮酒用的小酒杯"}, {"w": "劝盘", "t": "放劝杯用的盘子"}, {"w": "劝讽", "t": "婉言劝告"}, {"w": "劝导", "t": "规劝开导"}, {"w": "劝谏", "t": "劝说谏诤。"}]}, {"meaning": "勤勉;努力。", "cites": [{"t": "荆王大说,许救甚劝。", "b": "《战国策·宋策》"}], "words": [{"w": "劝赞", "t": "努力引见"}, {"w": "劝心", "t": "努力进取之心"}, {"w": "劝功", "t": "谓努力建功立业"}, {"w": "劝务", "t": "勤勉努力"}, {"w": "劝耕", "t": "努力耕种"}, {"w": "劝业", "t": "努力从事其事业。"}]}, {"meaning": "细看,看。", "cites": [{"t": "称德度功,劝其所能。", "b": "《管子·君臣下》"}]}, {"meaning": "喜乐。", "cites": [{"t": "以劝其心使犯其主。", "b": "《韩非子·八姦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('187wx','双','1','shuāng','又','4','','[{"pinyin": "shuāng", "defs": [{"meaning": "(会意。从雔,从又,持之。雔(chóu),两只鸟。又,手。本义:一对)。"}, {"meaning": "禽鸟二只。", "cites": [{"t": "雙,隹二枚也。", "b": "《说文》"}, {"t": "飞鸟曰双。", "b": "《方言六》"}, {"t": "其诸为其双双而俱至者与。", "b": "《公羊传·宣公五年》。正义:“双双之鸟,一身二首尾,有雌雄,随便而偶,常不离散。”"}, {"t": "中有双飞鸟,自名为鸳鸯。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "云南等地少数民族计算田亩的单位 。田广二亩、四亩、五亩都可称双,各从方俗;无定制。", "cites": [{"t": "官为田,四十双为二百亩。", "b": "《唐书》"}]}, {"meaning": "成双的,一对。", "cites": [{"t": "云有第三郎,窈窕世无双。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "厅旁一室,为吾与汝双栖之所。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "双人舞;举世无双;双红", "t": "双红帖。比单帖大一倍,从中折合,用红纸,故名"}, {"w": "双林(即沙罗双树,佛祖示寂(死亡)的地方", "t": ""}, {"w": "双阙", "t": "古代宫殿、宗庙与陵墓前左右各一个的高台楼观"}, {"w": "双套飞车", "t": "两头牲口拉的快车"}, {"w": "双骞", "t": "双飞"}, {"w": "双七", "t": "指农历七月七日"}, {"w": "双丸", "t": "指日和月"}, {"w": "双角", "t": "两角"}, {"w": "双杵", "t": "古人捣衣,对立执杵如舂米,故名双杵"}, {"w": "双枚", "t": "屋内的重檐"}, {"w": "双关儿透", "t": "很透彻"}, {"w": "双栖", "t": "指禽鸟雌雄同栖息。借喻夫妻形影不离"}, {"w": "双靥", "t": "脸的两颊"}, {"w": "双向沟通", "t": "指让意见沟通的双方均能有公平的机会,坦然地表达讯息的意义。"}]}, {"meaning": "偶,与“单”相对。", "cites": [{"t": "唐朝故事,只日视事,双日不坐。", "b": "《宋史·礼志》"}], "words": [{"w": "单日不着双日着", "t": "迟早有一天总会遇上。"}]}, {"meaning": "两个,一对。", "cites": [{"t": "凡献,执一双。", "b": "《仪礼·聘礼》"}, {"t": "客从远方来,遗我双鲤鱼。", "b": "古乐府《饮马长城窟行》"}], "words": [{"w": "一双鞋;一双短袜;三双手套;还要一双筷子;有一双灵丽的眼睛;一双脚", "t": ""}]}, {"meaning": "追随,跟从。", "cites": [{"t": "恶少爱众,天下双。", "b": "《文子·符言》"}]}, {"meaning": "匹敌。", "cites": [{"t": "至如信者,天下无双。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "双珠", "t": "兄弟俱美之称"}, {"w": "双凤", "t": "兄弟俱美,才智出众。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('188wx','书','1','shū','乛','4','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从聿,者声。聿(yù),即笔。隶书省“者”成“曰”。《说文》:“书,箸也。”箸(著)即显明。合起来表示用笔使文字显明,“者、箸”音近,故“者”有表意作用。本义:书写,记录,记载)。"}, {"meaning": "同本义。", "cites": [{"t": "書,著也。", "b": "《说文》。按说文序云:“著于竹帛谓之书。”"}, {"t": "五曰六书。", "b": "《周礼·保氏》"}, {"t": "作书。上古以刀录于竹若木,中古以漆画于帛,后世以墨写于纸。", "b": "朱骏声《说文通训定声》"}, {"t": "易之以书契。", "b": "《易·系辞》"}, {"t": "书者,以笔画记之辞。", "b": "《尚书序》疏"}, {"t": "子张书诸绅。", "b": "《论语·卫灵公》"}, {"t": "乃丹书帛曰:“陈胜王”,置人所罾鱼腹中。", "b": "《史记·陈涉世家》"}, {"t": "大书一“屈”字,以两竿夹揭之,走诉行御史台。", "b": "明·高启《书博鸡者事》"}, {"t": "众言同,于是乎书。", "b": "方苞《狱中杂记》"}], "words": [{"w": "书候", "t": "写信问候"}, {"w": "书孽", "t": "记载罪恶"}, {"w": "书记手", "t": "担任抄写文书等的书吏"}, {"w": "书画卯酉", "t": "上下班"}, {"w": "书文", "t": "撰文并书写"}, {"w": "书抄", "t": "指手抄本"}, {"w": "书具", "t": "书写工具,文具"}, {"w": "书券", "t": "书写契约"}, {"w": "书砚", "t": "砚台"}, {"w": "书狱", "t": "书写狱词"}, {"w": "书命", "t": "书写诏书、命令"}, {"w": "书格", "t": "一种文具,书写时用以支臂,使腕压着纸,以防墨污"}, {"w": "书帖", "t": "书写简贴。"}]}, {"meaning": "画。", "cites": [{"t": "今大将军问事,但令我书可邪?", "b": "《资治通鉴》。胡三省注:“书可,画可也。”"}]}, {"meaning": "书籍,装订成册的著作。", "cites": [{"t": "书,凡载籍谓之书。", "b": "《正字通》"}, {"t": "申子、韩子皆著书。", "b": "《史记·韩非列传》"}, {"t": "何必读书,然后为学?", "b": "《论语·先进》"}, {"t": "书者,五经六籍总名也。", "b": "《史记·礼书》李隐"}, {"t": "黄生允修借书。随园主人授之书而告之曰。", "b": "清·袁枚《黄生借书说》"}, {"t": "家贫,无从致书以观,每假借于藏书之家。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "史书", "t": "历史书"}, {"w": "图书", "t": "图和书。泛指书籍"}, {"w": "书客", "t": "卖书籍、文具的商贩"}, {"w": "书香之族", "t": "世代读书的家庭"}, {"w": "书香一脉", "t": "知书达理的家风"}, {"w": "书包翻身", "t": "指穷读书人发迹"}, {"w": "书谜儿", "t": "将书中的话作成的谜语"}, {"w": "书帕", "t": "礼金。明代官场习惯用书籍、手帕作礼物,称书帕"}, {"w": "书剑", "t": "书和剑。古代文人随身携带之物。后亦指文人生涯"}, {"w": "书笈", "t": "小书箱"}, {"w": "书仪", "t": "托名买书而馈赠的礼金"}, {"w": "书腐", "t": "蛀书虫。喻指迂腐的文人"}, {"w": "书心儿", "t": "一部书中最精采的章节"}, {"w": "书劫", "t": "书籍的劫难"}, {"w": "书会", "t": "宋元时戏曲作者、说话人共同组织的社团"}, {"w": "书呆", "t": "只知啃书本的人"}, {"w": "书城", "t": "书籍环列如城,言其多"}, {"w": "书脑", "t": "书籍装订时打眼穿线的部分"}, {"w": "书阁", "t": "收藏书籍的地方"}, {"w": "书录", "t": "图书目录"}, {"w": "书囊", "t": "盛书籍的袋子。"}]}, {"meaning": "信件,信函。", "cites": [{"t": "烽火连三月,家书抵万金。", "b": "杜甫《春望》"}, {"t": "一男附书至,二男新战死。", "b": "唐·杜甫《石壕吏》"}, {"t": "诸人徒见操书言水步八十万而各恐慑,不复料其虚实,便开此议,甚无谓也。", "b": "《资治通鉴》"}], "words": [{"w": "书介", "t": "传达书信的使人"}, {"w": "书尾", "t": "书信、信函的末尾"}, {"w": "书呈", "t": "亦作“书程”。给上司或长辈写的信,信函"}, {"w": "书字", "t": "书信"}, {"w": "书办", "t": "管办文书的官吏"}, {"w": "书启师爷", "t": "管文书的幕友"}, {"w": "书役", "t": "管理文书的小吏"}, {"w": "书尺", "t": "尺牍,书信"}, {"w": "书素", "t": "书信"}, {"w": "书筒", "t": "古代盛书信的筒。亦指书信"}, {"w": "书题", "t": "指书信"}, {"w": "书缄", "t": "书信。"}]}, {"meaning": "奏章;文书,文件。", "cites": [{"t": "上书谏寡人者,受中赏。", "b": "《战国策·齐策》"}, {"t": "先生有所陈奏,则著之于所进呈书之中而已。", "b": "清·梁启超《谭嗣同传》"}, {"t": "军书十二卷,卷卷有爷名。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "证书;保证书;说明书;书可", "t": "批阅公文,书字认可"}, {"w": "书禀", "t": "文书"}, {"w": "书文", "t": "文书"}, {"w": "书府", "t": "收藏文书图籍的府库"}, {"w": "书佐", "t": "主办文书的佐吏"}, {"w": "书办", "t": "管办文书的属吏。"}]}, {"meaning": "书法。", "cites": [{"t": "悦亲戚之情话,乐琴书以消忧。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "学书费纸,犹胜饮酒费钱。", "b": "欧阳修《学书费纸》"}], "words": [{"w": "楷书;隶书;书判", "t": "判别书法与文章的优劣"}, {"w": "书圣", "t": "指造诣最高的书法家"}, {"w": "书意", "t": "书法的神髓"}, {"w": "书品", "t": "评论书法优劣的书;书法的风格造诣"}, {"w": "书格", "t": "书法的风格。"}]}, {"meaning": "《尚书》的简称。", "cites": [{"t": "《书》不云乎?“好问则裕。”", "b": "清·刘开《问说》"}, {"t": "《书》曰:“满招损,谦得益。”", "b": "宋·欧阳修《新五代史·伶官传·序》"}, {"t": "庞涓果夜至斫木下,见白书。", "b": "《史记·孙子吴起列传》"}, {"t": "吾妻来归,时至轩中,从余问古事,或凭几学书。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "文字。", "cites": [{"t": "怀中一方板,板上数行书。", "b": "李贺《感讽》"}]}, {"meaning": "又如：书理(即文理。文辞之义理与脉络);书士(从事文字、文书工作的人员);书轨(指国中所用文字与车轨);书计(文字与筹算)。"}, {"meaning": "指“六书”,即中国古代分析文字的理论。", "cites": [{"t": "十年,出就外傅,居宿于外,学书计。", "b": "《礼记》。孙希旦集解:书、计,即六艺中六书、九数之学也。"}]}, {"meaning": "古代皇帝的诏书。", "cites": [{"t": "今以一郡一国之众,对无应书者,是王道往往而绝也。", "b": "《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('189wx','幻','1','huàn','幺','4','','[{"pinyin": "huàn", "defs": [{"meaning": "惑乱。", "cites": [{"t": "幻,相诈惑也。", "b": "《说文》"}, {"t": "民无或胥,诪张为幻。", "b": "《书·无逸》"}], "words": [{"w": "幻惑", "t": "迷惑。"}]}, {"meaning": "假象;虚幻,虚无。", "cites": [{"t": "皆幻也。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "幻者而同于真。", "b": ""}, {"t": "真者而同于幻。", "b": ""}], "words": [{"w": "幻魄", "t": "虚无的阴魂"}, {"w": "幻尘", "t": "佛教用语。指虚幻的人世"}, {"w": "幻泡", "t": "梦幻泡影的简称"}, {"w": "幻世", "t": "虚幻无常的人世。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('190wx','玉','1','yù','玉','5','','[{"pinyin": "yù", "defs": [{"meaning": "(象形。甲骨文字形。象一根绳子,串着一些玉石。“玉”是汉字的一个部首。本义:温润而有光泽的美石)。"}, {"meaning": "同本义。", "cites": [{"t": "玉,石之美者,有五德,润泽以温,仁之方也…", "b": "《说文》"}, {"t": "君无故玉不去身。", "b": "《礼记·曲记》。疏:“玉谓佩也。”"}, {"t": "五玉。", "b": "《虞书》。郑注:“执之曰瑞,陈列曰玉。”"}, {"t": "王齐则共食玉。", "b": "《周礼·王府》"}, {"t": "惟辟玉食。", "b": "《书·洪范》"}, {"t": "牺牲玉帛,弗敢加也,必以信。", "b": "《左传》"}], "words": [{"w": "玉情儿", "t": "玉石的质量、成色"}, {"w": "玉墀", "t": "白玉台阶"}, {"w": "玉阙", "t": "宝座;皇宫"}, {"w": "玉虚", "t": "道教指玉帝的居处"}, {"w": "玉树", "t": "指槐树"}, {"w": "玉砚", "t": "玉石制的砚台"}, {"w": "玉雕", "t": "玉石雕成的工艺品"}, {"w": "玉栏", "t": "玉石制的栏杆。"}]}, {"meaning": "指玉制的乐器。", "cites": [{"t": "集大成也者,金声而玉振之也。", "b": "《孟子》"}], "words": [{"w": "玉徽", "t": "美玉装饰的琴"}, {"w": "玉轸", "t": "琴上的玉制弦柱"}, {"w": "玉振金声", "t": "演奏古乐,以钟发声,以罄收韵,集众音之大成。金指钟,玉指罄。"}]}, {"meaning": "比喻美德、贤才。", "cites": [{"t": "君子比德如玉。", "b": "《礼记》"}], "words": [{"w": "玉笋之班", "t": "人材行列。唐末朝士风貌优异有才华的人,称玉笋。得与其列者称玉笋班"}, {"w": "玉堂金马", "t": "指翰林出身;亦指出身高贵,文武双全"}, {"w": "玉堂", "t": "翰林院"}, {"w": "玉音", "t": "帝王的话语。"}]}, {"meaning": "敬辞。多用以尊称对方的身体言行等。", "cites": [{"t": "而恐太后玉体之有所郄也。", "b": "《战国策》"}, {"t": "马嵬坡下泥土中,不见玉颜空死处。", "b": "白居易《长恨歌》"}], "words": [{"w": "玉文", "t": "对文字的美称"}, {"w": "玉面", "t": "尊称人的容颜"}, {"w": "玉札", "t": "对别人书信的敬称"}, {"w": "玉躬", "t": "玉体"}, {"w": "玉声", "t": "对他人言语的敬称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('191wx','刊','1','kān','刂','5','','[{"pinyin": "kān", "defs": [{"meaning": "(形声。从刀,干声。本义:砍,砍削)。"}, {"meaning": "同本义。", "cites": [{"t": "刊,剟也。", "b": "《说文》"}, {"t": "刊,削也。", "b": "《广雅》"}, {"t": "刊阳木而火之。", "b": "《周礼·柞氏夏日至令》。注:“谓斫去次地之皮。”"}, {"t": "刊其柄与末。", "b": "《礼记·杂记》。注:“犹削也。”"}, {"t": "随山刊木。", "b": "《书·益稷》"}], "words": [{"w": "刊山", "t": "砍伐山上树木"}, {"w": "刊木", "t": "砍伐树木"}, {"w": "刊薙", "t": "砍伐割除草木。"}]}, {"meaning": "删除。", "cites": [{"t": "诚不刊之典。", "b": "晁公武《郡斋读书志》"}], "words": [{"w": "刊落", "t": "删去冗赘多余的文字"}, {"w": "刊削", "t": "削除"}, {"w": "刊删", "t": "删改"}, {"w": "刊革", "t": "删改"}, {"w": "刊除", "t": "削除。"}]}, {"meaning": "刻;雕刻。", "cites": [{"t": "刊石作铭。", "b": "蔡邕《陈寔碑》"}, {"t": "重木刊凿之。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "刊刻", "t": "雕刻"}, {"w": "刊人", "t": "刻版工人"}, {"w": "刊石", "t": "镌刻在石上,以便长久保存"}, {"w": "刊立", "t": "刻石立碑"}, {"w": "刊版", "t": "刻版或排版"}, {"w": "刊刷", "t": "刊刻印刷"}, {"w": "刊书", "t": "刻印书籍"}, {"w": "刊成板", "t": "定例"}, {"w": "刊勒", "t": "雕刻碑文。"}]}, {"meaning": "", "cites": [{"t": "抗木刊。", "b": "《仪礼·既夕礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('192wx','未','1','wèi','木','5','','[{"pinyin": "wèi", "defs": [{"meaning": "(象形。基本义:没有;不。“未”字否定过去,不否定将来,与“不”有别。但有时候也当“不”字讲)。"}, {"meaning": "相当于“没有”、“不曾”、“尚未”。", "cites": [{"t": "未,无也。", "b": "《小尔雅·广诂》"}, {"t": "未由也已。", "b": "《论语·子罕》"}, {"t": "未之难矣。", "b": "《论语·宪问》"}, {"t": "吾与郑人未有成也。", "b": "《公羊传·隐公六年》"}, {"t": "吾未有言之。", "b": "《吕氏春秋·开春》"}, {"t": "未果。", "b": "晋·陶渊明《桃花源记》"}, {"t": "有孙母未去。", "b": "唐·杜甫《石壕吏》"}, {"t": "未百步则返。", "b": "明·袁宏道《满井游记》"}, {"t": "将舒未舒。", "b": ""}], "words": [{"w": "未际", "t": "未发迹"}, {"w": "未的", "t": "未必,不一定"}, {"w": "未从", "t": "未曾,尚未"}, {"w": "未傅", "t": "未成年的人"}, {"w": "未遑", "t": "来不及,没有闲暇"}, {"w": "未遇", "t": "未得到赏识和重用;未发迹"}, {"w": "未宾", "t": "没有归顺"}, {"w": "未集", "t": "未能完成"}, {"w": "未臻", "t": "未到圆满的地步"}, {"w": "未极", "t": "无穷远处;未到尽头;没有停止"}, {"w": "未意之志", "t": "没有完成的志向"}, {"w": "未第", "t": "科举考试中未中"}, {"w": "未萌", "t": "事情发生之前。"}]}, {"meaning": "(“未”字否定过去,“不”字否定将来,但有时候未也当不讲)不。", "cites": [{"t": "众宾未拾取矢。", "b": "《仪礼·乡射礼》。注:“未,犹不也。”"}, {"t": "未若复吾赋不幸。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "未为简易。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "游人虽未盛。", "b": "明·袁宏道《满井游记》"}, {"t": "犹未能也。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "未消", "t": "不必,不要"}, {"w": "未一", "t": "不再一一去详细叙述"}, {"w": "未敢苟同;未知可否;未审", "t": "不知"}, {"w": "未的", "t": "不确实,不确切"}, {"w": "未足", "t": "不足,不能"}, {"w": "未如", "t": "不如"}, {"w": "未妨", "t": "不妨"}, {"w": "未若", "t": "不如"}, {"w": "未孚", "t": "不算大信,不是至诚"}, {"w": "未足轻重", "t": "无关紧要,不值得重视"}, {"w": "未应", "t": "不曾,不须"}, {"w": "未为不可", "t": "不是不可以"}, {"w": "未逮", "t": "不及;没有达到。"}]}, {"meaning": "否 ——用在句末,表示疑问。", "cites": [{"t": "来日绮窗前,寒梅著花未?", "b": "王维《杂诗》"}]}, {"meaning": "滋味", "cites": [{"t": "未,味也。六月滋味也。五行,木老于未,象木重枝叶也。", "b": "《说文》"}]}, {"meaning": "地支的第八。", "cites": [{"t": "未还于此。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "与天干相配,用以纪年。如1967年为农历丁未年。"}, {"meaning": "用以纪月,即农历六月。"}, {"meaning": "用以纪时,叫“未刻”。即午后十三时至十五时。", "cites": [{"t": "两马相交,斗了一百余合,自从辰牌直杀到未刻。", "b": "《英烈传》"}]}, {"meaning": "五行属土。", "cites": [{"t": "丑、未,亦土也。", "b": "《论衡》"}]}, {"meaning": "十二生肖属羊。", "cites": [{"t": "未禽羊。", "b": "《论衡》"}]}, {"meaning": "将来。", "cites": [{"t": "凡刑人之本,禁暴恶恶,且征其未也。", "b": "《荀子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('193wx','末','1','mò','木','5','','[{"pinyin": "mò", "defs": [{"meaning": "(指事。金文字形。“木”上加一点,指明树木末梢所在处。本义:树梢)。"}, {"meaning": "同本义。", "cites": [{"t": "末,木上曰末。", "b": "《说文》"}, {"t": "不揣其本,而齐其末。", "b": "《孟子》"}, {"t": "末有十日,其华照下地。", "b": "《淮南子·地形》"}, {"t": "末大必折。", "b": "《左传·哀公十一年》"}], "words": [{"w": "末大", "t": "树木枝端粗大。喻部属势力强大"}, {"w": "末大必折", "t": "树木枝端粗大,必折其干。喻下属权重,危及上级"}, {"w": "末杪", "t": "末尾"}, {"w": "末梢", "t": "末尾;最后。"}]}, {"meaning": "泛指物的末端、末尾。", "cites": [{"t": "元首末要。", "b": "《周书·武顺》"}, {"t": "风淫末疾。", "b": "《左传·昭公元年》。注:“四肢也。”"}, {"t": "明足以察秋毫之末。", "b": "《孟子·梁惠王上》"}, {"t": "譬若锥之处囊中,其末立见。", "b": "《史记·平原君虞卿列传》"}, {"t": "非特其末见而已。", "b": ""}, {"t": "强弩之末。", "b": "《资治通鉴》"}, {"t": "左手执卷末。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "末大不掉", "t": "犹尾大不掉。比喻部属势力强大,难以驾驭"}, {"w": "末岁", "t": "岁末"}, {"w": "末冬", "t": "冬末"}, {"w": "末秋", "t": "秋末"}, {"w": "末春", "t": "春末。"}]}, {"meaning": "古代称农为本,反本为末,即工商业。", "cites": [{"t": "末技游食之民。", "b": "汉·贾谊《论积贮疏》。注:(末伎。古指工商业不值得重视的技能,游食,不劳而食)"}], "words": [{"w": "末民", "t": "古称从事工商业的人"}, {"w": "末产", "t": "手工业、商业"}, {"w": "末作", "t": "古代指工商业"}, {"w": "末利", "t": "古代指工商业"}, {"w": "末生", "t": "末业。指工商业。"}]}, {"meaning": "传统戏曲角色名。主要扮演中年男子。", "cites": [{"t": "杂剧有正末、副末之名。", "b": "焦循《剧说》"}]}, {"meaning": "末期;晚年。", "cites": [{"t": "武王末受命。", "b": "《礼记·中庸》"}, {"t": "申末酉初。", "b": "《广东军务记》"}, {"t": "崇祯末。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "末尾三梢", "t": "收场,结局"}, {"w": "物有本末,事有终始;他三月末回来;末限", "t": "最后期限"}, {"w": "末垂", "t": "最后的时日。"}]}, {"meaning": "细的粉末。", "cites": [{"t": "丝末。", "b": "《荀子·礼论》"}], "words": [{"w": "茶叶末;粉笔末;面色末;药末", "t": ""}]}, {"meaning": "蓋在车轼上遮蔽风尘的帷席。", "cites": [{"t": "寝兕、持虎、蛟韅、丝末、弥龙,所以养威也。", "b": "《荀子·礼论》"}]}, {"meaning": "卑微。", "cites": [{"t": "志末也。", "b": "《后汉书·象上传》"}], "words": [{"w": "末志", "t": "卑微的志向"}, {"w": "末臣", "t": "地位低贱之臣"}, {"w": "末官", "t": "卑小的官"}, {"w": "末陋", "t": "卑微鄙陋"}, {"w": "末位", "t": "卑微的职位"}, {"w": "末皂", "t": "卑贱的隶役"}, {"w": "末品", "t": "卑官。"}]}, {"meaning": "低级。", "cites": [{"t": "末流。", "b": "《后汉书·班彪传》。注:“犹下流也。”"}], "words": [{"w": "末弁", "t": "低级武官"}, {"w": "末列", "t": "犹下位。多用作谦词"}, {"w": "末底", "t": "最底下"}, {"w": "末俗", "t": "末世的习俗,低下的习俗。"}]}, {"meaning": "微不足道。", "cites": [{"t": "末之卜也。", "b": "《礼记·檀弓》。注:“微也。”"}], "words": [{"w": "末事", "t": "微不足道的小事"}, {"w": "末行", "t": "微不足道的行为"}, {"w": "末用", "t": "无足轻重之物"}, {"w": "末务", "t": "小事,无关紧要的事"}, {"w": "末务", "t": "小事,无关紧要的事。"}]}, {"meaning": "细,小。", "cites": [{"t": "浅智之所争,则末矣。", "b": "《吕氏春秋·精喻》"}], "words": [{"w": "末务", "t": "小事,无关紧要的事"}, {"w": "末操", "t": "小节"}, {"w": "末派", "t": "水的支流或下游。"}]}, {"meaning": "肤浅。", "cites": [{"t": "末学肤受。", "b": "张衡《东京赋》"}], "words": [{"w": "末学", "t": "浅薄的学者;肤浅无本之学"}, {"w": "末议", "t": "谦称自己的议论或意见"}, {"w": "末说", "t": "肤浅无本之说。"}]}, {"meaning": "抹拭。", "cites": [{"t": "三数叔鱼之恶,不为末减。", "b": "《左传·昭公十四年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('194wx','示','1','shì','示','5','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。小篆字形,“二”是古文“上”字,三竖代表日月星。甲骨文本作“T”,象祭台形。“示”是汉字的一个部首,其义多与祭祀、礼仪有关。本读(qí)。本义:地神。引申义:让人看,显示)。"}, {"meaning": "显现;表示。", "cites": [{"t": "示,现也。", "b": "《华严经音义》"}, {"t": "天垂象见吉凶所以示人也。", "b": "《说文》。古文三垂,日月星也。观乎天文以察时变,示神事也。"}, {"t": "示,现也。", "b": "《苍颉篇》"}, {"t": "武王示之病。", "b": "《战国策·秦策》"}, {"t": "穷不得所示。", "b": "《楚辞·怀沙》"}, {"t": "王不行,示赵弱且怯也。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "斩使以示威。", "b": "《三国演义》"}, {"t": "二子心计,公无从办,特示故人意耳。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "示像", "t": "显露外形"}, {"w": "示疾", "t": "佛教语。佛菩萨及高僧得病"}, {"w": "示现", "t": "菩萨应机缘而现种种化身"}, {"w": "示贬于褒", "t": "寓批评于表扬"}, {"w": "示重", "t": "表示器重"}, {"w": "示问", "t": "指表示问候的简札书启之类"}, {"w": "示俭", "t": "表现节俭"}, {"w": "示优", "t": "表示优厚"}, {"w": "示惩", "t": "表示惩戒"}, {"w": "示怀", "t": "表示恩德"}, {"w": "示导", "t": "启示开导"}, {"w": "示诲", "t": "开导教诲。"}]}, {"meaning": "指示;让人看;把事物摆出来或指出来让人知道。", "cites": [{"t": "示,语也,以事告人曰示也。", "b": "《玉篇》"}, {"t": "示,垂示。", "b": "《广韵》"}, {"t": "示我周行。", "b": "《诗·小雅·鹿鸣》"}, {"t": "言示之事。", "b": "《诗·大雅·抑》"}, {"t": "则不能毋举物示之乎?", "b": "《墨子·尚贤下》"}, {"t": "国之利器不可以示人。", "b": "《老子》"}, {"t": "袒而示之背。", "b": "《左传·庄公八年》"}, {"t": "召桑田巫,示而杀之。", "b": "《左传·成公十年》"}, {"t": "璧有瑕,请指示王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "权以示群下,莫不响震失色。", "b": "《资治通鉴》"}, {"t": "归以示成。", "b": "《聊斋志异·促织》"}], "words": [{"w": "示仰", "t": "指示;传达"}, {"w": "示梦", "t": "灵魂在梦中以事示人"}, {"w": "示下", "t": "指示"}, {"w": "示导", "t": "启示开导"}, {"w": "示众", "t": "给大家看,特指当众惩罚人"}, {"w": "示及", "t": "见示、谈到"}, {"w": "示化", "t": "启示化导"}, {"w": "示世", "t": "昭示于世人"}, {"w": "示唆", "t": "启示"}, {"w": "示覆", "t": "书牍中请对方作答之用语"}, {"w": "示知", "t": "信函用语。告知"}, {"w": "示谕", "t": "告知;晓示。"}]}, {"meaning": "暗示;示意解释。", "cites": [{"t": "范增数目项王,举所佩玉玦以示之者三。", "b": "《史记·项羽本纪》"}]}, {"meaning": "公文,告示。", "cites": [{"t": "那看的人虽如人山人海,好在国王久已出示,毋许驱逐闲人,悉听庶民瞻仰。", "b": "《镜花缘》"}]}, {"meaning": "泛指命令、指示。", "cites": [{"t": "戏子们请老爷的示:还是伺候,还是回去?", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('195wx','击','1','jī','凵','5','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从手,毄(jī)声。本义:敲击,敲打)。"}, {"meaning": "同本义。", "cites": [{"t": "欲以击柱。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "不肯击缻。", "b": ""}, {"t": "留击柝者。", "b": "《资治通鉴·唐纪》"}, {"t": "使击柝如故。", "b": ""}, {"t": "援玉 枹兮击鸣鼓。", "b": "《楚辞·九歌·国殇》"}], "words": [{"w": "击壤", "t": "相传尧时有老人击壤而歌曰:“日出而作,日入而息,凿井而饮,耕田而食,率力于我何有哉?后因以比喻太平盛世"}, {"w": "击节", "t": "打拍子"}, {"w": "击鞠", "t": "击皮球。"}]}, {"meaning": "攻击;攻打。", "cites": [{"t": "而诸侯敢救者,已拔赵,必移兵击之。", "b": "《史记·魏公子列传》"}], "words": [{"w": "击排", "t": "攻击排斥"}, {"w": "击排冒没", "t": "攻击排斥,轻率而不顾一切"}, {"w": "击床", "t": "击杀于床上。"}]}, {"meaning": "碰撞;接触。", "cites": [{"t": "齐吴傍以击汰。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "击毂摩肩", "t": "车碰轮,人摩肩。比喻拥挤,热闹"}, {"w": "击冲", "t": "撞击"}, {"w": "撞击", "t": "运动体与别的物体猛然碰上。"}]}, {"meaning": "杀;搏杀。", "cites": [{"t": "入水击蛟。", "b": "《世说新语·自新》"}, {"t": "数击杀响马贼。", "b": "明·魏禧《大铁椎传》"}, {"t": "客奋椎左右击。", "b": ""}, {"t": "猱进鸷击。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "击斩", "t": "斩杀"}, {"w": "击鲜", "t": "宰杀活的牲畜禽鱼,充作美食。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('196wx','打','1','dǎ dá','扌','5','','[{"pinyin": "dǎ", "defs": [{"meaning": "(形声。从手,丁声。本义:击)。"}, {"meaning": "同本义。", "cites": [{"t": "打,击也。", "b": "《说文新附》"}, {"t": "身世浮沉雨打萍。", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "用棍打狗;打拍", "t": "敲击"}, {"w": "打火刀", "t": "用来敲打火石的刀形铁片。"}]}, {"meaning": "往;去。", "cites": [{"t": "你打华州,须从这条路走。", "b": "《水浒传》"}]}, {"meaning": "制造;建造。", "cites": [{"t": "九子不葬父,一女找荆棺。", "b": "《荆棺峡谵》"}], "words": [{"w": "打船", "t": "造船。"}]}, {"meaning": "砍;割。", "cites": [{"t": "只在左近人家佣工,替人家挑土打柴。", "b": "《儒林外史》"}]}, {"meaning": "除去。", "cites": [{"t": "风流总被雨打风吹去。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}]}, {"meaning": "又如:打麦(用工具使麦子去皮或脱粒);打灭(打消;消除;消灭)。"}, {"meaning": "摇荡。", "cites": [{"t": "西江水阔吴山远,却打船头向北行。", "b": "王建《扬州寻张籍不见》"}]}, {"meaning": "武术 。如:教打;练打。亦指京剧里指武打。如:唱、做、念、打。"}]}, {"pinyin": "dá", "defs": [{"meaning": "量词，指十二个", "words": [{"w": "一打火柴", "t": ""}, {"w": "一打鸡蛋", "t": ""}, {"w": "一打铅笔", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('197wx','巧','1','qiǎo','工','5','','[{"pinyin": "qiǎo", "defs": [{"meaning": "(形声。从工,丂(kǎo)声。“工”有精密、灵巧义。本义:技艺高明、精巧)。"}, {"meaning": "同本义。", "cites": [{"t": "巧,技也。", "b": "《说文》"}, {"t": "利于人,谓之巧。", "b": "《墨子·贵义》"}, {"t": "刻雕众形,而不为巧。", "b": "《庄子·天道》"}, {"t": "工人巧士。", "b": "马融《长笛赋》"}, {"t": "明有奇巧人曰王叔远。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "巧思", "t": "精巧的构思、设计"}, {"w": "巧工", "t": "技艺高超的工匠"}, {"w": "巧任", "t": "技巧,技能"}, {"w": "精巧;工巧", "t": "能很快发明的创造力量和品质"}, {"w": "巧夺天孙", "t": "比喻比织女更巧"}, {"w": "巧舌", "t": "灵巧的舌头"}, {"w": "巧便", "t": "灵便;灵巧"}, {"w": "小巧", "t": "小而灵巧"}, {"w": "手巧", "t": "手灵巧,手艺高。"}]}, {"meaning": "巧妙;精妙。", "cites": [{"t": "巧者有余。", "b": "《史记·货殖列传》"}, {"t": "牙机巧制。", "b": "《后汉书·张衡传》"}, {"t": "明有奇巧人曰王叔远。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "巧招", "t": "巧妙的计策或手段"}, {"w": "巧劲", "t": "巧妙的手法"}, {"w": "巧法", "t": "巧妙的方法。"}]}, {"meaning": "美好;美丽。", "cites": [{"t": "巧言如流。", "b": "《诗·小雅·雨无止》。笺:“犹善也。”"}, {"t": "为奇巧声。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "巧笑", "t": "美好的笑容"}, {"w": "巧丽", "t": "美妙华丽"}, {"w": "巧媚", "t": "形容姿态美好"}, {"w": "巧地方", "t": ""}]}, {"meaning": "虚浮不实,伪诈。", "cites": [{"t": "余犹恶其佻巧。", "b": "《离骚》。注:“利也。”"}, {"t": "毋或作为淫巧。", "b": "《礼记·月令》。注:“谓奢伪怪好也。”"}, {"t": "对人前巧语花言。", "b": "王实甫《西厢记》"}, {"t": "绝巧弃利。", "b": "《老子》。注:“诈伪乱真也。”"}, {"t": "险极巧极。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "巧语虚言", "t": "花言巧语"}, {"w": "巧说", "t": "用花言巧语欺骗人"}, {"w": "巧言", "t": "表面上好听而实际上虚伪的话"}, {"w": "巧佞", "t": "奸诈机巧"}, {"w": "巧故", "t": "伪诈。"}]}, {"meaning": "技巧。", "cites": [{"t": "医能治一病谓之巧。", "b": "《论衡·别通》"}, {"t": "有常仪的,则羿、逢蒙以五寸为巧。", "b": "《韩非子·外储说左上》"}, {"t": "虽尽力于巧,极盛于寿。", "b": "《韩非子·大体》"}, {"t": "释规而任巧,释法而任智。", "b": "《韩非子·饰邪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('198wx','正','1','zhēng zhèng','止','5','','[{"pinyin": "zhēng", "defs": [{"meaning": "农历一年的第一个月。", "cites": [{"t": "正,岁之首月,夏以建寅月为正,殷以建丑月为正,周以建子月为正。", "b": "《集韵·清韵》"}]}, {"meaning": "箭靶的中心。", "cites": [{"t": "终日射候,不出正兮。", "b": "《诗·齐风·猗嗟》"}]}, {"meaning": "引申为目标。", "cites": [{"t": "刑(形)名已立,声号已建,则无所逃迹若正匿。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": ""}, {"meaning": "征税。", "cites": [{"t": "正其货贿。", "b": "《周礼·地官·司门》。郑注:“正,读为征。”"}, {"t": "唯加田无国正。", "b": "《周礼·夏官·司勋》"}, {"t": "谨正盐筴。", "b": "《管子·海王》。李哲明云:“正,税也,正、征古字通用。”"}]}, {"meaning": "出兵,征讨。", "cites": [{"t": "予畏上帝不敢不正。", "b": "《书·汤誓》"}, {"t": "故诸侯服而无正。", "b": "《管子·山至数》"}, {"t": "司马弗正。", "b": "《礼记·燕义》"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "(指事。甲骨文字形,上面的符号表示方向、目标,下面是足(止),意思是向这个方位或目标不偏不斜地走去。本义:不偏斜,平正)。"}, {"meaning": "同本义。", "cites": [{"t": "席不正不坐。", "b": "《论语·乡党》"}, {"t": "有绳不以正。", "b": "《吕氏春秋·君守》。注:“正,直也。”"}, {"t": "稍稍正坐。", "b": "《虞初新志·秋声诗自序》"}, {"t": "泰山正南。", "b": "清·姚鼐《登泰山记》"}, {"t": "正则无景。", "b": "清·龚自珍《病梅馆记》"}, {"t": "斫其正。", "b": ""}], "words": [{"w": "正门;正厅;正殿;正宫;正所儿", "t": "正屋"}, {"w": "正阳", "t": "日中之气"}, {"w": "正锋", "t": "中锋"}, {"w": "正院", "t": "正中的院子"}, {"w": "正分", "t": "正半,恰好一半"}, {"w": "正胁", "t": "三分牲牛之胁,中胁为正胁"}, {"w": "正位", "t": "中正之位"}, {"w": "正东;正上方;正前方;正南;正交;正情", "t": "端庄的情态。"}]}, {"meaning": "正直,正派。", "cites": [{"t": "平心持正。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "正人君子;忠正;廉正;正明公道", "t": "正大光明,不偏私"}, {"w": "正明交易", "t": "正大光明的事"}, {"w": "正士", "t": "正直之士"}, {"w": "正人", "t": "正直的人;品行端正的上等人。"}]}, {"meaning": "纯正不杂(多指色、味)。", "cites": [{"t": "古书之正。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "正而不至焉。", "b": ""}, {"t": "正赤如丹。(纯红得像朱砂。正:纯;丹:朱砂。)", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "正一", "t": "纯真之一"}, {"w": "正意", "t": "纯正的心志"}, {"w": "正黑", "t": "纯黑色"}, {"w": "正风", "t": "纯正的民歌;纯正的风气"}, {"w": "正性", "t": "纯正的禀性"}, {"w": "正味", "t": "纯正的滋味"}, {"w": "正青", "t": "纯青。"}]}, {"meaning": "作为主体的,与“副”相对。", "cites": [{"t": "而十四司正副郎好事者。", "b": "方苞《狱中杂记》"}], "words": [{"w": "正职;正角;正团长;正房大院", "t": "院落中的主要房舍及较大活动场所"}, {"w": "正赋", "t": "主要的赋税。指地丁税。"}]}, {"meaning": "正当;合适。", "cites": [{"t": "虽成败事异,而同居正号者,竝列于篇。", "b": "《后汉书·皇后纪序》"}, {"t": "名不正则言不顺。", "b": "《论语·子路》"}], "words": [{"w": "正号", "t": "正当的名号"}, {"w": "正条儿", "t": "比喻正经、非淫乱之事"}, {"w": "正用情借", "t": "正为有正当用途托情借债。"}]}, {"meaning": "正面,面对观察者或对手的一面。", "cites": [{"t": "从搭连中取出个正反两面皆可照人的镜子来。", "b": "《红楼梦》"}], "words": [{"w": "这张纸正好都很光洁", "t": ""}]}, {"meaning": "(zhěng)。使正;整理;端正。", "cites": [{"t": "立必正方,不倾听。", "b": "《礼记·曲礼上》"}, {"t": "正尔容。", "b": ""}, {"t": "正冠而缨绝。", "b": "《庄子·让王》"}], "words": [{"w": "正家", "t": "端正家风"}, {"w": "正襟", "t": "端正衣襟"}, {"w": "正德", "t": "端正自己的德行"}, {"w": "正己", "t": "端正自己的思想、言行。"}]}, {"meaning": "整治。", "cites": [{"t": "居者思正其家,行者乐出其途。", "b": "柳宗元《全义县复北门记》"}], "words": [{"w": "正世", "t": "整治世道"}, {"w": "正域", "t": "整治封疆"}, {"w": "正治", "t": "治理;整治。"}]}, {"meaning": "纠正;改正,匡正。", "cites": [{"t": "以正晋国。", "b": "《国语·晋语》"}, {"t": "正法则,选贤良。", "b": "《荀子·王制》"}, {"t": "政以治民,刑以正邪。", "b": "《左传·隐公十一年》"}, {"t": "就有道而正焉。", "b": "《论语·学而》"}, {"t": "正身以黜恶。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "正历", "t": "改订历法"}, {"w": "正订", "t": "订正;改正著作中的谬误"}, {"w": "正俗", "t": "匡正风俗"}, {"w": "正曲", "t": "矫正枉曲"}, {"w": "正主", "t": "匡正君主。"}]}, {"meaning": "正法,治罪。", "cites": [{"t": "贼杀其亲,则正之。", "b": "《周礼·夏官·大司马》"}]}, {"meaning": "决定,考定。", "cites": [{"t": "以土圭正日景。", "b": "张昭远《旧唐书》"}]}, {"meaning": "官长;君长。", "cites": [{"t": "昔先正保衡,作我先王。", "b": "《书·说命下》"}], "words": [{"w": "正受", "t": "编制以内的官员"}, {"w": "酒正", "t": "酒官之长。"}]}, {"meaning": "正常情况,正命,正常寿限。", "cites": [{"t": "百岁之命,是其正也。", "b": "王充《论衡》"}]}, {"meaning": "嫡长子,与“庶”相对。", "cites": [{"t": "诸侯与正而不贤也。", "b": "《谷梁传》"}]}, {"meaning": "妻,旧时代敬称人妻为“令正”。", "cites": [{"t": "不得登用妾媵以为嫡正。", "b": "房玄龄《晋书》"}], "words": [{"w": "正头娘子", "t": "正妻;大娘子"}, {"w": "正头妻", "t": "正式的、合法的妻子"}, {"w": "正夫人", "t": "嫡妻,正房夫人"}, {"w": "正嫡", "t": "正室,嫡妻;又指正室之子。"}]}, {"meaning": "道理,规律。", "cites": [{"t": "尽璇机之正。", "b": "《后汉书·张衡传》"}]}, {"meaning": "政治,政事。", "cites": [{"t": "有不贡士谓之不率正者。", "b": "《尚书大传·皋繇谟》"}, {"t": "古者文武为正均分。", "b": "《墨子·兼爱下》"}, {"t": "虽天子三公问正。", "b": "《荀子·大略》"}]}, {"meaning": "凭证,证据。", "cites": [{"t": "必有正焉。", "b": "《仪礼·士昏礼》"}, {"t": "指九天以为正兮。", "b": "《楚辞·离骚》"}, {"t": "指苍天以为正。", "b": "《楚辞·九章·惜诵》"}]}, {"meaning": "正好,恰好。", "cites": [{"t": "六合正相应。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "正称下情", "t": "正合心意;正中下怀"}, {"w": "正没理处", "t": "正在不知如何是好的时候"}, {"w": "正未有艾", "t": "正无穷期"}, {"w": "正如你所说的;大小正合适;正要", "t": "刚要;正预备。"}]}, {"meaning": "表示动作、状态的进行,持续,正在。", "cites": [{"t": "中儿正织鸡笼。", "b": "宋·苏轼《浣溪沙》"}, {"t": "见王夫人正和薛姨妈长篇大套的说些家务人情话。", "b": "《红楼梦》"}], "words": [{"w": "正然", "t": "正在"}, {"w": "正下着雪", "t": ""}]}, {"meaning": "仅;只。", "cites": [{"t": "乃自吴寻二陆,平原不在,正见清河。", "b": "《世说新语·自新门》"}]}, {"meaning": "端正地。", "cites": [{"t": "宾客意少舒,稍稍正坐。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "方,刚刚。", "cites": [{"t": "我思舜,正郁陶。", "b": "《史记·五帝本纪》"}]}, {"meaning": "公然;显然。", "cites": [{"t": "正告天下。", "b": "《史记·苏秦列传》"}]}, {"meaning": "总是。", "cites": [{"t": "何以正善人少而恶人多。", "b": "《世说新语》"}]}, {"meaning": "这么;这样。", "cites": [{"t": "今年怎正利害?", "b": "《老残游记》"}], "words": [{"w": "怎正大;怎正多", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('199wx','扑','1','pū','扌','5','','[{"pinyin": "pū", "defs": [{"meaning": "(形声。左形,右声。本义:击,打)。"}, {"meaning": "同本义。", "cites": [{"t": "扑,挨也。", "b": "《说文》"}, {"t": "扑,击也。", "b": "《广雅》"}, {"t": "连杖曰扑。", "b": "《通俗文》"}, {"t": "荫不祥之木为雷电所扑。", "b": "《淮南子·说林》"}, {"t": "举筑扑秦皇帝,不中。", "b": "《史记·刺客列传》"}, {"t": "吾即扑杀汝。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "扑掌", "t": "拍掌。表示惊讶、惋惜"}, {"w": "扑作教刑", "t": "用板子责打违反礼教的人"}, {"w": "扑刑", "t": "指教师用戒尺、教鞭之类对学生所作的体罚"}, {"w": "扑抶", "t": "杖击,鞭打"}, {"w": "扑责", "t": "杖击责罚"}, {"w": "扑枣", "t": "击落枣子。"}]}, {"meaning": "进攻。", "cites": [{"t": "秦破韩、魏,扑师武。", "b": "《史记·周本纪》"}]}, {"meaning": "拂着;拂拭。", "cites": [{"t": "旋见鸡伸颈摆扑。", "b": "《聊斋志异·促织》"}], "words": [{"w": "扑复", "t": "扑击"}, {"w": "扑手", "t": "扑击的招数"}, {"w": "扑殄", "t": "扑灭"}, {"w": "扑剪", "t": "扑灭铲除。"}]}, {"meaning": "倾倒", "cites": [{"t": "秦破韩魏,扑师武。", "b": "《史记·周本纪》"}, {"t": "朽机懼倾扑。", "b": "韩愈《纳凉联句》"}], "words": [{"w": "扑翻身", "t": "跪下后两手伏地,扑倒身子"}, {"w": "扑跌", "t": "相扑,摔交"}, {"w": "扑破", "t": "摔破;摔坏"}, {"w": "扑杀", "t": "摔死;击杀。"}]}, {"meaning": "喻指烟、气之属直冲(人的感官)。", "cites": [{"t": "剖之,有如烟扑口鼻。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "扑面", "t": ""}]}, {"meaning": "棰杖。", "cites": [{"t": "永泰中,余任洛阳丞,以扑抶军骑。", "b": "唐·韦应物《示从子河南尉班》"}]}, {"meaning": "鞭子;戒尺。古代体罚用具。", "cites": [{"t": "执敲扑而鞭笞天下,威振四海。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "扑罚", "t": "以鞭扑来惩罚"}, {"w": "扑挞", "t": "鞭打。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('200wx','卉','1','huì','十','5','','[{"pinyin": "huì", "defs": [{"meaning": "(会意。小篆字从三“屮”(chè),草木初生。本义:草的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "卉,草之总名也。", "b": "《说文》"}, {"t": "卉木萋萋。", "b": "《诗·小雅·出车》"}, {"t": "百卉具腓。", "b": "《诗·小雅·四月》"}, {"t": "鸟夷卉服。", "b": "《书·禹贡》"}], "words": [{"w": "卉木", "t": "草木"}, {"w": "卉犬", "t": "用草扎成的狗"}, {"w": "卉物", "t": "草木物产。"}]}, {"meaning": "泛指草木。", "cites": [{"t": "桑末寄失根生兮,卉既凋而已育。", "b": "《文选·张衡·思玄赋》"}]}, {"meaning": "指花。", "cites": [{"t": "奇卉怪草。", "b": "王元之《桂阳罗君游太湖洞庭诗序》"}]}, {"meaning": "众。", "cites": [{"t": "卉,众也。", "b": "《广雅·释诂三》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('201wx','扒','1','ba pá','扌','5','','[{"pinyin": "ba", "defs": [{"meaning": "刨,挖。", "cites": [{"t": "扒了好几天,才扒出来这个大洞子。", "b": "《高玉宝》"}, {"t": "用前足的钩扒掘地面。", "b": "《蝉》"}], "words": [{"w": "扒坑;扒开浮土;扒土;扒堤", "t": ""}]}, {"meaning": "攀援。", "cites": [{"t": "他明朝就扒在我头上来哩。", "b": "明·朱京藩《风流院传奇·投罗》"}], "words": [{"w": "扒车;扒得高,跌得重", "t": ""}]}]}, {"pinyin": "pá", "defs": [{"meaning": "用手或用工具把东西聚拢或散开。", "cites": [{"t": "姐夫,去请你爹进来扒口子饭。", "b": "《金瓶梅》"}], "words": [{"w": "扒草;把枯树叶扒在一起", "t": ""}]}, {"meaning": "从别人身上摸窃财物。", "cites": [{"t": "他送给我一只旧怀表…不知道它是在什么时候给扒手拿走的。", "b": "巴金《我的哥哥李尧林》"}], "words": [{"w": "扒钱包", "t": ""}]}, {"meaning": "挣。", "cites": [{"t": "社会在变,舞文弄墨者群也在变,能够在这领域里纵横驰聘的人,有不少已不赞成严肃认真,他们也称写作为“扒分”。就像个体户卖牛仔裤一样。", "b": "孙少琪《他在写作》"}], "words": [{"w": "扒分", "t": "挣钱,捞外快。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('202wx','功','1','gōng','力','5','','[{"pinyin": "gōng", "defs": [{"meaning": "(会意。从力,工声。“工”亦兼表字义,表示用力从事工作。本义:功绩,功业;功劳)。"}, {"meaning": "同本义。", "cites": [{"t": "功,以劳定国也。", "b": "《说文》"}, {"t": "国功曰功。", "b": "《周礼·司勋》"}, {"t": "欲诛有功之人,此亡秦之续耳。", "b": "《史记·项羽本纪》"}, {"t": "驽马十驾,功在不舍。", "b": "《荀子·劝学》"}, {"t": "位尊而无功,奉厚而无劳,而挟重器多也。", "b": "《战国策·赵策》"}], "words": [{"w": "功誉", "t": "功绩与声誉"}, {"w": "功行", "t": "功绩与德行"}, {"w": "功化", "t": "功业与教化"}, {"w": "功成名就", "t": "建立了功业,才有名声。后指功绩、名声皆得。"}]}, {"meaning": "事情;工作。", "cites": [{"t": "嗟我农夫,我稼既同(集中),上(通“尚”,还)入执宫功(室内的事)。", "b": "《诗·豳风·七月》"}, {"t": "惟荒度土功。", "b": "《书·益稷》"}, {"t": "事求可,功求成。", "b": "《庄子·天地》"}]}, {"meaning": "功德;恩德。", "cites": [{"t": "今恩足以及禽兽,而功不至于百姓者,独何与?", "b": "《孟子·梁惠王上》"}]}, {"meaning": ""}, {"meaning": "事。", "cites": [{"t": "登是南邦,世执其功。", "b": "《诗·大雅·崧高》"}, {"t": "故男不群乐以妨事,女不群乐以妨功。", "b": "《晏子春秋·内篇谏上》"}]}, {"meaning": "土木营造之事。", "cites": [{"t": "内兴功作,外攘夷狄。", "b": "《汉书·食货志上》"}]}, {"meaning": "工程和劳动人力。", "cites": [{"t": "陇右取材,功夫不难。", "b": "《三国志·魏书·董卓传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('203wx','扔','1','rēng','扌','5','','[{"pinyin": "rēng", "defs": [{"meaning": "(形声。从手,乃声。甲骨文字形,象以手牵引或投掷东西的样子。本义:牵引,拉)。"}, {"meaning": "同本义。", "cites": [{"t": "扔,引也。", "b": "《广雅》"}, {"t": "上礼为之而莫之应,则攘臂而扔之。", "b": "《老子》"}]}, {"meaning": "摧残。", "cites": [{"t": "窜伏扔轮。", "b": "《后汉书》"}]}, {"meaning": "", "cites": [{"t": "扔,姓。《古今人表》有扔君。", "b": "《正字通》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('204wx','去','1','qù','厶','5','','[{"pinyin": "qù", "defs": [{"meaning": "(会意兼形声。甲骨文字形。上面是人(大),下面是口(或作“凵”),表示人离开洞口或坑坎而去。《说文》:“从大,凵声。”凵(qū)。本义:离开)。"}, {"meaning": "同本义。", "cites": [{"t": "去,人相违也。", "b": "《说文》"}, {"t": "逝将去女,适彼乐土。", "b": "《诗·魏风·硕鼠》"}, {"t": "纪侯大去其国。", "b": "《春秋·庄公四年》"}, {"t": "大去者,不遗一人之辞也。", "b": "《谷梁传》"}, {"t": "武子去所。", "b": "《左传·襄公二十年》"}, {"t": "不能相去。", "b": "《战国策·齐策》"}, {"t": "乃去。", "b": "唐·柳宗元《三戒》"}, {"t": "久而不去。", "b": "宋·欧阳修《归田录》"}, {"t": "一狼径去。", "b": "《聊斋志异·狼三则》"}, {"t": "东向驰去。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "去离", "t": "分离;离开"}, {"w": "去任", "t": "因故离开职位"}, {"w": "去住无门", "t": "进退两难"}, {"w": "去来", "t": "离去;往来"}, {"w": "去位", "t": "离开官位。"}]}, {"meaning": "除去;去掉。", "cites": [{"t": "去死肌,杀三虫。", "b": "柳宗元《捕蛇者说》"}, {"t": "明日去。", "b": "清·袁枚《黄生借书说》"}, {"t": "俸去书来。", "b": ""}], "words": [{"w": "去绝根株", "t": "斩草除根"}, {"w": "去疾", "t": "除去疾病"}, {"w": "去皮;去邪归正", "t": "去掉邪恶,归于正道。"}]}, {"meaning": "相距,远离。", "cites": [{"t": "连峰去天不盈尺。", "b": "《蜀道难》"}, {"t": "日始出时去人近。", "b": "《列子·汤问》"}, {"t": "西蜀之去南海。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "去村四里。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "两地相去50里", "t": ""}]}, {"meaning": "前往,到别处,跟“来”相反。", "cites": [{"t": "大江东去,浪淘尽,千古风流人物。", "b": "苏轼《念奴娇·赤壁怀古》词"}, {"t": "公然抱茅入竹去。", "b": "杜甫《茅屋为秋风所破歌》"}, {"t": "汝可去应之。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "去住无门", "t": "进退两难"}, {"w": "去紧", "t": "走得快;迅疾"}, {"w": "去处", "t": "所去的地方"}, {"w": "去学校;谁去都一样", "t": ""}]}, {"meaning": "失掉; 失去。", "cites": [{"t": "大事去矣,可痛惜哉。", "b": "《三国演义》"}], "words": [{"w": "去失", "t": "丢失。"}]}, {"meaning": "赶走;打发走。", "cites": [{"t": "夫汇上之处女,有家贫而无烛者,处女相与语,欲去之。", "b": "《战国策》"}]}, {"meaning": "抛弃,舍弃。", "cites": [{"t": "是君臣、父子、兄弟尽去仁义,怀利以相接,然而不亡者,未之有也。", "b": "《孟子》"}], "words": [{"w": "去心", "t": "心里丢开;放心"}, {"w": "去势", "t": "舍弃权势。"}]}, {"meaning": "去世,死亡。", "cites": [{"t": "日月还复周,我去不再阳。", "b": "晋·陶渊明《杂诗》"}], "words": [{"w": "去世", "t": "死亡。"}]}, {"meaning": "用在谓词或谓词结构后表示趋向或持续。", "cites": [{"t": "上去下来船不定,自飞自语燕争忙。", "b": "宋·梅尧臣《绝句》"}, {"t": "归去来兮。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "一鸣辄跃去。", "b": "《聊斋志异·促织》"}, {"t": "跃去尺有咫。", "b": ""}], "words": [{"w": "我去考虑考虑;明年回乡下去;船向前慢慢开去;把东西给他送去", "t": ""}]}, {"meaning": "逃离,逃亡。", "cites": [{"t": "委而去之。", "b": "《孟子·公孙丑下》"}, {"t": "小敌去。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "纺焉以度而去之。", "b": "《左传·昭公十九年》"}]}, {"meaning": "驱逐。", "cites": [{"t": "千乘三去。", "b": "《左传·僖公十五年》"}]}, {"meaning": "胆小,畏缩。"}, {"meaning": "在。表示时间或处所。", "cites": [{"t": "去里面一字儿摆着三只大酒缸。", "b": "《水浒传》"}]}, {"meaning": "去声。汉语四声之一。", "cites": [{"t": "古人以“平”“上”“去”“入”四字各为一声的代表字,于是这四个字就成了四声的名称。", "b": "王力《汉语音韵学》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('205wx','甘','1','gān','甘','5','','[{"pinyin": "gān", "defs": [{"meaning": "(会意兼指事。小篆从口,中间的一横象口中含的食物,能含在口中的食物往往是甜的、美的。汉字部首之一,从“甘”的字往往与“甜”、“美味”有关。本义:味美)。"}, {"meaning": "同本义。", "cites": [{"t": "甘,美也。", "b": "《说文》"}, {"t": "稼穑作甘。", "b": "《书·洪范》"}, {"t": "以甘养肉。", "b": "《周礼·疡医》"}, {"t": "甘胜碱。", "b": "《素问·阴阳应象大论》"}, {"t": "秦王饮食不甘。", "b": "《韩非子·存韩》"}, {"t": "何向者视渡老人之芋之香而甘也!", "b": "清·周容《芋老人传》"}, {"t": "退而甘食其土之有,以尽吾齿。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "甘肥", "t": "味美香浓的食品"}, {"w": "甘味", "t": "甘肥。美味"}, {"w": "甘膳", "t": "珍馐美味"}, {"w": "甘馨", "t": "美味佳肴。"}]}, {"meaning": "甜。", "cites": [{"t": "辛甘行些。", "b": "《楚辞·招魂》"}, {"t": "开明北又有甘水。", "b": "《山海经·海内西经》"}, {"t": "吾闻井以甘竭,李以苦存,夫差以酣酒亡,而勾践以尝胆兴,无亦犹是也夫?", "b": "明·刘基《苦斋记》"}], "words": [{"w": "甘醴", "t": "甘甜美味的酒"}, {"w": "甘豆羹", "t": "一种甜豆羹"}, {"w": "甘瓠", "t": "甘甜可食的瓠瓜"}, {"w": "甘木", "t": "所结果实甜美的果树"}, {"w": "甘辛", "t": "甜而微辣。"}]}, {"meaning": "好,及时。", "cites": [{"t": "以祈甘雨,以介我稷黍。", "b": "《诗·小雅·甫田》"}], "words": [{"w": "甘泽", "t": "甘霖,甘雨"}, {"w": "甘澍", "t": "甘雨"}, {"w": "甘膏", "t": "甘雨,膏雨"}, {"w": "甘霈", "t": "甘雨。"}]}, {"meaning": "甘愿;乐意。", "cites": [{"t": "予本非文人画士,甘受诟厉,辟病梅之馆以贮之。", "b": "清·龚自珍《病梅馆记》"}, {"t": "等于己者,狎之而不甘问焉。", "b": "清·刘开《问说》"}], "words": [{"w": "不甘落后;甘分", "t": "甘心于本分"}, {"w": "甘伏", "t": "甘心降伏"}, {"w": "甘罪", "t": "自愿承担罪过。"}]}, {"meaning": "美味的食品。", "cites": [{"t": "为肥甘不足于口与?轻暖不足于体与?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "甘食", "t": "鲜美的食物"}, {"w": "甘软", "t": "鲜美柔软的食物"}, {"w": "甘鲜", "t": "鲜美的食品。"}]}, {"meaning": "甘味,甜味。", "cites": [{"t": "少尝苦曰苦,多尝苦曰甘,则必以此人为不知甘苦之辨矣。", "b": "《墨子·非攻上》"}]}, {"meaning": "果名,橘属。", "cites": [{"t": "卢橘夏熟,黄甘橙楱。", "b": "司马相如《上林赋》"}]}, {"meaning": "嗜好;爱好。", "cites": [{"t": "孙叔敖甘寝秉羽而郢人投兵。", "b": "《庄子·徐无鬼》"}, {"t": "残仁贼义,甘财悦色。", "b": "曹植《藉田说》"}], "words": [{"w": "甘酒", "t": "嗜酒"}, {"w": "甘嗜", "t": "嗜好"}, {"w": "甘乐", "t": "喜好"}, {"w": "甘利", "t": "好利;贪利"}, {"w": "甘得", "t": "贪得。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('206wx','世','1','shì','一','5','','[{"pinyin": "shì", "defs": [{"meaning": "(指事。金文字形。古人以三十年为一世。“止”上加三个圆点,表三十年;止,到此为止。本义:三十年)。"}, {"meaning": "同本义。", "cites": [{"t": "世,三十年为一世。", "b": "《说文》"}, {"t": "如有王者,必世而后仁。", "b": "《论语·子路》"}]}, {"meaning": "父子相继为世。一代(古礼规定,男子三十岁结婚生孩子,产生新一代)。", "cites": [{"t": "父子相代为一世。", "b": "《字汇》"}, {"t": "世室世世不毁也。", "b": "《公羊传·文公十三年》"}, {"t": "世相朝也。", "b": "《周礼·大行人》"}, {"t": "昔我先王世后稷。", "b": "《国语·周语》"}, {"t": "有蒋氏者,专其利三世矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "孙权据有江东,已历三世,国险而民附。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "世功", "t": "累代的功绩"}, {"w": "世世", "t": "代代"}, {"w": "世治", "t": "世世代代地统治"}, {"w": "世济", "t": "世代继承"}, {"w": "世卿", "t": "指世代承袭的卿大夫"}, {"w": "世职", "t": "父子相袭的官职"}, {"w": "世爵", "t": "世代继承爵位"}, {"w": "世谱", "t": "世系家谱"}, {"w": "世将", "t": "世代为将"}, {"w": "祖传世医", "t": ""}]}, {"meaning": "一生;一辈子。", "cites": [{"t": "负刍必以魏,殁世事秦。", "b": "《战国策·秦策》。注:“身也。”"}, {"t": "凡君之所毕世而经营者,为天下也。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "今生今世;尘世;来世;出世;入世;永世不忘", "t": ""}]}, {"meaning": "人世,世间;世界。", "cites": [{"t": "世有伯乐,然后有千里马。", "b": "唐·韩愈《马说》"}, {"t": "虽才高于世,而无骄尚之情。", "b": "《后汉书·张衡传》"}, {"t": "此世所谓上下相孚也。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "一世之雄;举世闻名;世故;世尊", "t": "佛祖。佛教徒对释迦牟尼的尊称"}, {"w": "世涂", "t": "光天化日之下;亦常比喻处世的经历"}, {"w": "世界路上", "t": "人世交际场中"}, {"w": "世外桃源", "t": ""}]}, {"meaning": "时代;朝代。", "cites": [{"t": "问今是何世,乃不知有汉,无论魏晋。", "b": "晋·陶渊明《桃花源记》"}, {"t": "而圣君治国累世而不见者。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "近世;治世;浊世;盛世;乱世;先世;世屯", "t": "时世艰难"}, {"w": "世务", "t": "当世有关国计民生的大事。"}]}, {"meaning": "岁;年。", "cites": [{"t": "志国三世。", "b": "《礼记·曲礼》"}, {"t": "世之有饥穰,天之行也。", "b": "《论积贮疏》"}], "words": [{"w": "世远事乖", "t": "年代久远,事情不顺。"}]}, {"meaning": "世俗。", "cites": [{"t": "龙德而隐者也,不易乎世。", "b": "《易·乾》"}]}, {"meaning": "后嗣;后人。", "cites": [{"t": "卫瑞木叔者,子贡之世也。", "b": "《列子·杨朱》"}], "words": [{"w": "后世;官人以世", "t": "官人不以贤才而以父兄。"}]}, {"meaning": "家世。", "cites": [{"t": "陵不引决,忝世灭姓。", "b": "《汉书》"}]}, {"meaning": "世族。", "cites": [{"t": "以族论罪,以世举贵,虽欲无乱,得乎哉?", "b": "《荀子·君子》"}], "words": [{"w": "世家子弟", "t": "泛指世代做官人家的子弟"}, {"w": "世家军籍", "t": "世代都是军人"}, {"w": "世胄", "t": "贵族后裔;泛指门第高、世代做官的人家。"}]}, {"meaning": "有世交关系,表示两家之间世代交往。", "cites": [{"t": "世先生同在桑梓,一向有失亲近。", "b": "《儒林外史》"}], "words": [{"w": "世先生", "t": "对世交的尊称"}, {"w": "世侄;世台", "t": "对世交晚辈的尊称"}, {"w": "世伯", "t": "对父辈朋友中年长于己父者的称呼"}, {"w": "世叔", "t": "对父辈朋友中年小于己父者的称呼"}, {"w": "世翁", "t": "对世代有交谊的长辈的尊称。"}]}, {"meaning": "指嫡长。", "cites": [{"t": "父之兄弟先生为世父。", "b": "《尔雅》"}, {"t": "世父言为嫡统继世也。故世子亦曰大子。", "b": "《释名》"}, {"t": "卫世叔仪。", "b": "《左传·襄公二十九年》"}]}, {"meaning": "大的。", "cites": [{"t": "滀乎进我色也,与乎止我德也;厉乎其似世乎!", "b": "《庄子·大宗师》"}], "words": [{"w": "世利", "t": "大大有利于。"}]}, {"meaning": "既然,已经。", "cites": [{"t": "小子世来你家,大姐不要说闲话。", "b": "元·马致远《青衫泪》"}]}, {"meaning": "从来;终归。", "cites": [{"t": "我将这角门儿世不曾牢拴。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "永远。", "cites": [{"t": "再休想那章台走马郎,度你到西方…,世脱下皮囊。", "b": "元·李寿卿《度翠柳》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('207wx','艾','1','ài yì','艹','5','','[{"pinyin": "ài", "defs": [{"meaning": "(形声。本义:草名)。"}, {"meaning": "即艾蒿 。一种菊科的多年生草本植物(Artemisia argyi),叶制成艾绒,供针灸用。", "cites": [{"t": "艾,冰台也。", "b": "《说文》"}, {"t": "削冰令圆举以向日,干艾于后,承其景则得火,故曰冰台。", "b": "《博物志》"}, {"t": "彼采艾兮,一日不见,如三岁兮。", "b": "《诗·王风·采葛》"}, {"t": "求三年之艾也。", "b": "《孟子》。"}], "words": [{"w": "艾人", "t": "用艾草结成的草人。旧俗在端午节以艾人悬挂于门上,可以避邪除毒。"}]}, {"meaning": "老年,对老年人的敬称。", "cites": [{"t": "有幼、壮、艾之期。", "b": "刘禹锡《送鸿举师游江南引》"}, {"t": "五十曰艾,服官政。", "b": "《礼记》。郑玄注:“艾,老也。”"}, {"t": "搜索稚与艾,惟存跛无目。", "b": "梅尧臣《田家语》。"}], "words": [{"w": "艾老", "t": "五十岁以上的老人。"}]}, {"meaning": "漂亮的人。", "cites": [{"t": "国君好艾(此指男色),大夫殆。", "b": "《国语·晋语》"}, {"t": "积得些金帛,娶了些娇艾。", "b": "《桃花扇》。"}], "words": [{"w": "艾色", "t": "美丽;漂亮。多指女色。"}]}, {"meaning": "小人。", "cites": [{"t": "何昔日之芳草兮,今直为此萧艾也。", "b": "屈原《离骚》"}]}, {"meaning": "老。", "cites": [{"t": "既定尔娄猪,盍归吾艾豭?", "b": "《左传·定公十四年》。"}], "words": [{"w": "艾孀", "t": "老寡妇"}, {"w": "艾孀", "t": "老公猪。"}]}, {"meaning": "艾草的颜色。即苍白色或绿色。", "cites": [{"t": "赐驳犀具剑、佩刀、紫艾绶、玉玦各一。", "b": "《后汉书·冯鲂传》。"}], "words": [{"w": "艾绶", "t": "绿色的印绶"}, {"w": "艾孀", "t": "年老的寡妇。"}]}, {"meaning": "终止,断绝。", "cites": [{"t": "夜如何其?夜未艾。", "b": "《诗·小雅·庭燎》"}, {"t": "一旦运穷福艾。", "b": "明·刘基《苦斋记》。"}], "words": [{"w": "艾命", "t": "舍弃生命"}, {"w": "艾艾", "t": "说话结结巴巴。形容口吃的样子"}, {"w": "方兴未艾", "t": "正在发展,一时不会停止。"}]}, {"meaning": "姓。"}]}, {"pinyin": "yì", "defs": [{"meaning": "刈割;斩除。", "cites": [{"t": "一年不艾,而百姓饥。", "b": "《谷梁传·庄公二十八年》"}], "words": [{"w": "艾命", "t": "舍生;捐躯。"}]}, {"meaning": "治理;安定。", "cites": [{"t": "或肃或艾。", "b": "《诗·小雅·小旻》"}, {"t": "海内艾安,府库充实。", "b": "《汉书》"}], "words": [{"w": "艾安", "t": "民生安定,宇内承平。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('208wx','古','1','gǔ','口','5','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。从十,从口。本义:古代。一般分为太古、上古、中古、近古)。"}, {"meaning": "同本义。", "cites": [{"t": "古,故也。", "b": "《说文》"}, {"t": "大古冠布。", "b": "《仪礼·士冠礼》。注:“大古,唐虞以上。”"}, {"t": "以是为近古也。", "b": "《谷梁传·桓公三年》。注:“古,谓五帝时。”"}, {"t": "慨长思而怀古。", "b": "《文选·张衡·东京赋》"}, {"t": "别求闻由古先哲王。", "b": "《书·康诰》"}, {"t": "故察己则可以知人,察今则可以知古。古今一也,人与我同耳。", "b": "《吕氏春秋·察今》"}, {"t": "故古之人君,量而不欲入者,许由、务光是也。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "远古", "t": "遥远的古代"}, {"w": "古字", "t": "指隶书以前的古代文字"}, {"w": "古器", "t": "可供玩赏的古代器物;古代乐器"}, {"w": "古货", "t": "古代货币"}, {"w": "古贤", "t": "古代贤人。"}]}, {"meaning": "古代的事物,特指先哲的遗典、道统。古代的典章、文献。", "cites": [{"t": "余嘉其能行古道,作《师说》以贻之。", "b": "唐·韩愈《师说》"}, {"t": "宽至雒阳,复从周王孙受古义,号《周氏传》。", "b": "《汉书·丁宽传》"}], "words": [{"w": "仿古;考古;拟古;怀古;古义", "t": "古书的义理"}, {"w": "古谊", "t": "古代典籍之义理"}, {"w": "古逸", "t": "指未加纂辑的古诗文等。"}]}, {"meaning": "古人。", "cites": [{"t": "古人云:“以地事秦,犹抱薪救火,薪不尽,火不灭。”", "b": "宋·苏洵《权书·六国论》"}, {"t": "陈古义以刺今,不说德而好色也。", "b": "《诗·郑风·女曰鸡鸣序》"}], "words": [{"w": "古老上人", "t": "古人"}, {"w": "古义", "t": "古人立身行事的道理;古人对经籍的传统解释"}, {"w": "古节", "t": "古人立身的节操"}, {"w": "古谊", "t": "古贤人之风义。"}]}, {"meaning": "天。", "cites": [{"t": "天为古。", "b": "《周书·周祝》"}, {"t": "曰若稽古。", "b": "《书·尧典》"}, {"t": "其于中古乎。", "b": "《易·系辞传》"}], "words": [{"w": "古帝", "t": "指天帝"}, {"w": "古后", "t": "先王,前代帝王。"}]}, {"meaning": "象声词。如;古剌剌(旗子飘动或甩鞭的声响);古鲁鲁(古鹿鹿。形容物体转动;也指腹内肠子蠕动或液体喷出的声响);古都都(多形容水不断涌出的声响)。"}, {"meaning": "久远;古老  ——用来指从很久以前就已经存在的东西。", "cites": [{"t": "古,久也。", "b": "《玉篇》"}, {"t": "逝不古处。", "b": "《诗·邶风·日月》"}, {"t": "古训是式。", "b": "《诗·大雅·烝民》"}, {"t": "今之于古也。", "b": "《吕氏春秋·长见》"}, {"t": "枯藤老树昏鸦,小桥流水人家,古道西风瘦马。", "b": "元·马致远《天净沙·秋思》"}, {"t": "圣贤名古邈,羁旅病年侵。", "b": "唐·杜牧《风疾舟中伏枕书怀三十六韵奉承湘南亲友》"}], "words": [{"w": "古文明;古王朝;古堡", "t": "边疆古老的城堡;营垒"}, {"w": "古渡", "t": "古老的渡口"}, {"w": "古始", "t": "远古"}, {"w": "古礼", "t": "古时的礼制。"}]}, {"meaning": "奇特,不同凡俗;执拗。", "words": [{"w": "古执", "t": "固执。古板执拗"}, {"w": "古董", "t": "方言。比喻顽固守旧的人"}, {"w": "古涩", "t": "形容文句古奥难读。"}]}, {"meaning": "旧,原来。", "cites": [{"t": "古法采草药多用二月、八月,此殊未当。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "良人惟古欢,枉驾惠前绥。", "b": "《古诗十九首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('209wx','节','1','jiē jié','艹','5','','[{"pinyin": "jiē", "defs": [{"meaning": "——用于“节骨眼”、“节子”等复音词中。"}]}, {"pinyin": "jié", "defs": [{"meaning": "(形声。从竹,即声。本义:竹节)。"}, {"meaning": "同本义。泛指草木枝干间坚实结节的部分。", "cites": [{"t": "節,竹约也。", "b": "《说文》"}, {"t": "苞笋抽节。", "b": "左思《吴都赋》"}, {"t": "譬如破竹,数节之后,皆迎刃而解。", "b": "《晋书·杜预传》"}, {"t": "其于木也,为坚多节。", "b": "《易·说卦》"}], "words": [{"w": "节根", "t": "草木的节与根"}, {"w": "节旄", "t": "竹节上所缀牦牛尾饰物"}, {"w": "节粉", "t": "竹节旁附着的白色粉末"}, {"w": "节槎", "t": "树木上歧出的节"}, {"w": "节次", "t": "依次,陆续;或程序,规程。"}]}, {"meaning": "骨节,节骨眼,关键。", "cites": [{"t": "客胜,则大关节不利。", "b": "《素问·至真要大论》"}, {"t": "人有十二节。", "b": "《素问·宝命全形论》"}, {"t": "彼节者有间。", "b": "《庄子·养生主》"}, {"t": "得失之节。", "b": "《吕氏春秋·慎行论》"}], "words": [{"w": "节解", "t": "一种酷刑。将犯人的四肢骨节予以支解"}, {"w": "节病", "t": "弊病。破绽"}, {"w": "节拊", "t": "按摩骨节"}, {"w": "节族", "t": "犹关节。节为关节;族为骨肉交错聚结的部位。"}]}, {"meaning": "节日,纪念日,也指传统的庆祝或祭祀的日子。", "cites": [{"t": "常恐秋节至。", "b": "《长歌行》"}], "words": [{"w": "节下", "t": "节日期间"}, {"w": "节导", "t": "仪仗队或在前开路的随从,警卫"}, {"w": "节仪", "t": "节日礼物,节日赠送钱财的雅称"}, {"w": "节朔", "t": "节日和朔日。"}]}, {"meaning": "气节;节操。", "cites": [{"t": "士大夫莫不敬节死制。", "b": "《荀子·王霸》"}, {"t": "屈节辱命。", "b": "《汉书·李广苏建传》"}, {"t": "壮其节。", "b": ""}, {"t": "成此大节。", "b": "清·全祖望《梅花岭记》"}, {"t": "爱听古人节义事。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "节义", "t": "节操与义行"}, {"w": "节敬", "t": "节仪"}, {"w": "节孝牌坊", "t": "古时经官府奏准为表扬节妇孝女而立的牌坊"}, {"w": "节介", "t": "志节操守"}, {"w": "节概", "t": "志节气概。"}]}, {"meaning": "节令,节气。", "cites": [{"t": "寒暑易节。", "b": "《列子·汤问》"}, {"t": "更那堪冷落清秋节。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "节序", "t": "时节的次第"}, {"w": "节物", "t": "应时节的风物景色"}, {"w": "节和", "t": "节令和顺"}, {"w": "节分", "t": "季节的分际。"}]}, {"meaning": "节度。", "cites": [{"t": "寝食违节。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "节宣", "t": "一种养生的方法。指身体的劳逸要有一定的节度,才能使体内郁气顺畅地宣泄。"}]}, {"meaning": "礼节,有礼貌的行为。", "cites": [{"t": "长功之节。", "b": "《论语·微子》"}], "words": [{"w": "节文", "t": "礼节;仪式"}, {"w": "节法", "t": "礼节与法度。"}]}, {"meaning": "符节,古代使者所持以作凭证。", "cites": [{"t": "司马握节以死,故书以官。", "b": "《左传·文公八年》"}, {"t": "持节云中,何日遣冯唐?", "b": "苏轼《江城子》"}, {"t": "持节送匈奴使。", "b": "《汉书·苏武传》"}, {"t": "乘轺建节。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "幢节玲珑。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "节钺", "t": "符节与斧钺。古代授与官员或将帅,作为加重权力的标志"}, {"w": "节帅", "t": "古代节度使的略称"}, {"w": "节楼", "t": "节度使驻节办公的楼"}, {"w": "节镇", "t": "即节度使"}, {"w": "节印", "t": "符节和印信。"}]}, {"meaning": "节拍,节奏。", "cites": [{"t": "应节而舞。", "b": "《聊斋志异·促织》"}], "words": [{"w": "节会", "t": "音乐的段落节奏"}, {"w": "节调", "t": "节拍和音调"}, {"w": "节变", "t": "指乐曲的节奏变化。"}]}, {"meaning": "由一整体分成的部分、段、区、片段或章节。", "cites": [{"t": "冲至第节。", "b": "宋·胡仔《苕溪渔隐丛话》"}], "words": [{"w": "章节;音节;季节;时节;第二章第一节;节旨", "t": "文章的段落大意"}, {"w": "节本", "t": "节录的本子。"}]}, {"meaning": "乐器名。拍板一类的乐器。", "cites": [{"t": "击节碎。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "又如:节鼓(古乐器。形状似博局,中开圆孔,恰容其鼓,击之以节乐)。"}, {"meaning": "减省。", "cites": [{"t": "强本而节用,则天不能贫。", "b": "《荀子·无论》"}, {"t": "节器用。", "b": "《左传·成公十八年》"}, {"t": "谨身节用。", "b": "宋·司马光《训俭示康》"}, {"t": "裁节邮传冗费。", "b": "清·张廷玉《明史》"}], "words": [{"w": "节啬", "t": "吝啬"}, {"w": "节限", "t": "节约限制"}, {"w": "节养", "t": "自奉俭省"}, {"w": "节缩", "t": "节俭紧缩"}, {"w": "节简", "t": "节俭简朴。"}]}, {"meaning": "节制;管束。", "cites": [{"t": "不以礼节之。", "b": "《论论》"}, {"t": "种树节四时之适。", "b": "《韩非子·难二》"}, {"t": "好廉自克曰节。", "b": "《周书·谥法》"}], "words": [{"w": "节性", "t": "节制性情"}, {"w": "节矜", "t": "节制约束而又刚毅坚强。"}]}, {"meaning": "调节。", "cites": [{"t": "节其流,开其源。", "b": "《荀子·富国》"}]}, {"meaning": "高峻的样子。", "cites": [{"t": "节彼南山,维石岩岩。(山石满满。)", "b": "《诗·小雅·节南山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('210wx','本','1','běn','木','5','','[{"pinyin": "běn", "defs": [{"meaning": "(指事。小篆字形,从“木”,下面的一横是加上的符号,指明树根之所在。本义:草木的根或靠根的茎干)。"}, {"meaning": "同本义。", "cites": [{"t": "本,木下曰本。", "b": "《说文》"}, {"t": "本实先拨。", "b": "《诗·大雅·荡》"}, {"t": "木水之有本原。", "b": "《左传·昭公元年》"}, {"t": "伐木不自其本,必复生。", "b": "《国语·晋语》"}, {"t": "是岁,有禾生景天中,三本一茎九穗。", "b": "《论衡·吉验》"}, {"t": "摇其本以观其疏密。", "b": "唐·柳宗元《种树郭橐驼传》"}], "words": [{"w": "水有源,木有本;本干", "t": "草木的根干。"}]}, {"meaning": "本宗族。", "cites": [{"t": "本支百世。", "b": "《诗·大雅·文王》"}, {"t": "几房的本家大约已经搬走了。", "b": "鲁迅《呐喊》"}], "words": [{"w": "本宗", "t": "犹祖籍;本宗族"}, {"w": "本种", "t": "自己的种族。"}]}, {"meaning": "事物的根基或主体。", "cites": [{"t": "君子务本。", "b": "《论语·学而》"}, {"t": "今背本而趋末。", "b": "汉·贾谊《论积贮疏》"}, {"t": "然墨之道,兼爱为本。", "b": "马中锡《中山狼传》"}], "words": [{"w": "治本", "t": "从根本上加以处理"}, {"w": "根本", "t": "事物的根源或最重要部分。"}]}, {"meaning": "母金,本钱。", "cites": [{"t": "子本相侔。(子:利息,侔:相等)", "b": "韩愈《柳子厚墓志铭》"}], "words": [{"w": "亏本", "t": "损失本钱"}, {"w": "本钿", "t": "方言。本钱"}, {"w": "本银", "t": "本钱,资本。"}]}, {"meaning": "根源,本源。", "cites": [{"t": "物有本末,事有始终。", "b": "《礼记·大学》"}, {"t": "盖亦反其本矣。", "b": "《孟子·梁惠王上》"}, {"t": "为是者有本有原。", "b": "唐·韩愈《原毁》"}, {"t": "人穷则反本。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "本根", "t": "根由,根源"}, {"w": "本缘", "t": "佛教语。由来,缘起"}, {"w": "本由", "t": "根由。"}]}, {"meaning": "古代指农业生产。", "cites": [{"t": "今殴民而归之农,皆著于本。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "本富", "t": "指经营农业致富"}, {"w": "本穑", "t": "犹稼穑"}, {"w": "本农", "t": "农业。古以农为本"}, {"w": "本业", "t": "指农业。"}]}, {"meaning": "底本。", "cites": [{"t": "今存其本不忍废。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "本文;稿本;脚本;话本;剧本;歌本", "t": ""}]}, {"meaning": "原来的;本来的。", "cites": [{"t": "此之谓失其本心。", "b": "《孟子》"}], "words": [{"w": "本处", "t": "原籍"}, {"w": "本贯", "t": "原籍"}, {"w": "本事", "t": "原本的事情。"}]}, {"meaning": "推究,推原。", "cites": [{"t": "抑本其成败之迹。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "本原", "t": "推究,推本溯源"}, {"w": "本察", "t": "推究,探究。"}]}, {"meaning": "自己或自己方面的。", "cites": [{"t": "本姓曹。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "本里", "t": "自己的乡里"}, {"w": "本宅", "t": "自己的住宅,自己的墓穴"}, {"w": "本乡,本市,本埠,本省,本队", "t": ""}]}, {"meaning": "这,那。", "cites": [{"t": "用芽者自从本说。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "本山", "t": "此山"}, {"w": "本法", "t": "这项法律"}, {"w": "本处", "t": "此地,此处。"}]}, {"meaning": "用于植物。株;棵。", "cites": [{"t": "一边种几本大芭蕉。", "b": "《红楼梦》"}], "words": [{"w": "二十本葱", "t": ""}]}, {"meaning": "原先,本来。", "cites": [{"t": "臣本布衣。", "b": "诸葛亮《出师表》"}, {"t": "本在冀州之南。", "b": "《列子·汤问》"}, {"t": "自言本是京城女。", "b": "唐·白居易《琵琶行(并序)》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('211wx','术','1','shù zhú','木','5','','[{"pinyin": "shù", "defs": [{"meaning": "(形声。从行,术声。行,甲骨文中指道路。本义:城邑中的道路)。"}, {"meaning": "同本义。", "cites": [{"t": "術,邑中道也。", "b": "《说文》"}, {"t": "术,道也。", "b": "《广雅》"}, {"t": "审端径术。", "b": "《礼记·月令》"}, {"t": "园圃术路。", "b": "《汉书·刑法志》。注:“大道也。”"}, {"t": "横术何广广兮。", "b": "《汉书·燕刺王旦传》"}, {"t": "归空城兮,狗不吠,鸡不鸣,横术何广兮,固知国中之无人!", "b": "《汉书》"}]}, {"meaning": "泛指街道、道路。", "cites": [{"t": "齐城、高唐当术而大败。", "b": "《孙膑兵法·擒庞涓》"}], "words": [{"w": "术阡", "t": "道路"}, {"w": "术径", "t": "大道与小路"}, {"w": "术路", "t": "大道"}, {"w": "术衢", "t": "道路。"}]}, {"meaning": "方法;策略。", "cites": [{"t": "臣有百胜之术。", "b": "《战国策·魏策》"}, {"t": "叩其术,曰:“是无难,别具本章,狱词无易,但取案末独身无亲戚者二人易汝名。”", "b": "清·方苞《狱中杂记》"}, {"t": "子有何术可导我耶?", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "术法", "t": "方法"}, {"w": "术鹄", "t": "方法与目的。"}]}, {"meaning": "特指君主控制和使用臣下的策略、手段。", "cites": [{"t": "孤不度德量力,欲信大义于天下,而智术浅短,遂用猖獗,至于今日。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "权术;计谋。", "cites": [{"t": "人主之大物,非法则术也。", "b": "《韩非子·难三》"}], "words": [{"w": "术数", "t": "方法和谋略"}, {"w": "术计", "t": "权术计谋"}, {"w": "术略", "t": "韬略;谋略"}, {"w": "术谋", "t": "讲求权术谋略。"}]}, {"meaning": "技艺;业术。", "cites": [{"t": "古之学术道者。", "b": "《礼记·乡饮酒义》"}, {"t": "役民三司盗者,授以击刺之术。", "b": "宋·苏轼《教战守》"}, {"t": "女婉贞,年十九,自幼好武术,习无不精。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "营造术;雕刻术;术道", "t": "才艺之道"}, {"w": "航海术", "t": ""}]}, {"meaning": "法,法律。", "cites": [{"t": "术,法也。", "b": "《广雅》"}, {"t": "不以犯有司正术也。", "b": "《礼记·文王世子》"}, {"t": "故君子操权一正以立术。", "b": "《商君书》"}]}, {"meaning": "学说。", "cites": [{"t": "闻道有先后,术业有专攻,如是而已。", "b": "唐·韩愈《师说》"}, {"t": "窦太后好黄帝、老子言,帝及太子诸窦不得不读《黄帝》《老子》,尊其术。", "b": "《史记·外戚世家》"}]}, {"meaning": "方术。指医、占卜、星相等术艺。", "cites": [{"t": "近塞上之人,有善术者,马无故亡而入胡。", "b": "《淮南子·人间训》"}], "words": [{"w": "术数", "t": "用星占、卜筮、命相、拆字等方术,推测国家和个人的气数及命运"}, {"w": "术法", "t": "法术;方术"}, {"w": "术知", "t": "道术才智"}, {"w": "术者", "t": "术人,以占卜、星相等为职业的人。"}]}, {"meaning": "学习;实践。", "cites": [{"t": "蛾子时而术之。", "b": "《礼记·学记》"}]}, {"meaning": "申述,叙述,记叙。", "cites": [{"t": "昔者暴王作之,穷人术之。", "b": "《墨子·非命下》"}, {"t": "体恭敬而心忠信,术礼义而情爱人。", "b": "《荀子·修身》"}, {"t": "今陛下念思祖考,术追厥功。", "b": "《汉书·贾山传》"}, {"t": "能术远者考之以近。", "b": "陆贾《新语》"}]}, {"meaning": "选择职业。", "cites": [{"t": "孟子曰:“术不可不慎。”信夫!", "b": "方苞《狱中杂记》"}]}]}, {"pinyin": "zhú", "defs": [{"meaning": "白术 。一种产于中国的苍术属多年生草本植物,叶互生,椭圆形或羽裂,边缘有刺状细锯齿,紫红色头状花生于茎顶。", "cites": [{"t": "术,白蓟。", "b": "《尔雅·释草》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('212wx','可','1','kě kè','口','5','','[{"pinyin": "kě", "defs": [{"meaning": "(会意。从口,从丂(供神之架),表示在神前歌唱。“可”似为“歌”字的古文。①本义:唱 ②引申义:许可)。"}, {"meaning": "许可;同意;准许。", "cites": [{"t": "可,许可也。", "b": "《广韵》"}, {"t": "去不我可。", "b": "《诗·小雅·何人斯》"}, {"t": "其殆不可乎?", "b": "《文选·司马相如·难蜀父老》。注:“不可,犹不堪也。”"}, {"t": "距关,毋内诸侯,秦地可尽王也。", "b": "《史记·项羽本纪》"}, {"t": "此人可就见,不可屈致也。", "b": "陈寿《隆中对》"}], "words": [{"w": "不可;可许", "t": "准许"}, {"w": "可传", "t": "可以传后;可以传授;可以流传"}, {"w": "可则", "t": "可作准则"}, {"w": "可风", "t": "可为风范。"}]}, {"meaning": "能够;可以。", "cites": [{"t": "可使以其技鸣。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "可与俱。", "b": "《史记·魏公子列传》"}, {"t": "可以一战。", "b": "《左传·庄公十年》"}, {"t": "可治。", "b": "汉·贾谊《论积贮疏》"}, {"t": "可得闻与?", "b": "《孟子·梁惠王下》(与通“欤”。)"}], "words": [{"w": "可刚可柔", "t": "可以强硬可以温和。指刚柔并用,恩威兼施"}, {"w": "可否", "t": "能不能;可以不可以"}, {"w": "可胜", "t": "岂能忍受。"}]}, {"meaning": "值得,堪。", "cites": [{"t": "可爱者甚藩。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "可歌可泣;可观", "t": "值得观览,有观览的价值"}, {"w": "可矜", "t": "值得怜悯"}, {"w": "可堪", "t": "那堪,怎堪"}, {"w": "可怜相", "t": "值得怜悯的样子。"}]}, {"meaning": "相称;适合。", "cites": [{"t": "其味相反,百皆可于口。", "b": "《庄子·天运》"}], "words": [{"w": "可体", "t": "合身"}, {"w": "可手", "t": "合手,称手"}, {"w": "可式", "t": "正合适"}, {"w": "可愿", "t": "符合愿望的事;符合愿望"}, {"w": "可意种", "t": "如意的人。"}]}, {"meaning": "应当,应该。", "cites": [{"t": "及平长,可娶妻,富人莫可与者。", "b": "《史记·陈丞相世家》"}], "words": [{"w": "可要", "t": "应该,须要。表示期望"}, {"w": "可知道", "t": "须知。"}]}, {"meaning": "病痊愈。", "cites": [{"t": "只见宋江暴病才可,吃不得酒肉。", "b": "《水浒传》"}]}, {"meaning": "善,好。", "cites": [{"t": "阻而鼓之,不亦可乎?", "b": "《左传·僖公二十二年》"}, {"t": "况君前途尚可。", "b": "《世说新语·自新》"}]}, {"meaning": "合意,认为正确,是;对。", "cites": [{"t": "然则古之无变,常之毋易,在常古之可与不可。", "b": "《韩非子》"}]}, {"meaning": "适当。", "cites": [{"t": "[驴]至则无可用。", "b": "柳宗元《黔之驴》"}], "words": [{"w": "可式", "t": "安放得当"}, {"w": "可可", "t": "恰巧"}, {"w": "可恰", "t": "正好,正合适"}, {"w": "可道", "t": "可真是,正是。"}]}, {"meaning": "满的。", "cites": [{"t": "他还是把一肚子话可桶儿的都倒出来。", "b": "《儿女英雄传》"}]}, {"meaning": "可是;却。", "cites": [{"t": "可怎生糊突了盗跖、颜渊。(意思是,可是怎么竟混淆了坏人和好人?跖,传说是春秋末年奴隶起义的首领,过去被诬称为“盗跖”。颜渊,孔子弟子,被推崇为“贤人”。盗跖、颜渊,这里泛指坏人和好人。)", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "劳动艰苦,可大家干劲十足", "t": ""}]}, {"meaning": "大约、近似。", "cites": [{"t": "潭中鱼可百许头,皆若空游无所依。(可百许头,大约有一百来条。)", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "可值千万余。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "重可千斤;年可十八;可四千余人", "t": ""}]}, {"meaning": "表示程度。", "cites": [{"t": "可哀痛。(使人感到哀痛。)", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "可动人了;人可多了", "t": ""}]}, {"meaning": "无义。语助词。", "cites": [{"t": "我孩儿安心,省可烦恼!", "b": "金·董解元《西厢记诸宫调》"}]}, {"meaning": "表被动的助动词。", "cites": [{"t": "可使报秦者。", "b": "《史记·廉颇蔺相如列传》"}]}]}, {"pinyin": "kè", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('213wx','丙','1','bǐng','一','5','','[{"pinyin": "bǐng", "defs": [{"meaning": "(象形。本义:鱼尾。《尔雅·释鱼》曰:‘鱼枕谓之丁,鱼肠谓之乙,鱼尾谓之丙’。乙之象鱼肠,丙之象鱼尾,可无庸说。”)。"}, {"meaning": "鱼尾。", "cites": [{"t": "鱼尾谓之丙。", "b": "《尔雅》"}]}, {"meaning": "假借为天干的第三位,与地支相配,用以纪年、月、日。", "cites": [{"t": "其日丙丁。", "b": "《礼记·月令》"}, {"t": "丙刚丁柔。", "b": "《广雅·释天》"}], "words": [{"w": "丙子、丙戍、丙寅以纪年;丙科", "t": "汉代考试的第三等科目"}, {"w": "丙夜", "t": "即三更。半夜,夜中子时。"}]}, {"meaning": "古代以十干配五方,丙为南方之位,因以指南方。", "cites": [{"t": "丙位南方,万物成炳。", "b": "《说文》"}], "words": [{"w": "丙向", "t": "南向,即朝南。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('214wx','左','1','zuǒ','工','5','','[{"pinyin": "zuǒ", "defs": [{"meaning": "(会意。甲骨文字形,象手的象形。本义:辅佐,从旁帮助"}, {"meaning": "同本义。", "cites": [{"t": "左,手相左助也。", "b": "《说文》。俗字作“佐”。"}, {"t": "以左右民。", "b": "《易·象上传》"}, {"t": "予欲左右有民。", "b": "《虞书》"}, {"t": "实左右商王。", "b": "《诗·商颂·长发》"}, {"t": "以左右刑罚。", "b": "《周礼·士师》"}, {"t": "左右就养无方。", "b": "《礼记·檀弓》。注:“谓扶持之。”"}, {"t": "辅相天地之宜,以左右民。", "b": "《易·泰》"}, {"t": "朕且继礼左助听政。", "b": "《后汉书·殇帝纪》"}]}, {"meaning": "贬谪,从朝廷下放到地方为官。", "cites": [{"t": "左,谪官为左迁。自汉起至唐,亦谓去朝廷为州县曰左迁。", "b": "《增韵》"}], "words": [{"w": "左除", "t": "降级授职"}, {"w": "左降", "t": "贬官"}, {"w": "左退", "t": "降官;贬职"}, {"w": "左宦", "t": "降官;贬职"}, {"w": "左授", "t": "降官;贬职"}, {"w": "左转", "t": "降官;贬职"}, {"w": "左黜", "t": "降官;贬职"}, {"w": "左迁", "t": "降官;贬职"}, {"w": "左官", "t": "降官;贬职。"}]}, {"meaning": "见外,把某人当外人看待。", "cites": [{"t": "今居分之土而官之,是左之也。", "b": "《国语》"}]}, {"meaning": "左手。", "cites": [{"t": "君子阳阳,左执簧,右招我由房,其乐只且。", "b": "《诗·王风·君子阳阳》"}], "words": [{"w": "左书", "t": "左手写字"}, {"w": "左癖", "t": "左撇子。"}]}, {"meaning": "方位名。与“右”相对。", "cites": [{"t": "虚左。", "b": "《史记·魏公子列传》"}], "words": [{"w": "左侍下", "t": "左边"}, {"w": "左势下", "t": "左边"}, {"w": "左符", "t": "符契的左半"}, {"w": "左驸", "t": "车箱左侧的立木"}, {"w": "左骖", "t": "左马。三马驾车中左边的马。"}]}, {"meaning": "地理上常以东为左。", "cites": [{"t": "疾逸道左。", "b": "唐·李朝威《柳毅传》"}, {"t": "淮左名都。", "b": "宋·姜夔《扬州慢》"}, {"t": "左天都。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "山左", "t": "太行山以东的地方,过去也专指山东省"}, {"w": "江左;左畔", "t": "东方"}, {"w": "左序", "t": "东厢房"}, {"w": "左海", "t": "海居于东;东海。"}]}, {"meaning": "后多泛指旁边。", "cites": [{"t": "臣以臣守有职,不得攀号于道左。", "b": "欧阳修文"}], "words": [{"w": "左邻", "t": "左近。邻近,附近。"}]}, {"meaning": "在直书而左行的文字中,特指右后。", "cites": [{"t": "复作故事滑稽之语六章,编之于左。", "b": "《史记》"}]}, {"meaning": "证据;证人。", "cites": [{"t": "廷尉定国考问,左验明白。", "b": "《汉书》"}, {"t": "帝愈,召洎问状,洎引马周为左。", "b": "《新唐书·刘洎传》"}], "words": [{"w": "左验", "t": "左证。证人;证据。"}]}, {"meaning": "御者,赶车的人。", "cites": [{"t": "左旋右抽,中军作好。", "b": "《诗·郑风·清人》"}]}, {"meaning": "偏僻,离中心城市很远。", "cites": [{"t": "足下所治僻左,书问致简,益用增劳。", "b": "曹丕《与吴质书》"}]}, {"meaning": "不正,偏邪。", "cites": [{"t": "左,人道尚右,以右为尊,故非正之术曰左道。", "b": "《增韵》"}], "words": [{"w": "左道", "t": "邪门旁道。多指非正统的巫蛊、方术等"}, {"w": "左道术", "t": "邪法。"}]}, {"meaning": "向左。", "cites": [{"t": "欲左,左。", "b": "《史记·殷纪》"}], "words": [{"w": "左回", "t": "向左方旋转"}, {"w": "左射", "t": "向左方射"}, {"w": "左衽", "t": "衣襟向左"}, {"w": "左转", "t": "向左方旋转"}, {"w": "左顾", "t": "向左方观看。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('215wx','厉','1','lì','厂','5','','[{"pinyin": "lì", "defs": [{"meaning": "(是“砺”的本字。从厂(hàn),象山崖形,表示与山石有关。本义:磨刀石)。"}, {"meaning": "同本义。", "cites": [{"t": "段注:“旱石者,刚于柔石者也。字亦作厲、作礪。”朱骏声曰:“精者曰厎,粗者曰厉。汉书地理志,述禹贡砥厉砮丹;诗公刘,取厉取锻,礼内则,刀砺;西山经,苕水其中多砥厉;中山经,阴山多砺石。”", "b": ""}, {"t": "涉渭为乱,取厉取锻。", "b": "《诗·大雅》。陆德明《经典释文》:“厉,本又作砺。”"}]}, {"meaning": "祸患;危险。", "cites": [{"t": "降此大厉。", "b": "《诗·大雅·瞻卬》"}], "words": [{"w": "厉阶", "t": "祸端。"}]}, {"meaning": "恶鬼。", "cites": [{"t": "晋侯梦大厉。", "b": "《左传·成公十年》"}]}, {"meaning": "疠,瘟疫,传染病。", "cites": [{"t": "盗贼公行,而天厉不戒。", "b": "《左传·襄公三十一年》"}, {"t": "漆身为厉。", "b": "《史记·范蔡传》"}, {"t": "鲜不为厉。", "b": "文天祥《正气歌》"}]}, {"meaning": "河岸,水旁;边。", "cites": [{"t": "有狐绥绥,在彼淇厉。", "b": "《诗·卫风·有狐》"}]}, {"meaning": "带,衣带的下垂部分。", "cites": [{"t": "垂带而厉。", "b": "《诗·小雅·都人士》"}, {"t": "鞶厉游缨。", "b": "《左传·桓公二年》"}, {"t": "带之垂者谓之厉。", "b": "《小尔雅·广服》"}]}, {"meaning": "(lài)。恶疮。", "cites": [{"t": "豫让又漆身为厉,吞炭为哑。", "b": "《史记·刺客列传》"}]}, {"meaning": "磨,磨快。", "cites": [{"t": "厉,磨也。", "b": "《广雅》"}, {"t": "砥厉廉隅。", "b": "《礼记·儒行》"}, {"t": "钝金必将待砻厉然后利。", "b": "《荀子·性恶》"}, {"t": "砺所以致刃也。", "b": "《说苑·建本》"}, {"t": "缀甲厉兵。", "b": "《战国策·秦策》"}, {"t": "束载厉兵秣马。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "厉兵", "t": "磨砺兵器,使锋利"}, {"w": "厉兵秣马", "t": "磨快兵器喂饱马。指作好战斗准备"}, {"w": "厉身", "t": "磨砺自身。"}]}, {"meaning": "砥砺,磨练。", "cites": [{"t": "参之谷梁氏以厉其气。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "厉行", "t": "砥砺操行"}, {"w": "厉操", "t": "砥砺节操。"}]}, {"meaning": "振奋。", "cites": [{"t": "坚甲厉兵以备难。", "b": "《韩非子·五蠹》"}, {"t": "矫翼厉翮。", "b": "扬雄《解嘲》"}], "words": [{"w": "厉翼", "t": "奖励辅佐君王的左右臣子"}, {"w": "厉节", "t": "激厉其气节,高其气节"}, {"w": "厉武", "t": "振奋武备"}, {"w": "厉精", "t": "振奋精神"}, {"w": "厉精更始", "t": "振奋精神,从事革新。"}]}, {"meaning": "激励,勉励。", "cites": [{"t": "故明主厉廉耻,招仁义。", "b": "《韩非子·用人》"}, {"t": "亲秉旄钺,以厉三军。", "b": "陈寿《三国志》"}], "words": [{"w": "厉世", "t": "激励世人"}, {"w": "厉俗", "t": "激励世俗"}, {"w": "厉诚", "t": "激励忠诚"}, {"w": "厉崇", "t": "勉励推重"}, {"w": "厉抚", "t": "勉励抚慰"}, {"w": "厉志", "t": "激励意志。"}]}, {"meaning": "连衣涉水。", "cites": [{"t": "越壑厉水。", "b": "司马相如《上林赋》"}], "words": [{"w": "厉揭", "t": "提起衣服涉水"}, {"w": "厉涉", "t": "连衣涉水"}, {"w": "厉度", "t": "涉水而过。"}]}, {"meaning": "策,鞭打。", "cites": [{"t": "厉马登高登高堤。", "b": "曹植《白马篇》"}]}, {"meaning": "警惕。", "cites": [{"t": "赐尚方斩马剑,断佞臣一人,以厉其余", "b": "《汉书》"}]}, {"meaning": "疾飞。", "cites": [{"t": "鹰隼横厉。", "b": "《汉书·息夫躬传》"}]}, {"meaning": "害;虐害;损害。", "cites": [{"t": "今也滕有仓禀府库,则是厉民而自养也。", "b": "《孟子·滕文公上》"}]}, {"meaning": "得传染病。", "cites": [{"t": "苗死,民厉。", "b": "《管子》"}]}, {"meaning": "变为恶鬼。", "cites": [{"t": "国为虚厉。", "b": "《庄子》"}]}, {"meaning": "严厉(威严不随和)。", "cites": [{"t": "子温而厉。", "b": "《论语·述而》"}, {"t": "色厉而内荏。", "b": "《论语·阳货》"}, {"t": "行峻而言厉。", "b": "韩愈《答尉迟生书》"}, {"t": "袁正色厉声。", "b": "清·梁启超《谭嗣同传》"}, {"t": "乘其厉声以呵。", "b": "明·张溥《五人墓碑记》"}, {"t": "应元厉声曰。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "声色俱厉;厉言", "t": "声色严厉地说话"}, {"w": "厉音", "t": "声音严厉"}, {"w": "厉气", "t": "严厉的神色"}, {"w": "厉禁", "t": "圈定范围,禁止他人侵入。后也用作严禁的意思"}, {"w": "厉直", "t": "严肃正直"}, {"w": "正颜厉色;厉肃", "t": "厉然。严肃。"}]}, {"meaning": "猛烈。", "cites": [{"t": "余寒犹厉。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "厉厉", "t": "寒风猛烈貌"}, {"w": "厉风", "t": "大风;烈风。"}]}, {"meaning": "恶,凶恶。", "cites": [{"t": "今梦黄熊入于寝门,其何厉鬼也?", "b": "《左传·昭公七年》"}]}, {"meaning": "危险。", "cites": [{"t": "有厉告自邑。", "b": "《易·夬·卦辞》"}]}, {"meaning": "味道浓烈。", "cites": [{"t": "厉而不爽些。", "b": "《楚辞·招魂》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('216wx','石','1','dàn shí','石','5','','[{"pinyin": "dàn", "defs": [{"meaning": "容量单位,十斗为一石。", "cites": [{"t": "十斗为一石。", "b": "《说苑·辨物》"}, {"t": "关石和钧。", "b": "《国语·周语》。注:“今之斛也。”"}, {"t": "一石沙,几斤重,朝载暮载将何用?", "b": "唐·白居易《官牛》"}]}, {"meaning": "重量单位,一百二十市斤为一石。", "cites": [{"t": "三十斤为钧,四钧为石。", "b": "《汉书·律历志上》"}, {"t": "重不过石。", "b": "《国语·周语》。注:“百二十斤也。”"}]}]}, {"pinyin": "shí", "defs": [{"meaning": "(象形。甲骨文字形。右象岩角,左象石块。“石”是汉字的一个部首。本义:山石)。"}, {"meaning": "同本义。", "cites": [{"t": "石,山石也。在厂之下,口象形。", "b": "《说文》"}, {"t": "它山之石。", "b": "《诗·小雅·鹤鸣》"}, {"t": "山体曰石。", "b": "《释名》"}, {"t": "介于石。", "b": "《易·豫》"}, {"t": "艮为小石。", "b": "《易·说卦传》"}, {"t": "原声石。", "b": "《周礼·典同》"}, {"t": "慈石召铁或引之也。", "b": "《吕氏春秋·精通》"}, {"t": "大夫有石材,庶人有石承。", "b": "《书·大传》。注:“石材,柱下质;石承,当柱下而已。”"}, {"t": "吾师肺肝,皆铁石所铸造也。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "石田", "t": "石多不可耕种的田,比喻不会生育的妇女"}, {"w": "石髓", "t": "钟乳石"}, {"w": "石头记", "t": "《红楼梦》之本名"}, {"w": "石头城", "t": "故址在今南京市清凉山,简称“石城”。后用以代指金陵或南京"}, {"w": "石子甬路", "t": "用鹅卵石铺成的甬路"}, {"w": "石桥三港", "t": "三孔的石桥。港:桥下的涵洞"}, {"w": "石灰布袋", "t": "比喻到处生事、惹祸,留下不好影响的人。"}]}, {"meaning": "石刻,碑碣。", "cites": [{"t": "哀斯墓之徒有其石也而为之记,死生之大,匹夫之有重于社稷也。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "石牛", "t": "石雕之牛"}, {"w": "石人,石像", "t": "石雕的人像"}, {"w": "石鲸", "t": "石雕的鲸鱼"}, {"w": "石璧", "t": "石雕的璧"}, {"w": "石驼", "t": "石刻的骆驼"}, {"w": "石犀", "t": "石刻的犀牛"}, {"w": "石本", "t": "石刻的拓本"}, {"w": "石碣", "t": "圆顶的石碑"}, {"w": "石铭", "t": "刻有文字的碑石。"}]}, {"meaning": "指矿物类药物。亦指道教用矿石炼的所谓长生的药。", "cites": [{"t": "禁芳草石药。", "b": "《素问·腹中论》。注:“石药,英乳也。”"}], "words": [{"w": "石水", "t": "矿泉水,亦泛指泉水"}, {"w": "石肝", "t": "一种矿石,可作美容药服用"}, {"w": "石药", "t": "指矿物类药物。"}]}, {"meaning": "石磬,古乐器名,八音之一。", "cites": [{"t": "歌梁韵金石,舞地委兰麝。", "b": "宋·黄庭坚《寄陈适用》"}]}, {"meaning": "古针,古代的医疗用具。", "cites": [{"t": "石之则狂。", "b": "《素问·腹中论》。注:“以石针开破之。”"}, {"t": "扁鹊怒而投其石。", "b": "《战国策》"}]}, {"meaning": "硬;坚固。", "cites": [{"t": "沉而石者,是肾气内著也。", "b": "《素问》"}], "words": [{"w": "石心", "t": "喻指坚定的意志"}, {"w": "石交", "t": "交谊牢固的朋友"}, {"w": "石骨", "t": "坚硬的岩石"}, {"w": "石镫", "t": "坚固的铠甲。"}]}, {"meaning": "大。", "cites": [{"t": "时奇谲之士、石画之臣甚众。", "b": "《汉书·匈奴传》"}, {"t": "无石师而能言。", "b": "《庄子·外物》"}, {"t": "石者,大也。", "b": "《汉书·律历志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('217wx','右','1','yòu','口','5','','[{"pinyin": "yòu", "defs": [{"meaning": "(会意。从口,从又(手)。口手并用帮助别人。本义:右助。见《说文》。这个意义后来写作“佑”)。"}, {"meaning": "助;帮助。后多作“佑”。", "cites": [{"t": "右,手口相助也。", "b": "《说文》。字亦作佑。"}, {"t": "右者,助也。", "b": "《易·系辞》"}, {"t": "以左右刑罚。", "b": "《周礼·士师》。注:“左右,助也。”"}, {"t": "王右伯舆。", "b": "《左传·襄公十年》。注:“助也。”"}, {"t": "保右命之。", "b": "《诗·大雅·嘉乐》"}], "words": [{"w": "右援", "t": "援助;引荐"}, {"w": "右序", "t": "辅助;佑助"}, {"w": "右饷", "t": "谓享受祭献,佑助降福"}, {"w": "右与", "t": "佑助,帮助。"}]}, {"meaning": "尊崇;崇尚。", "cites": [{"t": "兼爱,尚贤,右鬼,非命,墨子之所立也。", "b": "《淮南子》。高诱注:“右,犹尊也。”"}], "words": [{"w": "右鬼", "t": "尊崇鬼神"}, {"w": "右贤", "t": "尚贤,尊崇贤能"}, {"w": "右文", "t": "崇尚文治"}, {"w": "右武", "t": "崇尚武功。"}]}, {"meaning": "保佑", "cites": [{"t": "祐、右实同字。今据许书,凡助为右、为佑,神助则为祐。", "b": "清·朱骏声《说文通训定声》"}, {"t": "保右命尔。", "b": "《诗·大雅·大明》"}, {"t": "维天其右之。", "b": "《诗·周颂·我将》"}, {"t": "是天反复右我汉国也。", "b": "《汉书·翟义传》"}]}, {"meaning": "劝食。", "cites": [{"t": "一朝右之。", "b": "《诗·小雅·彤弓》"}, {"t": "既右飨之。", "b": "《诗·周颂·我将》"}, {"t": "以享右祭祀。", "b": "《周礼·春官·大祝》"}]}, {"meaning": "右手。", "cites": [{"t": "右秉白旄以麾。", "b": "《书·牧誓》"}, {"t": "范蠡乃左提鼓,右援,以应使者。", "b": "《国语》"}], "words": [{"w": "右口", "t": "中医名词。右手寸口"}, {"w": "右臂", "t": "人大多惯于用右手做事,因以右臂喻事物的要害部分。"}]}, {"meaning": "右手一边的方位,与“左”相对。", "cites": [{"t": "效驾,奋衣由右上。", "b": "《礼记》"}, {"t": "折其右肱。", "b": "《易·丰》"}], "words": [{"w": "右势下", "t": "右边;右旁"}, {"w": "右个", "t": "右侧的偏室"}, {"w": "右文", "t": "汉字形声字中右旁兼声义者称为右文"}, {"w": "右文说", "t": "文字学上一种从声符求字义的学说,形声字大都声旁在右。"}]}, {"meaning": "车右。即参乘,古代战车上站在右边负责警卫的武士。", "cites": [{"t": "菜驹为右。——《左传·僖公三十二——三十三年》", "b": ""}]}, {"meaning": "古代崇右,故以右为上,为贵,为高。", "cites": [{"t": "位在廉颇之右。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "无出其右者(古时以右方的位置为尊,故右指上位)。", "b": "《聊斋志异·促织》"}], "words": [{"w": "右戚", "t": "皇帝贵戚"}, {"w": "右姓", "t": "豪族大姓"}, {"w": "右客", "t": "尊贵的客人"}, {"w": "右地", "t": "要地"}, {"w": "右列", "t": "先贤,有德才的前辈。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('218wx','布','1','bù','巾','5','','[{"pinyin": "bù", "defs": [{"meaning": "(形声。从巾,父声。本义:麻布)。"}, {"meaning": "同本义(古时无棉布)。", "cites": [{"t": "坤为布。", "b": "《易·说卦》"}, {"t": "抱布贸丝。", "b": "《诗·卫风·氓》"}, {"t": "女有余布。", "b": "《孟子》"}, {"t": "果布辐凑而常然。", "b": "左思《吴都赋》"}, {"t": "商祝免袒,执功布入。", "b": "《仪礼·既夕礼记》"}, {"t": "许子必织布而后衣乎?", "b": "《孟子·滕文公》"}], "words": [{"w": "布衣", "t": "平民,老百姓。古时老百姓穿麻布衣服,所以称平为“布衣”"}, {"w": "布槽", "t": "布制的马槽"}, {"w": "布褐", "t": "粗布衣服;又指平民"}, {"w": "布总", "t": "古代丧服,以麻布束发。"}]}, {"meaning": "棉、麻、苎、葛等织物的通称。", "cites": [{"t": "足缠白布。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "土布", "t": "手工纺织的布"}, {"w": "布索", "t": "布制的绳"}, {"w": "布衣交", "t": "贫贱之交"}, {"w": "布裙荆钗", "t": "指民家的女子"}, {"w": "布头笺", "t": "用碎片制成而品质优良的笺纸"}, {"w": "布掸子", "t": "用布条札成的掸帚。"}]}, {"meaning": "古代钱币。", "cites": [{"t": "外府掌邦布之出入。", "b": "《周礼·天官·外府》"}], "words": [{"w": "布儿", "t": "古代钱币的通称。亦作“泉布”"}, {"w": "布缗", "t": "古代用绳子串起来的钱。"}]}, {"meaning": "铺开。", "cites": [{"t": "收葱子,必薄布阴干。", "b": "贾思勰《齐民要术·种葱》"}, {"t": "禹鲧是始布土。", "b": "《山海经·海内经》"}, {"t": "敢私布之。", "b": "《左传·昭公十六年》"}, {"t": "布币行礼。", "b": "《国语·鲁语上》"}]}, {"meaning": "引申为散开,分布。", "cites": [{"t": "天下英豪布在州郡。", "b": "《三国志·吴主权传》"}, {"t": "影布石上。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "布陈", "t": "敷布陈设"}, {"w": "布武", "t": "用小步疾走,使足迹散布,而不相重叠"}, {"w": "布锦", "t": "铺展锦绣。"}]}, {"meaning": "布列。", "cites": [{"t": "千人者布列江岸。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "布阵", "t": "布列阵势"}, {"w": "布兵", "t": "布戎。布甲。布列军队"}, {"w": "布伍", "t": "部署军队。"}]}, {"meaning": "布施;施行。", "cites": [{"t": "阳春布德泽。", "b": "《乐府诗集·长歌行》"}], "words": [{"w": "布德", "t": "广施恩德"}, {"w": "布惠", "t": "布施恩惠"}, {"w": "布化", "t": "施行教化。"}]}, {"meaning": "公布,颁布。", "cites": [{"t": "法者,…设之于官府,而布之于百姓者也。", "b": "《韩非子·难三》"}], "words": [{"w": "布按三司", "t": "布政、按察、都指挥史的总称"}, {"w": "布露", "t": "公布,向众人布告披露"}, {"w": "布谕", "t": "布告晓喻"}, {"w": "布教", "t": "颁布教令。"}]}, {"meaning": "传布。", "cites": [{"t": "上器其能,赐以秘书之副,时书未布。", "b": "《汉书·叙传》"}], "words": [{"w": "布旨", "t": "传布旨意"}, {"w": "布种", "t": "撒籽栽种"}, {"w": "布怨", "t": "播怨,结怨。"}]}, {"meaning": "陈述。", "cites": [{"t": "聊布往怀,君其详之。", "b": "丘迟《与陈伯之书》"}], "words": [{"w": "布达", "t": "陈述表达"}, {"w": "布述", "t": "书信用语。陈述。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('219wx','夯','1','hāng bèn','大','5','','[{"pinyin": "hāng", "defs": [{"meaning": "用力扛东西。", "cites": [{"t": "夯,大用力以肩举物。", "b": "《字汇》"}, {"t": "自家闺阁中物,不肯放下,反累及他人担夯,无乃大劳乎!", "b": "明·净善集《禅林宝训》"}]}, {"meaning": "充胀,胀满。", "cites": [{"t": "有口难言,气夯破胸脯。", "b": "元·王实甫《西厢记》"}]}]}, {"pinyin": "bèn", "defs": [{"meaning": "笨拙。", "cites": [{"t": "小儿蠢夯,自幼失学。", "b": "《儒林外史》"}], "words": [{"w": "夯汉", "t": "干粗笨体力活的人"}, {"w": "夯货", "t": "笨货;蠢人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('220wx','戊','1','wù','戈','5','','[{"pinyin": "wù", "defs": [{"meaning": "古代以十干配五方,戊居十干中,因以指中央。", "cites": [{"t": "五六者,天地之中合。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('221wx','龙','1','lóng','龙','5','','[{"pinyin": "lóng", "defs": [{"meaning": "(象形。甲骨文,象龙形。本义:古代传说中一种有鳞有须能兴云作雨的神异动物)。"}, {"meaning": "同本义。传说中的一种长形、有鳞、有角的神异动物，能走，能飞，能游泳，能兴云作雨。", "cites": [{"t": "龍,鳞虫之长。能幽能明,能细能巨,能短能长。春分而登天,秋分而潜渊。", "b": "《说文》。徐铉注:“象宛转飞动之貌。”饶炯注:“龙之为物,变化无端,说解因着其灵异如此,以能升天,神其物,而命之曰灵。”"}, {"t": "飞龙在天。", "b": "《易·乾》"}, {"t": "麟、凤、龟、龙,谓之四灵。", "b": "《礼记·礼运》"}, {"t": "甲虫三百有六十,而龙为之长。", "b": "《孔子家语·执辔》"}, {"t": "叶公子高好龙。", "b": "刘向《新序·叶公好龙》"}], "words": [{"w": "龙工", "t": "像龙一样熟悉水性之功。也作“龙功”"}, {"w": "龙公", "t": "指龙王,龙神"}, {"w": "龙渊", "t": "龙所栖止的深渊"}, {"w": "龙章", "t": "龙形的图案"}, {"w": "龙蛇", "t": "龙和蛇"}, {"w": "龙文", "t": "龙状花纹"}, {"w": "龙伯", "t": "传说中的水神"}, {"w": "龙沼", "t": "龙池"}, {"w": "龙旌凤翣", "t": "有龙凤图案的旌旗和大掌扇"}, {"w": "龙门", "t": "本是跨在黄河上游的山名。神话传说,鱼类跳过龙门,就可以变成神龙。后借指乡试考场的二门或三门为龙门。"}]}, {"meaning": "封建时代用龙作为皇帝的象征。", "cites": [{"t": "祖龙死,谓始皇也。祖,人之本;龙,人君之象也。", "b": "《论衡·纪妖》"}], "words": [{"w": "龙升", "t": "龙的升子。比喻天子即位"}, {"w": "龙辇", "t": "天子的乘车"}, {"w": "龙颜", "t": "额头隆起似龙。后世以喻皇帝的容貌。也用以指皇帝"}, {"w": "龙腾", "t": "比喻帝王的兴起"}, {"w": "龙鳞", "t": "喻指皇帝或皇帝的威严"}, {"w": "龙驭", "t": "皇帝车驾。代指皇帝"}, {"w": "龙兴", "t": "帝业兴旺;创立帝业"}, {"w": "龙节", "t": "皇帝所授与的符节"}, {"w": "龙衮", "t": "帝王的礼服"}, {"w": "龙下蛋", "t": "比喻不可能"}, {"w": "龙穴", "t": "最适宜埋棺材的好地方"}, {"w": "龙御", "t": "皇帝的车驾"}, {"w": "龙凤", "t": "旧时用以形容帝王的相貌。"}]}, {"meaning": "喻不凡之士,豪杰之士。", "cites": [{"t": "丞尉等并衣冠之龟龙,人物之标准。", "b": "唐·李白《化城寺大钟铭序》"}], "words": [{"w": "龙虎", "t": "比喻杰出的人物"}, {"w": "龙蛇", "t": "比喻非常的人"}, {"w": "龙逸", "t": "如龙隐逸。比喻贤人隐居于野"}, {"w": "龙凤", "t": "比喻才能优异的人"}, {"w": "龙驹", "t": "比喻俊才"}, {"w": "龙鹏", "t": "龙和鹏。比喻贤俊豪杰"}, {"w": "龙翰凤翼", "t": "比喻君子、贤者"}, {"w": "龙蟠凤逸", "t": "比喻才能卓越超群而未为世用的人。"}]}, {"meaning": "喻骏马。", "cites": [{"t": "马八尺以上为龙。", "b": "《周礼·夏官》"}], "words": [{"w": "龙子", "t": "良马名"}, {"w": "龙文", "t": "骏马名"}, {"w": "龙姿", "t": "骏马的形貌"}, {"w": "龙孙", "t": "良马名"}, {"w": "龙驹", "t": "骏马"}, {"w": "龙骥", "t": "骏马"}, {"w": "龙媒", "t": "指天马、骏马。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('222wx','平','1','píng','干','5','','[{"pinyin": "píng", "defs": [{"meaning": "(指事。小篆字形, 从于, 从八。“于”是气受阻碍而能越过的意思, “八”是分的意思, 气越过而能分散, 语气自然平和舒顺。本义: 语气平和舒顺)。"}, {"meaning": "同本义。", "cites": [{"t": "平,语平舒也。", "b": "《说文》"}, {"t": "终和且平。", "b": "《诗·小雅·伐木》"}, {"t": "神气乃平。", "b": "《素问·调经论》"}], "words": [{"w": "平典", "t": "和平典雅"}, {"w": "平度", "t": "平和的法度"}, {"w": "平气", "t": "平和之气"}, {"w": "平远", "t": "谓性情平和,胸襟远大"}, {"w": "平愉", "t": "平和愉悦"}, {"w": "平睦", "t": "犹平和。"}]}, {"meaning": "平坦,没有高低凹凸。", "cites": [{"t": "土治曰平,水治曰清。", "b": "《诗·小雅·黍苗》传"}, {"t": "平,正也。", "b": "《广韵》"}, {"t": "地爱其平。", "b": "《淮南子·本经》。注:“平,正也。”"}, {"t": "将以教民平好恶。", "b": "《吕氏春秋·适音》。注:“平,正也。”"}, {"t": "土地平旷,屋舍俨然。", "b": "晋·陶渊明《桃花源记》"}, {"t": "则以一平板按其面。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "平楚", "t": "平野;又谓从高处远望,丛林树梢齐平"}, {"w": "平展展", "t": "形容平整舒展"}, {"w": "平基", "t": "船上平放的垫板"}, {"w": "平蔚", "t": "平展繁盛"}, {"w": "平川旷野", "t": "广阔的平原田野"}, {"w": "平碧", "t": "一片平展的绿色"}, {"w": "平川地", "t": "平原旷地"}, {"w": "平壤", "t": "平地"}, {"w": "平畴", "t": "平坦的田地"}, {"w": "平阳", "t": "平坦宽敞"}, {"w": "平康", "t": "平坦广大"}, {"w": "平阡", "t": "田间的平坦小路"}, {"w": "平罔", "t": "指山脊平坦处"}, {"w": "平莽", "t": "谓平坦广阔的草原"}, {"w": "平盈", "t": "平坦"}, {"w": "平圃", "t": "平坦的园圃。"}]}, {"meaning": "平安;太平。", "cites": [{"t": "平人者,不病也。", "b": "《素问·平人气象论》"}], "words": [{"w": "清平", "t": "升平。太平"}, {"w": "平裕", "t": "平安充裕"}, {"w": "平不答的", "t": "平平和和的,没有波折"}, {"w": "平靖", "t": "稳定平静"}, {"w": "平吉", "t": "太平安吉"}, {"w": "平善", "t": "平安,安康"}, {"w": "平顺", "t": "平安顺遂;平稳顺畅。"}]}, {"meaning": "均平;齐一。", "cites": [{"t": "水面初平云脚低。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "平夜", "t": "犹半夜"}, {"w": "平春", "t": "仲春"}, {"w": "平火", "t": "亦作“平伙”。谓平均分摊"}, {"w": "平颁", "t": "谓平均分发"}, {"w": "平繇", "t": "平均使用力役"}, {"w": "平概", "t": "使平齐划一"}, {"w": "平富", "t": "均平薄敛。"}]}, {"meaning": "均等。", "cites": [{"t": "从上观之适与地平。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "云行雨施,天下平也。", "b": "《易·乾》"}], "words": [{"w": "平肩", "t": "地位平等"}, {"w": "平牒", "t": "古代职衔相等的方镇平等的互通文牒"}, {"w": "平揖", "t": "本谓双方地位相等,各拱手而不拜"}, {"w": "平状", "t": "犹言对等之礼"}, {"w": "平出平入", "t": "地位平等,可以随意出入。"}]}, {"meaning": "平允,公正。", "cites": [{"t": "昊天不平。", "b": "《诗·小雅·节南山》"}, {"t": "法平则吏无奸。", "b": "《商君书·靳令》"}, {"t": "既和且平。", "b": "《诗·商颂·那》"}], "words": [{"w": "持平", "t": "公正,公平"}, {"w": "不平", "t": "不公平;不公平的事"}, {"w": "平明", "t": "公平明察;天刚亮的时候"}, {"w": "平粜", "t": "平价出售"}, {"w": "平扑扑", "t": "形容很平常"}, {"w": "平情", "t": "冷静;公平"}, {"w": "平虚", "t": "虚心平允"}, {"w": "平格", "t": "公正至善"}, {"w": "平干", "t": "公正干练"}, {"w": "平狱", "t": "公正判案"}, {"w": "平肃", "t": "公正严肃。"}]}, {"meaning": "平地,平整土地。", "cites": [{"t": "原隰既平。", "b": "《诗·小雅·黍苗》"}, {"t": "子子孙孙无穷匮也,而山不加增,何苦而不平。", "b": "《列子·汤问》"}], "words": [{"w": "平了三亩地;平济", "t": "治理"}, {"w": "平塞", "t": "填平。"}]}, {"meaning": "平定;平息。", "cites": [{"t": "丧乱既平。", "b": "《诗·小雅·常棣》"}, {"t": "今北土未平,马超、韩遂尚在关西,为操后患。", "b": "《资治通鉴》"}, {"t": "平夷狄之乱。", "b": "《淮南子·泛论》"}, {"t": "以佐王平邦国。", "b": "《周礼·大司马》"}], "words": [{"w": "扫平", "t": "扫荡平定"}, {"w": "讨平", "t": "讨伐平定"}, {"w": "平忽", "t": "平息;平静"}, {"w": "平一", "t": "平定统一"}, {"w": "平收", "t": "平定,收捕"}, {"w": "平除", "t": "平定而根除之"}, {"w": "平涤", "t": "平定荡涤"}, {"w": "平荡", "t": "扫荡平定"}, {"w": "平灭", "t": "用武装镇压消灭"}, {"w": "平讨", "t": "讨伐平定。"}]}, {"meaning": "评论。", "cites": [{"t": "大事当共平议。", "b": "《三国志·魏书·杜畿传》"}, {"t": "平《公羊》、《谷梁》同异。", "b": "《汉书·瑕丘江公传》"}, {"t": "事成,以传示天下,与海内平之。", "b": "《汉书·王莽传上》"}], "words": [{"w": "平章", "t": "评议;商量"}, {"w": "平章政事", "t": "丞相"}, {"w": "平说", "t": "陈说评论"}, {"w": "平画", "t": "评议谋划"}, {"w": "平道", "t": "犹评议,评说"}, {"w": "平注", "t": "评注。评论注解"}, {"w": "平脏", "t": "平定赃物的价值"}, {"w": "平铨", "t": "比较评量"}, {"w": "平论", "t": "评论。"}]}, {"meaning": "媾和;和好。", "cites": [{"t": "平戎于王。", "b": "《左传·僖公十二年》。注:“和也。”"}, {"t": "平陈与宋。", "b": "《诗·邶风·击鼓》"}], "words": [{"w": "平戎", "t": "原谓与戎人媾和。后指对外族采取和解政策,或平定外族。"}]}, {"meaning": "标准。", "cites": [{"t": "以法为平。", "b": "叶适《故大理正知袁州罗公墓志铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('223wx','灭','1','miè','火','5','','[{"pinyin": "miè", "defs": [{"meaning": "(形声。从水,威(xuè)声。简化字“灭”为会意,从“一”从“火”,“一”表示覆压火上。本义:消灭;灭亡)。"}, {"meaning": "同本义。", "cites": [{"t": "灭,尽也。", "b": "《说文》"}, {"t": "灭,绝也。", "b": "《尔雅·释诂》"}, {"t": "国之灭亡无日矣。", "b": "《礼记·乐记》"}, {"t": "家有既亡,国有既灭。", "b": "《谷梁传·襄公六年》"}, {"t": "以小畜大灭。", "b": "《吕氏春秋·情势》"}, {"t": "谁得而族灭也?", "b": "杜牧《阿房宫赋》"}, {"t": "六国破灭,非兵不利,战不善,敝在赂秦。", "b": "苏洵《六国论》"}, {"t": "秦皇灭典,亦造仙诗", "b": "《文心雕龙·明诗》"}, {"t": "灭韩亡魏。", "b": "《战国策·魏策》"}], "words": [{"w": "灭于绛;一朝而灭;灭亲", "t": "断绝亲族间的关系"}, {"w": "灭户", "t": "全家皆死,宗嗣断绝"}, {"w": "消灭", "t": "使消灭;除掉;灭亡"}, {"w": "毁灭", "t": "摧毁消灭"}, {"w": "灭夷", "t": "消灭"}, {"w": "灭劫", "t": "毁灭的灾难。"}]}, {"meaning": "消失,隐没。", "cites": [{"t": "何(荷)校(木枷)灭耳。", "b": "杜甫《戏为六绝句》"}, {"t": "尔曹身与名俱灭。", "b": ""}], "words": [{"w": "灭抹", "t": "埋没"}, {"w": "灭名", "t": "名誉尽失"}, {"w": "灭身", "t": "丧身,毁灭自身"}, {"w": "灭没", "t": "湮没;隐没"}, {"w": "灭景", "t": "隐没形影,指隐居。"}]}, {"meaning": "熄灭。", "cites": [{"t": "火不灭。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "灭却", "t": "熄灭"}, {"w": "灭息", "t": "熄灭。"}]}, {"meaning": "淹没。", "cites": [{"t": "过涉灭顶。", "b": "《易·大过》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('224wx','轧','1','yà zhá gá','车','5','','[{"pinyin": "yà", "defs": [{"meaning": "(形声。从车,本义:辗压)。"}, {"meaning": "同本义。", "cites": [{"t": "轧,辗也。", "b": "《说文》"}, {"t": "罪小者轧。", "b": "《史记·匈奴传》。汉书注:“辗辗其骨节。若今之压踝者。”"}, {"t": "鳃鳃然常恐天下之一合而轧己也。", "b": "《汉书·刑法志》"}], "words": [{"w": "把路面轧一下", "t": ""}]}, {"meaning": "排挤,倾轧。", "cites": [{"t": "名也者,相轧也。", "b": "《庄子·人间世》"}]}, {"meaning": "委曲。", "cites": [{"t": "轧,辞也。", "b": "《谷梁传·宣公十九年》。注:“谓委曲也。”"}], "words": [{"w": "轧辞", "t": "委曲之辞。"}]}]}, {"pinyin": "zhá", "defs": [{"meaning": "把金属坯压成一定形状", "words": [{"w": "轧钢", "t": ""}]}]}, {"pinyin": "gá", "defs": [{"meaning": "挤入;拥挤", "words": [{"w": "轧米", "t": "[方言] 在拥挤的情况下争购食米"}]}, {"meaning": "结交", "words": [{"w": "轧朋友", "t": "结交朋友"}]}, {"meaning": "核查", "words": [{"w": "轧账", "t": "核算查对账目"}]}, {"meaning": "象声词", "words": [{"w": "轧拉", "t": "形容物体摩擦或受压力后而发出的声音"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('225wx','东','1','dōng','一','5','','[{"pinyin": "dōng", "defs": [{"meaning": "(会意。从木,官溥说,从日在木中。本义:东方,日出的方向)。"}, {"meaning": "同本义。", "cites": [{"t": "东,动也。", "b": "《说文》"}, {"t": "东方者,动方也,万物始动生也。", "b": "《白虎通·五行》"}, {"t": "东方木也。", "b": "《淮南子·天文训》。按:“日所出也。从日在木中,会意。”"}, {"t": "东君,日也。", "b": "《广雅·释天》"}, {"t": "东邻。", "b": "《易·既济》。虞注:“震为东。”"}, {"t": "东方者,阳也。", "b": "《白虎通·情性》"}, {"t": "大儿锄豆溪东,中儿正织鸡笼。", "b": "宋·辛弃疾《清平乐·村居》"}], "words": [{"w": "关东;旭日东升;东夏", "t": "指中国东部"}, {"w": "东朝", "t": "东宫"}, {"w": "东极", "t": "东方边远之处"}, {"w": "东君", "t": "神话中与西王母相对的东王公"}, {"w": "东坦", "t": "女婿"}, {"w": "东裔", "t": "东方边远地方"}, {"w": "东村女", "t": "即东施"}, {"w": "东方作", "t": "日出"}, {"w": "东记", "t": "古代传说中的日出处。亦泛指东方极远之地。"}]}, {"meaning": "向东,东去。", "cites": [{"t": "大江东去,浪淘尽,千古风流人物。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "东流", "t": "东去的流水"}, {"w": "东波", "t": "向东流逝之水"}, {"w": "东徙", "t": "向东迁移。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('226wx','卡','1','kǎ qiǎ','丨','5','','[{"pinyin": "kǎ", "defs": [{"meaning": "卡路里的简称。"}]}, {"pinyin": "qiǎ", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('227wx','北','1','běi','匕','5','','[{"pinyin": "běi", "defs": [{"meaning": "方位名。与“南”相对。", "cites": [{"t": "人坐立皆面明背暗,故以背为南北之北。", "b": "朱骏声《说文通训定声》"}, {"t": "万物负阴而抱阳。", "b": "《老子》。王力按,山北为阴,山南为阳,老子的话等于说万物负背而抱南。"}, {"t": "然则北通巫峡。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "南声函胡,北音清越。", "b": "宋·苏轼《石钟山记》"}, {"t": "沛公北向坐。", "b": "《史记·项羽本纪》"}, {"t": "又北向。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "正北;西北;东北;北邙", "t": "即氓山。在河南洛阳市北。东汉及魏晋的王侯公卿多葬于此。泛指墓地"}, {"w": "北闱(清代在顺天(今北京)的乡试称“北闱”,在江宁(今南京)的乡试称“南闱”", "t": ""}, {"w": "北里", "t": "妓院"}, {"w": "北阙", "t": "皇宫。借指帝王"}, {"w": "北鄙", "t": "北方的边邑"}, {"w": "北雍", "t": "北京的国子监"}, {"w": "北邙乡女", "t": "代指死去的女性"}, {"w": "北津", "t": "北方的渡口。"}]}, {"meaning": "败逃的军队。", "cites": [{"t": "燕兵独追北,入至临淄。", "b": "《战国策·燕策一》"}]}, {"meaning": "败北。", "cites": [{"t": "连战皆北。", "b": "《史记·项羽本纪》"}, {"t": "鲁人从君战,三战三北。", "b": "《韩非子·五蠹》"}]}, {"meaning": "败逃。", "cites": [{"t": "追亡逐北,伏尸百万。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('228wx','占','1','zhān zhàn','卜','5','','[{"pinyin": "zhān", "defs": [{"meaning": "(会意。从卜,从口。以口问卜。本义:推测吉凶,即察看甲骨的裂纹或蓍草排列的情况取兆推测吉凶)。"}, {"meaning": "同本义。", "cites": [{"t": "占,视兆问也。", "b": "《说文》"}, {"t": "未占有孚。", "b": "《易·萃》"}, {"t": "极数知来之谓占。", "b": "《易·系辞》"}, {"t": "三人占。", "b": "《书·洪范》"}, {"t": "占者三人。", "b": "《仪礼·士丧礼》。注:“三人,掌玉兆、瓦兆、原兆者也。”"}, {"t": "占衿兆。", "b": "《荀子·王制》"}, {"t": "以制器者尚其象,以卜筮者尚其占。", "b": "《易·系辞上》"}, {"t": "史苏占之,曰:不吉。", "b": "《左传·僖公十五年》"}], "words": [{"w": "占旺相", "t": "占卜时运"}, {"w": "占人", "t": "掌占卜的官员"}, {"w": "占工", "t": "占者。占家。专门从事占卜的人"}, {"w": "占术", "t": "占卜之术"}, {"w": "占书", "t": "占卜的书。"}]}, {"meaning": "占状(报告观测天象结果的奏状);占视(观察);占气(观云气风色以测吉凶)。"}, {"meaning": "推料,推测。", "cites": [{"t": "史以天占人,圣人以人占天。", "b": "《法言·五百》"}], "words": [{"w": "占候", "t": "推测气候变化"}, {"w": "占射", "t": "猜测"}, {"w": "占覆", "t": "猜度隐藏之物。"}]}, {"meaning": "估计;揣度。", "cites": [{"t": "度食不足,令民各自占家五种石斗数,为其期。", "b": "《墨子·号令》"}], "words": [{"w": "占费", "t": "估量费用"}, {"w": "占卖", "t": "估价出卖。"}]}, {"meaning": "征兆。", "cites": [{"t": "山崩川竭,国土将亡之占也。", "b": "《水经注》"}]}, {"meaning": "运数,运气。", "cites": [{"t": "顺天地之纪,幽明之占。", "b": "《史记》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhàn", "defs": [{"meaning": "占据,拥有。也作“佔”。", "cites": [{"t": "又改曰占。", "b": "宋·洪迈《容斋续笔》"}, {"t": "占一山之胜。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "占百户之田。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "占护", "t": "霸占"}, {"w": "霸占土地;独占公家的房子;占固", "t": "强占把持"}, {"w": "占冒", "t": "强占冒领。"}]}, {"meaning": "自报数目,估计上报。", "cites": [{"t": "度食不足,令民各自占家五种石斗数…匿不占,占不悉,令吏卒讏得,皆断。", "b": "《墨子》"}], "words": [{"w": "占租", "t": "自报应纳的租税"}, {"w": "占募", "t": "报名应募。"}]}, {"meaning": "估计、测算。", "cites": [{"t": "料丁壮以计庸,占商贾以均利。", "b": "《新唐书》"}]}, {"meaning": "口头吟作;口授。", "cites": [{"t": "一夜无寐,口占几句俚谈,权表谢意。", "b": "《西游记》"}], "words": [{"w": "占毕", "t": "诵读,吟诵"}, {"w": "占授", "t": "口授"}, {"w": "占辞", "t": "口述言辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('229wx','凸','1','tū','凵','5','','[{"pinyin": "tū", "defs": [{"meaning": "高出。高于周围的,如球形或圆形的外部或其一部分那样弯曲的 -- 指从外面观看一个球面或曲线。", "words": [{"w": "凸兀", "t": "高出"}, {"w": "凸凸", "t": "高出貌"}, {"w": "凸凹", "t": "高低不平"}, {"w": "凸凸囊囊", "t": "犹鼓鼓囊囊"}]}, {"meaning": "〖指月亮或行星〗可见的光亮部分大于半圆而不是全部的", "words": [{"w": "凸月", "t": ""}]}, {"meaning": "使突出于周围表面或范围之外", "words": [{"w": "凸起", "t": "突出;高起"}, {"w": "凸露", "t": "高出于外"}, {"w": "凸显", "t": "凸出显露"}, {"w": "凸出", "t": "高出;高起"}]}, {"meaning": "伸出;突出"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('230wx','卢','1','lú','卜','5','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。甲骨文字形,从皿,虎声。本义:饭器)。"}, {"meaning": "同本义。", "cites": [{"t": "卢,饭器也。", "b": "《说文》"}]}, {"meaning": "房屋。", "cites": [{"t": "君卢屋妾。", "b": "《荀子·富国》"}]}, {"meaning": "瞳人。", "cites": [{"t": "玉女无所眺其清卢兮。", "b": "《汉书·扬雄传》"}]}, {"meaning": "头盖骨。", "cites": [{"t": "蹶蹏足以破卢陷匈。", "b": "《淮南子·修务》"}]}, {"meaning": "黑色。", "cites": [{"t": "卢弓一。", "b": "《书·文侯之命》"}, {"t": "是犹绁韩卢而责之获也。", "b": "《汉书·王莽传下》。师古曰:“韩卢,古韩国之名犬也。黑色曰卢。”"}, {"t": "卢奴城内西北隅有水,渊而不流,…水色正黑,俗名曰‘黑水池’。水黑曰卢,不流曰奴,故此城藉水以取名矣。", "b": "《水经注·滱水》"}, {"t": "上九。与荼有守,辞于卢首不殆。", "b": "汉·扬雄《太玄经》。范望注:荼,白也;卢,黑也。"}, {"t": "于是乎卢橘夏熟。", "b": "《史记·司马相如传》"}], "words": [{"w": "卢弓;卢矢;卢瞳", "t": "黑眼珠"}, {"w": "卢狗", "t": "即韩卢。战国时韩国良犬"}, {"w": "卢猎", "t": "即卢鹊"}, {"w": "卢鹊", "t": "古代良犬韩卢、宋鹊的并称。亦泛指良犬"}, {"w": "卢卢", "t": "呼犬声。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('231wx','业','1','yè','业','5','','[{"pinyin": "yè", "defs": [{"meaning": "(象形。从丵(zhuó),从巾丛生草。巾象版。本义:古时乐器架子横木上的大版,刻如锯齿状,用来悬挂钟磬)。"}, {"meaning": "版,大版。"}, {"meaning": "古代覆在悬挂钟、鼓等乐器架横木上的装饰物,刻如锯齿形,涂以白色。", "cites": [{"t": "業,大版也。所以覆县钟鼓之栒,捷业如锯齿,以白画之。从丵,象其鉏鋙相承也。", "b": "《说文》"}, {"t": "有瞽有瞽,在周之庭。设业,崇牙树羽。", "b": "《诗·周颂·有瞽》。毛传:“业,大板也,所以饰栒为县也…植者为虚,衡者为栒。”"}]}, {"meaning": "筑墙版。", "cites": [{"t": "大版谓之业。绳之,谓之缩之。", "b": "《尔雅》。郭璞注:“筑墙版也。”"}]}, {"meaning": "古代书册之版。", "cites": [{"t": "先生问焉,终则对,请业则起,请益则起。", "b": "《礼记》。郑玄注:“业,谓篇卷也。”"}, {"t": "古人写书用方版,《尔雅》:“大版谓之业”,故书版谓之业", "b": ""}]}, {"meaning": "亦指写字用的业版。"}, {"meaning": "学业。", "cites": [{"t": "复不终业。", "b": "《后汉书·列女传》"}, {"t": "术业有专攻。", "b": "唐·韩愈《师说》"}, {"t": "业有不精。", "b": "明·宋濂《送东阳马生序》"}, {"t": "某业所就。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "卒业;修业;毕业;业行", "t": "学业与德行"}, {"w": "业精于勤", "t": "学业的精进在于勤奋。"}]}, {"meaning": "事业;功业。", "cites": [{"t": "先帝创业未半,而中道崩殂。", "b": "诸葛亮《出师表》"}, {"t": "共济世业。", "b": "《资治通鉴》"}, {"t": "子孙创业。", "b": "清·黄宗羲《原君》"}, {"t": "伊皋之业。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "业祚", "t": "帝业王位"}, {"w": "业峻绩鸿", "t": "功业高,成绩大。"}]}, {"meaning": "家业,产业。", "cites": [{"t": "受赏者甘利,未赏者慕业。", "b": "《韩非子》"}], "words": [{"w": "创业;家大业大;业户", "t": "不动产的所有者。"}]}, {"meaning": "职业。", "cites": [{"t": "各劝其业。", "b": "《史记·货殖列传》"}, {"t": "捕鱼为业。", "b": "晋·陶渊明《桃花源记》"}, {"t": "业是有年。(以是为业)", "b": "明·刘基《卖柑者言》"}, {"t": "为业以求钱。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "正业;副业;就业;业余;业命", "t": "国事与政令。"}]}, {"meaning": "罪孽。", "cites": [{"t": "把业龙擒捉,猛虎拖倒。", "b": "《西厢记诸官调》"}], "words": [{"w": "业罐子满了", "t": "恶贯满盈"}, {"w": "业缘病症", "t": "因前世罪孽而致今世得的病症"}, {"w": "业畜", "t": "造孽的畜生;作恶多端的坏蛋。骂人话"}, {"w": "业冤", "t": "冤孽;冤家。"}]}, {"meaning": "使从事于,以…为职业。", "cites": [{"t": "民卖茶资衣食,与农夫业田无异。", "b": "脱脱《宋史》"}], "words": [{"w": "业贼", "t": "以偷为业"}, {"w": "业网", "t": "以打鱼为业"}, {"w": "业儒", "t": "以儒学为业"}, {"w": "业缝", "t": "以做衣鞋等手艺为业"}, {"w": "业文", "t": "从事文学"}, {"w": "业武", "t": "从事武事"}, {"w": "业商", "t": "经商,从事商业"}, {"w": "业厚", "t": "从善。"}]}, {"meaning": "使成业或乐业。", "cites": [{"t": "曹公闻权以土地业备,方作书,落笔于地。", "b": "《三国志》"}]}, {"meaning": "已经。", "cites": [{"t": "良业为取履,因长跪履之。", "b": "《史记·留侯世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('232wx','旧','1','jiù','日','5','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。甲骨文字形,上面是“萑”(huān),鸱鸟类;下面是“臼”,作声符。本义:鸟名)。"}, {"meaning": "鸺鶹,即猫头鹰。"}, {"meaning": "故交,老交情。", "cites": [{"t": "待之若旧。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "与之有旧。", "b": "清·全祖望《梅花岭记》"}, {"t": "与相国有旧。", "b": "清·周容《芋老人传》"}], "words": [{"w": "怀旧;有旧;念旧;亲戚故旧;旧雨", "t": ""}]}, {"meaning": "原有的典章制度。", "cites": [{"t": "不必循旧。", "b": "《淮南子·泛论》"}], "words": [{"w": "复旧;照旧", "t": ""}]}, {"meaning": "丘冢,坟墓。", "cites": [{"t": "越王不隳旧冢。", "b": "《说苑·尊贤》"}, {"t": "越王不颓旧冢,而越人服。", "b": "《大戴礼·保傅》"}]}, {"meaning": "过时的;陈旧的(跟“新”相对)。", "cites": [{"t": "保守也故永旧。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "旧牌儿", "t": "旧谱子。旧规矩;老样子"}, {"w": "旧楮", "t": "旧纸币"}, {"w": "旧垒", "t": "旧的堡垒、营垒"}, {"w": "旧矩", "t": "老规矩"}, {"w": "旧车;旧衣服;旧流丢", "t": "破旧的样子。"}]}, {"meaning": "从前的;原先的。", "cites": [{"t": "告尔旧止。", "b": "《诗·大雅·抑》"}, {"t": "其旧如之何?", "b": "《诗·豳风·东山》"}, {"t": "非旧器者举毁。", "b": "《礼记·王制》"}, {"t": "还于旧都。", "b": "诸葛亮《出师表》"}, {"t": "风景旧曾谙。", "b": "唐·白居易《忆江南》"}, {"t": "增其旧制。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "临摹旧作。", "b": "蔡元培《图画》"}], "words": [{"w": "旧来", "t": "原来"}, {"w": "旧司", "t": "原来的职守"}, {"w": "旧姻", "t": "原先的配偶"}, {"w": "旧望", "t": "向来的门第"}, {"w": "旧瘴", "t": "原有的瘴气"}, {"w": "旧格", "t": "原来的风格"}, {"w": "旧腊", "t": "去年腊月"}, {"w": "旧恩", "t": "往日的情谊"}, {"w": "旧岁", "t": "去年"}, {"w": "旧家", "t": "从前住过的房宅"}, {"w": "旧志", "t": "从前的抱负"}, {"w": "旧我", "t": "从前的我。"}]}, {"meaning": "长久。", "cites": [{"t": "旧,久也。", "b": "《小尔雅》"}, {"t": "旧井无禽。", "b": "《易·井》"}, {"t": "旧劳于外。", "b": "《书·无逸》"}, {"t": "周虽旧邦。", "b": "《诗·大雅·文王》"}, {"t": "修旧也。", "b": "《公羊传·庆公二十九年》"}], "words": [{"w": "旧邦", "t": "历史长久的国家;故国"}, {"w": "旧人", "t": "久于其位的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('233wx','帅','1','shuài','巾','5','','[{"pinyin": "shuài", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义 ,佩巾也。——《说文》。张舜徽注:“然佩巾之义,经传皆用帨,无用帅者,帅乃为将帅义所专矣。吴楚《说文染指》谓帅字当以将帅为本义。", "cites": [{"t": "无感我帨兮。", "b": "《诗·野有死麕》"}, {"t": "毋施衿结帨。", "b": "《仪礼·士昏礼》"}, {"t": "左佩纷帨。又,女子设帨于门右。", "b": "《礼记·内则》"}]}, {"meaning": "军队中的主将、统帅。", "cites": [{"t": "帅刘良佐拥骑至城下,呼曰:“吾与阎雅故,为我语阎君,欲相见。”", "b": "清·邵长蘅《阎典史传》"}, {"t": "予自度不得脱,则直前诟虏帅失信,数吕师孟叔侄为逆。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "挂帅;帅甸", "t": "甸地的统帅。即公邑的大夫。"}]}, {"meaning": "地方的长官。", "cites": [{"t": "三乡为县,县有县帅。", "b": "《国语·齐语》"}], "words": [{"w": "帅长", "t": "首领"}, {"w": "帅使", "t": "宋代安抚使的别称"}, {"w": "帅司", "t": "宋代对各路安抚司或经略安抚司的通称,掌管一路的兵、民事务。"}]}, {"meaning": "中国象棋棋子中的主将。"}, {"meaning": "指首领或起主导作用的人或事物。", "cites": [{"t": "夫志,气之帅也。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "帅首", "t": "领袖;首领。"}]}, {"meaning": "表率;楷模。", "cites": [{"t": "相国萧、曹以宽厚清净为天下帅。", "b": "《汉书·循吏传序》"}]}, {"meaning": "指总督。清代下级称总督为“大帅”。", "cites": [{"t": "那帅爷又翻出六个字,是帅查确,拟揭参。", "b": "《官场现形记》"}]}, {"meaning": "统率;率领。", "cites": [{"t": "上帅士以人之所戴。", "b": "《管子·问篇》"}, {"t": "命子封帅车二百乘以伐京。", "b": "《左传·隐公元年》"}, {"t": "命李祐、李忠义帅突将三千为前驱。", "b": "《资治通鉴·唐纪》"}, {"t": "我文公帅诸侯及秦围郑。", "b": "《左传·成公十三年》"}], "words": [{"w": "帅厉", "t": "率领激励"}, {"w": "帅示", "t": "教导指示"}, {"w": "帅尔", "t": "率尔"}, {"w": "帅师;帅兵", "t": ""}]}, {"meaning": "引导;带头。", "cites": [{"t": "不立刚毅之心,勇猛之节,亡以帅先士大夫,尤失理不公。", "b": "《汉书·胡建传》"}, {"t": "自谓能以敦厉薄俗,帅之以义。", "b": "诸葛亮《黜来敏教》"}], "words": [{"w": "帅示", "t": "引导指示。"}]}, {"meaning": "遵循。", "cites": [{"t": "命乡简不帅教者以告。", "b": "《礼记·王制》"}, {"t": "不愆不忘,帅由旧章。", "b": "《风俗通义·愆礼》"}], "words": [{"w": "帅繇", "t": "遵循"}, {"w": "帅职", "t": "遵守职责"}, {"w": "帅由旧章", "t": "遵循成法。同率由旧章"}, {"w": "帅意", "t": "循其意志"}, {"w": "帅行", "t": "遵循实行"}, {"w": "帅由", "t": "遵循。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('234wx','归','1','guī kuì','彐','5','','[{"pinyin": "guī", "defs": [{"meaning": "(会意。从止,从婦省。本义:女子出嫁)。"}, {"meaning": "同本义。", "cites": [{"t": "归,女嫁也。", "b": "《说文》"}, {"t": "帝乙归妹。", "b": "《易·泰》"}, {"t": "桃之夭夭,灼灼其华。之子于归,宜其室家。", "b": "《诗·周南·桃夭》(之子:这个女子)"}, {"t": "女有归。", "b": "《礼记·礼运》"}, {"t": "妇人谓嫁曰归。", "b": "《公羊传·隐公二年》"}, {"t": "生女有所归,鸡狗亦得将。", "b": "杜甫《新婚别》"}, {"t": "后五年,吾妻来归,时至轩中,从余问古事。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "返回,回来。", "cites": [{"t": "归,返也。", "b": "《广雅》"}, {"t": "明公归自王。", "b": "西周金文《矢(zhé)令彝》"}, {"t": "分兵断其归津。", "b": "《资治通鉴》"}, {"t": "冠者五六人,童子六七人,浴乎沂,风乎舞雩,咏而归。", "b": "《论语·先进》"}, {"t": "归来见天子,天子坐明堂。", "b": "《乐府诗集·木兰诗》"}, {"t": "大风起兮云飞扬,威加海内兮归故乡。", "b": "《史记·高祖本纪》"}, {"t": "主人忘归客不发。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "归槽", "t": "回家"}, {"w": "归升", "t": "回归天界"}, {"w": "归朝", "t": "回朝"}, {"w": "归本", "t": "返回农耕"}, {"w": "归沐", "t": "回家洗沐。"}]}, {"meaning": "归还。", "cites": [{"t": "久假而不归。", "b": "《孟子·尽心上》"}, {"t": "臣请完璧归赵。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "则其读书也必专,而其归书也必速。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "归事", "t": "交还政权"}, {"w": "归元", "t": "归还人头"}, {"w": "归俗", "t": "还俗"}, {"w": "归业", "t": "回复原来的正业。"}]}, {"meaning": "辞官回家。", "cites": [{"t": "开荒田野际,守拙归园田。", "b": "晋·陶渊明《归园田居》"}], "words": [{"w": "归耕", "t": "辞官归里"}, {"w": "归老", "t": "辞官返回故里养老"}, {"w": "归休", "t": "辞官退休"}, {"w": "归卧", "t": "归林。辞官还乡"}, {"w": "归道", "t": "辞谢师职。"}]}, {"meaning": "死。", "cites": [{"t": "汝生于浙而葬于斯,离吾乡七百里矣,当时虽觭梦幻想,宁知此为归骨所耶?", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "归道山", "t": "死亡"}, {"w": "归阴", "t": "死"}, {"w": "归土", "t": "埋死人于土中"}, {"w": "归休", "t": "死去"}, {"w": "归神", "t": "归天。旧指离开人世,回归神位。"}]}, {"meaning": "合并;归依;归属;归到一处。", "cites": [{"t": "微斯人,吾谁与归?", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "樊将军以贫困来归丹,丹不忍以己之私,而伤长者之意。", "b": "《战国策·燕策》"}, {"t": "我以天下之利尽归于己,以天下之害尽归于人,亦无不可。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "归注", "t": "汇合。"}]}, {"meaning": "趋向;归向。", "cites": [{"t": "况刘豫州王室之胄,英才盖世,众士慕仰,若水之归海。", "b": "《资治通鉴》"}, {"t": "今殴民而归之农,皆著于本。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "归止", "t": "归着,归宿"}, {"w": "归一", "t": "一样"}, {"w": "归市", "t": "涌向集市"}, {"w": "殊途同归", "t": ""}]}, {"meaning": "结算。", "cites": [{"t": "到晚,牛浦回家,问着他,总归不出一个清账。", "b": "《儒林外史》"}]}, {"meaning": "(kuì)。饷,赠送。", "cites": [{"t": "归公乘马,祭服五称。", "b": "《左传·闵公二年》"}], "words": [{"w": "归衣", "t": "赠送衣服。"}]}, {"meaning": "羞惭。", "cites": [{"t": "面目犂黑,状有归色。", "b": "《战国策·秦策》"}]}]}, {"pinyin": "kuì", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('235wx','旦','1','dàn','日','5','','[{"pinyin": "dàn", "defs": [{"meaning": "(指事。甲骨文字形,象太阳从地面刚刚升起的样子。本义:天亮,破晓,夜刚尽日初出时)。"}, {"meaning": "同本义。", "cites": [{"t": "女曰:“鸡鸣”,士曰:“昧旦”。", "b": "《诗·郑风·女曰鸡鸣》"}, {"t": "夜穿墉以视之,达旦忘反。", "b": "《世说新语·贤媛》"}, {"t": "夫犬马,人所知也,旦暮罄于前,不可类之,故难。", "b": "《韩非子·外储说左上》"}, {"t": "旦而战,见星未已。", "b": "《左传·成公十六年》"}, {"t": "号呼达旦。", "b": "清·方苞《狱中杂记》"}, {"t": "旦辞爷娘去,暮宿黄河边。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "旦日", "t": "天亮时"}, {"w": "旦明", "t": "天亮时。"}]}, {"meaning": "早晨。", "cites": [{"t": "旦夕得甘毳以养亲。", "b": "《史记·刺客列传》"}], "words": [{"w": "旦夕之危", "t": "比喻非常迫促的危险"}, {"w": "旦气", "t": "清晨的空气"}, {"w": "旦晚", "t": "早晚。"}]}, {"meaning": "天,日;某日。", "cites": [{"t": "人有卖骏马者,比三旦立市,人莫之知。", "b": "《战国策·燕策》"}], "words": [{"w": "一旦", "t": "一天之间"}, {"w": "元旦", "t": "新年的第一天"}, {"w": "旦昏", "t": "白天与夜晚"}, {"w": "旦昼", "t": "第二天的白天"}, {"w": "旦朝", "t": "次日清早。"}]}, {"meaning": "旦角,传统戏剧中的女演员或女性角色类型。女主角称正旦,又有副旦、贴旦、外旦、小旦、大旦、老旦、花旦、色旦、搽旦等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('236wx','目','1','mù','目','5','','[{"pinyin": "mù", "defs": [{"meaning": "(象形。甲骨文和小篆字形。象眼睛形,外边轮廓象眼眶,里面象瞳孔。小篆处理为线条。先秦时期多用“目”,两汉以后,用眼逐渐多起来。“目”具有书面语色彩。本义:眼睛)。"}, {"meaning": "同本义。", "cites": [{"t": "目,人眼,象形。", "b": "《说文》"}, {"t": "目者,气之清明者也。", "b": "《礼记·郊特牲。》"}, {"t": "目者,心之符也。", "b": "《韩诗外传》"}, {"t": "夫妻反目。", "b": "《易·小畜卦》"}, {"t": "睅其目,皤其腹。", "b": "《左传·宣公二年》"}, {"t": "满目萧然。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "瞋目大怒。", "b": "晋·干宝《搜神记》"}, {"t": "目似瞑。", "b": "《聊斋志异·狼三则》"}, {"t": "目不忍睹。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "目不斜视", "t": "眼睛不向旁边看,形容为人正派"}, {"w": "目见耳闻", "t": "亲眼看见,亲耳听到"}, {"w": "目治手营", "t": "亲眼观察,亲手试验"}, {"w": "目空一世", "t": "什么都不放在眼里。形容骄傲自大"}, {"w": "目眩神摇", "t": "眼花缭乱,心神摇荡"}, {"w": "目无下尘", "t": "眼睛不朝下看。形容态度高傲。下尘,下风,喻指比自己低下的人"}, {"w": "目耗", "t": "眼睛昏花"}, {"w": "目指", "t": "用眼睛示意指点"}, {"w": "目眦", "t": "眼眶"}, {"w": "目珠", "t": "眼球"}, {"w": "目睛", "t": "眼珠"}, {"w": "目精", "t": "眼珠;眼睛。"}]}, {"meaning": "目光;眼力。", "cites": [{"t": "四海注目。", "b": "《晋书·孙惠传》"}], "words": [{"w": "目捷", "t": "目光敏捷"}, {"w": "目击道存", "t": "眼光一接触便知“道”之所在。形容悟性好"}, {"w": "目色", "t": "视力"}, {"w": "目使颔令", "t": "用眼色和下颔示意以役使别人。形容态度骄横"}, {"w": "目注", "t": "目光注视"}, {"w": "目波", "t": "水波似的目光、谓目光流盼如水波"}, {"w": "目逆", "t": "以目光相迎"}, {"w": "目极", "t": "用尽目力远望。"}]}, {"meaning": "孔眼。", "cites": [{"t": "举一纲而万目张。", "b": "郑玄《诗谱序》"}], "words": [{"w": "纲举目张;一个60目的筛", "t": ""}]}, {"meaning": "首领;头目。", "cites": [{"t": "夷目嘉符。", "b": "《广东军务记》"}], "words": [{"w": "目把", "t": "指西南少数民族中的小首领。"}]}, {"meaning": "名目,数目;行列。", "cites": [{"t": "不在使者之目。", "b": "宋·文天祥《后序》"}]}, {"meaning": "观看,注视。", "cites": [{"t": "指目陈胜。", "b": "《史记·陈涉世家》"}, {"t": "指目牵引。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "目过", "t": "过目;细看"}, {"w": "目下十行", "t": "形容看书速度极快"}, {"w": "目及", "t": "看到"}, {"w": "目染", "t": "因经常看见而受到影响"}, {"w": "目笑", "t": "目视而窃笑"}, {"w": "目礼", "t": "以目注视,表示敬意"}, {"w": "目断", "t": "犹望断。一直望到看不见"}, {"w": "目识", "t": "看后即记住"}, {"w": "目属", "t": "瞩目;注视"}, {"w": "目艳", "t": "看到美好的事物而感到羡慕"}, {"w": "目为", "t": "看作。"}]}, {"meaning": "递眼色,使眼。", "cites": [{"t": "酒阑,吕布因目留高祖。", "b": "《史记·高祖本纪》"}, {"t": "数目项王。", "b": "《史记·项羽本纪》"}], "words": [{"w": "目交心通", "t": "以眼色传情,心中相互沟通"}, {"w": "目挑眉语", "t": "以眉目挑逗传情"}, {"w": "目指气使", "t": "用眼神和气色示意,以支使别人。形容态度骄横"}, {"w": "目禁", "t": "用眼色禁止别人言行"}, {"w": "目语额瞬", "t": "眉毛眼睛能作态示意。"}]}, {"meaning": "看待。", "cites": [{"t": "不敢以说书目敬亭。", "b": "清·黄宗羲《柳敬亭传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('237wx','且','1','iě jū','一','5','','[{"pinyin": "iě", "defs": [{"meaning": "此,这;今。", "cites": [{"t": "匪且有且,匪今斯今。", "b": "《诗·周颂·载芟》。毛传:“且,此也。”"}]}, {"meaning": "将近;几乎。", "cites": [{"t": "年且九十。", "b": "《列子·汤问》"}, {"t": "上晚年多内宠,小王且二十人。", "b": "《资治通鉴》"}, {"t": "去后且三年。", "b": "清·侯方域《壮悔堂文集》"}]}, {"meaning": "将要。", "cites": [{"t": "会且归矣,无庶予子憎。", "b": "《诗·齐风》"}, {"t": "故天之且风,草木未动而鸟已翔矣。", "b": "《淮南子》"}, {"t": "且为之奈何。", "b": "《史记·项羽本纪》"}, {"t": "以为且噬己矣。", "b": "唐·柳宗元《三戒》"}, {"t": "火且尽。", "b": "宋·王安石《游褒禅山记》"}, {"t": "祸且及汝。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "且当", "t": "该当"}, {"w": "且然", "t": "亦将如此。"}]}, {"meaning": "暂且;姑且。", "cites": [{"t": "且往观乎?", "b": "《诗·郑风》"}, {"t": "且携所著。", "b": "清·梁启超《谭嗣同传》"}, {"t": "甚且心之所以清。", "b": "清·刘开《问说》"}], "words": [{"w": "你且等一下;这事且放一下;且可", "t": "犹暂且"}, {"w": "且休", "t": "暂且休整"}, {"w": "且自", "t": "暂且;只管"}, {"w": "且住", "t": "暂止"}, {"w": "且暂", "t": "犹暂且"}, {"w": "且权", "t": "暂且;姑且"}, {"w": "且则", "t": "姑且"}, {"w": "且复", "t": "姑且再。"}]}, {"meaning": "表示并列关系,相当于“又”、“而且”。", "cites": [{"t": "君子有酒,旨且多。", "b": "《诗·小雅》"}, {"t": "行牧且荛。", "b": "唐·柳宗元《童区寄传》"}, {"t": "连拜且泣。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "香且甘者。", "b": "清·周容《春酒堂遗书·芋老人传》"}, {"t": "贼能且众。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "贫且贱;横且直;且并", "t": "并且"}, {"w": "且是", "t": "而且。"}]}, {"meaning": "表示选择关系,相当于“抑或”、“或者”。", "cites": [{"t": "王以天下为尊秦乎?且尊齐乎”", "b": "《战国策》"}, {"t": "是且非邪。", "b": "唐·韩愈《朱文公校昌黎先生集》"}]}, {"meaning": "表示递进关系,相当于“尚且”、“况且”。", "cites": [{"t": "且焉置土石。", "b": "《列子·汤问》"}, {"t": "且北方之人,不习水战。", "b": "《三国志》"}, {"t": "且人患志之不立。", "b": "《世说新语·自新》"}, {"t": "余悲之,且曰…", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "且欲观客。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "且夫", "t": "且况。况且。"}]}, {"meaning": "表示假设关系,相当于“若”、“假如”。", "cites": [{"t": "且静郭君听辨而为之也,必无今日之患也。", "b": "《吕氏春秋》"}, {"t": "且复妄言。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "且如", "t": "假如;如果"}, {"w": "且使", "t": "假使;倘若。"}]}, {"meaning": "尚且,还。", "cites": [{"t": "臣死且不避,卮酒安足辞。", "b": "《史记·项羽本纪》"}, {"t": "为众人师且不敢。", "b": "唐·柳宗元《柳河东集》"}, {"t": "且继今以往。", "b": "[英]赫胥黎著、严复译《天演论》"}]}]}, {"pinyin": "jū", "defs": [{"meaning": "用在句末,相当于“啊”。", "cites": [{"t": "狂童之狂也且。", "b": "《诗·郑风·褰裳》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('238wx','叶','1','xié yè shè','口','5','','[{"pinyin": "xié", "defs": [{"meaning": "和洽。", "cites": [{"t": "犀牛一角叶箜篌。", "b": "《老残游记》"}, {"t": "逢吉与李程同执政,不叶。", "b": "《新唐书》"}], "words": [{"w": "叶律", "t": "叶韵;韵律"}, {"w": "叶韵", "t": "协韵;押韵"}, {"w": "叶中", "t": "犹适中"}, {"w": "叶吉", "t": "和协吉祥"}, {"w": "叶和", "t": "和睦;和合;和谐;亦作应和"}, {"w": "叶契", "t": "协和,配合"}, {"w": "叶泰", "t": "协和安泰。"}]}, {"meaning": "合,共同。", "cites": [{"t": "股肱叶谋,爪牙宣力。", "b": "《旧五代史》"}], "words": [{"w": "叶力", "t": "协力;合力"}, {"w": "叶心", "t": "同心"}, {"w": "叶谋", "t": "合谋;共谋。"}]}]}, {"pinyin": "yè", "defs": [{"meaning": "(形声。从艸,枽(yè)声。植物的叶子。“叶”,同“协”,会意字,从十从口。本是两个字。本义:草木之叶)。"}, {"meaning": "同本义。", "cites": [{"t": "叶,草木之叶也。", "b": "《说》"}, {"t": "其叶为胡蝶。", "b": "《列子·天瑞》。注:“散也。”"}, {"t": "枝叶未有害。", "b": "《诗·大雅·荡》"}], "words": [{"w": "叶尖", "t": "植物学名词。叶片的尖端部位"}, {"w": "叶序", "t": "植物学名词,叶在茎上的排列方式称为叶序"}, {"w": "叶芽", "t": "植物学名词。与花芽相对。发育后成为茎、枝及叶的芽"}, {"w": "叶基", "t": "植物学名词。叶片的下端靠近叶柄的部分。"}]}, {"meaning": "比喻轻小、轻飘像叶子的东西。", "cites": [{"t": "万里风波一叶舟。", "b": "李商隐《无题》"}], "words": [{"w": "百叶窗;一叶扁舟;肺叶", "t": ""}]}, {"meaning": "世,代。", "cites": [{"t": "勋载二叶。", "b": "汉《太尉刘宽碑》"}, {"t": "继德前叶,清和挺懿。", "b": "汉《豫州从事孔褒碑》"}, {"t": "李势在蜀既久,承藉累叶。", "b": "《世说新语》"}], "words": [{"w": "叶语", "t": "世代相传说。"}]}, {"meaning": "古邑名 ,在今河南叶县南。", "cites": [{"t": "公爱班固而忽崔骃,此叶公之好龙也。(叶公:本名沈诸梁,楚国贵族,叶是他的封地。)", "b": "《后汉书·崔骃传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "shè", "defs": [{"meaning": "古邑名。在今河南省叶县南。春秋时属楚领地。汉置县。", "words": [{"w": "叶县凫", "t": "指得到皇上眷念的县令"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('239wx','甲','1','jiá','田','5','','[{"pinyin": "jiá", "defs": [{"meaning": "(象形。小篆字形,像草木生芽后所戴的种皮裂开的形象。本义:种籽萌芽后所戴的种壳)。"}, {"meaning": "同本义。", "cites": [{"t": "甲,东方之孟阳气萌动。从木,戴孚甲之象。", "b": "《说文》"}, {"t": "甲象草木戴种而出之形。", "b": "《六书故》"}, {"t": "雷雨作而百果草木皆甲坼(chè)。", "b": "《易·解》"}], "words": [{"w": "莩甲;甲坼", "t": "甲宅。外壳裂开。指草木种子裂开硬壳发出芽头。"}]}, {"meaning": "古时战士的护身衣,用皮革或金属制成。也叫“铠”。", "cites": [{"t": "献甲者执胄。", "b": "《礼记·曲礼》"}, {"t": "殪以为大甲。", "b": "《国语·晋语》"}, {"t": "齐国寡甲兵。", "b": "《战国策·齐策》"}, {"t": "函人为甲。", "b": "《周礼·考工记》"}, {"t": "擐甲执兵,固即死也。", "b": "《左传·成公二年》"}, {"t": "卷甲而藏。", "b": "宋·苏轼《教战守》"}, {"t": "甲冰霜迸落。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "弃甲投戈。", "b": "《广东军务记》"}]}, {"meaning": "武器。", "cites": [{"t": "得甲库,取器械。", "b": "《资治通鉴》"}]}, {"meaning": "披甲的人,即甲士。", "cites": [{"t": "晋侯饮赵盾酒,伏甲将攻之。", "b": "《左传·宣公二年》"}, {"t": "精甲万人。", "b": "司马光《资治通鉴》"}]}, {"meaning": "天干的第一位,用以纪年、月、日。", "cites": [{"t": "乙卯乃雨,甲子又雨。", "b": "苏轼《喜雨亭记》"}], "words": [{"w": "六甲甲胆", "t": "中医认为人的脏腑分五行,同属的再以甲乙分。胆与肝同属木,胆称甲木,亦称甲胆。"}]}, {"meaning": "居第一;冠于。", "cites": [{"t": "治宅甲诸第。", "b": "《史记·魏其武安侯列传》"}], "words": [{"w": "桂林山水甲天下", "t": ""}]}, {"meaning": "把甲衣穿在身上。", "cites": [{"t": "晞一营大噪,尽甲。", "b": "柳宗元《段太尉逸事状》"}], "words": [{"w": "甲马", "t": "披甲的战马;画有神象或符咒的符箓"}, {"w": "甲坊署", "t": "掌管甲胄等的官署"}, {"w": "甲伍", "t": "披甲执兵的队伍"}, {"w": "甲士", "t": "押甲的战士"}, {"w": "甲第连云", "t": "形容达官显贵住宅高耸入云 的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('240wx','申','1','shēn','田','5','','[{"pinyin": "shēn", "defs": [{"meaning": "(指事。从臼,自持。从丨。身体。与寅同意。本义: 束身)。"}, {"meaning": "同本义;约束。", "cites": [{"t": "申,束身也。", "b": "《说文》"}, {"t": "约车申辕。", "b": "《淮南子·原道》。注:“束也。”"}, {"t": "畏忌自申。", "b": "《汉书·韦元成传》。注:“言自约束也。”"}, {"t": "勒兵申教令。", "b": "《汉书·元帝纪》"}, {"t": "朱绿带申加大带于上。", "b": "《礼记·杂记》"}, {"t": "申体防以自持。", "b": "曹植《洛神赋》"}], "words": [{"w": "申束", "t": "约束。"}]}, {"meaning": "舒展", "cites": [{"t": "形可劫而使诎申。", "b": "《荀子·解蔽》"}, {"t": "大夫执圭而使,所以申信也。", "b": "《礼记·郊特牲》"}, {"t": "咎犯申其左臂而诎五指。", "b": "《说苑·正谏》"}, {"t": "行止屈申,与时息兮。", "b": "班超《北征赋》"}], "words": [{"w": "申张", "t": "伸张;扩大"}, {"w": "申水", "t": "商业用语。旧时两种价格不同的货币互相交换时,由一方加价给他方作为补贴称“申水”"}, {"w": "申主", "t": "信主,出政而信于民的君主。"}]}, {"meaning": "表明,表达。", "cites": [{"t": "长者虽有问,役夫敢申恨?", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "申敬", "t": "表明敬意"}, {"w": "申意", "t": "表明、表达意思;致意"}, {"w": "申布", "t": "宣布"}, {"w": "申白", "t": "申明表白;禀明"}, {"w": "申好", "t": "表示结好"}, {"w": "申挺", "t": "辨明而从宽处理"}, {"w": "申约", "t": "申明约令;重申缔盟"}, {"w": "申奖", "t": "表示奖励"}, {"w": "申酌", "t": "借杯酒而表达"}, {"w": "申致", "t": "送达;送给;表达。"}]}, {"meaning": "申诫;告诫。", "cites": [{"t": "即三令五申之。", "b": "《史记·孙武列传》"}], "words": [{"w": "申守", "t": "再次警诫加强守备"}, {"w": "申救", "t": "告诫,郑重的训诫"}, {"w": "申戒", "t": "告诫"}, {"w": "申析", "t": "申说辨析"}, {"w": "申敕", "t": "告诫"}, {"w": "申诏", "t": "申令告诫"}, {"w": "申禁", "t": "宣布禁止从事某项活动"}, {"w": "申儆", "t": "儆;训戒"}, {"w": "申宪", "t": "绳之以法;依法处理"}, {"w": "申警", "t": "警戒;儆戒"}, {"w": "申严", "t": "申令严格遵守或执行某种法令、措施。"}]}, {"meaning": "重复地说,重申。", "cites": [{"t": "申之以孝悌之义,颁白者不负戴于道路矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "申志", "t": "一再表明心志"}, {"w": "申命", "t": "重申教命;再命"}, {"w": "申复", "t": "重申诉而使之恢复。"}]}, {"meaning": "申报,旧时官府行文,下级对上级称申。", "cites": [{"t": "须先具价申禀。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "申解", "t": "申报;解送;上报的文书"}, {"w": "申状", "t": "上报的文书"}, {"w": "申达", "t": "下级官府对上级行文表述"}, {"w": "申表", "t": "上报的奏章"}, {"w": "申闻", "t": "向上级报告"}, {"w": "申破", "t": "上报说明"}, {"w": "申黜", "t": "申报上级予以开除"}, {"w": "申文", "t": "行文呈报。"}]}, {"meaning": "欠伸。", "cites": [{"t": "熊经鸟申,为寿而已矣。", "b": "《庄子·刻意》"}]}, {"meaning": "地支的第九位。"}, {"meaning": "与天干相配用以纪年。如1944年为甲申年。"}, {"meaning": "用以纪月,即农历七月。"}, {"meaning": "用以纪日。"}, {"meaning": "用以纪时,即十五时至十七时为申时。", "cites": [{"t": "申末酉初,虹亘中天,日气蒸云,竟天作黄金色。", "b": "《三元里抗英》"}], "words": [{"w": "申牌", "t": "十二时辰之一。指十五时至十七时"}, {"w": "申酉戌亥", "t": "申:15—17时;酉:17—19时;戌:19—21时;亥:21—1时。"}]}, {"meaning": "周时国名。姜姓,传为伯夷之后。故城在今河南省南阳市。", "cites": [{"t": "彼其之子,不与我戍申。", "b": "《诗·王风》"}]}, {"meaning": "明, 明白。", "cites": [{"t": "利口倾险,反乱国家,罪无申证,狱不讯鞠。", "b": "《后汉书》"}]}, {"meaning": "重复,一再。", "cites": [{"t": "伊尹申告于王。", "b": "《书·太甲》"}], "words": [{"w": "申告", "t": "反复告诫"}, {"w": "申言", "t": "再次陈说;重复述说。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('241wx','叮','1','dīng','口','5','','[{"pinyin": "dīng", "defs": [{"meaning": "虫类用针形口器刺人。", "cites": [{"t": "力叮不释。", "b": "《聊斋志异·促织》"}], "words": [{"w": "叮得满身是红块", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('242wx','电','1','diàn','田','5','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从雨,申声。本义:闪电)。"}, {"meaning": "同本义。", "cites": [{"t": "电,阴阳激耀也。", "b": "《说文》"}, {"t": "电,电光也。", "b": "《五经通义》"}, {"t": "三月癸酉,大雨震电。震,雷也,电,霆也。", "b": "《谷梁传·隐公九年》。疏:“霆者,霹雳之别名。有霆必有电,故传云:‘电,霆也。’按,霆,电实同一词,后来歧为二义:其声曰霆,其光曰电。”"}], "words": [{"w": "电火", "t": "闪电。"}]}, {"meaning": "电报的简称。", "cites": [{"t": "请致电上海领事而救先生焉。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "急电;贺电;电底", "t": "电报的底稿"}, {"w": "海外来电", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('243wx','号','1','hào hào','口','5','','[{"pinyin": "hào", "defs": [{"meaning": "(会意。从虎,从号。“号”亦兼表读音。“号”是“號”的古字,上面是“口”,下面代表声音,即号呼的意思。后繁化,变成“號”,现在简化为“号”。本义:大声喊叫)。"}, {"meaning": "同本义。", "cites": [{"t": "号,呼也。", "b": "《尔雅》"}, {"t": "谁之永号?", "b": "《诗·魏风·硕鼠》"}, {"t": "公号庆郑。", "b": "《国语·晋语》"}, {"t": "号呼而转徙。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "因大号,一墟皆惊。", "b": "唐·柳宗元《童区寄传》"}, {"t": "阴风怒号。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "号泣载道。", "b": "《明史》"}], "words": [{"w": "号噪", "t": "呼叫,喧嚷"}, {"w": "号踯", "t": "号叫跳顿"}, {"w": "号佛", "t": "高声念佛。"}]}, {"meaning": "哭而有言。", "cites": [{"t": "号,痛声也。", "b": "《说文》"}, {"t": "以哭有言者为号。", "b": "《颜氏家训·礼》"}, {"t": "老聃死,秦失吊之,三号而出。", "b": "《庄子·养生主》"}, {"t": "冬暖而儿号寒,年丰而妻啼饥。", "b": "韩愈《进学解》"}, {"t": "先号咷而后笑。", "b": "《易·同人》"}, {"t": "号呼达旦。", "b": "方苞《狱中杂记》"}], "words": [{"w": "号啕痛", "t": "歇后语:哭"}, {"w": "号天搭地", "t": "大声哭叫"}, {"w": "号天哭地", "t": "哭天抢地"}, {"w": "号泣", "t": "大声哭泣。"}]}, {"meaning": "动物引声长鸣,大风发出巨响。", "cites": [{"t": "昆吾之山有兽焉,其音如号,", "b": "《山海经·中山经》"}], "words": [{"w": "寒号虫;号群", "t": "禽兽鸣号以求群类"}, {"w": "号怒", "t": "怒号,指风声疾厉"}, {"w": "北风怒号", "t": ""}]}]}, {"pinyin": "hào", "defs": [{"meaning": "扬言有。", "cites": [{"t": "项羽兵四十万,号百万。", "b": "《史记·高祖本纪》"}], "words": [{"w": "口喧佛号", "t": "大声念佛。"}]}, {"meaning": "命令,发令。", "cites": [{"t": "发枪之号。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "明诏大号。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "号令", "t": ""}]}, {"meaning": "宣称,称号。", "cites": [{"t": "号之曰有巢氏。", "b": "《韩非子·五蠹》"}, {"t": "号之曰燧人氏。", "b": ""}, {"t": "号为军机四卿。", "b": "清·梁启超《谭嗣同传》"}]}, {"meaning": "名位;名称;称谓。", "cites": [{"t": "号为张楚。", "b": "《史记·陈涉世家》"}, {"t": "赐号称王。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "号位", "t": "称号和爵位;名号"}, {"w": "号带", "t": "军旗。古代大将出征,旗上绣出主帅姓氏,叫号旗"}, {"w": "号名", "t": "标志;称谓;位号"}, {"w": "国号;年号", "t": ""}]}, {"meaning": "别号。名、字以外的称谓。", "cites": [{"t": "号曰醉翁。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "自号刚峰。", "b": "《明史》"}], "words": [{"w": "号谥", "t": "谥号。古代帝王、贵族、大臣等死后将葬,按其生前事迹给予寓意褒贬的称号"}, {"w": "号簿", "t": "犹今登记簿"}, {"w": "号屏", "t": "雨师的别名。"}]}, {"meaning": "商店的代称。", "cites": [{"t": "找了一家汇票号,是个日昇昌字号,汇了八百两,寄江南徐州家里去。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('244wx','田','1','tián','田','5','','[{"pinyin": "tián", "defs": [{"meaning": "(象形。小篆认为象阡陌纵横或沟浍四通的一块块农田。“田”是汉字的一个部首,从“田”的字多与田猎耕种有关。本义:种田)。"}, {"meaning": "后作“佃”。耕作。", "cites": [{"t": "田,树谷曰田。", "b": "《说文》"}, {"t": "田,种禾稼也。", "b": "《一切经音义》引《苍颉》"}, {"t": "无田甫田,维莠骄骄。", "b": "《诗·齐风·甫田》"}, {"t": "令民得田之。", "b": "《汉书·高帝纪上》"}, {"t": "使各居其宅,田其田。", "b": "刘向《说苑》"}], "words": [{"w": "田戍", "t": "屯田戍守"}, {"w": "田作", "t": "耕作"}, {"w": "田畜", "t": "耕种与畜牧"}, {"w": "田桑", "t": "种田和养蚕"}, {"w": "田农", "t": "农耕"}, {"w": "田种", "t": "耕种"}, {"w": "田穑", "t": "耕作。"}]}, {"meaning": "打猎", "cites": [{"t": "不敢盘于游田。", "b": "《书·无逸》"}, {"t": "田有禽。", "b": "《易·师卦》"}, {"t": "叔于田。", "b": "《诗·郑风·大叔于田》"}, {"t": "宣子田于首山。", "b": "《左传·宣公二年》"}, {"t": "齐侯游于姑棼,遂田于见丘。", "b": "《左传·庄公八年》"}, {"t": "焚林而田,偷取多兽,后必无兽。", "b": "《韩非子·难一》"}, {"t": "焚林而田,竭泽而渔。", "b": "《淮南子·本纪》"}], "words": [{"w": "田弋", "t": "打猎"}, {"w": "田犬", "t": "猎狗"}, {"w": "田车", "t": "打猎用的车子"}, {"w": "田事", "t": "狩猎之事"}, {"w": "田具", "t": "狩猎用具"}, {"w": "田狩", "t": "打猎"}, {"w": "田马", "t": "打猎所用的马"}, {"w": "田备", "t": "田猎的用具"}, {"w": "田渔", "t": "打猎和捕鱼。"}]}, {"meaning": "农田。", "cites": [{"t": "已耕者曰田。", "b": "《释名·释地》"}, {"t": "倬彼甫田。", "b": "《诗·小雅·甫田》"}, {"t": "大田多稼。", "b": "《诗·大雅·大田》"}, {"t": "田畴荒芜。", "b": "《国语·周语下》"}, {"t": "引河水灌民田。", "b": "褚少孙《西门豹治邺》"}], "words": [{"w": "田塍", "t": "田间的土埂子"}, {"w": "田舍翁", "t": "老农;乡巴佬"}, {"w": "田夫", "t": "农民"}, {"w": "田中", "t": "田地之中;田野之中"}, {"w": "田宅", "t": "田地和房屋"}, {"w": "田阱", "t": "田间洼地"}, {"w": "田邑", "t": "田野与都邑"}, {"w": "田陂", "t": "坡田"}, {"w": "田坪", "t": "田野中平坦的场地。"}]}, {"meaning": "一块蕴藏、出产或生产一种自然资源的土地 。", "words": [{"w": "油田;气田;煤田", "t": ""}]}, {"meaning": "大鼓。", "cites": [{"t": "应田县(悬)鼓。", "b": "《诗·周颂·有瞽》"}]}, {"meaning": "人体部位,俗称丹田。", "cites": [{"t": "寸田尺宅可治生。", "b": "张君房《云笈七签》"}]}, {"meaning": "古代统治者赏赐给亲属臣仆的封地。", "cites": [{"t": "乃宦卿之适子,而为之田,以为公族。", "b": "《左传》"}]}, {"meaning": "古代管理农事的官。", "cites": [{"t": "后稷为田。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('245wx','由','1','yóu','田','5','','[{"pinyin": "yóu", "defs": [{"meaning": "(《说文》无“由”字,古字字形)。"}, {"meaning": "树木生新枝。亦泛指萌生。", "cites": [{"t": "今在析木之津,犹将复由。", "b": "《左传》"}], "words": [{"w": "由蘖", "t": "树木枯槁或被砍伐后重发的枝条"}]}, {"meaning": "经,由。", "cites": [{"t": "谁能出不由户?", "b": "《论语·雍也》"}, {"t": "余在刑部狱,见死而由窦出者日三四人。", "b": "方苞《狱中杂记》"}], "words": [{"w": "必由之路;,由边门出去", "t": ""}]}, {"meaning": "行走。", "cites": [{"t": "舍正路而不由,哀哉。", "b": "《孟子》"}]}, {"meaning": "(yǐ)。用。", "cites": [{"t": "君子无易由言。", "b": "《诗·小雅·小弁》。笺:“由,用也。”"}, {"t": "不能由吾子。", "b": "《左传·襄公三十年》。杜预注:“由,用也。”"}, {"t": "亿万舟楫,亿万垣墙,窒隙防淫,是必由之。", "b": "《天工开物》"}], "words": [{"w": "由房", "t": "用房中的音乐娱乐。"}]}, {"meaning": "任用。", "cites": [{"t": "以晋国之多虞,不能由君子;使吾子辱在泥涂久矣。武之罪也。", "b": "《左传》"}, {"t": "废而不由,则女德不厌。", "b": "《汉书》"}], "words": [{"w": "由绎", "t": "任用之而使其尽力施展才能。"}]}, {"meaning": "听凭;听任。", "cites": [{"t": "若赛锦,由你是谁,都输与他。", "b": "《水浒传》"}], "words": [{"w": "由得", "t": "任凭"}, {"w": "由心", "t": "任凭心意"}, {"w": "由本", "t": "安于本分"}, {"w": "由身", "t": "任凭自己"}, {"w": "由性", "t": "任凭心意。"}]}, {"meaning": "遵从;遵照。", "cites": [{"t": "不愆不忘,率由旧章。", "b": "《诗·大雅》"}, {"t": "民可使由之,不可使知之。", "b": "《论语》"}], "words": [{"w": "由文", "t": "遵循礼仪"}, {"w": "由行", "t": "依其道而行"}, {"w": "由礼", "t": "遵循礼教。"}]}, {"meaning": "蹈行;践履。", "cites": [{"t": "隘与不恭,君子之不由也。", "b": "《孟子》"}, {"t": "是故隆礼由礼,谓之有方之士。", "b": "《礼记》"}]}, {"meaning": "原由;缘故。", "cites": [{"t": "盖闻古者祖有功而宗有德,制礼乐各有由。", "b": "《史记》"}], "words": [{"w": "由状", "t": "原由与情况"}, {"w": "由缘", "t": "缘故"}, {"w": "由委", "t": "原委"}, {"w": "由始", "t": "起因;起始。"}]}, {"meaning": "来源;开头。", "cites": [{"t": "善行动于心,善言出于意,同由共本,一气不异。", "b": "汉·王充《论衡》"}], "words": [{"w": "由历", "t": "起始和历程"}, {"w": "由趣", "t": "来历;由末"}, {"w": "由绪", "t": "来历;来由。"}]}, {"meaning": "机缘;机会。", "cites": [{"t": "某也愿见,无由达。", "b": "《仪礼》"}, {"t": "吾欲归附关中,但未有由耳。", "b": "《周书》"}]}, {"meaning": "法式。", "cites": [{"t": "匪言勿言,匪由勿语。", "b": "《诗·小雅·宾之初筵》"}]}, {"meaning": "途径;办法。", "cites": [{"t": "圣武之治民也,进则使无由得其所利,退则使无由避其所害。", "b": "《管子》"}], "words": [{"w": "无由", "t": "没有门径,无从。"}]}, {"meaning": "因为;由于。", "cites": [{"t": "由是则生,而有所不用也。", "b": "《孟子·告子上》"}, {"t": "宣宗初亦号供奉,程既审上晓音律…必为奇巧声动上,由是得幸。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "由是之扬,之杭,之金陵,名达于缙绅间(之,动词,到)。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "由以", "t": "因而。"}]}, {"meaning": "自,从…(表示起点)。", "cites": [{"t": "由,自也。", "b": "《尔雅》"}, {"t": "由屋顶放光入室。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "由中", "t": "由衷"}, {"w": "由自", "t": "自,尚自"}, {"w": "由来", "t": "自始以来"}, {"w": "由忠", "t": "由衷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('246wx','只','1','zhī zhǐ','口','5','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从又,持隹。持一隹曰隻,持二隹曰雙。本义:鸟一只) 同本义。", "cites": [{"t": "隻,鸟一枚也。", "b": "《说文》"}, {"t": "如彼翰林鸟,双栖一朝只。", "b": "《悼亡诗三首》"}], "words": [{"w": "只翼", "t": "一只鸟。比喻孤单。"}]}, {"meaning": "引申为凡物之单者曰只。单一。", "cites": [{"t": "莫遣只轮归海窟,仍留一箭射天山。", "b": "李益《塞下曲》"}, {"t": "匹马只轮无反者。", "b": "《公羊传·僖公三十三年》"}], "words": [{"w": "只轮不返", "t": "就连一只战车轮子都回不去了。比喻大败,全军覆灭"}, {"w": "只鸡架酒", "t": "比喻祭品虽菲薄简陋,然情意甚重"}, {"w": "只手", "t": "单手。转喻为独力"}, {"w": "只句", "t": "单句,零星散句"}, {"w": "只字", "t": "单字,零星的字迹或文辞"}, {"w": "只曲", "t": "指北曲中不成套的小令"}, {"w": "只眼", "t": "独眼。比喻独特的见地。"}]}, {"meaning": "单数;奇数。", "cites": [{"t": "肃宗而下,咸只日临朝,双日不坐。", "b": "《宋史·张洎传》"}], "words": [{"w": "只日", "t": "单日。"}]}]}, {"pinyin": "zhǐ", "defs": [{"meaning": "(指事。小篆字形。上为“口”,下面两点表示气向下。本义:句末语气词)。"}, {"meaning": "用于句末,表示终结或感叹。", "cites": [{"t": "母也天只, 不谅人只!", "b": "《诗·鄘风·柏舟》"}]}, {"meaning": "用于句末, 表示限止。相当于“耳”。", "cites": [{"t": "诸侯归晋之德只, 非归其尸盟也。", "b": "《左传》"}]}, {"meaning": "用于句中。", "cites": [{"t": "乐只君子, 福履绥之。", "b": "《诗·周南·樛木》"}]}, {"meaning": "用于判断句首,对主语起限定和强调作用。", "cites": [{"t": "只我便是宋江。", "b": "《水浒传》"}], "words": [{"w": "只这便是", "t": ""}]}, {"meaning": "(秖和衹在唐、宋以后多写作只。“祇”简化为“只”)。"}, {"meaning": "仅;仅仅。", "cites": [{"t": "只隔数重山。", "b": "宋·洪迈《容斋续笔》"}, {"t": "只在花开之数日。", "b": "明·李渔《闲情偶寄·种植部》"}]}, {"meaning": "又。", "cites": [{"t": "只有霜中败叶。", "b": ""}], "words": [{"w": "只道", "t": "只认为;只说"}, {"w": "只除", "t": "只有;除非"}, {"w": "只告诉你;只见过我父亲三次;只有两元钱;只他知道;只此", "t": "仅此;就此;唯有这样。"}]}, {"meaning": "唯此;无它。", "cites": [{"t": "别来杨柳街头树,摆弄春风只欲飞。", "b": "韩愈《镇州初归》"}], "words": [{"w": "只为读完了书的读者;我们在本章只指明该时期的主要特点;只在", "t": "就在"}, {"w": "只如", "t": "就像。"}]}, {"meaning": "本,本来。", "cites": [{"t": "(旦云)妾身早知陛下驾临,只合远接。", "b": "《汉宫秋》"}]}, {"meaning": "直;一直。", "cites": [{"t": "鲁智深离了桃花山,放开脚步,从早晨只走到午后。", "b": "《水浒传》"}], "words": [{"w": "只到", "t": "直到。"}]}, {"meaning": "指示代词。", "cites": [{"t": "若时乐,乐时苦,只个修行断门户。", "b": "一钵和尚《一钵歌》"}], "words": [{"w": "只个", "t": "这种;如此"}, {"w": "只凭", "t": "这样"}, {"w": "只么", "t": "如此"}, {"w": "只今", "t": "如今;现在。"}]}, {"meaning": "作,做。", "cites": [{"t": "相公到此只甚?", "b": "关汉卿《鲁斋郎》"}]}, {"meaning": "用在句中。", "cites": [{"t": "乐只君子,邦家之基。", "b": "《诗·小雅·南山有台》"}]}, {"meaning": "", "cites": [{"t": "他前面引尺,我背后把他跟随。", "b": "高文秀《黑旋风》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('247wx','叭','1','bā bà pā','口','5','','[{"pinyin": "bā", "defs": [{"meaning": "将食物扒入口中。", "cites": [{"t": "只三叭两咽,就是一碗。", "b": "《金瓶梅词话》"}]}, {"meaning": "叼;含在口中。", "cites": [{"t": "移开叭在口里的旱烟袋。", "b": "周立波《牛》"}]}]}, {"pinyin": "bà", "defs": [{"meaning": "——见“喇叭”。"}]}, {"pinyin": "pā", "defs": [{"meaning": "", "words": [{"w": "叭叭", "t": "形容拍击声"}, {"w": "叭啦", "t": "形容玻璃窗振动的声音。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('248wx','史','1','shǐ','口','5','','[{"pinyin": "shǐ", "defs": [{"meaning": "(会意。甲骨文字形,上面是放简策的容器,下面是手。合起来表示掌管文书记录。本义:史官)。"}, {"meaning": "古官名。职别各异。", "cites": [{"t": "史,记事者也。", "b": "《说文》。按,周官有大史、小史、闪史、外史、御史、女史。其属又各有府史、胥徒史,主造文书者亦称史。凡府史,皆其官长所自辟除。"}, {"t": "矧大史友内史友。", "b": "《书·酒诰》。郑注:“大史内史。”"}, {"t": "用史巫纷若。", "b": "《易·巽》"}, {"t": "辞多则史。", "b": "《礼记·聘礼记》"}, {"t": "史载笔。", "b": "《礼记·曲礼》"}, {"t": "史狐书贼。", "b": "《谷梁传·宣公二年》"}, {"t": "动则左史书之,言则右史书之。", "b": "《礼记·玉藻》"}]}, {"meaning": "殷代为驻守于外的武官。卜辞:“在北史其获羌。”。"}, {"meaning": "在王左右的史官,担任祭祀、星历、卜筮、记事等职。", "cites": [{"t": "迁有良史之才。", "b": "《汉书·司马迁传赞》"}], "words": [{"w": "史巫", "t": "祝史和巫觋"}, {"w": "史氏", "t": "史家;史官"}, {"w": "史臣", "t": "史官"}, {"w": "史职", "t": "史官的职务"}, {"w": "史家", "t": "史官或历史学家"}, {"w": "史胥", "t": "掌管文书的小吏。"}]}, {"meaning": "太史令的简称。", "cites": [{"t": "自去史职,五载复还。", "b": "《后汉书·张衡传》"}]}, {"meaning": "史册,历史。", "cites": [{"t": "如史载田横事,虽以史迁之善传游侠,亦不能为五百人立传,滋可痛已。", "b": "孙文《黄花冈七十二烈士事略序》"}, {"t": "幼而读书,好《楚辞》;诸子经史多所涉猎。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "史鉴", "t": "历史书"}, {"w": "史文", "t": "历史文献"}, {"w": "史绩", "t": "历史功绩"}, {"w": "史录", "t": "历史的文字纪录。"}]}, {"meaning": "古代官府的佐吏。", "cites": [{"t": "或佐之史。", "b": "《诗·小雅·宾之初筵》"}]}, {"meaning": "中国古代图书四大类别之一,包括各类历史书籍。", "cites": [{"t": "列经、史、子、集四库。", "b": "《新唐书·艺文志》"}]}, {"meaning": "画师。", "cites": [{"t": "宋元君将画图,众史皆至,受揖而立。", "b": "《庄子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('249wx','央','1','yāng','大','5','','[{"pinyin": "yāng", "defs": [{"meaning": "(会意。小篆字形。从大,在冂(jiǒng)之内。上像物体(冂),一个人(大)站在它的当中。本义:中心)。"}, {"meaning": "同本义。", "cites": [{"t": "央,中央也。", "b": "《说文》"}, {"t": "宛在水中央。", "b": "《诗·秦风·蒹葭》"}, {"t": "中央土。", "b": "《礼记·月令》"}, {"t": "今人或入其央渎,窃其猪彘。", "b": "《荀子·正论》。注:“中渎也。”"}, {"t": "惜蕃华之未央。", "b": "《汉书·外戚传》。注:“犹未半也。”"}, {"t": "方六里,名之曰社,有邑焉,名之曰央。", "b": "《管子》"}], "words": [{"w": "央渎", "t": "出水沟。"}]}, {"meaning": "灾祸。", "cites": [{"t": "经设三命,君获其央。", "b": "汉《严訢碑》"}, {"t": "年寿未究,而遭祸央。", "b": "汉《故民吴仲山碑》"}]}, {"meaning": "远;久。", "cites": [{"t": "央,一曰久也。", "b": "《说文》"}], "words": [{"w": "央央", "t": "广大的样子。"}]}, {"meaning": "恳求,请求。", "cites": [{"t": "抚台央出文案老爷来请进去谈谈,这面子有多大!", "b": "《老残游记》"}], "words": [{"w": "央烦", "t": "央求烦劳。请人办事的客气话"}, {"w": "央连", "t": "烦劳"}, {"w": "央人", "t": "求人;请人"}, {"w": "央央", "t": "央求"}, {"w": "央倩", "t": "邀请"}, {"w": "央中", "t": "请某人做中人"}, {"w": "央靠", "t": "央求,请托,依靠"}, {"w": "央请", "t": "请托"}, {"w": "央属", "t": "请托。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('250wx','兄','1','xiōng','儿','5','','[{"pinyin": "xiōng", "defs": [{"meaning": "(会意。据甲骨文,上为“口”,下为匍伏的人。小篆从口,从儿(人)。象一人在对天祈祷,是“祝”的本字。本义:兄长)。"}, {"meaning": "同本义。", "cites": [{"t": "兄,长也。", "b": "《说文》"}, {"t": "男子先生为兄。", "b": "《尔雅》"}, {"t": "兄及弟矣,式相好矣。", "b": "《诗·小雅·斯干》"}], "words": [{"w": "乃兄", "t": "你的哥哥"}, {"w": "令兄", "t": "尊兄,尊称对方的哥哥"}, {"w": "愚兄", "t": "哥哥自己谦称"}, {"w": "家兄", "t": "谦称自己的哥哥。"}]}, {"meaning": "亲戚中同辈男性中年龄比自己大的。", "cites": [{"t": "表兄下马步堤岸,上船拜吾兄。", "b": "唐·韩愈《此日足可惜赠张籍》"}], "words": [{"w": "表兄;内兄;姻克;堂兄", "t": ""}]}, {"meaning": "对他人的尊称。", "cites": [{"t": "兄知之,勿为他人言也。", "b": "柳宗元《与肖翰林佝俛书》"}], "words": [{"w": "学兄;仁兄", "t": ""}]}, {"meaning": "古代亦以称姐。", "cites": [{"t": "弥子之妻与子路之妻,兄弟也。", "b": "《孟子·万章上》"}, {"t": "俾同气女兄,摩笄引决。", "b": "唐·刘知几《史通》"}]}, {"meaning": "指物之先生而大者。", "cites": [{"t": "是故其耨也,长其兄而去其弟。", "b": "《吕氏春秋》。高诱注:“养大杀小。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('251wx','叽','1','jī','口','5','','[{"pinyin": "jī", "defs": [{"meaning": "稍微吃一点。", "cites": [{"t": "嘰,小食也。从口,幾声。", "b": "《说文》"}, {"t": "叽琼华。", "b": "《大人赋》"}, {"t": "进禨(叽)进羞。", "b": "《礼记·玉藻》"}, {"t": "呼吸沆瀣兮餐朝霞,噍咀芝英[兮]叽琼华。", "b": "《史记·司马相如列传》"}, {"t": "茹,叽,食也。", "b": "唐·段成式《酉阳杂俎》"}]}, {"meaning": "悲叹。", "cites": [{"t": "纣为象箸而箕子叽。", "b": "《淮南子·缪称训》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('252wx','叼','1','diāo','口','5','','[{"pinyin": "diāo", "defs": [{"meaning": "用嘴衔住", "words": [{"w": "叼着", "t": "用嘴衔住〖物体的一部分〗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('253wx','叫','1','jiào','口','5','','[{"pinyin": "jiào", "defs": [{"meaning": "(形声。本义:呼,喊)。"}, {"meaning": "同本义。", "cites": [{"t": "叫,嘑也。", "b": "《说文》"}, {"t": "或不知叫号。", "b": "《诗·小雅·北山》"}, {"t": "叫我友兮配耦。", "b": "《楚辞·疾世》。注:“急呼也。”"}, {"t": "叫帝阍使辟扉兮。", "b": "张衡《思玄赋》"}, {"t": "戍卒叫,函谷举。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "叫命", "t": "骂人话。临死时呼喊声"}, {"w": "叫聒", "t": "声音吵杂刺耳"}, {"w": "叫号", "t": "大声呼喊"}, {"w": "叫头", "t": "戏剧用语。剧中人物之一,在剧情悲痛、情急愤怒之时,高喊对方,称为叫头"}, {"w": "叫曲", "t": "唱曲时没有蕴藉的韵味、感情。"}]}, {"meaning": "招唤,招呼。", "cites": [{"t": "或叫于宋大庙。", "b": "《左传·襄公三十年》。注:“呼也。”"}, {"t": "高声叫道:…", "b": "《鲁提辖拳打镇关西》"}], "words": [{"w": "叫喜", "t": "道喜"}, {"w": "叫魂", "t": ""}]}, {"meaning": "鸣叫。", "cites": [{"t": "候扇举而清叫。", "b": "潘岳《射雉赋》。注:“鸣也。”"}, {"t": "百叫无绝。", "b": "吴均《与朱元思书》"}, {"t": "双双归蛰燕,一一叫群猿。", "b": "唐·韩愈《晚泊江口》"}], "words": [{"w": "叫嗥", "t": "犹吼叫。指豺狼等野兽大声叫。"}]}, {"meaning": "[方言] 叫子(哨儿)。清明到,做【麦叫】,一头吹,一头笑。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('254wx','叩','1','kòu','口','5','','[{"pinyin": "kòu", "defs": [{"meaning": "(《说文》无“叩”字,只有“敂”字。《说文》:“敂,击也。从攴,句声。读若扣。”从“攴”(pū),表示与击打有关。本义:击,敲打)。"}, {"meaning": "同本义。", "cites": [{"t": "叩石垦壤。", "b": "《列子·汤问》"}, {"t": "凡四方之宾客,敂关则为之告。", "b": "《周礼·地官·司关》"}, {"t": "扣之,其声清扬而远闻。", "b": "《荀子·法行》"}, {"t": "以杖叩其胫。", "b": "《论语·宪问》"}, {"t": "眾者叩舟。", "b": "《淮南子·说林》"}, {"t": "以杖叩狼。", "b": "马中锡《中山狼传》"}, {"t": "娘以指叩门扉。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "叩胫", "t": "以杖棍击胫骨。是惩罚的一种方式"}, {"w": "叩门扉", "t": "敲打门扉"}, {"w": "叩心", "t": "捶胸。表示悔恨交加的样子"}, {"w": "叩门", "t": "敲门。"}]}, {"meaning": "叩头、拜。", "cites": [{"t": "皆叩头,叩头且破,额血流地,色如死灰。", "b": "《史记·滑稽列传》"}], "words": [{"w": "叩恳", "t": "叩头请求"}, {"w": "叩奠", "t": "叩拜祭奠"}, {"w": "叩赏", "t": "磕头谢赏"}, {"w": "叩请", "t": "恭敬而诚恳地请求。"}]}, {"meaning": "举发;询问。", "cites": [{"t": "扣其乡及姓字,皆不答。", "b": "明·魏禧《大铁椎传》"}, {"t": "余叩所以。", "b": "方苞《狱中杂记》"}], "words": [{"w": "叩咨;叩问;叩询", "t": ""}]}, {"meaning": "攻打。", "cites": [{"t": "引兵叩城。", "b": "唐·韩愈《刘公墓志铭》"}]}, {"meaning": "拉住。", "cites": [{"t": "伯夷叔齐叩马而谏。", "b": "《史记·伯夷列传》"}], "words": [{"w": "叩马", "t": "拉住马缰绳,不使前进。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('255wx','叨','1','dāo tāo','口','5','','[{"pinyin": "dāo", "defs": [{"meaning": "话多", "words": [{"w": "叨缕", "t": "叨叨缕缕。说话啰嗦冗长"}, {"w": "叨蹬", "t": "捣腾,闹腾"}, {"w": "絮叨", "t": "念叨"}, {"w": "唠叨", "t": "没完没了地说。"}]}]}, {"pinyin": "tāo", "defs": [{"meaning": "[方言]∶临死前气息急促的样子", "cites": [{"t": "等他爬起来一看呀,小兔子正在叨气儿呢,胸脯里的心跳得一撞一撞的。", "b": "杨朔《春子姑娘》 "}]}, {"meaning": "贪婪。饕的俗字。", "cites": [{"t": "岂横叨天功以为己力乎?", "b": "《后汉书·卢植传》"}], "words": [{"w": "叨食", "t": "贪食"}, {"w": "叨冒", "t": "叨贪。贪婪"}, {"w": "叨懫", "t": "贪而暴戾"}, {"w": "叨秽", "t": "贪婪卑鄙"}, {"w": "叨沓", "t": "贪婪而荒于政务"}, {"w": "叨昧", "t": "贪恋;贪婪"}, {"w": "叨富贵", "t": ""}]}, {"meaning": "承受 。古汉语中用于对受人恩惠及礼物表示感谢的谦词。", "cites": [{"t": "位窍和羹重,恩叨醉酒深。", "b": "唐·张说《恩赐丽正殿书院宴应制得林字》"}], "words": [{"w": "叨福", "t": "承受福庇"}, {"w": "叨庇", "t": "承受庇佑"}, {"w": "叨沫", "t": "蒙受"}, {"w": "叨位", "t": "忝居官位"}, {"w": "叨名", "t": "虚有其名"}, {"w": "叨忝", "t": "忝列;叨光"}, {"w": "叨受", "t": "承受"}, {"w": "叨承", "t": "忝受;承受。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('256wx','另','1','lìng','口','5','','[{"pinyin": "lìng", "defs": [{"meaning": "分居,分开居住而各自谋生。", "cites": [{"t": "另,分居也。", "b": "《五音集韵》"}]}, {"meaning": "割开,分开。", "cites": [{"t": "另,割开也。", "b": "《五音集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('257wx','叹','1','tàn','口','5','','[{"pinyin": "tàn", "defs": [{"meaning": "(形声。从欠(另一繁体从“口”),“難”省声。欠,打呵欠,与出气有关。本义:叹息)。"}, {"meaning": "同本义。", "cites": [{"t": "叹,吞叹也。一曰太息也。", "b": "《说文》"}, {"t": "禽子再拜而叹。", "b": "《墨子·备梯》"}, {"t": "戏而不叹。", "b": "《礼记·坊记》"}, {"t": "望洋向若而叹。", "b": "《庄子·秋水》"}, {"t": "皆叹惋。", "b": "晋·陶渊明《桃花源记》"}, {"t": "默叹曰。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "婉贞微叹曰。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "叹借者之用。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "叹气嗐声", "t": "唉声叹气"}, {"w": "叹恨", "t": "叹息抱恨"}, {"w": "叹憾", "t": "叹息遗憾"}, {"w": "叹笑", "t": "叹息讥笑"}, {"w": "叹悔", "t": "叹息后悔"}, {"w": "叹喟", "t": "叹息"}, {"w": "叹嗟", "t": "叹息"}, {"w": "叹想", "t": "叹息怀念"}, {"w": "叹诧", "t": "叹息诧异"}, {"w": "长叹;叹一口气", "t": ""}]}, {"meaning": "赞叹,赞美。", "cites": [{"t": "默叹。", "b": "《虞初新志·秋声诗自序》"}, {"t": "亟叹其技。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "叹重", "t": "赞叹敬重"}, {"w": "叹奖", "t": "称赞奖励"}, {"w": "叹嘻", "t": "赞叹"}, {"w": "叹骇", "t": "赞叹骇异"}, {"w": "叹为观止", "t": "赞叹看到的事物好到极点"}, {"w": "叹异", "t": "惊叹。"}]}, {"meaning": "吟诵。", "cites": [{"t": "叹,吟也。", "b": "《说文》"}, {"t": "智勇盖当代,弛张使我叹。", "b": "《文选·卢谌·览古诗》"}, {"t": "一唱而三叹。", "b": "《礼记·乐记》"}], "words": [{"w": "叹诵", "t": "吟诵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('258wx','冉','1','rǎn','冂','5','','[{"pinyin": "rǎn", "defs": [{"meaning": "(象形。本义:毛柔弱下垂的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "冄,毛冄冄也。", "b": "《说文》"}], "words": [{"w": "冉弱", "t": "荏弱。"}]}, {"meaning": "逐渐,渐进。常作“冉冉”。", "cites": [{"t": "老冉冉其将至兮。", "b": "《离骚》。注:“行貌。”"}, {"t": "冉内,行也。又冉冉,进也。", "b": "《广雅》"}], "words": [{"w": "冉冉悠悠", "t": "行动飘忽貌"}, {"w": "冉冉缠缠", "t": "慢慢腾腾"}, {"w": "冉内趋", "t": "指仕宦为政。"}]}, {"meaning": "龟壳的边缘。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('259wx','皿','1','mǐn','皿','5','','[{"pinyin": "mǐn", "defs": [{"meaning": "(象形。小篆字形,象碗、盆之类的食器。本义:器皿) 同本义。泛指碗碟杯盘一类饮食用具。", "cites": [{"t": "皿,饭器之用器也。", "b": "《说文》"}, {"t": "于交皿虫为蠱。", "b": "《左传·昭公元年》。注:“器也。”"}, {"t": "是不昭谷明而皿蠱也。", "b": "《国语·晋语》"}, {"t": "牲杀器皿。", "b": "《孟子》。注:“皿所以覆器者也。”"}, {"t": "器皿非满案。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "皿金", "t": "金属器皿"}, {"w": "皿卷", "t": "清代科举,顺天乡试监生的试卷"}, {"w": "皿器", "t": "盛物用具的统称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('260wx','凹','1','āo','凵','5','','[{"pinyin": "āo", "defs": [{"meaning": "周围高,中间低。", "cites": [{"t": "其湖无凹凸,平湖无高下。", "b": "《神异经·北方荒经》"}], "words": [{"w": "凹岸;凹面;凹洼", "t": "凹陷"}, {"w": "凹地;凹处", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('261wx','囚','1','qiú','囗','5','','[{"pinyin": "qiú", "defs": [{"meaning": "(会意。从人在囗(围)中。本义:拘禁、囚禁)。"}, {"meaning": "同本义。", "cites": [{"t": "囚,系也。", "b": "《说文》"}, {"t": "囚,拘也。", "b": "《尔雅》"}, {"t": "在泮献囚。", "b": "《诗·鲁颂·泮水》"}, {"t": "斯率囚。", "b": "《史记·始皇纪》"}, {"t": "韩非囚秦。", "b": "司马迁《报任安书》"}, {"t": "景公乃囚阳虎。", "b": "《韩非子·难四》"}, {"t": "泾水之囚之至矣。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "囚阱", "t": "押进地牢"}, {"w": "囚解", "t": "拘禁押送"}, {"w": "被囚;囚奴", "t": "囚禁奴役"}, {"w": "囚拘", "t": "囚禁"}, {"w": "囚桎", "t": "囚禁。"}]}, {"meaning": "限制,围困。", "cites": [{"t": "眼光囚在一国里,听谈彼得和约翰就生厌,定须张三李四才行。", "b": "鲁迅《坟·未有天才之前》"}]}, {"meaning": "犯人,被逮捕或被捕入狱的人。", "cites": [{"t": "问秦囚。", "b": "《左传·僖公三十三年》"}, {"t": "系囚常二百余。", "b": "清·方苞《狱中杂记》"}, {"t": "刑部系囚。", "b": ""}, {"t": "杀人重囚。", "b": ""}], "words": [{"w": "囚伍", "t": "罪犯"}, {"w": "囚囊", "t": "囚根子,囚攮。囚犯。骂人话"}, {"w": "死囚", "t": "已被判处死刑而尚未处决的囚犯"}, {"w": "阶下囚", "t": ""}]}, {"meaning": "被俘获的敌人。", "cites": [{"t": "明日复战,乃逸楚囚。", "b": "《左传》"}], "words": [{"w": "囚虏", "t": "俘虏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('262wx','四','1','sì','囗','5','','[{"pinyin": "sì", "defs": [{"meaning": "(指事。甲骨文字形,象鼻子喘息呼气之形。本义:数目。三加一所得) 同本义。", "cites": [{"t": "四,阴数也。四分之。", "b": "《说文》"}, {"t": "阴数次三也。", "b": "《玉篇》"}, {"t": "路下四亚之。", "b": "《仪礼·觐礼》。注:“谓乘马也。”"}, {"t": "光被四表。", "b": "《书·尧典》"}, {"t": "闰月定四时成岁。", "b": ""}, {"t": "良马四之", "b": "《诗·鄘风·干旄》"}, {"t": "安得猛士兮守四方!", "b": "刘邦《大风歌》"}]}, {"meaning": "。中国民族音乐音阶上的一级,乐谱上用做记音符号,相当于简谱的“6”。", "cites": [{"t": "大吕、大簇用四字。", "b": "《宋史·乐志十七》"}]}, {"meaning": "古代一车四马称“驷”。", "cites": [{"t": "人臣处国无私朝,居军无私交…是故不得四从;不载奇兵", "b": "《韩非子》"}, {"t": "一言而非,四马不能追,一言不急,四马不能及。", "b": "《说苑·谈丛》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('263wx','生','1','shēng','生','5','','[{"pinyin": "shēng", "defs": [{"meaning": "(会意。甲骨文字形,上面是初生的草木,下面是地面或土壤。“生”是汉字部首之一。本义:草木从土里生长出来;滋长)。"}, {"meaning": "同本义。", "cites": [{"t": "生,进也。象草木生出土上。", "b": "《说文》"}, {"t": "生,出也。", "b": "《广雅》"}, {"t": "生,生长也。", "b": "《广韵》"}, {"t": "自无出有曰生。", "b": "刘巘《易义》"}, {"t": "天地之大德曰生。", "b": "《易·系辞》"}, {"t": "生好物也。", "b": "《左传·昭公二十五年》"}, {"t": "草木有生而无知。", "b": "《荀子·王制》"}, {"t": "生于道左。", "b": "《诗·唐风·有杕之杜》"}, {"t": "生我百谷。", "b": "《诗·小雅·信南山》"}, {"t": "种之,生且蕃。", "b": "徐光启《甘薯疏序》"}, {"t": "多杂树,多松,生石罅,皆平顶。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "生盛", "t": "生长繁茂"}, {"w": "生化", "t": "生长化育"}, {"w": "生骨", "t": "主骨骼的生长"}, {"w": "生落", "t": "生长与凋落"}, {"w": "生遂", "t": "生长"}, {"w": "生荣", "t": "生长繁荣"}, {"w": "生处", "t": "生长的地方"}, {"w": "生肌", "t": "长出新肉"}, {"w": "生条", "t": "长出枝条。"}]}, {"meaning": "生育;养育。", "cites": [{"t": "父母生我。", "b": "《诗·小雅·正月》"}, {"t": "郑武公娶于申,曰武姜,生庄公及共叔段。", "b": "《左传·隐公元年》"}, {"t": "生以驭其福。", "b": "《周礼·太宰》。注:“犹养也。”"}, {"t": "孔子生鲁昌平乡陬邑。", "b": "《史记·孔子世家》"}, {"t": "信知生男恶,反是生女好。", "b": "唐·杜甫《兵车行》"}, {"t": "以一人生三计之,至子之世而父子四人。", "b": "清·洪亮吉《治平篇》"}, {"t": "毅宗之语公主,亦曰:“若何为生我家?”痛哉斯言。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "生聚", "t": "繁殖人口,积聚财物"}, {"w": "生落", "t": "出生"}, {"w": "生育率", "t": "反映生育年龄妇女生育频度的指标"}, {"w": "生遂", "t": "生育"}, {"w": "生月", "t": "出生的月份"}, {"w": "生年", "t": "出身;出身以来"}, {"w": "生身", "t": "出生"}, {"w": "生时", "t": "出生的年、月、日、时"}, {"w": "生岁", "t": "出生之年支"}, {"w": "生诞", "t": "出生。"}]}, {"meaning": "生存;活。与“死”相对。", "cites": [{"t": "爱之欲其生,恶之欲其死。", "b": "《论语·颜渊》"}, {"t": "陷之死地而后生。", "b": "《孙子·九地》"}, {"t": "公子自度终不能得之于王,计不独生而今赵亡。", "b": "《史记·魏公子列传》"}, {"t": "倘复请之,吾辈无生理矣。", "b": "清·方苞《狱中杂记》"}, {"t": "然后知生于忧患,而死于安乐也。", "b": "《孟子·告子下》"}], "words": [{"w": "生得", "t": "生获,活捉"}, {"w": "生寇", "t": "活的敌人"}, {"w": "生犀", "t": "活犀牛;活杀犀牛而取得的犀角"}, {"w": "生间", "t": "能活着回报敌情的间谍"}, {"w": "生割", "t": "活活宰割"}, {"w": "生魂", "t": "活人的魂魄"}, {"w": "生博", "t": "生取;活捉"}, {"w": "生抢", "t": "生取;活捉"}, {"w": "生碑", "t": "为活人立的碑"}, {"w": "生传", "t": "为活人作的传记。"}]}, {"meaning": "滋生;产生。", "cites": [{"t": "一旦运穷福艾,颠沛生于不测,而不知醉醇饫肥之肠,不可以实疏粝。", "b": "明·刘基《苦斋记》"}, {"t": "别有幽愁暗恨生,此时无声胜有声。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "生火", "t": "产生焦躁的情绪。产生火气、热气"}, {"w": "生心", "t": "怀有图谋不轨的异心"}, {"w": "生嗔", "t": "对别人的行为不满,生气"}, {"w": "生忿", "t": "发怒;忤逆,不孝"}, {"w": "生风", "t": "产生风;比喻产生使人敬畏的声势或气派"}, {"w": "生隙", "t": "产生嫌隙或事端"}, {"w": "生怜", "t": "产生怜爱之情。"}]}, {"meaning": "救活,使活。", "cites": [{"t": "幸先生生我。", "b": "马中锡《中山狼传》"}]}, {"meaning": "制造。", "cites": [{"t": "而士大夫亦未尝言兵,以为生事扰民。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "生产;制作。", "cites": [{"t": "生之者甚少而靡之者甚多,天下财富何得不蹶?", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "生货", "t": "指制造业以外的生产部门如农业、林业、畜牧业等生产的产品"}, {"w": "生众食寡", "t": "生产的多,消费的少。"}]}, {"meaning": "生命。", "cites": [{"t": "生,亦我所欲也,义,亦我所欲也,二者不可得兼,舍生而取义者也。", "b": "《孟子·告子上》"}, {"t": "此万物莫不然,而于有生之类为尤者。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "生力", "t": "生命力;气力"}, {"w": "生本", "t": "生命的根本"}, {"w": "生全", "t": "保全生命,全身"}, {"w": "生次", "t": "生命的存在"}, {"w": "生聚", "t": "生命财产"}, {"w": "生类", "t": "泛指一切有生命之物。"}]}, {"meaning": "人的一生。", "cites": [{"t": "穷余生之光阴以疗梅也哉!", "b": "清·龚自珍《病梅馆记》"}, {"t": "羡万物之得时,感吾生之行休。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "生世", "t": "一生;一生一世"}, {"w": "生禄", "t": "指人的寿限。"}]}, {"meaning": "生活。", "cites": [{"t": "自吾氏三世居是乡,积于今六十岁矣,而乡邻之生日蹙。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "哀吾生之无乐兮,幽独处乎山中。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "生资", "t": "赖以生活的资财"}, {"w": "生赖", "t": "赖以生活之资,生计"}, {"w": "生生", "t": "养生;生活。"}]}, {"meaning": "后生,长辈对晚辈的称呼。", "cites": [{"t": "隶而从者,崔氏二小生。", "b": "柳宗元《至小丘西小石潭记》"}]}, {"meaning": "老师称弟子,或弟子自称;学生。", "cites": [{"t": "东阳马生君则在太学已二年,流辈甚称其贤。余朝京师,生以乡人子谒余。", "b": "明·宋濂《送东阳马生序》"}, {"t": "庑下一生伏案卧,文方成草。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "新型师生关系", "t": ""}]}, {"meaning": "妓女。", "cites": [{"t": "呼妓为生,未知始于何时。", "b": "徐士銮《宋艳》"}]}, {"meaning": "俘虏。", "cites": [{"t": "每捉生踏伏,沔必在数。", "b": "段成式《酉阳杂俎·喜兆》"}]}, {"meaning": "年长有学问、有德行的人。“先生”的省称。", "cites": [{"t": "言《尚书》自济南伏生,言《礼》自鲁高堂生。", "b": "《史记》"}]}, {"meaning": "儒生;读书人的通称。", "cites": [{"t": "侯生遂为上客。", "b": "《史记·魏公子列传》"}]}, {"meaning": "资质;禀赋。", "cites": [{"t": "惟民生厚,因物有迁。", "b": "《书·君陈》。孔颖达疏:言人自然之性敦厚,因所见所习之物有迁变之道,故必慎所以示之。"}, {"t": "文王蹶厥生。", "b": "《诗·大雅·緜》"}, {"t": "辨五地之物生。", "b": "《周礼·地官·大司徒》"}, {"t": "人伦并处,同求而异道,同欲而异知,生也。", "b": "《荀子·富国》"}, {"t": "君子生非异也,善假于物也。", "b": "《荀子·劝学》"}]}, {"meaning": "天生,生来。", "cites": [{"t": "人非生而知之者。", "b": "《师说》"}], "words": [{"w": "生巧", "t": "天生巧慧"}, {"w": "生来", "t": "天生。从小时候起;从来"}, {"w": "生才", "t": "天才;英才。"}]}, {"meaning": "生的,未煮熟的。", "cites": [{"t": "项王曰:“赐之彘肩。”则与一生彘肩。", "b": "《史记·项羽本纪》"}]}, {"meaning": "新鲜的。", "cites": [{"t": "妃嗜荔枝,必欲生致之,乃置驿传送。", "b": "《新唐书·后妃传》"}], "words": [{"w": "生鲜", "t": "鲜活"}, {"w": "生卉", "t": "鲜草"}, {"w": "生肉", "t": "鲜肉"}, {"w": "生花", "t": "鲜花。"}]}, {"meaning": "生疏。", "cites": [{"t": "自别城中礼数生。", "b": "王建《村居即事》"}], "words": [{"w": "生人;生手;生帐子货", "t": "陌生人"}, {"w": "生客", "t": "陌生的客人。"}]}, {"meaning": "具有活力的。", "cites": [{"t": "金添生兵二十万来。", "b": "《宋史》"}]}, {"meaning": "很、甚、极其。", "cites": [{"t": "怎不将天地也生埋怨。", "b": "《窦娥冤》"}], "words": [{"w": "生恐", "t": "方言。很怕;很担心"}, {"w": "生疼", "t": "很疼,特别疼。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('264wx','矢','1','shǐ','矢','5','','[{"pinyin": "shǐ", "defs": [{"meaning": "(象形。甲骨文字形。象镝括羽之形。本义:箭)。"}, {"meaning": "同本义。以竹为箭,以木为矢。", "cites": [{"t": "矢又谓之箭。", "b": "《释名》"}, {"t": "矢,弓弩矢也。", "b": "《说文》"}, {"t": "掌六弓、四弩、八矢法。", "b": "《周礼·司弓矢》"}, {"t": "矢,箭也。", "b": "《广雅》"}, {"t": "嗑得金矢,解得黄矢。", "b": "《易·噬》"}, {"t": "疾如锥矢。", "b": "《战国策·齐策》"}, {"t": "侍投则拥矢。", "b": "《礼记·少仪》"}, {"t": "既挟我矢。", "b": "《诗·小雅·吉日》"}, {"t": "矢以柘若棘。", "b": "《大戴礼记·投壶》"}, {"t": "秦无亡矢遗镞之费,而天下诸侯已困矣。", "b": "汉·贾谊《过秦论》"}, {"t": "入于太亩,还矢先王。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "飞矢;矢石", "t": "箭和礧石。古代守城的武器"}, {"w": "矢人", "t": "造箭的工匠"}, {"w": "矢如雨下", "t": "箭像雨一样射来。极言其多"}, {"w": "矢房", "t": "箭袋"}, {"w": "矢书", "t": "战争中用箭射至敌方的文字"}, {"w": "矢干", "t": "箭杆"}, {"w": "矢锋", "t": "箭的尖端"}, {"w": "矢镝;矢镞", "t": "箭头"}, {"w": "矢刃", "t": "箭和刀。泛指兵器。"}]}, {"meaning": "古代投壶用的筹码。", "cites": [{"t": "主人奉矢。", "b": "《礼记·投壶》"}], "words": [{"w": "矢跃", "t": "谓投壶时筹从壶中跳了出来。亦泛指投壶活动。"}]}, {"meaning": "几何学名词。弧弦之半径。", "cites": [{"t": "值弧与弦之半曰矢。", "b": "清·戴震《句股割圜记上》"}]}, {"meaning": "人或动物排出的粪便。", "cites": [{"t": "杀而埋之马矢之中。", "b": "《左传·文公十八年》"}, {"t": "以筐盛矢。", "b": "《庄子·人间世》"}, {"t": "是人也,所谓以孤父之戈钃牛矢也。", "b": "《荀子·荣辱》"}, {"t": "顷之,三遗矢矣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "千村薜荔人遗矢,万户萧疏鬼唱歌。", "b": "毛泽东《送瘟神》"}]}, {"meaning": "发誓。", "cites": [{"t": "永矢弗谖。", "b": "《诗·卫风·考槃》"}, {"t": "夫子矢之曰……《论语·雍也》", "b": ""}, {"t": "遗风令歌,永矢不愃。", "b": "《汉·平舆令薛君碑》"}], "words": [{"w": "矢孤介", "t": "誓守清高不随世俗的品格"}, {"w": "矢素志", "t": "立誓实现自己的夙愿"}, {"w": "矢慎矢勤", "t": "立誓谨慎和勤勉"}, {"w": "矢棋", "t": "棋艺高明的人"}, {"w": "矢日", "t": "指着太阳发誓"}, {"w": "矢心不二", "t": "立誓无二心"}, {"w": "矢死", "t": "誓死"}, {"w": "矢志不渝", "t": "立誓决不改变自己的志向"}, {"w": "矢盟", "t": "立誓"}, {"w": "矢誓", "t": "立誓;盟誓"}, {"w": "矢忠", "t": ""}]}, {"meaning": "施行。", "cites": [{"t": "矢其文德,洽此四国。", "b": "《诗·大雅·江汉》"}, {"t": "书曰:公矢鱼于棠。", "b": "《左传·隐公五年》"}], "words": [{"w": "矢谋", "t": "施行计谋。"}]}, {"meaning": "陈述。", "cites": [{"t": "皋陶矢厥谟。", "b": "《书·大禹谟》"}], "words": [{"w": "矢心", "t": "陈示衷心。"}]}, {"meaning": "陈列。", "cites": [{"t": "公矢鱼于棠。", "b": "《春秋·隐公五年》"}]}, {"meaning": "直;正直,端正。", "cites": [{"t": "矢,直也。", "b": "《广雅》"}, {"t": "其直如矢。", "b": "《诗·小雅·小东》"}, {"t": "捍矢言而不纳。", "b": "潘岳《西征赋》"}], "words": [{"w": "矢节", "t": "正直守节"}, {"w": "矢夫", "t": "正直之臣"}, {"w": "矢言", "t": "正直之言;直言,直说。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('265wx','失','1','shī','大','5','','[{"pinyin": "shī", "defs": [{"meaning": "(形声。从手,乙声。表示从手中丢失。小篆字形。本义:失掉;丢失)。"}, {"meaning": "同本义。", "cites": [{"t": "失,纵也。", "b": "《说文》。段注:“在手而逸去为失。”"}, {"t": "失得勿恤。", "b": "《易·晋》"}, {"t": "故人情不失。", "b": "《礼记·礼运》。注:“犹去也。”"}, {"t": "君子不失足于人。", "b": "《礼记·表记》。注:“失其容止之节也。”"}, {"t": "掌国中失之事。", "b": "《周礼·师氏》。注:“失,失礼者也。”"}, {"t": "塞翁失马,今未足悲。", "b": "魏泰《东轩笔录》"}, {"t": "失道者寡助。", "b": "《孟子·公孙丑下》"}, {"t": "累官故不失州郡也。", "b": "《资治通鉴》"}, {"t": "此之谓失其本心。", "b": "《孟子·告子上》"}], "words": [{"w": "失状", "t": "丢失财物的清单"}, {"w": "失脱", "t": "丢失;失掉"}, {"w": "失国", "t": "丧失国家"}, {"w": "失鉴", "t": "失去检点"}, {"w": "失瞻", "t": "失敬"}, {"w": "失翁马", "t": "比喻暂时遭受损失,却因此得到好处"}, {"w": "失民", "t": "丧失民心"}, {"w": "失本", "t": "失去根本"}, {"w": "失正", "t": "失其正道"}, {"w": "失名", "t": "丧失名节"}, {"w": "失合", "t": "失去配偶"}, {"w": "失偶", "t": "丧失配偶"}, {"w": "失鹿", "t": "失去天下"}, {"w": "失道", "t": "失去准则;违背道义"}, {"w": "失众", "t": "失去民心;失去众心"}, {"w": "失柄", "t": "丧失统治权力。"}]}, {"meaning": "错过。", "cites": [{"t": "鸡、豚、狗、彘之畜,无失其时,七十者可以食肉矣。", "b": "《孟子·梁惠王上》"}, {"t": "奉不可失,敌不可纵。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "失眼", "t": "没有看准;看错了"}, {"w": "失人", "t": "错过人才;错用人才"}, {"w": "失候", "t": "错过适当的时刻。"}]}, {"meaning": "不自禁,忍不住。", "cites": [{"t": "庄公失言。", "b": "《谷梁传·庄公二十五年》"}, {"t": "丞相何故失惊?", "b": "《三国演义》"}], "words": [{"w": "失喜", "t": "喜欢到极点,不能自禁"}, {"w": "失手;失笑;失足;失惊", "t": "吃惊。"}]}, {"meaning": "违背。", "cites": [{"t": "论功计劳,未尝失法律。", "b": "章炳麟《原法》"}], "words": [{"w": "失礼;失约;失命", "t": "违误命令。"}]}, {"meaning": "遗漏。", "cites": [{"t": "细过不失。", "b": "《商君书·开塞》"}], "words": [{"w": "失恩", "t": "不顾恩义"}, {"w": "失脱", "t": "疏忽失误。"}]}, {"meaning": "迷失。", "cites": [{"t": "关山难越,谁悲失路之人?", "b": "王勃《滕王阁序》"}], "words": [{"w": "失心风", "t": "神经错乱;精神病"}, {"w": "失志", "t": "心地糊涂。"}]}, {"meaning": "消失;消灭。", "cites": [{"t": "惟觉时之枕席,失向来之烟霞。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "其远古刻尽漫失,僻不当道者,皆不及往。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "淫泆,放荡,放纵。", "cites": [{"t": "秦穆公出游而车败,右服失,野人得之。", "b": "《淮南子·汜论》。王念孙云:“失,同佚。”"}, {"t": "非吾敢横失能尽之难也。", "b": "《史记·老子韩非列传》"}, {"t": "德薄而位尊者谓之失。", "b": "《管子·立政》"}, {"t": "虞于湛乐,淫失其身。", "b": "《国语·周语下》"}]}, {"meaning": "过错,错误。", "cites": [{"t": "今吾且死,而侯生曾无一言半辞送我,我岂有所失哉!", "b": "《史记·魏公子列传》"}, {"t": "帝知其冤而宥其失。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "失误", "t": "过失,过错"}, {"w": "失闪", "t": "差错;意外事故"}, {"w": "失花儿", "t": "差错。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('266wx','乍','1','zhà','丿','5','','[{"pinyin": "zhà", "defs": [{"meaning": "(会意。小篆字形,从亡从一。本义:忽然)。"}, {"meaning": "同本义。", "cites": [{"t": "乍,暂也。", "b": "《广雅》"}, {"t": "今人乍见孺子。", "b": "《孟子》"}, {"t": "银瓶乍破。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "雷霆乍惊。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "离乍", "t": "分离很骤然"}, {"w": "乍乍", "t": "忽然"}, {"w": "江上渔火乍明乍灭;乍冷乍热,天气很不正常", "t": ""}]}, {"meaning": "刚;才。", "cites": [{"t": "波色乍明。", "b": "明·袁宏道《满井游记》"}, {"t": "乍出于匣。", "b": ""}], "words": [{"w": "春寒乍暖,又下起了毛毛细雨;大雨乍停,球赛又继续进行", "t": ""}]}, {"meaning": "初;开始。", "cites": [{"t": "韶光明媚,乍晴转暖清明后。", "b": "柳永《笛家弄词》"}], "words": [{"w": "初来乍到,情况又不大了解,怎能乱发议论呢!老战友分别多年,乍一见面内心多高兴!", "t": ""}]}, {"meaning": "正;恰。", "cites": [{"t": "归去潒沉醉,小院新池月乍寒。", "b": "后周·和凝《抛球乐》"}, {"t": "凉透小帘栊,乍夜长迟睡。", "b": "张翥《真珠帘》"}]}, {"meaning": "或者。", "cites": [{"t": "或卷或舒,乍轻乍重。", "b": "秦·李斯《用笔法》"}]}, {"meaning": "宁可。", "cites": [{"t": "乍向草中耿介死,不求黄金笼下生。", "b": "唐·李白诗"}]}, {"meaning": "因害怕而颤动。", "cites": [{"t": "不由我意张狂,心惊乍。", "b": "佚名《鸳鸯被》"}]}, {"meaning": "耸;竖。", "cites": [{"t": "直气得胡髭眉花一乍一乍的。", "b": "《红旗谱》"}], "words": [{"w": "毛乍", "t": "汗毛竖起。"}]}, {"meaning": "俏丽的。", "cites": [{"t": "俺那小姐呵,打扮的身子儿乍。", "b": "《西厢记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('267wx','禾','1','hé','禾','5','','[{"pinyin": "hé", "defs": [{"meaning": "(象形。金文字形,象垂穗的禾本科农作物。汉字部首之一。从“禾”的字多与农作物有关。本义:谷类作物的总称)。"}, {"meaning": "古代指粟,即今之小米。", "cites": [{"t": "禾,嘉谷也,二月始生,八月而孰,得时之中,故谓之禾。", "b": "《说文》"}, {"t": "粢黍稻其采谓之禾。盖凡谷皆以成实为费,禾象穗成,故为嘉谷之通名,谷未秀曰苗,已秀曰禾。", "b": "《广雅·释草》"}], "words": [{"w": "禾粟", "t": "谷粟"}, {"w": "禾畴", "t": "种植禾谷的田野"}, {"w": "禾颖", "t": "带芒的谷穗"}, {"w": "禾绢", "t": "谷穗"}, {"w": "禾线", "t": "谷穗"}, {"w": "禾稿", "t": "连茎带穗的谷类收获物"}, {"w": "禾菽", "t": "谷类和豆类。"}]}, {"meaning": "粟的植株;谷类植物的统称。", "cites": [{"t": "九月筑场圃,十月纳禾稼。", "b": "《诗·豳风·七月》"}, {"t": "六月禾未秀,官家已修仓。", "b": "聂夷中《田家》"}, {"t": "取禾三百亿。", "b": ""}, {"t": "取禾三百囷。", "b": ""}, {"t": "禾生陇亩无东西。", "b": "唐·杜甫《兵车行》"}, {"t": "一丘之禾。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "禾黍", "t": "泛指庄稼或粮食"}, {"w": "禾卉", "t": "谷类作物的植株"}, {"w": "禾稼", "t": "谷类作物的统称"}, {"w": "禾谷", "t": "谷类作物。"}]}, {"meaning": "特指初生没有吐穗的水稻。", "cites": [{"t": "夫惜草茅者耗禾穗,惠盗贼者伤良民。", "b": "《韩非子·难二》"}, {"t": "天大雷电以风,禾尽偃。", "b": "《书·金滕》"}], "words": [{"w": "禾田", "t": "稻田"}, {"w": "禾把", "t": "连穗带秆的稻捆子"}, {"w": "禾更旧时以稻谷代替差役的一种赋税;禾米", "t": "稻米"}, {"w": "禾稻", "t": "稻谷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('268wx','丘','1','qiū','丿','5','','[{"pinyin": "qiū", "defs": [{"meaning": "(会意兼指事。甲骨文字形,象地面上并立两个小土峰。本义:自然形成的小土山)。"}, {"meaning": "同本义。", "cites": [{"t": "丘,土之高也。非人所为也。从北,从一。一,地也。人居在丘南,故从北。", "b": "《说文》"}, {"t": "小陵曰丘。", "b": "《广雅·释丘》"}, {"t": "丘中有麦。", "b": "《诗·王风·丘中有麻》"}, {"t": "丘中有李。", "b": ""}, {"t": "是降丘宅土。", "b": "《书·禹贡》"}, {"t": "北陵坟衍。", "b": "《周礼·大司徒》"}, {"t": "以君之力,曾不能损魁父之丘,如太行、王屋何?", "b": "《列子·汤问》"}, {"t": "性本爱丘山。", "b": "晋·陶渊明《归园田居》诗"}, {"t": "从小丘西行。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "苫蔽成丘。", "b": "清·蒲松龄《聊斋志异·狼三则》"}], "words": [{"w": "荒丘", "t": "沙丘;丘坡"}, {"w": "丘林", "t": "山林"}, {"w": "丘岳", "t": "山岳。"}]}, {"meaning": "泛指山。", "cites": [{"t": "列缺霹雳,丘峦崩摧。", "b": "李白《梦游天姥吟留别》"}, {"t": "以登介丘。", "b": "《汉书·司马相如传》。注:“山也。”"}, {"t": "三丘。", "b": "《后汉书·张衡传》"}], "words": [{"w": "丘坂", "t": "山坡"}, {"w": "丘林", "t": "山林"}, {"w": "丘岳", "t": "山岳"}, {"w": "丘阜", "t": "山丘;土山。"}]}, {"meaning": "坟墓。", "cites": [{"t": "亦何面复上先人之丘墓乎。", "b": "司马迁《报任安书》"}, {"t": "尧葬济阴,丘垅皆小。", "b": "《汉书·楚元王传》"}, {"t": "出郭门直视,但见丘与坟。", "b": "《文选·佚名·古诗十九首》"}], "words": [{"w": "丘垄", "t": "祖先的坟茔;坟墓"}, {"w": "丘木", "t": "植于墓地以庇兆域的树木"}, {"w": "丘封", "t": "泛指坟墓"}, {"w": "丘冢", "t": "坟墓"}, {"w": "丘陇", "t": "坟墓。"}]}, {"meaning": "废墟。", "cites": [{"t": "曾不知夏之为丘兮。", "b": "《楚辞·屈原·九章·哀郢》"}], "words": [{"w": "丘垅", "t": "废墟,荒地"}, {"w": "丘井", "t": "荒丘、枯井。比喻人心寂然不动。"}]}, {"meaning": "地域。", "cites": [{"t": "是故得乎丘民。", "b": "《孟子·尽心下》"}, {"t": "四邑为丘。", "b": "《周礼·地官·小司徒》"}]}, {"meaning": "空;寡。", "cites": [{"t": "高祖微时,时其丘嫂食。", "b": "《汉书·楚元王传》"}], "words": [{"w": "丘城", "t": "空城"}, {"w": "丘荒", "t": "空旷;荒凉"}, {"w": "丘虚", "t": "空虚的意思"}, {"w": "丘亭", "t": "空亭。"}]}, {"meaning": "大。", "cites": [{"t": "乡丘老不通。", "b": "《管子·侈靡》"}, {"t": "时时过其丘嫂。", "b": "《汉书·楚元王传》"}], "words": [{"w": "三丘秧田", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('269wx','付','1','fù','亻','5','','[{"pinyin": "fù", "defs": [{"meaning": "(会意。从人,从寸。从“寸”,表示与手的动作有关。意思是:以手持物交付给别人。本义:给予)。"}, {"meaning": "同本义。", "cites": [{"t": "付,与也。", "b": "《说文》"}, {"t": "付,予也。", "b": "《广雅》"}, {"t": "若有作奸犯科及为忠善者,宜付有司论其刑赏。", "b": "诸葛亮《出师表》"}, {"t": "操当以肃还付乡党,品其名位,犹不失下曹从事。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "付法", "t": "传授佛法"}, {"w": "付任", "t": "把事情交给别人去做"}, {"w": "付治", "t": "交有司治罪"}, {"w": "付推", "t": "交付有审问"}, {"w": "付度", "t": "移交,交代"}, {"w": "付命", "t": "授以天命。"}]}, {"meaning": "支付。", "cites": [{"t": "当下付了茶钱。", "b": "《儒林外史》"}], "words": [{"w": "付借款的利息", "t": ""}]}, {"meaning": "涂;搽。", "cites": [{"t": "永不得着绮穿罗,再不能施朱付粉。", "b": "《金瓶梅词话》"}]}, {"meaning": "(fú)。符合。", "cites": [{"t": "计凡付终,务本饬末,则富。", "b": "《管子·幼官》"}]}, {"meaning": "归附,附着。", "cites": [{"t": "皇天既付中国民。", "b": "《书·梓材》"}, {"t": "致德,其民和平以静;致道,其民付而不争。", "b": "《管子·正》"}], "words": [{"w": "付山", "t": "归山。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('270wx','仗','1','zhàng','亻','5','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从人,丈声。本义:执,拿着)。"}, {"meaning": "同本义。", "cites": [{"t": "韩信仗剑从之。", "b": "《史记·淮阴侯列传》"}, {"t": "独行仗剑至韩。", "b": "《史记·刺客列传》"}], "words": [{"w": "仗斧", "t": "手持斧铖钺。表示权威"}, {"w": "仗节", "t": "手持符节;坚守节操"}, {"w": "仗策", "t": "手持马鞭。骑马。"}]}, {"meaning": "依靠,依赖。", "cites": [{"t": "仗,凭仗。", "b": "《广韵》"}, {"t": "仗兵革之彊。", "b": "《史记·春申君传》"}, {"t": "朕自得疾,数日不能得睡,今夜仗二将军威势甚安。", "b": "《西游记》"}], "words": [{"w": "仗腰子的", "t": "靠山;背后支持者"}, {"w": "仰仗", "t": "依靠;依赖"}, {"w": "依仗", "t": "倚仗靠别人的势力或有利条件"}, {"w": "狗仗人势;仗气", "t": "凭仗正气。也指任性使气"}, {"w": "仗气使酒", "t": "任性纵酒。"}]}, {"meaning": "弓、矛、剑、戟等兵器的总称。", "cites": [{"t": "帝自山下望其众,袍仗精整,人人尽力,壮之。", "b": "《新唐书》"}], "words": [{"w": "兵仗", "t": "兵器"}, {"w": "器仗;仪仗;明火执仗", "t": ""}]}, {"meaning": "仪仗队。", "cites": [{"t": "凡朝会之仗,三卫番上,分为五仗,号衙内五卫。", "b": "《新唐书》"}], "words": [{"w": "仗士", "t": "卫士"}, {"w": "仗下", "t": "皇帝视朝毕,所列仪仗兵卫退下"}, {"w": "仗马", "t": "皇帝仪仗队所用的马"}, {"w": "仗队", "t": "仪仗队。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('271wx','代','1','dài','亻','5','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。小篆字形,从人,弋(yì)声。本义:更迭,代替)。"}, {"meaning": "同本义。", "cites": [{"t": "代,更也。凡以此易彼,以后续前,皆曰代。", "b": "《说文》"}, {"t": "县壶以代哭者。", "b": "《周礼·挈壶氏》"}, {"t": "与君代兴。", "b": "《左传·昭公十二年》。注:“更也。”"}, {"t": "使子父代处。", "b": "《国语·晋语》。注:“更也。”"}, {"t": "岁代处,故曰代田。", "b": "《汉书·食货志》。注:“易也。”"}, {"t": "韩地代相干也。", "b": "《汉书·地理志》"}, {"t": "四时迭代。", "b": "张衡《东京赋》"}, {"t": "转相攻伐,代为雌雄。", "b": "《汉书·刑法志》"}, {"t": "日月迭炤,四时代御。", "b": "《荀子·天论》"}, {"t": "孝成王使括(赵括)代廉颇为将。", "b": "汉·刘向《列女传》"}, {"t": "逆夷更觉胆落心寒,亟请广州府余暨南、番二县代求解免。", "b": "《广州军务记》"}], "words": [{"w": "代比", "t": "代人接受惩罚"}, {"w": "代茶", "t": "以茶代物,自谦微薄"}, {"w": "代馆", "t": "代理教书"}, {"w": "代运", "t": "代替运行"}, {"w": "代力", "t": "代为劳作。"}]}, {"meaning": "父子相继为“代”、“世代”。", "cites": [{"t": "代,世也。", "b": "《后汉书·窦何传》注"}, {"t": "五代,谓唐虞夏殷周也。", "b": "《后汉书·王符传》注"}, {"t": "人生代代无穷已,江月年年只相似。", "b": "张若虚《春江花月夜》"}, {"t": "汉家李将军,三代将门子。", "b": "王维《李陵咏》"}]}, {"meaning": "(这个意义唐以前写作“世”,唐人为避唐太宗李世民之讳,将“世”写成“代”,后人一直沿用)。"}, {"meaning": "历史上的某一时期或年代。", "cites": [{"t": "未知始自何年,更不知止于何代。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "古代的雕刻", "t": ""}]}, {"meaning": "朝代。", "cites": [{"t": "老人邻有西塾,闻其师为弟子说前代事。", "b": "清·周容《芋老人传》"}], "words": [{"w": "唐代", "t": ""}]}, {"meaning": "中医脉象之一,指脉搏跳动时出现较长的停歇现象。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('272wx','仙','1','xiān','亻','5','','[{"pinyin": "xiān", "defs": [{"meaning": "(会意。本作“僊”。右边的意思是人爬到高处取鸟巢,加上“人”旁,表示人升高成仙。隶书作“仙”,表示仙人多住在高处。本义:仙人)。"}, {"meaning": "同本义。", "cites": [{"t": "僊,长生迁去也。", "b": "《说文》"}, {"t": "求僊人羡门之属。", "b": "《汉书·郊祀志》"}, {"t": "仙圣为之臣。", "b": "《列子·黄帝》。注:“仙寿考之迹。”"}]}, {"meaning": "神仙,古代神话和宗教中指修炼得道长生不死的人,或指能达到至高神界的人物。", "cites": [{"t": "山不在高,有仙则名。", "b": "刘禹锡《陋室铭》"}, {"t": "仙之人兮。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "如听仙乐。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "仙及鸡犬。", "b": "《聊斋志异·促织》"}], "words": [{"w": "仙机玄奥", "t": "深奥不可知晓"}, {"w": "仙人劝驾", "t": "指有威望的人从中调解"}, {"w": "仙醪", "t": "仙酒"}, {"w": "仙闼", "t": "神仙的住处"}, {"w": "仙机", "t": "奥秘"}, {"w": "仙车", "t": "驾临"}, {"w": "仙缘", "t": "可成仙的缘分。"}]}, {"meaning": "仙女。"}, {"meaning": "旧时对美分(百分之一美元)音译名生脱的简称,现在香港、台湾仍用;香港货币的分亦称“仙”。"}, {"meaning": "成仙。", "cites": [{"t": "举家皆仙。", "b": "晋·葛洪《抱朴子·金丹》"}]}, {"meaning": "轻松,自在。", "cites": [{"t": "行迟更觉仙。", "b": "杜甫《览镜呈柏中丞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('273wx','们','1','men','亻','5','','[{"pinyin": "men", "defs": [{"meaning": "“么”的变音字。", "cites": [{"t": "李逵道:“这们睡,闷死我也。”", "b": "《水浒传》"}]}, {"meaning": "注意：名词前有数量词时，后面不加“们”，例如不说“三个孩子们”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('274wx','仪','1','yí','亻','5','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从人,义声。本义:容止仪表)。"}, {"meaning": "同本义。", "cites": [{"t": "令仪令色,小心翼翼。", "b": "《诗·大雅》。郑玄笺:“善威仪,善颜色。”"}, {"t": "心质平理,其仪安闲。", "b": "《人物志》"}], "words": [{"w": "仪状", "t": "容貌形状"}, {"w": "仪观", "t": "容貌威仪"}, {"w": "仪宇", "t": "仪容;器量"}, {"w": "仪缀", "t": "威仪,外观"}, {"w": "仪止", "t": "仪表举止"}, {"w": "仪采", "t": "仪表风采"}, {"w": "仪相", "t": "仪表容貌"}, {"w": "仪形", "t": "仪容;形体"}, {"w": "仪状", "t": "仪容形状"}, {"w": "仪望", "t": "仪容;外表"}, {"w": "仪干", "t": "仪容体格"}, {"w": "仪操", "t": "仪容节操"}, {"w": "仪举", "t": "仪容举止。"}]}, {"meaning": "法度;礼法。", "cites": [{"t": "仪,度也。", "b": "《说文》。徐锴系传:“度,法度也。”"}, {"t": "置此以为法,立此以为仪,将以量度天下之王公大人、卿大夫之仁与不仁,譬之犹分黑白也。", "b": "《墨子》"}, {"t": "所以宣布哲人之令德,示民轨仪也。", "b": "《国语》"}], "words": [{"w": "仪刑", "t": "法式,作为模范"}, {"w": "仪令", "t": "法令"}, {"w": "仪准", "t": "法度标准"}, {"w": "仪则", "t": "法则"}, {"w": "仪司", "t": "泛称地方司法机构。"}]}, {"meaning": "典范;表率。", "cites": [{"t": "望三五以为像兮,指彭咸以为仪。", "b": "《楚辞》"}, {"t": "上者,下之仪也。", "b": "《荀子》"}], "words": [{"w": "仪范", "t": "作为典范"}, {"w": "仪象", "t": "以为模式"}, {"w": "仪形", "t": "典范;楷模"}, {"w": "仪型", "t": "楷模,典范。"}]}, {"meaning": "礼仪。仪式;礼节。", "cites": [{"t": "礼仪卒度。", "b": "《诗·小雅·楚茨》"}, {"t": "肄仪为位。", "b": "《周礼·春官·小宗伯》"}, {"t": "十六知礼仪。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "礼仪", "t": "礼节和仪式"}, {"w": "仪部", "t": "礼部"}, {"w": "仪文", "t": "礼仪的形式"}, {"w": "仪位", "t": "礼仪、爵位"}, {"w": "仪检", "t": "礼仪法式"}, {"w": "仪台", "t": "行礼仪的高台"}, {"w": "仪序", "t": "礼仪的秩序"}, {"w": "仪制", "t": "礼仪制度及其具体规定。"}]}, {"meaning": "仪仗。", "cites": [{"t": "仪马之设,自汉始也。", "b": "《事物纪原》"}], "words": [{"w": "仪马", "t": "仪仗队的马"}, {"w": "仪刀", "t": "皇帝仪仗中所用的刀"}, {"w": "仪剑", "t": "仪卫所持之剑"}, {"w": "仪卫", "t": "仪仗与卫士的统称"}, {"w": "仪驾", "t": "皇太后、皇后的仪仗。"}]}, {"meaning": "礼物,馈赠给某人或单位的钱或物。", "cites": [{"t": "且出此间,备些祭仪。", "b": "《古今小说》"}], "words": [{"w": "寿仪;谢仪", "t": ""}]}, {"meaning": "取法;效法。", "cites": [{"t": "仪肖曹之指挥,羡张陈之奇画。", "b": "《抱朴子》"}], "words": [{"w": "仪式", "t": "取法。"}]}, {"meaning": "拟想;推测;忖度。", "cites": [{"t": "皆心仪霍将军女。", "b": "《汉书·外戚孝宣许皇后传》"}, {"t": "仪之于民,而度之于群生。", "b": "《国语》"}], "words": [{"w": "仪图", "t": "揣想,忖度。"}]}, {"meaning": "匹配。", "cites": [{"t": "我仪图之。", "b": "《诗·大雅·庶民》。笺:“仪,匹也。”"}, {"t": "丹朱凭身以仪之。", "b": "《国语·周语上》。韦昭注:“仪,匹也。”"}, {"t": "帝体丽明,仪表作贰。", "b": "《文选·颜延之·应诏宴曲水作诗》"}], "words": [{"w": "仪比", "t": "比拟;比匹。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('275wx','白','1','bái','白','5','','[{"pinyin": "bái", "defs": [{"meaning": "(象形。甲骨文字形,象日光上下射之形,太阳之明为白,从“白”的字多与光亮、白色有关。本义:白颜色)。"}, {"meaning": "同本义。古人用以代表西方、秋季、金、肺等。", "cites": [{"t": "白,西方色也。殷用事物色白。", "b": "《说文》"}, {"t": "虚室生白。", "b": "《庄子·人间世》"}, {"t": "若白驹之过隙。", "b": "《庄子·知北游》"}, {"t": "白昼大都之中。", "b": "《汉书·贾谊传》"}, {"t": "白玉不毁,孰为圭璋。", "b": "《庄子·马蹄》"}, {"t": "须眉交白。", "b": "《庄子·渔父》"}, {"t": "蒹葭苍苍,白露为霜。", "b": "《诗·秦风·蒹葭》"}, {"t": "目辨白黑美恶。", "b": "《荀子·荣辱》"}, {"t": "太子及宾客知其一者,皆白衣冠以送之。", "b": "《战国策·燕策》"}, {"t": "永州之野产异蛇,黑质而白章。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "雪白", "t": "像雪一样的洁白"}, {"w": "白衣", "t": "白衣人。古代未仕者穿的白衣。"}]}, {"meaning": "纯洁;代表清流贤正。", "cites": [{"t": "粉身碎骨浑可怕,要留清白在人间。", "b": "于谦《石灰吟》"}], "words": [{"w": "白心", "t": "使心得以澄明清静;指洁白明静的心。"}]}, {"meaning": "亮;明亮。与“暗”相对。", "cites": [{"t": "雄鸡一声天下白。", "b": "李贺《致酒行》"}], "words": [{"w": "东方发白;白日鬼", "t": "指日间公然招摇撞骗的人。"}]}, {"meaning": "一无所有。", "cites": [{"t": "白手起家成业。", "b": "《杂纂新录》"}], "words": [{"w": "白文", "t": "不附加注解的书本正文;俗称“阴文”,碑文或印文虚白的部分"}, {"w": "白手起家", "t": "自食其力而没有任何凭藉依恃而创建家业"}, {"w": "白社", "t": "无人祭祀的土地庙,亦指荒无人烟的家乡"}, {"w": "白大人", "t": "没有功名的人"}, {"w": "白战", "t": "徒手相搏"}, {"w": "一穷二白", "t": ""}]}, {"meaning": "显著。", "cites": [{"t": "礼义不加于国,则功名不白。", "b": "《荀子·天论》"}]}, {"meaning": "真诚;坦白。", "cites": [{"t": "机心存于心中,则纯白不备。", "b": "《庄子·天地》"}]}, {"meaning": "古时罚酒用的酒杯。也泛指酒杯。", "cites": [{"t": "屡读屡叫绝,辄拍案浮一大白。", "b": "《虞初新志》"}, {"t": "飞觞举白。", "b": "左思《吴都赋》"}]}, {"meaning": "", "cites": [{"t": "白起,小竖子耳。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "清楚,明白。", "cites": [{"t": "然使君冤未白,犹无益也。", "b": "高启《书搏鸡者事》"}], "words": [{"w": "不白之冤;真相大白", "t": ""}]}, {"meaning": "表明;说明。", "cites": [{"t": "吾将以死白之。", "b": "《吕氏春秋·士节》"}, {"t": "是女子也,不能白事。", "b": "褚少孙《西门豹治邺》"}], "words": [{"w": "自白", "t": "自我表白"}, {"w": "表白", "t": "对人解释,说明自己的意思。"}]}, {"meaning": "禀告;报告。", "cites": [{"t": "虚吏白州,州白大府。", "b": "唐·柳宗元《童区寄传》"}]}, {"meaning": "上告;控告。", "cites": [{"t": "式白君,而君荐之,何也?", "b": "《三国志·吴志·陆逊传》"}]}, {"meaning": "使…白。", "cites": [{"t": "乃斫大树白而书之。", "b": "《史记·孙子吴起列传》"}, {"t": "莫等闲,白了少年头。", "b": "岳飞《满江红》"}]}, {"meaning": "白白,平白。", "cites": [{"t": "咱们金玉一般的人,白叫这两个现世宝玷污了去。", "b": "《红楼梦》"}, {"t": "白什么改了姓更了名。", "b": "睢景臣《高祖还乡》"}], "words": [{"w": "白死;白活;白等;白瞪", "t": "白瞪眼,束手无策的样子"}, {"w": "白做了一天工夫;白得;白看戏", "t": ""}]}, {"meaning": "单单;只是。", "cites": [{"t": "要是白来逛逛呢便罢,有什么说,只管告诉二奶奶", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('276wx','仔','1','zǎi zī zǐ','亻','5','','[{"pinyin": "zǎi", "defs": [{"meaning": "(会意兼形声。从人,从子,子亦声。甲骨文字形,是小孩的意思。本义:儿子)。"}]}, {"pinyin": "zī", "defs": [{"meaning": "任。", "cites": [{"t": "仔,克也。从人,子声。", "b": "《说文》"}, {"t": "佛时仔肩,示我显德行。", "b": "《诗·周颂·敬之》"}], "words": [{"w": "仔肩", "t": "所肩负的任务;责任。"}]}]}, {"pinyin": "zǐ", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('277wx','他','1','tā','亻','5','','[{"pinyin": "tā", "defs": [{"meaning": "(本作“佗”。形声。从人,“它”省声。本义:负担)。"}, {"meaning": "古代、近代泛指男女及一切事物,现代则用于称代自己和对方以外的男性第三者。", "cites": [{"t": "某以非他故。", "b": "《仪礼·士昏礼》。注:“弥亲之辞。”"}, {"t": "他用刚日。", "b": "《仪礼·士虞礼记》"}]}, {"meaning": "表示指称,相当于“别的”、“其他的”,与“此”相对 。", "cites": [{"t": "又况于他物乎?", "b": "《吕氏春秋·贵生》。注:“犹异也。”"}, {"t": "我亦无他。", "b": "宋·欧阳修《归田录》"}, {"t": "他工辈。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "此无他。", "b": "清·黄宗羲《原君》"}, {"t": "不在他人。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "他山", "t": "别处的山"}, {"w": "他心", "t": "别的打算;异心"}, {"w": "他志", "t": "别的想法、企图"}, {"w": "他故", "t": "别的理由、原因;别的事"}, {"w": "他室", "t": "别室"}, {"w": "他途", "t": "别的途径。多指不正当的途径"}, {"w": "他处", "t": "别处"}, {"w": "他肠", "t": "异心,恶意"}, {"w": "他意", "t": "别的企图;异心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('278wx','斥','1','chì','斤','5','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从广(yǎn),屰(nì)声。从“广”,表示与房屋有关。“屰”(不顺)也兼表字义,表示人从房屋里逆行而出。本义:驱逐)。"}, {"meaning": "同本义。", "cites": [{"t": "斥,却屋也。", "b": "《说文》。谓却退其屋不居。"}, {"t": "无益于民者斥。", "b": "《汉书·五帝纪》"}, {"t": "击吉斥之。", "b": "《汉书·江都易王非传》"}, {"t": "斥小疏弱。", "b": "《史记·天官书》"}, {"t": "程一日果以眦睚杀人,上大怒,立命斥出,付京兆。", "b": "王谠《唐语林》"}], "words": [{"w": "斥放", "t": "斥退放逐"}, {"w": "斥遣", "t": "斥退,驱逐"}, {"w": "斥远", "t": "摒拒疏远"}, {"w": "斥去", "t": "排斥并使之离去。"}]}, {"meaning": "责备。又称:斥詈,斥遣。", "cites": [{"t": "目晋侯斥杀。", "b": "《谷梁传·僖公五年》"}], "words": [{"w": "申斥", "t": "斥责"}, {"w": "驳斥", "t": "反驳错误的言论或意见。"}]}, {"meaning": "开拓,开。", "cites": [{"t": "斥,开也。", "b": "《小尔雅》"}, {"t": "塞斥之。", "b": "《史记·货殖列传》"}, {"t": "除边开益斥。", "b": "《史记·司马相如传》"}], "words": [{"w": "斥地", "t": "斥土。开拓土地;开土地为冢圹"}, {"w": "斥道", "t": "开辟道路。"}]}, {"meaning": "黜免。", "cites": [{"t": "是孔丘斥逐于鲁君,曾不用于世也。", "b": "《盐铁论·利议》"}, {"t": "朝拜而不道,夕斥之矣。", "b": "柳宗元《封建论》"}], "words": [{"w": "斥罢", "t": "罢免其职务"}, {"w": "斥免", "t": "斥罢。罢免。"}]}, {"meaning": "侦察。", "cites": [{"t": "斥候而服事。", "b": "《书·禹贡传》"}], "words": [{"w": "斥兵", "t": "侦察兵"}, {"w": "斥堠", "t": "侦察敌情的士兵。"}]}, {"meaning": "多;众多的。", "cites": [{"t": "寇盗充斥。", "b": "《左传·襄公三十一年》"}], "words": [{"w": "充斥", "t": ""}]}, {"meaning": "大的;广的;宽的。", "cites": [{"t": "坟衍斥斥。", "b": "左思《魏都赋》"}], "words": [{"w": "斥斥", "t": "广大的样子"}, {"w": "斥莫", "t": "广大空旷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('279wx','瓜','1','guā','瓜','5','','[{"pinyin": "guā", "defs": [{"meaning": "(象形。小篆字形,两边象瓜蔓,中间是果实,是藤上结瓜的形象。从“瓜”的字,多与瓜果有关。草木蔓生植物名。种类很多,果实也称瓜)。"}, {"meaning": "同本义 。属于双子叶植物瓜科。", "cites": [{"t": "七月食瓜,八月断(摘下)壶(葫芦)。", "b": "《诗·豳风·七月》"}, {"t": "大曰瓜,小曰瓞,瓜之近本初生者常小。", "b": "《诗经集注》"}, {"t": "绵绵瓜瓞。", "b": "《诗·大雅·绵》"}], "words": [{"w": "瓜田", "t": "种瓜的田"}, {"w": "瓜润", "t": "瓜受到灌溉后,长得更为丰美"}, {"w": "瓜练", "t": "冬瓜的瓤"}, {"w": "瓜瓤", "t": "瓜肉。"}]}, {"meaning": "瓜州。"}, {"meaning": "古地名。故址在今甘肃省敦煌县。"}, {"meaning": "治所在今甘肃省安西县东。"}, {"meaning": "瓜洲,镇名 。又称瓜埠洲。在江苏省邗江县南部大运河入长江处。"}, {"meaning": "(wō)。蜗牛。", "cites": [{"t": "自作一瓜牛庐,净扫其中。", "b": "《三国志·魏书·管宁传》"}]}, {"meaning": "瓜成熟。", "cites": [{"t": "虽蔬食,菜羹,瓜祭,必齐(同“斋”,斋戒)如也。", "b": "《论语·乡党》"}, {"t": "齐侯使连称、管至父戍葵丘,瓜时而往。", "b": "《左传·庄公八年》"}], "words": [{"w": "瓜期", "t": "瓜代之期。官员任满由别人接任的日期"}, {"w": "瓜时而往,及瓜而代", "t": "同“瓜期”"}, {"w": "瓜时", "t": "指瓜熟的时候。"}]}, {"meaning": "分割。", "cites": [{"t": "于时瓜剖区宇,蜂起英豪。", "b": "唐·白居易《汉高皇帝亲斩白蛇赋》"}], "words": [{"w": "瓜剖", "t": "分割土地,同瓜分"}, {"w": "瓜剖豆分", "t": "比喻国土被人侵占瓜分。也作“豆剖瓜分”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('280wx','乎','1','hū','丿','5','','[{"pinyin": "hū", "defs": [{"meaning": "(会意。甲骨文字形,上面的符号表示声音上扬,下面的符号表示舒气。“乎”是“呼”的本字。当“乎”借作语气词、介词用之后,就另造了一个从“口”的形声字“呼”。本义:吐气)。"}, {"meaning": "同本义。"}, {"meaning": "表示疑问或反诘。", "cites": [{"t": "汝识之乎?", "b": "苏轼《石钟山记》"}, {"t": "为人谋而不忠乎?与朋友交而不信乎?传不习乎?", "b": "《论语》"}, {"t": "近者大乎。", "b": "《列子·汤问》"}, {"t": "远者凉乎。", "b": ""}, {"t": "汝多知乎。", "b": ""}, {"t": "污其行乎。", "b": "《后汉书·列女传》"}, {"t": "断斯织乎。", "b": ""}, {"t": "不亦精乎。", "b": ""}]}, {"meaning": "相当于“吗”。", "cites": [{"t": "学而时习之,不亦说乎!", "b": "《论语》"}, {"t": "可乎。", "b": "《列子·汤问》"}, {"t": "不闻藏书者乎。", "b": "清·袁枚《黄生借书说》"}, {"t": "天下事有难易乎?", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "学有难易乎。", "b": ""}]}, {"meaning": "表示感叹语气或呼告。", "cites": [{"t": "中庸之为德也,其至矣乎!", "b": "《论语》"}, {"t": "二十年之外,吴其为沼乎!", "b": "《左传》"}, {"t": "长铗归来乎!食无鱼。", "b": "《史记·平原君虞卿列传》"}, {"t": "贤人乎,贤人乎!非质有其内,恶能用之哉?", "b": "《史记》"}, {"t": "有甚是者乎。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "天乎。", "b": "清·袁枚《祭妹文》"}, {"t": "人乎。", "b": ""}]}, {"meaning": "表示祈使或命令语气。相当于“啊”、“呀”。", "cites": [{"t": "勉速行乎!无重而罪!", "b": "《左传》"}]}, {"meaning": "表示推测语气。", "cites": [{"t": "宋其亡乎?幸而后败。", "b": "《左传》"}, {"t": "愿见之乎。", "b": "《三国志·诸葛亮传》"}, {"t": "得无苦贫乎。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "或能免乎。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "表示呼唤人的语气。相当于“啊”、“呀”。", "cites": [{"t": "参乎!吾道一以贯之。", "b": "《论语》"}]}, {"meaning": "表示商榷语气。", "cites": [{"t": "以容取人乎,失之子羽;以言取人乎,失之宰予。", "b": "《韩非子》"}]}, {"meaning": "表示肯定语气。", "cites": [{"t": "故曰:“礼者,忠信之薄也,而乱之首乎。”", "b": "《韩非子》"}]}, {"meaning": "于;在 。介绍动作、行为发生的时间。", "cites": [{"t": "吾独穷困乎此时也!", "b": "屈原《离骚》"}, {"t": "今虽死乎此。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "于;从  介绍动作、行为发生的时间。", "cites": [{"t": "“春秋”何以始乎隐?", "b": "《公羊·哀十四年》"}]}, {"meaning": "于;在 。介绍动作、行为发生的处所。", "cites": [{"t": "楚人生乎楚,长乎楚,而楚言。", "b": "《吕览·用众》"}]}, {"meaning": "于;从 。介绍行为、动作发生的地点。", "cites": [{"t": "叫嚣乎东西。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "隳突乎南北。", "b": ""}, {"t": "先率遇举,擢之乎宾客之中,而立之乎群臣之上。", "b": "《战国策》"}]}, {"meaning": "于;因为;由于;在于 。介绍动作、行为产生的原因。", "cites": [{"t": "不动乎众人之非誉。", "b": "《荀子》"}, {"t": "德荡乎名,知出乎争。", "b": "《庄子》"}]}, {"meaning": "于;按照;根据 。介绍动作、行为遵循的准则。", "cites": [{"t": "素富贵,行乎富贵;素贫贱,行乎贫贱。", "b": "《礼记》"}]}, {"meaning": "于,对。引进动作产生的对象。", "cites": [{"t": "吾尝疑乎是。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "用在形容词后面,单独不能翻译。", "cites": [{"t": "宜乎众矣。", "b": "宋·周敦颐《爱莲说》"}, {"t": "洸洸乎干城之具。", "b": "明·刘基《卖柑者言》"}, {"t": "昂昂乎庙堂之器。", "b": ""}, {"t": "巍巍乎可畏。", "b": ""}, {"t": "赫赫乎可象。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('281wx','丛','1','cóng','一','5','','[{"pinyin": "cóng", "defs": [{"meaning": "(会意。从丵,取声。“丵”(zhuó),意思是“丛生草”。本义:聚集)。"}, {"meaning": "同本义。", "cites": [{"t": "丛,聚也。", "b": "《说文》"}, {"t": "其植物宜丛物。", "b": "《周礼·大司徒》"}, {"t": "树木丛生,百草丰茂。", "b": "曹操《观沧海》"}], "words": [{"w": "丛物", "t": "聚生于一处的植物"}, {"w": "丛灌", "t": "丛生的灌木"}, {"w": "丛丛", "t": "聚集的样子"}, {"w": "丛育", "t": "聚集生长"}, {"w": "丛毛", "t": "丛生的草"}, {"w": "丛森", "t": "树木繁茂幽深样子"}, {"w": "丛薄", "t": "草木丛生的地方。"}]}, {"meaning": "许多事物凑在一起。", "cites": [{"t": "石块丛起则历块。", "b": "《徐霞客游记》"}, {"t": "则百恶并起,而万灾丛至矣。", "b": "《吕氏春秋·达郁》"}]}, {"meaning": "众多;繁杂。", "cites": [{"t": "网密事丛。", "b": "《汉书·酷吏传赞》"}, {"t": "恶丛巧之乱世兮。", "b": "《后汉书·冯衍传》"}], "words": [{"w": "丛顇", "t": "繁多杂乱的样子"}, {"w": "丛谈", "t": "各种轶事杂说"}, {"w": "丛委", "t": "杂谈的堆积"}, {"w": "丛丛杂杂", "t": "杂乱而繁多的样子"}, {"w": "丛细,丛琐", "t": "繁多琐碎。"}]}, {"meaning": "丛林;丛生的树木。", "cites": [{"t": "兽走丛薄之中。", "b": "《淮南子·俶真》"}, {"t": "又间令吴广之次所旁丛祠中。", "b": "《史记·陈涉世家》"}], "words": [{"w": "桉树丛;松树丛;丛祠", "t": "草野间的神祠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('282wx','令','1','líng lǐng lìng','人','5','','[{"pinyin": "líng", "defs": [{"meaning": "听从", "cites": [{"t": "故古之圣王,审顺其天而以行欲,则民无不令矣。", "b": "《吕氏春秋》"}]}, {"meaning": "名词", "cites": [{"t": "脊令在源,兄弟急难。", "b": "《诗·小雅·常棣》。按:脊令即鶺鸰"}]}, {"meaning": "假设语气词。", "cites": [{"t": "令,设辞也。", "b": "《助字辨略》"}, {"t": "令他马,固不败伤我乎!", "b": "《史记·张释之冯唐传》"}, {"t": "令五人保其首领。", "b": "明·张溥《五人墓碑记》"}]}]}, {"pinyin": "lǐng", "defs": [{"meaning": "纸的数量单位, 原张的纸 500 张为一令。"}]}, {"pinyin": "lìng", "defs": [{"meaning": "(会意。甲骨文字形,上面是集聚的“集”;下面是“人”,象跪在那里听命。从集从人,表示集聚众人,发布命令。本义:发布命令)。"}, {"meaning": "同本义(上对下有所指示)。", "cites": [{"t": "令,发号也。", "b": "《说文》"}, {"t": "倒之颠之,自公令之。", "b": "《诗·齐风·东方未明》"}, {"t": "既不能令,又不受命。", "b": "《孟子·离娄上》"}, {"t": "其身正,不令而行。", "b": "《论语·子路》"}, {"t": "令操已拥百万之众,挟天子以令诸侯。", "b": "陈寿《三国志》"}, {"t": "召令徒属曰。", "b": "《史记·陈涉世家》"}, {"t": "乃下令。", "b": "《战国策·齐策》"}]}, {"meaning": "又。", "cites": [{"t": "令初下。", "b": ""}, {"t": "令所过毋供张。", "b": "清·张廷玉《明史》"}], "words": [{"w": "令书", "t": "天子所下的书面命令"}, {"w": "令官", "t": "行酒令的指挥官"}, {"w": "令君", "t": "县令"}, {"w": "令人", "t": "宋代命妇的封号。太中大夫以上官员之妻封令人;又指衙役,差役"}, {"w": "令牌", "t": "发令的木牌"}, {"w": "令众", "t": "号令示众"}, {"w": "喝令", "t": "大声命令。"}]}, {"meaning": "命名。", "cites": [{"t": "昔黄帝以其缓急作五声,以政五钟。令其五钟:一曰青钟大音,二曰…", "b": "《管子》"}]}, {"meaning": "使,让。", "cites": [{"t": "又间令吴广之次所旁丛祠中,夜篝火。", "b": "《史记》"}, {"t": "令贼知也。", "b": "明·魏禧《大铁椎传》"}, {"t": "火烧令坚。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "令人目不忍睹。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "又。", "cites": [{"t": "令人丧气若此。", "b": ""}], "words": [{"w": "令人深思;令人恶心;令人神往", "t": ""}]}, {"meaning": "命令;法令。", "cites": [{"t": "臣下罔攸禀令。", "b": "《书·说命上》"}, {"t": "犯令陵政则杜之。", "b": "《周礼·夏官·大司马》"}, {"t": "令初下,群臣进谏,门庭若市。", "b": "《战国策·齐策》"}, {"t": "王使屈平为令,众莫不知。每一令出,平伐其功。", "b": "《史记·屈原列传》"}], "words": [{"w": "政令;将令", "t": "军令"}, {"w": "传令", "t": "传达命令"}, {"w": "功令", "t": "旧时指法令。"}]}, {"meaning": "时令,季节。", "cites": [{"t": "群葩当令时。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "令序", "t": "时令次序。"}]}, {"meaning": "酒令,饮酒时做的可分输赢的游戏。", "cites": [{"t": "今日也行一个令才有意思。", "b": "《红楼梦》"}], "words": [{"w": "令章", "t": "酒令"}, {"w": "令官", "t": "行酒令的指挥官"}, {"w": "令酒", "t": "行酒令的人;最初必自先饮一杯,称令酒。"}]}, {"meaning": "词调、曲调名,即“小令”,又称“令曲”,一般字少调短,如词中的《十六字令》,元曲中的《叨叨令》之类。", "cites": [{"t": "词之难于令曲,如诗之难于绝句,不过十数句,一句一字闭不得。", "b": "张炎《词源·令曲》"}]}, {"meaning": "官名。", "cites": [{"t": "卜皮为县令。", "b": "《韩非子·内储说上》"}]}, {"meaning": "县一级的行政长官。", "cites": [{"t": "魏文侯时,西门豹为邺令。", "b": "褚少孙《西门豹治邺》"}, {"t": "海令为母寿。", "b": "清·张廷玉《明史》"}, {"t": "刺史守令。", "b": "清·周容《芋老人传》"}, {"t": "守令皆不在。", "b": "《史记·陈涉世家》"}, {"t": "华阴令欲媚上官。", "b": "《聊斋志异·促织》"}], "words": [{"w": "县令;令尹", "t": "官名。春秋时楚国最高的军政长官;明清时称知县为令尹"}, {"w": "令长", "t": "汉官名。即县令、县长。"}]}, {"meaning": "名声。", "cites": [{"t": "饰小语以干县(悬)令。", "b": "《庄子》"}]}, {"meaning": "鶺鴒。鸟名,大如鷃雀。", "cites": [{"t": "脊令在原,兄弟急难。", "b": "《诗·小雅·常棣》"}]}, {"meaning": "美善。", "cites": [{"t": "巧言令色。", "b": "《论语·学而》。集解:“令色,善其颜色。”"}, {"t": "何忧令名不彰。(令名不彰,好的名声不会显扬。)", "b": "《世说新语·自新》"}, {"t": "年始十八九,便言多令才。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "令色", "t": "和悦的面容;善于用谄媚和悦的颜色取悦人"}, {"w": "令辰", "t": "美好的时辰"}, {"w": "令居", "t": "吉善的住处"}, {"w": "令音", "t": "美言,佳音"}, {"w": "令政", "t": "善政,德政"}, {"w": "令望", "t": "好的名望。"}]}, {"meaning": "你的——尊称他人的亲属。", "cites": [{"t": "岂合令郎君。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "有此令郎君。", "b": ""}], "words": [{"w": "令阃", "t": "称对方妻子的敬辞"}, {"w": "令嗣", "t": "令郎。称对方儿子的敬辞"}, {"w": "令子", "t": "对别人儿子的美称"}, {"w": "令母", "t": "尊称他人的母亲"}, {"w": "令似", "t": "尊称他人的儿子"}, {"w": "令妹", "t": "称自己的妹妹。后用作敬称对方的妹妹。"}]}, {"meaning": "假使,假设。", "cites": [{"t": "藉第令毋斩,戌死者固十六七矣。", "b": "《史记·陈涉世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('283wx','用','1','yòng','用','5','','[{"pinyin": "yòng", "defs": [{"meaning": "(象形。甲骨文字形,象桶形。桶可用,故引申为用。本义:使用,采用)。"}, {"meaning": "同本义。", "cites": [{"t": "用,可施行也。", "b": "《说文》"}, {"t": "用,以也。", "b": "《苍颉篇》"}, {"t": "利用为大作。", "b": "《易·益》"}, {"t": "五行五用哉。", "b": "《虞书》"}, {"t": "乃攘窃神胝之牺牷牺用。", "b": "《书·微子》"}, {"t": "乘其财用出入。", "b": "《周礼·宰夫》"}, {"t": "乃会万民之卒伍而用之。", "b": "《周礼·小司徒》"}, {"t": "保甲之法,起于三代丘甲。管仲用之齐,子产用之郑,商君用之秦,仲长统言之汉,而非今日之立异也。", "b": "宋·王安石《上五事札子》"}, {"t": "皆不足用。", "b": "明·魏禧《大铁椎传》"}, {"t": "用水彩。", "b": "蔡元培《图画》"}, {"t": "兼用激刺。", "b": ""}, {"t": "又用篆章。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "用不着", "t": "没办法"}, {"w": "备用", "t": "准备着供随时使用"}, {"w": "实用", "t": "实际使用"}, {"w": "拆用", "t": "拆开使用"}, {"w": "用功", "t": "使用功力"}, {"w": "用长", "t": "使用长武器"}, {"w": "用板", "t": "使用诏书"}, {"w": "用计", "t": "使用计谋"}, {"w": "用天因地", "t": "利用天时,顺应地利"}, {"w": "用钱", "t": "使用钱币"}, {"w": "用药", "t": "使用药物。"}]}, {"meaning": "任用(委派人员担任职务)。", "cites": [{"t": "不用尚书郎。", "b": "《乐府诗集·木兰诗》"}, {"t": "用于昔日。", "b": "诸葛亮《出师表》"}, {"t": "贤能为之用。", "b": "《三国志·诸葛亮传》"}, {"t": "不能用也。", "b": "《资治通鉴》"}], "words": [{"w": "大材小用", "t": "用人不当"}, {"w": "重用", "t": "把某人放在重要的岗位上"}, {"w": "叙用", "t": "任用"}, {"w": "起用", "t": "重新起用已退职或已免职的人员"}, {"w": "用才", "t": "任用人才"}, {"w": "用臣", "t": "可任用之臣"}, {"w": "用行舍藏", "t": "被任用就行其道,不被任用就退隐"}, {"w": "用贤", "t": "任用贤人。"}]}, {"meaning": "运用(根据事物的特性加以利用)。", "cites": [{"t": "用间有五:有因间、有内间、有反间、有死间、有生间。", "b": "《孙子·用间》"}], "words": [{"w": "用间", "t": "运用间谍"}, {"w": "用计铺谋", "t": "安排计谋;出谋划策"}, {"w": "用长", "t": "运用其所长"}, {"w": "用奇", "t": "指军事上运用出人意料的策略"}, {"w": "用思", "t": "运用心思"}, {"w": "用智", "t": "运用智谋。"}]}, {"meaning": "治理;管理。", "cites": [{"t": "仁人之用国,将修志意,正身行。", "b": "《荀子》"}], "words": [{"w": "用民", "t": "治理和役使民众。"}]}, {"meaning": "出力;效命。", "cites": [{"t": "国有事,则学民恶法,商民善化,技艺之民不用,故其国易破也。", "b": "《商君书》"}], "words": [{"w": "用精", "t": "专心一意。"}]}, {"meaning": "需要。", "cites": [{"t": "生不用封万户侯,但愿一识韩荆州。", "b": "李白《与韩荆州书》"}], "words": [{"w": "不用", "t": ""}]}, {"meaning": "执政;当权。", "cites": [{"t": "孔子用于楚,则陈蔡用事大夫危矣。", "b": "《史记》"}]}, {"meaning": "行事;行动。", "cites": [{"t": "经称鹏之用,其将飞也必待海之运,其飞也必以怒。", "b": "明·徐渭《赡张君序》"}]}, {"meaning": "功用;功能。", "cites": [{"t": "小礼无所用。", "b": "《史记·魏公子列传》"}, {"t": "彼虽善事,其用不足称也。", "b": "唐·韩愈《原毁》"}, {"t": "其用不足称。", "b": "唐·韩愈《原毁》"}, {"t": "灵用不同。", "b": "唐·李朝威《柳毅传》"}, {"t": "其用有二。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "用头", "t": "用途。"}]}, {"meaning": "器用;物质。", "cites": [{"t": "地方数千里,兵精足用,英雄乐业,当横行天下。", "b": "《资治通鉴》"}], "words": [{"w": "用器", "t": "器物;使用器物。"}]}, {"meaning": "费用,资财。", "cites": [{"t": "给其食用。", "b": "《战国策·齐策四》"}, {"t": "多求妄用。", "b": "宋·司马光《训俭示康》"}, {"t": "兵精足用。", "b": "《资治通鉴》"}, {"t": "裹物之用。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "家常之用。", "b": ""}]}, {"meaning": "因;由。", "cites": [{"t": "觉见卧闻,俱用精神。", "b": "《论衡》"}], "words": [{"w": "用逸待劳", "t": "以逸待劳"}, {"w": "用情", "t": "以真实的感情相待。"}]}, {"meaning": "凭,拿。", "cites": [{"t": "何用识夫婿。", "b": "《乐府诗集·陌上桑》"}, {"t": "高蝉正用一枝鸣。", "b": "宋·洪迈《容斋续笔》"}]}, {"meaning": "因,因为。", "cites": [{"t": "必用此为务。", "b": "《史记·货殖列传》"}, {"t": "用甲第为国相。", "b": "清·周容《芋老人传》"}, {"t": "用此。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "表示结果,相当于“因而”、“于是”。", "cites": [{"t": "明淫于家,用殄厥也。", "b": "《书·益稷》"}], "words": [{"w": "用是", "t": "因此。"}]}, {"meaning": "表示目的,相当于“为了”、“为的是”。", "cites": [{"t": "朕及笃敬,恭承民命,用永地于新邑。", "b": "《书·盘庚下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('284wx','甩','1','shuǎi','用','5','','[{"pinyin": "shuǎi", "defs": [{"meaning": "扔;抛开。", "cites": [{"t": "将手里的绢子一甩,向宝玉脸上甩来。", "b": "《红楼梦》"}, {"t": "等我紧走慢赶地快要走近他时,他又噔噔地自个儿向前走了,一下又把我甩下几丈远。", "b": "《百合花》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('285wx','印','1','yìn','卩','5','','[{"pinyin": "yìn", "defs": [{"meaning": "(会意。甲骨文字形。左是手爪,右象跪着的人,合起来表示用手按人使之跪拜。本义:官印)。"}, {"meaning": "同本义。", "cites": [{"t": "印,执政所持信也。", "b": "《说文》"}, {"t": "玺者,印也。印者,信也。", "b": "蔡邕《独断》"}, {"t": "印,验也。", "b": "《苍颉篇》"}, {"t": "玺谓之印。", "b": "《小尔雅》。按,古上下通曰玺。秦以来,天子诸侯王称玺,独以玉;列侯至二千石曰章,千石至四百石曰印。"}, {"t": "每字为一印。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "密布字印。", "b": ""}, {"t": "每一字皆有数印。", "b": ""}, {"t": "其印自落。", "b": ""}], "words": [{"w": "印务", "t": "有关印章管理和收发文书的工作;也指官印和职务"}, {"w": "印券", "t": "盖有官印的凭证"}, {"w": "印佩", "t": "官印"}, {"w": "印牌", "t": "将印或令牌"}, {"w": "印囊", "t": "古代装印信的口袋"}, {"w": "印曹", "t": "掌刻印的官。"}]}, {"meaning": "泛指图章。", "cites": [{"t": "凡写诗文,名印当在上,字印当在下,道号又次之…试看宋元诸儒真迹中,用印皆然。", "b": "明·徐官《古今印史》"}], "words": [{"w": "打印", "t": "盖图章"}, {"w": "印匣", "t": "印章盒"}, {"w": "印篆", "t": "印章"}, {"w": "印合", "t": "印盒,模子。"}]}, {"meaning": "痕迹,标记。", "cites": [{"t": "原来宋时,但是犯人,徒流迁徙的,都脸上刺字,怕人恨怪,只唤做“打金印”。", "b": "《水浒传》"}], "words": [{"w": "手印;印痕;印识", "t": "犹印记。"}]}, {"meaning": "盖章。", "cites": [{"t": "县啬夫若丞及仓、乡相杂以印之。", "b": "《睡虎地秦墓竹简》"}], "words": [{"w": "印子债", "t": "一种高利贷,即印子钱"}, {"w": "印结", "t": "清制外省人在京考试或捐官,皆须在京的同乡京官为具保结,上盖六部印,这文书叫“结”。盖印的“结”叫“印结”"}, {"w": "印马", "t": "验收马匹时诸监按马之优劣,在不同部位加不同印记"}, {"w": "印子铺(房)(放印子钱的处所", "t": ""}, {"w": "印封", "t": "盖印的封泥"}, {"w": "印署", "t": "盖印签押。"}]}, {"meaning": "印刷。", "cites": [{"t": "板印书籍。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "若止印二三本。", "b": ""}, {"t": "若印数十本。", "b": ""}, {"t": "此印者才毕。", "b": ""}], "words": [{"w": "印板", "t": "指用木或金属雕成的印刷底板"}, {"w": "印板儿", "t": "刻着字的板。喻印象深刻"}, {"w": "印造", "t": "印刷制作。"}]}, {"meaning": "印证 。证明与事实相符。", "cites": [{"t": "虽时光倒流,儿时可再,而亦无与为证印者矣。(证印:印证)。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "印正", "t": "证明;验证。"}]}, {"meaning": "使物上留下痕迹。", "cites": [{"t": "脚上印着黄泥。", "b": "郭沫若《女神》"}], "words": [{"w": "印合", "t": "模子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('286wx','尔','1','ěr','小','5','','[{"pinyin": "ěr", "defs": [{"meaning": "(形声。本义:窗格花纹)。"}, {"meaning": "同本义。"}, {"meaning": "后引作薾。华盛的样子。", "cites": [{"t": "彼尔维何?维常之华。", "b": "《诗·小雅》。毛传:“尔,华盛貌。”"}], "words": [{"w": "丽尔", "t": "华丽的样子。"}]}, {"meaning": "近。", "cites": [{"t": "戚戚兄弟,莫远具尔。", "b": "《诗·大雅》"}, {"t": "尔上敦黍于筵上右之。", "b": "《仪礼·少牢馈食礼》"}, {"t": "公降立于阼阶之东南,南乡尔卿。", "b": "《仪礼·燕礼》"}, {"t": "名相近者相远也,实相近者相尔也。", "b": "《周礼·地官·肆长》"}, {"t": "士不信悫而有多知能,譬之其豺狼也,不可以身尔也。", "b": "《荀子·哀公》"}], "words": [{"w": "尔者", "t": "近来"}, {"w": "尔语", "t": "凑向跟前说话。"}]}, {"meaning": "浅近。"}, {"meaning": "第二人称代词。"}, {"meaning": "", "cites": [{"t": "尔为尔,我为我。", "b": "《孟子》"}, {"t": "尔安敢轻吾射。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "尔当", "t": "你"}, {"w": "尔躲", "t": "你身上"}, {"w": "尔汝", "t": "尊对卑称;贵对贱称;朋友间的亲密互称"}, {"w": "尔济", "t": "汝辈,你们。"}]}, {"meaning": "那。", "cites": [{"t": "尔夜风恬月朗。", "b": "《世说新语》"}], "words": [{"w": "尔俸尔禄", "t": "那些俸禄。尔:其,那"}, {"w": "尔语", "t": "那样言语"}, {"w": "尔时", "t": "那时,彼时。"}]}, {"meaning": "这个;此。", "cites": [{"t": "问君何能尔。", "b": "晋·陶渊明《饮酒》"}], "words": [{"w": "尔夕", "t": "今夕,这个晚上"}, {"w": "尔日", "t": "当天,这天"}, {"w": "尔为", "t": "这样,如此。"}]}, {"meaning": "如此;这样。", "cites": [{"t": "尔毋从从尔。", "b": "《礼记·檀弓》"}], "words": [{"w": "果尔;乃尔;尔馨", "t": "六朝时语词。即如此"}, {"w": "尔为", "t": "如此"}, {"w": "尔许", "t": "若此,如许。尔,此也。许,助辞"}, {"w": "不尔;云尔", "t": ""}]}, {"meaning": "形容词、副词的词尾,相当于“然”。", "cites": [{"t": "鼓瑟希,铿尔,舍瑟而作。", "b": "《论语》"}]}, {"meaning": "", "cites": [{"t": "非死则徒尔。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "表示限止用在句末,可译为“而己”“罢了”。", "cites": [{"t": "唯手熟尔。", "b": "宋·欧阳修《归田录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('287wx','乐','1','lè yuè','丿','5','','[{"pinyin": "lè", "defs": [{"meaning": "喜悦;愉快。", "cites": [{"t": "有朋自远方来,不亦乐乎。", "b": "《论语·学而》"}, {"t": "并怡然自乐。", "b": "晋·陶渊明《桃花源记》"}, {"t": "游人去而禽鸟乐也。", "b": "欧阳修《醉翁亭记》"}, {"t": "君游海而乐之,奈臣有图国者何?", "b": "《韩非子·十过》"}, {"t": "似与游者相乐。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "熙熙而乐。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "快乐", "t": "感到幸福或满意"}, {"w": "乐嬉嬉", "t": "喜悦貌"}, {"w": "乐悦", "t": "欢喜"}, {"w": "乐笑", "t": "欢笑"}, {"w": "乐胥", "t": "喜乐"}, {"w": "乐哈哈", "t": "形容喜笑的样子"}, {"w": "乐好", "t": "爱好"}, {"w": "乐志(愉悦心志)乐心(心里快乐", "t": ""}, {"w": "乐利", "t": "快乐与利益"}, {"w": "乐易", "t": "和乐平易"}, {"w": "乐郊", "t": "乐土"}, {"w": "乐处", "t": "快乐的所在。"}]}, {"meaning": "安乐。", "cites": [{"t": "逝将去女,适彼乐土。", "b": "《诗·魏风·硕鼠》"}], "words": [{"w": "乐欣", "t": "安乐欢欣"}, {"w": "乐佚", "t": "悠闲安乐"}, {"w": "乐安", "t": "安乐"}, {"w": "乐郊", "t": "乐土。安乐幸福的地方"}, {"w": "乐居", "t": "安乐的住所"}, {"w": "乐国", "t": "安乐的地方。"}]}, {"meaning": "乐于;安于。", "cites": [{"t": "英雄乐业。", "b": "《资治通鉴》"}, {"t": "人未有不乐为治平之民者也。", "b": "洪亮吉《治平篇》"}, {"t": "亦乐生焉。", "b": "明·刘基《诚意伯刘文成公文集》"}]}, {"meaning": "又。", "cites": [{"t": "先生乐游。", "b": ""}], "words": [{"w": "乐助", "t": "乐意助成"}, {"w": "乐用", "t": "乐于用命"}, {"w": "乐士", "t": "喜爱贤士"}, {"w": "乐育", "t": "乐于教育、培养人才"}, {"w": "乐业", "t": "乐于本业"}, {"w": "乐愿", "t": "乐意,情愿"}, {"w": "乐成", "t": "乐于成全。"}]}, {"meaning": "感到快乐,享受。", "cites": [{"t": "不知太守乐其乐也。(第一个“乐”。)", "b": "欧阳修《醉翁亭记》"}]}, {"meaning": "旧指“声色”。即歌舞和女色。", "cites": [{"t": "今吴王淫于乐而忘其百姓。", "b": "《国语》"}]}, {"meaning": "乐趣。", "cites": [{"t": "此乐何极。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "山水之乐。", "b": "宋·欧阳修《醉翁亭记》"}]}, {"meaning": "又。", "cites": [{"t": "乐亦无穷也。", "b": ""}, {"t": "宴酣之乐", "b": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "yuè", "defs": [{"meaning": "(象形。小篆字形。象鼓鼙木架形。本义:音乐)。"}, {"meaning": "同本义。", "cites": [{"t": "乐,五声八音总名。象鼓鞞,木其虡也。", "b": "《说文》。按,五声八音相比而成乐。"}, {"t": "乐者,天地之和也。夫乐者,先王之所以饰喜也。", "b": "《礼记·乐记》"}, {"t": "伶伦作乐。", "b": "《礼记·世本》"}, {"t": "二曰六乐,谓云咸韵夏濩武也。", "b": "《周礼·保氏》"}, {"t": "以乐传教。", "b": "《吕氏春秋·慎行论》"}]}, {"meaning": "又。", "cites": [{"t": "和乐之本。", "b": ""}, {"t": "置酒设乐。", "b": "《汉书·李广苏建传》"}, {"t": "乐将作,遂旁设一虚坐,置琵琶于其上。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "乐作焉。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "《乐》之五声", "t": "指古时音乐分宫、商、角、徵、羽五音"}, {"w": "《乐记》", "t": "《礼记》中的篇名。简述了音乐起源及作用,是我国最早的音乐论著之一"}, {"w": "乐官", "t": "古代管理音乐的官员或官署"}, {"w": "乐节", "t": "音乐的节奏与节拍"}, {"w": "乐德", "t": "指古代音乐教育中的中、和等六种品德"}, {"w": "乐仪", "t": "有音乐相配合的礼仪。"}]}, {"meaning": "乐器。", "cites": [{"t": "乐既和奏。", "b": "《诗·小雅·宾之初筵》"}, {"t": "太师抢乐,箕子拘囚。", "b": "司马贞《索隐述赞》"}], "words": [{"w": "乐悬", "t": "指钟、罄之类悬挂的打击乐器"}, {"w": "乐品", "t": "乐器"}, {"w": "乐歌", "t": "有乐器伴奏的唱歌。"}]}, {"meaning": "乐工,精于音乐的人。", "cites": [{"t": "乐具入奏。", "b": "《诗·小雅·楚茨》"}, {"t": "齐人归女乐,季桓子受之,三日不朝,孔子行。", "b": "《论语》"}], "words": [{"w": "乐妇", "t": "歌妓"}, {"w": "乐人", "t": "能歌善舞的艺人"}, {"w": "乐女", "t": "古代女乐工。"}]}, {"meaning": "", "cites": [{"t": "乐羊子之妻者,不知何氏之女也。", "b": "《后汉书·列女传》"}]}, {"meaning": "唱,用口发音乐音。", "cites": [{"t": "比单而乐之。", "b": "《礼记》"}]}, {"meaning": "奏乐。", "cites": [{"t": "殿上酒九行,使相乐曲。", "b": "《辽史》"}], "words": [{"w": "乐钟", "t": "能发出音乐声响的自鸣钟"}, {"w": "乐手", "t": "演奏音乐的人"}, {"w": "乐生", "t": "奏乐歌舞的人员"}, {"w": "乐童", "t": "奏乐的童子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('288wx','句','1','gōu jù','口','5','','[{"pinyin": "gōu", "defs": [{"meaning": "(形声。从口。正当读今言钩,俗作勾。本义:弯曲)。"}, {"meaning": "同本义。", "cites": [{"t": "句,曲也。", "b": "《说文》。段注:“凡曲折之物,侈为倨,敛为句。考工记多言倨句。”"}, {"t": "越子为左右句卒。", "b": "《左传·哀公十七年》"}, {"t": "句兵欲无弹。", "b": "《考工记·庐人》"}, {"t": "覆之而角至谓之句弓。", "b": "《考工记·弓人》"}, {"t": "履句履者知地。", "b": "《庄子·田子方》。李注:“方也。”"}, {"t": "句者毕出。", "b": "《礼记·月令》"}, {"t": "古之人衣上有冒而句领者。", "b": "《尚书大传》"}, {"t": "句者毕出,萌者尽达。", "b": "《礼记·月令》"}]}, {"meaning": "勾画。", "cites": [{"t": "说书虽小技,然必句性情,习方俗。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "如果——表示假设。", "cites": [{"t": "吾句能亲亲而兴贤,吾不遗亦至矣。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "古称不等腰直角三角形直角旁的短边。"}, {"meaning": "——人名用字。"}]}, {"pinyin": "jù", "defs": [{"meaning": "(会意。小篆字形,从口,从丩(jiū),象绳丝缠结之状)。“丩”亦兼表字音。①(gōu)本义:弯曲。②句子。"}, {"meaning": "语句;诗句。", "cites": [{"t": "句者,局也。联字分疆,所以局言者也。周伯琦曰:“语绝为句。”", "b": "《诗·关雎》疏。按,取稽留可钩之意,曲画以识之者也。说文瞿下曰:读如章句之句,则后汉时已转其音如今言屦。"}, {"t": "驴上得句。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "所得诗句。", "b": ""}, {"t": "书诗四句。", "b": "宋·王安石《伤仲永》"}, {"t": "蒙蒙之句。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "句式", "t": "句子的结构形式"}, {"w": "句语", "t": "语句,言辞"}, {"w": "句投", "t": "句逗。即句读"}, {"w": "句度", "t": "同句读。"}]}, {"meaning": "中国汉代行大礼时,由九宾中地位最低的士依次向上传话,与“胪”相反。", "cites": [{"t": "大行设九宾,胪、句传。", "b": "《汉书》"}]}, {"meaning": "用于时间的计量。表示点时,相当于“点”;表示时段时,相当于“个”(钟头)。", "cites": [{"t": "这时已经有六句钟了。", "b": "蒋光慈《弟兄夜话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('289wx','匆','1','cōng','勹','5','','[{"pinyin": "cōng", "defs": [{"meaning": "急促地", "cites": [{"t": "老栓匆匆走出,给他泡上茶。", "b": "鲁迅《药》"}], "words": [{"w": "匆冗", "t": "繁忙冗杂的事务。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('290wx','册','1','cè','丿','5','','[{"pinyin": "cè", "defs": [{"meaning": "(象形。金文、小篆字形与甲骨文相似,象简册形。本义:书简。古代文书用竹简。编简名为册,后凡簿籍均可称“册”)。"}, {"meaning": "同本义。", "cites": [{"t": "册,符命也。诸侯进受于王者。象其札,一长一短,中有二编之形。古文又从竹。", "b": "《说文》"}]}, {"meaning": "经传多以策为之,字俗作筴。", "cites": [{"t": "史乃册祝。", "b": "《书·金滕》"}, {"t": "公归,乃纳册于金滕之匮中。", "b": ""}, {"t": "王命作册。", "b": "《书·洛诰》"}, {"t": "有册有典。", "b": "《书·多士》"}], "words": [{"w": "名册;画册;纪念册;册书", "t": "史籍,史书。"}]}, {"meaning": "特指皇帝的诏书。", "cites": [{"t": "祝册自京师至。", "b": "韩愈《南海神庙碑》"}], "words": [{"w": "册文", "t": "古代帝王祭祀时告天地神袛的文书"}, {"w": "册书", "t": "古时君王施于臣下的文书。有祝册、玉册、立册、封册、哀册、赠册、谥册、赠谥册、祭册、赐册、免册等十一种。"}]}, {"meaning": "册封,封爵。", "cites": [{"t": "册太子则授玺绶。", "b": "《新唐书·百官至》"}], "words": [{"w": "册立", "t": "古代帝王封立太子、皇后"}, {"w": "册正", "t": "把妾扶为正室。"}]}, {"meaning": "计算书本数量的单位。", "cites": [{"t": "且携所著书及诗文辞稿本数册。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "人手一册;这套书共印十万册", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('291wx','卯','1','mǎo','卩','5','','[{"pinyin": "mǎo", "defs": [{"meaning": "(象形。象两扇门打开之形。本义:门开着)。"}, {"meaning": "用以纪月,即农历二月。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('292wx','犯','1','fàn','犭','5','','[{"pinyin": "fàn", "defs": [{"meaning": "同本义。", "cites": [{"t": "犯,侵也。", "b": "《说文》。按,字本言犬犯人。转注为凡干陵违逆之称。"}, {"t": "軓又义兴水中有蛟,山中有白额虎,并皆暴犯百姓。", "b": "《世说新语·自新》"}], "words": [{"w": "人不犯我,我不犯人;犯界", "t": "侵犯他国领土"}, {"w": "犯境", "t": "犯边。侵犯边界。"}]}, {"meaning": "触犯,冒犯。", "cites": [{"t": "若有作奸犯科及为忠善者,宜付有司论其刑赏。", "b": "诸葛亮《出师表》"}, {"t": "原来杨修为人恃才放旷,数犯曹操之忌。", "b": "《三国演义》"}], "words": [{"w": "犯忌讳;犯阙", "t": "危害国家,对抗朝廷。阙:指朝廷"}, {"w": "犯颜", "t": "冒犯他人的尊严。颜:颜面,引申为尊严,威严"}, {"w": "犯鳞", "t": "因直谏触犯君王"}, {"w": "犯众", "t": "触犯众人。"}]}, {"meaning": "袭击。", "cites": [{"t": "王祖帅诸垒共救之,夜犯燕军,燕人逆击,走之。", "b": "《资治通鉴》"}]}, {"meaning": "遭遇;顶着;冒着。", "cites": [{"t": "触风雨,犯寒暑。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "又。", "cites": [{"t": "盖一岁之犯死者二焉。", "b": ""}]}, {"meaning": "侵害。", "cites": [{"t": "水火之所犯,犹不可救,而况天乎?", "b": "《国语》"}]}, {"meaning": "伤害,损害。", "cites": [{"t": "季子皋葬其妻,犯人之禾。", "b": "《礼记·檀弓》"}]}, {"meaning": "欺凌,污辱。", "cites": [{"t": "后盗欲有犯妻者,乃先劫其姑。", "b": "《后汉书》"}]}, {"meaning": "违背;违反。", "cites": [{"t": "犯令陵政则杜之。", "b": "《周礼·大司马》。注:“犯令者,违命也。”"}, {"t": "犷悍无赖,犯法当死。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "犯干", "t": "违反;触犯"}, {"w": "犯顺", "t": "违背情理"}, {"w": "犯节", "t": "违背礼节"}, {"w": "犯教", "t": "违背礼教。"}]}, {"meaning": "值得(与不连用)。", "cites": [{"t": "四丫头不犯罗唣你,却是谁呢?", "b": "《红楼梦》"}]}, {"meaning": "制服;胜。", "cites": [{"t": "人无毛羽,不衣则不犯寒。", "b": "《韩非子》"}]}, {"meaning": "落入;落到。", "cites": [{"t": "犯到他手里,也是一个死。", "b": "《老残游记》"}]}, {"meaning": "至,到。", "cites": [{"t": "适路过此间,天晚,特造檀府借宿一宵,明早不犯天光就行。", "b": "《西游记》"}]}, {"meaning": "犯人,罪犯。", "cites": [{"t": "及他犯同谋多人者。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "惯犯;首犯;主犯;刑事犯;逃犯", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('293wx','外','1','wài','夕','5','','[{"pinyin": "wài", "defs": [{"meaning": "(会意。从夕,从卜。通常在白天占卜,如在夜里占卜,表明边疆(外)有事。又有人说,因为要在外过夜,故要卜问吉凶。本义:外面;外部)。"}, {"meaning": "同本义。与“内”或“里”相对。", "cites": [{"t": "外,远也。", "b": "《说文》"}, {"t": "凡卜筮日旬之外曰远。", "b": "《礼记·曲礼》"}, {"t": "外骨内骨。", "b": "《周礼·考工记·梓人》"}, {"t": "夜来城外一尺雪。", "b": "唐·白居易《卖炭翁》"}, {"t": "竹外桃花三两枝。", "b": "宋·苏轼《惠崇春江晚景》"}, {"t": "中通外直。", "b": "宋·周敦颐《爱莲说》"}, {"t": "身外即战场。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "外户", "t": "从外面关闭的大门"}, {"w": "外祟", "t": "指外来的危害"}, {"w": "外槨", "t": "棺材外的套棺"}, {"w": "外好里枒槎", "t": "对外人好,对自己人苛刻"}, {"w": "外藩", "t": "外部屏藩"}, {"w": "外廓", "t": "外城"}, {"w": "外见", "t": "显现于外"}, {"w": "外求", "t": "求之于外"}, {"w": "外舍", "t": "在外住宿。"}]}, {"meaning": "外表;仪表。", "cites": [{"t": "吉凶见乎外。", "b": "《易·系辞》"}, {"t": "外托服从之名。", "b": "《资治通鉴》"}], "words": [{"w": "外象包皮", "t": "指善恶美丑表现在身上,行动语言表现在外表上"}, {"w": "外表", "t": "人的外貌仪表"}, {"w": "外秀", "t": "外表俊秀"}, {"w": "外和", "t": "外表和气"}, {"w": "外化", "t": "外表的变化"}, {"w": "外方内圆", "t": "谓外表正直,内心圆滑"}, {"w": "外视", "t": "外观、外表。"}]}, {"meaning": "表面。", "cites": [{"t": "无非是三等喻品,外像皮毛。——明·佚名《梼杌闲评——明珠缘》", "b": ""}], "words": [{"w": "外刑", "t": "施于身体表面的刑罚"}, {"w": "外像", "t": "表面现象"}, {"w": "外局", "t": "表面上"}, {"w": "外合里表", "t": "表里不一"}, {"w": "外见", "t": "显现于外"}, {"w": "外扬", "t": "显现于外"}, {"w": "外意", "t": "文字描绘的表面意义"}, {"w": "外营", "t": "外层营垒。"}]}, {"meaning": "古代妻子对丈夫的称呼。", "cites": [{"t": "夫妇相称曰外内,晋、魏以前无之。", "b": "清·钱大昕《恒言录》"}]}, {"meaning": "外地;异乡。", "cites": [{"t": "上年老太太生日,曾有一个外路和尚来孝敬一个蜡油冻的佛手。", "b": "《红楼梦》"}], "words": [{"w": "外役", "t": "在外服役"}, {"w": "外奔", "t": "逃亡国外,逃离本阵营,投奔他方"}, {"w": "外府", "t": "外地"}, {"w": "外路和尚", "t": "从外地来的和尚。即行脚僧。"}]}, {"meaning": "母亲、妻子、姐妹或儿女方面的(指亲属)。", "cites": [{"t": "周三不合图财杀害外父外母。", "b": "明·冯梦龙《警世通言》"}], "words": [{"w": "外氏", "t": "外祖父母家"}, {"w": "外祖", "t": "外祖父"}, {"w": "外外", "t": "外甥"}, {"w": "外外姐姐", "t": "外甥媳妇"}, {"w": "外家", "t": "岳父家"}, {"w": "外孝", "t": "属于母族、妻族或出嫁姐妹等方面的"}, {"w": "外大父", "t": "外祖父"}, {"w": "外王父", "t": "外祖父"}, {"w": "外王母", "t": "外祖母。"}]}, {"meaning": "指外廷臣僚。", "cites": [{"t": "一个外郎,叫做丘三。", "b": "《初刻拍案惊奇》"}], "words": [{"w": "外郎", "t": "官名。宋元时亦称衙门书吏"}, {"w": "外朝", "t": "指在外朝参政诸官。后泛指朝臣。"}]}, {"meaning": "指地方官。亦谓京官调任地方官。", "cites": [{"t": "厥初防其淫,明敕内外臣。", "b": "白居易《重赋》"}], "words": [{"w": "外班", "t": "指分发到外省任职的班次"}, {"w": "外吏", "t": "外臣。指地方官"}, {"w": "外镇", "t": "镇守边关要塞的将帅"}, {"w": "外藩", "t": "有封地的诸侯王"}, {"w": "外补", "t": "道员的缺分,原则上由中央任命,但也规定了几个缺位,由外省督抚呈请任用。"}]}, {"meaning": "以外。", "cites": [{"t": "其外之文。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "秦以攻取之外。", "b": "宋·苏洵《六国论》"}, {"t": "付之度外。", "b": "宋·文天祥《指南录后序》"}]}, {"meaning": "又如:外作(正业之外的事);外郡(京都以外的州郡);外埠(本地以外的城镇);外境(国境以外的地区)。"}, {"meaning": "外来的。", "cites": [{"t": "这一起外祟何日是了!", "b": "《红楼梦》"}]}, {"meaning": "又如:外寇(外来的敌兵);外祟(外来的鬼怪、祸祟);外忧(外来的忧患);外比(外附,勾结外乱)。"}, {"meaning": "传统戏曲脚色行当。", "cites": [{"t": "外扮监斩官上。", "b": "元·关汉卿《窦娥冤》"}]}, {"meaning": "疏远。关系、感情上保持距离。", "cites": [{"t": "内小人而外君子。", "b": "《易·否》"}], "words": [{"w": "勿外", "t": "不要见外"}, {"w": "外我", "t": "视我为外人;疏远我"}, {"w": "外道", "t": "作客时,显得很疏远。"}]}, {"meaning": "背离。", "cites": [{"t": "骤令不行,民心乃外。", "b": "《管子·版法》"}]}, {"meaning": "排斥。", "cites": [{"t": "坚、白、石不相外,藏三可乎?", "b": "《公孙龙子》"}]}, {"meaning": "抛弃。", "cites": [{"t": "有所通,则贪污之利外矣。", "b": "《吕氏春秋》"}]}, {"meaning": "另外;其他;别的。", "cites": [{"t": "令居外宅。", "b": "《史记·衡山王列传》"}], "words": [{"w": "外教", "t": "外央。外行"}, {"w": "外来钱", "t": "外快。额外的财利"}, {"w": "外转", "t": "外输;外快"}, {"w": "外慕", "t": "犹言他求;别有喜好"}, {"w": "外第", "t": "别宅"}, {"w": "外累", "t": "谓身外事物的烦扰、拖累。"}]}, {"meaning": "非正式的,非正规的,不正当的。", "cites": [{"t": "齐悼惠王肥,其母,高祖微时外妇也。", "b": "《汉书·齐悼惠王传》"}], "words": [{"w": "外四路", "t": "指远亲"}, {"w": "外务", "t": "份外的事;外遇"}, {"w": "外宅", "t": "外妇;外室。指与男子无妻妾关系而同居的妇女"}, {"w": "外名", "t": "外号"}, {"w": "外妇", "t": "外妻;指男子于正妻以外在别处另娶的妾或私通之妇"}, {"w": "外道", "t": "歪门邪道,搞不正当的活动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('294wx','处','1','chú chù','夂','5','','[{"pinyin": "chú", "defs": [{"meaning": "(会意。从口,从文,或从处,虍(hū)声。“处”即“處”的古字,于六书为会意。金文加声旁“虍(hù)”变成了形声字。本义:中止;停止)。"}, {"meaning": "同本义。", "cites": [{"t": "処,止也。得几而止。", "b": "《说文》"}, {"t": "君子之道,或出或处。", "b": "《易·系辞上》"}, {"t": "处者处。", "b": "《礼记·射义》。注:“犹留也。”"}, {"t": "譬之如牛马处暑之既至。", "b": "《国语·楚语》。注:“止也。”"}, {"t": "日月不恒处,人生忽若离。", "b": "三国魏·曹植《浮萍篇》"}]}, {"meaning": "居住;生活。", "cites": [{"t": "莫敢遑处。", "b": "《诗·召南·殷其靁》"}, {"t": "占右穴居而野处。", "b": "《易·系辞下》"}, {"t": "淖约若处子。", "b": "《庄子·逍遥游》。释文:“在室女也。”按,凡士或女未用皆称处。"}, {"t": "处江湖之远则忧其君。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "穴居野处;处妇", "t": "居家的妇女"}, {"w": "处处", "t": "居其所当居的地方"}, {"w": "处势", "t": "居于有权势的高位"}, {"w": "处逸", "t": "生活在安逸之中"}, {"w": "处安思危", "t": "居安思危。"}]}, {"meaning": "居家不仕,隐居。", "cites": [{"t": "处士横议。", "b": "《孟子》"}, {"t": "处人以誉尊。", "b": "《淮南子·主术》。谓有道艺在家隐居不仕者。"}], "words": [{"w": "处人", "t": "居家不出之人;隐士"}, {"w": "处家", "t": "居家;在家里。"}]}, {"meaning": "惩罚。", "cites": [{"t": "议罪处罚。", "b": "《汉书·师丹传》"}], "words": [{"w": "处制", "t": "处罚"}, {"w": "处斩", "t": "执行斩决。"}]}, {"meaning": "治理;办理。", "cites": [{"t": "德以处事。", "b": "《左传·文公十八年》"}], "words": [{"w": "处制", "t": "处理;办理"}, {"w": "处断", "t": "处理决断"}, {"w": "处方", "t": "给病人开药方。"}]}, {"meaning": "决断;定夺。", "cites": [{"t": "臣愚不能处也。", "b": "《汉书·谷永传》。注:“断决也。”"}], "words": [{"w": "处正", "t": "犹裁决"}, {"w": "处变", "t": "处置事变。"}]}, {"meaning": "对待。", "cites": [{"t": "何以处我?", "b": "《礼记·檀弓下》"}], "words": [{"w": "处待", "t": "处置;对待"}, {"w": "处物", "t": "对待人和事物。"}]}, {"meaning": "相交,交往。", "cites": [{"t": "与贵酋处二十日,争曲直,屡当死。", "b": "文天祥《指南录后序》"}], "words": [{"w": "处不来;处常", "t": "长远相处"}, {"w": "处交", "t": "结交,社交。"}]}, {"meaning": "定,常。", "cites": [{"t": "喜怒无处。", "b": "《吕氏春秋·诬徒》。注:“处,常也。”"}, {"t": "犹思故处。", "b": "《吕氏春秋·音初》"}]}]}, {"pinyin": "chù", "defs": [{"meaning": "处所;地方。人或物所在的地方。", "cites": [{"t": "处,所也。", "b": "《广韵》"}, {"t": "五刑三次,是无隐也。", "b": "《国语·鲁语上》。注:“次,处也。三处,野朝市。”"}, {"t": "迁徙往来无常处。", "b": "《史记·五帝纪》"}, {"t": "夫猎,追杀兽兔者狗也,而发迹指示兽处者人也。", "b": "《史记·萧相国世家》"}, {"t": "儿童相见不相识,笑问客从何处来。", "b": "贺知章《回乡偶书》"}, {"t": "晓看红湿处,花重饰官城。", "b": "杜甫《春夜喜雨》"}], "words": [{"w": "住处;别处;停车处", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('295wx','冬','1','dōng','夂','5','','[{"pinyin": "dōng", "defs": [{"meaning": "(会意。表示时序终了,已进入寒冷季节。四季中的第四季,即农历十月至十二月)。"}, {"meaning": "一年四季中秋春之间的季节,天文学上认为是从12月至3月,农历十月到十二月。", "cites": [{"t": "冬,四时尽也。", "b": "《说文》"}, {"t": "我有旨蓄,亦以御冬。", "b": "《诗·邶风·谷风》"}, {"t": "无冬无夏。", "b": "《诗·陈风·宛丘》"}, {"t": "冬者,五谷成熟,物备礼成。", "b": "《后汉书·张纯传》"}], "words": [{"w": "冬暖夏凉;冬酿", "t": "冬季酿酒"}, {"w": "冬温", "t": "冬天所害的一种热病"}, {"w": "冬计", "t": "寒冬的生计。"}]}, {"meaning": "冬月,阴历十一月的俗称。", "cites": [{"t": "适冬(阴历十一月)之望日(十五日)前后,窗外疏梅筛月影。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "最后,终。", "cites": [{"t": "诰诰作事,毋从我冬始。", "b": "《马王堆汉墓帛书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('296wx','鸟','1','niǎo diǎo','鸟','5','','[{"pinyin": "niǎo", "defs": [{"meaning": "(象形。甲骨文字形,小篆作字形,都象鸟形。本义:飞禽总名) 同本义。", "cites": [{"t": "鸟,长尾禽总名也。象形。", "b": "《说文》"}, {"t": "飞鸟遗之音。", "b": "《易·小过》"}, {"t": "我则鸣鸟不闻。", "b": "《书·君奭》"}, {"t": "有鸟高飞。", "b": "《诗·小雅·菀柳》"}, {"t": "鸟乃去矣。", "b": "《诗·大雅·生民》"}, {"t": "兽奔鸟窜。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "鸟篆", "t": "鸟形的篆书"}, {"w": "鸟卜", "t": "用鸟预卜年岁的吉凶"}, {"w": "鸟恨", "t": "鸟声含恨"}, {"w": "鸟乌", "t": "指乌鸦"}, {"w": "鸟迹", "t": "鸟的足迹"}, {"w": "鸟耘", "t": "群鸟耘田"}, {"w": "鸟径", "t": "仅容飞鸟通行的小径"}, {"w": "鸟歌", "t": "鸟声如歌声,故称鸟鸣为鸟歌"}, {"w": "鸟举", "t": "鸟飞。比喻行动快速"}, {"w": "鸟窜", "t": "形容奔窜快速如鸟飞。"}]}]}, {"pinyin": "diǎo", "defs": [{"meaning": "人、畜的雄性生殖器 -- 一般指骂人的粗话。", "words": [{"w": "鸟乱", "t": "亦作“鸟闹”。骂人话。胡闹,捣乱"}, {"w": "鸟事", "t": "坏事情。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('297wx','务','1','wù','力','5','','[{"pinyin": "wù", "defs": [{"meaning": "(形声。从力,務(wù)声。从力,表示要致力于某事。本义:致力,从事)。"}, {"meaning": "同本义。", "cites": [{"t": "非务相反也。", "b": "《吕氏春秋·察今》"}, {"t": "欲富国者,务广其地。", "b": "《战国策·秦策一》"}, {"t": "务耕织。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "务能", "t": "竭力"}, {"w": "务精", "t": "极力求精;精益求精"}, {"w": "务穑", "t": "务农"}, {"w": "务法", "t": "致力于法治"}, {"w": "务本", "t": "专心致力于根本"}, {"w": "务外", "t": "谓研究学问,只致力于表面,不求深入"}, {"w": "务纯", "t": "致力于深钻细研,以达炉火纯青"}, {"w": "务本", "t": "致力于根本"}, {"w": "务于东", "t": "在东方致力作战。"}]}, {"meaning": "谋求。", "cites": [{"t": "不务文字奇。", "b": "白居易《寄唐生》"}]}, {"meaning": "追求。", "cites": [{"t": "务采色。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "贪多务得", "t": ""}]}, {"meaning": "事业;事务。", "cites": [{"t": "必因此为务。", "b": "《史记·货殖列传》"}, {"t": "粟者,王者大用,政之本务。", "b": "汉·晁错《论贵粟疏》"}, {"t": "方今之务。", "b": ""}, {"t": "军中多务。", "b": "《资治通鉴·汉纪》"}, {"t": "卿言多务", "b": ""}], "words": [{"w": "公务;私务;家务;税务;国务;校务", "t": ""}]}, {"meaning": "职业。", "cites": [{"t": "以剥削贫民为务。", "b": "谭嗣同《仁学》"}]}, {"meaning": "古代官署名。多为掌管贸易和税收的机构。", "cites": [{"t": "有言汝州地可为稻田者,因用其言,置务掌之,号稻田务。", "b": "《宋史·食货志上二》"}]}, {"meaning": "宋、元时的酒店。", "cites": [{"t": "村务里嗑酒去。", "b": "汤显祖《牡丹亭》"}]}, {"meaning": "一定;务必。", "cites": [{"t": "君子之事君也。务引其君以当道。", "b": "《孟子·告天下》"}, {"t": "来日吾出战,务要生擒黄忠。", "b": "《三国演义》"}, {"t": "陈言之务去。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "而务去之。", "b": ""}], "words": [{"w": "务能", "t": "尽量;尽其所能"}, {"w": "务请出席;务使大家明白这一点", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('298wx','包','1','bāo','勹','5','','[{"pinyin": "bāo", "defs": [{"meaning": "(会意。小篆字形,外边是“勹”。中间是个“巳”(sì)字,“象子未成形”。“勹”就是“包”的本字。本义:裹)。"}, {"meaning": "用纸、布等裹东西。", "cites": [{"t": "野有死麕,白茅包之。", "b": "《诗·召南·野有死麕》"}, {"t": "草木渐包。", "b": "《书·禹贡》"}, {"t": "包有鱼。", "b": "《易·姤》"}, {"t": "包之以虎皮。", "b": "《礼记·乐记》"}], "words": [{"w": "纸包不住火;包缠", "t": "包裹缠绕。"}]}, {"meaning": "包含,包容。里面含有。", "cites": [{"t": "举一滴可包陵谷。", "b": "唐·李朝威《柳毅传》"}, {"t": "皆包在诸谷中。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "把小费包在内;包函", "t": "包有,含有"}, {"w": "包吞", "t": "包含"}, {"w": "包荒", "t": "掩饰;遮盖;原谅,宽容。"}]}, {"meaning": "包围。四面围住。", "cites": [{"t": "河水分流,包山而过。", "b": "《水经注·河水》"}], "words": [{"w": "包络", "t": "包围环绕。"}]}, {"meaning": "保证,担保。", "cites": [{"t": "包你没事。", "b": "萧德祥《杀狗劝夫》"}], "words": [{"w": "包换;包退;包赔;包管", "t": "保证;保险;保单"}, {"w": "包票", "t": ""}]}, {"meaning": "约定专用。", "cites": [{"t": "烂倾新酿酒,包载下江船。", "b": "梅尧臣《村豪诗》"}], "words": [{"w": "全包", "t": "全部占有"}, {"w": "包饭;包厢;包程;包机", "t": ""}]}, {"meaning": "包装好的一堆单件。", "cites": [{"t": "五官掾献橘数包。", "b": "《后汉书·杨由传》"}], "words": [{"w": "一包香烟", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('299wx','饥','1','jī','饣','5','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从食,幾(jī)声。本义:荒年,五谷无收)。"}, {"meaning": "同本义。", "cites": [{"t": "饑,谷不熟为饑。", "b": "《说文》"}, {"t": "五谷不熟谓之饥。", "b": "《墨子·七患》"}, {"t": "降丧饥馑。", "b": "《诗·小雅·雨无止》"}, {"t": "齐尝大饥,道旁饿死者不可数也。", "b": "《韩非子·外储说右上》"}, {"t": "凶年饥发,君之民老弱转乎沟壑。", "b": "《孟子·梁惠王下》"}, {"t": "四时不出,天下大饥。", "b": "《淮南子·天文》"}, {"t": "今山东饥馑,人庶相食。", "b": "《汉书·翼奉传》"}], "words": [{"w": "饥荒;饥馁", "t": "饥饿"}, {"w": "饥时得一口", "t": "紧要处得人救济,恩德深厚"}, {"w": "饥氓", "t": "逃荒的人"}, {"w": "饥岁", "t": "荒年。"}]}, {"meaning": "(“飢”与“饑”的区别在于,“飢”指肚子饿,“饑”指饥荒。在先秦不相混同,到后来才逐渐通用。“飢”、“饑”现在均简化为“饥”)。"}, {"meaning": "吃不饱。", "cites": [{"t": "飢,饿也。从食,几声。", "b": "《说文》"}, {"t": "可以乐饥。", "b": "《诗·陈风·衡门》。笺:“饥者,不足于食也.”"}, {"t": "家有常业,虽饥不饿。", "b": "《韩非子·饰邪》"}, {"t": "或受之饥。", "b": "汉·贾谊《论积贮疏》"}, {"t": "操军兼以饥疫。", "b": "《资治通鉴》"}], "words": [{"w": "饥火", "t": "饥饿难忍,如火烧于腹中"}, {"w": "饥殍", "t": "饿死的人。同饿莩"}, {"w": "饥驱", "t": "为饥饿所迫,出外奔波谋生"}, {"w": "饥火中烧", "t": "饥饿难忍。如火烧于腹中。"}]}, {"meaning": "荒年,五谷无收。", "cites": [{"t": "饥岁之春。", "b": "《韩非子·五蠹》"}, {"t": "比年不登,人用饥匮。", "b": "《后汉书·张奋传》"}]}, {"meaning": "古国名。", "cites": [{"t": "西伯伐饥国,灭之。", "b": "《史记·殷本纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('300wx','主','1','zhǔ zhù','丶','5','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(象形。甲骨文字形,象点燃的火把。下面是木材。“主”是“炷”的本字。小篆字形从上往下依次为:火焰、油盏、灯台、灯座。本义:灯心)。"}, {"meaning": "同本义 。油灯上用来点火的灯草、纱、线等", "cites": [{"t": "主,镫中火主也。", "b": "《说文》"}]}, {"meaning": "君主 。古代国家的最高统治者。", "cites": [{"t": "惟天生民有欲,无主乃乱。", "b": "《书·仲虺之诰》"}, {"t": "今世之主。", "b": "《吕氏春秋·察今》"}, {"t": "下国卧龙空寤主,中原得鹿不由人。", "b": "唐·温庭筠《经五丈原》"}, {"t": "畔主背亲。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "欲斗两主。", "b": ""}, {"t": "共事之主。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "主驾", "t": "君主的车驾"}, {"w": "主道", "t": "君主治国之道"}, {"w": "主术", "t": "君主控制臣下的权术"}, {"w": "主胙", "t": "帝业"}, {"w": "主相", "t": "君主和相"}, {"w": "主长", "t": "君上"}, {"w": "主君", "t": "对一国之主的称呼"}, {"w": "主位", "t": "君主的权位。"}]}, {"meaning": "指立国一方的国君。旧史家以正统为帝,偏安为主 。如朱熹《资治通鉴纲目》以蜀为正统,故称“蜀”为“帝”,魏、吴为主。", "cites": [{"t": "凡人主必审分。", "b": "《吕氏春秋·审分》"}], "words": [{"w": "主君", "t": "诸侯互相聘问的主国之君。"}]}, {"meaning": "公主的简称。", "cites": [{"t": "主(平阳公主)见所侍美人,上弗悦。", "b": "《史记》"}, {"t": "主家山第接云开,天子春游动地来。", "b": "唐·李峤《奉和初春幸太平公主南庄应制》"}], "words": [{"w": "主第", "t": "公主的住宅"}, {"w": "主国", "t": "公主的侯国"}, {"w": "主傅", "t": "教导公主的女官。"}]}, {"meaning": "主人;东道主。", "cites": [{"t": "遂举觞对语,宾主无愧色。", "b": "《世说新语·方正》"}, {"t": "主不能守。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "宾主;客随主便;主队;主婆", "t": "主人婆"}, {"w": "主翁", "t": "犹主人"}, {"w": "主客", "t": "主人与宾客"}, {"w": "主党", "t": "主人一方的亲族"}, {"w": "主父", "t": "婢妾、仆役对男主人之称"}, {"w": "主人家", "t": "主人;特指店主人"}, {"w": "主人婆", "t": "主人之妻。"}]}, {"meaning": "控制者,支配者,财产或权力的所有者。", "cites": [{"t": "场主积薪。", "b": "《聊斋志异·促织》"}, {"t": "山塞中只有这个主。先除了此人,小喽另外何足为虑。", "b": "《水浒传》"}], "words": [{"w": "企业主;房主;车主", "t": ""}]}, {"meaning": "长官;首脑,首长。", "cites": [{"t": "何时见府主,长跪向之啼。", "b": "唐·元结《贫妇词》"}, {"t": "若乘边守险,足为一方之主。", "b": "《世说新语·识鉴》"}]}, {"meaning": "家长;父母或其他监护人。", "cites": [{"t": "内有主也。", "b": "《太玄》"}], "words": [{"w": "主伯", "t": "古代指家长和长子"}, {"w": "一家之主", "t": ""}]}, {"meaning": "事主,指当事人。", "cites": [{"t": "凡被举擢官,于诰命署举主姓名,他日不如举状,则连坐之。", "b": "《宋史·选举志》"}, {"t": "武大扯住郓哥道:“还我主来!”", "b": "《水浒传》"}], "words": [{"w": "买主;卖主;失主;盟主", "t": ""}]}, {"meaning": "事物的根本。", "cites": [{"t": "天下为主。", "b": "清·黄宗羲《原君》"}]}, {"meaning": "又。", "cites": [{"t": "以君为主。", "b": ""}, {"t": "以刚为主。", "b": "《明史》"}, {"t": "不主故常。", "b": "[英]赫胥黎著、严复译《天演论》"}]}, {"meaning": "死人的牌位。", "cites": [{"t": "上司批准下来,制主入祠,门首建坛。", "b": "《儒林外史》"}]}, {"meaning": "上帝。", "cites": [{"t": "有人从墓里把主移走了,我们不知道他们把他放在那里!", "b": "《圣经》"}]}, {"meaning": "真主 。伊斯兰教教徒对其所信仰的主神的称呼。"}, {"meaning": "主持;掌管。", "cites": [{"t": "聘则为妻奔是妾,不堪主祀奉苹蘩。", "b": "白居易《井底引银瓶》"}, {"t": "有劫贼杀财主,主者捕之。", "b": "《世说新语·政事》"}, {"t": "轩辕之时,史有仓颉,主文之职。", "b": "《文心雕龙·史传》"}, {"t": "主缚者亦然,不如何欲,缚时既先折筋骨。", "b": "方苞《狱中杂记》"}], "words": [{"w": "主苹蘩", "t": "指妻子主持家政"}, {"w": "主闱", "t": "科举考试的主试官"}, {"w": "主簿", "t": "主管文书"}, {"w": "主藏", "t": "主管库藏财物"}, {"w": "主业", "t": "主管产业"}, {"w": "主章", "t": "古代掌管木材的官吏"}, {"w": "主书", "t": "主管文书的官吏。"}]}, {"meaning": "支持,提倡,主张。", "cites": [{"t": "前所主唱。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "力主", "t": "极力主张"}, {"w": "主坐", "t": "主使的人"}, {"w": "主莫", "t": "主谋;力求"}, {"w": "主画", "t": "主意;谋划。"}]}, {"meaning": "寄住在。", "cites": [{"t": "或谓孔子于卫主痈疽,于齐主侍人瘠环。", "b": "《孟子》"}], "words": [{"w": "主人家", "t": "旅馆;客店。"}]}, {"meaning": "注重。", "cites": [{"t": "主忠信,无友不如己者。", "b": "《论语》"}]}, {"meaning": "保持。", "cites": [{"t": "主此盛德兮,牵于俗而芜秽。", "b": "《文选·宋玉·招魂》"}]}, {"meaning": "主持婚约。", "cites": [{"t": "主王姬者,必自公门出。", "b": "《谷梁传》"}]}, {"meaning": "预示。", "cites": [{"t": "齐王问大臣:“铜铁鸣,主何吉凶?", "b": "《三国志平话》"}]}, {"meaning": "存心;萌生。", "cites": [{"t": "我力斗二将不过,看看输与他。宋江收了军马,不知主何意。", "b": "《水浒传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhù", "defs": [{"meaning": "件,桩。", "cites": [{"t": "放着这样一主大财不会发,岂不是如入宝山空手回。", "b": "《儒林外史》"}]}, {"meaning": "灌入", "cites": [{"t": "主量必平,似法。", "b": "《荀子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('301wx','市','1','shì','巾','5','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。金文字形,上面是“之”(往),下面是“兮”,表市场嘈杂声。本义:市场)。"}, {"meaning": "同本义。", "cites": [{"t": "市,买卖之所也。", "b": "《说文》。按,古者神农作市,或曰祝融也。"}, {"t": "市者,货之准也。", "b": "《管子·乘马》"}, {"t": "大市日昃而市,百族为主;朝市朝时而市,商贾为主;夕市夕时而市,贩夫贩妇为主。", "b": "《周礼·司市》"}, {"t": "因井田以为市,故俗语曰市井。", "b": "《公羊传·宣公十五年》注"}, {"t": "肆之市朝。", "b": "《论语》"}, {"t": "商贾皆欲藏于王之市。", "b": "《孟子·梁惠王上》"}, {"t": "市南门外泥歇。", "b": "唐·白居易《卖炭翁》"}, {"t": "置于市,贾十倍。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "市征", "t": "市场的税征"}, {"w": "市曹", "t": "市中商店聚集的地方。即市场。引申为买卖官爵"}, {"w": "市声", "t": "街市中的喧闹声"}, {"w": "市人", "t": "集市或城中街道上的人"}, {"w": "市吏", "t": "市官。管理市场的官吏"}, {"w": "市刑", "t": "古代市场中的刑罚"}, {"w": "市司", "t": "古代管理市场的官员。"}]}, {"meaning": "集镇;城镇;城市。", "cites": [{"t": "乃与其徒日张“屈”字游金陵中。", "b": "明·高启《书博鸡者事》"}, {"t": "之盱眙市中为人说书,已能倾动其市人。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "市稍头", "t": "城镇接近农村的地方"}, {"w": "市井之夫", "t": "市俗的人"}, {"w": "市俗", "t": "普通人,一般人"}, {"w": "市肆", "t": "市内店铺"}, {"w": "市心", "t": "城镇中心地区"}, {"w": "市语", "t": "行话。常指下层社会中用的隐语"}, {"w": "市门", "t": "商店的门;城门"}, {"w": "市口", "t": "市镇"}, {"w": "市邑", "t": "市镇;城镇"}, {"w": "市列", "t": "市场中的店铺"}, {"w": "市中心;北京市;天津市", "t": ""}]}, {"meaning": "街市。", "cites": [{"t": "徇诸市。(徇:示众。)", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "市肆", "t": "市廛。街市上的店铺。"}]}, {"meaning": "交易;商品买卖。", "cites": [{"t": "郑商人弦高将市于周。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "市易", "t": "交易买卖,宋王安石所创的一种新法"}, {"w": "市官", "t": "管理买卖市集的官吏"}, {"w": "市交", "t": "市肆交易"}, {"w": "市合", "t": "开市"}, {"w": "市步", "t": "码头上的集市"}, {"w": "市利", "t": "贸易之利"}, {"w": "市买", "t": "交易。"}]}, {"meaning": "购买。", "cites": [{"t": "责毕收,以何市而反?", "b": "《战国策·齐策》"}, {"t": "愿为市鞍马,从此替爷征。", "b": "《乐府诗集·木兰诗》"}, {"t": "昨闻海令为母寿,市肉二斤矣。", "b": "《明史·海瑞传》"}, {"t": "先生所为文市义者,乃今日见之。", "b": "《战国策·齐策》"}], "words": [{"w": "市骏", "t": "购买骏马"}, {"w": "市沽", "t": "买酒"}, {"w": "市药", "t": ""}]}, {"meaning": "卖。", "cites": [{"t": "昨日入城市,归来泪满巾。", "b": "宋·张俞《蚕妇》"}, {"t": "荣遣其劾帅而己查办,昭雪之以市恩。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "市酒", "t": "卖酒"}, {"w": "市食", "t": "市中售卖的食物;购买食物"}, {"w": "市马", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('302wx','立','1','lì','立','5','','[{"pinyin": "lì", "defs": [{"meaning": "(会意。甲骨文象一人正面立地之形。本义:笔直的站立)。"}, {"meaning": "同本义。", "cites": [{"t": "立,侸也。", "b": "《说文》"}, {"t": "君子以立不易方。", "b": "《易·恒》"}, {"t": "哙遂入,披帷西乡立。", "b": "《史记·项羽本纪》"}, {"t": "持璧却立。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "立有间。", "b": "《韩非子·喻老》"}, {"t": "卖油翁释担而立。", "b": "宋·欧阳修《归田来》"}, {"t": "或立或卧。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "挺立", "t": "直立"}, {"w": "坐立不安;把电线杆立起来;肃立", "t": "恭敬庄严地站着"}, {"w": "立托", "t": "依托"}, {"w": "立容", "t": "站立时的仪态容表"}, {"w": "立戟", "t": "卫士持戟侍立守卫"}, {"w": "立谈", "t": "停立交谈。"}]}, {"meaning": "耸立;树立;建立;竖起。", "cites": [{"t": "大石侧立千尺。", "b": "苏轼《石钟山记》"}, {"t": "乃立宗庙于薛。", "b": "《战国策》"}, {"t": "且立石于基墓门。", "b": "张溥《五人墓碑记》"}, {"t": "且人患志之不立,何忧令名之不彰雅。", "b": "《世说新》"}], "words": [{"w": "立事", "t": "建功立业"}, {"w": "立方", "t": "立德"}, {"w": "立言", "t": "指著书立说"}, {"w": "立业", "t": "建树功烽"}, {"w": "立勋", "t": "建立功勋"}, {"w": "立石", "t": "树立碑石"}, {"w": "立权", "t": "树立权威"}, {"w": "立眉嗔目", "t": "竖眉瞪眼"}, {"w": "立德", "t": "树立德业"}, {"w": "立德立言", "t": "儒家认为,为了匡时济世,应树立圣人之德,宣谕圣人之言"}, {"w": "立碑垂成", "t": "刻文于石碑留作规戒。"}]}, {"meaning": "设置;设立。", "cites": [{"t": "故立君。", "b": "《吕氏春秋·荡兵》"}, {"t": "商君佐之,内立法度。", "b": "贾谊《过秦论》"}], "words": [{"w": "立元", "t": "建立年号"}, {"w": "立仗", "t": "设立仪仗"}, {"w": "立本", "t": "建立根本;确立根基"}, {"w": "立表下漏", "t": "设置日晷、漏刻以计时"}, {"w": "立事", "t": "设置治事小臣"}, {"w": "立制", "t": "建立制度。"}]}, {"meaning": "确定;决定。", "cites": [{"t": "人之立志。", "b": "清·澎端叔《为学一首示子侄》"}, {"t": "人患志之不立。", "b": "《世说新语·自新》"}, {"t": "复立楚国之社稷。", "b": "《史记·陈涉世家》"}, {"t": "足以立事。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "立限", "t": "确定期限"}, {"w": "立计", "t": "决意;打算"}, {"w": "立报", "t": "立志报效"}, {"w": "立愿", "t": "立定意向"}, {"w": "立语,立说", "t": "立论。"}]}, {"meaning": "存在;生存。", "cites": [{"t": "孤与老贼势不两立。", "b": "《资治通鉴》"}], "words": [{"w": "立命", "t": "修身养性以立天命"}, {"w": "立品", "t": "培养品德"}, {"w": "立行", "t": "建德修行"}, {"w": "立计", "t": "立业;谋生"}, {"w": "立身", "t": "处世为人。"}]}, {"meaning": "立身;立足。", "cites": [{"t": "故久立公子车骑市中。", "b": "《史记·魏公子列传》"}], "words": [{"w": "立崖岸", "t": "做出高傲不凡、难以亲切的样子"}, {"w": "立士", "t": "能自立的士人"}, {"w": "立身", "t": "立足;安身"}, {"w": "立行", "t": "行为举动"}, {"w": "立脚", "t": "安身;立身。"}]}, {"meaning": "登位,即位。", "cites": [{"t": "湣王立。", "b": "《韩非子·内储说上》"}, {"t": "当立者乃公子。", "b": "《史记·陈涉世家》"}]}, {"meaning": "又。", "cites": [{"t": "陈胜自立为将军。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "陈涉乃立为王。", "b": ""}], "words": [{"w": "立子", "t": "古代帝王或诸侯选立太子或世子"}, {"w": "立君", "t": "确立君王"}, {"w": "立政", "t": "确立为政之道"}, {"w": "立朝", "t": "指帝王在位"}, {"w": "立极", "t": "登帝位;秉国政。"}]}, {"meaning": "扶立;确定某种地位。", "cites": [{"t": "三十日不还,则请立太子为王。", "b": "《史记》"}], "words": [{"w": "立人", "t": "扶持、造就人"}, {"w": "立子", "t": "立庶子为太子或世子"}, {"w": "立王", "t": "所立的君王;在位的君王"}, {"w": "立后", "t": "册立皇后"}, {"w": "立朝", "t": "指在朝为官"}, {"w": "立储", "t": "立为太子。"}]}, {"meaning": "临,到。", "cites": [{"t": "乃为坛场大水之上,而与王立之焉。", "b": "《韩非子·内储说上》"}, {"t": "立事者贱者劳而贵者逸。", "b": "《淮南子·泰族》"}]}, {"meaning": "进食。", "cites": [{"t": "五种天不宜,其立后而手实。", "b": "《管子·地员》"}]}, {"meaning": "爵次、位次。", "cites": [{"t": "代立不忘社稷。", "b": "《商君书·更法》"}]}, {"meaning": "立时;立刻。", "cites": [{"t": "上大怒,立命斥出。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "指物作作诗立就。", "b": "宋·王安石《伤仲永》"}, {"t": "赵立奉璧来。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "立定", "t": "马上,立即"}, {"w": "立马造桥", "t": "立即兑现,不容拖延"}, {"w": "立成", "t": "立刻完成"}, {"w": "立便", "t": "立刻;立时。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('303wx','冯','1','féng píng','冫','5','','[{"pinyin": "féng", "defs": [{"meaning": "古地名。", "cites": [{"t": "郑于是乎伐冯、滑、胥靡,负黍、狐人、阙外。", "b": "《左传·定公六年》"}]}, {"meaning": "姓。"}]}, {"pinyin": "píng", "defs": [{"meaning": "(形声。从马,冫声。冫,古冰字的楷书写法。本义:马跑得快)。"}, {"meaning": "同本义。", "cites": [{"t": "冯,马行疾也。", "b": "《说文》"}], "words": [{"w": "冯冯", "t": "马行疾速的样子。"}]}, {"meaning": "大,盛。", "cites": [{"t": "今君奋焉震电冯怒。", "b": "《左传·昭公五年》"}, {"t": "冯弱犯寡。", "b": "《周礼·大司马》"}, {"t": "帝冯怒。", "b": "《列子·汤问》"}], "words": [{"w": "冯戎", "t": "富盛"}, {"w": "冯怒", "t": "盛怒,震怒"}, {"w": "冯隆", "t": "高大的样子。"}]}, {"meaning": "徒步过水。", "cites": [{"t": "不敢暴虎,不敢冯河。", "b": "《诗·小雅·小旻》"}], "words": [{"w": "冯河", "t": "徒步渡过河水。"}]}, {"meaning": "扶持,服膺。", "cites": [{"t": "有冯有翼。", "b": "《诗·大雅·卷阿》"}], "words": [{"w": "冯翼", "t": "辅佐;另有虚无的样子之意。"}]}, {"meaning": "依仗,倚托。", "cites": [{"t": "不冯其子,灵公夺而里之。", "b": "《庄子·则阳》"}, {"t": "神所冯依,将在德矣。", "b": "《左传·僖公十五年》"}, {"t": "伯陵之后,逢公之所冯神也。", "b": "《国语·周语下》"}, {"t": "冯太一。", "b": "《淮南子·精神》"}, {"t": "冯恃其众。", "b": "《左传·哀公七年》"}], "words": [{"w": "冯尸", "t": "葬礼仪式中的一种,死者入殓时,生者对死者有冯尸、托尸、拘尸、执尸等仪式,依其与死者之血缘、尊卑关系而定丧礼之等差"}, {"w": "冯资", "t": "依赖,凭依"}, {"w": "冯神", "t": "依仗神的力量。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('304wx','玄','1','xuán','玄','5','','[{"pinyin": "xuán", "defs": [{"meaning": "(象形。小篆字,下端象单绞的丝,上端是丝绞上的系带,表示作染丝用的丝结。本义:赤黑色,黑中带红)。"}, {"meaning": "同本义。", "cites": [{"t": "黑而有亦色者为玄。", "b": "《说文》"}, {"t": "五入为緅,七入为缁。", "b": "《考工记·钟氏》。注:“凡玄色者,在緅缁之间,其六入者与。”"}, {"t": "夏纁玄。", "b": "《周礼·染人》。注:“玄纁者,天地之色。”"}, {"t": "八月载绩,载玄载黄。", "b": "《诗·豳风·七月》"}, {"t": "天玄地黄。", "b": "《易·坤》"}, {"t": "篚厥玄黄。", "b": "《孟子》"}, {"t": "我马玄黄。", "b": "《诗·召南·卷耳》"}]}, {"meaning": "又泛指黑色。", "cites": [{"t": "玄,黑也。", "b": "《小尔雅》"}, {"t": "[徐州]厥篚玄纤缟。", "b": "《书·禹贡》。孔传:“玄,黑缯。”"}, {"t": "何草不玄,何人不矜。", "b": "《诗·小雅·何草不黄》"}, {"t": "奏之,有玄云从西北方起。", "b": "《韩非子·十过》"}], "words": [{"w": "玄禽", "t": "燕子"}, {"w": "玄霜", "t": "传说中的仙药"}, {"w": "玄岫场谷", "t": "青山翠谷"}, {"w": "玄霄", "t": "黑云"}, {"w": "玄厉", "t": "黑色磨刀石"}, {"w": "玄祺", "t": "浅黑色旗。"}]}, {"meaning": "引申为黑暗。", "cites": [{"t": "遗思在玄夜,相与复翱翔。", "b": "汉·刘桢《公宴》"}], "words": [{"w": "玄夜", "t": "黑夜"}, {"w": "玄窗", "t": "阴暗的深坑"}, {"w": "玄室", "t": "暗室。"}]}, {"meaning": "深;厚。", "cites": [{"t": "临沅湘之玄渊兮,遂自忍而沈流。", "b": "《楚辞》"}], "words": [{"w": "玄冰", "t": "厚冰"}, {"w": "玄包", "t": "深藏"}, {"w": "玄渊", "t": "深渊。"}]}, {"meaning": "神妙难捉摸;深奥。", "cites": [{"t": "难!难!难!道最玄。", "b": "《西游记》"}, {"t": "玄之又玄,众妙之门。", "b": "《老子》第一章"}, {"t": "异物名实玄纽。", "b": "《荀子·正名》"}, {"t": "学遍书部,特善玄言。", "b": "沈约《齐故安陆昭王碑文》"}], "words": [{"w": "玄机", "t": "神秘的先兆"}, {"w": "玄关", "t": "佛教称入道的法门"}, {"w": "玄术", "t": "神秘的法术"}, {"w": "玄策", "t": "神妙的谋略"}, {"w": "玄语", "t": "不切实际的话"}, {"w": "玄谈", "t": "脱离实际的空谈"}, {"w": "玄寂", "t": "玄虚寂静。"}]}, {"meaning": "假借为“远”或为“原”。", "cites": [{"t": "玄,幽远也。象幽而入覆之也。", "b": "《说文》"}, {"t": "玄古之君天下,无为也,天德而已矣。", "b": "《庄子》。高注:“淮南子曰:天也。圣经不言玄妙,至伪尚书有玄德升间之语。”"}], "words": [{"w": "玄古", "t": "远古"}, {"w": "玄睹", "t": "远见。"}]}, {"meaning": "寂静;清静。", "cites": [{"t": "天道玄默,无容无则。", "b": "《淮南子》"}], "words": [{"w": "玄谟", "t": "清静无为"}, {"w": "玄静", "t": "清静无为的思想境界"}, {"w": "玄嘿", "t": "寂静无为。"}]}, {"meaning": "天,天空。", "cites": [{"t": "玄,天也。", "b": "《释言》"}, {"t": "天以不见为玄。地以不形为玄,人以心腹为玄。", "b": "《太玄·玄告》"}, {"t": "共玄官。", "b": "《管子·幼官》。注:“主礼天之官也。”"}], "words": [{"w": "玄都", "t": "神仙的居处"}, {"w": "玄穹帝", "t": "即天帝"}, {"w": "玄极", "t": "天顶,天空"}, {"w": "玄贶", "t": "上天的赏赐"}, {"w": "玄浑", "t": "天。"}]}, {"meaning": "道家的学说;道教。", "cites": [{"t": "自中朝贵玄,江左称盛,因谈余气,流成文体。", "b": "《文心雕龙》"}], "words": [{"w": "玄门", "t": "道教"}, {"w": "玄功", "t": "道家修道的功夫"}, {"w": "玄玄道", "t": "道家及其深奥、神妙的教义。"}]}, {"meaning": "农历九月的别称。", "cites": [{"t": "至于玄月,王召范蠡而问焉。", "b": "《国语·越语下》"}]}, {"meaning": "玄孙的省称。", "cites": [{"t": "曾孙之子为玄孙。", "b": "《尔雅》"}]}, {"meaning": "北方。", "cites": [{"t": "以处玄宫。", "b": "《庄子》。陆德明释文:“玄宫,李云北方宫也。”"}], "words": [{"w": "玄方", "t": "北方"}, {"w": "玄郊", "t": "北郊"}, {"w": "玄海", "t": "北方之海"}, {"w": "玄朔", "t": "北方"}, {"w": "玄帝", "t": "北方之帝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('305wx','闪','1','shǎn','门','5','','[{"pinyin": "shǎn", "defs": [{"meaning": "(会意。从人在门中。本义:自门内偷看)。"}, {"meaning": "同本义,引申为偷看。", "cites": [{"t": "闪,窥头在门中也。", "b": "《说文》。南朝宋·裴松之注引《魏略·苛吏传》:“白日常自于墙壁间閨闪。”"}, {"t": "故鱼鲔不淰。", "b": "《礼记·礼运》。注:“淰之言闪也。”疏:“闪是忽有忽无,故字从门中人也。经传多以掩为之。”"}]}, {"meaning": "忽有忽无, 突然显现。", "cites": [{"t": "蝄像暂晓而闪屍", "b": "木华《海赋》。注:“暂见之貌。”"}, {"t": "为首闪出一将。", "b": "《三国演义》"}], "words": [{"w": "脑子闪过一个念头;闪尸", "t": "忽隐忽现"}, {"w": "闪飒", "t": "闪烁"}, {"w": "闪缀", "t": "闪闪发光"}, {"w": "闪然", "t": "隐没不见"}, {"w": "闪荡", "t": "光闪动"}, {"w": "闪放", "t": "闪烁放光"}, {"w": "闪明", "t": "天刚明"}, {"w": "闪忽", "t": "变化不定。"}]}, {"meaning": "动摇不定。", "cites": [{"t": "垂涎闪吞兮,挥霍旁午。", "b": "唐·柳宗元《招海贾文》"}]}, {"meaning": "遮拦。", "cites": [{"t": "因此上裴航要闪住你肖郎路。", "b": "明·汤显祖《邯郸记》"}]}, {"meaning": "抛弃。", "cites": [{"t": "教孩儿往帝都,把媳妇闪得苦又孤。", "b": "高明《琵琶记·糟粮自厌》"}], "words": [{"w": "闪了脸", "t": "翻了脸,损伤了感情"}, {"w": "闪落", "t": "撇开不管。"}]}, {"meaning": "抛洒。", "cites": [{"t": "闪英雄泪渍盈盈袖,伤心不为悲秋瘦。", "b": "明·汤显祖《牡丹亭》"}]}, {"meaning": "扭伤筋骨。", "cites": [{"t": "夫人休闪了手。", "b": "王实甫《西厢记》"}], "words": [{"w": "闪了腰;闪肭", "t": "扭伤筋肉。"}]}, {"meaning": "招引。", "cites": [{"t": "梦见一人,手执柳枝,闪了他去。", "b": "明·汤显祖《牡丹亭》"}]}, {"meaning": "天空的电光。俗称闪电为闪。", "cites": [{"t": "千里的雷声万里的闪。", "b": "李季《王贵与李香香》"}], "words": [{"w": "打闪;闪红", "t": "电光。"}]}, {"meaning": "闪族 ,高加索人种的一个分支,多住在中东一带,包括阿拉伯人、犹太人和埃塞俄比亚人。"}, {"meaning": "闪失;挫折。", "cites": [{"t": "不想又吃了这一闪。", "b": "《水浒全传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('306wx','兰','1','lán','丷','5','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从艸,阑(lán)声。本义:兰草,即泽兰)。"}, {"meaning": "同本义。", "cites": [{"t": "蘭,香草也。", "b": "《说文》"}, {"t": "衡兰芷若。", "b": "《汉书·司马相如传》"}, {"t": "兰槐之根是为芷。", "b": "《荀子·劝学》"}]}, {"meaning": "即“春兰”。亦称“兰花”、“山兰”、“草兰”、“朵朵香” 。一种多年生常绿草本植物,根簇生、肉质、圆柱形,叶线形、革质,早春由叶丛间抽生多数花茎,每茎顶开一花,花淡黄绿色、清香,供观赏。"}, {"meaning": "兵器架。", "cites": [{"t": "武库禁兵,设地蘭锜。", "b": "汉·张衡《西京赋》"}], "words": [{"w": "兰盾", "t": "放置兵器的架子。"}]}, {"meaning": "假借为“栏”。栏杆。", "cites": [{"t": "又置奴婢之市,与牛马同蘭。", "b": "《汉书·王莽传中》"}]}, {"meaning": "假借为“籣”。盛弩矢之袋,形如木桶。", "cites": [{"t": "轻罪入兰盾鞈革二戟。", "b": "《管子·小匡》"}]}, {"meaning": "姓 ?。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('307wx','半','1','bàn','十','5','','[{"pinyin": "bàn", "defs": [{"meaning": "(会意。从八,从牛。“八”是分解的意思;牛大,易于分割,所以取“牛”会意。本义:一半,二分之一)。"}, {"meaning": "同本义。", "cites": [{"t": "半,物中分也。", "b": "《说文》"}, {"t": "今汉有天下太半。", "b": "《汉书·高帝纪上》"}, {"t": "士卒食半。", "b": "《汉书·项籍传》"}, {"t": "先帝创业未半而中道崩殂。", "b": "诸葛亮《出师表》"}, {"t": "半匹红绡一丈绫。", "b": "唐·白居易《卖炭翁》"}, {"t": "身已半入,只露尻尾。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "太半", "t": "三分之二"}, {"w": "半日;半工;半升", "t": ""}]}, {"meaning": "部分的,不完全的。", "cites": [{"t": "犹抱琵琶半遮面。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "半自动;半老头;半工半读;半半拉拉;半死;半信半疑;一知半解", "t": ""}]}, {"meaning": "比喻极少的。", "cites": [{"t": "而侯生曾无一言半辞送我。", "b": "《史记·魏公子列传》"}], "words": [{"w": "一星半点;半歇", "t": "一会儿"}, {"w": "半星儿", "t": "半点儿"}, {"w": "半丝麻线", "t": "些微私弊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('308wx','汁','1','zhī','氵','5','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从水,十声。本义:含有某种物质的液体)。"}, {"meaning": "同本义。", "cites": [{"t": "汁,液也。", "b": "《说文》"}, {"t": "拾瀋。", "b": "《左传·哀公三年》。释文:“北土呼汁为瀋。”"}, {"t": "函牛之鼎以亨鸡,多汁则淡而不可食,少汁则熬而不可熟。", "b": "《后汉书·边让传》"}], "words": [{"w": "汁子", "t": "汁液;汤汁"}, {"w": "汁滓", "t": "汁液与渣滓"}, {"w": "汁献", "t": "求神用香酒"}, {"w": "墨汁;豆汁;胆汁;茄汁;酸橙汁", "t": ""}]}, {"meaning": "雨夹雪。", "cites": [{"t": "[仲冬之月]行秋令,则天时雨汁,瓜瓠不成。", "b": "《礼记·月令》。注:“雨汁者,水雪杂下也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('309wx','汇','1','huì','氵','5','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从匚(fāng),筐子,淮声。本义:盛器)。"}, {"meaning": "同本义。", "cites": [{"t": "汇,器也。", "b": "《说文》。段玉裁注:“谓有器名汇也。”"}]}, {"meaning": "大量吸收某种物质的器件或系统。", "cites": [{"t": "能汇", "b": ""}, {"t": "中子汇", "b": ""}]}, {"meaning": "迂回,围绕。", "cites": [{"t": "东汇泽为彭蠡。", "b": "《书·禹贡》。传:“回也。”"}], "words": [{"w": "汇行", "t": "绕道行走。"}]}, {"meaning": "(形声。从韋(yì),长毛兽,胃省声。本义:刺猬)。"}, {"meaning": "同本义。", "cites": [{"t": "彙,彙虫也。似豪猪而小。", "b": "《说文》"}, {"t": "彙,毛刺。", "b": "《尔雅》。注:“今彙,状似鼠。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('310wx','头','1','tóu tou','大','5','','[{"pinyin": "tóu", "defs": [{"meaning": "(形声。从页(xié),豆声。页,人头。头在战国时期才出现,首出现较早。本义:首)。"}, {"meaning": "同本义  本指人的头部,后也泛指各种动物的头部。", "cites": [{"t": "頭,首也。", "b": "《说文》"}, {"t": "苞头者,神所居。", "b": "《春秋·元命》"}, {"t": "头容直。", "b": "《礼记·玉藻》"}, {"t": "左头奉之。", "b": "《仪礼·士相见礼》"}, {"t": "杀人者刎头。", "b": "《公羊传》注"}, {"t": "王购子头千金。", "b": "晋·干宝《搜神记》"}, {"t": "将子头与剑来。", "b": ""}, {"t": "系向牛头充炭直。", "b": "唐·白居易《卖炭翁》"}, {"t": "举头望明月。", "b": "唐·李白《静夜思》"}, {"t": "低头思故乡。", "b": ""}], "words": [{"w": "头直上", "t": "头顶上"}, {"w": "光头", "t": "剃光的头;头上没有戴帽子"}, {"w": "头大", "t": "形容遇到困难头昏脑胀的样子"}, {"w": "头抵", "t": "敌对,对头。也作“头敌”、“敌头”"}, {"w": "头足异处", "t": "头脚分离。指人被杀。也作“头足异所”"}, {"w": "头昏脑闷", "t": "头脑昏晕。形容思虑不清。"}]}, {"meaning": "物的两端或末梢。", "cites": [{"t": "暮至黑山头。", "b": "明·张溥《五人墓碑记》"}, {"t": "既登峰头。", "b": "《徐霞客游记·游黄山记》"}, {"t": "船头坐三人。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "水头;梢头;桥头;露头;炕头儿;街头;弹头;杆头;床头", "t": ""}]}, {"meaning": "特指敌对的人。", "cites": [{"t": "冤有头,债有主。", "b": "《五灯会元》"}]}, {"meaning": "头部有发部分。", "cites": [{"t": "头,首自发以上为头。", "b": "《六书故》"}]}, {"meaning": "赌博或买卖中抽的回扣。", "cites": [{"t": "凡有卖字画、古董物件的,俱要抽头。", "b": "《豆棚闲话》"}]}, {"meaning": "磕头 。旧时的一种跪拜礼。", "cites": [{"t": "父亲母亲吩咐我,叫给舅母行礼,请舅母到厢房里坐下受头。", "b": "《儿女英雄传》"}]}, {"meaning": "件,桩。", "cites": [{"t": "这头亲事,不是情愿与的。", "b": "《水浒传》"}]}, {"meaning": "如多用以计算牲畜。", "cites": [{"t": "潭中鱼可百许头。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "以一头进。", "b": "《聊斋志异·促织》"}, {"t": "每责一头。", "b": ""}, {"t": "捕得两三头。", "b": ""}], "words": [{"w": "一头牛;三头猪", "t": ""}]}, {"meaning": "置于方位词后,表处所可不译。", "cites": [{"t": "路转溪头忽见。", "b": "宋·辛弃疾《西江月》"}, {"t": "惶恐滩头说惶恐。", "b": "宋·文天祥《过零丁洋》"}, {"t": "溪头卧剥莲蓬。", "b": "宋·辛弃疾《清平乐·村居》"}]}]}, {"pinyin": "tou", "defs": [{"meaning": "名词后缀。"}, {"meaning": "方位词后缀。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('311wx','汉','1','hàn','氵','5','','[{"pinyin": "hàn", "defs": [{"meaning": "(会意。从水難(省去隹)声。音熯。本义:水名。即汉水)。"}, {"meaning": "同本义,又叫汉江,长江的最大支流。", "cites": [{"t": "汉,汉水也。上流曰漾。", "b": "《说文》"}, {"t": "徐偃王处汉东。", "b": "《韩非子·五蠹》"}, {"t": "达于汉阴。", "b": "《列子·汤问》"}, {"t": "汉之阴。", "b": ""}, {"t": "收众汉南。", "b": "《资治通鉴》"}], "words": [{"w": "汉女", "t": "传说中的汉水女神"}, {"w": "汉津", "t": "汉水"}, {"w": "汉阴", "t": "汉水南岸。水南岸背太阳叫阴,水北岸面太阳叫阳"}, {"w": "汉渚", "t": "汉水水边;汉水。"}]}, {"meaning": "银河。也称云汉、银汉、天汉。", "cites": [{"t": "星汉灿烂。", "b": "曹操《步出门夏门行》"}], "words": [{"w": "汉沂", "t": "银河边"}, {"w": "汉清", "t": "即清汉,天河。"}]}, {"meaning": "朝代名,公元前202年刘邦称帝,国号汉,共历24帝,统治406年。", "cites": [{"t": "匈奴留汉使。", "b": "《汉书·李广苏建传》"}, {"t": "不知有汉。", "b": "晋·陶渊明《桃花源记》"}, {"t": "其实汉贼。", "b": "《资治通鉴》"}, {"t": "废汉自立。", "b": ""}], "words": [{"w": "汉宇", "t": "汉室。指汉朝。也称汉家"}, {"w": "汉军", "t": "汉朝的军队;元、清时称以汉人编成的军队"}, {"w": "汉风", "t": "汉代的威风或诗风"}, {"w": "汉唐", "t": "汉代和唐代。因两代的文治武功都很盛,故常常并称。"}]}, {"meaning": "国名。"}, {"meaning": "(公元 221—263)三国之一。史称季汉,又称蜀汉。刘备所建。"}, {"meaning": "(公元 304—329)东晋十六国之一。西晋时刘渊称汉,后改为赵,史称前赵。"}, {"meaning": "(公元311—347)东晋十六国之一。西晋时李雄称帝,国号成,至李寿时,改号为汉,史称成汉,也称后蜀。"}, {"meaning": "(公元917—971)五代十国之一。刘隐称帝,国号汉,史称南汉。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('312wx','宁','1','níng nìng zhù','宀','5','','[{"pinyin": "níng", "defs": [{"meaning": "(本作“寍”。从宀(mián),从心,从皿。表示住在屋里有饭吃就安心了。后世假“寧”为“寍”,“寧”行而“寍”废。今用“宁”字作“寧”简化字。“宁”本读zhù,是“贮”的本字。本义:安宁,平安)。"}, {"meaning": "同本义。", "cites": [{"t": "寍,安也。", "b": "《说文》。经传皆以寧为之。"}, {"t": "三日康寧。", "b": "《书·洪范》"}, {"t": "惟若寧侯。", "b": "《考工记·梓人》"}, {"t": "归寧乃邦。", "b": "《仪礼·觐礼》"}, {"t": "身欲寧。", "b": "《礼记·月令》"}, {"t": "鸡狗不得宁。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "宁汝于斯。", "b": "清·袁枚《祭妹文》"}, {"t": "幸宁心哉。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "心神不宁;宁吉", "t": "安宁吉祥"}, {"w": "宁息", "t": "安宁平静"}, {"w": "宁和", "t": "安宁和平"}, {"w": "宁泰", "t": "安宁太平"}, {"w": "宁康", "t": "安宁康乐。"}]}, {"meaning": "平静;宁静。", "cites": [{"t": "正是猴性顽劣,再无一个宁时。", "b": "《西游记》"}, {"t": "朕心绪不宁,教汝等且退,何故又来!", "b": "《三国演义》"}], "words": [{"w": "宁贴", "t": "妥贴,妥当"}, {"w": "宁晏", "t": "平静;安定"}, {"w": "宁俗", "t": "使民风宁静和睦"}, {"w": "宁极", "t": "宁静至极之性"}, {"w": "宁息", "t": "安宁;平静。"}]}, {"meaning": "已嫁女子回娘家探望父母;也泛指省亲。", "cites": [{"t": "归宁父母。", "b": "《诗·周南·葛覃》"}], "words": [{"w": "宁省", "t": "探望年长的亲属"}, {"w": "宁亲", "t": "省亲"}, {"w": "宁觐", "t": "返里省亲。"}]}, {"meaning": "守父母之丧。", "cites": [{"t": "前博士弟子父母死,予宁三年。", "b": "《汉书·哀帝纪》"}], "words": [{"w": "宁丧还家;宁告", "t": "古代官吏告假奔丧"}, {"w": "宁考", "t": "亡父。"}]}, {"meaning": "返回,回。", "cites": [{"t": "干连的人,尽数保放呆家。", "b": "《水浒传》"}], "words": [{"w": "宁家", "t": "回家。"}]}, {"meaning": "", "cites": [{"t": "有宁越、徐尚、苏秦、杜赫之属为之谋。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "姓。"}]}, {"pinyin": "nìng", "defs": [{"meaning": "宁可;宁愿。", "cites": [{"t": "宁,愿词也。", "b": "《说文》"}, {"t": "宁适不来。", "b": "《诗·小雅·伐木》"}, {"t": "均之二策,宁许以负秦曲。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "宁赴常流。", "b": "《史记·平原君虞卿列传》"}, {"t": "不逊也宁固。", "b": "宋·司马光《训俭示康》"}, {"t": "宁斩吾头。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "宁请汝先死。", "b": "清·林觉民《与妻书》"}, {"t": "宁使学终不进,不欲虚以下人。", "b": "清·刘开《问说》"}], "words": [{"w": "宁个", "t": "宁愿"}, {"w": "宁为玉碎,不为瓦全", "t": ""}]}, {"meaning": "岂;难道。", "cites": [{"t": "子宁不来。", "b": "《诗·郑风·子衿》"}]}, {"meaning": "又。", "cites": [{"t": "子宁不嗣音。", "b": ""}, {"t": "王侯将相宁有种乎?", "b": "《史记·陈涉世家》"}, {"t": "宁有政教。", "b": "《史记·货殖列传》"}, {"t": "宁不哀哉。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "宁止不避。", "b": "唐·李朝威《柳毅传》"}, {"t": "宁知此为归骨所。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "宁渠", "t": "难道;如何"}, {"w": "事之可怪,宁有逾此", "t": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "zhù", "defs": [{"meaning": "贮藏;积聚。本作“宁”", "cites": [{"t": "宁,办积物也。象形。", "b": "《说文》。按,与貯略同。"}, {"t": "惠风伫芳于阳林,醴泉涌溜于阴渠。", "b": "《文选·孙绰·游天台山赋》。唐·李善注:“‘伫’与‘宁’同。”"}]}, {"meaning": "久立。后作“佇、竚”,简化为“伫”。", "cites": [{"t": "天子当宁而立。", "b": "《礼记·曲礼》"}, {"t": "位宁有官司之典。", "b": "《国语·楚语》"}, {"t": "以人君门外有正朝,视朝则于此宁立故耳。", "b": "江永《乡党图考》"}], "words": [{"w": "宁僚", "t": "同朝任职的官僚。"}]}, {"meaning": "古代宫殿的门与屏之间。", "cites": [{"t": "门屏之间谓之宁。", "b": "《尔雅》。李注:“正门内两塾间。”孙注:“门内屏外君视朝所宁立处也。”"}, {"t": "天子当宁而立,诸公东面,诸侯西面,曰朝。", "b": "《礼记》"}], "words": [{"w": "宁位", "t": "帝王视朝时所居之位。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('313wx','穴','1','xué','穴','5','','[{"pinyin": "xué", "defs": [{"meaning": "(象形。小篆字形,上面是“宀”,表覆盖物;下面两边表示洞孔。本义:土窟窿,地洞)。"}, {"meaning": "同本义。", "cites": [{"t": "穴,土室也。", "b": "《说文》。按,象嵌空之形,非八字。"}, {"t": "出自穴。", "b": "《易·需》。注:“阴之路也。”"}, {"t": "有穴窈然,入之甚寒。", "b": "宋·王安石《游褒禅山记》"}, {"t": "古之民未知为宫室时,就陵阜而居,穴而处。", "b": "《墨子·辞过》"}], "words": [{"w": "洞穴", "t": "地洞或山洞"}, {"w": "穴人", "t": "在洞穴中采钟乳石的人"}, {"w": "穴流", "t": "洞穴中的水流。"}]}, {"meaning": "墓穴;埋棺材的坑。", "cites": [{"t": "临其穴。", "b": "《诗·秦风·黄鸟》"}, {"t": "谷则异室,死则同穴。", "b": "《诗·王风·大车》"}], "words": [{"w": "寿穴", "t": "生前造的墓穴。"}]}, {"meaning": "动物的窝。", "cites": [{"t": "狐狸驰赴穴,飞鸟翔故林。", "b": "汉·王粲《七哀诗》"}], "words": [{"w": "穴巢", "t": "鸟兽藏身的窝巢"}, {"w": "虎穴;蚁穴", "t": ""}]}, {"meaning": "指敌人或奸人盘据、藏匿的地方。", "cites": [{"t": "上官欲察州里之豪,不能不假耳目,而奸人常为之穴。", "b": "清·顾炎武《天下郡国利病书》"}], "words": [{"w": "穴群", "t": "谓聚众盘据"}, {"w": "穴巢", "t": "喻敌人或匪徒盘据、活动的场所。"}]}, {"meaning": "地道。", "cites": [{"t": "审知穴之所在,凿穴迎之。", "b": "《墨子》"}], "words": [{"w": "穴土", "t": "挖地道"}, {"w": "穴师", "t": "挖地道的士兵"}, {"w": "穴地", "t": "挖地道。"}]}, {"meaning": "水道。", "cites": [{"t": "江河既导,万穴俱流。", "b": "《文选》"}]}, {"meaning": "穴居;穴藏。", "cites": [{"t": "夫鼠,昼伏夜动,不穴于寝庙,畏人故也。", "b": "《左传》"}], "words": [{"w": "穴居野处", "t": "形容人类未有房屋前的生活状态"}, {"w": "穴处", "t": "居住山洞"}, {"w": "穴保", "t": "穴居裸体。"}]}, {"meaning": "挖凿;洞穿。", "cites": [{"t": "穴土而入。", "b": "《墨子·备穴》"}], "words": [{"w": "穴矛", "t": "开凿地道的工具"}, {"w": "穴垣", "t": "在墙上挖洞"}, {"w": "穴胃", "t": "穿通胃壁"}, {"w": "穴室枢户", "t": "穿室破户。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('314wx','它','1','tā','宀','5','','[{"pinyin": "tā", "defs": [{"meaning": "(象形。小篆字形。象虫形。本义:虫) 同本义", "cites": [{"t": "它,虫也。从虫而长,象冤曲垂尾形,上古草居患它,故相问“无它乎?”", "b": "《说文》"}]}, {"meaning": "称代人以外的事物 。如:煤炭,很多工业离不开它;香山观,从老远的地方就能看见它——口语中与“他、她”无分别。如:它比(引他类比附)。"}, {"meaning": "表示指称。相当于“别的”、“其他的”。", "cites": [{"t": "无它异。", "b": "《后汉书·列女传》"}, {"t": "贝勒及它将。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "帛布及它物。", "b": ""}, {"t": "与它石迥异。", "b": "《墨子·公输》"}], "words": [{"w": "它罪", "t": "别的罪名"}, {"w": "它肠", "t": "它心,二心"}, {"w": "它人", "t": "别人"}, {"w": "它年", "t": "以后的某年或某一时期"}, {"w": "它名", "t": "另外的名"}, {"w": "它所", "t": "其他地方。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('315wx','讨','1','tǎo','讠','5','','[{"pinyin": "tǎo", "defs": [{"meaning": "(会意。从言,从寸。言,言论。寸,法度。用言论和法度进行处治。本义:声讨)。"}, {"meaning": "同本义。", "cites": [{"t": "讨,治也。", "b": "《说文》"}, {"t": "讨,诛也。", "b": "《玉篇》"}, {"t": "其君无日不讨国人而训之。", "b": "《左传·宣公十二年》"}, {"t": "楚人讨陈叛。", "b": "《左传·襄公五年》"}]}, {"meaning": "讨伐;诛戮。", "cites": [{"t": "郑伯为王左卿士,以王命讨之。", "b": "《左传·隐公九年》"}, {"t": "托臣以讨贼。", "b": "诸葛亮《出师表》"}, {"t": "讨贼督师。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "征讨", "t": "出兵讨伐"}, {"w": "讨掩", "t": "讨伐掩捕。掩捕,乘人不备而捕捉"}, {"w": "讨贰", "t": "征讨叛逆不忠的诸侯"}, {"w": "讨贼", "t": "征讨叛逆或盗贼"}, {"w": "讨乱", "t": "征伐乱事"}, {"w": "讨荡", "t": "征讨扫荡。"}]}, {"meaning": "探究。", "cites": [{"t": "世叔讨论之。", "b": "《论语》"}], "words": [{"w": "讨实", "t": "摸清;落实"}, {"w": "讨究", "t": "探讨研究事物的道理"}, {"w": "讨索", "t": "研讨探索。"}]}, {"meaning": "索取。", "cites": [{"t": "何辱讨焉。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "讨针线", "t": "讨零花钱;靠人过日子;受人节制"}, {"w": "讨彩头", "t": "以祝贺主人吉利的名义索取财物"}, {"w": "讨春", "t": "寻春,探春;旧时称卜卦算命。"}]}, {"meaning": "诛杀。", "cites": [{"t": "讨,诛也。", "b": "《玉篇》"}, {"t": "是儿小秦武阳二岁,而讨杀二豪。", "b": "柳宗元《童区寄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('316wx','写','1','xiě xiè','冖','5','','[{"pinyin": "xiě", "defs": [{"meaning": "(形声。从宀,舃(xì)声。本义:移置;放置)。"}, {"meaning": "同本义。", "cites": [{"t": "写,置物也。", "b": "《说文》。俗字亦作泻。"}, {"t": "以浍写水。", "b": "《周礼·稻人》"}, {"t": "牛弗进,则置虚命彻。", "b": "《左传·昭公四年》。注:“写器令空。”"}, {"t": "御食于君,君赐余,器之溉者不写,其余皆写。", "b": "《礼记·曲礼上》。注:“写者,传已器中,乃食之也。”"}]}, {"meaning": "输送。", "cites": [{"t": "发北山石椁,乃写蜀、荆地材皆至。", "b": "《史记》"}]}, {"meaning": "倾吐,倾诉;抒发。", "cites": [{"t": "驾言出游,以写我忧。", "b": "《诗·邶风·泉水》"}, {"t": "写,除也。", "b": "《广雅》"}, {"t": "我心写也。", "b": "《诗·小雅·裳裳者华》。笺:“则我心所忧,写而去矣。”"}, {"t": "何以含忍,寄之此诗;何以写思,记之斯辞。", "b": "晋·陆云《失题》"}], "words": [{"w": "写心", "t": "抒发内心感情"}, {"w": "写志", "t": "发抒情志"}, {"w": "写情", "t": "抒发感情"}, {"w": "写怀", "t": "抒发情怀"}, {"w": "写念", "t": "抒发思念之情"}, {"w": "写思", "t": "抒发情思"}, {"w": "写神;写忧", "t": "发抒排除忧闷。"}]}, {"meaning": "传抄地书写(汉以前只用“书”,汉以后“书”与“写”并用)。", "cites": [{"t": "为官写书受直,以养老母。", "b": "《后汉书·班超传》"}, {"t": "武帝置写书官。", "b": "《汉书·艺文志》"}, {"t": "可笑此公何太惑,读书写字到三更。", "b": "宋·文同《可笑口号》"}], "words": [{"w": "写卷头", "t": "乡试时,考生在考前领取空白试卷,填写姓名、年龄、籍贯、祖宗三代履历后交回。入场时到二门口再发给"}, {"w": "写字洞", "t": "办公室"}, {"w": "写染", "t": "指书法、绘画、写诗、作文等笔墨之事。"}]}, {"meaning": "抄写。", "cites": [{"t": "《三都赋》成,竞相传写。", "b": "《晋书·左思传》"}, {"t": "困乏写手,一时未得奉寄。", "b": "清·顾炎武《答俞右吉书》"}], "words": [{"w": "写白", "t": "誊清"}, {"w": "写手", "t": "抄手"}, {"w": "写书", "t": "抄写书籍"}, {"w": "写经", "t": "抄经"}, {"w": "写录", "t": "抄录。"}]}, {"meaning": "仿效;描绘。", "cites": [{"t": "雷震之声,可以放钟写也。", "b": "《淮南子·本经》"}, {"t": "坟墓写状以孤出,哭泣含声而相召。", "b": "隋·李播《周天大象赋》"}], "words": [{"w": "写物", "t": "描绘人或物"}, {"w": "写境", "t": "描写环境"}, {"w": "写载", "t": "描画"}, {"w": "写状", "t": "描摹形状"}, {"w": "写貌", "t": "描绘形象"}, {"w": "写妙", "t": "描绘传神"}, {"w": "写放", "t": "描画实物。"}]}, {"meaning": "画。", "cites": [{"t": "一壁厢传旨宣召丹青,写下唐僧师徒四位喜容。", "b": "《西游记》"}, {"t": "绘影写光。", "b": "蔡元培《图画》"}], "words": [{"w": "写像", "t": "画像"}, {"w": "写载", "t": "描画"}, {"w": "写生;写影", "t": "画像;作画"}, {"w": "写真图,写真像", "t": "画像"}, {"w": "写形", "t": "画像,图写形貌。"}]}, {"meaning": "写作,创作。", "cites": [{"t": "文章写法,其道则一。心地光明,便有灵感,入情入理,就成艺术。", "b": "孙犁《秀露集》"}], "words": [{"w": "写定", "t": "写成定本"}, {"w": "写法", "t": "写作方法。"}]}, {"meaning": "租赁,确定某种出租或雇佣关系。", "cites": [{"t": "如今写了两只大官船,兵部里讨的火牌,勘合,一家子都往任上去了。", "b": "《醒世姻缘传》"}, {"t": "写了哥子的船。", "b": "《警世通言》"}]}]}, {"pinyin": "xiè", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('317wx','让','1','ràng','讠','5','','[{"pinyin": "ràng", "defs": [{"meaning": "(形声。从言,襄(xiāng)声。本义:责备)。"}, {"meaning": "同本义。", "cites": [{"t": "让,相责让也。", "b": "《说文》"}, {"t": "诘责以辞谓之让。", "b": "《小尔雅》"}, {"t": "让,责也。", "b": "《广雅》"}, {"t": "且让之。", "b": "《左传·昭公二十五年》"}, {"t": "让不贡。", "b": "《国语·周语》"}, {"t": "鲁人以为让。", "b": "《史记·齐世家》"}, {"t": "众知有为,因让之曰:…", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "让书", "t": "有责备言语的书信"}, {"w": "让勖", "t": "既责备又勉励"}, {"w": "让诮", "t": "责让讥诮。"}]}, {"meaning": "退让;谦让。", "cites": [{"t": "让者,礼之主也。", "b": "《左传·襄公十三年》"}, {"t": "让文之材也。", "b": "《国语·周语》"}, {"t": "让,推贤也。", "b": "《国语·晋语》"}, {"t": "允恭克让。", "b": "《书·尧典》。郑注:“推贤尚善曰让。”"}, {"t": "退让以明礼。", "b": "《礼记·曲礼》"}, {"t": "尧让天下于许由。", "b": "《庄子·逍遥游》"}, {"t": "侯生摄敝衣冠,直上载公子坐,不让,欲欢公子。", "b": "《史记·魏公子列传》"}], "words": [{"w": "让梨觅枣", "t": "比喻兄弟间的手足情爱"}, {"w": "见困难就上,见荣誉就让;各不相让;寸步不让;让棋;让衢", "t": "让路"}, {"w": "让再让三", "t": "三番五次地推让"}, {"w": "让客", "t": "礼让客人"}, {"w": "让德", "t": "谦让的品德。"}]}, {"meaning": "推举。", "cites": [{"t": "哥哥三打祝家庄身亡之后,众兄弟让我为头领。", "b": "李致远《还牢末》楔子"}]}, {"meaning": "以一定代价将东西的所有权转给他人。", "cites": [{"t": "把房子让给远房几家族人来住。", "b": "《儿女英雄传》"}, {"t": "薛家伏势倚情,偏不相让。", "b": "《红楼梦》"}], "words": [{"w": "让与", "t": "把财物或权利移转于别人"}, {"w": "让禄", "t": "把利禄移转给别人"}, {"w": "让国", "t": "把国君的地位让给他人"}, {"w": "让名", "t": "把名誉让给他人"}, {"w": "让价;让利销售", "t": ""}]}, {"meaning": "推辞;推让;拒绝。", "cites": [{"t": "乃惧距天用而让有用也。", "b": "《潜夫论·明闇》"}], "words": [{"w": "让职", "t": "辞让官职"}, {"w": "让爵", "t": "让爵位。"}]}, {"meaning": ""}, {"meaning": "窃夺。", "cites": [{"t": "治斧钺者,不敢让刑;治轩冕者,不敢让赏。", "b": "《管子·君臣下》"}]}, {"meaning": "骚扰。", "cites": [{"t": "巨涂则让,小涂则殆。", "b": "《荀子·荣辱》"}]}, {"meaning": "古代的一种礼节仪式。举手平衡状。", "cites": [{"t": "宾入门皇,升堂让。", "b": "《仪礼·聘礼》。郑玄注:“讓谓举手平衡也。”"}, {"t": "犬行不顾细谨,大礼不辞小让。", "b": "《史记·项羽本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('318wx','礼','1','lǐ','礻','5','','[{"pinyin": "lǐ", "defs": [{"meaning": "(会意。从示,从豊(lǐ)。“豊”是行礼之器,在字中也兼表字音。本义:举行仪礼,祭神求福)。"}, {"meaning": "同本义。", "cites": [{"t": "禮,履也。所以事神致福也。", "b": "《说文》"}, {"t": "脩五礼。", "b": "《虞书》。马注:“吉、凶、军、兵、嘉也。”"}, {"t": "脩六礼以节民性。六礼:冠、昏、丧、祭、乡、相见。", "b": "《礼记·王制》"}, {"t": "夫礼,天之经也,地之义也,民之行也。", "b": "《左传·昭公二十五年》"}, {"t": "冠、婚、朝、聘、丧、祭、宾主、乡饮酒、军旅此之谓九礼。", "b": "《大戴礼记·本命》"}, {"t": "邀见讲钧礼。", "b": "清·周容《芋老人传》"}, {"t": "设九宾礼于廷。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "礼神", "t": "祭神"}, {"w": "礼祠", "t": "以礼祭祀"}, {"w": "礼诵", "t": "礼佛诵经"}, {"w": "礼佛", "t": "顶礼于佛;拜佛。"}]}, {"meaning": "表示敬意;尊敬。", "cites": [{"t": "色愈恭,礼愈至,不敢出一言以复。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "礼交", "t": "以礼相交接"}, {"w": "礼待", "t": "以礼相待"}, {"w": "礼陈", "t": "以礼陈说"}, {"w": "礼新", "t": "礼待新来者。"}]}, {"meaning": "礼拜,顶礼膜拜。", "cites": [{"t": "暗与山僧别,低头礼白云。", "b": "李白《秋浦歌》"}], "words": [{"w": "礼揖", "t": "行礼作揖。"}]}, {"meaning": "礼遇;厚待。", "cites": [{"t": "礼天下之奇才。", "b": "宋·苏洵《六国论》"}, {"t": "信而礼之。", "b": "明·顾炎武《复庵记》"}, {"t": "敬贤礼士。", "b": "《资治通鉴》"}], "words": [{"w": "礼任", "t": "礼遇信任"}, {"w": "礼异", "t": "特殊礼遇"}, {"w": "礼案", "t": "掌管官妓乐籍的部门;亦作“乐案”。官妓乐籍档案。"}]}, {"meaning": "礼节。", "cites": [{"t": "礼节甚倨。(傲慢。)", "b": "《史记》"}], "words": [{"w": "军礼", "t": "军人的礼节"}, {"w": "回礼", "t": "回答别人的敬礼"}, {"w": "礼闱", "t": "指会试。因由礼部主持,故称"}, {"w": "礼宪", "t": "礼仪和法令"}, {"w": "礼检", "t": "指合乎礼仪的品行"}, {"w": "礼职", "t": "指有关礼仪之职务"}, {"w": "礼门", "t": "谓君子循行的礼仪之道"}, {"w": "礼度", "t": "犹礼法。礼仪法度。"}]}, {"meaning": "礼法;等级社会的典章制度,规定社会行为的规范、传统习惯。", "cites": [{"t": "导之以德,齐之以礼。", "b": "《论语·为政》"}], "words": [{"w": "礼防", "t": "指礼法。谓礼之禁乱,犹防之止水"}, {"w": "礼典", "t": "礼法"}, {"w": "礼宗", "t": "指妇女守礼而可为人师法者"}, {"w": "礼则", "t": "礼法,礼制。"}]}, {"meaning": "礼仪。", "cites": [{"t": "卒廷见相如,毕礼而归之。", "b": "《史记》"}], "words": [{"w": "丧礼;礼记", "t": "书名。西汉戴圣编,内容为先秦各家有关礼仪的论著"}, {"w": "礼体", "t": "礼仪,体统"}, {"w": "礼上", "t": "官员上任交替"}, {"w": "礼装", "t": "礼衣;礼服。"}]}, {"meaning": "礼物。", "cites": [{"t": "及受礼,唯酒一斗、鹿肉一柈。", "b": "《晋书·陆纳传》"}], "words": [{"w": "财礼", "t": "彩礼。定婚时男家送给女家的财物"}, {"w": "礼券", "t": "用以代礼物之券。"}]}, {"meaning": "礼貌。", "cites": [{"t": "则是无礼。", "b": "《世说新语·方正》"}, {"t": "轻而无礼。", "b": "《左传·僖公三十三年》"}]}, {"meaning": "又。", "cites": [{"t": "无礼则脱。", "b": ""}, {"t": "秦则无礼。", "b": ""}]}, {"meaning": "礼文;礼书。", "cites": [{"t": "儒以诗礼发冢。", "b": "《庄子·外物》"}, {"t": "礼者,礼经也。", "b": "《礼记》注"}], "words": [{"w": "礼志", "t": "言礼之书"}, {"w": "礼书", "t": "古代记礼法之书"}, {"w": "礼传", "t": "指礼书"}, {"w": "礼经", "t": "古代讲礼节的经典"}, {"w": "礼学", "t": "礼经;礼书之家。"}]}, {"meaning": "(tǐ)。身体。", "cites": [{"t": "采葑采菲,无以下礼。", "b": "《韩诗外传·卷九》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('319wx','训','1','xùn','讠','5','','[{"pinyin": "xùn", "defs": [{"meaning": "(形声。从言,川声。本义:教育,教导)。"}, {"meaning": "同本义。", "cites": [{"t": "训,说教也。", "b": "《说文》"}, {"t": "大训。", "b": "《书·顾命》"}, {"t": "告之训典。", "b": "《左传·文公六年》"}, {"t": "是为明训。", "b": "《国语·晋语》。注:“教也。”"}, {"t": "务材训农,通商惠工。", "b": "《左传·闵公二年》"}, {"t": "而五人生于编伍之间,素不闻诗书之训。", "b": "张溥《五人墓碑记》"}, {"t": "训俭示康。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "训蒙", "t": "在私塾教授小学生"}, {"w": "训蒙教授", "t": "教幼童的私塾先生"}, {"w": "训人", "t": "负责教育的官员或师长"}, {"w": "训章", "t": "训示规范。"}]}, {"meaning": "解说,注释。用通俗的话解释词语的意义。", "cites": [{"t": "但世人未之深亮训说,况文烦富,行于世者,失其旨要,故撰为《略解》焉。", "b": "三国魏·曹操《孙子》序"}], "words": [{"w": "训故", "t": "同训诂"}, {"w": "训义", "t": "解释文字的意义"}, {"w": "训解", "t": "训释解说"}, {"w": "训传", "t": "训解经义。"}]}, {"meaning": "训练;讲习。", "cites": [{"t": "有智略,能训治军旅。", "b": "宋·王安石《举渭川兵马都监盖传等充边上任使状》"}], "words": [{"w": "训戎", "t": "训练军旅"}, {"w": "训治", "t": "训练整治。"}]}, {"meaning": "顺从;归顺。", "cites": [{"t": "四方其训之。", "b": "《诗·大雅·抑》"}, {"t": "于帝其训,又,是训是行。", "b": "《书·洪范》"}]}, {"meaning": "取名。", "cites": [{"t": "后志存小字,不训法名者,遵慈母之意也。", "b": "宋·赞宁《宋高僧传》"}]}, {"meaning": "解说的词语  。如《尔雅·释训》。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('320wx','议','1','yì','讠','5','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从言,义声。本义:商议,讨论)。"}, {"meaning": "同本义。", "cites": [{"t": "议,语也。", "b": "《说文》"}, {"t": "议,谋也。", "b": "《广雅》。按,谓论事之宜。"}, {"t": "唯酒食是议。", "b": "《诗·小雅·斯干》"}, {"t": "法而不议。", "b": "《荀子·王制》"}, {"t": "赵王悉召群臣议。", "b": "《史记》"}], "words": [{"w": "议计", "t": "商议合计"}, {"w": "议妥", "t": "商量妥当"}, {"w": "议婚", "t": "商谈联姻之事。"}]}, {"meaning": "评议是非。", "cites": [{"t": "议论证据古今。", "b": "韩愈《柳子厚墓志铭》"}], "words": [{"w": "议勋", "t": "评议功勋"}, {"w": "议语", "t": "谈论。"}]}, {"meaning": "选择。", "cites": [{"t": "乃议侑于宾。", "b": "《仪礼·有司彻》。注:“犹择也。”"}], "words": [{"w": "议才", "t": "选拔人才。"}]}, {"meaning": "议处;议罪。", "cites": [{"t": "因为诬上,卒从吏议。", "b": "司马迁《报任安书》"}], "words": [{"w": "议状", "t": "论罪定刑的文书"}, {"w": "议处", "t": "清制对有过失的官吏,交吏部拟定处罚办法"}, {"w": "议惩", "t": "评议罪刑给予惩处"}, {"w": "议刑", "t": "议罪以定刑。"}]}, {"meaning": "议论,特指议论政事。", "cites": [{"t": "故圣人议多少论厚薄为之政。", "b": "《韩非子·五蠹》"}, {"t": "大功言而不议。", "b": "《礼记·闲传》"}]}, {"meaning": "(yí)。忖度。", "cites": [{"t": "议之而后动。", "b": "《易·系辞上》"}, {"t": "昔先王议事以制。", "b": "《国语·郑语》。王引之云:“议,读为仪。”"}, {"t": "博学不可使议世。", "b": "《墨子·非儒》。王念孙云:“仪,议古字通。”"}]}, {"meaning": "意见、看法、判断或评价。", "cites": [{"t": "不复料其虚实,便开此议。", "b": "《资治通鉴》"}], "words": [{"w": "议计", "t": "意见和计策"}, {"w": "议论风生", "t": "比喻能言善道,语辞生动有味。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('321wx','必','1','bì','心','5','','[{"pinyin": "bì", "defs": [{"meaning": "(会意。从八,从弋。弋亦兼表字音。“八”表示“分”,“弋”即“杙”,小木桩,合起来指用木杆做标记。本义:区分的标准)。"}, {"meaning": "标杆;标准。", "cites": [{"t": "必,分极也。", "b": "《说文》"}]}, {"meaning": "必须,一定要。", "cites": [{"t": "齐宣王使人吹竽,必三百人。", "b": "《韩非子·内储说》"}, {"t": "必为奇巧声动上。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "山水必有实景。", "b": "蔡元培《图画》"}], "words": [{"w": "必防其渐", "t": "防微杜渐之意。在事情上还不显著或刚刚发生的时侯就加以防止"}, {"w": "必也正名", "t": "必须按礼教来端正名份。"}]}, {"meaning": "必然,必定。", "cites": [{"t": "三人行,必有我师焉。", "b": "《论语》"}, {"t": "人人自以为必死。", "b": "《资治通鉴·唐纪》"}, {"t": "岂人主之子孙则必不善战哉。", "b": "《战国策·赵策》"}], "words": [{"w": "必因", "t": "一定;定然"}, {"w": "必败", "t": "一定败"}, {"w": "必昌", "t": "一定光耀"}, {"w": "必竟", "t": "肯定;一定。"}]}, {"meaning": "必须。", "cites": [{"t": "故天将降大任于斯人也,必先苦其心志,劳其筋骨。", "b": "《孟子》"}]}, {"meaning": "倘偌;假如。", "cites": [{"t": "必求之,吾助子请。", "b": "《左传》"}, {"t": "王必无人,臣愿奉璧往使。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('322wx','讯','1','xùn','讠','5','','[{"pinyin": "xùn", "defs": [{"meaning": "同本义。", "cites": [{"t": "讯,问也。", "b": "《说文》。按,字亦作询。汉宣帝名询。"}, {"t": "讯之占梦。", "b": "《诗·小雅·正月》。传:“问也。”"}, {"t": "多其讯。", "b": "《礼记·学记》。注:“或为訾,按,訾犹咨也。”"}, {"t": "执讯而与之书。", "b": "《左传·文公十二年》。注:“通问之官。”"}, {"t": "君尝讯臣矣。", "b": "《公羊传·僖公十年》。注:“上问下曰讯。”"}, {"t": "以讯首或告。", "b": "《礼记·王制》"}, {"t": "讯鞫论报。", "b": "《汉书·张汤传》。注:“考问也。”"}, {"t": "卒从吏讯。", "b": "《汉书·邹阳传》。注:“谓鞠问也。”"}, {"t": "乃讯申胥。", "b": "《国语·吴语》"}, {"t": "昼夜搒讯。", "b": "清·张廷玉《明史》"}, {"t": "木讯者三人。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "讯定", "t": "审问判决"}, {"w": "讯治", "t": "审问,处罚"}, {"w": "讯责", "t": "审问罪状而加谴责。"}]}, {"meaning": "询问;请教。", "cites": [{"t": "广问讯。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "咸来问讯。", "b": "晋·陶渊明《桃花源记》"}, {"t": "泛讯之。", "b": "清·方苞《狱中杂记》"}, {"t": "你如今也讯听着,不管他根基富贵,只要模样儿配的上,就来告诉我。", "b": "《红楼梦》"}], "words": [{"w": "讯听", "t": "打听。"}]}, {"meaning": "责问,诘问。", "cites": [{"t": "歌以讯之。", "b": "《诗·陈风·墓门》"}, {"t": "讯予不顾。", "b": ""}, {"t": "诏大臣至西宁卫讯理,按例赔偿。", "b": "清·俞正燮《癸已类稿》"}], "words": [{"w": "讯语", "t": "责问的言词"}, {"w": "讯理", "t": "责问处理"}, {"w": "讯让", "t": "又言词责告"}, {"w": "讯语", "t": "责问。"}]}, {"meaning": "问候。", "cites": [{"t": "绸缪结风徽,烟温吐芳讯。", "b": "《文选·谢瞻文》"}], "words": [{"w": "讯牍", "t": "问候的书信"}, {"w": "讯尺", "t": "问候的尺牍"}, {"w": "讯记", "t": "问候的书信。"}]}, {"meaning": "施以讯杖。", "cites": [{"t": "使坊市恶少年罗告富室,诬以罪恶,捕系地牢,讯掠取服。", "b": "《资治通鉴·唐太宗大历四年》"}], "words": [{"w": "讯掠", "t": "拷打审问"}, {"w": "讯疮", "t": "刑讯的创伤"}, {"w": "讯考", "t": "拷问;刑讯。"}]}, {"meaning": "消息;音信。", "cites": [{"t": "有客山中至,言传故人讯。", "b": "储光羲《田家即事答崔二东皋作》"}], "words": [{"w": "通讯;电讯;死讯;音讯;闻讯;简讯;零讯;喜讯", "t": ""}]}, {"meaning": "信。", "cites": [{"t": "行远疾速,而不可托讯者与?", "b": "《荀子》"}], "words": [{"w": "讯函", "t": "信函"}, {"w": "讯报", "t": "文书信函"}, {"w": "讯缄", "t": "信函。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('323wx','记','1','jì','讠','5','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从言,己声。本义:记住)。"}, {"meaning": "同本义。", "cites": [{"t": "记,疏也。", "b": "《说文》"}, {"t": "记,识也。", "b": "《广雅》"}, {"t": "记有成。", "b": "《礼记·内则》"}, {"t": "记间之学。", "b": "《礼记·学记》"}, {"t": "凡所经履,莫不暗记。", "b": "《后汉书·应奉传》"}, {"t": "常记溪亭日暮。", "b": "宋·李清照《如梦令》"}, {"t": "吾记天圣中。", "b": "宋·司马光《训俭示康》"}, {"t": "望中犹记。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "记混了;记错了;切记;牢记;铭记;记不清;记省", "t": "回忆,记忆"}, {"w": "记心", "t": "记在心上,常用于叮嘱"}, {"w": "记念", "t": "挂心;惦念"}, {"w": "记忆", "t": "记在心里。"}]}, {"meaning": "记载,记录。", "cites": [{"t": "记,书也。", "b": "《广雅》"}, {"t": "宫之奇果谏,记曰。", "b": "《公羊传·僖公二年》。注:“史记也。”"}, {"t": "受记考事。", "b": "《汉书·张敞传》"}, {"t": "属予作文以记之。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "记之而去。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "予在患难中,间以诗记所遭。", "b": "文天祥《 后序》"}, {"t": "览则省记。", "b": "清·袁枚《黄生借书说》"}, {"t": "姚鼐记之。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "摘记", "t": "摘要记录"}, {"w": "笔记", "t": "用笔记录"}, {"w": "手记", "t": "亲手记录"}, {"w": "记言", "t": "记录言论。"}]}, {"meaning": "标志,记号。", "cites": [{"t": "仓廒内自有官司封记。", "b": "《水浒传》"}], "words": [{"w": "标记;以红色为记;记色", "t": "凭据;证据。"}]}, {"meaning": "胎记。", "cites": [{"t": "生那儿时,脊背下有一搭红记。", "b": "《警世通言》"}], "words": [{"w": "他身上有块记", "t": ""}]}, {"meaning": "古时的一种公文 。如:奏记;残记。又指记述或解释典章制度的文字。如:十三经中的《周礼·考工记》和《礼记》。"}, {"meaning": "印章。", "cites": [{"t": "正其名,请铸铜记给之。", "b": "《宋史·职官志》"}], "words": [{"w": "戳记;图记;钤记;记室", "t": "官名。掌管章表书记文檄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('324wx','永','1','yǒng','水','5','','[{"pinyin": "yǒng", "defs": [{"meaning": "(象形。小篆字形,象水流曲曲折折的样子。本义:水流长)。"}, {"meaning": "同本义。", "cites": [{"t": "永,水长也。象水巠理之长。", "b": "《说文》"}, {"t": "江之永矣,不可方思。", "b": "《诗·周南·汉广》。毛传:“永,长。”"}]}, {"meaning": "泛指长。兼指时间和空间。", "cites": [{"t": "施于众长谓之永。", "b": "《方言一》"}, {"t": "不永所事。", "b": "《易·讼》"}, {"t": "日永星火。", "b": "《书·尧典》"}, {"t": "维以不永怀。", "b": "《诗·周南·卷耳》"}, {"t": "永矢弗谖。", "b": "《诗·卫风·考槃》"}, {"t": "且以永日。", "b": "《诗·唐风·山有枢》"}, {"t": "求永贞。", "b": "《周礼·大祝》"}, {"t": "永乃保之。", "b": "《仪礼·士冠礼》"}, {"t": "以永终誉。", "b": "《礼记·中庸》"}, {"t": "降年有永有不永。", "b": "《书·高宗彤日》"}, {"t": "斗南当日永,万物显光明。", "b": "《西游记》"}], "words": [{"w": "永昼", "t": "长长的白天"}, {"w": "永永", "t": "久远"}, {"w": "永生", "t": "长生"}, {"w": "永言", "t": "长言"}, {"w": "永伤", "t": "长久忧伤悲痛"}, {"w": "永思", "t": "长思,永怀"}, {"w": "永夕", "t": "长夜"}, {"w": "永日", "t": "长日,漫长的白天"}, {"w": "永宅", "t": "长住永守"}, {"w": "永安", "t": "长久稳固"}, {"w": "永住", "t": "长住;长存"}, {"w": "永命", "t": "长命"}, {"w": "永巷", "t": "宫中长巷;长巷"}, {"w": "永贞", "t": "长享正命"}, {"w": "永宵", "t": "长夜"}, {"w": "永逸", "t": "长久安逸"}, {"w": "永岁", "t": "长寿"}, {"w": "永路", "t": "长途,远路。"}]}, {"meaning": "游泳。“泳”的古字。", "cites": [{"t": "按:此“永”字,即潜行水中之“泳”字之初文。原从人在水中行,由文人做生意,故托以寄游泳之意…后人借用为长永,久而为借意所专,乃加水旁作“泳”以还其原。", "b": "高鸿缙《中国字例》"}]}, {"meaning": "延长。", "cites": [{"t": "资富能训,惟以永年。", "b": "《书·毕命》"}]}, {"meaning": "曼声。长吟,歌唱。", "cites": [{"t": "声依永,律和声。", "b": "《书·舜典》"}, {"t": "乐郊乐郊,谁之永号。", "b": "《诗·魏风·硕鼠》。郑笺:“永,歌也。”"}]}, {"meaning": "永久,永远。", "cites": [{"t": "匪报兮,永以为好也。", "b": "《诗·卫风》"}, {"t": "永奉陛下(永远伺候陛下)。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "与汝永别。", "b": "清·林觉民《与妻书》"}, {"t": "人谋永福。", "b": ""}, {"t": "保守也永旧。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "永别酒", "t": "死囚临刑前喝的酒"}, {"w": "永怀", "t": "永远思念"}, {"w": "永诀", "t": "长别,永不再见"}, {"w": "永康", "t": "永久平安。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('325wx','司','1','sī','口','5','','[{"pinyin": "sī", "defs": [{"meaning": "(指事。甲骨文字形,表示一个人用口发布命令,有统治、管理义。从反后,意思说,与帝王“后”相对为“司”,即有司。本义:职掌,主管)。"}, {"meaning": "同本义(含负责掌握、处理之意)。", "cites": [{"t": "司,臣司事于外者。", "b": "《说文》"}, {"t": "司,臣也。", "b": "《广雅》"}, {"t": "司,主也。", "b": "《小尔雅》。按,周官四十有一司,司者,理其事也。"}, {"t": "司王朝。", "b": "《周礼·师氏》"}, {"t": "司,主也。", "b": "《广雅》"}, {"t": "曰司徒。", "b": "《礼记·曲礼》。疏:“凡言司者,总其领也。”"}, {"t": "至于守司囹圄,禁制刑罚,人臣擅之,此谓刑劫。", "b": "《韩非子·三守》"}, {"t": "使鸡司夜,令狸执鼠,皆用其能,上乃无事。", "b": "《韩非子·扬权》"}, {"t": "役民之司盗者,授之以击刺之术。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "各司其事;司籍", "t": "管理典籍"}, {"w": "司掌", "t": "掌管,管理;管理的人"}, {"w": "司方", "t": "掌管一方;古称指南车"}, {"w": "司铎", "t": "掌管文教。相传古代宣布教化的人必摇木铎以聚众"}, {"w": "司衡", "t": "主管;主宰"}, {"w": "司勋", "t": "主管功赏之事"}, {"w": "司卫", "t": "负责保卫。"}]}, {"meaning": "承担。", "cites": [{"t": "实为人朴素无文,推听掌家樊得和孙升等为提掇,众享其利,而实司其名。", "b": "明·刘若愚《酌中志》"}]}, {"meaning": "侦察,观察。", "cites": [{"t": "为人下者,常司上之,随而行。", "b": "《墨子·号令》"}, {"t": "日欲司间而相与投藉之。", "b": "《荀子·王霸》"}, {"t": "居家相察,出入相司。", "b": "《盐铁论·周秦》"}, {"t": "司男女之无夫家者。", "b": "《周礼·媒氏》。注:“犹察也。”"}, {"t": "以为物而司之。", "b": "《汉书·高五王传》。注:“察视之也。”"}, {"t": "以司日月之长短。", "b": "《山海经·大荒西经》"}]}, {"meaning": "官吏;方面之长。", "cites": [{"t": "若有作奸犯科及为忠善者,宜付有司论其刑赏,以昭陛下平明之理。", "b": "诸葛亮《出师表》"}, {"t": "何必劳神苦思,代百司之职役哉!", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "文武之司;疆场之司;司会", "t": "官名。《周礼》天官之属。掌财政"}, {"w": "司吏", "t": "负责书写工作的小官吏"}, {"w": "司直", "t": "古官名。西汉时设置。辅佐丞相检举不法之事,位于司隶校尉之上。东汉时改属司徒,帮助司徒督察各州郡所举上奏"}, {"w": "司禄", "t": "官名。《周礼》地官之属。掌班禄事。"}]}, {"meaning": "中国古代官署的名称 。唐宋以后,尚书省各部所属有司。现称中央机关部以下一级的行政部门为司。", "cites": [{"t": "十四司正副郎好事者,及书吏、狱官、禁卒,皆利系者之多,少有连必多方钩致。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "财政部计划司", "t": ""}]}, {"meaning": "政府执行部门的独立的下属机构。", "cites": [{"t": "有御史偶阵戏乐,欲遵太祖法,予之杖。百司惴恐,多患苦之。", "b": "《明史·海瑞传》"}, {"t": "京师有京兆狱,有五城御史司坊,何故刑部系囚之多至此?", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "都司;土司;藩司;司房", "t": "州县衙门管理案卷的部门,刑房"}, {"w": "司道", "t": "巡抚的主要属官,司即藩司,臬司;道即道员,包括守道和巡道"}, {"w": "司狱司", "t": "管监狱的机关。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('326wx','尼','1','ní nǐ','尸','5','','[{"pinyin": "ní", "defs": [{"meaning": "(会意。从尸,匕声。甲骨文字形象两个人亲昵的样子。本义:亲近,亲昵)。"}, {"meaning": "同本义", "cites": [{"t": "尼,从后近之也。", "b": "《说文》"}, {"t": "尼,近也。", "b": "《小尔雅》。按,近昵之意,字亦作昵。"}, {"t": "不避远尼。", "b": "《尸子》"}]}, {"meaning": "安定,平和。", "cites": [{"t": "尼,安也。", "b": "《尔雅》"}, {"t": "尼,和也。", "b": "《广雅》"}, {"t": "竟界尼康。", "b": "《隶释·祝睦后碑》"}]}, {"meaning": "尼姑,佛教中出家修行的女子。是梵语“比丘尼”(Bhidsunt)的简称。", "cites": [{"t": "人道为尼,遂居此寺。", "b": "《洛阳伽蓝记·胡统寺》"}], "words": [{"w": "僧尼", "t": "和尚和尼姑"}, {"w": "尼寺", "t": "尼姑所住的寺院"}, {"w": "尼房", "t": "尼姑所居处"}, {"w": "尼坛", "t": "尼姑受戒的地方。"}]}]}, {"pinyin": "nǐ", "defs": [{"meaning": "阻止;阻拦。", "cites": [{"t": "淫嚣不静,当路尼众。", "b": "《墨子》"}], "words": [{"w": "尼行", "t": "停止或阻止前进"}, {"w": "尼阻", "t": "阻止,阻碍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('327wx','民','1','mín','氏','5','','[{"pinyin": "mín", "defs": [{"meaning": "(指事。从古文之象。古文从母,取蕃育意。古代指黎民百姓,平民。与君、官对称)。"}, {"meaning": "同本义。", "cites": [{"t": "民,众萌也。从古文之象。", "b": "《说文》。按,古文从母。取蕃育也,上下众多意,指事。"}, {"t": "民,氓也。", "b": "《广雅》。按,土著者曰民,外来者曰氓。"}, {"t": "古者有四民,有士民,有商民,有农民,有工民。", "b": "《谷梁传·成公元年》"}, {"t": "夫民神之主也。", "b": "《左传·桓公六年》"}, {"t": "无子曰兆民。诸侯曰万民。", "b": "《左传·闵公元年》"}, {"t": "黎民阻饥。", "b": "《书·舜典》"}, {"t": "民不适有居。", "b": "《书·盘庚上》"}, {"t": "哀我征夫,独为匪民。", "b": "《诗·小雅·何草不黄》"}, {"t": "民可使由之,不可使知之。", "b": "《论语·泰伯》"}, {"t": "吾入关,秋毫不敢有所近,籍吏民,封府库,而待将军。", "b": "《史记·项羽本纪》"}, {"t": "民为贵,社稷次之,君为轻。", "b": "《孟子·尽心下》"}], "words": [{"w": "民夫", "t": "被官府征召服劳役的百姓"}, {"w": "民户", "t": "民家"}, {"w": "民居", "t": "百姓居住之所"}, {"w": "民服", "t": "平民的衣服"}, {"w": "民宅", "t": "民房"}, {"w": "民望", "t": "民众的希望、心愿;在民众中的声望"}, {"w": "民牧", "t": "民众的治理者。后指地方的长官"}, {"w": "民情", "t": "民众的心情、意愿"}, {"w": "民役", "t": "民众所承担的劳役"}, {"w": "民利", "t": "民众的利益"}, {"w": "民命", "t": "民众的意旨;民众的生命;人命"}, {"w": "民和", "t": "民众和睦团结"}, {"w": "汉民;回民;藏民;民壮", "t": "清朝州、县官的卫兵。即三班中的壮班"}, {"w": "渔民;农民;牧民;民膏", "t": "比喻人民用血汗创造的财富"}, {"w": "民经", "t": "人民的规范"}, {"w": "民熙物阜", "t": "人民安乐,物产富饶。形容升平景象"}, {"w": "民害", "t": "人民的祸害"}, {"w": "民力", "t": "人民的财力和劳力"}, {"w": "民脂", "t": "比喻人民的劳动果实"}, {"w": "民财", "t": "人民的财物"}, {"w": "民纪", "t": "人民行为的准则"}, {"w": "民祗", "t": "人民所敬畏者。"}]}, {"meaning": "泛指人。", "cites": [{"t": "民受无地之中以生。", "b": "《左传·成公十三年》"}, {"t": "食者,民之本也。", "b": "《淮南子》"}, {"t": "石斧之民。", "b": "〔英〕赫胥黎著、严复译《天演论》"}], "words": [{"w": "民性", "t": "人的天赋本性"}, {"w": "民灵", "t": "人和神"}, {"w": "民智", "t": "人的聪明才智。"}]}, {"meaning": "民间的。", "cites": [{"t": "轻徭薄赋,以宽民力。", "b": "方勺《方腊起义》"}], "words": [{"w": "民谣", "t": "民间流传的歌谣"}, {"w": "民营", "t": "民间经营"}, {"w": "民语", "t": "民间广泛流行的定型的言语"}, {"w": "民狱", "t": "民间诉讼案件"}, {"w": "民社", "t": "民间祭祀土神。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('328wx','弗','1','fú','弓','5','','[{"pinyin": "fú", "defs": [{"meaning": "(象形。甲骨文字形,中间象两根不平直之物,上以绳索束缚之,使之平直。本义:矫枉)。"}, {"meaning": "同本义。", "cites": [{"t": "弗,矫也。", "b": "《说文》。徐灏注:“弗与弼音义同。凡弛弓,则以两弓相背而缚之,以正枉戾,所谓矫也。…阮太傅曰:弗字明是从弓。”"}]}, {"meaning": "违拗;拂逆。", "cites": [{"t": "诸君!敌人远我,欲以火器困我也,急逐弗失。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "弗声", "t": "不要出声。"}]}, {"meaning": "(fèi)。泉水喷涌的样子。", "cites": [{"t": "其高工之民,修治苦窳之器,聚弗靡之财,蓄积待时而牟农夫之利。", "b": "《韩非子》"}, {"t": "汹涌彭湃,滭弗密汨。", "b": "《汉书·司马相如传》"}]}, {"meaning": "怫郁,不舒畅。", "cites": [{"t": "吾山平兮钜野溢,鱼弗郁兮柏冬日。", "b": "《汉书·沟洫志》"}]}, {"meaning": "“弗”为“不”的同源字。", "cites": [{"t": "其言‘弗遇’何?", "b": "《公羊传·桓公十年》。注:“弗,不之深也。”"}, {"t": "澭水暴益,荆人弗知。", "b": "《吕氏春秋·察今》"}, {"t": "台臣弗为理。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "弗招架", "t": "方言。不留神;疏忽"}, {"w": "弗受用", "t": "方言。不舒服;患病"}, {"w": "弗翻淘", "t": "方言。没有关系"}, {"w": "弗识起倒", "t": "不知趣;不识好歹。"}]}, {"meaning": "笔。", "cites": [{"t": "笔,楚谓之聿,吴谓之不律,燕谓之弗。", "b": "清·杭世骏《续方言》"}]}, {"meaning": "法国货币法郎的异译。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('329wx','弘','1','hóng','弓','5','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从弓。厶(gōng)声。本义:弓声)。"}, {"meaning": "同本义。", "cites": [{"t": "弘,弓声也。", "b": "《说文》"}]}, {"meaning": "假借为“宏”。大的(现多作宏)。", "cites": [{"t": "弘,大也。", "b": "《尔雅》"}, {"t": "弘璧。", "b": "《书·顾命》"}, {"t": "丧乱弘多。", "b": "《诗·小雅·节南山》"}, {"t": "式虽小子,而式弘大。", "b": "《诗·大雅·民劳》"}, {"t": "诚取善之弘大。", "b": "清·刘开《问说》"}], "words": [{"w": "弘功", "t": "大功"}, {"w": "弘慈", "t": "大慈大悲"}, {"w": "弘绩", "t": "伟大的功绩"}, {"w": "弘长", "t": "远大;扩大;昌盛。"}]}, {"meaning": "广,广大。", "cites": [{"t": "士不可以不弘毅,任重而道远。", "b": "《论语·泰伯》"}], "words": [{"w": "弘休", "t": "广大的福泽"}, {"w": "弘浃", "t": "广大普遍"}, {"w": "弘致", "t": "广泛招来,极力延揽;大致的意思;大旨"}, {"w": "弘深", "t": "广大渊深。"}]}, {"meaning": "扩大;推广;光大。", "cites": [{"t": "弘,大之也。", "b": "《字汇》"}, {"t": "人能弘道,非道弘人。", "b": "《论语·卫灵公》"}], "words": [{"w": "弘化", "t": "推广教化"}, {"w": "弘长", "t": "光大发扬"}, {"w": "弘道", "t": "弘扬大道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('330wx','出','1','chū','凵','5','','[{"pinyin": "chū", "defs": [{"meaning": "(象形。象草木益滋上出达之形。本义:长出)。"}, {"meaning": "同本义。", "cites": [{"t": "出,进也。象草木益滋,上出达也。", "b": "《说文》。按,《说文》讲的“出”,其实是茁。"}, {"t": "句者毕出,萌者尽达。", "b": "《礼记·月令·季春》"}, {"t": "万物出乎震。", "b": "《易·说卦》"}]}, {"meaning": "引申为出入的“出”。出去,出来,与“入”相对。", "cites": [{"t": "诸侯出庙门俟。", "b": "《书·顾命》"}, {"t": "出自北门。", "b": "《诗·邶风·北门》"}, {"t": "我出我车。", "b": "《诗·小雅·出车》"}, {"t": "出车彭彭。", "b": ""}, {"t": "群众既皆承命,相揖趋出。", "b": "《书·康王之诰》"}, {"t": "我以日始出时去人近。", "b": "《列子·汤问》"}, {"t": "月出惊山鸟,时鸣春涧中。", "b": "王维《鸟鸣涧》"}], "words": [{"w": "出关;出塞;出城;出东门", "t": ""}]}, {"meaning": "出现;显露。", "cites": [{"t": "出自东方。", "b": "《诗·邶风·日月》"}, {"t": "月出之光。", "b": "《诗·齐风·鸡鸣》"}, {"t": "风霜高洁,水落而石出。", "b": "欧阳修《醉翁亭记》"}], "words": [{"w": "出化", "t": "显现"}, {"w": "出落", "t": "透露,显示;弄得,只落得"}, {"w": "出日", "t": "日出之处"}, {"w": "出出", "t": "连续出现的样子。"}]}, {"meaning": "生产;产生。", "cites": [{"t": "殚其地之出。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "出产", "t": "生产。"}]}, {"meaning": "高出;超出。", "cites": [{"t": "古之圣人,其出人也远矣。", "b": "韩愈《师说》"}], "words": [{"w": "出人", "t": "超越别人"}, {"w": "出服", "t": "出了五服。指出了规定的服丧范围"}, {"w": "出尖", "t": "拔尖;强出头"}, {"w": "出景", "t": "突出"}, {"w": "出月", "t": "出了本月;下个月。"}]}, {"meaning": "使出;拿出;取出。", "cites": [{"t": "余人各复延至其家,皆出酒食。", "b": "陶渊明《桃花源记》"}, {"t": "贫者出力", "b": ""}], "words": [{"w": "出费", "t": "拿出费用"}, {"w": "出分子", "t": "拿出若干钱来送礼"}, {"w": "出捐", "t": "拿出。"}]}, {"meaning": "发出,发布。", "cites": [{"t": "出言有章。", "b": "《诗·小雅·都人士》"}], "words": [{"w": "出案", "t": "张榜"}, {"w": "出布告", "t": ""}]}, {"meaning": "逃亡。", "cites": [{"t": "不能改而出圜土者。", "b": "《周礼·大司寇》。注:“谓逃亡也。”"}], "words": [{"w": "出彀", "t": "逃出樊笼"}, {"w": "出甲", "t": "指逃兵。"}]}, {"meaning": "经过,穿过 。 如:出边(渡越边境)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('331wx','辽','1','liáo','辶','5','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从辵(chuò),尞(liáo)声。本义:遥远)。"}, {"meaning": "同本义。", "cites": [{"t": "辽,远也。", "b": "《说文》"}, {"t": "山修远其辽辽兮。", "b": "《楚辞·九叹·忧苦》。注:“辽辽,远貌。”"}, {"t": "楚师辽远,粮食将尽,必将速归。", "b": "《左传·襄公八年》"}, {"t": "眷故乡之辽隔。", "b": "潘岳《登虎牢山赋》"}], "words": [{"w": "辽绝", "t": "远隔"}, {"w": "辽险", "t": "遥远险要"}, {"w": "辽天", "t": "远天"}, {"w": "辽阻", "t": "辽远阻隔"}, {"w": "辽荒", "t": "荒凉遥远。"}]}, {"meaning": "开阔。", "cites": [{"t": "江山辽落,居然有万里之势。", "b": "《世说新语·言语》"}], "words": [{"w": "辽落", "t": "通“寥落”。寂寥空阔"}, {"w": "辽缓", "t": "宽缓"}, {"w": "辽辽", "t": "广远的样子"}, {"w": "辽阔", "t": "远大广阔"}, {"w": "辽空", "t": "辽阔的天空"}, {"w": "辽原", "t": "辽阔原野。"}]}, {"meaning": "久远。", "cites": [{"t": "人生乐长久,百年自言辽。", "b": "阮籍《咏怀》"}], "words": [{"w": "辽远", "t": "久远"}, {"w": "辽廓", "t": "久远。"}]}, {"meaning": "朝代名 。公元916年,契丹族领袖耶律阿保机创建,国号契丹,两年后建都皇都(今内蒙巴林左旗南波罗城)。公元947年改国号为辽(983—1066年间曾重称契丹),改皇都为上京。疆域东北至今日本海黑龙江口,西北至蒙古中部,南以今天津海河、河北霸县、山西雁门关一线与宋接界。"}, {"meaning": "同为官吏,或朋辈。", "cites": [{"t": "遼党感动。", "b": "《外黄令高彪碑》"}, {"t": "朝廷愍惜,百遼叹伤。", "b": "《沛相杨统碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('332wx','奶','1','nǎi','女','5','','[{"pinyin": "nǎi", "defs": [{"meaning": "(古作嬭) (形声。从女,乃声。本义:乳房)。"}, {"meaning": "同本义。", "cites": [{"t": "今人谓乳房为奶,乳汁亦为奶。“奶”是“乳”的音转。", "b": "王力《同源字典》"}], "words": [{"w": "奶胖", "t": "乳子。"}]}, {"meaning": "乳汁。", "cites": [{"t": "我的血变了奶,吃的长这么大。", "b": "《红楼梦》"}], "words": [{"w": "奶食;奶豆腐;奶醒", "t": "乳汁的气味"}, {"w": "奶食", "t": ""}]}, {"meaning": "奶奶的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('333wx','奴','1','nú','女','5','','[{"pinyin": "nú", "defs": [{"meaning": "(会意。从女,从又。女指女奴,又(手)指用手掠夺之。一说又(手)指女奴从事劳动。本义:奴隶;奴仆)。"}, {"meaning": "同本义。", "cites": [{"t": "奴,奴婢皆古之罪人也。", "b": "《说文》"}, {"t": "其奴,男子入于罪隶,女子入于舂槁。", "b": "《周礼·司厉》"}, {"t": "从群奴而驰。", "b": "明·高启《书博鸡者事》"}, {"t": "奴惊", "b": ""}, {"t": "庸奴。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "对人的鄙称。", "cites": [{"t": "要当生缚此奴。", "b": "房玄龄《晋书》"}], "words": [{"w": "奴胎", "t": "对乐户子女或奴婢的贱称;骂人话,犹贱种"}, {"w": "胡奴;狂奴;奴官", "t": "出身卑贱的小军官"}, {"w": "奴下", "t": "才能低下的人。"}]}, {"meaning": "自称。"}, {"meaning": "古时青年女子的自称,或称“奴家”。", "cites": [{"t": "奴家年青,如何敢受礼。", "b": "施耐庵《水浒传》"}]}, {"meaning": "看作奴仆;贬低;使沦为奴隶。", "cites": [{"t": "入者主之,出者奴之。", "b": "韩愈《原道》"}], "words": [{"w": "奴化;奴视", "t": "视之如奴,轻视之意。"}]}, {"meaning": "水不流动。", "cites": [{"t": "不流曰奴。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('334wx','召','1','zhào','口','5','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从口,刀声。本义:呼唤)。"}, {"meaning": "召唤。用言语叫人来。", "cites": [{"t": "召,呼也。从口,刀声。以言曰召,以手曰招。", "b": "《说文》"}, {"t": "召,呼也。", "b": "《广雅·释诂二》"}, {"t": "召有司。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "召赵御吏。", "b": ""}, {"t": "大府召视儿。", "b": "唐·柳宗元《童区寄传》"}, {"t": "亦召供奉。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "召呼", "t": "呼唤;通知;交代"}, {"w": "召致", "t": "使之至;唤来。"}]}, {"meaning": "招致。", "cites": [{"t": "故言有召祸也,行有招辱也。", "b": "《荀子·劝学》"}, {"t": "召武受辞。", "b": "《汉书·李广苏建传》"}, {"t": "收召后学。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "召闹取怒。", "b": ""}], "words": [{"w": "召引", "t": "招引;引导"}, {"w": "召幸", "t": "被招致或宠爱的人"}, {"w": "召取", "t": "导致;引来。"}]}, {"meaning": "邀请。", "cites": [{"t": "楚人有烹猴而召其邻人。", "b": "《淮南子·脩务》。注:“召,犹请也。”"}, {"t": "令召客者酒酣。", "b": "《吕氏春秋·分职》"}, {"t": "今召客者,酒酣,歌舞,鼓瑟吹竽。", "b": "《吕氏春秋》"}]}, {"meaning": "征召来授予官职或另有调用。", "cites": [{"t": "于是天子乃召拜广为右北平太守。", "b": "《史记·李将军列传》"}, {"t": "召三老。", "b": "《史记·陈涉世家》"}, {"t": "累召不应。", "b": "《后汉书·张衡传》"}, {"t": "卒不召。", "b": "《明史》"}, {"t": "召为南京右佥都御史。", "b": ""}]}, {"meaning": "感化和召唤。", "cites": [{"t": "物色相召,人谁获安!", "b": "《文心雕龙》"}]}, {"meaning": "召集。", "cites": [{"t": "召令徒属。", "b": "《史记·陈涉世家》"}, {"t": "悉召群臣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "召诸贵人。", "b": "《汉书·李广苏建传》"}, {"t": "召会武官。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('335wx','加','1','jiā','力','5','','[{"pinyin": "jiā", "defs": [{"meaning": "(会意。从力,从口。本义:添枝加叶说假话、虚报)。"}, {"meaning": "同本义。", "cites": [{"t": "加,语相增加也。", "b": "《说文》"}, {"t": "君子称其功以加小人。", "b": "《左传·襄公十三年》"}, {"t": "我不欲人之加诸我也。", "b": "《论语》"}, {"t": "弗敢加也。", "b": "《左传·庄公十年》"}], "words": [{"w": "加叶添枝", "t": "加油添醋,加油加醋,加油添酱。为了夸张或渲染的需要,在叙述或转述时,增添原来没有的内容"}, {"w": "加诸", "t": "诬谤;凌驾于;乱说"}, {"w": "加诬", "t": "虚构诬陷。"}]}, {"meaning": "增加。", "cites": [{"t": "臂非加长。", "b": "《荀子·劝学》"}, {"t": "声非加疾。", "b": ""}, {"t": "何以复加。", "b": "《汉书·李广苏建传》"}, {"t": "加其土封。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "加注解;加符号;加一钱", "t": "收到本金十分之一的高利贷"}, {"w": "加二", "t": "二成"}, {"w": "加绪含容", "t": "增加功绩,包含宽容。绪:功绩"}, {"w": "加纳", "t": "加官受职"}, {"w": "加年", "t": "年龄增长"}, {"w": "加兵", "t": "增加兵力。"}]}, {"meaning": "放在上面,加上。", "cites": [{"t": "加彘肩上。", "b": "《史记·项羽本纪》"}, {"t": "加以金银。", "b": "宋·司马光《训俭示康》"}, {"t": "三缢加别械。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "加额", "t": "把手放在额头,表示庆幸或敬意"}, {"w": "加冠", "t": "古代男子二十岁行加冠礼,表示成年;著冠"}, {"w": "加笄", "t": "以簪束发。古代女子十五岁开始加笄,表示成年。"}]}, {"meaning": "施加;强加。", "cites": [{"t": "加之以师旅。", "b": "《论语·先进》"}, {"t": "加诸彼。", "b": "《孟子·梁惠王上》"}, {"t": "加兵于赵。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "卒不加诛。", "b": "汉·刘向《列女传》"}], "words": [{"w": "加功", "t": "施工"}, {"w": "加惠", "t": "施加恩惠。"}]}, {"meaning": "凌驾,侵凌。", "cites": [{"t": "加胜于赵。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "表示程度,相当于“更加”,“愈加”。", "cites": [{"t": "山不加增。", "b": "《列子·汤问》"}, {"t": "至又加少。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "加二", "t": "—ní方言。更加;加倍"}, {"w": "加丰", "t": "更加丰富"}, {"w": "加损", "t": "愈加减少"}, {"w": "加顺灵祗", "t": "更加顺应神灵的意思。"}]}, {"meaning": "益处;好处。", "cites": [{"t": "万钟则不辨礼义而受之,万钟于我何加焉?", "b": "《孟子·鱼我所欲也》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('336wx','皮','1','pí','皮','5','','[{"pinyin": "pí", "defs": [{"meaning": "(会意。金文字形上面是个口,表示兽的头;一竖表示身体;右边半圆表示已被揭起的皮;右下表手。“皮”是汉字部首之一。本义:用手剥兽皮)。"}, {"meaning": "同本义。", "cites": [{"t": "皮,剥取兽革者谓之皮。", "b": "《说文》"}, {"t": "皮,剥也。", "b": "《广雅》"}, {"t": "皮面抉眼。", "b": "《战国策·韩策》"}, {"t": "皮瓠以为蓄。", "b": "《释名》"}], "words": [{"w": "皮面", "t": ""}]}, {"meaning": "兽皮。", "cites": [{"t": "孤执皮帛。", "b": "《周礼·大宗伯》。注:“虎豹皮。”"}, {"t": "俪皮。", "b": "《仪礼·士昏礼》。注:“鹿皮。”"}, {"t": "事之以皮币。", "b": "《孟子》"}, {"t": "禽兽之皮足衣也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "皮条", "t": "用皮子做成的绳、带"}, {"w": "皮鼓", "t": "军用小鼓"}, {"w": "皮松肉紧", "t": "喻指淡漠;宽泛"}, {"w": "皮甲", "t": "用兽皮制的软甲"}, {"w": "皮船", "t": "古时用牛皮蒙罩船身以御矢石的战船"}, {"w": "皮胶", "t": "用动物皮熬成的粘性物质"}, {"w": "皮舰", "t": "古代用牛皮蒙罩船身以防御矢石的战舰。"}]}, {"meaning": "皮毛;皮革。", "cites": [{"t": "岛夷皮服。", "b": "《书·禹贡》"}], "words": [{"w": "皮排", "t": "古代以皮革制作的鼓风器具"}, {"w": "皮笠", "t": "古代革制的笠形帽"}, {"w": "皮袋", "t": "皮制的袋"}, {"w": "皮裘", "t": "毛皮的衣服"}, {"w": "皮褂", "t": "用毛皮做的上衣"}, {"w": "皮裳", "t": "用毛皮做的衣裳"}, {"w": "皮褥", "t": "毛皮做的垫褥"}, {"w": "皮箧", "t": "皮箱"}, {"w": "皮侯", "t": "古代以兽皮为饰的箭靶。"}]}, {"meaning": "包或围在物体外面的一层东西。", "cites": [{"t": "于时冰皮始解,波色乍明。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "书皮;饺子皮;馄饨皮也叫“皮子”", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('337wx','边','1','biān','辶','5','','[{"pinyin": "biān", "defs": [{"meaning": "(形声。从辵(chuò),臱(mián)声。本义:山崖的边缘)。"}, {"meaning": "同本义。", "cites": [{"t": "边,行垂崖也。", "b": "《说文》"}, {"t": "边,垂也。", "b": "《尔雅》"}, {"t": "白帝城边足风波,瞿塘五月谁敢过。", "b": "唐·李白《荆州歌》"}], "words": [{"w": "崖边;岸边;水池边;边侧", "t": "边沿,旁侧"}, {"w": "边涯", "t": "边际;边缘。"}]}, {"meaning": "边境。", "cites": [{"t": "其在边邑。", "b": "《礼记·玉藻》。注:“九洲之外。”"}, {"t": "顿颡于边。", "b": "《国语·吴语》。注:“边,边境也。”"}, {"t": "臣闻五大不在边,五细不在庭。(五大:一种大人物。)", "b": "《左传·昭公十一年》"}, {"t": "思念北边之末安。", "b": "《盐铁论·利议》"}, {"t": "归来头白还戍边。", "b": "唐·杜甫《兵车行》诗"}], "words": [{"w": "边人", "t": "边境的人"}, {"w": "边民", "t": "边境的人民"}, {"w": "边缺", "t": "边远地区官职的空缺"}, {"w": "边任", "t": "驻守边远地区的重要职位"}, {"w": "边庭", "t": "边疆"}, {"w": "边夷", "t": "泛指边疆的少数民族"}, {"w": "边功", "t": "在边境抗敌所建立的功劳。"}]}, {"meaning": "旁边。", "cites": [{"t": "边,方也。", "b": "《广雅》"}, {"t": "续衽钩边。", "b": "《礼记·深衣》"}, {"t": "齐衰不以边坐。", "b": "《礼记·檀弓》"}, {"t": "鸟宿池边树。", "b": "宋·胡仔《苕溪渔隐丛话》"}], "words": [{"w": "左边;右边;边厢", "t": "旁边"}, {"w": "边邦", "t": "邻邦"}, {"w": "边近", "t": "旁边,附近。"}]}, {"meaning": "尽头。", "cites": [{"t": "无边落木萧萧下,不尽长江滚滚来。", "b": "唐·杜甫《登高》"}], "words": [{"w": "无边;无边无际;边梢", "t": "树枝的末梢。"}]}, {"meaning": "方位词的后缀。", "cites": [{"t": "故垒西边。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "东边;西边;后边;前边", "t": ""}]}, {"meaning": "靠近。", "cites": [{"t": "齐边楚。", "b": "《史记·高祖本纪》。集解:“近也。”"}], "words": [{"w": "边鄙", "t": "靠近边界的地方"}, {"w": "边海", "t": "靠海,临海;海边"}, {"w": "边带", "t": "邻接,毗连。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('338wx','孕','1','yùn','子','5','','[{"pinyin": "yùn", "defs": [{"meaning": "(会意。甲骨文字形,外象妇女大腹之形,内象腹中怀子之形。本义:怀胎)。"}, {"meaning": "同本义。", "cites": [{"t": "孕裹子也。", "b": "《说文》"}, {"t": "毛者孕鬻。", "b": "《礼记·乐记》"}, {"t": "夫征不复,妇孕不育,凶。", "b": "《易·渐》"}], "words": [{"w": "孕重", "t": "怀胎"}, {"w": "孕吐", "t": "妊娠初期呕吐"}, {"w": "孕乳", "t": "怀胎哺育。"}]}, {"meaning": "孕育 。虽未显露、表达或发展,但却包含在某物本质中的。", "cites": [{"t": "拙辞或孕于巧义,庸事或萌于新意。", "b": "《文心雕龙》"}], "words": [{"w": "孕毓", "t": "孕育"}, {"w": "孕化", "t": "孕育变化。"}]}, {"meaning": "包含,含。", "cites": [{"t": "薪的饱孕着愁思的俊俏的脸庞也别有一种神秘的力量。", "b": "茅盾《路》"}], "words": [{"w": "孕括", "t": "包孕总括。"}]}, {"meaning": "分娩,生小孩。", "cites": [{"t": "野合有身,月满当孕。", "b": "《搜神记》"}], "words": [{"w": "孕别", "t": "生育。"}]}, {"meaning": "花含实。", "cites": [{"t": "花开满树红,花落万枝空。唯余一孕在,明日定随风。", "b": "知玄《五岁咏花》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('339wx','发','1','fā fà fèi','又','5','','[{"pinyin": "fā", "defs": [{"meaning": "(形声。本义: 放箭)。"}, {"meaning": "同本义。", "cites": [{"t": "發,射发也。", "b": "《说文》"}, {"t": "壹发五豝。", "b": "《诗·召南·驺虞》"}, {"t": "发彼有的。", "b": "《诗·小雅·宾之初筵》"}, {"t": "循声而发。", "b": "《礼记·射义》"}, {"t": "矢四发。", "b": "《汉书·匈奴传》"}, {"t": "其射,见敌急,非在数十步之内,度不中不发,发即应弦而倒。", "b": "《史记·李将军列传》"}, {"t": "暮见火而俱发。", "b": "《史记·孙子吴起列传》"}, {"t": "见其发矢十中八九。", "b": "宋·欧阳修《归田录》"}, {"t": "度不中而轻发。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": " 百发百中; 发矢", "t": "射箭"}, {"w": " 发箭", "t": "射箭"}, {"w": "发功", "t": "指射技。"}]}, {"meaning": "出发;上路。", "cites": [{"t": "发,去也。", "b": "《广雅》"}, {"t": "履我发兮。", "b": "《诗·齐风·东方之日》"}, {"t": "朝发枉诸。", "b": "《楚辞·离骚·涉江》"}, {"t": "顷之未发。", "b": "《战国策·燕策》"}, {"t": "卿与子敬、程公便前发。", "b": "《资治通鉴》"}, {"t": "兰舟催发。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "发足(起程,出发)发程(起程,上路;动身启程", "t": ""}, {"w": "发逐", "t": "出发追逐"}, {"w": "发迈", "t": "出发远行。"}]}, {"meaning": "打开;开启。", "cites": [{"t": "成有子九岁,窥父不在,窃发盆。", "b": "《聊斋志异·促织》"}], "words": [{"w": "发日", "t": "公文的启封日期"}, {"w": "发书", "t": "拆开诏书或书信。"}]}, {"meaning": "征发;征调。", "cites": [{"t": "西门豹即发民凿十二渠。", "b": "《西门豹治邺》"}], "words": [{"w": "发召", "t": "征调"}, {"w": "发调", "t": "征调"}, {"w": "发徭", "t": "征派徭役。"}]}, {"meaning": "发生;发出。", "cites": [{"t": "使人发书于赵王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "而大声发于水上。", "b": "宋·苏轼《石钟山记》"}, {"t": "怀怒未发。", "b": "《战国策·魏策》"}, {"t": "变遂发。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "发念", "t": "萌生念头"}, {"w": "发意", "t": "产生某种意念"}, {"w": "发兴", "t": "发生。"}]}, {"meaning": "发布;宣告。", "cites": [{"t": "今王发政施仁,使天下仕者皆立于王之朝。", "b": "《孟子·梁惠王上》"}, {"t": "遂发命,遽兴姜戎。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "发政", "t": "发布政令。"}]}, {"meaning": "抒发;发泄。", "cites": [{"t": "发狂吟。", "b": "《三国演义》"}, {"t": "发其志士之悲哉。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "发郁", "t": "发泄郁结在心头的烦闷"}, {"w": "发忿", "t": "发泄愤恨的情绪"}, {"w": "发挥", "t": "抒发。"}]}, {"meaning": "派遣。", "cites": [{"t": "吾欲发兵,使公及桓楚将。", "b": "《史记·项羽本纪》"}, {"t": "二世元年四月,发闾左适戍渔阳九百人。", "b": "《史记·陈涉世家》"}, {"t": "孤当续发人众,多载资粮,为卿后援。", "b": "《资治通鉴》"}], "words": [{"w": "发师", "t": "派遣军队、出兵"}, {"w": "发导", "t": "派遣向导。"}]}, {"meaning": "挖掘。", "cites": [{"t": "于败石丛草处,探石发穴。", "b": "《聊斋志异·促织》"}], "words": [{"w": "发冢", "t": "掘墓"}, {"w": "发硎", "t": "发掘整理"}, {"w": "发揭", "t": "发掘,揭开。"}]}, {"meaning": "花开放。", "cites": [{"t": "野芳发而幽香。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "发秀", "t": "开花"}, {"w": "发彩", "t": "指开花。"}]}, {"meaning": "送出;交付。与“收”相对;发出。", "cites": [{"t": "发五十金。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "发电报", "t": ""}]}, {"meaning": "显现;显露。", "cites": [{"t": "征于色,发于声,而后喻。", "b": "《孟子·告子下》"}, {"t": "凄凄切切,呼号奋发。", "b": "宋·欧阳修《秋声赋》"}], "words": [{"w": "发色", "t": "呈现色彩"}, {"w": "发迷", "t": "显现迷惘的神情"}, {"w": "发梦", "t": "显现梦境。"}]}, {"meaning": "揭露;暴露。", "words": [{"w": "发奸", "t": "揭发坏人坏事"}, {"w": "发潜", "t": "揭发潜伏的坏人坏事"}, {"w": "发举", "t": "揭发,检举。"}]}, {"meaning": "点燃;燃烧起来 褺。", "cites": [{"t": "同时发火。", "b": "《资治通鉴》"}], "words": [{"w": "发爨", "t": "烧火做饭"}, {"w": "发薪", "t": "点燃柴草。"}]}, {"meaning": "除去;错乱。", "cites": [{"t": "居干之道,菑栗不迤,则弓不发。", "b": "《周礼·考工记·弓人》"}, {"t": "毋逝我梁,毋发我笱。", "b": "《诗·邶风·谷风》"}]}, {"meaning": "效法,遵守。", "cites": [{"t": "法者不可不恒也,存亡治乱所从出,圣君所以为天下大仪也,君臣上下贵贱皆发焉。", "b": "《管子·任法》"}]}]}, {"pinyin": "fà", "defs": [{"meaning": "头发,人头上的毛 ?。", "cites": [{"t": "巽为寡发。", "b": "《易·说卦》"}, {"t": "其华在发。", "b": "《素问·大节藏象论》"}, {"t": "穷发之下。", "b": "《庄子·逍遥游》"}, {"t": "束发而就大学。", "b": "《大戴礼记·保傅》"}, {"t": "结发成夫妻。", "b": "《苏武古诗》。注:“结发始成人也。谓男年二十,女年十五,时取笄冠为义也。”"}, {"t": "人不寐,将军白发征夫泪。", "b": "宋·范仲淹《渔家傲》"}], "words": [{"w": "理发;脱发;怒发冲冠", "t": "形容怒极。"}]}, {"meaning": "草木。", "cites": [{"t": "穷发之北有冥海者,天池也。", "b": "《庄子》"}, {"t": "山以草木为发。", "b": "《地理书》"}]}, {"meaning": "古代旐末形如燕尾的垂旒;旗帜的通称。", "cites": [{"t": "武王载发,有虔秉钺;如火烈烈,则莫我敢遏。", "b": "《荀子·议兵》"}]}]}, {"pinyin": "fèi", "defs": [{"meaning": "崩坏;停止。", "cites": [{"t": "天无以清,将恐裂;地无以宁,将恐发。", "b": "《老子》"}, {"t": "君夜发不可以朝。", "b": "《晏子春秋》"}, {"t": "景公饮酒,酲,三日而后发。", "b": ""}], "words": [{"w": "发药", "t": "停止用药。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('340wx','圣','1','shèng','土','5','','[{"pinyin": "shèng", "defs": [{"meaning": "(形声。从耳,呈声。甲骨文字形。左边是耳朵,右边是口字。即善用耳,又会用口。本义:通达事理)。"}, {"meaning": "同本义。", "cites": [{"t": "圣,通也。", "b": "《说文》。按:耳顺之谓圣。彼教所言耳根圆通亦此意。"}, {"t": "听信之谓圣。", "b": "《管子·四时》"}, {"t": "睿作圣。", "b": "《书·洪范》。传:“于事无不通谓之圣。”"}, {"t": "母氏圣善。", "b": "《诗·邶风·凯风》"}, {"t": "而圣君治国累世而不见者,其所谓忠者不忠,而所谓贤者不贤也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "圣功", "t": "神灵的功力"}, {"w": "圣子", "t": "超凡入圣的儿子"}, {"w": "圣意", "t": "神灵的旨意"}, {"w": "圣明", "t": "英明。"}]}, {"meaning": "聪明;才智胜人。", "cites": [{"t": "圣人莫之。", "b": "《诗·小雅·巧言》"}, {"t": "是故圣愈圣,愚益愚。", "b": "韩愈《师说》"}], "words": [{"w": "圣相", "t": "德智才能出众的宰相"}, {"w": "圣童", "t": "智力特优的儿童"}, {"w": "圣通", "t": "圣明通达"}, {"w": "圣智", "t": "亦作“圣知”。聪明睿智,无所不通"}, {"w": "圣善", "t": "聪明贤良"}, {"w": "圣时", "t": "圣明之时"}, {"w": "圣子", "t": "超凡入圣的儿子或登帝位的儿子。"}]}, {"meaning": "神圣的。封建时代称颂帝王或与帝王有关的事物之词。亦为宗教圣徒对所崇拜事物的尊称。", "cites": [{"t": "诚宜开张圣听,以光先帝遗德。", "b": "诸葛亮《出师表》"}], "words": [{"w": "圣虑", "t": "帝王的思虑"}, {"w": "圣裁", "t": "皇上的决定;皇帝的裁决"}, {"w": "圣治", "t": "皇帝的治理"}, {"w": "圣眷", "t": "皇帝的爱护"}, {"w": "圣聪", "t": "帝王的听闻"}, {"w": "圣朝无阙事", "t": "指当代朝廷没有过失"}, {"w": "圣寿节", "t": "皇帝诞辰纪念日"}, {"w": "圣眷隆重", "t": "皇帝的深切关怀"}, {"w": "圣驾", "t": "皇帝或临朝皇后的车乘"}, {"w": "圣鉴", "t": "指帝王或临朝太后的鉴察"}, {"w": "圣子神孙", "t": "称皇帝的子孙。"}]}, {"meaning": "圣人。指儒家所称道德智能极高超的理想人物。", "cites": [{"t": "或圣或否。", "b": "《诗·小雅·小宛》"}, {"t": "圣人之所以为圣,愚人之所以为愚,其皆出于此乎?", "b": "唐·韩愈《师说》"}, {"t": "积善成德,而神明自得,圣心备焉。", "b": "《荀子·劝学》"}], "words": [{"w": "圣曹", "t": "神圣之辈"}, {"w": "圣贤", "t": "指神佛"}, {"w": "圣讳", "t": "圣人的名讳"}, {"w": "圣经", "t": "圣人的经典"}, {"w": "圣文", "t": "指圣人的文章典籍"}, {"w": "圣心", "t": "圣人的心怀"}, {"w": "圣臣", "t": "指德行智能超群出众之臣"}, {"w": "圣法、圣制", "t": "古代圣人的法则"}, {"w": "圣则", "t": "圣人所定的法则"}, {"w": "圣轨", "t": "圣人的规范"}, {"w": "圣神", "t": "泛称古代的圣人。"}]}, {"meaning": "古之王天下者。亦为对于帝王或太后的极称。", "cites": [{"t": "是故有天下七十一圣,其法皆不同。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "圣父", "t": "对太上皇的尊称指上帝"}, {"w": "圣主", "t": "对当代皇帝的尊称"}, {"w": "圣帝", "t": "犹圣主、圣君"}, {"w": "圣皇", "t": "对皇帝的尊称"}, {"w": "圣国", "t": "称皇帝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('341wx','对','1','duì','寸','5','','[{"pinyin": "duì", "defs": [{"meaning": "(会意。从口,从“丵”(zhuó,即,古“丛”字,象草木丛生。),从寸。寸,法度也。汉文帝以为责对而伪,言多非诚,故去其口,以从土。本义:应答)。"}, {"meaning": "同本义。", "cites": [{"t": "对,答也。", "b": "《广韵》"}, {"t": "听言则对。", "b": "《诗·大雅·桑柔》"}, {"t": "叶公问孔子于子路,子路不对。", "b": "《论语·述而》"}, {"t": "唐且对曰:“臣未尝闻也。”", "b": ""}, {"t": "王语暴以好乐,暴未有以对也。", "b": "《孟子·梁惠王下》"}, {"t": "冠者对。", "b": "《仪礼·士冠礼》。注:“应也。”"}, {"t": "对曰:“非礼也敢辞。”", "b": "《仪礼·曲礼》。注:“答问也。”"}, {"t": "操唤杨修问之,修以鸡肋之意对。", "b": "《三国演义》"}], "words": [{"w": "无言以对;对当", "t": "对答;安排"}, {"w": "对嘴", "t": "争辩;争吵"}, {"w": "对理", "t": "讲理;对证"}, {"w": "对番", "t": "对证后理曲"}, {"w": "对状", "t": "受审问时答述案情"}, {"w": "对日", "t": "回答有关太阳问题的故事。"}]}, {"meaning": "两者相对;面对。", "cites": [{"t": "贼易之,对饮酒,醉。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "对食", "t": "面对食物;古时宫人相约为夫妇,称为对食"}, {"w": "对枰", "t": "下棋"}, {"w": "对峙", "t": "相对峙立"}, {"w": "对酒", "t": "面对着酒。饮酒"}, {"w": "对酌", "t": "相对饮酒"}, {"w": "对月", "t": "向月"}, {"w": "对向", "t": "应对趋走"}, {"w": "对床", "t": "两人对床而卧"}, {"w": "对棋", "t": "相对下棋"}, {"w": "对扬", "t": "面君奏对。"}]}, {"meaning": "相当;相配。", "cites": [{"t": "帝作邦作对。", "b": "《诗·大雅·皇矣》。注:“配也。”"}, {"t": "木大而茎叶格对。", "b": "《吕氏春秋·审时》。注:“等也。”"}], "words": [{"w": "对头亲", "t": "门当户对的亲事"}, {"w": "对头", "t": "适当的婚配;配偶;冤家;仇敌"}, {"w": "对时对景", "t": "正符合当时的情景、场合"}, {"w": "对合", "t": "利息和本钱相等"}, {"w": "对越", "t": "配称"}, {"w": "对坎儿", "t": "双方情况正好符合"}, {"w": "对治", "t": "相匹敌。"}]}, {"meaning": "核对,比照着检查。", "cites": [{"t": "以两司奏状对勘,以防虚伪。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "对读", "t": "校对"}, {"w": "对笔迹;对数字;对理", "t": "对质"}, {"w": "对保", "t": "出具书面保证后,向保证人核对以证明保证属实的一种手续。"}]}, {"meaning": "对待,以特定方式待。", "cites": [{"t": "夫一人奋死可以对十。", "b": "《韩非子·初见秦》"}], "words": [{"w": "他对我不错", "t": ""}]}, {"meaning": "扬;显扬;指扬威。", "cites": [{"t": "以对于天下。", "b": "《诗·大雅·皇矣》"}, {"t": "对扬以辟之。", "b": "《礼记·祭统》"}]}, {"meaning": "抵押。", "cites": [{"t": "我们围着庄子的这几块地,年终不是有二百多银子的租子吗?就把这个对给他,合他说明白了,按月计利,不论年份,银到归赎。", "b": "《儿女英雄传》"}]}, {"meaning": "朝着。", "cites": [{"t": "当窗理云鬓,对镜帖花黄。", "b": "《乐府诗集·木兰诗》"}, {"t": "对长亭晚,骤雨初歇。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "斜边对直角;弧对圆心角", "t": ""}]}, {"meaning": "配偶。", "cites": [{"t": "择对不嫁,至年三十。", "b": "《后汉书·逸民传·梁鸿》"}]}, {"meaning": "对手,敌对者。", "cites": [{"t": "而所与对敌,或值人杰。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "对儿", "t": "对手;对头。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('342wx','台','1','tāi tái','口','5','','[{"pinyin": "tāi", "defs": [{"meaning": "地名。“台州”的简称 。唐武德五年(公元622年),改海州为台州,以境内天台山得名,治所在今浙江省临海县。元改为路,明改为府。", "cites": [{"t": "南发交广东温台。", "b": "王安石《和王微之登高斋二首》"}]}]}, {"pinyin": "tái", "defs": [{"meaning": "(形声。小篆字形。从口,(以)声。从口,与表示喜悦有一定的联系。本义:喜悦。读(yí))。"}, {"meaning": "鱼名。背上有黑的花纹", "cites": [{"t": "黄台背,以引以翼。", "b": "《诗·大雅·行苇》"}]}, {"meaning": "(会意。从至,从之,从高省,与室屋同意。按积土四方高丈曰台,不方者曰观曰阙。本义:用土筑成的方形的高而平的建筑物)。"}, {"meaning": "同本义。", "cites": [{"t": "台,观四方而高者。", "b": "《说文》"}, {"t": "可以处台榭。", "b": "《礼记·月令》"}, {"t": "层台累榭,临高山些!", "b": "《楚辞·招魂》"}, {"t": "歌台暖响,春光融融。", "b": "杜牧《阿房宫赋》"}, {"t": "百年多病独登台。", "b": "杜甫《登高》"}, {"t": "多少楼台烟雨中。", "b": "唐·杜牧《江南春绝句》"}, {"t": "台阁相向。", "b": "唐·李朝威《柳毅传》"}, {"t": "守台军士。", "b": "《广东军务记》"}], "words": [{"w": "台门", "t": "古代诸侯所筑用来了望守卫的土堆高台"}, {"w": "台榭", "t": "垒土高起的平方地叫台,台上的亭子叫榭"}, {"w": "台阁", "t": "台榭楼阁"}, {"w": "台观", "t": "楼台宫观"}, {"w": "台下", "t": "台榭的下面"}, {"w": "台馆", "t": "楼台馆阁。"}]}, {"meaning": "站;单位。", "cites": [{"t": "今从宽将贾赦发往台站效力赎罪。", "b": "《红楼梦》"}], "words": [{"w": "气象台;电视台", "t": ""}]}, {"meaning": "敬辞。用于称呼对方或跟对方有关的行为。", "cites": [{"t": "台,侍也。", "b": "《广雅·释诂一》"}, {"t": "仆臣台。", "b": "《左传·昭公七年》。服注:“给台下征召也。”"}], "words": [{"w": "台讳", "t": "对人官名的尊称"}, {"w": "台坐", "t": "敬辞。坐于尊位"}, {"w": "台表", "t": "敬辞。用于称呼人的字"}, {"w": "兄台;台鉴", "t": "请对方阅览的敬词"}, {"w": "台屏", "t": "敬辞。尊称对方的家"}, {"w": "台甫", "t": "敬辞。旧时用于问人的表字"}, {"w": "台安", "t": "敬辞。多用于书信结尾,表示对收信人的问候"}, {"w": "台候", "t": "敬辞。用于问候对方寒暖起居"}, {"w": "台席", "t": "古以三公取象三台,故称宰相的职位为台席。"}]}, {"meaning": "莎草。", "cites": [{"t": "南山有台,北山有莱。", "b": "《诗·小雅·南山有台》"}]}, {"meaning": "古代中央官署名。", "cites": [{"t": "尚书初入台为郎中。", "b": "《汉官仪》"}, {"t": "台谒当以属礼。", "b": "清·张廷玉《明史》"}]}, {"meaning": "用于某些机器。 如: 一台车床; 一台拖拉机。"}, {"meaning": "台风的简称 。 如:请大家注意收听当地广播电台的天气预报,注意防台抗台。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('343wx','矛','1','máo','矛','5','','[{"pinyin": "máo", "defs": [{"meaning": "(象形。金文字形,是古代用来刺杀敌人的进攻性武器。本义:长矛) 同本义。", "cites": [{"t": "矛,酋矛也。建于兵车,长二丈,象形。", "b": "《说文》。按,矛者,刺兵也,其饰县毛羽,兵车左人持弓,右人持矛,中人御。又有夷矛者,长二丈四尺,兵车所不建,不常用。"}, {"t": "二矛重英。", "b": "《诗·郑风·清人》"}, {"t": "二矛重乔。", "b": ""}, {"t": "脩我戈矛。", "b": "《诗·秦风·无衣》"}, {"t": "进矛戟者。", "b": "《礼记·曲礼》"}, {"t": "操戈执矛。", "b": "《周书·王会》"}, {"t": "矛若林立。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "矛戈", "t": "矛与戈。攻击;指责"}, {"w": "矛弧", "t": "矛与弓。泛指凶器"}, {"w": "矛子", "t": "梭镖。装有长柄的双刃单尖刀"}, {"w": "矛戟", "t": "矛和戟。泛指兵器"}, {"w": "矛叉", "t": "月牙铲"}, {"w": "矛舛", "t": "矛盾,乖谬"}, {"w": "矛戟", "t": "矛盾。矛与盾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('344wx','纠','1','jiū','纟','5','','[{"pinyin": "jiū", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,丩(jiū)声。本义:三股的绳子)。"}, {"meaning": "同本义。", "cites": [{"t": "纠,绳三合也。", "b": "《说文》。按,俗字作糺。单股曰纫,两股曰纠,三股曰纠,亦曰徽。”"}, {"t": "徽以纠墨。", "b": "扬雄《解嘲》"}], "words": [{"w": "纠纆", "t": "绳索。纠,二合绳;纆,三合绳。"}]}, {"meaning": "缠绕。", "cites": [{"t": "其笠伊纠。", "b": "《诗·周颂·良耜》"}, {"t": "何异纠纆。", "b": "《汉书·贾谊传》。注:“绞也。”"}, {"t": "青纶竞纠。", "b": "郭璞《江赋》"}, {"t": "纠思心以为纕兮。", "b": "《楚辞·悲风歌》。注:“戾也。”"}, {"t": "横厉纠纷。", "b": "《后汉书·刘琨传》。注:“乱貌。”"}, {"t": "福与祸如纠缠。", "b": "《鶡冠子》"}], "words": [{"w": "纠蓼", "t": "互相牵引"}, {"w": "纠结", "t": "连结"}, {"w": "纠纠", "t": "缠绕的样子"}, {"w": "纠曲", "t": "纠结盘曲。"}]}, {"meaning": "纠集;集结。", "cites": [{"t": "纠合宗族于成周。", "b": "《左传·僖公二十四年》"}, {"t": "收离糺散。", "b": "《后汉书·荀彧传》。注:“合也。”"}, {"t": "纠合俊杰披奸猖。", "b": "王安石《开元行》"}], "words": [{"w": "纠办", "t": "收集,备办"}, {"w": "纠合", "t": "联络,联合"}, {"w": "纠勒", "t": "聚集统率"}, {"w": "纠会", "t": "会合"}, {"w": "纠约", "t": "纠合约集。"}]}, {"meaning": "矫正。", "cites": [{"t": "以纠邦国。", "b": "《周礼·大司马》。注:“犹正也。”"}, {"t": "慢则纠之以猛。", "b": "《左传·昭公二十年》"}, {"t": "纠之以政。", "b": "《左传》"}], "words": [{"w": "纠劾", "t": "审查,弹劾"}, {"w": "纠举", "t": "纠正举发"}, {"w": "纠谬", "t": "纠正错误"}, {"w": "纠绳", "t": "纠正惩处"}, {"w": "纠错", "t": "纠正错误。"}]}, {"meaning": "督察。", "cites": [{"t": "以五刑纠万民。", "b": "《周礼·大司寇》"}, {"t": "凡宫之纠禁。", "b": "《周礼·小宰》"}, {"t": "贪利纠譑之名。", "b": "《荀子·富国》"}], "words": [{"w": "纠弹", "t": "纠察弹劾"}, {"w": "纠案", "t": "检举监察"}, {"w": "纠发", "t": "纠察举发"}, {"w": "纠逖", "t": "督察惩治。"}]}, {"meaning": "检举。", "cites": [{"t": "纠之以政。", "b": "《左传·昭公六年》。注:“举也。”"}, {"t": "恐见纠擿。", "b": "《明史》"}, {"t": "访缉纠诘。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "纠拾", "t": "揭发检举"}, {"w": "纠问", "t": "纠举问罪"}, {"w": "纠发", "t": "举发"}, {"w": "纠慝", "t": "惩处邪恶"}, {"w": "纠驳", "t": "纠举驳正。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('345wx','母','1','mǔ','母','5','','[{"pinyin": "mǔ", "defs": [{"meaning": "(象形。甲骨文字形,象母亲有乳之形。本义:母亲)。"}, {"meaning": "同本义。", "cites": [{"t": "母,牧也。从女。象怀子形,一曰,象乳子也。", "b": "《说文》"}, {"t": "母其中有两点,象人乳形。", "b": "《苍颉篇》"}, {"t": "坤为母。晋,受兹介福,于其王母。", "b": "《易·说卦》"}, {"t": "生曰父曰母,死曰考曰妣。", "b": "《礼记·曲礼》"}, {"t": "有孙母未出,出入无完裙。", "b": "杜甫《石壕吏》"}], "words": [{"w": "母难", "t": "生日。意为孩子出生时母亲要受难"}, {"w": "母以子贵", "t": "母亲因儿子居官而显贵"}, {"w": "母子", "t": "母亲和儿子"}, {"w": "母族", "t": "母亲之亲族"}, {"w": "母道", "t": "为母之道。"}]}, {"meaning": "本源。", "cites": [{"t": "以为天下母。", "b": "《老子》。注:“本也。”"}], "words": [{"w": "酒母;字母;工作母机;母财", "t": "资本"}, {"w": "母金", "t": "本金,本钱。"}]}, {"meaning": "女师。古时以妇道教子女的女教师。", "cites": [{"t": "妇人夜出不见傅母不下堂。", "b": "《公羊传·襄公三十年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('346wx','幼','1','yòu','幺','5','','[{"pinyin": "yòu", "defs": [{"meaning": "(会意。从幺(yāo),从力。幺,小。年幼力小。本义:幼小) 同本义。", "cites": [{"t": "幼,小也。", "b": "《说文》"}, {"t": "幼,稀也。", "b": "《尔雅》"}, {"t": "人生十年曰幼。", "b": "《礼记·曲礼》"}, {"t": "子幼。", "b": "《仪礼·丧服》。注:“谓年十五以下。”"}, {"t": "慈幼为其近于子也。", "b": "《礼记·祭义》"}, {"t": "幼原耳。", "b": "唐·柳宗元《童区寄传》"}, {"t": "吾幼且少。", "b": "唐·柳宗元《柳河东集》"}, {"t": "自幼好武术。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "余幼好书。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "幼主", "t": "年幼的君主"}, {"w": "幼少", "t": "幼小"}, {"w": "幼志", "t": "幼年时的志向"}, {"w": "幼君", "t": "年幼的君主"}, {"w": "幼孤", "t": "年幼的孤儿"}, {"w": "幼累", "t": "指年幼的儿女"}, {"w": "幼蒙", "t": "年幼"}, {"w": "幼愿", "t": "年幼而谨慎老实"}, {"w": "幼龄", "t": "幼年"}, {"w": "幼碎", "t": "幼弱"}, {"w": "幼学", "t": "幼时的学业"}, {"w": "幼虫", "t": ""}]}, {"meaning": "小孩儿。", "cites": [{"t": "携幼入室。", "b": "陶潜《归去来兮辞》"}, {"t": "扶老携幼。", "b": "明·归有光《项脊轩志》"}, {"t": "幼吾幼以及人之幼,老吾老以及人之老。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "幼壮", "t": "青少年时期"}, {"w": "幼科", "t": "中医指小儿科,也叫“小方脉科”"}, {"w": "幼妇", "t": "少女。借指“妙”字"}, {"w": "幼孺", "t": "孩童。"}]}, {"meaning": "爱护。", "cites": [{"t": "幼吾幼,以及人之幼。", "b": "《孟子》。赵岐注:“幼,犹爱也。”"}, {"t": "幼幼长长,顺天则也。", "b": "明·刘基《沙班子中兴义塾诗》序"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('347wx','丝','1','sī','一','5','','[{"pinyin": "sī", "defs": [{"meaning": "(会意。从二糸。糸(mì),细丝。本义:蚕丝)。"}, {"meaning": "同本义。", "cites": [{"t": "丝,蚕所吐也。", "b": "《说文》。段注:“凡蚕者为丝、麻者为缕。”"}, {"t": "素丝五总。", "b": "《诗·召南·羔羊》"}, {"t": "金石丝竹,乐之器也。谓弦也。”", "b": "《礼记·乐记》"}, {"t": "山东多鱼盐漆丝声色。", "b": "《史记·货殖列传序》"}, {"t": "此织生于蚕茧,成于机杼。一丝而累,以至于寸。", "b": "《后汉书·列女传》"}, {"t": "春蚕到死丝方尽,蜡炬成灰泪始干。", "b": "李商隐《无题》"}, {"t": "二月卖新丝,五月粜新谷。", "b": "聂夷中《咏田家》"}, {"t": "缯帛如山积,丝絮似云屯。", "b": "唐·白居易《重赋》"}], "words": [{"w": "丝棉;丝网;丝缰", "t": "丝制的马缰绳"}, {"w": "丝人", "t": "治理蚕丝纺织绸布的人"}, {"w": "丝布", "t": "蚕丝与麻、葛混制而成的布"}, {"w": "丝妇", "t": "养蚕治丝的妇女"}, {"w": "丝子", "t": "蚕丝"}, {"w": "丝行", "t": "买卖生丝的商行"}, {"w": "丝庄", "t": "旧时在华商与洋商间经营生丝贸易的中间商。"}]}, {"meaning": "泛指纤细如丝的东西。", "cites": [{"t": "五原春色旧来迟,二月垂杨未挂丝。", "b": "唐·张敬忠《边词》"}], "words": [{"w": "藕丝", "t": "莲藕切开后连于两断之间的丝状物"}, {"w": "丝柳", "t": "细柔如丝的柳条"}, {"w": "丝条", "t": "纤细的枝条"}, {"w": "丝雨", "t": "如丝的小雨。俗称“毛毛雨”"}, {"w": "丝状", "t": "矿物学名,指一种矿物具有丝状的结晶"}, {"w": "丝泪", "t": "形容泪下如丝"}, {"w": "丝络", "t": "连续不断"}, {"w": "丝网", "t": "细密如丝之物所交织而成的网"}, {"w": "丝纶", "t": "钓鱼用的丝线"}, {"w": "丝发", "t": "形容头发光泽柔细,如丝一样。"}]}, {"meaning": "线。", "cites": [{"t": "青丝为笼系,桂枝为笼钩。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "丝鞭", "t": "用丝线裹制的软鞭。古代招亲,男女双方递送丝鞭,表示缔结良缘"}, {"w": "丝络", "t": "丝线制成的网状装饰物"}, {"w": "丝缕", "t": "蚕丝、线缕之类的统称。"}]}, {"meaning": "丝织品。", "cites": [{"t": "足下蹑丝履,头上玳瑁光。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "丝纶", "t": "皇帝的诏书"}, {"w": "丝枲", "t": "丝麻织物。泛指布匹绸缎。枲:大麻的雄株"}, {"w": "丝衣", "t": "丝绸衣服"}, {"w": "丝末", "t": "古代覆盖在车轼上的丝织帷席"}, {"w": "丝帛", "t": "丝与丝状物的总称"}, {"w": "丝履", "t": "以丝织品制成的鞋"}, {"w": "丝鞭", "t": "丝制的马鞭"}, {"w": "丝罗", "t": "丝织物名。质地轻软,透气透光性能较好。"}]}, {"meaning": "八音之一。指琴、瑟、琵琶等弦乐器。", "cites": [{"t": "宴酣之乐,非丝非竹。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "浔阳地僻无音乐,终岁不闻丝竹声。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "丝中传意绪,花里寄春情。", "b": "《玉台新咏·王融咏琵琶》"}], "words": [{"w": "丝抹", "t": "古代御宴之乐,先演奏丝乐,然后众乐皆作,演者因称为丝抹"}, {"w": "丝簧", "t": "弦管乐器"}, {"w": "丝镛", "t": "泛指琴瑟钟磬之类的乐器"}, {"w": "丝竹会", "t": "有丝竹弹奏以助兴的聚会"}, {"w": "丝桐", "t": "琴,古代制琴多用桐木,练丝为弦,故称之"}, {"w": "丝管", "t": "琴瑟、箫、管类乐器"}, {"w": "丝篁", "t": "丝弦乐器和竹管乐器"}, {"w": "丝竹和鸣", "t": "音乐演奏的声音非常和谐。"}]}, {"meaning": "比喻极细微的东西。", "cites": [{"t": "见客卧地上,烛之死,然心下丝丝有动气。", "b": "《聊斋志异·尸变》"}], "words": [{"w": "丝丝两气", "t": "形容呼吸微弱,气息奄奄"}, {"w": "丝麻线儿", "t": "些微私弊"}, {"w": "丝肠", "t": "指细柔的肠子"}, {"w": "一丝不差;丝毫不差;一丝风;丝发", "t": "丝与发,比喻极细微。"}]}, {"meaning": "缫丝;纺丝。", "cites": [{"t": "男谷女丝行复歌。", "b": "杜甫《蚕谷行》"}], "words": [{"w": "丝车", "t": "人力或机动的缫丝机具"}, {"w": "丝枲", "t": "指缫丝织麻之事"}, {"w": "丝绝", "t": "指丝织之绝技。"}]}, {"meaning": "一种计算长度、容量和重量的微小单位。"}, {"meaning": "长度或重量的微量。十忽为一丝,十丝为一毫。", "cites": [{"t": "至于分粟叅黍量丝数龠,实以仰禀圣规,详参神恩。", "b": "北周·庾信《为晋阳公进玉律秤尺斗升表》"}]}, {"meaning": "表示极小或极少的量。", "cites": [{"t": "是芙蕖也者,无一时一刻不适耳目之观,无一物一丝不备家常之用者也。", "b": "明·李渔《闲情偶寄·种植部》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('348wx','邦','1','bāng','阝','6','','[{"pinyin": "bāng", "defs": [{"meaning": "(形声。从邑,丰声。古文从之、从田,会意。与封字从之、从土同意。本义:古代诸侯的封国、国家)。"}, {"meaning": "同本义。", "cites": [{"t": "邦,国也。", "b": "《说文》。段注:“邦之言封也。古邦封通用。书序云:‘邦康叔,邦诸侯。’论语云:‘在邦域之中’。皆封字也。”"}, {"t": "大宰之职,掌建邦之六典。", "b": "《周礼·天官·大宰》"}, {"t": "以佐王治邦国。", "b": "《周礼·天官·大宰》。注:“大曰邦,小曰国,邦之所居亦曰国。”按,散文邦国亦通。"}, {"t": "利用为依迁邦。", "b": "《易·益》"}, {"t": "协和万邦。", "b": "《书·尧典》"}, {"t": "以畜万邦。", "b": "《诗·小雅·节南山》"}, {"t": "后非众罔与守邦。", "b": "《国语·周语》"}]}, {"meaning": "汉避高祖讳,多以国易之。", "cites": [{"t": "且在邦域之中矣。", "b": "《论语·季氏》"}, {"t": "而谋动干戈于邦内。", "b": ""}, {"t": "民惟邦本,本固邦宁。", "b": "《书·五子之歌》"}, {"t": "及公子返晋邦、瘵兵伐郑,大破之。", "b": "《韩非子·喻老》"}, {"t": "夫子至于是邦也,必闻其政。", "b": "《论语·学而》"}], "words": [{"w": "邦畿", "t": "古代指直属于天子的地方"}, {"w": "邦家", "t": "诸侯的封国和大夫之家"}, {"w": "邦国", "t": "诸侯的封国。大的叫邦,小的叫国,后泛指国家。"}]}, {"meaning": "泛指国家。", "cites": [{"t": "姬汉旧邦,无取杂种。", "b": "南朝齐·丘迟《与陈伯之书》"}, {"t": "刑于寡妻,至于兄弟,以御(治)于家邦。", "b": "《孟子·梁惠王上》"}, {"t": "唯求则非邦也与?", "b": "《论语·先进》"}], "words": [{"w": "邻邦;盟邦;邦典", "t": "国家的法令制度。"}]}, {"meaning": "国都,大城镇。", "cites": [{"t": "逼迫迁旧邦,拥王以自疆。", "b": "《悲愤诗》"}]}, {"meaning": "泛指地方。", "cites": [{"t": "负海之邦,交趾之土,谓之南裔。", "b": "《博物志》"}]}, {"meaning": "封,分封。", "cites": [{"t": "设五等,邦群后。", "b": "柳宗元《封建论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('349wx','式','1','shì','弋','6','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从工,弋(yì)声。工有“矩”的意思。本义:法度;规矩)。"}, {"meaning": "同本义。", "cites": [{"t": "式,法也。", "b": "《说文》"}, {"t": "式,法也。", "b": "《周书·谥法》"}, {"t": "下士之式。", "b": "《诗·大雅·下武》。传:“法也。”"}, {"t": "三曰筮式。", "b": "《周礼·篔人》。注:“谓筮制作法式也。”"}, {"t": "掌妇式之法。", "b": "《周礼·典妇功》"}, {"t": "九式。", "b": "《周礼·太宰》。注:“谓用财之节度。”"}], "words": [{"w": "式度", "t": "规制,法式"}, {"w": "式则", "t": "法则;规范。"}]}, {"meaning": "榜样;楷模。", "cites": [{"t": "世世享德,百邦作式。", "b": "《书·微子之命》"}, {"t": "孝敬之准式。", "b": "箫统《文选序》"}, {"t": "式箕之门。", "b": "《汉书·韩良传》。注:“亦表也。”"}], "words": [{"w": "式范", "t": "模范,楷模。"}]}, {"meaning": "规格;样式。", "cites": [{"t": "正以音律调韵,取高前式。", "b": "沈约《谢灵运传论》"}], "words": [{"w": "新式;旧式;式盘", "t": "中国古代推“算”历数或占卜的工具。分天地盘。天盘为圆形,地盘为正方形。"}]}, {"meaning": "效法。", "cites": [{"t": "仪式刑文王之典。", "b": "《诗·周颂·我将》"}, {"t": "使诸大夫国人皆有所矜式。", "b": "《孟子·公孙丑下》"}, {"t": "使人主师五帝而式三王。", "b": "《后汉书·崔寔传》"}], "words": [{"w": "式型", "t": "效法,取法"}, {"w": "式瞻", "t": "敬仰,景慕。"}]}, {"meaning": "示范,作为榜样。", "cites": [{"t": "王命申伯,式是南邦。", "b": "《诗·大雅·崧高》"}], "words": [{"w": "示规", "t": "示范"}, {"w": "示望", "t": "仰望"}, {"w": "式慰", "t": "安慰"}, {"w": "式好", "t": "兄弟和好。"}]}, {"meaning": "使用。", "cites": [{"t": "神之听之,式榖以女。", "b": "《诗·小雅·小明》。郑玄《笺》:式,用;榖,善也。其用善人,则必用女。女,通“汝”。"}, {"t": "蛮夷戎狄,不式王命。", "b": "《左传·成公二年》"}, {"t": "不闻亦式。", "b": "《诗·大雅·思齐》"}, {"t": "式礼采,垂衣裳,以禁争夺。", "b": "《孙膑兵法·见威王》"}], "words": [{"w": "式昭", "t": "用以光大。"}]}, {"meaning": "以手抚轼,为古人表示尊敬的礼节。", "cites": [{"t": "释箕子囚,封比干墓,式商容闾。", "b": "《书·武成》"}, {"t": "一在前,二在后,以揉其式。", "b": "《周礼·考工记·舆人》"}, {"t": "天子为动,改容式车。", "b": "《史记·绛侯周勃世家》"}], "words": [{"w": "式式", "t": "恭整的样子"}, {"w": "式闾", "t": "礼敬贤人"}, {"w": "式路马", "t": "见路马则抚轼,以示崇敬。"}]}, {"meaning": "句首语气词。无实义。", "cites": [{"t": "兄及弟矣,式相好矣!", "b": "《诗·小雅·斯干》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('350wx','迂','1','yū','辶','6','','[{"pinyin": "yū", "defs": [{"meaning": "(形声。从辵(chuò),于声。本义:曲折,绕远)。"}, {"meaning": "同本义。", "cites": [{"t": "迂,僻也。", "b": "《说文》。按,僻远也。"}, {"t": "迂乃心。", "b": "《书·盘庚》。传:“僻也。”"}, {"t": "子之迂也。", "b": "《论语》。皇疏:“远也。”"}, {"t": "彼岂乐为迂阔哉。", "b": "班固《答宾戏》"}, {"t": "寡人以为迂言也。”", "b": "《吕氏春秋·先已》"}, {"t": "却霍见其语迂。", "b": "《国语·周语》。注:“迂回加诬于人。”"}, {"t": "迂,曲也。", "b": "《后汉书·蔡邕传》注"}, {"t": "惩山北之塞,出入之迂也。", "b": "《列子·汤问》"}], "words": [{"w": "迂直", "t": "虽迂曲却是最直接有利的"}, {"w": "迂折", "t": "迂回曲折"}, {"w": "迂弘", "t": "深远宏大"}, {"w": "迂邈", "t": "遥远"}, {"w": "迂路", "t": "绕路"}, {"w": "迂深", "t": "深远"}, {"w": "迂言", "t": "迂阔的言辞"}, {"w": "迂僻", "t": "偏僻"}, {"w": "迂狂", "t": "迂阔狂放"}, {"w": "迂谈", "t": "迂阔的谈论"}, {"w": "迂傲", "t": "迂阔而高傲。"}]}, {"meaning": "迂腐,不合事理。", "cites": [{"t": "迂儒之议。", "b": "宋·苏轼《教战守》"}, {"t": "厌其为迂。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "迂妄", "t": "荒诞,不合情理"}, {"w": "迂小", "t": "腐迂渺小"}, {"w": "迂板", "t": "迂腐古板"}, {"w": "迂癖", "t": "迂诞古怪"}, {"w": "迂僻", "t": "迂诞怪僻,不合情理"}, {"w": "迂呆", "t": "迂拙愚笨"}, {"w": "迂谬", "t": "迂腐荒谬"}, {"w": "迂薄", "t": "迂腐浅薄。"}]}, {"meaning": "邪避,不正。", "cites": [{"t": "不度而迂求。", "b": "《国语·晋语》。注:“邪也。”"}], "words": [{"w": "迂邪", "t": "邪避。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('351wx','刑','1','xíng','刂','6','','[{"pinyin": "xíng", "defs": [{"meaning": "同本义。", "cites": [{"t": "利用刑人。", "b": "《易·蒙》。注:“兑折为刑。”"}, {"t": "刑人之父子也。", "b": "《吕氏春秋·顺说》。注:“杀也。”"}, {"t": "杀戮之谓刑。", "b": "《韩非子·二柄》"}, {"t": "阴为刑。", "b": "《易·本命》"}, {"t": "阴将始刑。", "b": "《吕氏春秋·音律》。注:“杀也。”"}, {"t": "刑人如恐不胜。", "b": "《史记·项羽本纪》"}, {"t": "刑马作誓。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "膑至,庞涓恐其贤于己,疾之,则以法刑断其两足而黥之。", "b": "《史记》"}], "words": [{"w": "刑牛", "t": "古代盟誓时作牺牲用的牛"}, {"w": "刑牲", "t": "古时为了祭祀或盟约而杀牲畜"}, {"w": "刑马", "t": "古代结盟要杀马歃血,立誓为信,称“刑马”。"}]}, {"meaning": "惩罚。", "cites": [{"t": "刑其长吏。", "b": "《史记·陈涉世家》"}, {"t": "五人之当刑。", "b": "明·张溥《五人墓碑记》"}, {"t": "彼于刑者。", "b": "清·方苞《狱中杂记》"}, {"t": "从而刑之。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "刑吏", "t": "行刑的吏卒"}, {"w": "刑民", "t": "受刑之民"}, {"w": "刑臣", "t": "古时指受过宫刑的阉人。即后来的宦官,太监。"}]}, {"meaning": "形容,形体。", "cites": [{"t": "死生因天地之刑。", "b": "《国语·越语》"}, {"t": "夫諒彊之国,必先争谋、争刑、争权。", "b": "《管子·霸言》"}, {"t": "凡乱者刑名不当也。", "b": "《吕氏春秋·正名》"}]}, {"meaning": "法式,典范,榜样。", "cites": [{"t": "刑于寡妻。", "b": "《孟子·梁惠王上》"}, {"t": "仪式刑文王之典,日靖四方。", "b": "《诗·周颂·我将》"}, {"t": "贱有实,敬无用,则人可刑也。", "b": "《管子·侈靡》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('352wx','戎','1','róng','戈','6','','[{"pinyin": "róng", "defs": [{"meaning": "(会意。从戈,从十。“戈”是兵器,“十”是铠甲的“甲”。本义:古代兵器的总称。弓、殳、矛、戈、戟为古代五戎)。"}, {"meaning": "同本义。", "cites": [{"t": "戎,兵也。", "b": "《说文》"}, {"t": "以习五戎。", "b": "《礼记·月令》"}, {"t": "戎器不粥于市。", "b": "《礼记·王制》。注:“军器也。”"}, {"t": "伏戎于莽。", "b": "《易·同人》"}, {"t": "弓矢戎兵。", "b": "《诗·大雅·抑》"}], "words": [{"w": "戎仗", "t": "兵器,军械"}, {"w": "戎器", "t": "兵器"}, {"w": "戎储", "t": "兵器储备"}, {"w": "戎钺", "t": "泛指兵器。钺,古兵器名"}, {"w": "戎具", "t": "兵器。"}]}, {"meaning": "兵车。", "cites": [{"t": "元戎十乘。", "b": "《诗·小雅·六月》。传:夏曰钩车,殷曰寅车,周曰元戎。"}, {"t": "梁弘御戎。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "元戎", "t": "大战车"}, {"w": "戎御", "t": "兵车的驾御者"}, {"w": "戎轸", "t": "兵车"}, {"w": "戎轩", "t": "兵车"}, {"w": "戎路", "t": "古代帝王军中所乘的车。"}]}, {"meaning": "军队。", "cites": [{"t": "戎右少师。", "b": "《左传·桓公七年》。注;“军右也。”"}, {"t": "以脩我戎。", "b": "《诗·大雅·常武》"}], "words": [{"w": "投笔从戎;戎士", "t": "将士;兵士"}, {"w": "戎级", "t": "军职"}, {"w": "戎帅", "t": "军队的统帅"}, {"w": "戎重", "t": "军事重任"}, {"w": "戎威", "t": "军威"}, {"w": "戎柄", "t": "军权"}, {"w": "戎门", "t": "军门"}, {"w": "戎政", "t": "军政"}, {"w": "戎戍", "t": "行伍,军队"}, {"w": "戎略", "t": "军事谋略"}, {"w": "戎寄", "t": "军事任务"}, {"w": "戎兵", "t": "军服和兵器。"}]}, {"meaning": "战争。敌对双方的军事行动。", "cites": [{"t": "戎成不退。", "b": "《诗·小雅·雨无止》"}], "words": [{"w": "戎舰", "t": "战船"}, {"w": "戎烬", "t": "遭受战火的破坏"}, {"w": "戎缮", "t": "备战与修缮宫室之事"}, {"w": "戎场", "t": "战场"}, {"w": "戎戒", "t": "战备"}, {"w": "戎捷", "t": "战利品。"}]}, {"meaning": "戎羌,中国古代称西部民族。", "cites": [{"t": "西和诸戎。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "戎狄", "t": "西戎和北狄"}, {"w": "戎羌", "t": "借指我国少数民族地区"}, {"w": "戎荒,戎落", "t": "戎族聚居地"}, {"w": "戎骑", "t": "戎族的军队"}, {"w": "戎羯", "t": "戎和羯"}, {"w": "戎虏", "t": "古时对西方或北方少数名族的蔑称。"}]}, {"meaning": "兵士。", "cites": [{"t": "必有女戎。", "b": "《国语·晋语》"}], "words": [{"w": "戎卫", "t": "禁卫之兵"}, {"w": "戎符", "t": "兵符。引申指兵权"}, {"w": "戎经", "t": "兵书"}, {"w": "戎卒", "t": "兵士"}, {"w": "戎章", "t": "兵法,兵书"}, {"w": "戎号", "t": "武官品级"}, {"w": "戎禁", "t": "禁卫。"}]}, {"meaning": "敌寇。", "cites": [{"t": "戎者,兵也。…引申之,凡持兵器以侵盗者亦谓之戎。", "b": "王国维《观堂集林》"}]}, {"meaning": "古国名 。故地在今山东省曹县东南。", "cites": [{"t": "公会戎于潜。", "b": "《春秋》"}]}, {"meaning": "征伐;进行武装的敌对行动。", "cites": [{"t": "毋为戎首,不亦善乎?又何反服之礼之有?", "b": "《礼记·檀弓》"}], "words": [{"w": "戎心", "t": "征伐的意图"}, {"w": "戎首", "t": "攻伐的谋主。"}]}, {"meaning": "拔除。", "cites": [{"t": "戎,拔也。", "b": "《方言》"}]}, {"meaning": "假借为“从”。相助。"}, {"meaning": "假借为“崇”。大。", "cites": [{"t": "念兹戎功。", "b": "《诗·周颂·烈文》"}], "words": [{"w": "戎功", "t": "大功"}, {"w": "戎弓", "t": "大弓"}, {"w": "戎丑", "t": "大众"}, {"w": "戎疾", "t": "大害,大难。"}]}, {"meaning": "表示第二人称,相当于“你”、“你们”。", "cites": [{"t": "戎虽小子,而式弘大。", "b": "《诗·大雅·民劳》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('353wx','动','1','dòng','力','6','','[{"pinyin": "dòng", "defs": [{"meaning": "(形声。从力,重声。《说文》古文从“辵”。本义:行动;发作)。"}, {"meaning": "同本义。", "cites": [{"t": "动,作也。", "b": "《说文》"}, {"t": "动而健。", "b": "《易·彖传》。虞注:“震也。”"}, {"t": "效天下之动者也。", "b": "《易·系辞》。虞注:“发也,变动不居。”"}, {"t": "将终岁勤动。", "b": "《孟子》。注:“作也。”"}, {"t": "度义而后动。", "b": "宋·王安石《答司马谏议书》"}, {"t": "寨中人蜷伏不少动。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "按兵不动;动着", "t": "开始下棋"}, {"w": "动止", "t": "行动和静止;训练调度"}, {"w": "动烦", "t": "爆发战乱"}, {"w": "动转", "t": "行动,活动。"}]}, {"meaning": "摇动,震动,移动。与“静”相对。", "cites": [{"t": "风移影动。", "b": "明·归有光《项脊轩志》"}, {"t": "秋风之动容兮。", "b": "《楚辞·抽思》"}, {"t": "物莫之能动。", "b": "《吕氏春秋·论威》"}, {"t": "夜间,大鱼动。", "b": "《韩非子·内储说上》"}], "words": [{"w": "动耽", "t": "动弹"}, {"w": "动履", "t": "走动"}, {"w": "动展", "t": "伸展;活动"}, {"w": "动息", "t": "动静;消息"}, {"w": "动惮", "t": "动静"}, {"w": "动程", "t": "动身;起程"}, {"w": "风吹草动;别动人家的东西;振动;活动;动起", "t": "方言。动不动"}, {"w": "动移", "t": "移动"}, {"w": "动步", "t": "迈步前行"}, {"w": "动不得;不能动", "t": ""}]}, {"meaning": "动摇;震撼。", "cites": [{"t": "忽魂悸以魄动,恍惊起而长嗟。", "b": "李白《梦游天姥呤留别》"}, {"t": "所以动心忍性,曾益其所不能。", "b": "《孟子·告子下》"}, {"t": "风雨不动安如山。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "触动感应;感动。", "cites": [{"t": "明则动。", "b": "《礼记·中庸》。注:“动,动人心也。”"}, {"t": "乡园多故,不能不动客子之愁。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "动性", "t": "动心"}, {"w": "动心", "t": "遇事而心志动摇;感动人心。"}]}, {"meaning": "萌动。", "cites": [{"t": "春气动,鲜不疫矣。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "做;操作;劳作。", "words": [{"w": "动作", "t": "劳动;耕作"}, {"w": "动乖", "t": "动不动就违反"}, {"w": "动事", "t": "兴办事业;日常应用的器具。"}]}, {"meaning": "动不动,常常。", "cites": [{"t": "曹公,豺虎也,挟天子以征四方,动以朝廷为辞。", "b": "《资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('354wx','扛','1','gāng káng','扌','6','','[{"pinyin": "gāng", "defs": [{"meaning": "用两手举重物。", "cites": [{"t": "扛,横关对举也。", "b": "《说文》。字亦作掆."}, {"t": "两人对举为扛。", "b": "《后汉书·费长房传》注"}, {"t": "翘关扛鼎。", "b": "左思《吴都赋》"}, {"t": "扛,举也。", "b": "《广雅》"}, {"t": "力能扛鼎,才气过人。", "b": "《史记·项羽本纪》"}], "words": [{"w": "扛鼎", "t": "举鼎"}, {"w": "扛舁", "t": "举抬。"}]}, {"meaning": "横架。", "cites": [{"t": "这时城门已经上了大铁锁,扛了大木闩。", "b": "李连璧《古城怒火》"}]}, {"meaning": "顶撞;抬杠。", "cites": [{"t": "呆子慌了,往山坡下筑了有三尺深,下面都是石脚石根,扛住钯齿。", "b": "《西游记》"}]}]}, {"pinyin": "káng", "defs": [{"meaning": "(形声。从手,工声。(gāng)本义:两手对举以托重物)。"}, {"meaning": "用肩部携带。", "cites": [{"t": "役使扛炮。", "b": "《广东军务记》"}], "words": [{"w": "码头装卸工人的肩上扛着大包;扛荷", "t": "肩抬"}, {"w": "扛抬", "t": "共同用手或肩膀搬东西"}, {"w": "扛枪;扛锄头", "t": ""}]}, {"meaning": "用言语顶撞。", "cites": [{"t": "你讨得头钱,分与那个一分儿使也怎的?交我扛了两句,走出来。", "b": "《金瓶梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('355wx','寺','1','sì','寸','6','','[{"pinyin": "sì", "defs": [{"meaning": "同本义。", "cites": [{"t": "寺,廷也,有法度者也。", "b": "《说文》"}, {"t": "寺,治也,官舍也。", "b": "《一切经音义》"}, {"t": "寺,官舍也。", "b": "《三苍 》"}, {"t": "寺,官也。", "b": "《广雅》。按,朝中官曹所止理事之处。"}, {"t": "令骑奴还至寺门。", "b": "《汉书·何竝传》。注:“诸官曹之所,通呼为寺。”"}, {"t": "城郭官寺。", "b": "《汉书·元帝纪》。注:“凡府廷所在,皆谓之寺。”"}, {"t": "列寺七里。", "b": "左思《吴都赋》"}], "words": [{"w": "寺正", "t": "大理寺正卿的略称"}, {"w": "寺舍", "t": "官舍。官署办公的房子;佛教僧侣的房舍"}, {"w": "寺库", "t": "古时寺观里设的当铺"}, {"w": "寺省", "t": "古时中央行政机构“省”和“寺”的合称"}, {"w": "寺曹", "t": "九卿官署"}, {"w": "寺署", "t": "官署"}, {"w": "寺卿", "t": "九寺大卿的简称"}, {"w": "寺棘", "t": "大理寺的别称"}, {"w": "寺丞", "t": "官署中的佐吏。"}]}, {"meaning": "佛教的庙宇。", "cites": [{"t": "寺,汉西域白马驼经来,初止于鸿胪寺,遂取寺名,创置白马寺。", "b": "《广韵》"}, {"t": "南朝四百八十寺,多少楼台烟雨中。", "b": "杜牧《江南春绝句》"}, {"t": "五里,至汤寺,浴于汤池。", "b": "《徐霞客游记·游黄山记》"}, {"t": "孤山寺北贾亭西,水面初平云脚低。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "左忠毅公视学京畿,一日,风雪严寒,从数骑出,微行入古寺。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "寺宇", "t": "寺院"}, {"w": "寺刹", "t": "寺和塔"}, {"w": "寺主", "t": "主管佛寺事务的僧人"}, {"w": "寺庵", "t": "僧和尼所居的寺庙"}, {"w": "寺寝", "t": "祠庙的后殿。"}]}, {"meaning": "奄人,内监。古代皇宫内供使令的小臣。", "cites": [{"t": "未见君子,寺人之令。", "b": "《诗·秦风·车邻》"}, {"t": "匪教匪诲,时维妇寺。", "b": "《诗·大雅·瞻卬》"}, {"t": "齐寺人貂。", "b": "《左传·僖公二年》"}, {"t": "阍,门者也,寺人也。", "b": "《谷梁传·襄公二十九年》"}], "words": [{"w": "寺人", "t": "太监,古代宫内供使的小臣,东汉后专指宦官。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('356wx','吉','1','jí','口','6','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。甲骨文字形,上象兵器,下象盛放兵器的器具。合起来表示把兵器盛放在器中不用,以减少战争,使人民没有危难。本义:吉祥;吉利)。"}, {"meaning": "同本义。", "cites": [{"t": "吉,善也。", "b": "《说文》"}, {"t": "礼义顺祥曰吉。", "b": "《周书·武顺》"}, {"t": "安贞吉。", "b": "《易·坤》"}, {"t": "吉哉。", "b": "《书·皋谟》"}, {"t": "文王当兴,赤雀适来;…吉物动飞而圣遇也。", "b": "《论衡·初禀》"}]}, {"meaning": "吉服(古代祭祀时穿的礼服);吉帖(婚帖,庚帖);吉谶(预示吉祥的隐语或图记);吉羊(吉利祥瑞。古代器物上多铭刻“吉羊”二字。羊,古祥字);吉卜(吉利的卜兆);吉幸(吉利幸运);吉征(幸运的征兆)。"}, {"meaning": "善;美。", "cites": [{"t": "吉事先近日。", "b": "《礼记·曲礼》"}, {"t": "令月、吉日。", "b": "《仪礼·士冠礼》"}, {"t": "吉礼大祝。三曰吉祝,五曰吉拜。", "b": "《周礼·大宗伯》"}, {"t": "吉人之辞寡。", "b": "《易·系辞》"}, {"t": "吉日兮辰良。", "b": "屈原《东皇太一》"}]}, {"meaning": "吉士(古时对男子的美称。引申指大华优美之人);吉灵即溜(形容身段灵活);吉吉抖抖(弯曲成串的样子)。"}, {"meaning": "古州名 。隋置。唐、五代、宋、清因之。在今江西省吉安市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('357wx','扣','1','kòu','扌','6','','[{"pinyin": "kòu", "defs": [{"meaning": "(形声。从手,口声。本义:拉住,牵住)。"}, {"meaning": "同本义。", "cites": [{"t": "扣,牵马也。", "b": "《说文》"}, {"t": "扣马而谏。", "b": "《史记·伯夷叔齐传》"}, {"t": "梁由靡扣缪公之骖。", "b": "《淮南子·泛论》"}, {"t": "太子与郭荣扣马。", "b": "《左传·襄公十八年》"}], "words": [{"w": "扣马", "t": "牵住马,不使前进。也作“叩马”"}, {"w": "环环相扣;扣身", "t": "紧身,衣服紧贴身子。"}]}, {"meaning": "假借为“敂”(击)。敲击。", "cites": [{"t": "扣之其声清扬而远闻。", "b": "《荀子·法行》"}, {"t": "扣石垦壤。", "b": "《列子·汤问》"}, {"t": "于乱石间择其一二扣之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "扣扉", "t": "敲门"}, {"w": "扣户", "t": "敲门"}, {"w": "扣门", "t": "敲门"}, {"w": "扣扃", "t": "叩门,敲门"}, {"w": "扣阍", "t": "叩击宫门。"}]}, {"meaning": "求教;探问。", "cites": [{"t": "扣其乡及姓字。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "扣问", "t": "向人请教;询问"}, {"w": "扣发", "t": "启发;提出意见"}, {"w": "扣请", "t": "扣问。"}]}, {"meaning": "扣除。", "cites": [{"t": "逐日将本钱扣去。", "b": "《卖油郎独占花魁》"}], "words": [{"w": "扣工资;扣分数;扣钱;扣抵", "t": "扣除抵偿"}, {"w": "扣算", "t": "过分地算计。"}]}, {"meaning": "结。", "cites": [{"t": "纽结丁香,掩过芙蓉扣。", "b": "王实甫《西厢记》"}], "words": [{"w": "系一个扣", "t": ""}]}, {"meaning": "用于捆扎成束的文件或帐折等物。", "cites": [{"t": "劳佛便取出一扣三千银子往来的庄折。", "b": "《二十年目睹之怪现状》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('358wx','考','1','kǎo','耂','6','','[{"pinyin": "kǎo", "defs": [{"meaning": "(形声。从老省,丂(kǎo)声。按甲骨文、金文均象偻背老人扶杖而行之状,与老同义。本义:老,年纪大)同本义。", "cites": [{"t": "考,老也。", "b": "《说文》"}, {"t": "富贵寿考。", "b": "《新唐书》"}], "words": [{"w": "考寿", "t": "长寿"}, {"w": "考终", "t": "考终年"}, {"w": "考终年", "t": "享尽天年。"}]}, {"meaning": "去世的父亲。", "cites": [{"t": "父为考。", "b": "《尔雅》"}, {"t": "考妣延年。", "b": "《苍颉篇》"}, {"t": "有子考无咎。", "b": "《易·蛊》"}, {"t": "奔走事厥考厥长。", "b": "《书·酒诰》"}, {"t": "生曰父,死曰考。", "b": "《礼记·曲礼》"}, {"t": "考庙、王考庙、皇考庙、显考庙、祖考庙。", "b": "《礼记·祭法》"}, {"t": "五曰考终命。", "b": "《书·洪范》。按,考者,有子孙为后之称。"}, {"t": "朕皇考曰伯庸。", "b": "《楚辞·离骚》"}], "words": [{"w": "考妣", "t": "父称考,母称妣,古为生前通称;今人则称死去的父母为考妣。"}]}, {"meaning": "假借为“攷”。敲,击。", "cites": [{"t": "子有钟鼓,弗鼓弗考。", "b": "《诗·唐风·山有枢》"}, {"t": "金石有声,不考不鸣。", "b": "《庄子·天地》"}, {"t": "而陋者乃以斧斤考击而求之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "考击", "t": "敲打"}, {"w": "考考", "t": "敲鼓的声音。"}]}, {"meaning": "假借为“拷”。拷打。", "cites": [{"t": "幽囚考掠,五毒参至。", "b": "《后汉书·戴就传》"}], "words": [{"w": "考竟", "t": "鞭笞拷问;受拷问而死在监狱中"}, {"w": "考死", "t": "拷问致死"}, {"w": "考杀", "t": "拷问击杀。"}]}, {"meaning": "查核,考试。", "cites": [{"t": "略考其行事。", "b": "司马迁《报任安书》"}], "words": [{"w": "考较", "t": "查核;核实"}, {"w": "考语", "t": "考核官吏政绩的评语。"}]}, {"meaning": "审察,察考。", "cites": [{"t": "甚者且姓名不可考。", "b": "孙文《黄花冈七十二烈士争略》序"}], "words": [{"w": "考据", "t": "根据"}, {"w": "考正", "t": "根据文献资料核实证明"}, {"w": "考慎", "t": "审慎考察"}, {"w": "考寻", "t": "考察探求;研求"}, {"w": "考道", "t": "研求应尊之道"}, {"w": "考求", "t": "探索研求。"}]}, {"meaning": "完成;建成。", "cites": [{"t": "考仲子之宫。", "b": "《左传·隐公五年》"}], "words": [{"w": "考落", "t": "建成;落成"}, {"w": "考成", "t": "落成;建成。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('359wx','托','1','tuō','扌','6','','[{"pinyin": "tuō", "defs": [{"meaning": "推。同“拓”。", "cites": [{"t": "托,推也。", "b": "《玉篇》"}, {"t": "拓,手推物也。或作托。", "b": "《集韵》"}]}, {"meaning": "压力单位 ,等于1333.2巴,为0°C和标准重力下1毫米汞柱的压力。"}, {"meaning": "(形声。左形,右声。本字是“乇”(zhé),小篆字形,象形。象初生的嫩芽,“一”表地面,枝叶有根,有所寄托。后加“手”作“托”。汉字简化后,“托”又兼代“託”字。本义:寄托)。"}, {"meaning": "同本义。", "cites": [{"t": "託,寄也。", "b": "《说文》"}, {"t": "东方不可以託些。", "b": "《楚辞招魂》"}, {"t": "託山阪以孤魂。", "b": "《文选·张衡·思玄赋》"}, {"t": "久矣,予之不托于音也。", "b": "《礼记·檀弓下》"}, {"t": "自托于赵。", "b": "《战国策·赵策》"}, {"t": "岂足托乎。", "b": "《资治通鉴》"}], "words": [{"w": "托身", "t": "寄身"}, {"w": "托心", "t": "寄托心意"}, {"w": "托情", "t": "寄情"}, {"w": "托意", "t": "寄托心意"}, {"w": "托言", "t": "寄托言辞"}, {"w": "托附", "t": "寄托,依附"}, {"w": "托宿", "t": "寄宿"}, {"w": "托食", "t": "寄食。"}]}, {"meaning": "交付委托。", "cites": [{"t": "未填沟壑而托之。", "b": "《战国策·赵策》"}, {"t": "托臣以讨贼。", "b": "诸葛亮《出师表》"}, {"t": "家书一箧托焉。", "b": "清·梁启超《谭嗣同传》"}, {"t": "将身后托汝。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "托实", "t": "托重于人;不客气"}, {"w": "托命", "t": "托寄生命"}, {"w": "托音", "t": "寄托音信"}, {"w": "托意", "t": "借事物以寄托感情"}, {"w": "托体", "t": "委身。委托身体"}, {"w": "托附", "t": "委任,受托"}, {"w": "托始", "t": "托事而有所起始。后来也称开始为托始"}, {"w": "托寄", "t": "委托,交付。"}]}, {"meaning": "假托。", "cites": [{"t": "凡败法之人,心设诈托物以来亲。", "b": "《韩非子·饰邪》"}, {"t": "外托服从之名。", "b": "《资治通鉴》"}, {"t": "托名汉相。", "b": ""}, {"t": "托于柑以讽。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "托言", "t": "借口"}, {"w": "托病不来;托天", "t": "假托天命"}, {"w": "托事", "t": "假藉事故"}, {"w": "托善", "t": "假托美善"}, {"w": "托讽", "t": "藉事物以为讽喻"}, {"w": "托寓", "t": "藉以寓意"}, {"w": "托之空言", "t": "无事实为证的言论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('360wx','老','1','lǎo','耂','6','','[{"pinyin": "lǎo", "defs": [{"meaning": "(会意。甲骨文字形,象一个手里拿着拐杖的老人形。本义:年老,衰老)。"}, {"meaning": "五十至七十岁的高龄。", "cites": [{"t": "老,考也。七十曰老。", "b": "《说文》"}, {"t": "七十以上曰老。", "b": "《礼记·曲礼》"}, {"t": "有父母耆老而无昆弟者以告。", "b": "《国语·吴语》。注:“六十曰耆,七十曰老。”"}, {"t": "使帅一二耋老而绥焉。", "b": "《公羊传·宣公十二年》。注:“六十称耋,七十称老。”"}, {"t": "老冉冉其将至兮。", "b": "《楚辞·离骚》"}, {"t": "六十以上为老男,五十以上为老女。", "b": "《管子·海王》注"}, {"t": "穷当益坚,老当益壮。", "b": "《后汉书》"}], "words": [{"w": "老钝", "t": "年老迟钝"}, {"w": "老家人", "t": "老仆人"}, {"w": "老院子", "t": "老仆人"}, {"w": "老丹青", "t": "老画家"}, {"w": "老行", "t": "老年男子"}, {"w": "老姐", "t": "年老的女仆"}, {"w": "老杜", "t": "指杜埔。与后来的杜牧相对而言"}, {"w": "老羸", "t": "年老瘦弱"}, {"w": "老口", "t": "年老的人;亦指牲口年龄老。"}]}, {"meaning": "历时长久。", "cites": [{"t": "百年老屋,尘泥渗漉,雨泽下注。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "老工厂,老房子;老亲", "t": "多年的或世代的姻亲关系"}, {"w": "老晴", "t": "天晴得牢,不会很快转阴"}, {"w": "老酒", "t": "陈年的酒"}, {"w": "老桧", "t": "老刺柏"}, {"w": "老牧", "t": "旧称久任地方官者"}, {"w": "老相识", "t": "相识已久的人。"}]}, {"meaning": "排行在最后的。", "cites": [{"t": "我那太公有个老女儿,年方二十岁,更不曾配人。", "b": "《西游记》"}], "words": [{"w": "老生女儿", "t": "最后的一个女儿"}, {"w": "老女儿", "t": "最小的女儿。"}]}, {"meaning": "老年;晚年。", "cites": [{"t": "皆羸老之卒。", "b": "《资治通鉴·唐纪》"}, {"t": "老妇出门看。", "b": "唐·杜甫《石壕吏》"}]}, {"meaning": "又。", "cites": [{"t": "独与老翁别。", "b": ""}, {"t": "欲言国之老少。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "老生", "t": "老年之人"}, {"w": "老况", "t": "老年的景况"}, {"w": "老耋", "t": "老迈。"}]}, {"meaning": "对先辈、年长者的尊称。"}, {"meaning": "古时对某些臣僚的尊称。"}, {"meaning": "指上公。"}, {"meaning": "指上卿。"}, {"meaning": "指大夫。"}, {"meaning": "指大夫的家臣。"}, {"meaning": "指群吏之尊者。"}, {"meaning": "指父母或兄长。", "cites": [{"t": "老吾老,以及人之老。", "b": "《孟子》。朱熹注:“吾老,谓我之父兄。人之老,谓人之父兄。”"}], "words": [{"w": "老母", "t": "年老的母亲"}, {"w": "老子娘", "t": "指父母双亲"}, {"w": "老亲", "t": "年老的父母。"}]}, {"meaning": "死的讳称。", "cites": [{"t": "老于户牖之下。", "b": "明·张溥《五人墓碑记》"}, {"t": "以备京中老了人口,在此停灵。", "b": "《红楼梦》"}], "words": [{"w": "老去", "t": "死去"}, {"w": "老家", "t": "指阴间。俗语以“回老家”比喻死亡。"}]}, {"meaning": "敬爱,敬重。", "cites": [{"t": "老吾老,以及人之老。(指第一个老。)", "b": "《孟子》"}]}, {"meaning": "告老。", "cites": [{"t": "余将致政焉…乃老。", "b": "《国语》"}, {"t": "范武子将老。", "b": "《左传·宣公十七年》"}]}, {"meaning": "变老;衰老。", "cites": [{"t": "天若有情天亦老。", "b": "李贺《金铜仙人醉汉歌》"}]}, {"meaning": "衰老;衰颓。", "cites": [{"t": "臣之壮也,犹不如人;今老矣,无能为也已。", "b": "《左传》"}], "words": [{"w": "老色", "t": "衰老之色"}, {"w": "老拙", "t": "老朽愚拙"}, {"w": "老气", "t": "暮气"}, {"w": "老背悔", "t": "老背晦。老胡涂"}, {"w": "老货", "t": "骂老人的话。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('361wx','巩','1','gǒng','工','6','','[{"pinyin": "gǒng", "defs": [{"meaning": "(形声。从革,巩声。从“革”,表示与皮革有关。本义:用皮革捆东西)。"}, {"meaning": "同本义。", "cites": [{"t": "巩,以韦束也。", "b": "《说文》"}, {"t": "巩用黄牛之革。", "b": "《易·革》"}, {"t": "无不克鞏。", "b": "《诗·大雅·瞻卬》"}]}, {"meaning": "恐惧。", "cites": [{"t": "故君子恭而不难,敬而不巩。", "b": "《荀子·君道》"}], "words": [{"w": "巩巩", "t": "恐惧的样子。"}]}, {"meaning": "中国河南省县名 ,以在洛水之间,四面皆山,可以巩固,故名,历代因之。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
