('362wx','圾','1','jī','土','6','','[{"pinyin": "jī", "defs": [{"meaning": "——见“垃圾”(lājī)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('363wx','执','1','zhí','扌','6','','[{"pinyin": "zhí", "defs": [{"meaning": "(右边是人,手被铐住。本义:拘捕;捉拿)。"}, {"meaning": "同本义。", "cites": [{"t": "执,捕罪人也。", "b": "《说文》"}, {"t": "而妻妾执。", "b": "《礼记·檀弓》。注:“拘也。”"}, {"t": "使执连尹。", "b": "《吕氏春秋·慎行》。注:“囚也。”"}, {"t": "遂袭虞,灭之,执虞公。", "b": "《左传·僖公五年》"}, {"t": "被执至南门。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "执命", "t": "讨命;索命"}, {"w": "执讯", "t": "捉命并加以审问"}, {"w": "执囚", "t": "拘捕囚禁"}, {"w": "执问", "t": "拘留讯问"}, {"w": "执狱", "t": "治狱;审判案件。"}]}, {"meaning": "拿;持。", "cites": [{"t": "执之用黄牛之革。", "b": "《易·遯》"}, {"t": "执君之乘车。", "b": "《礼记·少仪》。注:“执辔也。”"}, {"t": "执竞武王。", "b": "《诗·周颂·执竞》。笺:“执,持也。”"}, {"t": "执束帛。", "b": "《礼记·曾子问》"}, {"t": "献琛执贽。", "b": "《文选·张衡·东京赋》"}, {"t": "执干戚舞。", "b": "《韩非子·五蠹》"}, {"t": "执叶伺蝉。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "居左者手执蒲葵扇。", "b": "明·魏学洢《核舟记》"}]}, {"meaning": "又。", "cites": [{"t": "东坡右手执卷端。", "b": ""}, {"t": "乃强起扶杖,执图诣寺后。", "b": "《聊斋志异·促织》"}], "words": [{"w": "执圭端拱", "t": "双手拿圭拱捧于胸前"}, {"w": "执鞭弭", "t": "为人驾驭车马,充当保镖"}, {"w": "执锐", "t": "手持兵器"}, {"w": "执桴", "t": "拿起鼓槌"}, {"w": "执拂", "t": "手执拂尘"}, {"w": "执玉", "t": "手捧玉器"}, {"w": "执杖", "t": "手持丧棒"}, {"w": "执圭", "t": "以手持圭。"}]}, {"meaning": "操持;执行。", "cites": [{"t": "御史执法,举不如仪者。", "b": "《汉书·叔孙通传》"}], "words": [{"w": "执作", "t": "操作;劳作"}, {"w": "执役", "t": "服役人员;工作人员"}, {"w": "执料", "t": "操持,照料"}, {"w": "执威", "t": "施行刑罚"}, {"w": "执务", "t": "操持,担任"}, {"w": "执职", "t": "从事某专职;服役。"}]}, {"meaning": "主持;掌管。", "cites": [{"t": "郑人游于乡校,以论执政。", "b": "《左传·襄公三十一年》"}, {"t": "执狱牢者无病。", "b": "《淮南子·说山训》"}], "words": [{"w": "执专阃外", "t": "执掌镇守国家边关的权力"}, {"w": "执正", "t": "主持公道"}, {"w": "执炊", "t": "掌管炊事,做饭"}, {"w": "执把", "t": "把持;掌管;拿着"}, {"w": "执事人", "t": "主管具体事务的人。"}]}, {"meaning": "掌握;控制。", "cites": [{"t": "公子执辔愈恭。(执辔:握着驭马的缰绳。)", "b": "《史记·魏公子列传》"}], "words": [{"w": "执服", "t": "慑服,因畏惧而服从"}, {"w": "执持", "t": "握持,控制,掌握"}, {"w": "执权", "t": "掌握权柄。"}]}, {"meaning": "固执;坚持。", "cites": [{"t": "乐乐兮其执道不殆也。", "b": "《荀子·儒效》"}], "words": [{"w": "执迷不化", "t": "固执己见,不知变通"}, {"w": "执泥一见", "t": "固执一义,不知通权变达"}, {"w": "执告", "t": "执意求告"}, {"w": "执违", "t": "执意违抗"}, {"w": "各执己见;执一", "t": "固执一端,不知变通;掌握根本之道。"}]}, {"meaning": "取得。", "cites": [{"t": "是皆不足以执信也。", "b": "马中锡《中山狼传》"}]}, {"meaning": "判断。", "cites": [{"t": "请诵其所闻,而吾子自执也。", "b": "《礼记·乐记》"}], "words": [{"w": "执狱", "t": "审判案子。"}]}, {"meaning": "堵塞。", "cites": [{"t": "子玉使伯棼请战,曰:“非敢必有功也,愿以间执谗慝之口。", "b": "《左传·僖公二十八年》"}]}, {"meaning": "结下,结成。", "cites": [{"t": "寡人不知其力之不足也,而又与大国执仇。", "b": "《国语·越语上》"}], "words": [{"w": "执怨", "t": "结怨,抱急"}, {"w": "执仇", "t": "结仇。"}]}, {"meaning": "对待。", "cites": [{"t": "貌执之士者百有余人。", "b": "《荀子》"}]}, {"meaning": "至交,好友。", "cites": [{"t": "怡然敬父执,问我来何方。", "b": "杜甫《赠卫八处士》"}]}, {"meaning": "相当于“用”、“凭”。", "cites": [{"t": "执古可以御今,证今可以知古。", "b": "《云笈七签》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('364wx','扩','1','kuò','扌','6','','[{"pinyin": "kuò", "defs": [{"meaning": "扩大;张开。", "cites": [{"t": "扩,引张之意。", "b": "《玉篇》"}, {"t": "知皆扩而充之矣。", "b": "《孟了·公孙丑上》"}, {"t": "王者何修身正行,扩施善政?", "b": "《论衡·感虚》"}], "words": [{"w": "扩清", "t": "廓清;肃清"}, {"w": "扩广", "t": "扩张。犹扩大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('365wx','扫','1','sǎo sào','扌','6','','[{"pinyin": "sǎo", "defs": [{"meaning": "(会意。从手,从帚。手拿扫帚表示打扫。本义:打扫)。"}, {"meaning": "同本义。", "cites": [{"t": "埽,弃也。", "b": "《说文》。字亦作掃。"}, {"t": "埽,除也。", "b": "《广雅》"}, {"t": "掌五寝之埽除粪洒之事。", "b": "《周礼·隶仆》"}, {"t": "子有廷内,弗洒弗扫。", "b": "《诗·唐风·山有枢》"}, {"t": "花径不曾缘客扫,蓬门今始为君开。", "b": "唐·杜甫《客至》"}], "words": [{"w": "扫径", "t": "清洁路径"}, {"w": "扫尘", "t": "扫去尘垢;比喻扫荡残敌,平定乱事"}, {"w": "扫脑儿", "t": "秃子"}, {"w": "扫道", "t": "踩出来的路"}, {"w": "扫桃", "t": "扫面子"}, {"w": "扫花以待", "t": "表示主人待客的诚意"}, {"w": "扫眉才子", "t": "指有文才的女子。"}]}, {"meaning": "掠过。", "cites": [{"t": "千骑飚扫,万乘雷奔。", "b": "李白《大猎赋》"}], "words": [{"w": "扫望", "t": "扫视"}, {"w": "扫射", "t": ""}]}, {"meaning": "清除,消灭。", "cites": [{"t": "扫项军于垓下。", "b": "张衡《东京赋》"}], "words": [{"w": "扫白", "t": "除去白发"}, {"w": "扫穴", "t": "清除巢穴"}, {"w": "扫穴擒渠", "t": "扫荡巢穴,擒拿贼首"}, {"w": "扫殄", "t": "消灭"}, {"w": "扫清", "t": "平定廓清"}, {"w": "扫定(平定):扫难(平定患难)", "t": ""}]}, {"meaning": "画,染。", "cites": [{"t": "淡扫蛾眉朝至尊。", "b": "张祜《集灵台》"}], "words": [{"w": "扫黛", "t": "画眉;用黛描画"}, {"w": "扫眼", "t": "描眼。"}]}, {"meaning": "祭扫。", "cites": [{"t": "故请母命而宁汝于斯,便祭扫也。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "扫墓", "t": ""}]}, {"meaning": "飞快地书写。", "cites": [{"t": "吾师醉后倚绳床,须臾扫尽数千张。", "b": "李白《草书歌行》"}]}]}, {"pinyin": "sào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('366wx','地','1','de dì','土','6','','[{"pinyin": "de", "defs": [{"meaning": "还用于状语后或补语前。", "cites": [{"t": "相看月未坠,白地断肝肠。", "b": "唐·杜甫《越女词》"}]}]}, {"pinyin": "dì", "defs": [{"meaning": "(形声。从土,也声。本义:大地)。"}, {"meaning": "同本义,与“天”相对。", "cites": [{"t": "立字士力于一者为地。", "b": "《春秋·元命苞》"}, {"t": "土乙力为地。", "b": "《尔雅·释地》"}, {"t": "地生养万物。", "b": "《管子·形势解》"}], "words": [{"w": "落地;天地;地角", "t": "地的末端。多比喻极僻远的地方"}, {"w": "地宫", "t": "帝王墓地放置棺材的地下建筑"}, {"w": "地府", "t": "阴间"}, {"w": "地脉", "t": "风水"}, {"w": "地遁", "t": "隐入地下;入土而逃。"}]}, {"meaning": "地面;陆地。", "cites": [{"t": "双兔傍地走,安能辨我是雄雌。", "b": "《乐府诗集·木兰诗》"}, {"t": "床前明月光,疑是地上霜。", "b": "唐·李白《静夜思》"}], "words": [{"w": "地文", "t": "地面山岳河海丘陵平原之形"}, {"w": "地藏", "t": "地下深处"}, {"w": "地市", "t": "地下的市镇"}, {"w": "地平", "t": "地面平坦。"}]}, {"meaning": "土地;田地。", "cites": [{"t": "殚其地之出。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "湿地;好地;下地干活儿;地头", "t": "地上,与天上相对;方面"}, {"w": "地灵", "t": "土地山川的灵秀之气。"}]}, {"meaning": "领土,属地;地区 。", "cites": [{"t": "而安陵君以五十里之地存者。", "b": "《战国策·魏策》"}], "words": [{"w": "各地;内地;本地;割地", "t": "割让领土"}]}, {"meaning": "地方;场所。", "cites": [{"t": "此地空余黄鹤楼。", "b": "唐·崔颢《黄鹤楼》"}, {"t": "英雄无用武之地。", "b": "《资治通鉴》"}], "words": [{"w": "各地文化站;产地", "t": "物品出产的地方"}, {"w": "坟地;原地;地著", "t": "久居其地不迁移的人"}, {"w": "地棍", "t": "地方上的流氓无赖。"}]}, {"meaning": "路程;面积。", "cites": [{"t": "那轿夫抬进去,走了一射之地。", "b": "《红楼梦》"}], "words": [{"w": "十里地", "t": ""}]}, {"meaning": "言语和行动可以回旋的地方。", "cites": [{"t": "恢恢乎其于游刃必有余地矣。", "b": "《庄子·养生主》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('367wx','场','1','cháng chǎng chang','土','6','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从土昜声。本义:平坦的空地)。"}, {"meaning": "祭坛旁的平地。", "cites": [{"t": "牺牲壇场。", "b": "《汉书·郊祀志》。注:“平地为场。”"}, {"t": "灵场之威。", "b": "《法言·问明》。注:“鬼神之壇也。”"}]}, {"meaning": "谷场,场子。", "cites": [{"t": "一曰治谷田也。", "b": "《说文》"}, {"t": "季秋除圃中为之。", "b": "《周礼·场人》注"}, {"t": "以场圃任园地。", "b": "《周礼·载师》"}, {"t": "九月筑场圃。", "b": "《诗·豳风·七月》"}]}, {"meaning": "又。", "cites": [{"t": "十月涤场。", "b": ""}, {"t": "顾野有麦场,场主积薪其中。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "打场", "t": "在场上脱粒"}, {"w": "禾场;摊场;晒场", "t": ""}]}, {"meaning": "道路。", "cites": [{"t": "除城场外,去池百步,墙垣树木小大俱坏伐。", "b": "《墨子》"}]}, {"meaning": "用于事情经过的次数。", "cites": [{"t": "千场纵博家仍富,几处报仇身不死。", "b": "高适《邯郸少年行》"}], "words": [{"w": "一场硬仗;闹了一场;场子", "t": "次数。"}]}]}, {"pinyin": "chǎng", "defs": [{"meaning": "(形声。从土,昜(yáng)声。本义:场所)。"}, {"meaning": "场所。众人聚集进行某桩事情的地方或事情发生的地方。", "cites": [{"t": "闲习军事,数践战场。", "b": "《后汉书·郑太传》"}], "words": [{"w": "广场;考场;会场;机场", "t": ""}]}]}, {"pinyin": "chang", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('368wx','扬','1','yáng','扌','6','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从手,昜(yáng)声。金文字形,像用双手举起“玉”,是会意字。本义:高举)。"}, {"meaning": "同本义。", "cites": [{"t": "扬,飞举也。", "b": "《说文》"}, {"t": "扬,举也。", "b": "《小尔雅》"}, {"t": "杜篑洗而扬觯。", "b": "《礼记·檀弓》"}, {"t": "盥洗扬斛。", "b": "《礼记·乡饮酒义》"}, {"t": "南扬弓。", "b": "《仪礼·乡射礼》"}, {"t": "扬其波。", "b": "《史记·屈原贾生列传》"}, {"t": "扬鞭语曰。", "b": "明·宗臣《报刘一丈书》"}, {"t": "大风扬积雪。", "b": "清·姚鼐《登泰山记》"}, {"t": "扬帆去。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "扬楫", "t": "行船"}, {"w": "扬袂", "t": "举袖"}, {"w": "扬眉", "t": "举目"}, {"w": "扬旌", "t": "高举军旗"}, {"w": "扬麋", "t": "扬眉"}, {"w": "扬觯", "t": "举起酒器"}, {"w": "扬鞭", "t": "挥鞭"}, {"w": "扬臂", "t": "振臂"}, {"w": "扬徽", "t": "挥动军旗"}, {"w": "扬刃", "t": "挥动锋刃。"}]}, {"meaning": "假借为“飞”。飞起,升高。", "cites": [{"t": "只因朝廷无驾驭,遂令草泽有鹰扬。", "b": "《水浒全传》"}, {"t": "飘风起兮扬尘埃,走鬯罔兮乍东西。", "b": "汉·王逸《九思·逢尤》"}], "words": [{"w": "扬蕤", "t": "彩带飘舞"}, {"w": "扬尘", "t": "激起尘土"}, {"w": "扬饭", "t": "扬去饭的热气。"}]}, {"meaning": "通过风或气流处理。", "cites": [{"t": "维南有箕,不可以簸扬。", "b": "《诗·小雅·大东》"}], "words": [{"w": "用连枷打谷后,他们又扬谷", "t": ""}]}, {"meaning": "提高声音。", "cites": [{"t": "不吴不扬。", "b": "《诗·鲁颂·泮水》"}], "words": [{"w": "扬言", "t": "大声地说"}, {"w": "扬音", "t": "谓发出高亢的声音"}, {"w": "扬歌", "t": "高声歌唱"}, {"w": "扬嚷", "t": "高声叫嚷。"}]}, {"meaning": "发扬,发挥。", "cites": [{"t": "发扬蹈厉,太公之志也。", "b": "《礼记·乐记》"}, {"t": "扬文欲其明。", "b": "唐·柳宗元《柳河东集》"}]}, {"meaning": "振作,昂扬。", "cites": [{"t": "振声激扬。", "b": "《后汉书·张衡传》"}]}, {"meaning": "显示;夸耀。", "cites": [{"t": "皆有功德,知名当世,是以表而扬之。", "b": "《汉书》"}], "words": [{"w": "扬美", "t": "称扬优点"}, {"w": "扬清", "t": "谓称扬美德"}, {"w": "扬善", "t": "宣扬好人好事"}, {"w": "扬称", "t": "赞扬。"}]}, {"meaning": "仰。", "cites": [{"t": "进则揖之,退则扬之。", "b": "《礼记·玉藻》"}]}, {"meaning": "眉毛及其上下部分。", "cites": [{"t": "清扬婉兮。", "b": "《诗·齐风·猗嗟》"}, {"t": "问我何所得,乐色填清扬。", "b": "《唐·卢仝》"}]}, {"meaning": "过长过高的树枝。", "cites": [{"t": "持斧伐远扬,荷锄觇泉脉。", "b": "王维《春中田园作》"}]}, {"meaning": "古九州之一 。辖今苏、皖、赣、浙、闽诸省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('369wx','耳','1','ěr','耳','6','','[{"pinyin": "ěr", "defs": [{"meaning": "(象形。甲骨文字形,象耳朵形。汉字部首之一。本义:耳朵)。"}, {"meaning": "同本义。", "cites": [{"t": "耳,主听也。", "b": "《说文》"}, {"t": "耳者,肾之候。", "b": "《白虎通·情性》"}, {"t": "耳者,心之候。", "b": "《春秋·元命苞》"}, {"t": "耳目者,心思之助也。", "b": "《鬼谷子·权篇》"}, {"t": "坎为耳。", "b": "《易·说卦》"}, {"t": "忠言逆耳利于行。", "b": "明·刘基《苦斋记》"}, {"t": "事不目见耳闻,而臆断其有无,可乎?", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "耳目官", "t": "指耳、目两种器官"}, {"w": "耳斡儿", "t": "亦作“耳挖子”。掏耳垢的小勺,另一头有尖头"}, {"w": "耳朵垂子", "t": "借指耳窝"}, {"w": "耳根厢", "t": "耳边"}, {"w": "耳顺", "t": "六十岁。"}]}, {"meaning": "谷物在雨淋后所生的芽。", "cites": [{"t": "禾头生耳黍穗黑,农夫田父无消息。", "b": "杜甫《秋雨叹三首》"}]}, {"meaning": "位置在两旁的如:耳门;耳房。"}, {"meaning": "退后,居次。", "cites": [{"t": "人自为种而天下耳。", "b": "《庄子·天运》"}]}, {"meaning": "表示限制,相当于“而已”、“罢了”。", "cites": [{"t": "技止此耳。", "b": "唐·柳宗元《三戒》"}, {"t": "止增笑耳", "b": "《聊斋志异·狼三则》"}, {"t": "子曰∶“二三子!偃之言是也。前言戏之耳。”", "b": "《论语·阳货》"}, {"t": "从此道至吾军,不过三十里耳。", "b": "《史记》"}]}, {"meaning": "表示肯定或语句的停顿与结束,如同“矣”,相当于“了”、“啊”、“也”。", "cites": [{"t": "田横,齐之壮士耳。", "b": "《资治通鉴》"}, {"t": "且壮士不死即已,死即举大名耳。", "b": "《史记》"}]}, {"meaning": "表示转折关系,相当于“而”。", "cites": [{"t": "故化成俗定,则为人臣者,主耳忘身,国而忘家,公耳忘私。", "b": "贾谊《治安策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('370wx','芋','1','yù','艹','6','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从艸,于声。本义:植物名。俗称“芋艿”)。"}, {"meaning": "同本义。", "cites": [{"t": "芋,大叶实根,骇人,故谓之芋也。", "b": "《说文》"}, {"t": "士卒食芋菽。", "b": "《史记·项羽本纪》"}, {"t": "其实葵菹芋。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "芋火", "t": "煨芋的炭火"}, {"w": "芋渠", "t": "大芋头。同“芋魁”"}, {"w": "芋荷", "t": "芋艿。因其叶似荷,故名。南方称芋头的叶及柄为芋荷"}, {"w": "芋火", "t": "煨芋之火"}, {"w": "芋郎君", "t": "抟芋酥作人形的食品"}, {"w": "芋魁", "t": "芋的块茎。泛指薯类植物的块茎"}, {"w": "芋魁豆饭", "t": "喻食物粗劣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('371wx','共','1','gōng gǒng gòng','八','6','','[{"pinyin": "gōng", "defs": [{"meaning": "供奉。", "cites": [{"t": "不共神祗。", "b": "《国语》"}, {"t": "尔贡包茅不入,王祭不共,无以缩酒。", "b": "《左传》"}]}, {"meaning": "恭敬", "cites": [{"t": "共武之服。", "b": "《诗·小雅·六月》"}, {"t": "虔共尔位。", "b": "《诗·大雅·韩奕》"}, {"t": "公卑杞,杞不共也。", "b": "《左传·僖公二十七年》"}, {"t": "共承嘉惠。", "b": "《史记·屈原贾生列传》。集解:“敬也。”"}], "words": [{"w": "共命", "t": "敬从命令"}, {"w": "共勤", "t": "恭谨勤劳"}, {"w": "共承", "t": "恭敬地承奉"}, {"w": "共奉", "t": "敬奉,供奉。"}]}, {"meaning": "供给;供应", "cites": [{"t": "共其羊牲。", "b": "《周礼·羊人》"}, {"t": "事之共给。", "b": "《国语·周语》"}, {"t": "不能共亿。", "b": "《左传·隐公十一年》"}, {"t": "行李之往来,共其乏困。", "b": "《左传·僖公三十年》"}, {"t": "三辅长无共张繇役之劳。", "b": "《汉书·成帝纪》"}], "words": [{"w": "共给", "t": "供给"}, {"w": "共张", "t": "供应、置备"}, {"w": "共待", "t": "备用"}, {"w": "共具", "t": "用以摆设酒食的器具。"}]}, {"meaning": "供职;奉职。", "cites": [{"t": "卿等不必言,其各共乃事。", "b": "《续资治通鉴》"}]}, {"meaning": "古国名 。有两个。一个在今甘肃省泾川北,另一个在今河南省 辉县。"}]}, {"pinyin": "gǒng", "defs": [{"meaning": "(拱的本字)。"}, {"meaning": "拱手,打拱。", "cites": [{"t": "共,同也。", "b": "《说文》。徐灏曰:“共,古拱字。”"}, {"t": "居其所而众星共之。", "b": "《论语·为政》。郑注:“共,拱手也。”"}, {"t": "退共。", "b": "《仪礼·乡饮酒礼》。注:“共,拱手也。”"}, {"t": "圣人共手,肘几将矣。", "b": "《荀子·赋篇》"}], "words": [{"w": "共手", "t": "两手在胸前叠合,表示恭敬。"}]}, {"meaning": "引申为环抱。", "cites": [{"t": "居其所而众星共之。", "b": "《论语》"}]}]}, {"pinyin": "gòng", "defs": [{"meaning": "(会意。从廿。本义:同)。"}, {"meaning": "共享,共用或共有。", "cites": [{"t": "共,同也。", "b": "《说文》"}, {"t": "惟喜康共。", "b": "《书·盘庚》"}, {"t": "共帅时。", "b": "《礼记·内则》。注:“犹皆也。”"}, {"t": "共其德也。", "b": "《庄子·庚桑楚》。崔注:“壹也。”"}, {"t": "臣有所与与。", "b": "《列子·说符》。注:“同也。”"}, {"t": "仁义者,与天下共其所有而同其利者也。", "b": "《韩非子·外储说右上》"}, {"t": "愿车马,衣轻裘,与朋友共,敝之而无憾。", "b": "《论语·公冶长》"}], "words": [{"w": "共名", "t": "共有的名称"}, {"w": "共少", "t": "共享少许东西,谓上下同甘苦"}, {"w": "共主", "t": "共同崇奉的宗主"}, {"w": "共害", "t": "共同承受祸患。"}]}, {"meaning": "(gǒng)。"}, {"meaning": "执持。", "cites": [{"t": "罔敷求先王,克共明刑。", "b": "《诗·大雅·抑》"}]}, {"meaning": "抱拳,拱手。", "cites": [{"t": "子路共之,三嗅而作。", "b": "《论语·乡党》"}], "words": [{"w": "退共", "t": "退后并抱拳的礼节"}, {"w": "共手", "t": "拱手。"}]}, {"meaning": "环绕。", "cites": [{"t": "居其所而众星共之。", "b": "《论语·为政》"}, {"t": "受命而海内顺之,犹众星之共北辰。", "b": "《春秋繁露·观德》"}]}, {"meaning": "(gòng)。"}, {"meaning": "奉献。", "cites": [{"t": "靖共尔位,好是正直。", "b": "《诗·小雅·小明》"}, {"t": "王祭不共,无以缩酒。", "b": "《左传·僖公四年》"}], "words": [{"w": "共贡", "t": "奉献贡物。"}]}, {"meaning": "供给。", "cites": [{"t": "布粟之绝则委之,币帛不足则 共之。", "b": "《墨子·非攻下》"}, {"t": "居处俭节,禄赐以共九族乡党。", "b": "《汉书·循吏传》"}], "words": [{"w": "共羊", "t": "供给羊只"}, {"w": "共费", "t": "供给经费。"}]}, {"meaning": "(gōng)。恭敬。有礼貌。", "cites": [{"t": "公卑杞,杞不共也。", "b": "《左传·僖公二十七年》"}, {"t": "共承嘉惠兮,俟罪长沙。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "共己", "t": "自敬。"}]}, {"meaning": "相同,一样。", "cites": [{"t": "夏曰校,殷曰序,周曰庠;学则三代共之。", "b": "《孟子·滕文公上》"}, {"t": "风烟俱净,天山共色。", "b": "南朝梁·吴均《与朱元思书》"}]}, {"meaning": "一同,一起。", "cites": [{"t": "苏黄共阅一卷。", "b": "明·魏学洢《核舟记》"}]}, {"meaning": "总共;共计。", "cites": [{"t": "对联、题名并篆刻文,为字共三十有四。", "b": "明·魏学洢《核舟记》"}, {"t": "前后共吃了十五碗。", "b": "《水浒传》"}], "words": [{"w": "合共;拢共;统共;一共", "t": ""}]}, {"meaning": "(gōng)。宫刑。古代破坏生殖机能的酷刑。又称腐刑,为五刑之一。", "cites": [{"t": "治古无肉刑,而有象刑,墨黥;慅婴;共,艾毕;菲,对屦;杀,赭衣而不纯。", "b": "《荀子·正论》"}]}, {"meaning": "表示涉及的对象,相当于“跟”、“同”。", "cites": [{"t": "秋水共长天一色。", "b": "唐·王勃《滕王阁序》"}, {"t": "即游亦尚有几许心中言要与知闻,共汝筹画也。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "和,与。", "cites": [{"t": "那里去辨甚么真共假?", "b": "《朝天子·咏喇叭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('372wx','芒','1','máng','艹','6','','[{"pinyin": "máng", "defs": [{"meaning": "(形声。从艸,亡声。本义:谷类植物种子壳上或草木上的针状物)。"}, {"meaning": "同本义。", "cites": [{"t": "芒,草耑也。", "b": "《说文》。徐锴曰:“谓麦谷为芒种是也。”"}, {"t": "种之芒种。", "b": "《周礼·地官·稻人》。郑众注:“芒种,稻麦也。”"}, {"t": "芒之为言萌也。", "b": "《白虎通·五行》"}, {"t": "麦渐渐以擢芒。(擢芒:长出麦芒。)", "b": "潘岳《射雉赋》"}], "words": [{"w": "芒茅", "t": "茅草的一种"}, {"w": "芒履", "t": "芒屣,芒屦,芒鞋"}, {"w": "芒鞋", "t": "用芒茎外皮编成的鞋。亦泛指草鞋"}, {"w": "芒刺", "t": "草木茎叶和果谷上的小刺。比喻使人极度不安的感觉"}, {"w": "芒角", "t": "植物的尖叶。"}]}, {"meaning": "光芒。", "cites": [{"t": "扬芒熛而绛天兮。", "b": "《文选·张衡·思玄赋》"}, {"t": "有作其芒。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "芒炎", "t": "星星的光芒"}, {"w": "芒彩", "t": "光彩;光芒。"}]}, {"meaning": "毫末;锋刃。", "cites": [{"t": "芒刀不顿。", "b": "《汉书·贾谊传》"}, {"t": "莫不衄锐挫芒。", "b": "左思《吴都赋》"}], "words": [{"w": "芒锷", "t": "锋芒。比喻人的锐气"}, {"w": "芒刃", "t": "刀剑锐利处。俗称刀尖、刀口。"}]}, {"meaning": "广大;众多。", "cites": [{"t": "芒芒其稼。", "b": "束晳《补亡诗·华黍》"}], "words": [{"w": "芒芒", "t": "通茫茫。广大辽远的样子;形容众多"}, {"w": "芒洋", "t": "也作茫洋。浩翰无边际的样子"}, {"w": "芒荒", "t": "大荒。辽阔的荒野。"}]}, {"meaning": "模糊不清。", "cites": [{"t": "目芒然无见。", "b": "《庄子·盗跖》"}], "words": [{"w": "芒昧", "t": "混沌不明的样子"}, {"w": "芒芠", "t": "混沌的样子"}, {"w": "芒然", "t": "茫然"}, {"w": "芒然自失", "t": "茫然自失。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('373wx','亚','1','yà','二','6','','[{"pinyin": "yà", "defs": [{"meaning": "(象形。小篆作“亞”。许慎认为像人驼背形。甲骨文一说像花边形。本义:丑)。"}, {"meaning": "同本义。", "cites": [{"t": "夫地有山有泽,有黑有白,有美有亚。", "b": "马王堆汉墓帛书《十六经》"}, {"t": "亚,丑也。", "b": "《说文》。段玉裁注:“此亚之本义。亚与恶音义皆同…衣驾切。”"}]}, {"meaning": "次;次于。表示时间或空间的先后。", "cites": [{"t": "言天下之至赜而不可亚也。", "b": "《易·系辞》荀本"}, {"t": "亚旅。", "b": "《书·牧誓》"}, {"t": "侯亚侯旅。", "b": "《诗·周颂·载芟》"}, {"t": "为亚卿焉。", "b": "《左传·文公六年》"}, {"t": "龟亚之。", "b": "《仪礼·士虞礼》"}, {"t": "亚父南向坐(亚父者,范增也。)。", "b": "《史记·项羽本纪》"}], "words": [{"w": "亚献", "t": "古代祭祀举行三次供物仪式,第二次叫“亚献”"}, {"w": "亚元", "t": "名列第二"}, {"w": "亚父", "t": "仅次于父"}, {"w": "亚帅", "t": "副帅"}, {"w": "亚相", "t": "官位次于丞相的大臣"}, {"w": "亚将", "t": "次将,副将"}, {"w": "亚饭", "t": "古代天子、诸侯第二次进食时奏乐佐食的乐师;古代天子、诸侯的第二次进食"}, {"w": "亚圣", "t": "道德才智仅次于圣人"}, {"w": "亚魁", "t": "古代泛指科举考试第二名。"}]}, {"meaning": "低于;低。表示等级的高低。", "cites": [{"t": "圭妫之班,亚宋子而相亲也。", "b": "《左传·襄公十九年》。杜预注:“亚,次之。”"}]}, {"meaning": "垂;低垂。", "cites": [{"t": "松装粉穗临窗亚,水结冰锤簇溜悬。", "b": "前蜀·韦庄《对雪献薛常侍》"}, {"t": "有几枝还低亚着,护定他从打枣的竿梢所得的皮伤。", "b": "鲁迅《野草》"}]}, {"meaning": "俯,偃俯。", "cites": [{"t": "舟人渔子入浦溆,山木尽亚洪涛风。", "b": "唐·杜甫《戏题王宰画山水图歌》"}, {"t": "言天下之至赜而不可亚也。", "b": "《易·系辞》荀李"}, {"t": "亚旅。", "b": "《书·牧誓》"}, {"t": "侯亚侯旅。", "b": "《诗·周颂·载芟》"}, {"t": "为亚卿焉。", "b": "《左传·文公六年》"}, {"t": "鱼亚之。", "b": "《仪礼·士虞礼》"}, {"t": "亚身受取白玉羁,开口衔将紫金勒。", "b": "唐·元稹《望云骓马歌》"}], "words": [{"w": "亚地", "t": "俯于地;倒于地。"}]}, {"meaning": "压;低压。", "cites": [{"t": "可怜把个行者头,勒得似个亚腰葫芦,十分疼痛难忍。", "b": "《西游记》"}, {"t": "叶重如将青玉亚,花轻疑是红绡挂。", "b": "宋·欧阳修《渔家傲》"}], "words": [{"w": "亚地", "t": "满地;遍地"}, {"w": "亚腰葫芦", "t": "细腰葫芦。亚:压;挤紧。"}]}, {"meaning": "挨着,靠近。", "cites": [{"t": "武松在轿上看时,只见亚肩叠背,闹闹嚷嚷,屯街塞巷,都来看迎大虫。", "b": "《水浒传》"}], "words": [{"w": "亚肩叠背", "t": "压肩叠背。"}]}, {"meaning": "掩,闭。", "cites": [{"t": "花笼淡月,重门深亚。", "b": "蔡伸《丑奴儿慢》"}]}, {"meaning": "垂压。", "cites": [{"t": "鬓毛垂领白,花蕊亚枝红。", "b": "杜甫《上巳日徐司录林园宴集》"}, {"t": "花亚欲移竹,鸟窥新卷帘。", "b": "杜甫《入宅三首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('374wx','芝','1','zhī','艹','6','','[{"pinyin": "zhī", "defs": [{"meaning": "(会意。从艸,从之,之亦声。本义:灵芝,菌类植物的一种)。"}, {"meaning": "同本义。", "cites": [{"t": "芝,神草也。", "b": "《说文》"}, {"t": "采三秀兮于山间。", "b": "《楚辞·山鬼》。注:“三秀,芝草也。”"}, {"t": "拔搴元芝兮。", "b": "《楚辞·谬谏》。注:“神草也。”"}, {"t": "咀噍芝英兮叽琼华。", "b": "《汉书·司马相如传》。注:“草蒻也。”"}, {"t": "土气和则芝草生。", "b": "王充《论衡》"}]}, {"meaning": "也称“木灵芝”。真菌的一种,生于枯木根际。入药,为强壮剂。《神农本草经》有青芝、赤芝、黄芝、白芝、黑芝、紫芝。古人以为瑞草,服之可以成仙。", "cites": [{"t": "芝生于土。…芝草延年,仙者所食。", "b": "《论衡·验符》"}], "words": [{"w": "芝草", "t": "即灵芝"}, {"w": "芝圃", "t": "相传为仙人栽植灵芝的园圃"}, {"w": "芝残", "t": "灵芝凋谢。比喻贤德的人凋零"}, {"w": "芝艾", "t": "芝草和艾草。比喻贵贱、贤愚"}, {"w": "芝田", "t": "传说中仙人种灵芝的地方。"}]}, {"meaning": "形如菌盖的东西,多指车盖。", "cites": [{"t": "于是乘舆乃登夫凤皇兮翳华芝。", "b": "《汉书·扬雄传》"}], "words": [{"w": "芝车", "t": "古天子、诸侯亲耕籍田时的乘车。也称耕车"}, {"w": "芝盖", "t": "车盖或伞盖。芝形如盖,故名。"}]}, {"meaning": "香草。也作“芷”。", "cites": [{"t": "芝兰生于深林,不以无人而不芸。", "b": "《孔子家语·在厄》"}, {"t": "好我芳若芝兰。", "b": "《荀子·王制》"}, {"t": "譬如芝兰玉树。", "b": "《世说新语·言语》"}], "words": [{"w": "芝桂", "t": "芝、桂皆为香类的植物,因以喻志行高洁的人"}, {"w": "芝髓", "t": "芝草的汁液"}, {"w": "芝草无根", "t": "比喻人的成就,全靠自己的努力,而无所凭藉"}, {"w": "芝艾", "t": "比喻美恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('375wx','朽','1','xiǔ','木','6','','[{"pinyin": "xiǔ", "defs": [{"meaning": "(形声。从木,丂(kǎo)声。本义:腐烂)。"}, {"meaning": "同本义。", "cites": [{"t": "朽,腐也。", "b": "《说文》"}, {"t": "荼蓼朽止。", "b": "《诗·周南·良耜》。释文:“烂也。”"}, {"t": "其臭朽。", "b": "《礼记·月令》。注:“气若有若无为朽。”"}, {"t": "锲而舍之,朽木不折。", "b": "《荀子·劝学》"}, {"t": "朽木不可雕也,粪土之墙不可圬也。", "b": "《论语》"}], "words": [{"w": "朽索", "t": "腐朽的绳子"}, {"w": "朽壤", "t": "腐烂的泥土"}, {"w": "朽木不可雕", "t": "朽木不雕,朽木难雕,朽棘不雕。比喻人不可造就或事物和局势败坏而不可救药"}, {"w": "朽木生花", "t": "喻事物得以新生。"}]}, {"meaning": "衰老;衰弱。", "cites": [{"t": "年朽发落。", "b": "《晋书·隐逸传》"}, {"t": "长安有男儿,二十心己朽。", "b": "李贺《赠陈商》"}, {"t": "臣虽朽迈,敢忘往言?", "b": "《三国志》"}], "words": [{"w": "朽钝", "t": "形容年迈笨拙"}, {"w": "朽迈", "t": "年老"}, {"w": "朽人", "t": "年迈衰老之人。多作谦词"}, {"w": "朽才", "t": "衰弱无能之才,不可造就之才。多用于诮人或自谦。"}]}, {"meaning": "磨灭,消散。", "cites": [{"t": "死且不朽。", "b": "《左传·僖公三十三年》"}, {"t": "传世而不朽。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "朽陈", "t": "指往昔的朝列"}, {"w": "朽散", "t": "离散、散去"}, {"w": "朽劳", "t": "无功之劳。"}]}, {"meaning": "作国画用土笔勾勒草图。", "cites": [{"t": "画之妍丑,岂在朽不朽乎?", "b": "清·方薰《山静居画论》"}], "words": [{"w": "朽炭", "t": "朽墨。作国画勾勒草图用的炭笔"}, {"w": "朽染", "t": "作国画用朽之法"}, {"w": "朽笔", "t": "用木炭作国画起稿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('376wx','朴','1','piáo pō pò pǔ','木','6','','[{"pinyin": "piáo", "defs": [{"meaning": "姓(明代有朴素)。"}]}, {"pinyin": "pō", "defs": []}, {"pinyin": "pò", "defs": [{"meaning": "(形声。左形,右声。古代二字意义不同。“朴”,本义:树皮。《说文》:“木皮也。”王褒《洞箫赋》:“秋蜩不食抱朴而长吟兮。”)。"}, {"meaning": "榆科,朴属植物的泛称 木名,落叶乔木,高五六丈,叶形椭圆而尖,上部缘边有锯齿,花细小,色淡黄。实为球形小肉果,黄赤色,味甘可食。木材可制器具。"}, {"meaning": "大木材。", "cites": [{"t": "材朴委积兮,莫知余之所有。", "b": "《楚辞·屈原·九章》"}]}, {"meaning": "没有晾干的鼠肉。", "cites": [{"t": "郑人谓玉未理者璞,周人谓鼠未腊者朴。", "b": "《战国策·秦策三》"}]}, {"meaning": "质朴", "cites": [{"t": "焚符破玺,而民朴鄙。", "b": "《庄子·胠箧》"}]}]}, {"pinyin": "pǔ", "defs": [{"meaning": "(形声。从木,菐声。本义:未加工的木材)。"}, {"meaning": "同本义。", "cites": [{"t": "朴,木素也。", "b": "《说文》"}, {"t": "既勤朴斫。", "b": "《书·梓材》。马注:“未成器也。”"}, {"t": "朴散则为器。", "b": "《老子》"}, {"t": "无刀斧之断者谓之朴。", "b": "《论衡·量知》"}]}, {"meaning": "本质;本性。", "cites": [{"t": "尚素朴。", "b": "张衡《东京赋》。注:“质也。”"}, {"t": "见素抱朴,少私寡欲。", "b": "《老子》"}]}, {"meaning": "货物的成本。", "cites": [{"t": "贵酒肉之价,重其租,令十倍其朴。", "b": "《商君书·垦令》"}]}, {"meaning": "砍伐整理。", "cites": [{"t": "朴桷不斫。", "b": "《淮南子·精神》。注:“采也。”"}], "words": [{"w": "朴斫", "t": "砍斫,削治。"}]}, {"meaning": "击,打。", "cites": [{"t": "举筑朴秦皇帝。", "b": "《史记·刺客列传》"}, {"t": "…水衡阎奉朴击卖请。", "b": "《史记·酷吏列传》"}]}, {"meaning": "淳朴;朴实。", "cites": [{"t": "敦兮其若朴。", "b": "《老子》"}, {"t": "浇淳散朴。", "b": "《汉书·黄霸传》"}, {"t": "民敦而俗朴。", "b": "《孔子家语·王言》"}], "words": [{"w": "古朴", "t": "朴素而有古代的风格"}, {"w": "质朴", "t": "朴实;不矫饰"}, {"w": "诚朴", "t": "诚恳朴实"}, {"w": "俭朴", "t": "俭省朴素"}, {"w": "朴秀", "t": "朴实而秀美"}, {"w": "朴质", "t": "朴素纯真"}, {"w": "朴讷", "t": "朴实而口才不好"}, {"w": "朴散", "t": "本谓纯真之道分离变异。后亦谓淳朴之风消散"}, {"w": "朴愚", "t": "质朴愚拙"}, {"w": "朴鄙", "t": "质朴鄙野"}, {"w": "朴涩", "t": "质朴迟钝"}, {"w": "朴辞", "t": "质朴而不文饰之辞"}, {"w": "朴赡", "t": "质朴而丰富"}, {"w": "朴木", "t": "质朴厚重"}, {"w": "朴索", "t": "质朴无华"}, {"w": "朴野", "t": "质朴无华。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('377wx','机','1','jī','木','6','','[{"pinyin": "jī", "defs": [{"meaning": "木名。桤木树。", "cites": [{"t": "机,机木。从木,几声。", "b": "《说文》"}, {"t": "单狐之山多机木。", "b": "《山海经·北山经》。注:“似榆,可烧,以粪稻田。”"}, {"t": "春机杨柳。", "b": "左思《蜀都赋》"}]}, {"meaning": "几案,小桌子。", "cites": [{"t": "奔其机。", "b": "《易·涣》。注:“承物者也。”"}, {"t": "公子牟隐机大息,仰天而笑。", "b": "《庄子·秋水》"}, {"t": "围巾几(机)筵。", "b": "《左传·昭公元年》"}], "words": [{"w": "机杖", "t": "几案与手杖"}, {"w": "机案", "t": "泛指案桌"}, {"w": "机筵", "t": "几案和坐席"}, {"w": "机榻", "t": "几案与床榻。"}]}, {"meaning": "(形声。从木,幾(jī)声。本义:弓弩上的发射机关。按:“机”与“機”古代是两个字。“机”本木名,即桤(qī)木树。现在“机”是“機”的简化字)。"}, {"meaning": "同本义。", "cites": [{"t": "主发谓之機。", "b": "《说文》"}, {"t": "耳目,心之枢机也。", "b": "《国语·周语》。注:“枢机,发动也。”"}, {"t": "施关发机。", "b": "《后汉书·张衡传》"}, {"t": "一龙发机。", "b": ""}, {"t": "一龙机发。", "b": ""}, {"t": "机发吐丸。(机关发动吐出铜丸。)", "b": "南朝宋·范晔《后汉书·张衡传》"}], "words": [{"w": "机牙", "t": "机互。弩上发箭的含矢处和钩弦制动的机件"}, {"w": "机括", "t": "机栝。弩上发矢的机件;可开关的机械装置;圈套,计谋;机密,关键"}, {"w": "机郭", "t": "弩上机牙的外壳"}, {"w": "机发", "t": "谓弩机发射。"}]}, {"meaning": "指机械,器械。", "cites": [{"t": "在璇机玉衡。", "b": "《虞书》。马注:“机,浑天仪可旋转,故曰机。”"}, {"t": "公输班为楚设机。", "b": "《战国策·宋策》"}], "words": [{"w": "工作母机;电动机;起重机;柴油机;机石", "t": "古代用机械引发的石头。"}]}, {"meaning": "捕鸟兽的机关。", "cites": [{"t": "机,捕兽机槛也。", "b": "《后汉书·赵壹传》注"}], "words": [{"w": "机弋", "t": "泛指猎取禽兽的器械"}, {"w": "机阱", "t": "圈套;设有机关的捕兽陷阱"}, {"w": "机网;机槛", "t": "设机具捕鸟兽的陷阱。"}]}, {"meaning": "指织机。", "cites": [{"t": "验机杼始出握机矩法。", "b": "《易·通卦》"}, {"t": "多于机上之工女。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "机绝", "t": "织锦的绝巧"}, {"w": "机房仔", "t": "方言。清代纺织工人的俗称"}, {"w": "机神", "t": "织机之神"}, {"w": "机素", "t": "织机上的白绢"}, {"w": "机梭", "t": "即机杼。指织机"}, {"w": "机轴", "t": "织机上卷布帛的部件。"}]}, {"meaning": "事物的关键;枢纽。", "cites": [{"t": "成败之机,在于今日。", "b": "《资治通鉴》"}], "words": [{"w": "机门", "t": "关键,机密所在"}, {"w": "枢机", "t": "事物的关键"}, {"w": "机缄", "t": "原指造成事物变化的造化力量,后用以指运气"}, {"w": "机密房", "t": "机要部门办事处所"}, {"w": "机柄", "t": "权柄;掌握事物关键的重要手段。"}]}, {"meaning": "事物变化之所由。", "cites": [{"t": "皆出于机。", "b": "《列子·天问》。注:“机者,群有之始。”"}, {"t": "万物皆出于机,皆入于机。", "b": "《庄子·至乐》"}], "words": [{"w": "机由", "t": "契机,原由"}, {"w": "机理", "t": "事物变化的道理。"}]}, {"meaning": "先兆,征兆。", "cites": [{"t": "知机其神乎。", "b": "《易·至乐》"}, {"t": "睹其机兆。", "b": "《三国志·蜀书·吴主传》"}], "words": [{"w": "机兆", "t": "先兆"}, {"w": "机道", "t": "事物变化的迹象、征兆"}, {"w": "机微", "t": "事物变化的最初征兆"}, {"w": "机先", "t": "事机萌动未发之时。"}]}, {"meaning": "时机,机会。", "cites": [{"t": "因机变化。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "机不容发", "t": "比喻时机紧迫"}, {"w": "机不旋踵", "t": "比喻时机短暂"}, {"w": "机便", "t": "机会;机宜。"}]}, {"meaning": "心计;心意。", "cites": [{"t": "吾机先被孔明识破。", "b": "《三国演义》"}], "words": [{"w": "机括", "t": "计谋,心思"}, {"w": "机轴", "t": "比喻诗文的构思、词采、风格。"}]}, {"meaning": "机密,机要。多指军国大事。", "cites": [{"t": "助理万机。", "b": "《汉书·百官公卿表》"}]}, {"meaning": "又如:机臣(机要近臣);机廷(掌握军国机杼大事的官署);机任(机要重任);机近(机密近要的地位)。"}, {"meaning": "机巧;机灵灵巧。", "cites": [{"t": "大夫不闻齐、鲁之多机乎?", "b": "《列子·仲尼》"}], "words": [{"w": "机急", "t": "机智敏捷"}, {"w": "机悟", "t": "反应快理解力强"}, {"w": "机捷", "t": "机警敏捷"}, {"w": "机巧心术", "t": "机诈权变的心计"}, {"w": "机带双敲", "t": "用心深沉或语言模棱两口。双敲:双关。"}]}, {"meaning": "危险。", "cites": [{"t": "处高而不机。", "b": "《淮南子·原道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('378wx','权','1','quán','木','6','','[{"pinyin": "quán", "defs": [{"meaning": "(形声。从木,雚（guàn）声。本义:黄花木)。"}, {"meaning": "同本义。", "cites": [{"t": "权,黄华木也。从木,雚声。", "b": "《说文》"}, {"t": "权,黄英。", "b": "《尔雅·释木》。又如:权舆(草木萌发的状态)"}, {"t": "于嗟乎,不承权舆。", "b": "《诗·秦风·权舆》"}, {"t": "于时冰泮发蛰,百草权舆。", "b": "《大戴礼记·诰志》"}]}, {"meaning": "秤。测定物体重量的器具。", "cites": [{"t": "权,称也。", "b": "《论语·尧曰》集解"}, {"t": "锤,谓之权。", "b": "《广雅·释器》"}, {"t": "权者,铢两斤钧石也。", "b": "《汉书·律历志》"}, {"t": "谨权量,审法度。", "b": "《论语·尧曰》"}, {"t": "为之权衡以称之,则并与权衡而窃之。", "b": "《庄子·胠箧》"}, {"t": "谨权量、审法度、修废官,四方之政行焉。", "b": "《论语》"}]}, {"meaning": "亦称秤锤。", "cites": [{"t": "[中春之月]正权概。", "b": "《礼记·月令》"}]}, {"meaning": "权柄,权力。", "cites": [{"t": "大夫执国权。", "b": "《谷梁传》"}, {"t": "权重也。", "b": "《韩非子·五蠹》"}, {"t": "利害之权。", "b": "清·黄宗羲《原君》"}, {"t": "皇上无权。", "b": "清·梁启超《谭嗣同传》"}, {"t": "真无权矣。", "b": ""}], "words": [{"w": "权牟人主", "t": "权力与君王相等"}, {"w": "权珰", "t": "擅权的宦官"}, {"w": "权宠", "t": "权势与宠幸"}, {"w": "权臣", "t": "握有权势而专横的臣子"}, {"w": "掌权;专权", "t": "独揽大权"}, {"w": "兵权", "t": ""}]}, {"meaning": "权宜、变通。", "cites": [{"t": "男女授受不亲,礼也;嫂溺授之以手者,权也。", "b": "《孟子·离娄上》"}], "words": [{"w": "权数", "t": "应变的机智"}, {"w": "权巧", "t": "权宜善巧"}, {"w": "权正", "t": "权变与常道"}, {"w": "权制", "t": "权宜之制"}, {"w": "权计", "t": "权宜之计"}, {"w": "权书", "t": "以权宜之策草拟国书。"}]}, {"meaning": "谋略,计谋。", "cites": [{"t": "三军之权。", "b": "《孙子·谋故》"}], "words": [{"w": "权属", "t": "即权术。有心机有手段"}, {"w": "权士", "t": "谋士"}, {"w": "权用", "t": "谋略、才干。"}]}, {"meaning": "唐以来的称试官或暂时代理官职为“权”。", "cites": [{"t": "韩愈吏部权京兆。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "权官", "t": "指代理之官"}, {"w": "权署", "t": "暂时代理或充任某官职。"}]}, {"meaning": "颧骨。", "cites": [{"t": "明眸善睐,靥辅承权。", "b": "曹植《洛神赋》"}]}, {"meaning": "称量。", "cites": [{"t": "权,然后知轻重;度,然后知长短。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "权称", "t": "用秤称。"}]}, {"meaning": "衡量,比较。", "cites": [{"t": "古人有权成败、计轻重而行之者,伊尹、霍光是也。", "b": "《三国志·武帝纪》注"}, {"t": "且人固难全,权而用其长者。", "b": "《吕氏春秋·举难》"}], "words": [{"w": "权时苟重", "t": "衡量时势而苟且顺从"}, {"w": "权度", "t": "权衡度量"}, {"w": "权量", "t": "犹权衡"}, {"w": "权准", "t": "权衡的准则。"}]}, {"meaning": "平衡。", "cites": [{"t": "九和之弓,角与杆权。", "b": "《周礼》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('379wx','过','1','guò guō','辶','6','','[{"pinyin": "guò", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,咼(guā)声。本义:走过,经过)。"}, {"meaning": "同本义。", "cites": [{"t": "过,度也。", "b": "《说文》"}, {"t": "禹八年于外,三过其门而不入。", "b": "《孟子·滕文公上》"}, {"t": "雷霆乍惊,宫车过也。", "b": "杜牧《阿房宫赋》"}, {"t": "有过于江上者,见人方引婴儿而欲投之江中。", "b": "《吕氏春秋·察今》"}, {"t": "行过夷门,见侯生。", "b": "《史记·魏公子列传》"}], "words": [{"w": "过江;过马路;从这条街上过;从他门前过;路过", "t": "途中经过"}, {"w": "过翼", "t": "经过的飞鸟"}, {"w": "过宾", "t": "路过的宾客"}, {"w": "过处", "t": "经过之处"}, {"w": "过来过往", "t": "来往经过"}, {"w": "过阴", "t": "到阴间走一趟。"}]}, {"meaning": "超出,胜过。", "cites": [{"t": "从此道至吾军,不过二十里耳。", "b": "《史记·项羽本纪》"}, {"t": "力能扛鼎,才气过人。", "b": ""}, {"t": "大都不过参国之一。", "b": "《左传·隐公元年》"}, {"t": "一出门,裘马过世家焉。", "b": "《聊斋志异·促织》"}, {"t": "古之人所以大过人者,无他焉,善推其所为而已矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "过如", "t": "超过;胜过"}, {"w": "过了漕", "t": "过了漕运期限"}, {"w": "过情", "t": "超过实际"}, {"w": "过实", "t": "超过实际情况"}, {"w": "过绝", "t": "超越;超过。"}]}, {"meaning": "过去(过后)。", "cites": [{"t": "天子偶用一物,未必不过此已忘。", "b": "《聊斋志异·促织》"}, {"t": "花过而采,则根色黯恶,此其效也。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "三伏已过;雨过天晴;过迹", "t": "过去的形迹"}, {"w": "过景", "t": "过时;不应景"}, {"w": "过逝", "t": "流逝。很快地过去"}, {"w": "过郤", "t": "过去。"}]}, {"meaning": "给予;递给。", "cites": [{"t": "邮人之过书,门者之传教也。", "b": "《论衡》"}, {"t": "予亦谓之过。辰州人谓以物予人曰过。", "b": "《通雅》"}], "words": [{"w": "过度", "t": ""}]}, {"meaning": "渡过。", "cites": [{"t": "野市分獐闹,官帆过渡迟。", "b": "宋·苏轼《荆州》"}], "words": [{"w": "过索", "t": "渡河之绳索"}, {"w": "过江", "t": "渡过长江。"}]}, {"meaning": "转移;过渡。", "cites": [{"t": "买的房子已付款,只是过户手续还未办理好", "b": ""}, {"t": "过录底稿", "b": ""}], "words": [{"w": "过龙", "t": "经手递送贿赂"}, {"w": "过处", "t": "词的上下片过渡之处。亦称“过片”。"}]}, {"meaning": "度过;过活。", "cites": [{"t": "吾家后日当甚贫,贫无所苦,清静过日而已。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "过阴天儿", "t": "休息"}, {"w": "过老", "t": "度晚年"}, {"w": "过日", "t": "度日;生活"}, {"w": "过遣", "t": "打发日子,消磨时光。"}]}, {"meaning": "来访;前往拜访;探望。", "cites": [{"t": "于是乘其车,揭其剑,过其友。", "b": "《战国策·齐策四》"}, {"t": "自迎嬴于众人广坐之中,不谊有所过,今公子故过之。", "b": "《史记·魏公子列传》"}], "words": [{"w": "过临", "t": "光临;惠临"}, {"w": "过款", "t": "过访"}, {"w": "过晤", "t": "前往会见。"}]}, {"meaning": "交往,相处。", "cites": [{"t": "稍喜过从近,扶筇不驾车。", "b": "宋·黄庭坚《次韵德孺五丈新居病起》"}, {"t": "过从甚密", "b": ""}], "words": [{"w": "过逢;过从", "t": "互相交往"}, {"w": "过会", "t": "农家亲朋每年定期聚会的日子,或公社每年举行庙会的节日。"}]}, {"meaning": "错,犯错误。", "cites": [{"t": "微二人,寡人几过。", "b": "《吕氏春秋·审应览·具备》"}, {"t": "人恒过,然后能改。", "b": "《孟子·告子下》"}, {"t": "(赵太后)曰:“君过矣,不若长安石之甚。”", "b": "《战国策·赵策》"}]}, {"meaning": "怪罪,责难。", "cites": [{"t": "孔子曰:“求,无乃尔是过与?(这恐怕应该责备你吧!)”", "b": "《论语·季氏》"}, {"t": "闻大王有意督过之,脱身得去,已至军矣。", "b": "《史记·项羽本纪》"}], "words": [{"w": "不过", "t": "不怪罪"}, {"w": "过谪", "t": "责备;怪罪"}, {"w": "过適", "t": "怪罪,责难。"}]}, {"meaning": "继入、赘入或嫁人。", "cites": [{"t": "孩儿也,他如今只待过门,喜事匆匆的,教我怎生回得他去。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "过嗣", "t": "过继"}, {"w": "过给", "t": "过继。"}]}, {"meaning": "传递。", "cites": [{"t": "他这个人喜欢过嘴,你说话可要注意", "b": ""}], "words": [{"w": "过盏", "t": "敬酒"}, {"w": "过嘴", "t": "传话"}, {"w": "过语", "t": "传话"}, {"w": "过书", "t": "传递书信"}, {"w": "过气", "t": "传送气息以交配"}, {"w": "过状", "t": "递交文状、诉状。"}]}, {"meaning": "无意的犯法或作恶行为;错误。", "cites": [{"t": "过,罪愆也。", "b": "《说文》"}, {"t": "出入禁闼,补过拾遗。", "b": "《史记·汲黯列传》"}, {"t": "过则无惮改。", "b": "《论语·学而》"}, {"t": "夫过有厚薄,则刑有轻重。", "b": "《商君书·开塞》"}, {"t": "刑过不避大夫,赏善不遗匹夫。", "b": "《韩非子·有度》"}, {"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·齐策》"}, {"t": "然而累汝至此者,未尝非予之过也。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "过愆", "t": "过失;罪咎"}, {"w": "过恶", "t": "过错"}, {"w": "勇于改过;知过必改;过行", "t": "过失行为"}, {"w": "过计", "t": "估计错误。"}]}, {"meaning": "灾殃。", "cites": [{"t": "八曰诛以驭其过。", "b": "《周礼·天官·大宰》"}], "words": [{"w": "大过", "t": "大灾大祸。"}]}, {"meaning": "过分;过于;太甚。", "cites": [{"t": "以其境过清,不可久居,乃记之而去。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "古者天下之人爱戴其君,比之如父母;拟之如天,诚不过也。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "过爱", "t": "过分的爱"}, {"w": "过余", "t": "过分"}, {"w": "过头话", "t": "过分的大话。"}]}]}, {"pinyin": "guō", "defs": [{"meaning": "古国名 ,在今山东省掖县稍西北近海处。", "cites": [{"t": "处浇于过,处豷于戈。", "b": "《左传·襄公四年》"}]}, {"meaning": "姓,过国之后。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('380wx','臣','1','chén','臣','6','','[{"pinyin": "chén", "defs": [{"meaning": "(象形。甲骨文字形,象一只竖立的眼睛形。人在低头时,眼睛即处于竖立的位置,字形正表示了俯首屈从之意。本义:男性奴隶)。"}, {"meaning": "同本义。", "cites": [{"t": "臣,事君者也。象屈服之形。", "b": "《说文》"}, {"t": "仕于公曰臣。", "b": "《礼记·礼运》"}, {"t": "事君不贰是谓臣。", "b": "《国语·晋语》"}, {"t": "臣治烦去惑者也。", "b": "《左传·成公二年》"}, {"t": "臣妾逋逃。", "b": "《书·费誓》。郑注:“臣妾,厮役之属也。”"}, {"t": "臣则左之。", "b": "《礼记·少仪》。注:“谓囚俘。”"}, {"t": "虽臣虏之劳不苦于此矣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "臣妾", "t": "古时对奴隶的称谓。男曰臣,女曰妾"}, {"w": "臣役", "t": "泛指奴仆"}, {"w": "臣御", "t": "臣妾仆御"}, {"w": "臣宰", "t": "本指奴隶。后亦以称辅佐帝王的臣佐。"}]}, {"meaning": "君主制时的官吏。", "cites": [{"t": "今功臣名将,雁行有序。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "侍卫之臣不懈于内。", "b": "诸葛亮《出师表》"}], "words": [{"w": "臣门如市", "t": "形容官宦门下钻营者极多,竟像集市一样热闹"}, {"w": "臣下", "t": "臣子。君主制时代的官吏"}, {"w": "臣人", "t": "臣下。"}]}, {"meaning": "君主制时的高级官员;大臣。", "cites": [{"t": "侍中、尚书、长史、参军,此悉忠良死节之臣。", "b": "诸葛亮《出师表》"}], "words": [{"w": "忠臣;奸臣", "t": ""}]}, {"meaning": "古人自称。"}, {"meaning": "古代大臣对君的自称。", "cites": [{"t": "臣窃见先帝欲开西域。", "b": "《后汉书·班超传》"}], "words": [{"w": "臣下", "t": "古时官吏对君主的自称。"}]}, {"meaning": "对父的自称。", "cites": [{"t": "始大人常以臣无赖。", "b": "《史记·高帝纪》"}]}, {"meaning": "对一般人的自称。表示自谦。", "cites": [{"t": "臣少好相人,相人多矣,无如季相。", "b": "《史记》"}]}, {"meaning": "臣服。", "cites": [{"t": "匈奴背叛不臣。", "b": "《盐铁论·本议》"}, {"t": "而欲以力臣天下之主。", "b": "《战国策·秦策》。注:“服也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('381wx','吏','1','lì','口','6','','[{"pinyin": "lì", "defs": [{"meaning": "(会意。甲骨文。从手(又),从中。以手持中。有人认为中为笔。“吏”、“事”、“使”古同字。本义:官吏)。"}, {"meaning": "官员的通称。汉以后,指低级官员或吏卒。", "cites": [{"t": "吏,治人者也。", "b": "《说文》"}, {"t": "吏者,名之师也。", "b": "《汉书·景帝纪》"}, {"t": "吏所以治民也。", "b": "《汉书·惠帝纪》"}, {"t": "吏者,民之所悬命也。", "b": "《管子·朋法》"}, {"t": "王使委于三吏。", "b": "《左传·成公二年》。注:“二三公也。”"}, {"t": "百吏庶民。", "b": "《国语·周语》"}, {"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·齐策》"}, {"t": "据法守职不敢为非者,人吏也。", "b": "《韩诗外传》"}, {"t": "君既为府吏,守节情不移。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "量其家之所有以为剂,而官与吏剖分焉。", "b": "方苞《狱中杂记》"}], "words": [{"w": "吏势", "t": "官吏的权势力量"}, {"w": "吏议", "t": "官吏商讨政事;处分官吏;拟议定罪"}, {"w": "吏司", "t": "管理司法案牍的官"}, {"w": "吏兵", "t": "官吏和士兵"}, {"w": "吏舍", "t": "官吏居住或办公的房子。汉以后只指一般的小官员或吏卒。"}]}, {"meaning": "专指官府中的胥吏或差役。", "cites": [{"t": "暮投石壕村,有吏夜捉人。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "吏目", "t": "八九品小官。又指地位在御医之下的一般医生"}, {"w": "吏员", "t": "古代地方官府的小吏"}, {"w": "胥吏", "t": "小官吏"}, {"w": "狱吏", "t": "旧时管理监狱的小官。"}]}, {"meaning": "吏部狱。", "cites": [{"t": "而右将军独下吏,当死,赎为庶人。", "b": "班固《汉书》"}]}, {"meaning": "治理;为官。", "cites": [{"t": "夫吏者,理也。", "b": "《汉书·王莽传下》"}, {"t": "是为长吏。", "b": "《汉书·百官公卿表上》"}, {"t": "吏,所以治民也。", "b": "《汉书·惠帝纪》"}, {"t": "宦游非吏隐,心事好幽偏。", "b": "宋之问《蓝田山庄》"}], "words": [{"w": "吏才", "t": "为政的才能"}, {"w": "吏方", "t": "为政的方略"}, {"w": "吏道", "t": "官吏处理政务之道"}, {"w": "吏隐", "t": "闲居下级官位"}, {"w": "吏材", "t": "为政的才干。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('382wx','再','1','zài','冂','6','','[{"pinyin": "zài", "defs": [{"meaning": "(会意。小篆:从一,冓(gòu)省。“冓”是“构”的初文,甲骨文字形,象两部分材木架起的样子。本义:第二次)。"}, {"meaning": "同本义。", "cites": [{"t": "再,一举而二也。", "b": "《说文》。按,冓者,加也。对耦之词曰二,重叠词曰再。"}, {"t": "再刺再宥再赦。", "b": "《周礼·司刺》"}, {"t": "樊缨十有再就。", "b": "《周礼·巾车》"}, {"t": "酒肉之赐弗再拜。", "b": "《礼记·玉藻》"}, {"t": "过言不再。", "b": "《礼记·儒行》。注:“犹不更也。”"}, {"t": "一鼓作气,再而衰,三而竭。", "b": "《左传·庄公十年》"}, {"t": "再战而烧夷陵。", "b": "《史记·平原君虞卿列传》"}, {"t": "再迁为太史令。", "b": "《后汉书·张衡传》"}, {"t": "敌枪再击。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "再则曰老大帝国。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "再录一堂", "t": "复审一次"}, {"w": "再速", "t": "再请"}, {"w": "再二", "t": "第二次,再次"}, {"w": "再之", "t": "第二次,第三次"}, {"w": "再眠", "t": "指蚕第二次蜕皮时的不食不动状态。"}]}, {"meaning": "两次。", "cites": [{"t": "女工再税。", "b": "《盐铁论·本议》"}, {"t": "击赵者再。", "b": "宋·苏洵《六国论》"}, {"t": "日再食。", "b": "明·宋濂《送东阳马生序》"}, {"t": "再夺门。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "至再三。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "事情或行为重复,继续。", "cites": [{"t": "她不敢再看一看那大庙。", "b": "叶紫《星》"}], "words": [{"w": "再试一次;拿来再商量;再议;再思", "t": "再度思考"}, {"w": "再聘", "t": "再度婚娶"}, {"w": "再阐", "t": "再度显扬。"}]}, {"meaning": "重,重新。", "cites": [{"t": "勿复再言。", "b": "《汉书·李广苏建传》"}, {"t": "再火令药用。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "再眺山下。", "b": "《徐霞客游记·游黄山记》"}, {"t": "寰再上疏。", "b": "《明史》"}], "words": [{"w": "再计", "t": "重新谋划"}, {"w": "再审", "t": "重新审查。"}]}, {"meaning": "更,更加 ——表示程度。", "cites": [{"t": "你会觉得世界末日也不会比这再坏。", "b": "茅盾《雷雨前》"}], "words": [{"w": "再高点儿;再多点儿", "t": ""}]}, {"meaning": "与否定词配合使用,强调情况的普遍性。", "cites": [{"t": "进了门,找周嫂子,再找不着。", "b": "《红楼梦》"}]}, {"meaning": "用于让步句,常同“也”、“都”配合使用,有“即使多么”、“不管怎样”的意思。", "cites": [{"t": "水再深脚也能过,山再高手也能攀。", "b": "《赶车传》"}]}, {"meaning": "表示转折,相当于“却”、“也”。", "cites": [{"t": "你只怨人行动嗔怪你,你再不知道你怄的人难受。", "b": "《红楼梦》"}]}, {"meaning": "表示两种行为或情状并举、并存、相当于“且…且”、“又…又”。", "cites": [{"t": "其词旨乃典乃文,再恳再切,实可警策未悟。", "b": "《全唐文纪事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('383wx','协','1','xié','十','6','','[{"pinyin": "xié", "defs": [{"meaning": "(会意。从办,从十。办亦声。办(xié)表示同力。十,表示众多。合起来表示众人同力。本义:和睦;融洽)。"}, {"meaning": "同本义。", "cites": [{"t": "協,众之同和也。", "b": "《说文》"}, {"t": "协和万邦。", "b": "《书·尧典》。传:“合也。”"}, {"t": "协用五纪。", "b": "《书·洪范》。传:“和也。”"}, {"t": "今刘表新亡,二子不协。", "b": "《资治通鉴》"}, {"t": "与彼协心。", "b": ""}, {"t": "协规同力。", "b": ""}, {"t": "声律相协而八音生。", "b": "《太玄·数》"}], "words": [{"w": "协允", "t": "合理公平"}, {"w": "协气", "t": "和气"}, {"w": "协恭", "t": "友好而同心协力"}, {"w": "协睦;协畅;协调;协泰", "t": "协和安泰。"}]}, {"meaning": "合;共同。", "cites": [{"t": "纪农协功。", "b": "《国语·周语》。注:“同也。”"}, {"t": "尔无共怒,协比谗言予一人。", "b": "《书·盘庚下》。孔传:“汝无共怒我,合比凶人而妄言。”"}], "words": [{"w": "协谋", "t": "共同谋略"}, {"w": "协爱", "t": "共同热爱"}, {"w": "协庆", "t": "共同庆贺"}, {"w": "协比", "t": "勾结在一起做坏事。即朋比。"}]}, {"meaning": "调和;调整。", "cites": [{"t": "协此四国。", "b": "《礼记·孔子闲居》"}], "words": [{"w": "协正", "t": "调整而使之正确"}, {"w": "协序", "t": "调和使有规律"}, {"w": "协律", "t": "调和音乐律吕,使之和谐"}, {"w": "协顺", "t": "调和使如意。"}]}, {"meaning": "顺服。", "cites": [{"t": "上帝时歆,下民祗协。", "b": "《书·微子之命》"}], "words": [{"w": "协从;协附", "t": "依附"}, {"w": "协服", "t": ""}]}, {"meaning": "用同“胁”。逼迫。", "cites": [{"t": "余皆协从。", "b": "《金声玉振集》"}]}, {"meaning": "符合。", "cites": [{"t": "实有爽德,协于丹朱。", "b": "《国语·周语上》"}], "words": [{"w": "协韵", "t": "符合韵律"}, {"w": "协义", "t": "符合礼义"}, {"w": "协句", "t": "协韵"}, {"w": "协中", "t": "符合中庸。"}]}, {"meaning": "清末新军的编制单位,在镇之下。三营为标,两标一协。相当于后代的旅。", "cites": [{"t": "那本标三营,分防二协,都受他调遣。", "b": "《儒林外史》"}], "words": [{"w": "协台", "t": "副将。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('384wx','西','1','xī','覀','6','','[{"pinyin": "xī", "defs": [{"meaning": "(象形。据小篆字形,上面是鸟的省写,下象鸟巢形。“西”是“栖”的本字。本义:鸟入巢息止)。"}, {"meaning": "同本义。", "cites": [{"t": "西,鸟在巢上,象形。", "b": "《说文》"}, {"t": "棹歌惊起乱西禽,女伴各归南浦。", "b": "《敦煌曲子词集》"}], "words": [{"w": "西迟", "t": "游息,流连。同栖迟。"}]}, {"meaning": "往西走;向西去。", "cites": [{"t": "西通巴蜀。", "b": "《三国志·诸葛亮传》"}, {"t": "何时复西归。", "b": "《乐府诗集·长歌行》"}, {"t": "从小丘西行……", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "西出阳关无故人。", "b": "唐·王维《送元二使安西》"}], "words": [{"w": "西上", "t": "向西去"}, {"w": "西驾", "t": "皇帝的车驾西行"}, {"w": "西夕", "t": "太阳西下而天黑。"}]}, {"meaning": "方位词。日落的方向,西方。", "cites": [{"t": "日在西方而鸟栖,故因以为东西之西。", "b": "《说文》"}, {"t": "王用享于西山。", "b": "《易·随》"}, {"t": "宅西。", "b": "《书·尧典》"}, {"t": "以白琥礼西方。", "b": "《周礼·大宗伯》"}, {"t": "赵王因起兵南戍韩梁之西边。", "b": "《战国策·赵策一》"}, {"t": "故有东宫、有西宫、有南宫、有北宫,异居而同财,有余则归之宗,不足则资之宗。", "b": "《仪礼·丧服》"}], "words": [{"w": "西班", "t": "武官。唐凡朝会,武官班于西"}, {"w": "各奔西东", "t": "各奔前程"}, {"w": "西帮", "t": "经营钱庄业的山西人"}, {"w": "西都", "t": "古指洛阳"}, {"w": "西裔", "t": "西部边远地区"}, {"w": "西牛贺洲", "t": "佛经中四大部洲之一,在西方。"}]}, {"meaning": "古称西边的邻国。", "cites": [{"t": "越山千万云门绝,西僧貌古还名月。", "b": "唐·皎然《寄题云门寺梵月无侧房》"}], "words": [{"w": "西僧", "t": "西蕃僧人"}, {"w": "西人", "t": "宋时指西夏人。"}]}, {"meaning": "现代我国称欧美为“西洋”或“泰西”,简称“西”。", "cites": [{"t": "初中西不睦,地方官出示,禁止华人受雇外洋,供其服役。", "b": "清·夏燮《粤民义师记》"}], "words": [{"w": "西珠", "t": "西洋商人贩运到中国来的珍珠"}, {"w": "西番柿子", "t": "番茄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('385wx','压','1','yā yà','厂','6','','[{"pinyin": "yā", "defs": [{"meaning": "(形声。从土,厌声。本义:崩坏)。"}, {"meaning": "同本义。", "cites": [{"t": "压,坏也。", "b": "《说文》"}, {"t": "侨将压焉。", "b": "《左传·襄公三十一年》"}, {"t": "吾惧压焉。", "b": "《国语·鲁语》。注:“笮也。”"}, {"t": "壤压之变。", "b": "欧阳修《新唐书》"}], "words": [{"w": "压溺", "t": "土崩和水淹。"}]}, {"meaning": "从上往下增加重力,加压。", "cites": [{"t": "千朵万朵压枝低。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "黑云压城城欲摧。", "b": "李贺《雁门太守行》"}], "words": [{"w": "压肩叠背", "t": "肩靠肩背挨背,形容人群拥挤"}, {"w": "压山探海", "t": "形容人数众多"}, {"w": "压尺", "t": "用金属或玉石做成的压纸用的尺状文具"}, {"w": "压枝", "t": "果实多,把树枝压低。"}]}, {"meaning": "压抑,压制;逼迫。", "cites": [{"t": "举杰压陛。", "b": "《楚辞·大招》"}, {"t": "予以大国压之。", "b": "《公羊传·文公十四年》"}, {"t": "克压帝心。", "b": "《繁阳令杨君碑》"}, {"t": "陵压百姓。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "压倒", "t": "压服;制服"}, {"w": "压良为贱", "t": "掠买平民子女为奴婢。"}]}, {"meaning": "杀。", "cites": [{"t": "且臣闻齐、卫先君刑马压羊。", "b": "《战国策》"}], "words": [{"w": "压羊", "t": "杀羊。"}]}, {"meaning": "逼近。", "cites": [{"t": "楚晨压晋军而陈。", "b": "《左传·襄公二十六年》"}], "words": [{"w": "压黑", "t": "临近天黑的时候"}, {"w": "压山", "t": "方言,谓日将落山。"}]}, {"meaning": "超越;胜于。", "cites": [{"t": "声不能压当世。", "b": "柳宗元《与萧翰林俛书》"}], "words": [{"w": "压倒元白", "t": "指诗文超过著名诗人白居易和元禛"}, {"w": "压轴戏(亦称压台戏,压轴子,指一次戏曲演出中的倒数第二个节目(最后的一出戏叫大轴子", "t": ""}, {"w": "现多指一台戏中放在最后的一出,谓其质量最高,表演最精彩,足以压住全台)", "t": ""}]}, {"meaning": "覆盖,笼罩。", "cites": [{"t": "覆压三百余里。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "压纽", "t": "覆压在璧纽上"}, {"w": "压覆", "t": "埋没;困顿"}, {"w": "压蔓,压青", "t": "把绿肥作物或采集的野草、树叶埋在田地里做肥料。"}]}, {"meaning": "镇住。", "cites": [{"t": "就安排筵席,一者与夫人压惊,二者庆贺这玉梳。", "b": "《古金杂剧》"}], "words": [{"w": "压物", "t": "镇压邪魔之物"}, {"w": "压镇", "t": "镇服"}, {"w": "压车", "t": "谓随车保护或坚守。"}]}, {"meaning": "压力。"}]}, {"pinyin": "yà", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('386wx','厌','1','yā yàn','厂','6','','[{"pinyin": "yā", "defs": [{"meaning": "一物压在另一物上。", "cites": [{"t": "厌,笮也。", "b": "《说文》。段注:“此义今人字作压,乃古今字之殊。”"}, {"t": "地震陇西,厌四百余家。", "b": "《汉书·五行志下之上》"}, {"t": "如墙厌之。", "b": "《荀子·彊国》"}, {"t": "厌目而视者,视一以为两。", "b": "《荀子·解蔽》"}], "words": [{"w": "厌覆", "t": "车翻人压。"}]}, {"meaning": "泛指压制;抑制。", "cites": [{"t": "东厌诸侯之权,西远羌胡之难。——《汉书·翼奉传》。——师古曰:“厌,抑也。”", "b": ""}, {"t": "故贤人立朝,折冲厌难,胜于亡形。", "b": "《汉书·辛庆忌传》。师古曰:“厌,抑也。”"}], "words": [{"w": "厌抑", "t": "压制。"}]}, {"meaning": "以迷信的方法,镇服或驱避可能出现的灾祸,或致灾祸于人。", "cites": [{"t": "秦始皇帝常曰:“东南有天子气”,于是因东游以厌之。", "b": "《史记·高祖纪》"}], "words": [{"w": "厌法", "t": "厌胜法。是一种用咒符来制服对手的巫术。"}]}, {"meaning": "堵塞。", "cites": [{"t": "厌其源,开其渎。", "b": "《荀子·修身》。注:“厌,塞也。”"}]}]}, {"pinyin": "yàn", "defs": [{"meaning": "(形声。从厂(hǎn),猒(yàn)声。厂,象山崖石穴形。《说文》:“厌,笮也。”意思是“压”。由“犬、肉、甘”三部分合起来,会意,表示“吃饱”、“满足”。本义:吃饱)。"}, {"meaning": "饱,满足", "cites": [{"t": "学而不厌,诲人不倦,何有于我哉?", "b": "《论语》"}, {"t": "不厌。", "b": "《左传·僖公三十三年》"}, {"t": "秦之欲无厌。", "b": "宋·苏洵《六国论》"}, {"t": "求之者无厌。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "厌极", "t": "满足穷尽"}, {"w": "厌饫", "t": "吃饱;吃腻;满足"}, {"w": "厌塞", "t": "满足"}, {"w": "厌伪", "t": "对奸邪巧伪感到满意"}, {"w": "厌恋", "t": "以此为满足而眷恋"}, {"w": "厌副", "t": "满足"}, {"w": "厌足", "t": "满足。"}]}, {"meaning": "憎恶;嫌弃。", "cites": [{"t": "人常厌事。", "b": "清·梁启超《谭嗣同传》"}, {"t": "惟厌事也。", "b": ""}, {"t": "犹厌言兵。", "b": "宋·姜夔《扬州慢》"}, {"t": "无厌其为迂。", "b": "明·宗臣《报刘一丈书》"}, {"t": "这儿我住厌了。", "b": "曹禺《雷雨》"}], "words": [{"w": "厌世", "t": "现世;出丑露乖"}, {"w": "厌厌地", "t": "无精打采地;微弱的样子"}, {"w": "厌物", "t": "骂人话,指讨人厌的东西"}, {"w": "厌钝", "t": "讨厌,扫兴"}, {"w": "厌色", "t": "厌烦、不满的脸色"}, {"w": "厌苦", "t": "厌烦以为苦事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('387wx','戌','1','qu xū','戈','6','','[{"pinyin": "qu", "defs": [{"meaning": "——见“屈戌儿”（qūqur）。"}]}, {"pinyin": "xū", "defs": [{"meaning": "(指事。从戊,含一。不详。戊(wù)武器。本义:地支的第十一位)。"}, {"meaning": "戌时。", "cites": [{"t": "明日大利,宜用戌亥时。", "b": "《三国演义》"}], "words": [{"w": "戌亥时", "t": "戌时与亥时。"}]}, {"meaning": "夏正建寅,九月为戌。", "cites": [{"t": "九月之辰谓为戌,戌者灭也,谓时物皆衰灭也。", "b": "《晋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('388wx','在','1','zài','土','6','','[{"pinyin": "zài", "defs": [{"meaning": "(形声。小篆字形。从土,才声。表示草木初生在土上。本义:存活着,生存,存在)。"}, {"meaning": "同本义。", "cites": [{"t": "在,存也。", "b": "《说文》。按,字从土,与坐同意。"}, {"t": "见龙在田。", "b": "《易·乾》"}, {"t": "父母在,不远游。", "b": "《论语·里仁》"}, {"t": "疾在腠理。", "b": "《韩非子·喻老》"}, {"t": "病在肌肤。", "b": ""}, {"t": "则无所不在。", "b": "《淮南子·原道》"}, {"t": "在往者,在来者。", "b": "《大戴礼·曾子立事》"}], "words": [{"w": "在生日", "t": "在世时"}, {"w": "祖父已经不在了;在日", "t": "在世之日"}, {"w": "在堂", "t": "母亲健在"}, {"w": "父母健在", "t": ""}]}, {"meaning": "居于,处于。", "cites": [{"t": "朕在位七十载。", "b": "《书·尧典》"}, {"t": "在河之洲。", "b": "《诗·周南·关雎》"}, {"t": "公在乾侯。", "b": "《春秋·昭公三十年》"}, {"t": "在冀州之南。", "b": "《列子·汤问》"}, {"t": "平原不在。", "b": "《世说新语·自新》"}, {"t": "人在室中。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "其在一室。", "b": ""}], "words": [{"w": "文件在桌上;在侍", "t": "儿女在父母身旁"}, {"w": "在室", "t": "女子未婚"}, {"w": "在丧", "t": "居丧。"}]}, {"meaning": "在于;决定于。", "cites": [{"t": "山不在高。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "水不在深。", "b": ""}, {"t": "不在他人。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "全在我少年。", "b": ""}], "words": [{"w": "贵在坚持;这事在你自己;要学习好,主要在自己努力;在道", "t": "在于正道。"}]}, {"meaning": "省视;观察。", "cites": [{"t": "存往者,在来者。", "b": "《大戴礼记》"}]}, {"meaning": "存问,问候。", "cites": [{"t": "寡人淹恤在外,二三子皆使寡人朝夕闻卫国之言,吾子独不在寡人。", "b": "《左传·襄公二十六年》"}]}, {"meaning": "到。", "cites": [{"t": "把橹一摇,那小船早荡在江心里去。", "b": "《水浒传》"}]}, {"meaning": "表示动作、情状所涉及的处所、时间、范围等。", "cites": [{"t": "宜在今日。", "b": "《资治通鉴》"}, {"t": "便在前发。", "b": ""}, {"t": "在药则未为良时。(在药就药材来说。)", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "在研究所工作;在梦中;在夜里;在某种情况下;在斯", "t": "在这里"}, {"w": "在道", "t": "正在途中"}, {"w": "在里", "t": "在军中;在里"}, {"w": "在假", "t": "在假期中"}, {"w": "在官言官", "t": "官:古地存放档案的机构。引申为地方。在什么地方处在什么地位说什么话"}, {"w": "在堂", "t": "在屋里。"}]}, {"meaning": "从。", "cites": [{"t": "正在五岳楼下来,撞见个诈奸不及的,把娘子拦住不肯放。", "b": "《水浒传》"}]}, {"meaning": "才;正在。", "words": [{"w": "在建造", "t": ""}]}, {"meaning": "用在动词后面表示可能,相当于“得”。", "cites": [{"t": "诗酒尚堪驱使在,未须料理白头人。", "b": "唐·杜甫《江畔独步寻花》"}]}, {"meaning": "表示一定的语气。", "cites": [{"t": "烦君惜此根株在,乞与伶伦学凤凰。", "b": "王安石《华严院此君亭》"}]}, {"meaning": "相当于“着”。", "cites": [{"t": "料想双亲像,他每留在。", "b": "《琵琶记》"}]}, {"meaning": "地方;处。", "cites": [{"t": "吾犹不能之(到)在。", "b": "王充《论衡》"}, {"t": "无日不营,无在不卫。", "b": "《辽史·营卫志上》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('389wx','百','1','bǎi','白','6','','[{"pinyin": "bǎi", "defs": [{"meaning": "(会意。从一,从白。“白”假借为“百”。本义:数词)。"}, {"meaning": "十个十。一百,100。", "cites": [{"t": "百,十十也。", "b": "《说文》"}, {"t": "律中百钟。", "b": "《淮南子·时则》"}, {"t": "虽人有百手,手有百指,不能指其一端。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "百辆之迎", "t": "用隆重仪式迎娶新妇"}, {"w": "百日", "t": "一百天;人死后的一百天,请僧道诵经或作道场"}, {"w": "百户", "t": "一百户人家;统兵百人之官。"}]}, {"meaning": "概数。言其多,许多的,众多的。", "cites": [{"t": "千禄百福。", "b": "《诗·大雅·假乐》"}, {"t": "将军百战死,壮士十年归。", "b": "《乐府诗集·木兰诗》"}, {"t": "猿则百叫无绝。", "b": "吴均《与朱元思书》"}], "words": [{"w": "百花争艳;百发百中;百官", "t": "众官"}, {"w": "百事", "t": "众多的事物。"}]}, {"meaning": "多种多样的;各种的。", "cites": [{"t": "百计营谋不得脱。", "b": "《聊斋志异·促织》"}], "words": [{"w": "百像图", "t": "各种人物的画像,是专供临摹影像的范本"}, {"w": "百般", "t": "各种不同的情态。"}]}, {"meaning": "所有;一切;凡。", "cites": [{"t": "社稷百官皆在。", "b": "清·侯方域《壮悔堂集》"}], "words": [{"w": "百业;百口", "t": "整个家族"}, {"w": "百工;百川归海", "t": "比喻众望所归。"}]}, {"meaning": "增为百倍。", "cites": [{"t": "如可赎兮,人百其身。", "b": "《诗·秦风·黄鸟》"}, {"t": "人一能之,己百之。", "b": "《礼记·中庸》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('390wx','有','1','yǒu yòu','月','6','','[{"pinyin": "yǒu", "defs": [{"meaning": "(会意。金文字形,从又(手)持肉,意思是手中有物。本义:具有,与“无”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "有,不宜有也。春秋传曰:“日月有食之。”", "b": "《说文》。按,掩日者月也。故许云月有食之,犹言日有食之月食之也。"}, {"t": "一有一亡曰有。", "b": "《谷梁传·庄公二十八年》"}, {"t": "大有众也。", "b": "《易·杂卦》"}, {"t": "有备无患。", "b": "《左传·襄公十一年》"}, {"t": "天若有情天亦老。", "b": "李贺《金铜仙人辞汉歌》"}], "words": [{"w": "有来有去", "t": "有板有眼"}, {"w": "有命无运", "t": "谓命好,运气却不好"}, {"w": "有酒胆无饭力", "t": "表面刚强,骨子里懦弱"}, {"w": "有竡划没是处", "t": "虽有安排,但无法实现。喻指无处下手之意"}, {"w": "有尺水行尺船", "t": "指量力而行"}, {"w": "有天无日头", "t": "天色已晚"}, {"w": "有腿没裤子", "t": "形容很穷"}, {"w": "有气的死人", "t": "比喻人无本事,不起什么作用"}, {"w": "有门楹人家(有声望、有地位的人家;官宦之家)有些头脸(有面子", "t": ""}, {"w": "有怀莫逐", "t": "有厚望不能实现"}, {"w": "有心计儿", "t": "有主意;有心眼"}, {"w": "有眼色", "t": "有眼力;有眼光"}, {"w": "有针线", "t": "有主意;有心眼"}, {"w": "有字号", "t": "有名气的店铺"}, {"w": "有出息", "t": "有才能;会办事"}, {"w": "有口舌", "t": "有口才;能言善辩"}, {"w": "有生之年", "t": "指人活着的岁月"}, {"w": "有缘千里来相会", "t": "人与人之间只要有缘分,即使相离很远也会相见。"}]}, {"meaning": "存在。", "cites": [{"t": "东有启明,西有长庚。", "b": "《诗·小雅》"}, {"t": "天下万物生于有,有生于无。", "b": "《老子》"}], "words": [{"w": "有想头", "t": "有利可图"}, {"w": "有讲究", "t": "有问题"}, {"w": "有肚皮", "t": "有默契;有深交"}, {"w": "有虞", "t": "有误"}, {"w": "有等", "t": "有些"}, {"w": "有偏", "t": "心地不公正"}, {"w": "有味", "t": "有利益;有油水"}, {"w": "有间", "t": "有区别;不同"}, {"w": "有分", "t": "有机会;有希望"}, {"w": "有服", "t": "亲属死后正在服丧期间"}, {"w": "有事", "t": "隐指有暧昧关系"}, {"w": "有首尾", "t": "有不正当关系"}, {"w": "有神没气", "t": "没有生气"}, {"w": "有负众望", "t": "辜负众人的期望"}, {"w": "有差", "t": "有区别,不一。"}]}, {"meaning": "取得,获得,占有。", "cites": [{"t": "若据而有之,此帝王之资也。", "b": "《资治通鉴》"}], "words": [{"w": "有功", "t": "有功劳,有功绩"}, {"w": "有根有苗", "t": "有根据,有线索"}, {"w": "有根有底", "t": "有根有据"}, {"w": "有福同享,有祸同当", "t": "有幸福共同享受,有灾难共同担当"}, {"w": "有娠", "t": "怀孕"}, {"w": "有理走遍天下", "t": "只要有道理,任何地方都行得通。"}]}, {"meaning": "相当于“或”。或许。", "cites": [{"t": "由是则生,而有不用也(有,或,有的人)。", "b": "《孟子·告子上》"}]}, {"meaning": "附着在动词、名词、形容词前,相当于词缀,无实际意义。", "cites": [{"t": "舜伐有苗…汤代有夏。", "b": "《荀子·议兵》"}]}]}, {"pinyin": "yòu", "defs": [{"meaning": "", "cites": [{"t": "割地朝者三十有六国。", "b": "《韩非子·五蠹》"}, {"t": "序八州而朝同列,百有余年矣。", "b": "汉·贾谊《过秦论》"}, {"t": "亡国之恨顿生,檀板之声无色,有非莫生之言可尽言者矣。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "对联、题名并篆文,为字共三十有四。", "b": "清·张潮《虞初新志·魏学·核舟记》"}, {"t": "以八月十三日斩于市,春秋三十有三。", "b": "清·梁启超《谭嗣同传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('391wx','存','1','cún','子','6','','[{"pinyin": "cún", "defs": [{"meaning": "(形声。本义:生存;存在)。"}, {"meaning": "同本义。", "cites": [{"t": "存,存在也。", "b": "《尔雅》。注:“存即在。”"}, {"t": "有天子存。", "b": "《公羊传·隐公三年》"}, {"t": "虽存乎人者。", "b": "《孟子·告子上》"}, {"t": "以其存心也。", "b": "《孟子·离娄下》"}, {"t": "召寇则无以存矣。", "b": "《吕氏春秋·应同》"}, {"t": "虽我之死,有子存焉。", "b": "《列子·汤问》"}, {"t": "而吾以捕蛇独存。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "存济", "t": "存活;活命"}, {"w": "存殁", "t": "活着的和死去的。"}]}, {"meaning": "恤问,劳问。", "cites": [{"t": "存,恤问也。", "b": "《说文》"}, {"t": "无一介之使以存之。", "b": "《战国策·秦策》。注:“劳问也。”"}], "words": [{"w": "存候", "t": "存问,问候"}, {"w": "存问", "t": "安慰,问候"}, {"w": "存抚", "t": "存问安抚"}, {"w": "存养", "t": "安抚养育。"}]}, {"meaning": "访问;问候。", "cites": [{"t": "存问长老。", "b": "《汉书·文帝纪》。注:“省视也。”"}, {"t": "臣乃市井鼓刀者,而公子亲数存之。", "b": "《史记·魏公子列传》"}], "words": [{"w": "存见", "t": "探望慰问"}, {"w": "存访", "t": "探望问候"}, {"w": "存谕", "t": "存问、慰谕。"}]}, {"meaning": "思念;怀念。", "cites": [{"t": "五曰存爱。", "b": "《礼记·大传》"}, {"t": "其存君兴国而欲反复之,一篇之中致志焉。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "存眷", "t": "思念,关注"}, {"w": "存想", "t": "考虑,思索,想像"}, {"w": "存注", "t": "意念,注意力"}, {"w": "存追", "t": "追念,追慕。"}]}, {"meaning": "储存;保存;保全。", "cites": [{"t": "或仅存姓名而无事迹。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "存志", "t": "保全志向"}, {"w": "封存", "t": "封闭起来保存"}, {"w": "存安", "t": "使之保全。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('392wx','而','1','ér néng','而','6','','[{"pinyin": "ér", "defs": [{"meaning": "(象形。小篆字形,象胡须形。上面的“一”表示鼻端,“|”表示人中;下面分内外两层,外层象两腮的胡子,内层象生在嘴下的胡子。“而”是汉字部首之一。本义:颊毛) 同本义。", "cites": [{"t": "而,颊毛也。", "b": "《说文》"}]}, {"meaning": "从古沿用下来的连词,可连接词、短语和分句,表示多种关系。"}, {"meaning": "表示并列关系。", "cites": [{"t": "永州之野产异蛇,黑质而白章。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "表示递进关系。", "cites": [{"t": "君子博学而日参省乎己。", "b": "《荀子·劝学》"}]}, {"meaning": "表示承接关系。", "cites": [{"t": "余方心动欲还,而大声发于水上。", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "表示转折关系。", "cites": [{"t": "青,取之于蓝,而青于蓝。", "b": "《荀子·劝学》"}]}, {"meaning": "表示假设关系。", "cites": [{"t": "诸君而(如果)有意;瞻余马首可也。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "表示修饰关系,连接状语。", "cites": [{"t": "吾恂恂而起。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "你;你的。", "cites": [{"t": "予岂不知而作。", "b": "《诗·大雅·桑柔》"}, {"t": "余知而无罪也。", "b": "《左传·昭公二十年》"}, {"t": "子归,殁而父母之世。", "b": "《国语·吴语》"}, {"t": "尽于酒肉,入于鼻口矣,而何足以知其所自来?", "b": "《庄子·徐无鬼》"}, {"t": "而翁归,自与汝复算耳。", "b": "《聊斋志异·促织》"}], "words": [{"w": "而翁", "t": "你的父亲。"}]}, {"meaning": "这样,此。", "cites": [{"t": "同是被逼迫,君而妾亦然。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "而夫", "t": "此人;这人。"}]}, {"meaning": "表示偏正关系,相当于“之”,“的”。", "cites": [{"t": "虞之与虢,相恃而势。", "b": "《淮南子·人间》"}]}, {"meaning": "与“上”、“下”、“前”、“后”、“来”、“往”连用,相当于“以”。", "cites": [{"t": "形而上者谓之道,形而下者谓之器。", "b": "《易·系辞上》"}]}, {"meaning": "用于句中,表示反问,相当于“难道”,“岂”。", "cites": [{"t": "为仁由己,而由人乎哉?", "b": "《论语·颜渊》"}]}, {"meaning": "用于句末,相当于“耳”,“哪”。", "cites": [{"t": "已而已而,今之从政者殆而。", "b": "《论语·微子》"}]}, {"meaning": "如,好象。", "cites": [{"t": "溺死者千有余人,军惊而坏都舍。", "b": "《吕氏春秋》"}]}]}, {"pinyin": "néng", "defs": [{"meaning": ""}, {"meaning": "才能。", "cites": [{"t": "然计天下之所以治者,何也?唯而以尚同一义为政故也。", "b": "《墨子·尚同下》"}, {"t": "戒之戒之,微而异之。", "b": "《管子·枢言》。微而,犹无能。而、能古字通用"}, {"t": "小白承天子之命而毋下拜。", "b": "《管子·小匡》"}, {"t": "不待我而有成事者也。", "b": "《商君书·慎法》"}]}, {"meaning": "能够。", "cites": [{"t": "桀纣幽厉……不而矫其耳目之欲。", "b": "《墨子·非命下》"}, {"t": "不逢汤武与恒缪兮,也孰去而知之?《楚辞·九章·惜往日》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('393wx','页','1','yè','页','6','','[{"pinyin": "yè", "defs": [{"meaning": "(象形。小篆字形。上面是“首”,下面是“人”,“头”的本字。本读xié。“页”是汉字的一个部首。从“页”的字都与头面有关。①本义:人头。②引申义:书页)。"}, {"meaning": "书页。", "cites": [{"t": "嶪,枼也。", "b": "《说文》。段玉裁注:“小儿所书写,每一页谓之一葉,今书一纸谓之一页。或作葉,其实当作枼。”"}], "words": [{"w": "页子", "t": "书页。"}]}, {"meaning": "量词。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('394wx','匠','1','jiàng','匚','6','','[{"pinyin": "jiàng", "defs": [{"meaning": "(会意。从匚(fāng),盛放工具的筐器,从斤(斧)。工具筐里放着斧头等工具,表示从事木工。本义:木工)。"}, {"meaning": "同本义。", "cites": [{"t": "匠,木工也。", "b": "《说文》"}, {"t": "攻木之工七:轮、舆、弓、庸、匠、车、梓。匠人建国,匠人营国,匠人为沟洫。", "b": "《考工记》"}, {"t": "执斧以涖匠师。", "b": "《周礼·乡师》。注:“主丰碑之事。”"}, {"t": "遂匠纳车于阶间。", "b": "《仪礼·既夕记》。注:“匠人主载柩窆。”"}], "words": [{"w": "匠氏", "t": "木匠"}, {"w": "匠者", "t": "木工"}, {"w": "匠营", "t": "土木工。"}]}, {"meaning": "亦泛指工匠。", "cites": [{"t": "能剒削柱梁谓之木匠;能穴凿穴埳谓之土匠,能雕琢文书谓之史匠。", "b": "《论衡·量知》"}], "words": [{"w": "匠作", "t": "工匠,以技艺做工谋生的人"}, {"w": "匠役", "t": "工匠,做工的仆役"}, {"w": "匠户", "t": "世业的工匠"}, {"w": "匠指", "t": "工匠"}, {"w": "匠门弃材", "t": "比喻无用之人,自称的谦词。"}]}, {"meaning": "治理。", "cites": [{"t": "匠,治也。", "b": "《小尔雅》"}], "words": [{"w": "匠世", "t": "治世"}, {"w": "匠理", "t": "精心治理。"}]}, {"meaning": "教。", "cites": [{"t": "今私门之正匠兮。", "b": "《楚辞·哀命》。注:“教也。”"}], "words": [{"w": "匠化", "t": "教化"}, {"w": "匠成", "t": "培养造就。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('395wx','夸','1','kuā','大','6','','[{"pinyin": "kuā", "defs": [{"meaning": "(形声。从大,于声。本义:奢侈)。"}, {"meaning": "同本义。", "cites": [{"t": "夸,奢也。", "b": "《说文》"}, {"t": "贵而不为夸。", "b": "《荀子·仲尼》。注:“奢侈也。”"}], "words": [{"w": "夸丽", "t": "虚美浮华"}, {"w": "夸侈", "t": "奢侈,浮华"}, {"w": "夸恣", "t": "奢侈放纵。"}]}, {"meaning": "自大;炫耀。", "cites": [{"t": "华言无实曰夸。", "b": "《周书·谥法》"}, {"t": "富有天下而不聘夸。", "b": "《吕氏春秋·下贤》。注:“诧而自大也。”"}, {"t": "石崇以奢靡夸人。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "夸奓", "t": "自大。"}]}, {"meaning": "大。", "cites": [{"t": "夸,大也。", "b": "《广雅·释诂一》"}, {"t": "夸者死权。", "b": "《史记·屈原贾生列传》。集解:“泰也。”"}, {"t": "妾夸布服,粝食。", "b": "班固《汉书》"}, {"t": "齐有狗盗之子与刖危子戏而相夸。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "夸节", "t": "大节,高尚的节操"}, {"w": "夸谈", "t": "大言,夸夸其谈。"}]}, {"meaning": "假借为“誇”。虚,空。", "cites": [{"t": "故古之人有不肯贵富者矣,由重生故也,非夸以名也,为其实也。", "b": "《吕氏春秋》。注:“虚也。”"}]}, {"meaning": "柔弱", "cites": [{"t": "形夸骨佳。", "b": "刘安《淮南子》"}], "words": [{"w": "夸布", "t": "大布,粗布。"}]}, {"meaning": "美好。", "cites": [{"t": "曼颊皓齿,形夸骨佳。", "b": "《淮南子·姱务》"}, {"t": "夸容乃理。", "b": "晋·傅毅《舞赋》"}], "words": [{"w": "形夸", "t": "体形美好"}, {"w": "夸容", "t": "美丽的容貌。"}]}, {"meaning": "(形声。从言,夸声。本义:把事情说得或做得超过了原有程度,不符合实际)。"}, {"meaning": "同本义。", "cites": [{"t": "自矜曰誇。", "b": "《通俗文》"}, {"t": "誇,大言也。", "b": "《字林》"}, {"t": "万物均既誇众矣。", "b": "《管子·白心》。注:“大也。”"}, {"t": "上将大誇。", "b": "《文选·扬雄·长杨赋序》。注:“誇,大言也。”"}, {"t": "伐败。", "b": "《公羊传·庄公九年》。注:“自誇大其伐。”"}, {"t": "虽势尊衣美,不以夸贱欺贫。", "b": "《韩非子·解老》"}], "words": [{"w": "夸诈", "t": "吹嘘欺骗"}, {"w": "夸诞", "t": "说话荒诞不经"}, {"w": "夸谈设嘴", "t": "吹嘘;夸口"}, {"w": "夸诩", "t": "骄傲自夸,炫耀"}, {"w": "人人都夸他爱劳动;夸耀", "t": "骄傲自夸;炫耀"}, {"w": "夸容", "t": "骄傲、炫耀、自夸自大之色。"}]}, {"meaning": "扩大,张大。", "cites": [{"t": "《春秋》谨严,《左氏》浮夸。", "b": "韩愈《进学解》"}]}, {"meaning": "(kuà)。兼有。", "cites": [{"t": "而藩国大者,夸州兼郡,连城数十。", "b": "《汉书·诸侯王表序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('396wx','夺','1','duó','大','6','','[{"pinyin": "duó", "defs": [{"meaning": "(会意。金文字形,上面象振翅欲飞的鸟,下面是手(又、寸),其意思是:这只振翅欲飞的鸟,眼看着就要从手中失脱掉。本义:丧失)。"}, {"meaning": "同本义。", "cites": [{"t": "夺,手持隹失之也。", "b": "《说文》"}, {"t": "给夺慈仁。", "b": "《礼记·仲尼燕居》。注:“犹乱也。”"}, {"t": "精气夺则虚。", "b": "《素问·通评虚实论》"}, {"t": "三军可夺帅也,匹夫不可夺志也。", "b": "《论语·子罕》"}, {"t": "勿夺农时。", "b": "《荀子·富国》"}], "words": [{"w": "夺宗", "t": "始封的国君被尊为诸侯以后,除去原来宗子的名分"}, {"w": "夺气", "t": "丧失了胆量和勇气"}, {"w": "夺魄", "t": "精神丧失而无生气"}, {"w": "夺胆", "t": "丧胆"}, {"w": "夺彩", "t": "失出光彩。"}]}, {"meaning": "强取。", "cites": [{"t": "夺,取也。", "b": "《玉篇》"}, {"t": "人夺女妻而不怒。", "b": "《左传·文公十八年》"}, {"t": "夺其印符。", "b": "《史记·淮阴侯列传》"}, {"t": "夺攘矫虔。", "b": "《书·吕刑》"}, {"t": "秦王度之,终不可夺。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "夺项王天下者,必沛公也。", "b": "《史记·项羽本纪》"}], "words": [{"w": "夺转", "t": "夺得"}, {"w": "夺劝", "t": "一边劝一边夺拿"}, {"w": "夺情", "t": "皇帝特许某些有亲丧的官僚不守孝,或者未满守孝期者复取。意思是夺去了他的哀思之情"}, {"w": "夺席", "t": "夺取他人的席位。"}]}, {"meaning": "竞先取得。", "cites": [{"t": "被泽徒深厚,惭无夺锦才。", "b": "高启《谢赐衣》"}], "words": [{"w": "夺高产;夺魁", "t": "夺取第一"}, {"w": "夺却", "t": "夺去;占去"}, {"w": "夺衣", "t": "夺袍。喻在诗文竞赛中获胜"}, {"w": "夺锦", "t": "夺取锦标。"}]}, {"meaning": "剥夺;削除。", "cites": [{"t": "胁服夺(罢免)其官。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "夺褫", "t": "剥夺"}, {"w": "夺爵;夺休", "t": "旧指女方提出离婚"}, {"w": "夺俸", "t": "官吏犯罪,被罚扣薪饷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('397wx','灰','1','huī','火','6','','[{"pinyin": "huī", "defs": [{"meaning": "(会意。从手,从火。意思是火已熄灭,可以用手去拿。本义:火灰)。"}, {"meaning": "同本义。", "cites": [{"t": "灰,死火余烬也。", "b": "《说文》"}, {"t": "毋烧灰。", "b": "《礼记·月令》。注:“火之灭者为灰。”"}, {"t": "火过为灰。", "b": "《字汇》"}, {"t": "春蚕到死丝方尽,蜡炬成灰泪始干。", "b": "李商隐《无题》"}, {"t": "满面尘灰烟火色。", "b": "唐·白居易《卖炭翁》"}, {"t": "纸灰之类。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "灰飞烟灭。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "灰灭", "t": "灰没。像灰烬般地被消灭"}, {"w": "灰榇", "t": "盛放骨灰的木匣,亦指骨灰"}, {"w": "灰罐", "t": "灰礶。盛墨的罐子"}, {"w": "灰枵", "t": "灰烬和腐木。喻消亡"}, {"w": "灰火", "t": "火灰"}, {"w": "灰末", "t": "灰粉。"}]}, {"meaning": "灰尘。", "cites": [{"t": "民间食盐,杂以灰土。", "b": "《宋史·食货志》"}, {"t": "已衄而灰。", "b": "《韩非子·说林上》"}, {"t": "素醰灰丝。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "路上都是灰;灰壤", "t": "尘埃"}, {"w": "灰朴朴", "t": "尘垢满身;土头土脑"}, {"w": "灰头灰脸", "t": "满面风尘的样子。"}]}, {"meaning": "灰浆。", "cites": [{"t": "和灰", "b": ""}]}, {"meaning": "灰色。白色和黑色的混合色。", "cites": [{"t": "面色灰死。", "b": "《聊斋志异·促织》"}], "words": [{"w": "灰黪", "t": "暗灰色"}, {"w": "灰鼠", "t": "灰色松鼠;也指灰鼠皮"}, {"w": "灰不答", "t": "形容颜色陈旧暗淡"}, {"w": "灰黑", "t": "浅黑色。"}]}, {"meaning": "烧毁;燃烧。", "cites": [{"t": "不灰之木。", "b": "《抱朴子·释滞》"}], "words": [{"w": "灰焚", "t": "焚烧成灰,烧光"}, {"w": "灰死", "t": "烧死;火灰熄灭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('398wx','达','1','dá','辶','6','','[{"pinyin": "dá", "defs": [{"meaning": "(形声。从辵(chuò),羍声。本义:道路畅通)。"}, {"meaning": "同本义。泛指畅通。", "cites": [{"t": "达,行不相遇也。", "b": "《说文》"}, {"t": "达,通也。", "b": "《广雅》"}, {"t": "左右达为夹室,所以相隔。", "b": "《礼记·内则》"}, {"t": "寡人其达王于甬句东。", "b": "《国语·吴语》"}, {"t": "达四聪。", "b": "《虞书》"}, {"t": "达于河。", "b": "《书·禹贡》"}, {"t": "七曰达吏。", "b": "《周礼·大宰》"}, {"t": "下达。", "b": "《仪礼·士昏礼》"}, {"t": "天下达道。", "b": "《礼记·中庸》"}, {"t": "唯恐道途显晦,不相通达。", "b": "唐·李朝威《柳毅传》"}, {"t": "屋极有窗以达气。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "四通八达;达越", "t": "疏通瑟底之孔使其声迟重"}, {"w": "达乡", "t": "相对而畅达的窗户。"}]}, {"meaning": "到达,通到。", "cites": [{"t": "凉州之兵始达咸阳。", "b": "《资治通鉴》"}, {"t": "路旁一歧东上,乃昔所未至者,遂前趋直上,几达天都侧。", "b": "《徐霞客游记·游黄山记》"}, {"t": "万人凿盘石,无由达江浒。", "b": "李白《丁都护歌》"}, {"t": "指通豫南,达于汉阴。", "b": "《列子·汤问》"}, {"t": "日与其徒置酒酣歌达曙。", "b": "清·方苞《狱中杂记》"}, {"t": "自昏达曙,目不交睫。", "b": "《聊斋志异·促织》"}], "words": [{"w": "小麦亩产达千斤;达济", "t": "渡水到达彼岸"}, {"w": "达标", "t": "达到规定的标准。"}]}, {"meaning": "通达事理;通晓,见识高远。", "cites": [{"t": "有达于理者,得不恐而畏乎?", "b": "柳宗元《送薛存义序》"}, {"t": "都给事中舒化论瑞迂滞不达政体。", "b": "《明史·海瑞传》"}], "words": [{"w": "达者", "t": "通达事理的人"}, {"w": "达才", "t": "通达事理的人"}, {"w": "达臣", "t": "通达义理的臣子"}, {"w": "达言", "t": "通达事理的言论"}, {"w": "达见", "t": "洞晓事物的道理。"}]}, {"meaning": "通晓事理,理解,明白。", "cites": [{"t": "所赖君子安贫,达人知命。", "b": "王勃《滕王阁序》"}], "words": [{"w": "达心", "t": "心里明白通达"}, {"w": "达生", "t": "能参透人生,了解性命的本质"}, {"w": "达权", "t": "明白权宜的道理,能临急应变。"}]}, {"meaning": "荐举。", "cites": [{"t": "在位多所荐达。", "b": "《后汉书·黄香传》"}], "words": [{"w": "达能", "t": "举荐有才能的人"}, {"w": "达吏", "t": "向上举荐官吏。"}]}, {"meaning": "将意思表达出来。", "cites": [{"t": "子曰:“辞达而已矣。”", "b": "《论语·卫灵公》"}], "words": [{"w": "转达", "t": "把一方的意思告诉另一方"}, {"w": "达旨", "t": "表达思想"}, {"w": "达诚", "t": "表达诚挚之情"}, {"w": "达善", "t": "表达善意"}, {"w": "达信", "t": "传达消息"}, {"w": "达知", "t": "通知;告知。"}]}, {"meaning": "通行的;共同的。", "cites": [{"t": "知、仁勇三者,天下之达德也。", "b": "《礼记·中庸》"}], "words": [{"w": "达尊", "t": "天下人公认的尊贵事物"}, {"w": "达孝", "t": "天下共认的最大孝道"}, {"w": "达制", "t": "通行的制度。"}]}, {"meaning": "显达(地位高而有名声)。", "cites": [{"t": "不求闻达于诸侯。", "b": "诸葛亮《出师表》"}], "words": [{"w": "达遂", "t": "显达顺遂"}, {"w": "达宦", "t": "职位显要的官吏"}, {"w": "达官贵人", "t": "地位高的官吏和尊贵显赫的人物。"}]}, {"meaning": "地名 。今四川省达县。"}, {"meaning": "形容物体相碰时发出的声响。", "cites": [{"t": "达、达、达,泥浆直溅。", "b": "叶圣陶《寒假的一天》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('399wx','列','1','liè','刂','6','','[{"pinyin": "liè", "defs": [{"meaning": "(形声。从刀,本义:割,分)。"}, {"meaning": "“裂”的古字。分割;分解。", "cites": [{"t": "列,分解也。", "b": "《说文》"}, {"t": "古者列地建国。", "b": "《荀子》"}, {"t": "大袂列。", "b": "《管子·五辅》。注:“决之也。”"}, {"t": "两骖列两服入厩。", "b": "《荀子·哀公》。?"}], "words": [{"w": "列断", "t": "裂断"}, {"w": "列地", "t": "列土。分地封侯"}, {"w": "列缺", "t": "高空中闪电所现出的空隙闪电"}, {"w": "列土分茅", "t": "古代帝王用茅土分封诸侯的仪式。"}]}, {"meaning": "排列。", "cites": [{"t": "列敌度宜谓之义。", "b": "《太玄·玄摛》。注:“序也。”"}, {"t": "森然布列。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "张筵列鼎。", "b": "清·周容《芋老人传》"}, {"t": "奇峰错列。", "b": "《徐霞客游记·游黄山记》"}, {"t": "江岸列营。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "列树", "t": "成列的树木"}, {"w": "列石", "t": "排列成行的石块"}, {"w": "列待", "t": "排列待立"}, {"w": "列炬", "t": "排列火炬"}, {"w": "列秧", "t": "按品级排列。"}]}, {"meaning": "陈列;摆开。", "cites": [{"t": "小者坐列贩卖。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "列缋", "t": "陈列绘画"}, {"w": "列兵", "t": "陈兵,驻扎军队"}, {"w": "列罗", "t": "陈列"}, {"w": "列卒", "t": "陈兵布阵"}, {"w": "列陈", "t": "摆开阵势。陈,通“阵”。"}]}, {"meaning": "安排;给予。", "cites": [{"t": "如谥,臣子所谏列也,诔生时所行,为之谥。", "b": "王充《论衡》"}]}, {"meaning": "布置。", "cites": [{"t": "太尉列卒取(捉拿)十七人。", "b": "柳宗元《段太尉逸事状》"}]}, {"meaning": "对立。", "cites": [{"t": "故下与官列法,上与君分威。", "b": "《管子》"}], "words": [{"w": "列眉", "t": "两眉对列。"}]}, {"meaning": "开列。", "cites": [{"t": "列贾五百金。", "b": "崔铣《记王忠肃公翱三事》"}], "words": [{"w": "列为甲等", "t": ""}]}, {"meaning": "假借为“迾”。遮遏,阻止。", "cites": [{"t": "山泽列而不赋。", "b": "《礼记·玉藻》"}]}, {"meaning": "排列有序的行列(竖排称“行”,横排称“列”)。", "cites": [{"t": "火三列。", "b": "《礼记·丧大记》。疏:“行也。”"}, {"t": "其土堰前列、伏水火而死者,不可胜数也。", "b": "《墨子·兼爱下》"}, {"t": "是以差轮爪牙之士,比列其舟车之卒。", "b": "《墨子·天志下》"}, {"t": "故仁人用兵,聚则成卒,散则成列。", "b": "《荀子·议兵》"}, {"t": "陈力就列。", "b": "《论语·季氏》"}, {"t": "比诸侯之列。", "b": "《战国策·燕策》"}, {"t": "既济,而未成列。", "b": "《左传·僖公二十二年》"}, {"t": "今井阱之道,车不得方轨,骑不得成列。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "第三列;列从", "t": "行列相从"}, {"w": "列树", "t": "成行的树木"}, {"w": "列列", "t": "行列分明。"}]}, {"meaning": "职务;职位。", "cites": [{"t": "入而未定列。", "b": "《左传·僖公十五年》"}, {"t": "轻重以列。", "b": "《左传·昭公十三年》。注:“位也。”"}, {"t": "翟无列于王室。", "b": "《国语·周语》。注:“位次也。”"}, {"t": "上官大夫与之同列。", "b": "《史记·屈原列传》"}, {"t": "相如每朝时,常称病,不欲与廉颇争列。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "列籍", "t": "名列;位列。"}]}, {"meaning": "店肆。", "cites": [{"t": "小者坐列贩卖。", "b": "《汉书·食货志上》"}]}, {"meaning": "序次。", "cites": [{"t": "以日星为纪,故事可列。", "b": "《礼记·礼运》"}], "words": [{"w": "列坐", "t": "列席,在座的人"}, {"w": "列次", "t": "次第,排列顺序。"}]}, {"meaning": "假借为“烈”。功业。", "cites": [{"t": "贪夫徇财兮,列士殉名。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "众,各。", "cites": [{"t": "富于列国之君。", "b": "《史记·货殖列传》"}], "words": [{"w": "列民", "t": "犹众民"}, {"w": "列邦", "t": "各国"}, {"w": "列臣", "t": "诸大臣"}, {"w": "列列", "t": "众多"}, {"w": "列都", "t": "各城邑。"}]}, {"meaning": "假借为“洌”。水清醇,洁净。", "cites": [{"t": "天地干燥,水纠列之时也。", "b": "《管子·度地》"}]}, {"meaning": "依次。", "cites": [{"t": "华月照方池,列坐金殿侧。", "b": "汉·刘桢《感遇》"}], "words": [{"w": "列拜", "t": "依次叩拜"}, {"w": "列席", "t": "列坐。依次而坐"}, {"w": "列序", "t": "依次排列。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('400wx','死','1','sǐ','歹','6','','[{"pinyin": "sǐ", "defs": [{"meaning": "(会意。小篆字形。右边是人,左边是“歺”(è),残骨,指人的形体与魂魄分离。本义:生命终止)。"}, {"meaning": "同本义。", "cites": [{"t": "死,民之卒事也。", "b": "《说文》"}, {"t": "死者,人之终也。", "b": "《列子·天瑞》"}, {"t": "庶人曰死。", "b": "《礼记·曲礼》"}, {"t": "沁人曰死。", "b": "《礼记·檀弓》"}, {"t": "民知不死,其亦夫有奋心。", "b": "《左传·哀公十六年》"}, {"t": "楚令尹死。—《左传·昭公二十三年》", "b": ""}, {"t": "予之及于死者不知其几矣!", "b": "宋·文天祥《指南录·后序》"}, {"t": "亡何国变,宁南死。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "死生", "t": "死亡和生存"}, {"w": "死过", "t": "死去,去世"}, {"w": "死限", "t": "死期,寿命的期限"}, {"w": "死却", "t": "死去;死掉"}, {"w": "死不残", "t": "半死不活;不中用"}, {"w": "死去还魂", "t": "死去活来"}, {"w": "死费尽残", "t": "半死不活"}, {"w": "死数里算帐", "t": "离死期不远"}, {"w": "死耗", "t": "死亡的消息"}, {"w": "死君", "t": "死去的国君。"}]}, {"meaning": "为某事或某人而牺牲性命。", "cites": [{"t": "今亡亦死,举大计亦死,等死,死国可乎?", "b": "《史记·陈涉世家》"}], "words": [{"w": "死义", "t": "为信守节义而死"}, {"w": "死难;死节", "t": "以一死保全节操"}, {"w": "死士", "t": "誓死效劳之士。"}]}, {"meaning": "穷,尽。", "cites": [{"t": "战余落日黄,军败鼓声死。", "b": "常建《吊王将军墓》"}, {"t": "讹言“苍天已死,黄天当立,岁在甲子,天下大吉。”", "b": "《后汉书》"}]}, {"meaning": "拼死,拼命。", "cites": [{"t": "于是乃废文任武,厚养死士,缀甲厉兵,效胜于战场。", "b": "《战国策·秦策》"}, {"t": "上欲陵死战,召陵母及妇,使相者视之,无死丧色。", "b": "《汉书·李广传》"}], "words": [{"w": "死战:死守;死杀", "t": "死命拼杀。"}]}, {"meaning": "死板,不灵活。", "cites": [{"t": "人画竹梢死羸垂,萧画枝活叶叶动。", "b": "白居易《画竹歌》"}], "words": [{"w": "死水;死法", "t": "固定、死板的方法"}, {"w": "死心眼;死画", "t": "呆板而不具灵性的画"}, {"w": "死规矩;死教条;死口", "t": "不可改变的话"}, {"w": "死格", "t": "死板的格式"}, {"w": "死办法;死临侵", "t": "亦作“死淋侵。”死呆呆毫无生气的样子。"}]}, {"meaning": "牢牢固定的;移动不了或极难移动的。", "cites": [{"t": "与顿丘李奖一面,便定死交。", "b": "《北齐书·宋游道传》"}], "words": [{"w": "死扣儿;窗子钉死了;死结;死心搭地", "t": "死心落地。不作他想,实心实意"}, {"w": "死桩", "t": "死木头;木头疙瘩。"}]}, {"meaning": "甚;极。", "cites": [{"t": "这添添小哥哥,今年十三岁,天生的甚是聪明,父亲欢喜死他。", "b": "杨文奎《儿女团圆》"}], "words": [{"w": "死急", "t": "极其急迫"}, {"w": "死要面子;高兴死了;累得要死;累死了;死沉;高兴死了", "t": ""}]}, {"meaning": "死刑。", "cites": [{"t": "君子以议狱缓死。", "b": "《易·中孚》"}]}, {"meaning": "尸体。", "cites": [{"t": "生拘白乞而问白公之死焉。", "b": "《左传·哀公十六年》"}, {"t": "汉遣使三辈至唐居,求谷吉等死。", "b": "《汉书·陈汤传》"}, {"t": "安所求子死?", "b": "《汉书·尹赏传》"}]}, {"meaning": "主,主管。", "cites": [{"t": "一爱相若,其类在死也。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('401wx','成','1','chéng','戈','6','','[{"pinyin": "chéng", "defs": [{"meaning": "(会意。甲骨文字形,从“|”(即“杵”)。“斧”、“杵”具备就可以做成事情。本义:完成,成就)。"}, {"meaning": "同本义。", "cites": [{"t": "成,就也。", "b": "《说文》"}, {"t": "成德之终也。", "b": "《国语·周语》"}, {"t": "成者功就不可易也。", "b": "《太元元错》"}, {"t": "箫韶九成。", "b": "《书·益稷》"}, {"t": "祝告曰利成。", "b": "《仪礼·少牢礼》"}, {"t": "及事成。", "b": "《周礼·司书》"}, {"t": "此织生自蚕茧,成于机杼。", "b": "《后汉书·列女传》"}], "words": [{"w": "落成", "t": "建筑物完工。"}]}, {"meaning": "变成;成为。", "cites": [{"t": "累寸不已,遂成丈匹。", "b": "《后汉书·列女传》"}], "words": [{"w": "成习", "t": "成为习惯"}, {"w": "成精;成仙", "t": "成为神仙。"}]}, {"meaning": "形成。", "cites": [{"t": "好鸟相鸣,嘤嘤成韵。", "b": "吴均《与朱元思书》"}], "words": [{"w": "成市", "t": "形成市场"}, {"w": "成列", "t": "形成队列"}, {"w": "成体", "t": "构成形体。"}]}, {"meaning": "事物生长到一定的状态;长成。", "cites": [{"t": "五谷萎败不成。", "b": "《吕氏春秋·明理》"}, {"t": "用实者成实时采。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "依新已五岁,转眼成人。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "树立。", "cites": [{"t": "以成伯王之名。", "b": "《战国策·秦策》。注:“立也。”。又如:成名成家(树立名声,成为专家);成果(造就,创建)"}]}, {"meaning": "平定;讲和。", "cites": [{"t": "会于稷,以成宋乱。", "b": "《左传·成公十一年》"}, {"t": "遂使之行成于吴。", "b": "《国语·越语》"}]}, {"meaning": "成功。", "cites": [{"t": "成败之机,在于今日。", "b": "《资治通鉴》"}], "words": [{"w": "成败", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('402wx','夹','1','jiā jiá gā','大','6','','[{"pinyin": "jiā", "defs": [{"meaning": "(会意。甲骨文字形,象左右二人从两边辅助中间一个人。本义:从左右两方相持,从两旁限制)。"}, {"meaning": "从两旁钳住。", "cites": [{"t": "夹,持也。从大挟二人。会意。", "b": "《说文》"}, {"t": "尔曷不夹介又我周王。", "b": "《书·多方》"}, {"t": "左右夹佩。", "b": "《穆天子传》"}, {"t": "怀为夹。", "b": "《周礼·梓材》"}, {"t": "使吾二婢子夹我。", "b": "《礼记·檀弓》"}, {"t": "夹大铁椎。", "b": "明·魏禧《大铁椎传》"}, {"t": "两竿夹揭。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "夹拥", "t": "左右围抱。"}]}, {"meaning": "栽插在物体的两边。", "cites": [{"t": "墙下当官道,依前夹竹篱。", "b": "姚合《原上新居》"}]}, {"meaning": "带;沿靠。", "cites": [{"t": "夹江傍山。", "b": "《文选·左思·蜀都赋》"}], "words": [{"w": "夹江", "t": "濒临江水,沿着江水"}, {"w": "夹单", "t": "夹放在手本第一幅里的单帖。"}]}, {"meaning": "辅佐。", "cites": [{"t": "五侯九伯,女实征之,以夹辅周室。", "b": "《左传》"}], "words": [{"w": "夹辅", "t": "共同辅佐"}, {"w": "夹介", "t": "犹言辅佐"}, {"w": "夹助", "t": "辅助"}, {"w": "夹持", "t": "犹夹辅,匡助。"}]}, {"meaning": "掺杂;混杂。", "cites": [{"t": "又夹百千求救声。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": " 夹和", "t": "乱七夹八"}, {"w": "夹叙夹议", "t": "边叙述边议论。"}]}, {"meaning": "处在两旁的。", "cites": [{"t": "引申为凡物在左右之称。", "b": "《说文》徐锴注"}, {"t": "圉人夹牵之。", "b": "《仪礼·既夕礼》"}, {"t": "夹岸复连沙,枝枝摇浪花。", "b": "雍裕之《芦花》"}, {"t": "夹岸数百步。", "b": "晋·陶渊明《桃花源记》"}, {"t": "高柳夹堤。", "b": "明·袁宏道《满井游记》"}, {"t": "送者夹岸。", "b": "清·张廷玉《明史》"}], "words": [{"w": " 夹道子", "t": "狭窄的巷道、胡同"}, {"w": "夹发", "t": "从左右两路同时出兵"}, {"w": "夹拥", "t": "左右围抱"}, {"w": " 夹岸", "t": "水流的两岸;堤岸的两边。"}]}, {"meaning": "钳夹用具。", "cites": [{"t": "笄夹。", "b": "《周礼·司弓矢》"}, {"t": "则以笄夹取之。", "b": "《周礼·射鸟氏》"}, {"t": "见叶梵书一夹。", "b": "《宋史·外国传·天笠》"}], "words": [{"w": "夹讯", "t": "用夹棍逼供审讯"}, {"w": "夹拶", "t": "用夹子夹手指的酷型"}, {"w": "夹剪", "t": "夹取物件的工具,铁制,形似剪刀,但无锋刃,头宽而平。"}]}, {"meaning": "剑把。", "cites": [{"t": "天子之剑,以……周、宋为镡,韩、魏为夹。", "b": "《庄子·说剑》"}, {"t": "诸侯之剑,…以豪桀士为夹。", "b": ""}]}]}, {"pinyin": "jiá", "defs": [{"meaning": "双层的(衣被等)。", "cites": [{"t": "御袷衣。", "b": "《文选·潘岳·秋兴赋》"}], "words": [{"w": "夹衣", "t": "双层的衣服。指有里、有面的衣服"}, {"w": "夹衫", "t": "双层的衣服"}, {"w": "夹布子", "t": "月经带"}, {"w": "夹被摩疼", "t": "喻指没有抓住要害。"}]}]}, {"pinyin": "gā", "defs": [{"meaning": "腋下", "words": [{"w": "夹肢窝", "t": "腋窝"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('403wx','夷','1','yí','大','6','','[{"pinyin": "yí", "defs": [{"meaning": "(会意。从大从弓。本义:东方之人。即我囯古代对对东部各民族的统称)。"}, {"meaning": "同本义 。殷代分布在今山东省,江苏省一带。后來蔑指中原以外的各族。", "cites": [{"t": "夷,东方之人也。从大,从弓,会意,弓所持也。字亦作巳。", "b": "《说文》"}, {"t": "夷有九种。", "b": "《後后汉书东夷传》"}, {"t": "宅喁夷。", "b": "《书饶典》。马注:“萊夷也。”"}, {"t": "四夷八蠻。", "b": "《周礼职方式》"}], "words": [{"w": "夷歌", "t": "夷人的歌曲。亦蔑指外族的歌曲"}, {"w": "夷蠻", "t": "古代东方和南方各族的蔑稱。"}]}, {"meaning": "旧时往往用以稱外囶或外囯人。", "cites": [{"t": "南抚夷越。", "b": "《三国志诸葛亮传》"}, {"t": "夷船由泥城。", "b": "《广东军务记》"}, {"t": "与夷决战。", "b": ""}, {"t": "馀夷脱逃。", "b": ""}], "words": [{"w": "夷场", "t": "即“洋场”。旧时上海人指租界地"}, {"w": "夷馆", "t": "清代称外囯人在中囯的馆舍。"}]}, {"meaning": "倚輩;同輩。", "cites": [{"t": "在醜夷不争。", "b": "《礼记曲礼上》。郑玄注:“夷,猶倚也。”"}, {"t": "今诸将皆陛下故等夷。", "b": "《史记留候世家》"}], "words": [{"w": "夷等", "t": "同列,同辈。"}]}, {"meaning": "古囯名 。在今山东省即墨市西。"}, {"meaning": "平坦。", "cites": [{"t": "大道甚夷而人好径。", "b": "《老子》"}, {"t": "驰骋夷道。", "b": "《淮南子原道》"}, {"t": "船背稍夷。", "b": "明魏学洢《核舟記》"}, {"t": "夫夷以近,则游者众;险以远,則至者少。", "b": "王安石《游褒禅山記》"}], "words": [{"w": "夷延", "t": "地势平坦而广阔"}, {"w": "夷阻", "t": "平坦和险阻。"}]}, {"meaning": "平和;平易。", "cites": [{"t": "与之辩解,言和而色夷。", "b": "明宋濂《送东阳马生序》"}], "words": [{"w": "夷坦", "t": "平和坦蕩"}, {"w": "夷伍", "t": "平易而放达"}, {"w": "夷易", "t": "平易,平正"}, {"w": "夷泰", "t": "平和闲靜"}, {"w": "夷淡", "t": "性情平和淡泊"}, {"w": "夷雅", "t": "平和闲雅"}, {"w": "夷道", "t": "平易之道"}, {"w": "夷远", "t": "平和而高远"}, {"w": "夷为", "t": "平和通达"}, {"w": "夷粹", "t": "平和纯正"}, {"w": "夷澹", "t": "平易恬靜"}, {"w": "夷简", "t": "平易質人。"}]}, {"meaning": "经常,常道。", "cites": [{"t": "王极之传言,是夷是训,于帝其順。", "b": "《史記》"}]}, {"meaning": "傲慢。", "cites": [{"t": "由礼則雅,不由禮則夷固僻违,庸众而野。", "b": "《荀子》"}]}, {"meaning": "喜悅。", "cites": [{"t": "云胡不夷?", "b": "《诗歌郑风风雨》"}, {"t": "我心则夷。", "b": "《诗.召南.草蟲》"}, {"t": "羡馀术兮可夷。", "b": "《楚辞.九怀》"}]}, {"meaning": "使平,拉平;铲平。", "cites": [{"t": "将塞井夷竈而为行也。", "b": "《左传.成公十六年》"}, {"t": "往而夷夫。", "b": "《吕氏春秋.似顺》"}, {"t": "芟夷大乱。", "b": "《资治通鉴》如:夷为平地;夷岳;夷拔(鏟平攻破)平定 [put down]"}, {"t": "乱生不夷,靡囯不泯。", "b": "《诗.大雅.桑柔》"}, {"t": "实靖夷我邦。", "b": "《诗.大雅.召》"}, {"t": "今操芟荑大难,略已平矣。", "b": "《资治通鉴》"}], "words": [{"w": "夷难", "t": "平定祸乱。"}]}, {"meaning": "伤,受伤。", "cites": [{"t": "夷于左股。", "b": "《易.明夷》"}, {"t": "芟夷我农功。", "b": "《左传.成公十三年》"}], "words": [{"w": "夷伤", "t": "创伤;死伤。"}]}, {"meaning": "铲除;消灭;诛灭。", "cites": [{"t": "是以人夷其宗庙。", "b": "《囯语.周语下》"}, {"t": "夷灭者数十家。", "b": "《汉书.李广苏建传》"}, {"t": "吾欲夷其九族,以谢天下,安肯与逆贼结亲耶?", "b": "《三囯演义》"}], "words": [{"w": "夷三族", "t": "古代的酷刑。一人犯罪,父母、兄弟、妻子三族同坐。"}]}, {"meaning": "锄草。", "cites": [{"t": "春始生而萌之,夏日至而夷之。", "b": "《周礼.秋官》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('404wx','轨','1','guǐ','车','6','','[{"pinyin": "guǐ", "defs": [{"meaning": "(形声。从车,九声。本义:轨距,车两轮间的距离)。"}, {"meaning": "同本义。", "cites": [{"t": "轨,车辙也。", "b": "《说文》"}, {"t": "经涂九轨。", "b": "《考工记·匠人》。注:“轨,谓辙广。”"}, {"t": "车不得方轨。", "b": "《战国策·齐策》。注:“车两轮间为轨。”按,谓两轮间相距之迹为轨也。"}, {"t": "今天下车同轨,书同文。", "b": "《礼记·中庸》"}], "words": [{"w": "轨距", "t": ""}]}, {"meaning": "车轮的痕迹,车辙。", "cites": [{"t": "轨,迹也。", "b": "《广雅》"}, {"t": "轨,车辙也。", "b": "《玉篇》"}, {"t": "兵车之轨交于天下。", "b": "柳宗元《辩侵伐论》"}, {"t": "城门之轨,两马之力与?", "b": "《孟子·尽心下》"}], "words": [{"w": "轨迹", "t": "车的辙迹"}, {"w": "轨躅", "t": "车轮辗过的痕迹。"}]}, {"meaning": "法则、法度。", "cites": [{"t": "田有轨,人有轨,用有轨,乡有轨,人事有轨,币有轨,县有轨,国有轨。", "b": "《管子·山国轨》"}, {"t": "东平失轨。", "b": "《汉书·叙传》。注:“法则也。”"}, {"t": "缘法循理谓之轨。", "b": "《贾子道术》"}, {"t": "轨事之大者也。", "b": "《汉书·贾山传》。注:“谓法度”"}, {"t": "时国王骄奢,不遵典宪,又多豪右,共为不轨。", "b": "《后汉书·张衡传》"}], "words": [{"w": "轨等", "t": "法度与等级"}, {"w": "轨仪", "t": "规范,法则"}, {"w": "轨法", "t": "轨范法则"}, {"w": "轨事", "t": "法度,法则"}, {"w": "轨模", "t": "法则,楷模。"}]}, {"meaning": "道,导轨。", "cites": [{"t": "五星循轨而不失其行。", "b": "《淮南子·本经训》"}], "words": [{"w": "轨度;轨道;出轨;单", "t": "双轨;出轨;无轨电车;有轨电车。"}]}, {"meaning": "车子。", "cites": [{"t": "外则轨躅八达,里闬对出。", "b": "左思《蜀都赋》。刘良注:“轨,车也。躅,迹也。”"}, {"t": "回轨异途。", "b": "《三国志·郤志传》"}]}, {"meaning": "道路;途径。", "cites": [{"t": "异轨同奔。", "b": "《宋书·谢灵运传论》"}]}, {"meaning": "又如;轨途(道路);轨路(道路)。"}, {"meaning": "盗窃或作乱的坏人。", "cites": [{"t": "臣闻乱在外为奸,在内为轨。", "b": "《左传·成公十七年》"}], "words": [{"w": "奸轨", "t": "作乱偷窃之人。"}]}, {"meaning": "依循,遵循。", "cites": [{"t": "是境内之民,其言谈者必轨于法。", "b": "《韩非子·五蠹》"}], "words": [{"w": "轨轨", "t": "遵循轨迹"}, {"w": "轨法", "t": "遵循法度"}, {"w": "轨承", "t": "遵循承奉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('405wx','邪','1','xié yé','阝','6','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从邑,牙声。本义:琅邪郡。字亦作琊)。", "cites": [{"t": "赤芾在股,邪幅在下。", "b": "《诗·小雅·采菽》"}, {"t": "方直不曲谓之正,反正为邪。", "b": "《贾子道术》"}, {"t": "竹林,前正而后有枉者谓之邪道。", "b": "《春秋繁露》"}, {"t": "回邪曲直。", "b": "《礼记·乐记》"}], "words": [{"w": "邪靡", "t": "倾斜披靡的样子"}, {"w": "邪睨", "t": "斜视"}, {"w": "邪绝", "t": "斜行度越。"}]}, {"meaning": "不正当,不正派。", "cites": [{"t": "虽有奇邪而不治者。", "b": "《礼记·祭义》"}, {"t": "亡正处邪。", "b": "《周书·王佩》。注:“奸术也。”"}, {"t": "愚乱之邪臣。", "b": "宋玉《登徒子好色赋》"}, {"t": "是以邪氛岁增。", "b": "《汉书·元帝纪》"}, {"t": "放辟邪侈。", "b": "《孟子·梁惠王上》"}, {"t": "惧谗邪。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "去邪无疑。", "b": "《尚书》"}, {"t": "愤世疾邪。", "b": "明·刘基《卖柑者言》"}, {"t": "辟邪说。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "邪魔", "t": "恶习"}, {"w": "邪皮", "t": "不正经,不老实"}, {"w": "邪说诬民", "t": "用有严重危害性的言论欺骗人民"}, {"w": "邪术", "t": "不正当的方术。"}]}, {"meaning": "异常。妖异怪诞。", "cites": [{"t": "性不信巫邪。", "b": "《南史》"}], "words": [{"w": "邪螭", "t": "古代传说中之蛟龙,头上无角"}, {"w": "邪教;邪传", "t": "怪异的传闻"}, {"w": "异端邪说;邪魔外道", "t": "指各形各色的鬼怪。或形容事情不入正途。"}]}, {"meaning": "品行不正的人。", "cites": [{"t": "任贤勿二,去邪勿疑。", "b": "《书·大禹谟》"}, {"t": "邪曲之害公。(邪恶的小人妨害国家。邪、曲,不正,邪恶的人。名词)。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "邪丑", "t": "邪恶丑陋的人。"}]}, {"meaning": "中医指邪气 。与人体正气相对而言。泛指各种致病因素及其病理损害。", "cites": [{"t": "邪之所凑,其气必虚。", "b": "《素问·评热病论》"}], "words": [{"w": "寒邪;风邪;灸刺和药逐去邪", "t": ""}]}]}, {"pinyin": "yé", "defs": [{"meaning": "(mòyé)。"}, {"meaning": "古同疑问词“耶”。", "cites": [{"t": "欺秦邪。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "令名不彰邪。", "b": "《世说新语·自新》"}, {"t": "何预我邪。", "b": "唐·柳宗元《柳河东集》"}, {"t": "是且非邪。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "肖于器邪。", "b": "唐·韩愈《朱文昌校昌黎先生集》"}, {"t": "可迎之邪。", "b": "《资治通鉴》"}, {"t": "孤岂欲卿治经为博士邪(邪,语助词,表反诘,吗)!", "b": "《资治通鉴·汉纪》"}, {"t": "此画果真邪。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "同于真邪。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('406wx','尧','1','yáo','兀','6','','[{"pinyin": "yáo", "defs": [{"meaning": "(会意。从垚(yáo),从兀。“垚”是土高,兀(wù)高耸突出,所以“尧”表示高。本义:高) 同本义。", "cites": [{"t": "尧,高也。", "b": "《说文》"}, {"t": "曰若稽古帝尧。", "b": "《书·尧典》。马注:“翼善传圣曰尧。”"}, {"t": "尧亦美谥也。", "b": "《论衡·须颂》"}, {"t": "尧犹荛荛也,至高之貌。", "b": "《白虎通·号》"}, {"t": "尧者,高也,饶也。", "b": "《风俗通·皇霸》"}]}, {"meaning": "中国古代的皇帝陶唐氏之号。生于伊,嗣后耆,故称伊耆氏;初封陶,后徙唐,又称“伊唐氏”。", "cites": [{"t": "长此戴尧天。", "b": "杜审言《蓬莱三殿传宴》"}, {"t": "运生世治,劫生世危,尧、舜、禹、汤…皆应运而生者。", "b": "《红楼梦》"}], "words": [{"w": "堯", "t": "草名,相传当初生于尧的厨房,能自己摇动生风,防止食物变质"}, {"w": "尧天", "t": "比喻太平盛世"}, {"w": "尧封", "t": "疆域。传说尧舜时划定我国疆土为十二州,故称。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('407wx','划','1','huá huà huai','刂','6','','[{"pinyin": "huá", "defs": [{"meaning": "用桨拨水使船行动。"}, {"meaning": "合算，按利益情况计较是否相宜。"}, {"meaning": "用刀或其它东西把物件分开或从物件上面擦过。"}, {"meaning": "指二人伸指猜拳行酒。"}]}, {"pinyin": "huà", "defs": [{"meaning": "(会意。从画(划分),从刀。“画”亦兼表读音。本义:割开,分开。按:“划”和“劃”古代是意义不同的两个字。“划”,读作huá,是个从戈、从刀的形声字,意思是“拔水前进”,如“划舟”、“划桨”等。而“割开”、“分开”等意义古代都写作劃,不写作“划”。现在“劃”简化为“划”)。"}, {"meaning": "划分。", "cites": [{"t": "划,锥刀曰划。", "b": "《说文》"}, {"t": "划,锥刀刻。", "b": "《广韵》"}], "words": [{"w": "划指", "t": "比划"}, {"w": "划地为牢", "t": "指限制在一定范围内"}, {"w": "划成分;划界", "t": ""}]}, {"meaning": "汉字的一笔。尤指一横。"}]}, {"pinyin": "huai", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('408wx','迈','1','mài','辶','6','','[{"pinyin": "mài", "defs": [{"meaning": "(形声。从辵 夲义:远行)。"}, {"meaning": "同本义。", "cites": [{"t": "丙子九月,辞家西迈。", "b": "钱谦益《徐霞客传》"}, {"t": "我日斯迈,而月斯征。", "b": "《诗·小雅·小宛》"}]}, {"meaning": "∪缏跬(勇行迈进);迈迹(迈行;远行)。"}, {"meaning": "行走;跨步。", "cites": [{"t": "行迈靡靡,中心摇摇。", "b": "《诗·王风·黍离》"}], "words": [{"w": "迈过门槛;迈腿;迈步", "t": "举脚向前走;跨出步子"}, {"w": "迈开", "t": "向前跨出。"}]}, {"meaning": "超过,跨越。", "cites": [{"t": "三王可迈,五帝可越。", "b": "《三国志·高堂隆传》"}], "words": [{"w": "迈世", "t": "超越时代"}, {"w": "迈秀", "t": "超逸秀拔"}, {"w": "迈绩", "t": "超绝的功绩。"}]}, {"meaning": "时光流逝。", "cites": [{"t": "今我不乐,日月其迈。", "b": "《诗·唐风·蟋蟀》"}], "words": [{"w": "迈迈", "t": "往逝的样子"}, {"w": "迈往", "t": "时光流逝。"}]}, {"meaning": "勤勉。", "cites": [{"t": "皋陶迈种德。", "b": "《左传·庄公八年》"}], "words": [{"w": "迈德", "t": "勉力树德"}, {"w": "迈仁", "t": "勉力实行仁政"}, {"w": "迈古", "t": "勉力学古。"}]}, {"meaning": "超然不俗。", "cites": [{"t": "风神高迈,客仪俊爽。", "b": "《晋书·裴楷传》"}], "words": [{"w": "迈气", "t": "豪放的气概"}, {"w": "迈达", "t": "豪爽旷达"}, {"w": "迈俗", "t": "超脱世俗"}, {"w": "迈秀", "t": "超逸秀拔"}, {"w": "迈峻", "t": "豪迈峻拔"}, {"w": "迈往", "t": "超脱凡俗。"}]}, {"meaning": "老。", "cites": [{"t": "衰迈欠风尘。", "b": "杜甫《上白帝城》"}], "words": [{"w": "老迈;年迈;迈终", "t": "老死"}, {"w": "迈景", "t": "暮年;老境"}, {"w": "迈寿", "t": "高年;长寿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('409wx','毕','1','bì','比','6','','[{"pinyin": "bì", "defs": [{"meaning": "(会意。甲骨文字形,上端象网形,下端是柄,古时用以捕捉鸟兽、老鼠之类的器具。金文又在上面加个“田”,意思是田猎所用的网。本义:打猎用的有长柄的网)。"}, {"meaning": "同本义。", "cites": [{"t": "畢,田网也。", "b": "《说文》"}, {"t": "田守毕弋。", "b": "《国语·齐语》。注:“掩雉兔之网。”"}, {"t": "其余荷垂天之毕。", "b": "《汉书·扬雄传》"}, {"t": "耒遭民田之毕。", "b": "《论衡·偶会》"}], "words": [{"w": "毕戈", "t": "毕为捕兽所用之网,戈为射鸟所用的系绳之箭。泛指打猎活动。"}]}, {"meaning": "毕宿。星名。二十八宿之一,西方白虎七宿的第五宿,有星八颗。以其形状像毕网得名。"}, {"meaning": "用毕猎取。", "cites": [{"t": "鸳鸯于飞,毕之罗之。", "b": "《诗·小雅·鸳鸯》"}]}, {"meaning": "完毕,结束。", "cites": [{"t": "若入前为寿,寿毕,请以舞剑。", "b": "《史记·项羽本纪》"}, {"t": "此印者才毕,则第二板已具。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "老人语未毕。", "b": "清·周容《芋老人传》"}, {"t": "公阅毕。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "礼毕;毕婚", "t": "完婚"}, {"w": "毕世", "t": "终其一生"}, {"w": "毕老", "t": "终其天年"}, {"w": "毕事", "t": "完事,了事。"}]}, {"meaning": "全部使出。", "cites": [{"t": "吾与汝毕力平险。", "b": "《列子·汤问》"}], "words": [{"w": "毕气", "t": "气数完尽"}, {"w": "毕辞", "t": "尽所欲言。"}]}, {"meaning": "全部,都,统统。", "cites": [{"t": "众妙毕备。", "b": "《虞初新志·秋声诗自序》"}, {"t": "忽然抚尺一下,群响毕绝。", "b": ""}, {"t": "责(债)毕收。", "b": "《战国策·齐策》"}, {"t": "莫不毕集。", "b": "清·侯方域《壮悔堂集》"}], "words": [{"w": "毕备", "t": "全都具备;完备"}, {"w": "毕恭毕敬", "t": "非常恭敬。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('410wx','至','1','zhì','至','6','','[{"pinyin": "zhì", "defs": [{"meaning": "(象形。从一,一犹地,指事,不去而下来。古文从土,上亦象飞下之形。尾上首下。本义:到来,到达)。"}, {"meaning": "同本义(上古时期多用“至”,中古时期多用“到”)。", "cites": [{"t": "至,鸟飞从高下至地也。", "b": "《说文》"}, {"t": "凤鸟不至。", "b": "《论语》"}, {"t": "至,到也。", "b": "《字林》"}, {"t": "至,到也。", "b": "《广韵》"}, {"t": "王朝至于商郊牧野。", "b": "《书·牧誓》"}, {"t": "我征聿至。", "b": "《诗·豳风·东山》"}, {"t": "远道不至。", "b": "《墨子·辞过》"}, {"t": "故不积跬步,无以至千里。", "b": "《荀子·劝学》"}, {"t": "至则行矣。", "b": "《论语·微子》"}, {"t": "至则无可用。", "b": "唐·柳宗元《三戒》"}, {"t": "风雨骤至。", "b": "汉·王粲《登楼赋》"}, {"t": "民至老死不相往来。", "b": "《老子·小国寡民》"}, {"t": "孝武帝时,至代相。", "b": "《史记·李将军列传》"}, {"t": "至通州,几以不纳死。", "b": "宋·文天祥《后序》"}, {"t": "富者不能至。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "前狼又至。", "b": "《聊斋志异·狼三则》"}, {"t": "至子之世。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "至旦", "t": "到天明"}, {"w": "水流至足;至竟", "t": "到底;毕竟"}, {"w": "至止", "t": "到达,到来。止,语气词"}, {"w": "无微不至;自春至冬;由东至西;至于", "t": "到;达到"}, {"w": "至乎", "t": "至于。到;达到"}, {"w": "至至", "t": "达到,道的最高境地"}, {"w": "至到", "t": "指程度达到极点;到。"}]}, {"meaning": "来;去。", "cites": [{"t": "至,来也。", "b": "《玉篇》"}, {"t": "君子是以知桓王之失郑也…己弗能有,而以与人;人之不至,不亦宜乎!", "b": "《左传·僖公五年》"}]}, {"meaning": "形容事物的尽善尽美。犹言最好、最高、最大。", "cites": [{"t": "至人无己。", "b": "《庄子·逍遥游》"}, {"t": "色愈恭,礼愈至。", "b": "明·宋濂《送东阳马生序》"}, {"t": "吾爱汝至。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "至心", "t": "极为诚恳的心意"}, {"w": "最骏", "t": "最好的骏马"}, {"w": "至意", "t": "极深远的用意"}, {"w": "至情", "t": "极其真实的思想感情"}, {"w": "至理", "t": "极深的道理"}, {"w": "至材", "t": "极佳的才能"}, {"w": "至治", "t": "最完善的政治"}, {"w": "至德", "t": "最高尚伟大的德性。"}]}, {"meaning": "深。", "cites": [{"t": "日,君以骊姬为夫人,民之疾心固皆至矣!", "b": "《周语》。韦昭注:“至,深也。”"}], "words": [{"w": "至虑", "t": "深思熟虑"}, {"w": "至戒", "t": "犹深戒"}, {"w": "至契", "t": "交情极深的朋友。"}]}, {"meaning": "得当;恰当。", "cites": [{"t": "不知逆顺之理、小大至不至之变者也,未可与及天下之大理者也。", "b": "《荀子·正论》。杨倞注:“至不至,犹言当不当也。”"}]}, {"meaning": "真挚;诚挚。", "cites": [{"t": "唯天下至诚,为能尽其性。", "b": "《中庸》。朱熹注:“天下至诚谓圣人之德之至,天下莫能加也。”"}], "words": [{"w": "至诚;至友", "t": ""}]}, {"meaning": "周到。", "cites": [{"t": "或遇其叱咄,色愈恭,礼愈至,不敢出一言以复。", "b": "明·宋濂《送东阳马生序》"}]}, {"meaning": "大。", "cites": [{"t": "至哉坤元,万物资生。", "b": "《易·坤》"}], "words": [{"w": "至贤", "t": "大贤。指极有贤德的人"}, {"w": "至砀", "t": "极广大。"}]}, {"meaning": "极;最。", "cites": [{"t": "材之不逮至远也。", "b": "汉·贾谊《治安策》"}, {"t": "陵见其至诚。", "b": "《汉书·李广苏建传》"}, {"t": "古之治天下,至纤至悉也。", "b": "贾谊《论积贮疏》"}, {"t": "罪至重而罚至轻,庸人不知恶矣。", "b": "《荀子·正论》"}], "words": [{"w": "至公", "t": "最公正"}, {"w": "至足", "t": "极充足"}, {"w": "至大至刚", "t": "广大无限而刚健不可屈挠"}, {"w": "至大无外", "t": "大到极点,外无以加"}, {"w": "至小无内", "t": "小到极点,内无余隙"}, {"w": "至公无私", "t": "公正到极点,丝毫没有私心"}, {"w": "至清", "t": "极其清澈。"}]}, {"meaning": "一定;必。", "cites": [{"t": "衡曰:“顾当得不耳,何至上书?”", "b": "《汉书·匡衡传》"}]}, {"meaning": "竟,竟然。", "cites": [{"t": "先生之巧,至能使木鸟飞。", "b": "《韩非子》"}]}, {"meaning": "夏至、冬至的简称。", "cites": [{"t": "凡分、至、启、闭,必书云物。", "b": "《左传·僖公五年》"}], "words": [{"w": "至节", "t": "冬至或夏至"}, {"w": "至日", "t": "指冬至日,夏至日。冬至昼最短,夏至昼最长。"}]}, {"meaning": "至道。道家多以指最玄妙精深的道理。", "cites": [{"t": "今背其本而求其末,释其要而索其于祥,末可与言至也。", "b": "《淮南子·本经训》"}], "words": [{"w": "至精", "t": "我国古代哲学家指一种极其精微神妙而不见形迹的存在。"}]}, {"meaning": "道德高尚的人;圣人。", "cites": [{"t": "道者,圣之所吏也,至之所得也。", "b": "《鹖冠子》"}], "words": [{"w": "至人", "t": "道家指超凡脱俗,达到无我境界的人;思想或道德修养最高超的人。"}]}, {"meaning": "准则。", "cites": [{"t": "民生而有习有常,以习为常,以常为慎…上贤而不穷,哀乐不谣,民知其至。", "b": "《逸周书》"}]}, {"meaning": "乃;乃至;以至。", "cites": [{"t": "时有所虑,至通夜不瞑。", "b": "曹丕《与吴质书》"}]}, {"meaning": "至于,甚至于 ——用于说完一事时,又另外提出一事。转折相连。", "cites": [{"t": "故言九州山川,《尚书》近之矣。至《禹本纪》、《山海经》所有怪物,余不敢言之也。", "b": "《史记》"}]}, {"meaning": "到…时候。", "cites": [{"t": "至其时,西门豹往会之河上。", "b": "褚少孙《西门豹治邺》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('411wx','此','1','cǐ','止','6','','[{"pinyin": "cǐ", "defs": [{"meaning": "(会意。从止,从人。甲骨文字形,左边是一只脚(止),右边是“人”,意思是一只脚踩在别人身上,是“跐”(cǐ)的本字。①本义:踩,踏。②指示代词,这)。"}, {"meaning": "这;这个 。表示近指的代词,与“彼”相对。", "cites": [{"t": "陈康肃公尧咨善射,当世无双,公亦以此自矜。", "b": "欧阳修《卖油翁》"}], "words": [{"w": "此等", "t": "这样"}, {"w": "此生", "t": "这辈子"}, {"w": "此地", "t": "这里"}, {"w": "此个", "t": "这个"}, {"w": "此家", "t": "此人。"}]}, {"meaning": "如此,这般。", "cites": [{"t": "虎因喜,计之曰:“技止此耳!”", "b": "柳宗元《黔之驴》"}], "words": [{"w": "此以", "t": "是以,因此。"}]}, {"meaning": "乃;则。", "cites": [{"t": "有德此有人,有人此有土,有土此有财,有财此有用。", "b": "《礼记·大学》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('412wx','贞','1','zhēn','贝','6','','[{"pinyin": "zhēn", "defs": [{"meaning": "(会意。从卜,从贝(甲骨文作“鼎”,后省改为“贝”)。鼎本是食器,这里表火具,即用火具而卜。本义:占卜) 同本义。", "cites": [{"t": "貞,卜问也。从卜,贝以为贽。会意。京房说,鼎省声。", "b": "《说文》"}, {"t": "季冬,陈玉,以贞来岁之恶。", "b": "《周礼·春官·天府》。郑玄注:“问事之正曰贞。”"}, {"t": "凡国大贞,卜立君,卜大封。", "b": "《周礼》"}], "words": [{"w": "贞龟", "t": "占卜。古人灼龟甲以卜"}, {"w": "贞吝", "t": "卜问不吉,其事难行"}, {"w": "贞卜", "t": "占卜;卜问。"}]}, {"meaning": "假借为“正”、为“定”。端方正直。", "cites": [{"t": "元、亨、利、贞。", "b": "《易·乾》"}, {"t": "厥赋贞。", "b": "《书·禹贡》。传:“正也。”"}, {"t": "求永贞。", "b": "《周礼·大祝》"}, {"t": "万国以贞。", "b": "《礼记·文王世子》"}, {"t": "一人元良,万邦以贞。", "b": "《书·太甲下》"}, {"t": "君子贞而不谅。", "b": "《论语》"}], "words": [{"w": "贞白", "t": "正直清白"}, {"w": "贞曜", "t": "正光"}, {"w": "贞一", "t": "心正专一"}, {"w": "贞期", "t": "政治清明的太平盛世"}, {"w": "贞明", "t": "正大光明"}, {"w": "贞确", "t": "贞正坚固。"}]}, {"meaning": "坚定不移。多指意志或操守。", "cites": [{"t": "言行抱一谓之贞。", "b": "《贾子道术》"}, {"t": "贞良死节之臣。", "b": "诸葛亮《出师表》"}], "words": [{"w": "贞亮死节", "t": "坚贞忠诚,能够以死殉节"}, {"w": "贞亮", "t": "坚贞亮节"}, {"w": "贞固", "t": "能固守正道,坚贞不变,始终如一"}, {"w": "贞人", "t": "志节坚定不移、能守正道的人"}, {"w": "贞毅", "t": "坚贞刚毅。"}]}, {"meaning": "坚硬;坚劲。", "cites": [{"t": "严霜识贞木。", "b": "房玄龄《晋书》"}], "words": [{"w": "贞木", "t": "坚劲耐寒,经严冬而不凋的树木"}, {"w": "贞珉", "t": "坚美可做碑铭石刻的石块"}, {"w": "贞悦", "t": "坚挺劲直"}, {"w": "贞柯", "t": "坚挺耐塞的枝柯"}, {"w": "贞玉", "t": "坚美的玉石。"}]}, {"meaning": "忠;真诚。", "cites": [{"t": "慕古人之贞节。", "b": "张衡《思玄赋》。注:“诚也。”"}, {"t": "不贰者,则是贞于君也。", "b": "《韩非子·难三》"}], "words": [{"w": "忠贞", "t": "忠诚而坚定不移"}, {"w": "贞臣", "t": "廉正有操守的臣子"}, {"w": "贞夫", "t": "忠直有守的正人君子。也作“真夫”"}, {"w": "贞实", "t": "忠信诚实。"}]}, {"meaning": "贞操,节操。旧称女子“贞节”。", "cites": [{"t": "清白守节曰贞。", "b": "《周书·谥法》"}, {"t": "贞女不更二夫。", "b": "《史记·甲单列传》"}, {"t": "一念之贞。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "贞妇", "t": "夫死不再改嫁的女子"}, {"w": "贞心", "t": "坚贞不移的心地"}, {"w": "贞艳", "t": "有坚贞之节的美女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('413wx','师','1','shī','巾','6','','[{"pinyin": "shī", "defs": [{"meaning": "(会意。从币,从垖。垖(duī)是小土山,帀(zā)是包围。四下里都是小土山,表示众多。本义:古代军队编制的一级。二千五百人为一师)。"}, {"meaning": "同本义。", "cites": [{"t": "师,二千五百人为师。", "b": "《说文》"}, {"t": "王乃犬巡六师。", "b": "《书·伪泰誓》"}, {"t": "陈师鞠旅。", "b": "《诗·小雅·采芑》"}, {"t": "五人为伍,五伍为两,四两为卒,五卒为旅,五旅为师。", "b": "《周礼·地官·小司徒》"}]}, {"meaning": "师今为隶属于军的单位,下辖若干旅或团。"}, {"meaning": "泛指军队。", "cites": [{"t": "十年春,齐师伐王。", "b": "《左传·庄公十年》"}, {"t": "九国之师,逡巡而不敢进。", "b": "汉·贾谊《过秦论》"}, {"t": "蹇叔之子与师,哭而送之曰:“晋人御师必于殽。”", "b": "《左传·僖公三十三年》"}], "words": [{"w": "水师", "t": "水军"}, {"w": "挥师", "t": "指挥并带领军队"}, {"w": "师旅", "t": "军队的通称,亦用来指战争"}, {"w": "师船", "t": "师舶,兵船,兵舰"}, {"w": "师老", "t": "军队疲劳,士气低落,战斗力衰弱"}, {"w": "师吏", "t": "军吏"}, {"w": "师令", "t": "军令"}, {"w": "师干", "t": "本指军队的防御力量。后指军队"}, {"w": "师禁", "t": "军队的禁令。"}]}, {"meaning": "军师。", "cites": [{"t": "千乘之国,摄乎大国之间,加之以师旅,因之以饥馑。", "b": "《论语·先进》"}]}, {"meaning": "民众,徒众。", "cites": [{"t": "溥彼韩城,燕师所完。", "b": "《诗·大雅·韩奕》"}, {"t": "师,众也。", "b": "《尔雅》"}, {"t": "师锡帝曰。", "b": "《书·尧典》"}, {"t": "天子所都曰京师。地下之众者,莫过于水,地上之众者,莫过于人,京大师众也。", "b": ""}], "words": [{"w": "师锡", "t": "众人的意见;舆论。"}]}, {"meaning": "古代行政区划单位。", "cites": [{"t": "八家而为邻,三邻而为朋,三朋而为里,五里而为邑,十邑而为都,十都而为师,州十有二师焉。", "b": "《尚书大传》"}]}, {"meaning": "老师。", "cites": [{"t": "古之学者必有师。师者,所以传道受业解惑也。", "b": "唐·韩愈《师说》"}, {"t": "又患无硕师名人与游。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "师儒", "t": "乡里教人道艺的人"}, {"w": "师生关系;师风", "t": "老师的风度"}, {"w": "师台", "t": "对老师的尊称"}, {"w": "师保", "t": "负责教导贵族子弟的官"}, {"w": "师课", "t": "由书院负责人主持的对学生进行的月考。"}]}, {"meaning": "长,首领。", "cites": [{"t": "甸师,下士二人。", "b": "《周礼》"}]}, {"meaning": "亦以称专司一事的神道或官员。"}, {"meaning": "首都,京城。", "cites": [{"t": "因入京师,观太学,遂通五经,贯六艺。", "b": "《后汉书·张衡传》"}]}, {"meaning": "擅长某种技术或在某个领域里有特殊技能的人。", "cites": [{"t": "而渔工水师虽知而不能言。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "工程师;医师;厨师;技师;师工", "t": "技工。亦指厨师与烧火工人"}, {"w": "师家", "t": "师傅门下。"}]}, {"meaning": "乐师;乐官。", "cites": [{"t": "师旷鼓琴。", "b": "《盐铁论·相刺》"}], "words": [{"w": "师工", "t": "古称主事制曲奏乐的人。即乐师"}, {"w": "师襄", "t": "春秋卫国的乐官。"}]}, {"meaning": "效法;学习。", "cites": [{"t": "生乎吾前,其闻道也固先乎吾,吾从而师之。", "b": "唐·韩愈《师说》"}], "words": [{"w": "师古", "t": "效法古代"}, {"w": "师仰", "t": "师法敬仰"}, {"w": "师师", "t": "互相效法"}, {"w": "师式", "t": "学习或效法的典范"}, {"w": "师效", "t": "效法。"}]}, {"meaning": "出兵征伐,进军。", "cites": [{"t": "若国作民而师田行役之事。", "b": "《周礼·地官·州长》"}], "words": [{"w": "师祭", "t": "古代军队出兵时所行祭祀祈祷之礼"}, {"w": "师期", "t": "出师的日期。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('414wx','尘','1','chén','小','6','','[{"pinyin": "chén", "defs": [{"meaning": "(会意。《说文》从三“鹿”,从“土”,表示鹿群行扬起尘土的意思。楷书简去重迭的部分,只保留一个“鹿”。现行简化字“尘”,也是一个从“小”从“土”的会意字。本义:尘土)。"}, {"meaning": "同本义。", "cites": [{"t": "湫隘嚣尘。", "b": "《左传·昭公三年》。注:“土也。”"}, {"t": "尘埃也。", "b": "《庄子·逍遥游》"}, {"t": "而游于尘垢之外。", "b": "《庄子·齐物论》"}, {"t": "朱尘筵些。", "b": "《楚辞·招魂》"}, {"t": "满面尘灰烟火色。", "b": "唐·白居易《卖炭翁》"}, {"t": "渭城朝雨浥轻尘。", "b": "唐·王维《送元二使安西》"}], "words": [{"w": "浮尘;降尘;灰尘", "t": "尘土"}, {"w": "一尘不染;尘封", "t": "盖满灰尘"}, {"w": "尘涓", "t": "尘埃与一滴水。比喻细微"}, {"w": "尘芥", "t": "尘土与草芥。比喻无价值的东西"}, {"w": "尘沙", "t": "因风飞扬的灰沙。"}]}, {"meaning": "喻庸俗肮脏或指庸俗肮脏的事物。", "cites": [{"t": "春不得避风尘。", "b": "晁错《论贵粟疏》"}, {"t": "惊尘蔽天。", "b": "马中锡《中山狼传》"}], "words": [{"w": "尘陋", "t": "凡俗浅陋。"}]}, {"meaning": "重量单位。十埃为“尘”。"}, {"meaning": "蒙上灰尘,弄脏。", "cites": [{"t": "无将大车,祗自尘兮。", "b": "《诗·小雅·无将大车》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('415wx','尖','1','jiān','小','6','','[{"pinyin": "jiān", "defs": [{"meaning": "(会意。从小,从大。一头小一头大为尖。本义:物体的末端细削而锐利)。"}, {"meaning": "同本义。", "cites": [{"t": "尖,锐也。", "b": "《广韵》"}]}, {"meaning": "音调细而高,刺耳。", "cites": [{"t": "促织声尖尖似针,更深刺着旅人心。", "b": "贾岛《客思》"}], "words": [{"w": "尖声;尖嗓子;尖儿", "t": "戏曲中指忽然高亢的唱腔"}, {"w": "尖脆", "t": "形容声音尖细清脆"}, {"w": "尖厉", "t": "形容声音高而刺耳。"}]}, {"meaning": "细长的手指。", "cites": [{"t": "歌彻阳春酒半醺,玉尖搦管蘸香云。", "b": "杨维桢《学书诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('416wx','劣','1','liè','力','6','','[{"pinyin": "liè", "defs": [{"meaning": "(会意。从力,从少。这是合并两个字的意思而构成的会意字。本义:弱;小)。"}, {"meaning": "同本义。", "cites": [{"t": "劣,弱也。", "b": "《说文》"}, {"t": "寿命长短,骨体强劣,各有人焉。", "b": "曹植《辩道论》"}], "words": [{"w": "劣马", "t": "瘦弱的马;又指烈性马"}, {"w": "劣弱", "t": "衰弱;懦弱。"}]}, {"meaning": "少,不足。", "cites": [{"t": "夫德劣故用兵,犯法故施刑。", "b": "《论衡》"}]}, {"meaning": "不好;低劣,与“优”相对。", "cites": [{"t": "优劣异名。", "b": "《论衡·气寿》"}, {"t": "必能使行阵和睦,优劣得所。", "b": "诸葛亮《出师表》"}, {"t": "羸牛劣马。", "b": "《齐民要术·养牛马》"}], "words": [{"w": "劣性", "t": "恶劣的品性"}, {"w": "劣缺", "t": "不好,恶劣"}, {"w": "劣衿", "t": "品行恶劣的生员。"}]}, {"meaning": "认为不好。", "cites": [{"t": "成以其小,劣之。", "b": "《聊斋志异·促织》"}]}, {"meaning": "劣下(低能;低下);劣弟(在平辈或朋友间表示自谦的称呼);劣丈(在世交中,长辈对晚辈表示自谦的称呼)。"}, {"meaning": "强;美。", "cites": [{"t": "论着雄心力劣牙爪,今日也合消,也合消封妻荫子,禄重官高。", "b": "元·尚仲贤《三夺槊》"}]}, {"meaning": "仅,只。", "cites": [{"t": "学谢朓劣得“黄鸟度青枝”。", "b": "《梁书·钟嵘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('417wx','光','1','guāng','儿','6','','[{"pinyin": "guāng", "defs": [{"meaning": "(会意。甲骨文字形,“从火,在人上”。本义:光芒,光亮)。"}, {"meaning": "同本义。", "cites": [{"t": "光,明也。", "b": "《说文》"}, {"t": "光,晃也,晃晃然也。亦言广也,所照广远也。", "b": "《释名·释天》"}, {"t": "与日月兮齐光。", "b": "《楚辞·九歌·云中君》"}, {"t": "能游冥冥者与日月同光。", "b": "《淮南子·俶真》"}, {"t": "日月淑清而扬光。", "b": "《淮南子·本经》"}, {"t": "国之光。", "b": "《易·观》"}, {"t": "夜未央,庭燎之光。", "b": "《诗·小雅·庭燎》"}, {"t": "推此志也,虽与日月争光可也。", "b": "《史记·屈原列传》"}, {"t": "光远而自他有耀者也。", "b": "《左传·庄公二十二年》"}, {"t": "光明之耀也。", "b": "《国语·晋语》"}, {"t": "容光必照焉。", "b": "《孟子》"}, {"t": "山有小口,仿佛若有光。", "b": "晋·陶渊明《桃花源记》"}, {"t": "有红光一缕起土桥,直射城西。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "阳光;灯光;反光", "t": "反射的光线"}, {"w": "色光", "t": "带颜色的光"}, {"w": "晨光", "t": "清晨的太阳光"}, {"w": "曙光", "t": "清晨的日光"}, {"w": "光晃", "t": "光芒闪烁。"}]}, {"meaning": "色泽;光彩。", "cites": [{"t": "妾有绣腰襦,葳蕤自生光。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "蛾脸不舒,中袖无光。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "丝光;油光", "t": "光亮润泽"}, {"w": "光色", "t": "光彩色泽"}, {"w": "砑光", "t": ""}]}, {"meaning": "荣耀;昭著。", "cites": [{"t": "邦家之光。", "b": "《诗·齐风·南山有台》"}, {"t": "连我脸色都无光了。", "b": "《儒林外史》"}, {"t": "士之处世,而望名誉之光,道德之行,难已。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "为国争光;沾光;光宠", "t": "光荣;增光"}, {"w": "光国", "t": "为国争光"}, {"w": "光天", "t": "光辉达于天下"}, {"w": "光隆", "t": "光辉隆盛"}, {"w": "光烂", "t": "光辉明亮"}, {"w": "光晶", "t": "光辉"}, {"w": "光赫", "t": "光辉显赫。"}]}, {"meaning": "光阴,时光。", "cites": [{"t": "始屏忧以愉思,乐兹情于寸光。", "b": "南朝宋·鲍照《观漏赋》"}], "words": [{"w": "寸光", "t": "短暂的光阴"}, {"w": "光阴荏苒", "t": "时光一天一天地逝去。荏苒:渐渐过去"}, {"w": "光景如梭", "t": "光阴如梭。形容时间过得很快"}, {"w": "光阴拈指", "t": "阳光在弹指间逝去。形容时间过得很快。"}]}, {"meaning": "景色。", "cites": [{"t": "上下天光,一碧万顷。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "风光;山光", "t": ""}]}, {"meaning": "称人来访的敬词。", "cites": [{"t": "四位老先生,今日光顾小园,老夫有何德能?", "b": "明·桑绍良《独乐园司马入桐》"}]}, {"meaning": "光明,明亮。", "cites": [{"t": "宝剑直千金,被服光且鲜。", "b": "三国蜀·曹植《名都篇》"}], "words": [{"w": "光净", "t": "明亮洁净"}, {"w": "光朗朗", "t": "光亮"}, {"w": "光眼", "t": "大而有神的眼"}, {"w": "光灯", "t": "明亮的灯火"}, {"w": "光润", "t": "光亮润泽。"}]}, {"meaning": "光滑。", "cites": [{"t": "白沙青石光无泥。", "b": "唐·杜甫《中丞严公雨垂寄见忆一绝奉答二绝》"}], "words": [{"w": "这种纸很光;磨光;光出律", "t": "光滑"}, {"w": "光碌碌", "t": "光圆滚动的样子"}, {"w": "光圆", "t": "光滑圆溜"}, {"w": "光油油", "t": "光滑明亮。"}]}, {"meaning": "裸露。", "cites": [{"t": "光头圆脑作僧看。", "b": "宋·郑清之《咏茄》"}], "words": [{"w": "光出溜", "t": "光秃"}, {"w": "光塌塌", "t": "光秃秃的样子"}, {"w": "光板板", "t": "平而裸露的。"}]}, {"meaning": "(guǎng)。广大,宽阔。", "cites": [{"t": "光被四表,格于上下。", "b": "《书·尧典》"}, {"t": "昔武王克商,光有天下。", "b": "《左传·昭公二十八年》"}], "words": [{"w": "地光", "t": "地域广大。"}]}, {"meaning": "照耀。", "cites": [{"t": "惟公德明光于上下。", "b": "《书·洛诰》"}], "words": [{"w": "光烛", "t": "照耀。"}]}, {"meaning": "增辉,发扬光大。", "cites": [{"t": "诚宜开张圣听,以光先帝遗德,恢弘志士之气。", "b": "诸葛亮《出师表》"}], "words": [{"w": "光宗耀祖;光国", "t": "为国争光"}, {"w": "光德", "t": "显扬有德之人"}, {"w": "光价", "t": "显扬其身价"}, {"w": "光演", "t": "光大延续"}, {"w": "光昌", "t": "显扬昌盛"}, {"w": "光前", "t": "光大前人的功业。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('418wx','当','1','dāng dàng','彐','6','','[{"pinyin": "dāng", "defs": [{"meaning": "(形声。从田,尚声。本义:两块田相当、相等)。"}, {"meaning": "对等;相当于。", "cites": [{"t": "当,田相值也。", "b": "《说文》"}, {"t": "必当其位。", "b": "《吕氏春秋·孟夏纪》"}, {"t": "蔽贤者当之。", "b": "《孟子·离娄下》"}, {"t": "朱也当御。", "b": "《国语·晋语》"}, {"t": "当之者戕焉。", "b": "《国语·晋语一》"}], "words": [{"w": "旗鼓相当;门当户对;当才", "t": "才能与所任之事相当"}, {"w": "当匹", "t": "匹敌;对等"}, {"w": "实力相当", "t": ""}]}, {"meaning": "面对着。", "cites": [{"t": "木兰当户织。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "当户", "t": "对着门户"}, {"w": "当风", "t": "正对着风"}, {"w": "当着矮人,别说短话", "t": "面对着某种有缺陷的人,不要说有关他短处的话,以避影射之嫌"}, {"w": "当头对面", "t": "面对面。"}]}, {"meaning": "承担。", "cites": [{"t": "念窦娥葫芦提当罪衍。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "当不起", "t": "谦词。表示担当不起他人的夸奖或款待"}, {"w": "当不得", "t": "奈何不得"}, {"w": "当不过", "t": "受不住;受不了。"}]}, {"meaning": "主持。", "cites": [{"t": "蚩尤明乎天道,故使为当时。", "b": "《管子·五行》"}, {"t": "北邀当国者相见。", "b": "宋·文天祥《指南录·后序》"}, {"t": "张居正当国。", "b": "《明史·海瑞传》"}], "words": [{"w": "当室", "t": "主持家事。今称当家"}, {"w": "当家之事", "t": "理家立业"}, {"w": "当家三年狗也嫌", "t": "主持家政的容易得罪人,讨人嫌弃。"}]}, {"meaning": "阻挡。", "cites": [{"t": "汝不知夫螳螂乎,怒其臂以当车辙,不知其不胜任也。", "b": "《庄子·人间世》"}], "words": [{"w": "螳臂当车;别当道站着;当拦", "t": "阻拦。"}]}, {"meaning": "用武力抵敌。", "cites": [{"t": "非刘豫州莫可以当曹操者。", "b": "《资治通鉴》"}], "words": [{"w": "万夫不当之勇;当关", "t": "守关"}, {"w": "一夫当关,万夫莫开", "t": ""}]}, {"meaning": "应当。", "cites": [{"t": "吾闻二世少子也,不当立,当立者乃公子扶苏。", "b": "《史记·陈涉世家》"}], "words": [{"w": "当用的还得用;当立之年", "t": "指三十岁"}, {"w": "当断不断", "t": "该做出决断的时候不能决断。"}]}, {"meaning": "判决罪人,断狱。", "cites": [{"t": "臣知欺大王罪当诛。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "而乃劾魏其矫先帝诏,罪当弃市。", "b": "《史记·魏其武安侯列传》"}]}, {"meaning": "在。", "cites": [{"t": "当春乃发生。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "当是时,妇手拍儿声,口中鸣声…一时齐发。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "当堂", "t": "当场,在现场"}, {"w": "当出", "t": "当初"}, {"w": "当来", "t": "向来;当初"}, {"w": "当便", "t": "即便;即就。"}]}, {"meaning": "本,这。", "cites": [{"t": "[兄子彦询]病卒,豹取急,亲送柩还乡,悲痛伤惜,以为丧当家之宝。", "b": "唐·李延寿《北史·房豹传》"}], "words": [{"w": "当家", "t": "本家"}, {"w": "当晚;当夜;当境", "t": "本境"}, {"w": "当坊", "t": "当方。本地"}, {"w": "当港", "t": "此港,本港。"}]}, {"meaning": "假使。", "cites": [{"t": "向使三国各爱其地,齐人勿附于秦,刺客不行,良将犹在,则胜负之数,存亡之理,当与秦相较,或未易量。", "b": "宋·苏洵《六国论》"}]}]}, {"pinyin": "dàng", "defs": [{"meaning": "主领;典领。", "cites": [{"t": "诏招摇与太阴兮,伏钩使当兵。", "b": "扬雄《甘泉赋》"}]}, {"meaning": "抵押,用实物作抵押向当铺借钱。", "cites": [{"t": "以王子姑曹当之,而后止。", "b": "《左传·哀公八年》"}, {"t": "虞所赍赏,典当胡夷。", "b": "《后汉书·刘虞传》"}, {"t": "走笔还诗债,中由衣当药钱。", "b": "唐·白居易《自咏老身示家属》"}], "words": [{"w": "当衣服;他把房子当了", "t": ""}]}, {"meaning": "当作;算是。", "cites": [{"t": "安步以当车。", "b": "《战国策·齐策四》"}], "words": [{"w": "当三钱", "t": "一个钱当三个钱用。这是宋朝的一种制钱"}, {"w": "当十钱", "t": "币值以一当十"}, {"w": "当甚", "t": "算什么"}, {"w": "当耳边风", "t": ""}]}, {"meaning": "抵得上。", "cites": [{"t": "以一仪而当汉中地。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "一个当俩;以一当十;当抵", "t": "抵挡。"}]}, {"meaning": "顶替。", "cites": [{"t": "募有能捕之者,当其租入。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "适合,适当。", "cites": [{"t": "古法采草药多用二月、八月,此殊未当。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "将献公堂,惴惴恐不当意,思试之斗以觇之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "只要措施得当就没问题;用词不当;当家子", "t": "同一家族中的人。"}]}, {"meaning": "指事情发生的那个时候或地方。相当于“本”、“此”。", "cites": [{"t": "当夜调度已定。", "b": "《三国演义》"}], "words": [{"w": "当下", "t": "那个时候"}, {"w": "当年;当天", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('419wx','早','1','zǎo','日','6','','[{"pinyin": "zǎo", "defs": [{"meaning": "(会意。小篆字形,上面是“日”,下面是“甲”。“甲”的最早写法象“十”,指皮开裂,或东西破裂。“早”即天将破晓,太阳冲破黑暗而裂开涌出之意。本义:早晨)。"}, {"meaning": "同本义。", "cites": [{"t": "早,晨也。", "b": "《说文》"}, {"t": "晨初为早。", "b": "《诗·召南·小星》疏"}, {"t": "是谓老服。", "b": "《老子》"}, {"t": "早夜以思。", "b": "唐·韩愈《原毁》"}, {"t": "早莺争暖树。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "早暮咈吾耳。", "b": "唐·柳宗元《柳河东集》"}, {"t": "早出暮归。", "b": "《聊斋志异·促织》"}], "words": [{"w": "清早", "t": "清晨"}, {"w": "明早", "t": "明天早上"}, {"w": "早出晚归", "t": "整日在外"}, {"w": "起早贪黑;早天", "t": "早晨的天空"}, {"w": "早角", "t": "早晨的号角声"}, {"w": "早朝", "t": "早晨朝参"}, {"w": "早膳", "t": "吃早饭"}, {"w": "早霞", "t": "朝霞"}, {"w": "早堂", "t": "旧时官府早晨坐衙治事称“早堂”"}, {"w": "大清早", "t": ""}]}, {"meaning": "本来;已经。", "cites": [{"t": "媳妇儿守寡又早三个年头,服孝将除了也。", "b": "关汉卿《窦娥冤》"}], "words": [{"w": "早来", "t": "本是;已经"}, {"w": "早为", "t": "已是。"}]}, {"meaning": "比一定的时间靠前。", "cites": [{"t": "晨往,寝门辟矣,盛服将朝。尚早,坐而假寐。", "b": "《左传·宣公二年》"}, {"t": "早与之绝。", "b": "《资治通鉴》"}, {"t": "早定大计。", "b": ""}], "words": [{"w": "他早走了;早死了;早世", "t": "过早地死去;夭死。"}]}, {"meaning": "何时;何日。", "cites": [{"t": "山水朝来笑问人:“翁早归来也?", "b": "宋·辛弃疾《卜算子》"}]}, {"meaning": "特指年幼时。", "cites": [{"t": "早岁那知世事艰,中原北望气如山。", "b": "宋·陆游《书愤》诗"}], "words": [{"w": "早年", "t": ""}]}, {"meaning": "在通常、预期、规定或实际的时间以前。是迟或晚的反义词。", "cites": [{"t": "早救之,孰与晚救之便?", "b": "《战国策·齐策一》"}, {"t": "土气有早晚。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "自有早晚。", "b": ""}], "words": [{"w": "今年春天来得早;早间", "t": "不久前"}, {"w": "迟早", "t": "或早或晚"}, {"w": "趁早", "t": "抓紧时机或提前时间"}, {"w": "提早", "t": "提前"}, {"w": "早律", "t": "早来的季候"}, {"w": "推测结果还为时太早;六十岁退休可不早;早早", "t": "比常时为早;很早。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('420wx','吁','1','xū yū yù','口','6','','[{"pinyin": "xū", "defs": [{"meaning": "(形声。从口,于声。本义:表示惊怪、不然、感慨等) 同本义。", "cites": [{"t": "王曰:“吁!来!有邦有土,告尔祥刑。”", "b": "《书·吕刑》"}, {"t": "吁!惊也。", "b": "《说文》"}, {"t": "王曰:“吁,来!…”", "b": "《史记·周本纪》"}, {"t": "吁!是何言欤?", "b": "《法言·君子》。注:“吁!骇叹之声。”"}], "words": [{"w": "吁咈", "t": "表示不以为然之意"}, {"w": "吁咈都俞", "t": "吁咈,吁俞。用以赞美君臣间论政之和洽。见《书·尧典》"}, {"w": "吁嗟", "t": "表示忧伤或有所感;表示赞美。"}]}, {"meaning": "叹息,叹气。", "cites": [{"t": "香车辗尽关山日,弹罢琵琶只自吁。", "b": "《明珠记》"}], "words": [{"w": "吁唏", "t": "吁嘘。嘘唏,叹息"}, {"w": "吁气", "t": "叹气"}, {"w": "吁嗟", "t": "哀叹;叹息"}, {"w": "吁嗟", "t": "慨叹"}, {"w": "吁然", "t": "感叹的样子"}, {"w": "吁叹", "t": "叹息;哀叹"}, {"w": "吁嘻", "t": "感叹。"}]}]}, {"pinyin": "yū", "defs": [{"meaning": "吆喝牲口的声音。"}]}, {"pinyin": "yù", "defs": [{"meaning": "呼天而告。", "cites": [{"t": "夫知保抱携持厥妇子,以哀吁天,徂厥亡出执。", "b": "《书·召诰》"}], "words": [{"w": "吁天", "t": "呼天而告"}, {"w": "吁号", "t": "呼叫"}, {"w": "呼吁", "t": "呼告请求援助或主持公道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('421wx','吐','1','tǔ tù','口','6','','[{"pinyin": "tǔ", "defs": [{"meaning": "(形声。从口,土声。本义:东西从口腔中涌出)。"}, {"meaning": "同本义。", "cites": [{"t": "吐,写也。", "b": "《说文》"}, {"t": "柔则茹之,刚则吐之。", "b": "《诗·大雅·烝民》"}, {"t": "然我一沫三捉发,一饭三吐哺。", "b": "《史记·鲁周公世家》"}, {"t": "血入乎牙,不肯吐口。", "b": "韩愈《元和圣德》"}, {"t": "机发吐丸。", "b": "《后汉书·张衡传》"}, {"t": "与风水相吞吐。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "吐气纳元", "t": "道家的一种练功修身之法。吐、纳是我国古人的一种养生之术"}, {"w": "吐信", "t": "吐舌头"}, {"w": "吞吐", "t": "吞进和吐出"}, {"w": "吐沫", "t": "吐出沫子"}, {"w": "吐茹,吐哺", "t": "吐出嘴里食物。"}]}, {"meaning": "摆出,亮出 。武术用语。", "cites": [{"t": "[燕青] 把布衫脱将下来,吐个架子。", "b": "《水浒传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "tù", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('422wx','吓','1','hè xià','口','6','','[{"pinyin": "hè", "defs": [{"meaning": "(形声。从口,赫声。本义:恐吓,恫吓) 同本义。", "cites": [{"t": "先生造此等言语,意欲吓编吾马。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "吓骗", "t": "恐吓诈骗"}, {"w": "吓诈", "t": "恐吓讹诈。"}]}]}, {"pinyin": "xià", "defs": [{"meaning": "使害怕。", "cites": [{"t": "吓,以口拒人谓之吓。", "b": "《集韵》"}], "words": [{"w": "杀鸡吓猴;惊吓", "t": "因意外的刺激而害怕"}, {"w": "吓呼", "t": "吓唬"}, {"w": "吓魂台", "t": "迷信指阴司中折磨鬼魂之处。借指令人失魂落魄的地方。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('423wx','虫','1','chóng huǐ','虫','6','','[{"pinyin": "chóng", "defs": [{"meaning": "(会意。汉字部首之一,从“虫”的字多与昆虫、蛇等有关。按:“虫”甲骨文字形象蛇形,本读huǐ,即虺,是一种毒蛇。后为“蟲”的简体。本义:昆虫的通称)。"}, {"meaning": "同本义。", "cites": [{"t": "虫,有足谓之虫,无足谓之豸。", "b": "《说文》"}, {"t": "风为虫。", "b": "《孔子家语·执辔》"}, {"t": "烦气为虫。", "b": "《淮南子·精神》"}, {"t": "禽兽虫蛾。", "b": "《列子·黄帝》"}, {"t": "虫飞薨薨。", "b": "《诗·齐风·桑柔》"}, {"t": "古人之观于天地、山川、草木、虫鱼、鸟兽,往往有得。", "b": "王安石《游褒禅山记》"}, {"t": "人民不胜虫蛇。", "b": "《韩非子·五蠹》"}]}, {"meaning": "古代泛指所有的动物。", "cites": [{"t": "蛟虫死。", "b": "《吕氏春秋·览冥》"}], "words": [{"w": "长虫", "t": "大虫。方言。指老虎"}, {"w": "虫虾", "t": "指鱼虾"}, {"w": "虫虱", "t": "泛指蛀虫"}, {"w": "虫网", "t": "谓蜘蛛布网。"}]}]}, {"pinyin": "huǐ", "defs": [{"meaning": "“虺”的本字。毒蛇名。", "cites": [{"t": "猨翼之山多蝮虫。", "b": "《山海经·南山经》"}], "words": [{"w": "蝮虫", "t": "蝮蛇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('424wx','曲','1','qū qǔ','曰','6','','[{"pinyin": "qū", "defs": [{"meaning": "弯曲,不直。", "cites": [{"t": "曲,象器曲受物之形。", "b": "《说文》"}, {"t": "曲,折也。", "b": "《广雅·释诂一》"}, {"t": "木曰曲直。", "b": "《书·洪范》"}, {"t": "曲,不直也。", "b": "《玉篇》"}, {"t": "木直中绳,輮以为轮,其曲中规。", "b": "《荀子》"}, {"t": "曲挺纵横。", "b": "《徐霞客游记·游黄山记》"}, {"t": "以曲为美。", "b": "清·龚自珍《病梅馆记》"}, {"t": "之疏之曲。", "b": ""}], "words": [{"w": "曲录", "t": "弯弯曲曲"}, {"w": "曲律", "t": "曲吕。弯曲的样子"}, {"w": "曲弯弯", "t": "像弓一样弯"}, {"w": "曲蟮", "t": "蚯蚓"}, {"w": "曲盖", "t": "古时仪杖用的曲柄华盖"}, {"w": "曲兵", "t": "形体弯曲的兵器。"}]}, {"meaning": "假借为“局”。狭隘,拘泥。", "cites": [{"t": "毋使人曲之。", "b": "《管子·侈靡》"}]}, {"meaning": "理屈;理亏。", "cites": [{"t": "其言曲而中。", "b": "《易·系辞下》"}, {"t": "曲在赵。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "曲在秦。", "b": ""}, {"t": "以负秦曲。", "b": ""}], "words": [{"w": "曲挠", "t": "无罪而被枉屈"}, {"w": "曲论", "t": "歪曲事实的议论;狡辩。"}]}, {"meaning": "弯曲的地方,亦指幽深之处。", "cites": [{"t": "在汾一曲。", "b": "《诗·魏风·汾沮洳》"}, {"t": "汾之一曲。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "河曲", "t": "河流弯曲的地方"}, {"w": "曲阿", "t": "屋的曲角"}, {"w": "曲房", "t": "内室,密室"}, {"w": "曲屋", "t": "周旋曲屈的楼阁"}, {"w": "曲隈", "t": "曲折隐蔽之处。"}]}, {"meaning": "蚕箔,用苇或竹编制的养蚕的器具。", "cites": [{"t": "勃以织曲薄为生。", "b": "《史记·周勃世家》"}], "words": [{"w": "曲簿", "t": "养蚕的器具。"}]}, {"meaning": "使弯曲。", "cites": [{"t": "饭疏食饮水,曲肱而枕之,乐亦在其中矣。", "b": "《论语·述而》"}, {"t": "弘曲躬而自卑。", "b": "《后汉书·郑弘传》"}], "words": [{"w": "曲匝", "t": "身体屈曲辗转"}, {"w": "曲肱", "t": "弯着胳膊作枕头。比喻清贫而闲适的生活。"}]}]}, {"pinyin": "qǔ", "defs": [{"meaning": "乐曲,歌曲。", "cites": [{"t": "莫辞更坐弹一曲,为君翻作琵琶行。", "b": "唐·白居易《琵琶行(并序)》诗"}, {"t": "快弹数曲。", "b": ""}, {"t": "曲罢悯然。", "b": ""}, {"t": "曲终收拨。", "b": ""}, {"t": "五更转曲。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "聂耳作曲,田汉作词;编曲", "t": ""}]}, {"meaning": "一种韵文形式,盛行于元代,又称元曲。", "cites": [{"t": "不复能终曲。", "b": "清·侯方域《壮悔堂文集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('425wx','团','1','tuán','囗','6','','[{"pinyin": "tuán", "defs": [{"meaning": "(形声。从囗(wéi),专声。本义:圆)。"}, {"meaning": "同本义。", "cites": [{"t": "团,圆也。", "b": "《说文》"}, {"t": "裁为合欢扇,团团似明月。", "b": "《文选·班婕妤·怨歌行》"}], "words": [{"w": "团扇", "t": "圆形的扇子。古代多用于帝王宫内,又称宫扇"}, {"w": "团领", "t": "圆领"}, {"w": "团栾", "t": "形容圆的样子"}, {"w": "团茅", "t": "团苞,团焦。圆形草屋"}, {"w": "团城", "t": "北京故宫西北、北海南门口的圆形围城。"}]}, {"meaning": "聚集,集合。", "cites": [{"t": "众宾团坐。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "团书", "t": "通知聚会的请柬。"}]}, {"meaning": "分不开;聚合在一起。", "cites": [{"t": "西园歌舞骤然稀,只有多情蝴蝶作团飞。", "b": "宋·石孝友《南歌子》"}], "words": [{"w": "团体", "t": "组织起来,团结为一体。"}]}, {"meaning": "团练。", "cites": [{"t": "谢庄办团。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "三保戒团众。", "b": ""}]}, {"meaning": "团子  米或粉制成的球形食品。", "cites": [{"t": "寒食枣团店,春低杨柳枝。", "b": "唐·白居易《寒食日过枣团店》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('426wx','吕','1','lǚ','口','6','','[{"pinyin": "lǚ", "defs": [{"meaning": "(象形。甲骨文字形,象脊骨形,是“膂”的本字。本义:脊梁骨)。"}, {"meaning": "同本义。“膂”的古字。", "cites": [{"t": "吕,脊骨也。象形。", "b": "《说文》"}, {"t": "氏曰有吕。", "b": "《国语·周语下》。注:“吕之为言膂也。”"}, {"t": "尻髋脊膂腰背吕。", "b": "《急就篇》。颜师古注:“吕,脊骨也。”"}]}, {"meaning": "客舍。", "cites": [{"t": "自今以来,叚门逆吕,赘婿后父,勿令为户,勿鼠田宇。", "b": "睡虎地秦墓竹简《为吏之道》"}]}, {"meaning": "古国名 。故地在今河南省南阳西。周时赐姓姜。春秋初年为楚所灭。"}, {"meaning": "吕县 。春秋宋邑。在今江苏省铜山县东南。"}, {"meaning": "吕州 。春秋晋邑。在今山西省霍县西南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('427wx','同','1','tóng tòng','口','6','','[{"pinyin": "tóng", "defs": [{"meaning": "(会意。从冃,从口。冃(mào),重复。本义:聚集)。"}, {"meaning": "同本义。", "cites": [{"t": "同,合会也。", "b": "《说文》"}, {"t": "同重体合类。", "b": "《墨子·经上》"}, {"t": "同人亲也。", "b": "《易·杂卦》"}, {"t": "六曰同衣服。", "b": "《周礼·大司徒》"}], "words": [{"w": "云同", "t": "云彩聚集"}, {"w": "同天", "t": "共存于人世间"}, {"w": "同合", "t": "使相一致;融会"}, {"w": "同流", "t": "诸水合流。"}]}, {"meaning": "相同,一样,共同(侧重于同样,齐一)。", "cites": [{"t": "同事之人,不可不审察也。", "b": "《韩非子·说林上》"}, {"t": "鸟兽不可与同群。", "b": "《论语·微子》"}, {"t": "同予者何人。", "b": "宋·周敦颐《爱莲说》"}, {"t": "同于真耶。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "同于幻耶。", "b": ""}], "words": [{"w": "同心戮力", "t": "同心合力"}, {"w": "同功一体", "t": "功绩地位一样"}, {"w": "同号", "t": "称号相同;运算符号相同"}, {"w": "同忾", "t": "相同的愤慨"}, {"w": "同义", "t": "仁义或道义相同"}, {"w": "同义字", "t": "意义相同的字"}, {"w": "同源字", "t": "音、义相同或相近。"}]}, {"meaning": "参与;一起干某事。", "cites": [{"t": "不知三军之事而同三军之政者,则军士惑矣。", "b": "《孙子·谋攻》"}], "words": [{"w": "同举", "t": "一同举荐"}, {"w": "同乐", "t": "一同娱乐"}, {"w": "同栖", "t": "一同栖息"}, {"w": "同休", "t": "同享福禄"}, {"w": "同枕", "t": "共枕而卧"}, {"w": "同利", "t": "共享利益"}, {"w": "同车", "t": "同乘一车"}, {"w": "同室", "t": "同居一室。"}]}, {"meaning": "共,共一个。", "cites": [{"t": "上下同欲者胜。", "b": "《孙子·谋政》"}, {"t": "俗之同病。", "b": "清·刘开《问说》"}, {"t": "同社诸君子。", "b": "明·张溥《五人墓碑记》"}, {"t": "以同姓为吾后。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "同福", "t": "共同的福禄。"}]}, {"meaning": "齐一;统一。", "cites": [{"t": "死去方知万事空,但悲不见九州同。", "b": "宋·陆游《示儿》"}]}, {"meaning": "共同。到一处。", "cites": [{"t": "同行十二年。", "b": "《乐府诗集·木兰诗》"}, {"t": "同是宦游人。", "b": "唐·王勃《杜少府之任蜀州》"}, {"t": "少同学。", "b": "明·魏禧《大铁椎传》"}, {"t": "既同寝。", "b": ""}], "words": [{"w": "同参", "t": "共同参与"}, {"w": "同晷", "t": "同受日光照耀"}, {"w": "同奖", "t": "共同辅助"}, {"w": "同庆", "t": "共同庆贺"}, {"w": "同进", "t": "一同前进"}, {"w": "同举", "t": "一同举荐"}, {"w": "同来同去;同吃同住;同宿;同游", "t": ""}]}, {"meaning": "中国古代诸侯朝见天子的六礼之一。每隔十二年,诸侯一齐来朝见天子叫“同”。", "cites": [{"t": "奠此中国,四夷来同。", "b": "王安石《赠贾魏公神道碑》"}]}, {"meaning": "中国古代土地面积单位,地方百里为同。", "cites": [{"t": "且昔天子之地一圻,列国一同。", "b": "《左传·襄公二十五年》"}]}, {"meaning": "中国古代爵一类的酒器。"}, {"meaning": "引进共同行动者 。", "words": [{"w": "我同你去;我同她说话", "t": ""}]}, {"meaning": "给,为。", "cites": [{"t": "合共还他三十六,还要同他做一年。", "b": "《中国歌谣资料》"}]}, {"meaning": "和,表示并列关系 。", "words": [{"w": "我同农民;教师同塾师", "t": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "tòng", "defs": [{"meaning": "——见“胡同”hútòng。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('428wx','吊','1','diào','口','6','','[{"pinyin": "diào", "defs": [{"meaning": "(吊为弔的俗字。会意。甲骨文字形,象人持弋射矰(zēng)缴之形。古人死而不葬,只是放在荒野里用柴薪盖着,但怕禽兽要来吃,连送丧的亲友都带着弓箭前来帮助驱除。本义:悼念死者)。"}, {"meaning": "同本义。", "cites": [{"t": "弔,问终也。古之葬者,厚衣之以薪。从人持弓,会敺禽。", "b": "《说文》"}, {"t": "知生者弔,古弔辞曰,如何不淑。", "b": "《礼记·曲礼》"}, {"t": "敬吊先生。", "b": "贾谊《吊屈原赋》"}], "words": [{"w": "吊纸", "t": "在死者灵前烧纸吊祭"}, {"w": "吊问", "t": "吊念死者,慰问生者"}, {"w": "吊死", "t": "吊慰死者;自缢而死"}, {"w": "吊祠", "t": "吊唁祭祀。"}]}, {"meaning": "引申为慰问。", "cites": [{"t": "人皆吊之。", "b": "《淮南子·人间训》"}, {"t": "有君不弔。", "b": "《左传·襄公十四年》。注:“恤也。”"}, {"t": "肃请得奉命吊表二子,并慰劳其军中用事者。", "b": "《资治通鉴》"}], "words": [{"w": "吊民", "t": "慰问遭受不幸的人"}, {"w": "吊伐", "t": "吊民伐罪。慰问穷苦的人"}, {"w": "吊恤", "t": "安慰抚恤"}, {"w": "吊水", "t": "慰问水灾的受害者"}, {"w": "吊临", "t": "灵前哭吊,吊唁。"}]}, {"meaning": "在牌戏中 。如:接连吊三圈主牌。如:吊主。"}, {"meaning": "提取。", "cites": [{"t": "即于狱中吊出秋公,立时释放。", "b": "明·冯梦龙《醒世恒言》"}], "words": [{"w": "吊案", "t": "提取案卷"}, {"w": "吊卷", "t": "提取文卷"}, {"w": "吊查", "t": "提取查阅。"}]}, {"meaning": "落下。", "cites": [{"t": "鸦雀无声,比皇帝出来还要静悄得多呢,连一根针吊在地上都听得见响!", "b": "《老残游记》"}], "words": [{"w": "吊了稍", "t": "吊稍。指没了钱,银子用完了"}, {"w": "吊下", "t": "掉下"}, {"w": "吊谎", "t": "掉谎。说谎。"}]}, {"meaning": "哀伤,悲悯。", "cites": [{"t": "中心吊兮。", "b": "《诗·桧风·匪风》"}], "words": [{"w": "吊影", "t": "独居无伴,对影自怜。"}]}, {"meaning": "善;良好。", "cites": [{"t": "无敢不吊。", "b": "《书·费誓》"}, {"t": "不吊昊天。", "b": "《诗·小雅·节南山》"}, {"t": "昊天不吊。", "b": "《左传·哀公十六年》"}, {"t": "帅群不吊之人,以行乱于王室。", "b": "《左传·昭公二六年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('429wx','吃','1','chī','口','6','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从口,乞声。本义:口吃,结巴) 同本义。", "cites": [{"t": "吃,言蹇难也。", "b": "《说文》"}, {"t": "昌为人吃。", "b": "《汉书·周昌传》"}], "words": [{"w": "吃子", "t": "口吃的人"}, {"w": "吃吃", "t": "形容口吃或有话说不出口。"}]}, {"meaning": "(形声。从口,契声。本义:吃东西。按:“吃”在古代一般不当“吃东西”讲。“吃东西”的意义古代写作“喫”。汉字简化后“喫”写作“吃”)。"}, {"meaning": "吃东西。与“喝”形成对照。", "cites": [{"t": "友闻白羊肉美,一生未曾得喫,故冒求前耳。", "b": "《世说新语·任诞》"}, {"t": "临岐意颇切,对酒不能吃。", "b": "杜甫《送李校书二十六韵》"}], "words": [{"w": "吃面包;吃喝;吃用", "t": "泛指吃、穿等生活资料和用费"}, {"w": "吃相", "t": "吃喝时的姿态、样子。"}]}, {"meaning": "被;让;由于。", "cites": [{"t": "自从嫁得你哥哥,吃他忒善了,被人欺负,才得到这里。", "b": "《金瓶梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('430wx','因','1','yīn','囗','6','','[{"pinyin": "yīn", "defs": [{"meaning": "(会意。从囗(wéi)大。大,人。甲骨文字形,象人在车席子上。本义:“茵”的本字,坐垫,车垫)。"}, {"meaning": "同本义。", "cites": [{"t": "因,就也。", "b": "《说文》。朱骏声注:“囗大俱非义。江氏永曰:‘象茵褥之形,中象缝线文理。’按即茵之古文。江说是也。”"}]}, {"meaning": "原因。", "cites": [{"t": "贵贱虽复殊途,因果竟在何处?", "b": "《梁书·范缜传》"}, {"t": "自谓得其势,无因有动摇。", "b": "白居易《有木》诗"}], "words": [{"w": "因果报应", "t": "佛教指物有起因必有结果,善因得善果,恶因得恶果"}, {"w": "前因后果", "t": ""}]}, {"meaning": "机会。", "cites": [{"t": "于今无会因。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "依靠;凭借。", "cites": [{"t": "谁因谁极。", "b": "《诗·傭风·载驰》"}, {"t": "论世之事,因为之备。", "b": "《韩非子·五蠹》"}, {"t": "因人成事者。", "b": "《史记·平原君虞卿列传》"}, {"t": "因厚币用事者臣靳尚。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "因缘(凭借;依据)因赃假位(利用贿赂买得官职", "t": ""}, {"w": "因公假私", "t": "借公家的名义以谋取私利"}, {"w": "因依", "t": "倚傍;依托"}, {"w": "因附", "t": "依附"}, {"w": "因国", "t": "可以依靠、利用的国家。"}]}, {"meaning": "沿袭,承袭。", "cites": [{"t": "殷因于夏礼,所损益可知也。", "b": "《论语·为政》"}, {"t": "因遗策。", "b": "汉·贾谊《过秦论》"}, {"t": "因秦宫室,据其府库。", "b": "张衡《东京赋》"}], "words": [{"w": "因承", "t": "承袭,因袭"}, {"w": "因习", "t": "相沿成习,沿袭。"}]}, {"meaning": "连接。", "cites": [{"t": "水边小丘因古城,上有巨竹数百个。", "b": "宋·陆游《城西接待院后竹下作》"}]}, {"meaning": "顺;顺应。", "cites": [{"t": "因其固然(因:顺着。固然:本来的样子。指牛的自然结构)。", "b": "《庄子·养生主》"}, {"t": "以径寸之木…因势象形,各具情态。(因势象形,就着木头的原样来模拟形状。因,就着,顺着。势,形势,这里指材料本身的形状特征。象,动词,模拟。形,形状)。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "因便", "t": "顺便"}, {"w": "因风吹火", "t": "比喻顺势行事,用力不多。"}]}, {"meaning": "相就;趋赴。", "cites": [{"t": "其民沓贪而忍,不可因也。", "b": "《国语·郑语》"}]}, {"meaning": "由于,因为。", "cites": [{"t": "因前使绝国功,封骞博望侯。", "b": "《史记·卫将军骠骑列传》"}], "words": [{"w": "因地", "t": "原委;因由"}, {"w": "因是", "t": "因此。"}]}, {"meaning": "趁着;乘便。", "cites": [{"t": "因利乘便。", "b": "汉·贾谊《过秦论》"}, {"t": "游于三辅,因入京师。(因,乘便)。", "b": "《后汉书·张衡传》"}]}, {"meaning": "亲,亲近。", "cites": [{"t": "因心则友。", "b": "《诗·大雅·皇矣》"}, {"t": "亲有礼,因重固,闲携贰,覆昏乱,霸王之器也。", "b": "《左传》"}], "words": [{"w": "因心", "t": "亲善仁爱之心"}, {"w": "因母", "t": "亲母。"}]}, {"meaning": "于是,就。", "cites": [{"t": "因以讽谏。", "b": "《后汉书·张衡传》"}, {"t": "驴不胜怒,蹄之。虎因喜,计之…", "b": "唐·柳宗元《三戒》"}, {"t": "因出己虫,纳比笼中。", "b": "《聊斋志异·促织》"}, {"t": "因跳踉大闞,断其喉,尽其肉,乃去。", "b": "唐·柳宗元《三戒·黔之驴》"}]}, {"meaning": "因而。", "cites": [{"t": "因以其伯。", "b": "《诗·大雅·韩奕》"}, {"t": "因使唐雎使于秦。", "b": "《战国策·魏策》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('431wx','吸','1','xī','口','6','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从口,及声。本义:吸气入体内)。"}, {"meaning": "同本义。", "cites": [{"t": "吹呴呼吸,吐故纳新。", "b": "《庄子·刻意》"}, {"t": "不食五谷,吸风引露。", "b": "《庄子·逍遥游》"}], "words": [{"w": "吸呼", "t": "呼吸"}, {"w": "吸留", "t": "變滓喘吸的样子"}, {"w": "吸风", "t": "吸气。道家辟谷养生之术。谓吸食天地之精气;亦作吸西北风。比喻挨饿"}, {"w": "吸新吐故", "t": "吸进新气,吐出浊气。"}]}, {"meaning": "张开口吸,急饮。", "cites": [{"t": "吸湛露之浮凉兮,漱凝霜之?雰雰。", "b": "《楚辞·九章·悲回风》"}, {"t": "左相嵧瘤鶹日兴费万钱,饮如长鲸吸百川。", "b": "唐·杜甫《饮中八仙歌》"}], "words": [{"w": "吸食", "t": "用嘴吸进"}, {"w": "吸霞", "t": "吸食朝霞。道家用以修炼养生"}, {"w": "吸露", "t": "吸饮露水。喻高洁。"}]}, {"meaning": "吸取;吸收;摄取。", "cites": [{"t": "久之,则吸纳他族互相同化,则不同血统而同一民族者有之。", "b": "梁启超《政治学大家伯伦知理之学说》"}], "words": [{"w": "吸纳", "t": "吸收容纳"}, {"w": "吸集", "t": "吸收汇集"}, {"w": "吸利", "t": "搜括钱财。"}]}, {"meaning": "引;吸引。", "cites": [{"t": "寿峰手上就像有吸铁石一样,完全都吸到手上。", "b": "张恨水《啼笑姻缘》"}], "words": [{"w": "异性相吸;吸毒石", "t": "相传能治毒的药石。"}]}, {"meaning": "聚合。", "cites": [{"t": "风尘吸张。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "吸逮", "t": "气聚集而不绝"}, {"w": "吸聚", "t": "翕聚,汇聚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('432wx','吗','1','ma má mǎ','口','6','','[{"pinyin": "ma", "defs": [{"meaning": "用在句末,表示疑问或反诘的语气。", "cites": [{"t": "先生,你会看喉咙吗?", "b": "《老残游记》"}]}]}, {"pinyin": "má", "defs": [{"meaning": "", "words": [{"w": "下午干吗?", "t": ""}]}]}, {"pinyin": "mǎ", "defs": [{"meaning": "译音字。"}, {"meaning": "〔吗啡〕用鸦片制成的有机化合物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('433wx','吆','1','yāo','口','6','','[{"pinyin": "yāo", "defs": [{"meaning": "大声喊。通常指大声斥责人,大声驱赶牲口,高声叫卖,喊劳动号子等。", "cites": [{"t": "现在皇帝还着人吆跑了。", "b": "《大波》"}], "words": [{"w": "吆号子", "t": "大声唱“吆号子”"}, {"w": "吆卖", "t": "大声叫卖"}, {"w": "吆天喝地", "t": "大声喊叫"}, {"w": "吆吆喝喝", "t": "大声喊叫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('434wx','屿','1','yǔ','山','6','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从山,与声。本义:小岛)。"}, {"meaning": "同本义。", "cites": [{"t": "为屿,为嵁,为岩。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "平地小山。", "cites": [{"t": "屿,平地小山也。", "b": "《六书故》"}, {"t": "中央之山宜平,则为坻为屿,若以供吾布席置酒之用也。", "b": "明·袁宏道《嵩游第五》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('435wx','屹','1','yì','山','6','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从山,乞声。本义:山势直立高耸的样子)。"}, {"meaning": "同本义。后泛指耸立的。", "cites": [{"t": "屹山峙以迂郁。(迂郁:盘曲的样子。)", "b": "王延寿《鲁灵光殿赋》"}], "words": [{"w": "屹仡", "t": "挺拔雄劲的样子"}, {"w": "屹峙", "t": "耸立。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('436wx','岁','1','suì','山','6','','[{"pinyin": "suì", "defs": [{"meaning": "(形声。小篆字形。从步,戌(xū)声。“步”有经历的意思。古音“岁、戌”迭韵。本义:岁星。即木星)。"}, {"meaning": "同本义。", "cites": [{"t": "岁,木星也。", "b": "《说文》"}, {"t": "岁在星纪。", "b": "《左传·襄公二十八年》"}], "words": [{"w": "岁君", "t": "太岁。古人称木星为太岁,认为冲犯它不吉利"}, {"w": "岁次", "t": "每年岁星所值的星次与其干支称为岁次。"}]}, {"meaning": "年的别称。", "cites": [{"t": "无衣无褐,何以卒岁?", "b": "《诗·豳风·七月》"}, {"t": "武留匈奴,凡十九岁。", "b": "《汉书·李广苏建传》"}, {"t": "盖一岁之犯死者二焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "三岁贯汝,莫我肯顾。", "b": "《诗·魏风·硕鼠》"}, {"t": "叔向曰:“与其死亡若何?《诗》曰:‘优哉游哉,聊以卒岁。’知也。”", "b": "《左传·襄公二十一年》"}], "words": [{"w": "岁祲", "t": "一年到头妖气弥漫"}, {"w": "岁腊", "t": "年终祭祀祖先"}, {"w": "岁考", "t": "年度考试"}, {"w": "岁事", "t": "诸侯每年秋季朝见天子之事"}, {"w": "岁晏", "t": "岁暮,年尾"}, {"w": "岁华", "t": "年华,岁月。"}]}, {"meaning": "年龄。", "cites": [{"t": "年十二岁,庄襄王死,政代为秦王。", "b": "《史记·秦始皇本纪》"}, {"t": "依新已五岁,转眼成人,汝其善抚之,使之肖我。", "b": "林觉民《与妻书》"}, {"t": "是儿少秦武阳二岁。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "三岁小孩;八十岁的老奶奶;两岁的牛儿正当年", "t": ""}]}, {"meaning": "岁月;时光。", "cites": [{"t": "日月逝矣,岁不我与。", "b": "《论语·阳货》"}, {"t": "那堪正漂泊, 来日岁华新。", "b": "唐·孟浩然《除夜》"}], "words": [{"w": "岁光", "t": "岁月,光阴"}, {"w": "岁华", "t": "时光。"}]}, {"meaning": "年景,一年的农事收成。", "cites": [{"t": "人死,则曰:“非我也,岁也。”", "b": "《孟子·梁惠王上》"}, {"t": "王无罪岁,斯天下之民至焉。", "b": ""}, {"t": "闵闵焉如农夫之望岁。", "b": "《左传·昭公三十二年》"}, {"t": "威后问使者曰:“岁亦无恙耶?民亦无恙耶?王亦无恙耶?", "b": "《战国策·齐策》"}, {"t": "岁恶不入,请卖爵子。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "岁恶", "t": "岁凶。收成不好"}, {"w": "岁登", "t": "年谷丰登"}, {"w": "丰岁;歉岁;岁熟;岁稔", "t": "年成丰熟"}, {"w": "岁丰", "t": "年谷丰收。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('437wx','帆','1','fān','巾','6','','[{"pinyin": "fān", "defs": [{"meaning": "张帆行驶。", "cites": [{"t": "不枉故人书,无因帆江水。", "b": "韩愈《除官赴阙》"}]}, {"meaning": "挂在船桅上利用风力使船前进的布篷。", "cites": [{"t": "孤帆远影碧空尽,唯见长江天际流。", "b": "李白《黄鹤楼送孟浩然之广陵》"}], "words": [{"w": "扬帆;帆力", "t": "帆受风时的推动力"}, {"w": "帆势", "t": "帆篷张挂之势"}, {"w": "帆楫", "t": "船帆和桨。"}]}, {"meaning": "靠帆推进的船舶。", "cites": [{"t": "两岸青山相对出,孤帆一片日边来。", "b": "唐·李白《望天门山》"}], "words": [{"w": "帆舶", "t": "船舶"}, {"w": "帆海", "t": "船行于海。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('438wx','回','1','huí','囗','6','','[{"pinyin": "huí", "defs": [{"meaning": "(囘为回的古字; 廻为迴的俗字。囬、迴同回。象形。甲骨文象渊水回旋之形。本义:回旋;旋转)。"}, {"meaning": "同本义。", "cites": [{"t": "回,转也。", "b": "《说文》"}, {"t": "昭回于天。", "b": "《诗·大雅·云汉》"}, {"t": "图回天下于掌上而辨白黑。", "b": "《荀子·儒效》"}, {"t": "诡文回波。", "b": "《淮南子·本经》"}, {"t": "畔回穴其若兹兮。", "b": "《汉书·叙传》"}, {"t": "虎鼓瑟兮鸾回车。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "山回路转不见君。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "廊腰缦回。", "b": "唐·杜枚《阿房宫赋》"}, {"t": "峰回路转。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "回湍", "t": "回旋的急流"}, {"w": "回倒", "t": "回旋倾倒"}, {"w": "回纡", "t": "迂回。回旋曲折"}, {"w": "回极", "t": "无极回旋的枢轴。"}]}, {"meaning": "环绕; 包围。", "cites": [{"t": "东道少回远。", "b": "《汉书·李广传》"}], "words": [{"w": "回峰", "t": "环绕的山峰"}, {"w": "回圆", "t": "环绕"}, {"w": "回塘", "t": "环曲的水池"}, {"w": "回缭", "t": "围绕"}, {"w": "回互", "t": "回环交互。"}]}, {"meaning": "掉转。", "cites": [{"t": "回车叱牛牵向北。", "b": "唐·白居易《卖炭翁》"}, {"t": "回看射雕处。", "b": "唐·王维《观猎》诗"}, {"t": "兴尽晚回舟。", "b": "宋·李清照《如梦令》"}, {"t": "回头望汝。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "回面", "t": "转过脸"}, {"w": "回眼", "t": "回转目光"}, {"w": "回天", "t": "形容力量很大,能扭转乾坤"}, {"w": "回舆", "t": "掉转马头,返回"}, {"w": "回逆", "t": "倒转。"}]}, {"meaning": "还,返回。", "cites": [{"t": "碧水东流至此回。", "b": "唐·李白《望天门山》"}, {"t": "少小离家老大回。", "b": "唐·贺知章《回乡偶书》"}, {"t": "余逆脱回。", "b": "《广东军务记》"}], "words": [{"w": "回寅", "t": "回到农历正月"}, {"w": "回九", "t": "旧俗新婚后新娘九日后回娘家"}, {"w": "回前线;回跸", "t": "帝王返驾回宫。"}]}, {"meaning": "改变。", "cites": [{"t": "道苟直,虽死不可回也;如回之,莫若亟去其位。", "b": "柳宗元《与韩愈论史官书》"}], "words": [{"w": "回心", "t": "改变心意"}, {"w": "回异", "t": "改变;违反"}, {"w": "回换", "t": "调换;变换"}, {"w": "回变", "t": "转变。"}]}, {"meaning": "违背。", "cites": [{"t": "厥德不回。", "b": "《诗·大雅·大明》"}, {"t": "徐方不回。", "b": "《诗·大雅·常武》"}, {"t": "经德不回,非以干禄也。", "b": "《孟子·尽心下》"}, {"t": "求福不回。", "b": "《后汉书·苏竟传》"}, {"t": "二人之不敢请,亦知始皇之鸷悍而不可回也。", "b": "苏轼《东坡志林》"}]}, {"meaning": "问。", "cites": [{"t": "进得店去,茶房便来回道:“客人,用什么夜膳?”", "b": "《老残游记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('439wx','岂','1','qǐ','山','6','','[{"pinyin": "qǐ", "defs": [{"meaning": "（kai）。安乐。", "cites": [{"t": "王在在镐,岂乐饮酒。", "b": "《诗·小雅·鱼藻》"}, {"t": "既见君子,孔燕岂弟。", "b": "《诗·小雅·蓼萧》"}]}, {"meaning": "(形声。从壴(zhù)省,微省声。壴,陈列乐器。(kǎi)本义:回师时献功之乐)。"}, {"meaning": "“岂”假借作虚词,用在句中或句首,表示反问。"}, {"meaning": "相当于“难道”,“怎么”。", "cites": [{"t": "岂非计久长。", "b": "《战国策·赵策》"}, {"t": "岂若吾乡邻。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "岂其愤世疾邪者耶。", "b": "明·刘基《卖柑者言》"}, {"t": "岂独一琴哉。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "岂奈", "t": "何奈,无奈"}, {"w": "岂不尔思", "t": "怎能不思念你"}, {"w": "岂有他哉", "t": "表示没有其他原因。"}]}, {"meaning": "其。"}, {"meaning": "表示估计、推测。相当于也许、莫非。", "cites": [{"t": "将军岂有意乎。", "b": "《战国策·燕策》"}]}, {"meaning": "又。", "cites": [{"t": "荆卿岂无意哉。", "b": ""}, {"t": "将军岂愿见之乎。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又。", "cites": [{"t": "将军岂有意乎。", "b": ""}], "words": [{"w": "岂有", "t": "也许有。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('440wx','则','1','zé','刂','6','','[{"pinyin": "zé", "defs": [{"meaning": "(会意。金文从鼎,从刀。古代的法律条文曾刻铸在鼎上,以便让人遵守。本义:准则,法则)。"}, {"meaning": "同本义。", "cites": [{"t": "则,等画物也。", "b": "《说文》"}, {"t": "则,法也;则,常也。", "b": "《尔雅》"}, {"t": "根天地之气,寒暑之和,水土之性,人民鸟兽草木之生物,虽不甚多,皆均有焉,而未尝变也,谓之则。", "b": "《管子·七法》"}, {"t": "均守平则。", "b": "《周礼·大司马》"}, {"t": "法则以驭其官。", "b": "《周礼·太宰》"}, {"t": "掌则以逆都鄙之治。", "b": "《周礼·太史》。注:“亦法也。”"}, {"t": "有物有则。", "b": "《诗·大雅·庶民》"}, {"t": "天不变其常,地不易其则。", "b": "《管子·形势》"}], "words": [{"w": "则天", "t": "以天为法,治理天下"}, {"w": "则度", "t": "法度"}, {"w": "则效", "t": "则象。效法。"}]}, {"meaning": "等级(由则的划分等级引申而来)。", "cites": [{"t": "《坤》作坠势,高下九则。", "b": "《汉书·叙传下》。颜师古注引刘德曰:“九州土田上中下九等也。”"}]}, {"meaning": "古指三百平方里以下的采邑 。王莽时以土方五十里为一则,为子男封邑。"}, {"meaning": "标准权衡器。", "cites": [{"t": "王者制事、立法、物度、轨则,壹禀于六律。", "b": "《史记》"}]}, {"meaning": "划分等级。", "cites": [{"t": "咸则三壤,成赋中邦。", "b": "《书·禹贡》"}]}, {"meaning": "做,作。", "cites": [{"t": "众人听了,吓得不敢则声。", "b": "《红楼梦》"}]}, {"meaning": "正相反。", "cites": [{"t": "则无可用。", "b": "唐·柳宗元《三戒》"}, {"t": "则又望其真。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "人皆好名,我则不然;则不", "t": "不但,不止。"}]}, {"meaning": "表示相反或对照。", "cites": [{"t": "则耻师焉。", "b": "唐·韩愈《师说》"}], "words": [{"w": "今则不然", "t": ""}]}, {"meaning": "表示平列关系。", "cites": [{"t": "则桃李冬实。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "则桃李夏荣。", "b": ""}]}, {"meaning": "表示假设,相当于“若”、“如果”。", "cites": [{"t": "今则来,沛公恐不得有此。", "b": "《史记·高祖本纪》"}]}, {"meaning": "虽然,表示让步关系。", "cites": [{"t": "元帅此计好则好,则怕瞒不过诸葛孔明。", "b": "《隔江斗智》"}]}, {"meaning": "用于判断句表示肯定,相当于“就”。", "cites": [{"t": "非死,则徙尔。", "b": "柳宗元《捕蛇者说》"}, {"t": "则明月斜挂。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "则绿草如茵。", "b": ""}, {"t": "则人物必有概范。", "b": "蔡元培《图画》"}]}, {"meaning": "表示前后两事时间相距很近,有因果、条件关系,相当于“即”、“便”。", "cites": [{"t": "则难者亦易矣。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "则易者亦难矣。", "b": ""}, {"t": "则治之如所言。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "表示在发现某事时早已如此,或即将如此,相当于“就”、“将”。", "cites": [{"t": "文不能取胜,则歃血于华屋之下。(那就在殿堂下歃血订盟。歃血,是古代订盟的仪式,取牲血盛于盘中,以口微微吸吞,以示守信。华屋,漂亮的堂宇,指朝会或议事的地方。)", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "表示范围,相当于“仅”、“只”。", "cites": [{"t": "口耳之间则四寸耳,曷足以美七尺之躯哉?", "b": "《荀子》"}], "words": [{"w": " 则除", "t": "唯有, 只有"}, {"w": " 则索", "t": "只好; 须得"}, {"w": " 则情", "t": "只好管"}, {"w": " 则故", "t": "只管,只顾。"}]}, {"meaning": "对已然或发生的事强调。可译为“都”、“已经”、“原来”。", "cites": [{"t": "客则鼾睡。", "b": "明·魏禧《大铁椎传》"}, {"t": "则学校大备。", "b": "蔡元培《图画》"}]}, {"meaning": "表示让步,可译为“倒”、“倒是”。", "cites": [{"t": "则名微而众寡。", "b": "《三国志·诸葛亮传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('441wx','刚','1','gāng','刂','6','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从刀,冈声。本义:坚硬)。"}, {"meaning": "同本义。", "cites": [{"t": "刚,坚也。", "b": "《增韵》"}, {"t": "刚,彊断也。", "b": "《说文》"}, {"t": "挢然刚折。", "b": "《荀子·臣道》"}, {"t": "断之以刚。", "b": "《左传·昭公六年》"}, {"t": "柔则茹之,刚则吐之。", "b": "《诗经·烝民》"}], "words": [{"w": "刚巨", "t": "坚硬锐利的爪"}, {"w": "刚条", "t": "坚硬的树枝"}, {"w": "刚木", "t": "木质坚硬的树木"}, {"w": "刚土", "t": "硬土。"}]}, {"meaning": "坚强。", "cites": [{"t": "刚,强也。", "b": "《广韵》"}, {"t": "柔弱胜刚强。", "b": "《老子》"}, {"t": "刚而塞。", "b": "《书·皋谟》"}, {"t": "吾未见刚者。", "b": "《论语·公冶长》"}, {"t": "强者必刚斗其意。", "b": "《商君书·立本》"}, {"t": "鲍叔牙为人,刚愎而上悍。", "b": "《韩非子·十过》"}, {"t": "子曰:“刚毅木讷,近仁。”", "b": "《论语·子路》"}], "words": [{"w": "刚明", "t": "严明"}, {"w": "刚绠", "t": "刚强正直"}, {"w": "刚气儿", "t": "刚强的气质"}, {"w": "刚傲", "t": "刚强傲岸"}, {"w": "刚猛", "t": "刚强勇猛。"}]}, {"meaning": "刚正,刚直方正。", "cites": [{"t": "瑞生平为学,以刚为主,因自号刚峰,天下称刚峰先生。", "b": "《明史·海瑞传》"}, {"t": "祭彤武节刚方,动用安重。", "b": "《后汉书·祭彤传》论"}], "words": [{"w": "刚特", "t": "刚正而不随流俗"}, {"w": "刚峭", "t": "刚正严峻"}, {"w": "刚亮", "t": "刚正信实"}, {"w": "刚方", "t": "刚直方正。"}]}, {"meaning": "倔强固执。", "cites": [{"t": "性刚愎,好自用。", "b": "《金史·赤盏合喜传》"}], "words": [{"w": "刚戾", "t": "固执凶暴;不讲道理"}, {"w": "刚褊", "t": "固执而气量狭小"}, {"w": "刚求", "t": "强求"}, {"w": "刚隘", "t": "刚愎褊急"}, {"w": "刚狠", "t": "刚愎。"}]}, {"meaning": "刚直。", "cites": [{"t": "然而刚肠激发,不遑辞候,惊扰宫中,复忤宾客。", "b": "唐·李朝威《柳毅传》"}, {"t": "允性刚棱疾恶。", "b": "《后汉书·王允传》"}], "words": [{"w": "刚硬", "t": "刚直倔犟"}, {"w": "刚棱", "t": "刚直而有锋芒"}, {"w": "刚折", "t": "刚直不阿"}, {"w": "刚切", "t": "刚直恳切。"}]}, {"meaning": "表示动作、行为或情况发生在不久之前,相当于“刚才”。", "cites": [{"t": "刚被太阳收拾去,却叫明月送将来。", "b": "宋·苏轼《花影》"}], "words": [{"w": "战斗刚结束;刚然", "t": "刚,刚刚"}, {"w": "刚子", "t": "刚只。刚刚,刚才。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('442wx','网','1','wǎng','冂','6','','[{"pinyin": "wǎng", "defs": [{"meaning": "(象形。“网”捕鸟兽的叫“网”,捕鱼的叫罟。笼统地说,两字没有不同。本义:捕鱼鳖鸟兽的工具)。"}, {"meaning": "同本义。", "cites": [{"t": "网,庖牺所结绳以渔。", "b": "《说文》"}, {"t": "网,谓之罟。", "b": "《广雅》"}, {"t": "网疏则兽失。", "b": "《盐铁论·刑德》"}], "words": [{"w": "鱼网", "t": "捕鱼用的网"}, {"w": "网户", "t": "渔家"}, {"w": "网密", "t": "网目细密"}, {"w": "网丝", "t": "蜘蛛网"}, {"w": "网虫", "t": "指蜘蛛"}, {"w": "网罛", "t": "捕鱼之网"}, {"w": "网罭9", "t": "鱼网。"}]}, {"meaning": "泛指多孔而状如网的东西。", "cites": [{"t": "瑶瑟玉箫无意绪,任从珠网任从灰。", "b": "唐·张仲素《燕子楼》"}], "words": [{"w": "网户", "t": "刻有方格的窗户"}, {"w": "乒乓球网;雷达网;无线电通讯网;法网;电网;网儿", "t": "拢头发的网状头巾。"}]}, {"meaning": "喻指法律,法令。", "cites": [{"t": "网,法网。", "b": "《正字通》"}, {"t": "天之降网,维其优矣。", "b": "《诗·大雅·瞻仰》"}], "words": [{"w": "网密", "t": "比喻法令严密"}, {"w": "网禁", "t": "法令"}, {"w": "网辟", "t": "指律令"}, {"w": "网墨", "t": "法度刑律。"}]}, {"meaning": "用网捕鱼。", "cites": [{"t": "有村氓数十家,俱网罟为业。", "b": "《徐霞客游记·滇游日记》"}], "words": [{"w": "网了一条鱼;网利", "t": "给自己捞好处。"}]}, {"meaning": "搜罗;收容。", "cites": [{"t": "则不能以非功网上利。", "b": "《商君书·赏利》"}, {"t": "又起广乐园,多萃名倡巨贾以网大利,有司莫敢忤。", "b": "《续资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('443wx','肉','1','ròu','肉','6','','[{"pinyin": "ròu", "defs": [{"meaning": "(象形。甲骨文 字形,小篆,象动物肉形。“肉”是汉字的一个部首。本义:动物的肌肉)。"}, {"meaning": "指供食用的动物肉。", "cites": [{"t": "肉,胾肉。", "b": "《说文》。段注:“胾,大脔也,谓鸟兽之肉。…人曰肌,鸟兽曰肉。”"}, {"t": "公赐之食,食舍肉。", "b": "《左传·隐公元年》"}, {"t": "七十者可食肉矣。", "b": "《孟子·梁惠王上》"}, {"t": "不归肉。", "b": "《礼记·曾子问》"}, {"t": "辨体名肉物。", "b": "《周礼·内饷》"}], "words": [{"w": "吃肉;蟹肉;家禽的黑肉;肉醢", "t": "肉酱"}, {"w": "肉山脯林", "t": "积肉如山,列脯如林"}, {"w": "肉林", "t": "食用之肉极多,悬挂于林,形容穷奢极欲"}, {"w": "肉腥", "t": "鱼肉等类荤腥食物"}, {"w": "肉糜", "t": "肉粥"}, {"w": "肉羹", "t": "用肉作成的浓汤。"}]}, {"meaning": "指人体的皮肤、肌肉和脂肪层。", "cites": [{"t": "治古无肉刑。", "b": "《荀子·正论》"}, {"t": "其亲戚死,朽其肉而弃之,然后埋其骨。", "b": "《墨子·节葬》"}, {"t": "人主之子也,骨肉之亲也。", "b": "《战国策·赵策》"}, {"t": "朽肉烂肉。", "b": "《韩非子·忠孝》"}, {"t": "肉袒负荆。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "肉里钱", "t": "喻辛勤劳动得来的钱"}, {"w": "肉骨肉髓", "t": "刺骨钻肉"}, {"w": "肉分肠断", "t": "骨肉分离"}, {"w": "肉面对肉面", "t": "脸对脸"}, {"w": "肉山", "t": "戏称人躯体肥大"}, {"w": "肉肌", "t": "肌肉"}, {"w": "肉痛", "t": "剜肉般疼痛"}, {"w": "肉赘", "t": "即疣。一种皮肤病。"}]}, {"meaning": "蔬果除去皮核外的可食部分。", "cites": [{"t": "取笋肉五六寸者。", "b": "《齐民要术·种竹》"}], "words": [{"w": "肉果", "t": "又称多汁果,果实的一类。果实成熟时,果皮肥厚而多汁"}, {"w": "肉杏", "t": "杏之一种。"}]}, {"meaning": "指从口中发出的歌声,对乐器之声而言。", "cites": [{"t": "廉肉节奏。", "b": "《礼记·乐记》"}], "words": [{"w": "肉竹", "t": "泛指音乐。肉,声乐;竹,管乐"}, {"w": "肉声", "t": "没有乐器伴奏的清唱。"}]}, {"meaning": "中间有孔的环状物的体部。", "cites": [{"t": "肉倍好谓之璧。", "b": "《尔雅·释器》。注:“边也。”"}, {"t": "肉好皆有周郭。", "b": "《汉书·食货志》。注:“体为肉,孔为好。”"}], "words": [{"w": "肉好", "t": "中央有孔的圆形物体。孔称为好,孔周围的实体称为肉"}, {"w": "肉头厚", "t": "方言。谓广有钱财。"}]}, {"meaning": "外层;外表。", "cites": [{"t": "久旱时,田肉深,独得不旱。", "b": "宋·陆九渊《语录》"}]}, {"meaning": "吃肉。", "cites": [{"t": "始见中原气象,泰然不肉而肥矣。", "b": "苏轼《答苏伯固三首》"}]}, {"meaning": "使长出肉。", "cites": [{"t": "生死而肉骨。", "b": "马中锡《中山狼传》"}], "words": [{"w": "肉芽", "t": "指刚长出的新肉"}, {"w": "肉骨", "t": "使白骨再生肌肉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('444wx','年','1','nián','干','6','','[{"pinyin": "nián", "defs": [{"meaning": "(形声。甲骨文字形,上面是“禾”,下面是“人”,禾谷成熟,人在负禾。小篆字形,从禾,千声。本义:年成,五谷成熟)。"}, {"meaning": "同本义。", "cites": [{"t": "秊,谷熟也。", "b": "《说文》"}, {"t": "五谷皆熟为有年也。", "b": "《谷梁传·桓公三年》"}, {"t": "五谷大熟为大有年。", "b": "《谷梁传·宣公十六年》"}, {"t": "丰年多黍多秊。", "b": "《诗·周颂·丰年》"}, {"t": "有年。", "b": "《左传·桓公二年》。疏:“年训为稔。”"}, {"t": "尔厥有干,有年于芘洛。", "b": "《书·多士》"}]}, {"meaning": "又指一年的收成。", "cites": [{"t": "凶年免于死亡。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "又。", "cites": [{"t": "凶年不免于死亡。", "b": ""}], "words": [{"w": "年登", "t": "谷物丰收"}, {"w": "年荒", "t": "谷物歉收"}, {"w": "年丰", "t": "年成丰收"}, {"w": "年饥", "t": "年成荒歉"}, {"w": "年灾", "t": "自然灾害。"}]}, {"meaning": "时间单位。地球环绕太阳公转一次所需的约365又1/4太阳日的周期。", "cites": [{"t": "禹八年于外,三过其门而不入。", "b": "《孟子·滕文公上》"}, {"t": "期年之后,虽欲言,无可进者。", "b": "《战国策·齐策》"}]}, {"meaning": "年节。", "cites": [{"t": "新年正月,公子回家拜祖父、母亲的年回来。", "b": "《儒林外史》"}], "words": [{"w": "过年;新年;拜年;年酒", "t": "为祝贺新年邀请亲友吃的酒席"}, {"w": "年敬", "t": "年礼。年敬送的礼物"}, {"w": "年开", "t": "谓新年开始"}, {"w": "年对", "t": "春联"}, {"w": "年羹", "t": "过年时吃的羹汤"}, {"w": "年团", "t": "过年吃的团子。"}]}, {"meaning": "年纪,岁数。", "cites": [{"t": "年且九十。", "b": "《列子·汤问》"}, {"t": "时年七岁。", "b": "《世说新语·方正》"}, {"t": "周处年少。", "b": "《世说新语·自新》"}, {"t": "彼与彼年相若,道相似也。", "b": "唐·韩愈《师说》"}, {"t": "永生五年。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "年计", "t": "年纪;岁数"}, {"w": "年腊", "t": "年纪;岁数"}, {"w": "年齿相等", "t": "年龄相当"}, {"w": "年齿相悬", "t": "年龄相差悬殊"}, {"w": "年台", "t": "对同年的尊称"}, {"w": "年朽", "t": "年纪衰老"}, {"w": "年位", "t": "年龄和爵位"}, {"w": "年次", "t": "年龄的顺序"}, {"w": "年侵", "t": "年纪渐老"}, {"w": "年高望重", "t": "年纪大,名望高"}, {"w": "年期", "t": "年纪的期限"}, {"w": "年辈", "t": "年龄和行辈"}, {"w": "年德", "t": "年龄德行。"}]}, {"meaning": "寿命;一生的岁数。", "cites": [{"t": "人固不可以无年。", "b": "《世说新语·品藻》"}], "words": [{"w": "年寿", "t": "人的寿命"}, {"w": "年力", "t": "年龄与精力"}, {"w": "年迫日索", "t": "老年逼近,余日不多"}, {"w": "年祚", "t": "人的寿命;指立国的年教"}, {"w": "年衰岁暮", "t": "年纪衰老,寿命将尽"}, {"w": "年在桑榆", "t": "比喻垂暮之年"}, {"w": "年运", "t": "年寿和气运。"}]}, {"meaning": "用以指有关年节用的。", "cites": [{"t": "接袭人家去吃年茶。", "b": "《红楼梦》"}], "words": [{"w": "年帖", "t": "春帖"}, {"w": "年物", "t": "农历新年用以馈赠亲友之物"}, {"w": "年春", "t": "新春"}, {"w": "年茶", "t": "指年节聚会吃的果茶。"}]}, {"meaning": "假借为“佞”。奸巧谄庾,花言巧语的人。", "cites": [{"t": "使王近於民,远于年,啬於时,惠於财,亲贤使能。", "b": "《大戴礼·公符》"}]}, {"meaning": "科举时代同科考中者互称。", "cites": [{"t": "你我年谊世好,就如至亲骨肉一般。", "b": "《儒林外史》"}], "words": [{"w": "年家", "t": "称同科考中者的家庭"}, {"w": "年伯", "t": "对与父亲同榜登科而年长者的尊称"}, {"w": "年谊", "t": "同年登科的关系"}, {"w": "年侄", "t": "年兄之侄"}, {"w": "年叔", "t": "对与父辈同榜登科而年岁较小者的尊称。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('445wx','朱','1','zhū','木','6','','[{"pinyin": "zhū", "defs": [{"meaning": "(指事。小篆字形,从木,一在其中指出这种木是红心的。 本义:赤心木)。"}, {"meaning": "同本义。", "cites": [{"t": "朱,赤心木,松柏属。", "b": "《说文》"}]}, {"meaning": "指朱色的物品。", "cites": [{"t": "…朱(此指朱色缯帛)四百裹。", "b": "《穆天子传》"}]}, {"meaning": "", "cites": [{"t": "朱孝纯子颍。(朱孝纯,字子颍,山东历城人,乾隆进士,当时任泰安知府,善诗画。)", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "朱色,大红色 。古代称为正色。", "cites": [{"t": "网户朱缀。", "b": "《楚辞·招魂》"}, {"t": "紫衣而朱冠。", "b": "《庄子·达生》"}, {"t": "朱衣冠,执朱弓,挟朱矢。", "b": "《墨子·明鬼下》"}, {"t": "朱门酒肉臭,路有冻死骨。", "b": "杜甫《自京赴奉先县咏怀五百字》"}, {"t": "禹作为祭器,墨染其外,而朱画其内。", "b": "《韩非子·十过》"}, {"t": "朱鳞火鬣。", "b": "唐·李朝威《柳毅传》"}, {"t": "朱缨宝饰之帽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "朱印", "t": "朱色印记"}, {"w": "朱封", "t": "用朱笔在封口作标记"}, {"w": "朱押", "t": "用朱笔在封条等上面签字或画花押。"}]}, {"meaning": "“朱砂”的简称。", "cites": [{"t": "出赤盐如朱,白盐如玉。", "b": "《隋书》"}], "words": [{"w": "磁朱丸", "t": "磁石、朱砂、神曲配成的丸药,治疗心悸失眠、头晕目眩等。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('446wx','先','1','xiān','儿','6','','[{"pinyin": "xiān", "defs": [{"meaning": "(会意。据甲骨文,上面是“止”(脚),下面是“人”。意思是脚已走在人的前面。本义:前进,走在前面)。"}, {"meaning": "同本义。", "cites": [{"t": "先,前进也。", "b": "《说文》"}, {"t": "旌蔽日兮敌若云,矢交坠兮士争先。", "b": "屈原《九歌·国殇》"}, {"t": "恐为操所先。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "身先士卒;争先恐后;争先", "t": "争着赶到别人前头。"}]}, {"meaning": "尊崇;重视。", "cites": [{"t": "安宁则长庠序,先本绌末,以礼义防于利。", "b": "《史记·本准书》"}], "words": [{"w": "先本", "t": "重视根本。"}]}, {"meaning": "首创;开始。", "cites": [{"t": "不为福先,不为祸始。", "b": "《庄子·刻意》"}], "words": [{"w": "先志", "t": "先立志向"}, {"w": "先事", "t": "先行其事。"}]}, {"meaning": "当初;先前。", "cites": [{"t": "丢三忘四,惹人抱怨,竟不大象先了。", "b": "《红楼梦》"}], "words": [{"w": "先起头", "t": "从前"}, {"w": "先来", "t": "先前,原来"}, {"w": "先日", "t": "从前;日前。"}]}, {"meaning": "先世;祖先。", "cites": [{"t": "仆之先非有剖符丹书之功。", "b": "《报任安书》"}, {"t": "行莫丑于辱先。", "b": "司马迁《报任少卿书》"}, {"t": "思厥先祖父。", "b": "宋·苏洵《六国论》"}, {"t": "先典攸高。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "先西域人。", "b": "明、清·侯方域《壮悔堂文集》"}, {"t": "先茔在杭(先茔:祖先的坟墓。杭:浙江省杭州市)。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "先陇", "t": "祖坟"}, {"w": "先陵", "t": "帝王祖先的坟墓"}, {"w": "先铭", "t": "先人的墓志铭。"}]}, {"meaning": "前导;前驱。", "cites": [{"t": "以为民先(先,先锋。形容词活用为名词)。", "b": "《韩非子·五蠹》"}, {"t": "行为士先。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "先引", "t": "前导"}, {"w": "先师", "t": "前辈老师"}, {"w": "先达", "t": "有德行学问的前辈。"}]}, {"meaning": "前,时间或次序在前。", "cites": [{"t": "以先国家之急。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "后先相继。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "固先乎吾。", "b": "唐·韩愈《师说》"}, {"t": "先天下之忧。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "古时的;先前的,先代的。", "cites": [{"t": "[季春之月]天子乃荐鞠衣于先帝。", "b": "《礼记·月令》"}, {"t": "愿君顾先王之宗庙。", "b": "《战国策·齐策》"}], "words": [{"w": "先帝", "t": "远古帝王"}, {"w": "先王", "t": "指上古贤明君王。"}]}, {"meaning": "首要,根本。", "cites": [{"t": "末学者,古人有之,而非所以先也。", "b": "《庄子·天道》。成玄英疏:“先,本也。”"}], "words": [{"w": "先天", "t": "宇宙的本体,万物的本原"}, {"w": "先务", "t": "首要的事务。"}]}, {"meaning": "上。", "cites": [{"t": "短长终不校,先后竟谁论?", "b": "唐·韩愈《和侯协律咏笋》"}], "words": [{"w": "先后", "t": "高下,优劣。"}]}, {"meaning": "已故的。称呼死者的敬词。", "cites": [{"t": "先大母婢也。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "先朝顾命", "t": "先帝临终托付"}, {"w": "先府君", "t": "尊称亡父。"}]}, {"meaning": "指事情、行为发生在前。", "cites": [{"t": "树下先有落叶。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "几欲先走。", "b": "《秋声诗自序》"}, {"t": "水暖鸭先知。", "b": "宋·苏轼《惠崇》"}, {"t": "春江晚景", "b": ""}, {"t": "为坎以先登。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('447wx','丢','1','diū','一','6','','[{"pinyin": "diū", "defs": [{"meaning": "遗留。", "cites": [{"t": "我一生是个无用的人,一块土也不曾丢给你们。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('448wx','廷','1','tíng','廴','6','','[{"pinyin": "tíng", "defs": [{"meaning": "(形声。从廴,壬(tíng)声。廴(yǐn),建之旁。有引长之义。本义:朝廷)。"}, {"meaning": "同本义。", "cites": [{"t": "廷,朝中也。", "b": "《说文》"}, {"t": "虎兕争兮于廷中。", "b": "《楚辞·王逸·九思逢尤》"}, {"t": "游汉廷公卿间。", "b": "《汉书·陆逵传》"}, {"t": "相如廷叱之。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "廷见相如。", "b": ""}, {"t": "廷中皆大笑。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "廷臣", "t": "朝臣"}, {"w": "廷吏", "t": "朝廷的官吏"}, {"w": "廷推", "t": "明代用高级官吏,由大臣推荐,经皇帝批准后任用"}, {"w": "廷魁", "t": "科举时廷试头名。即状元。"}]}, {"meaning": "官署。地方官吏办事的地方。", "cites": [{"t": "[刘邦] 为泗水亭长,廷中吏无所不狎侮。", "b": "《史记》"}]}, {"meaning": "庭院;院子", "cites": [{"t": "子有廷内。", "b": "《诗·唐风·山有枢》"}, {"t": "张武军于荧廷。", "b": "《左传·襄公二十三年》"}, {"t": "夫差使人立于廷。", "b": "《左传·定公十四年》"}, {"t": "门廷有事,期年而君不闻,此所谓远于万里也。", "b": "《管子·法法》"}, {"t": "门廷车骑以千数。", "b": "《史记·李斯列传》"}, {"t": "听于廷。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "朝位;位置。", "cites": [{"t": "奇从奇,正从正,奇与正,恒不同廷。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "公正。", "cites": [{"t": "廷尉,秦官。", "b": "《汉书·百官公卿表上》。颜师古注:“廷,平也。治狱贵平,故以为号。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('449wx','舌','1','shé','舌','6','','[{"pinyin": "shé", "defs": [{"meaning": "(会意。从干,从口。本义:舌头)。"}, {"meaning": "同本义。", "cites": [{"t": "舌,在口所以言也,别味也。从干,从口,会意。言犯口而出,食犯口而入也。", "b": "《说文》"}, {"t": "兑为口舌。", "b": "《易·说卦》"}, {"t": "心在窍为舌。", "b": "《素问·阴阳应象大论》"}, {"t": "人有百口,口有百舌,不能名其一处也。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "舌举", "t": "舌翘起而不能动。指理屈词穷"}, {"w": "舌挢不下", "t": "翘起舌头。形容惊讶或害怕的样子"}, {"w": "舌刺刺", "t": "形容嘴舌不停地说话"}, {"w": "舌敞唇穿", "t": "舌烂辰破,舌烂唇干"}, {"w": "舌簧", "t": "巧舌"}, {"w": "舌干唇焦", "t": "说话过多,舌头干燥,嘴唇焦裂。形容费尽口舌、反复申说、劝道。也作舌敝唇焦。"}]}, {"meaning": "代指言语。", "cites": [{"t": "云而使舌。人体委与之。", "b": "《国语·周语》。注:“舌人能达异方之志,象胥之官也。”"}, {"t": "驷不及舌。", "b": "《论语·颜渊》"}], "words": [{"w": "舌辩", "t": "能言善辩;争辩"}, {"w": "舌摇簧鼓", "t": "满嘴胡说;大发议论"}, {"w": "舌敝耳聋", "t": "指言者舌敝,听者耳聋。意为议论纷繁"}, {"w": "舌辨", "t": "口才敏捷"}, {"w": "舌锋", "t": "谓言词犀利"}, {"w": "舌人", "t": "古代的翻译官"}, {"w": "舌端月旦", "t": "用言语评论人物"}, {"w": "舌剑唇枪", "t": "比喻言辞锋利。也作“唇枪舌剑”"}, {"w": "舌灿莲花", "t": "比喻能言善道。"}]}, {"meaning": "指装在铃铎内的锤。亦指管乐器的簧。", "cites": [{"t": "遒人以木铎徇于路。", "b": "《书·胤征》。孔传:“木铎,金铃木舌。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('450wx','竹','1','zhú','竹','6','','[{"pinyin": "zhú", "defs": [{"meaning": "(象形。小篆字形,象竹茎与下垂的叶片。“竹”是汉字的一个部首。从“竹”的字大部分是乐器、竹器和记载文字的东西。本义:竹子)。"}, {"meaning": "同本义 。多年生常绿植物。茎杆有节,中空,可供建筑用,又可作造纸原料,还可以制成乐器。", "cites": [{"t": "竹,冬生草也。象形。", "b": "《说文》"}, {"t": "伐竹取道,下见小潭。", "b": "柳宗元《小石潭记》"}, {"t": "官用竹,皆令录厚头,积之如山。", "b": "《世说新语·政事》"}], "words": [{"w": "竹笋汤", "t": "竹板子"}, {"w": "竹夫人", "t": "中空、有孔的竹编床上用品"}, {"w": "竹撞", "t": "竹编提盒"}, {"w": "竹箨", "t": "竹笋的皮;笋衣"}, {"w": "竹笥", "t": "竹箱"}, {"w": "竹蓖", "t": "竹棍。一端劈开的篾条,用于打人的一种刑具"}, {"w": "竹笆", "t": "竹篱"}, {"w": "竹皮", "t": "笋壳"}, {"w": "竹母", "t": "带有笋芽的竹鞭"}, {"w": "竹工", "t": "制造竹器的工匠"}, {"w": "竹匠", "t": "用竹子编制器具的手工业者"}, {"w": "竹席", "t": "竹篾编成的铺垫用具"}, {"w": "竹笪", "t": "粗竹席"}, {"w": "竹笠", "t": "竹丝或竹蔑编成的笠帽。"}]}, {"meaning": "竹简。", "cites": [{"t": "明(抱)枯竹,守空言,不知趋舍之宜,时世之变。", "b": "《盐铁论》"}], "words": [{"w": "竹刑", "t": "记载于竹简上的刑法条文"}, {"w": "竹素", "t": "古人用以记载文字的竹简与白绢"}, {"w": "竹书", "t": "古代无纸,在竹简上记事书写。"}]}, {"meaning": "古代八音之一,指箫笛一类竹制乐器。", "cites": [{"t": "金石丝竹,乐之器也。", "b": "《礼记·乐记》"}, {"t": "匏竹在上。", "b": "《礼记·郊特牲》"}, {"t": "丝木匏竹。", "b": "《周礼·春官·太师》。注:“竹,管箫也。”"}, {"t": "宴酣之乐,非丝竹。", "b": "欧阳修《醉翁亭记》"}], "words": [{"w": "竹人", "t": "吹奏竹制乐器的乐工"}, {"w": "竹肉丝", "t": "泛指器乐和声乐"}, {"w": "竹笛", "t": "竹制管乐器"}, {"w": "竹管", "t": "指箫笛一类的竹制管乐器。"}]}, {"meaning": "竹林。", "cites": [{"t": "公然抱茅入竹去。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('451wx','迁','1','qiān','辶','6','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从辵,“辵”表移动。形声字声旁有时有表意作用,此即一例。本义:向高处迁移)。"}, {"meaning": "同本义。", "cites": [{"t": "迁,登也。", "b": "《说文》"}, {"t": "迁,徙也。", "b": "《尔雅》"}, {"t": "迁,移也。", "b": "《广雅》"}, {"t": "既其女迁。", "b": "《诗·小雅·巷伯》"}, {"t": "出自幽谷,迁于乔马。", "b": "《诗·小雅·伐木》"}], "words": [{"w": "迁莺", "t": "指迁升飞翔的黄莺。喻登第。"}]}, {"meaning": "晋升或调动。", "cites": [{"t": "帝迁明德。", "b": "《诗·大雅·皇矣》"}, {"t": "迁至栘中。", "b": "《汉书·李广苏建传》"}, {"t": "迁为太史令。", "b": "《后汉书·张衡传》"}, {"t": "迁我如振落叶。", "b": "崔铣《记王忠肃公翱三事》"}, {"t": "迁淳安知县。", "b": "《明史》"}], "words": [{"w": "迁于乔木", "t": "比喻升官"}, {"w": "迁除", "t": "指官吏的升调委派"}, {"w": "迁乔", "t": "官吏由低职升到高职位"}, {"w": "迁封", "t": "加封爵位"}, {"w": "迁官", "t": "晋升官爵。"}]}, {"meaning": "徙居;搬动。", "cites": [{"t": "二曰询国迁。", "b": "《周礼·小司寇》。注:“谓徒都改邑也。”"}, {"t": "毁其宗庙,迁其重器。", "b": "《孟子·梁惠王下》"}, {"t": "盘庚之迁。", "b": "宋·王安石《答司马谏议书》"}, {"t": "战守迁皆不及施。", "b": "宋·文天祥《后序》"}], "words": [{"w": "迁次", "t": "移居,迁移"}, {"w": "迁幸", "t": "旧指天子迁居他处"}, {"w": "迁神", "t": "移灵,移柩"}, {"w": "迁海", "t": "从濒海之地向内地迁徙"}, {"w": "迁祔", "t": "迁徙墓地"}, {"w": "迁冗", "t": "迁徙逃散"}, {"w": "迁京", "t": "迁都"}, {"w": "迁座", "t": "迁移灵座"}, {"w": "迁土", "t": "迁离乡土"}, {"w": "迁宅", "t": "犹迁居"}, {"w": "迁邻", "t": "迁居择邻。"}]}, {"meaning": "变更,变动。", "cites": [{"t": "有百世不迁之宗。", "b": "《礼记大传》。注:“犹变易也。”"}, {"t": "饬令,则法不迁。", "b": "《韩非子·饬令》"}, {"t": "其迁极渐。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "事过境迁;迁正", "t": "变异历制"}, {"w": "迁易", "t": "改变"}, {"w": "迁染", "t": "人的性情被习俗沾染而有所改变"}, {"w": "迁兰变鲍", "t": "在无形中渐渐受影响而同化"}, {"w": "迁日", "t": "更改日期。"}]}, {"meaning": "流放;放逐。", "cites": [{"t": "怒而迁之。", "b": "《史记·屈原贾生列传》"}, {"t": "及夫大逆不道,然后掩捕而迁之。", "b": "唐·柳宗元《封建论》"}], "words": [{"w": "迁放", "t": "流放"}, {"w": "迁逐", "t": "贬斥放逐"}, {"w": "迁窜", "t": "迁逐流放。"}]}, {"meaning": "贬谪,降职。", "cites": [{"t": "迁客骚人,多会于此。", "b": "《岳阳楼记》"}], "words": [{"w": "迁斥", "t": "贬斥,放逐"}, {"w": "迁臣", "t": "指贬斥远地的官吏"}, {"w": "迁削", "t": "谪降削职"}, {"w": "迁凑", "t": "迁就凑合"}, {"w": "迁寺", "t": "谪降削职。"}]}, {"meaning": "离散。", "cites": [{"t": "成而不迁。", "b": "《国语·晋语》。注:“离散也。”"}], "words": [{"w": "迁逃", "t": "逃走;逃离"}, {"w": "迁逝", "t": "消逝,流失"}, {"w": "迁摇", "t": "离散动摇。"}]}, {"meaning": "古州名 。北周置。即今湖北省房县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('452wx','乔','1','qiáo','丿','6','','[{"pinyin": "qiáo", "defs": [{"meaning": "(会意。从夭,从高省,高亦声。夭,象人(大)行走的样子。本义:高)。"}, {"meaning": "高耸。多用以形容树木。", "cites": [{"t": "乔,高而曲也。", "b": "《说文》"}, {"t": "厥木惟乔。", "b": "《书·禹贡》"}, {"t": "山有乔松。", "b": "《诗·郑风·山有扶苏》"}, {"t": "南有乔木。", "b": "《诗·郑风·汉广》"}], "words": [{"w": "乔木世家", "t": "指贵族世家。乔木代指贵族、高官"}, {"w": "乔松", "t": "高大的松树"}, {"w": "乔柯", "t": "高枝"}, {"w": "乔峰", "t": "高峰"}, {"w": "乔乔", "t": "高大的样子"}, {"w": "乔竦", "t": "高耸"}, {"w": "乔干", "t": "高高的树干"}, {"w": "乔树", "t": "高大的树。"}]}, {"meaning": "詈词。宋元以后,曲中用乔者甚多,常随文为释,含有坏、窝囊、糊涂、狡猾、怯懦无用等贬义。形容某种恶劣的表现。", "cites": [{"t": "乔才心邪,不来一月。", "b": "《金瓶梅》"}], "words": [{"w": "乔人", "t": "无赖,坏蛋"}, {"w": "乔人物", "t": "无赖;怪人"}, {"w": "乔材", "t": "亦作“乔才”。无赖,恶棍"}, {"w": "乔男女", "t": "恶徒"}, {"w": "乔相识", "t": "不诚实的怪伙伴。"}]}, {"meaning": "骄傲。", "cites": [{"t": "小人贫斯约,富斯乔。", "b": "《礼记·坊记》"}]}, {"meaning": "做作;装假。", "cites": [{"t": "戏子乔装打扮混了进来。", "b": "《儿女英雄传》"}], "words": [{"w": "乔模乔样", "t": "装模做样"}, {"w": "乔张乔致", "t": "乔张致"}, {"w": "乔做作", "t": "装腔作势"}, {"w": "乔神道", "t": "装神弄鬼"}, {"w": "乔乔", "t": "乔模乔样"}, {"w": "乔断案", "t": "指装腔作势耍威风"}, {"w": "乔乔画画", "t": "装扮"}, {"w": "乔公道", "t": "装好意;假作公平。"}]}, {"meaning": "尖峭的高山。", "cites": [{"t": "二矛重乔,河上乎逍遥。", "b": "《诗·郑风·清人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('453wx','迄','1','qì','辶','6','','[{"pinyin": "qì", "defs": [{"meaning": "(形声。从辵(chuò),乞声。本义:到;至) 同本义。", "cites": [{"t": "迄,至也。", "b": "《说文新附》"}, {"t": "以迄于今。", "b": "《诗·大雅·生民》"}, {"t": "迄于天下。", "b": "《国语·周语下》"}, {"t": "吴获迄古。", "b": "《楚辞·天问》"}, {"t": "声教迄于四海。", "b": "《汉书·艺文志》"}, {"t": "降周迄孔。", "b": "《汉书·扬雄传》"}, {"t": "夫普法之战,迄今虽为陈迹,而其事信而有征。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "迄今盛行。", "b": "蔡元培《图画》"}, {"t": "自皇古迄今。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "迄至", "t": "至,到。"}]}, {"meaning": "竟,毕竟,终究。", "cites": [{"t": "迄无成功。", "b": "《后汉书·孔融传》"}, {"t": "迄无济。", "b": "《聊斋志异·促织》"}, {"t": "迄未成功;迄无音信;迄功(犹竣工)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('454wx','伟','1','wěi','亻','6','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从人,韦声。本义:高大;壮美)。"}, {"meaning": "同本义。", "cites": [{"t": "伟,大也。", "b": "《华严经音义》引珠丛"}, {"t": "猗欤伟欤!", "b": "《文选·汉武帝·贤良诏》"}, {"t": "身长八尺,容貌甚伟。", "b": "《三国志·诸葛亮传》"}, {"t": "风骨伟岸。", "b": "《宋史·韩世宗传》"}, {"t": "庞然修伟。", "b": "《聊斋志异·促织》"}, {"t": "应元伟躯干。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "伟干长躯", "t": "身材高大、魁梧"}, {"w": "伟木", "t": "高大的树"}, {"w": "伟干", "t": "魁梧的身躯"}, {"w": "伟美,伟秀", "t": "魁梧英俊"}, {"w": "伟悍", "t": "魁梧勇猛"}, {"w": "伟貌", "t": "体貌魁梧"}, {"w": "伟壮", "t": "魁梧壮大"}, {"w": "伟状", "t": "状貌魁伟"}, {"w": "伟丈夫", "t": "有抱负有作为的男子汉;身体魁梧的男子。"}]}, {"meaning": "奇异。", "cites": [{"t": "伟,奇也。", "b": "《说文》"}, {"t": "有务奉下直曲、怪言、伟服、瑰称以眩民耳目者。", "b": "《韩非子·说疑》"}], "words": [{"w": "伟服", "t": "奇异的服装"}, {"w": "伟行", "t": "不平常的行为。"}]}, {"meaning": "伟大。", "cites": [{"t": "伟哉夫造物者。", "b": "《庄子·大宗师》。向注:“美也。”"}], "words": [{"w": "伟而", "t": "伟大健美"}, {"w": "伟器", "t": "大器。比喻杰出的人才"}, {"w": "伟懋", "t": "伟大茂盛"}, {"w": "伟烈", "t": "伟大的功业"}, {"w": "伟迹", "t": "伟大的业绩或事迹。"}]}, {"meaning": "宏大;盛大。", "cites": [{"t": "不为伟乎。", "b": "《史记·荆燕世家》。索隐:“盛也。”"}], "words": [{"w": "伟度", "t": "宏大的度量"}, {"w": "伟量", "t": "宏大的器量"}, {"w": "伟略", "t": "宏伟的谋略"}, {"w": "伟望", "t": "很大的名望"}, {"w": "伟博", "t": "巨大"}, {"w": "伟峻", "t": "雄伟挺拔"}, {"w": "伟懋", "t": "盛大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('455wx','传','1','chuán zhuàn','亻','6','','[{"pinyin": "chuán", "defs": [{"meaning": "传递;传送。", "cites": [{"t": "速于置郵而传命。", "b": "《孟子·公孙丑上》"}, {"t": "传以示美人及左右。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "传家", "t": "传于后代子弟"}, {"w": "传衣", "t": "继承衣钵"}, {"w": "传首", "t": "传送首级"}, {"w": "传运", "t": "传递运输"}, {"w": "传演", "t": "传递演变。"}]}, {"meaning": "传授。", "cites": [{"t": "师者,所以传道授业解惑也。", "b": "韩愈《师说》"}], "words": [{"w": "传度", "t": "传授"}, {"w": "传派", "t": "传授的流派"}, {"w": "传旨", "t": "传授意旨"}, {"w": "传书", "t": "传授书籍。"}]}, {"meaning": "让位;传代。", "cites": [{"t": "不传于贤而传于子。", "b": "《孟子》"}], "words": [{"w": "传位", "t": "传授帝王权位"}, {"w": "传政", "t": "传授政权。"}]}, {"meaning": "留传。", "cites": [{"t": "功如丘山,名传后时。", "b": "《盐铁论·非鞅》"}, {"t": "此世所以不传也。", "b": "苏轼《石钟山记》"}, {"t": "居第当传子孙。", "b": "司马光《训俭示康》"}], "words": [{"w": "传世", "t": "后传到后世"}, {"w": "传灯", "t": "传留佛法"}, {"w": "传祚", "t": "流传后世"}, {"w": "家传秘方", "t": ""}]}, {"meaning": "充分或确切地表明;表达。", "cites": [{"t": "传神写照。", "b": "《世说新语·巧艺》"}], "words": [{"w": "传真", "t": "画肖像。"}]}, {"meaning": "召,叫来。发出命令叫人来。", "cites": [{"t": "老太太那里传晚饭了。", "b": "《红楼梦》"}], "words": [{"w": "传嘴", "t": "传话"}, {"w": "传会", "t": "传呼"}, {"w": "传答", "t": "传达"}, {"w": "传证人", "t": ""}]}]}, {"pinyin": "zhuàn", "defs": [{"meaning": "驿站所备的车。", "cites": [{"t": "晋侯以传召伯宗。", "b": "《左传·成公五年》"}, {"t": "周公旦从鲁闻之,发急传而问之。(急传:特快的驿车)", "b": "《韩非子·外储说右上》"}, {"t": "非传非遽(驿马),载奇皮革,罪死不赦。", "b": "《韩非子·爱臣》"}]}, {"meaning": "驿站;驿舍。", "cites": [{"t": "昔者赵氏袭卫,车舍人不休传。", "b": "《战国策·齐策五》"}, {"t": "发人修道,缮理亭传。", "b": "《后汉书·陈忠传》"}], "words": [{"w": "传车", "t": "古代驿站的专用车辆"}, {"w": "传吏", "t": "驿舍的官吏"}, {"w": "传马", "t": "驿站所用的马"}, {"w": "传乘", "t": "驿站的车马"}, {"w": "传宰", "t": "管理驿站的小官。"}]}, {"meaning": "符信。", "cites": [{"t": "凡所达货贿者,则以节传出之。", "b": "《周礼》"}, {"t": "诈刻传出关归家。", "b": "《汉书·宁成传》"}]}, {"meaning": "传记。", "cites": [{"t": "吾已作传。", "b": "清·袁枚《祭妹文》"}, {"t": "善传游侠。", "b": "孙文《序》"}]}, {"meaning": "又。", "cites": [{"t": "为五百人立传。", "b": ""}], "words": [{"w": "自传;外传;别传;传状", "t": "传记行状"}, {"w": "传叙", "t": "人物传记"}, {"w": "传诔", "t": "传记和诔文。"}]}, {"meaning": "注释或阐述经义的文字。", "cites": [{"t": "六艺经传。", "b": "唐·韩愈《师说》"}], "words": [{"w": "传注", "t": "解释经籍的文字"}, {"w": "传诂", "t": "解释经籍的文字"}, {"w": "传疏", "t": "诠释经义的文字"}, {"w": "传笺", "t": "谓《诗经》的注解。"}]}, {"meaning": "作传;记载。", "cites": [{"t": "汉史既传其事,而后世工画者又图其迹。", "b": "唐·韩愈《送杨少尹序》"}], "words": [{"w": "前半部传的是傅仪", "t": ""}]}]}]','jingmo-wenyan');
