('457wx','乓','1','pāng','丿','6','','[{"pinyin": "pāng", "defs": [{"meaning": "象声词，形容枪声、关门声、东西砸破声等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('458wx','休','1','xiū','亻','6','','[{"pinyin": "xiū", "defs": [{"meaning": "(会意。从人,从木。人依傍大树休息。本义:休息)。"}, {"meaning": "同本义。", "cites": [{"t": "休,息止也。", "b": "《说文》"}, {"t": "休,息也。", "b": "《尔雅》"}, {"t": "南有乔木,不可休思。", "b": "《诗·周南·汉广》"}, {"t": "休,象人息木阴。", "b": "《五经文字》"}, {"t": "诚上休陛下余光。", "b": "《汉书·王莽传》。注:“庇荫也。”"}, {"t": "汔可小休。", "b": "《诗·大雅·民劳》"}, {"t": "毋休于都。", "b": "《礼记·月令》"}, {"t": "止宫休舍。", "b": "《史记·高帝纪》"}, {"t": "未休关西卒。", "b": "唐·杜甫《兵车行》"}, {"t": "景公猎,休,坐地而食。", "b": "《晏子春秋·内篇谏下》"}, {"t": "故且养兵休卒,蓄锐待敌。", "b": "岳飞《五岳祠盟记》"}, {"t": "休于树", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "命士少休。", "b": "《资治通鉴·唐纪》"}, {"t": "将士更休。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "劝以少休。", "b": ""}, {"t": "既暮,休于旅舍。", "b": "《聊斋志异》"}], "words": [{"w": "休日", "t": "休息的日子,假日"}, {"w": "休舍", "t": "休息"}, {"w": "休士", "t": "使士卒休息"}, {"w": "休坐", "t": "坐下休息。"}]}, {"meaning": "停止、中止或结束。", "cites": [{"t": "妇无公事,休其蚕织。", "b": "《诗·大雅·瞻卬》"}, {"t": "先生休矣。", "b": "《战国策·齐策四》"}, {"t": "日夜无休时。", "b": "《史记·货殖列传》"}, {"t": "吾生之行修。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "我有一条苦计,若救他不得,我和你都休。", "b": "《水浒传》"}, {"t": "若争数合无高下,太子心中不肯休。", "b": "《西游记》"}], "words": [{"w": "休粮", "t": "停止饮食"}, {"w": "休罢", "t": "罢休;停止"}, {"w": "休驾", "t": "使马车停歇"}, {"w": "休务", "t": "停止公务"}, {"w": "休已", "t": "停止"}, {"w": "休囚", "t": "死"}, {"w": "休偢", "t": "不理睬"}, {"w": "休息", "t": "平息;止息。"}]}, {"meaning": "辞去。", "cites": [{"t": "屡疏乞休。", "b": "清·张廷玉《明史》"}], "words": [{"w": "退休", "t": "职工因年老或因公残废而离开工作岗位"}, {"w": "休退", "t": "官吏辞职赋闲"}, {"w": "休居", "t": "辞官家居"}, {"w": "休官", "t": "辞官"}, {"w": "休归", "t": "退休。"}]}, {"meaning": "离弃,解除自己的婚姻。", "cites": [{"t": "你休了媳妇儿,兄弟,你如今可往那里去?", "b": "《元曲选·佚名·渔樵记剧》"}], "words": [{"w": "休离", "t": "休弃;离弃"}, {"w": "休妻;休书;休亲", "t": "离弃妻子。"}]}, {"meaning": "休假。", "cites": [{"t": "臣属吏张宛长休百日。", "b": "《后汉书》"}], "words": [{"w": "休沐", "t": "例假"}, {"w": "休下", "t": "官吏休假"}, {"w": "公休", "t": "星期日、纪念日等集体的休假"}, {"w": "轮休;休告", "t": "官员呈请休假"}, {"w": "休暇", "t": "休假。"}]}, {"meaning": "美好,美善。", "cites": [{"t": "顺天休命。", "b": "《易·大有》。郑注:“美也。”"}, {"t": "亦孔之休。", "b": "《诗·豳风·斧》"}, {"t": "休徵。", "b": "《书·洪范》"}, {"t": "休徵叙美行之验。", "b": "《后汉书·班固传》注"}, {"t": "累仕所至,必获休声。", "b": "柳宗元《与邕州李域中函论陆卓启》"}], "words": [{"w": "休声", "t": "美好的名声"}, {"w": "休咎", "t": "善恶"}, {"w": "休明", "t": "美好清明"}, {"w": "休名", "t": "美名"}, {"w": "休明", "t": "美善而光明"}, {"w": "休光", "t": "盛美光耀。"}]}, {"meaning": "吉庆。", "cites": [{"t": "无不受休。", "b": "《国语·楚语》。注:“庆也。”"}, {"t": "休祲降于天。", "b": "《战国策·魏策》"}, {"t": "休矣!美矣!惠泽远扬。", "b": "《三国演义》"}], "words": [{"w": "休咎", "t": "吉凶"}, {"w": "休应", "t": "吉兆"}, {"w": "休证", "t": "吉祥的证验"}, {"w": "休符", "t": "吉祥的征兆"}, {"w": "休福", "t": "吉庆。"}]}, {"meaning": "喜悦的,欢乐的。", "cites": [{"t": "为晋休戚。", "b": "《国语·周语》。注:“喜也。”"}, {"t": "既见君子,我心则休。", "b": "《诗·小雅·菁菁者莪》"}], "words": [{"w": "休戚", "t": "欣悦与忧患。"}]}, {"meaning": "悠闲;安闲。", "cites": [{"t": "休有烈光。", "b": "《诗·周颂·载见》"}], "words": [{"w": "休烈", "t": "盛大的事业。"}]}, {"meaning": "勿;不要;别。", "cites": [{"t": "玄德急止之曰:“休惊百姓!”", "b": "《三国演义》"}], "words": [{"w": "休得", "t": "不得,不要。"}]}, {"meaning": "语气助词。罢;了。", "cites": [{"t": "武松笑道:“却才去肚里发一发,我们去休。”", "b": "《水浒传》"}, {"t": "我儿可收拾早睡休,明日须半夜起来打点。", "b": "《清平山堂话本》"}]}, {"meaning": "树荫。", "cites": [{"t": "依松柏之余休。", "b": "《汉书·外戚传》"}]}, {"meaning": "福禄。", "cites": [{"t": "以礼承天之休。", "b": "《左传·襄公二十八年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('459wx','伍','1','wǔ','亻','6','','[{"pinyin": "wǔ", "defs": [{"meaning": "(会意。从人,从五。五人为伍。本义:五人构成一个集体)。"}, {"meaning": "同本义。", "cites": [{"t": "伍,行伍。", "b": "《广韵》"}, {"t": "五人为伍。", "b": "《管子·小筐》"}, {"t": "会其什伍而教之道义。", "b": "《周礼·天官·宫正》"}, {"t": "先偏后伍。", "b": "《左传·桓公五年》"}, {"t": "林不狃之伍。", "b": "《左传·哀公十一年》"}]}, {"meaning": "古代军队编制单位。士兵五名编为一伍。", "cites": [{"t": "全伍为上。", "b": "《墨子·公输》"}, {"t": "破伍次之。", "b": ""}], "words": [{"w": "伍伯", "t": "即伍长。古军队中五人为伍,一伍之长称伍长"}, {"w": "伍什", "t": "指部队"}, {"w": "伍老", "t": "伍长"}, {"w": "伍壮", "t": "指乡武装丁壮"}, {"w": "伍部", "t": "伍长"}, {"w": "伍乘", "t": "同乘共伍的士卒。"}]}, {"meaning": "。用于支票、会计防止出错或涂改。", "cites": [{"t": "参伍以变。", "b": "《易·系辞上》"}]}, {"meaning": "成对的组合。", "cites": [{"t": "八八为伍。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('460wx','伏','1','fú','亻','6','','[{"pinyin": "fú", "defs": [{"meaning": "(会意。从人,从犬。意思是:人如狗那样地匍伏着。本义:俯伏;趴下)。"}, {"meaning": "同本义。", "cites": [{"t": "伏,司也。", "b": "《说文》"}, {"t": "伏瘞亦如之。", "b": "《周礼·犬人》。司农注:“课伏犬以王车轹之。”"}, {"t": "伏,覆也。", "b": "《释名·释姿容》"}, {"t": "寝毋伏。", "b": "《礼记·曲礼上》"}, {"t": "雌鸡伏子。", "b": "《汉书·五行志中之上》"}, {"t": "楚子伏己而盐其脑。", "b": "《左传·僖公二十八年》"}, {"t": "一府中皆漝伏,莫敢起。", "b": "《史记·项羽本纪》"}, {"t": "庑下一生伏案卧。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "及敌枪再击,寨中人又鹜伏矣。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "伏尸", "t": "倒在地上的尸体,多指杀死"}, {"w": "伏肉", "t": "死尸的肉"}, {"w": "伏地", "t": "俯伏在地上"}, {"w": "伏虎;伏奏", "t": "俯伏上奏"}, {"w": "伏候", "t": "俯伏等候。"}]}, {"meaning": "身体前倾靠在物体上。", "words": [{"w": "伏轼", "t": "乘车。也作“扶轼”。轼:车厢前面的横木扶手"}, {"w": "伏惟", "t": "俯伏思惟,常用于书信中的敬词。"}]}, {"meaning": "潜藏;埋伏。", "cites": [{"t": "伏,藏也。", "b": "《广雅》"}, {"t": "福兮祸所伏。", "b": "《老子》"}, {"t": "物莫伏于蠱。", "b": "《国语·晋语》"}, {"t": "夫大国,难测也,惧有伏焉。", "b": "《左传·庄公十年》"}, {"t": "入武关,秦伏兵绝其后。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "伏莽", "t": "藏匿在丛林中的盗匪"}, {"w": "伏道", "t": "暗藏的地道"}, {"w": "伏龙", "t": "潜伏的龙;灶神"}, {"w": "伏戎", "t": "埋伏军队或刺客"}, {"w": "伏甲", "t": "埋伏武士或军队"}, {"w": "伏弩", "t": "埋伏弓箭手。"}]}, {"meaning": "屈服,顺从。承认罪行或失败。", "cites": [{"t": "许既伏其罪矣。", "b": "《左传·隐公十一年》"}, {"t": "骑皆伏曰:“如大王言!”", "b": "《史记·项羽本纪》"}, {"t": "这个苏小卿怎肯伏低。", "b": "明·贾仲名《对玉梳》"}], "words": [{"w": "伏老", "t": "自认年龄老,精力衰退"}, {"w": "伏死", "t": "甘愿舍弃生命"}, {"w": "伏低", "t": "承认自己的地位低下而向别人屈服"}, {"w": "伏礼", "t": "伏不是。认错"}, {"w": "伏从", "t": "服从"}, {"w": "伏辜", "t": "服罪。"}]}, {"meaning": "佩服,信服。", "cites": [{"t": "其所临莅,莫不肌栗慴伏。", "b": "《文选·王褒·四子讲德论》"}, {"t": "族弟刘璋,再拜致书于玄德宗兄将军麾下,久伏电天。", "b": "《三国演义》"}], "words": [{"w": "伏伏腊腊", "t": "极其顺服的样子。"}]}, {"meaning": "从事。", "cites": [{"t": "谁谓伏事浅,契阔逾三年。", "b": "陆机《为吴王郎中时从梁陈作一首》"}], "words": [{"w": "伏术", "t": "从事学术工作。"}]}, {"meaning": "保持。", "cites": [{"t": "伏清白以死直兮,固前圣之所厚。", "b": "《楚辞·离骚》"}]}, {"meaning": "伏天;伏日。指夏至后第三个庚日起至立秋后第二个庚日前一天止的一段时间,分为初伏、中伏、末伏,统称三伏,相当于阳历七月中旬至八月下旬。", "cites": [{"t": "大人,如今是三伏天天道…天降三尺瑞雪遮掩了窦娥尸首。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "入伏", "t": "进入伏天"}, {"w": "头伏", "t": "初伏"}, {"w": "数伏", "t": "进入伏天"}, {"w": "歇伏", "t": "在伏天停工休息。"}]}, {"meaning": "电势差和电压单位“伏特”的简称。"}, {"meaning": "居处。", "cites": [{"t": "寡君越在草莽,未获所伏。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('461wx','优','1','yōu','亻','6','','[{"pinyin": "yōu", "defs": [{"meaning": "(形声。从人,尤声。本义:古代表演乐舞、杂戏的艺人。宋元以后,亦泛称戏曲艺人、演员)。"}, {"meaning": "同本义。", "cites": [{"t": "优,饶也。一曰倡也。", "b": "《说文》。按,倡者本训,饶者假借。"}, {"t": "陈氏鲍氏之圉人为优。", "b": "《左传·襄公二十八年》"}, {"t": "公之优曰施。", "b": "《国语·晋语》"}, {"t": "信谗喜优。", "b": "《国语·越语》"}, {"t": "优笑在前。", "b": "《国语·齐语》。注:“倡俳也。”"}, {"t": "优孟。", "b": "《史记·滑稽列传》"}, {"t": "所爱倡优巧匠之属。", "b": "《汉书·灌夫传》。注:“谐戏者也。”"}, {"t": "优施曰:“…我优也,言无邮。”", "b": "《国语》"}], "words": [{"w": "优人杂剧", "t": "乐舞戏曲"}, {"w": "优孤", "t": "专演老年男子的优人"}, {"w": "优唱", "t": "艺人的说唱"}, {"w": "优语", "t": "优在演戏中戏谑嘲讽的话"}, {"w": "优歌", "t": "优人唱的歌曲。"}]}, {"meaning": "充足,富裕。", "cites": [{"t": "优,饶也。", "b": "《说文》"}, {"t": "优,多也。", "b": "《小尔雅》"}, {"t": "优,渥也。", "b": "《广雅》"}, {"t": "维其优矣。", "b": "《诗·大雅·瞻夘》"}, {"t": "汙池渊沼川泽,谨其时禁,故鱼鳖优多而百姓有余用也。", "b": "《荀子》"}], "words": [{"w": "优稳", "t": "优裕安逸"}, {"w": "优饶", "t": "富裕,充裕"}, {"w": "优佚", "t": "富裕,安逸"}, {"w": "优实", "t": "富裕"}, {"w": "优足", "t": "富足"}, {"w": "优渥", "t": "丰足;优厚"}, {"w": "优产", "t": "丰富的财产。"}]}, {"meaning": "雨水充沛。", "cites": [{"t": "既优既渥,既沾既足,生我百谷。", "b": "《诗·小雅·信南山》"}]}, {"meaning": "优良;美好;优越。跟“劣”相对。", "cites": [{"t": "优劣得所。", "b": "诸葛亮《出师表》"}], "words": [{"w": "优差美缺", "t": "美差肥缺;好的职位"}, {"w": "优行生", "t": "品学兼优的生员"}, {"w": "优劣", "t": "优和劣。指强弱、大小、好坏、工拙等"}, {"w": "优绌", "t": "优劣"}, {"w": "优壮", "t": "优美遒劲。"}]}, {"meaning": "宽厚;宽容。", "cites": [{"t": "上以宣名儒,优容之。", "b": "《汉书·鲍宣传》"}], "words": [{"w": "优宽", "t": "宽厚,宽和"}, {"w": "优薄", "t": "宽厚和浇薄"}, {"w": "优慎", "t": "宽容谨慎"}, {"w": "优纵", "t": "宽容放任。"}]}, {"meaning": "安闲,悠闲,安逸。", "cites": [{"t": "伴奂尔游矣,优游尔休矣。", "b": "《诗·大雅·卷阿》"}], "words": [{"w": "优游", "t": "闲暇自得的样子"}, {"w": "优逸", "t": "安闲"}, {"w": "优容", "t": "安闲自得貌"}, {"w": "优悠", "t": "悠闲舒适"}, {"w": "优犹", "t": "优游。优裕;宽裕"}, {"w": "优游自若", "t": "从容不迫,不变常态"}, {"w": "优游自得", "t": "悠闲如意"}, {"w": "优游自适", "t": "悠闲适意"}, {"w": "优豫", "t": "从容安祥"}, {"w": "优游卒岁", "t": "悠闲度日"}, {"w": "优游岁月", "t": "悠闲舒适地过日子。"}]}, {"meaning": "优厚。", "cites": [{"t": "益之以霢霂,既优既渥。", "b": "《诗·小雅·信南山》"}, {"t": "布施优裕。", "b": "《国语·周语》"}, {"t": "优诏奖瑞。", "b": "清·张廷玉《明史》"}], "words": [{"w": "优恤重典", "t": "朝廷对官员表示优厚抚恤的隆重典礼"}, {"w": "优保", "t": "优厚的保举提拔"}, {"w": "优赐", "t": "优厚的赏赐"}, {"w": "优缛", "t": "优厚,丰厚"}, {"w": "优恤", "t": "优厚。"}]}, {"meaning": "柔弱,少决断。", "cites": [{"t": "人君唯优与不敏为不可。", "b": "《管子·小匡》"}]}, {"meaning": "优待,给予好的待遇,厚待。", "cites": [{"t": "今区寓宁晏,庶绩咸熙,念勤简能,宜加优奖。", "b": "《南齐书·武帝纪》"}], "words": [{"w": "优渥", "t": "深厚"}, {"w": "优叙", "t": "按大功给予奖励"}, {"w": "优恤", "t": "从优抚恤"}, {"w": "优擢", "t": "从优提拔"}, {"w": "优与", "t": "从优给予。"}]}, {"meaning": "协调;调和。", "cites": [{"t": "其德优天地而和阴阳。", "b": "《淮南子·原道》"}]}, {"meaning": "开玩笑;戏谑。", "cites": [{"t": "宋华弱与乐辔少相狎,长相优,又相谤也。(长:长大;成年。)", "b": "《左传·襄公六年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('462wx','臼','1','jiù','臼','6','','[{"pinyin": "jiù", "defs": [{"meaning": "(象形。小篆字形,象舂米器具形,中间的四点表示有米。本义:中部下凹的舂米器具)。"}, {"meaning": "同本义。", "cites": [{"t": "臼,舂也。古者掘地为臼,其后穿木石。", "b": "《说文》"}, {"t": "断木为杵,掘地为臼。", "b": "《易·系辞下》"}, {"t": "择满臼,舂之而不碎。", "b": "贾思勰《齐民要术》"}], "words": [{"w": "臼杵", "t": "臼与杵"}, {"w": "臼塘", "t": "凿成船形的木臼,别称臼塘"}, {"w": "臼中无釜", "t": "比喻妻子亡故。"}]}, {"meaning": "用臼舂米。", "cites": [{"t": "织纺井臼。(臼,用如动词:舂米。)", "b": "清·周容《芋老人传》"}]}, {"meaning": "形如臼的 。如臼齿;臼头深目(形容相貌极丑);臼科(臼形的坑)。"}, {"meaning": "低。", "cites": [{"t": "岸外而臼中。(臼中,中间凹陷。)", "b": "明·刘基《诚意伯刘文成公文集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('463wx','伐','1','fá','亻','6','','[{"pinyin": "fá", "defs": [{"meaning": "(会意。从人,从戈。甲骨文字形,像用戈砍人的头。本义:砍杀)。"}, {"meaning": "同本义。", "cites": [{"t": "伐,击也。", "b": "《说文》"}, {"t": "伐,杀也。", "b": "《广雅》"}, {"t": "为酒醴,伐豚羔,舞长袖。", "b": "宋·苏辙《太白山祈雨词》"}], "words": [{"w": "伐祭", "t": "砍头祭天"}, {"w": "伐杀", "t": "杀戮。"}]}, {"meaning": "砍伐。", "cites": [{"t": "伐竹取道。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "坎坎伐檀兮。", "b": "《诗·魏风·伐檀》"}, {"t": "斯亦伐根以求木茂。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "伐薪烧炭南山中。 ", "b": "白居易《卖炭翁》"}], "words": [{"w": "伐取", "t": "砍伐取得"}, {"w": "伐炭", "t": "伐木烧炭"}, {"w": "伐薪", "t": "砍柴。"}]}, {"meaning": "讨伐,进攻。", "cites": [{"t": "齐师伐我。", "b": "《左传·庄公十年》"}, {"t": "凡师有钟鼓曰伐,无曰侵。", "b": "《左传·庄公二十九年》"}, {"t": "其后秦伐赵。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "季氏将伐颛臾。", "b": "《论语·季氏》"}], "words": [{"w": "口诛笔伐;伐叛", "t": "讨伐叛逆"}, {"w": "伐罪吊民", "t": "讨伐有罪的君主,抚慰受难的百姓。"}]}, {"meaning": "自吹自擂,夸耀自己。", "cites": [{"t": "愿无伐善,无施劳。", "b": "《论语·公冶长》"}, {"t": "每一令出,平伐其功。", "b": "《史记·屈原贾生列传》"}, {"t": "不伐己功,不矜己能。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "伐智", "t": "夸耀自己的才智"}, {"w": "伐善", "t": "夸耀自己的长处"}, {"w": "伐功矜能", "t": "吹嘘自己的功劳和才能"}, {"w": "伐德", "t": "自夸其德。"}]}, {"meaning": "败坏,损伤。", "cites": [{"t": "重被猛术。国本必伐。", "b": "宋·秦观《治势下》"}], "words": [{"w": "伐性", "t": "危害身心"}, {"w": "伐命", "t": "残害性命"}, {"w": "伐生", "t": "残害生命。"}]}, {"meaning": "打破、挫败。", "cites": [{"t": "故上兵伐谋,其次伐交,再次伐兵。", "b": "《孙子·谋攻》"}]}, {"meaning": "敲击。", "cites": [{"t": "征人伐鼓。", "b": "《诗·小雅·采芑》"}], "words": [{"w": "伐鼓", "t": "敲鼓"}, {"w": "伐梆", "t": "敲打梆子。"}]}, {"meaning": "引申为开凿。", "cites": [{"t": "乃伐山石,刻之日月。", "b": "唐·韩愈《汴州东西水门记》"}]}, {"meaning": "批评,责备。", "cites": [{"t": "伐孔子之说,何逆于礼。", "b": "王充《论衡·问孔》"}], "words": [{"w": "口诛笔伐", "t": ""}]}, {"meaning": "功劳,功业。", "cites": [{"t": "晋侯使却至献楚捷于周,与单襄公语,骤称其伐。", "b": "《左传·成公十六年》。杜预注:伐,功也。"}, {"t": "千秋无他材能术学,又无伐阅功劳。", "b": "《汉书·车千秋传》"}, {"t": "自矜功伐,奋其私智而不师古。", "b": "《史记·项羽本纪》"}, {"t": "北救赵而西却秦,此五霸之伐也。", "b": "《史记·魏公子列传》"}], "words": [{"w": "伐阅", "t": "功绩和资历。"}]}, {"meaning": "畎上高土。", "cites": [{"t": "匠人为沟洫,耜广五寸,二耜为耦,一耦之伐,广尺深尺,谓之畎。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('464wx','延','1','yán','廴','6','','[{"pinyin": "yán", "defs": [{"meaning": "同本义。", "cites": [{"t": "延,长行也。", "b": "《说文》。按,字亦作“蜒”。"}, {"t": "蝮蛇蜒只。", "b": "《楚辞·大招》"}, {"t": "延颈而鸣,舒翼而舞。", "b": "《韩非子》"}, {"t": "我不敢知曰:不其延。惟不敬厥德,乃早坠厥命。", "b": "《书·召诰》"}, {"t": "兹物苟难停,吾寿安得延!", "b": "晋·陆机《长歌行》"}, {"t": "莫不延颈举踵。", "b": "《吕氏春秋·顺说》"}], "words": [{"w": "延瞩", "t": "引颈瞩目"}, {"w": "延望", "t": "引颈远望"}, {"w": "延算三纪", "t": "延长寿命三十六年"}, {"w": "延年", "t": "延长寿命"}, {"w": "延息", "t": "延长寿命"}, {"w": "延期", "t": "延长或推迟日期。"}]}, {"meaning": "假借为“引”。引入;引见;迎接。", "cites": [{"t": "摈者,延之日升。", "b": "《礼记·玉藻》"}, {"t": "主人延客祭。", "b": "《礼记·曲礼》"}, {"t": "出延射。", "b": "《礼记·射义》"}], "words": [{"w": "延接", "t": "引进接待"}, {"w": "延入", "t": "引入"}, {"w": "延登", "t": "引入而登殿。"}]}, {"meaning": "拖延。", "cites": [{"t": "延至七年(拖延到民国七年,即公元1918年)。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "延挨", "t": "拖延"}, {"w": "延俄", "t": "延迟一会儿。"}]}, {"meaning": "延续。", "cites": [{"t": "延及孝文王、庄襄王…国家无事。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "延寿文疏", "t": "祝寿的颂辞"}, {"w": "延誉(称扬优点,使其名声远扬)延玩(迟延玩忽)", "t": ""}]}, {"meaning": "蔓延。", "cites": [{"t": "延,遍也。", "b": "《方言十三》"}, {"t": "延及于平民。", "b": "《书·吕刑》"}, {"t": "前后邃延。", "b": "《礼记·玉藻》"}], "words": [{"w": "延地", "t": "到处"}, {"w": "延灼", "t": "蔓延燃烧。"}]}, {"meaning": "邀请;请。", "cites": [{"t": "各复延至其家,皆出酒食。", "b": "晋·陶渊明《桃花源记》"}, {"t": "饮宴既毕,谦延玄德于上座。", "b": "《三国演义》"}], "words": [{"w": "延师", "t": "聘请教师"}, {"w": "延款", "t": "延请,款待"}, {"w": "延医", "t": "请医生。"}]}, {"meaning": "迎击。", "cites": [{"t": "秦人开关延敌。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "长,久。", "cites": [{"t": "延,长也。", "b": "《尔雅》"}, {"t": "延延,长也。", "b": "《广雅》"}, {"t": "延颈秀项。", "b": "曹植《洛神赋》"}, {"t": "延,年长也。凡施于年者谓之延。", "b": "《方言一》"}, {"t": "君亦悔祸之延。", "b": "《左传·成公十三年》"}, {"t": "悔相道之不察兮,延伫乎吾将反。", "b": "《楚辞·离骚》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('465wx','仲','1','zhòng','亻','6','','[{"pinyin": "zhòng", "defs": [{"meaning": "(会意兼形声。从人,从中。中亦声。甲骨文、金文作“中”。本义:排行第二)。"}, {"meaning": "同本义。", "cites": [{"t": "仲,中也。", "b": "《说文》"}, {"t": "仲,中也,言位在中也。", "b": "《释名》"}, {"t": "伯其甫、仲、叔、季惟其所当。", "b": "《仪礼·士冠礼》"}, {"t": "五十以伯仲,周道也。", "b": "《礼记·檀弓》。按,古者幼名冠字,冠字谓之且字,且,荐也。表之以字,所以为伯、仲、叔、季之藉也。殷礼二十为字之时,即兼伯仲叔季呼之,周礼始字不呼伯仲,至五十乃加而呼之。女子则笄而字即称伯姬、仲姬。"}, {"t": "伯仲之间见伊吕,指挥若定失萧曹。", "b": "杜甫《咏怀古迹》"}, {"t": "孰与仲多。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "仲子", "t": "对兄弟中排行第二者的尊称;次子"}, {"w": "仲兄", "t": "次兄;二哥"}, {"w": "仲年", "t": "次年,第二年"}, {"w": "仲弟", "t": "二弟"}, {"w": "仲叔", "t": "兄弟中排行第二者。"}]}, {"meaning": "假借为中。时序、位次居中的,特指每季的第二个月。", "cites": [{"t": "以殷仲春。", "b": "《书·尧典》"}, {"t": "律中仲吕。", "b": "《礼记·月令》"}, {"t": "凡四时成岁,有春夏秋冬,名有孟仲季,以名十有二月。", "b": "《逸周书·周月》"}], "words": [{"w": "仲月", "t": "每季的第二个月"}, {"w": "仲商", "t": "即仲秋"}, {"w": "仲阳", "t": "即仲春"}, {"w": "仲吕", "t": "中吕。古乐十二律的第六律,又称“小吕”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('466wx','件','1','jiàn','亻','6','','[{"pinyin": "jiàn", "defs": [{"meaning": "(会意。从人,从牛。《说文》:“分也。从人,从牛。牛大物故可分。”本义:分解,分开) 同本义。", "cites": [{"t": "件错理微。", "b": "晋·郭璞《山海经·图赞》"}], "words": [{"w": "件别", "t": "分别,一一分开"}, {"w": "件举", "t": "枚举,一一分开列举。"}]}, {"meaning": "计量某些个体事物、衣服等。", "cites": [{"t": "不要因一事而惹出两件三件。", "b": "《朱子语类辑略》"}], "words": [{"w": "三件行李;件把", "t": "约数,指数量接近或等于“一件”"}, {"w": "件件", "t": "每一件;一件件,一桩桩"}, {"w": "件数", "t": "事物的数目。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('467wx','任','1','rén rèn','亻','6','','[{"pinyin": "rén", "defs": [{"meaning": "汉王莽时女子爵位名。用以称公主。", "cites": [{"t": "其女皆为任。", "b": "《汉书·王莽传》"}]}, {"meaning": "古代中国南方少数民族的一种乐曲。", "cites": [{"t": "任,南蛮之乐也。", "b": "《礼记·明堂位》"}]}, {"meaning": "壬人,狡猾骗人的;巧言谄媚的。", "cites": [{"t": "惇德允元而难任人。", "b": "《书·舜典》"}, {"t": "孔任不行。", "b": "《后汉书·致恽传》"}], "words": [{"w": "任人", "t": "佞人。品行不端的人。"}]}, {"meaning": "姓。"}]}, {"pinyin": "rèn", "defs": [{"meaning": "(形声。从人,壬(rén)声。甲骨文字形。壬是任的初文。壬即担荷的担子的竖立形。本义:挑担;荷;肩负)。"}, {"meaning": "同本义。", "cites": [{"t": "悲灵均之任石。", "b": "郭璞《江赋》"}, {"t": "是任是负。", "b": "《诗·大雅·生民》。注:“任,犹抱也。”"}, {"t": "负任担荷。", "b": "《国语·齐语》。注:“任,抱也。”"}, {"t": "负任儋荷。", "b": "《国语·齐语》。注;“犹抱也。”"}, {"t": "任重石之何益。", "b": "《楚辞·悲回风》"}], "words": [{"w": "任石", "t": "负石。负以重石"}, {"w": "任车", "t": "载物负重之车"}, {"w": "任负", "t": "负载,承载。"}]}, {"meaning": "堪;承当;禁受。", "cites": [{"t": "病不任行。", "b": "《史记·白起传》"}, {"t": "身被大病,不任茅土。", "b": "《后汉书·丁鸿传》"}, {"t": "无由会晤,不任区区向往之至。", "b": "宋·王安石《答司马谏议书》"}, {"t": "副将史德威慨然任之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "任受", "t": "承受,忍受"}, {"w": "任患", "t": "承受祸患,承担过失"}, {"w": "任过", "t": "承担过失"}, {"w": "任堪", "t": "承受,禁受。"}]}, {"meaning": "保举;担保,保用。", "cites": [{"t": "使州里任之,则宥而赦之。", "b": "《周礼·大司徒》"}, {"t": "重怒难任。", "b": "《左传·僖公十五年》。注:“当也。”"}], "words": [{"w": "任出", "t": "取保出狱"}, {"w": "任保", "t": "担保。"}]}, {"meaning": "任用,委派人员担任职务。", "cites": [{"t": "以任邦国。", "b": "《周礼·大司马》"}, {"t": "以九职任万民》", "b": ""}], "words": [{"w": "任良", "t": "任用贤才"}, {"w": "任贤", "t": "委用德才兼备的人"}, {"w": "任能", "t": "委用有才能的人"}, {"w": "任势", "t": "利用形势"}, {"w": "新任厂长; 任官", "t": "委任官职"}, {"w": "任臣", "t": "委用臣下"}, {"w": "任寄", "t": "委任;付托。"}]}, {"meaning": "讲信用;相信;信任。", "cites": [{"t": "任,保也。", "b": "《说文》"}, {"t": "为气任侠。", "b": "《史记·季布栾布传》"}, {"t": "吾权任子以死生。", "b": "《管子·大匡》"}, {"t": "王甚任之。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "任属", "t": "信用托付"}, {"w": "任信", "t": "信任"}, {"w": "任待", "t": "信赖器重。"}]}, {"meaning": "听凭,任凭。", "cites": [{"t": "无意苦争春,一任群芳妒。", "b": "陆游《卜算子·咏梅》"}, {"t": "曷不委心任去留。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "恐不任我意。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "任兴", "t": "任性;凭兴趣"}, {"w": "任抓掀", "t": "任意选用;任意拿"}, {"w": "任谤任劳", "t": "任劳任怨;不怕别人诽谤,不辞劳苦"}, {"w": "任忒", "t": "听任差错;任意妄为"}, {"w": "任令", "t": "听凭,任凭"}, {"w": "任委", "t": "任随,任凭"}, {"w": "任真", "t": "听其自然"}, {"w": "任臆", "t": "任随心意。"}]}, {"meaning": "放纵,无拘束。", "cites": [{"t": "上舍法,任民之所善,故奸多。", "b": "《商君书·弱民》"}, {"t": "任情返道,劳而无获。", "b": "《齐民要术·种谷》"}, {"t": "感任达不拘,与叔父籍为竹林之游,当世礼法者讥其所为。", "b": "《晋书·阮咸传》"}], "words": [{"w": "任达", "t": "任性放纵,不受礼法拘束。"}]}, {"meaning": "使用。", "cites": [{"t": "为百姓积任器。", "b": "《周礼·司隶》"}], "words": [{"w": "任力", "t": "使用民力"}, {"w": "任数", "t": "用权谋,使心计"}, {"w": "任谋", "t": "使用权谋;运用策略"}, {"w": "任算", "t": "施用计谋,进行谋算。"}]}, {"meaning": "怀孕", "cites": [{"t": "周后妃任成王於身。", "b": "《大戴礼·保傅》"}, {"t": "初,李亲任政君在身。", "b": "《汉书·元后传》。师古曰:“任,怀任。”"}, {"t": "初,刘媪任高祖", "b": "《汉书·叙传上》"}], "words": [{"w": "任娠", "t": "怀孕;任身。"}]}, {"meaning": "立功。", "cites": [{"t": "六曰事典,以富邦国,以任百官,以生万民。", "b": "《周礼》"}]}, {"meaning": "担子,行李。", "cites": [{"t": "门子治任将归。", "b": "《孟子》。注:“担也。”"}, {"t": "班白者不以其任行乎道路。", "b": "《礼记·祭义》。注:“所担持也。”"}], "words": [{"w": "治任", "t": "收拾行李。"}]}, {"meaning": "职责。", "cites": [{"t": "且中期之所官,琴瑟也。弦不调,弄不明,中期之任也。", "b": "《韩非子》"}]}, {"meaning": "任务;责任。任何人应对其负责或承担的事务。", "cites": [{"t": "至于斟酌损益,进尽忠言,则攸之、伟、允之任也。", "b": "诸葛亮《出师表》"}, {"t": "天将降大任于斯人也。", "b": "《孟子·告子下》"}], "words": [{"w": "任责", "t": "责任"}, {"w": "任道", "t": "可担负重任的仁人志士"}, {"w": "任属巨肩", "t": "责任重大。"}]}, {"meaning": "人质。", "cites": [{"t": "皆请降送任于勒。", "b": "《晋书》"}]}, {"meaning": "丝;线。", "cites": [{"t": "夫以一缕之任,系千钧之重。", "b": "《汉书》"}]}, {"meaning": "能力。", "cites": [{"t": "因任而授官,循名而责实。", "b": "《韩非子》"}]}, {"meaning": "劳役。", "cites": [{"t": "赋敛重数,百姓任罢。", "b": "《汉书》。颜师古注:“任,谓役事也。”"}]}, {"meaning": "表示让步关系,相当于“纵使”、“即使 ”。", "cites": [{"t": "任是深山最深处,也应无计避征徭。", "b": "唐·杜荀鹤《山中寡妇》"}]}, {"meaning": "用于担任官职的次数。", "cites": [{"t": "他是举人出身,做过一任知县的。", "b": "清·吴敬梓《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('468wx','伤','1','shāng','亻','6','','[{"pinyin": "shāng", "defs": [{"meaning": "(形声。从人,塲(shāng)省声。本义:皮肉破损处;创伤)。"}, {"meaning": "同本义。", "cites": [{"t": "伤,创也。", "b": "《说文》"}, {"t": "命理瞻伤。", "b": "《礼记·月令》。注:“创之浅者曰伤。”"}, {"t": "以杙抉其伤。", "b": "《左传·襄公十七年》"}, {"t": "无面伤。", "b": "《左传·哀公元年》"}, {"t": "匠石运斤成风,听而斵之,尽垩而鼻不伤。", "b": "《庄子·徐无鬼》"}, {"t": "咶其叶,则口烂而受伤。", "b": "《庄子·人间世》"}, {"t": "则援剑戟而逐之,不避死伤。", "b": "《荀子·正论》"}, {"t": "其伤于缚者,即幸留,病数月乃瘳。", "b": "清·方苞《狱中杂记》"}, {"t": "城中死伤日积,巷哭声相闻。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "枪伤;两虎相斗,必有一伤;负伤;轻伤;重伤;遍体鳞伤;死伤;刀伤;烧伤,灼伤;烫伤;冻伤", "t": ""}]}, {"meaning": "丧事;丧祭。", "cites": [{"t": "是故明君饰食饮吊伤之礼。", "b": "《管子·君臣下》"}], "words": [{"w": "伤辞 ", "t": "古时为相识者死亡而作的哀辞。"}]}, {"meaning": "损失。", "cites": [{"t": "天下得其地,则其利少;攻其国,则其伤大。", "b": "《韩非子·五蠹》"}]}, {"meaning": "受伤的人。", "cites": [{"t": "虏救死扶伤不给 。", "b": "司马迁《报任安书》"}]}, {"meaning": "损伤;伤害。", "cites": [{"t": "川壅而溃,伤人必多。", "b": "《国语·周语》"}, {"t": "杀人者死,伤人及盗抵罪。", "b": "《史记·高祖本纪》"}, {"t": "受命以来,夙夜忧叹,恐托付不效,以伤先帝之明。", "b": "诸葛亮《出师表》"}, {"t": "苟余心之端直兮,虽僻远其何伤?", "b": "《楚辞·屈原·涉江》"}, {"t": "何伤乎!亦各言其志也。", "b": "《论语·先进》"}], "words": [{"w": "伤化", "t": "损害教化"}, {"w": "无伤大雅;伤沴", "t": "受伤害而不流通"}, {"w": "伤情", "t": "伤感"}, {"w": "伤暑", "t": "为暑气所伤"}, {"w": "伤勇", "t": "损害勇气"}, {"w": "伤脸", "t": "损了别人的面子"}, {"w": "伤夷折衄", "t": "遭受创伤,导致挫败"}, {"w": "伤命", "t": "伤害天子的诏命"}, {"w": "伤幸", "t": "出口伤人"}, {"w": "伤阂", "t": "伤害阻隔"}, {"w": "伤废", "t": "受伤残废的人"}, {"w": "伤毁", "t": "损坏"}, {"w": "伤廉", "t": "伤害廉洁"}, {"w": "伤生", "t": "伤害生命。"}]}, {"meaning": "受伤;负伤。", "cites": [{"t": "左骖殪兮右刃伤。", "b": "屈原《国殇》"}, {"t": "矢人惟恐不伤人。", "b": "《孟子·公孙丑上》"}, {"t": "一人予二十金,骨微伤,病间月。", "b": "方苞《狱中杂记》"}]}, {"meaning": "诋毁;中伤。", "cites": [{"t": "伤,诽也。", "b": "《广雅》"}, {"t": "伤之于昭公。", "b": "《吕氏春秋·察微"}, {"t": "人伤尧以不慈之名。", "b": "《吕氏春秋·举难》"}], "words": [{"w": "伤诋", "t": "中伤诋毁。"}]}, {"meaning": "死亡", "cites": [{"t": "生命寿长,终其年而不夭伤。", "b": "《战国策》"}]}, {"meaning": "哀伤;悲伤。", "cites": [{"t": "时人伤之,为诗云尔。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "多情自古伤离别,更那堪冷落清秋节!", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "伤今", "t": "忧思今日"}, {"w": "伤暮", "t": "哀叹年老而无成"}, {"w": "伤乖", "t": "因离别而悲伤"}, {"w": "伤沮", "t": "沮丧"}, {"w": "伤秋", "t": "悲秋,对秋景而伤感"}, {"w": "伤恫", "t": "哀痛"}, {"w": "伤惜", "t": "哀伤惋惜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('469wx','价','1','jià jiè jie','亻','6','','[{"pinyin": "jià", "defs": [{"meaning": "(形声。从人,贾声。本义:价格,价值)。"}, {"meaning": "同本义。", "cites": [{"t": "经千载以待价兮。", "b": "《文选·嵇康·琴赋》"}, {"t": "国贫而用不足,请以平价取之。", "b": "《管子·轻重》"}, {"t": "以求重价。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "价贯", "t": "价关。以铜钱计算的价钱"}, {"w": "价一不择主", "t": "价钱一样,卖得谁都可以"}, {"w": "价比", "t": "是一种物品计算期价格与其基期价格之比"}, {"w": "价色", "t": "价格。"}]}, {"meaning": "钱款、费用。", "cites": [{"t": "倘蒙不外,赍价前来,以一报答,并无虚谬。", "b": "《水许传》"}], "words": [{"w": "价钞", "t": "价款"}, {"w": "价银", "t": "指物品、产业按价应收付的银两数。"}]}, {"meaning": "声望。", "cites": [{"t": "百战百胜价,河南河北闻。", "b": "杜牧《史将军二首》"}], "words": [{"w": "价称", "t": "声价名誉。"}]}, {"meaning": "论价。", "cites": [{"t": "此屏后出为君得,胡贾欲价著不识。", "b": "宋·王安石"}]}]}, {"pinyin": "jiè", "defs": [{"meaning": "善。", "cites": [{"t": "介,善也。", "b": "《说文》"}, {"t": "价人维藩。", "b": "《诗·大雅·板》"}], "words": [{"w": "价人", "t": "善人"}, {"w": "价藩", "t": "大德之人是国家安全的屏藩。"}]}, {"meaning": "称被派遣传送东西或传达事情的人。", "cites": [{"t": "邻道守将走价驰书来诣。", "b": "《宋史》"}], "words": [{"w": "价傧", "t": "导引和接待宾客的人;陪从"}, {"w": "价妇", "t": "仆妾。"}]}]}, {"pinyin": "jie", "defs": [{"meaning": "用于句尾,相当于“的”、“似的”。", "cites": [{"t": "只听得一声震天价响,那尊金刚从台基上倒撞下来。", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('470wx','伦','1','lún','亻','6','','[{"pinyin": "lún", "defs": [{"meaning": "(形声。从人,仑(lún)声。本义:辈,类)。"}, {"meaning": "同本义。", "cites": [{"t": "伦,辈也。", "b": "《说文》"}, {"t": "人伦并处。", "b": "《荀子·富国》"}, {"t": "儗人必于其伦。", "b": "《礼记·曲礼下》"}, {"t": "毛犹有伦。", "b": "《礼记·曲礼下》"}, {"t": "廉颇赵奢之伦。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "伦辈", "t": "伦匹,伦党,伦伍"}, {"w": "伦序", "t": "流辈;等类"}, {"w": "伦表", "t": "流辈之上"}, {"w": "伦品", "t": "等类品第"}, {"w": "伦侯", "t": "秦爵名。与列侯相类而无封邑"}, {"w": "伦望", "t": "流辈中的声望"}, {"w": "伦族", "t": "所属之族。"}]}, {"meaning": "条理,顺序。", "cites": [{"t": "悌乃知序,序乃伦;伦不腾上,上乃不崩。", "b": "《逸周书》"}], "words": [{"w": "伦叙", "t": "有条理,有顺序"}, {"w": "伦次", "t": "条理次序"}, {"w": "伦绪", "t": "条理秩序。"}]}, {"meaning": "人伦,人与人之间的道德关系。伦常,纲纪,封建礼教规定的人与人之间正常关系,特指尊卑长幼之间的关系。", "cites": [{"t": "只是父亲伯叔兄弟之伦,因是圣人遗训,不敢违忤。", "b": "《红楼梦》"}, {"t": "欲洁其身,而乱大伦。", "b": "《论语》"}], "words": [{"w": "天伦", "t": "古代指父子、兄弟等关系"}, {"w": "伦物", "t": "人伦物理"}, {"w": "伦经", "t": "天道人伦的常则"}, {"w": "伦质", "t": "人伦道德之理"}, {"w": "伦谊", "t": "人伦大义。"}]}, {"meaning": "道理,义理。", "cites": [{"t": "我不知其彝伦攸叙。", "b": "《书·洪范》"}], "words": [{"w": "伦脊", "t": "道理;条理。"}]}, {"meaning": "意义。", "cites": [{"t": "夫祭有十伦焉。", "b": "《礼记·祭统》"}]}, {"meaning": "", "cites": [{"t": "有伦有义。", "b": "《庄子·齐物论》"}]}, {"meaning": "顺其纹理。", "cites": [{"t": "析开必伦。", "b": "《周礼》"}]}, {"meaning": "类比,匹敌。", "cites": [{"t": "德伦三五,配皇作烈。", "b": "三国魏·曹植《学宫颂》"}, {"t": "暴殄天物之罪,岂有伦哉!", "b": "康有为《大同书》"}], "words": [{"w": "伦列", "t": "等比,类比"}, {"w": "伦侪", "t": "比并。"}]}, {"meaning": "议论。", "cites": [{"t": "有伦、有义、有分、有辩。", "b": "《庄子·齐物论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('471wx','份','1','fèn','亻','6','','[{"pinyin": "fèn", "defs": [{"meaning": "(形声。从人,分声。同“彬”。①(bīn)本义:文质兼备的样子 ②量词。用于计数或搭配成组的东西)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('472wx','华','1','huā huá huà','十','6','','[{"pinyin": "huā", "defs": [{"meaning": "(会意。从芔,从芌(xū)。“華”的本字,上面是“垂”字,象花叶下垂形。本义:花)。"}, {"meaning": ",花朵。", "cites": [{"t": "华,荣也。", "b": "《说文》"}, {"t": "木谓之华,草谓之荣。", "b": "《尔雅·释草》"}, {"t": "桃之夭夭,灼灼其华。", "b": "《诗·周南·桃夭》"}, {"t": "焜黄华叶衰。", "b": "《乐府诗集·长歌行》"}, {"t": "今言华如华实之华者。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "华英", "t": "指花"}, {"w": "华叶", "t": "花与叶"}, {"w": "华胜", "t": "花胜。古代妇女的一种花形首饰"}, {"w": "华实", "t": "花和果实;亦指开花结果。"}]}, {"meaning": "轻浮柔弱如花的脉象。", "cites": [{"t": "脉至如华者,令人善恐。", "b": "《素问》。王冰注:“谓似华虚弱,不可正取也。”"}]}, {"meaning": "开花。", "cites": [{"t": "桃李始华。", "b": "《淮南子·时则训》"}], "words": [{"w": "华而不实", "t": "只开花不结果。比喻外表好看,内容空虚。"}]}, {"meaning": "昏花。", "cites": [{"t": "僧问:“拨尘见佛时如何?”师曰:“莫眼华。”", "b": "《五灯会元》"}]}, {"meaning": "当中剖开。", "cites": [{"t": "瓜曰华之。", "b": "《尔雅》"}, {"t": "为国君者华之。", "b": "《礼记·曲礼》。注:“中裂之。”"}]}]}, {"pinyin": "huá", "defs": [{"meaning": "华丽;光彩美丽。", "cites": [{"t": "金银华美之服。", "b": "宋·司马光《训俭示康》"}, {"t": "华堂之上。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "华衣乘马。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "华扁", "t": "华丽的匾额"}, {"w": "华彩", "t": "华美;光彩"}, {"w": "华服", "t": "华丽的服装"}, {"w": "华舆", "t": "华美的车辆或轿子"}, {"w": "华筵", "t": "华美的筵席"}, {"w": "华观", "t": "华丽的观阙,即宫门前的望楼"}, {"w": "华毂", "t": "华丽的车。"}]}, {"meaning": "豪华。", "cites": [{"t": "况我大魏天王,个为华侈。", "b": "杨衒之《洛阳伽蓝记》"}]}, {"meaning": "灰白。", "cites": [{"t": "多情应笑我,早生华发。", "b": "苏轼《赤壁怀古》"}], "words": [{"w": "华首", "t": "头发花白。指老人"}, {"w": "华颠", "t": "白发"}, {"w": "华鬓", "t": "鬓发花白"}, {"w": "华发", "t": "花白头发。"}]}, {"meaning": "浮华。", "cites": [{"t": "处其实,不居其华。", "b": "《老子》"}], "words": [{"w": "华辞", "t": "虚浮巧饰的言辞"}, {"w": "华誉", "t": "不实的声誉"}, {"w": "华风", "t": "浮华的文风。"}]}, {"meaning": "繁盛。", "cites": [{"t": "其街市之繁华,人烟之阜盛,自与别处不同。", "b": "《红楼梦》"}], "words": [{"w": "华滋", "t": "草木茂盛的样子。"}]}, {"meaning": "鲜美。", "cites": [{"t": "其民华食而脂肥。", "b": "《素问》。王冰注:华谓鲜美,酥酪骨肉之类也。"}]}, {"meaning": "光辉;光彩。", "cites": [{"t": "日月光华,旦复旦兮。", "b": "王勃《卿云歌》"}], "words": [{"w": "华景", "t": "明亮的阳光"}, {"w": "华月", "t": "皎洁的月亮"}, {"w": "华焕", "t": "光彩绚丽"}, {"w": "华魄", "t": "光彩;亦指皎洁的月光。"}]}, {"meaning": "声望。", "cites": [{"t": "客游梁朝,则声华籍甚。", "b": "《文选·任彦升·宣德皇后令》"}]}, {"meaning": "精华。", "cites": [{"t": "物华天宝。", "b": "王勃《滕王阁序》"}], "words": [{"w": "华甸", "t": "精华荟聚之区。常以指京都、中原、中国"}, {"w": "华英", "t": "精华"}, {"w": "华髓", "t": "精髓。"}]}, {"meaning": "文才。", "cites": [{"t": "昔庚无规才华清英。", "b": "刘勰《文心雕龙》"}]}, {"meaning": "瓜类植物的果实。", "cites": [{"t": "天子树瓜华,不敛藏之种也。", "b": "《礼记》"}]}, {"meaning": "光环。", "cites": [{"t": "薄云敝日时,由于无数水滴的衍射,在太阳、月亮或其他发光体四周形成的一组或几组小半径的同心彩色光环", "b": ""}]}, {"meaning": "矿脉或煤层已发生氧化或分解的露头。"}]}, {"pinyin": "huà", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('473wx','仰','1','yǎng áng','亻','6','','[{"pinyin": "yǎng", "defs": [{"meaning": "(会意兼形声。从人,从卬,卬亦声。卬,小篆字形。一个人站着,一个人跪着,跪者抬头看站者,为抬头仰望的“仰”的本字。后借为“我”,遂加“人”作“仰”。“卬”“仰”古今字。本义:抬头,脸向上)。"}, {"meaning": "同本义。跟“俯”相对。", "cites": [{"t": "仰,举也。", "b": "《说文》。按,仰即卬之或体。汉书皆作卬,不作仰。"}, {"t": "驷马仰秼。", "b": "《淮南子·说山》"}, {"t": "仰足以事父母。", "b": "《孟子·梁惠王上》"}, {"t": "仰头相向鸣。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "仰药而伏刃。", "b": "《汉书·息夫躬传》。注:“仰首而饮药。”"}, {"t": "无敢仰视。", "b": "汉·刘向《列女传》"}, {"t": "遂于树下仰取叶。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "仰视天。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "椎髻仰面。", "b": "清·魏学洢《核舟记》"}], "words": [{"w": "仰企俯思", "t": "抬头盼望,低头思念。有仰慕之意"}, {"w": "仰脸", "t": "抬头,脸向上方"}, {"w": "仰瞻", "t": "仰望;追慕。"}]}, {"meaning": "敬慕。钦佩或高度敬重。", "cites": [{"t": "众士慕仰。", "b": "《资治通鉴》"}], "words": [{"w": "仰从", "t": "服从;遵命"}, {"w": "仰服", "t": "敬服,钦佩。"}]}, {"meaning": "切望 旧时公文中上级命令下级的惯用辞,意为切望。", "cites": [{"t": "又仰山前山后里正之家也要捕虎文状。", "b": "《水浒传》"}, {"t": "仰各路大帅各尽忠力,以图国家大计。", "b": "《续资治通鉴》"}]}, {"meaning": "依赖;依靠。", "cites": [{"t": "前无可仰之积。", "b": "《后汉书·邓禹传》。注:“犹恃也。”"}, {"t": "随身所需,悉仰于官,不别治生产。", "b": "《三国演义》"}, {"t": "凡五谷者,民之所仰也。", "b": "《墨子·七患》"}], "words": [{"w": "仰人度日", "t": "依靠别人供给衣食来维持生活"}, {"w": "仰成", "t": "依赖别人取得成功"}, {"w": "仰哺", "t": "依靠他人哺养、供养。"}]}, {"meaning": "物体面朝上。", "cites": [{"t": "春若遇旱,秋耕之地得仰垄待雨。", "b": "《齐民要术》"}]}, {"meaning": "指把覆合着的物体翻过来,使底部朝上。"}]}, {"pinyin": "áng", "defs": [{"meaning": "高", "words": [{"w": "仰仰", "t": "气概轩昂的样子"}, {"w": "仰首伸眉", "t": "意气高昂的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('474wx','仿','1','fǎng páng','亻','6','','[{"pinyin": "fǎng", "defs": [{"meaning": "(形声。从人,方声。本义:相似。或作“彷”)。"}, {"meaning": "同本义。", "cites": [{"t": "仿,相似也。", "b": "《说文》。俗亦作倣。"}], "words": [{"w": "仿像", "t": "仿佛相像"}, {"w": "他俩长得相仿", "t": ""}]}, {"meaning": "仿效;模仿。也作“彷”、“倣”。", "cites": [{"t": "见所制蜡人,悉仿生人。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "他们的罐子似乎是仿皮革容器制作的;仿刻", "t": "仿照原本的款式和字体刻印"}, {"w": "仿模", "t": "模仿"}, {"w": "仿写", "t": "模仿书写。"}]}, {"meaning": "照着范本写的字。", "cites": [{"t": "正说得热闹,一个小学生送倣来批。", "b": "《儒林外史》"}]}, {"meaning": "——见“仿佛”(fǎngfú)。"}]}, {"pinyin": "páng", "defs": [{"meaning": ""}, {"meaning": "游荡,徘徊。", "cites": [{"t": "[楚灵]王亲独行,屏营仿偟于山林之中。", "b": "《国语·吴语》"}, {"t": "聊仿佯而逍遥兮,永历年而无成。", "b": "《楚辞》"}, {"t": "逍遥乎广泽之中,而仿洋于山峡之旁。", "b": "《淮南子·原道》"}]}, {"meaning": "地势坦荡。", "cites": [{"t": "西方…仿佯无所倚,广大无所极些。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('475wx','伙','1','huǒ huo','亻','6','','[{"pinyin": "huǒ", "defs": [{"meaning": "同伴，一同做事的人。古兵制十人为火,同火的人互称火伴", "words": [{"w": "伙伴", "t": "元魏时军人以十人为火,共灶炊食,故称同火时为火伴。引申为同伴。后多写‘伙伴’为同伴"}]}, {"meaning": "集体所办的饭食", "words": [{"w": "伙食", "t": "饭食,多指集体所办的饭食"}]}, {"meaning": "旧指店员或长工等人", "words": [{"w": "伙计", "t": "合伙人,合作共事的人"}]}, {"meaning": "结伴，联合起来", "words": [{"w": "合伙", "t": "合股营业"}]}]}, {"pinyin": "huo", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('476wx','伪','1','wěi','亻','6','','[{"pinyin": "wěi", "defs": [{"meaning": "(会意兼形声。从人,从为,为亦声。本义:欺诈)。"}, {"meaning": "同本义。", "cites": [{"t": "伪,诈也。", "b": "《说文》。徐锴曰:“伪者,人为之,非天真也。”"}, {"t": "无或诈伪淫巧。", "b": "《礼记·月令》"}, {"t": "不可学,不可事而在人者,谓之性;可学而能,可事而成之在人者,谓之伪。", "b": "《荀子·性恶篇》"}], "words": [{"w": "伪诈", "t": "欺诈"}, {"w": "伪怠", "t": "欺诈懈怠"}, {"w": "伪服", "t": "骗居尊位"}, {"w": "伪人", "t": "伪夫。伪善、诈伪之人"}, {"w": "伪巧", "t": "诈伪奸滑"}, {"w": "伪臣", "t": "诈伪之臣"}, {"w": "伪民", "t": "诈伪的人"}, {"w": "伪行", "t": "诈伪的行为。"}]}, {"meaning": "人为;矫饰。", "cites": [{"t": "人之性恶,其善者伪也。", "b": "《荀子·性恶》"}]}, {"meaning": "伪装;假装。", "cites": [{"t": "然则舜伪喜者与?", "b": "《孟子·万章上》"}], "words": [{"w": "伪廉", "t": "假装廉洁"}, {"w": "伪行", "t": "假装出某种行为;假装"}, {"w": "伪冒", "t": "假冒;冒充"}, {"w": "伪从", "t": "假作同意"}, {"w": "伪让", "t": "假意谦让。"}]}, {"meaning": "虚假;不真实。", "cites": [{"t": "作伪主以行。", "b": "《礼记·曾子问》"}, {"t": "道恶乎隐而有真伪?", "b": "《庄子·齐物论》"}, {"t": "寄伪儿啼。", "b": "唐·柳宗元《童区寄传》"}, {"t": "古书之正伪。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "伪为屋券。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "家藏伪章。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "伪言", "t": "虚假的言论"}, {"w": "伪名", "t": "假名"}, {"w": "伪行", "t": "虚假的行为"}, {"w": "伪命", "t": "虚假的命令"}, {"w": "伪辞", "t": "虚假的言辞"}, {"w": "伪态", "t": "虚伪的态度"}, {"w": "伪意", "t": "虚假的心意"}, {"w": "伪戾", "t": "诈伪乖戾"}, {"w": "伪俗", "t": "诈伪的风气。"}]}, {"meaning": "非法;非正统。", "cites": [{"t": "且臣少事伪朝。", "b": "晋·李密《陈情表》"}], "words": [{"w": "伪政府;伪组织;伪庭", "t": "伪朝"}, {"w": "伪师", "t": "僭伪、非正统政权的军队"}, {"w": "伪国", "t": "僭伪之国"}, {"w": "伪朝", "t": " 伪、非正统的王朝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('477wx','自','1','zì','自','6','','[{"pinyin": "zì", "defs": [{"meaning": "(象形。小篆字形。象鼻形。“自”是汉字的一个部首。本义:鼻子)。"}, {"meaning": "同本义。", "cites": [{"t": "自,鼻也。", "b": "《说文》。段玉裁注:“许谓自与鼻义同音同,而用自为鼻者绝少也。”"}]}, {"meaning": "始;开头。", "cites": [{"t": "故法者,王之本也;刑者,爱之自也。", "b": "《韩非子》"}]}, {"meaning": "起源。", "cites": [{"t": "知风之自,知微之显,可以入德也。", "b": "《礼记》"}], "words": [{"w": "自顷", "t": "近来。"}]}, {"meaning": "自己,自我;本身。", "cites": [{"t": "不自为政,卒劳百姓。", "b": "《诗·小雅 ·节南山》"}, {"t": "自引而起,绝袖。", "b": "《战国策·燕策》"}, {"t": "人必自侮,然后人侮之;家必自毁,而后人毁之;国必自伐,而后人伐之。", "b": "《孟子》"}, {"t": "自比于人。(“人”指信陵君。)", "b": "《史记·魏公子列传》"}, {"t": "自度终不能得之于王。(“度”,估计;“得”,指圆满得到;“之”,代援赵的具体措施。)", "b": "《史记·魏公子列传》"}, {"t": "自疏濯淖污泥之中。(自疏,自己疏远。濯,通“浊”。淖(nào)泥浆。)", "b": "《史记·屈原贾生列传》"}, {"t": "自知其陋而谨护其失。(其:第一人称代词,自己。陋:见闻少,知识浅薄。而:转折连词,可是,却。谨护其失:谨慎小心地掩盖自己的过错。失:过错。)", "b": "清·刘开《问说》"}, {"t": "自言本是京城女,家在虾蟆陵下住。", "b": "白居易《琵琶行》"}], "words": [{"w": "自戕", "t": "戕害自己;自杀"}, {"w": "自呈", "t": "自首;认罪"}, {"w": "自敝", "t": "自己困败"}, {"w": "自各儿", "t": "自己"}, {"w": "自凛", "t": "自身寒微"}, {"w": "自引", "t": "自行引退;自杀。"}]}, {"meaning": "由;从。", "cites": [{"t": "自,从也。", "b": "《广雅》"}, {"t": "自天右之。", "b": "《易·大有》"}, {"t": "退食自公。", "b": "《诗·召南·羔羊》"}, {"t": "出自东方。", "b": "《诗·邶风·日月》"}, {"t": "自去史职。", "b": "《后汉书·张衡传》"}, {"t": "自是指物作诗立就。", "b": "宋·王安石《伤仲永》"}, {"t": "自李唐以来。", "b": "宋·周敦颐《爱莲说》"}, {"t": "自张柴村。", "b": "《资治通鉴·唐纪》"}, {"t": "感觉何自起。", "b": "蔡元培《图画》"}, {"t": "自南海还。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "自海入侵。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "自从", "t": "介词。表示时间的起点。"}]}, {"meaning": "在;于。", "cites": [{"t": "不自我先,不自我后。", "b": "《诗·小雅》"}], "words": [{"w": "自诸", "t": "犹其余"}, {"w": "自余", "t": "犹其余;以外;此外。"}]}, {"meaning": "自然,当然。", "cites": [{"t": "重罚不用而民自治。(自治,自然太平。)", "b": "《韩非子·五蠹》"}, {"t": "神明自得。", "b": "《荀子·劝学》"}, {"t": "自见异物。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "自足制之。", "b": "《资治通鉴》"}, {"t": "自从本说。(意思是说,自然应当遵从《本草经》的说法。)", "b": "宋·沈括《梦溪笔谈》"}, {"t": "自有同志者在。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "自恁", "t": "自然;径自"}, {"w": "自化", "t": "自然化育"}, {"w": "自可", "t": "自然可以"}, {"w": "自老", "t": "自然衰老。"}]}, {"meaning": "本是;本来。", "cites": [{"t": "人之死生自有长短,不在操行善恶也。", "b": "汉·王充《论衡》"}, {"t": "小人自姓崔名宁,与那小娘子无半面之识。", "b": "《京本通俗小说》"}, {"t": "东家有贤女,自名秦罗敷。", "b": "《乐府诗集》"}], "words": [{"w": "自可", "t": "本来可以"}, {"w": "自性", "t": "个性;本性"}, {"w": "自合", "t": "自应;本该"}, {"w": "自恁", "t": "本当。"}]}, {"meaning": "仍旧,依然。", "cites": [{"t": "阁中帝子今何在?槛外长江空自流。", "b": "唐·王勃《滕王阁》"}]}, {"meaning": "亲自。", "cites": [{"t": "早自来谢项王。", "b": "《史记·项羽本纪》"}, {"t": "自抱持武。", "b": "《汉书·李广苏建传》"}, {"t": "王自往临视。", "b": "晋·干宝《搜神记》"}, {"t": "自将三千人。", "b": "宋·司马光《资治通鉴·唐纪》"}], "words": [{"w": "自鞫", "t": "亲自审讯罪犯。"}]}, {"meaning": "别自、另外。", "cites": [{"t": "一板已自布字。", "b": "宋·沈括《梦溪笔谈·活板》"}]}, {"meaning": "假如,苟。与“非”连用。", "cites": [{"t": "自非亭午夜分,不见曦月。", "b": "《三峡》"}], "words": [{"w": "自这般", "t": "假如像这样。"}]}, {"meaning": "即使,虽。", "cites": [{"t": "乐正子春之母死,五日而不食。曰:“吾悔之。自吾母而不得吾情,吾恶乎用吾情。”", "b": "《礼记·檀弓》"}]}, {"meaning": "却,可是。", "cites": [{"t": "不思量,自难忘。", "b": "苏轼《江城子·记梦》"}, {"t": "不是俺要结果你,自是前日来时,有那陆虞候传着高太尉钧旨,教我两个到这里结果你,立等金印回去回话。", "b": "《水浒传》"}]}, {"meaning": "因为,由于。", "cites": [{"t": "自我致冠,敬慎不败也。", "b": "《易·需》"}]}, {"meaning": "用。", "cites": [{"t": "天秩有礼,自我五礼有庸哉。", "b": "《书·皋陶谟》"}, {"t": "知之曰知之,不知曰不知,内不自以诬,外不自以欺。", "b": "《荀子·儒效》"}]}, {"meaning": "是。", "cites": [{"t": "女子无计可奈,见王先生也自一表非俗,只得从了他。", "b": "《初刻拍案惊奇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('478wx','伊','1','yī','亻','6','','[{"pinyin": "yī", "defs": [{"meaning": "(会意。从人,从尹。尹,治理。合起来指伊尹,殷治理天下者。后假借为那)。"}, {"meaning": "表示远指,相当于“那”。", "cites": [{"t": "所谓伊人,在水一方。", "b": "《诗·秦风·蒹葭》。笺:“伊,当作繄,犹是也。”"}]}, {"meaning": "表示第三人称,相当于“她”、“他”、“彼”。", "cites": [{"t": "薛蟠因伊倔强,将酒照脸泼去。", "b": "《红楼梦》"}, {"t": "江家我顾伊,庾家伊顾我。", "b": "《世说新语》"}, {"t": "吾见张时,伊已六十。", "b": "《南史》"}], "words": [{"w": "伊行", "t": "她那里;他们"}, {"w": "伊曹", "t": "彼辈,他们"}, {"w": "伊俦", "t": "彼辈,其类"}, {"w": "伊拉", "t": "方言。他们。"}]}, {"meaning": "表示第二人称,相当于“你”。", "cites": [{"t": "勿学汝兄,汝兄自不如伊。", "b": "《世说新语》"}, {"t": "我这里吐胆倾心说与伊,难道你不解其中意。", "b": "佚名《马陵道》"}], "words": [{"w": "伊咱", "t": "你"}, {"w": "伊行", "t": "你这里;你们"}, {"w": "伊家", "t": "你。"}]}, {"meaning": "表示判断,常与“匪”连用,相当于“却是”、“即是”。", "cites": [{"t": "匪莪伊蒿。", "b": "《诗·小雅·蓼莪》"}, {"t": "昔卫鞅因景监以见,有识知其不终。今得臣举者,匪荣伊辱。", "b": "《后汉书》"}], "words": [{"w": "匪朝伊暮;匪朝伊夕;匪荣伊辱;匪愚伊耄", "t": ""}]}, {"meaning": "语助词。用于句中,无义。", "cites": [{"t": "旨酒既清,嘉荐伊脯。", "b": "《仪礼》"}]}, {"meaning": "是。", "cites": [{"t": "不可畏也,伊可怀也。", "b": "《诗·豳风·东山》。笺:“伊,当作繄。”"}, {"t": "我这怀矣,自诒伊阻。", "b": "《诗·邶风·雄雉》"}]}, {"meaning": "伊拉克的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('479wx','血','1','xuè xiě','血','6','','[{"pinyin": "xuè", "defs": [{"meaning": "(指事。小篆字形,从皿,“一”象血形。表示器皿中盛的是血。本义:牲血,供祭祀用)。"}, {"meaning": "同本义。后泛指血液。", "cites": [{"t": "血,祭所荐牲血也。", "b": "《说文》"}, {"t": "取其血膋。", "b": "《诗·信南山》。笺:“血以告杀也。”"}, {"t": "以血祭祭社稷、五祀五岳。", "b": "《周礼·大宗伯》"}, {"t": "血祭盛气也。", "b": "《礼记·郊特性》"}, {"t": "叩其鼻以血社也。", "b": "《公羊传·僖公十九年》"}, {"t": "原野厌人之肉,川谷流人之血。", "b": "汉·扬雄《法言》"}], "words": [{"w": "血海的干系", "t": "关系非常重大的责任"}, {"w": "血映征袍", "t": "喻战斗激烈"}, {"w": "血肉蹀躞", "t": "死尸阻路,只能小步慢行。"}]}, {"meaning": "指妇女的月经。", "cites": [{"t": "今常见怀胎七八个月而生子者,但以血止为度。", "b": "张介宾《景岳全书》"}], "words": [{"w": "血分", "t": "妇女的经血"}, {"w": "经血;血崩", "t": "经血过多。"}]}, {"meaning": "悲痛的泪水。", "cites": [{"t": "老夫哭爱子,日暮千行血。", "b": "唐·顾况《伤子》"}, {"t": "乘马班如,泣血涟如。", "b": "《易·屯》"}], "words": [{"w": "血泪", "t": ""}]}, {"meaning": "血脉。", "cites": [{"t": "气血俱动。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "用鲜血涂沾。", "cites": [{"t": "兵可毋血刃而俱罢。", "b": "《汉书》"}], "words": [{"w": "血刃", "t": "血沾刀口。谓杀戮"}, {"w": "血衣", "t": "沾血的衣服"}, {"w": "血花", "t": "飞溅的鲜血"}, {"w": "血点,血踪", "t": "犹血迹。"}]}, {"meaning": "杀伤,杀害。", "cites": [{"t": "挥直刃以血其邪者。", "b": "唐·沈光《李白酒楼记》"}], "words": [{"w": "血风肉雨", "t": "形容剧烈残酷的搏斗或屠杀"}, {"w": "血场", "t": "指战场"}, {"w": "血沟", "t": "条状的流血伤口。"}]}, {"meaning": "染,涂。"}, {"meaning": "指有血缘关系的近亲。亦指血缘、血统。", "cites": [{"t": "亲附疏,割犯血。", "b": "汉·扬雄《太玄》"}], "words": [{"w": "血叔", "t": "嫡亲的叔父"}, {"w": "血胄", "t": "后裔"}, {"w": "血胤", "t": "同一血统的子孙后代;犹血统"}, {"w": "血嗣", "t": "指子孙"}, {"w": "血属", "t": "有血缘关系的亲属。"}]}, {"meaning": "喻红色。", "cites": [{"t": "杜鹃灿烂,血艳夺目。", "b": "《徐霞客游记》"}, {"t": "俄有赤龙长千余丈,雷目血舌。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "血殷", "t": "暗红"}, {"w": "血旗", "t": "指红旗"}, {"w": "血紫", "t": "紫红色。"}]}]}, {"pinyin": "xiě", "defs": [{"meaning": "口语读音(多单用)。", "words": [{"w": "鸭血", "t": "鸭子的血制成的食品。"}, {"w": "血沥沥", "t": "血淋淋"}, {"w": "血唬零喇", "t": "血糊淋粒。血淋淋的"}, {"w": "血胡同", "t": "血湖同。于人丛中杀出的血路"}, {"w": "血糊突", "t": "流血很多,像粥样"}, {"w": "血渌渌", "t": "鲜血淋漓"}, {"w": "血心", "t": "忠心;热忱"}, {"w": "血的教训", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('480wx','向','1','xiàng','口','6','','[{"pinyin": "xiàng", "defs": [{"meaning": "(象形。从宀(mián),从口。“宀”表示房屋,甲骨文中像屋墙,有窗户之形。本义:朝北开的窗户)。"}, {"meaning": "同本义。", "cites": [{"t": "向,北出牖也。", "b": "《说文》。古宫室北墉,无户牖,民间或有之,命之曰向。"}, {"t": "穹窒熏鼠,塞向墐户。", "b": "《诗·豳风·七月》"}]}, {"meaning": "泛指窗户。", "cites": [{"t": "闭户塞向,密泥,勿使风入漏气。", "b": "《齐民要术》"}, {"t": "刮楹达鄉(向)。", "b": "《礼记·明堂位》。注:“谓夹户窗也。”"}, {"t": "启牖鄉(向)如初。", "b": "《仪礼·士虞礼记》"}]}, {"meaning": "方向;方位。", "cites": [{"t": "明利害之向。", "b": "《国语·周语上》"}, {"t": "东向驰去。", "b": "明·魏禧《魏叔子文钞·大铁椎传》"}], "words": [{"w": "风向;反向;去向;山向;向前", "t": "犹将来。"}]}, {"meaning": "过去,往昔。", "cites": [{"t": "向也不恕而今也恕,向也虚而今也实。", "b": "《庄子·山水》"}, {"t": "向为身死而不受。", "b": "《孟子·告子上》"}, {"t": "向其先表之时可导也。(以前他们设立标记的时候,是可以根据标记渡水的。导,引导,渡水。)", "b": "《吕氏春秋·察今》"}, {"t": "寻向所志。", "b": "晋·陶渊明《桃花源记》"}, {"t": "便扶向路。", "b": ""}, {"t": "向吾不为斯役。(假使过去我不当这个差)", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "向察众人之议。", "b": "宋·司马光《资治通鉴》"}, {"t": "向之噌吰。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "向道", "t": "原以为"}, {"w": "向年", "t": "往年。"}]}, {"meaning": "从来,向来。", "cites": [{"t": "臣向蒙国恩,刻思图报。", "b": "《三国演义》"}], "words": [{"w": "向料", "t": "一直认为"}, {"w": "向蒙", "t": "一贯承蒙。"}]}, {"meaning": "刚才。", "cites": [{"t": "向见年少妇人自水边小径去矣。", "b": "《金史》"}, {"t": "向来道边有卖饼家。", "b": "《史记·华佗传》"}, {"t": "比向日不同。", "b": "《西厢记》"}], "words": [{"w": "向年", "t": "往年"}, {"w": "向事", "t": "往事"}, {"w": "向来", "t": "表示时间上过去不久。"}]}, {"meaning": "面朝、面对。跟“背”相对。", "cites": [{"t": "见剑向己。", "b": "《左传·定公十年》注"}, {"t": "磨刀霍霍向猪羊。", "b": "《木兰诗》"}, {"t": "眈眈相向。", "b": "《聊斋志异·狼三则》"}, {"t": "夫妻向隅,茅舍无烟。", "b": "《聊斋志异·促织》"}], "words": [{"w": "向灯向火", "t": "喻看法各一"}, {"w": "向暖", "t": "晒太阳"}, {"w": "向炎乞儿", "t": "近火取暖的乞丐。比喻趋炎附势之徒。"}]}, {"meaning": "趋向,亲近。", "cites": [{"t": "何故欲向汉?", "b": "《史记·班超传》"}, {"t": "向于时夏。", "b": "《书·多士》"}], "words": [{"w": "向化", "t": "归顺教化"}, {"w": "向服", "t": "仰慕佩服。"}]}, {"meaning": "爱;偏爱;偏袒。", "cites": [{"t": "不妨事,妳妳向着俺哩!", "b": "《元曲选·武汉臣·老生儿剧三》"}], "words": [{"w": "向顺", "t": "偏向;偏袒。"}]}, {"meaning": "往,去。", "cites": [{"t": "闲向溪边磨巨斧。", "b": "《水浒全传》"}], "words": [{"w": "向寓", "t": "以往借宿。"}]}, {"meaning": "从;在。", "cites": [{"t": "向那御屏风背后,转出一大臣。", "b": "《水浒传》"}]}, {"meaning": "用于“争”、“怎”、“争奈”、“如何”一类词语后,起加强语气作用。", "cites": [{"t": "怎生向,人间好事到头少。", "b": "《法曲第二》"}]}, {"meaning": "奔向;趋向。", "cites": [{"t": "嚮方略。", "b": "《荀子·仲尼》"}, {"t": "军以向宛洛。", "b": "《三国志·诸葛亮传》"}, {"t": "直下襄阳向洛阳。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "叱牛牵向北。", "b": "唐·白居易《卖炭翁》"}, {"t": "已向荆州。", "b": "《资治通鉴》"}], "words": [{"w": "向清虚", "t": "奔向高天。喻得到幸福。"}]}, {"meaning": "接近;临近。", "cites": [{"t": "东坡春向暮,树木今何如?", "b": "《东坡种花二首》"}], "words": [{"w": "向中", "t": "谓近午。比喻鼎盛时期"}, {"w": "向早", "t": "凌晨。"}]}, {"meaning": "旧时,以往。", "cites": [{"t": "曏,不久也。从日,鄉声。", "b": "《说文》"}, {"t": "曏役之三月。", "b": "《春秋传》"}, {"t": "曏谓往时也。", "b": "《桂苑珠丛》"}, {"t": "曏者,吾子辱使某见。", "b": "《仪礼·士相见礼》"}], "words": [{"w": "向日;向之豪气何在?", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('481wx','似','1','shì sì','亻','6','','[{"pinyin": "shì", "defs": [{"meaning": "用在名词、代词或动词后面,表示比况,相当于“似的”、“如…一般”。", "cites": [{"t": "那后生就空地当中,把一条棒使得风车儿似转。", "b": "《水浒传》"}]}]}, {"pinyin": "sì", "defs": [{"meaning": "(形声。从人,以声。本义:像;相像)。"}, {"meaning": "同本义。", "cites": [{"t": "似,象也。", "b": "《说文》"}, {"t": "似,有以相攖,有不相櫻也。", "b": "《墨子经上》"}, {"t": "见似目瞿。", "b": "《礼记·杂记》。注:“谓容貌似其父母。”"}, {"t": "寡人虽无似也。", "b": "《礼记·哀公问》。注:“无似犹言不肖。”"}, {"t": "似,类也。", "b": "《广雅》"}, {"t": "凄然似秋,暖然似春。", "b": "《庄子·大宗师》"}, {"t": "夫马似鹿者而题之千金。", "b": "《韩非子·外储说右上》"}, {"t": "玉人之所患,患石之似玉者。", "b": "《吕氏春秋·疑似》"}, {"t": "今世之主法先王之法也,有似于此。", "b": "《吕氏春秋·察今》"}, {"t": "布衾多年冷似铁,娇儿恶卧踏里裂。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "凄凄不似向前声,满座重闻皆掩泣。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "似起", "t": "像,如"}, {"w": "似像", "t": "相同的样子,模样"}, {"w": "似有若无", "t": "只当没有这回事。形容不在乎,不在意"}, {"w": "似许", "t": "如此,如许"}, {"w": "似漆如胶", "t": "形容情投意合,难舍难分"}, {"w": "似类", "t": "相类;相似;像"}, {"w": "似若", "t": "好像。"}]}, {"meaning": "似乎。", "cites": [{"t": "日光下彻,影布石上,怡然不动;倏尔远逝,往来翕忽,似与游者相乐。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "虫翘然矜鸣,似报主知。", "b": "《聊斋志异·促织》"}], "words": [{"w": "似不足信;似如", "t": "好像"}, {"w": "似若", "t": "好像"}, {"w": "似是而非", "t": ""}]}, {"meaning": "给予,送给。", "cites": [{"t": "今日把似君,谁为不平事。", "b": "贾岛《剑客》"}]}, {"meaning": "继承。", "cites": [{"t": "是以似之。", "b": "《诗·小雅·裳裳者华》"}, {"t": "似续妣祖。", "b": "《诗·小雅·斯干》"}], "words": [{"w": "似续", "t": "继承;继续"}, {"w": "召公是似", "t": ""}]}, {"meaning": "用于比较,表示程度更甚。", "cites": [{"t": "今年衰似去年些。", "b": "宋·刘克庄《浪淘沙·纸帐素屏遮》"}], "words": [{"w": "一个高似一个;一天好似一天", "t": ""}]}, {"meaning": "放在动词后面,表示动作影响及于他处,相当于“与”、“向”。", "cites": [{"t": "今朝别有承恩处,鹦鹉飞来说似人。", "b": "罗邺《宫中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('482wx','后','1','hòu','口','6','','[{"pinyin": "hòu", "defs": [{"meaning": "(会意。象人之形,施令以告四方,古之,从一口,发号者君后也。按从坐人,从口,与君同意。本义:君主,帝王)。"}, {"meaning": "同本义。", "cites": [{"t": "后,继君体也。", "b": "《说文》"}, {"t": "班瑞于群后。", "b": "《书·舜典》"}, {"t": "允王维后。", "b": "《诗·周颂·时迈》"}, {"t": "后王命冢宰。", "b": "《礼记·内则》"}, {"t": "昔我先世后稷。", "b": "《国语·周语》"}, {"t": "皇皇后帝。", "b": "《左传·文公二年》"}, {"t": "夏后皋之墓也。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "后王", "t": "君王;天子"}, {"w": "后帝", "t": "天帝;上帝"}, {"w": "后夷", "t": "上古有穷国的国君"}, {"w": "后辟", "t": "君主;帝王。"}]}, {"meaning": "帝王的妻子。", "cites": [{"t": "天子之妃曰后。", "b": "《礼记·曲礼》"}, {"t": "帝嫡妃曰皇后,帝母曰皇太后,帝祖母曰太皇太后。", "b": "《独断下》"}], "words": [{"w": "后族", "t": "皇后的亲族"}, {"w": "后党", "t": "清末慈禧一派;皇后、太后的亲族或与皇后、太后利害关系一致的人所结成的政治集团。"}]}, {"meaning": "古代指列国诸侯。", "cites": [{"t": "肆觐东后。", "b": "《书·舜典》。郑玄注:“东后,东方之诸侯也。”"}]}, {"meaning": "古代对长官、郡守或将领的尊称。", "cites": [{"t": "赫赫明后,柔嘉维则。", "b": "汉·李翕《西狭颂》"}, {"t": "岂知吾后意,忧此毗陵最。", "b": "前蜀·贯休《上孙使君》诗"}]}, {"meaning": "指后土。对大地的尊称。", "cites": [{"t": "王大封,则先告后土。", "b": "《周礼·大宗伯》"}], "words": [{"w": "后皇", "t": "后土与皇天"}, {"w": "后缗", "t": "地神。"}]}, {"meaning": "(会意。金文,从“彳”(chì),表示与走路有关,从“幺”(yāo,小),从“攵”(suī),是“足”的反写,有“行路迟缓”的意思)。段玉裁《说文解字注》:“幺者小也,小而行迟,后可知矣。”本义:迟到,走在后。"}, {"meaning": "同本义。", "cites": [{"t": "後,迟也。", "b": "《说文》"}, {"t": "非敢後也,马不进也。", "b": "《论语·雍也》"}, {"t": "子路从而後。", "b": "《论语·微子》"}, {"t": "兄弟之後生者。", "b": "《仪礼·有司後》"}, {"t": "臣闻命後。", "b": "《左传·定公八年》。注:“晚也。”"}, {"t": "收气乃後。", "b": "《素问·五常政大论》。注:“後,不及时也。”"}, {"t": "知古则可知後。", "b": "《吕氏春秋·长见》。注:“来也。”"}], "words": [{"w": "随后就来;落后;殿后", "t": "行军走在最后。"}]}, {"meaning": "承继。", "cites": [{"t": "陷队之士知疾斗,不得斩首队五人,则陷队之士,人赐爵一级,死则一人后。", "b": "《商君书》"}]}, {"meaning": "后代,子孙。", "cites": [{"t": "式救尔後。", "b": "《诗·大雅·瞻卬》"}, {"t": "为人後者为之子也。", "b": "《礼记·杂记》"}, {"t": "天下初发难时,假立诸侯,後以代秦。", "b": "《史记·项羽本纪》"}, {"t": "求太监后。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "无后;绝后;后叶", "t": "后代"}, {"w": "后胤", "t": "子孙,后裔"}, {"w": "后戒", "t": "后人的鉴戒"}, {"w": "后哲", "t": "后代的哲人"}, {"w": "后绝", "t": "没有后代。"}]}, {"meaning": "次序在后。", "cites": [{"t": "子路从而后。", "b": "《论语·微子》"}, {"t": "后岁余。", "b": "《聊斋志异·促织》"}, {"t": "从诸君子之后。", "b": "清·梁启超《谭嗣同传》"}, {"t": "惟恐或后。", "b": "清·周容《芋老人传》"}]}, {"meaning": "时间较迟或较晚。与“先”相对。", "cites": [{"t": "君还而后退。", "b": "《仪礼·聘礼》"}, {"t": "然后国之良士,亦将可得而众也。", "b": "《墨子·尚贤上》"}, {"t": "知止而后有定,定而后能静。", "b": "《礼记·大学》"}, {"t": "以五戒先後刑罚。", "b": "《周礼·士师》"}, {"t": "事至而後虑者谓之後。", "b": "《荀子·大略》"}, {"t": "后遂无问津者。", "b": "晋·陶渊明《桃花源记》"}, {"t": "后遂不复至。", "b": "明·魏禧《大铁椎传》"}, {"t": "花朝节后。", "b": "明·袁宏道《满井游记》"}, {"t": "其后为之者较少。", "b": "蔡元培《图画》"}], "words": [{"w": "后时", "t": "后来;以后"}, {"w": "后次", "t": "下次;下回"}, {"w": "后儿", "t": "后天"}, {"w": "后番", "t": "下次;下回。"}]}, {"meaning": "后面,位置在后。", "cites": [{"t": "事成而後。", "b": "《礼记·乐记》。注:“谓位在下也。”"}, {"t": "以後路与冕服。", "b": "《礼记·杂记》"}, {"t": "近出前后。", "b": "唐·柳宗元《三戒》"}, {"t": "后狼止。", "b": "《聊斋志异·狼三则》"}, {"t": "恐前后受其敌。", "b": ""}, {"t": "转视积薪后。", "b": ""}, {"t": "以攻其后。", "b": ""}], "words": [{"w": "后山", "t": "后面的山"}, {"w": "后应", "t": "居后作接应 的部队"}, {"w": "后廷", "t": "后宫"}, {"w": "后户", "t": "后门"}, {"w": "后言", "t": "背后的议论"}, {"w": "后阁", "t": "在后面 的殿阁"}, {"w": "先斩后奏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('483wx','行','1','háng hàng héng xíng','行','6','','[{"pinyin": "háng", "defs": [{"meaning": "(象形。本义:道路)。"}, {"meaning": "同本义。", "cites": [{"t": "行,道也。", "b": "《说文》"}, {"t": "行有死人。", "b": "《诗·小雅·小弁》"}, {"t": "遵彼微行。", "b": "《诗·豳风·七月》"}], "words": [{"w": "行苇", "t": "路旁芦苇"}, {"w": "行阡", "t": "道路"}, {"w": "行神", "t": "路神"}, {"w": "行程", "t": "路程"}, {"w": "行街", "t": "大路。"}]}, {"meaning": "直排为行,横排为列。", "cites": [{"t": "左右陈行,戒我师旅。", "b": "《诗·大雅·常武》"}, {"t": "凌余阵兮躐余行。", "b": "《楚辞·九歌·国殇》"}, {"t": "奉读书,五行并下。", "b": "《后汉书·应奉传》"}]}, {"meaning": "军队编制,二十五人为一行。", "cites": [{"t": "郑伯使卒出貑,行出犬鸡。", "b": "《左传·隐公十一年》"}]}, {"meaning": "队伍,军队。", "cites": [{"t": "陈胜、吴广皆次当行。", "b": "《史记·陈涉世家》"}, {"t": "必能使行阵和睦。", "b": "诸葛亮《出师表》"}], "words": [{"w": "行阵", "t": "军队行列"}, {"w": "行阵和睦", "t": "指军队协调团结"}, {"w": "行首", "t": "军队的行列"}, {"w": "行阵", "t": "行伍。旧指军队。"}]}, {"meaning": "行业。原指工商业中的类别,后亦泛指职业。", "cites": [{"t": "皆次当行。", "b": "《史记·陈涉世家》"}], "words": [{"w": "干装修水管这一行;你干哪一行?;行计", "t": "行业"}, {"w": "行户", "t": "行业,妓院;商户。"}]}, {"meaning": "辈分。", "cites": [{"t": "丈人行也。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "行次", "t": ""}]}, {"meaning": "连续贯穿。", "cites": [{"t": "以次贯行,固执无违。", "b": "《汉书》"}]}, {"meaning": "这里 ——表示处所。", "cites": [{"t": "这小贱人不来我行回话。", "b": "《西厢记》"}]}, {"meaning": "那里 ——表示处所。", "cites": [{"t": "最苦梦魂,今宵不到伊行。", "b": "周邦彦《风流子》"}]}]}, {"pinyin": "hàng", "defs": [{"meaning": "刚强。", "cites": [{"t": "行,行行,刚强的样子。", "b": "《集韵》"}]}]}, {"pinyin": "héng", "defs": [{"meaning": "——“道行”(dàohéng):僧道修行的功夫,比喻技能本领。"}]}, {"pinyin": "xíng", "defs": [{"meaning": "(会意。从彳,从亍。本义:走路,行走)。"}, {"meaning": "同本义。", "cites": [{"t": "行,人之步趋也。", "b": "《说文》"}, {"t": "行,往也。", "b": "《广雅》"}, {"t": "中行独复。", "b": "《易·复》"}, {"t": "我独南行。", "b": "《诗·邶风·击鼓》"}, {"t": "行彼周行。", "b": "《诗·小雅·大东》"}, {"t": "行李之往来。", "b": "《左传·僖公三十年》"}, {"t": "天子以四海为家,故谓所居为行在所。", "b": "蔡邕《独断》"}, {"t": "三人行,必有我师焉。", "b": "《论语·述而》"}, {"t": "此虽免乎行,犹有所待者也。", "b": "《庄子·逍遥游》"}, {"t": "羊子尝行路。", "b": "《后汉书·列女传》"}, {"t": "行数十里。", "b": "《世说新语·自新》"}, {"t": "与偕行。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "出行", "t": "到外地去"}, {"w": "远行", "t": "出远方"}, {"w": "行三坐五", "t": "前呼后拥,行坐都有人在旁伺候"}, {"w": "行学", "t": "上学"}, {"w": "行行", "t": "走动不停"}, {"w": "行次", "t": "行走;走到。"}]}, {"meaning": "出游;出行;出动。", "cites": [{"t": "坐席行衣,分为七覆,烟火鱼鸟,置作五衡。", "b": "唐·李商隐《谢何南公和诗启》"}], "words": [{"w": "行脚僧", "t": "行脚僧人,行脚头陀僧。云游四方的和尚"}, {"w": "行踏", "t": "游逛"}, {"w": "行幕", "t": "宿处的别称"}, {"w": "行粮", "t": "兵士的口粮"}, {"w": "行厨", "t": "随军厨师"}, {"w": "行童", "t": "佛寺里的童仆。"}]}, {"meaning": "运行。", "cites": [{"t": "天行有常。", "b": "《荀子·天论》"}, {"t": "日月之行。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "行行", "t": "指情况进展或时序运行"}, {"w": "行律", "t": "运行的规律"}, {"w": "行度", "t": "运行的度数"}, {"w": "行疾", "t": "运行迅速"}, {"w": "行健", "t": "运行壮健。"}]}, {"meaning": "流动,流通。", "cites": [{"t": "背夏首以窘逝兮,沂行川而永叹。", "b": "晋·陆云《九愍·修身》"}], "words": [{"w": "行川", "t": "流水"}, {"w": "行光", "t": "水中闪烁的光影"}, {"w": "行杯", "t": "流觞,流杯。古代风俗,每逢三月上旬巳日,于环曲的水渠边高会,置酒杯于水的上流,杯流行停于谁前,谁便取饮。"}]}, {"meaning": "流行;流传。", "cites": [{"t": "残贼公行。", "b": "汉·贾谊《论积贮疏》"}, {"t": "迄今盛行。", "b": "蔡元培《图画》"}], "words": [{"w": "行病", "t": "传播疾病"}, {"w": "行时道", "t": "走运"}, {"w": "行贝", "t": "通行贝币"}, {"w": "行术", "t": "通行的方法"}, {"w": "行钞", "t": "发行纸币"}, {"w": "行贿", "t": "流通财物。"}]}, {"meaning": "做;从事某种活动。", "cites": [{"t": "行劫缚者(干掳人抢东西的)。", "b": "唐·柳宗元《童区寄传》"}, {"t": "自行搜觅。", "b": "《聊斋志异·促织》"}], "words": [{"w": "行所无事", "t": "泰然自若;行若无事"}, {"w": "行不去", "t": "做不出"}, {"w": "行意", "t": "动静;行动的意思。"}]}, {"meaning": "实施。", "cites": [{"t": "行刑不疚。", "b": "《国语·晋语》"}, {"t": "所行者忠信。", "b": "欧阳修《朋党论》"}, {"t": "说秦王书十上而说不行。", "b": "《战国策·秦策一》"}], "words": [{"w": "行权", "t": "临时变通;权宜行事"}, {"w": "行化", "t": "消化"}, {"w": "行财", "t": "管理钱财的伙计"}, {"w": "行究", "t": "查究;追究"}, {"w": "行遣", "t": "处置,治罪"}, {"w": "行不去", "t": "行不通"}, {"w": "行吊", "t": "进行吊唁。"}]}, {"meaning": "离开。", "cites": [{"t": "为吾子之将行也。", "b": "《左传·僖公三十三年》"}]}, {"meaning": "路程。", "cites": [{"t": "千里之行,始于足下。", "b": "《老子》"}], "words": [{"w": "行纪", "t": "犹行程。"}]}, {"meaning": "道理,事物的发展规律。", "cites": [{"t": "下有直言,臣之行也。", "b": "《国语》"}, {"t": "天之行也。", "b": "汉·贾谊《论积贮疏》"}]}, {"meaning": "行为。", "cites": [{"t": "行为迟。", "b": "《庄子·养生主》"}, {"t": "此行所负之责。", "b": "孙文《黄花冈七十二烈士事略·序》"}, {"t": "行拂乱其所为(做事就使他做的事不顺,让他做的事情没秩序,颠倒错乱。)", "b": "《孟子·告子下》"}], "words": [{"w": "行踏", "t": "行为"}, {"w": "行景", "t": "行为;模样"}, {"w": "行短", "t": "行为不大方"}, {"w": "行作动步", "t": "举动"}, {"w": "行持", "t": "行为"}, {"w": "行处", "t": "行为;动作。"}]}, {"meaning": "品行。", "cites": [{"t": "宣其德行。", "b": "《国语·晋语》"}, {"t": "改桓之行。", "b": ""}, {"t": "吾子行厚。", "b": "唐·柳宗元《柳河东集》"}, {"t": "行为士先者。", "b": "明·张溥《五人墓碑记》"}, {"t": "辱人贱行。", "b": ""}], "words": [{"w": "德行", "t": "道德和品行"}, {"w": "行同能偶", "t": "品行相同,才能相等"}, {"w": "行高", "t": "品性高洁"}, {"w": "行能", "t": "品行与才能"}, {"w": "行义", "t": "品行,道义"}, {"w": "行谊", "t": "品行,道义。"}]}, {"meaning": "即将…。", "cites": [{"t": "行略定秦地。", "b": "《史记·项羽本纪》"}, {"t": "行与卿等诀别。", "b": "《新编五代史平话》"}], "words": [{"w": "行见天下太平", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('484wx','舟','1','zhōu','舟','6','','[{"pinyin": "zhōu", "defs": [{"meaning": "(象形。甲骨文字形,象船形。两边象船帮,中间三条线代表船头、船舱和船尾。先秦多用“舟”,汉以后用“船”渐多起来。本义:船)。"}, {"meaning": "同本义。", "cites": [{"t": "舟,船也。古者共鼓货狄,刳木为舟,剡木为楫,以济不通。象形。", "b": "《说文》"}, {"t": "自关而西谓之船,自关而东谓之舟。", "b": "《方言九》"}, {"t": "作舟以行水。", "b": "《考工记·总目》"}, {"t": "舟以行川谷。", "b": "《墨子·节用》。按,舟之始,古以自空大木为之,曰俞,后因集板为之,曰舟,又以其沿水而行曰船也。"}, {"t": "刳木为舟,剡木为楫。", "b": "《易·系辞下》"}, {"t": "二子乘舟,泛泛其逝。", "b": "《诗·邶风·二子乘舟》"}, {"t": "两岸猿声啼不住,轻舟已过万重山。", "b": "李白《早发白帝城》"}, {"t": "舟人大恐。(舟人,船夫)。", "b": "宋·苏轼《石钟山记》"}, {"t": "舟人指点。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "舟人", "t": "掌舟的人。即船夫"}, {"w": "舟次", "t": "船只及船只停留之处"}, {"w": "舟牧", "t": "古时掌船的官"}, {"w": "舟师", "t": "古时的水上军队,即今海军;船夫"}, {"w": "舟航", "t": "由舟相连而成的浮桥。也作“舟杭”"}, {"w": "舟梁", "t": "连船为桥;船和桥。"}]}, {"meaning": "尊彝等器的托盘。", "cites": [{"t": "皆有舟。", "b": "《周礼·司尊彝》。司农注:“尊下台,若今之承盘。”"}]}, {"meaning": "酒器名。", "cites": [{"t": "明当罚二子,已洗两王舟。", "b": "《东坡诗》"}]}, {"meaning": "用船过渡。", "cites": [{"t": "就其深矣,方之舟之。", "b": "《诗·邶风·谷风》"}, {"t": "商人舟米以来者相望。", "b": "李翱《故东川节度使卢公传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('485wx','全','1','quán','入','6','','[{"pinyin": "quán", "defs": [{"meaning": "(一作仝。会意。篆文从入,从王(玉)。盖谓交纳的玉完整无缺。本义:纯色玉)。"}, {"meaning": "同本义。", "cites": [{"t": "全,完也。", "b": "《说文》"}, {"t": "天子用全,上公用龙。", "b": "《周礼·考工记·王人》"}]}, {"meaning": "古州名。全州 。治所在今广西全县。"}, {"meaning": "完全。", "cites": [{"t": "不明其义,君人不全。", "b": "《礼记·祭统》。注:“犹具也。”"}, {"t": "天地无全功。", "b": "《列子·天瑞》"}, {"t": "唯全人能之。", "b": "《庄子·庚桑楚》"}, {"t": "以全争于天下。", "b": "《孙子·谋攻》"}, {"t": "墓中全乎为五人。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "全装贯带", "t": "全副武装"}, {"w": "全副", "t": "全套"}, {"w": "全家;全甲", "t": "全部披甲的士兵"}, {"w": "全仗", "t": "全部的仪仗兵卫;完全依靠"}, {"w": "全兵", "t": "军队全部以弓矛等兵器武装"}, {"w": "全舍", "t": "全部舍弃"}, {"w": "全批", "t": "统统"}, {"w": "全全", "t": "全部;统统"}, {"w": "全周", "t": "周全;全面"}, {"w": "全争", "t": "不动一卒,不攻一城,完全用智谋使敌降伏"}, {"w": "全别", "t": "完全变了样,完全不一样"}, {"w": "全制", "t": "完全控制"}, {"w": "全遂", "t": "完全遵从"}, {"w": "全错;全怪我;全无心肝;全完", "t": "全部缴纳"}, {"w": "全旨", "t": "全部的意蕴、含义"}, {"w": "全通", "t": "全部通晓"}, {"w": "全量", "t": "全部,所有"}, {"w": "全灶", "t": "全能的厨师"}, {"w": "全行", "t": "全部"}, {"w": "全副", "t": "整个"}, {"w": "全宗", "t": "整个宗族"}, {"w": "全批", "t": "全体"}, {"w": "全颗", "t": "一群人的全体"}, {"w": "全额", "t": "全部规定的数目。"}]}, {"meaning": "完备,完整。", "cites": [{"t": "法不平,令不全,是亦夺柄失位之道也。", "b": "《管子·任法》"}, {"t": "三年之后,未尝见全牛也。", "b": "《庄子·养生主》"}, {"t": "城郭不备全,不可以自守。", "b": "《墨子·七患》"}, {"t": "牺牲之不全肥。", "b": "《墨子·明鬼下》"}, {"t": "全吴之地。", "b": "《资治通鉴》"}, {"t": "全石以为底。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "全身盔甲。", "b": "《广东军务记》"}], "words": [{"w": "全帖", "t": "共有十面的礼帖,用红纸折成,用于隆重的礼节"}, {"w": "全分", "t": "全套;一整套"}, {"w": "全挂子", "t": "一整套的"}, {"w": "手稿不全;全牛", "t": "完整的牛"}, {"w": "全羽", "t": "完整的彩色鸟羽"}, {"w": "全衣", "t": "完整的衣着"}, {"w": "全具", "t": "用于祭祀的牲畜身体完整无损"}, {"w": "全肥", "t": "祭祀用的牲畜完整而肥美"}, {"w": "全牲", "t": "完整的家畜"}, {"w": "全气", "t": "精气完整"}, {"w": "全功", "t": "完满的功业"}, {"w": "全安", "t": "完满安乐"}, {"w": "全道", "t": "完满地掌握为君之道。"}]}, {"meaning": "纯,纯粹的。与“杂”相对。", "cites": [{"t": "知夫不全不粹之不足以为美也。", "b": "《荀子》"}]}, {"meaning": "保全。", "cites": [{"t": "又何吝一躯啖我而全微命乎?", "b": "马中锡《中山狼传》"}, {"t": "千万不复全。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "苟全性命。", "b": "诸葛亮《出师表》"}], "words": [{"w": "全国为上", "t": "少杀人,少破坏,能完整地得到敌方领土与百姓为好"}, {"w": "全身远害", "t": "保全自身,远离祸害"}, {"w": "全名完节", "t": "保全自身的名誉和节操"}, {"w": "全活", "t": "得以保全生命"}, {"w": "全交", "t": "保全交情和友谊"}, {"w": "全福", "t": "保全所享有的幸福"}, {"w": "全功", "t": "保全身心之功"}, {"w": "全生", "t": "保全天性,顺其自然"}, {"w": "全交", "t": "保全、维护友谊或交情"}, {"w": "全守", "t": "保全节操"}, {"w": "全安", "t": "保全平安"}, {"w": "全佑", "t": "保全,庇护"}, {"w": "全忠", "t": "保全忠贞"}, {"w": "全物", "t": "保全物类的生命"}, {"w": "全和", "t": "保全儒家中和的道德修养"}, {"w": "全性", "t": "保全天性"}, {"w": "全真", "t": "保全天性"}, {"w": "全节", "t": "保全气节;妇女保全贞操"}, {"w": "全养", "t": "保全,养成"}, {"w": "全济", "t": "保全,救活"}, {"w": "全躯", "t": "保全自己的身体、生命"}, {"w": "全护", "t": "保全,保护。"}]}, {"meaning": ",病愈。", "cites": [{"t": "十全为上。", "b": "《周礼·医师》。注:“犹瘉也。”"}, {"t": "复之全之。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "完全,都。", "cites": [{"t": "故今日之责任,不在他人,而全在我少年。", "b": "清·梁启超《饮冰室合集·文集》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('486wx','会','1','huì kuài','人','6','','[{"pinyin": "huì", "defs": [{"meaning": "(会意。古文从合,从彡。按彡亦众多意。本义:会合)。"}, {"meaning": "同本义。", "cites": [{"t": "会,合也。", "b": "《说文》"}, {"t": "会,聚也。", "b": "《广雅·释诂三》"}, {"t": "会同有绛。", "b": "《诗·小雅·车攻》"}, {"t": "会言近止。", "b": "《诗·唐风·杕杜》"}, {"t": "会朝清明。", "b": "《诗·大雅·大明》"}, {"t": "会诸其币。", "b": "《仪礼·聘礼》"}, {"t": "以会天地之藏。", "b": "《礼记·月令·季秋》"}, {"t": "然后天下会于一。", "b": "柳宗元《封建论》"}, {"t": "迁客骚人,多会于此。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "会茶", "t": "一起喝茶"}, {"w": "会酒", "t": "一起吃酒"}, {"w": "会猎", "t": "原指会合打猎,又比喻会同作战"}, {"w": "会衔", "t": "联名签署公文"}, {"w": "会次", "t": "朝会停留的时刻。"}]}, {"meaning": "晤见。", "cites": [{"t": "时见曰会。", "b": "《周礼·太宗伯》"}, {"t": "相见于卻地曰会。", "b": "《礼记·曲礼》"}, {"t": "会者何,期辞也。", "b": "《公羊传·桓公十年》"}, {"t": "留待作遗施,于今天会因。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "与燕王会境上。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "会于西河外渑池。", "b": ""}, {"t": "与秦王会渑池。", "b": ""}, {"t": "与赵王会饮。", "b": ""}], "words": [{"w": "会定", "t": "见到"}, {"w": "会少离多", "t": "相会少,别离多"}, {"w": "昨天我没有会着他", "t": ""}]}, {"meaning": "使协调一致;符合。", "cites": [{"t": "音韵清畅,又深会女心。", "b": "梁·吴均《续齐谐记》"}]}, {"meaning": "器物的盖子。", "cites": [{"t": "《礼经》:器之盖曰会,为其上下相合也。", "b": "《说文·会·段注》"}, {"t": "敦启会。", "b": "《仪礼·士丧礼》"}, {"t": "命佐食启会。", "b": "《仪礼·士虞礼》"}]}, {"meaning": "业务、社交或其他性质的集会。", "cites": [{"t": "会论虞常。", "b": "《汉书·李广苏建传》"}, {"t": "来会计事。", "b": "《史记·陈涉世家》"}, {"t": "乃罢会。", "b": "《资治通鉴》"}], "words": [{"w": "晚上有个全组会;开会;欢迎会;欢送会;会文", "t": "兼含观摩、竟赛、考试等多种功能的写作集会。"}]}, {"meaning": "灾厄;厄运。", "cites": [{"t": "百六有会,《过》、《剥》成灾。", "b": "《后汉书·董卓传赞》"}]}, {"meaning": "民间一种小规模经济互助形式 。一般由发起人约集若干人,按期等量交款,首次由发起人使用,以后按议定或拈阄决定的顺序轮流使用。", "cites": [{"t": "正在各书店里约了一个会,每店三两。", "b": "《儒林外史》"}]}, {"meaning": "中医经络穴位名。", "cites": [{"t": "扁鹊乃使弟子子阳厉针砥石,以取外三阳五会。", "b": "《史记·扁鹊仓公列传》"}]}, {"meaning": "古代中国历法所用的单位,等于10800年。", "cites": [{"t": "三十年为一世;十二世计三百六十年,为一运;三十运计一万八百年,为一会;十二会计十二万九千六百年,为一元。", "b": "邵雍《皇极经世书》"}]}, {"meaning": "必然,一定。", "cites": [{"t": "吾已失恩义,会不相从许。", "b": "古乐府《孔雀东南飞》"}, {"t": "长风破浪会有时。", "b": "唐·李白《行路难》"}]}, {"meaning": "恰巧,正好。", "cites": [{"t": "会天大雨。", "b": "《史记·陈涉世家》"}, {"t": "会其怒。", "b": "《史记·项羽本纪》"}, {"t": "会幸苑中。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "会雨大作,因留寺。", "b": "《徐霞客游记·游黄山记》"}, {"t": "会宾客大宴。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "表示范围。相当于“皆”、“都”。", "cites": [{"t": "弦、匏、笙、簧,会守拊鼓。", "b": "《礼记》"}]}, {"meaning": "相当于“与”、“同”、“和”。", "cites": [{"t": "上遣侍郎马尔泰会查郎河按治,于义坐夺官。", "b": "《清史稿·刘于义传》"}]}]}, {"pinyin": "kuài", "defs": [{"meaning": "(会意。本义:计算;总计。本指年终结账。后泛指算账) 同本义。", "cites": [{"t": "会,合也。", "b": "《说文》"}, {"t": "会,岁计也。", "b": "《玉篇》"}, {"t": "会,大计也。然则零性算之为计,总合算之为会。", "b": "《孟子·万章下》正义"}, {"t": "凡场务、仓库出纳在官之物,皆月计,季考,岁会。", "b": "《日知录》卷二十四"}, {"t": "岁终,则会,唯王及后之服不会。", "b": "《周礼·天官》"}, {"t": "听出入以要会。", "b": "《周礼·小宰》。注:“月计曰要,岁计为会。”"}], "words": [{"w": "会事", "t": "统计事务"}, {"w": "会最", "t": "总计;汇总。"}]}, {"meaning": "会稽(kuàjī)。山地名,县名。在今浙江绍兴。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('487wx','杀','1','shā','木','6','','[{"pinyin": "shā", "defs": [{"meaning": "(形声。从殳,杀声。古字作“杀”,甲骨文字形,在人(大)的下方做上一个被剁的记号,表示杀。殳(shū):兵器。从殳表示与杀有关。本义:杀戮)。"}, {"meaning": "同本义。", "cites": [{"t": "殺,戮也。", "b": "《说文》"}, {"t": "武王胜殷杀纣。", "b": "《墨子·三辩》"}, {"t": "杀气浸盛。", "b": "《吕氏春秋·仲秋》"}, {"t": "为杀矢。", "b": "《考工记·冶氏》"}, {"t": "杀其君,虔于乾溪。", "b": "《谷梁传·昭公十三年》"}, {"t": "杀人以梃与刃,有以异乎?", "b": "《孟子·梁惠王上》"}, {"t": "子罕杀宋君而夺政。", "b": "《韩非子·外储说右下》"}, {"t": "设酒杀鸡作食。", "b": "陶潜《桃花源记》"}, {"t": "然得而腊之以为饵,可以已大风、挛踠、瘘、疠,去死肌,杀三虫。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "杀猪;杀鸡;杀戒", "t": "佛教指禁止杀生的戒律"}, {"w": "杀坏", "t": "杀死"}, {"w": "杀落", "t": "被杀;杀死"}, {"w": "杀坯", "t": "骂人话。该杀的东西"}, {"w": "杀鸡扯脖", "t": "杀鸡扯腿,杀鸡抹脖。形容十分情急的样子"}, {"w": "杀人灭口", "t": "怕走漏风声而将人处死。"}]}, {"meaning": "攻杀,激战。", "cites": [{"t": "二将合兵一处,大杀一阵。魏兵方退。", "b": "罗贯中《三国演义》"}], "words": [{"w": "杀并", "t": "厮杀,火并。"}]}, {"meaning": "凋落。", "cites": [{"t": "待到秋来九月八,我花开后百花杀。", "b": "黄巢《赋菊》"}], "words": [{"w": "风势稍杀;杀敛", "t": "万物凋落敛藏。"}]}, {"meaning": "败坏;衰败。", "cites": [{"t": "为报年来杀风景,连江梦雨不知春。", "b": "苏轼《次韵林子中春日新堤书事》"}], "words": [{"w": "杀人威风", "t": ""}]}, {"meaning": "旧称臣杀君,子杀父母为弑。", "cites": [{"t": "里克杀奚齐于次。", "b": "《左传·僖公九年》"}, {"t": "项羽为无道放杀其主。", "b": "《汉书·高帝纪》"}]}, {"meaning": "猎获物。", "cites": [{"t": "[众上献猎物科]禀王爷,众将献杀。", "b": "清·洪昇《长生殿》"}]}, {"meaning": "用在谓语后面,表示程度之深。", "cites": [{"t": "白杨多悲风,萧萧愁杀人。", "b": "《文选·古诗十九首·其十四》"}, {"t": "孩儿,痛杀我也。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "将他气杀也;笑杀人;杀死个", "t": "方言。死命地;拼命地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('488wx','合','1','gě hé','口','6','','[{"pinyin": "gě", "defs": [{"meaning": "容量单位, 市制十合为一升。", "cites": [{"t": "十合为升,十升为斗。", "b": "《汉书》"}]}]}, {"pinyin": "hé", "defs": [{"meaning": "(会意。从亼(jí),三面合闭,从口。本义:闭合,合拢)。"}, {"meaning": "同本义。", "cites": [{"t": "合,合口也。", "b": "《说文》"}, {"t": "公孙龙口呿而不合。", "b": "《庄子·秋水》"}]}, {"meaning": "引申为开合之称。", "cites": [{"t": "合则成体。", "b": "《庄子·达生》"}, {"t": "合盖隆起。", "b": "《后汉书·张衡传》"}, {"t": "四面竹树环合。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "绿树村边合。", "b": "唐·孟浩然《过故人庄》"}, {"t": "暝色已合。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "蚌合;合上书;合祛", "t": "开闭"}, {"w": "合喙", "t": "闭口"}, {"w": "合盘", "t": "犹合掌"}, {"w": "合瞑", "t": "闭目;闭目入睡。"}]}, {"meaning": "会聚,聚合。", "cites": [{"t": "于是乎合其州乡朋友婚姻。", "b": "《国语·楚语下》"}, {"t": "将合诸侯。", "b": "《周礼·秋官·司仪》"}, {"t": "离则复合,合则复离。", "b": "《吕氏春秋·大乐》"}, {"t": "齐桓公合诸侯。", "b": "《吕氏春秋·精谕》"}, {"t": "公子即合符。", "b": "《史记·魏公子列传》"}, {"t": "晋鄙合符。", "b": ""}, {"t": "合江夏战士。", "b": "《资治通鉴》"}, {"t": "五万兵难卒合。", "b": ""}, {"t": "卒与尸合。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "合众", "t": "集合众人"}, {"w": "合族", "t": "聚合全族的人"}, {"w": "合火", "t": "结伙,结伴"}, {"w": "合军", "t": "集结军队"}, {"w": "合散", "t": "聚合消散"}, {"w": "合绪", "t": "聚集在一起。"}]}, {"meaning": "适合。", "cites": [{"t": "合于桑林之舞。", "b": "《庄子·养生主》"}, {"t": "甚合孤心。", "b": "《资治通鉴》"}], "words": [{"w": "合式", "t": "合适;合意"}, {"w": "合中", "t": "适中"}, {"w": "合折儿", "t": "合适"}, {"w": "合景", "t": "与当时场面相适合,相般配"}, {"w": "合折", "t": "恰当;合乎心思;合适"}, {"w": "合他意思", "t": ""}]}, {"meaning": "匹配;配偶。", "cites": [{"t": "天作之合。", "b": "《诗·大雅·大明》"}, {"t": "得耦为合。", "b": "《周礼·媒氏》注"}, {"t": "岂合令郎君。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "合和", "t": "结婚姻之好;亲睦"}, {"w": "合姓", "t": "指结婚。男女两性合为一家"}, {"w": "合独", "t": "使鳏夫寡妇结成夫妻。"}]}, {"meaning": "和睦,和谐,融洽。", "cites": [{"t": "妻子好合,如鼓瑟琴。", "b": "《诗·小雅·常棣》"}, {"t": "合群者也。", "b": "《荀子·非十二子》。注:“合,谓和合群众也。”"}, {"t": "以比黄钟之宫适合。", "b": "《吕氏春秋·古乐》"}, {"t": "议事每不合。", "b": "宋·王安石《答司马谏议书》"}, {"t": "甚与孤合。", "b": "《资治通鉴》"}, {"t": "与宁南意合。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "不谋而合。", "b": "《广东军务记》"}], "words": [{"w": "合心", "t": "齐心;同心"}, {"w": "合情", "t": "和谐情感。"}]}, {"meaning": "盒子", "cites": [{"t": "以黑木合盛茶。", "b": "冯梦龙《古今谭概》"}]}, {"meaning": "与;向。", "cites": [{"t": "又不好合你再要。", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('489wx','兆','1','zhào','儿','6','','[{"pinyin": "zhào", "defs": [{"meaning": "(象形。大篆字形像龟甲受灼所生的裂痕。本义:卜兆,龟甲烧后的裂纹)。"}, {"meaning": "同本义。", "cites": [{"t": "兆卜,灼龟拆也。——兆,古文兆卜省。——《说文》", "b": ""}, {"t": "掌三兆卜之法。", "b": "《周礼·大卜》"}, {"t": "不占卦兆。", "b": "《淮南子·本经》"}, {"t": "卜之龟,卦兆得大横。", "b": "《史记》"}], "words": [{"w": "兆象", "t": "占卜时龟板上显示的征象"}, {"w": "兆文", "t": "据以卜占吉凶的龟甲裂纹"}, {"w": "兆卦", "t": "显示于卦象上的征兆"}, {"w": "兆梦", "t": "占梦,圆梦。"}]}, {"meaning": "征兆,预兆。", "cites": [{"t": "相阴阳,占祲兆。", "b": "《荀子》"}, {"t": "其兆既成,已在宫中。", "b": "《新唐书》"}], "words": [{"w": "兆相", "t": "预先显示的迹象"}, {"w": "兆见", "t": "征召显现。"}]}, {"meaning": "人民;百姓。", "cites": [{"t": "行不群以颠越兮,又众兆之所仇。", "b": "《楚辞·九章·惜诵》"}], "words": [{"w": "兆民", "t": "古称太子之民,后泛指众民,百姓。又称“兆人”、“兆姓”、“兆萌”、“兆蒙”、“兆庶”、“兆众”、“兆黎”、“兆灵”。"}]}, {"meaning": "数词。一百万;极言众多。", "cites": [{"t": "岂天地之大,于兆人万姓之中,独私其一人一姓乎。", "b": "明·黄宗羲《原君》"}], "words": [{"w": "兆物", "t": "兆类。万物"}, {"w": "兆亿", "t": "数词。极言众多。又指民众"}, {"w": "兆古", "t": "太古,远古。"}]}, {"meaning": "墓地,埋葬死人之处。", "cites": [{"t": "无入子兆。", "b": "《左传·哀公二年》"}, {"t": "兆五帝于四郊。", "b": "《周礼·春官·小宗伯》"}, {"t": "吾力能改葬,当葬汝于先人之兆。", "b": "韩愈《祭十二郎文》"}], "words": [{"w": "兆域", "t": "墓地四周的疆界。亦以称“墓地”。"}]}, {"meaning": "开始。", "cites": [{"t": "能布其德,而兆其谋。", "b": "《左传·哀公元年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('490wx','企','1','qǐ','人','6','','[{"pinyin": "qǐ", "defs": [{"meaning": "(会意。从人,从止。甲骨文字形,上面是一个人,下面是“止”(脚),表示这个人在踮起后脚跟,有企立、企足的意思。本义:踮起脚跟)。"}, {"meaning": "同本义。", "cites": [{"t": "企,举踵也。", "b": "《说文》"}, {"t": "企者不立。", "b": "《老子》"}, {"t": "日夜企而望归。", "b": "《汉书·高帝纪》"}, {"t": "渠黄不能企其景。", "b": "郭璞《江赋》"}], "words": [{"w": "企望", "t": "举起脚跟而望"}, {"w": "企仰", "t": "踮起脚来仰望"}, {"w": "企足", "t": "踮起脚。"}]}, {"meaning": "立,站立。", "cites": [{"t": "鸟企山峙。", "b": "三国魏·何晏《景福殿赋》"}], "words": [{"w": "企予", "t": "踮起脚后跟站着"}, {"w": "企立", "t": "站立。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('491wx','众','1','zhòng','人','6','','[{"pinyin": "zhòng", "defs": [{"meaning": "(会意。“众”从三人。“三”表示众多。“众”表示众人站立。“衆”,甲骨文字形。象许多人在烈日下劳动。本义:众人、大家)。"}, {"meaning": "同本义。", "cites": [{"t": "人三为众。", "b": "《国语·周语》"}, {"t": "坤为众。", "b": "《易·说卦》"}, {"t": "大师之礼用众也,大均之礼恤众也,大田之礼简众也,大役之礼任众也,大封之礼合众也。", "b": "《周礼·大宗伯》"}, {"t": "安土重居,谓之众庶。", "b": "《后汉书·杨终传》"}, {"t": "庸众而野。", "b": "《荀子·脩身》。注:“众,众人也。”"}, {"t": "众恶之,必察焉。", "b": "《论语·卫灵公》"}, {"t": "众怒难犯。", "b": "《左传·襄公十年》"}, {"t": "则众何为而不汹汹然?", "b": "王安石《答司马谏议书》"}, {"t": "此教我先威众耳。", "b": "《史记·陈涉世家》"}, {"t": "群疑满服,众难塞胸。", "b": "诸葛亮《后出师表》"}, {"t": "激众愤。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "吾村之众。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "又。", "cites": [{"t": "众皆感奋。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "率众袭之。", "b": ""}], "words": [{"w": "众喙", "t": "众人的闲言碎语"}, {"w": "众口嚣嚣", "t": "众人吵吵嚷嚷"}, {"w": "众怨之的", "t": "大家怨恨的目标"}, {"w": "众力", "t": "众人之力"}, {"w": "众口", "t": "众人的言论"}, {"w": "众夫", "t": "众人;一般人"}, {"w": "众兆", "t": "众人"}, {"w": "众目", "t": "众人的眼睛"}, {"w": "众心", "t": "众人之心"}, {"w": "听众;观众;群众;会众", "t": "到会的人"}, {"w": "当众", "t": "当着大家"}, {"w": "民众", "t": "人民大众"}, {"w": "公众", "t": "社会上大多数的人"}, {"w": "万众", "t": "大众。"}]}, {"meaning": "指诸事,万事。", "cites": [{"t": "政事失其施,加于身而错于前,凡众之动失其宜。", "b": "《礼记·仲尼燕居》"}], "words": [{"w": "众名", "t": "万物之名"}, {"w": "众有", "t": "万物"}, {"w": "众念", "t": "万念"}, {"w": "众物", "t": "万物;诸物"}, {"w": "众圣", "t": "诸圣人。"}]}, {"meaning": "指百官;群臣。", "cites": [{"t": "天子之五官曰司徒、司马、司空、司士、司寇,典司五众。", "b": "《礼记》"}], "words": [{"w": "众士", "t": "贵臣以外诸臣。古代泛指诸侯臣僚,各级官吏"}, {"w": "众臣", "t": "贵臣身份以外之臣。即众士。"}]}, {"meaning": "兵;军队。亦指丁壮可为兵者。", "cites": [{"t": "率数万之众。(众指军队。)", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "众力", "t": "特指兵力"}, {"w": "众卒", "t": "一般兵士。"}]}, {"meaning": "殷、周从事农业生产的奴隶,或管理奴隶的人。", "cites": [{"t": "格!尔众庶,悉听朕言。", "b": "《书·汤誓》"}]}, {"meaning": "佛家语。用以指教徒人数。", "cites": [{"t": "一行三众,辞别高老及众亲友,投西而去。", "b": "《西游记》"}], "words": [{"w": "众性", "t": "佛教语。众生"}, {"w": "众生", "t": "泛指人和一切动物;指人以外的各种动物。"}]}, {"meaning": "众多,与“寡”、“少”相对。", "cites": [{"t": "今寇众我寡,难以持久。", "b": "《资治通鉴·赤壁之战》"}, {"t": "师克在和,不在众。", "b": "《左传·桓公十一年》"}, {"t": "树成荫而众鸟息焉。", "b": "《荀子·劝学》"}, {"t": "贼能且众。", "b": "明·魏禧《大铁椎传》"}]}, {"meaning": "又。", "cites": [{"t": "众贼环而进。", "b": ""}, {"t": "众宾团坐。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "众妙毕备。", "b": ""}], "words": [{"w": "众峰", "t": "许多山峰"}, {"w": "众工", "t": "许多工匠"}, {"w": "众支", "t": "众多的支系"}, {"w": "众小", "t": "众多小国"}, {"w": "众卉", "t": "百草"}, {"w": "众口纷纭", "t": "人多嘴杂,论论纷纷"}, {"w": "众毛飞骨", "t": "众多的众物能掀起重物"}, {"w": "众巧", "t": "众多的巧匠"}, {"w": "众矢之的", "t": "许多箭射的靶子。比喻众人攻击的目标。"}]}, {"meaning": "广泛;普遍。", "cites": [{"t": "是非容貌之患也,闻见之不众,议论之卑尔。", "b": "《荀子》。杨倞注:“闻见不广,议论不高。”"}], "words": [{"w": "众妙", "t": "一切深奥玄妙的的道理"}, {"w": "众医", "t": "一般医生;庸医。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('492wx','爷','1','yé','父','6','','[{"pinyin": "yé", "defs": [{"meaning": "(形声。从父,耶声。简体字“卩”只是个符号。本义:父亲)。"}, {"meaning": "同本义。也作“耶”。", "cites": [{"t": "愿为市鞍马,从此替爷征。", "b": "《木兰诗》"}, {"t": "卷卷有爷名。", "b": ""}, {"t": "旦辞爷娘去。", "b": ""}, {"t": "爷娘闻女来。", "b": ""}], "words": [{"w": "爷娘皇天", "t": "呼爹叫娘,嚎天喊地。"}]}, {"meaning": "爷爷。"}, {"meaning": "祖父——多叠用。", "cites": [{"t": "爷爷会织布、会种田、还会养牛", "b": ""}]}, {"meaning": "旧时对主人、上官或尊贵者的称呼 。如王爷;相爷;老爷;少爷。"}, {"meaning": "自矜之称。", "cites": [{"t": "祥子明知道上工辞工都是常有的事,此处不留爷,自有留爷处。", "b": "老舍《骆驼祥子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('493wx','伞','1','sǎn','人','6','','[{"pinyin": "sǎn", "defs": [{"meaning": "(繖为傘的古字)。"}, {"meaning": "特指伞盖。长柄,圆顶,伞面边缘有流苏下垂,也称马伞。古代仪仗的一种,用不同颜色区别品级的高下。知府以上用黄色,知州以下用蓝色。", "cites": [{"t": "服素衣,持白伞白幡。", "b": "《魏书·裴延传》"}, {"t": "人只看见他大门口,今日是一把黄伞的轿子来…。", "b": "《儒林外史》"}], "words": [{"w": "伞子", "t": "古代仪仗队里的执伞者"}, {"w": "伞扇", "t": "古代的两种仪仗物。均有长柄,上端分别为伞形和扇形"}, {"w": "伞竿", "t": "伞柄"}, {"w": "伞檐", "t": "张开的伞面的外沿。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('494wx','创','1','chuāng chuàng','刂','6','','[{"pinyin": "chuāng", "defs": [{"meaning": "(指事。从刀,仓声。金文,象一个躺着的人,手上脚上都有小竖,表示受了创伤,是个指事字。本义:创伤,伤口)。"}, {"meaning": "同本义。", "cites": [{"t": "刅,伤也。", "b": "《说文》"}, {"t": "创钜者其日久。", "b": "《礼记·三年问》"}, {"t": "项王身亦被十八余创。", "b": "《史记·项羽本纪》"}, {"t": "秦王复击轲,被八创。", "b": "《战国策·燕策》"}, {"t": "不呼则杖其背,尽创。", "b": "高启《书博鸡者事》"}], "words": [{"w": "身受重创;创痕", "t": "伤痕"}, {"w": "创病", "t": "伤病"}, {"w": "创残", "t": "伤残"}, {"w": "创瘢", "t": "伤疤。"}]}, {"meaning": "损伤;伤害。", "cites": [{"t": "欲令创咸面目。", "b": "《汉书·薛宣传》"}, {"t": "雄骏不创寿于旗幢。", "b": "《韩非子·大体》"}], "words": [{"w": "创刃", "t": "为刀剑之类所伤"}, {"w": "创毒", "t": "伤害"}, {"w": "创残", "t": "伤残。"}]}]}, {"pinyin": "chuàng", "defs": [{"meaning": "始造。", "cites": [{"t": "创,始也。", "b": "《广雅》"}, {"t": "以创制天下。", "b": "《国语·周语》。注:“造也。”"}, {"t": "君子创业垂统为可继也。", "b": "《孟子》"}, {"t": "华下之人或助之材,以创是庵而居之。", "b": "顾炎武《复庵记》"}, {"t": "先帝创业未半而中道崩殂。", "b": "诸葛亮《出师表》"}], "words": [{"w": "首创;草创;创行", "t": "首创并施行"}, {"w": "创垂", "t": "开创业绩"}, {"w": "创基", "t": "创立基业"}, {"w": "暂创一室;创造", "t": "建造;修造"}, {"w": "创建", "t": ""}]}, {"meaning": "惩治。", "cites": [{"t": "矛创若时。", "b": "《书·益稷》。传:“惩也。”"}, {"t": "羌虏破散创艾。", "b": "《汉书·冯奉世传》。注:“谓惩惧也。”"}], "words": [{"w": "创惩", "t": "惩戒。"}]}, {"meaning": "撰写。", "cites": [{"t": "裨谌草创之。", "b": "《论语》"}], "words": [{"w": "创述", "t": "创造;著述"}, {"w": "创纂", "t": "编造"}, {"w": "创撰", "t": "杜撰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('495wx','肌','1','jī','月','6','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从肉,几声。本义:肌肉)。"}, {"meaning": "同本义(先秦时期,“肌”表示人的肉;“肉”表示禽兽的肉)。", "cites": [{"t": "肌,肉也。", "b": "《说文》"}, {"t": "度制,肌肤血气之情也。", "b": "《春秋繁露》"}, {"t": "病在肌肤。", "b": "《韩非子·喻老》"}, {"t": "乃割皮解肌,诀脉结筋。", "b": "《史记·扁鹊列传》"}], "words": [{"w": "肌肥骨重", "t": "形容身躯壮实魁悟"}, {"w": "肌肌", "t": "肌肉强直的样子"}, {"w": "肌肪", "t": "肌肤"}, {"w": "肌革", "t": "肌肤,皮肉"}, {"w": "肌骨", "t": "肌肉与骨骼。"}]}, {"meaning": "引申指皮肤。", "cites": [{"t": "肌理细腻骨肉匀。", "b": "杜甫《丽人行》"}, {"t": "一肌一容。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "肌肤之所浸渍。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "肌衄", "t": "皮肤出血。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('496wx','肋','1','lèi lē','月','6','','[{"pinyin": "lèi", "defs": [{"meaning": "(形声。从肉,力声。本义:肋骨)。"}, {"meaning": "许多成对的骨质或部分为软骨的杆状体之一,起着加固大多数脊椎动物驱体侧壁并保护内脏的作用,通常其背部一端与脊柱相接合,而腹部一端有时也以形态学上认为是非骨化部分的肋软骨形式与胸骨连接,对哺乳动物来说都长在或几乎都长在胸部,人身上一般有12对 。", "cites": [{"t": "肋,肋骨也。", "b": "《说文》"}, {"t": "肋,勒也,所以捡勒五脏也。", "b": "《释名·释形体》"}], "words": [{"w": "肋下", "t": "腋下"}, {"w": "肋肢", "t": "腋下,胳肢窝"}, {"w": "肋窝", "t": "也作“肋罗”。胸前腋下的部位。通称胳肢窝。"}]}]}, {"pinyin": "lē", "defs": [{"meaning": "衣裳肥大，不整洁。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('497wx','朵','1','duǒ','木','6','','[{"pinyin": "duǒ", "defs": [{"meaning": "(象形。小篆字形,下面是“木”(树),上面象花实之类。本义:花朵。朶为朵的俗字)。"}, {"meaning": "树木枝叶花实下垂貌。今指花朵,即植物的花或苞。", "cites": [{"t": "朶,树木花朶朶也。", "b": "《说文》"}], "words": [{"w": "朵云", "t": "对他人书信的敬称"}, {"w": "朵作千叶", "t": "花瓣极多。"}]}, {"meaning": "花朵及花朵状物的计量单位。", "cites": [{"t": "千朵万朵压枝低。", "b": "唐·杜甫《江畔独步寻花》"}], "words": [{"w": "一朵花;两朵云", "t": ""}]}, {"meaning": "动。", "cites": [{"t": "我将观其往事之卒而朵焉。", "b": "《马王堆汉墓帛书》"}], "words": [{"w": "朵颐", "t": "动腮颊,吃东西的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('498wx','杂','1','zá','木','6','','[{"pinyin": "zá", "defs": [{"meaning": "(形声。从衣,集声。本义:五彩相合)。"}, {"meaning": "同本义。", "cites": [{"t": "画绘之事,杂五色。", "b": "《周礼·考工记》"}]}, {"meaning": "混合;搀杂。", "cites": [{"t": "故先王以土与金木水火杂,以成百物。", "b": "《国语·郑语》"}, {"t": "彼此错杂。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "杂烩菜", "t": "将各种剩菜合并在一起的菜淆"}, {"w": "夹杂", "t": "搀杂"}, {"w": "杂就", "t": "参杂而成"}, {"w": "混杂", "t": "混合搀杂。"}]}, {"meaning": "聚会;聚集。", "cites": [{"t": "杂,聚也。", "b": "《广雅》"}, {"t": "四方来杂,远乡皆至。", "b": "《吕氏春秋》"}], "words": [{"w": "杂物", "t": "聚集事物。"}]}, {"meaning": "驳杂不纯。", "cites": [{"t": "夹岸数百步,中无杂树。", "b": "晋·陶潜《桃花源记》"}]}, {"meaning": "众多。", "cites": [{"t": "杂然相许。", "b": "《列子·汤问》"}], "words": [{"w": "杂沓", "t": "众多而纷杂的样子"}, {"w": "杂袭", "t": "众多的样子"}, {"w": "杂玩", "t": "各种玩物。"}]}, {"meaning": "交错,交会。", "cites": [{"t": "嘈嘈切切错杂弹。", "b": "唐·白居易《琵琶行(并序)》诗"}, {"t": "杂植兰桂竹木。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "都;共同。", "cites": [{"t": "杂曰:“投诸渤海之尾,隐土之北。”", "b": "《列子·汤问》"}]}, {"meaning": "旧时等外的小官为杂职,如清代九品未入流之类或统称为佐杂。", "cites": [{"t": "听我将、弁、参、杂管领。", "b": "清·严如熤《苗防备览要略》"}]}, {"meaning": "传统戏曲角色名。元杂剧、明清传奇以至京剧里的“杂”,一般扮演杂差、百姓等人物。", "cites": [{"t": "杂绯衣扮秦国引院子梅香各乘车行上。", "b": "《长生殿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('499wx','危','1','wēi','厄','6','','[{"pinyin": "wēi", "defs": [{"meaning": "(会意。小篆字形上面是人,中间是山崖,下面腿骨节形。人站在山崖上,表示很高。本义:在高处而畏惧)。"}, {"meaning": "同本义。", "cites": [{"t": "危,在高而惧也。", "b": "《说文》"}, {"t": "决危而美名者。", "b": "《鬼谷子》。注:“山高也。”"}, {"t": "榣木不生危。", "b": "《国语·晋语》。注:“高险也。”"}, {"t": "高而不危。", "b": "《孝经》。郑注:“殆也。”"}]}, {"meaning": "恐惧;忧惧。", "cites": [{"t": "窃为君危之。", "b": "《战国策·西周策》"}], "words": [{"w": "人人自危;危心", "t": "心存戒惧"}, {"w": "危怖", "t": "恐惧不安"}, {"w": "危栗", "t": "恐惧战栗"}, {"w": "危气", "t": "气馁;危惧"}, {"w": "危悚", "t": "危悰,危惧"}, {"w": "危视", "t": "惊视"}, {"w": "危睇", "t": "俯视而感到惊恐。"}]}, {"meaning": "威胁,摧败。", "cites": [{"t": "能危山东者,强秦也。", "b": "《战国策·齐策一》"}]}, {"meaning": "使危险;伤害;损伤。", "cites": [{"t": "今先生之立法术,设度数,臣窃以为危于身而殆于躯。", "b": "《韩非子·问田》"}, {"t": "危士臣,构怨于诸侯。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "危国", "t": "危害国家。"}]}, {"meaning": "败亡,灭亡。", "cites": [{"t": "魏必危。", "b": "《战国策·秦策四》"}]}, {"meaning": "怀疑,疑虑。", "cites": [{"t": "夫妻相冒,日以相危。", "b": "《吕氏春秋·明理》"}]}, {"meaning": "高。", "cites": [{"t": "危冠广袖楚宫妆,独步闲庭逐夜凉。", "b": "唐·高适《听张立本女吟》"}, {"t": "危楼高百尺,手可摘星辰。", "b": "李白《夜宿山寺》"}, {"t": "断壁危楼。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "危楼", "t": "高楼"}, {"w": "危巧", "t": "高峻而精巧"}, {"w": "危邪", "t": "高而偏斜"}, {"w": "危岑", "t": "高峻的山峰"}, {"w": "危砌", "t": "高墙"}, {"w": "危柯", "t": "高枝"}, {"w": "危亭", "t": "耸立于高处的亭子"}, {"w": "危冠", "t": "古时的高冠"}, {"w": "危台", "t": "高台。"}]}, {"meaning": "危险; 危难。", "cites": [{"t": "法不信,则君行危矣。", "b": "《韩非子·有度》"}, {"t": "亡弗不能存,危弗能安。", "b": "《韩非子·十过》"}, {"t": "危而不持。", "b": "《论语·李氏》"}, {"t": "安危不可知。", "b": "《汉书·李广苏建传》"}, {"t": "危难之间。", "b": "诸葛亮《出师表》"}, {"t": "危急存亡。", "b": ""}], "words": [{"w": "危地", "t": "危险的地方"}, {"w": "危急存亡之秋", "t": "危险急迫到了决定生死存亡的关头"}, {"w": "危道", "t": "危险的措施"}, {"w": "危行", "t": "危险的行动"}, {"w": "危危", "t": "极其危险"}, {"w": "危困", "t": "危急困穷"}, {"w": "危脆", "t": "危险脆弱。"}]}, {"meaning": "很陡峭的。", "cites": [{"t": "泉声咽危石,日色冷青松。", "b": "唐·王维《过香积寺》"}], "words": [{"w": "危径", "t": "险峻的山路"}, {"w": "危狭", "t": "险峻狭窄"}, {"w": "危峭", "t": "高峻峭拔"}, {"w": "危峨", "t": "高峻的山岭"}, {"w": "危峰", "t": "高峻的山峰"}, {"w": "危崖", "t": "高峻的悬崖"}, {"w": "危朗", "t": "高峻而开朗"}, {"w": "危峦", "t": "险峻的山峦"}, {"w": "危壁", "t": "陡峭的山崖。"}]}, {"meaning": "特指人将死。", "cites": [{"t": "形盛脉细,少气不足以息者危。", "b": "《素问》。王冰注:“危者,言其近死犹有生者也。”"}], "words": [{"w": "病危;垂危", "t": ""}]}, {"meaning": "绷得紧;强劲。", "cites": [{"t": "丰肉而短,宽缓以荼,若是者为之危弓,危弓为之安矢。", "b": "《周礼》"}]}, {"meaning": "端正。", "cites": [{"t": "危然处其所而反其性。", "b": "《庄子》"}], "words": [{"w": "危坐", "t": "端坐;正坐。"}]}, {"meaning": "不正。", "cites": [{"t": "故薄薄之地,不得履之,非地不安也,危足无所履者,凡在言也。", "b": "《荀子》"}]}, {"meaning": "屋脊。", "cites": [{"t": "痤(范痤)因上屋骑危。", "b": "《史记·魏世家》"}]}, {"meaning": "艰难困苦。", "cites": [{"t": "十年携手共艰危,以沫相濡亦可哀。", "b": "鲁迅《集外集拾遗补编》"}]}, {"meaning": "几乎;差点儿。", "cites": [{"t": "我危得之。", "b": "《汉书》。颜师古注:孟康曰:“危,殆也。我殆得为天子也。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('500wx','旬','1','xún','日','6','','[{"pinyin": "xún", "defs": [{"meaning": "(会意。从勹(bāo)日。甲骨文,上为交叉记号,表示由此开始,后来引长内曲,表示回环周遍。金文又加“日”。本义:十日。古代天干纪日,每十日周而复始,称一旬)。"}, {"meaning": "同本义。", "cites": [{"t": "旬,徧也。十日为旬。", "b": "《说文》"}, {"t": "虽旬玄咎。", "b": "《易·丰》"}, {"t": "三百有六旬有六日。", "b": "《书·尧典》"}, {"t": "旬终则令正日成。", "b": "《周礼》"}, {"t": "筮旬有一日。", "b": "《仪礼·少牢礼》"}, {"t": "旬之外曰远某日。", "b": "《礼记·曲礼》"}, {"t": "围梁数旬,则梁可拔。", "b": "《韩非子·初见秦》"}], "words": [{"w": "兼旬", "t": "两个十天"}, {"w": "旬期", "t": "十天"}, {"w": "旬修", "t": "十天之中所作所为"}, {"w": "旬首", "t": "一旬之始"}, {"w": "旬浃", "t": "满十天"}, {"w": "旬宴", "t": "古天子旬假日赐群臣之宴。"}]}, {"meaning": "十岁为一旬,多指人的年龄。", "cites": [{"t": "且喜同年满七旬。", "b": "白居易《偶吟自慰兼呈梦得》"}], "words": [{"w": "八旬老母", "t": ""}]}, {"meaning": "巡视;游历。", "cites": [{"t": "王命台虎,来旬来宣。", "b": "《诗·大雅·江汉》"}]}, {"meaning": "光阴;时间。", "cites": [{"t": "量寸旬,涓吉日,陟中坛,即帝位。", "b": "《文选·左思·魏都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('501wx','旨','1','zhǐ','日','6','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(会意。甲骨文字形。上象“匕”(bǐ)即匙形,下面是口,以匙入口,表示味道好。”“口”隶变为“日”。《说文》:“从甘,匕声。本义:味美)。"}, {"meaning": "同本义。", "cites": [{"t": "旨,美也。从甘,匕声。", "b": "《说文》"}, {"t": "既饮旨酒。", "b": "《诗·鲁颂·泮水》"}, {"t": "告旨。", "b": "《仪礼·乡饮礼》"}, {"t": "虽有嘉肴,弗食,不知其旨也。", "b": "《礼记·学记》"}], "words": [{"w": "旨甘", "t": "美好的食物"}, {"w": "旨味", "t": "美味"}, {"w": "旨肴", "t": "美味的菜肴。"}]}, {"meaning": "美好。", "cites": [{"t": "垂功烈而不刊,不亦旨哉!", "b": "柳宗元《与李睦州论服气书》"}]}, {"meaning": "美味的食品。", "cites": [{"t": "我有旨畜,亦以御冬。", "b": "《诗·邶风·谷风》"}, {"t": "食旨不甘,闻乐不乐。", "b": "《论语·阳货》"}], "words": [{"w": "甘旨", "t": "美味的食物"}, {"w": "旨蓄", "t": "贮藏的美好食品"}, {"w": "旨嘉", "t": "美酒佳肴。"}]}, {"meaning": "意思;意义。", "cites": [{"t": "妙达此旨,始可言文。", "b": "《宋书·谢灵运传论》"}], "words": [{"w": "主旨", "t": "主要的意义、用意或目的"}, {"w": "大旨", "t": "主要的意思"}, {"w": "宏旨", "t": "大旨;要旨"}, {"w": "微旨", "t": "不是明说,而是含蓄表达出来的意思。"}]}, {"meaning": "意图;宗旨。", "cites": [{"t": "其旨远,其辞文。", "b": "《易·系辞下》"}, {"t": "肃宣权旨,论天下事势,致殷勤之意。", "b": "《资治通鉴》"}], "words": [{"w": "宗旨", "t": "主要的目的和意图"}, {"w": "旨譬", "t": "用意和取譬"}, {"w": "旨统", "t": "旨趣的系统。"}]}, {"meaning": "长官的命令。", "cites": [{"t": "初举孝廉,再迁圉令,以礼理人,以德化俗。…今承旨而杀之,是逆天心,顺府意也,其罚重矣。", "b": "《后汉书》"}]}, {"meaning": "皇帝的意见,命令。", "cites": [{"t": "旨,凡天子谕告臣民曰诏旨,下承上曰奉旨。", "b": "《正字通》"}], "words": [{"w": "传旨;听旨", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('502wx','旭','1','xù','日','6','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从日,九声。本义:太阳初出的样子) 同本义。", "cites": [{"t": "旭,日旦出貌。", "b": "《说文》"}, {"t": "旭日始旦。", "b": "《诗·邶风·匏有苦叶》"}, {"t": "方出旭旭。", "b": "《太玄·从》。注:“未明之间。”"}, {"t": "欢来苦夕短,已复至天旭。", "b": "晋·陶潜《归园田居》"}], "words": [{"w": "旭旭", "t": "日将出的样子。"}]}, {"meaning": "光。", "cites": [{"t": "玄门一掩,寒灯无旭。", "b": "唐·佚名《处士张兴墓志铭》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('503wx','负','1','fù','贝','6','','[{"pinyin": "fù", "defs": [{"meaning": "(会意。从人,从贝。本义:恃,即依恃,凭仗)。"}, {"meaning": "同本义。", "cites": [{"t": "负,恃也。从人守贝,有所恃也。", "b": "《说文》"}, {"t": "秦贪,负其强。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "负势竞上,互相轩邈。", "b": "《艺文类聚·吴均·与朱元思书》"}, {"t": "昔秦人负恃其众,贪于土地,逐我诸戎。", "b": "《左传·襄公十四年》"}, {"t": "其异姓负彊而动者,汉已幸胜之矣。", "b": "汉·贾谊《治安策》"}, {"t": "守自负年德,易之。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "背负。以背驮物。引申为负担。", "cites": [{"t": "命夸娥氏二子负二山,一厝朔东,一厝雍南。", "b": "《列子·汤问》"}, {"t": "颁白者不负戴于道路矣。", "b": "《孟子·梁惠王上》"}, {"t": "负晋侯出诸厕。", "b": "《左传·成公十年》"}], "words": [{"w": "负羽", "t": "背负弓箭"}, {"w": "负弩", "t": "身背弓矢"}, {"w": "负鼓", "t": "背着鼓"}, {"w": "负薪", "t": "背负薪柴"}, {"w": "负戴", "t": "以背负物,以头顶物"}, {"w": "负樵", "t": "背柴。"}]}, {"meaning": "背倚,背靠着。", "cites": [{"t": "有众逐虎,虎负隅,莫之敢撄。", "b": "《孟子·尽心下》"}, {"t": "背负青天而莫之千阏者。", "b": "《庄子·逍遥游》"}], "words": [{"w": "负河", "t": "依傍黄河"}, {"w": "负暄", "t": "冬天晒太阳取暖"}, {"w": "负立", "t": "靠墙站立"}, {"w": "负海", "t": "背靠大海"}, {"w": "负席", "t": "背对席位。"}]}, {"meaning": "抱持。", "cites": [{"t": "徐衍负石入海。", "b": "邹阳《狱中上梁书》"}], "words": [{"w": "负羁手执马络头;负锡", "t": "手持禅杖"}, {"w": "负托", "t": "抱恃。"}]}, {"meaning": "抱有;具有。", "cites": [{"t": "虚负凌云万丈志,一生襟袍未曾开。", "b": "崔珏《哭李商隐》"}, {"t": "少年负志气。", "b": "唐·刘禹锡《学阮公体》"}]}, {"meaning": "承担,担当。", "cites": [{"t": "均之二策,宁许以负秦曲。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "负责任;负输", "t": "装载运输"}, {"w": "负舟", "t": "承载舟船"}, {"w": "负任", "t": "担负重任"}, {"w": "负官", "t": "身负官职。"}]}, {"meaning": "背弃,违背。", "cites": [{"t": "相如度秦王虽斋,决负约不偿城。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "田荣者,数负项梁。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "又恶负约。", "b": ""}], "words": [{"w": "负诺", "t": "违背诺言"}, {"w": "负义", "t": "背弃恩义"}, {"w": "负心妄加", "t": "忘恩负义,反咬一口"}, {"w": "负盟", "t": "背弃盟约"}, {"w": "负违", "t": "违背,违反。"}]}, {"meaning": "欠债;欠缺;缺少。", "cites": [{"t": "仆少负不羁之才。", "b": "汉·司马迁《报任安书》"}, {"t": "通家尚负责(债)数钜万。", "b": "《汉书·邓通传》"}], "words": [{"w": "负进", "t": "欠债"}, {"w": "负券", "t": "负债字据"}, {"w": "负偿", "t": "欠债。"}]}, {"meaning": "失败。", "cites": [{"t": "不知彼而知己,一胜一负。", "b": "《孙子·谋攻》"}, {"t": "遇敌处战则必北。", "b": "《荀子·议兵》"}, {"t": "以决胜负。", "b": "《资治通鉴》"}, {"t": "胜负之数,存亡之理,当与秦相较,或未易量。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "负败", "t": "失败;受挫折"}, {"w": "负失", "t": "损失。"}]}, {"meaning": "蒙受。", "cites": [{"t": "且负下未易居。", "b": "汉·司马迁《报任安书》"}, {"t": "负屈无处诉,哀号动穹苍。", "b": "刘基《赠周宗道》"}]}, {"meaning": "又如:负屈衔冤(受到冤屈);负讥(受到讥刺);负谤(蒙受责难);负霜(受霜;带霜);负忧(遭受忧患)。"}, {"meaning": "辜负;对不起人。", "cites": [{"t": "是犯乃死,重负国。", "b": "《汉书·李广苏建传》"}, {"t": "客果有能也,吾负之。", "b": "《战国策·齐策四》"}, {"t": "吾上恐负朝廷,下恐愧吾师也。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "臣诚恐见欺于王而负赵,故令人持璧归。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "又如:负国(对不起国家);负恩(忘恩;背恩);负负(对不起、对不起);负咎(抱愧)。"}, {"meaning": "赔偿;补偿。", "cites": [{"t": "其不备,出者负之;其赢者,入之。", "b": "《睡虎地秦墓竹简》"}, {"t": "宋之富贾有监止子者,与人争买百金之璞玉,因佯失而毁之,负其百金。", "b": "《韩非子·说林下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('504wx','匈','1','xiōng','勹','6','','[{"pinyin": "xiōng", "defs": [{"meaning": "(形声。从勹,凶声。勹(bāo),裹。本义:胸膛)。"}, {"meaning": "“胸”的古字。", "cites": [{"t": "匈,膺也。", "b": "《说文》。字亦作胷、作胸"}, {"t": "胸满。", "b": "《素问·腹中论》"}, {"t": "贯匈国。其为人胸有窍。", "b": "《海内南经》"}]}, {"meaning": "心胸;胸怀。", "cites": [{"t": "吾素刚急,有匈中气,不可不顺也。", "b": "《资治通鉴》"}], "words": [{"w": "匈臆", "t": "胸怀。"}]}, {"meaning": "胸部。", "cites": [{"t": "项羽大怒,伏弩射中汉王,汉王伤匈。", "b": "《史记》"}]}, {"meaning": "称匈奴。亦泛称北方少数民族。", "cites": [{"t": "又匈虏一败,或当惧而修德,结怨于我,为患不细。", "b": "《旧唐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('505wx','名','1','míng','口','6','','[{"pinyin": "míng", "defs": [{"meaning": "(会意。甲骨文字形。从口夕。本义:自己报出姓名;起名字)。"}, {"meaning": "同本义。", "cites": [{"t": "名,自命也。", "b": "《说文》"}, {"t": "黄帝正名百物。", "b": "《礼记·祭法》"}, {"t": "名之曰幽厉。", "b": "《孟子》"}, {"t": "名公器也。", "b": "《庄子·天运》"}, {"t": "秦氏有好女,自名为罗敷。", "b": "《乐府诗集》"}, {"t": "以故其后名之曰“褒禅”。", "b": "宋·王安石《游褒禅山记》"}, {"t": "名之者谁。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "自名“蟹壳青”。", "b": "《聊斋志异·促织》"}], "words": [{"w": "名品", "t": "辨明品级。"}]}, {"meaning": "称说;说出。", "cites": [{"t": "不能名其一处。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "不可名状;莫名其妙;名状", "t": "形容描述。"}]}, {"meaning": "出名,有名声。", "cites": [{"t": "山不在高,有仙则名。", "b": "刘禹锡《陋室铭》"}]}, {"meaning": "以私人名义占有。", "cites": [{"t": "不名一钱。", "b": "王充《论衡》"}]}, {"meaning": "明白。", "cites": [{"t": "是以圣人不行而知,不见而名。", "b": "《老子·四十七章》"}]}, {"meaning": "名字;名称。", "cites": [{"t": "请问名。", "b": "《仪礼·士昏礼》"}, {"t": "记百名以上书于策。", "b": "《仪礼·聘礼》"}, {"t": "慎器与名。", "b": "《左传·昭公三十二年》。注:“爵号也。”"}, {"t": "大行受大名,细行受细名。", "b": "《周书·谥法》"}, {"t": "军书十二卷,卷卷有爷名。", "b": "《木兰诗》"}], "words": [{"w": "名榜", "t": "名帖"}, {"w": "名物", "t": "物品的名称及形状"}, {"w": "名纸", "t": "名片"}, {"w": "名象", "t": "泛指称谓、法制、器物等。名,指称;象,法象。"}]}, {"meaning": "名声,名誉,名望。", "cites": [{"t": "故西门豹为邺令,名闻天下。", "b": "《史记·滑稽列传》"}, {"t": "名达于缙绅间。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "名义。", "cites": [{"t": "名曰馆伴。(名义上是招待使者的官员。)", "b": "宋·文天祥《后序》"}], "words": [{"w": "名分", "t": "名义"}, {"w": "名田", "t": "以私名占有田地"}, {"w": "名色", "t": "名义。"}]}, {"meaning": "有名的,著名的;名贵的。", "cites": [{"t": "又患无硕师名人与游。", "b": "宋濂《送东阳马生序》"}, {"t": "有仙则名。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "名姝", "t": "著名的美女"}, {"w": "名宿", "t": "有名的老前辈"}, {"w": "名素", "t": "一向有名望的人"}, {"w": "名族", "t": "著名的家族;名字姓氏"}, {"w": "名花", "t": "名贵的花。俗称美女、名妓为名花"}, {"w": "名贵", "t": "著名而显贵的人;贵重难得的器物"}, {"w": "名都", "t": "著名的都市。"}]}, {"meaning": "大的。", "cites": [{"t": "因名山升中于天。", "b": "《礼记·礼器》。注:“犹大也。”"}, {"t": "环如因而赂一名都。", "b": "《战国策·秦策》。注:“大也。”"}], "words": [{"w": "名山", "t": "大山"}, {"w": "名川", "t": "大河"}, {"w": "名藩", "t": "重要的大藩镇"}, {"w": "名器", "t": "大器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('506wx','各','1','gě gè','口','6','','[{"pinyin": "gě", "defs": [{"meaning": "特别,与众不同。", "cites": [{"t": "各,异词也。从口攵,会意。攵者,有行而止之,不相听也。", "b": "《说文》"}, {"t": "各,词也。", "b": "《广雅》"}, {"t": "亦各,不一之辞。", "b": "《诗·载驰》疏"}], "words": [{"w": "这人很各", "t": ""}]}]}, {"pinyin": "gè", "defs": [{"meaning": "每个,各自。", "cites": [{"t": "各守尔典。", "b": "《书·汤浩》"}, {"t": "行人弓箭各在腰", "b": "唐·杜甫《兵车行》"}, {"t": "乡民复鸣锣会集各乡约数千人。", "b": "《三元里人民抗英》"}], "words": [{"w": "各有所长;各个;各自;各众", "t": "梵语。各位"}, {"w": "各行其志", "t": "各人按照自己的志向行事。"}]}, {"meaning": "皆。", "cites": [{"t": "各非敢违卜,用宏兹贲。", "b": "《书·盘庚下》"}, {"t": "诸在上者,皆为其下阳;诸在下者,各为其上阴。", "b": "《春秋繁露》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('507wx','多','1','duō','夕','6','','[{"pinyin": "duō", "defs": [{"meaning": "(会意。甲骨文字形,从二“夕”。表示数量大。本义:多,数量大,与“少”、“寡”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "多,重也。从重夕,会意。重夕为多,重日为叠。", "b": "《说文》"}, {"t": "多,众也。", "b": "《尔雅·释诂》"}, {"t": "何多日也。", "b": "《诗·邶风·旄丘》"}, {"t": "与为多焉。", "b": "《史记·五帝纪》。索隐:“大也。”"}, {"t": "宽裕而多容。", "b": "《荀子·致仕》"}, {"t": "以是人多以书假余。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "多次;多分", "t": "多半"}, {"w": "多士", "t": "众多士子"}, {"w": "多感", "t": "多谢,非常感激"}, {"w": "多口", "t": "多嘴"}, {"w": "多般", "t": "许多事端;多半;大概"}, {"w": "多口可", "t": "许多"}, {"w": "多花", "t": "方言。许多"}, {"w": "多许", "t": "多少。"}]}, {"meaning": "重。与“轻”相对。", "cites": [{"t": "士亦以此多之。", "b": "《汉书·灌夫传》。注:“犹重之。”"}, {"t": "名与身孰亲?身与货孰多?", "b": "《老子》"}]}, {"meaning": "贤;好。", "cites": [{"t": "听者自多而不得。", "b": "《吕氏春秋·谨听》。注:“自贤也。”"}], "words": [{"w": "多才", "t": "多才俊。女子昵称她所钟情的男子。"}]}, {"meaning": "赞许,推崇。", "cites": [{"t": "此诚雕虫之戏,不足为多也。", "b": "唐·白居易《与元九书》"}]}, {"meaning": "多么。"}, {"meaning": "虚指某种程度。"}, {"meaning": "只,仅仅。", "cites": [{"t": "多见其不知量也。", "b": "《论语》"}, {"t": "吾今实过,悔之何及,多遗秦禽。", "b": "《左传·襄公十四年》"}, {"t": "存亡有命,事楚何为?多取费焉。", "b": "《左传·定公十五年》"}]}, {"meaning": "大多。", "cites": [{"t": "以故多持女远逃亡。", "b": "《西门豹治邺》"}, {"t": "古法采草药多用二月、八月,此殊未当。", "b": "宋·沈括《梦溪笔谈·采草药》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('508wx','争','1','zhēng zhèng','刀','6','','[{"pinyin": "zhēng", "defs": [{"meaning": "(会意。金文字形,上为“爪”(手),下为“又”(手),中间表示某一物体,象两人争一样东西。从又,义同。本义:争夺)。"}, {"meaning": "同本义。", "cites": [{"t": "争,彼此竞引物也。", "b": "《一切经音义》引《说文》"}, {"t": "争所有余。", "b": "《墨子·公输》"}, {"t": "几只早莺争暖树。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "民争负薪。", "b": "《资治通鉴·唐纪》"}, {"t": "人争鬻之。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "争座", "t": "争座次;争高低"}, {"w": "争立", "t": "争夺王位"}, {"w": "争国", "t": "争夺君位"}, {"w": "争恶", "t": "争夺险要之地"}, {"w": "争标", "t": "争夺优胜"}, {"w": "争重", "t": "争夺帝位、王权。"}]}, {"meaning": "辩论;争论。", "cites": [{"t": "争者事之末也。", "b": "《国语·越语》"}, {"t": "在丑不争。", "b": "《孝经》。注:“竞也。”"}, {"t": "分争辩讼,非礼不决。", "b": "《礼记·曲礼》"}, {"t": "有竞有争。", "b": "《庄子·齐物论》。注:“对辩曰争。”"}, {"t": "与贵酋处二十日,争曲直,屡当死。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "争抗", "t": "抗争;抗衡"}, {"w": "争让", "t": "争执"}, {"w": "争口", "t": "争论"}, {"w": "争高低;争言", "t": "争辩;争吵。"}]}, {"meaning": "争胜,争着。", "cites": [{"t": "争割地而赂秦。", "b": "汉·贾谊《过秦论》"}, {"t": "争奔走焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "争延之使奏其技。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "诸将果争前抱持之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "争心", "t": "争强好胜的心理"}, {"w": "争途", "t": "抢占道路。亦喻争夺地位"}, {"w": "争求", "t": "竞相追求"}, {"w": "争妍", "t": "竞相逞美"}, {"w": "争长", "t": "争行礼先后;争相增长"}, {"w": "争奇", "t": "竞相逞其奇特。"}]}, {"meaning": "争斗。", "cites": [{"t": "操舍鞍马,仗舟楫,与吴越争衡。", "b": "《资治通鉴》"}], "words": [{"w": "争跤", "t": "摔跤"}, {"w": "争交", "t": "摔跤。"}]}, {"meaning": "竞争;较量。", "cites": [{"t": "推此志也,虽与日月争光可也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "争校", "t": "争竞,计较"}, {"w": "争春", "t": "争艳于春日"}, {"w": "争进", "t": "为仕宦而相争"}, {"w": "争张", "t": "争竞,夸张"}, {"w": "争棋", "t": "下棋争胜"}, {"w": "争强", "t": "争为强者。"}]}, {"meaning": "相差。", "cites": [{"t": "百年身后一丘土,贫富高低争几多?", "b": "唐·杜荀鹤《自遣》"}], "words": [{"w": "争些个", "t": "差一点"}, {"w": "争些儿", "t": "差一点儿;险些"}, {"w": "争不多", "t": "差不多"}, {"w": "争差", "t": "差错;差别。"}]}, {"meaning": "春秋时鲁国北城护城河名,又为北城门名 。也作“净”。"}, {"meaning": "多用于诗、词、曲中,相当于“怎么”。", "cites": [{"t": "片言争敢动吾皇。", "b": "《警世通言》"}], "words": [{"w": "争知", "t": "怎知"}, {"w": "争似", "t": "怎似"}, {"w": "争耐", "t": "怎标;无奈。"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhèng", "defs": [{"meaning": "“诤”的本字。强谏;规劝。", "cites": [{"t": "知而不争,不可谓忠。", "b": "《墨子·公输》"}, {"t": "争而不得。", "b": ""}, {"t": "伊尹、箕子可谓谏矣,比干、子胥可谓争矣。", "b": "《荀子·臣道》"}, {"t": "父有争子,不行无理。士有争友,不为不义。", "b": "《荀子·子道》"}], "words": [{"w": "争子", "t": "能直言规劝父母的儿子"}, {"w": "争友", "t": "能直言规劝的朋友"}, {"w": "争臣", "t": "能直言诤谏的大臣"}, {"w": "争引", "t": "能引事例以谏诤"}, {"w": "争弟", "t": "能直言规劝兄长的弟弟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('509wx','色','1','sè shǎi','色','6','','[{"pinyin": "sè", "defs": [{"meaning": "(会意。甲骨文中象一个人驮另一个人,仰承其脸色。本义:脸色)。"}, {"meaning": "同本义。", "cites": [{"t": "色,颜气也。", "b": "《说文》"}, {"t": "五气五色。", "b": "《周礼·疾医》"}, {"t": "其色必寿。", "b": "《素问·三部九侯论》"}, {"t": "形体色理以目异。", "b": "《荀子·正名》"}, {"t": "载色载笑。", "b": "《诗·鲁颂·泮水》"}]}, {"meaning": "又。", "cites": [{"t": "太后之色少解。", "b": "《战国策·赵策》"}, {"t": "侯生视公子色终不变,乃谢客就车。", "b": "《史记·魏公子列传》"}, {"t": "我言若,王色不许我。", "b": "《史记·商君列传》"}, {"t": "故以声声怖之。", "b": "《资治通鉴》"}], "words": [{"w": "面色", "t": "脸上的气色"}, {"w": "色喜", "t": "脸上显出欢喜之色"}, {"w": "色笑", "t": "开颜欢笑"}, {"w": "色沮", "t": "脸色露出沮丧的样子"}, {"w": "色变振恐", "t": "恐惧得脸上变色"}, {"w": "色庄", "t": "容貌庄重严肃"}, {"w": "色智", "t": "表现在容色上的才智"}, {"w": "喜形于色", "t": ""}]}, {"meaning": "颜色。", "cites": [{"t": "五色令人目盲。", "b": "《老子》"}, {"t": "满面尘灰烟火色,两鬓苍苍十指黑。", "b": "唐·白居易《卖炭翁》"}, {"t": "未花时采,则根色鲜泽。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "色衣", "t": "色服。除黑白二色以外的各种艳色衣服"}, {"w": "色丝", "t": "彩色绸缎"}, {"w": "色彩", "t": "彩色绸缎"}, {"w": "古色古香", "t": ""}]}, {"meaning": "姿色,容颜(多就女子而言);美色。", "cites": [{"t": "寡人有疾,寡人好色。", "b": "《孟子·梁惠王下》"}, {"t": "年长色衰,委身为贾人妇。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "绝色佳人;声色;色阵", "t": "指冶艳女子聚集之所"}, {"w": "国色", "t": "一国内容貌最美的女子。"}]}, {"meaning": "佛家语。指一切物质的存在。", "cites": [{"t": "空色皆寂灭。", "b": "陈子昂《感遇》"}], "words": [{"w": "色身(佛家语色,指有形、色、相的一切物,即所谓物质肉身,即有形血肉之身;自四大(地、水、火、风)、五尘(色、声、香、味、触)等色法而成,故称色身", "t": ""}, {"w": "色即是空(佛家语指世家一切色法(物质)的本性(内在真实性)都是空无所有)", "t": ""}]}, {"meaning": "履历,古称“脚色”,省称“色”。", "cites": [{"t": "吏部预选者甚多,[卢]恺即不授官,皆注色而遣。", "b": "《北史》"}]}, {"meaning": "物质(多指金银)的成分。", "cites": [{"t": "他这银子是九五兑九七色的。", "b": "《儒林外史》"}]}, {"meaning": "兆气,即古人烧灼龟甲占卜时甲上裂纹所呈现的征兆。", "cites": [{"t": "君占体,大夫占色。", "b": "《周礼》"}]}, {"meaning": "风景;景观。", "cites": [{"t": "两峰秀色,俱可手揽。", "b": "《徐霞客游记·游黄山记》"}, {"t": "入其城则四顾萧条,寒水自碧,暮色渐起。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "满园春色;湖光山色", "t": ""}]}, {"meaning": "天色。", "cites": [{"t": "夜色语声绝。", "b": "杜甫《石壕史》"}], "words": [{"w": "月色", "t": ""}]}, {"meaning": "生气;变脸。", "cites": [{"t": "谚所谓室于怒,市于色者,楚之谓矣。", "b": "《左传·昭公十九年》"}], "words": [{"w": "色作", "t": "作色,改变脸色"}, {"w": "色勃", "t": "骤然变色。发怒的样子"}, {"w": "色动", "t": "脸色改变。"}]}, {"meaning": "惊惧。", "cites": [{"t": "诸大夫见之,皆色然而骇。", "b": "《公羊传》"}]}]}, {"pinyin": "shǎi", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('510wx','壮','1','zhuàng','士','6','','[{"pinyin": "zhuàng", "defs": [{"meaning": "(形声。从士,爿(pán)声。本义:人体高大,肌肉壮实)。"}, {"meaning": "同本义。", "cites": [{"t": "壮,大也。", "b": "《说文》"}, {"t": "壮,健也。", "b": "《广雅》"}, {"t": "秦晋之间凡人之大谓之奘,或谓之壮。", "b": "《方言》"}, {"t": "三十曰壮。", "b": "《礼记·曲礼》"}, {"t": "壮士,赐之卮酒。", "b": "《史记·项羽本纪》"}, {"t": "右贤王惊,夜逃,独与其爱妾一人,壮骑数百驰。", "b": "《史记·卫将军骠骑列传》"}, {"t": "男气壮力。", "b": "《逸周书》"}, {"t": "壮哉我中国少年。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "三小姐长远勿见,好像壮仔点哉。", "b": "清·韩邦庆《海上花列传》"}], "words": [{"w": "壮浪", "t": "健壮"}, {"w": "壮盛", "t": "强壮旺盛"}, {"w": "壮勇", "t": "强壮而勇敢"}, {"w": "壮武", "t": "强壮勇武"}, {"w": "年轻力壮;兵强马壮;壮健", "t": "强壮,强健。"}]}, {"meaning": "豪壮;豪迈。", "cites": [{"t": "彼不知惧,而学壮语,此之不武,何能为也。", "b": "《晋书·谯刚王逊传》"}, {"t": "七龄思即壮,开口咏凤凰。", "b": "杜甫《壮游》"}], "words": [{"w": "壮夫", "t": "豪壮之士,豪杰"}, {"w": "壮思", "t": "豪壮的情思"}, {"w": "壮情", "t": "豪壮的情怀、抱负"}, {"w": "壮意", "t": "豪壮的意气。"}]}, {"meaning": "勇壮。", "cites": [{"t": "风萧萧兮易水寒,壮士一去兮不复还。", "b": "《战国策·魏策三》"}], "words": [{"w": "壮武", "t": "勇壮,雄武"}, {"w": "壮悍", "t": "勇壮强悍"}, {"w": "壮毅", "t": "勇壮刚毅"}, {"w": "壮辞", "t": "勇壮的言辞。"}]}, {"meaning": "宏伟。", "cites": [{"t": "克壮其犹。", "b": "《诗·小雅·采芑》"}, {"t": "且夫天子以四海为家,非壮丽无以重威。", "b": "《史记·高祖纪》"}], "words": [{"w": "壮丽", "t": "雄伟华丽"}, {"w": "壮制", "t": "宏伟的制作"}, {"w": "壮图", "t": "伟大的志愿、计划。"}]}, {"meaning": "坚实,坚牢。", "cites": [{"t": "金绳铁索纽壮,古鼎跃水龙腾梭。", "b": "韩愈《石鼓歌》"}]}, {"meaning": "增强。", "cites": [{"t": "《唐史拾遗》曰:“汝阳王王进尝于上前醉,不能下殿,上遣人掖出之。”王进谢罪曰:“臣以三斗壮胆,不觉至此。”", "b": "杜甫《饮中八仙歌·注》"}], "words": [{"w": "给他壮胆;壮声势", "t": ""}]}, {"meaning": "长成年,长大。", "cites": [{"t": "男女当壮,扶辇推舆,相赌树下,戏笑超距,终日不归。", "b": "《管子》"}]}, {"meaning": "以…为壮美;赞赏。", "cites": [{"t": "单于壮其本。", "b": "《汉书·李广苏建传》"}, {"t": "何其壮也。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "甚可壮也。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "识者壮之。", "b": "《明史》"}]}, {"meaning": "伤", "cites": [{"t": "姤,女壮,勿用取女。", "b": "《易·姤》"}, {"t": "韩安国壮趾,王恢兵首,彼若天命,此近人咎。", "b": "《汉书》"}]}, {"meaning": "壮年 。中国古代称男子三十为壮。", "cites": [{"t": "少壮不努力。", "b": "《乐府诗集·长歌行》"}, {"t": "比后壮乃问其母。(壮:成年。名词在句中作动词用。长大成人。)", "b": "晋·干宝《搜神记》"}]}, {"meaning": "灸法术语。"}, {"meaning": "指艾炷灸中的计数单位。每灸一个艾炷,称为一壮。"}, {"meaning": "指艾炷。如大壮灸,即指用较大的艾炷施灸,小壮灸即指用较小的艾炷施灸。"}, {"meaning": "壮族的省称 。原作“僮”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('511wx','冲','1','chōng chòng','冫','6','','[{"pinyin": "chōng", "defs": [{"meaning": "(形声。从水,中声。本义:向上涌流)。"}, {"meaning": "同本义。", "cites": [{"t": "冲溶沅瀁。", "b": "木华《海赋》"}]}, {"meaning": "直上。", "words": [{"w": "冲天", "t": "直上天空"}, {"w": "冲汉", "t": "直上霄汉。"}]}, {"meaning": "空虚。", "words": [{"w": "冲室", "t": "虚室,空室"}, {"w": "冲寞", "t": "虚寂恬静。"}]}, {"meaning": "平和;谦虚。", "words": [{"w": "冲融", "t": "融和充实"}, {"w": "冲和", "t": "性情谦虚和平。"}]}, {"meaning": "幼小。", "words": [{"w": "冲弱", "t": "年幼,幼稚"}, {"w": "冲年", "t": "幼年"}, {"w": "冲幼", "t": "年幼"}, {"w": "冲眇", "t": "幼小。"}]}, {"meaning": "(形声。从行,重声。“行”,意思是路。本义:交通要道)。"}, {"meaning": "同本义。", "cites": [{"t": "及冲,以戈击之。", "b": "《左传·昭公元年》。注:“要道。”"}, {"t": "冲风起兮水横波。", "b": "《楚辞·河伯》。注:“隧也。”"}, {"t": "太冲绝。", "b": "《素问·至真要论》。注;“肝脉气也。”"}], "words": [{"w": "冲衢", "t": "交通要道"}, {"w": "冲途", "t": "要道;大路"}, {"w": "冲境", "t": "冲要之地;交通发达地区。"}]}, {"meaning": "古战车名。用以攻城。", "cites": [{"t": "与尔临冲。", "b": "《诗·大雅·皇矣》"}, {"t": "主人焚冲。", "b": "《左传·定公八年》"}, {"t": "折冲万里。", "b": "《淮南子·说山》"}, {"t": "隆冲以攻。", "b": "《淮南子·泛论》"}], "words": [{"w": "冲车", "t": "古兵车名。用以冲城攻坚"}, {"w": "冲隆", "t": "古兵车。"}]}, {"meaning": "冲击;冲撞。", "cites": [{"t": "稍近,益狎,荡倚冲冒。", "b": "柳宗元《黔之驴》"}, {"t": "此鸟不飞则已,一飞冲天;不鸣则已,一鸣惊人。", "b": "《史记·滑稽列传》"}, {"t": "怒发上冲冠。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "冲激", "t": "冒犯"}, {"w": "冲打", "t": "冲击攻打"}, {"w": "冲阵", "t": "冲击敌方战阵。"}]}]}, {"pinyin": "chòng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('512wx','妆','1','zhuāng','女','6','','[{"pinyin": "zhuāng", "defs": [{"meaning": "(形声。从女,爿(pán)声。本义:梳妆打扮)。"}, {"meaning": "同本义。", "cites": [{"t": "妝,饰也。", "b": "《说文》。字亦作娤。"}, {"t": "不待饰装(妆)。", "b": "宋玉《登徒子好色赋》"}, {"t": "靓莊(妆)刻饰。", "b": "司马相如《上林赋》"}, {"t": "曲罢曾教善才服,妆成每被秋娘妒。", "b": "唐·白居易《琵琶行》"}]}, {"meaning": "又。", "cites": [{"t": "梦啼妆泪红阑干。", "b": ""}, {"t": "绿云扰扰,开妆镜也。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "形容憔悴,非昔悦,蓬鬓衰颜不复妆。", "b": "鲍照《拟行路难》"}, {"t": "想着他眉儿浅浅描,脸儿淡淡妆。", "b": "王实甫《西厢记》"}], "words": [{"w": "妆束", "t": "打扮的样式"}, {"w": "妆台", "t": "妇女梳妆用的镜台。亦借指闺房"}, {"w": "妆严", "t": "妆束;打扮。"}]}, {"meaning": "假装。同“装”。", "cites": [{"t": "叉手躬身,妆聋做哑。", "b": "王实甫《西厢记》"}], "words": [{"w": "妆谎子", "t": "装腔,作假"}, {"w": "妆晃", "t": "装门面,摆样子。"}]}, {"meaning": "女子身上的妆饰、脂粉。", "cites": [{"t": "阿姊闻妹来,当户理红妆。", "b": "《乐府诗集·木兰诗》"}, {"t": "罗襦不复施,对君洗红妆。", "b": "杜甫《新婚别》"}], "words": [{"w": "艳妆;浓妆;妆光", "t": "盛装的容貌"}, {"w": "妆盒", "t": "盛梳妆品的盒子"}, {"w": "妆泪", "t": "女子的粉泪"}, {"w": "妆奁", "t": "女子梳妆用的镜匣等物。"}]}, {"meaning": "装饰的式样。", "cites": [{"t": "小姑洲北浦云边,二女啼妆自俨然。", "b": "唐·李群玉《黄陵庙》"}], "words": [{"w": "宣和妆;宫样十八九妆;妆束", "t": "服饰"}, {"w": "妆梳", "t": "梳妆打扮的款式"}, {"w": "妆饰", "t": "打扮的样式。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('513wx','冰','1','bīng','冫','6','','[{"pinyin": "bīng", "defs": [{"meaning": "(会意。从仌,从水。金文作“仌”。金文字形表示水凝成冰后,体积增大,表面上涨(上拱)形。《说文》:“冻也,象水凝之形”。小篆繁化,增加“水”变成。从“仌”从“水”的会意字,于是“仌”就专用作部首。本义:水冻结而成的固体)。"}, {"meaning": "同本义。", "cites": [{"t": "冰,水坚也。", "b": "《说文》"}, {"t": "履霜坚冰至。", "b": "《易·坤》"}, {"t": "迨冰未泮。", "b": "《诗·邶风·匏有苦叶》"}, {"t": "冰者,阴之盛而水滞者也。", "b": "《汉书·五行志》"}, {"t": "冰,水为之。", "b": "《荀子·劝学》"}, {"t": "冰解而冻释。", "b": "《管子·五行》"}, {"t": "公徒释甲,执冰而踞。", "b": "《左传·昭公二十五年》"}], "words": [{"w": "冰扳", "t": "冰镇"}, {"w": "冰麝", "t": "冰片与麝香"}, {"w": "冰清水冷", "t": "像冰和水一样的清冷"}, {"w": "冰前刮雪", "t": "喻雪上加霜之事"}, {"w": "冰玉自信", "t": "自知冰清玉洁,并无苟且之事"}, {"w": "冰轮", "t": "比喻月亮。"}]}, {"meaning": "结冰,冻结。", "cites": [{"t": "水始冰,地始冻。", "b": "《礼记·月令》"}]}, {"meaning": "使感到极冷。", "cites": [{"t": "风月冰人别是乡。", "b": "杨万里《六月二十四日病起喜雨闻莺》"}], "words": [{"w": "这水冰手", "t": ""}]}, {"meaning": "清白,晶莹。", "cites": [{"t": "洛阳亲友如相问,一片冰心在玉壶。", "b": "王昌龄《芙蓉楼送辛渐》"}], "words": [{"w": "冰操", "t": "廉洁的操行。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('514wx','庄','1','zhuāng','广','6','','[{"pinyin": "zhuāng", "defs": [{"meaning": "(会意兼形声。从艸,从壮,壮亦声。本义:草大)。"}, {"meaning": "同本义。", "cites": [{"t": "莊,草芽之壮也。", "b": "《六书正伪》"}, {"t": "莊,草盛貌。", "b": "《唐韵》"}, {"t": "汉明帝名莊,汉世多以严字为之。《左传》、《楚莊王国》、《莊子》、《论语》、《卞莊子》,古今人表皆作严,此字从草,壮声,许不著说解,其义失传。", "b": "朱骏声《说文通训定声》"}]}, {"meaning": "谨严持重。", "cites": [{"t": "临之以庄,则敬。", "b": "《论语·为政》"}, {"t": "师之以庄贤于丘也。", "b": "《列子·仲尼》"}, {"t": "则季孙终身庄而遇贼。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "庄论", "t": "庄重严肃的议论或说教"}, {"w": "庄语", "t": "庄重正直的言论"}, {"w": "庄士", "t": "端正之士;正人君子"}, {"w": "庄色", "t": "严肃的神色。"}]}, {"meaning": "四面八方的,四通八达的。", "cites": [{"t": "为开第康庄之衢。", "b": "《史记·孟子荀卿列传》"}]}, {"meaning": "恭敬。", "cites": [{"t": "非礼不诚不庄。", "b": "《礼记·曲礼》。注:“敬也。”"}, {"t": "居处不庄,非孝也。", "b": "《吕氏春秋》"}], "words": [{"w": "庄椿", "t": "祝人长寿之词。"}]}, {"meaning": "村庄,也指建在山林田野间的住宅,别墅。", "cites": [{"t": "邻富鸡长住,庄贫客渐稀。", "b": "唐·姚合《原上新居》"}], "words": [{"w": "王家庄;台儿庄;庄子", "t": "村庄"}, {"w": "庄屯", "t": "清初,政府圈拨土地给各旗官兵而形成的村庄。又称屯庄。"}]}, {"meaning": "六路通达的大路。", "cites": [{"t": "得庆氏之木百车于庄。", "b": "《左传·襄公二十八年》"}, {"t": "康庄驰逐,穷巷蹋鞠。", "b": "《盐铁论·国疾》"}]}, {"meaning": "又如康庄(康,五路通达的大路;庄:六路通达的大路。合称通达的大路);庄馗(四通八达的道路。馗,同“逵”)。"}, {"meaning": "庄园,皇室、官僚、地主等在乡下占据的大片土地及其建筑物。", "cites": [{"t": "万里桥西宅,百花潭北庄。", "b": "《杜工部草堂诗笺》"}], "words": [{"w": "庄吏", "t": "为地主管理田庄及收税租的人"}, {"w": "庄奴", "t": "佃户,佃农"}, {"w": "庄宾", "t": "指佃客、佃农"}, {"w": "庄地", "t": "庄田。"}]}, {"meaning": "件", "cites": [{"t": "此一庄事不敢隐讳。", "b": "关汉卿《王闰香夜月四春园》"}]}, {"meaning": "古代云南交易用贝单位。", "cites": [{"t": "交易用贝,一枚曰庄,四庄曰手,四手曰苗,五苗曰索。", "b": "顾炎武《天下郡国利病书》"}]}, {"meaning": "打扮,修饰。", "cites": [{"t": "靓庄刻饰。", "b": "《汉书·司马相如传》"}, {"t": "靓庄藻野。", "b": "颜延之《三月三日曲水诗序》"}, {"t": "沐浴靓庄。", "b": "《北史·隋宗室诸王传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('515wx','庆','1','qìng','广','6','','[{"pinyin": "qìng", "defs": [{"meaning": "(会意。甲骨文字形,左边是个“文”字,中间有个心,表示心情诚恳;右边是一张鹿皮。合起来表示带着鹿皮,真诚地对人庆贺。小篆字形上面是鹿字省略一部分;中间是“心”字,表心意;下边是“攵”(suī脚),表示“往”。意思跟甲骨文相同。本义:祝贺;庆贺)。"}, {"meaning": "同本义。", "cites": [{"t": "庆,行贺人也。…吉礼以鹿皮为挚,故从鹿省。", "b": "《说文》。段注:“谓心所喜而行也。”"}, {"t": "庆,贺也。", "b": "《广雅·释言》"}, {"t": "庆子家驹。", "b": "《公羊传·昭公二十五年》"}, {"t": "故庆其喜。", "b": "《国语·鲁语》"}, {"t": "是以有庆矣。", "b": "《诗·小雅·裳者华》"}, {"t": "蜀遣卫尉陈震庆权践位。", "b": "《三国志·吴主传》"}, {"t": "苏秦见齐王,再拜,俯而庆,仰而吊。", "b": "《史记·苏秦列传》"}], "words": [{"w": "庆忭", "t": "欢庆鼓掌"}, {"w": "庆寿", "t": "祝贺生日"}, {"w": "庆问", "t": "庆贺问候"}, {"w": "庆官酒", "t": "庆祝升官的酒宴"}, {"w": "庆成宴", "t": "庆贺祭祀典礼圆满成功的宴会"}, {"w": "庆松", "t": "庆贺。"}]}, {"meaning": "赏赐。", "cites": [{"t": "农夫之庆。", "b": "《诗·小雅·甫田》"}], "words": [{"w": "庆赏", "t": "行赏奖励。"}]}, {"meaning": "喜;福庆,吉庆。", "cites": [{"t": "孝孙有庆。", "b": "《诗·小雅·楚茨》"}, {"t": "一人有庆,兆民赖之。", "b": "《书·吕刑》"}], "words": [{"w": "寿庆;校庆;国庆;庆色", "t": "喜色"}, {"w": "庆会", "t": "喜庆宴会"}, {"w": "庆门", "t": "福庆之家"}, {"w": "庆殃", "t": "福庆与祸殃。"}]}, {"meaning": "福泽。有幸的事。", "cites": [{"t": "有庆未尝不怡。", "b": "《国语·周语》。注:“福也。”"}], "words": [{"w": "余庆;庆云", "t": "庆烟。祥瑞的云气"}, {"w": "庆霄", "t": "吉祥的云气"}, {"w": "庆灵", "t": "景云与灵芝"}, {"w": "庆绪", "t": "福善的事业"}, {"w": "庆延", "t": "福泽绵延"}, {"w": "庆祉", "t": "福泽"}, {"w": "庆室", "t": "吉宅。"}]}, {"meaning": "卿士,大臣掌事者。", "cites": [{"t": "作率庆士,躬恤卫国。", "b": "《礼记·祭统》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('516wx','亦','1','yì','亠','6','','[{"pinyin": "yì", "defs": [{"meaning": "(指事。甲骨文字形,在“大”(人)旁加两点,指示两腋所在。“腋”的本字。本义:人腋窝) 同本义。", "cites": [{"t": "亦,人之臂亦也。", "b": "《说文》。字俗作腋"}, {"t": "胳谓之腋。", "b": "《广雅》"}, {"t": "腋在肘后。", "b": "《埤苍》"}]}, {"meaning": "也;也是。", "cites": [{"t": "亦免冠徒跣,以头抢地尔。(也不过是摘了帽子,光着脚,把头往地上撞罢了。抢,撞。)", "b": "《战国策·魏策》"}, {"t": "亦盛矣哉。(也真是盛大隆重的事啊!)", "b": "明·张溥《五人墓碑记》"}, {"t": "亦以明死生之大。(也就是为了用它表明死生的重大意义。以,用,后面省略了宾语“之”)。", "b": "明·张溥《五人墓碑记》"}, {"t": "攻一时,敌退,三保亦自喜。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "亦许", "t": "也许"}, {"w": "亦然", "t": "也是这样。"}]}, {"meaning": "又。", "cites": [{"t": "先君何罪?其嗣亦何罪?", "b": "《左传·文公七年》"}], "words": [{"w": "亦且", "t": "又,而且"}, {"w": "亦复", "t": "又。"}]}, {"meaning": "不过;仅仅;只是。", "cites": [{"t": "寡人之从君而西也,亦晋之妖梦是践。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('517wx','刘','1','liú','刂','6','','[{"pinyin": "liú", "defs": [{"meaning": "(形声。从金,从刀,丣(yǒu)声。本义:杀,戮)。"}, {"meaning": "同本义(含有大规模杀戮的意思)。", "cites": [{"t": "胜殷遏刘,耆代尔功。", "b": "《诗·周颂·武》"}, {"t": "重我民,无尽刘。", "b": "《书·盘庚上》。孔传:“刘,杀也。”"}, {"t": "秦晋宋卫之间谓杀曰刘,晋之北鄙亦曰刘。", "b": "《方言》卷一"}, {"t": "芟夷我农功,虔刘我边垂。(虔:杀戮)。", "b": "《左传·成公十三年》"}]}, {"meaning": "克,战胜。", "cites": [{"t": "咸刘商王纣,执矢恶臣百人。", "b": "《逸周书·世俘》"}]}, {"meaning": "兵器名。斧钺。", "cites": [{"t": "一人冕,执刘,立于东堂。", "b": "《书·顾命》。孔传:“刘,钺属。”孔颖达疏引郑玄曰:“刘,盖今鑱斧。”"}]}, {"meaning": "剥落,凋残。", "cites": [{"t": "靡草不凋,无木不刘。", "b": "明·刘基《擢彼乔松》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('518wx','齐','1','jì qí','齐','6','','[{"pinyin": "jì", "defs": [{"meaning": "调味品。", "cites": [{"t": "凡齐,执之以右,居之以左。", "b": "《礼记》"}]}, {"meaning": "合金。", "cites": [{"t": "金有六齐:六分其金而锡居一,谓之钟鼎之齐。", "b": "《周礼·考工记·辀人》"}]}, {"meaning": "登,升。", "cites": [{"t": "帝命不违,至於汤齐。", "b": "《诗·商颂·长发》"}]}]}, {"pinyin": "qí", "defs": [{"meaning": "(象形。甲骨文字形,象禾麦穗头长得平整的样子。小篆字形下面多了两条线,表示地面。本义:禾麦吐穗上平整)。"}, {"meaning": "同本义。", "cites": [{"t": "齊,禾麦吐穗上平也。", "b": "《说文》"}, {"t": "立如齐。", "b": "《礼记·曲礼》"}]}, {"meaning": "整齐。", "cites": [{"t": "其君齐明衷正。", "b": "《国语·周语》"}, {"t": "为齐敬也。", "b": "《国语·楚语》"}, {"t": "气候不齐。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "上下方整,前后齐平。", "b": "王羲之《题笔阵图》"}, {"t": "进退得齐焉。", "b": "《白虎通·礼乐》"}], "words": [{"w": "齐均", "t": "整齐均匀"}, {"w": "齐贝", "t": "整齐的贝壳。即“编贝”"}, {"w": "齐肃", "t": "整齐严肃。"}]}, {"meaning": "平等。", "cites": [{"t": "齐明而不竭。", "b": "《荀子·脩身》。注:“无偏无颇也。”"}, {"t": "齐民无藏盖。", "b": "《史记·平准书》"}], "words": [{"w": "齐等", "t": "平等。"}]}, {"meaning": "全,齐全。", "cites": [{"t": "而民不齐出于南亩。", "b": "《史记·平准书》"}, {"t": "各屋子里丫头们将灯火俱已点齐。", "b": "《红楼梦》"}], "words": [{"w": "齐全人", "t": "指家里的长辈及丈夫都全的妇女,被认为是有福气的"}, {"w": "人都到齐了", "t": ""}]}, {"meaning": "好。", "cites": [{"t": "如时运不齐,命途多舛。", "b": "唐·王勃《滕王阁序》"}]}, {"meaning": "疾,敏捷。", "cites": [{"t": "齐,疾也。", "b": "《尔雅》"}, {"t": "齐疾而均,速若飘风。", "b": "《商君书·弱民》"}, {"t": "齐给如响。", "b": "《荀子·臣道》"}, {"t": "多闻而齐给。", "b": "《尚书·大传》"}]}, {"meaning": "（zhai）。肃敬。", "cites": [{"t": "而又能齐肃衷正。", "b": "《国语·楚语下》"}]}, {"meaning": "同等,相等。", "cites": [{"t": "以给水火之齐。", "b": "《周礼·亨人》。注;“多少之量也。”"}, {"t": "大时不齐。", "b": "《礼记·学记 》"}, {"t": "与日月齐光。", "b": "《楚辞·屈原·涉江》"}, {"t": "一日之内,一宫之间,而气候不齐。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "齐生", "t": "指自然中万物生死的本质都是相同的"}, {"w": "齐死", "t": "指人生在世,无论贵贱贤愚,长寿短命,其死则同,死而必为腐骨亦同"}, {"w": "齐同", "t": "一致,同等"}, {"w": "齐物", "t": "万事万物从大道的眼光来看,没有生死、成毁、美丑的不同,但每物都有其存在的价值,每事都有其发生的意义。"}]}, {"meaning": "整治。", "cites": [{"t": "修身齐家治国平天下。", "b": "梁启超《少年中国说》"}], "words": [{"w": "齐正", "t": "平定。"}]}, {"meaning": "达到同样高度。", "cites": [{"t": "妻为具食,不敢于鸿前仰视,举案齐眉。", "b": "《后汉书》"}, {"t": "至日观数里内无树,而雪与人膝齐。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "使整齐。", "cites": [{"t": "马不齐髦。", "b": "《仪礼·既夕礼记》"}], "words": [{"w": "齐叶", "t": ""}]}, {"meaning": "（zhāi）。斋戒。", "cites": [{"t": "齐则缁之。", "b": "《仪礼·士冠礼》"}, {"t": "使五人齐,而长入拜。", "b": "《左传·昭公十三年》"}, {"t": "子之所慎,齐,战,疾。", "b": "《论语·述而》"}]}, {"meaning": "资助。"}, {"meaning": "朝代名 。南北朝时代,南朝萧道成代宋为帝,国号齐,史称南齐(479—502);北朝高洋代北魏为帝,国号齐,史称北齐(550—557)。"}, {"meaning": "齐国 。中国周朝分封的诸候国名(公元前1122—前265),在今山东省。", "cites": [{"t": "求救于齐。", "b": "《战国策·赵策》"}]}, {"meaning": "又。", "cites": [{"t": "质于齐。", "b": ""}, {"t": "齐兵乃出。", "b": ""}, {"t": "齐楚之精英。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "齐刀", "t": "古代齐国的钱币名"}, {"w": "齐人", "t": "齐国的人"}, {"w": "齐言", "t": "齐国的语言。"}]}, {"meaning": "肚脐。", "cites": [{"t": "若不早图,后君噬齐,其及图之乎!", "b": "《左传·庄公六年》"}, {"t": "环齐而痛,是为何病?", "b": "《素问·奇病论》"}]}, {"meaning": "中央。", "cites": [{"t": "不知斯齐国几千万里。", "b": "《列子·黄帝》。注:“齐,中也。”"}]}, {"meaning": "同,并,一齐,皆。", "cites": [{"t": "落霞与孤鹜齐飞。", "b": "王勃《滕王阁序》"}, {"t": "一时齐发。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "两儿齐哭。", "b": ""}, {"t": "百千齐作。", "b": ""}, {"t": "众枪齐发。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "齐行", "t": "商人共同抬高市价"}, {"w": "齐力", "t": "并力,合力"}, {"w": "齐手", "t": "众人一致,同时动手"}, {"w": "齐交", "t": "共同交往"}, {"w": "齐叫", "t": "同声呼喊"}, {"w": "齐肩", "t": "并肩,同等"}, {"w": "齐首", "t": "头相齐并列"}, {"w": "齐盟", "t": "同盟,诸国合盟"}, {"w": "齐驱", "t": "并列驰驱。"}]}, {"meaning": "从。", "cites": [{"t": "县官把那两通卷子都齐头看了,都圈点了许多,都在卷面上画了个大圈。", "b": "《醒世姻缘传》"}], "words": [{"w": "齐头", "t": "从头。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('519wx','交','1','jiāo','亠','6','','[{"pinyin": "jiāo", "defs": [{"meaning": "(象形。小篆字形,象人两腿交叉形。本义:交叉)。"}, {"meaning": "脚胫相交。", "cites": [{"t": "交,交胫也。", "b": "《说文》"}, {"t": "交足而待。", "b": "《战国策·秦策》"}, {"t": "雕题交趾。", "b": "《礼记·王制》"}], "words": [{"w": "交趾", "t": "古郡名。汉置,地处五岭以南一带。相传这里的人入睡时,两足相交。"}]}, {"meaning": "交叉;交错,错杂。", "cites": [{"t": "交臂厯指。", "b": "《庄子·天地》"}, {"t": "交韔二弓。", "b": "《诗·秦风·小戎》"}], "words": [{"w": "交裆", "t": "裤裆处"}, {"w": "交拐", "t": "拐弯走"}, {"w": "交戟", "t": "执戟相交"}, {"w": "交牙", "t": "如犬牙相交叉"}, {"w": "交歧", "t": "交错的路径。"}]}, {"meaning": "结交; 交往。", "cites": [{"t": "交游士林。", "b": "《资治通鉴》"}], "words": [{"w": "交友", "t": "结交朋友"}, {"w": "交礼", "t": "交往的礼节"}, {"w": "交驰", "t": "交相奔走,往来不断"}, {"w": "交绝", "t": "关系断绝,绝交"}, {"w": "交善", "t": "结交"}, {"w": "交援", "t": "与人交结而得其援助。"}]}, {"meaning": "交接,移交;交换。", "cites": [{"t": "交,易也。", "b": "《小尔雅》"}, {"t": "厥孚交如。", "b": "《易·大有卦》。疏:“交,谓交接也。”"}, {"t": "是言上下之交。", "b": "《荀子·儒效》。注:“交谓上下相交接也。”"}, {"t": "静郭君之交。", "b": "《吕氏春秋·知士》"}], "words": [{"w": "交盘", "t": "点交;交接"}, {"w": "交受", "t": "犹交易"}, {"w": "交点", "t": "清点财物,交付与有关的人"}, {"w": "交关", "t": "交接;紧要关头"}, {"w": "交贸", "t": "交易。"}]}, {"meaning": "交配。", "cites": [{"t": "虎始交。", "b": "《礼记·月令》"}, {"t": "备以为交佩。", "b": "《楚辞·思美人》"}], "words": [{"w": "交群", "t": "交配"}, {"w": "交构", "t": "亦作交媾。指性交;阴阳交合"}, {"w": "交群", "t": "交配"}, {"w": "交感", "t": "指性交。"}]}, {"meaning": "接触。", "cites": [{"t": "故上兵伐谋,其次伐交。", "b": "《孙子·谋攻》"}, {"t": "情交而不感者。", "b": "白居易《与元九书》"}, {"t": "战始三交失蛇矛。", "b": "《乐府诗集·陇上歌》"}], "words": [{"w": "交兵,交战;交臂失之", "t": "走得很靠近,擦肩而过。形容遇见好机会而又错过"}, {"w": "交敌", "t": "交手"}, {"w": "交绥", "t": "交战。"}]}, {"meaning": "送上;付出。", "cites": [{"t": "六日内交清。", "b": "《广东军务记》"}, {"t": "翌日先交。", "b": ""}], "words": [{"w": "交作业;交款;交白卷", "t": ""}]}, {"meaning": "朋友。", "cites": [{"t": "交浅而言深,是忠也。", "b": "《战国策·赵策》"}], "words": [{"w": "故交;旧交;知交;择交;深交", "t": ""}]}, {"meaning": "友谊;友情。", "cites": [{"t": "交浅而言深,是忠也。", "b": "《战国策·赵策》"}], "words": [{"w": "断交;私交;多年之交", "t": ""}]}, {"meaning": "交往。", "cites": [{"t": "布衣之交。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "即共定交。", "b": "《资治通鉴》"}, {"t": "交以绝。", "b": "清·周容《芋老人传》"}], "words": [{"w": "绝交;邦交;建交;复交", "t": ""}]}, {"meaning": "〖时间〗交替之际。", "cites": [{"t": "十月之交。 ", "b": "《诗·小雅·十月》 "}], "words": [{"w": "春夏之交", "t": ""}]}, {"meaning": "跟头。", "cites": [{"t": "鲁达焦躁,把那看的人,一推一交。", "b": "《水浒传》"}]}, {"meaning": "地名。汉代交州的略称。", "cites": [{"t": "交、广布鲑珍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "一齐。", "cites": [{"t": "中外交荐。", "b": "《明史》"}], "words": [{"w": "交至", "t": "一齐来到"}, {"w": "交下", "t": "俱下,齐下"}, {"w": "交攻", "t": "一并进攻"}, {"w": "交赞", "t": "一齐称赞。"}]}, {"meaning": "互相,相互。", "cites": [{"t": "疏条交映。", "b": "吴均《与朱元思书》"}, {"t": "交相问难。", "b": "清·刘开《问说》"}], "words": [{"w": "交注", "t": "互相注视"}, {"w": "交伐", "t": "交相戕害"}, {"w": "交沁", "t": "相互渗透"}, {"w": "交轧", "t": "互相排挤、倾轧"}, {"w": "交眩", "t": "交相惑乱而不明。"}]}, {"meaning": "美丽。", "cites": [{"t": "号曰庄姜。姜交好。", "b": "《列女传·齐女傅母》"}]}, {"meaning": "侮慢,骄傲。", "cites": [{"t": "彼交匪敖,万福来求。", "b": "《诗·小雅·桑扈》"}, {"t": "豢之而俞瘠者,交也。", "b": "《荀子·荣辱》"}]}, {"meaning": "狡谲,诡诈。", "cites": [{"t": "奉妒昧者谓之交谲。", "b": "《荀子·大略》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('520wx','衣','1','yī yì','衣','6','','[{"pinyin": "yī", "defs": [{"meaning": "(象形。甲骨文字形。上面象领口,两旁象袖筒,底下象两襟左右相覆,为上衣形。“衣”是汉字的一个部首。从“衣”的字与衣服有关。本义:上衣)。"}, {"meaning": "同本义。", "cites": [{"t": "衣,所以蔽体者也。上曰衣,下曰裳。", "b": "《说文》"}, {"t": "一戎衣。", "b": "《书·武城》。传:“服也。”"}, {"t": "薄澣我衣。", "b": "《诗·周南·葛覃》"}, {"t": "东方未明,颠倒衣裳。", "b": "《诗·齐风·东方未明》"}, {"t": "绿衣黄裳。", "b": "《诗·邶风·绿衣》"}, {"t": "荀九家乾为衣。", "b": "《易·说卦》"}, {"t": "夜披衣坐。", "b": "唐·李朝威《柳毅传》"}, {"t": "披紫衣。", "b": ""}], "words": [{"w": "衣祛", "t": "衣袖"}, {"w": "衣袖", "t": "衣服的袖子"}, {"w": "衣裤", "t": "上衣与裤子。"}]}, {"meaning": "服装的通称。合上衣下裳而言。", "cites": [{"t": "岂曰无衣,与子同袍。", "b": "《诗·秦风·无衣》"}, {"t": "无衣无褐。", "b": "《诗·邶风·七月》"}, {"t": "易衣而出,并日而食。", "b": "《礼记》"}], "words": [{"w": "衣衿", "t": "秀才穿的衣服;亦指秀才的功名"}, {"w": "衣不解带", "t": "指和衣而睡"}, {"w": "衣不周身", "t": "衣不蔽体"}, {"w": "衣巾寄学", "t": "以士子的身份就学"}, {"w": "衣袄", "t": "军服"}, {"w": "衣饭", "t": "借指谋生的职业、技能。"}]}]}, {"pinyin": "yì", "defs": [{"meaning": "穿衣。", "cites": [{"t": "许子必织布然后衣乎?", "b": "《孟子·滕文公上》"}, {"t": "许子衣褐。", "b": ""}, {"t": "妇人不织,禽兽之皮,足衣也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "衣紫腰金", "t": "身穿紫衣,腰系金带。喻高官厚禄,荣华富贵"}, {"w": "衣帛", "t": "穿丝制的衣裳"}, {"w": "衣冠", "t": "穿衣戴帽。"}]}, {"meaning": "遮盖;包扎。", "cites": [{"t": "古之葬者,厚衣之以薪。", "b": "《易·系辞下》"}, {"t": "裂裳衣疮。", "b": "柳宗元《段太尉逸事状》"}], "words": [{"w": "衣被海内", "t": "给全国都带来好处"}, {"w": "衣饰", "t": "掩饰"}, {"w": "衣覆", "t": "覆盖。"}]}, {"meaning": "依靠"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('521wx','次','1','cì','欠','6','','[{"pinyin": "cì", "defs": [{"meaning": "(形声。从欠,二声。本义:临时驻扎和住宿)。"}, {"meaning": "同本义。", "cites": [{"t": "次,舍也。", "b": "《礼记·檀弓上》注"}, {"t": "楚师伐郑,次于鱼陵。", "b": "《左传·襄公十八年》"}, {"t": "泰伯素服郊次。", "b": "《左传·僖公三十三年》"}, {"t": "王次于河朔。", "b": "《书·泰誓中》"}]}, {"meaning": "指行军在一处停留三宿以上。", "cites": [{"t": "初一交战,操军不利,引次江北。", "b": "《资治通鉴》"}], "words": [{"w": "次止", "t": "驻止;止宿。"}]}, {"meaning": "第二,居其次。", "cites": [{"t": "凡用兵之法,全国为上,破国次之。", "b": "《孙子·谋攻》"}], "words": [{"w": "次从", "t": "然后;接着"}, {"w": "次后", "t": "以后;续后"}, {"w": "次早", "t": "第二天早上。"}]}, {"meaning": "顺序,等第。", "cites": [{"t": "陈胜、吴广皆次当行,为屯长。", "b": "《史记·陈涉世家》"}, {"t": "盖以十舰最著前,中江举帆,余船以次俱进。", "b": "《资治通鉴》"}], "words": [{"w": "二次曲线;次序", "t": "依次排列的顺序"}, {"w": "次第", "t": "顺序,次序。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('522wx','产','1','chǎn','亠','6','','[{"pinyin": "chǎn", "defs": [{"meaning": "(形声。从生,彦省声。本义:出生,生育)。"}, {"meaning": "同本义。", "cites": [{"t": "産,生也。", "b": "《说文》"}, {"t": "百物之产。", "b": "《周礼·大宗伯》。注:“生其种曰产。以天产作阴德,以地产作阳德。”注:“天产者动物,地产者植物,谓九谷之属。”"}, {"t": "同产。", "b": "《后汉书·明帝纪》。注:“同母兄弟也。”"}, {"t": "其妻重身当产。", "b": "晋·干宝《搜神记》"}], "words": [{"w": "产子", "t": "生孩子"}, {"w": "产育", "t": "养育;生育"}, {"w": "产母", "t": "产妇。"}]}, {"meaning": "出产。", "cites": [{"t": "永州之野产异蛇。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "江宁之龙蟠,苏州之邓尉,杭州之西溪,皆产梅。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "产马;产粮;产煤;产油;产机器", "t": ""}]}, {"meaning": "产业;财产。", "cites": [{"t": "里胥猾黠,假此科敛丁口,每责一头,辄倾数家之产。", "b": "《聊斋志异·促织》"}], "words": [{"w": "私产;房地产;房产;家产", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('523wx','决','1','jué','冫','6','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从水,夬(guài)声。本义:疏通水道,使水流出去)。"}, {"meaning": "同本义。", "cites": [{"t": "自河决瓠子后,二十余岁,岁因以数不登。", "b": "《史记·河渠书》"}, {"t": "大决所犯,伤人必多。", "b": "《左传·襄公三十一年》"}, {"t": "决,行流也。", "b": "《说文》"}, {"t": "人导之而行曰决,水不循道而自行亦曰决。", "b": "《说文通训定声》"}, {"t": "予决九川,距四海。", "b": "《书·益稷》"}, {"t": "决之东方而东流。", "b": "《孟子》"}, {"t": "治水有决河深川。", "b": "《汉书·沟洫志》"}, {"t": "决水而灌之。", "b": "《韩非子·初见秦》"}, {"t": "河决不可复壅,鱼烂不可复全。", "b": "《史记·秦始皇纪赞》"}, {"t": "鲧禹决渎。", "b": "《韩非子·五蠹》"}, {"t": "决渎于殷周之世。", "b": ""}, {"t": "买庸而决窦。", "b": ""}], "words": [{"w": "决江", "t": "掘开江边堤岸放水"}, {"w": "决汩", "t": "疏通,疏导。开凿水流,使能通畅"}, {"w": "决子军", "t": "古代挖坑道、地道的工兵"}, {"w": "决泄", "t": "除去壅塞,排除积水。"}]}, {"meaning": "大水冲破堤岸或溢出。", "cites": [{"t": "则决雎澨。", "b": "《左传·成公十五年》"}, {"t": "孝文时,河决酸枣,东溃金堤。", "b": "《史记·河渠书》"}, {"t": "河水决濮阳,泛十六郡。", "b": "《汉书·武帝纪》"}, {"t": "贲星坠而勃海决。", "b": "《淮南子·天文》。注:“溢也。”"}, {"t": "黄河西来决仑。", "b": "李白《公无渡河》"}], "words": [{"w": "决水", "t": "河水决口"}, {"w": "决溢,决泆", "t": "河堤溃破、水流泛滥"}, {"w": "决溃", "t": "堤防被水冲破。"}]}, {"meaning": "断裂,折断。", "cites": [{"t": "决指而身死。", "b": "《淮南子·说山》。注:“伤也。”"}, {"t": "濡肉齿决。", "b": "《礼记·曲礼》。注:“犹断也。”"}], "words": [{"w": "决眥", "t": "眼眶裂开;张眼瞪视"}, {"w": "决羽", "t": "折断羽翼"}, {"w": "决坼", "t": "裂开,张开"}, {"w": "决浮云", "t": "截断浮云,形容剑的威力。"}]}, {"meaning": "离别,同“诀”。", "cites": [{"t": "与我决于传舍中。", "b": "《史记·外戚世家》。索隐:“别也。”"}, {"t": "与武决去。", "b": "《汉书·李广苏建传》"}, {"t": "与侯生决。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "决去", "t": "辞别离去"}, {"w": "决别", "t": "诀别"}, {"w": "决舍", "t": "弃舍,离弃。"}]}, {"meaning": "决断,决定。", "cites": [{"t": "是天下之大决也。", "b": "《荀子·仲尼》。注:“谓决断之大也。”"}, {"t": "孔子不能决也。", "b": "《列子·汤问》"}, {"t": "吾计已决矣。", "b": "汉·刘向《列女传》"}, {"t": "吾计决矣。", "b": "《资治通鉴》"}, {"t": "决人死生。", "b": "清·刘开《问说》"}], "words": [{"w": "决平", "t": "公平决断讼狱"}, {"w": "决正", "t": "认为正确而依从"}, {"w": "决市", "t": "决定行市"}, {"w": "决志", "t": "拿定主意"}, {"w": "决制", "t": "控制。"}]}, {"meaning": "判决。", "cites": [{"t": "审决狱。", "b": "《淮南子·时则》"}, {"t": "不敢专决。", "b": "清·方苞《狱中杂记》"}, {"t": "一二人立决。", "b": ""}, {"t": "中有立决者。", "b": ""}, {"t": "法应立决。", "b": ""}], "words": [{"w": "决狱", "t": "审理判决案件"}, {"w": "决囚", "t": "判决死刑"}, {"w": "决杖", "t": "处以杖刑"}, {"w": "决配", "t": "判处流放"}, {"w": "决滞", "t": "判决积压的案件"}, {"w": "决宪", "t": "作出惩处的决定;定罪"}, {"w": "决知", "t": "审知辨识"}, {"w": "决理", "t": "审理判决。"}]}, {"meaning": "处死犯人。", "cites": [{"t": "每岁大决。", "b": "方苞《狱中杂记》"}], "words": [{"w": "决不待时", "t": "处决重刑犯不必等到秋后就可以执行死刑"}, {"w": "决囚", "t": "执行死刑"}, {"w": "决刑", "t": "执行死刑"}, {"w": "决期", "t": "处决死囚的日期。"}]}, {"meaning": "较量,分胜负。", "cites": [{"t": "办之者诚决。", "b": "《资治通鉴》"}, {"t": "与孟德决之。", "b": ""}], "words": [{"w": "决胜;决斗", "t": ""}]}, {"meaning": "一定,必定。", "cites": [{"t": "决负约。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "不敢也决矣。", "b": "唐·柳宗元《柳河东集》"}, {"t": "事有决无可疑者。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "决非天运。", "b": ""}], "words": [{"w": "决然", "t": "一定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('524wx','亥','1','hài','亠','6','','[{"pinyin": "hài", "defs": [{"meaning": "(象形。甲骨文字形,与“豕”的写法相似,象猪形。古代“亥”与“豕”很容易写混,成语:“鲁鱼亥豕”讲的就是这种误写现象。本义:猪)。"}, {"meaning": "同本义。", "cites": [{"t": "豕与亥相似。", "b": "《吕氏春秋·慎行论》"}, {"t": "亥,豕也。", "b": "《论衡·物势》"}, {"t": "亥即豕,故曰首曰身也。", "b": "《左传·襄公三十年》"}]}, {"meaning": "地支的末一位。"}, {"meaning": "与天干相配,用以纪年。"}, {"meaning": "用以纪月,农历十月为亥。"}, {"meaning": "与天干相配,用以纪日。"}, {"meaning": "用以纪时,即夜里九点至十一点。"}, {"meaning": "十二生肖属猪。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('525wx','充','1','chōng','亠','6','','[{"pinyin": "chōng", "defs": [{"meaning": "(会意。从儿,育省声。育子长大成人。本义:长,高)。"}, {"meaning": "同本义。", "cites": [{"t": "充,长也,高也。", "b": "《说文》"}, {"t": "宗人视牲告充。", "b": "《仪礼·特牲礼》"}]}, {"meaning": "满。", "cites": [{"t": "充,塞也。", "b": "《小尔雅》"}, {"t": "充,满也。", "b": "《广雅》"}, {"t": "冠盗充斥。", "b": "《左传·襄公三十一年》"}, {"t": "言充其阳也。", "b": "《谷梁传·庄公二十五年》"}, {"t": "颜色充盈。", "b": "《荀子·子道》"}], "words": [{"w": "充多", "t": "众多"}, {"w": "充车", "t": "满车;喻数量众多"}, {"w": "充房", "t": "满屋"}, {"w": "充堂", "t": "满堂。"}]}, {"meaning": "装满;塞满。", "cites": [{"t": "以充府库。", "b": "《周礼·大府》"}, {"t": "近之则钟音充。", "b": "《淮南子·说山》"}, {"t": "平生衣取蔽寒,食取充腹。", "b": "司马光《训俭示康》"}, {"t": "狗马实外厩,美人充下陈。", "b": "《战国策·齐策》"}], "words": [{"w": "充虚", "t": "填满肚子"}, {"w": "充肠", "t": "充肚。填饱肚子"}, {"w": "充庭", "t": "古代的一种朝仪。每大朝会,陈皇帝车马仪仗于殿庭。"}]}, {"meaning": "任职,充任;充当。", "cites": [{"t": "遂为猾胥报充里正役。", "b": "《聊斋志异·促织》"}, {"t": "半匹红绡一丈绫,系向牛头充炭直。", "b": "白居易《卖炭翁》"}], "words": [{"w": "充吏", "t": "在衙门内供职"}, {"w": "充任", "t": "担当某职务"}, {"w": "充位", "t": "克位。徒居其位,无所建树。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('526wx','妄','1','wàng','女','6','','[{"pinyin": "wàng", "defs": [{"meaning": "(形声。从女,亡声。本义:胡乱)。"}, {"meaning": "同本义。", "cites": [{"t": "妄,乱也。", "b": "《说文》"}, {"t": "不通于轻重谓之妄言。", "b": "《管子·山至数》"}, {"t": "以人自观谓之度,反度为妄。", "b": "《贾子道术》"}, {"t": "施妄者,乱之始也。", "b": "《春秋繁露》"}, {"t": "妄自菲薄。", "b": "诸葛亮《出师表》"}, {"t": "多求妄用。", "b": "宋·司马光《训俭示康》"}, {"t": "妄传伯夷。", "b": "清·黄宗羲《原君》"}, {"t": "毋妄发。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "妄口", "t": "胡说"}, {"w": "妄系", "t": "无故抓人入罪"}, {"w": "妄扳平人", "t": "胡乱牵连无辜之人"}, {"w": "妄施", "t": "随便地施恩"}, {"w": "妄折", "t": "无原则地屈从"}, {"w": "妄行", "t": "随便行动"}, {"w": "妄言", "t": "乱说。"}]}, {"meaning": "虚妄,极不真实。", "cites": [{"t": "妄,虚妄。", "b": "《广韵》"}, {"t": "此言妄也。", "b": "《论衡·问孔》"}, {"t": "故得妄誉。", "b": "《大戴礼记·文王官人》"}, {"t": "妄见之也。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "妄誉", "t": "不实的赞美"}, {"w": "妄诞", "t": "虚妄不实"}, {"w": "妄执", "t": "虚妄的执念。"}]}, {"meaning": "不法,胡作非为。", "cites": [{"t": "彼好专利而妄。", "b": "《左传·哀公二十五年》"}, {"t": "若再妄求,恐非后福。——《梼杌闲评——明珠缘》", "b": ""}], "words": [{"w": "妄诛", "t": "不当责罚而责罚;滥杀"}, {"w": "妄杀", "t": "乱杀"}, {"w": "妄作", "t": "无知而任意胡为"}, {"w": "妄进", "t": "非分图进。"}]}, {"meaning": "狂乱,毫无约束。", "cites": [{"t": "性悖妄。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "妄男子", "t": "狂妄无知的男子。"}]}, {"meaning": "荒谬,荒诞。", "cites": [{"t": "王因囚而问之,果妄,乃杀之。", "b": "《韩非子·外储说左上》"}, {"t": "妄以臆度。", "b": "清·刘开《问说》"}], "words": [{"w": "妄语", "t": "荒诞不合常理的话"}, {"w": "妄异", "t": "荒诞怪异"}, {"w": "妄妖", "t": "荒诞邪怪。"}]}, {"meaning": "相当于“凡”。平庸。", "cites": [{"t": "人谓魏勃勇,妄庸人耳,何能为乎!", "b": "《史记·齐悼惠王世家》"}], "words": [{"w": "妄庸", "t": "平庸凡劣"}, {"w": "妄匠", "t": "平庸的工匠"}, {"w": "妄尉", "t": "平庸的低级军官。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('527wx','闭','1','bì','门','6','','[{"pinyin": "bì", "defs": [{"meaning": "(会意。从门,从才。“才”是用来闭门的东西。本义:关门,把门合闭起来)。"}, {"meaning": "同本义。", "cites": [{"t": "闭,阖门也。", "b": "《说文》"}, {"t": "门常闭。", "b": "《墨子号令》"}, {"t": "先王以至,日闭关。", "b": "《易·象传》"}, {"t": "坚闭门而不出。", "b": "《庄子·天运》"}, {"t": "门已闭矣。", "b": "《左传·哀公十五年》"}, {"t": "古语所谓闭门造车,出门合辙,盖言其法之同也。", "b": "《礼记·中庸》"}], "words": [{"w": "闭扫", "t": "即闭门欲扫。指闭门谢客"}, {"w": "闭影", "t": "关门不与外界往来。"}]}, {"meaning": "泛指闭合,合拢。", "cites": [{"t": "愿陈子闭口,毋复言。", "b": "《史记·张仪列传》"}], "words": [{"w": "闭目;闭嘴;闭合电路;闭口结舌;闭卷", "t": "答题时不能查阅有关资料的考试方法。"}]}, {"meaning": "壅塞不通。", "cites": [{"t": "闭而不通。", "b": "《国语·晋语》"}], "words": [{"w": "闭绝", "t": "堵塞;杜绝"}, {"w": "闭心", "t": "闭绝欲望。"}]}, {"meaning": "禁绝。", "cites": [{"t": "礼者,所以闭淫也。", "b": "《史记·乐书》"}], "words": [{"w": "闭淫", "t": "禁绝邪淫"}, {"w": "闭钳", "t": "禁制"}, {"w": "闭籴", "t": "禁止输出,封闭其买入米谷的通道。"}]}, {"meaning": "门闩的孔。", "cites": [{"t": "不谨其闭,不固其门,虎乃将存。", "b": "《韩非子·主道》"}], "words": [{"w": "键闭", "t": ""}]}, {"meaning": "古时称立秋、立冬为“闭”,意即开始闭藏的气节。", "cites": [{"t": "凡分、至、启、闭,必书云物。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('528wx','问','1','wèn','门','6','','[{"pinyin": "wèn", "defs": [{"meaning": "(形声。从口,门声。本义:问,询问)。"}, {"meaning": "同本义。", "cites": [{"t": "问,讯也。", "b": "《说文》"}, {"t": "皇帝请问下民。", "b": "《书·吕刑》"}, {"t": "时聘曰问。", "b": "《周礼·大宗伯》"}, {"t": "小聘曰问。", "b": "《仪礼·聘礼》"}, {"t": "问人于他邦。", "b": "《论语》"}, {"t": "善问者如攻坚木。", "b": "《礼记·学记》"}, {"t": "问女何所思,问女何所忆。", "b": "《乐府诗集·木兰诗》"}, {"t": "问其故。", "b": "《列子·汤问》"}, {"t": "跪问其故。", "b": "《后汉书·列女传》"}, {"t": "景公问政孔子。", "b": "《史记·孔子世家》"}, {"t": "豹往到邺,会长老,问之民所疾苦。", "b": "《史记·滑稽列传》"}, {"t": "既克,公问其故。", "b": "《左传·庄公十年》"}, {"t": "笑问客从何处来。", "b": "唐·贺知章《回乡偶书》"}, {"t": "康肃问曰。", "b": "宋·欧阳修《归田录》"}, {"t": "公问不至。", "b": "《左传·庄公八年》"}], "words": [{"w": "到食堂问一下开饭的时间;问途", "t": "打听路径"}, {"w": "问信", "t": "打听消息"}, {"w": "问官答花", "t": "答非所问"}, {"w": "不耻下问;查问;发问;讯问;追问;自问;不懂就问;问字", "t": "称从人受学或请教为问字"}, {"w": "问岁", "t": "询问年岁的丰歉"}, {"w": "问禁", "t": "初入他国,问其政教上的禁令"}, {"w": "问遂", "t": "问路。遂,水中可涉的径路"}, {"w": "问对", "t": "问,发问"}, {"w": "问知", "t": "向有学问的人请教"}, {"w": "问俗", "t": "查访风俗"}, {"w": "问卦", "t": "以卜得的卦象来探求吉凶"}, {"w": "问经", "t": "学习或请教有关经书的问题"}, {"w": "问龟", "t": "占卜"}, {"w": "问课", "t": "请教课业。"}]}, {"meaning": "访问。", "cites": [{"t": "问士以璧。", "b": "《荀子·大略》。注:“谓访其国事。”"}, {"t": "天王使南季来聘。", "b": "《春秋·隐公九年》。《谷梁传》解释说:“聘,问也。”"}]}, {"meaning": "责问。", "cites": [{"t": "昭王南征而不复,寡人是问。", "b": "《左传·僖公四年》"}], "words": [{"w": "质问;诘问", "t": ""}]}, {"meaning": "问候;慰问。", "cites": [{"t": "伯牛有病,子问之。", "b": "《论语·雍也》"}, {"t": "齐王使使者问赵威后。", "b": "《战国策·齐策》"}, {"t": "周游城中,家家致问。", "b": "《三国志·吕蒙传》"}], "words": [{"w": "问牛", "t": "形容官吏关怀民间疾苦"}, {"w": "问疾", "t": "探视病情"}, {"w": "问慰", "t": "慰问"}, {"w": "问省", "t": "问侯尊长的起居"}, {"w": "问宁", "t": "问安"}, {"w": "问劳", "t": "问候慰劳。"}]}, {"meaning": "过问。", "cites": [{"t": "不问之秋。", "b": "唐·王勃《杜少府之任蜀州》"}, {"t": "今不问农蚕,而但以饱暖相矜耀。", "b": "清·章学诚《文史通义》"}]}, {"meaning": "审案,审讯。", "cites": [{"t": "每得降卒,必亲引问委曲。", "b": "《资治通鉴》"}], "words": [{"w": "审问;拷问;问头", "t": "对罪犯的起诉文书"}, {"w": "问拟", "t": "审问罪犯"}, {"w": "问结", "t": "审问结案"}, {"w": "问断", "t": "经过审问判了罪。"}]}, {"meaning": "追究。", "cites": [{"t": "引问委曲。", "b": "《资治通鉴·唐纪》"}, {"t": "按问其家。", "b": "明·张溥《五人墓碑记》"}, {"t": "是不必问。", "b": "清·全祖望《梅花岭记》"}, {"t": "不问罪之有无。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "问革", "t": "问罪罢官"}, {"w": "问遣", "t": "问罪发配。"}]}, {"meaning": "寻访。", "cites": [{"t": "后遂无问津者。", "b": "晋·陶潜《桃花源诗并记》"}]}, {"meaning": "告诉。", "cites": [{"t": "或以问孟尝君。", "b": "《战国策》"}]}, {"meaning": "周代诸侯国间的一种相互访问的礼节。", "cites": [{"t": "凡诸侯之邦交,岁相问也,殷相聘也,世相朝也。", "b": "《周礼》"}]}, {"meaning": "指书信。", "cites": [{"t": "既而羁寓京师,久无家问。", "b": "《晋书·陆机传》"}], "words": [{"w": "久无家问", "t": ""}]}, {"meaning": "权威性的命令,常由上级向下级发布。", "cites": [{"t": "公问不至。", "b": "《左传》"}]}, {"meaning": "声誉。", "cites": [{"t": "肆不殄厥愠,亦不陨厥问。", "b": "《诗·大雅·緜》"}, {"t": "遂得光誉令问于天下。", "b": "《墨子·非命下》"}, {"t": "因失吾问。", "b": "《庄子·庚桑楚》"}, {"t": "问丧于夫子乎?", "b": "《礼记·檀弓上》"}, {"t": "淑问扬乎疆外。", "b": "《汉书·匡衡传》。颜师古云:问,名也。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('529wx','闯','1','chuǎng','门','6','','[{"pinyin": "chuǎng", "defs": [{"meaning": "(会意。从马,从门。本义:猛冲,突然直入)。"}, {"meaning": "同本义。", "cites": [{"t": "闖,马出门貌。从马在门中。", "b": "《说文》"}, {"t": "开之则闯然公子阳生也。", "b": "《公羊传·哀公六年》。注:“出头貌。”"}], "words": [{"w": "闯堂;闯阵;闯亮", "t": "江湖隐语,指望风探哨"}, {"w": "闯寡门", "t": "去妓院吃茶而不嫖宿"}, {"w": "闯花门阚(嫖)小娘(嫖妓宿娼)", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('530wx','羊','1','yáng','羊','6','','[{"pinyin": "yáng", "defs": [{"meaning": "(象形。甲骨文字形,像羊头形。“羊”是汉字的一个部首。本义:一种哺乳动物)。"}, {"meaning": "同本义 。反刍类,以食草为生。一般头上有一对角,有许多品种。", "cites": [{"t": "羊,羊兽也。", "b": "《说文》。孔子曰:“半羊之字以形举也。”"}, {"t": "羊曰柔毛。", "b": "《礼记·曲礼》"}, {"t": "羊曰少牢。", "b": "《大戴礼记·少牢》"}, {"t": "食麦与羊。", "b": "《礼记·月令》"}, {"t": "兑为羊。", "b": "《易·说卦》"}, {"t": "杖汉节牧羊。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "羊群里跑出骆驼来", "t": "喻指平常的人忽然变成了出类拔萃的人物了"}, {"w": "羊群蚁阵", "t": "形容众多而聚集"}, {"w": "羊酒花红", "t": "丰厚的赏赐和显赫的荣耀"}, {"w": "羊车过市", "t": "比喻男子才美绝伦,引人羡慕注目"}, {"w": "羊耳风", "t": "羊角风"}, {"w": "羊脏", "t": "调侃语。指好胃口"}, {"w": "羊羔", "t": "酒名;羊羔酒,一种汾州产的糯米制白酒"}, {"w": "羊儿风", "t": "羊角风。"}]}, {"meaning": "十二生肖之一,与十二地支的未相配。", "cites": [{"t": "丑、未,亦土也。丑禽牛,未禽羊。", "b": "《论衡》"}]}, {"meaning": "吉利", "cites": [{"t": "有恐后世子孙,不能敬莙以取羊。", "b": "《墨子》"}, {"t": "羊吉万岁,子孙自贵。", "b": "《王孝渊碑》"}], "words": [{"w": "羊枣", "t": "果名,俗称“软枣。表示吉祥"}, {"w": "吉羊", "t": ""}]}, {"meaning": "细密;完备", "cites": [{"t": "臣愿王与下吏羊计某言而竺(笃)虑之也。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('531wx','并','1','bīng bìng','干','6','','[{"pinyin": "bīng", "defs": [{"meaning": "古地名。并州。"}, {"meaning": "相传禹治洪水,分天下为九州。并州为九州之一,其地在今河北保定、正定和山西大同、太原一带。沿用为太原的别称。"}, {"meaning": "汉置并州,其地在今内蒙古、山西(大部)、河北(一部)。东汉时并入冀州。三国魏复置。其地在今山西汾水中游。", "cites": [{"t": "并、汾乔木,望秋先陨。", "b": "宋·沈括《梦溪笔谈》"}]}]}, {"pinyin": "bìng", "defs": [{"meaning": "(会意。《说文》:“从二立。”金文字形,为二人并立之形。本义:并行,并列)。"}, {"meaning": "同本义。", "cites": [{"t": "並,併也。从二立,会意。今隶作並。", "b": "《说文》"}, {"t": "並行。", "b": "《仪礼·乡射礼》"}, {"t": "並立则乐。", "b": "《礼记·儒行》"}, {"t": "俄而並乎尧舜。", "b": "《荀子·儒效》"}, {"t": "並纽约用组。", "b": "《礼记·玉藻》"}, {"t": "並驱从两肩兮,揖我谓我儇兮。", "b": "《诗·齐风·还》"}, {"t": "並驾齐驱,而一毂统辐。", "b": "《文心雕龙·附会》"}, {"t": "且夫尧、舜、桀、纣千世而一出,是比肩并踵而生也。", "b": "《韩非子·难势》"}], "words": [{"w": "并列;并肩作战;并介", "t": "不论穷富,都能耿介于守。兼利天下叫并,孤介自守叫介"}, {"w": "并夹", "t": "古代习射时从箭靶上拔取箭头的工具"}, {"w": "并封", "t": "古代传说中的双头兽"}, {"w": "并心", "t": "同心。"}]}, {"meaning": "合并(由一部分与另一部分结合一起)。", "cites": [{"t": "并力西向。", "b": "苏洵《六国论》"}, {"t": "遂以周瑜,程普为左右督,将兵与备并力逆操。", "b": "《资治通鉴》"}, {"t": "并一而不二。", "b": "《荀子·儒效》"}, {"t": "凡五十五章并为苍颉篇。", "b": "《汉书·艺文志》"}, {"t": "今野兽并角。", "b": "《汉书·终军传》"}], "words": [{"w": "兼并", "t": "容纳合并"}, {"w": "并叠", "t": "收拢;拼凑"}, {"w": "并坐", "t": "谓因牵连而一并治罪"}, {"w": "并兼", "t": "合并;并吞。"}]}, {"meaning": "兼并;并吞。", "cites": [{"t": "秦初并天下。", "b": "《史记·秦始皇本纪》"}, {"t": "巨是凡人,偏在远郡,行将为人所并,岂足托乎!", "b": "《资治通鉴》"}, {"t": "魏并中山。", "b": "《战国策·中山策》"}], "words": [{"w": "并火", "t": "即“拼伙”。同伙拼杀"}, {"w": "并卷", "t": "兼并席卷。"}]}, {"meaning": "具备。", "cites": [{"t": "天下良辰美景赏心乐事,四者难并。", "b": "谢灵运《拟魏太子邺中集诗序》"}]}, {"meaning": "排除。", "cites": [{"t": "至贵,爵国并焉。", "b": "《庄子·天运》"}]}, {"meaning": "相同。", "cites": [{"t": "行与世异,心与欲并。", "b": "嵇康《卜疑集》"}]}, {"meaning": "全,全都。", "cites": [{"t": "黄发垂髫并怡然自乐。", "b": "陶渊明《桃花源记》"}, {"t": "二人并有愧色。", "b": "刘义庆《世说新语·言语》"}, {"t": "荣贼并非推心待慰帅者。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "并然", "t": "完全"}, {"w": "据我了解,事情并不是这样", "t": ""}]}, {"meaning": "一起;一齐;同时。", "cites": [{"t": "陈胜佐之,并杀两尉。", "b": "《史记·陈涉世家》"}, {"t": "刘备周瑜水陆并进。", "b": "《资治通鉴》"}], "words": [{"w": "并举;并日而食", "t": "两天只吃一天的饭"}, {"w": "并存不悖", "t": "同时存在而不冲突。"}]}, {"meaning": "并且,连。", "cites": [{"t": "杖至百,两股间浓血流离,并虫亦不能行捉矣。", "b": "《聊斋志异·促织》"}], "words": [{"w": "我们完全同意并拥护这个报告", "t": ""}]}, {"meaning": "和,以及。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('532wx','关','1','guān','丷','6','','[{"pinyin": "guān", "defs": [{"meaning": "(形声。从门,丱(guān)声。金文作“門”,象门里有门闩形,本象形字。小篆繁化,变成了形声字。本义:门闩)。"}, {"meaning": "门闩。闩门的横木。", "cites": [{"t": "关,以木横持门户也。", "b": "《说文》"}, {"t": "臧纥斩鹿门之关以出。", "b": "《左传·襄公二十三年》"}, {"t": "赢乃夷门抱关者也,而公子亲枉车骑,自迎赢于众人广坐之中。", "b": "《史记·魏公子列传》"}], "words": [{"w": "关牡", "t": "门闩。也叫门牡"}, {"w": "关楗", "t": "关闭门户用的横木或木闩"}, {"w": "关龠", "t": "门上横木。用来闩门。"}]}, {"meaning": "关口,隘门。", "cites": [{"t": "万里赴戎机,关山度若飞。", "b": "《乐府诗集·木兰诗》"}, {"t": "尝以十倍之地,百万之师,叩关而攻秦。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "关石", "t": "关口征赋所用的量器名"}, {"w": "关令", "t": "守关口的官吏。即关尹"}, {"w": "关梁", "t": "关口和桥梁。"}]}, {"meaning": "事物的枢纽或重要的转折点。", "cites": [{"t": "中有都柱,傍行八道,施关发机。", "b": "《后汉书·张衡传》"}], "words": [{"w": "关目", "t": "剧本或故事的情节。引申为演出"}, {"w": "关捩", "t": "机关"}, {"w": "关煞", "t": "旧时星象家称所谓命里注定的灾难"}, {"w": "关捩子", "t": "机关;机轴。"}]}, {"meaning": "人体的重要孔窍或肢体。", "cites": [{"t": "肾者,胃之关也。", "b": "《素问·水热穴论》"}], "words": [{"w": "三关", "t": "即耳、眼、口"}, {"w": "四关", "t": "即耳、眼、口、鼻"}, {"w": "关元", "t": "人体经穴名之一。在脐下三寸处"}, {"w": "关窍", "t": "人体的孔穴;诀窍,窍门。"}]}, {"meaning": "征收关税的机构、组织或程序。", "cites": [{"t": "昔者文王之治岐也,耕者九一,仕者世禄,关市讥而不征。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "验关;结关;关栈", "t": "税关所设置用来供未经通关的货物积存的仓库。也叫保税仓库。"}]}, {"meaning": "古代公文的一种。用于互相质询。", "cites": [{"t": "其上闻及移关诸部,犹未敢然。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "关牒", "t": "公文"}, {"w": "关报", "t": "用文书通知;禀报"}, {"w": "关白", "t": "禀报;通告"}, {"w": "关文札牒", "t": "古时官府颁行的文书或通行证件。"}]}, {"meaning": "合拢,闭门。", "cites": [{"t": "关,闭也。", "b": "《方言十二》"}, {"t": "关,界上之门也。", "b": "《周礼·司关》注"}, {"t": "园日涉以成趣,门虽设而常关。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "春色满园关不住。", "b": "叶绍翁《游园不值》"}], "words": [{"w": "关门吃饭", "t": "比喻一心一意过日子"}, {"w": "关门落闩", "t": "比喻到了顶峰,极限。"}]}, {"meaning": "贯通,贯穿。", "cites": [{"t": "见轮人以其杖关毂而转輠者。", "b": "《礼记·杂记下》"}, {"t": "其次关木索、被箠楚受辱。", "b": "《汉书·司马迁传》"}, {"t": "大臣括发关械、裸躬受笞。", "b": "《汉书·王嘉传》"}, {"t": "《春秋》五经,义相关穿。", "b": "汉·王充《论衡·程材》"}], "words": [{"w": "关穿", "t": "关联贯穿"}, {"w": "关通", "t": "贯通,沟通"}, {"w": "关合", "t": "贯通;吻合。"}]}, {"meaning": "牵连,涉及。", "cites": [{"t": "故天子一跬步,皆关民命,不可忽也。", "b": "《聊斋志异·促织》"}, {"t": "你说的何尝不是。但事关人命,……岂可因私枉法。", "b": "《红楼梦》"}], "words": [{"w": "关天", "t": "关系于天命"}, {"w": "关着", "t": "牵涉;别着,带着"}, {"w": "关接", "t": "接触"}, {"w": "关风", "t": "涉及风趣,有味。"}]}, {"meaning": "支领,领取。", "cites": [{"t": "三军尽关了粮赏。", "b": "《水浒》第五十五回"}], "words": [{"w": "关领", "t": "支取,领取"}, {"w": "关请", "t": "领取"}, {"w": "关支", "t": "领取;支出,发放"}, {"w": "关发", "t": "颁发;发放"}, {"w": "关饷", "t": "发薪金"}, {"w": "关给", "t": "发放,供给。"}]}, {"meaning": "引弓。", "cites": [{"t": "越人关弓而射之。", "b": "《孟子·告子下》"}, {"t": "豹则关矣。", "b": "《左传·昭公二十一年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('533wx','米','1','mǐ','米','6','','[{"pinyin": "mǐ", "defs": [{"meaning": "(象形,甲骨文字形。象米粒琐碎纵横之状。“米”是汉字的一个部首,从“米”的字与米、粮有关。本义:谷物和其他植物子实去壳后的子实)。"}, {"meaning": "同本义。", "cites": [{"t": "米,粟实也。象禾实之形。", "b": "《说文》。按,四注象米,十其介者,九谷之分也。"}, {"t": "米麜有虞氏之痒也。", "b": "《礼记·明堂位》"}], "words": [{"w": "粟米;花生米", "t": ""}]}, {"meaning": "特指稻米。", "cites": [{"t": "饷米千斛,修书累纸。", "b": "《世说新语·雅量》"}, {"t": "掌米粟之出入,辨其物。", "b": "《周礼·地官》"}], "words": [{"w": "米烂陈仓,财高北斗", "t": "白米烂在仓里,钱财高过北斗。形容极其富有"}, {"w": "米缆", "t": "用米粉制成的线状食品,亦称米线或米粉"}, {"w": "米行", "t": "经营粮食买卖的商行"}, {"w": "米泔", "t": "淘米水"}, {"w": "米粃", "t": "米之细糠"}, {"w": "米酒", "t": "用米酿制的酒"}, {"w": "米麦", "t": "米与麦。泛指米麦之类的粮食。"}]}, {"meaning": "喻极少或极小的量。犹点滴。", "cites": [{"t": "波漂菰米沉云黑,露冷莲房坠粉红。", "b": "杜甫《秋兴八首》"}], "words": [{"w": "米粒之珠", "t": "形容渺小"}, {"w": "米雪", "t": "小雪珠,霰的俗称"}, {"w": "米粒雪", "t": "米雪。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('534wx','灯','1','dēng','火','6','','[{"pinyin": "dēng", "defs": [{"meaning": "(形声。从火,登声。本写作“ 镫”。本义:置烛用以照明的器具。“镫”在古代还作“盛熟食的器具”解。隶变以后,作照明器具用的写作“燈”,而“镫”多作马鞍两旁的铁脚踏讲)。"}, {"meaning": "同本义。亦指通电发光的照明器具或做其他用途的发光器具。", "cites": [{"t": "月夜见渔灯,孤光一点萤。", "b": "清·查慎行《舟夜书所见》"}], "words": [{"w": "油灯;电灯;日光灯;信号灯;探照灯;灯法", "t": "使用灯烛所作的幻术。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('535wx','州','1','zhōu','川','6','','[{"pinyin": "zhōu", "defs": [{"meaning": "(会意。甲骨文字形,两边的曲折线象河流,中间象水中的陆地。“州”是“洲”的本字。小篆字形象两个“川”字相重合。本义:水中的陆地)。"}, {"meaning": "同本义", "cites": [{"t": "水中可居曰州。", "b": "《说文》"}]}, {"meaning": "字亦作洲。", "cites": [{"t": "在河之州。", "b": "《诗·周南·关雎》。毛本作“洲”。"}]}, {"meaning": "中国古地方行政区划名。相传禹治水后,分其领域为九州。 历代多有兴废。 民国废州。 有些地名仍沿用至今。", "cites": [{"t": "昔,尧遭洪水,民居水中高土,故曰九州。", "b": "《说文》。按,即禹贡之冀、兖、青、徐、扬、荆、豫、梁、雍也。舜分青为营州,分冀为幽州,并州,即虞书十二州也。禹平水土,还为九州。"}, {"t": "跨州连郡。", "b": "《三国志·诸葛亮传》"}, {"t": "南越中数州。", "b": "唐·柳宗元《柳河东集》"}, {"t": "虚吏白州。", "b": "唐·柳宗元《童区寄传》"}, {"t": "守州城者。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "中国古代户籍编制单位。", "cites": [{"t": "州,国也。", "b": "《广雅》"}, {"t": "二百一十国为州。州有伯。", "b": "《礼记·王制》"}, {"t": "五党为州。", "b": "《周礼·大司徒》。注:“二千五百家。”"}, {"t": "晋于是乎作州兵。", "b": "《左传·僖公十五年》"}, {"t": "虽州里行乎哉。", "b": "《论语》。郑注:“万二千五百家为州。”"}, {"t": "州十有二师焉。", "b": "《书大传》。注:“州凡四十三万二千家。”"}, {"t": "里十为州。又,术十为州。", "b": "《管子·度地》"}], "words": [{"w": "州乡", "t": "泛指乡里"}, {"w": "州壤", "t": "州里,乡里"}, {"w": "州巷", "t": "乡里。"}]}, {"meaning": "周代国名。"}, {"meaning": "姜姓。故域在今山东省安丘县东北。"}, {"meaning": "偃姓。故域在今湖北省监利县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('536wx','汗','1','hán hàn','氵','6','','[{"pinyin": "hán", "defs": [{"meaning": "可汗,古代鲜卑、柔然、突厥、回纥、蒙古等族对其统治者的称号。", "cites": [{"t": "汗,可汗。蕃王称。", "b": "《广韵》"}, {"t": "咸丰四年,土谢图汗、车臣汗两部汗、王、公、台吉等请捐助军需,温旨郤之。", "b": "《清史稿》"}]}]}, {"pinyin": "hàn", "defs": [{"meaning": "(形声。从水,干声。本义:汗腺的分泌物)。"}, {"meaning": "由人或高等动物皮肤内腺体分泌的一种含盐的液体。", "cites": [{"t": "汗,身液也。", "b": "《说文》"}, {"t": "汗者,精气也。", "b": "《素问·评热病论》"}, {"t": "五藏化液心为汗。", "b": "《宣明五气篇》"}, {"t": "出令如出汗,汗出而不反也。", "b": "《汉书·刘向传》"}, {"t": "汗衣,近身受汗垢 之衣也。", "b": "《释名·释衣服》"}, {"t": "汗出浃背。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "汗巾", "t": "擦汗用的手巾"}, {"w": "汗血", "t": "汗与血;流汗流血;汗出如血"}, {"w": "汗汪汪", "t": "形容汗水多的样子"}, {"w": "汗星", "t": "细小的汗珠"}, {"w": "汗迹", "t": "汗水的痕迹。"}]}, {"meaning": "旧时维吾尔族一些上层男子名字后面所加的称号 。亦作维吾尔族表示女性的称号,用在名字末尾。"}, {"meaning": "出汗;使出汗。", "cites": [{"t": "汗牛塞屋。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "汗下", "t": "汗流下来"}, {"w": "汗浸浸", "t": "微微出汗的样子"}, {"w": "汗溶溶", "t": "汗津津"}, {"w": "汗脱", "t": "出汗失水而虚脱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('537wx','污','1','wū','氵','6','','[{"pinyin": "wū", "defs": [{"meaning": "(形声。从水,于声。本义:停积不流的水)。"}, {"meaning": "浊水池。一说小水坑。", "cites": [{"t": "污,秽也,一曰小池为污。", "b": "《说文》"}]}, {"meaning": "字亦作汙。", "cites": [{"t": "潢汙行潦之水。", "b": "《左传·隐公三年》。服注:“水不流谓之汙。”"}, {"t": "故水郁则为汙。", "b": "《吕氏春秋·达郁》"}], "words": [{"w": "污池", "t": "蓄水的池子。"}]}, {"meaning": "污垢,脏东西。", "cites": [{"t": "污,秽也。", "b": "《一切经音义》"}, {"t": "川泽纳污。", "b": "《左传·宣公十五年》"}, {"t": "尽怀其余肉持去,衣尽污。", "b": "《史记·滑稽列传》"}, {"t": "血色罗裙翻酒污。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "粪污;去污粉;去污剂;污涂", "t": "泥泞;污泥"}, {"w": "污腻", "t": "污垢,肮脏。"}]}, {"meaning": "劳苦之事。", "cites": [{"t": "若子之群吏,处不辟污。", "b": "《左传》"}]}, {"meaning": "不清洁,肮脏。", "cites": [{"t": "汙,浊也。", "b": "《广雅·释诂三》"}, {"t": "濯淖污泥。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "污手垢面", "t": "手脸都很脏"}, {"w": "污面", "t": "面部污黑"}, {"w": "污乱", "t": "污秽淫乱"}, {"w": "污慢", "t": "污秽怠忽"}, {"w": "污言", "t": "脏话"}, {"w": "污邪", "t": "污秽邪恶"}, {"w": "污史", "t": "污秽的史 实"}, {"w": "污世", "t": "污浊混乱的世道。"}]}, {"meaning": "腐败的;社会风气、个人道德等恶劣、败坏的。", "cites": [{"t": "污吏。", "b": "《孟子·暴君》"}], "words": [{"w": "贪官污吏;污道", "t": "污邪之道"}, {"w": "污俗", "t": "恶习;坏风气"}, {"w": "污官", "t": "脏官。"}]}, {"meaning": "衰微的。", "cites": [{"t": "道隆则从而隆,道污则从而污。", "b": "《礼记》"}]}, {"meaning": "玷污。", "cites": [{"t": "殊不沾污。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "蔑污使君。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "污闻", "t": "玷污耳朵的听闻"}, {"w": "污累", "t": "玷污连累"}, {"w": "血污其衣;污坏", "t": "污染败坏"}, {"w": "污眼", "t": "弄脏眼睛。"}]}, {"meaning": "洗去污垢。", "cites": [{"t": "风吹云露火,雪污玉关泥。", "b": "李贺《送秦光禄北征》"}]}, {"meaning": "漫出,水超过约束物高限而流出。", "cites": [{"t": "…忽震一声,瓮悉列于梁上,都无滴污于外。", "b": "康骈《剧谈录》"}]}, {"meaning": "贪污。", "cites": [{"t": "以污贿不饬罢。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('538wx','江','1','jiāng','氵','6','','[{"pinyin": "jiāng", "defs": [{"meaning": "(形声。从水,工声。本义:长江的专称)。"}, {"meaning": "同本义。", "cites": [{"t": "江,江水也。?", "b": ""}, {"t": "江之永矣。", "b": "《诗·周南·汉广》"}, {"t": "滔滔江汉。", "b": "《诗·小雅·四月》"}, {"t": "江上几人在,天涯孤棹还。", "b": "温庭筠《送人东归》"}, {"t": "江间波浪兼天涌,塞上风云接地阴。", "b": "杜甫《秋兴八首》"}], "words": [{"w": "江汉", "t": "长江与汉水"}, {"w": "江水", "t": "即长江"}, {"w": "江左烟霞", "t": "江东的山水风景。江左指今江苏、安徽等长江沿江地带"}, {"w": "江陵", "t": "县名。在今湖北省中部偏南、长江沿岸。向为我国南北陆路交通要冲。"}]}, {"meaning": "江河的通称。", "cites": [{"t": "南方的河流多称“江”,如:“珠江”、“沅江”;北方的河流多称“河”,如:“洛河”、“渭河”、“漳河”", "b": ""}, {"t": "何江也?有丹徒大江,有钱塘浙江,有吴通陵江。", "b": "《论衡·书虚》"}, {"t": "至江,江上有一渔父乘船。", "b": "《史记·伍子胥列传》"}], "words": [{"w": "江口", "t": "江水与他水会流处"}, {"w": "江燕引雏", "t": "江边的燕子,为避灾祸,遂引雏燕弃巢而离去"}, {"w": "江州车儿", "t": "一种独轮推车。"}]}, {"meaning": "中国古国名 。嬴姓,在今河南正阳西南,公元前623年灭于楚。"}, {"meaning": "是中古州名 。晋置,辖境约当今江西全省并西延至湖北省武昌附近。后专指江西省九江一带。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('539wx','汛','1','xùn','氵','6','','[{"pinyin": "xùn", "defs": [{"meaning": "同本义。", "cites": [{"t": "汛,洒也。", "b": "《说文》。按,此字经传多误作汛滥之汛。"}, {"t": "汛埽反道。", "b": "《礼记·郊特性》"}, {"t": "汛拚席。", "b": "《管子·弟子职》"}, {"t": "况尽汛扫前圣数千载功业,专用己之私,而能享佑者哉?", "b": "《文选·扬雄·剧秦美新》"}], "words": [{"w": "汛扫", "t": "洒扫"}, {"w": "汛逐", "t": "清扫驱除。"}]}, {"meaning": "防守。", "cites": [{"t": "大军汛黄河而角其前,荆州下宛、叶而犄其后。", "b": "《三国演义》"}]}, {"meaning": "明清时称军队驻防地段。", "cites": [{"t": "三镇各释小嫌,共图大事,速速回汛,听候调谴。", "b": "清·孔尚任《桃花扇》"}]}, {"meaning": "又称:汛地。", "cites": [{"t": "须俟汛报紧急,先以分守之兵,统赴汛地。", "b": "明·李颐《条陈海防疏》"}], "words": [{"w": "汛弁", "t": "汛地官兵"}, {"w": "汛守", "t": "汛地防守岗位"}, {"w": "汛防", "t": "巡逻防守"}, {"w": "汛兵", "t": "汛地的士兵"}, {"w": "汛房", "t": "汛地营房。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('540wx','池','1','chí','氵','6','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从水,也声。本义:水停积处)。"}, {"meaning": "水塘。", "cites": [{"t": "池,停水曰池。", "b": "《广韵》"}, {"t": "穿地畜水,圆者曰池,方者曰塘。", "b": "《中文大辞典》"}, {"t": "池之竭矣。", "b": "《诗·大雅·召》"}, {"t": "或饮于池。", "b": "《诗·小雅·无羊》"}, {"t": "毋漉陂池。", "b": "《礼记·月令》。注::穿地通水曰池。”"}, {"t": "掌沟渎浍池之禁。", "b": "《周礼·雍氏》。注:“谓陂障之水道也。”"}, {"t": "囿有林池。", "b": "《国语·周语》"}, {"t": "有良田美池桑竹之属。", "b": "晋·陶渊明《桃花源记》"}, {"t": "鸟宿池边树,僧敲月下门。", "b": "唐·贾岛《题李凝幽居》"}], "words": [{"w": "游泳池;池苑", "t": "池林园。有池水与林木的地方"}, {"w": "池阁", "t": "位于池畔的楼阁。"}]}, {"meaning": "护城河 。城堡或其他筑垒地方围墙外面深而宽的壕沟,通常注满水。", "cites": [{"t": "城郭沟池以为固。", "b": "《礼记·礼运》"}, {"t": "城非不高也,池非不深也。", "b": "《孟子·公孙丑下》"}, {"t": "无水曰隍,有水曰池。", "b": "《易·泰虞》注"}, {"t": "汤池百步。", "b": "《汉书·食货志》"}, {"t": "自胡马窥江去后,废池乔木,犹厌言兵。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "池隍", "t": "古代掘土筑城,城下之地,有水称池,无水称隍。因以“池隍”借指城市。"}, {"w": "池堑", "t": "护城河。"}]}, {"meaning": "某些四周围起象水池形状的处所。", "cites": [{"t": "节方圆以定形,锻金铁而为池。", "b": "傅玄《砚赋》"}], "words": [{"w": "花池;舞池;池子", "t": "剧场正厅的座席"}, {"w": "乐池", "t": ""}]}, {"meaning": "衣被等物的缘饰。", "cites": [{"t": "池者,缘饰之名,今所谓被池装池是也。", "b": "《匡缪正误》"}], "words": [{"w": "池毡", "t": "有边缘缀饰的一种毛毡。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('541wx','汝','1','rǔ','氵','6','','[{"pinyin": "rǔ", "defs": [{"meaning": "(形声。从水,女声。本义:汝水)。"}, {"meaning": "同本义。", "cites": [{"t": "汝水出宏农卢氏,还归山东入淮。", "b": "《说文》。按,出今河南,至安徽入淮,为淮河支流"}]}, {"meaning": "你。"}, {"meaning": "多用于称同辈或后辈。", "cites": [{"t": "汝陟帝位。", "b": "《书·舜典》"}, {"t": "格汝众。", "b": "《书·盘庚上》"}, {"t": "汝父为楚王作剑。", "b": "晋·干宝《搜神记》"}, {"t": "汝亦知射乎。", "b": "宋·欧阳修《归田录》"}, {"t": "吾与汝毕力平险。", "b": "《列子·汤问》"}], "words": [{"w": "汝们", "t": "你们"}, {"w": "汝辈", "t": "你们"}, {"w": "汝等", "t": ""}]}, {"meaning": "以“汝”相称,表示彼此亲昵。", "cites": [{"t": "其市井小人昔与敬亭尔汝者,从道旁私语。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "汝尔", "t": "彼此以“汝尔”相称,表示不拘礼。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('542wx','汤','1','tāng tàng shāng','氵','6','','[{"pinyin": "tāng", "defs": [{"meaning": "(形声。从水,昜(yáng)声。本义:热水;开水)。"}, {"meaning": "同本义。", "cites": [{"t": "汤,热水也。", "b": "《说文》"}, {"t": "见不善如探汤。", "b": "《论语·季氏》"}, {"t": "薪火水汤以济之。", "b": "《墨子·备梯》"}, {"t": "日中如探汤。", "b": "《列子·汤问》"}, {"t": "踔出汤中。", "b": "晋·干宝《搜神记》"}, {"t": "王头随堕汤中。", "b": ""}, {"t": "分其汤肉葬之。", "b": ""}], "words": [{"w": "汤羊", "t": "经过开水处理的整只羊"}, {"w": "汤火", "t": "滚水与烈火"}, {"w": "汤炭", "t": "滚水与炭火"}, {"w": "汤婆子", "t": "充以热水放在被中取暖的铜制扁圆形容器"}, {"w": "汤浴", "t": "洗热水澡。"}]}, {"meaning": "煮东西的汁液,菜汤。", "cites": [{"t": "三日入厨下,洗手作羹汤。", "b": "唐·王建《新嫁娘》"}], "words": [{"w": "汤脚", "t": "剩汤"}, {"w": "汤玉", "t": "汤饼"}, {"w": "汤饭", "t": ""}]}, {"meaning": "汤池,护城河。", "cites": [{"t": "金汤失险,车书共道。", "b": "《后汉书》"}]}, {"meaning": "古州名。"}, {"meaning": "唐置,辖境在今越南的凉山、朗高、鸿基之间的地区。"}, {"meaning": "唐勃海置,金废。故治在今辽宁省辽中县东北。"}, {"meaning": "山名。"}, {"meaning": "在北京市昌平县东,有大小二汤山。大汤山三峰并峙。小汤山南有温泉。"}, {"meaning": "在南京市东,有温泉,建有浴池,为疗养地。"}, {"meaning": "温泉", "words": [{"w": "汤井", "t": "汤泉,温泉"}, {"w": "汤殿", "t": "温泉浴室"}, {"w": "汤池", "t": "温泉浴池"}]}, {"meaning": "姓。"}]}, {"pinyin": "tàng", "defs": [{"meaning": "加热。", "cites": [{"t": "疾之居腠理也,汤之所及也。", "b": "《扁鹊仓公列传》"}, {"t": "汤其酒百樽。", "b": "《山海经·西山经》"}], "words": [{"w": "汤羊", "t": "宰羊后,用开水煺毛"}, {"w": "汤桶", "t": "烫酒桶。"}]}, {"meaning": "触,碰。", "cites": [{"t": "那个有福的汤着他身儿,也情愿一个死。", "b": "明·冯梦龙《醒世恒言》"}, {"t": "你汤我一汤,拷了你那腰截骨。", "b": "石君宝《秋胡戏妻》"}]}, {"meaning": "遇上,碰上。", "cites": [{"t": "好道汤着饿鬼了。", "b": "《西游记》"}]}]}, {"pinyin": "shāng", "defs": [{"meaning": "水势浩大、水流很急的样子", "cites": [{"t": "衔远山,吞长江,浩浩汤汤,横无际涯。", "b": "范仲淹《岳阳楼记》"}, {"t": "东边是流水汤汤的延河,隔河是清凉山。", "b": "《歌声》"}]}, {"meaning": "广大貌;浩茫貌", "cites": [{"t": "心汤汤而谁告?魄寂寂而何语? ", "b": "南朝梁·沈约《待罪江南思北归赋》"}]}, {"meaning": "形容非常流利", "cites": [{"t": "别人拿上书去,汤汤的背了,号上书,正了字,好不省事。", "b": "《醒世姻缘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('543wx','忙','1','máng','忄','6','','[{"pinyin": "máng", "defs": [{"meaning": "(形声。从心,亡声。本义:急迫,慌忙)。"}, {"meaning": "同本义。", "cites": [{"t": "出门看火伴,火伴皆惊忙。", "b": "《木兰诗》"}], "words": [{"w": "急忙", "t": "心里着急,行动加快"}, {"w": "忙丢丢", "t": "急急忙忙"}, {"w": "忙不择价", "t": "匆忙出卖东西,就卖不到好价钱"}, {"w": "忙迫", "t": "仓皇迫促;忙碌紧张"}, {"w": "忙手忙脚", "t": "做事时心慌忙乱的样子"}, {"w": "忙促", "t": "匆忙急促;忙碌而紧张"}, {"w": "忙碌碌", "t": "匆忙急迫貌"}, {"w": "忙忙迭迭", "t": "十分匆忙的样子。"}]}, {"meaning": "事情多,繁忙。", "cites": [{"t": "田家少闲月,五月人倍忙。", "b": "白居易《观刈麦》"}], "words": [{"w": "忙工", "t": "在农忙时雇用的临时工"}, {"w": "忙事", "t": "忙碌的事"}, {"w": "忙上加忙", "t": "分外忙碌"}, {"w": "忙忙叨叨", "t": "忙忙碌碌"}, {"w": "忙忙", "t": "形容事务繁冗,不得空闲"}, {"w": "忙劫劫", "t": "忙忙碌碌;急急忙忙"}, {"w": "忙碌碌", "t": "事情多,不得闲。"}]}, {"meaning": "赶快;赶紧。", "cites": [{"t": "胡屠户忙躲进女儿房里,不敢出来。", "b": "《儒林外史》"}]}, {"meaning": "急于。", "cites": [{"t": "他那里正等的你火里火发,你不去,却忙惚儿来我这里缠。", "b": "《金瓶梅词话》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('544wx','兴','1','xīng xìng','八','6','','[{"pinyin": "xīng", "defs": [{"meaning": "(会意。从舁,从同。舁(yú),共举;同,同力。本义:兴起;起来)。"}, {"meaning": "同本义。", "cites": [{"t": "兴,起也。", "b": "《说文》"}, {"t": "夙兴夜寐。", "b": "《诗·卫风·氓》"}, {"t": "乃寝乃兴。", "b": "《诗·小雅·斯干》"}, {"t": "三岁不兴。", "b": "《易·同人》"}, {"t": "其言足以兴。", "b": "《礼记·中庸》"}, {"t": "风萧瑟而并兴兮,天惨惨而无色。", "b": "王璨《登楼赋》"}, {"t": "但国家兴自塑土,徒居平城。", "b": "《资治通鉴》"}, {"t": "大楚兴。", "b": "《史记·陈涉世家》"}, {"t": "兴利除弊。", "b": "宋·王安石《答司马谏议书》"}, {"t": "水波不兴。", "b": "明·魏学洢《核舟记》"}, {"t": "怨颇兴。", "b": "清·张廷玉《明史》"}], "words": [{"w": "兴居", "t": "起居"}, {"w": "兴辞", "t": "起立致辞"}, {"w": "兴寝", "t": "起卧"}, {"w": "兴舍", "t": "兴亡"}, {"w": "兴废", "t": "盛衰;兴亡"}, {"w": "兴毁", "t": "兴亡。"}]}, {"meaning": "使兴盛;流行。", "cites": [{"t": "——言可以兴邦,有诸?——《论语·子路》", "b": ""}, {"t": "稽其成败兴坏之纪。", "b": "司马迁《报任安书》"}, {"t": "叔父建中兴之业,在此行也。", "b": "《资治通鉴》"}, {"t": "俺院中规矩,不兴拜堂,就吃喜酒吧。", "b": "《桃花扇·眠香》"}, {"t": "兴复汉室。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "兴复之效。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "兴德之言。", "b": ""}], "words": [{"w": "兴国", "t": "振兴国家"}, {"w": "兴家", "t": "振兴门庭"}, {"w": "兴道,兴德", "t": "振兴道德"}, {"w": "兴跃", "t": "振兴"}, {"w": "兴化", "t": "振兴教化"}, {"w": "兴邦", "t": "使国家兴盛起来。"}]}, {"meaning": "开始办理;创办 。", "cites": [{"t": "百废具兴。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "兴立", "t": "创建"}, {"w": "兴作", "t": "着手进行,兴造制作"}, {"w": "兴事", "t": "兴建政事"}, {"w": "兴造", "t": "施工建造"}, {"w": "兴葺", "t": "兴修修理"}, {"w": "兴筑", "t": "兴建"}, {"w": "兴思", "t": "构思"}, {"w": "兴缮", "t": "兴修。"}]}, {"meaning": "推举;选拔。", "cites": [{"t": "进贤兴功,以作邦国。", "b": "《周礼·夏官·大司马》"}], "words": [{"w": "兴文", "t": "提倡文治"}, {"w": "兴氓", "t": "举荐民间人才"}, {"w": "兴能", "t": "推举有才能的人"}, {"w": "兴廉", "t": "推举廉士"}, {"w": "兴义", "t": "崇尚道义"}, {"w": "兴举", "t": "倡导。"}]}, {"meaning": "成功。", "cites": [{"t": "教备而不从者,非人也。其可兴乎!", "b": "《国语·楚语上》"}], "words": [{"w": "兴时", "t": ""}]}, {"meaning": "派遣;发动。", "cites": [{"t": "遽兴姜戎。", "b": "《左传·僖公三十三年》"}, {"t": "不敢兴兵。", "b": "《战国策·燕策》"}, {"t": "王兴甲兵。", "b": "《孟子·梁惠王上》"}, {"t": "兴师以与楚战。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "征发。", "cites": [{"t": "今者兴发不小,动而无成。", "b": "《资治通鉴》"}], "words": [{"w": "兴徭", "t": "征募役夫"}, {"w": "兴积", "t": "积聚。"}]}, {"meaning": "作。", "cites": [{"t": "凡小祭祀则不兴舞。", "b": "《周礼》"}], "words": [{"w": "兴贩", "t": "做买卖"}, {"w": "兴词构讼", "t": "告状;打官司"}, {"w": "兴福", "t": "造福"}, {"w": "兴舞", "t": "起舞"}, {"w": "兴树", "t": "造成"}, {"w": "兴喻", "t": "打比方。"}]}, {"meaning": "宠;惯。", "cites": [{"t": "都是你兴的他,我只和你算账就完了。", "b": "《红楼梦》"}]}, {"meaning": "蓬勃发展;兴旺。", "cites": [{"t": "汉室可兴。", "b": "《三国志·诸葛亮传》"}, {"t": "天保定尔,以莫不兴。", "b": "《诗·小雅·天保》"}, {"t": "国以民为兴坏。", "b": "《新书·大政》"}]}, {"meaning": "姓。"}]}, {"pinyin": "xìng", "defs": [{"meaning": "兴致,情趣。", "cites": [{"t": "遥呤俯畅,逸兴遄飞。", "b": "王勃《滕王阁序》"}, {"t": "兴尽悲来,识盈虚之有数。", "b": ""}, {"t": "兴尽晚归舟。", "b": "宋·李清照《如梦令》"}], "words": [{"w": "兴动", "t": "兴头高;高兴"}, {"w": "兴兴头头", "t": "兴致勃勃"}, {"w": "兴头子", "t": "兴致;兴趣"}, {"w": "兴辞", "t": "兴趣索然"}, {"w": "兴会", "t": "兴致;趣味"}, {"w": "兴头起意", "t": "起兴;动心"}, {"w": "兴子", "t": "兴致。"}]}, {"meaning": "诗歌表现手法之一。以他事引起此事叫起兴。又简称兴。", "cites": [{"t": "以及李杜元白诸大家,最多兴体。", "b": "清·洪亮吉《北江诗话一》"}], "words": [{"w": "兴喻", "t": ""}]}, {"meaning": "情欲。", "cites": [{"t": "兴来时,正遇乖亲过。", "b": "明·冯梦龙《桂枝儿》"}]}, {"meaning": "一种修辞手段,即比喻。", "cites": [{"t": "以乐语教国子,兴、道、讽、诵、言、语。", "b": "《周礼》"}], "words": [{"w": "兴道", "t": "比喻、启发。"}]}, {"meaning": "喜欢;喜爱。", "cites": [{"t": "你瞧他兴的这样儿!", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('545wx','宇','1','yǔ','宀','6','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从宀(mián),于声。“宀”表示房屋。本义:屋檐)。"}, {"meaning": "同本义。", "cites": [{"t": "宇,屋边也。", "b": "《说文》"}, {"t": "宇,屋檐也。", "b": "《一切经音义》引《说文》"}, {"t": "上栋下宇。", "b": "《易·系辞》"}, {"t": "八月在宇。", "b": "《诗·豳风·七月》。释文:“屋四垂为宇。”"}, {"t": "置于宇西阶上。", "b": "《仪礼·士丧礼》"}, {"t": "五帝庙同宇。", "b": "《汉书·郊祀志》"}, {"t": "而燕雀佼之,以为不能与之争于宇宙之间。", "b": "《淮南子·览冥》"}, {"t": "权起更衣,肃追于宇下。", "b": "《资治通鉴》"}], "words": [{"w": "宇堂", "t": "屋檐下的正房前"}, {"w": "宇达", "t": "屋檐和窗户"}, {"w": "宇溜", "t": "屋檐。"}]}, {"meaning": "房屋。", "cites": [{"t": "聿来胥宇。", "b": "《诗·大雅·緜》"}, {"t": "高堂邃宇。", "b": "《楚辞·招魂》"}, {"t": "惟恐琼楼玉宇,高处不胜寒。", "b": "苏轼《水调歌头》"}], "words": [{"w": "屋宇", "t": "房屋"}, {"w": "宇庭", "t": "屋室和庭院"}, {"w": "宇室", "t": "房舍。借指家庭。"}]}, {"meaning": "空间。上下四方,天地之间。", "cites": [{"t": "四方上下曰宇,古往今来曰宙。", "b": "《三苍》"}, {"t": "神覆宇宙。", "b": "《吕氏春秋·下贤》。注:“四方上下曰宇。以屋喻天地也。”"}, {"t": "威振八寓。", "b": "张衡《东京赋》。注:“八方区宇也。”"}, {"t": "云霏霏而承宇。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "宇甸", "t": "宇县,宇寰,宇宙。天下"}, {"w": "寰宇;宇内", "t": ""}]}, {"meaning": "地域;疆土。"}, {"meaning": "又。", "cites": [{"t": "复周公之宇。", "b": ""}, {"t": "或多难以固其国,启其疆土;或难以丧其国,失其守宇。", "b": "《左传·昭公四年》"}], "words": [{"w": "宇守", "t": "国土;疆土。"}]}, {"meaning": "国境。", "cites": [{"t": "不谋削人之野,不谋劫人之宇。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "住处。", "cites": [{"t": "其余以均分公侯伯子男,使各有宁宇。", "b": "《国语·周语》"}]}, {"meaning": "风度,仪容。", "cites": [{"t": "世以此定二王神宇。", "b": "《世说新语·雅量》"}], "words": [{"w": "器宇轩昂", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('546wx','守','1','shǒu','宀','6','','[{"pinyin": "shǒu", "defs": [{"meaning": "(会意。从宀,从寸。宀表示房屋;寸是法度。合起来表示掌管法度。本义:官吏的职责,职守)。"}, {"meaning": "同本义。", "cites": [{"t": "守,官守也。从门,寺府之事也。", "b": "《说文》。寺,廷也;府,文书藏也。"}, {"t": "五载一巡守。", "b": "《书·舜典》"}, {"t": "王巡虢守。", "b": "《左传·二十一年》"}, {"t": "均地守。", "b": "《周礼均人》。注:“地守,衡虞之属。”"}, {"t": "纠其守。", "b": "《周礼·内宰》。注:“宿卫者。”"}, {"t": "虽守者益。", "b": "《荀子·王制》。注:“谓地也。”"}, {"t": "官司之守,非君所及也。", "b": "《左传·隐公五年》"}, {"t": "我无官守,我无言责也。", "b": "《孟子·公孙丑下》"}]}, {"meaning": "节操;操守。", "cites": [{"t": "妾为情缘,葳蕤之质,一朝失守。", "b": "《聊斋志异》"}]}, {"meaning": "秦代郡的长官名,汉代更名太守。后时作州、府地方长官的省称。被委任在某一方或某一区域负责实施法律或管理的政府主要官员。", "cites": [{"t": "守者,秦置也。秦兼天下,置三川守。伊、河、洛也。", "b": "蔡邕《独断》"}, {"t": "袁有守多惠政,民甚爱之。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "郡守;吴起为河西守", "t": ""}]}, {"meaning": "州郡地方政府所在地。", "cites": [{"t": "维梁之西,其蔽曰某山,某守曰兴州。", "b": "唐·柳宗元《兴州江运记》"}]}, {"meaning": "遵守;奉行。", "cites": [{"t": "故治国无法则乱,守法而弗变则悖。", "b": "《吕氏春秋·察今》"}, {"t": "荆州守文,岂能作意表行事。", "b": "《世说新语·识鉴》"}, {"t": "某亦守法,与公甚相得也。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "守官箴", "t": "遵守为官之准则"}, {"w": "守古", "t": "遵守古训"}, {"w": "守数", "t": "恪守法规。"}]}, {"meaning": "坚持,保持;保守。", "cites": [{"t": "守成上文,遭祸右武,未有易此者也。", "b": "《汉书·公孙弘传》"}, {"t": "村南有夫妇守贫者,织纺井臼,估读勤苦,幸获名成。", "b": "清·周容《芋老人传》"}, {"t": "田横,齐之壮士,犹守义不辱。", "b": "《资治通鉴》"}], "words": [{"w": "守一", "t": "执一,专一"}, {"w": "守经", "t": "固守经典之义"}, {"w": "守常", "t": "遵循惯例,固守常法"}, {"w": "守义", "t": "固守义理,笃守正道"}, {"w": "守孀", "t": "守寡。孀:寡妇"}, {"w": "守着老一套;因循守旧;守恶", "t": "坚持邪恶"}, {"w": "守求", "t": "坚持索求"}, {"w": "守故", "t": "守旧;保持原状"}, {"w": "守成", "t": "继承和保持前人已有的成就和业绩"}, {"w": "守阙", "t": "承继皇位"}, {"w": "守真", "t": "保持真元;保持本性"}, {"w": "守拙", "t": "以拙自安,不愿做官。拙:拙于应付世务。"}]}, {"meaning": "看守,看管。", "cites": [{"t": "汤为儿守舍。", "b": "《史记·张汤传》"}, {"t": "如今我抬举你,去替那老军来守天王堂。", "b": "《水浒传》"}, {"t": "后汉使复至匈奴,常惠请其守者与俱,得夜见汉使。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "守钱虏", "t": "守财奴;财多而吝啬者"}, {"w": "守喜婆", "t": "接生婆"}, {"w": "守生", "t": "守候接生"}, {"w": "守梓", "t": "守灵"}, {"w": "守庚申", "t": "在庚申日吃斋、静坐不眠"}, {"w": "守制读礼", "t": "守丧并阅读有关丧祭的礼书。"}]}, {"meaning": "保卫;防守,与“攻”相对。", "cites": [{"t": "俾守我王。", "b": "《诗·小雅·十月之交》"}, {"t": "横野将军徐晃守江陵。", "b": "《资治通鉴》"}, {"t": "乃使蒙恬北筑长城而守藩篱。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "守把", "t": "把守;掌握"}, {"w": "守备", "t": "明清所设武官名称,负责城堡守卫及营房粮饷等事"}, {"w": "守政", "t": "关于防守的事务"}, {"w": "守口", "t": "把守关口"}, {"w": "守要", "t": "把守要隘"}, {"w": "守境", "t": "守卫边境"}, {"w": "守舍", "t": "看守门户。"}]}, {"meaning": "掌管。", "cites": [{"t": "地广,民众,万物多,故分五官而守之。", "b": "《商君书》"}]}, {"meaning": "收捕。", "cites": [{"t": "昭应闻此,必劝楚王益兵守雍氏。", "b": "《战国策》"}]}, {"meaning": "请求。", "cites": [{"t": "数守大将军光,为丁外人求侯。", "b": "《汉书》"}]}, {"meaning": "守侯;守护。", "cites": [{"t": "去来江口守空船,绕船月明江水寒。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "吾诚愿与汝相守以死。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "做郡的知州。", "cites": [{"t": "滕子京谪守巴陵郡。", "b": "范仲淹《岳阳楼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('547wx','宅','1','zhái','宀','6','','[{"pinyin": "zhái", "defs": [{"meaning": "(形声。从宀(mián),乇(zhé)声。本义:住所;住处)。"}, {"meaning": "同本义。", "cites": [{"t": "宅,所托居也。", "b": "小徐本《说文》"}, {"t": "上以厚,下安宅。", "b": "《易·象传》"}, {"t": "五亩之宅。", "b": "《孟子·梁惠王上》"}, {"t": "便利田宅。", "b": "汉·刘向《列女传》"}, {"t": "方宅十余亩。", "b": "晋·陶渊明《归园田居》"}, {"t": "岐王宅里寻常见。", "b": "唐·杜甫《江南逢李龟年》"}, {"t": "住近湓江地低湿,黄芦苦竹绕宅生。", "b": "白居易《琵琶行》"}], "words": [{"w": "卜宅", "t": "卜择住处建都地或葬地"}, {"w": "宅司", "t": "宅子;宅院"}, {"w": "宅券", "t": "房契"}, {"w": "宅相", "t": "住宅风水之相"}, {"w": "宅神", "t": "住宅里的神鬼"}, {"w": "宅屋", "t": "住房。"}]}, {"meaning": "家,常指大家族的家。", "cites": [{"t": "当日宁荣两宅,人口也极多,如何便萧索了呢?", "b": "《红楼梦》"}], "words": [{"w": "宅库", "t": "私家财库"}, {"w": "宅上", "t": "犹府上。敬称对方的家"}, {"w": "宅家", "t": "唐代对皇帝的一种称呼。也称官家"}, {"w": "宅田", "t": "古时官员告老还家,公家给以养老的禄田"}, {"w": "宅眷", "t": "家眷;家属。多指女眷。"}]}, {"meaning": "葬地。", "cites": [{"t": "大夫卜宅与葬日。", "b": "《礼记·杂记》"}], "words": [{"w": "宅兆", "t": "墓地。"}]}, {"meaning": "居,居住。", "cites": [{"t": "我王来,既爰宅于兹。", "b": "《书·盘庚上》"}], "words": [{"w": "宅居", "t": "居住"}, {"w": "宅土", "t": "居住在平地上;所居住的土地"}, {"w": "宅者", "t": "古代指退休家居的官员"}, {"w": "宅道", "t": "所居之界域"}, {"w": "宅中图大", "t": "居于中心,谋划四方。谓得地势之利。"}]}, {"meaning": "居于;处于某种境地。", "cites": [{"t": "使宅百揆。(使它居统领百官的位置。)", "b": "《书·舜典》"}, {"t": "王宅忧,亮阴三祀。", "b": "《书·说命上》"}], "words": [{"w": "宅忧", "t": "处于父母丧事期间。"}]}, {"meaning": "存。", "cites": [{"t": "宅心知训。", "b": "《书·康诰》"}], "words": [{"w": "宅心", "t": "用心,放在心上。"}]}, {"meaning": "托;寄托。", "cites": [{"t": "夫设情有宅,置言有位;宅情曰章,位言曰句。", "b": "《文心雕龙》"}], "words": [{"w": "宅生", "t": "犹言寄托生命。"}]}, {"meaning": "顺应,归顺。", "cites": [{"t": "亦惟助王宅天命,作新民。", "b": "《书·康诰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('548wx','字','1','zì','子','6','','[{"pinyin": "zì", "defs": [{"meaning": "(会意兼形声。从宀(mián)从子,子亦声。在屋内生孩子。本义:生孩子)。"}, {"meaning": "同本义。", "cites": [{"t": "字,乳也。", "b": "《说文》。"}, {"t": "字,生也。", "b": "《广雅》"}, {"t": "妇人疏字者子活,数乳者子死。", "b": "《论衡·气寿》"}, {"t": "六畜遂字。", "b": "《汉书》。颜师古注:“字,生也。”"}, {"t": "苦山有木,服之不字。", "b": "《山海经·中山经》"}, {"t": "亭有畜字马,岁课息。", "b": "《汉书·食货志下》"}], "words": [{"w": "字乳", "t": "生育"}, {"w": "字育", "t": "生育、蕃育。"}]}, {"meaning": "怀孕,体内怀着胎儿。", "cites": [{"t": "女子贞不字,十年乃字。", "b": "《易·屯》"}, {"t": "乘字牝者,傧而不得聚会。", "b": "《史记·平准书》"}], "words": [{"w": "字牝", "t": "怀孕的母畜"}, {"w": "字孕", "t": "怀胎;生殖"}, {"w": "字马", "t": "怀孕的马。"}]}, {"meaning": "抚养;养育;教养。", "cites": [{"t": "其僚无子,使字敬叔。", "b": "《左传》"}, {"t": "不能字人之孤而杀之。", "b": "《左传·成公十一年》"}, {"t": "牛羊腓字之。", "b": "《诗·大雅·生民》"}, {"t": "字而幼孩,遂而鸡豚。", "b": "柳宗元《种树郭橐驼传》"}], "words": [{"w": "字养", "t": "抚养;养育"}, {"w": "字民", "t": "养育人民"}, {"w": "字育", "t": "化生"}, {"w": "字孤", "t": "抚养孤儿。"}]}, {"meaning": "爱。", "cites": [{"t": "于父,不能字厥子。", "b": "《书·廉诰》"}, {"t": "乐王鲋字而敬。", "b": "《左传·昭公元年》。注:“字,爱也。”"}], "words": [{"w": "字孤", "t": "抚爱孤儿"}, {"w": "字爱", "t": "抚爱。"}]}, {"meaning": "教育;教课;传授知识。", "cites": [{"t": "天会间,充女直字学生,学问通达,观书史,工为诗。", "b": "《金史·温敦兀带传》"}]}, {"meaning": "治理。", "cites": [{"t": "防民之理甚周,而不至皎察;字民之方甚裕,而不至使侵蛑。", "b": "刘禹锡《答饶州之使君书》"}]}, {"meaning": "取名;取表字。", "cites": [{"t": "名余曰正则兮,字余曰灵均。", "b": "《楚辞·离骚》"}, {"t": "武字子卿。", "b": "《汉书·李广苏建传》"}, {"t": "张衡字平子。", "b": "《后汉书·张衡传》"}, {"t": "扣其乡及姓字。", "b": "明·魏禧《大铁椎传》"}]}, {"meaning": "女子许嫁。", "cites": [{"t": "甚至于说,待字的大姑娘,也得拿出来抽签。", "b": "茅盾《动摇》"}], "words": [{"w": "字人", "t": "女子嫁人。"}]}, {"meaning": "文字(古时单体叫文,合体叫字,后人逐渐不再严格区别)。", "cites": [{"t": "仓颉之初作书,盖依类象形,故谓之文,其后形声相益,即谓之字。文者物象本,字者言孳乳而浸多也。", "b": "《说文解字·叙》"}, {"t": "说五字之文,至于二三万言。", "b": "《汉书·艺文志》"}, {"t": "分文析字。", "b": "《汉书·刘歆传》"}, {"t": "象形、指事,文也,会意、谐声、转注,字也。", "b": "《通志·六书略》"}, {"t": "有奇字素无备者,旋刻之。", "b": "《梦溪笔谈·活板》"}], "words": [{"w": "字指", "t": "文字的含意"}, {"w": "字号", "t": "以文字作符号"}, {"w": "字音", "t": "文字的读音"}, {"w": "字格", "t": "书写文字的格式"}, {"w": "字债", "t": "文字的债务"}, {"w": "字学", "t": "文字学"}, {"w": "中国字,汉字;篆字;字脚", "t": "字眼"}, {"w": "字养", "t": "指用在某处的字眼。"}]}, {"meaning": "表字,人的别名(字和名常有意义上的联系。自称用名,表示谦虚;称人用字,表示尊敬)。", "cites": [{"t": "男子二十,冠而字。", "b": "《礼记·曲礼上》"}, {"t": "幼名,冠字。", "b": "《礼记·檀弓》。疏:“始生三月而加名,故去幼名;年二十,有为人父之道,朋友等类不可复呼其名,故冠顶加字。”"}, {"t": "闻名即知其字,闻字而知其名,盖名与字相比附故。", "b": "《白虎通·姓名》"}, {"t": "生而首上圩顶,故因名曰丘云。字仲尼,姓孔氏。", "b": "《史记·孔子世家》"}, {"t": "陈胜者,阳城人也,字涉。", "b": "《史记·陈涉世家》"}]}, {"meaning": "名号。", "cites": [{"t": "季子谢之,请问姓字。", "b": "《论衡·书虚》"}]}, {"meaning": "用文字写成的凭据、字条或短柬。", "cites": [{"t": "杨执中又写了一个字去催权勿用见这字,收拾搭船来湖州。", "b": "《儒林外史》"}], "words": [{"w": "字据;立字为凭", "t": ""}]}, {"meaning": "书法 。文字的书写艺术;特指用毛笔写汉字的艺术。", "cites": [{"t": "又有李元中,字画之工,追踪钟王。", "b": "宋·王明清《挥麈三录》"}]}, {"meaning": "书法作品。", "cites": [{"t": "原来是问金冬心的字,我拿去卖了。", "b": "巴金《秋》"}, {"t": "专藏字,不藏画", "b": ""}]}, {"meaning": "书信。", "cites": [{"t": "亲朋无一字,老病有孤舟。", "b": "杜甫《登岳阳楼》"}, {"t": "托敝亲家写一封字来。", "b": "《儒林外史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('549wx','安','1','ān','宀','6','','[{"pinyin": "ān", "defs": [{"meaning": "(会意。从“女”在“宀”下,表示无危险。本义:安定;安全;安稳)。"}, {"meaning": "同本义。", "cites": [{"t": "安,定也。", "b": "《尔雅》"}, {"t": "共给之为安。", "b": "《庄子·天地》"}, {"t": "好和不争曰安。", "b": "《周书·谥法》"}, {"t": "心皆安下切上。", "b": "《仪礼·少牢礼》"}, {"t": "是故君子安而不忘危。", "b": "《易·系辞下》"}, {"t": "居安思危。", "b": "《左传·襄公十一年》"}, {"t": "风雨不动安如山。", "b": "杜甫《茅屋为秋风所破歌》"}, {"t": "然后得一夕安寝。", "b": "宋·苏洵《六国论》"}, {"t": "谢庄遂安。", "b": "清·徐珂《清稗类钞·战事类》。"}], "words": [{"w": "安睡;安寝;安抵", "t": "平安地抵达"}, {"w": "心神不安;坐立不安;安枕", "t": "安安稳稳地睡觉"}, {"w": "安帖", "t": "安定;平静;妥帖"}, {"w": "安席", "t": "安稳地坐着;安静入睡。"}]}, {"meaning": "安逸,安乐。", "cites": [{"t": "予出官二年,恬然自安。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "君子食无求饱,居主安。", "b": "《论语·学而》。"}], "words": [{"w": "安佚", "t": "安闲舒适"}, {"w": "安堵", "t": "安居,不受骚扰"}, {"w": "安坦", "t": "安心舒坦。"}]}, {"meaning": "安宁。", "cites": [{"t": "毅良久稍安。", "b": "唐·李朝威《柳毅传》。"}], "words": [{"w": "安生", "t": "安宁"}, {"w": "安豫", "t": "安宁快乐"}, {"w": "安淳", "t": "安宁淳朴"}, {"w": "安休", "t": ""}]}, {"meaning": "缓慢。", "cites": [{"t": "安步以当车。", "b": "《战国策·齐策四》。"}], "words": [{"w": "安步", "t": "缓步徐行"}, {"w": "安行", "t": ""}]}, {"meaning": "使安定。", "cites": [{"t": "与魏质以安其心。", "b": "《韩非子·存韩》"}, {"t": "可以为富安天下。", "b": "汉·贾谊《论积贮疏》"}, {"t": "安身立命。", "b": "明·李渔《闲情偶寄·种植部》。"}], "words": [{"w": "安神", "t": "使心神安定"}, {"w": "安国", "t": "安邦定国;安定的邦国"}, {"w": "安民", "t": "安定人民生活"}, {"w": "安邦", "t": "安定国家"}, {"w": "安内", "t": "安定内部。"}]}, {"meaning": "安抚,安顿抚慰。", "cites": [{"t": "若备与彼协心,上下齐同,则宜抚安。", "b": "司马光《资治通鉴》。"}], "words": [{"w": "安存", "t": "安抚存恤"}, {"w": "安恤", "t": "安抚体恤"}, {"w": "定人", "t": "安抚人民"}, {"w": "安辑", "t": "安抚。"}]}, {"meaning": "安排;安置。", "cites": [{"t": "离山十里有王平安营。", "b": "《三国演义》。"}], "words": [{"w": "安席", "t": "入座敬酒"}, {"w": "安座", "t": "安席。"}]}, {"meaning": "安心。习惯、满足于。", "cites": [{"t": "始而惭焉,久而安焉。", "b": "清·黄宗羲《原君》"}, {"t": "郊境之内,民不安业。", "b": "《三国志·司马郎传》。"}], "words": [{"w": "安于现状;安业", "t": "安于本业"}, {"w": "安命", "t": "顺从命运安排。"}]}, {"meaning": "安装。", "cites": [{"t": "今水大而急,不得安柱。", "b": "诸葛亮《与兄瑾言赵云烧赤崖阁书》。"}], "words": [{"w": "安电灯;安刀把儿", "t": ""}]}, {"meaning": "表示疑问,相当于“岂”、“怎么”。", "cites": [{"t": "尔安敢轻吾射。", "b": "宋·欧阳修《归田录》"}, {"t": "安与项伯有故。", "b": "《史记·项羽本纪》"}]}, {"meaning": "“安培”的简称。"}, {"meaning": "谁;何;什么。", "cites": [{"t": "安忠?忠王。安信?信赏。安敢?敢去不善。", "b": "《孙膑兵法·纂卒》"}, {"t": "皮之不存,毛将安附?", "b": "《左传·僖公十四年》"}, {"t": "吾谷为难,安始而可?", "b": "《国语·晋语》"}]}, {"meaning": "哪里,何处。", "cites": [{"t": "沛公安在?", "b": "《汉书·高帝纪》"}, {"t": "安在公子能急人之困。(即“公子能急人之困安在”。)", "b": "《史记·魏公子列传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('550wx','讲','1','jiǎng','讠','6','','[{"pinyin": "jiǎng", "defs": [{"meaning": "(形声。从言,冓(gōu)声。本义:和解)。"}, {"meaning": "同本义。", "cites": [{"t": "讲,和解也。", "b": "《说文》"}, {"t": "而秦未与魏讲也。", "b": "《战国策·西周策》"}, {"t": "与魏讲罢兵。", "b": "《史记·樗里子甘茂传》"}, {"t": "以中情出,小曰閒,大曰讲。", "b": "《大载礼记·千乘》"}, {"t": "卒使公子池以三城讲于三国,之兵乃退。", "b": "《战国策·秦策》"}, {"t": "引兵而归,因使人索六城于赵而讲。", "b": "《战国策·赵策》"}], "words": [{"w": "讲息", "t": "和解息争"}, {"w": "讲贡", "t": "讲和纳贡"}, {"w": "讲款", "t": "讲和,议款"}, {"w": "讲盟", "t": "订盟媾和。"}]}, {"meaning": "讲习(共同讨论研习学问)。", "cites": [{"t": "道士讲火经。", "b": "唐·李朝威《柳毅传》"}, {"t": "讲中外之故。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "讲颂", "t": "讲习诵读"}, {"w": "讲读", "t": "讲习诵读"}, {"w": "讲肄", "t": "讲习"}, {"w": "讲肆", "t": "讲舍"}, {"w": "讲贯", "t": "讲习"}, {"w": "讲帷", "t": "讲堂"}, {"w": "讲筵", "t": "讲席;讲坛。筵:古人席地而坐所铺的席。"}]}, {"meaning": "练习;操练。", "cites": [{"t": "田猎以讲武。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "讲武", "t": "讲习武艺。"}]}, {"meaning": "用。", "cites": [{"t": "邀见讲钧礼。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('551wx','讳','1','huì','讠','6','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从言,韦声。本义:避忌。有顾忌而躲开某些事或不说某些话)。"}, {"meaning": "同本义。", "cites": [{"t": "讳,誋也。", "b": "《说文》"}, {"t": "讳,避也。", "b": "《广雅·释诂三》"}, {"t": "卒哭乃讳。", "b": "《礼记·曲礼》"}, {"t": "舍故而讳新。", "b": "《礼记·檀弓》"}, {"t": "昭王之忌讳。", "b": "《周礼·小史》"}, {"t": "讳名不讳姓。", "b": "《孟子·尽心下》"}, {"t": "《春秋》为尊者讳,为亲者讳,为贤者讳。", "b": "《公羊传·闵公元年》"}], "words": [{"w": "直言不讳;讳名", "t": "对尊长避免说写其名,表示尊敬的心意"}, {"w": "讳恶", "t": "先王的名讳与国家的凶恶"}, {"w": "讳亡", "t": "忌言亡国。"}]}, {"meaning": "隐;隐蔽。", "cites": [{"t": "恐犯忌而干讳。", "b": "《楚辞·谬谏》。注:“所隐为讳。”"}], "words": [{"w": "讳疾", "t": "隐瞒缺失"}, {"w": "讳匿", "t": "隐匿;藏匿"}, {"w": "讳过", "t": "隐瞒过错或失误"}, {"w": "讳恶不悛", "t": "隐恶不改悔。"}]}, {"meaning": "畏,怕。", "cites": [{"t": "击断无讳。", "b": "《史记·范蔡传》"}, {"t": "不讳强大。", "b": "《战国策·秦策》。注:“犹辟也。”"}]}, {"meaning": "忌讳的事情。", "cites": [{"t": "有公讳。", "b": "《礼记·玉藻》"}, {"t": "入门而问讳。", "b": "《礼记·曲礼上》"}], "words": [{"w": "犯讳", "t": ""}]}, {"meaning": "旧时指死去的帝王或尊长的名字。", "cites": [{"t": "汉讳武帝名“彻”为通。", "b": "韩愈《讳辩》"}, {"t": "子厚讳宗元。", "b": "韩愈《柳子厚墓志铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('552wx','军','1','jūn','冖','6','','[{"pinyin": "jūn", "defs": [{"meaning": "(会意。金文字形,从车,从勹(bāo,包裹)。表示用车子打包围圈的意思。古代打仗主要靠车战,驻扎时,用战车围起来形成营垒,以防敌人袭击。本义:围成营垒)。"}, {"meaning": "同本义。", "cites": [{"t": "军,圜围也。", "b": "《说文》"}, {"t": "军,围也。", "b": "《广雅》"}, {"t": "军于庐柳。", "b": "《国语·晋语》"}]}, {"meaning": "注:“犹屯兵粮储也。”。", "cites": [{"t": "疏而不可蹙,数而不可军者,在于慎。", "b": "《银雀山汉墓竹简》"}]}, {"meaning": "攻杀。", "cites": [{"t": "凡盗贼军,乡邑及家人,杀之无罪。", "b": "《周礼》"}]}, {"meaning": "指挥作战。", "cites": [{"t": "祝聃射中王肩,王亦能军。", "b": "《左传·桓公五年》"}, {"t": "建德不能军,以百余骑走饶阳。饶阳无备,因取之。", "b": "《新唐书》"}]}, {"meaning": "从军。", "cites": [{"t": "越国女,尚耍白猿,教俺替爷军。", "b": "明·徐渭《雌木兰》"}]}, {"meaning": "军队。", "cites": [{"t": "击破沛公军。", "b": "《史记·项羽本纪》"}, {"t": "虽入军无忿争之心。", "b": "《韩非子·解老》"}, {"t": "亮身率诸军攻祁山。", "b": "《三国志·诸葛亮传》"}, {"t": "两军人马杂遝。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "英法联军。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "敌军已近寨。", "b": ""}, {"t": "军中发枪之号。", "b": ""}], "words": [{"w": "军变", "t": "军队哗变"}, {"w": "军流", "t": "充军流放"}, {"w": "军律", "t": "军法,军纪"}, {"w": "军门", "t": "军中长官、总督、将帅等;营门;衙署。"}]}, {"meaning": "军队的编制单位 。古代以军为军队中最大的编制单位。春秋时各大国多设上、中、下三军,历代沿用其名,人数多少不一。", "cites": [{"t": "五旅为师,五师为军。", "b": "《周礼·小司徒》"}, {"t": "万有二千五百人为军。", "b": "《周礼·夏官·序官》"}, {"t": "万人为一军。", "b": "《国语·齐语》。注:“齐制也。”"}, {"t": "全军为上。", "b": "《孙子·谋攻》"}, {"t": "破军次之。", "b": ""}], "words": [{"w": "歼敌一个军;军主", "t": "主一军,一军的主帅"}, {"w": "军副", "t": "一军之副将。"}]}, {"meaning": "士兵。", "cites": [{"t": "军皆殊死战。", "b": "《史记·淮阴侯列传》"}]}, {"meaning": "中国宋代行政区划名。与府、州、监同属于路。", "cites": [{"t": "奉化军节度。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "今为宋江军。", "b": ""}]}, {"meaning": "唐于设兵戍守之地 ,设置“军”、“守捉”、“镇”、“戍”等。安史之乱后,内地也设“军”。如汴州设宣武军。“军”与“守捉”的将领称使;“镇”与“戍”的将领称镇将。"}, {"meaning": "阵地。", "cites": [{"t": "战士军前半死生,美人帐下犹歌舞。", "b": "唐·高适《燕歌行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('553wx','讶','1','yà','讠','6','','[{"pinyin": "yà", "defs": [{"meaning": "(形声。从言,牙声。本义:迎接)。"}, {"meaning": "同本义。", "cites": [{"t": "讶,相迎也。从言,牙声。周礼曰,诸侯有卿讶发。按,乍接必以言,故从言,俗字作迓。周官有讶士,有掌讶。", "b": "《说文》"}, {"t": "跛者讶跛者。", "b": "《公羊传·成公二年》"}, {"t": "从者讶受皮。", "b": "《仪礼·公食大夫礼》。注:“迎也。”"}, {"t": "厥明,讶宾于馆。", "b": "《仪礼·聘礼》"}], "words": [{"w": "讶客", "t": "迎接宾客"}, {"w": "讶宾", "t": "迎宾。"}]}, {"meaning": "诧异,感到意外。", "cites": [{"t": "若夫道德,则不然,无讶无訾。", "b": "《吕氏春秋·必已》"}], "words": [{"w": "讶奇", "t": "惊奇。"}]}, {"meaning": "责怪。", "cites": [{"t": "本欲往见,以下痢乏力,未果,想未讶也。", "b": "苏轼《与郭功父》"}]}, {"meaning": "(yù)。称人之美。", "cites": [{"t": "若夫道德则不然,无讶无訾,一龙一蛇,与时俱化,而无肯专为。", "b": "《吕氏春秋·必己》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('554wx','许','1','xǔ','讠','6','','[{"pinyin": "xǔ", "defs": [{"meaning": "(形声。从言,午声。本义:应允,许可)。"}, {"meaning": "同本义。", "cites": [{"t": "许,听也。", "b": "《说文》。按,听从其言也。"}, {"t": "王子许。", "b": "《吕氏春秋·首时》。注:“诺也。”"}, {"t": "亟请于武公,公弗许。", "b": "《左传·隐公元年》"}, {"t": "[某]知公大贤,许我伐无道之君如何?", "b": "《武王伐纣平话》"}, {"t": "尔不许我,我乃屏璧与圭。", "b": "《书·金滕》"}, {"t": "杂然相许。", "b": "《列子·汤问》"}, {"t": "其许寡人。", "b": "《战国策·魏策》"}, {"t": "不可不许。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "遂许先帝以驱驰。", "b": "诸葛亮《出师表》"}], "words": [{"w": "特许;只许成功,不许失败;准许;默许;许认", "t": "同意,承认"}, {"w": "许肯", "t": "应允"}, {"w": "许允", "t": "答应。"}]}, {"meaning": "同意,赞同。", "cites": [{"t": "每自比于管仲、乐毅,时人莫之许也。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "事先答应给予。", "cites": [{"t": "秦王度之,终不可强夺,遂许斋五日。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "把我二姨儿许给皇粮庄头张家,指腹为婚。", "b": "《红楼梦》"}], "words": [{"w": "许香愿", "t": "对神佛有所祈求时,提出事后给予的某种酬谢"}, {"w": "许人", "t": "应允与人"}, {"w": "许字", "t": "许配,许婚,许嫁。都指允婚。"}]}, {"meaning": "期望。", "cites": [{"t": "塞上长城空自许,镜中衰鬓已先斑。", "b": "宋·陆游《书愤》"}], "words": [{"w": "许身", "t": "立志,自我期许。"}]}, {"meaning": "相信。", "cites": [{"t": "则王许之乎?", "b": "《孟子·梁惠王上》。赵岐注:“许,信也。”"}]}, {"meaning": "给予;奉献。", "cites": [{"t": "老母在,政身未敢以许人也。", "b": "《史记·剌客列传》"}], "words": [{"w": "以身相许;以身许国", "t": "许国:为国效命。"}]}, {"meaning": "处所,地方。", "cites": [{"t": "地里又远关山阻,无计奈,谩登楼,空目断,故人何许?", "b": "《西厢记诸宫调》"}, {"t": "不知何许人。", "b": "明·魏禧《大铁椎传》"}]}, {"meaning": "古国名 。公元前十一世纪周分封的诸侯国。姜姓。战国初期为楚所灭。一说灭于魏。故地在今河南省许昌东。"}, {"meaning": "表示大约的数量。", "cites": [{"t": "如是十许字。", "b": "宋·洪迈《容斋续笔》"}, {"t": "引之长丈许。", "b": "《聊斋志异·促织》"}]}, {"meaning": ":表示约略估计的数量。", "cites": [{"t": "赴河死者五万许人。", "b": "《后汉书》"}, {"t": "自富阳至桐庐一百许里。", "b": "吴均《与朱元思书》"}, {"t": "潭中鱼可百许头。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "这样,这般。", "cites": [{"t": "这江南方腊,起义已久,即渐而成,不想弄到许大事业。", "b": "《水浒传》"}, {"t": "世间那有千寻竹,月落庭空影许长。", "b": "宋·苏轼《次韵答文与可见寄》"}], "words": [{"w": "许些", "t": "许多"}, {"w": "许大", "t": "这样大;偌大;很大"}, {"w": "许来大", "t": "许大"}, {"w": "许大粗", "t": "这么大、这么粗。"}]}, {"meaning": "何,什么。", "cites": [{"t": "知君书记本翩翩,为许从容赴朔边?", "b": "唐·杜审言《赠苏绾书记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('555wx','讹','1','é','讠','6','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从言,化声。字本作“譌”。本义:谣言)。"}, {"meaning": "同本义。", "cites": [{"t": "譌,伪言也。", "b": "《说文》"}]}, {"meaning": "字亦作“讹”。", "cites": [{"t": "民之讹言。", "b": "《诗·小雅·沔水》"}, {"t": "讹言大水至。", "b": "《汉书·成帝纪》"}], "words": [{"w": "讹言", "t": "谣言。"}]}, {"meaning": "改变;感化。", "cites": [{"t": "或降于阿,或饮于池,或寝或讹。", "b": "《诗·小雅·无羊》"}]}, {"meaning": "变化。", "cites": [{"t": "式讹尔心。", "b": "《诗·小雅·节南山》"}, {"t": "岁月迁讹,斯风渐笃。", "b": "《通志》"}]}, {"meaning": "不正确的。", "cites": [{"t": "平秩南讹。", "b": "《书·尧典》"}], "words": [{"w": "讹音", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('556wx','论','1','lún lùn','讠','6','','[{"pinyin": "lún", "defs": [{"meaning": "《论语》的简称 。内容主要是记录孔子及其门徒的言行。"}]}, {"pinyin": "lùn", "defs": [{"meaning": "(形声。从言,仑(lún)声。本义:评论,研究。引申为“议论”)。"}, {"meaning": "议论, 分析和说明事理。", "cites": [{"t": "论,议也。", "b": "《说文》"}, {"t": "论理也,次也。", "b": "《论语序集解》"}, {"t": "坐而论道。", "b": "《周礼·考工记》。注:“谓谋虑治国之政令也。”"}, {"t": "臣请论其故。", "b": "《史记·张仪传》"}, {"t": "留连论诗。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "与蒙论议。", "b": "《资治通鉴·汉纪》"}, {"t": "每与臣论此事。", "b": "诸葛亮《出师表》"}, {"t": "十几人论议。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "论道", "t": "讲论治国道术"}, {"w": "论黄数黑", "t": "议论是非曲直"}, {"w": "论冒", "t": "相当于八股文中的“破题”,有“开宗明义”之意。"}]}, {"meaning": "思;思考。", "cites": [{"t": "论之思之,至于再三。", "b": "《汉书·王莽传》"}]}, {"meaning": "衡量;评定。", "cites": [{"t": "论其刑赏。", "b": "诸葛亮《出师表》"}, {"t": "闻言必熟论。", "b": "《吕氏春秋·慎行论》"}], "words": [{"w": "论功行赏", "t": ""}]}, {"meaning": "评论;辩析。", "cites": [{"t": "相国论河套。", "b": "清·侯方域《壮悔堂文集》"}]}, {"meaning": "又。", "cites": [{"t": "已而论河套。", "b": ""}], "words": [{"w": "论思", "t": "论辩思虑"}, {"w": "论理", "t": "论说道理"}, {"w": "论口", "t": "争论;斗嘴。"}]}, {"meaning": "判罪;判决。", "cites": [{"t": "会论虞常。", "b": "《汉书·李广苏建传》"}, {"t": "袁溥论瑞。", "b": "清·张廷玉《明史》"}, {"t": "舒华论瑞迂。", "b": "《明史》"}], "words": [{"w": "论囚", "t": "判刑"}, {"w": "论输", "t": "论其罪而罚其役。"}]}, {"meaning": "考虑;顾及。", "cites": [{"t": "食物不论,力气是不惜的。", "b": "鲁迅《彷徨·祝福》"}], "words": [{"w": "论平", "t": "考虑公正平和。"}]}, {"meaning": "较量。", "cites": [{"t": "我与一百斤大刀,却与那先生论么?", "b": "《三国志平话》"}]}, {"meaning": "控告,举报。", "cites": [{"t": "那里有令史勾结强贼理,如今世上媳妇论丈夫的稀。", "b": "元·李致远《还牢末》"}]}, {"meaning": "凭借。", "cites": [{"t": "想相如凭舌剑压秦国,论胆量完璧而回,乃股肱忠烈之士。", "b": "元·高文秀《渑池会》楔子"}]}, {"meaning": "说;陈述。", "cites": [{"t": "无论魏晋。", "b": "晋·陶渊明《桃花源记》"}, {"t": "弃者无论。", "b": "清·袁枚《黄生借书说》"}, {"t": "论天下事。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "又不可论。", "b": ""}], "words": [{"w": "相提并论;又当别论", "t": ""}]}, {"meaning": "研究。", "cites": [{"t": "论世之事。(论,研究、探讨。)", "b": "《韩非子·五蠹》"}]}, {"meaning": "又如:论演(研究阐发);论道经邦(研究治国之道,以治理好国家);论思(研究思想)。"}, {"meaning": "选择。", "cites": [{"t": "权节其用,论比协材。", "b": "《国语·齐语》"}, {"t": "论贤人,用有能,而民可使治。", "b": "《管子·五辅》"}]}, {"meaning": "治理。", "cites": [{"t": "云雷屯,君子以经论。", "b": "《易·屯》"}, {"t": "屡陈时政,经论治体。", "b": "《三国志·魏书·任苏杜郑仓传》"}]}, {"meaning": "主张;学说。", "cites": [{"t": "论笃是与,君子者乎,色庄者乎?", "b": "《论语·先进》"}, {"t": "余不妄,独持迂论。", "b": "徐光启《甘薯疏序》"}], "words": [{"w": "相对论;原子论;方程论", "t": ""}]}, {"meaning": "议论文。", "cites": [{"t": "论也者,弥纶群言,而研一理者也。", "b": "《文心雕龙·论说》"}], "words": [{"w": "《六国论》;《过秦论》", "t": ""}]}, {"meaning": "伦理。", "cites": [{"t": "於论鼓钟!", "b": "《诗·大雅·灵台》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('557wx','讼','1','sòng','讠','6','','[{"pinyin": "sòng", "defs": [{"meaning": "(形声。从言,公声。从言的字与讲话有关。本义:争论)。"}, {"meaning": "同本义。", "cites": [{"t": "讼,争也。…以手曰争,以言曰讼。", "b": "《说文》"}, {"t": "讼不亲也。", "b": "《易·杂卦》"}, {"t": "饮食必有讼。", "b": "《易·序卦》"}, {"t": "会礼之家,名为聚讼。", "b": "《后汉书·曹褒传》"}], "words": [{"w": "聚颂纷纭;讼辩", "t": "争辩"}, {"w": "讼斗", "t": "争斗"}, {"w": "讼怨", "t": "争吵怨恨"}, {"w": "讼直", "t": "申辩是非曲直"}, {"w": "讼争", "t": "争辩,争吵"}, {"w": "讼罪", "t": "争辩无罪"}, {"w": "讼曲", "t": "争论是非曲直。"}]}, {"meaning": "打官司。", "cites": [{"t": "讼,《六书故》:争曲直于官有司也。", "b": "《正字通》"}, {"t": "争罪曰狱,争财曰讼。", "b": "《周礼·地官》注"}, {"t": "有狱讼者。", "b": "《周礼·大司徒》。注:“争财曰讼。”"}, {"t": "争宝之讼解。", "b": "张协《七命》"}, {"t": "又某氏以不孝讼其子,左右邻械系入老监,号呼达旦。", "b": "清·方苞《狱中杂记》"}, {"t": "子曰:“听讼吾犹人也,必也使无讼乎!”", "b": "《论语·颜渊》"}], "words": [{"w": "讼牒", "t": "讼状"}, {"w": "讼事", "t": "诉讼之事"}, {"w": "讼理", "t": "讼事处理恰当"}, {"w": "讼狱", "t": "诉讼之事"}, {"w": "讼庭", "t": "公堂法庭"}, {"w": "讼学", "t": "专门讲究诉讼案件之学堂"}, {"w": "讼地", "t": "为争地而打官司。"}]}, {"meaning": "喧哗。", "cites": [{"t": "亲谗谀而疏贤圣兮,讼谓闾娵为丑恶。", "b": "汉·东方朔《七谏·怨世》"}]}, {"meaning": "为人辩冤。", "cites": [{"t": "汉武帝杀戾太子,田千秋讼太子冤。", "b": "宋·洪迈《容斋随笔》"}, {"t": "(莽)在国三岁,吏上书讼冤莽者以百数。", "b": "《汉书·王莽传》"}], "words": [{"w": "讼冤", "t": "申辩冤屈"}, {"w": "讼屈", "t": "申冤,辩冤。"}]}, {"meaning": "歌颂。", "cites": [{"t": "一国为之讼。", "b": "《韩非子·孤愤》"}, {"t": "深讼莽功德。", "b": "《汉书·王莽传上》"}, {"t": "家给人足,讼声并作。", "b": "《易林·否之大有》"}]}, {"meaning": "诉讼者。", "cites": [{"t": "政以慈爱为主,劝两讼勿争,词致殷重。", "b": "宋·叶适《故枢密参政汪公墓志铭》"}]}, {"meaning": "公开地,明白地。", "cites": [{"t": "夫有形埒者,天下讼见之;有篇籍者,世人传学之。", "b": "《淮南子·兵略》"}, {"t": "太尉尚恐不胜诸吕,未敢讼言诛之。", "b": "《史记·吕太后纪》"}], "words": [{"w": "讼言", "t": "公开地说"}, {"w": "讼刑", "t": "审慎用刑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('558wx','农','1','nóng','冖','6','','[{"pinyin": "nóng", "defs": [{"meaning": "(会意。甲骨文字形,从林,从辰。古代森林遍野,如要进行农耕,必先伐木开荒,故从“林”;古代以蜃蛤的壳为农具进行耕耨,故从“辰”。小篆认为从晨,囟(xìn)声。从“晨”,取日出而作、日入而息之意。本义:耕,耕种) 同本义。", "cites": [{"t": "农,耕也。", "b": "《说文》。按,耕必作于晨,故从晨。"}, {"t": "辟土植谷曰农。", "b": "《汉书·食货志》"}, {"t": "农,天下之大本也。", "b": "《汉书·文帝纪》"}, {"t": "贫生于不足,不足生于不农。", "b": "晁错《论贵粟疏》"}, {"t": "殴民而归之农。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "农家子", "t": "村野耕作之人"}, {"w": "农舆", "t": "耕作用的车"}, {"w": "农战", "t": "从事农耕,以为攻战之本"}, {"w": "农月", "t": "立夏以后农事的忙月。"}]}, {"meaning": "努力,勉力。", "cites": [{"t": "小人农力以事其尚。", "b": "《左传·襄公十三年》"}]}, {"meaning": "农业。", "cites": [{"t": "方今之务,莫若使民务农而已矣。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "务农", "t": "从事农业生产"}, {"w": "农田水利;农林牧;农末", "t": "农业和商业"}, {"w": "农政", "t": "有关农业的政令、制度"}, {"w": "农书", "t": "有关农业的书。"}]}, {"meaning": "农民。", "cites": [{"t": "士农工商,四民有业。", "b": "《汉书·食货志上》"}, {"t": "待农而食。", "b": "《史记·货殖列传》"}]}, {"meaning": "又。", "cites": [{"t": "农不出则乏。", "b": ""}], "words": [{"w": "自耕农;小农", "t": "个体农民"}, {"w": "老农;花农;菜农;果农;奶农", "t": ""}]}, {"meaning": "古代的田官。", "cites": [{"t": "飨农。", "b": "《礼记·郊特牲》"}], "words": [{"w": "农正", "t": "古官名。掌农事及农祈"}, {"w": "农父", "t": "古官名。司徒的尊称"}, {"w": "农师", "t": "古官名。掌农事。"}]}, {"meaning": "先秦学术思想流派之一,九流中“农家”的简称。"}, {"meaning": "勤勉。", "cites": [{"t": "耕者用力不农,有罪无赦。", "b": "《管子·大匡》"}]}, {"meaning": "浓厚。", "cites": [{"t": "农用八政。", "b": "《书·洪范》。郑玄:“农读为醲”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('559wx','讽','1','fěng','讠','6','','[{"pinyin": "fěng", "defs": [{"meaning": "(形声。从言,风声。本义:背诵;朗读;传诵)。"}, {"meaning": "同本义。", "cites": [{"t": "讽,诵也。", "b": "《说文》"}, {"t": "兴道讽诵言语。", "b": "《周礼·大司乐》。注:“倍文曰讽,以声节之曰诵。”"}, {"t": "少不讽。", "b": "《荀子·大略》。注:“谓就学讽诗书也。”按,诗风雅颂三类,以风为之,风借为讽。"}, {"t": "今我讽遗文,思人至其乡。", "b": "唐·白居易《游襄阳怀孟浩然》"}, {"t": "三藏就合掌讽起斋经。", "b": "《西游记》"}], "words": [{"w": "讽味", "t": "诵读诗文而玩索其中的意味"}, {"w": "讽经", "t": "念经"}, {"w": "讽书", "t": "背书"}, {"w": "讽术", "t": "背诵经艺。"}]}, {"meaning": "婉言微辞或指责。", "cites": [{"t": "讽,谏也。", "b": "《广雅》"}, {"t": "论礼有五,谏讽为上。", "b": "《后汉书·李云传》"}, {"t": "后迁侍中,帝引在帷幄,讽议左右。", "b": "《后汉书·张衡传》"}, {"t": "岂其愤世疾邪者耶?而托于柑以讽耶?", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "规劝。", "cites": [{"t": "而呤咏情性,以讽某上。", "b": "《文心雕龙》"}], "words": [{"w": "讽谏", "t": "用委婉的话来劝谏"}, {"w": "讽诫", "t": "讽谏告诫"}, {"w": "讽一劝百", "t": "辞赋之文,旨在讽谏,故因一事而起讽,以百事劝戒为终结。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('560wx','设','1','shè','讠','6','','[{"pinyin": "shè", "defs": [{"meaning": "(会意。从言,从殳。本义:摆设;陈列)。"}, {"meaning": "同本义。", "cites": [{"t": "設,施陈也。", "b": "《说文》"}, {"t": "钟鼓既设。", "b": "《诗·小雅·彤弓》"}, {"t": "整设于门外。", "b": "《礼记·月令》。注:“陈也。”"}, {"t": "规矩陈设。", "b": "《礼记·经解》"}, {"t": "张乐设饮。", "b": "《战国策·秦策》"}, {"t": "入其舍,则密室垂帘,帘外设香几。", "b": "《聊斋志异·促织》"}, {"t": "设树险阻。", "b": "《淮南子·本经》"}, {"t": "设酒杀鸡作食。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "陈设", "t": "摆设"}, {"w": "设醮修禳", "t": "僧道为禳除灾祟而设的道场"}, {"w": "设蓍", "t": "占卦。蓍:蓍草,古人常用其占卜"}, {"w": "设弧", "t": "摆设木弓。表示生男"}, {"w": "设帨", "t": "摆设佩巾。表示生女"}, {"w": "设奠", "t": "陈设祭品,追悼亡者"}, {"w": "设醴", "t": "设置甘美的醴酒。比喻礼遇贤士。"}]}, {"meaning": "创立,建立,开创。", "cites": [{"t": "权之所设。", "b": "《公羊传·桓公十一年》。注:“设,施也。”"}, {"t": "设都于禹之绩。", "b": "《诗·商颂·殷武》"}, {"t": "其后齐中衰,管子修之,设轻重九府。", "b": "《史记·货殖列传序》"}], "words": [{"w": "附设", "t": "附带设置"}, {"w": "设令", "t": "施设律令"}, {"w": "设位", "t": "立位,定位"}, {"w": "设官", "t": "设置官职"}, {"w": "设科", "t": "设立教授的学科;设置取士任官的科目"}, {"w": "设帐", "t": "开馆教授门徒"}, {"w": "设版", "t": "构筑防御工事以备敌"}, {"w": "设险", "t": "在险要地方设置防御"}, {"w": "设覆", "t": "设置伏兵。"}]}, {"meaning": "筹划;秘密策划。", "cites": [{"t": "设以攻宋。", "b": "《淮南子·修务》"}, {"t": "吾必设计先除此二人。", "b": "《三国演义》"}], "words": [{"w": "设阱", "t": "设计陷害别人"}, {"w": "想方设法;设谋", "t": "设定谋略"}, {"w": "设计", "t": "算计;谋划"}, {"w": "设局", "t": "设下骗局;安排圈套"}, {"w": "设施", "t": "安排;措置"}, {"w": "设处", "t": "筹划,安排。"}]}, {"meaning": "拟设;设置。", "cites": [{"t": "岂设君之道固如是乎?", "b": "清·黄宗羲《原君》"}], "words": [{"w": "设疑", "t": "提出疑问"}, {"w": "设论", "t": "文体名。拟设问答来阐扬论述的意旨"}, {"w": "设难", "t": "拟定问题铺设言辞,以困窘对方"}, {"w": "设辩", "t": "拟设辩说"}, {"w": "设言托意", "t": "拟设言语来寄寓心意。"}]}, {"meaning": "施行,实现。", "cites": [{"t": "各一则不设。", "b": "《吕氏春秋》"}], "words": [{"w": "设教", "t": "施行教化。"}]}, {"meaning": "布置,部署。", "cites": [{"t": "赵亦盛设兵以待秦,秦不敢动。", "b": "《史记》"}]}, {"meaning": "表示假设关系,相当于“如果”、“假如”。", "cites": [{"t": "设以炮至,吾村不齑粉乎?", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "设若;设使", "t": ""}]}, {"meaning": "完备。", "cites": [{"t": "居处,兵卫甚设。", "b": "《史记·刺客列传》"}]}, {"meaning": "大。", "cites": [{"t": "益长裕而不设。", "b": "《易·系辞下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('561wx','访','1','fǎng','讠','6','','[{"pinyin": "fǎng", "defs": [{"meaning": "(形声。从言,方声。本义:广泛地征求意见)。"}, {"meaning": "同本义。", "cites": [{"t": "訪,泛谋也。", "b": "《说文》"}, {"t": "訪,谋也。", "b": "《尔雅》"}, {"t": "王访于箕子。", "b": "《书·洪范》"}, {"t": "访予落止。", "b": "《诗·周颂·访落》"}, {"t": "受纳访", "b": "《周礼·内史》"}, {"t": "使访物官。", "b": "《国语·楚语》"}, {"t": "穆公访诸蹇叔。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "访断", "t": "咨询决疑"}, {"w": "访覃", "t": "问及"}, {"w": "访讯", "t": "讯问;打听。"}]}, {"meaning": "引申为访问、拜访(敬词)。", "cites": [{"t": "此行殊访戴,自可缓归桡。", "b": "李白《陪从祖济南太守泛鹊山湖》"}, {"t": "时余方访君寓。", "b": "清·梁启超《谭嗣同传》"}, {"t": "径造庐访成。", "b": "《聊斋志异·促织》"}], "words": [{"w": "访戴", "t": "访友的代称"}, {"w": "出访", "t": "到外国访问"}, {"w": "回访", "t": "在对方来拜访后去拜访对方"}, {"w": "过访", "t": "访问"}, {"w": "走访", "t": "访问;拜访"}, {"w": "造访", "t": "上门访问。"}]}, {"meaning": "寻求。", "cites": [{"t": "访风景于崇阿。", "b": "王勃《滕王阁序》"}, {"t": "至唐李渤始访其遗踪。", "b": "宋·苏轼《石钟山记》"}, {"t": "使人访其夫妇,载以来。", "b": "清·周容《芋老人传》"}], "words": [{"w": "寻访", "t": "寻求查访"}, {"w": "访觅", "t": "访寻;寻找"}, {"w": "访论稽古", "t": "探求讨论古事。"}]}, {"meaning": "初始。", "cites": [{"t": "访以吕氏故,几乱天下。", "b": "《汉书》"}]}, {"meaning": "谋议。", "cites": [{"t": "教之令,使访物官。", "b": "《国语》。韦昭注:“访,议也。物,事也。使议知百官之事业。”"}]}, {"meaning": "调查;查处。", "cites": [{"t": "又九门提督所访缉纠诘,皆归刑部。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "访缉", "t": "访查缉捕"}, {"w": "访办", "t": "调查处理"}, {"w": "访俗", "t": "察访民俗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('562wx','诀','1','jué','讠','6','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从言,夬(guài)声。本义:辞别,告别。特指长别)。"}, {"meaning": "同本义。", "cites": [{"t": "与死者辞曰诀。", "b": "《通俗文》"}, {"t": "相诀而去。", "b": "《史记·孔子世家》"}, {"t": "与王诀曰。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "诀妻子。", "b": "《明史》"}, {"t": "梦汝来诀。", "b": "清·袁枚《祭妹文》"}, {"t": "早知诀汝。", "b": ""}], "words": [{"w": "诀行", "t": "告别而行"}, {"w": "诀去", "t": "话别离去"}, {"w": "诀音", "t": "遗言"}, {"w": "诀绝", "t": "诀别,长别。"}]}, {"meaning": "自杀。", "cites": [{"t": "帝大怒,遂赐后死,逼令引诀。", "b": "《周书·宣帝杨皇后传》"}, {"t": "未能引诀。", "b": "《隋书·薛道衡传》"}, {"t": "天元大怒,遂赐后死,逼令引诀。", "b": "《资治通鉴·陈宣帝太建十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('563wx','寻','1','xún','寸','6','','[{"pinyin": "xún", "defs": [{"meaning": "(会意。从工口,从又(彐)寸。本义:八尺为寻) 中国古代的一种长度单位,八尺为寻。", "cites": [{"t": "尋,绎理也。", "b": "《说文》。度人之两臂为寻,八尺也。"}, {"t": "寻,长也。周官之法,度广为寻。", "b": "《方言一》"}, {"t": "是寻是尺。", "b": "《诗·鲁颂·閟宫》。传:“八尺曰寻。”"}, {"t": "舒肘知寻。", "b": "《大戴礼记·主言》"}, {"t": "度寻舒两肱也。", "b": "《小尔雅》"}, {"t": "蹄间三寻。", "b": "《史记·张仪传》。索隐:“七尺曰寻。按,程氏瑶田云,度广曰寻,度深曰仞。皆伸两臂为度。度广则身平臂直,而适得八尺;度深则身侧臂曲,而仅得七尺。其说精巧,寻仞皆以两臂度之,故仞亦或言八尺,寻亦或言七尺也。”"}, {"t": "争寻常以尽其民。", "b": "《左传·成公十二年》"}, {"t": "无寻尺之禄。", "b": "《国语·晋语》"}, {"t": "千寻铁锁沉江底。", "b": "《三国演义》"}, {"t": "深逾寻丈。", "b": "[英]赫胥黎著、严复译《天演论》"}]}, {"meaning": "寻找。", "cites": [{"t": "远寻师学。", "b": "《后汉书·列女传》"}, {"t": "寻向所志。", "b": "晋·陶渊明《桃花源记》"}, {"t": "寻视其侧。", "b": "《徐霞客游记·游黄山记》"}, {"t": "寻其方面。", "b": "《后汉书·张衡传》"}], "words": [{"w": "寻事", "t": "找岔子;招惹"}, {"w": "寻门路不着", "t": "托人情找不着门路"}, {"w": "寻瑕索瘢", "t": "寻找缺陷"}, {"w": "寻疵责人", "t": "喻故意挑剔毛病,指责他人"}, {"w": "寻孔讨气", "t": "找岔子生气"}, {"w": "寻宿儿", "t": "投宿。"}]}, {"meaning": "探究;研究;推求。", "cites": [{"t": "一一皆可寻其源。", "b": "苏轼《王维吴道子画》"}], "words": [{"w": "寻事", "t": "寻思;考虑"}, {"w": "寻朱数墨", "t": "只知道背诵文句,不明白道理"}, {"w": "寻省", "t": "推求省察。"}]}, {"meaning": "用。", "cites": [{"t": "寻,用也。", "b": "《小尔雅》"}, {"t": "日寻干戈。", "b": "《左传·昭公元年》"}, {"t": "将寻斧柯。", "b": "《孔子家语·观周》"}, {"t": "寻网求食,利在昏夜:此蜘蛛也。", "b": "《三国演义》"}, {"t": "三年将寻师焉。", "b": "《左传·僖公五年》"}], "words": [{"w": "寻戈", "t": "动用兵力"}, {"w": "寻斧", "t": "用斧"}, {"w": "寻师", "t": "用兵。"}]}, {"meaning": "继续。", "cites": [{"t": "及武侯死后,夫人寻逝,临终遗教,惟以忠孝勉其子瞻。", "b": "《三国演义》"}, {"t": "有利必有害,有损必有益,相纠相寻,至于无尽。", "b": "谭嗣同《思篇》"}], "words": [{"w": "寻复", "t": "相继"}, {"w": "寻声", "t": "随声"}, {"w": "寻续", "t": "相继,连续。"}]}, {"meaning": "讨伐,派兵去镇压。", "cites": [{"t": "夫三军之所寻,将蛮夷戎狄之骄逸不虔,于是乎致武。", "b": "《国语·周语》"}]}, {"meaning": "追逐。", "cites": [{"t": "乃有迅羽轻足,寻景追括。", "b": "汉·张衡《西京赋》"}], "words": [{"w": "寻行逐队", "t": "会合在一起"}, {"w": "寻逻", "t": "巡查警戒"}, {"w": "寻踪", "t": "跟踪捕捉。"}]}, {"meaning": "用热水脱毛。", "cites": [{"t": "必寻盟若可寻也。亦可寒也。", "b": "《左传·哀公十二年》"}, {"t": "聘而言盟者,寻旧盟也。", "b": "《公羊传·成公三年》"}]}, {"meaning": "顷刻,不久。", "cites": [{"t": "未果,寻病终。", "b": "晋·陶渊明《桃花源记》"}, {"t": "寻移刑部。", "b": "清·张廷玉《明史》"}, {"t": "帝寻被执。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "寻遣丞请还。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "沿着,顺着。", "cites": [{"t": "绍遂寻山北行。", "b": "《后汉书》"}, {"t": "轻舟泛月寻溪转,疑是山阴雪后来。", "b": "唐·李白《东鲁门泛舟》"}], "words": [{"w": "寻村转疃", "t": "走村串巷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('564wx','那','1','nā nà nè nèi nuó','阝','6','','[{"pinyin": "nā", "defs": [{"meaning": "姓。"}]}, {"pinyin": "nà", "defs": [{"meaning": "(形声。小篆字形,从邑,冄(rǎn)声。邑与地名或行政区域有关。后省作“那”。①本义:国名。《说文》:“西夷国。”本读nuó。②指示代词。特指某个人、某个时间、某个地方或某个事物。不一定是远指之词,如“那件事你我心里都清楚。”)。"}, {"meaning": "指示代词。"}, {"meaning": "指代较远的时间、处所。", "cites": [{"t": "那时使吾。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "那昝", "t": "那咱。那时"}, {"w": "从那以后,我就再也没见过她;那厢", "t": "那边"}, {"w": "那头儿", "t": "极点;尽头"}, {"w": "那哈儿", "t": "那儿,那里。"}]}]}, {"pinyin": "nè", "defs": [{"meaning": "", "words": [{"w": "那人可不怎么样", "t": ""}]}]}, {"pinyin": "nèi", "defs": [{"meaning": "", "words": [{"w": "那三年;那个;那些", "t": ""}]}]}, {"pinyin": "nuó", "defs": [{"meaning": "多。", "cites": [{"t": "不戢不难,受福不那。", "b": "《诗·小雅·桑扈》"}]}, {"meaning": "安闲的样子。", "cites": [{"t": "王在在镐,有那其居。", "b": "《诗·小雅·鱼藻》"}]}, {"meaning": "美好。", "cites": [{"t": "使富都那竖赞焉。", "b": "《国语·楚语上》"}]}, {"meaning": "代词。何。", "cites": [{"t": "那,借为问辞,犹何也。如何、奈何之合音也。", "b": "《正字通》"}]}, {"meaning": "移动", "cites": [{"t": "语言虽利便,身体莫能那。", "b": "《西游记》"}], "words": [{"w": "那用", "t": "挪用"}, {"w": "那空", "t": "因挪用而亏空"}, {"w": "那踪", "t": "移动步子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('565wx','迅','1','xùn','辶','6','','[{"pinyin": "xùn", "defs": [{"meaning": "快", "cites": [{"t": "迅,疾也。", "b": "《说文》"}, {"t": "狼绝有力迅。", "b": "《尔雅》"}, {"t": "藨者若鹿迅走。", "b": "《周书·王会》"}, {"t": "迅雷风烈。", "b": "《论语》"}], "words": [{"w": "迅即", "t": "立即"}, {"w": "迅指", "t": "巡指间。弹指间"}, {"w": "迅羽", "t": "形容快飞的鸟"}, {"w": "迅走", "t": "走得很快。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('566wx','尽','1','jǐn jìn','尸','6','','[{"pinyin": "jǐn", "defs": [{"meaning": "(尽为“儘”和“盡”的简化字)。"}, {"meaning": "任凭,纵使。", "cites": [{"t": "惟有落红不禁,尽教飞舞出宫墙。", "b": "武衍《宫词》"}], "words": [{"w": "尽下", "t": "听凭臣下;对臣下放心。帝王宽以待下。"}]}]}, {"pinyin": "jìn", "defs": [{"meaning": "(尽原为“盡”的俗字;今为“盡”的简化字。会意。甲骨文字形表示手持刷子洗刷器皿。盛东西的器皿只有空了才能洗刷。本义:器物中空) 同本义。", "cites": [{"t": "盡,器中空也。", "b": "《说文》"}], "words": [{"w": "尽觞", "t": "饮尽杯中之酒"}, {"w": "尽光", "t": "精光。全无剩余。"}]}, {"meaning": "竭;完;没有了。", "cites": [{"t": "尽,竭也,终也。", "b": "《广韵》"}, {"t": "尽,止也。", "b": "《小尔雅》"}, {"t": "尽莫不然也。", "b": "《墨子经》"}, {"t": "固民自尽。", "b": "《礼记·哀公问》。疏:“谓竭尽。”"}, {"t": "尽信书。", "b": "《孟子》"}, {"t": "虚坐尽后,食坐尽前。", "b": "《礼记·曲礼》"}, {"t": "尽信书。", "b": "《孟子》"}, {"t": "虚坐尽后,食坐尽前。", "b": "《礼记·曲礼》"}, {"t": "攻械尽。", "b": "《墨子·公输》"}, {"t": "民力尽于无用。", "b": "《墨子·七患》"}, {"t": "马力尽矣。", "b": "《荀子·哀公》"}, {"t": "林尽水源。", "b": "晋·陶渊明《桃花源记》"}, {"t": "雪尽马蹄轻。", "b": "唐·王维《观猎》诗"}, {"t": "以尽吾齿。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "尽其肉。", "b": "唐·柳宗元《柳河东集·三戒》"}, {"t": "烧尽北船。", "b": "《资治通鉴》"}, {"t": "必尽吾力。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "担中肉尽,止有剩骨。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "尽言", "t": "竭尽其言"}, {"w": "尽志", "t": "竭尽心志"}, {"w": "尽哀", "t": "竭尽哀思"}, {"w": "尽盘将军", "t": "指贪吃的人"}, {"w": "尽敬", "t": "竭尽敬意。"}]}, {"meaning": "达到极限。", "cites": [{"t": "五帝三王之于乐,尽之矣。", "b": "《吕氏春秋·明理》。注:“极也。”"}], "words": [{"w": "尽美", "t": "极美;完美"}, {"w": "尽善", "t": "十分完善"}, {"w": "尽齿", "t": "尽其年寿;指衰老。"}]}, {"meaning": "死。", "cites": [{"t": "转侧床头,惟思自尽。", "b": "《聊斋志异》"}], "words": [{"w": "尽命", "t": "终天年;效死;丧命"}, {"w": "尽年", "t": "极其天年"}, {"w": "尽死", "t": "效死"}, {"w": "尽绝", "t": "绝灭。"}]}, {"meaning": "努力完成。", "cites": [{"t": "农以力尽田,贾以察尽财,百工以巧尽械器。", "b": "《荀子·荣辱》。谓:“精于事。”"}], "words": [{"w": "尽义务", "t": "尽本分,完成自己所应做的事"}, {"w": "尽规", "t": "竭力谋划。"}]}, {"meaning": "追问。", "cites": [{"t": "当下心中大喜,却故意的尽了那风水几句。", "b": "《儿女英雄传》"}]}, {"meaning": "消灭;消失。", "cites": [{"t": "不过亡三十万金,则诸侯可尽。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "全部,都。", "cites": [{"t": "虚实尽知。", "b": "《资治通鉴·唐纪》"}, {"t": "尽杀其戍卒。", "b": ""}, {"t": "尽杀之。", "b": ""}, {"t": "尽戮之。", "b": ""}], "words": [{"w": "应有尽有;尽净", "t": "全部不剩"}, {"w": "尽皆", "t": "全都;完全"}, {"w": "尽实", "t": "完全按照实情"}, {"w": "尽多", "t": "全部,尽皆。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('567wx','导','1','dǎo','寸','6','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从寸,道声。“寸”与“手”意思相近。本义:以手牵引,引导)。"}, {"meaning": "同本义。", "cites": [{"t": "导,引也。", "b": "《说文》"}, {"t": "其治宜导引按轎。", "b": "《素问》。注:“谓摇筋骨动支节。”"}, {"t": "导官令本。", "b": "《续汉书·百官志》。注:“择也。”"}, {"t": "导官。", "b": "《后汉书·邓后纪》。注:“主导择米以供祭祀。”"}, {"t": "导一茎六穗于庖。", "b": "《汉书·司马相如传》。郑氏曰:“导,择也。”"}, {"t": "虞人导前,鹰犬罗后。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "导子", "t": "官员出行时在前面开路的仪仗队"}, {"w": "导从", "t": "古代官员出行时,担任前导和后从的人"}, {"w": "导仗", "t": "前导的仪仗。"}]}, {"meaning": "教导。", "cites": [{"t": "而不可以导人。", "b": "《淮南子·缪称》。注:“教也。”"}, {"t": "手持杯珓导我掷,云此最吉余难同。", "b": "韩愈《谒衡岳庙遂宿岳寺题门楼》"}], "words": [{"w": "导播", "t": "电视台中指导表演、监督整个节目播出的专业人员"}, {"w": "导训", "t": "引导而使和顺。"}]}, {"meaning": "疏通。", "cites": [{"t": "为川者决之使导。", "b": "《国语·周语上》"}], "words": [{"w": "导行费", "t": "汉灵帝时,郡国、地方每在进贡朝廷之外,另有物品给中署,做为所献之物的导行费"}, {"w": "导款", "t": "疏通"}, {"w": "导泄", "t": "疏导排泄。"}]}, {"meaning": "启发,开导。", "cites": [{"t": "忠信以导之。", "b": "《吕氏春秋·适威》。注:“犹先也。”"}, {"t": "是以导于民。", "b": "《国语·晋语》。注:“训也。”"}, {"t": "然后导以取保,出启于外。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "导谕", "t": "劝导晓谕"}, {"w": "导示", "t": "指导启示。"}]}, {"meaning": "引诱。", "cites": [{"t": "导之以政。", "b": "《论语》。皇疏:“谓诱引也。”"}], "words": [{"w": "导欲宣淫", "t": "倡导情欲,宣泄淫乱之事"}, {"w": "导谀", "t": "谄媚阿谀,曲意逢迎。。"}]}, {"meaning": "向导,引路人。", "cites": [{"t": "乌孙发导译送骞还。", "b": "《史记·大宛列传》"}], "words": [{"w": "导首", "t": "前导;领头"}, {"w": "前导", "t": "领头人。"}]}, {"meaning": "顺着。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('568wx','异','1','yì','廾','6','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。“異”,甲骨文字形,象个有手、脚、头的人形。从廾(gǒng)从畀(bì)。畀,予也。本义:奇特;奇异;奇怪)。"}, {"meaning": "同本义。", "cites": [{"t": "异,怪也。", "b": "《玉篇》"}, {"t": "异,奇也。", "b": "《广韵》"}, {"t": "何以异哉。", "b": "《列子·杨朱》"}, {"t": "异乎交益之士。", "b": "左思《魏都赋》"}, {"t": "妇人异甚。", "b": "《战国策·赵策》"}, {"t": "产异蛇。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "觉无异能。", "b": "唐·柳宗元《三戒》"}, {"t": "父异焉。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "异疾", "t": "奇怪的病症"}, {"w": "异形", "t": "怪异或奇特的形状。"}]}, {"meaning": "不同。", "cites": [{"t": "礼者为异。", "b": "《礼记·乐记》。注:“谓别贵贱也。”"}, {"t": "事为异别。", "b": "《礼记·王制》"}, {"t": "执心各异。", "b": "汉·刘向《列女传》"}, {"t": "得无异乎。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "或异二者。", "b": ""}, {"t": "何异以孤羊投群狼?", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "异俗", "t": "风俗异于汉族的少数民族"}, {"w": "异姓陌路", "t": "既不同姓也不认识"}, {"w": "异手", "t": "指不同之人"}, {"w": "异世", "t": "不同时代"}, {"w": "异目", "t": "另眼。"}]}, {"meaning": "其他,别的。", "cites": [{"t": "贾不敢为异事。", "b": "《吕氏春秋·上农》"}, {"t": "无它异也。(意思是,没有别的意外的事)。", "b": "《后汉书·列女传》"}], "words": [{"w": "异域茅草", "t": "蛮荒之地的乡野村夫"}, {"w": "异土", "t": "他乡;别处。"}]}, {"meaning": "护翼。", "cites": [{"t": "古天异临子。", "b": "《盂鼎》"}]}, {"meaning": "区别;分开。", "cites": [{"t": "异是非,明好恶,检奸邪,消佚乱。", "b": "《新语》"}], "words": [{"w": "异分", "t": "区别"}, {"w": "异居", "t": "分居。"}]}, {"meaning": "觉得奇怪;诧异。", "cites": [{"t": "渔人甚异之。", "b": "晋·陶潜《桃花源记》"}]}, {"meaning": "恭敬。", "cites": [{"t": "极明与与,有畏劝汝,何异非汝,何畏非世。", "b": "《逸周书》"}]}, {"meaning": "辅助。", "cites": [{"t": "令行禁止王始也…出三日无适异;出四日无适与。", "b": "《逸周书》"}]}, {"meaning": "怪异不祥之事;灾异。", "cites": [{"t": "己巳,日有食之。何以书?记异也。", "b": "《公羊传》"}]}, {"meaning": "指特殊本领、才能。", "cites": [{"t": "觉无异能者。", "b": "唐·柳宗元《三戒》"}, {"t": "举天下所贡蝴蝶…一切异状遍试之,无出其右者。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('569wx','弛','1','chí','弓','6','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从弓,也声。本义:放松弓弦)。"}, {"meaning": "同本义:。", "cites": [{"t": "弛,弓解也。", "b": "《说文》"}, {"t": "弛弓尚角。", "b": "《礼记·曲礼》"}, {"t": "一张一弛。", "b": "《礼记·杂记》"}, {"t": "乃弛弓而自后缚之。", "b": "《左传·襄公十八年》"}, {"t": "弧弓弛而不张。", "b": "《楚辞·谬谏》"}], "words": [{"w": "弛张", "t": "一松一紧。弛,放松弓弦;张,拉紧弓弦。"}]}, {"meaning": "松弛,放松。", "cites": [{"t": "弛,缓也。", "b": "《广雅》"}, {"t": "四日弛力。", "b": "《周礼·大司徒》。注:“息徭役也。”"}, {"t": "病热而筋弛。", "b": "《素问·刺要论》"}], "words": [{"w": "弛易", "t": "松慢;变换"}, {"w": "弛纵", "t": "放纵"}, {"w": "弛玩", "t": "松懈玩忽。"}]}, {"meaning": "解除。", "cites": [{"t": "令弛县。", "b": "《周礼·大司乐》。注:“释下之。”"}, {"t": "弛周室之忧。", "b": "《左传·昭公三十二年》。注:“犹解也。”"}], "words": [{"w": "弛解", "t": "解除警卫"}, {"w": "弛防", "t": "解除防备。"}]}, {"meaning": "毁坏;废弃。", "cites": [{"t": "庶民弛政。", "b": "《礼记·乐记》。注:“去纣时苛政也。”"}, {"t": "弛侯。", "b": "《谷梁传·襄公二十四年》。注:“废也。”"}, {"t": "文公欲弛孟子之宅。", "b": "《国语·鲁语》"}], "words": [{"w": "弛力", "t": "舍弃力役的事情"}, {"w": "弛政", "t": "除去苛政。"}]}, {"meaning": "放下。", "cites": [{"t": "弛于负担。", "b": "《左传·庄公二十二年》。注:“去离也。”"}, {"t": "屠乃奔倚其下,弛担持刀。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "弛仗", "t": "放下兵器"}, {"w": "弛兵", "t": "放下武器"}, {"w": "弛担", "t": "放下担子;推卸责任"}, {"w": "弛卸", "t": "推卸。"}]}, {"meaning": "懈怠,松懈。", "cites": [{"t": "识者固知元政紊弛而变兴自下之渐矣。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "弛绝", "t": "松懈断绝"}, {"w": "弛惰", "t": "松懈怠惰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('570wx','孙','1','sūn','子','6','','[{"pinyin": "sūn", "defs": [{"meaning": "(会意。从子,从系,续也。金文,象用绳索捆绑小孩子,意为少年俘虏。本义:儿子的儿子)。"}, {"meaning": "同本义。", "cites": [{"t": "孫,子之子曰孙。", "b": "《说文》"}, {"t": "孙谓祖后者。", "b": "《礼记·杂记》注"}, {"t": "子子孙孙引无极也。", "b": "《尔雅》"}, {"t": "遂率子孙荷担者三夫。", "b": "《列子·汤问》"}, {"t": "有孙母未出,出入无完裙。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "祖孙;重孙", "t": "孙子的儿子"}, {"w": "孙少爷", "t": "旧时尊称别人的孙子"}, {"w": "孙囡", "t": "方言。孙女儿"}, {"w": "孙儿;孙孙", "t": "孙儿,多用于爱称"}, {"w": "孙妇", "t": "孙媳妇"}, {"w": "孙曾", "t": "孙子和曾孙。"}]}, {"meaning": "跟孙子同辈的同性或异性亲属。", "cites": [{"t": "况且这通身的气派,竟不像老祖宗的外孙女儿,竟是个嫡亲的孙女。", "b": "《红楼梦》"}], "words": [{"w": "外孙,侄孙;孙婿", "t": "儿子的女婿。"}]}, {"meaning": "泛指后代子孙。", "cites": [{"t": "子孙视之不甚惜,举以予人,如弃草芥。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "孙息", "t": "子孙"}, {"w": "孙子", "t": "子孙后代"}, {"w": "孙男弟女", "t": "泛指晚辈。"}]}, {"meaning": "脉络的细小分支。", "cites": [{"t": "顾闻孙络谿谷。", "b": "《素问·气穴论》。注:“小络也。”"}, {"t": "经脉为里,支而横者为络,络之别者为孙。", "b": "《灵枢经》"}]}, {"meaning": "再生或孳生的植物。", "cites": [{"t": "孙竹之管。", "b": "《周礼·大司乐》。注:“孙枝根之未生者。”"}], "words": [{"w": "孙竹", "t": "竹根末端生出的新枝"}, {"w": "孙枝", "t": "树木旁枝所生的新枝。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('571wx','阵','1','zhèn','阝','6','','[{"pinyin": "zhèn", "defs": [{"meaning": "(会意。从阜(fù),从车。土山前摆满了战车。字本作“陈”。“阵”为后起字。本义:两军交战时队伍的战斗队形)。"}, {"meaning": "同本义。", "cites": [{"t": "阵,旅也。", "b": "《玉篇》"}, {"t": "信乃使万人先行,出背水阵。", "b": "《史记·淮阴侯传》"}, {"t": "先登陷阵。", "b": "《史记·樊哙传》。"}], "words": [{"w": "阵脚", "t": "战阵的前沿阵地"}, {"w": "阵圆", "t": "战阵布置完毕"}, {"w": "阵图", "t": "作战时所摆列的军阵图形"}, {"w": "阵梢", "t": "战斗队列的尾端"}, {"w": "阵杀", "t": "军中诛杀。"}]}, {"meaning": "阵地。", "cites": [{"t": "大王尝与吴人战,五战而三胜,阵卒尽矣。", "b": "《史记》"}]}, {"meaning": "又指战争或战斗。", "cites": [{"t": "鲜于仲通六万卒,征蛮一阵全军没。", "b": "唐·白居易《蛮子朝》。"}], "words": [{"w": "阵阵赢", "t": "仗仗取胜"}, {"w": "叫阵;怯阵;出阵;阵败", "t": "战败"}, {"w": "阵率", "t": "战士。"}]}, {"meaning": "雷阵雨来临前乌云翻滚、雷电交加的现象。", "cites": [{"t": "阵急如酣战,点粗成乱沤。", "b": "唐·李咸用《和殷衙推春霖即事》。"}], "words": [{"w": "阵头雨", "t": "雷阵雨"}, {"w": "阵影", "t": "阵云的阴影。"}]}, {"meaning": "布阵,列阵。", "cites": [{"t": "阵而后战,兵法之常,运用之妙,存乎一心。", "b": "《宋史·岳飞传》"}]}, {"meaning": "表示事物经过的一定时间段落。", "cites": [{"t": "每一阵至。", "b": "《徐霞客游记·游黄山记》。"}], "words": [{"w": "一阵雨;一阵风;一阵寒潮;一阵喧哗;一阵尘暴", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('572wx','阳','1','yáng','阝','6','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从阜,昜(yáng)声。从阜,与山有关。本义:山南水北)。"}, {"meaning": "同本义。", "cites": [{"t": "阳,高明也。", "b": "《说文》"}, {"t": "山南为阳,水北为阳。", "b": "《谷梁传·僖公二十八年》"}, {"t": "山东曰朝阳,山西曰夕阳。", "b": "《尔雅》"}, {"t": "利刊阳木而火之。", "b": "《周礼·柞氏》。注:“生于山南为阳木。”"}, {"t": "河阳之北。", "b": "《列子·汤问》"}, {"t": "华山之阳。", "b": "宋·王安石《游褒禅山记》"}, {"t": "阳谷皆入汶。", "b": "清·姚鼐《登泰山记》"}, {"t": "泰山之阳,汶水西流。", "b": ""}], "words": [{"w": "衡阳(在衡山之南),洛阳(在洛河之北", "t": ""}, {"w": "阳陆", "t": "山之南"}, {"w": "阳濒", "t": "水之北岸"}, {"w": "阳林", "t": "生在山南的林木"}, {"w": "阳木", "t": "山南之木"}, {"w": "阳柯", "t": "向阳光或南向的树枝"}, {"w": "阳崖", "t": "向南的山崖"}, {"w": "阳坡", "t": "向阳的山坡。"}]}, {"meaning": "太阳。", "cites": [{"t": "湛湛露斯,匪阳不晞。", "b": "《诗·小雅·湛露》"}, {"t": "阳春布德泽。", "b": "《乐府诗集·长歌行》"}, {"t": "斜阳草树。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}, {"t": "少年如朝阳。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "阳精", "t": "太阳"}, {"w": "斜阳;阳宗", "t": "指太阳"}, {"w": "阳明", "t": "太阳、阳光。也指光明。人体经络名"}, {"w": "阳彩", "t": "日光,太阳的色彩。"}]}, {"meaning": "物体的正面,前面。", "cites": [{"t": "自昔以钱之有字处为阴,无字处为阳。", "b": "清·顾炎武《日知录·钱面》"}]}, {"meaning": "男性生殖器。", "cites": [{"t": "其国男子年五十余,阳多痿。", "b": "《海国闻见录·东洋记》"}], "words": [{"w": "阳物", "t": "男性生殖器。"}]}, {"meaning": "精液。", "cites": [{"t": "女子七七四十九阴绝,男子八八六十四阳绝,过此为婚为野合。", "b": "《玉堂嘉话》"}]}, {"meaning": "外面。", "cites": [{"t": "必谋功不察志,论阳效不存阴计。", "b": "汉·王充《论衡定贤》"}], "words": [{"w": "阳浮", "t": "表面顺从"}, {"w": "阳效", "t": "表面的功效"}, {"w": "阳冻", "t": "地面上的冰冻"}, {"w": "阳事", "t": "外治,宫廷以外的政事"}, {"w": "阳冰", "t": "结在水面的冰。"}]}, {"meaning": "晴天。", "cites": [{"t": "仰福帝居,阳曜阴藏。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "天。", "cites": [{"t": "阳灵停曜于其表,阴祗雾于其里。", "b": "《文选·左思·魏都赋》"}], "words": [{"w": "阳灵", "t": "天神"}, {"w": "阳祀", "t": "祭天及宗庙。"}]}, {"meaning": "人世。", "cites": [{"t": "唐王游地府,回生阳世,开设水陆大会,超度阴魂。", "b": "《西游记》"}], "words": [{"w": "阳类", "t": "人世间的物类"}, {"w": "阳寿", "t": "人在世间的寿命"}, {"w": "阳报", "t": "在人世间得到的报应"}, {"w": "阳功", "t": "人间功德。"}]}, {"meaning": "额 。又指前面正面。", "cites": [{"t": "凡卜,辨龟之上下,左右,阴阳,以授命龟者,而诏相之。", "b": "《周礼》"}]}, {"meaning": "眸子。借指美目。", "cites": [{"t": "阳,《方言》:燕、代、朝鲜、洌水之间或好目为阳。", "b": "卷子本《玉篇》"}]}, {"meaning": "古代阴阳家、方士以四千六百一十七岁为一元,初入一元为一百零六岁,有旱灾九年,称为阳九。其余尚有阴九、阴七、阳七、阴五、阳五、阴三、阳三等。阳为旱灾,阴为水灾。"}, {"meaning": "太乙数以四百五十六年为一阳九,二百八十八年为一百六。阳九为奇数,为阳数之穷;百六,偶数,为阴数之穷。"}, {"meaning": "道家称三千三百年为小阳九,小百六;九千九百年为大阳九,大百六。(天厄称为阳九,地亏称为百六);阳干(指十干中的甲、丙、戊、庚、壬。即列于单数位天干。与阴相对);阳木(春夏所生的树木。一说为山南之木);阳辰(相术家以十二地支中的单数位,子、寅、辰、午、申、戊六日为阳辰,余六日为阴辰);阳鱼(鱼。因其生于阴生属于阳,故名);阳童(未成年而死的庶子。一说男孩夭亡为阳童,女孩夭亡为阴童);阳施(阳气散布);阳道(外事,政事);阳会(古俗妇女于每月十九日夜举行的一种聚会);阳德(阳气。也指日);阳错(阴阳家的迷信之说);阳声(古乐声分阴阳,六律为阳声。也指清声);阳灵(祭天之所。也指太阳)。"}, {"meaning": "中国中医学上指人体内部某些器官。", "cites": [{"t": "太阳藏独至,厥喘虚气逆,是阴不足,阳有余也。", "b": "《素问》"}]}, {"meaning": "又如:阳病(中医指阳虚有寒的病症);阳疾(中医指热邪)。"}, {"meaning": "春秋国名 。在今山东省沂水县西南。"}, {"meaning": "春秋燕邑名 。在今河南省唐县东北。"}, {"meaning": "指春夏。", "cites": [{"t": "夫人在阳则舒,在阴则惨,此牵乎天者也。", "b": "张衡《西京赋》"}]}, {"meaning": "又如:阳和(春天的暖气);阳夏(夏季);阳时(春夏之时);阳官(指《周礼》中的春官)。"}, {"meaning": "中午。", "cites": [{"t": "夏后氏祭其暗,殷人祭其阳,同人祭日以朝及暗。", "b": "《礼记》"}]}, {"meaning": "日出。", "cites": [{"t": "殷人祭其阳。", "b": "《礼记·祭义》。郑玄注:“阳,读为曰雨曰旸之旸。”"}, {"t": "艾,时阳若。", "b": "《汉书·五行志中之上》"}]}, {"meaning": "颜色明亮。", "cites": [{"t": "神光离合,乍阴乍阳。", "b": "曹植《洛神赋》"}]}, {"meaning": "鲜明。", "cites": [{"t": "得时之麻,必芒以长,疏节而色阳。", "b": "《吕氏春秋》"}]}, {"meaning": "温暖。", "cites": [{"t": "春日载阳,有鸣仓庚。", "b": "《诗·豳风》"}], "words": [{"w": "阳回", "t": "阳气回转"}, {"w": "阳晁", "t": "晴朗的早晨"}, {"w": "阳嘉", "t": "春日的暖气"}, {"w": "阳春有脚", "t": "比喻为人带来春天般的温暖。"}]}, {"meaning": "干旱。", "cites": [{"t": "太白司艾,西岳国师典致时阳,白炜象平,考量以铨。", "b": "《汉书》"}]}, {"meaning": "诈伪。", "cites": [{"t": "皆阳应曰。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "阳言", "t": "诈言。同佯言。"}]}, {"meaning": "奇数。", "cites": [{"t": "阳数奇,阴数偶。", "b": "《白虎通》"}], "words": [{"w": "阳爵", "t": "奇数的爵位等级"}, {"w": "阳数", "t": "奇数。"}]}, {"meaning": "外露;显露。", "cites": [{"t": "仲尼曰:“无入而藏,无出而阳,柴立其中央。”", "b": "《庄子·达生》"}]}, {"meaning": "假装。", "cites": [{"t": "而箕子被发阳狂。", "b": "《大戴礼记·保傅》"}, {"t": "然阳浮慕之。", "b": "《史记·酷吏张汤传》"}, {"t": "故胜己者,则不得闻,闻亦阳不知也。", "b": "晋·葛洪《抱朴子》"}]}, {"meaning": "复苏;生长。", "cites": [{"t": "日月还复周,我去不再阳。", "b": "晋·陶潜《杂诗》"}]}, {"meaning": "举起。", "cites": [{"t": "君子阳阳。", "b": "《诗·王风·君子阳阳》。王先谦云:“阳为扬之假借。”"}, {"t": "其声清阳而远闻。", "b": "《周礼·考工记·梓人》"}]}, {"meaning": "表面上。", "cites": [{"t": "吴主孙休,恐其内变,阳示恩宠,内实防之。", "b": "《三国演义》"}], "words": [{"w": "阳施阴夺", "t": "表面给予,暗中夺回"}, {"w": "阳奉阴违", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('573wx','收','1','shōu','攵','6','','[{"pinyin": "shōu", "defs": [{"meaning": "(形声。从攴(pū),收(jiū)声)。"}, {"meaning": "同本义。", "cites": [{"t": "收,捕也。", "b": "《说文》"}, {"t": "女反收之。", "b": "《诗·大雅·瞻卬》。传:“拘收也。”"}, {"t": "单于壮其节,朝夕遣人候问武,而收系张胜。", "b": "《汉书·李广苏建传》"}, {"t": "一时收禽,上下肃然,称为政理。", "b": "《后汉书·张衡传》"}], "words": [{"w": "收领", "t": "捉拿"}, {"w": "收系", "t": "逮捕下狱"}, {"w": "收付", "t": "拘捕罪犯,交付办案"}, {"w": "收考", "t": "拘捕考问"}, {"w": "收夷", "t": "捕杀"}, {"w": "收劾", "t": "拘捕弹劾"}, {"w": "收案", "t": "拘捕案问"}, {"w": "收掩", "t": "收捕"}, {"w": "收执", "t": "捉拿"}, {"w": "收禁", "t": "拘押监禁"}, {"w": "收领", "t": "拘禁。"}]}, {"meaning": "收拾;收取。", "cites": [{"t": "收,取也。", "b": "《广雅》"}, {"t": "收以奔褒。", "b": "《国语·郑语》。注:“取也。”"}, {"t": "勤者有事则收之。", "b": "《礼记·玉藻》。疏:“谓敛持在手。”"}, {"t": "责毕收乎?来何疾也!", "b": "《战国策·齐策》"}, {"t": "必死是间,余收尔骨焉。", "b": "《左传·僖公三十三年》"}, {"t": "古来白骨无人收。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "收发报;收信;收什", "t": "收拾"}, {"w": "收局", "t": "收拾局面"}, {"w": "收捉", "t": "方言。收拾;修建"}, {"w": "收略", "t": "收拾;安排"}, {"w": "收解", "t": "当铺收进的抵押品。"}]}, {"meaning": "聚集;收集。", "cites": [{"t": "收,敛也。", "b": "《小尔雅》"}, {"t": "我其收之。", "b": "《诗·周颂·维天之命》。传:“聚也。”"}, {"t": "既蜡而收。", "b": "《仪记·郊特牲》。注:“谓收敛积聚也。”"}, {"t": "其诗以养父母收族为意。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "收括", "t": "聚集;约束"}, {"w": "收藉", "t": "聚集;收集。"}]}, {"meaning": "收容;接受。", "cites": [{"t": "仲尼七十说,历聘莫见收。", "b": "李白《赠崔郎中宗之》"}, {"t": "收孤寡,补贫穷。", "b": "《荀子·王制》"}], "words": [{"w": "收小的", "t": "接生"}, {"w": "收管", "t": "接收囚犯后签的回执。"}]}, {"meaning": "收获;收割。", "cites": [{"t": "春生夏长,秋收冬藏。", "b": "《史记·太史公自序》"}, {"t": "春种一粒粟,秋收万颗子。", "b": "李绅《悯农》"}], "words": [{"w": "收田", "t": "收割农田的作物。"}]}, {"meaning": "使中断、停顿或终止。", "cites": [{"t": "曲终收拨当心画,四弦一声如裂帛。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "收功", "t": "止息功能"}, {"w": "收泪;收科", "t": "收场;圆场"}, {"w": "收逢", "t": "收场;罢休"}, {"w": "收煞", "t": "收场;结局"}, {"w": "收成结果", "t": "送上死路"}, {"w": "收驩", "t": "停止作乐"}, {"w": "收声", "t": "止声;销声"}, {"w": "收计", "t": "关闭清点。"}]}, {"meaning": "征收。", "cites": [{"t": "收租税。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "其收田租亩四升。", "b": "曹操《抑兼并令》"}, {"t": "收取其钱得数百万。", "b": "褚少孙《西门豹治邺》"}], "words": [{"w": "收租;收税", "t": ""}]}, {"meaning": "收回;收缴。", "cites": [{"t": "收天下之兵,聚之咸阳,销锋镝,铸以为金人十二。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "收掌", "t": "科举考试的办事人员。外收掌负责收卷;内收掌负责把试卷分给各房房官。"}]}, {"meaning": "收藏;保存。", "cites": [{"t": "乃遂收盛樊於期之首,函封之。", "b": "《战国策·燕策》"}]}, {"meaning": "占取。", "cites": [{"t": "秦将王翦破赵,虏赵王,尽收其地。", "b": "《战国策·燕策》"}]}, {"meaning": "收回;收复。", "cites": [{"t": "攻大泽乡,收而攻蕲。", "b": "《史记·陈涉世家》"}, {"t": "剑外忽传收蓟北,初闻涕泪满衣裳。", "b": "唐·杜甫《闻官军收河南河北》"}]}, {"meaning": "收获;收成。", "cites": [{"t": "其能耕者不过百,百亩之收不过百担。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "丰收;欠收;颗粒无收", "t": ""}]}, {"meaning": "收藏品。", "cites": [{"t": "燕、赵之收藏。", "b": "杜牧《阿房宫赋》"}]}, {"meaning": "车箱底部四面的横木,即车轸。"}, {"meaning": "夏代冠名。", "cites": [{"t": "帝尧者…黄收纯衣,彤车乘白马。", "b": "《史记·五帝本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('574wx','阶','1','jiē','阝','6','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从阜(fù),表示与地形地势的高低上下有关,皆声。本义:台阶)。"}, {"meaning": "同本义。", "cites": [{"t": "阶,陛也。字亦作堦。", "b": "《说文》"}, {"t": "御史奏鸡鸣于阶下。", "b": "《尚书·大传》"}, {"t": "浮堦乘虚。", "b": "何晏《景福殿赋》"}, {"t": "三揖至于阶。", "b": "《荀子·乐论》"}, {"t": "苔痕上阶绿。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "庭阶寂寂。", "b": "明·归有光《项脊轩志》"}, {"t": "匍匐阶下。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "阶廊", "t": "台阶和走廊"}, {"w": "阶檐", "t": "台阶与屋檐"}, {"w": "阶陛", "t": "宫殿的台阶"}, {"w": "阶除", "t": "台阶"}, {"w": "阶墀", "t": "宫殿台阶。"}]}, {"meaning": "梯子。", "cites": [{"t": "捐阶。", "b": "《孟子》。注:“梯也。”"}, {"t": "欲释阶而登天兮。", "b": "《楚辞·九章·惜诵》"}], "words": [{"w": "阶梯", "t": ""}]}, {"meaning": "官阶,官方的衔头。", "cites": [{"t": "但以无阶朝廷。", "b": "《汉书·匡衡传》"}, {"t": "文阶二十八阶,武阶二十一阶。", "b": "《新唐书·百官志》"}], "words": [{"w": "阶衔", "t": "官位;官衔"}, {"w": "阶次", "t": "官位的等级"}, {"w": "阶品", "t": "官吏的等级品位"}, {"w": "阶封", "t": "官阶与封号。"}]}, {"meaning": "缘由,途径。", "cites": [{"t": "夫婚姻,祸福之阶也。", "b": "《国语·周语中》"}], "words": [{"w": "阶祸", "t": "引致祸患,祸患的缘由。"}]}, {"meaning": "凭借。", "cites": [{"t": "汉亡尺土之阶…五载而成帝业。", "b": "《汉书·异姓诸侯王表》"}], "words": [{"w": "阶缘", "t": "凭藉,攀附。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('575wx','阴','1','yīn','阝','6','','[{"pinyin": "yīn", "defs": [{"meaning": "(会意。从阜(fù),从侌,侌(yīn)亦声。阜,土山,从阜多与地形有关。简化字属会意,表示月夜笼罩山冈,很阴暗。本义:山的北面,水的南面)。"}, {"meaning": "同本义。", "cites": [{"t": "陰,誾也。山之北,水之南也。从阜,从侌。", "b": "《说文》"}, {"t": "鸣鹤在阴。", "b": "《易·中孚》。按,二在兑泽之中,艮山之下,故称阴。"}, {"t": "壜上张赤挛阴羽。", "b": "《周书·王会》"}, {"t": "相其阴阳。", "b": "《诗·大雅·公刘》"}, {"t": "阴竹之管。", "b": "《周礼·大司乐》"}, {"t": "令剥阴木而水之。", "b": "《周礼·柞氏》"}, {"t": "达于汉阴(汉水南岸)。", "b": "《列子·汤问》"}, {"t": "洞庭之阴。", "b": "唐·李朝威《柳毅传》"}, {"t": "阴谷皆入济。", "b": "清·姚鼐《登泰山记》"}, {"t": "其阴,济水东流。(阴:泰山的北面。)", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "阴山背后", "t": "偏僻冷落的地方"}, {"w": "阴木", "t": "山北的树木。一说秋冬生长的树木"}, {"w": "阴竹", "t": "生长于山北的竹子"}, {"w": "阴滨", "t": "江河的南岸"}, {"w": "阴麓", "t": "山的北麓"}, {"w": "阴坡", "t": "北坡。"}]}, {"meaning": "泛指北面。", "cites": [{"t": "洞霞飘素练,藓壁画阴窗。", "b": "唐·李质《宿日观东房诗》"}], "words": [{"w": "阴窗", "t": "北窗"}, {"w": "阴欍", "t": "北窗"}, {"w": "阴隅", "t": "西北方"}, {"w": "阴列", "t": "最北边的一条山脉。"}]}, {"meaning": "背阳为阴。", "cites": [{"t": "阴崖积雪犹含冻,远树浮烟已带春。", "b": "《西游记》"}], "words": [{"w": "阴干", "t": "放在背阳处吹干"}, {"w": "阴崖", "t": "背阳的山崖"}, {"w": "阴地", "t": "背阳地"}, {"w": "阴阳瓦陇", "t": "瓦房顶的瓦是按一行凸面朝下一行凹面朝上交错铺排的。凸面为阳,凹面为阴。凸凹相间的行列叫瓦陇。"}]}, {"meaning": "生殖器。", "cites": [{"t": "那众强人那容分说,赶上前,把寇员外撩阴一脚,踢翻在地。", "b": "《西游记》"}]}, {"meaning": "指秋冬季节。", "cites": [{"t": "月是夜秋镜,寒为寂寞资。", "b": "唐·元稹《初寒夜寄卢子蒙》"}], "words": [{"w": "阴秋", "t": "秋季"}, {"w": "阴泉", "t": "秋冬之水"}, {"w": "阴条", "t": "秋冬仍青的树木"}, {"w": "阴时", "t": "秋冬之时"}, {"w": "阴期", "t": "秋冬季节。"}]}, {"meaning": "日影;阴影。", "cites": [{"t": "堂下之阴。", "b": "《吕氏春秋·察今》"}, {"t": "绿杨阴里白沙堤。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "树林阴翳。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "阴暎", "t": "树荫"}, {"w": "阴蔚", "t": "绿树茂盛浓密成荫"}, {"w": "阴森", "t": "树木浓密成荫"}, {"w": "阴林", "t": "茂林。"}]}, {"meaning": "雨。", "cites": [{"t": "日西则景朝多阴。", "b": "《周礼·大司徒》。疏:“即雨也。”"}], "words": [{"w": "阴朗", "t": "阴雨和晴朗"}, {"w": "阴泄", "t": "阴雨"}, {"w": "阴官", "t": "雨师;水神。"}]}, {"meaning": "水。", "cites": [{"t": "阴池幽流,玄泉冽清。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "阴蚪", "t": "水中的幼蛙"}, {"w": "阴族", "t": "水族。"}]}, {"meaning": "月亮。", "cites": [{"t": "日为阳,月为阴。", "b": "《素问》"}], "words": [{"w": "阴光", "t": "月光"}, {"w": "阴兔", "t": "月亮的别名。"}]}, {"meaning": "妇人。", "cites": [{"t": "弼佐王风,克柔阴化。", "b": "隋·江总《为陈六宫谢章》"}]}, {"meaning": "又如:阴教(女子的教化);阴化(女子的教化);阴德(女德);阴帝(指女娲)。"}, {"meaning": "坟,墓。", "cites": [{"t": "琢文阴壤,庶永后希。", "b": "宋·苏舜钦《广陵郡太君志铭》"}]}, {"meaning": "又如:阴壤(墓地);阴宅(坟墓;墓穴);阴户(墓门)。"}, {"meaning": "指月经。", "cites": [{"t": "女子七七四十九,阴绝。", "b": "王恽《玉堂嘉话》"}]}, {"meaning": "天空中十分之八以上的部分被中低云量占住叫做阴。", "cites": [{"t": "天阴雨湿。", "b": "唐·杜甫《兵车行》"}, {"t": "天阴黑。", "b": "《资治通鉴·唐纪》"}, {"t": "朝晖夕阴。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "浮云为我阴,悲风为我旋。", "b": "元·关汉卿《窦娥冤》"}]}, {"meaning": "又如:阴埃(阴雾和尘埃);阴晦(云气掩映日光,天气阴晦);阴凝冰坚(阴气始凝为霜,渐积成冰);阴澹(山色暗淡);阴雨(天阴下雨)。"}, {"meaning": "云块。", "cites": [{"t": "阴犹沉也。", "b": "汉·董仲舒《春秋繁露》。凌曙注:“蔡邕《月令章句》曰:‘阴者,密云也;沉者,云之重也。’”"}]}, {"meaning": "又如:阴霞(云霞)。"}, {"meaning": "鬼怪。", "cites": [{"t": "群山四渎,暮天晴、挥斥阴魔潜伏。", "b": "金·丘处机《无俗念·述怀》"}]}, {"meaning": "又如:阴魅(鬼魅);阴兵(鬼兵;神兵);阴力(鬼神之力);阴魅(魅火;鬼火)。"}, {"meaning": "中国古代哲学认为宇宙中贯通物质和人事的两大对立面之一(跟“阳”相对) 。阳的相对名称。", "cites": [{"t": "一阴一阳之谓道。", "b": "《易·系辞上》"}, {"t": "阴阳和而万物得。", "b": "《礼记·郊特性》"}, {"t": "天地之变,阴阳之化。", "b": "《荀子·天论》"}]}, {"meaning": "又如:阴阳不将(阴阳家所称的嫁娶吉日);阴阳官(专司星相、占卜、卜宅、相墓等的职官);阴阳生(阴阳人。指以星相、占卜、相宅、看风水等为职业的人)。"}, {"meaning": "凹进去的东西。", "cites": [{"t": "院门门额上还留有一块阴纹石匾。", "b": "茹志鹃《高高的白杨树》"}], "words": [{"w": "阴识", "t": "古器物上凹入的文字。即阴文。凸出的文字称为阳文"}, {"w": "阴纹", "t": "凹下的纹理。"}]}, {"meaning": "幽暗;昏暗。", "cites": [{"t": "阴径红桃落,秋坛白石生。", "b": "唐·姚合《游昊天玄都观》"}], "words": [{"w": "阴霾", "t": "空气中因悬浮着大量的烟、尘等微粒而形成混浊的现象"}, {"w": "阴煞", "t": "幽暗"}, {"w": "阴虹", "t": "昏暗的彩虹。比喻邪佞"}, {"w": "阴翥", "t": "翅毛浅黑色的凤"}, {"w": "阴堂", "t": "幽暗之室;墓室。"}]}, {"meaning": "阴险。", "cites": [{"t": "器性阴刻乐祸,残忍寡恩。", "b": "《旧唐书·崔器传》"}], "words": [{"w": "阴狙", "t": "阴险诡诈"}, {"w": "阴刻", "t": "阴险刻毒"}, {"w": "阴狡", "t": "阴险狡猾"}, {"w": "阴笑", "t": "冷笑;奸笑"}, {"w": "阴恶", "t": "阴险恶毒。"}]}, {"meaning": "冷,寒冷。", "cites": [{"t": "阴风怒号,浊浪排空。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "阴气", "t": "寒气,肃杀之气"}, {"w": "阴碛", "t": "塞外的沙漠。塞外很冷,故称"}, {"w": "阴宫", "t": "深宫;阴凉的宫室。"}]}, {"meaning": "阴湿;潮湿。", "cites": [{"t": "徽州世出墨工,多佳墨,云以置灰中,则阴润不能坏也。", "b": "宋·庄季裕《鸡肋编》"}], "words": [{"w": "阴润", "t": "阴湿滋润"}, {"w": "阴土", "t": "滋润的土壤。"}]}, {"meaning": "偶数。", "cites": [{"t": "禹铸九鼎,五者以应阳法,四者以象阴数。使工师以雌金为阴鼎,以雄金为阳鼎。", "b": "晋·王嘉《拾遗记》"}], "words": [{"w": "阴干", "t": "位于偶数的天干"}, {"w": "阴辰", "t": "指干支纪日中地支处于偶数的丑、卯、巳、未、酉、亥六日"}, {"w": "阴鼎", "t": "编列次序为偶数的鼎。"}]}, {"meaning": "隐藏的,不露在外面的。", "cites": [{"t": "阴血周作。", "b": "《左传·僖公十五年》"}], "words": [{"w": "阴事", "t": "隐秘的事情"}, {"w": "阴臣", "t": "私臣。一指妇人"}, {"w": "阴伏", "t": "阴私,阴事。指不为人所知的罪恶"}, {"w": "阴拱", "t": "私下敛下,不再参与。比喻袖手旁观"}, {"w": "阴恶", "t": "隐秘的不为人知的恶行;阴险狠毒"}, {"w": "阴阴", "t": "隐隐"}, {"w": "阴骘文", "t": "旧时专门劝人为善、做好事、积阴德的文章"}, {"w": "阴符", "t": "喻指军事谋略、部署等机密。"}]}, {"meaning": "暗中,暗地里。", "cites": [{"t": "大将军青亦阴受上诫。", "b": "《史记·李将军列传》"}, {"t": "阴相与谋。", "b": "《汉书·李广苏建传》"}, {"t": "阴知奸党姓名,一时收禽。", "b": "《后汉书·张衡传》"}, {"t": "阴纵之。", "b": "明·高启《书博鸡者事》"}, {"t": "执政阴沮。", "b": "清·张廷玉《明史》"}], "words": [{"w": "阴煞", "t": "损伤"}, {"w": "阴哂", "t": "暗笑"}, {"w": "阴哑", "t": "暗哑;嘶哑"}, {"w": "阴害", "t": "暗害"}, {"w": "阴中", "t": "暗中陷害。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('576wx','防','1','fáng','阝','6','','[{"pinyin": "fáng", "defs": [{"meaning": "(形声。从阜,方声。本义:堤坝)。"}, {"meaning": "同本义。", "cites": [{"t": "防,堤也。", "b": "《说文》"}, {"t": "以防止水。", "b": "《周礼·稻人》"}, {"t": "町原防。", "b": "《左传·襄公二十五年》"}, {"t": "祭防与水庸。", "b": "《礼记·郊特性》"}, {"t": "大者为之堤,小者为之防。", "b": "《管子·度地》"}, {"t": "巨防容蝼而漂邑杀人。", "b": "《吕氏春秋·慎小》。又如:防隅(水防山隅);沟防;堤防"}]}, {"meaning": "地名。"}, {"meaning": "春秋陈邑,在今河南省淮阳县北。"}, {"meaning": "春秋鲁地。在今山东省费城县东北。"}, {"meaning": "春秋宋地,后属鲁,在今山东省金乡县西南。"}, {"meaning": "住室。", "cites": [{"t": "夏,有芝生殿防内中。", "b": "《史记·武帝本纪》"}, {"t": "筑宫其上,名曰宣防。", "b": "《汉书·沟洫志》"}]}, {"meaning": "筑堤。", "cites": [{"t": "善防者水淫之。", "b": "《周礼·考工记》"}]}, {"meaning": "防止;防备。", "cites": [{"t": "不防川。", "b": "《国语·周语》。注:“障也。”"}, {"t": "防民之口,甚于防川。", "b": "《国语·周语上》"}, {"t": "逆阉防伺甚严,虽家仆不得近。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "防强盗;防雨;防辅", "t": "防止和辅导"}, {"w": "防侍", "t": "防备侍卫"}, {"w": "防患", "t": "防止祸患。"}]}, {"meaning": "防守;防御;防卫。", "cites": [{"t": "或从十五北防河,便至四十西营田。", "b": "唐·杜甫《兵车行》"}, {"t": "昼夜防拒,凡八十余日,城再崩再完,卒得不陷。", "b": "清·朱克敬《瞑庵杂识》"}], "words": [{"w": "防拒", "t": "防卫抵御"}, {"w": "防把", "t": "防御把守"}, {"w": "防戍", "t": "防守边境"}, {"w": "防营", "t": "防守地方的军队"}, {"w": "防塞", "t": "防卫堵绝。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('577wx','奸','1','gān jiān','女','6','','[{"pinyin": "gān", "defs": [{"meaning": "干犯,抵触。", "cites": [{"t": "奸时以动,而疲民以逞。", "b": "《左传·成公十六年》"}, {"t": "使而失命,召而不来,是再奸也。", "b": "《左传·昭公二十年》。杜预注:奸,犯也。"}, {"t": "以奸者七十二君,论先王之道而明周召之迹,一君无所钩用。", "b": "《庄子·天运》"}, {"t": "各守其职,不得相奸。", "b": "《淮南子·主术》"}, {"t": "以渔钓奸周西伯。", "b": "《史记·齐太公世家》"}, {"t": "察其驰骋步骤,芒炎或长或短,所历奸犯。", "b": "《汉书·五行志下》"}]}]}, {"pinyin": "jiān", "defs": [{"meaning": "(会意。从三女。本义:奸邪,虚伪狡诈)。"}, {"meaning": "同本义。", "cites": [{"t": "姦,私也。", "b": "《说文》"}, {"t": "姦,盗也。", "b": "《广雅》"}, {"t": "在内曰姦,在外曰宄。", "b": "《三苍》"}, {"t": "用轨之财者为姦。", "b": "《国语·鲁语》"}, {"t": "寇贼姦宄。", "b": "《书·舜典》"}, {"t": "是以其民饥寒并至,故为奸衺(xié同邪)。", "b": "《墨子·辞过》"}, {"t": "故以刑治则民威,民威则无姦,无姦则民安其所乐。", "b": "《商君书·开塞》"}, {"t": "荡渨湋之姦咎兮。", "b": "《梦辞·惜贤》。注:“乱在内曰姦。”"}, {"t": "盗器为姦。", "b": "《左传·文公十八年》"}, {"t": "多贼姦些。", "b": "《楚辞·招魂》。注:“恶也。”"}, {"t": "姦宄是防。", "b": "张衡《西京赋》。注:“邪也。”"}, {"t": "作奸犯科。", "b": "诸葛亮《出师表》"}, {"t": "攘除奸凶。", "b": ""}, {"t": "吏奸而不知禁。", "b": "明·刘基《卖柑者言》"}, {"t": "奸人构陷。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "奸慝", "t": "奸诈;邪恶"}, {"w": "奸顽", "t": "奸诈凶顽"}, {"w": "奸回", "t": "奸恶邪僻;奸邪"}, {"w": "奸智", "t": "奸诈邪恶的企图"}, {"w": "奸侠", "t": "心怀邪恶的人。即俗称的无赖汉"}, {"w": "奸非", "t": "作奸犯法的人"}, {"w": "奸利", "t": "作奸犯法所获得的利益"}, {"w": "奸证", "t": "做坏事的脏证"}, {"w": "奸钱", "t": "私铸的钱币"}, {"w": "奸事", "t": "不正当的事;非法的事"}, {"w": "奸市", "t": "违法交易"}, {"w": "奸宄", "t": "违法作乱的事情。"}]}, {"meaning": "伪。", "cites": [{"t": "姦,伪也。", "b": "《广雅》"}, {"t": "夫神者好和而恶姦。", "b": "《庄子·徐无鬼》。注:“私自许者姦也。”"}, {"t": "十姦。", "b": "《周书·宝典》。注:“不诚之行故曰姦。”"}]}, {"meaning": "(会意。从女,从干,干亦声。本义:奸淫;私通)。"}, {"meaning": "同本义。", "cites": [{"t": "奸,犯淫也。", "b": "《说文》"}, {"t": "夫人姜氏会齐侯于禚。书,姦也。", "b": "《左传·庄公二年》"}], "words": [{"w": "奸私", "t": "通奸"}, {"w": "奸占", "t": "非法占人妻女"}, {"w": "奸状", "t": "男女私通"}, {"w": "奸宿", "t": "奸通"}, {"w": "奸乱", "t": "淫乱。"}]}, {"meaning": "作乱或窃夺。", "cites": [{"t": "奸,犯也。", "b": "《小尔雅》"}, {"t": "臣敢奸之。", "b": "《左传·襄公十四年》"}, {"t": "是再奸也。", "b": "《左传·昭公二十年》"}, {"t": "奸时以动。", "b": "《左传·成公十六年》"}, {"t": "以奸忠直。", "b": "《汉书·孔光传》"}, {"t": "以奸者七十二君。", "b": "《庄子·天运》"}, {"t": "各守其职,不得相姦。", "b": "《淮南子·主术》。按,姦假借为干。”"}], "words": [{"w": "奸赃", "t": "营私纳贿"}, {"w": "奸盗", "t": "指为非作歹、劫盗财物。"}]}, {"meaning": "欺骗;作弄。", "cites": [{"t": "你奸得我索性。", "b": "元·高明《琵琶记》"}]}, {"meaning": "犯法作乱的人,歹徒;恶人。", "cites": [{"t": "故佼众者誉多,外内朋党,虽有大姦,其蔽主多矣。", "b": "《管子·明法》"}, {"t": "不告奸者腰斩。", "b": "《史记·商君列传》"}, {"t": "奸宄不得萌动而破灭。", "b": "《汉书·辛庆忌传》"}], "words": [{"w": "奸宄", "t": "为非作歹的坏人;奸臣"}, {"w": "奸凶", "t": "邪恶凶顽的人"}, {"w": "奸乱", "t": "心术不正,行迹不轨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('578wx','如','1','rú','女','6','','[{"pinyin": "rú", "defs": [{"meaning": "(会意。从女,从口。本义:遵从,依照)。"}, {"meaning": "同本义。", "cites": [{"t": "如,从随也。", "b": "《说文》。按,此字疑从女,若省声。女子从人者也。"}, {"t": "有律以如己也。", "b": "《左传·宣公十二年》。杜预注:“如,从也。”"}, {"t": "所不与舅氏同心者,有如白水!", "b": "《左传·僖公二十三年》"}, {"t": "犬皆如人意。", "b": "《柳宗元《三戒》"}], "words": [{"w": "如命", "t": "遵从命令"}, {"w": "如志", "t": "随顺意愿;实现志愿"}, {"w": "如令", "t": "从令,遵令。"}]}, {"meaning": "好像, 如同。", "cites": [{"t": "日初出大如车盖。", "b": "《列子·汤问》"}, {"t": "状貌如妇人女子。", "b": "《史记·留侯世家》"}, {"t": "两狼之并驱如故。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "如皋雉", "t": "比喻男子以才华博得女子青睐"}, {"w": "如许", "t": "似这般"}, {"w": "如今晚儿", "t": "现在"}, {"w": "如许豚犊", "t": "这样的不肖之子"}, {"w": "如应如响", "t": "十分灵验。"}]}, {"meaning": "比得上,及。", "cites": [{"t": "不如无生。", "b": "《诗·小雅·苕之华》"}, {"t": "窥镜而自视,又弗如远甚。", "b": "《战国策·齐策》"}, {"t": "臣之壮也,犹不如人。", "b": "《左传·僖公三十年》"}], "words": [{"w": "我不如他", "t": ""}]}, {"meaning": "去,往。", "cites": [{"t": "如,往也。", "b": "《尔雅》"}, {"t": "坐须臾,沛公起如厕。", "b": "《史记·项羽本纪》"}, {"t": "以一仪而当汉中地,臣请往如楚。", "b": "《史记·屈原贾生列传》"}, {"t": "如扬州过瓜洲扬子桥。", "b": "文天祥《指南录后序》"}]}, {"meaning": "遭遇,际遇。", "cites": [{"t": "淮阳叶生者,失其名字。文章词赋,冠绝当时;而所如不偶,因于名场。", "b": "《聊斋志异》"}]}, {"meaning": "相敌;抵挡。", "cites": [{"t": "夫宋之不足如梁也,寡人知之矣。", "b": "《战国策》"}]}, {"meaning": "应当。", "cites": [{"t": "君若爱司马,则如亡。", "b": "《左传》"}]}, {"meaning": "按照。", "cites": [{"t": "王如其言,煮头,三日三夕不烂。", "b": "晋·干宝《搜神记》"}], "words": [{"w": "如详缴", "t": "照报告中对原案处理的办法处理,并且准予销案"}, {"w": "如律令", "t": "按照法令执行。是古代檄文、诏书结尾用语"}, {"w": "如式", "t": "按照规矩。"}]}, {"meaning": "假如,如果。", "cites": [{"t": "如,若也。", "b": "《广雅》"}, {"t": "如用之,则吾从先进。", "b": "《论语·先进》"}, {"t": "如有复我者,则吾必在坟上矣。", "b": "《论语·阳货》"}, {"t": "如有地动,尊则振龙,机发吐丸,而蟾蜍衔之。", "b": "《后汉书·张衡传》"}, {"t": "洛阳亲友如相问。", "b": "唐·王昌龄《芙蓉楼送辛渐》诗"}], "words": [{"w": "如有不妥,请予指正;如不修改,未免粗糙;如使", "t": "假使;倘若。"}]}, {"meaning": "与,和。", "cites": [{"t": "公如大夫入。", "b": "《仪礼》"}]}, {"meaning": "或——表示选择关系。", "cites": [{"t": "安见方六七十、如五六十,而非邦也者。", "b": "《论语·先进》"}]}, {"meaning": "而——表示连接。", "cites": [{"t": "如有隐忧。", "b": "《诗·邶风·柏舟》"}, {"t": "夜中,星陨如雨。", "b": "《春秋》"}]}, {"meaning": "用于语末,相当于“然”。", "cites": [{"t": "子之燕居,申申如也。", "b": "《论语·述而》"}, {"t": "褎如充耳。", "b": "《诗·邶风·旄丘》"}, {"t": "屯如,乘马班如。", "b": "《易·屯卦》"}, {"t": "孔子三月如君,则皇皇如也。", "b": "《孟子·滕文公上》"}]}, {"meaning": "用于语末,相当于“焉”。", "cites": [{"t": "突如,其来如,焚如,死如,弃如。", "b": "《易·离》"}]}, {"meaning": "相当于“乎”。", "cites": [{"t": "善如尔之问也。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('579wx','妇','1','fù','女','6','','[{"pinyin": "fù", "defs": [{"meaning": "(会意。甲骨文字形,左边是“帚”,右边是“女”。从女持帚,表示洒扫。本义:已婚的女子)。"}, {"meaning": "同本义。", "cites": [{"t": "婦,服也。从女,持帚,洒埽也。会意。谓服事人者。", "b": "《说文》"}, {"t": "女子谓之妇人。", "b": "《广雅》"}, {"t": "妇人侠床。", "b": "《仪礼·士丧礼》。注:“妻妾子姓也。”"}, {"t": "士曰妇人,庶人曰妻。", "b": "《礼记·曲礼》"}, {"t": "听妇前致词,三男邺城戍。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "少妇;孕妇;媳妇;妇驵", "t": "交易时的女介绍人"}, {"w": "妇政", "t": "妇人参与政事"}, {"w": "妇人家", "t": "已婚妇女。"}]}, {"meaning": "泛指妇女,常指成年女子。", "cites": [{"t": "纵有健妇把锄犁,禾生陇亩无东西。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "妇职", "t": "妇女应做的事"}, {"w": "妇饰", "t": "妇女的打扮妆饰"}, {"w": "妇师", "t": "妇女的模范"}, {"w": "妇仪", "t": "妇女的容德规范"}, {"w": "妇德", "t": "妇女贞顺的德行"}, {"w": "妇道家", "t": "妇道人,妇道人家。女人。"}]}, {"meaning": "妻子。", "cites": [{"t": "门前冷落鞍马稀,老大嫁作商人妇。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "十七为君妇。", "b": "《乐府诗集·焦仲卿妻》"}], "words": [{"w": "新妇", "t": "新娘"}, {"w": "夫妇", "t": "夫妻"}, {"w": "妇子", "t": "妻与子"}, {"w": "妇氏", "t": "妇家。妻子的娘家"}, {"w": "妇翁", "t": "妻父。"}]}, {"meaning": "儿媳。", "cites": [{"t": "子之妻曰妇。", "b": "《尔雅》"}, {"t": "父殁而子嗣,姑死而妇代。", "b": "《论衡·偶会》"}, {"t": "非为织作迟,君家妇难为。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "妇姑", "t": "婆媳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('580wx','妃','1','fēi','女','6','','[{"pinyin": "fēi", "defs": [{"meaning": "(会意。从女,己声。本义:婚配,配偶)。"}, {"meaning": "(pèi)。同本义。", "cites": [{"t": "妃,匹也。", "b": "《说文》"}, {"t": "嘉耦曰妃。", "b": "《左传·桓公二年》"}, {"t": "故黄帝作君臣上下之义,父子兄弟之礼,夫妇妃匹之合。", "b": "《商君书·画策》"}], "words": [{"w": "吉妃", "t": "美满的婚配。"}]}, {"meaning": "泛指妻子。", "cites": [{"t": "以某妃配某氏。", "b": "《仪礼·少牢礼》。注:“某妃,某妻也。”"}, {"t": "嫘祖为黄帝正妃。", "b": "《史记》"}]}, {"meaning": "帝王的妾。", "cites": [{"t": "宿有妃,嫱嫔御焉。", "b": "《左传·哀公元年》"}], "words": [{"w": "妃妾", "t": "皇帝的妾"}, {"w": "妃嫔", "t": "帝王的妾侍。妃,位次于后;嫔,位又次于妃。"}]}, {"meaning": "特指太子、王侯之妻。", "cites": [{"t": "天子之妃曰后。", "b": "《礼记·曲礼》。注:“配也。”"}, {"t": "皇帝纳皇后。…皇太子纳妃。…亲王纳妃。", "b": "《新唐书》"}]}, {"meaning": "女神的尊称。", "cites": [{"t": "从南湘之二妃。", "b": "三国魏·曹植《洛神赋》"}]}, {"meaning": "某一事物的对立面。因其既相反又相成,故称。", "cites": [{"t": "水,火妃也。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('581wx','好','1','hǎo hào','女','6','','[{"pinyin": "hǎo", "defs": [{"meaning": "(会意。从女,从子。本义:美,貌美)。"}, {"meaning": "指女子貌美。", "cites": [{"t": "好,美也。", "b": "《说文》"}, {"t": "凡美色或谓之好。", "b": "《方言二》"}, {"t": "不可谓好。", "b": "《国语·晋语》。注:“美也。”"}, {"t": "是女子不好。", "b": "《史记·滑稽列传》"}, {"t": "鬼侯有子而好。", "b": "《战国策·赵策》"}, {"t": "秦氏有好女。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "好皮囊", "t": "好看的外貌"}, {"w": "好鸟", "t": "美丽的鸟"}, {"w": "好不丑", "t": "反语。即好不俊,俊得很"}, {"w": "好美", "t": "美貌"}, {"w": "好闲", "t": "容貌美丽,举止闲雅"}, {"w": "好妇", "t": "美貌的妇女。"}]}, {"meaning": "善,优良,良好。", "cites": [{"t": "领恶而全好者与。", "b": "《礼记·仲尼燕居》。注:“善也。”"}, {"t": "父信谗而不好。", "b": "《楚辞·惜诵》"}, {"t": "又是江南好风景。", "b": "唐·杜甫《江南逢李龟年》"}, {"t": "好雨知时节。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "江南好。", "b": "唐·白居易《忆江南》"}, {"t": "注曰不好。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "好天良夜", "t": "美好的时节"}, {"w": "好日", "t": "吉日;好天;又指结婚佳期"}, {"w": "好头脑", "t": "好对象;好人物"}, {"w": "好言", "t": "善言;好话。"}]}, {"meaning": "交好;友爱。", "cites": [{"t": "妻子好合。", "b": "《诗·小雅·常棣》"}, {"t": "欲与王为好。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "结好孙权。", "b": "《三国志·诸葛亮传》"}, {"t": "情好日密。", "b": ""}, {"t": "游处相好。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "好会", "t": "诸侯间友好的会盟"}, {"w": "好达达", "t": "妇女对男子的昵称。"}]}, {"meaning": "完成;完毕。", "cites": [{"t": "田车既好。", "b": "《诗·小雅·车攻》"}, {"t": "凤生将书封好,一同玉蟾蜍交付龙香。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "工具都准备好了", "t": ""}]}, {"meaning": "便于;宜于。", "cites": [{"t": "缁衣之好兮。", "b": "《诗·郑风·缁衣》"}], "words": [{"w": "好合", "t": "志意相合。"}]}, {"meaning": "宜于;便于;以便。", "cites": [{"t": "青春作伴好还乡。", "b": "唐·杜甫《闻官军收河南河北》"}], "words": [{"w": "想法打蛇的头,好打晕它;你作个决定,我好回他;你交代下来,我好去叫他", "t": ""}]}]}, {"pinyin": "hào", "defs": [{"meaning": "喜好;喜爱。", "cites": [{"t": "好憎者,心之暴也。", "b": "《淮南子·精神》"}, {"t": "人之好我。", "b": "《诗·小雅·鹿鸣》"}, {"t": "好治不病。", "b": "《韩非子·喻老》"}, {"t": "敏而好学。", "b": "《论语》"}, {"t": "黔无驴,有好事者船载以入。", "b": "唐·柳宗元《三戒》"}, {"t": "自幼好武术。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "好表现;好善", "t": "喜爱行善"}, {"w": "好涵高躅", "t": "喜欢混迹于高人之列"}, {"w": "好戏子", "t": "好奇"}, {"w": "好玩", "t": "爱玩儿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('582wx','她','1','tā','女','6','','[{"pinyin": "tā", "defs": [{"meaning": "(形声。从女,“它”省声。本义:女性第三人称)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('583wx','妈','1','mā','女','6','','[{"pinyin": "mā", "defs": [{"meaning": "(形声。从女,马声。本义:称呼母亲)。"}, {"meaning": "同本义。", "cites": [{"t": "妈,母也。", "b": "《广雅·释亲》"}], "words": [{"w": "有妈的孩子像个宝,没妈的孩子像根草;孩子的妈;谢谢妈", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('584wx','戏','1','hū huī xì','戈','6','','[{"pinyin": "hū", "defs": [{"meaning": "——“於戏”(wūhū):同“呜呼”(wūhū)。"}]}, {"pinyin": "huī", "defs": []}, {"pinyin": "xì", "defs": [{"meaning": "(形声。从戈。虚(xī)声。本义:一种兵器)。"}, {"meaning": "同本义。"}, {"meaning": "假借为“麾”。军队中的帅旗。", "cites": [{"t": "兵罢戏。", "b": "《史记·高帝纪》。正义:“大旗也。”"}, {"t": "戏下骑从者八百余人。", "b": "《汉书·项籍传》。注:“大将之旗。”"}]}, {"meaning": "侧翼。", "cites": [{"t": "戏,三军之偏也。", "b": "《说文》。段玉裁注:“偏为前拒之偏,谓军所驻之一面也。”"}]}, {"meaning": "指歌舞杂技等的表演。", "cites": [{"t": "云烟古寺闻僧梵,灯火长桥见戏场。", "b": "宋·陆游《出游》"}], "words": [{"w": "戏场", "t": "表演歌舞杂技的场子"}, {"w": "散戏;猴戏;游戏;排戏;配戏", "t": "配合主角演戏"}, {"w": "扮戏", "t": ""}]}, {"meaning": "戏剧。", "cites": [{"t": "那明湖居本是个大戏园子,戏台前有一百多张桌子。", "b": "《老残游记》"}], "words": [{"w": "戏提调", "t": "戏曲演出时负责安排戏码、分配演员、场面调度等事务的人"}, {"w": "戏面", "t": "假面具"}, {"w": "戏头", "t": "宋代戏曲演出中的主要角色之一"}, {"w": "京戏;黄梅戏", "t": ""}]}, {"meaning": "游戏。", "cites": [{"t": "尚促织之戏。", "b": "《聊斋志异·促织》"}]}, {"meaning": "角斗,角力。", "cites": [{"t": "少室周为赵简子之右,闻牛谈有力,请与之戏,弗胜,致右焉。", "b": "《国语·晋语九》。韦昭注:“戏,角力也。”"}]}, {"meaning": "开玩笑,耍笑捉弄。", "cites": [{"t": "偃之言是也。前言戏之耳。", "b": "《论语·阳货》"}, {"t": "智襄子戏韩康子而侮段规。", "b": "《国语·晋语九》"}], "words": [{"w": "戏辱", "t": "戏弄侮辱"}, {"w": "戏妇", "t": "戏弄新娘"}, {"w": "戏说", "t": "开玩笑。"}]}, {"meaning": "游戏;戏耍。", "cites": [{"t": "吴用见了,便教军校迎敌戏战,他若追来,乘势便退。", "b": "《水浒传》"}, {"t": "剧孟行大类朱家,而好博,多少年之戏。", "b": "《史记·游侠列传》"}, {"t": "宣德间,宫中尚促织之戏,岁征民间。", "b": "《聊斋志异·促织》"}, {"t": "留连戏蝶。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "门外戏。", "b": "《世说新语·方正》"}], "words": [{"w": "戏适", "t": "游戏消遣"}, {"w": "戏娱", "t": "游戏娱乐。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('585wx','羽','1','yǔ','羽','6','','[{"pinyin": "yǔ", "defs": [{"meaning": "(象形。甲骨文字形,象羽毛形,即鸟的长翎(líng)形。“羽”是汉字的一个部首,从“羽”的字多与羽毛有关。本义:鸟毛,特指鸟的长毛)。"}, {"meaning": "同本义。", "cites": [{"t": "羽,鸟长毛也。象形。", "b": "《说文》"}, {"t": "羽虫三百六十,而凤为之长。", "b": "《孔子家语·执辔》"}, {"t": "教羽舞。", "b": "《周礼·舞师》"}, {"t": "初献六羽。", "b": "《左传·隐公五年》"}, {"t": "染羽。", "b": "《考工记·钟氏》"}, {"t": "剑盾为羽旗,车为龙旗。", "b": "《墨子·旗帜》"}], "words": [{"w": "羽葆鼓吹", "t": "仪仗乐队"}, {"w": "羽葆翠盖", "t": "以翠羽连缀为饰的华丽车盖"}, {"w": "羽葆花旌", "t": "仪仗旗帜"}, {"w": "羽仪廊庙", "t": "指受到朝廷重视,其德行为满朝文武之楷模"}, {"w": "羽旆", "t": "用羽毛装饰的旌旗"}, {"w": "羽佩", "t": "以翠羽为饰的佩带。"}]}, {"meaning": "鸟类。", "cites": [{"t": "寡人之有仲父也,犹飞鸿之有羽翼也。", "b": "《管子·霸形》"}], "words": [{"w": "羽族", "t": "泛指鸟类"}, {"w": "羽物", "t": "鸟类"}, {"w": "羽皮", "t": "鸟兽的毛皮"}, {"w": "羽翔", "t": "首翼色青的鸾鸟"}, {"w": "羽翮", "t": "泛指鸟类"}, {"w": "羽类", "t": "鸟类。"}]}, {"meaning": "鸟虫的翅膀。", "cites": [{"t": "双燕戏云崖,羽翰始差池。", "b": "南朝宋·鲍照《咏双燕》"}], "words": [{"w": "羽肢", "t": "肢膀"}, {"w": "羽翎", "t": "鸟翼。"}]}, {"meaning": "指旌旗。", "cites": [{"t": "翠凤翔文螭,羽节朝玉帝。", "b": "唐·王维《金屑泉》"}], "words": [{"w": "羽旆", "t": "以羽毛为饰的旗帜"}, {"w": "羽旗", "t": "翠羽装饰的旌旗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('586wx','观','1','guān guàn','见','6','','[{"pinyin": "guān", "defs": [{"meaning": "(形声。从见,雚(guàn)声。本义:仔细看)。"}, {"meaning": "同本义。", "cites": [{"t": "观,谛视也。", "b": "《说文》"}, {"t": "观,视也。", "b": "《广雅·释诂一》"}, {"t": "观者如市。", "b": "《庄子·人间世》"}, {"t": "观于大海。", "b": "《庄子·秋水》"}, {"t": "曹共公闻其骈胁,欲观其裸;浴,薄而观之。", "b": "《左传·僖公二十三年》"}, {"t": "仰则观象于天,俯则观法于地。", "b": "《易·系辞下》"}, {"t": "吴王从台上观,见且斩爱姬,大骇。", "b": "《史记·孙子吴起列传》"}, {"t": "以人民往观之者三二千人。", "b": "《史记·滑稽列传》"}, {"t": "启窗而观,雕栏相望焉。", "b": "明·魏学洢《核舟记》"}, {"t": "因得观所谓石钟山中者。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "观觑", "t": "观看"}, {"w": "观占", "t": "观瞻,观看"}, {"w": "观玩", "t": "观看赏玩"}, {"w": "观涛", "t": "观赏浪潮"}, {"w": "观成", "t": "观看成果。"}]}, {"meaning": "观察,审察。", "cites": [{"t": "由此观之,王之蔽甚矣。", "b": "《战国策·秦策》"}, {"t": "吾观晋公子之从者,皆足以相国。", "b": "《左传·僖公二十三年》"}, {"t": "故为之说,以俟夫观人风者得焉。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "参观", "t": "实地观察"}, {"w": "综观", "t": "综合观察"}, {"w": "坐井观天;观过知仁", "t": "观察一个人所犯错误的性质,就可了解他的为人"}, {"w": "观时", "t": "察看时机。"}]}, {"meaning": "示范;显示。", "cites": [{"t": "诸侯之师观兵于郑东门。", "b": "《左传·哀公十一年》"}, {"t": "嘉量既成,以观四国。", "b": "《周礼·冬官》"}, {"t": "飨赐单于,观以珍宝。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "观治", "t": "显示治绩"}, {"w": "观民", "t": "显示于民"}, {"w": "观世", "t": "向世人显示"}, {"w": "观示", "t": "示范。"}]}, {"meaning": "玩赏;观赏。", "cites": [{"t": "公将如棠观鱼。", "b": "《左传·隐公元年》"}, {"t": "予观夫巴陵胜状,在洞庭一湖。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "观风", "t": "亦作“关风”。观赏风光;望风"}, {"w": "观乐", "t": "观赏玩乐;欣赏音乐"}, {"w": "观玩", "t": "观赏玩味。"}]}, {"meaning": "阅读。", "cites": [{"t": "余因得遍观群书。", "b": "明·宋濂《送东阳马生序》"}, {"t": "姑俟异目观。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "景象,情景。", "cites": [{"t": "此则岳阳楼之大观也。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "而世之奇伟、瑰怪、非常之观,常在于险远。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "奇观", "t": "雄伟美丽而又罕见的景象或出奇少见的事情"}, {"w": "旧观", "t": "原来的样子"}, {"w": "改观", "t": "改变原来的样子"}, {"w": "壮观", "t": "壮丽的景象"}, {"w": "大观", "t": "气势宏大的景象。"}]}]}, {"pinyin": "guàn", "defs": [{"meaning": "古代天子、诸侯宫门外张示法令的地方。同“阙”。", "cites": [{"t": "观谓之阙。", "b": "《尔雅·释宫》郭璞注:“孙炎曰:‘宫门双阙,旧章悬焉,使民观之,因谓之观。’”。"}, {"t": "出游于观之上。", "b": "《礼记·礼运》"}, {"t": "是以凤凰来信,集羽族于观阙,肉角驯毛宗于外囿。", "b": "《后汉书·班固传·典引》"}], "words": [{"w": "观阙", "t": "古代帝王宫门前的两座楼台"}, {"w": "观魏", "t": "即观阙。"}]}, {"meaning": "台榭。", "cites": [{"t": "宫室不观,舟车不饰。", "b": "《左传·哀公元年》"}, {"t": "大王见臣列观。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "若稍饰以楼观亭榭,与江山相发挥,自当高出金山之上矣。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "观台", "t": "台榭"}, {"w": "观榭", "t": "亭台楼榭"}, {"w": "观阁", "t": "亭台楼阁。"}]}, {"meaning": "道教的庙宇。", "cites": [{"t": "臣请本道定寺为三等,观为二等。上寺留僧二十一,上观道士十四。", "b": "《新唐书·李叔明传》"}, {"t": "玄都观里桃千树,尽是刘郎去后栽。", "b": "唐·刘禹锡《戏赠看花君子》"}, {"t": "不税于官,不隶于宫观之籍。", "b": "顾炎武《复庵记》"}], "words": [{"w": "白云观;观寺", "t": "寺观"}, {"w": "观宇", "t": "道观佛寺"}, {"w": "观阙", "t": "指庙宇。"}]}, {"meaning": "雚雀鸟。", "cites": [{"t": "彼视三釜三千钟,如观雀蚊虻相过乎前也。", "b": "《庄子·寓言》"}]}, {"meaning": "姓。春秋楚有观射父。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('587wx','欢','1','huān','欠','6','','[{"pinyin": "huān", "defs": [{"meaning": "(形声。从欠,雚(guàn)声。本义:喜悦,高兴)。"}, {"meaning": "同本义。", "cites": [{"t": "欢,喜乐也。", "b": "《说文》"}, {"t": "君子不尽人之欢。", "b": "《礼记·曲礼》"}, {"t": "夫妇不得不驩。", "b": "《荀子·大略》"}, {"t": "若果养乎?予果欢乎?", "b": "《庄子·至乐》"}, {"t": "许子而大欢,彼将知君利之也。", "b": "《韩非子·说林上》"}, {"t": "而大国与之懽。", "b": "《战国策·秦策》"}, {"t": "饮酒则欢乐。", "b": "《庄子·渔父》"}, {"t": "今日之欢。", "b": "《汉书·李广苏建传》"}, {"t": "众宾欢也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "欢动一城。", "b": "明·高启《书博鸡者事》"}, {"t": "奉一日之欢。", "b": "清·侯方域《壮悔堂文集》"}], "words": [{"w": "欢容", "t": "喜悦的容颜"}, {"w": "欢洽", "t": "快乐和睦"}, {"w": "欢哄", "t": "欢乐,哄闹"}, {"w": "欢情", "t": "喜悦的心情。"}]}, {"meaning": "欢迎,殷勤地或诚挚地迎接。", "cites": [{"t": "闻其声,争交欢解。", "b": "《史记·游侠列传》"}], "words": [{"w": "欢门", "t": "宋代酒馆、店铺用彩色纸帛装饰门窗,以招徕顾客,谓之欢门。"}]}, {"meaning": "古时男女相爱,女子对情人的称呼。", "cites": [{"t": "唱尽新词欢不见,红霞映树鹧鸪鸣。", "b": "刘禹锡《踏歌词》"}, {"t": "闻欢下扬州,相送楚山头。", "b": "古乐府《莫愁乐》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('588wx','买','1','mǎi','乙','6','','[{"pinyin": "mǎi", "defs": [{"meaning": "(会意。小篆字形,从网贝。“网”是收进,“贝”是财货。合起来表示把财货购进来。本义:买进,购进)。"}, {"meaning": "同本义。", "cites": [{"t": "买,市也。", "b": "《说文》"}, {"t": "请买其方百金。", "b": "《庄子·逍遥游》"}, {"t": "买粥易也。", "b": "《墨子·经说》"}, {"t": "郑人买其椟而还其珠。", "b": "《韩非子·外储说左上》"}, {"t": "买妾不知其姓,则卜之。", "b": "《礼记·曲礼》"}], "words": [{"w": "买嘴吃", "t": "买零食吃"}, {"w": "买市", "t": "旧市官方或豪绅定期召集商贩开市,以买卖财物为名,犒赏百姓"}, {"w": "买山", "t": "购置山地,作为隐居之处"}, {"w": "买骨", "t": "买马骨。比喻求贤之切"}, {"w": "买菜求益", "t": "买菜求小便宜,要求多给一点菜。比喻斤斤计较。"}]}, {"meaning": "雇,租。", "cites": [{"t": "买舟而下。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "买棹", "t": "雇船;乘船"}, {"w": "买帆", "t": "买舟,买船,买棹,雇船"}, {"w": "买佣", "t": "雇用工人"}, {"w": "买活", "t": "雇用。"}]}, {"meaning": "用金钱或其他手段取得;收买,买通。", "cites": [{"t": "沉吟此事泪满衣,黄金买醉未能归。", "b": "李白《梁园吟》"}], "words": [{"w": "买和", "t": "为使对方放弃诉讼,理亏的一方付与对方一定数目的钱财"}, {"w": "买上告下", "t": "对官府上上下下行贿求告"}, {"w": "习官", "t": "用钱财以求得官位"}, {"w": "习邻", "t": "先选择好的邻居再买房子"}, {"w": "买路钱", "t": "旧时出丧时沿途抛洒金奶纸钱;旧时盗贼拦路抢劫,称所得为买路钱"}, {"w": "买休", "t": "犯罪的人花钱了结事情。"}]}, {"meaning": "招惹,引起。", "cites": [{"t": "此所谓市怨而买祸者也。", "b": "《战国策·韩策》"}], "words": [{"w": "买忧", "t": "招惹忧愁"}, {"w": "买出", "t": "招惹出;引起"}, {"w": "买憔悴", "t": "寻烦恼,惹祸患。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('589wx','红','1','hóng gōng','纟','6','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,工声。本义:粉红色)。"}, {"meaning": "同本义。", "cites": [{"t": "红,帛赤白色也。", "b": "《说文》。段注:“按,此今人所谓粉红、桃红也。”"}, {"t": "缙红繎。", "b": "《急就篇》。颜注:“红,色赤而白也。”"}, {"t": "红,绛也,白色似绛者也。", "b": "《释名·释采帛》"}, {"t": "红紫不以为亵服。", "b": "《论语·乡党》"}], "words": [{"w": "红衣", "t": "荷花瓣儿"}, {"w": "红香", "t": "花瓣"}, {"w": "红脂", "t": "蟹黄。"}]}, {"meaning": "后也指各种红色。", "cites": [{"t": "日出江花红胜火,春来江水绿如蓝。", "b": "唐·白居易《忆江南》"}], "words": [{"w": "红巾", "t": "红色巾。对绿林好汉的称呼,因为他们常用红巾包头,史籍上因称红巾"}, {"w": "红灼灼", "t": "形容鲜红"}, {"w": "红颩颩", "t": "亦作“红彪彪”。形容鲜红"}, {"w": "红轮", "t": "红日。"}]}, {"meaning": "红色物品。"}, {"meaning": "花的代称,花多红色,故借红代花。", "cites": [{"t": "晓看红湿处。", "b": "唐·杜甫《春夜喜雨》"}], "words": [{"w": "红芳", "t": "指红花"}, {"w": "红林", "t": "盛开红花的树林"}, {"w": "红萼", "t": "红花"}, {"w": "红葩", "t": "红花。"}]}, {"meaning": "春秋时鲁国地名。在今山东省境内。", "cites": [{"t": "秋,蒐于红。", "b": "《春秋》"}]}]}, {"pinyin": "gōng", "defs": [{"meaning": "女工,从事手工劳动的女性。", "cites": [{"t": "农夫释耒,红女下机。", "b": "《汉书·郦食其传》"}, {"t": "吾已食禄,又夺园夫女红利虖。", "b": "《汉书·董仲舒传》"}]}, {"meaning": ""}, {"meaning": "功服。丧服名。", "cites": [{"t": "服大红十五日,小红十四日。", "b": "《汉书·景帝纪》"}]}, {"meaning": "劳绩,功绩。", "cites": [{"t": "雕文刻镂,伤农事者也;锦绣纂组,害女红者也。", "b": "《汉书·景帝纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('590wx','驮','1','tuó duò','马','6','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从马,大声。本作“佗”。《说文》:“负何也。”本义:骡马负载东西)。"}, {"meaning": "同本义。用背负载。", "cites": [{"t": "驮,负物也。", "b": "《说文新附》"}, {"t": "其奇畜则橐佗。", "b": "《汉书·匈奴传上》。师古曰:“橐佗,言能负橐囊而驮物也。”"}]}, {"meaning": "挨;受。", "cites": [{"t": "丫头驮打,丫头驮骂,丫头也是爷娘生,夫人打我,少打几下。", "b": "赵景深辑《古代儿歌资料》"}]}]}, {"pinyin": "duò", "defs": [{"meaning": "驮着货物的牲口或牲口所负载的货物", "words": [{"w": "驮垛", "t": "又称驮担、驮装、驮子。捆扎成垛供驮运的货物或行李。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('591wx','纤','1','qiàn xiān','纟','6','','[{"pinyin": "qiàn", "defs": [{"meaning": "用于拉船的绳索。", "cites": [{"t": "我比不得他们扯篷拉纤的图银子。", "b": "《红楼梦》"}], "words": [{"w": "纤道", "t": "江河两岸纤夫挽船前进的小路"}, {"w": "纤路", "t": "纤道。"}]}, {"meaning": "牵牲口的绳索。", "cites": [{"t": "马牛有纤,私属有闲。", "b": "唐·刘禹锡《观市》"}]}]}, {"pinyin": "xiān", "defs": [{"meaning": "(形声。从糸,千声从糸(mī),细丝,表微小。本义:细小)。"}, {"meaning": "同本义。", "cites": [{"t": "纤,细也。", "b": "《说文》"}, {"t": "厥筐元纤缟。", "b": "《书·禹贡》。郑注:“细也。”"}, {"t": "纤縠蛾飞。", "b": "傅毅《舞赋》。注:“细縠也。”"}, {"t": "杂纤罗。", "b": "司马相如《子虚赋》"}, {"t": "善无微而不赏,恶无纤而不贬。", "b": "《三国志·诸葛亮传》"}, {"t": "母子慈爱,始终无纤介之间。", "b": "《汉书·马皇后纪》。注:“纤介,犹微细也。”"}, {"t": "纤谷蛾飞可爱,浮腾雀跃仙踪。", "b": "《隋唐演义》"}], "words": [{"w": "纤毫芥蒂", "t": "细小的隔阂或不快"}, {"w": "纤忽", "t": "极细小"}, {"w": "纤刀", "t": "细小的刀子"}, {"w": "纤腰", "t": "细小的腰。形容美人的腰。"}]}, {"meaning": "吝啬,花钱小气。", "cites": [{"t": "周人既纤,而师史尤甚。", "b": "《史记》"}], "words": [{"w": "纤啬", "t": "悭吝,琐屑,指斤斤计较。"}]}, {"meaning": "脆弱,小巧。", "cites": [{"t": "妩媚纤弱。", "b": "司马相如《上林赋》。注:“纤弱,谓容体细柔弱也。”"}], "words": [{"w": "纤人", "t": "体质孱弱的人;品格低下的人,指小人"}, {"w": "纤指", "t": "女子柔细的手指。同纤手。"}]}, {"meaning": "衣薄的样子。"}, {"meaning": "祭服的颜色,黑经白纬曰纤。", "cites": [{"t": "已下,服大红十五日,小红十四日,纤七日,释服。", "b": "《史记》"}]}, {"meaning": "细纹丝帛。", "cites": [{"t": "被文服纤,丽而不奇些。", "b": "《楚辞》"}], "words": [{"w": "纤华", "t": "指细巧精美的衣服或物品"}, {"w": "纤罗", "t": "细薄透气的丝织品。"}]}, {"meaning": "纤维。", "cites": [{"t": "缕积于纤,纶成若屈。", "b": "《蜘蛛赋》"}], "words": [{"w": "化纤", "t": "化学纤维的简称。"}]}, {"meaning": "古代计量单位。"}, {"meaning": "一寸或一两的千万分之一。"}, {"meaning": "记时单位。", "cites": [{"t": "太阳一日平行五十九分八秒一十九微四十九纤三十六芒,最高一年行四十五秒。", "b": "《畴人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('592wx','驯','1','xùn','马','6','','[{"pinyin": "xùn", "defs": [{"meaning": "(形声。从马,川声。本义:马驯服)。"}, {"meaning": "同本义。亦指鸟兽驯服。", "cites": [{"t": "驯,马训也。", "b": "《说文》"}, {"t": "养野鸟兽使服谓之训。", "b": "《一切经音义》引《说文》"}, {"t": "驯,性行调顺也。", "b": "《字林》"}, {"t": "乃驾驯駮之驷。", "b": "《史记·司马相如传》"}, {"t": "南越献驯象。", "b": "《汉书·武帝纪》"}, {"t": "马先驯而后求良。", "b": "《淮南子》"}, {"t": "江鱼不池活,野鸟难笼驯。", "b": "唐·韩愈《送惠师》"}], "words": [{"w": "驯兽", "t": "驯服之兽"}, {"w": "驯雉", "t": "驯顺的雉"}, {"w": "驯禽", "t": "驯养的禽鸟"}, {"w": "驯鹿", "t": "驯养的鹿"}, {"w": "驯乌", "t": "驯顺的乌鸦"}, {"w": "驯象", "t": "驯养的象。"}]}, {"meaning": "泛指顺服。", "cites": [{"t": "能明驯德。", "b": "《史记·五帝纪》"}, {"t": "驯至其道。", "b": "《易·坤》"}, {"t": "驯行孝谨。", "b": "《史记·万石君传》"}, {"t": "山人有二鹤,甚驯而善飞。", "b": "宋·苏轼《放鹤亭记》"}], "words": [{"w": "驯良;驯顺", "t": "驯服和顺"}, {"w": "驯狎", "t": "驯顺可亲近"}, {"w": "驯懦", "t": "驯服懦弱"}, {"w": "驯警", "t": "驯顺而有警觉"}, {"w": "驯粗", "t": "驯服而有野性。"}]}, {"meaning": "熟悉。", "cites": [{"t": "汉儿刍秣久,相驯通语言。", "b": "清·施闰章《新都戍》"}], "words": [{"w": "驯悉", "t": "熟悉。"}]}, {"meaning": "善良。", "cites": [{"t": "知恶政之不可久,则虽苛烦之法,自可调之使驯。", "b": "清·王夫之《宋论》"}], "words": [{"w": "驯谨", "t": "善良谨慎"}, {"w": "驯行", "t": "善良的行为。"}]}, {"meaning": "使驯服;使和顺。", "cites": [{"t": "龙驹之子,方乃驯驾,所以此国多出善马。", "b": "唐·玄奘《大唐西域记》"}], "words": [{"w": "驯驾", "t": "训练驾车"}, {"w": "驯兽", "t": "使兽驯顺。"}]}, {"meaning": "解释。", "cites": [{"t": "又以先王之书,驯天明不解之道也知之。", "b": "《墨子》"}]}, {"meaning": "逐渐地,循序渐进。", "cites": [{"t": "学不陵节而施之曰驯。", "b": "《说苑》"}], "words": [{"w": "驯致", "t": "顺其自然而逐渐达到;顺应情致的自然发展"}, {"w": "驯增", "t": "逐渐增加。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('593wx','约','1','yuē yāo','纟','6','','[{"pinyin": "yuē", "defs": [{"meaning": "(形声。从糸(mì),勺声。糸是细丝,有缠束作用。本义:绳索)。"}, {"meaning": "同本义。", "cites": [{"t": "人寻约。", "b": "《左传》注"}], "words": [{"w": "寻约", "t": "八尺长的绳子。"}]}, {"meaning": "盟约;相期的诺言。", "cites": [{"t": "负约不偿城。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "约酬", "t": "契约,文券。"}]}, {"meaning": "缠束;环束。", "cites": [{"t": "约之阁阁。", "b": "《诗·小雅·斯干》"}, {"t": "约,缠束也。", "b": "《说文》"}, {"t": "凡任索约。", "b": "《考工记·匠人》。注:“缩也。”"}, {"t": "约绥约辔。", "b": "《仪礼·既夕礼》"}, {"t": "约车治装。", "b": "《战国策·齐策四》"}, {"t": "约车骑百乘。", "b": "《史记·魏公子列传》"}, {"t": "银蒜又垂碧户中,樱桃花下约帘拢。", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "约指", "t": "环束于指"}, {"w": "约臂", "t": "戴在手臂上的环形装饰品。"}]}, {"meaning": "约定,以语言或文字订立共同应遵守的条件。", "cites": [{"t": "约为婚姻。", "b": "《史记·项羽本纪》"}, {"t": "与诸将约曰。", "b": ""}, {"t": "不敢稍逾约。", "b": "明·宋濂《送东阳马生序》"}, {"t": "必如约。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "相约", "t": "相互约定"}, {"w": "预约", "t": "预先约定"}, {"w": "约分鸿沟", "t": "楚汉相争,双方曾约定以鸿沟为界,平分天下"}, {"w": "约信", "t": "用言辞订立相互信守之约定。"}]}, {"meaning": "邀请。", "cites": [{"t": "约与食客门下有勇力文武备具者二十人偕。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "约交", "t": "缔交"}, {"w": "约结", "t": "结交;邀结"}, {"w": "约从", "t": "邀约合纵。"}]}, {"meaning": "束缚,约束。", "cites": [{"t": "言语之约束也。", "b": "《周礼·司约》注"}, {"t": "约我以礼。", "b": "《论语》"}], "words": [{"w": "约己", "t": "约束自己"}, {"w": "约身", "t": "约束自身"}, {"w": "约礼", "t": "用礼约束自己。"}]}, {"meaning": "少;省减;简约 ——《史记·屈原贾生列传》。", "cites": [{"t": "待人也轻以约。", "b": "唐·韩愈《原毁》"}, {"t": "以约失之者鲜矣。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "约薄", "t": "刻薄"}, {"w": "约省", "t": "减省;简约"}, {"w": "约损", "t": "减省;俭约"}, {"w": "约节", "t": "简约;节俭"}, {"w": "约俭", "t": "简约省俭。"}]}, {"meaning": "估量。", "cites": [{"t": "长约八分有奇。", "b": "明·魏学洢《核舟记》"}, {"t": "约烧房铺数百间。", "b": "《广东军务记》"}], "words": [{"w": "约末", "t": "约莫"}, {"w": "约料", "t": "估计;料想"}, {"w": "约度", "t": "估计;衡量"}, {"w": "约谅", "t": "料想;忖度。"}]}, {"meaning": "简要。", "cites": [{"t": "读书一事,要由博而返之约,总以心得为主。", "b": "《儒林外史》"}, {"t": "博而不杂,约而不漏。", "b": "《文史通义》"}], "words": [{"w": "约简", "t": "俭约简易"}, {"w": "约艳", "t": "简洁华丽。"}]}, {"meaning": "姓。"}]}, {"pinyin": "yāo", "defs": [{"meaning": "", "words": [{"w": "给我约二斤肉", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('594wx','级','1','jí','纟','6','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,及声。本义:丝的次第)。"}, {"meaning": "同本义。", "cites": [{"t": "级,丝次弟也。", "b": "《说文》。段玉裁注:“本谓丝之次弟,故其字从系。引申为凡次弟之称。”"}]}, {"meaning": "引申为等级,特指官阶爵位的品级。", "cites": [{"t": "级,等也。", "b": "《广雅》"}, {"t": "拾级聚足。", "b": "《礼记·曲礼》。注:“等也。”"}, {"t": "级,阶次也。", "b": "《声类》"}, {"t": "以别贵贱等级之度。", "b": "《礼记·月令》"}, {"t": "百姓内粟千石,拜爵一级。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "超级", "t": "超过一般等级的"}, {"w": "震级", "t": "地震等级"}, {"w": "晋级", "t": "升到较高的等级"}, {"w": "级差", "t": "等级之间的差距。"}]}, {"meaning": "石阶。", "cites": [{"t": "乃领宾者延之而上,分级而立。", "b": "《吕氏春秋》"}, {"t": "澄源寻视其侧,得级。", "b": "《徐霞客游记·游黄山记》"}, {"t": "其级七千有余。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "石级", "t": ""}]}, {"meaning": "秦制,战争中斩敌首一,赐爵一级,称为首级。后以“级”为所斩之首的量词。", "cites": [{"t": "凡斩首七千六百级。", "b": "《汉书·赵充国传》"}], "words": [{"w": "斩级万余", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('595wx','纪','1','jǐ jì','纟','6','','[{"pinyin": "jǐ", "defs": [{"meaning": "姓。"}]}, {"pinyin": "jì", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,己声。本义:散丝的头绪)。"}, {"meaning": "同本义。", "cites": [{"t": "纪,别丝也。", "b": "《说文》"}, {"t": "三纲六纪。纪者,理也。", "b": "《白虎通》"}, {"t": "众之纪也。", "b": "《礼记·礼器》。注:“丝缕之数有纪。”"}, {"t": "譬若丝缕之有纪,网罟之有纲。", "b": "《墨子·尚同上》"}, {"t": "茧之性为丝,然非得工女煮以热汤而抽其统纪,则不能成丝。", "b": "《淮南子·泰族训》"}]}, {"meaning": "开端,头绪。", "cites": [{"t": "纪,绪也。", "b": "《方言十》"}], "words": [{"w": "乱其纪", "t": "事情乱了端绪。"}]}, {"meaning": "要领。", "cites": [{"t": "义也者,万事之纪也。", "b": "《吕氏春秋》"}, {"t": "故乐者,天地之命,中和之纪,人情之所不能免也。", "b": "《礼记·乐记》"}]}, {"meaning": "纲领;纲纪。", "cites": [{"t": "纲纪四方。", "b": "《诗·大雅·棫朴》"}, {"t": "道者,万物之始,是非之纪也。", "b": "《韩非子·主道》"}], "words": [{"w": "纪经", "t": "纲常"}, {"w": "纪纲", "t": "网罟的纲绳。引申为法纪与政纲;治理;管理"}, {"w": "纪序", "t": "纲纪次序。"}]}, {"meaning": "法则;准则。", "cites": [{"t": "无变天之道,无绝地之理,无乱人之纪。", "b": "《吕氏春秋·孟春》"}], "words": [{"w": "纪法", "t": "法律;法规。"}]}, {"meaning": "十二年的一个时期。", "cites": [{"t": "如何四纪为天子,不及卢家有莫愁。", "b": "李商隐《马嵬》"}]}, {"meaning": "中国古国名 。姜姓,春秋时为齐所灭,故城在今山东省寿光县东南。"}, {"meaning": "处理;治理。", "cites": [{"t": "纪农协功。", "b": "《国语·周语上》"}, {"t": "衣食当须纪,力耕不吾欺。", "b": "陶潜《移居》"}], "words": [{"w": "纪理", "t": "经纪,管理"}, {"w": "纪农", "t": "治理农事。"}]}, {"meaning": "记录,记载。", "cites": [{"t": "夫德,俭而有度,登降有数,文、物以纪之,声、明以发之,以临照百官。", "b": "《左传·恒公二年》"}, {"t": "司马子长纪黄帝以至孝武。", "b": "《论衡·须颂》"}, {"t": "咸用纪宗存主。", "b": "张衡《东京赋》"}, {"t": "恶能无纪。", "b": "明·袁宏道《满井游记》"}, {"t": "罗缕纪存。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "纪兴", "t": "记录兴致"}, {"w": "纪功", "t": "记载功绩"}, {"w": "纪述", "t": "记载叙述。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('596wx','驰','1','chí','马','6','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从马,也声。本义:车马疾行)。"}, {"meaning": "同本义。", "cites": [{"t": "驰,大驱也。", "b": "《说文》"}, {"t": "弗驰弗驱。", "b": "《诗·唐风·山有枢》"}, {"t": "车驰卒奔。", "b": "《左传·宣公十二年》"}, {"t": "好驰马试剑。", "b": "《孟子·滕文公上》"}, {"t": "啬夫驰。", "b": "《左传·昭公十七年》"}, {"t": "项伯乃夜驰之沛公军。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又驱使。", "cites": [{"t": "公诚能驰一介之使,加咫尺之书,则孝章可致,友道可弘矣。", "b": "汉·孔融《论盛孝章书》"}], "words": [{"w": "驰车", "t": "古代战场上快速奔走的马车、轻车;驾车行走"}, {"w": "驰马", "t": "骑马快跑"}, {"w": "驰道", "t": "为帝王行驶马车所筑的马路"}, {"w": "驰报", "t": "疾驰传报"}, {"w": "驰夫", "t": "骑马送信的差役。"}]}, {"meaning": "疾行。", "cites": [{"t": "每冒风驰行,未百步辄反。", "b": "明·袁宏道《满井游记》"}, {"t": "山舞银蛇,原驰蜡象。", "b": "毛泽东《沁园春·雪》"}], "words": [{"w": "风驰电掣;驰说", "t": "往来劝说"}, {"w": "驰求", "t": "奔走追求"}, {"w": "驰兵", "t": "迅速进兵。"}]}, {"meaning": "追逐。", "cites": [{"t": "齐师败绩,公将驰之。", "b": "《左传·庄公十年》"}], "words": [{"w": "驰竞", "t": "追逐,竞争。"}]}, {"meaning": "向往。", "cites": [{"t": "抑志而弥节兮,神高驰之邈邈。", "b": "《楚辞·离骚》"}, {"t": "身在边隅,情驰魏阙。", "b": "《隋书·史祥传》"}], "words": [{"w": "驰结", "t": "挂念,想念"}, {"w": "驰义", "t": "向往忠义而奔驰来归;归义,臣服。"}]}, {"meaning": "消逝迅速。", "cites": [{"t": "年与时驰,意与日去。", "b": "诸葛亮《诫子书》"}], "words": [{"w": "驰年", "t": "快速流逝的岁月"}, {"w": "驰晖", "t": "疾驰的日光。"}]}, {"meaning": "传播。", "cites": [{"t": "名驰三江外,峻节贯云霄。", "b": "李白《赠从孙义与宰铭》"}, {"t": "驰东皋之素谒。", "b": "《北山移文》。注:“犹宣布也。”"}], "words": [{"w": "驰芳", "t": "散播芳香"}, {"w": "驰声", "t": "声誉远播。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('597wx','纫','1','rèn','纟','6','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从糸,刃声。本义:搓绳)。"}, {"meaning": "同本义。", "cites": [{"t": "纫,禅绳也。", "b": "《说文》。朱骏声曰:“凡单展曰纫,合绳曰纠, 织绳曰辫。”"}, {"t": "纫针请补缀。", "b": "《礼记·内则》"}, {"t": "纫秋兰以为佩,岂惟纫夫蕙茝。", "b": "《离骚》"}, {"t": "并纫茅,丝以为索。", "b": "《楚辞·惜誓》"}], "words": [{"w": "纫佩", "t": "捻缀秋兰,佩带在身。"}]}, {"meaning": "缝纫; 缝补。", "cites": [{"t": "公受珠,内所著披袄中,纫之。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "纫缉", "t": "联缀修补"}, {"w": "纫缝", "t": "缝纫"}, {"w": "纫捺", "t": "缝制。"}]}, {"meaning": "穿。", "cites": [{"t": "今亦以线贯针为纫。", "b": "《方言》注"}], "words": [{"w": "纫针", "t": "以线穿针。引申为缝制衣服。"}]}, {"meaning": "连缀,联结。", "cites": [{"t": "腰纫双佩。", "b": "《北史》"}]}, {"meaning": "按摩。", "cites": [{"t": "裸体纫胸称疾。", "b": "《管子·霸形》"}], "words": [{"w": "纫佩", "t": "对别人的德泽和教益铭感于心,如纫佩在身。多用于书信。"}]}, {"meaning": "柔软而结实的", "cites": [{"t": "蒲苇纫如丝。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "纫如丝", "t": "如同丝那样柔软结实。"}]}, {"meaning": "绳索,绳子。", "cites": [{"t": "先作麻纫,缠十许匝。", "b": "《齐民要术》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('598wx','巡','1','xún','巛','6','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从辵(chuò),川声。本义:到各地视察;巡行)。"}, {"meaning": "同本义。", "cites": [{"t": "巡,视行也。", "b": "《说文》"}, {"t": "五载一巡守。", "b": "《虞书》。郑注:“行视所守也。殷制六年一巡守,周制十二年一巡守。”"}, {"t": "巡守者,巡所守也。", "b": "《孟子》"}, {"t": "昼三巡之。", "b": "《周礼·掌固》"}, {"t": "巡问而观察之。", "b": "《周礼·司谏》"}, {"t": "仆人巡宫。", "b": "《左传·襄公三十一年》"}, {"t": "巡丈城。", "b": "《左传·襄公九年》"}, {"t": "宾客则巡其道脩。", "b": "《周礼·遂师》"}, {"t": "师兄,我去巡山,你莫成跟我去听的?", "b": "《西游记》"}, {"t": "臣从君还轸,巡于天下,怨其多矣。", "b": "《国语》"}], "words": [{"w": "巡风料哨", "t": "巡哨;望风"}, {"w": "巡梭", "t": "巡逻;巡察"}, {"w": "巡环", "t": "来回观察了望"}, {"w": "巡幸", "t": "巡守。帝王出外巡视"}, {"w": "巡兵", "t": "巡罗兵士"}, {"w": "巡捕", "t": "巡查搜捕。"}]}, {"meaning": "审视;细看。", "cites": [{"t": "君巡牲。", "b": "《礼记·祭义》"}, {"t": "臣检少例;巡今逾疑。", "b": "南朝梁·江淹《萧被侍中敦传表》"}]}, {"meaning": "抚慰。", "cites": [{"t": "巡靖黎蒸。", "b": "《后汉书》"}], "words": [{"w": "巡靖", "t": "安抚。"}]}, {"meaning": "同时对一组的每个人各敬一杯酒。", "cites": [{"t": "陆秀宝上前筛了一巡酒。", "b": "《海上花列传》"}], "words": [{"w": "酒过三巡", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('599wx','寿','1','shòu','寸','7','','[{"pinyin": "shòu", "defs": [{"meaning": "(形声。从老省,畴声(依《说文》),从老省,即上面象“老”的上半部。本义:长寿) 同本义。", "cites": [{"t": "寿,久也。", "b": "《说文》"}, {"t": "寿命也。", "b": "《韩非子·显学》"}, {"t": "观其形骨,必不寿,不可与婚。", "b": "《世说新语·贤媛》"}, {"t": "死而不忘者寿。", "b": "《老子》"}, {"t": "则无遗寿耈。", "b": "《书·召诰》"}, {"t": "如南山之寿。", "b": "《诗·小雅·天保》"}, {"t": "长于上古,而不为寿。", "b": "《庄子·天道》。注:“寿者,期之远耳。”"}, {"t": "病变而药不变,向之寿民,今为殇子矣。", "b": "《吕氏春秋·察今》"}, {"t": "神龟虽寿,犹有竟时。", "b": "曹操《步出夏门行》"}, {"t": "斯役之价值,直可惊天地,泣鬼神,与武昌革命之役并寿。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "寿翁", "t": "年高长寿的老人;泛指祝寿者"}, {"w": "寿人", "t": "年高的人"}, {"w": "寿岂", "t": "长寿而快乐"}, {"w": "寿域", "t": "长寿的境域;比喻太平盛世"}, {"w": "寿发", "t": "老年人头发脱落后又生的头发"}, {"w": "寿夭有定", "t": "迷信认为,人的生命长短都是命里注定的。"}]}, {"meaning": "年寿,寿限。", "cites": [{"t": "上寿百二十,中寿百年,下寿八十。", "b": "《文选诗》注引《养生经》"}, {"t": "登昆仑兮食玉英,与天地兮比寿,与日月兮争光。", "b": "《楚辞·涉江》"}, {"t": "以终其寿。", "b": "《吕氏春秋·尊师》。注:“年也。”"}, {"t": "造恶的享富贵又寿延。", "b": "关汉卿《窦娥冤》"}]}, {"meaning": "祝寿;祝福。多指奉酒祝人长寿。", "cites": [{"t": "若入前为寿,寿毕,请以剑舞。", "b": "《史记·项羽本纪》"}, {"t": "昨闻海令为母寿,市肉二斤矣。", "b": "《明史·海瑞传》"}], "words": [{"w": "寿宫", "t": "供奉神位的地方;宫中寝室"}, {"w": "寿屏", "t": "以祝寿的文字书写而成的屏条"}, {"w": "寿诗", "t": "祝寿的诗"}, {"w": "寿文,寿序", "t": "祝寿的文辞"}, {"w": "寿宴", "t": "祝寿的宴会。"}]}, {"meaning": "向人献物以祝人长寿。", "cites": [{"t": "请以赵十五城为秦王寿。", "b": "《史记·项羽本纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('600wx','弄','1','nòng lòng','廾','7','','[{"pinyin": "nòng", "defs": [{"meaning": "(会意。上为“玉”,下为“廾”(即廾,gǒng)。指双手玩赏玉器。本义:用手把玩;玩弄)。"}, {"meaning": "同本义。", "cites": [{"t": "弄,玩也。", "b": "《说文》"}, {"t": "载弄之璋,载弄之瓦。", "b": "《诗·小雅·斯干》"}, {"t": "高祖持御史大夫印,弄之。", "b": "《汉书·周昌赵尧传》"}, {"t": "得鹊子还下弄;神气自若,傍若无人。", "b": "《世说新语·简傲》"}], "words": [{"w": "弄丸", "t": "古技巧名称。手持多丸,逐一抛出,再次第接住,如此循环不已"}, {"w": "玩枪弄棒", "t": "弄兵。使枪弄棒之类"}, {"w": "弄笔", "t": "舞文弄墨"}, {"w": "弄毫墨", "t": "舞弄笔墨"}, {"w": "弄舌", "t": "弄口。掉弄口舌;饶舌"}, {"w": "弄孙", "t": "逗玩孙儿。"}]}, {"meaning": "戏耍;游戏。", "cites": [{"t": "夷吾弱不好弄。", "b": "《左传·僖公九年》"}, {"t": "郎骑竹马来,绕床弄青梅。(床:井上栏杆。)", "b": "李白《长干行》"}], "words": [{"w": "弄嘴", "t": "耍嘴皮子,花言巧语"}, {"w": "弄刺子儿", "t": "耍花招,干坏事"}, {"w": "弄儿", "t": "花样;把戏"}, {"w": "弄法", "t": "耍弄法术"}, {"w": "弄虚头", "t": "耍花样"}, {"w": "弄喧", "t": "弄玄虚,耍花招"}, {"w": "弄空头", "t": "弄虚作假,耍花样"}, {"w": "弄白相", "t": "戏弄,开玩笑"}, {"w": "弄辞", "t": "戏谑之辞"}, {"w": "弄送", "t": "作弄;戏弄。"}]}, {"meaning": "作弄;期侮。", "cites": [{"t": "愚弄其民。", "b": "《左传·襄公四年》"}, {"t": "我和你干大事,如何肯弄你。", "b": "《水浒传》"}]}, {"meaning": "演奏乐器。", "cites": [{"t": "踞胡床,为作三调,弄毕,便上车去。", "b": "《世说新语》"}]}, {"meaning": "玩赏。", "cites": [{"t": "乘舟弄月宿泾溪。", "b": "李白《别山僧》"}], "words": [{"w": "弄月", "t": "赏月"}, {"w": "弄花", "t": "赏花"}, {"w": "弄月吟风", "t": "赏玩、吟咏风月美景。"}]}, {"meaning": "做;搞。", "cites": [{"t": "天天晚上弄到四更多才睡。", "b": "《红楼梦》"}], "words": [{"w": "弄性尚气", "t": "任性而为,意气用事"}, {"w": "弄硶儿", "t": "偷干坏事"}, {"w": "弄水", "t": "在水上作竞技表演"}, {"w": "弄文", "t": "指写文章"}, {"w": "弄巧", "t": "谓做出各种巧妙的花样"}, {"w": "弄姿", "t": "谓做出种种姿态"}, {"w": "把屋子弄一下;你来不了,我替你弄吧", "t": ""}]}, {"meaning": "妆饰。", "cites": [{"t": "弄姿帷房之里。", "b": "《文选·赵至·与嵇茂齐书》"}], "words": [{"w": "弄姿", "t": "妆饰容貌"}, {"w": "弄妆", "t": "妆饰,打扮"}, {"w": "弄碜儿", "t": "指做丑事。"}]}, {"meaning": "设法争得。", "cites": [{"t": "齐心打伙弄几个钱。", "b": "《红楼梦》"}], "words": [{"w": "弄钱;弄点吃的来", "t": ""}]}, {"meaning": "乐曲。", "cites": [{"t": "帝命[桓]伊吹笛,伊神气无忤,既吹一弄,乃放笛云。", "b": "《世说新语·任诞》刘注引《续晋阳秋》"}, {"t": "时奏狡弄,则彷徨翱翔。", "b": "《文选·王褒·洞箫赋》"}]}, {"meaning": "巷中巷。", "cites": [{"t": "及帝出,各欲自奋,帝竟无一言,出西弄,遇弑,年二十二。", "b": "《南史·齐废帝郁林王纪》"}]}]}, {"pinyin": "lòng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('601wx','麦','1','mài','麦','7','','[{"pinyin": "mài", "defs": [{"meaning": "(形声。甲骨文字形。从攵(zhí),来声。“麦”是汉字的一个部首。本义:麦子)。"}, {"meaning": "同本义 。一年生或二年生草本植物,有小麦、大麦、燕麦、黑麦等。子实主要作粮食或作精饲料、酿酒、制饴糖。秆可作编织或造纸原料。", "cites": [{"t": "麦,芒谷。", "b": "《说文》"}, {"t": "爰采麦矣。", "b": "《诗·鄘风·桑中》"}, {"t": "芃芃其麦。", "b": "《诗·鄘风·载驰》"}, {"t": "野有麦场。", "b": "《聊斋志异·狼三则》"}, {"t": "麦田浅鬣。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "麦棱头", "t": "麦田的田畦"}, {"w": "麦人", "t": "麦心,麦核。即麦仁"}, {"w": "麦天", "t": "农历四月前后麦子将熟的天气"}, {"w": "麦舟", "t": "运麦的船。麦舟之赠,用为助丧的典故,本范仲淹父子的故事"}, {"w": "麦序", "t": "指农历四月麦子成熟的季节"}, {"w": "麦李", "t": "麦子成熟时节所出产的李子"}, {"w": "麦秀", "t": "麦子开花。多用麦秀表怀古情意"}, {"w": "麦雨", "t": "收麦时节所下的雨"}, {"w": "麦花", "t": "麦子的花"}, {"w": "麦酒", "t": "用大麦酿造的酒"}, {"w": "麦气", "t": "麦成熟时散发出来的香气"}, {"w": "麦候", "t": "指农历四月麦熟的时节"}, {"w": "麦饭豆羹", "t": "指农家的粗菜便饭"}, {"w": "麦穗两岐", "t": "一麦长出双穗。为丰年的征兆。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('602wx','玖','1','jiǔ','王','7','','[{"pinyin": "jiǔ", "defs": [{"meaning": "(形声。从玉,久声。本义:似玉的黑色美石)。"}, {"meaning": "同本义。", "cites": [{"t": "玖,石之次玉,黑色。", "b": "《说文》"}, {"t": "报之以琼玖。", "b": "《诗·卫风·木瓜》"}, {"t": "贻我佩玖。", "b": "《诗·王风·邱中有麻》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('603wx','玛','1','mǎ','王','7','','[{"pinyin": "mǎ", "defs": [{"meaning": "矿物，成分主要是二氧化硅，有多种颜色，质地坚硬，耐磨，可做研磨用具、仪表轴承或装饰品，亦可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('604wx','形','1','xíng','彡','7','','[{"pinyin": "xíng", "defs": [{"meaning": "同本义。", "cites": [{"t": "形,象形也。", "b": "《说文》"}, {"t": "物成生理谓之形。", "b": "《庄子·天地》"}, {"t": "雷雨之动满形。", "b": "《易·屯》"}, {"t": "在天成象,在地成形。", "b": "《礼记·乐记》"}, {"t": "形色天性也。", "b": "《孟子》"}, {"t": "形者,生之具也。", "b": "《史记·太史公自序》"}, {"t": "良马可形容筋骨相也。", "b": "《列子·说符》"}, {"t": "形似酒尊。", "b": "《后汉书·张衡传》"}, {"t": "鸟兽之形。", "b": ""}, {"t": "形若土狗。", "b": "《聊斋志异·促织》"}, {"t": "因势象形。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "形物", "t": "有形之物"}, {"w": "条形;线形;方形;圆形;球形;梯形;三角形;正方形;多角形;多边形;口形;体形", "t": ""}]}, {"meaning": "形体,实体。", "cites": [{"t": "可以隐形。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "无案牍之劳形。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "山岳潜形。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "钩勒形廓。", "b": "蔡元培《图画》"}], "words": [{"w": "形寂", "t": "死亡"}, {"w": "形响", "t": "形体和声响"}, {"w": "形解", "t": "形体超脱现实;道教指尸解"}, {"w": "有形;无形;整形;形生", "t": "身体与性命"}, {"w": "形性", "t": "形体和性质"}, {"w": "形训", "t": "用文字形体的分析来释字义。"}]}, {"meaning": "容色,容貌。", "cites": [{"t": "望远者,察其貌,而不察其形。", "b": "《谷梁传》"}], "words": [{"w": "形藏", "t": "模样、身分"}, {"w": "形质", "t": "容貌与性情"}, {"w": "形秽", "t": "容貌不洁。"}]}, {"meaning": "各种自然环境或地表的自然特征。", "cites": [{"t": "秦,形胜之国。", "b": "《史记》"}], "words": [{"w": "形便", "t": "地形有利"}, {"w": "形要", "t": "形势险要"}, {"w": "形局", "t": "地理格局。"}]}, {"meaning": "情势,形势。", "cites": [{"t": "由此言之,勇怯,势也;强弱,形也。", "b": "司马迁《报任安书》"}, {"t": "仆未之得验,然其形必然。", "b": "汉·贾谊《铸钱》"}, {"t": "不能者之形。", "b": "《孟子·梁惠王上》"}, {"t": "鼎足之形。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "形服", "t": "迫于形势而屈服"}, {"w": "形宜", "t": "按照形势所应注意之事。"}]}, {"meaning": "模型。", "cites": [{"t": "冰炭不合形。", "b": "《韩非子·用人》"}, {"t": "仪形虞、周之盛。", "b": "《汉书·王莽传上》"}, {"t": "仪形文王,万邦作孚。", "b": "《潜夫论·德化》"}]}, {"meaning": "画图形。", "cites": [{"t": "乃审厥象,俾以形旁求于天下。", "b": "《书·说命》"}], "words": [{"w": "形摹", "t": "描摹。"}]}, {"meaning": "使之现形,显露,显示。", "cites": [{"t": "形,见也。", "b": "《广雅》"}, {"t": "然后心术形焉。", "b": "《礼记·乐记》。注:“犹见也。”"}, {"t": "形人而我无形,则我专而敌分。", "b": "《孙子·虚实》"}, {"t": "赵王不悦,形于颜色。", "b": "《战国策·赵策三》"}, {"t": "归而形诸梦。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "形藏", "t": "秘密;隐私"}, {"w": "情动于中而形于言;形见", "t": "显现;显形"}, {"w": "形言", "t": "表现在言辞上。"}]}, {"meaning": "比较,对照。", "cites": [{"t": "令狐綯大怒,说他以己之长,形人之短,文人无行。", "b": "《西湖二集》"}], "words": [{"w": "相形见绌", "t": ""}]}, {"meaning": "描绘。", "cites": [{"t": "虽有心略辞给,固未能缕形其所由然也。", "b": "汉·枚乘《七发》"}]}, {"meaning": "形成,成为某种形象。", "cites": [{"t": "上下未形,何由考之?", "b": "《楚辞·天问》"}, {"t": "惟有道者,能备患于未形也,故祸不萌。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('605wx','进','1','jìn','辶','7','','[{"pinyin": "jìn", "defs": [{"meaning": "(会意。甲骨文字形,上面是“隹”,象小鸟形,下面是“止”(趾)。鸟脚只能前进不能后退,故用以表示前进。本义:前进,与“退”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "进,登也。", "b": "《说文》"}, {"t": "巽为进退。", "b": "《易·说卦》"}, {"t": "进退维谷。", "b": "《诗·大雅·桑葇》"}, {"t": "徒衔枚而进。", "b": "《周礼·大司马》"}, {"t": "君子三揖而进。", "b": "《礼记·表记》"}, {"t": "进则引之,退则策之。", "b": "《韩非子·外储说右下》"}, {"t": "进兵击秦军。", "b": "《史记·魏公子列传》"}, {"t": "以次俱进。", "b": "《资治通鉴》"}, {"t": "水陆并进。", "b": ""}, {"t": "贼环而进。", "b": "明·魏禧《大铁椎传》"}, {"t": "猱进鸷击。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "迈进", "t": "大踏步地前进"}, {"w": "奋进", "t": "奋勇前进"}, {"w": "进不来出不去", "t": "比喻进退两难或处境尴尬"}, {"w": "进旅退旅", "t": "进退一致,整齐合一"}, {"w": "进退中绳", "t": "举动合乎规矩。"}]}, {"meaning": "超过。", "cites": [{"t": "臣之所好者,道也,进乎技矣。", "b": "《庄子·养生主》"}]}, {"meaning": "入,走入。", "cites": [{"t": "府尹叫进后堂来说。", "b": "《水浒全传》"}], "words": [{"w": "进门;进口;进屋;进洣", "t": "上学"}, {"w": "进了学", "t": "上学读书"}, {"w": "进镇", "t": "进驻镇守"}, {"w": "进壁", "t": "进驻并筑工事固守"}, {"w": "进营", "t": "进驻。"}]}, {"meaning": "奉献。", "cites": [{"t": "群臣进谏。", "b": "《战国策·齐策》"}, {"t": "进尽忠言。", "b": "诸葛亮《出师表》"}, {"t": "煮芋以进。", "b": "清·周容《芋老人传》"}, {"t": "再进。", "b": ""}, {"t": "厨者进芋。", "b": ""}, {"t": "以一头进。", "b": "《聊斋志异·促织》"}], "words": [{"w": "进草", "t": "遇有紧急事情在处理完毕后给皇帝的奏章"}, {"w": "进鲜", "t": "向皇帝或长辈或上司进献时鲜食物"}, {"w": "进上", "t": "进贡给皇帝"}, {"w": "进御", "t": "将东西奉献给皇帝。"}]}, {"meaning": "任官;出仕。", "cites": [{"t": "升诸司马曰进士。", "b": "《礼记·王制》"}, {"t": "而进之。", "b": "《吕氏春秋·慎行论》"}, {"t": "进亦忧。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "进导", "t": "引导进入仕途。"}]}, {"meaning": "推荐。", "cites": [{"t": "于是忌进孙子于威王。", "b": "《史记·孙子吴起列传》"}, {"t": "贵则观其所进。", "b": "《吕氏春秋·论人》"}, {"t": "父张孟常为颍阴侯灌婴舍人,得幸,因进之。", "b": "《汉书·灌夫传》"}], "words": [{"w": "进举", "t": "荐举;推荐"}, {"w": "进荐", "t": "推荐"}, {"w": "进贤兴功", "t": "荐举贤士功臣"}, {"w": "进贤任能", "t": "进荐任用贤能之士。"}]}, {"meaning": "登。", "cites": [{"t": "君子三揖而进。", "b": "《国语》"}]}, {"meaning": "促进,增强。", "cites": [{"t": "进本退末。", "b": "《盐铁论·本议》"}, {"t": "礼减而进。", "b": "《礼记·乐记》"}], "words": [{"w": "进躁", "t": "急于进取"}, {"w": "进趋", "t": "努力向上"}, {"w": "进锐退速", "t": "急于求进者往往后退亦快"}, {"w": "进致", "t": "进取"}, {"w": "进事", "t": "发展事业。"}]}, {"meaning": "推崇,赞扬。", "cites": [{"t": "退之以知道自居,而于董、贾独抑之,相如独进之。", "b": "明·方孝儒《答王秀才书》"}]}, {"meaning": "终止;竭尽。", "cites": [{"t": "终进乎?不知也。道终乎本无始,进乎本不久。", "b": "《列子·天瑞》"}, {"t": "竭聪明,进智力。", "b": "《列子·黄帝》"}]}, {"meaning": "钱财。", "cites": [{"t": "萧何主吏、主进。", "b": "《史记·高祖本纪》"}]}, {"meaning": "平房的一宅之内分前后几排的,一排称为一进。", "cites": [{"t": "右边一路,一间一间的房子,都有两进。", "b": "《儒林外史》"}]}, {"meaning": "层。", "cites": [{"t": "外墙砌宽一尺,石二进;内墙砌宽一尺,石一进。", "b": "清·严如煜《苗防备览》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('606wx','戒','1','jiè','戈','7','','[{"pinyin": "jiè", "defs": [{"meaning": "(会意。小篆字形,上面是“戈”,下面象两只手(即“廾”)。两手持戈,表示戒备森严。本义:警戒,戒备)。"}, {"meaning": "同本义。", "cites": [{"t": "戒,警也。", "b": "《说文》"}, {"t": "岂不日戒。", "b": "《诗·小雅·采薇》"}, {"t": "以三年之戒。", "b": "《礼记·曾子问》"}, {"t": "基浇能戒之。", "b": "《左传·哀公元年》"}, {"t": "息民不戒。", "b": "《国语·吴语》"}, {"t": "怵然为戒。", "b": "《庄子·养生主》"}, {"t": "戒之慎勿忘。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "知足以自戒。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "戒慎", "t": "戒备谨慎"}, {"w": "戒书", "t": "用来自我警戒的文字"}, {"w": "戒旦", "t": "警告天将破晓"}, {"w": "戒守", "t": "警戒守卫"}, {"w": "戒命", "t": "禁止某些行为的命令"}, {"w": "戒戢", "t": "警介禁止"}, {"w": "戒诗", "t": "自我警戒的诗。"}]}, {"meaning": "告诫。", "cites": [{"t": "主人戒宾。", "b": "《仪礼·士冠礼》"}, {"t": "三保戒团众。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "戒勉", "t": "告诫勉励"}, {"w": "戒约", "t": "告诫约束"}, {"w": "戒谕", "t": "告诫;训导"}, {"w": "戒朝", "t": "告诫无将明。"}]}, {"meaning": "预备;准备。", "cites": [{"t": "既种既戒。", "b": "《诗·小雅·大田》"}], "words": [{"w": "戒装", "t": "准备行装"}, {"w": "戒辖", "t": "准备车辆。"}]}, {"meaning": "戒除。", "cites": [{"t": "戒奢以俭。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "戒杀", "t": "戒除杀生"}, {"w": "戒脱", "t": "戒掉"}, {"w": "戒绝;戒诗", "t": "戒除做诗"}, {"w": "戒烟;戒酒", "t": ""}]}, {"meaning": "斋戒。", "cites": [{"t": "圣人以此斋戒。", "b": "《易·系辞》"}, {"t": "戒及宿之曰。", "b": "《周礼·太史》"}, {"t": "七曰戒。", "b": "《礼记·礼器》"}]}, {"meaning": "警戒之事。", "cites": [{"t": "君子有三戒。", "b": "《论语》"}]}, {"meaning": "界限,分界。", "cites": [{"t": "星茀于河戒。", "b": "《史记·天官书》"}, {"t": "江河为南北两戒。", "b": "《新唐书·天文志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('607wx','吞','1','tūn','口','7','','[{"pinyin": "tūn", "defs": [{"meaning": "(形声。从口,天声。本义:咽下)。"}, {"meaning": "同本义。", "cites": [{"t": "吞,咽也。", "b": "《说文》"}, {"t": "吞舟大鱼也。", "b": "《后汉书·杜笃传》注"}, {"t": "吞长江。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "与风水相吞吐。", "b": "宋·苏轼《石钟山记》"}, {"t": "气吞万里如虎。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "吞炭", "t": "吞咽火炭毁嗓子"}, {"w": "吞舌", "t": "闭口结舌不言"}, {"w": "吞舟", "t": "吞航。吞舟之鱼,能吞舟的大鱼"}, {"w": "吞刀刮肠", "t": "喻痛下决心,改过自新"}, {"w": "吞牛", "t": "比喻少年气概豪迈"}, {"w": "吞咀", "t": "吞食"}, {"w": "吞下一条鳝鱼", "t": ""}]}, {"meaning": "吞并,消灭掉。", "cites": [{"t": "吞,灭也。", "b": "《广雅》"}, {"t": "兼有吞周之意。", "b": "《战国策·西周策》"}, {"t": "而交吞揆之。", "b": "《楚辞·天问》"}, {"t": "吞二周。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "吞楼", "t": "侵吞"}, {"w": "吞夺", "t": "侵吞掠夺"}, {"w": "吞据", "t": "吞并,占据"}, {"w": "吞声忍气", "t": "强忍气愤而不出声"}, {"w": "吞声忍泪", "t": "形容强忍悲伤"}, {"w": "吞声饮恨", "t": "抱恨无言"}, {"w": "吞哀", "t": "隐忍悲伤。"}]}, {"meaning": "容纳。", "cites": [{"t": "吞若云梦者八九。", "b": "司马相如《子虚赋》"}]}, {"meaning": "忍受。", "cites": [{"t": "气断声吞。", "b": "《聊斋异·促织》"}], "words": [{"w": "吞恨", "t": ""}]}, {"meaning": "痴呆。", "cites": [{"t": "灯窗苦吟,寒酸撒吞。", "b": "汤显祖《牡丹亭·腐叹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('608wx','远','1','yuǎn','辶','7','','[{"pinyin": "yuǎn", "defs": [{"meaning": "(形声。从辵(chuò),袁声。本义:走路走得长)。"}, {"meaning": "同本义 。引申距离大,相隔远。与近相对。", "cites": [{"t": "远,辽也。", "b": "《说文》"}, {"t": "远,遐也。", "b": "《尔雅》"}, {"t": "屏之远方。", "b": "《礼记·王制》。注:“九州之外也。”"}, {"t": "柔远人也。", "b": "《礼记·中庸》"}, {"t": "穷高极远。", "b": "《礼记·乐记》"}, {"t": "念悲其远。", "b": "《战国策·赵策》"}, {"t": "远主备之,无乃不可乎?", "b": "《左传·僖公三十三年》"}, {"t": "劳师以袭远,非所闻也。", "b": "《左传·三十三年》"}, {"t": "缦立远视。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "火器利袭远,技击利巷战。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "极目远望。", "b": "《广东军务记》"}], "words": [{"w": "远行无急步", "t": "走长路不能走得太急"}, {"w": "远游之戒", "t": "指孔子“父母在,不远游”的戒训"}, {"w": "远招近揖", "t": "热情相邀、礼貌相待远近友人"}, {"w": "远水近火", "t": "即远水不救近火。比喻缓不济急。"}]}, {"meaning": "长久;长远。", "cites": [{"t": "则筮远日。", "b": "《仪礼·士冠礼》"}, {"t": "远祖者,几世乎?九世矣。", "b": "《公羊传·庄公四年》"}], "words": [{"w": "永远;长远;远世", "t": "远古的年代"}, {"w": "远裔", "t": "远代的子孙。也称“远胄”。"}]}, {"meaning": "高远;远大。", "cites": [{"t": "将有远志。", "b": "《国语·周语》"}, {"t": "未能远谋。", "b": "《左传 ·庄公十年》"}, {"t": "见义远。", "b": "《史记·屈原贾生列传》"}, {"t": "始有远略。", "b": "宋·苏洵《六国论》"}, {"t": "深谋远虑。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "远到", "t": "形容成就远大,不可限量"}, {"w": "远计", "t": "远大或长久的计划"}, {"w": "远略", "t": "远大的谋略。"}]}, {"meaning": "多。指差距大。", "cites": [{"t": "狗则远矣。", "b": "《吕氏春秋·慎行论》"}, {"t": "弗如远甚。", "b": "《战国策·齐策》"}, {"t": "出人也远矣。", "b": "唐·韩愈《师说》"}, {"t": "下圣人也亦远矣。", "b": ""}], "words": [{"w": "远年", "t": "多年"}, {"w": "远不相同", "t": ""}]}, {"meaning": "深远;深奥。", "cites": [{"t": "人无远虑,必有近忧。", "b": "《论语·卫灵公》"}], "words": [{"w": "远忧", "t": "深远的忧虑"}, {"w": "远奥", "t": "深远玄奥"}, {"w": "远略", "t": "深远的谋略"}, {"w": "远神", "t": "深远的神韵。"}]}, {"meaning": "离开;避开。", "cites": [{"t": "君子远疱厨。", "b": "《孟子·梁惠王上》"}, {"t": "暧暧远人村。", "b": "晋·陶渊明《归园田居》"}, {"t": "相远不知。", "b": "唐·李朝威《柳毅传》"}, {"t": "远罪丰家。", "b": "宋·司马光《训俭示康》"}, {"t": "敌人远我,欲以火器困我也。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "远嫌", "t": "远避嫌疑"}, {"w": "远罪", "t": "远离罪恶"}, {"w": "远鄙", "t": "避开粗俗"}, {"w": "远祸", "t": "避免祸患"}, {"w": "远开", "t": "方言。离开"}, {"w": "远势", "t": "避免滥用权势。"}]}, {"meaning": "违背。", "cites": [{"t": "故法不远义,则民服而不离。", "b": "《汉书·公孙弘传》"}], "words": [{"w": "远礼", "t": "背离礼仪"}, {"w": "远义", "t": "背离仁义。"}]}, {"meaning": "疏远,不亲近,不接近。", "cites": [{"t": "亲贤臣,远小人,此先汉所以兴隆也;亲小人,远贤臣,此后汉所以倾颓也。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又。", "cites": [{"t": "远贤臣。", "b": ""}], "words": [{"w": "远斥", "t": "疏远排斥"}, {"w": "远外", "t": "疏远,不亲近"}, {"w": "远慢", "t": "疏远轻忽"}, {"w": "远绝", "t": "疏远隔绝"}, {"w": "远斥", "t": "疏远隔绝"}, {"w": "远利", "t": "不近私利"}, {"w": "远斥", "t": "疏远排斥"}, {"w": "远外", "t": "疏远,不亲近"}, {"w": "远臣", "t": "不被亲信重视的臣子。"}]}, {"meaning": "超过;胜过 。如远逾(超越); 远迈(远远超过);远过,(超过)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('609wx','违','1','wéi','辶','7','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从辵(chuò),韦声。本义:离开;背离)。"}, {"meaning": "同本义。", "cites": [{"t": "违,离也。", "b": "《说文》"}, {"t": "违,远也。", "b": "《尔雅》"}, {"t": "中心有违。", "b": "《诗·邶风·谷风》。传:“离也。”"}, {"t": "薄违农父。", "b": "《书·酒诰》"}, {"t": "虽信美而无礼兮,来违弃而改求。", "b": "《楚辞·离骚》"}], "words": [{"w": "违别", "t": "离别"}, {"w": "违离", "t": "离别;分离;背离"}, {"w": "违恋", "t": "依依惜别"}, {"w": "违阔", "t": "离别;阔别"}, {"w": "违署", "t": "离开官署。指辞去官职"}, {"w": "违远", "t": "远离;离别"}, {"w": "违间", "t": "离别"}, {"w": "违弃", "t": "离弃;丢弃"}, {"w": "违异", "t": "离别;分离。"}]}, {"meaning": "避开。", "cites": [{"t": "纪侯大去其国,违齐难也。", "b": "《左传·庄公四年》"}], "words": [{"w": "违强凌弱", "t": "畏避强大,欺凌弱小"}, {"w": "违难", "t": "避难"}, {"w": "违避", "t": "避开;背离"}, {"w": "违敌", "t": "避敌;纵敌"}, {"w": "违寒", "t": "避开寒冷"}, {"w": "违患", "t": "避开祸患"}, {"w": "违世", "t": "避开尘世;去世。"}]}, {"meaning": "违背;违反。", "cites": [{"t": "违,偝也。", "b": "《广雅·释诂二》"}, {"t": "静言用违。", "b": "《书·尧典》"}, {"t": "且其违者不过数人。", "b": "《左传·哀公十四年》"}, {"t": "而违之俾不通。", "b": "《礼记·大学》"}, {"t": "不违农时,谷不可胜食也。", "b": "《孟子·梁惠王上》"}, {"t": "违天必有大咎。", "b": "《左传·僖公二十三年》"}, {"t": "慎勿违吾语。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "与我而相违。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "莫敢违。", "b": "《资治通鉴·唐纪》"}, {"t": "君赐不可违。", "b": "宋·司马光《训俭示康》"}, {"t": "寝食违节。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "违错", "t": "违反,违背"}, {"w": "违干", "t": "违犯;冒犯"}, {"w": "违别", "t": "违抗"}, {"w": "违逆", "t": "违背;不合情理"}, {"w": "违越", "t": "违背;越轨"}, {"w": "违心之论", "t": "与内心相违背的话"}, {"w": "违天", "t": "违背天意"}, {"w": "违科", "t": "不符合法令"}, {"w": "违俗", "t": "违背世俗的习惯或观念"}, {"w": "违常", "t": "反常,违反常理。"}]}, {"meaning": "恨。", "cites": [{"t": "行道迟迟,中心有违。", "b": "《诗·邶风·谷风》"}, {"t": "岂余身之足殉兮,违世业之可怀。", "b": "《文选·班固·幽通赋》"}], "words": [{"w": "违恨", "t": "怨恨"}, {"w": "违怨", "t": "怨恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('610wx','韧','1','rèn','韦','7','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从韦,刃声。韦,熟牛皮。本义:柔软而结实,受外力作用时虽变形而不易折断) 同本义。", "cites": [{"t": "故凡用兵者,攻坚则韧,乘暇则神。", "b": "《管子·制分》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('611wx','运','1','yùn','辶','7','','[{"pinyin": "yùn", "defs": [{"meaning": "(会意。从辵(chuò),军声。本义:运行;运转;转动)。"}, {"meaning": "同本义。", "cites": [{"t": "運,移徙也。", "b": "《说文》"}, {"t": "日、月运行。", "b": "《易·系辞》"}, {"t": "日运为躔,月运为逡。", "b": "《方言》。注:“犹行也。”"}, {"t": "是鸟也,海运。", "b": "《庄子·逍遥游》。简文注:“徙也。”"}, {"t": "天下可运于掌。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "运衡", "t": "指运转的玉衡星"}, {"w": "运玑", "t": "谓运转测天之器。玑,璇玑"}, {"w": "运斡", "t": "运转"}, {"w": "运掌", "t": "放在手掌上运转。比喻极为轻易的事情。"}]}, {"meaning": "搬运;运输。", "cites": [{"t": "运量万物而不匮。", "b": "《庄子·知北游》"}, {"t": "运,转也。", "b": "《广雅》"}, {"t": "三卜之运也。", "b": "《公羊传·定公十五年》"}, {"t": "将运舟而下浮兮。", "b": "《楚辞·九章·哀郢》"}, {"t": "浑元运物。", "b": "班固《幽通赋》"}, {"t": "运于渤海之尾。", "b": "《列子·汤问》"}, {"t": "(建兴)九年,亮复出祁山,以木牛运,粮尽退军。", "b": "三国魏·嵇康《嵇中散集》"}, {"t": "运一大石块。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "运行李;运兵;运粮;运漕", "t": "由水路运粮"}, {"w": "运船", "t": "载运物资的船只。"}]}, {"meaning": "运用。", "cites": [{"t": "或运智御世,不婴祸故。", "b": "嵇康《嵇中散集》"}], "words": [{"w": "运计铺谋", "t": "安排计谋;出谋划策"}, {"w": "运智", "t": "运用智慧计谋"}, {"w": "运谋", "t": "运用谋略。"}]}, {"meaning": "玩弄,拨弄。", "cites": [{"t": "侍坐于君子,君子欠伸,运笏,泽剑首,还履,问之蚤莫,虽请退可也。", "b": "《礼记》"}]}, {"meaning": "运气,命运。", "cites": [{"t": "运穷福艾。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "运隆祚永", "t": "国运隆盛兴旺,帝统传世久远"}, {"w": "运乖时蹇", "t": "运气很不好"}, {"w": "运合中兴", "t": "气数到了复兴的时候"}, {"w": "好运;走运", "t": ""}]}, {"meaning": "地之南北距离曰运。", "cites": [{"t": "勾践之地,…广运百里。", "b": "《国语》"}]}, {"meaning": "春秋莒邑 。在今山东省沂水县东北五十里。也作“郓”。"}, {"meaning": "日月周围的光圈。", "cites": [{"t": "画隨灰而月运朔。", "b": "《淮南子·览冥》"}, {"t": "其经运十,其别九十。", "b": "《周礼·春官·大卜》"}]}, {"meaning": "远。", "cites": [{"t": "帝德广运。", "b": "《书·大禹谟》"}]}, {"meaning": "纵,竖。", "cites": [{"t": "翼大七尺,目大运寸。", "b": "《庄子》"}]}, {"meaning": "浑浊。", "cites": [{"t": "晋之水枯旱而运,淤滞而杂。", "b": "《管子·水地》"}]}, {"meaning": "眩晕", "cites": [{"t": "五阴气俱绝,则目系转,转则目运。", "b": "《灵枢经》"}], "words": [{"w": "运眩", "t": "眼花。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('612wx','扶','1','fú','扌','7','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从手,夫声。从“手”,表示与手的动作有关。本义:搀扶)。"}, {"meaning": "同本义。", "cites": [{"t": "危而不持,颠而不扶,则将焉用彼相矣?", "b": "《论语·季氏》"}, {"t": "车至门扶。", "b": "《战国策·卫策》。注:“扶,谓下车。”"}, {"t": "遂扶以下。", "b": "《左传·宣公二年》"}, {"t": "扶杖望朱砂庵而登。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "扶绰", "t": "搀扶,扶托"}, {"w": "扶策", "t": "扶助,搀扶"}, {"w": "扶掖", "t": "搀扶;扶助"}, {"w": "扶挈", "t": "以手搀扶"}, {"w": "扶将", "t": "搀扶。"}]}, {"meaning": "扶持;护持。", "cites": [{"t": "蓬生麻中,不扶而直。", "b": "《荀子·劝学》"}], "words": [{"w": "扶树", "t": "扶持培植"}, {"w": "扶舁", "t": "扶持;搀扶"}, {"w": "扶舁", "t": "护持扛抬"}, {"w": "扶倾", "t": "扶持倾危的建筑物"}, {"w": "扶拨", "t": "扶持倾斜"}, {"w": "扶卫", "t": "扶持卫护。"}]}, {"meaning": "辅助;帮助。", "cites": [{"t": "扶,佐也。", "b": "《说文》"}, {"t": "若扶梁伐赵。", "b": "《战国策·宋策》"}, {"t": "求太老爷拘拿凶犯,以扶善良。", "b": "《红楼梦》"}], "words": [{"w": "扶政", "t": "辅佐政事"}, {"w": "扶携", "t": "扶助提携"}, {"w": "扶奖", "t": "辅助。"}]}, {"meaning": "靠近。", "cites": [{"t": "数披其木,毋使木枝挟疏。", "b": "《韩非子·杨权》"}, {"t": "秋蛩扶户吟,寒妇成夜织。", "b": "宋·鲍照《拟古八首》"}], "words": [{"w": "扶疏", "t": "枝叶茂密,高低疏密有致。"}]}, {"meaning": "攀缘。", "cites": [{"t": "扶摇抮抱羊角而上。", "b": "《淮南子·本纪》。注:“攀也。”"}], "words": [{"w": "扶服", "t": "伏在地上爬行"}, {"w": "扶伏", "t": "伏地爬行"}, {"w": "扶匐", "t": "伏地爬行。"}]}, {"meaning": "沿,顺。", "cites": [{"t": "既出,得其船,便扶向路,处处志之。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "扶向路", "t": "沿着原来的路。"}]}, {"meaning": "在水上泛行。", "cites": [{"t": "管子有扶舟之士五万人,以待战于曲菑。", "b": "《管子·轻重甲》"}]}, {"meaning": "抚养,培育。", "cites": [{"t": "芒卯之妻五子,后母慈惠仁义,扶养假子。", "b": "《列女传》"}]}, {"meaning": "古代妇女肃拜行礼的一种动作。", "cites": [{"t": "拜,于妇人为扶自抽扶而上下也。", "b": "《释名》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('613wx','抚','1','fǔ','扌','7','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从手,无声。本义:抚摩)。"}, {"meaning": "同本义。", "cites": [{"t": "撫,安也。", "b": "《说文》"}, {"t": "抚而泣之。", "b": "《国语·晋语八》"}, {"t": "左右抚矢而乘之。", "b": "《仪礼·乡射礼》"}, {"t": "妇抚儿乳,儿含乳啼。", "b": "《虞初新志·秋声诗自序》"}, {"t": "东坡右手执卷端,左手抚鲁直背。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "抚弄", "t": "抚摩"}, {"w": "抚心", "t": "用手抚摸胸口。表示安抚"}, {"w": "抚拭", "t": "抚摩拂拭"}, {"w": "抚背", "t": "抚摩脊背。表示安慰、关切等。"}]}, {"meaning": "用手按着。", "cites": [{"t": "抚弦登陴,岂不怆悢", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "抚剑", "t": "按剑"}, {"w": "抚臆", "t": "以手按胸"}, {"w": "抚手", "t": "拍手。"}]}, {"meaning": "拍或轻击。", "cites": [{"t": "抚,敷也,敷手以拍之也。", "b": "《释名·释姿容》"}, {"t": "权抚掌欢笑。", "b": "《三国志·鲁肃传》"}], "words": [{"w": "抚掌", "t": "拍手"}, {"w": "抚胸", "t": "以手捶胸。表示悲痛"}, {"w": "抚案", "t": "用手指按着节拍。"}]}, {"meaning": "安抚;安慰。", "cites": [{"t": "西和诸戎,南抚夷越。", "b": "《三国志·诸葛亮传》"}, {"t": "及设备使抚表众。", "b": "《资治通鉴》"}], "words": [{"w": "抚驭", "t": "安抚控制"}, {"w": "抚理", "t": "安抚治理"}, {"w": "抚辑", "t": "安抚慰问"}, {"w": "抚柔", "t": "安抚怀柔。"}]}, {"meaning": "照料使健全生长;养育。", "cites": [{"t": "依新已五岁,转眼成人,汝其善抚之。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "抚字", "t": "抚养;抚肩"}, {"w": "抚孤", "t": "抚养、救济孤儿"}, {"w": "抚畜", "t": "抚养"}, {"w": "抚稚", "t": "抚养儿女。"}]}, {"meaning": "占有。", "cites": [{"t": "西方有九国焉,君王其终抚诸。", "b": "《礼记》"}]}, {"meaning": "(hū)。掩;盖。", "cites": [{"t": "神与化游,以扶四方。", "b": "《淮南子·原道》"}], "words": [{"w": "抚世", "t": "盖世。"}]}, {"meaning": "官名。巡抚的简称。", "cites": [{"t": "督抚大吏争上符瑞,礼官輙表贺。", "b": "《明史·海瑞传》"}], "words": [{"w": "抚军", "t": "巡抚的别称"}, {"w": "抚台", "t": "巡抚的别称"}, {"w": "抚署", "t": "巡抚公著"}, {"w": "抚院、学院", "t": "巡抚衙门和学院衙门。清巡抚,省级最高行政长官。"}]}, {"meaning": "古州名 。汉豫章郡地,陈置抚州。在今江西省临川县治。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('614wx','坛','1','tán','土','7','','[{"pinyin": "tán", "defs": [{"meaning": "(形声。从土,亶(dǎn)声。本义:土筑的高台,用于祭祀、会盟等)。"}, {"meaning": "同本义。", "cites": [{"t": "坛,祭坛场也。", "b": "《说文》。除地曰场,曰墠,于墠筑土曰坛。坛无不墠,而墠有不坛。"}, {"t": "为三坛同墠。", "b": "《书·金縢》。马注:“坛,土堂也。”"}, {"t": "燔柴于泰坛祭天也。", "b": "《礼记·祭法》"}, {"t": "庄公升坛。", "b": "《公羊传·庄公十六年》"}, {"t": "为坛而盟。", "b": "《史记·陈涉世家》"}], "words": [{"w": "坛宇", "t": "高台的边际。譬喻规格、界限;祭祀的坛场"}, {"w": "坛兆", "t": "坛场。兆,坛的界限"}, {"w": "坛域", "t": "设坛的范围。引申为界域、范围"}, {"w": "坛户", "t": "掌管坛场财物、负责祭奠物品的人"}, {"w": "坛坎", "t": "供祭祀用的土台和坑穴。"}]}, {"meaning": "像坛之物。", "cites": [{"t": "又东五百里,曰成山,四方而三坛。", "b": "《山海经·南山经》"}]}, {"meaning": "土筑的屋基。", "cites": [{"t": "舍不为坛。", "b": "《左传·襄公二十八年》"}], "words": [{"w": "坛基", "t": "宅基。"}]}, {"meaning": "园林庭院中点缀环境的台子。", "cites": [{"t": "荪壁兮紫坛。", "b": "屈原《九歌》"}], "words": [{"w": "花坛", "t": ""}]}, {"meaning": "楚人称中庭为坛,庭院。", "cites": [{"t": "巢堂坛兮。", "b": "《楚词·屈原·涉江》"}]}, {"meaning": "筑坛祭祀。", "cites": [{"t": "维元祀,巡守四岳八伯,坛四奥,沈四海,封十有二山,兆十有二州。", "b": "《尚书大传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('615wx','技','1','jì','扌','7','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从手,支声。本义:技艺,技巧,才艺)。"}, {"meaning": "同本义。", "cites": [{"t": "技,巧也。", "b": "《说文》"}, {"t": "尚技而贱车。", "b": "《礼记·坊记》。注:“犹艺也。”"}, {"t": "无他抚。", "b": "《大学》"}, {"t": "他技,奇巧异端也。", "b": "《公羊传·文公十二年》注"}, {"t": "人多技巧。", "b": "《老子》。注:“工匠之巧也。”"}, {"t": "能有所艺者技也。", "b": "《庄子·天地》"}, {"t": "道也,进乎技矣。", "b": "《庄子·养生主》"}, {"t": "技盖至于此。", "b": "《庄子·养生主》"}, {"t": "技止此耳。", "b": "唐·柳宗元《三戒》"}, {"t": "技之奇妙。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "技亦灵怪。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "技量", "t": "本事;能耐"}, {"w": "技穷", "t": "方法用尽,本领使完"}, {"w": "技擅穿杨", "t": "形容射箭技艺高超"}, {"w": "技俩", "t": "技能;手段"}, {"w": "技法", "t": "艺术创作的技巧和方法。"}]}, {"meaning": "歌舞。亦指以歌舞为业的艺人。", "cites": [{"t": "名姝异技,虽禁中不逮。", "b": "《新唐书·元载传》"}, {"t": "天下之善技。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "李伶为绝技。", "b": ""}], "words": [{"w": "技和", "t": "宋代杂剧的散段"}, {"w": "技人", "t": "表演歌舞的艺人"}, {"w": "技乐", "t": "善于吹弹歌舞的人。"}]}, {"meaning": "工匠,从事一些行业或手工业的人。", "cites": [{"t": "故百技所成,所以养一人也。", "b": "《荀子·富国》"}], "words": [{"w": "百技", "t": "各种行业的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('616wx','坏','1','huài','土','7','','[{"pinyin": "huài", "defs": [{"meaning": "(形声。从土,褱(huái)声。古代建筑物主要以土建造,故从“土”。本义:倒塌(指建筑物遭到破坏)。按:古代“坏”与“壞”是音义都不相同的两个字。“坏”,本读作pēi,是个从土、不声的形声字,指“未烧过的砖瓦、陶器”。现在“壞”简化为“坏”)。"}, {"meaning": "同本义。", "cites": [{"t": "坏,败也。", "b": "《说文》。按,当训毁也。"}, {"t": "坏,毁也。", "b": "《尔雅·释诂》"}, {"t": "坠坏城郭。", "b": "《史记·秦始皇本纪》。正义:“坼也,自颓曰坏。”"}, {"t": "大室之屋坏。", "b": "《左传·文公十三年》"}, {"t": "恭公坏孔子宅以为宫。", "b": "《论衡·佚文》"}, {"t": "天雨墙坏。", "b": "《韩非子·说难》"}, {"t": "而坏都舍。", "b": "《吕氏春秋·察今》"}, {"t": "室坏不修。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "坏山", "t": "倒塌的山"}, {"w": "坏决", "t": "倒塌;破败"}, {"w": "坏溃", "t": "坍塌"}, {"w": "坏压", "t": "坍塌"}, {"w": "坏裂", "t": "崩溃"}, {"w": "坏颓", "t": "崩毁。"}]}, {"meaning": "破坏;毁坏。", "cites": [{"t": "门坏。", "b": "《资治通鉴·唐纪》"}, {"t": "坏大门及寝门而入。公惧,入于室,又坏户。", "b": "《左传·成公十年》"}, {"t": "有基无坏。", "b": "《左传·襄公二十四年》"}], "words": [{"w": "坏舛", "t": "毁坏错乱"}, {"w": "坏乱", "t": "败坏错乱"}, {"w": "坏乱", "t": "败坏;混乱"}, {"w": "坏废", "t": "败坏;废弛。"}]}, {"meaning": "衰亡。", "cites": [{"t": "诸侯贰则晋国坏,晋国贰则子之家坏。", "b": "《左传·襄公二十四年》"}, {"t": "王室之不坏。", "b": "《左传·襄公十四年》"}], "words": [{"w": "坏微", "t": "衰败"}, {"w": "坏灭", "t": "毁灭;磨灭。"}]}, {"meaning": "变质;变得不好或有害。", "cites": [{"t": "譬彼坏木。", "b": "《诗·小雅·小弁》"}], "words": [{"w": "坏烂", "t": "腐烂;变质"}, {"w": "坏腹", "t": "泻肚。"}]}, {"meaning": "战败。", "cites": [{"t": "擂鼓大进,北军大坏,曹军退走。", "b": "《三国志·吴志》"}, {"t": "北军大坏。", "b": "《资治通鉴》"}]}, {"meaning": "坏事,指官员被革职、查办。", "cites": [{"t": "这还是当年先父带来的,原系忠义亲王老千岁要的,因他坏了事,就不曾用。", "b": "《红楼梦》"}]}, {"meaning": "坏分子的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('617wx','抠','1','kōu','扌','7','','[{"pinyin": "kōu", "defs": [{"meaning": "(形声。从手,区声。本义:抓,提)。"}, {"meaning": "同本义。", "cites": [{"t": "使数人抠耳,力掀举之。", "b": "《聊斋志异·大力将军》"}], "words": [{"w": "抠衣", "t": "提起衣服前襟。表示对人恭敬"}, {"w": "抠迎", "t": "抠衣迎接"}, {"w": "抠裳", "t": "抠衣"}, {"w": "抠请", "t": "抠衣延请。"}]}, {"meaning": "挖。", "cites": [{"t": "抠眼睛,捻鼻子。", "b": "《西游记》"}], "words": [{"w": "在地上抠个洞;把掉在缝里的豆粒抠出来;抠心挖肚", "t": "抠心挖血。挖空心思,绞尽脑汁"}, {"w": "抠索", "t": "掏挖,勒索。"}]}, {"meaning": "抓牢。", "cites": [{"t": "卓气力大,两手抠住;吕布便入,揪倒伍孚。", "b": "《三国演义》"}]}, {"meaning": "眼睛凹陷 。如;抠搂(眼珠子深陷在眼眶里)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('618wx','扰','1','rǎo','扌','7','','[{"pinyin": "rǎo", "defs": [{"meaning": "(形声。从手,擾省(yōu)声。本义:搅扰;扰乱)。"}, {"meaning": "同本义。", "cites": [{"t": "扰,扰乱也。", "b": "《玉篇》"}, {"t": "各有攸处,德用不扰。", "b": "《左传·襄公四年》"}, {"t": "秦失其道,豪杰并扰。", "b": "《史记·太史公自序》"}, {"t": "当农桑时,以役事扰民者,举正以闻。", "b": "《三国志·吴主传》"}, {"t": "(逆夷)不敢复行兹扰。", "b": "《广东军务记》"}, {"t": "大惊扰。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "扰搅", "t": "搅扰"}, {"w": "扰怨", "t": "扰民惹怨"}, {"w": "扰紊", "t": "扰乱"}, {"w": "扰逼", "t": "骚乱逼迫"}, {"w": "扰累", "t": "扰害"}, {"w": "扰习", "t": "言习以为常"}, {"w": "扰夺", "t": "掠夺"}, {"w": "扰民", "t": "侵扰百姓。"}]}, {"meaning": "叨扰,指受人财物、饮食。", "cites": [{"t": "凡吊及送丧葬者,必助其丧事而勿扰也。", "b": "司马光《书仪》"}]}, {"meaning": "安抚;和顺。", "cites": [{"t": "以扰万民。", "b": "《周礼·大宰》"}], "words": [{"w": "扰乂", "t": "安定,治理"}, {"w": "扰绥", "t": "安抚。"}]}, {"meaning": "驯养。", "cites": [{"t": "乃扰畜龙。", "b": "《左传·昭二九年》"}], "words": [{"w": "扰化", "t": "教化"}, {"w": "扰畜", "t": "驯服;驯养"}, {"w": "扰柔", "t": "驯服"}, {"w": "扰服", "t": "驯服"}, {"w": "扰狎", "t": "驯服"}, {"w": "扰民", "t": "驯服百姓"}, {"w": "扰顺", "t": "驯服。"}]}, {"meaning": "混乱;烦乱。", "cites": [{"t": "绿云扰扰,梳晓鬟也。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "扰冗", "t": "烦乱"}, {"w": "扰惑", "t": "烦乱"}, {"w": "扰烦", "t": "烦扰"}, {"w": "扰弊", "t": "因纷扰而衰弊"}, {"w": "扰嚷", "t": "犹吵闹"}, {"w": "扰惧", "t": "惊恐,慌乱。"}]}, {"meaning": "浑浊不清。", "cites": [{"t": "水扰则鱼鳖不大。", "b": "朱骏声《说文通训定声》引《吕氏春秋》"}]}, {"meaning": "柔弱;顺从。", "cites": [{"t": "扰而毅。", "b": "《书·皋陶谟》"}, {"t": "其后有刘累,学扰龙。", "b": "《史记·夏本纪》"}, {"t": "里安户扰,罔有不咸。", "b": "宋·曾巩文"}], "words": [{"w": "扰从", "t": "顺从"}, {"w": "扰毅", "t": "和顺坚毅。"}]}, {"meaning": "家畜。", "cites": [{"t": "其畜宜六扰。", "b": "《周礼·夏官》。郑玄注:“六扰,马、牛、羊、豕、犬、鸡。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('619wx','扼','1','è','扌','7','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从手,厄声。本义:抓住;掐住)。"}, {"meaning": "同本义。", "cites": [{"t": "搤,捉也。", "b": "《说文》"}, {"t": "力扼虎,射命中。", "b": "《汉书·李陵传》"}, {"t": "搤其喉而不得进。", "b": "《后汉书·荀彧传》"}, {"t": "不搤其亢。", "b": "《汉书·娄敬传》"}, {"t": "搤熊罴。", "b": "《汉书·扬雄传》"}, {"t": "搤,持也。", "b": "《广雅·释诂三》"}], "words": [{"w": "扼虎", "t": "用双手掐住猛虎"}, {"w": "扼吭拊背", "t": "本指控制咽喉。引申为扼制要冲之意"}, {"w": "扼襟", "t": "握持衣服的襟领。引申为控制要害,掌握要领"}, {"w": "扼臂", "t": "手臂。"}]}, {"meaning": "阻碍,堵住。", "cites": [{"t": "因而搤之可也。", "b": "《庄子》。又如:扼昧(暗中加害);扼塞(阻塞);扼隘(堵住要隘);扼吭(气逆于喉)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('620wx','拒','1','jù','扌','7','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从手,巨声。本义:抵御,抵抗)。"}, {"meaning": "同本义。", "cites": [{"t": "其不可者拒之。", "b": "《论语》"}, {"t": "拒敌也。", "b": "《荀子·仲尼》注"}, {"t": "内以固城,外以拒难。", "b": "《荀子·君道》"}], "words": [{"w": "拒御", "t": "抵御"}, {"w": "拒敌", "t": "抵御敌人;匹敌,比得上"}, {"w": "拒捍", "t": "抵抗"}, {"w": "拒马", "t": "古代的一种防御战具。用以布阵阻塞,使人马止步,不得跨越。"}]}, {"meaning": "拒绝,抵制。", "cites": [{"t": "往者不追,来者不拒。", "b": "《孟子·尽心下》"}], "words": [{"w": "拒谏", "t": "不肯接受别人的规劝"}, {"w": "拒物", "t": "拒绝外物,谓不与外界接触"}, {"w": "拒却", "t": "拒绝,推却"}, {"w": "拒闭", "t": "闭门拒绝。"}]}, {"meaning": "占据。", "cites": [{"t": "不即安分,却来拒吾之公厅,此又不知耻也。", "b": "《清平山堂话本》"}]}, {"meaning": "方形阵势。", "cites": [{"t": "拘环拒折之容。", "b": "《淮南子·齐俗》"}, {"t": "从唐侯以为左拒,以从上军。", "b": "《左传·宣公十二年》"}, {"t": "郑子元请为左拒,以当蔡人,卫人;为右拒,以当陈人。", "b": "《左传·恒公五年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('621wx','找','1','zhǎo','扌','7','','[{"pinyin": "zhǎo", "defs": [{"meaning": "(会意。从手,从戈。像用手拾戈。本义:觅取,寻求)。"}, {"meaning": "同本义。", "cites": [{"t": "这可丢了!往那里找去?", "b": "《红楼梦》"}]}, {"meaning": "补不足。", "cites": [{"t": "当下先秤了一半船钱,那一半直待到县时找足。", "b": "《警世通言》"}], "words": [{"w": "找补", "t": "添补;补偿;补充"}, {"w": "找价", "t": "补加价款。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('622wx','批','1','pī','扌','7','','[{"pinyin": "pī", "defs": [{"meaning": "(形声。从手,比声。本义:反手打)。"}, {"meaning": "引申为刺入。", "cites": [{"t": "依乎天理,批大郤,导大窾。", "b": "《庄子》"}]}, {"meaning": "分析;评论。", "cites": [{"t": "后人有《西江月》二词,批宝玉极恰。", "b": "《红楼梦》"}], "words": [{"w": "揭批", "t": "揭发批判"}, {"w": "批削", "t": "即批改"}, {"w": "批拓", "t": "讥讽;轻视"}, {"w": "批点", "t": "批评指画"}, {"w": "批搨", "t": "即批评。"}]}, {"meaning": "披露。", "cites": [{"t": "妙玉扶乩批出来,众人不解。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('623wx','址','1','zhǐ','土','7','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从土,止声。字本从阜,止声。本义:地基,基部)。"}, {"meaning": "同本义。", "cites": [{"t": "阯,基也。从阜,止声,或从土。", "b": "《说文》"}, {"t": "禅泰山下阯。", "b": "《汉书·郊祀志》。注:“阯者,山之基足。”"}, {"t": "丰墙峭阯。", "b": "《汉书·太元大》"}, {"t": "自城中附城为长堤,壮其址。", "b": "宋·苏轼《奖喻敕记》"}, {"t": "废祠之址。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "地点;地址;处所。", "cites": [{"t": "树重置于西址,列骏骑手北垌。", "b": "汉·王粲《羽猪赋》"}], "words": [{"w": "芙蓉镇故址;厂址;住址", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('624wx','扯','1','chě','扌','7','','[{"pinyin": "chě", "defs": [{"meaning": "(形声。从手,奢声。扯是“撦”的俗字。本义:撕裂)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('625wx','走','1','zǒu','走','7','','[{"pinyin": "zǒu", "defs": [{"meaning": "(会意。金文字形象摆动两臂跑步的人形,下部象人脚。合起来表示人在跑。本义:跑)。"}, {"meaning": "同本义。", "cites": [{"t": "走,趋也。", "b": "《说文》"}, {"t": "来朝走马。", "b": "《诗·大雅·緜》"}, {"t": "某将走见。", "b": "《仪礼·士相见礼》"}, {"t": "险其走。", "b": "《左传·昭公二十三年》"}, {"t": "若蝉之走明火也。", "b": "《吕氏春秋·期贤》"}, {"t": "在位者皆反走辟。", "b": "《大戴礼记·诸侯迁庙》"}, {"t": "扁鹊望桓侯而还走。", "b": "《韩非子·喻老》"}, {"t": "兔走触株,折颈而死。", "b": "《韩非子·五蠹》"}, {"t": "夸父与日逐走。", "b": "《山海经·海外北经》"}, {"t": "双兔傍地走。", "b": "《乐府诗集·木兰诗》"}, {"t": "飞沙走砾。", "b": "明·袁宏道《满井游记》"}, {"t": "录毕,走送之,不敢稍愈约。", "b": "明·宋濂《送东阳马生序》"}, {"t": "几欲先走。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "走马观花;走堂的", "t": "跑堂的"}, {"w": "走塘的", "t": "跑堂的"}, {"w": "走百病", "t": "元宵节妇女出游,认为可驱邪除祟"}, {"w": "走骤", "t": "飞奔。疾驰"}, {"w": "走丸", "t": "如丸迅速旋转"}, {"w": "走解", "t": "在跑动的马背上表演特技"}, {"w": "走三家不如坐一家", "t": "比喻专心一事,比较容易成功。"}]}, {"meaning": "逃跑。", "cites": [{"t": "兵刃既接,弃甲曳兵而走。", "b": "《孟子·梁惠王上》"}, {"t": "老翁逾墙走,老妇出门看。", "b": "杜甫《石壕吏》"}, {"t": "已而燕军攻安平,城坏,齐人走,争涂。", "b": "《史记·田单列传》"}, {"t": "齐兵败,闵王出走于外。", "b": "《战国策·燕策一》"}, {"t": "田荣即引兵归,逐其王假,假亡走楚。", "b": "《史记·项羽本纪》"}, {"t": "老官,走了牛也!走了牛也!", "b": "《西游记》"}], "words": [{"w": "走避", "t": "逃去,避开"}, {"w": "走北", "t": "战败而逃"}, {"w": "走匿", "t": "逃走躲避。"}]}, {"meaning": "往。奔向某地。", "cites": [{"t": "渔者走渊,木者走山。", "b": "《淮南子》"}, {"t": "骊山北构而西折,直走咸阳。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "青捕虏知单于所居,乃自以精兵走之。", "b": "《史记·李将军列传》"}, {"t": "趋利如水走下,四方亡择也。", "b": "晁错《论贵粟疏》"}, {"t": "民之归仁也,犹水之就下,兽之走圹也。", "b": "《孟子》"}, {"t": "若蝉之走明火也。", "b": "《吕氏春秋》"}, {"t": "走诉行御史台。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "泄漏。", "cites": [{"t": "不是旧话儿走了风,却是甚的!", "b": "《西游记》"}], "words": [{"w": "走作", "t": "超出范围或改变原来的样子"}, {"w": "走泄", "t": "走漏;泄露"}, {"w": "走阳", "t": "精泄不止;遗精"}, {"w": "走话", "t": "说话泄露秘密"}, {"w": "走火入魔", "t": "因过分沉溺于某种事情,而方法又不正确,以致身心受到伤害。"}]}, {"meaning": "丧失,失去。", "cites": [{"t": "沟不要深,则不走肥。", "b": "《沈氏农书》"}], "words": [{"w": "走油", "t": "旧法用桐油漆饰器物,油饰融褪,称为“走油”"}, {"w": "走板", "t": "唱歌时不合节拍"}, {"w": "走失", "t": "丧失;丢去"}, {"w": "走泄", "t": "放泄,流失。"}]}, {"meaning": "泛指兽类。", "cites": [{"t": "上无逸飞,下无遗走。", "b": "汉·张衡《西京赋》"}]}, {"meaning": "车轮。", "cites": [{"t": "以车两走,轴间广大以圉。", "b": "《墨子》"}]}, {"meaning": "仆人,有时含蔑称意。", "cites": [{"t": "我议欲板筑,群走皆不怡。", "b": "《建德新墙》"}], "words": [{"w": "走吏", "t": "供奔走的小吏"}, {"w": "走史", "t": "走使。指仆役"}, {"w": "走胥", "t": "小吏"}, {"w": "走脚", "t": "跑腿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('626wx','抄','1','chāo','扌','7','','[{"pinyin": "chāo", "defs": [{"meaning": "(形声。从手,少声。本义:叉取)。"}, {"meaning": "同本义。"}, {"meaning": "搜查并没收。", "cites": [{"t": "而抄捕南海馆之报忽至。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "抄籍", "t": "抄没并登记归公"}, {"w": "抄没", "t": "查抄没收。"}]}, {"meaning": "匙子;小勺。", "cites": [{"t": "两个初煨黄栗子,半抄新炒白芝麻。", "b": "《清史稿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('627wx','贡','1','gòng','贝','7','','[{"pinyin": "gòng", "defs": [{"meaning": "(形声。从贝,工声。本义:进贡,把物品进献给朝廷)。"}, {"meaning": "同本义。", "cites": [{"t": "贡,献功也。", "b": "《说文》"}, {"t": "贡,上也。", "b": "《释言》"}, {"t": "贡,献也。", "b": "《广雅》"}, {"t": "尔贡包茅不入。", "b": "《左传·僖公四年》"}, {"t": "以令地贡。", "b": "《周礼·大司徒》。注:“贡地所生,谓九谷。”"}, {"t": "以任地事而令贡赋。", "b": "《周礼·小司徒》。注:“谓九谷三泽之材也。”"}, {"t": "贡者,自治其所受田,贡其税谷。", "b": "《考工记·匠人》注"}, {"t": "举天下所贡蝴蝶、螳螂、油利挞、青丝额一切异状遍试之,无出其右者。", "b": "《聊斋志异·促织》"}], "words": [{"w": "贡奉", "t": "进献物品给朝廷"}, {"w": "贡云", "t": "宋宫中假山艮岳既成,命近山处居民以油绢巨囊,于晨间捕捉山间野云,用车驾运送艮岳,放纵假山间,以供君王观赏,名为贡云。"}]}, {"meaning": "示告;告诉。", "cites": [{"t": "六爻之义易以贡。", "b": "《易·系辞》。韩注:“告也。”"}], "words": [{"w": "贡诚", "t": "表达真诚之心"}, {"w": "贡实", "t": "表达诚心"}, {"w": "贡款", "t": "贡诚。"}]}, {"meaning": "赏赐。", "cites": [{"t": "贡,赐也。", "b": "《尔雅·释诂》"}, {"t": "端木赐,字子贡。", "b": "《史记·仲尼弟子传》"}], "words": [{"w": "贡土", "t": "古代帝王分封诸侯时,按封地方位取一色土授之,供其立社设坛。"}]}, {"meaning": "推荐。", "cites": [{"t": "举人贡士。", "b": "《后汉书·章帝纪》"}, {"t": "尝勤苦学文,迨今十年,始获一贡。", "b": "唐·白居易《与陈给事书》"}], "words": [{"w": "贡人", "t": "由府、州、县推荐到朝廷的人士"}, {"w": "贡士", "t": "清代会试被录取者"}, {"w": "贡官", "t": "科举时代主持考务的官员"}, {"w": "贡察", "t": "举荐"}, {"w": "贡贤", "t": "荐举贤人"}, {"w": "贡选", "t": "州、郡向中央举荐选拔的人材。"}]}, {"meaning": "贡品,贡献的物品。", "cites": [{"t": "五官致贡曰享。", "b": "《礼记·曲礼》。注:“功也。”"}, {"t": "理道之远近而致贡。", "b": "《荀子·王制》"}], "words": [{"w": "纳贡;进贡;贡计", "t": "贡物的登记簿"}, {"w": "贡砚", "t": "贡研。充作贡品的砚台"}, {"w": "贡棐", "t": "盛贡品的竹筐"}, {"w": "贡禄", "t": "贡赋和俸禄。"}]}, {"meaning": "夏代的田赋名称。", "cites": [{"t": "夏后氏五十而贡,殷人七十而助,周人百亩而彻,其实皆什一也。", "b": "《孟子·滕文公上》"}], "words": [{"w": "贡赋", "t": "赋税"}, {"w": "贡助", "t": "古代田赋之法。夏代一夫授田五十亩,每夫计其五亩之入以为贡"}, {"w": "贡彻", "t": "贡、彻分别为夏、周的田税制度。后因以指赋税。"}]}, {"meaning": "(gōng)。女工。从事手工劳动的女性。", "cites": [{"t": "女贡织帛,苟合于国奉者,皆置而券之。", "b": "《管子·山国轨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('628wx','汞','1','gǒng','水','7','','[{"pinyin": "gǒng", "defs": [{"meaning": "本义:一种有毒的银白色一价和二价重金属元素,它是常温下唯一的液体金属,游离存在于自然界并存在于辰砂、甘汞及其他几种矿中。常常用焙烧辰砂和冷凝汞蒸气的方法制取汞,它主要用于科学仪器(电学仪器、控制设备、温度计、气压计)及汞锅炉、汞泵及汞气灯中 ——元素符号Hg。通称“水银”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('629wx','坝','1','bà','土','7','','[{"pinyin": "bà", "defs": [{"meaning": "(形声。从土,霸声。本义:堤坝)。"}, {"meaning": "截河拦水的堤堰。堤坝。", "cites": [{"t": "其河自西坝至东坝十六里有余。", "b": "单锷《吴中水利书》"}], "words": [{"w": "丁坝;坝埽;顺坝", "t": ""}]}, {"meaning": "平地。", "cites": [{"t": "君家水茄白银色,殊胜坝里紫彭亨。", "b": "黄庭坚《谢杨履道》"}], "words": [{"w": "坝子", "t": "中国西南地区称平地或平原"}, {"w": "坪坝;晒坝", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('630wx','攻','1','gōng','攵','7','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从攴(pū),工声。本义:进攻,攻打)。"}, {"meaning": "同本义(与“守”相对)。", "cites": [{"t": "攻,击也。", "b": "《说文》"}, {"t": "攻灵公于桃园。", "b": "《左传·宣公二年》"}, {"t": "宽则两军相攻。", "b": "《战国策·秦策》"}, {"t": "以此攻城,何城不克?", "b": "《左传·僖公四年》"}, {"t": "公输盘为楚造云梯之械,成,将以攻宋。", "b": "《墨子·公输》"}, {"t": "其次伐兵,下政攻城,攻城之法为不得已。", "b": "《孙子·谋攻》"}, {"t": "仁义不施而攻守之势异也。", "b": "汉·贾谊《过秦论》"}, {"t": "子曰:“非吾徒也,小子鸣鼓而攻之可也。”", "b": "《论语·先进》"}], "words": [{"w": "攻车", "t": "古代的一种兵车。用于进攻"}, {"w": "攻钞", "t": "攻打劫掠"}, {"w": "攻围", "t": "攻敌时切断敌人要塞与外界的交通,予以四面包围"}, {"w": "攻无不取", "t": "只要进攻,必能夺取。"}]}, {"meaning": "指责。", "cites": [{"t": "五曰攻,六曰说。", "b": "《周礼·太祝》。注:“以辞责之。”"}, {"t": "攻者责也。", "b": "《论衡·顺鼓》"}], "words": [{"w": "攻瑕指失", "t": "批评缺点,指出失误"}, {"w": "攻瑕索垢", "t": "批评不足,寻找缺点"}, {"w": "攻摘", "t": "批评指摘。"}]}, {"meaning": "引申为以药物治疗疾病。", "cites": [{"t": "凡疗疡,以五毒攻之。", "b": "《周礼·天官·疡医》"}], "words": [{"w": "攻疗", "t": "治疗"}, {"w": "攻治", "t": "医治"}, {"w": "攻熨", "t": "原指以药物炒热敷患处,散寒止痛。引申为改正"}, {"w": "攻泻", "t": "饮服烈性药物使之宣泻。"}]}, {"meaning": "致力研究,专心从事。", "cites": [{"t": "闻道有先后,术业有专攻,如是而已。", "b": "唐·韩愈《师说》"}], "words": [{"w": "攻苦食淡", "t": "致力于勤苦之事,食用无味之物。引申为艰苦自励,一心求学"}, {"w": "攻苦", "t": "从事于劳苦之事。多指苦心求学"}, {"w": "攻习", "t": "攻读;奋力学习。"}]}, {"meaning": "治理,加工。", "cites": [{"t": "攻,治也。", "b": "《广雅·释诂三》"}, {"t": "庶民攻之。", "b": "《国语·楚语上》"}, {"t": "农攻粟,工攻器,贾攻货。", "b": "《吕氏春秋·上农》"}, {"t": "贤第新成,攻坚。", "b": "《汉书·董贤传》"}], "words": [{"w": "攻玉", "t": "琢磨玉石"}, {"w": "他山之石,可以攻玉", "t": ""}]}, {"meaning": "器物精好坚利。", "cites": [{"t": "我车既攻,我马既同。", "b": "《诗·小雅·车攻》"}, {"t": "械用兵革攻完便利者强。", "b": "《荀子·议兵》"}, {"t": "先者难为知,而后者易为攻也。", "b": "《淮南子·原道》"}], "words": [{"w": "攻牢", "t": "坚固"}, {"w": "攻致", "t": "坚固紧密"}, {"w": "攻完", "t": "坚固完好。"}]}, {"meaning": "功绩。", "cites": [{"t": "易攻伐以治我国,攻必倍。", "b": "《墨子·非攻下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('631wx','赤','1','chì','赤','7','','[{"pinyin": "chì", "defs": [{"meaning": "(会意。甲骨文,从大(人)从火。人在火上,被烤得红红的。一说“大火”为赤。本义:火的颜色,即红色)。"}, {"meaning": "同本义。", "cites": [{"t": "赤,南方色也。", "b": "《说文》"}, {"t": "赤者,火色也。", "b": "《书·洪范·五行传》"}, {"t": "其色赤。", "b": "《素问·风论》。注:“赤者,心色也。”"}, {"t": "赤刀。", "b": "《书·顾命》。郑注:“武王诛纣时刀赤为饰。”"}, {"t": "色赤椒好。", "b": "《齐民要术·种椒》"}, {"t": "困于赤绂。", "b": "《易·困卦》。郑注:“朱深曰赤。”"}, {"t": "日上,正赤如丹。", "b": "姚鼐《登泰山记》。又如:赤刀(刀口赤色的宝刀);赤衣(红色衣服);赤丸(红色弹丸);赤日(红日;烈日);赤石(红色的石头);赤泥(呈红色的泥土)"}]}, {"meaning": "忠诚;真纯。", "cites": [{"t": "推赤心于天下。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "赤心", "t": "忠心"}, {"w": "赤衷", "t": "赤诚的心意"}, {"w": "赤情", "t": "真诚的心意。"}]}, {"meaning": "裸露。", "cites": [{"t": "当流赤足蹋涧石,水声激激风吹衣。", "b": "唐·韩愈《山石诗》"}], "words": [{"w": "赤剥", "t": "光身子"}, {"w": "赤巴巴", "t": "赤裸裸;毫无掩饰"}, {"w": "赤脚大罗仙", "t": "传说中得道的李君"}, {"w": "赤条精光", "t": "全身赤裸。"}]}, {"meaning": "空;尽;一无所有。", "cites": [{"t": "晋国大旱,赤地三年。", "b": "《韩非子·十过》"}, {"t": "当年老使君赤手降於菟。", "b": "苏轼《送范纯粹守庆州》"}], "words": [{"w": "赤淋淋", "t": "赤条条,一丝不挂"}, {"w": "赤白白", "t": "一无所有"}, {"w": "赤洒洒", "t": "形容无牵无挂。"}]}, {"meaning": "共产党。", "cites": [{"t": "这里现亦大讨其赤,中大学生被捕者有四十余人。", "b": "鲁迅《书信·致李霁野》"}]}, {"meaning": "除掉,诛灭。", "cites": [{"t": "此祸水也!指日赤吾族矣!", "b": "《聊斋志异·小翠》"}], "words": [{"w": "赤族", "t": "诛灭全族"}, {"w": "赤诛", "t": "诛杀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('632wx','折','1','shé zhē zhé','扌','7','','[{"pinyin": "shé", "defs": [{"meaning": "使断成两截(如在变形应力或张应力下)。", "cites": [{"t": "别太使劲,不然绳子就要折了", "b": ""}]}]}, {"pinyin": "zhē", "defs": [{"meaning": "倒过来倒过去。", "cites": [{"t": "只管把果子折在一个碟子里,端着就走。", "b": "《红楼梦》"}], "words": [{"w": "开水太烫,拿两个杯子折一折就凉了", "t": ""}]}]}, {"pinyin": "zhé", "defs": [{"meaning": "(会意。甲骨文字形,右边是斧子(斤),左边是断开的“木”,意即斤砍断木。后来断木演变为“手”,意为用手拿斧弄断东西。本义:折断)。"}, {"meaning": "同本义。", "cites": [{"t": "折其右肱。", "b": "《易·丰》"}, {"t": "兑为毁折。", "b": "《易·说卦》"}, {"t": "无折我树杞。", "b": "《诗·郑风·将仲子》"}, {"t": "折疡之祝药。", "b": "《周礼·疡医》"}, {"t": "设折俎。", "b": "《仪礼·特牲礼》"}, {"t": "无折骨。", "b": "《左传·哀公元年》"}, {"t": "兔走触株,折领而死。", "b": "《韩非子·五蠹》"}, {"t": "堕而折期髀。", "b": "《淮南子·人间训》"}, {"t": "白草折。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "触柱折辕。", "b": "《汉书·李广苏建传》"}, {"t": "折臂断足。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "骨折;兰摧玉折;折针儿", "t": "断针。比喻不值钱的东西"}, {"w": "折伐", "t": "拗折砍伐"}, {"w": "折首", "t": "砍首"}, {"w": "折脚铛", "t": "断脚锅"}, {"w": "折齿", "t": "折断牙齿。"}]}, {"meaning": "引申为曲折;弯。", "cites": [{"t": "折,曲也。", "b": "《广雅》"}, {"t": "河九折入于海。", "b": "《淮南子·览冥》"}, {"t": "安能摧眉折腰事权贵。", "b": "李白《梦游天姥呤留别》"}, {"t": "潭西南而望,斗折蛇行。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "折身", "t": "曲身"}, {"w": "折行", "t": "水曲折流行"}, {"w": "折简", "t": "折札"}, {"w": "折水", "t": "回旋的流水"}, {"w": "折还", "t": "曲行。古代礼节,表示行进的一种步法"}, {"w": "折盘", "t": "回旋貌;盘曲貌"}, {"w": "折腰步", "t": "走路时摆动腰肢,扭捏作态"}, {"w": "折脖子", "t": "低头。"}]}, {"meaning": "反转;改变方向。", "cites": [{"t": "骊山北构而西折。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "折旋", "t": "折回来,返回"}, {"w": "折身", "t": "转身"}, {"w": "折易", "t": "辟易。改变方向行走。"}]}, {"meaning": "屈服;折服。", "cites": [{"t": "则周必折而入于韩。", "b": "《战国策·西周策》"}, {"t": "晚救之,韩且折而入于魏,不如早救之。", "b": "《战国策》"}], "words": [{"w": "折伏", "t": "制服,使屈服"}, {"w": "折愧", "t": "折辱,侮辱"}, {"w": "折慢幢", "t": "使傲慢者折伏"}, {"w": "折意", "t": "忍性屈情。"}]}, {"meaning": "挫伤,挫折。", "cites": [{"t": "折其骄气。", "b": "宋·苏轼《教战守》"}, {"t": "折北不救。", "b": "《汉书》。颜师古注:“折,挫也。”"}], "words": [{"w": "折食料", "t": "不敢当此厚遇而折了寿数"}, {"w": "折草料", "t": "不敢承受厚遇,怕折寿。"}]}, {"meaning": "折合;抵当。", "cites": [{"t": "每日早上,还折两个钱与你买点心吃。", "b": "《儒林外史》"}], "words": [{"w": "折帕", "t": "以银子代替书帕"}, {"w": "折过", "t": "互相抵消"}, {"w": "折兑", "t": "折算调换"}, {"w": "折充", "t": "折合抵充。"}]}, {"meaning": "损失;减损。", "cites": [{"t": "魏延左冲右突,不得脱身,折兵大半。", "b": "《三国演义》"}], "words": [{"w": "折除", "t": "减损"}, {"w": "折福", "t": "折损福分"}, {"w": "折损", "t": "损伤;损失"}, {"w": "折消", "t": "消除。"}]}, {"meaning": "毁坏。", "cites": [{"t": "是故政举之日,夷关折符,无通其使。", "b": "《孔子·九地》"}]}, {"meaning": "汉字笔画名。", "cites": [{"t": "每作一波,常三过折笔。", "b": "《法书要录》"}], "words": [{"w": "横、竖、撇、点、折", "t": ""}]}, {"meaning": "戏曲名词。元、明杂剧剧本中的一个段落,每剧大都四折 。其中可单独演出的一折,叫“折子戏”。"}, {"meaning": "折叠。", "cites": [{"t": "折叠环复。(往复环绕。)", "b": "明·魏禧《大铁椎传》"}, {"t": "折藏之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "折袖", "t": "袖口翻出一块的服装式样,供习武时穿用"}, {"w": "折本", "t": "古代由长卷折叠成的书本"}, {"w": "折扇", "t": ""}]}, {"meaning": "转折;曲折。", "cites": [{"t": "折遇墙隅。", "b": "蒲松龄《聊斋志异·促织》"}, {"t": "又三四折。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('633wx','抓','1','zhuā','扌','7','','[{"pinyin": "zhuā", "defs": [{"meaning": "(形声。从手,爪声。本义:搔)。"}, {"meaning": "同本义 。人用指甲或带齿的东西或动物用爪在物体上划过。", "cites": [{"t": "杜诗韩集愁来读,似倩麻姑痒处抓。", "b": "唐·杜牧《读韩杜集》"}], "words": [{"w": "抓挠", "t": "用指甲或轻或重地抓搔"}, {"w": "抓心", "t": "形容心里焦急得难受。"}]}, {"meaning": "用手或爪取物。", "cites": [{"t": "夫十围之木,始生而蘖,足可搔而绝,手可擢而抓。", "b": "《文选·枚乘·上书谏吴王》"}], "words": [{"w": "抓子儿", "t": "手中抓物让人猜的一种游戏"}, {"w": "抓挠", "t": "抓取,取得"}, {"w": "想抓救命稻草", "t": ""}]}, {"meaning": "扎缚。", "cites": [{"t": "下面青白间道行缠,抓着裤子口。", "b": "《水浒传》"}], "words": [{"w": "抓角儿", "t": "头顶两旁梳扎的髻"}, {"w": "抓髻", "t": "把发辫盘扎在头上的发式"}, {"w": "抓扎", "t": "扎缚;扎束"}, {"w": "抓缚", "t": "捆扎;扎缚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('634wx','扳','1','bān pān','扌','7','','[{"pinyin": "bān", "defs": [{"meaning": "(形声。从手,反声。本义:拉,引)。"}, {"meaning": "拉;引;拨动。", "cites": [{"t": "日扳仲永环谒于邑人。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "扳罾", "t": "拉罾网捕鱼"}, {"w": "扳倒", "t": "用力拧转使之倒翻;翻倒"}, {"w": "扳闸", "t": ""}]}, {"meaning": "扭转;背转。", "cites": [{"t": "帝谓能丰己,故扳公议立之。", "b": "《新唐书·则天武皇后传》"}], "words": [{"w": "扳回一局棋;扳本", "t": "方言。翻本。"}]}]}, {"pinyin": "pān", "defs": [{"meaning": "(古通“攀”)。"}, {"meaning": "攀援。", "cites": [{"t": "扳,援也。", "b": "《广雅》"}, {"t": "诸大夫扳隐而立之。", "b": "《公羊传·隐公元年》"}], "words": [{"w": "扳援", "t": "攀着他物向上或向前"}, {"w": "扳缘", "t": "攀着他物向上爬"}, {"w": "扳陟", "t": "攀登,抓住或握住某物向上爬"}, {"w": "扳跻", "t": "攀登。"}]}, {"meaning": "结交。", "cites": [{"t": "若是平常经纪人家;没前程的,金老大又不肯扳他了。", "b": "《喻世恒言》"}]}, {"meaning": "攀附。", "cites": [{"t": "近年牛医儿,城社更扳援。", "b": "唐·李商隐《行次西郊作一百韵》"}], "words": [{"w": "扳附", "t": "依附"}, {"w": "扳亲", "t": "攀附姻亲"}, {"w": "扳联", "t": "攀附,牵引"}, {"w": "扳高", "t": "竭力与地位高的人结亲或拉关系"}, {"w": "扳龙", "t": "比喻依附帝王或有权势的人。"}]}, {"meaning": "纠缠。", "cites": [{"t": "质弱易扳缠。", "b": "谢灵运诗"}], "words": [{"w": "扳蔓", "t": "纠缠"}, {"w": "扳缠", "t": "纠缠;牵制"}, {"w": "扳差头", "t": "有意找别人的过失"}, {"w": "扳厚", "t": "拉关系"}, {"w": "扳话接舌", "t": "攀谈搭腔。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('635wx','抡','1','lūn lún','扌','7','','[{"pinyin": "lūn", "defs": [{"meaning": "挥动或挥舞。", "cites": [{"t": "那后生抡着棒又赶入来。", "b": "《水浒全传》"}], "words": [{"w": "抡打", "t": "挥舞"}, {"w": "抡大铁锤;抡荤的", "t": "说下流话。"}]}]}, {"pinyin": "lún", "defs": [{"meaning": "(形声。从手,仑(lún)声。本义:挑选,选拔) 同本义。", "cites": [{"t": "抡,择也。", "b": "《说文》"}, {"t": "凡邦工入山林而抡材不禁。", "b": "《周礼·山虞》"}, {"t": "君抡贤人之后。", "b": "《国语·晋语》。注:“择也。”"}], "words": [{"w": "抡材", "t": "抡才,选拨人才"}, {"w": "抡选", "t": "选拔,挑选"}, {"w": "抡择", "t": "挑选"}, {"w": "抡元", "t": "科举考试中选第一名"}, {"w": "抡魁", "t": "科举考试的第一名。亦指中选第一名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('636wx','扮','1','bàn','扌','7','','[{"pinyin": "bàn", "defs": [{"meaning": "(形声。从手,分声。(fěn)本义:握,并)。"}, {"meaning": "打扮,装扮。", "cites": [{"t": "鲁智深、武松扮作行脚僧。", "b": "《征四寇传》"}], "words": [{"w": "扮作客人;扮女人;扮相;扮戏子", "t": "化妆演戏的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('637wx','抢','1','qiāng qiǎng','扌','7','','[{"pinyin": "qiāng", "defs": [{"meaning": "撞;碰;触。", "cites": [{"t": "飞抢榆枋支遁。", "b": "《庄子·逍遥游》。注:“突也”"}, {"t": "抢,刺也。", "b": "《汉书·扬雄传》注"}, {"t": "以头抢地。", "b": "《战国策·魏策》"}, {"t": "抢呼欲绝。", "b": "《聊斋志异·促织》"}], "words": [{"w": "抢地", "t": "碰触地面。指叩头求饶"}, {"w": "抢地呼天", "t": "以头撞地,悲呼苍天。形容极其伤痛"}, {"w": "抢跪", "t": "屈一膝的半跪礼。"}]}, {"meaning": "推,搡 。"}, {"meaning": "创伤,伤。", "cites": [{"t": "足伤金距缩,头抢花冠翻。", "b": "唐·白居易《赎鸡》诗"}]}, {"meaning": "冲;闯。", "cites": [{"t": "抢出一条吊桶大小,雪花也似蛇来。", "b": "《水浒传》"}]}]}, {"pinyin": "qiǎng", "defs": [{"meaning": "(形声。从手,仓声。本义:抢夺)。"}, {"meaning": "同本义。", "cites": [{"t": "抢夺声。", "b": "《虞初新志·秋声诗自序》"}, {"t": "抢夺耕牛。", "b": "《广东军务记》"}], "words": [{"w": "抢火", "t": "趁火打劫"}, {"w": "抢行", "t": "同业相竞,引申指争爱"}, {"w": "抢了我的东西未必能使他变富;抢案", "t": "抢劫事件,抢劫案件"}, {"w": "抢掳", "t": "抢劫掳掠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('638wx','孝','1','xiào','子','7','','[{"pinyin": "xiào", "defs": [{"meaning": "(形声。从老省,从子。本义:尽心奉养和服从父母)。"}, {"meaning": "同本义。", "cites": [{"t": "孝,善事父母者。", "b": "《说文》"}, {"t": "孝利亲也。", "b": "《墨子经》"}, {"t": "子爱利亲谓之孝。", "b": "《贾子道术》"}, {"t": "慈惠爱亲为孝。协时肇享为孝、五宗安之曰孝,秉德不回曰孝。", "b": "《周书·谥法》"}, {"t": "众之本教曰孝。", "b": "《礼记·祭义》"}, {"t": "夫孝,德之本也。又,天之经也,民之行也。", "b": "《孝经》"}, {"t": "孝,文之本也。", "b": "《国语·周语》"}, {"t": "孝,礼之始也。", "b": "《左传·文公二年》"}, {"t": "中和祗庸孝友。", "b": "《周礼·大司乐》"}, {"t": "靡有不孝,自求伊祜。", "b": "《诗·鲁颂·泮水》"}, {"t": "孝悌之义。", "b": "《孟子·梁惠王上》"}, {"t": "性婉顺有容德,事父母以孝闻。", "b": "《旧唐书》"}], "words": [{"w": "孝弟", "t": "孝顺父母,敬爱兄长"}, {"w": "孝慈", "t": "孝顺父母,慈爱幼弱"}, {"w": "孝养", "t": "孝顺父母,奉养父母。"}]}, {"meaning": "祭,祭祀 。向神或祖先供财物以示感激。", "cites": [{"t": "禹,吾无间然矣。菲饮食而致孝乎鬼神…", "b": "《论语》"}]}, {"meaning": "能继先人之志。", "cites": [{"t": "追孝于前文人。", "b": "《书·文侯之命》"}]}, {"meaning": "居丧。", "cites": [{"t": "后丧母,居丧,哀毁骨立。人云:“崔九作孝,风吹即倒。”", "b": "《北史·崔逞传》"}], "words": [{"w": "孝门", "t": "孝悌之家"}, {"w": "孝家", "t": "居丧守孝的人家"}, {"w": "孝堂", "t": "灵堂。"}]}, {"meaning": "丧服,孝服 。象征悲恸的白色稀纱衣服(尤指中国)或黑色服装、黑纱或黑色标志(尤指西方各民族)。", "cites": [{"t": "原来这婆娘自从药死了武大,那里肯戴孝。", "b": "《水浒传》"}], "words": [{"w": "孝白", "t": "举丧时穿的白色孝服"}, {"w": "穿孝;带孝;挂孝;重孝;热孝;脱孝", "t": ""}]}, {"meaning": "又指办丧事仪式。", "cites": [{"t": "崔九作孝,风吹即倒。", "b": "《北史》"}], "words": [{"w": "吊孝;谢孝", "t": ""}]}, {"meaning": "居丧的人。", "cites": [{"t": "今日与谢孝剧谈一出来。", "b": "《世说新语》。按:时谢玄居父丧,故称谢孝"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('639wx','坎','1','kǎn','土','7','','[{"pinyin": "kǎn", "defs": [{"meaning": "(形声。从土,欠声。本义:坑,穴)。"}, {"meaning": "同本义。", "cites": [{"t": "坎,陷也。", "b": "《说文》"}, {"t": "坎者,陷也。", "b": "《易·序卦》"}, {"t": "其坎深不至于泉。", "b": "《礼记·檀弓下》"}, {"t": "钁其城为坎以先登。", "b": "《资治通鉴·唐纪》"}, {"t": "凿地为坎。", "b": "东汉·班固《汉书·李广苏建传》"}], "words": [{"w": "坎儿", "t": "道路不平。喻指麻烦,变故"}, {"w": "坎止", "t": "遇险难而止"}, {"w": "坎阱", "t": "陷阱"}, {"w": "坎深", "t": "深渊"}, {"w": "坎傺", "t": "住在土窟里。"}]}, {"meaning": "墓穴;墓坑。", "cites": [{"t": "观其葬焉,其坎深不至于泉。", "b": "《礼记·檀弓下》"}]}, {"meaning": "八卦之一,代表水。", "cites": [{"t": "习坎,重险也。", "b": "《易·习坎》"}], "words": [{"w": "坎离", "t": "八卦中的水和火"}, {"w": "坎德", "t": "谦虚之德。《周易》以坎属水,水就下处卑下之地。故有此称谓。"}]}, {"meaning": "光学名词。坎德拉的简称。"}, {"meaning": "掘坑,挖洞。", "cites": [{"t": "坎垣入之,戍者不知也。", "b": "《新唐书·吴少诚传》"}]}, {"meaning": "陷;陷落。", "cites": [{"t": "坎,陷也。", "b": "《易·说卦》"}], "words": [{"w": "坎陷", "t": "塌陷。"}]}, {"meaning": "扣;戴。", "cites": [{"t": "[晁大舍]随把网巾摘下,坎了浩然巾,穿了狐白皮袄,出去接待。", "b": "《醒世姻缘传》"}]}, {"meaning": "忧,恨。", "cites": [{"t": "哀仆夫之坎毒兮,屡离忧而逢患。", "b": "刘向《九叹·离世》"}], "words": [{"w": "坎毒", "t": "愤恨"}, {"w": "坎愁帽", "t": "犯愁,担忧"}, {"w": "坎上愁帽", "t": "犯愁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('640wx','均','1','jūn','土','7','','[{"pinyin": "jūn", "defs": [{"meaning": "(形声。从土,匀声。“匀”亦兼表字义。合起来指土地分配均平。本义:均匀;公平)。"}, {"meaning": "同本义。", "cites": [{"t": "均,平也。", "b": "《说文》"}, {"t": "乃均土地。", "b": "《周礼·小司徒》"}, {"t": "土均。", "b": "《周礼·序官·均人》"}, {"t": "大夫不均。", "b": "《诗·小雅·北山》"}, {"t": "而患不均。", "b": "《论语·季氏》"}, {"t": "盖均无贫。", "b": ""}, {"t": "性行淑均。", "b": "诸葛亮《出师表》"}, {"t": "霜露所均。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "有无不均。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "均壹", "t": "公平专一"}, {"w": "均浃", "t": "平均而普遍"}, {"w": "均人", "t": "官名。周礼地官之属。掌平均土地征役"}, {"w": "均徧", "t": "公平周徧"}, {"w": "均辨", "t": "公平"}, {"w": "均平", "t": "均匀公平"}, {"w": "均遍", "t": "均匀周遍"}, {"w": "均种", "t": "指种植的间隔均匀适度。"}]}, {"meaning": "等同,相同。", "cites": [{"t": "德虽如舜,不免形均。", "b": "《荀子·君子》"}], "words": [{"w": "均权", "t": "权势相等"}, {"w": "均科", "t": "同等之罪"}, {"w": "均敌", "t": "犹对等"}, {"w": "均礼", "t": "行对等之礼。"}]}, {"meaning": "使…同样;平分。", "cites": [{"t": "我行法,当等贵贱,均贫富。", "b": "《续资治通鉴》"}], "words": [{"w": "均摊;均贫富", "t": ""}]}, {"meaning": "衡量,比较。", "cites": [{"t": "均之二策。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "均工", "t": "按日计酬。"}]}, {"meaning": "皆,都,全部。", "cites": [{"t": "均欲奋勇出城。", "b": "《广东军务记》"}, {"t": "均被火烧。", "b": ""}], "words": [{"w": "诸事均已办妥", "t": ""}]}, {"meaning": "一种制造陶器所用的转轮,又称“陶旋轮”,后喻国政。", "cites": [{"t": "秉国之均。", "b": "《诗·小雅·节南山》"}, {"t": "犹立朝夕于运均之上。", "b": "《管子·七法》"}]}, {"meaning": "中国水名 。汉水支流之一,上、中游为河南淅河,至河南淅川县与丹水合为均水,也称“丹江”。"}, {"meaning": "中国州名 。今为湖北省均县。"}, {"meaning": "中国宋代瓷窑名,在今河南省禹县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('641wx','抑','1','yì','扌','7','','[{"pinyin": "yì", "defs": [{"meaning": "(本写作“归”。会意。小篆字形,象用手抑人使跽。本义:按,向下压)。"}, {"meaning": "同本义。", "cites": [{"t": "抑之欲其奥。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "抑按", "t": "按压"}, {"w": "抑首", "t": "按其首"}, {"w": "抑搔", "t": "按摩抓搔"}, {"w": "抑扬", "t": "按下与上举。"}]}, {"meaning": "抑制。", "cites": [{"t": "抑其兼并。", "b": "清·洪亮吉《治平篇》"}, {"t": "不可遏抑。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "抑勒", "t": "压制被扣"}, {"w": "抑情", "t": "克制感情"}, {"w": "抑引", "t": "抑制情欲而导之以善"}, {"w": "抑末", "t": "抑制商贾"}, {"w": "抑志", "t": "抑制自己的志向"}, {"w": "抑枉", "t": "抑制邪辟"}, {"w": "抑削", "t": "抑制削弱"}, {"w": "抑挫", "t": "抑制折挫。"}]}, {"meaning": "贬。", "cites": [{"t": "教之春秋,而为之耸善而抑恶焉。", "b": "《国语·楚语上》"}], "words": [{"w": "抑卑", "t": "贬低"}, {"w": "抑贬", "t": "贬低"}, {"w": "抑退", "t": "黜退;贬退"}, {"w": "抑损", "t": "贬低;贬损"}, {"w": "抑黜", "t": "亦作“抑绌”。贬废;排斥。"}]}, {"meaning": "强行;强迫。", "cites": [{"t": "乙卯,诏诸路散青苗钱,禁抑配。", "b": "《宋史·神宗纪二》"}], "words": [{"w": "抑配", "t": "强行分配"}, {"w": "抑勒", "t": "强逼;压制"}, {"w": "抑逼", "t": "强迫"}, {"w": "抑留", "t": "强行留住"}, {"w": "抑掠", "t": "强夺"}, {"w": "抑买", "t": "强行购买"}, {"w": "抑夺", "t": "剥夺;强行夺取"}, {"w": "抑籴", "t": "强行收购粮食。"}]}, {"meaning": "或是,还是。", "cites": [{"t": "抑其无取。", "b": "唐·柳宗元《柳河东集》"}, {"t": "抑未死耶。", "b": "清·全祖望《梅花岭记》"}, {"t": "吾能之乎?抑汝能之乎?", "b": "清·林觉民《与妻书》"}]}, {"meaning": "但是;不过。", "cites": [{"t": "抑愈所谓。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "抑不知生。", "b": ""}, {"t": "抑又有难。", "b": ""}], "words": [{"w": "抑岂", "t": "难道"}, {"w": "抑且", "t": ""}]}, {"meaning": "而且。", "cites": [{"t": "非独晓其文,抑亦深其义。", "b": "《太平广记》"}], "words": [{"w": "抑且", "t": "而且。"}]}, {"meaning": "表示推测,可译为“或许”、“也许”。", "cites": [{"t": "抑本其成。", "b": "宋·欧阳修《新五代史·伶官传·序》"}]}, {"meaning": "用在句首,无义。", "cites": [{"t": "抑又闻之。", "b": "唐·柳宗元《柳河东集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('642wx','抛','1','pāo','扌','7','','[{"pinyin": "pāo", "defs": [{"meaning": "(形声。本义:丢弃)。"}, {"meaning": "同本义。", "cites": [{"t": "管儿不作供奉儿,抛在东都双鬓丝。", "b": "唐·元稹《琵琶歌》"}, {"t": "纸片抛落。", "b": "《聊斋志异·促织》"}], "words": [{"w": "抛漾", "t": "抛弃"}, {"w": "抛撒", "t": "抛弃;脱落;洒落"}, {"w": "抛撇", "t": "抛开;撇弃"}, {"w": "抛官", "t": "辞官,弃官"}, {"w": "抛除", "t": "丢弃,抛掉。"}]}, {"meaning": "抛,掷。", "cites": [{"t": "忆昔花间相见后,只凭纤手,暗抛红豆。", "b": "唐·欧阳炯《贺明朝》"}], "words": [{"w": "抛砖引玉;抛丸", "t": "杂技之一。两手上下抛接多个弹丸不使落地"}, {"w": "抛扔", "t": "投掷"}, {"w": "抛珠滚玉", "t": "比喻流泪"}, {"w": "抛声炫俏", "t": "故意声张卖弄"}, {"w": "抛泊", "t": "抛锚停泊。"}]}, {"meaning": "秽物一堆为一抛。也作“泡”。", "cites": [{"t": "像你这尖嘴猴腮,也该撒抛尿自己照照!", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('643wx','投','1','tóu','扌','7','','[{"pinyin": "tóu", "defs": [{"meaning": "(会意。从手,从殳。殳(shū),古兵器。合起来表示手拿兵器投掷。本义:投掷)。"}, {"meaning": "同本义。", "cites": [{"t": "投,擿(掷)也。", "b": "《说文》"}, {"t": "受其书而投之。", "b": "《左传·昭公五年》"}, {"t": "投我以桃。", "b": "《诗·大雅·柳》"}, {"t": "毋投与狗骨。", "b": "《礼记·曲礼上》"}, {"t": "投之深渊些。", "b": "《楚辞·招魂》"}, {"t": "欲投鼠而忌器。", "b": "《汉书·贾谊传》"}, {"t": "以肉投馁虎。", "b": "《史记·魏公子列传》"}, {"t": "作投击势。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "投以骨。", "b": "《聊斋志异·狼三则》"}, {"t": "复投之。", "b": ""}, {"t": "孤羊投群狼。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "投兵", "t": "向人投掷兵刃。谓诛杀"}, {"w": "投注", "t": "投掷"}, {"w": "投食", "t": "投掷食物"}, {"w": "投绂", "t": "弃去印绶。"}]}, {"meaning": "跳进去;投入(专指自杀行为)。", "cites": [{"t": "务光因自投于河。", "b": "《韩非子·说林上》"}, {"t": "有过于江上者,见人方引婴儿而欲投之江中。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "投河;投江;投井", "t": ""}]}, {"meaning": "投弃,抛弃。", "cites": [{"t": "投诸渤海之尾。", "b": "《列子·汤问》"}, {"t": "平生怀仗剑,慷慨即投笔。", "b": "刘希夷《从军行》"}, {"t": "停杯投箸。", "b": "唐·李白《行路难》"}, {"t": "有怀投笔,慕宗悫之长风。", "b": "王勃《滕王阁序》"}, {"t": "弃甲投戈。", "b": "《广东军务记》"}], "words": [{"w": "投簪", "t": "丢掉固定帽子的簪子。比喻弃官"}, {"w": "投传", "t": "投弃符信"}, {"w": "投檄", "t": "投弃征召的文书"}, {"w": "投纶", "t": "投弃钓具"}, {"w": "投笔", "t": "弃文而就他业"}, {"w": "投策", "t": "弃鞭;弃杖"}, {"w": "投畀", "t": "抛弃。"}]}, {"meaning": "投奔。前往依靠别人。", "cites": [{"t": "欲往投之。", "b": "《资治通鉴》"}, {"t": "欲投吴巨。", "b": ""}], "words": [{"w": "投赴", "t": "投奔"}, {"w": "投止", "t": "投奔托足;投宿。"}]}, {"meaning": "投宿,临时住宿。", "cites": [{"t": "暮投石壕村。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "投驿", "t": "投宿驿站"}, {"w": "投归", "t": "投宿"}, {"w": "投到", "t": "投宿"}, {"w": "投暮", "t": "傍晚。"}]}, {"meaning": "顿,用力往下踩。", "cites": [{"t": "盖一举手,一投足之劳也。", "b": "韩愈《应科目时与人书》"}]}, {"meaning": "投入,投进。", "cites": [{"t": "投之江中。《吕氏春秋·察今》", "b": ""}, {"t": "投江死。", "b": "清·全祖望《梅花岭记》"}, {"t": "投火死。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "投壶的省称。中国古代宴会时的游戏。设特制之壶,宾主依次投矢其中,中多者为胜,负者饮。", "cites": [{"t": "侍投则拥矢。", "b": "《礼记·少仪》"}]}, {"meaning": "骰子。赌具 。骨制,成正立方体,六面分别刻一点至六点之数,掷之以决胜负。点着色,故也称“色子”。"}, {"meaning": "表示方位、方向,相当于“朝”、“向”。", "cites": [{"t": "拨马投西便走。", "b": "《三国演义》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('644wx','坟','1','fén','土','7','','[{"pinyin": "fén", "defs": [{"meaning": "(形声。从土,贲(bēn)声。本义:大防)。"}, {"meaning": "同本义。", "cites": [{"t": "坟,大防。", "b": "《尔雅·释丘》"}, {"t": "坟莫大于河坟。", "b": "《尔雅释地》"}, {"t": "遵彼汝坟。", "b": "《诗·周南·汝坟》。传:“大防也。”"}]}, {"meaning": "注:“或曰河坟,汝坟、淮坟也。”。"}, {"meaning": "土堆。", "cites": [{"t": "崇坟夷靡。", "b": "潘岳《射雉赋》。注:“今呼为塘。”"}, {"t": "登大坟以远望兮。", "b": "屈原《九章·哀郢》"}], "words": [{"w": "坟家", "t": "用土堆成的坟包。"}]}, {"meaning": "水边;沿河的高地。", "cites": [{"t": "坟,地大也,青幽之间,凡土而高大者谓之坟。", "b": "《方言》"}, {"t": "背坟衍之广陆兮。", "b": "王粲《登楼赋》"}, {"t": "遵彼汝坟,伐其条枚。", "b": "《诗·周南·汝坟》"}, {"t": "坟延者六施,六七四十二尺而至於泉。", "b": "《管子·地员》"}]}, {"meaning": "特指坟堆,坟墓。", "cites": [{"t": "墳,墓也。", "b": "《说文》。按,此字本训大防也。"}, {"t": "坟,冢。秦晋之间谓之坟。", "b": "《方言十三》。注:“坟取名于大防也。”"}, {"t": "古也,墓而不坟。", "b": "《礼记·檀弓》。注:“土之高者谓之坟。”"}, {"t": "出郭门直视,但见近与坟。", "b": "《古诗十九首》"}, {"t": "古也墓而不坟。", "b": "《礼记·檀弓上》"}, {"t": "不治坟,欲为省。", "b": "《史记·文帝本纪》"}, {"t": "吾往河阳省坟墓。", "b": "唐·韩愈《祭十二郎文》"}], "words": [{"w": "坟兆", "t": "坟墓之间的界域"}, {"w": "坟陵", "t": "帝王的陵墓。"}]}, {"meaning": "古代典籍名。", "cites": [{"t": "是能读三坟、五典、八索、九丘。", "b": "《左传·昭公十二年》"}], "words": [{"w": "坟典", "t": "坟策、坟籍、坟素,都泛指古书,古籍。"}]}, {"meaning": "起土堆;筑坟。", "cites": [{"t": "渐就壤坟。", "b": "《后汉书·明帝纪》。注:“起也。”"}], "words": [{"w": "坟土", "t": "墓葬。"}]}, {"meaning": "划分。", "cites": [{"t": "地方九则,何以坟之?", "b": "《楚辞·天问》"}]}, {"meaning": "大。", "cites": [{"t": "牂羊坟首。", "b": "《诗·小雅·苕之华》"}, {"t": "共坟烛庭燎。", "b": "《周礼·司烜氏》。注:“大也。”"}], "words": [{"w": "坟烛", "t": "大火炬"}, {"w": "坟首", "t": "大头"}, {"w": "坟仓", "t": "大粮仓。"}]}, {"meaning": "顺从的。", "cites": [{"t": "坟然若一父之子,若一家之实,义礼明也。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('645wx','坑','1','kēng','土','7','','[{"pinyin": "kēng", "defs": [{"meaning": "(形声。从土,亢声。本义:地面上凹下去的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "坑,堑也,壑也。", "b": "《玉篇》"}, {"t": "或被坑水冲淹。", "b": "《广东军务记》"}], "words": [{"w": "刨个坑;挖坑;坑阱", "t": "泛指深坑"}, {"w": "坑坎", "t": "指地面高低不平;洼地;坑穴。"}]}, {"meaning": "矿穴,矿场。", "cites": [{"t": "其天下自五岭以北,见捋银坑,并宜禁断。", "b": "《旧唐书·食货志上》"}], "words": [{"w": "坑户", "t": "唐宋以来采掘金属矿的在籍专业户"}, {"w": "坑冶", "t": "金属矿的开采与冶炼"}, {"w": "坑探", "t": "开挖坑道探明矿藏的情况。"}]}, {"meaning": "陷害。", "cites": [{"t": "则被你坑杀人燕侣莺俦。", "b": "《窦娥冤》"}], "words": [{"w": "坑闪", "t": "坑害抛弃"}, {"w": "坑陷", "t": "坑害;陷害"}, {"w": "坑蒙", "t": "坑害蒙骗。"}]}, {"meaning": "活埋。", "cites": [{"t": "于是楚军夜击坑秦卒二十余人。", "b": "《史记·项羽本纪》"}], "words": [{"w": "坑降", "t": "活埋已经投降的兵将"}, {"w": "坑杀", "t": "活埋"}, {"w": "坑戮", "t": "坑杀;活埋"}, {"w": "焚书坑儒", "t": ""}]}, {"meaning": "损人。", "cites": [{"t": "我并没得罪人,为甚么这么坑我?", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('646wx','抗','1','kàng','扌','7','','[{"pinyin": "kàng", "defs": [{"meaning": "(形声。从手,亢声。本义:抵抗,抵御)。"}, {"meaning": "同本义。", "cites": [{"t": "抗,扦也。", "b": "《说文》"}, {"t": "抗,御也。", "b": "《小尔雅·广言》"}, {"t": "抗木横一缩。", "b": "《仪礼·既夕礼》"}, {"t": "非抗于九国之师也。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "抗木", "t": "旧时所用的葬具。在棺木之上覆盖一席,用以防御尘土"}, {"w": "抗力", "t": "抵抗力"}, {"w": "抗犯", "t": "抵抗与进犯"}, {"w": "抗玩", "t": "玩忽抗命"}, {"w": "抗质", "t": "谓劫持人质以相抗"}, {"w": "抗矫", "t": "矫情抗俗,高蹈。"}]}, {"meaning": "抗拒;拒绝。", "cites": [{"t": "安能抗此难乎。", "b": "《资治通鉴》"}, {"t": "抗辞慷慨。", "b": "宋·文天祥《指南录后序》"}, {"t": "欲出力助上以抗之。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "抗拒", "t": "顶撞;违抗并拒绝"}, {"w": "抗违", "t": "抗拒,违背"}, {"w": "抗租", "t": "抗缴地租"}, {"w": "抗逆", "t": "违抗,抗拒"}, {"w": "抗斗", "t": "反抗斗争。"}]}, {"meaning": "匹敌,抗衡。", "cites": [{"t": "独莲花与抗耳。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "抗横", "t": "抗衡"}, {"w": "抗行", "t": "并行;抗衡"}, {"w": "抗美", "t": "抗衡媲美"}, {"w": "抗库", "t": "并立,抗衡。"}]}, {"meaning": "举起。", "cites": [{"t": "抗皓手而清歌。", "b": "曹植《七启》"}], "words": [{"w": " 抗力", "t": "力能举起"}, {"w": "抗手", "t": "举手为礼"}, {"w": "抗足", "t": "投足,举足"}, {"w": "抗兵", "t": "举兵。"}]}, {"meaning": "高;大", "cites": [{"t": "谪戍之众,非抗于几国之师也。", "b": "汉·贾谊《过秦论》"}, {"t": "以犯上为亢。", "b": "《韩非子·问辩》"}], "words": [{"w": "抗世", "t": "高世,超乎世俗"}, {"w": "抗殿", "t": "谓高筑殿堂或指高大的殿堂。"}]}, {"meaning": "刚正不阿;高尚。", "cites": [{"t": "若贤人之美辞,忠臣之抗直。", "b": "萧统《文选序》"}], "words": [{"w": "抗迈", "t": "俊杰出群,高超不凡"}, {"w": "抗行", "t": "高尚的德行"}, {"w": "抗迹", "t": "高洁不群的行为"}, {"w": "抗直", "t": "坦率刚直"}, {"w": "抗词", "t": "直言陈说。亦指严厉正直的言辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('647wx','坊','1','fāng fáng','土','7','','[{"pinyin": "fāng", "defs": [{"meaning": "(形声。从土,方声。本义:城市中街市里巷的通称)。"}, {"meaning": "古代把一个城邑划分为若干区,通称为坊。", "cites": [{"t": "两京及州县之郭内为坊,郊外为村。", "b": "《唐元典》"}, {"t": "坊隅众人,慌忙拢来。", "b": "《水浒传》"}], "words": [{"w": "坊隅", "t": "街巷,街坊"}, {"w": "坊厢", "t": "古代城市区划,城中曰坊,近城曰厢"}, {"w": "坊市", "t": "街市"}, {"w": "坊郭", "t": "城郭市街。"}]}, {"meaning": "官署名 。隋代太子官署有左右坊、门下坊、典书坊等,唐以后易为太子左春坊、右春坊。", "cites": [{"t": "明年春,大疫,为病坊,处疾病之无归者。", "b": "宋·曾巩《越州赵公救灾记》"}], "words": [{"w": "坊局", "t": "詹事府属下的左、右春坊和司经局的合称。"}]}, {"meaning": "铸造器物的土模。"}, {"meaning": "店铺。", "cites": [{"t": "茶坊每五更点灯博易。", "b": "孟元老《东京孟华录》"}], "words": [{"w": "坊肆", "t": "商店"}, {"w": "坊店", "t": "店铺"}, {"w": "坊贾", "t": "书商。"}]}, {"meaning": "别屋;专用的房舍。", "cites": [{"t": "里边有十数家,都是开坊子吃衣饭的。", "b": "《金瓶梅词话》"}], "words": [{"w": "坊子", "t": "妓院;私娼的屋子"}, {"w": "坊陌", "t": "妓女居所名"}, {"w": "坊曲", "t": "唐代妓女居住的地方。也指小街曲巷。"}]}, {"meaning": "古州名  在今陕西省黄陵县。"}]}, {"pinyin": "fáng", "defs": [{"meaning": "堤防。", "cites": [{"t": "祭坊与水庸,事也。", "b": "《礼记·郊特牲》"}, {"t": "大为之坊,民犹逾之。", "b": "《礼记·坊记》"}, {"t": "长城钜坊,足以为塞。", "b": "《战国策·秦策》"}]}, {"meaning": "小手工业者的工作场所。", "cites": [{"t": "小号店在这里,后边还有栈房,还有作坊。", "b": "《老残游记》"}], "words": [{"w": "染坊;粉坊;磨坊;碾坊;油坊;谷坊", "t": ""}]}, {"meaning": "防止;防范。", "cites": [{"t": "故君子礼以坊德,刑以坊淫,命以坊欲。", "b": "《礼记·坊记》"}]}]}]','jingmo-wenyan');
