('648wx','抖','1','dǒu','扌','7','','[{"pinyin": "dǒu", "defs": [{"meaning": "(形声。从手,斗声。本义:抖擞)。"}, {"meaning": "振动;甩动 )。"}, {"meaning": "振作。", "cites": [{"t": "抖起精神", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('649wx','护','1','hù','扌','7','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从言,蒦(huó)声。本义:保卫;保护)。"}, {"meaning": "同本义。", "cites": [{"t": "吏护还之乡。", "b": "唐·柳宗元《童区寄传》"}, {"t": "吾欲护汝。", "b": "明·魏禧《大铁椎传》"}, {"t": "从我杀贼护家室。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "贯铁絙护之。", "b": ""}], "words": [{"w": "护队", "t": "行军所设防卫的军队"}, {"w": "护藏", "t": "保护经藏"}, {"w": "护梁", "t": "城楼上作护卫用的横梁"}, {"w": "护镜", "t": "护心镜。衣甲上用以防护前心和后心的铜镜。"}]}, {"meaning": "爱护。", "cites": [{"t": "备极护爱。", "b": "《聊斋志异·促织》"}], "words": [{"w": "护书", "t": "收放文书用的长方形木匣子"}, {"w": "护头", "t": "小孩子不肯剃头发"}, {"w": "护槽", "t": "马吃草时,人难接近。"}]}, {"meaning": "袒护;包庇。", "cites": [{"t": "谨护其失。", "b": "清·刘开《问说》"}], "words": [{"w": "护庇", "t": "袒护;包庇"}, {"w": "护相容隐", "t": "庇护容忍"}, {"w": "护失", "t": "袒护自己的过错。"}]}, {"meaning": "监视;监督。", "cites": [{"t": "护,救视也。", "b": "《说文》"}, {"t": "有白马将出护其兵。李广上马车十余骑奔射杀胡白马将。", "b": "《史记》"}]}, {"meaning": "救助。", "cites": [{"t": "高祖为布衣时,何数以吏事护高祖。", "b": "《史记·萧相国世家》"}]}, {"meaning": "总领。", "cites": [{"t": "乐毅于是并护赵、楚、韩、魏、燕之兵以伐齐,破之济西。", "b": "《史记·乐毅传》"}]}]}]','jingmo-wenyan');
