('650wx','壳','1','ké qiào','士','7','','[{"pinyin": "ké", "defs": [{"meaning": "坚硬的外皮", "words": [{"w": "脑壳", "t": ""}, {"w": "贝壳儿", "t": ""}, {"w": "壳子", "t": "外壳"}, {"w": "壳族", "t": "贝类、介类等有壳动物"}, {"w": "壳菜", "t": "称有壳的海贝"}, {"w": "壳果", "t": "带硬壳的果品。"}]}]}, {"pinyin": "qiào", "defs": [{"meaning": "坚硬的外皮。", "cites": [{"t": "蠃蚌脱壳。", "b": "〖英〗赫胥黎著、严复译《天演论》"}], "words": [{"w": "躯壳", "t": ""}, {"w": "甲壳", "t": ""}, {"w": "地壳", "t": ""}, {"w": "金蝉脱壳", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('651wx','志','1','zhì','心','7','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从心,士声。战国文字,从心之,之亦声。意为心愿所往。本义:志气,意愿:心之所向,未表露出来的长远而大的打算)。"}, {"meaning": "同本义。", "cites": [{"t": "志,意也。", "b": "《说文》"}, {"t": "志,德义之府也。", "b": "《国语·晋语》"}, {"t": "夫志,气之帅也。", "b": "《孟子》"}, {"t": "在心为志。", "b": "《毛诗序》"}, {"t": "思虑为志。", "b": "《春秋·说题辞》"}, {"t": "志者,臧也。", "b": "《荀子·解蔽》"}, {"t": "志者,欲之使也。", "b": "《鬼谷子·阴府》"}, {"t": "诗言志,歌永言。", "b": "《书·舜典》"}, {"t": "父在观其志。", "b": "《论语·学而》"}, {"t": "燕雀安知鸿鹄之志哉!", "b": "《史记·陈涉世家》"}, {"t": "小子安知壮士志哉!", "b": "《后汉书·班超传》"}, {"t": "又曰“士志于道而耻恶衣恶食者,未足与议也”。", "b": "宋·司马光《训俭示康》"}, {"t": "身将老寂寞,志欲死闲暇。", "b": "唐·韩愈《县斋有怀》"}], "words": [{"w": "志志诚诚", "t": "真心实意"}, {"w": "志局", "t": "意志和器量"}, {"w": "志干", "t": "意志坚强"}, {"w": "志意", "t": "意志"}, {"w": "志坚如钢;有志者事竟成;志分", "t": "志向与才分"}, {"w": "志虑", "t": "志向思虑"}, {"w": "志抱", "t": "志向和抱负"}, {"w": "志尚", "t": "志向;理想"}, {"w": "志况", "t": "志趣"}, {"w": "志好", "t": "志趣好尚"}, {"w": "志略", "t": "志气谋略"}, {"w": "志局", "t": "志气器量"}, {"w": "志介", "t": "志气和节操"}, {"w": "志高气扬", "t": "志气高昂而自得。"}]}, {"meaning": "心情。", "cites": [{"t": "志不可满,乐不可极。", "b": "《礼记·曲礼上》"}], "words": [{"w": "志情", "t": "心情"}, {"w": "志意", "t": "志愿;思想;精神"}, {"w": "志识", "t": "思想意识;见解"}, {"w": "志度", "t": "气度"}, {"w": "志思", "t": "情志,怀抱。"}]}, {"meaning": "神志。", "cites": [{"t": "罔兮不乐,怅然失志。", "b": "《神女赋》"}]}, {"meaning": "旗帜。", "cites": [{"t": "卫宫设兵张旗志。", "b": "《史记·叔孙通传》"}, {"t": "沛公以周昌为职志。", "b": "《史记·张丞相传》。索隐:“志,旗帜也。”"}, {"t": "不用麾志,举矛为行伍。", "b": "《华阳国志》"}]}, {"meaning": "皮肤上生的班痕", "cites": [{"t": "约左目重瞳子,腰有紫志。", "b": "《梁书》"}]}, {"meaning": "有志;立志;专心。", "cites": [{"t": "吾十有五而志于学。", "b": "《论语·为政》"}], "words": [{"w": "志于学", "t": "专心求学"}, {"w": "志道", "t": "有志于道"}, {"w": "志古", "t": "笃信古道。"}]}, {"meaning": "记着。", "cites": [{"t": "疆志而用命。", "b": "《国语·晋语七》"}, {"t": "一经目辄志于心。", "b": "《新唐书·褚亮传》"}, {"t": "博闻彊志。(知识广博,记诵的事多。闻,学识。彊,同“强”。志,记。)", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "永志不忘", "t": ""}]}, {"meaning": "向慕。", "cites": [{"t": "老生惜岁月,烈士志功名。", "b": "陆游《感秋》"}]}, {"meaning": "记载,记录。", "cites": [{"t": "《齐谐》者,志怪者也。", "b": "《庄子·逍遥游》。释文:“志,记也。”"}, {"t": "掌天星,以志星辰日月之变动。", "b": "《周礼·春官·保章氏》"}, {"t": "就是张华的《博物志》,也不过志其一二。", "b": "《醒世恒言》"}], "words": [{"w": "志书", "t": "记事的书"}, {"w": "志乘", "t": "记载历史的书"}, {"w": "杂志", "t": ""}]}, {"meaning": "叙述。", "cites": [{"t": "汝将行,盍志而子美德乎?", "b": "《荀子·尧问》"}]}, {"meaning": "(形声。言形志声。本义:记忆)。"}, {"meaning": "同本义。", "cites": [{"t": "誌,记誌也。", "b": "《说文新附》"}, {"t": "誌,记也。", "b": "《字诂》"}, {"t": "亮少警敏,博见图史,一经目辄志于心。", "b": "《新唐书》"}], "words": [{"w": "志而不忘", "t": "牢记心中,永远不会忘怀。"}]}, {"meaning": "记录。", "cites": [{"t": "太古之事灭矣,孰志之哉?", "b": "《列子》"}], "words": [{"w": "志异", "t": "记载奇异之事"}, {"w": "志怪", "t": "记载怪异之事"}, {"w": "志记", "t": "史书中的志和记。"}]}, {"meaning": "做记号。", "cites": [{"t": "既出,得其船,便扶向路,处处志之。", "b": "晋·陶潜《桃花源记》"}]}, {"meaning": "又。", "cites": [{"t": "寻向所志。", "b": ""}]}, {"meaning": "标记;记号。", "cites": [{"t": "襄阳土俗,邻居种桑树于界上为志。", "b": "《南齐书·韩孙伯传》"}], "words": [{"w": "志桩", "t": "刻有尺度的木桩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('652wx','块','1','kuài','土','7','','[{"pinyin": "kuài", "defs": [{"meaning": "(形声。从土,鬼声。字本作“凷”,是个会意字,表示土块装在筐器之中。后来写作“塊”,变成了形声字,现在简化为“块”。本义:土块)。"}, {"meaning": "同本义。", "cites": [{"t": "凷,墣也。从土,一屈象形。", "b": "《说文》。张舜徽注:“凵象盛土之器,而土在其中也。”"}, {"t": "凷,坚土也。", "b": "《一切经音义》引《说文》"}, {"t": "寝苫枕块。", "b": "《仪礼·丧服传》。释文:“土也。”"}, {"t": "大块噫气。", "b": "《庄子·齐物论》"}, {"t": "大块禀群生。", "b": "《文选 ·张华诗》。注:“谓地也。”"}, {"t": "石块丛起则历。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "块阜", "t": "小土丘"}, {"w": "块苏", "t": "土块和草堆。比喻卑微"}, {"w": "块山", "t": "土墙。"}]}, {"meaning": "整体的一部分。", "cites": [{"t": "人运大石一块。", "b": "清·邵长衡《青门剩稿》"}], "words": [{"w": "一块布;一块石头;一块煤;一块方糖;一块肥皂;一块冰砖", "t": ""}]}, {"meaning": "孤独;孑然。", "cites": [{"t": "块然独立天地间。", "b": "《荀子·性恶》"}, {"t": "块然独立,则哀愤两集。", "b": "刘琨《答卢谌书》"}]}, {"meaning": "又如;块坐(独坐);块然(孤独;安适自得的样子);块独(孤独)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('653wx','扭','1','niǔ','扌','7','','[{"pinyin": "niǔ", "defs": [{"meaning": "(形声。从手,丑声。本义:用手拧)。"}, {"meaning": "揪住。", "cites": [{"t": "大众见他二人扭在一起。", "b": "《官场现形记》"}], "words": [{"w": "扭殴", "t": "揪打"}, {"w": "扭拽", "t": "拉扯"}, {"w": "扭拽", "t": "揪住"}, {"w": "扭搜", "t": "硬挤。"}]}, {"meaning": "扭动;摇摆。", "cites": [{"t": "只消把腰儿扭一扭就过去了。", "b": "《西游记》"}], "words": [{"w": "扭扭屹屹", "t": "躯体扭动的样子"}, {"w": "扭扭捏捏", "t": "身体摆动的样子"}, {"w": "扭秧歌", "t": "跳秧歌舞"}, {"w": "扭搐", "t": "抽搐"}, {"w": "扭造", "t": "做作;不自然。"}]}, {"meaning": "拧伤筋骨。", "cites": [{"t": "可扭了腰没有。", "b": "《红楼梦》"}], "words": [{"w": "扭筋", "t": "因用力过猛,导致筋肉受挫伤。"}]}, {"meaning": "争执;违拗。", "cites": [{"t": "那里扭得过他。", "b": "《水浒全传》"}], "words": [{"w": "扭别", "t": "别扭,不顺遂"}, {"w": "别扭", "t": "不顺心;难对付;意见不相投"}, {"w": "胳膊扭不过大腿", "t": ""}]}, {"meaning": "掉转,转动。", "cites": [{"t": "杨志听得弓弦响,扭回身。", "b": "《水浒全传》"}], "words": [{"w": "扭头向后看;一扭身跑了", "t": ""}]}, {"meaning": "手铐。", "cites": [{"t": "抱钳扭,徙幽裔。", "b": "《后汉书·蔡邕传论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('654wx','声','1','shēng','士','7','','[{"pinyin": "shēng", "defs": [{"meaning": "(形声。从耳,殸(qìng)声。“殸”是古乐器“磬”的本字,“耳”表示听。本义:声音;声响)。"}, {"meaning": "同本义。", "cites": [{"t": "声,音也。", "b": "《说文》"}, {"t": "感于物而动,故形于声。", "b": "《礼记·乐记》"}, {"t": "声依永律和声。", "b": "《虞书》"}, {"t": "凡声阳也。", "b": "《礼记·郊特牲》"}, {"t": "苍蝇之声。", "b": "《诗·齐风·鸡鸣》"}, {"t": "有闻无声。", "b": "《诗·小雅·车攻》"}, {"t": "闻水声,如鸣佩环,心乐之。", "b": "柳宗元《永州八记》"}, {"t": "寻声暗问弹者谁?琵琶声停欲语迟。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "百姓闻王钟鼓之声,管龠之音。", "b": "《孟子·梁惠王下》"}], "words": [{"w": "声叉", "t": "声音不正常"}, {"w": "声嘶", "t": "声音破哑"}, {"w": "声如洪钟", "t": "形容人语音响亮,有如大钟的声音"}, {"w": "声振林木", "t": "形容歌声的高亢清远,足以使林木摇动"}, {"w": "声动梁尘", "t": "形容歌声洪亮动人。"}]}, {"meaning": "音乐;诗歌。", "cites": [{"t": "不大声以色。", "b": "《诗·大雅·皇矣》"}, {"t": "赵王窃闻秦王善为秦声。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "声音不足听于耳与?", "b": "《孟子·梁惠王下》"}]}, {"meaning": "声望,声名(名声)。", "cites": [{"t": "文王有声。", "b": "《诗·大雅·文王有声》"}, {"t": "故声闻过情,君子耻之。", "b": "《孟子·离娄下》"}, {"t": "臣闻古人有辞天下而无恨色者,臣闻其声,于王而见其实。", "b": "《吕氏春秋·过理》"}], "words": [{"w": "声气", "t": "名声;名气"}, {"w": "声名煊赫", "t": "名声显赫"}, {"w": "声芳", "t": "美好的声名"}, {"w": "声施", "t": "名声流传"}, {"w": "声烈", "t": "显赫的名望"}, {"w": "声名人", "t": "有名望的人"}, {"w": "声位", "t": "声望与地位。"}]}, {"meaning": "口信;消息;传说。", "cites": [{"t": "界上亭长寄声谢我,何以不为致问?", "b": "《汉书·赵广汉传》"}], "words": [{"w": "声传", "t": "传闻之事"}, {"w": "声论", "t": "犹舆论"}, {"w": "声闻", "t": "音讯,讯息。"}]}, {"meaning": "声威;声势。", "cites": [{"t": "声威天下。", "b": "《战国策·齐策》。注:“势也。”"}], "words": [{"w": "声教", "t": "声威与教化"}, {"w": "声焰", "t": "声势气焰"}, {"w": "声振寰宇", "t": "名声威势振动天下。形容声威极盛"}, {"w": "声乡", "t": "犹声势"}, {"w": "声张势厉", "t": "声势煊赫"}, {"w": "声势重灼", "t": "声威气势逼人"}, {"w": "声势赫奕", "t": "声威气势盛大显赫"}, {"w": "声势汹汹", "t": "形容气势盛大的样子。多含贬义。"}]}, {"meaning": "言语,口音。", "cites": [{"t": "与人罕言,语类楚声。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "声嗽", "t": "言语。"}]}, {"meaning": "声称,宣扬。", "cites": [{"t": "吾社之行为士先者,为之声义。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "声云", "t": "犹声言"}, {"w": "声兵", "t": "宣布出兵"}, {"w": "声述", "t": "声明陈述"}, {"w": "声叙", "t": "明白陈述。"}]}, {"meaning": "听。", "cites": [{"t": "目不得而色,耳不得而声,口鼻不得而臭味。", "b": "清·谭嗣同《仁学》"}]}, {"meaning": "表示声音发出次数的单位。", "cites": [{"t": "转轴拨弦三两声,未成曲调先有情。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "几声抽泣;几声鸟鸣", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('655wx','把','1','bǎ bà','扌','7','','[{"pinyin": "bǎ", "defs": [{"meaning": "(形声。从手,巴声 。本义:握持;执)。"}, {"meaning": "同本义。", "cites": [{"t": "把,握也。", "b": "《说文》"}, {"t": "其拱把而上者。", "b": "《庄子·人间世》"}, {"t": "拱把之桐梓。", "b": "《孟子》。注:“以一手把之也。”"}, {"t": "汤自把铖以伐昆吾。", "b": "《史记·殷本纪》"}, {"t": "无把铫推耨之劳,而有积粟之实。", "b": "《战国策·秦策四》"}, {"t": "把酒临风。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "把其袖。", "b": "《战国策·燕策》"}, {"t": "把酒话桑麻。", "b": "唐·孟浩然《过故人庄》"}], "words": [{"w": "把杯", "t": "拿着杯子"}, {"w": "把刀", "t": "掌刀,上灶烧菜"}, {"w": "把卷", "t": "持卷"}, {"w": "把玩", "t": "握在手中或置于手中赏玩"}, {"w": "把腕", "t": "握住手腕。"}]}, {"meaning": "把守;看守。站岗放哨。", "cites": [{"t": "街亭有兵把守。", "b": "《三国演义》"}], "words": [{"w": "把大门;把界军", "t": "守边军队。"}]}, {"meaning": "掌管;控制。", "cites": [{"t": "把脚不住,翻筋斗跌倒。", "b": "明·冯梦龙《醒世恒言》"}], "words": [{"w": "把稳", "t": "把持稳妥。"}]}, {"meaning": "给。", "cites": [{"t": "我一天杀一头猪还赚不到钱把银子,都把与你去丢在水里,叫我一家老小嗑西北风。", "b": "《儒林外史》"}], "words": [{"w": "把与", "t": "送给。"}]}, {"meaning": "把东西扎在一起的小捆儿。", "cites": [{"t": "二月山城无菜把。", "b": "杨万里《南雄邑外寄堂》"}], "words": [{"w": "草把", "t": ""}]}, {"meaning": "大约 ——用在数词(如百、千、万)和度量衡单位(如公里、公斤、个)的后面表示数量近于这个单位数。", "cites": [{"t": "起来又走了里把多路。", "b": "《儒林外史》"}], "words": [{"w": "个把月;百把公斤;千把块钱", "t": ""}]}, {"meaning": "引进凭借的工具、材料、方法等,相当于“拿”、“用”。", "cites": [{"t": "生来不读半行书,只把黄金买身贵。", "b": "唐·李贺《嘲少年》"}]}, {"meaning": "引进对象,相当于“对”。", "cites": [{"t": "吓怕了的,所以把二哥哥的事也疑惑起来。", "b": "《红楼梦》"}]}, {"meaning": "表示经过,用在处所词前面,相当于“从”。", "cites": [{"t": "军师言:“夏侯惇败了必把你手内过也。”", "b": "《三国志平话》"}]}, {"meaning": "在被动式里引进行为的主动者,相当于“被”。", "cites": [{"t": "谁想走到人市处,把梅香迷了。", "b": "元·杨景声《刘行首》"}]}, {"meaning": "一握或一小捆。", "cites": [{"t": "拱把之桐梓,人苟欲生之,皆知所以养之者。", "b": "《孟子·告子》"}], "words": [{"w": "一把韭菜", "t": ""}]}]}, {"pinyin": "bà", "defs": [{"meaning": "柄。器物上便于用手拿的部分。", "cites": [{"t": "左手承弣。", "b": "《礼记·曲礼上》。注:“弣把中。”释文:“把,手执处也。”"}, {"t": "戾翳旋把。", "b": "《文选·潘岳·射雉赋》"}], "words": [{"w": "茶壶把儿;印把子", "t": ""}]}, {"meaning": "植物上支持着一个或多个叶片、花朵或果实的部分。", "cites": [{"t": "无把之枝。", "b": "《淮南子·缪称》"}], "words": [{"w": "花把儿;梨把儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('656wx','报','1','bào','扌','7','','[{"pinyin": "bào", "defs": [{"meaning": "(会意。从帇,从阜,金文字形,左边象刑具形,即“帇(niè)”。右象手按人使之跽跪意,即“阜”,读fǔ。组合在一起表示治人罪之意。本义:断狱,判决罪人)。"}, {"meaning": "同本义。", "cites": [{"t": "辟报故不穷审。", "b": "《汉书·胡建传》"}, {"t": "报囚。", "b": "《后汉书·鲁恭传》。注:“谓奏请报决也。”"}, {"t": "报而罪之。", "b": "《韩非子·五蠹》"}]}, {"meaning": "又。", "cites": [{"t": "闻死刑之报,君为流涕。", "b": ""}], "words": [{"w": "报囚", "t": "判决囚犯"}, {"w": "报当", "t": "判罪。"}]}, {"meaning": "报答,报酬。", "cites": [{"t": "欲报之于陛下也。", "b": "诸葛亮《出师表》"}, {"t": "欲略上报。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "报本", "t": "报答;回报"}, {"w": "报称", "t": "报答恩德"}, {"w": "报命", "t": "报答恩情;执行命令"}, {"w": "报捐", "t": "捐钱买官"}, {"w": "报塞", "t": "报答;报效"}, {"w": "报谢", "t": "报答;答谢。"}]}, {"meaning": "报告,答复。", "cites": [{"t": "列子行泣报壶子。", "b": "《淮南子·精神》"}, {"t": "荀息操璧牵马而报。", "b": "《吕氏春秋·权勋》"}, {"t": "阙然久不报,幸勿为过!", "b": "司马迁《报任少卿书》"}, {"t": "请为张唐先报赵。", "b": "《战国策·秦策五》"}, {"t": "求人可使报秦者。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "一日晌午,谍报敌骑至。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "具以沛公言报项王。", "b": "《史记·项羽本记》"}], "words": [{"w": "报录人", "t": "专门向升了官或考中了科的人家里送喜报的人"}, {"w": "报辜", "t": "报案状子"}, {"w": "报喜;报数;报春", "t": "报告春天的到来。"}]}, {"meaning": "报复。", "cites": [{"t": "睚眦之怨必报。", "b": "《史记·范雎传》"}, {"t": "日夜思欲报楚王。", "b": "晋·干宝《搜神记》"}, {"t": "欲求报其父仇。", "b": "《史记·魏公子列传》"}, {"t": "士不敢弯弓而报怨。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "报恨", "t": "报仇雪恨"}, {"w": "报雪", "t": "报仇雪恨"}, {"w": "报怨", "t": "埋怨;抱怨。"}]}, {"meaning": "(fù)。奔赴。", "cites": [{"t": "毋拔来,毋报往。", "b": "《礼记·少仪》"}, {"t": "报葬者报虞。", "b": "《礼记·丧服小记》"}, {"t": "卿但暂还家,吾今且报府。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "报应。", "cites": [{"t": "夫造物者之报人也,不报其人而报其人之天。", "b": "《庄子·列御寇》"}, {"t": "前后造业后人报,如是我闻佛亦狂。", "b": "董必武《和叶参谋长过五台山》"}]}, {"meaning": "传达消息的文件或信号。", "cites": [{"t": "而抄捕南海馆之报(消息)忽至。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "情报;警报", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('657wx','拟','1','nǐ','扌','7','','[{"pinyin": "nǐ", "defs": [{"meaning": "(形声。从手,以声。本义:揣度,猜测)。"}, {"meaning": "同本义。", "cites": [{"t": "拟,度也。", "b": "《说文》"}, {"t": "行止而拟度焉。", "b": "《周礼·射人》注"}, {"t": "拟之而后言,议之而后动。", "b": "《易·系辞上》"}, {"t": "先生说的可单是拟题?", "b": "《儒林外史》"}], "words": [{"w": "悬拟", "t": "凭空虚构"}, {"w": "拟足", "t": "揣度脚步"}, {"w": "拟度", "t": "揣度;推测"}, {"w": "拟迹", "t": "揣度足迹"}, {"w": "拟题", "t": "应试举子揣度命题。"}]}, {"meaning": "类似;比拟。", "cites": [{"t": "复举剑拟之。", "b": "《汉书·李广苏建传》"}, {"t": "客以剑拟王,王头随堕汤中。(拟:比划,作砍的样子。“拟”后有“于”省略。客用剑向楚王一比划,楚王的人头就落到开水里。", "b": "晋·干宝《搜神记》)"}, {"t": "非它山可拟。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "又。", "cites": [{"t": "不可拟小孤。", "b": ""}, {"t": "拟之如天。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "拟主", "t": "自比作主人"}, {"w": "拟制", "t": "比拟其规模制度"}, {"w": "拟物", "t": "修辞方法之一。把人拟作物或把物拟作人,或把甲物拟作乙物"}, {"w": "拟伦", "t": "比拟;伦比"}, {"w": "拟容", "t": "形貌上的比拟"}, {"w": "拟圣", "t": "比拟圣人"}, {"w": "拟质", "t": "比拟。"}]}, {"meaning": "模仿。", "cites": [{"t": "衡乃拟班固《两都》作《二京赋》。", "b": "《后汉书·张衡传》"}], "words": [{"w": "模拟", "t": "模仿"}, {"w": "拟经", "t": "模仿经典"}, {"w": "拟水", "t": "古代祭祀仪式中模拟盥洗的动作"}, {"w": "拟托", "t": "模拟假托"}, {"w": "拟象", "t": "谓模仿其状"}, {"w": "拟貌", "t": "摹拟描摹"}, {"w": "拟仪", "t": "模仿其法度;仿效。"}]}, {"meaning": "打算。", "cites": [{"t": "拟用左通政。", "b": "清·张廷玉《明史》"}], "words": [{"w": "拟作", "t": "准备有所作为"}, {"w": "拟待", "t": "打算"}, {"w": "拟踪", "t": "打算达到"}, {"w": "拟托", "t": "打算委托。"}]}, {"meaning": "起草。", "cites": [{"t": "命君拟旨。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "草拟", "t": "起草;初步设计"}, {"w": "拟制", "t": "草拟制订"}, {"w": "拟奏", "t": "起草奏章;准备奏呈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('658wx','却','1','què','卩','7','','[{"pinyin": "què", "defs": [{"meaning": "(形声。本作“却”,俗字作“却”。从卩,谷(què)声。卩(jié),象人下跪的样子,即腿骨节屈曲的样子。从“卩”与脚的活动有关。本义:退)。"}, {"meaning": "同本义。", "cites": [{"t": "却,节欲也。", "b": "《说文》。按:“退也”。"}, {"t": "却行仄行。", "b": "《考工记·梓人》"}, {"t": "吾行却曲。", "b": "《庄子·人间世》"}, {"t": "怒战栗而却。", "b": "《战国策·秦策》"}, {"t": "却下而载之。", "b": "《仪礼·既夕礼》"}, {"t": "却骐骥以转运兮。", "b": "《楚辞·愍命》"}, {"t": "北救赵而却秦。", "b": "《史记·魏公子列传》"}, {"t": "已却秦存赵。", "b": ""}, {"t": "持璧却立。", "b": "《史记·廉颇蔺相列传》"}, {"t": "曳笏却立。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "退却", "t": "向后撤退;畏难后退"}, {"w": "却走", "t": "退避;退走"}, {"w": "却还", "t": "退还"}, {"w": "却避", "t": "退避"}, {"w": "却归", "t": "退归"}, {"w": "却略", "t": "退身"}, {"w": "却去", "t": "后退;离去"}, {"w": "却生", "t": "后退贪生"}, {"w": "却立", "t": "后退站立。"}]}, {"meaning": "除;去。", "words": [{"w": "却扇", "t": "古代婚礼行礼时,新娘以扇遮面,交拜后去扇"}, {"w": "却惑", "t": "去邪;消除疑难"}, {"w": "了却", "t": "了结。"}]}, {"meaning": "避;避免。", "cites": [{"t": "是时李少君亦以祠灶谷道却老方见上,上尊之。", "b": "《史记·封禅书》"}], "words": [{"w": "却老", "t": "避免衰老"}, {"w": "却死", "t": "避死。"}]}, {"meaning": "用在偏正复句的正句中,提出跟偏句相反或不一致的动作、行为或状况,表示转折,相当于“但”、“但是”、“可是”。", "cites": [{"t": "一连数日,施恩来了大牢里三次,却不提防被张团练家心腹人见了。", "b": "《水浒传》"}]}, {"meaning": "固然。", "cites": [{"t": "好却十分好了,只是一件,这孩儿生下来,昼夜啼哭,乳也不肯吃。", "b": "《喻世明言》"}]}, {"meaning": "再。", "cites": [{"t": "却与小姑别。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "却看妻子愁何在。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "却坐促弦弦转急。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "却又", "t": "再"}, {"w": "却再", "t": "再。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('659wx','抒','1','shū','扌','7','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从手,予声。本义:舀出)。"}, {"meaning": "同本义。", "cites": [{"t": "抒,挹也。", "b": "《说文》"}, {"t": "汲出谓之抒。", "b": "《通俗文》"}, {"t": "抒,取也。", "b": "《苍颉篇》"}, {"t": "或舂或揄。", "b": "《诗·大雅·生民》。毛传:“揄,抒臼也。”"}]}, {"meaning": "表达;发泄。", "cites": [{"t": "以辞抒意。", "b": "《墨子·小取》"}, {"t": "发愤以抒情。", "b": "《楚辞·惜诵》"}, {"t": "一抒愚意。", "b": "《汉书·刘向传》"}], "words": [{"w": "各抒己见;抒诚", "t": "申达诚意"}, {"w": "抒词", "t": "运用词语,表达词意"}, {"w": "抒意", "t": "表达心意"}, {"w": "抒愤", "t": "发泄怨愤。"}]}, {"meaning": "解除,排除或免除,减轻。", "cites": [{"t": "有此四德者,难必抒矣。", "b": "《左传·文公六年》"}, {"t": "闻之者意悦而情抒。", "b": "谢偃《听歌赋》"}], "words": [{"w": "抒伸", "t": "解闷;舒畅。"}]}, {"meaning": "斜削。", "cites": [{"t": "管之下端,抒之以合于筩。", "b": "《农政全书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('660wx','劫','1','jié','力','7','','[{"pinyin": "jié", "defs": [{"meaning": "(会意。从力,去声。本义:以强力使对方欲去而不得)。"}, {"meaning": "威胁;威逼。", "cites": [{"t": "劫,人欲去,以力胁止,曰劫。", "b": "《说文》"}, {"t": "劫之以众。", "b": "《礼记·儒行》"}, {"t": "已珉欲以齐秦劫魏。", "b": "《战国策·秦策》"}, {"t": "故口可劫而使墨云。", "b": "《荀子·解蔽》"}, {"t": "不可劫以死生。", "b": "《淮南子·精神》"}, {"t": "因以劫众。", "b": "《汉书·高帝纪》"}, {"t": "积威所劫。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "劫杀", "t": "劫持并加以杀害"}, {"w": "劫略", "t": "以威力胁迫于人"}, {"w": "劫盟", "t": "以暴力逼人缔结盟约"}, {"w": "劫质", "t": "挟持人质,借此勒索。"}]}, {"meaning": "抢夺;强取。", "cites": [{"t": "乃欲以生劫之,必得约契以报太子。", "b": "《战国策·燕策》"}, {"t": "谋劫单于母。", "b": "《汉书·李广苏建传》"}, {"t": "行劫缚者。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "劫掳", "t": "抢劫掳掠"}, {"w": "劫鞘", "t": "抢劫鞘银"}, {"w": "劫磷", "t": "劫难;灾难。磷:薄;损伤"}, {"w": "劫剞", "t": "抢劫掠夺"}, {"w": "打劫", "t": "抢劫"}, {"w": "行劫", "t": "进行抢劫。"}]}, {"meaning": "围棋术语,争夺某一从属未定的棋眼。", "cites": [{"t": "陈木南正在暗欢喜,又被他生出一个劫来,打个不清,陈木南又要输了。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('661wx','芙','1','fú','艹','7','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从艸,夫声。芙蕖:荷花的别名。本义:芙蓉:荷花的别名)。"}, {"meaning": "同本义。", "cites": [{"t": "芙蓉覆水,秋兰被涯。", "b": "《文选·张衡·东京赋》"}]}, {"meaning": "木莲,即木芙蓉。落叶大灌木,叶大掌状浅裂,花大有柄,色有红白,晚上变深红,供观赏,叶和花均可入药。"}, {"meaning": "喻指美女。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('662wx','芜','1','wú','艹','7','','[{"pinyin": "wú", "defs": [{"meaning": "(形声。从艸,无声。本义:土地不耕种而荒废)。"}, {"meaning": "同本义。", "cites": [{"t": "田甚芜,仓甚虚。", "b": "《老子》"}, {"t": "田彼南山,芜秽不治。", "b": "杨恽《报孙会宗书》"}, {"t": "田园将芜。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "芜荒", "t": "荒芜"}, {"w": "芜绝", "t": "荒芜断绝"}, {"w": "芜蔓", "t": "荒芜;荒凉"}, {"w": "芜废", "t": "荒废"}, {"w": "芜荟", "t": "荒芜"}, {"w": "芜蒌", "t": "野草"}, {"w": "芜旷", "t": "犹荒芜。"}]}, {"meaning": "杂乱。", "cites": [{"t": "陆文深而芜。", "b": "《世说新语·文学》"}], "words": [{"w": "芜音", "t": "声音多而杂乱。引申指音律不协畅"}, {"w": "芜昧", "t": "不明,杂乱不清的样子"}, {"w": "芜浅", "t": "杂乱浅陋"}, {"w": "芜累", "t": "文字不够简炼,常有多余重复之处"}, {"w": "芜漫", "t": "杂乱散漫。"}]}, {"meaning": "丛生的杂草。", "cites": [{"t": "寝兴日已寒,白露生庭芜。", "b": "颜延年《秋朝诗》"}], "words": [{"w": "芜没", "t": "指杂草丛生,隐没于其中"}, {"w": "芜芜", "t": "草木茂密繁盛的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('663wx','苇','1','wěi','艹','7','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从艸,韦声。本义:芦苇) 同本义。", "cites": [{"t": "苇,大葭也。", "b": "《说文》"}, {"t": "震为萑苇。", "b": "《易·说卦》"}], "words": [{"w": "苇车", "t": "简陋的柴车"}, {"w": "苇杖", "t": "蒲鞭,用以施轻刑的草鞭子"}, {"w": "苇索", "t": "一种用蒲苇编结而成的绳索。古代于年节时,将苇索装结于门上,以祛除邪鬼、邪气"}, {"w": "苇茭", "t": "苇草编织的绳索"}, {"w": "苇戟桃杖", "t": "用芦苇做戟,以桃木制杖。为古代祛除恶鬼的物品"}, {"w": "苇荻", "t": "苇苕。芦苇"}, {"w": "苇莞", "t": "苇草和蒲草。亦指这两种草编成的席子"}, {"w": "苇带", "t": "用苇草编成的衣带"}, {"w": "苇笮", "t": "用苇草制成的绳索。笮,竹索"}, {"w": "苇薄", "t": "苇席。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('664wx','芽','1','yá','艹','7','','[{"pinyin": "yá", "defs": [{"meaning": "(形声。从艸,牙声。本义:尚未发育成长的枝、叶或花的雏体)。"}, {"meaning": "同本义。", "cites": [{"t": "芽,萌芽也。", "b": "《说文》。段注:“古多以牙为芽。”"}, {"t": "芽,孽也。", "b": "《广雅·释草》"}, {"t": "遂令黄泉下,萌芽夭句尖。", "b": "韩愈《苦寒诗》"}, {"t": "二月草已芽,八月草未枯。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "同芽者。", "b": ""}, {"t": "粪溉者先芽。", "b": ""}, {"t": "蒌蒿满地芦芽短。", "b": "宋·苏轼《惠崇"}, {"t": "春江晚景", "b": ""}]}, {"meaning": "》。", "words": [{"w": "芽茶", "t": "最嫩的茶叶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('665wx','花','1','huā','艹','7','','[{"pinyin": "huā", "defs": [{"meaning": "同本义。"}, {"meaning": "草木花的总称。", "cites": [{"t": "百卉含蘤。", "b": "《汉书·张衡传》。注:“蘤,古花字也。经传皆以华为之。”"}, {"t": "菊垂今秋花,石戴古车辙。", "b": "杜甫《北征》"}, {"t": "一丛深色花,十户中人赋。", "b": "白居易《买花》"}], "words": [{"w": "花洞", "t": "茂密的花丛。或指花丛深处"}, {"w": "花石纲", "t": "运送花石的船队"}, {"w": "花朝日", "t": "传说农历二月十二日为百花生日,称为花朝"}, {"w": "花魂", "t": "花的精神、魂魄"}, {"w": "花相", "t": "芍药的别名。古时品花,群芳中,牡丹品为第一,芍药为第二,故世称牡丹为花王,芍药为花相"}, {"w": "花酒", "t": "用花酿成的酒"}, {"w": "花气", "t": "花朵的香气"}, {"w": "花经", "t": "品论花卉的书"}, {"w": "花历", "t": "记载群花开落时期的历法"}, {"w": "花口", "t": "初开的花。因花开时如口张状,故称。"}]}, {"meaning": "泛指能开花供观赏的草本与木本植物。", "cites": [{"t": "春路雨添花,花动一山春色。", "b": "秦观《好事近》"}], "words": [{"w": "花丁", "t": "种花的园丁"}, {"w": "花池", "t": "庭园中种植花草的地方。一般有矮栏围绕"}, {"w": "花草", "t": "泛指可供观赏的花和草。"}]}, {"meaning": "特指某一名花。", "cites": [{"t": "洛人凡花不曰花,独牡丹曰花。", "b": "《尘史》"}], "words": [{"w": "花王", "t": "花中之王。指牡丹"}, {"w": "花水", "t": "农历二、三月间桃花开放时盛涨的河水。即桃花水"}, {"w": "花相", "t": "古称牡丹为花王,芍药为花相。"}]}, {"meaning": "形状像花朵的东西。", "cites": [{"t": "闲敲棋子落灯花。", "b": "赵师秀《有约》"}], "words": [{"w": "花下子", "t": "结婚第一夜怀孕而生的孩子"}, {"w": "花湖", "t": "一种纸牌"}, {"w": "花门儿", "t": "贴在门上的画"}, {"w": "花生彩笔", "t": "笔下生花,喻才华横溢。"}]}, {"meaning": "喻指美女。", "cites": [{"t": "娇花巧笑久寂寥。", "b": "唐·白居易《霓裳羽衣舞歌》"}], "words": [{"w": "花林粉阵", "t": "比喻群集的美女"}, {"w": "花枝", "t": "比喻美女"}, {"w": "花月缘", "t": "佳人才子的情缘"}, {"w": "花魁娘子", "t": "美称妓女。"}]}, {"meaning": "喻出卖色相的女子。", "cites": [{"t": "花娘十二能歌舞。", "b": "宋·梅尧臣《花娘歌》"}], "words": [{"w": "花捐", "t": "旧时对娼妓所征的税。也叫妓捐、乐户捐"}, {"w": "花娘", "t": "歌妓。后也指娼妓"}, {"w": "花奶奶", "t": "旧时对从良妓女的称呼"}, {"w": "花曲", "t": "指妓院所在处。"}]}, {"meaning": "开花。", "cites": [{"t": "朱雀桥边野草花。", "b": "刘禹锡《乌衣巷》"}, {"t": "未花时采。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "花过而采。", "b": ""}, {"t": "平地三月花。", "b": ""}, {"t": "深山中则四月花。", "b": ""}, {"t": "不花而结实。", "b": "裴渊《广州记》"}]}, {"meaning": "在支付或支出上用掉钱。", "cites": [{"t": "我不入社花几个钱。", "b": "《红楼梦》"}], "words": [{"w": "花钱;花用", "t": "耗费"}, {"w": "花朴朴", "t": "隆重铺张;消费大量财物。"}]}, {"meaning": "模糊不清。", "cites": [{"t": "眼花落井水底眠。", "b": "杜甫《饮中八仙歌》"}], "words": [{"w": "花镜;花腊搽", "t": "犹言昏花模糊。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('666wx','芹','1','qín','艹','7','','[{"pinyin": "qín", "defs": [{"meaning": "芹菜。", "cites": [{"t": "芹,楚葵也。", "b": "《说文》"}]}, {"meaning": "即今之水芹菜》。", "cites": [{"t": "言采其芹。", "b": "《诗·小雅·采菽》"}, {"t": "薄采其芹。", "b": "《诗·鲁颂·泮水》"}, {"t": "菜之美者,云梦之芹。", "b": "《吕氏春秋·本味》"}, {"t": "芹菹兔醢。", "b": "《周礼·醢人》"}]}, {"meaning": "多年生草本植物,夏天开白色花,茎叶可以吃。亦名“水芹”、“水靳”,古名“楚葵”。又有一种旱芹,有特殊的香气,俗名“药芹”。"}, {"meaning": "喻微薄。", "cites": [{"t": "邀兄到敝斋一饮,不知可纳芹意否?", "b": "《红楼梦》"}], "words": [{"w": "芹敬", "t": "微薄的礼物"}, {"w": "芹诚", "t": "谦词。微薄的诚意"}, {"w": "芹意", "t": "谦词。微薄的情意"}, {"w": "芹曝", "t": "谦词。所献微不足道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('667wx','芥','1','jiè gài','艹','7','','[{"pinyin": "jiè", "defs": [{"meaning": "(形声。从艸,介声。本义:蔬菜名。即“芥菜”)。"}, {"meaning": "同本义。一年或二年生草本植物，种子黄色，味辛辣。", "cites": [{"t": "芥,芥菜也。", "b": "《说文》"}, {"t": "天地之行,芥苦味也。", "b": "《春秋繁露》"}, {"t": "脍,春用葱,秋用芥。", "b": "《礼记·内则》"}], "words": [{"w": "芥子", "t": "芥菜的种子。颗粒很小,可榨油或制芥末"}, {"w": "芥孙", "t": "芥菜于霜雪中再发的嫩牙"}, {"w": "芥尽", "t": "芥子用完。佛教用语。比喻时间之久或劫数之多"}, {"w": "芥苔", "t": "芥菜开花新生的嫩茎。"}]}, {"meaning": "小草。", "cites": [{"t": "芥为之舟。", "b": "《庄子·逍遥游》"}, {"t": "似寻针芥。", "b": "《聊斋志异·促织》"}], "words": [{"w": "芥豆", "t": "小草和豆子"}, {"w": "芥豆大小人家", "t": "比喻小户人家"}, {"w": "芥舟", "t": "比喻小舟"}, {"w": "芥拾", "t": "比喻轻易地取得。"}]}, {"meaning": "梗塞。", "cites": [{"t": "恨无乖崖老,一洗芥蒂胸。", "b": "苏轼《送路都曹》"}], "words": [{"w": "芥蒂", "t": "细小的梗塞物,比喻积在心中的怨恨或不快"}, {"w": "介纳须弥", "t": "佛教说法:小小的芥子可包容须弥大山或整个世界。须弥:传说中的古印度山名"}, {"w": "芥虿", "t": "芥蒂。"}]}, {"meaning": "", "words": [{"w": "芥羽", "t": "指用以角斗的鸡。斗鸡之时,把芥末播撒在鸡的羽毛上,迷蒙对方鸡的眼而取胜。"}]}, {"meaning": "比喻轻微纤细的事物", "words": [{"w": "草芥", "t": ""}, {"w": "芥视", "t": "轻视,不看重"}]}]}, {"pinyin": "gài", "defs": [{"meaning": "芥菜"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('668wx','芬','1','fēn','艹','7','','[{"pinyin": "fēn", "defs": [{"meaning": "(会意。从艸,从分,分亦声。本义:香气)。"}, {"meaning": "同本义。", "cites": [{"t": "芬,草初生其香分布也。", "b": "《说文》"}, {"t": "芬,芬香也。", "b": "《广雅》"}, {"t": "天地之行分、苦味也。", "b": "《春秋繁露》"}, {"t": "苾苾芬芬。", "b": "《诗·小雅·信南山》"}, {"t": "芬馥肸蚃。", "b": "左思《吴都赋》"}, {"t": "芳菲菲而难亏兮,芬至今犹未沬。", "b": "《楚辞·离骚》"}]}, {"meaning": "特别好闻的香气。", "cites": [{"t": "流芬赋采,风靡云旋。", "b": "潘岳《芙蓉赋》"}]}, {"meaning": "比喻盛德或美名。", "cites": [{"t": "扬芬千载之上。", "b": "《晋书·桓彝传》"}], "words": [{"w": "扬芬千载", "t": "扬名千年"}, {"w": "芬烈", "t": "喻功业盛美。"}]}, {"meaning": "(fěn)。米细末,化妆用的粉末。", "cites": [{"t": "五隐之状,黑土黑苔,青怵以肥,芬然若灰。", "b": "《管子·地员》"}]}, {"meaning": "和,和好。", "cites": [{"t": "芬,和也。", "b": "《方言十三》"}], "words": [{"w": "芬芗", "t": "和调。"}]}, {"meaning": "乱,杂。", "cites": [{"t": "乘玄四龙,回驰北行,羽旄殷盛,芬哉芒芒。", "b": "《汉书·礼乐志》"}], "words": [{"w": "芬芬", "t": "纷纷。杂乱的样子。"}]}, {"meaning": "隆起的样子。", "cites": [{"t": "五壤之状,芬然若泽、若屯土。", "b": "《管子·地员》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('669wx','苍','1','cāng','艹','7','','[{"pinyin": "cāng", "defs": [{"meaning": "(形声。从艸,仓声。本义:草色)。"}, {"meaning": "同本义,引申为青黑色。", "cites": [{"t": "苍,草色也。", "b": "《说文》"}, {"t": "苍,青也。", "b": "《广雅》"}, {"t": "在色为苍。", "b": "《素问·阴阳应象大论》。注:“谓薄青色。”"}, {"t": "彼苍者天。", "b": "《诗·秦风·黄鸟》"}, {"t": "春为苍天。", "b": "《尔雅·释天》"}, {"t": "东方曰苍天。", "b": "《吕氏春秋·有始》"}, {"t": "驾苍龙。", "b": "《礼记·月令孟春》。注:“苍亦青也。”"}, {"t": "染于苍则苍,染于黄则黄。", "b": "《墨子·所染》"}], "words": [{"w": "苍山", "t": "青山"}, {"w": "苍苔", "t": "青苔"}, {"w": "苍头", "t": "旧指仆人。汉时奴仆皆以深青色巾包头,故名;又指老年人。"}]}, {"meaning": "灰白色。", "cites": [{"t": "满面尘灰烟火色,两鬓苍苍十指黑。", "b": "白居易《卖炭翁》"}], "words": [{"w": "苍髯;苍浪", "t": "花白"}, {"w": "苍华", "t": "形容头发灰白。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('670wx','芳','1','fāng','艹','7','','[{"pinyin": "fāng", "defs": [{"meaning": "(形声。从艸,方声。本义:花草)。"}, {"meaning": "同本义。", "cites": [{"t": "野芳发而幽香。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "芳芷", "t": "香草名"}, {"w": "芳苓", "t": "芳荃。香草名"}, {"w": "芳草", "t": "香草。"}]}, {"meaning": "香气。", "cites": [{"t": "芳,草香也。", "b": "《说文》"}, {"t": "芳菲菲其弥章。", "b": "《楚辞·离骚》。注:“香貌。”"}, {"t": "兰芝以芳未尝见霜。", "b": "《淮南子·说林》"}, {"t": "芳与泽其杂糅兮。", "b": "《楚辞·离骚》"}, {"t": "兰有莠兮菊有芳。", "b": "汉武帝《秋风辞》"}]}, {"meaning": "比喻美名或美德。", "cites": [{"t": "昭示来世,垂芳后昆。", "b": "汉·蔡邕《刘镇南碑》"}], "words": [{"w": "芳尘", "t": "比喻美好的名声或风气"}, {"w": "芳风", "t": "美好的风尚和教化;亦指美誉流芳百世。"}]}, {"meaning": "喻有贤德的人。", "cites": [{"t": "腥臊并御,芳不得薄兮。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "芳躅", "t": "前贤的遗迹"}, {"w": "芳规", "t": "前贤的遗规"}, {"w": "芳魂", "t": "志行高尚者的灵魂"}, {"w": "芳迹", "t": "前贤的行迹。"}]}, {"meaning": "子房。", "cites": [{"t": "穗钜而芳夺。", "b": "《吕氏春秋》"}]}, {"meaning": "(páng)。侧,边。", "cites": [{"t": "陕之芳七施,七七四十九尺,而至於泉。", "b": "《管子·地员》"}]}, {"meaning": "香,气味美好。", "cites": [{"t": "芳草发狂。", "b": "《素问·腹中论》"}, {"t": "和致芳些。", "b": "《楚辞·大招》"}, {"t": "鼓芳风以扇游尘。", "b": "《谷梁传序》"}, {"t": "芳草鲜美,落英缤纷。", "b": "晋·陶渊明《桃花源记》"}, {"t": "芳草萋萋鹦鹉洲。", "b": "唐·崔颢《黄鹤楼》"}], "words": [{"w": "芳兰竟体", "t": "通体芳香。比喻举止闲雅,超凡脱俗"}, {"w": "芳芽", "t": "香茗"}, {"w": "芳旨", "t": "香美之味"}, {"w": "芳苾", "t": "芬芳"}, {"w": "芳茗", "t": "香茶。"}]}, {"meaning": "美好。", "cites": [{"t": "其志洁,故其称物芳。", "b": "《史记·屈原贾生列传》"}, {"t": "曾经学舞度芳年。", "b": "卢照邻《长安古意》"}], "words": [{"w": "流芳百世;芳序", "t": "良辰,美好的时光"}, {"w": "芳誉", "t": "好名声"}, {"w": "芳风", "t": "雅正的音乐;美好的文章。"}]}, {"meaning": "对人的敬称,美称。", "cites": [{"t": "原来今日也是姐姐的芳诞。", "b": "《红楼梦》"}], "words": [{"w": "芳范", "t": "对女性容貌的美称"}, {"w": "芳魂", "t": "敬称别人的灵魂"}, {"w": "芳札", "t": "敬称他人的书信。也称芳讯,芳翰"}, {"w": "芳信", "t": "敬称他人的书信。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('671wx','严','1','yán','一','7','','[{"pinyin": "yán", "defs": [{"meaning": "同本义。", "cites": [{"t": "事严,虞不敢请。", "b": "《孟子·公孙丑下》"}], "words": [{"w": "严急", "t": "犹危急;紧急"}, {"w": "严行", "t": "急行"}, {"w": "严鼓", "t": "急鼓,急促的鼓声。"}]}, {"meaning": "严厉;严肃。", "cites": [{"t": "诛严不为戾。", "b": "《韩非子·五蠹》"}, {"t": "严限追比。", "b": "《聊斋志异·促织》"}, {"t": "性严毅。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "严紧", "t": "严厉"}, {"w": "严查", "t": "严格检查"}, {"w": "严假", "t": "期限严格的假期"}, {"w": "严戢", "t": "谓严格管理"}, {"w": "严讥", "t": "严格查问"}, {"w": "严谴", "t": "严厉谴责"}, {"w": "严辞", "t": "严厉的言辞"}, {"w": "严罚", "t": "严厉处罚"}, {"w": "严察", "t": "严厉苛察"}, {"w": "严禁", "t": "严厉的禁令"}, {"w": "严愎", "t": "严厉而刚愎"}, {"w": "严参", "t": "严厉弹劾"}, {"w": "严处", "t": "严厉处罚"}, {"w": "严敏", "t": "严厉果断"}, {"w": "严重", "t": "严肃而持重"}, {"w": "严介", "t": "严肃耿介"}, {"w": "严色", "t": "严肃的神色"}, {"w": "严直", "t": "严肃正直"}, {"w": "严威", "t": "严肃而威重"}, {"w": "严庄", "t": "严肃庄重"}, {"w": "严远", "t": "严肃而使人敬畏"}, {"w": "严悫", "t": "严肃而诚实"}, {"w": "严谕", "t": "严肃告谕"}, {"w": "严凝", "t": "严肃凝重"}, {"w": "严懔", "t": "严肃而使人畏惧。"}]}, {"meaning": "紧密。", "cites": [{"t": "《春秋》谨严,左氏浮夸。", "b": "唐·韩愈《进学解》"}, {"t": "驰而不严。", "b": "唐·柳宗元《柳河东集》"}, {"t": "防伺甚严。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "严严实实", "t": "形容严密"}, {"w": "严秘", "t": "犹严密,秘密"}, {"w": "严捕", "t": "严密搜捕"}, {"w": "严幄", "t": "严密的帷幄"}, {"w": "严备", "t": "严密戒备"}, {"w": "严设", "t": "谓严密设防"}, {"w": "严紧", "t": "严密"}, {"w": "严确", "t": "犹严谨,严密"}, {"w": "严严", "t": "紧密严实貌"}, {"w": "严警", "t": "严密警戒。"}]}, {"meaning": "猛烈,严酷。", "cites": [{"t": "董之以严刑。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "风雪严寒。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "威严、威信。", "cites": [{"t": "有严有翼,共武之服。", "b": "《诗·小雅·六月》"}], "words": [{"w": "严毅", "t": "威严刚毅"}, {"w": "严惮", "t": "慑服"}, {"w": "严翼", "t": "威严敬慎"}, {"w": "严驵", "t": "威严傲慢"}, {"w": "严耸", "t": "威严傲岸。"}]}, {"meaning": "警戒。", "cites": [{"t": "严,戒也。昏鼓曰夜严,捶一鼓为一严,二鼓为二严,三鼓为三严…", "b": "《正字通》"}]}, {"meaning": "畏惧。", "cites": [{"t": "无严诸侯,恶声至,必反之。", "b": "《孟子》"}], "words": [{"w": "严惮", "t": "畏惧;害怕。"}]}, {"meaning": "尊敬,尊重。", "cites": [{"t": "严大国之威。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "严父", "t": "尊敬父亲"}, {"w": "严敬", "t": "尊敬;敬重。"}]}, {"meaning": "(kàn)。远望。", "cites": [{"t": "内严一家而三不归。", "b": "《管子·轻重丁》。丁士涵云:“严乃瞰之借字。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('672wx','芦','1','lú','艹','7','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。从艸,盧声。本义:草名。芦菔)。"}, {"meaning": "芦菔,似芜菁。今作萝卜。", "cites": [{"t": "芦,芦菔也。", "b": "《说文》。段注:“今之萝卜也。”"}, {"t": "芜菁,共紫华者谓之芦菔。", "b": "《方言》三"}], "words": [{"w": "芦萉", "t": "莱菔的别名。又名萝卜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('673wx','芯','1','xīn xìn','艹','7','','[{"pinyin": "xīn", "defs": [{"meaning": "灯心草茎中的髓,俗称“灯芯”。", "cites": [{"t": "家有千金,不添双芯,俭之积也。", "b": "光绪年修《黄岩县志》"}]}]}, {"pinyin": "xìn", "defs": [{"meaning": "", "words": [{"w": "岩芯;型芯", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('674wx','劳','1','láo','力','7','','[{"pinyin": "láo", "defs": [{"meaning": "(会意。小篆字形,上面是焱(yàn),即“焰”的本字,表示灯火通明;中间是“冖”字,表示房屋;下面是“力”,表示用力。夜间劳作。本义:努力劳动;使受辛苦)。"}, {"meaning": "同本义。", "cites": [{"t": "是犹推舟于陆地,劳而无功。", "b": "《庄子》"}, {"t": "或劳心,或劳力;劳心者治人,劳力者治于人。", "b": "《孟子·滕文公上》"}], "words": [{"w": "劳心焦思", "t": "苦思苦想"}, {"w": "劳民", "t": "劳役人民"}, {"w": "劳民动众", "t": "动用众多民力去做某件事"}, {"w": "劳师", "t": "使军队劳累;劳军。"}]}, {"meaning": "烦劳;麻烦。", "cites": [{"t": "劳各位等了许久,兄弟非常抱歉。", "b": "巴金《家》"}], "words": [{"w": "劳尊", "t": "表示客气的敬词。劳驾"}, {"w": "劳扰", "t": "烦劳打扰。"}]}, {"meaning": "慰劳。", "cites": [{"t": "公劳之日。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "莫我肯劳。", "b": "《诗经·魏风·硕鼠》"}, {"t": "劳之来之,匡之直之,辅之翼之。", "b": "《孟子·滕文公上》"}], "words": [{"w": "劳农", "t": "慰勉农耕"}, {"w": "劳赐", "t": "慰劳赏赐"}, {"w": "劳兵", "t": "慰劳军队。"}]}, {"meaning": "忧愁;愁苦。", "cites": [{"t": "实劳我心。", "b": "《诗·邶风·燕燕》"}], "words": [{"w": "劳人", "t": "劳苦忧伤之人"}, {"w": "劳结", "t": "郁结。指积在心中的忧思。"}]}, {"meaning": "夺取。", "cites": [{"t": "牺牲不劳,则牛马育。", "b": "《管子·小匡》《方言》注:“捞,取也。古无捞字,借劳为之。”"}]}, {"meaning": "劳累,疲劳。", "cites": [{"t": "师劳力竭,远主备之,无乃不可乎?", "b": "《左传·僖公三十二年》"}, {"t": "无案牍之劳形。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "劳其筋骨。", "b": "《孟子·告子下》"}, {"t": "历农亩之劳。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "好逸恶劳。", "b": "清·黄宗羲《原君》"}, {"t": "事力劳而供养薄", "b": "《韩非子·五蠹》"}], "words": [{"w": "劳碌", "t": "劳苦忙碌"}, {"w": "劳佚", "t": "劳苦与安佚"}, {"w": "劳倦", "t": "劳累疲倦"}, {"w": "劳烦", "t": "劳累麻烦"}, {"w": "劳竭", "t": "疲劳枯竭。"}]}, {"meaning": "辛苦;费力。", "cites": [{"t": "自谓少时用心于学甚劳。", "b": "宋濂《送东阳马生序》"}], "words": [{"w": "劳谦", "t": "勤劳谦虚"}, {"w": "劳谦日昃", "t": "恭谨勤劳,直到太阳偏西"}, {"w": "劳劳扰扰", "t": "忙忙碌碌。"}]}, {"meaning": "劳绩,小功。", "cites": [{"t": "奉厚而无劳。", "b": "《战国策·赵策》"}, {"t": "又口舌为劳。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "劳伐", "t": "功劳,功绩"}, {"w": "劳效", "t": "功效;功绩"}, {"w": "劳烈", "t": "劳绩;功业。"}]}, {"meaning": "摩田农具。", "cites": [{"t": "劳亦再遍。", "b": "《齐民要术·耕田》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('675wx','克','1','kè','十','7','','[{"pinyin": "kè", "defs": [{"meaning": "(象形。甲骨文字形,下面象肩形。整个字形,象人肩物之形。本义:胜任)。"}, {"meaning": "同本义。", "cites": [{"t": "克,肩也。", "b": "《说文》。按,以肩任物曰克。物高于肩,故从高省,下象肩形。古文亦象肩形。"}, {"t": "佛时仔肩。", "b": "《诗·周颂·敬之》。传:“仔肩,克也。”"}, {"t": "子克家。", "b": "《易·蒙》"}, {"t": "邾子克。", "b": "《左传·隐公元年》"}, {"t": "周王子克。", "b": "《左传·桓公十八年》"}, {"t": "伐柯如何?匪斧不克。", "b": "《诗·豳风·伐柯》"}, {"t": "克勤于邦,克俭于家。", "b": "《书·大禹谟》"}], "words": [{"w": "克当", "t": "担当,承受"}, {"w": "克堪", "t": "胜利"}, {"w": "克家", "t": "能承担家事"}, {"w": "克祚", "t": "能继承祖辈的福禄"}, {"w": "克家子", "t": "克家儿。能继承祖业的子弟"}, {"w": "克明", "t": "能察是非。"}]}, {"meaning": "能够。", "cites": [{"t": "克,能也。", "b": "《尔雅》"}, {"t": "匪斧不克。", "b": "《诗·齐风·南山》"}, {"t": "二曰刚克,三曰柔克。", "b": "《书·洪范》。郑注:“能也。”"}, {"t": "如其克谐,天下可定也。", "b": "《资治通鉴》"}], "words": [{"w": "克化", "t": "能够消化"}, {"w": "克尽", "t": "能够尽力"}, {"w": "克协", "t": "能够符合;等同"}, {"w": "克长", "t": "能教诲不倦"}, {"w": "克果", "t": "能成功,能实现"}, {"w": "克承", "t": "能够继承"}, {"w": "克荷", "t": "能够承担"}, {"w": "克臬", "t": "能奉法行事"}, {"w": "克能", "t": "能够。"}]}, {"meaning": "攻下;战胜;打败。", "cites": [{"t": "以此攻城,何城不克?", "b": "《左传·僖公四年》"}, {"t": "郑伯克段于鄢。", "b": "《左传·隐公元年》"}, {"t": "克,胜也。", "b": "《玉篇》"}, {"t": "然操遂能克绍,以弱为强者,非惟天时,抑亦人谋也。", "b": "陈寿《隆中对》"}, {"t": "饮酒温克。", "b": "《诗·小雅·小宛》"}, {"t": "如云不克。", "b": "《诗·大雅·桑柔》"}, {"t": "执轻如不克。", "b": "《礼记·曲礼下》"}], "words": [{"w": "克伏", "t": "降伏,制伏"}, {"w": "克伐", "t": "侵害"}, {"w": "迭克名城;克平", "t": "制伏,平定"}, {"w": "克胜", "t": "克敌制胜。"}]}, {"meaning": "克制。", "cites": [{"t": "二曰刚克,三曰柔克。", "b": "《书·洪范》"}, {"t": "克己奉公。", "b": "《后汉书·祭遵传》"}], "words": [{"w": "克心", "t": "约束内心"}, {"w": "克治", "t": "克制私欲邪念。"}]}, {"meaning": "严格限定期限。", "cites": [{"t": "公乃与克日会战。", "b": "《三国志·武帝操》"}, {"t": "克期置酒。", "b": "《三国志·张嶷传》"}, {"t": "与克期俱至,无或违者。", "b": "《后汉书·钟离意传》"}], "words": [{"w": "克期完工;克日", "t": "约定或限定时日。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('676wx','芭','1','bā','艹','7','','[{"pinyin": "bā", "defs": [{"meaning": "(形声。巴声。本义:①香草名。②芭蕉)。"}, {"meaning": "古书上说的一种香草。", "cites": [{"t": "传芭兮代舞。", "b": "《楚辞·九歌·礼魂》"}]}, {"meaning": "芭蕉。", "cites": [{"t": "乘兴书芭叶,闲来入豆房。", "b": "段成式《赠诸上人》"}], "words": [{"w": "芭叶", "t": "芭蕉的叶片"}, {"w": "芭蕉扇", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('677wx','苏','1','sū','艹','7','','[{"pinyin": "sū", "defs": [{"meaning": "(形声。从艸,稣(sū)声。从艸,与植物有关。本义:植物名,即紫苏)。"}, {"meaning": "柴草。", "cites": [{"t": "樵苏脂烛,莫非种植之物也。", "b": "《颜氏家训》"}]}, {"meaning": "须状下垂的饰物。", "cites": [{"t": "金车玉作轮,踯躅青骢马,流苏金缕鞍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "更生。", "cites": [{"t": "死而复生谓之苏。", "b": "《小尔雅·广名》"}, {"t": "苏,俗作甦。", "b": "《集韵》"}, {"t": "蘇,息也,死而更生也。", "b": "《广韵》"}, {"t": "更生为苏。", "b": "《颜氏家训·杂艺》"}, {"t": "震苏苏。", "b": "《易·震卦》"}, {"t": "傒予后,后来其苏。", "b": "《书·仲虺之诰》"}, {"t": "蛰虫昭苏。", "b": "《礼记·乐记》"}, {"t": "苏世独立。", "b": "《楚辞·九章·橘颂》"}, {"t": "自言身化促织,轻捷善斗,今始苏耳。", "b": "《聊斋志异·促织》"}], "words": [{"w": "苏息", "t": "再生滋长"}, {"w": "苏生", "t": "苏醒;复活"}, {"w": "苏更", "t": "复活;苏醒"}, {"w": "苏复", "t": "恢复“穌”。"}]}, {"meaning": "唤醒;昏迷后醒过来。", "cites": [{"t": "近抚之,气息惙然。喜置榻上,半夜复苏。", "b": "《聊斋志异·促织》"}], "words": [{"w": "苏省", "t": "苏醒"}, {"w": "苏活", "t": "苏醒;复活"}, {"w": "苏兴", "t": "犹苏醒。"}]}, {"meaning": "割草;取草。", "cites": [{"t": "行者践其首脊,苏者取而爨之而已。", "b": "《庄子·天运》"}]}, {"meaning": "引申为取。", "cites": [{"t": "苏粪壤以充帏兮。", "b": "《离骚》"}]}, {"meaning": "“噜囌”(lūsū),即“噜苏”(lūsū)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('678wx','杆','1','gān gǎn','木','7','','[{"pinyin": "gān", "defs": [{"meaning": "较长的棍", "words": [{"w": "旗杆", "t": ""}, {"w": "电线杆", "t": ""}, {"w": "桅杆", "t": ""}]}]}, {"pinyin": "gǎn", "defs": [{"meaning": "器物上像棍子的细长部分", "words": [{"w": "杆秤", "t": "区别于台秤等"}, {"w": "杆菌", "t": ""}]}, {"meaning": "量词，用于有杆的器物"}, {"meaning": "兵器,盾牌。", "cites": [{"t": "杆,古作干,俗加木。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('679wx','杠','1','gāng gàng','木','7','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从木,工声。(gāng)本义:床前横木)。"}, {"meaning": "同本义。", "cites": [{"t": "床,其杠,北燕、朝鲜之间谓之树,自关而西,秦晋之间谓之杠。", "b": "《方言》"}, {"t": "杠,床前横木也。", "b": "《说文》"}]}, {"meaning": "指旗杆。", "cites": [{"t": "素锦绸杠。", "b": "《尔雅·释天》"}]}]}, {"pinyin": "gàng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('680wx','杜','1','dù','木','7','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从木,土声。本义:杜梨,棠梨,一种木本植物)。"}, {"meaning": "同本义。", "cites": [{"t": "杜,甘棠也。", "b": "《说文》。按:“牡曰棠,牝曰杜。”"}, {"t": "杜树大者插五枝。", "b": "《齐民要术》"}]}, {"meaning": "堵塞。", "cites": [{"t": "杜,塞也。", "b": "《小尔雅·广诂》"}, {"t": "犯令陵政则杜之。", "b": "《周礼·大司马》。注:“杜塞使不得与邻国交通。”"}], "words": [{"w": "杜耳恶闻", "t": "塞住耳朵不愿听"}, {"w": "杜隔", "t": "阻塞隔离"}, {"w": "杜闭", "t": "堵塞,关闭"}, {"w": "杜禁", "t": "堵塞。"}]}, {"meaning": "关门,封闭 。", "cites": [{"t": "杜乃护王。", "b": "《书·费誓》。注:“闭也。”"}, {"t": "犯令陵政则杜之。", "b": "《周礼·夏官·大司马》"}, {"t": "强公室,杜私门。", "b": "《史记·李斯列传》"}, {"t": "陵怒,谢病免,杜门竟不朝请。", "b": "《汉书·王陵传》。颜师古注:杜,塞也,闭塞其门也。"}, {"t": "塞隘杜津。", "b": "《汉书·叙传》"}], "words": [{"w": "杜口", "t": "闭口不说"}, {"w": "杜门却扫", "t": "关闭大门,不再打扫庭院路径"}, {"w": "杜门晦(屏)迹(关闭大门,隐匿自己的踪迹)", "t": ""}]}, {"meaning": "冲击。", "cites": [{"t": "水之性,行至曲必留退,满则后推前,地下则平行,地高即控,杜曲则捣毁,杜曲激则跃。", "b": "《管子·度地》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('681wx','材','1','cái','木','7','','[{"pinyin": "cái", "defs": [{"meaning": "(形声。从木,才声。本义:木材,木料)。"}, {"meaning": "同本义。", "cites": [{"t": "材,木梃也。", "b": "《说文》"}, {"t": "五曰材贡。", "b": "《周礼·太宰》"}, {"t": "驾而乘材。", "b": "《国语·晋语》。注:“横木也。”"}, {"t": "无所取材。", "b": "《论语》。郑注:“无所取于桴材。”"}, {"t": "自吾执斧斤以随夫子,未尝见材如此其美也。", "b": "《庄子·人间世》"}, {"t": "材朴委积兮。", "b": "《楚辞·九章·怀沙》"}, {"t": "因造玉清宫,伐山取材。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "木材;材器", "t": "材木与器物。"}]}, {"meaning": "泛指原料、材料。", "cites": [{"t": "饬化八材。", "b": "《周礼·太宰》。注:“珠、象、玉、石、木、金、革、羽也。”"}, {"t": "其材足以备器用。", "b": "《左传·隐公五年》"}, {"t": "献材于殡门外。", "b": "《仪礼·士丧礼》。注:“明器之材。”"}], "words": [{"w": "钢材;器材;木材;就地取材", "t": ""}]}, {"meaning": "才能,能力。", "cites": [{"t": "任官惟材,左右惟其人。", "b": "《书·咸有一德》"}, {"t": "士脩身功材。", "b": "《管子·五辅》。注:“材谓艺能。”"}]}, {"meaning": "财物。", "cites": [{"t": "广辟土地,著税伪材。", "b": "《墨子·公孟》"}, {"t": "知务本禁末之为多材也。", "b": "《荀子·君道》"}, {"t": "材伎之士。", "b": "《荀子·王制》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('682wx','村','1','cūn','木','7','','[{"pinyin": "cūn", "defs": [{"meaning": "(形声。从邑,屯声。本义:村庄)。"}, {"meaning": "同本义。", "cites": [{"t": "邨,地名。", "b": "《说文》。徐铉曰:“今俗作村。”"}, {"t": "村中闻有此人,咸来问讯。", "b": "陶潜《桃花源记》"}, {"t": "僵卧孤村不自哀。", "b": "宋·陆游《十一月四日风雨大作》"}, {"t": "环村居者皆猎户。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "乡村,乡下,农村。", "cites": [{"t": "岂无山歌与村笛,呕哑嘲哳难为听。", "b": "白居易《琵琶行(并序)》"}], "words": [{"w": "村田乐", "t": "宋元明时表现农村生活的民间舞蹈"}, {"w": "村泊", "t": "村野,乡村"}, {"w": "村务", "t": "乡村小酒店;农家"}, {"w": "村野匹夫", "t": "身居乡野的鄙陋无知之人"}, {"w": "村醪浊酒", "t": "乡下人自家酿的酒"}, {"w": "村姑", "t": "农村少女。"}]}, {"meaning": "冒犯,用不好听的话伤人。", "cites": [{"t": "黛玉自悔失言,原是打趣宝玉的,就忘了村了彩云了。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('683wx','杖','1','zhàng','木','7','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从木,丈声。本义:执;持)。"}, {"meaning": "同本义。", "cites": [{"t": "杖,持也。", "b": "《说文》"}, {"t": "王左杖黄钺。", "b": "《书·牧誓》"}, {"t": "杖剑从之。", "b": "《汉书·韩信传》"}, {"t": "杖斧。", "b": "《汉书·武帝纪》"}], "words": [{"w": "杖斧", "t": "持斧以为威权"}, {"w": "杖楫", "t": "持杖"}, {"w": "杖斧之臣", "t": "掌握兵权的武臣"}, {"w": "杖策", "t": "执马鞭"}, {"w": "杖节", "t": "执持旌节。"}]}, {"meaning": "凭倚;依靠。", "cites": [{"t": "杖信以待晋,不亦可乎?", "b": "《左传·襄公八年》"}, {"t": "近臣已下足杖矣。", "b": "《汉书·李寻传》"}, {"t": "仗父兄之烈。", "b": "《资治通鉴》"}, {"t": "仗舟楫。", "b": ""}, {"t": "仗汝扶持。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "杖力", "t": "依靠武力"}, {"w": "杖仁", "t": "依仗仁德"}, {"w": "杖任", "t": "依靠,信任"}, {"w": "杖威", "t": "凭恃权威"}, {"w": "杖信", "t": "凭靠信义。"}]}, {"meaning": "用棍子打;拷打 。自隋开皇新律始定为五刑(笞、杖、徒、流、死)之一。用大荆条、大竹板或棍棒抽击人的背、臀或腿部。", "cites": [{"t": "尝受守杖。", "b": "明·高启《书博鸡者事》"}, {"t": "杖汝。", "b": ""}, {"t": "杖之百。", "b": "《明史》"}, {"t": "予之杖。", "b": ""}, {"t": "宰严限追比,旬余,杖至百,两股间脓血流离。", "b": "《聊斋志异·促织》"}, {"t": "杖其背。", "b": "明·高启《书博鸡者事》"}, {"t": "杖杀其父", "b": ""}], "words": [{"w": "杖楚", "t": "以棍棒拷打"}, {"w": "自杖三十;杖牛", "t": "打春牛"}, {"w": "杖徒", "t": "五刑之。用大竹板、棍棒、荆条抽打犯人背部"}, {"w": "杖钱", "t": "给施杖刑衙役的贿赂钱"}, {"w": "杖刑", "t": "古代刑罚之一。用荆条拷打犯人"}, {"w": "杖治", "t": "以杖刑治罪。"}]}, {"meaning": "拄着。", "cites": [{"t": "必操几杖以从之。", "b": "《礼记·曲礼上》"}, {"t": "杖名齐其心。", "b": "《仪礼·丧服》"}, {"t": "杖汉节牧羊。", "b": "《汉书·苏武传》"}, {"t": "遥望老子杖藜而来。", "b": "《中山狼传》"}, {"t": "五十杖于家,六十杖于乡,七十杖于国,八十杖于朝。", "b": "《礼记·王制》"}]}, {"meaning": "手杖(走路时手里拄着的棍子,俗称“拐杖”)。", "cites": [{"t": "必操几杖以从之。", "b": "《礼记·曲礼》"}, {"t": "植其杖而芸。", "b": "《论语·微子》"}, {"t": "扶杖望朱砂庵。", "b": "《徐霞客游记·游黄山记》"}, {"t": "落吾杖底", "b": ""}], "words": [{"w": "锡杖", "t": "佛教的杖形法器,头部装有锡环"}, {"w": "魔杖", "t": "魔术师所用的棍儿"}, {"w": "杖者", "t": "指老年人"}, {"w": "杖几", "t": "拐杖与几案"}, {"w": "杖父", "t": "拄杖老人。"}]}, {"meaning": "泛指棍棒或棒状物。", "cites": [{"t": "球惊杖奋合且离,红牛缨绂黄金羁。", "b": "韩愈《汴泗交流赠张仆射》"}], "words": [{"w": "杖棒", "t": "棍棒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('684wx','杏','1','xìng','木','7','','[{"pinyin": "xìng", "defs": [{"meaning": "木名。杏树 。一种落叶乔木,叶子宽卵形,花单性,白色或粉红色,果实圆形,成熟时黄红色,味酸甜。", "cites": [{"t": "杏,杏果也。从木,可省声。", "b": "《说文》。按,尚省声。"}, {"t": "五沃之土,其木宜杏。", "b": "《管子》"}, {"t": "孔子游缁帷之林,坐杏坛之上。", "b": "《庄子》"}, {"t": "桃李梅杏,楂梨姜桂。", "b": "《礼记·内则》"}], "words": [{"w": "杏苑", "t": "杏树园林;泛指新科进士游宴处"}, {"w": "杏林", "t": "见杏田典故。以杏林代指良医,并以“杏林春满”、“誉满杏林”等称颂医术高明"}, {"w": "杏林得意", "t": "借指进士及第。"}]}, {"meaning": "杏花。", "cites": [{"t": "桃未芳菲杏未红,冲寒先喜笑东风。", "b": "《红楼梦》"}], "words": [{"w": "杏雨", "t": "杏花雨"}, {"w": "杏腮", "t": "指杏花"}, {"w": "杏装", "t": "杏花的装扮。指粉红色"}, {"w": "杏殇", "t": "杏的花苞凋落。喻婴儿夭折"}, {"w": "杏靥", "t": "指杏花。"}]}, {"meaning": "杏仁。", "cites": [{"t": "杏粥犹堪食,榆羹已稍煎。", "b": "《清明日忆诸弟》"}], "words": [{"w": "杏丹", "t": "方士以杏仁为主要原料所制的一种成药。传说食之能令人颜色美好"}, {"w": "杏酪", "t": "杏仁粥。古代多为寒食节食品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('685wx','杉','1','shā shān','木','7','','[{"pinyin": "shā", "defs": [{"meaning": "义同“杉”(shān),用于“杉篙”“杉木”。"}]}, {"pinyin": "shān", "defs": [{"meaning": "", "words": [{"w": "水杉;红杉;紫杉", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('686wx','巫','1','wū','工','7','','[{"pinyin": "wū", "defs": [{"meaning": "(象形。据甲骨文,象古代女巫所用的道具。小篆象女巫两袖舞形。本义:古代称能以舞降神的人)。"}, {"meaning": "同本义。", "cites": [{"t": "巫,祝也。女能事无形,以舞降神者也。", "b": "《说文》"}, {"t": "一驼背巫。", "b": "《聊斋志异·促织》"}, {"t": "巫从旁望空。", "b": ""}, {"t": "巫医乐师百工之人。", "b": "唐·韩愈《师说》"}]}, {"meaning": "商代的巫地位较高。周时分男巫、女巫,司职各异,同属司巫。春秋以后,医道渐从巫术中分出。", "cites": [{"t": "然疑家巫有蔡妪者。", "b": "《韩非子·外储说右上》"}, {"t": "今巫祝之祝人曰:“使若千秋万岁。”", "b": "《韩非子·显学》"}, {"t": "其人家有好女者,恐大巫祝为河伯取之。", "b": "《史记·滑稽列传》"}], "words": [{"w": "巫女", "t": "巫婆,巫妪。女巫;也指巫山上的神女"}, {"w": "巫史", "t": "古代为人问神鬼报功祈福,并转达鬼神降福之意的人。即巫祝"}, {"w": "巫尪", "t": "古代祈雨女巫"}, {"w": "巫步", "t": "巫师道士作法时的一种步法"}, {"w": "巫东由人", "t": "马来人"}, {"w": "巫神自荐", "t": "比喻女子主动求爱"}, {"w": "巫蛊厌睐", "t": "迷信人通过诅咒或祈祷鬼神加祸于人。"}]}, {"meaning": "巫州 。唐代设置,治所在今湖南省黔阳西南黔城镇。"}, {"meaning": "古县名 。秦设置。汉因之。治所在今四川省巫山县东。"}, {"meaning": "巫山。"}, {"meaning": "在今山东省肥城县西北。"}, {"meaning": "另在湖南省城步县东。", "cites": [{"t": "[城步县] 又有巫山,以巫水所出也。", "b": "清·顾祖禹《读史方舆纪要》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('687wx','极','1','jí','木','7','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从木,亟声。本义:房屋的正梁)。"}, {"meaning": "同本义。", "cites": [{"t": "極,栋也。", "b": "《说文》。按,在屋之正中至高处。"}, {"t": "万载宫极。", "b": "《汉书·天文志》"}, {"t": "有夫妻臣妾登极。", "b": "《庄子·则阳》。司马注:“屋栋也。”"}, {"t": "茂初在广汉,梦坐大殿,极上有三穗禾,茂跳取之,得其中穗,辄复失之。", "b": "《后汉书·蔡茂传》"}]}, {"meaning": "最高的地位。", "cites": [{"t": "今以三寸之舌,为帝者师,封万户,位列侯,此布衣之极,于良足矣。", "b": "《史记·留侯世家》"}], "words": [{"w": "极峰", "t": "最高层的官员。"}]}, {"meaning": "特指君位。", "cites": [{"t": "建用皇极。", "b": "《书·洪范》"}], "words": [{"w": "登极", "t": "登君位。"}]}, {"meaning": "顶点,最高处;最高最远的处所。", "cites": [{"t": "不知便可登峰造极不?", "b": "《世说新语·文学》"}, {"t": "屋极有窗。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "登峰造极;极巅", "t": "山顶端"}, {"w": "极至", "t": "极度,极顶。顶点"}, {"w": "极峰", "t": "最高层的官员。"}]}, {"meaning": "尽头;极限。", "cites": [{"t": "何使我至于此极也!(极,指最痛苦的地步。)", "b": "《孟子·梁惠王上》"}, {"t": "至治之极。", "b": "《史记·货殖列传》"}], "words": [{"w": "极地", "t": "绝处"}, {"w": "极界", "t": "界限"}, {"w": "极际", "t": "边际,尽头"}, {"w": "极尽", "t": "终点,尽头"}, {"w": "极则必反", "t": "事物发展到极端,就会向相反的方面转化。"}]}, {"meaning": "地球的南北两端 。如:极流(从地球南北极移向赤道的潮流);极光;极冠。又指磁体的两端;电源或电器上电流的输入输出端。如:南极;北极;正极;负极。"}, {"meaning": "北极星。", "cites": [{"t": "譬众星之环极。", "b": "张衡《西京赋》"}], "words": [{"w": "极枢", "t": "指北极星和天枢星。"}]}, {"meaning": "最高准则、标准。", "cites": [{"t": "莫匪尔极。", "b": "《诗·周颂·思文》"}, {"t": "立名者,行之极也。", "b": "司马迁《报任安书》"}]}, {"meaning": "最,非常,狠,满。", "cites": [{"t": "初极狭。", "b": "晋·陶渊明《桃花源记》"}, {"t": "极为神速。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "备极欢洽。", "b": "《广东军务记》"}, {"t": "极盛于十六世纪。", "b": "蔡元培《图画》"}], "words": [{"w": "极荷", "t": "深深承蒙"}, {"w": "极通", "t": "很对"}, {"w": "极打", "t": "狠打,痛打。"}]}, {"meaning": "至,到达。", "cites": [{"t": "意有所极,梦亦同趣。", "b": "柳宗元《永州八记》"}]}, {"meaning": "极天际地(直达天边,遍及大地。形容广大无边);极天爬地(用尽一切办法);极明(直至天明);极格(及格。达到标准);极海(至海);极晨(直到次日清晨)。"}, {"meaning": "穷尽,竭尽。", "cites": [{"t": "平原远而极目兮。", "b": "王粲《登楼赋》"}, {"t": "不得极夫游之乐。(极,使尽,使动用法。夫,指示代词,那。)", "b": "宋·王安石《游褒禅山记》"}, {"t": "南极潇湘。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "极力为之。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "极情尽致(感情充沛,神态逼真);极望(尽目所见,放眼远望);极言(尽言无余);极目(穷尽目力,眺望远方)。"}, {"meaning": "惩罚,诛杀。", "cites": [{"t": "子之罪大极重。", "b": "《庄子·盗跖》。《尔雅·释言》:殛,诛也。言罪大而诛重也。极、殛古字通。"}, {"t": "故至治之国,有赏罚,而无喜怒,故圣人极。", "b": "《韩非子·用人》"}], "words": [{"w": "极法", "t": "极刑。死刑;重刑。"}]}, {"meaning": "到达极点。", "cites": [{"t": "感极而悲者矣。", "b": "范仲淹《岳阳楼记》"}, {"t": "所得表众,亦极七八万耳。(极,至多,最多,动词状语。)", "b": "《资治通鉴》"}]}, {"meaning": "最高的、最远的,达到极点的。", "cites": [{"t": "地势极而南溟深。", "b": "王勃《滕王阁赋》"}, {"t": "是以就极刑而无愠色。", "b": "司马迁《报任安书》"}, {"t": "极天云一线。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": ""}, {"meaning": "急速。", "cites": [{"t": "予不敢不极卒宁王图事。", "b": "《书·大诰》"}, {"t": "队有急,极发其近者往佐。", "b": "《墨子·杂守》"}, {"t": "诸侯假之威久而不知极已者殆。", "b": "《管子·枢言》"}, {"t": "无羽无翼,反复甚极。", "b": "《荀子·赋篇》"}], "words": [{"w": "极走", "t": "急促地奔跑"}, {"w": "极言", "t": "急忙告诉"}, {"w": "极卒", "t": "尽快完成。"}]}, {"meaning": "屡次,一再。", "cites": [{"t": "以极聘于诸侯。", "b": "《管子·小匡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('688wx','李','1','lǐ','木','7','','[{"pinyin": "lǐ", "defs": [{"meaning": "(形声。从木,子声。本义:李树)。"}, {"meaning": "同本义。落叶乔木,春天开白色花,果实叫李子,熟时黄色或紫红色,可吃。", "cites": [{"t": "李,李果也。", "b": "《说文》"}, {"t": "北山有李。", "b": "《诗·小雅·南山有台》"}]}, {"meaning": "(李:李花)。", "cites": [{"t": "报之以李。", "b": "《诗·大雅·抑》"}]}, {"meaning": "(李:李子)。", "cites": [{"t": "丘中有李。", "b": "《诗·王风·丘中有麻》"}]}, {"meaning": "(李:李园)。"}, {"meaning": "狱官", "cites": [{"t": "皋陶为李。", "b": "《管子·法法》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('689wx','杨','1','yáng','木','7','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从木,昜(yáng)声。本义:植物名。落叶乔木)。"}, {"meaning": "杨柳科杨属植物的泛称。", "cites": [{"t": "杨,杨木也。", "b": "《说文》"}, {"t": "杨,蒲柳。", "b": "《尔雅》"}, {"t": "杨与柳别。杨,枝劲脆而短,叶圆阔而尖;柳,叶长而狭,枝软而韧。", "b": "清·朱骏声《说文通训定声》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('690wx','求','1','qiú','水','7','','[{"pinyin": "qiú", "defs": [{"meaning": "(《说文》以“求”为“裘”之古文。省衣,象形。金文与战国古文作“求”。本是“裘衣”的“裘”。古人皮衣一般毛朝外,所以甲骨文在“衣”字外加毛。表示裘衣。本义:皮衣)。"}, {"meaning": "“裘”的古字。皮衣。", "cites": [{"t": "乐正求。", "b": "《汉书》"}]}, {"meaning": "请求;干请;乞助。", "cites": [{"t": "求,乞也。", "b": "《增韵》"}, {"t": "因留怀王以求割地。", "b": "《史记·屈原列传》"}, {"t": "求救于齐。", "b": "《战国策·赵策》"}, {"t": "有求于我也。", "b": "《战国策·齐策》"}, {"t": "求其能千里也。", "b": ""}, {"t": "求救于孙将军。", "b": "《资治通鉴》"}], "words": [{"w": "求浼", "t": "请求;央求"}, {"w": "求神福", "t": "祈求神灵保佑;祝福"}, {"w": "求张良,拜韩信", "t": "到处求人;求托有用的人"}, {"w": "求化", "t": "乞求人施舍财物。"}]}, {"meaning": "追求,谋求;寻求;寻找。", "cites": [{"t": "求,索也。", "b": "《玉篇》"}, {"t": "求则得之,舍则失之。", "b": "《孟子·告子上》"}, {"t": "入水求之。", "b": "《吕氏春秋·察今》"}, {"t": "求剑若此。", "b": ""}, {"t": "求人可使报秦者。", "b": "《史记·廉颇蔺相列传》"}, {"t": "不求闻达。", "b": "诸葛亮《出师表》"}, {"t": "求利以污其行。", "b": "《后汉书·列女传》"}, {"t": "求钱之民。", "b": "清·龚自珍《病梅馆记》"}, {"t": "以求钱也。", "b": ""}, {"t": "以求重价。", "b": ""}, {"t": "求太监后。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "求代", "t": "迷信指吊死鬼诱人当“替死鬼”,以求投胎托生"}, {"w": "力求", "t": "极力追求;尽力谋求"}, {"w": "求友", "t": "寻求朋友"}, {"w": "求正", "t": "寻求正道"}, {"w": "求合", "t": "寻求志同道合者"}, {"w": "求采", "t": "搜求选取"}, {"w": "求觅", "t": "寻找"}, {"w": "求访", "t": "寻觅探访。"}]}, {"meaning": "索取。", "cites": [{"t": "我之求也,此何罪?请杀我乎!", "b": "《左传·桓公十六年》"}, {"t": "以城求璧。", "b": "《史记·廉颇蔺相列传》"}, {"t": "空言求璧。", "b": ""}, {"t": "就吾求寒衣。", "b": "《资治通鉴·唐纪》"}, {"t": "忽啼求之。", "b": "宋·王安石《伤仲永》"}]}, {"meaning": "探索。", "cites": [{"t": "不得于言,勿求于心;不得于心,勿求于气。", "b": "《孟子·公孙丑上》"}, {"t": "求思之深。", "b": "宋·王安石《游褒禅山记》"}, {"t": "求古仁人之心。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "责备,责求。", "cites": [{"t": "君子求诸己,小人求诸人。", "b": "《论语·卫灵公》"}]}, {"meaning": "招来。", "cites": [{"t": "求善良。", "b": "《礼记·学记》"}]}, {"meaning": "贪求;贪婪。", "cites": [{"t": "不忮不求。", "b": "《诗·邶风·雄雉》"}]}, {"meaning": "聚合。", "cites": [{"t": "彼交匪敖,万福来求。", "b": "《诗·小雅·桑扈》"}]}, {"meaning": "贿赂。", "cites": [{"t": "阜其财求。", "b": "《国语·周语上》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('691wx','甫','1','fǔ','用','7','','[{"pinyin": "fǔ", "defs": [{"meaning": "(象形。甲骨文字形,象田中有菜苗之形。金文字形,变为从田父声的形声字。本义:苗)。"}, {"meaning": "中国古代对男子的美称。多用于表字之后。", "cites": [{"t": "甫,男子美称也。", "b": "《说文》"}, {"t": "保兹天子,生仲山甫。", "b": "《诗·大雅·丞民》"}, {"t": "天启壬戌秋日,虞山王毅叔远甫刻。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "台甫", "t": "敬辞,旧时用于问人的表字。"}]}, {"meaning": "(fù)。对男性长辈的通称,犹父老。", "cites": [{"t": "曰伯某甫,仲叔季唯所当。", "b": "《仪礼·士冠礼》"}, {"t": "忽兹遇众甫,欲彀羞断弦。", "b": "宋·叶适文"}], "words": [{"w": "众甫", "t": "各位父老。"}]}, {"meaning": "(pǔ)。种植果木瓜菜的园地。", "cites": [{"t": "东有甫草,驾言行狩。", "b": "《诗·小雅·车攻》"}]}, {"meaning": "方才,刚刚。", "cites": [{"t": "瑞抚吴甫半岁。", "b": "《明史·海瑞传》"}, {"t": "部署甫定而外围合。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "年甫二十;甫愈", "t": "刚痊愈"}, {"w": "甫至", "t": "刚到"}, {"w": "甫能", "t": "刚刚能。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('692wx','匣','1','xiá','匚','7','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从匚,甲声。匚(fāng),盛物器。本义:匣子)。"}, {"meaning": "同本义,一般呈方形,大的叫箱,小的叫匣。", "cites": [{"t": "匣,匮也。", "b": "《说文》"}, {"t": "匣,箱匣也。", "b": "《广韵》"}, {"t": "废藏在室匣中者。", "b": "《汉书·王莽传》。注:“匮也。”"}, {"t": "赐东园画棺玉匣衣衾。", "b": "《后汉书·梁竦传》"}, {"t": "忧来杖匣剑,更上林北冈。", "b": "唐·杜甫《又上后园山脚》"}, {"t": "而秦舞阳奉地图匣,以次进。", "b": "《史记·刺客传·荆轲》"}, {"t": "冷光之乍出于匣也(匣,指镜匣)。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "匣子炮", "t": "匣子枪。驳壳枪"}, {"w": "木匣;梳头匣儿;镜匣", "t": "盛梳妆用品的匣子。"}]}, {"meaning": "棺材。", "cites": [{"t": "河街上船总顺顺,派人找了一只空船带了副白木匣子,即刻向碧溪咀撑去。", "b": "沈从文《边城》"}], "words": [{"w": "匣子", "t": ""}]}, {"meaning": "旧时江、浙一带称商业界的一种同行业组织。", "cites": [{"t": "两淮盐政高恒,以侵贪匣费故,拟大辟。", "b": "清·昭梿《啸亭杂录·杀高恒》"}], "words": [{"w": "匣上", "t": "清代谓盐务组织为匣上"}, {"w": "匣费", "t": "盐务款项。"}]}, {"meaning": "用匣子收藏。", "cites": [{"t": "且匣起,青铜休照。", "b": "刘克庄《贺新郎》"}, {"t": "匣而埋诸土(匣,装在匣子里)。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "匣匮", "t": "放在匣柜里"}, {"w": "匣剑", "t": "把宝剑藏在匣里。亦指带剑。"}]}, {"meaning": "夹、锁。", "cites": [{"t": "牢子狱卒把武松押在大牢里,将他一双脚昼夜匣着。", "b": "《水浒传》"}], "words": [{"w": "匣床", "t": "旧时牢狱中使用的一种刑具,形如木床,命囚犯仰卧其上,将手脚紧紧夹住,全身不能转动,痛苦异常。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('693wx','更','1','gēng gèng','曰','7','','[{"pinyin": "gēng", "defs": [{"meaning": "(形声。从攴(pū),“更”的小篆形是个形声字。丙声。 本义:改变)。"}, {"meaning": "同本义。", "cites": [{"t": "更,改也。", "b": "《说文》"}, {"t": "更也,人皆仰之。", "b": "《论语·子张》"}, {"t": "更爵洗。", "b": "《仪礼·大射仪》"}, {"t": "更皮币。", "b": "《礼记·月令》"}, {"t": "更姓改物。", "b": "《国语·周语》"}, {"t": "应国之称号亦更矣。", "b": "《管子·侈靡》"}, {"t": "国更立法以典民则祥。", "b": "《管子·任法》"}, {"t": "更葬也。", "b": "《史记·晋世家》"}, {"t": "景公欲更晏子之宅。", "b": "《晏子春秋·内篇杂下》"}, {"t": "将军若能翻然改图,易迹更步,古人不难追,鄙士何足宰哉!", "b": "《三国志·吕凯传》"}, {"t": "曲沃武公已即位三十七年矣,更号曰晋武公。", "b": "《史记·晋世家》"}], "words": [{"w": "更故", "t": "更改;变改"}, {"w": "更号", "t": "改变名位与称号"}, {"w": "更步", "t": "改变行止"}, {"w": "更元", "t": "更改年号"}, {"w": "更移", "t": "变迁;改变"}, {"w": "更徙", "t": "变迁"}, {"w": "更法", "t": "变法"}, {"w": "更革", "t": "变革;改革。"}]}, {"meaning": "改,改正。", "cites": [{"t": "此则寡人之罪也,寡人请更。", "b": "《国语·越语上》"}, {"t": "既云常赦,不免皆赦除之,此非直赦其有罪,亦是与天下断,当许其更新(改过自新)。", "b": "《旧唐书·孙伏伽传》"}], "words": [{"w": "更订", "t": "改订;修订"}, {"w": "更议", "t": "改议"}, {"w": "更窜", "t": "窜改,改动。"}]}, {"meaning": "更换;替代。", "cites": [{"t": "更,代也。", "b": "《方言三》"}, {"t": "弗用则更。", "b": "《周礼·司弓矢》"}, {"t": "余将告于莅事者,更若役,复若赋,则何如?", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "良庖岁更刀,割也;族庖月更刀,折也。", "b": "《庄子·养生主》"}], "words": [{"w": "除旧更新", "t": "除去旧的,用新的来代替"}, {"w": "更王", "t": "改换帝王"}, {"w": "更置", "t": "变动,变换"}, {"w": "更调", "t": "调换;改换。"}]}, {"meaning": "经过,经历。", "cites": [{"t": "因欲通使(大月氏),道必更(经过)匈奴中。", "b": "《史记·大宛列传》"}, {"t": "其佐李揖、刘秩等皆儒生,未尝更军旅。", "b": "《新唐书·房琯传》"}], "words": [{"w": "更世", "t": "更事。阅世,经历世事"}, {"w": "更涉", "t": "经历"}, {"w": "更尝", "t": "亲身经历,实际体验"}, {"w": "更履", "t": "经历;遭遇。"}]}, {"meaning": "连续,接续。", "cites": [{"t": "姓利相更。", "b": "《国语·晋语》。注:“续也。”"}], "words": [{"w": "更相", "t": "相继;相互。"}]}, {"meaning": "轮流。", "cites": [{"t": "每有警,辄数月不就寝,使将士更休,而自坐帷幕外。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "更伯", "t": "轮流称霸"}, {"w": "更王", "t": "轮番为主"}, {"w": "更直", "t": "轮番值班"}, {"w": "更徭", "t": "更番戍守边境的徭役。"}]}, {"meaning": "偿还;抵偿。", "cites": [{"t": "功之成也不足以更责。", "b": "《淮南子·诠言训》"}]}, {"meaning": "报,报答。", "cites": [{"t": "不更厥贞,大命其倾。", "b": "《国语·晋语三》"}]}, {"meaning": "(gěng)。阻塞。", "cites": [{"t": "明知千里之外,隐微之中,曰动奸,奸动则变更矣。", "b": "《管子·九守》"}]}, {"meaning": "汉代皇宫中值班人员分五个班次,按时更换,叫“五更”。更鼓。", "cites": [{"t": "先生骨清少眠卧,长夜默坐数更鼓。", "b": "宋·苏轼《夜过舒尧文戏作》"}], "words": [{"w": "更点", "t": "指更鼓之声"}, {"w": "更钥", "t": "放置报时更鼓处的钥匙。"}]}, {"meaning": "量词。旧时夜间计时单位,一夜分为五更,每更约两小时。", "cites": [{"t": "中有双飞鸟,自名为鸳鸯,仰头相向鸣;夜夜达五更。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "半夜三更", "t": ""}]}]}, {"pinyin": "gèng", "defs": [{"meaning": "表示动作行为的重复,相当于“再”、“复”、“又”。", "cites": [{"t": "欲穷千里目,更上一层楼。", "b": "唐·王之涣《登鹳雀楼》"}, {"t": "数千里外,得长者时赐一书,以慰长想,即亦甚幸矣;何至更辱馈遗,则不才益将何以报焉?", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "更无六耳", "t": "再没有第三人。六耳:第三者的代称"}, {"w": "更若", "t": "再如;倘若"}, {"w": "更待", "t": "再等;再过。"}]}, {"meaning": "表示程度的加深,相当于“更加”、“愈加”、“越发”等。", "cites": [{"t": "加以官贪吏虐,民日贴妇卖儿,更无休止。", "b": "《聊斋志异·促织》"}, {"t": "今日拒之,事更不顺。", "b": "《资治通鉴》"}, {"t": "且以汝之有身也,更恐不胜悲。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "表示在所说的范围之外,相当于另外;也。", "cites": [{"t": "得更求好女,后日送之。", "b": "《西门豹治邺》"}, {"t": "更闻谁氏子,读书时,愿他日得志,廉干如古人某,忠孝如古人某。", "b": "清·周容《芋老人传》"}]}, {"meaning": "表示跟上一层意思相反或出乎意料和常情之外,相当于“反而”“竟然”“还是”。", "cites": [{"t": "谓言无罪过,供养卒大恩;仍更被驱遣,何言复来还!", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "与,和。", "cites": [{"t": "着尽工夫是化工,不关春雨更春风。", "b": "宋·杨万里《春兴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('694wx','束','1','shù','木','7','','[{"pinyin": "shù", "defs": [{"meaning": "(会意。从囗(weí)木。在木上加圈,象用绳索把木柴捆起来。本义:捆绑)。"}, {"meaning": "同本义。", "cites": [{"t": "束,缚也。", "b": "《说文》"}, {"t": "束帛戋戋。", "b": "《易·贲》。子夏传:“五匹为束。”"}, {"t": "束帛俪皮。", "b": "《仪礼·士冠礼》。注:“十端也。”"}, {"t": "贿荀偃束锦。", "b": "《左传·襄公十九年》"}, {"t": "入束矢于朝。", "b": "《周礼·大司寇》"}, {"t": "自行束脩以上。", "b": "《论语》"}, {"t": "墙有茨,不可束也。", "b": "《诗·鄘风·墙有茨》"}, {"t": "则束载厉兵秣马矣。", "b": "《左传·僖公三十三年》"}, {"t": "若业为吾所有,必高束焉。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "束刃", "t": "捆扎兵器"}, {"w": "束刍", "t": "捆成一束的干草"}, {"w": "束戈卷甲", "t": "捆起兵器甲胄。谓缴械投降"}, {"w": "束手", "t": "捆绑双手"}, {"w": "束火,束炬", "t": "扎火把"}, {"w": "束手束脚", "t": "捆住手脚。形容胆子小,顾虑多"}, {"w": "束竹", "t": "捆成束的竹子"}, {"w": "束杖", "t": "捆起来的刑具"}, {"w": "束载", "t": "捆物装车。"}]}, {"meaning": "约束;限制。", "cites": [{"t": "强自取柱,柔自取束。", "b": "《荀子·劝学》"}, {"t": "空名束壮士。", "b": "李白《留别广陵诸公》"}], "words": [{"w": "检束", "t": "检点约束"}, {"w": "束累", "t": "约束牵累"}, {"w": "束躬", "t": "约束自己,检点"}, {"w": "束约", "t": "管束;控制"}, {"w": "束持", "t": "约束持重"}, {"w": "束制", "t": "约束克制。"}]}, {"meaning": "收拾;整理。", "cites": [{"t": "去者束装以待期,妻子鹤望而计日。", "b": "《三国志》注"}], "words": [{"w": "束甲", "t": "卷起盔甲,轻装急进。表示要决一死战"}, {"w": "束箧", "t": "收拾行装"}, {"w": "束兵秣马", "t": "整顿军队,喂饱战马,形容准备战斗"}, {"w": "束囊", "t": "收拾行装"}, {"w": "束担", "t": "收拾行李。"}]}, {"meaning": "搁置。", "cites": [{"t": "束书不观,游谈无根。", "b": "苏轼《李氏山房藏书记》"}]}, {"meaning": "把,小捆。", "cites": [{"t": "生刍(草)一束。", "b": "《诗·小雅·白驹》"}], "words": [{"w": "一束花", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('695wx','吾','1','wú','口','7','','[{"pinyin": "wú", "defs": [{"meaning": "(形声。从口,五声。本义:我)。"}, {"meaning": "同本义。", "cites": [{"t": "吾,我自称也。", "b": "《说文》"}, {"t": "吾,我也。", "b": "《尔雅·释诂》"}, {"t": "愿吾子之教之也。", "b": "《仪礼·士冠礼》"}, {"t": "吾将镇之以无名之朴。", "b": "《老子》"}, {"t": "莫吾知兮。", "b": "《楚词·屈原·涉江》"}, {"t": "毋吾以也。", "b": "《论语·先进》"}, {"t": "不吾知也。", "b": ""}]}, {"meaning": "按,在上古时代,“吾”和“我”在语法上有别,吾不用于动词后作宾语。", "cites": [{"t": "今者吾丧我。", "b": "《庄子·齐物论》"}], "words": [{"w": "吾侪", "t": "我等,我辈,我们"}, {"w": "吾当", "t": "我"}, {"w": "吾侬", "t": "我"}, {"w": "吾谁与归", "t": "我将从谁"}, {"w": "吾爱", "t": "我所爱的人"}, {"w": "吾兄", "t": "对朋友的称呼;称自己的兄长"}, {"w": "吾祖", "t": "我的祖先"}, {"w": "吾与", "t": "我的同伴、同伙"}, {"w": "吾庐", "t": "我的住所"}, {"w": "吾党", "t": "我的同乡;吾辈。"}]}, {"meaning": "抵御。", "cites": [{"t": "厚攻则吾,薄攻则薄吾。", "b": "《墨子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('696wx','豆','1','dòu','豆','7','','[{"pinyin": "dòu", "defs": [{"meaning": "(象形。甲骨文字形,形似高脚盘,或有盖。汉字部首之一,从“豆”的字或与食器有关。或与豆类有关。本义:古代一种盛食物的器皿)。"}, {"meaning": "同本义。形似高足盘,或有盖。新石器时代晚期开始出现,盛行于商周时,多陶制,也有青铜制或木制涂漆的。后世也作礼器。", "cites": [{"t": "豆,古食肉器也。", "b": "《说文》"}, {"t": "卬盛于豆。", "b": "《诗·大雅·生民》"}]}, {"meaning": "又。", "cites": [{"t": "于豆于登。", "b": ""}, {"t": "笾豆大房。", "b": "《诗·鲁颂·閟宫》"}, {"t": "木豆谓之豆,竹豆谓之笾,瓦豆谓之登。", "b": "《尔雅》"}, {"t": "食一豆肉,中人之食也。", "b": "《周礼·考工记》"}, {"t": "若所市于人者,将以实笾豆奉祭祀、供宾客乎?", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "豆俎", "t": "指古代祭祀用的礼器"}, {"w": "豆笾", "t": "古代宴会和祭祀时盛放食物的器皿。木制的叫豆,竹制的叫笾。"}]}, {"meaning": "古代容器 。亦为容量单位,四升为一豆。", "cites": [{"t": "四升为豆。", "b": "《左传·昭公三年》"}], "words": [{"w": "豆登", "t": "古代盛器,亦用作祭器。登似豆而较浅。"}]}, {"meaning": "“豆”假借为“菽”,豆类植物的总称。", "cites": [{"t": "大儿锄豆溪东,中儿正织鸡笼。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "四月时雨降,可种大小豆", "b": "后魏·贾思勰《齐民要术·种豆》"}], "words": [{"w": "扁豆;黑豆;豆觞", "t": "豆肉觞酒的简称"}, {"w": "豆腐饭", "t": "旧称家常便饭"}, {"w": "豆腐牌儿", "t": "卖豆腐的布招"}, {"w": "豆糜", "t": "煮豆为粥"}, {"w": "豆苗", "t": "豆的幼苗"}, {"w": "豆剖瓜分", "t": "比喻疆土分裂"}, {"w": "豆秧", "t": "豆的幼苗"}, {"w": "豆藤", "t": "豆类植物中蔓生种的茎杆。"}]}, {"meaning": "古代重量单位 。十六黍为一豆,六豆为一铢,二十四铢重一两,十六两为一斤。", "cites": [{"t": "十六黍为一豆。", "b": "《说苑辨物》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('697wx','两','1','liǎng','一','7','','[{"pinyin": "liǎng", "defs": [{"meaning": "(会意。从一,兩平分。兩亦声。本义:二十四铢为一两)。"}, {"meaning": "同本义  16两为1斤。今市制折合国际单位制0。05千克,十钱一两,十两一斤。", "cites": [{"t": "两,二十四铢为一两。", "b": "《说文》"}, {"t": "衡权…本起于黄钟之重。一龠容千二百黍,重十二铢,两之为两,二十四铢为两,十六两为斤。…两者,两黄钟律之重也。", "b": "《汉书·律历志上》"}]}, {"meaning": "双。用于鞋娄。", "cites": [{"t": "一两棕鞋八尺藤,广陵行遍又金陵。", "b": "唐·戴叔伦《忆原上人》"}]}, {"meaning": "匹(长四丈)。", "cites": [{"t": "归夫人鱼轩,重锦三十两。", "b": "《左传·闵公二年》"}]}, {"meaning": "车一乘。", "cites": [{"t": "武王戎车三百两。", "b": "《书·牧誓·序》"}, {"t": "之子于归,百两御之。", "b": "《诗·召南·鹊巢》"}]}, {"meaning": "二。", "cites": [{"t": "参天两地而倚数。", "b": "《易·说卦》"}, {"t": "以九两系邦国之民。", "b": "《周礼·天官·大宰》。注:“两,犹耦也。”"}, {"t": "两小儿辩斗。", "b": "《列子·汤问》"}, {"t": "陈胜佐之,并杀两尉。", "b": "《史记·陈涉世家》"}, {"t": "途中两狼。", "b": "《聊斋志异·狼三则》"}, {"t": "两军人马。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "两骑来是谁。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "两个人;两扇门;两夫妻;两头猪;两没", "t": "两者一起死亡"}, {"w": "两肉", "t": "两只牛"}, {"w": "两替", "t": "两批"}, {"w": "两考", "t": "官吏的两次考绩"}, {"w": "两榜(明清以会试(考进士)为甲榜,乡试(考举人)为乙榜,由举人考中进士,叫两榜进士,简称“两榜”)", "t": ""}]}, {"meaning": "双方;常用于相对的两个方面或成对的人或事物。", "cites": [{"t": "则以法刑断其两足而黥之。", "b": "《史记·孙子吴起列传》"}, {"t": "今兄弟遘恶,此势不两全。", "b": "《三国志·魏志》"}, {"t": "两儿齐哭。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "两股战战。", "b": ""}, {"t": "两鬓苍苍。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "势不两立;两败俱伤;两相情愿;两袒", "t": "袒露双肩,女子兼适两夫家"}, {"w": "两珥", "t": "指日、月两旁的光晕"}, {"w": "两阵", "t": "亦两阵。交战的双方所布列的阵势"}, {"w": "两握", "t": "指双拳"}, {"w": "两视", "t": "同时看两件事物"}, {"w": "两雄", "t": "两者一起强大"}, {"w": "两仪", "t": "指天地"}, {"w": "两交婚", "t": "两家的儿女相互娶嫁为婚。"}]}, {"meaning": "表示不定数,多与“一”或“三”前后连用,义为少量。", "cites": [{"t": "两三点雨山前。", "b": "宋·辛弃疾《西江月》"}, {"t": "竹外桃花三两枝。", "b": "宋·苏轼《惠崇春江晚景》"}, {"t": "拨弦三两声。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "两三", "t": "几个。表示少量"}, {"w": "两言", "t": "三言两语。"}]}, {"meaning": "同时兼具两方面,双方,两下里。", "cites": [{"t": "目不能两视而明,耳不能两听而聪。", "b": "《荀子·劝学》"}], "words": [{"w": "两兼", "t": "兼具两方面"}, {"w": "两礼", "t": "双方免礼"}, {"w": "两誉", "t": "夸奖双方"}, {"w": "两让", "t": "双方各自责让。"}]}, {"meaning": "等同;比并。", "cites": [{"t": "御下,两马,掉鞅。", "b": "《左传》"}], "words": [{"w": "两大", "t": "两者并大"}, {"w": "两帝", "t": "两个天子并立"}, {"w": "两当", "t": "两者相当。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('698wx','酉','1','yǒu','酉','7','','[{"pinyin": "yǒu", "defs": [{"meaning": "(象形。金文字形,象酒坛形。“酉”是汉字的一个部首,从“酉”的字多与酒或因发酵而制成的食物有关。本义:酒)。"}, {"meaning": "同本义。", "cites": [{"t": "酉,就也。八月黍成,可为酎酒。", "b": "《说文》。按,酉即酒字,象酿器形,中有实。"}, {"t": "二在天下为酉。", "b": "《颜氏家训·书证》引诗说"}], "words": [{"w": "酉泽", "t": "酿造精熟的酒。"}]}, {"meaning": "地支的第十位。"}, {"meaning": "与天干相配,或在太岁纪年法中用以纪年。如1945年为农历乙酉年。"}, {"meaning": "用以纪月,即农历八月。"}, {"meaning": "用以纪日。"}, {"meaning": "十二生肖之一。属鸡。"}, {"meaning": "成熟;老。", "cites": [{"t": "酉者,老也。", "b": "《白虎通·五行》"}], "words": [{"w": "酉黍", "t": "成熟的禾谷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('699wx','丽','1','lí lì','一','7','','[{"pinyin": "lí", "defs": [{"meaning": "遭遇;落入。", "cites": [{"t": "鱼丽于罶。", "b": "《诗·小雅·鱼丽》"}]}]}, {"pinyin": "lì", "defs": [{"meaning": "(形声。从鹿,丽声。其字本作“丽”,后加“鹿”,成为形声字。鹿形丽声,鹿成对,并驾。本义:成群;结伴;成对)。"}, {"meaning": "成对", "cites": [{"t": "丽,两也。", "b": "《小尔雅·广言》"}, {"t": "丽钩芒与骖蓐收兮。", "b": "《汉书·扬雄传上》。师古曰:“丽,并驾也。”"}, {"t": "丽马一圉。", "b": "《周礼·夏官·校人》"}, {"t": "良马五之。", "b": "《诗·鄘风·干旄》。孔颖达疏引三国魏·王肃曰:“夏后氏驾两谓之丽。”"}, {"t": "自扬、马、张、蔡,崇盛丽辞。", "b": "刘勰《文心雕龙》"}], "words": [{"w": "丽限", "t": "指期限的上限与下限"}, {"w": "丽偶", "t": "对偶"}, {"w": "丽辞", "t": "对偶的辞句"}, {"w": "丽泽", "t": "两个沼泽相连。"}]}, {"meaning": "美丽,漂亮。", "cites": [{"t": "状貌甚丽。", "b": "《史记·平津侯主父列传》"}, {"t": "妻子衣服丽都。", "b": "《战国策·齐策》"}, {"t": "天生丽质难自弃。", "b": "白居易《长恨歌》"}, {"t": "长安水边多丽人。", "b": "杜甫《丽人行》"}], "words": [{"w": "壮丽", "t": "雄壮而美丽"}, {"w": "秀丽", "t": "清秀美丽"}, {"w": "丽象", "t": "美丽的景象"}, {"w": "丽姝", "t": "亦称姝丽。美女"}, {"w": "丽春园", "t": "又叫丽春院。相传是名妓苏卿的住处,后因以称妓院或艺妓、歌女的住处。"}]}, {"meaning": "华丽,华靡。", "cites": [{"t": "恶丽靡而不近,斥芬芳而不御。", "b": "《汉书·扬雄传下》"}, {"t": "绮丽之艳说。", "b": "刘勰《文心雕龙》"}], "words": [{"w": "丽句", "t": "绮靡的文句"}, {"w": "丽则", "t": "佳美而失法度"}, {"w": "丽尔", "t": "华丽"}, {"w": "丽谯", "t": "壮丽的高楼"}, {"w": "丽靡", "t": "奢靡华丽。"}]}, {"meaning": "猛烈。", "cites": [{"t": "西北曰厉风。", "b": "《淮南子·地形》"}]}, {"meaning": "结伴而行。", "cites": [{"t": "若其五县游丽辩论之士,街谈巷议,弹射臧否。", "b": "汉·张衡《西京赋》"}]}, {"meaning": "依附;附着。", "cites": [{"t": "日月丽乎天,百谷草木丽乎土。", "b": "《易·离》"}, {"t": "丽土之毛。", "b": "徐光启《甘薯疏序》"}], "words": [{"w": "丽水", "t": "附着于水中"}, {"w": "丽霄", "t": "附着在天空"}, {"w": "丽紫", "t": "着上紫色。"}]}, {"meaning": "施;加。", "cites": [{"t": "越兹丽刑。", "b": "《书·吕刑》"}], "words": [{"w": "丽兵", "t": "将武器施加于人。"}]}, {"meaning": "射中。", "cites": [{"t": "射麋丽龟。", "b": "《左传·宣公十二年》"}], "words": [{"w": "丽龟", "t": "射中禽兽中心脊椎。"}]}, {"meaning": "依托。", "cites": [{"t": "人无所丽。", "b": "《后汉书·张衡传》"}]}, {"meaning": "系;拴。", "cites": [{"t": "君牵牲,…既入庙门,丽于碑。", "b": "《礼记·祭义》"}]}, {"meaning": "遭遇。", "cites": [{"t": "鱼丽于罶。", "b": "《诗·小雅·鱼丽》"}]}, {"meaning": "数,数目。", "cites": [{"t": "商之孙子,其丽不亿。(不止十万。)", "b": "《诗·大雅·文王》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('700wx','医','1','yī','匚','7','','[{"pinyin": "yī", "defs": [{"meaning": "(会意兼形声。从匚(fāng),从矢,矢亦声。《说文》:“盛弓弩矢器也。”“醫”,会意,从“殹”(yī),从酉(yǒu)。“殹”,治病时的扣击声。“酉”,用以医疗的酒。二字各有本义,今用“医”为简体字。本义:治病的人)。"}, {"meaning": "同本义。", "cites": [{"t": "医,治 病工也。殹,恶姿也。醫之性得酒而使。", "b": "《说文》"}, {"t": "将免者以告,公令医守之。", "b": "《国语·越语》"}, {"t": "不可以作巫医。", "b": "《论语》"}, {"t": "譬之若良医。", "b": "《吕氏春秋·察今》"}, {"t": "驰召医。", "b": "《汉书·李广苏建传》"}, {"t": "又无医药。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "医国", "t": "指良医"}, {"w": "医家有割股之心", "t": "喻医生有治病救人的虔诚愿望"}, {"w": "缺医少药;医家", "t": "医生,医学家"}, {"w": "医师", "t": "官名。为众医之长"}, {"w": "医婆", "t": "女医师"}, {"w": "医人", "t": "医生"}, {"w": "医工", "t": "原为官名,指医官。后泛指一般医生"}, {"w": "医流", "t": "医生,医家"}, {"w": "医算", "t": "医生和卜人"}, {"w": "医巫", "t": "治病的人。古代医生往往兼用巫术治病,故称。"}]}, {"meaning": "医术;医学。", "cites": [{"t": "原来尊夫人懂得医理,明日就请来看看罢。", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "医手", "t": "医术高明者"}, {"w": "行医;学医;医王", "t": "医术极精的人。多用以比喻诸佛或高僧等"}, {"w": "医部", "t": "医学书籍"}, {"w": "医理", "t": "医学道理或理论"}, {"w": "医道", "t": "医术。"}]}, {"meaning": "治疗,治愈。", "cites": [{"t": "聚毒药以共医事。", "b": "《周礼》"}], "words": [{"w": "医药局", "t": "集防疫、治疗、司药为一体的医疗机构"}, {"w": "医缘", "t": "迷信的人认为疾病好坏与医药有命定的关系,称作医缘"}, {"w": "医济", "t": "医治。"}]}, {"meaning": "救治。", "cites": [{"t": "上医医国,其次疾人。", "b": "《国语》"}], "words": [{"w": "医国", "t": "比喻救治国家。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('701wx','辰','1','chén','辰','7','','[{"pinyin": "chén", "defs": [{"meaning": "(象形。金文字形,是蛤蚌壳之类软体动物的形象,“蜃”的本字。后经假借而产生了其他用法。本义;蛤蚌之类的软体动物)。"}, {"meaning": "同本义。", "cites": [{"t": "辰,有身也。", "b": "《说文》"}, {"t": "辰者,言万物之蜃也。", "b": "《史记·律书》"}]}, {"meaning": "十二地支的第五位。"}, {"meaning": "在太岁纪年法中与天干相配用以纪年。如1976年为农历丙辰年。"}, {"meaning": "用以纪月,即农历三月。"}, {"meaning": "用以纪日。"}, {"meaning": "时光;日子。", "cites": [{"t": "此去经年,应是良辰好景虚设。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "诞辰;辰光", "t": "方言。时候"}, {"w": "辰告", "t": "以时告戒。"}]}, {"meaning": "古地名,即辰州 。今属湖南省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('702wx','励','1','lì','力','7','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从力,厉声。本义:勉力,努力)。"}, {"meaning": "同本义。", "cites": [{"t": "勵,勉力也。", "b": "《说文》。"}, {"t": "用勵相我邦家。", "b": "《书·立政》"}, {"t": "庶明励翼。", "b": "《书·皋谟》"}, {"t": "励于一言。", "b": "《鬼谷子·决篇》"}], "words": [{"w": "砺翼", "t": "勉力辅佐君主,精勤以行君命"}, {"w": "励志", "t": "勉励其心志;集中心思于某种事业"}, {"w": "励节", "t": "勉力志行,崇尚气节。"}]}, {"meaning": "振作。", "cites": [{"t": "处遂改励。", "b": "《世说新语·自新》"}, {"t": "相早励良规。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "励精更始。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "励精", "t": "振作精神。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('703wx','否','1','fǒu pǐ','口','7','','[{"pinyin": "fǒu", "defs": [{"meaning": "(会意。从口,从不。“不”亦兼表字音。本义:不然,不是这样)。", "words": [{"w": "这是妥当的办法吗?否", "t": ""}]}, {"meaning": "非,不是。", "cites": [{"t": "大人否亨。", "b": "《易·否卦》"}, {"t": "否则熟虑而从之。", "b": "《礼记·表记》。注:“谓非己志也。”"}, {"t": "夫建国设都,乃作后王君公,否用泰也。", "b": "《墨子》"}]}, {"meaning": "用在疑问句末,构成是非问句。", "cites": [{"t": "是不必问其果解脱否也。", "b": "清·全祖望《梅花岭记》"}, {"t": "廉颇老矣,尚能饭否?", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "汝知之否", "t": ""}]}]}, {"pinyin": "pǐ", "defs": [{"meaning": "闭塞;阻隔不通。", "cites": [{"t": "否,隔也。", "b": "《广雅》"}, {"t": "否难知也。", "b": "《诗·小雅·何人斯》"}, {"t": "否者,蔽固不通之称。", "b": "《匡谬正俗》"}, {"t": "否者,闭而乱也。", "b": "《汉书·刘向传》"}], "words": [{"w": "否滞", "t": "停滞;阻塞"}, {"w": "否塞", "t": "闭塞不通"}, {"w": "否结", "t": "阻滞,郁结。比喻运数不好"}, {"w": "否隔", "t": "亦作“否鬲”。隔绝不通"}, {"w": "否道", "t": "壅蔽之道"}, {"w": "否闭", "t": "闭塞不通。"}]}, {"meaning": "贬斥。", "cites": [{"t": "每与之言,言皆玄远,未尝臧否人物。", "b": "《世说新语》"}]}, {"meaning": "变坏;灭绝。", "cites": [{"t": "若到天地昏曚而万物否矣。", "b": "《西游记》"}, {"t": "不择善否。", "b": "《庄子·渔父》"}]}, {"meaning": "困厄;不顺。", "cites": [{"t": "执事顺成为臧,逆为否。", "b": "《左传·宣公十二年》"}], "words": [{"w": "否屈", "t": "困顿受挫"}, {"w": "否败", "t": "穷困;时运不好"}, {"w": "否往泰来", "t": "坏运到了尽头,好运就来了"}, {"w": "否而末泰", "t": "时局动荡不安"}, {"w": "否运", "t": "恶运,坏运。"}]}, {"meaning": "恶。", "cites": [{"t": "未知臧否。", "b": "《诗·大雅·抑》"}, {"t": "陟罚臧否,不宜异同。", "b": "诸葛亮《出师表》"}], "words": [{"w": "否心", "t": "邪恶之心"}, {"w": "否德", "t": "卑劣的品德"}, {"w": "否臧", "t": "善恶。"}]}, {"meaning": "鄙陋。", "cites": [{"t": "不善少而否老。", "b": "《庄子·大宗师》"}, {"t": "予所否者,天厌之!天厌之!", "b": "《论语·雍也》"}], "words": [{"w": "否妇", "t": "鄙陋的妇女。"}]}, {"meaning": "病名,胸中满闷结块的病。", "cites": [{"t": "心下否痛。", "b": "《素问·五常政大论》"}], "words": [{"w": "否肿", "t": "痞块肿胀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('704wx','还','1','hái huán','辶','7','','[{"pinyin": "hái", "defs": [{"meaning": "——表示某些语气,有时兼有连接前后分句的作用。“还”表示的语气大体上可以分成平、扬、抑三类。"}, {"meaning": "表示平的语气,不含轻重抑扬的意思。"}, {"meaning": "表示行为动作或状况不变,跟“仍旧、依然”相当。", "cites": [{"t": "白头还戍边。", "b": "唐·杜甫《兵车行》"}, {"t": "取酒还独倾。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "一樽还酹江月。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "还在原位;我的脚还痛", "t": ""}]}, {"meaning": "跟“虽然、尽管”等连用,表示行为状况不因别的条件改变而改变。如:虽然已经宣布散会,人们还在继续争论(表示行为重复,有“重新、再”的意思。如:京剧团明天还演一场)。"}, {"meaning": "表示扬的语气,把事情往大里、高里、重里说。"}, {"meaning": "表示抑的语气,把事情往小里、低里、轻里说。"}, {"meaning": "表示感情为主,意思有的可以用前面三项来解释,但那是次要的。"}]}, {"pinyin": "huán", "defs": [{"meaning": "(形声。从辵(chuó,表示与行走有关),瞏(huán)声。本义:返回)。"}, {"meaning": "同本义。", "cites": [{"t": "还,復也。", "b": "《说文》"}, {"t": "还,返也。", "b": "《尔雅·释言》"}, {"t": "还而不入。", "b": "《诗·小雅·何人斯》"}, {"t": "吾其还也。", "b": "《左传·僖公三十年》"}, {"t": "势还不远,可先为起第。", "b": "《资治通鉴》"}, {"t": "既罢,还内。", "b": ""}, {"t": "还部白府君。(回到府里报告太守。府君,太守。)", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "送儿还故乡。", "b": "《乐府诗集·木兰诗》"}, {"t": "便要还家。", "b": "晋·陶渊明《桃花源记》"}, {"t": "复还终业。", "b": "《后汉书·列女传》"}, {"t": "自南海还。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "还首", "t": "自动回来请罪"}, {"w": "还云", "t": "飘回的云朵;指回信"}, {"w": "还函", "t": "回信"}, {"w": "还转", "t": "回转,返回"}, {"w": "还复", "t": "返回。"}]}, {"meaning": "回头;回顾。", "cites": [{"t": "羽还叱之。", "b": "《汉书·项籍传》"}, {"t": "视无还。", "b": "《国语·周语》"}], "words": [{"w": "还顾", "t": "回顾;回头看"}, {"w": "还睇", "t": "回头看"}, {"w": "还视", "t": "回头看。"}]}, {"meaning": "环绕。", "cites": [{"t": "左还授师。", "b": "《礼记·内则》"}, {"t": "还辟再拜稽首。", "b": "《礼记·曲礼》"}, {"t": "将还玩吴国于股掌之上。", "b": "《国语·吴语》。注:“还,转也。”"}, {"t": "引车右还。", "b": "《楚辞·招魂》"}, {"t": "道还公宫。", "b": "《左传·哀公三年》"}, {"t": "诸侯之师,还郑而来。", "b": "《左传·襄公十年》"}, {"t": "还庐树桑,菜茹有畦。", "b": "《汉书·食货志上》"}, {"t": "三人还射。", "b": "《史记·李将军传》"}, {"t": "还柱而走。", "b": "《战国策·燕策》"}, {"t": "方还柱走。", "b": ""}, {"t": "以地还之也。", "b": "《公羊传·庄公十年》"}, {"t": "水潦所还,埒丘。", "b": "《尔雅·释丘》"}], "words": [{"w": "还绕", "t": "环绕"}, {"w": "还会", "t": "交互缠绕的样子"}, {"w": "还旋", "t": "环绕。"}]}, {"meaning": "恢复;还原。", "cites": [{"t": "吏以过误罢者还其职。", "b": "《明史·太祖本纪》"}], "words": [{"w": "还惺", "t": "歇息一会而恢复精力"}, {"w": "还质", "t": "恢复丽质"}, {"w": "还睦", "t": "恢复和睦"}, {"w": "还童", "t": "恢复青春"}, {"w": "还级", "t": "恢复到原等级。"}]}, {"meaning": "来,到来。", "cites": [{"t": "舜禹还至,王业还起。", "b": "《荀子·王霸》"}], "words": [{"w": "春还", "t": "春天到来;春天来了"}, {"w": "时还", "t": "时来运转。"}]}, {"meaning": "交还;归还。", "cites": [{"t": "当奉还土地民人。", "b": "《三国志·吴主传》"}, {"t": "还矢先王。", "b": "宋·欧阳修《新五代史·伶官传》"}, {"t": "率夺还之。", "b": "《明史》"}], "words": [{"w": "还璧", "t": "归还玉璧;归还原物或辞谢馈赠之物"}, {"w": "还珠", "t": "物归原地与原主"}, {"w": "还归", "t": "归还。"}]}, {"meaning": "偿还;交付。", "cites": [{"t": "割慈忍爱还租庸。", "b": "杜甫《岁晏行》"}], "words": [{"w": "还付", "t": "归还交付"}, {"w": "还偿", "t": "偿还"}, {"w": "还款", "t": "归还所欠的债款或偿付所欠的贷款"}, {"w": "还直", "t": "偿还价值。"}]}, {"meaning": "后退。", "cites": [{"t": "主人答拜还。", "b": "《仪礼·乡饮酒礼》"}], "words": [{"w": "还走", "t": "返身后退而走"}, {"w": "还流", "t": "回流;回旋或倒流之水。"}]}, {"meaning": ""}, {"meaning": "经营;谋画。", "cites": [{"t": "内则大夫自还而不尽忠,外则诸侯连朋合舆。", "b": "《管子·山至数》"}], "words": [{"w": "还秩", "t": "谋求私利"}, {"w": "还私", "t": "谋私。"}]}, {"meaning": "惑乱。", "cites": [{"t": "国多私,比周还主党与施。", "b": "《荀子·成相》"}, {"t": "周环中规,折还中矩。", "b": "《礼记·玉藻》"}], "words": [{"w": "还主", "t": "惑乱君主。"}]}, {"meaning": "仍然;重复。", "cites": [{"t": "子孙日以长,世世还复然。", "b": "柳宗元《田家》"}]}, {"meaning": "反而。", "cites": [{"t": "譬画虎不成,还为狗者也。", "b": "《三国志·陈思王植传》裴松之注引《典略》"}]}, {"meaning": "迅速。", "cites": [{"t": "法立而还废之,令出而后反之。", "b": "《管子·任法》"}, {"t": "食骏马之肉,而不还饮酒,余恐其伤女也。", "b": "《吕氏春秋·爱士》"}, {"t": "鬼魅不能自还兮,半长途而下颠。", "b": "《汉书·扬雄传上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('705wx','尬','1','gà','尢','7','','[{"pinyin": "gà", "defs": [{"meaning": "——“尴尬”(gāngà):处境困难,不易处理。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('706wx','歼','1','jiān','歹','7','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。从歹(表示与死有关),韱(xiān)声。本义:消灭)。"}, {"meaning": "同本义。", "cites": [{"t": "歼,微尽也。", "b": "《说文》"}, {"t": "歼,尽也。", "b": "《尔雅》"}, {"t": "歼我良人。", "b": "《诗·秦风·黄鸟》"}, {"t": "齐人歼于遂。", "b": "《春秋·庄公十七年》"}, {"t": "东邻虐而歼仁兮。", "b": "班固《幽通赋》"}, {"t": "歼厥渠魁。", "b": "《书·胤征》"}], "words": [{"w": "歼夷", "t": "杀光夷平"}, {"w": "歼殄", "t": "消灭,灭绝"}, {"w": "歼除", "t": "灭绝铲除"}, {"w": "歼殛", "t": "消灭"}, {"w": "歼夺", "t": "使丧之"}, {"w": "歼一警百", "t": "同“杀一儆百”,杀一个人来警告一批人"}, {"w": "歼良", "t": "诛杀好人"}, {"w": "歼剥", "t": "杀戮伤害"}, {"w": "歼残", "t": "杀戮摧残。"}]}, {"meaning": "死。", "cites": [{"t": "[关羽]死逾月而[吕蒙]歼。天欲亡汉,故以蒙袭羽,又为羽灭蒙也。", "b": "明·胡应麟《少室山房笔丛》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('707wx','来','1','lái lài','木','7','','[{"pinyin": "lái", "defs": [{"meaning": "(象形。甲骨文字形。象麦子形。本义:麦。小麦叫“麦”,大麦叫“麰”(或写作“牟”))。"}, {"meaning": "同本义。", "cites": [{"t": "來,周所受瑞麥來麰也。", "b": "《说文》"}, {"t": "贻我来牟。", "b": "《诗·周颂·思文》。段注:“武王渡孟津,白鱼跃入王舟。出涘以燎。后五日。火流为乌,五至,以殻俱来,此谓遗我来牟。”"}, {"t": "于皇来牟。", "b": "《诗·周颂·臣工》。疏:“叹其受麦瑞而得丰年也。”"}], "words": [{"w": "来牟", "t": "古时大小麦的统称。"}]}, {"meaning": "未来,将来。", "cites": [{"t": "来日方长。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "知来者之可追。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "来代", "t": "后代;后世"}, {"w": "来辰", "t": "来早。明天早晨"}, {"w": "来兹", "t": "来年;将来"}, {"w": "来哲", "t": "后世贤智之人"}, {"w": "来轸", "t": "后来的车,比喻后来的人或物。"}]}, {"meaning": "由彼至此;由远到近。与“去”、“往”相对。", "cites": [{"t": "来,至也。", "b": "《尔雅》。朱骏声曰:“往來之來正字是麥,菽麥之麥,正字是來。三代以还,承用互易,如苑宛、童僮、酢醋、穜種之比。许君未经订正,故沿伪至今。”"}, {"t": "憧憧往来。", "b": "《易·咸》"}, {"t": "我行不来。", "b": "《诗·小雅·采薇》"}, {"t": "笑问客从何处来。", "b": "唐·贺知章《回乡偶书》"}, {"t": "翩翩两骑来是谁。", "b": "唐·白居易《卖炭翁》"}, {"t": "然往来视之。", "b": "唐·柳宗元《三戒》"}, {"t": "有朋自远方来。", "b": "《论语》"}, {"t": "往昔初阳时,谢家来贵门。", "b": "《古诗为焦仲卿妻作》"}], "words": [{"w": "来寇", "t": "敌人来犯"}, {"w": "来至", "t": "来到"}, {"w": "来突", "t": "突然而来。"}]}, {"meaning": "归,回来,返回。", "cites": [{"t": "萃聚而升不来也。", "b": "《易·杂卦》。注:“还也。”"}, {"t": "凡诸侯之女归宁曰来。", "b": "《左传·庄公二十七年》"}, {"t": "若吾子之德莫可歌也,其谁来之?", "b": "《左传·文公七年》"}], "words": [{"w": "来家", "t": "回到家里来"}, {"w": "来三去四", "t": "来来去去"}, {"w": "来还", "t": "归来,回来"}, {"w": "来宁", "t": "归宁。女子回娘家省亲"}, {"w": "来归", "t": "回来;归来"}, {"w": "来舍", "t": "回归而有所定止。"}]}, {"meaning": "归服;归顺。", "cites": [{"t": "修文德以来之", "b": "《论语·季氏》"}], "words": [{"w": "来服", "t": "前来顺服。"}]}, {"meaning": "招来;招致。后多作“徕”。", "cites": [{"t": "故远人不服,则修文德以来之。", "b": "《论语·季氏》"}], "words": [{"w": "来致", "t": "招致,招来。"}]}, {"meaning": "表示动作的趋向。", "cites": [{"t": "将子头与剑来。", "b": "晋·干宝《搜神记》"}, {"t": "闻来垂钓碧溪上。", "b": "唐·李白《行路难》"}, {"t": "长铗归来乎。", "b": "《战国策·齐策四》"}, {"t": "归来倚杖自叹息。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "归来头白还戍边。", "b": "唐·杜甫《兵车行》"}, {"t": "长铗归来者。", "b": "《战国策·齐策四》"}]}, {"meaning": "赐予。", "cites": [{"t": "来女孝孙。", "b": "《仪礼·少牢馈食礼》。郑玄注:“来,读曰釐;赐也”"}]}, {"meaning": "赐予。", "cites": [{"t": "东人之子,职劳不来。", "b": "《诗·小雅·大东》。高亨注:“来,借为赉。”"}]}, {"meaning": "这。", "cites": [{"t": "俺哥哥传将令三四番,可怎生无一个承头的?来一个燕青将面劈,那一个杨志头低。", "b": "元·佚名《黄花峪 》"}]}, {"meaning": "无义,译作“了”,“吧”,或不译。", "cites": [{"t": "归去来兮,田园将芜,胡不归。", "b": "陶渊明《归去来兮辞》"}]}, {"meaning": "以来,表示时间从过去某时持续到现在。", "cites": [{"t": "吾数年来欲买舟。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "数百年来。", "b": "唐《柳河东集》"}, {"t": "去来江口守空船。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "夜来城外一尺雪。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "来古", "t": "自古以来"}, {"w": "来来", "t": "以来"}, {"w": "来缘", "t": "指来生的因缘"}, {"w": "别来无恙乎?", "t": ""}]}, {"meaning": "用于句尾。", "cites": [{"t": "刚才奶奶和袭人姐姐怎么嘱咐来!", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}, {"pinyin": "lài", "defs": [{"meaning": "慰劳。", "cites": [{"t": "勑,劳也。从力,來声。字亦作俫。", "b": "《说文》"}, {"t": "知子之来之,杂佩以赠之。", "b": "《诗·郑风·女曰鸡鸣》。高亨注:“来,借为勑。”"}, {"t": "劳俫有意者。", "b": "《汉书·平当传》"}, {"t": "劳之来之,匡之直之,辅之翼之。", "b": "《孟子·滕文公上》"}, {"t": "莫我肯勑。", "b": "《诗·魏风·硕鼠》"}, {"t": "贤者勑其材。", "b": "《韩非子·王道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('708wx','连','1','lián','辶','7','','[{"pinyin": "lián", "defs": [{"meaning": "(会意。从辵(chuò),从车。本义:人拉的车)。"}, {"meaning": "同本义。", "cites": [{"t": "連,负车也。", "b": "《说文》。段注:“连即古文輦也。"}, {"t": "连车组輓。", "b": "《周礼·故书巾车》"}, {"t": "与其輂连。", "b": "《周礼·乡师》"}, {"t": "行服连轺辇者。", "b": "《管者·海王》"}, {"t": "民相连而从之。", "b": "《庄子·让王》。郑君、房君、司马君皆云:“读为辇。”"}, {"t": "[太后]曰:‘老妇持连而瞏(還)。’", "b": "马王堆汉墓帛书《战国纵横家书》"}]}, {"meaning": "姻亲关系。", "cites": [{"t": "[吕嘉]及苍梧(地名)秦王有连。", "b": "《史记·南越列传》"}], "words": [{"w": "连亲", "t": "连姻"}, {"w": "连昏", "t": "连婚。本有姻亲关系而又结亲。即俗称亲上加亲。"}]}, {"meaning": "连词的简称。"}, {"meaning": "古州名。"}, {"meaning": "在今广东连县一带。"}, {"meaning": "在今四川筠连县。"}, {"meaning": "兰草。", "cites": [{"t": "薜荔白芷、蘼芜椒连。", "b": "《管子·地员》"}]}, {"meaning": "铅。", "cites": [{"t": "长沙出边锡。", "b": "《史记·货殖列传》"}]}, {"meaning": "用人拉的车。", "cites": [{"t": "往蹇来连。", "b": "《易·蹇》。注:“连,辇也。”"}]}, {"meaning": "(自汉以来,习用连,不用联,故反以借字改正字)。"}, {"meaning": "连接;相连。", "cites": [{"t": "一曰连山。", "b": "《周礼·太卜》"}, {"t": "云连徒州。", "b": "《国语·楚语》"}, {"t": "天姥连天向天横,势拔五岳掩赤城。", "b": "李白《梦游天姥吟留别》"}, {"t": "东连吴会,西接巴蜀。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "藕断丝连;连观", "t": "互相连接的楼台"}, {"w": "连舻", "t": "舟船相连"}, {"w": "连属", "t": "连接;连续"}, {"w": "连枝", "t": "树枝相连;连在一起的树枝"}, {"w": "连行", "t": "鱼类相随而行"}, {"w": "连眉", "t": "两眉相接连"}, {"w": "连云", "t": "比喻高与云齐。"}]}, {"meaning": "连续,不停止。", "cites": [{"t": "烽火连三月,家书抵万金。", "b": "杜甫《春望》"}], "words": [{"w": "连仍", "t": "连续不断"}, {"w": "连住子", "t": "陆续地"}, {"w": "连延", "t": "连续不断的样子"}, {"w": "连更晓夜", "t": "昼夜不停"}, {"w": "连珠儿", "t": "接连不断。"}]}, {"meaning": "牵连。", "cites": [{"t": "少有连,必多方钩致。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "连缠", "t": "纠缠,牵连"}, {"w": "连引", "t": "牵连;引及"}, {"w": "连手", "t": "交情,牵连;勾搭。"}]}, {"meaning": "联合;结合。", "cites": [{"t": "外连衡而斗诸侯。", "b": "贾谊《过秦论》"}, {"t": "民相连而从之,遂成国于岐山之下。", "b": "《吕氏春秋·审为》"}, {"t": "约以连兵大举。", "b": "文天祥《指南录后序》"}], "words": [{"w": "连城", "t": "连成一片的好多城池"}, {"w": "连横", "t": "也作“联衡”。战国时秦国对付六国的一种战略。古以南北为纵,东西为横。"}]}, {"meaning": "同时获得。", "cites": [{"t": "一钓而连六鳌。", "b": "《列子》"}]}, {"meaning": "自;从。", "cites": [{"t": "连太太起,里里外外的都不干净。", "b": "《红楼梦》"}]}, {"meaning": "艰难。", "cites": [{"t": "孟轲虽连蹇,犹为万乘师。", "b": "扬雄《解嘲》"}], "words": [{"w": "连嵝", "t": "委曲,困顿"}, {"w": "连蹇", "t": "艰难,困厄。"}]}, {"meaning": "连续;多次。", "cites": [{"t": "匈奴复连发大兵侵击乌孙。", "b": "《汉书》"}, {"t": "连破其众。", "b": "脱脱《宋史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('709wx','轩','1','xuān','车','7','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从车,干声。本义:中国古代一种前顶较高而有帷幕的车子,供大夫以上乘坐)。"}, {"meaning": "同本义。", "cites": [{"t": "轩,曲輈藩车。", "b": "《说文》"}, {"t": "轩,安车也。", "b": "《声类》"}, {"t": "而乘轩者三百人也。", "b": "《左传·僖公二十八年》"}, {"t": "舍其文轩。", "b": "《战国策·宋策》"}, {"t": "俄轩冕。", "b": "扬雄《羽猎赋》。注:“车有轓曰轩。”"}, {"t": "如轾如轩。", "b": "《诗·小雅·六月》"}, {"t": "后重曰轩。", "b": "《通俗文》。按,后重曰轾,前高曰轩。"}, {"t": "舍其文轩。", "b": "《墨子·公输》"}, {"t": "文轩之与敝舆。", "b": ""}, {"t": "卫懿公好鹤,鹤有乘轩者。", "b": "《左传·闵公二年》"}], "words": [{"w": "轩服", "t": "轩车与冕服"}, {"w": "轩朱", "t": "古代显贵者所乘坐的车子"}, {"w": "轩车", "t": "曲辕而有帷幕的马车。是古代大夫以上的坐车"}, {"w": "轩冕", "t": "古代卿大夫的轩车和冕服。"}]}, {"meaning": "泛指华美的车子。", "cites": [{"t": "至若龙马银鞍,朱轩绣轴。", "b": "江淹《别赋》"}]}, {"meaning": "屋檐。", "cites": [{"t": "轩,檐宇之末曰轩,取车象。", "b": "《集韵》"}], "words": [{"w": "轩宁", "t": "殿前檐下的平台和殿上屏门之间"}, {"w": "轩檐", "t": "屋檐。"}]}, {"meaning": "殿堂前檐处。", "cites": [{"t": "酒半酣,辽主临轩,命诸部长次弟起舞。", "b": "《续资治通鉴》"}], "words": [{"w": "轩砌", "t": "殿堂前的台阶"}, {"w": "轩陛", "t": "殿堂的台阶。"}]}, {"meaning": "房屋。也用作书斋、茶馆的字号。", "cites": [{"t": "我们家里如今虽有几处轩馆,我又不住着,借了来也没趣。", "b": "《红楼梦》"}], "words": [{"w": "轩子", "t": "屋室"}, {"w": "轩宇", "t": "轩敞的屋宇"}, {"w": "轩序", "t": "指住宅"}, {"w": "轩房", "t": "住室。"}]}, {"meaning": "以敞朗为特点的建筑物。", "cites": [{"t": "新构一轩跨路,貌灵官于中。", "b": "《徐霞客游记》"}], "words": [{"w": "轩榭", "t": "指以轩敞为特点的亭阁台榭一类建筑物"}, {"w": "轩厂", "t": "棚舍。"}]}, {"meaning": "厕所的别称。", "cites": [{"t": "厕或曰轩,前有版似殿轩也。", "b": "《释名》"}, {"t": "是日,武帝起更衣,子夫侍尚衣,轩中得幸。", "b": "《史记·外戚世家》"}, {"t": "均之土也,或基堂殿,或涂轩户。", "b": "《论衡·幸偶篇》"}], "words": [{"w": "轩厕", "t": ""}]}, {"meaning": "槛板。", "cites": [{"t": "轩,谓槛正板也。", "b": "唐·慧琳《一切经音义》"}], "words": [{"w": "轩栏", "t": "栏板。"}]}, {"meaning": "有窗槛的小室或长廊。", "cites": [{"t": "啸傲东轩下。", "b": "陶潜《饮酒》"}, {"t": "读书轩中。", "b": "明·归有光《项脊轩志》"}, {"t": "轩东故尝为厨。", "b": ""}, {"t": "从轩前过。", "b": ""}, {"t": "轩凡四遭火。", "b": ""}], "words": [{"w": "轩子", "t": "有窗的长廓"}, {"w": "轩陛", "t": "指居室"}, {"w": "轩栏", "t": "殿前长廊的栏干"}, {"w": "轩楹", "t": "堂前的廊柱。"}]}, {"meaning": "指窗户或门。", "cites": [{"t": "开轩纳微凉。", "b": "杜甫《夏夜叹》"}, {"t": "开轩面场圃。", "b": "唐·孟浩然《过故人庄》"}], "words": [{"w": "轩户", "t": "门户。指人家"}, {"w": "轩扉", "t": "门窗"}, {"w": "轩榥", "t": "窗户。"}]}, {"meaning": "古代车子前高后低叫“轩”,前低后高叫“轾”。引申为高大。", "cites": [{"t": "中轩敞者。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "轩昂", "t": "气概不凡;高大雄伟"}, {"w": "轩秀", "t": "挺拔秀出"}, {"w": "轩眉", "t": "即扬眉。形容人志气高昂或高兴的样子"}, {"w": "轩峙", "t": "高耸矗立"}, {"w": "轩特", "t": "轩昂出众"}, {"w": "轩举", "t": "高昂,爽朗。"}]}, {"meaning": "重。", "cites": [{"t": "夫居前不能令人轾,居后不能令人轩,与人怨不能为人患,臣所耻也。", "b": "《后汉书》"}]}, {"meaning": "宽悦。也作“刳”。", "cites": [{"t": "君子不可以不刳心焉。", "b": "《庄子》。唐·陆德明释文:“刳,崔本作轩,云:‘宽悦貌。’”"}]}, {"meaning": "高扬;飞扬。", "cites": [{"t": "归雁载轩。", "b": "王粲《赠蔡子笃》"}, {"t": "翔雾连轩。", "b": "木华《海赋》"}, {"t": "交吕既鸿轩,攀嵇亦凤举。", "b": "颜延年《五君咏向常侍》"}], "words": [{"w": "轩轩", "t": "起舞的样子;扬扬自得的样子"}, {"w": "轩毳", "t": "飞鸟"}, {"w": "轩翥", "t": "飞举"}, {"w": "轩举", "t": "高扬飞举。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('710wx','步','1','bù','止','7','','[{"pinyin": "bù", "defs": [{"meaning": "(会意。甲骨文字形,由两只脚的象形符号重迭而成,表示两脚一前一后走路。本义:行走)。"}, {"meaning": "同本义。", "cites": [{"t": "步,行也。", "b": "《说文》"}, {"t": "跬步而不敢忘,孝也。", "b": "《礼记·祭义》"}, {"t": "王朝步自周。", "b": "《书·召诰》"}, {"t": "步路马必中道。", "b": "《礼记·曲礼》"}, {"t": "见夫人之步马者。", "b": "《左传·襄公二十六年》"}, {"t": "步余马兮山皋。", "b": "《楚辞·屈原·涉江》"}, {"t": "晚食以当肉,安步以当车。", "b": "《战国策·齐策四》"}], "words": [{"w": "止步;信步", "t": "随意走动;散步"}, {"w": "步步虚心", "t": "时时虚怀若谷,毫不自满"}, {"w": "步阁", "t": "步廊,走廊"}, {"w": "步趋", "t": "行走。"}]}, {"meaning": "按照,跟着;跟随。", "cites": [{"t": "柳亚子先生即席赋浣溪沙,因步其韵奉和。", "b": "毛泽东《浣溪沙》"}], "words": [{"w": "步人后尘;步武", "t": "追随前人脚步而行"}, {"w": "步趾", "t": "犹追随"}, {"w": "步趋", "t": "追随,效法。"}]}, {"meaning": "推算;测算。", "cites": [{"t": "迎日步气。", "b": "《时令论上》"}], "words": [{"w": "步天", "t": "测算天体"}, {"w": "步漏", "t": "推算时刻"}, {"w": "步历", "t": "推算岁时节候。"}]}, {"meaning": "脚步,步伐。", "cites": [{"t": "纤纤作细步。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "盈盈公府步(方步),冉冉府中趋。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "方步", "t": "斯斯文文的大而慢的步子"}, {"w": "放步", "t": "迈开大步"}, {"w": "阔步", "t": "迈大步"}, {"w": "碎步", "t": "小而快的步子"}, {"w": "纵步", "t": "放开脚步。"}]}, {"meaning": "古时一举足叫跬(半步);两足各跨一次叫步。今指行走时两脚之间的距离。", "cites": [{"t": "五步一楼,十步一阁。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "不积跬步,无以至千里。", "b": "《荀子·劝学》"}], "words": [{"w": "跑步;大踏步;步伐", "t": "行走的步子"}, {"w": "朝门走了两步,停了下来", "t": ""}]}, {"meaning": "步兵(诸兵种之一)。", "cites": [{"t": "诸人徒见操书言水步八十万而各恐慑。", "b": "《资治通鉴》"}], "words": [{"w": "步士", "t": "步兵"}, {"w": "步队", "t": "步兵队伍"}, {"w": "步骑", "t": "步兵与骑兵"}, {"w": "步哨", "t": "专任警戒的士兵。"}]}, {"meaning": "时运,命运。", "cites": [{"t": "於乎有哀,国步斯频。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "不幸落到这一步;后步", "t": "余地"}, {"w": "地步", "t": "处境;景况。"}]}, {"meaning": "埠 ,水边停船处。", "cites": [{"t": "宅有新屋,步有新船。", "b": "韩愈《柳州罗池庙碑》"}, {"t": "江之浒,凡舟可縻而上下者曰步。", "b": "柳宗元《铁炉步志》"}]}, {"meaning": "长度单位,历代不一,周代以八尺为一步,秦代以六尺,为一步。", "cites": [{"t": "舆六尺,六尺为步。", "b": "《史记·秦始皇本纪》"}, {"t": "骐骥一跃,不能十步。", "b": "《荀子·劝学》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('711wx','卤','1','lǔ','卜','7','','[{"pinyin": "lǔ", "defs": [{"meaning": "(象形。金文字形,象盐罐(或盐池)中有盐形。本义:盐碱地)。"}, {"meaning": "同本义。", "cites": [{"t": "晋荀吴帅师败狄于大鹵。", "b": "《春秋·昭公元年》"}, {"t": "表淳卤,数疆潦。", "b": "《左传·襄公二十五年》"}, {"t": "卤中草木白。", "b": "杜甫《盐井》"}], "words": [{"w": "卤田", "t": "盐田"}, {"w": "卤莽", "t": "荒地上的野草"}, {"w": "卤泻", "t": "含盐碱的土壤"}, {"w": "卤地", "t": "盐碱地。"}]}, {"meaning": "天然生成的盐称为“卤”。泛指食盐。", "cites": [{"t": "山东食海盐,山西食盐卤。", "b": "《史记·货殖列传》"}, {"t": "夷狄曰大鹵。", "b": "《谷梁传》"}], "words": [{"w": "卤池", "t": "咸水湖"}, {"w": "卤桶", "t": "盐场盛水的木桶"}, {"w": "卤脉", "t": "地下卤水的脉系"}, {"w": "卤汁", "t": "盐汁"}, {"w": "卤味", "t": "卤水之味"}, {"w": "卤烟", "t": "熬煮卤水时冒出的烟。"}]}, {"meaning": "大盾。", "cites": [{"t": "伏尸百万,流血漂卤。", "b": "贾谊《过秦论》"}], "words": [{"w": "卤楯", "t": "大盾。"}]}, {"meaning": "抄掠", "cites": [{"t": "毋得掠卤。", "b": "《史记·高祖本纪》"}, {"t": "鹵御物。", "b": "《史记·吴王濞传》。集解:“抄掠也。”"}, {"t": "有出掠虏者。", "b": "《后汉书·光武纪》"}, {"t": "所过勿得卤掠。", "b": "《汉书》"}], "words": [{"w": "卤掠", "t": "劫夺别人的财物。同掳掠"}, {"w": "卤获", "t": "虏掠而获得。也指袭击所得。同掳获。"}]}, {"meaning": "笨;迟钝", "cites": [{"t": "才操卤钝。", "b": "《风俗通义·过誉》"}, {"t": "卤纯者醒悟。", "b": "葛洪《抱朴子》"}], "words": [{"w": "卤钝", "t": "愚鲁迟钝。同鲁钝"}, {"w": "卤人", "t": "莽汉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('712wx','坚','1','jiān','土','7','','[{"pinyin": "jiān", "defs": [{"meaning": "(会意。从臤(qiān),从土。“臤”,金文象以手拉“臣”(屈服的奴隶)。从“土”,表示土质坚硬。本义:泥土坚硬)。"}, {"meaning": "同本义。泛指坚硬;结实。", "cites": [{"t": "坚,刚也。", "b": "《说文》"}, {"t": "坚,坚土也。", "b": "《广雅》"}, {"t": "四为壤五,为坚三。", "b": "《九章算术·穿地》"}, {"t": "铠甲不坚。", "b": "《韩非子·五蠹》"}, {"t": "剑坚,故不可立拔。(剑坚,剑插得紧。)", "b": "《战国策·燕策》"}, {"t": "非不坚利。", "b": "《孟子·公孙丑下》"}, {"t": "披坚执锐。", "b": "《史记·陈涉世家》"}, {"t": "火烧令坚。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "砚冰坚。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "坚瓠", "t": "坚厚而实心的葫芦。不可剖以盛物,因喻无用的东西"}, {"w": "坚冰", "t": "多以喻积过成祸,困难重重"}, {"w": "坚顽", "t": "极其坚硬"}, {"w": "坚确", "t": "坚硬"}, {"w": "坚滑", "t": "坚硬滑溜"}, {"w": "坚润", "t": "坚硬而润泽。"}]}, {"meaning": "牢固,坚固,强固有力而不易摧毁。", "cites": [{"t": "坚,强也。", "b": "《广雅》"}, {"t": "坚穷廉直。", "b": "《吕氏春秋·审分》"}, {"t": "誉其盾之坚,物莫能陷也。", "b": "《韩非子·难势》"}, {"t": "坚闭门而不出。", "b": "《庄子·天运》"}], "words": [{"w": "坚巧", "t": "牢固而精巧"}, {"w": "坚城", "t": "坚固不易攻破的城池"}, {"w": "坚勚", "t": "结实"}, {"w": "坚壁", "t": "坚固的墙壁或营垒;坚守壁垒。"}]}, {"meaning": "坚定;意志、主张不动摇。", "cites": [{"t": "穷且益坚,不坠青云之志。", "b": "王勃《滕王阁序》"}], "words": [{"w": "坚凝", "t": "坚定;坚强;紧凑简练"}, {"w": "坚确", "t": "心志坚定;土质坚固"}, {"w": "坚劲", "t": "强而有力;意志坚强不变"}, {"w": "坚心", "t": "坚定的心志。"}]}, {"meaning": "牢靠,稳定。", "cites": [{"t": "坚致为上。", "b": "《淮南子·时则》。注:“功,牢也。”"}], "words": [{"w": "坚心", "t": "一心"}, {"w": "坚附", "t": "安定,牢固附着"}, {"w": "坚卧", "t": "按兵不动。"}]}, {"meaning": "固执。", "cites": [{"t": "二曰行辟而坚。", "b": "《荀子·宥坐》"}, {"t": "小敌之坚。(坚,硬拼。)", "b": "《孙子·谋攻》"}], "words": [{"w": "坚意", "t": "执意,决心"}, {"w": "坚卧", "t": "坚不出仕,隐居"}, {"w": "坚秉", "t": "坚持"}, {"w": "坚僻", "t": "固执怪僻。"}]}, {"meaning": "坚固的东西。", "cites": [{"t": "披坚执锐。", "b": "《史记·陈涉世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('713wx','肖','1','xiāo xiào','月','7','','[{"pinyin": "xiāo", "defs": [{"meaning": "姓。“萧”字的俗写。"}, {"meaning": "假借为“小”。细微。", "cites": [{"t": "肖,小也。", "b": "《方言十二》"}, {"t": "肖翘之物。", "b": "《庄子·ń箧》"}, {"t": "达生之情者傀,达于知者肖。", "b": "《庄子》"}], "words": [{"w": "肖翘", "t": "细小能飞的生物。"}]}, {"meaning": "假借为“消”。消灭;消失;衰退,衰微。", "cites": [{"t": "达于知者肖。", "b": "《庄子·列御寇》"}, {"t": "申吕肖矣,尚父侧微。", "b": "《史记·太史公自序》"}]}]}, {"pinyin": "xiào", "defs": [{"meaning": "(形声。从肉,小声。本义:相似,相像)。"}, {"meaning": "同本义(侧重于本质特点上的相像)。", "cites": [{"t": "肖,骨肉相似也。", "b": "《说文》。字亦作俏"}, {"t": "人俏天地之类。", "b": "《列子·杨朱》"}, {"t": "肖形而蕃。", "b": "《淮南子·地形》"}, {"t": "丹朱之不肖。", "b": "《孟子》"}, {"t": "乃审厥象,俾以形旁求于天下,(傅)说筑傅岩之野,惟肖。", "b": "《书·说命上》"}, {"t": "使之肖我。", "b": "清·林觉民《与妻书》"}, {"t": "无不毕肖。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "肖子", "t": "在志趣等方面与其父一致的儿子"}, {"w": "肖题", "t": "切题"}, {"w": "肖似", "t": "肖貌,肖神。相似,神似"}, {"w": "肖形", "t": "仿形。"}]}, {"meaning": "刻画,谓图画或雕塑人像。", "cites": [{"t": "以紫檀肖其象而祠之。", "b": "宋·范仲淹文"}, {"t": "旁肖十六应真像。", "b": "清·李斗《扬州画航录》"}], "words": [{"w": "肖物", "t": "刻画事物。"}]}, {"meaning": "仿效。", "cites": [{"t": "我肖其涤,以清厥身。", "b": "宋·王安石《张君玉墓志铭》"}], "words": [{"w": "肖形", "t": "仿形。亦泛指形状。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('714wx','旱','1','hàn','日','7','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从日,干声。本义:久不下雨)。"}, {"meaning": "同本义。", "cites": [{"t": "旱,不雨也。", "b": "《说文》"}, {"t": "旱既大甚,蕴隆虫虫。", "b": "《诗·大雅·云汉》"}, {"t": "不得雨曰旱。", "b": "《谷梁传·僖公十一年》"}, {"t": "二谷不收谓之旱。", "b": "《墨子·七患》"}, {"t": "三千里之旱。", "b": "汉·贾谊《论积贮疏》"}, {"t": "兵旱相乘。", "b": ""}], "words": [{"w": "旱涝", "t": "干旱与水涝"}, {"w": "旱云", "t": "干旱不雨的云"}, {"w": "旱亢", "t": "大旱"}, {"w": "旱苗得雨", "t": "久旱的禾苗喜逢甘霖滋润。"}]}, {"meaning": "迅猛", "cites": [{"t": "水激则旱兮,矢激则远。", "b": "汉·贾谊《鹏鸟赋》"}]}, {"meaning": "山名。旱山 。在今陕西省南郑县西南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('715wx','盯','1','dīng','目','7','','[{"pinyin": "dīng", "defs": [{"meaning": "(形声。从目,丁声。本义:注视)。"}, {"meaning": "紧跟着不放松。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('716wx','呈','1','chéng','口','7','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从口,壬(tǐng)声。本义:平)。"}, {"meaning": "同本义。", "cites": [{"t": "呈,平也。", "b": "《说文》"}]}, {"meaning": "呈现,显现,显露。", "cites": [{"t": "呈,显也。", "b": "《广韵》"}, {"t": "延颈秀项,皓质呈露,芳泽无加,铅华弗御。", "b": "曹植《洛神赋》。注:“见也。”"}, {"t": "无风亦呈袅娜之姿。", "b": "清·李渔《闲情偶寄·种植部》"}], "words": [{"w": "呈华", "t": "显示才华"}, {"w": "呈瑞", "t": "呈现祥瑞"}, {"w": "呈质", "t": "呈现本体。"}]}, {"meaning": "献。", "cites": [{"t": "汝曹呈艺已遍,吾当呈艺。", "b": "《避暑录话》"}], "words": [{"w": "呈艺", "t": "献技,献艺"}, {"w": "呈献", "t": "敬献。"}]}, {"meaning": "旧时公文的一种,用于下对上。", "cites": [{"t": "老爹,我而今就写呈去首。", "b": "《儒林外史》"}], "words": [{"w": "呈稿", "t": "呈本。呈文的底稿"}, {"w": "呈子", "t": "状子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('717wx','时','1','shí','日','7','','[{"pinyin": "shí", "defs": [{"meaning": "(形声。从日,寺声。从“日”与时间有关。本义:季度;季节)。"}, {"meaning": "同本义。", "cites": [{"t": "时,四时也。", "b": "《说文》"}, {"t": "四时,四方各一时,时,期也。", "b": "《释名》"}, {"t": "谓其三时不害。", "b": "《左传·桓公六年》。注:“春夏秋也。”"}, {"t": "三时者,成岁之要时。又,天时不如地利。", "b": "《孟子·篇叙》。注:“谓时曰支干五行相孤虚之属也。”"}, {"t": "斧斤以时入山林。", "b": "《孟子·梁惠王上》"}, {"t": "时事之征也。", "b": "《左传·闵公二年》"}, {"t": "时者,所以记岁也。", "b": "《管子·山权数》"}, {"t": "四时者,天之吏也。", "b": "《淮南子·天文》"}, {"t": "四时和谓之宝烛。", "b": "《尔雅·释天》。注:“道光照也。”"}, {"t": "敬授人时。", "b": "《书·尧典》。马注:“羲和四子掌四时。”"}, {"t": "四时之景不同,而乐亦无穷也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "谓其三时(指春夏秋)不害,而民和年丰也。", "b": "《左传·桓公六年》"}], "words": [{"w": "时气", "t": "时令,气候"}, {"w": "时若", "t": "四时和顺"}, {"w": "时食", "t": "四季应时的食品"}, {"w": "时耕", "t": "春耕"}, {"w": "时夏", "t": "夏季"}, {"w": "时暑", "t": "夏天的炎热"}, {"w": "时景", "t": "春景"}, {"w": "时禽", "t": "随节候而出现的鸟"}, {"w": "时享", "t": "宗庙四时的祭祀"}, {"w": "时序", "t": "季节的顺序,时间的先后"}, {"w": "时祀", "t": "按四季所举行的祭祀"}, {"w": "时田", "t": "四时田猎。指古代帝王、贵族四时到野外打猎,并行军事训练"}, {"w": "时令病", "t": "在一定季节流行的疾病"}, {"w": "时衣", "t": "四时的衣服"}, {"w": "时芳", "t": "应季节而开放的花。"}]}, {"meaning": "时辰 ,计时单位,一昼夜的十二分之一(古时一昼夜分为十二时)。", "cites": [{"t": "时,时辰也。十二时也。", "b": "《韵会》"}, {"t": "觯俟时而酌。", "b": "《仪礼·既夕记》。注:“朝兮也。”"}, {"t": "以时启闭。", "b": "《周礼·阍人》"}, {"t": "时数辞违。", "b": "《太玄·玄数》"}, {"t": "一日思亲十二时。", "b": "黄庭坚《思亲汝州作》"}, {"t": "时已过午,奴辈适至。", "b": "《徐霞客游记·游黄山记》"}, {"t": "从已时直杀到未时,周瑜虽得利,只恐寡不敌众,遂下令鸣金收住船只。", "b": "《三国演义》"}], "words": [{"w": "报时;此日此时;时辰钟", "t": "时钟,钟表"}, {"w": "晡时", "t": "下午四时左右"}, {"w": "午时", "t": "白天11点至1点"}, {"w": "子时", "t": "夜间11点至1点。"}]}, {"meaning": "时间;时候。", "cites": [{"t": "始臣之解牛之时,所见无非全牛者。", "b": "《庄子·养生主》"}, {"t": "生之有时而用之亡度,则物力心屈。", "b": "汉·贾谊《论积贮疏》"}, {"t": "自谓少时用心于学甚劳。", "b": "明·宋濂《送东阳马生序》"}, {"t": "女时昔作儿,生小出野里。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "费时", "t": "耗费时间"}, {"w": "多时", "t": "很长时间"}, {"w": "时晌", "t": "时饷。时间"}, {"w": "时子", "t": "时候"}, {"w": "时目", "t": "时下的眼光"}, {"w": "时出", "t": "得其时而出。"}]}, {"meaning": "时尚,时俗。", "cites": [{"t": "李氏子蟠,年十七,好古文,六艺经传皆通习之,不拘于时,学于余。", "b": "唐·韩愈《师说》"}]}, {"meaning": "时运;命运。", "cites": [{"t": "死之短长,时也。", "b": "《左传》"}, {"t": "杀身有地初非惜,报国无时未免愁。", "b": "宋·陆游《登慧照寺小阁》"}], "words": [{"w": "时衰", "t": "时运衰落"}, {"w": "时道", "t": "时运;机会"}, {"w": "时蹇", "t": "时运不佳。"}]}, {"meaning": "时机;机会。", "cites": [{"t": "长风破浪会有时,直挂云帆济沧海。", "b": "唐·李白《行路难》"}, {"t": "鸡豚狗彘之畜,无失其时。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "失时;时乖运蹇", "t": ""}]}, {"meaning": "岁月,光阴。", "cites": [{"t": "时不久留。", "b": "《吕氏春秋》"}]}, {"meaning": "指时势或时局。", "cites": [{"t": "救时应仗出群才。", "b": "秋瑾《黄海舟中》"}], "words": [{"w": "时化", "t": "时势的变化"}, {"w": "时艰", "t": "时局的艰难困苦。"}]}, {"meaning": "代,朝。", "cites": [{"t": "自云先世避秦时乱。", "b": "晋·陶渊明《桃花源记》"}, {"t": "世易时移,变法宜矣。", "b": "《吕氏春秋·察今》"}, {"t": "变法者因时而他。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "时世", "t": "时代,时局"}, {"w": "时年", "t": "时代。"}]}, {"meaning": "气候。", "cites": [{"t": "天时不如地利,地利不如人和。", "b": "《孟子·公孙丑下》"}, {"t": "今天时顺正,死者尚稀。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "合时宜的,适时的。", "cites": [{"t": "时雨降矣。", "b": "《庄子》"}], "words": [{"w": "时豪", "t": "穿着入时;时髦"}, {"w": "时谚;时文;时服", "t": "当时通行的服装;时兴的服装。"}]}, {"meaning": "当时的。", "cites": [{"t": "每自比于管仲乐毅,时人莫之许也。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "时忌", "t": "当时的忌讳"}, {"w": "时辈", "t": "当时的名流、贤达"}, {"w": "时彦", "t": "当时的英才"}, {"w": "时人", "t": "当时的人"}, {"w": "时势;时语", "t": "当时的口语"}, {"w": "时豪", "t": "当时的豪强"}, {"w": "时俊", "t": "当代或当时的贤俊。"}]}, {"meaning": "善,好。", "cites": [{"t": "尔酒既旨,尔殽既时。", "b": "《诗·小雅·怡弁》"}]}, {"meaning": "相当于“常常”、“经常”。", "cites": [{"t": "时与出游猎。", "b": "《史记·吕太后本纪》"}, {"t": "策扶老以流憩,时矫首而遐。", "b": "陶潜《归去来兮辞》"}, {"t": "庭阶寂寂,小鸟时来啄食,人至不去。", "b": "明·归有光《项脊轩志》"}, {"t": "数千里外,得长者时赐一书,以慰长想,即亦甚幸矣。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "时闻", "t": "常常聆听"}, {"w": "时常", "t": "常常;经常"}, {"w": "时形", "t": "经常出现。"}]}, {"meaning": "相当于“有时”、“偶尔”。", "cites": [{"t": "下盼诸峰,时出为碧峤,时没为银海。", "b": "明·徐宏祖《游黄山记》"}, {"t": "故家大姓时有被诬负屈者。", "b": "《明史·海瑞传》"}]}, {"meaning": "按时,到时候。", "cites": [{"t": "谨食之,时而献焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "学而时习之,不亦说乎?", "b": "《论语·学而》"}]}, {"meaning": "当时,这时,那时。", "cites": [{"t": "时秦昭王与楚婚。", "b": "《史记》"}, {"t": "时天下承平日久,自王侯以下莫不逾侈。", "b": "《后汉书·张衡传》"}, {"t": "时大风雪。", "b": "《资治通鉴》"}]}, {"meaning": "表示近指,相当于“此”、这”。", "cites": [{"t": "时,是也。", "b": "《尔雅》"}, {"t": "黎民于变时雍。", "b": "《书·尧典》。传:“是也。”"}, {"t": "孝友时格。", "b": "《仪礼·士冠礼》"}, {"t": "率时农夫,播厥百谷。", "b": "《诗·周颂·噫嘻》"}, {"t": "匪上帝不时,殷不用旧。", "b": "《荀子·非十二子》"}, {"t": "奉时辰牡,辰牡孔硕。", "b": "《诗·秦风·驷》"}, {"t": "时大风雪,旌旗裂,人马冻死者相望。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "适时;合于时宜。", "cites": [{"t": "风雨之不时。", "b": "《荀子》"}], "words": [{"w": "时菊", "t": "应时开的菊"}, {"w": "时雪", "t": "应时的雪"}, {"w": "时味", "t": "应时的美味"}, {"w": "时果", "t": "应时的水果"}, {"w": "时物", "t": "应时的作物"}, {"w": "时花", "t": "应时开的花"}, {"w": "时鸟", "t": "应时而鸣的鸟"}, {"w": "时材", "t": "应时的才能"}, {"w": "时风", "t": "应时的风"}, {"w": "时馐", "t": "应时的美味"}, {"w": "时稼", "t": "应时的作物。"}]}, {"meaning": "伺候;等待。", "cites": [{"t": "孔子时其亡无而往拜之。", "b": "《论语·阳货》"}, {"t": "时其饥饱,达其怒心。", "b": "《庄子·人间世》"}, {"t": "来丹遂执剑从黑卵,时黑卵之醉偃于牖下,自颈至腰三斩之。", "b": "《列子·汤问》"}], "words": [{"w": "时行", "t": "等待时机而行;及时而作"}, {"w": "少时", "t": "稍等。"}]}, {"meaning": "处,处于。", "cites": [{"t": "宜于时通,利以处穷。", "b": "《荀子》"}]}, {"meaning": "承,承受。", "cites": [{"t": "纳于百揆,百揆时叙。", "b": "《书·舜典》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('718wx','吴','1','wú','口','7','','[{"pinyin": "wú", "defs": [{"meaning": "(会意。从口,从矢。矢(zè),象头的动作。合起来表示晃着头大声说话。本义:大声说话,喧哗) 同本义。", "cites": [{"t": "不吴不敖,胡考之休。", "b": "《诗·周颂·丝衣》。传:“吴,哗也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('719wx','助','1','chú zhù','力','7','','[{"pinyin": "chú", "defs": [{"meaning": "除去。", "cites": [{"t": "颜不疑归,而师董梧,以助其色。", "b": "《庄子》"}]}]}, {"pinyin": "zhù", "defs": [{"meaning": "(形声。从力,且(zǔ)声。助人要用力,故从力。本义:帮助)。"}, {"meaning": "同本义(在物质上或精神上给予协助)。", "cites": [{"t": "助,左也。", "b": "《说文》"}, {"t": "助,佐也。", "b": "《小尔雅》"}, {"t": "非助我者也。", "b": "《论语》。孔注:“犹益也。”"}, {"t": "九一而助。", "b": "《孟子》"}, {"t": "助天为虐者,不祥。", "b": "《国语·越语下》"}, {"t": "予助苗长矣。", "b": "《孟子·公孙丑上》"}, {"t": "跳往助之。", "b": "《列子·汤问》"}, {"t": "负薪刍助之。", "b": "《资治通鉴·唐纪》"}, {"t": "挟矢以助战。", "b": "明·魏禧《大铁椎传》"}, {"t": "肤觉之助。", "b": "蔡元培《图画》"}], "words": [{"w": "助胆", "t": "帮助壮胆"}, {"w": "互助", "t": "互相帮助"}, {"w": "扶助", "t": "帮助"}, {"w": "资助", "t": "用财物帮助"}, {"w": "助力", "t": "帮助;援助。"}]}, {"meaning": "辅助。", "cites": [{"t": "射夫即同,助我举柴。", "b": "《诗·小雅》"}], "words": [{"w": "助化", "t": "辅助教化"}, {"w": "助葬", "t": "佐助他人发丧送葬"}, {"w": "助研", "t": "助理研究员的简称。"}]}, {"meaning": "增添;增加。", "cites": [{"t": "于是窦后持之而泣,泣涕交横下。侍御左右皆伏地泣,助皇后悲哀。", "b": "《史记》"}], "words": [{"w": "助哭", "t": "旧俗,客来灵前吊丧,丧主命人号哭以助哀,谓之助哭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('720wx','县','1','xiàn xuán','厶','7','','[{"pinyin": "xiàn", "defs": [{"meaning": "(会意。从系持倒首。象悬挂的样子。(xuán)本义:悬挂)。"}, {"meaning": "县假借为“寰”,为州县的县 。行政区划单位。周代县大于郡,秦以后县属于郡。今为一级行政区划,隶属于地区、自治州、直辖市之下。", "cites": [{"t": "遂缚诣县。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "南番二县。", "b": "《广东军务记》"}, {"t": "龙泉县。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "开道置县。", "b": "《明史》"}], "words": [{"w": "县尹", "t": "一县的长官"}, {"w": "县学", "t": "旧制设在县里的学校,以培养人才,教育百姓,称县学"}, {"w": "县委", "t": "中国共产党县一级委员会的简称。"}]}]}, {"pinyin": "xuán", "defs": [{"meaning": "系挂。", "cites": [{"t": "縣,系也。从系,持县会意。", "b": "《说文》。"}, {"t": "骊姬请使申,处曲沃以速縣。", "b": "《国语·晋语》。注:“缢也。”"}, {"t": "不狩不猎,胡瞻尔庭有县鹑兮?", "b": "《诗·魏风·伐檀》"}, {"t": "尔庭有县特兮。", "b": ""}, {"t": "尔庭有县鹑兮。", "b": ""}], "words": [{"w": "县令", "t": "高悬的命令。即“高名”、“虚名”"}, {"w": "县车", "t": "悬挂缰绳,停放车子不用。比喻退隐不再出仕。"}]}, {"meaning": "维系;拴系;系联。", "cites": [{"t": "县联房植。", "b": "《淮南子·本经》"}, {"t": "县棺而封。", "b": "《礼记·檀弓》"}], "words": [{"w": "县绝", "t": "悬系之绳断绝"}, {"w": "县联", "t": "椽子和屋檐木相接之处。"}]}, {"meaning": "揭示;颁立。", "cites": [{"t": "县法以诱民。", "b": "《汉书·食货志》"}], "words": [{"w": "县法", "t": "古代公布法令,皆悬在阙下,使众周知,故以称颁布法令。"}]}, {"meaning": "古称悬挂的乐器,如钟磬等。", "cites": [{"t": "正乐縣之位。", "b": "《周礼·小胥》。注:“谓钟磬之属。”"}], "words": [{"w": "县垂", "t": "指钟磬等悬挂乐器"}, {"w": "县兴", "t": "奏钟磬之类的乐器"}, {"w": "县磬", "t": "悬挂的磬。喻空无所有,贫困之极。"}]}, {"meaning": "秤锤。", "cites": [{"t": "故衡诚縣不可欺以轻重。", "b": "《礼记·经解》。注:“谓锤也。”"}], "words": [{"w": "衡县", "t": "秤锤。"}]}, {"meaning": "远,悬殊。", "cites": [{"t": "县隔千里。", "b": "《汉书·高帝纪》"}, {"t": "此古之所谓县解也。", "b": "《庄子·大宗师》。向注:“无所系也。”"}], "words": [{"w": "县隔", "t": "相隔很远或差别很大。同“悬隔”"}, {"w": "县久", "t": "历时久长"}, {"w": "县远", "t": "悬殊;距离遥远。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('721wx','里','1','lǐ','里','7','','[{"pinyin": "lǐ", "defs": [{"meaning": "(会意。从衣,里声。本义:衣服的里层)。"}, {"meaning": "同本义。", "cites": [{"t": "裏,衣内也。", "b": "《说文》。衣外曰表。"}, {"t": "襦在裏也。", "b": "《谷梁传·宣公九年》注"}, {"t": "不罹于裏。", "b": "《诗·小雅·小弁》"}, {"t": "绿衣黄里。", "b": "《诗·邶风·绿衣》"}], "words": [{"w": "里衣", "t": "内衣,汗衫。指贴身的衣报"}, {"w": "里外发烧", "t": "指里外都是毛皮缝制的衣服。"}]}, {"meaning": "内,中。与外相反。", "cites": [{"t": "裏急暴痛。", "b": "《素问·至真要大论》"}, {"t": "肉里之脉。", "b": "《素问·刺腰痛篇》"}, {"t": "约定今夜放火,里应外合。", "b": "《三国演义》"}], "words": [{"w": "里向", "t": "靠里边的;里面"}, {"w": "里势", "t": "里面"}, {"w": "里勾外连", "t": "内外勾结"}, {"w": "里头大叔", "t": "里头,指宫内。指慈禧最宠信的大太监李连英"}, {"w": "里牵绵", "t": "指饮酒下肚时,好像腹内忽有厚绵暖着一样。"}]}, {"meaning": "时候。", "cites": [{"t": "妾身年少里,父母俱倾弃。", "b": "宋·佚名《张协状元》"}]}, {"meaning": "附在“这”、“那”、“哪”等字后边表示地点;位置;处所。", "cites": [{"t": "我这里凭阑望,母亲那里倚门悲。", "b": "郑德辉《玉粲登楼》"}], "words": [{"w": "这里,那里;哪里;省里;县里", "t": ""}]}, {"meaning": "(会意。从土,从田。从“田”,含有区分界域的意思。本义:里弄;街巷)。"}, {"meaning": "同本义。", "cites": [{"t": "里,居也。", "b": "《说文》"}, {"t": "里,邑也。", "b": "《尔雅》。李注:“居之邑也。”"}, {"t": "里尻也。", "b": "《广雅》"}, {"t": "在野曰庐,在邑曰里。", "b": "《汉书·食货志》"}, {"t": "于蹶之里。", "b": "《诗·大雅·韩奕》"}, {"t": "赋里以人。", "b": "《国语·晋语》。注:“廛也。”"}, {"t": "以里听者,禄之以里。", "b": "《吕氏春秋·怀宠》。注:“闾也。”"}, {"t": "河洛为王之里。", "b": "左思《蜀都赋》。注:“居也。”"}, {"t": "匪仁里其焉宅兮。", "b": "张衡《思玄赋》。注:“里宅皆居也。”"}, {"t": "将仲子兮,无逾我里。", "b": "《诗·郑风·将仲子》"}, {"t": "既行,及里门,门扃未发。", "b": "沈既济《任氏传》"}], "words": [{"w": "里门", "t": "乡里的门。古代聚族列里以居,里有里门"}, {"w": "里闬", "t": "即里门,乡里"}, {"w": "里闾", "t": "里门,乡里。"}]}, {"meaning": "古代一种居民组织,先秦以二十五家为里。", "cites": [{"t": "八家为邻,三邻为朋,三朋为里。", "b": "《尚书大传》"}, {"t": "古者七十二家为里。", "b": "《论语·譔考文》"}, {"t": "一里八十户。", "b": "《公羊传·宣公十五年》"}, {"t": "百家为里。", "b": "《管子·度地》"}, {"t": "广三百步、长三百步为一里。", "b": "《韩诗外传》"}, {"t": "择其贤民,使为里君。", "b": "《管子·小匡》"}], "words": [{"w": "里长", "t": "主管一里的人。古时五里为邻,五邻为里"}, {"w": "里尹", "t": "里长,里中的长官。即里正"}, {"w": "里正图董", "t": "乡长、里长一类的人物"}, {"w": "里吏", "t": "即里尹、里正、里胥。"}]}, {"meaning": "乡里;家乡;故乡。", "cites": [{"t": "三老、官属、豪长者、里父老皆会。", "b": "《史记·滑稽列传》"}, {"t": "黯耻为令,病归田里。", "b": "《史记·汲郑列传》"}, {"t": "暧暧远人村,依依墟里烟。", "b": "陶潜《归园田居》"}, {"t": "割慈忍爱,离邦去里。", "b": "江淹《别赋》"}], "words": [{"w": "里籍", "t": "籍贯"}, {"w": "里豪", "t": "乡里中豪强的人"}, {"w": "里妪", "t": "乡村妇女"}, {"w": "里门", "t": "故里;故乡。"}]}, {"meaning": "量词。长度单位。", "cites": [{"t": "于三十里。", "b": "《诗·小雅·六月》"}], "words": [{"w": "华里", "t": "市里的旧称"}, {"w": "里数;里程;里堠", "t": "记里程的土堆。"}]}, {"meaning": "地理。", "cites": [{"t": "通于沟渠,修堤防,树五谷,通于地里者也。", "b": "《说苑·臣术》"}]}, {"meaning": "居住。", "cites": [{"t": "在壄曰庐,在邑曰里。", "b": "《汉书·食货志上》"}, {"t": "悠悠我里。", "b": "《诗·小雅·十月之交》"}, {"t": "军社之所里。", "b": "《周礼·夏官·量人》"}, {"t": "里仁而美。", "b": "《论语·里仁》"}], "words": [{"w": "里布", "t": "古代的土地税。里,居也;布,钱也"}, {"w": "里舍", "t": "私人住宅;同乡里人"}, {"w": "里仁", "t": "居住在仁者所居之里;与仁人为邻。"}]}, {"meaning": "治理。", "cites": [{"t": "乃里西土之数。", "b": "《穆天子传》"}]}, {"meaning": "忧伤。", "cites": [{"t": "悠悠我里,亦孔之痗。", "b": "《诗·小雅·十月之交》"}]}, {"meaning": "同“哩”。", "cites": [{"t": "[正旦云]梅香,你看奶奶做什么里?[梅香云]奶奶看经哩。", "b": "元·关汉卿《金线池》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('722wx','呆','1','dāi','口','7','','[{"pinyin": "dāi", "defs": [{"meaning": "痴;傻。", "cites": [{"t": "呆霸王调情遭苦打。", "b": "《红楼梦》"}], "words": [{"w": "呆霸王", "t": "《红楼梦》中薛蟠的浑号"}, {"w": "呆里撒奸", "t": "装痴卖呆以售其奸"}, {"w": "呆串了友", "t": "呆得不可收拾"}, {"w": "呆想", "t": "痴想"}, {"w": "呆人", "t": "呆子,傻瓜"}, {"w": "呆汉", "t": "痴呆的人"}, {"w": "呆大", "t": "傻瓜;笨蛋"}, {"w": "呆老汉", "t": "傻老公"}, {"w": "呆物", "t": "詈词。傻家伙"}, {"w": "呆性", "t": "傻气;痴迷劲儿。"}]}, {"meaning": "暂时住在。", "cites": [{"t": "但这一来,我就不能在镇头市呆下去了。", "b": "《潘虎》"}], "words": [{"w": "她喜欢呆在娘家", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('723wx','吱','1','zhī zī','口','7','','[{"pinyin": "zhī", "defs": [{"meaning": "细小的声音。", "cites": [{"t": "人语闹吱嗻。", "b": "《牡丹亭》"}]}, {"meaning": "发出。", "cites": [{"t": "老孙头看看四周,却不吱声。", "b": "《暴风骤雨》"}]}]}, {"pinyin": "zī", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('724wx','吠','1','fèi','口','7','','[{"pinyin": "fèi", "defs": [{"meaning": "(会意。从犬,从口。本义:狗叫)。"}, {"meaning": "同本义。", "cites": [{"t": "吠,犬鸣也。", "b": "《说文》"}, {"t": "邑犬君吠兮所怪也。", "b": "《楚辞·九章》"}, {"t": "谚云:“一犬吠形,百犬吠声。”", "b": "王符《潜夫论·贤难》"}], "words": [{"w": "吠声", "t": "狗叫声"}, {"w": "吠日", "t": "很少见到太阳的狗,偶尔见到太阳出来就狂叫,喻少见多怪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('725wx','呕','1','ǒu','口','7','','[{"pinyin": "ǒu", "defs": [{"meaning": "(形声。从口,区(ōu)声。本义:东西在胃喉中上涌,从口中出来)。"}, {"meaning": "同本义。", "cites": [{"t": "欧,吐也。", "b": "《说文》。字亦作呕。"}, {"t": "吾伏嘔呕血。", "b": "《左传·哀公二年》"}, {"t": "其音如呕。", "b": "《山海经·东山经》"}, {"t": "有女子方跪,据树而呕丝北海外也。", "b": "《博物志·异人》"}, {"t": "老夫情怀恶,呕泄卧数日。", "b": "唐·杜甫《北征》"}], "words": [{"w": "呕逆", "t": "恶心想吐"}, {"w": "呕泄", "t": "吐泻"}, {"w": "呕家", "t": "平素患有恶心、呕吐的病人。"}]}, {"meaning": "唱歌。", "cites": [{"t": "其妻亦负戴相随,数止买臣毋歌呕道中。", "b": "《汉书·朱买臣传》"}], "words": [{"w": "呕吟", "t": "歌吟"}, {"w": "呕唱", "t": "唱歌。"}]}, {"meaning": "逗弄;故意惹人生怒。", "cites": [{"t": "你不要呕我。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('726wx','园','1','yuán','囗','7','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从囗(wéi),袁声。形符为“囗”(wéi),表示范围。本义:种蔬菜、花果、树木的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "园,所以树果也。", "b": "《说文》"}, {"t": "种树曰园。", "b": "《三苍》"}, {"t": "园圃毓草木。", "b": "《周礼·大宰》"}, {"t": "以场圃任园地。", "b": "《周礼·载师》。注:“樊圃谓之园。”"}, {"t": "于丘园。", "b": "《易·贲》"}, {"t": "园有桃。", "b": "《诗·魏风·园有桃》"}, {"t": "青青园中葵。", "b": "《乐府诗集·长歌行》"}, {"t": "田园将芜。", "b": "晋·陶渊明《归园田居》"}]}, {"meaning": "又。", "cites": [{"t": "园日涉以成趣。", "b": ""}], "words": [{"w": "园头", "t": "禅寺内管菜园的人"}, {"w": "果园;植物园;园公", "t": "即东园公。商山四皓之一;又指管理花园的仆人"}, {"w": "园户", "t": "指唐宋时种植、制作茶叶的民家。"}]}, {"meaning": "庭园;供人憩息、游乐或观赏的地方。", "cites": [{"t": "白菟素鸠,游君园庭。", "b": "《隶释》"}], "words": [{"w": "园叟花丁", "t": "园丁与花匠"}, {"w": "园叟", "t": "年老的园丁"}, {"w": "公园;戏园;动物园;园客", "t": "游园的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('727wx','旷','1','kuàng','日','7','','[{"pinyin": "kuàng", "defs": [{"meaning": "(会义兼形声。从日,广声。本义:光明;明朗)。"}, {"meaning": "同本义。", "cites": [{"t": "旷,明也。", "b": "《说文》"}, {"t": "旷,光明也。", "b": "《玉篇》"}, {"t": "此人谓照旷。", "b": "《庄子·天地》"}, {"t": "旷若发矇。", "b": "《后汉书》"}], "words": [{"w": "旷旷", "t": "光明;明亮。"}]}, {"meaning": "心境开阔,开朗。", "cites": [{"t": "则有心旷神怡。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "旷度", "t": "宽大的气度"}, {"w": "旷澹", "t": "心胸豁达,不重名利"}, {"w": "旷怀", "t": "开阔的心胸"}, {"w": "旷逸", "t": "心胸开阔,性情超脱"}, {"w": "旷士", "t": "胸襟开阔之士"}, {"w": "旷如", "t": "开阔。"}]}, {"meaning": "空旷;开阔。", "cites": [{"t": "旷兮其若谷。", "b": "《老子》十五章"}, {"t": "居于旷林。", "b": "《左传·昭公元年》"}, {"t": "率彼旷野。", "b": "《诗·小雅·何草不黄》"}, {"t": "独观于昭旷之道。", "b": "《汉书·邹阳传》"}, {"t": "土地平旷。", "b": "晋·陶渊明《桃花源记》"}, {"t": "其下平旷。", "b": "宋·王安石《游褒禅山记》"}, {"t": "星光照旷野。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "旷平", "t": "宽广平坦"}, {"w": "旷廊", "t": "空旷;空阔"}, {"w": "旷僻", "t": "空阔而偏僻"}, {"w": "旷宇", "t": "广阔的原野;宽广的胸怀。"}]}, {"meaning": "久。", "cites": [{"t": "自夏涉玄冬,弥旷大余旬。", "b": "刘桢《赠五官中郎将》"}], "words": [{"w": "旷劫", "t": "佛教指过去时间极长"}, {"w": "旷代", "t": "隔世,谓历时长久。"}]}, {"meaning": "遥远。", "cites": [{"t": "旷如望羊。", "b": "《孔子家语·辨乐》。注:“用志广远。”"}], "words": [{"w": "旷迥", "t": "遥远之处"}, {"w": "旷望", "t": "极目眺望,远望"}, {"w": "旷绝", "t": "僻远。"}]}, {"meaning": "空,使空闲。", "cites": [{"t": "祥车旷左。", "b": "《礼记·曲礼》"}, {"t": "旷安宅而弗居。", "b": "《孟子》"}, {"t": "无旷庶官。", "b": "《书·皋谟》"}, {"t": "无旷其众。", "b": "《国语》"}], "words": [{"w": "旷虚", "t": "虚空;空缺"}, {"w": "旷绝", "t": "空缺"}, {"w": "旷额", "t": "空额。"}]}, {"meaning": "绝。", "cites": [{"t": "许由务光所以旷后世而不闻也。", "b": "清·黄宗羲《原君》"}]}, {"meaning": "耽误;荒废。", "cites": [{"t": "弃德旷宗。", "b": "《左传·昭公十年》"}, {"t": "今得强赵之兵,以杜燕将,旷日持久数岁,令士大夫余子之力尽于沟垒。", "b": "《战国策·赵策四》"}], "words": [{"w": "旷班;旷任;旷惰", "t": "怠惰,荒废职守"}, {"w": "旷官", "t": "官吏荒废职守,才能不足称其职;悬缺待补的官职"}, {"w": "旷土", "t": "荒芜的土地"}, {"w": "旷学", "t": "荒废学业。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('728wx','围','1','wéi','囗','7','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从囗,韦声。“囗”是“围”的古字。本义:环绕)。"}, {"meaning": "同本义。", "cites": [{"t": "囗,回也,象回币之形。", "b": "《说文》。段注:“按,围绕, 周围字当用此。”"}, {"t": "围,裹也。", "b": "《广雅·释诂四》"}, {"t": "范围天地之化。", "b": "《易·系辞上》"}, {"t": "以其一为之被而围之。", "b": "《周礼·考工记·庐人》"}], "words": [{"w": "围堑", "t": "围绕营垒的壕沟"}, {"w": "围圆", "t": "圆形围墙"}, {"w": "围地", "t": "四周山川环绕,形势险峻的地方"}, {"w": "围屏", "t": "屏风"}, {"w": "围落", "t": "篱笆,栅栏。"}]}, {"meaning": "包围。", "cites": [{"t": "秦之围邯郸。", "b": "《史记·平原君虞卿列传》"}, {"t": "兵围邯郸。", "b": "《史记·魏公子列传》"}, {"t": "江都围急。", "b": "清·全祖望《梅花岭记》"}, {"t": "四面围住。", "b": "《广东军务记》"}], "words": [{"w": "围歼;围守", "t": "包围监守"}, {"w": "围取", "t": "包围夺取。"}]}, {"meaning": "防守。", "cites": [{"t": "围,守也。", "b": "《说文》"}, {"t": "围不言战。", "b": "《公羊传·庄公十年》"}], "words": [{"w": "围落", "t": "藩篱。借指防卫。"}]}, {"meaning": "违背;离开。", "cites": [{"t": "其功顺天者天助之,其功逆天者天围之。", "b": "《管子·形势》"}, {"t": "则王以春围其农,夏食其食,秋取其刈,冬陈其宝。", "b": "《商君书·徕民》"}]}, {"meaning": "围子,用土、石、荆棘等围成的防御设施。", "cites": [{"t": "敕军营更筑严围。", "b": "《三国志》"}]}, {"meaning": "打猎的围场;围猎。", "cites": [{"t": "百官戎服骑从,鼓行入围。", "b": "《隋书》"}]}, {"meaning": "封建帝王出外所圈设的禁区。", "cites": [{"t": "今皇上巡幸曰围,取巡狩义。", "b": "俞正燮《癸巳存稿》"}]}, {"meaning": "围田。围占江湖淤滩造的田。"}, {"meaning": "区域。", "cites": [{"t": "上帝是祗,帝命式于九围。", "b": "《诗·商颂·长发》"}]}, {"meaning": "包围圈。", "cites": [{"t": "外围合。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "即撤围。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('729wx','呀','1','yā ya','口','7','','[{"pinyin": "yā", "defs": [{"meaning": "叹词，表示惊疑"}]}, {"pinyin": "ya", "defs": [{"meaning": "表示语气。", "words": [{"w": "他从小就没有了家呀!群众的力量真大呀!老张,快去呀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('730wx','吨','1','dūn','口','7','','[{"pinyin": "dūn", "defs": [{"meaning": "(形声。从口,屯声。本义:重量单位。公制1吨为 1000 公斤)。"}, {"meaning": "同本义。"}, {"meaning": "质量和重量的单位 。以下各种重量单位中的任何一种都叫吨。"}, {"meaning": "等于 20 长担或 2240磅的单位,主要用于英国——亦称“长吨”(long ton)。"}, {"meaning": "等于20短担或2000磅的单位,主要用于美国、加拿大和南非——亦称“短吨”(short ton)。"}, {"meaning": "船舶的内部容积单位,等于100立方英尺——亦称“注册吨” (register ton)。"}, {"meaning": "用来计算船只排水,约等于一长吨海水体积的单位,用来计算船舶排水量,亦等于35立方英尺——亦称“排水吨”(displacement ton)。"}, {"meaning": "船舶装载容积的单位, 通常按 40 立方英尺计算——亦称“装载吨”(freight ton;measurement ton)。"}, {"meaning": "欧洲的木料数量单位,等于480板英尺。"}, {"meaning": "致冷量的单位,等于一吨冰在24小时内融化的致冷效力。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('731wx','足','1','zú','足','7','','[{"pinyin": "zú", "defs": [{"meaning": "(会意。甲骨文字形,上面的方口象膝,下面的“止”即脚,合起来指整个脚。本义:脚)。"}, {"meaning": "(同本义。秦汉以前,“足”和’趾”都表示“脚”;“脚”表示小腿。魏晋以后,三者都表示脚,但在书面语中,多用“足”)。", "cites": [{"t": "足,人之足也,在下,从止口。", "b": "《说文》。按,膝下至跖之总名也。从止,即趾字,从口,象膝形。"}, {"t": "震为足。", "b": "《易·说卦》"}, {"t": "足恭而口圣。", "b": "《大戴礼记》"}, {"t": "手足胼胝,面目黧。", "b": "《韩非子·外储说左上》"}, {"t": "郑人有欲买履者,先自度其足而置之其坐。", "b": "《韩非子》"}, {"t": "假舆马者,非利足也,而致千里。", "b": "《荀子·劝学》"}, {"t": "折臂断足。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "东坡现右足。", "b": "清·魏学洢《核舟记》"}, {"t": "鲁直现左足。", "b": ""}, {"t": "细若文足。", "b": ""}], "words": [{"w": "足心", "t": "脚底的中心"}, {"w": "足炉", "t": "用来暖脚的小火炉"}, {"w": "足不出户", "t": "形容深居家门很少出门"}, {"w": "足衣", "t": "袜子"}, {"w": "足音跫然", "t": "形容久处寂寞,听到人的脚步声,便感到欢欣。"}]}, {"meaning": "支撑器物的脚。", "cites": [{"t": "鼎折足,覆公餗。", "b": "《易·鼎》"}, {"t": "如此则荆、吴之势强,鼎足之形成矣。", "b": "《资治通鉴》"}], "words": [{"w": "鼎足", "t": ""}]}, {"meaning": "充实;完备;足够。", "cites": [{"t": "国无九年之畜曰不足。", "b": "《谷梁传·庄公二十有八年》"}, {"t": "杀所不足。", "b": "《墨子·公输》"}, {"t": "取于食客门下足矣。", "b": "《史记·平原君虞卿列传》"}, {"t": "兵甲已足。", "b": "诸葛亮《出师表》"}, {"t": "力不足。", "b": "唐·韩愈《杂说》"}, {"t": "方是时,余之力尚足以入,火尚足以明也。", "b": "王安石《游褒禅山记》"}, {"t": "一钵足矣。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "足纹", "t": "成色十足的银子"}, {"w": "足钱", "t": "每贯足实一百枚的钱币"}, {"w": "足食足兵", "t": "指国内粮食兵备均甚充足。"}]}, {"meaning": "富裕的。", "cites": [{"t": "民不足而可治者自古及今未之尝闻。", "b": "贾谊《论积贮疏》"}, {"t": "古之畜天下者,无欲而天下足。", "b": "《庄子》"}], "words": [{"w": "足民", "t": "富足,民生富足"}, {"w": "丰足", "t": "富裕。"}]}, {"meaning": "使满足。", "cites": [{"t": "采色不足。", "b": "《孟子·梁惠王上》"}, {"t": "声音不足。", "b": ""}, {"t": "皆不足用。", "b": "明·魏禧《大铁椎传》"}, {"t": "不足子所乎。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "重视。", "cites": [{"t": "法礼足礼,谓之有方之士。", "b": "《荀子·礼论》"}]}, {"meaning": "止。", "cites": [{"t": "为天下谷,常德乃足,复归于朴。", "b": "《老子》"}]}, {"meaning": "完成。", "cites": [{"t": "言以足志,文以足言。", "b": "《左传》"}]}, {"meaning": "值得。", "cites": [{"t": "不足为外人道也。(为,向、对。)", "b": "晋·陶渊明《桃花源记》"}, {"t": "岂足托乎。", "b": "《资治通鉴》"}, {"t": "不足与图大事。", "b": ""}, {"t": "何足道。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "足信", "t": "值得信赖"}, {"w": "不足", "t": "不值得;不够格。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('732wx','邮','1','yóu','阝','7','','[{"pinyin": "yóu", "defs": [{"meaning": "(会意。从邑垂。垂,边郵;邑,城邑。“邮”,从邑,由声。本义:古地名。)。"}, {"meaning": "同本义。", "cites": [{"t": "邮,左冯翊高陵,从邑,由声。", "b": "《说文》。按,邮亭,邮乡,在今陕西西安府高陵县。"}]}, {"meaning": "传递文书的驿站。", "cites": [{"t": "德之流行,速于置邮而传命。", "b": "《孟子·公孙丑上》"}, {"t": "因邮上封事。", "b": "《汉书》"}, {"t": "缮治邮亭。", "b": "《汉书·赵充国传》"}], "words": [{"w": "邮吏", "t": "驿战管邮递的小官"}, {"w": "邮馆", "t": "设在驿站的旅店"}, {"w": "邮驿", "t": "古时办理传送公务信件的地方。"}]}, {"meaning": "指传送文书的人。", "cites": [{"t": "殷洪乔不为致书邮。", "b": "《晋书·殷浩传》"}], "words": [{"w": "邮人", "t": "传递公文书信的人。"}]}, {"meaning": "过失,罪过。", "cites": [{"t": "不知其邮。", "b": "《诗·小雅·宾之初筵》"}, {"t": "邮又甚焉。", "b": "《国语·晋语四》。韦昭注:“邮,过也。”"}, {"t": "以显朕邮。", "b": "《汉书·成帝纪》"}], "words": [{"w": "邮罚", "t": "判人罪过,处罚其身。"}]}, {"meaning": "责怪。", "cites": [{"t": "己无邮人。", "b": "《荀子·成相》"}, {"t": "罪人不邮其上。", "b": "《荀子·议兵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('733wx','男','1','nán','田','7','','[{"pinyin": "nán", "defs": [{"meaning": "(会意。从田,从力。表示用力(一说指耒)在田间耕作。本义:男人,与“女”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "男,丈夫也。从男从力,言男用力于田也。", "b": "《说文》"}, {"t": "乃生男子。", "b": "《诗·小雅·斯干》"}, {"t": "则百斯男。", "b": "《诗·大雅·思齐》"}, {"t": "男女奔窜。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "男女衣著,悉如外人。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "男事", "t": "古指成年男子应尽的职责"}, {"w": "男夫", "t": "成年男子"}, {"w": "男圻", "t": "犹男服"}, {"w": "男教", "t": "对男子的教化"}, {"w": "男德", "t": "有德行的男子"}, {"w": "男权", "t": "男子在家庭、社会中的支配性特权。"}]}, {"meaning": "引申为儿子。", "cites": [{"t": "三男邺成戍。", "b": "唐·杜甫《石壕吏》"}]}, {"meaning": "又。", "cites": [{"t": "一男附书至。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "信知生男恶,反是生女好。", "b": ""}, {"t": "生子是男。", "b": "晋·干宝《搜神记》"}, {"t": "两女一男。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "男花女花", "t": "一男半女;引伸为孩子"}, {"w": "长男;次男;生男育女", "t": ""}]}, {"meaning": "又指儿子对父母的自称。", "cites": [{"t": "男病已愈,胃口亦渐开。", "b": "鲁迅《书信》"}]}, {"meaning": "封建制度五等爵位的第五等。", "cites": [{"t": "王者之制禄爵,公、侯、伯、子、男,凡五等。", "b": "《礼记·王制》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('734wx','困','1','kùn','囗','7','','[{"pinyin": "kùn", "defs": [{"meaning": "(会意。甲骨文字形,从囗(wéi),象房的四壁;里边是生长的树木。本义:废弃的房屋)。"}, {"meaning": "同本义。", "cites": [{"t": "困,故庐也。", "b": "《说文》"}]}, {"meaning": "“梱”的本字。门槛。", "cites": [{"t": "试藉车之力而为之困。", "b": "《墨子·备城门》"}]}, {"meaning": "穷;贫困。", "cites": [{"t": "困,穷也。", "b": "《广雅》"}, {"t": "行而无资谓之乏,居而无食谓之困。", "b": "《周礼·地官·禀人》疏引书传"}, {"t": "四海困穷,天禄永终。", "b": "《论语》"}, {"t": "以振穷困。", "b": "《吕氏春秋·慎大》"}, {"t": "行李之往来,共其乏困。", "b": "《左传·僖公三十年》"}, {"t": "岁饥民困。", "b": "《史记·宋世家》"}, {"t": "今岁不登,已遣使节振贷困乏。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "困污", "t": "生活贫苦,地位低下"}, {"w": "困悴", "t": "贫困愁苦"}, {"w": "困匮", "t": "贫乏,贫困。"}]}, {"meaning": "困难;苦难。", "cites": [{"t": "不以监困故而受。", "b": "《史记·魏公子列传》"}, {"t": "楚大困。", "b": "《史记·屈原贾生列传》"}, {"t": "民困而不知救。", "b": "明·刘基《卖柑者言》"}, {"t": "俾困苦不可忍。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "困穷", "t": "艰难窘迫;生活困苦贫穷"}, {"w": "困笃", "t": "病重垂危"}, {"w": "因踬", "t": "因厄不得升进"}, {"w": "困学", "t": "遇到困难才去学习。指被动学习"}, {"w": "困心衡虑", "t": "尽心竭虑,经过一番艰苦的思考"}, {"w": "困知勉行", "t": "苦学以求知,勉力践行。"}]}, {"meaning": "劳倦;疲倦。", "cites": [{"t": "牛困人饥日已高。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "困约", "t": "困顿贫乏"}, {"w": "困耗", "t": "困顿衰败"}, {"w": "困腾腾", "t": "困倦无神的样子"}, {"w": "困恹恹", "t": "憔悴,没精神。"}]}, {"meaning": "急难、危难。", "cites": [{"t": "能急人之困。", "b": "《史记·魏公子列传》"}]}, {"meaning": "困扰;围困,为人所阨阻。", "cites": [{"t": "敌人远我,欲以火器困我也。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "数十伶人困之。", "b": "宋·欧阳修《伶官传·序》"}]}, {"meaning": "又。", "cites": [{"t": "智勇多困于所溺。", "b": ""}, {"t": "困于心。", "b": "《孟子·告子下》"}, {"t": "困于雨。", "b": "清·周容《竽老人传》"}, {"t": "酒困路长。", "b": "宋·苏轼《浣溪沙》"}, {"t": "致此疾困。", "b": "《明史》"}], "words": [{"w": "困兽", "t": "被围捕的野兽"}, {"w": "困踬", "t": "受挫,失败"}, {"w": "困斗", "t": "被人围困的野兽,仍然极力抵抗,作最后的挣扎"}, {"w": "困蒙", "t": "为蒙昧无知所困扰。"}]}, {"meaning": "阻碍。", "cites": [{"t": "困于石,据于蒺藜。", "b": "《易·困》"}]}, {"meaning": "穷尽。", "cites": [{"t": "樱花落尽春将困。", "b": "南唐·李煜《谢新恩》"}]}, {"meaning": "睡。", "cites": [{"t": "忽昏困如梦。", "b": "宋·王定国《甲申杂录》"}], "words": [{"w": "困头", "t": "想睡的时刻"}, {"w": "困到头忽里", "t": "方言。一觉未醒。忽:睡一觉为一忽"}, {"w": "困到长忽里", "t": "方言。死去"}, {"w": "困梦头里弗曾想着", "t": "方言。竟想不到。"}]}, {"meaning": "疲倦欲睡。", "cites": [{"t": "萧队长困了,只迷糊地回答这一句,又合上眼了。", "b": "周立波《暴风骤雨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('735wx','吵','1','chāo chǎo','口','7','','[{"pinyin": "chāo", "defs": [{"meaning": "——古人名用字。"}]}, {"pinyin": "chǎo", "defs": [{"meaning": "(形声。从口,少声。本义:叫嚷)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('736wx','串','1','guàn chuàn','丨','7','','[{"pinyin": "guàn", "defs": [{"meaning": "习惯。", "cites": [{"t": "宗军人串噉粗食。", "b": "《南史·宗悫传》"}], "words": [{"w": "串用", "t": "惯用"}, {"w": "串习", "t": "习惯。"}]}, {"meaning": "亲近的人。", "cites": [{"t": "团歌遂成赋,聊用布亲串。", "b": "晋·谢惠连《秋怀》"}], "words": [{"w": "亲串;戚串", "t": ""}]}, {"meaning": "亲近,巴结。也作串昵。", "cites": [{"t": "文静数履军陷阵,以才自进,而寂专用串昵显。", "b": "《新唐书》"}]}]}, {"pinyin": "chuàn", "defs": [{"meaning": "多个同类东西连贯在一起", "words": [{"w": "串讲", "t": "讲解文言文的一种传统方式，即讲解词句，串通文意。"}]}, {"meaning": "将物品连贯在一起。亦指连贯而成的物品", "words": [{"w": "串珠子", "t": ""}, {"w": "串珠", "t": ""}]}, {"meaning": "勾结，做坏事", "words": [{"w": "串诈", "t": "合谋诈骗"}, {"w": "串哄", "t": "结伙儿胡闹;起哄"}]}, {"meaning": "交错连接", "words": [{"w": "串线", "t": "电话串线"}, {"w": "串票", "t": "旧时征收钱粮后由官方发给的收据"}]}, {"meaning": "走;到别人家走动", "words": [{"w": "串店", "t": "出入旅店"}, {"w": "串门", "t": "到别人家走动"}]}, {"meaning": "担任戏曲角色", "words": [{"w": "客串", "t": ""}, {"w": "串演", "t": ""}]}, {"meaning": "量词，用于连贯起来的东西"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('737wx','员','1','yuán yún yùn','口','7','','[{"pinyin": "yuán", "defs": [{"meaning": "(会意。甲骨文字形,表示俯视鼎,看到鼎口是圆形的。小篆从贝,口声。本义:物的数量;人员的数额。亦指人员)。"}, {"meaning": "同本义。", "cites": [{"t": "员,物数也。——《说文》。木曰枚,竹曰箇,丝曰总,貝曰员。——《说文》", "b": ""}, {"t": "员,众也。", "b": "《广雅》"}, {"t": "国人过员。", "b": "《汉书·高惠高后功臣表》。注:“数也。”"}, {"t": "责以员程。", "b": "《汉书·尹翁归传》"}, {"t": "今少一人,愿君即以遂备员而行矣。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "员位", "t": "人员定额;职位"}, {"w": "员次", "t": "员额等次。"}]}, {"meaning": "成员。"}, {"meaning": "园形", "cites": [{"t": "以为方员平置。", "b": "《孟子·离娄上》"}, {"t": "员径八尺。", "b": "《后汉书·张衡传》"}, {"t": "其穴竖而起,亦员如井。", "b": "《徐霞客游记》"}], "words": [{"w": "员全", "t": "圆满;周全"}, {"w": "员园", "t": "无棱角,圆滑"}, {"w": "员栅", "t": "用木棒对立的圆形栅栏"}, {"w": "员渊", "t": "圆池。"}]}]}, {"pinyin": "yún", "defs": [{"meaning": "增益。", "cites": [{"t": "员于尔辐。", "b": "《诗·小雅·正月》"}]}, {"meaning": "相当于“云”。", "cites": [{"t": "或、员、云,有也。", "b": "《广雅·释诂一》"}]}]}, {"pinyin": "yùn", "defs": [{"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('738wx','呐','1','nà nè','口','7','','[{"pinyin": "nà", "defs": [{"meaning": "呐喊,大叫。", "cites": [{"t": "且说史进就中堂又放起火来,大开了庄门,呐声喊,杀将出来。", "b": "《水浒传》"}]}, {"meaning": "表示提醒注意。", "cites": [{"t": "呐,我们可以开始了。", "b": "吉学沛《田野里的追逐》"}]}]}, {"pinyin": "nè", "defs": [{"meaning": "(会意兼形声。从口,从内,内亦声。讲话迟钝或口吃,好像在口内存留。本义:说话迟钝或口吃) 同本义。同“讷”。", "cites": [{"t": "言之讷也。", "b": "《说文》"}, {"t": "其辩不若其呐也。", "b": "《荀子·非相》"}, {"t": "广呐口少言。", "b": "《汉书·李广传》"}, {"t": "臣宣呐钝于辞。", "b": "《汉书·鲍宣传》"}, {"t": "呐者言之疑。", "b": "《韩非子·八经》"}], "words": [{"w": "呐口", "t": "说话困难,不流畅"}, {"w": "呐吃", "t": "口吃。说话结结巴巴"}, {"w": "呐呐", "t": "说话迟钝"}, {"w": "呐钝", "t": "语言迟钝。"}]}, {"meaning": "小声说话。", "cites": [{"t": "只听得差拨口里呐出一句‘高太尉’三个字来。", "b": "《水浒》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('739wx','听','1','tīng','口','7','','[{"pinyin": "tīng", "defs": [{"meaning": "(形声。本字从耳德,壬(tìng)声。从耳德,即耳有所得,今简化为“听”。“听”本义“笑貌”。从口,斤声。本义:用耳朵感受声音)。"}, {"meaning": "同本义。", "cites": [{"t": "听,聆也。", "b": "《说文》"}, {"t": "天视自我民视,天听自我民听。", "b": "《书·泰誓中》"}, {"t": "无稽之言勿听。", "b": "《书·大禹谟》"}, {"t": "心不在焉,视而不见,听而不闻。", "b": "《礼记·大学》"}, {"t": "行人驻足听。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "听妇前致词。", "b": "唐·杜甫《石壕吏》"}, {"t": "夜阑卧听风吹雨。", "b": "《资治通鉴·唐纪》"}, {"t": "听于庭。", "b": ""}, {"t": "听取蛙声一片。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "听知", "t": "听到"}, {"w": "听受", "t": "聆听,用耳感受声音"}, {"w": "听言", "t": "道听途说,没有根据的话"}, {"w": "听真", "t": "听得真切"}, {"w": "听直", "t": "听取曲直。"}]}, {"meaning": "接受,听信,接纳。", "cites": [{"t": "不听寡人。", "b": "《战国策·魏策》"}, {"t": "故听之。", "b": "《史记·项羽本纪》"}, {"t": "而听细说。", "b": ""}, {"t": "壹听陵言。", "b": "《汉书·李广苏建传》"}, {"t": "开张圣听。", "b": "诸葛亮《出师表》"}], "words": [{"w": "听人", "t": "听从别人的意见,任人支配。喻愚昧"}, {"w": "听用", "t": "听从并予采用或任用"}, {"w": "听纳", "t": "听从采纳;听谏纳善"}, {"w": "听能", "t": "听从能者的意见"}, {"w": "听唤", "t": "听从使唤。"}]}, {"meaning": "治理,管理或执行事务 。", "words": [{"w": "听政", "t": "执政;处理政务"}, {"w": "听治", "t": "处理政事。"}]}, {"meaning": "决断;审理 。", "words": [{"w": "听决", "t": "听断,判决"}, {"w": "听治", "t": "处理政事。"}]}, {"meaning": "等候;待 。", "words": [{"w": "听用", "t": "听候任用"}, {"w": "听选", "t": "等候任命。"}]}, {"meaning": "听凭,任凭。", "words": [{"w": "听人穿鼻", "t": "让人牵着鼻子走。比喻任人支配而无主见"}, {"w": "听其自便", "t": "听凭人任意行动"}, {"w": "听势", "t": "听凭情势的发展变化。"}]}, {"meaning": "侦察。", "cites": [{"t": "请谓(为)王听东方之处。", "b": "《战国策》"}]}, {"meaning": "耳朵。", "cites": [{"t": "翏翏而为穷苦愁怨之声,不啻风泉之满听矣。", "b": "清·黄宗羲《金介山诗序》"}]}, {"meaning": "马口铁罐。", "words": [{"w": "听装午餐肉;听装咖啡亦用作听装物品的量名", "t": ""}]}, {"meaning": "耳目,间谍。", "cites": [{"t": "且仁人之用十里之国,则将有百里之听。", "b": "《荀子》"}]}, {"meaning": "厅堂。古代官府办公处,后作“厅”。", "cites": [{"t": "病人或至数百,听廊皆满。", "b": "《资治通鉴》"}, {"t": "大司马府听前有一老槐,甚扶疏。", "b": "《世说新语·黜免》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('740wx','吟','1','yín','口','7','','[{"pinyin": "yín", "defs": [{"meaning": "(形声。从口,今声。唫为吟的本字。本义:呻吟、叹息)。"}, {"meaning": "同本义。", "cites": [{"t": "吟,呻也。", "b": "《说文》"}, {"t": "吟,叹也。", "b": "《苍颉篇》"}, {"t": "呿吟至微。", "b": "《素问·宝命全形论》。注:“谓吟叹也。”"}, {"t": "昼吟宵哭。", "b": "《战国策·楚策》"}, {"t": "相送悲吟不尽情,关山陇坂高无极。", "b": "明·何景明《陇右行送徐少参》"}], "words": [{"w": "吟呻", "t": "呻吟。因痛苦而发出哼哼声"}, {"w": "吟啸", "t": "悲叹;哀号。"}]}, {"meaning": "吟咏;诵读。", "cites": [{"t": "倚树而吟。", "b": "《庄子·德充符》"}, {"t": "则将吴吟。", "b": "《战国策·秦策》。注:“歌吟也。”"}, {"t": "盗跖吟口。", "b": "《荀子·不苟》"}, {"t": "吟青黄。", "b": "《汉书·礼乐志》。注:“谓歌诵也。”"}], "words": [{"w": "吟盐咏絮", "t": "对盐吟咏女子的赞词"}, {"w": "吟月", "t": "对月吟诗"}, {"w": "吟弄", "t": "吟唱;吟咏"}, {"w": "吟呻", "t": "吟咏;推敲诗句"}, {"w": "吟玩", "t": "吟咏玩赏"}, {"w": "吟颂", "t": "讴吟歌诵"}, {"w": "吟诗", "t": "吟诵诗歌"}, {"w": "吟歌", "t": "吟咏歌唱"}, {"w": "吟写", "t": "吟咏抒写。"}]}, {"meaning": "鸣,叫。", "cites": [{"t": "熊咆龙吟。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "吟叫", "t": "鸣叫"}, {"w": "吟吼", "t": "吼叫"}, {"w": "吟鸟", "t": "善鸣的鸟"}, {"w": "吟蛩", "t": "鸣叫着的蟋蟀"}, {"w": "吟鸣", "t": "鸣叫"}, {"w": "吟啸", "t": "呼啸;呼叫"}, {"w": "吟虫", "t": "善鸣的虫。"}]}, {"meaning": "作诗,写诗;推敲字句。", "cites": [{"t": "吟安一个字,捻断数茎须。", "b": "卢延让《苦吟》"}], "words": [{"w": "吟怀", "t": "作诗的情怀"}, {"w": "吟讽", "t": "作诗。亦谓作诗讽刺。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('741wx','吩','1','fēn','口','7','','[{"pinyin": "fēn", "defs": [{"meaning": "(也写作\\"分付\\")叮嘱，嘱咐，多用于口头分派或命令这件事，～咐他去办理。～咐她早点回来。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('742wx','呛','1','qiāng qiàng','口','7','','[{"pinyin": "qiāng", "defs": [{"meaning": "鸟啄食物。", "cites": [{"t": "呛,鸟食。", "b": "《玉篇》"}]}]}, {"pinyin": "qiàng", "defs": [{"meaning": "受,忍受。", "cites": [{"t": "没出过远门,怕呛不住。", "b": "靳以《到佛子岭去》"}], "words": [{"w": "呛劲", "t": "憋足劲头,奋力。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('743wx','吻','1','wěn','口','7','','[{"pinyin": "wěn", "defs": [{"meaning": "(形声。从口,勿声。本义:嘴唇)。"}, {"meaning": "同本义。", "cites": [{"t": "吻,唇两角头边也。", "b": "《华严经音义》"}, {"t": "黄吻澜漫赤。", "b": "左思《娇女诗》"}, {"t": "遂鼓吻奋爪以向先生。", "b": "马中锡《中山狼传》"}], "words": [{"w": "接吻;亲吻", "t": ""}]}, {"meaning": "嘴;口。", "cites": [{"t": "使人之吻助己言谈。", "b": "《墨子·尚同中》"}], "words": [{"w": "吻舌", "t": "吻唇。口和舌"}, {"w": "吻吮", "t": "用口吹奏"}, {"w": "吻流", "t": "利口之辈"}, {"w": "吻创", "t": "口疮"}, {"w": "吻翰", "t": "口与笔"}, {"w": "吻噤", "t": "闭口"}, {"w": "吻儒", "t": "善谑利口的儒生。"}]}, {"meaning": "指鸱吻。古建筑屋脊两端的装饰物。", "cites": [{"t": "其制设吻者为殿,无吻者不为殿矣。", "b": "宋·叶梦得《石林燕语》"}]}, {"meaning": "合;闭。", "cites": [{"t": "道士摇着铃注卵子,念几句生意经,吻了材盖。", "b": "清·张南庄《何典》"}], "words": [{"w": "吻着唇点点头", "t": ""}]}, {"meaning": "紧接;相符合。", "cites": [{"t": "闽城吻海而派江,辅山以居。", "b": "唐·沈亚之《闽城开新池记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('744wx','吹','1','chuī','口','7','','[{"pinyin": "chuī", "defs": [{"meaning": "(会意。从口,从欠。“欠”是出气的意思。本义:合拢嘴唇用力呼气)。"}, {"meaning": "同本义。", "cites": [{"t": "吹,嘘也。", "b": "《说文》"}, {"t": "生物之以息相吹也。", "b": "《庄子·逍遥游》"}], "words": [{"w": "吹火筒;吹火", "t": "吹气使火旺盛。古多用竹筒以口吹之"}, {"w": "吹网", "t": "吹气于网中,欲使之鼓满"}, {"w": "吹吁", "t": "吹气和哈气。"}]}, {"meaning": "刮风。", "cites": [{"t": "夜阑卧听风吹雨,铁马冰河入梦来。", "b": "陆游《十一月四日风雨大作》"}], "words": [{"w": "风一阵阵地吹;暴风吹得船搁浅了;吹云", "t": "吹起云气;鼓的别称。"}]}, {"meaning": "引申为吹奏乐器。", "cites": [{"t": "齐宣王使人吹竽,必三百人。", "b": "《韩非子·内储说上》"}], "words": [{"w": "吹手", "t": "吹鼓手"}, {"w": "吹打", "t": "吹打乐器。指演奏乐曲"}, {"w": "吹唇", "t": "吹口哨。"}]}, {"meaning": "说大话,自夸。", "cites": [{"t": "夫言非吹也。", "b": "《庄子·齐物论》"}], "words": [{"w": "吹得天花乱坠;吹镑懵诈", "t": "说大话欺人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('745wx','呜','1','wū','口','7','','[{"pinyin": "wū", "defs": [{"meaning": "口中舒发而出的声音,叹息声。悲叹。", "cites": [{"t": "及与公卿言国家事,未尝不噫呜流涕。", "b": "《后汉书·袁安传》"}], "words": [{"w": "呜呃", "t": "悲叹"}, {"w": "呜乎", "t": "呜呼"}, {"w": "呜唈", "t": "因悲哀、愤懑而抑郁气塞"}, {"w": "呜恻", "t": "悲泣"}, {"w": "呜噎", "t": "呜咽。忧伤悲泣"}, {"w": "呜呼噫嘻", "t": "表示慨叹。"}]}]}]','jingmo-wenyan');
