('746wx','吭','1','háng kēng','口','7','','[{"pinyin": "háng", "defs": [{"meaning": "鸟的喉咙,泛指喉咙;咽喉", "words": [{"w": "吭咽", "t": "咽喉。比喻交通要道"}, {"w": "吭首", "t": "咽喉与头。比喻要害之地"}, {"w": "吭嗌", "t": "咽喉。比喻形势险要的地方。"}]}]}, {"pinyin": "kēng", "defs": [{"meaning": "出声，发言", "words": [{"w": "吭声", "t": ""}, {"w": "吭哧", "t": "形容用力时发出的声音"}, {"w": "吭唧", "t": "〖小孩儿〗发出似哭非哭的声音"}]}]}]','jingmo-wenyan');
