INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('748wx','邑','1','yì','邑','7','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。甲骨文字形。上为囗(wéi),表疆域,下为跪着的人形,表人口。合起来表城邑。“邑”是汉字的一个部首,变体为右耳旁。从“邑”的字多和地名、邦郡有关。本义:国)。"}, {"meaning": "古代称侯国为邑。", "cites": [{"t": "邑,国也。", "b": "《说文》。段玉裁注:“《左传》凡称人曰大国,凡自称曰敞邑。古国邑通称。”朱骏声通训定声:“《书》‘西邑夏’、‘天邑商’、‘大邑周’,皆谓国。”"}, {"t": "君惠徼福于敝邑之社稷。", "b": "《左传·僖公四年》"}], "words": [{"w": "敝邑", "t": "对本国的谦称。"}]}, {"meaning": "国都,京城。", "cites": [{"t": "邑外谓之郊。", "b": "《尔雅》。郭璞注:邑,国都也"}, {"t": "商邑翼翼。", "b": "《诗·商颂·殷武》"}]}, {"meaning": "(翼翼:整齐的样子)。", "cites": [{"t": "是以论其迁邑易京,则同规乎殷盘。", "b": "汉·张衡《东京赋》"}]}, {"meaning": "指古代无先君宗庙的都城。", "cites": [{"t": "凡邑,有宗庙先君之主曰都,无曰邑。", "b": "《左传》。孔颖达疏:小邑有宗庙,则虽小曰都,无乃为邑,为尊宗庙,故小邑与大都同名"}], "words": [{"w": "邑郛", "t": "城郭"}, {"w": "邑门", "t": "城门;都邑之门。"}]}, {"meaning": "泛指一般城镇。大曰都,小曰邑。", "cites": [{"t": "小则获邑,大则获城", "b": "宋·苏洵《六国论》"}, {"t": "日扳仲永环谒于邑人。", "b": "宋·王安石《伤仲永》"}, {"t": "邑小不足容。", "b": "清·张廷玉《明史》"}, {"t": "摄篆旁邑。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "邑有成名。", "b": "《聊斋志异·促织》"}, {"t": "俾入邑庠。", "b": ""}], "words": [{"w": "邑人", "t": "乡邑中的人"}, {"w": "邑子", "t": "同乡,同邑人"}, {"w": "邑屋", "t": "村舍"}, {"w": "邑落", "t": "村落"}, {"w": "邑党", "t": "乡党"}, {"w": "邑闾", "t": "里巷的门"}, {"w": "邑邻", "t": "邻里。"}]}, {"meaning": "旧时县的别称。", "cites": [{"t": "秦有天下,裂都会而为之郡邑。", "b": "唐·柳宗元《封建论》"}, {"t": "故今之邑民,最独畏旱而旱辄连年。", "b": "宋·王安石《上杜学士言开河书》"}], "words": [{"w": "邑乘", "t": "县志;地方志"}, {"w": "邑僚", "t": "县府中的同僚"}, {"w": "邑尉", "t": "县尉"}, {"w": "邑宰", "t": "县邑之长。即县令。"}]}, {"meaning": "通称诸侯的封地、大夫的采地。", "cites": [{"t": "邑万家。", "b": "《战国策·燕策》"}, {"t": "然广不得爵邑。", "b": "《史记·李将军列传》"}], "words": [{"w": "邑入", "t": "贵族在封地上所收的租税"}, {"w": "邑", "t": "邑,采邑;祭肉。借指封地的收入"}, {"w": "邑钱", "t": "封邑的租税收入"}, {"w": "邑赏", "t": "封地和赏赐"}, {"w": "邑粟", "t": "采邑的赋粟"}, {"w": "邑族", "t": "封地和宗族"}, {"w": "邑国", "t": "古代大夫、诸侯的封地"}, {"w": "邑租", "t": "封邑的租赋。"}]}, {"meaning": "居民聚居的地方。", "cites": [{"t": "邑犬群吠。", "b": "唐·柳宗元《柳河东集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('749wx','吼','1','hǒu','口','7','','[{"pinyin": "hǒu", "defs": [{"meaning": "(形声。从口,孔声。本义:大声叫)。"}, {"meaning": "同本义。", "cites": [{"t": "吼,声也。", "b": "《广韵》"}], "words": [{"w": "虎吼;狮子吼;大炮一再地吼", "t": ""}]}, {"meaning": "虹。", "cites": [{"t": "虹谓之吼。", "b": "明·李翊《俗呼小录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('750wx','囤','1','dùn tún','囗','7','','[{"pinyin": "dùn", "defs": [{"meaning": "用木栅围成,填以土石,作堤防或防御工事之用。", "cites": [{"t": "缘河堤埽,止用蒲绳泥草,不能持久。宜编木为囤,填石其中,则水可杀,堤可固。", "b": "《明史》"}]}]}, {"pinyin": "tún", "defs": [{"meaning": "(形声。从囗(wéi),屯声。囗表示一个范围 ①(dùn)本义:储存粮食的器物 ②引申义:储存) 积存。储存。", "cites": [{"t": "囤,屯也,屯聚之也。", "b": "《释名·释宫室》"}], "words": [{"w": "囤塌", "t": "积存;囤积"}, {"w": "囤货;囤粮;囤户", "t": "囤货以牟利的人家。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('751wx','别','1','bié biè','刂','7','','[{"pinyin": "bié", "defs": [{"meaning": "(会意。从冎(guǎ),从刀。“冎”,《说文》:“剔人肉置其骨也。”“别”的小篆形体,是一个表示用刀剔骨头的会意字。本义:分解)。"}, {"meaning": "同本义。", "cites": [{"t": "别,分解也。", "b": "《说文》"}, {"t": "桀之力,别觡伸钩。", "b": "《淮南子·主术训》"}], "words": [{"w": "别割", "t": "分割"}, {"w": "别产", "t": "分割家产;分家"}, {"w": "别国", "t": "从一国分化而成的国家;现常指别的国家。"}]}, {"meaning": "分离;分开;分出。", "cites": [{"t": "岷山导江,东别为沱。", "b": "《书·禹贡》"}, {"t": "久之,颇晓其别蓍布卦意。", "b": "《汉书·张禹传》"}, {"t": "有别券者几何家?", "b": "《管子·问》。注:“别券,谓分契也。”"}, {"t": "别其官属常惠等,各置他所。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "别疏", "t": "分离疏远"}, {"w": "别宥", "t": "除去蒙蔽。指排除主观成见"}, {"w": "别脚", "t": "破绽。"}]}, {"meaning": "区分;辨别。", "cites": [{"t": "知国之安危臧否,若别白黑。", "b": "《荀子·君道》"}, {"t": "我又欲与若别之。", "b": "《列子·杨朱》"}, {"t": "如丝体变为缕体,缕体即是丝体,有何别焉。", "b": "南朝梁·范缜《神灭论》"}], "words": [{"w": "鉴别", "t": "辨别"}, {"w": "分门别类;别白", "t": "分别明白。明辨"}, {"w": "别族", "t": "区别氏族。"}]}, {"meaning": "离别;告别。", "cites": [{"t": "余既不难夫难别兮。", "b": "屈原《离骚》"}, {"t": "天明登前途,独与老翁别。", "b": "唐·杜甫《石壕吏》"}, {"t": "自君别我后。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "生人作死别,恨恨那可论。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "府吏闻此事,心知长别离。(“别”的时间长;“离”的时间短。)", "b": ""}, {"t": "别君去兮何时还?", "b": "李白《梦游天姥吟留别》"}], "words": [{"w": "告别", "t": "离别;告辞"}, {"w": "话别", "t": "别离前在一块儿谈话"}, {"w": "别情", "t": "离别之情"}, {"w": "别绪", "t": "离别时的情感。"}]}, {"meaning": "送别。", "cites": [{"t": "何处可为别,长安青绮门。", "b": "唐·李白《送裴十八图南归嵩山二首》"}], "words": [{"w": "别筵", "t": "送别的宴会"}, {"w": "别敬", "t": "旧时送别时赠钱名目之一。"}]}, {"meaning": "扭、转过去。", "cites": [{"t": "老都管别了脸对众军道…", "b": "《水浒传》"}], "words": [{"w": "别转", "t": "扭过去;掉转"}, {"w": "别折", "t": "折断;拗折。"}]}, {"meaning": "另外的,不同的。", "cites": [{"t": "诗有别趣,非关理也。", "b": "严羽《沧浪诗话》"}, {"t": "再眺山下,则日光晶晶,别一区宇也。", "b": "《徐霞客游记》"}], "words": [{"w": "别驾", "t": "官名。指州刺吏的佐史。因随刺史出巡时另乘传车,故称。"}]}, {"meaning": "特殊的。", "cites": [{"t": "映日荷花别样红。", "b": "宋·杨万里《晓出净慈寺送林子方》"}], "words": [{"w": "别致", "t": "新奇,特别,不同寻常"}, {"w": "别材", "t": "特殊的才能"}, {"w": "别真", "t": "格外纯真"}, {"w": "别趣", "t": "趋向各异。"}]}, {"meaning": "另外(古代没有“另”字,现代“另、另外”的意义在古书中常用“别”字来表示)。", "cites": [{"t": "宜别图之。", "b": "《资治通鉴》"}, {"t": "若欲见子敬,可别过之。", "b": "《资治通鉴》"}, {"t": "已别有旨。", "b": "《后汉书·班超梁慬传》"}, {"t": "是无难,别具本章。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "又当别论;别有心肠", "t": "别有心肝。别有肺肠。另有打算或企图"}, {"w": "别置", "t": "另行安排"}, {"w": "别婚", "t": "另娶。"}]}, {"meaning": "各;各自。", "cites": [{"t": "成树之后,树别下子一石。", "b": "贾思勰《齐民要术》"}, {"t": "死生别处,终始异居。", "b": "班固《白虎通》"}], "words": [{"w": "别裁", "t": "分别裁定,决定取舍"}, {"w": "别自", "t": "各自"}, {"w": "别食", "t": "分别进食。"}]}]}, {"pinyin": "biè", "defs": [{"meaning": "", "words": [{"w": "我想不依他,可又别不过他", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('752wx','吮','1','shǔn','口','7','','[{"pinyin": "shǔn", "defs": [{"meaning": "(形声。从口,允声。本义:用口含吸,缓饮)。"}, {"meaning": "同本义。", "cites": [{"t": "医善吮人之伤,含人之血。", "b": "《韩非子·备内》"}, {"t": "磨牙吮血,杀人如麻。", "b": "李白《蜀道难》"}, {"t": "母曰:“非然也。往年吴公吮其父,其父战不旋踵,遂死于敌。吴公今又吮其子,妾不知其死矣。”", "b": "《史记·孙子吴起列传》"}, {"t": "卒有病疽者,起为吮之。", "b": ""}], "words": [{"w": "吮痈", "t": "用嘴吸痈疽的脓血以祛毒"}, {"w": "吮疮", "t": "以口嘬吸疮疽之毒"}, {"w": "吮卒", "t": "为士兵嘬吸疮口的脓血"}, {"w": "吮嘬", "t": "用嘴吸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('753wx','岖','1','qū','山','7','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从山,区声。崎岖,地面高低不平的样子)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('754wx','岗','1','gǎng gāng gàng','山','7','','[{"pinyin": "gǎng", "defs": [{"meaning": "(形声。从山,冈声。本义:岗位,哨位)。"}, {"meaning": "土石坡儿 。如:黄土岗儿。亦指平面上凸起的长道。如:胸口上肿起一道岗子。"}]}, {"pinyin": "gāng", "defs": [{"meaning": "山脊,山岭。", "cites": [{"t": "振衣千仞岗,濯足万里流。", "b": "晋·左思《咏史》之五"}]}]}, {"pinyin": "gàng", "defs": [{"meaning": "", "words": [{"w": "岗尖", "t": "形容极满;超出一般;极好。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('755wx','帐','1','zhàng','巾','7','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从巾,长声。巾,麻丝织品。本义:篷帐,有顶的篷帐)。"}, {"meaning": "同本义 。一种张挂或支架起来作为遮蔽用的器物。通常用布帛毡革制成。", "cites": [{"t": "帐,帱也。", "b": "《说文》"}, {"t": "帱谓之帐。", "b": "《尔雅》"}, {"t": "在上曰帐,在旁曰帷,禅帐曰帱。", "b": "《何承天纂要》"}, {"t": "项羽晨朝上将军宋义,即其帐中斩宋义头。", "b": "《史记·项羽本纪》"}, {"t": "战士军前半死生,美人帐下犹歌舞。", "b": "唐·高适《燕歌行》"}], "words": [{"w": "帷帐", "t": "帷是四周相围而无顶的篷帐;帐是有顶的篷帐"}, {"w": "帐具", "t": "陈列帷帐入筵。指备膳、帷帐和膳具"}, {"w": "帐门", "t": "篷帐的出入口"}, {"w": "帐下", "t": "营帐中;将帅的部下"}, {"w": "帐内", "t": "军幕中的将佐"}, {"w": "帐天", "t": "布篷"}, {"w": "帐落", "t": "游牧部落聚居之处"}, {"w": "帐殿", "t": "作为行宫的帐幕"}, {"w": "帐幄", "t": "帐御。帷帐衣服等"}, {"w": "帐饮", "t": "在郊野张设篷帐,宴饮送别"}, {"w": "帐饯", "t": "设帐置酒饯行。"}]}, {"meaning": "蚊帐,床帐。", "cites": [{"t": "帐,张也,张施于床上也。", "b": "《释名》"}, {"t": "偷夜解齐将军之帱帐而献之。", "b": "《淮南子》"}], "words": [{"w": "帐檐", "t": "帐荫子。帐子前幅上端下垂如檐,用作装饰的横幅"}, {"w": "帐钩", "t": "床帐的金属框架。"}]}, {"meaning": "古代游牧民族计算人户的单位 。因他们逐水草而居,每户住一顶帐篷,故按帐计人户数。", "cites": [{"t": "帐者,犹中国之户数也。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('756wx','财','1','cái','贝','7','','[{"pinyin": "cái", "defs": [{"meaning": "(形声。从贝,才声。本义:财物)。"}, {"meaning": "同本义(多指日常生活必需品,包括米粟在内)。", "cites": [{"t": "财,人所宝也。", "b": "《说文》"}, {"t": "财,货也。", "b": "《广雅》"}, {"t": "以九赋敛财贿。", "b": "《周礼·太宰》。注:“泉谷也。”"}, {"t": "与其财用。", "b": "《周礼·职方式》。注:“帛谷货贿也。”"}, {"t": "先财而后礼。", "b": "《礼记·坊记》。注:“币帛也。”"}, {"t": "此轻财而重礼之义也。", "b": "《礼记·聘义》。注:“谓璧琮享币也。”"}, {"t": "财之为言才也。凡粟米丝麻材木可用者曰财。", "b": "《六书故》"}, {"t": "乘其财用之出入。", "b": "《周礼·天官·宰夫》"}, {"t": "暮而果大亡其财。", "b": "《韩非子·说难》"}, {"t": "苟粟多而财有余,何为而不成?", "b": "贾谊《论积贮疏》"}], "words": [{"w": "资财", "t": "资金与财物"}, {"w": "生财;地财;浮财;洋财;邪财", "t": ""}]}, {"meaning": "财富;财产。", "cites": [{"t": "终不以监门困故而受公子财。", "b": "《史记·魏公子列传》"}, {"t": "务本节用财无极。", "b": "《荀子·成相》"}], "words": [{"w": "钱财;敛财", "t": "搜括钱财。"}]}, {"meaning": "仅仅。", "cites": [{"t": "财令陵为助兵。", "b": "《汉书·李陵传》"}, {"t": "士财有数千。", "b": "《汉书·李广利传》"}]}, {"meaning": "刚刚。", "cites": [{"t": "乃为小冠,高广财二寸。", "b": "《汉书·杜钦传》"}]}, {"meaning": ""}, {"meaning": "裁成,裁制。", "cites": [{"t": "天地交泰,后以财成天地人道。", "b": "《易·泰》"}, {"t": "一天下,财万物,长养人民,兼利天下。", "b": "《荀子·非十二子》"}, {"t": "财制礼义之宜 。", "b": "《淮南子·要略》"}]}, {"meaning": "裁断,指材料的剪裁和人事的论断。", "cites": [{"t": "凡物载名而来,圣人因而财之,而天之治。", "b": "《管子·心术下》"}, {"t": "斩山木而财之。", "b": "《韩非子·十过》"}]}, {"meaning": "节制,制裁。", "cites": [{"t": "民重则君轻,民轻则君重,此乃财馀以满不足之数也。", "b": "《管子·揆度》"}, {"t": "财非其类,以养其类,夫是之谓天养。", "b": "《荀子·天论》"}]}, {"meaning": "杀,自杀。", "cites": [{"t": "于嗟不可悔兮,宁早自财。", "b": "《史记·吕太后本纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('757wx','针','1','zhēn','钅','7','','[{"pinyin": "zhēn", "defs": [{"meaning": "(会意。从金,从十。最初用的竹针,写作“箴”,后来有了金属的针,写作“鍼”(针)。本义:缝衣的用具)。"}, {"meaning": "同本义。"}, {"meaning": "缝缀衣物的用具。也叫“引线”。", "cites": [{"t": "鍼,所以缝也。", "b": "《说文》。字亦作针。"}, {"t": "挫鍼治繲,足以糊口。", "b": "《庄子·人间世》"}, {"t": "若当针,不过一二处。", "b": "《三国志·华陀传》"}, {"t": "月小看针暗,云开见缕明。", "b": "陈叔宝《七夕宴玄圃诗》"}], "words": [{"w": "针头线脑", "t": "做针线活的零碎物件"}, {"w": "针巧", "t": "针线的工夫精巧"}, {"w": "针缕", "t": "即“针线”。也作“鍼缕”、“鍼镂”"}, {"w": "针关", "t": "针孔"}, {"w": "针颖", "t": "针尖"}, {"w": "针头", "t": "针尖。借指绣针"}, {"w": "针锋", "t": "针尖"}, {"w": "针帖", "t": "插针用的线板"}, {"w": "针虱", "t": "针马虱。比喻细微之物"}, {"w": "针尖不倒", "t": "指手不停针"}, {"w": "针衣", "t": "藏针用的带。"}]}, {"meaning": "医疗用具。用石或金属做成。", "cites": [{"t": "鍼石运乎手爪。", "b": "《后汉书·文苑赵壹传》"}], "words": [{"w": "针石", "t": "用以治病的石针"}, {"w": "针艾", "t": "即针灸"}, {"w": "针膏", "t": "针饵。针灸和药物"}, {"w": "针剂", "t": "针灸和药剂。"}]}, {"meaning": "缝。", "cites": [{"t": "因命染人与针女,先制两裘赠二君。", "b": "唐·白居易《醉后狂言酬赠萧殷二协律》"}], "words": [{"w": "针线娘", "t": "替富人做针线活儿的妇女"}, {"w": "针黹", "t": "缝纫、刺绣等针线活儿"}, {"w": "针指", "t": "缝纫、刺线之类的针线活计"}, {"w": "针姑", "t": "制衣之神"}, {"w": "针女", "t": "缝纫女工"}, {"w": "针匠", "t": "裁缝"}, {"w": "针纫", "t": "缝纫"}, {"w": "针妇", "t": "俗名纺织娘。即络纬"}, {"w": "针绝", "t": "绝妙的缝纫、刺绣手艺"}, {"w": "针缀", "t": "缝纫。"}]}, {"meaning": "刺。", "cites": [{"t": "鍼,刺也。", "b": "《广雅》"}, {"t": "针之立死。", "b": "《物类相感志》"}], "words": [{"w": "针笔匠", "t": "在人身上刺画花纹的技师"}, {"w": "针史", "t": "唐末无赖之徒于身上刺字,录入文字或记经历,称为“针史”"}, {"w": "针绣", "t": "刺绣。"}]}, {"meaning": "以针刺治病。", "cites": [{"t": "太祖苦头风,每发,心乱目眩,佗针鬲,随手而差。", "b": "《三国志》"}], "words": [{"w": "针治", "t": "针灸治病"}, {"w": "针科", "t": "针灸科"}, {"w": "针师", "t": "针灸医师。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('758wx','钉','1','dīng dìng','钅','7','','[{"pinyin": "dīng", "defs": [{"meaning": "(形声。从金,丁声。本义:鍊饼黄金)。"}, {"meaning": "钉子 ,用以贯穿物体使结合牢固的东西。", "cites": [{"t": "假借为丁,今俗用为铁钉字。", "b": "《说文通训定声》"}], "words": [{"w": "钉铰", "t": "一种金属零件。凡刀柄鞍首等皆有此"}, {"w": "钉靴", "t": "鞋底钉钉,雨天可以防滑的鞋。"}]}, {"meaning": "催促;监督;紧迫。", "cites": [{"t": "小珍儿还是尽钉着问,这叫什么,那叫什么。", "b": "张天翼《宝葫芦的秘密》"}]}]}, {"pinyin": "dìng", "defs": [{"meaning": "用锐器刺人。", "cites": [{"t": "以棘针钉其心,女遂患心痛。", "b": "《晋书·文苑传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('759wx','牡','1','mǔ','牜','7','','[{"pinyin": "mǔ", "defs": [{"meaning": "(会意。从牛,土声。甲骨文字形,左为阳性生殖器。本义:雄性的鸟兽)。"}, {"meaning": "同本义。", "cites": [{"t": "牡,畜父也。", "b": "《说文》"}, {"t": "駉駉牡马。", "b": "《诗·鲁颂·駉》"}, {"t": "雉鸣求其牡。", "b": "《诗·邶风·匏有苦叶》"}]}, {"meaning": "男性生殖器。", "cites": [{"t": "男露其牡,女张其牝。", "b": "汉·东方朔《神异记》"}]}, {"meaning": "雄性的,在生殖过程中起授精作用从而生育下一代的生物。", "cites": [{"t": "牡麻者,枲麻也。", "b": "《仪礼·丧服传》"}, {"t": "阳奇为牡。", "b": "《汉书·五行志》"}, {"t": "丘陵为牡。", "b": "《大戴礼记·易本命》"}], "words": [{"w": "牡鸡;牡牝", "t": "雄性和雌性"}, {"w": "牡麻", "t": "大麻的雄株。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('760wx','告','1','gào','口','7','','[{"pinyin": "gào", "defs": [{"meaning": "(会意。甲骨文字形,上面的“牛”,牛触人,角着横木,所以告人也。从口,从牛。本义:报告,上报)。"}, {"meaning": "同本义。", "cites": [{"t": "告,牛触人。角着横木,所以告人也。", "b": "《说文》"}, {"t": "乃告太王王季文王。", "b": "《书·金滕》"}, {"t": "告公用圭。", "b": "《易·益》"}, {"t": "必告父母。", "b": "《诗·齐风·南山》"}, {"t": "以告于乡先生君子。", "b": "《仪礼·乡射礼》"}, {"t": "告,请也。", "b": "《尔雅·释言》"}, {"t": "敢以告于先君。", "b": "《吕氏春秋·赞能》"}, {"t": "敢敬告天子。", "b": "《书·康王之诰》"}, {"t": "予誓告汝。", "b": "《书·甘誓》"}, {"t": "诞告万方。", "b": "《书·汤诰》"}, {"t": "不告而娶。", "b": "《列子·杨朱》"}, {"t": "不效则治臣之罪,以告先帝之灵。", "b": "诸葛亮《出师表》"}, {"t": "入于太庙,还矢先王,而告以成功。", "b": "宋·欧阳修《新五代史·伶官传·序》"}, {"t": "或告元济曰:“官军至矣!”", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "告事", "t": "报告情况"}, {"w": "告报", "t": "报告;禀报"}, {"w": "告变", "t": "报告发生变故"}, {"w": "告荒", "t": "报告灾情。"}]}, {"meaning": "把话说给别人听,告诉。", "cites": [{"t": "告,语也。", "b": "《玉篇》"}, {"t": "公语之故,且告之悔。", "b": "《左传·隐公元年》"}, {"t": "愿三老、巫祝、父老送女河上,幸来告语之。", "b": "《史记·滑稽列传》"}, {"t": "项伯乃夜驰之沛公军,私见张良,具告以事。", "b": "《史记·项羽本纪》"}], "words": [{"w": "转告;电告;正告", "t": "严正地告诉"}, {"w": "告讼", "t": "告诉"}, {"w": "告称", "t": "告诉;告说"}, {"w": "告托", "t": "告诉,嘱托。"}]}, {"meaning": "揭发,告状,控告。", "cites": [{"t": "点纸连名,我可便直告到中书省。", "b": "《陈州粜米》"}, {"t": "小人告了一年的状,竟无人作主。", "b": "《红楼梦》"}], "words": [{"w": "上告", "t": "向上级机关或司法部门告状"}, {"w": "诬告;控告;告首", "t": "告发"}, {"w": "告引", "t": "互相告发;牵连而出。"}]}, {"meaning": "请求。", "cites": [{"t": "夫为人子者,出必告,反必面。", "b": "《礼记》"}, {"t": "(曹操)佯怒夏侯杶,亦欲斩之。众官告免。", "b": "《三国演义》"}], "words": [{"w": "告致", "t": "官员告老退休"}, {"w": "告饮", "t": "请饮"}, {"w": "告籴", "t": "请求买粮"}, {"w": "告请", "t": "申请,请求"}, {"w": "告命", "t": "请命。"}]}, {"meaning": "谕告,宣告", "cites": [{"t": "告,教也。", "b": "蔡邕《独断》"}, {"t": "燕居告温温。", "b": "《礼记·玉藻》。注:“谓教使也。”"}, {"t": "天子告朔于诸侯。", "b": "《谷梁传·文公十六年》"}], "words": [{"w": "告誓", "t": "宣誓;祷告"}, {"w": "告教", "t": "告喻教诲"}, {"w": "告匮", "t": "宣告物质短缺"}, {"w": "告谴", "t": "宣示谴责之意。"}]}, {"meaning": "告别,辞行。", "cites": [{"t": "足下待故人如此,便请告退。", "b": "《三国演义》"}], "words": [{"w": "告诀", "t": "告别"}, {"w": "告行", "t": "告别,辞行。"}]}, {"meaning": "光亮,洁白。", "cites": [{"t": "明告君子,吾将以为类兮。", "b": "《楚辞》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('761wx','我','1','wǒ','戈','7','','[{"pinyin": "wǒ", "defs": [{"meaning": "(会意。从戈,从戈。“我”表示兵器。甲骨文字形象兵器形。本义:兵器。基本义:第一人称代词)。"}, {"meaning": "自称;自己。", "cites": [{"t": "我,施身自谓也。", "b": "《说文》"}, {"t": "观我生。", "b": "《易·观卦》"}, {"t": "万物皆备于我矣。", "b": "《孟子·尽心上》"}]}, {"meaning": "向一边倾斜的,扭歪的。", "cites": [{"t": "我,顷顿也。", "b": "《说文》。段玉裁注:“谓倾侧也。顷,头不正也。顿,下首也。故引申为顷侧之意。”"}]}, {"meaning": "杀。", "cites": [{"t": "我伐用张。", "b": "《书·泰誓中》"}, {"t": "我,古杀字。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('762wx','乱','1','luàn','乙','7','','[{"pinyin": "luàn", "defs": [{"meaning": "(会意。金文字形,象上下两手在整理架子上散乱的丝。是“乱”的本字。本义:理丝)。"}, {"meaning": "同本义。", "cites": [{"t": "人以一手持丝,又一手持互以收之,丝易乱,以互收之,则有条不紊,故字训治训理也。", "b": "杨树达《积微居小学述林》"}]}, {"meaning": "治理。", "cites": [{"t": "予有乱臣十人。", "b": "《论语》"}], "words": [{"w": "乱政", "t": "治理政务;干扰、败坏政治。"}]}, {"meaning": "扰乱;打乱;使乱。", "cites": [{"t": "行拂乱其所为。", "b": "《孟子·告子下》"}, {"t": "沽名乱政。", "b": "清·张廷玉《明史》"}, {"t": "与江水乱。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "乱行", "t": "打乱了的行列"}, {"w": "乱目", "t": "扰乱视觉"}, {"w": "乱神", "t": "扰乱心神。"}]}, {"meaning": "淫乱,玩弄。", "cites": [{"t": "始乱之,终弃之。", "b": "元稹《会真记》"}], "words": [{"w": "乱失", "t": "淫乱放荡。"}]}, {"meaning": "败坏;破坏。", "cites": [{"t": "坏法乱纪。", "b": "《礼记·礼运》"}, {"t": "欲洁其身而乱大伦。", "b": "《论语·微子》"}, {"t": "是乱天下也。", "b": "《孟子·滕文公上》"}], "words": [{"w": "乱家", "t": "伦常败坏的家庭"}, {"w": "乱俗", "t": "败坏风俗"}, {"w": "乱纪", "t": "败坏法纪。"}]}, {"meaning": "为丧事奔忙。", "cites": [{"t": "他父亲死了,我在他家帮着乱了几日", "b": ""}]}, {"meaning": "烦乱。", "cites": [{"t": "当时曹操心乱,不能稳睡。", "b": "《三国演义》"}], "words": [{"w": "乱志", "t": "烦乱的心志。"}]}, {"meaning": "横渡。", "cites": [{"t": "乱于河。", "b": "《书·禹贡》"}]}, {"meaning": "昏乱;迷乱。", "cites": [{"t": "酒乱其神也。", "b": "《荀子》"}], "words": [{"w": "乱行", "t": "昏乱的行为"}, {"w": "乱命", "t": "临死前神志昏迷时留下的遗言"}, {"w": "乱性", "t": "迷乱心性"}, {"w": "乱朝", "t": "昏乱的朝廷。"}]}, {"meaning": "混乱;无秩序。", "cites": [{"t": "视其辙乱。", "b": "《左传·庄公十年》"}, {"t": "人影散乱。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "于乱石间择其一二扣之。", "b": "宋·苏轼《石钟山记》"}, {"t": "群莺乱飞。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "乱法", "t": "混乱的法令"}, {"w": "乱纪", "t": "混乱的时代"}, {"w": "乱哄", "t": "混乱;吵闹"}, {"w": "乱松松", "t": "头发散乱蓬松的样子"}, {"w": "乱人", "t": "违背正道或制造混乱的人。"}]}, {"meaning": "混杂,杂。", "cites": [{"t": "乱之楮叶之中而不可别也。", "b": "《韩非子》"}], "words": [{"w": "乱烘烘", "t": "纷杂混乱的样子"}, {"w": "乱葬地", "t": "乱葬岗,乱葬埂。旧时埋葬无主尸体和死去的穷人的地方。"}]}, {"meaning": "随意,随便;任意。", "cites": [{"t": "乱罚无罪,杀无辜。", "b": "《书·无逸》"}], "words": [{"w": "乱背弓空", "t": "意借债"}, {"w": "乱开玩笑;乱吃;乱出主意;乱跑;乱说乱动", "t": ""}]}, {"meaning": "叛乱;动乱;不安定。", "cites": [{"t": "治乱非天也。", "b": "《荀子·天论》"}]}, {"meaning": "又。", "cites": [{"t": "禹以治,桀以乱。", "b": ""}, {"t": "危邦不入,乱邦不居。", "b": "《论语·泰伯》"}, {"t": "吴民之乱。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "又。", "cites": [{"t": "大阉之乱。", "b": ""}, {"t": "桀纣暴乱。", "b": "《韩非子·五蠹》"}, {"t": "乱者四应。", "b": "宋·欧阳修《新五代史·伶官传·序》"}, {"t": "避秦时乱。", "b": "晋·陶渊明《桃花源记》"}, {"t": "苟全性命于乱世。", "b": "诸葛亮《出师表》"}, {"t": "避乱江东。", "b": "《资治通鉴》"}, {"t": "国无法则乱。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "乱邦", "t": "动乱的国家"}, {"w": "乱危", "t": "动乱;不安定"}, {"w": "乱法", "t": "引起国家动乱"}, {"w": "乱萌", "t": "动乱的苗头"}, {"w": "乱言", "t": "作乱的话"}, {"w": "乱逆", "t": "叛乱,叛逆"}, {"w": "乱贼", "t": "叛乱"}, {"w": "乱谋", "t": "叛乱的阴谋"}, {"w": "乱党", "t": "旧时当政者对叛逆集团或其成员的称谓。"}]}, {"meaning": "淫乱的事,男女胡乱的性交。", "cites": [{"t": "欲与乱,以止其口。", "b": "《汉书·衡山王传》"}], "words": [{"w": "乱气", "t": "淫乱之气"}, {"w": "乱族", "t": "家族内部的淫乱"}, {"w": "乱孽", "t": "淫乱邪恶。"}]}, {"meaning": "危害;祸乱。", "cites": [{"t": "当断不断,反受其乱。", "b": "《汉书·霍光传》"}], "words": [{"w": "乱首", "t": "祸乱的开端"}, {"w": "乱根", "t": "祸乱的根源"}, {"w": "乱萌", "t": "祸乱的苗子"}, {"w": "乱祸", "t": "祸乱。"}]}, {"meaning": "乐章的尾声叫做乱 。辞赋里用在篇末,总括全篇思想内容的文字也叫乱。", "cites": [{"t": "乱曰。", "b": "《楚辞·屈原·涉江》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('763wx','利','1','lì','刂','7','','[{"pinyin": "lì", "defs": [{"meaning": "(会意。从刀,从禾。表示以刀断禾的意思。本义:刀剑锋利,刀口快)。"}, {"meaning": "同本义。", "cites": [{"t": "利铦也。", "b": "《说文》"}, {"t": "其利断金。", "b": "《易·系辞》"}, {"t": "国之利器,不可以示人。", "b": "《老子》"}, {"t": "木受绳则直,金就砺则利。", "b": "《荀子·劝学》"}, {"t": "兵革非不坚利也。", "b": "《孟子·公孙丑下》"}]}, {"meaning": "又。", "cites": [{"t": "不以兵革之利。", "b": ""}, {"t": "则国之伤也若以利剑刺之。", "b": "《韩非子·解老》"}, {"t": "非兵不利。", "b": "宋·苏洵《六国论》"}, {"t": "求天下之利匕首。", "b": "《战国策·燕策》"}]}, {"meaning": "又泛指锐利。", "cites": [{"t": "吾矛之利,于物无不陷也。", "b": "《韩非子·难一》"}], "words": [{"w": "利爪;利喙", "t": "尖利的嘴"}, {"w": "利矢", "t": "锋利的箭"}, {"w": "利口辩给", "t": "能言善辩,含贬义"}, {"w": "利金", "t": "锋利的兵器。"}]}, {"meaning": "快;敏捷。", "cites": [{"t": "假舆马者,非利足也,而致千里。", "b": "《荀子·劝学》"}, {"t": "子贡利口巧辞。", "b": "《史记·仲尼弟子传》"}], "words": [{"w": "利马", "t": "快马"}, {"w": "利嗖", "t": "轻快利落"}, {"w": "利爽", "t": "灵活敏捷"}, {"w": "利屣", "t": "舞屣,头小而尖的鞋子"}, {"w": "利便", "t": "伶利。"}]}, {"meaning": "吉利;顺利。", "cites": [{"t": "时不利兮骓不逝。", "b": "《史记·项羽本纪》"}, {"t": "探军不利。", "b": "《资治通鉴》"}, {"t": "因利乘便。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "利钝", "t": "顺利与挫折"}, {"w": "利市酒", "t": "为祈祷好运而喝的酒"}, {"w": "利时", "t": "吉时。"}]}, {"meaning": "有利的。", "cites": [{"t": "善战者因其势而利导之。", "b": "《资治通鉴》"}]}, {"meaning": "重要的;要害的。", "cites": [{"t": "怀抱利器", "b": "韩愈《送董邵南序》"}, {"t": "国之利器不可以示人。", "b": "《庄子·胠箧》"}]}, {"meaning": "利益。", "cites": [{"t": "上下之利,若是其异也。", "b": "《韩非子·五蠹》"}, {"t": "有蒋氏者,专其利三世矣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "利尽南海。", "b": "《三国志·诸葛亮传》"}, {"t": "火器利袭远。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "又。", "cites": [{"t": "技击利巷战。", "b": ""}], "words": [{"w": "福利", "t": "生活上的利益,特指对职工生活的照顾"}, {"w": "利孔", "t": "获得利益的来源。"}]}, {"meaning": "赢利;利息。", "cites": [{"t": "逐什一之利。", "b": "《史记·越王勾践世家》"}, {"t": "欲居之以为利。", "b": "《聊斋志异·促织》"}, {"t": "商人重利轻别离。", "b": "白居易《琵琶行(并序)》"}], "words": [{"w": "暴利", "t": "巨额利润"}, {"w": "利赢", "t": "赢利;利润"}, {"w": "利子", "t": "利息。"}]}, {"meaning": "财利。", "cites": [{"t": "君子喻于义,小人喻于利。", "b": "《论语·里仁》"}, {"t": "毋示以利。", "b": "汉·桓宽《盐铁论本文》"}], "words": [{"w": "利禄", "t": "财利与爵禄"}, {"w": "利路", "t": "生财门路;钱财"}, {"w": "利物", "t": "给优胜者的钱物;赃物。"}]}, {"meaning": "指个人的安危。", "cites": [{"t": "但欲求死,不复顾利害。", "b": "宋·文天祥《指南录后序》"}]}, {"meaning": "胜利。", "cites": [{"t": "必以全争于天下,故兵不顿而利可全。", "b": "《孙子》"}]}, {"meaning": "物资出产。", "cites": [{"t": "荆州北据汉、沔,利尽南海。", "b": "陈寿《三国志》"}, {"t": "力过吏势,以利相倾。", "b": "汉·晁错《论贵粟疏》"}, {"t": "西有巴蜀汉中之利。", "b": "《战国策·秦策一》"}]}, {"meaning": "", "cites": [{"t": "轻土多利。", "b": "《淮南子·地形》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('764wx','秃','1','tū','禾','7','','[{"pinyin": "tū", "defs": [{"meaning": "(象形。从人,上象禾粟之形。本义:头顶无发)。"}, {"meaning": "同本义。", "cites": [{"t": "秃,无发也。", "b": "《说文》"}, {"t": "秃者不免。", "b": "《礼记·问丧》"}, {"t": "秃者不髽。", "b": "《礼记·丧服四制》"}, {"t": "齐人谓无发为秃揭。", "b": "《礼记·明堂位》注"}, {"t": "秃翁。", "b": "《后汉书·匈奴传》。注:“即乃翁也。”"}, {"t": "齿危发秃。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "秃厮", "t": "光头家伙"}, {"w": "秃科子", "t": "秃脑瓜"}, {"w": "秃驴", "t": "光头驴。骂和尚的话"}, {"w": "秃颅", "t": "秃头"}, {"w": "秃人", "t": "秃发的人"}, {"w": "秃儿", "t": "犹秃奴"}, {"w": "秃发", "t": "头发脱落。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('765wx','秀','1','xiù','禾','7','','[{"pinyin": "xiù", "defs": [{"meaning": "(会意。石鼓文,上为“禾”,下象禾穗摇曳。本义:谷物抽穗扬花)。"}, {"meaning": "同本义。", "cites": [{"t": "荣而实者谓之秀。", "b": "《尔雅》"}, {"t": "秀,出也。", "b": "《广雅》"}, {"t": "实发实秀,实坚实好。", "b": "《诗·大雅·生民》"}], "words": [{"w": "秀发", "t": "指植物生长繁茂,花朵盛开"}, {"w": "秀穗", "t": "植物从叶鞘长出穗"}, {"w": "秀而不实", "t": "禾谷叶穗开花而不结实。"}]}, {"meaning": "草类结实。", "words": [{"w": "秀孚", "t": "开花结实。"}]}, {"meaning": "成长。", "cites": [{"t": "振振子孙,或秀或苗。", "b": "《后汉书·孝章皇帝八王传赞》"}], "words": [{"w": "秀茂", "t": "生长茂盛"}, {"w": "秀甲", "t": "娇嫩的新芽。"}]}, {"meaning": "美好,秀丽(指人的容貌姿态或景物,重于内在的气韵)。", "cites": [{"t": "容则秀雅,稚朱颜只。", "b": "《楚辞·大招》"}, {"t": "曲眉丰颊,清声而便体,秀外而惠中。", "b": "韩愈《送李愿归盘谷序》"}, {"t": "望之蔚然而深秀者琅琊也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "佳木秀", "b": ""}, {"t": "天下奇秀。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "秀出半天。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "秀溜", "t": "秀气;俊巧"}, {"w": "秀而不媚", "t": "秀丽而不妖媚"}, {"w": "秀上", "t": "秀美高雅"}, {"w": "秀木", "t": "秀美的树木。"}]}, {"meaning": "茂盛。亦指茂盛的草木。", "cites": [{"t": "野芳发而幽香,佳木秀而繁阴。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "秀草", "t": "茂盛之草"}, {"w": "秀蔚", "t": "谓山陵秀美草木繁茂。"}]}, {"meaning": "特异;优秀。多指人品德美好。", "cites": [{"t": "五行之秀气也。", "b": "《礼记·礼运》"}, {"t": "容则秀雅,稚朱颜只。", "b": "《楚辞·屈原·大招》"}, {"t": "后剌史臣荣,举臣秀才。", "b": "李密《陈情表》"}, {"t": "马弟吾乡秀,青云正壮年。", "b": "元·张宇《送马德新》"}, {"t": "木秀于林,风必摧之。", "b": "三国魏·李康《运命论》"}], "words": [{"w": "秀士", "t": "德行才艺出众的人"}, {"w": "秀世", "t": "特出于世"}, {"w": "秀立", "t": "秀升特出"}, {"w": "秀艾", "t": "优异俊美之士"}, {"w": "秀茂", "t": "优异突出的人才。"}]}, {"meaning": "草木之花。", "cites": [{"t": "采三秀兮于山间。", "b": "《楚辞·山鬼》。按,三秀即小正之秀幽、秀萑苇、秀莽也。灵芝之说起于汉,古芝即菌,王逸注:“三秀,芝草,失之。”"}, {"t": "兰有秀兮菊有芳,携佳人兮不能忘。", "b": "汉武帝《秋风辞》"}]}, {"meaning": "宋、明间对官僚贵族子弟和有财势者的称呼。", "cites": [{"t": "秀者,元时称人以郎、官、秀为等第,至今人之鄙人曰:“不郎不秀”,是言“不高不下”也。", "b": "明·田艺蘅《留青日札摘抄》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('766wx','私','1','sī','禾','7','','[{"pinyin": "sī", "defs": [{"meaning": "(形声。从禾,厶(sī)声。本义:禾;庄稼)。"}, {"meaning": "同本义。", "cites": [{"t": "私,禾也。北道名禾主人曰私主人。", "b": "《说文》。段玉裁注:“盖禾有名私者也。”"}]}, {"meaning": "中国古时女子称姊妹之夫为私。", "cites": [{"t": "谭公维私。", "b": "《诗·卫风·硕人》。孔颖达疏引孙炎曰:“私,无正亲之言。”"}]}, {"meaning": "男女阴部。", "cites": [{"t": "早有私病,不近妇人。", "b": "汉·伶玄《赵飞燕外传》"}], "words": [{"w": "私病;私处", "t": "生殖器。"}]}, {"meaning": "日常衣服。", "cites": [{"t": "薄污我私。", "b": "《诗·周南·葛覃》"}], "words": [{"w": "私衣", "t": "官吏日常的便衣。"}]}, {"meaning": "古指私田。", "cites": [{"t": "雨我公田,遂及我私。", "b": "《诗·小雅·大田》"}, {"t": "骏发尔私,终三十里。", "b": "《诗·周颂·噫嘻》"}]}, {"meaning": "古代卿大夫的家臣。", "cites": [{"t": "某也,夫子之贱私。", "b": "《仪礼》"}]}, {"meaning": "又指诸侯国君的嬖臣妾媵。", "cites": [{"t": "君多私。", "b": "《国语》"}], "words": [{"w": "蓄私", "t": ""}]}, {"meaning": "假借为“厶”。私人的;自己的。与“公”相对。", "cites": [{"t": "汉之为汉,几四十年矣,公私之积,犹可哀痛。", "b": "汉·贾谊《论积贮疏》"}, {"t": "丹不忍以乇之私,而伤长者之意,愿足下更虑之。", "b": "《战国策·燕策》"}, {"t": "兼覆无遗谓之公,反公为私。", "b": "《贾子道术》"}, {"t": "私者,下之所以侵法乱主也。", "b": "《管子·任法》"}, {"t": "皇天无私阿兮。", "b": "《离骚》"}, {"t": "寡君君之私也。", "b": "《仪礼·燕礼》。注:“谓独受恩厚也。”"}, {"t": "大夫有私丧。", "b": "《礼记·杂记》。注:“妻女子之丧也。”"}, {"t": "不以私邑累公邑也。", "b": "《公羊传·昭公五年》"}], "words": [{"w": "私宴", "t": "私人的宴乐;举行家宴"}, {"w": "私衙", "t": "官吏的私第"}, {"w": "私憾", "t": "私人之间的怨恨"}, {"w": "私淑", "t": "对自己没有从学的前辈的敬仰"}, {"w": "私力", "t": "私人的权力"}, {"w": "私田", "t": "私人所有的田地"}, {"w": "私地", "t": "私人的土地或地区"}, {"w": "私邑", "t": "封邑。私人的领地"}, {"w": "私兵", "t": "私人拥有的士兵"}, {"w": "私客", "t": "私人的门客"}, {"w": "私奴", "t": "旧时私家蓄养以供役使的奴仆。"}]}, {"meaning": "秘密的;不公开的。", "cites": [{"t": "项王乃疑范增与汉有私,稍夺之权。", "b": "《史记·项羽本纪》"}, {"t": "七月七日长生殿,夜半无人私语时。", "b": "唐·白居易《长恨歌》"}], "words": [{"w": "私款", "t": "私下聚会并招待"}, {"w": "私倒", "t": "秘密买进卖出"}, {"w": "私习", "t": "秘密学习"}, {"w": "私盟", "t": "秘密结盟"}, {"w": "私瘗", "t": "私下掩埋"}, {"w": "私门", "t": "暗娼"}, {"w": "私休", "t": "私下了结"}, {"w": "私肥", "t": "贪污中饱"}, {"w": "私房关目", "t": "夫妻之间的秘密事情,隐私"}, {"w": "私房走野", "t": "乱搞男女关系"}, {"w": "私盐包儿", "t": "比喻麻烦事儿。过去私人贩盐是犯法的,故称"}, {"w": "私盐私醋", "t": "比喻不能公开的事"}, {"w": "私肚子", "t": "私孕"}, {"w": "私路", "t": "不为人知的小路"}, {"w": "私慝", "t": "关系暧昧"}, {"w": "私面", "t": "私下会面"}, {"w": "私赏", "t": "私下赏赐。"}]}, {"meaning": "邪,不正。", "cites": [{"t": "若虽知之,奚道知其不为私?", "b": "《吕氏春秋》"}]}, {"meaning": "小。", "cites": [{"t": "私,小也。自关而西,秦晋之郊,梁益之间,凡物小者谓之私。", "b": "《方言》"}]}, {"meaning": "非法的。", "cites": [{"t": "敢私铸铁器煮盐者,釱左趾,没入其器物。", "b": "《史记·平准书》"}], "words": [{"w": "私刑;私盐", "t": ""}]}, {"meaning": "通奸。", "cites": [{"t": "臣邻家有远为吏者,其妻私人。", "b": "《战国策·燕策》"}], "words": [{"w": "私奸", "t": "私自搞不正当的男女关系"}, {"w": "私夫", "t": "姘夫。"}]}, {"meaning": "排尿;小便。", "cites": [{"t": "师慧过宋朝,交私焉。", "b": "《左传·襄公十五年》"}], "words": [{"w": "私起", "t": "夜晚起床小便。"}]}, {"meaning": "偏爱。", "cites": [{"t": "吾妻之美我者,私我也。", "b": "《战国策·齐策》"}, {"t": "岂天地之大,于兆人万姓之中,独私其一人一姓乎?", "b": "清·黄宗羲《原君》"}], "words": [{"w": "私称", "t": "偏爱的称谓"}, {"w": "私溺", "t": "偏爱"}, {"w": "私爱", "t": "偏爱;指私自宠爱的人"}, {"w": "私厚", "t": "偏爱厚待"}, {"w": "私阿", "t": "偏爱;曲意庇护"}, {"w": "私幸", "t": "指受到帝王宠爱的臣子"}, {"w": "私昵", "t": "指所亲近宠爱的人"}, {"w": "私我", "t": "偏爱我。"}]}, {"meaning": "贪爱,求多。", "cites": [{"t": "王虽有万金,弗得私也。", "b": "《战国策》"}]}, {"meaning": "占有。", "cites": [{"t": "平生负国谴,骸骨非敢私。", "b": "柳宗元《哭连州凌员外司马》"}]}, {"meaning": "用财物买通,贿赂。", "cites": [{"t": "门者故不入,则甘言媚词,作妇人状,袖金以私之。", "b": "明·宗臣《报刘一丈书》"}]}, {"meaning": "私下,偷偷地。", "cites": [{"t": "荆轲之太子不忍,乃遂私见樊於期。", "b": "《战国策·燕策》"}, {"t": "臣尝从大王与燕王会境上,燕王私握臣手曰,“愿结友”,以此知之。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "私分", "t": "私自分配"}, {"w": "私布", "t": "私自陈述"}, {"w": "私市", "t": "私自买进"}, {"w": "私充", "t": "私自冒充顶替"}, {"w": "私巡", "t": "指天子私自巡游"}, {"w": "私求", "t": "私自有所要求"}, {"w": "私见", "t": "私自谒见"}, {"w": "私伺", "t": "私自探望"}, {"w": "私私", "t": "私自地;暗暗地"}, {"w": "私庇", "t": "暗中庇护"}, {"w": "私地", "t": "暗中;背地里"}, {"w": "私意儿", "t": "背地里,有意地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('767wx','每','1','měi','母','7','','[{"pinyin": "měi", "defs": [{"meaning": "(形声。小篆字形,从屮(chè),母声。屮,草木初生。一说“每”为“母”的异体字。本义:草旺盛生长) 同本义。", "cites": [{"t": "每,草盛上出也。", "b": "《说文》"}, {"t": "舆人诵曰:原田每每。", "b": "《左传·僖公二十八年》。杜注:“晋军美盛,若原田之草每每然。”"}]}, {"meaning": "常常,经常。", "cites": [{"t": "妪每次谓余曰。", "b": "明·归有光《项脊轩志》"}, {"t": "每大言曰。", "b": "·宗臣《宗子相先生集·报刘一丈书》"}], "words": [{"w": "每常间", "t": "往日,平常"}, {"w": "春秋佳日,每作郊游", "t": ""}]}, {"meaning": "每一次。", "cites": [{"t": "相如每朝。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "每与臣论。", "b": "诸葛亮《出师表》"}, {"t": "每得降卒。", "b": "《资治通鉴·唐纪》"}, {"t": "每冒风驰行。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "他每到学校,总要来看我;月刊每逢15出版", "t": ""}]}, {"meaning": "各个。", "cites": [{"t": "每韵为一帖,木格贮之(意思是,把字按韵分类,分别放在木格里)。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "每字为一印。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "每一巨弹。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "每字有二十余印;每天;每一分钱;每星期五", "t": ""}]}, {"meaning": "用在人称代词或名词后,表示复数。", "cites": [{"t": "我每且去寻房子,再来会这些人。", "b": "《儒林外史》"}], "words": [{"w": "窗隔每", "t": "指多扇窗隔"}, {"w": "桌椅每", "t": "很多桌椅"}, {"w": "他每", "t": "他们。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('768wx','兵','1','bīng','八','7','','[{"pinyin": "bīng", "defs": [{"meaning": "(会意。从廾,从斤。甲骨文字形,上面是“斤”,是短斧之类;下面是“廾”(gǒng,双手),象双手持斤。本义:兵器,武器)。"}, {"meaning": "同本义。", "cites": [{"t": "兵,械也。", "b": "《说文》"}, {"t": "掌五兵。", "b": "《周礼·司兵》。司农注:“戈、殳、戟、酋矛、夷矛也。”"}, {"t": "陈五兵。", "b": "《谷梁传·庄公二十五年》。注:“矛、戟、钺、楯、弓矢也。”"}, {"t": "谓五方之兵,东矛、南弩、西戈、北铩、中央剑也。”", "b": "《匡谬正俗》"}, {"t": "离为戈兵。", "b": "《易·说卦》"}, {"t": "修尔车马,弓矢戎兵。", "b": "《诗·大雅·抑》"}, {"t": "古之兵,戈、矛、弓、矢而已矣。", "b": "《荀子·议兵》"}, {"t": "兵刃既接,弃甲曳兵而走。", "b": "《孟子·梁惠王上》"}, {"t": "兵者,凶器也。", "b": "《国语·越语》"}, {"t": "兵者,不祥之器。", "b": "《老子》"}, {"t": "兵者,国之爪也。", "b": "《墨子·七患》"}, {"t": "收天下之兵,聚之咸阳。", "b": "汉·贾谊《过秦论》"}, {"t": "郑穆公使视客馆,则束载、厉兵、秣马矣。", "b": "《左传·僖公三十三年》"}, {"t": "乃令骑皆下马步行,持短兵接战。", "b": "《史记·项羽本纪》"}], "words": [{"w": "短兵相接;兵不血刃;动刀兵;坚甲利兵;兵革", "t": "兵器甲胄的总称。引申指战争"}, {"w": "兵解", "t": "古代方士以为学道者死于兵刃,供兵刃解脱躯壳以成仙,称为兵解"}, {"w": "兵戈", "t": "干戈。借以指战争。"}]}, {"meaning": "士兵的群体,即整个军队。", "cites": [{"t": "越人之兵虽多,亦奚益於胜败哉?", "b": "《列子·虚实》"}, {"t": "必以长安君为质,兵乃出。", "b": "《战国策·赵策四》"}, {"t": "举兵伐徐,遂灭之。", "b": "《韩非子·五蠹》"}, {"t": "赵亦盛设兵待秦,秦不敢动。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "赵兵果败。", "b": "汉·刘向《列女传》"}], "words": [{"w": "兵柄", "t": "军权"}, {"w": "兵备道", "t": "明代的官名。分巡道的首长,兼管军务,负责管区内的治安"}, {"w": "兵房", "t": "县衙中六房之一,掌兵事"}, {"w": "兵马制置", "t": "即制置使。唐大中五年始置,负责边防军务。宋初不常设,后为对金作战,设置渐多。"}]}, {"meaning": "士卒。", "cites": [{"t": "悉使羸兵负草填之,骑乃得过。", "b": "《资治通鉴》"}, {"t": "瑜得精兵五万。", "b": "《资治通鉴》"}, {"t": "又望八公山上草木,皆以为晋兵。", "b": "《资治通鉴》"}], "words": [{"w": "雄兵百万;草木皆兵;当兵;兵来将敌水来土堰", "t": "不管对方使用何种策略,都自有对付的办法。"}]}, {"meaning": "军事;武力;战争。", "cites": [{"t": "兵者,国之大事。", "b": "《孙子兵法·计篇》"}, {"t": "夫兵,犹火也。", "b": "《左传·隐公四年》"}, {"t": "故谋用是作,而兵由此起。", "b": "《礼记·礼运》"}], "words": [{"w": "兵交", "t": "交战"}, {"w": "兵端", "t": "战争的发端"}, {"w": "兵燹", "t": "因战火引起的焚烧毁坏"}, {"w": "兵栏", "t": "军营周围的栅栏"}, {"w": "兵纪", "t": "军事要事"}, {"w": "兵冲", "t": "军事要冲。"}]}, {"meaning": "用兵策略,战略。", "cites": [{"t": "故士兵伐谋,其次伐交。", "b": "《孙子·谋攻》"}, {"t": "故兵无常势。", "b": "《孙子·虚实》"}]}, {"meaning": "牌戏名。"}, {"meaning": "国际象棋16个棋子中价值最小的棋子。"}, {"meaning": "中国象棋中红方的价值最小的五个棋子之一——蓝方相应的为“卒”。"}, {"meaning": "用兵器攻击,刺杀。", "cites": [{"t": "左右欲兵之。", "b": "《史记·伯夷列传》"}], "words": [{"w": "兵诛", "t": "用兵器诛杀。"}]}, {"meaning": "伤害。", "cites": [{"t": "反以自兵。", "b": "《吕氏春秋·侈乐》"}], "words": [{"w": "兵荒", "t": "战争造成的饥荒及其他灾祸"}, {"w": "兵寇", "t": "乱兵或乱兵的侵扰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('769wx','估','1','gū gù','亻','7','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从人,古声。本义:物价)。"}, {"meaning": "同本义。", "cites": [{"t": "乃高盐直,贱帛估。", "b": "《新唐书·陆长源传》"}]}, {"meaning": "商人。", "cites": [{"t": "莫复临时不寄人,漫道江中无估客。", "b": "《玉台新咏·梁元帝·别诗》"}], "words": [{"w": "估人", "t": "商人。"}]}, {"meaning": "市场税。", "cites": [{"t": "估税悉除,市无二价。", "b": "《晋书·甘卓传》"}], "words": [{"w": "估税", "t": "古代的一种市场税。"}]}, {"meaning": "用同“鼓”。凸起;涨大。", "cites": [{"t": "卫先生估着眼道:“前科没有文章。”", "b": "《儒林外史》"}]}]}, {"pinyin": "gù", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('770wx','体','1','tǐ tī','亻','7','','[{"pinyin": "tǐ", "defs": [{"meaning": "(体,会意。从人,从本。古代“体、軆”是两个字,“体”是“劣”,又指粗笨。身体本字是“軆”,形声。从骨,豊(lǐ)声。今简化为“体”。本义:身体)。"}, {"meaning": "同本义。", "cites": [{"t": "体,总十二属之名也。", "b": "《说文》。按,十二属者:顶、面、颐,首属三;肩、脊、臀,身属三;肱、臂、手,手属三;股、胫、足,足属三也。"}, {"t": "体,身也。", "b": "《广雅》"}, {"t": "饿其体肤,空乏其身。", "b": "《孟子·告子下》"}, {"t": "居五日,桓侯体痛。", "b": "《韩非子·喻老》"}, {"t": "体有不快。", "b": "《后汉书·华佗传》"}, {"t": "伤乎体。", "b": "《韩非子·五蠹》"}, {"t": "口体之奉。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "体态轻盈", "t": "形容女子婀娜多姿"}, {"w": "上体;下体;体高五尺;体大身强;肉体", "t": "人的身体,区别于“精神”"}, {"w": "体骸", "t": "躯壳;尸骸"}, {"w": "体候", "t": "身体状况"}, {"w": "体素", "t": "敬词。玉体"}, {"w": "体段", "t": "身段。"}]}, {"meaning": "手脚、四肢。", "cites": [{"t": "轻暖不足于体。", "b": "《孟子·梁惠王上》"}, {"t": "犹其有四体也。谓二手二足。", "b": "《孟子》"}], "words": [{"w": "四体", "t": "人的四肢"}, {"w": "五体投地", "t": ""}]}, {"meaning": "形体 ;体态。", "cites": [{"t": "可怜体无比。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "体段", "t": "样子;身分"}, {"w": "体相", "t": "形体相貌"}, {"w": "长方体;立方体;几何体;正方体;角柱体;圆柱体;刚体;磁体;黑体;发光体;导体;晶体", "t": ""}]}, {"meaning": "牲体。", "cites": [{"t": "辨体名肉物。", "b": "《周礼·内飨》。按,牲体有七脊也,左右肋也,左右肱也,左右股也,所谓全軆也。"}], "words": [{"w": "体解", "t": "古代祭祀时将牲体切割成二十一块"}, {"w": "体节", "t": "带骨的大块牛羊肉。"}]}, {"meaning": "事物的主要部分。", "cites": [{"t": "以天演为体。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "体用", "t": "事物的本体与作用"}, {"w": "体物", "t": "体现于万事万物之中"}, {"w": "体例", "t": "制度的纲领和细则"}, {"w": "体要", "t": "大体与纲要。"}]}, {"meaning": "实体。", "cites": [{"t": "天之与地,皆体也。", "b": "王充《论衡》"}]}, {"meaning": "规格;法式。", "cites": [{"t": "直求输赤诚,所望大体全。", "b": "唐·李商隐《行次西郊作一百韵》"}], "words": [{"w": "体式", "t": "法式,格式"}, {"w": "体法", "t": "指书法的格局法式"}, {"w": "体段", "t": "体格、结构"}, {"w": "体气", "t": "诗文的气质格调;人品性格"}, {"w": "体统", "t": "规矩,制度;诗文或著作中的体裁和条理。"}]}, {"meaning": "占卜时的兆象。", "cites": [{"t": "尔卜尔筮,体无咎言。", "b": "《诗·卫风·氓》"}]}, {"meaning": "又如;体象(象征)。"}, {"meaning": "本性,本质 。", "words": [{"w": "体识", "t": "禀性和器识"}, {"w": "体器", "t": "禀性和器度"}, {"w": "体履", "t": "禀性和行为。"}]}, {"meaning": "准则。", "cites": [{"t": "平居妄自尊大而临事不知体,此俗人也。", "b": "宋·陈善《扪虱新话》"}]}, {"meaning": "文体 。", "words": [{"w": "古体诗;近体诗;散体;骈体", "t": ""}]}, {"meaning": "体制。", "cites": [{"t": "自汉至魏,四百余年,辞人才子,文体三变。", "b": "沈约《谢灵运传论》"}]}, {"meaning": "又如:政体;国体。"}, {"meaning": "动词的一套屈折形式、表示动作的性质或关于该动作的开始、持续、完成或重复等方面的情况,但不涉及该动作发生的时间——最初用于斯拉夫语言,后来用于其他语言 。"}, {"meaning": "如:完成体;进行体。"}, {"meaning": "文字的书写形式 。"}, {"meaning": "如:草体;楷体;宋体;字体;印刷体。"}, {"meaning": "立体。", "cites": [{"t": "后见为体。", "b": "蔡元培《图画》"}, {"t": "体面互见。", "b": ""}, {"t": "舍体而取面。", "b": ""}, {"t": "体之感觉。", "b": ""}]}, {"meaning": "亲身经验;体察。", "cites": [{"t": "汝体吾此心。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "体物", "t": "描绘事物"}, {"w": "体信", "t": "守信;信服"}, {"w": "体行", "t": "躬亲践行"}, {"w": "体认", "t": "体察认识"}, {"w": "体测", "t": "体察忖测。"}]}, {"meaning": "设身处地为人着想 。", "words": [{"w": "体国", "t": "关心国家"}, {"w": "体悉", "t": "体谅了解。"}]}, {"meaning": "划分,分解。", "cites": [{"t": "体其犬豕牛羊。", "b": "《礼记》"}], "words": [{"w": "体解", "t": "分解牲畜的肢体;古代酷刑之一;肢体解离"}, {"w": "体国经野", "t": "区画都城,丈量土地;泛指治理国家。"}]}, {"meaning": "成形。", "cites": [{"t": "敦彼行苇,牛羊勿践履,方苞方体,维叶泥泥。", "b": "《诗·大雅·行苇》"}]}, {"meaning": "表现;体现。", "cites": [{"t": "阴阳合德,而刚柔有体,以体天地之撰。", "b": "《易·系辞上》"}]}, {"meaning": "效法。", "cites": [{"t": "帝者体太一。", "b": "《淮南子》"}]}, {"meaning": "相承;继承。", "cites": [{"t": "正体于上,又乃将所传重也。", "b": "《仪礼》"}]}, {"meaning": "生长。", "cites": [{"t": "体物而不可遗。", "b": "《礼记》"}]}, {"meaning": "包含;容纳。", "cites": [{"t": "君子体人,足以长人。", "b": "《易·乾》"}]}, {"meaning": "体验;实行。", "cites": [{"t": "尔卜尔筮,体无咎言。", "b": "《诗·卫风·氓》。《释文》云:韩诗作履。履,幸也。"}, {"t": "能戴大圆者,体平大方。", "b": "《管子·心术下》"}, {"t": "体恭敬而心忠信,术礼义而情爱人。", "b": "《荀子·修身》"}, {"t": "笃志而体,君子也。", "b": ""}], "words": [{"w": "体乾", "t": "履行天命。"}]}]}, {"pinyin": "tī", "defs": [{"meaning": "亲近的,贴心的。"}, {"meaning": "家庭成员个人积蓄的(指财物)。"}, {"meaning": "私下里。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('771wx','何','1','hé hè','亻','7','','[{"pinyin": "hé", "defs": [{"meaning": "什么。", "cites": [{"t": "何节奄忽,蹄足洒血?", "b": "《文选·宋玉·高唐赋》。注:“何,问辞也。”"}, {"t": "何调翰之乔桀?", "b": "《文选·潘岳·射雉赋》。注:“何,疑问之辞也。”"}, {"t": "何以自绘。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "子何恃而往?", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "何异断斯织。", "b": "《后汉书·列女传》"}], "words": [{"w": "何人;何物;有何困难;何干", "t": "有什么相干。"}]}, {"meaning": "怎么样。", "cites": [{"t": "如太行王屋何。", "b": "《列子·汤问》"}, {"t": "如土石何。", "b": ""}, {"t": "问女何所思。", "b": "《乐府诗集·木兰诗》"}, {"t": "得钱何所营。", "b": "唐·白居易《卖炭翁》"}, {"t": "何苦而不平。", "b": "《列子·汤问》"}, {"t": "何不以锯中。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "何忧令名不彰。", "b": "《世说新语·自新》"}, {"t": "羌笛何须怨杨柳。", "b": "唐·王之涣《凉州词》诗"}], "words": [{"w": "何居", "t": "何故"}, {"w": "何者", "t": "为什么"}, {"w": "何意", "t": "为什么,何故"}, {"w": "何缘", "t": "为什么。"}]}, {"meaning": "哪里,什么地方。", "cites": [{"t": "笑问客从何处来。", "b": "唐·贺知章《回乡偶书》"}, {"t": "何处得秋霜。", "b": "唐·李白《秋浦歌》"}], "words": [{"w": "何往;此行何去?;何从", "t": "哪里"}, {"w": "何止", "t": "哪里止,不止。"}]}, {"meaning": "谁。", "cites": [{"t": "何事非君,何使非民。", "b": "《孟子·万章下》"}, {"t": "不知何氏之女。", "b": "《后汉书·列女传》"}]}, {"meaning": "哪样,哪点。", "cites": [{"t": "何有于我哉?(哪一样我能有呢?这是孔子自谦的话。)", "b": "《论语》"}]}, {"meaning": "问,盘问,诘问。", "cites": [{"t": "陈列兵而谁何。", "b": "《史记·秦皇纪》"}], "words": [{"w": "谁何", "t": "盘问是谁。"}]}, {"meaning": "谴责;呵斥。", "cites": [{"t": "何,与诃通。", "b": "《正字通》"}, {"t": "又下令不何止夜行;使民自便,境内以安。", "b": "《新唐书》"}, {"t": "良将精弩寄要害之处,信臣精卒,陈利兵而谁何,天下以定。", "b": "《史记·秦始皇本纪》"}, {"t": "故其在大谴大何之域者,闻谴何则自冠氂缨。", "b": "《汉书·贾谊传》"}]}, {"meaning": "甚;多么。", "cites": [{"t": "秦王扫六合,虎视何雄哉!", "b": "唐·李白《古风》"}, {"t": "水何澹澹。", "b": "曹操《步出夏门行》"}]}, {"meaning": "句中语气词,相当于“啊”。", "cites": [{"t": "隐隐何甸甸。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}, {"pinyin": "hè", "defs": [{"meaning": "(形声。从人,可声。金文,象人负担之形。本义:负荷) 同本义", "cites": [{"t": "何校灭耳,凶。", "b": "《易·噬嗑》"}, {"t": "何天之衢。", "b": "《易·大畜》"}, {"t": "殷受命咸宜,百禄是何。", "b": "《诗·商颂·玄鸟》"}, {"t": "何天之休,不競不絿。", "b": "《诗·商倾·长发》"}, {"t": "用此五子者何功。", "b": "《管子·小匡》"}], "words": [{"w": "何校", "t": "戴枷"}, {"w": "何劳", "t": "承受烦劳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('772wx','佐','1','zuǒ','亻','7','','[{"pinyin": "zuǒ", "defs": [{"meaning": "(本作左。形声。从人,左声。本义:辅助,帮助)。"}, {"meaning": "同本义(古人以“右”为尊,“左”为卑。“佐”常用于下对上、弱对强的帮助。上对下,强对弱时用“佑”)。", "cites": [{"t": "佐,助也。", "b": "《广雅》"}, {"t": "故周公旦佐相天子。", "b": "《墨子·贵义》"}, {"t": "陈胜佐之。", "b": "《史记·陈涉世家》"}, {"t": "太宰之职,常建邦之六典,以佐王治邦国。", "b": "《周礼·天官》"}, {"t": "四岳佐之。", "b": "《国语·周语下》"}, {"t": "予佐尔贾。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "佐以科学。", "b": "蔡元培《图画》"}, {"t": "佐读勤苦。", "b": "清·周容《芋老人传》"}], "words": [{"w": "佐理", "t": "助理,帮助处理"}, {"w": "佐事", "t": "辅助事奉"}, {"w": "佐戎", "t": "参与军事"}, {"w": "佐相", "t": "辅助"}, {"w": "佐佑", "t": "辅助;支持"}, {"w": "佐检", "t": "辅助"}, {"w": "佐州", "t": "辅佐州政"}, {"w": "佐谋", "t": "辅助筹划"}, {"w": "佐治", "t": "辅佐治理。"}]}, {"meaning": "劝。", "cites": [{"t": "召之,使佐食,比已食,三叹。", "b": "《国语·晋语》。韦昭注:“佐,犹劝也。”"}], "words": [{"w": "佐觞", "t": "劝酒。"}]}, {"meaning": "处于辅助地位的官员,僚属。", "cites": [{"t": "有赵孟以为大夫,有伯瑕以为佐。", "b": "《左传》"}], "words": [{"w": "佐杂", "t": "地方官署的辅佐官员"}, {"w": "佐吏", "t": "汉时辅佐地方政事的小官"}, {"w": "佐将", "t": "太平天国前期对军中带兵官和地方行政名的通称。"}]}, {"meaning": "副,第二位。", "cites": [{"t": "掌佐车之政。", "b": "《周礼·田仆》"}, {"t": "郑周父御佐车。", "b": "《左传·成公二年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('773wx','佑','1','yòu','亻','7','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从人,右声。字本作“右”。表右助。因“右”用为左右之“右”,又造“佑”字表示本义。本义:保护;右助)。"}, {"meaning": "同本义。", "cites": [{"t": "天佑下民,作之君,作之师。", "b": "《书·泰誓上》"}, {"t": "天命反侧,何罚何佑?", "b": "《楚辞》"}], "words": [{"w": "保佑", "t": "迷信的人称神力保护和帮助"}, {"w": "佑助", "t": "保佑扶助;庇护。"}]}, {"meaning": "辅助;帮助。", "cites": [{"t": "佑,助也。", "b": "《玉篇》"}]}, {"meaning": "《说文》无“佑”字。徐铉在“右”字下注云:“今俗别作佑。”按:又、右、佑当为一字分化。", "cites": [{"t": "高祖为亭长,常佑之。", "b": "《汉书》"}], "words": [{"w": "佑庇", "t": "帮助;保护。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('774wx','但','1','dàn','亻','7','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从人,旦声。①本义:脱去上衣,露出身体的一部分。经传皆以袒为之。②只,仅,不过)。"}, {"meaning": "表示范围,相当于“只”,“仅”。", "cites": [{"t": "但闻黄河流水鸣溅溅。", "b": "《乐府诗集·木兰诗》"}, {"t": "天下所以贵者,但以闻声。", "b": "《史记·李斯传》"}], "words": [{"w": "但已", "t": "仅此而已"}, {"w": "但凭", "t": "任凭;随便"}, {"w": "但可", "t": "只须。"}]}, {"meaning": "只管,尽管。", "cites": [{"t": "此系私室,但坐不妨。", "b": "《红楼梦》"}]}, {"meaning": "只是;但是——表示转折。", "cites": [{"t": "公干有逸气,但未遒耳。", "b": "曹丕《与吴质书》"}], "words": [{"w": "勤锻炼但不要过分", "t": ""}]}, {"meaning": "只要——表示假设或条件。", "cites": [{"t": "但使龙城飞将在,不教胡马度阴山。", "b": "唐·王昌龄《出塞二首》"}, {"t": "但出牌呼妾,妾便出来。", "b": "《警世通言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('775wx','伸','1','shēn','亻','7','','[{"pinyin": "shēn", "defs": [{"meaning": "(本作“申”。形声。从人,申声。本义:伸直,伸展)。"}, {"meaning": "同本义。", "cites": [{"t": "伸,不屈也。", "b": "《说文》"}, {"t": "伸,展也。", "b": "《广雅》"}, {"t": "引而伸之。", "b": "《易·系辞上》"}, {"t": "君子欠伸。", "b": "《仪礼·士相见礼》。注:“志倦则见,体倦则伸。”"}, {"t": "熊经鸟伸。", "b": "《淮南子·精神》。注:“频伸也。”"}, {"t": "便有妇人惊觉欠伸,其夫呓语。", "b": "《虞初新志·秋声诗自序》"}, {"t": "手指不可屈伸。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "伸吭", "t": "伸长脖子"}, {"w": "伸舒", "t": "伸展;舒展"}, {"w": "伸不得手", "t": "插不上手;施展不开手段"}, {"w": "伸长倘脚", "t": "方言。伸脚舒腿躺着"}, {"w": "伸卷", "t": "将卷轴卷起和展开"}, {"w": "伸屈", "t": "伸直与屈曲"}, {"w": "伸歇", "t": "舒展肢体休息。"}]}, {"meaning": "申理;洗雪。", "cites": [{"t": "小事尚不伸,况大事乎?", "b": "《宋史·韩绛传》"}], "words": [{"w": "伸雪", "t": "诉说冤情以求昭雪"}, {"w": "伸诉", "t": "向上级官员说明情由。"}]}, {"meaning": "陈述,表白。", "cites": [{"t": "第为上者不能察,使匹夫攘袂群起以伸其愤。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "伸问", "t": "亦作“申问”。查问,询问"}, {"w": "伸诉", "t": "详细说明"}, {"w": "伸覆", "t": "陈说禀告。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('776wx','佃','1','diàn tián','亻','7','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从人,田声。“田”又兼表字义。①(tián)本义:耕种土地 ②引申义:租种田地)。"}, {"meaning": "畋猎,猎取禽兽。", "cites": [{"t": "作结绳而为罔罟,以佃以渔,盖取诸离。", "b": "《易·系辞下》"}, {"t": "则又成王之所佃。", "b": "《诗·小雅·信南山》笺"}, {"t": "今观宰司之取士也,有似于司原之佃也。", "b": "《潜夫论·贤难》"}]}]}, {"pinyin": "tián", "defs": [{"meaning": "(形声。从人,田声。本义:耕作)。"}, {"meaning": "同本义。", "cites": [{"t": "畇畇原隰,曾孙田之。", "b": "《诗·小雅·信南山》"}, {"t": "即上言方佃作诗。", "b": "《汉书·韩安国传》"}], "words": [{"w": "佃作", "t": "从事耕作"}, {"w": "佃具", "t": "耕具,农具"}, {"w": "佃器", "t": "农具。"}]}, {"meaning": "打猎。", "cites": [{"t": "以佃以渔。", "b": "《易·系辞下》"}, {"t": "齐侯至自佃。", "b": "《左传·昭公二十年》"}], "words": [{"w": "佃渔", "t": "猎兽和捕鱼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('777wx','作','1','zuō zuò','亻','7','','[{"pinyin": "zuō", "defs": [{"meaning": "作坊,手工业工场。", "cites": [{"t": "明帝方修宫室而节气不合,…而礼径至所作,不复重奏,称诏罢民。", "b": "《三国志·魏志》"}], "words": [{"w": "作房", "t": "作坊"}, {"w": "作分", "t": "作坊"}, {"w": "木工作;油漆作;洗衣作", "t": ""}]}]}, {"pinyin": "zuò", "defs": [{"meaning": "(会意。从人,从乍。人突然站起为作。甲骨文字形,象衣领初作的形状。本义:人起身)。"}, {"meaning": "同本义。", "cites": [{"t": "作,起也。", "b": "《说文》"}, {"t": "明两作。", "b": "《易·离》"}, {"t": "作其即位。", "b": "《书·无逸》"}, {"t": "与子偕作。", "b": "《诗·秦风·无衣》"}, {"t": "或作而行之。", "b": "《考工记》"}, {"t": "凡作民。", "b": "《周礼·士师》"}, {"t": "三献作止爵。", "b": "《仪礼·特牲礼》"}, {"t": "后圣有作。", "b": "《礼记·礼运》"}, {"t": "而后作焉。", "b": "《左传·襄公二十三年》"}, {"t": "舍瑟而作。", "b": "《论语·先进》"}, {"t": "客作而辞。", "b": "《礼记·少仪》"}, {"t": "如日出时,眠者皆作。", "b": "宋·苏轼《画佛赞》"}, {"t": "有洪洞令杜君者,作而言曰。", "b": "方苞《狱中杂记》"}], "words": [{"w": "作止", "t": "作息;起居。"}]}, {"meaning": "起来;开始工作。", "cites": [{"t": "日出而作,日入而息。", "b": "《乐府诗集》"}, {"t": "蚤作而夜思。", "b": "唐·柳宗元《送董邵南序》"}, {"t": "往来种作。", "b": "晋·陶渊明《桃花源记》"}, {"t": "田家秋作苦,邻女夜春寒。", "b": "唐·李白《宿五松山下荀媪家》"}], "words": [{"w": "作力", "t": "出力;使力"}, {"w": "作本", "t": "务农"}, {"w": "作苦", "t": "耕作辛苦"}, {"w": "作一", "t": "劳动专一"}, {"w": "作牧", "t": "畜牧,放牧"}, {"w": "作剧", "t": "劳作勤苦"}, {"w": "作劳", "t": "劳作,劳动"}, {"w": "作甚", "t": "做什么。"}]}, {"meaning": "产生,兴起。", "cites": [{"t": "包牺氏没,神农氏作。", "b": "《易·系辞下》"}, {"t": "周秦之际,诸子并作。", "b": "《论衡》"}, {"t": "由汤至于武丁,贤圣之君六七作。", "b": "《孟子·公孙丑下》"}, {"t": "且王者之不作,未有疏于此时者也。", "b": ""}, {"t": "天油然作云。", "b": "《孟子》"}, {"t": "坚冰作于履霜,寻木起于蘖栽。", "b": "汉·张衡《东京赋》"}, {"t": "浓雾半作半止。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "作兴", "t": "兴起"}, {"w": "作师", "t": "兴兴"}, {"w": "作病", "t": "发生疾病,致病"}, {"w": "作见", "t": "出现;显现"}, {"w": "作逆", "t": "作乱,造反"}, {"w": "作贼", "t": "造反"}, {"w": "作缘", "t": "发生瓜葛、联系。"}]}, {"meaning": "做;创制;制作;从事某种活动。", "cites": [{"t": "始作俑者,其无后乎?", "b": "《孟子·梁惠王上》"}, {"t": "遂乃研核阴阳,妙尽璇机之正,作浑天仪。", "b": "《后汉书·张衡传》"}, {"t": "作结绳而为罔罟。", "b": "《易·系辞下》"}, {"t": "为楚王作剑。", "b": "晋·干宝《搜神记》"}, {"t": "吾为楚王作剑。", "b": ""}, {"t": "汝父为楚王作剑。", "b": ""}, {"t": "作二铁板。", "b": "宋·沈括《梦溪笔谈·活板》"}]}, {"meaning": "写作,创作。", "cites": [{"t": "屈平之作《离骚》,盖自怨生也。", "b": "《史记·屈原列传》"}, {"t": "仲尼卮而作《春秋》。", "b": "汉·司马迁《报任安书》"}, {"t": "登高作赋,是所望于群公。", "b": "唐·王勃《滕王阁序》"}, {"t": "文章合为时而著,歌诗合为时而作", "b": "唐·白居易"}]}, {"meaning": "《与元九书》。", "cites": [{"t": "作敲字佳矣。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "自是指物作诗立就。", "b": "宋·王安石《伤仲永》"}, {"t": "令作诗。", "b": ""}, {"t": "属予作文以记之。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "作古作故", "t": "不依旧规,自创先例"}, {"w": "作述", "t": "创作传述。"}]}, {"meaning": "振作。", "cites": [{"t": "困于心,衡于虑,而后作。", "b": "《孟子·告子下》"}, {"t": "一鼓作气。", "b": "《左传·庄公十年》"}], "words": [{"w": "作气", "t": "振作勇气"}, {"w": "作强", "t": "产生强劲之力。"}]}, {"meaning": "充当。", "cites": [{"t": "人而无恒,不可以作巫医。", "b": "《论语》"}], "words": [{"w": "做冰", "t": "做媒人"}, {"w": "作霖", "t": "充作救旱之雨。后指降甘霖或下雨"}, {"w": "作小", "t": "做小。与人为妾"}, {"w": "作眼", "t": "做眼线"}, {"w": "作甘", "t": "做救旱甘霖。"}]}, {"meaning": "当作。", "cites": [{"t": "青春作伴好还乡。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "老大嫁作商人妇。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "有风既作飘飖之态。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "作傍", "t": "当作靠山;作依托"}, {"w": "作外", "t": "当作外文,见外"}, {"w": "作做", "t": "当作,算作。"}]}, {"meaning": "建筑。", "cites": [{"t": "将有作。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "作亭者谁。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "作邑", "t": "建筑都城"}, {"w": "作洛", "t": "另建新都"}, {"w": "作土", "t": "积土堆垒以御敌。"}]}, {"meaning": "发出音响,演奏。", "cites": [{"t": "乐将作。", "b": "宋·王谠《唐语林·雅量》"}]}, {"meaning": "又如:作倡(演奏音乐或表演歌舞);作健(成为强者。谓奋发称雄)。"}, {"meaning": "生出,长出来。", "cites": [{"t": "采薇采薇,薇亦作止。", "b": "《诗·小雅·采薇》"}]}, {"meaning": "又如:作花(长出花蕾;开花);作谷(田里生长着的谷物);作肉(方言。长肉)。"}, {"meaning": "培育,造就。", "cites": [{"t": "亦惟助宅天命,作新民。", "b": "《书·康诰》"}]}, {"meaning": "又如:作育(造就培养);作新(比喻教化百姓移风易俗);作养(培养,培育);作诲(教诲,训导)。"}, {"meaning": "担任。", "cites": [{"t": "伯禹作司空。", "b": "《书·舜典》"}]}, {"meaning": "又如:作县(当县官);作吏(担任官职);作宾(担任太子宾客职务);作游(谓游幕。指到各地做幕僚);作邑(当县令)。"}, {"meaning": "发生,发作。", "cites": [{"t": "冻风时作。", "b": "明·袁宏道《满井游记》"}, {"t": "作则飞沙走砾。", "b": ""}, {"t": "此疫作也。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "发出,放射。", "cites": [{"t": "泠泠作响。", "b": "吴均《与朱元思书》"}, {"t": "振奋作声。", "b": "《聊斋志异·促织》"}, {"t": "有作其芒。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "百千齐作。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "发动。", "cites": [{"t": "一夫作难而匕庙隳。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "像;似(唐宋时期出现的)。", "cites": [{"t": "马作的卢飞快,弓如霹雳弦惊。", "b": "宋·辛弃疾《破阵子·为陈同甫赋壮词以寄之》"}]}, {"meaning": "咒诅。", "cites": [{"t": "侯作侯祝。", "b": "《诗·大雅·荡》"}, {"t": "下作之地,上作之天。", "b": "《管子·轻重己》。俞樾云:“两作字读为诅,古字通用。”"}]}, {"meaning": "作品;文章。", "cites": [{"t": "临摹旧作。", "b": "蔡元培《图画》"}, {"t": "理想派之作。", "b": ""}], "words": [{"w": "遗作;译作;新作", "t": ""}]}, {"meaning": "事情,事业。", "cites": [{"t": "利用为大作。", "b": "《易·益》"}, {"t": "毋以小谋败大作。", "b": "《礼记·缁衣》"}]}, {"meaning": "措施;办法。", "cites": [{"t": "作有利于时,制有便于物者,可为也。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('778wx','伯','1','bà bǎi bó','亻','7','','[{"pinyin": "bà", "defs": [{"meaning": "原指春秋时诸侯的首领。", "cites": [{"t": "穆公任之,强配五伯、六卿施。(五伯,即五个盟主,五霸:齐桓公、晋文公、宋襄公、秦穆公、楚庄王。)", "b": "《荀子·成相》"}], "words": [{"w": "伯气", "t": "霸气。"}]}, {"meaning": "称霸。", "cites": [{"t": "一朝而伯。", "b": "《荀子·儒效》"}]}]}, {"pinyin": "bǎi", "defs": [{"meaning": "数目。十的十倍。", "cites": [{"t": "亡(无)农夫之苦,有仟伯之得。", "b": "《汉书·食货志上》"}], "words": [{"w": "仟伯", "t": "仟钱和百钱"}, {"w": "伯夫", "t": "百人。泛指多人。"}]}, {"meaning": "百倍", "cites": [{"t": "使有什伯之器而不用。", "b": "《老子》"}]}, {"meaning": "妇人对夫兄的称呼 。又称“伯子”、“伯叔”(妇人称丈夫的兄弟)。今北方方言称作“大伯子”。"}]}, {"pinyin": "bó", "defs": [{"meaning": "(形声。从人,白声。本义:排行第一的,老大)。"}, {"meaning": "同本义。", "cites": [{"t": "伯,长也。", "b": "《说文》"}, {"t": "问我诸姑,遂及伯姊。", "b": "《诗·邶风 ·泉水》"}, {"t": "侯主侯伯,侯亚侯旅。", "b": "《诗·周颂·载芟》"}, {"t": "曰伯某甫仲叔季,唯其所当。", "b": "《仪礼·士冠礼》"}, {"t": "五官之长曰伯。", "b": "《礼记·曲礼下》"}, {"t": "千里之外访方伯。", "b": "《礼记·王制》"}, {"t": "忆作儿童随伯氏,南来今只一身存。", "b": "韩愈《过始兴江口感怀》"}], "words": [{"w": "伯氏", "t": "长兄,哥哥"}, {"w": "伯兄", "t": "长兄"}, {"w": "伯氏", "t": "长兄"}, {"w": "伯歌季舞", "t": "比喻兄弟情感和好融洽"}, {"w": "伯姊", "t": "大姐。"}]}, {"meaning": "伯父。父亲的哥哥。", "cites": [{"t": "汝伯何由发如漆。", "b": "杜甫《醉歌行》"}], "words": [{"w": "伯舅", "t": "对母亲的哥哥的称呼;古时帝王对异姓诸侯的称呼"}, {"w": "伯叔", "t": "伯父叔父"}, {"w": "伯娘", "t": "伯父的妻子"}, {"w": "伯翁", "t": "父亲的伯父;丈夫的伯父"}, {"w": "伯姑", "t": "大姑母。"}]}, {"meaning": "对年龄较长的男子的尊称。", "cites": [{"t": "将伯助予。", "b": "《诗·小雅·正月》"}]}, {"meaning": "女子对丈夫的尊称。", "cites": [{"t": "自伯之东,首如飞蓬。", "b": "《诗·卫风 ·伯兮》"}]}, {"meaning": "古代统领一方的长官。", "cites": [{"t": "分天下以为左右,曰二伯。", "b": "《礼记·王制》"}], "words": [{"w": "伯叔", "t": "周王朝对同姓诸侯的称呼"}, {"w": "伯长", "t": "古代对地方官的泛称。"}]}, {"meaning": "古代五等爵位的第三等。", "cites": [{"t": "秦伯素服郊次。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "伯甸", "t": "以伯爵而居甸服。"}]}, {"meaning": "王覇", "cites": [{"t": "彭祖得之,上及有虞,下及五伯。", "b": "《庄子·大宗师》"}, {"t": "一朝而伯。", "b": "《荀子·儒效》"}, {"t": "桓公五伯之上也。", "b": "《韩非子·难四》"}, {"t": "伯者莫高于齐桓。", "b": "《汉书·高帝纪下》"}, {"t": "衰则五伯扶其弱。", "b": "《汉书·诸侯王表》"}, {"t": "壤长地进,至乎伯王。", "b": "《汉书·严安传》"}], "words": [{"w": "伯余", "t": "黄帝的臣子。古代传说最初制造衣裳的人"}, {"w": "伯道", "t": "霸道"}, {"w": "伯王", "t": "霸王。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('779wx','伶','1','líng','亻','7','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从人,令声。本义:古乐官名、相传黄帝时有伶伦,世掌乐官)。"}, {"meaning": "同本义。", "cites": [{"t": "伶,弄臣也。", "b": "《说文》"}, {"t": "寺人之伶。", "b": "《韩诗·车邻》"}, {"t": "令伶箫咏歌。", "b": "《国语·鲁语》"}, {"t": "仕于伶官。", "b": "《诗·简兮序》"}, {"t": "问之伶州鸠。", "b": "《国语·周语》"}], "words": [{"w": "伶官", "t": "古代的乐官"}, {"w": "伶工", "t": "旧指乐师或演员"}, {"w": "伶伦", "t": "传说中黄帝时的乐官"}, {"w": "伶界", "t": "旧称戏曲界。"}]}, {"meaning": "引申为表演歌舞的艺人。", "cites": [{"t": "伶,乐人。", "b": "《广韵》"}, {"t": "帝制新曲,教女伶数十百人。", "b": "《新唐书·礼乐志》"}, {"t": "教坊优伶。", "b": "《北梦琐言》"}, {"t": "去年西京寺,众伶集讲筵。", "b": "孟郊《教坊歌儿》"}], "words": [{"w": "男伶", "t": "男演员"}, {"w": "女伶;名伶", "t": "名演员"}, {"w": "红伶", "t": "走红的演员"}, {"w": "伶优", "t": "优伶。"}]}, {"meaning": "孤独。", "cites": [{"t": "伶俜萦苦辛(孤孤单单,受尽辛苦折磨。伶俜,孤单的样子。萦,缠绕)。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "伶丁", "t": "孤独的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('780wx','佣','1','yōng yòng','亻','7','','[{"pinyin": "yōng", "defs": [{"meaning": "(形声。从人,庸声。本义:受雇佣,出卖劳动力) 同本义。", "cites": [{"t": "佣,均直也。卖力受直曰佣。隋其力均其直也。", "b": "《说文》"}, {"t": "教民相与佣輓犁。", "b": "《汉书·食货志》"}, {"t": "尝与人佣耕。", "b": "《史记·陈涉世家》"}, {"t": "佣者笑而应。", "b": ""}, {"t": "若为佣耕。", "b": ""}, {"t": "子佣出。", "b": "清·周容《芋老人传》"}, {"t": "子不佣矣。", "b": ""}]}, {"meaning": "又如 雇佣。如:佣伍(雇佣的军队);佣钱(雇佣的酬金、工钱) 受雇佣。如:佣作(受雇于人,为人工作);佣债(受雇于人,从事劳役以取酬劳);佣耕(受雇于人,为人耕种);佣书(受雇于人,为人书写文字);佣客(受雇用的人);佣力(受雇出卖劳力)。"}, {"meaning": "工钱。", "cites": [{"t": "凡三年,运七百万石,省陆运之佣四十万贯。", "b": "《旧唐书》"}]}, {"meaning": "平凡。", "cites": [{"t": "心平愉则色不及佣而可以养目,声不及佣而可以养耳。", "b": "《荀子》"}], "words": [{"w": "佣士", "t": "平凡的人"}, {"w": "佣中佼佼", "t": "在平凡之人中才能较为突出。"}]}]}, {"pinyin": "yòng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('781wx','低','1','dī','亻','7','','[{"pinyin": "dī", "defs": [{"meaning": "(形声。从人,氐(dǐ)声。本义:下,与“高”相对)。"}, {"meaning": "同本义。"}, {"meaning": "向上伸展的长度相对较小的。", "cites": [{"t": "风吹草低见牛羊。", "b": "《乐府诗集·杂歌谣辞·敕勒歌》"}], "words": [{"w": "低水位;低仰", "t": "忽高忽低"}, {"w": "低小", "t": "低矮窄小"}, {"w": "低狭", "t": "低矮狭小。"}]}, {"meaning": "向下;向下垂。", "cites": [{"t": "低,低昂。", "b": "《广韵》"}, {"t": "据轼低头,不能出气。", "b": "《庄子·盗跖》"}, {"t": "封君皆低首仰给。", "b": "《史记·平淮书》"}, {"t": "举头望明月,低头思故乡。", "b": "唐·李白《静夜思》"}], "words": [{"w": "低忖", "t": "低头思量"}, {"w": "低腰", "t": "弯着腰"}, {"w": "低眉", "t": "眼向下看"}, {"w": "低首", "t": "低颜,低簪。低着头"}, {"w": "低首下心", "t": "形容屈从恭顺的样子。"}]}, {"meaning": "触犯。", "cites": [{"t": "天之道,虚其无形,虚则不屈,无形则无所低赶。", "b": "《管子·心术上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('782wx','你','1','nǐ','亻','7','','[{"pinyin": "nǐ", "defs": [{"meaning": "(形声。从人,尔声。本义:称说话的对方)。"}, {"meaning": "同本义。", "cites": [{"t": "武平元年童谣曰:“狐截尾,你欲除我我除你。”", "b": "《隋书·五行志上》"}], "words": [{"w": "你咱", "t": "你"}, {"w": "你懑", "t": "你们"}, {"w": "你娘", "t": "骂人的话,相当于“你娘的”"}, {"w": "你老", "t": "对尊长的敬称"}, {"w": "你那", "t": "你老人家"}, {"w": "你伫", "t": "您"}, {"w": "你等", "t": "你们。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('783wx','住','1','zhù','亻','7','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从人,主声。本义:停留)。"}, {"meaning": "同本义(站住)。", "cites": [{"t": "见者呼之曰:“蓟先生小住。”", "b": "《后汉书·蓟子训传》"}, {"t": "春光已向梅梢住。", "b": "《后汉书》"}, {"t": "融为中书郎,未有居止,权牵小船于岸上住。", "b": "《南齐书·张融传》"}, {"t": "舞余香尚存,歌尽声犹住。", "b": "萧悫《春日曲水》"}], "words": [{"w": "住歇", "t": "停止,停歇"}, {"w": "住滞", "t": "停留"}, {"w": "住后", "t": "留后;殿后"}, {"w": "住锡", "t": "僧人在某地居留。锡,锡杖。"}]}, {"meaning": "停止。", "cites": [{"t": "杜请裴追之,羊去数里住马,既而俱还杜许。", "b": "《世说新语·方正》"}, {"t": "两岸猿声啼不住,轻舟已过万重山。", "b": "李白《早发白帝城》"}], "words": [{"w": "住脚", "t": "止步"}, {"w": "住罢", "t": "停止。"}]}, {"meaning": "暂居;居住。", "cites": [{"t": "自言本是京城女,家在虾蟆陵下住。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "又。", "cites": [{"t": "住近湓江。", "b": ""}, {"t": "人道寄奴曾住。", "b": "宋·辛弃疾《永遇乐》"}], "words": [{"w": " 住坐", "t": "居住"}, {"w": "住室", "t": "供人居住的房间。"}]}, {"meaning": "住宿;过夜。", "cites": [{"t": "行多有病住无粮,万里还乡未到乡。", "b": "卢纶《逢病军人》"}]}, {"meaning": "保留。", "cites": [{"t": "应似园中桃李树,花落随风子住枝。", "b": "白居易《母别子》"}]}, {"meaning": "做动词的补语。"}, {"meaning": "表示牢固或稳当。", "cites": [{"t": "众人向前,一个带住婆子,三四个带住唐牛儿,把他横拖倒拽,直推进郓城县里来。", "b": "《水浒全传》"}, {"t": "贾政还欲打时,早被王夫人抱住板子。", "b": "《红楼梦》"}]}, {"meaning": "表示停止或静上。", "cites": [{"t": "我给你个好主意,虎姑娘立住了,面对面地对他说,…这个事非我自己办不可。", "b": "老舍《骆驼祥子》"}]}, {"meaning": "跟“得”或“不”连用。表示能否胜任或能否够得上。", "cites": [{"t": "那祝龙当敌秦明不住,拍马便走。", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('784wx','位','1','wèi','亻','7','','[{"pinyin": "wèi", "defs": [{"meaning": "(会意。从人立。人站在朝廷上。本义:官吏在朝廷上站立的位置)。"}, {"meaning": "同本义。", "cites": [{"t": "列中廷之左右谓之位。", "b": "《说文》"}, {"t": "掌外朝之位。", "b": "《周礼·朝士》"}], "words": [{"w": "位著(也作位宁古代宫殿,中庭左右两侧叫“位”,门屏之间叫“著”(或“宁”),故用以借指在朝居官)", "t": ""}]}, {"meaning": "位置;方位。", "cites": [{"t": "阴阳易位。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "座位;席位;铺位", "t": ""}]}, {"meaning": "职位;地位。", "cites": [{"t": "位卑则足羞,官盛则近谀。", "b": "韩愈《师说》"}, {"t": "以在位久。", "b": "宋·王安石《答司马谏议书》"}, {"t": "位之移人也。", "b": "清·周容《芋老人传》"}, {"t": "位尊而无功。", "b": "《聊斋志异·促织》"}, {"t": "长安君之位。", "b": ""}], "words": [{"w": "位地", "t": "官位门第"}, {"w": "位任", "t": "官位,职务"}, {"w": "位行", "t": "名位与事迹"}, {"w": "位序", "t": "官职级别"}, {"w": "位宦", "t": "位号。官职爵位"}, {"w": "位秩", "t": "官爵和俸禄"}, {"w": "位阶", "t": "官阶品级"}, {"w": "位极人臣", "t": "官位达于人臣的最高一级"}, {"w": "位遇", "t": "官位和待遇。"}]}, {"meaning": "特指君王或诸侯之位。", "cites": [{"t": "朕在位七十载。", "b": "《书·尧典》"}]}, {"meaning": "占据其应有的位置。", "cites": [{"t": "卑高以陈,贵贱位矣。", "b": "《易·系辞上》"}]}, {"meaning": "立,站。", "cites": [{"t": "面三槐,三公位焉。", "b": "《周礼》"}]}, {"meaning": "引申为居,处。", "cites": [{"t": "位其所位焉,正也。", "b": "《公孙龙子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('785wx','伴','1','bàn pàn','亻','7','','[{"pinyin": "bàn", "defs": [{"meaning": "陪同;依随。", "cites": [{"t": "伴张驰之信期。", "b": "《楚辞·悲回风》。注:“俱也。”"}, {"t": "二贵酋名曰馆伴。(名义上是招待使者的官员。)", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "伴宿", "t": "出殡前一天夜里,亲属等人通宵守灵"}, {"w": "伴游", "t": "陪同游玩。"}]}, {"meaning": "相比。", "cites": [{"t": "他都是前生修的,咱拿甚么伴他?", "b": "《醒世姻缘传》"}]}, {"meaning": "伴侣;同伴。", "cites": [{"t": "众骇遽以离心兮,又何以为此伴也?", "b": "《楚辞·九章·惜诵》"}, {"t": "青春作伴好还乡。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "羁魂(旅魂)有伴,当不孤寂。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "伴等", "t": "伙伴"}, {"w": "伴佣", "t": "伙计。指店员"}, {"w": "伴哥", "t": "农村中少年的泛称"}, {"w": "伴伍", "t": "邻里。"}]}]}, {"pinyin": "pàn", "defs": [{"meaning": "大貌。", "cites": [{"t": "伴,大貌。从人,半声。", "b": "《说文》"}, {"t": "伴奂尔游矣。", "b": "《诗·大雅·卷阿》。传:“广大。”笺:“自纵弛之貌。”"}, {"t": "心广体胖(伴)。", "b": "《礼记·大学》"}, {"t": "般(伴)乐怠傲。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('786wx','身','1','shēn','身','7','','[{"pinyin": "shēn", "defs": [{"meaning": "(象形。象人之形。本义:身躯的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "身,躬也。象人之形。", "b": "《说文》。按,身的本义是人的躯干。"}, {"t": "必有寝礼,长一身有半。", "b": "《论语·乡党》"}, {"t": "人自项以下,踵以上,总谓之身。颈以下,股以上,亦谓之身。", "b": "王述之《经义述闻》"}, {"t": "人百其身。", "b": "《诗·秦风·黄鸟》"}, {"t": "身也者,亲之枝也。", "b": "《礼记·哀公问》"}, {"t": "身也者,父母之遗体也。", "b": "《礼记·祭义》"}, {"t": "饿其体肤,空乏其身。", "b": "《孟子·告子下》"}, {"t": "身首离兮心不惩。", "b": "《楚辞·九歌·国殇》"}, {"t": "粉骨碎身浑不怕,要留青白在人间。", "b": "明·于谦《石灰吟》"}, {"t": "项伯亦拔剑起舞,常以身翼蔽沛公,庄不得击。", "b": "《史记·项羽本纪》"}], "words": [{"w": "身边钱", "t": "随身带的钱"}, {"w": "身品", "t": "身材"}, {"w": "身伴", "t": "身旁"}, {"w": "身边人", "t": "贴知伺候的奴婢,妾"}, {"w": "身首分离", "t": "人的头和躯体分开。指被杀"}, {"w": "身殃", "t": "谓身遭灾殃"}, {"w": "身牖", "t": "身体的窗子,指耳朵"}, {"w": "身无长物", "t": "比喻人的穷困。"}]}, {"meaning": "物件的主体部分。", "cites": [{"t": "枞,松叶柏身;桧,柏叶松身。", "b": "《尔雅·释木》"}, {"t": "亥有二首六身。", "b": "《左传·襄公三十年》"}], "words": [{"w": "树身;河身", "t": ""}]}, {"meaning": "自己,自身。", "cites": [{"t": "免不可复得,而身为宋国笑。", "b": "《韩非子·五蠹》"}, {"t": "远者数世,近者及身。", "b": "清·黄宗羲《原君》"}, {"t": "吾日三省吾身。", "b": "《论语·学而》"}, {"t": "是不亦责于身者重以周乎?", "b": "唐·韩愈《原毁》"}], "words": [{"w": "身己", "t": "本身,指属于自己的事"}, {"w": "身外", "t": "自己以外,自身之外"}, {"w": "身愆", "t": "己身的过失。"}]}, {"meaning": "生命,性命。", "cites": [{"t": "国事至此,予不得爱身。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "献身;奋不顾身;舍身救人", "t": ""}]}, {"meaning": "地位或身分。", "cites": [{"t": "惟恐或后,竞以宗庙、社稷、身名、君宠,无不同于芋焉。", "b": "清·周容《芋老人传》"}], "words": [{"w": "身名俱泰", "t": "物质生活优裕,名望亦崇高"}, {"w": "身地", "t": "出身地位。"}]}, {"meaning": "毕生,一辈子。", "cites": [{"t": "行之乎仁义之途,游之乎《诗》《书》之源,无迷其途,无绝其源,终吾身而已矣。", "b": "唐·韩愈《答李翊书》"}], "words": [{"w": "身后萧条", "t": "死后景况凄凉,没有遗下产业、钱财或子女。"}]}, {"meaning": "亲身,亲自。", "cites": [{"t": "禹之王天下也,身执耒碴臿以为民先。", "b": "《韩非子·五蠹》"}, {"t": "将军身率益州之众出于秦川。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "身历", "t": "亲身经历。"}]}, {"meaning": "怀孕。", "cites": [{"t": "大任有身,生此文王。", "b": "《诗·大雅·大明》。大任:周文王之母"}, {"t": "且以汝之有身也,更恐不胜悲,故惟日日呼酒买醉。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "身已", "t": "妇人怀孕"}, {"w": "身怀六甲", "t": "即怀孕"}, {"w": "身瑞", "t": "身孕。"}]}, {"meaning": "体验。", "cites": [{"t": "尧、舜性之也;汤、武身之也;五霸,假之也。", "b": "《孟子》"}]}, {"meaning": "担当。", "cites": [{"t": "中有贤子自为家督,遂起而身父母之任焉。", "b": "明·李贽《战国论》"}]}, {"meaning": "担任。", "cites": [{"t": "自奉天入,琯身中军先锋。 ", "b": "《新唐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('787wx','皂','1','zào','白','7','','[{"pinyin": "zào", "defs": [{"meaning": "皂斗的略称(指栎实、柞实等),其壳斗煮汁,可以染黑,本作“皁”,后作“皂”。", "cites": [{"t": "一日山林,其植物宜皂物。", "b": "《周礼·地官·大司徒》"}], "words": [{"w": "皂物", "t": "柞栗之类。可做黑色染料。"}]}, {"meaning": "旧时衙门内的差役。", "cites": [{"t": "官府坐在三堂上,叫值日的皂头把万中书提了进来。", "b": "《儒林外史》"}], "words": [{"w": "皂雕追紫燕,猛虎啖羊羔", "t": "形容捉拿人时凶猛而迅速"}, {"w": "皂快壮健", "t": "捕快壮卒"}, {"w": "皂快", "t": "捕快;缉捕差役"}, {"w": "皂头", "t": "旧时衙门差役的头目"}, {"w": "皂舆", "t": "皂人与舆人。古代贱役的两种小吏"}, {"w": "皂衣", "t": "借指下吏"}, {"w": "皂役", "t": "旧时官衙中的差役"}, {"w": "皂班", "t": "泛指差役"}, {"w": "皂人", "t": "古代养马的下吏。"}]}, {"meaning": "喂马或喂牛的饲槽。", "cites": [{"t": "牛骥同一皂。", "b": "文天祥《正气歌》"}], "words": [{"w": "皂枥", "t": "即马厩"}, {"w": "皂牢", "t": "饲养牛马的圈栏"}, {"w": "皂栈", "t": "马厩。皂,食槽;栈,马脚下防湿的木板。"}]}, {"meaning": "皂荚的省称。", "cites": [{"t": "皂树高大,叶如槐叶。", "b": "明·李时珍《本草纲目》"}], "words": [{"w": "皂角", "t": "即皂荚"}, {"w": "皂汤", "t": "浸泡皂荚的水。"}]}, {"meaning": "黑色", "cites": [{"t": "黑人黑马皂罗袍。", "b": "《封神演义》"}], "words": [{"w": "青红皂白;皂褶儿", "t": "穿在外面的黑色上衣"}, {"w": "皂帕", "t": "黑色的头巾"}, {"w": "皂巾", "t": "黑色的头巾"}, {"w": "皂靴", "t": "黑色的短靴"}, {"w": "皂盖", "t": "古代车上的黑色车盖"}, {"w": "皂鞋", "t": "一种黑色的便鞋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('788wx','伺','1','sì cì','亻','7','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从人,司声。本义:候望,探察)。"}, {"meaning": "同本义。", "cites": [{"t": "伺,候望也。", "b": "《说文新附》"}, {"t": "其后阁下位益尊,伺侯于门墙者日益进。", "b": "唐·韩愈《与陈给事书》"}], "words": [{"w": "伺候", "t": "等候;服侍;衙役"}, {"w": "伺觇", "t": "窥探"}, {"w": "伺闲", "t": "窥测时机。"}]}, {"meaning": "观察。", "cites": [{"t": "伺,视也。", "b": "《方言十》"}, {"t": "童微伺其睡,以缚背刃,力上下,得绝。", "b": "唐·柳宗元《童区寄传》"}, {"t": "逆阉防伺甚严,虽家仆不得近。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "伺察", "t": "观察;侦察"}, {"w": "伺望", "t": "守望;察看"}, {"w": "伺漏", "t": "察看刻漏。"}]}, {"meaning": "守候,等待。", "cites": [{"t": "伺,候也。察也。", "b": "《字林》"}, {"t": "楚人贫居,读《淮南子》,得“螳螂伺蝉自鄣叶可以隐形”。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "振声激扬,伺者因此觉知。", "b": "《后汉书·张衡传》"}], "words": [{"w": "伺便", "t": "等待方便的时机"}, {"w": "伺晨", "t": "等待天明"}, {"w": "伺应", "t": "待机策应。"}]}, {"meaning": "对待。", "cites": [{"t": "父牵车为业,伺小三如奴,偶不称意,便叱詈。", "b": "徐珂《清稗类钞》"}]}]}, {"pinyin": "cì", "defs": [{"meaning": "在人身边供使唤；"}, {"meaning": "照料饮食起居；", "cites": [{"t": "伺候柴进回庄,林冲便说道", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('789wx','佛','1','fó fú','亻','7','','[{"pinyin": "fó", "defs": [{"meaning": "梵文 Buddha音译“佛陀”的简称 。意译为“觉者”、“知者”、“觉”。觉有三义:自觉、觉他(使众生觉悟)、觉行圆满,是佛教修行的最高果位。据称,凡夫缺此三项,声闻、缘觉缺后二项,菩萨缺最后一项,只有佛才三项俱全。小乘讲的“佛”,一般是用作对释迦牟尼的尊称。大乘除指释迦牟尼外, 还泛指一切觉行圆满者。宣称三世十方,到处有佛。", "cites": [{"t": "西方有神,名曰佛。", "b": "《后汉书·西域传》"}], "words": [{"w": "佛天", "t": "佛;西天;美好的地方"}, {"w": "佛化", "t": "佛的教化"}, {"w": "佛光", "t": "佛所带来的光明"}, {"w": "佛会", "t": "佛菩萨众圣会聚的地方"}, {"w": "佛图", "t": "佛塔"}, {"w": "佛位", "t": "成佛正果之位。"}]}, {"meaning": "佛教。", "cites": [{"t": "攘斥佛老。", "b": "韩愈《进学解》"}], "words": [{"w": "信佛;佛学", "t": "佛教的学问"}, {"w": "佛义", "t": "佛教的经义"}, {"w": "佛典", "t": "佛教的典籍。"}]}, {"meaning": "佛像。", "cites": [{"t": "此上手房宇,乃管待老爷们的佛堂、经堂、斋堂。", "b": "《西游记》"}], "words": [{"w": "铜佛;佛面", "t": "佛像面部"}, {"w": "佛座", "t": "安置佛像的台"}, {"w": "佛殿;佛宝", "t": "各种佛像。"}]}, {"meaning": "比喻慈悲的人。", "cites": [{"t": "民举手加额,呼余为佛。", "b": "宋·吕祖谦《吕氏家塾记》"}]}, {"meaning": "佛经。", "cites": [{"t": "两个姑子先念了佛偈。", "b": "《红楼梦》"}], "words": [{"w": "诵佛;念佛;佛偈", "t": "佛经中的颂词。"}]}]}, {"pinyin": "fú", "defs": [{"meaning": "违背。", "cites": [{"t": "佛,戾也。或作拂。", "b": "《集韵》"}]}, {"meaning": "——见“仿佛”(fǎngfú)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('790wx','囱','1','cōng','囗','7','','[{"pinyin": "cōng", "defs": [{"meaning": "灶突。今称烟囱。", "cites": [{"t": "囱,通孔也,灶突也。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('791wx','近','1','jìn','辶','7','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,斤声。本义:走近,接近)。"}, {"meaning": "同本义。", "cites": [{"t": "近,附也。", "b": "《说文》"}, {"t": "为其近于道也。", "b": "《礼记·祭义》"}, {"t": "小大近丧。", "b": "《诗·大雅·荡》"}, {"t": "吾入关,秋毫不敢有所近。", "b": "《史记·项羽本纪》"}, {"t": "稍出近之。", "b": "唐·柳宗元《三戒》"}, {"t": "近出前后。", "b": ""}, {"t": "稍近。", "b": ""}, {"t": "时敌军已近寨。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "逼近", "t": "靠近;接近"}, {"w": "挨近;近傍", "t": "接近;靠近"}, {"w": "近晚", "t": "傍晚"}, {"w": "近火", "t": "靠近火。"}]}, {"meaning": "引申追求,希求。", "cites": [{"t": "为近利市三倍。", "b": "《易·说卦》"}], "words": [{"w": "近名", "t": "追求名誉"}, {"w": "近利", "t": "逐利。"}]}, {"meaning": "逼近。", "cites": [{"t": "二与四同功而异位,其善不同。二多誉,四多惧,近也。", "b": "《易·系辞下》。韩康伯注:“位逼于君,故多惧也。”"}]}, {"meaning": "得宠。", "cites": [{"t": "襄子必近幸子。", "b": "《战国策·赵策》"}, {"t": "有七孺子皆近。", "b": "《战国策·齐策》"}, {"t": "虽有贵戚近习。", "b": "《礼记·月令》"}], "words": [{"w": "近上", "t": "接近上司"}, {"w": "近上的", "t": "接近上层的;等级高的"}, {"w": "近珰", "t": "皇帝宠信的太监"}, {"w": "近爱", "t": "帝王所亲近宠爱。"}]}, {"meaning": "知晓。", "cites": [{"t": "慈亲不能传于子,忠臣不能入于君,唯有其材者为近之。", "b": "《吕氏春秋》"}]}, {"meaning": "指时间或空间的距离短。", "cites": [{"t": "无有远近幽深。", "b": "《易·系辞》"}, {"t": "忘路之远近。", "b": "陶潜《桃花源记》"}, {"t": "日始出时去人近。", "b": "《列子·汤问》"}, {"t": "而日中时近也。", "b": ""}, {"t": "远者小而近者大。", "b": ""}, {"t": "近者热而远者凉。", "b": ""}], "words": [{"w": "四近", "t": "周围附近的地方"}, {"w": "邻近", "t": "位置挨近;附近"}, {"w": "近宅", "t": "附近左右的住宅"}, {"w": "近局", "t": "近邻,邻居"}, {"w": "近火先焦", "t": "比喻无辜的人因最接近祸源而首先遭殃。"}]}, {"meaning": "最近。", "cites": [{"t": "近三世纪则学校大备。", "b": "蔡元培《图画》"}], "words": [{"w": "新近", "t": "不久以前"}, {"w": "近目", "t": "近日;目前"}, {"w": "近夜", "t": "傍晚"}, {"w": "近忧", "t": "近虞。目前的忧虑。"}]}, {"meaning": "亲近。", "cites": [{"t": "外无期功强近之亲。", "b": "李密《陈情表》"}], "words": [{"w": "近宾", "t": "亲近的宾客;有亲密关系的宾客"}, {"w": "近侍", "t": "亲近侍奉"}, {"w": "近属", "t": "血缘关系较近的亲属"}, {"w": "近党", "t": "关系密切的亲族。"}]}, {"meaning": "浅近,容易理解,容易明白的。", "cites": [{"t": "言近而指远者,善言也。", "b": "《孟子·尽心下》"}], "words": [{"w": "近识", "t": "识见浅陋"}, {"w": "近器", "t": "才识浅陋平庸的人"}, {"w": "近鄙", "t": "鄙薄"}, {"w": "近浅", "t": "浅陋,平庸"}, {"w": "近俗", "t": "浅近通俗"}, {"w": "近事", "t": "浅鄙之事。"}]}, {"meaning": "将近;差不多。", "cites": [{"t": "应者近万人。", "b": "《资治通鉴·唐纪》"}, {"t": "官盛则近谀。", "b": "唐·韩愈《师说》"}], "words": [{"w": "近半", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('792wx','彻','1','chè','彳','7','','[{"pinyin": "chè", "defs": [{"meaning": "(形声。从彳(chì),甲骨文,从“鬲”(炊具)从“丑”(举手),表示吃罢饭用手撤去炊具的意思。《说文》给古文增加了音符“彳”,变成了形声字。本义:撤除,撤去)。"}, {"meaning": "同本义。", "cites": [{"t": "废彻不迟。", "b": "《诗·小雅·楚茨》"}, {"t": "司宫彻之士。", "b": "《礼记·燕礼》"}, {"t": "彻筮席。", "b": "《礼记·士冠礼》"}, {"t": "大夫无故不彻县。", "b": "《礼记·曲礼》"}, {"t": "且虽诸侯相见,军卫不彻,警也。", "b": "《左传·宣公十二年》"}, {"t": "三家者以《雍》彻。", "b": "《论语·八佾上》"}, {"t": "解车休马,罢酒彻乐。", "b": "《淮南子·原道》"}], "words": [{"w": "彻案", "t": "撤去食案"}, {"w": "彻坐", "t": "撤去座位"}, {"w": "彻兵", "t": "撤军。"}]}, {"meaning": "拆毁;拆下。", "cites": [{"t": "彻我墙屋。", "b": "《诗·小雅·十月之交》"}, {"t": "伯昌号衰,秉鞭作牧,何令彻彼岐社,命有殷国?", "b": "《楚辞·天问》"}], "words": [{"w": "彻屋", "t": "拆除房屋。"}]}, {"meaning": "通达;明白。", "cites": [{"t": "汝心之固,固不可彻,曾不若孀妻弱子。", "b": "《列子·汤问》"}], "words": [{"w": "彻鉴", "t": "明鉴;洞察。"}]}, {"meaning": "垦治。", "cites": [{"t": "彻田为粮。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "彻田", "t": "垦治田地。"}]}, {"meaning": "穿透。", "cites": [{"t": "日光下彻,影布石上。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "彻札", "t": "穿透铠甲。"}]}, {"meaning": "结束,完结。", "cites": [{"t": "自经丧乱少睡眠,长夜沾湿何由彻。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "彻命", "t": "达其使命"}, {"w": "彻卷", "t": "毕卷;读章全卷。"}]}, {"meaning": "通,达。", "cites": [{"t": "彻,通也。", "b": "《说文》"}, {"t": "果无不彻。", "b": "《国语·晋语六》"}, {"t": "摄而不彻。", "b": "《国语·楚语上》"}, {"t": "陈士卒百人以为彻行百行。", "b": "《国语·吴语》"}, {"t": "其何事不彻?", "b": "《国语·周语上》"}, {"t": "焚烟彻于上。", "b": "《国语·鲁语上》"}, {"t": "其聪能听彻之。", "b": "《国语·楚语下》"}]}, {"meaning": "又。", "cites": [{"t": "民之彻官百品。", "b": ""}, {"t": "不敢彻声闻于天王。", "b": "《国语·国语上》"}, {"t": "物彻疏明。", "b": "《庄子·应帝王》"}, {"t": "目彻为明,耳彻为聪,鼻彻为颤,口彻为甘,心彻为知,知彻为德。", "b": "《庄子·外物》。注:“彻,通也。”"}], "words": [{"w": "透彻", "t": "详尽而深入"}, {"w": "洞彻", "t": "透彻地了解"}, {"w": "通彻", "t": "通晓;贯通"}, {"w": "彻夜", "t": "通宵,整夜"}, {"w": "彻内彻外", "t": "从里到外;完完全全"}, {"w": "彻朗", "t": "清明。指心地清净光明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('793wx','役','1','yì','彳','7','','[{"pinyin": "yì", "defs": [{"meaning": "(古文作伇。会意。甲骨文字形,象人持殳(shū)击人。本义:服兵役,戍守边疆)。"}, {"meaning": "同本义。", "cites": [{"t": "役,戍边也。执殳巡行也。", "b": "《说文》"}, {"t": "若起野役。", "b": "《周礼·遂人》"}, {"t": "听政役以比居州长。", "b": "《周礼·小宰》"}, {"t": "行役之事。", "b": "《周礼·师田》"}, {"t": "君子于役,如之何勿思。", "b": "《诗·王风》。郑玄笺:“行役多危难,我诚思之。”"}, {"t": "弃政而役,非其任也。", "b": "《国语》"}], "words": [{"w": "役夫", "t": "服役的人"}, {"w": "役民", "t": "服役的人"}, {"w": "役卒", "t": "服役的人。"}]}, {"meaning": "役使,驱使。", "cites": [{"t": "予造天役,遗大投艰于朕身。", "b": "《书·大诰》"}], "words": [{"w": "役车", "t": "供役用的车"}, {"w": "役徒", "t": "服工役的人"}, {"w": "役属", "t": "使隶属于己而役使之"}, {"w": "役养", "t": "役使;役使休养"}, {"w": "役法", "t": "为法令所役使"}, {"w": "役物", "t": "役使外物为我所用"}, {"w": "役令", "t": "役使,驱遣。"}]}, {"meaning": "劳役。", "cites": [{"t": "兵久不辍,民困于役。", "b": "《三国志》"}], "words": [{"w": "役丁", "t": "服劳役者"}, {"w": "役作", "t": "工役劳作"}, {"w": "役所", "t": "役作的处所"}, {"w": "役庸", "t": "用以代替力役的赋税。"}]}, {"meaning": "服劳役的人。", "cites": [{"t": "季氏使其乘之人,以其役邑入者无征。", "b": "《左传》。孔颖达疏:役谓共官力役,帅今之丁也"}]}, {"meaning": "仆人。", "cites": [{"t": "汝辈幼小,家贫无役,柴水之劳,何时可免?", "b": "《南史》"}, {"t": "虽留下几户穷民,只好奔走官差,那有空役等雇。", "b": "《京本通俗小说》"}]}, {"meaning": "门生,弟子。", "cites": [{"t": "儒家之徒董无心,墨家之役缠子,相见讲道。", "b": "《论衡》"}]}, {"meaning": "事情。", "cites": [{"t": "为此役也,子若以君命赐之,其已。", "b": "《左传》。杜预注:役,事也"}]}, {"meaning": "事件。", "cites": [{"t": "鸿门之役,微项伯几殆。", "b": "宋·陈亮《酌古论一》"}]}, {"meaning": "士卒,服兵役的人。", "cites": [{"t": "寡人帅不腆吴国之役,遵汶之上。", "b": "《国语》。韦昭注:“役,兵也。”"}]}, {"meaning": "职责,职分。", "cites": [{"t": "万物各有役,吾生何所营。", "b": "宋·陆游《晓赋》"}]}, {"meaning": "战斗;战争。", "cites": [{"t": "秦穆公伐郑之役,考之《左传》,其谏而止之,哭而送其子者,独蹇叔而已。", "b": "金·王若虚《史记辨惑二》"}], "words": [{"w": "台儿庄之役", "t": ""}]}, {"meaning": "差役。", "cites": [{"t": "宰悦,免成役。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('794wx','返','1','fǎn','辶','7','','[{"pinyin": "fǎn", "defs": [{"meaning": "(形声。从辵,反声。字本作“反”。本义:回归,返回)。"}, {"meaning": "同本义。", "cites": [{"t": "返,还也。", "b": "《说文》"}, {"t": "返,归也。", "b": "《广雅》"}, {"t": "祖伊返。", "b": "《书·西伯勘黎》"}, {"t": "黄鹤一去不复返,白云千载空悠悠。", "b": "唐·崔颢《黄鹤楼》"}, {"t": "公子往而臣不送,以是知公子恨之复返也。", "b": "《史记·魏公子列传》"}, {"t": "久在樊笼里,复得返自然。", "b": "晋·陶渊明《归园田居》"}, {"t": "返字本作“反”", "b": ""}, {"t": "福禄来反。", "b": "《诗·周颂·执竞》"}, {"t": "而反其侵地。", "b": "《国语·齐语》"}], "words": [{"w": "返命", "t": "办完事情后,回来复命"}, {"w": "返书", "t": "回信"}, {"w": "返棹", "t": "船只返回。"}]}, {"meaning": "归还。", "cites": [{"t": "其子长而返其璧。", "b": "《吕氏春秋·观表》"}, {"t": "俟汝至石头城,返汝簪。", "b": "《搜神记》"}], "words": [{"w": "返璧", "t": "送还别人馈赠的礼品"}, {"w": "返金", "t": "退钱,还钱。"}]}, {"meaning": "更换。", "cites": [{"t": "返瑟而弦。", "b": "《吕氏春秋·慎人》"}], "words": [{"w": "返瑟而弦", "t": "换瑟而弹奏"}, {"w": "返嘴", "t": "反口,改口"}, {"w": "返易", "t": "倒换,掉换。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('795wx','余','1','yú','人','7','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从食,余声。本义:饱足)。"}, {"meaning": "饱足。足食得饱。", "cites": [{"t": "余,饶也。", "b": "《说文》"}]}, {"meaning": "剩下;剩余。", "cites": [{"t": "昔人已乘黄鹤去,此地空余黄鹤楼。", "b": "崔颢《黄鹤楼》"}]}, {"meaning": "剩下的,多余的。", "cites": [{"t": "行有余力,则以学文。", "b": "《论语》"}, {"t": "亦无使有余。", "b": "《吕氏春秋·辩士》。注:“犹多也。”"}, {"t": "父有余(余)财。", "b": "《吴仲山碑》"}, {"t": "今也每食无余(余)。", "b": "《诗·秦风·权舆》"}], "words": [{"w": "余夫", "t": "指一家五口或八口为率以外多余的人口"}, {"w": "余润", "t": "利润"}, {"w": "余资", "t": "剩余的钱"}, {"w": "余师", "t": "很多余地;的老师。"}]}, {"meaning": "残留的;遗留的。", "cites": [{"t": "孤嶂秦碑在,荒城鲁殿余。", "b": "唐·杜甫《登兖州城楼》"}, {"t": "肯与邻翁相对饮,隔篱呼取尽余(余)杯。", "b": "唐·杜甫《客至》"}], "words": [{"w": "余蔌", "t": "剩余的菜肴"}, {"w": "余庆", "t": "祖先留下的福泽。即因前辈的善行而使子孙得到某些好处"}, {"w": "余水", "t": "剩余的水"}, {"w": "余芳", "t": "残花;死后遗留的美名"}, {"w": "余杯", "t": "杯中残余的酒"}, {"w": "余珍", "t": "前代遗留的遗物。"}]}, {"meaning": "次要的。", "cites": [{"t": "唱彻《阳关》泪未干,功名余事且加餐。", "b": "辛弃疾《鹧鸪天》"}], "words": [{"w": "余光", "t": "落日残余的光辉"}, {"w": "余春", "t": "晚春,残余的春光。"}]}, {"meaning": "不尽,无穷。", "cites": [{"t": "一弹再三唱,慷慨有余哀。", "b": "《古诗十九首》"}], "words": [{"w": "余哀", "t": "不尽的哀思"}, {"w": "余思", "t": "不尽的怀思"}, {"w": "余音袅袅", "t": "歌声的余音回荡缭绕"}, {"w": "余霞成绮", "t": "用以称赞文章时含有无穷的意味。"}]}, {"meaning": "其余,其他,以外。", "cites": [{"t": "大儿孔文举,小儿杨德祖,余(余)子碌碌,莫足数也。", "b": "《后汉书·祢衡传》"}, {"t": "得十九人,余无可取者,无以满二十人。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "余子", "t": "其他的人"}, {"w": "余事", "t": "另外的事,其他的事"}, {"w": "余业", "t": "副业"}, {"w": "余论", "t": "指本论以外的议论。"}]}, {"meaning": "多,表示整数后不定的零数。", "cites": [{"t": "一车炭重千余斤。", "b": "白居易《卖炭翁》"}, {"t": "有竹一顷余(余),乔木上参天。", "b": "唐·杜甫《杜鹃》"}], "words": [{"w": "六百余米;五十余岁", "t": ""}]}, {"meaning": "闲暇。", "cites": [{"t": "无为也,则用天下而有余。", "b": "《庄子·天道》"}], "words": [{"w": "余功", "t": "余暇,空闲"}, {"w": "余闲", "t": "余暇。"}]}, {"meaning": "第一人称代词,我或我的。", "cites": [{"t": "余敢贪天子之命,,无下拜?", "b": "《左传·僖公九年》"}, {"t": "余弟宗玄。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "余于仆碑。", "b": "宋·王安石《游褒禅山记》"}, {"t": "此地适与余近。", "b": "明·袁宏道《满井游记》"}]}, {"meaning": "又。", "cites": [{"t": "余之游将自此始。", "b": ""}, {"t": "余亟叹其技。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "又。", "cites": [{"t": "余闻法人好胜。", "b": ""}, {"t": "余既为此志。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "余一人", "t": "古代天子自称。也写作“予一人”"}, {"w": "余小子", "t": "古代天子居丧时的自称。也写作“予小子”。"}]}, {"meaning": "农历四月的别称。", "cites": [{"t": "四月为余。", "b": "《尔雅》"}]}, {"meaning": "“余”的简化字 “余”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('796wx','希','1','xī','巾','7','','[{"pinyin": "xī", "defs": [{"meaning": "(会意。从巾,从爻(yáo),象做针线。“巾”,丝织品,“爻”,象针线交错。本义:刺绣)。"}, {"meaning": "假借为“稀”。稀少;罕见。", "cites": [{"t": "希,罕也。", "b": "《尔雅》"}, {"t": "怨是用希。又,十世希不失矣。", "b": "《论语·先进》。孔注:“少也”"}, {"t": "祸希不及身。", "b": "《吕氏春秋·原乱》。注:“鲜也。”"}, {"t": "鼓瑟希。", "b": "《论语·先进》"}, {"t": "知我者希。", "b": "《老子》"}, {"t": "朱华未希。", "b": "《文选·曹植·朔风诗》"}, {"t": "明星晨未希。", "b": "鲍照《咏史诗》"}, {"t": "有志乎古者希矣。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "希姓", "t": "罕见的姓"}, {"w": "希言", "t": "少言"}, {"w": "希疏", "t": "稀少"}, {"w": "希诧", "t": "希罕惊奇"}, {"w": "希希罕儿", "t": "希罕少见的东西"}, {"w": "希有之事;物以希为贵;希世之宝", "t": ""}]}, {"meaning": "稀疏,成员稀少疏落。同“稀”。", "cites": [{"t": "异于深山之野,人者几希。", "b": "《孟子》。注:“希,远也。”"}, {"t": "地广人希。", "b": "《史记·货殖列传》"}], "words": [{"w": "希行", "t": "稀行。稀客;不常走动。"}]}, {"meaning": "寂静无声。", "cites": [{"t": "大器晚成,大音希声,大象无形。", "b": "《老子》"}], "words": [{"w": "希声", "t": "无声"}, {"w": "希夷", "t": "空虚寂静,无声无色。"}]}, {"meaning": "观望", "cites": [{"t": "希主好恶。", "b": "《商君书》"}, {"t": "希世用事。", "b": "《汉书·董仲舒传》。注:“观相也。”"}]}, {"meaning": "仰慕。", "cites": [{"t": "本无意于希颜,岂有心于慕蔺。", "b": "《隋书·隐逸传》"}, {"t": "希望北极中大星。", "b": "《周髀算经下》。注:“希,仰。”"}, {"t": "仰高希骥。", "b": "《后汉书·赵壹传》"}], "words": [{"w": "希颜", "t": "仰慕颜渊。后泛指仰幕贤者"}, {"w": "希天", "t": "仰慕上天"}, {"w": "希古", "t": "仰慕古人"}, {"w": "希风", "t": "仰慕风操"}, {"w": "希贤", "t": "仰慕贤者。"}]}, {"meaning": "希望。", "cites": [{"t": "夫希世而行。", "b": "《庄子·让王》。司马注:“望也。”"}, {"t": "希其光。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "少时陈力希公侯。", "b": "柳宗元《冉溪》"}, {"t": "[潘金莲]每日抖擞着精神妆饰打扮,希宠市爱。", "b": "《金瓶梅词话》"}], "words": [{"w": "希踪禹迹", "t": "向大禹学习,希望得到成功"}, {"w": "希遂", "t": "希望实践"}, {"w": "希准时出席;敬希指正;尚希笑纳;希能为力", "t": ""}]}, {"meaning": "希图,谋求。", "cites": [{"t": "御下者,请谒希爵,一宜禁塞。", "b": "《后汉书·卢植传》。注:“希,求也。”"}, {"t": "孰有至孤之迹,敢萌希进之心。", "b": "宋·曾巩《谢解启》"}], "words": [{"w": "希进", "t": "希图升官"}, {"w": "希恩", "t": "希冀恩宠"}, {"w": "希荣", "t": "企求名门利禄。"}]}, {"meaning": "迎合。", "cites": [{"t": "希代来贡,作珍皇家。", "b": "晋·傅玄《走狗赋》"}], "words": [{"w": "希代", "t": "迎合世俗"}, {"w": "希合", "t": "迎合"}, {"w": "希旨", "t": "迎合尊长的意旨。"}]}, {"meaning": "表示程度。非常;极。", "cites": [{"t": "你有什么过不去,不要寻他,勒死我倒也是希松的。", "b": "《红楼梦》"}], "words": [{"w": "希臭膨天", "t": "臭气熏天"}, {"w": "希辉光号", "t": "辉煌闪耀"}, {"w": "希脏坌臭", "t": "又脏又臭"}, {"w": "希嫩", "t": "非常嫩"}, {"w": "希松", "t": "极为轻松平常。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('797wx','坐','1','zuò','土','7','','[{"pinyin": "zuò", "defs": [{"meaning": "(会意。《说文》古文作象形字,象两人坐在土上。本义:人的止息方式之一。古人席地而坐,坐时两膝着地,臀部压在脚跟上)。"}, {"meaning": "同本义。", "cites": [{"t": "像二人对坐土形。", "b": "林义光《文源》"}, {"t": "坐而迁之。", "b": "《礼记·曲记》。疏:“坐通名跪,跪名不通坐也。”"}, {"t": "退而坐,取屦。", "b": "《礼记·玉藻》"}, {"t": "受立、授立,不坐。", "b": "《礼记·少仪》"}, {"t": "武坐致右宪王。", "b": "《礼记·乐记》。疏:“坐,跪也。”"}, {"t": "坐行而入。", "b": "《左传·昭公二十六年》。注:“膝行也。”按,坐者,尻也,处也。古席地而坐,膝着席而下其臀曰坐,耸其体曰跪。跪,亦谓之启。跪可言坐,坐不可言跪也。"}, {"t": "侯生坐上坐。", "b": "《史记·魏公子列传》"}, {"t": "坐以待旦。", "b": "《书·太早上》"}, {"t": "坐如尸。", "b": "《礼记·玉藻》"}, {"t": "项王、项伯东向坐,亚夫南向坐。", "b": "《史记·项羽本纪》"}, {"t": "先生坐!何至于此!寡人喻矣。", "b": "《战国策·魏策》"}, {"t": "席不正不坐。", "b": "《论语·乡党》"}, {"t": "坐语未讫。", "b": "《汉书·赵尹韩张两王传》"}]}, {"meaning": "现代在椅、凳出现后,凡将臀部置于椅、凳以支持身体的重量者皆为坐。", "cites": [{"t": "坐看霞色晚,疑是赤城标。", "b": "孟浩然《舟中晓望》"}], "words": [{"w": "坐地", "t": "坐下;坐着;坐在地上"}, {"w": "坐堂", "t": "坐在堂上"}, {"w": "坐上客", "t": "原指在坐宾客。后称受人礼遇为坐上客"}, {"w": "坐啸", "t": "闲坐吟啸,无所事事"}, {"w": "坐拜", "t": "跪拜"}, {"w": "坐右", "t": "曲右足而坐"}, {"w": "坐列", "t": "排列而坐。形容无斗志;坐在店铺内"}, {"w": "坐思", "t": "坐着思念"}, {"w": "坐起", "t": "安坐或起立;起身而坐"}, {"w": "坐静", "t": "静坐修持"}, {"w": "坐饮", "t": "入座宴饮"}, {"w": "坐催", "t": "坐等催取。"}]}, {"meaning": "引申为就坐,就任,包含“主持”、“掌管”的意思。", "cites": [{"t": "二子在幄,坐射犬于外,既食而后食之。", "b": "《左传》"}, {"t": "就打止灵霄宝殿,教他龙床坐不成。", "b": "《西游记》"}], "words": [{"w": "坐膺", "t": "荣膺;受封"}, {"w": "坐办", "t": "清制,非常设机构中负责日常事务者"}, {"w": "坐馆", "t": "任塾师或幕客。"}]}, {"meaning": "定罪,由…而获罪。", "cites": [{"t": "使与邾大夫坐。", "b": "《左传·昭公二十三年》。注:“讼曲直也。”"}, {"t": "坐,罪也。", "b": "《苍颉篇》"}, {"t": "遣郭威招诱白承福入居太原城中,以谋叛坐之,并其部属四百余口尽杀之,不留一个。", "b": "《新编五代史平话》"}]}, {"meaning": "因…犯罪,触犯法律。", "cites": [{"t": "又坐贼杀不辜、鞠狱故不以实、擅斥除骑士乏军兴数罪。", "b": "《汉书·赵尹韩张两王传》"}]}, {"meaning": "居留,停留。", "cites": [{"t": "坐,止也。从土,从畱省。会意。土所止也。此与留同意。", "b": "《说文》"}, {"t": "父子坐旅中,惝恍累日,因留过岁。", "b": "清·归庄《黄孝子传》"}], "words": [{"w": "坐窝子", "t": "留在原处。"}]}, {"meaning": "守,防守。", "cites": [{"t": "楚人坐其北门,而覆诸山下。", "b": "《左传·桓公十二年》"}, {"t": "省外各府州县,皆有坐省家丁。", "b": "徐珂《清稗类钞》"}], "words": [{"w": "坐索", "t": "守候索取;守候催促"}, {"w": "坐阵", "t": "守卫阵地"}, {"w": "坐铺", "t": "守卫本铺。谓警戒"}, {"w": "坐夜", "t": "守夜。"}]}, {"meaning": "坐儿,坐位。后来写作“座”。", "cites": [{"t": "坐中数千人。", "b": "《乐府诗集·陌上桑》"}, {"t": "请以剑舞,因击沛公于坐,杀之。", "b": "《史记·项羽本纪》"}, {"t": "置之坐上。", "b": ""}, {"t": "设一虚坐。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "满坐宾客。", "b": "明·高启《书博鸡者事》"}, {"t": "满坐寂然。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "满坐儿;这个剧场有五千个坐儿;坐上", "t": "座席上"}, {"w": "坐上客", "t": "座席上的宾客。"}]}, {"meaning": "因为;由于。", "cites": [{"t": "停车坐爱枫林晚。", "b": "杜牧《山行》"}, {"t": "但坐观罗敷。", "b": "《乐府诗集·陌上桑》"}, {"t": "坐谪兴国州判官。", "b": "《明史》"}], "words": [{"w": "坐此解职;坐是", "t": "因是之故,因此"}, {"w": "坐怀", "t": "因念,因而想到。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('798wx','谷','1','gǔ yù','谷','7','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。甲骨文字形,上面的部分象水形而不全,表示刚从山中出洞而尚未成流的泉脉;下面象谷口。“谷”是汉字部首之一。本义:两山之间狭长而有出口的低地,往往包含一个流域)。"}, {"meaning": "同本义。", "cites": [{"t": "水注谿曰谷。", "b": "《尔雅·释水》"}, {"t": "无障谷。", "b": "《公羊传·僖公三年》"}, {"t": "川谷径复。", "b": "《楚辞·招魂》"}, {"t": "含谿怀谷。", "b": "《文选·左思·蜀都赋》"}, {"t": "当余之从师也,负箧曳屣,行深山巨谷中。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "向斜谷;裂谷;山谷;河谷;峡谷;幽谷;谷口", "t": "两山之间的入口"}, {"w": "谷水", "t": "山谷的水。"}]}, {"meaning": "两山之间的水流。", "cites": [{"t": "泉出通川为谷。", "b": "《说文》"}, {"t": "阳谷皆入汶,阴谷皆入济。", "b": "清·姚鼐《惜抱轩全集》卷十四"}], "words": [{"w": "谷饮", "t": "汲谷水而饮"}, {"w": "谷泉", "t": "山谷间所出的泉水。"}]}, {"meaning": "泛指水流。", "cites": [{"t": "为大川广谷之不可济,于是利为舟楫。", "b": "《墨子》"}]}, {"meaning": "困穷 。引申为困境。", "cites": [{"t": "人亦有言,进退维谷。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "进退维谷", "t": "形容处境非常困难。"}]}, {"meaning": "谷类植物或粮食作物的总称。", "cites": [{"t": "穀,百谷之总名。从禾,穀声。", "b": "《说文》。百谷者,稻粱菽各二十;蔬果助谷各二十也。”"}, {"t": "五至,以谷俱来。", "b": "《书·太古誓》。郑注:“盖牟麦也。”"}, {"t": "亟(同“急”)其乘屋,其始播百谷。", "b": "《诗·豳风·七月》"}, {"t": "四体不勤,五谷不分。", "b": "《论语·微子》"}, {"t": "时人不识农家苦,将谓田中谷自生。", "b": "颜仁郁《农家》"}], "words": [{"w": "五谷;谷田;谷人", "t": "农夫"}, {"w": "谷入", "t": "禾稼的收获"}, {"w": "谷土", "t": "耕地"}, {"w": "谷芒", "t": "禾谷的芒刺"}, {"w": "谷道", "t": "古代方士不吃五谷,以求长生不老的道术。"}]}, {"meaning": "即稻谷。未脱壳的水稻的子实。", "cites": [{"t": "这两天的价钱是糙米五块,谷三块。", "b": "《多收了三五斗》"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "——“吐谷浑”(Tǔyùhún):我国古代西部民族名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('799wx','妥','1','tuǒ','女','7','','[{"pinyin": "tuǒ", "defs": [{"meaning": "(会意。从爪女。爪指手。意思是得到了女子,就安稳、安定了。本义:安稳,安定)。"}, {"meaning": "同本义。", "cites": [{"t": "妥,安也。", "b": "《说文》"}, {"t": "以妥以侑。", "b": "《诗·小雅·楚茨》"}, {"t": "诏妥尸。", "b": "《礼记·郊特性》"}, {"t": "妥而后传言。", "b": "《仪视·士相见礼》"}], "words": [{"w": "妥密", "t": "稳妥机密"}, {"w": "妥安", "t": "稳定"}, {"w": "妥妥", "t": "安定貌"}, {"w": "妥帖", "t": "安定;平静;稳当"}, {"w": "妥洽", "t": "稳妥合适"}, {"w": "妥干", "t": "稳妥干练"}, {"w": "妥绥", "t": "安定"}, {"w": "妥宁", "t": "安宁。"}]}, {"meaning": "落下,掉下。", "cites": [{"t": "花妥莺捎蝶。", "b": "杜甫《重过何氏》"}]}, {"meaning": "停止。", "cites": [{"t": "妥,止也。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('800wx','含','1','hán hàn','口','7','','[{"pinyin": "hán", "defs": [{"meaning": "(形声。从口,今声。本义:含在嘴里)。"}, {"meaning": "同本义。", "cites": [{"t": "含,嗛也。", "b": "《说文》"}, {"t": "含,口也,合口亭之也。衔亦然也。", "b": "《释名·释饮食》"}, {"t": "含哺而熙,鼓腹而游。", "b": "《庄子·马蹄》"}, {"t": "生不布施,死何含珠为?", "b": "《庄子·外物》"}, {"t": "含杜若,握玉环。", "b": "《韩非子·内储说下》"}, {"t": "吾但当含饴弄孙。", "b": "《后汉书·明德马皇后传》"}, {"t": "口如含朱丹。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "儿含乳啼。", "b": "《虞初新志·秋声诗自序》"}, {"t": "含乳啼声。", "b": ""}], "words": [{"w": "含哺", "t": "口衔食物"}, {"w": "含殓", "t": "含口;含口垫背。死人入殓时,把珍珠等物放在死人嘴里,叫“含口”。把金钱放在死人身下,叫“垫背”"}, {"w": "含咀", "t": "衔在口中咀嚼。比喻品味。"}]}, {"meaning": "容纳;包含。", "cites": [{"t": "阿女含泪答。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "含有音乐。", "b": "蔡元培《图画》"}, {"t": "含文学之趣味。", "b": ""}, {"t": "为之含悲。", "b": "孙文《序》"}], "words": [{"w": "含元", "t": "包含万物的本原;包含元气"}, {"w": "含气", "t": "含藏元气"}, {"w": "含孕", "t": "包含;孕育"}, {"w": "含光", "t": "内藏光采,包藏美德。"}]}, {"meaning": "怀着不露;隐藏在内。", "cites": [{"t": "少年别有赠,含笑看吴钩。", "b": "杜甫《后出塞五首》"}, {"t": "使渠弥含憎惧死以侥幸。", "b": "《韩非子·难囚》"}], "words": [{"w": "含哀", "t": "怀着哀痛之情"}, {"w": "含戚", "t": "怀着忧伤"}, {"w": "含道", "t": "怀藏正道;抱有主张"}, {"w": "含愁", "t": "怀着愁苦"}, {"w": "含伤", "t": "怀着悲伤。"}]}]}, {"pinyin": "hàn", "defs": [{"meaning": "古时丧葬时放在死人口里的珠玉 。天子用玉,诸侯用璧,士用米贝。", "cites": [{"t": "王使荣叔归含且赗。", "b": "《左传·文公五年《释文》:含作唅。《说文》作琀。"}, {"t": "大丧共(供)含玉。", "b": "《周礼·天官·玉府》"}, {"t": "含者何,口实也。", "b": "《公羊传·文公五年》"}, {"t": "贝玉曰含。", "b": "《谷梁传·隐公元年》"}, {"t": "死则不得饭含。", "b": "《战国策·赵策三》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('801wx','邻','1','lín','阝','7','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从邑,粦(lìn)声。从“邑”,表示与行政区域有关。本义:古代的一种居民组织。五家为邻)。"}, {"meaning": "周朝地方基层组织的户口单位。", "cites": [{"t": "邻,五家为邻。", "b": "《说文》"}, {"t": "五家为邻,五邻为里。", "b": "《周礼·地官·遂人》"}, {"t": "渔翁家苇间,蜗舍无邻伍。", "b": "陈造《泊慈湖北岸》"}], "words": [{"w": "邻伍", "t": "古制一邻有五家,五家为伍,故称邻伍"}, {"w": "邻里", "t": ""}]}, {"meaning": "相连接的家户。邻居;邻国。", "cites": [{"t": "东邻杀牛。", "b": "《礼记·坊记》"}, {"t": "武义动于南邻。", "b": "《汉书·扬雄传》"}, {"t": "邻人京城氏。", "b": "《列子·汤问》"}, {"t": "其邻人之父。", "b": "《韩非子·说难》"}, {"t": "邻有敝舆。", "b": "《墨子·公输》"}, {"t": "邻有短褐。", "b": "《墨子·公输》"}, {"t": "恃交援而简近邻,怙强大之救,而侮所迫之国者,可亡也。", "b": "《韩非子·亡征》"}], "words": [{"w": "邻党", "t": "邻里乡亲"}, {"w": "邻佑", "t": "邻右。邻居"}, {"w": "邻舍家", "t": "邻比。邻居"}, {"w": "邻曲", "t": "邻居,左邻右舍的人。"}]}, {"meaning": "磷火。", "cites": [{"t": "马血之为转邻也。", "b": "《列子·天瑞》"}]}, {"meaning": "五家为一组,彼此相距不远,因此引申为邻近;近邻。", "cites": [{"t": "五家谓伍,又谓之邻。邻,连也,相接也。", "b": "《释名·释州国》"}, {"t": "邻,近也。", "b": "《小尔雅》"}, {"t": "臣哉邻哉。", "b": "《书·益稷》"}, {"t": "恰比其邻。", "b": "《诗·小雅·正月》"}, {"t": "善谋邻国敌也。", "b": "《汉书·新序》"}, {"t": "海内存知己,天涯若比邻。", "b": "唐·王勃诗"}, {"t": "邻有西塾。", "b": "清·周容《芋老人传》"}, {"t": "与国邻接。", "b": "《资治通鉴》"}], "words": [{"w": "邻敌", "t": "邻近的敌国"}, {"w": "邻境", "t": "地域相接"}, {"w": "邻村", "t": "邻近的村舍"}, {"w": "邻近", "t": "接近;靠近,在附近。"}]}, {"meaning": "位置很接近,邻近。", "cites": [{"t": "荆州与国邻接,江山险固,沃野千里。", "b": "《资治通鉴》"}, {"t": "无与福邻,祸乃不存。", "b": "《韩非子·初见秦》"}]}, {"meaning": "顾惜,舍不得。", "cites": [{"t": "谦卑而不邻。", "b": "《盐铁论·刺复》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('802wx','岔','1','chà','山','7','','[{"pinyin": "chà", "defs": [{"meaning": "(会意。从山,从分。本义:山脉分岐的地方)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('803wx','肝','1','gān','月','7','','[{"pinyin": "gān", "defs": [{"meaning": "(形声。从肉,干声。本义:肝脏)。"}, {"meaning": "同本义。", "cites": [{"t": "肝,木藏也。", "b": "《说文》"}, {"t": "肝,榦也。于五行属木,故其体状有枝干。", "b": "《释名·释形体》"}, {"t": "赞以肝从。", "b": "《仪礼·士昏礼》"}, {"t": "祭先肝。", "b": "《礼记·月令》"}, {"t": "吾师肺肝,皆铁石所铸造也。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "肝肺", "t": "肝与肺"}, {"w": "肝鬲", "t": "体内的肝和膈。鬲,通“膈”,即横膈膜"}, {"w": "肝脑", "t": "肝与脑"}, {"w": "肝木", "t": "即肝。中医以五行之说释五脏,肝属木,故称。"}]}, {"meaning": "比喻人的内心。", "cites": [{"t": "聊为《义鹘行》,永激壮士肝。", "b": "唐·杜甫《义鹘行》"}], "words": [{"w": "肝怀", "t": "内心"}, {"w": "肝心", "t": "比喻人的内心"}, {"w": "肝血", "t": "比喻赤诚之心"}, {"w": "肝脾", "t": "比喻内心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('804wx','肛','1','gāng','月','7','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从肉,工声。本义:肛门)。"}, {"meaning": "同本义。", "cites": [{"t": "肛,肛门。", "b": "《集韵》"}, {"t": "“大肠端,肛门也。”", "b": "《六书故》"}]}, {"meaning": "肛管和肛门的总称。", "cites": [{"t": "脱肛属气热、气虚、血虚、血热。", "b": "明·朱震享《丹溪先生心法·脱肛》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('805wx','肚','1','dù dǔ','月','7','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从肉,土声。本义:人或动物的腹部)。", "words": [{"w": "牵肠挂肚", "t": "挂念，不放心"}]}, {"meaning": "器物下面的中心部分"}, {"meaning": "圆而凸起像肚子的"}]}, {"pinyin": "dǔ", "defs": [{"meaning": "供食用的动物的胃。", "words": [{"w": "猪肚", "t": ""}, {"w": "牛肚", "t": ""}, {"w": "羊肚", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('806wx','肘','1','zhǒu','月','7','','[{"pinyin": "zhǒu", "defs": [{"meaning": "(会意。从肉从寸,寸,腕下“寸口”部位。点明肘所在的范围。本义:上下臂相接处可以弯曲的部位)同本义。", "cites": [{"t": "肘,臂节也。", "b": "《说文》"}]}, {"meaning": "肘者,肱与臂相接处。", "cites": [{"t": "反诎之,及肘。", "b": "《礼记·深衣》。注:“肘或为腕。”"}, {"t": "俄而柳生其左肘。", "b": "《庄子·至乐》"}, {"t": "自始合,而矢贯余手及肘。", "b": "《左传》"}], "words": [{"w": "肘膊", "t": "手臂。比喻得力的助手"}, {"w": "肘弯", "t": "肘关节部位"}, {"w": "肘翼", "t": "胳膊肘和羽翼,比喻切近之地"}, {"w": "肘臂", "t": "臂膀。比喻亲信;爪牙"}, {"w": "肘腕", "t": "肘关节向里凹下去的地方"}, {"w": "肘行", "t": "以肘前行,表示畏服"}, {"w": "肘行膝步", "t": "匍匐前行,表示虔诚或哀戚。"}]}, {"meaning": "用肘触人示意;拉住肘部。", "cites": [{"t": "柴俯不对,女肘之,柴始强颜笑。", "b": "《聊斋志异》"}], "words": [{"w": "肘掣", "t": "拉住胳膊。比喻牵制或留难"}, {"w": "肘足", "t": "以肘触肘,以足蹑足。比喻暗中示意,互结其谋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('807wx','肠','1','cháng','月','7','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从肉,昜(yáng)声。本义:人和动物消化器官之一)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('808wx','龟','1','guī jūn qiū','刀','7','','[{"pinyin": "guī", "defs": [{"meaning": "(象形。甲骨文字形,头象它(蛇)头,左象足,右象甲壳,下面象尾。本义:乌龟)。"}, {"meaning": "即金龟,亦称乌龟 。一种龟属动物(Chinemys reevesii),头、颈侧面有黄色线状斑纹,背甲有三条纵走的隆起,后缘不呈锯齿状,雄体背部黑色,雌体呈棕色,腹面略带黄色,均有暗褐色斑纹,四肢较扁平,有爪,指、趾间具全蹼,产于中国、朝鲜和日本,其腹甲可入药。", "cites": [{"t": "文体有六篆,巧妙入神,或象龟文,或比龙鳞。", "b": "汉·蔡邕《篆势》"}], "words": [{"w": "龟文", "t": "龟背所现的纹理"}, {"w": "龟王", "t": "指龟类中的王者"}, {"w": "龟龙", "t": "古人以龟、龙、麟、凤合称四灵"}, {"w": "龟蛇", "t": "龟和蛇。"}]}, {"meaning": "龟甲。", "cites": [{"t": "虎兕出于柙,龟玉毁于椟中,是谁之过与?", "b": "《论语·季氏》"}, {"t": "合龟兆,视吉凶,观星辰风去之变,欲以成胜立功,臣以为难。", "b": "《尉缭子·武议》"}], "words": [{"w": "龟玉", "t": "龟甲和宝玉。古时并为国家重器"}, {"w": "龟坼", "t": "天旱地裂,纹如龟甲"}, {"w": "龟筒", "t": "大龟甲、龟壳"}, {"w": "龟灼", "t": "用火灼龟甲。比喻才智之士容易招损"}, {"w": "龟卜", "t": "灼龟甲来预卜吉凶,是古时占卜的一种方法"}, {"w": "龟兆", "t": "古时占卜时显现在龟甲上可借以预测吉凶的兆纹"}, {"w": "龟骨", "t": "古时用于占卜的龟甲"}, {"w": "龟筮", "t": "即卜筮。古代卜用龟甲,筮用蓍草"}, {"w": "龟贝", "t": "古货币名。"}]}, {"meaning": "男生殖器。", "cites": [{"t": "今老爹…大身材,一表人物,也曾吃药养龟。", "b": "《金瓶梅词话》"}]}, {"meaning": "(jūn)。皮肤冻裂。"}, {"meaning": "高隆。", "cites": [{"t": "新安王伯固,字牢之,世祖之第五子也,生而龟胸,目通睛扬白。", "b": "《陈书·新安王伯固传》"}], "words": [{"w": "龟胸", "t": "胸骨凸起,状似龟背。即鸡胸。"}]}, {"meaning": "比喻高寿。", "cites": [{"t": "坐享龟龄鹤,稳佩金鱼玉带,常近赭黄袍。", "b": "宋·侯寘《水调歌头·为郑子礼提刑寿》"}, {"t": "借向蜉蝣辈,宁知龟鹤年。", "b": "晋·郭璞《游仙》"}], "words": [{"w": "龟寿", "t": "比喻高寿"}, {"w": "龟鹄", "t": "龟和鹄。比喻长寿"}, {"w": "龟龄", "t": "比喻长寿"}, {"w": "龟龄鹤寿", "t": "比喻人高寿"}, {"w": "龟鹤遐寿", "t": "比喻长寿。"}]}]}, {"pinyin": "jūn", "defs": [{"meaning": "手足的皮肤冻裂。", "cites": [{"t": "视衍沃而龟坼,沉高田之未耰。", "b": "王炎《喜雨赋》"}], "words": [{"w": "龟裂;龟手", "t": "手上皮肤冻裂"}, {"w": "龟坼", "t": "手足皮肤冻裂"}, {"w": "龟纹", "t": "冻裂而成的纹。"}]}]}, {"pinyin": "qiū", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('809wx','甸','1','diàn','田','7','','[{"pinyin": "diàn", "defs": [{"meaning": "(会意。从田,包省声,田亦声。本义:王田)。"}, {"meaning": "古时都城的郭外称郊,郊外称甸。", "cites": [{"t": "甸,天子五百里地。", "b": "《说文》。段注:“甸,王田也。”"}, {"t": "五百里甸服。", "b": "《书·禹贡》。注:“为天子服治田也。”"}, {"t": "千里之内曰甸。", "b": "《礼制·王制》"}, {"t": "甸服。", "b": "《周礼·夏官·职方式》。注:“甸,田也。治田入谷也。”"}], "words": [{"w": "甸地;甸邑;甸服", "t": "古制称离王城五百里的区域;泛指京城附近的地方"}, {"w": "甸畿", "t": "古代九畿之一。京畿方千里称国畿。其外方五百里,称侯畿;又其外方五百里称畿。"}]}, {"meaning": "田野。", "cites": [{"t": "潮平见楚甸,天际望维扬。", "b": "唐·刘希夷《江南曲》"}]}, {"meaning": "田野出产物。", "words": [{"w": "甸粟", "t": "京畿王田生产的谷物"}, {"w": "甸役", "t": "田猎的力役"}, {"w": "甸祝", "t": "古官名。周礼春官之属,掌管四时田猎祭祀之事。"}]}, {"meaning": "古代管理柴薪的官。", "cites": [{"t": "诸侯宾至,甸设庭燎。", "b": "《左传》"}]}, {"meaning": "甸师,古代管理田事的官。", "cites": [{"t": "甸粟而纳之三宫。", "b": "《谷梁传·桓公十四年》。注:“甸,甸师,掌田之官也。”"}], "words": [{"w": "甸人", "t": "古官名。掌管藉田及供野物等事务"}, {"w": "甸师", "t": "即甸人"}, {"w": "甸官", "t": "甸畿官署。"}]}, {"meaning": "治理。", "cites": [{"t": "维禹甸之。", "b": "《诗·小雅·信南山》"}], "words": [{"w": "甸邑", "t": "治理县邑。"}]}, {"meaning": "挺。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('810wx','免','1','miǎn wèn','刀','7','','[{"pinyin": "miǎn", "defs": [{"meaning": "(会意。金文字形,下面是“人”,上面象人头上戴帽形,是冠冕的“冕”本字。由于假借为“免除”义,另造“冕”字。假借义:免除,避免)。"}, {"meaning": "脱掉;脱落。", "cites": [{"t": "免,脱也。", "b": "《广雅·释诂四》"}, {"t": "左右免胄而下。", "b": "《国语·周语中》"}, {"t": "其将不免乎!", "b": "《左传·襄公十年》"}, {"t": "免使者而复鼓。", "b": "《左传·成公十六年》"}, {"t": "免胄而听命。", "b": "《国语·晋语六》"}, {"t": "秦师过周北门,左右免胄而下。", "b": "《左传·僖公三十三年》"}, {"t": "谓身不死得免去皮肤也?", "b": "《论衡·道虚》"}], "words": [{"w": "免胄", "t": "脱下头盔"}, {"w": "免丧", "t": "脱去丧服"}, {"w": "免绖", "t": "脱去麻带而仅着丧服。"}]}, {"meaning": "赦免,释放。", "cites": [{"t": "暂而免诸国。", "b": "《左传·僖公三十三年》"}, {"t": "因而获免。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "惠而免之;免囚", "t": "被赦免的囚犯"}, {"w": "免坐", "t": "对罪犯亲属免予治罪"}, {"w": "免放", "t": "释放"}, {"w": "免赦", "t": "赦免。"}]}, {"meaning": "逃避灾难或罪过。", "cites": [{"t": "诚得如此,臣免死罪矣。", "b": "《韩非子·内储说上》"}, {"t": "以免于难。", "b": "《国语·晋语》"}, {"t": "于溷藩以免。", "b": "明·张溥《五人墓碑记》"}, {"t": "即免死。", "b": "清·方苞《狱中杂记》"}, {"t": "五国既丧,齐亦不免。", "b": "宋·苏洵《六国论》"}, {"t": "或能免乎。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "免却", "t": "避免,防止"}, {"w": "免身", "t": "脱身免祸。"}]}, {"meaning": "去掉;除掉。", "cites": [{"t": "了缘道:“这也容易。但我的徒弟乃新出家的,这个可以免得。望列位做个人情。”", "b": "《醒世恒言》"}], "words": [{"w": "免虑", "t": "免得挂念"}, {"w": "免试;免学费;免俗", "t": "不拘世俗常情"}, {"w": "免责", "t": "不受责备"}, {"w": "免掉", "t": "消除,除去。"}]}, {"meaning": "罢黜。", "cites": [{"t": "遂免丞相勃。", "b": "《汉书·文帝纪》"}, {"t": "宰说,免成役。", "b": "《聊斋志异·促织》"}, {"t": "多自免去。", "b": "《明史》"}], "words": [{"w": "免去", "t": "免除"}, {"w": "免册", "t": "罢免的册书"}, {"w": "免臣", "t": "被罢官的人"}, {"w": "免退", "t": "撤职。"}]}, {"meaning": "生孩子。同“娩”。", "cites": [{"t": "将免者以告。", "b": "《国语·越语上》"}, {"t": "妇人免乳大故。", "b": "《汉书·外戚传上》"}, {"t": "朔妇免身生男。", "b": "《史记·赵世家》"}], "words": [{"w": "免身", "t": "分娩"}, {"w": "免乳", "t": "分娩。"}]}, {"meaning": "分开;分离;别离。", "cites": [{"t": "是以不免于欲利之心。", "b": "《韩非子·解老》"}, {"t": "子生三年,然后免于父母之怀。", "b": "《论语·阳货》"}]}, {"meaning": "低头。", "cites": [{"t": "冯忌接手免首,欲言而不敢。", "b": "《战国策·赵策四》"}]}, {"meaning": "努力,尽力。", "cites": [{"t": "使百吏免尽。", "b": "《荀子·王制》"}, {"t": "免耕杀匿,使农事得。", "b": "《吕氏春秋·辩士》"}]}]}, {"pinyin": "wèn", "defs": [{"meaning": "物之新生、稚弱者。", "cites": [{"t": "推远稚免之幼志,崇积文武之宠德。", "b": "《大戴礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('811wx','狂','1','kuáng','犭','7','','[{"pinyin": "kuáng", "defs": [{"meaning": "(形声。本义:狗发疯)。"}, {"meaning": "同本义。也指狗发疯。", "cites": [{"t": "狂,狾犬也。", "b": "《说文》"}, {"t": "值狂犬之暴怒,加楚害于微躯。", "b": "三国魏·阮籍《鸠赋》"}], "words": [{"w": "狂犬", "t": "凶猛的狗。"}]}, {"meaning": "引申指“人的精神失常”,“疯癫”。", "cites": [{"t": "狂夫瞿瞿。", "b": "《诗·齐风·东方未明》"}, {"t": "狂走者累日。", "b": "唐·柳宗元《柳河东集》"}, {"t": "漫卷诗书喜欲狂。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "忽忽如狂。", "b": "《汉书·李广苏建传》"}, {"t": "佯狂不知所之者。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "狂死", "t": "因疯疾致死"}, {"w": "狂易", "t": "精神失常"}, {"w": "狂惑", "t": "精神错乱;疯癫"}, {"w": "狂徒", "t": "狂人。"}]}, {"meaning": "狂妄。", "cites": [{"t": "幼而狂。", "b": "《左传·昭公二十三年》"}, {"t": "其蔽也狂。", "b": "《论语》。注:“妄抵触人。”"}, {"t": "愈以是得狂名。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "狂谬", "t": "狂妄荒谬"}, {"w": "狂且", "t": "行动轻狂之人"}, {"w": "狂乖", "t": "狂妄狡猾"}, {"w": "狂纵", "t": "狂妄放肆"}, {"w": "狂轻", "t": "狂妄而轻浮"}, {"w": "狂悖", "t": "狂妄背理;猖獗"}, {"w": "狂且", "t": "行动轻狂"}, {"w": "狂话", "t": "狂妄的话"}, {"w": "狂狡", "t": "狂妄狡诈"}, {"w": "狂戾", "t": "狂妄暴戾"}, {"w": "狂惑", "t": "狂妄昏惑。"}]}, {"meaning": "狂放,任性放荡。", "cites": [{"t": "狂夫之言,圣人择之。", "b": "清·刘开《问说》"}], "words": [{"w": "狂士", "t": "狂放的读书人"}, {"w": "狂朋怪侣", "t": "行为狂放不循常轨的朋友"}, {"w": "狂态", "t": "狂放的态度。"}]}, {"meaning": "凶猛。", "cites": [{"t": "狂风吹古月。", "b": "李白《司马将军歌》"}], "words": [{"w": "狂风毒雨", "t": "狂风暴雨。"}]}, {"meaning": "汹涌。", "cites": [{"t": "挽狂澜于既倒。", "b": "韩愈《进学解》"}], "words": [{"w": "狂涛", "t": "汹涌的波涛"}, {"w": "狂浪", "t": "汹涌的浪涛"}, {"w": "狂流", "t": "汹涌的水波。"}]}, {"meaning": "欺骗。", "cites": [{"t": "吾以是狂而不信也。", "b": "《庄子·逍遥游》"}, {"t": "使子必智而寿,则世必以为狂。", "b": "《韩非子·显学》"}]}, {"meaning": "(wǎng)。去。", "cites": [{"t": "我其发出狂。", "b": "《书·微子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('812wx','犹','1','yóu','犭','7','','[{"pinyin": "yóu", "defs": [{"meaning": "(形声。从犬,酋(尤)声。本义:一种猿类动物)。"}, {"meaning": "兽名。猴属,也叫“犹猢”,形如麂。", "cites": [{"t": "猶,愑属。", "b": "《说文》。字亦作猷。"}, {"t": "犹如麂,善登木。", "b": "《尔雅》"}, {"t": "犹,五尺大犬也。", "b": "《释文》引《尸子》"}, {"t": "犹,兽名也。", "b": "《颜氏家训·书证》"}, {"t": "犹与未决。", "b": "《史记·吕后纪》。索隐:“犹,猿类也。夘鼻长尾 ,性多疑。”"}, {"t": "山多犹猢,似猴而短足好游崖树,一腾百步,或三百丈,顺往倒返,乘空若飞。", "b": "《水经注》"}]}, {"meaning": "犬子。", "cites": [{"t": "犹,《说文》:“陇西谓犬子为犹。”", "b": "《集韵》"}]}, {"meaning": "如同。好比。", "cites": [{"t": "此犹文轩之与敝舆。", "b": "《墨子·公输》"}, {"t": "梁肉之与糠糟。", "b": ""}, {"t": "此犹锦绣之与短褐。", "b": ""}, {"t": "今之乐犹古之乐也。", "b": "《孟子·梁惠王下》"}, {"t": "犹鱼之有水也。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "犹子", "t": "如同儿子"}, {"w": "犹父", "t": "如同父亲"}, {"w": "犹龙", "t": "道之高深奇妙,如龙之变化不可测"}, {"w": "犹言", "t": "好比说;等于说"}, {"w": "过犹不及", "t": ""}]}, {"meaning": "踌躇疑惧。", "cites": [{"t": "心犹嶑而狐疑。", "b": "《离骚》"}, {"t": "豫兮若冬涉川,犹兮若畏四邻。", "b": "《老子》"}], "words": [{"w": "犹预", "t": "犹与。犹夷。犹豫"}, {"w": "犹犹", "t": "迟疑不决。"}]}, {"meaning": "谋画。", "cites": [{"t": "克壮其犹。", "b": "《诗·小雅·采芑》"}, {"t": "犹来无弃。", "b": "《诗·魏风·陟岵》"}, {"t": "王犹充塞。", "b": "《荀子·议兵》"}]}, {"meaning": "还;仍然 。多用于书面语。", "cites": [{"t": "犹不失下曹从事。", "b": "《资治通鉴》"}, {"t": "犹得备晨炊。", "b": "唐·杜甫《石壕吏》"}, {"t": "余寒犹厉。", "b": "明·袁宏道《满井游记》"}, {"t": "吾数年来欲买舟而下,犹未能也。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "不说犹可,一说他反而更有意见了;此事他犹不知,何况我呢;记忆犹新", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('813wx','狈','1','bèi','犭','7','','[{"pinyin": "bèi", "defs": [{"meaning": "传说中的一种兽,狼属。前腿特别短,走路时要爬在狼身上,没有狼,它就不能行动,所以用狼狈形容困苦或受窘的样子 。“狼狈为奸”:互相勾结做坏事。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('814wx','角','1','jiǎo jué','角','7','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(象形。甲骨文字形,象兽角形。本义:动物的角)。"}, {"meaning": "同本义。", "cites": [{"t": "角,兽角也。", "b": "《说文》"}, {"t": "麟之角。", "b": "《诗·周南·麟之趾》"}, {"t": "北方之美者,有幽都之筋角焉。—《尔雅·释地》", "b": ""}, {"t": "旃裘筋角。", "b": "《史记·货殖列传》"}, {"t": "大小毛角。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "角灯", "t": "用透明角质物做罩的灯"}, {"w": "角带", "t": "缀有角质饰物的腰带"}, {"w": "角弓", "t": "用兽角作装饰的硬弓"}, {"w": "角枕", "t": "以兽角来装饰的枕头"}, {"w": "角马", "t": "马头上生角。比喻违反常态"}, {"w": "角节", "t": "用犀角做的符节。"}]}, {"meaning": "突起的额骨。", "cites": [{"t": "恶角犀丰盈。", "b": "《国语·郑语》"}], "words": [{"w": "角犀", "t": "额角近头发边缘,隐然隆起,有如伏犀,称为角犀"}, {"w": "角崩", "t": "以头叩地。"}]}, {"meaning": "古代未成年的人,头顶两侧束发为髻,状如牛角,故称角。", "cites": [{"t": "男角女羁。", "b": "《礼记·内则》"}], "words": [{"w": "角儿", "t": "头顶向上竖起的发髻"}, {"w": "总角;角髻", "t": "古代童稚的发髻。状如牛角"}, {"w": "角发", "t": "束发如角状"}, {"w": "角婢", "t": "少婢。束发如角。"}]}, {"meaning": "角落。", "cites": [{"t": "四角垂香囊。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "四角龙子幡。", "b": ""}], "words": [{"w": "门角;拐角;墙角;角子", "t": "角落;阁子,小屋;饺子"}, {"w": "角子门", "t": "侧门,边门"}, {"w": "角睐", "t": "用眼角斜视"}, {"w": "角隅", "t": "角落。"}]}, {"meaning": "号角。", "cites": [{"t": "四面边声连角起。", "b": "宋·范仲淹《渔家傲》"}, {"t": "清角吹寒。", "b": "宋·姜夔《扬州慢》"}]}, {"meaning": "古时平斗斛的工具。", "cites": [{"t": "角之而知有余不足之处。", "b": "《孙子兵法·虚实篇》"}, {"t": "尺寸也、绳墨也,……,角量也,谓之法。", "b": "《管子·七法》"}]}, {"meaning": "古代量器名。", "cites": [{"t": "一角一散。", "b": "《特牲馈食礼》。注:“角四升。”"}, {"t": "斗,斛也,角,量也。", "b": "《管子》"}, {"t": "鲁达道:“先打四角酒来。”", "b": "《水浒传》"}]}]}, {"pinyin": "jué", "defs": [{"meaning": "古代盛酒的器具。青铜制。形似爵而无柱与流,两尾对称,有盖,用以温酒和盛酒。", "cites": [{"t": "一角一散。", "b": "《仪礼·特牲馈食礼》。注:“角四升,疑古酒器之始,以角为之。”"}, {"t": "宗庙之祭,尊者举觯,卑者举角。", "b": "《礼记·礼器》"}]}, {"meaning": "比试;竞争。", "cites": [{"t": "陛下之与诸公,非亲角材之臣之也。", "b": "《汉书·贾谊传》"}, {"t": "作角抵戏。", "b": "《汉书·武帝纪》"}, {"t": "肆射御角力。", "b": "《吕氏春秋·孟冬》。注:“犹试也。”"}, {"t": "日与子弟角。", "b": "《聊斋志异·促织》"}], "words": [{"w": "角试", "t": "通过比赛成绩比较优劣"}, {"w": "解力", "t": "比赛武力;动武"}, {"w": "口角", "t": "争吵;斗嘴。"}]}, {"meaning": "衡量,考察。", "cites": [{"t": "角斗甬。", "b": "《礼记·月令》。注:“谓平之也。”"}, {"t": "角之,而知有余不足之处。", "b": "《孙子》。曹操注:“角,量也。”"}, {"t": "陛下之与诸公,非亲角材而臣之也。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('815wx','删','1','shān','刂','7','','[{"pinyin": "shān", "defs": [{"meaning": "(会意。从刀从册。册是简册,把若干竹简编穿在一起叫“册”。简册的内容有问题,就用刀除掉,所以从“刀”。本义:削除)。"}, {"meaning": "削除;勾划掉。", "cites": [{"t": "删,剟也。", "b": "《说文》"}, {"t": "删,除也。", "b": "《三苍》"}, {"t": "删,定也。", "b": "《声类》"}, {"t": "删,刊也。", "b": "《汉书·刑法志》注"}, {"t": "删,削也。", "b": "《汉书·丙吉传》注"}, {"t": "又不可以使天下之民,斫直、删密、锄正,以夭梅病梅为业以求钱也。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "增删", "t": "增加和删去"}, {"w": "删存", "t": "经过删除保留下来"}, {"w": "删裁", "t": "删除"}, {"w": "删弃", "t": "删除,删去"}, {"w": "删割", "t": "删去"}, {"w": "删繁", "t": "删除繁冗之言"}, {"w": "删抹", "t": "删除,勾掉。"}]}, {"meaning": "选录,抄录或摘引。", "cites": [{"t": "删诗为三百篇。", "b": "《书·孔序》"}, {"t": "今删其要,以备篇籍。", "b": "《汉书·艺文志》"}], "words": [{"w": "删本", "t": "经过删节的版本"}, {"w": "删要", "t": "加以删削留取精要。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('816wx','条','1','tiáo','木','7','','[{"pinyin": "tiáo", "defs": [{"meaning": "(形声。从木,攸(yōu)声。本义:小枝)。"}, {"meaning": "同本义。", "cites": [{"t": "条,小枝 也。", "b": "《说文》"}, {"t": "桑柳丑条。", "b": "《尔雅》"}, {"t": "遵彼汝坟,伐其条枚。", "b": "《诗·周南·汝坟》"}, {"t": "高柯擢条干,远眺同天色。", "b": "陶潜《联句》"}, {"t": "疏条交映。", "b": "吴均《与朱元思书》"}, {"t": "柳条将舒。", "b": "明·袁宏道《满井游记》"}, {"t": "养其旁条。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "条枚", "t": "枝干"}, {"w": "条枝", "t": "树枝"}, {"w": "条柯", "t": "枝条"}, {"w": "条修叶贯", "t": "枝长叶连。比喻有条理、有系统"}, {"w": "条叶", "t": "枝叶。比喻分支;支派"}, {"w": "条蔓", "t": "枝蔓"}, {"w": "条干", "t": "枝干。"}]}, {"meaning": "泛指一般长条形的物体。", "cites": [{"t": "缕条紧而贯矩,针鼻细而穿中。", "b": "北周·庾信《七夕赋》"}], "words": [{"w": "长条巨幅;口条", "t": "用作食品的猪舌或牛舌"}, {"w": "发条;肋条;齿条;苗条;炉条;毡条;通条;辐条;布条", "t": ""}]}, {"meaning": "条款;项目。", "cites": [{"t": "科条既备,民多伪态。", "b": "《战国策·秦策》"}], "words": [{"w": "条会", "t": "条目大纲"}, {"w": "条领", "t": "条目要领"}, {"w": "条汇", "t": "条目类别"}, {"w": "条秩", "t": "条目次第。"}]}, {"meaning": "条理;次序。", "cites": [{"t": "若网在纲,有条而不紊。", "b": "《书·盘庚上》"}], "words": [{"w": "有条不紊", "t": ""}]}, {"meaning": "用于长条形的东西。", "words": [{"w": "一条街", "t": "路、公路、铁路"}, {"w": "一条河", "t": "江、沟、渠、小溪"}, {"w": "一条山脉;一条裤子", "t": "裙子"}, {"w": "两条绳子", "t": "带子、鞭子、电线"}, {"w": "在纸上画了三条线;几条口袋", "t": "麻袋"}, {"w": "一条床单", "t": "毯子、被子、被面、被里。"}]}, {"meaning": "引申用于人体。", "words": [{"w": "一条人命;一条好嗓子;要跟群众一条心,不要两条心", "t": ""}]}, {"meaning": "用于某些抽象事物。", "words": [{"w": "一条计策", "t": "妙计"}, {"w": "一条正确路线;两条意见", "t": "建议"}, {"w": "十条罪状;只有一条出路;这一版共有九条新闻", "t": "消息。"}]}, {"meaning": "长方形的 。", "words": [{"w": "条几", "t": "长方形的几案"}, {"w": "条子", "t": "长方形的纸张;便条"}, {"w": "条石;条桌;条褥;条柜;条凳", "t": ""}]}, {"meaning": "长条形的 。", "words": [{"w": "条扇", "t": "裱糊后挂起来的画轴"}, {"w": "条印;条田;条盆;条纹;条幅", "t": ""}]}, {"meaning": "逐条地。逐项地 。", "words": [{"w": "条分节解", "t": "逐条逐节分析"}, {"w": "条析", "t": "逐条辨析"}, {"w": "条呈", "t": "分条陈述的呈文"}, {"w": "条比", "t": "分项排列"}, {"w": "条正", "t": "逐条订正"}, {"w": "条疏,条奏", "t": "逐条上奏。"}]}, {"meaning": "分列条款、条目。", "cites": [{"t": "其余事况,条写如后。", "b": "白居易《与元微之书》"}], "words": [{"w": "条写", "t": "分条书写"}, {"w": "条晰", "t": "分条叙明"}, {"w": "条具", "t": "分条开列"}, {"w": "条述", "t": "分条叙述"}, {"w": "条列", "t": "分条列举"}, {"w": "条白", "t": "分条陈明。"}]}, {"meaning": "通达。", "cites": [{"t": "声气远条。", "b": "《汉书·礼乐志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('817wx','彤','1','tóng','彡','7','','[{"pinyin": "tóng", "defs": [{"meaning": "(会意。从丹,从彡(shān)。丹,丹砂。彡,毛饰。本义:彩色装饰) 同本义。", "cites": [{"t": "彤,丹饰也。", "b": "《说文》"}, {"t": "彤弓一。", "b": "《书·文侯之命》"}, {"t": "诸侯彤弓。", "b": "《荀子·大略》。按:“丹漆也。”"}], "words": [{"w": "彤几", "t": "朱漆几"}, {"w": "彤镂", "t": "涂丹漆和雕刻花纹"}, {"w": "彤辇", "t": "朱漆宫车"}, {"w": "彤壶", "t": "朱漆漏壶"}, {"w": "彤庭", "t": "彤宫,彤殿,彤廷。汉代宫廷。因以朱漆涂饰,故称"}, {"w": "彤车", "t": "朱漆车"}, {"w": "彤弓", "t": "朱漆弓"}, {"w": "彤矢", "t": "朱漆箭"}, {"w": "彤闱", "t": "朱漆宫门。"}]}, {"meaning": "赤色。", "cites": [{"t": "麻冕彤裳。", "b": "《书·顾命》"}, {"t": "贻我彤管。", "b": "《诗·邶风·静女》"}], "words": [{"w": "彤丹", "t": "朱漆"}, {"w": "彤芝盖", "t": "朱伞"}, {"w": "彤彤", "t": "通红貌"}, {"w": "彤珠", "t": "烧红的铁丸。"}]}, {"meaning": "彤管(笔)的简称。", "cites": [{"t": "书笏珥彤,纪言事于仙室。", "b": "《文选·王融·三月三日曲水诗序》"}]}, {"meaning": "周代国名 。在今陕西省华县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('818wx','卵','1','luǎn','卩','7','','[{"pinyin": "luǎn", "defs": [{"meaning": "(象形。小篆字形像卵。本义:卵子,特指蛋)。"}, {"meaning": "蛋。", "cites": [{"t": "卵,凡物无乳者卵生。", "b": "《说文》"}, {"t": "鸟翼鷇卵。", "b": "《国语·鲁语》。注:“未孚曰卵。”"}, {"t": "梁卵焍黄。", "b": "《史记·龟策传》。索隐:“鸡子也。”"}, {"t": "濡鱼卵酱。", "b": "《礼记·内则》"}, {"t": "卵壳孕而雌雄生。", "b": "《论衡》"}, {"t": "风至苕折,卵破子死。", "b": "《荀子·劝学》"}], "words": [{"w": "卵袋", "t": "指长圆形口上有绳可结扎的钱袋"}, {"w": "卵清", "t": "蛋白"}, {"w": "卵用鸡", "t": "以产蛋为主要目的而饲养的鸡种。"}]}, {"meaning": "指动物发育的第一个阶段 。例如完全变态的昆虫(蛾,蝶、蚊、蝇等),有卵、幼虫、蛹和成虫四个阶段。"}, {"meaning": "大。", "cites": [{"t": "桃诸,梅诸,卵盐。", "b": "《礼记·内则》。注:“卵盐,大盐也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('819wx','灸','1','jiǔ','火','7','','[{"pinyin": "jiǔ", "defs": [{"meaning": "(形声。从火,久声。本义:用艾火烧灼。中医的一种疗法)。"}, {"meaning": "同本义。", "cites": [{"t": "灸,灼也。", "b": "《说文》"}, {"t": "所谓不病而灸,无忧而自默。", "b": "向秀《难养生论》"}], "words": [{"w": "灸刺", "t": "艾灸和针刺"}, {"w": "灸客", "t": "接受灸疗的病人"}, {"w": "灸眉", "t": "用艾炷烧灼眉头以治狂疾"}, {"w": "灸师", "t": "以灸术治病的医师。"}]}, {"meaning": "拄,支撑。", "cites": [{"t": "灸诸墙,以眡其桡之均也。", "b": "《周礼》"}]}, {"meaning": "堵塞。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('820wx','岛','1','dǎo','山','7','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从山,鸟声。本义:江、湖、海洋中被水所包围而比大陆要小的一片陆地) 同本义。"}, {"meaning": "字省作“岛”。", "cites": [{"t": "入海居岛中。", "b": "《史记·田儋传》。集解引韦昭:“海中山曰岛。”"}, {"t": "山岛竦峙。", "b": "曹操《步出夏门行》"}, {"t": "英伦诸岛乃属冰天雪海之区。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "岛峙", "t": "似海岛般耸峙"}, {"w": "岛夷", "t": "古指中国东部近海一带及海岛上的居民;南北朝时南北双方封建统治者各以正统自居,互相诋毁,北朝称南朝为岛夷;也指倭寇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('821wx','刨','1','bào páo','刂','7','','[{"pinyin": "bào", "defs": [{"meaning": "推刮木料等，使其平滑的一种工具。", "words": [{"w": "刨床", "t": "推刮金属材料使平滑的机器"}]}]}, {"pinyin": "páo", "defs": [{"meaning": "(形声。从刀,包声。本义:削)。"}, {"meaning": "同本义。", "cites": [{"t": "刨,削也。", "b": "《玉篇》"}]}, {"meaning": "挖掘", "words": [{"w": "刨坑", "t": "解释"}, {"w": "刨根问底", "t": "喻追究底细"}]}, {"meaning": "[口语]减，除去"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('822wx','迎','1','yíng','辶','7','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从辵(chuò)。本义:遇,相逢)。"}, {"meaning": "同本义。", "cites": [{"t": "迎,逢也。", "b": "《说文》。段玉裁注:“夆,悟也;逢,遇也,其理一也。”"}, {"t": "以迎岁于东郊。", "b": "《淮南子·时则》。注:“逆春也。”"}, {"t": "迎日推策。", "b": "《史记·五帝纪》。正义:“逆也。”"}], "words": [{"w": "迎霜", "t": "遇霜。"}]}, {"meaning": "迎接;欢迎。", "cites": [{"t": "冕而亲迎。", "b": "《礼记·昏义》"}, {"t": "亲迎于渭。", "b": "《诗·大雅·大明》"}, {"t": "哀公迎孔子。", "b": "《墨子·非儒下》"}, {"t": "每迎女婿固不遣。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "迎风板子", "t": "迎风。指新官上任,为树权威先访拿数人杖责四十。然后视情节再行发落"}, {"w": "迎猪", "t": "赶猪回家"}, {"w": "迎枕", "t": "迎手。中医号脉时垫在病人腕部的枕头"}, {"w": "迎年", "t": "迎接新年"}, {"w": "迎气", "t": "迎接祭祀五帝,祈求五谷丰收"}, {"w": "迎将", "t": "迎接"}, {"w": "迎劳", "t": "迎接慰劳"}, {"w": "迎新送旧", "t": "迎接新来的,辞送离去的"}, {"w": "迎銮", "t": "迎接皇帝"}, {"w": "迎宾", "t": "迎接宾客。"}]}, {"meaning": "迎合;逢迎。", "cites": [{"t": "则民严而不迎。", "b": "《孔子家语·入官》。注:“奉也。”"}, {"t": "群臣迎阿,独怀道执不可。", "b": "《新唐书》"}], "words": [{"w": "迎阿", "t": "逢迎阿谀"}, {"w": "迎意", "t": "测知他人心意,迎合他人心意"}, {"w": "迎望", "t": "迎合,迎承"}, {"w": "迎时", "t": "迎合时势"}, {"w": "迎逢", "t": "迎合;逢迎"}, {"w": "迎附", "t": "迎合。"}]}, {"meaning": "投降。", "cites": [{"t": "愚谓大计不如迎之。", "b": "宋·司马光《资治通鉴》"}]}, {"meaning": "面向着,正对着。", "cites": [{"t": "迎风收栗子,过雨剪花头。", "b": "明·袁宏道《再和散木韵》"}], "words": [{"w": "迎风飞翔;迎见", "t": "迎面遇见"}, {"w": "迎潮", "t": "逆潮流而上"}, {"w": "迎流", "t": "逆流。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('823wx','饭','1','fàn','饣','7','','[{"pinyin": "fàn", "defs": [{"meaning": "(形声。从食,反声。本义:吃饭)。"}, {"meaning": "同本义。", "cites": [{"t": "饭,食也。", "b": "《说文》"}, {"t": "饭飱者三饭也。", "b": "《礼记·玉藻》"}, {"t": "呼饭饮之。", "b": "《汉书·朱买臣传》"}, {"t": "饭疏食,饮水。", "b": "《论语·述而》"}, {"t": "饭糗(干粮)茹草。", "b": "《孟子·尽心下》"}, {"t": "廉颇老矣,尚能饭否?", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "尚能饭否;饭粥", "t": "吃粥"}, {"w": "饭蔬", "t": "吃蔬菜。"}]}, {"meaning": "给人喂饭或喂牲口。", "cites": [{"t": "有一漂母见信饥,饭信。", "b": "《史记·淮阴侯列传》"}, {"t": "吕望屠于朝歌兮,宁戚歌而饭牛。", "b": "《楚辞·九章·惜往日》"}], "words": [{"w": "饭牛", "t": "饲牛"}, {"w": "饭僧", "t": "施舍饭食给僧人。"}]}, {"meaning": "含。古代将米贝珠玉之类放入死者口中。", "cites": [{"t": "共饭玉。", "b": "《周礼·典瑞》。注:“碎玉以杂米也。”"}], "words": [{"w": "饭玉", "t": "饭含。古时把碎玉杂米放入死者口中"}, {"w": "饭腥", "t": "把生米填入死人口中"}, {"w": "饭米", "t": "填入死者口中的米。"}]}, {"meaning": "煮熟的谷类食物,多指米饭。", "cites": [{"t": "毋抟饭。", "b": "《礼记·曲礼上》"}, {"t": "父时为将,身所奉饭者以十数。", "b": "汉·刘向《列女传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('824wx','饮','1','yǐn yìn','饣','7','','[{"pinyin": "yǐn", "defs": [{"meaning": "(会意。甲骨文字形。右边是人形,左上边是人伸着舌头,左下边是酒坛(酉)。象人伸舌头向酒坛饮酒。小篆演变为“飲”,隶书作“饮”。本义:喝)。"}, {"meaning": "同本义。有时特指喝酒。", "cites": [{"t": "飮,飮也。", "b": "《说文》。今隶作饮。"}, {"t": "君子以饮食宴乐。", "b": "《易·需》。虞注:“水流入口为饮。”"}, {"t": "饮酒浆饮,俟于东房。", "b": "《仪礼·公食礼》"}, {"t": "冬日则饮汤,夏日则饮水。", "b": "《孟子·告子上》"}, {"t": "子反受而饮之。", "b": "《韩非子·十过》"}, {"t": "项王即日因留沛公与饮。", "b": "《史记》"}], "words": [{"w": "豪饮", "t": "放量饮酒"}, {"w": "饮水茹藻", "t": "喝泠水吃淡味食品。喻处境艰难或内心抑郁之情"}, {"w": "饮茶;一饮而尽;饮水", "t": "喝水。"}]}, {"meaning": "含;忍。", "cites": [{"t": "耕男饐妇猛一省,髑髅饮冤死犹警。", "b": "清·贝青乔《哀甬乐》"}], "words": [{"w": "饮恨而终", "t": "含恨而死"}, {"w": "饮冤", "t": "含冤"}, {"w": "饮默", "t": "忍着不吭声"}, {"w": "饮气", "t": "忍气。"}]}, {"meaning": "隐没;藏匿", "cites": [{"t": "然终不伐其能饮其德。", "b": "《汉书·游侠朱家传》"}, {"t": "趣以饮章,辞情何缘复闻?", "b": "《后汉书·蔡邕传》"}], "words": [{"w": "饮章", "t": "匿名的奏章。"}]}, {"meaning": "酒。", "cites": [{"t": "辨四饮之物。", "b": "《周礼·酒正》"}], "words": [{"w": "饮徒", "t": "酒友,酒徒"}, {"w": "饮豪", "t": "指酒量极大"}, {"w": "饮令", "t": "酒令。"}]}, {"meaning": "饮料。", "cites": [{"t": "司马子反渴而求饮。", "b": "《吕氏春秋·权勋》"}], "words": [{"w": "冷饮;热饮", "t": ""}]}]}, {"pinyin": "yìn", "defs": [{"meaning": "把水给人或牲畜喝。", "cites": [{"t": "饮之食之,教之诲之。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "饮羊", "t": "指羊贩让羊多饮水,增加其体重以牟利。后引申为欺诈牟利"}, {"w": "饮水", "t": "给牲口喝水"}, {"w": "饮马长江", "t": "在长江边给战马喝水。指渡江南下进行征伐。"}]}, {"meaning": "用酒食款待。", "cites": [{"t": "中军置酒饮归客。", "b": "唐·岑参《白雪歌送武判官归京》"}], "words": [{"w": "饮客", "t": "用酒食款待客人"}, {"w": "饮劳", "t": "以酒食慰劳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('825wx','系','1','jì xì','糸','7','','[{"pinyin": "jì", "defs": [{"meaning": "拴;系结。", "cites": [{"t": "忽风云腾涌,急系缆。", "b": "陆游《过小孤山大孤山》"}, {"t": "系之苇召。", "b": "《荀子·劝学》"}], "words": [{"w": "系腰", "t": "腰带"}, {"w": "系鞋带;把晾衣服绳系在树上;她的头发上系了一根红缎带;腰上系了一根紫色的…腰带;把卡片系在包上;把衣服扣系上", "t": ""}]}, {"meaning": "约束;羁绊。", "cites": [{"t": "愚士系俗兮,窘若囚拘。", "b": "汉·贾谊《鹏鸟赋》"}]}, {"meaning": "拘囚。", "cites": [{"t": "累及好人,无故系狱。", "b": "元·关汉卿《裴度还带》"}]}, {"meaning": "牵涉;关连。", "cites": [{"t": "穷通各问命,不系才不才。", "b": "唐·白居易《谕友》"}]}]}, {"pinyin": "xì", "defs": [{"meaning": "(“系”、“係”、“繫”三字的意义界限不清楚,故往往通用,且经传多以繫为之,只有世系的意义,只用“系”字。会意。甲骨文字形上面是“爪”,下面是“丝”。丝悬于掌中而下垂。本义:悬,挂)。"}, {"meaning": "同本义。", "cites": [{"t": "以羽为巢,而编之以发,系之苇苕。", "b": "《荀子》"}], "words": [{"w": "系璧", "t": "系在带间的小玉璧"}, {"w": "系滞", "t": "悬挂弃置。"}]}, {"meaning": "拴;绑。", "cites": [{"t": "繫,约束也。", "b": "《说文》"}, {"t": "繫,系也。", "b": "《易·系辞》释文"}, {"t": "以九两繫邦国之民。", "b": "《周礼·天官·大宰》。注:“繫,联缀也。”"}, {"t": "子婴即系颈以组,白马素车,奉天子玺符,降轵道旁。", "b": "《史记》"}], "words": [{"w": "系足", "t": "借指婚姻"}, {"w": "系裹", "t": "穿戴衣帽"}, {"w": "系舟", "t": "指船靠岸。也作“系船”。"}]}, {"meaning": "拘囚;关进牢狱。", "cites": [{"t": "收系张胜。", "b": "《汉书·李广苏建传》"}, {"t": "老母系保宫。", "b": ""}, {"t": "利系者之多。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "拘系", "t": "拘禁"}, {"w": "系縻", "t": "束缚。"}]}, {"meaning": "牵挂。", "cites": [{"t": "可怜赫赫丹阳尹,数颗槟榔尚系怀。", "b": "宋·陆游《读史》"}], "words": [{"w": "系怀", "t": "心中牵挂某事或某人。"}]}, {"meaning": "依附。", "cites": [{"t": "古者诸侯之有女子也,所以苞苴玩弄系援于大国也。", "b": "汉·刘向《列女传》"}], "words": [{"w": "系援", "t": "依附求助"}, {"w": "系象", "t": "寄托意象"}, {"w": "系命", "t": "犹言寄托性命。"}]}, {"meaning": "关联。", "cites": [{"t": "足有系帛书。", "b": "东汉·班固《汉书·李广苏建传》"}], "words": [{"w": "系亲", "t": "联姻,结亲"}, {"w": "系络", "t": "联结"}, {"w": "系联", "t": "联系"}, {"w": "系属", "t": "联缀。"}]}, {"meaning": "系物的带、绳。", "cites": [{"t": "武冠,俗谓之大冠,环缨无蕤,以青系为绲。", "b": "《后汉书·舆服志下》"}]}, {"meaning": "世系;系统。", "cites": [{"t": "桑道茂者,寒人,失其系望。", "b": "《新唐书》"}], "words": [{"w": "系望", "t": "世系郡望"}, {"w": "系孙", "t": "指后代子孙"}, {"w": "系族", "t": "一姓世代相传的序列"}, {"w": "系录", "t": "谱牒。记录一姓世系的书"}, {"w": "系世", "t": "记载世系的谱牒"}, {"w": "谱系;管系;层系;坐标系;星系;银河系;太阳系;奥陶系;碳系;志留系", "t": ""}]}, {"meaning": "地质学名词 。地层系统分类的第二级,小于界,相当于地质年代的纪。", "cites": [{"t": "系燕王父子。", "b": "宋·欧阳修《新五代史·伶官传·序》"}]}, {"meaning": "姓。楚有系益。"}, {"meaning": "束缚;捆绑。", "cites": [{"t": "系,繫也。", "b": "《说文》"}, {"t": "系,连也。", "b": "《广雅》"}, {"t": "系,繫也,相联繫也。", "b": "《释名·释衣服》"}, {"t": "系曰。", "b": "《文选·张衡·思玄赋》。旧注:“系,繫也,言繫一赋之前意也。”"}, {"t": "系隆我汉。", "b": "《后汉书·光武纪下》。注:“犹繫也。”"}, {"t": "係,繫束也。", "b": "《说文》"}, {"t": "係妻孥。", "b": "《国语·越语上》注:“係,繫也。”"}, {"t": "係马舌。", "b": "《国语·吴语》。又注:“係,缚也。缚马舌恐有声也。”"}, {"t": "係累其子弟。", "b": "《孟子,梁惠王下》。注:“係累,犹缚结也。”"}, {"t": "百越之君,俯首係颈,委命下吏。", "b": "贾谊《过秦论》"}], "words": [{"w": "系累", "t": "束缚"}, {"w": "系锁", "t": "用锁索捆绑"}, {"w": "系颈", "t": "把绳套在颈上,表示伏罪投降。"}]}, {"meaning": "继续;接续。", "cites": [{"t": "汎海而至,风波艰阻,沈溺相係。", "b": "《后汉书·郑弘传》"}, {"t": "邓、唐、蔡、陈,驰捷系踵。", "b": "宋·洪迈《容斋四笔·会合联句》"}], "words": [{"w": "系进", "t": "接续进发"}, {"w": "系道", "t": "相继于道,络绎不绝。"}]}, {"meaning": "维系;关联。", "cites": [{"t": "某命系于将军,惟将军怜之。", "b": "《三国演义》"}], "words": [{"w": "系属", "t": "联系,关联"}, {"w": "系心", "t": "犹归心;挂心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('826wx','言','1','yán','言','7','','[{"pinyin": "yán", "defs": [{"meaning": "(指事。甲骨文字形,下面是“舌”字,下面一横表示言从舌出。“言”是张口伸舌讲话的象形。从“言”的字与说话或道德有关。本义:说,说话)。"}, {"meaning": "同本义。", "cites": [{"t": "直言曰言,论难曰语。", "b": "《说文》"}, {"t": "志以发言。", "b": "《左传·襄公二十七年》"}, {"t": "志以定言。", "b": "《左传·昭公九年》"}, {"t": "国人莫敢言,道路以目。", "b": "《国语·周语上》"}, {"t": "言,心声也。", "b": "《法言·问神》"}, {"t": "言,口之利也。", "b": "《墨子经》"}, {"t": "言者所以在意。", "b": "《庄子·外物》"}, {"t": "具言所闻。", "b": "晋·陶渊明《桃花源记》"}, {"t": "趋机而言。", "b": "《后汉书·列女传》"}, {"t": "言于李??。", "b": "宋·司马光《资治通鉴·唐纪》"}, {"t": "言讫不见。", "b": "明·魏禧《大铁椎传》"}, {"t": "今言“华”如“华实”之“华”者,盖音谬也。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "言绝", "t": "言罢;说完"}, {"w": "言言", "t": "直言"}, {"w": "言不尽意", "t": "言语无法把所有的心意全部表达出来"}, {"w": "言戏", "t": "说话轻浮不庄重"}, {"w": "言人人殊", "t": "人各一词,所言各异"}, {"w": "言笑自若", "t": "谈笑自得的样子"}, {"w": "言之无文", "t": "说话没有文采条理"}, {"w": "言方行圆", "t": "即言行不一"}, {"w": "言信", "t": "说到做到的信用"}, {"w": "言爽", "t": "说话不守信用"}, {"w": "言不顾行", "t": "言行不一"}, {"w": "言欢", "t": "说笑。"}]}, {"meaning": "议论,谈论。", "cites": [{"t": "赵括自少时学兵法,言兵事。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "言路", "t": "谏官的职务"}, {"w": "言事", "t": "在君主时代,臣民与天子、国君议论政事"}, {"w": "言文", "t": "谈论文辞"}, {"w": "言默", "t": "议论和沉默"}, {"w": "言状", "t": "所述情状。"}]}, {"meaning": "记载。", "cites": [{"t": "雁荡山…自古图牒,未尝有言者。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "渔工水师虽知而不能言。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "言行录", "t": "录记叙述一人或多人的嘉言美行的书。"}]}, {"meaning": "问。", "cites": [{"t": "臣意言王曰:“才人女子竖何能?”", "b": "《史记》。王引之述闻:“言王,问王也。”"}], "words": [{"w": "言问", "t": "讯问。"}]}, {"meaning": "告知;告诉。", "cites": [{"t": "其顺之,然后言其丧筭。", "b": "《礼记》。郑玄注:“言,语也。”"}], "words": [{"w": "言讽", "t": "用委婉的语言示告。"}]}, {"meaning": "陈述;叙述。", "cites": [{"t": "臣愿悉言听闻,唯大王裁其罪。", "b": "《韩非子》"}], "words": [{"w": "言功", "t": "陈述功绩。"}]}, {"meaning": "解释引文、词语或某种现象的发端词,相当于“就是说”或“意思是”。", "cites": [{"t": "《诗》云:“既醉以酒,既饱以德。”言饱乎仁义也。", "b": "《孟子》"}]}, {"meaning": "说明。", "cites": [{"t": "言其利害(说明合从的好处和不合从的害处。其,指示代词,代合从,它的)。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "话,言语,口语。又特指怨言、谤言。", "cites": [{"t": "父母之言。", "b": "《诗·郑风·将仲子》又"}, {"t": "诸兄之言。", "b": ""}, {"t": "口之宣言也,善败于是乎兴。", "b": "《国语·周语上》"}, {"t": "感斯人言,是夕始觉有迁谪意。", "b": "唐·白居易《琵琶行》序"}, {"t": "王如其言。", "b": "晋·干宝《搜神记》"}, {"t": "未尝有言。", "b": "明·刘基《卖柑者言》"}, {"t": "思其言。", "b": ""}, {"t": "是何言。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "言能践行", "t": "说到做到"}, {"w": "言语高低", "t": "指说话没分寸,冲撞别人"}, {"w": "言差语错", "t": "言语冲撞或口舌之争"}, {"w": "言言善果", "t": "多说劝人行善的话,必有好处"}, {"w": "言同勒石", "t": "喻指说的话深刻而珍贵,如同刻石"}, {"w": "言词", "t": "用语言表达的词汇或词句"}, {"w": "言不尽意", "t": "言语无法把所有的心意全部表达出来"}, {"w": "言不愿行", "t": "言语和行为不相符合"}, {"w": "言语妙天下", "t": "言语精妙,天下没有人比得上"}, {"w": "言听谋决", "t": "说的话听从照办"}, {"w": "言废", "t": "说的话不被采纳"}, {"w": "言简义丰", "t": "语言简练,含意丰富"}, {"w": "言与心违", "t": "言语与心意相违背"}, {"w": "言智", "t": "言语的才智"}, {"w": "言无伦次", "t": "言语杂乱无章。"}]}, {"meaning": "言论;见解;意见。", "cites": [{"t": "如何昊天?辟言不信。", "b": "《诗·小雅·雨无止》"}, {"t": "言无二贵,法无两适,故言行而不轨于法令者必禁。", "b": "《韩非子》"}], "words": [{"w": "言扬行举", "t": "根据德行和声名来选择人才"}, {"w": "言金", "t": "珍贵的言论"}, {"w": "言之成理", "t": "言论能自成系统而有文理"}, {"w": "言中无物", "t": "言论空洞而无实际内容。"}]}, {"meaning": "言辞;辞令;辞章。", "cites": [{"t": "无乃非盟载之言,以阙君德;而执事不利焉。", "b": "《左传》"}], "words": [{"w": "言外", "t": "言辞本身以外的意思"}, {"w": "言使", "t": "使者。使者主要在传达言辞,故称言使"}, {"w": "言泉", "t": "言辞滔滔不绝,如泉水般涌出。比喻口辩敏捷,言语通畅"}, {"w": "言多必失", "t": "言辞过多,必定发生差错。"}]}, {"meaning": "政令;号令。", "cites": [{"t": "有不祭则修意,有不祀则修言。", "b": "《国语·周语》。韦昭注:“言,号令也。”"}], "words": [{"w": "言语", "t": "命令;指示"}, {"w": "言文", "t": "法律条文"}, {"w": "言文刻深", "t": "法律条文严峻刻薄"}, {"w": "言出法随", "t": "命令一下达,就依法考核、赏罚。"}]}, {"meaning": "誓言;盟辞;约言。", "cites": [{"t": "初既与余成言兮,后悔遁而有他。", "b": "《楚辞》"}, {"t": "史载笔,士载言。", "b": "《礼记》。郑玄注:“言,谓会同盟要之辞。”"}], "words": [{"w": "言约", "t": "口头言语为约定"}, {"w": "言瑞", "t": "信言。"}]}, {"meaning": "建议;主意;计策。", "cites": [{"t": "我言为服,勿以为笑。", "b": "《诗·大雅》"}], "words": [{"w": "言责", "t": "进言的职责。"}]}, {"meaning": "学说;主张。", "cites": [{"t": "“杨朱、墨翟之言盈天下。天下之言,不归杨则归墨。”", "b": "《孟子》"}]}, {"meaning": "言语或文章中的字。", "cites": [{"t": "凡六百一十六言,命曰《琵琶行》。", "b": "唐·白居易《琵琶行》序"}], "words": [{"w": "五言诗;七言诗", "t": ""}]}, {"meaning": "口语或文章中的句子。", "cites": [{"t": "《诗》三百,一言以蔽之,曰“思无邪。”", "b": "《论语》"}, {"t": "今吾且死,而侯生曾无一言半辞送我,我岂有所失哉?", "b": "《史记》"}], "words": [{"w": "一言为定;片言九鼎", "t": ""}]}, {"meaning": "著作。", "cites": [{"t": "焚百家之言,以愚黔首。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "言对", "t": "文体的一种。"}]}, {"meaning": "无义,用于句中或句首,作语气助词。", "cites": [{"t": "静言思之。", "b": "《诗·邶风·柏舟》"}, {"t": "既盟之后,言归于好。", "b": "《左传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('827wx','冻','1','dòng','冫','7','','[{"pinyin": "dòng", "defs": [{"meaning": "(形声。从仌(bīng),东声。本义:结冰)。"}, {"meaning": "同本义。", "cites": [{"t": "冻,仌也。", "b": "《说文》"}, {"t": "壮冰曰冻。", "b": "《风俗通》"}, {"t": "水始冰,地始冻。", "b": "《礼记·月令》"}, {"t": "风掣红旗冻不翻。", "b": "唐·岑参《白雪歌送武判官归京》"}], "words": [{"w": "冻柱", "t": "冻住"}, {"w": "冻浦", "t": "结了冰的河川。"}]}, {"meaning": "受冻;感到寒冷。", "cites": [{"t": "夜冻寒。", "b": "《管子·五辅》"}, {"t": "人马冻死者相望。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "冻草", "t": "使草受冻"}, {"w": "冻树", "t": "寒霜凝结在树木上"}, {"w": "冻笔", "t": "因寒冷而冻结的毛笔。"}]}, {"meaning": "厚冰。", "cites": [{"t": "冰解而冻释。", "b": "《管子·五行》"}], "words": [{"w": "冻合", "t": "冰封"}, {"w": "冻冻", "t": "冰"}, {"w": "冻轮", "t": "冰轮"}, {"w": "冻雪", "t": "冰雪。"}]}, {"meaning": "寒冷,受冷或感到冷。", "cites": [{"t": "吾庐独破受冻死亦足。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "冻刺刺", "t": "冻钦钦。冷得发颤的样子"}, {"w": "冻冽", "t": "冰冷;极冷"}, {"w": "冻剥剥", "t": "寒冷透凉地"}, {"w": "小心冻着", "t": ""}]}, {"meaning": "水晶般的,形容像冰一般晶莹润泽的。", "cites": [{"t": "石有数种,灯光冻石为最。", "b": "文彭《印章杂说》"}], "words": [{"w": "冻珠;亦为冻石的简称;冻石", "t": "一种可制成印章或工艺品的石头"}, {"w": "冻云", "t": "冬天下雪前凝聚的阴云。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('828wx','状','1','zhuàng','犬','7','','[{"pinyin": "zhuàng", "defs": [{"meaning": "(形声。从犬,爿(pán)声。用具体的动物“犬”表示事物各具形态。本义:犬形)。"}, {"meaning": "同本义。引申为形状,形态。", "cites": [{"t": "状,犬形也。", "b": "《说文》"}, {"t": "且曰献状。", "b": "《左传·文公十五年》。谓献其骈肋之状也。"}, {"t": "凡铸金之状。", "b": "《考工记·桌氏》。杜注:“谓形状。”"}, {"t": "以筒水灌之,始出,状极俊健。", "b": "《聊斋志异》"}, {"t": "有双石高竦,其状若门。", "b": "郦道元《水经注》"}, {"t": "若啸呼状。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "状类", "t": "形似"}, {"w": "粉状;杆状;块状;粒状;絮状;海绵状;奇形怪状", "t": ""}]}, {"meaning": "情形;状况。", "cites": [{"t": "舍人弟上变,告信欲反状于吕后。", "b": "《史记·淮阴侯列传》"}, {"t": "欲死秦军状。", "b": "《史记·魏公子列传》"}, {"t": "以状语武。", "b": "《汉书·李广苏建传》"}, {"t": "巡抚状闻。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "巴陵胜状。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "自绘败状。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "景状亦近。", "b": "蔡元培《图画》"}], "words": [{"w": "现状;状容", "t": "形态"}, {"w": "状候", "t": "情况;状态。"}]}, {"meaning": "行状,记述死者事迹的一种文体,属于传记类。", "cites": [{"t": "敢以状私于执事。", "b": "柳宗元《段太尉逸事状》"}], "words": [{"w": "状略", "t": "行状的大略"}, {"w": "状式", "t": "行状的格式。"}]}, {"meaning": "诉状。", "cites": [{"t": "李具状,求在狱候春发遣。", "b": "方苞《狱中杂记》"}], "words": [{"w": "状头", "t": "原告人"}, {"w": "状儿", "t": "状子;起诉书"}, {"w": "告状;状呈", "t": "即状子"}, {"w": "状告", "t": "递状控告。"}]}, {"meaning": "书信。", "cites": [{"t": "是以前状辄述鄙城,眷惠手翰还答,益增欣悚。", "b": "韩愈《与鄂州柳中丞书》"}]}, {"meaning": "容貌,面貌。", "cites": [{"t": "妾无状。", "b": "《汉书·东方朔传》。注:“形貌也。”"}, {"t": "[吕]不韦使[异人]楚服相见,王后悦其状,高其智。", "b": "《战国策·秦策》"}]}, {"meaning": "礼貌 。常与“无”连用,“无状”即没有礼貌之意。", "cites": [{"t": "诸侯吏卒异时故徭使屯戍过秦中,秦中吏卒遇之多无状。", "b": "《史记·项羽本纪》"}]}, {"meaning": "陈述。", "cites": [{"t": "自状其过以不当亡者众,不状其过以不当存者寡。", "b": "《庄子·德充符》"}, {"t": "再思此言,自状其短,观过知仁,亦足称也。", "b": "洪迈《容斋四笔》"}]}, {"meaning": "描绘。", "cites": [{"t": "灼灼状桃花之鲜,依依尽杨柳之貌。", "b": "《文心雕龙》"}], "words": [{"w": "状物", "t": "描绘事物"}, {"w": "状写描绘", "t": ""}]}, {"meaning": "描摹。", "cites": [{"t": "遂以五可之容颜发肤,神情态度,口写而手状之。", "b": "《聊斋志异》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('829wx','亩','1','mǔ','亠','7','','[{"pinyin": "mǔ", "defs": [{"meaning": "(形声。小篆字形。从十,从田,久声。十,四方。本义:中国土地面积市亩的通称) 同本义,一亩约等于667平方米。", "cites": [{"t": "畮,六尺为步,百步为畮。秦田二百四十步为畮。畮或从十久。", "b": "《说文》。字亦作畆、畒、畝、畞。如:亩制(以亩为单位划分、计算土地面积的制度);亩级(田地土壤质量好坏的等级);亩积(每一亩田的面积)"}]}, {"meaning": "田垄。", "words": [{"w": "亩丘", "t": "有垄界的丘地"}, {"w": "亩道", "t": "古代以国都为中心的大道。"}]}, {"meaning": "泛指农田,田地。", "cites": [{"t": "又亲操耒耨以修畎亩。", "b": "《韩非子·说疑》"}], "words": [{"w": "畎亩", "t": "泛指田地,田间。析言之,垄上叫亩,垄中叫畎,即田中垄沟"}, {"w": "亩陇", "t": "田野,农田"}, {"w": "亩畹", "t": "园圃。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('830wx','况','1','kuàng','冫','7','','[{"pinyin": "kuàng", "defs": [{"meaning": "(形声。从水,兄声。本义:寒冷的水)。"}, {"meaning": "同本义。", "cites": [{"t": "況,寒水也。", "b": "《说文》。段玉裁注:“未得其证。…古矧兄、比兄,皆用兄字;后乃用況字,后又改作况。”"}]}, {"meaning": "情形,景况(侧重于整个事物的概况)。", "cites": [{"t": "乱况斯削。", "b": "《诗·大雅·桑柔》"}, {"t": "客有问雁山游况者,聊以塞责,不足观也。", "b": "韩愈《雁山杂记》"}], "words": [{"w": "况味", "t": "境况情味。有时专指境遇"}, {"w": "闲况;状况;实况;战况;情况;盛况", "t": ""}]}, {"meaning": "比拟,比喻。", "cites": [{"t": "案火灭不能复燃以况之,死入不能复为鬼,明矣。", "b": "王充《论衡》"}], "words": [{"w": "每下愈况", "t": ""}]}, {"meaning": "光顾;访问。", "cites": [{"t": "足下不远千里,来况齐国。", "b": "《史记·司马相如列传》"}]}, {"meaning": "赐予。", "cites": [{"t": "成(盛)名况乎诸侯。", "b": "《荀子》"}, {"t": "北面拜况。", "b": "《礼记·聘礼》"}, {"t": "亦无况也。", "b": "《左传·僖公十五年》"}, {"t": "况使臣以大礼。", "b": "《国语·鲁语下》"}], "words": [{"w": "况施", "t": ""}]}, {"meaning": "表示递进关系,相当于“何况”、“况且”。", "cites": [{"t": "况拾遗求利以污其行乎。", "b": "《后汉书·列女传》"}, {"t": "况君前途尚可。", "b": "《世说新语·自新》"}, {"t": "况大国乎。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "况刘豫州王室之胄。", "b": "《资治通鉴》"}, {"t": "况流俗乎。(流俗:指一般人,世俗之人。)", "b": "清·刘开《问说》"}, {"t": "况草野之无闻者欤。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "(何况在乡间那些没有声名的人呢?草野,与“朝廷”相对,借指民间。闻,这里应读“wèn”,声名,声誉)。", "cites": [{"t": "竹柏皆冻死,况彼无衣民!", "b": "白居易《村居苦寒》"}], "words": [{"w": "况乃", "t": "何况;况且。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('831wx','床','1','chuáng','广','7','','[{"pinyin": "chuáng", "defs": [{"meaning": "(形声。从木,爿(pán)声。本义:坐卧的器具)。"}, {"meaning": "同本义。", "cites": [{"t": "牀,安身之坐也。从木,片声。字亦作床。古闲居坐于牀,隐于几,不垂足,夜则寝,晨兴则敛枕簟。", "b": "《说文》"}, {"t": "在下而安者也。", "b": "《易·剥牀》王注?"}, {"t": "媒人下床去,诺诺复尔尔。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "床头屋漏无干处,雨脚如麻未断绝。", "b": "杜甫《茅屋为秋风所破歌》"}, {"t": "阿母得闻之,槌床便大怒。", "b": "汉乐府《孔雀东南飞》"}], "words": [{"w": " 单人床;双人床;帆布床;折叠床;卧病在床;床裙", "t": "床围,围在床四周的绸、布等"}, {"w": "床地平", "t": "床面"}, {"w": "床背阁", "t": "置于床背的长方形柜子,上面放被褥,下有箱、屉"}, {"w": "床上安床", "t": "床上放床。比喻无谓的重复。"}]}, {"meaning": "床形物。", "cites": [{"t": "赖知禾黍收,已觉糟床注。", "b": "杜甫《羌村三首》"}], "words": [{"w": " 机床;车床;硫化床;河床;苗床", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('832wx','库','1','kù','广','7','','[{"pinyin": "kù", "defs": [{"meaning": "(会意。从广(yǎn),表示与房屋有关,从车。兵车藏在房屋一类的建筑内,表示是储藏武器战车的地方。本义:军械库,收藏兵器和兵车的处所)。"}, {"meaning": "同本义。", "cites": [{"t": "库,兵车藏也。", "b": "《说文》"}, {"t": "在库言库。", "b": "《礼记·曲礼》"}, {"t": "七月官库。", "b": "《淮南子·时则》。注:“兵府也。”"}, {"t": "焚库,无聚,将何以守矣。", "b": "《左传·哀公十六年》"}], "words": [{"w": "库兵", "t": "库藏的兵器。"}]}, {"meaning": "后泛指贮物的屋舍。", "cites": [{"t": "库,舍也。", "b": "《广雅》"}, {"t": "管库之士。", "b": "《礼记·檀弓》。注:“物所藏。”"}, {"t": "衡库者天子之礼也。", "b": "《管子·七律》"}, {"t": "库门,天子皋门。", "b": "《礼记·名堂位》"}, {"t": "百姓虚而府库满。", "b": "《荀子·富国》"}, {"t": "使府人、库人各儆其事。", "b": "《左传·昭公十八年》"}, {"t": "库不受甲兵。", "b": "《韩非子·十过》"}, {"t": "纳之库。", "b": "《明史》"}], "words": [{"w": "库子", "t": "库号。掌管、守卫官库的人"}, {"w": "库局", "t": "佛寺中掌管仓库、财务的部门"}, {"w": "库司", "t": "佛寺中掌管仓库钱粮的人"}, {"w": "库收", "t": "藩台衙门库房收银后发给的临时收据"}, {"w": "库金", "t": "库藏之金帛"}, {"w": "库门", "t": "仓库的门。"}]}, {"meaning": "监狱。", "cites": [{"t": "故拘之牖里之库百日,欲令之死。", "b": "《史记·鲁仲连邹阳列传》"}]}, {"meaning": "宋时酒肆称库。", "cites": [{"t": "大抵酒肆除官库、子库、脚店之外,其余谓之“拍户”,兼卖诸般下酒,食次随意索唤。", "b": "宋·吴自牧《梦粱录》"}]}, {"meaning": "电量单位“库仑”的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('833wx','庇','1','bì','广','7','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从广,比声。“广”(yǎn),甲骨文、金文象屋顶屋墙。从“广”表示与房屋等有关。本义:遮蔽)。"}, {"meaning": "同本义。", "cites": [{"t": "庇,荫也。", "b": "《说文》。按,字亦作庀"}, {"t": "弓长六尺,谓之庇轵。", "b": "《考工记·轮人》"}, {"t": "安得广厦千万间,大庇天下寒士俱欢颜。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "保护。", "cites": [{"t": "虽有庇民之大德。", "b": "《礼记·表记》"}, {"t": "大官、大邑,身之所庇也。", "b": "《左传·襄公三十一年》"}, {"t": "子盖亦远绩禹功而大庇民乎!", "b": "《左传·昭公元年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('834wx','疗','1','liáo','疒','7','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从疒(chuáng),表示疾病有关,尞(liáo)声。本义:医治)。"}, {"meaning": "同本义(含有对症下药之意)。", "cites": [{"t": "疗,治也。", "b": "《广雅·释诂》"}, {"t": "凡疗疡,以五毒攻之。", "b": "《周礼·天官·疡医》"}, {"t": "不可救疗。", "b": "《左传·襄公二十六年》"}, {"t": "凡疗病者,必知脉之虚实。", "b": "《后汉书·王符传》"}, {"t": "既泣之三日,乃誓疗之。", "b": "龚自珍《病梅馆记》"}], "words": [{"w": "疗治", "t": "治疗,调治"}, {"w": "疗疾", "t": "疗病。治疗疾病"}, {"w": "疗视", "t": "诊察治疗"}, {"w": "疗护", "t": "治疗救护"}, {"w": "疗妒", "t": "治疗嫉妒的病症"}, {"w": "疗病", "t": "治病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('835wx','吝','1','lìn','口','7','','[{"pinyin": "lìn", "defs": [{"meaning": "(形声。从口,文声。本义:顾惜,舍不得)。"}, {"meaning": "同本义(爱惜过分,当耗费的舍不得耗费,该使用的舍不得使用)。", "cites": [{"t": "吝,恨惜也。", "b": "《说文》。字亦作恡,作悋。"}, {"t": "凡贪而不施或谓之悋。悋,恨也。", "b": "《方言十》"}, {"t": "以往吝。", "b": "《易·蒙》"}, {"t": "坤为吝啬。", "b": "《易·说卦》"}, {"t": "悔吝者,言乎其小疵也。", "b": "《易·系辞》"}, {"t": "出纳之吝。", "b": "《论语》。皇疏:“难惜之也。”"}, {"t": "商甚恡于财。", "b": "《孔子家语·致思》。注:“啬甚也。”"}, {"t": "改过不吝。", "b": "《书·仲虺之诰》"}, {"t": "惟予之公书,与张氏之吝书若不相类。", "b": "袁枚《黄生借书说》"}, {"t": "犹之与人也,出纳之吝谓之有司。", "b": "《论语·尧曰》"}, {"t": "又何吝一躯以啖我而全微命乎?", "b": "马中锡《中山狼传》"}], "words": [{"w": "吝色", "t": "舍不得的神情"}, {"w": "吝情", "t": "舍不得的表情。"}]}, {"meaning": "认为耻辱。", "cites": [{"t": "得之不休,不获不吝。", "b": "张衡《应间》"}]}, {"meaning": "吝啬;小气。", "cites": [{"t": "固吝者何。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "以为鄙吝。", "b": "宋·司马光《训俭示康》"}, {"t": "赏赐无所吝。", "b": "清·邵长蘅《清门剩稿》"}], "words": [{"w": "吝爱", "t": "过分吝啬"}, {"w": "吝悭", "t": "吝啬"}, {"w": "吝简", "t": "吝啬"}, {"w": "吝骄", "t": "吝啬而骄傲。"}]}, {"meaning": "非分贪求。", "cites": [{"t": "如有周公之才之美,使骄且吝,其余不足观也已。", "b": "《论语·泰伯》"}, {"t": "[夏侯]楙字子休,其性最急,又最吝。", "b": "《三国演义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('836wx','应','1','yīng yìng','广','7','','[{"pinyin": "yīng", "defs": [{"meaning": "应当,应该。", "cites": [{"t": "应,当也。", "b": "《说文》"}, {"t": "应,当也。", "b": "《尔雅》"}, {"t": "文王既勤止,我应受之。", "b": "《诗·周颂·赉》"}, {"t": "故国神游,多情应笑我。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}, {"t": "应是良晨好景虚设。", "b": "宋·柳永《雨霖铃》"}, {"t": "凡所应有。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "应得之资。", "b": ""}, {"t": "不应重罚。", "b": "清·方苞《狱中杂记》"}, {"t": "法应立决。", "b": ""}], "words": [{"w": "应然", "t": "应该如此"}, {"w": "应伯爵", "t": "白吃白喝。“应白嚼”之谐音"}, {"w": "应合", "t": "应当;该当"}, {"w": "应是", "t": "应当是。"}]}, {"meaning": "答应,允许。", "cites": [{"t": "桓侯不应。", "b": "《韩非子·喻老》"}], "words": [{"w": "应候", "t": "应承"}, {"w": "应诺", "t": "答应;应承"}, {"w": "应许", "t": "答应;允许"}, {"w": "应准", "t": "答应;说定"}, {"w": "应允", "t": "答应,允许"}, {"w": "提出的条件他都应了;是我应下来的任务", "t": ""}]}, {"meaning": "所有;全部。", "cites": [{"t": "应退出地皆拨还本主;应水占地皆以官地对还。", "b": "宋·苏辙《再论京西水柜状》"}], "words": [{"w": "应干", "t": "一切有关的。"}]}, {"meaning": "古国名 ,故址在今河南省鲁山县东。"}]}, {"pinyin": "yìng", "defs": [{"meaning": "应和,响应。", "cites": [{"t": "龟往离散以应我。", "b": "《国语·晋语》"}, {"t": "齐王不应。", "b": "《战国策·齐策》"}, {"t": "宋王无以应。", "b": "《吕氏春秋·顺说》"}, {"t": "桓侯不应。", "b": "《韩非子·喻老》"}, {"t": "河曲智叟无以应。", "b": "《列子·汤问》"}, {"t": "佣者笑而应。", "b": "《史记·陈涉世家》"}, {"t": "宜多应者。", "b": "《史记·陈涉世家》"}, {"t": "杀之以应陈涉。", "b": ""}, {"t": "云集响应。", "b": "汉·贾谊《过秦论》"}, {"t": "应者近万人。", "b": "《资治通鉴·唐纪》"}, {"t": "金色而玉应。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "每闻琴瑟之声,则应节而舞。", "b": "《聊斋志异·促织》"}], "words": [{"w": "一呼百应;里应外合;应口", "t": "还嘴;对答"}, {"w": "应昂", "t": "答应"}, {"w": "应嘴", "t": "答话,回嘴"}, {"w": "应响", "t": "回声"}, {"w": "应机赴节", "t": "依照节拍敲击演奏"}, {"w": "应合", "t": "应和配合;应和"}, {"w": "应佛僧", "t": "应召到有关人家去做佛事的和尚"}, {"w": "应令", "t": "响应诏令。"}]}, {"meaning": "受;接受。", "cites": [{"t": "迫切不得已,乃应命至都。", "b": "《南史·虞荔传》"}], "words": [{"w": "应事", "t": "承担事务"}, {"w": "应役", "t": "受征召服劳役"}, {"w": "应供", "t": "接受奉养"}, {"w": "应约", "t": "接受约请。"}]}, {"meaning": "符合;适应;顺应。", "cites": [{"t": "六合正相应。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "得心应手;应天顺人", "t": "适应天命,顺从人心"}, {"w": "应化", "t": "顺应变化。"}]}, {"meaning": "应付;对付。", "cites": [{"t": "枢始得其环中,以应无穷。", "b": "《庄子·齐物论》"}], "words": [{"w": "应接不暇;应急屎坑", "t": "喻指紧急时刻可以应用的对象"}, {"w": "应故事", "t": "按照老规矩,敷衍塞责"}, {"w": "应难", "t": "应付危难。"}]}, {"meaning": "感应;应验。", "cites": [{"t": "令兄托梦,莫非应在此人身上。", "b": "《说唐》"}], "words": [{"w": "应兆", "t": "应验的征兆"}, {"w": "应劫", "t": "应验劫运"}, {"w": "应符", "t": "应验符命"}, {"w": "应瑞", "t": "应验祥瑞。"}]}, {"meaning": "对敌方回击、迎击。", "cites": [{"t": "齐威王使章子将而应之。", "b": "《战国策·齐策一》"}, {"t": "今以三万之众而应强国之兵。", "b": "《战国策·赵策三》"}, {"t": "卢沟桥的烽火一起,我们挺身迎战。", "b": "闻一多《愈战愈强》"}], "words": [{"w": "应敌", "t": "迎击来敌。"}]}, {"meaning": "许配。", "cites": [{"t": "以我应他人。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('837wx','这','1','zhè zhèi','辶','7','','[{"pinyin": "zhè", "defs": [{"meaning": "(形声。从辵(chuò),言声。本义:迎)。"}, {"meaning": "此,指目前的或较近的或刚刚提到的人、物、事或想法。", "cites": [{"t": "为报江南二三日,这回应见雪中人。", "b": "卢仝《送好法师归江南诗》"}], "words": [{"w": "这向", "t": "这些日子"}, {"w": "这厢", "t": "这边;这里"}, {"w": "这的", "t": "这个;这里"}, {"w": "这壁", "t": "这里;这边"}, {"w": "这厮", "t": "这个奴才,这个家伙。对人轻蔑的称呼。"}]}]}, {"pinyin": "zhèi", "defs": [{"meaning": "", "words": [{"w": "这二列火车;这本书", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('838wx','冷','1','lěng','冫','7','','[{"pinyin": "lěng", "defs": [{"meaning": "(形声。从仌(bīng),冰,令声。本义:凉)。"}, {"meaning": "同本义。", "cites": [{"t": "冷,寒也。", "b": "《说文》"}, {"t": "画堂鹦鹉鸟,冷暖不相知。", "b": "白居易《乌夜啼》"}], "words": [{"w": "冷香", "t": "清雅的香气"}, {"w": "冷泉", "t": "清凉的泉水"}, {"w": "冷翠", "t": "给人以清凉感的翠绿色。"}]}, {"meaning": "寒冷。", "cites": [{"t": "布衾多年冷似铁。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "冰冷", "t": "很冷"}, {"w": "干冷", "t": "干燥而寒冷"}, {"w": "冷丁丁", "t": "亦作“冷化化”。形容天气寒冷。也形容身体冰凉;表情冷淡、严肃的样子"}, {"w": "冷噤", "t": "冷禁。冷战;寒颤"}, {"w": "冷铺", "t": "乞丐居住。也指驿亭"}, {"w": "冷节遗芳", "t": "寒冷时节开的花。"}]}, {"meaning": "冷清;冷落。", "cites": [{"t": "门前冷落鞍马稀,老大嫁作商人妇。", "b": "白居易《琵琶行》"}, {"t": "诸公衮衮登台省,广文先生官独冷。", "b": "杜甫《醉时歌赠广文馆学士郑虔》"}], "words": [{"w": "冷巷", "t": "僻静的小巷"}, {"w": "冷闷", "t": "冷落;冷冰冰"}, {"w": "冷曹", "t": "清冷的官署"}, {"w": "冷局", "t": "冷落的衙门"}, {"w": "冷寂", "t": "冷落寂寞。"}]}, {"meaning": "不畅销。", "cites": [{"t": "这《千家诗》还算一半是冷货,一年不过百把部。", "b": "《老残游记》"}], "words": [{"w": "冷书", "t": "不热门的书。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('839wx','庐','1','lú','广','7','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。从广(yǎn),廬声。从“广”,表示与房屋有关。本义:特指田中看守庄稼的小屋)。"}, {"meaning": "同本义。", "cites": [{"t": "庐,寄也。秋冬去,春夏居。", "b": "《说文》"}, {"t": "庐,舍也。", "b": "《广雅》"}, {"t": "余二十亩,以为庐舍。", "b": "《汉书·食货志》。注:“田中屋也。”"}, {"t": "庐井有伍。", "b": "《左传·襄公三十年》"}, {"t": "中田有庐,疆场有瓜。", "b": "《诗·小雅·信南山》"}]}, {"meaning": "亦泛指简陋居室。", "cites": [{"t": "屋室庐庾。", "b": "《荀子·正名》。注:“草屋也。”"}, {"t": "众鸟欣有托,吾亦爱吾庐。", "b": "晋·陶潜《读山海经诗》之一"}, {"t": "结庐在人境,而无车马喧。", "b": "晋·陶潜《饮酒》"}, {"t": "南阳诸葛庐。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "或黔其庐。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "竭其庐之入。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "焚汝庐。", "b": "明·高启《书博鸡者事》"}, {"t": "造庐访成。", "b": "《聊斋志异·促织》"}], "words": [{"w": "庐舍", "t": "田舍;茅屋"}, {"w": "庐落", "t": "庐舍院落"}, {"w": "庐舍丘墟", "t": "家业败落"}, {"w": "庐井", "t": "房舍田园"}, {"w": "庐宇", "t": "房屋。"}]}, {"meaning": "古代沿途迎候宾客的房舍。", "cites": [{"t": "凡国野之道,十里有庐,庐有饮食。", "b": "《周礼·地官》"}]}, {"meaning": "古代官员值宿所住的房舍。", "cites": [{"t": "君厌承明之庐。", "b": "《汉书·严助传》。注:“直宿所止曰庐。”"}], "words": [{"w": "庐帐", "t": "以帐幕作居室;帐篷"}, {"w": "庐徼", "t": "驻有巡逻守备兵丁的营舍。"}]}, {"meaning": "古州名 。故址在今安徽省合肥市一带。"}, {"meaning": "矛戟等兵器的柄。", "cites": [{"t": "粤无镈,燕无函,秦无庐。", "b": "《周礼·考工记·总序》"}], "words": [{"w": "庐器", "t": "古代戈属兵器的柄"}, {"w": "庐人", "t": "造戈矛之柄的工匠。"}]}, {"meaning": "寄住。", "cites": [{"t": "京师之野,于时处处,于时庐旅。", "b": "《诗·大雅·公刘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('840wx','序','1','xù','广','7','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从广,予声。从广(yǎn),与房屋有关。本义:东西墙)。"}, {"meaning": "堂屋的东西墙。", "cites": [{"t": "序,东西墙也。", "b": "《说文》"}, {"t": "西序东向。", "b": "《书·顾命》"}, {"t": "奠爵于序端。", "b": "《仪礼·乡饮酒礼》"}, {"t": "直东序。", "b": "《仪礼·士冠礼》"}, {"t": "宾升,立于序内,东方。", "b": "《仪礼·燕礼》"}, {"t": "皆馔于西序下。", "b": "《仪礼·士丧礼》"}, {"t": "东西墙谓之序。", "b": "《尔雅》"}, {"t": "若陈衣于序东。", "b": "《礼记·丧大记》"}]}, {"meaning": "正屋两侧东西厢房。", "cites": [{"t": "西厢踟蹰以闲宴,东序重深而奥秘。", "b": "《文选》"}]}, {"meaning": "古代学校的别名。", "cites": [{"t": "春秋以礼会民,而射于州序。", "b": "《周礼》。郑玄注:“序,州党之学也。”"}, {"t": "殷曰痒,周曰序。", "b": "《汉书·儒林传序》"}], "words": [{"w": "序室", "t": "古代幼童读书处。"}]}, {"meaning": "次第,次序。", "cites": [{"t": "言有序。", "b": "《易·艮》"}, {"t": "与四时合其序。", "b": "《易·文言》"}, {"t": "内官序当其夜。", "b": "《左传·宣公十二年》"}, {"t": "日月忽其不淹兮,春与秋其代序。", "b": "《楚辞·离骚》"}, {"t": "长幼有序。", "b": "《荀子·君子》"}, {"t": "雁行有序。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "工序;次序;岁序;词序;语序;序秩", "t": "官序"}, {"w": "序成", "t": "第等,次序。"}]}, {"meaning": "特指官吏等级系列中的位次。", "cites": [{"t": "卿大夫以序守之。", "b": "《左传·昭公二十九年》"}]}, {"meaning": "教育。", "cites": [{"t": "神理共契,政序相参。", "b": "《文心雕龙》"}]}, {"meaning": "季节。", "cites": [{"t": "回忆海棠结社,序属清秋。", "b": "《红楼梦》"}]}, {"meaning": "序言。", "cites": [{"t": "序以建言,首引情本。", "b": "《文心雕龙》"}, {"t": "丐序于予。", "b": "孙文《黄花冈七十二烈士事略·序》"}]}, {"meaning": "又。", "cites": [{"t": "予为斯序。", "b": ""}], "words": [{"w": "序跋;序引", "t": "序和引"}, {"w": "代序;自序;序文", "t": ""}]}, {"meaning": "功业。", "cites": [{"t": "继序思不忘。", "b": "《诗·周颂·闵予小子》"}]}, {"meaning": "头绪。", "cites": [{"t": "楚王梦亦有其序。", "b": "《汉书》"}]}, {"meaning": "依次序排列。", "cites": [{"t": "序宾以贤。", "b": "《诗·大雅·行革》。毛传:“言宾客次第皆贤。”"}, {"t": "序八州而朝同列。(古时天下分九州,秦原居雍州,六国分居八州。)", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "序齿排班", "t": "序齿"}, {"w": "序位", "t": "安排位次"}, {"w": "序立", "t": "按品级站立。"}]}, {"meaning": "叙述,叙说。", "cites": [{"t": "彼此序了几句闲话。", "b": "《老残游记》"}], "words": [{"w": "序齿录", "t": "记载有关个人家事生平姻亲及其他情况的册籍。"}]}, {"meaning": "引出。", "cites": [{"t": "病身属恨管,暮景序悉端。", "b": "《骂玉郎过感皇恩采茶歌·四时闺怨·秋》"}]}, {"meaning": "草拟。", "cites": [{"t": "县里正在序稿。", "b": "《老残游记》"}, {"t": "又如:序稿(草拟文稿)", "b": ""}]}, {"meaning": "给……作序。", "cites": [{"t": "庐陵文天祥自序其诗。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "按功升官。", "cites": [{"t": "崇德序功。", "b": "《三国志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('841wx','辛','1','xīn','辛','7','','[{"pinyin": "xīn", "defs": [{"meaning": "(象形。据甲骨文,像古代刑刀。本义:大罪)。"}, {"meaning": "同本义。", "cites": [{"t": "辛,大罪也。", "b": "《说文》。段注:“辛痛泣出,罪人之象。凡辠(罪)、宰、辜、辭皆从辛者由此。”"}, {"t": "辛所以煞伤之也。", "b": "《白虎通》"}, {"t": "[隆科多] 凡四十一款,当斩,妻子入辛者库,财产入官。", "b": "《清史稿》"}]}, {"meaning": "葱蒜等带刺激性的蔬菜。", "cites": [{"t": "以辛养筋。", "b": "《周礼·疡医》"}, {"t": "辛甘行些。", "b": "《楚辞·招魂》。注:“谓椒姜也。”"}, {"t": "江南曰辣,中国曰辛。", "b": "《声类》"}, {"t": "大蒜勿食,荤辛害目。", "b": "《养生要》李善注"}, {"t": "五辛菜,乃元旦立春,以葱、蒜、韭、蓼、蒿、芥辛嫩之菜,杂和食之,取迎新之义。", "b": "《五辛菜》"}]}, {"meaning": "天干第八位与地支相配,用以纪年、月、日。", "cites": [{"t": "其日庚辛。", "b": "《礼记·月令》。注:“辛之言新也,因以为日名焉。”"}, {"t": "朔月辛卯。", "b": "《诗·小邪·十月之交》"}, {"t": "太岁在辛曰重光。", "b": "《尔雅》"}]}, {"meaning": "商帝号。", "cites": [{"t": "子辛立,是谓帝辛,天下谓之纣。", "b": "《史记》"}], "words": [{"w": "辛甲", "t": "纣臣,屡谏纣王不听,去而至周,为太史"}, {"w": "辛癸", "t": "商纣与夏桀。"}]}, {"meaning": "辣味。", "cites": [{"t": "大苦咸酸,辛甘行些。", "b": "《楚辞·招魂》"}, {"t": "曲直作酸,从草作辛。", "b": "《书·洪范》"}, {"t": "苦而微辛。", "b": "元、明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "辛刻", "t": "辛辣峻刻"}, {"w": "辛凉", "t": "辛辣清凉。"}]}, {"meaning": "劳苦;艰苦。", "cites": [{"t": "柔武以匡辛苦。", "b": "《周书》。注:“辛苦,穷也。”"}, {"t": "萦苦辛。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "东君用意不辞辛,料想春光先到处,吹绽梅英。", "b": "宋·苏轼《浪淘沙·昨日出东城》"}], "words": [{"w": "辛心", "t": "苦心"}, {"w": "辛艰", "t": "辛苦艰难"}, {"w": "辛毒", "t": "辛苦。"}]}, {"meaning": "痛苦,悲伤。", "cites": [{"t": "仓卒骨肉情,能不怀苦辛?", "b": "曹植《赠白马王彪》"}], "words": [{"w": "身受酸辛;辛楚", "t": "辛酸苦楚"}, {"w": "辛伤", "t": "悲伤"}, {"w": "辛切", "t": "悲切。"}]}, {"meaning": "酸痛。", "cites": [{"t": "胆移热于脑,则辛额鼻渊。", "b": "《素问》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('842wx','弃','1','qì','廾','7','','[{"pinyin": "qì", "defs": [{"meaning": "(会意。甲骨文字形,上面是个头向上的婴孩,三点表示羊水,头向上表示逆产。中间是只簸箕 ,下面是两只手。合起来表示将不吉利的逆产儿倒掉之意。小篆写法大同小异。本义:扔掉;抛弃)。"}, {"meaning": "同本义。", "cites": [{"t": "弃,捐也。", "b": "《说文》。段注:“弃者,不孝子人所弃也。”"}, {"t": "天之弃商也久矣。", "b": "《左传·僖公二十二年》"}, {"t": "抛子弃草间。", "b": "王粲《七哀》"}, {"t": "举以予人,如弃草芥。", "b": "苏洵《六国论》"}, {"t": "敌弃炮仓皇遁。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "子孙弃者。", "b": "清·袁枚《黄生借书说》"}, {"t": "弃其妇。", "b": "清·周容《芋老人传》"}, {"t": "弃甲投戈。", "b": "《广东军务记》"}, {"t": "弃厌(嫌弃;厌恶);弃亲(抛弃亲族);弃礼(抛弃礼制);弃秽(抛弃秽浊);弃失(丢失);弃地(丢弃田地);弃灰(把灰烬弃在路上);弃物(被丢失之物);弃国(丢失封国或都城);弃才(被遗弃的人才)", "b": ""}]}, {"meaning": "废,废除。", "cites": [{"t": "水官弃矣。", "b": "《左传·昭公二十九年》。注:“废也。”"}, {"t": "弃言(已经废弃之言);弃法(废弃法度);弃井(废井)", "b": ""}]}, {"meaning": "忘记。", "cites": [{"t": "弃,忘也。", "b": "《尔雅》"}, {"t": "其庸可弃乎。", "b": "《左传·昭公十三年》。注:“犹忘。”"}, {"t": "弃忽(遗忘,忽略)", "b": ""}]}, {"meaning": "离开。", "cites": [{"t": "子弃寡人。", "b": "《战国策·秦策》。注:“去也。”"}, {"t": "弃予(离开我);弃代(去世)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('843wx','冶','1','yě','冫','7','','[{"pinyin": "yě", "defs": [{"meaning": "(形声。从冫(古“冰”字),台(yí)声。以冰融化解释金属销熔。段玉裁:“冰之融如铄金然,故炉铸亦曰冶。”本义:销熔)。"}, {"meaning": "同本义。", "cites": [{"t": "冶,销也。", "b": "《说文》"}, {"t": "冶,销铄也。", "b": "《三苍》"}, {"t": "良冶之子。", "b": "《礼记·学记》"}, {"t": "冶铸煮盐。", "b": "《史记·平淮书》"}], "words": [{"w": "冶铸", "t": "冶炼铜铁,铸造器物"}, {"w": "冶锻", "t": "冶炼"}, {"w": "冶人", "t": "犹冶工"}, {"w": "冶工", "t": "铸造金属器物的工人"}, {"w": "冶士", "t": "古代从事冶炼铸造的刑徒。"}]}, {"meaning": "陶冶。", "cites": [{"t": "当是时,文王能陶冶天下之士。", "b": "王安石《上仁宗皇帝言事书》"}]}, {"meaning": "田野,郊原。", "cites": [{"t": "冶游步春露。", "b": "古乐府《子夜四时歌》"}, {"t": "是以时人谓之冶葛。", "b": "《北史·诸葛颖传》"}, {"t": "不知身属冶游郎。", "b": "李商隐《无题》"}]}, {"meaning": "艳丽。", "cites": [{"t": "美丽姚冶。", "b": "《荀子·非相》"}, {"t": "纨袖渐冶,王颜掩姱。", "b": "谢惠连《雪赋》"}], "words": [{"w": "冶阳天", "t": "艳阳天"}, {"w": "冶逸", "t": "容貌艳丽,神采飞扬"}, {"w": "冶服", "t": "华丽的服装"}, {"w": "冶丽", "t": "美丽异常;指美丽的女子"}, {"w": "冶色", "t": "容颜美好。"}]}, {"meaning": "容态妖媚。", "cites": [{"t": "冶容诲淫。", "b": "《易·系辞上》"}], "words": [{"w": "冶由", "t": "妩媚的笑态"}, {"w": "冶步", "t": "步态妖冶妩媚。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('844wx','忘','1','wàng','心','7','','[{"pinyin": "wàng", "defs": [{"meaning": "(会意兼形声。从心,从亡,亡亦声。本义:忘记,不记得)。"}, {"meaning": "同本义。", "cites": [{"t": "忘,不识也。", "b": "《说文》"}, {"t": "德音不忘。", "b": "《诗·郑风·有女同车》"}, {"t": "中年病忘。", "b": "《列子·周穆王》。释文:“不记事也。”"}, {"t": "忘路之远近。", "b": "晋·陶渊明《桃花源记》"}, {"t": "宠辱偕忘。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "忘身于外。", "b": "诸葛亮《出师表》"}], "words": [{"w": "忘魂", "t": "忘怀"}, {"w": "忘昏", "t": "忘怀"}, {"w": "忘反", "t": "流连忘归"}, {"w": "忘年", "t": "忘记年岁"}, {"w": "忘味", "t": "忘记美食的滋味"}, {"w": "忘食", "t": "忘了吃饭"}, {"w": "忘却", "t": "不记得"}, {"w": "忘生舍死", "t": "忘却性命,不怕牺牲"}, {"w": "忘先", "t": "忘记祖先。"}]}, {"meaning": "玩忽,怠忽。", "cites": [{"t": "夙夜不敢忘怠。", "b": "唐·韩愈《潮州祭神文》"}]}, {"meaning": "逃亡;遗失;灭亡。", "cites": [{"t": "乐隤心其如忘。", "b": "《文选·陆机·叹逝赋》"}, {"t": "敷前人受命,兹不忘大功。", "b": "《书·大诰》"}, {"t": "佩玉将将,寿考不忘。", "b": "《诗·秦风·终南》"}, {"t": "不愆不忘,率由旧章。", "b": "《诗·大雅·假乐》"}, {"t": "今日不为,明日忘贷。", "b": "《管子·乘马》"}, {"t": "臣闻子胥尽忠而忘其号。", "b": "《汉书·武五子传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('845wx','闰','1','rùn','门','7','','[{"pinyin": "rùn", "defs": [{"meaning": "(会意。从“王在门中”。古代天子每年冬季以明年朔政分赐诸侯,诸侯于月初祭庙受朔政称为“告朔”。据《说文》段注,举行告朔之礼时,王通常居于明堂,但逢闰月,则居于路寝门,所以“从王在门中。”本义:余数。指历法纪年和地球环绕太阳一周运行时间的差数,多余的叫“闰”。如“闰月”) 同本义。", "cites": [{"t": "闰,余分之月,五岁再闰。", "b": "《说文》"}, {"t": "闰月诏王居门终月。", "b": "《周礼·大史》"}, {"t": "闰月则阖门左扉。", "b": "《礼记·玉藻》"}, {"t": "以闰月定四时成岁。", "b": "《书·尧典》"}, {"t": "光绪十六年春闰二月甲子。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "闰秋", "t": "闰九月"}, {"w": "闰法", "t": "设闰月的方法"}, {"w": "闰余", "t": "农历一年多出回归年的时日"}, {"w": "闰双", "t": "农历三年一闰,五年再闰,再闰叫闰双"}, {"w": "闰分", "t": "农历一年多出回归年的时日。"}]}, {"meaning": "副;偏;伪。对“正”而言。", "cites": [{"t": "区别正闰。", "b": "《宋史·宋庠传》"}], "words": [{"w": "闰位", "t": "非正统的帝位"}, {"w": "闰统", "t": "指僭位的帝统。对正统而言"}, {"w": "闰徵", "t": "变徵"}, {"w": "闰集", "t": "旧时正集后附录的僧、道、妇人等的作品"}, {"w": "闰朝", "t": "伪朝"}, {"w": "闰升", "t": "例外被提升"}, {"w": "闰宫", "t": "变宫。五音中只有宫徵有变。"}]}, {"meaning": "滋润。", "cites": [{"t": "主闰宗筋。", "b": "《素问·痿论篇》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('846wx','闲','1','xián','门','7','','[{"pinyin": "xián", "defs": [{"meaning": "(会意。从门中有木。本义:栅栏)。"}, {"meaning": "同本义。", "cites": [{"t": "闲,阑也。", "b": "《说文》"}, {"t": "人闲有家。", "b": "《易·家》。注;“阑也。”"}, {"t": "日闲舆卫。", "b": "《易·大畜》。注:“阂也。”"}, {"t": "舍则守王闲。", "b": "《周礼·虎贲氏》。郑玄注:“闲,梐枑。”贾公彦疏:“闲与梐枑皆禁卫之物。”"}]}, {"meaning": "马厩,关养马的地方。", "cites": [{"t": "天子十有二闲,马六种。", "b": "《周礼·夏官》"}, {"t": "龙与闲驹。", "b": "《汉书·百官表》"}], "words": [{"w": "闲厩", "t": "古代皇家养牲口的地方"}, {"w": "闲驹", "t": "养马之所。"}]}, {"meaning": "伦理道德的规范、界限。", "cites": [{"t": "掌十有二闲之政教。", "b": "《周礼·痩人》"}, {"t": "大德不逾闲,小德出入可也。", "b": "《论语·子张》"}]}, {"meaning": "阻隔。", "cites": [{"t": "亲非其肤,…中心闲也。", "b": "《太玄经》"}], "words": [{"w": "闲间", "t": "间隔。"}]}, {"meaning": "限制,约束。", "cites": [{"t": "虽收放心,闲之维艰。", "b": "《书·毕命》"}, {"t": "闲之以义。", "b": "《左传·昭公六年》"}], "words": [{"w": "闲检", "t": "约束检点"}, {"w": "闲节", "t": "限制;约束。"}]}, {"meaning": "熟悉、熟练", "cites": [{"t": "闲于兵甲,习于战攻。", "b": "《战国策·燕策二》"}, {"t": "兵入则振旅,以闲习之,因于彼狩,存不忘亡,安不忘危。", "b": "《春秋繁露·五行逆顺》"}, {"t": "谢安石有庙堂之量,不闲将略。", "b": "《肥水之战》"}], "words": [{"w": "闲习", "t": "熟习"}, {"w": "闲晓", "t": "熟悉"}, {"w": "闲博", "t": "熟习博通。"}]}, {"meaning": "防止。", "cites": [{"t": "建极闲邪。(建立准则,防止邪说。)", "b": "刘禹锡《天论》"}]}, {"meaning": "闲暇。", "cites": [{"t": "止于坐隅兮,貌甚闲暇。", "b": "贾谊《鹏鸟赋》"}, {"t": "闲来垂钓。", "b": "唐·李白《行路难》"}, {"t": "闲驱泾水。", "b": "唐·李朝威《柳毅传》"}, {"t": "人闲桂花落(“闲”通“閒”)。", "b": "唐·王维《鸟鸣涧》"}, {"t": "田家少闲月,五月人倍忙。", "b": "唐·白居易《观刈麦》"}], "words": [{"w": "闲男女", "t": "糊涂虫,蠢傢伙"}, {"w": "闲踢蹬", "t": "闲游逛"}, {"w": "闲戏", "t": "闲嬉。游戏,玩耍"}, {"w": "闲遥遥", "t": "闲邀邀,闲摇摇。悠闲自在或闲散无聊。"}]}, {"meaning": "空着,没使用。", "cites": [{"t": "又多闲田。", "b": "清·龚自珍《病梅馆记》"}, {"t": "野无闲田。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "闲田闲地;闲屋", "t": "无人居住的房屋"}, {"w": "闲壤", "t": "闲置的土地"}, {"w": "闲园", "t": "荒园。"}]}, {"meaning": "悠闲。", "cites": [{"t": "闲抱琵琶寻旧曲,远山眉黛绿。", "b": "前蜀·韦庄《谒金门》"}], "words": [{"w": "闲晏", "t": "悠闲安逸"}, {"w": "闲素", "t": "悠闲纯朴"}, {"w": "闲肆", "t": "悠闲自然"}, {"w": "闲蹓", "t": "闲逛。散步。"}]}, {"meaning": "空虚。", "cites": [{"t": "向来的幻境安在,回首总成闲。", "b": "刘克庄《水调歌头·和西外判宗湖楼韵之三》"}], "words": [{"w": "闲宵", "t": "寂寞无聊的夜晚。"}]}, {"meaning": "安静。", "cites": [{"t": "质真而素朴,闲静而不躁。", "b": "《淮南子·本经》"}, {"t": "闲亭独坐。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "闲裕", "t": "安静从容"}, {"w": "闲旷", "t": "安静空旷"}, {"w": "闲邃", "t": "闲静深远"}, {"w": "闲默", "t": "安静沉默。"}]}, {"meaning": "娴雅", "cites": [{"t": "妖冶闲都。", "b": "《汉书·司马相如传上》"}, {"t": "美女妖且闲,採桑歧路间。", "b": "曹植《美女篇》"}], "words": [{"w": "闲整", "t": "闲雅整洁"}, {"w": "闲媚", "t": "娴雅柔美;闲雅妩媚。"}]}, {"meaning": "大。", "cites": [{"t": "闲显轩敞,云屋晧旰。", "b": "《文选·曹植·七启》"}]}, {"meaning": "空阔;宽大。", "cites": [{"t": "像设居室,静闲安些。", "b": "《楚辞》"}, {"t": "烟水闲,乾坤大,四面云无遮碍。", "b": "元·张养浩《普天乐》"}], "words": [{"w": "闲燥", "t": "宽敞"}, {"w": "闲敞", "t": "广阔空旷。"}]}, {"meaning": "空闲的时间。", "cites": [{"t": "时人不识余心乐,将谓偷闲学少年。", "b": "程颢《春日偶成》"}]}, {"meaning": "闲职。", "cites": [{"t": "投闲置散了,乃分之宜。", "b": "韩愈《进学解》"}]}, {"meaning": "“閒”另见jiān“间”;jiàn“间”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('847wx','间','1','jiān jiàn','门','7','','[{"pinyin": "jiān", "defs": [{"meaning": "(间是后起字,本字作閒,本义见间jiàn)。"}, {"meaning": "中间;内。", "cites": [{"t": "一动一静者,天地之閒也。", "b": "《礼记·乐记》"}, {"t": "而独閒数百千里。", "b": "《汉书·严助传》。注:“中间也。”"}, {"t": "攘臂于其閒。", "b": "《庄子·人间世》。司马注:“犹里也。”"}, {"t": "黄河远上白云间。", "b": "唐·王之涣《凉州词》"}, {"t": "林间窥之。", "b": "唐·柳宗元《三戒》"}, {"t": "草木之间。", "b": "明·袁宏道《袁中郎全集·满井游记》"}, {"t": "达于缙绅间。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "出于其间。", "b": "蔡元培《图画》"}], "words": [{"w": "两地之间;上下之间;左右之间;半中间;两个高楼间的小弄;两个电极间的真空", "t": ""}]}, {"meaning": "一会儿,顷刻。", "cites": [{"t": "莫然有间,而子桑户死。", "b": "《庄子·大宗师》"}, {"t": "乃留止閒曰。", "b": "《战国策·秦策》"}], "words": [{"w": "间不容息", "t": "其时间不容喘息。比喻时间短促。"}]}, {"meaning": "近来。", "cites": [{"t": "帝间颜色瘦黑。", "b": "《汉书·叙传上》"}]}, {"meaning": "姓(閒)。"}, {"meaning": "表示房屋的量詞。", "cites": [{"t": "安得广厦千萬间。", "b": "唐·杜甫《茅屋为秋風所破歌》"}], "words": [{"w": "一间卧室;三间門面", "t": ""}]}, {"meaning": "另見jiàn;。"}, {"meaning": "“间”另见xián。"}]}, {"pinyin": "jiàn", "defs": [{"meaning": "(会意。古写作“閒”,“间”是后起字。金文,从门,从月。段玉裁《说文解字注》:“开门月入,门有缝而月光可入。”(jiàn) 本义:门缝)。"}, {"meaning": "同本义。泛指缝隙;空隙。", "cites": [{"t": "閒,隙也。从門,中见月。会意。", "b": "《说文》"}, {"t": "有閒中也。又,閒不及旁也。", "b": "《墨子经》"}, {"t": "其閒不能以寸。", "b": "《孟子》"}, {"t": "从门閒而窥其夫。—《史记·管晏传》", "b": ""}, {"t": "彼节者有间。", "b": "《庄子·养生主》"}, {"t": "以无厚入有间。", "b": ""}, {"t": "得间奔真州。", "b": "宋·文天祥《 后序》"}], "words": [{"w": "间出", "t": "乘隙私出,微行"}, {"w": "间缺", "t": "空隙"}, {"w": "间蹊", "t": "小道"}, {"w": "间径", "t": "小道;僻路。"}]}, {"meaning": "隔阂;嫌隙。", "cites": [{"t": "时将有反,事将有间。", "b": "《国语·越语下》"}]}, {"meaning": "挑拔,使人不和。", "cites": [{"t": "谗人间之。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "离间", "t": "挑拔使之不和睦"}, {"w": "间构", "t": "离间构陷,挑拔中伤"}, {"w": "间疏", "t": "离间"}, {"w": "间貳", "t": "离间"}, {"w": "间书", "t": "用以挑拔是非的信。"}]}, {"meaning": "隔开间隔。", "cites": [{"t": "枫松相间。", "b": "《徐霞客游记·游黄山记》"}, {"t": "病间月。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "间行", "t": "拉开距离行进"}, {"w": "间阔", "t": "久别;远离"}, {"w": "间岁", "t": "隔一年"}, {"w": "间世", "t": "隔代。"}]}, {"meaning": "夹杂;参杂。", "cites": [{"t": "中间力拉。", "b": "《虞初新志·秋声诗序》"}], "words": [{"w": "间色", "t": "杂"}, {"w": "间错", "t": "间杂"}, {"w": "间编", "t": "编次杂乱"}, {"w": "间厕", "t": "夹杂"}, {"w": "间诂", "t": "夹注。"}]}, {"meaning": "参与。", "cites": [{"t": "肉食者谋之,又何间焉!", "b": "《左传·庄公十年》"}]}, {"meaning": "更迭;交替。", "cites": [{"t": "异才复间出,周道日惟新。", "b": "杜甫《别蔡十四著作》"}], "words": [{"w": "间歌", "t": "古时吹笙和唱歌相交替的一种礼制"}, {"w": "间出", "t": "隔世而出"}, {"w": "间生", "t": "隔世而生。"}]}, {"meaning": "间或,断断续续。", "cites": [{"t": "时时而间进。", "b": "《战国策·齐策》"}, {"t": "间道经其门。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "间以诗记所遭。", "b": "宋·文天祥《 后序》"}, {"t": "间则蹑屐。", "b": "明·刘基《诚意伯刘文成公文集》"}]}, {"meaning": "秘密,暗中(隔开众人,使自己隐而不现)。", "cites": [{"t": "又间令吴广之次所旁丛祠中。", "b": "《史记·陈涉世家》"}, {"t": "侯生乃屏人间语。", "b": "《史记·魏公子列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('848wx','闷','1','mēn mèn','门','7','','[{"pinyin": "mēn", "defs": [{"meaning": "气闷,因气不通畅而引起的不快之感。", "cites": [{"t": "闭则热而闷。", "b": "《素问·风论》"}], "words": [{"w": "闷吐", "t": "心闷想吐"}, {"w": "闷绝", "t": "晕倒。一说窒息而死"}, {"w": "闷痒", "t": "因身体不舒爽而发痒"}, {"w": "闷窒", "t": "窒息"}, {"w": "闷躁", "t": "气闷烦躁。"}]}, {"meaning": "沉默不出声或声音不响的样子。", "cites": [{"t": "闷然而后应。", "b": "《庄子·德充符》"}], "words": [{"w": "闷默", "t": "静默不出声"}, {"w": "闷闷", "t": "闷声不响。"}]}]}, {"pinyin": "mèn", "defs": [{"meaning": "(形声。从心,门声。本义:烦闷;愤懑)。"}, {"meaning": "同本义。", "cites": [{"t": "闷,懑也。", "b": "《说文》"}, {"t": "遯世无闷。", "b": "《易·乾卦》。疏:“谓逃遯避世,虽逢无道,心无所闷。”"}, {"t": "中闷瞀之忳忳。", "b": "《楚辞·九章·惜诵》"}, {"t": "忧闷欲死。", "b": "《聊斋志异·促织》"}], "words": [{"w": "闷闷渴渴", "t": "形容烦闷苦恼"}, {"w": "闷怀顿释", "t": "心中的忧虑、烦闷一下子就消失了"}, {"w": "闷恹恹", "t": "精神疲乏,心情烦闷"}, {"w": "闷嗗咄", "t": "闷闷的一声不响。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('849wx','判','1','pàn','刂','7','','[{"pinyin": "pàn", "defs": [{"meaning": "(形声兼会意。从刀,半声。从刀,表明其意义与刀有联系。“半”是把牛分开。本义:分,分开)。"}, {"meaning": "同本义。", "cites": [{"t": "判,分也。", "b": "《说文》"}, {"t": "继犹判涣。", "b": "《诗·周颂·访落》"}, {"t": "纪于是乎判。", "b": "《左传·庄公三年》"}, {"t": "若七德离判,民乃携贰。", "b": "《国语·周语中》"}, {"t": "遂判为十二,合为七国,威分于陪臣之邦。", "b": "柳宗元《封建论》"}], "words": [{"w": "判割", "t": "分割"}, {"w": "判妻", "t": "丈夫去世或与丈夫离异后再嫁的妇女"}, {"w": "判散", "t": "分散"}, {"w": "判礼", "t": "分离;分开"}, {"w": "判迹", "t": "分道而行"}, {"w": "判裂", "t": "割裂;分离。"}]}, {"meaning": "判决。", "cites": [{"t": "太尉判状辞甚巽(恭顺)。", "b": "唐·柳宗元《段太尉逸事状》"}], "words": [{"w": "审判", "t": "审理和判决"}, {"w": "判词", "t": "判决的文词"}, {"w": "判牍", "t": "判决司法案件的文书"}, {"w": "判有罪;判无罪", "t": ""}]}, {"meaning": "区别;分辨。", "cites": [{"t": "判天地之美,析万物之理。", "b": "《庄子·天下》"}, {"t": "故不战而强弱胜负已判矣。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "判别是非;判正", "t": "分辨是非曲直。"}]}, {"meaning": "舍弃。", "cites": [{"t": "海波无底珠沉海,采珠之人判死采。", "b": "元稹《采珠行》"}]}, {"meaning": "半。", "cites": [{"t": "凡有责者有判书。", "b": "《周礼·朝士》。注:“半分而合者。”"}, {"t": "卿大夫判县。", "b": "《周礼·小胥》。按:“宫县四面,判县两面。”"}, {"t": "掌万民之判。", "b": "《周礼·媒氏》"}, {"t": "璋判白。", "b": "《公羊传·定公八年》"}, {"t": "天地判合。", "b": "《汉书·翟义传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('850wx','兑','1','duì','丷','7','','[{"pinyin": "duì", "defs": [{"meaning": "(会意。从人,从囗,八象气之舒散,兄者与祝同意。从八,与曾同意,今字作悦。本义:喜悦)。"}, {"meaning": "同本义。", "cites": [{"t": "兑,说也。", "b": "《说文》"}, {"t": "兑为口。", "b": "《易·说卦》"}, {"t": "兑者说也。", "b": "《易·序卦》"}, {"t": "佞兑而不曲。", "b": "《荀子·脩身》。注:“兑,悦也。”"}, {"t": "见由则兑而倨。", "b": "《荀子·不苟》"}, {"t": "豫通而不失乎兑。", "b": "《庄子·德充符》"}, {"t": "多兑道以为上。", "b": "《管子·七臣七主》"}, {"t": "祷祠而求福,雩兑而请雨。", "b": "《淮南子·泰族》"}], "words": [{"w": "兑悦", "t": "喜悦。"}]}, {"meaning": "锋利。", "cites": [{"t": "两铤交之置如平,不如平不利,兑其两末。", "b": "《墨子·备城门》"}, {"t": "为人巧转而兑利。", "b": "《管子·小匡》"}, {"t": "兑则若莫邪之利锋。", "b": "《荀子·议兵》"}, {"t": "前列直斗口三星,随北端兑,若见若不。", "b": "《史记·天官书》"}]}, {"meaning": "拼。", "cites": [{"t": "你这剪径的毛团,我须是认得你,做这老性命不着,与你兑了罢!", "b": "元·佚名《京本通俗小说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('851wx','灶','1','zào','火','7','','[{"pinyin": "zào", "defs": [{"meaning": "(会意。从火从土。繁体从穴,鼀(cù)声。本义:用砖石等砌成,供烹煮食物、烧水的设备)。"}, {"meaning": "同本义。", "cites": [{"t": "灶,炊穴也。", "b": "《说文》"}, {"t": "灶者,火之主。人所以自养也。", "b": "《白虎通·五祀》"}, {"t": "灶烟阳。", "b": "《汉书·五行志》"}, {"t": "灶者,老妇之祭也。", "b": "《礼记·郊特牲》"}, {"t": "井灶有遗处,桑竹残朽株。", "b": "陶渊明《归园田居》"}], "words": [{"w": "灶床脚", "t": "紧靠炉灶旁边的地面"}, {"w": "锅灶;行军灶;灶妄", "t": "掌炉煮饭的婢女"}, {"w": "灶下养", "t": "厨役。古代对厨师的贱称"}, {"w": "灶燎", "t": "上灶头烧火。"}]}, {"meaning": "灶神。", "cites": [{"t": "夏为太阳,其气长养,祀之于灶。", "b": "蔡邕《独断》"}, {"t": "接着一声钝响,是送灶的爆竹。", "b": "鲁迅《彷徨·祝福》"}], "words": [{"w": "灶王", "t": "也称“灶王爷”。灶神的俗称"}, {"w": "灶公", "t": "灶神的俗称。相传灶神上天奏事直言不讳,因喻正直的人"}, {"w": "灶马", "t": "木刻印刷在纸上的灶神像;灶神的坐骑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('852wx','灿','1','càn','火','7','','[{"pinyin": "càn", "defs": [{"meaning": "(形声。从火,粲声。本义:灿烂,光彩鲜明耀眼)。"}, {"meaning": "同本义。", "cites": [{"t": "灿若图绣。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "灿然", "t": "明亮"}, {"w": "灿灿", "t": "闪闪发光的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('853wx','灼','1','zhuó','火','7','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从火,勺声。本义:烧,灸)。"}, {"meaning": "同本义。", "cites": [{"t": "灼,炙也。", "b": "《说文》"}, {"t": "皆忧心如火灼烂之矣。", "b": "《诗·节南山》笺"}, {"t": "征丝灼之。", "b": "《史记·龟策传》"}, {"t": "不可灼也。", "b": "《淮南子·泛论》"}, {"t": "唐虞点灼而毁议。", "b": "《楚辞》"}, {"t": "无若火始焰焰,厥攸灼叙,弗其绝。", "b": "《书·洛诰》"}], "words": [{"w": "灼艾", "t": "燃烧艾绒熏灸人体一定的穴位"}, {"w": "灼臂落发", "t": "烧炙手臂剃去头发。佛教徒表示自我忏悔的一种方式"}, {"w": "灼火", "t": "燃火。"}]}, {"meaning": "烫伤。", "cites": [{"t": "泉源沸涌,浩气云浮,以腥物投之,俄倾即熟,其中时有细赤鱼游之,不为灼也。", "b": "《水经注》"}]}, {"meaning": "照亮,用光亮照明。", "cites": [{"t": "皆仆掩门户。以烛灼之,惧有野犬留厨下。", "b": "徐珂《清稗类钞》"}], "words": [{"w": "灼灼", "t": "鲜明;明亮的样子"}, {"w": "灼天", "t": "照亮天空"}, {"w": "灼夜", "t": "照亮黑夜。"}]}, {"meaning": "(zhuō)。明亮,鲜明。", "cites": [{"t": "灼见三有俊心。", "b": "《书·立政》"}]}, {"meaning": "又。", "cites": [{"t": "我其克灼知厥若。", "b": ""}, {"t": "灼绣颈而衮背。", "b": "潘岳《射雉赋》"}], "words": [{"w": "灼灼辉辉", "t": "明亮炽盛"}, {"w": "灼耀", "t": "明亮耀眼"}, {"w": "灼如", "t": "昭明显赫的样子"}, {"w": "灼粲", "t": "光辉灿烂"}, {"w": "灼眼", "t": "明亮耀眼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('854wx','弟','1','dì','弓','7','','[{"pinyin": "dì", "defs": [{"meaning": "(象形。甲骨文字形,象有绳索围绕于“弋”,象竖立有杈的短木桩。绳索捆束木桩,就出现了一圈一圈的“次第”。本义:次第)。"}, {"meaning": "同本义。", "cites": [{"t": "弟,韦束之次第也。", "b": "《说文》"}, {"t": "乱必有弟。大乱五,小乱三。", "b": "《吕氏春秋·原乱》"}]}, {"meaning": "弟弟。", "cites": [{"t": "男子先生为兄,后生为弟。", "b": "《尔雅·释亲》"}, {"t": "如兄如弟。", "b": "《诗·邶风·谷风》"}, {"t": "称小功以下为兄弟,大功以上为昆弟。", "b": "《仪礼·丧服》"}, {"t": "联兄弟。", "b": "《周礼·大司徒》。注:“兄弟婚姻嫁聚也。”"}], "words": [{"w": "弟老的", "t": "排行最小的"}, {"w": "弟郎", "t": "兄弟"}, {"w": "弟兄相狱", "t": "兄弟相互诉讼"}, {"w": "弟昆", "t": "弟兄"}, {"w": "弟息", "t": "弟弟与儿子"}, {"w": "弟道", "t": "做弟弟应遵守的道德标准。"}]}, {"meaning": "古代亦称妹为弟。", "cites": [{"t": "弥子之妻与子路之妻,兄弟也。", "b": "《孟子》"}]}, {"meaning": "敬爱兄长。", "cites": [{"t": "孝弟也者,其为人之本兴?", "b": "《论语·学而》"}, {"t": "国有礼有乐,有诗有画,有善有修,有孝有弟,有廉有辩。", "b": "《商君书·去强》"}, {"t": "能以事亲谓之孝,能以事兄谓之弟,能以事上谓之顺,能以使下谓之君。", "b": "《荀子·王制》"}, {"t": "僚友称其弟也。", "b": "《礼记·曲礼上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('855wx','汪','1','wāng','氵','7','','[{"pinyin": "wāng", "defs": [{"meaning": "(形声。从水,王声。本义:深广的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "汪,深广也。", "b": "《说文》"}, {"t": "汪是土也。", "b": "《国语·晋语》。注:“大貌。”"}, {"t": "泽汪濊。", "b": "《汉书·礼乐志》"}, {"t": "汪汪若千顷陂。", "b": "《后汉书·班彪传》"}], "words": [{"w": "汪波", "t": "盈盈水波"}, {"w": "汪汪", "t": "水宽广的样子"}, {"w": "汪浵", "t": "水深的样子"}, {"w": "汪流", "t": "水深的样子"}, {"w": "汪然", "t": "深广的样子"}, {"w": "汪茫", "t": "气势广大的样子;广阔无边的样子"}, {"w": "汪翔", "t": "广博。"}]}, {"meaning": "弯曲的。", "cites": [{"t": "曲则全,汪则正。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "池。指污浊的小水坑。", "cites": [{"t": "渟水曰汪。", "b": "《通俗文》"}, {"t": "尸之周氏之汪。", "b": "《左传·桓公十五年》"}], "words": [{"w": "汪坑", "t": "水坑,池沼。"}]}, {"meaning": "古地名。故地约在今陕西省白水县境。", "cites": [{"t": "伐秦,取汪及彭衙而还。", "b": "《左传》"}]}, {"meaning": "狗叫声。", "cites": [{"t": "汪的一口,把头血淋淋的咬将下来。", "b": "《西游记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('856wx','沐','1','mù','氵','7','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从水,木声。本义:洗头发)。"}, {"meaning": "同本义。", "cites": [{"t": "沐,濯发也。", "b": "《说文》"}, {"t": "予发曲局,薄言归沫。", "b": "《诗·小雅·采绿》"}, {"t": "共王之沐浴。", "b": "《周礼·宫人》"}, {"t": "沐则心覆。", "b": "《左传》"}, {"t": "诸侯皆有汤沐之邑也。", "b": "《公羊传·隐公八年》"}, {"t": "夫子助之沫椁。", "b": "《礼记·檀弓》"}, {"t": "且沐者,去首垢也,洗去足垢,盥去手垢,浴去身垢,皆去一形之垢,其实等也。", "b": "《论衡·讥日》"}, {"t": "新沐者必弹冠,新浴者必振衣。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "沐发", "t": "洗发"}, {"w": "沐澡", "t": "洗头洗澡"}, {"w": "沐濯", "t": "洗头洗澡"}, {"w": "沐芳", "t": "用香草水洗头"}, {"w": "沐巾", "t": "洗发用的巾"}, {"w": "沐盆", "t": "盥洗盆"}, {"w": "栉风沐雨", "t": ""}]}, {"meaning": "芟除。", "cites": [{"t": "沐涂树之枝。", "b": "《管子》"}], "words": [{"w": "沐树", "t": "芟除树枝,使之无荫。"}]}, {"meaning": "水名。即中国山东省弥河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('857wx','沛','1','pèi','氵','7','','[{"pinyin": "pèi", "defs": [{"meaning": "(形声。从水,市(bèi)声。本义:沛水)。"}, {"meaning": "同本义。", "cites": [{"t": "沛,沛水。出辽东番汗塞外,西南入海。", "b": "《说文》"}]}, {"meaning": "泽名。沛泽。", "cites": [{"t": "齐侯田于沛。", "b": "《左传·昭二十年》。注:“沛,泽名。”"}]}, {"meaning": "多水草的沼泽地。", "cites": [{"t": "大陷于沛泽之中。", "b": "《公羊传·僖公四年》。注:“草棘曰沛。”"}, {"t": "犹逸禽之赴深林,蝱虫内之趣大沛。", "b": "《后汉书·崔骃传》"}]}, {"meaning": "蓄积用来灌田的水。", "cites": [{"t": "浙中…少水,人家多于山上置闸蓄水,遇旱岁开以灌田,名之曰沛,取沛然之义也。", "b": "《三余赘笔》"}]}, {"meaning": "旗,幡。", "cites": [{"t": "丰其沛,日中见沫。", "b": "《易·丰》"}]}, {"meaning": "水势湍急的样子,泛指盛,大。", "cites": [{"t": "沛,水波流也。", "b": "《一切经音义》"}, {"t": "民归之,由水之就下,沛然谁能御之。", "b": "《孟子·梁惠王上》"}, {"t": "焚沛泽。", "b": "《管子·揆度》。注:“大泽也。”"}, {"t": "沛焉竞溢。", "b": "王褒《洞箫赋》"}, {"t": "河水沛沛,比夫众川,孰者为大?", "b": "《论衡·自纪》"}], "words": [{"w": "充沛;沛沛", "t": "水盛大的样子"}, {"w": "沛若", "t": "盛大的样子"}, {"w": "沛然", "t": "充盛的样子;盛大的样子"}, {"w": "沛发", "t": "大量涌出"}, {"w": "沛泽", "t": "盛大的恩泽。"}]}, {"meaning": "雨盛大的样子。", "cites": [{"t": "天油然作云,沛然下雨。", "b": "《孟子·梁惠王上》"}, {"t": "冻雨沛其洒涂。", "b": "张衡《思玄赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('858wx','汰','1','tài','氵','7','','[{"pinyin": "tài", "defs": [{"meaning": "淘洗。", "cites": [{"t": "作热汤,于大盆中浸豆黄。良久,淘汰,挪去黑皮,漉而蒸之。", "b": "《齐民要术》"}]}, {"meaning": "洗涤、清洗。", "cites": [{"t": "总为设教令,明赏罚,磨治洗汰,其俗一变。", "b": "《新唐书·马总传》"}]}, {"meaning": "波涛。", "cites": [{"t": "汰,波也。", "b": "《广雅》"}, {"t": "齐吴榜以击汰。", "b": "《楚词·屈原·涉江》"}], "words": [{"w": "汰沃", "t": "大水流动的声音。"}]}, {"meaning": "骄泰;奢侈。", "cites": [{"t": "般乐奢汰。", "b": "《荀子·仲尼》。注:“侈也。”"}, {"t": "其事行也若是其险汙淫汰也!", "b": ""}, {"t": "汰哉淑氏,专以礼许人。", "b": "《礼记·檀弓上》"}, {"t": "君臣衣服舆马甚汰,吾欲禁之,可乎?", "b": "《说苑·反质》"}], "words": [{"w": "汰侈", "t": "骄奢"}, {"w": "汰虐", "t": "骄奢残暴"}, {"w": "汰流", "t": "骄纵"}, {"w": "汰然", "t": "骄矜的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('859wx','沥','1','lì','氵','7','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从水,歷声。字又作“砯”,从石从水会意。本义:踩着石头过河)。"}, {"meaning": "水、泪、酒等液体下滴。", "cites": [{"t": "动滴沥以成响,殷雷应其若警。", "b": "汉·王延寿《鲁灵光殿赋》"}, {"t": "以杓酌油沥之。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "沥血", "t": "刺破皮肤使滴血,以发誓、表竭诚或作祭祀"}, {"w": "沥液", "t": "水滴"}, {"w": "沥滴", "t": "水下滴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('860wx','沙','1','shā shà','氵','7','','[{"pinyin": "shā", "defs": [{"meaning": "(会意。从水,从少。《说文》:“水少沙见。”金文字形,左边是水,右边“少”象沙粒形。本义:极细碎的石粒)。"}, {"meaning": "同本义。", "cites": [{"t": "沙,水中散石也。", "b": "《说文》。字亦作砂。"}, {"t": "于沙。", "b": "《易·需》。荀注:“水中之刚。故曰沙。”"}, {"t": "剽土之次曰五沙。五沙之状,粟焉。如屑尘厉。", "b": "《管子·地员》"}, {"t": "白沙山广员三百里。尽沙也。", "b": "《北山经》"}, {"t": "红壁丹沙。", "b": "《楚辞·招魂》"}, {"t": "胡关饶风沙,萧索竟终古。", "b": "李白《古风》"}, {"t": "绿杨荫里白沙堤。", "b": "白居易《钱塘湖春行》"}], "words": [{"w": "沙芦", "t": "泥沙里的芦苇"}, {"w": "沙砾", "t": "细沙和碎石。也作砂砾"}, {"w": "沙坛", "t": "沙祭坛"}, {"w": "沙路;沙堤;沙痕", "t": "沙上的痕迹"}, {"w": "沙泉", "t": "沙上涌出的泉水"}, {"w": "沙府", "t": "铺沙的墓穴。"}]}, {"meaning": "沙滩。水边或水中由沙子淤积成的陆地。", "cites": [{"t": "凫鷖在沙。", "b": "《诗·大雅·凫鷖》"}], "words": [{"w": "沙线", "t": "地图上表明航道上暗滩的虚线"}, {"w": "沙涂", "t": "沙泥沉积而成的浅滩"}, {"w": "沙步", "t": "沙滩边渡口"}, {"w": "沙洪", "t": "由流沙淤积而成的大暗滩"}, {"w": "沙路", "t": "沙滩上的路;沙石路"}, {"w": "沙际", "t": "沙滩或沙洲边"}, {"w": "沙屿", "t": "沙滩和小岛"}, {"w": "沙碛", "t": "沙滩;沙洲。"}]}, {"meaning": "古有时通“纱”。指绢之轻细者。", "cites": [{"t": "素沙者今之白缚也,……今世有沙縠者,名出于此。", "b": "《周礼·天官·内司服》郑注"}, {"t": "白沙在涅,与之俱黑。", "b": "《荀子·劝学》"}]}]}, {"pinyin": "shà", "defs": [{"meaning": "", "words": [{"w": "把米里的稗子沙一沙", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('861wx','汽','1','qì','氵','7','','[{"pinyin": "qì", "defs": [{"meaning": "水枯竭。", "cites": [{"t": "汽,水涸也。", "b": "《说文》"}]}, {"meaning": "泣下 。今作汔。", "cites": [{"t": "汽…或曰泣下。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('862wx','沃','1','wò','氵','7','','[{"pinyin": "wò", "defs": [{"meaning": "(形声。从水,夭(yāo)声。本义:把水从上浇下)。"}, {"meaning": "同本义。", "cites": [{"t": "使火燃,以水沃之,可谓水贼火。", "b": "《论衡·偶然》"}], "words": [{"w": "沃盥", "t": "浇水洗手"}, {"w": "沃酹", "t": "以酒浇地而祭奠"}, {"w": "沃漏", "t": "以沸水浇灌漏壶"}, {"w": "沃醊", "t": "以酒浇地而祭祀"}, {"w": "沃雪", "t": "以热水浇雪。比喻事情极易解决"}, {"w": "沃馈", "t": "以酒食祭奠"}, {"w": "沃洒", "t": "浇洒。"}]}, {"meaning": "大水量的灌溉。", "cites": [{"t": "沃,溉灌也。", "b": "《说文》"}, {"t": "决白马之口以沃魏氏。", "b": "《韩非子·初见秦》"}], "words": [{"w": "沃濯", "t": "浇灌"}, {"w": "沃灌", "t": "浇灌"}, {"w": "沃流", "t": "可供灌溉的水流。"}]}, {"meaning": "饮,喝。", "cites": [{"t": "载(扈载)连沃六七巨觥,吐呕淋漓。", "b": "宋·陶谷《清异录》"}]}, {"meaning": "淹。", "cites": [{"t": "勃然发怒决洪流,立拟沃杀九日沃。", "b": "唐·卢仝《月蚀诗》"}]}, {"meaning": "浸泡,使没于水中。", "cites": [{"t": "那个抓来就将水里沃。", "b": "《西游记》"}]}, {"meaning": "肥美。", "cites": [{"t": "关中为沃野,无凶年。", "b": "《史记·河渠书》"}, {"t": "以盘石为沃田,以桀暴为良民。", "b": "《论衡·宣汉》"}, {"t": "沃野千里。", "b": "《三国志·诸葛亮传》"}, {"t": "膏之沃者。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "沃野万里。", "b": "《资治通鉴》"}], "words": [{"w": "沃地", "t": "肥沃的土地"}, {"w": "沃田;沃淫", "t": "肥沃润泽的土地"}, {"w": "沃润", "t": "肥沃润泽"}, {"w": "沃饶", "t": "土地肥沃"}, {"w": "沃畴", "t": "肥沃的田畴"}, {"w": "沃瘠", "t": "土地的肥瘦"}, {"w": "沃实", "t": "土地肥沃,物产丰盛"}, {"w": "沃腴", "t": "肥沃"}, {"w": "沃美", "t": "肥美。"}]}, {"meaning": "低。", "cites": [{"t": "沃,低也。", "b": "《广雅》"}]}, {"meaning": "驯顺。", "cites": [{"t": "我马维骆,六辔沃若。", "b": "《诗·小雅》"}]}, {"meaning": "沃水 。在今山西省右玉县境。"}, {"meaning": "地名 。春秋晋地曲沃的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('863wx','沦','1','lún','氵','7','','[{"pinyin": "lún", "defs": [{"meaning": "(形声。从水,仑(lún)声。本义:水起微波)。"}, {"meaning": "同本义。", "cites": [{"t": "沦,小波为沦。", "b": "《说文》"}, {"t": "河水清且沦猗。", "b": "《诗·魏风·伐檀》。传:“小风水成文转如轮也。”"}, {"t": "从流而风曰沦。沦,文貌。”", "b": ""}]}, {"meaning": "沉沦;没落。", "cites": [{"t": "沦,渍也。", "b": "《广雅》"}, {"t": "沦于不测。", "b": "《淮南子·精神》。注:“入也。”"}, {"t": "微霜降而下沦兮。", "b": "《楚辞·远游》"}, {"t": "韩公沦卖药。", "b": "江淹《杂体诗》"}], "words": [{"w": "沦化", "t": "变化;沦落"}, {"w": "沦降", "t": "沦落"}, {"w": "沦倾", "t": "陷落"}, {"w": "沦滞", "t": "陷入苦境。"}]}, {"meaning": "灭亡;丧亡。", "cites": [{"t": "沦,一曰没也。", "b": "《说文》"}, {"t": "今殷其沦丧。", "b": "《书·微子》"}, {"t": "沦胥以铺。", "b": "《诗·小雅·雨无止》"}, {"t": "无沦胥以亡。", "b": "《诗·大雅·抑》"}]}, {"meaning": "又如：沦翳(衰亡消失);沦坠(沦亡,消灭);沦替(没落衰微);沦殁(死亡);沦佚(沦没散失);沦溺(沉没;淹没)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('864wx','汹','1','xiōng','氵','7','','[{"pinyin": "xiōng", "defs": [{"meaning": "(形声。从水,凶声。本义:水猛烈地向上涌腾) 同本义。通常作“汹涌”。", "cites": [{"t": "洶,涌也。", "b": "《说文》"}, {"t": "大江动我前,汹若溟渤宽。", "b": "唐·杜甫《大会渡》"}, {"t": "填其汹渊,毋使水清。", "b": "《韩非子·杨权》"}], "words": [{"w": "汹呶", "t": "水势喧嚣翻腾貌"}, {"w": "汹急", "t": "水势湍急"}, {"w": "汹怒", "t": "水流激荡"}, {"w": "汹然", "t": "汹涌翻腾貌"}, {"w": "汹溶", "t": "水势翻腾上涌。"}]}, {"meaning": "形容声音大;喧嚣。", "cites": [{"t": "洶洶、嗑嗑,皆水声也。", "b": "《尚书大传》"}, {"t": "飘风来之洶洶。", "b": "《楚辞·逢纷》"}], "words": [{"w": "汹汹拳拳", "t": "喧闹欢腾的样子"}, {"w": "汹赫", "t": "形容气势盛"}, {"w": "汹洶", "t": "形容声音喧腾迅疾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('865wx','泛','1','fàn','氵','7','','[{"pinyin": "fàn", "defs": [{"meaning": "(形声。从水,乏声。汎、泛实同一词。本义:漂浮)。"}, {"meaning": "同本义。", "cites": [{"t": "汎,浮貌。从水,凡声。与泛略同。与氾迥别。", "b": "《说文》"}, {"t": "汎彼柏舟。", "b": "《诗·邶风·柏舟》"}, {"t": "汎舟于河。", "b": "《国语·晋语》。注:“浮也。”"}, {"t": "一曰泛齐。", "b": "《周礼·酒正》"}, {"t": "汎齐,浮蛾在上汎汎然也。", "b": "《释名·释饭食》"}, {"t": "汎汎杨舟。", "b": "《诗·小雅·菁菁者莪》"}, {"t": "乘天潢之汎汎兮。", "b": "《文选·张衡·思玄赋》"}, {"t": "盖大苏泛赤壁云。", "b": "明·魏学洢《核舟记》"}, {"t": "泛彭蠡口,四望无际。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "泛然", "t": "漂浮,浮动的样子"}, {"w": "泛浮", "t": "漂浮"}, {"w": "泛萍", "t": "比喻漂荡不定"}, {"w": "泛蚁", "t": "浮在酒上的泡沫。"}]}, {"meaning": "漫溢,大水漫流。", "cites": [{"t": "河水决濮阳,泛郡十六。", "b": "《汉书·武帝纪》"}], "words": [{"w": "黄泛区;泛浸", "t": "泛滥淹没"}, {"w": "泛涨", "t": "水涨溢"}, {"w": "泛澜", "t": "漫溢横流。"}]}, {"meaning": "弥漫。", "cites": [{"t": "凝烟泛城阙,凄风入轩房。", "b": "南朝宋·刘铄《歌诗》"}]}, {"meaning": "向上冒出。", "cites": [{"t": "坑里泛出半人深的水,油汪汪的,漂着汽油。", "b": "杨朔《三千里江山》"}]}, {"meaning": "(fěng),倾覆。", "cites": [{"t": "大命将泛,莫之振救。", "b": "汉·贾谊《论积贮疏》"}]}, {"meaning": "假借为氾。广泛,普遍。", "cites": [{"t": "以杜君言泛汛之。", "b": "清·方苞《狱中杂记》"}, {"t": "情窦既开,必致于泛用无度。", "b": "顾炎武《天下郡国利病书》"}], "words": [{"w": "泛利", "t": "广泛施利"}, {"w": "泛涉", "t": "广泛涉猎"}, {"w": "泛采", "t": "取材广泛"}, {"w": "泛广", "t": "广泛,普遍"}, {"w": "泛观", "t": "纵观;广泛地浏览。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('866wx','沧','1','cāng','氵','7','','[{"pinyin": "cāng", "defs": [{"meaning": "(形声。从水,仓声。本义:寒冷)。"}, {"meaning": "寒冷。", "cites": [{"t": "沧,寒也。", "b": "《说文》"}, {"t": "天地之间有沧热。", "b": "《周书·周祝》"}, {"t": "疾养滄热,滑铍轻重以形体异。", "b": "《荀子·正名》"}, {"t": "欲汤之滄,一人炊之,百人扬之,无益也,不如绝薪止火而已。", "b": "《汉书·枚乘传》"}, {"t": "日初出,沧沧凉凉。", "b": "《列子·汤问》"}], "words": [{"w": "沧凉", "t": "寒凉;寒冷"}, {"w": "沧热", "t": "寒冷与炎热。"}]}, {"meaning": "州名 。北朝东魏置。治所在今河北省盐山县与山东省乐陵县之间。唐至元因之,治所向北移至今河北省沧州市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('867wx','没','1','méi mò','氵','7','','[{"pinyin": "méi", "defs": [{"meaning": "不领有,不具有,不存在。", "cites": [{"t": "恐怕没来由走去撞在乱兵之手,死了也没说处。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "没谱", "t": "没有标准"}, {"w": "没根蒂", "t": "没有根据"}, {"w": "没脚手", "t": "没有雨具"}, {"w": "没个了局", "t": "没有了结;没完没了"}, {"w": "没个道理", "t": "没有办法"}, {"w": "没仁没义", "t": "没有一点情义"}, {"w": "没家亲引不出外鬼来", "t": "没有内患,引不来外敌"}, {"w": "没事", "t": "无端;无缘无故"}, {"w": "没对", "t": "无敌;无与匹敌"}, {"w": "没来历", "t": "无缘由"}, {"w": "没空生有", "t": "犹无中生有,凭空胡诌。"}]}, {"meaning": "没有,不曾,未。"}]}, {"pinyin": "mò", "defs": [{"meaning": "(会意 表示入水有所取。本义:沉没水中)。"}, {"meaning": "同本义。", "cites": [{"t": "没,沉也。", "b": "《说文》"}, {"t": "其子没于渊。", "b": "《庄子·列御寇》"}, {"t": "若赴水火,入焉焦没耳。", "b": "《荀子·议兵》"}, {"t": "梦为鱼而没于渊。", "b": "《庄子·大宗师》"}, {"t": "或浮或没。", "b": "《世说新语·自新》"}, {"t": "浅草才能没马蹄。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "水不没顶。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "没水而死。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "沉没", "t": "没入水中"}, {"w": "淹没", "t": "大水漫过;盖过"}, {"w": "没胫", "t": "没过脚胫"}, {"w": "没不煞", "t": "方言。沉没不了"}, {"w": "没溺", "t": "沉没"}, {"w": "洪水没过了大坝;没漂", "t": "淹没冲荡"}, {"w": "没石", "t": "暗礁。"}]}, {"meaning": "潜游水中。", "cites": [{"t": "若乃夫没人,则未尝见舟而便操之也。", "b": "《庄子·达生》"}, {"t": "南方多没人。", "b": "苏轼《日喻》"}], "words": [{"w": "没人", "t": "熟知水性能潜水的人"}, {"w": "没水", "t": "潜水"}, {"w": "没头蹲", "t": "扎猛子,以头朝下钻入水中。"}]}, {"meaning": "消失,不见;隐没。", "cites": [{"t": "良久,羽旄之影渐没。", "b": "马中锡《中山狼传》"}, {"t": "未闻刃没而利存。", "b": "范缜《神灭论》"}]}, {"meaning": "覆灭;败亡。", "cites": [{"t": "遂没其军。", "b": "《史记》"}]}, {"meaning": "没收。", "cites": [{"t": "财产没官。", "b": "《三国志》"}], "words": [{"w": "没官", "t": "没收入官"}, {"w": "没入", "t": "没收财物、人口等入官"}, {"w": "没有", "t": "犹没收。"}]}, {"meaning": "死。", "cites": [{"t": "庖牺氏没。", "b": "《易·系辞下》"}, {"t": "逮至昔三代圣王既没。", "b": "《墨子·明鬼下》"}, {"t": "圣王已没。", "b": "《荀子·正论》"}, {"t": "以没其身。", "b": "《国语·晋语》"}, {"t": "皆为戮没。", "b": "《战国策·燕策》"}, {"t": "孝公既没。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "没化", "t": "死亡"}, {"w": "没世", "t": "终身;一辈子"}, {"w": "没地", "t": "人死埋葬于地下"}, {"w": "没命", "t": "舍命。丧身,死亡"}, {"w": "没陈", "t": "阵亡"}, {"w": "没寿", "t": "谓死。"}]}, {"meaning": "沦没,落入。", "cites": [{"t": "侯没胡中。", "b": "《汉书·李广苏建传》"}]}, {"meaning": "隐没。", "cites": [{"t": "没为银海。", "b": "《徐霞客游记·游黄山记》"}, {"t": "出没于鲸波万仞之中。", "b": "周密《观潮》"}], "words": [{"w": "出没", "t": "出现和隐藏"}, {"w": "没矢", "t": "谓箭射进石头后隐没不见。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('868wx','沟','1','gōu','氵','7','','[{"pinyin": "gōu", "defs": [{"meaning": "(形声。从水,冓(gōu)声。本义:田间水道)。"}, {"meaning": "同本义。", "cites": [{"t": "沟,水渎,广四尺,深四尺。", "b": "《说文》"}, {"t": "九夫为井,井间广四尺、深四尺,谓之沟。", "b": "《考工记·匠人》"}, {"t": "十夫有沟,沟上有畛。", "b": "《周礼·遂人》"}, {"t": "苟为无本,七八月之间雨集,沟浍皆盈;其涸也,可立而待也。", "b": "《孟子·离娄下》"}], "words": [{"w": "沟洫", "t": "沟浍。田间水道与沟渠"}, {"w": "沟洫", "t": "田间水道"}, {"w": "沟塍", "t": "沟渠和田埂。"}]}, {"meaning": "泛指水道。", "cites": [{"t": "水注谷曰沟。", "b": "《尔雅》"}, {"t": "血流入沟中。", "b": "《汉书·刘尾氂传》"}, {"t": "鲁以五月起众为长沟。", "b": "《韩非子·外储说右上》"}, {"t": "兵法曰:“丈五之沟,渐车之水。", "b": "晁错《言兵事疏》"}], "words": [{"w": "一沟死水;阴沟;万丈深沟;沟中瘠", "t": "指死于沟壑之人"}, {"w": "沟防", "t": "沟渠和堤防"}, {"w": "沟沿", "t": "沟渠的边岸。"}]}, {"meaning": "护城河。", "cites": [{"t": "城郭不辨,沟池不拑。", "b": "《荀子·议兵》"}, {"t": "楚方域以为城,江汉以为沟。", "b": "《史记·齐太公世家》"}], "words": [{"w": "沟郭", "t": "城壕。即护城河与城郭"}, {"w": "沟门", "t": "营门,因旧时军营前有沟"}, {"w": "沟池", "t": "城壕。即护城河。"}]}, {"meaning": "挖沟。", "cites": [{"t": "钩,沟也,既割去垄上草,又辟其土,以壅苗根,使垄下为沟受水潦也。", "b": "《释名》"}], "words": [{"w": "沟贯", "t": "沟通贯穿谓通晓"}, {"w": "沟封", "t": "筑沟洫封疆,以划分疆界。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('869wx','沪','1','hù','氵','7','','[{"pinyin": "hù", "defs": [{"meaning": "捕鱼的竹栅。", "cites": [{"t": "潮生鱼沪短,风起鸭船斜。", "b": "陆游《村舍》"}, {"t": "列竹于海澨曰沪。", "b": "唐·陆龟蒙《渔具》诗序"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('870wx','沈','1','shěn','氵','7','','[{"pinyin": "shěn", "defs": [{"meaning": "西周分封的诸侯国名。", "cites": [{"t": "伐沈。", "b": "《左传·文公三年》。朱骏声曰:“国在今河南汝州汝阳县东南。定(公)四年蔡灭之。”"}]}, {"meaning": "姬姓。一说姒姓。始封之君为周文王之子季载。在今河南平舆北。公元前506年为蔡所灭。"}, {"meaning": "水名。沈水  旧名小沈河,俗称五里河。在辽宁省沈阳市南。源出县东哈达岭观音阁下,流入浑河,再流至三岔河注入辽河。"}, {"meaning": "汁。", "cites": [{"t": "瀋,汁也。从水,審声。", "b": "《说文》"}, {"t": "无备而官办者,犹拾瀋也。", "b": "《左传·哀公三年》。释文:“北土呼汁为瀋。”"}, {"t": "为榆沈。", "b": "《礼记·檀弓》"}, {"t": "布绞取沈,以和花汁。", "b": "《齐民要术》"}], "words": [{"w": "沈液", "t": "汁液。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('871wx','沉','1','chén','氵','7','','[{"pinyin": "chén", "defs": [{"meaning": "(形声。从水,冘(yín)声。甲骨文字形,中间是牛,周围是水,表示把牛沉到水中。商代祭祀用牲的方法。本义:没入水中)。"}, {"meaning": "同本义。", "cites": [{"t": "沈,没也。", "b": "《广雅》"}, {"t": "以狸沈祭山林川泽。", "b": "《周礼·大宗伯》。注:“川泽曰沈。”"}, {"t": "泛泛杨舟,载沉载浮。", "b": "《诗·小雅·箐箐者莪》"}, {"t": "皓月千里,浮光跃金,静影沉璧,渔歌互答,此乐何极!", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "山河破碎风飘絮,身世浮沉雨打萍。", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "石沉大海;沉溺", "t": "沉没水中。"}]}, {"meaning": "沉迷,沉溺。", "cites": [{"t": "寡人不祥,被于宗庙之祟,沉于谄谀之臣。", "b": "《战国策·齐策四》"}, {"t": "细腰沉赵女。", "b": "杨敬之《客思吟》"}, {"t": "我用沈酗于酒。", "b": "《书·微子》。传:“沈,湎也。”"}, {"t": "沈酒冒色。", "b": "《书·秦誓上》"}, {"t": "沈而乐者。", "b": "扬雄《法言·寡见》"}], "words": [{"w": "沉饮", "t": "沉迷于饮酒"}, {"w": "沉酣", "t": "沉酒而酣适"}, {"w": "沉乱", "t": "沉迷昏乱。"}]}, {"meaning": "沉沦;沦落 。 如:沉人(沉沦在下的贤人);沉顿(沉沦顿踬)。"}, {"meaning": "山岭上凹处的积水。", "cites": [{"t": "除山川沈斥。", "b": "《汉书·刑法志》"}]}, {"meaning": "古水名 。"}, {"meaning": "陕西省滪水的别名。"}, {"meaning": "今四川省射洪县东南的杨桃溪,为涪江的支流。"}, {"meaning": "份量重,重。", "cites": [{"t": "无苗时采,则实而沉。", "b": "宋·沈括《梦溪笔谈·采草药》"}]}, {"meaning": "低沉。", "cites": [{"t": "暮霭沉沉楚天阔。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "沉冥", "t": "低沉冥寂"}, {"w": "沉细", "t": "低沉细微"}, {"w": "沉声", "t": "声调低沉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('872wx','沁','1','qìn','氵','7','','[{"pinyin": "qìn", "defs": [{"meaning": "(形声。从水,心声。本义:沁水)。"}, {"meaning": "同本义。", "cites": [{"t": "沁水,出上党谷远羊头山,东南入河。", "b": "《说文》"}]}, {"meaning": "即出今山西省沁源县东北绵山东谷,南流至河南省武陟县南入黄河。"}, {"meaning": "县名 。在山西省中部偏南。"}, {"meaning": "吸水。", "cites": [{"t": "义泉虽至近,盗索不敢沁。", "b": "唐·韩愈孟郊《同宿联句》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('873wx','怀','1','huái','忄','7','','[{"pinyin": "huái", "defs": [{"meaning": "(形声。从心,褱声。本义:想念,怀念)。"}, {"meaning": "同本义。", "cites": [{"t": "怀,思念也。", "b": "《说文》"}, {"t": "嗟我怀人。", "b": "《诗·周南·卷耳》"}, {"t": "维以不永怀。", "b": ""}, {"t": "有女怀人。", "b": "《诗·召南·野有死麕》"}, {"t": "惟佳人之独怀兮。", "b": "《楚辞·悲回风》"}, {"t": "怀良辰以孤往。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "久行怀思。", "b": "《后汉书·列女传》"}, {"t": "而不怀仁。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "去国怀乡。(国,国都)", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "怀土", "t": "怀恋故乡;安于所处"}, {"w": "怀香", "t": "怀念女色;风流"}, {"w": "怀慕", "t": "怀念仰慕"}, {"w": "怀乡", "t": "思念故乡。"}]}, {"meaning": "心里存有;怀藏。", "cites": [{"t": "心怆悢以伤怀。", "b": "《文选·班彪·北征赋》"}, {"t": "怀瑾握瑜兮。", "b": "《楚辞·九章·怀沙》。注:“在衣为怀,在手为握。”"}, {"t": "怀怒未发。", "b": "《战国策·魏策》"}, {"t": "怀信佗傺。", "b": "《楚词·屈原·涉江》"}, {"t": "怀犹豫之计。", "b": "《资治通鉴》"}, {"t": "尚怀狐疑。", "b": ""}, {"t": "怀其璧。", "b": "《史记·廉颇蔺相列传》"}, {"t": "怀瑾握瑜。", "b": "《史记·屈原贾生列传》"}, {"t": "佩紫怀黄。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "汝姊在吾怀。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "怀玉", "t": "怀抱美玉。比喻人具有才德"}, {"w": "怀慝", "t": "心中怀有不良的意念"}, {"w": "怀贰", "t": "怀有二心"}, {"w": "怀袖", "t": "拥抱"}, {"w": "怀刺", "t": "心怀讽刺。"}]}, {"meaning": "包容;包围。", "cites": [{"t": "荡荡怀山襄陵。", "b": "《书·尧典》。传:“怀,包也。”"}, {"t": "怀万物。", "b": "《淮南子·览冥》"}], "words": [{"w": "怀挟", "t": "包藏"}, {"w": "怀山", "t": "包围山陵。"}]}, {"meaning": "归向;依恋。", "cites": [{"t": "戎狄怀之。", "b": "《国语·晋语》"}, {"t": "怀与安,实败名。", "b": "《左传·僖公二十三年》"}], "words": [{"w": "怀向", "t": "归向;向往"}, {"w": "怀附", "t": "归向,归附"}, {"w": "怀服", "t": "内心顺服"}, {"w": "怀化", "t": "归服向化。"}]}, {"meaning": "安;安抚。", "cites": [{"t": "而怀西戎。", "b": "《韩非子·五蠹》"}, {"t": "广德行以怀之。", "b": "汉·桓宽《盐铁论·本议》"}], "words": [{"w": "怀生", "t": "安于生计"}, {"w": "怀保", "t": "安抚保护;抚养"}, {"w": "怀远", "t": "安抚边远的人"}, {"w": "怀抚", "t": "安抚。"}]}, {"meaning": "胸口;怀抱里。", "cites": [{"t": "免于父母之怀。", "b": "《论语·然后》"}, {"t": "寘子于怀。", "b": "《诗·小雅·谷风》"}, {"t": "出其父母怀衽之中。", "b": "《韩非子·初见秦》"}], "words": [{"w": "怀黄", "t": "怀里揣着金印"}, {"w": "怀金", "t": "怀揣金印"}, {"w": "怀襟", "t": "胸襟。"}]}, {"meaning": "心意;情意。", "cites": [{"t": "仆怀欲陈之,而未有路。", "b": "汉·司马迁《报任安书》"}, {"t": "感君区区怀。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "逆以前我怀。", "b": ""}, {"t": "聊布往怀。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "予怀怆然。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "怀恩", "t": "感念恩德"}, {"w": "怀寄", "t": "寄托心志"}, {"w": "怀爱", "t": "心中喜爱。"}]}, {"meaning": "古地名 ,在今河南省武陟县西南。", "cites": [{"t": "卅九年,攻怀。", "b": "《睡虎地秦墓竹简·编年纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('874wx','忧','1','yōu','忄','7','','[{"pinyin": "yōu", "defs": [{"meaning": "(本字古作上“页”（xie）下“心”。会意。心中有了忧愁，必然在脸上(用“页”即人头代表)反映出来。后加“攵”(suī表示行走),形成“憂”字。“忧”是形声字。本义:担忧;发愁)同本义。", "cites": [{"t": "忧,愁也。", "b": "《说文》"}, {"t": "忧,愁也。", "b": "《玉篇》"}, {"t": "忧悲者德之失也。", "b": "《淮南子·原道》"}, {"t": "勿忧。", "b": "《易·丰》"}, {"t": "坎为加忧。", "b": "《易·说卦》"}, {"t": "我心忧伤。", "b": "《诗·小雅·小弁》"}, {"t": "忧心忡忡。", "b": "《诗·召南·草虫》"}, {"t": "何忧令名不彰。", "b": "《世说新语·自新》"}, {"t": "心忧炭贱。", "b": "唐·白居易《卖炭翁》"}, {"t": "忧谗畏讥。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "忧其民。", "b": ""}], "words": [{"w": "忧忿滞中", "t": "中医指忧愁忿懑滞郁在胸中"}, {"w": "忧蹙", "t": "因忧愁而紧锁眉头"}, {"w": "忧愠", "t": "忧愁懊恼"}, {"w": "忧忆", "t": "忧愁担心"}, {"w": "忧心如捣", "t": "忧愁得像有什么东西捣心一样"}, {"w": "忧邑", "t": "愁闷抑郁"}, {"w": "忧畏", "t": "忧虑畏怯"}, {"w": "忧世", "t": "为世时或时事而忧虑"}, {"w": "忧怀", "t": "忧虑怀念"}, {"w": "忧怯", "t": "担忧畏怯"}, {"w": "忧天", "t": "担心天塌下来"}, {"w": "忧公忘私", "t": "关心公益,不顾私利"}, {"w": "忧鱼", "t": "担心水患。"}]}, {"meaning": "居丧 。多指居父母丧。", "cites": [{"t": "王宅忧,亮阴三祀。", "b": "《书·说命上》"}], "words": [{"w": "忧居", "t": "丁忧家居"}, {"w": "忧服", "t": "因父母死而居忧服丧"}, {"w": "忧纪", "t": "居父母丧之期"}, {"w": "忧棘", "t": "居父母之丧"}, {"w": "忧毁", "t": "居父母之丧哀伤过度而损害身体"}, {"w": "忧艰", "t": "忧父母之丧。"}]}, {"meaning": "忧患,祸患。", "cites": [{"t": "必为子孙忧。", "b": "《论语·季氏》"}, {"t": "恐季氏之忧。", "b": ""}, {"t": "愦于忧。", "b": "《战国策·齐策四》"}, {"t": "乐琴书以消忧。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "忧困", "t": "忧患困顿"}, {"w": "忧逼", "t": "忧患侵迫"}, {"w": "忧难", "t": "忧患"}, {"w": "忧衅", "t": "忧患之端。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('875wx','忱','1','chén','忄','7','','[{"pinyin": "chén", "defs": [{"meaning": "真诚而有信用", "words": [{"w": "忱辞", "t": "至诚之辞"}, {"w": "赤忱", "t": "赤诚"}]}, {"meaning": "信任", "words": [{"w": "忱恂", "t": "诚信"}]}, {"meaning": "真诚的心意", "words": [{"w": "热忱", "t": ""}, {"w": "谢忱", "t": "感谢的心意"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('876wx','快','1','kuài','忄','7','','[{"pinyin": "kuài", "defs": [{"meaning": "(形声。从心,(guài)声。本义:高兴,痛快)。"}, {"meaning": "同本义。", "cites": [{"t": "快,喜也。", "b": "《说文》"}, {"t": "文信侯去而不快。", "b": "《战国策·秦策》"}, {"t": "心不快。", "b": "《史记·魏公子列传》"}, {"t": "快意留之,非忠臣也。", "b": "《后汉书·班超传》"}, {"t": "则不快吾意。", "b": "明·魏禧《大铁椎传》"}, {"t": "若所为诚快。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "快观", "t": "让人看了高兴"}, {"w": "快吾意", "t": "使吾意快,符合我的意思。"}]}, {"meaning": "舒适;舒畅。", "cites": [{"t": "有一士大夫不快。", "b": "《三国志·方伎传》"}]}, {"meaning": "又。", "cites": [{"t": "体中不快。", "b": ""}, {"t": "使快弹数曲。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "快哉此风。", "b": "宋玉《风赋》"}], "words": [{"w": "快畅", "t": "痛快,舒畅"}, {"w": "快当", "t": "痛快,爽快"}, {"w": "快饮", "t": "畅饮;痛饮"}, {"w": "快意", "t": "痛快。"}]}, {"meaning": "动作迅速,与“慢”相对。", "cites": [{"t": "俗谓急速曰快。", "b": "《正字通》"}, {"t": "此马虽快,然力薄不堪苦行。", "b": "《晋书·王湛传》"}, {"t": "彭城王有快牛,至爱惜之。", "b": "《世说新语·汰侈》"}, {"t": "健儿须快马,快马须健儿。", "b": "古乐府《折杨柳歌辞》"}], "words": [{"w": "快拍", "t": "戏曲中拍子急速的调子"}, {"w": "快当", "t": "快;迅速"}, {"w": "快马", "t": "善于奔驰的健马"}, {"w": "快迅", "t": "速度快。"}]}, {"meaning": "锋利。", "cites": [{"t": "快刀断其头。", "b": "李商隐《行次西郊作》"}], "words": [{"w": "快谈", "t": "痛快锋利的言谈。"}]}, {"meaning": "直爽,爽快。", "cites": [{"t": "人见邻里有佳快者,使子弟慕而学之。", "b": "《颜氏家训·勉学》"}], "words": [{"w": "快士", "t": "豪爽之士"}, {"w": "快爽", "t": "爽利"}, {"w": "快口", "t": "不加考虑,有话就说。"}]}, {"meaning": "旧时州县衙门里任缉捕的差卒。", "cites": [{"t": "各县捕快捉来的强盗。", "b": "《老残游记》"}]}, {"meaning": "赌博时撒出的头钱为“快”,表示“赢”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('877wx','完','1','wán','宀','7','','[{"pinyin": "wán", "defs": [{"meaning": "(形声。从宀(mián),元声。“宀”与房屋有关。本义:完备,完整)。"}, {"meaning": "同本义。", "cites": [{"t": "完,全也。", "b": "《说文》"}, {"t": "巢非不完也。", "b": "《荀子·劝学》"}, {"t": "完全富足而趋赵。", "b": "《荀子·议兵》"}, {"t": "完璧归赵。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "果得一死男,手足完具。", "b": "《三国志·华佗传》"}, {"t": "不如伐蜀之完也。", "b": "《战国策·秦策一》"}, {"t": "功少而最完,势疏而最忠。", "b": "贾谊《治安策》"}, {"t": "不能独完。", "b": "宋·苏洵《六国论》"}, {"t": "无一完者。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "完计", "t": "周密完善的计策"}, {"w": "完完", "t": "完整无缺的样子"}, {"w": "完充", "t": "完备充裕"}, {"w": "完锐", "t": "完备精良"}, {"w": "完块", "t": "完整的田土"}, {"w": "完篇", "t": "完整的篇章"}, {"w": "完丽", "t": "完整华美"}, {"w": "完垒", "t": "完整的营垒"}, {"w": "完名", "t": "完美的名节"}, {"w": "完书", "t": "完美的书;完整的书"}, {"w": "完德", "t": "完美的品德。"}]}, {"meaning": "充足;充实。", "cites": [{"t": "今天水完富,士马最强。", "b": "《后汉书》"}]}, {"meaning": "完成,结束。", "cites": [{"t": "那夜安公子早已完卷。", "b": "《儿女英雄传》"}], "words": [{"w": "完卷", "t": "完成答卷"}, {"w": "完房", "t": "完婚"}, {"w": "完娶", "t": "结为夫妻,完婚"}, {"w": "完就", "t": "成就,成功"}, {"w": "完饭", "t": "婚俗。婚后三日,女家送食物到男家,男家则以茶饭招待"}, {"w": "完了那纂", "t": "做完那些事情。"}]}, {"meaning": "重新整修。", "cites": [{"t": "父母使舜完廩。", "b": "《孟子·万章上》"}, {"t": "缮完葺墙。", "b": "《左传·襄公三十一年》"}], "words": [{"w": "完缮", "t": "修理;修缮"}, {"w": "完补", "t": "补救;修复"}, {"w": "完葺", "t": "修缮,修葺"}, {"w": "完理", "t": "修整。"}]}, {"meaning": "指生命终结或进入危急的境地。", "cites": [{"t": "大家都说,完了,怕是遭了狼了。", "b": "鲁迅《祝福》"}]}, {"meaning": "古代轻刑之一。", "cites": [{"t": "刖者使守囿,完者使守积。", "b": "《刑法志》"}]}, {"meaning": "汉以前指剪去犯人的须发;汉以后罚作劳役。因其不伤肢体,故曰“完”。"}, {"meaning": "山羊。"}, {"meaning": "地名 。在河北省境内,太行山东麓。秦为曲逆县,北齐设北平县,金改永平县,后升完州,明改完县。"}, {"meaning": "水名。即今黑龙江。"}, {"meaning": "墙垣。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('878wx','宋','1','sòng','宀','7','','[{"pinyin": "sòng", "defs": [{"meaning": "(会意。从宀(mián),从木。表示房屋周围有树木。本义:定居) 同本义。", "cites": [{"t": "宋,居也。", "b": "《说文》。段玉裁注:“此义未见经传,名子者不以国,而鲁定公名宋,则必取其本义也。”"}, {"t": "郑公子宋字子公。", "b": "《左传·宣公四年》"}]}, {"meaning": "周代诸侯国名。", "cites": [{"t": "桓帝时,有黄星见于楚、宋之分。", "b": "《三国演义》"}, {"t": "吾在北方闻子为梯,将以攻宋,宋何罪之有?", "b": "《墨子·公输》"}]}, {"meaning": "子姓。周武王灭商后,封商王纣子武庚于商旧都(今河南商丘)。成王时,武庚叛乱,被杀,又以其地与纣的庶兄微子启,号宋公,为宋国。战国初年曾迁都彭城(今徐州)。公元前286年为齐所灭。辖地在今河南东部及山东、江苏、安徽之间。"}, {"meaning": "中国朝代名 。公元960年赵匡胤(宋太祖)代后周称帝。国号宋,定都汴京(今河南开封),史称北宋。钦宗靖康元年(1126年)金兵攻入开封,北宋亡。次年赵构(宋高宗)在南京(今河南商丘)称帝后建都临安(今浙江杭州),史称南宋。两宋共历十八帝,统治三百二十年。", "cites": [{"t": "(嗣同)与杨锐、林旭、刘光第同参预新,时号为“军机四卿”。参预新政者,犹唐、宋之“参知政事”,实宰相之职也。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "宋儒", "t": "指周敦颐、程颢、程颐、张载、朱熹等一班宋朝理学家。"}]}, {"meaning": "主观响度单位 ,1宋等于强度为听者听阈上40分贝的1000赫纯音的响度。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('879wx','宏','1','hóng','宀','7','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从宀(mián),表示与家室房屋有关,厷(gōng)声。本义:屋子宽大而深)。"}, {"meaning": "同本义。", "cites": [{"t": "宏,屋深响也。", "b": "《说文》。段玉裁注:“屋深也。各本深下衍响字,此因下文‘屋响’而误,今依《韵会》、《集韵》、《类篇》正。…屋深者,其内深广也。”"}, {"t": "宏我邦我家。", "b": "《毛公鼎》"}, {"t": "宏,按:深大之屋凡声如有应响。", "b": "清·朱骏声《说文通训定声》"}]}, {"meaning": "大;宏大。", "cites": [{"t": "宏,大也。", "b": "《尔雅·释诂》"}, {"t": "若保宏父。", "b": "《书·酒诰》"}, {"t": "举其宏纲。", "b": "《书·序》"}, {"t": "其器宏以弇。", "b": "《吕氏春秋·孟冬》"}], "words": [{"w": "宏才", "t": "大才"}, {"w": "宏硕", "t": "大儒硕学。指有学问的人"}, {"w": "宏纲", "t": "大纲"}, {"w": "宏宏", "t": "广大的样子。"}]}, {"meaning": "扩大;光大。", "cites": [{"t": "宏兹九德。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "宏大;宏肆", "t": "谓发扬光大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('880wx','牢','1','láo','牛','7','','[{"pinyin": "láo", "defs": [{"meaning": "(象形指事。据甲骨文,里面是个“牛”字,外面象养牛的圈。泛指一般养性畜的栏圈(juàn)。本义:关养牛马等牲畜的圈)。"}, {"meaning": "同本义。", "cites": [{"t": "牢,闲养牛马圈也。", "b": "《说文》。按,牛羊豕之闲曰牢。"}, {"t": "执豕于牢。", "b": "《诗·大雅·公刘》"}, {"t": "亡羊而补牢,未为迟也。", "b": "《战国策·楚策》"}, {"t": "祀五帝则系于牢。", "b": "《周礼·充人》"}, {"t": "长幼群聚,而为牢藉。", "b": "《列子·仲尼》"}, {"t": "元端以临牢筴。", "b": "《庄子·达生》"}], "words": [{"w": "牢栈", "t": "圈养牲畜的栅栏"}, {"w": "牢筴", "t": "猪圈"}, {"w": "牢藉", "t": "猪圈。"}]}, {"meaning": "古代祭祀或宴享时用的牲畜。牛羊豕各一曰太牢,羊豕各一曰少牢。", "cites": [{"t": "天子社稷皆太牢,诸侯社稷皆少牢。", "b": "《礼记·王制》。又如:牢羞(牛羊等祭祀牲品);牢礼(用牛羊豕三牲宴请宾客之礼);牢具(牲牢之体);牢酒(牢牲和酒)"}]}, {"meaning": "监狱。", "cites": [{"t": "故土有画地为牢,势不可入。", "b": "司马迁《报任安书》"}, {"t": "县请治牢具。", "b": "《三国志·司马芝传》"}], "words": [{"w": "监牢", "t": "监狱"}, {"w": "牢犴", "t": "监狱"}, {"w": "牢城", "t": "宋时囚禁流配罪犯的地方"}, {"w": "牢坑", "t": "囚禁犯人的处所。"}]}, {"meaning": "古州名 。唐置,在今广西玉林县。"}, {"meaning": "古水名 。即今广东西南部的新兴江。源出天露山,北流至高要入西江。"}, {"meaning": "坚固;牢固。", "cites": [{"t": "舜住陶焉,期年而器牢。", "b": "《韩非子·难一》"}, {"t": "愈束缚牢甚。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "牢良", "t": "坚车良马"}, {"w": "牢守", "t": "坚守"}, {"w": "牢车", "t": "坚固的车子"}, {"w": "牢壮", "t": "结实;坚固"}, {"w": "牢坚", "t": "坚固;牢固"}, {"w": "牢密", "t": "坚固细密;严密。"}]}, {"meaning": "稳妥可靠。", "cites": [{"t": "监军之计,计在持牢,而非见时知机之变也。", "b": "《三国志·袁绍传》裴松之注引《献帝传》"}], "words": [{"w": "牢利", "t": "稳当灵活"}, {"w": "牢饭碗", "t": "比喻稳当的职业。犹今言铁饭碗"}, {"w": "牢稳", "t": "稳当可靠。"}]}, {"meaning": "以谨慎少言为标志的;嘴紧。", "cites": [{"t": "就在这里说,才娃他妈嘴牢着哩。", "b": "柳青《创业史》"}]}, {"meaning": "用网或罩捉。", "cites": [{"t": "冬天牢野鸡,整沙鸡。", "b": "周立波《暴风骤雨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('881wx','究','1','jiū','穴','7','','[{"pinyin": "jiū", "defs": [{"meaning": "(形声。从穴,九声。本义:穷;尽) 同本义。", "cites": [{"t": "究,穷也。", "b": "《说文》"}, {"t": "靡届靡究。", "b": "《诗·大雅·荡》"}, {"t": "害气将究。", "b": "《汉书·食货志》"}, {"t": "此告民究也。", "b": "《吕氏春秋·任地》"}, {"t": "靡届靡究。", "b": "《诗·大雅·荡》"}, {"t": "害气将究。", "b": "《汉书·食货志》"}, {"t": "此告民究也。", "b": "《吕氏春秋·任地》"}, {"t": "必须天道,[如日月]周旋无究。", "b": "《国语》"}], "words": [{"w": "究途", "t": "走完全部的路程。比喻做事有始有终"}, {"w": "究年", "t": "终年"}, {"w": "究归", "t": "终归。"}]}, {"meaning": "谋划;研究;探求。", "cites": [{"t": "究,谋也。", "b": "《尔雅》"}, {"t": "不舒究之。", "b": "《诗·小雅·小弁》"}, {"t": "爰究爰度。", "b": "《诗·大雅·皇矣》"}, {"t": "莫可究详。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "究讨", "t": "研究探讨"}, {"w": "究理", "t": "推求事物的原理"}, {"w": "究心", "t": "费力;用心钻研"}, {"w": "究味", "t": "研究体会"}, {"w": "究明", "t": "研究清楚"}, {"w": "究索", "t": "研究探索。"}]}, {"meaning": "系统调查或追查。", "cites": [{"t": "是究是图。", "b": "《诗·小雅·棠棣》"}, {"t": "不究其旧。", "b": "唐·韩愈《原毁》"}, {"t": "究其旧。", "b": ""}, {"t": "士之孝曰究,究者,以明审为义。", "b": "《孝经·援神契》"}, {"t": "究主使者。", "b": "《明史》"}], "words": [{"w": "究讯", "t": "追查审问"}, {"w": "究治", "t": "追究处治"}, {"w": "究审", "t": "追究审问"}, {"w": "究切", "t": "追究责备"}, {"w": "究处", "t": "追究处分"}, {"w": "究询", "t": "追究询问"}, {"w": "究寻", "t": "追查。"}]}, {"meaning": "达,贯彻。", "cites": [{"t": "有擅主之臣,则君令不下究,臣情不上通。", "b": "《韩非子》"}]}, {"meaning": "毕竟,到底。", "cites": [{"t": "其究安宅。", "b": "《诗·小雅·鸿雁》"}, {"t": "独见环儿仍是先前,究不甚钟爱。", "b": "《红楼梦》"}, {"t": "寒家在此虽住了三代,究系寄居,亲友甚少。", "b": "《镜花缘》"}, {"t": "百姓究何辜。", "b": "《广东军务记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('882wx','穷','1','qióng','穴','7','','[{"pinyin": "qióng", "defs": [{"meaning": "(形声。从穴,躬声。躬,身体,身在穴下,很窘困。简化字为会意,力在穴下,有劲使不出。本义:穷尽,完结)。"}, {"meaning": "同本义。", "cites": [{"t": "穷,极也。", "b": "《说文》"}, {"t": "穷,竟也。", "b": "《小尔雅·广诂》"}, {"t": "横四海兮焉穷?", "b": "《楚辞·九歌·云中君》"}, {"t": "赤水穷焉。", "b": "《山海经·大荒南经》。注:“流极于此山也。”"}, {"t": "与物变化而无所终穷。", "b": "《吕氏春秋·下贤》"}, {"t": "穷高极远,而测深厚。", "b": "《礼记·乐记》"}, {"t": "儒有博学而不穷。", "b": "《礼记·儒行》"}, {"t": "图穷而匕首见。", "b": "《战国策·燕策》"}, {"t": "欲穷其林。", "b": "晋·陶渊明《桃花源记》"}, {"t": "欲穷千里目,更上一层楼。", "b": "唐·王之涣《登鹳雀楼》诗"}, {"t": "接天莲叶无穷碧。", "b": "宋·杨万里《晓出净慈寺送林子方》诗"}, {"t": "乐亦无穷。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "理屈词穷。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "穷形尽致", "t": "比喻说话不留余地,毫无保留"}, {"w": "穷师远讨", "t": "穷竭兵力进行远征"}, {"w": "穷兵屯戍", "t": "尽全部兵力驻守边疆"}, {"w": "无穷", "t": "没有穷尽;没有限度"}, {"w": "穷了", "t": "穷尽,终止"}, {"w": "穷生", "t": "尽其生年,终生。"}]}, {"meaning": "贫穷,缺乏衣食钱财。", "cites": [{"t": "穷,贫也。", "b": "《广雅》"}, {"t": "分贫,振穷。", "b": "《左传·昭公十四年》"}, {"t": "至无有者穷。", "b": "《荀子·大略》"}, {"t": "穷饿无聊。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "穷酸饿醋", "t": "穷酸"}, {"w": "穷腮乞脸", "t": "穷酸相"}, {"w": "穷拉拉", "t": "形容很穷"}, {"w": "穷滴滴", "t": "很穷"}, {"w": "穷薄", "t": "贫穷;穷困"}, {"w": "穷暴", "t": "贫穷之极"}, {"w": "贫穷", "t": "生产资料和生活资料缺乏"}, {"w": "穷通显晦", "t": "困窘、亨通、显赫、背晦"}, {"w": "穷迫", "t": "穷困窘迫"}, {"w": "穷厮", "t": "对贫穷男子的贱称"}, {"w": "穷丁", "t": "穷汉。贫穷男子"}, {"w": "穷鬼;穷日子;穷达", "t": "困穷与显达。"}]}, {"meaning": "边远的。", "cites": [{"t": "孤灯耿霜夕,穷山读兵书。", "b": "陆游《夜读兵书》"}], "words": [{"w": "穷城", "t": "历尽边城"}, {"w": "穷边", "t": "荒僻的边远地区"}, {"w": "穷泽", "t": "僻远的水乡。"}]}, {"meaning": "特指不得志。", "cites": [{"t": "固将愁苦而终穷。", "b": "《楚辞·屈原·涉江》"}, {"t": "人穷则反本。", "b": "《史记·屈原贾生列传》"}, {"t": "可谓穷矣。", "b": ""}], "words": [{"w": "穷人", "t": ""}]}, {"meaning": "寻根究源。", "cites": [{"t": "穷理尽性,以至于命。", "b": "《易·说卦》"}], "words": [{"w": "穷径", "t": "深入研究经籍"}, {"w": "穷本", "t": "追究本源"}, {"w": "穷微", "t": "穷究万物的精微道理。"}]}, {"meaning": "揭穿。", "cites": [{"t": "恐事穷且得罪,乃再诣相府。", "b": "沈括《梦溪笔谈》"}]}, {"meaning": "终端;终极。", "cites": [{"t": "纵欲而不穷,则民心奋而不可说也。", "b": "《荀子》"}], "words": [{"w": "穷工极巧", "t": "极端精巧"}, {"w": "穷工极态", "t": "极端工巧和富有风致"}, {"w": "穷凶", "t": "极端凶恶。"}]}, {"meaning": "缺陷。", "cites": [{"t": "此其为术,犹有所穷。", "b": "陈亮《酌古论·曹公》"}]}, {"meaning": "恶人。", "cites": [{"t": "上贤而不穷。", "b": "《逸周书》。孔晁注:“穷,谓不肖之人。”"}], "words": [{"w": "穷固", "t": "谓穷凶顽恶"}, {"w": "穷凶极虐", "t": "极端凶恶暴虐。"}]}, {"meaning": "身体。", "cites": [{"t": "注:鞠穷如也。", "b": "《仪礼·聘礼》"}, {"t": "说不行则白道而冥穷。", "b": "《荀子·正名》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('883wx','灾','1','zāi','火','7','','[{"pinyin": "zāi", "defs": [{"meaning": "(会意。甲骨文字形,象火焚屋的形状。小篆从川,表水;从火。水火都是灾祸之源。本义:火灾)。"}, {"meaning": "同本义。", "cites": [{"t": "天火曰烖,从火,哉声。古文从才,籀文从巛声。", "b": "《说文》。或体灾。"}, {"t": "大者曰灾,小者火。", "b": "《公羊传·襄公九年》"}, {"t": "国曰灾,邑曰火。", "b": "《谷梁传·昭公九年》"}, {"t": "火所烧灭之余曰烖,言其余物如是也。", "b": "《释名》"}, {"t": "凡火,人火曰火,天火曰灾。", "b": "《左传·宣公十六年》"}, {"t": "夏四月,陈灾。(陈地发生火灾。)", "b": "《左传·昭公九年》"}], "words": [{"w": "灾火", "t": "火灾"}, {"w": "灾燀", "t": "火灾。"}]}, {"meaning": "灾害,祸患。", "cites": [{"t": "大烖。", "b": "《周礼·司服》。注:“水火为害。”"}, {"t": "祸烖杀礼。", "b": "《周礼·掌客》。注:“新有兵寇水火也。”"}, {"t": "国有大故天烖。", "b": "《周礼·大祝》。注:“疫疠水旱也。”"}, {"t": "灾及其身。", "b": "《荀子·臣道》"}, {"t": "天灾降戾。(戾:猛,凶)", "b": "《国语·周语》"}], "words": [{"w": "灾晦", "t": "灾祸;恶运"}, {"w": "灾燀", "t": "灾祸;灾难"}, {"w": "天灾", "t": "自然灾害"}, {"w": "受灾", "t": "遭受灾害"}, {"w": "灾殃", "t": "灾难"}, {"w": "灾兵", "t": "战争的灾难"}, {"w": "灾疫", "t": "指疫疠这种灾祸"}, {"w": "灾时", "t": "灾变的时间"}, {"w": "灾疚", "t": "祸患疾苦"}, {"w": "灾毒", "t": "祸患"}, {"w": "灾故", "t": "灾患"}, {"w": "灾魔", "t": "祸患;灾难。"}]}, {"meaning": "罪恶。", "cites": [{"t": "灾,纪也。", "b": "《谷梁传》。范宁注:“灾,谓罪恶;纪,治理也。”"}]}, {"meaning": "伤害,使受灾害。", "cites": [{"t": "人君失政,天为异;不改,灾其人民;不改,乃灾其身也。", "b": "《论衡》"}]}, {"meaning": "焚烧。", "cites": [{"t": "滥炎妄起,灾宗庙,烧宫馆。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('884wx','良','1','liáng','艮','7','','[{"pinyin": "liáng", "defs": [{"meaning": "(形声。本义:善良)。"}, {"meaning": "同本义。", "cites": [{"t": "良,善也。", "b": "《说文》"}, {"t": "德音无良。", "b": "《诗·邶风·日月》"}, {"t": "人之无良。", "b": "《诗·鄘风·鹑之奔奔》"}, {"t": "侍中、侍郎郭攸之、费袆、董允等,此皆良实。", "b": "诸葛亮《出师表》"}], "words": [{"w": "天良", "t": "良心"}, {"w": "驯良", "t": "和顺善良"}, {"w": "良正", "t": "善良正直。"}]}, {"meaning": "良好;美好。", "cites": [{"t": "良剑期乎断,不期乎镆铘;良马期乎千里,不期乎骥骜。", "b": "《吕氏春秋·察今》"}, {"t": "故作不良计,勿复怨鬼神。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "良田美池。", "b": "晋·陶渊明《桃花源记》"}, {"t": "赵之良将。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "富家良马。", "b": "《淮南子·人间训》"}], "words": [{"w": "良图", "t": "好办法"}, {"w": "良牧", "t": "好官"}, {"w": "良死", "t": "安享天年而死。即好死、善终"}, {"w": "良沃", "t": "良田,肥沃的田地"}, {"w": "良朋", "t": "好朋友"}, {"w": "良书", "t": "好书,益书"}, {"w": "良罟", "t": "好的渔网"}, {"w": "良贱", "t": "好坏老少之人"}, {"w": "良士", "t": "贤士"}, {"w": "良吏", "t": "贤良的宫吏"}, {"w": "良妻", "t": "贤淑的妻子。即贤妻。"}]}, {"meaning": "优秀。", "cites": [{"t": "天下之良工也。", "b": "《孟子》"}], "words": [{"w": "良弓", "t": "善于制造弓的人"}, {"w": "良工", "t": "技艺精妙的匠人"}, {"w": "良疱", "t": "技艺精妙的厨师"}, {"w": "良匠", "t": "手艺精巧的工匠"}, {"w": "良车", "t": "制作精良的车子"}, {"w": "良史", "t": "古称不畏权势,记事忠于史实的史官"}, {"w": "良干", "t": "廉洁正直的高级官员"}, {"w": "良笔", "t": "指历史家维护正义、忠于史事的记叙笔法。"}]}, {"meaning": "和悦;和善。", "cites": [{"t": "其容良。", "b": "《荀子·非十二子》"}]}, {"meaning": "长,久;深。", "cites": [{"t": "良夜乃罢。", "b": "《汉书》"}], "words": [{"w": "良夜", "t": "长夜"}, {"w": "良宵", "t": "长夜。"}]}, {"meaning": "诚实,信实。", "cites": [{"t": "知虑渐深,则一之以易良。", "b": "《荀子·修身》"}]}, {"meaning": "很,甚,极其,非常。", "cites": [{"t": "清荣峻茂,良多趣味。", "b": "《水经注》"}, {"t": "市者良久计曰。", "b": "唐·柳宗元《童区寄传》"}]}, {"meaning": "确实;果然。", "cites": [{"t": "良多趣味。", "b": "郦道元《水经注》"}], "words": [{"w": "良然", "t": "果然。确实如此。"}]}, {"meaning": "首;头。", "cites": [{"t": "人之所不学而能者,良能也;所不虑不知者,良知也。", "b": "《孟子》"}]}, {"meaning": "首领;首长。", "cites": [{"t": "右无良焉,必败。", "b": "《左传》"}]}, {"meaning": "坟墓。", "cites": [{"t": "阖胡尝视其良,既为秋柏之实矣?", "b": "《庄子·列御寇》"}]}, {"meaning": "认为好。", "cites": [{"t": "良司臣而逸之。", "b": "《左传》"}]}, {"meaning": "能够。", "cites": [{"t": "吾身泯焉,弗良及也。", "b": "《左传·昭公十八年》"}], "words": [{"w": "良比", "t": "堪与比美。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('885wx','证','1','zhèng','讠','7','','[{"pinyin": "zhèng", "defs": [{"meaning": "谏正。", "cites": [{"t": "证,谏也。从言,正声。", "b": "《说文》"}, {"t": "士尉以证靖郭君,靖郭君不听。", "b": "《战国策·齐策》。高诱注:“证,谏也。”"}], "words": [{"w": "证谏", "t": "直言规劝。"}]}, {"meaning": "病症。", "cites": [{"t": "然后先生之言,为思陵对证之药也。", "b": "清·黄宗羲《子刘子行状》"}]}, {"meaning": "假借为“徵”。今亦用为證验字。证据。", "cites": [{"t": "索证正不在远。", "b": "[英]赫胥黎著、严复译《天演论》"}]}, {"meaning": "(形声。从言,正声。繁体为“登”声。本义:告发)。"}, {"meaning": "同本义。", "cites": [{"t": "證,告也。从言,登声。", "b": "《说文》"}, {"t": "其父攘羊,而子证之。", "b": "《论语·子路》"}], "words": [{"w": "证父", "t": "告发父亲。"}]}, {"meaning": "谏诤。 直爽地说出人的过错,劝人改正。", "cites": [{"t": "愎过自用,不可证移。", "b": "《吕氏春秋·巫徒》"}]}, {"meaning": "验证;证实。", "cites": [{"t": "所以證之而不远。", "b": "《楚辞·惜诵》。注:“验也。”"}, {"t": "而胗独证据其事。", "b": "《后汉书·缪肜传》"}, {"t": "援古证今。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": " 证占", "t": "验证"}, {"w": "证验", "t": "验证"}, {"w": "证类", "t": "以同类事物作证"}, {"w": "证审", "t": "验证审察"}, {"w": "证察", "t": "考证审察。"}]}, {"meaning": "佛教用语。参悟,修行得道。", "cites": [{"t": "禅师后证果,居于林虑山。", "b": "唐·张鷟《朝野佥载》"}], "words": [{"w": "证果", "t": "修得妙道"}, {"w": "证圣", "t": "证入圣果"}, {"w": "证悟", "t": "修行得道"}, {"w": "证业", "t": "证悟业果。"}]}, {"meaning": "证据,凭据。", "cites": [{"t": "慎用六證。", "b": "《大戴礼记·文王官人》"}, {"t": "罪无申证,狱不讯鞫。", "b": "《后汉书》"}], "words": [{"w": "证明师", "t": "起到证据作用的人或物"}, {"w": "证左", "t": "指当时在现场亲知亲见其事,可以证明实际情形的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('886wx','启','1','qǐ','口','7','','[{"pinyin": "qǐ", "defs": [{"meaning": "(会意。从户,从口。甲骨文字形,左边是手(又),右边是户(单扇门);用手开门,即开启的意思。后繁化加“口”,或省去手(又)而成“启”。金文又加“攴”(pū)成“啓”。现简化为“启”。本义:开,打开)。"}, {"meaning": "同本义。", "cites": [{"t": "启,开也。", "b": "《说文》"}]}, {"meaning": "经传皆作“啟”。", "cites": [{"t": "公将啟之。", "b": "《左传·隐公元年》"}, {"t": "疆埸无主,则啟戒心。", "b": "《国语·晋语一》"}, {"t": "凡啟塞从时。", "b": "《左传·僖公二十年》。注:“门户道桥谓之啟。”"}, {"t": "啟户。", "b": "《仪礼·士虞礼》"}, {"t": "门启而入。", "b": "《左传》"}, {"t": "启窗而观。", "b": "明·魏学洢《核舟记》"}, {"t": "不能启口。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "启沃", "t": "开诚忠告。旧时指用治国之道开导帝王"}, {"w": "启扉", "t": "开门"}, {"w": "启请", "t": "开口询问;请教"}, {"w": "启户", "t": "开门。"}]}, {"meaning": "启发;教育。", "cites": [{"t": "啟,教也。从攴,启声。", "b": "《说文》"}, {"t": "不愤不啟。", "b": "《论语》"}, {"t": "皆啟以商政。", "b": "《左传·定公四年》"}, {"t": "啟古献公。", "b": "《礼记·祭统》"}, {"t": "佑啟我后人。", "b": "《孟子》"}], "words": [{"w": "启诲", "t": "开导教诲"}, {"w": "启导", "t": "开导;启发指导"}, {"w": "启机", "t": "开启机兆。"}]}, {"meaning": "出发;起程。", "cites": [{"t": "正月啟蛰。", "b": "《仪礼·夏小正》。传:“言始发蛰也。”"}, {"t": "首啟戎行。", "b": "《三国志·武帝纪》"}], "words": [{"w": "启行", "t": "启程,动身上路"}, {"w": "启轮", "t": "轮船起航"}, {"w": "启锚", "t": "谓开船。"}]}, {"meaning": "开拓;开创。", "cites": [{"t": "齐桓公并国三十,启地三千里。", "b": "《韩非子·有度》"}, {"t": "启陨箨以艺粟菽。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "启土", "t": "开拓疆域"}, {"w": "启设", "t": "创设"}, {"w": "启业", "t": "开创基业。"}]}, {"meaning": "启奏;禀告。", "cites": [{"t": "堂上启阿母。", "b": "《玉台新咏 ·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "伏惟启阿母。", "b": ""}, {"t": "某启。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "启帖", "t": "叙述情况的帖子"}, {"w": "启白", "t": "禀告"}, {"w": "启问", "t": "陈述;禀告。"}]}, {"meaning": "跪。", "cites": [{"t": "王事靡盬,不遑启处。", "b": "《诗·小雅·采薇》"}]}, {"meaning": "省视,察看。", "cites": [{"t": "启予足!启予手!", "b": "《论语·泰伯》"}]}, {"meaning": "书信。", "cites": [{"t": "方欲奉启告别,遽辱惠问。", "b": "苏轼《与王敏仲八首》"}]}, {"meaning": "官方文件。", "cites": [{"t": "官信曰启。", "b": "服虔《通俗文》"}]}, {"meaning": "中国古代指立春、立夏。", "cites": [{"t": "凡分、至、启、闭,必书云物。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('887wx','评','1','píng','讠','7','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从言,平声。本义:议论是非高下)。"}, {"meaning": "同本义。", "cites": [{"t": "评,议也。", "b": "《广雅》"}, {"t": "评,评量。", "b": "《广韵》"}, {"t": "嵘品古今诗为评,言其优劣。", "b": "《南史·钟嵘传》"}, {"t": "蔡伯喈评之曰。", "b": "《世说新语·品藻》"}], "words": [{"w": "评决", "t": "评定"}, {"w": "评泊", "t": "量度或评论"}, {"w": "评品", "t": "议论人或事物而定其高下"}, {"w": "评跋", "t": "评论,量度"}, {"w": "评断", "t": "评议决断"}, {"w": "讲评", "t": "讲述和评论"}, {"w": "评质", "t": "评价;品评。"}]}, {"meaning": "评判。", "cites": [{"t": "不可以富贵,不可以评刑。", "b": "《商君书·赏刑》"}], "words": [{"w": "评理", "t": "评判处理"}, {"w": "评决", "t": "评判决定"}, {"w": "评刑", "t": "批评刑法"}, {"w": "评审", "t": "评判审核。"}]}, {"meaning": "棃的一个部件。", "cites": [{"t": "辕之上又有如槽形,亦如箭焉,刻为级,前高而后庳,所以进退,曰“评”。进之则箭下,入土也深。", "b": "唐·陆龟蒙《耒耜经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('888wx','补','1','bǔ','衤','7','','[{"pinyin": "bǔ", "defs": [{"meaning": "(形声。从衣,甫声。本义:补衣服)。"}, {"meaning": "同本义。", "cites": [{"t": "补,完衣也。", "b": "《说文》"}, {"t": "田赞衣补衣。", "b": "《吕氏春秋·顺说》"}, {"t": "补褐防寒岁。", "b": "唐·白居易《村居卧病》"}], "words": [{"w": "补衣;补袜;补衬", "t": "打补丁,衬里子"}, {"w": "补衣", "t": "打过补丁的衣服。"}]}, {"meaning": "修补;整修破旧的东西。", "cites": [{"t": "牵萝补茅屋。", "b": "唐·杜甫《佳人》"}], "words": [{"w": "修桥补路;补天济世", "t": "修补天道,救济世人"}, {"w": "补天", "t": "传说古代之时,苍天西北角有破缺之处,于是女娲氏炼石以补苍天,使无缺损;比喻挽回时运。"}]}, {"meaning": "补充。", "cites": [{"t": "愿令得补黑衣之数。", "b": "《战国策·赵策》"}], "words": [{"w": "填补", "t": "补足空缺或缺欠"}, {"w": "弥补", "t": "把不足的部分填足。"}]}, {"meaning": "弥补。", "cites": [{"t": "维仲山甫补之。", "b": "《诗·大雅·烝民》"}, {"t": "必能裨补阙漏。", "b": "诸葛亮《出师表》"}, {"t": "稀豁之处,锄而补之。", "b": "《齐民要术·种谷》"}], "words": [{"w": "补刖", "t": "弥补被刖的脚跟。比喻矫正缺失,使归真返朴"}, {"w": "补拙", "t": "弥补愚钝"}, {"w": "补苴", "t": "弥补缺漏。"}]}, {"meaning": "济助。", "cites": [{"t": "收孤寡,补贫穷。", "b": "《荀子·王制》"}], "words": [{"w": "补益", "t": "裨补助益"}, {"w": "补报", "t": "增补"}, {"w": "补裨", "t": "增益补阙。"}]}, {"meaning": "补养;滋补。", "cites": [{"t": "静然可以补病。", "b": "《庄子·外物》"}], "words": [{"w": "补理", "t": "滋补调理"}, {"w": "补导", "t": "采补和导引。道家的养生术。"}]}, {"meaning": "春秋时地名 。在今河南省汜水县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('889wx','初','1','chū','刀','7','','[{"pinyin": "chū", "defs": [{"meaning": "(会意。从刀,从衣。合起来表示:用刀剪裁衣服是制衣服的起始。本义:起始,开端)。"}, {"meaning": "同本义。", "cites": [{"t": "初,始也。裁者衣之始也。", "b": "《说文》"}, {"t": "初,舒也。", "b": "《广雅》。按,谓展帛以就裁。"}, {"t": "初吉终乱。", "b": "《易·既济》"}, {"t": "名曰初虑。", "b": "《易·书大传》"}, {"t": "我生之初。", "b": "《诗·王风·兔爰》"}, {"t": "初疾畏惊,见鬼之来。", "b": "《论衡·订鬼》"}, {"t": "初极狭,才通人。复行数十步,豁然开朗。", "b": "陶渊明《桃花源记》"}], "words": [{"w": "初岁", "t": "年初"}, {"w": "初枯", "t": "秋季里植物开始枯萎"}, {"w": "初头", "t": "起初;开头"}, {"w": "初化", "t": "变化之始"}, {"w": "初末", "t": "始末。"}]}, {"meaning": "本原。", "cites": [{"t": "欲知学之力,贤愚同一初。", "b": "唐·韩愈《符读书城南》"}]}, {"meaning": "往昔;当初。", "cites": [{"t": "初,郑武公娶于申。", "b": "《左传·隐公元年》"}, {"t": "初,鲁肃闻刘表卒,言于孙权。", "b": "《资治通鉴·赤壁之战》"}]}, {"meaning": "表示时间、频率,相当于“才”、“刚刚”。", "cites": [{"t": "剑外忽传收蓟北,初闻涕泪满衣裳。", "b": "杜甫《闻官军收河南河北》"}, {"t": "用叶者取叶初长足时。", "b": "李渔《芙蕖》"}], "words": [{"w": "初生", "t": "刚刚出生"}, {"w": "初凉;初寒", "t": ""}]}, {"meaning": "全;本来就。", "cites": [{"t": "受教三日,初不奉行。", "b": "《后汉书》"}]}, {"meaning": "加在“一”至“十”的前面,表示农历一个月前十天的次序。", "cites": [{"t": "八月初一日,上召见袁世凯,特赏侍郎。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "三月初一;五月初五;七月初十", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('890wx','社','1','shè','礻','7','','[{"pinyin": "shè", "defs": [{"meaning": "(会意。从示从土。土亦声。社土同字。本义:土地神)。"}, {"meaning": "同本义。", "cites": [{"t": "社,地主也。", "b": "《说文》"}, {"t": "共工之子句龙为社神。", "b": "《春秋传》"}, {"t": "社,土也。", "b": "《论衡·顺鼓》"}, {"t": "以社以方。", "b": "《诗·小雅·甫田》。传:“社,后土也。”"}, {"t": "命民社。", "b": "《礼记·月令·仲春》。注:“社,后土也。”"}, {"t": "故社,祭社也。", "b": "《荀子·礼论》。注:“社,土神。”"}, {"t": "故祀以为社。", "b": "《国语·鲁语上》。注:“社,后土之神也。”"}, {"t": "不谓之“土”何?封土为社,故变名谓之“社”,利于众土也。", "b": "《白虎通·社稷》"}]}, {"meaning": "又。", "cites": [{"t": "社者,土地之神也。", "b": ""}, {"t": "后土为社。", "b": "《左传·昭公二十九年》"}], "words": [{"w": "社伯", "t": "城隍神"}, {"w": "社鼠", "t": "原指土地庙中的老鼠,后用来比喻仗势作恶的坏人"}, {"w": "社长", "t": "即社神,土地"}, {"w": "社主", "t": "古谓社稷之神;古谓土地神的神主"}, {"w": "社鬼", "t": "即“社公”。古称土地神"}, {"w": "社神", "t": "古代称土地神"}, {"w": "社稷神", "t": "即“土地神”、“谷神”"}, {"w": "社公", "t": "旧称土地神。"}]}, {"meaning": "土地之神的神主。", "cites": [{"t": "用命赏于祖,弗用命戮于社。", "b": "《书·甘誓》"}]}, {"meaning": "祭祀社神之所。", "cites": [{"t": "旧时茅店社林边,路转溪头忽见。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "社稷坛", "t": "旧时帝王祭土神谷神之所。"}]}, {"meaning": "台湾高山族的基层社会组织。史书上称“土社”、“番社”,每社自八、九户至几百户不等,头目多由群众选举,少数世袭。"}, {"meaning": "集体性组织;团体。", "cites": [{"t": "吾社之行为士先者,为之声义。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "社友", "t": "同社之人"}, {"w": "社家", "t": "内行人"}, {"w": "社陌", "t": "社会,社团"}, {"w": "社条", "t": "社团组织制定的条例。"}]}, {"meaning": "社日,祭祀社神的日子。", "cites": [{"t": "佛狸祠下,一片神鸦社鼓!", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "春社;秋社", "t": ""}]}, {"meaning": "机构。"}, {"meaning": "祭祀社神。", "cites": [{"t": "里中设,平为宰,分肉甚均。", "b": "《史记·陈丞相世家》"}], "words": [{"w": "社饭", "t": "祭社时所供的饭食"}, {"w": "社头", "t": "迎神赛社的领土"}, {"w": "社酒", "t": "古代祀社神用的祭酒"}, {"w": "社赛", "t": "祭祀酬谢社神的赛会"}, {"w": "社日", "t": "古时祭祀土神的日子,一般在立春、立秋后第五个戊日"}, {"w": "社肉", "t": "社日祭神之牲肉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('891wx','祀','1','sì','礻','7','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从示,巳声。“示”常与祭祀有关。本义:祭祀天神)。"}, {"meaning": "同本义。", "cites": [{"t": "祀,祭无已也。", "b": "《说文》"}, {"t": "祀,国之大事也。", "b": ""}, {"t": "左传·文公二年》", "b": ""}, {"t": "五祀。", "b": "《周礼·在宗伯》。郑注:“五色之帝。”"}, {"t": "以雷鼓鼓神祀。", "b": "《周礼》。贾公彦疏:“天神称祀,地祗称祭,宗庙称享。”"}]}, {"meaning": "一说指祭祀地神。", "cites": [{"t": "祠,祭也,天祭也。祀,地祭也。", "b": "唐·玄应《一切经音义》"}]}, {"meaning": "祭祀。", "cites": [{"t": "国之大事,在祀与戎。", "b": "《左传·成公十三年》"}, {"t": "祭祀必祝之。", "b": "《战国策》"}, {"t": "瑞抚吴甫半岁,小民闻当去,号泣载道,家绘像祀之。", "b": "《明史·海瑞传》"}], "words": [{"w": "祀灶", "t": "祭灶神。在腊月二十三日,为古代五祀之一"}, {"w": "祀南北郊", "t": "天子即位后在城南郊外祭天,在城北郊外祭地"}, {"w": "祀土", "t": "祭祀土地神"}, {"w": "祀天", "t": "祭祀天神"}, {"w": "祀孔", "t": "指祭祀孔子的典礼"}, {"w": "祀田", "t": "以田租收入供祭祀用的田"}, {"w": "祀社", "t": "祭祀土神"}, {"w": "祀奉", "t": "祭祀供奉"}, {"w": "祀典", "t": "记载祭祀仪礼的典籍"}, {"w": "祀物", "t": "祭祀所用的供物"}, {"w": "祀命", "t": "祭祀的命令"}, {"w": "祀享", "t": "祭祀供献"}, {"w": "祀孤", "t": "祭祀孤魂"}, {"w": "祀姑", "t": "古代旗帜名。"}]}, {"meaning": "祭神的地方。", "cites": [{"t": "过墓则式,过祀则下。", "b": "《礼记》"}], "words": [{"w": "祀堂", "t": "祭殿"}, {"w": "祀舍", "t": "祭祀的房屋,庙宇"}, {"w": "祀场", "t": "古代祭祀地神的处所"}, {"w": "祀坛", "t": "古代祭祀时用土筑的平台。"}]}, {"meaning": "世,代。", "cites": [{"t": "固有文不传于后祀,声遂绝于天下者矣。", "b": "唐·柳宗元《与友人论为文书》"}]}, {"meaning": "中国商代对年的一种称呼。", "cites": [{"t": "惟十有三祀。", "b": "《书·洪范》"}]}, {"meaning": "向神或神明供奉动物或植物食物、酒类、香烛或珍贵物品作为祭祀的行为或举动。", "cites": [{"t": "祀,国之大事也", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('892wx','识','1','shí zhì','讠','7','','[{"pinyin": "shí", "defs": [{"meaning": "(形声。从言。戠(zhí)声。善于言谈,表示有知识,故从言。本义:知道;懂得)。"}, {"meaning": "同本义。", "cites": [{"t": "識,知也。", "b": "《说文》"}, {"t": "君子是识。", "b": "《诗·大雅·瞻卬》。笺:“知也。”"}, {"t": "壹宥曰不识。", "b": "《周礼·司刺》"}, {"t": "草荣识节和,木衰知风厉。", "b": "陶潜《桃花源诗》"}, {"t": "知可以战与不可以战者胜,识众寡之用者胜。", "b": "《孙子·谋攻》"}, {"t": "不识有诸?", "b": "《孟子·梁惠王上》"}, {"t": "苟有险,余必下推车,子岂识之?", "b": "《左传·成公二年》"}, {"t": "使汝不识诗书,或未必艰贞若是。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "识味", "t": "知味"}, {"w": "识空便", "t": "知趣;识相"}, {"w": "识道", "t": "知圣道"}, {"w": "识义", "t": "知义理。"}]}, {"meaning": "认识。", "cites": [{"t": "今为所识穷乏者得我而为之。", "b": "《孟子·告子上》"}, {"t": "仲永生五年,未尝识书具。", "b": "王安石《伤仲永》"}, {"t": "儿童相见不相识,笑问客从何处来。", "b": "贺知章《回乡偶书》"}, {"t": "莫愁前路无知己,天下谁人不识君!", "b": "唐·高适《别董大》"}], "words": [{"w": "识路", "t": "认识道路"}, {"w": "相识", "t": "彼此认识"}, {"w": "识丁", "t": "认识字"}, {"w": "识认", "t": "认识。"}]}, {"meaning": "赏识。", "cites": [{"t": "林识拔同郡王经于民户之中,卒为民士。", "b": "陈寿《三国志》"}], "words": [{"w": "识鉴", "t": "赏识鉴别"}, {"w": "识举", "t": "赏识并举用"}, {"w": "识遇", "t": "赏识知遇。"}]}, {"meaning": "感觉;识别;辨别。", "cites": [{"t": "新妇识马声,蹑履相逢迎。", "b": "《古诗为焦仲卿妻作》"}, {"t": "何用识夫婿?白马从骊驹。", "b": "《乐府诗集·陌上桑》"}, {"t": "独其为文犹可识曰“花山”。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "识宝太师", "t": "受贿的贪官"}, {"w": "识主", "t": "识货的买主"}, {"w": "识真", "t": "识别真相"}, {"w": "识理", "t": "辨认和理解。"}]}, {"meaning": "见识;知识。", "cites": [{"t": "贾生志大而量小,才有余而识不足也。", "b": "苏轼《贾谊论》"}, {"t": "非学无以致疑,非问无以广识。", "b": "清·刘开《问说》"}, {"t": "识者固知元政紊驰而变兴自下之渐矣。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "常识;才识", "t": "才能和见识"}, {"w": "胆识;才益多者其识远;识略", "t": "见识与谋略"}, {"w": "识面", "t": "世面"}, {"w": "识野", "t": "个人一瞬间在内心中意识所及的范围或所能觉知之意念的范围"}, {"w": "识断", "t": "具有见识,并能判断"}, {"w": "识远", "t": "见识远大。"}]}, {"meaning": "相知的朋友。", "cites": [{"t": "异乡无旧识,车马到门稀。", "b": "唐·刘禹锡《元日感怀》"}]}, {"meaning": "思想或意识。", "cites": [{"t": "阮公虽沦迹,识密鉴亦洞。", "b": "颜延年《五君咏》"}], "words": [{"w": "识想", "t": "思想;意念。"}]}, {"meaning": "刚才。", "cites": [{"t": "识见不谷而趋。(刚才看见我却很快躲开了。)", "b": "《左传·成公十六年》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhì", "defs": [{"meaning": "旗帜", "cites": [{"t": "京师闻青徐贼众数十万人,讫无文号旌旗表识,咸怪异之。", "b": "《汉书·王莽传下》"}]}, {"meaning": "古代钟鼎上凸出的文字。", "cites": [{"t": "广西土中铜鼓…周围款识,其圆纹为古钱,其方文如织簟。", "b": "《岭外代答》"}]}, {"meaning": "标记。", "cites": [{"t": "以龙熊鸟雀为识。", "b": "《宝刀赋序》"}], "words": [{"w": "标识", "t": "标志。"}]}, {"meaning": "加上标记", "cites": [{"t": "识以柳枝,命本部涉济。", "b": "《金史》"}], "words": [{"w": "识别", "t": "加上标记使有区别。"}]}, {"meaning": "记住。", "cites": [{"t": "小子识之,苛政猛于虎也。", "b": "《礼记·檀弓下》"}, {"t": "默而识之。", "b": "《论语·述而》"}, {"t": "文镂无款哀。", "b": "《史记·孝武纪》"}, {"t": "以计识其人众畜牧。", "b": "《汉书·匈奴传上》。师古曰:“识亦记也。”"}, {"t": "贤者识其大者,不贤者识其小者。", "b": "《论语·子张》"}], "words": [{"w": "识念", "t": "记忆"}, {"w": "博闻强识", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('893wx','诈','1','zhà','讠','7','','[{"pinyin": "zhà", "defs": [{"meaning": "(形声。从言,乍声。从言,说明与言论有关。本义:欺骗)。"}, {"meaning": "同本义。", "cites": [{"t": "诈,欺也。", "b": "《说文》"}, {"t": "诈,伪也。", "b": "《尔雅》"}, {"t": "匿行曰诈。", "b": "《荀子·脩身》"}, {"t": "有掎挈伺诈。", "b": "《荀子·富国》"}, {"t": "繁战之君,不足于诈。", "b": "《吕氏春秋·义赏》"}, {"t": "无功伐而求荣富,诈也。", "b": "《吕氏春秋·务本》"}, {"t": "相如度秦王特以诈佯为予赵城,实不可得。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "禽兽之变诈。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "诈端", "t": "讹诈的理由"}, {"w": "诈掯", "t": "敲诈勒索"}, {"w": "诈哄", "t": "欺骗"}, {"w": "诈伪", "t": "欺骗"}, {"w": "诈力", "t": "诈术与暴力"}, {"w": "诈人", "t": "专务诈欺作伪的人。"}]}, {"meaning": "假装;冒充。", "cites": [{"t": "诈自称公子。", "b": "《史记·陈涉世家》"}, {"t": "乃诈称公子。", "b": ""}, {"t": "诈云欲降。", "b": "《资治通鉴》"}], "words": [{"w": "诈酒三分醉", "t": "喝酒不多却装做醉酒"}, {"w": "诈使命", "t": "假使节;伪装的使节"}, {"w": "诈允", "t": "假装允诺"}, {"w": "诈狂", "t": "假装颠狂"}, {"w": "诈死", "t": "假装死去"}, {"w": "诈痴不颠", "t": "假装痴呆。"}]}, {"meaning": "用语言试探,诱使对方露真情。", "cites": [{"t": "谁不知道李十太爷是能事的!把我一诈,就吓毛了!", "b": "《红楼梦》"}], "words": [{"w": "他是拿话诈我", "t": ""}]}, {"meaning": "体面;俊俏。", "cites": [{"t": "打扮的身子儿诈,准备着云雨会巫峡。", "b": "《西厢记》"}]}, {"meaning": "矜夸;神气。", "cites": [{"t": "只待要弄柳拈花,马儿上扭捏着身子儿诈。", "b": "元·郑廷玉《看钱奴买冤家债主》"}]}, {"meaning": "不诚实;虚伪。", "cites": [{"t": "先诈力而后仁义。", "b": "贾谊《过秦论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('894wx','诉','1','sù','讠','7','','[{"pinyin": "sù", "defs": [{"meaning": "(形声。本义:告状;控告)。"}, {"meaning": "同本义。", "cites": [{"t": "诉,告也。", "b": "《说文》"}, {"t": "负孝公之周愬天子。", "b": "《公羊传·昭公三十一年》"}, {"t": "必东愬于齐。", "b": "《战国策·齐策》"}, {"t": "即连楮为巨幅,广二丈,大书一“屈”字,以两竿夹揭之,走诉行御史台。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "起诉;上诉;公诉;诉呈", "t": "诉状"}, {"w": "诉权", "t": "起诉和诉原的权利"}, {"w": "诉辩", "t": "申诉并辩白"}, {"w": "诉牒", "t": "诉状"}, {"w": "诉告", "t": "上诉;告状。"}]}, {"meaning": "告诉,说给人听。", "cites": [{"t": "正遇延平二人,诉说前事。", "b": "《三国演义》"}, {"t": "弦弦掩抑声声思,似诉平生不得志。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "吾与并肩携长,低低切切,何事不语?何情不诉?", "b": "林觉民《与妻书》"}], "words": [{"w": "诉怨", "t": "对人诉说怨愤之情"}, {"w": "诉长道短", "t": "原原本本地向人诉说"}, {"w": "诉事", "t": "陈诉事情"}, {"w": "诉屈", "t": "申诉冤屈"}, {"w": "诉言", "t": "诉说。"}]}, {"meaning": "有事实根据地说人坏话。通“愬。", "cites": [{"t": "取货于宣伯而诉公于晋侯。", "b": "《左传·成公十六年》"}, {"t": "公伯寮愬子路于季孙", "b": "《论语·宪问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('895wx','罕','1','hǎn','冖','7','','[{"pinyin": "hǎn", "defs": [{"meaning": "(古字为爳”。形声。小篆字形,从网,干声。本义:捕鸟用的长柄小网)。"}, {"meaning": "同本义。", "cites": [{"t": "爳,网也。《说文》", "b": ""}, {"t": "罕车飞扬。", "b": "扬雄《羽猎赋》"}, {"t": "毕曰罕车,主弋猎。", "b": "《史记·天官书》"}], "words": [{"w": "罕车", "t": "载有猎狩等网具的车;星宿名,毕宿的别名。因毕八星排列如网,故名。"}]}, {"meaning": "旌旗名。", "cites": [{"t": "云罕九游。", "b": "张衡《东京赋》"}], "words": [{"w": "罕旗", "t": "古代帝王所用的旗帜。旗有九斿,或有九旒"}, {"w": "罕毕", "t": "古代帝王仪仗之旗。"}]}, {"meaning": "稀;少。", "cites": [{"t": "叔发罕忌。", "b": "《诗·郑风·大叔于田》"}, {"t": "罕见曰闻名。", "b": "《礼记·少仪》"}, {"t": "盖以罕书也。", "b": "《公羊传·桓公六年》"}, {"t": "则功筑罕。", "b": "《谷梁传·庄公二十九年》"}, {"t": "子罕言利。", "b": "《论语·子罕》"}, {"t": "人之罕至。", "b": "宋·王安石《游褒禅山记》"}, {"t": "与人罕言语。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "罕物", "t": "希罕的、名贵的物品"}, {"w": "罕事", "t": "少有的事"}, {"w": "罕伦", "t": "很少能够与之相比"}, {"w": "罕闻", "t": "很少听说"}, {"w": "罕发", "t": "很少发生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('896wx','诊','1','zhěn','讠','7','','[{"pinyin": "zhěn", "defs": [{"meaning": "(形声。从言。诊断需要询问,故从言。本义:看病)。"}, {"meaning": "同本义。", "cites": [{"t": "诊,候也。", "b": "《三苍》"}, {"t": "诊,验也。", "b": "《通俗文》"}, {"t": "诊其所疾。", "b": "《列子·力命》。释文:“候脉也。”"}, {"t": "特以诊脉为名耳。", "b": "《史记·扁仓传》"}, {"t": "原诊以知政。", "b": "《汉书·艺文志》。注:“谓视其脉及色候也。”"}, {"t": "郎中诊罢,嘻嘻的冷笑。", "b": "《西厢记诸宫调》"}]}, {"meaning": "验看;辨别。", "cites": [{"t": "匠石觉而诊其梦。", "b": "《庄子·人间世》。司马注:“占梦也。”"}, {"t": "群臣怪而诊之,乃吴将军首也。", "b": "《后汉书》"}]}, {"meaning": "整治。", "cites": [{"t": "顶好把那个兔崽子也诊他一诊,给他点儿王法。", "b": "张天翼《反攻·脊背与奶子》"}]}, {"meaning": "症状。", "cites": [{"t": "五藏之形状不同者何?愿闻其诊及其病能。", "b": "《素问·风论》"}, {"t": "听问其诊。", "b": "《素问·风论》。注:“谓可言之证。”"}]}, {"meaning": "引申为情况,征兆。", "cites": [{"t": "夫喜怒章于色诊,哀乐亦宜形于声音。", "b": "三国魏·嵇康《声无哀乐论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('897wx','词','1','cí','讠','7','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从言,司声。本义:言词。按,“辞”、“词”在“言词”这个意义上是同义词。但在较古的时代,一般只说“辞”,不说“词”。汉代以后逐渐以“词”代“辞”)。"}, {"meaning": "同本义。", "cites": [{"t": "词,意内而言外也。", "b": "《说文》"}, {"t": "词色甚强。", "b": "《世说新语·轻诋》"}, {"t": "听妇前致词:三男邺城戍。", "b": "杜甫《石壕吏》"}, {"t": "门者故不入,则甘言媚词,作妇人状,袖金以私之。", "b": "宗臣《报刘一丈书》"}], "words": [{"w": "名词;动词;形容词;词色", "t": "声色"}, {"w": "词锋", "t": "犀利的文笔,好像刀剑的锋芒"}, {"w": "词不达意", "t": ""}]}, {"meaning": "诗文中的词语。", "cites": [{"t": "纵豆蔻词工,青楼梦好,难赋深情。", "b": "姜夔《扬州慢》"}], "words": [{"w": "词科", "t": "文词科场;科举考场"}, {"w": "词场", "t": "文坛、文苑、文辞荟萃的地方;文词科试的场所"}, {"w": "词翰", "t": "词章"}, {"w": "词章", "t": "文辞的通称。后用以专称诗赋文章而言。"}]}, {"meaning": "状纸;诉讼。", "cites": [{"t": "次日,一乘轿子抬到县门口,正值知县坐早堂,就喊了冤,知县叫补进词来。", "b": "《儒林外史》"}], "words": [{"w": "词状", "t": "状词;诉状"}, {"w": "词因", "t": "原因,情由。多指供词,讼状所陈述的内容"}, {"w": "词讼", "t": "同辞讼。诉讼。"}]}, {"meaning": "文体名,诗歌的一种 。一种韵文形式,由五言诗、七言诗或民间歌谣发展而成,起于唐代,盛于宋代。原是配乐歌唱的一种诗体,句的长短随歌调而改变,因此又叫长短句。有小令和慢词两种,一般分上下两阕。"}, {"meaning": "说,告诉。", "cites": [{"t": "其词于宾曰。", "b": "《礼记·曾子问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('898wx','译','1','yì','讠','7','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从言,睪(yì)声。本义:翻译,把一种语言文字翻译成另一种语言文字)。"}, {"meaning": "同本义。", "cites": [{"t": "译,传译四夷之言者。", "b": "《说文》"}, {"t": "译,传也。", "b": "《方言十三》"}, {"t": "北方曰译。", "b": "《礼记·王制》"}, {"t": "重舌之人九译。", "b": "张衡《东京赋》"}, {"t": "译者称西人。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "译欧西人之言。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "汉语被译成日语;译品", "t": "翻译的作品"}, {"w": "译义", "t": "意译"}, {"w": "译写", "t": "翻译写作"}, {"w": "译经", "t": "翻译经典。"}]}, {"meaning": "解释;阐述。", "cites": [{"t": "夫圣人为天口,贤者为圣译。", "b": "《潜夫论》"}]}, {"meaning": "选择。", "cites": [{"t": "周道衰微,失爵亡邦,后嗣乖散,各相土译居。", "b": "《隶释·汉孟郁修尧庙碑》"}], "words": [{"w": "译居", "t": "择居。"}]}, {"meaning": "翻译人员。", "cites": [{"t": "于是乃召越译,乃楚说之。", "b": "刘向《说苑》"}], "words": [{"w": "译费", "t": "支付给翻译人员的钱"}, {"w": "译界", "t": "翻译界"}, {"w": "译员", "t": "翻译工作者。"}]}, {"meaning": "异域。", "cites": [{"t": "沧波伏忠信,译语辨讴谣。", "b": "唐·顾况《送从兄使新罗》"}], "words": [{"w": "译语", "t": "异域的语言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('899wx','君','1','jūn','口','7','','[{"pinyin": "jūn", "defs": [{"meaning": "(会意。从尹,从口。“尹”,表示治事;从“口”,表示发布命令。合起来的意思是:发号施令,治理国家。本义:君主,国家的最高统治者)。"}, {"meaning": "古代大夫以上据有土地的各级统治者的通称。", "cites": [{"t": "君,尊也。", "b": "《说文》"}, {"t": "赏庆刑威曰君。", "b": "《左传·昭公二十八年》"}, {"t": "君也者,掌令者也。", "b": "《春秋繁露》"}, {"t": "君者,治辨之主也。", "b": "《荀子·礼论》"}, {"t": "君帝清问下民。", "b": "《书·吕刑》"}, {"t": "克长克君。", "b": "《诗·大雅·皇矣》"}, {"t": "二十余君。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "思得明君。", "b": "《三国志·诸葛亮传》"}, {"t": "则忧其君。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "身名君宠。", "b": "清·周容《芋老人传》"}], "words": [{"w": "尧舜之君;欺君罔上;贤君;暴君;昏君;国君;君臣;明君;君王", "t": "古时对帝王的一种尊称"}, {"w": "君伐", "t": "君王的功绩"}, {"w": "君位", "t": "国君之位"}, {"w": "君长", "t": "国君与卿大夫;天子或诸侯"}, {"w": "君体", "t": "人主的体统"}, {"w": "君德", "t": "人主的德行或恩德"}, {"w": "君侯", "t": "古代对列侯的尊称"}, {"w": "君公", "t": "诸侯"}, {"w": "君父", "t": "对父为国君者的称呼"}, {"w": "君子医", "t": "术精德高的名医。"}]}, {"meaning": "封建制度的一种尊号,尤指君主国家所封的称号或封号。", "cites": [{"t": "君以十五之地存。", "b": "《战国策·魏策》"}], "words": [{"w": "平原君;春申君;武安君", "t": ""}]}, {"meaning": "引申为人的尊称,相当于“您”。", "cites": [{"t": "君有疾。", "b": "《韩非子·喻老》"}, {"t": "君之病在肌肤。", "b": ""}, {"t": "君之病在肠胃。", "b": ""}, {"t": "况君前途尚可。", "b": "《世说新语·自新》"}, {"t": "落花时节又逢君。", "b": "唐·杜甫《江南逢李龟年》"}], "words": [{"w": "诸君;李君;王君;祝君早安;请君光临;君子不羞当面", "t": "君子不以当面把话说清楚为羞。"}]}, {"meaning": "夫妇之间的尊称。", "cites": [{"t": "君行虽不远,守边赴河阳。", "b": "杜甫《新婚别》"}, {"t": "君问归期未有期。", "b": "李商隐《夜雨寄北》"}], "words": [{"w": "夫君;君姑", "t": "古时妻子称丈夫的母亲"}, {"w": "君舅", "t": "古时妻子称丈夫的父亲。"}]}, {"meaning": "主宰、统治。", "cites": [{"t": "君之宗之。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "君火", "t": "中医称主宰神明之火。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('900wx','灵','1','líng','火','7','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从巫,靈(líng)声。本义:巫)。"}, {"meaning": "古时楚人称跳舞降神的巫为灵。", "cites": [{"t": "灵,灵巫也。以玉事神。", "b": "《说文》"}, {"t": "命灵氛为余占之。", "b": "《离骚》"}, {"t": "灵连踡兮既留。", "b": "《楚辞·云中君》"}, {"t": "灵偃蹇兮姣胶。", "b": "屈原《东皇太一》"}], "words": [{"w": "灵子", "t": "指巫。以舞导引神的人。"}]}, {"meaning": "神灵。", "cites": [{"t": "天神曰灵。", "b": "《尸子》"}, {"t": "灵者,神也。", "b": "《风俗通》"}, {"t": "阳之精气曰神,阴之精气曰灵。", "b": "《大戴礼记·曾子问》"}, {"t": "合五岳与八灵兮。", "b": "《楚辞·怨思》。注:“八方之神也。”"}, {"t": "灵之来兮如云。", "b": "屈原《九歌·湘夫人》"}], "words": [{"w": "灵神", "t": "神灵"}, {"w": "灵祗", "t": "神明;神灵"}, {"w": "灵霄殿", "t": "天帝的神殿"}, {"w": "灵怪", "t": "神怪"}, {"w": "灵圣", "t": "灵验,指神鬼显灵"}, {"w": "灵圣儿", "t": "指神佛塑像中放置的金属作的心脏象征物"}, {"w": "灵河", "t": "书中虚拟的仙河"}, {"w": "灵槎", "t": "神仙乘的木筏"}, {"w": "灵山", "t": "佛家称灵鹫山为灵山。佛祖居处。也泛指仙山。"}]}, {"meaning": "灵魂。", "cites": [{"t": "经始灵台。", "b": "《诗·大雅·灵台》"}, {"t": "天子太庙上可以望气,故谓之灵台。", "b": "《礼记·明堂位》卢注"}, {"t": "藏之于灵室。", "b": "《素问·气交变大论》。注:“谓灵兰室,黄帝之书府也。”"}, {"t": "以告先帝之灵。", "b": "诸葛亮《出师表》"}, {"t": "吾灵尚依依旁汝。", "b": "清·林觉民《与妻书》"}, {"t": "汝倘有灵。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "灵爽", "t": "灵魂"}, {"w": "灵表", "t": "仪表"}, {"w": "灵明", "t": "指心灵"}, {"w": "灵知", "t": "指心灵"}, {"w": "灵界", "t": "佛家语。指云魂所住的世界。"}]}, {"meaning": "敬辞。用以称有关鬼神的事物。对死者的敬称。", "cites": [{"t": "在缸内画上灵符。", "b": "清·钱彩等《说岳全传》"}], "words": [{"w": "灵床子", "t": "人死后虚设的坐卧之具,供祭尊用;又指供在灵床上写有死者名字的牌位"}, {"w": "灵幡", "t": "殡葬时所持之幡,上写有表明死者身分的文字"}, {"w": "灵符", "t": "道士画的图形。迷信者认为可用于驱使鬼神、祭祷和治病等"}, {"w": "灵前", "t": "灵位之前。"}]}, {"meaning": "灵柩的简称。", "cites": [{"t": "孤魂翔故域,灵柩寄京师。", "b": "曹植《赠白马王彪》"}], "words": [{"w": "停灵;起灵;灵榇", "t": ""}]}, {"meaning": "指人的精神状态。", "cites": [{"t": "不可内于灵台。不可入于灵府。", "b": "《庄子·德充府》。注:“皆谓心也。”"}], "words": [{"w": "心灵", "t": "指内心、精神、思想等"}, {"w": "灵明", "t": "指“心”,即主观精神。"}]}, {"meaning": "窗中竖木。", "cites": [{"t": "载葱(即窗)灵,寝于其中而逃。", "b": "《左传·定公九年》。疏:“贾逵曰:‘葱灵,衣车也。’然则此车前后有蔽,两旁开葱,可以观望;忽中竖木,谓之灵。今人犹名葱木为灵子。”"}]}, {"meaning": "指天、地、日、月等尊称及物品名。", "cites": [{"t": "辰之神为灵星。", "b": "《风俗通》"}, {"t": "灵星,火星也。", "b": "蔡邕《独断》"}], "words": [{"w": "灵景", "t": "日光"}, {"w": "灵汉", "t": "银河"}, {"w": "灵图", "t": "指天子的地位"}, {"w": "灵辉", "t": "太阳的光辉。"}]}, {"meaning": "威灵;福气,福分。", "cites": [{"t": "若以大夫之灵,得保首领以没。", "b": "《左传·隐公三年》"}, {"t": "受天之祐,享鬼神之灵。", "b": "《汉书·董仲舒传》"}]}, {"meaning": "茯苓。", "cites": [{"t": "伏灵者,千岁松根也。", "b": "《史记·策列传》"}]}, {"meaning": "有窗的小船。", "cites": [{"t": "横大江兮扬灵。", "b": "《楚辞·九歌·湘君》"}]}, {"meaning": "命令、法令。", "cites": [{"t": "或问循吏,曰:吏也。游侠,曰:窃国灵也。", "b": "《法言·渊骞》"}]}, {"meaning": "假借为“良”。善,美好。", "cites": [{"t": "灵,善也。", "b": "《广雅》"}, {"t": "吊由灵。", "b": "《书·盘庚》"}, {"t": "丕灵承帝事。", "b": "《书·多士》"}, {"t": "灵雨既零。", "b": "《诗·鄘风·定之方中》"}, {"t": "积仁为灵。", "b": "《说苑·修文》"}], "words": [{"w": "灵辰", "t": "良时"}, {"w": "灵波", "t": "美妙的水波"}, {"w": "灵姿", "t": "美好的仪表。"}]}, {"meaning": "灵活;有灵性。", "cites": [{"t": "水不在深,有龙则灵。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "机灵", "t": "聪明伶俐"}, {"w": "灵矫", "t": "灵巧的飞翔"}, {"w": "灵透", "t": "机灵聪明"}, {"w": "灵变", "t": "灵活变通;灵敏轻巧"}, {"w": "灵断", "t": "明敏的判断"}, {"w": "灵变", "t": "灵活变通"}, {"w": "心灵手巧;灵修", "t": "能神明远见的人。比喻国君"}, {"w": "灵鉴", "t": "明敏的观察,英明的见解"}, {"w": "灵主", "t": "圣明的君主。"}]}, {"meaning": "应验;灵验。", "cites": [{"t": "灵用不同。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "灵神", "t": "灵验"}, {"w": "灵丹", "t": "灵药,神奇有效的丹药"}, {"w": "灵砂", "t": "道家炼出的所谓长生不老药"}, {"w": "灵异", "t": "神奇而怪异"}, {"w": "灵武", "t": "超绝的勇武"}, {"w": "灵芬", "t": "神奇的芬芳。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('901wx','即','1','jí','卩','7','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。甲骨文作坐人形(后讹为卩)面对食器(皀)会意。本义:走近去吃东西)。"}, {"meaning": "同本义。", "cites": [{"t": "即,就食也。", "b": "《说文》"}, {"t": "席末取粮即稻。", "b": "《仪礼·公食礼》"}, {"t": "鼎有实,我仇有疾,不我能即。", "b": "《易·鼎》。高亨注:“《说文》:‘即,就食也。’此用其本义。”"}]}, {"meaning": "基本义是接近、靠近、走向,与“离”对举。", "cites": [{"t": "将即席。", "b": "《礼记·曲礼》"}, {"t": "匪来贸丝,来即我谋。", "b": "《诗·卫风·氓》"}, {"t": "神即形也,形即神也。", "b": "范缜《神灭论》"}, {"t": "夜半,童自转,以缚即炉火烧绝之。", "b": "柳宗元《童区寄传》"}], "words": [{"w": "若即若离", "t": ""}]}, {"meaning": "登上;走上。", "cites": [{"t": "公即位。", "b": "《春秋·桓公元年》"}, {"t": "山行即桥。", "b": "《史记·河渠书》"}, {"t": "及庄公即位,为之请制。", "b": "《左传·隐公元年》"}], "words": [{"w": "即阼", "t": "即位。皇帝登极叫即阼。因古时新天子登基,有升登东阶而主祭的仪式,所以叫即阼。阼:东阶"}, {"w": "即真", "t": "正式就皇帝位。后世以官职由代理而改为实授,也称即真"}, {"w": "即禽", "t": "打猎,在野外猎取禽兽"}, {"w": "即祚", "t": "皇席即位登基。"}]}, {"meaning": "虽然。", "cites": [{"t": "小即小,天生的口不曾合。", "b": "《西厢记诸宫调》"}]}, {"meaning": "假若。", "cites": [{"t": "即有不称。(如果不能称将军之职。意即打败仗。)", "b": "汉·刘向《列女传》"}, {"t": "即不幸有方二三千里之旱,国胡以相恤。", "b": "汉·贾谊《论积贮疏》"}]}, {"meaning": "即使。", "cites": [{"t": "公子即合符。(即,即使。)", "b": "《史记·魏公子列传》"}, {"t": "即不幸有方二三千里之旱。", "b": "汉·贾谊《论积贮疏》"}, {"t": "即谋单于。", "b": "东汉·班固《汉书·李广苏建传》"}, {"t": "即捕得三两头。", "b": "《聊斋志异·促织》"}, {"t": "其伤于缚者,即幸留,病数月乃瘳,或竟成痼疾。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "即或", "t": ""}]}, {"meaning": "那就。", "cites": [{"t": "即患秦兵之来。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "不死即已。", "b": "《史记·陈涉世家》"}, {"t": "死即举大名。", "b": ""}, {"t": "即更刮目相待。(即,就。)", "b": "《资治通鉴·汉纪》"}]}, {"meaning": "就在某时某处;乘,趁。", "cites": [{"t": "即其帐中斩宋义头。", "b": "《史记·项羽本纪》"}, {"t": "即时诛灭。", "b": "《汉书·李广苏建传》"}, {"t": "即如前年…一事。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "即忙", "t": "连忙;赶紧"}, {"w": "即拜", "t": "就在所在地授予官职"}, {"w": "即早", "t": "及早;趁早。"}]}, {"meaning": "当。", "cites": [{"t": "即此风云佳,孤觞聊可命。", "b": "南朝齐·谢朓《赋贫民田》"}], "words": [{"w": "即此", "t": "就此;只此。"}]}, {"meaning": "立刻,当即。", "cites": [{"t": "王即临之。", "b": "晋·干宝《搜神记》"}, {"t": "太守即遣人随其往。", "b": "晋·陶渊明《桃花源记》"}, {"t": "处即刺杀虎。", "b": "《世说新语·自新》"}, {"t": "即书诗四句。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "即速", "t": "立刻;赶快。"}]}, {"meaning": "那就是说,那就是。", "cites": [{"t": "民死亡者,非其父兄,即其子弟。", "b": "《左传·襄公八年》"}, {"t": "梁父即楚将项燕。", "b": "《史记·项羽本纪》"}, {"t": "即今之傫然在墓者。", "b": "明·张溥《五人墓碑记》"}, {"t": "即此爱汝。", "b": "清·林觉民《与妻书》"}, {"t": "即如忠烈遗骸。", "b": "清·全祖望《梅花岭记》"}, {"t": "身外即战场。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "即是", "t": ""}]}, {"meaning": "烛头烬。", "cites": [{"t": "左手执烛,右手折即。", "b": "《管子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('902wx','层','1','céng','尸','7','','[{"pinyin": "céng", "defs": [{"meaning": "(形声。从尸,尸者象屋形,从屋省。本义:楼房)。"}, {"meaning": "同本义。", "cites": [{"t": "层,重屋也。", "b": "《说文》"}, {"t": "珠殿连云,金层辉景。", "b": "刘孝绰《栖隐寺碑》"}], "words": [{"w": "层楹", "t": "高楼大厦。"}]}, {"meaning": "重叠。", "cites": [{"t": "高堂邃宇,槛层轩些。", "b": "《楚辞·招魂》"}]}, {"meaning": "又。", "cites": [{"t": "层台累榭。", "b": ""}, {"t": "巡曾楹而空楹。", "b": "《文选·江淹·别赋》"}, {"t": "熊咆龙吟殷岩泉,慄深林兮惊层巅。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "层观", "t": "重叠高耸的宫观楼宇"}, {"w": "层台", "t": "多层的高台"}, {"w": "层云", "t": "重重云层"}, {"w": "层澜", "t": "叠起的波浪。"}]}, {"meaning": "重复,连接不断。", "cites": [{"t": "而境界危恶,层见错出,非人世所堪。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "量的单位,用于重叠的、有层次的事物。", "cites": [{"t": "云盖三层。", "b": "《山海经·海外西经》"}], "words": [{"w": "一层油漆;一层薄冰;两层玻璃,五层楼", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('903wx','屁','1','pì','尸','7','','[{"pinyin": "pì", "defs": [{"meaning": "肠道产生但从肛门突然排出的臭气", "words": [{"w": "屁滚尿流", "t": ""}, {"w": "放屁", "t": ""}]}, {"meaning": "屁股,臀部", "words": [{"w": "拍马屁", "t": ""}, {"w": "屁眼", "t": "肛门"}]}, {"meaning": "常用来骂人或指斥诗文、言语的荒谬。"}, {"meaning": "比喻没用的、微不足道的事物", "words": [{"w": "屁事", "t": ""}, {"w": "屁精", "t": "指油头粉面的男青年"}, {"w": "屁雌寡淡", "t": "[方言]比喻一无所用"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('904wx','尿','1','niào suī','尸','7','','[{"pinyin": "niào", "defs": [{"meaning": "(会意。从尸,从水。尸代表人体。本义:小便) 同本义。", "cites": [{"t": "尿,人小便也。", "b": "《说文》。古书多假溺为之。"}], "words": [{"w": "糠尿病;尿鳖", "t": "尿壶。骂人之语,厌恶的人。"}]}]}, {"pinyin": "suī", "defs": [{"meaning": "", "words": [{"w": "膀胱又名尿脬;撒尿又叫“屙尿”;尿尿(niàosuī):小便;尿胞(尿脬", "t": ""}, {"w": "尿胞种子", "t": "尿脬内是空的。指不能发芽生长的空壳种子。咒骂小儿长不大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('905wx','尾','1','wěi yǐ','尸','7','','[{"pinyin": "wěi", "defs": [{"meaning": "(会意。从倒毛在尸后。尸,指人。象人长有尾巴。本义:人或动物的尾巴)。"}, {"meaning": "同本义。", "cites": [{"t": "尾,微也。", "b": "《说文》"}, {"t": "履虎尾 ,未济,濡其尾。", "b": "《易·履》"}], "words": [{"w": "虎尾;牛尾;尾大", "t": "比喻臣下势力强大"}, {"w": "尾君子", "t": "指猴子。"}]}, {"meaning": "末端,末尾。", "cites": [{"t": "渤海之尾。", "b": "《列子·汤问"}, {"t": "运于渤海之尾。", "b": ""}, {"t": "系于其尾。", "b": "《资治通鉴》"}, {"t": "舟尾横卧一楫。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "首尾;无头无尾;尾末", "t": "末尾;尾宿之末"}, {"w": "尾句", "t": "句尾"}, {"w": "尾页", "t": "末页。"}]}, {"meaning": "边际,边界。", "cites": [{"t": "夫边境者,国之尾也。", "b": "《国语》"}]}, {"meaning": "后部。", "cites": [{"t": "是我起兵已首尾期月矣。", "b": "方勺《方腊起义》"}]}, {"meaning": "鸟兽虫鱼交配。", "cites": [{"t": "鸟兽孳尾。", "b": "《书·尧典》"}, {"t": "雄雌在前,孳尾成群。", "b": "《列子》"}]}]}, {"pinyin": "yǐ", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('906wx','迟','1','chí','辶','7','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。本义:慢慢走)。"}, {"meaning": "同本义。泛指慢。", "cites": [{"t": "迟,徐行也。", "b": "《说文》"}, {"t": "迟,缓也。", "b": "《广雅》"}, {"t": "废彻不迟。", "b": "《诗·小雅·楚茨》"}, {"t": "行道迟迟。", "b": "《诗·邶风·谷风》"}, {"t": "迟归有待。", "b": "《易·归妹》"}, {"t": "陵迟故也。", "b": "《荀子·宥坐》"}, {"t": "三日断五匹,大人故嫌迟。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "迟徐", "t": "缓慢"}, {"w": "迟滞", "t": "缓慢阻滞。"}]}, {"meaning": "迟钝;反应慢,不灵敏。", "cites": [{"t": "料事同而迟速不同。", "b": "魏源《默觚下》"}, {"t": "周少言重迟。", "b": "《汉书·杜周传》。注:“谓性非敏速也。”"}]}, {"meaning": "迟疑;犹豫。", "cites": [{"t": "寻声暗问弹者谁,琵琶声停欲语迟。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "晚。", "cites": [{"t": "迟,晚也。", "b": "《广雅》"}, {"t": "汤降不迟。", "b": "《诗·商颂·长发》"}], "words": [{"w": "他来迟了;迟疾", "t": "太晚,耽搁太久。"}]}, {"meaning": "长久。", "cites": [{"t": "昭假迟迟。", "b": "《诗·商颂·长发》"}], "words": [{"w": "迟久", "t": "长久。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('907wx','局','1','jú','尸','7','','[{"pinyin": "jú", "defs": [{"meaning": "(会意。从口,从尺。“尺”示规矩法度。口易出错,故以尺相拘束。本义:局促)。"}, {"meaning": "同本义。", "cites": [{"t": "局,促也。", "b": "《说文》"}, {"t": "不敢不局。", "b": "《诗·小雅·正月》"}, {"t": "意局而辞野。", "b": "潘民《乘舆箴》"}], "words": [{"w": "局守", "t": "谨守"}, {"w": "局定", "t": "限制,固定"}, {"w": "局囿", "t": "局限,限制"}, {"w": "局滞", "t": "局限停滞"}, {"w": "局蹐", "t": "局限,局束"}, {"w": "局脊", "t": "拘泥,拘束"}, {"w": "局数", "t": "局束"}, {"w": "局趣", "t": "拘束。同局促"}, {"w": "局局蹐蹐", "t": "畏缩不安的样子"}, {"w": "局促乡里", "t": "碌碌无为地呆在乡里。"}]}, {"meaning": "距离近。", "cites": [{"t": "涂路虽局,官守有限。", "b": "曹丕《与吴质书》"}]}, {"meaning": "弯曲。", "cites": [{"t": "予发曲局。", "b": "《诗·小雅·采绿》"}, {"t": "床不须局脚。", "b": "殷芸《小说》"}], "words": [{"w": "局局", "t": "俯身而大笑 的样子"}, {"w": "局脚", "t": "装在器物底部的弯曲形高脚"}, {"w": "局背", "t": "驼背。"}]}, {"meaning": "催逼;逼迫。", "cites": [{"t": "遂以局杀湣公于蒙泽。", "b": "《史记》"}, {"t": "屠户被众人局不过,只得连斟两碗酒喝了,壮一壮胆。", "b": "《儒林外史》"}]}, {"meaning": "部分。", "cites": [{"t": "左右有局。", "b": "《礼记·曲礼》。注:“部分也。”"}, {"t": "局,部也。", "b": "《后汉书·袁绍传》注"}, {"t": "各司其局。", "b": "《礼记·曲礼》"}]}, {"meaning": "邻居。", "cites": [{"t": "漉我新熟酒,只鸡招近局。", "b": "晋·陶渊明《归园田居》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('908wx','改','1','gǎi','己','7','','[{"pinyin": "gǎi", "defs": [{"meaning": "(会意。甲骨文字形,左边是“己”,象一个跪着的小孩子;右边是“攴”(pū),象以手持杖或执鞭。表示教子改过归正之意。本义: 改变)。"}, {"meaning": "同本义。", "cites": [{"t": "改,更也。", "b": "《说文》"}, {"t": "敝予又改为兮。", "b": "《诗·郑风·缁文》"}, {"t": "盖改葬也。", "b": "《公羊传·庄公三年》"}, {"t": "回也不改其乐。", "b": "《论语·雍也》"}, {"t": "改取一个挟之。", "b": "《仪礼·乡射礼》。注:“更也。”"}, {"t": "改居则请退可也。", "b": "《仪礼·士相见礼》"}, {"t": "执政未改。", "b": "《国语·鲁语下》"}, {"t": "前图未改。", "b": "《楚辞·九章·怀沙》"}, {"t": "少小离家老大回,乡音无改鬓毛衰。", "b": "唐·贺知章《回乡偶书》"}, {"t": "盘庚不为怨者故改其度,度义而后动,是而不见可悔故也。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "改容加饰", "t": "改变神气而加以奖饰"}, {"w": "改适", "t": "改嫁"}, {"w": "改教", "t": "改任执教"}, {"w": "改律", "t": "改变法规"}, {"w": "改视", "t": "改变看法;另眼相看"}, {"w": "改节", "t": "改变节操。"}]}, {"meaning": "改正;纠正。", "cites": [{"t": "三人行必有我师焉,择其善者而从之,其不善者而改之。", "b": "《论语·述而》"}, {"t": "始知为人情所患,有自改意。", "b": "《世说新语·自新》"}], "words": [{"w": "改励", "t": "改过自勉"}, {"w": "改悟", "t": "醒悟改过"}, {"w": "改悛", "t": "改悔。"}]}, {"meaning": "重新;再。", "cites": [{"t": "缁衣之好兮,敝予又改造兮。", "b": "《诗·郑风 ·缁衣》"}], "words": [{"w": "改卜", "t": "重新占卜;另行选择"}, {"w": "改口沓舌", "t": "重新转动舌头,改变原来的说法"}, {"w": "改作", "t": "重制;另制"}, {"w": "改析", "t": "重新划分"}, {"w": "改撰", "t": "重新撰写。"}]}, {"meaning": "另行;改任。", "cites": [{"t": "后公改两广,太监泣别,赠大珠四枚。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "明年正月,召为南京右佥都御史,道改南吏部右侍郎。", "b": "《明史·海瑞传》"}], "words": [{"w": "改聚", "t": "另行增加民众"}, {"w": "改置", "t": "另行设置"}, {"w": "改授", "t": "另行授予官职"}, {"w": "改除", "t": "另行授官"}, {"w": "改取", "t": "另行采择。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('909wx','张','1','zhāng zhàng','弓','7','','[{"pinyin": "zhāng", "defs": [{"meaning": "(形声。从弓,长声。本义:把弦安在弓上)。"}, {"meaning": "同本义 。与“弛”相对。", "cites": [{"t": "张,施弓弦也。", "b": "《说文》"}, {"t": "一张一弛。", "b": "《礼记·杂记》"}, {"t": "鲁琴张字子开。", "b": "《左传·昭公二十年》"}, {"t": "良弓难张,然可以及高入深。", "b": "《墨子·亲士》"}, {"t": "天之道其犹张弓与?高者抑之,下者举之。", "b": "《老子》"}, {"t": "既张我弓,既挟我矢。", "b": "《诗·小雅·吉日》"}]}, {"meaning": "开弓;拉弓弦。", "cites": [{"t": "更张空弦。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "张弓设箭", "t": "拉弓射箭。比喻使用武力"}, {"w": "张弓", "t": "拉弓;弦拉紧的弓。"}]}, {"meaning": "张开。", "cites": [{"t": "是故质的张而弓矢至焉。", "b": "《荀子·劝学》"}, {"t": "琴瑟张而不均。", "b": "《荀子·礼论》"}, {"t": "左右欲刃相如,相如张目叱之。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "张口承之。", "b": "《后汉书·张衡传》"}], "words": [{"w": "张牙欠口", "t": "张开嘴巴"}, {"w": "张眼", "t": "睁大眼睛"}, {"w": "张牙", "t": "张口露牙"}, {"w": "张唇植髭", "t": "唇吻开合。形容滔滔不绝地论列是非的样子"}, {"w": "张袂成阴", "t": "张开袖子能遮掩天日。形容人多。"}]}, {"meaning": "张挂(展开挂起)。", "cites": [{"t": "罗帱张些。", "b": "《楚辞·招魂》"}, {"t": "张缇绛帷,女居其中。", "b": "《史记·滑稽列传》"}, {"t": "日张屈字。", "b": "明·高启《书博鸡者事》"}, {"t": "张黄盖拥纛。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "张旃", "t": "展开、张挂起赤色曲柄的大旗"}, {"w": "张卖", "t": "张挂出卖。"}]}, {"meaning": "展开。", "cites": [{"t": "张尾伸须。", "b": "《聊斋志异·促织》"}], "words": [{"w": "张翅膀;张网;张畤", "t": "延展耸立"}, {"w": "张开双臂;张动", "t": "伸展舞动"}, {"w": "张眉", "t": "舒展眉毛"}, {"w": "张眉努眼", "t": "指善于作态"}, {"w": "张眉努目", "t": "喻粗犷浅露。"}]}, {"meaning": "设网捕捉。", "cites": [{"t": "原来徱兔李吉,正在那山坡下张兔儿。", "b": "《水浒传》"}], "words": [{"w": "张捕", "t": "张网捕捉。"}]}, {"meaning": "张设(部署;设置)。", "cites": [{"t": "张,施也。", "b": "《广雅·释诂三》"}, {"t": "张乐设饮,郊迎三十里。", "b": "《战国策·秦策一》"}, {"t": "当日杀牛宰马,大张筵席。", "b": "《三国演义》"}, {"t": "张筵列鼎。", "b": "清·周容《芋老人传》"}], "words": [{"w": "张设", "t": "陈设"}, {"w": "张疑", "t": "设置疑兵"}, {"w": "张筵", "t": "设宴"}, {"w": "张所", "t": "布置朝见之所"}, {"w": "张事", "t": "张设帷幕之事。"}]}, {"meaning": "看;望。", "cites": [{"t": "我张着姐姐哩。", "b": "《西厢记》"}], "words": [{"w": "张亲", "t": "看望亲戚"}, {"w": "张着眼错", "t": "趁人不注意"}, {"w": "张个眼慢", "t": "趁人不注意"}, {"w": "张人眼错", "t": "趁人不注意"}, {"w": "张头望颈", "t": "伸长脖子张望"}, {"w": "东张西望;张看", "t": "张望观看。"}]}, {"meaning": "布满,充满。", "cites": [{"t": "火尽燎,烟焰张天。", "b": "《金史·乌春传》"}], "words": [{"w": "张天", "t": "布满天空。"}]}, {"meaning": "增强,扩大。", "cites": [{"t": "臣欲张公室也。", "b": "《左传·昭公十四年》"}]}, {"meaning": "又如:张吾军(壮大自己的声势)。"}, {"meaning": "夸张;夸大。", "cites": [{"t": "虚张异类,托有于无。", "b": "唐·皇甫谧《三都赋序》"}]}, {"meaning": "又如:虚张声势。"}, {"meaning": "主張。", "cites": [{"t": "那婆子聽得叫,失张失志,出去迎接來叫的官人。", "b": "《清平山堂話本》"}], "words": [{"w": "张智", "t": "主意;主张"}, {"w": "张主", "t": "主张;主意;做主张;拿主意。"}]}, {"meaning": "星名 。二十八宿之一,南方朱雀七宿的第五宿,有星六顆。"}, {"meaning": "汉代諸侯囯名 。在今河南省任縣西南。"}, {"meaning": "", "cites": [{"t": "张氏藏书。", "b": "清.袁枚《黄生借书説》"}]}, {"meaning": "一种或一类中的一件。", "cites": [{"t": "鸟杌千张。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "几张仿古的漂亮的柚木桌;三张报;一张桌子;一张弓", "t": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "zhàng", "defs": [{"meaning": "帐幔,帷幕。", "cites": [{"t": "居则设张容。", "b": "《荀子·正论》"}, {"t": "张饮三日。", "b": "《史记·高祖本纪》"}, {"t": "供张东都门外。", "b": "《汉书·疏广传》"}]}, {"meaning": "胀满。", "cites": [{"t": "将食,张,如厕。", "b": "《左传·成公十年》"}, {"t": "张脉偾兴。", "b": "《左传·僖公十五年》"}, {"t": "亭历愈张。", "b": "《淮南子·缪称》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('910wx','忌','1','jì','心','7','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从心,己声。本义:憎恨)。"}, {"meaning": "同本义。", "cites": [{"t": "忌,憎恶也。", "b": "《说文》"}, {"t": "而忌处者。", "b": "《国语·晋语》"}, {"t": "不克不忌。", "b": "《大戴礼记·卫将军文子》"}, {"t": "子将助天为虐,不忌其不祥乎?", "b": "《国语·越语》"}], "words": [{"w": "忌恶", "t": "憎恶坏人坏事"}, {"w": "忌愤", "t": "怨愤,嫉恨。"}]}, {"meaning": "嫉妒。", "cites": [{"t": "操虽称美,心甚忌之。", "b": "《三国演义》"}], "words": [{"w": "忌前", "t": "妒嫉贤才"}, {"w": "忌妇", "t": "妒妇,善妒的妻子"}, {"w": "忌克", "t": "忌妒他人才能而想超过他"}, {"w": "忌才", "t": "嫉妒他人的才华或才能。"}]}, {"meaning": "禁忌;忌讳。", "cites": [{"t": "公室卑则忌直言。", "b": "《韩非子·外储说左下》"}, {"t": "忌怒,则能害己。", "b": "《韩非子·说疑》"}], "words": [{"w": "忌三房", "t": "迷信者认为生病的人忌进新房、产房和灵房"}, {"w": "忌作", "t": "唐宋习俗谓春、秋社日停做针线"}, {"w": "忌针", "t": "阴历正月忌动针线"}, {"w": "忌惮儿", "t": "忌讳害怕。"}]}, {"meaning": "顾忌。", "cites": [{"t": "贪吏害民无所忌。", "b": "白居易《采诗官》"}], "words": [{"w": "忌畏", "t": "畏惧害怕"}, {"w": "忌惮遮拦", "t": "顾虑遮掩"}, {"w": "忌器", "t": "有所顾忌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('911wx','际','1','jì','阝','7','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从阜(fù),祭声。本义:两墙相合之缝)。"}, {"meaning": "同本义。", "cites": [{"t": "际,壁会也。", "b": "《说文》。段玉裁注:两墙相合之缝也。"}]}, {"meaning": "泛指合缝的地方;缝隙。", "cites": [{"t": "凿棺际而安之。", "b": "南朝梁·江淹《铜剑赞》"}, {"t": "覆盖周密无际。", "b": "《后汉书·张衡传》"}]}, {"meaning": "边缘。", "cites": [{"t": "东南大海际。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "横无际涯。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "川原无际。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "岩际;水际;无边无际;边际;天际;九天之际;一望无际;分际;漫无边际", "t": ""}]}, {"meaning": "时候;时机。", "cites": [{"t": "败军之际。", "b": "诸葛亮《出师表》"}, {"t": "去就之际。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "革灭之际。", "b": "宋·苏洵《权书·六国论》"}, {"t": "天宝之际。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "会议召开之际;兴利除害之际;受任于败军之际;实生此际", "t": ""}]}, {"meaning": "中间,彼此之间。", "cites": [{"t": "利害之际。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "国际;校际;省际;星际;脑际;胸际", "t": ""}]}, {"meaning": "旁边;近旁。", "cites": [{"t": "宿云鹏际落,残月蚌中开。", "b": "宋之问《早发始兴江口至虚氏村作》"}]}, {"meaning": "其时;适逢…的时候。", "cites": [{"t": "际夜转西壑,隔山望南斗。", "b": "綦母潜《春泛若耶溪》"}], "words": [{"w": "际此盛会", "t": ""}]}, {"meaning": "交会;会合。", "cites": [{"t": "无往不复,天地际也。", "b": "《易·泰》"}]}, {"meaning": "适逢;恰遇。", "cites": [{"t": "良辅超拔于际会。", "b": "《论衡·偶会》"}, {"t": "昔张士逊亦以旧学际遇,用太傅致仕。", "b": "《宋史·何执中传》"}, {"t": "豪杰相逢鱼得水,英雄际会弟投兄。", "b": "《水浒传》"}], "words": [{"w": "遭际;际遇", "t": "幸遇;适逢"}, {"w": "际会", "t": "遭遇;遇会;会合"}, {"w": "际会风云", "t": "喻好的际遇"}, {"w": "际逢", "t": "遇到。"}]}, {"meaning": "达到;连接。", "cites": [{"t": "高不可际,深不可测。", "b": "《淮南子·原道》"}]}, {"meaning": "靠近或沿着。", "cites": [{"t": "北山陡起,下与河际。", "b": "《徐霞客游记·游龙门记》"}], "words": [{"w": "际海;际水;际晓", "t": "犹黎明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('912wx','陆','1','liù lù','阝','7','','[{"pinyin": "liù", "defs": [{"meaning": "数目字“六”的大写。"}]}, {"pinyin": "lù", "defs": [{"meaning": "(会意。从阜(fù),表示与地形地势的高低上下有关,从坴(lù),土块很大。“坴”亦兼表字音。本义:陆地,高而平的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "陆,高平地。", "b": "《说文》"}, {"t": "鸿渐于陆。", "b": "《易·渐卦》"}, {"t": "陵阜陆墐。", "b": "《国语·齐语》"}, {"t": "陵衍平陆。", "b": "《穆天子传》三"}, {"t": "水陆草木。", "b": "宋·周敦颐《爱莲说》"}, {"t": "水陆俱下。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "水陆并进。", "b": ""}], "words": [{"w": "大陆", "t": "广大的陆地"}, {"w": "水陆", "t": "水面和陆地上"}, {"w": "陆毛", "t": "陆地之所产。指兽类"}, {"w": "陆田", "t": "旱田。对水田而言"}, {"w": "陆径", "t": "即陆路"}, {"w": "陆船", "t": "即旱船。船形的花车。"}]}, {"meaning": "路;道。", "cites": [{"t": "复陆重阁,转石成雷。", "b": "张衡《西京赋》"}]}, {"meaning": "陆路。", "cites": [{"t": "运盐之法,凡行百里,陆运斤四钱,船运近一钱。", "b": "沈括《梦溪笔谈·官政一》"}], "words": [{"w": "水陆兼程;水陆交通", "t": ""}]}, {"meaning": "西汉侯国名 ,在今山东省寿光县东。"}, {"meaning": "跳跃。", "cites": [{"t": "龁草饮水,翘足而陆,此马之真性也。", "b": "《庄子·马蹄》"}]}, {"meaning": "卸;摘。", "cites": [{"t": "一边就摘了帽子,陆了网子,脱了布衫子。", "b": "明·西周生《醒世姻缘传》"}]}, {"meaning": "掳掠。", "cites": [{"t": "会公孙瓒师旅南驰,陆掠北境。", "b": "《后汉书·袁绍传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('913wx','阿','1','ē ā ǎ à','阝','7','','[{"pinyin": "ē", "defs": [{"meaning": "(形声。从阜,可声。本义:大的山陵,大的土山)。"}, {"meaning": "同本义。", "cites": [{"t": "阿,大陵也。一曰曲阜也。", "b": "《说文》"}, {"t": "我陵我阿。", "b": "《诗·大雅·皇矣》"}, {"t": "有卷者阿。", "b": "《诗·大雅·卷阿》"}, {"t": "在彼中阿。", "b": "《诗·小雅·菁菁者莪》"}], "words": [{"w": "阿丘", "t": "一边偏高的土丘。"}]}, {"meaning": "泛指山。", "cites": [{"t": "流自眺夫衡阿兮。", "b": "张衡《思玄赋》。注:“山下也。”"}], "words": [{"w": "阿阜", "t": "山峰,峰峦"}, {"w": "崇阿", "t": "高大的山。"}]}, {"meaning": "山坡。"}, {"meaning": "细缯,古代一种轻细的丝织品。", "cites": [{"t": "衣阿锡,曳齐纨。", "b": "《淮南子·修务》"}, {"t": "被阿锡,揄纻缟。", "b": "《史记·司马相如传》"}, {"t": "曳阿锡。", "b": "《汉书·礼乐志》。注:“细缯也。”"}], "words": [{"w": "阿锡", "t": "细的丝布。阿指细缯,锡是细布。"}]}, {"meaning": "曲隅,角落。", "cites": [{"t": "四阿重屋。", "b": "《周礼·考工记》"}, {"t": "若有人兮山之阿。", "b": "《楚辞·山鬼》。注:“曲隅也。”"}, {"t": "周阿而生", "b": "班固《西都赋》。注:“庭之曲也。”"}, {"t": "汾之阿。", "b": "《汉书·礼乐志》。注:“水之曲隅。”"}]}, {"meaning": "水边。", "cites": [{"t": "丙午,天子饮于河水之阿。", "b": "《穆天子传》"}]}, {"meaning": "曲从;迎合。", "cites": [{"t": "弗谏而阿之。", "b": "《国语·周语》。注:“随也。”"}, {"t": "阿郑君之心。", "b": "《吕氏春秋·长见》"}, {"t": "行叩诚而不阿兮。", "b": "《楚辞·逢纷》。注:“曲也。”"}, {"t": "是察阿党。", "b": "《礼记·月令》。注:“谓治狱吏以私恩,曲桡为也。”"}], "words": [{"w": "阿奉", "t": "阿谀奉承"}, {"w": "阿世", "t": "迎合世俗"}, {"w": "阿邑", "t": "迎合奉承的样子"}, {"w": "阿意", "t": "曲意附和他人的心意。"}]}]}, {"pinyin": "ā", "defs": [{"meaning": "(汉语名词词头,盛行于魏晋以后)。"}, {"meaning": "加在亲属称呼前面有亲昵的意味。", "cites": [{"t": "阿姊闻妹来。", "b": "《乐府诗集·木兰诗》"}, {"t": "府吏得闻之,堂上启阿母。", "b": "《玉台新咏·古诗为焦仲卿妻作》。"}], "words": [{"w": "阿爷", "t": "又作“阿耶”。称父亲"}, {"w": "阿翁", "t": "称祖父;称父亲;妇女称丈夫之父"}, {"w": "阿嫂", "t": "对朋友之妻的称呼"}, {"w": "阿叔", "t": "对丈夫之弟的称呼"}, {"w": "阿家", "t": "又称“阿姑”。妇人称丈夫的母亲"}, {"w": "阿爹", "t": "称父亲;也尊称长者"}, {"w": "阿父", "t": "称父亲;也称伯伯、叔叔,或作伯叔自称"}, {"w": "阿伯", "t": "尊称年长的男子。"}]}, {"meaning": "加于某些人的姓、名、小名、排行前用作称呼,往往带有一定的感情色彩或尊卑关系。", "cites": [{"t": "阿女含泪答。", "b": "《玉台新咏·古诗为焦仲卿妻作》。"}], "words": [{"w": "阿咸", "t": "侄子。晋朝阮籍的侄儿阮咸有才,后来遂用来称侄子"}, {"w": "阿连", "t": "弟弟。南朝宋谢灵运的族弟惠连很有才,人们随谢灵运称之为阿连"}, {"w": "阿杜", "t": "原指周盘龙的小妾杜氏,后为妾的别称"}, {"w": "阿娇", "t": "汉武帝陈皇后的小名;泛指美丽的女子"}, {"w": "阿蒙", "t": "三国时吴国名将吕蒙"}, {"w": "阿瞒", "t": "三国曹操的小字。"}]}, {"meaning": "阿托(10-18)的简称。"}, {"meaning": "表示疑问、肯定、呼召、祈请等语气。", "cites": [{"t": "是阿!我想办一桩事情,总得先立个威。", "b": "《文明小史》"}, {"t": "好苦恼阿!好苦恼阿!我出去,我出去。", "b": "佚名《刘弘嫁婢》"}, {"t": "儿阿,不是我有心要耽误你。", "b": "《儒林外史》"}], "words": [{"w": "阿也", "t": "阿约,阿呀。哎哟。"}]}]}, {"pinyin": "ǎ", "defs": [{"meaning": "用于表示各种感情(如惊讶)。", "cites": [{"t": "阿,你怎的这样客气起来!", "b": "鲁迅《呐喊·故乡》"}]}]}, {"pinyin": "à", "defs": [{"meaning": "", "words": [{"w": "阿晓得(可晓得)?阿去(可去)?", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('914wx','陈','1','chén','阝','7','','[{"pinyin": "chén", "defs": [{"meaning": "(形声。从阜,从木,申声。本义:地名。古宛丘地,春秋时陈国国都,在今河南省淮阳县。引申为姓氏)。"}, {"meaning": "古国名 。在今河南省东部和安徽省北部一带。", "cites": [{"t": "陈,宛丘,舜后妫(guí)满之所封。", "b": "《说文》"}, {"t": "陈,颛顼之族也。", "b": "《左传·昭公八年》"}]}, {"meaning": "陈朝 。朝代名。南朝之一。公元557年陈霸先代梁称帝,国号陈。建都建康(今江苏南京),后被隋所灭。"}, {"meaning": "战阵;行列。", "cites": [{"t": "前未到匈奴陈二里所。", "b": "《史记·李将军列传》"}]}, {"meaning": "陈设,陈列。", "cites": [{"t": "陈,列也。", "b": "《广雅》"}, {"t": "陈,布也。", "b": "《玉篇》"}, {"t": "展器陈告备。", "b": "《周礼·肆师》"}, {"t": "陈力就列,不能者止。", "b": "《论语·季氏》"}, {"t": "陈鱼而观之。", "b": "《左传·隐公五年》"}, {"t": "山肴野蔌,杂然而前陈者,太守宴也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "信臣精卒陈利兵而谁何。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "陈献", "t": "陈设供奉"}, {"w": "陈宝", "t": "陈列宝物。"}]}, {"meaning": "述说。", "cites": [{"t": "吾非尧舜之道,不敢以陈于王前。", "b": "《孟子·公孙丑下》"}, {"t": "跪敷衽以陈辞兮。", "b": "屈原《离骚》"}, {"t": "今日良宴会,欢乐难具陈。", "b": "《古诗十九首》"}, {"t": "衡因上疏陈事。", "b": "《后汉书·张衡传》"}, {"t": "常惠请其守者与俱,得夜见汉使,具自陈道。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "详陈", "t": "详细述说"}, {"w": "陈言", "t": "陈述。"}]}, {"meaning": "陈旧。", "cites": [{"t": "年谷复熟而陈积有余。", "b": "《荀子·富国》"}, {"t": "当其取于心而注于手也,惟陈言之务去。", "b": "唐·韩愈《答李翊书》"}], "words": [{"w": "陈醋;陈迹;推陈出新,新陈代谢", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('915wx','阻','1','zǔ','阝','7','','[{"pinyin": "zǔ", "defs": [{"meaning": "(形声。从阜(jù)声,且(jǔ)声。“阜”是土山,与高下险阻有关。本义:险要的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "阻,险也。", "b": "《说文》"}, {"t": "德行恒简以知阻。", "b": "《易·系辞》"}, {"t": "黎民阻饥。", "b": "《书·舜典》"}, {"t": "司险掌九州之图,以周知川泽之阻。", "b": "《周礼·司险》"}, {"t": "左据函谷、二崤之阻,表以太华、终南之山。", "b": "汉·班固《西都赋》"}, {"t": "罙入其阻。", "b": "《诗·商颂·殷武》"}], "words": [{"w": "阻隘", "t": "险要之地"}, {"w": "阻阨", "t": "据守险要。"}]}, {"meaning": "妨碍物;障隔。", "cites": [{"t": "保其岩阻。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又如;险阻(险要阻塞之地);阻障(障碍);阻寻(排除险阻寻访);阻积(险阻众多)。"}, {"meaning": "地形崎岖多阻隔,道路难行。", "cites": [{"t": "溯洄从之,道阻且长。", "b": "《诗·秦风·蒹葭》"}, {"t": "不知山林险阻、沮泽之形者,不能行军。", "b": "《孙子·军争》"}], "words": [{"w": "阻修", "t": "阻隔而长远"}, {"w": "阻长", "t": "道路艰险而遥远"}, {"w": "阻深", "t": "险阻幽深。"}]}, {"meaning": "沮丧。也作“沮”。", "cites": [{"t": "我之怀矣,自诒伊阻。", "b": "《诗·邶风·雄雉》"}, {"t": "其人惭阻,即日去苏。", "b": "《清稗类钞》"}], "words": [{"w": "意阻", "t": "意志消沉沮丧"}, {"w": "阻丧", "t": "沮丧失色。"}]}, {"meaning": "阻止;阻隔;阻拦。", "cites": [{"t": "夫仆俱阻。", "b": "《徐霞客游记·游黄山记》"}, {"t": "阻风不行。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "幸亡阻也。", "b": "明·宗臣《报刘一丈书》"}, {"t": "阻人走报。(阻止人家来报信。)", "b": "清·袁枚《祭妹文》"}, {"t": "西后阻挠。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "阻掯", "t": "阻挡刁难"}, {"w": "阻拗", "t": "阻拦;阻挡"}, {"w": "阻睽", "t": "阻隔分离"}, {"w": "阻乏", "t": "阻止和减少"}, {"w": "阻抑", "t": "阻止抑制"}, {"w": "阻滞", "t": "阻碍滞留。"}]}, {"meaning": "隔绝;断绝。", "cites": [{"t": "竄伏村墟,迁延岁月,音容久阻,书问莫传。", "b": "《剪灯新话》"}], "words": [{"w": "阻旷", "t": "隔绝。"}]}, {"meaning": "感到疑惑不解。", "cites": [{"t": "是服也,狂夫阻之。", "b": "《左传·闵公二年》"}]}, {"meaning": "凭借。", "cites": [{"t": "夫州吁阻兵而安忍。", "b": "《左传·隐公四年》"}], "words": [{"w": "阻山带河", "t": "靠山环河"}, {"w": "阻山", "t": "凭借高山的险阻"}, {"w": "阻众", "t": "凭借人众力大。"}]}, {"meaning": "离别。", "cites": [{"t": "常恐亲朋阻,独行知虑非。", "b": "唐·孟郊《与韩愈李翱张籍话别》"}]}, {"meaning": "推却,拒绝。", "cites": [{"t": "既阻我德,贾用不售。", "b": "《诗·邶风·谷风》"}], "words": [{"w": "阻拒", "t": "拒绝;推却。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('916wx','附','1','fù','阝','7','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从阜,付声。从“阜”(fù),表示与地形地势的高低上下有关。(bù)本义:小土丘。《说文》:“附娄,小土山也。”)。"}, {"meaning": "沾着,附着。", "cites": [{"t": "如涂涂附。", "b": "《诗·小雅·角弓》"}, {"t": "是故涂不附。", "b": "《考工记·轮人》"}, {"t": "丈人附耳谓先生曰:“有匕首否?”", "b": "马中锡《中山狼传》"}], "words": [{"w": "附缠", "t": "附着,纠缠住"}, {"w": "附离", "t": "附着。"}]}, {"meaning": "依傍;依附。", "cites": [{"t": "附于诸侯,曰附庸。", "b": "《礼记·王制》"}, {"t": "胜所以自附为婚姻者,以公子之高义,为能急人之困。", "b": "《史记·魏公子列传》"}, {"t": "齐人勿附于秦。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "附势;附籍天潢", "t": "依附皇室"}, {"w": "附郭", "t": "近城的地方;郊外"}, {"w": "附纳", "t": "依附交结"}, {"w": "附顺", "t": "依附顺从"}, {"w": "附权", "t": "依附权贵。"}]}, {"meaning": "归附。", "cites": [{"t": "荆州之民附操者逼兵势耳。", "b": "《资治通鉴》"}, {"t": "怀敌附远,何招而不至?", "b": "《汉书·食货志》引汉·贾谊《论积贮疏》"}], "words": [{"w": "附众", "t": "使众人归附"}, {"w": "附款", "t": "归附款服"}, {"w": "附化", "t": "归化"}, {"w": "附就", "t": "俯就,屈己从人"}, {"w": "附悦", "t": "顺从悦服。"}]}, {"meaning": "佩带。", "cites": [{"t": "西门豹急,佩韦以自缓;董安于缓,带弦以自促。急之与缓,俱失中和,然而韦弦附身,成为完具之人。", "b": "《论衡》"}]}, {"meaning": "靠近。", "cites": [{"t": "燕不用而耳不附。", "b": "《韩非子·用人》"}, {"t": "其附于刑者,归于土。", "b": "《周礼·大司徒》"}], "words": [{"w": "附火", "t": "靠近火取暖。"}]}, {"meaning": "增益。", "cites": [{"t": "刻死而附生谓之墨,刻生而附死谓之惑。", "b": "《荀子·礼论》。注:“附,增益也。”"}], "words": [{"w": "附益", "t": "增益,增加"}, {"w": "附说", "t": "增加解说。"}]}, {"meaning": "捎带;寄。", "cites": [{"t": "一男附书至,二男新战死。", "b": "唐·杜甫《石壕吏》"}]}, {"meaning": "(fǔ)。体恤,抚慰。", "cites": [{"t": "昭公之弟商人以桓公死争立而不得,阴交贤士,附爱百姓。", "b": "《史记·齐世家》"}]}, {"meaning": "树木外表的粗皮。"}, {"meaning": "中草药“附子”的简称。"}, {"meaning": "脏腑。", "cites": [{"t": "臣幸得托肺附。", "b": "《汉书·楚元王传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('917wx','坠','1','zhuì','土','7','','[{"pinyin": "zhuì", "defs": [{"meaning": "(形声。从土,队声。坠落到地上,故从土。本义:落下,掉下)。"}, {"meaning": "同本义。", "cites": [{"t": "隊,从高陨也。", "b": "《说文》。俗字作墜。"}, {"t": "墜,落也。", "b": "《尔雅》"}, {"t": "墜,堕也。", "b": "《广雅》"}, {"t": "死而坠也。", "b": "《公羊传·文公三年》"}, {"t": "朝饮木籣之坠露兮。", "b": "《楚辞·离骚》"}, {"t": "矢交坠兮士争先。", "b": "《楚辞·九歌·国殇》"}, {"t": "自舟中坠于水。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "又。", "cites": [{"t": "剑之所从坠。", "b": ""}, {"t": "抗坠疾徐。(坠,声音低沉。)", "b": "清·侯方域《壮悔堂文集》"}, {"t": "杞国有人,忧天地崩坠。", "b": "《列子·天瑞》"}, {"t": "坠入深渊难以复出。", "b": "《汉书·枚乘传》"}], "words": [{"w": "坠睫", "t": "落泪"}, {"w": "坠楼", "t": "从楼上掉落下地"}, {"w": "坠泪", "t": "坠睫;掉泪"}, {"w": "坠红", "t": "落花。"}]}, {"meaning": "丧失;败坏。", "cites": [{"t": "今惟殷坠厥命。", "b": "《书·酒诰》"}, {"t": "自先王莫坠其国,当君而亡之,君之过也。", "b": "《国语》"}], "words": [{"w": "坠亡", "t": "丧失"}, {"w": "坠失", "t": "失去"}, {"w": "坠言", "t": "失言"}, {"w": "坠履", "t": "不轻易遗弃旧物或故物失而复得之典。"}]}, {"meaning": "毁坏。", "cites": [{"t": "昔者夫子闵王道之缺,伤斯文之坠。", "b": "《文心雕龙·史传》"}], "words": [{"w": "坠典", "t": "已废亡的典章制度"}, {"w": "坠湮", "t": "湮没亡失"}, {"w": "坠绪", "t": "坠遗。行将断绝的皇统。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('918wx','妓','1','jì','女','7','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从女,支声。本义:古代歌舞的女子)。"}, {"meaning": "同本义。", "cites": [{"t": "妓,女乐也。", "b": "《广韵》"}]}, {"meaning": "字本作伎。", "cites": [{"t": "军装宫妓扫蛾浅,摇摇锦旗夹城暖。", "b": "李贺《三月》"}], "words": [{"w": "妓人", "t": "妓妇。歌舞女艺人"}, {"w": "妓航", "t": "女妓乘坐的船"}, {"w": "妓堂", "t": "第宅中女妓歌舞处"}, {"w": "妓婢师", "t": "教女妓演习歌舞的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('919wx','妙','1','miào','女','7','','[{"pinyin": "miào", "defs": [{"meaning": "(会意兼形声。从女,从少,少亦声。美妙少女。本义:美,好)。"}, {"meaning": "同本义。", "cites": [{"t": "尽所历妙。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "天镜之句为妙;妙巧", "t": "美妙奇巧"}, {"w": "妙香", "t": "特好的香气"}, {"w": "妙丽", "t": "容貌美好"}, {"w": "妙观", "t": "美妙的观察"}, {"w": "妙引", "t": "佳美的文辞"}, {"w": "妙色", "t": "庄严或美丽的色彩。"}]}, {"meaning": "神妙。", "cites": [{"t": "其当是其妙处不传。", "b": "《世说新语·文学》"}], "words": [{"w": "妙理", "t": "神妙的道理"}, {"w": "妙略", "t": "夺谋,妙计"}, {"w": "妙契", "t": "神妙的契合"}, {"w": "妙用", "t": "神妙的作用"}, {"w": "妙笔", "t": "神妙之笔。指书画或文字的高手。"}]}, {"meaning": "精妙;精微。", "cites": [{"t": "常无欲以观其妙。", "b": "《老子》。王注:“妙者,微之极也。”"}, {"t": "所知者妙矣。", "b": "《吕氏春秋·审分》"}, {"t": "虽妙必效情。", "b": "《史记·律书》。注:“妙,谓微妙之性也。”"}, {"t": "妙尽琁机之正。(琁机:玉饰的测天仪器。正:则,译为原理)。", "b": "《后汉书·张衡传》"}], "words": [{"w": "妙旨", "t": "精微幽深的旨意"}, {"w": "妙言要道", "t": "精到的言论,中肯的道理"}, {"w": "妙绪", "t": "精妙的思绪,思想"}, {"w": "妙思", "t": "精妙的构思"}, {"w": "妙演", "t": "精妙的阐述"}, {"w": "妙说", "t": "意旨精微的言论。"}]}, {"meaning": "巧妙,高明。", "cites": [{"t": "众妙毕备。", "b": "《虞初新志·秋声诗自序》"}, {"t": "皆服其妙。", "b": "《后汉书·张衡传》"}], "words": [{"w": "以为妙绝;妙着", "t": "高明的棋着;好办法"}, {"w": "妙品", "t": "精巧美妙的物品"}, {"w": "妙远", "t": "高妙深远"}, {"w": "妙迹", "t": "指佳妙的书法作品"}, {"w": "妙旨", "t": "好的意见,计谋。"}]}, {"meaning": "细微,幼小,年少。", "cites": [{"t": "所知者妙矣。", "b": "《吕氏春秋·审分》"}, {"t": "终军以妙年使越,欲得长缨占其王。", "b": "曹植《求自试表》"}], "words": [{"w": "妙人", "t": "年少风流的男子"}, {"w": "妙年", "t": "指少壮之年"}, {"w": "妙身", "t": "指幼年之身。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('920wx','妖','1','yāo','女','7','','[{"pinyin": "yāo", "defs": [{"meaning": "(形声。从女,夭声。)。"}, {"meaning": "同本义。", "cites": [{"t": "妖,妍也。", "b": "《三苍》"}, {"t": "妖夫曳衔。", "b": "《楚辞·天问》"}, {"t": "妖冶闲都。", "b": "《汉书·司马相如传》。注:“妖冶,美好也。”"}, {"t": "妖姬静女。", "b": "清·侯方域《壮梅堂文集》"}], "words": [{"w": "妖妍", "t": "艳丽"}, {"w": "妖姿", "t": "艳丽的姿容"}, {"w": "妖异", "t": "美艳奇异"}, {"w": "妖丽", "t": "艳丽"}, {"w": "妖靡", "t": "艳丽华美"}, {"w": "妖蛊", "t": "艳丽"}, {"w": "妖姬", "t": "美女"}, {"w": "妖玩", "t": "美女。"}]}, {"meaning": "妖媚。淫邪,不正。", "cites": [{"t": "梁冀妻孙寿,色美而善为妖态,作愁眉。", "b": "《后汉书》"}], "words": [{"w": "妖红", "t": "妇女勾引男子并与其私通"}, {"w": "妖妙", "t": "妖娆美好"}, {"w": "妖惑", "t": "惑人的媚态"}, {"w": "妖韶", "t": "妖绕美好"}, {"w": "妖娇", "t": "娇美"}, {"w": "妖服", "t": "妖冶的服装。"}]}, {"meaning": "古称一切反常怪异的事物或现象。", "cites": [{"t": "人无衅焉,妖不自作。", "b": "《左传·庄公十四年》"}, {"t": "心和而出,且为声为名,为妖为孽。", "b": "《庄子·人间世》"}], "words": [{"w": "妖变", "t": "指反常、怪异的现象和事物。"}]}, {"meaning": "迷信传说中称害人的怪物。", "cites": [{"t": "菩萨又怕那妖无礼,却把一个箍儿,丢在那妖头上。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('921wx','姊','1','zǐ','女','7','','[{"pinyin": "zǐ", "defs": [{"meaning": "(形声。本义:姐姐)。"}, {"meaning": "同本义。", "cites": [{"t": "姊,女兄也。", "b": "《说文》"}, {"t": "男子谓女子先生为姊。", "b": "《尔雅》"}, {"t": "遂及伯姊。", "b": "《诗·邶风·泉水》"}, {"t": "阿姊闻妹来。", "b": "《乐府诗集·木兰诗》"}]}, {"meaning": "又。", "cites": [{"t": "小弟闻姊来。", "b": ""}], "words": [{"w": "姊丈", "t": "姐姐的丈夫"}, {"w": "姊夫", "t": "姐姐的丈夫"}, {"w": "姊弟", "t": "姐姐和妹妹或姐姐和弟弟"}, {"w": "姊儿", "t": "对妓女的称呼。"}]}, {"meaning": "指母亲。", "cites": [{"t": "如今之所谓者,若中州名汉,关右称羌,易臣以奴,呼母云姊。", "b": "刘知几《史通·杂说中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('922wx','妨','1','fáng','女','7','','[{"pinyin": "fáng", "defs": [{"meaning": "(形声。从女,方声。本义:损害;有害于)。"}, {"meaning": "同本义。", "cites": [{"t": "妨,害也。", "b": "《说文》"}, {"t": "将妨于国家。", "b": "《国语·越语》"}, {"t": "敬而无妨些。", "b": "《楚辞·招魂》"}, {"t": "令人行妨。", "b": "《老子》。注:“伤也。”"}, {"t": "不以自妨也。", "b": "《荀子·解蔽》"}, {"t": "贼父之子,妨兄之弟,与此同召。", "b": "《论衡·偶会》"}], "words": [{"w": "妨要", "t": "妨害要务"}, {"w": "妨紊", "t": "伤害扰乱。"}]}, {"meaning": "阻碍。", "cites": [{"t": "无发令而干时,以妨神农之事。", "b": "《吕氏春秋·季夏》"}], "words": [{"w": "妨贤", "t": "阻碍贤者登进。"}]}, {"meaning": "妨碍。", "cites": [{"t": "不以小功妨大务。", "b": "《韩非子·难二》"}], "words": [{"w": "不妨;何妨;妨蔽", "t": "妨碍。"}]}, {"meaning": "中止。", "cites": [{"t": "丁亥,敕翰林直学士陈大任妨本职专修《辽史》。", "b": "《金史》"}]}, {"meaning": "迷信者以为因命相、时辰、方位等凶像而人造成的灾厄,即所谓犯尅。", "cites": [{"t": "自从你昨日下了书呈,将俺员外急心疼一夜妨杀了。", "b": "元·马致远《荐福碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('923wx','妒','1','dù','女','7','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从女,户声。本义:妇女忌妒丈夫。也指忌妒别的女子的姿色)。", "words": [{"w": "妒鳞", "t": "妒妇发威,有如龙的逆鳞不可冒犯"}, {"w": "妒女祠", "t": "唐代祠名。相传若有人盛服经过时,则风雷大作"}, {"w": "妒色", "t": "嫉忌美色。多指妻妒婢妾"}, {"w": "妒妇", "t": "好妒忌的妇人。"}]}, {"meaning": "泛指忌妒别人。", "cites": [{"t": "妆成每被秋娘妒。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "妒害", "t": "妒忌陷害"}, {"w": "妒纷", "t": "因互相妒忌而引起的争执、纠纷"}, {"w": "妒痴", "t": "过度的妒忌而引发的痴病"}, {"w": "妒刻", "t": "嫉妒刻薄"}, {"w": "妒富愧贫", "t": "忌妒别人富裕,羞愧自己贫穷"}, {"w": "妒敌", "t": "相忌恨的敌手。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('924wx','努','1','nǔ','力','7','','[{"pinyin": "nǔ", "defs": [{"meaning": "(形声。从力,奴声。本义:勉力,出力)。"}, {"meaning": "同本义。", "cites": [{"t": "少壮不努力,老大徒伤悲。", "b": "《乐府诗集·长歌行》"}], "words": [{"w": "努筋拔力", "t": "竭尽全力;费了很大的力。"}]}, {"meaning": "向外突出。", "cites": [{"t": "却才见押司努嘴过来。", "b": "《水浒传》"}], "words": [{"w": "努唇胀嘴", "t": "撅着嘴,表示不高兴的样子"}, {"w": "努咀", "t": "撅嘴;以嘴示意"}, {"w": "努目", "t": "努眼。把眼睛张大,使眼球突出"}, {"w": "努嘴胖唇", "t": "鼓嘴凸唇。形容不高兴"}, {"w": "努臂", "t": "努膊。伸臂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('925wx','忍','1','rěn','心','7','','[{"pinyin": "rěn", "defs": [{"meaning": "(形声。从心, 刃声。本义: 忍耐、 容忍)。"}, {"meaning": "同本义。", "cites": [{"t": "忍,能也。", "b": "《说文》"}, {"t": "忍,耐也。", "b": "《广雅》"}, {"t": "是可忍也。", "b": "《论语·八脩》。皇疏:“忍,犹容耐也。”"}, {"t": "强力忍垢,吾不知其他也。", "b": "《庄子·让王》"}, {"t": "吾子忍之。", "b": "《左传·成公二年》"}, {"t": "小不忍,则乱大谋。", "b": "《论语·卫灵公》"}, {"t": "忍所私以行大义。", "b": "《吕氏春秋·去私》"}, {"t": "故遂忍悲为汝言之。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "忍事", "t": "以忍耐态度面对各种事情"}, {"w": "忍容", "t": "容忍"}, {"w": "忍顺", "t": "忍耐顺受;忍耐顺从"}, {"w": "忍从", "t": "忍受顺从"}, {"w": "忍羞", "t": "忍受羞辱"}, {"w": "忍气", "t": "忍受别人的欺侮"}, {"w": "忍垢", "t": "忍受污垢"}, {"w": "忍丑", "t": "忍受耻辱"}, {"w": "忍耻", "t": "忍受耻辱"}, {"w": "忍痛", "t": "忍受痛苦。"}]}, {"meaning": "抑制; 克制。", "cites": [{"t": "志忍私,然后能公。", "b": "《荀子·儒效》"}, {"t": "所以动心忍性,曾益其所不能。", "b": "《孟子》"}], "words": [{"w": "忍性", "t": "克制性情"}, {"w": "忍口", "t": "抑制食欲"}, {"w": "忍情", "t": "抑制感情"}, {"w": "忍志", "t": "犹屈意"}, {"w": "忍恶", "t": "忍住脾气"}, {"w": "忍泪", "t": "忍住眼泪, 不使流出来"}, {"w": " 忍笑", "t": "忍住不笑。"}]}, {"meaning": "愿意; 舍得。", "cites": [{"t": "不忍为之下。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "忍屑", "t": "愿意关心。"}]}, {"meaning": "认识,识别。", "cites": [{"t": "夫国之疑,二三子莫忍老臣。", "b": "《管子·大匡》"}]}, {"meaning": "坚韧。"}, {"meaning": "残忍;忍心;狠心。", "cites": [{"t": "维其忍之。", "b": "《诗·小雅·小弁》"}, {"t": "君王为人不忍。", "b": "《史记·项羽本纪》"}], "words": [{"w": "忍苛", "t": "残忍苛刻"}, {"w": "忍人", "t": "残忍的人"}, {"w": "忍忮", "t": "刻毒忌恨"}, {"w": "忍毒", "t": "残忍狠毒"}, {"w": "忍虐", "t": "残忍暴虐"}, {"w": "忍悖", "t": "残忍狂悖"}, {"w": "忍害", "t": "杀害"}, {"w": "忍酷", "t": "残忍暴虐"}, {"w": "忍鸷", "t": "残忍凶狠"}, {"w": "忍暴", "t": "残忍暴虐。"}]}, {"meaning": "怎;岂。", "cites": [{"t": "干惟画肉不画骨,忍使骅骝气凋丧!", "b": "杜甫《丹青引赠曹将军霸》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('926wx','劲','1','jìn jìng','力','7','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从力,坙声。①(jìng)本义:强劲有力。②力气)。"}]}, {"pinyin": "jìng", "defs": [{"meaning": "(形声。从力,巠声。本义:强劲有力)。"}, {"meaning": "同本义。", "cites": [{"t": "劲,彊也。", "b": "《说文》"}, {"t": "劲,强也。", "b": "《字林》"}, {"t": "廉直劲正庄诚之音作。", "b": "《礼记·乐记》"}, {"t": "夫梁兵劲而权重。", "b": "《战国策·宋策》"}, {"t": "孔子之劲。", "b": "《列子·说符》"}, {"t": "弓先调而后求劲。", "b": "《淮南子·说林》"}, {"t": "良将劲弩守要塞。", "b": "汉·贾谊《新书·过秦论上》"}, {"t": "天下之强弓劲弩,皆自韩出。", "b": "《战国策》"}, {"t": "风力虽尚劲。", "b": "明·袁宏道《满井游记》"}, {"t": "此劲敌也。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "刚劲;劲弩", "t": "坚强有力的弓弩"}, {"w": "劲酒", "t": "烈酒"}, {"w": "劲节", "t": "强劲的枝节;坚贞不移的操守"}, {"w": "劲武", "t": "刚健勇武"}, {"w": "劲猛", "t": "强悍勇猛"}, {"w": "劲兵", "t": "战斗力很强的部队"}, {"w": "劲卒", "t": "精锐的士兵"}, {"w": "劲勇", "t": "精壮的勇士"}, {"w": "劲锐", "t": "精锐的士卒或军队。"}]}, {"meaning": "猛烈;风势强劲。", "cites": [{"t": "风劲角弓鸣。", "b": "唐·王维《观猎》"}, {"t": "筋力越劲。", "b": "《荀子·非相》。注:“勇也。”"}], "words": [{"w": "劲秋", "t": "秋气肃杀,能凋零草木,所以称秋天为劲秋"}, {"w": "劲气", "t": "寒冷之气"}, {"w": "劲厉", "t": "风势猛烈而寒冷。"}]}, {"meaning": "坚固;坚硬。", "cites": [{"t": "材虽劲。", "b": "《吕氏春秋·顺说》"}, {"t": "木益枯则劲。", "b": "《吕氏春秋·别类》"}, {"t": "真心凌晚桂,劲节掩寒松。", "b": "骆宾王《浮槎》"}], "words": [{"w": "劲节", "t": "竹木丫枝出生的坚固之处"}, {"w": "劲利", "t": "坚固锐利"}, {"w": "劲质", "t": "坚硬的质地;坚强的质性。"}]}, {"meaning": "强壮,对疾病或恶劣天气有抵抗力。", "cites": [{"t": "其气急疾坚劲。", "b": "《素问·腹中论》。注:“刚也。”"}], "words": [{"w": "劲草;劲松", "t": ""}]}, {"meaning": "坚强;刚强。", "cites": [{"t": "某度之,必其兵未集而有是言。使之集,则使者健而言必劲矣。", "b": "辛弃疾《九议》"}], "words": [{"w": "劲直", "t": "刚毅正直"}, {"w": "劲切", "t": "刚强峻急"}, {"w": "劲果", "t": "刚毅果敢"}, {"w": "劲廉", "t": "刚正廉洁"}, {"w": "劲躁", "t": "刚强而急躁。"}]}, {"meaning": "精锐部队。", "cites": [{"t": "摧坚陷劲,所向有功。", "b": "明·屈大均《东广州县起义传》"}]}, {"meaning": "加强。", "cites": [{"t": "得其众不足以劲兵。", "b": "《史记》"}, {"t": "不如与魏以劲之。", "b": "《战国策·秦策一》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('927wx','矣','1','yǐ','矢','7','','[{"pinyin": "yǐ", "defs": [{"meaning": "(形声。小篆字形,上面是“以”字,下面是“矢”。从矢,以声。“以”也可以理解为象矢飞逝的声音,是完成的语气。本义:语气词。是“了”)。"}, {"meaning": "表示完成时态。", "cites": [{"t": "骨尽矣,而两狼之并驱如故。", "b": "《聊斋志异·狼三则》"}]}, {"meaning": "表示坚决、肯定。", "cites": [{"t": "德薄而位尊,知小而谋大,力小而任重,鲜不及矣!", "b": "《易·系辞下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('928wx','鸡','1','jī','鸟','7','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从鸟,奚声。本义:家禽名。雄鸡可以报晓) 鸟纲雉科家禽,品种很多,喙短锐,有冠与肉髯,翅膀短,尤指普通家鸡(Gallus gallus)。", "cites": [{"t": "雞,知时兽也。从隹,奚声。籀文从鳥。", "b": "《说文》"}, {"t": "雞者,小兽,主司时起居人。", "b": "《汉书·五行志》"}, {"t": "食菽与雞。", "b": "《礼记·月令》"}, {"t": "雞曰翰音。", "b": "《礼记·曲礼》"}, {"t": "巽为雞。", "b": "《易·说卦传》"}, {"t": "工商执雞。", "b": "《周礼·大宗伯》"}, {"t": "鸡犬相闻。", "b": "晋·陶渊明《桃花源记》"}, {"t": "故人具鸡黍。", "b": "唐·孟浩然《过故人庄》"}, {"t": "鸡栖于厅。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "鸡男", "t": "雄鸡"}, {"w": "鸡坊", "t": "养鸡场"}, {"w": "鸡肤", "t": "鸡皮。比喻皮肤粗糙而多皱纹"}, {"w": "鸡鹜", "t": "鸡和鸭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('929wx','纬','1','wěi','纟','7','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从糸(mì),韦声。本义:织横纱)。"}, {"meaning": "同本义。", "cites": [{"t": "纬,织横丝也。", "b": "《说文》"}, {"t": "恃纬萧而食者。", "b": "《庄子·列御寇》。释文:“织也。”"}], "words": [{"w": "纬萧", "t": "用蒿草编织窗帘子。"}]}, {"meaning": "东西向的道路或土地。与南北向的“经”相对。", "cites": [{"t": "凡地东西为纬。", "b": "《大戴礼记·易本命》"}, {"t": "正督经纬。", "b": "《周髀算经》"}], "words": [{"w": "纬途", "t": "古代都城内的东西大道。"}]}, {"meaning": "行星的古称。", "cites": [{"t": "五纬相汁。", "b": "《西京赋》。注:“五星也。”"}], "words": [{"w": "纬象", "t": "星象"}, {"w": "纬星", "t": "行星的总称。"}]}, {"meaning": "琴徽,系琴弦的绳子。", "cites": [{"t": "挟人筝而弹纬。", "b": "《楚辞·愍命》。王逸注:“纬,张弦也”。"}]}, {"meaning": "地理学上所假想为地球上与赤道平行的南北分度线。在赤道以北的叫北纬,以南的叫南纬。", "cites": [{"t": "国中九经九纬。", "b": "《周礼·考工记·匠人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('930wx','驱','1','qū','马','7','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从马,区声。本义:奔驰;疾行)。"}, {"meaning": "同本义。", "cites": [{"t": "驱,马驰也。", "b": "《说文》"}, {"t": "驱,奔也。", "b": "《广雅·释室》"}, {"t": "王用三驱。", "b": "《易·比》"}, {"t": "驱马悠悠。", "b": "《诗·鄘风·载驰》"}, {"t": "负而前驱。", "b": "宋·欧阳修《新五代史·伶官传》"}, {"t": "并驱如故。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "驱弛;驰驱", "t": "骑马快跑"}, {"w": "长驱", "t": "迅速地向很远的目的地走"}, {"w": "驱侵", "t": "驱车侵袭"}, {"w": "驱劳", "t": "奔走辛劳"}, {"w": "驱突", "t": "驱驰奔跑"}, {"w": "驱骇", "t": "奔走惊骇。"}]}, {"meaning": "赶马。", "cites": [{"t": "并驱从两肩兮。", "b": "《诗·齐风·还》"}, {"t": "并驱从两牡兮。", "b": ""}, {"t": "驱而之薛。", "b": "《战国策·齐策四》"}, {"t": "冯谖先驱。", "b": ""}, {"t": "被驱不异犬与鸡。", "b": "唐·杜甫《兵车行》"}, {"t": "闲驱泾水之涘。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "驱驱", "t": "策马快奔"}, {"w": "驱马", "t": "策马奔驰"}, {"w": "驱良", "t": "驱策良马"}, {"w": "驱驽", "t": "驱策劣马"}, {"w": "驱肥", "t": "驱策肥马"}, {"w": "驱鑣", "t": "驱策奔驰"}, {"w": "驱放", "t": "驱策奔驰。"}]}, {"meaning": "驱逐;赶走。", "cites": [{"t": "我自不驱卿。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "驱出斩之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "驱治", "t": "驱赶整治"}, {"w": "驱虐", "t": "驱除虐疾"}, {"w": "驱摈", "t": "驱逐摈弃"}, {"w": "驱羊", "t": "驱赶羊群"}, {"w": "驱乌", "t": "驱赶乌鸦"}, {"w": "驱捶", "t": "驱逐捶打。"}]}, {"meaning": "迫使。", "cites": [{"t": "驱而之善。", "b": "《孟子·梁惠王上》"}, {"t": "饥来驱我去,不知竟何之。", "b": "陶渊明《乞食》"}, {"t": "驱予并往。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "驱番", "t": "推倒"}, {"w": "驱役", "t": "驱使。差遣;役使"}, {"w": "驱制", "t": "差遣管辖"}, {"w": "驱丁", "t": "“金”、“元”时对奴仆的称呼。"}]}, {"meaning": "追随。", "cites": [{"t": "双美并进,骈驰翼驱。", "b": "《文选·嵇康·琴赋》"}]}, {"meaning": "行进。", "cites": [{"t": "妇乘以几,姆加景,乃驱。", "b": "《仪礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('931wx','纯','1','chún','纟','7','','[{"pinyin": "chún", "defs": [{"meaning": "(形声。从糸(mì),屯声。从“糸”,表示与线丝有关。本义:蚕丝)。"}, {"meaning": "同本义。", "cites": [{"t": "纯,丝也。", "b": "《说文》"}, {"t": "纯衣。", "b": "《仪礼·士冠礼》"}, {"t": "被我纯缋。", "b": "《法言·孝至》"}], "words": [{"w": "纯衣", "t": "古时士的祭服,以丝为之。"}]}, {"meaning": "同一颜色的丝织品。", "cites": [{"t": "一色成体谓之醇,白黑杂合谓之驳。", "b": "《汉书·梅福传》。王先谦补注:官本“醇”作“纯”,是"}]}, {"meaning": "纯正,纯粹。", "cites": [{"t": "侍中侍郎郭攸之、费瑋、董允等,此皆忠臣?志虑忠纯。", "b": "诸葛亮《出师表》"}, {"t": "不设色之画,其感人也,纯以形式及笔势。", "b": "蔡元培《图画》"}], "words": [{"w": "纯固", "t": "品行纯粹坚定"}, {"w": "纯素", "t": "纯粹而不杂;纯朴"}, {"w": "纯德", "t": "纯粹的德行"}, {"w": "纯儒", "t": "品行纯粹的儒者。"}]}, {"meaning": "美;善。", "cites": [{"t": "纯,文也。纯,好也。", "b": "《方言》十三"}, {"t": "贵纯之道也。", "b": "《礼记·郊特牲》"}], "words": [{"w": "纯臣", "t": "忠心耿耿事奉君主的大臣"}, {"w": "纯吏", "t": "忠纯爱民的官吏"}, {"w": "纯渥", "t": "纯朴笃厚。"}]}, {"meaning": "大。", "cites": [{"t": "文王之德之纯。", "b": "《诗·周颂·维天之命》"}], "words": [{"w": "纯嘏", "t": "大福"}, {"w": "纯国", "t": "大国"}, {"w": "纯德", "t": "大德。"}]}, {"meaning": "专一。", "cites": [{"t": "帅旧德,而守终纯固。", "b": "《国语·周语》"}]}, {"meaning": "质朴。", "cites": [{"t": "冠衣不纯素。", "b": "《礼记·曲礼》"}], "words": [{"w": "纯臣", "t": "忠纯笃实之臣"}, {"w": "纯悫", "t": "纯朴诚实。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('932wx','纱','1','shā','纟','7','','[{"pinyin": "shā", "defs": [{"meaning": "(会意。从糸(mì),从少。本义:轻细的绢)。"}, {"meaning": "轻细的丝麻织物,古时多以蚕丝为之。古亦作“沙”。", "cites": [{"t": "白纱入缁,不染自黑。", "b": "汉·王充《论衡》"}, {"t": "绸缎一百三十卷,纱绫一百八十卷。", "b": "《红楼梦》"}], "words": [{"w": "纱元", "t": "纸制的纱缎和元宝;祭品"}, {"w": "纱绢", "t": "细薄丝织品的通称;纱手帕"}, {"w": "纱罗", "t": "轻软细薄的丝织品的通称"}, {"w": "纱笼中人", "t": "喻命中富贵,可官至宰相。"}]}, {"meaning": "今泛指用棉麻、化学纤维或其他材料制成的经纬线稀疏的织品。", "cites": [{"t": "温温土炉火,耿耿纱笼烛。", "b": "唐·白居易《宿东亭晓兴》"}], "words": [{"w": "纱帐", "t": "纱制帐幕"}, {"w": "纱屉子", "t": "纱窗。旧时的窗户分两层,里面一层多用纱糊,透明,通气"}, {"w": "纱帷", "t": "即纱帐"}, {"w": "纱幌", "t": "纱制窗帘"}, {"w": "乔其纱;泡泡纱;纱窗", "t": "蒙纱的窗户"}, {"w": "纱罩", "t": "蒙纱的灯罩;蒙纱的防蝇罩;煤气灯上的主要附件。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('933wx','纲','1','gāng','纟','7','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,冈声。本义:提网的总绳)。"}, {"meaning": "同本义。", "cites": [{"t": "纲,维紘绳也。", "b": "《说文》"}, {"t": "若网在纲,有条而不紊。", "b": "《书·盘庚》"}, {"t": "纲纪四方。", "b": "《诗·大雅·棫朴》。笺:“张之为纲,理之为纪。”"}, {"t": "四方之纲。", "b": "《诗·大雅·卷阿》"}, {"t": "举其宏纲。", "b": "《书·序》"}, {"t": "纪纲之仆。", "b": "《左传·僖公二十四年》"}, {"t": "善张网者引其纲,不一一摄万目而后得。则是劳而难,引其纲则鱼已囊矣。", "b": "《韩非记·外储说右下》"}], "words": [{"w": "纲挈目张", "t": "犹纲举目张"}, {"w": "纲提领挈", "t": "提起网纲,挈住裘领。比喻抓住要领。"}]}, {"meaning": "事物的关键部分,事理的要领。", "cites": [{"t": "为政贵当举纲。", "b": "《北史·源贺传》"}, {"t": "然洽闻之士,宜撮纲要,揽华而食实,弃邪而采正。", "b": "《文心雕龙·诸子》"}, {"t": "熔则纲领昭畅。", "b": "《文心雕龙·熔裁》"}, {"t": "法令为维纲。", "b": "《管子·禁藏》"}], "words": [{"w": "纲辖", "t": "朝廷中枢总要之职。唐、宋多指尚书省执政官"}, {"w": "大纲", "t": "内容要点"}, {"w": "一部两卷本的世界史纲", "t": ""}]}, {"meaning": "系束。", "cites": [{"t": "纲恶马。", "b": "《周礼·夏官》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('934wx','纳','1','nà','纟','7','','[{"pinyin": "nà", "defs": [{"meaning": "(形声。从糸(mì),内声。本义:丝被水浸湿)。"}, {"meaning": "同本义。", "cites": [{"t": "纳,丝湿纳纳也。", "b": "《说文》"}, {"t": "衣纳纳而掩露。", "b": "刘向《九叹·逢纷》"}], "words": [{"w": "纳纳", "t": "潮湿的样子。"}]}, {"meaning": "收藏;收入。", "cites": [{"t": "察纳雅言。", "b": "诸葛亮《出师表》"}], "words": [{"w": "采纳;容纳;藏垢纳污", "t": "包藏容纳污秽之物。比喻包容坏人坏事。"}]}, {"meaning": "“纳”假借为“接纳”;接受。", "cites": [{"t": "几以不纳死。", "b": "宋·文天祥《指南录·后序》"}, {"t": "遂开门纳众。", "b": "《资治通鉴·唐纪》"}, {"t": "诬守纳己赇。", "b": "明·高启《书博鸡者事》"}, {"t": "纳钱案上。", "b": "《聊斋志异·促织》"}], "words": [{"w": "纳质", "t": "接受质证;接受质询"}, {"w": "纳采", "t": "古婚嫁六礼中的第一件事。即行聘;其他如纳吉,纳聘,纳征,纳币皆为六礼之中"}, {"w": "纳贽", "t": "初次见面所馈赠的礼物"}, {"w": "纳受", "t": "接受;收受"}, {"w": "纳下", "t": "采纳下面的意见。"}]}, {"meaning": "缴纳,贡献。", "cites": [{"t": "九江纳锡大龟。", "b": "《书·禹贡》"}, {"t": "岁终则会其出入,而纳其余。", "b": "《周礼·地官·泉府》"}, {"t": "小臣纳卿大夫。", "b": "《仪礼·燕礼》"}, {"t": "纳于太庙。", "b": "《公羊传·桓公二年》"}, {"t": "十月纳禾稼。", "b": "《诗·豳风·七月》"}, {"t": "命弟子纳射器。", "b": "《仪礼·乡射礼》"}, {"t": "纳之库。", "b": "诸葛亮《出师表》"}], "words": [{"w": "纳监", "t": "捐纳财物取得监生资格"}, {"w": "纳锡", "t": "进贡"}, {"w": "纳粟", "t": "也作内粟,入粟;捐纳粟米或财货给官,以谋求某种利益"}, {"w": "纳官", "t": "向官府缴纳谷物"}, {"w": "纳质", "t": "送纳人质。"}]}, {"meaning": "使进入。", "cites": [{"t": "三纳之而未克。", "b": "马中锡《中山狼传》"}]}, {"meaning": "取;娶。", "cites": [{"t": "杀三卻而尸诸朝,纳其室以分妇人。", "b": "《国语·晋语》"}], "words": [{"w": "纳币", "t": "订婚时男方给女方的财物"}, {"w": "纳宠", "t": "娶妾"}, {"w": "纳赘", "t": "招上门女婿"}, {"w": "纳妇", "t": "娶妇。"}]}, {"meaning": "结交。", "cites": [{"t": "魏了翁闻之,更纳交焉。", "b": "《宋史·张忠恕传》"}], "words": [{"w": "纳交", "t": "结交"}, {"w": "纳宗", "t": "结交宗室朋友。"}]}, {"meaning": "用同“捺”。"}, {"meaning": "密针缝纫。", "cites": [{"t": "那婆子又拿了一件破衣,补补纳纳。", "b": "《西游记》"}], "words": [{"w": "纳衣", "t": "衲衣。取人弃去之布帛缝衲之僧衣。也称“百衲衣”"}, {"w": "纳鞋", "t": "用线缝制鞋底。"}]}, {"meaning": "扣压。", "cites": [{"t": "枢密童贯同太师蔡京,太尉高俅、杨戬,商议纳下表章不奏。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('935wx','驳','1','bó','马','7','','[{"pinyin": "bó", "defs": [{"meaning": "(会意。从马,从爻。甲骨文字形,右边是“爻”(yáo),表示马的毛色混杂,左边是“马”。本义:马毛色不纯)。"}, {"meaning": "同本义。", "cites": [{"t": "驳,马色不纯也。", "b": "《说文》"}, {"t": "为驳马。", "b": "《易·说卦》"}, {"t": "皇驳其马。", "b": "《诗·豳风·东山》"}, {"t": "红白杂毛曰驳。", "b": "《文选·赭·白马赋》注"}, {"t": "绛皓驳色,而皆若偻。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "驳杂;庞杂。", "cites": [{"t": "纯而王,驳而伯。", "b": "《荀子·赋》"}, {"t": "惠施多方,其书五车,其道舛驳。", "b": "《庄子·天下》"}, {"t": "法小弛则是非驳。", "b": "刘禹锡《天论上》"}], "words": [{"w": "驳错", "t": "交杂混乱"}, {"w": "驳辞", "t": "杂乱的言辞。"}]}, {"meaning": "驳斥,反驳。", "cites": [{"t": "不以己之是驳人之非。", "b": "《晏子春秋》"}], "words": [{"w": "批驳", "t": "书面否决下级的意见或要求;批评驳斥"}, {"w": "驳审", "t": "否决原判"}, {"w": "驳正", "t": "纠正错误。"}]}, {"meaning": "传说中能食虎豹的猛兽。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('936wx','纵','1','zòng','纟','7','','[{"pinyin": "zòng", "defs": [{"meaning": "(形声。从糸(mì),从声。本义:松缓)。"}, {"meaning": "同本义。", "cites": [{"t": "纵,缓也。", "b": "《说文》"}, {"t": "蓬发施纵,无形仪,不治家业。", "b": "《南齐书》"}], "words": [{"w": "纵缓", "t": "松懈"}, {"w": "纵弛", "t": "松懈;放松。"}]}, {"meaning": "南北称纵,东西称横。古作“从衡”。", "cites": [{"t": "不别横之与纵。", "b": "《楚辞·沈江》"}, {"t": "纵有千古,横有八荒。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "纵贯南北的京九铁路", "t": ""}]}, {"meaning": "广泛。", "cites": [{"t": "谈道之余,纵言及文辞,…,非凡子所及。", "b": "陆游《重修天封寺记》"}], "words": [{"w": "纵意", "t": "任意。"}]}, {"meaning": "发;放。", "cites": [{"t": "纵,一曰舍也。", "b": "《说文》"}, {"t": "李种坐故纵死罪。", "b": "《汉书·昭帝纪》。注:“谓容放之。”"}, {"t": "夫民气纵则底。", "b": "《国语·楚语》。注:“放也。”"}, {"t": "抑纵送忌。", "b": "《诗·郑风·大叔于田》"}, {"t": "纵言至于理。", "b": "《礼记·仲尼燕居》"}, {"t": "有如乘风船,一纵不可缆。", "b": "唐·韩愈《秋怀诗》之六"}, {"t": "顺风纵火。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "纵目", "t": "放眼远望"}, {"w": "纵出", "t": "放出"}, {"w": "纵兵", "t": "发兵;出兵"}, {"w": "纵笔", "t": "放手书写。"}]}, {"meaning": "释放;放走。", "cites": [{"t": "奉不可失,敌不可纵。", "b": "《左传·僖公三十三年》"}, {"t": "七擒七纵。", "b": "《李靖》"}, {"t": "纵虎归山也。", "b": "《三国演义》"}], "words": [{"w": "纵囚", "t": "释放囚犯"}, {"w": "纵出", "t": "枉法减轻刑罚或非法释放囚犯;任意放出"}, {"w": "纵遣", "t": "释放遣发"}, {"w": "纵舍", "t": "释放;宽放。"}]}, {"meaning": "放纵;随心所欲,不受约束,不加检点。", "cites": [{"t": "纵欲而不忍。", "b": "《离骚》。按,任情肆意之谓也。"}, {"t": "我实纵欲,而不能自克也。", "b": "《左传·昭公十年》"}, {"t": "纵之顺之。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "若纵", "t": "如果放纵听任"}, {"w": "纵放", "t": "言行放纵,不自检点;奔放自如,具有豪迈雄健的气势。"}]}, {"meaning": "指合纵。战国时期苏秦游说六国诸侯,要他们联合起来西向抗秦,秦在西边,六国土地南北相连,故曰“合纵”。", "cites": [{"t": "必得定纵。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "(纵,定纵。)又。", "cites": [{"t": "纵之利害。", "b": ""}, {"t": "谨奉社稷而以纵。", "b": ""}, {"t": "日出而言纵。", "b": ""}, {"t": "纵定乎?", "b": ""}, {"t": "歃血而定纵。", "b": ""}, {"t": "定纵于殿上。", "b": ""}]}, {"meaning": "纵然,即使。", "cites": [{"t": "公子纵轻胜。", "b": "《史记·魏公子列传》"}, {"t": "纵有健妇把锄犁。", "b": "唐·杜甫《兵车行》"}, {"t": "纵有千种风情,更与何人说!", "b": "宋·柳永《雨霖铃》"}, {"t": "纵豆蔻词工。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "纵有", "t": "即使有"}, {"w": "纵大", "t": "纵然;即使"}, {"w": "纵得", "t": "纵令,即使"}, {"w": "纵饶", "t": "纵令,即使。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('937wx','纷','1','fēn','纟','7','','[{"pinyin": "fēn", "defs": [{"meaning": "(形声。从糸(mì),分声。从“糸”,表示与线丝等有关。本义:马尾韬,扎束马尾的丝麻织物)。"}, {"meaning": "同本义。", "cites": [{"t": "纷,马尾韬也。", "b": "《说文》。段玉裁注:“韬,剑衣也。引申凡为衣之称。《释名》曰:‘纷,放也,防其放弛以拘之也。’”"}]}, {"meaning": "旗上的飘带。", "cites": [{"t": "青云为纷,虹霓为缳。", "b": "汉·扬雄《羽猎赋》"}], "words": [{"w": "佩纷", "t": "佩饰丝带。"}]}, {"meaning": "花边。", "cites": [{"t": "次席纷纯,左右玉几。", "b": "张衡《东京赋》"}]}, {"meaning": "祸乱;灾难。", "cites": [{"t": "唯天轨之不辟兮,何纯絜而离纷!", "b": "《汉书》"}]}, {"meaning": "争执;纠纷。", "cites": [{"t": "谈言微中,亦可以解纷。", "b": "《史记·滑稽列传》"}], "words": [{"w": "纷纠", "t": "纠纷;纷扰;祸乱"}, {"w": "纷哓", "t": "争辩不休。"}]}, {"meaning": "盛多,各种各样。", "cites": [{"t": "且矫诏纷出,钩党之捕遍于天下。", "b": "明·张溥《五人墓碑记》"}, {"t": "于是众枪齐发,敌人纷堕如落叶。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "艚又如:纷委(盛多);纷若(盛多的样子);纷营(众多,杂乱);纷郁(盛多的样子)。"}, {"meaning": "杂乱。", "cites": [{"t": "霰雪纷其无垠兮,云霏霏其承宇。", "b": "《楚辞·屈原·涉江》"}, {"t": "班其相纷些。", "b": "《楚辞·招魂》"}, {"t": "涫涫纷纷。", "b": "《荀子·解蔽》"}, {"t": "狱之放纷。", "b": "《左传·昭公十六年》"}, {"t": "顾自民国肇造,变乱纷乘。", "b": "孙文《 序》"}], "words": [{"w": "纷腾", "t": "杂乱喧腾"}, {"w": "纷嚣", "t": "纷乱喧嚣"}, {"w": "纷错", "t": "杂乱的样子"}, {"w": "纷纶", "t": "乱而多。忙乱"}, {"w": "纷罗", "t": "排列混乱无序的样子。或指众多并列。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('938wx','纸','1','zhǐ','纟','7','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从糸(mì),氏声。纸的原料本是破旧的丝绵,故从糸。本义:纸张)。"}, {"meaning": "同本义。", "cites": [{"t": "纸,絮也,一曰苫也。", "b": "《说文》。按,潎絮一苫也。造纸昉于漂絮以苫荐而成之,后汉蔡伦造。意用树肤麻头及敝巾魚网为之。今亦用竹质木皮,其细者,有致密竹帘荐焉。"}, {"t": "[帝]令逵自选《公羊》严、颜诸生高才者二十人,教以《左传》,与简纸经传各一通。", "b": "《后汉书·贾逵传》"}], "words": [{"w": "纸撚儿", "t": "用易燃纸搓成的点火纸卷儿"}, {"w": "纸标儿", "t": "纸做的出售标志"}, {"w": "纸筋", "t": "用于做纸浆的废纸"}, {"w": "纸阄", "t": "带有标记的纸片,用于拈韵"}, {"w": "纸衣", "t": "以纸制成的衣服。"}]}, {"meaning": "冥钱,旧俗为祭奠鬼神而焚化的纸钱。", "cites": [{"t": "弄得我们少香没纸,血食全无。", "b": "《西游记》"}], "words": [{"w": "纸劄", "t": "纸糊的冥器"}, {"w": "纸锞", "t": "纸钱"}, {"w": "纸扎", "t": "纸糊的冥器"}, {"w": "纸元宝", "t": "有金色或银色纸糊制的元宝形冥钱。迷信用品。"}]}, {"meaning": "文契,字据。", "cites": [{"t": "把小的驴和米同稍袋都叫人短了家去,还不发出纸来。", "b": "《儒林外史》"}]}, {"meaning": "书信、文件的张;件。", "cites": [{"t": "邺下谚云:“博士买驴,书卷三纸,未有驴字。”", "b": "《颜氏家训》"}], "words": [{"w": "一纸空文;纸半张", "t": "即半张纸。比喻微不足道"}, {"w": "太宗真迹六百纸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('939wx','纹','1','wén','纟','7','','[{"pinyin": "wén", "defs": [{"meaning": "(形声。从糸(mì),文声。本义:丝织品上的花纹)。"}, {"meaning": "同本义。", "cites": [{"t": "纹,绫纹也。", "b": "《玉篇》"}, {"t": "纹,绫也。", "b": "《广韵》"}, {"t": "作断纹焉。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "纹杇", "t": "丝织品的皱纹,常用来形容水波。"}]}, {"meaning": "皮肤上的纹理。", "cites": [{"t": "主人,近三十岁的容貌,眉宇间已露艰辛的纹路。", "b": "瞿秋白《赤都心史》"}]}, {"meaning": "以彩色线条刻画在物体表面。", "cites": [{"t": "陶器、陶片发见最多,西阴村遗址发见的多至数万片,制造技术和纹饰,一般说是很美的。", "b": "范文澜《中国通史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('940wx','纺','1','fǎng','纟','7','','[{"pinyin": "fǎng", "defs": [{"meaning": "(形声。从糸(mì),方声。本义:将丝麻纤维制成纱或线)。"}, {"meaning": "同本义。", "cites": [{"t": "纺,网丝也。", "b": "《说文》"}, {"t": "纺焉以度而去之。", "b": "《左传·昭公十九年》"}, {"t": "村南有夫妇守贫者,织纺井臼,佐读勤苦。", "b": "清·周容《芋老人传》"}], "words": [{"w": "纺绩", "t": "纺纱与绩麻"}, {"w": "纺手", "t": "指纺纱、纺线的人"}, {"w": "纺缉", "t": "纺丝和缉麻。"}]}, {"meaning": "捆绑,悬挂;束缚。", "cites": [{"t": "献子执而纺于庭之槐。", "b": "《国语·晋语》。韦昭注:“纺,悬也。”"}]}, {"meaning": "绸属;素纱 。古指素色纱绢。", "cites": [{"t": "宾裼,迎大夫,贿用束纺。", "b": "《仪礼·聘礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('941wx','驴','1','lǘ','马','7','','[{"pinyin": "lǘ", "defs": [{"meaning": "(形声。从马,盧声。本义:驴子。家畜名)。"}, {"meaning": "同本义。", "cites": [{"t": "驴,似马,长耳。", "b": "《说文》。段注:“按,‘驴、骡、駃騠’太史公皆谓为匈奴奇畜,本中国所不用,故字皆不见经传,盖秦人造之耳。”"}, {"t": "腾驾罢牛,骖蹇驴兮。", "b": "贾谊《吊屈原文》"}, {"t": "骐骥不能与罢驴为驷。", "b": "《史记·日者列传》"}, {"t": "黔无驴。", "b": "唐·柳宗元《三戒》"}]}, {"meaning": "又。", "cites": [{"t": "主将适蝼而麓不闻。", "b": "《国语·晋语》"}, {"t": "驴不胜怒。", "b": ""}], "words": [{"w": "驴头", "t": "驴马头。骂人的话"}, {"w": "驴王", "t": "指凶残恶狠的人"}, {"w": "驴年", "t": "古代以生肖纪年,十二肖中没有驴。比喻没有期限"}, {"w": "驴券", "t": "比喻为文或说话不得要领"}, {"w": "驴颓", "t": "骂男子的粗话。指公驴的生殖器"}, {"w": "驴辇", "t": "用驴驾引的车子"}, {"w": "驴生戟角", "t": "比喻不可能发生的事"}, {"w": "驴鸣犬吠", "t": "比喻文章的鄙俗"}, {"w": "驴前马后", "t": "贱称仆役、随从。饥笑人自甘落后。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('942wx','纽','1','niǔ','纟','7','','[{"pinyin": "niǔ", "defs": [{"meaning": "(形声。从糸(mì),丑声。从糸,与丝线有关。本义:指可解的结)。"}, {"meaning": "同本义。", "cites": [{"t": "纽,系也。一曰结而可解。", "b": "《说文》。按,结而不可解曰缔。"}, {"t": "并纽约。", "b": "《礼记·玉藻》。疏:“带之交结之处。”"}, {"t": "冠帻簪簧结发纽。", "b": "《急就篇》"}], "words": [{"w": "纽约", "t": "用以扣合衣服的纽结。"}]}, {"meaning": "比喻事物的根本,关键。", "cites": [{"t": "禹舜之所纽也。", "b": "《庄子·人间世》"}], "words": [{"w": "电纽;枢纽", "t": ""}]}, {"meaning": "纽绊。器物上用以提携或系绳带的部件。", "cites": [{"t": "延纽。", "b": "《周礼·弁师》。注:“小鼻在武上,笄可贯也。”"}], "words": [{"w": "秤纽;印纽", "t": ""}]}, {"meaning": "汉语音韵学名词,指辅音或声母。如“声母”又称“声纽”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('943wx','奉','1','fèng','大','8','','[{"pinyin": "fèng", "defs": [{"meaning": "(会意。小篆字形,从手,从収(gǒng,双手),最上面像一串玉或树盖子。是用手捧物的意思。本义:两手恭敬地捧着"}, {"meaning": "同本义。", "cites": [{"t": "奉,承也。", "b": "《说文》"}, {"t": "黔敖左奉食,右执饮。", "b": "《礼记·檀弓下》"}, {"t": "常山王奉头鼠窜。", "b": "《汉书·蒯通传》"}, {"t": "项伯即入见沛公,沛公奉卮酒为寿,约为婚姻。", "b": "《史记·项羽本纪》"}, {"t": "臣愿奉璧往使。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "荆轲奉樊於期头函,而秦武阳奉地图匣,以次进。", "b": "《战国策·燕策》"}], "words": [{"w": "奉书;奉地图;奉手", "t": "捧握长者之手。"}]}, {"meaning": "恭敬地接受。", "cites": [{"t": "受任于败军之际,奉命于危难之间。", "b": "诸葛亮《出师表》"}, {"t": "近者奉辞伐罪,旌麾南指,刘琮束手。", "b": "《资治通鉴》"}], "words": [{"w": "奉教", "t": "接受教导"}, {"w": "奉委", "t": "接受委任"}, {"w": "奉制", "t": "接受天子的命令"}, {"w": "奉玄", "t": "信奉道教。"}]}, {"meaning": "进献,下对上送东西。", "cites": [{"t": "请奉盆缻秦王,以相娱乐。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "玉斗一双,再拜奉大将军足下。", "b": "《史记·项羽本纪》"}], "words": [{"w": "奉上新书一册;奉纳", "t": "交纳"}, {"w": "奉呈", "t": "奉献,献上"}, {"w": "双手奉上;奉贽", "t": "进献见面礼品。"}]}, {"meaning": "送;给予,赐予。", "cites": [{"t": "太子乃使人以千金奉庄子,庄子弗受。", "b": "《庄子·说剑》"}, {"t": "奉之弥繁,侵之愈急。", "b": "宋·苏洵《六国论》"}, {"t": "奉违蹇叔,而以贪勤民,天奉我也。", "b": "《左传·僖公三十三年》"}, {"t": "今国家所以奉西北之虏者,岁以百万计。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "为…效劳,侍候。", "cites": [{"t": "向为身死而不受,今为妻妾之奉而为之。", "b": "《孟子》"}], "words": [{"w": "奉执箕帚", "t": "给你料理家务;许配于你"}, {"w": "奉从", "t": "奉陪侍侯"}, {"w": "奉巾栉", "t": "伺候洗沐梳发"}, {"w": "奉问", "t": "侍奉问候"}, {"w": "奉候", "t": "恭候。"}]}, {"meaning": "奉承。", "cites": [{"t": "虽则他神通广大,却好奉承。", "b": "《西游记》"}], "words": [{"w": "阳奉阴违;奉附", "t": "奉承依附"}, {"w": "奉喜", "t": "奉承而讨人喜欢"}, {"w": "奉顺", "t": "奉承顺应"}, {"w": "奉循", "t": "奉承遵循。"}]}, {"meaning": "贯彻,执行。", "cites": [{"t": "谨奉法令。", "b": "《史记》"}], "words": [{"w": "奉天", "t": "奉行天命"}, {"w": "奉元", "t": "遵奉天道"}, {"w": "奉修", "t": "奉行"}, {"w": "奉宪", "t": "奉行法令"}, {"w": "奉法", "t": "奉行或遵守法令。"}]}, {"meaning": "尊奉。", "cites": [{"t": "子奉君命以会大事,而背宋盟,无乃不可乎?", "b": "《左传·昭公十一年》"}], "words": [{"w": "奉辞", "t": "奉命"}, {"w": "奉天承运", "t": "尊奉上天的命令,承受兴盛的时运"}, {"w": "奉遵", "t": "遵守;遵从。"}]}, {"meaning": "供奉,供养。", "cites": [{"t": "人之道则不然,损不足以奉有余。", "b": "《老子》"}, {"t": "敲剥天下之骨髓,离散天下之子女,以奉我一人之淫乐。", "b": "清·黄宗羲《原君》"}, {"t": "张文节为相,自奉养如为河阳掌书记时。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "持,拿。", "cites": [{"t": "奉甲执兵。", "b": "《墨子·非攻中》"}]}, {"meaning": "辅助,拥戴。", "cites": [{"t": "郑伯使许大夫百里奉许叔以居许东偏。", "b": "《左传·隐公十一年》"}]}, {"meaning": "俸禄。", "cites": [{"t": "位尊而无功,奉厚而无劳,而挟重器多也。", "b": "《战国策·秦策》"}, {"t": "吏皆送奉钱三。", "b": "《史记·萧相国世家》"}, {"t": "列侯幸得赐餐钱奉邑。", "b": "《汉书·高后纪》"}, {"t": "其令公奉舍人赏赐皆倍故。", "b": "《汉书·王莽传上》"}, {"t": "今小吏皆勤事而奉禄簿。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "无劳之奉;奉粟;奉稍;奉饷;奉禄", "t": "俸禄。"}]}, {"meaning": "待遇,事奉。", "cites": [{"t": "向为身死而不受,今为妻妾之奉为之。", "b": "《孟子》"}]}, {"meaning": "奉天的省称 。1929年改名沈阳市。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('944wx','玩','1','wán','王','8','','[{"pinyin": "wán", "defs": [{"meaning": "(形声。从玉,元声。本义:以手玩弄)。"}, {"meaning": "玩耍;玩弄。", "cites": [{"t": "玩,弄也。", "b": "《说文》"}, {"t": "将还玩吾国于股掌之上。", "b": "《国语·吴语》"}, {"t": "民狎而玩之,则多死焉,故宽难。", "b": "《左传·昭公二十年》"}, {"t": "岂惟玩景物,亦欲摅心素。", "b": "《白氏长庆集·读谢灵运诗》"}, {"t": "玩古知今,特可宝爱。", "b": "《颜氏家训·杂艺》"}, {"t": "玩天地于掌握之中。", "b": "《淮南子·精神》"}, {"t": "摩玩不已。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "玩服", "t": "玩赏佩用之物"}, {"w": "玩爱", "t": "玩赏珍爱"}, {"w": "玩饰", "t": "供玩赏的佩饰。"}]}, {"meaning": "玩赏;欣赏。", "cites": [{"t": "展玩不可晓。", "b": "《聊斋志异·促织》"}], "words": [{"w": "玩咏", "t": "玩赏吟咏"}, {"w": "玩幽", "t": "玩赏幽景"}, {"w": "玩好", "t": "玩赏与爱好"}, {"w": "玩月", "t": "赏月。"}]}, {"meaning": "戏弄。", "cites": [{"t": "玩人丧德,玩物丧志。", "b": "《书·旅獒》"}], "words": [{"w": "为人所玩;玩巧", "t": "玩弄巧诈手段"}, {"w": "玩奸", "t": "玩弄奸诈的手段"}, {"w": "玩谑", "t": "戏弄;开玩笑"}, {"w": "玩是玩,笑是笑", "t": "俗语。开玩笑是开玩笑,该正经时要正经。"}]}, {"meaning": "研讨;反复体会。", "cites": [{"t": "顾玩所见。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "而玩其辞。", "b": "《易·系辞上》"}, {"t": "玩其文也久矣。", "b": "《列子·黄帝》"}], "words": [{"w": "玩索", "t": "体味探索"}, {"w": "玩习", "t": "玩味研习"}, {"w": "玩占", "t": "占卜;研究卦象、卜辞"}, {"w": "玩思", "t": "研究,探索"}, {"w": "玩耽", "t": "潜心玩味"}, {"w": "玩咏", "t": "玩味讽咏"}, {"w": "玩意", "t": "玩味,体味。"}]}, {"meaning": "轻慢;轻视。", "cites": [{"t": "究属玩视, 着记大过三次。", "b": "《官场现形记》"}], "words": [{"w": "玩令", "t": "玩命。玩忽命令"}, {"w": "玩延", "t": "玩忽延误"}, {"w": "玩弛", "t": "玩忽松懈"}, {"w": "玩法", "t": "玩忽法令"}, {"w": "玩泄", "t": "玩忽,轻慢"}, {"w": "玩俗", "t": "玩忽法令的风气"}, {"w": "玩怠", "t": "玩忽,懈怠。"}]}, {"meaning": "供玩赏之物。", "cites": [{"t": "若夫白珩,先王之玩也。", "b": "《国语·楚语下》"}], "words": [{"w": "古玩;珍玩;玩好", "t": "玩物,供人玩赏的东西。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('945wx','环','1','huán','王','8','','[{"pinyin": "huán", "defs": [{"meaning": "(形声。从玉,瞏huán声。本义:圆形而中间有孔的玉器)。"}, {"meaning": "同本义。", "cites": [{"t": "环,璧也。", "b": "《说文》"}, {"t": "肉好若一谓之不。", "b": "《尔雅·释器》。李注:“其孔及边肉大小适等。”"}, {"t": "行步则有环珮之声。", "b": "《礼记·经解》"}, {"t": "孔子佩象环五寸。", "b": "《礼记·玉藻》"}, {"t": "闻水声,如鸣佩环。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "腰白玉之环。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "环佩", "t": "古人衣带上所系的佩玉"}, {"w": "环玦", "t": "玉环和玉玦"}, {"w": "环琨", "t": "环与琨,并为玉佩"}, {"w": "环塡", "t": "两种玉制的耳饰。环,耳环。塡,冠冕上的塞耳之玉。"}]}, {"meaning": "泛指圆圈形的物品。", "cites": [{"t": "布巾环幅。", "b": "《仪礼·士丧礼》"}, {"t": "瓜祭上环。", "b": "《礼记·玉藻》。注:“上环,头忖也。”"}], "words": [{"w": "环中", "t": "圆环的中心;又比喻空虚而无是无非的境界"}, {"w": "环利通索", "t": "连环铁索。"}]}, {"meaning": "数学中,具有加法和乘法运算的集合 。其中任两个元素的并与对称差仍是该族中的元素。", "cites": [{"t": "环论", "b": ""}]}, {"meaning": "环绕,围绕。", "cites": [{"t": "三江环之。", "b": "《国语·越语上》"}, {"t": "戎翟之民实环之。", "b": "《国语·晋语二》"}, {"t": "譬众星之环极。", "b": "《文选·张衡·西京赋》"}, {"t": "环而攻之。", "b": "《孟子·公孙丑下》"}, {"t": "竹树环合。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "贼环而进。", "b": "明·魏禧《大铁椎传》"}, {"t": "环村皆猎户。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "环坐", "t": "环绕而坐"}, {"w": "环绦", "t": "束腰的丝带"}, {"w": "环攻", "t": "围攻"}, {"w": "环瞰", "t": "包围窥伺"}, {"w": "环击", "t": "围攻"}, {"w": "环迫", "t": "四面威逼。"}]}, {"meaning": "旋转。", "cites": [{"t": "环拜以钟鼓为节。", "b": "《周礼·乐师》"}, {"t": "环山者三。", "b": "《战国策·齐策》"}, {"t": "九首蛇身自环。", "b": "《山海经·大荒北经》"}], "words": [{"w": "环回", "t": "循环,周转"}, {"w": "环拜", "t": "盘旋与直拜"}, {"w": "环激", "t": "旋转搅动"}, {"w": "环涛", "t": "回旋的波涛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('946wx','武','1','wǔ','止','8','','[{"pinyin": "wǔ", "defs": [{"meaning": "(会意。从止,从戈。据甲骨文,人持戈行进,表示要动武。本义:勇猛;猛烈) 同本义。", "cites": [{"t": "楚庄王曰,夫文止戈为武。又曰,夫武禁暴戢兵保大定功安民和财者也。", "b": "《左氏春秋·宣公十二年》"}, {"t": "武大为于大君。", "b": "《易·履》"}, {"t": "孔武有力。", "b": "《诗·郑风·羔裘》"}, {"t": "诚既勇兮又以武。", "b": "《楚辞·九歌·国殇》"}], "words": [{"w": "英武", "t": "英俊威武"}, {"w": "威武", "t": "武力;权势;力量强大"}, {"w": "武色", "t": "凶猛的神色"}, {"w": "武车", "t": "威猛的兵车"}, {"w": "武健", "t": "勇武刚健"}, {"w": "武断乡曲", "t": "以威势主断曲直。"}]}, {"meaning": "指干戈军旅之事。", "cites": [{"t": "德不厚而行武。", "b": "《韩非子·五蠹》"}, {"t": "用武之国。", "b": "《三国志·诸葛亮传》"}, {"t": "无用武之地。", "b": "《资治通鉴》"}, {"t": "神武雄才。", "b": ""}], "words": [{"w": "武弁", "t": "武夫;武官"}, {"w": "武不善作", "t": "出力的事不能文绉绉地去做"}, {"w": "武训", "t": "军事训练"}, {"w": "武略", "t": "军事谋略"}, {"w": "武教", "t": "军事教育"}, {"w": "武运", "t": "武事的气运"}, {"w": "武德", "t": "武道。"}]}, {"meaning": "士,兵,卒。", "cites": [{"t": "勇武一人,为三军雄。", "b": "《淮南子》"}, {"t": "文既有之,武亦宜然。", "b": "刘勰《文心雕龙》"}]}, {"meaning": "古以六尺为步,半步为武。", "cites": [{"t": "夫目之察度也,不过步武尺寸之间。", "b": "《国语·周语下》"}]}, {"meaning": "舞蹈", "cites": [{"t": "溺者,非不笑也;罪人,非不歌也;狂者,非不武也。", "b": "《吕氏春秋》"}]}, {"meaning": "足迹。", "cites": [{"t": "昭兹来许,绳其祖武。", "b": "《诗·大雅·生民》"}]}, {"meaning": "古州名 。南朝梁置,治所在武陵(今湖南省常德市)。"}, {"meaning": "金属打击乐器。", "cites": [{"t": "始奏以文,复乱以武。", "b": "《礼记》"}]}, {"meaning": "继承。", "cites": [{"t": "下武维周,世有哲王。", "b": "《诗·大雅·下武》"}]}, {"meaning": "半步。古代六尺为步,半步为武。", "cites": [{"t": "夫目之祭度也,不过步武尺寸之间。", "b": "《国语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('947wx','青','1','qīng','青','8','','[{"pinyin": "qīng", "defs": [{"meaning": "(会意。从生,从丹。金文字形上面是个“生”字;下面是“丹”字,丹是井字之变。“青”是汉字部首之一。本义:蓝色)。"}, {"meaning": "同本义。", "cites": [{"t": "青,东方色也。", "b": "《说文》"}, {"t": "正东曰青州。", "b": "《周礼·职方氏》"}, {"t": "时则有青眚青祥。", "b": "《洪范五行传》。注:“木色也。”"}, {"t": "其色青。", "b": "《素问·风论》。注:“肝色。”"}, {"t": "掌凡金玉锡石丹青之戒令。", "b": "《周礼·职金》。注:“青,空青也。”"}, {"t": "青取之于蓝,而青于蓝。", "b": "《荀子·劝学》"}], "words": [{"w": "青磷", "t": "磷火。俗称鬼火"}, {"w": "青靛", "t": "深蓝色"}, {"w": "青焰焰", "t": "青蓝色"}, {"w": "青云万里", "t": "比喻前程远大"}, {"w": "青云干吕", "t": "庆云翔集,应乎六吕。是一种吉祥的征兆"}, {"w": "青冥", "t": "青天"}, {"w": "青霄", "t": "青空,碧空。"}]}, {"meaning": "深绿色。", "cites": [{"t": "两岸青山相对出。", "b": "唐·李白《望天门山诗》"}, {"t": "草色入帘青。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "青箬笠。", "b": "唐·张志和《渔歌子》词"}, {"t": "青树翠蔓。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "青冉冉", "t": "形容松柏叶色青翠、柔和"}, {"w": "青靛", "t": "浮萍"}, {"w": "青铜", "t": "铜镜"}, {"w": "青琐", "t": "宫门上的一种青色连环图案"}, {"w": "青冢", "t": "坟墓;亦单指王昭君墓"}, {"w": "青记", "t": "生下来在皮肤上就有的青斑"}, {"w": "青条条", "t": "形容青而长"}, {"w": "青鸦鸦", "t": "青青的"}, {"w": "青港港", "t": "深青色"}, {"w": "青枫林", "t": "指墓地。旧时墓地多种青枫树。"}]}, {"meaning": "东方的代称。", "cites": [{"t": "东方谓之青。", "b": "《考工记·画绘之事》"}], "words": [{"w": "青宫", "t": "太子居东宫,东方色为青,所以称东宫为青宫"}, {"w": "青土", "t": "指东方之地。"}]}, {"meaning": "春的代称。", "cites": [{"t": "镜朱尘之照烂,袭青气之烟。", "b": "南朝梁·江淹《别赋》"}], "words": [{"w": "青风", "t": "春风"}, {"w": "青阳", "t": "春天"}, {"w": "青帝", "t": "春神。"}]}, {"meaning": "青海省的简称。"}, {"meaning": "古州名。"}, {"meaning": "《禹贡》九州之一。在今山东省及辽宁省辽河以东。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('948wx','责','1','zé zhài','贝','8','','[{"pinyin": "zé", "defs": [{"meaning": "(形声。小篆字形。从贝,朿(cì)声。(zhài)本义:债款,债务)。"}, {"meaning": "索取(财物)。", "cites": [{"t": "责,求也。", "b": "《说文》"}, {"t": "往责于东邑。", "b": "《吕氏春秋·慎行论》"}, {"t": "责之里正。", "b": "《聊斋志异·促织》"}, {"t": "责一头。", "b": ""}, {"t": "以塞官责。", "b": ""}], "words": [{"w": "责偿", "t": "索取赔偿"}, {"w": "责货", "t": "索贿"}, {"w": "责诺", "t": "求取他人的许诺"}, {"w": "责义", "t": "以合乎礼义要求别人"}, {"w": "责债", "t": "索债"}, {"w": "责赂", "t": "索求财物。"}]}, {"meaning": "责备。", "cites": [{"t": "责人斯无难,惟受责俾如流,是惟艰哉!", "b": "《书·泰誓》"}, {"t": "尚不觉悟而不自责,过矣。", "b": "《史记·项羽本纪》"}, {"t": "无责也。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "叱责", "t": "大声呵叱责备"}, {"w": "呵责", "t": "呵斥"}, {"w": "苛责", "t": "过严地责备"}, {"w": "责嚷", "t": "责备;训斥"}, {"w": "责劝", "t": "责备并规劝"}, {"w": "责黜", "t": "责备和贬黜"}, {"w": "谴责", "t": "严加申斥"}, {"w": "责让", "t": "责备、谴责"}, {"w": "贬责", "t": "指出过失,加以批评;责备。"}]}, {"meaning": "惩罚。", "cites": [{"t": "当其为里正,受扑责时,岂意其至此哉!", "b": "《聊斋志异·促织》"}, {"t": "崇患太祖慵惰不作业,数加笞责。", "b": "《新五代史·梁家人传》"}], "words": [{"w": "笞责;责惩", "t": "责罚惩处"}, {"w": "责知", "t": "责罚包庇罪人、知情不言者"}, {"w": "责杖", "t": "以杖刑责罚。"}]}, {"meaning": "诘问。", "cites": [{"t": "收奴婢十余人去,责以杀婢事。", "b": "《汉书·赵严韩张两王传》"}], "words": [{"w": "责诘", "t": "责问"}, {"w": "责究", "t": "责问追究。"}]}, {"meaning": "责令;要求。", "cites": [{"t": "今释其所有,责其所无。", "b": "《盐铁论·本议》"}, {"t": "躬自厚而薄责于人。", "b": "《论语·卫灵公》"}, {"t": "赦罪责功。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "责己也重以周。", "b": "唐·韩愈《原毁》"}, {"t": "大将军使长史急责广之幕府对簿。", "b": "《史记·李将军列传》"}, {"t": "责成人之道。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "责报", "t": "让人报答;图报"}, {"w": "责办", "t": "责成办理"}, {"w": "责买", "t": "责成购买。"}]}, {"meaning": "责任,差使。", "cites": [{"t": "亦恐二世诛之,故欲以法诛将军以塞责。", "b": "《史记·项羽本纪》"}, {"t": "主道者,使人臣有必言之责,又有不言之责。", "b": "《韩非子》"}, {"t": "救护之责。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "专责", "t": "专门担负的某项责任"}, {"w": "权责", "t": "权力和责任"}, {"w": "负责", "t": "担负责任"}, {"w": "卸责", "t": "推卸责任"}, {"w": "职责", "t": "职务和责任"}, {"w": "罪责", "t": "罪行的责任。"}]}]}, {"pinyin": "zhài", "defs": [{"meaning": "欠别人的财物", "cites": [{"t": "听称责以傅别。", "b": "《周礼·小宰》。司农注:“称责,谓贷子。”"}, {"t": "薄敛已责。", "b": "《左传·昭公二十年》"}, {"t": "使无券契之责。", "b": "《管子·轻重乙》"}, {"t": "博言负责数百万。", "b": "《汉书·淮阳宪王钦传》。注:“假贷人财物未偿者。”"}, {"t": "是有丕子之责于天。", "b": "《书·金滕》"}, {"t": "宋多责赂于郑。", "b": "《左传·桓公十三年》"}, {"t": "谁习计会,能为文收责于薛者乎?", "b": "《战国策·齐策》"}, {"t": "岁竟,此两家常折券弃责。", "b": "《汉书·高帝纪上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('949wx','现','1','xiàn','见','8','','[{"pinyin": "xiàn", "defs": [{"meaning": "(形声。从玉,见声。本义:出现)。"}, {"meaning": "同本义(明显看得见)。", "cites": [{"t": "现,俗见字。", "b": "《广韵》"}, {"t": "东坡现右足。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "现弄", "t": "在人面前炫示自己"}, {"w": "现化", "t": "佛教所称佛或菩萨在人间显现的化身"}, {"w": "现示", "t": "显示。"}]}, {"meaning": "见。", "cites": [{"t": "帝宣,三人借袍现帝。", "b": "《三国志平话》"}]}, {"meaning": "玉光。", "cites": [{"t": "现,玉光。", "b": "《集韵》"}]}, {"meaning": "次于玉的石。", "cites": [{"t": "现,石之次玉者。", "b": "《集韵》"}]}, {"meaning": "现在,眼前。", "cites": [{"t": "那世里造的孽,这会子现世现报。", "b": "《红楼梦》"}], "words": [{"w": "现时报", "t": "现世报"}, {"w": "现世生苗", "t": "眼前就有效益"}, {"w": "现打不赊", "t": "犹言立即惩处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('950wx','玫','1','méi','攵','8','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从玉,文声。双音词“玫瑰”,指美玉,或珍珠,又植物名)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('951wx','表','1','biǎo','一','8','','[{"pinyin": "biǎo", "defs": [{"meaning": "(会意。从毛,从衣,“毛”又兼作声符。小篆字形,衣字中间加个毛字。古人穿皮衣,毛朝外面,所以“表”从“毛”。本义:外衣)。"}, {"meaning": "同本义。", "cites": [{"t": "表,上衣也。", "b": "《说文》。朱骏声曰:“古者衣裘,以毛为里。按,古衣裘皆外毛,礼服必加裼衣其上。许所谓上衣也,故曰以毛为田,言有表,则毛在里也。”"}, {"t": "表裘不入公门。", "b": "《礼记·玉藻》"}, {"t": "必表而出之。", "b": "《论语》。皇疏:“谓加上衣也。”"}, {"t": "中绀而表素。", "b": "《庄子·让王》"}], "words": [{"w": "表裘", "t": "外衣"}, {"w": "表礼", "t": "作为礼物的衣料"}, {"w": "表里", "t": "衣服的面子与里子;里外;也指作为礼物的衣料。"}]}, {"meaning": "外面(与“里”相对)。", "cites": [{"t": "表里山河。", "b": "《左传·僖公二十八年》"}], "words": [{"w": "表海", "t": "临海,滨海"}, {"w": "表薄", "t": "泛指出身贫贱。表:野外;薄:山林"}, {"w": "表里相应", "t": "指内外互相应和"}, {"w": "表壮不如里壮", "t": "丈夫有才能,还不如妻子善能持家,可为内助。表指丈夫,里指妻子。"}]}, {"meaning": "外表,外貌。", "cites": [{"t": "虚有其表耳。", "b": "《明皇实录》"}], "words": [{"w": "表相", "t": "外貌"}, {"w": "表征", "t": ""}]}, {"meaning": "表率,榜样。", "cites": [{"t": "仁者,天下之表也。", "b": "《礼记·表记》"}, {"t": "廉者,民之表也。", "b": "包拯《乞不用赃吏》"}], "words": [{"w": "表正", "t": "证据;表率;榜样"}, {"w": "表俗", "t": "作为世人的表率。"}]}, {"meaning": "表帜,标志。", "cites": [{"t": "祭之日表。", "b": "《周礼·肆师》"}, {"t": "君法明,论有常,表仪既设民知方。", "b": "《荀子·成相》"}], "words": [{"w": "表旗", "t": "边境上的标帜"}, {"w": "表识", "t": "标记,标帜。"}]}, {"meaning": "给皇帝上的奏章。", "cites": [{"t": "今当远离,临表涕零,不知所言。", "b": "诸葛亮《出师表》"}, {"t": "出师一表真名世,千载谁堪伯仲间。", "b": "陆游《书愤》"}], "words": [{"w": "表函", "t": "上呈天子的函件"}, {"w": "表奏", "t": "表文奏章"}, {"w": "表草", "t": "表文的草稿。"}]}, {"meaning": "表格。", "cites": [{"t": "为十表。", "b": "司马迁《报任安书》"}], "words": [{"w": "度量衡表;对数表;乘法表;编制表;一览表;价目表", "t": ""}]}, {"meaning": "作标记的木柱。", "cites": [{"t": "吴起治西河,欲谕其信于民,夜日置表于南门之外。", "b": "《吕氏春秋·慎小》"}, {"t": "城上千步一表。", "b": "《墨子·备城门》"}]}, {"meaning": "直立于地面,用以测日影的标杆。", "cites": [{"t": "夏至日中立八尺之表,其景尺有五寸,谓之地中。(景:影。)", "b": "阮元《畴人传》"}]}, {"meaning": "石碑。", "cites": [{"t": "千里立表,万里连纪。", "b": "《汉书》"}]}, {"meaning": "表彰,显扬。", "cites": [{"t": "刻石表功兮炜煌煌。", "b": "唐·韦应物《石鼓歌》"}], "words": [{"w": "旌表", "t": "立石碑、匾额以颂扬功德"}, {"w": "表章", "t": "显扬;宣扬;古代臣子上君王的奏章"}, {"w": "表显", "t": "显扬"}, {"w": "表式", "t": "表彰。"}]}, {"meaning": "设立标记;标出,标明。", "words": [{"w": "表木", "t": "立木为标志"}, {"w": "表目", "t": "标名,命名"}, {"w": "表揭", "t": "标志。"}]}, {"meaning": "表白。", "cites": [{"t": "或援誓以表心。", "b": "刘知几《史通》"}], "words": [{"w": "表异", "t": "表明特异之处"}, {"w": "表微", "t": "表明微细之事"}, {"w": "表心意;按下不表;表抒", "t": "表达,抒发。"}]}, {"meaning": "启奏,上表章给皇帝。", "cites": [{"t": "亮自表后主。", "b": "《三国志·诸葛亮传》"}, {"t": "礼官辄表贺。", "b": "《明史·海瑞传》"}, {"t": "曹公表权为骠骑将军。", "b": "《三国志·吴书·吴主传》"}], "words": [{"w": "表救", "t": "上表援救"}, {"w": "表闻", "t": "上表申闻于上"}, {"w": "表荐", "t": "上表推荐"}, {"w": "表谢", "t": "上表谢恩"}, {"w": "表劝", "t": "上表劝即帝位。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('952wx','规','1','guī','见','8','','[{"pinyin": "guī", "defs": [{"meaning": "(会意。金文字形,从聿从周,当系以规画之意。本义:画圆的器具,今指圆规)。"}, {"meaning": "同本义。", "cites": [{"t": "规,有法度也。从矢,从见,会意。", "b": "《说文》"}, {"t": "规矩方圆之至也。", "b": "《孟子》"}, {"t": "规者,正圆之器也。", "b": "《诗·沔水》序·笺"}, {"t": "圆曰规,方曰矩。", "b": "《楚辞·离骚》"}, {"t": "我有天志,譬若轮人之有规,匠人之有矩。", "b": "《墨子·天志上》"}, {"t": "圆者中规,方者中矩。", "b": "《荀子·赋》"}, {"t": "木直中绳,輮以为轮,其曲中规。", "b": "《荀子·劝学》"}], "words": [{"w": "规绳", "t": "规矩绳墨"}, {"w": "规旋", "t": "如圆规般旋转"}, {"w": "规轮", "t": "圆规和车轮"}, {"w": "规轴", "t": "圆规之轴。比喻规度。"}]}, {"meaning": "法度、准则。", "cites": [{"t": "必将崇论闳议,创业垂统,为万世规。", "b": "《史记·司马相如列传·难蜀父老》"}], "words": [{"w": "规绳", "t": "规矩绳墨。比喻法度"}, {"w": "规简", "t": "规矩法度"}, {"w": "规检", "t": "规矩法度;循规矩,守法度"}, {"w": "规度", "t": "规则法度。"}]}, {"meaning": "模范;典范,风仪。", "cites": [{"t": "生为百夫雄,死为壮士规。", "b": "三国魏·王粲《咏史》"}, {"t": "素德清规足传于汗简矣。", "b": "《晋传书王承传论》"}], "words": [{"w": "规仿", "t": "以为模范而加以仿效。"}]}, {"meaning": "成例;标准;法则。", "cites": [{"t": "夫萧规曹随。", "b": "扬雄《解嘲》"}, {"t": "释规而任巧,释法而任智,惑乱之道也。", "b": "《韩非子·饰邪》"}], "words": [{"w": "规节", "t": "规矩,节操"}, {"w": "规礼", "t": "清代官吏向下属索取的现金和礼品"}, {"w": "规银", "t": "当时上海通行的计算银两。每两块银约合银元一元四角左右"}, {"w": "规容", "t": "规范"}, {"w": "规表", "t": "规范表率。"}]}, {"meaning": "画圆。", "cites": [{"t": "其母梦神规其臀以墨。", "b": "《国语·周语下》"}, {"t": "曲眉规只。", "b": "《楚辞·大招》"}], "words": [{"w": "规圆", "t": "用圆规校之使其圆。"}]}, {"meaning": "划分土地而占有。", "cites": [{"t": "昔我先王之有天下也,规方千里,以为甸服。", "b": "《国语·周语中》"}, {"t": "规方千里:划定王都周围千里的地方。甸服:畿内之地,作为直接收取谷物的地方。", "b": ""}], "words": [{"w": "规田", "t": "周时田地分等的名称。用以蓄水的土地,合九人所分到的称为一规。农耕的土地,合九人所 配得耕种的称为一井。四规相当一井"}, {"w": "规表", "t": "划分明白。"}]}, {"meaning": "劝告,建议,尤指温和地力劝。", "cites": [{"t": "夫可规以利而可谏以言者,皆愚陋恒民之谓耳。", "b": "《庄子·盗跖》"}, {"t": "朋友之交,至于劝善规过足矣。", "b": "清·刘开《问说》"}], "words": [{"w": "规利", "t": "以利益来劝诱"}, {"w": "规饬", "t": "劝诫"}, {"w": "规过", "t": "规正过失"}, {"w": "规谈", "t": "劝勉"}, {"w": "规箴", "t": "规戒劝告"}, {"w": "规镜", "t": "规鉴。规箴与鉴戒。"}]}, {"meaning": "计划;打算。", "cites": [{"t": "南阳刘子骥,高尚士也,闻之,欣然规往。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "规事", "t": "计划事情"}, {"w": "规谋", "t": "规划计谋"}, {"w": "规虑", "t": "规划;谋虑"}, {"w": "规算", "t": "规划打算。"}]}, {"meaning": "谋求;谋划。", "cites": [{"t": "今将军诚能命猛将统兵数万,与豫州协规同力,破操军必矣。", "b": "《资治通鉴》"}], "words": [{"w": "规求", "t": "谋求;贪求"}, {"w": "规脱", "t": "设法逃脱"}, {"w": "规图", "t": "谋求"}, {"w": "规画", "t": "筹划;谋划。"}]}, {"meaning": "窥察。", "cites": [{"t": "不能死之,千人环规。", "b": "《商君书·境内》"}], "words": [{"w": "规情", "t": "窥探军情或情报。"}]}, {"meaning": "圆形。", "cites": [{"t": "冥冥皓容,规规皓质。", "b": "唐·蒋防《姮娥奔月赋》"}], "words": [{"w": "规天", "t": "圆形的天空"}, {"w": "规空", "t": "圆形的天空"}, {"w": "规规", "t": "圆的样子。多形容日月"}, {"w": "规车", "t": "指车轮"}, {"w": "规天矩地", "t": "象征圆的天和方的地。"}]}, {"meaning": "浅陋、拘泥的样子。", "cites": [{"t": "而小儒规规焉以君臣之义无所逃于天地之间。", "b": "清·黄宗羲《原君》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('953wx','抹','1','mā mǒ mò','扌','8','','[{"pinyin": "mā", "defs": [{"meaning": "揩;擦。", "cites": [{"t": "武松抹了桌子。", "b": "《水浒全传》"}], "words": [{"w": "抹脱", "t": "擦掉"}, {"w": "抹泪揉眵", "t": "揩拭眼泪"}, {"w": "抹抹", "t": "揩抹干净。"}]}]}, {"pinyin": "mǒ", "defs": [{"meaning": "(形声。从手,末声。本义:涂抹,涂敷;搽)。"}, {"meaning": "同本义。", "cites": [{"t": "学毋无不为,晓妆随手抹。", "b": "杜甫《北征》"}], "words": [{"w": "抹脸", "t": "演戏时化妆涂脸"}, {"w": "抹油嘴", "t": "白吃,沾便宜。"}]}, {"meaning": "涂掉,抹去。", "cites": [{"t": "我抹的这瓶口儿净。", "b": "李真夫《虎头牌》"}], "words": [{"w": "抹倒", "t": "抹掉;抹去"}, {"w": "抹勒", "t": "涂掉"}, {"w": "抹零", "t": "算账或付钱时抹去整数之外的尾数。"}]}]}, {"pinyin": "mò", "defs": [{"meaning": "轻按。弹奏弦乐器的一种指法。", "cites": [{"t": "轻拢慢捻抹复挑。", "b": "唐·白居易《琵琶行》"}]}, {"meaning": "蒙住。", "cites": [{"t": "各以红绡抹头。", "b": "《聊斋志异》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('954wx','卦','1','guà','卜','8','','[{"pinyin": "guà", "defs": [{"meaning": "(形声。从卜(bǔ,占卜),圭(guī)声。本义:象征自然现象和人事变化的一套符号,供占卜用)。"}, {"meaning": "同本义。", "cites": [{"t": "卦,筮也。", "b": "《说文》。按,所以筮也。"}, {"t": "观变于阴阳而立卦。", "b": "《易·说卦》。注:“象也。”"}, {"t": "神卦灵兆。", "b": "《剧秦美新》。注:“蓍曰卦。”"}, {"t": "卦者在左。", "b": "《仪礼·士冠礼》。注:“有司主画地识爻者也。”又所卦者。注:“所卦者,所以画地记爻。”"}]}, {"meaning": "比喻预见。", "cites": [{"t": "好嘛,看你生宝这卦灵不灵吧。", "b": "柳青《创业史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('955wx','坷','1','kě kē','土','8','','[{"pinyin": "kě", "defs": [{"meaning": "意思是道路高低不平；事情不顺利或不称心，比喻十分不得志。"}]}, {"pinyin": "kē", "defs": [{"meaning": "[方言]土块"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('956wx','坯','1','pī','土','8','','[{"pinyin": "pī", "defs": [{"meaning": "没有烧过的砖瓦、陶器。", "cites": [{"t": "坏,瓦未烧也。", "b": "《说文》"}], "words": [{"w": "砖坯;瓦坯", "t": ""}]}, {"meaning": "山丘一重", "cites": [{"t": "山:三袭,陟;再成,英;一成,坯。", "b": "《尔雅·释山》。义疏:“坯者,当作坏。《说文》云:“丘,再成也。”再,盖一字之误。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('957wx','拓','1','tà tuò','扌','8','','[{"pinyin": "tà", "defs": [{"meaning": "拓印 。在刻铸有文字或图像的器物上蒙一层纸,捶打后使凹凸分明,涂上墨,显出文字图像来。", "cites": [{"t": "其相承传拓之本,犹在秘府。", "b": "《隋书·经籍志》"}], "words": [{"w": "拓工", "t": "拓印的工艺"}, {"w": "拓手", "t": "摹印石碑上文字、图画的技艺"}, {"w": "拓本", "t": "拓片装订成的本子"}, {"w": "拓印", "t": "摹印石碑或器物上的文字、图画"}, {"w": "拓墨", "t": "拓取用的墨。"}]}, {"meaning": "以纸片依样制作。", "cites": [{"t": "新拓来的鞋样子的鞋,刚刚上脚。", "b": "丁玲《母亲》"}]}, {"meaning": "贴。", "cites": [{"t": "就是前日被瘟官打的棒疮,在暗地狱里讨个烂膏药拓了。", "b": "清·张南庄《何典》"}]}, {"meaning": "涂抹。", "cites": [{"t": "极鬼便纠合几个同道中,来到村里,拣个僻静所在,拓花了面孔,扎扮停当,…打进门去。", "b": "清·张南庄《何典》"}]}]}, {"pinyin": "tuò", "defs": [{"meaning": "举,托起。", "cites": [{"t": "孔子之劲,能拓国门之关。", "b": "《列子·说符》。注:“拓,举也。”"}]}, {"meaning": "开辟;扩展。", "cites": [{"t": "扩地寖广,兵甲日盛。", "b": "《后汉书·张步传》"}, {"t": "辟土四面,拓地千里。", "b": "《吴子·图国》"}, {"t": "拓世贻统。", "b": "颜延之《三月三日曲水诗序》"}], "words": [{"w": "拓地", "t": "开拓疆土"}, {"w": "拓界", "t": "开拓疆界"}, {"w": "拓宇", "t": "开辟疆域"}, {"w": "拓造", "t": "开辟创造"}, {"w": "拓销", "t": "开辟销路"}, {"w": "拓边", "t": "开拓边疆"}, {"w": "拓辟", "t": "开辟。"}]}, {"meaning": "把物推开。", "cites": [{"t": "拓,手推物。", "b": "《集韵》"}]}, {"meaning": "张开。", "cites": [{"t": "至是, [张]浦见士皆拓两石弓有余力,大骇。", "b": "吴广成《西夏书事》"}]}, {"meaning": "——见“落拓”（luòtuò）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('958wx','拢','1','lǒng','扌','8','','[{"pinyin": "lǒng", "defs": [{"meaning": "(形声。从手,龙声。本义:聚合,合拢)。"}, {"meaning": "同本义。", "cites": [{"t": "拢万川乎巴梁。", "b": "郭璞《江赋》"}], "words": [{"w": "拢钱", "t": ""}]}, {"meaning": "梳理;整理。", "cites": [{"t": "[湘云]便在石蹬上重新匀了脸,拢了鬓,连忙起身,同着来至红香圃中。", "b": "《红楼梦》"}]}, {"meaning": "傍靠。", "cites": [{"t": "知郎旧时意,且请拢船头。", "b": "《乐府诗集·丁仙芝·江南曲》"}], "words": [{"w": "拢家", "t": "回家"}, {"w": "拢岸;拢船", "t": "撑船靠岸"}, {"w": "拢边", "t": "靠近旁边。"}]}, {"meaning": "弹奏弦乐器的一种指法。用指在弦上上下按捺。", "cites": [{"t": "轻拢慢捻抹复挑。", "b": "白居易《琵琶行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('959wx','拔','1','bá','扌','8','','[{"pinyin": "bá", "defs": [{"meaning": "(形声。从手,犮(bó)声。本义:拔起,拔出)。"}, {"meaning": "同本义。", "cites": [{"t": "拔,擢也。", "b": "《说文》"}, {"t": "拔,引也。", "b": "《苍颉篇》"}, {"t": "确乎其不可拔。", "b": "《易·乾》。郑注:“移也。”"}, {"t": "拔河。", "b": "《封氏见闻录》"}, {"t": "杨子取为我,拔一毛而利天下,不为也。", "b": "《孟子·尽心上》"}, {"t": "力拔山兮气盖世。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "拔剑切而啖之。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "拔剑撞而破之。", "b": ""}, {"t": "拔刃奋起。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "拔毛;拔草;拔秧", "t": ""}]}, {"meaning": "选拔;提拔。", "cites": [{"t": "是以先帝简拔以遗陛下。", "b": "诸葛亮《出师表》"}, {"t": "山涛作冀州,甄拔三十余人。", "b": "李白《与韩荆州书》"}], "words": [{"w": "拔用", "t": "提拔任用"}, {"w": "拔补", "t": "提拔补官"}, {"w": "选拔", "t": "挑选"}, {"w": "提拔", "t": "挑选人员任更高职。"}]}, {"meaning": "突出;超出。", "cites": [{"t": "势拔五岳掩赤城。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "拔绝", "t": "卓越"}, {"w": "出类拔萃", "t": "才能出众。"}]}, {"meaning": "突起。", "cites": [{"t": "皆峭拔险怪。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "然峭拔秀丽皆不可与小孤比。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "挺拔", "t": "直立而高耸"}, {"w": "拔立", "t": "耸立;挺立。"}]}, {"meaning": "攻取。", "cites": [{"t": "拔石城。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "已拔赵。", "b": "《史记·魏公子列传》"}], "words": [{"w": "拔城;连拔敌人四个据点", "t": ""}]}, {"meaning": "移动。", "cites": [{"t": "亮拔县千余家。", "b": "罗贯中《三国演义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('960wx','坪','1','píng','土','8','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从土,平声。本义:平坦之地)。"}, {"meaning": "同本义,泛指山区和丘陵地区局部的平地。", "cites": [{"t": "坪,地平也。", "b": "《说文》"}], "words": [{"w": "草坪;停机坪", "t": ""}]}, {"meaning": "中国西北黄土地区的黄土阶地或台地。草多是良好的农耕场所。"}, {"meaning": "日本面积单位名,等于一日亩的三十分之一,合3.3057平方米。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('961wx','拣','1','jiǎn','扌','8','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从手,柬声。“柬”亦兼表字义。本义:挑选,选择)。"}, {"meaning": "同本义。", "cites": [{"t": "揀,择也。", "b": "《广雅》"}], "words": [{"w": "拣人", "t": "挑人"}, {"w": "拣换", "t": "挑选,更换"}, {"w": "拣口儿", "t": "挑食,挑可口的食物"}, {"w": "拣发", "t": "选择;委派"}, {"w": "拣有头发的抓", "t": "选择有钱人作为进攻的对象。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('962wx','坦','1','tǎn','土','8','','[{"pinyin": "tǎn", "defs": [{"meaning": "(形声。从土,旦声。本义:平而宽广)。"}, {"meaning": "同本义。", "cites": [{"t": "坦,安也。", "b": "《说文》"}, {"t": "道坦坦。", "b": "《易·履》"}, {"t": "坦坦,平也。", "b": "《广雅》"}, {"t": "坦气修通。", "b": "《管子·板法》。注:“平也。”"}], "words": [{"w": "平坦", "t": "没有高低凹凸"}, {"w": "坦夷", "t": "土地开阔平坦"}, {"w": "坦坦", "t": "平宽的样子"}, {"w": "坦迤", "t": "地势平缓而连绵不断"}, {"w": "坦途", "t": "平坦的路。"}]}, {"meaning": "坦率,显明。", "cites": [{"t": "君子坦荡荡。", "b": "《论语》"}], "words": [{"w": "坦挚", "t": "坦率而真诚"}, {"w": "坦怀", "t": "开诚相见;胸怀坦荡"}, {"w": "坦衷", "t": "襟怀坦率"}, {"w": "坦易", "t": "坦率平易"}, {"w": "坦直", "t": "坦白直率"}, {"w": "坦夷", "t": "坦率平易。"}]}, {"meaning": "敞开。", "cites": [{"t": "坦腹江亭暖,长呤野望时。", "b": "杜甫《江亭》"}], "words": [{"w": "坦怀", "t": "敞开胸怀。"}]}, {"meaning": "露出;吐露。", "cites": [{"t": "赵大爷给我出的主意:教我到派出所去坦白,要不然我永远是个黑人。", "b": "老舍《龙须沟》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('963wx','担','1','dān dàn','扌','8','','[{"pinyin": "dān", "defs": [{"meaning": "(形声。从手,詹声。本义:用肩挑)。"}, {"meaning": "同本义。", "cites": [{"t": "儋,何也。从人,詹声。以背曰负,以肩曰儋。", "b": "《说文》。字亦作“擔”。"}, {"t": "担,负也。", "b": "《字林》"}, {"t": "担囊行取薪。", "b": "曹操《苦寒行》"}, {"t": "负书担橐。", "b": "《战国策·秦策一》"}], "words": [{"w": "肩不能担,手不能提;担戴", "t": "肩挑头顶。"}]}, {"meaning": "承当,承担。", "cites": [{"t": "吾担悲也。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "分担", "t": "担负一部分"}, {"w": "担承", "t": "承担"}, {"w": "担扶", "t": "担当;扶助"}, {"w": "担杜", "t": "有能力承担责任的人"}, {"w": "担干系", "t": "担干纪。负责任。"}]}]}, {"pinyin": "dàn", "defs": [{"meaning": "扁担和挂在两头的东西。", "cites": [{"t": "负担荷以丈尺兮。", "b": "《楚辞·哀时命》。注:“荷曰担。”"}, {"t": "有卖油翁释担而立。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "挑担;担仗", "t": "行李担子。亦作“担脚”,“担杖”"}, {"w": "担头", "t": "货担两头;一挑东西"}, {"w": "货郎担", "t": ""}]}, {"meaning": "中国重量单位。旧制一百斤为一担,今以百市斤为一市担。", "cites": [{"t": "但闻行路吟新诗,不叹举家无担石。", "b": "李颀《别梁鍠》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('964wx','坤','1','kūn','土','8','','[{"pinyin": "kūn", "defs": [{"meaning": "(形声。从土,申声。本义:八卦之一,象征地)。"}, {"meaning": "地,大地。", "cites": [{"t": "坤,地也,易之卦也。", "b": "《说文》"}, {"t": "坤,土也。", "b": "《左传·庄公二十二年》"}, {"t": "坤也者,地也。", "b": "《易·说卦》"}, {"t": "山岳河渎,皆坤之灵。", "b": "《宋书·乐志》"}], "words": [{"w": "坤元", "t": "坤的元始之德,指大地资生万物之德"}, {"w": "坤母", "t": "地;火"}, {"w": "坤后", "t": "地"}, {"w": "坤珍", "t": "象征大地的符瑞"}, {"w": "坤轴", "t": "想像中的地轴"}, {"w": "坤维", "t": "地维。指大地的四方"}, {"w": "坤仪", "t": "大地。同坤舆。"}]}, {"meaning": "《易》卦名。"}, {"meaning": "八卦之一。", "cites": [{"t": "坤为地、为母、为布、为釜、为吝啬。", "b": "《易·说卦》"}], "words": [{"w": "坤卦", "t": "八卦之一,代表地"}, {"w": "坤乾", "t": "古书名。阴阳之书。"}]}, {"meaning": "六十四卦之一。", "cites": [{"t": "地势坤,君子以厚德载物。", "b": "《易·坤·象》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('965wx','押','1','yā','扌','8','','[{"pinyin": "yā", "defs": [{"meaning": "(形声。从手,甲声。本义:签署,在公文、契约上签字或画记号,以做凭信)。"}, {"meaning": "同本义。", "cites": [{"t": "随即押一纸公文。", "b": "《水浒全传》"}], "words": [{"w": "押了花字", "t": "押花"}, {"w": "押合同", "t": "签订合同"}, {"w": "押榜", "t": "在官府文告上签字"}, {"w": "押敕", "t": "签署诏令"}, {"w": "押文字", "t": "签字"}, {"w": "押字", "t": "签字"}, {"w": "押署", "t": "签名;画押。"}]}, {"meaning": "抵押,典当。", "cites": [{"t": "暂且押四百两银子。", "b": "《红楼梦》"}], "words": [{"w": "押月", "t": "租赁房屋时先付给房东两个月租金,其中一个月的租金作为预付"}, {"w": "押地", "t": "旧时作为抵押品的田地"}, {"w": "押款", "t": "商业用语。以货物或有价证券等做抵押向银行或钱庄借款"}, {"w": "押期", "t": "抵押期限"}, {"w": "押价", "t": "典当或抵押的价格"}, {"w": "押保", "t": "押出交保。"}]}, {"meaning": "押送。", "cites": [{"t": "押正旦带枷上。", "b": "《窦娥冤》"}], "words": [{"w": "押水", "t": "水路运输的押运人"}, {"w": "押发", "t": "押送。"}]}, {"meaning": "执掌。", "cites": [{"t": "以六员分押尚书六曹。", "b": "《新唐书·百官志》"}], "words": [{"w": "押寨夫人", "t": "压寨夫人"}, {"w": "押班", "t": "百官朝会时位在班列之首的官员。"}]}, {"meaning": "挤压。", "cites": [{"t": "初生子,便以石押其头使扁。", "b": "《晋书·东夷·辰韩传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('966wx','抽','1','chōu','扌','8','','[{"pinyin": "chōu", "defs": [{"meaning": "(形声。从手,由声。本义:拔出,抽出)。"}, {"meaning": "拔出,把夹在中间的东西取出。", "cites": [{"t": "抽,拔也。", "b": "《广雅》"}, {"t": "每射,抽矢菆。", "b": "《左传·宣公十二年》"}, {"t": "挈水若抽。", "b": "《庄子·天地》。李注:“引也。”"}, {"t": "左旋右抽。", "b": "《诗·郑风·清人》"}, {"t": "抽刀断水水更流。", "b": "李白《宣州谢眺楼饯别校书叔云》"}], "words": [{"w": "抽简禄马", "t": "算命"}, {"w": "抽匣", "t": "抽剑出匣"}, {"w": "抽毫", "t": "抽笔出套"}, {"w": "抽宝剑;抽刀", "t": ""}]}, {"meaning": "从全部里取出一部分;拔除。", "cites": [{"t": "言抽其棘。", "b": "《诗·小雅·楚茨》"}, {"t": "抽其半。", "b": "《仪礼·丧服传》"}], "words": [{"w": "抽分", "t": "从中取得一分"}, {"w": "抽功夫", "t": "抽空"}, {"w": "抽暇", "t": "抽空。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('967wx','拐','1','guǎi','扌','8','','[{"pinyin": "guǎi", "defs": [{"meaning": "(形声。从手。本义:拐杖) 同本义", "cites": [{"t": "沉香拐拄一根。", "b": "《红楼梦》"}], "words": [{"w": "拐子头", "t": "小孩。因老人需孩子扶行,其作用如同“拐杖”;又俗称太监身边的小厮"}, {"w": "拐儿", "t": "拐杖;脚踝"}, {"w": "拐柱", "t": "拐棍"}, {"w": "拐子马", "t": "北宋时称左右两翼骑兵为拐子马。"}]}, {"meaning": "诱骗。把妇女或儿童骗带走。", "cites": [{"t": "那日买了一个丫头,不想是拐子拐来的。", "b": "《红楼梦》"}, {"t": "又拐了三百多去。", "b": "清·郭小亭《济公全传》"}], "words": [{"w": "拐孩子;拐占", "t": "拐骗占有"}, {"w": "拐米倒做了仓官", "t": "喻世上不平事太多,说不清楚"}, {"w": "拐良为娼", "t": "拐卖良家妇女作妓女"}, {"w": "拐儿", "t": "拐骗人口、财物的人"}, {"w": "拐局", "t": "拐骗的圈套。"}]}, {"meaning": "转弯,常指行进时改变方向。", "cites": [{"t": "往前走一百米,再向右拐弯,就到了他家", "b": ""}], "words": [{"w": "拐弯儿;拐回来", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('968wx','拖','1','tuō','扌','8','','[{"pinyin": "tuō", "defs": [{"meaning": "(形声。本作“拕”,左形,右声。本义:曳引)。"}, {"meaning": "同本义。", "cites": [{"t": "拕,引也。", "b": "《广雅》"}, {"t": "纵体拖发。", "b": "《淮南子·齐俗》"}, {"t": "拖其衣被。", "b": "《淮南子·人间世》"}, {"t": "拖舟而入水。", "b": "《汉书·南越传》"}], "words": [{"w": "拖上州拔下县", "t": "被拖到州里,拉到县上"}, {"w": "拖罟", "t": "拖网"}, {"w": "拖钩", "t": "拔河的别称"}, {"w": "拖刀计", "t": "假装败走将刀垂下,乘机回击之计"}, {"w": "拖扯", "t": "拉扯;拉住。"}]}, {"meaning": "下垂。", "cites": [{"t": "峨大冠拖长绅。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "拖天扫地", "t": "形容衣服过长"}, {"w": "拖玉", "t": "衣襟下垂带玉佩。喻指显贵"}, {"w": "拖地锦", "t": "女子结婚时的披红"}, {"w": "拖挂", "t": "下垂。亦指小竽之物"}, {"w": "拖露", "t": "下垂。"}]}, {"meaning": "强夺或费力取得。", "cites": [{"t": "秦牛缺径于山中而遇盗…拖其衣被。", "b": "《淮南子》"}]}, {"meaning": "披散。", "cites": [{"t": "纵体拖发,箕倨反言。", "b": "《淮南子》"}]}, {"meaning": "掷。", "cites": [{"t": "昔闻杨伯起,拖金振清风。", "b": "南朝梁·吴均诗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('969wx','者','1','zhě','耂','8','','[{"pinyin": "zhě", "defs": [{"meaning": "(《说文》:“别事词也。相当于“这”)。"}, {"meaning": "同本义。", "cites": [{"t": "那边走,者边走,莫厌金杯酒。", "b": "五代·王衍《醉妆词》"}], "words": [{"w": "者回", "t": "这回"}, {"w": "者般", "t": "这般"}, {"w": "者流", "t": "犹言这个流派"}, {"w": "者番", "t": "这番;这次"}, {"w": "者里", "t": "这里"}, {"w": "者个", "t": "这个"}, {"w": "者边", "t": "这边。"}]}, {"meaning": "用在形容词、动词、动词词组或主谓词组之后,组成“者”字结构,用以指代人、事、物。"}, {"meaning": "指代人。", "cites": [{"t": "知人者智,自知者明。", "b": "《老子》"}, {"t": "射者中。(射的射中了目标。这里指宴饮时的一种游戏,射中的照规定的杯数喝酒。)", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "读书者有几。", "b": "清·袁枚《黄生借书说》"}, {"t": "后死者。", "b": "孙文《黄花冈七十二烈士事略序》"}]}, {"meaning": "指代事或物。", "cites": [{"t": "逝者如斯夫!不舍昼夜。", "b": "《论语》"}, {"t": "吾君在前,叱者何也?", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "用在数词之后,指代上文所说的几种人或几件事。", "cites": [{"t": "老而无妻曰鳏,老而无夫曰寡,老而无子曰独,幼而无父曰孤。此四者,天下之穷民而无告者。", "b": "《孟子》"}, {"t": "二者不可得兼。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "用在表时间的名词后面,表示停顿。", "cites": [{"t": "昔者,吾舅死于虎,吾夫又死焉,今吾子又死焉。", "b": "《礼记》"}]}, {"meaning": "作为定语后置的标志。", "cites": [{"t": "马之千里者,一食或尽粟一石。", "b": "唐·韩愈《杂说》"}]}, {"meaning": "用于名词之后,标明语音上的停顿,并引出下文,常表示判断。", "cites": [{"t": "仁者,天下之表也。", "b": "《礼记》"}, {"t": "北山愚公者,年且九十。(者,语气助词,表提顿。)", "b": "《列子·汤问》"}, {"t": "中有鲁人冯三保者,精技击。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "不知忠义者圣贤家法,其气浩然,常留天地间。", "b": "清·全祖望《梅花岭记》"}]}, {"meaning": "用在句末表示语气完毕。", "cites": [{"t": "大人者,不失其赤子之心者也。", "b": "《孟子》"}]}, {"meaning": "用在句末,与疑问词相配合表示疑问。", "cites": [{"t": "飘风不终朝,骤雨不终日,孰为此者?", "b": "《老子》"}]}, {"meaning": "表示祈使语气。", "cites": [{"t": "琴童接下马者!", "b": "《西厢记》"}]}, {"meaning": "表示商榷。", "cites": [{"t": "今汉继大乱之后,若宜少损周之文致,用夏之忠者。", "b": "《汉书》"}]}, {"meaning": "表示比拟,相当于“…的样子”。", "cites": [{"t": "于是公子立自责,似若无所容者。", "b": "《史记》"}]}, {"meaning": "“者也”两个语气词连用,起加强语气的作用,语气重点在最后一个语气词上,“也”在这里强调了肯定的语气。", "cites": [{"t": "舍鱼而取熊掌者也。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "轻狂。", "cites": [{"t": "一时甜如蜜,一时辣如椒,没定准的冤家也,看你者到何时了?", "b": "明·冯梦龙《桂枝儿·者妓》"}]}, {"meaning": "虚假,不老实。", "cites": [{"t": "今以称人之不老实者曰“者”。", "b": "明·顾起元《客座赘语》"}, {"t": "娼妓之家,讳“者、扯、丐、漏、走”五个字。", "b": "《水浒传》"}]}, {"meaning": "(zhū)。众多。", "cites": [{"t": "相总要者官谋士。", "b": "《管子·君臣上》"}, {"t": "天下遇,者监和。", "b": "《管子·五行》"}, {"t": "者生无易由言。", "b": "《盐铁论·散不足》"}]}, {"meaning": "假借,借口。", "cites": [{"t": "他弄个光皮散儿好看,者着求医治树,单单了脱身走路,还顾得了你和我哩!", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('970wx','拍','1','pāi','扌','8','','[{"pinyin": "pāi", "defs": [{"meaning": "(形声。从手,白声。本义:拍击)。"}, {"meaning": "同本义。", "cites": [{"t": "举手拍鞍马。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "拍浮", "t": "游泳"}, {"w": "拍肩", "t": "轻拍别人的肩膀。表示友好或爱护"}, {"w": "拍惜", "t": "轻拍爱怜"}, {"w": "拍张", "t": "伸展肢体拍打"}, {"w": "拍球;拍台拍凳", "t": "拍桌子打板凳;歇斯底里地大发脾气。"}]}, {"meaning": "抚慰。", "cites": [{"t": "妇手拍儿声。", "b": "《虞初新志·秋声诗自序》"}, {"t": "妇拍儿亦渐拍渐止。", "b": ""}], "words": [{"w": "拍惜", "t": "温柔地抚弄"}, {"w": "拍户", "t": "兼卖酒肴的零售酒馆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('971wx','顶','1','dǐng','页','8','','[{"pinyin": "dǐng", "defs": [{"meaning": "(形声。从页(xié),丁声。从“页”,表示与人头有关。本义:人头的最上端)。"}, {"meaning": "同本义。", "cites": [{"t": "顶颠也。", "b": "《说文》"}, {"t": "过涉灭顶。", "b": "《易·大过》"}, {"t": "肩高于顶。", "b": "《庄子·大宗师》。释文:“本作项。”"}, {"t": "生人与死者并踵顶而卧。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "头顶;秃顶;顶光", "t": "即佛或菩萨顶上的圆形光环"}, {"w": "顶珠", "t": "显贵者巾顶上所装饰的大珠"}, {"w": "顶角", "t": "男童头上蓄留的小辫"}, {"w": "顶颡", "t": "“颡”应作“嗓”。顶到喉咙口。形容吃得很饱"}, {"w": "顶老", "t": "头顶;妓女"}, {"w": "顶阳骨 (头盖骨;) 顶瓜皮 (头皮", "t": ""}, {"w": "顶搭子 ", "t": "婴儿留在头顶上的一撮头发"}, {"w": " 顶门上针", "t": "刺中穴道的针砭。比喻打中要害"}, {"w": "顶虫", "t": "古代传说中指生于头颅的虫"}, {"w": "顶疮", "t": "头疮"}, {"w": "顶发", "t": "头发。"}]}, {"meaning": "引申为物的最上部;前部。", "cites": [{"t": "今不称九天之顶,则言黄泉之底,是两末之端议,何可以公论乎?", "b": "《淮南子》"}, {"t": "由屋顶放光明入室。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "山顶有大池,相传以为雁荡。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "灭顶之灾;山顶;桅顶;塔顶;顶上五台山", "t": "孝子在灵前引路"}, {"w": "顶马", "t": "旧时大官出行,骑马为前驱的官吏"}, {"w": "顶针挨住", "t": "一个接一个地等待。"}]}, {"meaning": "顶子。清代官吏依其等级在冠上,缀珠玉宝石金银等以为饰,谓之顶。", "cites": [{"t": "固伦额驸吉服冠,顶用红宝石。", "b": "《清史稿》"}]}, {"meaning": "以头承戴。", "cites": [{"t": "拥渔蓑,顶渔笠,作渔翁。", "b": "宋·汪莘《行香子》"}], "words": [{"w": "头上顶着一包东西;顶盔掼甲", "t": "戴上头盔,披上战甲。指全身武装"}, {"w": "顶了大帽子", "t": "凭了权贵的力量。"}]}, {"meaning": "支撑;承担。", "cites": [{"t": "顶门的,也是他。", "b": "《西游记》"}, {"t": "我昨日把王善保的老婆打了,我还顶着徒罪呢。", "b": "《红楼梦》"}], "words": [{"w": "顶扛", "t": "承当"}, {"w": "顶门主顾", "t": "老主顾"}, {"w": "顶号", "t": "代人受过"}, {"w": "顶岗", "t": "独立担当本职工作。"}]}, {"meaning": "到。", "cites": [{"t": "那船儿须臾顶岸。", "b": "《西游记》"}, {"t": "吃中饭的时候就叫送稿,顶如今还不送来。", "b": "《官场现形记》"}], "words": [{"w": "顶岸", "t": "靠岸,抵岸。"}]}, {"meaning": "旧时指转让或取得企业经营权、房屋或土地租赁权。", "cites": [{"t": "本军因无暇自种,往往顶与民人耕种认租。", "b": "清·林则徐《清理屯田章程折》"}], "words": [{"w": "招顶;顶出去;顶进来;", "t": ""}]}, {"meaning": "拜。", "cites": [{"t": "行者顶谢不尽。", "b": "《西游记》"}, {"t": "二奶奶顶上大老爷,知道大老爷来家了,热孝在身,不好过来拜见。", "b": "《儒林外史》"}], "words": [{"w": "顶上", "t": "拜上"}, {"w": "顶礼慈云", "t": "向佛跪拜致敬"}, {"w": "顶谢", "t": "顶礼致谢"}, {"w": "顶谒", "t": "顶礼谒见。"}]}, {"meaning": "围棋手法的术语。", "cites": [{"t": "顶,撞也。我彼之子,同路而直撞之之谓顶。", "b": "宋·徐铉《围棋义例》"}]}, {"meaning": "相当;抵得上。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('972wx','拆','1','chāi cā','扌','8','','[{"pinyin": "chāi", "defs": [{"meaning": "(形声。从手,斥声。本义:裂开)。"}, {"meaning": "裂开;绽开。", "cites": [{"t": "雷雨作而百果草木皆甲拆。", "b": "《易·解·彖传》"}], "words": [{"w": "拆裂", "t": "分裂;破裂"}, {"w": "拆副", "t": "裂开。"}]}, {"meaning": "开启。", "cites": [{"t": "公拆袄,出珠授之。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "拆信;拆辩", "t": "辩白解释。"}]}, {"meaning": "分散,把合在一起的弄开 暗中破坏;中伤)。"}]}, {"pinyin": "cā", "defs": [{"meaning": "[方言]∶排泄", "words": [{"w": "拆烂污", "t": "[方言]∶做事苟且马虎,不负责任,致使事情糟到难以收拾 "}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('973wx','拎','1','līn','扌','8','','[{"pinyin": "līn", "defs": [{"meaning": "[方言] 提", "cites": [{"t": "把鱼接在手里…拎着尾巴,望汤锅里一掼。", "b": "《儒林外史》"}], "words": [{"w": "拎东西", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('974wx','拥','1','yōng','扌','8','','[{"pinyin": "yōng", "defs": [{"meaning": "(形声。从手,雍声。本义:抱)。"}, {"meaning": "同本义。", "cites": [{"t": "闭门,聚众鸣鼓。众恐,拥柱而歌。", "b": "汉·刘向《列女传》"}], "words": [{"w": "拥树", "t": "拥抱小孩;环抱树木"}, {"w": "拥矢", "t": "古代行投壶礼时,卑者抱矢而投"}, {"w": "拥社", "t": "抱持社主"}, {"w": "拥持", "t": "拥抱"}, {"w": "拥膝", "t": "抱膝。"}]}, {"meaning": "簇拥。", "cites": [{"t": "诸将所拥。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "蜂拥而上。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "乡民蚁拥。", "b": "《广东军务记》"}], "words": [{"w": "前呼后拥;一群人拥着老教授走出来;拥攒", "t": "围拢"}, {"w": "拥舍", "t": "厅堂边的小屋。"}]}, {"meaning": "环抱。", "cites": [{"t": "回首孤城,依约青山拥。", "b": "金·董解元《西厢记诸宫调》"}, {"t": "旗翻光复照神州,虎踞龙蟠拥石头。", "b": "柳亚子《题太平天国战史》"}], "words": [{"w": "拥列", "t": "环抱耸列"}, {"w": "拥炉", "t": "围炉取暖"}, {"w": "拥带", "t": "屏障环绕。"}]}, {"meaning": "持;执持。", "cites": [{"t": "哙即带剑拥盾入军门。", "b": "《史记·项羽本纪》"}, {"t": "拥至尹前。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "拥火以入。", "b": "宋·王安石《游褒禅山记》"}, {"t": "拥豪民马前。", "b": "明·高启《书博鸡者事》"}, {"t": "张黄盖拥纛。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "拥篲", "t": "为迎接贵宾而大扫除"}, {"w": "拥书", "t": "持书;捧读;亦指沉溺于书堆中"}, {"w": "拥主", "t": "挟持君主。"}]}, {"meaning": "聚集。", "cites": [{"t": "今操已拥百万之众。", "b": "《三国志·蜀老》"}], "words": [{"w": "拥兵", "t": "掌握、聚集军队"}, {"w": "拥集", "t": "聚集。"}]}, {"meaning": "拥挤。", "cites": [{"t": "严禁闲人围看,拥挤喧哗。", "b": "《福惠全书·刑名部·人命上》"}], "words": [{"w": "拥户", "t": "挤满一屋子。"}]}, {"meaning": "裹。", "cites": [{"t": "以衾拥覆。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "拥项", "t": "围脖"}, {"w": "拥皋比", "t": "坐拥皋比。任教。皋比:虎皮"}, {"w": "拥衾、拥被", "t": "半卧以被裹护下体"}, {"w": "拥覆", "t": "围裹覆盖。"}]}, {"meaning": "阻塞。", "cites": [{"t": "又拥阏不通。", "b": "《史记·朝鲜列传》"}, {"t": "事不拥隔。", "b": "《三国志·夏侯尚传》"}, {"t": "拥隔我通逵。", "b": "唐·丘鸿渐《愚公移山赋》"}], "words": [{"w": "拥遏", "t": "阻塞,阻拦"}, {"w": "拥道", "t": "堵塞道路"}, {"w": "拥滞", "t": "留滞;阻滞;滞缓。"}]}, {"meaning": "遮盖。", "cites": [{"t": "女子出门,必拥蔽其面。", "b": "《礼记·内则》"}], "words": [{"w": "拥蔽", "t": "遮掩"}, {"w": "拥掩", "t": "遮掩。"}]}, {"meaning": "占有。", "cites": [{"t": "拥雍州之地。", "b": "汉·贾谊《过秦论》"}, {"t": "拥众数万。", "b": "《汉书·李广苏建传》"}, {"t": "拥百万之众。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又如:拥蹲(占有权位);拥制(控制);拥兵(掌握、聚集军队)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('975wx','抵','1','dǐ','扌','8','','[{"pinyin": "dǐ", "defs": [{"meaning": "(形声。从手,氐(dǐ)声。本义:挤,推)。"}, {"meaning": "同本义。", "cites": [{"t": "抵,挤也。", "b": "《说文》"}, {"t": "抵,推也。", "b": "《广雅》"}, {"t": "抵,距也。", "b": "《汉书·梁怀王揖传》注"}], "words": [{"w": "抵掎", "t": "排挤攻击"}, {"w": "抵斥", "t": "排斥"}, {"w": "抵排", "t": "排斥;抵触。"}]}, {"meaning": "抵赖,拒不承认事实。", "cites": [{"t": "延年抵曰。", "b": "《汉书·田延年传》。注:“拒讳也。”"}], "words": [{"w": "抵讳", "t": "抵赖;不认账"}, {"w": "抵谰", "t": "抵赖,拒不承认。"}]}, {"meaning": "抵偿。", "cites": [{"t": "伤人及盗抵罪。", "b": "《史记·高帝纪》"}], "words": [{"w": "抵充", "t": "抵偿充当"}, {"w": "抵补", "t": "抵充补足。"}]}, {"meaning": "抵达。", "cites": [{"t": "抵九原。", "b": "《史记·始皇纪》"}, {"t": "抵营室。", "b": "《史记·天官书》"}, {"t": "抵山谷中。", "b": "《汉书·李陵传》"}, {"t": "乘虚直抵其城。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "抵任", "t": "到任"}, {"w": "抵官", "t": "到职"}, {"w": "日内抵京", "t": ""}]}, {"meaning": "相当。", "cites": [{"t": "烽火连三月,家书抵万金。", "b": "唐·杜甫《春望》"}], "words": [{"w": "价抵连城", "t": ""}]}, {"meaning": "扔,掷。", "cites": [{"t": "抵,掷也。", "b": "《后汉书·献穆曹后纪》注"}], "words": [{"w": "抵掷", "t": "投掷。"}]}, {"meaning": "欺诈。", "cites": [{"t": "抵,欺也。", "b": "《后汉书·刘隆传》注"}], "words": [{"w": "抵换", "t": "掉换。以假换真或以次换好"}, {"w": "抵盗", "t": "从自己家或主人家向外偷东西。"}]}, {"meaning": "用角顶,相触。", "cites": [{"t": "牴,触也。从牛,氐声。字亦作觝。", "b": "《说文》"}, {"t": "三年春,作角抵戏,三百里内皆观。", "b": "《汉书·武帝纪》"}, {"t": "触崖觝隈。", "b": "稽康《琴赋》"}], "words": [{"w": "抵触", "t": "冒犯,顶撞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('976wx','拘','1','jū','扌','8','','[{"pinyin": "jū", "defs": [{"meaning": "(会意。从手,从句,句亦声。本义:拘留,拘禁)。"}, {"meaning": "同本义。", "cites": [{"t": "拘,止也。", "b": "《说文》"}, {"t": "艮为拘随物系之。", "b": "《易·说卦》传"}, {"t": "拘系之乃从。", "b": "《易·随》"}, {"t": "盖文王拘而演。", "b": "《周易》"}, {"t": "狎徐君,拘齐庆封。", "b": "《韩非子·十过》"}], "words": [{"w": "拘证", "t": "缉拿审问"}, {"w": "拘刷", "t": "通缉;拘捕"}, {"w": "拘究", "t": "拘留审察"}, {"w": "拘制", "t": "拘禁,系缚"}, {"w": " 拘责", "t": "拘留责罚"}, {"w": "拘闭", "t": "拘禁,扣押。"}]}, {"meaning": "束缚;限制。", "cites": [{"t": "使人拘而多畏。", "b": "《汉书·司马迁传》"}, {"t": "其流也,埤下裾拘,必循其理。", "b": "《荀子·宥坐》"}, {"t": "井蛙不可以语于海者,拘于虚也。", "b": "《庄子·秋水》"}, {"t": "拘,犹限也。", "b": "《后汉书·王霸传》注"}, {"t": "而不肖者拘焉。", "b": "《淮南子·泛论》。注:“犹检也。”"}], "words": [{"w": "拘紧", "t": "约束、束缚得紧"}, {"w": "拘管", "t": "管教约束"}, {"w": "拘逼", "t": "束缚,强迫"}, {"w": "拘定", "t": "限定"}, {"w": "拘卷", "t": "拘倦。约束,不自在"}, {"w": "拘虚", "t": "受限于居所。"}]}, {"meaning": "拘守;拘泥于。", "cites": [{"t": "不拘于时。", "b": "唐·韩愈《师说》"}, {"t": "拘以定月。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "拘文牵墨", "t": "拘泥于文章教化,或受文章束缚"}, {"w": "拘文牵义", "t": "拘泥于字义、文义。"}]}, {"meaning": "抽搐。", "cites": [{"t": "筋肉拘苛。", "b": "《素问·至真要大论》"}, {"t": "拘挛犹拘束也。", "b": "《后汉书·曹褒传》注"}], "words": [{"w": "拘苛", "t": "抽搐;痉挛"}, {"w": "拘急", "t": "因感受风寒而身体痉挛、抽搐"}, {"w": "拘拳", "t": "拘挛拳曲。引申为受束缚而不自由"}, {"w": "拘缀", "t": "痉挛。"}]}, {"meaning": "钩取,探取。", "cites": [{"t": "不荣通,不醜穷;不拘一穷,是圣人之辩者也。", "b": "《庄子·天地》"}]}, {"meaning": "曲,痉挛;痀偻,曲背。", "cites": [{"t": "夫指之拘也,莫不求伸也。", "b": "《淮南子·泰族》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('977wx','势','1','shì','力','8','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从力,埶(yì)声。本义:权力;权势)。"}, {"meaning": "同本义。", "cites": [{"t": "富者得势益彰,失势则客无所之。", "b": "《史记·货殖列传序》"}, {"t": "有势家朱丹其门,闻瑞至,黝之。", "b": "《明史·海瑞传》"}], "words": [{"w": "势家", "t": "有权势的豪家大族"}, {"w": "失势", "t": "失去权势"}, {"w": "权势", "t": "权柄和势力"}, {"w": "势子", "t": "趋炎附势的人"}, {"w": "势利", "t": "权势和利益"}, {"w": "势任", "t": "掌握权势的重要职位"}, {"w": "势利场", "t": "争权夺利的地方。"}]}, {"meaning": "力量;威力。", "cites": [{"t": "夫六国与秦皆诸侯,其势弱于秦。", "b": "宋·苏洵《六国论》"}, {"t": "如此则荆吴之势强,鼎足之形成矣。", "b": "《资治通鉴》"}], "words": [{"w": "声势", "t": "声威和气势"}, {"w": "势耀", "t": "势力威望"}, {"w": "势倾人主", "t": "威风势力压倒了皇帝"}, {"w": "势派", "t": "气势;气派。"}]}, {"meaning": "形势;情势。", "cites": [{"t": "仁义不施,攻守之势异也。", "b": "汉·贾谊《过秦论》"}, {"t": "今两虎共斗,其势不俱生。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "势促", "t": "形势所迫"}, {"w": "势面", "t": "世面"}, {"w": "势穷力屈", "t": "形势窘迫,力量衰竭"}, {"w": "大势所趋;守势;势胜", "t": "形势优越。"}]}, {"meaning": "姿态。", "cites": [{"t": "因摸地上刑械作投击势。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "装腔作势", "t": ""}]}, {"meaning": "形状;样式;架式。", "cites": [{"t": "罔不因势象形各具情态。", "b": "《虞初新志·魏学洢·核舟记》"}]}, {"meaning": "自然界或物体的形貌。", "cites": [{"t": "其岸势犬牙差互,不可知其源。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "人及动物的睾丸。", "cites": [{"t": "淫者割其势。", "b": "《晋书·刑法志》"}], "words": [{"w": "势不知有无", "t": "忘乎所以;由于过度兴奋而忘记了一切。势:指男子生殖器。"}]}, {"meaning": "物理学名词 。亦称“位”。根据它可以算出在某范围内任一点的强度或速度的不同函数中的任一函数。"}, {"meaning": "势头;趋势;时机。", "cites": [{"t": "三保见敌势可乘,急挥帜。", "b": "《清稗类钞·战事类》"}, {"t": "然羽非有尺寸,乘势起陇庙之中。", "b": "《史记·项羽纪赞》"}], "words": [{"w": "势如破竹", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('978wx','抱','1','bào','扌','8','','[{"pinyin": "bào", "defs": [{"meaning": "(形声。从手,包声。本义:用手臂围住)。"}, {"meaning": "同本义。", "cites": [{"t": "公然抱茅入竹去。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "遂相与一抱而别。", "b": "清·梁启超《谭嗣同传》"}, {"t": "犹抱薪救火。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "抱石", "t": "怀石。指投水而死"}, {"w": "抱嫁", "t": "苏州风俗。女子出嫁时由阿舅抱上花轿"}, {"w": "抱冰", "t": "比喻刻苦自励。"}]}, {"meaning": "捧着。", "cites": [{"t": "和乃抱其璞而哭于楚山之下。", "b": "《韩非子·和氏》"}], "words": [{"w": "抱璞", "t": "春秋楚人卞和发现一块玉璞,献给楚灰王、武王,两次都被认为是顽石,并刖去双足。后楚文王即位,卞和又抱璞哭于荆山之下,文王命人剖璞,果系美玉,称和氏璧。"}]}, {"meaning": "环绕。", "cites": [{"t": "清江一曲抱村流。", "b": "唐·杜甫《江村》"}, {"t": "陵峦抱江城。", "b": "李白《见会公谈陵阳山水》"}], "words": [{"w": "清溪抱村", "t": ""}]}, {"meaning": "怀藏,心里存有。", "cites": [{"t": "大师,抱天时,与大师同车。", "b": "《周礼·大史》"}, {"t": "然则抱此无涯之憾。", "b": "清·袁枚《祭妹文》"}, {"t": "至于长者之抱才而困。", "b": "明·宗臣《报刘一丈先生书》"}], "words": [{"w": "抱学", "t": "心怀学问"}, {"w": "抱敌对态度;抱才", "t": "怀才"}, {"w": "抱志", "t": "胸怀大志"}, {"w": "抱思", "t": "怀念"}, {"w": "抱恩", "t": "怀念恩惠。"}]}, {"meaning": "保护,爱护。", "cites": [{"t": "全汝形,抱汝生,无使汝思虑营营。", "b": "《庄子·庚桑楚》"}]}, {"meaning": "生育。", "cites": [{"t": "亦既抱子。", "b": "《诗·大雅·抑》"}], "words": [{"w": "抱出笼", "t": "本指刚出笼的小鸡,喻不老练、不在行的人"}, {"w": "抱子", "t": "生子。"}]}, {"meaning": "孵。", "cites": [{"t": "北燕朝鲜洌水之间,谓伏鸡曰抱其卵。", "b": "《方言》"}], "words": [{"w": "抱小鸡儿;抱空窝", "t": "老母鸡孵没蛋的窝。"}]}, {"meaning": "怀,胸怀。", "cites": [{"t": "念离(离别)独伤抱。", "b": "唐·韦应物《寒食日寄诸弟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('979wx','拄','1','zhǔ','扌','8','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(形声。从手,主声。本义:支撑)。"}, {"meaning": "同本义。", "cites": [{"t": "修剑拄颐。", "b": "《战国策·齐策六》"}], "words": [{"w": "拄颊", "t": "以手支颊"}, {"w": "拄颐", "t": "顶到面颊。形容剑长"}, {"w": "拄撑", "t": "支撑。"}]}, {"meaning": "执持;靠。", "cites": [{"t": "宝玉听说,只得拄了一支杖,趿着鞋,走出院外。", "b": "《红楼梦》"}], "words": [{"w": "拄杖", "t": "执持;支撑着拐杖"}, {"w": "拄墙", "t": "比喻依靠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('980wx','垃','1','lā','土','8','','[{"pinyin": "lā", "defs": [{"meaning": "脏土或抛扔的破烂东西，科学处理～圾。〈喻〉旧时遗留下来的反动腐朽的事物，腐朽的～圾。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('981wx','拉','1','lā lá lǎ','扌','8','','[{"pinyin": "lā", "defs": [{"meaning": "(形声。从手,立声。本义:摧折,折断)。"}, {"meaning": "同本义。", "cites": [{"t": "拉,摧也。", "b": "《说文》"}, {"t": "使力士彭生拉杀鲁桓公。", "b": "《史记·齐世家》"}, {"t": "拉捭摧藏。", "b": "《文选·左思·吴都赋》"}, {"t": "拉干而杀之。", "b": "《公羊传·庄公元年》"}, {"t": "范雎拉胁折齿于魏。", "b": "《汉书·邹阳传》"}], "words": [{"w": "摧枯拉朽", "t": "摧折枯枝朽木。比喻极容易办到"}, {"w": "拉杂", "t": "折断弄碎。后用以指杂乱而没有条理"}, {"w": "拉齿", "t": "折齿"}, {"w": "拉枯", "t": "摧毁枯朽之物。比喻轻而易举。"}]}, {"meaning": "牵;引;扯;拽。", "cites": [{"t": "谁能拉花住,争换得春回。", "b": "刘禹锡《花下醉中联句》"}], "words": [{"w": "拉手", "t": "满人久别见面的一种礼节"}, {"w": "拉拉", "t": "趿拉,即将鞋后帮踩在脚后跟下面"}, {"w": "拉人", "t": "拉夫"}, {"w": "拉火线", "t": "手榴弹等引爆的拉线。"}]}, {"meaning": "牵连。", "cites": [{"t": "此后的小报,每当攻击胡风时,便往往不免拉上我。", "b": "鲁迅《且介亭杂文末编》"}]}]}, {"pinyin": "lá", "defs": []}, {"pinyin": "lǎ", "defs": [{"meaning": "", "words": [{"w": "那一溜是炼钢厂,这半拉是炼铁厂", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('982wx','拦','1','lán','扌','8','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从手,阑(lán)声。本义:阻挡;遮拦)。"}, {"meaning": "同本义。", "cites": [{"t": "拦,遮拦也。", "b": "《玉篇》"}, {"t": "牵衣顿足拦道哭,哭 声直上干云霄。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "拦关", "t": "形容两臂力大无穷;又指粗壮的手臂"}, {"w": "拦护", "t": "阻拦,保护"}, {"w": "拦门", "t": "宋时娶妻,回至男家门时,乐人等拦在门外索要钱物"}, {"w": "拦驾", "t": "遮拦皇帝的銮驾。"}]}, {"meaning": "表示方式、方向,相当于“当”、“对着”。", "cites": [{"t": "倒像背地里有人把我拦头一棍,疼的眼睛前头漆黑。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('983wx','幸','1','xìng','干','8','','[{"pinyin": "xìng", "defs": [{"meaning": "侥幸。", "cites": [{"t": "非分而得谓之幸。", "b": "《小尔雅》"}, {"t": "朝无幸位。", "b": "《荀子·富国》。注:“无德而禄谓之幸位。”"}, {"t": "小人见人之厄则幸之。", "b": "《公羊传·宣公十五年》。注:“侥倖也。”"}, {"t": "幸得脱矣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "幸皆杀之。", "b": "唐·柳宗元《童区寄传》"}, {"t": "朕自得丞相,幸成帝业。", "b": "《三国演义》"}], "words": [{"w": "幸心", "t": "侥幸心理"}, {"w": "幸生", "t": "侥幸偷生"}, {"w": "幸民", "t": "侥幸于万一之民"}, {"w": "幸位", "t": "侥幸得位"}, {"w": "幸得", "t": "幸而"}, {"w": "幸诡", "t": "侥幸和诡诈"}, {"w": "幸赏", "t": "侥幸得赏。"}]}, {"meaning": "幸亏。", "cites": [{"t": "幸大雪踰岭。", "b": "唐·柳宗元《柳河东集》"}, {"t": "幸诚门未有烧。", "b": "《广东军务记》"}, {"t": "幸彼苍默佦", "b": ""}], "words": [{"w": "幸为", "t": "幸而"}, {"w": "幸然", "t": "幸亏"}, {"w": "幸赖", "t": "幸亏依靠"}, {"w": "幸得", "t": "幸亏"}, {"w": "幸偶", "t": "幸运而偶然遇合。"}]}, {"meaning": "表敬,副词,表明对方的行为使自己感到幸运。", "cites": [{"t": "亦幸赦臣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "乃幸见取。", "b": "唐·柳宗元《柳河东集》"}, {"t": "幸君子书叙。", "b": "唐·李朝威《柳毅传》"}, {"t": "官入幸顾我。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "幸叨", "t": "有幸得到他人的好处"}, {"w": "幸蒙", "t": "有幸承蒙"}, {"w": "请不吝赐教为幸", "t": ""}]}, {"meaning": "使…欢乐、愉快或欣喜;庆幸。", "cites": [{"t": "愿大王以幸天下。", "b": "《汉书·高帝纪下》"}]}, {"meaning": "宠爱。", "cites": [{"t": "幸于赵王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "你瞧瞧,把他幸的这个样儿,我劝你收着些儿好。", "b": "《红楼梦》"}], "words": [{"w": "幸私", "t": "古谓帝王对人宠爱"}, {"w": "幸昵", "t": "宠爱亲近"}, {"w": "幸待", "t": "宠爱优待"}, {"w": "幸媚", "t": "亲近宠幸"}, {"w": "幸近", "t": "宠幸亲近"}, {"w": "幸嬖", "t": "宠爱狎昵。"}]}, {"meaning": "感受到怜悯之心。", "cites": [{"t": "王必幸臣与臣之母,愿先生之勿患也。", "b": "《吕氏春秋·至忠》"}]}, {"meaning": "希望。", "cites": [{"t": "幸可广问讯。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "吾子幸观。", "b": "唐·柳宗元《柳河东集》"}, {"t": "幸蒙其赏。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "幸宁吾心。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "幸为", "t": "希望"}, {"w": "幸存照鉴", "t": "希望留存查照"}, {"w": "幸来", "t": "希望前来"}, {"w": "幸愿", "t": "希望"}, {"w": "幸勉", "t": "望其勉力"}, {"w": "幸望,幸翼", "t": "希望。"}]}, {"meaning": "旧指皇帝亲临,后也泛指皇族亲临。", "cites": [{"t": "会幸苑中。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "忽然有个诏书下来,说御驾亲幸泰山,要修汉武帝封禅的故事。", "b": "《醒世恒言》"}], "words": [{"w": "幸顾", "t": "帝王临幸垂顾"}, {"w": "幸听", "t": "皇帝亲临听讲"}, {"w": "幸学", "t": "皇帝巡视学校"}, {"w": "幸御", "t": "帝王巡游时驻跸。"}]}, {"meaning": "特指帝王与女子同房。", "cites": [{"t": "妇女无所幸。", "b": "《史记·项羽本纪》"}], "words": [{"w": "得幸;御幸;王因幸之", "t": ""}]}, {"meaning": "遇。", "cites": [{"t": "二年冬,幸大雪逾岭被南越中数州。", "b": "柳宗元《答韦中立论师道书》"}]}, {"meaning": "使…活命。", "cites": [{"t": "汝天下之国士也,幸汝以成而名。", "b": "《吕氏春秋》"}]}, {"meaning": "幸福。", "cites": [{"t": "大丈夫得死于疆场者,幸也,吾何恨焉?", "b": "《三国演义》"}]}, {"meaning": "受宠的人。", "cites": [{"t": "妾媵盈宫,非无爱幸也。", "b": "《申鉴》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('984wx','拌','1','bàn pān pàn','扌','8','','[{"pinyin": "bàn", "defs": [{"meaning": "搅和;调匀。", "cites": [{"t": "拿香油一收,外加糟油一拌。", "b": "《红楼梦》"}], "words": [{"w": "用水拌面粉;拌种;拌草;拌匀", "t": "搅拌使均匀。"}]}]}, {"pinyin": "pān", "defs": [{"meaning": "耗费。", "cites": [{"t": "短檐破屋,皆拌数十年之力;晓风夜雨,沉冥其中。", "b": "清·黄宗羲《张元岵先生墓志铭》"}]}, {"meaning": "摧残。", "cites": [{"t": "夜间猛雨拌花尽,寒恋重衾觉梦多。", "b": "唐·温庭筠《春日偶作》"}]}, {"meaning": "分开", "cites": [{"t": "今以木击木则拌。", "b": "《吕氏春秋》"}]}]}, {"pinyin": "pàn", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('985wx','拧','1','níng nǐng nìng','扌','8','','[{"pinyin": "níng", "defs": [{"meaning": "(形声。从手,宁声。本义:用拇指和另外一两个指头扭住皮肉用力转动)。"}]}, {"pinyin": "nǐng", "defs": [{"meaning": "用力扭转。", "cites": [{"t": "说罢,三步两步,跑到那马车跟前,伸手把机关一拧,用力一拉,开了门。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "拧转", "t": "扭转,转过"}, {"w": "水笼头拧不开;拧螺旋", "t": ""}]}, {"meaning": "别扭;意见相互不一致。", "cites": [{"t": "他两个越说越拧,脸上的笑影儿都没有了。", "b": "袁静《新儿女英雄传》"}]}, {"meaning": "颠倒,不好,荒谬,不正确。", "cites": [{"t": "张姑娘才觉得这句话是说拧了,忍着笑扭过头去。", "b": "《儿女英雄传》"}, {"t": "你可别认成…作成圈套儿来讪你的,那可就更拧了。", "b": "《儿女英雄传》"}], "words": [{"w": "他想说“小题大做”,说拧了,说成“大题小做”", "t": ""}]}]}, {"pinyin": "nìng", "defs": [{"meaning": "固执,执拗。", "cites": [{"t": "王格这孩子真个的怎么这么拧啊!。", "b": "《儿女英雄传》"}], "words": [{"w": "他脾气拧得很", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('986wx','拂','1','fú','扌','8','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从手。弗声。本义:拂拭;掸除)。"}, {"meaning": "同本义。", "cites": [{"t": "拂,过击也。", "b": "《说文》。按,随击随过,犹拍也。”"}, {"t": "拂,去也。", "b": "《广雅》"}, {"t": "授弓拂弓。", "b": "《仪礼·大射仪》。注:“去尘也。”"}, {"t": "和弓击摩。", "b": "《考工记·弓人》。注:“拂之摩之。”"}, {"t": "商祝拂柩。", "b": "《仪礼·既文礼》"}, {"t": "主人拂几。", "b": "《仪礼》"}, {"t": "以手拂之,其印自落。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "拂掉", "t": "拂杓。拂拭;扫除"}, {"w": "拂帚", "t": "拂尘"}, {"w": "拂子", "t": "拂尘"}, {"w": "拂须", "t": "揩拭胡须"}, {"w": "拂去桌上的尘土", "t": ""}]}, {"meaning": "击。", "cites": [{"t": "拂颐,贞凶。", "b": "《易·颐》"}, {"t": "神武据鞍未动,金以鞭拂马,神武乃还。", "b": "《北史》"}]}, {"meaning": "违背;逆。", "cites": [{"t": "行拂乱其所为,所以动心忍性,曾益其所不能。", "b": "《孟子·告子下》"}, {"t": "而无拂吾虑。", "b": "《国语·吴语》"}, {"t": "是谓拂人之性。", "b": "《礼记·大学》"}, {"t": "拂于耳。", "b": "《汉书·东方朔传》"}], "words": [{"w": "拂戾", "t": "违逆,不和顺"}, {"w": "拂心", "t": "违逆其心意"}, {"w": "拂经", "t": "违背常理"}, {"w": "拂乱", "t": "违反其意愿以乱之"}, {"w": "拂世", "t": "违背世情。"}]}, {"meaning": "掠过或轻轻擦过。", "cites": [{"t": "长袂拂面。", "b": "《楚辞·大招》"}, {"t": "梧桐杨柳拂金井。", "b": "唐·李白《扶风豪士歌》"}], "words": [{"w": "春风拂面;拂掠", "t": "轻轻掠过。"}]}, {"meaning": "甩动;抖动。", "cites": [{"t": "明日便当拂衣而去。", "b": "《后汉书》"}], "words": [{"w": "拂袖", "t": "甩动衣袖"}, {"w": "拂衣", "t": "拂袖;振衣,表示兴奋。"}]}, {"meaning": "除去。", "cites": [{"t": "拂其恶。", "b": "《太玄经·从》。注:“去也。”"}], "words": [{"w": "拂暑", "t": "拂除暑气"}, {"w": "拂彻", "t": "消除,除去"}, {"w": "拂除", "t": "祓除。"}]}, {"meaning": "从…中拔出来。", "cites": [{"t": "不然拂剑起,沙漠收奇勋。", "b": "唐·李白《赠何七判官昌浩》"}]}, {"meaning": "拂拭的用具。", "cites": [{"t": "一妓有殊色,执红拂,立于前。", "b": "前蜀·杜光庭《虬髯客传》"}], "words": [{"w": "拂尘", "t": "拂子,掸尘土或驱赶蚊蝇的用具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('987wx','拙','1','zhuō','扌','8','','[{"pinyin": "zhuō", "defs": [{"meaning": "(形声。从手,出声。本义:笨拙,不灵活)。"}, {"meaning": "同本义。", "cites": [{"t": "拙,不巧也。", "b": "《说文》"}, {"t": "拙,钝也。", "b": "《广雅》"}, {"t": "不利于人谓之拙。", "b": "《墨子·贵义》"}, {"t": "予亦拙谋。", "b": "《书·盘庚》"}, {"t": "理弱而媒拙兮。", "b": "《离骚》"}, {"t": "大直若屈,大巧若拙,大辩若讷。", "b": "《老子》四十五章"}, {"t": "每动作而受嗤,言发口而违理者,拙人也。", "b": "《抱朴子》"}, {"t": "拙者不足。", "b": "《史记·货殖列传》"}, {"t": "理弱而媒兮,恐导言之不固。", "b": "《楚辞·离骚》"}, {"t": "汉家青史上,计拙是和亲。", "b": "唐·戎昱《咏史》"}, {"t": "姐妹们虽拙,大家一处作伴,也可解些烦闷。", "b": "《红楼梦》"}], "words": [{"w": "性拙", "t": "生性笨拙"}, {"w": "拙行", "t": "外行;不在行"}, {"w": "拙诚", "t": "笨拙而真诚"}, {"w": "拙鸠", "t": "相传鸠鸟性笨拙,不善营巢,常占据他鸟的巢而栖息"}, {"w": "拙薄", "t": "拙劣浅薄"}, {"w": "拙守", "t": "安于愚拙,不取巧。"}]}, {"meaning": "我的 。自谦之辞。", "cites": [{"t": "拙妻好乘鸾,娇女爱飞鹤。", "b": "李白《题嵩山逸人元丹邱山居》"}, {"t": "这妇人便插口道:“这个叔叔,便是拙夫新认识的兄弟。”", "b": "《水浒全传》"}], "words": [{"w": "拙子", "t": "对人称自己的儿子"}, {"w": "拙分", "t": "谦称自己的名分、职分"}, {"w": "拙作", "t": "称自己作品的谦词"}, {"w": "拙室", "t": "拙妇。称自己妻子的谦词"}, {"w": "拙恶", "t": "谦称自己的作品。"}]}, {"meaning": "粗劣。", "cites": [{"t": "黄金即为侈,白石又太拙。", "b": "陆龟蒙《酒樽》"}], "words": [{"w": "拙易", "t": "粗陋肤浅"}, {"w": "拙野", "t": "粗糙"}, {"w": "拙率", "t": "粗率"}, {"w": "拙浅", "t": "粗浅,浅陋"}, {"w": "拙恶", "t": "粗劣。"}]}, {"meaning": "倒霉。", "cites": [{"t": "缅思桃源内,益叹身世拙。", "b": "杜甫《北征》"}, {"t": "中了一个甚么举人,就得了这个拙病。", "b": "《儒林外史》"}], "words": [{"w": "运拙", "t": "命运不济;命该倒霉。"}]}, {"meaning": "质朴无华。", "cites": [{"t": "巧诈不如拙诚。", "b": "《韩非子》"}], "words": [{"w": "拙木", "t": "质朴"}, {"w": "拙句", "t": "自然质朴的诗句。"}]}, {"meaning": "不善于。", "cites": [{"t": "拙讷谢浮名。", "b": "谢灵运《初去郡》"}], "words": [{"w": "拙生", "t": "拙于生计,不善谋生"}, {"w": "拙政", "t": "拙于为政。亦用为谦词"}, {"w": "拙宦", "t": "不善于为官,仕途不顺。多用以自谦"}, {"w": "拙讷", "t": "才疏口拙,不善应对。"}]}, {"meaning": "穷尽;用尽。", "cites": [{"t": "计拙无衣食,途穷仗友生。", "b": "杜甫《客夜》"}]}, {"meaning": "屈抑;粗暴对待。", "cites": [{"t": "径省其说,则以为不智而拙之。", "b": "《韩非子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('988wx','招','1','zhāo','扌','8','','[{"pinyin": "zhāo", "defs": [{"meaning": "(会意。从手。召声,呼唤。本义:打手势叫人来)。"}, {"meaning": "同本义。", "cites": [{"t": "招,手呼也。", "b": "《说文》"}, {"t": "招者,召也。以手曰招,以言曰召。", "b": "《楚辞·招魂序》"}, {"t": "招樊哙出。", "b": "《史记·项羽本纪》"}, {"t": "登高而招,臂非加长也,而见者远。", "b": "《荀子·劝学》"}], "words": [{"w": "招迎", "t": "招呼使接待;招引迎接"}, {"w": "招求", "t": "招引导求"}, {"w": "招招", "t": "招呼的样子"}, {"w": "招诱", "t": "招唤劝导"}, {"w": "招护", "t": "招呼,关照"}, {"w": "招应", "t": "招呼、理睬。"}]}, {"meaning": "招收;招募。", "cites": [{"t": "上招贤良。", "b": "《汉书·晁错传》"}], "words": [{"w": "招拔", "t": "召来并加以擢用"}, {"w": "招用", "t": "招收使用"}, {"w": "招军", "t": "招募士兵。"}]}, {"meaning": "邀请。", "cites": [{"t": "招前日宾客。", "b": "清·侯方域《壮悔堂文集》"}], "words": [{"w": "招宴", "t": "邀请参加酒宴"}, {"w": "招要", "t": "招邀。邀请"}, {"w": "招饮", "t": "招人宴饮。"}]}, {"meaning": "招致;招惹。", "cites": [{"t": "满招损,谦受益。", "b": "宋·欧阳修《伶官传》引《书·大禹谟》"}, {"t": "招而不至。", "b": "汉·贾谊《论积贮疏》"}, {"t": "招越蜀呔怪。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "招风惹雨", "t": "招惹是非"}, {"w": "招风揽火", "t": "招惹是非"}, {"w": "招尤", "t": "招致他人的怪罪或怨恨"}, {"w": "招召", "t": "招来祸福"}, {"w": "招振", "t": "招致擢用。"}]}, {"meaning": "招供,供认。", "cites": [{"t": "非法拷打,何罪不招!", "b": "宋·胡太初《昼帘绪论》"}], "words": [{"w": "招状", "t": "供状"}, {"w": "招款", "t": "招状"}, {"w": "招稿", "t": "招供的文稿"}, {"w": "招承", "t": "招认;认罪或认错。"}]}, {"meaning": "逗引。", "cites": [{"t": "今夫赵女郑姬,设形容,…目挑心招,出不远千里,不择老少者,奔富厚也。", "b": "《史记》"}], "words": [{"w": "招蜂引蝶", "t": "比喻逗引异性。"}]}, {"meaning": "招抚;招安。", "cites": [{"t": "仕途捷径无过贼,上将奇谋只是招。", "b": "宋·庄季裕《鸡肋篇》"}], "words": [{"w": "招讨", "t": "招抚征讨"}, {"w": "招慰", "t": "招抚"}, {"w": "招怀", "t": "招抚。"}]}, {"meaning": "摇动;挥舞。", "cites": [{"t": "船上把青旗只一招,芦苇里棹出一只小船。", "b": "《水浒全传》"}], "words": [{"w": "招飐", "t": "招展。"}]}, {"meaning": "招赘;招婿。", "cites": [{"t": "他今日倒赔缘房,招你为婿。", "b": "元·乔吉《金钱记》"}, {"t": "不争你要来我家,我孩儿要招个做杂剧的。", "b": "宋·无名氏《错立身》"}], "words": [{"w": "不招", "t": "不当上门女婿"}, {"w": "招嫁", "t": "招赘与出嫁。"}]}, {"meaning": "(jiǎo)。举起。", "cites": [{"t": "自虞氏招仁义以挠天下也。", "b": "《庄子·骈拇》"}, {"t": "操其觚招其末", "b": "《淮南子·主术》。注:“招,举也。”"}, {"t": "招八州而朝同列。", "b": "《汉书·陈胜项籍传赞》"}]}, {"meaning": "靶子。", "cites": [{"t": "万人操弓,共射其一招,招无不中。", "b": "《吕氏春秋·本生》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('989wx','坡','1','pō','土','8','','[{"pinyin": "pō", "defs": [{"meaning": "(形声。从土,皮声。本义:山地倾斜的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "坡,陂也。", "b": "《说文》"}, {"t": "隰则有泮。", "b": "《诗·卫风·氓》。传:“泮,坡也。”"}], "words": [{"w": "山坡;上下坡;坡土", "t": "山坡地"}, {"w": "坡陀", "t": "山势起伏的样子;不平坦;山;山坡"}, {"w": "坡坂", "t": "倾斜的山坡"}, {"w": "坡梁", "t": "方言。土冈,山冈"}, {"w": "坡垅", "t": "丘陵"}, {"w": "坡撇", "t": "鸨儿。开妓院的女老板。"}]}, {"meaning": "平原;原野。", "cites": [{"t": "言阜者土山也,小堆曰阜,平原曰坡,坡高曰陇。", "b": "宋·韩拙《山水纯》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('990wx','披','1','pī','扌','8','','[{"pinyin": "pī", "defs": [{"meaning": "(形声。从手,皮声。本义:引柩帛) 古夹具。即用在柩车两旁牵挽的帛。", "cites": [{"t": "披,从旁持曰披。", "b": "《说文》"}, {"t": "设披周也。", "b": "《礼记·檀弓》。注:“披,柩行夹引棺者。”"}, {"t": "执披。", "b": "《周礼·司士》。注:“柩车行所以披持棺者,有纽以结之,谓之戴。”"}, {"t": "执披者旁四人。", "b": "《仪礼·士丧礼》"}, {"t": "设披。", "b": "《仪礼·既夕礼》"}]}, {"meaning": "分开;裂开。", "cites": [{"t": "而披其地。", "b": "《左传·成公十八年》。注:“犹分也。”"}, {"t": "又披其邑。", "b": "《左传·昭公五年》。注:“析也。”"}, {"t": "不折必披。", "b": "《史记·魏其安侯传》。正义:分析也。”"}, {"t": "柳条将舒未舒,柔梢披风。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "竹竿披了;披磔", "t": "开割"}, {"w": "披砍", "t": "撇开"}, {"w": "披榛", "t": "砍去丛生之草木。"}]}, {"meaning": "打开;开发。", "cites": [{"t": "披,张也。", "b": "《广雅》"}, {"t": "披重攘以诞兮。", "b": "嵇良《琴赋》。注:“开也。”"}, {"t": "哙遂入,披帷西向立。", "b": "《史记·项羽本纪》"}], "words": [{"w": "披卷", "t": "开卷阅读"}, {"w": "披帙", "t": "打开卷帙"}, {"w": "披对", "t": "开诚相对"}, {"w": "披肝胆", "t": "表示以真诚相见"}, {"w": "披展", "t": "披诚展拜,拜见"}, {"w": "披情", "t": "剖露情怀"}, {"w": "披示", "t": "揭示,显示"}, {"w": "披决", "t": "劈剖"}, {"w": "披荆", "t": "比喻在前进道路上或创业过程中扫除障碍,克服困难。"}]}, {"meaning": "拨开。", "cites": [{"t": "蹑迹披求,见有虫伏棘根。", "b": "《聊斋志异·促织》"}], "words": [{"w": "披究", "t": "拨开观赏"}, {"w": "披草", "t": "拨开荒草"}, {"w": "披抉", "t": "拨开挑剔"}, {"w": "披视", "t": "拨开来看"}, {"w": "披云雾", "t": "拨开云雾得见青天"}, {"w": "披拨", "t": "犹推开。"}]}, {"meaning": "覆盖或搭衣于肩。", "cites": [{"t": "孰居无事而披拂是。", "b": "《庄子·天运》。释文:“风貌。”"}, {"t": "景从云合,而见一人,披紫衣,执青玉。", "b": "唐·李朝威《柳毅传》"}, {"t": "夜披衣坐。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "披甲", "t": "穿着铠甲"}, {"w": "披帛", "t": "妇女服饰名。相当于近代婚嫁庆功的披红"}, {"w": "披肩", "t": "覆于肩上;旧时妇女的服饰"}, {"w": "披红", "t": "红帛披身"}, {"w": "披毛戴角", "t": "指变牛变马"}, {"w": "披发跣足", "t": "披散头发,赤着脚"}, {"w": "披坚持锐", "t": "穿上坚固的铠甲,拿起锋利的武器"}, {"w": "披房", "t": "披屋。正屋后的平房"}, {"w": "披子", "t": "即披屋"}, {"w": "披檐", "t": "正屋屋檐下搭建的附属建筑物"}, {"w": "披厦", "t": "一种房屋结构,房檐突出,檐下可避风雨。"}]}, {"meaning": "翻开;翻阅。", "cites": [{"t": "手不停披于百家之编。", "b": "唐·韩愈《进学解》"}], "words": [{"w": "披味", "t": "翻阅玩味"}, {"w": "披书", "t": "翻阅文书"}, {"w": "披图", "t": "展阅图籍、图画等"}, {"w": "披诵", "t": "展卷诵读"}, {"w": "披簿", "t": "翻阅簿籍"}, {"w": "披检", "t": "翻阅查检"}, {"w": "披涉", "t": "翻阅涉猎"}, {"w": "披索", "t": "翻阅求索"}, {"w": "披书", "t": "开卷,读书"}, {"w": "披省", "t": "披览"}, {"w": "披文", "t": "披阅文章"}, {"w": "披核", "t": "披阅考校"}, {"w": "披绎", "t": "披阅寻绎"}, {"w": "披寻", "t": "披阅寻讨"}, {"w": "披较", "t": "披阅考较"}, {"w": "披校", "t": "批校。"}]}, {"meaning": "披靡。", "cites": [{"t": "汉军皆披靡。", "b": "《史记·项羽本纪》。正义:“言精体低垂。”"}], "words": [{"w": "披却", "t": "犹披靡"}, {"w": "披退", "t": "披靡退却"}, {"w": "披易", "t": "披靡辟易"}, {"w": "披荡", "t": "犹披靡"}, {"w": "披攘", "t": "披靡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('991wx','拨','1','bō','扌','8','','[{"pinyin": "bō", "defs": [{"meaning": "(形声。从手,发声。本义:治理)。"}, {"meaning": "同本义。", "cites": [{"t": "撥,治也。", "b": "《说文》"}, {"t": "玄王桓拨。", "b": "《诗·商颂·长发》"}, {"t": "拨乱世,反诸正,莫近诸《春秋》。", "b": "《公羊传·哀公十四年》"}], "words": [{"w": "拨烦", "t": "治理烦杂的事务"}, {"w": "拨乱", "t": "治理乱政;平定祸乱"}, {"w": "拨畦", "t": "整治田畦"}, {"w": "拨通", "t": "开导;启发。"}]}, {"meaning": "拨动东西;分开;拨开。", "cites": [{"t": "香炉风雪拨帘看。", "b": "唐·白居易《香炉峰下新卜山居草堂初成偶题东壁重题》"}, {"t": "乃奋臂以指拨眦。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "试以猪鬣撩拨虫须,仍不动。", "b": "《聊斋志异·促织》"}], "words": [{"w": "拨风", "t": "像拨开大风的样子,速度异常之快"}, {"w": "拨火儿", "t": "拨动火种使火烧得旺,比喻挑拨"}, {"w": "拨置", "t": "挑拨"}, {"w": "拨嘴", "t": "拌口舌"}, {"w": "拨正", "t": "拨动使正;曲与直。"}]}, {"meaning": "调拨。", "cites": [{"t": "吾与汝二万五千精兵,再拨一员上将,相助你去。", "b": "《三国演义》"}], "words": [{"w": "拨款;拨降", "t": "发下"}, {"w": "拨发", "t": "调拨发运"}, {"w": "拨换", "t": "调换"}, {"w": "拨兑", "t": "调拨;掉换。"}]}, {"meaning": "废弃。", "cites": [{"t": "秦拨古文。", "b": "《史记·太史公自序》"}], "words": [{"w": "拨置", "t": "废置;挑拨"}, {"w": "拨弃", "t": "抛开,丢弃"}, {"w": "拨捐", "t": "犹泼弃,倾弃。"}]}, {"meaning": "排除。", "cites": [{"t": "虽然如此,早晚定拨冗而来。", "b": "毕魏《三报恩》"}]}, {"meaning": "断绝,折。", "cites": [{"t": "枝叶未有害,本实先拨。", "b": "《诗·大雅·荡》"}]}, {"meaning": "弹拨。", "cites": [{"t": "转轴拨弦三两声,未成曲调先有情。", "b": "白居易《琵琶行》"}]}, {"meaning": "碰撞;撞击。", "cites": [{"t": "将军金甲夜不脱,半夜军行戈相拨。", "b": "岑参《走马川行奉送封大夫出师西征》"}]}, {"meaning": "拨子。", "cites": [{"t": "曲终收拨当心划,四弦一声如裂帛。", "b": "唐·白居易《琵琶行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('992wx','择','1','zé zhái','扌','8','','[{"pinyin": "zé", "defs": [{"meaning": "(形声。从手,睪(yì)声。本义:选取,挑选)。"}, {"meaning": "同本义。", "cites": [{"t": "择,柬选也。", "b": "《说文》"}, {"t": "与恶剑无择。", "b": "《吕氏春秋·简选》。注:“别也。”"}, {"t": "而错择名利。", "b": "《淮南子·俶真》。注:“取也。”"}, {"t": "申此择辞。", "b": "《汉书·韦元成传》。注:“谓创艾也。”"}, {"t": "择师而教之。", "b": "唐·韩愈《师说》"}, {"t": "择其一二。", "b": "宋·苏轼《石钟山记》"}, {"t": "不择食矣。", "b": "清·方苞《狱中杂记》"}, {"t": "不择人而问焉。", "b": "清·刘开《问说》"}], "words": [{"w": "择席之癖", "t": "有选择睡铺的习惯"}, {"w": "择吉结缡", "t": "选择吉日,迎娶完婚"}, {"w": "择邻", "t": "选择邻居"}, {"w": "择木", "t": "选择主人,为其效劳"}, {"w": "择术", "t": "选择职业"}, {"w": "择尤", "t": "挑选突出的"}, {"w": "择决", "t": "挑选"}, {"w": "择车", "t": "经过挑选的战车"}, {"w": "择官", "t": "挑选官职"}, {"w": "择婿", "t": "挑选女婿;挑选夫婿。"}]}, {"meaning": "捉。", "cites": [{"t": "神武后见之,哀其憔悴,以膝承其首,亲为择虱。", "b": "《北史》"}]}, {"meaning": "(dù)。败坏;不合法度。", "cites": [{"t": "罔有择言在身。", "b": "《书·吕刑》"}, {"t": "口无择言,身无择行。", "b": "《孝经》"}], "words": [{"w": "择言", "t": "败言或不合法度的议论"}, {"w": "择行", "t": "败坏的德行或不合法度的行为。"}]}, {"meaning": "挑剔。", "cites": [{"t": "取此择彼,问右观宜。", "b": "《墨子》"}], "words": [{"w": "择嘴", "t": "饮食挑剔"}, {"w": "择毛儿", "t": "吹毛求疵。"}]}, {"meaning": "区别。", "cites": [{"t": "牛羊何择焉。", "b": "《孟子·梁惠王上》"}]}]}, {"pinyin": "zhái", "defs": [{"meaning": "挑拣,用于口语。", "cites": [{"t": "子产之从政也,择能而使之。", "b": "《左传·襄公三十一年》"}], "words": [{"w": "择菜;择不开", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('993wx','抬','1','tái','扌','8','','[{"pinyin": "tái", "defs": [{"meaning": "(形声。从手,台声。本义:合力共举一物)。"}, {"meaning": "同本义。", "cites": [{"t": "抠眼睛,捻鼻子,抬鼓弄,直打做一个攒盘。", "b": "《西游记》"}], "words": [{"w": "抬鼓弄", "t": "许多人把一个人抬起来翻倒"}, {"w": "抬轿子;抬出去;抬驾", "t": "抬轿"}, {"w": "抬盒", "t": "两人抬着盛放礼品的箱匣"}, {"w": "抬筐", "t": "两人抬的装物大筐。"}]}, {"meaning": "高举,使升高。", "cites": [{"t": "抬望眼,仰天长啸,壮怀激烈。", "b": "岳飞《满江红》"}], "words": [{"w": "抬头;抬手;抬眼;抬颏", "t": "昂首。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('994wx','拇','1','mǔ','扌','8','','[{"pinyin": "mǔ", "defs": [{"meaning": "(形声。从手,母声。本义:手大指) 同本义。", "cites": [{"t": "拇,拇指也。", "b": "《说文》。按,中指为将指,大指为拇指,手足大指皆曰拇。"}, {"t": "至于手拇毛脉。", "b": "《国语·楚语》。注:“大指也。”"}], "words": [{"w": "拇印", "t": "以手的拇指代印"}, {"w": "拇阵", "t": "拇战。猜拳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('995wx','拗','1','ǎo ào niù','扌','8','','[{"pinyin": "ǎo", "defs": [{"meaning": "(形声。从手,幼声。本义:折断)。"}, {"meaning": "同本义。", "cites": [{"t": "捣麝成尘香不灭,拗莲作寸丝难绝。", "b": "唐·温庭筠《达摩支曲》"}, {"t": "十分小心的拗开了,焦皮里面窜出一道白气,白气散了,是两半个白面的馒头。", "b": "鲁迅《药》"}], "words": [{"w": "拗折", "t": "折断。"}]}, {"meaning": "转折;弯转。", "cites": [{"t": "读到这里,他总是微笑起来,而且将头仰起,摇着,向后面拗过去,拗过去。", "b": "鲁迅《朝花夕拾》"}]}]}, {"pinyin": "ào", "defs": [{"meaning": "违反;不服从。", "cites": [{"t": "古心虽自鞭,世路终难拗。", "b": "唐·韩愈《答孟郊》"}], "words": [{"w": "拗憋", "t": "倔强顽抗,不顺从"}, {"w": "拗怒", "t": "压抑愤怒"}, {"w": "拗抗", "t": "违反;不服从"}, {"w": "拗戾", "t": "违反。"}]}, {"meaning": "不顺口,作旧诗时平仄不依常格。", "cites": [{"t": "怪事,没有比这个再拗口,再难记的了。—茅盾《陀螺》", "b": ""}], "words": [{"w": "拗律", "t": "违反平仄常格的律诗"}, {"w": "拗救", "t": "律诗的拗句,须用拗救,有拗有救,才不为病"}, {"w": "拗字", "t": "律诗中不合常格的字。"}]}, {"meaning": "撬,扳。", "cites": [{"t": "口如暴死人,铁石拗不开。", "b": "前蜀·贯休《偶作》"}], "words": [{"w": "拗项", "t": "扭拗颈项。比喻士大夫期望高官厚禄"}, {"w": "拗开", "t": "两手把东西掰开。"}]}]}, {"pinyin": "niù", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('996wx','其','1','jī qí','八','8','','[{"pinyin": "jī", "defs": [{"meaning": "周年。", "cites": [{"t": "丧:父母三年,妻、后子三年,父、叔父、弟兄、庶子其,戚、族人五月。", "b": "《墨子》"}, {"t": "左右伯受沐涂树之枝阔,其年,民被白布。", "b": "《管子·轻重戊》"}, {"t": "亟其乘屋,其始播百谷。", "b": "《诗·豳风·七月》"}]}]}, {"pinyin": "qí", "defs": [{"meaning": "期限。", "cites": [{"t": "既辱且危,死其将至。", "b": "《易·系辞下》"}]}, {"meaning": "(形声。甲骨文字形象簸箕形,即“箕”本字。金文又加声符“丌”(jī),变成“其”。(jī)本义:簸箕。今字作“箕”。“其”假借为代词:他、他们、那等)。"}, {"meaning": "彼、他。", "cites": [{"t": "郯子之徒,其贤不及孔子。", "b": "《师说》"}], "words": [{"w": "独善其身", "t": ""}]}, {"meaning": "它。", "cites": [{"t": "或者不如说希望:希望其有,又希望其无。", "b": "鲁迅《祝福》"}]}, {"meaning": "他的。", "cites": [{"t": "他日归,则有馈其兄生鹅者。", "b": "《孟子·滕文公下》"}], "words": [{"w": "其妻", "t": ""}]}, {"meaning": "根据情况所指的、提到的或认为的那个。", "cites": [{"t": "其日牛马嘶,新妇入青庐。", "b": "《孔雀东南飞》"}], "words": [{"w": "正当其时", "t": ""}]}, {"meaning": "也许;大概。", "cites": [{"t": "善不可失,恶不可长,其陈桓公之谓乎!", "b": "《左传·隐公六年》"}, {"t": "其自桓叔以下。", "b": "《国语·晋语》"}, {"t": "齐国其庶几乎。", "b": "明·宗臣《报刘一丈书》"}, {"t": "齐其庶几乎。", "b": ""}, {"t": "其一旦将以不敬之民而驱之战。", "b": "《左传·僖公三十二年》"}]}, {"meaning": "表示祈使。当,可。", "cites": [{"t": "吾其还也。", "b": "《左传·僖公三十二年》"}, {"t": "君其详之。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "汝其善抚之。", "b": "清·林觉民《与妻书》"}, {"t": "弟其宽心勿畏可也。", "b": "太平天国·洪仁玕《英杰归真》"}]}, {"meaning": "将,将要。", "cites": [{"t": "今殷其沦丧。", "b": "《书·微子》"}]}, {"meaning": "表示诘问", "cites": [{"t": "其为死君乎。", "b": "《左传·僖公三十二年》"}, {"t": "其敢自谓几于成乎。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "其可怪也欤。", "b": "唐·韩愈《师说》"}, {"t": "尽吾志也而不能至者,可以无悔矣,其孰能讥之乎?", "b": "王安石《游褒禅山记》"}, {"t": "中国其果老矣乎。", "b": "清·梁启超《少年中国说》"}]}, {"meaning": "极,甚。", "cites": [{"t": "开地数千里,此其大功也。", "b": "《韩非子·初见秦》"}]}, {"meaning": "如果,假设。", "cites": [{"t": "其或未能处置,即且给公验。", "b": "唐·封演《封氏闻见记》"}]}, {"meaning": "或许;大概。", "cites": [{"t": "我中国前途,其有望乎?", "b": "《负曝闲谈》"}], "words": [{"w": "其诸", "t": "或者"}, {"w": "其者", "t": "或者。"}]}, {"meaning": "还是。表选择。", "cites": [{"t": "其真无马耶。", "b": "唐·韩愈《杂说》"}]}, {"meaning": "又。", "cites": [{"t": "其真不知马耶。", "b": ""}, {"t": "其亦足乐乎。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "用作语助。"}, {"meaning": "附着于形容词前、后,起加强形容的作用。", "cites": [{"t": "北风其凉,雨雪其雰。", "b": "《诗·邶风》"}], "words": [{"w": "他们对工作是极其认真的;这类好辞书,尤其需要;说得何其好哇!", "t": ""}]}, {"meaning": "句中助词,无义,只增加一个音节。", "cites": [{"t": "虽僻远其何伤。", "b": "《楚辞·屈原·涉江》"}]}, {"meaning": "又。", "cites": [{"t": "云霏霏其承宇。", "b": ""}, {"t": "其敢自谓几于成乎。", "b": "唐·韩愈《朱文公校昌黎先生集》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('997wx','取','1','qǔ','又','8','','[{"pinyin": "qǔ", "defs": [{"meaning": "(会意。从又,从耳。甲骨文字形。左边是耳朵,右边是手(又),合起来表示用手割耳朵。古代作战,以割取敌人尸体首级或左耳以计数献功。本义:割下左耳)。"}, {"meaning": "同本义。", "cites": [{"t": "取,捕取也。", "b": "《说文》"}, {"t": "大兽公之,小禽私之,获者取左耳。", "b": "《周礼》"}, {"t": "且今之勍者,皆吾敌也,虽及胡者,获则取之,何有于二毛?", "b": "《左传·僖公二十二年》"}, {"t": "取吴元济。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "斩获敌人的首级为取。", "cites": [{"t": "恨君不取契丹首,金甲牙旗归故乡。", "b": "宋·苏轼《阳关词》"}]}, {"meaning": "拿。", "cites": [{"t": "取数斗归。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "对面取人物。", "b": ""}, {"t": "取一葫芦。", "b": "宋·欧阳修《归田录》"}, {"t": "取器械。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "从架上取书;从巢里取蛋;取受", "t": "拿取和收受"}, {"w": "取则", "t": "取作准则,规范或榜样"}, {"w": "取将", "t": "拿取。"}]}, {"meaning": "娶妻。", "cites": [{"t": "取妻如之何?", "b": "《诗·齐风·南山》"}, {"t": "君取于吴,为同姓。", "b": "《论语·述而》"}, {"t": "勿用取女。", "b": "《易·蒙》"}, {"t": "可以冠子取妻。", "b": "《礼记·杂记》"}, {"t": "昭公取于吴。", "b": "《左传·哀公十二年》"}, {"t": "终老不复取。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "还必相迎取。", "b": ""}, {"t": "我近来取得一个老小,清河县人。", "b": "《水浒传》"}], "words": [{"w": "取女", "t": "娶妻"}, {"w": "取亲", "t": "娶妻"}, {"w": "取室", "t": "娶妻。"}]}, {"meaning": "选取;选拔。", "cites": [{"t": "深思而慎取。", "b": "宋·王安石《游褒禅山记》"}, {"t": "人取之。", "b": "明·刘基《卖柑者言》"}, {"t": "舍体而取面。", "b": "蔡元培《图画》"}], "words": [{"w": "取路", "t": "上路"}, {"w": "取戏", "t": "采取游戏态度"}, {"w": "取义", "t": "选择正义,就义而死"}, {"w": "取人", "t": "选择人"}, {"w": "取友", "t": "选取朋友"}, {"w": "取途", "t": "选取经由的道路"}, {"w": "取象", "t": "取某种事物之征象。"}]}, {"meaning": "招致。", "cites": [{"t": "谗毁竟自取。", "b": "唐·杜甫《上水遣怀》"}], "words": [{"w": "取罪", "t": "自我罪责"}, {"w": "取讥", "t": "招致讥讽"}, {"w": "取毙", "t": "招致丧身"}, {"w": "取醉", "t": "喝酒致醉。"}]}, {"meaning": "得到;取得。", "cites": [{"t": "不稼不穑,胡取禾三百廛兮?", "b": "《诗·魏风·伐檀》"}, {"t": "青,取之于蓝,而青于蓝。", "b": "《荀子·劝学》"}, {"t": "钻燧取火。", "b": "《韩非子·五蠹》"}, {"t": "文能取胜。", "b": "《史记·平原君虞卿列传》"}, {"t": "于人也奚取焉。", "b": "唐·韩愈《朱文昌校昌黎·先生集》"}, {"t": "召闹取怒。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "取事", "t": "取得成就事功的机会;行事"}, {"w": "取讨", "t": "讨取;索取"}, {"w": "取和儿", "t": "取了和气。和睦相处"}, {"w": "取真气", "t": "摄取天地间元气"}, {"w": "取觅", "t": "收入;获得"}, {"w": "取供", "t": "讨取口供。"}]}, {"meaning": "攻取,夺取。", "cites": [{"t": "必取宋。", "b": "《墨子·公输》"}, {"t": "取阳晋。", "b": "《史记·廉颇蔺相列传》"}]}, {"meaning": ""}, {"meaning": "会合,集合。", "cites": [{"t": "郑国多盗,取人于萑苻泽。", "b": "《左传·昭公二十年》"}]}, {"meaning": "积畜。", "cites": [{"t": "而利取分寡。", "b": "《晏子春秋·外篇重而异者》"}]}, {"meaning": ""}, {"meaning": "跑,疾走。", "cites": [{"t": "王良御之,则日取乎千里。", "b": "《韩非子·难势》"}, {"t": "上高堂,行取殿下堂,孤儿泪下如雨。", "b": "《古乐府》"}]}, {"meaning": "趋向。", "cites": [{"t": "两者合而天下取。", "b": "《荀子·王霸》"}, {"t": "夸主以为高,异取以为高。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "表示范围,相当于“才”、“仅”。", "cites": [{"t": "杨子取为我,拔一毛而利天下,不为也。", "b": "《孟子·尽心上》"}]}, {"meaning": "表示动态,相当于“得”、“着”。", "cites": [{"t": "人生自古谁无死,留取丹心照汗青。", "b": "文天祥《过零丁洋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('998wx','茉','1','mò','艹','8','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从艸,末声。茉莉,植物名)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('999wx','苦','1','kǔ gǔ','艹','8','','[{"pinyin": "kǔ", "defs": [{"meaning": "(形声。从艸,古声。本义:苦菜)。"}, {"meaning": "同本义,即“荼”。", "cites": [{"t": "苦,大苦苓也。", "b": "《说文》"}, {"t": "采苦采苦,首阳之下。", "b": "《诗·唐风·采苓》"}, {"t": "濡豚包苦实蓼。", "b": "《礼记·内则》"}, {"t": "天子于是食苦。", "b": "《穆天子传》"}], "words": [{"w": "苦苣", "t": "野苣。又名荼"}, {"w": "苦荼", "t": "苦菜"}, {"w": "苦賈", "t": "苦菜。"}]}, {"meaning": "病;病痛。", "cites": [{"t": "自苦而居海上。", "b": "《吕氏春秋·遇合》。注;“伤也。”"}, {"t": "皆甚苦之。", "b": "《吕氏春秋·贵卒》。注:“病也。”"}, {"t": "苦垮之家。", "b": "《淮南子·精神》。注:“疾也。”"}], "words": [{"w": "苦车", "t": "晕车。乘车时有晕眩呕吐等感觉"}, {"w": "苦船", "t": "晕船。乘船时有晕眩呕吐等感觉。"}]}, {"meaning": "苦味,跟“甘”、“甜”相对。古称“五味”之一。", "cites": [{"t": "谁为荼苦。", "b": "《诗·邶风·谷风》"}, {"t": "而凡味之似苦,亦命为苦。", "b": "《广雅》"}, {"t": "以苦养气。", "b": "《周礼·疡医》。注:“火味也。”"}, {"t": "苦胜辛。", "b": "《素问·五运行大论》"}, {"t": "则苦雨数来。又,苦者人所恶。故甘苦为物之美恶,亦为人之爱恶。", "b": "《礼记·月令》"}, {"t": "大率不能甘而善苦。", "b": "明·刘基《苦斋记》"}]}, {"meaning": "又。", "cites": [{"t": "其味皆苦。", "b": ""}, {"t": "良药苦口利于病。", "b": ""}, {"t": "李以苦存。", "b": ""}], "words": [{"w": "苦瓠子", "t": "苦瓜。喻指受苦人"}, {"w": "苦艳艳", "t": "苦味浓浓的"}, {"w": "苦行", "t": "在寺院专事劳作的净人,即未出家的人"}, {"w": "苦口师", "t": "指茶"}, {"w": "苦荼", "t": "苦茶,苦茗。即茶。"}]}, {"meaning": "痛苦;困苦。", "cites": [{"t": "其毒大苦。", "b": "《诗·小雅·小明》"}, {"t": "妇啼一何苦。", "b": "唐·杜甫《石壕吏》"}, {"t": "俾困苦不可忍。", "b": "清·方苞《狱中杂记》"}, {"t": "其平居常苦于多疾。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "苦厄", "t": "苦难;厄运"}, {"w": "苦主", "t": "命案中被害者的家属"}, {"w": "苦脑子", "t": "命苦;可怜;苦命人;可怜的人"}, {"w": "苦滴滴", "t": "形容人十分痛苦"}, {"w": "苦淹淹", "t": "苦恹恹,苦厌厌。形容非常痛苦、悲惨"}, {"w": "苦孜孜", "t": "痛苦悲切。"}]}, {"meaning": "刻苦。", "cites": [{"t": "盖以苦学力文所致。", "b": "白居易《与元九书》。又如:苦读"}]}, {"meaning": "劳苦;辛苦。", "cites": [{"t": "母氏劳苦。", "b": "《诗·邶风·凯风》"}, {"t": "辨其功苦。", "b": "《管子·小筐》。注:“谓滥恶。”"}, {"t": "辨其苦良。", "b": "《周礼·典妇功》"}, {"t": "从师苦而欲学之功也。", "b": "《吕氏春秋·诬徒》"}, {"t": "虽臣虏之劳不苦于此矣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "苦节", "t": "艰苦卓绝、守志不谕的节操"}, {"w": "苦绷苦拽", "t": "不辞辛苦,东拼西凑。"}]}, {"meaning": "贫穷。", "cites": [{"t": "苦,穷也。", "b": "《广雅》"}], "words": [{"w": "苦哈哈", "t": "非常穷的人"}, {"w": "苦混混", "t": "穷人"}, {"w": "苦胎", "t": "对穷人的蔑称"}, {"w": "苦尽甘来", "t": "苦日子结束,好日子到来"}, {"w": "苦日子", "t": ""}]}, {"meaning": "困扰;困辱。", "cites": [{"t": "长史自不欲苦物。", "b": "《世说新语·赏誉》"}], "words": [{"w": "苦计", "t": "在走投无路的情况下所使用的计策"}, {"w": "苦恨", "t": "苦恼"}, {"w": "苦煎", "t": "形容身心备受折磨。"}]}, {"meaning": "使困苦,困于。", "cites": [{"t": "不苦一民。", "b": "《战国策·秦策》。注:“劳也。”"}, {"t": "纳至忠甚苦。", "b": "《汉书·谷永传》。注:“劳也。”"}, {"t": "何苦而不平(苦于山挖不平。)", "b": "《列子·汤问》"}, {"t": "天下苦秦久矣。", "b": "《史记·陈涉世家》"}, {"t": "若辈得无苦贫乎。", "b": "明·崔銧《记王忠肃公翱三事》"}], "words": [{"w": "苦热", "t": "苦于炎热;酷热"}, {"w": "苦饥", "t": "困于饥饿;很饿。"}]}, {"meaning": "恨,怨嫌。", "cites": [{"t": "人苦不知足。", "b": "《后汉书·岑彭传》"}], "words": [{"w": "苦竹哀丝", "t": "谓怨苦之情发于管弦"}, {"w": "苦毒", "t": "痛恨。"}]}, {"meaning": "竭力;尽力。", "cites": [{"t": "杨朗苦谏不从。", "b": "《世说新语·识鉴》"}, {"t": "何必劳神苦思。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "苦死", "t": "拼命,极力"}, {"w": "苦虑", "t": "苦思冥想"}, {"w": "苦谏", "t": "苦心竭力地规劝。"}]}, {"meaning": "甚,很。表示程度。", "cites": [{"t": "帝遂召武子苦责之。", "b": "《世说新语·方正》"}], "words": [{"w": "苦爱", "t": "酷爱"}, {"w": "苦会", "t": "很会。"}]}, {"meaning": "幸好,幸亏。", "cites": [{"t": "这孟州城是个小去处,那土城苦不甚高。", "b": "《水浒传》"}]}]}, {"pinyin": "gǔ", "defs": [{"meaning": "粗劣", "words": [{"w": "苦盐", "t": "粗盐,颗粒盐"}, {"w": "苦功", "t": "粗工艺"}, {"w": "苦事", "t": "粗制滥造。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1000wx','昔','1','xī','日','8','','[{"pinyin": "xī", "defs": [{"meaning": "(象形。象残肉日以晞之,与俎同意。本义:干肉)。"}, {"meaning": "同本义。", "cites": [{"t": "昔,干肉也。", "b": "《说文》"}]}, {"meaning": "假借为“昨。”从前;过去(与“今”相对)。", "cites": [{"t": "二曰昔酒。", "b": "《周礼·酒正》。?"}, {"t": "昔之人无闻知。", "b": "《书·无逸》"}, {"t": "自古在昔。", "b": "《诗·商颂·那》"}, {"t": "昔者,圣王之作易也。", "b": "《易·说卦传》"}, {"t": "昔栾武子。", "b": "《国语·晋语》"}, {"t": "昔人已乘黄鹤去。", "b": "唐·崔颢《黄鹤楼》"}, {"t": "昔自郡城。", "b": "清·周容《芋老人传》"}], "words": [{"w": "抚今追昔;今非昔比;今胜于昔;在昔", "t": "过去,从前"}, {"w": "昔来", "t": "往日以来"}, {"w": "昔士", "t": "古之贤人。"}]}, {"meaning": "昨日。", "cites": [{"t": "昔者疾,今日愈,如之何不吊?", "b": "《孟子·公孙丑下》。赵岐注:“昔者,昨天也。”"}]}, {"meaning": "傍晚。", "cites": [{"t": "是今日适越而昔至也。", "b": "《庄子·齐物论》"}, {"t": "日入至于星出谓之昔。", "b": "《谷梁传·庄公七年》"}, {"t": "其乐非特朝昔之乐也。", "b": "《史记·楚世家》"}]}, {"meaning": "夜晚。", "cites": [{"t": "通昔不寐矣。", "b": "《庄子·天运》"}, {"t": "昔,夜也。", "b": "《广雅》"}, {"t": "夏四月辛卯昔。", "b": "《谷梁传·庄公七年》"}, {"t": "昔昔梦为国君……昔昔梦为人仆。", "b": "《列子·周穆王》"}, {"t": "为一昔之期。", "b": "《左传·哀公四年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1001wx','苛','1','kē','艹','8','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。本义:小草)。"}, {"meaning": "同本义。", "cites": [{"t": "苛,小草也。", "b": "《说文》"}]}, {"meaning": "疥疮。", "cites": [{"t": "疾痛苛痒。", "b": "《礼记·内则》"}], "words": [{"w": "苛痒", "t": "疥疮痒。"}]}, {"meaning": "病", "cites": [{"t": "其形安而不移,能守一而弃万苛。", "b": "《管子·内业》"}, {"t": "身无苛殃。", "b": "《吕氏春秋·审时》。注:“病也。”"}], "words": [{"w": "苛殃", "t": "疾病和灾患"}, {"w": "苛疾", "t": "疾病。"}]}, {"meaning": "繁杂,烦琐。", "cites": [{"t": "好苛礼。", "b": "《史记·郦生陆贾传》"}, {"t": "内无苛慝。", "b": "《国语·晋语》。注:“烦也。”"}, {"t": "去烦蠲苛。", "b": "王褒《四子讲德论》"}], "words": [{"w": "苛礼", "t": "苛刻微细的礼节"}, {"w": "苛难", "t": "以琐事诘难"}, {"w": "苛敛", "t": "烦重地征收赋税"}, {"w": "苛小", "t": "烦琐细小。亦指繁杂细微之事。"}]}, {"meaning": "狠虐、刻薄(侧重于残暴狠毒)。", "cites": [{"t": "弭其百苛。", "b": "《国语·楚语》。注:“虐也。”"}, {"t": "关市苛难之。", "b": "《韩非子·内储说上》"}, {"t": "父老苦秦苛法久矣。", "b": "《史记·高祖本纪》"}, {"t": "苛政猛于虎也。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "苛虐", "t": "苛刻虐待"}, {"w": "苛法", "t": "烦琐严厉的法令"}, {"w": "苛吏", "t": "酷吏"}, {"w": "苛求", "t": "过严过分地要求"}, {"w": "苛征", "t": "横征暴敛。"}]}, {"meaning": "使…苛刻。", "cites": [{"t": "苛关市之征以难其事。", "b": "《荀子·富国》"}]}, {"meaning": "烦扰,骚扰。", "cites": [{"t": "朝夕苛我边鄙。", "b": "《国语·晋语一》"}]}, {"meaning": "谴责,责问。", "cites": [{"t": "大司空士夜过奉常亭,亭长苛之。", "b": "《汉书·王莽传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1002wx','若','1','rě ruò','艹','8','','[{"pinyin": "rě", "defs": [{"meaning": "（bōrě）:智慧(佛经用语)。"}]}, {"pinyin": "ruò", "defs": [{"meaning": "(象形。甲骨文字形,象一个女人跪着,上面中间象头发,两边两只手在梳发,表示“顺从”。本义:顺从)。"}, {"meaning": "同本义。", "cites": [{"t": "若,顺也。", "b": "《尔雅·释名》"}, {"t": "万民是若。", "b": "《诗·鲁颂·阙宫》"}, {"t": "天子是若。", "b": "《诗·大雅·烝民》"}, {"t": "有孚禺若。", "b": "《易·观》"}, {"t": "钦若昊天。", "b": "《书·尧典》"}, {"t": "不逢不若。", "b": "《左传·宣公三年》"}], "words": [{"w": "若时", "t": "顺应天时"}, {"w": "若淑", "t": "温顺而善良。"}]}, {"meaning": "如同;像。", "cites": [{"t": "圣人之德,若天之高,若地之普。", "b": "《墨子·尚贤中》"}, {"t": "肌肤若 冰雪,绰约若处子。", "b": "《庄子·逍遥游》"}, {"t": "关山度若飞。", "b": "《乐府诗集·木兰诗》"}, {"t": "天涯若比邻。", "b": "唐·王勃《杜少府之任蜀州》"}], "words": [{"w": "视若分敌;若明若昧", "t": "好像清楚又好像不清楚"}, {"w": "若出一辙", "t": "若出一轨。像从一个车辙里出来的。比喻言论、行动、遭遇等完全一样"}, {"w": "若如", "t": "如;像"}, {"w": "若卵投石", "t": "同“以卵击石”。比喻不自量力,必遭失败"}, {"w": "若涉渊水", "t": "若涉渊冰。比喻处境艰险。"}]}, {"meaning": "择菜。", "cites": [{"t": "若,择菜也。从艸、右。右,手也。", "b": "《说文》"}]}, {"meaning": "引申为选择。", "cites": [{"t": "《晋语》秦穆公曰:“夫晋国之乱,吾谁使先若夫二公子而立之,以为朝夕之急。”此谓使谁先择二公子而立之,若正训择,择菜引申之义也。", "b": "清·段玉裁《说文解字注》"}]}, {"meaning": "同,相当。", "cites": [{"t": "彼与彼年相若也。", "b": "韩愈《师说》"}, {"t": "布帛长短同,则贾相若。", "b": "《孟子》"}]}, {"meaning": "及;到。", "cites": [{"t": "病未若死。", "b": "《国语》"}]}, {"meaning": "比得上(多用于否定句和反问句)。", "cites": [{"t": "虽然,则彼疾,当养者孰若妻与宰?", "b": "《礼记》"}, {"t": "徐公不若君之美也。", "b": "《战国策·齐策》"}]}, {"meaning": "诺,应允,后作“诺”。", "cites": [{"t": "已若必信,则处于度之内也。", "b": "《马王堆汉墓帛书·经法》"}, {"t": "步骑之所蹂若。", "b": "《文选·司马相如·上林赋》"}]}, {"meaning": "对付,处置。", "cites": [{"t": "寇深矣,若之何?", "b": "《左传·僖公十五年》"}]}, {"meaning": "如此,这样。", "cites": [{"t": "出若入若。", "b": "《荀子·王霸》。注:“如此也。”"}, {"t": "织自若。", "b": "《战国策·秦策》"}, {"t": "以若所为,求若所欲,犹缘木而求鱼也。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "若许", "t": "如许;这些"}, {"w": "若言", "t": "此言,这样的话"}, {"w": "若曰", "t": "这样说"}, {"w": "若大若小", "t": "大大小小"}, {"w": "若此", "t": "如此,这样"}, {"w": "若是", "t": "如此,这样"}, {"w": "若斯", "t": "如此"}, {"w": "若然", "t": "如此"}, {"w": "若尔", "t": "如此,如果这样。"}]}, {"meaning": "你。", "cites": [{"t": "若,汝也。", "b": "《小尔雅》"}, {"t": "惟若宁候。", "b": "《考工记·梓人》"}, {"t": "若则有常。", "b": "《仪礼·士昏礼记》"}, {"t": "若肯发兵助我乎?", "b": "《汉书·匈奴传上》"}, {"t": "若不恭命。", "b": "《墨子·明鬼下》"}, {"t": "命曰三日,若宿而至。", "b": "《国语·晋语四》"}, {"t": "若为佣耕,何富贵也。", "b": "《史记·陈涉世家》"}, {"t": "若辈得无苦贫乎。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "若曹", "t": "你们这些人"}, {"w": "若属", "t": "你们"}, {"w": "若辈", "t": "你们。"}]}, {"meaning": "其;他的 ——用于他称。", "cites": [{"t": "今人处若国得罪。", "b": "《墨子·天志下》"}]}, {"meaning": "这么;那么。用同“偌”。", "cites": [{"t": "老太太若大年纪。", "b": "《红楼梦》"}]}, {"meaning": "假如;如果。", "cites": [{"t": "公子若反晋国,则何以报不谷?", "b": "《左传·僖公二十三年》"}, {"t": "若反国,将为乱。", "b": "《史记·赵世家》"}, {"t": "寡人若朝于薛,不敢与诸任齿。", "b": "《左传·隐公十一年》"}, {"t": "若印数十百千本,则极为神速。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "天若有情天亦老。", "b": "唐·李贺《金铜仙人辞汉歌》"}], "words": [{"w": "若不是", "t": "如果不是"}, {"w": "若曰", "t": "如果说"}, {"w": "假若", "t": "假使"}, {"w": "若其", "t": "假如,如果"}, {"w": "若苟", "t": "若或。假如,如果"}, {"w": "若非", "t": "如果不是;要不是"}, {"w": "若果", "t": "如果"}, {"w": "若使", "t": "假使,假如,如果"}, {"w": "若是", "t": "如果,如果是。"}]}, {"meaning": "至于 。用在句首以引起下文。", "cites": [{"t": "若夫霪雨霏霏,连月不开,阴风怒号,浊浪排空。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "若乃", "t": "至于。用于句子开头,表示另起一事。"}]}, {"meaning": "或;或者。", "cites": [{"t": "以万人若一郡降者,封万户。", "b": "《汉书·高帝纪》"}, {"t": "若有会同。", "b": "《周礼·稍人》"}], "words": [{"w": "若者", "t": "或者"}, {"w": "若大若小", "t": "大大小小。"}]}, {"meaning": "与,和。", "cites": [{"t": "旅王若公。", "b": "《书·召诰》"}]}, {"meaning": "而。", "cites": [{"t": "抑若扬兮。", "b": "《诗·齐风·猗嗟》"}, {"t": "宠辱若惊。", "b": "《老子》。顾注:“而已”"}, {"t": "若降天地之施,垂三光之明者,实在陛下。", "b": "《三国志·魏志》"}]}, {"meaning": "禾秆皮。", "cites": [{"t": "稣,杷取禾若也。", "b": "《说文》。朱骏声《说文通训定声》:“秆皮散乱,杷而梳取之。”"}]}, {"meaning": "香草名。", "cites": [{"t": "杜若,香草。", "b": "《说文》"}, {"t": "华采衣兮若英。", "b": "《楚辞·云中君》"}, {"t": "顺微风,挥若芳。", "b": "傅毅《舞赋》。注:“杜也。”"}, {"t": "衡兰芷若。", "b": "《汉书·司马相如传》"}], "words": [{"w": "若芳", "t": "杜若的香气"}, {"w": "若英", "t": "杜若的花"}, {"w": "若惠", "t": "香草名。杜若和蕙草。"}]}, {"meaning": "秦、汉时县名 。治所在今湖北省宜城县东南。"}, {"meaning": "古水名 。即今雅砻江,为金沙江支流。源出青海,东南流经甘孜、新龙等县,到攀枝花市东北入金沙江。"}, {"meaning": "用在形容词或副词后面,表示事物的状态。相当于“貌”、“样子”。", "cites": [{"t": "用史巫纷若,吉。", "b": "《易·巽卦》"}, {"t": "有孚颗若。", "b": "《易·观卦》"}, {"t": "乘其四骆,六辔沃若。", "b": "《诗·小雅·裳裳者华》"}, {"t": "桑之未落,其叶沃若。", "b": "《诗·卫风·氓》"}]}, {"meaning": "用于句首。", "cites": [{"t": "若昔朕其逝。", "b": "《书·大诰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1003wx','茂','1','mào','艹','8','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从艸,戊(wù)声。本义:草木繁盛)。"}, {"meaning": "同本义。", "cites": [{"t": "茂,草丰盛也。", "b": "《说文》"}, {"t": "草不溃茂。", "b": "《诗·大雅·召卬》"}, {"t": "种之黄茂。", "b": "《诗·大雅·生民》"}, {"t": "树木丛生,百草丰茂。", "b": "曹操《观沧海》"}], "words": [{"w": "茂英", "t": "繁盛的花朵"}, {"w": "茂苑", "t": "花木茂盛的苑囿"}, {"w": "茂育", "t": "滋长繁盛"}, {"w": "茂实", "t": "丰盛的果实。也指草木长得茂盛并结果实"}, {"w": "茂遂", "t": "繁荣滋长。"}]}, {"meaning": "大;盛大。", "cites": [{"t": "德音是茂。", "b": "《诗·小雅·南山有台》。笺:“盛也。”"}, {"t": "桐生茂豫。", "b": "《汉书·礼乐志》。注:“茂豫美盛而光悦也。”"}, {"t": "以旌茂功,以慰劬劳。", "b": "《三国志·吴志》"}], "words": [{"w": "茂世", "t": "盛世"}, {"w": "茂业", "t": "伟大的功业"}, {"w": "茂绪", "t": "盛大的事业"}, {"w": "茂豫", "t": "美盛而有光彩;比喻昌盛安乐。"}]}, {"meaning": "美好;优秀。", "cites": [{"t": "子之茂兮。", "b": "《诗·齐风·还》。传:“美也。”"}, {"t": "广延茂士。", "b": "《汉书·朱邑传》"}, {"t": "茂材异等。", "b": "《汉书·武帝纪》。应昭注:“旧言秀才,避光武帝讳称茂才。”"}, {"t": "出文多者,才知(智)茂。", "b": "王充《论衡》"}], "words": [{"w": "茂士", "t": "优秀的人才"}, {"w": "茂异", "t": "茂美特异。指优秀出众的人才"}, {"w": "茂科", "t": "科举名。即贤良方正科"}, {"w": "茂年", "t": "盛壮之年"}, {"w": "茂龄", "t": "壮年。"}]}, {"meaning": "买卖。", "cites": [{"t": "商以足用,茂迁有无。", "b": "《汉书·叙传下》"}]}, {"meaning": "劝勉。", "cites": [{"t": "先王以茂对时育万物。", "b": "《易·无妄》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1004wx','苹','1','píng','艹','8','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从艸,平声。本义:浮萍)。"}, {"meaning": "同本义。", "cites": [{"t": "苹,无根浮水而生者。", "b": "《说文》"}]}, {"meaning": "蒿的一种。即青蒿。", "cites": [{"t": "呦呦鹿呜,食野之苹。", "b": "《诗·小雅·鹿鸣》"}], "words": [{"w": "苹藻主", "t": "妻子"}, {"w": "苹敬", "t": "礼金。"}]}, {"meaning": "兵车的一种。", "cites": [{"t": "苹车之萃。", "b": "《周礼·春官·车仆》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1005wx','苗','1','miáo','艹','8','','[{"pinyin": "miáo", "defs": [{"meaning": "(会意。从田,从艸。田里生长的形状象草的东西。本义:禾苗,未吐穗的庄稼)。"}, {"meaning": "同本义;泛指初生的植物。", "cites": [{"t": "苗,草生于田者。", "b": "《说文》"}, {"t": "无食我苗。", "b": "《诗·魏风·硕鼠》。传:“嘉谷也。”"}, {"t": "无苗。", "b": "《公羊传·庄公七年》。注:“苗者禾也。生曰苗,秀曰禾。”"}, {"t": "宋人有闵其苗之不长而揠之者,芒芒然归。", "b": "《孟子》"}, {"t": "南门之外有黄犊食苗道左者。", "b": "《韩非子·内储说上》"}, {"t": "八月苗未枯。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "无苗时采。", "b": ""}, {"t": "有苗时采。", "b": ""}], "words": [{"w": "补苗;间苗;秧苗;麦苗;豆苗;壮苗", "t": "健壮的幼苗。"}]}, {"meaning": "子孙后代。", "cites": [{"t": "大王刘氏苗族,绍世而起。", "b": "《三国志·诸葛亮传》"}, {"t": "其先出自箕子苗。", "b": "《李翊碑》"}], "words": [{"w": "苗末", "t": "后代子孙"}, {"w": "苗胄", "t": "后代的子孙"}, {"w": "苗胤", "t": "子孙相承续。亦指后代子孙"}, {"w": "苗嗣", "t": "后嗣,后代"}, {"w": "苗绪", "t": "后代子孙。"}]}, {"meaning": "事物的开端;事物的预兆。", "cites": [{"t": "言者志之苗,行者文之根。", "b": "白居易《读张籍古乐府》"}], "words": [{"w": "苗脉", "t": "比喻事物的根源"}, {"w": "苗头", "t": "端绪;预兆;因由。"}]}, {"meaning": "庄稼出苗。", "cites": [{"t": "苗而不秀者有矣夫。", "b": "《论语·子罕》"}]}, {"meaning": "夏天的狩猎。", "cites": [{"t": "之子于苗,选徒嚣嚣。", "b": "《诗·小雅·车攻》"}, {"t": "春蒐,夏苗,秋狝,冬狩。", "b": "《左传·隐公五年》"}], "words": [{"w": "苗田", "t": "指夏季的狩猎"}, {"w": "苗狩", "t": "夏猎与冬猎。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1006wx','英','1','yīng','艹','8','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从艸,央声。本义:花)。"}, {"meaning": "同本义。", "cites": [{"t": "英,草荣而不实者。", "b": "《说文》"}, {"t": "有女同行,颜如舜英。", "b": "《诗·郑风·有女同车》。传:“华也。”"}, {"t": "秋菊之落英。", "b": "《离骚·夕餐》。注:“华也。”"}, {"t": "嗣若英于西冥。", "b": "谢庄《月赋》。注:“若木之英也。”"}, {"t": "毋夭英。", "b": "《管子·禁藏》。注:“谓草木之初生也。”"}, {"t": "落英缤纷。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "落英", "t": "花落"}, {"w": "英华", "t": "言花木之美。"}]}, {"meaning": "矛上的羽饰。", "cites": [{"t": "二矛重英,河上乎翱翔。", "b": "《诗·郑风·清人》。传:“矛有英饰也。”"}, {"t": "三英粲兮。", "b": "《诗·郑风·羔裘》"}]}, {"meaning": "杰出的人。", "cites": [{"t": "才能过人曰英。", "b": "《正字通》"}, {"t": "尧、舜者,天下之英也。", "b": "《荀子·正论》"}, {"t": "智过万人者谓之英。", "b": "《淮南子·泰族》"}, {"t": "德过千人曰英。", "b": "《礼记·辨名记》"}, {"t": "与三代之英。", "b": "《礼记·礼运》。注:“俊选之尤者。”"}], "words": [{"w": "英耆", "t": "年老有德有智的人"}, {"w": "英人", "t": "智慧和才能超群的人"}, {"w": "英士", "t": "才智或武艺出众之士"}, {"w": "英少", "t": "才华出众的青少年"}, {"w": "英台", "t": "才能杰出的台阁官员"}, {"w": "英材", "t": "英才。具有出众才智的人。"}]}, {"meaning": "精华。", "cites": [{"t": "含英咀华。", "b": "韩愈《进学解》"}], "words": [{"w": "英精", "t": "精华。指事物最纯粹、最美好的部分"}, {"w": "英辟", "t": "精辟。"}]}, {"meaning": "精灵;神灵。"}, {"meaning": "英国,英格兰。", "cites": [{"t": "英法联军。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "英将也。", "b": ""}, {"t": "英夷亦从此胆寒。", "b": "《广东军务记》"}, {"t": "英之南野。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "英美", "t": ""}]}, {"meaning": "卓越,才智杰出。", "cites": [{"t": "况刘豫州王室之胄,英才盖世。", "b": "《资治通鉴》"}], "words": [{"w": "英雄儿女", "t": "英雄业绩与男女恋情"}, {"w": "英才卓跞", "t": "才能卓越,高超绝异"}, {"w": "英杰", "t": "才智超群的人。"}]}, {"meaning": "好,美好。", "cites": [{"t": "英,美也。", "b": "《广雅》"}, {"t": "英华沉浮,洋溢八区。", "b": "扬雄《长杨赋》"}], "words": [{"w": "英声", "t": "美名,盛名;美音,优美的声音"}, {"w": "英旨", "t": "美妙的旨意,指诗文的思想内容和意境"}, {"w": "英标", "t": "俊美;英俊"}, {"w": "英拔", "t": "英俊特出。"}]}, {"meaning": "光华,光彩。", "cites": [{"t": "龙渊有玉英。", "b": "《淮南子·地形》"}], "words": [{"w": "英光", "t": "明亮有神的目光;亦指光辉"}, {"w": "英英", "t": "光彩鲜明的样子;轻盈明亮的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1007wx','苟','1','gǒu','艹','8','','[{"pinyin": "gǒu", "defs": [{"meaning": "(形声。从艸,句(gōu)声。本义:草名。又:菜名) 同本义。", "cites": [{"t": "苟,苟草也。", "b": "《说文》"}, {"t": "苟贞夫。", "b": "《急就篇》。注“苟,草名也。”"}]}, {"meaning": "随便,轻率。", "cites": [{"t": "生亦我所欲,所欲有甚于生者,故不为苟得也。", "b": "《孟子·告子上》"}], "words": [{"w": "一丝不苟;不苟言笑;苟言", "t": "言谈轻率随便。"}]}, {"meaning": "姑且;暂且。", "cites": [{"t": "苟者,偷合之称。所以行为廉隅,不存德义,谓之苟且。", "b": "《匡谬正俗》。按,累呼曰苟且,单呼曰苟。"}, {"t": "且苟而赋。", "b": "《国语·鲁语》"}, {"t": "临财毋苟得。", "b": "《礼记·曲礼上》"}, {"t": "苟全性命于乱世,不求闻达于诸侯。", "b": "诸葛亮《出师表》"}, {"t": "虽董之以严刑,振之以威怒,终苟免而不怀仁。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "苟全性命", "t": "暂时保全性命"}, {"w": "苟简", "t": "苟且简略"}, {"w": "苟止", "t": "苟且行事;勉强停止"}, {"w": "苟且行止", "t": "不正当的行为"}, {"w": "苟容", "t": "苟且依附。指被权贵者所收容接纳"}, {"w": "苟且因循", "t": "得过且过,不求进取"}, {"w": "苟免", "t": "苟且免于损害。"}]}, {"meaning": "若;如果;假使。", "cites": [{"t": "苟富贵,无相忘。", "b": "《史记·陈涉世家》"}, {"t": "苟粟多而财有余,何为而不成?", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "苟或", "t": "假如;如果"}, {"w": "苟能坚持,必将胜利", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1008wx','苑','1','yuàn','艹','8','','[{"pinyin": "yuàn", "defs": [{"meaning": "(形声。从艸,夗(yuàn)声。本义:养禽兽植树木的地方。后来多指帝王游乐打猎的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "苑,所以养禽兽囿也。", "b": "《说文》"}, {"t": "养牛马林木曰苑。", "b": "《三苍》"}, {"t": "有垣曰苑。", "b": "《字林》"}, {"t": "值林为苑。", "b": "左思《吴都赋》。刘注:“有木曰苑。”"}]}, {"meaning": "泛指园林,花园。", "cites": [{"t": "会幸苑中。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "苑囿兵", "t": "禁兵"}, {"w": "苑马", "t": "苑囿和马厩;亦指苑囿中的马。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1009wx','苞','1','bāo','艹','8','','[{"pinyin": "bāo", "defs": [{"meaning": "(形声。本义:席草,可制席子和草鞋)。"}, {"meaning": "同本义。", "cites": [{"t": "苞,苞草也,南阳以为粗履。", "b": "《说文》"}, {"t": "浸彼苞稂。", "b": "《诗·曹风·下泉》"}]}, {"meaning": "又。", "cites": [{"t": "浸彼包萧。", "b": ""}, {"t": "浸彼苞蓍。", "b": ""}, {"t": "系于包桑。", "b": "《易·否》"}, {"t": "其高燥则生葴(zhēn,马兰)、菥(sī,麦的一种)、苞、荔(草名)。", "b": "司马相如《子虚赋》"}], "words": [{"w": "包屦", "t": "古人居丧所穿的一种草鞋。"}]}, {"meaning": "苞片,花未开时包着花朵的变态叶。", "cites": [{"t": "山桃发红萼,野蕨渐紫苞。", "b": "南朝宋·谢灵运《酬从弟惠连》"}], "words": [{"w": "含苞未放", "t": ""}]}, {"meaning": "草木的根或茎干。", "cites": [{"t": "苞有三蘖。", "b": "《诗·商颂·长发》"}], "words": [{"w": "苞桑", "t": "原指根深柢固的桑树;比喻牢固的根基"}, {"w": "苞桑磐石", "t": "比喻极其坚固"}, {"w": "苞桑戒", "t": "系于根深蒂固的事物上而求得的牢靠鉴戒。"}]}, {"meaning": "草木茂盛,丛生。", "cites": [{"t": "苞,丰也。", "b": "《尔雅·释诂》"}, {"t": "方苞方体。", "b": "《诗·大雅·行苇》"}, {"t": "集于苞栩。", "b": "《诗·唐风·鸨羽》"}, {"t": "草木渐苞。", "b": "《书·禹贡》"}, {"t": "如竹苞也,如松茂矣。", "b": "《诗·小雅·斯干》"}], "words": [{"w": "苞杞", "t": "丛生的枸杞"}, {"w": "苞并", "t": "丛生。"}]}, {"meaning": "包裹;怀抱。", "cites": [{"t": "如山之苞。", "b": "《诗·大雅·常武》"}, {"t": "厥苞橘柚锡贡。", "b": "《书·禹贡》"}, {"t": "凡以弓剑苞苴箪笥问人者。", "b": "《礼记·曲礼上》"}, {"t": "尔贡苞茅不入。", "b": "《左传·僖公四年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1010wx','范','1','fàn','艹','8','','[{"pinyin": "fàn", "defs": [{"meaning": "(形声。从车,笵(fàn)省声。本义:古代遇大事出车,先辗过祭坛及祭牲的一种祭祀活动,祭路神)。"}, {"meaning": "同本义。"}, {"meaning": "假借为笵。法则。", "cites": [{"t": "範,法也。範,常也。", "b": "《尔雅》"}, {"t": "吾为之範我驰驱。", "b": "《孟子》。注:“法也。”"}], "words": [{"w": "范防", "t": "防范"}, {"w": "范轨", "t": "法则,模范。"}]}, {"meaning": "典范。", "cites": [{"t": "宇文新州之懿范。", "b": "王勃《滕王阁序》"}], "words": [{"w": "规范;示范;范轨", "t": "模范,法则"}, {"w": "范型", "t": "典型,范例。"}]}, {"meaning": "模子。", "cites": [{"t": "则以一铁范置铁板上,仍密布字印,满铁苑为一板。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "铁范;钱范;铜范;范金合土", "t": "用模子浇铸金属和泥。"}]}, {"meaning": "用模子浇铸,引申纳入规范。", "cites": [{"t": "范金合土。", "b": "《礼记·礼运》"}], "words": [{"w": "范型", "t": "使合乎某种模式"}, {"w": "范溶", "t": "铸造器物"}, {"w": "范铜", "t": "铸铜。"}]}, {"meaning": "效法;取法。", "cites": [{"t": "吾为之范我驰驱,终日不获。", "b": "《孟子·滕文公》"}], "words": [{"w": "范水模山", "t": "喻效法模仿他人"}, {"w": "范围", "t": "效法。"}]}, {"meaning": "草名。", "cites": [{"t": "范,草也。", "b": "《说文》"}]}, {"meaning": "蜂。", "cites": [{"t": "范则冠而蝉有婑。", "b": "《礼记·檀弓下》"}]}, {"meaning": "县名。汉置,属东郡。今仍为县。原属山东省。1964年划归河南省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1011wx','直','1','zhí','目','8','','[{"pinyin": "zhí", "defs": [{"meaning": "(会意。小篆字形,从L(yǐn),从十,从目。徐锴:“L,隐也,今十目所见是直也。”本义:不弯曲,与“枉”、“曲”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "直,正见也。", "b": "《说文》"}, {"t": "木直中绳,輮以为轮,其曲中规。", "b": "《荀子·劝学》"}, {"t": "正直为正,正曲为直。", "b": "《左传·襄公七年》"}, {"t": "木曰曲直。", "b": "《书》"}, {"t": "巽为绳直。", "b": "《易·说卦》"}, {"t": "先定准直。", "b": "《礼记·月令》"}, {"t": "争高直指。", "b": "吴均《与朱元思书》"}, {"t": "中通外直。", "b": "宋·周敦颐《爱莲说》"}, {"t": "梅以曲为美,直则无姿。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "又。", "cites": [{"t": "斫直删密。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "锄其直。", "b": ""}], "words": [{"w": "直线;直路;笔直;直迫", "t": "直直愎愎。直直劈劈。直搭直。直截了当"}, {"w": "直橛橛", "t": "身体挺得直直的"}, {"w": "直隆隆", "t": "高而直起"}, {"w": "直堑", "t": "直的沟渠"}, {"w": "直缕", "t": "形容直直挺挺,形容笔直或僵直的样子"}, {"w": "直坦坦", "t": "笔直而平坦。"}]}, {"meaning": "竖。与“横”相对 。跟地面垂直的。", "cites": [{"t": "直栏横槛。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "直上直下;直升机", "t": ""}]}, {"meaning": "引申为正直;公正;不偏私。", "cites": [{"t": "夫君之直臣,父之暴子也。", "b": "《韩非子·五蠹》"}, {"t": "师直为壮,曲为老。", "b": "《左传·僖公二十八年》"}, {"t": "屈平正道直行,竭忠尽智,以事其君。", "b": "《史记·屈原贾生列传》"}, {"t": "直道而行。", "b": "宋·司马光《训俭示康》"}, {"t": "居正惮瑞峭直。", "b": "《明史》"}], "words": [{"w": "直辞", "t": "正直的言辞"}, {"w": "直声", "t": "正直之言"}, {"w": "直质", "t": "正直朴实的资质"}, {"w": "直信", "t": "正直诚实"}, {"w": "直言正色", "t": "言语正直,仪容严肃。"}]}, {"meaning": "直爽。", "cites": [{"t": "哥哥是口直心快射粮军。", "b": "《元曲选》"}], "words": [{"w": "心直口快;直势", "t": "耿直坦率"}, {"w": "直性子", "t": "性情直爽的人"}, {"w": "直人", "t": "直爽的人;正直的人"}, {"w": "直心眼", "t": "指人的心地直率。"}]}, {"meaning": "正。", "cites": [{"t": "云白山青万余里,愁看直北是长安。", "b": "杜甫《小寒食舟中作》"}], "words": [{"w": "直南", "t": "正南"}, {"w": "直北", "t": "正北"}, {"w": "直准", "t": "正则。"}]}, {"meaning": "正当,有理。", "cites": [{"t": "师直为壮,曲为老。", "b": "《左传·僖公二十八年》"}]}, {"meaning": "径直,一直。", "cites": [{"t": "敢独与数十骑驰,直贯胡骑。", "b": "《史记·李将军列传》"}, {"t": "直抵其城。", "b": "《资治通鉴·唐纪》"}, {"t": "直进罾步。", "b": "《广东军务记》"}]}, {"meaning": "又。", "cites": [{"t": "直至初六。", "b": ""}, {"t": "直诘袁曰。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "直书就和", "t": "径直写成了一首和诗"}, {"w": "直律律", "t": "直接;径直"}, {"w": "直乃", "t": "简直就是"}, {"w": "直叙", "t": "直接叙述"}, {"w": "直解", "t": "直接领悟"}, {"w": "直抵", "t": "一直到达。"}]}, {"meaning": "故意。", "cites": [{"t": "有一老父,衣褐,至良所,直堕其履圮下。", "b": "《汉书·张良传》"}, {"t": "直堕其履圯下。", "b": "《史记·留侯世家》"}]}, {"meaning": "竟然。", "cites": [{"t": "何物老魅,直尔大胆,致坏箧子。", "b": "《聊斋志异》"}, {"t": "而直为此廪廪也。(直:竟。为:造成。廪廪:通懔懔,危惧的样子。)", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "直如此", "t": "竟然这样"}, {"w": "直恁", "t": "竟然如此;竟然这样。"}]}, {"meaning": "只;仅仅。", "cites": [{"t": "不可,直不百步耳。", "b": "《孟子·梁惠王上》"}, {"t": "直无由进之耳。", "b": "《荀子·礼论》"}, {"t": "直好世俗之乐耳。", "b": "《孟子·梁惠王下》"}, {"t": "直以为不能。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "直见爱甚。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "直当的", "t": "仅仅够得上;只值"}, {"w": "直好", "t": "只得;只好。"}]}, {"meaning": "简直。", "cites": [{"t": "是直用管窥天,用锥指地也。", "b": "《庄子·秋水》"}, {"t": "直可惊天地。", "b": "孙文《序》"}]}, {"meaning": "&X({tè})。单单,单独。", "cites": [{"t": "直好世俗之乐耳。", "b": "《孟子·梁惠王下》"}, {"t": "直立而不胜。", "b": "《荀子·不苟》"}, {"t": "直堕其履圮下。", "b": "《史记·留侯世家》"}]}, {"meaning": "伸直;挺直。", "cites": [{"t": "蓬生麻中,不扶而直。", "b": "《荀子·劝学》"}], "words": [{"w": "直身", "t": "伸直的身躯"}, {"w": "直直腰儿;把铁丝直一直;直脚", "t": "伸腿,死去"}, {"w": "直屡屡", "t": "挺直。"}]}, {"meaning": "伸雪。", "cites": [{"t": "妾虽死不敢诉也,而天使见之,为直其冤。", "b": "苏轼《子姑神记》"}]}, {"meaning": "面对着,当。", "cites": [{"t": "马各直其算。", "b": "《礼记·投壶》"}, {"t": "前列直斗口三星。", "b": "《史记·天官书》"}, {"t": "武库正直其墓。", "b": "《史记·樗里子甘茂传》"}, {"t": "魏之武卒,不可以直秦之锐士。", "b": "《汉书·刑法志》"}, {"t": "[主人]立阼阶下,直东序西面。", "b": "《仪礼·士冠礼》"}, {"t": "直夜溃围南出。", "b": "《史记·项羽本纪》"}]}, {"meaning": "遇,碰上。", "cites": [{"t": "管教他灵山会里直着个有缘人。", "b": "汤显祖《南柯记·宫训》"}]}, {"meaning": "当值,轮值,轮班。", "cites": [{"t": "王民为侍中,直于省内。", "b": "房玄龄《晋书》"}, {"t": "直使送之。", "b": "《战国策·齐策三》。注:“直,当日直使也。”"}], "words": [{"w": "直内", "t": "内廷值班的人"}, {"w": "值月", "t": "当值某月"}, {"w": "直房", "t": "值班室。"}]}, {"meaning": "担任。", "cites": [{"t": "宋孝武使直华林学省。", "b": "李延寿《南史》"}]}, {"meaning": "价值相当于。", "cites": [{"t": "为皮币,直四十万。", "b": "《史记·平淮书》"}, {"t": "岂闻一绢直万钱?", "b": "杜甫《惜昔诗》"}]}, {"meaning": "价值;代价。", "cites": [{"t": "爰得我直。", "b": "《诗·魏风·硕鼠》"}, {"t": "象床之直千金。", "b": "《战国策·齐策三》"}, {"t": "系向牛头充炭直。", "b": "唐·白居易《卖炭翁》"}, {"t": "昂其直。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "高其直。", "b": ""}]}, {"meaning": "工钱。", "cites": [{"t": "受若直,怠若事。", "b": "柳宗元《送薛存义之任序》"}]}, {"meaning": "即使。", "cites": [{"t": "人生直作百岁翁,亦是万古一瞬中。", "b": "《池州送孟迟先辈》"}], "words": [{"w": "直饶", "t": "即使。"}]}, {"meaning": "当…时候。", "cites": [{"t": "直夜溃围南出。", "b": "《史记·项羽本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1012wx','茁','1','zhuó','艹','8','','[{"pinyin": "zhuó", "defs": [{"meaning": "(会意。从艸,从出,出亦声。本义:植物才生长出来的样子)同本义。", "cites": [{"t": "茁,草初生出地貌。", "b": "《说文》"}, {"t": "彼茁者葭。", "b": "《诗·召南·驺虞》"}, {"t": "向东风种就,一亭兰茁,玉香初茂。", "b": "陈允平《过秦楼》"}], "words": [{"w": "茁茁", "t": "草刚长出的样子"}, {"w": "茁茂", "t": "茂盛"}, {"w": "茁肥", "t": "肥壮"}, {"w": "茁实", "t": "扎实;健壮结实。"}]}, {"meaning": "生出;生长。", "cites": [{"t": "牛羊茁壮长而已矣。", "b": "《孟子》。注:“生长貌。”"}, {"t": "曝干则为干看蕈,今深山穷民以此代耕,殆天茁此品,以遗其利也。", "b": "王祯《农书》"}], "words": [{"w": "茁芽", "t": "发芽。"}]}, {"meaning": "绽开,开。", "cites": [{"t": "蠹树高枝茁朵稠,嫩苞开破雪搓球。", "b": "张建《咏梨花》"}]}, {"meaning": "生。", "cites": [{"t": "霜髭茁病骨,饥坐听午钟。", "b": "苏轼《僧惠勒初罢僧职》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1013wx','茄','1','qié jiā','艹','8','','[{"pinyin": "qié", "defs": [{"meaning": "(形声。从艸,加声。本义:茄子。植物名) 同本义。", "cites": [{"t": "茄,夫渠茎。", "b": "《说文》"}]}, {"meaning": "茄科,一年生草本植物,叶椭圆形、花紫色,果实球形或长圆形、紫色、白色或浅绿色,表面光泽,是普通蔬菜;", "words": [{"w": "茄子", "t": "指该种植物的果实。"}]}, {"meaning": "一年生草本植物，花黄色。果实圆形，熟时红、黄色。", "words": [{"w": "番茄", "t": "西红柿。"}]}]}, {"pinyin": "jiā", "defs": [{"meaning": "荷梗", "words": [{"w": "茄房", "t": "即‘莲蓬’，以蓬实外苞分隔如房,故名"}]}, {"meaning": "", "words": [{"w": "茄袋", "t": "一种制作精致的小包,俗称荷包。随身佩带作什件,备放零钱或什物用。"}]}, {"meaning": "译音用字", "words": [{"w": "雪茄", "t": "一种烟草制品，由干燥及经过发酵的烟草卷制而成。"}]}, {"meaning": "一种上衣。", "words": [{"w": "茄克", "t": "一种短上衣,穿在上身的类似外套的短外衣,通常有前开门、领、翻领(卜头)、袖子及口袋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1014wx','茎','1','jīng','艹','8','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从艸,巠声。本义:植物的主干)。"}, {"meaning": "同本义。", "cites": [{"t": "茎,枝柱也。谓众枝之主。", "b": "《说文》"}, {"t": "茎,本也。", "b": "《广雅》。按,字从艸,艸曰茎,木日干。散文则草木枝亦皆曰茎。"}, {"t": "西方有木焉,名曰射干,茎长四寸。", "b": "《荀子·劝学》"}], "words": [{"w": "块茎;根茎;球茎;鳞茎;地上茎;地下茎;茎立", "t": "像草茎一样的直立"}, {"w": "茎英", "t": "古乐名。"}]}, {"meaning": "柱;竿。", "cites": [{"t": "抗仙掌以承露,擢双立之金茎。", "b": "《后汉书》"}]}, {"meaning": "小枝。", "cites": [{"t": "茎,小枝也。", "b": "唐·慧琳《一切经音义》"}]}, {"meaning": "器物的柄。", "cites": [{"t": "桃氏为剑,腊广二寸有半寸…以其腊广为之茎围,长倍之。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1015wx','苔','1','tāi tái','艹','8','','[{"pinyin": "tāi", "defs": [{"meaning": "——“舌苔”（shétāi）。"}, {"meaning": "舌上的垢腻。"}]}, {"pinyin": "tái", "defs": [{"meaning": "(形声。从艸,台声。本义:青苔;也指苔类植物)。"}, {"meaning": "植物名。本作菭。又名地衣,水衣。属隐花植物类,根、茎、叶区别不明显,有青、绿、紫等色,多生于阴湿地方,延贴地面,故亦叫“地衣”。", "cites": [{"t": "苔深不能扫,落叶秋风早。", "b": "李白《长干行》。又如:苔衣(即青苔。泛指苔藓类植物);苔岑(不同的苔生在同一山崖上。比喻志同道合的朋友相聚在一起);苔钱(即苔。因苔点形圆如铜钱,故称);苔茸(丛生的苔藓)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1016wx','茅','1','máo','艹','8','','[{"pinyin": "máo", "defs": [{"meaning": "(形声。从艸,矛声。本义:草名。即白茅,俗称茅草)。"}, {"meaning": "同本义。", "cites": [{"t": "茅,菅也。", "b": "《说文》。按,菅之不滑泽有毛者,可缩酒;又以为藉。"}, {"t": "藉用白茅。", "b": "《易·大过》"}, {"t": "昼尔于茅。", "b": "《诗·豳风·七月》"}, {"t": "祭祀共萧茅。", "b": "《周礼·甸师》"}, {"t": "白华菅兮,白茅束兮。", "b": "《诗·小雅·白华》"}, {"t": "山径之蹊,间介然用之而成路;为间不用,则茅塞之矣。", "b": "《孟子·尽心下》"}, {"t": "尔贡包茅不入。", "b": "《左传·僖公四年》"}, {"t": "卷我屋上三重茅。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "茅飞渡江;抱茅入竹;茅卜", "t": "古代卜法之一。琼茅是一种多年生的草,古人以为灵验,用琼茅来占卜吉凶称为茅卜"}, {"w": "茅店", "t": "茅草搭盖的客店。指简陋的旅舍"}, {"w": "茅茹", "t": "茅根相牵连的样子。喻同类事物之相互牵引"}, {"w": "茅茨", "t": "茅草屋。上古房屋都是茅顶,殷墟出土的宫室屋顶都覆以茅草"}, {"w": "茅塞", "t": "茅草蔽塞山路,不能通行。比喻人心遭受物欲蒙蔽,不能通透义理"}, {"w": "茅屋采椽", "t": "用茅草盖屋顶,柞木做屋橼。比喻居处的俭朴。"}]}, {"meaning": "竿顶用旄牛尾做装饰的旗帜。", "cites": [{"t": "郑伯肉袒,左执茅旌,右执鸾刀,以逆庄王。", "b": "《公羊传·宣公十二年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1017wx','枉','1','wǎng','木','8','','[{"pinyin": "wǎng", "defs": [{"meaning": "(形声。从木,王声。本义:弯曲;不正)。"}, {"meaning": "同本义。", "cites": [{"t": "枉,邪曲也。", "b": "《说文》"}, {"t": "是犹立直木而求其景之枉也。", "b": "《荀子·王霸》"}, {"t": "枉道速祸。", "b": "宋·司马光《训俭示康》"}, {"t": "枉用三尺。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "枉法营私", "t": "曲解、破坏法律,以谋求私利"}, {"w": "枉矢", "t": "不直的箭"}, {"w": "枉径", "t": "弯曲的小路"}, {"w": "枉策", "t": "弯曲的马鞭"}, {"w": "枉路", "t": "弯曲的道路"}, {"w": "枉渚", "t": "弯曲之渚"}, {"w": "枉木", "t": "曲木,弯木"}, {"w": "枉直", "t": "曲与直。比喻是非、好坏。"}]}, {"meaning": "邪恶。", "cites": [{"t": "举直错诸枉,能使枉者直。", "b": "《论语·颜渊》"}], "words": [{"w": "枉上", "t": "不正之君主"}, {"w": "枉邪", "t": "邪恶不正,亦指邪恶不正的人"}, {"w": "枉情", "t": "邪念。"}]}, {"meaning": "使受冤屈。", "cites": [{"t": "恒人见枉。", "b": "《论衡·问孔》"}, {"t": "其枉民也。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "枉状", "t": "歪曲事实,诬告别人的状文"}, {"w": "枉滥", "t": "枉法恣肆,使人无辜受害"}, {"w": "枉结", "t": "冤屈难解的事件"}, {"w": "枉抑", "t": "冤屈"}, {"w": "枉陷", "t": "冤枉陷害;无故陷害。"}]}, {"meaning": "违背。", "cites": [{"t": "税外加一物,皆以枉法论。", "b": "白居易《重赋》"}], "words": [{"w": "枉戾", "t": "谓歪曲颠倒"}, {"w": "枉屈", "t": "歪曲,违背"}, {"w": "枉墨矫绳", "t": "比喻违背准绳、准则"}, {"w": "枉道事人", "t": "本谓违背正道侍奉人。"}]}, {"meaning": "谦词。谓使对方受屈。", "cites": [{"t": "枉车骑过之。", "b": "《史记·魏公子列传》"}, {"t": "亲枉车骑。", "b": ""}], "words": [{"w": "枉驾", "t": "屈尊以相访。称人走访的敬词"}, {"w": "枉骑", "t": "屈尊相访。即枉驾"}, {"w": "枉人", "t": "谓枉劳人,麻烦别人"}, {"w": "枉才", "t": "指被埋没的人才"}, {"w": "枉口", "t": "屈服改口"}, {"w": "枉问", "t": "敬词。犹言承蒙问候"}, {"w": "枉访", "t": "屈尊就访"}, {"w": "枉语", "t": "屈尊告诉。"}]}, {"meaning": "徒然,白费。", "cites": [{"t": "还有枉抛心力处,多于五柳赋闲情。", "b": "唐·崔道融《读杜紫微集》"}], "words": [{"w": "枉费工夫;枉言", "t": "白说,空说"}, {"w": "枉沐", "t": "白白地蒙受"}, {"w": "枉苦", "t": "徒然;白白地"}, {"w": "枉劳", "t": "徒劳"}, {"w": "枉说", "t": "徒然说,白说"}, {"w": "枉杀", "t": "白费;辜负。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1018wx','林','1','lín','木','8','','[{"pinyin": "lín", "defs": [{"meaning": "(会意。从二木。表示树木丛生。本义:丛聚的树木或竹子)。"}, {"meaning": "同本义。", "cites": [{"t": "林,平土有丛木曰林。", "b": "《说文》"}, {"t": "野外谓之林。", "b": "《尔雅·释地》"}, {"t": "有鹤在林。", "b": "《诗·小雅·白华》"}, {"t": "每大林麓。", "b": "《周礼·地官·序官·林衡》。注:“竹木生平地曰林。”"}, {"t": "山中丛木曰林。林,森也。", "b": "《释名》"}, {"t": "忽逢桃花林,夹岸数百步。", "b": "晋·陶潜《桃花源记》"}, {"t": "蔽林间窥之。", "b": "《黔之驴》"}], "words": [{"w": "竹木林;山林", "t": "有山有树林的地方"}, {"w": "深山老林;防护林;林落", "t": "树林,丛林"}, {"w": "林浪", "t": "林琅、琳琅、林郎。丛林"}, {"w": "林麓", "t": "森林与山脚"}, {"w": "林泉", "t": "林木与泉石"}, {"w": "林错", "t": "林中树木交错,形容众多。"}]}, {"meaning": "指野外或退隐的地方。", "cites": [{"t": "富贵还乡国,光辉满旧林。", "b": "张说《和魏仆射还乡》"}], "words": [{"w": "林木", "t": "指山林田野退隐之处"}, {"w": "林下人", "t": "退隐之人。林,指退隐之地"}, {"w": "林丘", "t": "指隐居的地方。"}]}, {"meaning": "泛指人或事物的会聚,汇集处。", "cites": [{"t": "士有此五者,然后可以托于世,而列于君子之林矣。", "b": "司马迁《报任安书》"}], "words": [{"w": "林府", "t": "事物众多之处"}, {"w": "林薮", "t": "比喻事物聚集的处所。"}]}, {"meaning": "众多的样子。", "cites": [{"t": "林者,众也。万物成熟,种类众多也。", "b": "《白虎通》"}, {"t": "惟人之初,总总而生,林林而群。", "b": "柳宗元《贞符》"}], "words": [{"w": "林戈", "t": "如林之多。极言其多"}, {"w": "林立", "t": "如同树林一样密密麻麻地竖立着,形容数量很多。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1019wx','枝','1','zhī','木','8','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从木,支声。本义:主干上分出的茎条)。"}, {"meaning": "同本义。", "cites": [{"t": "枝,木别生条也。", "b": "《说文》"}, {"t": "草荄之枝。", "b": "《素问·移精变气论》"}, {"t": "千朵万朵压枝低。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "不蔓不枝。", "b": "宋·周敦颐《爱莲说》"}, {"t": "明月别枝惊鹊。", "b": "宋·辛弃疾《西江月》"}, {"t": "正用一枝鸣。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "枝任", "t": "树叶多的树枝"}, {"w": "枝末", "t": "树枝的梢头"}, {"w": "枝主", "t": "枝条和主干"}, {"w": "枝杪", "t": "树木枝条的梢头"}, {"w": "枝柯", "t": "枝条"}, {"w": "枝干", "t": "树枝和树干。"}]}, {"meaning": "古代指嫡长子以外的宗族子孙。", "cites": [{"t": "《诗》云:“本枝百世。”", "b": "《左传·庄公六年》"}], "words": [{"w": "枝庶", "t": "嫡长子以外的支系"}, {"w": "枝嗣", "t": "旁支的子孙"}, {"w": "枝萼", "t": "枝上的花萼。喻宗族旁支。"}]}, {"meaning": "人的手足与鸟兽翼足的总称。", "cites": [{"t": "四枝坚固。", "b": "《管子·内业》"}, {"t": "若生四枝。", "b": "《荀子·儒效》"}, {"t": "人之有形体四枝。", "b": "《吕氏春秋·圜道》"}]}, {"meaning": "通常是细长的从树主干或大枝上长出的细茎或者由植物芽苞长出的嫩茎或部分。", "cites": [{"t": "竹外桃花三两枝。", "b": "宋·苏轼《惠崇》"}, {"t": "春江晚景", "b": ""}], "words": [{"w": "一枝苹果花", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1020wx','杯','1','bēi','木','8','','[{"pinyin": "bēi", "defs": [{"meaning": "(形声。从木,不声。本义:盛酒、茶或其他饮料的器皿)。"}, {"meaning": "同本义,也称“耳杯”。", "cites": [{"t": "执觞觚杯豆而不醉。", "b": "《大戴礼记·曾子事父母》。注:“杯,盘盎盆盏之总名也。”"}, {"t": "杯圈不能饮焉。", "b": "《礼记·玉藻》"}, {"t": "停杯投箸不能食。", "b": "唐·李白《行路难》"}], "words": [{"w": "茶杯;杯茗", "t": "茶杯与茶水"}, {"w": "杯酒戈矛", "t": "比喻为一件小事大动干戈"}, {"w": "杯杓", "t": "酒杯和杓子。借指饮酒。"}]}, {"meaning": "表示以杯量的量。", "cites": [{"t": "劝君更尽一杯酒。", "b": "唐·王维《送元二使安西》"}, {"t": "浊酒一杯家万里。", "b": "宋·范仲淹《渔家傲》"}], "words": [{"w": "一杯水;三杯酒", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1021wx','枢','1','shū','木','8','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从木,区声。本义:户枢。旧式门的转轴或承轴臼)。"}, {"meaning": "同本义。", "cites": [{"t": "枢,户枢也。", "b": "《说文》"}, {"t": "枢谓这椳。又枢达北方谓之落时。", "b": "《尔雅》"}, {"t": "枢机之发。", "b": "《易·系辞》。注:“制动之主。”释文:“门臼也。”"}, {"t": "视门枢下当有白发。", "b": "《汉书·五行志》"}, {"t": "然陈涉瓮牖绳枢之子,甿隶之人,而迁徙之徒也。", "b": "汉·贾谊《过秦论》"}, {"t": "流水不腐,户枢不蝼,动也。", "b": "《吕氏春秋·尽数》"}], "words": [{"w": "枢户", "t": "解脱门枢。"}]}, {"meaning": "木名,即刺榆。", "cites": [{"t": "山有枢,隰有榆。", "b": "《诗·唐风·山有枢》"}]}, {"meaning": "泛指转轴。", "cites": [{"t": "半弦弧不满圜半径者,以矢为枢,以半弦弧规之,成浑圜之小规。", "b": "清·阮元《畴人传》"}]}, {"meaning": "又指主制动的机关。", "cites": [{"t": "其枢在水。", "b": "《管子·水地》。注:“主运转者也。”"}, {"t": "琴氏乃横弓着臂,施机设枢。", "b": "汉·赵晔《吴越春秋》"}], "words": [{"w": "枢干", "t": ""}]}, {"meaning": "中心;枢纽;关键。", "cites": [{"t": "今夫韩魏,中国之处,而天下之枢也。", "b": "《战国策·秦策》"}, {"t": "谓之道枢。", "b": "《庄子·齐物论》。释文:“要也。”"}], "words": [{"w": "枢柄", "t": "主要的权柄"}, {"w": "枢奥", "t": "中枢堂奥的所在"}, {"w": "枢秘", "t": "关键;纲要"}, {"w": "枢括", "t": "关键,中心"}, {"w": "枢管", "t": "枢辖。关键"}, {"w": "枢中", "t": "枢要中心。"}]}, {"meaning": "旧指国家政权或天子之位。", "cites": [{"t": "予除右丞相兼枢密使。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "枢垣", "t": "朝廷中重要的、接近皇帝的官署"}, {"w": "枢近", "t": "在天子近侧或中央机要的职位"}, {"w": "枢臣", "t": "指朝廷中枢的大臣"}, {"w": "枢府", "t": "国政机要之所。宋多指枢密院。宋朝枢密院与中书省分掌文武,号为二府"}, {"w": "枢使", "t": "枢密使的简称"}, {"w": "枢相", "t": "枢密使"}, {"w": "枢务", "t": "国家的重要政务。多指宰臣所掌的政事"}, {"w": "枢幄", "t": "枢密院"}, {"w": "枢衡", "t": "指中央行政机关。也指行政中枢的主要职权"}, {"w": "枢廷", "t": "政权中枢"}, {"w": "枢秘", "t": "指中央机要部门,犹枢要"}, {"w": "枢辖", "t": "指中央政权的机要部门"}, {"w": "枢辅", "t": "旧时指中央掌军权的大臣。"}]}, {"meaning": "星名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1022wx','柜','1','guì jǔ','木','8','','[{"pinyin": "guì", "defs": [{"meaning": "(形声。从木,匮(guì)声。本义:收藏衣物、书籍的家具)。"}, {"meaning": "小匣。", "cites": [{"t": "匮,匣也。从匚,贵声。俗作櫃。", "b": "《说文》"}, {"t": "将为胠箧探囊发匮之盗。", "b": "《庄子·胠箧》"}, {"t": "玉与石而同匮兮。", "b": "《楚辞·谬谏》"}, {"t": "楚人有卖其珠于郑者,为木兰之柜,董以桂椒,缀以珠玉,饰以玫槐,辑以悲翠。", "b": "《韩非子·外储左上》"}]}, {"meaning": "四周高起以蓄水的地方。", "cites": [{"t": "江边有田以柜称,四起封圉皆力成。", "b": "《元诗选·王祯·柜田》"}], "words": [{"w": "柜田", "t": ""}]}, {"meaning": "老板;掌柜的。", "cites": [{"t": "柜有话,你还不明白吗?", "b": "清·佚名《小五义》"}]}]}, {"pinyin": "jǔ", "defs": [{"meaning": "木名。柜柳,即“榉柳”。", "cites": [{"t": "柜,柜木也。从木,巨声。俗字作“榉”。似柳,皮可煮作饮。", "b": "《说文》"}, {"t": "性犹杞柳也。", "b": "《孟子》。注:“柜柳也。”"}, {"t": "柜,同榉。", "b": "《篇海类编》"}]}, {"meaning": "行马。古时官府门前拦阻通行的障碍物。", "cites": [{"t": "设梐柜再重。", "b": "《周礼·掌舍故书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1023wx','枚','1','méi','木','8','','[{"pinyin": "méi", "defs": [{"meaning": "(会意。从木,从攴(pū)。本义:树干)。"}, {"meaning": "同本义。", "cites": [{"t": "枚,枝干也。可为杖。", "b": "《说文》"}, {"t": "竹曰个,木曰枚。", "b": "《释名》"}, {"t": "枚,条也。", "b": "《广雅》"}, {"t": "施于条枚。", "b": "《诗·大雅·旱麓》"}, {"t": "遵彼汝坟,伐其条枚。", "b": "《诗·周南·汝坟》"}]}, {"meaning": "马鞭。", "cites": [{"t": "还于东门中,以枚数阖。", "b": "《左传·襄公十八年》"}]}, {"meaning": "古代行军时,士卒口衔用以防止喧哗的器具,形如筷子。", "cites": [{"t": "军士衔枚,夜登芒山,未明击之。", "b": "《北史》"}]}, {"meaning": "相当于“个”,“支”,“件”等。", "cites": [{"t": "六枚都使升空法,云端里面各翻腾。", "b": "《西游记》"}], "words": [{"w": "一枚铜钱", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1024wx','析','1','xī','木','8','','[{"pinyin": "xī", "defs": [{"meaning": "(会意。从木,从斤。用斧子劈开木头。本义:劈,劈木头)。"}, {"meaning": "同本义。", "cites": [{"t": "析,破木也。", "b": "《说文》"}, {"t": "析,劈也。", "b": "《声类》"}, {"t": "析薪如之何?匪斧不克。", "b": "《诗·齐风·南山》"}, {"t": "扶桑可薪,析木可焚,是桂永存。", "b": "明·方孝孺《双桂轩铭》"}], "words": [{"w": "析木", "t": "劈开木头"}, {"w": "析薪", "t": "劈柴。"}]}, {"meaning": "分析,辨认。", "cites": [{"t": "判天地之美,析万物之理。", "b": "《庄子·天下》"}, {"t": "奇文共欣赏,疑义相与析。", "b": "晋·陶潜《移居》"}], "words": [{"w": "析理", "t": "分析事物的道理"}, {"w": "析句", "t": "分析句子的结构、成分等"}, {"w": "析字", "t": "辨析字义"}, {"w": "析微", "t": "分析精深细微的道理"}, {"w": "析辩", "t": "分析论辩。"}]}, {"meaning": "分开;分散。", "cites": [{"t": "厥民析。", "b": "《书·尧典》。传:“其民老壮分析也。”"}, {"t": "逮归,季孟已有析烟之议。", "b": "宋·张今《范子严墓志》"}], "words": [{"w": "析骸以爨", "t": "折散尸骨当柴烧饭"}, {"w": "析箸", "t": "分家"}, {"w": "析耕", "t": "分开田产,各自耕作。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1025wx','板','1','bǎn','木','8','','[{"pinyin": "bǎn", "defs": [{"meaning": "(形声。从木,反声。《说文》作“版”。本义:片状的木头。后凡施于宫室器用的片状物皆可称板)。"}, {"meaning": "木板。", "cites": [{"t": "板,木片也。", "b": "《玉篇》"}, {"t": "在其板屋,乱我心曲。", "b": "《诗·秦风 ·小戎》"}, {"t": "五板而堵。", "b": "《公羊传·定公十二年》。注:“八尺曰板。”"}, {"t": "一丈为板。", "b": "《诗·鸿雁》传"}, {"t": "今一日而三斩板。", "b": "《礼记·檀弓》。"}], "words": [{"w": "板舆", "t": "由人扛抬的板车。古代老人的一种代步工具"}, {"w": "板梯", "t": "木板制的梯子"}, {"w": "板箱", "t": "大车的木板车厢。"}]}, {"meaning": "泛指板状的扁平之物。", "cites": [{"t": "先设一铁板,其上以松脂、蜡和纸灰之类冒之。", "b": "宋·沈括《梦溪笔谈·活板》"}]}, {"meaning": "又。", "cites": [{"t": "则以一平板按其面。", "b": ""}], "words": [{"w": "石板;钢板;纸板", "t": ""}]}, {"meaning": "笏,手板。古代官吏上朝时所执的记事板。", "cites": [{"t": "不得奉板中涓,预衣裳之会。", "b": "王僧孺《与何炯书》"}], "words": [{"w": "板笏;板书", "t": "在笏板上书写奏章。"}]}, {"meaning": "板筑用的夹板。", "cites": [{"t": "[筑城]平板桢。", "b": "《左传·宣公十一年》"}], "words": [{"w": "板筑", "t": "筑墙,用两板相夹,填土于其中,用杵捣实"}, {"w": "板堞", "t": "板筑的女墙。"}]}, {"meaning": "印板,印书用的板片。现用“版”。"}, {"meaning": "又。", "cites": [{"t": "以备一板内有重复者。", "b": ""}]}, {"meaning": "门窗的遮板,如店铺的门板。常作“板儿”。", "cites": [{"t": "吾从板外相为应答。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "铺子都上板儿了", "t": ""}]}, {"meaning": "结成硬块。", "cites": [{"t": "凡种绿豆,一日之内,遇大雨板土,则不复合。", "b": "宋应星《天工开物》"}], "words": [{"w": "板田", "t": "土壤板结的田"}, {"w": "板荒", "t": "板结的荒地。"}]}, {"meaning": "私营工商业的财产所有者。"}, {"meaning": "旧尊称戏剧演员。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1026wx','松','1','sōng','木','8','','[{"pinyin": "sōng", "defs": [{"meaning": "(形声。从木,公声。本义:松科植物的总称) 同本义。", "cites": [{"t": "松,松木也。", "b": "《说文》"}, {"t": "山有乔松。", "b": "《诗·郑风·山有扶苏》"}, {"t": "如松茂矣。", "b": "《诗·小雅·斯干》"}, {"t": "出户望南山,松生石上,剑在其背。", "b": "《搜神记·干将莫邪》"}]}, {"meaning": "发乱;乱发貌。", "cites": [{"t": "首蓬松以半散,支棘瘠而枯踈。", "b": "唐·陆龟蒙《自怜赋》"}]}, {"meaning": "不紧。", "cites": [{"t": "蜂须蝉翅薄松松,浮动搔头似有风。", "b": "唐·王建《宫词》"}], "words": [{"w": "松宽", "t": "亦作宽松。使行动有较大的自由,放松"}, {"w": "松松爽爽", "t": "轻松爽快"}, {"w": "松怠怠", "t": "赖散的样子"}, {"w": "松通", "t": "宽松,放宽。"}]}, {"meaning": "不中用。", "cites": [{"t": "有这等一个松驸马。", "b": "明·汤显祖《南柯记》"}]}, {"meaning": "慢 。围棋术语。", "cites": [{"t": "松,慢也。棋家取其玲珑透空,疏而不漏之谓也。", "b": "宋·徐铉《围棋义例》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1027wx','枪','1','qiāng','木','8','','[{"pinyin": "qiāng", "defs": [{"meaning": "(形声。从木,仓声。本义:二树的枝条互相抵拒)。"}, {"meaning": "古时长柄有尖头的刺击武器。", "cites": [{"t": "枪,歫也。", "b": "《说文》。按,歫人之械也。"}, {"t": "枪,谓木两 头锐者也。", "b": "《苍颉篇》"}, {"t": "剡木伤盗曰枪。", "b": "《通俗文》"}, {"t": "挟其枪刈耨刈。", "b": "《国语·齐语》。注:“桩也。”"}, {"t": "铁骑突出刀枪鸣。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "枪刺应元。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "红缨枪;枪缨", "t": "枪上用丝、线等做成的穗状饰物。"}]}, {"meaning": "武器名。火铳,火枪;发射子弹的火器。同“鎗”。", "cites": [{"t": "开枪者。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "枪声隆然。", "b": "清·徐珂《青稗类钞·战事类》"}, {"t": "众枪齐发。", "b": ""}, {"t": "发枪之号。", "b": ""}, {"t": "都带着洋枪,还怕什么呢?", "b": "《老残游记》"}], "words": [{"w": "枪火", "t": "指枪支弹药"}, {"w": "枪把子", "t": "枪柄。比喻权柄"}, {"w": "枪材", "t": "制作枪柄的木材"}, {"w": "枪枝", "t": "同“枪支”"}, {"w": "枪竿", "t": "竖立的枪身"}, {"w": "枪疤", "t": "枪伤后留下的伤疤"}, {"w": "枪珠", "t": "炮弹"}, {"w": "枪柱", "t": "枪上可以推送子弹进枪膛的机件。"}]}, {"meaning": "触,撞,碰撞。", "cites": [{"t": "枪榆坊而止。", "b": "《庄子·逍遥游》"}, {"t": "见狱吏则头枪地。", "b": "司马迁《报任少卿书》"}], "words": [{"w": "枪榆", "t": "形容识浅志小,亦指识浅志小的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1028wx','枫','1','fēng','木','8','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。从木,风声。本义:木名。即枫香树)。"}, {"meaning": "同本义。", "cites": [{"t": "枫,枫木也。厚叶弱枝,善摇。", "b": "《说文》"}, {"t": "枫欇欇。", "b": "《尔雅·释木》。注:“树似白杨,叶圆而岐,有脂而香。”孙注:“生江上,有寄生枝,高三四尺,生毛,一名枫子,天旱,以泥泥之,即雨。”"}, {"t": "湛湛江水兮上有枫。", "b": "《楚辞》"}]}, {"meaning": "落叶乔木,春季开花,黄褐色。叶子掌状三裂,秋季变成红色。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1029wx','构','1','gòu','木','8','','[{"pinyin": "gòu", "defs": [{"meaning": "(会意。古字为“冓。从木,冓(góu)声。字本作“冓”,金文象屋架两面对构形。本义:架木造屋)。"}, {"meaning": "同本义。", "cites": [{"t": "冓,交积材也。", "b": "《说文》"}, {"t": "构,盖也。", "b": "《说文》"}]}, {"meaning": "字亦作“搆”。", "cites": [{"t": "大搆驾,兴宫室。", "b": "《淮南子·本经》"}, {"t": "筑土构木。", "b": "《淮南子·泛论》"}, {"t": "观其结构。", "b": "《鲁灵光殿赋》"}, {"t": "有圣人作,构木为巢以避群害,而民悦之,使王天下,号之曰有巢氏。", "b": "《韩非子·五蠹》"}, {"t": "骊山北构而西折,直走咸阳。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "构木", "t": "架木造物"}, {"w": "构天", "t": "构造天地"}, {"w": "构巢", "t": "构木为巢"}, {"w": "构厦", "t": "营造大厦"}, {"w": "构第", "t": "营造宅第。"}]}, {"meaning": "构成,造成。", "cites": [{"t": "邪秽在身,怨之所构。", "b": "《荀子·劝学》"}, {"t": "楚尝与秦构难,战于汉中。", "b": "《史记·张仪列传》"}], "words": [{"w": "构难", "t": "结成怨仇"}, {"w": "构怨", "t": "结怨"}, {"w": "构愁", "t": "结怨,结仇。"}]}, {"meaning": "招致,引起。", "cites": [{"t": "相(视)彼泉水,载清载浊。我日构祸,曷云能穀?", "b": "《诗·小雅·四月》"}, {"t": "吾闻秦楚构兵。", "b": "《孟子·告子》"}], "words": [{"w": "构乱", "t": "叛乱"}, {"w": "构战", "t": "交战"}, {"w": "构兵", "t": "交兵;交战"}, {"w": "构祸", "t": "造成祸乱。"}]}, {"meaning": "诬陷,陷害。", "cites": [{"t": "宣姜与公子朔构急子。", "b": "《左传·桓公十六年》"}], "words": [{"w": "构害", "t": "谋害,陷害"}, {"w": "构抉", "t": "搜寻捏造"}, {"w": "构死", "t": "诬陷而死。"}]}, {"meaning": "挑拨离间。", "cites": [{"t": "彼实构吾二君,寡君若得而食之,不厌。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "构结", "t": "勾结串通"}, {"w": "构扇", "t": "挑衅扇动"}, {"w": "构间", "t": "挑拨离间"}, {"w": "构合", "t": "从中挑拨,使彼此结成嫌隙。"}]}, {"meaning": "连结,交合。", "cites": [{"t": "秦楚之构而不离。", "b": "《战国策·秦策》"}], "words": [{"w": "构结", "t": "勾结"}, {"w": "构精", "t": "男女交合"}, {"w": "构云", "t": "连接云天"}, {"w": "构致", "t": "聚集招致。"}]}, {"meaning": "遭遇。", "cites": [{"t": "我日构祸,曷云能谷?", "b": "《诗·小雅·四月》"}]}, {"meaning": "悬赏,收买。", "cites": [{"t": "其次伍有罪,若能身捕罪人,若告之吏,皆构之。", "b": "《墨子·号令》"}], "words": [{"w": "构赏", "t": "收买悬赏。"}]}, {"meaning": "(jiǎng)。"}, {"meaning": "解释。", "cites": [{"t": "是非辐凑,上不与构。", "b": "《韩非子·扬权》"}]}, {"meaning": "和解。", "cites": [{"t": "已乃知文侯以构于己,乃皆朝魏。", "b": "《韩非子·说林下》"}]}, {"meaning": "房屋,屋宇,供人居住的木、砖瓦构筑物。", "cites": [{"t": "近因顶有新构,遂称此为寺云。", "b": "《徐霞客游記》"}]}, {"meaning": "业绩。", "cites": [{"t": "顾临兆民,永怀先构。", "b": "《南齐书》"}]}, {"meaning": "(gōu)。篝火。", "cites": [{"t": "夜于丛祠中构火。", "b": "《前汉纪.高祖纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1030wx','杭','1','háng','木','8','','[{"pinyin": "háng", "defs": [{"meaning": "(形声。从木,亢(kāng)声。(Káng)本义:抵御)。"}, {"meaning": "方舟并济或以船渡。", "cites": [{"t": "杭,渡也。", "b": "《说文》"}, {"t": "谁谓河广?一苇杭之!", "b": "《诗·卫风·河广》"}, {"t": "魂中道而无杭。", "b": "《楚辞·九章·惜诵》"}], "words": [{"w": "杭筏", "t": "渡水的筏子"}, {"w": "杭绝", "t": "乘船渡过。"}]}, {"meaning": "航行。", "cites": [{"t": "惩往途而省究兮,吾庶以慎吾杭。", "b": "明·何景明《进舟赋》"}]}, {"meaning": "方舟;船。", "cites": [{"t": "杭,方舟也。", "b": "《说文》"}, {"t": "盖周跃鱼陨杭。", "b": "《史记·司马相如传》"}], "words": [{"w": "杭绝", "t": "乘船渡过。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1031wx','杰','1','jié','木','8','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从人,桀(jié)声。杰为傑的俗字。本义:才智出众的人)。"}, {"meaning": "同本义。", "cites": [{"t": "五人曰茂,十人曰选,百人曰俊,千人曰英,倍英曰贤,万人曰杰,万杰曰圣。", "b": "《白虎通圣人引辨名记》"}, {"t": "命太尉赞杰俊。", "b": "《礼记·月令》"}, {"t": "俊杰在位。", "b": "《孟子》"}, {"t": "小国英杰之士。", "b": "《战国策·齐策》"}, {"t": "英杰化之。", "b": "《荀子·儒效》"}, {"t": "子房、萧何、韩信,三者皆人杰也。", "b": "《汉书·高祖纪》"}], "words": [{"w": "人杰", "t": "才智超群的人"}, {"w": "英杰", "t": "豪杰。才能出众的人"}, {"w": "杰士", "t": "才智特出的人;杰出的人。"}]}, {"meaning": "作标志用的小木椿。", "cites": [{"t": "吏卒民各自大书于杰。", "b": "《墨子·号令》"}]}, {"meaning": "卓异的;出色的。", "cites": [{"t": "雄姿杰出。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "杰立", "t": "卓绝出众"}, {"w": "杰句", "t": "佳句"}, {"w": "杰表", "t": "不凡的仪表"}, {"w": "杰思", "t": "出色的构思"}, {"w": "杰笔", "t": "杰出的文笔。"}]}, {"meaning": "高大;高耸。", "cites": [{"t": "杰屋大像无时止,安得疲民免饥死。", "b": "陆游《僧庐》"}, {"t": "又有一石,不附山,杰然特起。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "杰然", "t": "高大的样子"}, {"w": "杰阁", "t": "高耸的楼阁"}, {"w": "杰观", "t": "高大的楼阁"}, {"w": "杰秀", "t": "高峻秀美"}, {"w": "杰屈", "t": "指高大的楼房。"}]}, {"meaning": "凶暴。", "cites": [{"t": "乃悉召杰黠少年素为乡里患者,置为主帅。", "b": "《北史·韩褒传》"}], "words": [{"w": "杰黠", "t": "凶猛而狡黠"}, {"w": "杰滑", "t": "凶猛狡诈"}, {"w": "杰暴", "t": "强悍凶暴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1032wx','述','1','shù','辶','8','','[{"pinyin": "shù", "defs": [{"meaning": "(形声。从辵(chuò),术声。本义:遵循)。"}, {"meaning": "同本义。", "cites": [{"t": "述,循也。", "b": "《说文》"}, {"t": "报我不述。", "b": "《诗·邶风·日月》"}, {"t": "遂述命曰。", "b": "《仪礼·少牢礼》"}, {"t": "述大禹之戒以作歌。", "b": "《书·五子之歌》"}], "words": [{"w": "述遵", "t": "遵循"}, {"w": "述旧", "t": "遵行旧规"}, {"w": "述祖", "t": "遵循祖训。"}]}, {"meaning": "陈述,记叙。", "cites": [{"t": "识礼乐之文者能述。", "b": "《礼记·乐记》"}, {"t": "小有述职。", "b": "《左传·昭公五年》"}, {"t": "诸侯朝于天子曰述职。", "b": "《孟子》"}, {"t": "后常流涕述其事以语人,曰:“吾师肺肝,皆铁石所铸造也。”", "b": "清·方苞《左忠毅公逸事》"}, {"t": "成述其异,宰不信。试与他虫斗,虫尽靡。又试之鸡,果如成言。", "b": "《聊斋志异·促织》"}], "words": [{"w": "综述", "t": "综合叙述"}, {"w": "口述;重述一遍;述知", "t": "陈述;告诉"}, {"w": "述事", "t": "陈述事理"}, {"w": "述载", "t": "陈述记载"}, {"w": "述圣", "t": "陈述圣人之道"}, {"w": "述历", "t": "一一陈述"}, {"w": "述而不作", "t": "传述先哲的理论,不再自创新意。"}]}, {"meaning": "传述;传承;阐述前人成说。", "cites": [{"t": "述而不作,信而好古。", "b": "《论语·述而》"}], "words": [{"w": "述宣", "t": "继承和发扬"}, {"w": "述修", "t": "修治;修明"}, {"w": "述附", "t": "承袭。"}]}, {"meaning": "泛指叙述的文字。", "cites": [{"t": "醉能同其乐,醒能述以文者,太守也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "此则岳阳楼之大观也,前人之述备矣。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "德琏常斐然有述作之意,其才学足以著书。", "b": "三国魏·曹丕《与吴质书》"}], "words": [{"w": "述作", "t": "著作"}, {"w": "述撰", "t": "撰述;著作"}, {"w": "述制", "t": "记述;著作"}, {"w": "述造", "t": "著作。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1033wx','枕','1','zhěn','木','8','','[{"pinyin": "zhěn", "defs": [{"meaning": "(形声。从木。本义:枕头)。"}, {"meaning": "同本义。", "cites": [{"t": "枕,卧所荐首也。", "b": "《说文》"}, {"t": "辗转伏枕。", "b": "《诗·陈风·泽陂》"}, {"t": "险且枕。", "b": "《易·坎》。郑注:“木在首曰枕”。陆绩注:“枕闲碍险害之貌。”"}, {"t": "三窟已就,君姑高枕为乐矣。", "b": "《战国策》。"}], "words": [{"w": "枕上之花", "t": "比喻女色"}, {"w": "枕箱", "t": "可作枕头使用的长方形扁箱。出门旅行时放置零物"}, {"w": "枕山", "t": "谓垫得很高的枕头"}, {"w": "枕中术", "t": "藏在枕中的秘术"}, {"w": "枕中书", "t": "珍秘之书。"}]}, {"meaning": "枕骨。", "cites": [{"t": "头横骨为枕。", "b": "《素问·骨空论》"}]}, {"meaning": "枕着。", "cites": [{"t": "曲肱而枕之。", "b": "《论语》"}, {"t": "吾枕戈待旦,志枭逆虏。", "b": "《晋书》"}, {"t": "尸骸枕藉。", "b": "清·邵长蘅《青门剩稿》。"}], "words": [{"w": "枕弓", "t": "犹枕戈"}, {"w": "枕戈汗马", "t": "枕着武器,疾驰战马。形容时刻准备杀敌立功"}, {"w": "枕石", "t": "枕于石头。多指隐居山林"}, {"w": "枕甲", "t": "枕着铠甲。"}]}, {"meaning": "靠近,临。", "cites": [{"t": "会稽东接于海,南近诸越,北枕大江。", "b": "《汉书·严助传》。"}], "words": [{"w": "枕江", "t": "临江"}, {"w": "枕河", "t": "临河"}, {"w": "枕水", "t": "靠近水边"}, {"w": "枕流", "t": "靠近水流。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1034wx','丧','1','sāng sàng','一','8','','[{"pinyin": "sāng", "defs": [{"meaning": "丧仪;丧事 。在埋葬或火化前为死者举行的哀悼仪式。泛指丧事,人死后殓、奠殡、葬等事宜。", "cites": [{"t": "秦不哀吾丧而伐吾同姓,秦则无礼。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "丧纪", "t": "丧事"}, {"w": "丧宰", "t": "主持丧事的人"}, {"w": "丧家", "t": "有丧事的人家"}, {"w": "治丧", "t": "办理丧事"}, {"w": "丧车", "t": "送葬者坐的车"}, {"w": "丧制", "t": "治丧的礼制"}, {"w": "丧庭", "t": "灵堂"}, {"w": "丧器", "t": "丧事用器具"}, {"w": "丧荒", "t": "指诸侯臣下的丧事及荒年。"}]}, {"meaning": "人的尸体、骨殖。", "cites": [{"t": "丧(灵柩;殡仪队)出江上,白衣冠送者夹岸,酹而哭者百里不绝。", "b": "《明史·海瑞传》"}], "words": [{"w": "丧次", "t": "停灵治丧的地方"}, {"w": "丧具", "t": "人死后所需的棺椁、衣被之类"}, {"w": "丧柩", "t": "灵柩"}, {"w": "丧灵", "t": "死尸;灵柩。"}]}, {"meaning": "祸难。", "cites": [{"t": "自经丧乱少睡眠,长夜沾湿何由彻!", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "丧氛", "t": "预兆死亡的云气"}, {"w": "丧祸", "t": "丧乱"}, {"w": "丧乱", "t": "死亡;祸乱。"}]}, {"meaning": "服丧,持丧。", "cites": [{"t": "子上之母死而不丧。", "b": "《礼记·檀弓上》"}], "words": [{"w": "居丧;国丧;号丧", "t": "遭亲丧而哭泣致哀"}, {"w": "丧人", "t": "居丧的人"}, {"w": "丧居", "t": "丧家所在"}, {"w": "丧食", "t": "礼制规定的居丧时的饮食"}, {"w": "丧音", "t": "报丧的声音"}, {"w": "丧冠", "t": "服丧时所戴的一种帽子"}, {"w": "丧娶", "t": "在服丧期间婚娶"}, {"w": "丧期", "t": "服丧的期限"}, {"w": "丧帻", "t": "居丧时戴的头巾"}, {"w": "丧幡", "t": "丧家挂白条旗。"}]}, {"meaning": "悲悼;伤悼。", "cites": [{"t": "狂夫乐之,贤者丧焉。", "b": "《商君书·更法》"}]}]}, {"pinyin": "sàng", "defs": [{"meaning": "(会意。小篆字形,上面是“哭’,下面是“亡”。表示哭已死去的人。本义:丧失)。"}, {"meaning": "同本义。", "cites": [{"t": "喪,亡也。", "b": "《说文》"}, {"t": "东北丧朋。", "b": "《易·坤》。马注:“失也。”"}, {"t": "受禄无丧。", "b": "《诗·大雅·皇矣》"}, {"t": "问丧无夫子乎。又,丧人无以为宝。", "b": "《礼记·檀弓》"}, {"t": "宣王既丧南国之师。", "b": "《国语·周语》"}, {"t": "非独贤者有是心也,人皆有之,贤者能勿丧耳。", "b": "《孟子·告子上》"}, {"t": "偃王行仁义而丧其国。", "b": "《韩非子·五蠹》"}], "words": [{"w": "丧明", "t": "眼睛失明"}, {"w": "丧检", "t": "丧失德行,失去检点"}, {"w": "丧履", "t": "失去庇护"}, {"w": "丧精", "t": "失神"}, {"w": "丧心", "t": "心理反常;丧失理智"}, {"w": "丧志", "t": "丧失心志"}, {"w": "丧律", "t": "丧失军纪"}, {"w": "丧师", "t": "失去民心"}, {"w": "丧师辱国", "t": "军队损失,国家蒙受耻辱"}, {"w": "丧资", "t": "失去财产。"}]}, {"meaning": "死去。", "cites": [{"t": "小人多欲则多求妄用,败家丧身。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "丧躯", "t": "丧身"}, {"w": "丧元", "t": "掉头颅"}, {"w": "丧仆", "t": "亡身"}, {"w": "丧身", "t": "丧命"}, {"w": "丧没", "t": "灭亡,死亡"}, {"w": "丧明之痛", "t": "丧子之痛"}, {"w": "丧亲", "t": "父或母亡"}, {"w": "丧室", "t": "妻室丧亡"}, {"w": "丧家子", "t": "丧失其家无所依存的人。"}]}, {"meaning": "灭亡;失败。", "cites": [{"t": "六国互丧,率赂秦耶?", "b": "宋·苏洵《六国论》"}], "words": [{"w": "丧师", "t": "战败"}, {"w": "丧国之社", "t": "国家灭亡,无人祭祀的宗庙"}, {"w": "丧师", "t": "战败而损失军队"}, {"w": "丧陷", "t": "失陷"}, {"w": "丧败", "t": "因失败而受损失。"}]}, {"meaning": "忘记,忘掉。", "cites": [{"t": "今者吾丧我,汝知之乎?", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1035wx','或','1','huò','戈','8','','[{"pinyin": "huò", "defs": [{"meaning": "(会意。甲骨文字形从囗(象城形),从戈(以戈守之)。表示以戈卫国。本义:国家。用本义时读yù)有人,有的——泛指人或事物。", "cites": [{"t": "或,有也。", "b": "《小尔雅·广言》"}, {"t": "或跃在渊。", "b": "《易·乾》"}, {"t": "殷其弗或乱正四方。", "b": "《书·微子》"}, {"t": "或群或友。", "b": "《诗·小雅·吉日》"}, {"t": "庶或饷之。", "b": "《礼记·祭义》"}, {"t": "或赐二小人酒。", "b": "《左传·昭公二十八年》"}, {"t": "或说处杀虎斩蛟。", "b": "《世说新语·自新》"}, {"t": "或立或卧。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "或坐或俯。", "b": ""}, {"t": "或笑或哭。", "b": ""}, {"t": "或饮或博。", "b": ""}], "words": [{"w": "或人", "t": "某人。不称名而暗指的人。有些人"}, {"w": "或时", "t": "有时"}, {"w": "或一,或种", "t": "某种"}, {"w": "或日", "t": "某日,有一天。"}]}, {"meaning": "用作虚词  表示选择或列举。如:或是(连词。表示选择或并列关系);或乃(或者。常用于句首表示变换叙述内容) 在不同或不相似的事物、状况或行动之间的一个抉择。如:有病或无病,他不都应该在这里 近似、可疑或不肯定。如:在五天或六天之内 两个词或两个短语同义、等义或替换的性质。", "cites": [{"t": "或尽粟一石。", "b": "唐·韩愈《杂说》"}, {"t": "君实或见恕。", "b": "宋·王安石《答司马谏议书》"}, {"t": "或异二者之为。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "或能免乎。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "跌下悬崖或峭壁", "t": ""}]}, {"meaning": "间或,有时。", "cites": [{"t": "或长烟一空。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "或至相殴。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "或时", "t": "有时。"}]}, {"meaning": "迷惑。", "cites": [{"t": "夜半,而城上四面鼓噪,敌人必或。", "b": "《墨子·备蛾传》"}, {"t": "无或乎王之不智也。", "b": "《孟子·告子上》"}, {"t": "擅创为令,迷或其君。", "b": "《管子·回称》"}, {"t": "买则失实,卖则失理,其疑或滋益甚。", "b": "《盐铁论·错币》"}, {"t": "贫贱吾恐其或失也。", "b": "《大戴礼记·曾子制言》"}, {"t": "别从东道,或失道。", "b": "《汉书·霍去病传》"}, {"t": "惟恐或后。", "b": "清·周容《芋老人传》"}], "words": [{"w": "或或", "t": "迷惑。或,通惑"}, {"w": "或乱", "t": "昏乱;惑乱"}, {"w": "或疑", "t": "怀疑,疑惑;有人怀疑。"}]}, {"meaning": "语气词,在否定句中加强否定语气。", "cites": [{"t": "莫或兴之。", "b": "清·黄宗羲《原君》"}, {"t": "莫或除之。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1036wx','画','1','huà','田','8','','[{"pinyin": "huà", "defs": [{"meaning": "(会意兼指事。金文。上面是“聿”(yù),象以手执笔的样子,是“笔”的本字;下面象画出的田界。整个字形,象人持笔画田界之形。本义:划分,划分界线)。"}, {"meaning": "同本义。", "cites": [{"t": "画,界也,象田四界,聿所以画之。", "b": "《说文》"}, {"t": "画为九州。", "b": "《左传·襄公四年》"}, {"t": "画壄分州。", "b": "《汉书·地理志上》"}], "words": [{"w": "画野分疆", "t": "划分疆域而治"}, {"w": "画土分贡", "t": "中国古代实行分封制,天子划分封地给诸侯,诸侯定期向天子朝贡"}, {"w": "画地", "t": "在地上画界线"}, {"w": "画界", "t": "划定疆界。"}]}, {"meaning": "绘画;作画。", "cites": [{"t": "为蛇画足。", "b": "清·全祖望《梅花岭记》"}, {"t": "善画者多工书。", "b": "蔡元培《图画》"}, {"t": "善画者或兼建筑。", "b": ""}], "words": [{"w": "画学", "t": "绘画的学问"}, {"w": "画壁", "t": "在墙壁上作画"}, {"w": "画革", "t": "在皮革上书写"}, {"w": "画癖", "t": "喜爱绘画艺术成癖。"}]}, {"meaning": "截止;停止。", "cites": [{"t": "力不足者,中道而废,今女画。", "b": "《论语》。何晏集解引孔安国曰:“画,止也……自女自止耳,非力极。”"}, {"t": "百川学海而至于海,丘陵学山不至于山,是故恶夫画也。", "b": "汉·扬雄《法言》。李轫注:“画,止。”"}]}, {"meaning": "谋划;策划。", "cites": [{"t": "画,计也,策也。", "b": "《说文》"}, {"t": "孝公平画。", "b": "《商君书·更法》"}, {"t": "助画方略。", "b": "《资治通鉴》"}], "words": [{"w": "画策", "t": "计划;筹划"}, {"w": "划事", "t": "筹划事情"}, {"w": "画制", "t": "筹画制度"}, {"w": "画计", "t": "谋画。"}]}, {"meaning": "横划过去。", "cites": [{"t": "曲终收拨当心画。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "成品画。", "cites": [{"t": "画果真邪。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "不设色之画。", "b": "蔡元培《图画》"}, {"t": "中国之画。", "b": ""}, {"t": "西人之画。", "b": ""}], "words": [{"w": "画本", "t": "泛指画册"}, {"w": "画卷", "t": "裱后带轴的长幅图画。"}]}, {"meaning": "计策;计谋。", "cites": [{"t": "后乃谋臣献画,而离削自守矣。", "b": "柳宗元《封建论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1037wx','卧','1','wò','卜','8','','[{"pinyin": "wò", "defs": [{"meaning": "(会意。从人臣。“臣”是竖立的眼睛。本义:人伏在几案上休息,眼睛呈竖立形)。"}, {"meaning": "同本义。", "cites": [{"t": "坐而言,不应,隐几而卧。", "b": "《孟子》。焦循正义:“卧与寝异,寝于床,卧于几。统言之则不别。”"}, {"t": "一生伏案卧。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "躺;卧而不眠。", "cites": [{"t": "弛然而卧。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "溪头卧剥莲蓬。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "卧听风吹雨。", "b": "宋·陆游《十一月四日风雨大作》"}, {"t": "僵卧孤村不自哀。", "b": "宋·陆游《示儿》"}, {"t": "或立或卧。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "卧冰", "t": "卧于冰上。古孝子卧冰事母的故事"}, {"w": "卧碑", "t": "规矩。原指明清两代在明伦堂立的石碑,上面刻着约束生员的条文"}, {"w": "卧治", "t": "躺着治事。指无为而治"}, {"w": "卧佛", "t": "横卧的佛像。即释迦的涅槃像"}, {"w": "卧理", "t": "躺着理事。同“卧治”"}, {"w": "卧苫枕块", "t": "卧于草垫上,以土块作枕头。指人子守父母之丧而言。同“寝苫枕块”"}, {"w": "卧甲", "t": "不解甲而卧。有枕戈待敌之意。"}]}, {"meaning": "眠,睡。", "cites": [{"t": "暮卧则梦闻。", "b": "《论衡·订鬼》"}], "words": [{"w": "卧不安席", "t": "睡不安宁。形容心事重重"}, {"w": "卧处", "t": "指睡卧起居;寝卧之所"}, {"w": "卧起", "t": "寝卧和起身。多指日常生活诸事"}, {"w": "卧榻之侧", "t": "床铺旁边。比喻距离很近或在自己的管辖范围之内。"}]}, {"meaning": "倒伏;横陈。", "cites": [{"t": "长桥卧波。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "横卧一楫。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "卧辙", "t": "卧于道路上阻止行车。后用作挽留去职官吏的用语"}, {"w": "卧骨", "t": "谓死于沙场"}, {"w": "卧翻", "t": "将牲兽翻倒。"}]}, {"meaning": "燠,暖。", "cites": [{"t": "屈木为棬,以张生绢袋子,滤热乳,著瓦瓶子中卧之。", "b": "《齐民要术》"}]}, {"meaning": "趴伏。", "cites": [{"t": "卧右膝。", "b": "明·魏学洢《核舟记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1038wx','事','1','shì','亅','8','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从史,之省声。史,掌管文书记录。甲骨文中与“吏”同字。本义:官职)。"}, {"meaning": "同本义。", "cites": [{"t": "事,职也。", "b": "《说文》"}, {"t": "无功而受事,无爵而显荣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "事宦", "t": "仕宦。事通“仕”。"}]}, {"meaning": "引申为职守;政事;事务。", "cites": [{"t": "事,勤也。", "b": "《尔雅》"}, {"t": "为政事庸力行务。", "b": "《左传·昭公二十五年》。注:“在君为政,在臣为事。”"}, {"t": "事蚤济也。", "b": "《礼记·乐记》"}, {"t": "事至佚而功。", "b": "《荀子·王霸》。注:“任也。”"}, {"t": "陉山之事。", "b": "《战国策·秦策》。注:“役也。”"}, {"t": "公侯之事。", "b": "《诗·召南·采蘩》"}, {"t": "王事多难。", "b": "《诗·小雅·出车》"}, {"t": "赵太后新用事,秦急攻之。", "b": "《战国策·赵策》"}, {"t": "余将告于莅事者,更若役,复若赋,则何如?", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "事分", "t": "职分;名分。"}]}, {"meaning": "职业。", "cites": [{"t": "舞阳侯樊哙者,沛人也。以屠狗为事。", "b": "《史记》"}]}, {"meaning": "事情。", "cites": [{"t": "子入太庙,每事问。", "b": "《论语·八佾》"}, {"t": "敏于事而慎于言。", "b": "《论语·学而》"}, {"t": "事无大小悉以咨之。", "b": "诸葛亮《出师表》"}, {"t": "天下之事有难易乎?", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "闻其师为弟子说前代事。", "b": "清·周容《芋老人传》"}]}, {"meaning": "事业。", "cites": [{"t": "若事之不济,此乃天也。", "b": "《资治通鉴》"}, {"t": "他日继吾志事,惟此生耳。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "事绩", "t": "业绩,重大的成就"}, {"w": "事济", "t": "事业完成。"}]}, {"meaning": "事故,事件。", "cites": [{"t": "延及孝文王、庄襄王,享国之日浅,国家无事。", "b": "汉·贾谊《过秦论上》"}, {"t": "而士大夫亦未尝言兵,以为生事扰民,渐不可长。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "事款则圆", "t": "遇事要从长计议,才能圆满解决。"}]}, {"meaning": "典故;故事。", "cites": [{"t": "汝来床前,为说稗官野史可喜可愕之事,聊资一欢。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "情况,情形。", "cites": [{"t": "论战斗之事,则缩颈而股栗。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "事色", "t": "情况,情势。"}]}, {"meaning": "侍奉;供奉。", "cites": [{"t": "奉事循公姥,进止敢自专?", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "安能摧眉折腰事权贵,使我不得开心颜!", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "事君;事师;事奉", "t": "供奉;侍奉"}, {"w": "事上", "t": "事奉尊长"}, {"w": "事畜", "t": "侍奉父母,养育妻子"}, {"w": "事亲", "t": "侍奉父母。"}]}, {"meaning": "做,从事。", "cites": [{"t": "回虽不敏,请事斯语矣。", "b": "《论语·颜渊》"}, {"t": "居数月,漠然无所事。", "b": "清·方苞《狱中杂记》"}, {"t": "其游惰不事者何能一一遵上之约束乎?", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "无所事事;不事生产;事本", "t": "从事本业"}, {"w": "事力", "t": "从事体力劳动"}, {"w": "事行", "t": "做事;行事。"}]}, {"meaning": "使用;役使。", "cites": [{"t": "不事而自然谓之性。", "b": "《荀子·正名》。注:“事任使也。”"}, {"t": "备承事也。", "b": "《国语·鲁语下》"}, {"t": "坐事国人过律。", "b": "《史记·傅靳蒯成传》"}, {"t": "尚安事客!", "b": "《信陵君窃符救赵》"}], "words": [{"w": "事役", "t": "劳役"}, {"w": "事智", "t": "运用智慧"}, {"w": "事用", "t": "使用;应用。"}]}, {"meaning": "奉行。", "cites": [{"t": "今管仲不务尊主明法,而事增宠益爵。", "b": "《韩非子》"}]}, {"meaning": "治理;办理。", "cites": [{"t": "齐、魏得地葆利,而详事下吏。", "b": "《战国策》"}]}, {"meaning": "任用。", "cites": [{"t": "是在王公大人,为政于国家者,不能以尚贤事能为政也。", "b": "《墨子》"}]}, {"meaning": "件;副。", "cites": [{"t": "著我绣夹裙,事事四五通。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1039wx','刺','1','cì cī','刂','8','','[{"pinyin": "cì", "defs": [{"meaning": "(形声。从刀,朿(cì)声。本义:扎入,用尖利的东西刺)。"}, {"meaning": "同本义。", "cites": [{"t": "君杀大夫曰刺。刺,直伤也。", "b": "《说文》"}, {"t": "刺,杀也。", "b": "《尔雅》"}, {"t": "掌三刺三宥三赦之法。", "b": "《周礼·司刺》"}, {"t": "夫专诸之刺王僚也,慧星袭月。", "b": "《战国策·魏策》"}], "words": [{"w": "刺焚", "t": "刺股、焚膏之略词,比喻刻苦攻读"}, {"w": "刺子", "t": "暗剑"}, {"w": "刺心", "t": "以刀等刺进心脏。喻刺痛内心"}, {"w": "刺血", "t": "刺手指出血。表示虔诚的一种苦行"}, {"w": "刺臂", "t": "古代一种黥刑,在犯者臂部刺字;刺臂出血,用以盟誓。"}]}, {"meaning": "讽刺。", "cites": [{"t": "上称帝喾,下道齐桓,中述汤、武,以刺世事", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "讥刺", "t": "讥讽"}, {"w": "刺邪", "t": "讽刺邪恶"}, {"w": "刺戒", "t": "讥刺告戒"}, {"w": "刺美", "t": "讽刺邪恶,赞扬美好。"}]}, {"meaning": "杀。古时君杀大夫叫刺。", "cites": [{"t": "经刺公子偃。", "b": "《左传·成公十六年》。注:“鲁杀大夫皆言刺。”"}, {"t": "刺怀公于高梁。", "b": "《国语·晋语》"}], "words": [{"w": "刺斫", "t": "刺杀"}, {"w": "刺虎", "t": "杀虎。"}]}, {"meaning": "指责、揭发。", "cites": [{"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·齐策》"}], "words": [{"w": "刺举", "t": "检举;谓检举奸恶,举荐有功"}, {"w": "刺打", "t": "斥责。方言。"}]}, {"meaning": "探取;采取。", "cites": [{"t": "刺六经中作王制。", "b": "《史记·封禅书》"}], "words": [{"w": "刺取", "t": "采取,选用"}, {"w": "刺问", "t": "探问"}, {"w": "刺答", "t": "拜访答问。"}]}, {"meaning": "刺探;侦探。", "cites": [{"t": "至公车刺取。", "b": "《汉书·丙吉传》"}], "words": [{"w": "刺事", "t": "打探事情"}, {"w": "刺取", "t": "刺探"}, {"w": "刺候", "t": "刺探侦察。"}]}, {"meaning": "名帖。", "cites": [{"t": "即门者持刺入,而主者又不即出见。", "b": "宗臣《报刘一丈书》"}], "words": [{"w": "刺呼", "t": "名片上所写的姓名"}, {"w": "刺纸", "t": "犹名片"}, {"w": "刺请", "t": "以名刺邀请。"}]}]}, {"pinyin": "cī", "defs": [{"meaning": "象声词", "words": [{"w": "刺的一声,他滑了一个跟头", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1040wx','枣','1','zǎo','木','8','','[{"pinyin": "zǎo", "defs": [{"meaning": "(会意。从双朿(cì)。朿,木芒。枣树多刺。本义:枣树)。"}, {"meaning": "同本义。", "cites": [{"t": "枣,羊枣也。", "b": "《说文》"}, {"t": "枣有十一名,羊枣其一也。", "b": "《尔雅》"}, {"t": "衣巾落枣花。", "b": "宋·苏轼《浣溪沙》"}]}, {"meaning": "枣树所结的果实。", "cites": [{"t": "八月剥枣,十月获稻。", "b": "《诗·豳风·七月》"}, {"t": "梨栗枣柿。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "枣核", "t": "枣子的核"}, {"w": "枣菜", "t": "枣子与蔬菜"}, {"w": "枣脯", "t": "枣子制成的果干"}, {"w": "枣榛", "t": "枣子与榛子"}, {"w": "枣实", "t": "枣子"}, {"w": "枣蔬", "t": "枣子与蔬菜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1041wx','雨','1','yǔ yù','雨','8','','[{"pinyin": "yǔ", "defs": [{"meaning": "雨,从云层中降向地面的水。", "cites": [{"t": "雨,濡物者也。", "b": "《管子·形势解》"}, {"t": "积土成山,风雨兴焉。", "b": "《荀子》"}], "words": [{"w": "雨过天晴", "t": "像雨后晴空般的蓝色"}, {"w": "雨打梨花", "t": "喻指零乱不堪的狼狈情景"}, {"w": "雨打鸡", "t": "喻浑身湿淋淋的状态"}, {"w": "雨毛", "t": "细雨"}, {"w": "雨泣", "t": "泪流如雨。"}]}, {"meaning": "比喻朋友。", "cites": [{"t": "常时车马之客,旧,雨来;今,雨不来。", "b": "唐·杜甫《秋述》"}]}, {"meaning": "比喻教导之言,教泽。", "cites": [{"t": "泽雨无偏,心田受润。", "b": "南朝梁·简文帝《上大法颂表》"}]}, {"meaning": "譬喻离散。", "cites": [{"t": "风流云散,一别如雨。", "b": "三国魏·王粲《赠蔡子笃》"}], "words": [{"w": "雨散云收", "t": "比喻离散"}, {"w": "雨迹云踪", "t": "比喻男女旧情,已成往事"}, {"w": "雨落不上天", "t": "比喻离异的夫妻,难再复合。"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "(象形。甲骨文字形,象下雨形。“雨”是汉字的一个部首,从“雨”的字都与“雨水”有关。本义:下雨)。"}, {"meaning": "同本义。", "cites": [{"t": "雨,水从云下也。", "b": "《说文》"}, {"t": "密云不雨。", "b": "《易·小畜卦》"}]}, {"meaning": "又。", "cites": [{"t": "既雨既处。", "b": ""}, {"t": "天雨墙坏。", "b": "《韩非子·说难》"}, {"t": "失时不雨,民且狼顾。", "b": "汉·贾谊《论积贮疏》"}, {"t": "天雨雪。", "b": "《汉书·李广苏建传》"}, {"t": "恒雨少日。", "b": "唐·柳宗元《答韦中立论师道书》"}]}, {"meaning": "天上降下。", "cites": [{"t": "他日,月宿毕,竟不雨。", "b": "《史记》"}], "words": [{"w": "雨毛", "t": "天上降下兽毛"}, {"w": "雨矢", "t": "箭矢像雨一样的落下。比喻密集"}, {"w": "雨泗", "t": "比喻流泪。"}]}, {"meaning": "密集地射击或投掷。", "cites": [{"t": "烧答覆之,沙石雨之。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1042wx','卖','1','mài','十','8','','[{"pinyin": "mài", "defs": [{"meaning": "(会意。小篆字形。从出,从买。将收进的财物卖出。本义:以货物换钱。与“买”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "卖,出物货也。", "b": "《说文》。徐灏曰:“出物货曰‘卖’,购取曰‘买’,祗一声之轻重。与物美曰‘好’,好之曰‘好’,物丑曰‘恶’,恶之曰‘恶’同例。窃谓‘买、卖’本是一字,后以其声异,故从‘出’以别之。”"}, {"t": "岁恶不入,请卖爵子。", "b": "贾谊《论积贮疏》"}, {"t": "有卖果者。", "b": "明·刘基《卖柑者言》"}, {"t": "卖炭翁。", "b": "唐·白居易《卖炭翁》"}, {"t": "于是有卖田宅,鬻子孙,以偿债者矣。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "卖炭得钱;出卖", "t": "拿东西换钱"}, {"w": "卖动", "t": "卖出去"}, {"w": "卖缺", "t": "出卖官位"}, {"w": "卖冰", "t": "天热时,贩卖冰水。引申指有利的时机或作事应掌握时机"}, {"w": "卖婆", "t": "牙婆,以贩卖货物为生的妇女"}, {"w": "卖婚", "t": "嫁娶时,多索财物作为聘金或嫁妆,有如买卖,故称卖婚"}, {"w": "卖爵", "t": "买卖官爵"}, {"w": "卖货", "t": "出售货物"}, {"w": "卖春", "t": "卖娼;卖淫。指妇女出卖肉体"}, {"w": "卖契", "t": "出售田产、货物等时立下的契约"}, {"w": "卖妻鬻子", "t": "形容生活穷困,不能维持,而卖妻儿"}, {"w": "卖文", "t": "写文章赚取酬劳。"}]}, {"meaning": "背地里害人以利己;背叛。", "cites": [{"t": "谄贵卖友。", "b": "《后汉书·李固传》"}], "words": [{"w": "卖放", "t": "接受贿赂而私自放走"}, {"w": "卖阵", "t": "受敌方收买而于阵前佯败;接受贿赂而向人提供情况"}, {"w": "卖交", "t": "背叛朋友。出卖朋友间的交情"}, {"w": "卖邻", "t": "出卖邻邦"}, {"w": "卖友求荣", "t": "出卖朋友以谋求名利、地位。"}]}, {"meaning": "炫耀。", "cites": [{"t": "我们姑娘年轻媳妇子,也难卖头卖脚的,倒还是舍看我这付老脸去碰一碰。", "b": "《红楼梦》"}], "words": [{"w": "卖口", "t": "夸口"}, {"w": "卖才", "t": "卖弄才华;显才"}, {"w": "卖舌", "t": "卖弄口舌。即以巧语炫世"}, {"w": "卖膏药", "t": "比喻说大话、吹牛皮"}, {"w": "卖富", "t": "夸富;摆阔气"}, {"w": "卖风流", "t": "卖风情,指女子浓妆艳抹,卖弄姿色以诱人。"}]}, {"meaning": "旧时酒馆中称一整份菜为一卖。", "cites": [{"t": "景兰江叫了一卖一钱二分银子的杂烩。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1043wx','郁','1','yù','阝','8','','[{"pinyin": "yù", "defs": [{"meaning": "郁夷。", "cites": [{"t": "郁,右扶风郁夷也。从邑,有声。", "b": "《说文》"}]}, {"meaning": "古地名。汉置县。在今陕西省陇县西。"}, {"meaning": "物实无中核者谓之郁。", "cites": [{"t": "物实无中核者谓之郁,无刀斧之斫者谓之朴。", "b": "《论衡》"}], "words": [{"w": "郁朴", "t": "本指没有内核的果实或未加工的木料,借喻缺乏教养的人。"}]}, {"meaning": "文采美盛。", "cites": [{"t": "周监于二代,郁郁乎文哉!", "b": "《论语·八佾》"}, {"t": "纷郁郁其远承兮。", "b": "《楚辞·九章·思美人》"}], "words": [{"w": "郁郁桓桓", "t": "文采明盛、勇武出众的样子。"}]}, {"meaning": "丰盛。", "cites": [{"t": "蜜房郁毓被其阜。", "b": "左思《蜀都赋》。注:“盛多也。”"}], "words": [{"w": "郁毓", "t": "丰盛的样子"}, {"w": "郁霭", "t": "云彩盛多的样子。"}]}, {"meaning": "香气浓郁。", "cites": [{"t": "践椒涂之郁烈。", "b": "曹植《洛神赋》"}], "words": [{"w": "郁芬", "t": "浓烈的香气"}, {"w": "郁攸", "t": "火气;灼热之气"}, {"w": "郁郁青青", "t": "香气馥郁,青葱繁茂的样子。"}]}, {"meaning": "(形声。从邑,有声。“郁”本是地名,又作姓。“鬱”为形声,从林,鬱(yù)省声。本义:繁盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "鬱,木丛生也。", "b": "《说文》"}, {"t": "郁彼北林。", "b": "《诗·秦风·晨风》"}, {"t": "郁郁园中柳。", "b": "《古诗》。注:“茂盛也。”"}, {"t": "桑榆郁相望,邑里多鸡鸣。", "b": "唐·王维《赠房卢氏琯》"}], "words": [{"w": "郁秀", "t": "茂密秀丽"}, {"w": "郁茀", "t": "郁勃。茂盛的样子"}, {"w": "郁茂", "t": "茂盛。"}]}, {"meaning": "隆盛;繁多。", "cites": [{"t": "洛阳云树郁崔嵬。", "b": "元·杨果《洛阳怀古》"}], "words": [{"w": "郁盎", "t": "旺盛,引申为久长"}, {"w": "郁绿", "t": "深绿"}, {"w": "郁翠", "t": "苍翠,浓绿"}, {"w": "郁雾", "t": "浓雾。"}]}, {"meaning": "忧郁。", "cites": [{"t": "故乐愈侈,而民愈郁,国愈乱。", "b": "《淮南子·泛论训》"}], "words": [{"w": "郁尼", "t": "郁悒不申"}, {"w": "郁邑", "t": "郁悒"}, {"w": "郁忡忡", "t": "忧虑不安的样子"}, {"w": "郁沉", "t": "忧郁沉闷。"}]}, {"meaning": "积聚。", "cites": [{"t": "郁浊困滞。", "b": "《管子·中匡》"}], "words": [{"w": "郁酿", "t": "积聚掺和"}, {"w": "郁黑", "t": "因湿热郁积而变黑"}, {"w": "郁伏", "t": "蕴藏隐伏"}, {"w": "郁聿", "t": "蕴积"}, {"w": "郁浃", "t": "蕴结满溢"}, {"w": "郁云", "t": "积云。"}]}, {"meaning": "怨恨;愤怒。", "cites": [{"t": "或有宛足郁怒。", "b": "傅毅《舞赋》"}], "words": [{"w": "郁伊", "t": "忧愤郁结"}, {"w": "郁怨", "t": "怨恨郁结。"}]}, {"meaning": "郁积,阻滞。", "cites": [{"t": "精气郁也。", "b": "《吕氏春秋》。注:“不通也。”"}, {"t": "郁湮不育。", "b": "《左传·昭公二十九年》。注:“滞也。”"}, {"t": "忠良切言皆郁于胸。", "b": "《汉书·路温舒传》"}], "words": [{"w": "郁陶", "t": "忧思郁积,思念的样子"}, {"w": "郁噎", "t": "阻塞,郁积。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1044wx','矾','1','fán','石','8','','[{"pinyin": "fán", "defs": [{"meaning": "各种金属(如铜、铁、锌)的硫酸盐,尤指具有玻璃质状态表面或光泽的该种硫酸盐的水合物。", "words": [{"w": "矾山", "t": "宋代士大夫暑月宴客,堆明矾于盘中,置席上以像冰雪"}, {"w": "矾水", "t": "溶明矾的水"}, {"w": "矾粉", "t": "脱胶的明矾粉末"}, {"w": "矾书", "t": "用明矾水写的保密书信"}]}, {"meaning": "铝的氧化物Al2O3", "words": [{"w": "矾土", "t": "在自然界以刚玉和水合形式存在,通常由各种形式的铝土矿制得,主要用作金属铝的来源、磨料和耐火材料、催化剂和催化剂载体,以及吸附剂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1045wx','矿','1','kuàng','石','8','','[{"pinyin": "kuàng", "defs": [{"meaning": "(形声。从石,广声。本义:矿产,矿物)。"}, {"meaning": "同本义。", "cites": [{"t": "其下则金矿丹砾。", "b": "晋·郭璞《江赋》"}], "words": [{"w": "铁矿;矿田;矿丁", "t": "旧时对矿工的称呼"}, {"w": "矿夫", "t": "即矿兵"}, {"w": "矿屯", "t": "用驻军开采矿产以节省国家开支的一种措施"}, {"w": "矿主", "t": "旧时占有矿山和开矿生产手段的资本家"}, {"w": "矿务", "t": "采矿事务。"}]}, {"meaning": "石针,古代的一种医疗工具。", "cites": [{"t": "汤剂不可理,矿艾不可攻。", "b": "皮日休《祀虐疠文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1046wx','码','1','mǎ','石','8','','[{"pinyin": "mǎ", "defs": [{"meaning": "码碯(亦作“玛瑙”。一种似玉而次于玉的宝石)。", "cites": [{"t": "码,码碯,石次玉也。", "b": "《玉篇》"}]}, {"meaning": "英制长度单位,美制码等于0.9144米,在英国,则1码等于保存在威斯敏斯特商务部标准局的青铜棒两个金塞子上横线标记之间的距离(在62°F时)。"}, {"meaning": "撂下不管。", "cites": [{"t": "照市井上外话说,这就叫“把朋友码在那儿”了。", "b": "《儿女英雄传》"}], "words": [{"w": "码下", "t": "撂下;搁在一旁不管。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1047wx','厕','1','cè si','厂','8','','[{"pinyin": "cè", "defs": [{"meaning": "(形声。从厂(hǎn),则声。“厂”,小篆字形象山崖,可以住人。“厂”作为汉字部首之一,常与“广”(yǎn)通用,表示与房屋有关,如“廁”又写作“厠”。本义:厕所)。"}, {"meaning": "同本义。", "cites": [{"t": "厠,杂也。言人杂厠在上非一也。", "b": "《释名·释宫室》"}, {"t": "沛公起如厕。", "b": "《史记·项羽本纪》"}], "words": [{"w": "男厕;女厕;厕屋", "t": "厕溷。厕所"}, {"w": "厕筹", "t": "厕简。大便后用来拭粪的小木片片。"}]}, {"meaning": "假借为“侧”。旁边。", "cites": [{"t": "上踞厠视之。", "b": "《汉书·汲黯传》。注:“厠,床边侧也。”"}, {"t": "居霸陵,北临厠。", "b": "《汉书·刘向传》。注:“厠,侧近水也。”"}, {"t": "上居外临厠。", "b": "《汉书·张释之传》。注:“岸之边侧也。”"}]}]}, {"pinyin": "si", "defs": [{"meaning": "——如“茅厕”（máosi）:厕所(用于口语)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1048wx','奈','1','nài','大','8','','[{"pinyin": "nài", "defs": [{"meaning": "如,如何。", "cites": [{"t": "奈何去社稷也?", "b": "《礼记·曲礼下》"}, {"t": "诸侯不从,奈何?", "b": "《史记·高祖本纪》"}, {"t": "无奈何也。", "b": "《韩非子·喻老》"}, {"t": "无可奈何。", "b": "《史记·屈原贾生列传》"}, {"t": "亡奈何矣。", "b": "明·宗臣《报刘一丈书》"}, {"t": "唯无形者,无可奈也。", "b": "《淮南子·兵略训》"}]}, {"meaning": "这。", "cites": [{"t": "虽然久后成佳配,奈时间怎不悲啼。意似痴,心如醉。", "b": "《西厢记》"}]}, {"meaning": "对付;处置。", "cites": [{"t": "谁奈离愁得,村醪或可尊。", "b": "黄庭坚《和文潜舟中所题》"}], "words": [{"w": "奈何天", "t": "言对付天公。"}]}, {"meaning": "禁受住;忍受。", "cites": [{"t": "斟酌姮娥寡,天寒奈九秋。", "b": "杜甫《月》"}], "words": [{"w": "奈烦", "t": "耐烦,能承受,能忍耐"}, {"w": "耐守", "t": "耐心等待"}, {"w": "奈久", "t": "耐久,能够经久"}, {"w": "奈心", "t": "耐心,心里不急躁,不厌烦。"}]}, {"meaning": "怎奈、无奈的省文 。用于转折句,表示原因。", "cites": [{"t": "此地奈无城郭,又无险阴。", "b": "《三国演义》"}], "words": [{"w": "奈向", "t": "奈何,如何"}, {"w": "无奈人多口杂,说不上去;奈何天", "t": "令人无可奈何的时光"}, {"w": "奈缘", "t": "犹怎奈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1049wx','奔','1','bēn bèn','大','8','','[{"pinyin": "bēn", "defs": [{"meaning": "(会意。金文字形,上面从“大”(人),象人挥动双手,下面从“止”(趾),而且是三个“止”,表示快跑。本义:快跑)。"}, {"meaning": "同本义。", "cites": [{"t": "中庭谓之走,大路谓之奔。", "b": "《尔雅·释宫》"}, {"t": "将奔走之。", "b": "《左传·昭公三十一年》。注:“犹赴趣也。”"}, {"t": "弗迓克奔。", "b": "《书·牧誓》"}, {"t": "猛浪若奔。", "b": "吴均《与朱元思书》"}, {"t": "屠乃奔倚其下。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "东奔西跑;奔冲", "t": "奔驰,猛冲"}, {"w": "奔走呼号", "t": "一面奔跑,一面叫喊"}, {"w": "奔马;奔驹;奔丧", "t": "父母丧,儿女由外地赶回安葬守丧。"}]}, {"meaning": "逃跑,逃亡。", "cites": [{"t": "大奔曰败。", "b": "《左传·庄公十一年》"}, {"t": "得间奔真州。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "奔沮", "t": "逃亡"}, {"w": "奔迸", "t": "逃散"}, {"w": "奔溃", "t": "败逃。"}]}, {"meaning": "私奔,中国古代女子没有通过正当礼节而私去与男子结合。", "cites": [{"t": "奔者为妾。", "b": "《内记·内则》"}, {"t": "奔者不禁。", "b": "《周礼·媒氏》"}, {"t": "文君夜亡奔相如。", "b": "《史记·司马相如列传》"}], "words": [{"w": "奔女", "t": "私奔之女。"}]}, {"meaning": "急速。", "words": [{"w": "奔流", "t": "流得很急"}, {"w": "奔湍", "t": "急速的水流"}, {"w": "奔泻", "t": ""}]}]}, {"pinyin": "bèn", "defs": [{"meaning": "直往;趋向。", "cites": [{"t": "只见那边两骑马直奔凤姐车来。", "b": "《红楼梦》"}], "words": [{"w": "直奔实验室", "t": ""}]}, {"meaning": "竭尽全力。", "cites": [{"t": "(旦)娘,你女儿不幸,作何处置?(老)奔你回去也,儿。", "b": "明·汤显祖《牡丹亭》"}], "words": [{"w": "他是奔六十的人了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1050wx','奇','1','qí jī','大','8','','[{"pinyin": "qí", "defs": [{"meaning": "(会意。从大,从可,可亦声。本义:奇异,怪异)。"}, {"meaning": "同本义。", "cites": [{"t": "奇,异也。", "b": "《说文》"}, {"t": "奇服怪民不入宫。", "b": "《周礼·阍人》"}, {"t": "国君不乘奇车。", "b": "《礼记·曲礼》"}, {"t": "奇生怪。", "b": "《国语·晋语》"}, {"t": "足以为奇伟偃却之属。", "b": "《荀子·非相》。注:“奇伟誇大也。”"}, {"t": "余幼好此奇服兮。", "b": "《楚辞·屈原·涉江》"}, {"t": "有奇字素无备者。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "邑人奇之。", "b": "宋·王安石《伤仲永》"}, {"t": "奇已。", "b": "清·周容《芋老人传》"}, {"t": "奇花初胎。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "奇挺", "t": "奇异挺拔;奇异超群"}, {"w": "奇怀", "t": "奇异的想法"}, {"w": "奇缘", "t": "奇特的缘分"}, {"w": "奇古", "t": "奇特古朴"}, {"w": "奇辟", "t": "奇特异常"}, {"w": "奇节", "t": "奇特的节操"}, {"w": "奇险", "t": "奇特险怪。"}]}, {"meaning": "珍奇;稀奇。", "cites": [{"t": "此奇货可居。", "b": "《史记·吕不韦传》"}], "words": [{"w": "奇稀", "t": "奇希。希奇"}, {"w": "奇货", "t": "珍奇少见的物品或货物"}, {"w": "奇珍", "t": "奇异珍贵之物"}, {"w": "奇花异卉", "t": "稀奇少见的花草。"}]}, {"meaning": "出人意外,诡变莫测。", "cites": [{"t": "以奇用兵。", "b": "《老子》。注:“诈也。”"}], "words": [{"w": "奇咳", "t": "奇祕"}, {"w": "奇正", "t": "兵法术语。设计邀截袭击为奇,对阵交锋为正"}, {"w": "奇病", "t": "奇怪的病。"}]}, {"meaning": "引起惊讶;感到惊异。", "cites": [{"t": "大将军邓骘奇其才,累召不应。", "b": "《张衡传》"}], "words": [{"w": "不足为奇;奇诧", "t": "惊奇,诧异"}, {"w": "奇骇", "t": "非常惊异;奇特惊人。"}]}, {"meaning": "姓。"}]}, {"pinyin": "jī", "defs": [{"meaning": "(字源见奇(qí)。本义:奇特,奇异)。"}, {"meaning": "单数,偶之对。", "cites": [{"t": "奇,一曰不耦。", "b": "《说文》"}, {"t": "阳数奇。", "b": "《白虎通·嫁娶》"}, {"t": "一算为奇。", "b": "《仪礼·乡射礼》"}, {"t": "奇肱之国,其人一臂三目,有阴有阳。", "b": "《山海经·海外西经》"}, {"t": "每奇日,未尝不视朝。", "b": "《资治通鉴》"}], "words": [{"w": "奇日", "t": "奇数之日。即单日"}, {"w": "奇左", "t": "仅有左臂"}, {"w": "奇肱", "t": "仅有一臂。又指古代神话中的国名"}, {"w": "奇偏", "t": "偏于一方面,片面。"}]}, {"meaning": "余数,零头,不足整数者。", "cites": [{"t": "时有奇羡。", "b": "《史记·货殖列传》。索隐:“余衍也。”"}, {"t": "操其奇赢。", "b": "《汉书·食货志》。注:“谓有余财。”"}, {"t": "旁入奇利。", "b": "《管子·禁藏》。注:“余也。”"}, {"t": "长约八分有奇。", "b": "明·魏学洢《核舟记》"}, {"t": "七万五千有奇。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "奇得", "t": "多余的利益"}, {"w": "奇羡", "t": "商贾买卖的赢利"}, {"w": "奇零", "t": "不满整数的数目"}, {"w": "奇赢", "t": "以余财蓄积奇异的货物。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1051wx','奋','1','fèn','大','8','','[{"pinyin": "fèn", "defs": [{"meaning": "(会意。金文字形,中间是“隹”(鸟);外面象鸟振翅欲飞之势;下面是“田”,表示空旷的田野。本义:鸟类振羽展翅)。"}, {"meaning": "同本义。", "cites": [{"t": "奮,翚也。", "b": "《说文》"}, {"t": "奋隼归凫。", "b": "张衡《西京赋》"}, {"t": "羽翼奋也。", "b": "《淮南子·原道》"}, {"t": "雉绝有力奋,鸡绝有力奋。", "b": "《尔雅·释鸟》"}, {"t": "不能奋飞。", "b": "《诗·邶风·柏舟》"}, {"t": "于是宾客无不变色离席,奋袖出臂。", "b": "《虞初新志·秋声诗自序》"}, {"t": "虫暴怒,直奔,遂相腾击,振奋作声。", "b": "《聊斋志异·促织》"}], "words": [{"w": "奋翅", "t": "振翼起飞"}, {"w": "奋翼", "t": "振翼高飞"}, {"w": "奋翔", "t": "振翼高飞"}, {"w": "奋鳞", "t": "龙腾飞"}, {"w": "奋翮", "t": "展翅,振羽。"}]}, {"meaning": "鼓起劲来,振作。", "cites": [{"t": "奋,振也。", "b": "《广雅·释言》"}, {"t": "拔刀奋起,率众袭之。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "及至始皇,奋六世之余烈。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "奋烈", "t": "振奋威武"}, {"w": "奋信", "t": "振奋伸张"}, {"w": "奋武扬威", "t": "振奋勇气,施展威风"}, {"w": "奋气", "t": "奋发振作。"}]}, {"meaning": "震动。", "cites": [{"t": "雷出地奋。", "b": "《易·豫》"}, {"t": "奋,动也。", "b": "《广雅》"}], "words": [{"w": "奋首", "t": "摇头,表示疲困"}, {"w": "奋髯", "t": "抖动胡须"}, {"w": "奋蹄", "t": "振蹄。"}]}, {"meaning": "奋力;施展;发挥。", "cites": [{"t": "奋至德之光。", "b": "《史记·乐书》。集解:“发也。”"}, {"t": "王奋厥武。", "b": "《诗·大雅·常武》"}, {"t": "岂其士卒众多哉,诚能据其势而奋其威。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "奋张", "t": "有力地伸展、张开"}, {"w": "奋末", "t": "四肢用力。"}]}, {"meaning": "挥动;举起;舞动。", "cites": [{"t": "陈王奋臂,为天下倡始。", "b": "《史记·张耳陈余列传》"}, {"t": "众贼环而进,客奋椎左右击,人马仆地。", "b": "明·魏禧《大铁椎传》"}, {"t": "遂鼓吻奋爪以向先生。", "b": "马中锡《中山狼传》"}], "words": [{"w": "奋臂", "t": "有力地举臂,表示振奋"}, {"w": "奋袂", "t": "举袖,挥袖,形容振奋"}, {"w": "奋笔", "t": "提笔疾书"}, {"w": "奋戈", "t": "使劲挥舞干戈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1052wx','态','1','tài','心','8','','[{"pinyin": "tài", "defs": [{"meaning": "(会意。从心,从能。简体字为形声。从心,太声。本义:姿态,姿势与状态)。"}, {"meaning": "同本义。", "cites": [{"t": "態,意态也。", "b": "《说文》。段注:“意态者,有是意,因有是状,故曰意态。从心能,会意。心所能必见于外也。”"}, {"t": "柔远能迩。", "b": "《虞书》。郑注:“能,恣也,恣即态也。”"}, {"t": "人之态不如备。", "b": "《荀子·成相》。按:“诈态也。”"}, {"t": "尽变态乎其中。", "b": "张衡《西京赋》"}, {"t": "滂心淖态。", "b": "《楚辞·大招》"}, {"t": "狗偷致态。", "b": "傅毅《舞赋》"}, {"t": "宁溘死而流亡兮,予不忍为此态也。", "b": "《楚辞·离骚》"}, {"t": "有风既作飘摇之态,无风亦呈袅娜之态。", "b": "李渔《芙蕖》"}, {"t": "是以上多故则下多诈,上多事则下多态,上烦扰则下不定。", "b": "《淮南子》"}, {"t": "尽态极妍。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "密则无态。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "情状,神情。", "cites": [{"t": "览将帅之变态。", "b": "司马相如《上林赋》。又如:病态;情态;气态;液态;态色(踌躇满志的神色);态状(状态;状貌);态浓(妆扮浓艳)"}]}, {"meaning": "用以表明动作主体和动词表示的行为之间的关系 ——见“主态”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1053wx','欧','1','ōu','欠','8','','[{"pinyin": "ōu", "defs": [{"meaning": "歌唱。", "cites": [{"t": "百姓欧歌。", "b": "《隶释·三公山碑》"}], "words": [{"w": "欧歌", "t": "讴歌,歌颂。"}]}, {"meaning": "", "cites": [{"t": "或导之以德教,或欧之以法令。。", "b": "《大戴礼·礼察》"}]}, {"meaning": "殴打。", "cites": [{"t": "(老父)顾谓良曰:孺子下取履!良鄂然,欲欧之。", "b": "《汉书·张良传》"}]}, {"meaning": "种族名 。如:欧人(古越族的一支);亦为地名。如:欧越(即瓯越。古越人聚居之地)。"}, {"meaning": "欧姆的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1054wx','殴','1','ōu','殳','8','','[{"pinyin": "ōu", "defs": [{"meaning": "(形声。从殳,区(ōu)声。殳(shū),古代兵器,用以撞击。本义:打击,捶击)。"}, {"meaning": "同本义。", "cites": [{"t": "殴,捶击物也。", "b": "《说文》"}, {"t": "后数复殴伤郎。", "b": "《汉书·梁王襄传》"}, {"t": "或至相殴。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "殴曳", "t": "殴打拖曳"}, {"w": "殴仗", "t": "以仗殴打"}, {"w": "殴逐", "t": "殴打追逐"}, {"w": "殴伤", "t": "殴斗致伤,打伤"}, {"w": "殴击", "t": "殴打"}, {"w": "殴骂", "t": "打骂"}, {"w": "殴挞", "t": "殴打,鞭挞。"}]}, {"meaning": "气恼。", "cites": [{"t": "杨志骂道:“这畜生不殴死俺,只是打便了。”", "b": "《水浒传》"}]}, {"meaning": "假借为“驱”。驱赶。", "cites": [{"t": "以弓矢殴乌鸢。", "b": "《唐石经《周礼·夏官·射乌氏》"}, {"t": "殴除群厉。", "b": "张衡《东京赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1055wx','垄','1','lǒng','土','8','','[{"pinyin": "lǒng", "defs": [{"meaning": "(形声。从土,龙声。本义:坟)。"}, {"meaning": "同本义。", "cites": [{"t": "生王之头,曾不若死士之垄也。", "b": "《战国策·齐策》"}], "words": [{"w": "垄墓", "t": "坟墓。"}]}, {"meaning": "土埂。"}, {"meaning": "田埂。", "cites": [{"t": "辍耕之垄上。", "b": "《史记·陈涉世家》"}], "words": [{"w": "垄次", "t": "田间"}, {"w": "垄亩之臣", "t": "辞官归耕田野的臣子"}, {"w": "垄亩", "t": "阡陌田野。"}]}, {"meaning": "成行种植农作物的土埂。"}, {"meaning": "高丘,高地。", "cites": [{"t": "封比干之丘垄。", "b": "《楚辞·东方朔·七谏沉江》。注:“小曰丘,大曰垄。垄,一作陇。”"}], "words": [{"w": "垄岗沙", "t": "沙漠中广泛分布的一种沙丘,也称“沙垄”或“纵向沙丘”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1056wx','妻','1','qī qì','女','8','','[{"pinyin": "qī", "defs": [{"meaning": "(会意。小篆字形从女,从屮,从又。“屮”象家具形,又是手。合起来象女子手拿家具从事劳动的形象。本义:男子的正式配偶)。"}, {"meaning": "同本义。", "cites": [{"t": "妻,妇与夫齐者也。", "b": "《说文》"}, {"t": "庶人曰妻。", "b": "《礼记·曲礼》"}]}, {"meaning": "又。", "cites": [{"t": "天子有妻、有妾。", "b": ""}, {"t": "聘则为妻,奔则为妾。", "b": "《礼记·内则》"}, {"t": "妻也者,亲之主也。", "b": "《礼记·哀公问》"}, {"t": "妻者,夫之合也。", "b": "《春秋繁露》"}, {"t": "夫妻反目。", "b": "《易·小畜》"}, {"t": "令妻寿母。", "b": "《诗·鲁颂·閟宫》"}], "words": [{"w": "妻妾", "t": "嫡妻与侧室"}, {"w": "妻房", "t": "妻室,妻子"}, {"w": "妻儿", "t": "妻和儿女;妻"}, {"w": "妻姊妹婚", "t": "再与亡妻之姊、妹缔结婚姻"}, {"w": "妻谒", "t": "透过得宠的女子去干求请托。"}]}, {"meaning": "周代宫中女御。", "cites": [{"t": "天子有后,有夫人,有世妇,有嫔,有妻,有妾。", "b": "《礼记》"}]}]}, {"pinyin": "qì", "defs": [{"meaning": "以女嫁人。", "cites": [{"t": "黥布归芮,芮妻之。", "b": "《汉书·吴芮传》。注:“妻,嫁女与人也。”"}, {"t": "妻娶(嫁人和娶妻)", "b": ""}]}, {"meaning": "娶女子为配偶。", "cites": [{"t": "齐侯又请妻之。", "b": "《左传·桓公六年》"}, {"t": "好色,人之所欲,妻帝之二女,而不足以解忧。", "b": "《孟子》"}]}, {"meaning": "奸淫。", "cites": [{"t": "妻略妇女。", "b": "《后汉书》"}, {"t": "妻略(奸污霸占)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1057wx','轰','1','hōng','车','8','','[{"pinyin": "hōng", "defs": [{"meaning": "(会意。从三车。本义:群车行驶声)。"}, {"meaning": "同本义。", "cites": [{"t": "轰,群车声也。", "b": "《说文》"}, {"t": "轰轰殷殷。", "b": "《史记·苏秦传》"}], "words": [{"w": "轰隐", "t": "成群车队的喧闹声"}, {"w": "轰輵", "t": "象声词。形容车声、雷声等"}, {"w": "轰轰阗阗", "t": "形容车马声。"}]}, {"meaning": "眩晕。", "cites": [{"t": "请大夫把病来调,我涩的难行立,轰的则待倒。", "b": "元·张国宾《罗李郎》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1058wx','顷','1','qīng qǐng','页','8','','[{"pinyin": "qīng", "defs": [{"meaning": "(会意。从匕(bì),从页(xié)。匕有排列比较义,也有不正之义。页,头。合起来表示头偏。本义:头不正)。"}, {"meaning": "同本义。", "cites": [{"t": "顷,头不正也。", "b": "《说文》。段玉裁注:“顷者,头也。”徐灏注:“顷、倾古今字。”"}]}, {"meaning": "倾斜;偏侧。", "cites": [{"t": "妇人擅国兹谓顷。", "b": "《汉书·五行志》"}, {"t": "不盈顷筐。", "b": "《诗·周南·卷耳》"}], "words": [{"w": " 顷筐", "t": "倾斜口的竹筐。形似今之畚箕"}, {"w": "顷危", "t": "倾斜而危险"}, {"w": "顷宫", "t": "十分高大的宫殿"}, {"w": "顷倒", "t": "倒下。"}]}]}, {"pinyin": "qǐng", "defs": [{"meaning": "田地面积的单位,等于一百亩。", "cites": [{"t": "凡为田一顷十二亩半。", "b": "《公羊传·宣公十五年》注"}, {"t": "筑为顷宫。", "b": "《吕氏春秋·过理》"}, {"t": "一碧万顷。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "有田一顷。", "b": "清·洪亮吉《治平篇》"}, {"t": "食田一顷。", "b": ""}, {"t": "田百顷。", "b": "《聊斋志异·促织》"}], "words": [{"w": "碧波万顷;顷亩", "t": "百亩之地。泛指土地、田地"}, {"w": "顷晦", "t": "顷亩"}, {"w": "顷宫", "t": "占地一顷的宫殿"}, {"w": "一顷地", "t": ""}]}, {"meaning": "少顷,短时间。", "cites": [{"t": "莅政有顷。", "b": "《战国策·秦策》。注:“言未久。”"}, {"t": "不为顷久推移。", "b": "《庄子·秋水》"}], "words": [{"w": "俄顷", "t": "很短的时间"}, {"w": "顷之", "t": "未几,不久"}, {"w": "顷久", "t": "短暂与长久"}, {"w": "顷息", "t": "喘息的时间"}, {"w": "顷顷", "t": "片刻"}, {"w": "顷然", "t": "一会儿。"}]}, {"meaning": "偏侧。", "cites": [{"t": "不盈顷筐。", "b": "《诗·周南·卷耳》"}, {"t": "顷筐墍之。", "b": "《诗·召南·摽有梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1059wx','转','1','zhuǎn zhuàn','车','8','','[{"pinyin": "zhuǎn", "defs": [{"meaning": "(形声。从车,专声。转运要用车,故从车。本义:转运)。"}, {"meaning": "同本义(通过陆路运输)。", "cites": [{"t": "转,运也。", "b": "《说文》"}, {"t": "胡转予于恤?", "b": "《诗·小雅·祈父》"}, {"t": "丁壮苦军旅,老弱罢转饷。", "b": "《汉书·高帝纪上》"}, {"t": "却骐骥以转运兮。", "b": "《楚辞·刘向·九叹愍命》"}, {"t": "转漕甚辽远。", "b": "《史记·项羽本纪》。司马贞索隐:“车运曰转,水运曰漕。”"}, {"t": "辇车相属,转粟流输,千里不绝。", "b": "《汉书·邹阳传》"}], "words": [{"w": "转饷", "t": "转运粮饷"}, {"w": "转输", "t": "转运输送物资"}, {"w": "转海", "t": "海运"}, {"w": "转粟", "t": "运送谷物"}, {"w": "转漕", "t": "转运粮饷"}, {"w": "转毂", "t": "转运货物的车子。"}]}, {"meaning": "回还,转动。", "cites": [{"t": "我心匪石,不可转也。", "b": "《诗·邶风·柏舟》"}, {"t": "故善战人之势,如转圆石于千仞之山者,势也。", "b": "《孙子·势》"}, {"t": "转轴拨弦三两声,未成曲调先有情。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "回头转眄似雕鹗,有志飞鸣人岂知!", "b": "唐·李颀《别梁锽》"}], "words": [{"w": "转盼", "t": "转动眼珠"}, {"w": "转眄", "t": "转动眼珠"}, {"w": "转规", "t": "像圆规旋转一样,比喻一往无阻"}, {"w": "转侧", "t": "在床上转动身体。"}]}, {"meaning": "指情况的变化、改变。", "cites": [{"t": "兵生于治而异,俗生于法而万转。", "b": "《商君书·立本》。高亨注译:“万转,万变。指风俗多变化,有好有坏。”"}, {"t": "道直身还在,恩深命转轻。", "b": "唐·裴度《中书即事》"}, {"t": "其为政也,善因祸而为福,转败而为功。", "b": "《史记·管晏传》"}], "words": [{"w": "转靶子", "t": "改变主意"}, {"w": "转角头", "t": "转弯处"}, {"w": "转日回天", "t": "形容力量大,能扭转很难挽回的局面。"}]}, {"meaning": "转移,辗转。", "cites": [{"t": "转送其家。", "b": "《汉书·高帝纪上》"}, {"t": "浊之则郁而无转。", "b": "《淮南子·泛论》"}, {"t": "转而攻秦。", "b": "汉·贾谊《过秦论》"}, {"t": "转而缘南晦。", "b": "汉·贾谊《论积贮疏》"}, {"t": "路转溪头忽见。", "b": "宋·辛弃疾《西江月》"}]}, {"meaning": "丢弃。", "cites": [{"t": "生无乏用,死无转尸。", "b": "《淮南子》"}], "words": [{"w": "转尸", "t": "人死而不能葬,尸体弃于沟中"}, {"w": "转死", "t": "弃尸"}, {"w": "转尸沟壑", "t": "弃尸于山沟水渠。"}]}, {"meaning": "迁官转任。", "cites": [{"t": "王述转尚书令,事行便拜。", "b": "《世说新语·方正》"}, {"t": "密有才能,常望内转,而朝廷无援,乃迁汉中太守。", "b": "《晋书》"}], "words": [{"w": "转除", "t": "升官"}, {"w": "转任", "t": "转换所任职务"}, {"w": "转补", "t": "迁调官职,以补缺额。"}]}, {"meaning": "掉转;转向。", "cites": [{"t": "东亭转卧向壁。", "b": "《世说新语·品藻》"}, {"t": "转头向户里。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "童自转。", "b": "唐·柳宗元《童区寄传》"}, {"t": "云何裁转背,便卖恶于人?", "b": "《宋书·蔡廓传》"}, {"t": "若夫转身易位,全众传国,最其病也。", "b": "《韩非子·说疑》"}, {"t": "转视积薪后。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "转步", "t": "改变走向"}, {"w": "转舵", "t": "转动船舵,以改变航向;比喻转变方向。"}]}, {"meaning": "移动;迁徙。", "cites": [{"t": "盤石无转移。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "转入石门。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "转手", "t": "移动手臂"}, {"w": "转居", "t": "移居。"}]}, {"meaning": "离去,离开。", "cites": [{"t": "衙门无事,相公且转厅。", "b": "马致远《大妇小妻还牢末杂剧》"}]}, {"meaning": "摇动;飘荡。", "cites": [{"t": "光风转蕙,泛崇兰兮。", "b": "《楚辞·招魂》"}, {"t": "四角龙子帆,婀娜随风转。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "转蓬身", "t": "比喻到处飘泊的人"}, {"w": "转磷", "t": "飘忽不定的磷火"}, {"w": "转烛", "t": "风摇烛火。用以比喻世事变幻莫测"}, {"w": "转萍", "t": "比喻飘泊不定。"}]}, {"meaning": "避。", "cites": [{"t": "引而使之,民不敢转其力。", "b": "《管子》"}]}, {"meaning": "缠绕。", "cites": [{"t": "以红绡转其头。", "b": "《席上腐谈》"}]}, {"meaning": "又如:转踅(回旋缠绕)。"}, {"meaning": "卖。", "cites": [{"t": "现今这房子转的出四十两银子…竟托书店里人把房子转了,拿了银子回来。", "b": "《儒林外史》"}]}, {"meaning": "又如:转物(买卖货物);转肩(一种不正当的买卖。高价赊入,低价卖出);转货(做买卖);转卖(把买进的东西再卖出去)。"}, {"meaning": "诵。", "cites": [{"t": "素公不出院,转《法华经》三万七千部。", "b": "段成式《酉阳杂俎》"}, {"t": "三藏转咒,震舌呼祝。", "b": "《太平广记》引《宣室志》"}]}, {"meaning": "又如:转经(诵经);转读(诵读佛经)。"}, {"meaning": "曲折,盘曲。", "cites": [{"t": "千岩万转。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "山回路转。", "b": "唐·岑参《白雪歌送武判官归京》"}]}, {"meaning": "量词。等于说“次”。古时军功每加一等,则官爵随升一级,叫做一转。", "cites": [{"t": "策勋十二转。", "b": "《乐府诗集·木兰诗》"}]}]}, {"pinyin": "zhuàn", "defs": [{"meaning": "旋转;打转。", "cites": [{"t": "峰回路转。", "b": "《醉翁亭记》"}, {"t": "下者飘转。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "转丸", "t": "转动的弹丸。比喻升降沉浮不定"}, {"w": "转灯", "t": "走马灯"}, {"w": "机器转子团团转;砂轮转得快;地球绕着太阳转", "t": ""}]}, {"meaning": "绕过。", "cites": [{"t": "由千佛山脚下往东,转过山坡,竟向南去。", "b": "《老残游记》"}]}, {"meaning": "鸟鸣,蝉鸣。", "cites": [{"t": "蝉则千转不穷。", "b": "吴均《与朱元思书》"}]}, {"meaning": "次;回。", "cites": [{"t": "策勋十二转。赏赐百千强。", "b": "《木兰诗》"}, {"t": "一天哭三回,三天哭九转,铁石的心也变软。", "b": "李季《王贵与李香香》"}], "words": [{"w": "下转", "t": "下次;下一回。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1060wx','斩','1','zhǎn','斤','8','','[{"pinyin": "zhǎn", "defs": [{"meaning": "(会意。从车,从斤。古有“车裂”之刑,故从车。斤,斧子,可用于杀人。本义:古代死刑的一种。斩首或腰斩;杀)。"}, {"meaning": "同本义。", "cites": [{"t": "斩,截也。", "b": "《说文》"}, {"t": "斩,杀也。", "b": "《尔雅·释诂》"}, {"t": "国既卒斩。", "b": "《诗·小雅·节南山》"}, {"t": "斫头曰斩,斩要曰要斩。", "b": "《释名·释丧制》"}, {"t": "掌斩杀贼谍而膊之。", "b": "《周礼·秋官·掌戮》。注:“斩以斧钺,若今之要斩;杀以刀刃,若今之弃市。”"}, {"t": "不从令者斩。", "b": "《墨子·备城门》"}, {"t": "法皆斩。", "b": "《史记·陈涉世家》"}, {"t": "失期当斩。", "b": ""}, {"t": "借第令毋斩。", "b": ""}, {"t": "杀虎斩蛟。", "b": "《世说新语·自新》"}], "words": [{"w": "斩使", "t": "斩杀来使"}, {"w": "斩棺戮尸", "t": "劈开棺木,刺杀尸体"}, {"w": "斩立决", "t": "处斩刑决不待时"}, {"w": "斩馘", "t": "杀头并取左耳,以计功"}, {"w": "问斩", "t": "斩首"}, {"w": "斩首", "t": ""}]}, {"meaning": "砍;砍断。", "cites": [{"t": "斩荆棘。", "b": "宋·苏洵《六国论》"}, {"t": "斩刈杀伐之际。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "斩伐", "t": "砍伐"}, {"w": "斩祀", "t": "砍伐神祠近旁的树"}, {"w": "斩祛", "t": "斩断其袖。借指旧怨"}, {"w": "斩绝", "t": "斩断;断绝"}, {"w": "斩断", "t": "砍断;切断"}, {"w": "斩关", "t": "砍断门闩,泛指攻破城门。"}]}, {"meaning": "断绝。", "cites": [{"t": "汉祀不斩,皆出将军之赐也。", "b": "《三国演义》"}], "words": [{"w": "斩夫之祀", "t": "断绝夫家的祭祀"}, {"w": "斩了", "t": "断了;绝了。"}]}, {"meaning": "剪裁,特指丧服不缉下边。", "cites": [{"t": "齐晏桓子卒,晏婴粗缳,斩。", "b": "《左传·襄公十七年》"}], "words": [{"w": "斩衰", "t": "粗麻布丧服,不缝边,是五种丧服中最重的,服期三年。"}]}, {"meaning": "用同“眨”。眼睛一睁一闭。", "cites": [{"t": "还斩眼动鳞。", "b": "《西游记》"}], "words": [{"w": "斩眼", "t": "眨眼"}, {"w": "斩眉多梭眼", "t": "挤眉弄眼。"}]}, {"meaning": "非常;特别。", "cites": [{"t": "老远地便见有多少洋枪队,由教习打着外国口号,一斩齐地走了上来。", "b": "《老残游记》"}], "words": [{"w": "斩平", "t": "特别平整"}, {"w": "斩截", "t": "干脆;利落"}, {"w": "斩新", "t": "簇新;全新。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1061wx','轮','1','lún','车','8','','[{"pinyin": "lún", "defs": [{"meaning": "(形声。从车,仑(lún)声。本义:车轮,轮子)。"}, {"meaning": "同本义。", "cites": [{"t": "轮,有辐曰轮,无辐曰辁。", "b": "《说文》。按,考工有轮人。"}, {"t": "坎为弓轮。", "b": "《易·说卦》"}, {"t": "輮以为轮。", "b": "《荀子·劝学》"}, {"t": "金车玉作轮。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "轮指", "t": "弹奏乐器的一种指法:一手的几个手指接连动作,犹如车轮的转动"}, {"w": "轮轭", "t": "车轮和车轭"}, {"w": "轮崇", "t": "车轮的高度。"}]}, {"meaning": "引申为车子。", "cites": [{"t": "椎轮抵长乐。", "b": "梁简文帝《长安道》"}], "words": [{"w": "轮轩", "t": "显贵者所乘坐的车子"}, {"w": "轮鞅", "t": "车马。比喻访客"}, {"w": "轮盖", "t": "车盖。"}]}, {"meaning": "凡平圆形像车轮似的东西。", "cites": [{"t": "未央前殿月轮高。", "b": "王昌龄《春宫曲》"}], "words": [{"w": "叶轮;花轮;月轮;收卷钓丝的转轮", "t": ""}]}, {"meaning": "制作车轮的工匠。", "cites": [{"t": "梓、匠、轮、舆,能与人规矩,不能使人巧。", "b": "《孟子·尽心下》"}], "words": [{"w": "轮人", "t": "制作车轮的工匠"}, {"w": "轮舆", "t": "轮人和舆人。"}]}, {"meaning": "高大的样子。", "cites": [{"t": "宫阙方轮焕。", "b": "白居易《和望晓》"}], "words": [{"w": "轮囷", "t": "高大的样子"}, {"w": "轮奂", "t": "形容房屋的高大华美"}, {"w": "轮焕", "t": "高大华美。"}]}, {"meaning": "回转;转动。", "cites": [{"t": "只有那眼珠间或一轮,还可以表示她是一个活物。", "b": "鲁迅《彷徨·祝福》"}], "words": [{"w": "轮甲", "t": "转动手指"}, {"w": "轮藏", "t": "能旋转的藏置佛经的书架"}, {"w": "轮磨", "t": "旋转挥动。"}]}, {"meaning": "用力挥动", "cites": [{"t": "轮刀耀日光。", "b": "《隋书·五行志》"}], "words": [{"w": "轮铡", "t": "挥舞铡刀。"}]}, {"meaning": "依次更替,轮流。", "cites": [{"t": "宰相与参政,轮班知印,同升政事堂。", "b": "《宋史·职官志》"}], "words": [{"w": "轮充", "t": "轮流担任工作"}, {"w": "轮替", "t": "轮流"}, {"w": "轮直", "t": "轮流值班"}, {"w": "轮回;轮对", "t": "轮流跟皇帝讨论时政。"}]}, {"meaning": "辆。", "cites": [{"t": "车至20轮,陈于阙前。", "b": "《南史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1062wx','软','1','ruǎn','车','8','','[{"pinyin": "ruǎn", "defs": [{"meaning": "(形声。从车,欠声。本义:柔软)。"}, {"meaning": "同本义。质地不硬,与“硬”相对。也作“輭”。", "cites": [{"t": "軟,柔也。", "b": "《玉篇》"}, {"t": "軟,俗輭字。", "b": "《广韵》"}, {"t": "輭,柔也。", "b": "《广韵》"}, {"t": "步步金阶上软舆。", "b": "唐·王建《宫词》"}, {"t": "婆子们抱着几个软包。", "b": "《红楼梦》"}], "words": [{"w": "软壁", "t": "可折叠的屏风"}, {"w": "软片", "t": "指裱好的书画"}, {"w": "软柔柔", "t": "非常柔软"}, {"w": "软设设", "t": "软软的"}, {"w": "软性", "t": "轻柔的事物。与硬性相对"}, {"w": "绵软", "t": "柔软;又形容身体无力"}, {"w": "松软", "t": "松散绵软"}, {"w": "软甲", "t": "软战。用非金属制作的软质战衣。"}]}, {"meaning": "柔和;温和。", "cites": [{"t": "文辞婉软。", "b": "柳宗元《乞巧文》"}], "words": [{"w": "软咍咍", "t": "软绵绵;软软地"}, {"w": "软善", "t": "和善"}, {"w": "软款", "t": "娇柔;柔和;温顺地恳求"}, {"w": "软局子", "t": "软手段"}, {"w": "软软款款", "t": "用温柔亲切的话体贴、抚慰"}, {"w": "软熟", "t": "形容人性格柔和,不违世人"}, {"w": "软语温香", "t": "形容女性细芳的身体"}, {"w": "软语温存", "t": "用温和婉转的话相抚慰"}, {"w": "软和", "t": "柔和"}, {"w": "软风", "t": "和风"}, {"w": "软美", "t": "柔和美好;温顺。"}]}, {"meaning": "形容人体柔弱无力。", "cites": [{"t": "李园,软弱人也。", "b": "《战国策·秦策》"}], "words": [{"w": "软刺答", "t": "软答刺。软弱无力的样子"}, {"w": "软丢答", "t": "轻飘无力"}, {"w": "软困", "t": "疲乏无力"}, {"w": "酸软", "t": "身体发酸而无力"}, {"w": "酥软", "t": "肢体软弱无力"}, {"w": "软兀剌", "t": "形容无力,乏劲"}, {"w": "软懒", "t": "乏力慵懒的样子"}, {"w": "软乎", "t": "形容柔弱无力。"}]}, {"meaning": "意志不坚定,容易被感动或动摇。", "cites": [{"t": "心里早软了。", "b": "《红楼梦》"}], "words": [{"w": "软壳鸡蛋", "t": "比喻性情软弱之人"}, {"w": "软揣", "t": "软弱,不坚强"}, {"w": "软怯怯", "t": "软弱,羞怯"}, {"w": "软厮禁", "t": "不硬挣,不坚强"}, {"w": "心软", "t": "容易被外界事物感动而生怜悯或同情"}, {"w": "手软", "t": "不忍下手或下手不狠"}, {"w": "软脊脊", "t": "比喻没有主见,不坚定"}, {"w": "软耳朵", "t": "比喻无主见、容易轻信人言的人"}, {"w": "软商", "t": "用软磨的手段商量。"}]}, {"meaning": "不用强硬的手段,只是平和地进行。", "cites": [{"t": "主公软监诸将在内,水食不便。", "b": "《三刻拍案惊奇》"}], "words": [{"w": "软招", "t": "软办法,软手段"}, {"w": "软困", "t": "软禁;用软办法围困"}, {"w": "软监", "t": "软禁。"}]}, {"meaning": "麻痹;软化。", "cites": [{"t": "你莫诡诈欺心软我,欲为脱身之计。", "b": "《西游记》"}], "words": [{"w": "软顽", "t": "顽滑;刁顽"}, {"w": "软痛", "t": "缓解伤痛"}, {"w": "软口汤", "t": "为封人口而送的人情贿赂之类。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1063wx','到','1','dào','刂','8','','[{"pinyin": "dào", "defs": [{"meaning": "(形声。从至,刀声。本义:到达,达来,去到)。"}, {"meaning": "同本义。", "cites": [{"t": "到,至也。", "b": "《说文》"}, {"t": "靡国不到。", "b": "《诗·大雅·韩奕》"}, {"t": "虽隆薛之城到于天。", "b": "《战国策·齐策》"}, {"t": "朝发白帝,暮到江陵。", "b": "《水经注·江水》"}, {"t": "豹往到邺,会长老,问之民所疾苦。", "b": "《史记·滑稽列传》"}, {"t": "功施到今。", "b": "李斯《谏逐客书》"}, {"t": "复到舅家。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "到时", "t": "到达之时"}, {"w": "飞机半夜到北京;官员到后,会就开始了;到头来", "t": "结果;后来。"}]}, {"meaning": "颠倒。", "cites": [{"t": "草木之到(倒)植者过半。", "b": "《庄子·外物》。注:“锄拔反之更生者曰到植。今字作倒。”"}, {"t": "公子学去尊,今又王齐王,何其到也?", "b": "《吕氏春秋·爱类》"}], "words": [{"w": "到植", "t": "倒立"}, {"w": "到三不着两", "t": "行事无准则,颠三倒四。"}]}, {"meaning": "往。", "cites": [{"t": "百川东到海。", "b": "《乐府诗集·长歌行》"}], "words": [{"w": "到北京去", "t": ""}]}, {"meaning": "可作状语,介绍出动作的时间,表明动作到此时的状况。", "cites": [{"t": "到那时使吾眼睁睁看汝死。", "b": "清·林觉民《与妻书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1064wx','非','1','fēi','非','8','','[{"pinyin": "fēi", "defs": [{"meaning": "(指事。金文作“兆”,像“飞”字下面相背展开的双翅形,双翅相背,表示违背。本义:违背;不合)。"}, {"meaning": "同本义。", "cites": [{"t": "非,违也。从飛,下翅取其相背也。", "b": "《说文》"}, {"t": "非刀匕是共。", "b": "《礼记·檀弓》。皇氏注:“不也。”"}, {"t": "非礼也。", "b": "《礼记·礼运》。注:“犹失也。”"}, {"t": "傲主人,非礼也;以贵骄人,非道也。", "b": "《世说新语·简傲》"}], "words": [{"w": "非常异义", "t": "违背经文正义的异说"}, {"w": "非度", "t": "违反法度"}, {"w": "非道", "t": "不合道义"}, {"w": "非德", "t": "不合道德;违背道德"}, {"w": "非理", "t": "不合常理;违背情理。"}]}, {"meaning": "责怪;非难;反对。", "cites": [{"t": "私田稼不善则非吏。", "b": "《谷梁传·宣公十五年》。注:“责也。”"}, {"t": "今诸生不师今而学古,以非当世。", "b": "《史记·秦始皇本纪》"}, {"t": "苟或不然,人争非之,以为鄙吝。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "非驳", "t": "非难驳斥,诘责缺失"}, {"w": "未可厚非", "t": ""}]}, {"meaning": "讨厌。", "cites": [{"t": "吾岂厌喧而求静,吾岂好丹而非素?", "b": "宋·王安石《白鹤吟示觉海元公》"}]}, {"meaning": "讥刺。", "cites": [{"t": "非世而恶利。", "b": "《史记·李斯传》"}, {"t": "其观于人,不知其非笑之为非笑也。", "b": "唐·韩愈《答李翊书》"}, {"t": "当时士大夫家皆然,人不相非也。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "非讥", "t": "讥评,议论"}, {"w": "非笑", "t": "讥笑。"}]}, {"meaning": "(fěi)。诽谤,诋毁。", "cites": [{"t": "此山谷之士,非世之人,枯槁赴渊者之所好也。", "b": "《庄子·刻意》"}, {"t": "民释实事而诵虚词,则力少而非多。", "b": "《商君书·慎法》"}, {"t": "誉者不能进,非者弗能退。", "b": "《韩非子·有度》"}]}, {"meaning": "∮秩?非誉(诽谤与赞誉);非而不用(诽谤而不予重用);非世(诋毁世俗);非孝(非难毁诋孝行);非怨(诋毁,怨恨)。"}, {"meaning": "躲开。", "cites": [{"t": "古者周公旦非关叔,辞三公,东处于商盖[奄],人皆谓之狂。", "b": "《墨子》"}]}, {"meaning": "无;没有。", "cites": [{"t": "登高而招,臂非加长也,而见者远。", "b": "《荀子·劝学》"}, {"t": "非学无以致疑,非问无以广识。", "b": "清·刘开《问说》"}, {"t": "然陈涉…才能不及中人,非有仲尼、墨翟之贤,陶朱、猗顿之富。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "非辜", "t": "无辜,无罪"}, {"w": "非材", "t": "无能;不才"}, {"w": "非意相干", "t": "没事寻衅,无故制造事端"}, {"w": "非钱不行", "t": "有钱才能成事。讥讽民风不淳,世人但知逐利。"}]}, {"meaning": "不对;错误。", "cites": [{"t": "立是废非。", "b": "《淮南子·脩务》"}, {"t": "实迷途其未远,觉今是而昨非。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "辞多类非而是,多类似而非,是非之经,不可不分,此圣人之所慎也。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "不明善恶,不辨是非;分清是非", "t": ""}]}, {"meaning": "相当于“不”、“不是”。", "cites": [{"t": "城非不高也,城非不深也,兵草非不坚利也。", "b": "《孟子·公孙丑下》"}, {"t": "是非贿得之。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "非挟太山以超北海之类也。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "非时", "t": "不是时候"}, {"w": "非计", "t": "失策,不是良计"}, {"w": "非义之财", "t": "不应得的财物"}, {"w": "非直", "t": "不但,不仅"}, {"w": "非细", "t": "不小"}, {"w": "非据", "t": "不应据有的职位。"}]}, {"meaning": "不真实。", "cites": [{"t": "近日小人妄造非语。", "b": "宋·苏轼《谏买浙灯状》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1065wx','叔','1','shū','又','8','','[{"pinyin": "shū", "defs": [{"meaning": "会意兼形声。同本义。", "cites": [{"t": "叔,拾也。", "b": "《说文》。汝南名收芋为叔。"}, {"t": "九月叔苴,采荼薪樗。", "b": "《诗·豳风·七月》"}]}, {"meaning": "假借为“少”。年幼的。", "cites": [{"t": "叔者,少也。", "b": "《白虎通·姓名》"}, {"t": "父之兄弟后生为叔父,父之弟妻为叔母。又夫之弟为叔。", "b": "《尔雅》"}, {"t": "伯某甫,仲叔季,唯其所当。", "b": "《仪礼·士冠礼》"}]}, {"meaning": "古时兄弟长幼顺序常用“伯、仲、叔、季”或“孟、仲、叔、季”表示,叔表示排第三的。", "cites": [{"t": "仲叔继幽沦。", "b": "唐·柳宗元《哭连州凌员外司马》"}]}, {"meaning": "末;衰。", "cites": [{"t": "同姓小邦,则曰叔父,异姓小邦,则曰叔舅。", "b": "《仪礼·觐礼》"}, {"t": "皆叔世也。", "b": "《汉书·刑法志》。注:“晚世也。”"}, {"t": "然所遇之时,实是叔世。", "b": "《晋书·刘颂传》"}], "words": [{"w": "叔世", "t": "末世,衰乱的年代"}, {"w": "叔末", "t": "叔世、末世的合称"}, {"w": "叔季", "t": "末也,国家衰乱将亡的时代,又指少年时代"}, {"w": "叔代", "t": "衰乱的时代。"}]}, {"meaning": "称父亲的弟弟。", "cites": [{"t": "数吕师孟叔侄为逆。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "女性对其丈夫的弟弟的称呼。", "cites": [{"t": "我们山里人,小户人家,这算得什么?她有小叔子,也得娶老婆。", "b": "鲁迅《祝福》"}], "words": [{"w": "叔舅", "t": "母亲的弟弟;周天子对异姓小邦诸侯的称呼"}, {"w": "叔丈人", "t": "妻子的叔父"}, {"w": "叔丈母", "t": "妻子的婶母"}, {"w": "叔郎", "t": "丈夫的弟弟,即小叔"}, {"w": "叔妹", "t": "丈夫的妹妹;即“小姑”"}, {"w": "叔姑", "t": "丈夫的叔母,即“婶婆”。"}]}, {"meaning": "豆类的总称。", "cites": [{"t": "子见夫牺牛乎?衣以文绣,食以刍叔。", "b": "《庄子·列御冠》"}, {"t": "以叔粟当赋。", "b": "《汉书·昭帝纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1066wx','歧','1','qí','止','8','','[{"pinyin": "qí", "defs": [{"meaning": "(同“跂”。形声。从止,支声。或作“岐”。本义:多余的脚趾)。"}, {"meaning": "同本义。", "cites": [{"t": "跂,《说文》:“足多指也。”或作枝歧。", "b": "《集韵》"}, {"t": "歧趾而胪情。", "b": "张衡《思玄赋》"}]}, {"meaning": "叉开,事物错出。", "cites": [{"t": "物两为歧。", "b": "《尔雅·释名》"}, {"t": "歧舌国。", "b": "《山海经·海外南经》"}, {"t": "光歧俨其偕列。", "b": "潘岳《笙赋》"}, {"t": "无为在歧途。", "b": "唐·王勃《杜少府之任蜀州》"}, {"t": "多歧路。", "b": "唐·李白《行路难》"}], "words": [{"w": "歧歧", "t": "禽鸟举翅飞行的样子"}, {"w": "歧旨", "t": "歧义"}, {"w": "歧言", "t": "指离别之言"}, {"w": "歧意", "t": "二心。"}]}, {"meaning": "岔路。", "cites": [{"t": "路旁一歧东上。", "b": "《徐霞客游记·游黄山记》"}]}, {"meaning": "亦指走入歧路。", "cites": [{"t": "大道以多歧亡羊。", "b": "《列子·说符》"}], "words": [{"w": "歧旁", "t": "旁出的岔路"}, {"w": "歧道", "t": "歧路,岔路"}, {"w": "歧阻", "t": "道路阻塞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1067wx','肯','1','kěn','月','8','','[{"pinyin": "kěn", "defs": [{"meaning": "(会意。小篆字形从肉,从冎(guǎ)省。本义:着骨之肉)  同本义。", "cites": [{"t": "肎,骨间肉肎肎着也。", "b": "《说文》。俗字误作肯。"}, {"t": "技经肯綮之未尝。", "b": "《庄子·养生主》"}], "words": [{"w": "肯綮", "t": ""}]}, {"meaning": "假借为“可”。表示应允,同意。", "cites": [{"t": "太后不肯。", "b": "《战国策·赵策》"}, {"t": "留为小吏,不肯。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "劝说了半天,他才肯了;肯认", "t": "认可,同意"}, {"w": "肯可", "t": "赞成,同意"}, {"w": "肯首", "t": "点头表示同意"}, {"w": "肯酒", "t": "允婚酒。表示女方应允亲事。"}]}, {"meaning": "愿意,心甘情愿、乐意。", "cites": [{"t": "莫肯我顾。", "b": "《诗·魏风·硕鼠》"}, {"t": "客肯为靖郭君末寡人乎。", "b": "《战国策·齐策》。注:“犹可也。”"}, {"t": "不肯者,可以肯也。", "b": "《谷梁传·宣公三年》"}, {"t": "秦王不肯击缻。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "李伶即又不肯授我。", "b": "明·清侯方域《壮悔堂文集》"}, {"t": "大将军仁慈不肯发令。", "b": "《广东军务记》"}], "words": [{"w": "肯干;他肯吗?肯吃苦;肯心儿", "t": "心甘情愿"}, {"w": "肯心", "t": "心甘情愿;顺心"}, {"w": "肯道", "t": "愿意。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1068wx','齿','1','chǐ','齿','8','','[{"pinyin": "chǐ", "defs": [{"meaning": "(象形。甲骨文,象嘴里的牙齿,象形字。战国文字在上面加了个声符“止”,成为形声字。小篆同。本义:牙)。"}, {"meaning": "同本义。", "cites": [{"t": "男以八月而生齿,八岁而龀,女七月生齿,七岁而龀。", "b": "《大戴礼记·易本命》"}, {"t": "发堕齿槁。", "b": "《素问·上古天真论》。注:“齿为骨余。”"}], "words": [{"w": "齿吻", "t": "齿及唇"}, {"w": "齿颊", "t": "牙齿与脸颊。"}]}, {"meaning": "排列如齿状的物品。", "cites": [{"t": "齿革羽毛。", "b": "《书·禹贡》。传:“象牙也。”"}], "words": [{"w": "锯齿;梳齿;羊齿", "t": "一种植物。"}]}, {"meaning": "指年龄。", "cites": [{"t": "齿路马有诛。", "b": "《礼记·曲礼》。注:“数年也。”"}, {"t": "古者谓年龄,齿亦龄也。", "b": "《礼记·文王世子》"}, {"t": "退而甘食其土之有,以尽吾齿。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "齿序", "t": "年龄的大小顺序"}, {"w": "齿力", "t": "年龄和体力。"}]}, {"meaning": "并列,次列。", "cites": [{"t": "不敢与诸任齿。", "b": "《左传·隐公十一年》。注:“列也。”"}, {"t": "百官以此相齿。", "b": "《庄子·天下》"}], "words": [{"w": "齿列", "t": "与人同等并列"}, {"w": "齿遇", "t": "以同等相对待"}, {"w": "齿班", "t": "并列。"}]}, {"meaning": "录用,收纳。", "cites": [{"t": "终身不齿。", "b": "《礼记·王制》。注:“犹录也。”按,齿有行列者。"}], "words": [{"w": "齿召", "t": "予以录用征召"}, {"w": "齿用", "t": "录用"}, {"w": "齿旧", "t": "录用旧臣。"}]}, {"meaning": "挡,触。", "cites": [{"t": "吾谋适合意,几亦齿奸锋。", "b": "宋·王安石文"}], "words": [{"w": "齿战", "t": "上下齿连连相击。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1069wx','些','1','xiē','二','8','','[{"pinyin": "xiē", "defs": [{"meaning": "(会意。从此,从二。未详)。"}, {"meaning": "细小。", "cites": [{"t": "雀微贱,身体些小,肌肉瘠瘦,所得盖少。", "b": "三国魏·曹植《鹞雀赋》"}], "words": [{"w": "些子事", "t": "指极细小的违背礼法的事情"}, {"w": "些娘", "t": "方言。细小。"}]}, {"meaning": "少许;一点儿。", "cites": [{"t": "你今日诈得百姓许多财物,如何不借我些?", "b": "《水浒传》"}], "words": [{"w": "些来大", "t": "些娘大。一点点大"}, {"w": "些子儿", "t": "些微,些少,些仔,些些,些儿,些儿子,些屑等都指少许,一点儿。"}]}, {"meaning": "表示不定的多数。一些。", "cites": [{"t": "宋江取些碎银子还了酒钱。", "b": "《水浒传》"}]}, {"meaning": "些。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1070wx','卓','1','zhuó','十','8','','[{"pinyin": "zhuó", "defs": [{"meaning": "(卓的古字。形声。匕形早声。“匕”表示“人”。本义:超然独立;高明;高超)。"}, {"meaning": "同本义。", "cites": [{"t": "卓,高也。", "b": "《说文》"}, {"t": "十日卜为卓。", "b": "《续汉书·五行志》"}, {"t": "如有所立,卓尔。", "b": "《论语》"}, {"t": "鸿卓之义,发于颠沛之朝。", "b": "《论衡》"}, {"t": "嵇延祖卓卓如野鹤之在鸡群。", "b": "《世说新语·容止》"}, {"t": "不胶者卓矣。", "b": "汉·扬雄《法言》"}], "words": [{"w": "卓荦不羁", "t": "卓越超群,不甘受拘束"}, {"w": "卓尔独行", "t": "超越众人"}, {"w": "卓夺", "t": "作出高明的决断"}, {"w": "卓殊", "t": "卓越,特异"}, {"w": "卓逸", "t": "卓越超绝。"}]}, {"meaning": "高远;遥远。", "cites": [{"t": "卓行殊远而粮不绝。", "b": "《汉书·霍去病传》"}, {"t": "卓如日月。", "b": "《后汉书·祭遵传》"}, {"t": "必有卓诡切至。", "b": "《汉书·刘辅传》"}, {"t": "使卓然可观。", "b": "《汉书·成帝纪》"}], "words": [{"w": "卓远", "t": "遥远"}, {"w": "卓望", "t": "远望"}, {"w": "卓卓", "t": "高远的样子"}, {"w": "卓行", "t": "远行"}, {"w": "卓阔", "t": "高远广大。"}]}, {"meaning": "独特。", "cites": [{"t": "彼特以天为父,而身犹爱之,而况其卓乎!", "b": "《庄子》"}]}, {"meaning": "直立。", "cites": [{"t": "王英两脚蹬空,头盔倒卓,撞下马来。", "b": "《水浒传》"}], "words": [{"w": "卓坚", "t": "直立"}, {"w": "卓笔", "t": "直立的笔"}, {"w": "卓锥", "t": "立锥。"}]}, {"meaning": "白额的马。", "cites": [{"t": "奉束帛匹马,卓上,九马随之。中庭西上奠币,再拜稽首。", "b": "《仪礼》"}]}, {"meaning": "", "cites": [{"t": "卓文君。汉临邛大富商卓王孙女,好音律,新寡家居。司马相如过饮于卓氏以琴心挑之,文君夜奔相如,同驰归成都", "b": ""}]}, {"meaning": "建立;竖立。", "cites": [{"t": "僧于言下大悟。遂云,某甲自今已后,向无人烟处卓个草庵。", "b": "《古尊宿语录》"}, {"t": "熙宁中,予使契丹,至其极北黑水境永安山下卓帐。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "卓肩", "t": "耸着肩膀"}, {"w": "头盔倒卓;卓地", "t": "直立于地。"}]}, {"meaning": "停;停留。", "cites": [{"t": "花花满枝红似霞,罗袖画帘肠断,卓香车。", "b": "唐·温庭筠《思帝乡》"}, {"t": "记得去年寒食日,延秋门外卓金轮。", "b": "五代·薛昭蕴《浣溪沙》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1071wx','虎','1','hǔ hù','虍','8','','[{"pinyin": "hǔ", "defs": [{"meaning": "(象形。金文字形象以虎牙、虎纹为特征的虎形。本义:老虎)。"}, {"meaning": "同本义 ,亚洲产的一种大型食肉类哺乳动物(Panthera tigris),在黄褐色的毛皮上有黑色横纹,尾长而无簇毛,有黑圈,下体大部白色,无鬣,典型的体形比狮子略大。", "cites": [{"t": "虎,山兽之君。", "b": "《说文》"}, {"t": "阚如虓虎。", "b": "《诗·大雅·常武》"}, {"t": "虎狼之心。", "b": "《史记·项羽本纪》"}, {"t": "苛政猛于虎。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "曹公豺虎也。", "b": "《资治通鉴》"}, {"t": "气吞万里如虎。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "虎螭", "t": "虎与龙"}, {"w": "虎啸", "t": "虎吼叫"}, {"w": "虎跃", "t": "猛虎腾跃"}, {"w": "虎残", "t": "虎口余生。"}]}, {"meaning": "比喻残酷凶暴。", "cites": [{"t": "或问酷吏。曰:“虎哉!虎哉!角而翼者也”。", "b": "《法言》"}]}, {"meaning": "姓。"}]}, {"pinyin": "hù", "defs": [{"meaning": "[方言] 虎不拉：比喜鹊稍大的一种鸟,性猛善鸣。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1072wx','虏','1','lǔ','虍','8','','[{"pinyin": "lǔ", "defs": [{"meaning": "(形声。从力,从毌(guàn),虍(hū)声。“毌”即“贯”字,是穿钱用的绳索。这里表示用绳索拘捕的意思。本义:俘获)。"}, {"meaning": "同本义。", "cites": [{"t": "虏,获也。", "b": "《说文》"}, {"t": "献民虏者操右袂。", "b": "《礼记·曲礼》。注:“军所获也。”"}, {"t": "且为所虏。", "b": "《史记·项羽本纪》"}, {"t": "虏楚将屈匄。", "b": "《史记·屈原贾生列传》"}, {"t": "虏赵王。", "b": "《战国策·燕策》"}]}, {"meaning": "亦指虏掠、抄掠。", "cites": [{"t": "珠柙离丘体,珍宝见剽虏。", "b": "张载《七哀》"}, {"t": "匈奴虏略千余人及畜产而去。", "b": "《史记·韩长孺列传》"}], "words": [{"w": "虏掠", "t": "虏获掠夺"}, {"w": "虏夺", "t": "虏掠抢夺"}, {"w": "虏暴", "t": "残害暴虐他人,一如奴隶"}, {"w": "虏略", "t": "虏获掠夺。"}]}, {"meaning": "俘虏。", "cites": [{"t": "乘奔逐北,斩首捕虏十余万。", "b": "《盐铁论·诛秦》"}, {"t": "吾属今为之虏矣!", "b": "《史记·项羽本纪》"}, {"t": "为降虏手蛮夷。", "b": "《汉书·李广苏建传》"}, {"t": "为奔亡之虏。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "乞为囚虏。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "虏囚", "t": "俘虏"}, {"w": "虏役", "t": "奴役"}, {"w": "虏伏", "t": "如俘虏一样降服。"}]}, {"meaning": "奴仆。", "cites": [{"t": "虽臣虏之劳不苦于此矣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "虏役", "t": "奴仆"}, {"w": "虏使", "t": "役使之如奴隶。"}]}, {"meaning": "指敌人;叛逆。", "cites": [{"t": "则直前诟虏帅失信。", "b": "文天祥《指南录后序》"}], "words": [{"w": "虏尘", "t": "指敌寇或叛乱者的侵扰。"}]}, {"meaning": "古时对北方外族或南方人对北方人的蔑称。", "cites": [{"t": "诟虏帅失信。", "b": "宋·文天祥《指南录后序》"}, {"t": "奉西北之虏。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "虏人", "t": "胡人"}, {"w": "虏民", "t": "胡族的人民"}, {"w": " 虏廷", "t": "胡虏的朝廷"}, {"w": " 虏使", "t": "胡虏的使臣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1073wx','肾','1','shèn','月','8','','[{"pinyin": "shèn", "defs": [{"meaning": "位于脊椎动物体腔内脊柱近旁的一对内脏器官,它排出尿液、尿酸和其它代谢的排泄物。", "cites": [{"t": "肾,水藏也。从肉,茞声。", "b": "《说文》"}, {"t": "肾者,主蛰封藏之本,精之处也。其华在发,其充在骨。", "b": "《素问·六节藏象论》"}], "words": [{"w": "肾肠", "t": "肺腑,比喻诚意"}, {"w": "肾痹", "t": "五脏痹症之一,主要症状为骨萎弱不能行走,腰背弯曲或关节肿胀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1074wx','贤','1','xián','贝','8','','[{"pinyin": "xián", "defs": [{"meaning": "(形声。从贝,与财富有关。本义:多财)。"}, {"meaning": "有德行;多才能。", "cites": [{"t": "贤,多才也。", "b": "《说文》"}, {"t": "以财分人之谓贤。", "b": "《庄子·徐无鬼》"}, {"t": "相如既归,赵王以为贤大夫。", "b": "《史记》"}, {"t": "闲贤臣。", "b": "诸葛亮《出师表》"}], "words": [{"w": "贤声远达", "t": "好的名声远扬四处"}, {"w": "贤歌", "t": "品行技艺都好的歌妓"}, {"w": "贤才", "t": "德才并美之人"}, {"w": "时贤", "t": "指当代有贤能有声望的人。"}]}, {"meaning": "对人的敬称。", "cites": [{"t": "凡与人言……自叔父母以下,则加“贤”字。", "b": "《颜氏家训》"}, {"t": "分明是如贤所教,但是小生自小坐书斋,不谙其他生活。", "b": "《新编五代史评话》"}], "words": [{"w": "贤宰", "t": "知县"}, {"w": "贤乔梓", "t": "尊称人家父子"}, {"w": "贤竹林", "t": "魏晋间“竹林七贤”。后用作对他人叔姪的敬称"}, {"w": "贤弟;贤甥", "t": ""}]}, {"meaning": "良,美善。", "cites": [{"t": "东家有贤女。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "多闻其贤。", "b": "《史记·陈涉世家》"}, {"t": "非不贤也。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "贤否", "t": "好的与坏的"}, {"w": "贤妻", "t": "贤淑的妻子"}, {"w": "贤慧", "t": "称美女子善良而明大义。"}]}, {"meaning": "艰难;劳苦。", "cites": [{"t": "大夫不均,我从事独贤。", "b": "《诗·小雅·北山》"}]}, {"meaning": "有才德的人;人才。", "cites": [{"t": "三曰进贤。", "b": "《周礼·太宰》。注:“有善行也。”"}, {"t": "思贤如渴。", "b": "《三国志·诸葛亮传》"}, {"t": "唐贤今人。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "尊贤而重士(贤,形容词作名词用,贤人)。", "b": "汉·贾谊《过秦论》"}, {"t": "思贤如渴。", "b": "《三国志》"}], "words": [{"w": "贤圣", "t": "圣贤"}, {"w": "前贤", "t": "有才德的前辈"}, {"w": "先贤", "t": "已去世的有才德的人"}, {"w": "圣贤", "t": "圣人和贤人。"}]}, {"meaning": "人的贤能。", "cites": [{"t": "其贤不及孔子。", "b": "唐·韩愈《师说》"}]}, {"meaning": "胜过,超过。", "cites": [{"t": "师不必贤于弟子。", "b": "韩愈《师说》"}, {"t": "贤于长安君。", "b": "《战国策·赵策》"}, {"t": "贤于己者。", "b": "清·刘开《问说》"}]}, {"meaning": "尊重;崇尚。", "cites": [{"t": "子夏说:“贤贤易色”。", "b": "《老残游记》"}], "words": [{"w": "贤贤易色", "t": "学习贤美的品德来改变好色之心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1075wx','尚','1','shàng','小','8','','[{"pinyin": "shàng", "defs": [{"meaning": "(会意。从八,向声。本义:尚且)。"}, {"meaning": "同本义。", "cites": [{"t": "尚,曾也。", "b": "《说文》"}, {"t": "尚无为。", "b": "《诗·王风·免爰》"}]}, {"meaning": "又。", "cites": [{"t": "尚无造。", "b": ""}, {"t": "尚求其雌。", "b": "《诗·小雅·小弁》"}, {"t": "亦尚一人之庆。", "b": "《书·秦誓》"}, {"t": "元济尚寝,笑曰:“俘囚为盗耳,晓当尽戮之。”", "b": "《资治通鉴·唐纪》"}, {"t": "臣以布衣之交尚不相欺,况大国乎?", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "尚有不少;尚来得及;尚未娶亲;尚待研究;尚兀自", "t": "还;尚且"}, {"w": "尚尔", "t": "尚且这样"}, {"w": "尚自", "t": "尚且"}, {"w": "尚然", "t": "尚且"}, {"w": "尚犹", "t": "犹,还。"}]}, {"meaning": "还;仍然。", "cites": [{"t": "赵王使使(派使者)视廉颇尚可用否。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "如仆尚何言哉?", "b": "司马迁《报任安书》"}]}, {"meaning": "希望  表示命令或希望。", "cites": [{"t": "鸣呼哀哉!伏惟尚飨。", "b": "柳宗元《为韦京兆祭太常崔少卿文》"}]}, {"meaning": "差不多。", "cites": [{"t": "灵王卜曰:“余尚得天下。”", "b": "《左传·昭公十三年》"}]}, {"meaning": "尚假借为“上”,尊崇。", "cites": [{"t": "尚,上也。", "b": "《广雅》"}, {"t": "以其上古之书谓之尚书。", "b": "《书·孔安国序》"}, {"t": "尚有晋国。", "b": "《国语·晋语》"}, {"t": "学者多称五帝,尚矣!", "b": "《史记·五帝纪》"}, {"t": "尚论古之人。", "b": "《孟子·万章下》"}, {"t": "尚三王只。", "b": "《楚辞·大招》"}, {"t": "尚左。", "b": "《仪礼·觐礼》"}, {"t": "宣德间,宫中尚促织之戏。", "b": "《聊斋志异·促织》"}, {"t": "且五方土音,乡俗好尚,习见习闻。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "崇尚", "t": "尊重;推崇"}, {"w": "尚茅茨", "t": "崇尚茅屋"}, {"w": "尚齿", "t": "尊崇年老的人"}, {"w": "尚年", "t": "尊崇年长者"}, {"w": "尚左", "t": "以左为尊"}, {"w": "尚右", "t": "以右为尊"}, {"w": "尚白", "t": "崇尚白色。"}]}, {"meaning": "重视。", "cites": [{"t": "臣欲使士大夫尊尚武勇,讲习兵法。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "尚文", "t": "重视文治"}, {"w": "尚气", "t": "重气节,重义气;负气。"}]}, {"meaning": "仰慕。", "cites": [{"t": "尚前良之遗风兮,恫后辰而无及。", "b": "汉·张衡《思玄曲》"}]}, {"meaning": "佑,佑助。", "cites": [{"t": "象曰:包荒得尚于中行,以光大也。", "b": "《易·泰》"}]}, {"meaning": "给帝王管理事物。", "cites": [{"t": "今日堂有炼珍,朝分尚食。", "b": "清·周容《芋老人传》"}], "words": [{"w": "尚食", "t": "掌帝王膳食"}, {"w": "尚宝", "t": "明代官名。掌理宝玺、金银、符牌等事"}, {"w": "尚衣", "t": "古官名。掌管帝王衣服"}, {"w": "尚席", "t": "官名。掌理宫中筵席"}, {"w": "尚宫", "t": "宫中女官名。为宫官的首长,掌管导引皇后及闺阁廪赐。"}]}, {"meaning": "夸耀。", "cites": [{"t": "君子不自大其事,不自尚其功。", "b": "《礼记·表记》"}]}, {"meaning": "超过;高出。", "cites": [{"t": "得闻先生之余论,则大庭氏何以尚兹?", "b": "张衡《东京赋》"}]}, {"meaning": "奉;承。", "cites": [{"t": "愿赐问而自进兮,得尚君之玉音。", "b": "《文选·司马相如·长门赋》"}]}, {"meaning": "仰攀婚姻。", "cites": [{"t": "卓王孙喟然而叹,自以得使女尚司马长卿晚。", "b": "《史记》"}]}, {"meaning": "加上,往…上补充东西。", "cites": [{"t": "尚之以琼华乎而。", "b": "《诗·齐风·著》"}], "words": [{"w": "尚絅", "t": "穿锦衣时加上罩袍,以使华美不显耀于外。"}]}, {"meaning": "荐举;选拔。", "cites": [{"t": "尚者,《五制》:“上贤以崇德”,“上贤谓举贤也”。上与尚通。", "b": "《广雅》王念孙疏证"}]}, {"meaning": "娶帝王之女为妻。", "cites": [{"t": "诸男皆尚秦公主。", "b": "《史记·李斯列传》"}], "words": [{"w": "尚主", "t": "娶公主为妻。"}]}, {"meaning": "志向;愿望。", "cites": [{"t": "平生有微尚,欢笑自此毕。", "b": "李白《登峨眉山》"}]}, {"meaning": "久远;古远。", "cites": [{"t": "乐所由来者尚矣。", "b": "《吕氏春秋·古乐》"}], "words": [{"w": "尚远", "t": "久远。"}]}, {"meaning": "自负;骄傲。", "cites": [{"t": "虽才高于世,而无骄尚之情。", "b": "《后汉书·张衡传》"}]}, {"meaning": "上,高尚。", "cites": [{"t": "南阳刘子骥,高尚士也。", "b": "陶渊明《桃花源记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1076wx','旺','1','wàng','日','8','','[{"pinyin": "wàng", "defs": [{"meaning": "(形声。从日,王声。本义:光美) 日晕。", "cites": [{"t": "旺,日晕。", "b": "《玉篇》"}]}, {"meaning": "火势炽烈。", "cites": [{"t": "翠环道:“屋里火盆旺着呢!快向屋里烘去罢!”", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1077wx','具','1','jù','八','8','','[{"pinyin": "jù", "defs": [{"meaning": "(会意。甲骨文字形,上面是“鼎”,下面是双手。表示双手捧着盛有食物的鼎器(餐具)。本义:准备饭食或酒席)。"}, {"meaning": "同本义。泛指准备,备办。", "cites": [{"t": "具,供置也。", "b": "《说文》"}, {"t": "具,备也,办也。", "b": "《广韵》"}, {"t": "以食具告。", "b": "《仪礼·士相见礼》。注:“犹办也。”"}, {"t": "官备则具备。", "b": "《礼记·祭统》"}, {"t": "寿为具召武帝显。", "b": "《汉书·何武传》"}, {"t": "礼举仪具。", "b": "张衡《东京赋》"}, {"t": "具器械。", "b": "《孙子·谋攻》"}, {"t": "故人具鸡黍。", "b": "唐·孟浩然《过故人庄》"}, {"t": "第二板已具。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "别具本章。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "具食", "t": "准备食物"}, {"w": "具觞", "t": "备酒。觞:酒杯"}, {"w": "具状", "t": "备办词状;写状子"}, {"w": "具禀", "t": "备办上报的文件"}, {"w": "具覆", "t": "备办回复的文件。"}]}, {"meaning": "写,题。", "cites": [{"t": "李具状求在狱。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "具草", "t": "拟稿,起草"}, {"w": "具衔", "t": "题写官衔"}, {"w": "知名不具;具结检验", "t": "与案件有关的人员出具保证,以免对尸体、现场等进行检验。"}]}, {"meaning": "具备,有。", "cites": [{"t": "具乎其前。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "各具情态。", "b": "明·魏学洢《核舟记》"}, {"t": "狱具矣。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "具寿", "t": "和尚的通称。师父呼弟子或长老呼少年和尚时常用。具有尽其寿命及法身慧命的意思"}, {"w": "具眼", "t": "具有鉴别事物的见识和能力"}, {"w": "具足", "t": "具备。"}]}, {"meaning": "判决;定案。", "cites": [{"t": "有某姓兄弟,以把持公仓,法应立决,狱具矣。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "用具;器械。", "cites": [{"t": "实战之具。", "b": "汉·贾谊《新书·过秦论上》"}, {"t": "奉生送死之具。", "b": "《史记·货殖列传》"}, {"t": "虑患之具。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "具器食", "t": "用食具盛放的便餐"}, {"w": "具理", "t": "瓶罐之类的器皿"}, {"w": "农具;文具;刑具;卧具;茶具;道具;餐具;量具", "t": ""}]}, {"meaning": "才能;才干。", "cites": [{"t": "皆信命世之才,抱将相之具。", "b": "《文选·李陵·答苏武书》"}, {"t": "干诚之具。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "酒席。", "cites": [{"t": "今有贵客,为具召之。", "b": "《史记》"}]}, {"meaning": "饭食。", "cites": [{"t": "食以草具。", "b": "《战国策·齐策四》"}, {"t": "则佐长者视具。", "b": "《礼记·内则》。注:“馔也。”"}, {"t": "分曹携具。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "完备;详尽。", "cites": [{"t": "项伯乃夜驰之沛公军,私见张良,具告以事。欲呼张良与俱去,曰:“无从俱死也。”", "b": "《史记·项羽本纪》"}, {"t": "此人一一为具言所闻。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "具述", "t": "详细叙述"}, {"w": "具言", "t": "详细说明"}, {"w": "具考", "t": "详细推问"}, {"w": "具论", "t": "详细讨论"}, {"w": "具告", "t": "详细上告。"}]}, {"meaning": "假借为“俱”。都;全。", "cites": [{"t": "火烈具举。", "b": "《诗·郑风·大叔于田》"}, {"t": "火烈具扬。", "b": ""}, {"t": "神具醉止。", "b": "《诗·小雅·楚茨》"}, {"t": "莫怨具庆。", "b": ""}, {"t": "具馔于西塾。", "b": "《仪礼·士冠礼》"}, {"t": "皆立而待鼓而然火,即具发之。", "b": "《墨子·备梯》"}, {"t": "谋之其臧,则具是违;谋之不臧,则具是依。", "b": "《荀子·修身》"}, {"t": "具答之。", "b": "晋·陶渊明《桃花源记》"}, {"t": "政通人和,百废具兴。", "b": "范仲淹《岳阳楼记》"}, {"t": "具以情告。", "b": "《世说新语·自新》"}, {"t": "具对所得。", "b": "宋·胡仔《苕溪渔隐丛话》"}], "words": [{"w": "具悉", "t": "完全了解"}, {"w": "具然", "t": "自足的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1078wx','味','1','wèi','口','8','','[{"pinyin": "wèi", "defs": [{"meaning": "(形声。从口,未声。本义:滋味)。"}, {"meaning": "同本义。", "cites": [{"t": "味,滋味也。", "b": "《说文》"}, {"t": "以五味五谷五药养其病。", "b": "《周礼·疾医》"}, {"t": "味者,气之父母也。", "b": "《鹖冠子·泰录》"}, {"t": "五味六和十二食。", "b": "《礼记·礼运》"}, {"t": "一镬之味。", "b": "《吕氏春秋·察今》"}, {"t": "其味皆苦。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "味亦苦。", "b": ""}, {"t": "味苦而微辛。", "b": ""}], "words": [{"w": "味如嚼蜡", "t": "比喻诗文枯燥,读后令人心情不舒"}, {"w": "入味", "t": "有滋味"}, {"w": "味口", "t": "犹胃口。指食欲"}, {"w": "味欲", "t": "对美味的嗜好"}, {"w": "口味", "t": "饮食品的滋味。"}]}, {"meaning": "食物。", "cites": [{"t": "食不二味,坐不重席。", "b": "《韩非子》"}]}, {"meaning": "——用于中药配方药物的一种为一味。", "cites": [{"t": "加入几味祛风的药。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1079wx','果','1','guǒ','木','8','','[{"pinyin": "guǒ", "defs": [{"meaning": "(象形。甲骨文字形,田象树上结的果实形,在木之上。本义:果子,果实。这个意义后来曾写作“菓”)。"}, {"meaning": "同本义。", "cites": [{"t": "果,木实也。", "b": "《说文》"}, {"t": "艮为果蓏。", "b": "《易·说卦》"}, {"t": "而树之果蓏,珍异之物。", "b": "《周礼·场人》。张晏曰:“有核曰果,无核曰蓏。”臣瓒曰:“在地曰蓏,在树曰果。”"}, {"t": "五果为助。", "b": "《素问·藏器法时论》。注:“谓桃李杏栗枣也。”"}, {"t": "凡长安豪富人为观游及卖果者,皆争迎取养。", "b": "柳宗元《种树郭橐驼传》"}, {"t": "杭有卖果者,善藏柑。", "b": "明·刘基《卖柑者言》"}, {"t": "果止于梨、栗、枣、柿之类。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "果布", "t": "果品与布帛"}, {"w": "果馔", "t": "果品与菜肴"}, {"w": "果谷", "t": "果类与谷类"}, {"w": "果正", "t": "正果。亦指转世"}, {"w": "果桌", "t": "果卓。摆设筵席用的桌子"}, {"w": "草果;荚果;浆果;果瓜", "t": "供果用的甜瓜"}, {"w": "果茹", "t": "瓜果蔬菜"}, {"w": "果隋", "t": "瓜果"}, {"w": "果蔗", "t": "一种供鲜食的甘蔗。"}]}, {"meaning": "结果。", "cites": [{"t": "贵贱虽复殊途,因果竟在何处。", "b": "《南史·范云传》附范缜"}, {"t": "敌人既然敢犯罪,他就该自食其恶果!", "b": ""}], "words": [{"w": "果验", "t": "应验"}, {"w": "战果;效果;成果;自食其果;恶果", "t": ""}]}, {"meaning": "(guàn)。古代帝王以酒祭奠祖先或赐宾客饮之礼。", "cites": [{"t": "大宾客则摄而载果。", "b": "《周礼·春官》"}, {"t": "以待果将。", "b": ""}]}, {"meaning": "果敢,果断。", "cites": [{"t": "由也果。", "b": "《论语》。苞注:“谓果敢决断也。”"}, {"t": "其身果而辞顺。", "b": "《国语·晋语》。注:“谓敢行其志也。”"}, {"t": "故制戎以果毅,制朝以序成。", "b": "《国语·周语中》"}, {"t": "凡此之辈数百人,皆忠壮果烈,有智有仁。", "b": "汉·陈琳《檄吴将校部曲文》"}], "words": [{"w": "言必行,行心果;果谲", "t": "果敢而多谋的计谋"}, {"w": "果直", "t": "果敢正直"}, {"w": "果烈", "t": "果敢刚毅"}, {"w": "果侠", "t": "果敢仗义"}, {"w": "果劲", "t": "果敢强劲"}, {"w": "果行", "t": "果断的行动"}, {"w": "果志", "t": "果断之志"}, {"w": "果勇", "t": "果断勇猛"}, {"w": "果悍", "t": "果断勇猛。"}]}, {"meaning": "(luǒ)。赤体。赤露。", "cites": [{"t": "东龟曰果属。", "b": "《周礼·春官·龟人》"}]}, {"meaning": "吃饱。", "cites": [{"t": "充嗛果腹兮,骄傲欢欣。", "b": "唐·柳宗元《赠王孙文》"}], "words": [{"w": "果腹;果足", "t": "盘缠;旅费。"}]}, {"meaning": "实现。凡事与预期相合的称果,不合的称不果。", "cites": [{"t": "闻之,欣然规往。未果,寻病终。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "果然,当真。", "cites": [{"t": "如姬果盗兵符与公子。", "b": "《史记·魏公子列传》"}, {"t": "审知故松山列难督师洪公果死耶,抑未死耶?", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "果不出所料;果尔", "t": "果真如此"}, {"w": "果是", "t": "果然是"}, {"w": "果若", "t": "果真。"}]}, {"meaning": "究竟,终于,到底。", "cites": [{"t": "夫当今生民之患果安在哉?在于知安而不知危,能逸而不能劳。", "b": "宋·苏轼《教战守》"}, {"t": "果不如先愿,又非君所详。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "如果,假若。", "cites": [{"t": "丈人顾先生曰:“果如是,是羿亦有罪焉”。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "果能如此", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1080wx','昆','1','kūn','日','8','','[{"pinyin": "kūn", "defs": [{"meaning": "(会意。从日,从比。金文字形,表示二人在日光下并肩行走 。本义:一起,共同)。"}, {"meaning": "同本义。", "cites": [{"t": "昆,同也。", "b": "《说文》"}, {"t": "理生昆群。", "b": "《太玄·玄摛》"}, {"t": "格也乖而昆也同。", "b": "《太玄·玄错》"}, {"t": "昆仑旁薄幽。", "b": "《太玄中》"}, {"t": "噍(jiū)噍昆鸣。", "b": "扬雄《羽猎赋》"}], "words": [{"w": "昆群", "t": "同群。"}]}, {"meaning": "后,然后。", "cites": [{"t": "魂兮归徕,正始昆只。", "b": "《楚辞》"}]}, {"meaning": "哥哥,胞兄。", "cites": [{"t": "昆,兄也。", "b": "《广韵》"}, {"t": "终远兄弟,谓他人昆。", "b": "《诗·王风·葛藟》"}, {"t": "昔有昆弟三人。", "b": "《列子》"}], "words": [{"w": "昆友", "t": "兄弟和朋友"}, {"w": "昆仲", "t": "称呼别人兄弟的敬词"}, {"w": "昆玉", "t": "对别人兄弟的敬称。"}]}, {"meaning": "子孙,后代。", "cites": [{"t": "虞、魏之昆。", "b": "左思《吴都赋》"}], "words": [{"w": "昆仍", "t": "后代子孙"}, {"w": "昆孙", "t": "第六代的子孙。后泛指远孙。"}]}, {"meaning": "昆山 。古代传说中产玉之山。", "cites": [{"t": "火炎昆冈,玉石俱焚。", "b": "《书·胤征》"}]}, {"meaning": "众多,诸多。", "cites": [{"t": "昆小虫,抵蚳。昆,众也。", "b": "《大戴礼记》"}]}, {"meaning": "盛明貌。", "cites": [{"t": "樵蒸昆上,配藜四施。", "b": "《文选·扬雄·甘泉赋》"}]}, {"meaning": "——见“昆仑山”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1081wx','国','1','guó','囗','8','','[{"pinyin": "guó", "defs": [{"meaning": "(会意。从“囗”(wéi),表示疆域。从或(即“国”)。“或”亦兼表字音。本义:邦国)。"}, {"meaning": "周代,天子统治的是“天下”,略等于现在说的“全国”。", "cites": [{"t": "国,邦也。", "b": "《说文》"}, {"t": "以佐王治邦国。", "b": "《周礼·太宰》。注:“大曰邦,小曰国。”"}, {"t": "方千里曰国畿,诅祝以叙国之信用,以资邦国之剂信。", "b": "《周礼·大司马》。注:“国谓王之国;邦国,谓诸侯国也。”"}, {"t": "都城过百雉,国之害也。", "b": "《左传·隐公元年》"}, {"t": "丘也闻有国有邦者。", "b": "《论语·微子》"}, {"t": "夫大国,难测也,惧有伏焉。", "b": "《左传·庄公十年》"}, {"t": "秦人开关延敌,九国之师,逡巡而不敢进。", "b": "汉·贾谊《新书·过秦论上》"}], "words": [{"w": "齐国;晋国;郑国", "t": ""}]}, {"meaning": "国都,一国最高政权机关所在地。又称国城,国邑。", "cites": [{"t": "国中九经九纬。", "b": "《考工记·匠人》。注:“城内也。”"}, {"t": "三曰国禁。", "b": "《周礼·士师》。注:“城中也。”"}, {"t": "在国曰市井之臣。", "b": "《孟子》。注:“谓都邑也。”"}, {"t": "土国地漕。", "b": "《诗·邶风·击鼓》"}, {"t": "先王之制,大都不过参国之一,中五之一,小九之一。", "b": "《左传·隐公元年》"}, {"t": "武夫力而拘诸原,妇人暂而免诸国。", "b": "《左传·僖公三十三年》"}, {"t": "愿君顾先王之宗庙,姑反国统万人乎!", "b": "《战国策·齐策》"}, {"t": "登斯楼也,则有去国怀乡,忧馋畏讥,满目萧然,感极而悲者矣。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "国中", "t": "王城之内;国内"}, {"w": "国人", "t": "国都中的人"}, {"w": "国迁", "t": "国都迁徙"}, {"w": "国阴", "t": "都城北郊"}, {"w": "国郊", "t": "国都周围地名"}, {"w": "国禁", "t": "古代国都中的禁令"}, {"w": "国邑", "t": "城邑"}, {"w": "国刑", "t": "城中施行的刑罚。"}]}, {"meaning": "国家。", "cites": [{"t": "聊以行国。", "b": "《诗·魏风·园有桃》"}, {"t": "国无有残。", "b": "《诗·大雅·民劳》"}, {"t": "僵卧孤村不自哀,尚思为国戍轮台。", "b": "宋·陆游《十一月四日风雨大作》"}, {"t": "思国之安者,必积其德义。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "国人皆以诸先烈之牺牲精神为国奋斗。", "b": "孙文《黄花冈七十二烈士事序》"}], "words": [{"w": "国纪", "t": "旧指国家礼制与法令"}, {"w": "国帑", "t": "国库中的钱币"}, {"w": "国禄", "t": "国家的俸禄"}, {"w": "国课", "t": "国税;国家税收"}, {"w": "国器", "t": "可主持国政的人才。"}]}, {"meaning": "古代王、侯的封地。", "cites": [{"t": "汉王之国,良送至褒中。", "b": "《史记·留侯之家》"}, {"t": "孟尝君就国于薛。", "b": "《战国策·齐策》"}], "words": [{"w": "国租", "t": "封地的田赋。"}]}, {"meaning": "部落。", "cites": [{"t": "[韩]凡七十八国。伯济是其一国焉。大者万余户,小者数千家,各在山海间。", "b": "《后汉书》"}]}, {"meaning": "地方。", "cites": [{"t": "荆州北据汉沔,利尽南海,东连吴会,西通巴蜀,此用武之国。", "b": "晋·陈寿《三国志·诸葛亮传》"}, {"t": "逝将去女,适彼乐国。", "b": "《诗·魏风·硕鼠》"}]}, {"meaning": "家乡。", "cites": [{"t": "[侃]欲逊位归国,佐吏等苦留之。", "b": "《晋书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1082wx','哎','1','āi','口','8','','[{"pinyin": "āi", "defs": [{"meaning": "叹词，表示不满或提醒。", "words": [{"w": "哎呀", "t": "表示惊讶或赞叹"}]}, {"meaning": "表示惊讶或不满意。哎,你怎么不早说! "}, {"meaning": "表示提醒。哎,小声点 ! "}, {"meaning": "表示醒悟。哎!原来是这样! "}, {"meaning": "表示招呼。哎,大婶,我们回头再来看你! "}, {"meaning": "表示答应。哎,我一会儿就来! "}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1083wx','咕','1','gū','口','8','','[{"pinyin": "gū", "defs": [{"meaning": "鸟的叫声", "words": [{"w": "咕咕", "t": "鸟的叫声。"}]}, {"meaning": "小声说话，低声说话等的声音", "words": [{"w": "咕哝", "t": "小声说话或自言自语。"}]}, {"meaning": "象声词,脚踩进泥水的声音", "words": [{"w": "咕哧", "t": "他‘咕哧’一声踩进水稻田。"}]}, {"meaning": "[方言]低声说话等的声音", "words": [{"w": "嘀咕", "t": "她俩在角落里咕哧了一阵子。"}]}, {"meaning": "嘀咕唠叨;自言自语", "words": [{"w": "咕叨", "t": "别咕叨了,听听大伙的意见! "}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1084wx','昌','1','chāng','日','8','','[{"pinyin": "chāng", "defs": [{"meaning": "(会意。从日,从曰。本义:善,正当)。"}, {"meaning": "同本义。", "cites": [{"t": "昌,美言也。", "b": "《说文》"}, {"t": "禹拜昌言。", "b": "《书·大禹谟》"}], "words": [{"w": "昌言", "t": "正直的善言、好话"}, {"w": "昌教", "t": "善美的教化。"}]}, {"meaning": "兴旺发达,与“亡”相对。", "cites": [{"t": "邦乃其昌。", "b": "《书·仲虺之诰》"}, {"t": "顺之者昌,逆之者不死则亡。", "b": "《史记·太史公自序》"}, {"t": "今中国未闻有因变法而流血者,此国之所以不昌也。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "昌瑞", "t": "昌盛祥瑞"}, {"w": "昌乐", "t": "兴盛安乐。"}]}, {"meaning": "光;光明。", "cites": [{"t": "一曰日光。诗曰:东方昌昌。", "b": "《说文》"}], "words": [{"w": "昌晖", "t": "光明"}, {"w": "昌华", "t": "光华。"}]}, {"meaning": "壮大;美好。", "cites": [{"t": "猗嗟昌兮,颀而长兮。", "b": "《诗·齐风·猗嗟》"}], "words": [{"w": "昌大", "t": "盛大"}, {"w": "昌化", "t": "大的恩泽"}, {"w": "昌世", "t": "太平盛世。"}]}, {"meaning": "生物。", "cites": [{"t": "今夫百昌皆生于土而反于土。", "b": "《庄子·在宥》。释文:“百昌,犹百物也。”"}]}, {"meaning": "", "words": [{"w": "昌本", "t": "菖蒲根"}, {"w": "昌羊", "t": "即菖蒲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1085wx','呵','1','hē hā kē ā a','口','8','','[{"pinyin": "hē", "defs": [{"meaning": "(形声。从口,可声。本义:怒责,大声发怒地喝斥)。"}, {"meaning": "同本义。", "cites": [{"t": "訶,大言而怒也。从言,可声,字亦作呵。", "b": "《说文》"}, {"t": "訶,怒也。", "b": "《广雅·释诂二》"}, {"t": "纵而弗呵虖。", "b": "《汉书·食货志》。注:“责怒也。”"}, {"t": "青邶之山有鸟焉,其音若呵。", "b": "《山海经·南山经》"}, {"t": "呵,责也。", "b": "《玉篇》"}, {"t": "王出而訶之。", "b": "《韩非子·内储说下》"}, {"t": "厉声以呵。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "呵咄", "t": "大声斥责;吆喝"}, {"w": "呵怒", "t": "怒斥"}, {"w": "呵格", "t": "喝斥殴打"}, {"w": "呵索", "t": "呵叱搜查"}, {"w": "呵辱", "t": "辱骂"}, {"w": "呵逐", "t": "斥骂驱逐"}, {"w": "呵问", "t": "责问;盘究。"}]}, {"meaning": "喝道,喝令行人让路。", "cites": [{"t": "武夫前呵,从者塞途。", "b": "韩愈《送李愿归盘谷序》"}], "words": [{"w": "呵引", "t": "呵道"}, {"w": "呵卫", "t": "喝道护卫的人"}, {"w": "呵道", "t": "亦作“呵导”。古时贵人外出时,引路差役喝令行人让路。"}]}, {"meaning": "喝。", "cites": [{"t": "次日早辰,小鸦儿吃了几个冷饼,呵了两碗热水,依旧挑了担子出去。", "b": "《醒世姻缘传》"}, {"t": "你不吃,呵嗏儿罢。", "b": "《金瓶梅词话》"}]}, {"meaning": "笑声。", "cites": [{"t": "有酒且呵呵,人生能几何?", "b": "韦庄《菩萨蛮》词"}], "words": [{"w": "呵呵", "t": "笑声"}, {"w": "呵呵大笑", "t": ""}]}]}, {"pinyin": "hā", "defs": [{"meaning": "弯。", "cites": [{"t": "他很大方地呵一呵腰,就走出去了。", "b": "茅盾《子夜》"}]}]}, {"pinyin": "kē", "defs": [{"meaning": "", "words": [{"w": "呵罗单,古国名,故地在今苏门答腊岛", "t": ""}]}]}, {"pinyin": "ā", "defs": [{"meaning": "表示惊异或赞叹。同“啊”。", "cites": [{"t": "呵,青春,愿你光芒四射。", "b": "郭小川《致青年公民》"}]}]}, {"pinyin": "a", "defs": [{"meaning": "表示感叹或惊讶的语气。", "cites": [{"t": "安家立业了,日子过好了,可是不能忘本呵。", "b": "周立波《暴风骤雨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1086wx','畅','1','chàng','田','8','','[{"pinyin": "chàng", "defs": [{"meaning": "(形声。从申,昜(yáng)声。本义:畅通,无阻碍)。"}, {"meaning": "同本义。", "cites": [{"t": "登台四望,三面皆畅。", "b": "《韩非子·说林上》"}, {"t": "美在其中,而畅于四支。", "b": "《易·坤》"}], "words": [{"w": "通畅", "t": "运行无阻"}, {"w": "顺畅", "t": "顺利通畅,没有阻碍。"}]}, {"meaning": "舒畅。", "cites": [{"t": "旧国旧都,望之畅然。", "b": "《庄子·则阳》"}, {"t": "感条畅之气。", "b": "《礼记·乐记》"}, {"t": "美声畅于虞氏。", "b": "《文选·张衡·西京赋》"}], "words": [{"w": "宽畅", "t": "心里舒畅"}, {"w": "酣畅", "t": "畅快。"}]}, {"meaning": "茂盛。", "cites": [{"t": "草木畅茂。", "b": "《孟子·滕文公上》"}]}, {"meaning": "正;极;甚。", "cites": [{"t": "青衫忒离俗,栽得畅可体。", "b": "《董西厢》"}], "words": [{"w": "畅好", "t": "畅好是,畅好道。真是,真正;正好,甚好。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1087wx','明','1','míng','日','8','','[{"pinyin": "míng", "defs": [{"meaning": "(会意。甲骨文以“日、月”发光表示明亮。小篆从月囧(jiǒng),从月,取月之光;从囧,取窗牖之明亮。本义:明亮,清晰明亮)。"}, {"meaning": "同本义。与“昏暗”相对。", "cites": [{"t": "朙,照也。", "b": "《说文》"}, {"t": "照临四方曰明。", "b": "《左传·昭公二十八年》"}, {"t": "东方明矣。", "b": "《诗·齐风·鸡鸣》"}, {"t": "明,精白也。", "b": "《国语·周语》"}, {"t": "视曰明。", "b": "《书·洪范》"}, {"t": "明则著。", "b": "《礼记·中庸》"}, {"t": "明星谓之启明。", "b": "《尔雅》"}, {"t": "东有启明。", "b": "《诗·小雅·大东》"}, {"t": "在天者莫明于日月。", "b": "《荀子·天论》"}, {"t": "不知明镜里,何处得秋霜。", "b": "唐·李白《秋浦歌》"}, {"t": "“月明星稀,乌鹊南飞”,此非曹孟德之诗乎?", "b": "苏轼《赤壁赋》"}, {"t": "禁卒居中央,牖其以通明,屋极有窗以达气。", "b": "方苞《狱中杂记》"}, {"t": "明月斜挂。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "江船火独明。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "明暗之掩映。", "b": "蔡元培《图画》"}], "words": [{"w": "明星", "t": "明亮的星。泛指众星"}, {"w": "明珠", "t": "明亮的宝珠。多指珍珠"}, {"w": "明明", "t": "明亮"}, {"w": "明丢丢", "t": "明朗朗,明光光,明灼灼,明亮亮;明亮貌"}, {"w": "明晃晃", "t": "明幌幌,光亮闪烁"}, {"w": "明晦", "t": "晴阴"}, {"w": "明彩", "t": "光彩。"}]}, {"meaning": "明白,清楚。", "cites": [{"t": "明谓左右。", "b": "《战国策·赵策》"}, {"t": "名实已明。", "b": "宋·王安石《答司马谏议书》"}, {"t": "扬之欲其明。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "明切", "t": "明白深切"}, {"w": "明言", "t": "明白的话"}, {"w": "明悉", "t": "详细清楚"}, {"w": "明标着册历", "t": "标,写。册历,指账本。"}]}, {"meaning": "圣明,明察,明智。", "cites": [{"t": "耀明于子。", "b": "唐·柳宗元《柳河东集》"}, {"t": "明智而忠信。", "b": "汉·贾谊《过秦论》"}, {"t": "幸遇明主。", "b": "南明梁·丘迟《与陈伯之书》"}], "words": [{"w": "明后", "t": "圣明的君主"}, {"w": "明主", "t": "英明的君主"}, {"w": "明上", "t": "圣上,尊称君主"}, {"w": "明王", "t": "贤明的君主"}, {"w": "明公", "t": "对有地位者的尊称。"}]}, {"meaning": "明显,明确。", "cites": [{"t": "君法明,伦有常。", "b": "《荀子·成相》"}], "words": [{"w": "明分", "t": "明确的本分"}, {"w": "明刑", "t": "明确的法令"}, {"w": "明效", "t": "明显的效果。"}]}, {"meaning": "明艳, 鲜明。", "words": [{"w": "明服", "t": "鲜艳的服饰"}, {"w": "明姿", "t": "明艳的姿态"}, {"w": "明绚", "t": "明丽绚烂"}]}, {"meaning": "照亮。", "cites": [{"t": "火尚足以明。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "明中", "t": "明照中天"}, {"w": "明烛", "t": "照亮。"}]}, {"meaning": "点燃,点亮。", "cites": [{"t": "并非明火执仗,怎算是强盗?", "b": "《红楼梦》"}], "words": [{"w": "明火执杖", "t": "点着火把,拿着武器,公开活动"}, {"w": "明灯", "t": "点灯。"}]}, {"meaning": "懂得,了解。", "cites": [{"t": "愚者亦明之。", "b": "清·黄宗羲《原君》"}, {"t": "吾未其明也。", "b": "唐·韩愈《师说》"}, {"t": "明于治乱。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "明经义谙雅故", "t": "了解经书的意义,通晓过去的文章典故。谙:熟悉"}, {"w": "明中", "t": "通晓星象历法"}, {"w": "明悟", "t": "明白领悟"}, {"w": "明理", "t": "明白道理。"}]}, {"meaning": "阐明,表明。", "cites": [{"t": "文者以明道。", "b": "唐·柳宗元《柳河东集》"}, {"t": "明死生之大。", "b": "明·张溥《五人墓碑记》"}, {"t": "明道德之广崇。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "明心", "t": "表明心迹"}, {"w": "明志", "t": "表明心志"}, {"w": "明明", "t": "表明。"}]}, {"meaning": "明确。", "cites": [{"t": "明法度,定律令。", "b": "《史记》"}], "words": [{"w": "明分", "t": "明确职分"}, {"w": "明惑", "t": "明确与困惑。"}]}, {"meaning": "受。", "cites": [{"t": "以我齐明,与我牺羊。", "b": "《诗·小雅·甫田》。注:“明者,盛之假借。"}]}, {"meaning": "结盟。", "cites": [{"t": "此邦之人,不可与明。", "b": "《诗·小雅·黄鸟》"}, {"t": "以其背明约而杀义帝也。", "b": "《汉书·黥布传》"}]}, {"meaning": "白昼,白天。", "cites": [{"t": "靡明靡晦。", "b": "《诗·大雅·荡》"}], "words": [{"w": "明夜", "t": "昼夜。"}]}, {"meaning": "人世,阳世。", "cites": [{"t": "人神幽明绝,朋好云雨乖。", "b": "颜延年《和谢监灵运》"}], "words": [{"w": "明幽", "t": "人间和阴间"}, {"w": "明晦", "t": "人世与阴间。"}]}, {"meaning": "眼睛,视力。", "cites": [{"t": "明足以察秋毫之末。", "b": "《孟子·梁惠王上》"}, {"t": "左丘失明,厥有《国语》。", "b": "《史记·太史公自序》"}], "words": [{"w": "不用明焉;明杖", "t": "盲人用以代眼的手杖。"}]}, {"meaning": "明朝 。(1368—1644年)朱元璋所建。先定都南京,永乐年间迁都北京。", "cites": [{"t": "明有奇巧人。", "b": "明·魏学洢《核舟记》"}, {"t": "明朝一典史。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "明人", "t": "明代的人。"}]}, {"meaning": "声名、名誉。", "cites": [{"t": "则天下之明誉兴。", "b": "《大戴礼·主言》"}]}, {"meaning": "名分,地位身分。", "cites": [{"t": "收陵、婴之明分,绝信、布之觊觎。", "b": "《汉书·叙传上》"}]}, {"meaning": "公开。", "cites": [{"t": "明诏大号。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "明正", "t": "公开处置"}, {"w": "明升暗降", "t": "表面上升官,暗中却被削去了权力"}, {"w": "明伙", "t": "公然结伙。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1088wx','易','1','yì','日','8','','[{"pinyin": "yì", "defs": [{"meaning": "(象形。本义:蜥易)。"}, {"meaning": "换,交换。", "cites": [{"t": "寒暑易节。", "b": "《列子·汤问》"}, {"t": "寡人欲以百里之地易安陵。", "b": "《战国策·魏策》"}, {"t": "以大易小。", "b": ""}, {"t": "弗敢易。", "b": ""}, {"t": "易寡人之璧。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "楚人围宋,易子而食。", "b": "《左传·哀公八年》"}, {"t": "移风易俗。", "b": "李斯《谏逐客书》"}, {"t": "贵人过而见之,易之以百金,献诸朝。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "易筋经", "t": "讲武术的书,托名南朝梁代达摩和尚所作"}, {"w": "易箦", "t": "换竹席。比喻行将死亡"}, {"w": "易货", "t": "交换货物"}, {"w": "易地", "t": "互换所处的地位;交换土地"}, {"w": "易身", "t": "换位。"}]}, {"meaning": "改变,更改。", "cites": [{"t": "狱词无易。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "易字", "t": "改换名字"}, {"w": "易箦", "t": "更换竹席"}, {"w": "易辙", "t": "改变行车道路"}, {"w": "易心", "t": "改变心志;改变想法"}, {"w": "易初", "t": "改变初衷"}, {"w": "易革", "t": "改革,变革"}, {"w": "易节", "t": "改变气节操守。"}]}, {"meaning": "替代。", "cites": [{"t": "上古穴居而野处,后世圣人易之以宫室。", "b": "《易·系辞下》"}, {"t": "北都政变,以暴易暴者数矣!", "b": "章炳麟《致段祺瑞书》"}], "words": [{"w": "易代", "t": "更换朝代。"}]}, {"meaning": "蔓延;传播。", "cites": [{"t": "绝其本根,勿能使能殖,畏其易也。", "b": "《东观汉记》"}], "words": [{"w": "易种", "t": "蔓延其种。"}]}, {"meaning": "治,整治。", "cites": [{"t": "易其田畴,薄其税敛,民可使富也。", "b": "《孟子》"}]}, {"meaning": "轻视。含有“不以为意”的意思。", "cites": [{"t": "易慢之心入之矣。", "b": "《礼记·乐记》。注:“易,轻易也。”"}, {"t": "是于圣人也,胥易技兿。", "b": "《庄子·应帝王》。释文引崔注:“易,相轻易也。”"}, {"t": "易者使倾。", "b": "《易·系辞下》。注;“易,慢易也。”"}, {"t": "吏民慢易之。", "b": "《汉书·王嘉传》"}, {"t": "寄伪儿啼,恐栗,为儿状。贼易之,对饮酒,醉。", "b": "唐·柳宗元《童区寄传》"}, {"t": "是以古之易财,非仁也,财多也。", "b": "《韩非子·五蠹》"}]}, {"meaning": "容易。与“难”相对。", "cites": [{"t": "贵货而易土。", "b": "《国语·晋语七》"}, {"t": "不庄不敬而易慢之心入之矣。", "b": "《礼记·乐记》"}, {"t": "物幽兴易惬,事胜趣弥浓。", "b": "唐·岑参《秋夜宿仙游寺南》"}, {"t": "事有难易。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "学有难易。", "b": ""}], "words": [{"w": "易与", "t": "容易对付"}, {"w": "易可", "t": "容易"}, {"w": "易人", "t": "可以轻易对付的人"}, {"w": "易易", "t": "极容易"}, {"w": "易如反掌", "t": ""}]}, {"meaning": "简易,简省。", "cites": [{"t": "栾范易行以诱之。", "b": "《左传》"}]}, {"meaning": "平坦。", "cites": [{"t": "羁坚辔,附易路。", "b": "《文选·枚乘·七发》"}], "words": [{"w": "易野", "t": "平坦的原野"}, {"w": "易道", "t": "平路"}, {"w": "易地", "t": "平地。"}]}, {"meaning": "古代指阴阳变代消长的现象。", "cites": [{"t": "王者乘时,圣人乘易。", "b": "《管子》"}]}, {"meaning": "古代卜筮书,包括《连山》、《归藏》、《周易》,合称三易。"}, {"meaning": "《周易》的简称。", "cites": [{"t": "《易》,书名也。其卦本伏羲所画,有交易、变易之义,故谓之《易》。", "b": "朱熹《周易本义序》"}, {"t": "本之易。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "《易》之八像(《易经》中用八种符号(八卦)代表八种自然界中的现象)", "t": ""}]}, {"meaning": "古代占卜官名。", "cites": [{"t": "昔者圣人建阴阳天土之情,立以为《易》,易抱龟南面,天子卷冕北面。", "b": "《礼记》"}]}, {"meaning": "卜筮之象,古代以示吉凶祸福。", "cites": [{"t": "卜易、谈星、看相…晚生都略知道一二。", "b": "《儒林外史》"}]}, {"meaning": "弹奏弦乐器拽法之一,即中指向外,拨动琴弦。"}, {"meaning": "边界。", "cites": [{"t": "观国之治乱臧否,至于疆易而端已见矣。", "b": "《荀子·富国》"}, {"t": "六五,丧羊于易,无悔。", "b": "《易·大壮》"}, {"t": "殖于疆易。", "b": "《汉书·食货志上》"}, {"t": "吾易久远。", "b": "《汉书·礼乐志》"}]}, {"meaning": "州名 。治所在今河北省易县。"}, {"meaning": "易水的简称 。在现在河北省西部,发源于易县,在定兴县汇入南拒马河。", "cites": [{"t": "秦兵旦暮渡易水。", "b": "《战国策·燕策》"}, {"t": "易,出代州,经保定之易州、安州至高阳,下与曹、徐、滋、沙诸河合。", "b": "明·徐向志《读书札记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1089wx','咙','1','lóng','口','8','','[{"pinyin": "lóng", "defs": [{"meaning": "喉咙,咽部和喉部的统称。", "cites": [{"t": "咙,喉也。", "b": "《说文》"}], "words": [{"w": "咙胡", "t": "咽喉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1090wx','昂','1','áng','日','8','','[{"pinyin": "áng", "defs": [{"meaning": "(形声。从曰,卬声。本义:仰起,抬起)。"}, {"meaning": "同本义。", "cites": [{"t": "袒胸露乳,矫首昂视,神情与苏黄不属。", "b": "明·魏学洢《核舟记》"}, {"t": "柳树得春风,一低复一昂。", "b": "《乐府诗集·柳树得春风》"}], "words": [{"w": "昂首", "t": "仰着头"}, {"w": "昂首挺胸", "t": "仰着头,挺起胸膛。形容无所畏惧或坚决的样子。"}]}, {"meaning": "高,升高。", "cites": [{"t": "横奉之,令左昂右低,如有首尾然。", "b": "《礼记·曲礼》"}]}, {"meaning": "抬高物价。", "cites": [{"t": "昂其直,居为奇货。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1091wx','迪','1','dí','辶','8','','[{"pinyin": "dí", "defs": [{"meaning": "开导。", "cites": [{"t": "迪,道也。", "b": "《说文》。按,谓导也。"}, {"t": "弗求弗迪。", "b": "《诗·大雅·桑柔》"}, {"t": "启迪后人。", "b": "《书·太甲上》"}]}, {"meaning": "遵循。", "cites": [{"t": "为国不迪其法。", "b": "扬雄《法言》"}]}, {"meaning": "行,出走。", "cites": [{"t": "商其沦丧,我无所为人臣仆,诏王子出迪。", "b": "《书·微子》"}]}, {"meaning": "(形声。从辵,由声。本义:道;道理) 同本义。", "cites": [{"t": "易初本迪兮,君子所鄙。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1092wx','典','1','diǎn','八','8','','[{"pinyin": "diǎn", "defs": [{"meaning": "(会意。甲骨文字形,上面是“册”字,下面是大。本义:重要的文献、典籍)。"}, {"meaning": "同本义。", "cites": [{"t": "典,五帝之书也…庄都说,典,大册也。", "b": "《说文》。按,谓从册,从大,古文从古文册。"}, {"t": "典,经也。", "b": "《尔雅·释言》"}, {"t": "不可为典要。", "b": "《易·系辞》"}, {"t": "是能读三坟、五典、八索、九丘。", "b": "《左传·昭公十二年》"}, {"t": "司晋之典籍。", "b": "《左传·昭公十五年》"}, {"t": "不远而复,先典攸高(重贵)。", "b": "丘迟《与陈伯之书》"}, {"t": "自书典所记,未之有也。", "b": "《后汉书·张衡传》"}], "words": [{"w": "药典;字典;释典", "t": "佛经"}, {"w": "法典;佛典;引经据典;典志", "t": "记载政典的文籍"}, {"w": "典坟", "t": "《三坟》和《五典》的省称。都是上古的典籍。"}]}, {"meaning": "法律;法规。", "cites": [{"t": "掌建邦之三典,轻典、中典、重典也。", "b": "《周礼·大司寇》"}], "words": [{"w": "典例", "t": "可依为准则的成例"}, {"w": "典常", "t": "常法,常规"}, {"w": "典诰", "t": "古代文体名。典指常法;诰指诏令。"}]}, {"meaning": "主持;主管。", "cites": [{"t": "命汝典乐。", "b": "《书·尧典》"}, {"t": "或时下愚而千金,顽鲁而典城。", "b": "《论衡·命禄》"}, {"t": "专典机密。", "b": "《三国志·吴仪传》"}], "words": [{"w": "典御", "t": "掌管统治"}, {"w": "典诠", "t": "主持选拔"}, {"w": "典守", "t": "主管、保管;看守"}, {"w": "典历", "t": "掌管;经历。"}]}, {"meaning": "抵押,旧时一方把土地或房屋等押给另一方使用,换取一笔钱,不付利息,议定年限,到期还款,收回原物。", "cites": [{"t": "朝回日日典春衣。", "b": "杜甫《曲江二首》"}, {"t": "民间质典,利息重者至五、七分。", "b": "《金史·百官志》"}], "words": [{"w": "典东西;典地,典田", "t": "典当田地"}, {"w": "典衣", "t": "典押衣服"}, {"w": "典身钱", "t": "卖身钱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1093wx','固','1','gù','囗','8','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从囗(wéi),“围”的古体字,象四周围起来的样子,古声。本义:坚,坚固)。"}, {"meaning": "同本义。", "cites": [{"t": "固,四塞也。", "b": "《说文》"}, {"t": "亦孔之固。", "b": "《诗·小雅·天保》。传:“固,坚也。”"}, {"t": "脩陈固列。", "b": "《左传·成公十六年》"}, {"t": "弱颜固植。", "b": "《楚辞·招魂》"}, {"t": "筋骨欲其固也。", "b": "《吕氏春秋·达郁》"}, {"t": "秦孝公据殽函之固。", "b": "汉·贾谊《过秦论》"}, {"t": "如是则兵劲城固,敌国畏之。", "b": "《荀子·王霸》"}, {"t": "良马固车。", "b": "《韩非子·难势》"}], "words": [{"w": "固项", "t": "牛皮制的护领"}, {"w": "固阴", "t": "隆冬时阴气固结"}, {"w": "固植", "t": "根基巩固。比喻意志坚定不移。"}]}, {"meaning": "特指地势险要和城郭坚固。", "cites": [{"t": "荆州与国邻接,江山险固,沃野万里。", "b": "《资治通鉴》"}, {"t": "今夫颛臾,固而近于费,今不取,后世必为子孙忧。", "b": "《论语·季氏》"}], "words": [{"w": "固塞", "t": "坚固的要塞。"}]}, {"meaning": "久。", "cites": [{"t": "固,久也。", "b": "《小尔雅·广诂》"}, {"t": "臣固闻之。", "b": "《国语·晋语六》"}, {"t": "皆以太子为非固相也。", "b": "《战国策·魏策二》"}]}, {"meaning": "疾病经久难治的", "cites": [{"t": "季冬行春令,则“国多固疾。”", "b": "《礼记·月令》"}, {"t": "太后前闻商有女,欲以备后宫,商言有固疾。", "b": "《汉书·王商传》"}]}, {"meaning": "安定,稳固。", "cites": [{"t": "根不固而求木之长,德不厚而思国之安,臣虽下愚,知其不可。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "国可以固。", "b": "《国语·晋语二》"}], "words": [{"w": "固色", "t": "安定的情绪和神色。"}]}, {"meaning": "固执,专一。", "cites": [{"t": "汝心之固,固不可彻。", "b": "《列子·汤问》"}, {"t": "独夫之心,日益骄固。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "固护", "t": "精神专一,意志坚定。"}]}, {"meaning": "鄙陋。", "cites": [{"t": "鄙人固陋,不知忌讳。", "b": "汉·司马相如《上林赋》"}]}, {"meaning": "坚定。", "cites": [{"t": "上无固植,下有疑心。", "b": "《管子·洁法》"}, {"t": "公夫人甚爱女,每迎女,婿固不遣。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "固植", "t": "固志。坚定的意志"}, {"w": "固色", "t": "坚定的志节"}, {"w": "固宠", "t": "宠幸眷爱,坚定不移。"}]}, {"meaning": "巩固;使坚固;加固。", "cites": [{"t": "固国不以山溪之险。", "b": "《孟子·公孙丑下》"}, {"t": "臣闻求木之长者,必固其根本。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "固堤;固垒", "t": "加固营垒"}, {"w": "固壁清野", "t": "固壁,加固壁垒,使敌不易攻击;清野,转移人口、物质,使敌无所获取"}, {"w": "固位", "t": "巩固保持权位。"}]}, {"meaning": "安守;坚守。", "cites": [{"t": "君子固穷,小人穷斯滥矣。", "b": "《论语·卫灵公》"}, {"t": "竟抱固穷节,饥寒饱所更。", "b": "晋·陶渊明《饮酒》诗十六"}], "words": [{"w": "固穷", "t": "信守道义,安于贫贱穷困。"}]}, {"meaning": "执意;坚决地。", "cites": [{"t": "蔺相如固止之。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "少年固强之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "固守阵地;固却", "t": "坚决拒绝"}, {"w": "固获", "t": "坚持据为己有"}, {"w": "固谢", "t": "执意推辞;谢绝"}, {"w": "固让", "t": "再三辞让。"}]}, {"meaning": "必,一定。", "cites": [{"t": "吾不能变心以从俗兮,固将愁苦而终穷。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "固必", "t": "引申义:一定;必然"}, {"w": "固当如此", "t": ""}]}, {"meaning": "原来;本来。", "cites": [{"t": "生乎吾前,其闻道也固先乎吾,吾从而师之。", "b": "唐·韩愈《师说》"}]}, {"meaning": "当然;仍然。", "cites": [{"t": "天下分裂,而唐室固以微矣。", "b": "宋·苏轼《教战守》"}, {"t": "余固笑而不信也。", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "确实。", "cites": [{"t": "沛公默然,曰:“固不如也。且为之奈何?”", "b": "《史记·项羽本纪》"}]}, {"meaning": "已经。", "cites": [{"t": "以小舟涉鲸波,出无可奈何,而死固付之度外矣。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "固众", "t": "固然很多。"}]}, {"meaning": "(hú)。何,何故。", "cites": [{"t": "夫明白入素,无为复朴,体性抱神,以游世俗之间者,汝将固惊邪?", "b": "《庄子·天地》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1094wx','忠','1','zhōng','心','8','','[{"pinyin": "zhōng", "defs": [{"meaning": "(形声。从心,中声。本义:忠诚无私,尽心竭力)。"}, {"meaning": "同本义。", "cites": [{"t": "不可谓忠。", "b": "《墨子·公输》"}, {"t": "忠之属也。(忠,尽力做好本分的事。)", "b": "《左传·庄公十年》"}, {"t": "为忠善者。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "志虑忠纯。", "b": ""}, {"t": "君子以为忠。", "b": "宋·司马光《训俭示康》"}, {"t": "尽心于人曰忠,不欺于己曰信。", "b": "宋·司马光《四言铭系述》"}], "words": [{"w": "忠贞廉士", "t": "忠诚坚贞廉洁的人"}, {"w": "忠孝带", "t": "清代官员系的一种短而阔的带子,用于保驾或皇帝赐死时自尽"}, {"w": "忠敬", "t": "忠诚恭敬。"}]}, {"meaning": "忠厚。", "cites": [{"t": "交不忠兮怨长。", "b": "《楚辞·九歌·湘君》"}], "words": [{"w": "忠嘉", "t": "忠厚善良"}, {"w": "忠笃", "t": "忠厚笃实。"}]}, {"meaning": "尽忠。特指事上忠诚。", "cites": [{"t": "忠陛下之职分。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "忠而被谤。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "求忠以自为。", "b": ""}, {"t": "忠孝如古人某。", "b": "清·周容《芋老人传》"}], "words": [{"w": "忠功", "t": "尽忠建功"}, {"w": "忠效", "t": "尽忠效力"}, {"w": "忠益", "t": "尽忠报效的益处"}, {"w": "忠孝", "t": "忠于君国,孝于父母"}, {"w": "忠略", "t": "忠于君国的谋略"}, {"w": "忠情", "t": "忠于君国的感情。"}]}, {"meaning": "忠臣。", "cites": [{"t": "莫不欲求忠以自为。", "b": "《屈原列传》"}]}, {"meaning": "中间,适中。", "cites": [{"t": "忠人之和。", "b": "《管子·禁藏》"}, {"t": "则有仇讐之忠。", "b": "《韩非子·五蠹》。高亨云:“忠,借为中。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1095wx','呻','1','shēn','口','8','','[{"pinyin": "shēn", "defs": [{"meaning": "(形声。从口,申声。本义:吟诵)。"}, {"meaning": "同本义。", "cites": [{"t": "学业荒呻毕。", "b": "范成大《藻侄比课》"}], "words": [{"w": "呻毕", "t": "诵读书籍。毕,书简"}, {"w": "呻唤", "t": "因劳苦病痛而呻吟或叫唤。"}]}, {"meaning": "病痛时低声哼。", "cites": [{"t": "疾者思愈,必呻而求医。", "b": "刘禹锡《上杜司徒书》"}], "words": [{"w": "呻呼", "t": "因劳苦疾痛而呻吟呼喊;高吟"}, {"w": "呻恫", "t": "因病痛而发出声音"}, {"w": "呻楚", "t": "呻吟痛楚"}, {"w": "呻鸣", "t": "发出凄楚的声音"}, {"w": "呻嘶", "t": "呻吟叫喊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1096wx','咒','1','zhòu','口','8','','[{"pinyin": "zhòu", "defs": [{"meaning": "(呪俗作咒。会意。从口从兄。“兄”,“祝”的本字。“祝、呪本同一词。祝愿和诅呪是一件事的两面。本义:祝告)。"}, {"meaning": "同本义。", "cites": [{"t": "时夏大旱,…辅乃自暴庭中,慷慨呪曰。", "b": "《后汉书·谅辅传》"}, {"t": "尸呪齐戒。", "b": "《淮南子·说山》"}, {"t": "崇替在人,咒何预焉?", "b": "《文心雕龙》"}], "words": [{"w": "咒延", "t": "祝祷延年益寿"}, {"w": "咒祝", "t": "祝祷祈福"}, {"w": "咒愿", "t": "向天或神佛祷祝,希望顺遂或表示心愿。"}]}, {"meaning": "诅咒,乞求神灵降祸。", "cites": [{"t": "忳咒曰:“有何枉状,可前求理乎?”", "b": "《后汉书·王忳》"}], "words": [{"w": "他没完没了地咒骂;咒念", "t": "诅咒;咒骂"}, {"w": "咒詈", "t": "咒骂"}, {"w": "咒罚", "t": "诅咒惩罚。"}]}, {"meaning": "旧时僧、道、方士等自称可以驱鬼降妖的口诀;某些宗教或巫术中的密语。", "cites": [{"t": "[张角]符水咒说以疗病。", "b": "《后汉书》"}], "words": [{"w": "咒水", "t": "迷信认为饮后可驱灾治病的仙水"}, {"w": "咒诀", "t": "旧时僧、道、方士等行法所念的咒文口诀。"}]}, {"meaning": "梵语陀罗尼,意译为咒,又曰真言,被认为具有魔力的一个词或一组词。", "cites": [{"t": "此非是经,乃是一卷揭斋之咒。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1097wx','咋','1','zǎ zé zhā zhà','口','8','','[{"pinyin": "zǎ", "defs": [{"meaning": "[方言] 怎;怎么"}, {"meaning": "为什么原因、理由或目的"}, {"meaning": "多用于句末,表示疑问、命令、惊讶等语气"}]}, {"pinyin": "zé", "defs": [{"meaning": "啃咬。", "cites": [{"t": "犬彘咋其骨,乌鸢啄其皮。", "b": "苏舜钦《城南感怀呈永叔》"}], "words": [{"w": "咋指", "t": "咬指出血以自誓"}, {"w": "咋噬", "t": "咬嚼吞吃"}, {"w": "咋笔", "t": "操笔。古人构思为文时常以口咬笔杆,故称。"}]}]}, {"pinyin": "zhā", "defs": [{"meaning": ""}]}, {"pinyin": "zhà", "defs": [{"meaning": "突然。", "cites": [{"t": "桓子咋谓林楚…。", "b": "《左传·定公八年》"}]}, {"meaning": "激怒。", "cites": [{"t": "急得他三尸神咋,七窍生烟。", "b": "《西游记》"}]}, {"meaning": "炸开。", "cites": [{"t": "半山里,崖崩岭咋。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1098wx','咐','1','fù','口','8','','[{"pinyin": "fù", "defs": [{"meaning": "——“吩咐”(fēnfù):嘱托;安排。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1099wx','呼','1','hū','口','8','','[{"pinyin": "hū", "defs": [{"meaning": "(形声。从口,乎声。本义:吐气,与“吸”相对)。"}, {"meaning": "同本义 。生物体把体内的气体排出体外——与“吸”相对。", "cites": [{"t": "呼,外息也。", "b": "《说文》(外息,指呼气)"}, {"t": "阴盛则呼吸万物而藏之内也。", "b": "《书·大传》"}, {"t": "候呼引针。", "b": "《素问·离合真邪论》"}], "words": [{"w": "呼哈", "t": "呼吸吞吐"}, {"w": "呼噏", "t": "吐云纳气"}, {"w": "呼息", "t": "呼吸,喘气"}, {"w": "呼翕", "t": "呼气和吸气。"}]}, {"meaning": "大声叫喊。", "cites": [{"t": "呼,唤也。", "b": "《广韵》"}, {"t": "式号式呼。", "b": "《诗·大雅·荡》"}, {"t": "城上不呼。", "b": "《礼记·曲礼上》"}, {"t": "媵侍于户外,呼则闻。", "b": "《仪礼·士昏礼》"}, {"t": "呼河伯妇来。", "b": "《史记·滑稽列传》"}, {"t": "一人大呼。", "b": "《虞初新志·秋声诗自序》"}, {"t": "夫起大呼。", "b": ""}, {"t": "妇亦大呼。", "b": ""}, {"t": "千百人大呼。", "b": ""}], "words": [{"w": "呼噪", "t": "嘈杂地叫喊;喧嚷"}, {"w": "呼天", "t": "向天呼喊以求助"}, {"w": "呼天吁地", "t": "呼喊天地以求救助。"}]}, {"meaning": "召唤。", "cites": [{"t": "呼张良与俱去。", "b": "《史记·项羽本纪》"}, {"t": "前者呼。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "奋呼攻打。", "b": "《广东军务记》"}, {"t": "忠烈大呼。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "呼之即来;一呼百诺", "t": ""}]}, {"meaning": "称呼。", "cites": [{"t": "呼宋将军。", "b": "明·魏禧《大铁椎传》"}, {"t": "不呼名。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "自呼其名;呼唱", "t": "大声唱名"}, {"w": "呼称", "t": "称呼"}, {"w": "呼谓", "t": "称呼,称谓。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1100wx','鸣','1','míng','鸟','8','','[{"pinyin": "míng", "defs": [{"meaning": "(会意。从口,从鸟。本义:鸟叫)。"}, {"meaning": "同本义。", "cites": [{"t": "鸣,鸟声也。", "b": "《说文》"}, {"t": "鸟兽之音曰鸣。", "b": "《管辂别传》"}, {"t": "鸣鹤在阴。", "b": "《易·中孚》"}, {"t": "凤皇鸣矣。", "b": "《诗·大雅·卷阿》"}, {"t": "鸡既鸣矣,朝既盈矣。", "b": "《诗·鸡鸣》"}, {"t": "狗吠深巷中,鸡呜桑树巅。", "b": "陶渊明《归园田居》"}]}, {"meaning": "又如鸣管(鸟类的发声装置);鸣凤(凤鸟鸣叫);鸣雁(雁鸣叫)。"}, {"meaning": "泛指发声。", "cites": [{"t": "震为鸣。", "b": "《易·说卦传》"}, {"t": "萧萧马鸣。", "b": "《诗·小雅·车攻》"}, {"t": "鸣玉者,佩玉也。", "b": "《南子·贾经》"}, {"t": "驴一鸣。", "b": "唐·柳宗元《三戒》"}, {"t": "虽大风不能鸣也。", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "又如鸣石(撞击则会发出声响的石头);鸣玉(古人佩于腰间的玉饰。行走时相互撞击而发声);鸣琴(指琴。又比喻瀑布的声音);鸣鞭(挥鞭发出声响);鸣銮(车上的銮铃鸣响。指天子或贵族出行)。"}, {"meaning": "震惊。", "cites": [{"t": "愿得燕弓射天将,耻令越甲鸣吾君。", "b": "唐·王维《老将行》"}]}, {"meaning": "申告。", "cites": [{"t": "重者鸣官究治。", "b": "明·祁彪佳诗"}]}, {"meaning": "言说;称说。", "cites": [{"t": "天选子之形,子以坚白鸣!", "b": "《庄子》"}]}, {"meaning": "闻名,著称。", "cites": [{"t": "以其技鸣。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "以技鸣者。", "b": ""}], "words": [{"w": "以文鸣江东", "t": ""}]}, {"meaning": "假借为“明”。光明,明亮。", "cites": [{"t": "里社鸣而圣人出。", "b": "李康《运命论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1101wx','咏','1','yǒng','口','8','','[{"pinyin": "yǒng", "defs": [{"meaning": "(形声。从口,永声。又作“詠”。本义:曼声长吟;歌唱)。"}, {"meaning": "同本义。", "cites": [{"t": "詠,歌也。或从口。", "b": "《说文》。段注:“尧典曰:‘歌永言。’乐记曰:‘歌为之言也,长言之也。说之,故言之;言之不足,故长言之。’”"}, {"t": "搏拊琴瑟以咏。", "b": "《虞书》。郑注:“谓歌诗也。”"}, {"t": "五曰夷则,所咏歌九则,平民无二也。", "b": "《国语·周语下》"}, {"t": "人喜则斯陶,陶斯咏。", "b": "《礼记·檀弓》"}, {"t": "咏而归。", "b": "《论语·先进》"}, {"t": "咏殷周之《诗》。", "b": "班固《东都赋》"}], "words": [{"w": "咏士", "t": "诗人"}, {"w": "咏雪", "t": "咏絮。泛指有诗才的女子"}, {"w": "咏哦", "t": "歌咏吟哦"}, {"w": "咏吟", "t": "曼声诵读"}, {"w": "咏言", "t": "吟诗。"}]}, {"meaning": "用诗词等形式来写景抒情。", "cites": [{"t": "若是而不从,动而不悛,则文咏物以行之,求贤良以翼之。", "b": "《国语·楚语上》"}, {"t": "歌以咏志。", "b": "《乐府诗集·曹操·步出夏门行》"}], "words": [{"w": "咏桑寓柳", "t": "喻表面上赞美此事物,实际是为寄托对他事物的情感"}, {"w": "咏志", "t": "以诗歌抒发心志"}, {"w": "咏风嘲月", "t": "诗人写诗,常以风月为题材,故常泛称写诗为咏风嘲月。"}]}, {"meaning": "歌颂。", "cites": [{"t": "含淳咏德之声盈耳。", "b": "汉·王褒《四子讲德论》"}], "words": [{"w": "咏颂", "t": "歌颂"}, {"w": "咏仁", "t": "歌颂仁德"}, {"w": "咏德", "t": "歌颂高尚的品德。"}]}, {"meaning": "指诗歌等韵文作品。", "cites": [{"t": "不有佳咏,何伸雅怀。", "b": "唐·李白《春夜宴从弟桃花园序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1102wx','呢','1','ne ní','口','8','','[{"pinyin": "ne", "defs": [{"meaning": "用在疑问句末,表示疑问"}, {"meaning": "用在反问句末,加强反问"}, {"meaning": "用在陈述句末,表示对事实的确认或强调"}, {"meaning": "用在陈述句末,表示动作或情况正在继续"}, {"meaning": "用在句中表示停顿"}]}, {"pinyin": "ní", "defs": [{"meaning": "一种毛织物", "words": [{"w": "呢子", "t": "呢绒"}]}, {"meaning": "人们的悄声细语。", "cites": [{"t": "呢,呢喃,小声多言也。", "b": "《玉篇》"}], "words": [{"w": "呢呢", "t": "絮絮不休貌。"}]}, {"meaning": "燕子鸣声。", "cites": [{"t": "燕雏羽弱飞难起,母燕呢喃翔复止。", "b": "周士彬《营巢燕》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1103wx','咄','1','duō','口','8','','[{"pinyin": "duō", "defs": [{"meaning": "(形声。从口,出声。本义:呵叱声) 同本义。", "cites": [{"t": "咄,相调也。", "b": "《说文》"}, {"t": "咄,相诃也。", "b": "《字林》"}, {"t": "咄,啐也。", "b": "《苍颉篇》"}, {"t": "咄!口无毛。", "b": "《汉书·东方朔传》。注:“叱咄之声。”"}, {"t": "郭舍人疾言骂之曰:“咄!老女子!何不疾行!”", "b": "《史记》"}, {"t": "咄!你是个破落户。", "b": "《水浒传》"}], "words": [{"w": "咄叱", "t": "呵责"}, {"w": "咄啐", "t": "呵斥"}, {"w": "咄骂", "t": "呵斥辱骂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1104wx','咖','1','gā kā','口','8','','[{"pinyin": "gā", "defs": [{"meaning": "——译音用字。"}]}, {"pinyin": "kā", "defs": [{"meaning": "(形声。从口,加声。咖啡:木名。种子制成粉末可作饮料。也指这种饮料) ——译音用字。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1105wx','岸','1','àn','山','8','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从山,从厂,干声。厂(hǎn,山崖),意思为水边高起之地。本义:河岸)。"}, {"meaning": "同本义。", "cites": [{"t": "淇则有岸。", "b": "《诗·卫风·氓》"}, {"t": "三尺之岸,而虚车不能登也。", "b": "《荀子·宥坐》"}, {"t": "两岸猿声啼不住,轻舟已过万重山。", "b": "唐·李白《早发白帝城》"}]}, {"meaning": "后泛指靠近水边的陆地。", "cites": [{"t": "岸芷汀兰。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "沿岸;起岸", "t": "把货物从船上搬运到岸上。"}]}, {"meaning": "比喻高位。", "cites": [{"t": "诞先登于岸。(诞:发语词,无义。)", "b": "《诗·大雅·皇矣》"}]}, {"meaning": "台阶。", "cites": [{"t": "襄岸夷涂。", "b": "张衡《西京赋》"}]}, {"meaning": "高傲。", "cites": [{"t": "莫笑老翁犹气岸。", "b": "黄庭坚《定风波》"}], "words": [{"w": "傲岸", "t": "高傲,自高自大"}, {"w": "岸异", "t": "独特不凡"}, {"w": "岸谷", "t": "高傲;高深的山谷。"}]}, {"meaning": "高。", "cites": [{"t": "充为人魁岸,容貌其壮。", "b": "《汉书·江充传》"}]}, {"meaning": "头饰高戴,前额外露。", "cites": [{"t": "[谢奕]岸帻笑咏。", "b": "房玄龄《晋书》"}], "words": [{"w": "岸巾", "t": "岸帻。表示无拘无束的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1106wx','岩','1','yán','山','8','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从山,严声。“岩”为会意字。从山,从石。本义:高峻的山崖)。"}, {"meaning": "同本义。", "cites": [{"t": "嵌岩窦穴。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "高岩峭壁。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "植土龛岩。", "b": ""}], "words": [{"w": "岩电", "t": "山崖间的闪电"}, {"w": "岩阿", "t": "山崖旁边凹下的地方"}, {"w": "岩徼", "t": "山崖边远的地方"}, {"w": "岩下", "t": "山崖之下"}, {"w": "岩饰", "t": "岩壁上的雕饰。"}]}, {"meaning": "山峰。", "cites": [{"t": "阻穷西征,岩何越焉。", "b": "《楚辞》"}, {"t": "千岩万转路不定,迷花倚石忽已暝。", "b": "唐·李白《梦游天姥吟留别》"}]}, {"meaning": "高山。", "cites": [{"t": "千岩盛阻积,万壑势回萦。", "b": "鲍照《登庐山诗》"}], "words": [{"w": "岩岫", "t": "山崖峰峦"}, {"w": "岩隈", "t": "深山曲折处。"}]}, {"meaning": "高出水面较大而高耸的石头。", "cites": [{"t": "近岸,卷石底以出…为岩。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "高险。", "cites": [{"t": "保其岩阻。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "岩邑", "t": "险要的城邑"}, {"w": "岩墙", "t": "高而危险的墙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1107wx','帖','1','tiē tiě tiè','巾','8','','[{"pinyin": "tiē", "defs": [{"meaning": "帖服。对约束、控制或权威命令顺从的。", "cites": [{"t": "塞外蛮人方帖服,水边鬼卒又猖狂。", "b": "《三侠五义》"}], "words": [{"w": "伏伏帖帖;俯首帖耳;帖帖", "t": "形容帖伏收敛的样子;温顺,服帖"}, {"w": "帖伏", "t": "折服,顺从不反抗"}, {"w": "帖胁", "t": "拘束不展。"}]}, {"meaning": "安定。", "cites": [{"t": "事不妥帖。", "b": "王逸《楚辞序》"}, {"t": "安置妥帖平不颇。", "b": "韩愈《石鼓歌》"}], "words": [{"w": "帖然", "t": "安定"}, {"w": "帖泰", "t": "安宁;安定。"}]}, {"meaning": "安静。", "cites": [{"t": "帖,静也。", "b": "《广雅》"}], "words": [{"w": "帖息", "t": "平静无声"}, {"w": "帖妥", "t": "静止不动。"}]}, {"meaning": "粘。同“贴”。", "cites": [{"t": "对镜帖花黄。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "帖黄", "t": "贴黄。唐时敕书用纸。凡有更改的地方,仍以黄纸贴之。"}]}, {"meaning": "紧挨着。", "cites": [{"t": "因帖卧床上,剑至果高。", "b": "《世说新语·假谲》"}], "words": [{"w": "帖骑", "t": "贴身于马上"}, {"w": "帖席", "t": "贴卧席上"}, {"w": "帖伏", "t": "贴地而伏。"}]}, {"meaning": "砌垒。", "cites": [{"t": "帖石防溃岸。", "b": "唐·杜甫《早起》"}]}, {"meaning": "添补,增添 。", "words": [{"w": "帖例", "t": "帖附前例。"}]}, {"meaning": "典押。", "cites": [{"t": "臣计天下编户,贫弱者众,有卖舍、帖田供王役者。", "b": "《新唐书·李峤传》"}]}]}, {"pinyin": "tiě", "defs": [{"meaning": "官府文书,公文。", "cites": [{"t": "府帖昨夜下,次选中男行。", "b": "杜甫《新安吏》"}], "words": [{"w": "帖发", "t": "行文发送"}, {"w": "帖写", "t": "清时衙门中的抄写小吏"}, {"w": "帖头", "t": "差役。"}]}, {"meaning": "证券;单据;凭证。", "cites": [{"t": "一季无讼,即书户帖,连庄帐付之,以为地符。", "b": "《宋史》"}]}, {"meaning": "写有简短文字的柬帖 。", "words": [{"w": "名帖;拜帖;盟帖;庚帖;请帖;下帖子;回帖;谢帖", "t": ""}]}, {"meaning": "书面的或印刷的通告或公告 。", "words": [{"w": "招帖", "t": ""}]}, {"meaning": "科举时代明经科的考试名目。", "cites": [{"t": "题赋曰帖,故唐制帖试士曰试贴。", "b": "《通俗文》"}], "words": [{"w": "帖恬", "t": "科举考试的一种程式文章"}, {"w": "帖经", "t": "帖文。唐代科举考试的一种方法"}, {"w": "帖试", "t": "帖括。以帖经试士。"}]}, {"meaning": "箭靶。", "cites": [{"t": "箭头破帖浑无敌。", "b": "唐·贾岛《上邠宁邢司徒》"}]}, {"meaning": "旧时妇女置放缝纫用品的器物。", "cites": [{"t": "启帖理针线,非独学裁缝。", "b": "唐·孟郊《古意》"}]}, {"meaning": "标签。", "cites": [{"t": "以纸帖之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "每韵为一帖。", "b": ""}]}, {"meaning": "用于配合起来的若干味汤药。", "words": [{"w": "一帖药", "t": ""}]}]}, {"pinyin": "tiè", "defs": [{"meaning": "(形声。从巾,占声。本义:古代字写在布帛上叫帖)。"}, {"meaning": "写在帛上的书签。", "cites": [{"t": "帖,帛书署也。", "b": "《说文》。段玉裁注:木部曰:“检,书署也。”木为之谓之检,帛为之则谓之帖,皆谓幖题,今人所谓签也。”"}]}, {"meaning": "名册,名簿。", "cites": [{"t": "府帖昨夜下,次选中男行。", "b": "杜甫《新安吏》"}]}, {"meaning": "铭功纪事的石刻称“碑”,书疏称“帖” 。", "words": [{"w": "晋代王羲之有《姨母帖》、《快雪时晴帖》", "t": ""}]}, {"meaning": "又指石刻、木刻的拓本,书画的摹临范本 。", "words": [{"w": "碑帖;字帖;画帖", "t": ""}]}, {"meaning": "对联;联语。", "cites": [{"t": "金子友来乞楹帖。", "b": "《瓯北诗话》"}], "words": [{"w": "春帖", "t": "春联。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1108wx','罗','1','luó','罒','8','','[{"pinyin": "luó", "defs": [{"meaning": "(会意。甲骨文字形,象网中有隹,表示以网捕鸟的意思。小篆增加了“糸”(mì),表示结网所用的材料。本义:用绳线结成的捕鸟网)。"}, {"meaning": "同本义。", "cites": [{"t": "罗,以丝罟鸟也。", "b": "《说文》"}, {"t": "有兔爰爰,雉离于罗。", "b": "《诗·王风·兔爰》"}, {"t": "以天下为这罗,则雀不失矣。", "b": "《韩非子·难三》"}, {"t": "不见篱间雀,见鹞自投罗。", "b": "曹植《野田黄雀行》"}], "words": [{"w": "罗尉", "t": "捕鸟的网"}, {"w": "罗落", "t": "截捕禽兽的用具"}, {"w": "罗弋", "t": "捕鸟的工具。"}]}, {"meaning": "轻软的丝织品。", "cites": [{"t": "遍身罗绮。", "b": "宋·张俞《蚕妇》"}, {"t": "湿罗幕。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "红罗复斗帐。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "晚成单罗纱。", "b": ""}], "words": [{"w": "罗绮", "t": "罗与绮皆为丝织品,这里指衣着高贵华丽的人"}, {"w": "罗衾", "t": "绸被"}, {"w": "罗衫", "t": "古人夏季时所穿的丝织衣衫;质料柔软轻爽"}, {"w": "罗巾", "t": "丝制手巾"}, {"w": "罗帕", "t": "丝织方巾"}, {"w": "罗衣", "t": "轻软丝织品制成的衣服"}, {"w": "罗纨", "t": "泛指精美的丝织品"}, {"w": "罗带", "t": "丝织的衣带。"}]}, {"meaning": "罗马尼亚的简称。"}, {"meaning": "用网捕捉。", "cites": [{"t": "鸳鸯于飞,毕之罗之。", "b": "《诗·小雅·鸳鸯》"}], "words": [{"w": "罗雀", "t": "设网来捕雀,比喻门庭冷落"}, {"w": "罗毕", "t": "用网捕鸟"}, {"w": "罗雀掘鼠", "t": "粮尽而张网捕雀、挖洞捉鼠以充饥。"}]}, {"meaning": "排列;广布。", "cites": [{"t": "族布而罗生。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "桃李罗堂前。", "b": "晋·陶渊明《归园田居》"}], "words": [{"w": "罗落", "t": "罗列部署 "}, {"w": "罗落境界", "t": "分布驻扎于边境"}, {"w": "罗天结角", "t": "布下天罗地网。"}]}, {"meaning": "收罗;招集,收集。", "cites": [{"t": "万物毕罗,莫足以归。", "b": "《庄子·天下》"}, {"t": "网罗天下放失旧闻。", "b": "司马迁《报任安书》"}], "words": [{"w": "罗斋", "t": "指聚集等待他人雇请的工匠、僧道"}, {"w": "罗弋", "t": "网罗"}, {"w": "罗取", "t": "搜罗求取"}, {"w": "罗捕", "t": "搜索捕捉"}, {"w": "罗搜", "t": "到处搜索。"}]}, {"meaning": "英文gross的省音译。十二打为一罗。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1109wx','帜','1','zhì','巾','8','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从巾,只(戠zhí)声。本义:旗帜的通称)。"}, {"meaning": "同本义。", "cites": [{"t": "帜,旌旗之属。", "b": "《说文新附》"}, {"t": "长丈五尺、广半幅曰帜。", "b": "《墨子》"}, {"t": "私记曰帜。", "b": "《通俗文》"}, {"t": "拔赵帜,立汉赤帜。", "b": "《史记·淮阴侯列传》"}, {"t": "树帜曰。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "又。", "cites": [{"t": "急挥帜。", "b": ""}, {"t": "张帜乘潮。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "帜羽", "t": "羽饰之旌旗"}, {"w": "帜志", "t": "旗帜。"}]}, {"meaning": "标记。", "cites": [{"t": "缝其裾为帜。", "b": "《后汉书》"}], "words": [{"w": "帜志", "t": "典范,标准。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1110wx','帕','1','pà','巾','8','','[{"pinyin": "pà", "defs": [{"meaning": "帷帐。", "cites": [{"t": "绿树垂垂护宝栏,床头翠帕幂双环。", "b": "陈旅《题春宫倦绣图诗》"}]}, {"meaning": "压强单位。帕斯卡的简称 ,即单位面积上所受的压力。"}, {"meaning": "缠绕,包裹。", "cites": [{"t": "以锦缠股,以红帕首。", "b": "韩愈《元和圣德诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1111wx','岭','1','lǐng','山','8','','[{"pinyin": "lǐng", "defs": [{"meaning": "(形声。从山,领声。本义:山道;山坡)。"}, {"meaning": "同本义。", "cites": [{"t": "岭,山道也。", "b": "《说文新附》"}, {"t": "日末涧增波,云生岭逾叠。", "b": "南朝宋·谢灵运《登上戍石鼓山》"}]}, {"meaning": "顶上有路可通行的山,亦泛指山峰。", "cites": [{"t": "予登岭上。", "b": "清·全祖望《梅花岭记》"}, {"t": "岭外望之。", "b": "宋·沈括《溪笔谈》"}], "words": [{"w": "翻山越岭;岭隘", "t": "山岭上险要的隘口"}, {"w": "岭北", "t": "山峰北面;五岭之北。"}]}, {"meaning": "相连的山,山脉。", "cites": [{"t": "横看成岭侧成峰,远近高低各不同。", "b": "苏轼《题西林壁》"}], "words": [{"w": "岭阴", "t": "岭北。山的北面"}, {"w": "岭坫", "t": "山岭屏障、边缘。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1112wx','凯','1','kǎi','几','8','','[{"pinyin": "kǎi", "defs": [{"meaning": "(会意,从豈,从几。“几”象架子。字本作“豈”(qǐ),也作“愷”。从豆,(wèi)省声。本义:军队得胜所奏的乐曲) 同本义。", "cites": [{"t": "豈,还师振旅乐也。", "b": "《说文》。按,经传多以愷为之。亦作凱。"}, {"t": "凯以强教之。即以豈胜豈乐为训。", "b": "《礼记·表记》"}, {"t": "汔可休而凯归。", "b": "左思《吴都赋》"}, {"t": "则令奏恺乐。", "b": "《周礼·大司乐》。注:“献功之乐。”"}, {"t": "恺乐献于社。", "b": "《周礼·大司马》。注:“兵乐曰恺。”"}, {"t": "振旅恺以入于晋。", "b": "《左传·僖公二十八年》。注:“乐也。”"}, {"t": "六军张凯声如雷。", "b": "刘克庄《破阵曲》"}], "words": [{"w": "凯入", "t": "奏着胜利的乐曲归来"}, {"w": "凯乐", "t": "演奏胜利的乐曲 "}, {"w": "凯声", "t": "胜利的乐歌声"}, {"w": "凯期", "t": "胜利的日期"}, {"w": "凯还", "t": "胜利归来。"}]}, {"meaning": "和乐;欢乐。", "cites": [{"t": "故凯乐之情,见于金石。", "b": "嵇康《声无哀乐论》。又如:凯泽(和乐,欢乐);凯乐(和乐,欢乐)"}]}, {"meaning": "安乐;温和。", "cites": [{"t": "凯风自南。", "b": "《诗·邶风·凯风》"}, {"t": "心凯康以乐欢。", "b": "宋玉《神女赋》"}], "words": [{"w": "凯易", "t": "平和平易的样子"}, {"w": "凯风", "t": "和风;南风"}, {"w": "凯弟", "t": "和顺善良的样子。"}]}, {"meaning": "杀,斩。", "cites": [{"t": "叵耐这两个畜生逃走,今日捉将来,我恼了,如何不凯?", "b": "《京本通俗小说·碾玉观音下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1113wx','败','1','bài','贝','8','','[{"pinyin": "bài", "defs": [{"meaning": "(会意。从贝,从攴。攴(pū),甲骨文象以手持杖,敲击的意思,汉字部首之一。在现代汉字中,“攴”大多写成“攵”,只有极少数字保留着“攴”的写法。从“攴”的字多与打、敲、击等手的动作有关。败,甲骨文左边是“鼎”字(小篆简作“贝”),右边是“攴”,表示以手持棍击鼎。本义:毁坏,搞坏)。"}, {"meaning": "同本义。", "cites": [{"t": "败,毁也。", "b": "《说文》"}, {"t": "无俾正败。", "b": "《诗·大雅·民劳》"}, {"t": "若唇之与击,空柔相摩而不致败。", "b": "《淮南子·说林》"}, {"t": "能全天之所生而勿败之。", "b": "《吕氏春秋·尊师》"}, {"t": "法败则国乱。", "b": "《韩非子》"}, {"t": "败家丧身。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "又。", "cites": [{"t": "以侈自败者多矣。", "b": ""}, {"t": "于是纵散约败。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "败辕裂犁", "t": "比喻把事情弄坏"}, {"w": "败名", "t": "败坏名声"}, {"w": "败好", "t": "败坏盟好"}, {"w": "败事", "t": "败坏事情"}, {"w": "败家相", "t": "败坏家业的情状"}, {"w": "败俗", "t": "败坏风俗。"}]}, {"meaning": "损害;损伤。", "cites": [{"t": "死而形体朽,精气散,犹囊橐穿败,粟米弃出也。", "b": "《论衡》"}, {"t": "蠹鱼败书编,萍草粘户半。", "b": "宋·陆游《久雨喜晴十韵》"}], "words": [{"w": "败足", "t": "伤脚"}, {"w": "败物", "t": "破损之物"}, {"w": "败面", "t": "毁伤面容"}, {"w": "败群", "t": "危害集体。"}]}, {"meaning": "失败;战败。", "cites": [{"t": "齐师败矣。", "b": "《左传·成公二年》"}, {"t": "故善战者,立于不败之地。", "b": "《孙子兵法·形篇》"}, {"t": "赵尝五战于秦,二败而三胜。", "b": "宋·苏洵《六国论》"}, {"t": "赵兵果败,括死军覆。", "b": "汉·刘向《列女传》"}, {"t": "成败之机,在于今日!", "b": "《资治通鉴》"}, {"t": "宋义论武信君之军必败,居数日,军果败。", "b": "《史记·项羽本纪》"}], "words": [{"w": "成败", "t": "成功或失败"}, {"w": "败道", "t": "失败的原因"}, {"w": "败走", "t": "战败逃跑"}, {"w": "败却", "t": "败退"}, {"w": "败于垂成", "t": "临近成功时遭到失败"}, {"w": "败阵", "t": "对阵时被打败。"}]}, {"meaning": "打败。使…战败。", "cites": [{"t": "败宋师于黄。", "b": "《左传·隐公元年》"}, {"t": "匈奴入杀辽西太守,败韩将军。", "b": "《史记·李将军列传》"}, {"t": "秦数败赵军。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "文公用咎犯之言,而败楚人于城濮。", "b": "《吕氏春秋·义赏》"}], "words": [{"w": "败衄", "t": "战败。"}]}, {"meaning": "腐烂变质。", "cites": [{"t": "鱼馁而肉败,不食。", "b": "《论语·乡党》"}]}, {"meaning": "破旧。", "cites": [{"t": "则干若败絮。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "又。", "cites": [{"t": "又何往而不金玉其外,败絮其中也哉!", "b": ""}, {"t": "提竹筒、丝笼于败堵丛中。", "b": "《聊斋志异·促织》"}], "words": [{"w": "败絮", "t": "破絮"}, {"w": "败纸;败物", "t": "破损的东西"}, {"w": "败衲", "t": "破旧的僧衣"}, {"w": "败敝", "t": "破旧"}, {"w": "败褐", "t": "破旧的粗布衣服。"}]}, {"meaning": "衰落;破旧;凋谢。", "cites": [{"t": "只有霜中败叶,零落难堪。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "败叶", "t": "落叶;枯叶"}, {"w": "枯枝败叶;衰败", "t": "衰落"}, {"w": "花开败了;败没", "t": "衰落;破败。"}]}, {"meaning": "灾年;荒年。", "cites": [{"t": "丰年补败。", "b": "《谷梁传·庄公二十八年》"}]}, {"meaning": "弊端;过失。", "cites": [{"t": "汉兴,改秦之败。", "b": "《汉书》"}, {"t": "舜之求败也,则是尧有失也。", "b": "《韩非子·难一》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1114wx','账','1','zhàng','贝','8','','[{"pinyin": "zhàng", "defs": [{"meaning": "(古作“帐”。形声。从贝,长声。从贝,表明与财富有关。本义:账目,关于银钱财物出入的记载)。"}, {"meaning": "同本义。", "cites": [{"t": "每年造僧账二本,其一本奏闻,一本申祠部。", "b": "《旧五代史》"}], "words": [{"w": "账略", "t": "简要的账目。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1115wx','贩','1','fàn','贝','8','','[{"pinyin": "fàn", "defs": [{"meaning": "(形声。从贝,反声。本义:贱买而贵卖的人)。"}, {"meaning": "同本义。", "cites": [{"t": "贩,买贱卖贵也。", "b": "《说文》"}, {"t": "贩夫贩妇。", "b": "《周礼·司市》"}, {"t": "虽负贩者,必有尊也。", "b": "《礼记·曲礼》"}], "words": [{"w": "菜贩;摊贩;贩商", "t": "商贩"}, {"w": "贩人", "t": "商贩。"}]}, {"meaning": "古国名。", "cites": [{"t": "贩,古国名。", "b": "《六书故》"}]}, {"meaning": "买货出售。", "cites": [{"t": "资用乏,以贩马自业。", "b": "《后汉书·吴汉传》"}], "words": [{"w": "贩粜", "t": "贩卖粮食"}, {"w": "贩鲜", "t": "贩卖鱼虾之类"}, {"w": "贩易", "t": "做买卖"}, {"w": "贩肆", "t": "贩运货物,开店买卖。"}]}, {"meaning": "比喻叛卖。", "cites": [{"t": "虽吕布贩君,郦寄卖友,万之斯人,未足为酷。", "b": "《宋书·沈攸之传》"}], "words": [{"w": "贩君", "t": "卖主求荣"}, {"w": "贩国", "t": "卖国"}, {"w": "贩交买名", "t": "卖友求荣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1116wx','贬','1','biǎn','贝','8','','[{"pinyin": "biǎn", "defs": [{"meaning": "(形声。从贝,乏声。本义:减少;减损)。"}, {"meaning": "同本义。", "cites": [{"t": "贬,损也。", "b": "《说文》"}, {"t": "贬,减也。", "b": "《广雅》"}, {"t": "何以不氏,贬。", "b": "《公羊传·隐公二年》。注:“犹损也。”"}, {"t": "贬食省用。", "b": "《左传·僖公二十一年》"}], "words": [{"w": "贬颜", "t": "容颜瘦损"}, {"w": "贬乐", "t": "减少声色之娱"}, {"w": "贬价", "t": "降低价格"}, {"w": "贬悴", "t": "瘦损憔悴。"}]}, {"meaning": "降级。", "cites": [{"t": "请自贬三等,以督厥咎。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "特指降职并外放;贬谪。", "cites": [{"t": "遇用事者得罪,例出为刺史;未至,又例贬永州司马。", "b": "韩愈《柳子厚墓志铭》"}, {"t": "其后修贬夷陵,太夫人言笑自若。", "b": "欧阳修《泷冈阡表》"}, {"t": "贬连州刺史。", "b": "《旧唐书·刘禹锡传》"}], "words": [{"w": "贬斥", "t": "官吏被贬黜"}, {"w": "贬书", "t": "黜退的文书"}, {"w": "贬谪", "t": "把有过错的官员降职并派往远离京城的地方。"}]}, {"meaning": "给予低的评价。与“褒”相对。", "cites": [{"t": "《春秋》以一字为褒贬,然皆数句以成言。", "b": "杜预《春秋左氏传序》"}], "words": [{"w": "褒贬", "t": "评论好坏"}, {"w": "贬身", "t": "谦冲有抑,不与人争名利"}, {"w": "贬谤", "t": "贬低,毁谤"}, {"w": "贬弹", "t": "贬低和指斥。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1117wx','购','1','gòu','贝','8','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从贝。从“贝”,表示与财物有关。本义:悬赏征求)。"}, {"meaning": "同本义。", "cites": [{"t": "购,以财有所求也。", "b": "《说文》"}, {"t": "购,偿也。", "b": "《广雅·释言》"}, {"t": "吾闻汉购我头千金,邑万户,吾为若德。", "b": "《史记·项羽本纪》"}, {"t": "穷饿无聊,追购又急,天高地迥,号呼靡及。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "购求", "t": "设置奖金以捉捕犯人"}, {"w": "购问", "t": "悬赏征询"}, {"w": "购募", "t": "悬赏募求"}, {"w": "购悬", "t": "悬赏缉拿。"}]}, {"meaning": "原指用重金收买,后泛指买。", "cites": [{"t": "帝方博购王羲之贴。", "b": "《旧唐书·褚遂良传》"}, {"t": "予购三百盆,皆病者,无一完者。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "购求", "t": "寻求购买"}, {"w": "购粮;购房;购地;赊购;购辑", "t": "购买收集"}, {"w": "购请", "t": "购买。"}]}, {"meaning": "讲和。", "cites": [{"t": "乃警公仲之行,将西购于秦。", "b": "《史记·韩世家》"}], "words": [{"w": "购于秦", "t": "与秦国媾和;向秦讲和。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1118wx','贮','1','zhù','贝','8','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从贝,宁(zhù)声。从贝与财物有关。本义:积存,收藏)。"}, {"meaning": "同本义(侧重于保存,含有积累储存的过程)。", "cites": [{"t": "貯,积也。", "b": "《说文》。按,与宁同。因宁为朝宁义所专,复制此字。"}, {"t": "货物贮藏于市中。", "b": "《周礼·廛人》注"}, {"t": "我有衣冠,而子产贮之。", "b": "《吕氏春秋·乐成》"}, {"t": "而商贾大者积贮倍息,小者坐列贩卖。", "b": "晁错《论贵粟疏》"}, {"t": "厨中有贮酒数百斛。", "b": "《世说新语·任诞》"}, {"t": "木格贮之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "备贮弹药。", "b": "清·梁启超《谭嗣同传》"}, {"t": "馆以贮之。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "又。", "cites": [{"t": "以广贮江宁、杭州、苏州之病梅。", "b": ""}], "words": [{"w": "贮廊", "t": "厅后的房屋"}, {"w": "贮草过冬;贮木场", "t": ""}]}, {"meaning": "等待", "cites": [{"t": "饰新宫以延贮兮,泯不归乎故乡。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1119wx','图','1','tú','囗','8','','[{"pinyin": "tú", "defs": [{"meaning": "(会意。从囗,从啚。囗(wéi),表示范围。啚(bǐ),“鄙”的本字,表示艰难。合起来表示规划一件事,需慎重考虑,相当不容易。本义:谋划,反复考虑)。"}, {"meaning": "同本义。", "cites": [{"t": "图,画计难也。", "b": "《说文》"}, {"t": "是究是图。", "b": "《诗·小雅·常棣》。传:“谋也。”"}, {"t": "君与臣图事。", "b": "《仪礼·聘礼》"}, {"t": "君不图与。", "b": "《公羊传·庄公十三年》"}, {"t": "而天下可图也。", "b": "《战国策·秦策》"}], "words": [{"w": "试图", "t": "打算"}, {"w": "图计", "t": "谋划。"}]}, {"meaning": "图谋;谋取。", "cites": [{"t": "阙秦以利晋,唯君图之。", "b": "《左传·僖公三十年》"}, {"t": "举其一不计其十,究其旧不图其新。", "b": "韩愈《原毁》"}, {"t": "而后乃今将图南。", "b": "《庄子·逍遥游》"}, {"t": "不可图也。", "b": "《三国志·诸葛亮传》"}, {"t": "与图大事。", "b": "《资治通鉴》"}, {"t": "图报复也。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "以图将来。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "图王", "t": "图谋王业"}, {"w": "图功", "t": "图谋建立功业"}, {"w": "图回", "t": "图谋运转"}, {"w": "图全", "t": "图谋保全自身"}, {"w": "图利", "t": "图谋私利"}, {"w": "图私利;图一时之痛快;图名;图害", "t": "谋害"}, {"w": "图饱私囊;图吞公款", "t": ""}]}, {"meaning": "筹划;设法对付。", "cites": [{"t": "无使滋蔓,蔓难图也。", "b": "《左传·隐公元年》"}], "words": [{"w": "图治", "t": "想办法把国家治好。"}]}, {"meaning": "绘画。", "cites": [{"t": "上思股肱之美,乃图画其人于麒麟角。", "b": "《汉书·苏武传》"}], "words": [{"w": "图形", "t": "画出人的相貌"}, {"w": "图工", "t": "善于绘画的人"}, {"w": "图画", "t": "描绘人或物的形像。"}]}, {"meaning": "摹拟。", "cites": [{"t": "命铸铜以图其像。", "b": "《水经注》"}]}, {"meaning": "预料,料想到。多用于否定。", "cites": [{"t": "子在齐闻《韶》,三月不知肉味,曰:“不图为乐之至于斯也。”", "b": "《论语·述而》"}, {"t": "不图子自归。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "所画的图画。", "cites": [{"t": "至见其图,状貌如妇人好女。", "b": "《史记·留侯世家》"}, {"t": "然不得列于名臣之图。", "b": "《汉书·苏武传》"}], "words": [{"w": "看图识字;图载", "t": "以图像表达"}, {"w": "图障", "t": "绘有图画的屏风"}, {"w": "图卷;图法", "t": "图录和法典"}, {"w": "图轴", "t": "画轴;画卷"}, {"w": "略图", "t": "简单的图画"}, {"w": "图经", "t": "附有图画、地图的书籍或地理志"}, {"w": "图说", "t": "兼附图画以助解说的著作。"}]}, {"meaning": "地图。", "cites": [{"t": "有司案图。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "河出图,洛出书,圣人则之。", "b": "《易·系辞上》"}, {"t": "灿若图绣。", "b": "《徐霞客游记·游黄山记》"}, {"t": "普法交战图。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "山水之图。", "b": "蔡元培《图画》"}], "words": [{"w": "图本", "t": "图样"}, {"w": "图志", "t": "附有地图的地方志"}, {"w": "图牒", "t": "图籍表册"}, {"w": "图书", "t": "图籍;书籍"}, {"w": "图式;图例;图板;图忏", "t": "古代方士或儒生编造的关于帝王受命征验一类的书,多为隐语、预言"}, {"w": "图纬", "t": "图忏和纬书。"}]}, {"meaning": "版图。有所有权与管辖权的领土,行使主权的领土。", "cites": [{"t": "州图领同谷,驿道出流沙。", "b": "唐·杜甫《秦州杂诗》"}]}, {"meaning": "意图;意愿。", "cites": [{"t": "帝子留遗恨,曹公屈壮图。", "b": "杜甫《过南岳入洞庭湖》"}]}, {"meaning": "塔,即“浮图”的简称。", "cites": [{"t": "南峰北岭,多结禅栖之士;东岩西谷,又是刹灵之图。", "b": "《水经注》"}]}, {"meaning": "明清时地方区划名。", "cites": [{"t": "改乡为都,改里为图。", "b": "顾炎武《日知录》引《萧山县志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1120wx','钓','1','diào','钅','8','','[{"pinyin": "diào", "defs": [{"meaning": "(形声。从金,勺声。本义:以钩饵取鱼)。"}, {"meaning": "同本义。", "cites": [{"t": "钓,钩鱼也。", "b": "《说文》"}, {"t": "以钓于淇。", "b": "《诗·卫风·竹竿》"}, {"t": "子钓而不纲。", "b": "《论语》"}, {"t": "闲来垂钓碧溪上。", "b": "唐·李白《行路难》"}, {"t": "孤舟簑笠翁,独钓寒江雪。", "b": "唐·柳宗元《江雪》"}], "words": [{"w": "钓蛤蟆", "t": ""}]}, {"meaning": "引申为诱取。", "cites": [{"t": "而晋献以璧马钓之。", "b": "《淮南子·主术》。注:“取也。”"}, {"t": "以三公为布被,诚饰诈欲以钓名。", "b": "《汉书·公孙宏传》"}, {"t": "隐匿谋诈,所以钓战也。", "b": "《银雀山汉墓竹简》"}], "words": [{"w": "钓名", "t": "作伪以求取名誉"}, {"w": "钓奇", "t": "以奇货谋取大利"}, {"w": "钓誉", "t": "求取名声。钓名沽誉的省称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1121wx','制','1','zhì','刂','8','','[{"pinyin": "zhì", "defs": [{"meaning": "制、製本同一词,后来分化,“製”用于具体的制 造,“制”且于抽象的制作。(会意。小篆字形,左边是“未”,右为刀。“未”即有滋味,乐于裁制。本义:裁断;制作)。"}, {"meaning": "同本义。", "cites": [{"t": "制,裁也。", "b": "《说文》"}, {"t": "贤主之用人也,犹巧工之制木也。", "b": "《淮南子·主术》"}, {"t": "制彼裳衣。", "b": "《诗·豳风·东山》"}, {"t": "可使制梃,以挞秦楚之坚甲利兵矣。", "b": "《孟子》"}], "words": [{"w": "制割", "t": "裁剪切割"}, {"w": "制义", "t": "制宜,裁断适宜"}, {"w": "轧制;机制;仿制;自制;试制;研制", "t": "研究制造"}, {"w": "配制;提制", "t": "提炼制造"}, {"w": "精制;中国制", "t": ""}]}, {"meaning": "制定,用文字规定。", "cites": [{"t": "泽上有水,节,君子以制数度,议德行。", "b": "《易·节》"}, {"t": "今也,制民之产。", "b": "《孟子·梁惠王上》"}, {"t": "故王者之制法,昭乎如日月。", "b": "《盐铁论·刑德》"}, {"t": "周之王也,制礼。", "b": "《左传·哀公七年》"}], "words": [{"w": "制宜", "t": "谓区别不同的情况而制定适宜的方式方法"}, {"w": "制则", "t": "制定法度"}, {"w": "制立", "t": "建立制度"}, {"w": "制改", "t": "改制。谓制定典章革除弊端。"}]}, {"meaning": "控制;制服。", "cites": [{"t": "水因地而制流,兵因敌而制胜。", "b": "《孙子·虚实》"}, {"t": "从天而颂之,孰与制天命而用之?", "b": "《荀子·天论》"}, {"t": "威制豪强。", "b": "《汉书·赵广汉传》"}, {"t": "制其兵。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "又。", "cites": [{"t": "制六合。", "b": ""}, {"t": "秦有余力而制其弊。", "b": ""}, {"t": "受制于人。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "自制足之。", "b": ""}], "words": [{"w": "制屈", "t": "制伏;使屈服"}, {"w": "制地", "t": "控制土地"}, {"w": "制驭", "t": "控制驾驭"}, {"w": "制御", "t": "统治,控制。"}]}, {"meaning": "抑制,限制,忍住。", "cites": [{"t": "衣服有制,饮食有节,则出寡矣。", "b": "《商君书·画策》"}], "words": [{"w": "制劫", "t": "牵制"}, {"w": "制使", "t": "制约"}, {"w": "制遏", "t": "抑制"}, {"w": "制约", "t": "限制约束"}, {"w": "制限", "t": "限制"}, {"w": "制缚", "t": "制约束缚"}, {"w": "制防", "t": "限制防范。"}]}, {"meaning": "裁决,决断。", "cites": [{"t": "行无专制。", "b": "《淮南子》"}, {"t": "当是时,晋国政皆决知伯,晋哀公不得有所制。", "b": "《史记·晋世家》"}]}, {"meaning": "抵押。", "cites": [{"t": "昔不谷先委制于越君。", "b": "《国语·吴语》"}, {"t": "委制于吴。", "b": "《国语·越语》"}]}, {"meaning": "规章,制度。", "cites": [{"t": "擅作典制。", "b": "《史记·礼书》"}, {"t": "虽有典制。", "b": "《三国志·孙权传》"}, {"t": "今京不度,非制也。", "b": "《左传·隐公元年》"}]}, {"meaning": "又。", "cites": [{"t": "先王之制,大都不过参国之一。", "b": ""}], "words": [{"w": "公制;制令", "t": "制度法令"}, {"w": "制象", "t": "制度,法制"}, {"w": "制号", "t": "制度号令"}, {"w": "制节", "t": "制度适宜"}, {"w": "全民所有制", "t": ""}]}, {"meaning": "式样。", "cites": [{"t": "俎豆犹古法, 衣裳无新制。", "b": "陶潜《桃花源诗》"}, {"t": "其制稍异。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "制样", "t": "犹样式。"}]}, {"meaning": "规模。", "cites": [{"t": "乃重修岳阳楼,增其旧制。", "b": "范仲淹《岳阳楼记》"}]}, {"meaning": "守父母之丧为制。", "cites": [{"t": "因在制中,不便行礼。", "b": "《红楼梦》"}]}, {"meaning": "帝王的命令。也指法令。", "cites": [{"t": "臣请归节,伏矫制之罪。", "b": "《史记·汲黯列传》"}, {"t": "制曰:“下京兆尹治。”", "b": "《汉书·赵广汉传》"}], "words": [{"w": "制曰", "t": "皇帝的诏书上说"}, {"w": "制敕", "t": "皇帝的诏令。"}]}, {"meaning": "(会意。从衣从制。本义:裁制衣服)。"}, {"meaning": "同本义。", "cites": [{"t": "製,裁也。", "b": "《说文》"}, {"t": "子有美锦,不使人学制焉。", "b": "《左传·襄公三十一年》"}, {"t": "制芰荷以为衣兮。", "b": "《楚辞·离骚》。注:“制,裁也。”"}, {"t": "服短衣楚制。", "b": "《汉书·叔孙通传》"}, {"t": "旌性行以制珮兮。", "b": "《文选·张衡·思玄赋》"}], "words": [{"w": "制裁", "t": "裁制的式样"}, {"w": "制芰", "t": "以芰荷之叶裁制衣裳。指象征芳洁的隐者之服。"}]}, {"meaning": "制造,制作器物。", "cites": [{"t": "牙机巧制。", "b": "《后汉书·张衡传》"}, {"t": "所制蜡人。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "制出将来。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "所制火药。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "制锦", "t": "制造美锦。引申为赞颂县令有政绩"}, {"w": "制冷(人工制造低温(低于环境温度)的技术", "t": ""}, {"w": "制琢", "t": "制造雕刻。"}]}, {"meaning": "作品,文章。", "cites": [{"t": "至于先士茂制,讽高历赏。", "b": "《宋书》"}], "words": [{"w": "佳制;鸿篇巨制", "t": ""}]}, {"meaning": "式样。", "cites": [{"t": "通儒服,汉王憎之,乃变其服,服短衣,楚制。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1122wx','知','1','zhī','矢','8','','[{"pinyin": "zhī", "defs": [{"meaning": "(会意。小篆字形,从口矢。段玉裁:“识敏,故出于口者疾如矢也。”意思是:认识、知道的事物,可以脱口而出。本义:知道)。"}, {"meaning": "同本义。", "cites": [{"t": "知,识也。", "b": "《玉篇》"}, {"t": "知汝远来应有意。", "b": "唐·韩愈《左迁至蓝关示侄孙湘》"}, {"t": "心徹为知。", "b": "《庄子·外物》"}, {"t": "留侯曰:“陛下不知乎?此谋反耳。", "b": "《史记·留侯世家》"}, {"t": "不知何氏女。", "b": "《后汉书·列女传》"}]}, {"meaning": "又。", "cites": [{"t": "日知基所亡。", "b": ""}, {"t": "汝亦知射。", "b": "宋·欧阳修《归田录》"}, {"t": "不知几千里。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "知其不可而为之。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "知不到", "t": "不知道"}, {"w": "知风", "t": "知道情况"}, {"w": "知不道", "t": "不知道"}, {"w": "知兵", "t": "通晓军事"}, {"w": "知古今", "t": "识古通今"}, {"w": "知足不辱", "t": "自知满足就不会招致羞辱"}, {"w": "知命不忧", "t": "识天命者无忧虑。"}]}, {"meaning": "懂得,了解,理会。", "cites": [{"t": "百姓闻之,知与不知,无老壮皆为垂涕。", "b": "《史记·李将军列传》"}, {"t": "食马者不知。", "b": "唐·韩愈《杂说》"}]}, {"meaning": "又。", "cites": [{"t": "真不知马。", "b": ""}, {"t": "人非生而知之者。", "b": "唐·韩愈《师说》"}, {"t": "不知御。", "b": "明·刘基《卖柑者言》"}, {"t": "知幸与不幸。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "知道眉高眼低", "t": "比喻懂事"}, {"w": "知窍", "t": "能见机行事;知趣"}, {"w": "知局", "t": "知趣"}, {"w": "知臣莫若君;知子莫若父;知心着意", "t": "彼此了解,心意投合"}, {"w": "知我", "t": "深切了解我"}, {"w": "知好歹", "t": "明白道理,懂事"}, {"w": "知情识趣", "t": "懂情意,善体贴"}, {"w": "知高识底", "t": "说话、做事懂得掌握分寸。"}]}, {"meaning": "主持;管理。", "cites": [{"t": "有能助寡人谋而退吴者,吾与之共知越国之政。", "b": "《国语·越语上》"}, {"t": "夜开金殿看星河,宫女知更月明里。", "b": "王建《温泉宫行》"}], "words": [{"w": "知更", "t": "主管更漏"}, {"w": "知内外事", "t": "主持内政和外交事务"}, {"w": "知客寮", "t": "寺院中的接待客"}, {"w": "知印", "t": "主持用印"}, {"w": "知贡举", "t": "唐宋时特派主持进士考试的大臣。"}]}, {"meaning": "识别;区别。", "cites": [{"t": "孪子之相似者,唯其母能知之。", "b": "《淮南子》"}], "words": [{"w": "知时达变", "t": "识时务,善变通"}, {"w": "知人则哲", "t": "能识别人的贤愚善恶就聪明。"}]}, {"meaning": "赏识。", "cites": [{"t": "含愁更奏绿绮琴,调高弦绝无知音。", "b": "卢仝《有所思》"}], "words": [{"w": "知爱", "t": "赏识喜爱"}, {"w": "知器", "t": "赏识,器重"}, {"w": "知遇", "t": "赏识;优待"}, {"w": "知怜", "t": "赏识爱护"}, {"w": "知重", "t": "赏识;看重。"}]}, {"meaning": "要好。", "cites": [{"t": "悲莫悲兮生别离,乐莫乐兮新相知。", "b": "《楚辞·九歌》"}, {"t": "张胜相知。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "知慰", "t": "关心;抚慰"}, {"w": "知契", "t": "知心投合。"}]}, {"meaning": "感到,感觉,察觉。", "cites": [{"t": "[君主]又损其生以资天下之人,而终不自知。", "b": "《吕氏春秋·情欲》"}, {"t": "识者固知。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "参与。", "cites": [{"t": "高、鲍将不纳君,而立公子角,国子知之。", "b": "《左传·成公十七年》"}]}, {"meaning": "知识。", "cites": [{"t": "子曰:“吾有知乎哉?无知也。”", "b": "《论语·子罕》"}, {"t": "吾生也有涯,而知也无涯。", "b": "《庄子·养生主》"}], "words": [{"w": "求知欲;真知灼见;无知;通过努力学习,可以由无知转化为有知", "t": ""}]}, {"meaning": "知觉。", "cites": [{"t": "草木有生而无知。", "b": "《荀子·王制》"}, {"t": "死而有知,有几何离;其无知,悲不几时,而不悲者无穷期矣。", "b": "唐·韩愈《祭十二郎文》"}]}, {"meaning": "知己。", "cites": [{"t": "绝宾客之知。", "b": "汉·司马迁《报任安书》"}, {"t": "天涯占梦数,疑误有新知。", "b": "李商隐《凉思》"}], "words": [{"w": "知心腹", "t": "亲信。"}]}, {"meaning": "“智”的古字。智慧;才智。", "cites": [{"t": "故夫知效一官。", "b": "《庄子·逍遥游》"}, {"t": "择不处仁,焉得知?", "b": "《论语·里仁》"}, {"t": "汝多知乎?", "b": "《列子·汤问》"}, {"t": "则知明而行无过矣。(知,通“智”)。", "b": "《荀子·劝学》"}, {"t": "大知而察。", "b": "清·刘开《问说》"}], "words": [{"w": "知力", "t": "才智能力"}, {"w": "知士", "t": "才智之士。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1123wx','迭','1','dié','辶','8','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从辵,失声。本义:交替,轮流)。"}, {"meaning": "同本义。", "cites": [{"t": "迭,更递也。", "b": "《说文》"}, {"t": "迭,更也。", "b": "《尔雅》"}, {"t": "迭用柔刚。", "b": "《易·说卦》"}, {"t": "胡迭而微。", "b": "《诗·邶风·日月》"}, {"t": "迭相为经。", "b": "《礼记·乐记》"}, {"t": "弟兄迭为君。", "b": "《公羊传·襄公二十九》"}, {"t": "四时迭起。", "b": "《庄子·天运》"}], "words": [{"w": "迭为宾主;迭变", "t": "交替变化"}, {"w": "迭宿", "t": "轮流值宿"}, {"w": "迭进", "t": "轮番进言。"}]}, {"meaning": "停止。", "cites": [{"t": "两个在阵前叫苦不迭。", "b": "《水浒传》"}], "words": [{"w": "忙不迭;迭不的", "t": "迭不得。来不及。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1124wx','氛','1','fēn','气','8','','[{"pinyin": "fēn", "defs": [{"meaning": "(形声。从气,分声。本义:凶气,古时迷信说法指预示吉凶的云气,多指凶气 )。"}, {"meaning": "同本义。", "cites": [{"t": "楚氛甚恶。", "b": "《左传·襄公二十七年》"}, {"t": "台不过望氛祥。", "b": "《国语·楚语》。注:“凶气为氛。”"}, {"t": "氛邪岁增。", "b": "《汉书·元帝纪》。注:“恶气也。”"}, {"t": "环顾国内,贼氛方炽。", "b": "孙文《序》"}], "words": [{"w": "氛慝,氛邪", "t": "邪恶之气"}, {"w": "氛厉", "t": "祸害之气"}, {"w": "氛霓", "t": "凶气,妖气"}, {"w": "氛杂", "t": "杂乱之气"}, {"w": "氛秽", "t": "邪恶肮脏之气"}, {"w": "氛妖", "t": "妖气。"}]}, {"meaning": "泛指雾气;云气。", "cites": [{"t": "氛雾冥冥。", "b": "《礼记·月令》"}, {"t": "寒氛结为霜雪。", "b": "《素问·六玄正纪大论》"}, {"t": "雨雪雰雰。", "b": "《诗·小雅·信南山》"}], "words": [{"w": "氛昏", "t": "云雾,烟霭"}, {"w": "氛旄", "t": "以氛气为旄"}, {"w": "氛气", "t": "雾气。"}]}, {"meaning": "尘埃。", "cites": [{"t": "消氛埃于中宸。", "b": "张衡《西京赋》。注:“尘秽也。”"}], "words": [{"w": "氛浊", "t": "尘浊之气"}, {"w": "氛垢", "t": "尘雾。"}]}, {"meaning": "乱,杂。", "cites": [{"t": "上天同云,雨雪氛氛。", "b": "《诗·小雅·信南山》"}, {"t": "霰雪氛糅其增加兮,乃知遭命之将至。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1125wx','垂','1','chuí','土','8','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从土,(chuí)声。本义:边疆)。"}, {"meaning": "边疆;边境。", "cites": [{"t": "垂,远边也。", "b": "《说文》。按,下垂的垂,说文作垂。"}, {"t": "垂,疆也。", "b": "《广韵》"}, {"t": "寡人无良边垂之臣。", "b": "《公羊传·宣公十二年》"}, {"t": "今大国之地,半天下有二垂。", "b": "《战国策·秦策四》"}, {"t": "少小去乡邑,扬声沙漠垂。", "b": "曹植《白马篇》"}, {"t": "边境之臣处,则疆垂不丧。", "b": "《荀子·臣道》"}]}, {"meaning": "堂檐下靠阶的地方。", "words": [{"w": "垂堂", "t": "堂边近阶处屋檐下。"}]}, {"meaning": "垂挂。", "cites": [{"t": "垂带悸兮。", "b": "《诗·卫风·芄兰》"}, {"t": "垂发。", "b": "《后汉书·邓禹传》"}, {"t": "红罗复斗帐,四角垂香囊。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "每至手足无可着处,澄源必先登垂接。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "垂垂", "t": "形容下垂的样子"}, {"w": "垂丝", "t": "垂下发丝"}, {"w": "垂梢", "t": "马尾长而下垂"}, {"w": "垂涕", "t": "哭泣"}, {"w": "垂髫", "t": "童子未行冠礼前,头发下垂,用以指童年或儿童。"}]}, {"meaning": "留传。", "cites": [{"t": "舍则传诸其徒,垂诸文而为后世法。", "b": "韩愈《答李诩书》"}], "words": [{"w": "垂名竹帛", "t": "名载史册;流芳后世"}, {"w": "垂教", "t": "留传教训于后世"}, {"w": "永垂不朽", "t": ""}]}, {"meaning": "注意;留意 。 如:垂青(看重;见爱);垂顾(看重;宠爱)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1126wx','牧','1','mù','牜','8','','[{"pinyin": "mù", "defs": [{"meaning": "(会意。甲骨文字形。从牛,从攴(pū),表示手拿棍棒牧牛(羊)。本义:放牧牲畜)。"}, {"meaning": "同本义。", "cites": [{"t": "掌牧六牲。", "b": "《周礼·牧人》"}, {"t": "谁扞牧圉。", "b": "《左传·僖公二十八年》。注:“牛曰牧。”"}, {"t": "周宣王之牧正。", "b": "《列子·黄帝》。注:“养禽兽之长也。”"}, {"t": "牧人乃梦。", "b": "《诗·小雅·无羊》"}, {"t": "郊外谓之牧。", "b": "《尔雅》"}, {"t": "使牧羝。", "b": "《汉书·李广苏建传》"}, {"t": "权汉节牧羊。", "b": ""}, {"t": "郴州荛牧儿。", "b": "唐·柳宗元《童区寄传》"}, {"t": "行牧且荛。", "b": ""}], "words": [{"w": "牧所", "t": "牧养牲畜的处所"}, {"w": "牧苑", "t": "牧场。牧地。牧放牲畜的地方"}, {"w": "牧子", "t": "放牧的人;牧童"}, {"w": "牧夫", "t": "放牧牲畜的人。"}]}, {"meaning": "统治;主管。", "cites": [{"t": "请牧基贤者思。", "b": "《荀子·成相》。注:“治也。”"}], "words": [{"w": "牧司", "t": "牧夫,牧人。管民政的地方官"}, {"w": "牧字", "t": "治理抚育。"}]}, {"meaning": "牧人;牧民。", "cites": [{"t": "牧,养牛人也。", "b": "《说文》"}, {"t": "尔牧来思。", "b": "《诗·小雅·无羊》"}, {"t": "马有圉,牛有牧。", "b": "《左传·昭公七年》"}], "words": [{"w": "牧豕奴", "t": "放牧牲畜的仆人"}, {"w": "牧笛", "t": "牧民或牧童所吹的笛子"}, {"w": "牧啸", "t": "牧人的啸歌"}, {"w": "牧奴", "t": "对放牧者的蔑称。"}]}, {"meaning": "掌畜牧的官员或官署。", "cites": [{"t": "而建其牧。", "b": "《周礼·大宰》。注:“侯伯有功德者,加命作州长,谓之牧。”"}, {"t": "八命作牧。", "b": "《周礼·大宗伯》"}, {"t": "吾记天圣中先公为群牧判官。", "b": "司马光《训俭示康》"}], "words": [{"w": "牧马所", "t": "宋有牧马监,掌牧马之事;小说家所捏造的一种职司"}, {"w": "牧正", "t": "牧官之长,主管畜牧。"}]}, {"meaning": "古代州的长官。", "cites": [{"t": "九州之长入天子之国,曰牧。", "b": "《礼记·曲礼》"}], "words": [{"w": "牧令", "t": "旧时称地方长官"}, {"w": "牧守", "t": "牧伯。州郡的长官"}, {"w": "牧宰", "t": "泛指州县长官。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1127wx','物','1','wù','牜','8','','[{"pinyin": "wù", "defs": [{"meaning": "(形声,从牛,勿声。“勿”是一种杂色旗,表示杂色。本义:万物)。"}, {"meaning": "同本义。", "cites": [{"t": "物,万物也。牛为大物,天地之数起于牵牛,故从牛。", "b": "《说文》"}, {"t": "物以群分。", "b": "《礼记·乐记》"}, {"t": "四时之散精为物。", "b": "《淮南子·天文》"}, {"t": "物也者,大共名也。", "b": "《荀子·正名》"}, {"t": "九曰物贡。", "b": "《周礼·太宰》"}], "words": [{"w": "物品", "t": "各种财货、物件"}, {"w": "物母", "t": "万物的本源"}, {"w": "物曲", "t": "物的性能"}, {"w": "物如", "t": "事物的本源"}, {"w": "物序", "t": "事物的规律"}, {"w": "物祖", "t": "万物之祖"}, {"w": "物际", "t": "事物的界限"}, {"w": "物恺", "t": "愿各物安乐"}, {"w": "物灵", "t": "万物之灵"}, {"w": "物用", "t": "百物器用。"}]}, {"meaning": "物件,东西。", "cites": [{"t": "庞然大物。", "b": "唐·柳宗元《三戒》"}, {"t": "润物细无声。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "一物无所持。", "b": "明·魏禧《大铁椎传》"}, {"t": "夺其物。", "b": ""}], "words": [{"w": "物外", "t": "有形事物之外"}, {"w": "物变", "t": "事物变化"}, {"w": "物隐", "t": "事物的隐秘"}, {"w": "物端", "t": "东西,物品"}, {"w": "物诱", "t": "为外物所引诱"}, {"w": "物势", "t": "事物的趋势、态势"}, {"w": "物惑", "t": "外物的诱惑"}, {"w": "物则", "t": "事物的法则"}, {"w": "物像", "t": "样子。"}]}, {"meaning": "事;事情。", "cites": [{"t": "有物有则。", "b": "《诗·大雅·烝民》。传:“事也。”"}], "words": [{"w": "物务", "t": "事务"}, {"w": "物事", "t": "事情"}, {"w": "物格", "t": "事理得到穷究。"}]}, {"meaning": "社会,外界环境。", "cites": [{"t": "君子生非异也。善假于物也。", "b": "《荀子·劝学》"}], "words": [{"w": "物外人", "t": "尘世以外的人"}, {"w": "物道", "t": "世道"}, {"w": "物运", "t": "世运"}, {"w": "物外交", "t": "超世脱俗的交谊。"}]}, {"meaning": "杂色牛。", "cites": [{"t": "三十维物,尔牲则具。", "b": "《诗·小雅·无羊》。毛传:“异毛色者三十也。”"}]}, {"meaning": "杂色的旗。", "cites": [{"t": "[九旗] 杂帛为物,以杂色缀其边为燕尾,将帅所建,象物杂色也。", "b": "《释名》"}, {"t": "司常掌九旗之物品,各有属以待国事:日月为常,旃龙为旂,通帛为旃,杂帛为物…。", "b": "《周礼》"}]}, {"meaning": "牲畜的种类、 品级。", "cites": [{"t": "辨六马之属,种马一物,戎马一物……驽马一物。", "b": "《周礼》"}], "words": [{"w": "物类", "t": "同类,物的同类;种类"}, {"w": "物汇", "t": "物类。"}]}, {"meaning": "颜色。", "cites": [{"t": "比物四骊。", "b": "《诗·小雅·六月》"}], "words": [{"w": "物采", "t": "色彩。"}]}, {"meaning": "哲学用语。物质,与“心”相对。", "cites": [{"t": "自其不变者而观之,则物与我皆无尽也。", "b": "苏轼《赤壁赋》"}], "words": [{"w": "唯物论;物气", "t": "物质性的妖气"}, {"w": "物观", "t": "客观。"}]}, {"meaning": "物产。", "cites": [{"t": "此物故非西产。", "b": "《聊斋志异·促织》"}], "words": [{"w": "物图", "t": "物产分布图"}, {"w": "物殷俗阜", "t": "物产丰盛,风俗淳厚"}, {"w": "物阜民康", "t": "物产丰富,人民安康"}, {"w": "物阜", "t": "物产丰盛。"}]}, {"meaning": "他人;众人。", "cites": [{"t": "损己以利物。", "b": "唐·魏征《十渐不克终疏》"}], "words": [{"w": "物听", "t": "众人的言论"}, {"w": "物意", "t": "众人的心意"}, {"w": "物师", "t": "众人的师表"}, {"w": "物鬼", "t": "人鬼"}, {"w": "物迹", "t": "人迹"}, {"w": "物轨", "t": "众人的榜样"}, {"w": "物宗", "t": "众人所景仰的人"}, {"w": "物和", "t": "人和"}, {"w": "物物", "t": "人对于万物的役使、支配"}, {"w": "物忌", "t": "众人忌惮或忌妒"}, {"w": "物心", "t": "人心"}, {"w": "物望", "t": "人望;众望。"}]}, {"meaning": "神灵。", "cites": [{"t": "辑江淮物,会大海气,以合泰山。", "b": "《汉书》"}]}, {"meaning": "标记,记号。", "cites": [{"t": "叔孙氏之甲有物,吾未敢以出。", "b": "《左传·昭公三十二年》"}]}, {"meaning": "选择。", "cites": [{"t": "以物地事授地职,而待其政令。", "b": "《周礼》"}]}, {"meaning": "观察。", "cites": [{"t": "物土方,议远迩。", "b": "《左传·昭公三十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1128wx','乖','1','guāi','丿','8','','[{"pinyin": "guāi", "defs": [{"meaning": "(会意。小篆字形,象羊角形,从“北”。从“北”,取其分背的意思。本义:背离,违背,不和谐)。"}, {"meaning": "同本义。", "cites": [{"t": "乖,戾也。", "b": "《说文》"}, {"t": "刚柔得适谓之和,反和为乖。", "b": "《贾子道术》"}, {"t": "吾独乖刺而无当兮。", "b": "《楚辞·怨世》"}, {"t": "乖,背也。", "b": "《广雅》"}, {"t": "楚执政众而乖。", "b": "《左传·昭公三十年》"}, {"t": "上下相反,好恶乖迕。", "b": "晁错《论贵粟疏》"}, {"t": "唯恐道途显晦,不相通达,致负诚托,又乖恳愿。", "b": "唐·李朝威《柳毅传》"}, {"t": "今墨家非儒,儒家非墨,各有所持,故乖不合。", "b": "汉·王充《论衡·薄葬》"}], "words": [{"w": "乖礼", "t": "违背成礼、定制"}, {"w": "乖角", "t": "违背抵触"}, {"w": "乖贰", "t": "背离;违异"}, {"w": "乖背", "t": "违背"}, {"w": "乖则", "t": "违反法则。"}]}, {"meaning": "分离;离别。", "cites": [{"t": "昔我同袍,今永乖别。", "b": "魏·曹植《朔风》"}], "words": [{"w": "乖分", "t": "分离;分裂"}, {"w": "乖别", "t": "分离;离别"}, {"w": "乖拆", "t": "分离"}, {"w": "乖析", "t": "分离,支离破碎。"}]}, {"meaning": "不同;差异。", "cites": [{"t": "人度量之乖舛,何相越之辽迥。", "b": "晋·潘岳《西征赋》"}], "words": [{"w": "乖讹", "t": "差错;乖僻"}, {"w": "乖越", "t": "差失,错误;不相当"}, {"w": "乖舛", "t": "乖殊。乖异;不同。"}]}, {"meaning": "反常;谬误。", "cites": [{"t": "朕醉中处事有乖。", "b": "《辽史·穆宗纪》"}, {"t": "衣服滓弊,行止乖角。", "b": "《太平广记·韩愈外甥》引《仙传拾遗》"}], "words": [{"w": "乖性儿", "t": "乖僻性格"}, {"w": "乖和", "t": "不正常;不和谐"}, {"w": "乖节", "t": "失常;过度"}, {"w": "乘诞", "t": "乖戾荒诞"}, {"w": "乖眼", "t": "怪眼。"}]}, {"meaning": "邪恶;奸滑。", "cites": [{"t": "烦君自入华阳洞,直割乖龙左耳来。", "b": "唐·韩愈《答张道士寄树鸡》诗"}], "words": [{"w": "乖滑", "t": "狡猾;调皮"}, {"w": "乖子", "t": "狡猾的人"}, {"w": "乖劣", "t": "暴戾;恶劣"}, {"w": "乖气", "t": "邪恶之气"}, {"w": "乖沴", "t": "邪气,不和之气"}, {"w": "乖诡", "t": "奸滑怪诞"}, {"w": "乖眼", "t": "怪眼;凶眼。"}]}, {"meaning": "灵巧,聪明,伶俐。", "cites": [{"t": "行者的眼乖。", "b": "《西游记》十五回"}, {"t": "上了一回当,他也学乖了", "b": ""}, {"t": "黄文炳是个乖觉的人,早瞧了八分,,便奔船梢后走,望江里踊身便跳。", "b": "《水浒》第四十一回"}], "words": [{"w": "乖觉", "t": "机敏"}, {"w": "乖人", "t": "机灵人"}, {"w": "乖乖伶(聪明伶俐)乖唇蜜舌(形容口齿伶俐)", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1129wx','刮','1','guā','刂','8','','[{"pinyin": "guā", "defs": [{"meaning": "(形声。小篆作字形,从刀。本义:削,用刃平削物体,或把物体表面的某些东西去掉)。"}, {"meaning": "同本义。", "cites": [{"t": "刮,掊杷也。", "b": "《说文》"}, {"t": "刮,减也。", "b": "《广雅》"}, {"t": "刮楹达乡。", "b": "《礼记·明堂位》。注:“刮,刮摩也。”"}, {"t": "刮摩之工。", "b": "《考工记》"}, {"t": "采椽不刮,茅茨不剪。", "b": "《史记·太史公自序》"}, {"t": "医曰:“矢镞有毒,毒入骨,当破臂作创,刮骨去毒,然后此患乃除耳。", "b": "《三国志·关羽传》"}], "words": [{"w": "刮毒", "t": "刻毒,狠毒"}, {"w": "刮子", "t": "耳光"}, {"w": "刮刷", "t": "刮除干净"}, {"w": "刮垢磨光;刮楹", "t": "刮削摩擦过的柱子"}, {"w": "刮锅子;刮磨", "t": "磨练"}, {"w": "刮摩", "t": "琢磨器物,使之光平"}, {"w": "刮火柴;以瓦片刮疥", "t": ""}]}, {"meaning": "扫拂;刷抹。", "cites": [{"t": "爬罗剔抉,刮垢磨光。", "b": "唐·韩愈《进学解》"}], "words": [{"w": "刮土儿", "t": "刮扫土地。扫除无余"}, {"w": "刮除", "t": "扫除"}, {"w": "刮揸(刮扫清除)刮目(拭目;用新眼光看)", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1130wx','秆','1','gǎn','禾','8','','[{"pinyin": "gǎn", "defs": [{"meaning": "(形声。从禾,旱声。本义:禾茎) 同本义。后泛指草木的茎。", "cites": [{"t": "稈,禾茎也。", "b": "《说文》"}, {"t": "稻穰谓之稈。", "b": "《广雅》"}], "words": [{"w": "秆草", "t": "作饲料的禾茎杂草"}, {"w": "麦秆;麻秆儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1131wx','和','1','hé hè hú huó huò huo','口','8','','[{"pinyin": "hé", "defs": [{"meaning": "和谐;协调。", "cites": [{"t": "和,相应也。", "b": "《说文》"}, {"t": "和,谐也。", "b": "《广雅》"}, {"t": "音声相和。", "b": "《老子》"}, {"t": "乐从和。", "b": "《国语·周语下》"}, {"t": "倡予和女。", "b": "《诗·郑风·萚兮》"}, {"t": "鸣鹤在阴,其子和之。", "b": "《易·中孚卦》"}, {"t": "与讴谣乎相龢。", "b": "《文选·王褒·洞箫赋》"}, {"t": "和五声。", "b": "《吕氏春秋·慎行论》"}, {"t": "圣人为能和。", "b": ""}, {"t": "和乐之本也。", "b": ""}, {"t": "夔能和之。", "b": ""}], "words": [{"w": "和合日", "t": "和谐、合好的吉日"}, {"w": "和合会", "t": "合好;和谐"}, {"w": "和令", "t": "和谐畅适"}, {"w": "和比", "t": "和谐。"}]}, {"meaning": "和睦;融洽。", "cites": [{"t": "颜色愈和。", "b": "《史记·魏公子列传》"}, {"t": "言和而色夷。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "和友", "t": "和睦友爱"}, {"w": "和比", "t": "和睦;和谐"}, {"w": "和居", "t": "和睦相处"}, {"w": "和勉", "t": "和睦互勉。"}]}, {"meaning": "暖和;和煦;晴和。", "cites": [{"t": "海上风和日暖。", "b": "刘斧《青锁高议》"}, {"t": "春和景明。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "天稍和。", "b": "明·袁宏道《满井游记》"}, {"t": "久而乃和。", "b": "明·宋濂《送东阳马生序》"}, {"t": "和无寡。", "b": "《论语·季氏》"}], "words": [{"w": "和清", "t": "温和清朗"}, {"w": "和媚", "t": "温和美好。"}]}, {"meaning": "指身体健康舒适。", "cites": [{"t": "和于身也。", "b": "《战国策·赵策》"}], "words": [{"w": "和宜", "t": "合适,舒服"}, {"w": "和胜", "t": "病愈"}, {"w": "和舒", "t": "和畅舒适。"}]}, {"meaning": "搀和,混和。", "cites": [{"t": "松脂蜡和纸灰。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "泪珠和笔墨齐下。", "b": "清·林觉民《与妻书》"}]}, {"meaning": "和解;息争而归和平。", "cites": [{"t": "与楚以和。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "和番", "t": "以婚姻安抚外族,和睦异族"}, {"w": "和盟", "t": "和好结盟"}, {"w": "和邻", "t": "与邻国媾和交好"}, {"w": "和宁", "t": "和解,平息"}, {"w": "和释", "t": "和解;消除。"}]}]}, {"pinyin": "hè", "defs": [{"meaning": "应和;跟着唱。", "cites": [{"t": "荆轲和而歌。", "b": "《战国策·燕策》"}, {"t": "拊石而和之。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "当哭相和也。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "唱和;曲高和寡;和歌", "t": "应和他人之歌声而唱歌。"}]}]}, {"pinyin": "hú", "defs": [{"meaning": "打麻将或斗纸牌时某一家的牌合乎规定的要求,取得胜利。"}]}, {"pinyin": "huó", "defs": [{"meaning": "", "words": [{"w": "和揉", "t": "在粉状物中加液调匀揉合"}, {"w": "和解", "t": "犹溶解"}, {"w": "和丸", "t": "比喻母亲教子勤学"}, {"w": "和熊", "t": "为母亲教子勤学之典。"}]}]}, {"pinyin": "huò", "defs": [{"meaning": "不同的人混杂到一起。", "cites": [{"t": "与他们甚么相干?怎么也和在里头?", "b": "《文明小史》"}]}, {"meaning": "用于时间,相当于“会儿”。", "cites": [{"t": "韦义方去怀里摸索一和,把出席帽儿来。", "b": "《古今小说》"}]}]}, {"pinyin": "huo", "defs": [{"meaning": "——用于“搀和”(chānhuo)、“搅和”jiǎohuo、“暖和”nuǎnhuo、“热和”rèhuo、“软和”(ruǎnhuo)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1132wx','季','1','jì','子','8','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。从子,从稚省。“稚”亦兼表读音。本义:即排行最后的)。"}, {"meaning": "同本义(与“老”相对)。", "cites": [{"t": "季,少称。", "b": "《说文》"}, {"t": "曰伯某甫仲叔季,唯其所当。", "b": "《仪礼·士冠礼》。注:“伯、仲、叔、季,长幼之称。”"}, {"t": "季者,有中之辞也。—《谷梁传·昭公二十五年》", "b": ""}, {"t": "季者,幼也。", "b": "《白虎通》"}, {"t": "有齐季女。", "b": "《诗·召南·采蘋》"}, {"t": "生四子,太祖其季也。", "b": "《明史·太祖本纪》"}], "words": [{"w": "季女", "t": "最小的女儿"}, {"w": "季父", "t": "父亲的幼弟"}, {"w": "季指", "t": "小指头"}, {"w": "季弟", "t": "最小的弟弟。"}]}, {"meaning": "一年四季中,每季的最后一个月。", "cites": [{"t": "季春之月。", "b": "《礼记·月令》"}, {"t": "季冬讲武,习射御。", "b": "柳宗元《时令论上》"}], "words": [{"w": "季月", "t": "每季的最后一月,即农历三、六、九、十二月"}, {"w": "季考", "t": "宋代太学中每一季度末举行的考试"}, {"w": "季商", "t": "农历九月。"}]}, {"meaning": "下等。", "cites": [{"t": "季绢。", "b": "《管子·乘马》。注:“三等其下者曰季。”"}], "words": [{"w": "季祖母", "t": "祖父之妾"}, {"w": "季绢", "t": "下等的丝绢。"}]}, {"meaning": "物之幼嫩者。", "cites": [{"t": "凡服耜斩季材。", "b": "《周礼·山虞》"}], "words": [{"w": "季材", "t": "幼嫩的木材。"}]}, {"meaning": "末,一个朝代的末期。", "cites": [{"t": "虽当三季之王。", "b": "《国语·晋语》。注:“末也。”"}, {"t": "汉世昔云季,中原争逐鹿。", "b": "杨炯《广溪峡》"}, {"t": "视清季有加。", "b": "孙文《< 黄花冈七十二烈士事略> 序》"}], "words": [{"w": "季年", "t": "晚年"}, {"w": "季王", "t": "王朝末代的君主"}, {"w": "季业", "t": "末代的基业"}, {"w": "季世", "t": "末世,末叶。"}]}, {"meaning": "泛指弟弟。", "cites": [{"t": "群季俊秀,皆为惠连。", "b": "唐·李白《春夜宴桃李园序》"}]}, {"meaning": "", "cites": [{"t": "季文子相三君。(季文子辅佐三位国君。见《左传》襄公五年。季文子,鲁国大夫季孙行父,曾辅佐宣、成、襄三公,以忠俭著称,“文”是他的谥号。相,辅助。)", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "季氏", "t": "即春秋鲁国季孙氏。庄公弟季友的后裔。自友以下,其子孙“季孙行父”、“季孙宿”等,世为大夫,执掌鲁政,颇专擅,权势极盛。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1133wx','委','1','wēi wěi','女','8','','[{"pinyin": "wēi", "defs": [{"meaning": "曲,委曲。", "cites": [{"t": "委两馆于咸唐。", "b": "《楚辞·九叹·远游》"}, {"t": "委貌,冠形有委曲之貌,上大下小也。", "b": "《释名·释首饰》"}, {"t": "委委佗佗。", "b": "《诗·鄘风·君子偕老》"}]}]}, {"pinyin": "wěi", "defs": [{"meaning": "(会意。从女,从禾。“女”表顺随,“禾”表委曲。本义:曲折)。"}, {"meaning": "同本义。", "cites": [{"t": "委,委随也。", "b": "《说文》。按,委随犹委蛇。"}, {"t": "若至委曲小变,不可胜道。", "b": "《史记·天官书》"}], "words": [{"w": "委折", "t": "曲折"}, {"w": "委注", "t": "曲折流往"}, {"w": "委宛", "t": "委曲婉转"}, {"w": "委纡", "t": "曲折"}, {"w": "委延", "t": "曲折蜿蜒"}, {"w": "委坠", "t": "曲折,遥远。"}]}, {"meaning": "委托。", "cites": [{"t": "愿委之于子。", "b": "《战国策·齐策一》"}, {"t": "委广州府余。", "b": "《广东军务记》"}], "words": [{"w": "委计", "t": "托付以国家大计"}, {"w": "委付", "t": "委托;嘱咐"}, {"w": "委冰", "t": "托媒人"}, {"w": "委政", "t": "付以政柄"}, {"w": "委勘", "t": "交付审查"}, {"w": "委权", "t": "授以权柄"}, {"w": "委属", "t": "托付"}, {"w": "委遇", "t": "信任。"}]}, {"meaning": "丢弃,抛弃。", "cites": [{"t": "委,弃也。", "b": "《广雅》"}, {"t": "委而去之。", "b": "《孟子·公孙丑下》"}, {"t": "相委而去。", "b": "《世说新语·方正》"}], "words": [{"w": "委去", "t": "委弃而离去"}, {"w": "委世", "t": "弃世"}, {"w": "委仗", "t": "丢弃武器"}, {"w": "委伏", "t": "委弃埋没"}, {"w": "委舍", "t": "舍弃,委卸"}, {"w": "委叛", "t": "弃官叛离"}, {"w": "委捐", "t": "放弃,丢掉。"}]}, {"meaning": "推卸;推诿。", "cites": [{"t": "司马欲委罪于孤耶?", "b": "《晋书·王裒传》"}], "words": [{"w": "委咎", "t": "归罪"}, {"w": "委卸", "t": "推卸。"}]}, {"meaning": "安,安于。", "cites": [{"t": "乐天安分,以至百年。", "b": "陶潜《自祭文》"}]}, {"meaning": "交付,给。", "cites": [{"t": "婆惜道:“第二件,我头上带的,我身上穿的,家里使用的,虽都是你办的,也委一纸文书,不许你日后来讨。”", "b": "《水浒传》"}]}, {"meaning": "水的下流。", "cites": [{"t": "三王之祭川也,皆先河而后海,或源也,或委也,此之谓务本。", "b": "《礼记》"}]}, {"meaning": "后称事情的本末为原委或源委。"}, {"meaning": "帽檐,冠檐。", "cites": [{"t": "委武玄缟而后蕤。", "b": "《礼记》"}]}, {"meaning": "末尾。", "cites": [{"t": "教化从来有源委,必将泳海先泳河。", "b": "《骠国乐》"}]}, {"meaning": "琐碎;鄙陋。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1134wx','秉','1','bǐng','禾','8','','[{"pinyin": "bǐng", "defs": [{"meaning": "(会意。从又,从禾,表示以手持禾。“又”篆体象一只手。本义:禾把,禾束)。"}, {"meaning": "同本义。", "cites": [{"t": "秉,禾束也。", "b": "《说文》"}, {"t": "彼有遗秉。", "b": "《诗·小雅·大田》"}, {"t": "或取一秉秆焉。", "b": "《左传·昭公二十七年》"}], "words": [{"w": "秉穗", "t": "收稻时遗留在田中的禾把与禾实"}, {"w": "秉握", "t": "一握稻把。言数量少。"}]}, {"meaning": "权力,权柄。", "cites": [{"t": "治国不失秉。", "b": "《管子·小匡》"}, {"t": "国子实执齐秉。", "b": "《左传·哀公十七年》"}]}, {"meaning": "手拿着,手持(是一只手从旁边拿着小物)。", "cites": [{"t": "秉,执也。", "b": "《尔雅》"}, {"t": "武王载旆,有虔秉钺。", "b": "《诗·商颂·长发》"}, {"t": "右手秉遗穗,左臂悬敝筐。", "b": "白居易《观刈麦》"}], "words": [{"w": "秉圭", "t": "持着玉圭"}, {"w": "秉烛云长", "t": "即云长秉烛,指三国关云长执灯夜读的事"}, {"w": "秉笔", "t": "执笔;握笔"}, {"w": "秉烛达旦", "t": "指关云长在护送两位皇嫂途中,秉烛达旦事"}, {"w": "秉节", "t": "持节。节,古代使臣所持的符节;保持节操,守节"}, {"w": "秉牍", "t": "手执简牍。"}]}, {"meaning": "引申为主持,掌握。", "cites": [{"t": "光秉政前后二十年。", "b": "《汉书·霍光传》"}, {"t": "共秉朝政。", "b": "《三国志·吕布传》"}], "words": [{"w": "秉公灭私", "t": "主持公道,灭除私念"}, {"w": "秉正无私", "t": "主持正义,没有私念"}, {"w": "秉教伽持", "t": "佛教语。指执行佛法、施加佛力于众生,以保护扶持之。"}]}, {"meaning": "保持;坚持。", "cites": [{"t": "民之秉彝。", "b": "《诗·大雅·丞民》"}, {"t": "君子秉心。", "b": "《诗·小雅·小弁》"}], "words": [{"w": "秉彝", "t": "坚持道理"}, {"w": "秉心", "t": "居心;用心;持心"}, {"w": "秉志", "t": "持志。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1135wx','佳','1','jiā','亻','8','','[{"pinyin": "jiā", "defs": [{"meaning": "(形声。从人,圭(guī)声。本义:美,美好)。"}, {"meaning": "同本义。", "cites": [{"t": "佳,善也。", "b": "《说文》"}, {"t": "佳,大也,又,好也。", "b": "《广雅》"}, {"t": "佳兵者不祥。", "b": "《老子》"}, {"t": "佳丽人之所出也。", "b": "《战国策·中山策》"}, {"t": "丽以佳只。", "b": "《楚辞·大招》"}, {"t": "佳侠函光。", "b": "《汉书·外戚传》。注:“佳侠,犹佳丽。”"}, {"t": "形夸骨佳。", "b": "《淮南子·脩务》"}, {"t": "佳人不同体,美人不同面,而皆说于目。", "b": "《淮南子·说林》"}, {"t": "山气日夕佳。", "b": "晋·陶渊明《饮酒》"}, {"t": "秋菊有佳色。", "b": ""}, {"t": "每自矜风调,思得佳偶。", "b": "蒋防《霍小玉传》"}, {"t": "作敲字佳。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "佳木秀而繁阴。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "佳者笼养。", "b": "《聊斋志异·促织》"}, {"t": "小时了了,大未必佳。", "b": "《世说新语·言语》"}, {"t": "一经品题,便作佳士。", "b": "李白《与韩荆州书》"}], "words": [{"w": "佳士", "t": "品学兼优的人"}, {"w": "佳夕", "t": "良夜"}, {"w": "佳器", "t": "美好的器物"}, {"w": "佳口", "t": "美婢"}, {"w": "佳侠", "t": "佳丽,美女"}, {"w": "佳色", "t": "妍丽的颜色;美丽的色彩"}, {"w": "佳冶", "t": "娇美妖冶"}, {"w": "佳观", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1136wx','侍','1','shì','亻','8','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从人,寺声。本义:在尊长旁边陪着)。"}, {"meaning": "同本义。", "cites": [{"t": "侍,承也。", "b": "《说文》"}, {"t": "曾子侍。", "b": "《孝经》。郑注:“卑在尊者之侧为侍也。”"}, {"t": "侍中。", "b": "《后汉书·邳彤传》。注:“有左右曹,入侍天子。故曰侍中。”"}, {"t": "中常侍。", "b": "《后汉书·朱穆传》。注:“秦官也。”"}, {"t": "使侍人僚租告公。", "b": "《左传·昭公二十五年》"}, {"t": "遂即天子位,群臣以次侍。", "b": "《汉书·文帝纪》"}, {"t": "余立侍左右,援疑质理,俯身侧耳以请。", "b": "明·宋濂《送东阳马生序》"}]}, {"meaning": "引申为服侍、侍奉。", "cites": [{"t": "子路、曾皙冉有、公西华侍坐。", "b": "《论语·先进》"}, {"t": "媵侍于户外。", "b": "《仪礼·士昏礼》"}, {"t": "执荐者百人侍西房。", "b": "《荀子·正论·五祀》"}]}, {"meaning": "进言,进献。", "cites": [{"t": "迁我京职,则汝朝夕侍母。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "荀欣侍以选练举贤,任官使能。", "b": "《史记·赵世家》"}]}, {"meaning": "侍妾;侍女。", "cites": [{"t": "一为阿爷侍者朱氏,一为阿兄侍者陶氏。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "侍儿", "t": "丫环;婢女;妇女自称的谦辞"}, {"w": "侍妾", "t": "婢女"}, {"w": "侍姝", "t": "姣美的侍女"}, {"w": "侍姬", "t": "贴身侍女或姬妾。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1137wx','岳','1','yuè','山','8','','[{"pinyin": "yuè", "defs": [{"meaning": "(会意。从山,从丘。古文字形,象两座高大的山峰形,表示高山大岭。“嶽”字从山,狱声。本义:高大的山)。"}, {"meaning": "特指名山“五岳”或“四岳”。", "cites": [{"t": "嶽,东岱、南霍、西华、北恒、中泰室,王者之所巡狩所至。从山,狱声。古文从山,象高形,今作岳。", "b": "《说文》。按,唐虞四岳,至《周礼·大宗伯》,始有五岳之名。"}, {"t": "崧高维岳,骏极于天。", "b": "《诗·大雅·崧山》"}]}, {"meaning": "高大的山。", "cites": [{"t": "二女感于崇岳兮。", "b": "《思玄赋》。注:“山也。”"}, {"t": "山岳潜形。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "岳阡", "t": "山上墓道"}, {"w": "岳秀", "t": "山岳秀丽"}, {"w": "岳峙", "t": "谓如高山耸立"}, {"w": "岳神", "t": "山神"}, {"w": "岳镇渊停", "t": "如山岳屹立,如渊水停滞,多形容人坚定沉着。"}]}, {"meaning": "“嶽”另见yuè。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1138wx','供','1','gōng gòng','亻','8','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从人,共声。本义:供给,供应)。"}, {"meaning": "同本义。", "cites": [{"t": "供,供给。", "b": "《说文》"}, {"t": "凡与之所以大用者,外供甲兵而内给淫奢也。", "b": "《韩非子·解老》"}, {"t": "王之诸臣皆足以供之,而王岂为是哉?", "b": "《孟子·梁惠王上》"}, {"t": "今诸生学于太学,县官日有廪稍之供,父母岁有裘葛之遗,无冻馁之患矣。", "b": "明·宋濂《送东阳马生序》"}, {"t": "一人之食供十人已不足,何况供百人乎?", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "供亿", "t": "供应所需,也指供应的东西"}, {"w": "供膳", "t": "供给膳食"}, {"w": "供饷", "t": "供给差粮"}, {"w": "供祀", "t": "供给祭祀。"}]}, {"meaning": "恭敬。有礼貌。", "cites": [{"t": "行而供冀。", "b": "《荀子·脩身》"}], "words": [{"w": "供翼", "t": "恭敬小心。供:通恭。"}]}]}, {"pinyin": "gòng", "defs": [{"meaning": "(形声。从人,共声。本义:摆设;陈设)。"}, {"meaning": "同本义。", "cites": [{"t": "供,设也。", "b": "《说文》"}, {"t": "供帐。", "b": "《后汉书·班彪传》"}, {"t": "曩胡公按部,令所过毋供张。", "b": "《明史·海瑞传》"}, {"t": "士大夫出其境率不得供顿,由是怨颇兴。", "b": "《明史·海瑞传》"}], "words": [{"w": "供帐", "t": "陈设帷帐等用具。作为宴会、旅行之用"}, {"w": "供顿", "t": "备酒宴客;供应"}, {"w": "供馔", "t": "陈设祭祀食品"}, {"w": "供享", "t": "摆供品以祭祀"}, {"w": "供佛", "t": ""}]}, {"meaning": "供奉,供献。", "cites": [{"t": "张羽旗,设供具,以礼神君。", "b": "《史记·封禅书》"}, {"t": "休唱贞元供奉曲,当时朝士已无多。", "b": "唐·刘禹锡《听旧宫中乐人穆氏唱歌》"}], "words": [{"w": "供具", "t": "供奉鬼神的器具。后也指供佛的器具"}, {"w": "供奉曲", "t": "宫廷内演奏的曲子"}, {"w": "供进", "t": "进献宫廷"}, {"w": "供御", "t": "进奉于帝王。"}]}, {"meaning": "受审者陈述案情。", "cites": [{"t": "吏辈责供,多不足凭。", "b": "宋·陈襄《州县提纲·面审所供》"}], "words": [{"w": "招供", "t": "供出犯罪事实"}, {"w": "吐供", "t": "招供"}, {"w": "供招", "t": "招供。供出犯罪事实"}, {"w": "供攀", "t": "攀供。在供词中牵连他人。"}]}, {"meaning": "供词,口供,受审者所说的案情。", "cites": [{"t": "张文定公在真宗时,戚里有争分财不均者,更相诉讼,……即命各供状结实。", "b": "宋·赵自鐐《狱讼》"}], "words": [{"w": "翻供;供款", "t": "供词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1139wx','使','1','shǐ','亻','8','','[{"pinyin": "shǐ", "defs": [{"meaning": "(形声。从人,吏声。从人表示人的动作行为。本义:命令)。"}, {"meaning": "同本义。", "cites": [{"t": "使,伶也。", "b": "《说文》。按,伶者,令也。"}, {"t": "故君使其臣。", "b": "《礼记·表记》。注:“谓使之聘问师役之属也。”"}, {"t": "扶苏以数谏故,上使外将兵。", "b": "《史记·陈涉世家》"}, {"t": "怀王使屈原造为宪令。", "b": "《史记·屈原列传》"}, {"t": "魏王使将军晋鄙将十万众救赵。", "b": "《史记·魏公子列传》"}], "words": [{"w": "支使", "t": "命令人去做事。"}]}, {"meaning": "派遣。", "cites": [{"t": "乃使蒙恬北筑长城而守藩篱。", "b": "汉·贾谊《过秦论》"}, {"t": "郑穆公使视客馆,则束载,厉兵,秣马矣。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "差使", "t": "差遣;派遣"}, {"w": "使转", "t": "打发去"}, {"w": "使遣", "t": "差遣"}, {"w": "使会", "t": "差遣,使唤。"}]}, {"meaning": "致使;让;叫。", "cites": [{"t": "不以一己之利为利,而使天下受其利。", "b": "清·黄宗羲《原君》"}, {"t": "到那时使吾眼睁睁看汝死,或使汝眼睁睁看我死,吾能之乎?", "b": "清·林觉民《与妻书》"}], "words": [{"w": "一场大火,使他一贫如洗;虚心使人进步", "t": ""}]}, {"meaning": "运用;使用。", "cites": [{"t": "联闻,使功不如使过。", "b": "《旧唐书·李靖传》"}, {"t": "造父巧于使马。", "b": "《韩诗外传》"}, {"t": "尚贤使能。", "b": "《荀子·王制》"}], "words": [{"w": "使费", "t": "使用钱财"}, {"w": "使低嘴", "t": "说坏话"}, {"w": "使不着", "t": "用不着"}, {"w": "使民", "t": "使用民力"}, {"w": "使风", "t": "利用风力"}, {"w": "使指", "t": "使用手指"}, {"w": "使官", "t": "利用职权"}, {"w": "使弊幸", "t": "用心计"}, {"w": "使贤任能", "t": "任用有品德有才能的人"}, {"w": "使钱出土", "t": ""}]}, {"meaning": "使唤;役使;支使。", "cites": [{"t": "节用而爱人,使民以时。", "b": "《论语·学而》"}, {"t": "民之外事,莫难于战,故轻法不可以使之。", "b": "《商君书·外内》"}, {"t": "使之虽病也。", "b": "《礼记·檀弓》"}, {"t": "况于使之者乎。", "b": "《荀子·解蔽》。注:“役也。”"}, {"t": "人皆得以隶使之,安能屈豪杰之流,扼腕墓道,发其志士之悲哉!", "b": "明·张溥《五人墓碑记》"}, {"t": "恣君之所使之。", "b": "《战国策·赵策》"}], "words": [{"w": "使伶", "t": "供使唤的人"}, {"w": "使役", "t": "役使,驱使。"}]}, {"meaning": "出使。", "cites": [{"t": "唐雎使于秦。", "b": "《战国策·魏策》"}, {"t": "臣舍人蔺相如可使。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "使北营,留北关外,为一卷。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "使人", "t": "奉命出使的人。"}]}, {"meaning": "放纵,任性。", "cites": [{"t": "灌夫为人刚直,使酒。", "b": "《汉书·灌夫传》。注:“因酒而使气也。”"}], "words": [{"w": "使脾气;使心别气", "t": "发脾气"}, {"w": "使性", "t": "使性气,使性儿。发脾气,任性。"}]}, {"meaning": "主使。", "cites": [{"t": "是时以大中丞抚吴者为魏之私人,周公之逮所由使也。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "使者。", "cites": [{"t": "时汉连伐胡,数通使相窥视。", "b": "《汉书·苏武传》"}, {"t": "梁使三反,孟尝君固辞不往也。", "b": "《战国策·齐策》"}], "words": [{"w": "专使;使曹", "t": "使者"}, {"w": "使轺", "t": "使者所用的快车"}, {"w": "使牙", "t": "节度使办公的衙门"}, {"w": "使臣星", "t": "使者"}, {"w": "使车", "t": "使者所乘之车"}, {"w": "使传", "t": "经使者传达的皇帝诏书"}, {"w": "使署", "t": "使馆"}, {"w": "使客", "t": "使者"}, {"w": "使官", "t": "使臣"}, {"w": "使物", "t": "使者和货物。"}]}, {"meaning": "使命。", "cites": [{"t": "时周瑜受使至番阳,肃劝权召瑜还。", "b": "《资治通鉴》"}]}, {"meaning": "佣人;奴仆。", "cites": [{"t": "那厨役雇的是个乡下小使。", "b": "《儒林外史》"}], "words": [{"w": "使下", "t": "仆从"}, {"w": "使长", "t": "奴仆对家主的称呼"}, {"w": "使婢", "t": "侍婢;婢女"}, {"w": "使唤的", "t": "奴仆,仆婢"}, {"w": "使人", "t": "仆人"}, {"w": "使数", "t": "随从,供使唤的人"}, {"w": "使头", "t": "仆人的头儿。"}]}, {"meaning": "假如;如果。", "cites": [{"t": "向使三国各爱其地,齐人勿附于秦。", "b": "清·刘开《问说》"}, {"t": "使举国之少年而果为少年也,则吾中国为未来之国,其进步未可量也。", "b": "清·梁启超《少年中国说》"}], "words": [{"w": "使无先生相助,岂有我之今日?使能发愤图强,必定前途无量", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1140wx','例','1','lì','亻','8','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从人,列声。本义:比照) 同本义。", "cites": [{"t": "例,比也。", "b": "《说文》。按,礼记服问:上附下附,列也。公别比例之义。古只作列,此字后出。"}, {"t": "举此以例其余。", "b": "元·刘壎《隐居通议·欧阳公》"}], "words": [{"w": "溯古例今;以此例比", "t": ""}]}, {"meaning": "类;列。", "cites": [{"t": "扬州城下进退不由,殆例送死。", "b": "文天祥《指南录后序》"}], "words": [{"w": "不在此例;例及", "t": "连类而及"}, {"w": "例侪", "t": "按类分列。"}]}, {"meaning": "可以作依据的事物;例子。", "cites": [{"t": "两贤同时,便是未有前例。", "b": "《南齐书·陆慧晓传》"}], "words": [{"w": "援例行事;例贡", "t": "边境官员及土司每年依例献纳的贡物;清代又指例贡生"}, {"w": "例授", "t": "循例封赠"}, {"w": "病例;实例", "t": ""}]}, {"meaning": "规定;规则;条例。", "cites": [{"t": "故例。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "开例;禁例;老例", "t": "旧规矩;旧习惯。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1141wx','侠','1','xiá','亻','8','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从人,夹声。本义:侠义)。"}, {"meaning": "同本义。指见义勇为、肯舍己助人的性格、气质或行为。", "cites": [{"t": "俠,俜也。", "b": "《说文》"}, {"t": "所谓言必行,行必果,己诺 必诚,不爱其躯,赴士之阨困,千里诵义者也。荀悦曰,立气齐,作威福,结私交,以立强于世者,谓之游侠。", "b": "《史记·游侠传》"}, {"t": "刘义者,亦一节士。少放肆为侠行,因酒杀人亡命。", "b": "《新唐书·刘义传》"}, {"t": "这十三妹是一位正气不过的侠女,你为何这等唐突他起来?", "b": "《儿女英雄传》"}], "words": [{"w": "侠奴", "t": "侠义的奴仆"}, {"w": "侠情", "t": "见义勇为、舍己助人的感情。"}]}, {"meaning": "侠客。", "cites": [{"t": "材力绝人,少重然许,喜侠节。", "b": "《新唐书·窦建德传》"}], "words": [{"w": "游侠;武侠;剑侠;豪侠;大侠;女侠;侠节", "t": "侠客的节操。"}]}, {"meaning": "要挟。", "cites": [{"t": "凶强侠气(粗暴强悍,以力欺人。侠,这里指“要挟”。侠气,以力欺人,为人霸道)。", "b": "《世说新语·自新》"}, {"t": "为气任侠。", "b": "《史记·季布传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1142wx','侥','1','jiǎo yáo','亻','8','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从人,尧声。(yáo) 本义: 僬侥(jiāoyáo): 古代传说中的矮人)。"}, {"meaning": "贪求不止。", "cites": [{"t": "不敢复有侥冀。", "b": "《资治通鉴》"}], "words": [{"w": "侥速", "t": "贪求速度"}, {"w": "侥滥", "t": "贪得无厌不守法度"}, {"w": "侥望", "t": "对财利的非分奢望。"}]}, {"meaning": "引申指希求意外成功或幸免。", "cites": [{"t": "此以人之国侥倖也。", "b": "《庄子·在宥》"}], "words": [{"w": "侥天之幸", "t": "极其侥幸"}, {"w": "侥利", "t": "侥幸所得之利"}, {"w": "侥会", "t": "侥幸遇合。"}]}, {"meaning": "侥薄,即浇薄。指民俗浮薄。", "cites": [{"t": "不修廉隅以侥名当世。", "b": "王安石《答龚深父书》"}]}]}, {"pinyin": "yáo", "defs": [{"meaning": "——“僬侥”(jiāoyáo)。", "cites": [{"t": "南方有焦侥人,长三尺,短之极,从人,尧声。", "b": "《说文》"}, {"t": "从中州以东,四十万里,得僬侥国。", "b": "《列子·汤问》"}, {"t": "有小人,名曰焦侥之国。几姓,嘉谷是食。", "b": "《山海经·大荒南经》"}, {"t": "焦侥国在二首东。", "b": "《山海经·海外南经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1143wx','版','1','bǎn','片','8','','[{"pinyin": "bǎn", "defs": [{"meaning": "(形声。从片,反声。“片”(piàn),意思是破开的木片或草片。从“片”的字大都与木板有关。本义:筑墙的夹板)。"}, {"meaning": "同本义。", "cites": [{"t": "版,判也。", "b": "《说文》。按,判木也。"}, {"t": "傅说举于版筑之间。", "b": "《孟子·告子下》"}, {"t": "五板(版)而堵。", "b": "《公羊传·定公十二年》"}, {"t": "缩版以载。", "b": "《诗·大雅·绵》"}]}, {"meaning": "又指版筑的土墙。", "cites": [{"t": "朝济而夕设版焉。", "b": "《左传·僖公三十年》"}], "words": [{"w": "版筑", "t": ""}]}, {"meaning": "牍。古时书写用的木简,后也指书籍。", "cites": [{"t": "修业不息版。", "b": "《管子·宙合》。注:“牍也。”"}, {"t": "送版使王[献之]书之。", "b": "《世说新语》"}], "words": [{"w": "版牍", "t": "古代书写用的薄木片。"}]}, {"meaning": "名册;户籍。", "cites": [{"t": "听闾里以版图。", "b": "《周礼·小宰》。注:户籍也。”"}, {"t": "掌群臣之版。", "b": "《周礼司士》。注:“名籍也。”"}, {"t": "嗟哉生计一如此,廖入王民版籍论。", "b": "梅尧臣《小村》"}], "words": [{"w": "版曹", "t": "户部的别称。以掌管版籍得名。"}]}, {"meaning": "国家的图籍。", "cites": [{"t": "式负版者。", "b": "《论语》。郑注:“谓邦国籍也。”"}, {"t": "凡五部,咸入版籍。", "b": "《辽史》"}]}, {"meaning": "朝笏,即手板。古代官吏上朝用的笏。", "cites": [{"t": "投版弃官而去。", "b": "《后汉书·范滂传》"}], "words": [{"w": "版谒", "t": "持名帖进见。"}]}, {"meaning": "授职;任命。", "cites": [{"t": "华版为秦州刺史。", "b": "房玄龄《晋书》"}], "words": [{"w": "版檄", "t": "任命官员的文书"}, {"w": "版职", "t": "以白版形式授予的职务或封号。"}]}, {"meaning": "古代墙计量单位。", "cites": [{"t": "引汾水灌其城,城不浸者三版。", "b": "《史记·赵世家》"}], "words": [{"w": "一版长一丈,或八尺,或六尺,高二尺", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1144wx','侄','1','zhí','亻','8','','[{"pinyin": "zhí", "defs": [{"meaning": "(侄为姪的俗字)弟兄或其他同辈男性亲属的子女。", "cites": [{"t": "姪,兄之女也。从女,至声。", "b": "《说文》"}, {"t": "女子谓兄弟之子为姪。", "b": "《尔雅》"}, {"t": "谓吾姑者,吾谓之姪。", "b": "《仪礼·丧服传》"}, {"t": "大夫不名世臣姪娣。", "b": "《礼记·曲礼》。疏:“姪是妻之兄女。”"}, {"t": "继室以其姪。", "b": "《左传·襄公二十三年》"}, {"t": "姪其从姑。", "b": "《左传·僖公十五年》"}, {"t": "则我皇妣大姜之姪。", "b": "《国语·周语》。注:“女子谓昆弟之子,男女皆曰姪。”朱按,受姪称者,男女皆可通,而称人姪者,必妇人也。男子称兄弟之子曰从子。"}, {"t": "侄其从姑。", "b": "《左传·僖公十五年》"}], "words": [{"w": "侄少爷", "t": "旧时对侄子的尊称"}, {"w": "侄儿", "t": "侄子"}, {"w": "侄儿子", "t": "侄儿,侄子"}, {"w": "侄哥", "t": "对侄子的爱称"}, {"w": "表侄;内侄;世侄", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1145wx','侦','1','zhēn','亻','8','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从人,贞声。本义:探伺,暗中察看)。"}, {"meaning": "同本义。", "cites": [{"t": "外令兄弟求其纤过,内使御者侦伺得失。", "b": "《字汇》"}], "words": [{"w": "侦知", "t": "探知;暗中查明"}, {"w": "侦伺", "t": "窥探,伺望"}, {"w": "侦者", "t": "侦探敌情的人。"}]}, {"meaning": "问,卜问。凭借占卜来寻求预言。", "cites": [{"t": "《易》曰:“不恒其德,或承之羞。恒其德侦,妇人吉,夫子凶。”", "b": "《礼记》"}], "words": [{"w": "侦问", "t": "探问。"}]}, {"meaning": "侦察。", "cites": [{"t": "侦谍不敢东窥,驼马不敢南牧。", "b": "《文选·沈约·齐故字陆昭王碑文》"}], "words": [{"w": "侦谍", "t": "从事侦察的密探"}, {"w": "侦巡", "t": "侦察巡逻"}, {"w": "侦哨", "t": "侦察岗"}, {"w": "侦候", "t": "侦察,侦探。"}]}, {"meaning": "探子;间谍。", "cites": [{"t": "生疑为宋人之侦,姑伪应之。", "b": "《聊斋志异》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1146wx','侣','1','lǚ','亻','8','','[{"pinyin": "lǚ", "defs": [{"meaning": "(形声。从人,吕声。本义:伴侣,同伴) 同本义。", "cites": [{"t": "命俦啸侣,或戏清流,或翔神渚。", "b": "曹植《洛神赋》"}, {"t": "我来无伴侣,把酒对南山。", "b": "唐·韩愈《把酒》"}, {"t": "故人念我寡徒侣,持用赠我比知音。", "b": "唐·韩愈《利剑》"}, {"t": "以元侣悲。", "b": "清·林觉民《与妻书》"}, {"t": "告其故侣。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "携来百侣曾游。", "b": "毛泽东《游泳》"}], "words": [{"w": "仙侣;僧侣", "t": "出家修行的佛教徒"}, {"w": "侣俦", "t": "朋友。"}]}, {"meaning": "结为伴侣;陪伴。", "cites": [{"t": "侣鱼虾而友麋鹿。", "b": "苏轼《赤壁赋》"}], "words": [{"w": "侣行", "t": "结伴而行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1147wx','侧','1','cè zè zhāi','亻','8','','[{"pinyin": "cè", "defs": [{"meaning": "(形声。从人,则声。本义:旁边)。"}, {"meaning": "同本义。亦用作谦词。", "cites": [{"t": "侧,旁也。", "b": "《说文》"}, {"t": "居侧室。", "b": "《礼记·内则》。注:“谓夹之室次燕寝也。”"}, {"t": "立于侧阶。", "b": "《书·顾命》"}, {"t": "倾容幸而待侧。", "b": "《楚辞·思古》"}, {"t": "有泉侧出。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "左侧;右侧;侧闻", "t": "谦词。表示从旁听到"}, {"w": "侧畔", "t": "旁边。"}]}, {"meaning": "边缘。", "cites": [{"t": "坎坎伐辐兮,置之河之侧兮。", "b": "《诗·魏风·伐檀》"}, {"t": "铸钟官赤侧。", "b": "《史记·平准书》。集解:“以赤铜为其廓也。”"}]}, {"meaning": "向旁边歪斜。", "cites": [{"t": "樊哙侧其盾以撞。", "b": "《史记·项羽本纪》"}, {"t": "侧弁之俄。", "b": "《诗·小雅·宾之初筵》。笺:“侧,倾也。”"}], "words": [{"w": "侧耳细听;侧目", "t": "斜着眼睛看,形容畏惧或愤恨的样子。"}]}, {"meaning": "靠近。", "cites": [{"t": "侧其故处。", "b": "《仪礼·公食礼》。疏:“近也。”"}], "words": [{"w": "侧近", "t": "临近,最近。"}]}, {"meaning": "不正,邪辟。", "cites": [{"t": "无反无侧,王道正直。", "b": "《书·洪范》"}, {"t": "乡之行劫缚者,侧目莫敢过其门。", "b": "柳宗元《童区寄传》"}]}]}, {"pinyin": "zè", "defs": [{"meaning": "倾斜。", "cites": [{"t": "侧弁之俄。", "b": "《诗·小雅·宾之初宴》"}, {"t": "无反无侧。", "b": "《书·洪范》"}]}, {"meaning": "“平仄”也作“平侧”。"}]}, {"pinyin": "zhāi", "defs": [{"meaning": "", "words": [{"w": "帽子侧歪在一边;侧棱;侧歪", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1148wx','凭','1','píng','几','8','','[{"pinyin": "píng", "defs": [{"meaning": "(会意。从几,从任。几,矮而小的桌子。任,凭借。本义:倚靠)。"}, {"meaning": "同本义。", "cites": [{"t": "恁,依也。", "b": "《小尔雅》"}, {"t": "某自幼与周郎同窗交契,愿凭三寸不烂之舌,往江东说此人来降。", "b": "《三国演义》"}, {"t": "或凭几学书。", "b": "明·归有光《项脊轩志》"}, {"t": "独自莫凭栏,无限江山。", "b": "李煜《浪淘沙》"}], "words": [{"w": "凭几", "t": "凭靠几案"}, {"w": "凭肩", "t": "以手靠在别人肩上"}, {"w": "凭脉", "t": "搭脉。"}]}, {"meaning": "依托;仰仗。", "cites": [{"t": "不凭其子,灵公夺而里之。", "b": "《庄子·则阳》"}, {"t": "凭恃其众。", "b": "《左传·哀公七年》"}], "words": [{"w": "凭附", "t": "依附;依靠"}, {"w": "凭妖", "t": "依托妖言"}, {"w": "凭狐", "t": "喻依仗他人权势的人"}, {"w": "凭城", "t": "据城以守"}, {"w": "凭系", "t": "依托维系"}, {"w": "凭负", "t": "依恃"}, {"w": "凭托", "t": "依仗,依托"}, {"w": "凭高", "t": "登临高处"}, {"w": "凭虚", "t": "凌空。"}]}, {"meaning": "不论;不管。", "cites": [{"t": "凭谁问:廉颇老矣,尚能饭否?", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "凭你跑得多快,我也赶得上", "t": ""}]}, {"meaning": "如此。", "cites": [{"t": "原来凭地可恶,把我轻薄也罢,如何触伤我父亲。", "b": "《石点头》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1149wx','侨','1','qiáo','亻','8','','[{"pinyin": "qiáo", "defs": [{"meaning": "(形声。从人,乔声。本义:高) 同本义。", "cites": [{"t": "侨,高也。", "b": "《说文》"}, {"t": "败长狄侨如。", "b": "《左传·文公十一年》"}], "words": [{"w": "侨人", "t": "踩高跷的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1150wx','佩','1','pèi','亻','8','','[{"pinyin": "pèi", "defs": [{"meaning": "(会意。从人凡巾。本义:系在衣带上的装饰品)。"}, {"meaning": "同本义。", "cites": [{"t": "佩,大带佩也。", "b": "《说文》"}, {"t": "青青子佩。", "b": "《诗·郑风·子衿》"}, {"t": "共王之服玉佩玉。", "b": "《周礼·王府》。注:“王之所带者。”"}, {"t": "遗余佩兮澧浦。", "b": "《楚辞·湘君》"}], "words": [{"w": "佩玖", "t": "作佩饰用的浅黑色美石"}, {"w": "佩玦", "t": "有缺口的环形佩玉"}, {"w": "佩珂", "t": "用黄黑色玉石制成的佩饰"}, {"w": "佩衽", "t": "佩玉和衣襟。"}]}, {"meaning": "佩带,把徽章、符号、手枪等戴在或挂在胸前、臂上、肩上或腰间。", "cites": [{"t": "佩之金玦。", "b": "《左传·闵公二年》"}, {"t": "古代君子,必佩玉。", "b": "《礼记·玉藻》"}, {"t": "佩其象揥。", "b": "《诗·魏风·葛屦》"}, {"t": "举所佩玉玦以示之者三。", "b": "《史记·项羽本纪》"}], "words": [{"w": "佩章", "t": "古代官员佩带的印章"}, {"w": "佩巾", "t": "古代女子外出时系于腰左的拭巾"}, {"w": "佩玉", "t": "古代系于衣带用作装饰的玉。"}]}, {"meaning": "钦佩,敬仰。", "cites": [{"t": "圣人行之,愚者佩之。", "b": "《素问·四气调神大论》"}]}, {"meaning": "携带,随身拿着。", "cites": [{"t": "农夫佩其耒耜,工匠佩其斧斤。", "b": "《白虎通·衣裳》"}, {"t": "杻阳之山,有兽名鹿蜀,佩之宜子孙。", "b": "《山海经·南山经》。注:“谓带其皮毛。”"}], "words": [{"w": "佩仰", "t": "钦佩和信仰"}, {"w": "佩慰", "t": "钦佩欣慰"}, {"w": "佩德勿谖", "t": "受到的恩情,永远不会忘记。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1151wx','货','1','huò','贝','8','','[{"pinyin": "huò", "defs": [{"meaning": "(形声。从贝,化声。本义:财物)。"}, {"meaning": "财物,金钱珠玉布帛的总称。", "cites": [{"t": "货,财也。", "b": "《说文》"}, {"t": "二曰货。", "b": "《书·洪范》。郑注:“掌金帛之官。”"}, {"t": "商贾阜通货贿。", "b": "《周礼·太宰》。注:“金玉曰货,布帛曰贿。”"}, {"t": "司货。", "b": "《礼记·曲礼》"}, {"t": "多货则伤于德。", "b": "《仪礼·聘礼》。注:“货,天地所化生谓玉也。”"}, {"t": "假货居贿。", "b": "《国语·晋语》"}, {"t": "患货之不足。", "b": ""}, {"t": "而货财寡。", "b": "《韩非子·五蠹》"}, {"t": "贪于财货。", "b": "《史记·项羽本纪》"}, {"t": "治行则货积。", "b": "《商君书·立本》"}, {"t": "居为奇货。", "b": "《聊斋志异·促织》"}], "words": [{"w": "货儿", "t": "货郎"}, {"w": "货易", "t": "即贸易"}, {"w": "货财", "t": "财物"}, {"w": "货贿", "t": "金玉布帛,即财物。"}]}, {"meaning": "钱币。", "cites": [{"t": "日中为市,致天下之民,聚天下之货,交易而退。", "b": "《易·系辞下》"}, {"t": "先是汉川悉以绢为货。", "b": "《宋书·刘秀之传》"}], "words": [{"w": "货布", "t": "古代钱币名。王莽时所铸。又泛指货币"}, {"w": "货贝", "t": "古代用贝壳作的货币"}, {"w": "货法", "t": "货币流通的法令"}, {"w": "货泉", "t": "王莽时货币名。亦指货币的通称。"}]}, {"meaning": "买进,卖出。", "cites": [{"t": "所货西洋珠。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "货卖", "t": "出售"}, {"w": "货卜", "t": "卖卜;卖卦"}, {"w": "货畚", "t": "售畚箕"}, {"w": "货与", "t": "卖给;效力"}, {"w": "货产", "t": "典卖财产。"}]}, {"meaning": "贿赂。", "cites": [{"t": "曹伯之竖侯鑐货筮史。", "b": "《左传·僖公二十八年》"}, {"t": "邠人偷嗜暴恶者,率以货窜名军伍中。", "b": "柳宗元《段太尉逸事状》"}], "words": [{"w": "货贿", "t": "以财物贿赂官吏"}, {"w": "货求", "t": "谓受贿"}, {"w": "货赂", "t": "贿赂"}, {"w": "货遗", "t": "贿赂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1152wx','侈','1','chǐ','亻','8','','[{"pinyin": "chǐ", "defs": [{"meaning": "(形声。从人,多声。本义:自高自大,盛气凌人)。"}, {"meaning": "同本义。", "cites": [{"t": "侈,掩胁也。", "b": "《说文》。段注:“掩者,掩盖其上;胁者,胁制其旁。凡自多以陵人曰侈。此侈之本义也。”"}, {"t": "侈兮哆兮。", "b": "《诗·小雅·巷伯》"}], "words": [{"w": "侈慢", "t": "自大傲慢"}, {"w": "侈满", "t": "骄纵"}, {"w": "侈然", "t": "骄纵貌;自大貌"}, {"w": "侈傲", "t": "骄纵"}, {"w": "侈邪", "t": "言行放肆。"}]}, {"meaning": "奢侈,追求过分的享受。", "cites": [{"t": "侈,一曰奢也。", "b": "《说文》"}, {"t": "于臣侈矣。", "b": "《左传·昭公三年》"}, {"t": "四方之国有侈离之德则必灭。", "b": "《荀子·王霸》"}, {"t": "多费谓之侈。", "b": "《韩非子·解老》"}, {"t": "以侈自败者多矣。", "b": "司马光《训俭示康》"}, {"t": "淫侈之俗日日以长。", "b": "汉·贾谊《论积贮疏》"}, {"t": "自王侯以下莫不逾侈。", "b": "《后汉书·张衡传》"}], "words": [{"w": "侈服", "t": "华丽的衣服"}, {"w": "侈饰", "t": "奢华的服饰。"}]}, {"meaning": "过分;过度。", "cites": [{"t": "专淫逸侈靡,不顾国政。", "b": "《战国策·楚策》"}, {"t": "关市之征侈之。", "b": "《管子·大匡》。注:“谓过常也。”"}], "words": [{"w": "侈欲", "t": "过分的欲望"}, {"w": "侈务", "t": "过度的徭役"}, {"w": "侈言", "t": "夸大不实的言辞"}, {"w": "侈论", "t": "夸大不实的言论。"}]}, {"meaning": "夸大,吹牛。", "cites": [{"t": "莽为人侈口。", "b": "《汉书·王莽传》"}, {"t": "侈言无验,虽丽非经。", "b": "左思《三都赋序》"}], "words": [{"w": "侈言", "t": "夸大其辞"}, {"w": "侈口", "t": "夸口。"}]}, {"meaning": "放纵。", "cites": [{"t": "苟无恒心,放辟邪侈,无不为已。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "侈伪", "t": "放纵僭为"}, {"w": "侈意", "t": "放纵之心。"}]}, {"meaning": "扩大。", "cites": [{"t": "侈苑囿之大。", "b": "《淮南子·本经训》"}, {"t": "妇人以众多为侈也。", "b": "《公羊传·成公十年》"}, {"t": "以广侈吴王之心。", "b": "《国语·吴语》"}, {"t": "伯父秉德已侈大哉!", "b": "《国语·吴语》"}, {"t": "有节有侈。", "b": "《吕氏春秋·古乐》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1153wx','依','1','yī yǐ','亻','8','','[{"pinyin": "yī", "defs": [{"meaning": "(形声。从人,衣声。甲骨文字形。人在衣中。本义:靠着)。"}, {"meaning": "同本义。", "cites": [{"t": "依,倚也。", "b": "《说文》"}, {"t": "依,恃也。", "b": "《广雅》"}, {"t": "白日依山尽,黄河入海流。", "b": "王之涣《登鹳雀楼》"}, {"t": "依柱而笑。", "b": "《史记·刺客列传》"}, {"t": "空游无所依。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "极贫无所依。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "依山之榭", "t": "靠山建造的房屋"}, {"w": "依栖", "t": "依傍栖息"}, {"w": "依山傍水;依着电线杆;偎依", "t": "亲密地靠着"}, {"w": "依倚", "t": "倚靠;依傍"}, {"w": "依门卖笑", "t": "以色媚人。"}]}, {"meaning": "倚仗,仗恃,仰赖。", "cites": [{"t": "无依势作威,无依法以削。", "b": "《书·君陈》"}], "words": [{"w": "依仰", "t": "依赖仰仗"}, {"w": "依阻", "t": "凭借;仗恃"}, {"w": "依负", "t": "倚恃;依附"}, {"w": "依乘", "t": "凭借"}, {"w": "依毗", "t": "倚仗。"}]}, {"meaning": "依靠;托身。", "cites": [{"t": "必依水草而背众树。", "b": "《孙子·行军》"}, {"t": "勤勤嘱四邻,幸愿相依傍。", "b": "梅尧臣《汝ń贫女诗》"}, {"t": "今去依傍外祖母及舅氏姊妹。", "b": "《红楼梦》"}], "words": [{"w": "生死相依;无依无靠;唇齿相依;依傍门墙", "t": "依靠师父"}, {"w": "依仰", "t": "依靠;依赖"}, {"w": "依贴", "t": "依恋体贴"}, {"w": "依栖", "t": "依靠他人并寄居"}, {"w": "依怙", "t": "依靠;依赖"}, {"w": "依重", "t": "依靠;倚重"}, {"w": "依荷", "t": "依靠"}, {"w": "依接", "t": "依靠连接"}, {"w": "依诉", "t": "依靠诉说"}, {"w": "依缘", "t": "依靠,凭借。"}]}, {"meaning": "同意;允许。", "cites": [{"t": "有一事肯依,窦娥便死而无怨。", "b": "《元曲选·关汉卿·窦娥冤剧三》"}], "words": [{"w": "依心像意", "t": "称心如意"}, {"w": "依得", "t": "依允,依从"}, {"w": "依心", "t": "称心"}, {"w": "依信", "t": "信从;依赖"}, {"w": "依许", "t": "准许。"}]}, {"meaning": "遵照,根据。", "cites": [{"t": "乃拜宪车骑将军,金印紫绶,官属依司空。", "b": "《后汉书·窦融传》"}], "words": [{"w": "依科设仪", "t": "按照规定的格式举行仪式。"}]}, {"meaning": "爱。", "cites": [{"t": "思媚其妇,有依其士。", "b": "《诗·周颂》"}], "words": [{"w": "依人", "t": "与人亲近而不离群"}, {"w": "依迟", "t": "依依不舍的样子。"}]}, {"meaning": "依照,按照。", "cites": [{"t": "依乎天理。", "b": "《庄子·养生主》"}, {"t": "钦依都司。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "(yǐn)。藏匿。", "cites": [{"t": "乃逸,则知小人之依。", "b": "《书·无逸》。王引之云:“依,隐也,古音微与殷通,故依、隐同声。”"}, {"t": "知小人之依。", "b": ""}]}, {"meaning": "茂盛的样子。", "cites": [{"t": "依彼平林,有集维嫶。", "b": "《诗·小雅》。传:“茂木貌。”"}]}]}, {"pinyin": "yǐ", "defs": [{"meaning": "户牖间画有斧形的屏风。", "cites": [{"t": "天子设斧依于户牖之间。", "b": "《仪礼·觐礼》"}, {"t": "王位设黼依。", "b": "《周礼·春官·司几筵》"}, {"t": "居则设张容,负依而坐。", "b": "《荀子·正论》。杨倞注:“依,亦作扆,音同。”"}, {"t": "天子当依而立。", "b": "《礼记·曲礼下》。释文:“依,本又作扆。”"}, {"t": "天子负黼依。", "b": "《汉书·西域传赞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1154wx','卑','1','bēi','十','8','','[{"pinyin": "bēi", "defs": [{"meaning": "(椑之古字,本义是圆搕,一种酒器)。"}, {"meaning": "地位低微。", "cites": [{"t": "卑,庳也。", "b": "《广雅》"}, {"t": "文王卑服。", "b": "《书·无逸》"}, {"t": "人皆赴高,己独赴下卑也。", "b": "《管子·水地》"}, {"t": "天尊地卑。", "b": "《易·系辞》"}, {"t": "位卑则足羞。", "b": "唐·韩愈《师说》"}, {"t": "先帝不以臣卑鄙。", "b": "诸葛亮《出师表》"}], "words": [{"w": "卑弁", "t": "下级武职对上级的自称"}, {"w": "卑寒", "t": "谦词。谓位卑家贫"}, {"w": "卑陋", "t": "低矮简陋"}, {"w": "卑辱", "t": "卑微屈辱"}, {"w": "卑人", "t": "地位低下的人。"}]}, {"meaning": "地势低下。与“高”相对。", "cites": [{"t": "谓山盖卑。", "b": "《诗·小雅·正月》"}, {"t": "卑高已陈。", "b": "《礼记·乐记》"}, {"t": "闻长沙卑湿。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "卑小", "t": "矮小"}, {"w": "卑隘", "t": "低矮狭窄"}, {"w": "卑洼", "t": "低洼。"}]}, {"meaning": "衰微,衰弱。", "cites": [{"t": "王室其将卑乎?", "b": "《国语·周语》"}]}, {"meaning": "素质低下。", "cites": [{"t": "非天质之卑,则必不若余之专耳。", "b": "宋濂《送东阳马生序》"}]}, {"meaning": "谦恭。", "cites": [{"t": "卑礼厚币以招贤者。", "b": "《史记·魏世家》"}], "words": [{"w": "卑谨", "t": "谦卑恭敬"}, {"w": "卑顺", "t": "谦恭驯顺。"}]}, {"meaning": "轻视,小看。", "cites": [{"t": "何以卑我?", "b": "《国语·晋语四》"}, {"t": "吏之所卑,法之所尊也。", "b": "汉·晁错《论贵粟疏》"}], "words": [{"w": "卑侮王室", "t": "贱视并凌辱王室成员。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1155wx','的','1','de dí dì','白','8','','[{"pinyin": "de", "defs": [{"meaning": "用在两个数量词中间。"}, {"meaning": ",后面带补语。", "cites": [{"t": "那知进了园门,园子里已结坐的满满的了。", "b": "《老残游记》"}]}, {"meaning": "(de)。用在状语后,表示状语和中心词之间的修饰关系。"}]}, {"pinyin": "dí", "defs": [{"meaning": "确实;实在。", "cites": [{"t": "不因霜叶辞林去,的当山翁未觉秋。", "b": "秦观《淮海集》"}], "words": [{"w": "的对;的据", "t": "真凭实据"}, {"w": "的觉", "t": "果然;的确"}, {"w": "的是", "t": "的确是。"}]}]}, {"pinyin": "dì", "defs": [{"meaning": "(形声。本作“旳”,从日,勺声。本义:鲜明、明亮的样子)。"}, {"meaning": "鲜明的样子。", "cites": [{"t": "朱唇的其(语气词)若丹。", "b": "战国楚·宋玉《神女赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1156wx','迫','1','pò pǎi','辶','8','','[{"pinyin": "pò", "defs": [{"meaning": "(形声。从辵(chuò),白声。本义:逼近)。"}, {"meaning": "同本义。", "cites": [{"t": "迫,近也。", "b": "《说文》"}, {"t": "迫,逼也,近也。", "b": "《广韵》"}, {"t": "望崦嵫而勿迫。", "b": "《离骚》。注:“附也。”"}, {"t": "而侮所迫之国者,可亡也。", "b": "《韩非子·亡征》"}, {"t": "涉旬月,迫季冬。", "b": "司马迁《报任安书》"}, {"t": "时北兵已迫修门外。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "迫措", "t": "犹逼近。"}]}, {"meaning": "硬逼,逼迫。", "cites": [{"t": "贾家庄几为巡徼所陵迫死。", "b": "宋·文天祥《指南录后序》"}, {"t": "里胥迫我纳。", "b": "白居易《重赋》"}], "words": [{"w": "胁迫", "t": "威胁强迫"}, {"w": "强迫", "t": "施加压力使服从"}, {"w": "迫劫", "t": "逼迫"}, {"w": "迫蹙", "t": "逼迫强制"}, {"w": "迫阨", "t": "逼迫;胁迫"}, {"w": "迫弄", "t": "逼迫并戏耍"}, {"w": "迫拶", "t": "逼迫"}, {"w": "迫索", "t": "强迫索取"}, {"w": "迫胁", "t": "逼迫、威胁"}, {"w": "迫勒", "t": "强迫。"}]}, {"meaning": "催促。", "cites": [{"t": "迫生而下。", "b": "《吕氏春秋·贵生》"}, {"t": "迫孔悝于厕,强盟之。", "b": "《左传·哀公十五年》"}, {"t": "能事不受相促迫。", "b": "唐·杜甫《戏题画山水图歌》"}], "words": [{"w": "迫催", "t": "催逼,催促。"}]}, {"meaning": "紧迫;急迫。", "cites": [{"t": "迫而动。", "b": "《淮南子·精神》。注:“切也。”"}, {"t": "此迫矣!臣请入,与之同命。", "b": "《史记·项羽本纪》"}], "words": [{"w": "迫促", "t": "匆忙"}, {"w": "迫急", "t": "迫切"}, {"w": "迫划", "t": "紧急筹划"}, {"w": "迫遽", "t": "急促"}, {"w": "迫守", "t": "急切收捕"}, {"w": "迫究", "t": "紧逼追问"}, {"w": "迫亟", "t": "急促;急迫"}, {"w": "迫速", "t": "急迫"}, {"w": "迫猝", "t": "急迫;仓促。"}]}, {"meaning": "狭窄。", "cites": [{"t": "西州地势局迫。", "b": "《后汉书·窦融列传》"}], "words": [{"w": "迫隘", "t": "狭窄;险阻"}, {"w": "迫小", "t": "狭小"}, {"w": "迫隘", "t": "狭窄，险阻"}, {"w": "迫束", "t": "束缚,不得伸展"}, {"w": "迫迮", "t": "狭窄"}, {"w": "迫胁", "t": "迫窄;狭陋"}, {"w": "迫唶", "t": "狭窄。"}]}]}, {"pinyin": "pǎi", "defs": [{"meaning": "一种火炮", "words": [{"w": "迫击炮", "t": "用座钣承受后座力、发射尾翼弹的一种滑膛曲射炮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1157wx','质','1','zhì','贝','8','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从贝,斦(zhì)声。朱骏声认为“斦”是砧板。从贝,与财富有关。本义:抵押;以…作人质)。"}, {"meaning": "同本义。", "cites": [{"t": "质,以物相赘也。", "b": "《说文》。按,以钱受物曰赘,以物受钱曰质。"}, {"t": "于是为长安君约车百乘,质于齐,齐兵乃出。", "b": "《战国策·赵策》"}, {"t": "遂纳子为质。", "b": "《后汉书·班超传》"}, {"t": "犹质其首。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "质库", "t": "当铺"}, {"w": "质作", "t": "抵押其身,使服劳役"}, {"w": "质鬻", "t": "典押出卖"}, {"w": "质录", "t": "收押"}, {"w": "质卖", "t": "典押和出卖"}, {"w": "质债", "t": "抵债"}, {"w": "质当", "t": "典当;质押"}, {"w": "质肆", "t": "当铺。"}]}, {"meaning": "(jié)。问;诘问。", "cites": [{"t": "爰质所疑。", "b": "扬雄《太玄经》"}, {"t": "援疑质理。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "质之鬼神;质责", "t": "以正义质询责问"}, {"w": "质问", "t": "向人询问疑难的问题"}, {"w": "质让", "t": "诘问,谴责"}, {"w": "质辩", "t": "质疑辩论"}, {"w": "质论", "t": "质疑评论。"}]}, {"meaning": "双方对质,验证。", "cites": [{"t": "虽质君之前,臣不讳也。", "b": "《礼记·曲礼上》"}], "words": [{"w": "质验", "t": "验证;勘验"}, {"w": "质凭", "t": "证实"}, {"w": "质审", "t": "质对审讯。"}]}, {"meaning": "评断。", "cites": [{"t": "司会以岁之成质于天子。", "b": "《礼记·王制》"}], "words": [{"w": "质成", "t": "请人评断事情的是非"}, {"w": "质律", "t": "古代评定市价的一种文书。"}]}, {"meaning": "抵押品;人质。", "cites": [{"t": "故周郑交质。", "b": "《左传·隐公三年》"}, {"t": "以三公子为质。", "b": "《左传·昭公二十年》"}, {"t": "请以宝为质于子,以假子之邑粟。", "b": "《管子·山权数》"}, {"t": "必以长安君为质,兵乃出。", "b": "《战国策·赵策》"}], "words": [{"w": "质馆", "t": "安置人质的馆舍"}, {"w": "质布", "t": "质人向犯约者所收的罚金,称为“质布”"}, {"w": "质婆", "t": "作人质的妇女"}, {"w": "质留", "t": "扣留作为人质"}, {"w": "质宫", "t": "人质的居室"}, {"w": "质任", "t": "人质和任子。"}]}, {"meaning": "盟约。", "cites": [{"t": "黄池之役,先主与吴王有质。", "b": "《左传·哀公二十年》"}]}, {"meaning": "古代贸易用的券书。", "cites": [{"t": "并质共剂。", "b": "《后汉书》"}], "words": [{"w": "质剂", "t": "古代贸易的券契"}, {"w": "质要", "t": "古代买卖货物的凭证"}, {"w": "质契", "t": "契约,契据。"}]}, {"meaning": "箭靶。", "cites": [{"t": "是故质的张而弓矢至焉。", "b": "《荀子·劝学》"}, {"t": "骑而驰,而击方寸之质。", "b": "《器胜策》"}], "words": [{"w": "质的", "t": "射侯。箭靶。"}]}, {"meaning": "素质;本质;禀性。", "cites": [{"t": "太素者,质之始也。", "b": "《列子》"}, {"t": "若仆大质已亏缺矣。", "b": "汉·司马迁《报任安书》"}, {"t": "奈何以非金石之质,欲与草木而争荣?", "b": "王粲《登楼赋》"}], "words": [{"w": "质像", "t": "资质仪表"}, {"w": "质性", "t": "资质,本性。"}]}, {"meaning": "物质;事物。", "cites": [{"t": "气形光声,无逃质理。", "b": "《物理小识》"}]}, {"meaning": "形体。", "cites": [{"t": "骈门裸质。", "b": "《南齐书》"}], "words": [{"w": "质辞", "t": "仪表言辞"}, {"w": "质貌", "t": "形体相貌"}, {"w": "质干", "t": "躯体"}, {"w": "质象", "t": "形体"}, {"w": "质状", "t": "形状;体态。"}]}, {"meaning": "质地、底子。", "cites": [{"t": "黑质而白章。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "玉质而金色。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "砧板 。行斩刑时用的垫板。", "cites": [{"t": "君不如肉袒伏斧质请罪。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "解衣伏质。", "b": "《汉书·张周赵任申屠传》"}, {"t": "訢已解衣伏质。", "b": "《汉书·王訢传》"}]}, {"meaning": "信物;见面礼。", "cites": [{"t": "臣委质于狄之鼓。", "b": "《国语·晋语九》"}, {"t": "出疆必载质。", "b": "《孟子·滕文公下》"}, {"t": "惠王患之,乃令张仪佯去秦,厚币委质事楚。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "对象。", "cites": [{"t": "自夫子之死也,吾无以为质矣,吾无与言之矣。", "b": "《左传·徐无鬼》"}]}, {"meaning": "朴实、朴素。", "cites": [{"t": "以质信言,则见以为鄙。", "b": "《韩非子·难言》"}, {"t": "以求其质。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "质木", "t": "质朴无华"}, {"w": "质厚", "t": "朴实浑厚"}, {"w": "质讷", "t": "朴实厚道,不善言辞"}, {"w": "质简", "t": "质朴简易。"}]}, {"meaning": "信实;诚信。", "cites": [{"t": "楚子闻蛮子之乱也,与蛮子之无质也。", "b": "《左传·昭公十六年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1158wx','欣','1','xīn','欠','8','','[{"pinyin": "xīn", "defs": [{"meaning": "(形声。从欠,斤声。实与忻同字。本义:喜悦) 同本义。", "cites": [{"t": "欣,笑喜也。", "b": "《说文》。段注:“言部訢下曰:‘喜也。’义略同。”"}, {"t": "欣,乐也。", "b": "《尔雅》"}, {"t": "旨酒欣欣。", "b": "《诗·大雅·凫鷖》。传:“欣欣然乐也。”"}, {"t": "君欣欣兮乐康。", "b": "《楚辞·九歌·东皇太一》。注:“欣欣,喜貌。”"}, {"t": "天地欣合。", "b": "《史记·乐书》。注:“欣,喜也。”"}, {"t": "载欣载奔。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "欣惧", "t": "欣喜而惶恐"}, {"w": "欣赞", "t": "欣喜赞美"}, {"w": "欣欢", "t": "欣喜欢乐"}, {"w": "欣赖", "t": "欣喜仰赖。"}]}, {"meaning": "爱戴。", "cites": [{"t": "百姓欣而奉之,国可以固。", "b": "《国语·晋语二》"}], "words": [{"w": "欣戴", "t": "欣悦拥戴。"}]}, {"meaning": "悦服。", "cites": [{"t": "是以民能欣之。", "b": "《国语·晋语一》"}], "words": [{"w": "欣佩", "t": "欢欣,敬佩"}, {"w": "欣服", "t": "悦服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1159wx','征','1','zhēng','彳','8','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从彳(chì),正声。从彳,表示与行走有关。甲骨文从彳,从足。本义:到很远的地方去,远行)。"}, {"meaning": "同本义。", "cites": [{"t": "徴,正行也。从辵,正声。或从彳。", "b": "《说文》"}, {"t": "征,行也。", "b": "《尔雅》"}, {"t": "壮于趾征凶。", "b": "《易·大壮》"}, {"t": "而月斯征。", "b": "《诗·小雅·小宛》"}, {"t": "先王卜征五年。", "b": "《左传·襄公十三年》。注:“谓巡狩征行。”"}, {"t": "肃肃宵征,夙夜在公。", "b": "《诗·召南·小星》"}, {"t": "愿为市鞍马,从此替爷征。", "b": "古乐府《木兰词》"}, {"t": "孤蓬万里征。", "b": "唐·李白《送友人》"}], "words": [{"w": "征鼙", "t": "征战的军鼓"}, {"w": "征衣", "t": "行旅在在外的御寒衣服"}, {"w": "征客", "t": "游子。同征人"}, {"w": "征鸟", "t": "远飞的鸟"}, {"w": "征盖", "t": "远行的车"}, {"w": "征夫", "t": "远行的人;出征的士兵。"}]}, {"meaning": "征伐,发兵讨伐。", "cites": [{"t": "征者,上伐下也。", "b": "《孟子》"}, {"t": "奉辞伐罪曰征。", "b": "《书·允征》"}, {"t": "桓桓于征。", "b": "《诗·鲁颂·泮水》"}, {"t": "一曰征。", "b": "《周礼·太卜》。司农注:“谓征伐人也。”"}, {"t": "挟天子以征四方。", "b": "《资治通鉴》"}], "words": [{"w": "征诛", "t": "征讨诛戮"}, {"w": "征阵", "t": "战阵"}, {"w": "征讨", "t": "讨伐"}, {"w": "征略", "t": "征战略地"}, {"w": "征剿", "t": "犹征讨。"}]}, {"meaning": "争夺,争取。", "cites": [{"t": "不为征利。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "征收。", "cites": [{"t": "宣德间,宫中尚促织之戏,岁征民间。", "b": "《聊斋志异》"}], "words": [{"w": "征榷", "t": "征税与专卖"}, {"w": "征役", "t": "征税与劳役"}, {"w": "征缮", "t": "谓征收赋税,整顿武备"}, {"w": "征敛", "t": "亦作“征敛”。"}]}, {"meaning": "赋税。", "cites": [{"t": "有布缕之征,粟米之征。", "b": "《孟子·尽心下》"}], "words": [{"w": "征役", "t": "赋税与徭役。"}]}, {"meaning": "(会意。从微省、壬。行于微而闻达。本义:征召)。"}, {"meaning": "同本义。", "cites": [{"t": "徵,召也。", "b": "《说文》"}, {"t": "徵,召也。", "b": "《尔雅》"}, {"t": "以量度成贾而徵徴。", "b": "《周礼·司市》"}, {"t": "各掌其县之政令徵比。", "b": "《周礼·县正》"}, {"t": "徵唯所欲。", "b": "《仪礼·乡射礼》"}, {"t": "王使来徵聘。", "b": "《左传·宣公九年》"}, {"t": "发征期会。", "b": "《史记·货殖列传》"}, {"t": "征拜郎中。", "b": "《后汉书·张衡传》"}, {"t": "征拜尚书。", "b": ""}], "words": [{"w": "征引", "t": "征召引用"}, {"w": "征令", "t": "征召及施令"}, {"w": "征吏", "t": "谓召用佐吏"}, {"w": "征车", "t": "古代征召贤达使用的车子"}, {"w": "征守", "t": "谓天子征召守国的诸侯。"}]}, {"meaning": "求取;索取。", "cites": [{"t": "物贱之征贵。", "b": "《史记·货殖列传》"}, {"t": "贵之征贱。", "b": ""}, {"t": "岁征民间。", "b": "《聊斋志异·促织》"}, {"t": "会征促织。", "b": ""}], "words": [{"w": "征乞", "t": "求取"}, {"w": "征索", "t": "索取"}, {"w": "征须", "t": "求取"}, {"w": "征贿", "t": "求取贿赂"}, {"w": "征求", "t": "求索。"}]}, {"meaning": "追究;追问。", "cites": [{"t": "寡人是征。", "b": "《左传·僖公四年》"}]}, {"meaning": "证明;验证。", "cites": [{"t": "念用庶征。", "b": "《书·洪范》"}, {"t": "征为五声。", "b": "《左传·昭公元年》"}, {"t": "用牲,加书征之。", "b": "《左传·襄公二十六年》"}, {"t": "怪其无征。", "b": "《后汉书·张衡传》"}], "words": [{"w": "征验;征圣", "t": "验证于前圣的遗教"}, {"w": "征象", "t": "验证"}, {"w": "征效", "t": "效验。"}]}, {"meaning": "征兆;迹象。", "cites": [{"t": "明征定保。", "b": "《书·胤征》"}, {"t": "休征嘉应。", "b": "《汉书·平帝纪赞》"}, {"t": "候善恶之征。", "b": "《汉书·艺文志》"}, {"t": "征兆必报。", "b": "《汉书·儿宽传》"}, {"t": "观国之强弱贫富有征。", "b": "《荀子》"}, {"t": "征于色。", "b": "《孟子·告子下》"}], "words": [{"w": "征迹", "t": "迹象"}, {"w": "征怪", "t": "怪异的征兆"}, {"w": "征咎", "t": "灾祸的征兆"}, {"w": "征候", "t": "发生某种情况的迹象,征兆"}, {"w": "征效", "t": "征兆 “徵”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1160wx','往','1','wǎng','彳','8','','[{"pinyin": "wǎng", "defs": [{"meaning": "(会意。甲骨文字形,从止,从土。意为从这个地方走向目的地。本义:去,到…去)。"}, {"meaning": "同本义。", "cites": [{"t": "往,之也。", "b": "《说文》"}, {"t": "大夫有所往。", "b": "《礼记·玉藻》"}, {"t": "憧憧往来。", "b": "《易·咸》"}, {"t": "吾言既往矣。", "b": "《国语·晋语》"}, {"t": "往而不返。", "b": "《庄子·逍遥游》"}, {"t": "往见老聃。", "b": "《庄子·天道》"}, {"t": "跳往助之。", "b": "《列子·汤问》"}, {"t": "随其往。", "b": "晋·陶渊明《桃花源记》"}, {"t": "欣然前往。", "b": ""}, {"t": "子何恃而往。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "前往", "t": "前去;去"}, {"w": "往造", "t": "前去拜访"}, {"w": "往教", "t": "老师前往学生处施教"}, {"w": "往旋", "t": "往复回旋"}, {"w": "往蹇来连", "t": "往来皆难"}, {"w": "往人", "t": "派往的人"}, {"w": "往至", "t": "前往"}, {"w": "往程", "t": "去的路程"}, {"w": "往夫", "t": "一往无前的战士。"}]}, {"meaning": "彼此间来往。", "cites": [{"t": "往复一月间事,过城池已固。", "b": "《三侠五义》"}], "words": [{"w": "往回", "t": "来回;往返"}, {"w": "往往来来", "t": "多次往返。"}]}, {"meaning": "亡去。", "cites": [{"t": "无以蓄之则往而不可止也。", "b": "《管子·权修》。注:“谓亡去也。”"}], "words": [{"w": "往化", "t": "死亡。"}]}, {"meaning": "给予,送。", "cites": [{"t": "愧彼赠我厚,惭此往物轻。", "b": "泰嘉《留郡赠妇诗三首》"}]}, {"meaning": "归向。", "cites": [{"t": "执大象,天下往。", "b": "《老子》"}]}, {"meaning": "昔时;过去。", "cites": [{"t": "不慕往。", "b": "《荀子·解蔽》。注:“古昔也。”"}, {"t": "往哲是与。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "往闻庸蜀之南。", "b": "唐·柳宗元《柳河东集》"}, {"t": "见往事耳。", "b": "《资治通鉴·汉纪》"}, {"t": "叩以往事。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "往日无冤,近日无仇", "t": "俗语。从未有过冤仇"}, {"w": "往哲", "t": "古代的哲人"}, {"w": "往时", "t": "昔时"}, {"w": "往代", "t": "前代"}, {"w": "往岁", "t": "往年"}, {"w": "往例", "t": "先例"}, {"w": "往则", "t": "往昔的法则。"}]}, {"meaning": "死者。", "cites": [{"t": "送往事居。", "b": "《左传·僖公九年》。杜预注:“往,死者。居,生者。”"}]}, {"meaning": "后;以后。", "cites": [{"t": "不嫁义郎体,其往欲何云?", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "外,超过某种限度或范围。", "cites": [{"t": "阳山以往,皆北假也。", "b": "《水经注·河水》"}]}, {"meaning": "同“望”。表示动作行为的方向,相当于“朝”、“向”。", "cites": [{"t": "叉开五指往店主人脸上只一掌,把那店主人打了踉跄。", "b": "《水浒传》"}], "words": [{"w": "往虎口里探头", "t": "俗语。指冒失、危险的举动"}, {"w": "往高枝儿上飞", "t": "借指依附上层人物,也有向上爬之意。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1161wx','爬','1','pá','爪','8','','[{"pinyin": "pá", "defs": [{"meaning": "(形声。从爪,巴声。爪,手爪。本义:搔,爬梳)。"}, {"meaning": "同本义。", "cites": [{"t": "爬,搔也。", "b": "《广韵》"}, {"t": "怯烦类决痈,惬兴剧爬疥。", "b": "韩愈等《雨中寄孟刑部几道联句》"}, {"t": "支分闲事了,爬背向阳眠。", "b": "白居易《自咏老身示诸家属》"}], "words": [{"w": "爬挲", "t": "爬搔,摩挲"}, {"w": "爬栉", "t": "梳理,整理。同爬梳"}, {"w": "爬耳搔腮", "t": "急切无奈貌"}, {"w": "爬拉", "t": "频频拨饭菜入口。"}]}, {"meaning": "爬行,匍匐。躯体贴地(如虫、蛇、龟)缓慢向前行。", "cites": [{"t": "爬沙脚手钝,谁使女解缘青冥。", "b": "韩愈《月蚀诗效玉川子作》"}], "words": [{"w": "爬蹉", "t": "来回爬动"}, {"w": "爬沙", "t": "缓慢地爬动"}, {"w": "爬坑缸弗上", "t": "屎尿失控,来不及上厕所;离死不远"}, {"w": "爬滩弗动", "t": "趴在地上,无法走动。"}]}, {"meaning": "攀登。", "cites": [{"t": "他们为了出风头,向上爬,却把我们踩在脚底下!", "b": "《星火》1979年第二期"}], "words": [{"w": "爬树;爬上高枝儿", "t": "依附地位高的人"}, {"w": "爬得越高,跌得越惨", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1162wx','彼','1','bǐ','彳','8','','[{"pinyin": "bǐ", "defs": [{"meaning": "(形声。从彳,皮声。“彳”(chì)。本义:流行、传播,施加)。"}, {"meaning": "那,与“此”相对。", "cites": [{"t": "彼,对此称彼也。", "b": "《玉篇》"}, {"t": "逝将去女,适彼乐土。", "b": "《诗·魏风·硕鼠》"}, {"t": "彼君子兮,不素食兮。", "b": "《诗·魏风·伐檀》"}, {"t": "此土延续石耳。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "彼此腾倒着做", "t": "彼此交换。骂西门庆与书童有染,而书童又与李瓶儿有染"}, {"w": "彼苍", "t": "指天"}, {"w": "此起彼伏;彼人", "t": "那人。"}]}, {"meaning": "另一个事物。", "cites": [{"t": "知彼知己,百战不殆。", "b": "《孙子·谋攻》"}], "words": [{"w": "由此及彼", "t": ""}]}, {"meaning": "他,他们。", "cites": [{"t": "彼与彼年相若也。", "b": "唐·韩愈《师说》"}, {"t": "幸而杀彼,甚善!", "b": "唐·柳宗元《童区寄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1163wx','径','1','jīng jìng','彳','8','','[{"pinyin": "jīng", "defs": [{"meaning": "经过,行经。", "cites": [{"t": "径,过也。", "b": "《广雅》"}, {"t": "夜径泽中。", "b": "《汉书·高帝纪》。按,行也。"}], "words": [{"w": "径历", "t": "经过"}, {"w": "径复", "t": "往返,迂回曲折。"}]}]}, {"pinyin": "jìng", "defs": [{"meaning": "(形声。从彳(chì),表示与道路有关,巠声。本义:步行小路)。"}, {"meaning": "同本义。", "cites": [{"t": "径,步道也。", "b": "《说文》"}, {"t": "径,小道也。", "b": "《字林》"}, {"t": "艮为径路。", "b": "《易·说卦》"}, {"t": "审端径术。", "b": "《礼记·月令》"}, {"t": "送丧不由径。", "b": "《礼记·曲礼》"}, {"t": "行不由径。", "b": "《论语》"}, {"t": "夫逃虚空者,藜藿柱乎鼪鼬之径。", "b": "《庄子·徐无鬼》"}, {"t": "夫惟捷径以窘步。", "b": "《离骚》"}, {"t": "三径就荒。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "野径云俱黑。", "b": "唐·杜甫《春夜喜雨》"}], "words": [{"w": "径术", "t": "径路与沟洫"}, {"w": "径路", "t": "小路"}, {"w": "径逾", "t": "本意是逾越堤渠而走。引申为不走正道"}, {"w": "径行", "t": "小路与大道"}, {"w": "径界", "t": "小路"}, {"w": "径畛", "t": "田间道路。"}]}, {"meaning": "泛指道路。", "cites": [{"t": "塞徯径。", "b": "《礼记·月令》。注:“徯径,禽兽之道也。”"}, {"t": "皋兰被径兮路斯渐。", "b": "《楚辞·招魂》"}], "words": [{"w": "径要", "t": "必经之要道;要领,精义。"}]}, {"meaning": "直径。", "cites": [{"t": "员径八尺。", "b": "《后汉书·张衡传》"}, {"t": "径寸之木。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "径中", "t": "指中径,内经"}, {"w": "径寸", "t": "圆的直径为一寸"}, {"w": "径轮", "t": "南北的长度,直径"}, {"w": "径寸心", "t": "寸心。心在胸中占径寸之地,故称。"}]}, {"meaning": "径直;直接。", "cites": [{"t": "肃径迎之。", "b": "《资治通鉴》"}, {"t": "一狼径去。", "b": "《聊斋志异·狼三则》"}, {"t": "径造袁所。", "b": "清·梁启超《谭嗣同传》"}, {"t": "径造庐。(一直上门来。径,一直,径直。造,到,往。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "径捷", "t": "直接,便当"}, {"w": "径启", "t": "直接了当地陈述、启禀"}, {"w": "径取", "t": "直接出兵夺取"}, {"w": "径行", "t": "直行,任性而行。"}]}, {"meaning": "特地,特意。", "cites": [{"t": "径差潘美…前来聘请赴京授职。", "b": "罗贯中《风云会》"}]}, {"meaning": "即,就。", "cites": [{"t": "不过一斗,径醉矣。", "b": "《史记·滑稽列传》"}]}, {"meaning": "取道。", "cites": [{"t": "夜径泽中。", "b": "《史记·高祖本纪》"}]}, {"meaning": "经过。", "cites": [{"t": "昔赵衰以壶飱从,径,馁而弗食。", "b": "《左传·僖公二十五年》"}, {"t": "河水南径北屈县故城西。", "b": "郦道元《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1164wx','所','1','suǒ','户','8','','[{"pinyin": "suǒ", "defs": [{"meaning": "(形声。从斤,户声。斤,斧子。(hǔ)本义:伐木声)。"}, {"meaning": "“所”假借为“处”。处所;地方。", "cites": [{"t": "有截其所。", "b": "《诗·商颂·殷武》"}, {"t": "不可不为择所而后错之。", "b": "《荀子·王霸》"}, {"t": "必于无人之所。", "b": "《吕氏春秋·达郁》"}, {"t": "僻远悠闲之所。", "b": "《吕氏春秋·谨听》"}, {"t": "不如早为之所。", "b": "《左传·隐公元年》"}, {"t": "持童抵主人所,愈束缚牢甚。", "b": "唐·柳宗元《童区寄传》"}, {"t": "成反复自念,得无教我猎虫所耶?", "b": "《聊斋志异·促织》"}, {"t": "汝生于浙而葬于斯,离吾乡七百余里矣,当时虽觭梦幻想,宁知此为归骨所耶?", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "哨所;寓所;诊所;交易所;看守所;托儿所;招待所; 收容所;诊疗所;观察所;指挥所;各得其所", "t": ""}]}, {"meaning": "地方。", "cites": [{"t": "虽众,无所用之。", "b": "《左传·僖公四年》"}]}, {"meaning": "进行科学研究的机构 。如:物理所;农民问题研究所。又指机关或其他机构的名称。如:派出所;招待所;指挥所。"}, {"meaning": "着落;结果。", "cites": [{"t": "勤而无所,必有悖心。", "b": "《左传·僖公三十二年》"}, {"t": "今也天下之人怨恶其君,视之如寇仇,名之为独夫,固其所也。", "b": "清·黄宗羲《原君》"}]}, {"meaning": "表示结构。"}, {"meaning": "与后面的动词结合,构成名词性结构。", "cites": [{"t": "生,亦我所欲也,义,亦我所欲也。", "b": "《孟子·告子上》"}, {"t": "二贵酋名曰馆伴,夜则以兵围所寓舍,而予不得归矣。", "b": "宋·文天祥《指南录·后序》"}, {"t": "然则王之所大欲可知矣已:欲辟土地,朝秦楚莅中国而抚四夷也。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "闻所未闻;各尽所能", "t": ""}]}, {"meaning": "用在作主谓结构的谓词前,相当于“之”、“的”。", "cites": [{"t": "各因其土地所宜,人民所多少而纳职焉。", "b": "《史记》"}]}, {"meaning": "用作宾语提前的标志,多与“唯”字配合使用,相当于“是”。", "cites": [{"t": "臣唯命所试。", "b": "《列子》"}]}, {"meaning": "与“为”呼应,构成“为…所…”句式,表示被动。", "cites": [{"t": "其后楚目以削,数十年,竟为秦所灭。", "b": "《史记·屈原贾生列传》"}, {"t": "巨是凡人,偏在远郡,行将为人所并。", "b": "《资治通鉴》"}, {"t": "为国者无使为积威之所劫哉。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "为好奇心所驱使;为实践所证明", "t": ""}]}, {"meaning": "与介词“从”“由”“自”结合,组成所字结构,表示与动作有关的地方、原因、对象等。", "cites": [{"t": "其剑自舟中坠于水,遽契其舟,曰“是吾剑之所从坠”。", "b": "《吕氏春秋·察今》"}, {"t": "是时以大中丞抚吴者为魏之私人,周公之遗所由使也。", "b": "明·张溥《五人墓碑记》"}, {"t": "抚军不忘所自,无何,宰以卓异闻。", "b": "《聊斋志异·促织》"}]}, {"meaning": "和介词“以”组成“所以”这一短语,根据“以”的不同用法与具体语言环境,有不同的意思。", "cites": [{"t": "盏之所以距子者,吾不言。(用什么方法)", "b": "《墨子·公输》"}, {"t": "先王之所以为法者,人也。", "b": "《吕氏春秋·察今》"}, {"t": "此殆天所以资将军,将军邮局有意乎?", "b": "《三国志·诸葛亮传》"}, {"t": "亲贤臣,远小人,此先汉所以兴隆也。", "b": "诸葛亮《出师表》"}]}, {"meaning": "用于山、岛等物,相当于“座”。", "cites": [{"t": "百济国西南海中有大岛十五所。", "b": "《括地志》"}]}, {"meaning": "用于建筑物。", "cites": [{"t": "离宫别馆三十六所。", "b": "班固《西都赋》"}]}, {"meaning": "尚,还。", "cites": [{"t": "江陵去扬州,三千三百里。已行一千三,所有二千在。", "b": "《乐府诗集》"}]}, {"meaning": "大约 。用在数量词后面,表示大概的数目。", "cites": [{"t": "父去里所,复还。", "b": "《史记·留侯世家》"}, {"t": "从弟子女十人所。", "b": "《史记·滑稽列传》"}, {"t": "从弟子女十人所,皆衣缯单衣,立大巫后。", "b": "《西门豹治邺》"}]}, {"meaning": "表示疑问,相当于“何”、“什么”。", "cites": [{"t": "问帝崩所病,立者谁子,年几岁。", "b": "《汉书》"}]}, {"meaning": "宜,适宜的,为其所需的。", "cites": [{"t": "交易而退,各得其所。", "b": "《易·系辞下》"}]}, {"meaning": "许多的,多种的。", "cites": [{"t": "收拾得所事儿温柔,妆点得诸余里颗恰。", "b": "《南吕·一枝花》"}]}, {"meaning": "可以的。", "cites": [{"t": "必欲争天下,非信无所与计事者。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1165wx','舍','1','shě shè','舌','8','','[{"pinyin": "shě", "defs": [{"meaning": "放在一边;丢开。", "cites": [{"t": "捨,释也。从手,舍声。", "b": "《说文》"}, {"t": "捨,置也。", "b": "《广雅》"}, {"t": "舍车而徒。", "b": "《易·贲》"}], "words": [{"w": "舍手", "t": "放开手;放下手"}, {"w": "舍置", "t": "丢开"}, {"w": "舍脸", "t": "沉下脸。"}]}, {"meaning": "放弃;舍弃。", "cites": [{"t": "万物捨此而求生。", "b": "《老子》注经传多以舍为之"}, {"t": "不如舍。", "b": "《易·屯》"}, {"t": "舍命不渝。", "b": "《诗·郑风·羔裘》"}, {"t": "子在川上曰:逝者如斯夫,不舍昼夜。", "b": "《论语·子罕》"}, {"t": "求则得之,舍者失之。", "b": "《孟子·告子上》"}, {"t": "管仲之取舍,非周公旦未可知也。", "b": "《韩非子·难二》"}, {"t": "而操舍鞍马,仗舟楫,与吴越争衡。", "b": "《资治通鉴》"}, {"t": "舍鱼而取熊掌者也。", "b": "《孟子·告子上》"}], "words": [{"w": "舍己成人", "t": "牺牲自己利益,成全别人"}, {"w": "舍却", "t": "抛开"}, {"w": "舍实求虚", "t": "放弃实在的东西,而去追求虚无缥缈的所在"}, {"w": "舍拼", "t": "舍弃;不顾一切干"}, {"w": "舍筏", "t": "舍弃渡人的船筏"}, {"w": "舍业", "t": "放弃学业;舍弃产业"}, {"w": "舍己芸人", "t": "舍弃自己的田地,去耕耘别人的田地。比喻荒废自己本分内的工作而替他人做事。"}]}, {"meaning": "废止、停止。", "cites": [{"t": "耕者少舍。", "b": "《礼记·月令》。注:“止也。”"}, {"t": "舍我穑事。", "b": "《书·汤誓》。释文:“废也。”"}, {"t": "舍药物可也。", "b": "《左传·昭公九年》。服注:“止也。”"}, {"t": "驽马十驾,功在不舍。", "b": "《荀子·劝学》"}], "words": [{"w": "舍业", "t": "停止学习。"}]}, {"meaning": "布施,施舍。", "cites": [{"t": "我听见人说,就是中相公时,也不是你的文章,还是宗师看见你老,不过意,舍与你的。", "b": "《儒林外史》"}], "words": [{"w": "舍个数", "t": "在神佛面前许个愿"}, {"w": "舍贫", "t": "接济穷人"}, {"w": "舍宅", "t": "施舍住宅作寺院"}, {"w": "舍施", "t": "施舍。"}]}, {"meaning": "免罪或免罚;释放。", "cites": [{"t": "忧忘其身,内忘其亲,上忘其君,是刑法之所不舍也,圣王之所不畜也。", "b": "《荀子·荣辱》"}, {"t": "王贤其母,说其义,即舍田子罪。", "b": "《韩诗外传·卷九》"}, {"t": "夫人请之,吾舍之也。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "舍禁", "t": "解除封山泽的禁令"}, {"w": "舍纵", "t": "宽赦,放纵"}, {"w": "舍眼", "t": "睁眼;抬眼。"}]}, {"meaning": "发,发射。", "cites": [{"t": "不失其驰,舍矢如破。", "b": "《诗·小雅·车攻》"}], "words": [{"w": "舍拔", "t": "发箭"}, {"w": "舍放", "t": "发射,放射。"}]}]}, {"pinyin": "shè", "defs": [{"meaning": "(象形。小篆字形,上端象屋顶,下端象建筑物的基础。中间是客舍招徕顾客的幌子。本义:客舍)。"}, {"meaning": "同本义。", "cites": [{"t": "舍,市居曰舍。", "b": "《说文》。按,客店也。周礼之庐也,路室也,候馆也,皆是。"}, {"t": "天子赐舍。", "b": "《仪礼·觐礼》。注:“犹致馆也。”"}, {"t": "夫子休就舍。", "b": "《庄子·说剑》"}, {"t": "子闻之也,舍馆定,然后求见长者乎?", "b": "《孟子·离娄上》"}, {"t": "至舍,四支僵不能动。", "b": "明·宋濂《送东阳马生序》"}, {"t": "夜则以兵围所寓舍。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "旅舍", "t": "旅馆"}, {"w": "舍馆", "t": "住所;客舍"}, {"w": "舍长", "t": "守护客馆的负责人。"}]}, {"meaning": "房屋(住宅)。", "cites": [{"t": "将适舍。—《礼记·曲礼》。注:“主人家也。”", "b": ""}, {"t": "舍之上舍。", "b": "《战国策·齐策》。注:“甲第也。”"}, {"t": "神归其舍。", "b": "《鬼谷了·本经阴符》"}, {"t": "舍南舍北皆春水。", "b": "《杜甫《客至》"}, {"t": "荆人弗知,循表而夜涉,溺死者千有余人,军惊而怀都舍。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "庐舍", "t": "简陋的房屋"}, {"w": "茅舍", "t": "茅屋"}, {"w": "舍园", "t": "宅内庭院"}, {"w": "舍中", "t": "家中"}, {"w": "宿舍;茅舍;牛舍;校舍;舍匿", "t": "用房子藏匿。即“窝藏”。"}]}, {"meaning": "营寨;营房。", "cites": [{"t": "于是徙舍而走平陵。", "b": "《孙膑兵法·擒庞涓》"}]}, {"meaning": "中国古代行军以三十里为一舍。", "cites": [{"t": "微楚之惠不及此,退三舍避之,所以报也。", "b": "《左传·僖公二十三年》。杜预注:“一舍,三十里。”"}]}, {"meaning": "谦辞,用于对别人称自己的家或辈分低、年纪小的亲属。", "cites": [{"t": "屈到舍下暂住,细细请教何如?", "b": "《长生殿·弹词》"}], "words": [{"w": "舍弟", "t": "对别人谦称自己的弟弟"}, {"w": "舍妹", "t": "对别人谦称自己的妹妹"}, {"w": "舍下", "t": "谦称自己的居室。"}]}, {"meaning": "置;安置。", "cites": [{"t": "舍相如广成传舍。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "唐浮图慧褒始舍于其址。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "舍匿", "t": "窝藏"}, {"w": "舍藏", "t": "窝藏。"}]}, {"meaning": "住宿。", "cites": [{"t": "夫子出于山,舍于故人之家。", "b": "《庄子·山木》"}], "words": [{"w": "舍次", "t": "临时住宿"}, {"w": "舍止", "t": "停驻,居留。"}]}, {"meaning": "休息;止息。", "cites": [{"t": "逝者如斯夫,不舍昼夜。", "b": "《论语·子罕》"}]}, {"meaning": "安排住宿。", "cites": [{"t": "少间白至,乘骏马如龙,生另舍舍之。", "b": "《聊斋志异·白于玉》"}]}, {"meaning": "宿营。", "cites": [{"t": "凡师一宿为“舍”,再宿为“信”,过信为“次”。", "b": "《左传·庄公三年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1166wx','金','1','jīn','金','8','','[{"pinyin": "jīn", "defs": [{"meaning": "(会意。金文字形。从人(表示覆盖),从土,从二。从“土”,表示藏在地下;从“二”,表示藏在地下的矿物。本义:金属)。"}, {"meaning": "金属的通称或金属总名。", "cites": [{"t": "金,五色金也。黄为之长。久埋不生衣,百錬不轻,从革不违,西方之行,生于土,从土左右。注:象金在土中形。", "b": "《说文》"}, {"t": "西南之美者,有华山之金石焉。", "b": "《尔雅·释地》"}, {"t": "系于金柅。", "b": "《易·妒》"}, {"t": "惟金三品。", "b": "《书·禹贡》。注:“铜三色也。”"}, {"t": "项掣金锁。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "五金", "t": "指金、银、铜、铁、锡,泛指金属"}, {"w": "白金", "t": "铂的通称;古代指银子"}, {"w": "金背", "t": "镜子"}, {"w": "金钥", "t": "门销或金属门环、门闩"}, {"w": "金荷", "t": "金属制成的荷叶状独台"}, {"w": "金铺", "t": "本指门上衔接门环部分的带有虎头等花纹的装饰物,亦指门环"}, {"w": "金钟", "t": "金属酒杯。"}]}, {"meaning": "金属的制品,可省称为金。"}, {"meaning": "刀、剑、箭等兵器。", "cites": [{"t": "金就砺则利。", "b": "《荀子·劝学》"}], "words": [{"w": "金吾", "t": "手执的铜制仪仗棒"}, {"w": "金革;金翅", "t": "兵舰名"}, {"w": "金猊", "t": "用金属铸成狻猊状的香炉"}, {"w": "金钩", "t": "刀名"}, {"w": "金创,金伤", "t": "为兵器所创的伤痕。"}]}, {"meaning": "犁铧头。", "cites": [{"t": "耜广五寸,二耜为耦。", "b": "《周礼》"}]}, {"meaning": "钏、镯一类妆饰品。", "cites": [{"t": "金银华美之服。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "金步摇", "t": "女子的首饰名"}, {"w": "金粉", "t": "妇女妆饰用的花钿和铅粉"}, {"w": "金雀", "t": "妇女装饰用的头钗。"}]}, {"meaning": "化学元素名。金子  一种延性展性非常好的黄色三价和一价金属元素,产状主要为独立存在的自然金,但也存在于如针碲金银矿或叶碲矿等少数矿物中;大多数化学品对它不起作用,但遇到氯气和王水会受浸蚀;为增加硬度或改变颜色供商业上应用(如金币、首饰、金牙)而加入铜、银、锌、镉及其它金属熔成合金。", "cites": [{"t": "得遗金。", "b": "《后汉书·列女传》"}, {"t": "指金于野。", "b": ""}, {"t": "玉质而金色。", "b": "明·刘基《卖柑者言》"}, {"t": "金玉其外。", "b": ""}], "words": [{"w": "赤金", "t": "纯金"}, {"w": "金篦儿", "t": "一种篦子状的金首饰"}, {"w": "金钗客", "t": "妓女的讳称"}, {"w": "金绳", "t": "古代封禅仪式中用的金线"}, {"w": "金赀", "t": "金银财宝。"}]}, {"meaning": "钱财;货币。", "cites": [{"t": "金五百斤。", "b": "《战国策·齐策四》"}, {"t": "所赐金帛。", "b": "汉·刘向《列女传》"}, {"t": "橐金数千。", "b": "清·张廷玉《明史》"}, {"t": "输不必金。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "金粟", "t": "钱与米"}, {"w": "金罚", "t": "以金钱赎罪的处罚法"}, {"w": "金选", "t": "古代用来赎罪的罚金。也称“金铢”"}, {"w": "金财", "t": "金钱财货。"}]}, {"meaning": "星名。金星的简称。", "cites": [{"t": "金、水二星,行速而不经天。", "b": "《隋书·天文志》"}]}, {"meaning": "朝代名 。公元1115年—1234年,共历九帝,统治中国北部120年。由女真族完颜部领袖阿骨打创建,建都会宁(今黑龙江省阿城南),先后迁都中都(今北京)、开封等地,后在蒙古和宋的联合进攻下灭亡。"}, {"meaning": "古州名 。治所在今陕西省安康县。"}, {"meaning": "古代货币单位。", "cites": [{"t": "请献十金。", "b": "《墨子·公输》"}, {"t": "购子头千金。", "b": "晋·干宝《搜神记》"}, {"t": "易之以写金。", "b": "明·刘基《郁离子·千里马篇》"}]}, {"meaning": "金黄色,亚麻色,尤用指头发。", "cites": [{"t": "浮光跃金。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "青项金翅。", "b": "《聊斋志异·促织》"}], "words": [{"w": "金象", "t": "金色本相"}, {"w": "金缕", "t": "金色丝线"}, {"w": "金兽", "t": "门环上的金色衔环"}, {"w": "金蚕", "t": "金色的蚕"}, {"w": "金蛇", "t": "金色的小蛇"}, {"w": "金蛾", "t": "金色的蛾形图案"}, {"w": "金凤", "t": "金色的凤凰。"}]}, {"meaning": "比喻声音美妙。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1167wx','刹','1','chà shā','刂','8','','[{"pinyin": "chà", "defs": [{"meaning": "(形声,从刀,杀声。梵语刹多罗的省称。本义:土或土田,国土)。"}]}, {"pinyin": "shā", "defs": [{"meaning": "", "words": [{"w": "急刹车", "t": "或作急煞车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1168wx','命','1','mìng','口','8','','[{"pinyin": "mìng", "defs": [{"meaning": "(会意。从口从令。表示用口发布命令。本义:指派;发号)。"}, {"meaning": "同本义。", "cites": [{"t": "命,使也。", "b": "《说文》。朱骏声按:“在事为令,在言为命,散文则通,对文则别。令当训使也,命当训发号也。”"}, {"t": "出君下臣名曰命。", "b": "汉·蔡邕《独断》"}, {"t": "语下命者,制令也。", "b": "《贾子·礼容》"}, {"t": "凡尊者之言曰命。", "b": "《文选·闲居赋序》注"}, {"t": "维君子命。", "b": "《诗·大雅·卷阿》"}, {"t": "某固辞不得命。", "b": "《仪礼·燕礼》"}, {"t": "命田舍东郊。", "b": "《吕氏春秋·孟春纪》。注:“命,令也。”"}, {"t": "命夸娥氏二子负二山。", "b": "《列子·汤问》"}, {"t": "令将军诚能命猛将统兵数万。", "b": "《资治通鉴·赤壁之战》"}, {"t": "命妪煮芋。", "b": "清·周容《芋老人传》"}, {"t": "遂命酒,使快弹数曲。", "b": "白居易《琵琶行序》"}], "words": [{"w": "命酌", "t": "使充酌酒者"}, {"w": "命席", "t": "下令安排座位"}, {"w": "命酒", "t": "命人置酒"}, {"w": "命乐", "t": "命人奏乐"}, {"w": "命官", "t": "任命官吏"}, {"w": "命材", "t": "任用有才干的人"}, {"w": "命事", "t": "安排职事"}, {"w": "命使", "t": "任命使者"}, {"w": "命将", "t": "任命将领"}, {"w": "命相", "t": "命令三公辅政、行事"}, {"w": "命讨", "t": "下令讨伐"}, {"w": "命教", "t": "命令。"}]}, {"meaning": "取名;命名。", "cites": [{"t": "今之命师者。", "b": "唐·柳宗元《柳河东集》"}, {"t": "命曰琵琶行。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "命名", "t": "给予名称,定名"}, {"w": "命姓", "t": "赐姓;建姓"}, {"w": "命爵", "t": "赐给爵位、官职。"}]}, {"meaning": "动,用。", "cites": [{"t": "欣然命笔。", "b": "毛泽东《送瘟神二首序》"}], "words": [{"w": "命旅", "t": "出师,誓师,启程"}, {"w": "命笔", "t": "动笔,使笔"}, {"w": "命管", "t": "命笔。"}]}, {"meaning": "在神前誓约,结盟。", "cites": [{"t": "凡我同盟,毋蕴年,…或间兹命,司慎、司盟、名川、群神、群祀、先王、先公、七姓十二国之祖,明神殛之。", "b": "《左传·襄公十一年》"}]}, {"meaning": "命令;政令;教令。", "cites": [{"t": "既不能令,又不受命。", "b": "《孟子·离娄上》"}, {"t": "奉命于危难之间。", "b": "诸葛亮《出师表》"}, {"t": "以王命聚之。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "何命焉为。", "b": "《墨子·公翰》"}, {"t": "大君有命。", "b": "《易·师》"}, {"t": "掌王后之命。", "b": "《周礼·内小臣》"}, {"t": "凡诸侯有命告则书。", "b": "《左传·隐公十一年》"}, {"t": "喜而从命。", "b": "《资治通鉴》"}, {"t": "西市待命。", "b": "清·方苞《狱中杂记》"}, {"t": "使于四方,不辱君命。", "b": "《论语》"}], "words": [{"w": "遵命", "t": "敬辞。表示依照对方的嘱咐"}, {"w": "命戒", "t": "命令与禁令"}, {"w": "命词", "t": "诏书;也指起草诏书"}, {"w": "命诏", "t": "君王的命令。"}]}, {"meaning": "命运,天命。", "cites": [{"t": "岂吾相不当侯邪?且固命也?", "b": "《史记·李将军列传》"}, {"t": "人生有命。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "命道", "t": "命运"}, {"w": "命毒", "t": "命苦,命运不好"}, {"w": "命快", "t": "命运好"}, {"w": "好命;苦命;算命;命分", "t": "命运;命中给的天分;禀赋。"}]}, {"meaning": "性命,寿命。", "cites": [{"t": "命悬于遂。", "b": "《史记·平原君虞卿列传》"}, {"t": "命如南山石。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "命绝今日。", "b": ""}, {"t": "皆关民命。", "b": "《聊斋志异·促织》"}, {"t": "命如南山石,四体康且直。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "彼不能以二人之命易其官。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "逃命;短命;命犯", "t": "有杀人罪的罪犯。"}]}, {"meaning": "帝王按等级官职赐给臣下的东西。", "cites": [{"t": "赐晋惠公命。(此指服装)", "b": "《国语》"}], "words": [{"w": "命士", "t": "命夫。受有爵命的人"}, {"w": "命禾", "t": "天子所赐的嘉禾"}, {"w": "命民", "t": "受帝王赐爵的平民"}, {"w": "命圭", "t": "天子赐的玉圭。"}]}, {"meaning": "声誉。", "cites": [{"t": "时周之命。", "b": "《诗·周颂·赉》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1169wx','肴','1','yáo','月','8','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。小篆字形。从肉,爻(yáo)声。本义:做熟的鱼肉等) 同本义。", "cites": [{"t": "肴,啖也。凡熟馈可啖之肉,折俎,豆实皆是。", "b": "《说文》"}, {"t": "肴,肉也。", "b": "《广雅》"}, {"t": "肴羞未通。", "b": "《楚辞·招魂》。注:“鱼肉为肴。”"}, {"t": "蕙肴蒸兮蘭藉。", "b": "《楚辞·东皇太一》。注:“用蕙草以蒸肉也。”"}, {"t": "山肴野薮。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "肴止于脯、醢、菜羹(肴,下酒的菜)。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "肴蔌", "t": "鱼肉与菜蔬"}, {"w": "肴核", "t": "肉类和果类食品"}, {"w": "肴俎", "t": "肉食"}, {"w": "肴品", "t": "荤菜;佳肴"}, {"w": "肴俎", "t": "盛菜肴的器皿"}, {"w": "肴羞", "t": "美味的菜肴"}, {"w": "肴酒", "t": "酒肴"}, {"w": "肴菜", "t": "菜肴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1170wx','斧','1','fǔ','斤','8','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从斤(斧头),父声。本义:斧子,伐木工具)。"}, {"meaning": "同本义。", "cites": [{"t": "斧,斫也。", "b": "《说文》"}, {"t": "丧其资斧。", "b": "《易·巽卦》。注:“斧,所以断者也。”"}, {"t": "既破我斧。", "b": "《诗·豳风·破斧》"}, {"t": "寺僧使小童持斧,于乱石间择其一二扣之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "斧柯", "t": "斧柄;斧头与斧柄;做媒"}, {"w": "斧脑", "t": "斧之背"}, {"w": "斧砧", "t": "古代刑具"}, {"w": "斧绣", "t": "持斧绣衣。古执法使者的仪制。"}]}, {"meaning": "白与黑相间的斧形图案。", "cites": [{"t": "斧谓之黼。", "b": "《尔雅·释器》"}, {"t": "加斧于椁上。", "b": "《礼记·檀弓上》"}, {"t": "天子负斧依。", "b": "《礼记·明堂位》。注:“斧依,为斧文屏风于户牖之间。”"}, {"t": "负斧扆。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "斧藻", "t": ""}]}, {"meaning": "用斧子劈、砍或破开。", "cites": [{"t": "公怒,斧其门。", "b": "《聊斋志异》"}], "words": [{"w": "斧木", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1171wx','爸','1','bà','父','8','','[{"pinyin": "bà", "defs": [{"meaning": "(形声。从父,巴声。本义:父亲)。", "words": [{"w": "爸爸", "t": "父亲"}, {"w": "阿爸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1172wx','采','1','cǎi cài','采','8','','[{"pinyin": "cǎi", "defs": [{"meaning": "(会意。从爪从木。甲骨文,上象手,下象树木及其果实。表示以手在树上采摘果实和叶子。本义:用手指或指尖轻轻摘取来)。"}, {"meaning": "同本义。", "cites": [{"t": "采,捋取也。", "b": "《说文》。字俗作採。"}, {"t": "参差荇菜,左右采之。", "b": "《诗·周南·关雎》"}, {"t": "采葑采菲,无以下体。", "b": "《诗·邶风·谷风》"}, {"t": "采薇采薇,薇亦作止。", "b": "《诗·小雅·采薇》"}, {"t": "行以肆夏,趋以采荠。", "b": "《周礼·乐师》。司农注:“乐名。或曰皆逸诗。”"}, {"t": "采菊东篱下,悠然见南山。", "b": "晋·陶渊明《饮酒》"}], "words": [{"w": "采花;采果子;采及葑菲", "t": "对别人征求意见时的谦辞。"}]}, {"meaning": "引申为采集;搜集。", "cites": [{"t": "古有采诗之官。", "b": "《汉书·艺文志》"}], "words": [{"w": "采兰赠药;博采众长;广收薄采;采了200多种矿样;采药;采珍珠;采铁;采金;采气;采油", "t": ""}]}, {"meaning": "挑选;采纳。", "cites": [{"t": "纳采。", "b": "《仪礼·士昏礼》"}, {"t": "昏礼始纳采。谓采择其可者也。", "b": "《礼记·坊记》注"}, {"t": "嵘虽位末名卑,而所言或有可采。", "b": "《资治通鉴》"}, {"t": "采上古帝位号,曰皇帝。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "多色的丝织品。后来写作“綵”。", "cites": [{"t": "衣必文采,食必梁肉。", "b": "汉·晁错《论贵粟疏》"}]}, {"meaning": "引申为彩色。后写作“彩”。", "cites": [{"t": "抑为采色不足视於目与?", "b": "《孟子·梁惠王上》"}, {"t": "吾令人望其气,皆为龙虎,成五采。", "b": "《史记·项羽本纪》"}], "words": [{"w": "采缯", "t": "彩色丝织品"}, {"w": "采服", "t": "彩色的衣服"}, {"w": "采章", "t": "绘有彩色图案的旌旗、车舆及服饰。"}]}, {"meaning": "文章的词藻。", "cites": [{"t": "繁采寡情,味之必厌。", "b": "《文心雕龙》"}]}]}, {"pinyin": "cài", "defs": [{"meaning": "采地,古代士大夫的封邑 ,又叫采邑,食邑,采地。", "cites": [{"t": "大夫有采,以处其子孙。", "b": "《礼记·礼运》"}, {"t": "西采雍梁。", "b": "《法言·重黎》。注:“食税也。”"}, {"t": "所谓采者,不得有其土地人民采取其租税耳。字亦作寀。", "b": "《公羊传·襄公十五年》注"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1173wx','觅','1','mì','见','8','','[{"pinyin": "mì", "defs": [{"meaning": "(会意。从爪,从见。表示用手和眼去寻找。本义:寻找,到处寻找)。"}, {"meaning": "同本义。", "cites": [{"t": "是犹欲登山者,涉舟航而觅路。", "b": "《晋书·武帝纪》"}, {"t": "自行搜觅。", "b": "《聊斋志异·促织》"}, {"t": "英雄无觅孙仲谋处。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "觅汉", "t": "雇工"}, {"w": "觅举", "t": "士人到处请托人,求人荐举"}, {"w": "觅句", "t": "指诗人构思、寻觅诗句"}, {"w": "觅食", "t": "寻找食物"}, {"w": "觅死", "t": "求死,寻死"}, {"w": "觅取", "t": "求取"}, {"w": "觅活", "t": "求活命"}, {"w": "觅婚", "t": "求婚。"}]}, {"meaning": "偷窃。", "cites": [{"t": "我觅得禁魂张员外的一包儿细软,我将归客店里去,安在头边,枕着头。你觅着我的时,你便去上东京。", "b": "《喻世明言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1174wx','受','1','shòu','又','8','','[{"pinyin": "shòu", "defs": [{"meaning": "(会意。甲骨文字形,象两手中间有一只舟,表示传递东西。本义:接受;承受)。"}, {"meaning": "同本义。", "cites": [{"t": "受,相付也。", "b": "《说文》”王筠曰:“手部授,人部付,皆曰“予也。”今以付说受,则是受授同字矣。”"}, {"t": "受其币。", "b": "《周礼·天官·司书》"}, {"t": "主妇拜受爵。", "b": "《仪礼·特牲馈食礼》"}, {"t": "则受之。", "b": "《周礼·司干》。注:“取藏之。”"}, {"t": "受以小功衰。", "b": "《仪礼·丧服》。注:“犹承也。”"}, {"t": "颛顼受之。", "b": "《国语·楚语》。注:“承也。”"}, {"t": "釜十五,吾受,而宫出之以百。", "b": "《管子·海南》"}, {"t": "志士不饮盗泉之水,廉者不受嗟来之食。", "b": "《后汉书·列女传》"}, {"t": "臣修身洁行数十年,终不以监门困故而受公子财。", "b": "《史记·魏公子列传》"}], "words": [{"w": "受茶", "t": "女子受聘,订立婚约"}, {"w": "受宫厅", "t": "衙门中的厅堂"}, {"w": "受法", "t": "伏法"}, {"w": "受事", "t": "接受教诲"}, {"w": "受册", "t": "接受册命"}, {"w": "受祉", "t": "接受天地神明的降福"}, {"w": "受胙", "t": "接受胙肉。"}]}, {"meaning": "蒙受;遭受。", "cites": [{"t": "人又谁能以身之察察,受物之汶汶者乎?", "b": "《史记·屈原贾生列传》"}, {"t": "民到于今受其赐。", "b": "《论语·宪问》"}, {"t": "一夫不耕,或受之饥,一女不织,或受之寒。", "b": "贾谊《论积贮疏》"}, {"t": "吾庐独破受冻死亦足。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "受侮;受敌;受污", "t": "遭受污染。"}]}, {"meaning": "得到。", "cites": [{"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·齐策》"}], "words": [{"w": "受知", "t": "得到他人的赏识、礼遇"}, {"w": "受名", "t": "获得名称"}, {"w": "受直", "t": "得到报酬"}, {"w": "受瘪;受享", "t": "享受。"}]}, {"meaning": "收进,取回。", "cites": [{"t": "舞者既陈,则授舞器,既舞则受之。", "b": "《周礼·春官·司干》"}]}, {"meaning": "买入,收入。", "cites": [{"t": "釜十五吾受,而官出之百。", "b": "《管子》"}], "words": [{"w": "受主", "t": "买主。"}]}, {"meaning": "容纳。", "cites": [{"t": "秋水才添四五尺,野航恰受两三人。", "b": "杜甫《南邻》"}]}, {"meaning": "授予;交给。", "cites": [{"t": "若有诸公大夫则使人受俎如宾礼。", "b": "《仪礼·乡饮酒礼》"}, {"t": "以劳受禄,则民不幸生。", "b": "《管子·君臣上》"}, {"t": "受以王命,委以王事。", "b": "《论衡·自然》"}, {"t": "因能而受官。", "b": "《韩非子·外储说左上》"}]}, {"meaning": "教授;传授。", "cites": [{"t": "师者,所以传道受业解惑也。", "b": "唐·韩愈《师说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1175wx','乳','1','rǔ','乙','8','','[{"pinyin": "rǔ", "defs": [{"meaning": "(会意。从孚)。甲骨文中象手抱婴儿哺乳形。“孚”是以爪抱子哺乳。本义:生子,生产。"}, {"meaning": "同本义。", "cites": [{"t": "人及鸟生子曰乳,兽曰产。", "b": "《说文》"}, {"t": "乳化曰孽。", "b": "《书·尧典》传"}, {"t": "胎生曰乳。", "b": "《尸子》"}, {"t": "菑川王美人怀子而不乳。", "b": "《史记·扁仓传》"}, {"t": "主人方乳。", "b": "《吕氏春秋·音初》"}, {"t": "使牧羝,羝乳乃得归。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "乳子", "t": "产子;分娩"}, {"w": "乳舍", "t": "产房"}, {"w": "乳妇", "t": "产妇"}, {"w": "乳卵(产(下)蛋", "t": ""}, {"w": "乳抱", "t": "繁殖。"}]}, {"meaning": "喂奶。", "cites": [{"t": "妪,先大母婢也,乳二世。", "b": "明·归有光《项脊轩志》"}, {"t": "妇抚儿乳。", "b": "林嗣环《口技》"}], "words": [{"w": "乳狗", "t": "育子的母狗"}, {"w": "乳育", "t": "哺育"}, {"w": "乳哺", "t": "哺育;养育"}, {"w": "乳养", "t": "哺育"}, {"w": "乳雏", "t": "哺育幼雏"}, {"w": "乳兽", "t": "育子的猛兽"}, {"w": "哺乳", "t": ""}]}, {"meaning": "孵化。", "cites": [{"t": "立春,鸡始乳。", "b": "《魏书》"}]}, {"meaning": "饮。", "cites": [{"t": "乳血飧肤。", "b": "鲍照《芜城赋》"}]}, {"meaning": "乳汁。", "cites": [{"t": "常饮牛乳,色如处子。", "b": "《魏书·王琚传》"}], "words": [{"w": "乳花", "t": "奶花。指年幼无知"}, {"w": "乳白;乳茶;乳酒;乳畜;乳食;乳汁;乳牛;炼乳;乳臭小子", "t": "对年轻人的鄙称"}, {"w": "乳腥气;乳臭", "t": ""}]}, {"meaning": "乳房。", "cites": [{"t": "儿含乳啼。", "b": "《虞初新志·秋生诗自序》"}, {"t": "袒胸露乳。", "b": "魏学洢《核舟记》"}], "words": [{"w": "乳峰;乳下", "t": "乳部之下。"}]}, {"meaning": "草鞋上穿带子的耳鼻儿。", "cites": [{"t": "百忙里鞋儿断了乳,好着我难行。", "b": "元·孟汉卿《魔合罗》"}]}, {"meaning": "年幼。", "cites": [{"t": "乳燕逐草虫。", "b": "鲍照《咏采桑》"}, {"t": "少年如乳虎。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "乳女;乳哺儿", "t": "婴儿"}, {"w": "乳驹", "t": "幼马"}, {"w": "乳鸦", "t": "幼鸦"}, {"w": "乳稚", "t": "幼儿"}, {"w": "乳兽", "t": "幼兽"}, {"w": "乳茄", "t": "嫩茄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1176wx','贪','1','tān','贝','8','','[{"pinyin": "tān", "defs": [{"meaning": "(形声。从贝,今声。从“贝”,与财物有关。本义:贪财)。"}, {"meaning": "同本义。", "cites": [{"t": "贪,欲物也。", "b": "《说文》"}, {"t": "晋、魏河内之比,谓惏曰残。楚谓之贪。", "b": "《方言一》"}, {"t": "贪于饮食,惰于作务。", "b": "《墨子·非儒下》"}, {"t": "贪货弃命。", "b": "《左传·襄公二十三年》"}, {"t": "爱财曰贪,爱食曰婪。", "b": "《楚辞·离骚》注"}, {"t": "虞公贪利其璧与马而欲许之。", "b": "《韩非子·十过》"}], "words": [{"w": "贪赃", "t": "官吏接受贿赂"}, {"w": "贪便宜;贪得无厌;贪冒", "t": "贪图财利"}, {"w": "贪鄙", "t": "贪婪卑鄙"}, {"w": "贪汙", "t": "贪求私利,取非分的财物"}, {"w": "贪墨", "t": "贪财受贿"}, {"w": "贪夫徇财", "t": "贪婪的人为财而死。"}]}, {"meaning": "贪婪。多欲而不知满足。", "cites": [{"t": "贪欲无艺。", "b": "《国语·晋语》"}, {"t": "左右皆恶之,以为贪而不知足。", "b": "《战国策·齐策四》"}, {"t": "以贪勤民。", "b": "《左传·僖公三十二年》"}, {"t": "秦贪。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "贪虐", "t": "贪婪暴虐"}, {"w": "贪娼", "t": "贪婪而妒忌"}, {"w": "贪狠", "t": "贪心暴戾"}, {"w": "贪残", "t": "贪婪残贼"}, {"w": "贪花", "t": "怜爱美色"}, {"w": "贪粗", "t": "贪婪粗犷"}, {"w": "贪谗", "t": "贪婪并进谗言"}, {"w": "贪陵", "t": "贪婪侵夺"}, {"w": "贪悍", "t": "贪婪凶横。"}]}, {"meaning": "求。同“探”。", "cites": [{"t": "贪权据凡,则高名自立矣。", "b": "王充《论衡》"}, {"t": "若夫推己以议物,捨状以贪情。", "b": "《后汉书·郭躬传论》"}], "words": [{"w": "贪祸", "t": "取祸"}, {"w": "贪黑", "t": "摸黑"}, {"w": "贪嗜", "t": "贪求嗜好"}, {"w": "贪贾", "t": "贪图小利的商人"}, {"w": "贪迷", "t": "贪恋,迷恋"}, {"w": "贪怯", "t": "贪生怕死。"}]}, {"meaning": "贪污。", "cites": [{"t": "贪于财贺。", "b": "《史记·项羽本纪》"}, {"t": "贪慕富贵。", "b": "宋·司马光《训俭示康》"}, {"t": "知某不贪。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "官贪吏虐。", "b": "《聊斋志异·促织》"}], "words": [{"w": "贪滥", "t": "贪污渎职"}, {"w": "贪黩", "t": "贪污"}, {"w": "贪洿", "t": "贪污"}, {"w": "贪官", "t": "贪污的官吏"}, {"w": "贪罔", "t": "贪赃欺罔"}, {"w": "贪吏", "t": "贪污的官吏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1177wx','念','1','niàn','心','8','','[{"pinyin": "niàn", "defs": [{"meaning": "(形声。从心,今声。本义:常思;思念,惦念)。"}, {"meaning": "同本义。", "cites": [{"t": "念,常思也。", "b": "《说文》"}, {"t": "天念尔祖。", "b": "《诗·大雅·文王》"}, {"t": "不念昔者。", "b": "《诗·邶风·谷风》"}, {"t": "不念旧恶。", "b": "《论语》"}, {"t": "念悲其远。", "b": "《战国策·赵策》"}, {"t": "念鬼。", "b": "《史记·陈涉世家》"}, {"t": "念母劳家里。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "念蒙君实。", "b": "宋·王安石《答司马谏议书》"}, {"t": "因念黄山当平生奇览,而有奇若此。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "念诵", "t": "念叨"}, {"w": "念恤", "t": "挂念忧虑"}, {"w": "念旧", "t": "不忘故旧"}, {"w": "念思", "t": "怀念"}, {"w": "念想", "t": "想念"}, {"w": "念一", "t": "思念大道"}, {"w": "念恋", "t": "思念爱恋。"}]}, {"meaning": "思考, 考虑。", "cites": [{"t": "顾吾念之。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "念虑", "t": "思考"}, {"w": "念咎", "t": "反省过失"}, {"w": "念思", "t": "考虑。"}]}, {"meaning": "引申为忧虑。", "cites": [{"t": "报国心皎洁,念时涕泛澜。", "b": "唐·韩愈《龊龊》"}]}, {"meaning": "哀怜,可怜。", "cites": [{"t": "念窦娥身首不完全。", "b": "关汉卿《窦娥冤》"}]}, {"meaning": "想法;念头。", "cites": [{"t": "一念之贞。", "b": "清·袁枚《祭妹文》"}, {"t": "爱汝一念。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "概念;观念;信念;杂念;邪念", "t": ""}]}, {"meaning": "二十。", "cites": [{"t": "辛未三月念六夜四鼓。", "b": "《与妻书》"}], "words": [{"w": "念余年", "t": "二十多年。"}]}, {"meaning": "佛教名词。法相宗别境之一。指记忆。", "cites": [{"t": "念谓于缘明记不忘。", "b": "《俱舍论》"}]}, {"meaning": "诵读,按字读出声。", "cites": [{"t": "欲为《论》,念张文。", "b": "《汉书·张禹传》"}], "words": [{"w": "念词", "t": "念台词或道白"}, {"w": "念咒", "t": "念诵自认为可以产生神奇力量的神秘语句"}, {"w": "念曲", "t": "唱歌而声无抑扬"}, {"w": "念奴", "t": "唐天宝长安妓女,以善歌著名。后用以泛指歌女"}, {"w": "念奴娇", "t": "词牌名。其调高亢。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1178wx','贫','1','pín','贝','8','','[{"pinyin": "pín", "defs": [{"meaning": "(会意兼形声。从贝从分,分亦声。“贝”是古货币,一个“贝”还要分开,表示贫困。本义:缺少财物,贫困。与“富”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "贫,财分少也。", "b": "《说文》"}, {"t": "无财谓之贫。", "b": "《庄子·让王》"}, {"t": "贫者,士之常也。", "b": "《说苑·杂言》"}, {"t": "分贫振穷。", "b": "《左传·昭公十四年》。疏:“贫、穷相类。细言,穷困于贫。”"}, {"t": "贫而无谄。", "b": "《论语》"}, {"t": "强本而节用,则天下不能贫。", "b": "《荀子·天论》"}, {"t": "楚人贫居。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "家贫,无从致书以观。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "贫难", "t": "贫苦,困难"}, {"w": "贫胎", "t": "骂人的话。穷鬼"}, {"w": "贫窭", "t": "贫苦"}, {"w": "贫贱之交", "t": "贫困患难中结交的朋友"}, {"w": "贫户", "t": "贫穷人家"}, {"w": "贫交", "t": "贫贱者相交友"}, {"w": "贫巷", "t": "贫民居住的地方"}, {"w": "贫病", "t": "又穷又病"}, {"w": "贫汉", "t": "贫穷的男子。"}]}, {"meaning": "引申为缺少,不足。", "cites": [{"t": "富于万篇,而贫于一字。", "b": "刘勰《文心雕龙·练字》"}], "words": [{"w": "贫阙", "t": "不足,短缺"}, {"w": "贫薄", "t": "浅陋,短浅"}, {"w": "贫腐", "t": "贫乏陈腐"}, {"w": "贫微", "t": "贫乏微薄"}, {"w": "贫寒", "t": "贫乏单薄"}, {"w": "贫空", "t": "谓空无所有"}, {"w": "贫辛", "t": "贫乏艰涩。"}]}, {"meaning": "以为贫穷。", "cites": [{"t": "夫人贫之,竟不商女。", "b": "《聊斋志异》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1179wx','忿','1','fèn','心','8','','[{"pinyin": "fèn", "defs": [{"meaning": "(形声。从心,分声。从“心”,表示与心情有关。本义:愤怒,怨恨)。"}, {"meaning": "同本义。", "cites": [{"t": "忿,悁也。", "b": "《说文》"}, {"t": "忿,怒也。", "b": "《广雅》"}, {"t": "君子以惩忿窒欲。", "b": "《易·象传》"}, {"t": "身有所忿窒。", "b": "《礼记·大学》"}, {"t": "惩违改忿兮。", "b": "《楚辞·怀沙》。注:“恨也。”"}, {"t": "忿慉之气。", "b": "《庄子·达生》"}, {"t": "忿,恨也,怒也。", "b": "《玉篇》"}, {"t": "伯主约而不忿。", "b": "《战国制·秦策》"}, {"t": "将不胜其忿而蚁附之。", "b": "《孙子·谋攻》"}, {"t": "吾意久怀忿,汝岂得自由。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "忿恨", "t": "愤怒怨恨"}, {"w": "忿气", "t": "气愤;生气"}, {"w": "忿怒", "t": "愤怒"}, {"w": "忿疾", "t": "愤怒厌恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1180wx','肤','1','fū','月','8','','[{"pinyin": "fū", "defs": [{"meaning": "(形声。从肉,盧省声。本义:人的皮肤)。"}, {"meaning": "同本义。", "cites": [{"t": "肤受之愬。", "b": "《论语·颜渊》"}, {"t": "衣不暖肤。", "b": "《商君书·算地》"}, {"t": "手如柔荑,肤如凝脂。", "b": "《诗·卫风·硕人》"}], "words": [{"w": "肌肤", "t": "肌肉皮肤"}, {"w": "肤革", "t": "皮肤的表皮和真皮;外面,表面"}, {"w": "肤不生毛", "t": "皮肤上长满了厚茧而长不出毛。"}]}, {"meaning": "某些像皮层那样的东西。", "cites": [{"t": "纸光洁如玉,肤如卵膜。", "b": "宋·陈师道《后山谈丛》"}], "words": [{"w": "草皮;纸张", "t": ""}]}, {"meaning": "古代用于祭祀或供食用的肉类。", "cites": [{"t": "麋肤,鱼醢。", "b": "《礼记》。郑玄注:“肤,切肉也。”"}]}, {"meaning": "外表。", "cites": [{"t": "而短小精悍者,游侠之徒也。人何足以知之?此皆其肤也。", "b": "宋·苏轼《王定国真赞》"}]}, {"meaning": "(fǔ)。古祭祀燕享,以盛稻粱的器皿。", "cites": [{"t": "剥床以肤,凶。", "b": "《易·剥卦》"}]}, {"meaning": "浅薄。", "cites": [{"t": "所谓末学肤受,贵耳而贱目者也。", "b": "汉·张衡《东京赋》"}], "words": [{"w": "肤见", "t": "浅陋的见解"}, {"w": "肤学", "t": "浅学,所学浅陋"}, {"w": "肤俗", "t": "肤浅庸俗"}, {"w": "肤庸", "t": "浅薄平庸"}, {"w": "肤语", "t": "肤辞,肤浅空泛的言语。"}]}, {"meaning": "大。", "cites": [{"t": "薄伐猃狁,以奏肤公。", "b": "《诗·小雅·六月》"}], "words": [{"w": "肤功", "t": "大功。"}]}, {"meaning": "肥美,美。", "cites": [{"t": "公孙硕肤。", "b": "《诗·豳风·狼跋》"}], "words": [{"w": "肤美", "t": "优美敏捷"}, {"w": "肤敏", "t": "德行美好,行事敏捷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1181wx','肺','1','fèi','月','8','','[{"pinyin": "fèi", "defs": [{"meaning": "人和某些高级动物的呼吸器官", "words": [{"w": "肺肠", "t": "肺和肠。指生理上的欲念。即七情六欲"}, {"w": "肺肝", "t": "肺与肝。比喻内心"}, {"w": "肺吵丢丢掀", "t": "方言。心花怒放"}, {"w": "肺火", "t": "中医称肺部的邪热。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1182wx','肢','1','zhī','月','8','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从肉,支声。本义:人的手足与鸟兽翼足的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "劳其四肢,伤其五脏。", "b": "《商君书》"}, {"t": "四肢六道,身之体也。", "b": "《管子》"}], "words": [{"w": "肢节", "t": "四肢关节"}, {"w": "肢骸", "t": "肢体骸骨"}, {"w": "上肢;下肢;假肢", "t": ""}]}, {"meaning": "指人体的腰部。", "cites": [{"t": "协肩屏气,舐痔折肢。", "b": "《朝野佥载》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1183wx','肿','1','zhǒng','月','8','','[{"pinyin": "zhǒng", "defs": [{"meaning": "(形声。从肉,中(重)声。本义:痈) 同本义。", "cites": [{"t": "肿,痈也。", "b": "《说文》"}, {"t": "肉暴长曰肿。", "b": "《论衡·状留》"}, {"t": "肿疡。", "b": "《周礼·疡医》。注:“痈而上创者。”"}, {"t": "郁处头,则为肿为风。", "b": "《吕氏春秋·尽数》"}, {"t": "疡医掌肿疡。", "b": "《周礼·天官》。郑玄注:“肿疡,痈而上生疮者”"}]}, {"meaning": "浮胀;肿胀。", "cites": [{"t": "看那店主人,打的半边脸都肿了,半日挣扎不起。", "b": "《水浒传》"}], "words": [{"w": "肿泄", "t": "病名。腹泻及手足浮肿"}, {"w": "肿哙", "t": "虚肿"}, {"w": "肿疡", "t": "痈;毒疮"}, {"w": "肿病", "t": "病名。即水肿。通称浮肿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1184wx','胀','1','zhàng','月','8','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从肉,长声。从肉,表示与身体有关。本义:皮肉鼓胀)。"}, {"meaning": "同本义 。因为身体内壁受到压迫而产生的不适之感。亦泛指充塞难受的感觉。", "cites": [{"t": "胀,胀满。", "b": "《广韵》"}, {"t": "寒气泄注腹胪胀。", "b": "《急就篇》。注:“胀,谓腹鼓胀也。”"}, {"t": "人或嚥气,气满腹胀,不能餍饱。", "b": "汉·王充《论衡·道虚》"}], "words": [{"w": "胀闷", "t": "又胀又闷"}, {"w": "胀病;鼓胀;单腹胀;头胀;胁胀", "t": ""}]}, {"meaning": "膨胀,体积变大。", "cites": [{"t": "斯须之间,见囊大胀如吹。", "b": "《晋书·韩友传》"}], "words": [{"w": "热胀冷缩;胀鼓鼓", "t": "形容胀得鼓起的样子"}, {"w": "腹胀;吃多了,感到肚子有点发胀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1185wx','朋','1','péng','月','8','','[{"pinyin": "péng", "defs": [{"meaning": "(象形。本义:古代货币单位。相传五贝为一朋。或说五贝为一系,两系为一朋)。"}, {"meaning": "古代货币单位。五贝为一朋。一说两贝为一朋,也有说十贝为一朋的。", "cites": [{"t": "既见君子,锡我百朋。", "b": "《诗·小雅·菁菁者莪》"}]}, {"meaning": "同学。", "cites": [{"t": "君子以朋友讲习。", "b": "《易·兑》。孔颖达疏:“同门曰朋,同志曰友。”"}]}, {"meaning": "朋友。", "cites": [{"t": "朋,比也,朋,类也。", "b": "《广雅》"}, {"t": "或益之十朋之龟。", "b": "《易·损》。注:“党也。”"}, {"t": "每有良朋。", "b": "《诗·小雅·常棣》"}, {"t": "有朋自远方来。", "b": "《论语·学而》"}], "words": [{"w": "朋故", "t": "朋友故旧"}, {"w": "朋曹", "t": "朋友辈"}, {"w": "朋好", "t": "朋友,好友"}, {"w": "朋伴", "t": "朋友,同伴"}, {"w": "朋知", "t": "朋友;知交"}, {"w": "朋侣", "t": "朋友;同伴。"}]}, {"meaning": "队;班。", "cites": [{"t": "一朋头用杖击弄球子,如缀球子方坠队,两朋争占,供与朋头。", "b": "宋·孟元老《东京梦华录》"}]}, {"meaning": "勾结。", "cites": [{"t": "世并举而好朋兮。", "b": "《楚辞·离骚》"}, {"t": "向闻杨虞卿兄弟朋比贵势,妨平进之路。", "b": "《唐书·选举志》"}], "words": [{"w": "朋谋", "t": "结党图谋不轨"}, {"w": "朋比", "t": "阿附;勾结"}, {"w": "朋邪", "t": "朋比为奸"}, {"w": "朋奸", "t": "朋比为奸"}, {"w": "朋附", "t": "勾结、阿附"}, {"w": "朋挺", "t": "犹勾结"}, {"w": "朋扇", "t": "相互勾结煽动"}, {"w": "朋援", "t": "勾结引援。"}]}, {"meaning": "倒塌。", "cites": [{"t": "其状义而不朋。", "b": "《庄子·大宗师》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1186wx','股','1','gǔ','月','8','','[{"pinyin": "gǔ", "defs": [{"meaning": "(形声。从肉,殳(shū)声。本义:大腿)。"}, {"meaning": "同本义。", "cites": [{"t": "股,髀也。", "b": "《说文》"}, {"t": "膝上曰股,膝下曰胫。", "b": "《论语·宪问》疏"}, {"t": "读书欲睡,引锥刺其股。", "b": "《战国策·秦策》"}, {"t": "余皆股栗。", "b": "《史记·酷吏列传》"}, {"t": "屠自后断其股,亦毙之。", "b": "《聊斋志异·狼三则》"}, {"t": "闻鸣镝而股战,对穹庐以屈膝又何劣邪!", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "股掌", "t": "大腿与手掌"}, {"w": "股弁", "t": "大腿发抖。"}]}, {"meaning": "事物的分支或一部分。", "cites": [{"t": "注:“如淳曰:股,支别也。”", "b": "《汉书·沟洫志》。"}], "words": [{"w": "人事股;军需股", "t": ""}]}, {"meaning": "不等腰直角三角形构成直角的较长的边。", "cites": [{"t": "故折矩,以为句(即勾)广三,股修四,径隅(即弦)五。", "b": "《周髀算经》"}], "words": [{"w": "勾股弦", "t": ""}]}, {"meaning": "一阵突然而剧烈的爆发 。如:一股熊熊火焰正从屋顶冒出来;尤指一阵感情的激烈爆发。如:一股劲。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1187wx','肮','1','āng háng','月','8','','[{"pinyin": "āng", "defs": [{"meaning": "a.不干净；b.喻卑鄙、丑恶。"}]}, {"pinyin": "háng", "defs": [{"meaning": "咽喉", "words": [{"w": "绝肮", "t": "割断咽喉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1188wx','肪','1','fáng','月','8','','[{"pinyin": "fáng", "defs": [{"meaning": "脂肪 。动物组织的一部分,主要由充满油脂物质或油液物质的细胞所组成。", "cites": [{"t": "窃见玉书,称美玉白如截肪。", "b": "曹丕《与钟大理书》"}]}, {"meaning": "也特指动物腰部肥厚的油。", "cites": [{"t": "脂在腰曰肪。", "b": "《文选》李善注引《通俗文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1189wx','肥','1','féi','月','8','','[{"pinyin": "féi", "defs": [{"meaning": "(会意。从肉，本义:脂肪多)。"}, {"meaning": "同本义。", "cites": [{"t": "肥,多肉也。", "b": "《说文》"}, {"t": "坚土之人肥。", "b": "《大戴礼记·易本命》"}, {"t": "瞻肥瘠。", "b": "《礼记·月令》"}, {"t": "吾牲牷肥。", "b": "《左传·桓公六年》。服注:“牛羊曰肥。”"}, {"t": "庖有肥肉,厩有肥马。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "肥猪;肥肉", "t": "喻指有钱的人"}, {"w": "肥腻", "t": "含油脂多的食物;油脂多"}, {"w": "肥汉", "t": "肥胖的男子。"}]}, {"meaning": "引申为肥沃。", "cites": [{"t": "不爱珍器重肥饶之地。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "这块地肥极了;肥衍", "t": "土地肥沃"}, {"w": "肥饶", "t": "肥沃富饶。"}]}, {"meaning": "茁壮,粗大。", "cites": [{"t": "桃花流水鳜鱼肥。", "b": "唐·张志和《渔歌子》"}], "words": [{"w": "肥茂", "t": "肥壮茂盛"}, {"w": "肥茁", "t": "肥壮"}, {"w": "肥润", "t": "肥壮润泽"}, {"w": "肥泽", "t": "肌肉丰润。"}]}, {"meaning": "使土地肥沃。", "cites": [{"t": "掩地表亩,剌草殖谷,多粪肥田,是农夫众庶之事也。", "b": "《荀子·富国》"}]}, {"meaning": "(fēi)。责难。", "cites": [{"t": "目所偏视,晋国爵之;口所偏肥,晋国黜之。", "b": "《列子·黄帝》"}]}, {"meaning": "油脂。", "cites": [{"t": "干其皮,中作肥。", "b": "《齐民要术》引《南方记》"}]}, {"meaning": "古国名 。春秋时狄人所建,后为晋所灭。故都在山西省昔阳县东。", "cites": [{"t": "秋八月壬午,灭肥。", "b": "《左传·昭公十二年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1190wx','服','1','fú fù','月','8','','[{"pinyin": "fú", "defs": [{"meaning": "(会意。古文从舟,兼做声符。本义:舟两旁的夹木)。"}, {"meaning": "服从,顺服。", "cites": [{"t": "敌已服矣。", "b": "《吕氏春秋·论威》"}, {"t": "以一服八。", "b": "《孟子·梁惠王上》"}, {"t": "以力服人者,非心服也。", "b": "《孟子·公孙丑上》"}, {"t": "当舜之时,有苗不服。", "b": "《韩非子·五蠹》"}, {"t": "授之政,西土服。", "b": "《墨子·尚贤》"}, {"t": "远人不服而不能来也。", "b": "《论语·季氏》"}, {"t": "强国请服,弱国入朝。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "服听", "t": "服从听命"}, {"w": "服低", "t": "屈服;低头"}, {"w": "服杀", "t": "折服;倾倒。杀:用在动词后,表示程度深"}, {"w": "服主", "t": "轻易服输的人"}, {"w": "服属", "t": "顺从归属。"}]}, {"meaning": "佩服;信服;使信服。", "cites": [{"t": "毛遂比至楚,与十九人议论,十九人皆服。", "b": "《史记·平原君虞卿列传》"}, {"t": "后数日驿至,果地震陇西,于是皆服其妙。", "b": "范晔《后汉书·张衡传》"}, {"t": "服人如何?", "b": "《论衡·问孔》"}], "words": [{"w": "以理服人;心服", "t": "衷心信服"}, {"w": "悦服", "t": "从心里佩服"}, {"w": "服众", "t": "使众人心服"}, {"w": "服善", "t": "佩服、顺从别人的长处"}, {"w": "不服输", "t": ""}]}, {"meaning": "使用。", "cites": [{"t": "诸侯御荼,大夫服笏。", "b": "《荀子·大略》"}, {"t": "子弟犹归器,衣服裘衾车马,则必献其上,而后敢服用其次也。", "b": "《礼记·内则》"}]}, {"meaning": "从事;致力。", "cites": [{"t": "以德就利,以官服事。", "b": "《墨子·尚贤》"}, {"t": "有事,弟子服其劳。", "b": "《论语》"}, {"t": "肇牵车牛,运服贾。", "b": "《书·酒诰》"}], "words": [{"w": "服田", "t": "从事耕作,种田"}, {"w": "服官", "t": "做官"}, {"w": "服贾", "t": "从商,作买卖"}, {"w": "服劳", "t": "服事效劳"}, {"w": "服休", "t": "侍侯帝王宴息的近臣。"}]}, {"meaning": "饮用或吞服药物。", "cites": [{"t": "即作汤二升,先服一升。", "b": "《三国志·方伎传》"}, {"t": "众人…便知他有不足之症,因问:“常服何药?”", "b": "《红楼梦》。又如:服毒;服饵(服食丹药);服鸩(饮毒酒自杀);服食(服用饮食之物)"}]}, {"meaning": "担任;承当。", "cites": [{"t": "若农服田力穑。", "b": "《书·盘庚上》"}], "words": [{"w": "服劳", "t": "服事效劳"}, {"w": "服职", "t": "供职。"}]}, {"meaning": "招认,承认,肯定,认可。", "cites": [{"t": "于是傅付许狱,考验首服。", "b": "《三国志·方伎传》"}], "words": [{"w": "服过", "t": "承认自己的过错"}, {"w": "服辩", "t": "认罪供状"}, {"w": "服词", "t": "承认罪责之词。"}]}, {"meaning": "穿着。", "cites": [{"t": "朝服衣冠,窥镜。", "b": "《战国策·齐策》"}, {"t": "亦不敢服垢弊以矫俗干名,但顺吾性而已。", "b": "宋·司马光《训俭示康》"}, {"t": "昨望见妇女犹服夹领小袖。", "b": "《资治通鉴》"}], "words": [{"w": "服卉", "t": "穿着用絺葛制的衣裳"}, {"w": "服孝", "t": "带孝。穿孝服"}, {"w": "服冕", "t": "穿着冕服。"}]}, {"meaning": "佩带。", "cites": [{"t": "服太阿之剑。", "b": "秦·李斯《谏逐客书》"}], "words": [{"w": "服玉", "t": "佩玉"}, {"w": "服媚", "t": "喜爱佩带"}, {"w": "服剑", "t": "随身佩带的宝剑。"}]}, {"meaning": "铭记,怀念。", "cites": [{"t": "得一善,则拳拳服膺,而弗之矣。", "b": "《中庸》"}], "words": [{"w": "服膺", "t": "铭记在心。"}]}, {"meaning": "任用。", "cites": [{"t": "忠臣危殆,谗人服矣。", "b": "《荀子》"}]}, {"meaning": "实行;施行。", "cites": [{"t": "此古服道致士之法也。", "b": "《战国策·燕策一》"}]}, {"meaning": "又如:服行(施行,实行)。"}, {"meaning": "得。", "cites": [{"t": "明者固能察极,知人之所不能知,服人之所不能得。", "b": "马王堆汉墓帛书《道原》"}]}, {"meaning": "使习惯于。", "cites": [{"t": "后皇嘉树,橘徕服兮。", "b": "《楚辞·屈原·九章·橘颂》"}]}, {"meaning": "又如:不服水土。"}, {"meaning": "负荷;驾驶。", "cites": [{"t": "服牛乘马,引重致远,以利天下。", "b": "《易·系辞下》"}, {"t": "再鼓,服辇载粟而至。", "b": "《淮南子·人间》"}]}, {"meaning": "又如:服牛乘马(役使牛马驾车);服辂,服舆(驾车);服驯(驾驭车马);服御(驾驶车马)。"}, {"meaning": "遮盖,掩蔽。", "cites": [{"t": "道逢辇者,以其辇服其道。", "b": "《韩诗外传》"}]}, {"meaning": "衣服,服装。", "cites": [{"t": "甘其食,美其服。", "b": "《老子》八十章"}, {"t": "长者加以金银华美之服,輙羞赧弃去之。", "b": "宋·司马光《训俭示康》"}, {"t": "余幼好此奇服兮,年既老而不衰。", "b": "《楚辞·屈原·涉江》"}]}, {"meaning": "事情。", "cites": [{"t": "不学杂服,不能安礼。", "b": "《礼记·学记》"}]}, {"meaning": "服丧。", "cites": [{"t": "三年服阙。", "b": "《风俗通·十反》"}, {"t": "服阙,服全椒长。", "b": "《后汉书·刘平传》"}], "words": [{"w": "服满", "t": "服阙。服丧期满"}, {"w": "服制", "t": "服丧制度。按生者与死者关系的远近亲疏,分为斩衰、齐衰、大功、小功、缌麻五等"}, {"w": "服除", "t": "服丧期满"}, {"w": "服假", "t": "丧假。"}]}, {"meaning": "古代一车驾四马,居中的两匹叫“服”。", "cites": [{"t": "两服上襄。(上襄:指马头昂举。)", "b": "《诗·郑风 》"}]}, {"meaning": "盛箭之器。", "cites": [{"t": "四牡翼翼,象弭鱼服。", "b": "《诗·小雅·采薇》"}, {"t": "衣三属之甲,操十二石之弩,负服五十个,置戈其上,冠胄带剑,赢三日之粮,日中而趋百里。", "b": "《荀子·议兵》"}], "words": [{"w": "服无矢", "t": "箭筒内无箭。形容实力不强大。"}]}, {"meaning": "鸟名,又名山鴞,古以为不祥之鸟。", "cites": [{"t": "单于之岁兮,四月孟夏,庚子日施兮,服集于舍。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "又。", "cites": [{"t": "楚人命鴞曰服。", "b": ""}, {"t": "谊为长沙傅三年,有服飞入谊舍,止于坐隅。", "b": "《汉书·贾谊传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "fù", "defs": [{"meaning": "车厢。", "cites": [{"t": "大车牝服二柯,有参分柯之二。", "b": "《考工记·车人》"}, {"t": "凡服耜,斩季材,以时入之。", "b": "《周礼·山虞》"}]}, {"meaning": "负载;负荷。", "cites": [{"t": "车为服重致远,乘之则安,引之则利。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1191wx','胁','1','xié','月','8','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从肉(月),劦(xié)声。本义:腋下肋骨所在的部分)。"}, {"meaning": "同本义。", "cites": [{"t": "胁,两膀也。", "b": "《说文》。按,腋下之名也。其骨谓之肋,牲体则谓之拍。"}, {"t": "两胁里急。", "b": "《素问·至真要大论》"}, {"t": "兵尚胁盾。", "b": "《管子·版法》。注:“盾或著之于胁,固曰胁盾。”"}, {"t": "脊胁肺肩在上。", "b": "《仪礼》"}, {"t": "右胁夹大铁椎。", "b": "明·魏禧《大铁椎传》"}, {"t": "越天都之胁。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "胁胑", "t": "由腋下到腰以上的部位"}, {"w": "胁窝里", "t": "比喻两侧"}, {"w": "胁不沾席", "t": "形容佛教徒勤苦修行"}, {"w": "胁骨", "t": "肋骨"}, {"w": "胁衣", "t": "女人的内衣。或称“袜”"}, {"w": "胁肢", "t": "胁和臂之间的部位"}, {"w": "胁盾", "t": "盾的或称。"}]}, {"meaning": "肋骨。", "cites": [{"t": "曹共公闻其骈胁,欲观其裸。", "b": "《左传·僖公二十三年》。注:“骈胁,合干也。”"}]}, {"meaning": "旁边,边侧。", "cites": [{"t": "旁著岸胁,去地二百余丈,民俗名曰石鼓。", "b": "《汉书》"}], "words": [{"w": "胁士", "t": "佛教语。侍立在佛两旁的菩萨。"}]}, {"meaning": "挟持。", "cites": [{"t": "是谓胁君。", "b": "《礼记·礼运》"}, {"t": "乃胁栾中行。", "b": "《国语·晋语》。注:“劫也。”"}], "words": [{"w": "裹胁", "t": "用胁迫手段使人跟从"}, {"w": "胁君", "t": "胁持国君;被胁持的国君"}, {"w": "胁权", "t": "挟权。假用君上权名胁迫别人。"}]}, {"meaning": "威逼,用威力促使。", "cites": [{"t": "公欲从之。众从者胁公,不得归。", "b": "《左传·庄公八年》"}, {"t": "使使胁求君主。", "b": "《汉书·常惠传》。注:“谓以威迫之也。”"}, {"t": "淫而相胁。", "b": "《淮南子·本经》"}, {"t": "武终不可胁。", "b": "明·魏禧《大铁椎传》"}, {"t": "胁服夺其官。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "胁污", "t": "被胁迫而致玷污"}, {"w": "胁劫", "t": "威胁而劫持之"}, {"w": "胁和", "t": "迫使讲和"}, {"w": "胁服", "t": "迫使服从"}, {"w": "胁降", "t": "迫使降服;被迫投降。"}]}, {"meaning": "(xī)。收缩。", "cites": [{"t": "易系坤动,动静辟胁,万物生焉。", "b": "《汉书·王莽传中》"}], "words": [{"w": "胁肩", "t": "耸起肩膀,故示敬畏"}, {"w": "胁肩低眉", "t": "胁肩低首。缩肩低头。形容故作恭敬畏惧的样子"}, {"w": "胁肩累足", "t": "缩紧肩膀,不敢立正。形容极为恐惧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1192wx','周','1','zhōu','口','8','','[{"pinyin": "zhōu", "defs": [{"meaning": "(象形。甲骨文字形,在“田”里加四点,郭沫若认为“周象田中有种植之形。”有稠密和周遍的意思。小篆析为会意,从用口。段玉裁认为,善用口则周密。本义:周密;周到而没有疏漏)。"}, {"meaning": "同本义。", "cites": [{"t": "周,密也。", "b": "《说文》"}, {"t": "忠信为周。", "b": "《国语·鲁语》"}, {"t": "自周有终。", "b": "《礼记·缁衣》。注:“忠信曰周。”"}, {"t": "人不可不周。", "b": "《管子·人主》。注:“谓谨密也。”"}, {"t": "其藏之也周。", "b": "《左传·昭公四年》"}, {"t": "辅周则国必强。", "b": "《孙子·谋政》"}, {"t": "责己也重以周。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "周悉", "t": "周密"}, {"w": "计划不周;周谋", "t": "周密的谋划"}, {"w": "周严", "t": "周密严谨"}, {"w": "周谨", "t": "周密谨慎"}, {"w": "周虑", "t": "周密考虑。"}]}, {"meaning": "稠密;紧密。", "cites": [{"t": "橐之而约则周也。", "b": "《周礼·考工记·函人》"}, {"t": "具车徒以受地必周。", "b": "《左传·襄公二十六年》。注:“密也。”"}, {"t": "盟所以周信也。", "b": "《左传·襄公十二年》。注:“固也。”"}], "words": [{"w": "周置", "t": "密布"}, {"w": "周云", "t": "密云,浓云"}, {"w": "周闭", "t": "严密隐蔽内情。"}]}, {"meaning": "亲密,亲切,熟悉而情深。", "cites": [{"t": "周泽未渥也,而语极知。", "b": "《韩非子·说难》"}, {"t": "虽有周亲,不如仁人。", "b": "《论语·尧曰》"}], "words": [{"w": "周笃", "t": "亲密深厚"}, {"w": "周厚", "t": "亲密深厚"}, {"w": "周亲", "t": "至亲"}, {"w": "周党", "t": "至亲好友。"}]}, {"meaning": "周到,处处留意和体贴;周全;全面。", "cites": [{"t": "古之君子,其责己也重以周,其待人也轻以约。", "b": "韩愈《原毁》"}], "words": [{"w": "周致", "t": "周到严格"}, {"w": "周细", "t": "周详"}, {"w": "周悉", "t": "周到详尽"}, {"w": "周委", "t": "周详委曲。"}]}, {"meaning": "完备。", "cites": [{"t": "古之君子,其责己也重以周。", "b": "韩愈《原毁》"}], "words": [{"w": "周置", "t": "周全;办理"}, {"w": "周庇", "t": "周全;庇护"}, {"w": "周足", "t": "完备;充足"}, {"w": "周普", "t": "完备;普遍"}, {"w": "周方", "t": "周全方便。"}]}, {"meaning": "遍及;普遍。", "cites": [{"t": "布履星罗,四周于天下。", "b": "柳宗元《封建论》"}, {"t": "周身之帛缕。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "周身温暖;周谒", "t": "遍访"}, {"w": "周览", "t": "遍览;巡视"}, {"w": "周顾", "t": "环视"}, {"w": "周观", "t": "纵观;遍览。"}]}, {"meaning": "诚,忠信。", "cites": [{"t": "公不周乎伐郑也。", "b": "《谷梁传·成公十七年》"}]}, {"meaning": "周围。", "cites": [{"t": "大城不可以不完,郭周不可以外通。", "b": "《管子·八观》"}], "words": [{"w": "周驰", "t": "京城周围专供帝王车马行驶的道路"}, {"w": "周回", "t": "周围"}, {"w": "周合", "t": "四周合拢"}, {"w": "周城", "t": "古代天子之城。周围城垣回绕不缺,与“斩城”对称。"}]}, {"meaning": "拐角儿。", "cites": [{"t": "有杕(dì:挺立貌)之杜,生于道周。", "b": "《诗·唐风·有杕之林》"}]}, {"meaning": "朝代名。"}, {"meaning": "公元前11世纪周武王灭商后建立,建都镐京(今陕西西安市南)。历史上称平王东迁以前为西周,以后为东周。公元前256年为秦所灭,共历三十四王,八百多年。", "cites": [{"t": "周景王之无射(yì)。(《国语》记载,周景王二十四年即公元前521年铸成“无射”钟。)", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "南北朝时,宇文觉代西魏称帝,国号周。史称北周。为隋所灭。"}, {"meaning": "唐时,武则天临朝执政,改国号为周。"}, {"meaning": "五代时,郭威继后汉称帝,国号周。史称后周。960年为宋所灭。"}, {"meaning": "绕一圈,环绕。", "cites": [{"t": "逐之,三周华不注。(山名。)", "b": "《左传·成公二年》"}, {"t": "垣墙周庭。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "周而复始", "t": "循环往复"}, {"w": "周屈", "t": "环绕盘曲"}, {"w": "周沓", "t": "回环错杂"}, {"w": "周圆", "t": "循环"}, {"w": "周转", "t": "运转,运行"}, {"w": "周复", "t": "循环;反复。"}]}, {"meaning": "保全。", "cites": [{"t": "小智非周身之务。", "b": "《萤火赋》"}], "words": [{"w": "周方", "t": "帮助;关照;周全。"}]}, {"meaning": "周济;救济。", "cites": [{"t": "靡人不周。", "b": "《诗·大雅·云汉》"}, {"t": "君子周急不继富。", "b": "《论语·雍也》"}, {"t": "周天下。", "b": "《礼记·月令》"}, {"t": "周贫济老,咱们先倒挫磨起老奴才来了?", "b": "《红楼梦》"}], "words": [{"w": "周才", "t": "济世之才"}, {"w": "周亟", "t": "救济急难"}, {"w": "周急", "t": "周济困急"}, {"w": "周务", "t": "济事,成事"}, {"w": "周养", "t": "周济供养。"}]}, {"meaning": "合,适合。", "cites": [{"t": "宫室器械周于资用。", "b": "《韩非子·难二》"}], "words": [{"w": "周容", "t": "敬合取容"}, {"w": "周和", "t": "谐合。"}]}, {"meaning": "巩固。", "cites": [{"t": "盟,所以周信也。", "b": "《左传·哀公十二年》"}], "words": [{"w": "周固", "t": "牢不可破。"}]}, {"meaning": "保密。", "cites": [{"t": "周而成,泄而败。", "b": "《荀子·解蔽》"}]}, {"meaning": "(tiáo)调和,协调。", "cites": [{"t": "虽不周于今之人兮。", "b": "《楚辞·离骚》"}, {"t": "贵其周于数。", "b": "《淮南子·原道》。注:“周,调也。”"}, {"t": "立手四时之周。", "b": "《韩诗外传》"}]}, {"meaning": "回。", "cites": [{"t": "週,回也。", "b": "《玉篇》"}]}, {"meaning": "“週”同“周”。", "cites": [{"t": "週,俗周字。", "b": "《正字通》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1193wx','昏','1','hūn','日','8','','[{"pinyin": "hūn", "defs": [{"meaning": "(会意。从日,从氐(dǐ)省。“氐”是下的意思。合起来表示日已下沉。本义:黄昏) 同本义。", "cites": [{"t": "昏,日冥也。", "b": "《说文》"}, {"t": "日至于虞渊,是为黄昏。", "b": "《淮南子·天文训》"}, {"t": "昏以为期。", "b": "《诗·陈风·东门之杨》"}, {"t": "与曛黄以为期。", "b": "《楚辞·思美人》"}, {"t": "在昼犹昏。", "b": "吴均《与朱元思书》"}, {"t": "昏晨之往来。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "风雨晨昏。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "昏旦", "t": "黄昏和早上"}, {"w": "昏晚", "t": "天刚黑"}, {"w": "昏黄", "t": "暮色,天色暗淡。"}]}, {"meaning": "引申为昏暗;无光。", "cites": [{"t": "秋天漠漠向昏黑。", "b": "杜甫《茅屋为秋风所破歌》"}, {"t": "过午已昏。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "昏邓", "t": "昏暗的样子"}, {"w": "昏邓邓", "t": "昏澄澄、昏昏瞪瞪。形容昏暗"}, {"w": "昏曚", "t": "昏暗模糊"}, {"w": "昏昏", "t": "昏暗;阴暗。"}]}, {"meaning": "昏聩;糊涂。", "cites": [{"t": "昏迷不恭。", "b": "《书·大禹漠》"}, {"t": "我独若昏。", "b": "《老子》"}, {"t": "远我昏乎?", "b": "《庄子·在宥》"}, {"t": "昏微遵迹。", "b": "《楚辞·天问》"}, {"t": "不昏乎其所已知,而昏乎其所未知。", "b": "《吕氏春秋·有度》"}, {"t": "重昏而终身。", "b": "《楚辞·屈原·涉江》"}, {"t": "伪孽昏狡。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "以昏气出之。", "b": "唐·柳宗元《柳河东集》"}, {"t": "幽暗昏惑。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "昏眊", "t": "糊涂而年老"}, {"w": "昏耄", "t": "年老胡涂"}, {"w": "昏瞀", "t": "神志不清;缺乏分辨能力"}, {"w": "昏愚", "t": "糊涂而愚蠢。"}]}, {"meaning": "世道混乱、黑暗。", "cites": [{"t": "昏椓靡共。", "b": "《诗·大雅·召》"}], "words": [{"w": "昏世", "t": "黑暗腐败的时代"}, {"w": "昏敝", "t": "政治黑暗腐败。"}]}, {"meaning": "斑驳难辨。", "cites": [{"t": "看那山门时,上有一面朱红牌额,内有四个金个,都昏了,写着“瓦罐之寺”。", "b": "《水浒传》"}]}, {"meaning": "昏迷;失去知觉。", "cites": [{"t": "昏到于地。", "b": "《儒林外史》"}], "words": [{"w": "昏晕", "t": "昏迷。"}]}, {"meaning": "惑乱;迷惑。", "cites": [{"t": "下民昏垫。", "b": "《书·皋陶谟》"}, {"t": "寡君之二三臣札瘥天昏。", "b": "《左传·昭公十九年》。注:短折曰矢,未名曰昏。"}, {"t": "君子失心,鲜不夭昏。", "b": "《国语·晋语》。注:昏,狂荒之疾。"}, {"t": "蟊贼内讧,昏椓靡共。", "b": "《诗·大雅·召》。《笺》云:昏椓皆奄人也。"}, {"t": "昏于小利。", "b": "《吕氏春秋·诬徒》"}, {"t": "先生之老与昏与?", "b": "《吕氏春秋·贵直》"}, {"t": "僮昏不可使谋。", "b": "《国语·晋语四》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1194wx','鱼','1','yú','鱼','8','','[{"pinyin": "yú", "defs": [{"meaning": "(象形。甲骨文字形,象鱼形。本义:一种水生脊椎动物)。"}, {"meaning": "完全水生并在水中呼吸的有头冷血脊椎动物,包括圆口类、板鳃类和具有软骨或硬骨骨骼的高等有鳃水生脊椎动物。", "cites": [{"t": "鱼,水虫也。象形。鱼尾与燕尾相似。", "b": "《说文》"}, {"t": "豚鱼吉。", "b": "《易·中孚》"}, {"t": "鱼木精。", "b": "《论衡·指瑞》"}, {"t": "鱼十有五。", "b": "《仪礼·特牲礼》"}, {"t": "鱼网之设。", "b": "《诗·邶风·新台》"}, {"t": "鲜鱼曰脡祭。", "b": "《礼记·曲礼》"}, {"t": "鱼上冰,獭祭鱼。", "b": "《吕氏春秋》"}, {"t": "白鱼跃入王舟中。", "b": "《史记·周本记》"}], "words": [{"w": "鱼鲩冠儿", "t": "女道士戴的鱼脑骨似的尖形帽子"}, {"w": "鱼鳞册", "t": "“鱼鳞图册”的简称。官府为征派赋役而编造的土地薄册"}, {"w": "鱼烂", "t": "像鱼鳞那样成了一小块一小块的"}, {"w": "鱼轩", "t": "用鱼皮装饰的一种车辆,为贵妇乘用"}, {"w": "鱼脍", "t": "切得很细的鱼肉。特指生食的鱼片"}, {"w": "鱼市", "t": "批售鱼类的市场"}, {"w": "鱼质龙文", "t": "外貌似龙,而实质为鱼。比喻虚有其表"}, {"w": "鱼米", "t": "鱼类和米粮"}, {"w": "鱼秧", "t": "比鱼苗稍大的小鱼"}, {"w": "鱼鱼雅雅", "t": "形容威仪整肃的样子。因为鱼贯行,鸦飞成阵。"}]}, {"meaning": "某些像鱼的水生动物。", "cites": [{"t": "鱼甲烟聚,貝胄星罗。", "b": "《文选·王融·三月三日曲水诗序》"}], "words": [{"w": "鱼甲", "t": "鲨鱼皮铠甲"}, {"w": "鱼须", "t": "鲨鱼的须"}, {"w": "鲸鱼;鳄鱼;甲鱼;鲵鱼", "t": ""}]}, {"meaning": "两眼白色的马。"}, {"meaning": "中医穴位名。指手拇指(或足姆趾)后方的掌(或跖)骨处有明显肌肉隆起,状如鱼腹的部位。", "cites": [{"t": "大渊,鱼后一寸陷者中也,为腧。", "b": "《灵枢经》"}]}, {"meaning": "“渔”的古字。打鱼,捕鱼。", "cites": [{"t": "以佃以鱼。", "b": "《易·系辞下》"}, {"t": "公将如棠观鱼者。", "b": "《左传·隐公五年》"}, {"t": "抛掉一官如粪壤,好随鱼舸此中间。", "b": "宋·孔武仲《自实丰仓归》"}], "words": [{"w": "鱼罟", "t": "鱼网"}, {"w": "鱼户", "t": "捕渔之家"}, {"w": "鱼船", "t": "钓鱼或捕鱼的船只"}, {"w": "鱼钓", "t": "钓鱼"}, {"w": "鱼榔", "t": "捕鱼时用来惊鱼入网的木棒"}, {"w": "鱼舸", "t": "渔船。又作“鱼舲”"}, {"w": "鱼罩", "t": "捕鱼竹罩。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1195wx','兔','1','tù','刀','8','','[{"pinyin": "tù", "defs": [{"meaning": "(象形。象踞后其尾形。本义:哺乳类动物,通称兔子)。"}, {"meaning": "同本义。", "cites": [{"t": "兔,兽名。象踞后其尾形。", "b": "《说文》。其兽前足短后足长,俗字作菟。"}, {"t": "兔舐毫而孕,及其生子,从口而出也。", "b": "《论衡·奇怪》"}, {"t": "肃肃兔罝。", "b": "《诗·召南·兔置》"}, {"t": "兔曰明视。", "b": "《礼记·曲礼》"}, {"t": "兔走触株。", "b": "《韩非子·五蠹》"}, {"t": "冀复得兔。", "b": ""}, {"t": "兔不可复得。", "b": ""}, {"t": "雄兔脚扑朔。", "b": "《乐府诗集·木兰诗》"}, {"t": "雌兔眼迷离。", "b": ""}, {"t": "双兔傍地走。", "b": ""}]}, {"meaning": "古代车制 。舆下方木,伏于毂上轴内两旁,用以承舆者。名优兔,省称为兔。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1196wx','狐','1','hú','犭','8','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从犬,瓜声。本义:狐狸)。"}, {"meaning": "同本义。", "cites": [{"t": "朕狐疑。", "b": "《汉书·文帝纪》。注:“狐性多疑,每渡冰河,且听且渡,故言疑者称狐疑。”"}, {"t": "小狐汔济。", "b": "《易·未济》"}, {"t": "狐鸣呼曰。", "b": "《史记·陈涉世家》"}, {"t": "狐裘不暖锦衾薄。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "狐凭鼠伏。", "b": "《广东军务记》"}], "words": [{"w": "狐丘", "t": "狐穴居之小山"}, {"w": "狐白", "t": "狐腋下的白毛"}, {"w": "狐兔", "t": "狐和兔"}, {"w": "狐仙", "t": "传说狐狸能修炼成仙,化为人形,与人来往。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1197wx','忽','1','hū','心','8','','[{"pinyin": "hū", "defs": [{"meaning": "(形声。从心,勿声。本义:不重视;忽略)。"}, {"meaning": "同本义。", "cites": [{"t": "忽,忘也。", "b": "《说文》"}, {"t": "忽,轻也。", "b": "《广雅·释诂三》"}, {"t": "奈何而忽。", "b": "《汉书·食货志》"}, {"t": "忽于小过。", "b": "《汉书·王嘉传》"}, {"t": "忽于道德。", "b": "《汉书·东平思王宇传》"}, {"t": "不可忽也。", "b": "《聊斋志异·促织》"}], "words": [{"w": "疏忽;忽忘", "t": "忘记"}, {"w": "忽易", "t": "忽略,忽视"}, {"w": "忽睨", "t": "傲视"}, {"w": "忽怠", "t": "轻慢"}, {"w": "忽慢", "t": "轻慢"}, {"w": "忽薄", "t": "轻视。"}]}, {"meaning": "忽然;突然。", "cites": [{"t": "忽逢桃花林。", "b": "晋·陶渊明《桃花源记》"}, {"t": "路转溪头忽见。", "b": "宋·辛弃疾《西江月》诗"}, {"t": "忽闻客大呼。", "b": "明·魏禧《大铁椎传》"}, {"t": "忽一人大呼。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "忽冷忽热;忽明忽暗;忽漫", "t": "忽而,偶然"}, {"w": "忽剌巴", "t": "忽然"}, {"w": "忽儿", "t": "突然,忽然"}, {"w": "忽流", "t": "忽然。"}]}, {"meaning": "急速。", "cites": [{"t": "其亡也忽焉。", "b": "《左传·庄公十一年》"}, {"t": "忽反顾以游目兮。", "b": "《楚辞·离骚》"}], "words": [{"w": "忽眨", "t": "眼睛不停地开闭"}, {"w": "忽焉", "t": "快速的样子"}, {"w": "忽溜", "t": "转动的样子"}, {"w": "忽腾腾", "t": "快迅奔腾的样子"}, {"w": "忽骤", "t": "犹急速。"}]}, {"meaning": "渺茫;辽远;恍忽。", "cites": [{"t": "忽乎吾将行兮。", "b": "《楚辞·屈原·涉江》"}]}, {"meaning": "中国古代的长度和重量单位,1忽等于1/1000分,即等于1/3000厘米或1/20000克。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1198wx','狗','1','gǒu','犭','8','','[{"pinyin": "gǒu", "defs": [{"meaning": "(形声。从犬,句(gōu)声。本义:犬。原指小犬。后为狗犬的通称)。"}, {"meaning": "同本义。", "cites": [{"t": "狗,犬也。大者为犬,小者为狗。", "b": "《说文》"}, {"t": "艮为狗。", "b": "《易·说卦传》"}, {"t": "故斗运狗三月而生也。", "b": "《春秋·考异郵》。注:“狗,斗之精所生也。”"}, {"t": "以狗御蛊。", "b": "《史记·秦本纪》"}, {"t": "效犬者左牵之。", "b": "《礼记·曲礼上》。疏:“大者为犬,小者为狗。”"}, {"t": "悍吏之来吾乡,…哗然而骇者,虽鸡狗不得宁焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "有念“笑人齿缺曰狗窦大开”的。", "b": "《从百草园到三味书屋》"}]}, {"meaning": "古代特指未长毛的小狗崽。", "cites": [{"t": "(犬)未成豪,狗。", "b": "《尔雅》。郝懿行义疏:“狗,大通名。若对文则大者名犬,小者名狗…今亦通名犬为狗矣。”"}, {"t": "貂不足, 狗尾续。", "b": "《晋书》"}]}, {"meaning": "比喻坏人。", "cites": [{"t": "我要早知道这是个狼心狗肺的家伙,当初哪会去管他是死是活", "b": ""}], "words": [{"w": "狗心狗行", "t": "比喻坏心肠、恶劣行为"}, {"w": "狗鼠", "t": "比喻品行卑劣的人。"}]}, {"meaning": "指事之失度或人之失意。", "cites": [{"t": "嘲事之失度、人之失意也曰狗。", "b": "明·顾起元《客座赘语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1199wx','狞','1','níng','犭','8','','[{"pinyin": "níng", "defs": [{"meaning": "弱。", "cites": [{"t": "花楼玉凤声娇狞,海绡红文香浅清。", "b": "唐·李贺《秦王饮酒》"}]}, {"meaning": "忿怒而视。", "cites": [{"t": "他狞起眼睛望着空中,忽然转为忿怒。", "b": "茅盾《子夜》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1200wx','备','1','bèi','夂','8','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从人,備(bèi)声。本义:谨慎、警惕)。"}, {"meaning": "同本义。", "cites": [{"t": "事戒不虞曰知备。", "b": "《大戴礼记·小辨》"}, {"t": "备者,国之重也。", "b": "《墨子·七患》"}, {"t": "且夫备有未至而设之。", "b": "《国语·周语》"}, {"t": "貌若傥荡不备,然心甚谨密。", "b": "《汉书·史丹传》"}], "words": [{"w": "傥荡不备", "t": "行为无拘无束,不谨慎。"}]}, {"meaning": "完备;齐备。", "cites": [{"t": "备,具也。", "b": "《广雅·释诂三》"}, {"t": "易之为书也,广大悉备。", "b": "《易·系辞》"}, {"t": "前人之述备矣。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "众妙毕备。", "b": "《虞初新志·秋声诗自序》"}, {"t": "圣心备焉。", "b": "《荀子·劝学》"}, {"t": "请备述之。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "德才兼备;完备", "t": "齐备。"}]}, {"meaning": "疲乏;困顿。", "cites": [{"t": "修容而以言,耻食以上交,以避农战,外交以备,国之危也。", "b": "《商君书·靳令》"}, {"t": "孔子穷于陈蔡之间,七日不尝食,藜羹不糁,宰予备矣。", "b": "《吕氏春秋·慎人》"}]}, {"meaning": "准备;预备。", "cites": [{"t": "宗人举兽尾告备。", "b": "《仪礼·特牲馈食礼》"}, {"t": "备物以将形。", "b": "《庄子·庚桑楚》"}, {"t": "犹得备晨炊。", "b": "唐·杜甫《石壕吏》"}, {"t": "居安思危,思则有备,有备无患。", "b": "《左传·襄公十一年》"}, {"t": "有奇字素无备者,旋刻之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "又备经年裹物之用。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "备马;备他充饥;备办;备课", "t": ""}]}, {"meaning": "防备;戒备。", "cites": [{"t": "无所不备,则无所不寡。", "b": "《孙子·虚实》"}, {"t": "远主备之,无乃不可乎。", "b": "《左传·僖公三十三年》"}, {"t": "备他盗之出入与非常也。", "b": "《史记·项羽本记》"}], "words": [{"w": "守备", "t": "防守戒备"}, {"w": "备水", "t": "防备水患"}, {"w": "备灾;备患", "t": "防备祸患。"}]}, {"meaning": "储备。", "cites": [{"t": "而设法备贮弹药。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "备料;备藏", "t": "收藏。"}]}, {"meaning": "提供或装备。", "cites": [{"t": "事异则备变。", "b": "《韩非子·五蠹》"}], "words": [{"w": "所需各种农业机械无一不备;备榜", "t": "张榜;出榜。"}]}, {"meaning": "凑数;充数。", "cites": [{"t": "吾尝备位将相。", "b": "《汉书·萧望之传》"}], "words": [{"w": "备位", "t": "居官的自谦之词"}, {"w": "备员", "t": "凑数,充数。"}]}, {"meaning": "设备;设施。", "cites": [{"t": "故事因于世而备适于事。", "b": "《韩非子·五蠹》"}]}, {"meaning": "又。", "cites": [{"t": "论世之事,因为之备。", "b": ""}], "words": [{"w": "军备;装备", "t": ""}]}, {"meaning": "全部;完全;尽。", "cites": [{"t": "农事备收。", "b": "《礼记·月令》"}, {"t": "诸侯备闻此言。", "b": "《左传·成公十三年》"}, {"t": "备极欢洽。", "b": "《广东军务记》"}, {"t": "备极护爱。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1201wx','饰','1','shì','饣','8','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从巾,从人,食声。人佩巾有装饰作用。本义:刷拭)。"}, {"meaning": "同本义。", "cites": [{"t": "饰,刷也。", "b": "《说文》。按,字亦作拭。"}, {"t": "凡祭祀,饰其牛牲。", "b": "《周礼·地官·封人》"}]}, {"meaning": "装饰;修饰。", "cites": [{"t": "运而有光者,饰也。", "b": "《大戴礼记·劝学》"}, {"t": "共粉饰之,如嫁女床席。", "b": "《史记·滑稽列传》"}, {"t": "豹饰。", "b": "《礼记·玉藻》"}, {"t": "君子不以绀緅饰。", "b": "《论语》"}, {"t": "饰以篆文、山龟鸟兽之形。", "b": "《后汉书·张衡传》"}, {"t": "若稍饰以楼观亭榭,与江山相发挥,自当高出金山之上矣。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "饰车", "t": "有彩漆文饰之车。大夫以上所乘"}, {"w": "饰说", "t": "修饰美巧的文辞。"}]}, {"meaning": "掩饰,粉饰。", "cites": [{"t": "辩足以饰非。", "b": "《庄子·盗跖》"}, {"t": "饰省宣义。", "b": "《史记·秦皇纪》。正义:谓文饰也。”"}, {"t": "皆以情对,不能隐饰。", "b": "《汉书·范谤传》"}], "words": [{"w": "饰非", "t": "明知其过失而加以掩饰"}, {"w": "饰诈", "t": "矫饰诈伪"}, {"w": "饰智", "t": "设巧使诈以欺骗他人"}, {"w": "饰过", "t": "掩饰过失"}, {"w": "饰伪", "t": "矫饰和虚伪"}, {"w": "饰非遂过", "t": "知过不改而更加掩饰,因使错误形成。"}]}, {"meaning": "表扬,奖励。", "cites": [{"t": "上以饰贤良,下以养百姓而安乐之。", "b": "《荀子·王制》"}], "words": [{"w": "饰终", "t": "古代表扬死者尊荣的典礼"}, {"w": "饰擢", "t": "奖励才能之士并加以拔擢任用。"}]}, {"meaning": "整饬;整治。", "cites": [{"t": "凡祭祀饰其牛牲。", "b": "《周礼·地官·封人》"}, {"t": "欲民之有耻,则小耻不可不饰也。", "b": "《管子·权修》"}, {"t": "王者之人饰动以礼义。", "b": "《荀子·王制》"}, {"t": "古者大国过小邑,小邑必饰城而请罪。", "b": "《谷梁传·襄公二十五年》"}, {"t": "以饰法设刑,而天下治。", "b": "贾谊《过秦论》"}]}, {"meaning": "饰物,装饰品。", "cites": [{"t": "青黄刻镂之饰。", "b": "《墨子·辞过》"}, {"t": "同舍生皆披绮绣,戴朱缨宝饰之帽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "首饰;衣饰;花饰;窗饰;饰巾", "t": "戴头巾为饰,而不加冠冕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1202wx','饱','1','bǎo','饣','8','','[{"pinyin": "bǎo", "defs": [{"meaning": "(形声。从食,包声。本义:吃足)。"}, {"meaning": "同本义。与“饥”相对。", "cites": [{"t": "饱,厌也。", "b": "《说文》"}, {"t": "饱,满也。", "b": "《广雅》"}, {"t": "既醉既饱。", "b": "《诗·小雅·执竞》"}, {"t": "乐岁(丰年)终身饱。", "b": "《孟子·梁惠王上》"}, {"t": "食不饱,力不足。", "b": "唐·韩愈《杂说》"}, {"t": "生为之饱。", "b": "清·周容《芋老人传》"}], "words": [{"w": "酒足饭饱;饱食暖衣", "t": "吃得饱,穿得暖。比喻生活富裕安乐。"}]}, {"meaning": "充足,多。", "cites": [{"t": "有学饱而才馁,有才富而学贫。", "b": "《文心雕龙·事类》"}], "words": [{"w": "饱参", "t": "参悟真理甚多。"}]}, {"meaning": "满足。", "cites": [{"t": "既醉以酒,既饱以德。", "b": "《诗·大雅·既醉》"}], "words": [{"w": "一饱眼福;饱德", "t": "饱足以德,备受德惠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1203wx','饲','1','sì','饣','8','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从食,司声。本义:给人吃,喂食。本作“食”)。"}, {"meaning": "同本义。", "cites": [{"t": "屈指计归,张颐待饲。", "b": "《旧唐书》"}]}, {"meaning": "粮食。", "cites": [{"t": "饲,粮也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1204wx','变','1','biàn','又','8','','[{"pinyin": "biàn", "defs": [{"meaning": "(形声。从攴(pū),孌(luán)声。本义:变化,改变)。"}, {"meaning": "同本义。", "cites": [{"t": "变,更也。", "b": "《说文》"}, {"t": "变,易也。", "b": "《小尔雅》"}, {"t": "变者,非常也。", "b": "《白虎通》"}, {"t": "一阖一辟谓之变。", "b": "《易·系辞》"}, {"t": "病变而药不变。", "b": "《吕氏春秋·察今》"}, {"t": "于是宾客无不变色离席。", "b": "《虞初新志·秋声诗自序》"}, {"t": "无下有变…百姓熟敢不箪食壶浆以迎将军者乎?", "b": "《三国志·诸葛亮传》"}, {"t": "不得已,变姓名。", "b": "宋·文天祥《指南录·后序》。"}], "words": [{"w": "变文协韵", "t": "古文修辞术语。用变换文字或颠倒词序等手段使句子的音调和谐"}, {"w": "天气突变;巨变", "t": "巨大的变化"}, {"w": "变豹", "t": "即豹变,指人发迹而富贵"}, {"w": "变宫", "t": "中国古代七音的一种。即宫的变声,比高宫低半音。"}]}, {"meaning": "变通。", "cites": [{"t": "善言而不知变,未可谓能说也。", "b": "汉·桓宽《盐铁论》"}]}, {"meaning": "发动事变。", "cites": [{"t": "待吕氏变而共诛之。", "b": "《汉书·高后纪》"}], "words": [{"w": "变谋", "t": "变乱的图谋"}, {"w": "变震", "t": "变乱震惊。"}]}, {"meaning": "事变,有重大影响的突发事件。", "cites": [{"t": "变遂发。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "哗变", "t": "称军队突然叛变"}, {"w": "变事", "t": "突然发生的重大事件。"}]}, {"meaning": "灾异,异常的自然现象。", "cites": [{"t": "灾异愈甚,天变成形。", "b": "《汉书·五行志》"}, {"t": "天变不足畏。", "b": "《宋史·王安石传》"}], "words": [{"w": "变怪", "t": "灾变怪异。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1205wx','京','1','jīng','亠','8','','[{"pinyin": "jīng", "defs": [{"meaning": "(象形。甲骨文字形,象筑起的高丘形,上为耸起的尖端。本义:人工筑起的高土堆)。"}, {"meaning": "同本义。", "cites": [{"t": "京,人所为绝京丘也。", "b": "《说文》"}, {"t": "辨京陵。", "b": "《左传·襄公二十五年》"}, {"t": "筑重京。", "b": "《淮南子·览冥》"}, {"t": "为京邱若山陵。", "b": "《吕氏春秋·禁塞》"}, {"t": "乃觏于京。", "b": "《诗·大雅·公刘》"}, {"t": "于堑里筑京,皆高五六丈。", "b": "《三国志·公孙瓒传》"}]}, {"meaning": "国都。", "cites": [{"t": "念彼京师。", "b": "《诗·曹风·下泉》"}, {"t": "辞帝京。", "b": "白居易《琵琶行》"}, {"t": "迁我京职。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "京中有善口技者。", "b": "明·高启《书博鸡者事》"}, {"t": "至京。", "b": "清·周容《芋老人传》"}, {"t": "君之始入京也。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "京吏", "t": "京师各衙门的都吏。别于外吏而言"}, {"w": "京圻", "t": "京都"}, {"w": "京府", "t": "京畿。京城和京都附近的地方;国都所在地"}, {"w": "京仓", "t": "京师储粮的地方。"}]}, {"meaning": "京族。"}, {"meaning": "", "cites": [{"t": "乘钜鳞,骑京鱼。", "b": "《汉书·扬雄传上》"}], "words": [{"w": "京鱼", "t": "鲸鱼。"}]}, {"meaning": "古代数目名十兆为京,一说万万兆为京。古代数位序列是:万、亿、兆、京。十兆为京。", "cites": [{"t": "京垓岁之中。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "京垓", "t": "古代以十兆为京,十京为垓。极言众多。"}]}, {"meaning": "春秋时邑名,汉置京县 。故城在今河南省荥阳县东南二十余里。"}, {"meaning": "大,盛。", "cites": [{"t": "京,大也。燕之北鄙,东楚之郊,或谓之京。", "b": "《方言一》"}, {"t": "京,大也。", "b": "《尔雅》"}, {"t": "裸将于京。", "b": "《诗·大雅·文王》"}, {"t": "曰嫔于京。", "b": "《诗·大雅·大明》"}, {"t": "莫之与京。", "b": "《左传·庄公二十二年》"}, {"t": "京邑翼翼。", "b": "张衡《东京赋》"}, {"t": "发京仓。", "b": ""}, {"t": "京师者何?天子之居也。京者何?大也。", "b": "《公羊传·桓公九年》。朱骏声曰:“京大师众也。”"}], "words": [{"w": "京鞋", "t": "华美而样式新颖的鞋"}, {"w": "京仓", "t": "大粮仓。朱骏声曰:“京大师众也”"}, {"w": "京庾", "t": "大粮仓"}, {"w": "京枣", "t": "大枣。"}]}, {"meaning": "悲痛的。", "cites": [{"t": "忧心京京。", "b": "《诗·小雅·正月》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1206wx','享','1','xiǎng','亠','8','','[{"pinyin": "xiǎng", "defs": [{"meaning": "(会意。本作“亯”。从“高”省,“曰”象进献熟物形。本义:祭献,上供。用物品进献人,供奉鬼神使其享受)。"}, {"meaning": "同本义。", "cites": [{"t": "享,献也。", "b": "《说文》"}, {"t": "享于祖考。", "b": "《诗·小雅·信南山》"}, {"t": "是用孝享。", "b": "《诗·小雅·天保》"}, {"t": "以享以祀。", "b": "《诗·小雅·楚茨》"}, {"t": "诸侯侯以享天子。", "b": "《考工记·玉人》"}, {"t": "王用享于西山。", "b": "《易·随》"}, {"t": "享尝乃止。", "b": "《礼记·祭法》"}, {"t": "相夺予享。", "b": "《左传·僖公三十一年》"}, {"t": "兹予大享于先王。", "b": "《书·盘庚》"}, {"t": "杀牛宰马,祭天享地。", "b": "《西游记》"}], "words": [{"w": "享厅", "t": "供奉祖宗木主或神佛偶像的地方"}, {"w": "享牛", "t": "供祭祀的牛。"}]}, {"meaning": "人享受福禄。", "cites": [{"t": "大臣享其禄。", "b": "《国语·周语》"}, {"t": "而享其生禄。", "b": "《左传·僖公三十三年》"}, {"t": "子孙享之。", "b": "《刘熊碑》"}, {"t": "享无穷逸致。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "不享其利。", "b": "清·黄宗羲《原君》"}, {"t": "受享无穷。", "b": ""}, {"t": "滋味之享。", "b": "明·宋濂《送东阳马生序》"}, {"t": "常只是遇节令,设蔬品奉祭,未卜享否?", "b": "《西游记》"}], "words": [{"w": "享强寿", "t": "享受到长寿之年"}, {"w": "共享太平", "t": ""}]}, {"meaning": "献,像进贡那样地交付、献出。", "cites": [{"t": "莫敢不来享。", "b": "《诗·商颂·殷武》"}], "words": [{"w": "享觐", "t": "朝见天子进献贡品"}, {"w": "享礼;享上", "t": "奉承上级。"}]}, {"meaning": "鬼神享用祭品。", "cites": [{"t": "如是,则非德,民不和,神不享矣。", "b": "《左传·僖公五年》"}, {"t": "使之主祭而百神享之,是天受之。", "b": "《孟子》"}]}, {"meaning": "宴请,以酒食待客", "cites": [{"t": "止而享之。", "b": "《左传·庄公四年》"}, {"t": "享齐戌。", "b": "《左传·庄公十七年》"}, {"t": "享卫灵公。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "享食", "t": "飨宴"}, {"w": "享客;享祠", "t": "宴饷"}, {"w": "享宴", "t": "宴飨"}, {"w": "享道", "t": "饮食之仪规。"}]}, {"meaning": "适应。", "cites": [{"t": "自非圣贤国,谁能享休斯。", "b": "《文选·王粲·从军诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1207wx','庞','1','páng','广','8','','[{"pinyin": "páng", "defs": [{"meaning": "(形声。从广,龙声。广(yǎn),象高屋形。本义:高屋)。"}, {"meaning": "同本义。", "cites": [{"t": "庞,高屋也。", "b": "《说文》。段玉裁注:“谓屋之高者也,故字从广。”"}]}, {"meaning": "多而杂乱的。", "cites": [{"t": "邑居庞杂,号为难理。", "b": "《旧唐书·李勉传》"}], "words": [{"w": "庞杂;庞鸿", "t": "天地元气浑成未分,宇宙浑然一体的样子"}, {"w": "庞眉", "t": "眉毛又粗又黑。"}]}, {"meaning": "高大。", "cites": [{"t": "湛恩庞洪。", "b": "《汉书·司马相如传》。注:“厚大也。”"}, {"t": "庞眉皓首无住著。", "b": "杜甫《戏为韦偃双松图歌》"}, {"t": "成视之,庞然修伟。", "b": "《聊齐志异·促织》"}]}, {"meaning": "厚实。", "cites": [{"t": "四牡庞庞。", "b": "《诗·车攻》"}], "words": [{"w": "庞庞", "t": "厚实的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1208wx','店','1','diàn','广','8','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从广(yǎn),占声。从“广”,表示与房屋有关。本义:栈房)。"}, {"meaning": "同本义。", "cites": [{"t": "肆,所以陈货鬻之物也;店,所以置货鬻之物也。", "b": "晋·崔豹《古今注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1209wx','夜','1','yè','夕','8','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。金文字形。从月,亦声。本义:从天黑到天亮的时间)。"}, {"meaning": "同本义。", "cites": [{"t": "夜,舍也。天下休舍也。", "b": "《说文》"}, {"t": "夜,暮也。", "b": "《广雅》"}, {"t": "夜呼旦。", "b": "《周礼·鸡人》。注:“夜,夜漏未尽,鸡鸣时也。”"}, {"t": "辛卯夜,恒星不见。", "b": "《左传·庄公七年》。疏;“夜者自昏至旦之总名。”"}, {"t": "夜者阴。", "b": "《周髀算经》"}, {"t": "夙兴夜寐,靡有朝矣。", "b": "《诗·卫风·氓》"}, {"t": "昨夜见军帖。", "b": "《乐府诗集·木兰诗》"}, {"t": "三日三夜。", "b": "《世说新语·自新》"}]}, {"meaning": "黄昏,天黑。", "cites": [{"t": "岂不夙夜?谓行多露。", "b": "《诗·召南·行露》"}, {"t": "行者怏怏自退,看看日色早已夜了。便道此时将暗,也寻不见师父,不如把几面镜子细看一回。", "b": "《西游补》"}]}, {"meaning": "凌晨,天快要亮的时候。", "cites": [{"t": "郑玄注:“夜,夜漏未尽鸡鸣时也。”", "b": ""}]}, {"meaning": "晦暝,幽暗。", "cites": [{"t": "是故索物于夜室者,莫良于火;索道于当世者,莫良于典。", "b": "《潜夫论》"}], "words": [{"w": "夜室", "t": "黑暗的房间;墓穴"}, {"w": "夜台", "t": "夜庭。坟墓。亦借指阴间"}, {"w": "夜府", "t": "犹夜台,墓穴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1210wx','庙','1','miào','广','8','','[{"pinyin": "miào", "defs": [{"meaning": "(形声。从广(yǎn),朝声。“广”与建筑物有关。本义:宗庙,供奉祭祀祖先的处所)。"}, {"meaning": "同本义。", "cites": [{"t": "廟,尊先祖貌也。", "b": "《说文》。按,当作宗庙尊先祖貌也。"}, {"t": "庙祧坛墠,鬼祭先祖也。", "b": "《广雅·释天》"}, {"t": "室有东西厢曰庙,无曰寝。", "b": "《尔雅·释宫》"}, {"t": "寝庙必备。", "b": "《礼记·月令》。注:“前曰庙,后曰寝。”"}, {"t": "复于小庙。", "b": "《周礼·祭仆》。注:“高祖以下也。始祖曰大庙。”"}, {"t": "太庙,天子明堂。", "b": "《礼记·明堂位》。按,周制:天子七庙,…诸侯五庙,大夫三庙,士一庙。"}, {"t": "庙成。", "b": "《战国策·齐策四》"}, {"t": "一夫作难而七庙堕。", "b": "贾谊《过秦论》"}, {"t": "庙在山之西蔍,额曰“惠济”。", "b": "陆游《过小孤山大孤山》"}, {"t": "至八月朝,诣庙中坐。", "b": "《搜神记》"}, {"t": "藏之于庙。", "b": "宋·欧阳修《伶官传》序"}], "words": [{"w": "少年告庙;庙视道士", "t": "庙中管香火的道人"}, {"w": "庙主", "t": "庙中的牌位;总管全庙事务的僧道"}, {"w": "庙见", "t": "新妇谒见祖庙"}, {"w": "庙祝", "t": "管庙里香火的人"}, {"w": "庙貌", "t": "宗庙中供奉的祖先像"}, {"w": "庙堂", "t": "宗庙"}, {"w": "庙社", "t": "宗庙和社稷。"}]}, {"meaning": "古时供奉神佛的处所。", "cites": [{"t": "林教头风雪山神庙。", "b": "《水浒传》"}, {"t": "庙在山之西。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "庙有小姑像;小艇游庙中;方立庙门;土地庙;城隍庙", "t": ""}]}, {"meaning": "古时供奉祭祀历史上有名人物的处所。", "cites": [{"t": "诏为亮立庙于沔阳。", "b": "《三国志》"}], "words": [{"w": "文庙", "t": "孔庙"}, {"w": "武庙", "t": "关公庙"}, {"w": "岳庙", "t": ""}]}, {"meaning": "“朝廷”的代称。", "cites": [{"t": "居庙堂之高,则忧其民。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "庙算", "t": "朝廷议定的克敌谋略"}, {"w": "庙谋", "t": "朝廷的谋略"}, {"w": "庙朝", "t": "专指朝廷"}, {"w": "庙略", "t": "朝廷的谋略"}, {"w": "庙廊", "t": "朝廷;借指天子。"}]}, {"meaning": "古代贵族住房的前厅,王宫和庙宇的前殿都称庙。", "cites": [{"t": "宫前曰庙,后曰寝。今王宫之前殿,士大夫之听事是也。", "b": "《六书故》"}]}, {"meaning": "已死皇帝在宗庙中的称呼。", "cites": [{"t": "及英庙崩,溥预有入阁之喜。", "b": "《典故纪闻》"}], "words": [{"w": "庙号;庙讳", "t": ""}]}, {"meaning": "祭祀;立庙祭祖。", "cites": [{"t": "(季春之月)以共郊庙之服。", "b": "《吕氏春秋》"}], "words": [{"w": "庙祀", "t": "即太祝;立庙奉祀"}, {"w": "庙食", "t": "谓死后立庙,受人奉祀,享受祭飨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1211wx','府','1','fǔ','广','8','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从广(yǎn),表示与房屋有关,付声。本义:府库,府藏。古时国家收藏文书或财物的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "府,文书藏也。", "b": "《说文》"}, {"t": "开府库,出币帛。", "b": "《淮南子·时则》"}, {"t": "在府言府。", "b": "《礼记·曲礼》"}, {"t": "籍吏民,封府库,而待将军。", "b": "《史记·项羽本纪》"}, {"t": "以问公卿,亦以为虚费府帑。", "b": "《汉书·匈奴传》"}, {"t": "遇有水旱疾疫,则开仓廪悉府库以赈之。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "府室", "t": "国家书库"}, {"w": "府库", "t": "官府储存财物、兵甲的仓库"}, {"w": "府实", "t": "府库中的财物"}, {"w": "府帑", "t": "国库;国库所藏的金帛"}, {"w": "府钱", "t": "府库的钱财。"}]}, {"meaning": "官署。汉至南北朝多指高级官员及诸王治事之所。", "cites": [{"t": "以八法治官府。", "b": "《周礼·太宰》。注:“百官所居曰府。”"}, {"t": "宫中府中,俱为一体。", "b": "诸葛亮《出师表》"}, {"t": "缙绅大夫士萃于左丞相府,莫知计所出。", "b": "宋·文天祥《< 指南录>后序》"}], "words": [{"w": "府上", "t": "官府,衙门;今尊称对方家宅或家乡"}, {"w": "府厅", "t": "官署的厅堂"}, {"w": "府朝", "t": "官署;王府"}, {"w": "府幕", "t": "府署的幕僚。"}]}, {"meaning": "脏腑。", "cites": [{"t": "所谓上喘而为水者,阴气下而复上,上则邪客于藏府间,故为水也。", "b": "《素问》"}]}, {"meaning": "又。", "cites": [{"t": "五藏已伤,六府不通。", "b": ""}], "words": [{"w": "六府", "t": "中医指胃、小肠、大肠、膀胱、胆和三焦。"}]}, {"meaning": "屈身,低头,与“仰”相对。", "cites": [{"t": "王府而视之,其宫榭若累块积苏焉。", "b": "《列子·周穆王》"}], "words": [{"w": "府然", "t": "屈身、低头的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1212wx','底','1','de dǐ','广','8','','[{"pinyin": "de", "defs": [{"meaning": "“底”在五四时期至三十年代用于领属关系,现已不用。"}]}, {"pinyin": "dǐ", "defs": [{"meaning": "(形声。从广(yǎn),氐(dǐ)声。本义:止住;停滞)。"}, {"meaning": "同本义。", "cites": [{"t": "底,止居也。", "b": "《说文》"}, {"t": "勿使有壅蔽湫底。", "b": "《左传·昭公元年》"}]}, {"meaning": "又。", "cites": [{"t": "底禄以德。", "b": ""}, {"t": "有所底止。", "b": "《左传·宣公三年》"}, {"t": "盟以底信。", "b": "《左传·昭公十三年》"}, {"t": "戾久将底。", "b": "《国语·晋语》"}], "words": [{"w": "底止", "t": "结局"}, {"w": "底着", "t": "停滞;滞留"}, {"w": "底遏", "t": "遏止"}, {"w": "底滞", "t": "滞留。"}]}, {"meaning": "最下面,底端。", "cites": [{"t": "底,一曰下也。", "b": "《说文》"}, {"t": "实惟无底之谷。", "b": "《列子·汤问》"}, {"t": "则言黄泉之底。", "b": "《淮南子·脩务》"}, {"t": "清澈见底。", "b": "明·袁宏道《满井游记》"}, {"t": "全石以为底。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "疑问代词。何,什么。", "cites": [{"t": "底处飞双燕,衔泥上药栏。", "b": "宋范成大《双燕》"}], "words": [{"w": "底作", "t": "何为,干什么"}, {"w": "底事", "t": "何事"}, {"w": "底物", "t": "何物"}, {"w": "底处", "t": "何处"}, {"w": "底许", "t": "几许,多少。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1213wx','疟','1','nüè yào','疒','8','','[{"pinyin": "nüè", "defs": [{"meaning": "(形声。从疒(chuáng),虐声。本义:病名,即疟疾)。"}, {"meaning": "同本义。", "cites": [{"t": "疟者,风寒之气不常也。", "b": "《素问·疟论》"}, {"t": "许悼公疟。", "b": "《左传·昭公十九年》"}, {"t": "疟,寒热休作。", "b": "《说文》"}, {"t": "疟,酷虐也。凡疾或寒或热耳,而此疾先寒后热两疾,似酷虐者也。", "b": "《释名、释疾病》"}, {"t": "狂诵新诗驱疟鬼。", "b": "陆游《寓叹》"}], "words": [{"w": "疟病", "t": "疟疾"}, {"w": "疟患", "t": "疟病的祸患"}, {"w": "疟寒", "t": "疟病"}, {"w": "疟疠", "t": "疟疾;疟疫。"}]}, {"meaning": "残暴;灾害。", "cites": [{"t": "静作相养,德疟相成。", "b": "《马王堆汉墓帛书》"}]}]}, {"pinyin": "yào", "defs": [{"meaning": "——义同“疟”(nüè),只用于“疟子”(yàozi)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1214wx','疙','1','gē','疒','8','','[{"pinyin": "gē", "defs": [{"meaning": "——如:疙蹅蹅(象声词。敲击器物的声音);疙皱(蹙眉。表示烦恼、发愁);疙颤颤(抖动摇晃的样子;颤巍巍);疙秃(头上突起的疮疖)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1215wx','疚','1','jiù','疒','8','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,久声。本义:久病)。"}, {"meaning": "同本义。", "cites": [{"t": "无饥馑疾疚祸罪之殃。", "b": "《韩非子》"}], "words": [{"w": "疚病", "t": "疾病"}, {"w": "疚疾", "t": "疾病"}, {"w": "疚头怪脑", "t": "丑头怪脸的样子。"}]}, {"meaning": "贫穷。", "cites": [{"t": "维昔之富不如时,维今之疚不如兹。", "b": "《诗·大雅·召旻》"}]}, {"meaning": "缺陷。", "cites": [{"t": "行刑不疚。(不疚,无弊病。)", "b": "《国语·晋语》"}, {"t": "令章靡疚,亦善之亚。", "b": "《文心雕龙》"}]}, {"meaning": "害;灾殃。", "cites": [{"t": "行刑不疚。(不疚,无弊病。)", "b": "《国语·晋语》"}, {"t": "刚中正,履帝位而不疚,光明也。", "b": "《易·履》"}]}, {"meaning": "因有过失而感到内心惭愧痛苦。", "cites": [{"t": "使我心疚。", "b": "《诗·小雅·大东》"}], "words": [{"w": "疚怀", "t": "内心不安。同疚心"}, {"w": "疚惭", "t": "犹疚愧"}, {"w": "疚悔", "t": "因负疚而后悔"}, {"w": "疚负", "t": "犹过失"}, {"w": "疚恶", "t": "犹错误。"}]}, {"meaning": "困惑。", "cites": [{"t": "设之以国家之患而不疚。", "b": "《国语》"}, {"t": "行前定则不疚。道前定则不穷。", "b": "《孔子家语》"}]}, {"meaning": "败坏;伤害。", "cites": [{"t": "西方之书有之曰:“怀与安,实疚大事。”", "b": "《国语》"}, {"t": "今有负其子而汲者,队其子于井中,其母必从而道之。今岁凶民饥道饿,此疚重于队其子,其可无察邪?", "b": "《墨子》"}]}, {"meaning": "居丧。", "cites": [{"t": "自仲秋而在疚兮,逾履霜以践冰。", "b": "潘岳《寡妇赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1216wx','剂','1','jì','刂','8','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。从刀,齐声。“齐”亦兼表字义。本义:剪齐)。"}, {"meaning": "同本义。", "cites": [{"t": "剂,齐也。", "b": "《说文》"}, {"t": "剂,剪齐也。", "b": "《后汉书·刘梁传》注"}, {"t": "其命剂也。", "b": "《太玄·永》。注:“剪绝也。”"}, {"t": "永不轨,其命剂也。", "b": "《太玄·永》"}, {"t": "剂,剪齐也。", "b": "《尔雅》。郭璞注:“南方人呼剪刀为剂刀。”"}]}, {"meaning": "割。", "cites": [{"t": "豫让剂面而变容,吞炭为哑。", "b": "《新书》"}]}, {"meaning": "调节;调和。", "cites": [{"t": "家之所有为剂。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "调剂;剂和", "t": "调药;调和"}, {"w": "剂救", "t": "调和弥补"}, {"w": "剂调", "t": "调节。"}]}, {"meaning": "古代买卖时用的契券。", "cites": [{"t": "以两剂禁民狱。", "b": "《周礼·大司寇》。注:“今券书也。”"}, {"t": "正之以傅别约剂。", "b": "《周礼·士师》。注:“各所持券也。”"}, {"t": "听买卖以质剂。", "b": "《周礼·小宰》。注:“谓两书一札,同而别之,长曰质,短曰剂。”"}, {"t": "大市以质,小市以剂。", "b": "《周礼》"}]}, {"meaning": "分剂,一定的分量。", "cites": [{"t": "又精方药,其疗疾,合汤不过数种,心解分剂,不复称量。", "b": "《三国志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1217wx','卒','1','cù zú','十','8','','[{"pinyin": "cù", "defs": [{"meaning": "仓促,急速。", "cites": [{"t": "行西逾陇卒。", "b": "《汉书·食货志》。注:“仓卒也。”"}, {"t": "兴卒暴之作。", "b": "《汉书·成帝纪》"}, {"t": "而卒惶急无以击轲,而乃以手共搏之。", "b": "《战国策·燕策》"}], "words": [{"w": "卒拔", "t": "仓猝攻取"}, {"w": "卒迫", "t": "仓促紧迫。"}]}, {"meaning": "突然。", "cites": [{"t": "则亡以应卒。", "b": "《汉书·辛庆忌传》"}, {"t": "卒然边境有急,数千百万之众,国胡以馈之?", "b": "贾谊《论积贮疏》"}], "words": [{"w": "卒倒", "t": "突然晕倒"}, {"w": "卒暴", "t": "突然"}, {"w": "卒然", "t": "忽然,突然。"}]}]}, {"pinyin": "zú", "defs": [{"meaning": "(指事。小篆字形,在“衣”上加一点标记,表示穿这种衣服的人。本义:古代供隶役穿的一种衣服。衣上著有标记,以区别于常人)。"}, {"meaning": "同本义。", "cites": [{"t": "卒,隶人给事者为卒。卒,衣有题识者。", "b": "《说文》"}]}, {"meaning": "古代供驱遣从事一定劳役的奴隶。后用为低级差役的称呼。", "cites": [{"t": "悉发卒数万人穿漕渠,三岁而通。", "b": "《史记》"}], "words": [{"w": "卒奴", "t": "奴婢。"}]}, {"meaning": "步兵。", "cites": [{"t": "在车曰士,步曰卒。", "b": "《吕氏春秋·简选》注"}, {"t": "缮甲兵,具卒乘。", "b": "《左传·隐公元年》"}, {"t": "魏氏之武卒不可以遇秦之锐士。", "b": "《荀子·议兵》"}]}, {"meaning": "后泛指士兵。", "cites": [{"t": "每得降卒必亲引问之。", "b": "宋·司马光《资治通鉴·唐纪》"}, {"t": "羸老之卒。", "b": ""}, {"t": "守门卒。", "b": ""}, {"t": "印度卒。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "卒兵", "t": "士兵"}, {"w": "卒乘", "t": "士兵与战车;后泛指军队"}, {"w": "卒徒", "t": "徒众;兵众。"}]}, {"meaning": "春秋时地方一级居民单位名,同时也是一级军队编制名。", "cites": [{"t": "全卒为上。", "b": "《孙子·谋攻》"}, {"t": "破卒次之", "b": ""}], "words": [{"w": "卒长", "t": "古代军队百人为卒,其长官称卒长"}, {"w": "卒伍", "t": "五人为伍,百人为卒。也泛指军队、行伍"}, {"w": "卒列", "t": "行列。"}]}, {"meaning": "古代天子统率诸侯的一级组织名。三十国为卒。", "cites": [{"t": "三十国以为卒,卒有正。", "b": "《礼记》"}]}, {"meaning": "春秋时军队中百人的指挥者。", "cites": [{"t": "卒必力…卒不力,无以承训。", "b": "《逸周书》"}]}, {"meaning": "末尾,结局。", "cites": [{"t": "有始有卒者,其惟圣人乎!", "b": "《论语》"}]}, {"meaning": "棋子。"}, {"meaning": "终止;尽,完毕。", "cites": [{"t": "人始于生而卒于死。", "b": "《韩非子·解老》"}, {"t": "无衣无褐,何以卒岁?", "b": "《诗·豳风·七月》"}], "words": [{"w": "卒其事;卒时", "t": "尽时"}, {"w": "卒读", "t": "尽读。"}]}, {"meaning": "古代指大夫死亡,后为死亡的通称。", "cites": [{"t": "大夫曰卒。", "b": "《公羊传·隐公三年》"}, {"t": "我独不终。", "b": "《诗·小雅·蓼莪》"}, {"t": "永和四年卒。", "b": "《后汉书·张衡传》"}, {"t": "初,鲁肃闻刘表卒。", "b": "《资治通鉴》"}, {"t": "居正已卒。", "b": "《明史》"}, {"t": "卒官。", "b": ""}, {"t": "卒时。", "b": ""}], "words": [{"w": "暴卒;病卒;生卒年月", "t": ""}]}, {"meaning": "停止。", "cites": [{"t": "三饭卒食,赞洗爵酌。", "b": "《仪礼》"}, {"t": "三日五哭卒。", "b": "《礼记》"}]}, {"meaning": "终究;终于。", "cites": [{"t": "卒廷见相如。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "卒相与欢。", "b": ""}, {"t": "故卒不加诛。", "b": "汉·刘向《列女传》"}, {"t": "卒葬之。", "b": "宋·王安石《游褒禅山记》"}, {"t": "卒不赦程。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "卒与尸合。(头终于同尸身合在一起。)", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "卒然", "t": "终于,最后"}, {"w": "卒爵", "t": "最后一杯。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1218wx','郊','1','jiāo','阝','8','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从邑,交声。从“邑”,表示与城郭、行政区域有关。本义:上古时代国都外百里以内的地区称“郊”)。"}, {"meaning": "郊区。", "cites": [{"t": "郊,距国百里为郊。", "b": "《说文》。按,周时距离国都五十里的地方叫近郊,百里的地方叫远郊。"}, {"t": "适彼乐郊。", "b": "《诗·魏风·硕鼠》"}, {"t": "素服郊次。", "b": "《左传·僖公三十二年》"}, {"t": "洒江郊。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "始知郊田。", "b": "明·袁宏道《满井游记》"}, {"t": "邑外谓之郊。", "b": "《尔雅·释地》"}, {"t": "郊二旬。", "b": "《周礼·质人》。注:“远郊也。”"}, {"t": "至于郊。", "b": "《仪礼·觐礼》。注:“谓近郊。”"}], "words": [{"w": "郊祀", "t": "古时帝王在郊外祭祀天地"}, {"w": "郊圻", "t": "城邑的疆界。圻,地界"}, {"w": "郊里", "t": "郊外的村落。"}]}, {"meaning": "田野。", "cites": [{"t": "地可垦辟,悉为农郊,以赡萌。", "b": "《文选·司马相如·上林赋》"}]}, {"meaning": "古代祭天地的典礼。", "cites": [{"t": "郊社所从来尚矣。", "b": "《史记·封禅书》"}], "words": [{"w": "初郊", "t": "初即位而祀天"}, {"w": "郊社", "t": "祭天地"}, {"w": "郊赦", "t": "天子祭天于郊,而特赦天下的囚犯"}, {"w": "郊畤", "t": "祭天的地方。畤,神灵居止之处。"}]}, {"meaning": "古地名 。春秋晋地。在今山西省运城县境。"}, {"meaning": "在郊区住。", "cites": [{"t": "牛山之木尝美矣,以其郊于大国也。斧斤伐之,可以为美乎?", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1219wx','庚','1','gēng','广','8','','[{"pinyin": "gēng", "defs": [{"meaning": "天干的第七位,与地支相配,用以纪年、月、日。", "cites": [{"t": "庚,位西方。", "b": "《说文》"}, {"t": "先庚三日,后庚三日。", "b": "《易·巽》"}, {"t": "太岁在庚日上章,月在庚曰窒。", "b": "《尔雅》"}, {"t": "其日庚辛。", "b": "《淮南子》"}, {"t": "秋,日庚、辛。", "b": "《史记》"}]}, {"meaning": "又以配五行。", "cites": [{"t": "庚辛申酉,金也。", "b": "《淮南子·天文》"}]}, {"meaning": "赔偿,偿还。", "cites": [{"t": "季子皋葬其妻,犯人之禾,申祥以告,曰:“请庚之”。", "b": "《礼记·檀弓下》"}], "words": [{"w": "庚偿", "t": "抵偿。"}]}, {"meaning": "变更;更换", "cites": [{"t": "丙枕或思前夜席,庚邮宁肯后锋东。", "b": "宋·邹登龙《送表兄赵奏院赴南外知宗》"}], "words": [{"w": "庚邮", "t": "更换递送的驿邮。"}]}, {"meaning": "愈加。", "cites": [{"t": "五年之后,心庚念是非,口庚言利害,夫子始一解颜而笑。", "b": "《列子·黄帝篇》"}, {"t": "七年之后,从心之所念,庚无是非;从口之所言,庚无利害,夫子始一引吾并席而坐。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1220wx','废','1','fèi','广','8','','[{"pinyin": "fèi", "defs": [{"meaning": "(形声。从广,发声。从“广”(yǎn),表示与房屋有关。本义:房子倾倒)。"}, {"meaning": "同本义。", "cites": [{"t": "废,屋顿也。", "b": "《说文》。段玉裁注:“顿之言钝,谓屋钝置无居之者也。”"}]}, {"meaning": "泛指倾圮,倒塌。", "cites": [{"t": "往古之时,四极废,九州裂。", "b": "《淮南子》"}]}, {"meaning": "废弃;废除。", "cites": [{"t": "于是废先王之道,焚百家之言。", "b": "汉·贾谊《过秦论》"}, {"t": "今存其本不忍废。", "b": "宋·文天祥《指南录后序》"}, {"t": "然则废衅钟与?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "作废", "t": "因失效而废弃"}, {"w": "废业", "t": "丢弃正业,不务正业;荒废衰败的事业"}, {"w": "废贩", "t": "荒废;败坏"}, {"w": "废损", "t": "荒废损害"}, {"w": "废旷", "t": "荒废,不利用。"}]}, {"meaning": "停止; 中止。", "cites": [{"t": "力不足止,中道而废。", "b": "《论语·雍也》"}, {"t": "轮转而不废。", "b": "《淮南子·原道训》"}, {"t": "君子遵道而行,半途而废。", "b": "《礼记·中庸》"}], "words": [{"w": "废格", "t": "终止,搁置"}, {"w": "废业", "t": "中止学业"}, {"w": "废朝", "t": "停止朝会"}, {"w": "废市", "t": "停止营业。"}]}, {"meaning": "废黜,罢官。", "cites": [{"t": "老贼欲废汉自立久矣。", "b": "《资治通鉴》"}], "words": [{"w": "废锢", "t": "罢官并禁止再任职"}, {"w": "废立", "t": "废旧君,立新君"}, {"w": "废退", "t": "黜退;贬黜"}, {"w": "废斥", "t": "废黜屏斥"}, {"w": "废后", "t": "废黜皇后"}, {"w": "废免", "t": "罢免。"}]}, {"meaning": "衰败;败坏。", "cites": [{"t": "即除魏阉废祠之址以葬之。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "废残", "t": "残破"}, {"w": "废败", "t": "浪费,败坏"}, {"w": "废落", "t": "衰败飘零。"}]}, {"meaning": "坠落;跌下。", "cites": [{"t": "[邾子]自投于床,废于炉炭,烂,遂卒。", "b": "《左传》"}, {"t": "今去而野处,念自废于苟践不廉之地。", "b": "宋·王安石《上相府书》"}]}, {"meaning": "杀害,杀死。", "cites": [{"t": "贼国之镇,不忠;受命而废之,不信。", "b": "《国语》"}]}, {"meaning": "费,浪费。", "cites": [{"t": "今若断斯织也,则损失成功,稽废时日。", "b": "《后汉书·列女传》"}, {"t": "使观者大废眼光,亦非畅事。", "b": "《红楼梦》"}]}, {"meaning": "举,发生。", "cites": [{"t": "示不复用也。于是废军而郊射。", "b": "《韩诗外传》"}, {"t": "此道之塞久矣,而世主莫之能废也,故三代不四,非明主莫有能听也。", "b": "《商君书·开塞》"}], "words": [{"w": "废疾", "t": "发生疾病。"}]}, {"meaning": "荒废,放弃不用的。", "cites": [{"t": "废池乔木,犹厌言兵。", "b": "宋·姜夔《扬州慢》"}, {"t": "百废俱兴。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "废井;废业;废址;废矿", "t": ""}]}, {"meaning": "沮丧失望。", "cites": [{"t": "而适先生之所,则废然而反。", "b": "《庄子·德充符》"}]}, {"meaning": "衰败。", "cites": [{"t": "政之所废,在逆民心。", "b": "《管子·牧民》"}]}, {"meaning": "残疾的。", "cites": [{"t": "荆轲废,乃引其匕首提秦王。", "b": "《战国策·燕策》"}], "words": [{"w": "废人;废疾", "t": "残疾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1221wx','净','1','jìng','冫','8','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从水,争声。本义:春秋时鲁国北城门“争门”的护城河)。"}, {"meaning": "同本义。", "cites": [{"t": "净,鲁北城门池也。", "b": "《说文》。按,北城之门曰净门,当因池水名净而命也。公羊传所谓鹿门、争门、吏门,盖以争为之。"}]}, {"meaning": "清洁,洁净。亦用于形容抽象事物。亦指明净。", "cites": [{"t": "风烟俱净。", "b": "吴均《与朱元思书》"}, {"t": "亭亭净植。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "窗明几净;白净", "t": "白而洁净"}, {"w": "净本", "t": "唐人称誊写清楚的文书"}, {"w": "净袜", "t": "白色布袜"}, {"w": "净色", "t": "明净的月色"}, {"w": "净衣", "t": "洁净的衣服。"}]}, {"meaning": "空无所有,无余。", "cites": [{"t": "北累既除,表里俱净。", "b": "萧子良《开物归信门》"}], "words": [{"w": "净办", "t": "净辨。消静,干净利索"}, {"w": "净光", "t": "一点不剩"}, {"w": "净尽", "t": "一点不剩。"}]}, {"meaning": "冷。", "cites": [{"t": "朝嫌剑花净,暮嫌剑光冷。", "b": "唐·李贺《走马引》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1222wx','盲','1','máng','目','8','','[{"pinyin": "máng", "defs": [{"meaning": "(形声。从目,亡声。本义:眼睛失明)。"}, {"meaning": "同本义。", "cites": [{"t": "盲,目无牟子也。", "b": "《说文》"}, {"t": "目不能决黑白之色则谓之盲。", "b": "《韩非子·解老》"}, {"t": "目不见青黄曰盲。", "b": "《论衡·别通》"}, {"t": "五色令人目盲;五音令人耳聋。", "b": "《老子》"}, {"t": "丁椽,好士也,即使其两目盲,尚当与女,何况但眇?", "b": "《三国志·陈思王植传》注"}], "words": [{"w": "盲冥", "t": "眼睛失明"}, {"w": "盲废", "t": "因丧失视力而致残"}, {"w": "盲聋", "t": "眼瞎耳聋"}, {"w": "盲聩", "t": "眼瞎耳聋"}, {"w": "盲妹,盲女", "t": "旧时多指以卖唱为生的失明女子"}, {"w": "盲翁", "t": "丧失视力的老人。"}]}, {"meaning": "昏暗。", "cites": [{"t": "列星殒坠,旦暮晦盲。", "b": "《荀子·赋》"}], "words": [{"w": "盲盲", "t": "茫茫无所见"}, {"w": "盲倀", "t": "晦暗不明的样子"}, {"w": "盲云", "t": "乌云。"}]}, {"meaning": "迅疾。", "cites": [{"t": "盲风至。", "b": "《礼记·月令》"}], "words": [{"w": "盲风", "t": "疾风"}, {"w": "盲雨", "t": "急雨;暴雨"}, {"w": "盲风怪雨", "t": "谓非常急骤凶猛的风雨。"}]}, {"meaning": "使失明。", "cites": [{"t": "周人初以敌囚为民时,乃盲其左目以为奴征。", "b": "郭沫若《甲骨文字研究》"}]}, {"meaning": "看望。", "cites": [{"t": "豕盲眡而交睫腥。", "b": "《周礼·天官·内饔》"}]}, {"meaning": "指盲人。", "cites": [{"t": "观读之音,晓然若盲之开目。", "b": "《论衡·自纪》"}], "words": [{"w": "盲公镜", "t": "盲人所戴的一种眼镜"}, {"w": "盲臣", "t": "古代乐官的自称。因常以盲人充任,故称"}, {"w": "盲圣", "t": "指双目失明的唐代圣僧鉴真和尚"}, {"w": "盲瞽", "t": "盲人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1223wx','放','1','fàng','攵','8','','[{"pinyin": "fàng", "defs": [{"meaning": "(形声。从攴(pū),方声。本义:驱逐,流放)。"}, {"meaning": "同本义。", "cites": [{"t": "放,逐也。", "b": "《说文》"}, {"t": "见伯夷之放迹。", "b": "《楚辞·悲回风》"}, {"t": "卿大夫外淫者放。", "b": "刘向《列女传》"}, {"t": "放驩兜于崇山。", "b": "《虞书》"}, {"t": "放弑其君则残之。", "b": "《周礼·大司马》"}, {"t": "放其大夫。", "b": "《左传·襄公二十九年》"}, {"t": "齐放其大臣孟尝君于诸侯。", "b": "《战国策·齐策》"}, {"t": "虽放流,眷顾楚国,系心怀王。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "又。", "cites": [{"t": "何故怀瑾握瑜而自令见放为?", "b": ""}], "words": [{"w": "流放", "t": "把犯人驱逐到边远地方去"}, {"w": "放伐", "t": "以武力讨伐并放逐暴君"}, {"w": "放徒", "t": "放野。放逐于野"}, {"w": "放远", "t": "远逐"}, {"w": "放废", "t": "放逐罢黜"}, {"w": "放迁", "t": "放逐。"}]}, {"meaning": "舍弃;废置。", "cites": [{"t": "放,弃也。", "b": "《小尔雅》"}, {"t": "惟威惟虐,大放王命。", "b": "《书·康诰》"}], "words": [{"w": "放丢", "t": "扔,丢放"}, {"w": "放绝", "t": "废弃"}, {"w": "放蔑", "t": "废弃蔑视。"}]}, {"meaning": "解除约束;释放。", "cites": [{"t": "昔毛宝放龟而得渡。", "b": "马中锡《中山狼传》"}, {"t": "休放往来人闲走。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "把俘虏放回去;放赦", "t": "宽赦;赦免"}, {"w": "放脱", "t": "放走"}, {"w": "放免", "t": "放赦。释放,赦免"}, {"w": "放遣", "t": "释放;遣散"}, {"w": "放释", "t": "释放。"}]}, {"meaning": "免去;免除。", "cites": [{"t": "任事者知不足以治职,则放官收。", "b": "《韩非子·八经》"}], "words": [{"w": "放良", "t": "官府或主人放免奴婢脱籍,使之成平民"}, {"w": "放官", "t": "免职"}, {"w": "放退", "t": "免职,退职"}, {"w": "放税", "t": "免税。"}]}, {"meaning": "放纵,恣纵。", "cites": [{"t": "无使放悖。", "b": "《吕氏春秋·审分》"}, {"t": "益增其放。", "b": "《绝交书》。注:“放荡。”"}, {"t": "苟无恒心,放辟邪侈,无不为己。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "放弛", "t": "放纵"}, {"w": "放玩", "t": "纵情游玩"}, {"w": "放傲", "t": "放纵自傲"}, {"w": "放醉", "t": "纵情醉酒"}, {"w": "放横", "t": "恣意蛮横"}, {"w": "放浊", "t": "放纵邪行"}, {"w": "放怀", "t": "纵意,放纵情怀。"}]}, {"meaning": "发放。", "cites": [{"t": "月钱放过了不曾?", "b": "《红楼梦》"}], "words": [{"w": "放赏", "t": "发放赏钱"}, {"w": "放高利贷;放官吏债", "t": "宋代富家将银钱放与候补京官使用,待京官得到实缺时,可得加倍利息。"}]}, {"meaning": "搁置;放下。", "cites": [{"t": "放,置也。", "b": "《广雅》"}, {"t": "无放饭。", "b": "《礼记·曲礼》"}, {"t": "隐居放言。", "b": "《论语》。包注:“置也。”"}, {"t": "沉吟放拨插弦中,整顿衣裳起敛容。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "放着", "t": "放置,搁置"}, {"w": "放桌子", "t": "摆餐具"}, {"w": "放顿", "t": "安放"}, {"w": "放仗", "t": "放下兵器。"}]}, {"meaning": "委任;外放(旧指京官调任外地)。", "cites": [{"t": "既而胡即放宁夏知府。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "放缺", "t": "委任官职;做官。"}]}, {"meaning": "从。", "cites": [{"t": "放牛于桃林之野。", "b": "《伪武成》"}, {"t": "至则无可用,放之山下。", "b": "唐·柳宗元《三戒》"}, {"t": "且放白鹿山崖间,须行即骑访名山。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "放牛;放羊拾柴", "t": "指老人娶妻,有意不加管束,冀能怀孕,从而得到名份上的儿子。"}]}, {"meaning": "并船。", "cites": [{"t": "不放舟,不避风,则不可涉也。", "b": "《荀子·子道》"}]}, {"meaning": "又如:落日放船好,轻风生浪迟。"}, {"meaning": "发射;放射;发出。", "cites": [{"t": "由屋顶放光入室。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "又如:有的放矢;放电;放光。"}, {"meaning": "点燃  如:放爆竹;放焰火。"}, {"meaning": "在规定的时间内停止学习或工作  如:放寒假;放学。"}, {"meaning": "阻碍。", "cites": [{"t": "不利作土工之事,放农焉。", "b": "《管子·度地》"}]}, {"meaning": ""}, {"meaning": "模拟。", "cites": [{"t": "宾之礼事,放上而动,咨也。", "b": "《国语·周语下》"}, {"t": "有放而不致也。", "b": "《礼记·礼器》"}, {"t": "心难而行易,好友同志,仕不择地。浊操伤行,世何效放?", "b": "《论衡·自纪》"}]}, {"meaning": "又如:放物(模拟事物);放效(模拟仿效)。"}, {"meaning": "相似。", "cites": [{"t": "有人治道若相放,可不可,然不然。", "b": "《庄子·天地》"}]}, {"meaning": "正当。", "cites": [{"t": "桓公放春三月观于野。", "b": "《管子·小问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1224wx','刻','1','kè','刂','8','','[{"pinyin": "kè", "defs": [{"meaning": "(形声。从刀,亥声。本义:雕刻,在木头上雕刻)。"}, {"meaning": "同本义。", "cites": [{"t": "刻,镂也。", "b": "《说文》"}, {"t": "金谓之镂,木谓之刻。", "b": "《尔雅·释器》"}, {"t": "器不刻镂。", "b": "《礼记·哀公问》"}, {"t": "二十四年春,刻其桷,皆非礼也。", "b": "《左传·庄公二十四年》"}]}, {"meaning": "又。", "cites": [{"t": "刻桓宫桷。", "b": ""}]}, {"meaning": "泛指在各种材料上的雕刻。", "cites": [{"t": "用胶泥刻字,旋刻之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "是日观道中石刻,其远方刻尽漫失。", "b": "清·姚鼐《登泰山记》"}, {"t": "右刻山高月小水落石出,左刻清风徐来水波不兴。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "刻图章;刻刀", "t": "雕刻所用的刀具"}, {"w": "刻木", "t": "在木质器物上雕刻"}, {"w": "刻饰", "t": "雕刻装饰"}, {"w": "刻铭", "t": "在金石等器物上镂刻文字"}, {"w": "刻划", "t": "雕刻;刻印"}, {"w": "刻篆", "t": "指雕刻的文字、花纹。"}]}, {"meaning": "绘画;修饰。", "cites": [{"t": "何乃刻画无盐,以唐突西子也?", "b": "《世说新语·轻诋》"}], "words": [{"w": "刻句", "t": "推敲锻炼词句"}, {"w": "刻桷", "t": "有绘饰的方椽"}, {"w": "刻章琢句", "t": "修饰琢磨章句"}, {"w": "刻励", "t": "琢磨推敲。"}]}, {"meaning": "限定。", "cites": [{"t": "指日刻期,应时有验。", "b": "《白石神君碑》"}], "words": [{"w": "刻纳", "t": "限期归还。"}]}, {"meaning": "伤害。", "cites": [{"t": "山坐金,反自刻。", "b": "刘安《淮南子》"}], "words": [{"w": "刻虐", "t": "侵害"}, {"w": "刻害", "t": "侵害,残害"}, {"w": "刻贼", "t": "伤害;残害"}, {"w": "刻烂", "t": "毁伤溃烂。"}]}, {"meaning": "铭记。", "cites": [{"t": "刻骨攫新句。", "b": "刘得仁《陈情上知己》"}], "words": [{"w": "刻骨镂心", "t": "喻永志不忘。多用表达感激之情"}, {"w": "刻心", "t": "谓铭记于心。"}]}, {"meaning": "时间单位,一小时的四分之一。", "cites": [{"t": "无一时一刻不适耳目。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "六点一刻", "t": ""}]}, {"meaning": "刻薄;苛刻。", "cites": [{"t": "性刻害,好发人阴私。", "b": "《汉书·杨恽传》"}, {"t": "诜居官颇刻敛。", "b": "《唐书·孟诜传》"}], "words": [{"w": "刻峭", "t": "苛刻;严酷"}, {"w": "刻碎", "t": "苛刻繁琐"}, {"w": "刻诛", "t": "严酷的刑罚"}, {"w": "刻酷", "t": "苛刻;严酷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1225wx','育','1','yō yù','月','8','','[{"pinyin": "yō", "defs": [{"meaning": "—— 见“杭育”(hángyō)。"}]}, {"pinyin": "yù", "defs": [{"meaning": "(会意。甲骨文字形,象妇女生孩子。上为“母”及头上的装饰,下为倒着的“子”。)。"}, {"meaning": "同本义。", "cites": [{"t": "育,生也。", "b": "《广雅》"}, {"t": "无遗育。", "b": "《书·盘庚》"}, {"t": "至如今不育。", "b": "《国语·晋语》"}, {"t": "子孙蕃育之谓也。", "b": "《国语·周语》"}, {"t": "妇孕不育,失其道也。", "b": "《易·渐》"}], "words": [{"w": "节育", "t": "节制生育"}, {"w": "育孕", "t": "怀胎足月以至分娩"}, {"w": "生儿育女", "t": ""}]}, {"meaning": "抚养;教育。", "cites": [{"t": "育,养子使作善也。", "b": "《说文》"}, {"t": "教育子。", "b": "《虞书》"}, {"t": "载生载育,时维后稷。", "b": "《诗·大雅·生民》"}], "words": [{"w": "育女", "t": "养女"}, {"w": "育材", "t": "育才。培养人才"}, {"w": "育德", "t": "培养德性"}, {"w": "德育", "t": "政治思想和道德品质的教育"}, {"w": "智育;体育", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1226wx','氓','1','máng méng','氏','8','','[{"pinyin": "máng", "defs": [{"meaning": "——“流氓”(liúmáng):原指无业游民,后来指品质恶劣、不务正业、为非作歹的人。"}]}, {"pinyin": "méng", "defs": [{"meaning": "(会意。从民,亡声。“亡”亦有表意作用,指自彼来此之民。本义:外来的百姓)。"}, {"meaning": "同本义。", "cites": [{"t": "氓,民也。", "b": "《说文》。按,自彼来此之民曰氓。"}, {"t": "而不忧民氓。", "b": "《战国策·秦策》"}, {"t": "以宽民氓。", "b": "《淮南子·脩务》"}, {"t": "远方之人,闻君行仁政,愿受一廛而为氓。", "b": "《孟子》"}]}, {"meaning": "古代称百姓。", "cites": [{"t": "氓之蚩蚩,抱布贸丝。", "b": "《诗·卫风》"}, {"t": "氓家无积而衣服修。", "b": "《管子·八观》。注:“谓民家”"}], "words": [{"w": "群氓", "t": "统治阶级对百姓的蔑称"}, {"w": "氓黎", "t": "民众,百姓"}, {"w": "氓家", "t": "民家"}, {"w": "氓庶", "t": "百姓"}, {"w": "氓萌", "t": "民众"}, {"w": "氓智", "t": "人民的聪明才智"}, {"w": "氓俗", "t": "民俗。"}]}, {"meaning": "野民,周朝指居住在鄙野地区从事农业生产的奴隶。", "cites": [{"t": "奸巧边萌(氓)。", "b": "《史记·三王世家》"}], "words": [{"w": "氓隶", "t": "犹贱民,旧时对劳动人民的贬称。"}]}, {"meaning": "灭,尽。", "cites": [{"t": "庄王之氓社稷也。", "b": "《韩非子·有度》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1227wx','闸','1','zhá','门','8','','[{"pinyin": "zhá", "defs": [{"meaning": "(形声。从门,甲声。本义:开闭門(根据枢转轧轧有声而造字,本义读yā声))。"}, {"meaning": "水闸。", "cites": [{"t": "完我岸闸,千夫奏功。", "b": "宋·苏轼《祭英烈王祝文》"}], "words": [{"w": "闸牌子", "t": "河道上管水闸的人"}, {"w": "开闸;船闸;涵闸", "t": "涵洞和水闸的总称"}, {"w": "闸头", "t": "水闸。"}]}, {"meaning": "把水截住,关闸。引申为拦。", "cites": [{"t": "如水之流,夜间则闸得许多水住在这里,这一池水便满。", "b": "《朱子语类》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1228wx','闹','1','nào','门','8','','[{"pinyin": "nào", "defs": [{"meaning": "(会意。从市,从門(斗)。市场上的争吵、喧闹。本义:嘈杂,喧扰)。"}, {"meaning": "同本义。", "cites": [{"t": "鸣声相呼和,无理只取闹。", "b": "韩愈《食虾蟆》"}, {"t": "召闹取怒。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "渐不喜闹", "b": ""}], "words": [{"w": "闹里", "t": "闹哄哄的场合中"}, {"w": "人声吵闹;喧闹", "t": "喧哗吵闹"}, {"w": "闹耳朵", "t": "形容嘈杂"}, {"w": "闹吵", "t": "喧闹,大声争吵。"}]}, {"meaning": "热闹。", "cites": [{"t": "门巷不教当闹市,诗篇转觉足工夫。", "b": "张籍《奇元员外》"}], "words": [{"w": "闹篮", "t": "热闹多事的场合"}, {"w": "闹杂", "t": "热闹嘈杂"}, {"w": "闹热", "t": "热闹"}, {"w": "闹猛", "t": "方言。繁忙热闹"}, {"w": "闹洋洋", "t": "热闹得很"}, {"w": "闹盈盈", "t": "热热闹闹"}, {"w": "闹闹和和", "t": "热闹和睦。"}]}, {"meaning": "浓盛。", "cites": [{"t": "绿杨烟外晓寒轻,红杏枝头春意闹。", "b": "宋·宋祁《玉楼春》"}, {"t": "正当十分春色,花开得正闹。", "b": "杨朔《荔枝蜜》"}]}, {"meaning": "争吵。", "cites": [{"t": "正闹中间,只见一条大汉挑着一担柴来。", "b": "《水浒全传》"}], "words": [{"w": "叫孩子们别闹了;又哭又闹;闹喳", "t": "吵闹"}, {"w": "闹垓", "t": "争吵;吵架。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1229wx','郑','1','zhèng','阝','8','','[{"pinyin": "zhèng", "defs": [{"meaning": "(形声。从邑,奠声。从邑,与地名、邦域有关。本义:周代诸侯国名,姬姓)。"}, {"meaning": "同本义。", "cites": [{"t": "郑,京兆县,周厉王子友所封。从邑,奠声。宗周之灭,郑徙缯洧之上,今新郑是也。", "b": "《说文》"}, {"t": "至于南郑。", "b": "《穆天子传》。此旧郑也。"}, {"t": "郑穆公使视客馆。", "b": "《左传·僖公三十三年》"}]}, {"meaning": "原指春秋战国时郑国的民间音乐,后与所谓雅乐对举,指与雅乐相背的“淫邪之音”。", "cites": [{"t": "改华服以就紫,变雅音而入郑。", "b": "《惟皇诫德赋》"}], "words": [{"w": "郑音", "t": "本指春秋时郑国的音乐,后多指俗乐。"}]}, {"meaning": "郑重;慎重。", "cites": [{"t": "郑,重也。", "b": "《广雅》"}, {"t": "非皇天所以郑重降符命之意。", "b": "《汉书·王莽传》"}], "words": [{"w": "郑重其事", "t": "对某件事持慎重、认真、严肃的态度。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1230wx','券','1','quàn xuàn','刀','8','','[{"pinyin": "quàn", "defs": [{"meaning": "(形声。 券要分成两半,故从“刀”。本义:契据)。"}, {"meaning": "同本义。古代用于买卖或债务的契据。书于简牍,常分为两半,双方各执其一,以为凭证。后用纸帛书写。", "cites": [{"t": "券,契也。……券别之书,以刀判契其旁,故曰契券。", "b": "《说文》"}, {"t": "使吏召诸民当偿者悉来合券。", "b": "《战国策·齐策》"}, {"t": "因烧其券。", "b": ""}, {"t": "裁券而行。", "b": ""}], "words": [{"w": "券契", "t": "契据"}, {"w": "券要", "t": "契约"}, {"w": "券约", "t": "契据"}, {"w": "券书", "t": "契约,文书"}, {"w": "券剂", "t": "契据;凭证"}, {"w": "券证", "t": "契据。"}]}, {"meaning": "状写,描摹。", "cites": [{"t": "若夏革谈妙,《齐谐》志怪,券宇宙之无极,状鵾鹏之变态。", "b": "宋·刘昌诗《芦浦笔记》"}]}, {"meaning": "钻。", "cites": [{"t": "我把身子长一长,券破罢。", "b": "《西游记》"}]}, {"meaning": "懈怠,厌倦。", "cites": [{"t": "施舍弗券,求善不厌。", "b": "《凉州刺史魏元丕碑》"}]}]}, {"pinyin": "xuàn", "defs": [{"meaning": "通称“拱券” 。桥梁、门窗等建筑物上呈弧形的部分。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1231wx','卷','1','juǎn juàn quán','厄','8','','[{"pinyin": "juǎn", "defs": [{"meaning": "(形声。从卩(jié,甲骨文象人曲膝而跪的样子),劵(juàn)声。(quǎn)本义:膝曲)。"}, {"meaning": "把物弯转成圆筒形。", "cites": [{"t": "有卷者阿。", "b": "《诗·大雅·卷 阿》"}, {"t": "赢缩卷舒。", "b": "《淮南子·本经》。注:“卷,屈也。”"}, {"t": "漫卷诗书喜欲狂。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "卷甲而藏之。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "卷舒", "t": "裹卷和舒展"}, {"w": "卷帐", "t": "新郎在女家结婚,三日之后新婚夫妇带妆奁回到男家"}, {"w": "卷坐", "t": "轿舆不调头,向后退称卷坐"}, {"w": "卷戏", "t": "过去河南地方剧种之一,今已绝迹。"}]}, {"meaning": "席卷。", "cites": [{"t": "卷石底以出。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "北风卷地白草折。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "卷我屋上三重茅。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "卷起千堆雪。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "卷地", "t": "从地面席卷而过,形容气势浩大"}, {"w": "卷包", "t": "犹言席卷"}, {"w": "卷篷", "t": "风卷飞篷。"}]}, {"meaning": "衮服。古代贵族画卷龙图案的礼服。", "cites": [{"t": "制三公一命卷,若有加则赐也。", "b": "《礼记·王制》"}, {"t": "天子卷冕北面。", "b": "《礼记·祭义》"}]}, {"meaning": "断绝。", "cites": [{"t": "我举安邑,塞女戟,韩氏太原卷。", "b": "《史记》"}]}, {"meaning": "犹聚。", "cites": [{"t": "舞《云门》、《大卷》。", "b": "《周礼》。贾公彦疏:“卷者,卷聚之义,即族类也。”"}]}]}, {"pinyin": "juàn", "defs": [{"meaning": "古时书籍写在帛或纸上,一部书可分成若干部分,每部分的文字自有起讫,后代仍用来指全书的一部分。", "cites": [{"t": "军书十二卷。", "b": "《乐府诗集·木兰诗》"}, {"t": "卷卷有爷名。", "b": ""}, {"t": "为一卷。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "上卷;下卷;第三卷", "t": ""}]}, {"meaning": "试卷。", "cites": [{"t": "呈卷。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "试卷;答卷;交卷;卷摺", "t": "科举考试的卷子"}, {"w": "卷头", "t": "考卷的封面"}, {"w": "卷牍", "t": "文件。"}]}, {"meaning": "裱好并带轴的书画等。", "cites": [{"t": "东坡右手执卷。", "b": "明·魏学洢《核舟记》"}, {"t": "鲁直左手执卷末。", "b": ""}, {"t": "右手指卷。", "b": ""}, {"t": "各隐卷底衣褶中。", "b": ""}], "words": [{"w": "画卷;书卷", "t": ""}]}]}, {"pinyin": "quán", "defs": [{"meaning": "膝盖弯曲。引申泛指弯曲。", "cites": [{"t": "卷,膝曲也。", "b": "《说文》"}, {"t": "有卷娄者。", "b": "《庄子·徐无鬼》。释文:“犹拘挛也。”"}, {"t": "卷曲而不中规矩。", "b": "《庄子·逍遥游》"}, {"t": "郑丰卷字子张。", "b": "《左传·襄公三十年》"}], "words": [{"w": "卷曲", "t": "弯曲;蜷缩,肢体弯曲"}, {"w": "卷娄", "t": "拘挛。衰老背驼貌"}, {"w": "卷陲", "t": "泛指蜿蜒的山陵"}, {"w": "卷屈", "t": "蜷曲"}, {"w": "卷舒", "t": "卷缩和伸展。"}]}, {"meaning": "诚恳。", "cites": [{"t": "敢昧死竭卷卷。", "b": "《汉书·贾捐之传》"}]}, {"meaning": "美好的样子。", "cites": [{"t": "有美一人,硕大且卷。", "b": "《诗·陈风》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1232wx','单','1','dān chán shàn','十','8','','[{"pinyin": "dān", "defs": [{"meaning": "(本义:大)。"}, {"meaning": "同本义。", "cites": [{"t": "單,大也。", "b": "《说文》。段注:“当为大言也,浅人删言字。如誣加言也,浅人亦删言字。”"}, {"t": "明清于单辞。", "b": "《书·吕刑》。按,夸诞之辞。"}, {"t": "夏禹能单平水土。", "b": "《国语·郑语》"}, {"t": "王之威亦单矣。", "b": "《史记·春申君传》"}, {"t": "单埢垣兮。", "b": "扬雄《甘泉赋》。注:“大貌。”"}]}, {"meaning": "单独。", "cites": [{"t": "单足以喻则单。", "b": "《荀子·正名》。注:单,物之单名也。”"}], "words": [{"w": "单幅门", "t": "独扇的门"}, {"w": "单跪", "t": "弯屈一膝,行半跪之礼。也叫“打千”"}, {"w": "单绪", "t": "只有一个儿子传宗接代。即单传。"}]}, {"meaning": "一个。", "cites": [{"t": "单,一也。", "b": "《汉书·枚乘传》注"}, {"t": "今单车来代之。", "b": "《史记·魏公子列传》"}], "words": [{"w": "单介", "t": "一人;一个"}, {"w": "单味", "t": "一味菜肴"}, {"w": "单民", "t": "只身"}, {"w": "单幅", "t": "单条;条幅。"}]}, {"meaning": "孤独;孤立。", "cites": [{"t": "令母在后单。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "孤单", "t": "单身无靠;感到寂寞"}, {"w": "单孑", "t": "只身;个人"}, {"w": "单己", "t": "只身;个人"}, {"w": "单老", "t": "孤独无依的老人"}, {"w": "单然", "t": "孤单的样子"}, {"w": "单雄", "t": "孤单的雄鸟。"}]}, {"meaning": "衣物等单层。", "cites": [{"t": "庶人单衣。", "b": "《礼记·儒行》注"}, {"t": "晚成单罗衫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "单绞", "t": "苍黄色的单衣"}, {"w": "单账", "t": "单层的账子"}, {"w": "单席", "t": "一重坐席。"}]}, {"meaning": "衣物单薄。", "cites": [{"t": "可怜身上衣正单,心忧炭贱愿天寒。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "单复", "t": "单薄的衣服和厚重的衣服"}, {"w": "单虚", "t": "单薄空虚"}, {"w": "单衾", "t": "薄被"}, {"w": "单轻", "t": "单薄。"}]}]}, {"pinyin": "chán", "defs": [{"meaning": "古代匈奴君主的称号。"}]}, {"pinyin": "shàn", "defs": [{"meaning": "地名。单县 ,在山东省西南部。"}, {"meaning": "姓(春秋有单豹)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1233wx','炬','1','jù','火','8','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从火,巨声。本义:火把)。"}, {"meaning": "同本义。", "cites": [{"t": "苣,束苇烧。从艸,巨声。俗字作炬。", "b": "《说文》"}, {"t": "束苣乘城。—《后汉书·皇甫嵩传》", "b": ""}, {"t": "炬可以昭明。", "b": "《张衡传》注"}, {"t": "牛尾炬火,光明炫耀。", "b": "《史记·田单列传》"}, {"t": "炬焰(火把燃烧的光芒)", "b": ""}]}, {"meaning": "蜡烛。", "cites": [{"t": "春蚕到死丝方尽,蜡炬成灰泪始干。", "b": "李商隐《无题》"}], "words": [{"w": "炬烛", "t": "指蜡烛。"}]}, {"meaning": "火烧;放火。", "cites": [{"t": "楚人一炬,可怜焦土。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "炬火;炬炭", "t": "炽热的炭火。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1234wx','炒','1','chǎo','火','8','','[{"pinyin": "chǎo", "defs": [{"meaning": "(形声。从火,少声。本义:煎炒,火干)。"}, {"meaning": "中药炮制法之一。将药材放在锅内加热、翻动至一定要求 。炒时不加辅料叫清炒;加辅料同炒的有:麸炒、土炒、米炒、酒炒、醋炒等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1235wx','炊','1','chuī','火','8','','[{"pinyin": "chuī", "defs": [{"meaning": "(形声。从火,吹省声。本义:烧火做饭)。"}, {"meaning": "同本义。", "cites": [{"t": "析骸而炊之。", "b": "《公羊传》"}, {"t": "一人炊之。", "b": "《汉书·枚乘传》"}, {"t": "先炊之属。", "b": "《史记·封禅书》。注:“先炊,古炊母之神也。”"}, {"t": "急应河阳役,犹得备晨炊。", "b": "杜甫《石壕吏》"}], "words": [{"w": "炊米", "t": "煮饭"}, {"w": "炊人", "t": "厨子"}, {"w": "炊妇", "t": "煮饭的妇人"}, {"w": "吹家子", "t": "古代军中掌管炊事的人"}, {"w": "吹沙成饭", "t": "比喻徒劳无功。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1236wx','炕','1','hāng kàng','火','8','','[{"pinyin": "hāng", "defs": [{"meaning": "张开。", "cites": [{"t": "守宫槐,叶昼聂宵炕。", "b": "《尔雅》"}]}]}, {"pinyin": "kàng", "defs": [{"meaning": "(形声。从火,亢声。本义:干,烘干)。"}, {"meaning": "同本义。", "cites": [{"t": "炕,干也。", "b": "《说文》"}, {"t": "炕,曝也。", "b": "《广雅》"}, {"t": "炕火曰炙。", "b": "《诗·匏叶传》"}, {"t": "君炕阳而暴虐。", "b": "《汉书·五行志》。"}]}, {"meaning": "又如：把湿褥子在炕上炕一炕。"}, {"meaning": "断绝。", "cites": [{"t": "西揖彊秦之相,扼其咽,炕其气,附其背而夺其位。", "b": "《汉书·扬雄传下》"}]}, {"meaning": "中国北方住宅里用砖或土坯砌成,上面铺席,下有孔道和烟囱相通,可以烧火取暖的床。", "cites": [{"t": "客则鼾睡炕上矣。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "炕幔", "t": "炕前的帘子;遮挡炕上睡人的围布"}, {"w": "炕柴灶", "t": "北方一种与炕床相通的锅灶,烧饭兼可取暖"}, {"w": "炕几", "t": "炕桌。"}]}, {"meaning": "干渴。", "cites": [{"t": "老牛呵!你水有咧,草有咧,不饿不炕了。", "b": "《中国民间故事选·牛郎配织女》"}]}, {"meaning": "急躁。", "cites": [{"t": "华臣炕暴失义。", "b": "《汉书·五行志》"}], "words": [{"w": "炕暴", "t": "性情急躁横暴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1237wx','炎','1','yán','火','8','','[{"pinyin": "yán", "defs": [{"meaning": "(会意。从二火。本义:火苗升腾)。"}, {"meaning": "同本义。", "cites": [{"t": "炎,火光上也。", "b": "《说文》"}, {"t": "火曰炎上。", "b": "《书·洪范》"}, {"t": "秉畀炎火。", "b": "《诗·小雅·大田》"}, {"t": "南有炎火千里。", "b": "《楚辞·大招》"}, {"t": "顷之,烟炎张天(炎,通“焰”,火焰)。", "b": "《资治通鉴》"}], "words": [{"w": "炎上", "t": "火焰向上;火向上燃烧。"}]}, {"meaning": "焚烧。", "cites": [{"t": "大炎昆冈,玉石俱焚。", "b": "《书·胤征》"}, {"t": "今时复旱,如炎如焚。", "b": "《后汉书》"}]}, {"meaning": "炎热,酷热。", "cites": [{"t": "赫赫炎炎。", "b": "《诗·大雅·云汉》。传:“热气也。”"}, {"t": "南方曰炎天,又东北曰炎风。", "b": "《吕氏春秋·有始》"}, {"t": "观炎气之相仍兮,窥烟液之所积。", "b": "《楚辞》"}, {"t": "夏炎百木盛,阴郁增埋覆。", "b": "唐·韩愈《南山》"}], "words": [{"w": "炎暑", "t": "炎热酷暑"}, {"w": "炎天", "t": "大热天"}, {"w": "炎魃", "t": "旱鬼"}, {"w": "炎威", "t": "夏天酷热的威势"}, {"w": "炎月", "t": "暑月"}, {"w": "炎辰", "t": "炎热的日子"}, {"w": "炎兵", "t": "喻酷热"}, {"w": "炎冷", "t": "犹冷热"}, {"w": "炎序", "t": "炎夏季节。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1238wx','炉','1','lú','火','8','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。从火,盧声。本义:贮火的器具,作冶炼、烹饪、取暖等用)。"}, {"meaning": "火炉。", "cites": [{"t": "鑪,金鑪也。", "b": "《说文》"}, {"t": "炉,火所居也。", "b": "《声类》"}, {"t": "邾庄公废于鑪炭。", "b": "《左传》"}, {"t": "鑪橐埵坊。", "b": "《淮南子·齐俗》"}, {"t": "奉炽炉,炭火尽赤红。", "b": "《韩非子》"}, {"t": "左手抚炉。", "b": "清·张潮《核舟记》"}]}, {"meaning": "又。", "cites": [{"t": "炉上有壶。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "为炉,为壶。", "b": ""}, {"t": "即炉火烧绝。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "炉鸭", "t": "放在火炉上烧烤出来的鸭子"}, {"w": "炉饼", "t": "烧饼"}, {"w": "炉的", "t": "蒸的"}, {"w": "炉铫", "t": "煎药或烧水用的器具"}, {"w": "炉火", "t": "炉中之火"}, {"w": "炉灰", "t": "燃料在炉内燃烧后所剩的粉状物"}, {"w": "炉匠", "t": "铁匠。"}]}, {"meaning": "古代酒店前放置酒坛的土台子。", "cites": [{"t": "买一酒舍酤酒,而令文君当炉。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1239wx','沫','1','mò','氵','8','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从水,末声。本义:沫水)。"}, {"meaning": "同本义。", "cites": [{"t": "沫,沫水也。出蜀西徼外东南入江。", "b": "《说文》"}]}, {"meaning": "古水名,即今四川省大渡河。"}, {"meaning": "泡沫,沫子。", "cites": [{"t": "瀑下一曰沫也。", "b": "《说文》"}, {"t": "沫流赭。", "b": "《汉书·礼乐志》。注:“言汗流沫出也。”"}], "words": [{"w": "沫血", "t": "水面上的泡沫像血一样"}, {"w": "沫雨", "t": "骤雨成潦,上浮泡沫"}, {"w": "沫流", "t": "冒着泡沫的水流。指激流;流派。"}]}, {"meaning": "唾沫。", "cites": [{"t": "余干骨之沫为斯弥。", "b": "《庄子·主乐》。李注:“口中汁也。”"}]}, {"meaning": "竭,终止。", "cites": [{"t": "芳菲菲而难亏兮,芬至今犹未沫。", "b": "《楚辞·离骚》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1240wx','浅','1','qiǎn jiān','氵','8','','[{"pinyin": "qiǎn", "defs": [{"meaning": "实行,实现。", "cites": [{"t": "臣之梦浅矣。", "b": "《韩非子·难四》"}]}, {"meaning": "(形声。从水,戔(jiān)声。本义:水不深)。"}, {"meaning": "从表面到底或外面到里面距离小的。与“深”相对。", "cites": [{"t": "浅,不深也。", "b": "《说文》"}, {"t": "石濑兮浅浅。", "b": "《楚辞·湘君》"}, {"t": "审知卑城浅城而错守焉。", "b": "《墨子·备城门》"}, {"t": "水浅而舟大也。", "b": "《庄子·逍遥游》"}, {"t": "徐而察之,则山下皆石穴罅,不知其浅深。", "b": "宋·苏轼《石钟山记》"}, {"t": "河汉清且浅,相去复几许?", "b": "《古诗十九首》"}]}, {"meaning": "从上到下或从外到内距离小(跟“深”相反)。", "cites": [{"t": "浅草才能没马蹄。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "麦田浅鬣寸许。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "浅小", "t": "距离近"}, {"w": "浅攻", "t": "近距离出击,不深入敌方腹地。"}]}, {"meaning": "浅显,明白易懂。", "cites": [{"t": "何以为辨?喻深以浅。", "b": "《论衡》"}], "words": [{"w": "粗浅", "t": "浅显不深奥"}, {"w": "浅切", "t": "浅易切当"}, {"w": "浅直", "t": "浅显直率"}, {"w": "浅注", "t": "简明的注释"}, {"w": "浅俚", "t": "浅显粗俗"}, {"w": "浅率", "t": "浅近率直;浅显粗率"}, {"w": "浅稚", "t": "浅显幼稚。"}]}, {"meaning": "肤浅,浅薄。", "cites": [{"t": "浅人不察。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "浮浅", "t": "浅薄;肤浅"}, {"w": "浅丈夫", "t": "浅夫。见识短浅的人"}, {"w": "浅人", "t": "见识浅薄的人"}, {"w": "浅妄", "t": "浅薄妄为"}, {"w": "短浅", "t": "狭窄而肤浅"}, {"w": "浅术", "t": "肤浅的技艺"}, {"w": "浅拙", "t": "浅薄笨拙。"}]}, {"meaning": "不久，时间短。", "cites": [{"t": "施及孝文王、庄襄王,享国之日浅。", "b": "西汉·贾谊《过秦论》"}], "words": [{"w": "年代浅", "t": ""}]}, {"meaning": "衣带宽松。", "cites": [{"t": "逢衣浅带,矫言伪行,以迷惑天下之主。", "b": "《庄子》"}]}, {"meaning": "程度不深的。"}, {"meaning": "颜色淡薄。", "words": [{"w": "浅红", "t": "颜色不深的红色"}]}]}, {"pinyin": "jiān", "defs": [{"meaning": "流水声", "words": [{"w": "浅浅", "t": "形容水流急速的样子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1241wx','法','1','fǎ','氵','8','','[{"pinyin": "fǎ", "defs": [{"meaning": "(会意。从“水”,表示法律、法度公平如水;从“廌”(zhì),即解廌,神话传说中的一种神兽,据说,它能辨别曲直,在审理案件时,它能用角去触理曲的人。基本义:刑法;法律;法度)。"}, {"meaning": "同基本义。", "cites": [{"t": "灋,刑也。平之如水。从水,廌所以触不直者去之,从去,会意。", "b": "《说文》"}, {"t": "利用刑人,以正法也。", "b": "《易·蒙》"}, {"t": "惟作五虐之刑曰法。", "b": "《书·吕刑》"}, {"t": "法者,刑罚也。所以禁强暴也。", "b": "《盐铁论·诏圣》"}, {"t": "杀戮禁诛谓之法。", "b": "《管子·心术》"}, {"t": "礼者禁于将然之前,而法者禁于已然之后。", "b": "《大戴礼记》"}, {"t": "失期,法当斩。", "b": "《史记·陈涉世家》"}, {"t": "故治国无法则乱,守法而弗度则悖。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "又。", "cites": [{"t": "法虽今而在。", "b": ""}], "words": [{"w": "合法;犯法;法禁", "t": "刑法和禁令。"}]}, {"meaning": "法令;规章;制度。", "cites": [{"t": "汉法令非行也。", "b": "汉·贾谊《治安策》"}], "words": [{"w": "法日", "t": "制度规定的日子。"}]}, {"meaning": "标准;模式。", "cites": [{"t": "匹夫而为百世师,一言而为天下法。", "b": "宋·苏轼《潮州韩文公庙碑》"}], "words": [{"w": "法戒", "t": "楷式和监戒。"}]}, {"meaning": "方法;办法。", "cites": [{"t": "凡用兵之法,全国为上。", "b": "《孙子·九变》"}, {"t": "其法,用胶泥刻字。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "古法采草药多用二月八月。", "b": "《梦溪笔谈·采草药》"}], "words": [{"w": "用法;分类法;法套", "t": "办法"}, {"w": "法儿", "t": "法子;办法。"}]}, {"meaning": "法拉,电容的MKS制实用单位,等于电容器极板上充以1库仑电量后两板间的电压为1伏特时的电容。"}, {"meaning": "尊称佛家的事物。", "cites": [{"t": "文少保亦以悟大光明法蝉脱。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "法施", "t": "以佛法度人"}, {"w": "法嗣", "t": "佛教称继承衣钵的弟子为法嗣。后亦泛指继承人"}, {"w": "法界", "t": "佛教指整个现象界"}, {"w": "法华", "t": "佛经名。《妙法莲华经》的简称。佛教主要经典之一。"}]}, {"meaning": "中国战国时期一重要学派名。", "cites": [{"t": "杂家者流,盖出于议官。兼儒、墨,合名、法。", "b": "《汉书》"}]}, {"meaning": "法国的简称。", "cites": [{"t": "余闻法人好胜。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "合法。", "cites": [{"t": "其于诸侯之求索也,法则听之,不法则距之。", "b": "《韩非子·八奸》"}]}, {"meaning": "效法。", "cites": [{"t": "则文王不足法与?", "b": "《孟子·公孙丑上》"}, {"t": "不期修古,不法常可。", "b": "《韩非子·五蠹》"}, {"t": "法其所以为法。", "b": "《吕氏春秋·察今》"}, {"t": "垂诸文而为后世法。", "b": "唐·韩愈《答李翊书》"}], "words": [{"w": "法常可", "t": "效法通常的做法。常可,指旧制度"}, {"w": "法天", "t": "效法自然和天道"}, {"w": "法古", "t": "效法古代"}, {"w": "法循", "t": "效法遵循。"}]}, {"meaning": "守法。", "cites": [{"t": "夕受而不法,朝斥之矣。", "b": "柳宗元《封建论》"}]}, {"meaning": "依法处治。", "cites": [{"t": "[商鞅]将法太子。", "b": "《史记·商君列传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1242wx','泄','1','xiè','氵','8','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从水,世声。本义:泄水。在江西)。"}, {"meaning": "假借为“歇”。发泄;发散。", "cites": [{"t": "运物之泄也。", "b": "《庄子·山木》。司马注:“发也。”"}, {"t": "穷岫泄云。", "b": "左思《魏都赋》。注:“犹出也。”"}, {"t": "宗气泄也。", "b": "《素问·平人气象论》。注:“谓发泄也。”"}, {"t": "精泄于目。", "b": "《淮南子·本经》"}, {"t": "惠此中国,俾民忧泄。", "b": "《诗·大雅·民劳》"}, {"t": "蓄泄数千载。", "b": "李白《历阳壮士勤将军名思齐歌》"}], "words": [{"w": "泄宣", "t": "宣泄,宣露"}, {"w": "泄冤", "t": "表白或洗雪冤屈"}, {"w": "泄写", "t": "宣泄,倾吐。写,同“泻”。"}]}, {"meaning": "排出。", "cites": [{"t": "振河海而不洩。", "b": "《礼记·中庸》"}, {"t": "泻出于两峰之间。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "泄洪;泄水道;泄水坝;泄水闸", "t": ""}]}, {"meaning": "腹泻。", "cites": [{"t": "金郁泄之。", "b": "《素问·六元正经大论》。注:“谓渗泄也。”"}], "words": [{"w": "泄溺", "t": "大小便"}, {"w": "泄下", "t": "水泻,腹泻"}, {"w": "泄利", "t": "泄痢。水泻;痢疾。利,通“痢”"}, {"w": "泄注", "t": "腹泻"}, {"w": "泄药", "t": "泄剂。泻药。"}]}, {"meaning": "泄漏;泄露。", "cites": [{"t": "言若泄臣不获死。", "b": "《左传·昭公二十五年》"}, {"t": "阴重不泄。", "b": "《史记·万石张叔传》"}], "words": [{"w": "泄了陶", "t": "露了底"}, {"w": "泄口", "t": "谓言语泄露"}, {"w": "泄风", "t": "泄漏消息。"}]}, {"meaning": "物体由孔穴或缝中滴下、透出或掉出。", "cites": [{"t": "落泪便如泻。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "泄涕", "t": "犹流泪。"}]}, {"meaning": "狎侮;轻慢。", "cites": [{"t": "武王不泄迩,不忘远。", "b": "《孟子·离娄下》"}, {"t": "憍泄者,人之殃也。", "b": "《荀子·荣辱》"}], "words": [{"w": "泄慢", "t": "轻慢"}, {"w": "泄渎", "t": "轻慢,亵渎。"}]}, {"meaning": "指风邪久入腠理间,以致出现汗泄不止、口干、身痛的病症。"}, {"meaning": "皮肤长小疙瘩并有瘙痒的病症。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1243wx','沽','1','gū','氵','8','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从水,古声。本义:古水名)。"}, {"meaning": "同本义。", "cites": [{"t": "沽,沽水,出渔阳塞外,东入海。", "b": "《说文》"}]}, {"meaning": "古水名,即今河北省白河。"}, {"meaning": "即今河北省州河。下流为蓟运河,经宁河县至天津市北塘入海。"}, {"meaning": "天津市的别称。"}, {"meaning": "买。多指买酒", "cites": [{"t": "沽酒市脯。", "b": "《论语·乡党》"}, {"t": "向了一回火,觉得身上寒冷,寻思却才老军所说,二里路外有那市井,何不去沽些酒来吃?", "b": "《水浒》"}], "words": [{"w": "沽酒市脯", "t": "买酒买菜"}, {"w": "沽酒", "t": "从市场上买来的酒;买酒。"}]}, {"meaning": "卖,出售", "cites": [{"t": "有美玉于斯,韫(yùn收藏)匵而藏诸?求善贾(gǔ商人)而沽诸?", "b": "《论语·子罕》"}, {"t": "宋人有沽酒者。", "b": "《韩非子·外储说右上》"}], "words": [{"w": "沽泊", "t": "卖酒"}, {"w": "沽家", "t": "酒馆"}, {"w": "沽卖", "t": "出售"}, {"w": "沽贩", "t": "经商,做买卖"}, {"w": "沽恩", "t": "卖好,讨好。"}]}, {"meaning": ""}, {"meaning": "粗劣。", "cites": [{"t": "冠者,沽功也。", "b": "《仪礼·丧服》"}], "words": [{"w": "沽物", "t": "粗劣的物品。"}]}, {"meaning": "简略。", "cites": [{"t": "杜桥之母之丧,宫中无相,以为沽也。", "b": "《礼记·檀弓上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1244wx','河','1','hé','氵','8','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从水,可声。本义:黄河)。"}, {"meaning": "同本义。", "cites": [{"t": "河,河水出敦煌塞外昆仑山,发原注海。", "b": "《说文》"}, {"t": "导河积石。", "b": "《书·禹贡》"}, {"t": "河阳之北。", "b": "《列子·汤问》"}, {"t": "三豕涉河。", "b": "《吕氏春秋·慎行论》"}], "words": [{"w": "河堧", "t": "黄河河边之地"}, {"w": "河湟", "t": "黄河与湟水"}, {"w": "河朔", "t": "泛指黄河北岸的地方"}, {"w": "河洛", "t": "黄河与洛水"}, {"w": "河堑", "t": "黄河沿岸的壕沟。"}]}, {"meaning": "河流的通称。", "cites": [{"t": "南方无河也,冀州凡水大小皆谓之河。", "b": "《汉书·司马相如传》注"}, {"t": "国破山河在,城春草木深。", "b": "杜甫《春望》"}, {"t": "韩信钓河曲。", "b": "《后汉书·郦炎传》"}, {"t": "散作满河星。", "b": "清·查慎行《舟夜书所见》"}, {"t": "河出伏流。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "鸡翼城河面。", "b": "《广东军务记》"}, {"t": "沿河施放。", "b": ""}], "words": [{"w": "河次", "t": "河边"}, {"w": "河浒", "t": "河边;河畔"}, {"w": "河畔", "t": "河滨"}, {"w": "河津", "t": "河流的渡口"}, {"w": "河洲", "t": "河中可居的陆地。"}]}, {"meaning": "天河,银河。", "cites": [{"t": "秋河曙耿耿。", "b": "谢元晖《诗》。注:“天汉也。”"}], "words": [{"w": "河星", "t": "银河中的星星"}, {"w": "河云", "t": "指银河。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1245wx','沾','1','zhān','氵','8','','[{"pinyin": "zhān", "defs": [{"meaning": "古水名。", "cites": [{"t": "沾,沾水,出上党壶关东入淇。从水,占声。", "b": "《说文》"}]}, {"meaning": "淇水支流。源出山西省壶关县南赵掌尖老山南麓,东流入河南省,至鹤壁市西注入淇水。今上流建有弓上水库。"}, {"meaning": "假借为“霑”。浸润;浸湿。", "cites": [{"t": "沾,一曰益也。", "b": "《说文》"}, {"t": "惠沾渥。", "b": "《汉曹全碑》"}, {"t": "澍雨沾洽。", "b": "《白石神君碑》"}, {"t": "汗出沾背。", "b": "《史记·陈丞相世家》"}, {"t": "泣下沾衿。", "b": "《汉书·李广苏建传》"}, {"t": "长夜沾湿何由彻!", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "泣下沾襟。", "b": "宋·欧阳修《伶官传》"}, {"t": "不终朝日,而澍雨沾洽。", "b": "《白石神君碑》"}, {"t": "十八日,大雨沾足,乃种豆。", "b": "《聊斋志异》"}]}, {"meaning": "接触。", "cites": [{"t": "沾水则高下不平。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "殊不沾污。", "b": ""}], "words": [{"w": "沾粘", "t": "相互粘结,接触"}, {"w": "沾唇", "t": "形容略微喝一点酒、茶水等饮料"}, {"w": "沾牙", "t": "吃喝东西"}, {"w": "从来滴酒不沾", "t": ""}]}, {"meaning": "熏陶;感化。", "cites": [{"t": "礼乐所不沾,宪章弗能革。", "b": "北魏·杨衒之《洛阳伽蓝记》"}], "words": [{"w": "沾化", "t": "感受德化"}, {"w": "沾被", "t": "影响所及。"}]}, {"meaning": "雨水浸湿。", "cites": [{"t": "霑,渍也。", "b": "《广雅·释诂二》"}, {"t": "霑体涂足。", "b": "《国语·齐语》。注:“霑,濡也。”"}, {"t": "霑余襟之浪浪。", "b": "《楚辞·离骚》"}, {"t": "既霑既足,生我百谷。", "b": "《诗·小雅·信南山》"}], "words": [{"w": "沾衣", "t": "润湿衣服"}, {"w": "沾衿", "t": "沾湿衣襟"}, {"w": "沾醉", "t": "饮酒大醉,沾湿胸襟"}, {"w": "沾体涂足", "t": "身体被田水沾湿,脚上被泥巴涂污。"}]}, {"meaning": "比喻恩泽沾润。", "cites": [{"t": "盖闻圣主之养民也,仁沾而恩洽。", "b": "《文选·扬雄·长杨赋》"}], "words": [{"w": "沾沐", "t": "承受恩泽"}, {"w": "沾洽", "t": "雨泽丰足,也以比喻恩泽广被。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1246wx','泪','1','lèi','氵','8','','[{"pinyin": "lèi", "defs": [{"meaning": "(形声。从水,戾(lì)声。简化字“泪”是个从“水”从“目”的会意字。本义:眼泪)。"}, {"meaning": "同本义。", "cites": [{"t": "望其碑者莫不流涕,杜预因名为坠泪碑。", "b": "《晋书·羊祜传》"}, {"t": "士皆垂泪涕。", "b": "《战国策·燕策》"}, {"t": "剑外忽传收蓟北,初闻涕泪满衣裳。", "b": "杜甫《闻官军收河南河北》"}, {"t": "却与小姑别,泪落连珠子。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "涕泪", "t": "先秦时期,“涕”指眼泪,后来出现了“泪”,表示眼泪,与“涕”同义并用"}, {"w": "泪波", "t": "泪水如波"}, {"w": "泪泉", "t": "指眼泪"}, {"w": "泪球", "t": "泪珠,泪滴"}, {"w": "泪晶", "t": "泪珠。"}]}, {"meaning": "流泪。", "cites": [{"t": "泪翟子之悲,恸朱公这哭。", "b": "孔稚圭《北山移文》"}], "words": [{"w": "泪河", "t": "泪下如河。形容悲痛之极"}, {"w": "泪下沾衿", "t": "流泪很多;沾湿衣襟"}, {"w": "泪坠尊者", "t": "佛教用语。佛灭后,“大阿罗汉”有大悲心,常因悲三途的众生而啼泣,故称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1247wx','沮','1','jǔ jù','氵','8','','[{"pinyin": "jǔ", "defs": [{"meaning": "(形声。从水,且声。①(jū)本义:古水名。在今陕西省。②阻止)。"}, {"meaning": "阻止,阻遏;终止。", "cites": [{"t": "乱庶斯沮。", "b": "《诗·小雅·巧言》"}, {"t": "其次,为赏劝罚沮。", "b": "《商君书·靳令》"}, {"t": "嬖人有臧仓者沮君,君是以不果来也。", "b": "《孟子·梁惠王下》"}, {"t": "是以为善者劝,为不善者沮,上下一心,三军同力。", "b": "《荀子·强国》"}, {"t": "沮之以兵。", "b": "《礼记·儒行》"}, {"t": "溯流转漕,谷恒输沮。", "b": "《汉·巴郡太守都亭侯张纳功德叙》"}], "words": [{"w": "沮挠", "t": "阻挠;阻止"}, {"w": "沮丘", "t": "背水的山丘"}, {"w": "沮格", "t": "阻拦"}, {"w": "沮厄", "t": "阻挠遏止"}, {"w": "沮止", "t": "阻止,遏止。"}]}, {"meaning": "畏惧,恐惧。", "cites": [{"t": "沮之以兵。", "b": "《礼记·儒行》。注:“谓恐怖之也。”"}], "words": [{"w": "沮畏", "t": "畏惧"}, {"w": "沮恐", "t": "畏惧,恐惧"}, {"w": "沮喘", "t": "恐怖"}, {"w": "沮惮", "t": "恐惧"}, {"w": "沮慑", "t": "恐惧。"}]}, {"meaning": "破坏,败坏。", "cites": [{"t": "妄举,则事沮不胜。", "b": "《韩非子·二柄》"}], "words": [{"w": "沮咹衂", "t": "受挫;挫败"}, {"w": "沮坏", "t": "中伤;败坏"}, {"w": "沮解", "t": "破坏而使其离散。"}]}, {"meaning": "丧气、颓丧或灰心失望。", "cites": [{"t": "神辱志沮。", "b": "嵇康《幽愤诗》"}], "words": [{"w": "沮折", "t": "沮丧屈从"}, {"w": "沮惨不豫", "t": "失望悲惨,不高兴"}, {"w": "沮气", "t": "丧失志气"}, {"w": "沮索", "t": "颓废失意的样子"}, {"w": "沮恐", "t": "沮丧惶恐"}, {"w": "沮服", "t": "受挫灰心而降伏。"}]}]}, {"pinyin": "jù", "defs": [{"meaning": "湿,湿润。", "cites": [{"t": "彼汾沮洳。", "b": "《诗·魏风·汾沮洳》"}], "words": [{"w": "沮淤", "t": "低洼泥泞"}, {"w": "沮洳场", "t": "低下阴湿的地方"}, {"w": "沮泞", "t": "低洼泥泞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1248wx','油','1','yóu','氵','8','','[{"pinyin": "yóu", "defs": [{"meaning": "(形声。从水,由声。本义:油水)。"}, {"meaning": "同本义。", "cites": [{"t": "油,油水出武陵孱陵西,东南入江。", "b": "《说文》。按,在今湖北荆州府公安县北。"}]}, {"meaning": "古水名。也作“繇”。发源于湖北五峰县界,东流经松滋县界,至公安县西南油口注入长江。今其上游汇入松滋河,南流注入澧水,下游为荆江分洪区,故址已不复存在。"}, {"meaning": "动物的脂肪和由植物或矿物中提炼出来的脂质物。", "cites": [{"t": "积油满万石,则自然生火。", "b": "晋·张华《博物志》"}], "words": [{"w": "油尽灯枯", "t": "形容人被消耗得心力衰竭,生命垂危"}, {"w": "油盏", "t": "油灯"}, {"w": "油海", "t": "指特大的油田"}, {"w": "油火虫虫", "t": "方言。即萤火虫。"}]}, {"meaning": "涂油。", "cites": [{"t": "茶色贵白,而饼茶多以珍膏油其面。", "b": "蔡襄《茶录》"}], "words": [{"w": "油窗户;油抹", "t": "上漆上油"}, {"w": "油壁香车", "t": "一种油漆彩绘的车,多为妇女乘用"}, {"w": "油搭扇", "t": "一种竹骨黑油纸的折扇"}, {"w": "油衣", "t": "雨衣"}, {"w": "油鬏髻", "t": "油鬏髻。女人头上梳的发髻。亦代指女人。"}]}, {"meaning": "比喻浮滑,不诚实。", "cites": [{"t": "若不多读书,多贯穿,而遽言性情,则开后学油腔滑调、信口成章之恶习矣。", "b": "王士祯《师友传灯录》"}], "words": [{"w": "油嘴贫舌", "t": "爱多说话,耍嘴皮子"}, {"w": "油花和尚", "t": "油头滑脑不守清规的和尚。"}]}, {"meaning": "色泽光润的样子。", "cites": [{"t": "禾黍油油。", "b": "《史记·宋微子世家》。索隐:“光悦貌。”"}], "words": [{"w": "油光可鉴", "t": "非常光亮润泽"}, {"w": "油光光", "t": "非常光亮"}, {"w": "油光晶亮", "t": "非常光滑明亮"}, {"w": "油晃晃,油幌幌", "t": "油光闪亮"}, {"w": "油浸浸", "t": "形容物体光亮油润。"}]}, {"meaning": "和悦恭谨的样子。", "cites": [{"t": "礼已,三爵而油油以退。", "b": "《礼记·玉藻》"}], "words": [{"w": "油如", "t": "宽和的样子"}, {"w": "油翼", "t": "温和恭谨。"}]}, {"meaning": "流动的样子,常形容云和水。", "cites": [{"t": "自我天覆,云之油油。", "b": "《史记·司马相如传》"}, {"t": "油油湘江。", "b": "《楚辞·惜贤》。注:“流貌。”"}], "words": [{"w": "油气", "t": "微弱的气息。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1249wx','泊','1','bó pō','氵','8','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从水,白声。本义:停船)。"}, {"meaning": "同本义。", "cites": [{"t": "西有鸾冈,洪崖先生乘鸾所憩泊也。", "b": "《水经注·赣水》"}, {"t": "晚泊沙夹,距小孤一里。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "士大夫终不肯以小舟夜泊绝壁之下。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "泊船;泊舟", "t": "船停泊靠岸"}, {"w": "泊步", "t": "埠头,码头"}, {"w": "泊主", "t": "船家"}, {"w": "船泊港外", "t": ""}]}, {"meaning": "栖止,停留。", "cites": [{"t": "独泊灵台侧。", "b": "唐·陈子昂《古意》"}], "words": [{"w": "漂泊", "t": ""}]}, {"meaning": "淡泊;恬静(心地安然,不为名利所动)。", "cites": [{"t": "我独泊兮其未兆,如婴儿之未孩。", "b": "《老子》"}, {"t": "非淡泊无以明志,非宁静无以致远。", "b": "诸葛亮《诫子书》"}], "words": [{"w": "淡泊", "t": "不追求名利"}, {"w": "泊如", "t": "水宽大的样子,恬淡无欲。"}]}, {"meaning": "轻微;不厚道。", "cites": [{"t": "禀气有厚泊,故性有善恶也。", "b": "《论衡·率性》"}], "words": [{"w": "泊礼", "t": "薄礼"}, {"w": "酒之厚泊", "t": ""}]}]}, {"pinyin": "pō", "defs": [{"meaning": "粘。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1250wx','沿','1','yán','氵','8','','[{"pinyin": "yán", "defs": [{"meaning": "同本义。", "cites": [{"t": "王沿夏,将欲入鄢。", "b": "《左传》"}, {"t": "沿于江海,达于淮泗。", "b": "《书·禹贡》"}], "words": [{"w": "沿溯", "t": "顺水下行与逆水上行"}, {"w": "沿涉", "t": "顺流而行"}, {"w": "沿流", "t": "顺流而下。"}]}, {"meaning": "遵循;因袭。", "cites": [{"t": "五帝殊时,不相沿乐,三王异世,不相袭理。", "b": "《礼记·乐记》"}], "words": [{"w": "沿袭", "t": "遵循旧制"}, {"w": "世代相沿;相沿成习;沿习", "t": "因袭;向来因循的习惯"}, {"w": "沿惯", "t": "依照惯例。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1251wx','泡','1','pào pāo','氵','8','','[{"pinyin": "pào", "defs": [{"meaning": "(形声。从水,包声。本义:浮沤,水泡)。"}]}, {"pinyin": "pāo", "defs": [{"meaning": "古水名。又名丰水。", "cites": [{"t": "泡,泡水,出山阳平乐,东北入泗。", "b": "《说文》"}]}, {"meaning": "盛大。", "cites": [{"t": "泡,盛也。", "b": "《方言》二"}], "words": [{"w": "泡溲", "t": "水盛大的样子。"}]}, {"meaning": "相当于“番”、“回”。", "cites": [{"t": "顺便去会制台,着实恭维一泡。", "b": "《文明小史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1252wx','注','1','zhù','氵','8','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从水,主声。本义:灌入,注入)。"}, {"meaning": "同本义。", "cites": [{"t": "注,灌也。", "b": "《说文》"}, {"t": "振盪注流。", "b": "左思《吴都赋》"}, {"t": "丰水东注。", "b": "《诗·大雅·文王有声》"}, {"t": "声如震雷破山,泪如倾河注海。", "b": "《世说新语·言语》"}, {"t": "而泽下注。", "b": "明·归有光《项脊轩志》"}, {"t": "大雨如注。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "暴雨下如注,水潦成流。", "b": "《东观汉记》"}, {"t": "解州盐泽,方百二十里,久雨,四山之水悉注其中。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "把酒注到瓶里;注溉", "t": "灌溉"}, {"w": "注萤", "t": "以水浇灌萤火"}, {"w": "注集", "t": "流泻汇集"}, {"w": "注溜", "t": "倾泻的水流。"}]}, {"meaning": "集中;聚集。", "cites": [{"t": "及弊田,令禽注于虞中。", "b": "《周礼·天官·兽人》"}, {"t": "谢注神倾意,不觉流汗交面。", "b": "《世说新语·文学》"}], "words": [{"w": "注心", "t": "集中心意,专心"}, {"w": "注耳", "t": "倾耳"}, {"w": "注仰", "t": "抬头注视"}, {"w": "注盼", "t": "凝视"}, {"w": "注神", "t": "凝神"}, {"w": "注眼", "t": "集中目光看"}, {"w": "注眸", "t": "凝眸"}, {"w": "注睇", "t": "凝眸斜视。"}]}, {"meaning": "解释古书原文意义为“注”(解释前人注文的意义为“疏”)。", "cites": [{"t": "其有明圣人之道,尽六经之意,而不能诵疏与注,一切弃之。", "b": "柳冕《与权德舆书》"}, {"t": "及景纯注《雅》,动植必赞。", "b": "《文心雕龙·颂赞》"}, {"t": "郑玄欲注《春秋传》。", "b": "《世说新语·文学》"}, {"t": "注曰“不好”,改为“过”。(注曰,在旁边注明。)", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "注本", "t": "带有注释的版本"}, {"w": "注述", "t": "注释"}, {"w": "注训", "t": "注解"}, {"w": "注家", "t": "注解古籍的人。"}]}, {"meaning": "投;击。", "cites": [{"t": "以瓦注者巧,以钩注者惮,以黄金注者昏", "b": "《庄子·达生》"}]}, {"meaning": "连为一个整体;连接。", "cites": [{"t": "首尾连注,千里不绝。", "b": "《北史》"}, {"t": "船上伙计注好纤绳,跳上干岸。", "b": "《何典》"}], "words": [{"w": "注易", "t": "接连不断"}, {"w": "注连", "t": "连属,接连不断。"}]}, {"meaning": "预示。", "cites": [{"t": "南斗注生,北斗注死。", "b": "《搜神记》"}]}, {"meaning": "涂抹。", "cites": [{"t": "注了红脂,着意再描双蛾。", "b": "清·洪昇《长生殿·春睡》"}, {"t": "注口樱桃小,添眉桂叶浓。", "b": "李贺《恼公》"}]}, {"meaning": "记载。", "cites": [{"t": "元初五年,平望侯刘毅以太后多德政,欲令早有注记。", "b": "《后汉书》"}]}, {"meaning": "预先决定。", "cites": [{"t": "这命须臾!也是年该月值前生注,来到山溪野路。", "b": "康海《中山狼》"}]}, {"meaning": "附着;安放。", "cites": [{"t": "注旄首曰旌。", "b": "《尔雅·释天》"}]}, {"meaning": "输送。", "cites": [{"t": "令禽注于虞中。", "b": "《周礼·天官·兽人》"}]}, {"meaning": "赌注。", "cites": [{"t": "一日,博局争注,欧杀人命,亡归平阳。", "b": "《聊斋志异》"}], "words": [{"w": "注头", "t": "赌注;赌博时押的钱"}, {"w": "注马", "t": "赌注:下注。"}]}, {"meaning": "用于斟注的小壶。", "cites": [{"t": "他则水注:五彩注,石榴注,彩色双瓜注,双鸳注,双鹅注。", "b": "刘侗、于奕正《帝京景物略》"}]}, {"meaning": "屋檐滴水处。", "cites": [{"t": "高廊四注,重坐曲阁。", "b": "司马相如《上林赋》"}]}, {"meaning": "古地名 。故址在河南省临汝县西。", "cites": [{"t": "[魏文侯]三十二年,伐郑城酸枣。败秦于注。", "b": "《史记》"}]}, {"meaning": "用于赌注。赌博时一次所用的本钱叫一注。", "cites": [{"t": "李逵道:“我不傍猜,只要博这一博,五两银子做一注。”", "b": "《水浒全传》"}]}, {"meaning": "用于钱款、交易等。相当于“笔”、“桩”。", "cites": [{"t": "头一年,省亲连盖花园子,你算一算那一注花了多少,就知道了。", "b": "《红楼梦》"}]}, {"meaning": "用于雨。相当于“阵”、“场”。", "cites": [{"t": "萤飞渐多屋渐薄,一注愁霖当面落。", "b": "陆龟蒙《奉酬袭美苦雨见寄》"}]}, {"meaning": "用文字解释词句。", "cites": [{"t": "《说文》无註字。《说文解字序》:保氏教国子,先以六书,五曰转注。其字作“注。”段玉裁曰:“俗作注”。", "b": "清·雷浚《说文外编》"}, {"t": "先儒传埻,一切废不用。", "b": "《宋史》"}], "words": [{"w": "批注", "t": "加评语和注解"}, {"w": "评注", "t": "评论并注解"}, {"w": "注述", "t": "注释和著述"}, {"w": "注官", "t": "注出拟授官职"}, {"w": "注家", "t": "从事注释的人"}, {"w": "注语", "t": "用作说明的文字"}, {"w": "注赞", "t": "关于言行的说明和赞语。"}]}, {"meaning": "记载;登记。", "cites": [{"t": "一事註乎志,所以恶子也。", "b": "《谷梁传》"}, {"t": "重黎记註。", "b": "《后汉书》"}], "words": [{"w": "注代", "t": "古代前后仕官吏替换时登记备案"}, {"w": "注记", "t": "记载,记录。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1253wx','泣','1','qì','氵','8','','[{"pinyin": "qì", "defs": [{"meaning": "(形声。从水,立声。本义:无声或低声地哭)。"}, {"meaning": "同本义。", "cites": [{"t": "持其踵为之泣。", "b": "《战国策·赵策》"}, {"t": "如闻泣幽咽。", "b": "唐·杜甫《石壕吏》诗"}, {"t": "连拜且泣。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "太监泣别。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "泣励", "t": "哭着激励"}, {"w": "泣詈", "t": "边哭边骂"}, {"w": "泣血捶膺", "t": "形容悲痛欲绝的样子"}, {"w": "泣血", "t": "无声痛哭,泪如血涌"}, {"w": "泣别", "t": "流泪告别。"}]}, {"meaning": "眼泪。", "cites": [{"t": "泣下沾衿。", "b": "《汉书·李广苏建传》"}, {"t": "座中泣下谁最多。", "b": "唐·白居易《琵琶行(并序)》诗"}, {"t": "泣下沾襟。", "b": "宋·欧阳修《伶官传(序)》"}, {"t": "因泣下。", "b": "清·张廷玉《明史》"}, {"t": "泣涕(泣泪。眼泪);饮泣(含忍眼泪,形容极其悲痛)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1254wx','泞','1','nìng','氵','8','','[{"pinyin": "nìng", "defs": [{"meaning": "(形声。从水,宁声。本义:泥浆) 同本义。", "cites": [{"t": "泞,荥泞也。", "b": "《说文》"}]}, {"meaning": "按,荥泞叠韵连语,小水之貌。", "cites": [{"t": "戎马还泞而止。", "b": "《左传·僖公十五年》"}, {"t": "不泞车辆。", "b": "《管子·地员》"}, {"t": "一旬半雷雨,泥泞相牵攀。", "b": "杜甫《彭衙行》"}], "words": [{"w": "泞淖", "t": "泥泞;泥淖"}, {"w": "泞溺", "t": "被泥泞掩盖"}, {"w": "泞滞", "t": "谓泥水淤积难行"}, {"w": "泞潦", "t": "泥水淤积"}, {"w": "路泞难行", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1255wx','泻','1','xiè','氵','8','','[{"pinyin": "xiè", "defs": [{"meaning": "倾泻。", "cites": [{"t": "泻,倾也。", "b": "《玉篇》"}, {"t": "以浍写(泻)水。", "b": "《周礼·地官·稻人》"}, {"t": "急雨如河泻瓦沟,空堂卧对一灯幽。", "b": "宋·陆游《雨夜》"}], "words": [{"w": "泻泪", "t": "形容泪流如注"}, {"w": "泻溜", "t": "泻下小股水流"}, {"w": "泻月", "t": "形容泉水如月光倾洒"}, {"w": "泻润", "t": "谓雨水倾泻滋润。比喻帝王下施恩泽。"}]}, {"meaning": "倾注;倾倒。", "cites": [{"t": "吟诗欲泻百重愁。", "b": "《水浒全传》"}], "words": [{"w": "泻注", "t": "倾注"}, {"w": "泻盆", "t": "大雨倾盆"}, {"w": "泻辩", "t": "滔滔不绝地辩论"}, {"w": "泻囊", "t": "倾囊,谓拿出所有的钱。"}]}, {"meaning": "排泄。", "cites": [{"t": "泻,吐泻。", "b": "《广韵》"}], "words": [{"w": "泻邪", "t": "中医谓以药物泄去致病的因素"}, {"w": "泻痢", "t": "下痢"}, {"w": "泻证", "t": "下泻的症候"}, {"w": "泻火", "t": "中医为清泻邪火实热的一种治法"}, {"w": "上吐下泻", "t": ""}]}, {"meaning": "消散。", "cites": [{"t": "…,以适筋骨肉血脉,以泻气。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1256wx','泌','1','bì mì','氵','8','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从水,必声。本义:泉水涌出的样子) 同本义。", "cites": [{"t": "泌,侠流也。", "b": "《说文》"}, {"t": "泌之洋洋,可以乐饥。", "b": "《诗·陈风·衡门》。孔颖达疏:“泌者,泉水涓流不已,乃至广大。”"}]}, {"meaning": "又指涌出的泉水。"}, {"meaning": "水名。"}, {"meaning": "在河南省西南部,唐河上游的别称。"}, {"meaning": "在山东省中部,源出肥城县,流入汶水。现称卫鱼河。"}]}, {"pinyin": "mì", "defs": [{"meaning": "", "words": [{"w": "泌渗", "t": "液体从细小的空隙中慢慢地透出。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1257wx','泳','1','yǒng','氵','8','','[{"pinyin": "yǒng", "defs": [{"meaning": "(形声。从水,永声。本义:潜行水中;游泳) 同本义。", "cites": [{"t": "泳,潜行水中也。", "b": "《说文》"}, {"t": "泳,游也。", "b": "《尔雅·释言》"}, {"t": "潜行为泳。", "b": "《尔雅·释水》"}, {"t": "泳之游之。", "b": "《诗·邶风·谷风》"}, {"t": "复从而泳之。", "b": "《列子·黄帝》"}, {"t": "汉之广矣,不可泳思。", "b": "《诗·周南·汉广》"}], "words": [{"w": "泳涵", "t": "涵泳,沉浸"}, {"w": "游泳", "t": "人或动物在水里游动"}, {"w": "仰泳;蛙泳", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1258wx','泥','1','ní nì','氵','8','','[{"pinyin": "ní", "defs": [{"meaning": "(形声。从水,尼声。本义:泥水)。"}, {"meaning": "中国古水名,泾水支流,即今甘肃省庆阳地区的东河及其下流马连河。", "cites": [{"t": "泥,泥水也。出北地郁郅北蛮中。亦曰白马水。一名东河。", "b": "《说文》"}, {"t": "北地郡郁郅县,泥水出北蛮夷中。", "b": "《汉书》"}]}, {"meaning": "泥土;泥巴。", "cites": [{"t": "厥土惟涂泥。", "b": "《书·禹贡》"}, {"t": "致远恐泥。", "b": "《论语》"}, {"t": "存者无消息,死者为尘泥。", "b": "杜甫《无家别》"}, {"t": "谁家新燕啄春泥。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "泥中死者。", "b": "《资治通鉴》"}], "words": [{"w": "泥木", "t": "土木"}, {"w": "泥水", "t": "带泥土的水"}, {"w": "泥牛", "t": "即土牛"}, {"w": "泥冈子", "t": "土山冈"}, {"w": "泥坂", "t": "土坡"}, {"w": "泥灰", "t": "灰土"}, {"w": "泥尘", "t": "尘土"}, {"w": "泥墩墩", "t": "土墩子。比喻呆板无用的人"}, {"w": "泥垡头", "t": "泥土块。"}]}, {"meaning": "泥水,稀泥;烂泥。", "cites": [{"t": "震遂泥。", "b": "《易·震卦》。虞注:“坤土得雨为泥。”"}, {"t": "胡为乎泥中。", "b": "《诗·邶风·式微》"}, {"t": "市南门外泥中歇。", "b": "唐·白居易《卖炭翁》"}, {"t": "尘泥渗漉。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "泥掌", "t": "泥水匠用以抹平墙壁的泥镘"}, {"w": "泥书", "t": "泥封的书函"}, {"w": "泥头", "t": "指封酒坛口的泥巴"}, {"w": "泥缄", "t": "古人书函多以泥封,后因以借指书信"}, {"w": "泥章", "t": "封泥上所盖的印章"}, {"w": "泥淖", "t": "烂泥;淤泥"}, {"w": "泥荡", "t": "泥潭。泥坑"}, {"w": "泥沟", "t": "烂泥淤积的水沟。"}]}, {"meaning": "一堆捣成或压成的柔软的糊状混合料。", "cites": [{"t": "那庄家连忙取半只熟狗肉,捣些蒜泥,将来放在智深面前。", "b": "《水浒传》"}], "words": [{"w": "枣泥;土豆泥;蒜泥", "t": ""}]}, {"meaning": "读“niè”,通“涅”,染黑。", "cites": [{"t": "皭然泥而不滓者也。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "软弱无力。", "cites": [{"t": "威夷(兽名),长颈而泥。", "b": "《尔雅·释兽》"}]}]}, {"pinyin": "nì", "defs": [{"meaning": "阻塞,阻滞。", "cites": [{"t": "虽小道,必有可观者焉,致远恐泥。", "b": "《论语·子张》"}], "words": [{"w": "泥滞", "t": "滞留,停留"}, {"w": "泥漉", "t": "阻塞干涸"}, {"w": "泥饮", "t": "强留饮酒"}, {"w": "江为山所泥", "t": ""}]}, {"meaning": "拘泥于;拘执,不变通。", "cites": [{"t": "总而言之,不能泥信的就是了。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "泥文", "t": "拘泥于文字"}, {"w": "泥定", "t": "株守;拘执"}, {"w": "泥信", "t": "拘泥一面,过分相信"}, {"w": "泥执", "t": "拘泥固执"}, {"w": "泥常", "t": "拘泥于常规"}, {"w": "泥象", "t": "拘泥形迹"}, {"w": "泥视", "t": "谓死板地看问题。"}]}, {"meaning": "涂沫。", "cites": [{"t": "王以赤石脂泥壁。", "b": "《世说新语·汰侈》"}], "words": [{"w": "泥坦克", "t": ""}]}, {"meaning": "糊。", "cites": [{"t": "红纸泥窗绕画廊。", "b": "花蕊夫人《宫词》"}]}, {"meaning": "软求,软缠;缠着。", "cites": [{"t": "年年至日长为客,忽忽穷愁泥杀人。", "b": "杜甫《冬至》"}, {"t": "翠环仍泥着不肯去。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1259wx','沸','1','fèi','氵','8','','[{"pinyin": "fèi", "defs": [{"meaning": "(形声。从水,弗声。本义:泉水大量涌出的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "沸,滭沸滥泉也。", "b": "《说文》。按,涌出之貌。"}, {"t": "觱沸槛泉。", "b": "《诗·小雅·采菽》"}, {"t": "百川沸騰。", "b": "《诗·小雅·十月之交》"}, {"t": "愤泉秋沸。", "b": "北周·庾信《哀江南赋》"}], "words": [{"w": "沸沸", "t": "翻滚涌现的样子;行事迅速果断的样子"}, {"w": "沸射", "t": "喷射"}, {"w": "沸然", "t": "水腾涌的样子。"}]}, {"meaning": "水波翻涌的样子。", "cites": [{"t": "宫殿摆簸,云烟沸涌。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "沸波", "t": "鸟名。即鱼鹰。因俯冲食水中鱼时扬起波浪"}, {"w": "沸渭", "t": "水翻腾奔涌的样子"}, {"w": "沸泻", "t": "水流翻滚奔腾。"}]}, {"meaning": "把水烧开;沸腾。", "cites": [{"t": "抽薪止沸,剪草除根。", "b": "魏收《为侯景叛移梁朝文》"}], "words": [{"w": "沸煎", "t": "沸滚,沸腾翻滚"}, {"w": "沸溢", "t": "水翻滚漫出"}, {"w": "沸动", "t": "翻动。"}]}, {"meaning": "声音喧闹或嘈杂。", "cites": [{"t": "沸乎暴怒。", "b": "司马相如《上林赋》"}, {"t": "临河列阵,百余里中,钟鼓之声沸河动地。", "b": "《晋书·刘曜载记》"}], "words": [{"w": "沸喧", "t": "沸激。像滚水一样喧闹"}, {"w": "沸耳", "t": "声音喧腾"}, {"w": "沸聒", "t": "喧腾,嘈杂"}, {"w": "沸闹", "t": "喧闹"}, {"w": "沸稠", "t": "繁密喧腾。"}]}, {"meaning": "沸水。", "cites": [{"t": "以指挠沸。", "b": "《荀子·议兵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1260wx','沼','1','zhǎo','氵','8','','[{"pinyin": "zhǎo", "defs": [{"meaning": "(形声。从水,召声。本义:水池,积水的洼地。上古时期,池和沼都表水池,塘在中古时期才表示水池。一说圆曰池,曲曰沼)。"}, {"meaning": "同本义。", "cites": [{"t": "沼,小池也。", "b": "《一切经音义》引《说文》"}, {"t": "于沼于沚。", "b": "《诗·召南·采蘩》"}, {"t": "鱼在于沼,亦匪克乐。", "b": "《诗·小雅·正月》"}, {"t": "龟龙在宫沼。", "b": "《礼记·礼运》"}, {"t": "涧溪沼沚之毛。", "b": "《左传·隐公三年》"}, {"t": "王立于沼上。", "b": "《孟子》"}, {"t": "射沼滨之高鸟。", "b": "《淮南子·原道》"}, {"t": "茅覆环堵亭,泉添方丈沼。", "b": "唐·白居易《过骆山人野居小池》"}], "words": [{"w": "沼沚", "t": "池塘。亦借指积水坑"}, {"w": "沼气", "t": ""}]}, {"meaning": "池水。", "cites": [{"t": "御坐前建蓬莱山,曲池接筵,飞沼拂席。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1261wx','波','1','bō','氵','8','','[{"pinyin": "bō", "defs": [{"meaning": "(形声。从水,皮声。本义:波浪,水自身涌动而成波动的水面)。"}, {"meaning": "同本义。", "cites": [{"t": "波,水涌流也。", "b": "《说文》"}, {"t": "规有摩而水有波。", "b": "《韩非子·八说》"}, {"t": "起波涛。", "b": "《淮南子·人间》。注:“波者,涌起。”"}, {"t": "河渭为之波荡。", "b": "张衡《西京赋》"}, {"t": "扬素波而挥连珠兮。", "b": "《文选·王褒·洞箫赋》"}, {"t": "清风徐来,水波不兴。", "b": "苏轼《赤壁赋》"}, {"t": "洪波涌起。", "b": "《乐府诗集·曹操·步出夏门行》"}], "words": [{"w": "波磔", "t": "向右下捺的一笔叫磔,波浪形的叫波磔"}, {"w": "波查", "t": "苦难;折磨"}, {"w": "波平如镜", "t": "水面平静如镜"}, {"w": "波臣为虐", "t": "指水灾"}, {"w": "波骇", "t": "水波激烈动荡。引申为受到震撼"}, {"w": "波峭", "t": "指岩石或屋宇的曲折峻峭。后用以形容人物的威仪俊伟有风致。"}]}, {"meaning": "涌流的水;流水。", "cites": [{"t": "长桥卧波。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "波路", "t": "水路;航路"}, {"w": "波流", "t": "水流;支流"}, {"w": "波神", "t": "水神。"}]}, {"meaning": "目光流转;流转的目光。", "cites": [{"t": "目流睇而横波。", "b": "傅毅《舞赋》"}], "words": [{"w": "眼波", "t": "形容流动如水波的眼睛"}, {"w": "秋波", "t": "比喻美女的眼睛"}, {"w": "波俏", "t": "俏丽。"}]}, {"meaning": "激荡,起水波。", "cites": [{"t": "洞庭波兮木叶下。", "b": "《楚辞·九歌·湘夫人》"}], "words": [{"w": "波腾", "t": "波浪涌起的样子。多比喻众议激烈"}, {"w": "波靡", "t": "随波起伏,顺风而倒"}, {"w": "波荡", "t": ""}]}, {"meaning": "奔;逃跑。", "cites": [{"t": "各自波逃,信脚而走。", "b": "敦煌本《张义潮变文》"}], "words": [{"w": "波波", "t": "劳苦奔波的样子"}, {"w": "波波碌碌", "t": "奔走忙碌的样子"}, {"w": "波逃", "t": "逃跑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1262wx','泼','1','pō','氵','8','','[{"pinyin": "pō", "defs": [{"meaning": "(形声。从水,发声。本义:水漏出。见《玉篇》。用力向外倒或洒)。"}, {"meaning": "同本义。", "cites": [{"t": "又夹百千求救声,曳屋许许声,抢夺声,泼水声。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "泼丢泼养", "t": "像泼脏水那样去养育小儿,指让小儿风里吹,泥里滚,反能养大"}, {"w": "泼撒", "t": "花钱大手大脚"}, {"w": "泼水难收", "t": "比喻不可挽回的局面"}, {"w": "泼污水", "t": "比喻对人或对事进行诬蔑和打击"}, {"w": "泼油救火", "t": "用油去扑灭火焰。比喻使用的方法不对头,不仅于事无补,反使情况更加严重"}, {"w": "泼散", "t": "泼撒;用水冲击物体。"}]}, {"meaning": "泡。", "cites": [{"t": "唤老婢泼出一盏热腾腾的茶,将托盘托将出来。", "b": "《警世通言》"}]}, {"meaning": "淹死。", "cites": [{"t": "至有不识水性深浅者,学弄潮,多有被泼了去,坏了性命。", "b": "《警世通言》"}]}, {"meaning": "凶悍,蛮横,耍赖。", "cites": [{"t": "那泼贱贼也敢来这里害我!", "b": "《水浒传》"}], "words": [{"w": "泼贱", "t": "蛮横卑贱的人"}, {"w": "泼恶", "t": "蛮横;凶恶"}, {"w": "泼做", "t": "蛮干"}, {"w": "泼婆娘", "t": "凶悍的妇人"}, {"w": "泼娼根", "t": "贱婊子"}, {"w": "泼声厉言", "t": "泼辣的声音,严厉的语言"}, {"w": "泼恶", "t": "蛮横凶狠。"}]}, {"meaning": "讨厌,恶劣;无赖;可恶。", "cites": [{"t": "腌臢打脊泼才,叫你认得洒家。", "b": "《水浒传》"}], "words": [{"w": "泼才", "t": "蛮横不讲理的家伙"}, {"w": "泼脚子货", "t": "蛮横不讲理的人"}, {"w": "泼物", "t": "坏蛋;泼皮"}, {"w": "泼言语", "t": "流氓言语;污秽的话"}, {"w": "泼辣货", "t": "直率疯癫无拘束的女子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1263wx','泽','1','zé','氵','8','','[{"pinyin": "zé", "defs": [{"meaning": "(形声。从水。睪(yì)声。本义::光泽,润泽)。"}, {"meaning": "同本义。", "cites": [{"t": "泽,光润也。", "b": "《说文》"}, {"t": "共饭不泽手。", "b": "《礼记·曲礼》"}, {"t": "泽剑首。", "b": "《礼记·少仪》"}, {"t": "实诸泽器。", "b": "《考工记·慌氏》"}, {"t": "顺非而泽。", "b": "《荀子·礼论》"}, {"t": "芳与泽其杂糅兮。", "b": "《离骚》"}, {"t": "热多则淖泽。", "b": "《素问·经络论》"}, {"t": "色沃不泽。", "b": "《素问·玉机真藏论》"}, {"t": "色泽莹润。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "根色鲜泽。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "仁义不足泽其性,礼乐不足锢其情。", "b": "王安石《太古》"}], "words": [{"w": "泽雨", "t": "润泽万物之雨"}, {"w": "泽器", "t": "润泽光滑的器皿"}, {"w": "色泽", "t": "颜色和光泽。"}]}, {"meaning": "水深的湖泽或水草丛杂的湖泽。", "cites": [{"t": "下而有水曰泽,言润泽也。", "b": "《释名》"}, {"t": "水草交厝名之为泽。言其润泽万物以阜民用也。", "b": "《风俗通》"}, {"t": "泽水之钟也。", "b": "《国语·周语》"}, {"t": "川壅为泽。", "b": "《左传·宣公十二年》"}, {"t": "泽居苦水者,买庸而决窦。", "b": "《韩非子·五蠹》"}, {"t": "山泽不避。", "b": "《史记·货殖列传》"}, {"t": "行吟泽畔。", "b": "《史记·屈原贾生列传》"}, {"t": "在某泽中。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "泽陂", "t": "池沼"}, {"w": "泽皋", "t": "沼泽"}, {"w": "泽淖", "t": "泥潭"}, {"w": "泽农", "t": "指在水泽地区耕作的农夫"}, {"w": "泽卤", "t": "地低洼而多盐碱"}, {"w": "泽薮", "t": "大泽"}, {"w": "川泽", "t": ""}]}, {"meaning": "恩泽,恩惠。", "cites": [{"t": "泽及万世而不为仁。", "b": "《庄子·大宗师》"}, {"t": "故西门豹为邺令,名闻天下,泽流后世。", "b": "《史记·西门豹传》"}], "words": [{"w": "泽民", "t": "施恩惠于民"}, {"w": "泽物", "t": "施恩于人,做好事"}, {"w": "泽枯,泽骨", "t": "恩泽施及死去的人。形容恩情深厚"}, {"w": "泽霈", "t": "恩惠普施"}, {"w": "泽润", "t": "恩泽普施。"}]}, {"meaning": "仁慈的行动。", "cites": [{"t": "殷王亦罔敢失帝,罔不配天其泽。", "b": "《书·多士》"}]}, {"meaning": "雨和露。", "cites": [{"t": "两泽下注。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "泽下尺,升上尺", "t": "天上的雨下落一尺,地上的禾苗就向上长一尺。比喻君王赐给臣民恩泽,臣民就拥戴君王。"}]}, {"meaning": "土壤中的水分。", "cites": [{"t": "凡耕之本,在于趣时,和土,务粪泽,早锄早获。", "b": "《齐民要术》"}]}, {"meaning": "津液、唾液或汗水。", "cites": [{"t": "几扇门窗上就留着他的手泽了。", "b": "叶圣陶《小铜匠》"}]}, {"meaning": "润头发或皮肤的油脂。", "cites": [{"t": "你让我来分你一些香泽吧!", "b": "郭沫若《王昭君》"}], "words": [{"w": "芳泽;香泽", "t": ""}]}, {"meaning": "汗衣;内衣。", "cites": [{"t": "岂曰无衣,与子同泽。", "b": "《诗·秦风·无衣》"}]}, {"meaning": "禄位;遗风。", "cites": [{"t": "君子之泽,五世而斩。", "b": "《孟子》"}], "words": [{"w": "手泽", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1264wx','治','1','zhì','氵','8','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从水,台声。①(chí)本义:水名。②引申义:治水;整治;修治)。"}, {"meaning": "同引申义。", "cites": [{"t": "昔禹治洪水。", "b": "郦道元《水经注》"}, {"t": "民治渠。", "b": "褚少孙《西门豹治邺》"}, {"t": "遂治别院,使夫妇成礼。", "b": "《聊斋志异·小翠》"}, {"t": "其后治装行,东入海求其师云。", "b": "《史记·孝武本纪》"}], "words": [{"w": "治酒", "t": "置办酒食"}, {"w": "治步", "t": "修整仪容,举止合乎法度"}, {"w": "治任", "t": "整理行装"}, {"w": "治行", "t": "治严。整理行装"}, {"w": "治缮", "t": "修缮"}, {"w": "治茸", "t": "修缮。"}]}, {"meaning": "治理;管理;统治。", "cites": [{"t": "治国无法则乱。", "b": "《吕氏春秋·察今》"}, {"t": "或劳心,或劳力。劳心者治人,劳力者治于人。治于人者食人,治人者食于人。", "b": "《孟子·滕文公上》"}, {"t": "伯乐善治马。", "b": "《庄子·马蹄》"}, {"t": "衡下车,治威严,整法度。(治威严,树立威信。)", "b": "《后汉书·张衡传》"}], "words": [{"w": "天下大治;法治;人治;自治;根治;治公", "t": "治理公务;办公"}, {"w": "治戎", "t": "治军,用兵"}, {"w": "治具", "t": "治理国家的各项措施"}, {"w": "治术", "t": "治理国家的方法"}, {"w": "治制", "t": "治理国家的法制、体制"}, {"w": "治道", "t": "治理国家的方针、政策、措施等"}, {"w": "治乱", "t": "治理混乱的局面,使国家安定、太平"}, {"w": "治掌", "t": "掌管"}, {"w": "治市", "t": "古代掌管市场贸易的官员。"}]}, {"meaning": "办理;处理。", "cites": [{"t": "后频历武威二郡太守,随俗化导,各得治宜。", "b": "《后汉书·廉范传》"}, {"t": "皆尚威严,有治办名。", "b": "《汉书·酷吏传·尹赏》"}], "words": [{"w": "治办", "t": "善于办理事物"}, {"w": "治剧", "t": "办理繁杂的工作"}, {"w": "治事", "t": "办理公事"}, {"w": "治数", "t": "处理各种事务"}, {"w": "治宜", "t": "处理事务合宜"}, {"w": "治干", "t": "处理政务的才干。"}]}, {"meaning": "经营。", "cites": [{"t": "父子治产,居无几何,致产数十万。", "b": "《史记·越王勾践世家》"}], "words": [{"w": "治产", "t": "经营产业。"}]}, {"meaning": "治;治疗。", "cites": [{"t": "如人有疾,不治则寝以深。", "b": "《盐铁论·世务》"}], "words": [{"w": "治得病治不得命", "t": "迷信指命定该死,怎么治疗也不行"}, {"w": "他的病不久就治好了;治聋", "t": "医治耳聋。"}]}, {"meaning": "惩处;惩办。", "cites": [{"t": "治古无肉刑,而有象刑。", "b": "《荀子·正论》"}, {"t": "高有大罪,秦王令蒙毅法治之。", "b": "《史记·蒙恬列传》"}, {"t": "不效则治臣之罪,以告先帝之灵。", "b": "诸葛亮《出师表》"}], "words": [{"w": "惩治;治释", "t": "惩治与赦免。"}]}, {"meaning": "修筑。", "cites": [{"t": "又治秦中。", "b": "《汉书·高帝纪》。注:“谓都之也。”"}, {"t": "治居第于封丘门内。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "整顿,训练。", "cites": [{"t": "治其大礼。", "b": "《周礼·大宗伯》。注:“犹简习也。”"}, {"t": "今治水军八十万众,方与将军会猎于吴。", "b": "《资治通鉴》"}], "words": [{"w": "治礼", "t": "讲习礼仪。"}]}, {"meaning": "研究。", "cites": [{"t": "此真治异国语言文字者之至乐也。", "b": "严复《译天演论序》"}], "words": [{"w": "治经", "t": "研究经学。"}]}, {"meaning": "政治。", "cites": [{"t": "冢宰掌邦治,统百官,均四海。", "b": "《书·周官·太宰》"}], "words": [{"w": "治体", "t": "政治法度"}, {"w": "治号", "t": "治令; 政令"}, {"w": " 治务", "t": "政务"}, {"w": " 治绩", "t": "政绩。"}]}, {"meaning": "社会安定、太平(跟“乱”相对)。", "cites": [{"t": "禹以治,桀以乱,治乱非天也。", "b": "《荀子·天论》"}]}, {"meaning": "又。", "cites": [{"t": "受时与治世同,而殃祸与治世异》", "b": ""}, {"t": "是以厚赏不行,重罚不用,而民自治。", "b": "《韩非子·五蠹》"}, {"t": "君子安而不忘危,…,治而不忘乱。", "b": "《易·系辞下》"}, {"t": "治平至百余年。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "治强", "t": "安定强盛"}, {"w": "治康", "t": "国家太平安宁"}, {"w": "治乱", "t": "安定与动乱。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1265wx','怔','1','zhēng zhèng','忄','8','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从心,正声。本义:惶恐不安的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "军书交驰,羽檄狎至,乃复怔忪如前。", "b": "《潜夫论》"}], "words": [{"w": "怔忡之症", "t": "心脏跳动加速、节律不整的病症"}, {"w": "怔忡", "t": "惊恐不安;又指患者心脏跳动剧烈的一种症状。"}]}, {"meaning": "发愣,发呆。", "cites": [{"t": "那丫鬟倒发了个怔。", "b": "《红楼梦》"}], "words": [{"w": "怔怔", "t": "呆愣的样子。"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "", "words": [{"w": "怔忪", "t": "惊恐不安"}, {"w": "怔营", "t": "惶恐不安"}, {"w": "怔忡", "t": "惊恐不安;又指心脏剧烈跳动的一种症状。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1266wx','怯','1','qiè','忄','8','','[{"pinyin": "qiè", "defs": [{"meaning": "(形声。从心,去声。《说文》:本从犬。本义:胆小,畏缩)。"}, {"meaning": "同本义 怯,多畏也。从犬,去声。杜林说,从心或曰劫省声。——《说文》。", "cites": [{"t": "持节不恐谓之勇,反勇为怯。", "b": "《贾子道术》"}, {"t": "怯者不得独退。", "b": "《孙子·军事》"}, {"t": "五不行,示赵弱且怯也。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "怯怯乔乔", "t": "战战兢兢"}, {"w": "怯壳儿", "t": "怯坎儿,怯条子。土气,没有见过大世面的人"}, {"w": "怯症", "t": "胆怯"}, {"w": "胆怯", "t": "胆小;畏缩"}, {"w": "羞怯", "t": "羞涩胆怯。"}]}, {"meaning": "土气。", "cites": [{"t": "怕人说他怯,笑他不开眼。", "b": "《负曝闲谈》"}]}, {"meaning": "虚弱。", "cites": [{"t": "一来我们身小力怯,着甚来由吃挨吃搅。", "b": "《京本通俗小说》"}]}, {"meaning": "害怕;畏惧。", "cites": [{"t": "勇士不怯死而灭名。", "b": "《史记·鲁仲连邹阳传》"}, {"t": "黄花不怯西风冷,只怕诗人两鬓霜。", "b": "辛弃疾《鹧鸪天》"}], "words": [{"w": "怯床", "t": "指妓女畏惧接客或男子性能力不足"}, {"w": "怯上", "t": "怕见地位高的人"}, {"w": "怯色", "t": "惊慌的表情。"}]}, {"meaning": "舍弃。", "cites": [{"t": "高声喝叫:“得莺莺便把残生怯。”", "b": "董解元《西厢记诸宫调》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1267wx','怖','1','bù','忄','8','','[{"pinyin": "bù", "defs": [{"meaning": "(形声。从心,布声。《说文》“作‘悑’”。本义:惶恐,惊惧)。"}, {"meaning": "同本义。", "cites": [{"t": "昔者纣为象箸而箕子怖。", "b": "《韩非子·喻老》"}, {"t": "吾畏其卒,故怖其始。", "b": ""}, {"t": "焦心怖肝。", "b": "《淮南子·脩务》"}, {"t": "神心怖覆。", "b": "《文选·宋玉·神女赋》"}], "words": [{"w": "恐怖", "t": "由于生命受到威胁而引起的恐惧"}, {"w": "怖畏", "t": "恐惧"}, {"w": "怖怯", "t": "胆小害怕;恐惧"}, {"w": "怖覆", "t": "恐怖而反复"}, {"w": "怖肝", "t": "戒惧"}, {"w": "怖沮", "t": "恐惧沮丧。"}]}, {"meaning": "恐吓。", "cites": [{"t": "依托鬼神,诈怖愚民。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1268wx','性','1','xìng','忄','8','','[{"pinyin": "xìng", "defs": [{"meaning": "(形声。从心,生声。本义:人的本性)。"}, {"meaning": "同本义。", "cites": [{"t": "性,人之阳气性善者也。", "b": "《说文》"}, {"t": "性,质也。", "b": "《广雅》"}, {"t": "天命之谓性。", "b": "《礼记·中庸》"}, {"t": "自诚明谓之性。", "b": ""}, {"t": "不可学,不可事,而在人者谓之性。", "b": "《荀子·性恶篇》"}, {"t": "五性者何?仁义礼智信也。", "b": "《白虎通》"}, {"t": "性相近也,习相远也。", "b": "《论语·阳货》"}, {"t": "生之所以然者谓之性。", "b": "《荀子·正名篇》"}], "words": [{"w": "性根", "t": "根性;本性"}, {"w": "性行", "t": "人的禀性和行为"}, {"w": "性气", "t": "人的个性和脾气"}, {"w": "个性", "t": "人的本性;人所具有的正常的感情或理性"}, {"w": "禀性", "t": "本性"}, {"w": "性尚", "t": "本性的爱好和崇尚。"}]}, {"meaning": "事物的性质或性能。", "cites": [{"t": "则天之明,因地之性。", "b": "《左传·昭公二十五年》"}, {"t": "物性之苦。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "物性之不同。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "性力", "t": "指药性和药力"}, {"w": "性状;共性", "t": "共同具有的性质。"}]}, {"meaning": "(shēng)。生命;生机。", "cites": [{"t": "莫保其性。", "b": "《左传·昭公八年》"}, {"t": "民乐其性,而无寇雠。", "b": "《左传·昭公十九年》"}, {"t": "为炮烙以伤民性。", "b": "《韩非子·难势》"}, {"t": "性命寿长,终其天年而不夭伤。", "b": "《史记·范雎蔡泽列传》"}, {"t": "以治气养性,则身后彭祖。", "b": "《韩诗外传·卷一》"}], "words": [{"w": "性理", "t": "谓生命之原理"}, {"w": "性类", "t": "犹生类,指有生命的物类。"}]}, {"meaning": "性情;脾气。", "cites": [{"t": "动心忍性。", "b": "《孟子·告子下》"}, {"t": "少无适俗韵,性本爱丘山。", "b": "晋·陶潜《归园田居》"}, {"t": "吾性不喜华靡。", "b": "宋·司马光《训俭示康》"}, {"t": "性悖妄。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "尊德性。", "b": "清·刘开《问说》"}], "words": [{"w": "性行淑均", "t": "性格和善,品行端正"}, {"w": "性耽隐癖", "t": "秉性迟钝,甘子寂寞"}, {"w": "性起", "t": "发脾气"}, {"w": "性理", "t": "性情和理智。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1269wx','怕','1','pà','忄','8','','[{"pinyin": "pà", "defs": [{"meaning": "(形声。从心,白声。怕就是怖,“怕”是中古的新字。本义:畏惧)同本义。", "cites": [{"t": "怕,怕惧。", "b": "《广韵》"}, {"t": "鬼神怕嘲咏。", "b": "韩愈《双鸟诗》"}, {"t": "粉骨碎身浑不怕。", "b": "明·于谦《石灰吟》"}], "words": [{"w": "惧怕", "t": "害怕"}, {"w": "害怕", "t": "遇到困难、危险等而心中不安或发慌"}, {"w": "怕怯", "t": "害怕。"}]}, {"meaning": "如其,倘。", "cites": [{"t": "您昆仲各东西,俺子母两分离,怕哥哥不嫌相辱呵?权为个妹!", "b": "《古今杂剧·关汉卿·拜月亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1270wx','怜','1','lián','忄','8','','[{"pinyin": "lián", "defs": [{"meaning": "(形声。从心,粦声。本义:哀怜,怜悯)。"}, {"meaning": "同本义。", "cites": [{"t": "憐,哀也。从心。粦声。字亦作怜。", "b": "《说文》"}, {"t": "矜憐抚掩之也。", "b": "《尔雅》"}, {"t": "独不怜公子姊邪?", "b": "《史记·魏公子列传》"}, {"t": "若俯首贴耳,摇尾而乞怜者,非我之志也。", "b": "韩愈《应科目时与人书》"}, {"t": "且喜且怜之。", "b": "《史记·淮阴侯列传》"}, {"t": "天子怜百姓新劳苦,故且休之。", "b": "《史记·郦生陆贾列传》"}, {"t": "所怜者。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "可怜", "t": "值得怜悯"}, {"w": "怜见", "t": "哀矜,怜悯"}, {"w": "怜拯", "t": "怜悯拯救"}, {"w": "怜鉴", "t": "哀怜审察"}, {"w": "怜闵", "t": "哀怜,同情。"}]}, {"meaning": "爱,惜。", "cites": [{"t": "憐,爱也。", "b": "《尔雅》"}, {"t": "楚人怜之。", "b": "《史记·陈涉世家》"}, {"t": "丈夫亦爱怜其少子乎?", "b": "《战国策·赵策》"}], "words": [{"w": "爱怜", "t": "十分疼爱"}, {"w": "怜才", "t": "爱惜人才"}, {"w": "怜忪", "t": "爱怜其惺忪之态"}, {"w": "怜香", "t": "喜爱花香"}, {"w": "怜遇", "t": "宠爱恩遇。"}]}, {"meaning": "吝惜。", "cites": [{"t": "不慕往,不闵来,无邑怜之心。", "b": "《荀子》"}], "words": [{"w": "怜下", "t": "怜惜下人"}, {"w": "怜嗟", "t": "怜惜嗟叹"}, {"w": "怜察", "t": "察知其情而怜惜之。"}]}, {"meaning": "遗憾。", "cites": [{"t": "所怜者,吾自戊寅年读汝哭侄诗后,…至今无男。", "b": "清·袁枚《祭妹文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1271wx','怪','1','guài','忄','8','','[{"pinyin": "guài", "defs": [{"meaning": "(形声。从心,圣(kù)声。恠曾为怪的俗字。本义:奇异;奇怪) 同本义。", "cites": [{"t": "怪,异也。", "b": "《说文》"}, {"t": "诡于众而突出曰怪。", "b": "《论衡·自纪》"}, {"t": "铅松怪石。", "b": "《书·禹贡》"}, {"t": "苟床之山多怪石。", "b": "《山海经·中山经》"}, {"t": "见怪物", "b": "《礼记·祭法》。疏:“庆云之属。”"}, {"t": "奇服怪民不入宫。", "b": "《周礼·阍人》"}, {"t": "齐谐者,志怪者也。", "b": "《庄子·逍遥游》"}, {"t": "嘻,技亦灵怪矣哉!", "b": "魏学洢《核舟记》"}, {"t": "绝巘多生怪柏,悬泉瀑布,飞潄其间。", "b": "《水经注·三峡》"}, {"t": "后小山下,怪石乱卧,针针丛棘,青麻头伏焉。", "b": "《聊斋志异·促织》"}], "words": [{"w": "怪伟", "t": "奇特雄伟"}, {"w": "怪物相", "t": "奇异的样子;轻蔑、难堪的脸色"}, {"w": "怪迂", "t": "怪异而不切实际"}, {"w": "怪谲", "t": "怪异任性。"}]}, {"meaning": "妖精,鬼物。", "cites": [{"t": "子不语怪、力、乱、神。", "b": "《论语·述而》"}, {"t": "土之怪为獖羊。", "b": "《博物志》"}, {"t": "山高必有怪。", "b": "《西游记》"}], "words": [{"w": "鬼怪;妖怪;精怪;神怪", "t": "神仙与鬼怪"}, {"w": "魔怪", "t": "妖魔鬼怪。"}]}, {"meaning": "责怪。", "cites": [{"t": "世果群怪聚骂,指目牵引,而增与为言辞。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "虽然,使后之为君者果能保此产业,传之无穷,亦无怪乎其私之也。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "怪责", "t": "责怪"}, {"w": "怪恨", "t": "责怪怨恨"}, {"w": "怪嗔", "t": "嗔怪,对别人的言语行为表示不满"}, {"w": "怪得", "t": "怪底;怪的。难怪,怪不得。"}]}, {"meaning": "惊异;觉得奇怪。", "cites": [{"t": "民怪之,莫敢徒。", "b": "《史记·商君列传》"}, {"t": "予怪而问之。", "b": "刘基《卖柑者言》"}], "words": [{"w": "怪底", "t": "惊怪,惊疑"}, {"w": "怪怖", "t": "惊异恐惧"}, {"w": "怪疑", "t": "骇异;惊异疑惑"}, {"w": "怪慑", "t": "惊异害怕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1272wx','怡','1','yí','忄','8','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从心,台(yí)声。本义:和悦的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "怡,和也。", "b": "《说文》"}, {"t": "公乃为诗以怡王。", "b": "《书·金传》。郑注:“悦也。”"}, {"t": "下气怡色。", "b": "《礼记·内则》。注:“悦也。”"}, {"t": "有庆未尝不怡。", "b": "《国语·周语》"}, {"t": "[亲稚]狗之事大矣,而主之色不怡,何也?", "b": "《国语》"}, {"t": "怡然自乐。", "b": "晋·陶渊明《桃花源记》"}, {"t": "心旷神怡。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "怡心", "t": "和悦心情"}, {"w": "怡目", "t": "悦目"}, {"w": "怡怡", "t": "怡悦神情"}, {"w": "怡情", "t": "怡悦心情"}, {"w": "怡魂", "t": "使精神愉快"}, {"w": "怡养", "t": "和乐"}, {"w": "怡声", "t": "犹柔声"}, {"w": "怡颜", "t": "和悦的容颜"}, {"w": "怡宁", "t": "安宁。"}]}, {"meaning": "喜乐的,使人心神感官愉快的。", "cites": [{"t": "怡,乐也。", "b": "《尔雅》"}, {"t": "眄庭柯以怡颜。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "怡色;怡愉", "t": "喜悦"}, {"w": "怡裕", "t": "安乐,欢乐"}, {"w": "怡畅", "t": "欢畅"}, {"w": "怡荡", "t": "怡悦放荡"}, {"w": "怡乐", "t": "安乐,快乐"}, {"w": "怡穆", "t": "愉悦和睦"}, {"w": "怡怿", "t": "愉悦;快乐。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1273wx','学','1','xué','子','8','','[{"pinyin": "xué", "defs": [{"meaning": "(形声。本作“壆”,象双手构木为屋形。后作声符,加“子”为义符。子,孩子。小孩子是学习的主体。本义:学习)。"}, {"meaning": "同本义。", "cites": [{"t": "学,识也。", "b": "《广雅》"}, {"t": "好学近乎知。", "b": "《礼记·中庸》"}, {"t": "念终始典于学。", "b": "《礼记·文王世子》"}, {"t": "学,效也。近而愈明者学也。", "b": "《尚书大传》"}, {"t": "学者,学其所不能学也。", "b": "《庄子·庚桑楚》"}, {"t": "远寻师学。", "b": "《后汉书·列女传》"}, {"t": "学而时习之。", "b": "《论语》"}, {"t": "学即继以问也。", "b": "清·刘开《问说》"}], "words": [{"w": "学书", "t": "认真读书"}, {"w": "学学乖", "t": "经世面,学聪明"}, {"w": "学理论;学技术;好学;苦学;教学相长;学文", "t": "学习人文学科或社会科学;学习文化知识"}, {"w": "学古", "t": "学习研究古代典籍。"}]}, {"meaning": "模仿。", "cites": [{"t": "[巧姐儿]笑嘻嘻走到凤姐身边学舌。", "b": "《红楼梦》。又如:学嘴(学舌);调嘴学舌;学他爸爸走路的样子;学不上来"}]}, {"meaning": "讲述,说。", "cites": [{"t": "一五一十向着珍哥、晁大舍学个不了。", "b": "《醒世姻缘传》"}, {"t": "见说万山潭,渔童尽能学。", "b": "唐·陆龟蒙《鱼具》"}], "words": [{"w": "学舌", "t": "说闲话;搬弄是非。"}]}, {"meaning": "讲学。", "cites": [{"t": "学,教也。", "b": "《广雅》"}, {"t": "叔仲皮学子柳。", "b": "《礼记》"}, {"t": "凡学世子及学士。", "b": "《礼记·文王世子》"}, {"t": "哀王者,帝之少弟,与太子游学相长大。", "b": "《资治通鉴》"}]}, {"meaning": "学校 。又曾称学庐、学教、学馆、学堂、学宫、学院、学屋、学园。", "cites": [{"t": "学,官也。", "b": "《广雅·释室》"}, {"t": "君子学以致其道。", "b": "《论语》"}, {"t": "学则三代共之。", "b": "《孟子》"}, {"t": "万用入学。", "b": "《夏小正》"}, {"t": "小学在公宫南之左,大学在郊。", "b": "《礼记·王制》"}, {"t": "国子先生晨入太学。", "b": "韩愈《进学解》"}], "words": [{"w": "学俸", "t": "教师的薪水"}, {"w": "学宪", "t": "学台"}, {"w": "学台", "t": "学政"}, {"w": "学里", "t": "明清时设立的管理各级地方儒生的机构。"}]}, {"meaning": "学问。", "cites": [{"t": "天子积学。", "b": "《后汉书·列女传》"}, {"t": "学有未达。", "b": "清·刘开《问说》"}, {"t": "是芋视乃学。", "b": "清·周容《芋老人传》"}, {"t": "生平为学。", "b": "清·张廷玉《明史》"}, {"t": "人之为学有难易乎?", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "学耻全牛", "t": "惭愧学问未到炉火纯青的地步"}, {"w": "学行", "t": "学问与品行"}, {"w": "才学", "t": "才能与学问"}, {"w": "绝学", "t": "失传的学问"}, {"w": "家学", "t": "祖传学问。"}]}, {"meaning": "学科;某一门类系统的知识。", "cites": [{"t": "今日覩卿词学。", "b": "《剧谈录·宣宗夜召翰林学士》"}], "words": [{"w": "文学;哲学;地理学;化学;问学于师", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1274wx','宝','1','bǎo','宀','8','','[{"pinyin": "bǎo", "defs": [{"meaning": "(形声。甲骨文字形,象房子里有贝和玉,表示家里藏有珍宝,会意。在西周金文里,又加上一个声符“缶”(古音与“宝”同)。本义:珍宝)。"}, {"meaning": "同本义。", "cites": [{"t": "宝,珍也。", "b": "《说文》"}, {"t": "稼穑维宝。", "b": "《诗·大雅·桑柔》"}, {"t": "以作尔宝。", "b": "《诗·大雅·崧高》"}, {"t": "宝玉者,封圭也。", "b": "《谷梁传·定公八年》"}, {"t": "以其宝来奔。", "b": "《国语·鲁语》。注:“玉也。”"}, {"t": "怀其宝。", "b": "《论语》"}, {"t": "和氏壁天下人所共传宝也。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "戴朱缨宝饰之帽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "珠宝;宝函", "t": "宝匣"}, {"w": "珍宝", "t": "珠玉宝石等"}, {"w": "宝肆", "t": "出售珍宝的店铺"}, {"w": "宝冕", "t": "宝冠。用宝石装饰的帽子"}, {"w": "宝钏", "t": "以金玉等制作的手镯"}, {"w": "宝钗", "t": "首饰名。用金银珠宝制作的双股簪子。"}]}, {"meaning": "珍贵的东西。", "cites": [{"t": "轻敌几丧吾宝。", "b": "《老子》。注:“身也。”"}, {"t": "啬其大宝。", "b": "《吕氏春秋·先已》。注:“身也。”"}, {"t": "正得秋而万宝成。", "b": "《庄子·庚桑楚》"}, {"t": "不爱珍奇重宝肥饶之地。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "献宝;财宝;传家宝;文房四宝", "t": ""}]}, {"meaning": "印信符玺。", "cites": [{"t": "又有“万几宸翰之宝”。", "b": "《红楼梦》"}], "words": [{"w": "宝札", "t": "玺书。古代以印章封记的文书;私人书信的敬辞"}, {"w": "宝符", "t": "朝廷用作信物的符节。"}]}, {"meaning": "一种赌具。方形,用牛角或硬木做成,上有指示方向的记号,参加赌博的人猜测宝上所指的方向下注。", "cites": [{"t": "开宝,你们有胆子没有?", "b": "老舍《骆驼祥子》"}]}, {"meaning": "珍爱,珍视。", "cites": [{"t": "吾有三宝,持而宝之。", "b": "《韩非子·解老》"}], "words": [{"w": "宝身", "t": "珍惜身躯"}, {"w": "宝重", "t": "珍惜重视"}, {"w": "宝惜", "t": "珍惜。"}]}, {"meaning": "珍贵的,宝贵的。", "cites": [{"t": "夫物不产于秦,可宝者多。", "b": "李斯《谏逐客书》"}], "words": [{"w": "宝刀", "t": "珍贵的战刀"}, {"w": "宝玉", "t": "珍贵的玉"}, {"w": "宝书", "t": "宝籍。珍贵的书籍。"}]}, {"meaning": "敬词。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1275wx','宗','1','zōng','宀','8','','[{"pinyin": "zōng", "defs": [{"meaning": "(会意。从宀示。示,神祇,宀,房屋。在室内对祖先进行祭祀。本义:宗庙,祖庙)。"}, {"meaning": "同本义。", "cites": [{"t": "宗,尊祖庙也。", "b": "《说文》"}, {"t": "汝作秩宗。", "b": "《虞书》。传:“主郊庙之官。”"}, {"t": "凡师甸用牲于社宗。", "b": "《周礼·肆师》"}, {"t": "承我宗事。", "b": "《仪礼·士昏礼》"}, {"t": "既燕于宗。", "b": "《诗·大雅·凫鹥》"}, {"t": "寡君闻君有不令之臣为君忧,无宁以为宗羞?", "b": "《左传·昭公二十二年》"}, {"t": "故筑为宫室,设为宗祧。", "b": "《孔子家语》"}], "words": [{"w": "宗守", "t": "宗庙所在"}, {"w": "宗邑", "t": "宗庙所在的城邑"}, {"w": "宗稷", "t": "宗庙社稷"}, {"w": "宗仪", "t": "有关宗庙的典章礼仪"}, {"w": "宗彝", "t": "宗庙祭祀所用的酒器"}, {"w": "宗器", "t": "宗庙祭器。"}]}, {"meaning": "祖先(常指祖父辈以上的)。", "cites": [{"t": "若不获命,而使嗣宗职。", "b": "《左传·成公三年》。注:“嗣其祖宗之职位。”"}, {"t": "故先祖基之,子孙成之。", "b": "《盐铁论·结和》"}], "words": [{"w": "列祖列宗;宗公", "t": "先公"}, {"w": "宗祀", "t": "对祖宗的祭祀"}, {"w": "宗绪", "t": "祖先的绪业"}, {"w": "宗职", "t": "祖宗世袭的职位"}, {"w": "宗灵", "t": "祖宗灵位。"}]}, {"meaning": "宗族;同族。", "cites": [{"t": "其宗灭于绛。", "b": "《国语·晋语》"}, {"t": "衰宗多弟侄,若个赏池台?", "b": "王绩《在京思故园见乡人问》"}], "words": [{"w": "宗英", "t": "宗族中杰出的人才"}, {"w": "宗缘", "t": "宗族因缘"}, {"w": "宗党", "t": "宗族党羽"}, {"w": "宗女", "t": "同宗的女儿"}, {"w": "宗支", "t": "同宗族的、支派"}, {"w": "宗氏", "t": "同族,宗族"}, {"w": "宗表", "t": "同族远房兄弟互称宗表。"}]}, {"meaning": "宗派;派别。", "cites": [{"t": "一钵事南宗,僧仪称病客。", "b": "许浑《冬日宣城开元寺赠元孚上人诗》"}], "words": [{"w": "宗门", "t": "佛教名宗的通称"}, {"w": "禅宗;正宗;宗风", "t": "指佛教各宗系特有的风格、传统,多用于禅宗。"}]}, {"meaning": "宗子,即嫡长子。", "cites": [{"t": "以妾代妻,以孽代宗。", "b": "《诗·小雅》"}], "words": [{"w": "宗潢", "t": "皇族的子孙"}, {"w": "宗主", "t": "宗子。一姓的继承人。"}]}, {"meaning": "即品系 。一个种中具有明显不同的形态和生理特性的变种,如异宗配合的霉菌有两个宗:(十)宗和(一)宗,前者以其较强壮的生长势而区别于相应的后者。"}, {"meaning": "被传达、表示或暗示的意思;主旨。", "cites": [{"t": "以天为法,以德为行,以道为宗。", "b": "《吕氏春秋》"}]}, {"meaning": "尊祭之神。", "cites": [{"t": "自从献宝朝河宗,无复射蛟江水中。", "b": "杜甫《韦讽录事宅观曹将军画马图》"}]}, {"meaning": "帝王的庙号。从汉代起,始帝称为太祖、高祖或世祖,以后的嗣君称为太宗、世宗等。", "cites": [{"t": "玄宗回马杨妃死,云雨难忘日月新。", "b": "郑畋《马嵬坡》"}, {"t": "盖闻古者祖有功而宗有德。", "b": "《史记·孝文帝本纪》"}, {"t": "天下有王,分地建国设祖宗。", "b": "《孔子家语·庙制解》"}]}, {"meaning": "诸侯夏天朝见天子之礼。", "cites": [{"t": "春见曰朝,夏见曰宗。", "b": "《周礼》"}]}, {"meaning": "尊崇。", "cites": [{"t": "食之饮之,君之宗之。", "b": "《诗·大雅·公刘》"}, {"t": "诸葛大名垂宇宙,宗臣遗像肃清高。", "b": "杜甫《咏怀古迹》"}]}, {"meaning": "尊敬。", "cites": [{"t": "宗尔父母之言。", "b": "《仪礼·士昏礼》"}], "words": [{"w": "宗附", "t": "宗仰依附"}, {"w": "宗臣", "t": "国人敬重之臣"}, {"w": "宗奉", "t": "宗仰敬奉"}, {"w": "宗长", "t": "尊崇长者"}, {"w": "宗敬", "t": "尊敬。"}]}, {"meaning": "取法。", "cites": [{"t": "室家遂宗。", "b": "《楚辞·招魂》"}, {"t": "词曲一道,但有前书堪读,并无成法可宗。", "b": "李渔《闲情偶寄》"}], "words": [{"w": "宗尚", "t": "推崇;效法。"}]}, {"meaning": "归往。", "cites": [{"t": "江汉朝宗于海。", "b": "《书·禹贡》"}], "words": [{"w": "宗归", "t": "宗尚,归依。"}]}, {"meaning": "归向。", "cites": [{"t": "武王已平殷乱,天下宗周。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1276wx','定','1','dìng','宀','8','','[{"pinyin": "dìng", "defs": [{"meaning": "(会意。从宀(mián),从正。“正”亦兼表字音。本义:安定;安稳)。"}, {"meaning": "同本义,与“乱”或“动”相对。", "cites": [{"t": "定,安也。", "b": "《说文》"}, {"t": "靡所定处。", "b": "《诗·大雅·桑柔》"}, {"t": "岂敢定居,一月三捷。", "b": "《诗·小雅·采薇》"}, {"t": "昏定而晨省。", "b": "《礼记·曲礼》"}, {"t": "以待阴阳之所定。", "b": "《礼记·月令》"}, {"t": "天下属安定,何故反乎?", "b": "《史记·留侯世家》"}, {"t": "痛定思痛,痛何如哉!", "b": "宋·文天祥《指南录·后序》"}, {"t": "如其克谐,天下可定也。", "b": "《资治通鉴》"}], "words": [{"w": "定迭", "t": "定叠。安定,太平"}, {"w": "定害", "t": "定搅,定虐。扰乱,扰害"}, {"w": "定帖", "t": "稳定;安定"}, {"w": "定昏", "t": "请晚安。"}]}, {"meaning": "镇静;宁静。", "cites": [{"t": "磬罢僧初定,山空月又生。", "b": "李中《碧云集》"}], "words": [{"w": "心神不定;入定", "t": "佛教徒闭眼静坐,控制身心各种活动"}, {"w": "镇定", "t": "遇到紧急情况不慌乱。"}]}, {"meaning": "固定。", "cites": [{"t": "我戎未定。", "b": "《诗·小雅·采薇》"}, {"t": "岂可一切拘以定月哉。", "b": "宋·沈括《梦溪笔谈·采草药》"}, {"t": "山高风钜,雾气去来无定。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "定数", "t": "迷信者认为人生祸福都是命里注定,称为定数"}, {"w": "定止", "t": "固定的处所"}, {"w": "定式", "t": "固定的样式"}, {"w": "定所", "t": "固定的住所、居处。"}]}, {"meaning": "使安定。", "cites": [{"t": "以定王国。", "b": "《诗·小雅·六月》"}, {"t": "定身以行事。", "b": "《国语·晋语二》"}, {"t": "秦岁定。", "b": "《国语·晋语三》"}, {"t": "吾定而禄爵。", "b": "《国语·晋语九》"}, {"t": "先王之所以定天下也。", "b": "《吕氏春秋·孝行》"}], "words": [{"w": "定国", "t": "安定国家。"}]}, {"meaning": "平定。", "cites": [{"t": "行略定秦地。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "灭秦定天下者,皆将相诸君与籍之力也。", "b": ""}, {"t": "天下已定。", "b": "汉·贾谊《过秦论》"}, {"t": "王师北定中原日,家祭无忘告乃翁。", "b": "南宋·陆游《示儿》"}], "words": [{"w": "定乱", "t": "平定祸乱。"}]}, {"meaning": "奠定。", "cites": [{"t": "臣观自古帝受定鼎,皆欲传之万代。", "b": "魏征《十渐不克终疏》"}, {"t": "高祖以圣武定鼎。", "b": "颜延之《三月三日曲水诗序》"}], "words": [{"w": "定鼎", "t": "奠定国都;建立王朝"}, {"w": "定功", "t": "建立功业"}, {"w": "定业", "t": "奠定国家大业"}, {"w": "定霸", "t": "奠定霸业。"}]}, {"meaning": "决定。", "cites": [{"t": "始欲作“推”字,又欲作“敲”字,炼之未定。", "b": "宋·胡仔《苔溪渔隐丛话》"}, {"t": "凡如是十许字,始定为“绿”。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "定方针;定法", "t": "决定法则"}, {"w": "定见", "t": "作决定"}, {"w": "定谋", "t": "决定谋略。"}]}, {"meaning": "确定。", "cites": [{"t": "要之,死日然后是非乃定。", "b": "司马迁《报任安书》"}, {"t": "割地定制。", "b": "汉·贾谊《治安策》"}], "words": [{"w": "一言为定;约定俗成;定名;定分", "t": "确定名分"}, {"w": "定在", "t": "固定住处"}, {"w": "定归", "t": "确定,定准。"}]}, {"meaning": "规定。", "cites": [{"t": "以闰月定四时成岁。", "b": "《尚书》"}], "words": [{"w": "定科", "t": "明确规定的法令条例"}, {"w": "定令", "t": "制定法令"}, {"w": " 定法", "t": "制定法令、法规、办法等"}, {"w": "定例", "t": "制定条例"}, {"w": "定拟", "t": "起草制定。"}]}, {"meaning": "约定签定,缔结。", "cites": [{"t": "王当歃血而定从,次者吾君,次者遂。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "定婚", "t": "订立婚约。"}]}, {"meaning": "止;停止。", "cites": [{"t": "乱靡有定。", "b": "《诗·小雅·节南山》"}, {"t": "反而定三革。", "b": "《荀子·儒效》"}, {"t": "俄顷风定云墨色,秋天漠漠向昏黑。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "判定,断定。", "cites": [{"t": "若定是非以教吾子。", "b": "唐·柳宗元《答韦中立论师道书》"}]}, {"meaning": "一定。", "cites": [{"t": "定要感的六出冰花滚似绵。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "定不得", "t": "没准头;说不定。"}]}, {"meaning": "到底;究竟。", "cites": [{"t": "卿云“艾艾”,定是几“艾”。", "b": "《世说新语·言语》"}], "words": [{"w": "定归", "t": "确定,定准。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1277wx','宠','1','chǒng','宀','8','','[{"pinyin": "chǒng", "defs": [{"meaning": "(形声。从宀(mián),龙声。本义:尊崇)。"}, {"meaning": "同本义。", "cites": [{"t": "宠神其祖。", "b": "《国语·楚语》。注:“尊也。”"}, {"t": "宠,尊居也。", "b": "《说文》"}, {"t": "宠名皆弃。", "b": "《左传·襄公三十年》。谓族也。"}], "words": [{"w": "宠存", "t": "尊崇慰问"}, {"w": "宠重", "t": "尊崇重视"}, {"w": "崇厉", "t": "尊崇勉励。"}]}, {"meaning": "宠爱。", "cites": [{"t": "君以为忠,而甚宠之。", "b": "《左传·昭公十年》"}, {"t": "不宜爱而受宠。", "b": "《论衡·幸偶》"}, {"t": "少姜有宠而死。", "b": "《左传·昭公三年》"}, {"t": "宠辱若惊。", "b": "《老子》"}, {"t": "上官大夫与之同列,争宠而心害其能。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "一家人很宠他;宠冠一时", "t": "备受宠爱,冠绝一时"}, {"w": "宠拔", "t": "宠爱提拔。"}]}, {"meaning": "荣耀。", "cites": [{"t": "承天宠也。", "b": "《易·师》。郑注:“光耀也。”"}, {"t": "其宠大矣。", "b": "《国语·楚语》。注:“荣也。”"}, {"t": "宠有孝悌长幼顺明之节。", "b": "《史记·赵世家》。正义:“贵也。”"}, {"t": "心旷神怡,宠辱偕忘。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "宠辱", "t": "荣耀与耻辱"}, {"w": "宠借", "t": "给予荣宠和奖励。"}]}, {"meaning": "受宠爱的人。", "cites": [{"t": "齐侯好内,多内宠。", "b": "《左传·僖公十七年》"}], "words": [{"w": "内宠;爱宠", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1278wx','宜','1','yí','宀','8','','[{"pinyin": "yí", "defs": [{"meaning": "(会意。从门之下一之上。甲骨文字形。象屋里俎上有肉的形状。本义:合适;适宜) 同本义。", "cites": [{"t": "宜,所安也。", "b": "《说文》"}, {"t": "宜,事也。", "b": "《尔雅》"}, {"t": "宜得其所也。", "b": "《苍颉篇》"}, {"t": "君子宜之。", "b": "《诗·小雅·裳裳者华》"}, {"t": "宜其室家。", "b": "《诗·周南·桃夭》"}, {"t": "世易时移,变法宜矣。(宜矣,是适宜的了,是应该的了。)", "b": "《吕氏春秋·察今》"}], "words": [{"w": "宜子", "t": "女子富有生育能力"}, {"w": "宜民", "t": "使民众安辑"}, {"w": "宜时", "t": "适时"}, {"w": "宜春", "t": "适宜于春天。"}]}, {"meaning": "煮熟可吃的肉。", "cites": [{"t": "弋言加之,与子宜之。", "b": "《诗·郑风》"}]}, {"meaning": "祭名。祭祀土地之神。", "cites": [{"t": "起大事,动大众,必先有事乎社而后出,谓之宜。", "b": "《尔雅》"}]}, {"meaning": "适宜的事。"}, {"meaning": "法度,标准。", "cites": [{"t": "宜鉴于殷,骏命不易。", "b": "《诗·大雅·文王》"}, {"t": "万物之生各得其宜也。", "b": "《诗·小雅·由仪序》"}]}, {"meaning": "(yì)。合理的道理、行为。", "cites": [{"t": "将施于宜。", "b": "《国语·晋语四》"}, {"t": "案主当宜,行其正理。", "b": "《管子·明法》。俞樾云:“宜乃谊之省。”"}, {"t": "宜无嫌于往初。", "b": "张衡《东京赋》"}]}, {"meaning": "应当(多用于否定式)。", "cites": [{"t": "不宜有所过。(“宜”,应该;“过”拜访。)", "b": "《史记·魏公子列传》"}, {"t": "宜付有司论其刑赏。(应该交给主管的官,判定他们受罚或者受赏。有司:职有专司,就是专门管理某种事情的官。刑:罚。)", "b": "诸葛亮《出师表》"}, {"t": "宜乎众人矣。(当然人很多了。宜:应当,这里和“乎”字连用,有“当然”的意思。乎:用在形容词、动词、副词的后面,表示事物或动作的状态,同“然”。众矣:人很多了。)", "b": "宋·周敦颐《爱莲说》"}, {"t": "国亦宜矣。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "宜蠲", "t": "应该减免"}, {"w": "事不宜迟;不宜操之过急;宜速归;宜然", "t": "应该这样"}, {"w": "宜当", "t": "情理上必须如此。"}]}, {"meaning": "当然。", "cites": [{"t": "宜君王之欲杀女而立职也。", "b": "《左传》"}]}, {"meaning": "大概。", "cites": [{"t": "今阴阳不调,宜更历之过也。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1279wx','审','1','shěn','宀','8','','[{"pinyin": "shěn", "defs": [{"meaning": "(会意。从宀番。宀房屋。番,兽足。屋里有兽足印,能仔细分辨。简体字从宀申声。本义:详究;考察)。"}, {"meaning": "同本义。", "cites": [{"t": "审,谓详观其道也。", "b": "《荀子·非相》"}, {"t": "闻而审,则为福矣。", "b": "《吕氏春秋·察传》"}, {"t": "故审堂下之阴,而知日月之行,阴阳之变。", "b": "《吕氏春秋·察今》"}, {"t": "直以不能内审诸己,外受流言,沉迷猖獗,以至于此。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "审时", "t": "详察时令"}, {"w": "审物", "t": "详察物情"}, {"w": "审形", "t": "详察实情"}, {"w": "审决", "t": "审察决定"}, {"w": "审机而行", "t": "详细、周密地进行分析研究,把握好时机再行动"}, {"w": "审别", "t": "审察辨别"}, {"w": "审势", "t": "审察形势。"}]}, {"meaning": "知道,知悉。", "cites": [{"t": "审,知也。", "b": "《类篇》"}, {"t": "审矣,何足怪乎?", "b": "司马迁《报任安书》"}, {"t": "君子审礼。", "b": "《史记·礼书》"}, {"t": "陛下连降三诏,召臣回朝,未审圣意为何?", "b": "《三国演义》"}]}, {"meaning": "又。", "cites": [{"t": "今投使君,共图大事,未审尊意如何?", "b": ""}, {"t": "倚南窗以寄傲,审容膝之易安。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "审悉", "t": "详细了解。"}]}, {"meaning": "审核,审查,检查核对。", "cites": [{"t": "为人主计者,莫如先审取舍。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "审考", "t": "审查"}, {"w": "审合", "t": "审查验证"}, {"w": "审决", "t": "审查决定"}, {"w": "审覆", "t": "审查;审察"}, {"w": "审释", "t": "审查释放"}, {"w": "审端", "t": "检查修正"}, {"w": "审分", "t": "审定名分、职分"}, {"w": "审律", "t": "审定乐律"}, {"w": "审音", "t": "审定字的读音。"}]}, {"meaning": "审讯;审判。", "cites": [{"t": "余经秋审,皆减等发配。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "审断", "t": "审判裁决"}, {"w": "审究", "t": "审问查究"}, {"w": "审拟", "t": "审问拟罪"}, {"w": "审鞫", "t": "审讯"}, {"w": "审录", "t": "审讯"}, {"w": "审语", "t": "审判结论"}, {"w": "审质", "t": "审问。"}]}, {"meaning": "询问,打听清楚。", "cites": [{"t": "十一娘亦审里居。", "b": "《聊斋志异》"}]}, {"meaning": "真实;确实。", "cites": [{"t": "先生在兵间,审知故扬州阁部史公果死耶,抑未死耶?", "b": "清·全祖望《梅花岭记》"}]}, {"meaning": "详尽,仔细。", "cites": [{"t": "等于己者,问焉以资切磋,所谓交相问难,审问而明辨之也。", "b": "清·刘开《问说》"}], "words": [{"w": "审观", "t": "仔细观察"}, {"w": "审图", "t": "周密谋划;仔细考虑"}, {"w": "审画", "t": "填重筹划"}, {"w": "审度", "t": "详细考量"}, {"w": "审顾", "t": "仔细察看"}, {"w": "审虑", "t": "仔细考虑"}, {"w": "审详", "t": "仔细审察"}, {"w": "审酌", "t": "仔细斟酌"}, {"w": "审注", "t": "仔细观察;细看"}, {"w": "审求", "t": "仔细探求"}, {"w": "审谋", "t": "周密谋划"}, {"w": "审省", "t": "详细省察"}, {"w": "审稽", "t": "详细考查"}, {"w": "审说", "t": "详细解说"}, {"w": "审辨", "t": "审慎辨别"}, {"w": "审当", "t": "周密而确当。"}]}, {"meaning": "慎重,小心谨慎。", "cites": [{"t": "言审莫过圣人。", "b": "王充《论衡》"}], "words": [{"w": "审练", "t": "审慎精细。"}]}, {"meaning": "确切。", "cites": [{"t": "称言命者,有命审矣。", "b": "王充《论衡》"}], "words": [{"w": "审期", "t": "确切的日期。"}]}, {"meaning": "正,不偏斜。", "cites": [{"t": "本不审,虽尧舜不能以治。", "b": "《吕氏春秋》"}]}, {"meaning": "固定;安定。", "cites": [{"t": "故水之守土也审,影之守人也审,物之守物也审。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1280wx','宙','1','zhòu','宀','8','','[{"pinyin": "zhòu", "defs": [{"meaning": "(形声。从宀(mián),由声。“宀”,表示房屋。本义:栋梁)。"}, {"meaning": "同本义。", "cites": [{"t": "宙,舟舆所极覆也。", "b": "《说文》。按,舟舆上覆如屋极者,或曰覆也,舟舆所极也。"}, {"t": "而燕雀佼之,以为不能与之争于宇宙之间。", "b": "刘安《淮南子·览冥》。高诱注:“宇,屋檐也。宙,栋梁也。”"}]}, {"meaning": "古往今来的时间;时间的总称。", "cites": [{"t": "往古来今谓之宙,四方上下谓之宇。", "b": "刘安《淮南子·齐俗》"}, {"t": "有实而无乎处者宇也,有长而无本剽者宙也。", "b": "《庄子·庚桑楚》。注:“宙者,有古今之长。”"}], "words": [{"w": "宙始", "t": "远古"}, {"w": "宙合", "t": "囊括上下古今之道。"}]}, {"meaning": "天空。", "cites": [{"t": "功烛上宙,德耀中天。", "b": "《南齐书》"}, {"t": "霜凝碧宙,水莹丹霄。", "b": "王勃《七夕赋》"}], "words": [{"w": "宙外", "t": "天外"}, {"w": "宙合", "t": "世间,天下。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1281wx','官','1','guān','宀','8','','[{"pinyin": "guān", "defs": [{"meaning": "(会意。甲骨文字形,从“宀”(mián), 以冖覆众,则有治众的意思。本义:官吏,官员)。"}, {"meaning": "同本义。", "cites": [{"t": "官,吏事君也。", "b": "《说文》"}, {"t": "有虞氏官五十,夏后氏官百,殷二百,周三百。", "b": "《礼记·明堂位》"}, {"t": "任官然后爵之。", "b": "《礼记·王制》"}, {"t": "在官言官。", "b": "《礼记·曲礼》"}, {"t": "官师一庙。", "b": "《礼记·祭法》。注:“官师:中士、下士也。”"}, {"t": "举不失选,官不易方。", "b": "《左传·襄公九年》"}, {"t": "公一女,嫁为畿辅某官某妻。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "此物故非西产,有华阴令欲媚上官,以一头进。", "b": "《聊斋志异·促织》"}], "words": [{"w": "文官;武官;京官;地方官;清官;贪官;军官;教官", "t": ""}]}, {"meaning": "官府(政府机关)。", "cites": [{"t": "官,官舍曰官。", "b": "《字汇》"}, {"t": "官,谓朝廷治事之处也。", "b": "《礼记·王藻》注"}, {"t": "贼二人得我,我幸皆之矣。愿以闻于官。", "b": "唐·柳宗元《童区寄传》"}, {"t": "上于盆而养之,蟹白栗黄,备极护爱,留待限期,以塞官责。", "b": "《聊斋志异·促织》"}, {"t": "有华阴令欲媚上官。", "b": ""}], "words": [{"w": "官局", "t": "官署。政府所设的机构"}, {"w": "官寺", "t": "官署、衙门的旧称"}, {"w": "官项", "t": "官府的钱项"}, {"w": "官休", "t": "纠纷经官府裁定了结。"}]}, {"meaning": "房舍,馆舍。", "cites": [{"t": "官乃馆之古文,闲官即闲馆,谓馆舍之空虚者。", "b": "俞樾《诸子平议》"}, {"t": "夫子之墙数仞,不得其门而入,不见宗庙之美,百官之富。", "b": "《论语》"}]}, {"meaning": "器官。", "cites": [{"t": "方今之时,臣以神遇而不以目视,官知正而神欲行。", "b": "《庄子·养生主》"}], "words": [{"w": "五官;感官", "t": ""}]}, {"meaning": "官职,职位。", "cites": [{"t": "衡不慕当世,所居之官辄积年不徙。", "b": "《后汉书·张衡传》"}, {"t": "位卑则足羞,官盛而近谀。", "b": "唐·韩愈《师说》"}, {"t": "台臣惭,追受其牒为复守官而黜臧使者。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "官秩", "t": "官阶与俸禄"}, {"w": "官守", "t": "官位职守,官员职责"}, {"w": "家父辞官回到省城来", "t": ""}]}, {"meaning": "古时用以称天子。", "cites": [{"t": "官家难称,吾欲行冒顿之事,卿从我乎?", "b": "《晋书·石季龙载记上》《资治通鉴》晋成帝咸廉三年译注:“称天子为官家,始见于此。”"}], "words": [{"w": "官里", "t": "皇帝"}, {"w": "官窑", "t": "专为皇家服务的瓷窑"}, {"w": "官院", "t": "王子所居的院子。"}]}, {"meaning": "公;公有。与“私”相对。", "cites": [{"t": "何须把官烛,似恼鬓毛苍。", "b": "唐·杜甫《台上》"}], "words": [{"w": "官厕所;官大道;官中的", "t": "公共的,公家的"}, {"w": "官中", "t": "大家庭中共有的银钱。"}]}, {"meaning": "当官,作官。", "cites": [{"t": "论定然后官之。", "b": "《礼记·王制》"}, {"t": "故明君不官无功之臣。", "b": "曹操《论吏士行能论》"}, {"t": "阿品远官河南,亦无子女,九族无可继者。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "官兴", "t": "官瘾"}, {"w": "官声", "t": "做官的名声"}, {"w": "官照", "t": "官员任职的执照,也称部照"}, {"w": "官常", "t": "为官的职责。"}]}, {"meaning": "(guǎn)。管制,管理。", "cites": [{"t": "轨守其时,有官天财。", "b": "《管子·山国轨》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1282wx','空','1','kōng kǒng kòng','穴','8','','[{"pinyin": "kōng", "defs": [{"meaning": "空虚;内无所有。引申为空虚处,空档。", "cites": [{"t": "空,空虚。", "b": "《广韵》"}, {"t": "小东大东,杼柚其空。", "b": "《诗·小雅·大东》"}, {"t": "常有高猿长啸,属引凄异,空谷传响。", "b": "《水经注·江水》"}, {"t": "仓禀实而囹圄空。", "b": "《管子·五辅》"}, {"t": "夜静春山空。", "b": "唐·王维《鸟鸣涧》"}, {"t": "送将军登空堡上。", "b": "明·魏禧《大铁椎传》"}, {"t": "独卧空室之中。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "而或长烟一空。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "空衔", "t": "有官衔无实职或俸禄"}, {"w": "空脑子", "t": "心中无盘算,没有头脑之意"}, {"w": "空花阳焰", "t": "比喻不切实际的想法。空花:虚幻之花。阳焰:日光中浮动的烟尘。"}]}, {"meaning": "罄尽;空其所有。引申为没有。", "cites": [{"t": "而或长烟一空,皓月千里。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "空户", "t": "做空头生意的人"}, {"w": "空竭", "t": "罄尽"}, {"w": "空尽", "t": "竭尽;凋敝"}, {"w": "空臆", "t": "讲尽心里的话。"}]}, {"meaning": "广阔;空旷。", "cites": [{"t": "寥寥空宇中,所讲在玄虚。", "b": "左思《咏史》"}], "words": [{"w": "空江", "t": "浩瀚寂静的江面"}, {"w": "空落", "t": "偏僻;空旷"}, {"w": "空霄", "t": "天空;云霄"}, {"w": "空杳", "t": "空旷深远"}, {"w": "空场", "t": "空旷的场地"}, {"w": "空落落", "t": "空旷冷落貌。"}]}, {"meaning": "空洞而不实际;空泛;虚构。", "cites": [{"t": "以空言求璧。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "欲以如父如天之空名。", "b": "清·黄宗羲《原君》"}, {"t": "此非空言也。", "b": "《史记·货殖列传》"}], "words": [{"w": "空构", "t": "虚构;杜撰"}, {"w": "空语", "t": "虚构的话,只说不做的话"}, {"w": "空玄", "t": "幻想"}, {"w": "空门面", "t": "虚有其表"}, {"w": "空梦", "t": "幻梦"}, {"w": "空设", "t": "虚置"}, {"w": "空声", "t": "虚名。"}]}, {"meaning": "空间;天空。", "cites": [{"t": "皆若空游无所依。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "浊浪排空。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "乱石穿空。", "b": "宋·苏轼《念奴娇·赤璧怀古》"}, {"t": "复道行空。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "空青", "t": "指青色的天空"}, {"w": "空碧", "t": "指澄碧的天空"}, {"w": "空中结构", "t": "凭空虚构"}, {"w": "空壤", "t": "指天地"}, {"w": "空悬", "t": "悬在空中"}, {"w": "空天", "t": "辽阔的天宇。"}]}, {"meaning": "佛教语。"}, {"meaning": "道家谓虚静之性。", "cites": [{"t": "澹乎若深泉之静,泛乎若不系之舟。不以生故自宝兮,养空而浮。", "b": "《文选》。李善注引郑玄曰:“道家养空,虚若浮舟也。”"}]}, {"meaning": "徒然;白白地。", "cites": [{"t": "白云千载空悠悠。", "b": "唐·崔颢《黄鹤楼》"}, {"t": "空以身膏草野。", "b": "《汉书·李广苏建传》"}, {"t": "空余泪痕。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "空跑一趟;空忙;空亡", "t": "白死"}, {"w": "空劳", "t": "徒劳;白费。"}]}, {"meaning": "只;仅。", "cites": [{"t": "雪上空留马行处。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "此处空余黄鹤楼。", "b": "唐·崔颢《黄鹤楼》"}], "words": [{"w": "空饭", "t": "只吃饭,不吃菜。"}]}, {"meaning": "使空虚;使罄尽。", "cites": [{"t": "内空府库之藏,外乏执备之用。", "b": "《盐铁论·本议》"}, {"t": "乃出图书,空囊橐,徐徐焉实狼其中。", "b": "马中锡《中山狼传》"}]}]}, {"pinyin": "kǒng", "defs": [{"meaning": "(形声。从穴,工声。本义:孔,窟窿)。"}, {"meaning": "同本义", "cites": [{"t": "然骞凿空。", "b": "《汉书·张骞传》"}, {"t": "衣又穿空。", "b": "《汉书·鲍宣传》"}, {"t": "空以穴其城。", "b": "《汉书·李广利传》"}, {"t": "空,犹穿也。", "b": "《汉书·沟洫志》注"}, {"t": "司空主土。不言上,言空者,空尚主之,何况于实,以微见箸。", "b": "《白虎通·封公侯》"}, {"t": "空石之中有人焉。", "b": "《荀子·解蔽》。注:“石穴也。”"}, {"t": "空穴之中,足以适情。", "b": "《淮南子·原道》。注:“崖穴也。”"}, {"t": "舜穿井为匿空旁出。", "b": "《史记·五帝本纪》"}], "words": [{"w": "空石", "t": "山洞;岩洞"}, {"w": "空穴", "t": "岩洞"}, {"w": "空洞", "t": "孔穴;地道"}, {"w": "空窾", "t": "洞穴。"}]}, {"meaning": "口,嘴巴。", "cites": [{"t": "利出一空者,其国无敌;利出二空者,其兵半用;利出十空者,民不守。", "b": "《韩非子》"}]}]}, {"pinyin": "kòng", "defs": [{"meaning": "使之困穷。", "cites": [{"t": "不宜空我师。", "b": "《诗·小雅·节南山》"}, {"t": "饿其体肤,空乏其身。", "b": "《孟子》"}], "words": [{"w": "空乏", "t": "困穷;贫穷"}, {"w": "空竭", "t": "穷困;贫乏"}, {"w": "空匮", "t": "空乏;财用不足。"}]}, {"meaning": "腾让出来。", "cites": [{"t": "同时,船旁的坐板也空出坐位来了。", "b": "鲁迅《彷徨·离婚》"}], "words": [{"w": "他由于辞职从而把他在国会的席位空了出来", "t": ""}]}, {"meaning": "闲暇,闲功夫,没被占用的时间。", "cites": [{"t": "那里有个坐着的空儿。", "b": "《红楼梦》"}], "words": [{"w": "有空到我这里来;空当", "t": "空隙;空子"}, {"w": "空儿", "t": "闲功夫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1283wx','帘','1','lián','巾','8','','[{"pinyin": "lián", "defs": [{"meaning": "旧时酒家、茶馆作店招的旗帜,用布做成。", "cites": [{"t": "白鸟窥鱼网,青帘认酒家。", "b": "唐·郑谷《旅寓洛南村舍》"}]}, {"meaning": "(形声。从竹,廉声。本义:门帘)。"}, {"meaning": "帘子,遮蔽门窗的用具。", "cites": [{"t": "簾,堂簾也。", "b": "《说文》"}, {"t": "簾,户蔽也。", "b": "《声类》。"}, {"t": "严持箧书,置饰室簾南。", "b": "《汉书》"}, {"t": "草色入簾青。", "b": "唐·刘禹錫《陋室銘》"}, {"t": "入其舍,则密室垂簾。", "b": "《聊斋志异·促織》"}], "words": [{"w": "簾帷", "t": "遮蔽門窗的簾子、布幕"}, {"w": "簾籠", "t": "窗簾和窗牖"}, {"w": "簾旌", "t": "簾端所綴之布帛"}, {"w": "簾政", "t": "皇太後垂簾聽政,故名"}, {"w": "簾庑", "t": "指堂前廊檐垂簾之處。"}]}, {"meaning": "古代盛梳妆用品的器具,也用于嫁女时嫁妆的總稱。", "cites": [{"t": "箱簾六七十,绿碧青丝绳。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1284wx','宛','1','wǎn','宀','8','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从宀(mián),夗(yuàn)声。象屋里的草弯曲自相覆盖。本义:弯曲)。"}, {"meaning": "同本义。", "cites": [{"t": "宛,屈草自覆也。", "b": "《说文》"}, {"t": "宛宛黄龙。", "b": "《史记·司马相如传》"}, {"t": "是以欲谈者宛舌而固声。", "b": "《汉书·扬雄传下》"}], "words": [{"w": "宛妙", "t": "事物屈曲美妙"}, {"w": "宛虹", "t": "弯曲的虹"}, {"w": "宛曲", "t": "辗转;曲折"}, {"w": "宛委", "t": "弯曲;曲折"}, {"w": "宛宛", "t": "盘旋屈曲的样子;山川道路蜿蜒曲折"}, {"w": "宛燀", "t": "回旋盘曲。"}]}, {"meaning": "晃荡;摇动。", "cites": [{"t": "晴野霞飞绮,春郊柳宛丝。", "b": "白居易诗"}]}, {"meaning": "释散。", "cites": [{"t": "纷乎宛乎。", "b": "《庄子》。成玄英疏:“纷纶宛转,并释散之貌也。”"}]}, {"meaning": "委婉;婉转。", "cites": [{"t": "一面收拾礼物,径往东京,投宿省院诸官,令其于天子之前,善言启奏,别作宛转。", "b": "《水浒传》"}], "words": [{"w": "宛款", "t": "委婉诚恳"}, {"w": "宛曼", "t": "柔媚;婉转曼妙"}, {"w": "宛畅", "t": "婉转流畅"}, {"w": "宛笃", "t": "婉曲而诚挚"}, {"w": "宛态", "t": "含蓄曲折的情态"}, {"w": "宛折", "t": "婉转曲折。"}]}, {"meaning": "凹入;低洼。", "cites": [{"t": "子之汤兮,宛丘之上兮。", "b": "《诗·陈风·宛丘》。毛传:“四方高中央下曰宛丘。”"}]}, {"meaning": "隆起。", "cites": [{"t": "宛中宛丘。", "b": "《尔雅·小宛》。郭璞注:“宛,谓中央隆高。”"}]}, {"meaning": "顺利;顺遂。", "cites": [{"t": "天为粤宛,草木养长,五谷蕃实秀大。", "b": "《管子》"}]}, {"meaning": "小。", "cites": [{"t": "宛彼鸣鸠,翰飞戾天。", "b": "《诗·小雅·小宛》"}]}, {"meaning": "似乎,好像;仿佛。", "cites": [{"t": "宛然可遇。", "b": "清·全祖望《梅花岭记》"}, {"t": "宛然尚在。", "b": "《聊斋志异·促织》"}], "words": [{"w": "宛肖", "t": "逼真;极像"}, {"w": "宛类", "t": "很像。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1285wx','实','1','shí','宀','8','','[{"pinyin": "shí", "defs": [{"meaning": "(会意。从宀,从贯。宀,房屋。贯,货物,以货物充于屋下。本义:财物粮食充足,富有)。"}, {"meaning": "同本义。", "cites": [{"t": "實,富也。", "b": "《说文》"}, {"t": "实,满也,塞也。", "b": "《小尔雅》"}, {"t": "实,荣也。", "b": "《墨子经上》"}, {"t": "有者为实,故凡中质充满皆曰实。", "b": "《素问·调经论》"}, {"t": "而君之仓廪实,府库充。", "b": "《孟子·梁惠王下》"}, {"t": "管子曰:“仓廪实而知礼节。”", "b": "汉·贾谊《论积贮疏》"}, {"t": "公家虚而大臣实。", "b": "《韩非子·亡征》"}], "words": [{"w": "殷实;实核", "t": "种子"}, {"w": "实谷", "t": "子粒饱满的谷类作物。"}]}, {"meaning": "真实;诚实。", "cites": [{"t": "实,诚也。", "b": "《广雅》"}, {"t": "夫图画,非母之实身也。", "b": "《论衡·乱龙》"}, {"t": "虚则知实之情。", "b": "《韩非子·主道》"}, {"t": "今人又言心电感应有道,吾亦望其言是实。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "实充", "t": "老实"}, {"w": "实受", "t": "忠厚老实"}, {"w": "实业", "t": "实际业绩"}, {"w": "实迹", "t": "真实的证据,事实"}, {"w": "实拍", "t": "实在的"}, {"w": "实丕丕", "t": "实呸呸、实坯坯。都指实实在在"}, {"w": "实志", "t": "真实的心愿"}, {"w": "实理", "t": "真实的道理"}, {"w": "实音", "t": "确实的消息"}, {"w": "实户", "t": "实际户数"}, {"w": "实支", "t": "实际支出"}, {"w": "实年", "t": "实际年龄"}, {"w": "实务", "t": "实际事物"}, {"w": "实福", "t": "实际的幸福"}, {"w": "实祸", "t": "实际的祸害。"}]}, {"meaning": "广大。", "cites": [{"t": "节彼南山,有实其猗。", "b": "《诗·小雅·节南山》"}]}, {"meaning": "坚实;坚强。", "cites": [{"t": "兵之形,避实而击虚。", "b": "《孙子·虚实》"}], "words": [{"w": "实落", "t": "结实;实实在在"}, {"w": "实拍拍", "t": "形容硬、结实"}, {"w": "实秘秘", "t": "严严实实"}, {"w": "实癖癖", "t": "硬鼓鼓"}, {"w": "实坚", "t": "坚定。"}]}, {"meaning": "果实;种子。", "cites": [{"t": "草木之实。", "b": "《礼记·祭统》。注:“菱芡榛栗之属。”"}, {"t": "实函斯活。", "b": "《诗·周颂·载芟》。笺:“种子也。”"}, {"t": "复蒂下生蓬,蓬中结实,亭亭独立。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "用实者成实时采。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "结实", "t": ""}]}, {"meaning": "实际,事实。", "cites": [{"t": "今以实校之,彼所将中国人不过十五六万。", "b": "《资治通鉴》"}, {"t": "较秦之所得,与战胜而得者,其实百倍。", "b": "宋·苏洵《权书·六国论》"}], "words": [{"w": "实情", "t": ""}]}, {"meaning": "物资,器物。", "cites": [{"t": "在军无日不讨军事而申儆之。", "b": "《左传》"}]}, {"meaning": "结果,效果。", "cites": [{"t": "畏惧存想,同一实也。", "b": "王充《论衡》"}]}, {"meaning": "诚实的人。", "cites": [{"t": "此皆良实,志虑忠纯。", "b": "诸葛亮《出师表》"}]}, {"meaning": "真正地;确实;实在。", "cites": [{"t": "瞻望弗及,实劳我心。", "b": "《诗·邶风·燕燕》"}, {"t": "兰芝仰头答:理实如兄言。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "故自汝归后,虽为汝悲,实为予喜。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "实供", "t": "如实招供"}, {"w": "实属谣言;实有其事;实然", "t": "真实;实在"}, {"w": "实稔", "t": "确实成熟了。"}]}, {"meaning": "果然。", "cites": [{"t": "毕阳实送州犁于荆。", "b": "《国语》"}]}, {"meaning": "终于。", "cites": [{"t": "其实无不安者,功大故也。", "b": "《吕氏春秋》"}]}, {"meaning": "实际上。", "cites": [{"t": "或说处杀虎斩蛟,实冀三横唯余其一。", "b": "《世说新语·自新》"}, {"t": "传者因谓小孤庙有彭郎像,澎浪庙有小姑像,实不然也。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "充满;充实;填塞。", "cites": [{"t": "实其言,必长晋国。", "b": "《左传·宣公十二年》"}, {"t": "狗马实外厩。", "b": "《战国策·齐策四》"}, {"t": "将以实笾豆奉祭祀、供宾客乎?", "b": "明·刘基《卖柑者言》"}, {"t": "乃出图书,空囊橐,徐徐焉实狼其中。", "b": "马中锡《中山狼传》"}], "words": [{"w": "实牣", "t": "充满;充实"}, {"w": "实实窒窒", "t": "拥挤不堪的样子"}, {"w": "实心", "t": "充塞于心"}, {"w": "实窒胡同", "t": "死胡同"}, {"w": "实边", "t": "充实边疆"}, {"w": "实禀", "t": "充实粮仓。"}]}, {"meaning": "结果实;结子实。", "cites": [{"t": "苗而不秀者有矣夫,秀而不实者有矣夫。", "b": "《论语》"}]}, {"meaning": "使加强,充实。", "cites": [{"t": "徙民实边。", "b": "《汉书·晁错传》"}]}, {"meaning": "察实;核实。", "cites": [{"t": "阅实其罪。", "b": "《书·吕刑》"}]}, {"meaning": "即,就是。", "cites": [{"t": "我之先君,实汝伯兄。", "b": "明·方孝孺《祭从兄希声》"}]}, {"meaning": "据实陈报。", "cites": [{"t": "令国中凡有游产,皆使自实。", "b": "《三国志》引《魏略》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1286wx','试','1','shì','讠','8','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从言,式声。本义:用;任用)。"}, {"meaning": "同本义。", "cites": [{"t": "试,用也。", "b": "《说文》"}, {"t": "明试以功。", "b": "《虞书》"}, {"t": "今予将试以汝迁。", "b": "《书·盘庚》"}, {"t": "师干之试。", "b": "《诗·小雅·采芑》"}, {"t": "兵革不试。", "b": "《礼记·乐记》"}, {"t": "吾不试。", "b": "《论语》"}, {"t": "私人之子,百僚是试。", "b": "《诗·小雅·大东》"}, {"t": "兵革不试,五刑不用。", "b": "《礼记·乐记》"}], "words": [{"w": "试兵", "t": "用兵。"}]}, {"meaning": "尝试。", "cites": [{"t": "试,尝也。", "b": "《广雅》"}, {"t": "不可试也。", "b": "《易·无妄》"}, {"t": "臣请试之。", "b": "《战国策·秦策》"}, {"t": "我虽不敏,请尝试之。", "b": "《孟子·梁惠王上》"}, {"t": "日高人渴漫思茶,敲门试问野人家。", "b": "宋·苏轼《浣溪沙》"}], "words": [{"w": "试啼", "t": "试着啼哭"}, {"w": "试药郎中", "t": "方言。庸医诊病时以病试药"}, {"w": "试试缩缩", "t": "即畏畏缩缩,不敢大胆前进"}, {"w": "试水", "t": "尝试品尝茶水。"}]}, {"meaning": "初次使用。", "cites": [{"t": "思试之斗以觇之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "试酌", "t": "初饮。"}]}, {"meaning": "试验。", "cites": [{"t": "试用于今日,先帝称之曰能。", "b": "诸葛亮《出师表》"}, {"t": "又试之鸡,果如成言。", "b": "《聊斋志异·促织》"}], "words": [{"w": "试守", "t": "试任某一官职"}, {"w": "试儿", "t": "旧时试测小儿性情和志趣的习俗。也称“抓周”、“试周”"}, {"w": "试晬", "t": "周岁测试小孩"}, {"w": "试艺", "t": "试验才艺"}, {"w": "试年庚", "t": "古时风俗在除夕夜聚博,以胜负来作为来年运气的征兆。"}]}, {"meaning": "考查;考试。", "cites": [{"t": "老人延入坐,知从郡城就童子试归。", "b": "清·周容《芋老人传》"}, {"t": "及试吏呼名至史公,公瞿然注视。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "试验", "t": "考查;验证"}, {"w": "试判", "t": "考试"}, {"w": "试官", "t": "主持考试的官。"}]}, {"meaning": "试探;刺探。", "cites": [{"t": "白发不相负,青阳始试旬。", "b": "清·王夫之《元日折梅次定山韵》"}], "words": [{"w": "试风头", "t": "剌探情况"}, {"w": "试旬", "t": "探求;探寻。"}]}, {"meaning": "旧称臣杀君、子杀父母等行为。", "cites": [{"t": "受命之臣,专征云试。", "b": "《汉书》"}]}, {"meaning": "相当于“姑且”。", "cites": [{"t": "王试出兵以观之。", "b": "《史记·周本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1287wx','郎','1','láng','阝','8','','[{"pinyin": "láng", "defs": [{"meaning": "(形声。从邑,良声。从“邑”,表示与行政区域有关。本义:古邑名。在今山东金乡县境)。"}, {"meaning": "古地名。春秋鲁邑。", "cites": [{"t": "郎,鲁邑也。", "b": "《说文》。按,鲁有二郎。"}]}, {"meaning": "在今山东省鱼台县东北,是费伯的食邑。", "cites": [{"t": "费伯帅师城郎。", "b": "《左传·隐公元年》"}]}, {"meaning": "在今山东省曲阜县附近。", "cites": [{"t": "夏,城郎。", "b": "《左传·隐公九年》"}]}, {"meaning": "郎,古廊字。原指宫殿廷廊,置侍卫人员所在。官名。", "cites": [{"t": "郎官,谓三中郎将下之属官也。", "b": "《后汉书·桓帝纪》注"}]}, {"meaning": "旧时妇女对丈夫或情人的昵称。", "cites": [{"t": "郎骑竹马来,绕床弄青梅。", "b": "李白《长干行》"}], "words": [{"w": "郎伯", "t": "妇人称丈夫为郎、伯,并称郎伯。"}]}, {"meaning": "汉魏以后少年的美称。", "cites": [{"t": "瑜时年二十四,吴中皆呼为周郎。", "b": "《三国志》"}]}, {"meaning": "旧时对一般男子的尊称。", "cites": [{"t": "王家诸郎亦皆可嘉,闻来觅婿。", "b": "《世说新语·雅量》"}], "words": [{"w": "伴郎;郎不郎,秀不秀", "t": "指不成材"}, {"w": "郎子", "t": "对英俊少年的爱称"}, {"w": "郎秀", "t": "明初乡里间称呼男子因出身而异,大家豪族称秀;平凡家庭称郎。"}]}, {"meaning": "仆人称主人为郎。", "cites": [{"t": "为两郎僮。", "b": "唐·柳宗元《童区寄传》"}]}, {"meaning": "又。", "cites": [{"t": "孰若为一郎僮。", "b": ""}, {"t": "正副郎好事者。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "郎主", "t": "门生家奴称其主;对外族首领的称呼。"}]}, {"meaning": "室外有顶的过道。", "cites": [{"t": "今陛下累郎台,恐其不高也。", "b": "《汉书·东方朔传》"}, {"t": "盖闻虞舜之时,游于岩郎之上。", "b": "《汉书·董仲舒传》"}]}, {"meaning": "朝廷。", "cites": [{"t": "茤荛之言,可择郎庙。", "b": "三国·魏·钟繇《宣示帖》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1288wx','诗','1','shī','讠','8','','[{"pinyin": "shī", "defs": [{"meaning": "(形声。从言,寺声。本义:诗歌)。"}, {"meaning": "同本义。", "cites": [{"t": "诗言志,歌永言。", "b": "《书·舜典》"}, {"t": "诗,志也。", "b": "《说文》"}, {"t": "诗所以合意,歌所以咏诗也。", "b": "《国语·鲁语》"}, {"t": "教六师,曰风,曰赋,曰比,曰典,曰雅,曰颂。", "b": "《周礼·大师》。毛诗序,在心为志,发言为诗。"}, {"t": "临清流而赋诗。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "诗筒", "t": "装诗稿的竹筒"}, {"w": "诗瓢", "t": "放诗稿的瓢勺"}, {"w": "诗友", "t": "以诗词唱和的朋友"}, {"w": "诗虎", "t": "作成诗句的灯谜"}, {"w": "诗流", "t": "诗的流别系统"}, {"w": "诗案", "t": "因诗获罪的案件"}, {"w": "诗眼", "t": "诗句中最为工巧传神的一个字"}, {"w": "诗债", "t": "指向他人乞诗或索和未及酬答"}, {"w": "诗传", "t": "诗集"}, {"w": "诗狱", "t": "因诗篇的内容为言官所检举而引发的文字狱。"}]}, {"meaning": "指《诗经》。在古语中凡称“诗曰”、“诗云”都是指《诗经》。", "cites": [{"t": "诗三百,一言以蔽之,曰:思无邪。", "b": "《论语·为政》"}, {"t": "诗云:“他人有心,予忖度之。", "b": "《孟子·梁惠王上》"}, {"t": "坐大厦之下而诵《诗》《书》,无奔走之劳矣。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "诗什", "t": "《诗经》以十篇为一单位,编为一卷,因乃名为一什"}, {"w": "诗序", "t": "《诗经》的序"}, {"w": "诗教", "t": "《诗经》的教化功能"}, {"w": "诗传", "t": "《诗经》的注解。"}]}, {"meaning": "诵诗;作诗;赋诗歌颂。", "cites": [{"t": "能造者其必诗,敢往者无不赋。", "b": "杨衒之《洛阳伽蓝记》"}], "words": [{"w": "诗功", "t": "作诗的功力"}, {"w": "诗酒", "t": "做诗与饮酒"}, {"w": "诗道", "t": "作诗的规律、主张和方法"}, {"w": "诗牌", "t": "用以题诗的木板"}, {"w": "诗怀", "t": "做诗怀念。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1289wx','肩','1','jiān','月','8','','[{"pinyin": "jiān", "defs": [{"meaning": "(象形。从户,从肉。本义:肩膀)。"}, {"meaning": "同本义。", "cites": [{"t": "肩,髆也。从肉,象形。", "b": "《说文》"}, {"t": "北方有比肩之民焉。迭食而迭望。", "b": "《尔雅》"}, {"t": "肩臂臑。", "b": "《仪礼·少牢礼》"}, {"t": "肩之所倚。", "b": "《庄子·养生主》"}, {"t": "并肩手相接。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "肩巴", "t": "肩膀"}, {"w": "肩甲", "t": "即肩胛"}, {"w": "肩磨", "t": "肩膀耸动,浑身发抖"}, {"w": "肩排", "t": "并肩排列;并排。"}]}, {"meaning": "动物的腿根部。", "cites": [{"t": "项王曰:“赐之彘肩。”则与一生彘肩。樊哙覆其盾于地,加彘肩上,拔剑切而啗之。", "b": "《史记·项羽本纪》"}]}, {"meaning": "任,任用。", "cites": [{"t": "肩,胜也。", "b": "《尔雅》"}, {"t": "朕不肩好货。", "b": "《书·盘庚》。传:“任也。”"}, {"t": "永肩一心。", "b": "《书·盘庚下》。注:“长任一心以示。”"}]}, {"meaning": "用于比喻重量、负担。", "cites": [{"t": "卫老婆子仿佛卸了一肩重担似的嘘了一口气。", "b": "鲁迅《祝福》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1290wx','房','1','fáng','户','8','','[{"pinyin": "fáng", "defs": [{"meaning": "(形声。从户,方声。上古边室皆用单扇门(即“户”),庙门大门才用双扇门,故“房”从“户”。本义:正室左右的住室)。"}, {"meaning": "古代堂中间叫正室,两旁的叫房。", "cites": [{"t": "房,室在傍者也。", "b": "《说文》"}, {"t": "房,室旁夹室也。", "b": "《六书故》。段曰:“凡堂之内,中为正室,左右为房,所谓东房、西房也”。桂馥曰:“古者宫室之制,前堂后室。前堂之两头有夹室,后室之两旁有东西房。”"}, {"t": "记宰夫宴出自东房。", "b": "《仪礼·乡食礼》"}, {"t": "在东房。", "b": "《书·顾命》"}, {"t": "郤子登,妇人笑于房。", "b": "《左传·宣公十七年》"}], "words": [{"w": "厢房", "t": "正房前面两旁的房屋"}, {"w": "房植", "t": "房室四角的柱"}, {"w": "房奥", "t": "房室之深处。"}]}, {"meaning": "泛指房屋。", "cites": [{"t": "无门无房,四达之皇皇也。", "b": "《庄子·知北游》"}], "words": [{"w": "库房", "t": "储存财物的房屋"}, {"w": "住房;私房;房宇", "t": "屋宇,房子。"}]}, {"meaning": "房间。", "cites": [{"t": "店主王公迎接了,慌忙指派房头,堆放行旅。", "b": "《古今说》"}], "words": [{"w": "房卧", "t": "卧房;嫁妆"}, {"w": "房头", "t": "房间"}, {"w": "房户", "t": "房间门窗。"}]}, {"meaning": "官署及办公处所 。如:房科(旧时官衙里的下级办事人员);房省(宫室,官署)。又指明清乡、会试分房阅卷处所。亦指分房阅卷的同考官。如:房书(八股文的选集,所选的是进士的文章);房考(亦称“房官”。明清时乡、会试时分房阅卷的考官);房差(房考官的差使)。"}, {"meaning": "结构和作用像房子的东西。", "cites": [{"t": "蜂房不容鹄卵。", "b": "《淮南子·泛论》"}, {"t": "露冷莲房坠粉红。", "b": "杜甫《秋兴》"}], "words": [{"w": "心房;蛎房", "t": ""}]}, {"meaning": "房族及其宗支的单位。", "cites": [{"t": "我有个房分兄弟,行三,人都叫他潘三爷。", "b": "《儒林外史》"}]}, {"meaning": "妻室。", "cites": [{"t": "本房的丫環忙捧上茶子。", "b": "《红楼梦》"}], "words": [{"w": "正房;偏房;填房;房内", "t": "妻子"}, {"w": "房老", "t": "僧之妻。"}]}, {"meaning": "俎,祭器。", "cites": [{"t": "神来饷,房俎陈。", "b": "《清史稿》"}]}, {"meaning": "用于植物的果实等物,相当于“串”、“个”。", "cites": [{"t": "今有马乳蒲萄,一房长二尺余。", "b": "唐·封演《封氏闻见记》"}]}, {"meaning": "用于妻妾,相当于“个”。", "cites": [{"t": "只我家相公要讨一房侧室。", "b": "《古今小说》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1291wx','诚','1','chéng','讠','8','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从言,成声。本义:诚实,真诚)。"}, {"meaning": "同本义。", "cites": [{"t": "诚,信也。", "b": "《说文》"}, {"t": "币必诚。", "b": "《礼记·郊特牲》"}, {"t": "诚者自成也。", "b": "《礼记·中庸》"}, {"t": "帝感其诚,命夸娥氏二子负二山,一厝朔东,一厝雍南。", "b": "《列子·汤问》"}, {"t": "行之发于至诚。", "b": "《汉书·赵广汉传》"}, {"t": "乃能衔哀致诚。", "b": "韩愈《祭十二郎文》"}], "words": [{"w": "诚款", "t": "真诚恳切"}, {"w": "诚敬", "t": "真诚,敬重"}, {"w": "诚虔", "t": "虔诚,恭敬而有诚意。"}]}, {"meaning": "真实。", "cites": [{"t": "善人为邦百年,亦可以胜残去杀矣。诚哉是言也!", "b": "《论语·子路》"}, {"t": "此谓诚于中,形于外。", "b": "《礼记·大学》"}, {"t": "巧诈不如拙诚。", "b": "《韩非子·说林上》"}], "words": [{"w": "诚理", "t": "真理"}, {"w": "诚谛", "t": "真实而详审。"}]}, {"meaning": "确实,的确。", "cites": [{"t": "诚既勇兮又以武。", "b": "《楚辞·九歌·国殇》"}, {"t": "臣诚知不如徐公美。", "b": "《战国策·齐策》"}, {"t": "所谓无者诚难测,而神者诚难明矣。", "b": "韩愈《祭十二郎文》"}, {"t": "此为宰相听事诚隘,为太祝、奉礼听事已宽矣。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "诚不能免;诚恐", "t": "只怕,恐怕。"}]}, {"meaning": "果真;如果。", "cites": [{"t": "楚诚能绝齐,秦愿献商于之地六百里。", "b": "《史记·屈原贾生列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1292wx','衬','1','chèn','衤','8','','[{"pinyin": "chèn", "defs": [{"meaning": "(形声。从衣,親声。本义:外衣内的单衫)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1293wx','衫','1','shān','衤','8','','[{"pinyin": "shān", "defs": [{"meaning": "古代指无袖头的开衩上衣。", "cites": [{"t": "朝成绣夹裙,晚成单罗衫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "衫子", "t": "指古代妇女穿的一种袖子宽大的上衣;上衣的通称"}, {"w": "衫帽", "t": "凉衫便帽。是宋代士大夫闲居时的装束"}, {"w": "衫裙", "t": "短衫和裙子,泛指衣服"}, {"w": "衫褃", "t": "衣服的腰身"}, {"w": "衫煖", "t": "即“衫子”"}, {"w": "衫傒", "t": "衣袖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1294wx','视','1','shì','见','8','','[{"pinyin": "shì", "defs": [{"meaning": "(会意兼形声。从见示,示亦声。见,看见。示,表现。本义:看)。"}, {"meaning": "同本义。", "cites": [{"t": "视,瞻也。", "b": "《说文》"}, {"t": "天视自我民视,天听自我民听。", "b": "《书·泰誓中》"}, {"t": "目不能徧视,手不能徧操。", "b": "《墨子·辞过》"}, {"t": "子兴视夜。", "b": "《诗·郑风·子曰鸡鸣》"}, {"t": "视而不见,听而不闻。", "b": "《礼记·大学》"}, {"t": "熟视之。", "b": "《战国策·齐策》"}, {"t": "然往来视之,觉无异能者。", "b": "柳宗元《三戒》"}, {"t": "撤屏视之,一人、一桌、一椅、一扇、一抚尺而已。", "b": "《虞初新志·秋声诗自序》"}, {"t": "穆公使视客馆,则束载、厉兵、秣马矣。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "视探", "t": "看望,探望"}, {"w": "视瞻", "t": "顾盼的目光"}, {"w": "视日", "t": "观日影而察早晚时刻;注视太阳"}, {"w": "视远步高", "t": "高视阔步"}, {"w": "视习", "t": "见习。"}]}, {"meaning": "考察,察看,审察。", "cites": [{"t": "视其所以。", "b": "《论语·为政》"}, {"t": "下视其辙,登轼而望之。", "b": "《左传·庄公十年》"}, {"t": "窥镜而自视,又弗如远甚。", "b": "《战国策·齐策》"}], "words": [{"w": "视师", "t": "视察军队"}, {"w": "视草", "t": "检视天子所写文词诏令的草稿"}, {"w": "视药", "t": "查看汤药"}, {"w": "视荫", "t": "观察日影。"}]}, {"meaning": "治理,处理。", "cites": [{"t": "崔子称疾不视事。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "视朝", "t": "天子朝临治理政事"}, {"w": "视篆", "t": "古代官印皆用篆文,故官吏上任治事称“视篆”。"}]}, {"meaning": "看待。", "cites": [{"t": "弃其妇,致郁郁死,是芋视乃妇也。", "b": "清·周容《芋老人传》"}, {"t": "子孙视之不甚惜,举以予人,如弃草芥。", "b": "宋·苏洵《六国论》"}, {"t": "然言其户,则视三十年以前增五倍焉。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "视遇", "t": "看待,照顾"}, {"w": "视同膜外", "t": "视若无睹;漠不关心"}, {"w": "视民如伤", "t": "将百姓的疾苦看作自己的伤痛"}, {"w": "视为同路人;视伟", "t": "看重。"}]}, {"meaning": "向…表示。", "cites": [{"t": "指视我。", "b": "《汉书·周勃传》"}, {"t": "视民不奢。", "b": "《汉书·晁错传》。师古曰:“视读曰示。”"}, {"t": "视民不恌。", "b": "《诗·小雅·鹿鸣》"}, {"t": "亦视项羽无东意。", "b": "《汉书·高帝纪》"}], "words": [{"w": "视化", "t": "显示教化。视,同“示”。"}]}, {"meaning": "比照。", "cites": [{"t": "环顾国内,贼氛方炽,杌陧之象,视清季有加。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "视秩", "t": "比照品级次第。"}]}, {"meaning": "效法。", "cites": [{"t": "王懋乃德,视乃厥祖。", "b": "《书·太甲中》"}], "words": [{"w": "视效", "t": "仿效;效法。"}]}, {"meaning": "接纳。", "cites": [{"t": "故君子于有馈者,弗能见,则不视其馈。", "b": "《礼记·坊记》"}]}, {"meaning": "眼;眼力;视线。", "cites": [{"t": "吾见其难为,怵然为戒,视为止,行为迟。", "b": "《庄子·养生主》"}, {"t": "左手抚炉,炉上有壶,其人视端容寂,若听茶声然。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "视流", "t": "目光流转,不专注于一物"}, {"w": "视躁", "t": "目光不定的样子"}, {"w": "视端", "t": "目光端正。"}]}, {"meaning": "水名。即“涀水” 。在河南省叶县西。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1295wx','祈','1','qí','礻','8','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从示,斤声。本义:向上天或神明求福)。"}, {"meaning": "同本义。", "cites": [{"t": "祈,求福也。", "b": "《说文》"}, {"t": "掌六祈。", "b": "《周礼·大祝》"}, {"t": "祭有祈焉。", "b": "《礼记·郊特牲》"}], "words": [{"w": "祈场", "t": "向神祈祷的场所"}, {"w": "祈祝", "t": "祈求祝福"}, {"w": "祈死", "t": "祈求速死"}, {"w": "祈克", "t": "祈求克敌"}, {"w": "祈祉", "t": "祈求幸福"}, {"w": "祈祓", "t": "祈神除灾去秽"}, {"w": "祈战", "t": "祈求战胜。"}]}, {"meaning": "请求;希望。", "cites": [{"t": "不祈土地。", "b": "《礼记·儒行》"}, {"t": "以祈尔爵。", "b": "《诗·小雅·宾之初筵》"}], "words": [{"w": "祈喜", "t": "求福"}, {"w": "祈借", "t": "求借。"}]}, {"meaning": "假借为 “畿”。古称天子直辖之地。", "cites": [{"t": "《祈父》,刺宣王也。", "b": "《诗·小雅·祈父序》孔颖达《疏》:“当作畿字,今作圻。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1296wx','话','1','huà','讠','8','','[{"pinyin": "huà", "defs": [{"meaning": "(形声。从言,舌声。本义:言语)。"}, {"meaning": "同本义。", "cites": [{"t": "话,合会善言也。", "b": "《说文》"}, {"t": "著之话言。", "b": "《左传·文公六年》"}, {"t": "不知话言。", "b": "《左传·文公十八年》"}, {"t": "告之话言。", "b": "《左传·襄公元年》"}, {"t": "出话不然。", "b": "《诗·大雅·板》"}, {"t": "悦亲戚之情话。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "心诚之话。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "话言", "t": "话语"}, {"w": "话差", "t": "言语纠葛;争吵"}, {"w": "话白儿", "t": "闲话"}, {"w": "话布口袋", "t": "比喻一肚子的话。"}]}, {"meaning": "说;谈。", "cites": [{"t": "话,言也。", "b": "《尔雅·释诂》"}, {"t": "乃话民之弗率。", "b": "《书·盘庚》"}, {"t": "把酒话桑麻。", "b": "唐·孟浩然《过故人庄》"}], "words": [{"w": "话夜", "t": "夜谈"}, {"w": "话心", "t": "谈心"}, {"w": "话家常;话雨", "t": "朋友相聚晤谈旧事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1297wx','诞','1','dàn','讠','8','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从言,延声。本义:说大话)。"}, {"meaning": "同本义。", "cites": [{"t": "诞,词诞也。", "b": "《说文》"}, {"t": "诞惟民怨。", "b": "《书·酒诰》"}, {"t": "肆朕诞以尔东征。", "b": "《书·大诰》"}, {"t": "言神事如迂诞。", "b": "《汉书·郊祀志上》。师古曰:“诞,大言也。”"}, {"t": "则诞欺怪迂之文弥以益多。", "b": "《汉书·艺文志》"}], "words": [{"w": "诞诈", "t": "诞妄奸诈"}, {"w": "诞辞", "t": "虚诞的言辞"}, {"w": "诞言", "t": "夸大的话。"}]}, {"meaning": "虚妄;荒唐。", "cites": [{"t": "是言诞也。", "b": "《国语·楚语》。注:“虚也。”"}, {"t": "非诞说矣。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "诞妄", "t": "虚妄不实"}, {"w": "诞谩", "t": "荒诞不实。"}]}, {"meaning": "大。", "cites": [{"t": "诞告万方。", "b": "《书·汤诰》传:“诞,大也。”"}, {"t": "诞先登于岸。", "b": "《诗·大雅·皇矣》"}], "words": [{"w": "诞命", "t": "大命,承受天命"}, {"w": "诞章", "t": "弘大的法度典章。"}]}, {"meaning": "生育;出生。", "cites": [{"t": "上诞日,不纳中外之贡。", "b": "《旧唐书·德宗纪》"}, {"t": "庆门诞瓦,寒舍得雄。", "b": "《剪灯余话》"}], "words": [{"w": "诞辰;诞日;诞育", "t": "生育"}, {"w": "诞圣", "t": "诞生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1298wx','诡','1','guǐ','讠','8','','[{"pinyin": "guǐ", "defs": [{"meaning": "(形声。从言,危声。本义:责成,要求)。"}, {"meaning": "同本义。", "cites": [{"t": "诡,责也。", "b": "《说文》"}, {"t": "自诡灭贼。", "b": "《汉书·赵充国传》"}, {"t": "今臣得出守郡,自诡效功,恐未效而死。", "b": "《汉书·京房传》"}], "words": [{"w": "诡求", "t": "要求,责求"}, {"w": "诡驳", "t": "责难驳斥"}, {"w": "诡责", "t": "责备;责问"}, {"w": "诡令", "t": "责令。"}]}, {"meaning": "违反,自相矛盾。", "cites": [{"t": "诡,违也。", "b": "《西京赋》注引《说文》"}, {"t": "容服有仪谓之仪,反仪为诡。", "b": "《贾子道术》"}, {"t": "诡自然之性。", "b": "《淮南子·主术》"}, {"t": "古今诡趣。", "b": "《淮南子·辩亡论》"}, {"t": "言行相诡,不祥莫大焉。", "b": "《吕氏春秋·淫辞》"}], "words": [{"w": "诡故", "t": "违反本心"}, {"w": "诡局", "t": "同诡句、诡论。哲学名词。加以肯定或否定都会获致相反结果的局面、论点或述句。"}]}, {"meaning": "隐蔽;隐藏。", "cites": [{"t": "不得已,变姓名,诡踪迹。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "怪异,奇异。", "cites": [{"t": "其名为吊诡。", "b": "《庄了·齐物论》"}, {"t": "诡文回波。", "b": "《淮南子·本经》。注:“奇异也。”"}, {"t": "殊形诡制,每各异观。", "b": "汉·班固《西都赋》"}, {"t": "神仙诡诞之说,谓颜太师以兵解,文少保亦以悟大光明法蝉脱,实未尝死。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "诡形", "t": "奇异的形状"}, {"w": "诡特", "t": "奇特怪异"}, {"w": "诡喻", "t": "奇诡的比喻"}, {"w": "诡说", "t": "虚妄怪诞的言论。"}]}, {"meaning": "欺诈;假冒。", "cites": [{"t": "持诡辩以中伤人。", "b": "《汉书·石显传》"}, {"t": "求利之诡缓。", "b": "《荀子·正论》。注:“诈也。”"}, {"t": "汉求武等,匈奴诡言武死。", "b": "《汉书·苏武传》"}], "words": [{"w": "诡对", "t": "以虚伪、欺诈的言辞对答"}, {"w": "诡遇", "t": "打猎时不按礼法规定而横射禽兽"}, {"w": "诡弊", "t": "欺骗蒙蔽"}, {"w": "诡得", "t": "用不正当的手段取得。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1299wx','询','1','xún','讠','8','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从言,旬声。本义:询问,请教)。"}, {"meaning": "同本义。", "cites": [{"t": "今因经无以询为问罪字,遂用讯不用询,其实讯询一字也。", "b": "朱骏声《说文通训定声》"}, {"t": "询事考言。", "b": "《虞书》"}, {"t": "周爰咨询。", "b": "《诗·小雅·皇皇者华》"}, {"t": "询尔仇方。", "b": "《诗·大雅·皇矣》"}, {"t": "咨亲为询。", "b": "《左传·襄公四年》"}, {"t": "询于八虞。", "b": "《国语·晋语》"}, {"t": "秦大夫不询于我寡君。", "b": "《左传·成公十三年》"}, {"t": "咨才为诹,咨事为谋,咨义为度,咨亲为询。", "b": "《国语》"}, {"t": "民俗,事疑必询三老。", "b": "马中锡《中山狼传》"}, {"t": "苟无至诚恻怛忧天下之心,则不能询考贤才,讲求法度。", "b": "宋·王安石《上时政疏》"}], "words": [{"w": "询悉", "t": "询问后得知"}, {"w": "探询", "t": "探问"}, {"w": "咨询", "t": "征求意见"}, {"w": "询察", "t": "稽查访问。"}]}, {"meaning": "查考;打听。", "cites": [{"t": "燕多剧贼…楚材询察得其姓名,皆留后亲属及势家子,尽捕下狱。", "b": "《元史》"}], "words": [{"w": "询质", "t": "查考和质正"}, {"w": "询索", "t": "查访"}, {"w": "询按", "t": "查核按验"}, {"w": "询究", "t": "查考,究门。"}]}, {"meaning": "谋。", "cites": [{"t": "帝曰:格汝舜,询事考言,乃言底可绩。", "b": "《书·舜典》。孔传:“询,谋。”"}], "words": [{"w": "询谋", "t": "谋于众人。"}]}, {"meaning": "均,协调。", "cites": [{"t": "四时推六律、六吕,询十有二变,而道宏广。", "b": "《尚书大传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1300wx','该','1','gāi','讠','8','','[{"pinyin": "gāi", "defs": [{"meaning": "(形声。从言,亥声。本义:军中互相戒守的约言。《说文》:“该,军中约也。”引申为“完备”。引申义:完备,包括一切"}, {"meaning": "同引申义。", "cites": [{"t": "此该之变而道之也。", "b": "《谷梁传·哀公元年》。注:“备也。”"}, {"t": "招具该备。", "b": "《楚辞·招魂》"}, {"t": "又撰《西京记》三卷,引据该洽,世称其博闻焉。", "b": "《周书·卢寊传》"}], "words": [{"w": "该洽", "t": "完备周详"}, {"w": "该备", "t": "完备,详备"}, {"w": "该尽", "t": "完备无遗"}, {"w": "该详", "t": "完备详尽。"}]}, {"meaning": "包容;包括。", "cites": [{"t": "该秉季德。", "b": "《楚辞·天问》。注:“包也。”"}, {"t": "旁该终始。", "b": "《太玄·云图》。注:“兼也。”"}, {"t": "《广韵》一书可以该六书之学,其用宏矣。", "b": "潘来《重刊古本广韵序》"}], "words": [{"w": "该臧", "t": "包藏和充塞"}, {"w": "该遍", "t": "包容一切"}, {"w": "该兼", "t": "包容,兼容"}, {"w": "该天", "t": "遮天"}, {"w": "该括", "t": "包罗,概括。"}]}, {"meaning": "应该;应当(宋、元时才出现此义)。", "cites": [{"t": "(凤姐)说道:天也不早了,我也该起来了。", "b": "《红楼梦》"}], "words": [{"w": "不该拒绝;该当;该办;我们该走了", "t": ""}]}, {"meaning": "欠。", "cites": [{"t": "人家该咱们的,咱们该人家的…算一算,看看还有几个钱没有。", "b": "《红楼梦》"}], "words": [{"w": "我不该他钱", "t": ""}]}, {"meaning": "表示范围,相当于“全”、“都”。", "cites": [{"t": "招具该备,永啸呼些。", "b": "《楚辞》"}, {"t": "如万事该悉。", "b": "《北史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1301wx','详','1','xiáng','讠','8','','[{"pinyin": "xiáng", "defs": [{"meaning": "(形声。从言,羊声。本义:审察,审理)。"}, {"meaning": "同本义。", "cites": [{"t": "详,审议也。", "b": "《说文》"}, {"t": "度作详刑,以诘四方。", "b": "《书·吕刑》。郑注:“审察之也。”"}, {"t": "凤姐详情度理,说:“他们必不敢多说一句话。”", "b": "《红楼梦》"}, {"t": "愿明上详之。", "b": "《三国演义》"}], "words": [{"w": "详允", "t": "审判得当、公平"}, {"w": "详当", "t": "详审而允当"}, {"w": "详阅", "t": "审查批阅。"}]}, {"meaning": "详细说明。", "words": [{"w": "详梦", "t": "解梦;析梦"}, {"w": "内详;另详", "t": ""}]}, {"meaning": "清楚地知道。", "cites": [{"t": "非君所详。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "亦不详其姓字。", "b": "陶潜《五柳先生传》"}], "words": [{"w": "详典", "t": "了解典据。"}]}, {"meaning": "旧时下级将案情向上级报告请示。", "cites": [{"t": "漏报填格,详府审转。", "b": "《红楼梦》"}, {"t": "一到任就有件人命官司详至案下。", "b": "《红楼梦》"}], "words": [{"w": "详革", "t": "请示罢免;撤职"}, {"w": "详参揭报", "t": "上报揭发进行弹劾"}, {"w": "详报", "t": "上报,申报。"}]}, {"meaning": "祷祝。", "cites": [{"t": "轻则到园化纸许愿,重则详星拜斗。", "b": "《红楼梦》"}]}, {"meaning": "揣摩;推断。", "cites": [{"t": "详起那签文来,我们要抱外孙也不会太迟。", "b": "茅盾《霜叶红似二月花》"}], "words": [{"w": "详玩", "t": "揣摩;玩味。"}]}, {"meaning": "详细;详尽。", "cites": [{"t": "博学而详说之。", "b": "《孟子》。注:“悉也。”"}, {"t": "君其详之。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "言之不详。", "b": "宋·苏轼《石钟山记》"}, {"t": "条理甚详。", "b": "清·梁启超《谭嗣同传》"}, {"t": "一一详述。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "周详", "t": "周到而详细"}, {"w": "详征博引", "t": "详细而广博地引证"}, {"w": "详究", "t": "详细追究。"}]}, {"meaning": "公平。", "cites": [{"t": "刑戮将甚不详。", "b": "《汉书·食货志下》"}], "words": [{"w": "详正", "t": "平正。"}]}, {"meaning": "吉祥", "cites": [{"t": "不能退,不能遂,不详也。", "b": "《易·大壮》"}, {"t": "详以事神,义以建利。", "b": "《左传·成公十六年》"}, {"t": "告从不赦不详。", "b": "《公羊传·宣公十二年》"}]}, {"meaning": "庄重。", "cites": [{"t": "性沈详而不烦。", "b": "宋玉《神女赋》"}]}, {"meaning": "安详。", "cites": [{"t": "神仪妩媚,举止详妍。", "b": "陶潜《闲情赋》"}], "words": [{"w": "详雅", "t": "安详文雅"}, {"w": "详妍", "t": "安详美好。"}]}, {"meaning": "详情;细节。", "cites": [{"t": "访其根因来历,往往能道本末之详。", "b": "元·陈天祥《论卢世荣奸邪状》"}]}, {"meaning": "旧时下级将案情向上级请示报告的公文。", "cites": [{"t": "混详塞责取咎云云。", "b": "《歧路灯》"}, {"t": "只好藏在家中听候转详。", "b": "《红楼梦》"}], "words": [{"w": "详文", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1302wx','建','1','jiàn','廴','8','','[{"pinyin": "jiàn", "defs": [{"meaning": "(会意。从廴(yǐn),有引长的意思,从聿(意为律)。本义:立朝律)。"}, {"meaning": "同本义。", "cites": [{"t": "立朝律也。", "b": "《说文》"}, {"t": "建,立也。", "b": "《广雅》"}], "words": [{"w": "建法", "t": "制定法律"}, {"w": "建中", "t": "定立标准"}, {"w": "建极", "t": "制定至中至正的建国大法。"}]}, {"meaning": "引申为建立、创设。", "cites": [{"t": "官惟王建国。", "b": "《周礼·天官序》"}, {"t": "掌建邦之宫刑。", "b": "《周礼·小宰》"}, {"t": "州建百里之国三十。", "b": "《礼记·王制》"}, {"t": "皇建其有极。", "b": "《书·洪范》"}, {"t": "择建立卜筮人。", "b": ""}, {"t": "夫位政之建也。", "b": "《国语·鲁语》"}, {"t": "足下自以为善汉王,欲建万世之业,臣窃以为误矣。", "b": "《史记·淮阴侯列传》"}, {"t": "德之不建。", "b": "《国语·晋语》"}, {"t": "建伊皋之业。", "b": "明·刘基《卖柑者言》"}, {"t": "建一官而三物成。", "b": "《左传·襄公三年》"}], "words": [{"w": "建官", "t": "设置官职"}, {"w": "建封", "t": "设置爵位,分封诸侯"}, {"w": "建竖", "t": "建立功绩"}, {"w": "建醮净宅", "t": "设场建坛,用酒祭神以祛除宅院里的邪气"}, {"w": "建本", "t": "奠定基础,建立根本。"}]}, {"meaning": "封立。", "cites": [{"t": "利建侯。", "b": "《易·屯》"}, {"t": "天子建德,因生以赐姓。", "b": "《左传·隐公八年》"}, {"t": "康王息民,并建母弟以蕃屏周。", "b": "《左传·昭公二十六年》"}], "words": [{"w": "建侯", "t": "封立诸侯;封侯建国;立功封侯"}, {"w": "建德", "t": "封立有德者为诸侯。"}]}, {"meaning": "树立、竖起。", "cites": [{"t": "九十杖而朝见君见杖。", "b": "《书·大传》"}, {"t": "设此旐矣,建彼旄矣。", "b": "《诗·小雅·出车》"}, {"t": "建鼓在阼阶西。", "b": "《仪礼·大射仪》"}, {"t": "乘轺建节。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "上建旌旗。", "b": "《资治通鉴》"}], "words": [{"w": "建鼓", "t": "立鼓"}, {"w": "建旗", "t": "树立旗帜"}, {"w": "建牙", "t": "古时出师,在军前树立军旗"}, {"w": "建节", "t": "树立节操"}, {"w": "建标", "t": "树立标志"}, {"w": "建麾", "t": "树立旌旗。"}]}, {"meaning": "建筑;建造。", "cites": [{"t": "建丛台于后。", "b": "张衡《东京赋》"}], "words": [{"w": "建缮", "t": "建筑修缮。"}]}, {"meaning": "倡仪;提出。", "cites": [{"t": "愛盎等皆建以为不可。", "b": "《汉书·邹阳传》。注:“谓立议。”"}], "words": [{"w": "建言", "t": "建议,陈述己见"}, {"w": "建倡", "t": "倡议"}, {"w": "建明", "t": "建白。陈述意见"}, {"w": "建策", "t": "献出谋策"}, {"w": "建陈", "t": "提议陈请"}, {"w": "建画", "t": "建议谋划"}, {"w": "建弼", "t": "建议和辅佐。"}]}, {"meaning": "为岁首的历法。"}, {"meaning": "星官名。建星(古星官名。亦省称“建”。凡六星。在黄道北。与南斗六星同属斗宿)。"}, {"meaning": "", "cites": [{"t": "广德若不足,建德若偷,质德若渝。", "b": "《老子·四十一章》"}], "words": [{"w": "建德", "t": "刚健之德"}, {"w": "大建", "t": "指30、31天之月"}, {"w": "小建", "t": "29天之月。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1303wx','肃','1','sù','聿','8','','[{"pinyin": "sù", "defs": [{"meaning": "(会意。小篆字形。表示人战战兢兢,非常畏惧小心。本义:{恭敬})。"}, {"meaning": "同本义。", "cites": [{"t": "肃,持事振敬也。", "b": "《训文》"}, {"t": "忠肃共懿。", "b": "《左传·文公十八年》"}, {"t": "肃肃在庙。", "b": "《诗·大雅·思齐》"}, {"t": "又能齐肃衷正。", "b": "《国语·楚语》"}, {"t": "宽肃宣惠。", "b": "《国语·周语》"}, {"t": "貌之不恭,是谓不肃。", "b": "《汉书·五行志》"}, {"t": "入掖庭为人,时年十六。恭肃小心,动有法度。", "b": "《后汉书·邓皇后传》"}], "words": [{"w": "肃敬", "t": "恭恭敬敬"}, {"w": "肃迓", "t": "恭迎"}, {"w": "肃奉", "t": "恭敬地接受或遵奉"}, {"w": "肃括", "t": "恭敬而有法度。指人的威仪。亦有于治学和书法、文辞等"}, {"w": "肃修", "t": "恭敬地修书。致亲友书札用语"}, {"w": "肃如", "t": "恭敬的样子"}, {"w": "肃服", "t": "恭敬顺服"}, {"w": "肃然", "t": "恭敬的样子"}, {"w": "肃肃", "t": "恭敬的样子。"}]}, {"meaning": "庄重;严肃。", "cites": [{"t": "广廷严居,众人之所肃也,晏室独处,曾(参)史(鳅)之所僈也。", "b": "《韩非子·难三》"}, {"t": "衡下车,治威严,整法度,阴知奸党名姓,一时收禽,上下肃然,称为政理。", "b": "《后汉书·张衡传》"}], "words": [{"w": "肃命", "t": "严肃命令"}, {"w": "肃括", "t": "仪容严正而有礼法"}, {"w": "肃容", "t": "严肃的仪容"}, {"w": "肃陈", "t": "陈列严整"}, {"w": "肃戒", "t": "严肃地告诫或警戒"}, {"w": "肃坐", "t": "古坐容之一。后指端正地坐着。"}]}, {"meaning": "清静;安静。", "cites": [{"t": "出紫宫之肃肃兮,集大微之阆阆。", "b": "《后汉书·张衡传·思玄赋》"}], "words": [{"w": "肃肃", "t": "清寂,幽静"}, {"w": "肃烈", "t": "肃穆威烈"}, {"w": "肃森", "t": "阴森的样子"}, {"w": "肃听", "t": "静听。含恭敬意。"}]}, {"meaning": "峻急。十万火急的。", "cites": [{"t": "刑肃而俗敝,则法无常。", "b": "《礼记》"}]}, {"meaning": "敏捷", "cites": [{"t": "肃肃宵片,夙夜在公,寔命不同。", "b": "《诗·召南·小星》"}], "words": [{"w": "肃给", "t": "敏捷"}, {"w": "肃肃", "t": "迅速的样子。"}]}, {"meaning": "揖拜。拜礼之一。即揖。今妇人行礼称端肃,朋友通函称肃启、谨肃,本此。", "cites": [{"t": "敢告不宁君命之辱,为事之故,敢肃会者。", "b": "《左传·成公十六年》"}], "words": [{"w": "肃拜", "t": "古九拜之一。即揖。身体直立,容貌严肃,微下手以拜"}, {"w": "肃揖", "t": "肃拜。直立作揖"}, {"w": "肃香", "t": "供香。"}]}, {"meaning": "恭敬地引进。", "cites": [{"t": "主人肃客而入。", "b": "《礼·曲礼》"}], "words": [{"w": "肃客", "t": "迎进客人。"}]}, {"meaning": "衰落,萎缩。", "cites": [{"t": "季春行冬令,则寒气时发,草木皆肃。", "b": "《吕氏春秋·季春纪》"}], "words": [{"w": "肃物", "t": "摧残万物。指深秋肃杀之气使草木凋谢"}, {"w": "肃气", "t": "肃杀之气"}, {"w": "肃景", "t": "秋景。秋气肃杀,故称。"}]}, {"meaning": "清除;平靖;肃清。", "cites": [{"t": "师不踰时,梁益肃清。", "b": "《文选·孙誓·为石仲容与孙皓书》"}], "words": [{"w": "肃菁", "t": "肃清。削平寇乱"}, {"w": "肃靖", "t": "清扫;平定"}, {"w": "肃齐", "t": "安靖整饬"}, {"w": "有反必肃", "t": ""}]}, {"meaning": "整饬;整肃。", "cites": [{"t": "保护圣主,复大权,清君侧,肃宫廷,指挥若定不世之业也。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "肃正", "t": "整饬,使端正"}, {"w": "肃衣", "t": "整衣"}, {"w": "肃治", "t": "整顿治理。"}]}, {"meaning": "古代州名 。隋置。在今甘肃省。", "cites": [{"t": "肃,州名,古月氏国也。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1304wx','录','1','lù','彐','8','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从金,录声。本义:绿色金属)。"}, {"meaning": "同本义。", "cites": [{"t": "録,金色也。", "b": "《说文》"}]}, {"meaning": "记载言行事物的册籍。", "cites": [{"t": "录,记之具也。", "b": "《广雅·释诂三》"}, {"t": "皆辨其物而奠其录。", "b": "《周礼·职币》"}], "words": [{"w": "言行录;名人录", "t": ""}]}, {"meaning": "次第,次序。", "cites": [{"t": "今大国越录。", "b": "《国语·吴语》"}]}, {"meaning": "总领。", "cites": [{"t": "融为太尉,并录尚书事。", "b": "《后汉书·章帝纪》"}], "words": [{"w": "录公", "t": "对总领台阁尚书事者的敬称。"}]}, {"meaning": "抄写(含有有选择地照样誊写的意味)。", "cites": [{"t": "手自笔录。", "b": "明·宋濂《送东阳马生序》"}]}, {"meaning": "又。", "cites": [{"t": "余之手录。", "b": ""}], "words": [{"w": "抄录", "t": "抄写"}, {"w": "录黄", "t": "宋代中书省枢密院承旨抄录颁送门下省的文件。"}]}, {"meaning": "记载。", "cites": [{"t": "《春秋》录内而略外。", "b": "《公羊传·隐公十年》"}, {"t": "录功而与官,则莫敢索官。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "采录", "t": "采集并记录"}, {"w": "笔录", "t": "用笔记录"}, {"w": "录囚", "t": "审讯登录囚犯的罪状。"}]}, {"meaning": "采取。", "cites": [{"t": "君既若见录。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "录用", "t": "录取任用"}, {"w": "录遗", "t": "选录遗才。"}]}, {"meaning": "记;惦记。", "cites": [{"t": "君既若见录,不久望君来。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "逮捕。", "cites": [{"t": "吏录一犯夜人来。", "b": "《世说新语·政事》"}]}, {"meaning": "收集;收藏。", "cites": [{"t": "敕船官悉录锯木屑,不限多少。", "b": "《世说新语·政事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1305wx','隶','1','lì','隶','8','','[{"pinyin": "lì", "defs": [{"meaning": "(隶:又樆尾会意。本义:逮、捕、追及)。"}, {"meaning": "同本义。", "cites": [{"t": "隶,及也,从又从尾省,又持尾者从后及之也。", "b": "《说文》"}]}, {"meaning": "跟从;附属。", "cites": [{"t": "隶而从者。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "不隶于宫观之籍。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "隶事", "t": "以故事相互隶属。"}]}, {"meaning": "流离。", "cites": [{"t": "饿馑流隶,饥寒道路。", "b": "《汉书·叙传·王命论》"}]}, {"meaning": ""}, {"meaning": "检查。", "cites": [{"t": "关东吏隶郡国出入关者。", "b": "《史记·酷吏列传》"}]}, {"meaning": "练习。", "cites": [{"t": "廼令群臣习隶。", "b": "《史记·刘敬叔孙通列传》"}]}, {"meaning": "中囯古代对一种奴隶或差役的称谓。", "cites": [{"t": "輿臣隶,隶臣僚。", "b": "《左传》"}, {"t": "皆得以隶使之。", "b": "明·张溥《五人墓碑记》"}, {"t": "甿隶之人。", "b": "汉·贾谊《过秦论》"}, {"t": "欲效野夫贱隶。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "出入必輿隶。", "b": ""}], "words": [{"w": "隶人", "t": "职位低微的吏役;因罪被罚为官奴而从事劳役的人"}, {"w": "隶仆", "t": "仆役"}, {"w": "隶户", "t": "被没入为奴隶的人家"}, {"w": "隶农", "t": "农奴,佃户,代耕农。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1306wx','帚','1','zhǒu','巾','8','','[{"pinyin": "zhǒu", "defs": [{"meaning": "(象形。甲骨文字形,象扫帚形。本义:扫帚) 同本义。", "words": [{"w": "笤帚", "t": "扫帚"}, {"w": "帚卜", "t": "吴中旧俗,妇女于正月灯节用裙束破帚以占事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1307wx','屉','1','tì','尸','8','','[{"pinyin": "tì", "defs": [{"meaning": "鞍屉,马鞍垫子。", "cites": [{"t": "屉,鞍屉也。", "b": "《字汇》"}]}, {"meaning": "抽屉。", "cites": [{"t": "暂设装奁,还抽镜屉。", "b": "北周·庾信《镜赋》"}]}, {"meaning": "笼屉 。", "words": [{"w": "刚出屉的包子好吃", "t": ""}]}, {"meaning": "窗棂;窗格子。", "cites": [{"t": "那窗上的纸,隔着屉子,渐渐的透进清光来。", "b": "《红楼梦》"}]}, {"meaning": "“屟”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1308wx','居','1','jū','尸','8','','[{"pinyin": "jū", "defs": [{"meaning": "(象形。金文字形,是“踞”的本字,象人曲胫蹲踞形。本义:蹲着)。"}, {"meaning": "同本义", "cites": [{"t": "居,蹲也。从尸,古者居从古,俗居从足。", "b": "《说文》"}, {"t": "不宜居见长者。", "b": "《史记》"}, {"t": "昔阖庐食不二味,居不重席,室不崇坛。", "b": "《左传》"}]}, {"meaning": "居住。", "cites": [{"t": "则居可知矣。", "b": "《易·系辞下》"}, {"t": "仁者居之。", "b": "《吕氏春秋·离俗》"}, {"t": "卒不居赵地。", "b": "《吕氏春秋·达郁》"}, {"t": "寝居直梦。", "b": "《淮南子·地形》"}, {"t": "居者,居其所也。", "b": "《谷梁传·僖公二十四年》"}, {"t": "天王出居于郑。", "b": "《左传·僖公二十四年》"}, {"t": "面山而居。", "b": "《列子·汤问》"}, {"t": "楚人贫居。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "君子居必择乡。", "b": "《荀子·劝学》"}, {"t": "自吾氏三世居是乡。", "b": "柳宗元《捕蛇者说》"}, {"t": "城居者未之知。", "b": "明·袁宏道《满井游记》"}, {"t": "居者皆猎户。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "居俭", "t": "居家俭约"}, {"w": "居恒", "t": "安闲度日"}, {"w": "居移气,养移体", "t": "人的所处环境可以改变人的气质,供养可以改变人的体质。"}]}, {"meaning": "坐。", "cites": [{"t": "居,吾语女。", "b": "《礼记·乐记》。注:“坐也。”"}, {"t": "孔子闲居。", "b": "《仲尼燕居》"}, {"t": "数各居其上三分。", "b": "《礼记·王制》"}, {"t": "令女居其上。", "b": "褚少孙《西门豹治邺》"}]}, {"meaning": "处在,处于。", "cites": [{"t": "佛印居石。", "b": "明·魏学洢《核舟记》"}, {"t": "鲁直居左。", "b": ""}, {"t": "居左者右手执蒲葵扇。", "b": ""}, {"t": "居右者椎髻。", "b": ""}], "words": [{"w": "居先", "t": "处于先位"}, {"w": "居卖", "t": "在市场上做买卖"}, {"w": "居贫", "t": "处于贫困的境地"}, {"w": "居安资深", "t": "掌握学问牢固而根底深厚"}, {"w": "居易", "t": "处于平常情况。"}]}, {"meaning": "积储。", "cites": [{"t": "假货居贿。", "b": "《国语·晋语》"}, {"t": "居物致富。", "b": "《汉书·张汤传》"}, {"t": "居为奇货。", "b": "《聊斋志异·促织》"}, {"t": "居之以为利。", "b": ""}], "words": [{"w": "居积", "t": "囤积财物"}, {"w": "居仁由义", "t": "内心存仁,行事循义"}, {"w": "居物", "t": "囤积财物"}, {"w": "居贩", "t": "居积贩卖。"}]}, {"meaning": "占。", "cites": [{"t": "谋计居多。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "二者必居其一;居多", "t": "占多数"}, {"w": "居有", "t": "据有,占有。"}]}, {"meaning": "治理;安置。", "cites": [{"t": "居天下之人,使安其业。", "b": "柳宗元《梓人传》"}], "words": [{"w": "居材", "t": "处置木材"}, {"w": "居处", "t": "安置;处置。"}]}, {"meaning": "停止;休息;止息。", "cites": [{"t": "居十日。", "b": "《韩非子·喻老》"}, {"t": "居五日。", "b": ""}, {"t": "居数月。", "b": "《淮南子·人间训》"}, {"t": "不可久居。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "傲慢。", "cites": [{"t": "莫肯下遗,式居娄骄。", "b": "《韩非子·诡使》"}]}, {"meaning": "住所,住宅。", "cites": [{"t": "问其名居,不告而退。", "b": "《左传·宣公二年》"}, {"t": "居停主人勿复言。", "b": "《宋史·丁谓传》"}, {"t": "其居仅仅足。", "b": "清·洪亮吉《治平篇》"}, {"t": "一人之居。", "b": ""}], "words": [{"w": "居停", "t": "主人,东家;寓所,临时借住的地方"}, {"w": "居址", "t": "住所地址"}, {"w": "居庐", "t": "泛指住房"}, {"w": "居宿", "t": "指住处。"}]}, {"meaning": "平素家居。", "cites": [{"t": "居则曰:“不吾知也。”", "b": "《论语·先进》"}], "words": [{"w": "居平", "t": "居常"}, {"w": "居冠", "t": "古代官员退朝居家时所戴的帽子"}, {"w": "居盈", "t": "过富贵生活"}, {"w": "居常", "t": "平时,平常。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1309wx','届','1','jiè','尸','8','','[{"pinyin": "jiè", "defs": [{"meaning": "(形声。从尸,凷(kuài)声。本义:人行路不便) 同本义。", "cites": [{"t": "届,行不便也。", "b": "《说文》"}]}, {"meaning": "极限;穷极。", "cites": [{"t": "至天之届,于河之沂。", "b": "晋·陆云诗"}, {"t": "靡有夷届。", "b": "《诗·大雅·瞻卬》"}, {"t": "君子如届,俾民心阕。", "b": "《诗·小雅·节南山》"}]}, {"meaning": "到达。", "cites": [{"t": "无远弗届。", "b": "《书·大禹谟》"}], "words": [{"w": "届候", "t": "届时"}, {"w": "届止", "t": "停留,止息"}, {"w": "届路", "t": "登程,上路。"}]}, {"meaning": "届满,结束 (如一段时间)。", "cites": [{"t": "距悔罪乞降之始末届十年。", "b": "林则徐文"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1310wx','刷','1','shuā shuà','刂','8','','[{"pinyin": "shuā", "defs": [{"meaning": "(形声。本义:清扫;揩拭;冲洗)。"}, {"meaning": "同本义。", "cites": [{"t": "刷,刮也。礼有刷巾。", "b": "《说文》"}, {"t": "刷羽汎清源。", "b": "《文选·沈约和谢宣城诗》"}, {"t": "旦刷幽燕,昼秼荆越。", "b": "颜延之《赫白马赋》"}, {"t": "秋刷。", "b": "《周礼·凌人》"}, {"t": "洗兵海岛,刷马江州。", "b": "晋·左思《魏都赋》"}], "words": [{"w": "刷刮", "t": "擦拭"}, {"w": "刷涤", "t": "洗刷;洗除"}, {"w": "刷刨", "t": "刮擦;刷拭"}, {"w": "刷剃", "t": "擦眼泪。"}]}, {"meaning": "清除;洗雪。", "cites": [{"t": "王虽东取地于越,不足以刷耻。", "b": "《史记·楚世家》"}, {"t": "欲刷耻改行。", "b": "《汉书·武帝纪》"}, {"t": "刷会稽之耻。", "b": "班固《汉书》"}], "words": [{"w": "刷淤", "t": "清除淤泥"}, {"w": "刷剔", "t": "删汰。"}]}, {"meaning": "刷抹;涂抹。", "cites": [{"t": "淡天刷墨晓来阴。", "b": "宋·杨万里《发银树林》"}], "words": [{"w": "刷墨", "t": "涂墨"}, {"w": "刷字", "t": "谦词。犹涂抹成字"}, {"w": "刷色", "t": "着色,涂上的颜色"}, {"w": "刷腻", "t": "擦抹油脂。"}]}, {"meaning": "选取。", "cites": [{"t": "新刷来的头巾。", "b": "睢景臣《哨遍·高祖还乡》"}], "words": [{"w": "刷选", "t": "搜寻;挑选"}, {"w": "刷充", "t": "选取充当。"}]}, {"meaning": "查,查核;查究。", "cites": [{"t": "加老夫两淮提刑廉访使之职,随处审囚刷卷。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "刷照", "t": "清查,查阅"}, {"w": "刷卷", "t": "元代由肃政廉访使清查所属各衙门处理狱讼案件有无拖延枉曲,称刷卷"}, {"w": "刷问", "t": "追究;查问"}, {"w": "刷磨", "t": "清理;查究"}, {"w": "刷目", "t": "经过审查清理的帐册项目。"}]}, {"meaning": "刷子。", "cites": [{"t": "劲刷理鬓。", "b": "嵇康《养生论》"}], "words": [{"w": "地板刷;钢丝刷;板刷;鞋刷;刷帚", "t": "扫帚。扫除的用具"}, {"w": "刷抿", "t": "一种抿理头发的梳子。"}]}]}, {"pinyin": "shuà", "defs": [{"meaning": "刷白。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1311wx','屈','1','qū','尸','8','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从尸,出声。尸,古文字中是假卧着的人形。本义:弯曲)。"}, {"meaning": "同本义。", "cites": [{"t": "屈,拗曲。", "b": "《广韵》"}, {"t": "凡曲而不伸者皆曰屈。", "b": "《正字通》"}, {"t": "尺蠖之屈,以求信也。", "b": "《易·系辞》"}, {"t": "猬缩蠖屈。", "b": "马中锡《中山狼传》"}, {"t": "不可屈伸。", "b": "明·宋濂《送东阳马生序》"}, {"t": "安能屈豪杰。", "b": "明·张溥《五人墓碑记》"}, {"t": "屈膝叩首。", "b": "清·方苞《狱中杂记》"}, {"t": "不当屈。", "b": "清·张廷玉《明史》"}], "words": [{"w": "屈指询算", "t": "迷信指用手指占算"}, {"w": "屈律", "t": "弯曲的样子"}, {"w": "屈卮", "t": "有弯曲把手的酒杯"}, {"w": "屈申", "t": "屈伸。屈曲和伸展"}, {"w": "诎屈", "t": "曲折;弯曲"}, {"w": "屈伸", "t": "屈曲"}, {"w": "屈屈", "t": "弯弯曲曲"}, {"w": "屈蠖", "t": "曲身的尺蠖。"}]}, {"meaning": "委屈;冤屈。", "cites": [{"t": "不可屈致。", "b": "《三国志·诸葛亮传》"}, {"t": "大书一屈字。", "b": "明·高启《凫藻集·书博鸡者事》"}, {"t": "求一屈己。", "b": "清·刘开《问说》"}, {"t": "被诬负屈。", "b": "清·张廷玉《明史》"}], "words": [{"w": "屈官司", "t": "冤枉官司"}, {"w": "屈致", "t": "随便招请,使人受到委屈"}, {"w": "屈事", "t": "冤枉事"}, {"w": "屈驰", "t": "委屈"}, {"w": "屈气", "t": "怨气"}, {"w": "屈漾", "t": "屈央,屈恙。冤枉"}, {"w": "屈厄", "t": "委屈困顿。"}]}, {"meaning": "屈服。", "cites": [{"t": "屈人之兵。", "b": "《孙子·谋政》"}, {"t": "屈人之兵而非战。", "b": ""}, {"t": "富贵不能淫,贫贱不能移,威武不能屈。", "b": "《孟子·滕文公下》"}], "words": [{"w": "宁死不屈;大丈夫能屈能伸;屈挠", "t": "屈服顺从"}, {"w": "屈伏", "t": "屈服。"}]}, {"meaning": "治理,收治。", "cites": [{"t": "顺彼长道,屈此群丑。", "b": "《诗·鲁颂·泮水》"}]}, {"meaning": "强迫。", "cites": [{"t": "力不胜,皆屈为僮。", "b": "柳宗元《童区寄传》"}]}, {"meaning": "理亏。", "cites": [{"t": "理屈词穷。", "b": "清·纪昀《阅微草堂笔记》"}]}, {"meaning": "古邑名 。春秋晋地。在今山西省吉县北,盛产良马。"}, {"meaning": "假借为“崛”。高起,突出。", "cites": [{"t": "而得屈起在此位者也。", "b": "《汉书·叙传上》"}]}, {"meaning": "假借为“倔”。直傲不屈。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1312wx','弧','1','hú','弓','8','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从弓,瓜声。本义:木弓)。"}, {"meaning": "同本义;泛指弓。", "cites": [{"t": "弧,木弓也。", "b": "《说文》"}, {"t": "弦木为弧。", "b": "《易·系传》"}, {"t": "檿弧箕服。", "b": "《国语·郑语》"}, {"t": "弧弓夭猎。", "b": "《汉书·韩安国传》"}], "words": [{"w": "弧弓", "t": "古代六弓之一。其力强,可以远射甲革坚硬之物。六弓:王弓、弧弓、夹弓、庚弓、唐弓、大弓"}, {"w": "孤矢", "t": "弓箭"}, {"w": "孤室", "t": "弓袋"}, {"w": "弧弦", "t": "开弓张弦。"}]}, {"meaning": "张旗用的竹弓。", "cites": [{"t": "载弧屬。", "b": "《礼记·明堂位》"}], "words": [{"w": "弧旌枉矢", "t": "谓以竹弓张悬旌旗的正幅,并在弓衣上绘流矢,作弧矢星状,以象征武事。"}]}, {"meaning": "弯曲如弓。", "cites": [{"t": "采其有弧矢之威。", "b": "《礼记·大射仪》注"}, {"t": "燕弧盈库而委劲。", "b": "《魏都赋》"}], "words": [{"w": "弧圈", "t": "弧线"}, {"w": "弧深", "t": "谓弯曲度深。"}]}, {"meaning": "圆弧。"}, {"meaning": "电弧。", "cites": [{"t": "弧电压", "b": ""}]}, {"meaning": "在地面上沿一条曲线重复出现的地质或地形特征。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1313wx','弥','1','mí','弓','8','','[{"pinyin": "mí", "defs": [{"meaning": "(形声。从弓,尔声。本义:放松弓弦)。"}, {"meaning": "同本义。", "cites": [{"t": "彌,驰弓也。", "b": "《说文》"}, {"t": "弥,《说文》:弛弓也。", "b": "《集韵》"}]}, {"meaning": "充满;填满。", "cites": [{"t": "弥缝其阙,而匡救其灾。", "b": "《左传》"}], "words": [{"w": "弥封;弥补;弥缝", "t": ""}]}, {"meaning": "停止。", "cites": [{"t": "不弥人争。", "b": "《管子·四称》"}, {"t": "以弥乱发姦,登大司马,职在内辅。", "b": "《汉书·王莽传》"}]}, {"meaning": "遍;满。", "cites": [{"t": "弥山跨谷。", "b": "《汉书·司马相如传》。注:满也。”"}, {"t": "弥祀社稷祷祠。", "b": "《周礼·大祝》。注:“犹徧也。”"}, {"t": "马畜弥山。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "弥天亘地", "t": "满天连地,形容巨大无比"}, {"w": "弥旬", "t": "满十天"}, {"w": "弥衍", "t": "蔓延;满溢"}, {"w": "弥期", "t": "满一年"}, {"w": "弥望", "t": "充满视野;满眼"}, {"w": "弥竞", "t": "布满"}, {"w": "弥襟", "t": "满怀"}, {"w": "弥罗", "t": "包罗;布满。"}]}, {"meaning": "广。", "cites": [{"t": "弥纶天地之道。", "b": "《易·系辞》"}], "words": [{"w": "弥茫", "t": "广远,迷茫"}, {"w": "弥广", "t": "广阔;辽阔。"}]}, {"meaning": "久;远。", "cites": [{"t": "历世弥久。", "b": "《汉石门颂》"}, {"t": "俾尔弥尔性。", "b": "《诗·大雅·卷阿》"}, {"t": "弥望广潒。", "b": "张衡《西京赋》。注:“远也。”"}, {"t": "旷日弥久而无益于理。", "b": "桓宽《盐铁论·相刺》"}], "words": [{"w": "弥久", "t": "长久;愈久"}, {"w": "弥永", "t": "久长"}, {"w": "弥长", "t": "久长"}, {"w": "弥时", "t": "谓历时久。"}]}, {"meaning": "更加;越发。", "cites": [{"t": "是以其曲弥高,其和弥寡。", "b": "宋玉《对楚王问》"}, {"t": "垂二百祀,大业弥固。", "b": "柳宗元《封建论》"}, {"t": "奉之弥繁。", "b": "宋·苏洵《六国论》"}, {"t": "弥觉其甘。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "弥至", "t": "更甚;倍至"}, {"w": "弥事", "t": "愈加从事于。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1314wx','弦','1','xián','弓','8','','[{"pinyin": "xián", "defs": [{"meaning": "(会意。左为“弓”,右为“丝”。弓弦是用丝做成的。本义:弓弦)。"}, {"meaning": "同本义。", "cites": [{"t": "弦,弓弦也。从弓,象丝轸之形。", "b": "《说文》"}, {"t": "无待韦弦。", "b": "《文选·王文宪集序》"}, {"t": "故佩弦以自急。", "b": "《韩非子·观行》"}, {"t": "引弦而战。", "b": "《淮南子·人间训》"}, {"t": "抚弦登陴。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "弦箭", "t": "弦上之箭"}, {"w": "弦栝", "t": "弓弦和箭末扣弦处。"}]}, {"meaning": "乐器上的肠线或金属丝。", "cites": [{"t": "弦而鼓之。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "朝歌夜弦。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "转轴拨弦。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "小弦切切", "b": ""}], "words": [{"w": "弦徽", "t": "琴弦与琴徽;系琴弦之绳。后也指琴面上的标志"}, {"w": "弦乐", "t": "丝弦乐器"}, {"w": "弦子", "t": "胡琴"}, {"w": "弦吹", "t": "泛称弦管乐"}, {"w": "弦柱", "t": "乐器上绾丝的柱子"}, {"w": "弦桐", "t": "琴的别名。以桐木为造琴良材,故名。"}]}, {"meaning": "弦乐器。", "cites": [{"t": "孔子烈然返瑟而弦。", "b": "《吕氏春秋》"}], "words": [{"w": "弦子", "t": "胡琴"}, {"w": "弦吹", "t": "指弦乐器和管乐器"}, {"w": "弦柱", "t": "乐器绾丝之柱"}, {"w": "弦乐", "t": "丝弦乐器"}, {"w": "弦子", "t": "三弦。"}]}, {"meaning": "弦乐器弹奏出的声音。", "cites": [{"t": "管清疑警鹤,弦巧似娇莺。", "b": "唐·刘禹锡《历阳书事七十韵》"}], "words": [{"w": "弦歌", "t": "歌泳诵读,也指儒家的礼乐教化"}, {"w": "弦节", "t": "琴瑟之节拍"}, {"w": "弦外之音", "t": "同“絃外之音”。喻指含蓄不尽的言外之意。"}]}, {"meaning": "直角三角形的斜边(直角所对的边)。", "cites": [{"t": "勾三、股四、弦五。", "b": "《周髀算经》"}]}, {"meaning": "四分之一。"}, {"meaning": "地平圈按四分之一划分的一个部分或相当于这一部分的基本方位点。"}, {"meaning": "半圆形的月亮。", "cites": [{"t": "月中分谓之弦。", "b": "《论衡·四讳》"}], "words": [{"w": "弦朔(指农历每月的初七、初八、廿二、廿三日(弦日)和初一(朔日)", "t": ""}, {"w": "弦晦;弦望", "t": "月相变化。"}]}, {"meaning": "周代国名 。春秋时为楚所灭。故城在今河南省潢川县西南。", "cites": [{"t": "楚人灭弦,弦子奔黄。", "b": "《春秋》"}]}, {"meaning": "弦脉。中医指脉气紧张,是脉象之一。", "cites": [{"t": "六脉皆弦,因平日郁结所致。", "b": "《红楼梦》"}], "words": [{"w": "弦怯", "t": "指弦脉虚弱"}, {"w": "弦芤", "t": "切脉时如同指按丝弦、浮大中空。"}]}, {"meaning": "弹奏琴瑟等弦乐器。", "cites": [{"t": "北面而弦。", "b": "《礼记·乐记》。注:“谓鼓琴瑟也。”"}, {"t": "匡坐而弦。", "b": "《庄子·让王》"}, {"t": "春诵夏弦。", "b": "《礼记·文王世子》"}], "words": [{"w": "弦音", "t": "拉弓弦的声音"}, {"w": "弦琴", "t": "弹琴。"}]}, {"meaning": "安上弓弦。", "cites": [{"t": "弦大木为弓。", "b": "《后汉书》"}], "words": [{"w": "弦弧", "t": "在曲木上张弦成弓。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1315wx','承','1','chéng','手','8','','[{"pinyin": "chéng", "defs": [{"meaning": "(会意。甲骨文字形,上面象跽跪着的人,下面象两只手。合起来表示人被双手捧着或接着。本义:捧着)。", "words": [{"w": "承印", "t": "捧印"}, {"w": "承萼", "t": "指物件承托的联结部分"}, {"w": "承盘", "t": "托盘。"}]}, {"meaning": "继承。", "cites": [{"t": "朱明未承夜兮。", "b": "《楚辞·招魂》。注:“续也。”"}, {"t": "承致多福无疆于女孝孙。", "b": "《仪礼·少牢礼》。注:“犹传也。”"}, {"t": "吾本寒家,世以清白相承。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "承袭", "t": "继承"}, {"w": "承家", "t": "承继家业"}, {"w": "承授", "t": "承继传受。"}]}, {"meaning": "接受;承受。", "cites": [{"t": "若不足而不承。", "b": "《庄子·大宗师》"}, {"t": "士于大夫承贺。", "b": "《礼记·王藻》"}], "words": [{"w": "承派", "t": "接受委派"}, {"w": "承教", "t": "谦词。接受教诲"}, {"w": "承做", "t": "接受加工"}, {"w": "承命", "t": "受命。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1316wx','孟','1','mèng','子','8','','[{"pinyin": "mèng", "defs": [{"meaning": "(形声。从子,皿声。本义:妾媵生的长子称“孟”,正妻生的长子称“伯”,后来统称长子)。"}, {"meaning": "同本义。", "cites": [{"t": "孟,长也。", "b": "《说文》"}, {"t": "孟侯。", "b": "《书·康诰》"}, {"t": "天子太子年十八曰孟侯。", "b": "《书·大传》"}, {"t": "彼美孟姜。", "b": "《诗·郑风·有女同车》。传:“齐之长女。”"}, {"t": "孟,姊也。", "b": "《方言十二》"}, {"t": "惠公元妃孟子。", "b": "《左传·隐公元年》"}, {"t": "胡卫道三子:孟曰宽,仲曰定,季曰宕。", "b": "周密《癸辛杂识前集》"}], "words": [{"w": "孟兄;孟孙;孟仲叔季", "t": "兄弟姊妹的长幼顺序,顺次排行为大、二、三、四。"}]}, {"meaning": "始,四季中每季的第一个月。", "cites": [{"t": "孟,始也。", "b": "《广雅》"}, {"t": "孟春之月。", "b": "《礼记·月令》"}, {"t": "摄提贞于孟陬兮。", "b": "《楚辞·离骚》"}, {"t": "孟冬十月,北风徘徊。", "b": "曹操《步出夏门行》"}], "words": [{"w": "孟月", "t": "四季的第一个月,即农历正月、四月、七月、十月"}, {"w": "孟享(帝王宗庙祭礼因于每年的四孟(孟春、孟夏、孟秋、孟冬)举行,故称)", "t": ""}]}, {"meaning": "假借为“猛”。威猛。", "cites": [{"t": "孟行以过其情,以遇其主矣。", "b": "《管子·任法》"}]}, {"meaning": "民众。", "cites": [{"t": "昔宾孟之蔽者,乱家是也。", "b": "《荀子·解蔽》"}]}, {"meaning": "姓。孟尝(齐国贵族,姓田名文;春申,楚国人,姓黄名歇。他们同赵国的平原君和魏国的信陵君都是当时仅次于国君的当政者,被称赤“战国四君子”)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1317wx','陋','1','lòu','阝','8','','[{"pinyin": "lòu", "defs": [{"meaning": "(形声。本义:狭窄,狭小)。"}, {"meaning": "同本义。", "cites": [{"t": "陋,阨陕也。", "b": "《说文》"}, {"t": "百盖无筑,千聚无社,谓之陋。", "b": "《管子·侈靡》"}, {"t": "生于辟陋之国。", "b": "《淮南子·修务》"}, {"t": "淩恒山其若陋兮。", "b": "《楚辞·自悲》"}, {"t": "莒恃其陋,而不修城郭。", "b": "《左传》"}, {"t": "在陋巷,人不堪其忧,回也不改其乐。", "b": "《论语》"}], "words": [{"w": "陋巷蓬门", "t": "穷苦人的住处。狭巷草编门。"}]}, {"meaning": "简陋。", "cites": [{"t": "何陋之有。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "陋宇", "t": "简陋的房屋"}, {"w": "陋室;朴陋", "t": "朴素简陋"}, {"w": "粗陋", "t": "粗糙简陋"}, {"w": "简陋", "t": "房屋、设备等简单粗陋;不完备。"}]}, {"meaning": "知识浅薄。", "cites": [{"t": "少见曰陋。", "b": "《荀子·修身》"}, {"t": "辞令就得谓之雅,反雅谓之陋。", "b": "《贾子道术》"}, {"t": "而陋者乃以斧斤考击而求之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "浅陋", "t": "见识贫乏"}, {"w": "固陋", "t": "见闻不广"}, {"w": "鄙陋", "t": "见识浅薄"}, {"w": "陋儒", "t": "学识浅薄的读书人"}, {"w": "陋质末才", "t": "学识浅薄"}, {"w": "陋拙", "t": "浅陋拙笨,多用于自谦。"}]}, {"meaning": "偏僻;边远。", "cites": [{"t": "今使人生于辟陋之国。", "b": "《淮南子·修务》"}], "words": [{"w": "陋夷", "t": "古时对异族的蔑称"}, {"w": "僻陋", "t": "地区偏僻荒凉。"}]}, {"meaning": "粗劣。", "cites": [{"t": "衣裘器服,皆择其陋者。", "b": "《宋书·孔觊传》"}]}, {"meaning": "粗俗,野鄙。", "cites": [{"t": "固陋之心终不能移。", "b": "徐光启《甘薯疏序》"}], "words": [{"w": "陋俗", "t": ""}]}, {"meaning": "不好看,丑。", "cites": [{"t": "杞貌陋而色如蓝,人皆鬼视之。", "b": "张昭远《旧唐书》"}], "words": [{"w": "丑陋", "t": "相貌难看。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1318wx','陌','1','mò bǎi','阝','8','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从阜(fù),百声。阜,土山,与地形有关。本义:田间小路)。"}, {"meaning": "田间东西方向的小路。也泛指田间小路。", "cites": [{"t": "为田开阡陌封疆,而赋税平。", "b": "《史记·商君列传》"}, {"t": "阡陌交通,鸡犬相闻。", "b": "陶渊明《桃花源记》"}], "words": [{"w": "南陌", "t": "南方的田间小路"}, {"w": "陌路", "t": "田间的小路"}, {"w": "陌头", "t": "路旁。"}]}, {"meaning": "泛指道路。", "cites": [{"t": "素骥鸣广陌,慷慨送我行。", "b": "陶潜《咏荆轲》"}, {"t": "越陌度阡,枉用相存。", "b": "曹操《短歌行》"}], "words": [{"w": "陌头杨柳", "t": ""}]}, {"meaning": "田野。", "cites": [{"t": "蹑足行伍之间,而倔起阡陌之中。", "b": "贾谊《过秦论》"}]}, {"meaning": "街道。", "cites": [{"t": "寻常巷陌,人道寄奴曾住。", "b": "辛弃疾《永遇乐·京口北固亭怀古》"}]}, {"meaning": "用于钱,指一百文。", "cites": [{"t": "又官库出纳缗钱,皆以八十为陌。", "b": "《旧五代史·王章传》"}, {"t": "三分天下犹嫌小,一陌黄钱值几文?", "b": "《蠖斋诗话》"}, {"t": "张氏早使敬济拿五两银子,几陌金银钱纸,往门外与长老,替他父亲念经。", "b": "《金瓶梅词话》"}]}, {"meaning": "用于旧时祭奠所烧的纸钱,约相当于“叠”。", "cites": [{"t": "烧不了的纸钱,与窦娥烧一陌儿。", "b": "关汉卿《窦娥冤》"}], "words": [{"w": "陌钱", "t": "纸钱。"}]}]}, {"pinyin": "bǎi", "defs": [{"meaning": "", "cites": [{"t": "与窦娥一陌八。", "b": "关汉卿《窦娥冤》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1319wx','孤','1','gū','子','8','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从子,瓜声。本义:幼年丧父,即孤儿)。"}, {"meaning": "同本义。", "cites": [{"t": "孤,无父也。", "b": "《说文》"}, {"t": "如孤子。", "b": "《礼记·深衣》。注:“三十以下无父称孤。”"}, {"t": "司民协孤终。", "b": "《国语·周语》"}, {"t": "少伶俜而偏孤兮。", "b": "潘岳《寡妇赋》"}, {"t": "老而无子曰独,幼儿无父曰孤。", "b": "《孟子·梁惠王下》"}, {"t": "救灾患,宥孤寡。", "b": "《左传·昭公十四年》"}, {"t": "备答曰:“刘荆州临亡,讬我以遗孤,背信自济,吾所不为,死何面目见刘荆州乎?", "b": "孔衍《汉魏春秋》"}]}, {"meaning": "古代王侯的自称。", "cites": [{"t": "君名孤寡。", "b": "《吕氏春秋·君守》。注:“人君谦称。”"}, {"t": "凡人有此一德者,足以南面称孤矣。", "b": "《庄子·盗跖》"}, {"t": "虽贵必以贱为本,虽高必以下为基,是以侯王称孤寡不穀。", "b": "《战国策·齐策》"}, {"t": "诸人持议,甚失孤望。", "b": "《资治通鉴》"}], "words": [{"w": "称孤道寡;孤家", "t": "古代君王、诸候的自称。"}]}, {"meaning": "单独;孤独。", "cites": [{"t": "孤,独也。", "b": "《广雅·释诂三》"}, {"t": "君名孤寡。", "b": "《吕氏春秋·君守》"}, {"t": "且燕赵处秦革灭殆尽之际,可谓智力孤危。", "b": "宋·苏洵《六国论》"}, {"t": "大漠孤烟直,长河落日圆。", "b": "唐·王维《使至塞上》"}, {"t": "以区区百人,投身大敌,与之扑斗,何异以孤羊投群狼?", "b": "《清稗类钞·战事类"}], "words": [{"w": "孤冷", "t": "孤独冷清"}, {"w": "孤孤恓恓", "t": "孤独恓惶"}, {"w": "孤恓", "t": "孤独不安"}, {"w": "孤桩桩", "t": "孤零零站着"}, {"w": "孤贫", "t": "孤独穷困。"}]}, {"meaning": "孤高。", "cites": [{"t": "孤怀吐明月,众毁铄黄金。", "b": "唐·孟郊《连州吟》"}], "words": [{"w": "孤风", "t": "孤高的风度、品格"}, {"w": "孤直", "t": "孤高耿直"}, {"w": "孤特", "t": "孤高;特出"}, {"w": "孤梗", "t": "孤高刚直"}, {"w": "孤逸", "t": "孤高洒脱"}, {"w": "孤清", "t": "孤高而清静。"}]}, {"meaning": "独特。", "cites": [{"t": "清词孤韵有歌响,击触钟磬鸣环珂。", "b": "唐·李商隐《安平公》"}], "words": [{"w": "孤音", "t": "独特的音律;孤独的声音"}, {"w": "孤艳", "t": "指独秀的花"}, {"w": "孤韵", "t": "独特的风格;超凡的韵律"}, {"w": "孤怀", "t": "孤高的情操。"}]}, {"meaning": "负,负恩,背弃恩德。", "cites": [{"t": "孤,负也。毛曰:凡孤负之孤当作孤。俗作辜,非。", "b": "《良熙字典》"}, {"t": "陵虽孤恩,汉亦负德。", "b": "汉·李陵《答苏武书》"}, {"t": "孤负陵心区区之意。", "b": ""}, {"t": "孤负重恩,衔恨黄泉。", "b": "《后汉书·光武十王传》"}, {"t": "终无纯固之节,必有孤负之心。", "b": "《魏书·袁翻传》"}], "words": [{"w": "孤恩", "t": "负恩,背弃恩德。"}]}, {"meaning": "狐立于。", "cites": [{"t": "是以主孤于上而臣党于下。", "b": "《韩非子·奸劫弑臣》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1320wx','陕','1','shǎn','阝','8','','[{"pinyin": "shǎn", "defs": [{"meaning": "古地名。战国陕邑,在今河南省陕县。", "cites": [{"t": "自陕而东者,周公主之;自陕而西者,召公主之。", "b": "《公羊传》"}]}, {"meaning": "中国陕西省的简称。"}, {"meaning": "狭窄。", "cites": [{"t": "是故溪陕者速涸(hé,干)。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1321wx','降','1','jiàng xiáng','阝','8','','[{"pinyin": "jiàng", "defs": [{"meaning": "(会意)。"}, {"meaning": "同本义,与“陟”相对。", "cites": [{"t": "降,下也。", "b": "《说文》"}, {"t": "是降丘宅土。", "b": "《书·禹贡》"}, {"t": "复降在原。", "b": "《诗·大雅·公刘》"}, {"t": "维岳降神。", "b": "《诗·大雅·崧高》"}, {"t": "降西阶一等。", "b": "《仪礼·士冠礼》"}, {"t": "子余使公子降拜曰。", "b": "《国语·晋语》"}], "words": [{"w": "降阶", "t": "走下台阶"}, {"w": "降格", "t": "从上而至。即降临。格,至"}, {"w": "降辇", "t": "帝王下车"}, {"w": "降拜", "t": "下堂拜宾"}, {"w": "降真", "t": "降临的神灵"}, {"w": "降饯", "t": "高贵人物屈尊赴宴"}, {"w": "降驾", "t": "帝王临幸"}, {"w": "降坛诗", "t": "扶乩时鬼神降临祭坛所题的诗。"}]}, {"meaning": "贬抑;降低。", "cites": [{"t": "若有故为,当加降黜。", "b": "《资治通鉴》"}, {"t": "稍降辞色。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "降调", "t": "降职调动"}, {"w": "降处外任", "t": "将京官降职外放为地方官"}, {"w": "降尊", "t": "降低尊贵的身分"}, {"w": "降除", "t": "降职"}, {"w": "降发", "t": "降职发落"}, {"w": "降贬", "t": "降官贬职"}, {"w": "降革", "t": "降级免职。"}]}, {"meaning": "下落,落下。从高往低掉。", "cites": [{"t": "降,落也。", "b": "《尔雅》"}, {"t": "羽鸟曰降。", "b": "《礼记·曲礼》"}, {"t": "大寒降。", "b": "《国语·鲁语》"}, {"t": "若时雨之降,莫不说喜。", "b": "《荀子·议兵》"}, {"t": "降大任于是人。", "b": "《孟子·告子下》"}, {"t": "休祲降于天。", "b": ""}, {"t": "天降大雨。", "b": "《广东军务记》"}], "words": [{"w": "降液", "t": "对天降雨露的敬称"}, {"w": "升降;降落;递降;骤降;降雨;沉降; 空降", "t": ""}]}, {"meaning": "诞生;降生。", "cites": [{"t": "汤降不迟。", "b": "《诗·商颂·长发》"}, {"t": "釐降二女于妫汭。", "b": "《书·尧典》"}, {"t": "惟庚寅吾以降。", "b": "《楚辞·离骚》"}, {"t": "不拘一格降人材。", "b": "龚自珍《己亥杂诗》"}], "words": [{"w": "降精", "t": "生下良马"}, {"w": "降诞", "t": "降生,诞生。"}]}, {"meaning": "赐给;给予。", "cites": [{"t": "无坠天之降宝命。", "b": "《书·金滕》"}], "words": [{"w": "降锡", "t": "赐给"}, {"w": "降德", "t": "赐予恩惠"}, {"w": "降祥", "t": "降下吉祥"}, {"w": "降福;降诏", "t": ""}]}]}, {"pinyin": "xiáng", "defs": [{"meaning": "投降。", "cites": [{"t": "曷为不言降。", "b": "《公羊传》。注:“降者自优之文。”"}, {"t": "每得降卒。", "b": "《资治通鉴·唐纪》"}, {"t": "琮已降。", "b": "《资治通鉴》"}, {"t": "诈云欲降", "b": ""}, {"t": "指言盖降", "b": ""}], "words": [{"w": "降附", "t": "投降归附"}, {"w": "降骨", "t": "投降者的骨骸。"}]}, {"meaning": "降服,使驯服。", "cites": [{"t": "六卿三族,降听政也。", "b": "《左传·哀公二十六年》。注:“和同也。”"}, {"t": "其能降以相从也。", "b": "《左传·隐公十一年》。注:“降,降心也。”"}, {"t": "降虏兼千帐,居人有万家。", "b": "唐·杜甫《秦州杂诗二十首》"}, {"t": "[太公]又与了我五钱银子做盘缠,教我再去请好法师降他。", "b": "《西游记》"}], "words": [{"w": "降发", "t": "降伏;制伏"}, {"w": "降视", "t": "降伏"}, {"w": "降龙", "t": "以佛法降伏神龙。"}]}, {"meaning": "欢悦,快乐。", "cites": [{"t": "亦既覯止,我心则降。", "b": "《诗·召南·草虫》"}]}, {"meaning": "详细。", "cites": [{"t": "则俺那官人要个明降。", "b": "元·孟汉卿《魔合罗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1322wx','函','1','hán','凵','8','','[{"pinyin": "hán", "defs": [{"meaning": "(象形。今隶误作函。本义:舌)。"}, {"meaning": "同本义。", "cites": [{"t": "圅,舌也。", "b": "《说文》"}, {"t": "若合而函吾中。", "b": "《国语·楚语》。注:“入也。”按,如舌之在口中也。"}, {"t": "口上曰臄,口下曰圅。", "b": "《通俗文》"}, {"t": "噱,圅舌也。", "b": "《广雅·释亲》"}]}, {"meaning": "盛物的匣子、套子。", "cites": [{"t": "函封之。", "b": "《战国策·燕策》"}, {"t": "函封。", "b": ""}, {"t": "买五人之脰而函之。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "剑函;镜函", "t": ""}]}, {"meaning": "信封。", "cites": [{"t": "发函伸纸,…。", "b": "《文选·吴质·答东阿王书》"}]}, {"meaning": "铠甲。", "cites": [{"t": "函,铠也。", "b": "《广雅》"}], "words": [{"w": "函人", "t": "制造铠甲的工人。"}]}, {"meaning": "包含;容纳。", "cites": [{"t": "席间函丈。", "b": "《礼记·曲礼》。注:“容也。”"}, {"t": "夫函牛之鼎沸。", "b": "《淮南子·诠言》。注:“受一牛之鼎也。”"}, {"t": "以函夏之大汉兮。", "b": "《汉书·扬雄传》。注:“包容也。”"}, {"t": "函之如海。", "b": "《汉书·叙传》。注:“读与含同。”"}, {"t": "臣蜯函珠。", "b": "张衡《南都赋》"}], "words": [{"w": "函夏", "t": "包函诸夏。意指中国全部"}, {"w": "函括", "t": "包含,包括"}, {"w": "函盖", "t": "包含;概括。"}]}, {"meaning": "用匣子或封套装盛。", "cites": [{"t": "函梁君臣之首。", "b": "宋·欧阳修《新五代史·伶官传》"}], "words": [{"w": "函匣", "t": "谓置物于匣中"}, {"w": "函封", "t": "用匣子盛而封之"}, {"w": "函首", "t": "用匣子装盛人头。"}]}, {"meaning": "陷入。", "cites": [{"t": "若合而函吾中,吾上下必败其左右。", "b": "《国语·楚语上》"}]}, {"meaning": "宽阔。", "cites": [{"t": "伊兹都之函宏。", "b": "左思《吴都赋》。注:“宽大也。”"}], "words": [{"w": "函弘", "t": "广大。弘,或作宏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1323wx','限','1','xiàn','阝','8','','[{"pinyin": "xiàn", "defs": [{"meaning": "(形声。从阜,艮(gèn)声。阜,土山,与山势有关。本义:阻隔)。"}, {"meaning": "同本义。", "cites": [{"t": "限,阻也。", "b": "《说文》"}, {"t": "限之以大故。", "b": "《楚辞·怀沙》"}, {"t": "牵牛织女遥相望,尔独何辜限河梁。", "b": "三国魏·曹丕《燕歌行》"}], "words": [{"w": "限绝", "t": "隔绝"}, {"w": "限隔", "t": "阻隔;隔绝"}, {"w": "限带", "t": "阻隔围绕"}, {"w": "限难", "t": "阻难。"}]}, {"meaning": "限制;限定。", "cites": [{"t": "是身如浮云,安可限南北。", "b": "杜甫《别赞上人》"}], "words": [{"w": "限状", "t": "限期完成公务的文书。"}]}, {"meaning": "险阻。", "cites": [{"t": "南有巫山,黔中之限。", "b": "《战国策》"}]}, {"meaning": "限期。", "cites": [{"t": "限六日内交。", "b": "《广东军务记》"}, {"t": "不可限以时月。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "留待限期。", "b": "《聊斋志异·促织》"}, {"t": "严限追比。", "b": ""}], "words": [{"w": "限次", "t": "期限"}, {"w": "限尽", "t": "寿命到了期限"}, {"w": "限外", "t": "逾期。"}]}, {"meaning": "界限、边界、分界线(如领土、运动场所、田地等)。", "cites": [{"t": "限,界也。", "b": "《小尔雅》"}, {"t": "长城之限。", "b": "清·姚鼐《惜抱轩诗文集·登泰山记》"}], "words": [{"w": "东限琅琊台", "t": ""}]}, {"meaning": "限度,止境。", "cites": [{"t": "心中无限事。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "地有限。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "权限", "t": "职权范围"}, {"w": "宽限", "t": "放宽限期"}, {"w": "极限;上限;下限;限级", "t": "限度等级。"}]}, {"meaning": "门槛。", "cites": [{"t": "限,一日门榍。", "b": "《说文》"}, {"t": "限阈也。", "b": "《玉篇》"}], "words": [{"w": "锯断城门限", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1324wx','妹','1','mèi','女','8','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。从女,未声。本义:妹妹)。"}, {"meaning": "称同父母或同父异母或同母异父比自己年纪小的女子。", "cites": [{"t": "妹,女弟也。", "b": "《说文》"}, {"t": "及姑姊妹。", "b": "《左传·襄公十二年》"}, {"t": "妹者,少女之称也。", "b": "《易·归妹》注"}, {"t": "东宫之妹,邢侯之姨。", "b": "《诗·卫风·硕人》"}], "words": [{"w": "妹妹;妹丈", "t": "妹妹的丈夫"}, {"w": "妹婿", "t": "妹夫。"}]}, {"meaning": "古邑 。在今河南省淇县。"}, {"meaning": "昏暗不明。", "cites": [{"t": "而弃妹之者,不仁也。", "b": "《庄子·天道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1325wx','姑','1','gū','女','8','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从女,古声。本义:丈夫的母亲)。"}, {"meaning": "同本义。", "cites": [{"t": "姑,夫母也。", "b": "《说文》"}, {"t": "姑在则曰君姑,姑殁则曰先姑。又,妇谓夫之庶母为少姑。", "b": "《尔雅》"}, {"t": "如母而非母也,姑也。", "b": "《白虎通》"}, {"t": "既而将诉于舅姑;舅姑(公婆)爱其子,不能御。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "翁姑;姑嫜", "t": "古时妻子对丈夫父母的称呼,即公婆。"}]}, {"meaning": "父亲的姐妹。", "cites": [{"t": "父之姊妹为姑。", "b": "《尔雅》"}, {"t": "问我诸姑。", "b": "《诗·邶风·泉水》"}, {"t": "姪其从姑。", "b": "《左传·僖公十五年》"}], "words": [{"w": "姑舅", "t": "姑母和舅父"}, {"w": "姑姊", "t": "父之姐"}, {"w": "姑姑;姑婿", "t": ""}]}, {"meaning": "丈夫的姐妹。", "cites": [{"t": "新妇初来时,小姑始扶床。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "姑嫂;小姑", "t": "丈夫的妹妹。"}]}, {"meaning": "姑且,暂且。", "cites": [{"t": "今姑贷汝,后不善自改,且复妄言,我当焚汝庐。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "姑置勿论", "t": ""}]}, {"meaning": "(gǔ)。诂训。以通行的文字解释古代语言文字或方言字义。", "cites": [{"t": "姑形以形,以形务名。", "b": "《管子·心术》"}]}, {"meaning": "吸饮。", "cites": [{"t": "狐狸食之,蝇蚋姑嘬之。", "b": "《孟子·滕文公上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1326wx','姐','1','jiě','女','8','','[{"pinyin": "jiě", "defs": [{"meaning": "(形声。从女,且声。本义:母亲的别称)。"}, {"meaning": "女兄。同父母或只同父或同母;年龄比自己大的女子。", "cites": [{"t": "近世多以女兄为姐,盖尊之也。", "b": "吴曾《能改斋漫录》"}], "words": [{"w": "大姐;二姐;姐妹;姐弟", "t": ""}]}, {"meaning": "指妓女。", "cites": [{"t": "常言“姐爱俏,鸨爱钞。”", "b": "《警世通言》"}], "words": [{"w": "姐姐", "t": "称妓女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1327wx','姓','1','xìng','女','8','','[{"pinyin": "xìng", "defs": [{"meaning": "(会意兼形声。从女,从生,生亦声。本义:标志家族系统的字)。"}, {"meaning": "同本义。", "cites": [{"t": "姓,人所生也。", "b": "《说文》"}, {"t": "左氏传曰:天子建德,因生以赐姓。", "b": "《春秋·隐公八年》。按,神农母居姜水,黄帝母居姬水,舜母居姚虚,因以为姓。故从女生。"}, {"t": "赐姓刘氏,拜为郎中。", "b": "《史记·刘敬叔孙通列传》"}, {"t": "世为著姓。", "b": "《后汉书·张衡传》"}, {"t": "姓者,统其祖考之所自出,氏者,别其子孙之所自分。", "b": "刘恕《通鉴外纪》"}], "words": [{"w": "姓族", "t": "大族,望族"}, {"w": "姓字", "t": "姓氏和名字"}, {"w": "姓系", "t": "姓氏家族的源流系统"}, {"w": "姓第", "t": "姓氏行第。"}]}, {"meaning": "命,性命。", "cites": [{"t": "救民之姓而不夸,行补三君而不有。", "b": "《晏子春秋》"}]}, {"meaning": "官吏。", "cites": [{"t": "百姓兆民。", "b": "《国语》。韦昭注:“百姓,百官。”"}]}, {"meaning": "平民。", "cites": [{"t": "填国家,抚百姓。", "b": "《汉书》"}]}, {"meaning": "子孙的通称。", "cites": [{"t": "问其姓,对曰:“余子长矣,能奉雉而从我矣。”", "b": "《左传》"}]}, {"meaning": "命名,称呼。", "cites": [{"t": "项氏世世为楚将,封于项,故姓项氏。", "b": "《史记·项羽本纪》"}, {"t": "或曰,冉氏尝居也,故姓是溪曰冉溪。", "b": "唐·柳宗元《愚溪诗序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1328wx','妮','1','nī','女','8','','[{"pinyin": "nī", "defs": [{"meaning": "(形声。从女,尼声。本义:婢女,侍候主人的女孩子)。"}, {"meaning": "同本义。", "cites": [{"t": "今又谓婢曰妮。", "b": "《六书政》"}, {"t": "吾有梳头妮子。", "b": "《新五代史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1329wx','始','1','shǐ','女','8','','[{"pinyin": "shǐ", "defs": [{"meaning": "(形声。从女,台声。本义:开头,开始)。"}, {"meaning": "同本义。与“终”相对。", "cites": [{"t": "始,女之初也。", "b": "《说文》。朱曰:“裁衣之始为初,草木之始为才,人身之始为首为元,筑墙之始为基,开户之始为戽,子孙之始为祖,形生之始为胎。”"}, {"t": "无名天地之始。", "b": "《老子》。注:“始者,道本也。”"}, {"t": "始求深也。", "b": "《易·恒》。虞注:“乾为始。”"}, {"t": "君子慎始。", "b": "《礼记·经解》"}, {"t": "礼始于冠。", "b": "《礼记·昏义》。注:“犹根也。”"}, {"t": "天地者,生之始也。", "b": "《荀子·王制》"}, {"t": "忧懈怠则思慎始而敬终。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "始缢即气绝。", "b": "方苞《狱中杂记》"}, {"t": "始于文艺中兴时代之意大利。", "b": "蔡元培《图画》"}], "words": [{"w": "始卒", "t": "开始和终止"}, {"w": "始室", "t": "始娶的妻子,元配夫人"}, {"w": "始基", "t": "初立的基业"}, {"w": "自始至终", "t": ""}]}, {"meaning": "过去,从前。", "cites": [{"t": "公侯之子孙,必复其始。", "b": "《左传》"}]}, {"meaning": "根本,本源。", "cites": [{"t": "坚树在始。", "b": "《国语》。韦昭注:“始,根本也。”"}]}, {"meaning": "当初,在最初的时候。", "cites": [{"t": "其始太医以王命聚之,岁赋其二。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "庭中始为篱,已为墙,凡再变矣。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "始春", "t": "立春日。二十四节气之一"}, {"w": "始愿", "t": "最初的志愿"}, {"w": "欲善终,应善始;始初", "t": "开始,起初"}, {"w": "始闻其语", "t": "当初听到他的话。"}]}, {"meaning": "曾,尝。", "cites": [{"t": "以为凡是州之山水有异态者,皆我有也;而未始知西山之怪特。", "b": "柳宗元《始得西山宴游记》"}]}, {"meaning": "刚刚;才。", "cites": [{"t": "至丹以荆卿为计,始速祸焉。", "b": "宋·苏洵《六国论》"}, {"t": "千呼万唤始出来,犹抱琵琶半遮面。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "始适还家门。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "千呼万唤始出来", "t": ""}]}, {"meaning": "然后;随之;立刻就。", "cites": [{"t": "母亲良氏,素有阴虚之症,服药即吐,惟以海参煮食,始能稍安。", "b": "《镜花缘》"}]}, {"meaning": "仅仅,只。", "cites": [{"t": "访古始及平台间。", "b": "唐·李白《梁园吟》"}]}, {"meaning": "谋划。", "cites": [{"t": "爰始爰谋,爰契我龟。", "b": "《诗·大雅·緜》。马瑞辰通释:“始亦谋也。爰始爰谋,犹言是究是图也。”"}]}, {"meaning": "滋生。", "cites": [{"t": "君子念始之者也。", "b": "《礼记》。郑玄注:“始,犹生也。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1330wx','姆','1','mǔ mā','女','8','','[{"pinyin": "mǔ", "defs": [{"meaning": "(形声。从女,母声。本义:中国古代教育未出嫁女子的妇人)。"}, {"meaning": "同本义。", "cites": [{"t": "娒,女师也。", "b": "《说文》"}, {"t": "姆纚笄宵衣在其右。", "b": "《仪礼·士昏礼》。注:“姆,妇人年五十,无子,出而不复嫁,能以妇道教人者,若今时乳母。”"}, {"t": "姆教婉娩听从。", "b": "《礼记·内则》"}], "words": [{"w": "保姆", "t": "保母。受雇为人看孩子或干家务的妇女"}, {"w": "姆母", "t": "古时为人教育女子的妇人"}, {"w": "姆师", "t": "古时以妇道教育女子的女师"}, {"w": "姆训", "t": "女师的训诫"}, {"w": "姆教", "t": "女师传授妇道于女子。"}]}, {"meaning": "乳母。", "cites": [{"t": "姆抱幼子立侧。", "b": "韩愈《殿中少监马君墓志》"}]}]}, {"pinyin": "mā", "defs": [{"meaning": "[方言]母亲"}, {"meaning": "泛称跟母亲年龄相近的妇女"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1331wx','迢','1','tiáo','辶','8','','[{"pinyin": "tiáo", "defs": [{"meaning": "(形声。从辵(chuò),召声。本义:遥远)。"}, {"meaning": "同本义。", "cites": [{"t": "旷瞻迢递。", "b": "《文选·左思·吴都赋》。刘注:“迢递,远貌。”"}], "words": [{"w": " 千里迢迢;夜迢迢;迢邈", "t": "遥远"}, {"w": "迢渺", "t": "遥远渺茫。"}]}, {"meaning": "高貌,高峻貌 。", "words": [{"w": "迢递", "t": "高峻的样子"}, {"w": "迢越", "t": "高远的样子"}, {"w": "迢峣", "t": "高大的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1332wx','驾','1','jià','马','8','','[{"pinyin": "jià", "defs": [{"meaning": "(形声。从马,加声。本义:以轭加于马上)。"}, {"meaning": "同本义。", "cites": [{"t": "驾,马在轭中。", "b": "《说文》"}, {"t": "其乱至矣,不可以驾矣。", "b": "《吕氏春秋·贵因》"}, {"t": "驾言兮焉求。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "驾御", "t": "驾驭。驾驶车马;引申为驱驶、控制。"}]}, {"meaning": "把鞍加在马背上。", "cites": [{"t": "一马驾一鞍,一女驾一男。", "b": "明·陈罴《跃鲤记》"}]}, {"meaning": "骑;乘。", "cites": [{"t": "驾,乘也。", "b": "《广雅》"}, {"t": "郤献子闻之,驾往救之。", "b": "《韩非子·难一》"}], "words": [{"w": "驾士", "t": "导引皇帝坐车的人"}, {"w": "驾龙", "t": "仙道乘龙飞行"}, {"w": "驾跨", "t": "骑乘"}, {"w": "驾鹤西游", "t": "死的婉称。"}]}, {"meaning": "操纵;驾驶。", "cites": [{"t": "晓驾炭车辗冰辙。", "b": "唐·白居易《卖炭翁》"}, {"t": "驾而宿于朝房。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "驾飞机;驾轮船;驾着一叶舟;驾长", "t": "船长;对船主的尊称"}, {"w": "驾娘", "t": "划船的女子;女船工。"}]}, {"meaning": "用胳膊支撑。", "cites": [{"t": "驾着鹰雕。", "b": "《武王伐纣平话》"}], "words": [{"w": "驾鹰走犬", "t": "带上鹰犬"}, {"w": "驾祸害人", "t": "制造祸端,加害他人"}, {"w": "驾景朝元", "t": "魂归天上。"}]}, {"meaning": "抵挡。", "cites": [{"t": "见那乱竹篙打来,两只手一驾,早抢了五六条在手里。", "b": "《水浒传》"}]}, {"meaning": "凌驾;超越。", "cites": [{"t": "驾,凌也。", "b": "《小尔雅》"}, {"t": "犹诈晋而驾焉。", "b": "《左传·昭公元年》"}, {"t": "其乱至矣,不可以驾矣。", "b": "《吕氏春秋·贵国》"}], "words": [{"w": "驾车夫", "t": "陵驾,超越"}, {"w": "驾凌", "t": "凌驾"}, {"w": "驾俗", "t": "超俗。"}]}, {"meaning": "传布。", "cites": [{"t": "仲尼驾说者也。", "b": "《法言·学行》。注:“传也。”"}], "words": [{"w": "驾说", "t": "传布学说。"}]}, {"meaning": "车子,或帝王车乘的总称。", "cites": [{"t": "为之驾。", "b": "《战国策·齐策四》"}], "words": [{"w": "驾部", "t": "官名。掌舆辇、传乘、邮驿、厩牧之事"}, {"w": "驾头", "t": "宋代帝王车驾出行时,仪仗队名目之一"}, {"w": "驾被", "t": "车马的饰物。"}]}, {"meaning": "马拉车走一天叫一驾。", "cites": [{"t": "驽马十驾。", "b": "《荀子·劝学》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1333wx','叁','1','sān','厶','8','','[{"pinyin": "sān", "defs": [{"meaning": "\\"三\\"的大写。", "cites": [{"t": "參，三也。--《广雅》", "b": ""}, {"t": "參天两地而倚数。--《易·说卦》。虞注：”參，三也。”", "b": ""}, {"t": "大都不过參国之一。--《左传·隐公元年》。注：“三分国城之一。”", "b": ""}, {"t": "參伍以变。--《易·系辞上》。疏：“參，三也。”", "b": ""}, {"t": "志以发言，言以出信，信以立志，參以定之。--《左传·襄公二十七年》。注：“志言行三者具，而后身安存。”", "b": ""}, {"t": "天有其时，地有其财，人有其治，夫是之谓能參。--《荀子·天论》。注：“人能治在时地财而用之，则是參于天地。”", "b": ""}, {"t": "參天地而独立兮。--《汉书·杨雄传上》。师古曰：“參之言三也。”", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1334wx','参','1','cān cēn sān shēn','厶','8','','[{"pinyin": "cān", "defs": [{"meaning": "(本义见shēn音)。"}, {"meaning": "加入。", "cites": [{"t": "参水浸于盂内。", "b": "宋应星《天工开物》"}], "words": [{"w": "参选", "t": "参加选拔"}, {"w": "参纂", "t": "参加编纂。"}]}, {"meaning": "参与(亦作“参予”“参豫”。预闻而参议其事)。", "cites": [{"t": "与之参国政。", "b": "《晋书·唐彬传》"}], "words": [{"w": "参决", "t": "参与决定计划"}, {"w": "参定", "t": "参与决定"}, {"w": "参事", "t": "参与计议国事。"}]}, {"meaning": "领悟;琢磨。", "cites": [{"t": "或者此时参悟了,也未可定。", "b": "《红楼梦》"}], "words": [{"w": "参悟", "t": "领悟"}, {"w": "参禅", "t": "佛教禅宗的修行方法。通过静心思虑,排除杂念来参悟佛教的“妙谛”。"}]}, {"meaning": "检验。", "cites": [{"t": "无参验而必之者,愚也。", "b": "《韩非子·显学》"}]}, {"meaning": "进见,拜见(以一定的礼节进见)。", "cites": [{"t": "拜了佛祖金身,参了罗汉。", "b": "《西游记》"}], "words": [{"w": "参承", "t": "参拜侍候。表示恭敬"}, {"w": "参请", "t": "参拜请教。"}]}, {"meaning": "弹劾,封建时代指向皇帝告发官吏罪状。", "cites": [{"t": "他怕京官老爷们写信给御史参他。", "b": "《老残游记》"}], "words": [{"w": "参劾", "t": "纠弹官吏的失职"}, {"w": "参奏", "t": "向皇帝提出对官吏的弹劾。"}]}]}, {"pinyin": "cēn", "defs": []}, {"pinyin": "sān", "defs": [{"meaning": "即三。", "cites": [{"t": "参天两地而倚数。", "b": "《易·说卦》"}, {"t": "参分其辐之长而杀其一。", "b": "《迥礼·考工记·轮人》"}, {"t": "先王之制,大都不过参国之一,中五之一,小九之一。", "b": "《左传·隐公元年》"}, {"t": "参日而后能外天下。", "b": "《庄子·大宗师》"}, {"t": "君子博学而日参省乎己。", "b": "《荀子·劝学》"}, {"t": "参分天下,而有其二。", "b": "《后汉书·伏湛传》"}, {"t": "而勤思乎参天贰地。", "b": "《汉书·司马相如传下》。师吉曰:“地与己并天为三,是三天也。”"}, {"t": "将军气概与天参。", "b": "《三国演义》"}]}]}, {"pinyin": "shēn", "defs": [{"meaning": "星名,二十八宿之一。", "cites": [{"t": "迁实沈于大厦,主参。", "b": "《左传》"}], "words": [{"w": "参横月落", "t": "天快亮"}, {"w": "参井", "t": "参星与井星。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1335wx','艰','1','jiān','艮','8','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。表示与土有关,艮(gèn)声。本义:土难治理)。"}, {"meaning": "同本义。", "cites": [{"t": "艰,土难治也。", "b": "《说文》。段玉裁注:“引申之,凡难理皆曰艰。”"}]}, {"meaning": "艰难;困难。", "cites": [{"t": "艰,难也。", "b": "《尔雅》"}, {"t": "艰则无咎。", "b": "《易·大有》"}, {"t": "遗大投艰于朕身。", "b": "《书·大诰》"}, {"t": "固国之艰急是为。", "b": "《国语·鲁语》"}, {"t": "长太息以掩涕兮,哀民生之多艰。", "b": "《楚辞·离骚》"}, {"t": "艰其昏晨之往来。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "勤且艰若此。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "艰虞", "t": "艰难困苦"}, {"w": "艰屯", "t": "艰苦险阻"}, {"w": "艰患", "t": "艰难祸患"}, {"w": "艰急", "t": "困难"}, {"w": "艰深", "t": "艰难深奥,晦涩难解"}, {"w": "艰苦奋斗", "t": "以巨大的努力克服艰难困苦而进行"}, {"w": "艰苦朴素", "t": "不怕苦累、生活俭朴、不追求享受的态度和行为"}, {"w": "艰疚", "t": "忧困,苦难"}, {"w": "艰厄", "t": "艰阨。饥乏;困乏"}, {"w": "艰棘", "t": "困苦,危难。"}]}, {"meaning": "险恶,危难。", "cites": [{"t": "彼何人斯,其心孔艰。", "b": "《诗·小雅·何人斯》"}], "words": [{"w": "艰贞", "t": "指人处境艰危之时能守正不屈"}, {"w": "艰地", "t": "险境"}, {"w": "艰难", "t": "危险"}, {"w": "艰关", "t": "崎岖辗转,历尽千辛万苦。"}]}, {"meaning": "旧指父母之丧事。", "cites": [{"t": "又以居母艰去官。", "b": "王俭《褚渊碑文》"}], "words": [{"w": ":丁艰", "t": "父或母丧"}, {"w": "外艰", "t": "父丧"}, {"w": "内艰", "t": "母丧"}, {"w": "艰疚", "t": "丧亲之痛"}, {"w": "艰棘", "t": "亲丧"}, {"w": "艰酷", "t": "亲丧。亲亡为惨痛之事,故称。"}]}, {"meaning": "开发土地。", "cites": [{"t": "暨稷播,奏庶艰食鲜食。", "b": "《书·益稷》"}, {"t": "艰,土难治也。", "b": "《说文》。段玉裁注:“按许书无垦字,疑古艰即今垦字。”徐灏注:“段谓艰即古垦字,其说甚精。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1336wx','线','1','xiàn','纟','8','','[{"pinyin": "xiàn", "defs": [{"meaning": "(形声。从糸(mì),戔(jiān)声。本义:用棉麻丝毛等材料拈成的细缕)。"}, {"meaning": "同本义。", "cites": [{"t": "线,缕也。", "b": "《说文》。按古文从糸,泉声。"}, {"t": "中国不绝如线。", "b": "《公羊传·僖公四年》"}, {"t": "爱惜起东西来,连个线头儿都是好的。", "b": "《红楼梦》"}], "words": [{"w": "线儿提的", "t": "提线木偶。借指酒后失态,步法踉跄"}, {"w": "毛线;丝线;缝纫线", "t": ""}]}, {"meaning": "细长如线的东西。", "cites": [{"t": "天云一线。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "线溜", "t": "细长的山水。"}]}, {"meaning": "线索。", "cites": [{"t": "并多雇素暗夷语线民,假装济夷办艇,作为内应。", "b": "清·林则徐《焚剿夷船擒获汉奸折》"}], "words": [{"w": "线上的", "t": "同行"}, {"w": "明线;内线;暗线", "t": ""}]}, {"meaning": "记录边界、区域或等高线的标记。", "cites": [{"t": "唐人线画,流动如生。", "b": "鲁迅《书信集·致李桦》"}], "words": [{"w": "边线;中线;水线;防线;警戒线", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1337wx','练','1','liàn','纟','8','','[{"pinyin": "liàn", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,柬声。本义:把生丝煮熟;亦指把麻或织品煮得柔而洁白)。"}, {"meaning": "同本义。", "cites": [{"t": "练,湅缯也。", "b": "《说文》"}, {"t": "冬则练帛之中,足以为轻且煖。", "b": "《墨子·辞过》"}, {"t": "凡染,春暴练。", "b": "《周礼·染人》"}, {"t": "主练染,作采色。", "b": "《后汉书》"}], "words": [{"w": "练丝", "t": "未染色的熟丝。"}]}, {"meaning": "练习;操演。", "cites": [{"t": "练之禾定。", "b": "宋·胡仔《苕溪渔隐丛话》"}], "words": [{"w": "练阅", "t": "训练检阅"}, {"w": "练句", "t": "写作时斟酌遣词用句的工夫。也作炼句"}, {"w": "练字", "t": "写作时用字技巧的推敲琢磨。也作炼字。"}]}, {"meaning": "熔炼。", "cites": [{"t": "方士欲练以求奇药。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "练丹", "t": "炼丹。"}]}, {"meaning": "选择。", "cites": [{"t": "选士厉兵,简练俊杰。", "b": "《礼记·月令》。又如:练日(选择日期);练材(精选的优质材料);练择(精选)"}]}, {"meaning": "染。", "cites": [{"t": "白纱入缁,不练自黑。", "b": "王充《论衡》"}], "words": [{"w": "练肆", "t": "染坊。"}]}, {"meaning": "选择。", "cites": [{"t": "既不能昭练贤鄙。", "b": "《潜夫论·本政》"}]}, {"meaning": "洁白的熟绢。", "cites": [{"t": "使邓廖帅组甲三百被练三千,以侵吴。", "b": "《左传·襄公三年》"}, {"t": "文绣素练。", "b": "《墨子·节葬下》"}, {"t": "澄江静如练。", "b": "谢朓《晚登三山远望京邑》"}], "words": [{"w": "江白如练;练文", "t": "形容澄澈的波纹。有如柔软洁白的生丝。"}]}, {"meaning": "古代祭名。因古时于父母去世十三月时戴练冠祭于家庙而得名。", "cites": [{"t": "鲁大夫练而床,礼邪?", "b": "《荀子·子道》"}], "words": [{"w": "练主", "t": "丧礼小祥之祭时所立的神主,藏于祖庙以供奏祀"}, {"w": "练冠", "t": "丧祭所戴的冠"}, {"w": "练衣", "t": "丧祭时所穿的衣。"}]}, {"meaning": "水名 。在今广东省普宁县至潮阳县一带。"}, {"meaning": "链子。", "cites": [{"t": "如锁上练。", "b": "明·魏禧《大铁椎传》"}]}, {"meaning": "白,素色。", "cites": [{"t": "墨子见练丝而泣之,为其可以黄,可以墨。", "b": "《淮南子·说林训》"}], "words": [{"w": "练巾", "t": "白色的头巾"}, {"w": "练衣", "t": "白色布衣"}, {"w": "练文", "t": "比喻像白练飘动般的波纹。"}]}, {"meaning": "引申为经验多,精熟。", "cites": [{"t": "世事洞明皆学问,人情练达即文章。", "b": "《红楼梦》"}], "words": [{"w": "干练", "t": "又有才能又有经验"}, {"w": "练才", "t": "文才练达"}, {"w": "练甲", "t": "精兵。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1338wx','组','1','zǔ','纟','8','','[{"pinyin": "zǔ", "defs": [{"meaning": "(形声。从糸(mì),且(jǔ)声。与丝织品有关,故从糸。本义:具有文采的宽丝带。古代多用作佩印或佩玉的绶)。"}, {"meaning": "同本义。", "cites": [{"t": "组,绶属。其小者以为冠缨。", "b": "《说文》。按,织丝有文以为绶缨之用者也。阔者曰组,为带绶;狭者曰条,为冠缨。"}, {"t": "掌组。", "b": "《周礼·典丝》"}, {"t": "厥篚玄纁玑组。", "b": "《书·禹贡》"}, {"t": "织纴组紃。", "b": "《礼记·内则》"}, {"t": "系颈以组。", "b": "《汉书·高帝纪》"}, {"t": "仓皇展转,竟就死于尺组之下。", "b": "唐·陈鸿《长恨传》"}, {"t": "系燕父子以组。(组,这里指绳索。)", "b": "欧阳修《伶官传序》"}], "words": [{"w": "组帐", "t": "系以丝带的华丽帷帐"}, {"w": "组缨", "t": "系冠的丝带"}, {"w": "组紃", "t": "丝绳带"}, {"w": "组带", "t": "丝织系带"}, {"w": "组就", "t": "古代冕旒上彩色丝绳串。"}]}, {"meaning": "代指官印或官吏。", "cites": [{"t": "君长、敬通揭节垂组,自相署立。", "b": "《后汉书》"}, {"t": "鲁连让齐爵,遗组去邯郸。", "b": "唐·陈子昂《感遇诗三十八首》"}], "words": [{"w": "组绂", "t": "印绶。借指官位"}, {"w": "组绶", "t": "用以系印的丝带。借指官爵。"}]}, {"meaning": "编织。", "cites": [{"t": "有力如虎,执辔如组。", "b": "《诗·邶风》"}], "words": [{"w": "组练", "t": "组甲与被练;另指军容;绳索"}, {"w": "组甲", "t": "用线绳带联缀皮革或金属的甲片"}, {"w": "组缋", "t": "丝织品上的彩色刺绣或绘饰。"}]}, {"meaning": "华丽。", "cites": [{"t": "其服组,其容妇。其俗淫。", "b": "《荀子》"}], "words": [{"w": "组绣", "t": "华丽的丝绣服饰"}, {"w": "组丽", "t": "华丽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1339wx','绅','1','shēn','纟','8','','[{"pinyin": "shēn", "defs": [{"meaning": "(形声。从糸(mì),申声。本义:士大夫束在衣外的大带)。"}, {"meaning": "同本义。", "cites": [{"t": "绅,大带也。", "b": "《说文》"}, {"t": "绅,带也。", "b": "《广雅》。按,大带束腰,垂其余以为饰,谓之绅。"}, {"t": "绅长制士三尺,有司二尺有五寸。", "b": "《礼记·玉藻》"}, {"t": "衣裳所以必有绅带者,示敬谨自约整也。", "b": "《白虎通》"}, {"t": "端哔绅。", "b": "《礼记·内则》。注:“大带所以自绅约也。”"}, {"t": "峨大冠、拖长绅者,昂昂乎庙堂之器也。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "绅笏", "t": "大带与笏板"}, {"w": "绅带", "t": "古时士大夫束腰之大带"}, {"w": "绅緌", "t": "绅,大带;緌冠带之末端下垂部分。借指有官职的人"}, {"w": "绅冕", "t": "腰带和冠。借指士大夫。"}]}, {"meaning": "旧指地方上有地位权势的人物或他们所属的阶级。", "cites": [{"t": "缙绅、大夫、士萃于左丞相府,莫知计所出。", "b": "文天祥《指南录·后序》"}, {"t": "两家绅衿共一百四五十人,一同到祠堂口迎接当事。", "b": "《儒林外史》"}], "words": [{"w": "官绅;土豪劣绅;乡绅", "t": "指地方上有权势有地位的人"}, {"w": "绅宦", "t": "泛称官员"}, {"w": "绅民", "t": "绅士自称;绅士与民众"}, {"w": "绅商", "t": "绅士和商人"}, {"w": "绅董", "t": "绅士和董士"}, {"w": "绅衿", "t": "地方绅士和在学的人。"}]}, {"meaning": "束上带子,佩大带。", "cites": [{"t": "绅之束之。", "b": "《韩非子·外储》"}], "words": [{"w": "绅束", "t": "约束。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1340wx','细','1','xì','纟','8','','[{"pinyin": "xì", "defs": [{"meaning": "(形声。从系(mì),囟(xìn)声。系,细丝。本义:细小)。"}, {"meaning": "同本义。和“大”相对。", "cites": [{"t": "细,微也。", "b": "《说文》。按,细者,细之微也。"}, {"t": "细,小也。", "b": "《广雅》"}, {"t": "细人之爱人也以姑息。", "b": "《礼记·檀弓》"}, {"t": "细钧有钟无镈。", "b": "《国语·周语》"}, {"t": "此吾所谓君子明细而不明大也。", "b": "《墨子·天志中》"}, {"t": "不积细流。", "b": "《荀子·劝学》"}, {"t": "游鱼细石,直视无碍。", "b": "吴均《与朱元思书》"}, {"t": "斜风细雨。", "b": "唐·张志和《渔歌子》"}, {"t": "不知其细。", "b": "清·刘开《问说》"}], "words": [{"w": "细崽", "t": "细作;西崽"}, {"w": "细人", "t": "细作;姬妾"}, {"w": "细探人", "t": "多指军队中的探子"}, {"w": "细士", "t": "小人。"}]}, {"meaning": "纤细。和“粗”相对。", "cites": [{"t": "昔者楚灵王好士细要。", "b": "《墨子·兼爱中》"}, {"t": "细笔钩勒。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "细若蚊足。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "细腰", "t": "细要。纤细的腰身"}, {"w": "细娘家", "t": "指容貌美好的少女"}, {"w": "细袅袅", "t": "细而柔软的样子"}, {"w": "细毛", "t": "纤细的毛。"}]}, {"meaning": "精致,细密。", "cites": [{"t": "还是那年我和你拌嘴的那日起,叫上来做细活的。", "b": "《红楼梦》"}], "words": [{"w": "细欺雀舌", "t": "指上乘的茶叶"}, {"w": "细针密线", "t": "喻周密,周到"}, {"w": "细攒", "t": "密密聚集;精细镶嵌"}, {"w": "细果", "t": "精美点心。"}]}, {"meaning": "仔细,详细。", "cites": [{"t": "细瞻景状。", "b": "《聊斋志异·促织》"}, {"t": "细疏其能", "b": ""}, {"t": "大妈原是谢家的使唤丫头,至于怎么嫁给大伯的,却不知细情。", "b": "魏巍《东方》"}], "words": [{"w": "细罄", "t": "详细地说尽"}, {"w": "细事", "t": "详情;底细。"}]}, {"meaning": "细音,尖细的声音 的韵母,称为“细音”)。"}, {"meaning": "地位低微。", "cites": [{"t": "遂欲满求,不顾细民,非存之道。", "b": "《晏子春秋》"}], "words": [{"w": "细夫", "t": "小民"}, {"w": "细民", "t": "平民"}, {"w": "细婢", "t": "小婢。"}]}, {"meaning": "细微,轻微。", "cites": [{"t": "润物细无声。", "b": "唐·杜甫《春夜喜雨》"}]}, {"meaning": "旧称行为不高尚或地位低下的人。", "cites": [{"t": "臣主未宁于上,黔细未辑于下。", "b": "郭璞《省刑疏》"}]}, {"meaning": "指轻微的罪过。", "cites": [{"t": "狃于奸宄,败常乱俗,三细不宥。", "b": "《书·君陈》"}], "words": [{"w": "细行", "t": "小过;微服出行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1341wx','驶','1','shǐ','马','8','','[{"pinyin": "shǐ", "defs": [{"meaning": "(形声。从马,史声。本义:马行疾(快))。"}, {"meaning": "同本义。", "cites": [{"t": "[石崇]复问驭人牛所以驶。", "b": "刘义庆《世说新语·汰侈》"}], "words": [{"w": "甚驶", "t": "骑马跑得很快"}, {"w": "驶马", "t": "疾驰之马。"}]}, {"meaning": "疾速。", "cites": [{"t": "欲缓携手期,流年一何驶!", "b": "王维《赠从弟司库员外絿》"}], "words": [{"w": "驶流", "t": "湍急的水流"}, {"w": "驶风", "t": "疾风"}, {"w": "驶河", "t": "急流"}, {"w": "驶卒", "t": "急递的驿卒"}, {"w": "驶雨", "t": "急雨。"}]}, {"meaning": "使者。也作“使”。", "cites": [{"t": "某岁杪得承便驶,遣以环洒,故人千里之情蔼然可掬。", "b": "宋·文天祥《与颜县尉复古书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1342wx','织','1','zhī zhì','纟','8','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从糸(mì),埴(zhí)声。从“糸”,与丝织品有关。本义:织布,制作布帛的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "织,作布帛之总名也。", "b": "《说文》"}, {"t": "治丝曰织。织,绘也。", "b": "《尔雅》"}, {"t": "厥篚织贝。", "b": "《书·禹贡》。传:“细紵。”"}, {"t": "士不衣织。", "b": "《礼记·玉藻》。注:“染丝织之。”"}, {"t": "文织良货贿之物。", "b": "《周礼·玉府》。注:“文织画及绣锦。”"}, {"t": "妇人不织。", "b": "《韩非子·五蠹》"}, {"t": "木兰当户织。", "b": "《乐府诗集·木兰诗》"}, {"t": "一女不织。", "b": "汉·贾谊《论积贮疏》"}, {"t": "织纺井臼。", "b": "清·周容《芋老人传》"}], "words": [{"w": "织纸", "t": "纺织缝紝"}, {"w": "织紝", "t": "泛指织布。织是织布帛,紝是用以织布帛的丝线,也指织布帛的工人"}, {"w": "织造", "t": "织作绸、布、呢绒等之总称"}, {"w": "织花", "t": "用各种纱线、丝缕在织机上织成带有花纹的纺织品"}, {"w": "织帛", "t": "织作丝织品。"}]}, {"meaning": "编制,组成。", "cites": [{"t": "下展禽,置六关,妾织蒲,三不仁。", "b": "《孔子家语》"}], "words": [{"w": "织毛衣;织皮", "t": "兽毛织成的毛布或毛衣"}, {"w": "织金", "t": "交错金丝"}, {"w": "织罗", "t": "虚构情由,网罗入罪,以诬谄无辜的人;编织罗网。"}]}, {"meaning": "搜罗;收集。", "cites": [{"t": "要什么东西?顺便织来孝敬。", "b": "《红楼梦》"}]}, {"meaning": "布帛,织布机上的丝。", "cites": [{"t": "织生自蚕茧。", "b": "《后汉书·列女传》"}]}, {"meaning": "又。", "cites": [{"t": "今若断斯织。", "b": ""}, {"t": "何异断斯织。", "b": ""}]}]}, {"pinyin": "zhì", "defs": [{"meaning": "旗帜。", "cites": [{"t": "织文鸟章。", "b": "《诗·小雅·六月》"}, {"t": "望见单于城上立五采幡织。", "b": "《汉书·陈汤传》。颜师古云:“织,读曰帜。”"}, {"t": "旗织加其上。", "b": "《汉书·食货志下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1343wx','驹','1','jū','马','8','','[{"pinyin": "jū", "defs": [{"meaning": "(形声。从马,句声。本义:两岁以下的马)。"}, {"meaning": "同本义。", "cites": [{"t": "驹,马二岁曰驹。", "b": "《说文》"}, {"t": "老马反为驹。", "b": "《诗·角弓》"}, {"t": "执驹。", "b": "《周礼·校人》"}, {"t": "武帝谓之千里驹。", "b": "《汉书·刘德传》。注:“年齿幼少,故谓之驹。”"}, {"t": "夫马之为草驹之时。", "b": "《淮南子·脩务》"}], "words": [{"w": "驹儿隙", "t": "白驹过隙。比喻人生的短促"}, {"w": "驹阴", "t": "比喻易逝的光阴"}, {"w": "驹隙", "t": "比喻光阴容易消逝。"}]}, {"meaning": "泛指少壮的马。", "cites": [{"t": "言秣其驹。", "b": "《诗·汉广》。传:“五尺以上曰驹。”"}, {"t": "乘我乘驹。", "b": "《诗·株林》。笺:“六尺以下曰驹。”"}, {"t": "执腾驹。", "b": "《淮南子·时则》。注:“八尺以下曰驹。”"}, {"t": "我马维驹。", "b": "《诗·皇皇者华》"}], "words": [{"w": "驹龙", "t": "俊马"}, {"w": "驹騋", "t": "少壮、高大的马"}, {"w": "驹谷", "t": "散放在山谷中的马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1344wx','终','1','zhōng','纟','8','','[{"pinyin": "zhōng", "defs": [{"meaning": "(形声。从糸(mì),冬声。甲骨文字形,象一束丝,两头象结扎的末端。本义:把丝缠紧)。"}, {"meaning": "同本义。", "cites": [{"t": "终,絿丝也。", "b": "《说文》"}, {"t": "旋终在项。", "b": "《睡虎地秦墓竹简》"}]}, {"meaning": "终了;结束。与“始”相对。", "cites": [{"t": "终,极也;终,穷也。", "b": "《广雅》"}, {"t": "天禄永终。", "b": "《论语》"}, {"t": "君子以永终知敝。", "b": "《易·象下传》。虞注:“坤为永终。”"}, {"t": "终朝三拕之。", "b": "《易·讼》"}, {"t": "庶人终食。", "b": "《国语·周语》"}, {"t": "妇怨无终。", "b": "《左传·僖公二十四年》"}, {"t": "曲终收拨当心画,四弦一声如裂帛。", "b": "白居易《琵琶行》(并序)"}, {"t": "终继五国迁灭。", "b": "宋·苏洵《六国论》"}]}, {"meaning": "又。", "cites": [{"t": "用武而不终。", "b": ""}, {"t": "终亦不顾。", "b": "《徐霞客游记·游黄山记》"}, {"t": "不终岁。", "b": "《聊斋志异·促织》"}], "words": [{"w": "月终", "t": "月底"}, {"w": "年终", "t": "一年的末了"}, {"w": "始终", "t": "从开始到最后"}, {"w": "终服", "t": "父母之丧,服满三年。同终制"}, {"w": "终献", "t": "古代举行祀典时有三献之礼,第三次奠酒为终献"}, {"w": "终覆", "t": "复试结束。"}]}, {"meaning": "死。", "cites": [{"t": "愁苦而终穷。", "b": "《楚辞·屈原·涉江》"}, {"t": "未果,寻病终。", "b": "晋·陶渊明《桃花源记》"}, {"t": "终吾身而已。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "终誉", "t": "死后的声名"}, {"w": "终没", "t": "寿终"}, {"w": "终具", "t": "送终之具,指棺、槨等"}, {"w": "终服", "t": "终丧"}, {"w": "终丧", "t": "服满父母去世后三年之丧。"}]}, {"meaning": "完成。", "cites": [{"t": "羊子感其言,复还终业。", "b": "《后汉书·列女传》"}]}, {"meaning": "相当。", "cites": [{"t": "出载而立,其广终队。", "b": "《墨子·备梯》"}]}, {"meaning": "古代历法指称“闰月”。", "cites": [{"t": "举正于中,归邪于终。", "b": "《史记》"}]}, {"meaning": "众人。", "cites": [{"t": "终莫能就。", "b": "《战国策·韩策》"}, {"t": "以义终。", "b": "《礼记·祭法》"}, {"t": "终生之化。", "b": "《汉书·杨王孙传》"}]}, {"meaning": "整;全,尽。", "cites": [{"t": "终宵刺探。(终宵:通夜。刺探:探问。)", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "终夕", "t": "整夜,通宵"}, {"w": "终夜", "t": "整夜,全夜"}, {"w": "终风", "t": "整日刮风"}, {"w": "终朝", "t": "整个早上;整天,整日。"}]}, {"meaning": "(zhòng)。多。", "cites": [{"t": "终三十里。", "b": "《诗·周颂·噫嘻》"}, {"t": "以永终誉。", "b": "《诗·周颂·振鹭》"}]}, {"meaning": "始终,总。表始终全过程。", "cites": [{"t": "愿终守之。", "b": "《战国策·魏策》"}, {"t": "终无所成。", "b": "《世说新语·自新》"}, {"t": "终不敢搏。", "b": "唐·柳宗元《三戒》"}, {"t": "终不能发。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "终究,到底。", "cites": [{"t": "终不可强夺。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "王终遣之。", "b": "汉·刘向《列女传》"}, {"t": "终为忠臣。", "b": "《世说新语·自新》"}, {"t": "士大夫终不肯以小舟夜泊绝壁之下。", "b": "宋·苏轼《石钟山记》"}, {"t": "终不蒙见察。", "b": "宋·王安石《答司马谏议书》"}, {"t": "猛鸷终弗逮。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "终乖", "t": "到底违背"}, {"w": "终究", "t": "毕竟,也作“终久”"}, {"w": "终须", "t": "终究,毕竟"}, {"w": "终于", "t": "终究;到底"}, {"w": "终久", "t": "终究"}, {"w": "终归", "t": "终究;毕竟。"}]}, {"meaning": "表示时间,相当于“常”、“久”。", "cites": [{"t": "故官无常贵而民无终贱。", "b": "《墨子·尚贤上》"}], "words": [{"w": "终古", "t": "久远;经常。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1345wx','驻','1','zhù','马','8','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从马,主声。本义:马立止)。"}, {"meaning": "同本义。", "cites": [{"t": "驻,马立也。", "b": "《说文》"}, {"t": "驻驾。", "b": "《后汉书·灵帝纪》。注:“停车处也。”"}, {"t": "驻,止也。", "b": "《苍颉篇》"}, {"t": "怅容与而久驻兮。", "b": "《文选·班昭·东征赋》"}, {"t": "主称未醉,惟见马驻。", "b": "宋之问《上巳泛舟昆明池宴宗主簿席序》"}], "words": [{"w": "驻马", "t": "驻鞍、驻勒。都指使马停下不走。"}]}, {"meaning": "古时特指车驾停立。", "cites": [{"t": "今旦明府早驾,久驻未出。", "b": "《汉书》"}], "words": [{"w": "驻罕", "t": "古代帝王在外停驻"}, {"w": "驻盖", "t": "驻轸、驻轴、驻轮、驻轩等,都指停车"}, {"w": "驻驾庑", "t": "停车棚"}, {"w": "驻辇", "t": "帝王外出,停在某处。"}]}, {"meaning": "停留;止住。", "cites": [{"t": "行人驻足听。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "解鞍少驻初程。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "驻步", "t": "停步,止步;停留而不前进或离去"}, {"w": "驻气", "t": "静气,屏息"}, {"w": "驻蹇", "t": "使驴停下不走"}, {"w": "驻敌", "t": "止住敌人的攻势"}, {"w": "驻云", "t": "止住云动"}, {"w": "驻水", "t": "拦水。"}]}, {"meaning": "驻扎。", "cites": [{"t": "瑜请得精兵数万人,进住夏口。(住,通“驻”。)", "b": "《资治通鉴》"}], "words": [{"w": "进驻", "t": "军队开进某一地区驻扎下来"}, {"w": "驻泊", "t": "停船逗留;宋代屯驻各州的军队"}, {"w": "二连驻在河边;驻宿", "t": "驻扎过夜"}, {"w": "驻屯", "t": "驻扎"}, {"w": "驻止", "t": "驻扎"}, {"w": "驻戍", "t": "驻扎防守。"}]}, {"meaning": "居留其地。", "cites": [{"t": "五年,率诸军北驻汉中。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "驻使", "t": "驻留外国的大使及公使"}, {"w": "驻锡", "t": "指僧人之居住寺庙"}, {"w": "驻所", "t": "机构驻在地。"}]}, {"meaning": "留住。", "cites": [{"t": "莎深苔滑地无尘,竹冷花迟剩驻春。", "b": "唐·雍陶《访友人幽居》"}], "words": [{"w": "驻春", "t": "留住春天"}, {"w": "驻年", "t": "留住年华"}, {"w": "驻颜", "t": "留住容貌使不衰老"}, {"w": "驻色", "t": "留住年华。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1346wx','绊','1','bàn','纟','8','','[{"pinyin": "bàn", "defs": [{"meaning": "(形声。从糸,半声。本义:驾车时套在牲口后部的皮带)。"}, {"meaning": "同本义。", "cites": [{"t": "绊,马絷也。字亦作跘。", "b": "《说文》"}, {"t": "靽,半也,拘使半行不得自纵也。", "b": "《释名·释车》"}]}, {"meaning": "泛指系鸟兽的绳子。", "cites": [{"t": "饰五采之华绊,结璇玑之金环。", "b": "傅玄《鹰赋》"}]}, {"meaning": "喻阴谋、圈套。", "cites": [{"t": "连兄弟燕青也着绊了。", "b": "《燕青博鱼》"}]}, {"meaning": "亦用以比喻误中圈套而受害。"}, {"meaning": "装束,穿戴。", "cites": [{"t": "国人之绊。", "b": "《瀛涯胜览》"}]}, {"meaning": "羁绊;拘束;束缚。", "cites": [{"t": "细推物理须行乐,何用浮荣绊此身。", "b": "杜甫《曲江二首》"}, {"t": "今绊姜维于沓中,使不得东顾。", "b": "《资治通鉴》"}]}, {"meaning": "用绳子把足系住。", "cites": [{"t": "不羁不绊。", "b": "扬雄《交州牧箴》"}], "words": [{"w": "绊脚", "t": "用绳子绑住脚。"}]}, {"meaning": "走路或跑步时被别的东西挡住或缠住。", "cites": [{"t": "被门槛子绊倒。", "b": "《红楼梦》"}], "words": [{"w": "绊倒", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1347wx','驼','1','tuó','马','8','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从马,它声。从马,表示与马相类的动物。本义:骆驼)。"}, {"meaning": "相当于“坨”、“块”。", "cites": [{"t": "你没看见,退油丹都使了两驼!", "b": "《大波》"}]}, {"meaning": "用牲口负物。也作“驮”。", "cites": [{"t": "其兽则麒驎角端,騊騟橐驼。", "b": "《汉书·司马相如传》。颜师古注:“橐驼者,言其可负橐囊而驼物。故以名云。"}, {"t": "他有一匹马,背驼三将,入水如踏平地,日行千里流星马,此乃是无敌之骑。", "b": "明·黄元吉《黄廷道夜走流星马》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1348wx','绍','1','shào','纟','8','','[{"pinyin": "shào", "defs": [{"meaning": "(形声。从糸(mì),召声。本义:继承;紧密连续)。"}, {"meaning": "同本义。", "cites": [{"t": "绍,继也。", "b": "《说文》"}, {"t": "绍庭上下。", "b": "《诗·周颂·访落》"}, {"t": "弗念厥绍。", "b": "《诗·大雅·抑》"}, {"t": "使寡君之绍续昆裔。", "b": "《国语·晋语》"}, {"t": "不绍叶公之明,而使之悦近而来远。", "b": "《韩非子·难三》"}, {"t": "以此绍殷,是以乱易暴也。", "b": "《吕氏春秋·诚廉》"}, {"t": "绍复先王之大业。", "b": "《书·盘庚》"}], "words": [{"w": "绍真", "t": "继承正统;统一天下"}, {"w": "绍天明命", "t": "承受上天之命"}, {"w": "绍衣", "t": "承服奉行先人的德化和教言"}, {"w": "绍兴", "t": "继续发扬光大;另县名。"}]}, {"meaning": "介绍,为人引见,使相互认识。", "cites": [{"t": "绍我周王见休。", "b": "《孟子》"}, {"t": "胜请为绍介。", "b": "《史记·鲁仲连传》"}, {"t": "士为绍摈。", "b": "《仪礼·聘礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1349wx','绎','1','yì','纟','8','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从糸(mì),睪(yì)声。本义:抽丝)。"}, {"meaning": "同本义。", "cites": [{"t": "绎,抽丝也。", "b": "《说文》"}, {"t": "绎,理也。丝曰绎之。", "b": "《方言一》"}, {"t": "绎,抽也。", "b": "《三苍》"}]}, {"meaning": "陈述。", "cites": [{"t": "庶言同则绎。", "b": "《书》。孔传:众言同则陈而布之"}], "words": [{"w": "绎志", "t": "抒陈自己的志向;书名。"}]}, {"meaning": "陈列。", "cites": [{"t": "射之为言者绎也,或曰舍也。绎者,各绎己之志也。", "b": "《礼记》。孔颖达疏:“绎,陈也,言陈己之志。”"}]}, {"meaning": "扰动。", "cites": [{"t": "匪绍匪游,徐方绎骚,震惊徐方。", "b": "《诗·大雅》"}], "words": [{"w": "绎骚", "t": "骚动;扰动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1350wx','经','1','jīng jìng','纟','8','','[{"pinyin": "jīng", "defs": [{"meaning": "(古字为“巠”。形声。从糸(mì),表示与线丝有关,巠声。本义:织物的纵线,与“纬”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "经,织也。", "b": "《说文》。按,从丝为经,衡丝为纬,凡织,经静而纬动。"}, {"t": "经,经纬以成缯帛也。", "b": "《玉篇》"}, {"t": "毋失经纪。", "b": "《礼记·月令》"}, {"t": "经正而后纬成。", "b": "刘勰《文心雕龙》"}], "words": [{"w": "经布", "t": "来回穿梭织布。"}]}, {"meaning": "南北纵贯的道路或土地。", "cites": [{"t": "凡地东西为纬,南北为经。", "b": "《大戴礼记·易本命》"}, {"t": "国中九经九纬。", "b": "《考工记·匠人》"}], "words": [{"w": "经途", "t": "南北向的道路"}, {"w": "经涂", "t": "南北向的道路。"}]}, {"meaning": "常道。指常行的义理、准则、法制。", "cites": [{"t": "经,常也。", "b": "《广雅》"}, {"t": "拂经。", "b": "《易·颐》"}, {"t": "武之美经也。", "b": "《左传·宣公十二年》"}, {"t": "王之大经也。", "b": "《左传·昭公十五年》。疏:“经者,纲纪之言也。”"}, {"t": "经也者,常也;权也者,达经也。", "b": "柳宗元《断刑论》"}], "words": [{"w": "经权", "t": "原则与权宜"}, {"w": "经榜", "t": "旧时为死者做法事时张贴的榜文"}, {"w": "经事", "t": "经典规定的常道。"}]}, {"meaning": "经典。"}, {"meaning": "历来被尊奉为典范的著作。", "cites": [{"t": "五经何谓?谓易、尚书、诗、礼、春秋也。", "b": "《白虎通·五经》"}, {"t": "鲁叟谈五经,白发死章句。", "b": "李白《嘲鲁儒》"}, {"t": "辛苦遭逢起一经。", "b": "宋·文天祥《过零丁洋》"}, {"t": "治经为博士。", "b": "《资治通鉴·汉纪》"}, {"t": "执经叩问。", "b": "明·宋濂《送东阳马生序》"}, {"t": "先生授经。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "《道德经》;《十三经》;诵经;引经注典;博古通经", "t": ""}]}, {"meaning": "中医称经脉,人体气血运行的通路。", "cites": [{"t": "技经肯綮。", "b": "《庄子·养生主》"}], "words": [{"w": "经穴;经络", "t": ""}]}, {"meaning": "中国古代图书目录四部(经、史、子、集)分类法中指儒家经典及小学(文学、音韵、训诂)方面的书。", "cites": [{"t": "诸子及经史。", "b": "明·顾炎武《复庵记》"}]}, {"meaning": "中国古地名 。在今河北省巨鹿县东北。"}, {"meaning": "小路,途径。", "cites": [{"t": "学之经莫速乎好其人,隆礼次之。", "b": "《荀子·劝学》"}, {"t": "邪心胜则事经绝,事经绝则祸难生。", "b": "《韩非子·解老》"}]}, {"meaning": "治理。", "cites": [{"t": "经世之条理。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "经邦", "t": "治国"}, {"w": "经国济民", "t": "治理国家,普济万民"}, {"w": "经济之才", "t": "治理济世的志向"}, {"w": "经济之才", "t": "经邦济世;治理国家的才干"}, {"w": "经维之才", "t": "治理国家的才能。"}]}, {"meaning": "经过,经历。", "cites": [{"t": "经德不回。", "b": "《孟子》"}, {"t": "经日乃厌倦。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "经三日三夜。", "b": "《世说新语·自新》"}, {"t": "其所已经者。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "其所未经者。", "b": ""}], "words": [{"w": "经练", "t": "经历;经验"}, {"w": "经涉", "t": "途中跋涉"}, {"w": "经经眼", "t": "过目;看看"}, {"w": "经行", "t": "行程中经过"}, {"w": "经见", "t": "经历和见识"}, {"w": "经官起诉", "t": "到官府起诉。"}]}, {"meaning": "经营;料理。", "cites": [{"t": "为夫妇外内,以经二物。", "b": "《左传·昭公二十五年》"}, {"t": "经理宇内。", "b": "《史记·秦始皇本纪》"}, {"t": "经国之大业。", "b": "曹丕《典论论文》"}], "words": [{"w": "经催", "t": "负责催收租税"}, {"w": "经划", "t": "经营筹划"}, {"w": "经画", "t": "经营筹划"}, {"w": "经量", "t": "清查丈量,经营规划"}, {"w": "经账", "t": "旧时出卖田产时,写明田产的亩数、边界、价格等内容的账单。"}]}, {"meaning": "量度;筹划。", "cites": [{"t": "经始灵台,经之营之。", "b": "《诗·大雅·灵台》"}, {"t": "古者经井田。", "b": "《盐铁论·相刺》"}], "words": [{"w": "经治", "t": "筹划治理"}, {"w": "经远", "t": "长远谋划"}, {"w": "经筭", "t": "筹划谋算。"}]}, {"meaning": "上吊,缢死。", "cites": [{"t": "自经于沟渎而莫之知也?", "b": "《论语·宪问》"}, {"t": "灵王经而死。", "b": "《公羊传·昭公十三年》"}, {"t": "经其颈于树枝。", "b": "《史记·田单传》"}], "words": [{"w": "经死", "t": "上吊而死。"}]}, {"meaning": "正常;经常。", "cites": [{"t": "其语闳大不经。", "b": "《史记》"}], "words": [{"w": "经入", "t": "指常规赋税收入"}, {"w": "经用", "t": "经常用度"}, {"w": "经惯", "t": "老练,有经验"}, {"w": "经赋", "t": "常规赋税。"}]}]}, {"pinyin": "jìng", "defs": [{"meaning": "纺织,把纤维拧成纱。", "cites": [{"t": "吾始经之而不可更也。", "b": "《韩非子》"}, {"t": "叔叔伯伯来经布,廿五个筒子满一车。", "b": "《中国歌谣资料》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1351wx','贯','1','guàn','贝','8','','[{"pinyin": "guàn", "defs": [{"meaning": "(会意。从毌(guàn),从贝(表示与钱财有关)。“毌”是贯穿之贯,象穿物之形。本义:穿钱的绳子)。"}, {"meaning": "同本义。", "cites": [{"t": "贯,钱贝之贯也。", "b": "《说文》"}, {"t": "都内之钱,贯朽而不可挍。", "b": "《汉书》"}, {"t": "厨有臭败肉,库有贯朽钱。", "b": "唐·白居易《伤宅》"}, {"t": "反尔如贯。", "b": "《诗·小雅·何人斯》"}], "words": [{"w": "贯朽", "t": "串钱的绳子朽断,形容积钱多而经久不用。"}]}, {"meaning": "旧时用绳索穿钱,每一千文为一贯。", "cites": [{"t": "着落店主人家追要原典身钱三千贯。", "b": "《水浒》"}], "words": [{"w": "贯百", "t": "贯伯。一贯钱,一些钱。百:一百文钱"}, {"w": "钱串一贯", "t": "一千文钱"}, {"w": "万贯家私", "t": ""}]}, {"meaning": "事情,事例。", "cites": [{"t": "闵子骞曰:“仍旧贯,如之何?何必改作?”", "b": "《论语·先进》"}], "words": [{"w": "贯利", "t": "事功和利益。"}]}, {"meaning": "条理;系统。", "cites": [{"t": "鱼贯而进。", "b": "《三国志·邓艾传》"}], "words": [{"w": "贯类", "t": "从同类事物的比较中贯通其理"}, {"w": "贯鱼", "t": "穿成一串的鱼。比喻有次序。"}]}, {"meaning": "罪恶。", "cites": [{"t": "商罪贯盈,天命诛之。", "b": "《书·秦誓》"}], "words": [{"w": "贯恶", "t": "一贯的罪恶"}, {"w": "贯盈", "t": "罪恶满盈"}, {"w": "贯天", "t": "滔天。形容罪恶、灾祸极大。"}]}, {"meaning": "祖籍;籍贯。", "cites": [{"t": "翁云贯属新丰县,生逢聖代无征战。", "b": "唐·白居易《新丰折臂翁》"}], "words": [{"w": "贯系", "t": "籍贯世系"}, {"w": "贯址", "t": "籍贯和地址。"}]}, {"meaning": "序次;按顺序排列。", "cites": [{"t": "今猥以轻鄙,超伦踰等,上乱聖朝贯鱼之序,下违群士准平立论。", "b": "《晋书·蔡谟传》"}], "words": [{"w": "贯序", "t": "序次;按顺序排列"}, {"w": "贯叙", "t": "贯序;按次序铨叙录用"}, {"w": "贯次", "t": "前后有序"}, {"w": "贯列", "t": "排列"}, {"w": "贯比", "t": "排列比较。"}]}, {"meaning": "古国名 。故址在曹州济阴县南五六十里。"}, {"meaning": "姓。汉有贯高。"}, {"meaning": "用绳子穿连成串。", "cites": [{"t": "贯,累也。", "b": "《广雅》"}, {"t": "贯,穿也。以绳穿物曰贯。", "b": "《苍颉》"}, {"t": "贯魚以宫人宠。", "b": "《易·剥卦》"}, {"t": "贯金石。", "b": "《列子·周穆王》"}, {"t": "射则贯兮。", "b": "《诗·齐风·猗嗟》"}, {"t": "不贯不释。", "b": "《仪礼·乡射礼》"}], "words": [{"w": "贯结", "t": "用绳子穿起来结牢。形容牢记在心"}, {"w": "贯绳", "t": "串钱绳"}, {"w": "贯繦", "t": "串钱绳"}, {"w": "贯玉", "t": "成串的珠玉。形容文章或容颜体态之美"}, {"w": "贯系", "t": "贯穿连结。"}]}, {"meaning": "穿过;贯通,精通。", "cites": [{"t": "贯,穿也。", "b": "《广雅·释言》"}, {"t": "予一以贯之。", "b": "《论语·卫灵公》"}, {"t": "始而合,而矢贯余手及肘。", "b": "《左传·成公二年》"}, {"t": "白虹贯日。", "b": "《战国策·魏策》"}, {"t": "贯穿经传,驰聘古今,上下数千载间,斯己勤矣。", "b": "《汉书·司马迁传·赞》"}, {"t": "衡少善属文,游于三辅,因入京师,观太学,遂通五经,贯六艺。", "b": "《后汉书·张衡传》"}], "words": [{"w": "贯串", "t": "贯通;通达"}, {"w": "贯越", "t": "贯通穿越"}, {"w": "贯穴", "t": "贯通"}, {"w": "贯心", "t": "贯穿心脏"}, {"w": "贯头", "t": "古代某些民族在布匹中央挖一圆洞套入头颈,作为衣服"}, {"w": "贯珠", "t": "穿戴珠宝"}, {"w": "贯耳", "t": "指穿耳戴环以妆饰。"}]}, {"meaning": "累;连续。", "cites": [{"t": "贯四时而不改柯易叶。", "b": "《礼记·礼器》"}, {"t": "若夫贯日而治洋,一日而曲列之,是所使夫百吏官人为也,不足以是伤游玩安燕之乐。", "b": "《荀子·王霸》"}], "words": [{"w": "贯鱼承宠", "t": "来来往往的宫中女官依次受到宠爱"}, {"w": "贯属", "t": "连贯;连属"}, {"w": "贯辰", "t": "贯日;连日"}, {"w": "贯日", "t": "积日;累日。"}]}, {"meaning": "侍奉,服事。", "cites": [{"t": "三岁贯女,莫我肯顾。", "b": "《诗经·魏风·硕鼠》"}], "words": [{"w": "贯女", "t": "侍女"}, {"w": "华贯", "t": "华美的服事。"}]}, {"meaning": "学习;复习。", "cites": [{"t": "昼而讲贯,夕雨刃复。", "b": "《国语·鲁语下》"}], "words": [{"w": "讲贯", "t": "讲习。"}]}, {"meaning": ""}, {"meaning": "熟习;熟练。", "cites": [{"t": "无术之智,不教之能,而恃强速贯刃,不足以成也。", "b": "《吕氏春秋·不二》"}], "words": [{"w": "贯知", "t": "习知;熟知"}, {"w": "贯酣", "t": "通晓熟习"}, {"w": "贯习", "t": "熟练;熟悉"}, {"w": "贯熟", "t": "熟习;熟悉。"}]}, {"meaning": "习惯。", "cites": [{"t": "我不贯与小人乘,请辞。", "b": "《孟子·滕文公下》"}], "words": [{"w": "贯战", "t": "惯战;善战"}, {"w": "贯渎", "t": "惯于亵渎鬼神。"}]}, {"meaning": "(wān)。弯弓,张满弓。", "cites": [{"t": "胡人不敢南下而牧马,士亦不敢贯弓而报怨。", "b": "《史记·陈涉世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1352wx','契','1','qì xiè','大','9','','[{"pinyin": "qì", "defs": [{"meaning": "古代在龟甲、兽骨上灼刻文字和灼刻文字用的刀具,皆称契。"}, {"meaning": "刻龟甲的凿子。", "cites": [{"t": "菙氏掌共燋契,以待卜事。", "b": "《周礼》"}], "words": [{"w": "契文", "t": ""}]}, {"meaning": "泛指雕凿用具。", "cites": [{"t": "如室斯构而去其凿契,如水斯积而决其堤防。", "b": "晋·干宝《晋纪总论》"}]}, {"meaning": "感情志趣投合的朋友。", "cites": [{"t": "愿言蹑轻风,高举寻吾契。", "b": "陶潜《桃花源诗》"}], "words": [{"w": "契交", "t": "契士。情投意合的朋友"}, {"w": "契旧", "t": "老朋友"}, {"w": "契好", "t": "契交"}, {"w": "契弟", "t": "结拜兄弟"}, {"w": "契己", "t": "犹知己。"}]}, {"meaning": "用刀刻。", "cites": [{"t": "栔,刻也。", "b": "《说文》"}, {"t": "契,绝也。", "b": "《尔雅》。注:“今江东呼刻断物为契断。”"}, {"t": "爰契我龟。", "b": "《诗·大雅·緜》。传:“契,开也。”笺:“契灼其龟。”"}, {"t": "其剑自舟中坠于水,遂契其舟。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "又。", "cites": [{"t": "从其所契者。", "b": ""}, {"t": "斯契船而求剑,守株而伺兔也。", "b": "《后汉书·张衡传》"}, {"t": "契臂(刻臂沥血);契令(古代管理刻印书籍的官吏);契领(断颈)", "b": ""}]}]}, {"pinyin": "xiè", "defs": [{"meaning": "楔子。", "cites": [{"t": "从批契系(或作“继”)腰曳之。", "b": "《齐民要术》"}]}, {"meaning": "人名。殷代的祖先,传说是舜的臣。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1353wx','贰','1','èr','贝','9','','[{"pinyin": "èr", "defs": [{"meaning": "(会意。从贝,弍,(èr)声。本义:副)。"}, {"meaning": "同本义。", "cites": [{"t": "贰,副益也。", "b": "《说文》。段注:当云副也,益也。”"}, {"t": "簋贰用缶。", "b": "《易·坎卦》"}, {"t": "大祭三贰。", "b": "《周礼·乃酒正》"}, {"t": "取贰绥。", "b": "《礼记·曲礼》"}, {"t": "受其贰令。", "b": "《周礼·职内》"}, {"t": "其卜贰圉也。", "b": "《左传·僖公十五年》"}, {"t": "以贰六官。", "b": "《周礼·春官·大史》"}, {"t": "乘副车则式,佐车则否。", "b": "《礼记·少仪》"}], "words": [{"w": "贰佐", "t": "州县官的副"}, {"w": "贰相", "t": "副相"}, {"w": "贰官", "t": "副职。"}]}, {"meaning": "二的大写 ——用于会计账中以防伪造。", "cites": [{"t": "因贰以济民行。", "b": "《易·系辞》"}, {"t": "贰偷之不暇。", "b": "《左传·昭公十三年》。注:“不壹也。”"}, {"t": "命西鄙北鄙贰于己。", "b": "《左传·隐公元年》"}, {"t": "无是贰言也。", "b": "《国语·越语上》"}, {"t": "从许子道,则市贾不贰。", "b": "《孟子·滕文公上》"}], "words": [{"w": "贰端", "t": "二端"}, {"w": "贰统", "t": "分一统的帝系为二。"}]}, {"meaning": "古国名 。故地在今湖北省应山县境。", "cites": [{"t": "楚屈瑕将盟贰、轸。", "b": "《左传》"}]}, {"meaning": "一分为二。", "cites": [{"t": "既而大叔命西鄙北鄙贰于己。公子吕曰:“国不堪二。”", "b": "《左传·隐公元年》"}, {"t": "贰,益也。", "b": "《广雅·释诂一》"}], "words": [{"w": "贰觞", "t": "再三献酒"}, {"w": "贰纪", "t": "古礼中添饭加菜的规章。"}]}, {"meaning": "背离;怀有二心。", "cites": [{"t": "百姓携贰。", "b": "《国语·周语上》。注:“二心也。”"}, {"t": "君立臣从,何贰之有?", "b": "《国语·晋语一》"}, {"t": "诸侯贰,则晋国坏。", "b": "《左传·襄公二十四年》"}], "words": [{"w": "贰志", "t": "异志;二心"}, {"w": "贰虑", "t": "二心;三心二意。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1354wx','奏','1','zòu','大','9','','[{"pinyin": "zòu", "defs": [{"meaning": "(会意。小篆字形。上为“屮”(chè),初生的草,有上进义;中为双手形;下为“本”(tāo),行趋之义。本义:奉献,送上)。"}, {"meaning": "同本义。", "cites": [{"t": "奏,进也。", "b": "《说文》"}, {"t": "敷奏以言。", "b": "《虞书》"}, {"t": "以奏肤公。", "b": "《诗·小雅·六月》"}, {"t": "各奏尔能。", "b": "《诗·小雅·宾之初筵》"}, {"t": "予乘四载,随水刊木,既益奏庶鲜食。", "b": "《书·益稷》"}, {"t": "相如奉璧奏秦王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "使奏其技。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "以夏进炉,以冬奏扇。", "b": "《论衡·逢遇》"}, {"t": "燕姬奏妙舞,郑女发清歌。", "b": "萧纪《同萧长史看妓》"}, {"t": "俟封奏时潜易之而己。", "b": "方苞《狱中杂记》"}], "words": [{"w": "奏舞", "t": "行舞,献舞"}, {"w": "奏歌", "t": "行歌,献歌。"}]}, {"meaning": "特指向帝王进言或上书。", "cites": [{"t": "上书谓之奏。", "b": "《论衡·对作》"}, {"t": "奏平彻以闲雅。", "b": "陆机《文赋》。注:“奏以陈情叙事。”"}, {"t": "奏对称旨。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "奏书", "t": "上奏于天子的文书"}, {"w": "奏牍", "t": "古时臣子上奏君上的书牍"}, {"w": "奏参", "t": "向皇上奏章弹劾"}, {"w": "奏事", "t": "臣下上书给天子论事"}, {"w": "奏劾", "t": "上章弹劾"}, {"w": "奏明", "t": "奏陈明白。"}]}, {"meaning": "演奏,吹奏。", "cites": [{"t": "奏而食。", "b": "《礼记·玉藻》"}, {"t": "要其节奏。", "b": "《礼记·乐记》"}, {"t": "皆奏鸣凤。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "迨半奏。", "b": ""}, {"t": "辍其技不奏。", "b": ""}, {"t": "更奏鸣凤。", "b": ""}, {"t": "含愁更秦绿绮琴,调高弦绝无知音。", "b": "唐·卢仝《有所思》"}], "words": [{"w": "奏公", "t": "从事演奏"}, {"w": "奏阕", "t": "乐曲演奏终了"}, {"w": "奏假", "t": "演奏升堂之乐"}, {"w": "奏庸", "t": "击钟"}, {"w": "奏曲", "t": "演奏乐曲。"}]}, {"meaning": "取得;产生。", "cites": [{"t": "各奏汝功。", "b": "唐·韩愈《平淮西碑》"}], "words": [{"w": "奏绩", "t": "取得成绩;建立功绩"}, {"w": "奏凯", "t": "胜利。"}]}, {"meaning": "进(刀)。", "cites": [{"t": "奏刀騞然。", "b": "《庄子·养生主》"}]}, {"meaning": "臣子上帝王的文书。", "cites": [{"t": "在奏未上,会得进兵玺书。《后汉书·赵充国传》", "b": ""}, {"t": "汉定礼仪,则有四品:一曰章,二曰奏,三曰表,四曰议。章以谢恩,奏以按劾,表以陈情,议以执异。", "b": "《文心雕龙》"}], "words": [{"w": "奏稿", "t": "奏章的草稿"}, {"w": "奏札", "t": "臣下上殿奏对时呈给皇帝的文书"}, {"w": "奏牍", "t": "书写奏章的简牍"}, {"w": "奏案", "t": "批阅奏本的几桌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1355wx','春','1','chūn','日','9','','[{"pinyin": "chūn", "defs": [{"meaning": "(会意。甲骨文字形,从草(木),草木春时生长;中间是“屯”字,似草木破土而出,土上臃肿部分,即刚破土的胚芽形,表示春季万木生长;“屯”亦兼作声符。小篆字形,隶变以后,除“日”之外,其他部分都看不出来了。本义:春。四季的第一季)。"}, {"meaning": "同本义。", "cites": [{"t": "春,推也。从艸屯,从日,艸春时生也。会意,屯亦声…今隶作春字,亦作芚。", "b": "《说文》"}, {"t": "春为青阳,春为发生,春秋繁露。春者,天之和也。又春,喜气也,故生。", "b": "《尔雅·释天》"}, {"t": "春者何,岁之始也。", "b": "《公羊传·隐公元年》"}, {"t": "为此春酒。", "b": "《诗·豳风·七月》"}, {"t": "春眠不觉晓,处处闻啼鸟。", "b": "孟浩然《春晓》"}, {"t": "红豆生南国,春来发几枝?", "b": "王维《相思》"}], "words": [{"w": "春归", "t": "春天来临"}, {"w": "春闱", "t": "春季考试"}, {"w": "春蚕", "t": "春季饲养的蚕"}, {"w": "春事", "t": "春季农耕之事"}, {"w": "春人", "t": "春游之人"}, {"w": "春试", "t": "春季在京师举行的科举考试"}, {"w": "春忙", "t": "春季农耕忙碌时"}, {"w": "春社", "t": "元宵节前后举行猜灯谜活动的一种游戏组织。"}]}, {"meaning": "男女情欲。", "cites": [{"t": "有女怀春。", "b": "《诗·召南·野有死麕》"}], "words": [{"w": "怀春", "t": "少女爱慕异性"}, {"w": "春女", "t": "怀春的女子"}, {"w": "春方", "t": "春药"}, {"w": "春兴", "t": "情欲"}, {"w": "春线", "t": "浸过兴奋药剂的线。淫秽物品。"}]}, {"meaning": "泛指一年。", "cites": [{"t": "一卧东山三十春。", "b": "高适《人日寄杜二拾遗》"}], "words": [{"w": "春年", "t": "青春,年华"}, {"w": "春秋", "t": "年纪;年数。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1356wx','帮','1','bāng','巾','9','','[{"pinyin": "bāng", "defs": [{"meaning": "(形声。从巾,邦声。“巾”。从“巾”字多与布帛有关。本义:鞋的边缘部分)。"}, {"meaning": "同本义。", "cites": [{"t": "用纤指将绣帮儿弹。", "b": "元·乔吉《赏花时·睡鞋儿》"}], "words": [{"w": "帮子,帮儿", "t": "鞋帮。"}]}, {"meaning": "从旁挟持。", "cites": [{"t": "曹正、杨志紧紧地帮着鲁智深到阶下。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1357wx','玷','1','diàn','王','9','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。本义:白玉上的斑点)。"}, {"meaning": "同本义。", "cites": [{"t": "玷,玉瑕。", "b": "《广韵》"}, {"t": "白圭之玷,尚可磨也。", "b": "《诗·大雅·抑》。传:“玷,缺也。”"}, {"t": "不知其玷。", "b": "《诗·大雅·召旻》"}, {"t": "元成复作自荐复玷缺之艰难。", "b": "《汉书·韦元成传》。注:“玉缺曰玷。”"}], "words": [{"w": "玷缺", "t": "白玉有斑点、缺损。比喻人的品德有缺点"}, {"w": "玷翳", "t": "玉上斑痕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1358wx','珍','1','zhēn','王','9','','[{"pinyin": "zhēn", "defs": [{"meaning": "(本义:珠玉等宝物)。"}, {"meaning": "同本义。", "cites": [{"t": "珍,宝也。", "b": "《说文》"}, {"t": "珍圭。", "b": "《周礼·典瑞》。注:“王使之瑞节。”"}, {"t": "多珍怪些。", "b": "《楚辞·招魂》。注:“金玉为珍。”"}, {"t": "珍怪奇物。", "b": "《淮南子·主术》"}, {"t": "远方莫致其珍。", "b": "《荀子·解蔽》"}, {"t": "希世之珍。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "堂有炼珍。", "b": "清·周容《芋老人传》"}], "words": [{"w": "珍积", "t": "积蓄的财宝"}, {"w": "珍翰", "t": "墨宝"}, {"w": "珍币", "t": "珍宝财物"}, {"w": "珍赂", "t": "珍赀。珍宝财物"}, {"w": "珍瑰", "t": "珍玮。珍宝。"}]}, {"meaning": "比喻难得的人才。", "cites": [{"t": "此固国家之珍,而社稷之佐也。", "b": "《墨子》"}]}, {"meaning": "精美的食品。", "cites": [{"t": "交广市鲑珍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "食必珍美。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "珍杂", "t": "珍错,山珍海味"}, {"w": "珍鲑", "t": "山珍海味"}, {"w": "珍滋", "t": "美味"}, {"w": "珍异", "t": "珍贵奇特的食物"}, {"w": "山珍海味", "t": ""}]}, {"meaning": "珍贵的,宝贵的。", "cites": [{"t": "珍器重宝。", "b": "汉·贾谊《过秦论》"}, {"t": "奇草珍木。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "珍惠", "t": "赐予珍贵的恩惠"}, {"w": "珍贶", "t": "珍贵的礼品"}, {"w": "珍木", "t": "珍贵的树木"}, {"w": "珍卉", "t": "珍贵的花卉"}, {"w": "珍甘", "t": "珍贵甘美的食品。"}]}, {"meaning": "珍爱,珍视。", "cites": [{"t": "书曰:公子遂,珍之也。", "b": "《左传·文公八年》。注:“珍,贵也。”"}], "words": [{"w": "珍袭", "t": "珍藏"}, {"w": "珍宠", "t": "珍惜宠爱"}, {"w": "珍练", "t": "珍重、保重"}, {"w": "珍调", "t": "保重调养。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1359wx','玲','1','líng','王','9','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从玉,令声。玲玎:玉石等相击的清脆声)。"}, {"meaning": "象声词。玉声。", "cites": [{"t": "玲,玉声。", "b": "《说文》"}, {"t": "玲珑,玉声也。", "b": "《埤苍》"}, {"t": "和氏珑玲。", "b": "扬雄《甘泉赋》"}], "words": [{"w": "玲玲;玲琅", "t": "玉声。"}]}, {"meaning": "明亮或美好的样子。", "cites": [{"t": "珊瑚幽茂而玲珑。", "b": "左思《吴都赋》。注:“明貌。”"}], "words": [{"w": "玲珑", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1360wx','珊','1','shān','王','9','','[{"pinyin": "shān", "defs": [{"meaning": "由一种叫珊瑚虫的腔肠动物的外骨骼聚集而成。", "cites": [{"t": "珊瑚，色赤，生于海，或生于山。--《说文》", "b": ""}]}, {"meaning": "珊瑚在网比喻有才学的人都被收罗来了。"}, {"meaning": "", "cites": [{"t": "动雾縠以徐步兮，拂墀声之珊珊。--宋玉《神女赋》", "b": ""}, {"t": "时闻杂佩声珊珊。 -- 杜甫《郑驸马宅宴洞中》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1361wx','玻','1','bō','王','9','','[{"pinyin": "bō", "defs": [{"meaning": "a.一种质地硬而脆的透明物品，一般用细纱、石灰石、碳酸钠等混合起来，加高温熔解，冷却后制成，主要成分是二氧化碳、氧化钠和氧化钙。b.俗称某些透明的像玻璃的质料。"}, {"meaning": "【玻尔半径】在玻尔理论中是氢原子处于基态时电子绕核运行所作的圆轨道的半径。是原子物理学中的一种长度单位。常用表示。"}, {"meaning": "【玻尔的原子理论】根据卢瑟福的核式结构模型、用经典运动规律和普朗克的量子概念来阐明原子结构的初步理论。其主要内容包括如下假设（1）原子只能处于一系列不连续的能量状态中，在这些状态中原子是稳定的，电子虽做加速运动，但不向外辐射能量；（2）原子从一种定态跃迁到另一种定态时，它辐射一定频率的光子，光子的能量等于这两种定态的能量差；（3）原子的不同能量状态跟电子沿不同的圆形轨道绕核运动相适应。"}, {"meaning": "【玻璃】一种质地硬而脆的透明物体。一般玻璃是用含石英的砂子、石灰石、纯碱等混合后，在高温下熔化，成型，冷却后制成。主要成分是二氧化硅、氧化钠和氧化钙。此外还有以硼酸盐、氟化物等为主的特种玻璃、安全玻璃、有色玻璃等。"}, {"meaning": "【玻璃电极】玻璃和溶液接触时，界面上有电位差，其数值同溶液的ph值有关。利用这种关系所制成的一种测定溶液氢离子浓度的电极就是玻璃电极。"}, {"meaning": "【玻璃钢】用玻璃纤维或其织物增强的塑料。质地轻巧而坚硬，机械强度可与钢材相比。不导电，耐腐蚀。在某些方面可代替钢材。是重要的工业材料。"}, {"meaning": "【玻璃体】填充于眼球后部腔隙内的一种无色透明胶状物质。具有支撑眼球内壁、透光、折光的作用。"}, {"meaning": "【玻利瓦尔】（1783-1830）南美西班牙殖民地独立战争领袖，南美共和制度的奠基者。生于加拉加斯。曾在欧洲学习。1810年起投身南美独立战争，曾获\'解放者\'称号，多次率军打败西班牙军队。1819年建立大哥伦比亚，任总统。1826年建玻利维亚共和国，结束西班牙在南美的统治。1830年大哥伦比亚陷于分裂时辞职。12月17日在哥伦比亚病死。"}, {"meaning": "【玻利维亚】全称玻利维亚共和国。位于南美洲中部。面积108万平方公里。人口719万（1989），印第安人占54%，，印欧混血种人占31%，。官方语言为西班牙语。95%的居民信奉天主教。法定首都苏克雷。议会、政府所在地拉巴斯。"}, {"meaning": "【玻色子】自旋动量矩为1/2h/2π的偶数倍的微观粒子（h是普朗克常量）。如光子、π介子、a粒子及由偶数个核子构成的原子核等。不服从泡利不相容原理。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1362wx','毒','1','dú','母','9','','[{"pinyin": "dú", "defs": [{"meaning": "(会意。从屮(象草木初生),毒声。本义:毒草滋生)。"}, {"meaning": "毒物;毒纯洁。", "cites": [{"t": "毒,厚也,害人之草,往往而生。", "b": "《说文》"}, {"t": "聚毒药,以共医事。", "b": "《周礼·医师》"}]}, {"meaning": "苦;苦痛。", "cites": [{"t": "尔万方百姓罹其凶害,弗忍荼毒。", "b": "《书·汤诰》。孔传:“荼毒,苦也,不能堪忍虐之甚。”"}]}, {"meaning": "毒害。", "cites": [{"t": "以此毒天下。", "b": "《易·师》"}, {"t": "或同系,情罪重者反出在外,而轻者、无罪者罹其毒。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "毒老鼠;毒人", "t": "毒害别人"}, {"w": "毒化", "t": "利用毒品残害人们。亦指用落后反动思想腐蚀人们"}, {"w": "毒瘾", "t": "吸毒的癖好。因吸毒而失业,贫穷潦倒"}, {"w": "毒钩", "t": "指某些动物尾部能注射毒液的钩针刺。"}]}, {"meaning": "怨恨,憎恨。", "cites": [{"t": "今虽死乎此,比吾乡邻之死则已后矣,又安敢毒耶?", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "毒情", "t": "怨仇"}, {"w": "毒恨", "t": "痛恨;憎恨"}, {"w": "毒苦", "t": "怨恨"}, {"w": "毒孽", "t": "犹痛恨"}, {"w": "毒情", "t": "犹冤仇。"}]}, {"meaning": "治理。"}, {"meaning": "有毒的;恶性的。", "cites": [{"t": "呼嘘毒疠,往往而死者相藉也。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "毒卉", "t": "毒草"}, {"w": "毒虫", "t": "使人害病的虫"}, {"w": "毒蝤", "t": "有毒的梭子蟹"}, {"w": "毒鱼口", "t": "也称便毒、横痃,指各种性病的腹股沟淋巴结肿大"}, {"w": "毒蛇螫手,壮士解腕", "t": "喻为全局忍痛割让局部"}, {"w": "毒孽", "t": "深重的罪孽"}, {"w": "毒病", "t": "恶性病症"}, {"w": "毒症", "t": "毒病"}, {"w": "毒肿", "t": "毒性肿块"}, {"w": "毒疮", "t": "恶性疮疡"}, {"w": "毒利", "t": "恶疾。"}]}, {"meaning": "厉害;甚于。", "cites": [{"t": "有九折坂,夏则凝冰,冬则毒寒。", "b": "《水经注·河水》"}], "words": [{"w": "毒严", "t": "严寒。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1363wx','型','1','xíng','土','9','','[{"pinyin": "xíng", "defs": [{"meaning": "(形声。从土,刑声。本义:铸造器物的模子。用木做的叫模,用竹做的叫范,用泥做的叫型)。"}, {"meaning": "同本义。", "cites": [{"t": "型,铸器之法也。", "b": "《说文》。字亦作侀"}, {"t": "刑者,侀也。侀者,成也。水曰准,曰法;木曰模,竹曰笵;士曰型。", "b": "《礼记·王制》"}, {"t": "夫纯钩、鱼肠之始下型。", "b": "《淮南子·修务》"}, {"t": "凝土亦能型。", "b": "谢灵运《命学士讲书》"}], "words": [{"w": "纸型;剂型;砂型;造型;铸型;模型", "t": ""}]}, {"meaning": "楷模。", "cites": [{"t": "虽无老成人,尚有典型。", "b": "《诗·大雅·荡》"}, {"t": "太夫人仁慈果决如此,其泽物型家,推类可想。", "b": "清·陈康祺《郎潜纪闻》"}], "words": [{"w": "型坊", "t": "犹典范,楷模"}, {"w": "型范", "t": "典范;法式。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1364wx','拭','1','shì','扌','9','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从手,式声。本义:揩,擦) 同本义。", "cites": [{"t": "拭,清也。", "b": "《尔雅》"}, {"t": "拭圭。", "b": "《仪礼·聘礼》。注:“清也。”"}, {"t": "雍人拭羊。", "b": "《礼记·杂记》"}, {"t": "反祛拭面,泣涕沾襟。", "b": "《论衡·指端》"}, {"t": "惊定还拭泪。", "b": "杜甫《羌村三首》"}, {"t": "从粉板上拭去了孔乙己的名字。", "b": "《孔乙己》"}], "words": [{"w": "拭目", "t": "擦亮眼睛"}, {"w": "拭泪,拭拂", "t": "拭擦,揩擦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1365wx','挂','1','guà','扌','9','','[{"pinyin": "guà", "defs": [{"meaning": "(形声。从手,圭(guī)声。本义:区别,区分)。"}, {"meaning": "同本义。", "cites": [{"t": "挂,画也。", "b": "《说文》。段玉裁注:《易·系辞传》:“分而为二以象两,挂一以象三。”…古本多作画者,此等皆有分别画出之意。陆德明云:“挂,别也。后人乃云悬挂,俗制挂字耳。”"}, {"t": "挂于季指。", "b": "《仪礼·特牲礼》"}, {"t": "变更易常以掛功名。", "b": "《庄子·渔夫》。释文:“别也。”"}]}, {"meaning": "悬挂;下垂。", "cites": [{"t": "挂曲琼些。", "b": "《楚辞·招魂》。注:“悬也。”"}, {"t": "仰视天,则明月斜挂,云霞掩映。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "长风破浪会有时,直挂云帆齐沧海。", "b": "唐·李白《行路难》"}], "words": [{"w": "挂匾;挂筹", "t": "将酒筹挂在座旁,以示暂时离席"}, {"w": "挂红", "t": "给人披封红色绢绸,以示贺喜"}, {"w": "挂雷", "t": "悬挂着的爆炸武器。"}]}, {"meaning": "钩住;拴住。", "cites": [{"t": "高者挂罥长林梢,下者飘转沉塘坳。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "把拖车挂上;我的衣服被钉子挂住了", "t": ""}]}, {"meaning": "悬挂。", "cites": [{"t": "罩者抑之,挂者举之。", "b": "《淮南子·说林》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1366wx','封','1','fēng','寸','9','','[{"pinyin": "fēng", "defs": [{"meaning": "(会意。金文字形,左边象土上长着丰茂的树木形,右边是一只手(又,后来写作“寸”),表示聚土培植。《说文》:“封,爵诸侯之土也。从之从土从寸。”郭沫若曰:“古之畿封实以树为之也。此习于今犹存。然其事之起,乃远在太古。太古之民多利用自然林木以为族与族间之畛域,西方学者所称为境界林者是也。”。李孝定曰:“封之本义当以郭说为是,许训乃后起之义。字象植树土上,以明经界。爵诸侯必有封疆,乃其引申义。”本义:疆界;田界)。"}, {"meaning": "同本义。", "cites": [{"t": "所封封域。", "b": "《周礼·春官·保章氏》"}, {"t": "田有封洫。", "b": "《左传·襄公三十年》"}, {"t": "使田有封洫。", "b": "《吕氏春秋·乐成》"}, {"t": "既东封郑,又欲肆其西封。", "b": "《左传·僖公三十年》"}], "words": [{"w": "封内,封外", "t": "天子或诸侯的领地之内或外"}, {"w": "封守", "t": "边防;封疆"}, {"w": "封界,封略", "t": "疆界;边境"}, {"w": "封洫", "t": "区分田界的水沟"}, {"w": "封畔", "t": "国界。"}]}, {"meaning": "坟堆;土堆。", "cites": [{"t": "而五人者亦得以加其土封。", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "土堆或形状像坟的堆积物。", "cites": [{"t": "所谓平原者,下泽也。虽有小封,不得为高。", "b": "《管子》"}]}, {"meaning": "国土,土地。", "cites": [{"t": "土地之大,封内千里。", "b": "《荀子》"}]}, {"meaning": "泛指书信。", "cites": [{"t": "封来江渺渺,信去雨冥冥。", "b": "李商隐《酬令狐郎中见寄》"}]}, {"meaning": "封建主义的简称。"}, {"meaning": "封山,山名 。在今浙江省德清县西南。"}, {"meaning": "分封土地。", "cites": [{"t": "以赂秦之地,封天下之谋臣。", "b": "宋·苏洵《六国论》"}, {"t": "故太公望封于营丘。", "b": "《史记· 货殖列传序》"}], "words": [{"w": "封国", "t": "封土立国"}, {"w": "封爵", "t": "封土授爵"}, {"w": "封赋", "t": "受封田地的赋税"}, {"w": "封邑", "t": "赐给领地以为食邑。"}]}, {"meaning": "帝王把爵位及土地赐给臣子也叫封。", "cites": [{"t": "安緼王即位,封公子为信陵君。", "b": "《史记·魏公子列传》"}, {"t": "刘良佐者,故弘光四镇之一,封广昌伯。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "分封", "t": "古代帝王社祭,以五色土为坛,分封诸侯则割方色之土,以茅草包之,授予受封者,作为分封土地的表示"}, {"w": "封名", "t": "封爵赐姓"}, {"w": "封拜", "t": "赐爵授官"}, {"w": "封侯", "t": "封拜侯爵。"}]}, {"meaning": "堆土植树为界;培土。", "cites": [{"t": "将何以封矣。", "b": "《国语·楚语下》"}, {"t": "于是封之,崇四尺。", "b": "《礼记·檀弓下》"}, {"t": "开阡陌封疆。", "b": "《史记·商君书》"}], "words": [{"w": "封植", "t": "封土植树"}, {"w": "封树", "t": "堆土植树以固疆界"}, {"w": "封表", "t": "堆土以作标记"}, {"w": "封殖", "t": "壅土培育。"}]}, {"meaning": "古代帝王打胜仗筑土坛以祭天也叫封。", "cites": [{"t": "元嘉草草,封狼居胥,赢得仓皇北顾。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}]}, {"meaning": "堆土筑坟。", "cites": [{"t": "封王子比干之墓。", "b": "《礼记》"}]}, {"meaning": "用加盖印章的纸条贴在门、箱或其他容器的口上以防开启。", "cites": [{"t": "籍吏民,封府库,而待将军。", "b": "《史记·项羽本纪》"}, {"t": "公拆袄,出珠授之,封识宛然。", "b": "明·崔铣《记王忠肃公翱三事》"}]}, {"meaning": "界限,局限。", "cites": [{"t": "余不敢以麋鹿自封也。", "b": "徐光启《甘薯疏序》"}, {"t": "民族者,非封于汉属而已。", "b": "章炳麟《复仇是非论》"}]}, {"meaning": "封闭(以封记关闭,使不能动用、通行或随便打开);堵塞。", "cites": [{"t": "遂收盛樊於期之首,函封之。", "b": "《战国策·燕策》"}], "words": [{"w": "封贮", "t": "封存,贮藏"}, {"w": "封藏;封锢", "t": "严密关锁"}, {"w": "封关", "t": "封锁关口"}, {"w": "封灵", "t": "盖棺。"}]}, {"meaning": "高。", "cites": [{"t": "登封泰山,降坐明堂。", "b": "《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1367wx','持','1','chí','扌','9','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从手,寺声。本义:拿着)。"}, {"meaning": "同本义。", "cites": [{"t": "持,握也。", "b": "《说文》"}, {"t": "持弓矢审固。", "b": "《礼记·射义》"}, {"t": "有持盈。", "b": "《国语·越语》"}, {"t": "客持头往见楚王,王大喜。", "b": "晋·干宝《干将莫邪》"}, {"t": "秦王谓轲曰:“起,取武阳所持图。”", "b": "《战国策·燕策》"}], "words": [{"w": "持仗", "t": "手持武器"}, {"w": "持斧操斤", "t": "拿着斧头"}, {"w": "持笔;持戟", "t": ""}]}, {"meaning": "引申为掌握;控制。", "cites": [{"t": "悖乱不可以持国。", "b": "《吕氏春秋·察 今》"}, {"t": "夫仁义辩智,非所以持国也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "主持", "t": "负责掌握或处理"}, {"w": "持事", "t": "管理事务"}, {"w": "持权", "t": "掌权。"}]}, {"meaning": "保守,保持。", "cites": [{"t": "持久者知止足也。", "b": "《后汉书·列女传》"}, {"t": "犹引绳墨以持曲直。", "b": "《荀子·正名》"}], "words": [{"w": "持势", "t": "保持地位、权力"}, {"w": "保持", "t": "维持原状"}, {"w": "持世", "t": "维持世道"}, {"w": "持衡;持位", "t": "保守地位。"}]}, {"meaning": "搀扶;支持;支撑。", "cites": [{"t": "及丞相御史所持。", "b": "《汉书·刘向传》"}, {"t": "危而不持,颠而不扶,则将焉用彼相矣?", "b": "《论语》"}], "words": [{"w": "支持", "t": "给以鼓励或赞助"}, {"w": "持载;持扶", "t": "扶持。"}]}, {"meaning": "对抗,不相上下。", "cites": [{"t": "子与子家持之。", "b": "《左传·昭公元年》。疏:“奕棋谓不能相害为持。”"}], "words": [{"w": "僵持", "t": "相持不下"}, {"w": "持顽", "t": "任性。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1368wx','拷','1','kǎo','扌','9','','[{"pinyin": "kǎo", "defs": [{"meaning": "(形声。从手,考声。本义:打;拷打) 同本义。", "cites": [{"t": "不听非法拷人。", "b": "《魏书·刑罚志》"}], "words": [{"w": "拷较", "t": "拷问刑讯"}, {"w": "拷讯", "t": "拷打审问"}, {"w": "拷究", "t": "拷打审问"}, {"w": "拷掠", "t": "拷打逼供"}, {"w": "拷勘", "t": "拷问。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1369wx','拱','1','gǒng','扌','9','','[{"pinyin": "gǒng", "defs": [{"meaning": "(形声。从手,共声。本义:抱拳,敛手。两手在胸前相合,表示恭敬)。"}, {"meaning": "同本义。", "cites": [{"t": "拱,敛手也。", "b": "《说文》。注:“谓沓其手。右手在内,左手在外。男之吉拜尚左,女之吉拜尚右。凶拜反是。九拜必皆拱手。”"}, {"t": "子路拱而立。", "b": "《论语》"}, {"t": "颐羀垂拱。", "b": "《礼记·玉藻》"}, {"t": "与我其拱璧。", "b": "《左传·襄公二十八年》。注:“拱,谓合两手也。”"}, {"t": "拱把之桐梓。", "b": "《孟子·告子上》"}, {"t": "文武并用,垂拱而治。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "子路拱而立。", "b": "《论语·微子》"}], "words": [{"w": "拱默", "t": "拱手不言,以避免惹是非"}, {"w": "拱伏", "t": "两手抱拳以示服从。伏:屈服"}, {"w": "拱手听命", "t": "服从对方,不敢反抗"}, {"w": "拱候", "t": "拱手相候;恭候"}, {"w": "拱揖", "t": "拱手作揖以示敬意。"}]}, {"meaning": "围绕,环绕。", "cites": [{"t": "众星拱北辰。", "b": "晋·傅玄《明君》"}], "words": [{"w": "众星拱月;拱绕", "t": "环绕"}, {"w": "拱斗", "t": "环卫北斗星"}, {"w": "拱北", "t": "众星围绕北辰。"}]}, {"meaning": "肢体弯曲成弧形。", "cites": [{"t": "座上众精闻言,都拱身对老龙作礼。", "b": "《西游记》"}], "words": [{"w": "拱肩缩背", "t": ""}]}, {"meaning": "用粗嘴脸向上或向前顶掀。", "cites": [{"t": "野猪一夜工夫能拱完一亩红薯。", "b": "《猎户》"}], "words": [{"w": "猪拱土", "t": ""}]}, {"meaning": "两手合围,常用来表达树木的粗细。", "cites": [{"t": "尔何知!中寿,尔墓之木拱矣!", "b": "《左传·僖公三十二年》"}], "words": [{"w": "拱木", "t": "径围有两臂合围大的树"}, {"w": "拱把", "t": "拱:两手合围;把:一手满握。常用来比拟树木枝干的大小。"}]}, {"meaning": "大璧。", "cites": [{"t": "与我其拱璧,吾献其柩。", "b": "《左传·襄公二十八年》"}, {"t": "虽有拱璧,以先驷马。", "b": "《老子·六十二章》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1370wx','项','1','xiàng','工','9','','[{"pinyin": "xiàng", "defs": [{"meaning": "(形声。从页,工声。从页,与头有关。本义:脖子的后部)。"}, {"meaning": "同本义。", "cites": [{"t": "项,头后也。", "b": "《说文》"}, {"t": "延颈秀项,皓质呈露。", "b": "曹植《洛神赋》"}, {"t": "项背相望。", "b": "《后汉书·左雄传》"}], "words": [{"w": "项髻", "t": "挽发髻于颈后"}, {"w": "项窝", "t": "脖子后部的凹处。"}]}, {"meaning": "泛指人颈。", "cites": [{"t": "老魔将芭蕉扇插在后项衣领。", "b": "《西游记》"}, {"t": "项掣金锁。", "b": "唐·李朝威《柳毅传》"}, {"t": "青项金翅。", "b": "《聊斋志异·促织》"}], "words": [{"w": "项头", "t": "头与脖项"}, {"w": "项领", "t": "指颈部"}, {"w": "项缩", "t": "缩颈。形容畏惧的样子。"}]}, {"meaning": "春秋时国名 。在今河南省项城县东北。"}, {"meaning": "冠的后部。", "cites": [{"t": "宾右手执项,左手执前进客。", "b": "《仪礼·士冠礼》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1371wx','垮','1','kuǎ','土','9','','[{"pinyin": "kuǎ", "defs": [{"meaning": "(形声。从土,夸声。本义:倒塌,崩溃瓦解)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1372wx','挎','1','kuà','扌','9','','[{"pinyin": "kuà", "defs": [{"meaning": "胳膊弯起来挂着东西"}, {"meaning": "把东西挂在肩头、脖颈或挂在腰里", "words": [{"w": "挎包", "t": "常指皮革、人造革或帆布制、平底、附有背带的小包。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1373wx','城','1','chéng','土','9','','[{"pinyin": "chéng", "defs": [{"meaning": "(会意。从土,从成,成亦声。本义:城墙)。"}, {"meaning": "同本义 。都邑四周用作防御的高墙。一般分两重,里面的叫城,外面的叫郭,城字单用时,多包含城与郭。城郭对举时,只指城。", "cites": [{"t": "城,所以盛民也。", "b": "《说文》"}, {"t": "城郭沟池以为固。", "b": "《礼记·礼运》"}, {"t": "使老弱女子乘城。", "b": "《史记·田单列传》"}, {"t": "百雉而城。", "b": "《公羊传·定公十二年》。注:“天子周城,诸侯轩城。”"}, {"t": "城为保民为之也。", "b": "《谷梁传·隐公七年》"}, {"t": "城者,可以自守也。", "b": "《墨子·七患》"}, {"t": "青山横北郭,白水绕东城。", "b": "唐·李白《送友人》"}], "words": [{"w": "城内;城外;万里长城;城守", "t": "据城守御"}, {"w": "城曲", "t": "城墙角落的地方"}, {"w": "城铺", "t": "城上巡查的岗位"}, {"w": "城堵", "t": "城墙。"}]}, {"meaning": "古代王朝国都、诸侯封地、卿大夫采邑,都以有城垣的都邑为中心。皆可称城。", "cites": [{"t": "邑曰筑,都曰城。", "b": "《左传·庄公二十八年》"}], "words": [{"w": "城大", "t": "一城的长官。即城主"}, {"w": "城主", "t": "一城之主"}, {"w": "城辇", "t": "帝王所居的都市。也泛指京城"}, {"w": "城禁", "t": "城市的警戒防卫。"}]}, {"meaning": "城市。", "cites": [{"t": "今日割五城,明日割十城,然后得一夕安寝", "b": "宋·苏洵《六国论》"}], "words": [{"w": "东城,西城;城雕", "t": "城市雕塑。"}]}, {"meaning": "国。", "cites": [{"t": "土国城漕。", "b": "《诗·邶风·击鼓》"}]}, {"meaning": "筑城。", "cites": [{"t": "今吴是惧而城于郢。", "b": "《左传·昭公二十三年》"}], "words": [{"w": "城郭国", "t": "古时谓西域筑城定居的国家"}, {"w": "城干", "t": "筑城时埋置土中的木柱。"}]}, {"meaning": "守城。", "cites": [{"t": "县距刺史治所四十里,城嘉陵江南。", "b": "唐·孙樵《书何易于》"}], "words": [{"w": "城寨", "t": "防守用的围墙或栅栏"}, {"w": "城操", "t": "备边;备边士卒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1374wx','挟','1','xié','扌','9','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从手,夹声。本义:用胳膊夹住)。"}, {"meaning": "同本义。", "cites": [{"t": "挟,俾持也。", "b": "《说文》"}, {"t": "挟其枪。刈耨鑮。", "b": "《国语·齐语》"}, {"t": "右掖曰挟。", "b": "《管子·小匡》注"}, {"t": "挟经秉枹。", "b": "《国语·吴语》"}, {"t": "何冯弓挟矢。", "b": "《楚辞·天问》"}, {"t": "左挟弹,右摄丸。", "b": "《战国策》"}, {"t": "挟太山。", "b": "《孟子·梁惠王上》"}, {"t": "骑马挟矢。", "b": "明·魏禧《大铁椎传》"}, {"t": "操刀挟盾。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "挟匕首。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "腋下挟着一本书;挟枪;挟弓;挟尺", "t": ""}]}, {"meaning": "挟制。", "cites": [{"t": "今有奸雄曹操,挟寡人行势,当识也。", "b": "《三国志平话》"}, {"t": "今操已拥百万之众,挟天子而令诸侯。", "b": "《三国志·诸葛亮传》"}, {"t": "挟天子以征四方。", "b": "宋·司马光《资治通鉴》"}, {"t": "挟东宫二王。", "b": "明·顾炎武《复庵记》"}, {"t": "将挟兵力。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "挟养", "t": "挟制豢养"}, {"w": "挟挠", "t": "挟制扰乱"}, {"w": "挟今;要挟", "t": ""}]}, {"meaning": "怀抱,怀有。", "cites": [{"t": "挟持私虑(怀着个人打算)。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "挟仇", "t": "心怀仇恨"}, {"w": "挟私", "t": "心怀私念"}, {"w": "挟忿,挟怨;挟策", "t": "胸 怀计谋"}, {"w": "挟义", "t": "怀持正义"}, {"w": "挟奸", "t": "心怀奸计"}, {"w": "挟嫌;挟恨", "t": ""}]}, {"meaning": "携带。", "cites": [{"t": "挟飞仙以遨游,抱明月而长终。", "b": "苏轼《赤壁赋》"}], "words": [{"w": "挟册", "t": "携带书籍"}, {"w": "挟策", "t": "手拿书本"}, {"w": "挟子巢栖", "t": ""}]}, {"meaning": "占有,拥有。", "cites": [{"t": "位尊而无功,奉厚而无劳,而挟重器多也。", "b": "《战国策》"}]}, {"meaning": "倚仗,依恃。", "cites": [{"t": "不挟长,不挟贵,不挟兄弟而友。", "b": "《孟子》"}], "words": [{"w": "挟依,挟恃", "t": "依仗"}, {"w": "挟势", "t": "依仗权势。"}]}, {"meaning": "夹杂;夹带。", "cites": [{"t": "琼珉山积,不能无挟瑕之器。", "b": "《抱朴子·外篇》"}]}, {"meaning": "辅佐,从旁协助。", "cites": [{"t": "挟,辅也。", "b": "《广雅》"}], "words": [{"w": "挟佐;挟赞", "t": "辅佐"}, {"w": "挟辅", "t": ""}]}, {"meaning": "搀扶。", "cites": [{"t": "挟澄源。", "b": "《徐霞客游记·游黄山记》"}, {"t": "挟予以登。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1375wx','挠','1','náo','扌','9','','[{"pinyin": "náo", "defs": [{"meaning": "(形声。从手,尧声。本义:扰乱)。"}, {"meaning": "同本义。", "cites": [{"t": "挠,扰也。", "b": "《说文》"}, {"t": "挠乱百度。", "b": "《国语·吴语》。韦昭注:“挠,扰也。”"}, {"t": "挠乱国家,几危社稷。", "b": "《汉书·王莽传上》。颜师古注:“挠,扰也。”"}, {"t": "民以法难犯上,而上以法挠慈仁。", "b": "《韩非子·八经》"}, {"t": "匈奴之众易挠乱也。", "b": "《汉书·晁错传》"}, {"t": "挠以军法。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "挠乱", "t": "搅乱;扰乱"}, {"w": "挠滑", "t": "惑乱,扰乱"}, {"w": "挠正", "t": "扰乱正气"}, {"w": "挠动", "t": "扰乱骚动。"}]}, {"meaning": "搅,搅动。", "cites": [{"t": "挠,搅也。", "b": "《声类》"}, {"t": "手挠顾指。", "b": "《庄子·天地》。释文:“动也。”"}, {"t": "挠乱百度。", "b": "《国语·吴语》"}, {"t": "以指挠沸。", "b": "《荀子·议兵》"}, {"t": "使水浊者,鱼挠之。", "b": "《淮南子·说林》"}], "words": [{"w": "挠酒", "t": "搅和酒浆"}, {"w": "挠混", "t": "搅浑"}, {"w": "挠荡", "t": "搅扰激荡"}, {"w": "挠扰", "t": "搅拌"}, {"w": "挠搅", "t": "搅拌。"}]}, {"meaning": "阻挠。", "cites": [{"t": "于是众人竭力挠之。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "挠抑", "t": "阻挠抑止"}, {"w": "挠抗", "t": "阻挠抗拒"}, {"w": "挠阻", "t": "阻挠"}, {"w": "挠沮", "t": "阻挠"}, {"w": "挠格", "t": "阻挠,抗拒。"}]}, {"meaning": "屈服。", "cites": [{"t": "抑挠志以从君。", "b": "《国语·晋语》。注:“屈也。”"}, {"t": "秦王色挠。", "b": "《战国策·魏策》"}, {"t": "坚毅不挠。", "b": "孙文《黄花冈七十二烈士事略序》"}, {"t": "以坚毅不挠之精神,与民贼相搏。", "b": ""}], "words": [{"w": "挠志", "t": "挠屈志节"}, {"w": "百折不挠;不屈不挠;挠折", "t": "屈服"}, {"w": "挠弱", "t": "懦弱无能"}, {"w": "挠沮", "t": "屈从退缩"}, {"w": "挠屈", "t": "屈服"}, {"w": "挠挫", "t": "屈服"}, {"w": "挠节", "t": "屈节;屈从他人"}, {"w": "挠辞", "t": "屈服的言词"}, {"w": "挠法", "t": "枉法"}, {"w": "挠情", "t": "曲徇私情。"}]}, {"meaning": "弯曲。", "cites": [{"t": "栋挠。", "b": "《周易》"}, {"t": "其弓菑,则挠之。", "b": "《考工记·轮人》注"}], "words": [{"w": "挠折", "t": "弯曲折裂。"}]}, {"meaning": "弱。", "cites": [{"t": "弓不试则劲挠诬。", "b": "王符《潜夫论》"}], "words": [{"w": "挠弱", "t": "怯弱胆小"}, {"w": "挠坏", "t": "败坏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1376wx','政','1','zhēng zhèng','攵','9','','[{"pinyin": "zhēng", "defs": [{"meaning": "(zhēng)。"}, {"meaning": "征伐。", "cites": [{"t": "先为之政。", "b": "《管子·势》"}, {"t": "吴政荆。", "b": "《韩非子·内储下》"}, {"t": "诸侯力政。", "b": "《大戴礼记·用兵》"}]}, {"meaning": "征税。", "cites": [{"t": "宽政役。", "b": "《管子·小匡》"}, {"t": "相地而衰政。", "b": "《荀子·王制》"}, {"t": "庶民弛政。", "b": "《礼记·乐记》"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "(会意兼形声。从攴从正,正亦声。攴(pū)敲击。统治者靠皮鞭来推行其政治。“正”是光明正大。本义:匡正)。"}, {"meaning": "同本义。", "cites": [{"t": "政,正也。", "b": "《说文》"}, {"t": "政者,有所改更匡正。", "b": "《论语·有政》马注"}, {"t": "必从上之政下。", "b": "《墨子·天志上》"}, {"t": "俚句戏呈伯母大人粲政。", "b": "清·秋瑾《致琴文书》"}], "words": [{"w": "正己", "t": ""}]}, {"meaning": "主持政事。", "cites": [{"t": "盖善政者,视俗而施教,察失而立防,威德更兴,文武迭用。", "b": "《后汉书》"}], "words": [{"w": "政本", "t": "为政的根本"}, {"w": "政主", "t": "执政者"}, {"w": "政官", "t": "掌管军政的官员"}, {"w": "政术", "t": "施政的方法"}, {"w": "政要", "t": "施政要领"}, {"w": "政理", "t": "为政之道"}, {"w": "政路", "t": "为政的途径。"}]}, {"meaning": "政治;政事。", "cites": [{"t": "其政不获。", "b": "《诗·大雅·皇矣》。释文:“政,政教也。”"}, {"t": "使帅其属而掌邦政。", "b": "《周礼·夏官》"}, {"t": "荆国之为政。", "b": "《吕氏春秋·察今》"}, {"t": "论厚薄为之政。", "b": "《韩非子·五蠹》"}, {"t": "上下肃然,称为政理。", "b": "《后汉书·张衡传》"}, {"t": "元政紊弛。", "b": "明·高启《书博鸡者事》"}, {"t": "言时政者。", "b": "清·张廷玉《明史》"}, {"t": "沽名乱政。", "b": ""}], "words": [{"w": "政化", "t": "政治和教化"}, {"w": "政地", "t": "处理政事的地方"}, {"w": "政争", "t": "政治斗争"}, {"w": "政役", "t": "政事役使"}, {"w": "政拙", "t": "拙于政事"}, {"w": "政制", "t": "政治制度"}, {"w": "政俗", "t": "政治与风俗。"}]}, {"meaning": "政策;法令。", "cites": [{"t": "先王之政。", "b": "宋·王安石《答司马谏议书》"}, {"t": "袁有守多惠政。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "政刑", "t": "政令和刑罚"}, {"w": "政典", "t": "政策和制度"}, {"w": "政条", "t": "政令"}, {"w": "政道", "t": "施政的方略。"}]}, {"meaning": "官长;主事者。", "cites": [{"t": "政诸侯。", "b": "《墨子·非命上》"}, {"t": "以为大政。", "b": "《左传·昭公十五年》"}, {"t": "周公作立政。", "b": "《书·立政》"}], "words": [{"w": "学政;盐政", "t": ""}]}, {"meaning": "政权。", "cites": [{"t": "州吁果杀其君而夺之政。", "b": "《韩非子·内储说下》"}]}, {"meaning": "策略 其次伐兵,下政攻城。——《孙子》。"}, {"meaning": "朝廷;政府机关。", "cites": [{"t": "在其政府,与韩琦同心辅政。", "b": "脱脱《宋史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1377wx','赴','1','fù','走','9','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从走,卜声。从“走”的字、多与“跑”、“走”有关。本义:奔向,奔赴。多指奔向危险的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "赴,趋也。", "b": "《说文》"}, {"t": "万里赴戎机,关山度若飞。", "b": "《乐府诗集·木兰诗》"}, {"t": "天下之欲疾其君者,皆欲赴愬于王。", "b": "《孟子·梁惠王上》"}, {"t": "以赴礼者。", "b": "《左传·昭公二十五年》"}, {"t": "赴水则接腋持颐。", "b": "《庄子·秋水》"}], "words": [{"w": "赴履", "t": "奔赴"}, {"w": "赴质", "t": "奔赴目标"}, {"w": "赴助", "t": "赴救"}, {"w": "赴急", "t": "往救急难"}, {"w": "赴援", "t": "赴救。"}]}, {"meaning": "前往;去;到;至,到达。", "cites": [{"t": "长子迈将赴饶之德兴尉,送之至湖口。", "b": "宋·苏轼《石钟山记》"}, {"t": "吾今且赴府,不久当归还。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "赴吊", "t": "前往吊丧"}, {"w": "赴市", "t": "到市集上去"}, {"w": "赴考", "t": "前往应试"}, {"w": "赴哀", "t": "奔丧"}, {"w": "赴接", "t": "前往救援、接应。"}]}, {"meaning": "报丧(古人讣告字只作赴者,取急疾之意。)。", "cites": [{"t": "死必赴。", "b": "《礼记·文王世子》"}, {"t": "凡崩薨,不赴则不书。", "b": "《左传·文公十四年》"}, {"t": "周烈王崩,诸侯皆吊,齐后往。周怒,赴于齐曰。", "b": "《战国策·赵策三》"}, {"t": "赴者未至,则哭于巷,哀于馆。", "b": "《仪礼·聘礼》"}], "words": [{"w": "赴闻", "t": "报丧"}, {"w": "赴告", "t": "春秋时,各国将贵族丧亡祸福等事告诉别国。凶事叫赴,其他的事叫告。今俗称讣告。"}]}, {"meaning": "跳进,举身投入。", "cites": [{"t": "揽裙脱丝履,举身赴清池。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "赴海归神", "t": "跳海而死"}, {"w": "赴鼎", "t": "跳入汤镬而死"}, {"w": "赴险", "t": "进入险地"}, {"w": "赴蹈", "t": "赴汤蹈火。献身。"}]}, {"meaning": "投身;参与。", "cites": [{"t": "欲以客往赴秦军,与赵国俱死。", "b": "《史记·魏公子列传》"}], "words": [{"w": "赴命", "t": "奔命,拼命努力。"}]}, {"meaning": "向前倾跌。", "cites": [{"t": "穷而无子者,靡得相鬻而养之,勿使赴于沟浍之中。", "b": "《管子·轻重甲》"}], "words": [{"w": "病赴", "t": "因病跌倒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1378wx','赵','1','zhào','走','9','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从走,肖声。本义:快走) 同本义。", "cites": [{"t": "趙,趋趙也。", "b": "《说文》"}, {"t": "趙,及也。", "b": "《广雅》"}, {"t": "天子北征,赵行囗舍。", "b": "《穆天子传》。郭璞注:“赵,犹超腾。”"}]}, {"meaning": "字亦作“踃”。", "cites": [{"t": "简惰跳踃般纷絮兮。", "b": "傅毅《舞赋》"}, {"t": "踃,跳也。字之作逍。", "b": "《埤仓》"}]}, {"meaning": "古国名。"}, {"meaning": "周穆王封造父于赵,故址在今山西省赵城县西南。"}, {"meaning": "战国七雄之一。在今山西北部、河北西部和南部一带。", "cites": [{"t": "赵将括。(赵国的将军赵括。)", "b": "汉·刘向《列女传》"}, {"t": "遗赵王书。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "赵王于是遂遣。", "b": ""}, {"t": "赵主之子孙。", "b": "《战国策·赵策》"}]}, {"meaning": "东晋十六国之一。在今河北、山西、河南、陕西各一部分。史称“前赵”。"}, {"meaning": "东晋十六国之一。羯族石勒灭前赵后称帝,史称“后赵”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1379wx','挡','1','dǎng dàng','扌','9','','[{"pinyin": "dǎng", "defs": [{"meaning": "(形声。从手,当声。本义:阻拦;抵挡)。"}, {"meaning": "同本义。", "cites": [{"t": "攩,推也。", "b": "《方言十》"}, {"t": "挡,遮遏也。", "b": "《正字通》"}], "words": [{"w": "挡人牌", "t": "挡箭牌。在前边极力承担困难的人"}, {"w": "挡手", "t": "商店经理;作经纪的。"}]}]}, {"pinyin": "dàng", "defs": [{"meaning": "——见“摒挡”(bìngdàng)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1380wx','拽','1','yè zhuāi zhuài','扌','9','','[{"pinyin": "yè", "defs": [{"meaning": "“抴”。拉,牵引。如 :拽步(拉开脚步);拽扶(牵扶);拽扎(绷紧;捆紧)。"}, {"meaning": "携带。", "cites": [{"t": "(盖道云)便把札子取了出来 ,给大家瞧了一瞧,仍旧拽在身上。", "b": "《官场现形记》"}]}, {"meaning": "短桨。一说船舷。", "cites": [{"t": "今又促装下邑,浪拽上京。", "b": "《文选·孔稚圭·北山移文》"}]}]}, {"pinyin": "zhuāi", "defs": [{"meaning": "", "words": [{"w": "把皮球拽出去", "t": ""}]}]}, {"pinyin": "zhuài", "defs": [{"meaning": "", "words": [{"w": "生拉硬拽;一把拽住不放", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1381wx','哉','1','zāi','口','9','','[{"pinyin": "zāi", "defs": [{"meaning": "(形声。本义:语气词。《说文》:“言之间也。”表感叹)。"}, {"meaning": "同本义。"}, {"meaning": "表示感叹,相当于“啊”。", "cites": [{"t": "幸甚至哉。", "b": "曹操《步出夏门行》"}, {"t": "非人哉。", "b": "《世说新语·方正》"}, {"t": "旦旦有是哉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "变诈几何哉。", "b": "《聊斋志异·狼三则》"}, {"t": "美哉,我少年中国。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "远哉遥遥;快哉此风;命不易哉;谁不为之痛心哉", "t": ""}]}, {"meaning": "表示疑问或反问,相当于“呢”或“吗”。", "cites": [{"t": "安知鸿鹄之志哉。", "b": "《史记·陈涉世家》"}, {"t": "岂独一琴哉。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "岂主之子孙不必善哉。", "b": "《聊斋志异·促织》"}, {"t": "岂独一箸间哉。", "b": "清·周容《芋老人传》"}, {"t": "顾不如蜀鄙之僧哉?(哉,表示反问语气,相当于“吗”。)", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "以此为治,岂不难哉?吾又何能为哉?", "t": ""}]}, {"meaning": "表示测度,相当于“吧”。", "cites": [{"t": "我其试哉!", "b": "《书·尧典》"}], "words": [{"w": "我岂有所失哉!", "t": ""}]}, {"meaning": "表示祈使语气,相当于“吧”。", "cites": [{"t": "振振君子,归哉归哉!", "b": "《诗·召南》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1382wx','挺','1','tǐng','扌','9','','[{"pinyin": "tǐng", "defs": [{"meaning": "(形声。从手,廷声。本义:拔出)。"}, {"meaning": "同本义。", "cites": [{"t": "挺,拔也。", "b": "《说文》"}, {"t": "挺剑而起。", "b": "《战国策·魏策》"}, {"t": "尉剑挺。", "b": "《史记·陈涉世家》"}], "words": [{"w": "挺举;挺挏", "t": "上下推动。"}]}, {"meaning": "生出;生长。", "cites": [{"t": "荔挺。", "b": "《吕氏春秋·仲冬》。注:“生也。”"}], "words": [{"w": "挺茂", "t": "生长茂盛。"}]}, {"meaning": "动摇。", "cites": [{"t": "不足以挺其心矣。", "b": "《吕氏春秋》"}]}, {"meaning": "直,伸直,撑直。", "cites": [{"t": "不复挺者。", "b": "《荀子·劝学》"}, {"t": "曲挺纵横。", "b": "《徐霞客游记·游黄山记》"}]}, {"meaning": "睡 。", "words": [{"w": "挺死尸", "t": "骂人睡得死"}, {"w": "挺床", "t": "詈词。睡觉"}, {"w": "挺觉", "t": "睡眠的谑词或詈词。"}]}, {"meaning": "使身体处于直立状态 。", "words": [{"w": "挺争", "t": "挺身争斗。"}]}, {"meaning": "勉强支撑 。", "words": [{"w": "挺折腰", "t": "到了顶,竭尽全力"}, {"w": "你挺得住吗", "t": ""}]}, {"meaning": "突出 。", "words": [{"w": "挺着肚子;他把头挺得高高的", "t": ""}]}, {"meaning": "忍受痛苦 。", "words": [{"w": "挺过去;挺住", "t": ""}]}, {"meaning": "前进。", "cites": [{"t": "单身挺战,众莫能当。", "b": "《宋书》"}]}, {"meaning": "顶住,抵抗 。", "words": [{"w": "挺撞", "t": "顶撞"}, {"w": "谁能挺敌;挺刑", "t": "不屈服于刑罚。"}]}, {"meaning": "脱身 。"}, {"meaning": "如:挺走(退走);挺逸(脱逃)。"}, {"meaning": "杰出;特出。", "cites": [{"t": "自谓颇挺出,立登要路津。", "b": "杜甫《奉赠韦左丞丈二十二韵》"}], "words": [{"w": "挺率", "t": "卓越特出"}, {"w": "挺秀", "t": "杰出,俊秀"}, {"w": "挺杰", "t": "卓越杰出"}, {"w": "挺特", "t": "超群特出"}, {"w": "挺冠", "t": "杰出超群。"}]}, {"meaning": "直率。", "cites": [{"t": "我心挺挺。", "b": "《左传·襄公五年》"}], "words": [{"w": "挺切", "t": "直率恳切"}, {"w": "挺正", "t": "正直"}, {"w": "挺确", "t": "刚正"}, {"w": "挺挺", "t": "正直的样子。"}]}, {"meaning": "生硬 。", "words": [{"w": "挺腰子", "t": "摆架子,耍威风"}, {"w": "挺触", "t": "顶撞,触犯"}, {"w": "直挺挺地站了起来", "t": ""}]}, {"meaning": "非常 。", "words": [{"w": "挺好;病得挺重的", "t": ""}]}, {"meaning": "颇,相当 。", "words": [{"w": "今天挺冷", "t": ""}]}, {"meaning": "用于某些挺直物。", "cites": [{"t": "荐脯五挺。", "b": "《仪礼·乡礼酒礼》"}], "words": [{"w": "一挺机关枪", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1383wx','括','1','kuò','扌','9','','[{"pinyin": "kuò", "defs": [{"meaning": "(形声。本义:结,扎束)。"}, {"meaning": "用绳或带子结扎,捆束。", "cites": [{"t": "括,絜也。", "b": "《说文》。按,絜者,束也。"}, {"t": "括囊。", "b": "《易·坤》。注:“结也。”"}, {"t": "括,约束也。", "b": "《韩诗章句》"}, {"t": "卫北宫括。", "b": "《左传·襄公三十年》。注:“子结。”"}, {"t": "羌人括领。", "b": "《淮南子·齐俗》"}, {"t": "内狼于囊,遂括囊口。(内:纳。)", "b": "马中锡《中山狼传》"}], "words": [{"w": "括囊", "t": "结扎袋口"}, {"w": "括发", "t": "束发"}, {"w": "括结", "t": "结扎;捆缚"}, {"w": "括约肌", "t": ""}]}, {"meaning": "引申为约束。", "cites": [{"t": "以礼括其君,使人于善也。", "b": "《孔丛子》"}]}, {"meaning": "阻滞;闭塞。", "cites": [{"t": "君子藏器于身,待时而动,何不利之有?动而不括,是以出而有获,语成器而动者也。", "b": "《易·系辞下》"}]}, {"meaning": "包容,包括。", "cites": [{"t": "囊括四海。", "b": "贾谊《过秦论》"}], "words": [{"w": "总括;概括", "t": "把事物的共同特点归结在一起。"}]}, {"meaning": "搜求。", "cites": [{"t": "时大括人为军士。", "b": "《北史·孙搴传》"}], "words": [{"w": "括次", "t": "搜求比次"}, {"w": "括索", "t": "搜索;探索"}, {"w": "括责", "t": "搜求"}, {"w": "括率", "t": "搜刮;聚敛"}, {"w": "括取", "t": "搜刮,掠夺"}, {"w": "括刷", "t": "搜刮。"}]}, {"meaning": "汇集。", "cites": [{"t": "日之夕矣,中羊下括。", "b": "《诗·卫风·君子于役》"}], "words": [{"w": "括撮", "t": "会聚"}, {"w": "括总", "t": "会集在一起;总括。"}]}, {"meaning": "法。"}, {"meaning": "箭的末端。", "cites": [{"t": "括而羽之,镞而砺之。", "b": "《孔子家语·子路初见》"}], "words": [{"w": "括羽", "t": "箭末羽毛"}, {"w": "括蔽", "t": "谓箭穿蔽体之物"}, {"w": "括镞", "t": "箭镞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1384wx','垢','1','gòu','土','9','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从土,后声。本义:污秽,尘土一类的脏东西)。"}, {"meaning": "同本义。", "cites": [{"t": "垢,浊也。", "b": "《说文》"}, {"t": "茫然彷徨乎尘垢之外。", "b": "《庄子·大宗师》"}, {"t": "不吹毛而求小疵,不洗垢而察难知。", "b": "《韩非子·大体》"}, {"t": "爬罗剔块,刮垢磨光。", "b": "韩愈《进学解》"}, {"t": "不获世之滋垢,皭然泥而不滓者也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "积垢;尘垢;泥垢;牙垢;污垢;耳垢", "t": ""}]}, {"meaning": "耻辱,因不名誉而产生的羞耻感。", "cites": [{"t": "受天下之垢。", "b": "《庄子·让王》"}, {"t": "国君含垢。", "b": "《左传·宣公十五年》"}]}, {"meaning": "污秽不洁。", "cites": [{"t": "亦不敢服垢弊以矫俗干名,但顺吾性而已。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "蓬头垢面;垢氛", "t": "污浊的气氛"}, {"w": "垢尘;垢俗", "t": "尘俗"}, {"w": "垢染", "t": "污染"}, {"w": "垢玩", "t": "污浊混乱,玩忽荒怠。"}]}, {"meaning": "耻辱。", "cites": [{"t": "维彼不顺,征以中垢。", "b": "《诗·大雅·桑柔》"}, {"t": "人皆取先,己独取后,曰受天下之垢。", "b": "《庄子·天下》"}], "words": [{"w": "含垢", "t": "忍受耻辱"}, {"w": "忍垢", "t": "忍受耻辱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1385wx','拴','1','shuān','扌','9','','[{"pinyin": "shuān", "defs": [{"meaning": "(形声。从手,全声。本义:绑住)。"}, {"meaning": "同本义。", "cites": [{"t": "拴了倪二,拉着就走。", "b": "《红楼梦》"}], "words": [{"w": "把你的马拴在树上;应当把恶狗拴好;拴束", "t": "捆绑;收拾。"}]}, {"meaning": "插上门闩。", "cites": [{"t": "武松把门关上,拴了。", "b": "《水浒传》"}]}, {"meaning": "门闩。", "cites": [{"t": "门子只得捻脚捻手,把拴拽了。", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1386wx','拾','1','shí shè','扌','9','','[{"pinyin": "shí", "defs": [{"meaning": "(形声。从手,合声。本义:捡取,从地上捡起来)。"}, {"meaning": "同本义。", "cites": [{"t": "拾,掇也。", "b": "《说文》"}, {"t": "犹拾遗于涂,摭弃于野。", "b": "《论衡·逢遇》"}, {"t": "故周之夺殷也,拾遗于庭。", "b": "《韩非子·安危》"}, {"t": "犹拾瀋也。", "b": "《左传·哀公三年》"}, {"t": "俯有拾,仰有取。", "b": "《史记·货殖列传》"}, {"t": "志士不饮盗泉之水,廉者不受嗟来之食,况拾遗求利以污其行乎!", "b": "《后汉书·列女传》"}, {"t": "拾视之,非字而画。", "b": "《聊斋志异·促织》"}], "words": [{"w": "拾粪;拾麦穗儿;拾毛", "t": "拣界外球。毛:用毛充塞内部的球"}, {"w": "拾芥", "t": "拾取地上的小草。比喻取之极易"}, {"w": "拾石为砚", "t": "从地上拾起一块石头用作砚台"}, {"w": "拾夺", "t": "拾掇;收拾"}, {"w": "拾拣", "t": "拣取"}, {"w": "拾翠", "t": "拾取翠鸟羽毛以为首饰"}, {"w": "拾沈", "t": "拾取汁水。"}]}, {"meaning": "收敛,收集。", "cites": [{"t": "妇人拾蚕。", "b": "《韩非子·说林下》"}, {"t": "拾发以将乘矢。", "b": "《仪礼·大射仪》"}, {"t": "请拾投。", "b": "《礼设·投壶》"}, {"t": "萧何入秦,收拾文书。", "b": "《论衡·别通》"}], "words": [{"w": "拾骨", "t": "收拾遗骨改葬"}, {"w": "拾菜", "t": "采撷野菜"}, {"w": "拾尘", "t": "本指捡起饭中的灰尘,后借为引起误会而猜疑"}, {"w": "拾集", "t": "收集"}, {"w": "拾摭", "t": "收集"}, {"w": "拾纂", "t": "收集编纂。"}]}, {"meaning": "十,数目,九加一所得,汉字数目‘十’的大写"}]}, {"pinyin": "shè", "defs": [{"meaning": "沿着台阶一级一级地登上", "words": [{"w": "拾级", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1387wx','挑','1','tiāo tiǎo','扌','9','','[{"pinyin": "tiāo", "defs": [{"meaning": "(本义的挑读tiǎo,挖取)。"}, {"meaning": "用肩膀担。", "cites": [{"t": "担挑双草履,壁依一乌藤。", "b": "陆游《自题传神》。"}], "words": [{"w": "挑力", "t": "挑担。以肩荷物"}, {"w": "挑包", "t": "肩挑包裹"}, {"w": "挑码头", "t": "在码头上挑运东西"}, {"w": "从对门坡上挑柴火;挑米;挑油;挑谷", "t": ""}]}, {"meaning": "引申为承担;担当 。", "words": [{"w": "挑头的", "t": "领头,带头"}, {"w": "挑家过日子;挑担子", "t": "承担责任或担负重任。"}]}, {"meaning": "挑选。", "cites": [{"t": "你不嫌不好,挑两块去好了。", "b": "《红楼梦》"}], "words": [{"w": "挑兵", "t": "选募兵"}, {"w": "挑补", "t": "挑选补官"}, {"w": "挑踢", "t": "挑选"}, {"w": "挑撮", "t": "撷章摘句"}, {"w": "挑嘴", "t": "挑拣食物。"}]}, {"meaning": "挑剔。", "cites": [{"t": "他再不放人一点儿,专会挑人。", "b": "《红楼梦》"}], "words": [{"w": "挑抉", "t": "挑剔"}, {"w": "挑刺", "t": ""}]}, {"meaning": "窃取。", "cites": [{"t": "却至挑天。", "b": "《国语》"}]}, {"meaning": "挖取。", "cites": [{"t": "时挑野菜和根煮。", "b": "唐·杜荀鹤《山中寡妇》"}]}, {"meaning": "抬举。", "cites": [{"t": "只要六老爷别的事上多挑他们姐儿们就是了,这一席酒,我们效六老爷的劳。", "b": "《儒林外史》"}]}, {"meaning": "用于成挑儿的东西。", "words": [{"w": "一挑水;一挑柴火", "t": ""}]}, {"meaning": "修长貌。多指身材。", "cites": [{"t": "容长脸儿,长挑身材。", "b": "《红楼梦》"}]}, {"meaning": "轻佻。", "cites": [{"t": "入境观其风俗,其百姓朴,其声乐不流抉,其服不挑。", "b": "《荀子·强国》"}]}]}, {"pinyin": "tiǎo", "defs": [{"meaning": "(形声。从手,兆声。本义:挑拨,挑动)。"}, {"meaning": "同本义。", "cites": [{"t": "挑,挠也。", "b": "《说文》"}, {"t": "挠挑无极。", "b": "《庄子·太宗师》"}, {"t": "汉王欲挑战。", "b": "《汉书·高帝纪》"}, {"t": "故相如以琴心挑之。", "b": "《史记·司马相如传》"}, {"t": "目窕心与。", "b": "《文选·枚乘·七发》。注:“窕当为挑。史记曰:‘目挑心招’。张晏汉书注曰:‘挑,娆也。’”"}, {"t": "媒而挑之。", "b": "《列子·杨朱》"}], "words": [{"w": "挑三豁四", "t": "搬弄是非"}, {"w": "挑头子", "t": "挑起事端;借端生事"}, {"w": "挑眼", "t": "嫌弃;挑刺"}, {"w": "挑茶斡刺", "t": "寻事生非"}, {"w": "挑缀", "t": "挑拨"}, {"w": "挑拨弄火", "t": "挑逗;拨弄火舌"}, {"w": "挑引", "t": "挑逗,逗引"}, {"w": "挑泛", "t": "挑逗"}, {"w": "挑招", "t": "挑逗勾引"}, {"w": "挑狎", "t": "调戏"}, {"w": "挑情", "t": "挑动情爱"}, {"w": "挑发", "t": "挑动诱发"}, {"w": "挑谑", "t": "逗引,调笑。"}]}, {"meaning": "挖取 。", "words": [{"w": "挑野菜;挑耳;挑治", "t": "挑挖治病"}, {"w": "挑挖", "t": "挖掘"}, {"w": "挑补", "t": "挖补"}, {"w": "挑动", "t": "开挖"}, {"w": "挑浚", "t": "清除淤塞,开通河道"}, {"w": "挑剜", "t": "抠挖"}, {"w": "挑菜", "t": "挖菜。"}]}, {"meaning": "用竿子把东西举起或支起 。", "words": [{"w": "把帘子挑起来;挑拨", "t": "拨动灯芯使灯火明亮。"}]}, {"meaning": "用指尖、棍尖等刺或戳 。", "words": [{"w": "挑火;挑刺;挑灯;挑破水泡", "t": ""}]}, {"meaning": "显露。", "cites": [{"t": "贵人有过端,而说者明言礼义以挑其恶,如此者身危。", "b": "《韩非子》"}]}, {"meaning": "弹奏琵琶的一种指法,反手回拨。", "cites": [{"t": "轻拢慢捻抹复挑。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "汉字的笔画之一,由左斜上。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1388wx','垛','1','duǒ duò','土','9','','[{"pinyin": "duǒ", "defs": [{"meaning": "垛子;墙两侧或上头伸出的部分。", "cites": [{"t": "垜,堂塾也。从土,朶声。门堂之塾有左右。左右各有南向北向两塾,今俗谓门两边伸出小墙曰垛头。", "b": "《说文》"}], "words": [{"w": "垛口;垛迭", "t": "建筑物突出的部分,指门两旁伸出的墙"}, {"w": "垛楼", "t": "军官住的高楼。"}]}, {"meaning": "设置箭靶的小土墙。", "cites": [{"t": "罗灰修药灶,筑垛阅弓垜。", "b": "唐·元稹《江边四十韵》"}], "words": [{"w": "箭垛", "t": ""}]}]}, {"pinyin": "duò", "defs": [{"meaning": "堆,成堆的东西。", "words": [{"w": "柴火垛;麦垛", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1389wx','指','1','zhǐ','扌','9','','[{"pinyin": "zhǐ", "defs": [{"meaning": "手指。手掌的五个终端部分之一。", "cites": [{"t": "指,手指也。", "b": "《说文》"}, {"t": "骈拇枝指。", "b": "《庄子·骈拇》"}, {"t": "是犹伛身而好升高也,指其顶者愈众。", "b": "《荀子·儒效》"}, {"t": "指如削葱根。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "两鬓苍苍十指黑。", "b": "唐·白居易《卖炭翁》"}, {"t": "以指叩门。", "b": "明·归有光《项脊轩志》"}, {"t": "虽人有百手,手有百指,不能指其一端。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "指下", "t": "手指按下,比喻诊脉看病"}, {"w": "伸手不见五指;屈指可数;指甲,指爪", "t": "指纹痕迹,手指尖端,指端背面扁平的表皮角质层"}, {"w": "指尺", "t": "古时以中指的中节为一寸"}, {"w": "指掌", "t": "手指和手掌"}, {"w": "指语", "t": "哑语的一种,以手指形状、姿势表示拼音字母。"}]}, {"meaning": "足指也叫做指。", "cites": [{"t": "乃扪足曰:“虏中吾指。”", "b": "《史记·高祖本纪》"}]}, {"meaning": "近代误写作“趾”。"}, {"meaning": "意旨;意向。", "cites": [{"t": "其指极大。", "b": "《史记·屈原贾生列传》"}, {"t": "承从天之指。", "b": "《管子·侈靡》。注:“指,意也。”"}, {"t": "大将军阴受上指。", "b": "《汉书·李广传》"}, {"t": "乃论六家之要指。", "b": "《汉书·司马迁传》"}], "words": [{"w": "指约", "t": "旨意简约"}, {"w": "指略", "t": "要旨"}, {"w": "指象", "t": "天以景象示意"}, {"w": "指意", "t": "指意,意向。"}]}, {"meaning": "指向;指着。", "cites": [{"t": "自是指物作诗立就。", "b": "宋·王安石《伤仲永》"}, {"t": "微指左公。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "不能指其一端。", "b": "《虞初新志·秋声诗自序》"}, {"t": "右手指卷。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "指景", "t": "指着太阳,“指日心誓,叹以自明也”"}, {"w": "指天誓日", "t": "指着天、日发誓,表明心迹"}, {"w": "指东划西", "t": "指手划脚做手势。"}]}, {"meaning": "指定。", "cites": [{"t": "望路殊未穷,指期今已促。", "b": "唐·杜德舆《奉使宜春渡新淦江》"}], "words": [{"w": "指省", "t": "由官员出一笔钱,免去抽签,自己指定任职省分"}, {"w": "指克", "t": "指定期限"}, {"w": "指配", "t": "指定许配。"}]}, {"meaning": "指示。", "cites": [{"t": "辞也者,各指其所也。", "b": "《易·系辞上》"}], "words": [{"w": "指麾", "t": "发令调度;指挥"}, {"w": "指受", "t": "指注。受命,指示,指点"}, {"w": "指办", "t": "指派办理"}, {"w": "指裁", "t": "指示,裁夺。"}]}, {"meaning": "指点。", "cites": [{"t": "指迷团灵心讲射,擅巧技妙算谈天。", "b": "《镜花缘》"}], "words": [{"w": "指顾", "t": "手指目顾"}, {"w": "指受", "t": "指点;传授"}, {"w": "指诀", "t": "指点要诀"}, {"w": "指告", "t": "指点晓谕"}, {"w": "指喻", "t": "指正告知。"}]}, {"meaning": "指责。", "cites": [{"t": "里谚曰:“千人所指,无病而死。”", "b": "《汉书·王嘉传》"}], "words": [{"w": "指搠", "t": "指指点点;指手画脚"}, {"w": "指切", "t": "指摘;指责"}, {"w": "指首", "t": "指名告发"}, {"w": "指怒", "t": "议论指斥。"}]}, {"meaning": "诬指。", "cites": [{"t": "洒家又不曾杀你,你如何拿住洒家,妄指平人。", "b": "《水浒全传》"}], "words": [{"w": "指攀", "t": "招供时攀扯牵连别人"}, {"w": "妄指", "t": "无证诬告。"}]}, {"meaning": "竖起。", "cites": [{"t": "发尽上指冠。", "b": "《战国策·燕策》"}, {"t": "头发上指,目眥尽裂。", "b": "《史记·项羽本纪》"}], "words": [{"w": "直指", "t": "笔直指向"}, {"w": "指冠", "t": "头发直竖。"}]}, {"meaning": "美好。", "cites": [{"t": "不时宜,不敬交,…,虽指,非礼也。", "b": "《荀子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1390wx','垫','1','diàn','土','9','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从土,执声。本义:下陷,淹没)。"}, {"meaning": "同本义。", "cites": [{"t": "垫,下也。", "b": "《说文》"}, {"t": "垫,下也。凡屋而下曰垫。", "b": "《方言六》"}, {"t": "洪水滔天,浩浩怀山襄陵,下民昏垫。", "b": "《书·益稷》。郑注:“垫,陷也。”疏:“垫是下湿之名。”"}, {"t": "武功中水乡民三舍垫为池。", "b": "《汉书·王莽传下》"}, {"t": "则厕足而垫之。", "b": "《庄子·外物》"}], "words": [{"w": "垫没", "t": "下沉"}, {"w": "垫溺", "t": "陷溺"}, {"w": "垫裂", "t": "塌陷破裂"}, {"w": "垫陷", "t": "下陷。亦指陷入困境。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1391wx','挣','1','zhēng zhèng','扌','9','','[{"pinyin": "zhēng", "defs": [{"meaning": "撞;击。", "cites": [{"t": "摐金挣玉,吐宫咽征。", "b": "前蜀·贯休《长持经僧》"}]}, {"meaning": "用力张开。", "cites": [{"t": "你挣着口袋,我量与你么。", "b": "《陈州粜米》"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "用力摆脱。", "cites": [{"t": "那呆子左挣右挣,挣不得脱手。", "b": "《西游记》"}, {"t": "郑屠挣不起来,那把尖刀也丢在一边。", "b": "《水浒传》"}], "words": [{"w": "挣开;挣不脱手", "t": ""}]}, {"meaning": "用力支撑。", "cites": [{"t": "林冲挣的起来,被枷碍了,曲身不得。", "b": "《水浒全传》"}, {"t": "是有一个媳妇,赛过男子,尽挣得家住。", "b": "《初刻拍案惊奇》"}], "words": [{"w": "挣持", "t": "勉强支持"}, {"w": "挣扎", "t": "用力支撑或摆脱。"}]}, {"meaning": "用力。", "cites": [{"t": "众匠人大半尚兀自在那里挣趱未办的工程。", "b": "《水浒全传》"}], "words": [{"w": "挣挫", "t": "勉力摆脱"}, {"w": "挣脱", "t": "奋力摆脱"}, {"w": "挣揣", "t": "用力获取"}, {"w": "挣罗", "t": "用力追求"}, {"w": "挣趱", "t": "勉力赶做。"}]}, {"meaning": "用力获取;赚取。", "cites": [{"t": "昔年先父原没甚所遗,多亏我弟兄,挣得些小产业,只望弟兄相守到老,传至子侄等辈分析。", "b": "《醒世恒言》"}], "words": [{"w": "挣下基业;挣座", "t": "尽力争得;获取"}, {"w": "挣多少钱;一个月挣七十块钱", "t": ""}]}, {"meaning": "修饰。", "cites": [{"t": "梳裹箱儿里取明镜,把脸儿挣得光莹。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "挣额颅", "t": "修饰头面。"}]}, {"meaning": "发呆,发怔。", "cites": [{"t": "庙倒没去得成,倒把俺婆婆气了个挣。", "b": "《醒世姻缘传》"}, {"t": "瞥然一见如风的,有甚心情更待随喜?立挣了浑身森地!", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "挣挣", "t": "发呆的样子"}, {"w": "挣痴", "t": "发呆的样子。"}]}, {"meaning": "漂亮。", "cites": [{"t": "做为挣,百事抢,只少天衣,便是捻塑的观音像。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "挣挞", "t": "漂亮;俊俏"}, {"w": "挣四", "t": "漂亮的"}, {"w": "挣达", "t": "漂亮"}, {"w": "挣勤", "t": "漂亮的嫖客。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1392wx','挤','1','jǐ','扌','9','','[{"pinyin": "jǐ", "defs": [{"meaning": "(形声。从手,齐声。本义:推开;除去)。"}, {"meaning": "同本义。", "cites": [{"t": "挤,排也。", "b": "《说文》"}, {"t": "挤,推也。", "b": "《广雅》"}, {"t": "小人老而无子,知挤于沟壑矣。", "b": "《左传·昭公十三年》"}, {"t": "汉军却,为楚所挤。", "b": "《史记·项羽本纪》"}], "words": [{"w": "挤住了", "t": "凑上遇上而又推脱不开。"}]}, {"meaning": "排斥;排挤。", "cites": [{"t": "故其君因其修以挤之。", "b": "《庄子·人间世》"}, {"t": "抑有功而挤有罪。", "b": "《荀子·仲尼》"}], "words": [{"w": "挤抑", "t": "排挤压抑"}, {"w": "挤撮", "t": "合伙欺负;拿捏;排挤"}, {"w": "挤陷", "t": "排挤陷害。"}]}, {"meaning": "毁坏;损坏。", "cites": [{"t": "挤社稷,失宗庙。", "b": "《逸周书·武纪》"}], "words": [{"w": "挤讹头", "t": "找岔子进行敲诈勒索"}, {"w": "挤害", "t": "挤陷。陷害。"}]}, {"meaning": "簇聚;拥挤。", "cites": [{"t": "乌压压挤了一屋子。", "b": "《红楼梦》"}], "words": [{"w": "挤拃", "t": "拥挤"}, {"w": "挤匝", "t": "拥挤"}, {"w": "挤轧", "t": "拥挤"}, {"w": "挤拥", "t": "拥挤,拥塞。"}]}, {"meaning": "攒聚。", "cites": [{"t": "那些童生…挤眉弄眼,无所不为。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1393wx','拼','1','pīn','扌','9','','[{"pinyin": "pīn", "defs": [{"meaning": "绑。", "cites": [{"t": "武松定睛看时,却是两个人,把虎皮缝做衣裳,紧紧拼在身上。", "b": "《水浒传》"}]}, {"meaning": "随从。", "cites": [{"t": "拼,从也。", "b": "《尔雅》。郭璞注:“为随从。”"}]}, {"meaning": "拼命,不顾惜,舍弃。", "cites": [{"t": "不如拼博一笑。", "b": "《聊斋志异·促织》"}], "words": [{"w": "拼杀;拼到底;拼舍着脸", "t": "撕下脸;扳着脸"}, {"w": "拼命亡身", "t": "不顾一切的伤害自己"}, {"w": "拼死吃河豚", "t": "夸口;说大话。"}]}, {"meaning": "弹;拉开。", "cites": [{"t": "拼,古文抨同,谓弹绳墨为拼也。", "b": "唐·玄应《一切经音义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1394wx','挖','1','wā','扌','9','','[{"pinyin": "wā", "defs": [{"meaning": "(挖为穵的俗字。形声。从手,穵(wā)声。本作“穵”。穵,空大的意思。本义:掘)。"}, {"meaning": "镂,镂空。", "cites": [{"t": "头上戴着一顶挖云鹅黄片金里大红猩猩毡昭君套。", "b": "《红楼梦》"}], "words": [{"w": "挖云", "t": "镂穿成云头形的边饰"}, {"w": "挖垫", "t": "旧时女红之一。把布帛镂穿成各种花样,在后面垫上不同颜色的布帛做衬托"}, {"w": "挖镶", "t": "镂空镶嵌。"}]}, {"meaning": "掏取。用工具或手从物体内向外扒出。", "cites": [{"t": "见他袖子里头挖出一张片子来。", "b": "清·蘧园《负曝闲谈》"}], "words": [{"w": "挖耳朵;挖单", "t": "魔术师用的双层布单,泛指包袱皮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1395wx','按','1','àn','扌','9','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从手,安声。本义:用手向下压或摁)。"}, {"meaning": "同本义。", "cites": [{"t": "按,下也。谓手抑物使下。", "b": "《说文》"}, {"t": "于是天子乃按辔徐行。", "b": "《史记·绛侯周勃世家》"}, {"t": "项王按剑而跽曰。", "b": "《史记·项羽本记》"}, {"t": "缇骑按剑而前。", "b": "张溥《五人墓碑记》"}, {"t": "则以一平板按其面。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "按电钮;按铃;按手印", "t": ""}]}, {"meaning": "控制;抑止。", "cites": [{"t": "以按徂旅。", "b": "《诗·大雅·皇矣》"}, {"t": "按强助弱。", "b": "《管子·霸言》"}, {"t": "赵简子按兵而不动。", "b": "《吕氏春秋·召类》"}, {"t": "何不按兵束甲。", "b": "《资治通鉴》"}, {"t": "若街亭有兵把守,即当按兵不行。", "b": "《三国演义》"}], "words": [{"w": "按下此事不提;按不住心头怒火", "t": ""}]}, {"meaning": "考察,考验。", "cites": [{"t": "按诛五人。", "b": "明·张溥《五人墓碑记》"}, {"t": "影胡公按部。", "b": "《明史·海瑞传》"}], "words": [{"w": "按杀", "t": "查实处死"}, {"w": "按讨", "t": "查验究治。"}]}, {"meaning": "打。", "cites": [{"t": "按管调弦于茶坊酒肆。", "b": "孟元老《东京梦华录序》"}], "words": [{"w": "按曲", "t": "击节唱曲"}, {"w": "按键;按拍", "t": "打拍子"}, {"w": "按板", "t": "拍击板眼"}, {"w": "按鼓;按丝竹;按乐;按风琴", "t": ""}]}, {"meaning": "按摩,用手在人身上推、捏、揉。", "cites": [{"t": "其治导引按蹻。", "b": "《素问·异法方宜论》"}, {"t": "按金驹,立长沟,枇杷落尽茱萸秋。", "b": "袁宏道《拟古乐府》"}], "words": [{"w": "按跷", "t": "抚摩导引。"}]}, {"meaning": "巡视。", "cites": [{"t": "遂西定河南地,按榆溪旧塞。", "b": "《史记·卫将军骠骑列传》"}], "words": [{"w": "按察", "t": "巡行视察"}, {"w": "巡按", "t": "官名"}, {"w": "按察司", "t": "官名。提刑按察使司的简称。明、清时一省的司法和检察机关"}, {"w": "按临", "t": "按察考核;巡行到达。"}]}, {"meaning": "安置;安定。", "cites": [{"t": "余悉除去秦法,吏民皆按堵如故。", "b": "《汉书·高帝纪》"}, {"t": "按抚柔氐三千余落,拨徙以实关中。", "b": "《三国志·郭淮传》"}]}, {"meaning": "依据;依照;按照。", "cites": [{"t": "各按行伍。", "b": "《汉书·扬雄传》"}], "words": [{"w": "按理", "t": "按照常理"}, {"w": "按章;按期;按说", "t": "按照情理来说。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1396wx','挥','1','huī','扌','9','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从手,军声。本义:抛洒、甩出)。"}, {"meaning": "同本义。", "cites": [{"t": "挥,备也。", "b": "《说文》"}, {"t": "而挥之,谓振去之也。", "b": "《周礼·考工记·幌氏》"}, {"t": "饮玉爵者弗挥。", "b": "《礼记·曲礼》"}, {"t": "挥涕恋行在,道八犹恍惚。", "b": "杜甫《北征》"}, {"t": "既而挥之。", "b": "《左传·僖公二十三年》"}, {"t": "挥汗成雨。", "b": "《战国策·齐策》"}], "words": [{"w": "挥涕", "t": "洒泪,哭泣"}, {"w": "挥尘", "t": "拂尘"}, {"w": "挥墨", "t": "挥洒墨水。"}]}, {"meaning": "舞动;摇动。", "cites": [{"t": "挥手自兹去。", "b": "唐·李白《送友人》"}, {"t": "大呼挥椎。", "b": "明·魏禧《大铁椎传》"}, {"t": "急挥帜。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "挥刀奋斫。", "b": ""}], "words": [{"w": "挥楚", "t": "挥杖拷打"}, {"w": "挥羽", "t": "挥动羽扇"}, {"w": "挥弄", "t": "挥动"}, {"w": "挥棹", "t": "摇动长桨。"}]}, {"meaning": "挥霍。", "cites": [{"t": "纷纷挥霍。", "b": "《庄子·文赋》。注:“疾貌。”"}], "words": [{"w": "挥金", "t": "散发或挥霍钱财"}, {"w": "挥攉", "t": "豪奢;任意浪费财物。"}]}, {"meaning": "运动;移动。", "cites": [{"t": "天浑而挥,故其运不已。", "b": "《太玄·玄告》"}]}, {"meaning": "飞翔。", "cites": [{"t": "终奋翼而高挥。", "b": "潘岳《西征赋》"}], "words": [{"w": "挥忽", "t": "飘然而逝。"}]}, {"meaning": "旗幡", "cites": [{"t": "戎士介而扬挥。", "b": "张衡《东京赋》"}, {"t": "登高冈而击鼓吹,扬素挥以启降路。", "b": "《文选·陈琳·为袁绍檄豫州文》"}]}, {"meaning": "光辉", "cites": [{"t": "六爻发挥。", "b": "《易·乾》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1397wx','挪','1','nuó','扌','9','','[{"pinyin": "nuó", "defs": [{"meaning": "(形声。从手,那声。本义:揉搓)。"}, {"meaning": "同本义。", "cites": [{"t": "两手自相挪。", "b": "韩愈《读东方朔杂事》"}]}, {"meaning": "移动,从一处移到另一处。", "cites": [{"t": "行者叩头,启上如来:“千万望挪玉一降。”", "b": "《西游记》"}], "words": [{"w": "挪玉", "t": "移动玉步;劳动大驾"}, {"w": "挪桌子;那个理发店挪地方了;把椅子挪开;挪步", "t": "移动脚步。"}]}, {"meaning": "移用。", "cites": [{"t": "他向日挪我的五十两银子,得便叫他算还给我。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1398wx','拯','1','zhěng','扌','9','','[{"pinyin": "zhěng", "defs": [{"meaning": "(形声。从手,丞(chéng)声。本义:向上举)。"}, {"meaning": "同本义。", "cites": [{"t": "艮期腓,不拯其随。", "b": "《易·艮》。王弼注:“随,谓趾也。止其腓,故其趾不拯也。”孔颖达疏:“拯,举也。”"}]}, {"meaning": "救济;援救。", "cites": [{"t": "吾必尽吾力以拯吾村。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "起而拯之。", "b": ""}], "words": [{"w": "拯弊", "t": "匡救衰病"}, {"w": "拯世", "t": "救世"}, {"w": "拯物", "t": "济世"}, {"w": "拯恤", "t": "援助;救济"}, {"w": "拯抚", "t": "救济安抚"}, {"w": "拯济", "t": "救助;救济。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1399wx','某','1','mǒu','木','9','','[{"pinyin": "mǒu", "defs": [{"meaning": "(象形。金文字形。像木上结一个果实,本是“梅”的象形。(méi)本义:梅)。"}, {"meaning": "指一定的不明说的人或事物。", "cites": [{"t": "如古人某。", "b": "清·周容《芋老人传》"}, {"t": "狂生某者。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "太监某守辽东。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "某亦守法。", "b": ""}, {"t": "王某。(王安石。古人作文起稿,写到自己的名字,往往只作“某”,或在“某”上冠姓,以后誊写时才把姓名写出。根据书稿编的文集,也常保留“某”的字样)。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "某人;某天;某官某(某某官(叫)某某的(人)某,文言虚指代词此处前一个代此人官职,后一个代他的姓名", "t": ""}, {"w": "某等", "t": "我等,我们"}, {"w": "某们", "t": "我们,某是代词"}, {"w": "某舍", "t": "犹某公子。"}]}, {"meaning": "指不定的不说明的人或事物。", "cites": [{"t": "某所,而母立于兹。", "b": "明·归有光《项脊轩志》"}, {"t": "某年月日。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "畿辅某官。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "决斗某所。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "某家", "t": "指不确定的一家。"}]}, {"meaning": "自称之词。指代“我”或本名。旧时谦虚的用法。", "cites": [{"t": "某启。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "某则以为;某不量敌;某知罪矣;我张某;某以", "t": "某矣。自称自己的代词,我"}, {"w": "某家", "t": "戏曲中自称之词"}, {"w": "某乙", "t": "自称代称"}, {"w": "某甲", "t": "自称之代词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1400wx','甚','1','shèn shén','甘','9','','[{"pinyin": "shèn", "defs": [{"meaning": "(会意。小篆字形,从甘,从匹。甘是快乐,匹,匹耦。沉溺于男女欢情。本义:异常安乐)。"}, {"meaning": "同本义。", "cites": [{"t": "甚,尤安乐也。", "b": "《说文》。徐灏注:“甚,古今字。女部。‘乐也。’通作耽、湛。《卫风·氓篇》:‘无与士耽。’《小雅·常隶篇》:‘和乐且湛。’皆甚字之本义。从甘匹,会意,昵其匹耦也;甘亦声”"}, {"t": "玄甚。", "b": "《老子》。注:“谓贪淫声色。”"}]}, {"meaning": "过分。", "cites": [{"t": "甚矣,汝之不惠。", "b": "《列子·汤问》"}, {"t": "此不亦畏之太甚而养之太过欤?", "b": "宋·苏轼《教战守》"}], "words": [{"w": "甚泰", "t": "衣着过于宽大。"}]}, {"meaning": "厉害,严重。", "cites": [{"t": "则吾斯役之不幸,未若复吾赋不幸之甚也。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "若是其甚与?", "b": "《孟子·梁惠王上》"}]}, {"meaning": "盛,大。", "cites": [{"t": "王之好乐,甚。", "b": "《孟子》。注:“大也。”"}, {"t": "观表甚欢。", "b": "《吕氏春秋》。注:“厚也。”"}, {"t": "甚口。", "b": "《左传·昭公二十八年》。疏:“谓大口也。”"}, {"t": "未刻,迅雷甚雨,乡民佯败,引入黄婆洞磨刀坑,杀死逆夷百余名。", "b": "《三元里抗英》"}]}, {"meaning": "深厚。", "cites": [{"t": "心不同兮媒劳,恩不甚兮轻绝。", "b": "《楚辞·九歌》"}]}, {"meaning": "重要。", "cites": [{"t": "如使人之所欲莫甚于生,则凡可以得生者何不用也!", "b": "《孟子·告子上》"}]}, {"meaning": "极端,极其;非常,异常。", "cites": [{"t": "水陆草木之花,可爱者甚蕃。", "b": "宋·周敦颐《爱莲说》"}, {"t": "吾家后日当甚贫。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "啊,甚是面熟,咱们是在哪里见过呢?他们的行动甚为迅速;他进步甚快;城镇相离甚远;甚为怏怏", "t": "很不高兴"}, {"w": "甚是次第", "t": "非常整齐"}, {"w": "甚当", "t": "很对;很正确"}, {"w": "甚悉", "t": "很正确"}, {"w": "甚溥", "t": "很普遍。"}]}, {"meaning": "诚,真。", "cites": [{"t": "左右皆曰甚然。", "b": "《战国策·秦策》。注:“谓诚也。”"}], "words": [{"w": "甚然", "t": "诚然。"}]}, {"meaning": "超过,胜过。", "cites": [{"t": "甚于水火。", "b": "《论语》。皇疏:“犹胜也。”"}, {"t": "孰知赋敛之毒,有甚是蛇者乎!", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "甚于", "t": "超过。"}]}, {"meaning": "引申为宠爱配偶 。又凡事之过皆曰甚。古者读若耽,声转为常枕切。”张舜徽注:“许云甘匹耦者,谓沈于色也。”。"}, {"meaning": "责备。", "cites": [{"t": "后世不以是少汉文,亦不以是甚贾谊。", "b": "宋·苏轼《田表圣奏议叙》"}]}]}, {"pinyin": "shén", "defs": [{"meaning": "疑问代词。什么", "words": [{"w": "甚般", "t": "哪般,什么;怎样"}, {"w": "甚的", "t": "甚底、甚迭。什么"}, {"w": "甚娘", "t": "甚末娘,什么娘。骂人的话。什么"}, {"w": "甚实", "t": "确实,很实"}]}, {"meaning": "为什么,怎么", "words": [{"w": "甚地", "t": "怎么"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1401wx','荆','1','jīng','艹','9','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从艸,刑声。本义:一种灌木)。"}, {"meaning": "灌木名。又名楚。", "cites": [{"t": "荆,楚木也。", "b": "《说文》"}, {"t": "以牡荆书幡。", "b": "《汉书·郊祀志》。注:“作幡柄也。”"}, {"t": "白刑堪为履。", "b": "《广州记》"}]}, {"meaning": "荆条。古代用为刑杖。", "cites": [{"t": "肉袒负荆。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "荆子", "t": "荆条作的挞具"}, {"w": "荆朴", "t": "鞭笞,杖击"}, {"w": "荆门", "t": "柴门"}, {"w": "荆革", "t": "荆条皮鞭。鞭笞用的刑具"}, {"w": "荆室", "t": "用荆条搭建的屋舍;借指穷苦人家"}, {"w": "荆冠", "t": "用荆条编的帽子。"}]}, {"meaning": "荆山的简称。", "words": [{"w": "荆玉", "t": "荆山之玉;喻美质贤才"}, {"w": "荆山玉", "t": "荆山产的美玉。相传楚卞和得璞玉于荆山"}, {"w": "荆襄", "t": "泛指古荆州及襄阳郡地区"}, {"w": "荆岑", "t": "荆山。泛指古楚国境内的高山。"}]}, {"meaning": "古国名。", "cites": [{"t": "荆之地。", "b": "《墨子·公输》"}, {"t": "荆有云梦。", "b": ""}, {"t": "荆有长松。", "b": ""}, {"t": "荆人欲袭宋。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "荆凡(西周时代的荆国(楚国)和凡国", "t": ""}, {"w": "荆尸", "t": "春秋时楚军阵法名"}, {"w": "荆王", "t": "楚王"}, {"w": "荆巫", "t": "荆楚的巫祝"}, {"w": "荆吴", "t": "春秋时的楚国与吴国。后泛指长江中下游地区。"}]}, {"meaning": "古九州之一荆州的简称。", "cites": [{"t": "正南曰荆州。", "b": "《周礼·职方氏》"}, {"t": "荆州之民附操者。", "b": "《资治通鉴》"}], "words": [{"w": "荆州瘿", "t": "古代流行于荆州一带的颈生囊状赘生物的疾病"}, {"w": "荆南", "t": "荆州一带。亦泛指南方"}, {"w": "荆扬", "t": "荆州和扬州。亦泛指长江中下游地区。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1402wx','茸','1','róng','艹','9','','[{"pinyin": "róng", "defs": [{"meaning": "(形声。本义:草初生时又细又柔软) 同本义。", "cites": [{"t": "茸,草茸茸貌。", "b": "《说文》"}, {"t": "在阘茸之中。", "b": "司马迁《报任安书》。注:“细毛也。”"}], "words": [{"w": "茸壑", "t": "长着青草、苔藓的山洞、土穴。"}]}, {"meaning": "鹿茸的简称。", "cites": [{"t": "河天月晕鱼分子,槲叶风微鹿养茸。", "b": "黄庭坚《诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1403wx','革','1','gé jí','革','9','','[{"pinyin": "gé", "defs": [{"meaning": "(象形。金文字形,象被剖剥下来的兽皮。中间的圆形物,是被剥下的兽身皮,余下的部分是兽的头、身和尾。“革”是汉字部首之一,从“革”的字多与皮革有关。本义:去毛的兽皮)。"}, {"meaning": "同本义。皮的总称。", "cites": [{"t": "革,兽皮治去其毛。", "b": "《说文》"}, {"t": "齿革羽毛。", "b": "《书·禹贡》"}, {"t": "执之用黄牛之革。", "b": "《易·遯卦》"}, {"t": "掌秋敛皮,冬敛革。", "b": "《周礼·天官》"}, {"t": "江南出梓、姜、桂、金、锡、连、丹沙、犀、瑇瑁、珠玑、齿、革。", "b": "《史记·货殖列传序》"}], "words": [{"w": "人造革;革带", "t": "皮带"}, {"w": "革笥", "t": "用皮作的甲胄"}, {"w": "革船", "t": "用皮革缝制的船。"}]}, {"meaning": "用革制成的甲胄。", "cites": [{"t": "固国不以山溪之险,威天下不以兵革之利。", "b": "《孟子·公孙丑下》"}]}, {"meaning": "车前的饰物。", "cites": [{"t": "革车千乘。", "b": "《礼记·明堂位》"}], "words": [{"w": "革车", "t": "战车。"}]}, {"meaning": "(lè)。马络头。有嚼口的叫勒,没有的叫羁。", "cites": [{"t": "故王良造父,天下之善御者也。然而使王良操左革而叱咤之,使造父操右革而鞭笞之,马不能行十里,故共之。", "b": "《韩非子·外储说右下》"}]}, {"meaning": "变革,更改。", "cites": [{"t": "革,改也。", "b": "《玉篇》"}, {"t": "鸟兽希革。", "b": "《书·尧典》"}, {"t": "故因秦时,本十月为岁首,不革。", "b": "《汉书·任敖传》"}, {"t": "愿革心易行。", "b": "《汉书·严助传》"}, {"t": "天地阴阳不革而成。", "b": "《吕氏春秋·执一》"}, {"t": "厉治革典。", "b": "《国语·周语下》"}, {"t": "革法明教,而秦人大治。", "b": "《盐铁论·非鞅》"}, {"t": "革故鼎新。", "b": "李德裕《次柳氏旧闻》"}, {"t": "瑞锐意兴革,清浚吴淞、白茆,通流入海,民赖其流。", "b": "《明史·海瑞传》"}], "words": [{"w": "革心", "t": "改变心意,不再为非作歹"}, {"w": "革面", "t": "改变旧面貌,转变立场"}, {"w": "革正", "t": "改正。"}]}, {"meaning": "免除或丢掉。", "cites": [{"t": "今革旧从新,为里党之法,在所牧守,宜以喻民,使知去烦即简之要。", "b": "《魏书·食货志》"}], "words": [{"w": "革旧从新", "t": "指除去旧的章法,遵从新的制度"}, {"w": "革去", "t": "除去。"}]}, {"meaning": "姓。"}]}, {"pinyin": "jí", "defs": [{"meaning": "", "cites": [{"t": "成子高寝疾,庆遗人请,曰:“子之病革矣。", "b": "《礼记·檀弓上》"}], "words": [{"w": "病革", "t": "病重。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1404wx','茬','1','chá','艹','9','','[{"pinyin": "chá", "defs": [{"meaning": "(形声。从艸,在声。(chí)本义:草茂盛的样子)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1405wx','荐','1','jiàn','艹','9','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从草,存声。本义:草垫子) 同本义。", "cites": [{"t": "荐,薦席也。", "b": "《说文》。按,凡亲地者谓之筵,加于筵者谓之席。席即因也,重于筵也。"}]}, {"meaning": "再;又;接连。", "cites": [{"t": "荐,再也。", "b": "《尔雅》"}, {"t": "荐,重也。", "b": "《小尔雅》"}, {"t": "晋荐饥。", "b": "《左传·僖公十三年》"}, {"t": "以荐食上国。", "b": "《左传·定公四年》"}, {"t": "饥馑荐降。", "b": "《国语·鲁语上》"}], "words": [{"w": "荐仍", "t": "接连而来"}, {"w": "荐更", "t": "反复经历"}, {"w": "荐臻", "t": "荐蓁。接连地来到;一再遇到"}, {"w": "荐饥", "t": "连年灾荒;连续灾荒。"}]}, {"meaning": "同本义。", "cites": [{"t": "薦,黍蓬。", "b": "《尔雅》。按,蒿类也,或以为野茭。"}, {"t": "麋鹿食荐。", "b": "《庄子·齐物论》。崔注:“甘草也。”"}], "words": [{"w": "荐草", "t": "茂盛的牧草。"}]}, {"meaning": "细草。", "cites": [{"t": "薦草多衍。", "b": "《管子·八观》。注:“茂草也。”"}, {"t": "其民不衣而褐薦。", "b": "《素问·异法方宜论》。注:“谓细草也。”"}, {"t": "北胡随畜薦居。", "b": "《汉书·终军传》"}], "words": [{"w": "荐居", "t": "逐水草而居,没有固定的住所。"}]}, {"meaning": "假借为荐。草垫子。", "cites": [{"t": "薦,席也。", "b": "《广雅》"}], "words": [{"w": "草荐;荐席", "t": "垫席"}, {"w": "荐蒋", "t": "垫席"}, {"w": "荐藉", "t": "草席。"}]}, {"meaning": "介绍进献人才。", "cites": [{"t": "昔者,尧荐舜于天,而天受之。", "b": "《孟子·万章上》"}, {"t": "中外交荐。", "b": "清·张廷玉《明史》"}, {"t": "徐公致靖荐。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "荐本", "t": "官吏向皇帝推荐人才的奏本"}, {"w": "荐辟", "t": "举荐"}, {"w": "荐书", "t": "推荐信"}, {"w": "荐士", "t": "推荐有才德的人。"}]}, {"meaning": "进;进献。", "cites": [{"t": "未遑荐璧。", "b": "《梁书·袁昂传》"}], "words": [{"w": "荐酒;荐璧", "t": "进献璧玉"}, {"w": "荐贿", "t": "奉献财物。"}]}, {"meaning": "衬,垫。", "cites": [{"t": "章甫荐履,渐不可久兮。", "b": "贾谊《吊屈原赋》"}], "words": [{"w": "荐居", "t": "垫草而居。"}]}, {"meaning": "包裹。", "cites": [{"t": "韦恕荐轮,第中游戏。", "b": "汉·荀悦《汉纪》"}]}, {"meaning": "无酒肉作贡品的祭祀,素祭。", "words": [{"w": "荐新", "t": "果菜米谷刚熟,先到神主先人前设供祭祀"}, {"w": "荐享", "t": "祭献;祭祀"}, {"w": "荐奠", "t": "祭奠。祭祀的仪式,即向鬼神敬献祭品"}, {"w": "荐羞", "t": "奉献的祭品"}, {"w": "荐享", "t": "进献祭品祭祀。"}]}, {"meaning": "铺陈。", "cites": [{"t": "君荐虎皮道旁。", "b": "宋·叶适《毛积夫墓志铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1406wx','巷','1','xiàng hàng','巳','9','','[{"pinyin": "xiàng", "defs": [{"meaning": "同本义。直为街,曲为巷;大者为街,小者为巷。", "cites": [{"t": "斜阳草树,寻常巷陌,人道寄奴曾往。", "b": "辛弃疾《永遇乐》"}, {"t": "深巷中犬吠。", "b": "《虞初新志·秋声诗自序》"}, {"t": "巷哭声相闻。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "巷口", "t": "里弄的出入口"}, {"w": "巷战", "t": "在城市街巷里进行的战斗"}, {"w": "巷言,巷议", "t": "于里巷中议论是非。"}]}, {"meaning": "住宅。", "cites": [{"t": "在陋巷,人不堪其忧,回也不改其乐。", "b": "《论语·雍也》"}]}]}, {"pinyin": "hàng", "defs": [{"meaning": "矿坑里的通道", "words": [{"w": "巷道", "t": "略与地面平行、用于采矿探矿的坑道"}, {"w": "煤巷", "t": ""}, {"w": "风巷", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1407wx','带','1','dài','巾','9','','[{"pinyin": "dài", "defs": [{"meaning": "(象形。小篆字形,上面表示束在腰间的一根带子和用带的两端打成的结。下面象垂下的须子,有装饰作用。本义:大带,束衣的腰带)。"}, {"meaning": "同本义。", "cites": [{"t": "带,绅也。上象系佩之形。佩必有巾,从重巾。", "b": "《说文》"}, {"t": "不说带。", "b": "《仪礼·士虞礼记》"}, {"t": "之子无带。", "b": "《诗·卫风·有狐》"}, {"t": "带裳幅舄。", "b": "《左传·桓公二年》"}, {"t": "王遂披襟解带,留连不能已。", "b": "《世说新语·文学》"}, {"t": "子墨子解带围城。", "b": "《墨子·公输》"}], "words": [{"w": "带冕", "t": "大带和冠冕"}, {"w": "带围", "t": "腰围,腰带"}, {"w": "带钩", "t": "皮革腰带上的金属钩。形状一端曲直,另一端为圆钮以承钩。有动物形的,也有铸花纹的"}, {"w": "带头", "t": "旧时衣袍外腰带上的扣头,常镶以金、玉等装饰物。"}]}, {"meaning": "泛指狭长形条状物。", "cites": [{"t": "而半山居雾若带然。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "裤带;鞋带", "t": ""}]}, {"meaning": "佩带。", "cites": [{"t": "哙即带剑拥盾入军门。", "b": "《史记·项羽本纪》"}, {"t": "带刀升座。", "b": "《隋书·礼仪志》"}, {"t": "带长铗之陆离兮。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "带甲", "t": "披戴盔甲的将士;又比喻战乱"}, {"w": "带剑;带刀", "t": ""}]}, {"meaning": "携带。", "cites": [{"t": "遗已聚敛得数斗焦饭,未展归家,遂带以从军。", "b": "《世说新语·德行》"}, {"t": "应元带刀鞬出,跃马大呼于市曰。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "兼管。", "cites": [{"t": "谢为太傅长史被弹,王即取作长史,带晋陵郡。", "b": "《世说新语·言语》"}]}, {"meaning": "表示两个动作同时进行,相当于“又” 连说带比划的,就交上朋友了;带口(随口)。"}, {"meaning": "表示附有较小的数量。", "cites": [{"t": "你不是常常说,你才三十带点,日子还很长么?", "b": "沙汀《困兽记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1408wx','草','1','cǎo','艹','9','','[{"pinyin": "cǎo", "defs": [{"meaning": "(形声。从艸,早声。小篆艸,象两棵草形,是草的本字。今“草”字系假借字,原是“皂”的本字。《说文》:“草,草斗,栎(lì)实也”(栎实:栎树的荚果,即皂角)。借为“草木”之“草”以后,则另造“皂”字来代替。本义:栎实)。"}, {"meaning": "草本植物的总称。", "cites": [{"t": "艸,百卉也。从二屮。会意。经传皆以草为之。汉书多以屮为之。", "b": "《说文》"}, {"t": "大草不生。", "b": "《吕氏春秋·任地》。注:“草,秽也。”"}, {"t": "草食者羶。", "b": "《吕氏春秋·本味》"}, {"t": "草苴比而不芳。", "b": "《楚辞·悲回风》。注:“生曰草。”"}, {"t": "苔痕上阶绿,草色入帘青。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "茅檐低小,溪上青青草。", "b": "宋·辛弃疾《清平乐·村居》"}], "words": [{"w": "除草;粮草", "t": "军用的粮食和草料"}, {"w": "野草遍地;寸草不留;青草;牧草;茅草;草厅", "t": "草堂;厅堂"}, {"w": "草莽", "t": "草丛。比喻无用的东西。"}]}, {"meaning": "指用作燃料、饲料的干草。", "cites": [{"t": "今又盛寒,马无稿草。", "b": "《资治通鉴》"}], "words": [{"w": "草库伦", "t": "指围起来的草场"}, {"w": "草料", "t": ""}]}, {"meaning": "未开垦过的荒地。", "cites": [{"t": "垦草创邑,辟地生粟。", "b": "《韩非子·外储说》"}], "words": [{"w": "草甸子", "t": "方言。长满野草的低湿地"}, {"w": "草洼", "t": "低洼积水,野草丛生的地方"}, {"w": "草间", "t": "民间"}, {"w": "草茅危言", "t": "百姓对国政的剀切言论。草茅,指在野百姓;百姓论庙堂,恐有危险,故谓危言。"}]}, {"meaning": "文书的底稿;初稿。", "cites": [{"t": "吴中士人家藏其草。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "草藁", "t": "同草稿"}, {"w": "起草;奏草", "t": "奏张的草稿"}, {"w": "草本", "t": "原稿的底本。"}]}, {"meaning": "粗糙;粗劣。", "cites": [{"t": "令人事无大小皆潦草过了。", "b": "《朱子类语·训门人》"}], "words": [{"w": "草略", "t": "马虎,疏忽"}, {"w": "草具", "t": "粗劣;粗劣的饭食"}, {"w": "草酌", "t": "简便的筵席。多用作设宴请客的谦词"}, {"w": "潦草", "t": "字不工整;不仔细;不认真。"}]}, {"meaning": "创造;创立。", "cites": [{"t": "草,造也。", "b": "《广雅》"}, {"t": "天造草昧。", "b": "《易·屯》。虞注:“草,草创物也。”"}], "words": [{"w": "草立", "t": "创立"}, {"w": "草昧", "t": "创始;草创"}, {"w": "草律", "t": "创制法律。"}]}, {"meaning": "草拟;起稿。", "cites": [{"t": "萧何草律。", "b": "《汉书·艺文志》。注:“创造之。”"}, {"t": "草立土德时历制度。", "b": "《汉书·任敖传》。注:“创始也。”"}, {"t": "召今草檄。", "b": "《南史·蔡景立传》"}], "words": [{"w": "草立", "t": "创立"}, {"w": "草制", "t": "拟订制书"}, {"w": "草诏", "t": "草拟诏书"}, {"w": "草表", "t": "草拟章奏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1409wx','茧','1','jiǎn','艹','9','','[{"pinyin": "jiǎn", "defs": [{"meaning": "许多昆虫幼虫在化蛹前包围身体大部分的由丝组成的外皮,在其中化蛹。家蚕的茧是商业蚕丝的来源。", "cites": [{"t": "生自蚕茧。", "b": "《后汉书·列女传》"}], "words": [{"w": "蚕茧;茧儿", "t": "喻指秘事;名堂;见不得人的事"}, {"w": "茧素", "t": "白色的生绢"}, {"w": "茧纸", "t": "用蚕茧制作的纸。"}]}, {"meaning": "絮丝棉的衣服 "}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1410wx','茵','1','yīn','艹','9','','[{"pinyin": "yīn", "defs": [{"meaning": "(形声。从艸,因声。本义:车垫子。字本作“因”)。"}, {"meaning": "同本义。", "cites": [{"t": "茵,车重席也。", "b": "《说文》"}, {"t": "交茵畅毂。", "b": "《秦风·小戎》。传:“文茵虎皮也。”"}, {"t": "茵席。", "b": "《礼记·少仪》。注:“著褥也。”"}, {"t": "御者在茵上。", "b": "《汉书·五行志》"}, {"t": "同车未尝敢均茵冯。", "b": "《汉书·周阳由传》"}, {"t": "绿草如茵。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "茵伏", "t": "茵轼。车蓐和车轼"}, {"w": "茵冯", "t": "茵凭。车蓐与车轼。"}]}, {"meaning": "", "cites": [{"t": "茵蕴祗冥。", "b": "《江文通集·莲花赋》"}], "words": [{"w": "茵蘊", "t": "氤氲。气弥漫的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1411wx','茶','1','chá','艹','9','','[{"pinyin": "chá", "defs": [{"meaning": "茶叶。由茶树的嫩叶加工制成,供泡取饮料用。", "cites": [{"t": "前月浮梁买茶去。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "茶市", "t": "茶叶市场。"}]}, {"meaning": "用茶叶泡制、烹制或煎制而成的饮料。", "cites": [{"t": "唐人煎茶,用姜用盐。", "b": "苏轼《东坡志林》"}, {"t": "日高人渴漫思茶。", "b": "宋·苏轼《浣溪沙》"}], "words": [{"w": "茶座", "t": "茶馆为卖茶而设的座位"}, {"w": "茶坊", "t": "茶局子、茶局。指茶馆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1412wx','荒','1','huāng huang','艹','9','','[{"pinyin": "huāng", "defs": [{"meaning": "(形声。从丱,巟(huāng)声。本义:荒芜)。"}, {"meaning": "同本义。", "cites": [{"t": "荒,芜也,一曰草荒地也。", "b": "《说文》"}, {"t": "我居圉卒荒。", "b": "《诗·大雅·召》"}, {"t": "野荒民散则削之。", "b": "《周礼·大司马》"}, {"t": "地广大荒而不治。", "b": "《礼记·曲礼》"}, {"t": "三径就荒。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "开荒南野际。", "b": ""}, {"t": "极于荒残。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "几处荒坟。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "荒陂", "t": "荒芜的坡地"}, {"w": "荒梗", "t": "土地荒废,道路阻隔"}, {"w": "荒楚", "t": "杂草树木蔓生的地方"}, {"w": "荒白", "t": "荒芜"}, {"w": ";荒居", "t": "荒凉的住处。常用作对自己住处的谦称"}, {"w": "荒陋", "t": "荒凉简陋"}, {"w": "荒城", "t": "荒凉的古城"}, {"w": "荒梗", "t": "荒凉闭塞。"}]}, {"meaning": "年成不好;凶年;歉收。", "cites": [{"t": "以荒政十有二聚万民。", "b": "《周礼·大司徒》。注:“凶年也。”"}, {"t": "大荒。", "b": "《周礼·春官·同服》。注:“饥馑也。”"}, {"t": "果不熟为荒。", "b": "《尔雅·释天》"}, {"t": "四谷不升谓之荒。", "b": "《韩诗外传》"}]}, {"meaning": "卷八》。", "cites": [{"t": "三曰丧荒之式。", "b": "《周礼·天官·大宰》"}], "words": [{"w": "荒春", "t": "春末的时候,青黄不接,生活最为困难,所以称为荒春"}, {"w": "荒旱表", "t": "上报旱情的奏章"}, {"w": "荒耗", "t": "遭灾减产,民用空竭。"}]}, {"meaning": "大;广大,无边际。引申为不可信。", "cites": [{"t": "好乐无荒。", "b": "《诗·唐风·蟋蟀》"}, {"t": "幽居允荒。", "b": "《诗·大雅·公刘》"}, {"t": "大王荒之。", "b": "《诗·周颂·天作》"}, {"t": "大荒落之岁。", "b": "《淮南子·天文》"}], "words": [{"w": "荒荒", "t": ""}]}, {"meaning": "远;久远。", "cites": [{"t": "荒,远也。", "b": "《广雅·释诂一》"}, {"t": "戎翟荒服。", "b": "《国语·周语》"}], "words": [{"w": "荒古;荒绝", "t": "邈远"}, {"w": "荒土", "t": "东北方极远之地"}, {"w": "荒外", "t": "边远之外,或八荒之外的地方。极远的意思。引申指偏僻无文化的地方"}, {"w": "荒服", "t": "五服之一。指距离京城最远的属地"}, {"w": "荒域", "t": "边远的地方。"}]}, {"meaning": "成色不足的。", "cites": [{"t": "老夫带得三两荒银,权为程敬。", "b": "《警世通言》"}]}, {"meaning": "荒废;荒疏。", "cites": [{"t": "无荒失朕命。", "b": "《书·盘庚》"}], "words": [{"w": "荒疏;荒顿", "t": "荒疏废弃"}, {"w": "荒陋", "t": "荒疏浅薄"}, {"w": "荒宁", "t": "荒废懈怠,贪图安逸"}, {"w": "荒坠", "t": "荒废坠失。"}]}, {"meaning": "废弃物;破烂。", "cites": [{"t": "隔壁拾荒的四喜子不知从什么地方拾来了挺厚的一叠。", "b": "茅盾《子夜》"}]}]}, {"pinyin": "huang", "defs": [{"meaning": "——“饥荒”(jīhuang):指经济困难。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1413wx','茫','1','máng','艹','9','','[{"pinyin": "máng", "defs": [{"meaning": "(形声。从水,芒声。本义:水浩大的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "茫乎其若迷。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "拔剑四顾心茫然。", "b": "唐·李白《行路难》"}], "words": [{"w": "茫无涯际", "t": "茫无边际。辽阔浩渺而无边际。"}]}, {"meaning": "迷蒙不明;模糊不清。", "cites": [{"t": "茫乎昧乎,未之尽者。", "b": "《庄子·天下》"}], "words": [{"w": "茫洋", "t": "广大无垠的样子"}, {"w": "茫乎", "t": "芒乎。茫然。无所知的样子"}, {"w": "茫如", "t": "茫然。谓无所知"}, {"w": "茫无所知", "t": "一点也不知道"}, {"w": "茫茫荡荡", "t": "辽阔深远而又模糊不清"}, {"w": "茫昧", "t": "幽暗不明,模糊不清。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1414wx','荡','1','dàng','艹','9','','[{"pinyin": "dàng", "defs": [{"meaning": "(会意。从皿,从汤,汤亦声。本义:洗涤)。"}, {"meaning": "同本义。", "cites": [{"t": "荡亡秦之毒螫。", "b": "班固《西都赋》"}]}, {"meaning": "动;摇动;震动。", "cites": [{"t": "此四六者不荡,胸中则正。", "b": "《庄子·庚桑楚》"}, {"t": "天下不能荡也。", "b": "《荀子·劝学》"}, {"t": "以荡上心。", "b": "《吕氏春秋·季春纪》"}, {"t": "以其休止不荡也。", "b": "《淮南子·说山》"}, {"t": "从流漂荡,任意东西。", "b": "吴均《与朱元思书》"}, {"t": "波心荡,冷月无声。", "b": "宋·姜夔《扬州慢》"}]}, {"meaning": "又如;荡突(冲撞);荡心(摇荡心神);荡摇(动摇);荡荡悠悠(摇荡、飘流的样子)。"}, {"meaning": "清除。", "cites": [{"t": "荡平塞表。", "b": "曹操《表论田畴功》"}], "words": [{"w": "荡风", "t": "两广的一种风俗。女婿在未见岳父岳母前,依俗饮一大杯酒。有荡除行路风寒之意"}, {"w": "荡除", "t": "消灭。"}]}, {"meaning": "毁坏;破坏。", "cites": [{"t": "家乡既荡尽,远近理亦齐。", "b": "杜甫《无家别》"}], "words": [{"w": "荡产", "t": "破产,耗尽财产"}, {"w": "荡散", "t": "消失;毁败"}, {"w": "荡灭", "t": "毁灭;消灭。"}]}, {"meaning": "冲撞;冲杀;触碰。", "cites": [{"t": "稍近,益狎,荡倚冲冒。", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "荡突", "t": "冲撞。即唐突"}, {"w": "荡析", "t": "游走离散。"}]}, {"meaning": "放纵,放荡。", "cites": [{"t": "余心荡。", "b": "《左传·庄公四年》"}, {"t": "德荡者其行伪。", "b": "《淮南子·俶真》"}, {"t": "吉驭者耆酒,数逋荡。", "b": "《汉书·丙吉传》"}, {"t": "古之 狂也肆,今之狂也荡。", "b": "《论语·阳货》"}], "words": [{"w": "荡荡", "t": "放纵邪僻"}, {"w": "荡子", "t": "远行在外,流荡不归的男子;游荡放浪,不务正业的男子。"}]}, {"meaning": "平坦。", "cites": [{"t": "山顶有大池,相传以为雁荡。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "坦荡;荡无高卑", "t": "地位平等,没有高低尊卑"}, {"w": "荡荡", "t": "平坦、宽坦的样子。"}]}, {"meaning": "广阔。", "cites": [{"t": "荡荡洪水滔天。", "b": "《史记·五帝纪》"}, {"t": "荡荡乎!民无能名焉。", "b": "《论语·泰伯》"}], "words": [{"w": "荡漭", "t": "广阔无边貌"}, {"w": "荡荡", "t": "广大的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1415wx','荣','1','róng','艹','9','','[{"pinyin": "róng", "defs": [{"meaning": "(形声。从木,荧省声。本义:梧桐。又金文字形,象两支如火把相互照耀的花朵或穗头形)。"}, {"meaning": "同本义。", "cites": [{"t": "荣,桐木也。", "b": "《说文》"}, {"t": "荣,桐木。", "b": "《尔雅》。注:“即梧桐。”"}]}, {"meaning": "草本植物的花。又为花的通称。", "cites": [{"t": "木谓之华,草谓之荣,不荣而实者谓之秀,荣而不实者谓之英。", "b": "《尔雅》"}, {"t": "攀条折其荣。", "b": "《古诗十九首》"}], "words": [{"w": "荣悴", "t": "草木的开花与凋萎"}, {"w": "荣年", "t": "百花争艳的季节"}, {"w": "荣色", "t": "花的色彩。"}]}, {"meaning": "飞檐,屋檐两头翘起的部分。", "cites": [{"t": "直于东荣。", "b": "《仪礼·士冠礼》。注:屋翼也。”"}, {"t": "暴于南荣。", "b": "《上林赋》。注:“南檐也。”"}], "words": [{"w": "荣阿", "t": "飞檐的曲隅。"}]}, {"meaning": "荣誉。良好的名声或社会名望。", "cites": [{"t": "且辱者也而荣。", "b": "《吕氏春秋·振乱》"}, {"t": "会九世而飞荣。", "b": "《南都赋》"}], "words": [{"w": "荣级", "t": "荣誉爵位"}, {"w": "启荣", "t": "死后的荣誉。"}]}, {"meaning": "繁茂,茂盛。", "cites": [{"t": "木欣欣以向荣。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "荣谢", "t": "草木茂盛与凋零"}, {"w": "荣芬", "t": "茂盛,繁密"}, {"w": "荣旺", "t": "植物生长旺盛"}, {"w": "荣条", "t": "茂盛的枝条"}, {"w": "荣敷", "t": "荣荣。草木茂盛的样子"}, {"w": "荣熙", "t": "繁盛。"}]}, {"meaning": "繁荣。", "cites": [{"t": "室宫荣与。", "b": "《荀子·大略》。注:“盛也。”"}], "words": [{"w": "荣昌", "t": "繁荣昌盛"}, {"w": "荣泰", "t": "繁荣安定"}, {"w": "荣怀", "t": "国家繁荣则万民归附"}, {"w": "荣茂", "t": "繁荣茂盛"}, {"w": "荣落", "t": "荣盛与衰落"}, {"w": "荣畅", "t": "荣盛"}, {"w": "荣观", "t": "荣盛的景观"}, {"w": "荣仕", "t": "高官显爵"}, {"w": "荣逸", "t": "显赫安乐"}, {"w": "荣国", "t": "昌盛之国。"}]}, {"meaning": "盛多;丰富。", "cites": [{"t": "宫室荣与?妇谒盛与?", "b": "《荀子》"}]}, {"meaning": "开花。", "cites": [{"t": "诸越则桃李冬实,朔漠则桃李夏荣。", "b": "宋·沈括《梦溪笔谈》"}]}, {"meaning": "抛弃。", "cites": [{"t": "荣汝之粮,不若遄归也。", "b": "《列子》"}]}, {"meaning": "使…荣耀;使…光荣。", "cites": [{"t": "足以荣汝身。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "是以蓼洲周公,忠义暴于朝廷,赠溢美显,荣于身后。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "荣除之庆", "t": "封官授爵的喜庆"}]}, {"meaning": "经营。", "cites": [{"t": "君子以俭德辟难,不可荣以禄。", "b": "《易·否》"}]}, {"meaning": "炫惑。", "cites": [{"t": "不掩欲以荣君。", "b": "《晏子春秋·内篇问上》"}, {"t": "以荣其意而乱其政。", "b": "《韩非子·内储说下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1416wx','荤','1','hūn xūn','艹','9','','[{"pinyin": "hūn", "defs": [{"meaning": "(形声。从丱,军声。本义:指葱蒜类辛臭的蔬菜)。"}, {"meaning": "同本义。", "cites": [{"t": "荤,臭菜也。", "b": "《说文》"}, {"t": "荤,辛菜也。", "b": "《苍颉篇》"}, {"t": "膳荤。", "b": "《仪礼·士相见礼》。注:“辛物,葱韭之属。”"}, {"t": "膳于君有荤桃茢。", "b": "《礼记·玉藻》。注:“姜及辛菜也。”"}, {"t": "然后荤菜百蔬以泽量。", "b": "《荀子·富国》"}, {"t": "唯不饮酒、不茹荤者数月矣。", "b": "《庄子·人间世》"}], "words": [{"w": "荤辛", "t": "味道浓重、辛辣的蔬菜。佛家禁止使用。"}]}]}, {"pinyin": "xūn", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1417wx','荧','1','yíng','艹','9','','[{"pinyin": "yíng", "defs": [{"meaning": "(会意。从焱(yàn)冂(jiǒng)。焱,火花。冂,远方的边界。合起来表示远处的火花,光微弱。本义:光微弱的样子) 同本义。", "cites": [{"t": "荧,屋下灯烛之光。", "b": "《说文》"}, {"t": "荧荧,光也。", "b": "《广雅》"}, {"t": "鬼火兮荧荧。", "b": "《楚辞·王逸·九思·哀岁》"}, {"t": "琳珉青荧。", "b": "《后汉书·班固传》"}], "words": [{"w": "荧烛", "t": "微弱的烛光"}, {"w": "荧然", "t": "光微弱的样子"}, {"w": "荧燎", "t": "微光"}, {"w": "荧耀", "t": "微光"}, {"w": "荧华", "t": "闪烁的亮光"}, {"w": "荧煌", "t": "辉煌"}, {"w": "荧晔", "t": "光明的样子"}, {"w": "荧灿", "t": "明亮。"}]}, {"meaning": "萤火。", "cites": [{"t": "腐草为荧。", "b": "《礼记·月令》"}, {"t": "夜步逐荧光。", "b": "《后汉书·灵帝记》"}]}, {"meaning": "眩惑。", "cites": [{"t": "而目将荧之。", "b": "《庄子·人间世》"}], "words": [{"w": "荧惑星", "t": "火星"}, {"w": "荧惑守心", "t": "火星守御星"}, {"w": "荧侮", "t": "迷惑侮狎"}, {"w": "荧眩", "t": "眩惑"}, {"w": "荧惑", "t": "炫惑"}, {"w": "荧乱", "t": "迷乱"}, {"w": "荧听", "t": "淆乱听闻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1418wx','故','1','gù','攵','9','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从攴(pū),古声。从“攴”,取役使之意。本义:缘故,原因)。"}, {"meaning": "同本义。", "cites": [{"t": "故,使为之也。", "b": "《说文》"}, {"t": "又明于忧患与故。", "b": "《易·系辞传》"}, {"t": "则是无故。", "b": "《礼记·礼运》"}, {"t": "夫有其故。", "b": "《国语·楚语》"}, {"t": "既克,公问其故。", "b": "《左传·庄公十年》"}, {"t": "扶苏以数谏故,上使外将兵。", "b": "《史记·陈涉世家》"}, {"t": "广行取胡儿弓,射杀追骑,以故得脱。", "b": "《史记·李将军列传》"}], "words": [{"w": "借故", "t": "托故。借口某种原因"}, {"w": "无故", "t": "没有缘故。"}]}, {"meaning": "事;事情。", "cites": [{"t": "昭伯问家故,尽对。", "b": "《左传·昭公二十五年》"}, {"t": "敢问天道乎,抑人故也?—《国语·周语下》", "b": ""}, {"t": "教、孝景固袭掌故,未遑讲试。", "b": "《史记·龟策传》"}], "words": [{"w": "细故", "t": "细小而值不得计较的事情"}, {"w": "掌故", "t": "历史上的人物事迹、制度沿革等。"}]}, {"meaning": "意外或不幸的事变。", "cites": [{"t": "国有故。", "b": "《周礼·天官·宫正》"}, {"t": "乡园多故,不能不动客子之愁。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "故端", "t": "事故;事端"}, {"w": "变故", "t": "灾难;意外发生的事情"}, {"w": "事故", "t": "意外的损失或灾祸。"}]}, {"meaning": "旧识;旧交。", "cites": [{"t": "君安与项伯有故?", "b": "《史记·项羽本纪》"}], "words": [{"w": "一见如故;故贵", "t": "旧交与贵人"}, {"w": "故义", "t": "故交旧友"}, {"w": "旧故", "t": "旧交"}, {"w": "亲故", "t": "亲戚故旧。"}]}, {"meaning": "特指旧法、旧典、成例。", "cites": [{"t": "变化齐一,不主故常。", "b": "《庄子·天运》"}, {"t": "是时,宣帝循武帝故事,招名儒俟材置左右。", "b": "《汉书·楚元王传》"}], "words": [{"w": "蹈常袭故;故典", "t": "典故"}, {"w": "故语", "t": "典故成语"}, {"w": "故祀", "t": "按惯例举行的祭祀"}, {"w": "故套", "t": "陈规俗套。"}]}, {"meaning": "旧的事物。", "cites": [{"t": "温故而知新,可以为师矣。", "b": "《论语·为政》"}], "words": [{"w": "吐故纳新", "t": ""}]}, {"meaning": "以今言解释古代语言文字或方言字义。", "cites": [{"t": "训故举大谊而已。", "b": "《汉书·儒林传》"}, {"t": "并作周官解故。", "b": "《后汉书·贾逵传》"}]}, {"meaning": "原来。旧时的。", "cites": [{"t": "故,旧也。", "b": "《广韵》"}, {"t": "反故居些。", "b": "《楚辞·招魂》"}, {"t": "乐先故些。", "b": ""}, {"t": "蔓成然故事蔡公。", "b": "《左传·昭公十三年》"}, {"t": "所谓故国者。", "b": "《孟子·梁惠王下》"}, {"t": "以故法为其国与此同。", "b": "《吕氏春秋·察今》"}, {"t": "敬亭丧失其资略尽,贫困如故时。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "轩东故尝为厨。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "故步", "t": "旧时行步的方法"}, {"w": "故地", "t": "旧有的属地"}, {"w": "故夫", "t": "以前的丈夫"}, {"w": "故方", "t": "旧药方"}, {"w": "故吏", "t": "原有属吏"}, {"w": "故林", "t": "从前栖息的树林"}, {"w": "故式", "t": "古旧的仪式。"}]}, {"meaning": "时代久远。", "cites": [{"t": "是故之时,陈财之道,可以行今也。", "b": "《管子·侈靡》"}], "words": [{"w": "先故", "t": "很久以前。"}]}, {"meaning": "死亡。", "cites": [{"t": "前年赵三郎已故了,他老婆在家守寡。", "b": "《古今小说·穷马固遭际卖鎚媪》"}], "words": [{"w": "病故;亡故", "t": "死去"}, {"w": "染病身故", "t": "死"}, {"w": "物故", "t": "去世"}, {"w": "大故", "t": "指父亲或母亲死亡"}, {"w": "故鬼", "t": "旧鬼,死去已久的人的鬼魂。"}]}, {"meaning": "衰老。", "cites": [{"t": "弟走从军阿姨死,暮去朝来颜色故。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "故意,存心。", "cites": [{"t": "广故数言欲亡。", "b": "《史记·陈涉世家》"}, {"t": "主者故不受,则固请。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "故故", "t": "故意;屡屡;常常"}, {"w": "故违", "t": "有意违抗"}, {"w": "故推", "t": "故意推托"}, {"w": "故靳", "t": "故意吝惜。靳:吝惜"}, {"w": "故纵干咎", "t": "有意纵容罪犯而触犯法令。"}]}, {"meaning": "原来,本来。", "cites": [{"t": "程不识故与李广俱以边太守将军屯。", "b": "《史记·李将军列传》"}, {"t": "此物故非西产。", "b": "《聊斋志异·促织》"}]}, {"meaning": "仍,还是。", "cites": [{"t": "三日断五匹,大人故嫌迟。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "犹不失下曹从事,乘犊车从吏卒,交游士林,累官故不失州郡也。", "b": "《资治通鉴》"}]}, {"meaning": "何,何故。", "cites": [{"t": "公将有行,故不送公?", "b": "《管子·侈靡》"}], "words": [{"w": "故为", "t": "何故如此。"}]}, {"meaning": "因此,所以 ——表示因果关系。", "cites": [{"t": "夫秦无道,故沛公得至此。", "b": "《史记·留侯世家》"}, {"t": "故审堂下之阴,而知日月之行,阴阳之变。", "b": "《吕氏春秋·察今》"}, {"t": "时恐急,剑坚,故不可立拔。", "b": "《战国策·燕策》"}], "words": [{"w": "今日下雨,故未成行;故以", "t": "因此;所以"}, {"w": "故厎", "t": "所以致成。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1419wx','胡','1','hú','月','9','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从肉,古声。本义:牛脖子下的垂肉)。"}, {"meaning": "鸟兽颔下的垂肉或皮囊。", "cites": [{"t": "胡,牛顄垂也。", "b": "《说文》。徐锴曰:“牛颔下垂皮也。”"}, {"t": "狼跋其胡。", "b": "《诗·豳风·狼跋》。传:“老狼有胡。”"}, {"t": "有龙垂胡须下迎黄帝。", "b": "《汉书·郊祀志上》。师古曰:“胡,谓颈下垂肉也。”"}], "words": [{"w": "胡髯朗", "t": "羊的别名。胡,颈下垂肉;髯,须"}, {"w": "胡皱", "t": "牛颔下松弛有皱纹的皮"}, {"w": "胡袋", "t": "某些鸟类颌下的皮囊,也称喉囊。"}]}, {"meaning": "古代称北方和西方的民族如匈奴等为胡。", "cites": [{"t": "燕山胡骑。", "b": "《乐府诗集·木兰诗》"}, {"t": "亡而入胡。", "b": "《淮南子·人间训》"}, {"t": "将胡骏马。", "b": ""}, {"t": "胡人大入塞。", "b": ""}]}, {"meaning": "古国名 。其地在今天的安徽省阜阳县西北。", "cites": [{"t": "二月,楚灭胡。", "b": "《左传》"}]}, {"meaning": "怎样;何。", "cites": [{"t": "胡,何也。", "b": "《广雅·释诂三》"}, {"t": "弗虑胡获?弗为胡成?", "b": "《书·太甲下》"}, {"t": "胡能有定?", "b": "《诗·邶风·日月》"}], "words": [{"w": "胡说", "t": "何说,怎么说"}, {"w": "胡为", "t": "何故"}, {"w": "胡为如此?", "t": ""}]}, {"meaning": "为什么;何。", "cites": [{"t": "胡然而天也,胡然而帝也。", "b": "《诗·鄘风·君子偕老》"}, {"t": "云胡不夷?", "b": "《诗·郑风·风雨》"}, {"t": "胡取禾三百廛兮?", "b": "《诗·魏风·伐檀》"}, {"t": "胡不已乎。", "b": "《墨子·公输》"}, {"t": "胡不见我于王。", "b": ""}, {"t": "胡不汉先王之法。", "b": "《吕氏春秋·察今》"}, {"t": "胡可得而法。", "b": ""}], "words": [{"w": "胡为", "t": "何为;为什么"}, {"w": "胡然", "t": "为何。表示疑问或反诘"}, {"w": "胡宁", "t": "何乃;为何。"}]}, {"meaning": "黑。", "cites": [{"t": "或谑张飞胡,或笑邓艾吃。", "b": "李商隐《骄儿诗》"}]}, {"meaning": "胡须。", "cites": [{"t": "有龙垂胡髯。", "b": "《风俗通·正失》"}], "words": [{"w": "胡髯", "t": "“胡”是“胡子”的通称;“髯”指两颊上的胡子"}, {"w": "胡子;胡须", "t": ""}]}, {"meaning": "见“胡同”(hútong)“衚”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1420wx','荫','1','yìn','艹','9','','[{"pinyin": "yìn", "defs": [{"meaning": "(形声。从艸,阴声。本义:树阴)。"}, {"meaning": "同本义。", "cites": [{"t": "荫,草阴也。", "b": "《说文》"}, {"t": "荫,草阴地也。", "b": "《广韵》"}, {"t": "赵盂视荫。", "b": "《左传·昭公元年》。注:“荫日景也。”"}, {"t": "玉足以庇荫嘉谷。", "b": "《国语·楚语下》"}, {"t": "荫不祥之木。", "b": "《淮南子·说林》。注:“荫,木景也。”"}, {"t": "武王荫暍人于樾下。", "b": "《淮南子·人间》"}, {"t": "树成荫而众鸟息焉。", "b": "《荀子》"}], "words": [{"w": "树成荫而众鸟息;垂荫万亩;荫樊", "t": "树荫浓密。"}]}, {"meaning": "指地窖或暗室。", "cites": [{"t": "则一荫之曲豉,尽美而多量。", "b": "《潜夫论·德化》"}], "words": [{"w": "荫室", "t": "谓阳光照射不到的屋舍,如窑洞、地窖之类。"}]}, {"meaning": "字亦作廕。遮蔽。", "cites": [{"t": "若君实庇廕膏泽之。", "b": "《国语·晋语》"}, {"t": "本根无所庇荫矣。", "b": "《左传·文公七年》"}, {"t": "榆柳荫后。", "b": "晋·陶渊明《归园田居》"}, {"t": "有松可荫。", "b": "明·顾炎武《复庵记》"}]}, {"meaning": "庇荫 。封建时代,因祖先有勋劳或官职而循例受封、得官。", "cites": [{"t": "武王荫暍人于樾下。", "b": "《淮南子·人间》"}, {"t": "少以父荫。", "b": "《隋书·柳述传》"}, {"t": "继子荫孙图富贵,更无一个肯回头!", "b": "《西游记》"}], "words": [{"w": "荫恤", "t": "因前代功德而得到官职或抚恤"}, {"w": "荫籍", "t": "依赖先辈有功而得到恩赐的官职"}, {"w": "荫生", "t": "因先世荫庇而入国子监读书的称为荫生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1421wx','荔','1','lì','艹','9','','[{"pinyin": "lì", "defs": [{"meaning": "草名。即“马蔺” 。又名“马荔”。一种多年生草本植物,须根长而坚硬,叶片狭线形,花蓝色。花及种子可入药,叶可造纸,根可制刷子。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1422wx','南','1','nán nā','十','9','','[{"pinyin": "nán", "defs": [{"meaning": "(象形,甲骨文字形,是钟镈之类的乐器。①本义:乐器。《诗·小雅·鼓钟》:“以雅以南。”②方位词)。"}, {"meaning": "方位名。和“北”相对。", "cites": [{"t": "南,草木至南方有枝任也。", "b": "《说文》"}, {"t": "出户南望。", "b": "晋·干宝《搜神记》"}, {"t": "南抚夷越。", "b": "《三国志·诸葛亮传》"}, {"t": "旌麾南指。", "b": "《资治通鉴》"}, {"t": "南极潇湘。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "南薰", "t": "借指从南面刮来的风"}, {"w": "南离", "t": "南方。"}]}, {"meaning": "南方;南面。", "cites": [{"t": "阮仲容步兵居道南,诸阮居道北。", "b": "《新说新语·言语》"}], "words": [{"w": "南风", "t": "南方势力"}, {"w": "南酒", "t": "黄酒,南方酿造"}, {"w": "南宗", "t": "佛教指南北二宗,南宗为六祖惠能所创立"}, {"w": "南夏", "t": "泛指中国的南部"}, {"w": "南客", "t": "客居南方"}, {"w": "南浦", "t": "南面的水边"}, {"w": "南琛", "t": "南方所产的珍宝"}, {"w": "南乡", "t": "南方"}, {"w": "南邻", "t": "古指南方金邻国;南边的近郊"}, {"w": "南荣", "t": "房屋的南檐;南方之地"}, {"w": "南鄙", "t": "南方边境地区"}, {"w": "南迁", "t": "迁都南方"}, {"w": "南徼", "t": "南方边陲"}, {"w": "南馔", "t": "南方口味的菜肴"}, {"w": "南关", "t": "南方的关塞。"}]}, {"meaning": "官爵名", "cites": [{"t": "郑伯,男南也。", "b": "《孔子家语·正论解》。注:“南,《左传》作男,古字作男,亦多用作此南,连言之,犹言公侯也。”"}]}, {"meaning": "对《诗经》中《周南》、《召南》的简称。", "cites": [{"t": "周始二《南》,《风》兼六代。", "b": "《晋书》"}]}, {"meaning": "向南走;向南移动。", "cites": [{"t": "因遗策,南取汉中,西举巴蜀,东割膏腴之地。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "又。", "cites": [{"t": "南取百越之地,以为桂林、象郡。", "b": ""}], "words": [{"w": "南辕", "t": "车辕向南。"}]}, {"meaning": "向南。", "cites": [{"t": "月明星稀,乌鹊南飞。", "b": "曹操《短歌行》"}, {"t": "南面称帝。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "南奔", "t": "向南奔跑。"}]}, {"meaning": "姓。"}]}, {"pinyin": "nā", "defs": [{"meaning": "佛教用语", "words": [{"w": "南无", "t": "佛学用语又作南牟，意思是合掌稽首，表示对佛尊敬或皈依，常加于佛、菩萨名的前面，表示对佛法的一种尊敬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1423wx','药','1','yào','艹','9','','[{"pinyin": "yào", "defs": [{"meaning": "(形声。从艸,乐声。本义:治病的物品。药物;药材。一般是植物,故从艸)。"}, {"meaning": "同本义。", "cites": [{"t": "药,治病草也。", "b": "《说文》"}, {"t": "以五味五谷五药养其病。", "b": "《周礼·疾医》。注:“五药,草木虫石谷也。”"}, {"t": "勿药有喜。", "b": "《易·无妄》"}, {"t": "求仙人不死之药。", "b": "《史记》"}], "words": [{"w": "药肆", "t": "药店"}, {"w": "药贴", "t": "处方单"}, {"w": "药封", "t": "用红纸袋封送的诊断费"}, {"w": "药案", "t": "药方"}, {"w": "药王", "t": "指治病用药如神的人"}, {"w": "药引", "t": "中医处方中先选某种药物作为其他药物的导引,使药力可以达到病处,称为药引"}, {"w": "药局", "t": "专司配药剂的机构;俗称出卖药品的部门为药局"}, {"w": "药饵", "t": "药物。"}]}, {"meaning": "指某些有化学作用的物质。", "cites": [{"t": "药稍熔,则以一平板按其面,则字平如砥(药稍稍化开,此指松脂、腊等)。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "药水龙", "t": "化学灭火器"}, {"w": "药骰", "t": "在骰子中封入水银或铅,庄家可以任意操纵得到的点数,以欺骗押赌者。"}]}, {"meaning": "特指火药。", "cites": [{"t": "凡鸟铳长约三尺,铁管载药。", "b": "宋应星《天工开物》"}]}, {"meaning": "用药治疗。", "cites": [{"t": "多将熇熇,不可救药。", "b": "《诗·大雅·板》"}, {"t": "不如吾闻而药之也。", "b": "《孔子家语·正论》"}, {"t": "彼得之不足以药伤补败。", "b": "《荀子》"}], "words": [{"w": "药师", "t": "药工、医师之古称"}, {"w": "药捻", "t": "带药的纸捻或纱布条,外科治疗时用来放入伤口或疮口内"}, {"w": "药膳", "t": "配有中药做的菜肴或食品。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1424wx','标','1','biāo','木','9','','[{"pinyin": "biāo", "defs": [{"meaning": "(形声。从木,票声。本义:树梢)。"}, {"meaning": "同本义。", "cites": [{"t": "标,木杪末也。", "b": "《说文》"}, {"t": "大本而小标。", "b": "《管子·霸言》"}], "words": [{"w": "标枝", "t": "树梢的枝条"}, {"w": "标末", "t": "树梢。"}]}, {"meaning": "末梢;事物的枝节或表面。与“本”相对。", "cites": [{"t": "本标相应。", "b": "刘安《淮南子》"}, {"t": "此所谓气之标。", "b": "《素问六·微旨大论》"}], "words": [{"w": "标季", "t": "末季,末期"}, {"w": "治标;标本", "t": "本末。中医称后起为标,本原为本"}, {"w": "标病", "t": "表面上的病症。"}]}, {"meaning": "顶端。", "cites": [{"t": "标出(塔顶露出)海云长。", "b": "唐·李白《秋日登扬州西灵塔》"}], "words": [{"w": "标颠", "t": "顶端,最高点。"}]}, {"meaning": "柱竿之类。", "cites": [{"t": "但立直标,终无曲影。", "b": "《旧唐书·崔彦昭传》"}]}, {"meaning": "旗帜。", "cites": [{"t": "梁祖(朱全忠)自初起,每令左右持大赤旗,缓急之际,用以挥军,祖自目为火龙标。", "b": "宋·陶谷《清异录》"}]}, {"meaning": "标准。", "cites": [{"t": "示我百篇文,诗家一标准。", "b": "唐·杜甫《赠郑十八贲》"}]}, {"meaning": "标明,显出。", "cites": [{"t": "黄琬之早标聪察。", "b": "任昉《王文宪集序》"}], "words": [{"w": "标上号码;标树", "t": "标举,评价。同标置"}, {"w": "标举", "t": "显示,标明。"}]}, {"meaning": "题写。", "cites": [{"t": "名标于奇纪(指《山海经》)。", "b": "《文选·孙绰·游天台山赋》"}], "words": [{"w": "标了牌票", "t": "填写了执行公务的凭照"}, {"w": "标目", "t": "题写书文名称"}, {"w": "标名", "t": "题名。列举姓名"}, {"w": "标句", "t": "撰写词句"}, {"w": "标注", "t": "犹批注。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1425wx','栈','1','zhàn','木','9','','[{"pinyin": "zhàn", "defs": [{"meaning": "(形声。从木,戔(jiān)声。本义:牲口棚)。"}, {"meaning": "同本义。", "cites": [{"t": "栈,棚也。", "b": "《说文》。按,栅者,竖编之,棚者,横编之。"}, {"t": "埋之马栈之下。", "b": "《战国策·齐策》"}, {"t": "马栈最难。", "b": "《管子·小问》"}, {"t": "编之以皁栈。", "b": "《庄子·马蹄》。崔注:“木棚也。”"}, {"t": "毙于内栈。", "b": "颜延之《赭白马赋》"}, {"t": "驽马恋栈豆。", "b": "《晋书·宣帝纪》"}, {"t": "四墙其社,覆上栈下,示不得通。", "b": "《汉书》"}], "words": [{"w": "皂栈", "t": "马房中的栅栏和方格木条。"}]}, {"meaning": "古代用竹木条横排编成车箱的轻便车子。", "cites": [{"t": "栈,竹木之车曰栈。", "b": "《说文》"}, {"t": "有栈之车。", "b": "《诗·小雅·何草不黄》"}, {"t": "车乘栈车。", "b": "《周礼·巾车》"}, {"t": "宾奠币于栈左。", "b": "《仪礼·既夕礼》"}], "words": [{"w": "栈车", "t": "栈舆。古代用竹木条编成车箱的车,不蒙皮革"}, {"w": "栈轸", "t": "指编排竹木条而成的车箱,不蒙皮革"}, {"w": "栈舆马", "t": "陋车劣马。后用为居官清廉俭朴的典实。"}]}, {"meaning": "栈道。", "cites": [{"t": "栈道千里,通于蜀汉。", "b": "《战国策·秦策》"}, {"t": "复从峡度栈以上。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "栈山", "t": "以栈为道跋越高山"}, {"w": "栈山航海", "t": "谓跋山涉水,逾越险阻"}, {"w": "栈谷", "t": "架设栈道以跨越山谷"}, {"w": "栈径", "t": "栈道"}, {"w": "栈云", "t": "谓栈道高与云连"}, {"w": "栈路", "t": "栈道。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1426wx','柑','1','gān','木','9','','[{"pinyin": "gān", "defs": [{"meaning": "(形声。从木,甘声。本义:木名,柑树,果实也称柑)"}, {"meaning": "一种小的有刺柑橘属乔木,复叶,叶翼小。春末夏初开白色花,单生或丛生。果扁圆形,红色或橙黄色,中心柱大,味酸甜不一。种子多为多胚性。性较耐寒。用嫁接、压条、实生等法繁殖。果供生食或加工,果皮、核、叶供药用。亦指柑树的果实。", "words": [{"w": "柑酒", "t": "以柑子为原料酿的酒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1427wx','枯','1','kū','木','9','','[{"pinyin": "kū", "defs": [{"meaning": "(形声。从木,古声。本义:枯槁,草木干枯)。"}, {"meaning": "同本义。", "cites": [{"t": "枯,槁木也。", "b": "《说文》"}, {"t": "草木蚤枯。", "b": "《礼记·月令》"}, {"t": "离离原上草,一岁一枯荣。", "b": "白居易《赋得古草原送别》"}, {"t": "草枯鹰眼疾。", "b": "唐·王维《观猎》"}, {"t": "载燥荻枯柴。", "b": "《资治通鉴》"}, {"t": "菀枯顷刻。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "八月禾未枯。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "枯荣", "t": "草木的繁荣与凋零。后指盛衰;也指干涸,干竭"}, {"w": "枯凋", "t": "枯槁凋零"}, {"w": "枯索", "t": "草木枯萎全无生机"}, {"w": "枯梧", "t": "枯萎的梧桐;泛指枯木。喻卑小的职位"}, {"w": "枯鱼", "t": "干鱼;鱼干;比喻处于困境的人"}, {"w": "枯腊", "t": "枯干的肉,指尸体。"}]}, {"meaning": "弃市暴死。", "cites": [{"t": "捶笞膑脚,斩断枯磔。", "b": "《荀子·正论》。杨倞注:“枯,弃市暴尸也。”"}], "words": [{"w": "枯磔", "t": "古代的两种重刑。枯,指弃市暴死;磔,指车裂。"}]}, {"meaning": "干涸。", "cites": [{"t": "江河之水,驰涌滑漏,席地长远,无枯竭之流,本源盛矣。", "b": "《论衡·效力》"}, {"t": "渊生珠而崖不枯。", "b": "《荀子·劝学》"}, {"t": "山林川泽之数。", "b": "《周礼·天官·司书》。注:“山林川泽童枯则不税。”。疏:“山林不茂为童、川泽无水为枯。”"}], "words": [{"w": "枯池", "t": "干涸的池塘"}, {"w": "枯渴", "t": "干渴"}, {"w": "枯鱼之肆", "t": "比喻身在穷途。"}]}, {"meaning": "空。", "cites": [{"t": "过其枯城,或蘖青青。", "b": "《太玄差》。范望注:“枯,虚也。”"}], "words": [{"w": "枯守", "t": "空守"}, {"w": "枯城", "t": "荒废的旧城"}, {"w": "枯煎", "t": "空受熬煎。"}]}, {"meaning": "干。", "cites": [{"t": "曾不如早索我于枯鱼之肆。《外子·外物》", "b": ""}], "words": [{"w": "枯窘", "t": "枯竭贫乏"}, {"w": "枯泪", "t": "泪已哭尽"}, {"w": "枯灭", "t": "消灭尽。"}]}, {"meaning": "干瘦;憔悴。", "cites": [{"t": "开若枯骸,心若死灰。", "b": "《庄子·知北游》"}, {"t": "颜色憔悴,形容枯槁。", "b": "《史记·屈原列传》"}], "words": [{"w": "枯悴", "t": "憔悴"}, {"w": "枯黧", "t": "憔悴黧黑"}, {"w": "枯黯", "t": "憔悴而灰暗"}, {"w": "枯羸(憔悴羸弱)枯毁(瘦弱,毁损)", "t": ""}]}, {"meaning": "枯朽的树木。", "cites": [{"t": "人皆集于苑,己独集于枯。", "b": "《国语·晋语二》"}]}, {"meaning": "肉已烂尽的骸骨。", "cites": [{"t": "泽及骴骨。", "b": "《吕氏春秋》。高诱注:“骨有肉曰骴,无曰枯。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1428wx','柄','1','bǐng','木','9','','[{"pinyin": "bǐng", "defs": [{"meaning": "(形声。从木,丙声。本义:器物的把儿)。"}, {"meaning": "同本义。", "cites": [{"t": "柄,柯也。(柯:斧柄。)", "b": "《说文》"}, {"t": "覆之南柄。", "b": "《仪礼·少牢礼》"}, {"t": "有柄。", "b": "《仪礼·大射礼》"}, {"t": "柄(铁椎把)铁折叠环复。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "柄子", "t": "方言。器物的把儿"}, {"w": "刀柄;勺柄;曲柄", "t": "曲轴的弯曲部分。"}]}, {"meaning": "权力。", "cites": [{"t": "而皇上无寸柄。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "权柄", "t": "所掌握的权力"}, {"w": "柄用", "t": "被重用而掌握大权"}, {"w": "柄令", "t": "权柄;命令。"}]}, {"meaning": "根本。", "cites": [{"t": "是故礼者,君之大柄也。", "b": "《礼记·礼运》"}, {"t": "谦,德之柄也。", "b": "《易·系辞下》"}, {"t": "治国家不失其柄。", "b": "《国语·齐语》"}]}, {"meaning": "执掌;掌握。同“秉”。", "cites": [{"t": "以八柄诏王驭群臣。", "b": "《周礼·天官·大宰》"}], "words": [{"w": "柄事", "t": "执掌政事"}, {"w": "柄朝", "t": "执掌朝政。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1429wx','栋','1','dòng','木','9','','[{"pinyin": "dòng", "defs": [{"meaning": "(形声。从木,东声。本义:屋的正梁,即屋顶最高处的水平木梁,支承着椽皮 的上端)。"}, {"meaning": "同本义。", "cites": [{"t": "栋,极也。从木,东声。屋内至中至高之处亦曰阿,俗谓之正梁。", "b": "《说文》"}, {"t": "栋隆。", "b": "《易·大过》。虞注:“正中曰栋。”"}, {"t": "仰而视其细枝,则拳曲而不可以为栋梁。", "b": "《庄子·人间世》"}, {"t": "使负栋之柱,多于南亩之农夫。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "梁栋宏可爱。", "b": "韩愈《合江亭》"}], "words": [{"w": "栋宇", "t": "指房屋。栋:屋的正梁;宇:屋的四垂"}, {"w": "栋桴", "t": "屋梁。桴:房屋前后檐的横木"}, {"w": "栋折", "t": "屋梁断折。比喻倾覆"}, {"w": "栋折榱崩", "t": "正梁折断,椽子崩坏,指房倒。多比喻倾覆。"}]}, {"meaning": "比喻堪当大任的人或重要的物。", "cites": [{"t": "天子,国之栋也。", "b": "《国语·晋语》"}, {"t": "主疾无嗣,弄臣为辅。鼎足不强,栋干微挠。", "b": "《汉书·佞幸传赞》"}], "words": [{"w": "栋干", "t": "栋梁干材。比喻担当国家重任的人"}, {"w": "栋甍", "t": "房梁和屋脊。比喻担任重任的人物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1430wx','相','1','xiāng xiàng','目','9','','[{"pinyin": "xiāng", "defs": [{"meaning": "交互;互相。", "cites": [{"t": "故曰教学相长也。", "b": "《礼记·学记》"}, {"t": "民至老死不相往来。", "b": "《老子·小国寡民》"}, {"t": "生当复来归,死当长相思。", "b": "汉·苏武《留别妻》"}, {"t": "当国者相见。", "b": "宋·文天祥《 后序》"}, {"t": "与北骑相出没。", "b": ""}, {"t": "袁人相聚。", "b": "明·高启《书博鸡者事》"}, {"t": "父子相保。", "b": "《淮南子·人间训》"}, {"t": "鸡犬相闻。", "b": "晋·陶渊明《桃花源记》"}, {"t": "更相庆。", "b": "《世说新语·自新》"}, {"t": "里人相庆", "b": ""}, {"t": "青山相对。", "b": "唐·李白《望天门山》"}, {"t": "水石相搏。", "b": "宋·苏轼《石钟山记》"}, {"t": "两相思,两不知。", "b": "南朝宋·鲍照《代春日行》"}], "words": [{"w": "相叙契阔", "t": "互相诉说分别后的情思"}, {"w": "相思锦色", "t": "红豆又称相思豆。即红豆色。"}]}, {"meaning": "共同。", "cites": [{"t": "鲁孟孙、叔孙、季孙相勠力劫昭公", "b": "《韩非子·内储说下》"}], "words": [{"w": "上下相安", "t": ""}]}, {"meaning": "递相;先后。", "cites": [{"t": "死者相藉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "相传以为雁荡。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "络绎相属。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "父子相传;相寻", "t": "连续;不断"}, {"w": "相及", "t": "犹相继。"}]}, {"meaning": "表示一方对另一方有所施为。"}, {"meaning": "表自称。", "cites": [{"t": "便可白公姥,及时相遣归。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "表对称。", "cites": [{"t": "吾已失恩义,会不相从许。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "亲友如相问。", "b": "唐·王昌龄《芙蓉楼送辛渐》"}]}, {"meaning": "表他称。", "cites": [{"t": "狼不敢前,眈眈相向。", "b": "《聊斋志异·狼三则》"}, {"t": "杂然相许。", "b": "《列子·汤问》"}, {"t": "相委而去。", "b": "《世说新语·自新》"}, {"t": "莫相知。(不知道它是什么东西。)", "b": "唐·柳宗元《三戒》"}, {"t": "则噪而相逐。(相逐,追逐他。相,特指代词,单指毛一鹭。)", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "相唤", "t": "招呼"}, {"w": "相牵", "t": "牵来;捆绑"}, {"w": "相招", "t": "招来;引来。"}]}, {"meaning": "相差。", "cites": [{"t": "三王五霸,其所道不过爵禄,而功相万者,其所道明也。", "b": "《商君书·错法》"}], "words": [{"w": "相万", "t": "相差万倍。极言相差之大"}, {"w": "相绝", "t": "相差极大"}, {"w": "相远", "t": "相异;差距大。"}]}]}, {"pinyin": "xiàng", "defs": [{"meaning": "(会意。从目,从木。本义:察看;仔细看)。"}, {"meaning": "同本义。", "cites": [{"t": "相,省视也。", "b": "《说文》"}, {"t": "相,视也。", "b": "《尔雅》"}, {"t": "相时憸民。", "b": "《书·盘庚上》"}, {"t": "惟太保先周公相宅。", "b": "《书·召诰》"}, {"t": "善相丘陵。", "b": "《礼记·月令》"}, {"t": "相鼠有皮,人而无仪。", "b": "《诗·鄘风·相鼠》"}, {"t": "伯乐学相马,顾玩所见,无非马者。", "b": "《论衡·订鬼》"}, {"t": "不敢复相士。", "b": "《史记·平原君虞卿列传》"}, {"t": "胜相士多。", "b": ""}, {"t": "颠倒相来,到底只是一个盖儿。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "相尸", "t": "验尸"}, {"w": "相女配夫", "t": "根据女儿的情况选配女婿"}, {"w": "相脚头", "t": "盗贼作案前窥探线路。"}]}, {"meaning": "看相。", "cites": [{"t": "臣少好相人。", "b": "《史记·高祖本纪》"}], "words": [{"w": "相法", "t": "观察面相体态等以卜吉凶的方法"}, {"w": "相禄", "t": "谓享有福禄的面相。"}]}, {"meaning": "辅佐,扶助。", "cites": [{"t": "有相之道。", "b": "《诗·大雅·生民》"}, {"t": "相夫子。", "b": "《论语·季氏》"}, {"t": "季文子相三君。", "b": "宋·司马光《训俭示康》"}, {"t": "伊尹相汤伐桀。", "b": "《汤誓》"}, {"t": "吾观晋公子之从者,皆足以相国。", "b": "《晋公子重耳出亡》"}, {"t": "使相之。", "b": "晋·干宝《搜神记》"}, {"t": "无物以相之。", "b": "宋·王安石《游褒禅山》"}], "words": [{"w": "相天", "t": "助成自然之道"}, {"w": "相王", "t": "辅佐帝王;谓宰相而封王者"}, {"w": "相吏", "t": "汉代辅佐诸侯王的官员"}, {"w": "相者", "t": "助主人传命或导客的人。"}]}, {"meaning": "教导。", "cites": [{"t": "问谁相礼,则华元…。", "b": "《国语》"}]}, {"meaning": "治,治理。", "cites": [{"t": "相我受民。", "b": "《书·立政》"}]}, {"meaning": "选择。", "cites": [{"t": "良禽相木而栖,贤臣择主而事。", "b": "《三国演义》"}], "words": [{"w": "相攸", "t": "择婚的别称"}, {"w": "相宅", "t": "择地定居;旧时迷信以观察地形地物判定住屋吉凶的一种方术。"}]}, {"meaning": "作某国或某人的相;使作相。", "cites": [{"t": "及遣其子宋襄相齐。", "b": "《史记·项羽本纪》"}]}, {"meaning": "像。", "cites": [{"t": "几树青松常带雨,浑然相个人家。", "b": "《西游记》"}]}, {"meaning": "人的外貌,相貌。", "cites": [{"t": "岂吾相不当侯邪?", "b": "《史记·李将军列传》"}, {"t": "儿已薄禄相。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "非人臣之相也。", "b": "《三国演义》"}, {"t": "内观不识因无相,外合明知作有形。", "b": "《西游记》"}], "words": [{"w": "长相", "t": "相貌"}, {"w": "形相", "t": "外貌;外表"}, {"w": "相表", "t": "相貌;体形"}, {"w": "相品", "t": "仪表,人品。"}]}, {"meaning": "官名。"}, {"meaning": "古代辅佐帝王的大臣。后专指宰相。", "cites": [{"t": "赵歇为王,陈馀为将,张耳为相。", "b": "《史记·项羽本纪》"}, {"t": "王侯将相宁有种乎?", "b": "《史记·陈涉世家》"}, {"t": "况于将相乎。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "托名汉相。", "b": "宋·司马光《资治通鉴》"}, {"t": "有将相。", "b": "清·周容《芋老人传》"}], "words": [{"w": "相辅", "t": "宰相"}, {"w": "将相和;贤相;良相;奸相;权相;相王", "t": "宰相又封王者"}, {"w": "相臣", "t": "宰相。亦泛指大臣"}, {"w": "相父", "t": "皇帝对继续任职的先朝宰相的敬称"}, {"w": "相邦", "t": "相国。"}]}, {"meaning": "汉时诸侯王国的实际执政者,相当于郡太守。", "cites": [{"t": "永和初,出为河间相。", "b": "《后汉书》"}]}, {"meaning": "赞礼者,主持礼节仪式的人。", "cites": [{"t": "宗庙之事,如会同,端章甫,愿为小相焉。", "b": "《论语·先进》"}]}, {"meaning": "古代的一种乐器。", "cites": [{"t": "后乱以武,治乱以相。", "b": "《礼记》"}]}, {"meaning": "农历七月的别名。", "cites": [{"t": "七月为相,八月为壮。", "b": "《尔雅》"}]}, {"meaning": "古地名 。故址在今河南省安阳市西。"}, {"meaning": "引盲人行走的人。", "cites": [{"t": "固相师之道也。", "b": "《论语·卫灵公》"}, {"t": "焉用彼相。", "b": "《论语·季氏》"}], "words": [{"w": "相步;相道", "t": "向导,引导;观察、选择道路。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1431wx','查','1','chá zhā','木','9','','[{"pinyin": "chá", "defs": [{"meaning": "(形声。从木,且声。本义:木筏)。"}, {"meaning": "同本义。同“楂”。", "cites": [{"t": "有巨查浮于西海。", "b": "晋·王嘉《拾遗记·唐尧》"}], "words": [{"w": "查影", "t": "筏影,船影"}, {"w": "查头", "t": "船头。"}]}]}, {"pinyin": "zhā", "defs": [{"meaning": "棍、杖之类。", "cites": [{"t": "懦弱底与它几下刀背,顽猾底与它一顿铁查。", "b": "宋·佚名《张协状元》"}]}, {"meaning": "放纵不拘礼度的人。", "cites": [{"t": "近代流俗,呼丈夫妇人纵放不拘礼度者为查。", "b": "《封氏闻见记》"}], "words": [{"w": "查语", "t": "怪诞或不拘礼度的话"}, {"w": "查谈", "t": "同查语"}, {"w": "查查胡胡", "t": "咋咋呼呼。表示炫耀自己。"}]}, {"meaning": "张开;分开。", "cites": [{"t": "一双怪眼似明星,两耳过肩查又硬。", "b": "《西游记》"}], "words": [{"w": "查耳", "t": "张开耳朵"}, {"w": "查沙", "t": "方言。张开,伸开。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1432wx','柏','1','bǎi bó bò','木','9','','[{"pinyin": "bǎi", "defs": [{"meaning": "(形声。从木,白声。本义:木名,柏树,也称“椈”)。"}, {"meaning": "柏科柏木属植物的通称。", "cites": [{"t": "柏,鞠也。", "b": "《说文》"}, {"t": "柏,椈。", "b": "《尔雅》"}, {"t": "鬯臼以椈。", "b": "《礼记·杂记》"}, {"t": "岁寒,然后知松柏之后凋也。", "b": "《论语·子罕》"}]}, {"meaning": "特指柏台(御史台的别称。汉御史府中列植柏树,固称)。", "cites": [{"t": "俱蟠使下之柏,俱擅乙中之二。", "b": "唐·黄滔《祭陈侍御》"}]}, {"meaning": "古国名。故地在今河南省西平县。", "cites": [{"t": "于是江、黄、道、柏方睦于齐。", "b": "《左传》"}]}]}, {"pinyin": "bó", "defs": [{"meaning": "", "words": [{"w": "柏林;柏拉图", "t": ""}]}]}, {"pinyin": "bò", "defs": [{"meaning": "——见“黄柏”:即黄檗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1433wx','栅','1','zhà shān cè','木','9','','[{"pinyin": "zhà", "defs": [{"meaning": "(会意兼形声。从木,从册,册亦声。本义:栅栏)。"}, {"meaning": "同本义。", "cites": [{"t": "栅,编竖木也。", "b": "《说文》"}, {"t": "木桓曰栅。", "b": "《通俗文》"}, {"t": "内支盈于柴栅。", "b": "《庄子·天地》"}, {"t": "结木为栅。", "b": "《后汉书·段潁传》"}, {"t": "据其栅。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "栅门", "t": "栅栏的门"}, {"w": "栅刺子", "t": "即栅栏"}, {"w": "栅塘", "t": "有栅栏围护的水塘"}, {"w": "栅垒", "t": "安装在栅栏上的锁"}, {"w": "栅孔", "t": "树立栅木的孔洞"}, {"w": "栅墙", "t": "用铁、木条围成的墙"}, {"w": "栅锁、栅钥", "t": "关、开栅栏的锁或钥匙。"}]}, {"meaning": "营寨。", "cites": [{"t": "高祖尽命众军分部甲卒,对冶城立航渡兵,攻其水南二栅。", "b": "《陈书》"}]}, {"meaning": "编竹木搭建的浮桥。", "cites": [{"t": "齐军于秣陵故县跨淮立桥栅,引渡兵马。", "b": "《陈书·高祖纪》"}]}]}, {"pinyin": "shān", "defs": [{"meaning": "由金属细丝组成的筛网状或螺旋状电极,插在电子管另外两个电极之间,起控制板极电流强度、改变电子管性能的作用。"}, {"meaning": "产生光的衍射图像的光学仪器。"}, {"meaning": "[方言]中国北京市前门外一条热闹街市名。"}]}, {"pinyin": "cè", "defs": [{"meaning": "地名，在中国广东省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1434wx','柳','1','liǔ','木','9','','[{"pinyin": "liǔ", "defs": [{"meaning": "(形声。从木,丣(yǒu)声。本义:木名。枝条柔韧。种类很多,常见的有垂柳、旱柳、杞柳等)。"}, {"meaning": "同本义 ,柳属的一种落叶乔木或灌木,枝细长下垂,叶狭长,其中多种有重要经济用途,如作木材,编篮用柳条,或树皮用于鞣皮,其中少数(如白柳和垂柳)为观赏遮荫树木。", "cites": [{"t": "桺,小杨也。", "b": "《说文》"}, {"t": "折柳樊圃。", "b": "《诗·齐风·东方未明》"}, {"t": "青青河畔草,郁郁园中柳。", "b": "《古诗十九首》"}], "words": [{"w": "柳花", "t": "柳树的花"}, {"w": "柳黄", "t": "像柳树芽那样的浅黄色"}, {"w": "柳陌花街", "t": "寻花买笑的场所"}, {"w": "柳绿", "t": "柳叶的青绿色"}, {"w": "柳眼", "t": "初发的柳芽"}, {"w": "柳下", "t": "柳树之下;春秋鲁柳下惠的省称"}, {"w": "柳火", "t": "榆柳之火"}, {"w": "柳市", "t": "柳树成荫的街市"}, {"w": "柳巷", "t": "植柳的里巷。"}]}, {"meaning": "肿瘤。", "cites": [{"t": "俄而,柳生其左肘。", "b": "《庄子·至乐》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1435wx','柱','1','zhǔ zhù','木','9','','[{"pinyin": "zhǔ", "defs": [{"meaning": "支撑", "cites": [{"t": "且鳌足可以柱天,体必长大,不容于天地,女娲虽圣,何能杀之?", "b": "《论衡·谈天》"}], "words": [{"w": "柱天", "t": "撑天;支天"}, {"w": "柱地", "t": "立柱支地。"}]}, {"meaning": "挡住;阻塞。", "cites": [{"t": "内人共举机以柱门,兵斫门,不能破。", "b": "《三国志》"}]}, {"meaning": "拄。", "cites": [{"t": "手把定筇竹,柱杖行田野,出村房。", "b": "《刘知远诸宫调》"}], "words": [{"w": "柱杖", "t": "手杖。"}]}]}, {"pinyin": "zhù", "defs": [{"meaning": "(形声。从木,主声。本义:屋柱)。"}, {"meaning": "同本义。", "cites": [{"t": "柱,楹也。", "b": "《说文》"}, {"t": "剪屏柱楣。", "b": "《仪礼·丧服》。注:“所谓梁闇。”"}, {"t": "东至于底柱。", "b": "《书·禹贡》"}, {"t": "散木也,…以为柱则蠹。", "b": "《庄子·人间世》"}, {"t": "荆轲废,乃引其匕首以掷秦王,不中,中柱。", "b": "《战国策·燕策》"}, {"t": "柱以白璧。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "柱磉石", "t": "支撑柱子的基石"}, {"w": "铜柱;楣柱;柱桷", "t": "屋柱和椽子"}, {"w": "柱梁", "t": "柱和梁"}, {"w": "柱栋", "t": "屋柱与栋梁"}, {"w": "柱极", "t": "殿柱和正梁"}, {"w": "柱楣", "t": "茅庐的立柱和前檐;柱和梁。"}]}, {"meaning": "像柱子的东西。", "cites": [{"t": "王以名使括(赵括),若胶柱鼓瑟耳。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "水柱;冰柱;花柱", "t": ""}]}]}]','jingmo-wenyan');
