INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1437wx','栏','1','lán','木','9','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从木,阑(lán)声。“栏”和“拦”都是后起字。“阑”用作名词时写作“栏”,用作动词时,写作“拦”。本义:栏杆)。"}, {"meaning": "同本义。由扶手和支柱构成的栅杆护围。", "cites": [{"t": "栏,木栏也,谓阶际木句栏。", "b": "《玉篇》"}, {"t": "直栏横槛。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "雕栏相望焉。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "栏楯", "t": "栏杆"}, {"w": "栏干子", "t": "栏杆"}, {"w": "栏角", "t": "栏杆的转角"}, {"w": "栏船", "t": "有栏杆的大木船。"}]}]}]','jingmo-wenyan');
