('1438wx','柠','1','níng','木','9','','[{"pinyin": "níng", "defs": [{"meaning": "木名。", "cites": [{"t": "柠,木皮入酒浸,治风。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1439wx','树','1','shù','木','9','','[{"pinyin": "shù", "defs": [{"meaning": "(形声。从木,尌(shù)声。本义:栽树)。"}, {"meaning": "同本义。", "cites": [{"t": "树,生植之总名。", "b": "《说文》。段注:“植,立也。假借为尌竖字。"}, {"t": "宿敢不封殖此树。", "b": "《左传·昭公二年》"}, {"t": "夫坚树在始。", "b": "《国语·晋语》。注:“树木也。”"}, {"t": "地道敏树。", "b": "周礼《中庸》。注:“谓殖草木也。”"}, {"t": "二曰树艺。", "b": "《周礼·大司徒》"}, {"t": "树之榛栗。", "b": "《诗·鄘风·定之方中》"}, {"t": "五亩之宅,树之以桑,五十者可以衣帛矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "树事", "t": "种植草木之事"}, {"w": "树杨", "t": "种植杨树"}, {"w": "十年之计,在于树木;树其树以荫行人", "t": ""}]}, {"meaning": "种植。", "cites": [{"t": "树,种也。", "b": "《广雅》"}, {"t": "所食之粟,伯夷之所树与?", "b": "《孟子·滕文公下》"}, {"t": "后稷教民稼穑,树艺五谷。", "b": "《孟子·滕文公上》"}], "words": [{"w": "树萱", "t": "种植萱草"}, {"w": "树稼", "t": "种植农作物"}, {"w": "树植", "t": "种植"}, {"w": "树养", "t": "种植培养。"}]}, {"meaning": "竖起或建起;树立。", "cites": [{"t": "崇牙树羽。", "b": "《诗·周颂·有瞽》"}, {"t": "犹有未树也。", "b": "《庄子·逍遥游》"}, {"t": "如是,则人有树事之患,而有争功之祸矣。", "b": "《荀子·富国》"}, {"t": "皆稽颡树颔,扶服蛾伏。", "b": "《汉书·扬雄传下》"}, {"t": "树德而济同欲焉。", "b": "《左传·成公二年》"}, {"t": "无易树子。", "b": "《公羊传·僖公三年》"}, {"t": "筑石寨土堡于要隘,树帜曰:“谢庄团练冯”。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "树炮", "t": "架炮"}, {"w": "树建", "t": "建立,树立"}, {"w": "树表", "t": "竖立标志"}, {"w": "树栅", "t": "构筑栅栏"}, {"w": "树牙", "t": "建立牙旗"}, {"w": "树竿", "t": "竖着竹竿"}, {"w": "树功", "t": "建立功勋"}, {"w": "树事", "t": "建立事业"}, {"w": "树基", "t": "建立根基"}, {"w": "树教", "t": "建立教化"}, {"w": "树君", "t": "立君主"}, {"w": "树子", "t": "古代诸侯立为世子的嫡子。"}]}, {"meaning": "培植;培养。", "cites": [{"t": "终身之计,莫如树人。", "b": "《管子·权修》"}]}, {"meaning": "树木。", "cites": [{"t": "树,木总名也。", "b": "《广韵》"}, {"t": "树,木生植之总名。", "b": "《说文系传》"}, {"t": "有嘉树焉,宣子誉之。", "b": "《左传·昭公二年》"}, {"t": "树木方盛。", "b": "《礼记·月令》"}, {"t": "狗吠深巷中,鸡鸣桑树颠。", "b": "晋·陶渊明《归园田居》"}, {"t": "斜阳草树,寻常巷陌,人道寄奴曾住。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "果树;松树;树科", "t": "草丛;灌木丛"}, {"w": "树上开花", "t": "比喻好上加好"}, {"w": "树老招风,人老招贱", "t": "树老被风吹,人老被轻视"}, {"w": "树末", "t": "树梢"}, {"w": "树桠", "t": "树杈子"}, {"w": "树杪", "t": "树梢"}, {"w": "树株", "t": "树棵"}, {"w": "树阙", "t": "树间空隙"}, {"w": "树簇", "t": "树木丛生"}, {"w": "树瘢", "t": "树木经砍伐后留下的疤痕。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1440wx','勃','1','bó','力','9','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从力,孛(bèi)声。本义:排,推动) 同本义。", "cites": [{"t": "勃,排也。", "b": "《说文》"}, {"t": "勃,展也。", "b": "《广雅》。今苏俗语以力旋转物曰勃。"}], "words": [{"w": "勃郁", "t": "风回旋的样子;郁结"}, {"w": "勃屑", "t": "即勃窣。"}]}, {"meaning": "兴起;旺盛。", "cites": [{"t": "气喷勃以布覆兮。", "b": "马融《长笛赋》"}, {"t": "勃勃,盛也。", "b": "《广雅》"}, {"t": "勃然平世之俗起焉。", "b": "《荀子·非十二子》。注:“兴起貌。”"}], "words": [{"w": "蓬勃", "t": "繁荣;旺盛"}, {"w": "勃腾腾", "t": "烟气上升的样子;怒气上升的样子"}, {"w": "勃勃", "t": "烟气上升的样子。"}]}, {"meaning": "乖戾。", "cites": [{"t": "彻志之勃,解心之谬。", "b": "《庄子·庚桑楚》"}, {"t": "利在故新相反,前后相勃。", "b": "《韩非子·定法》"}], "words": [{"w": "勃乱", "t": "行止违背常理"}, {"w": "勃逆", "t": "叛逆"}, {"w": "勃谿", "t": "相争吵。今婆媳不和叫妇姑勃谿。"}]}, {"meaning": "变容、变色的样子。", "cites": [{"t": "君召使摈,色勃如也。", "b": "《论语·乡党》"}], "words": [{"w": "勃如", "t": "脸色变成庄重的样子"}, {"w": "勃然", "t": "发怒变色的样子;突然;兴起的样子。"}]}, {"meaning": "粉末;粉状物。", "cites": [{"t": "有黄黑勃,着之污人手。", "b": "《农政全书·种植》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1441wx','要','1','yāo yào','覀','9','','[{"pinyin": "yāo", "defs": [{"meaning": "(象形。小篆字形。中间象人形,两旁为两手形。表示两手叉腰。本义:人腰)。"}, {"meaning": "“腰”的古字。", "cites": [{"t": "昔者,楚灵王好细要。", "b": "《墨子》"}, {"t": "户服艾以盈要兮,谓幽兰其不可佩。", "b": "《楚辞》"}, {"t": "故量食而食之,量要而带之。", "b": "《荀子·礼论》"}], "words": [{"w": "要膂", "t": "腰和脊骨。比喻重要部位"}, {"w": "要章", "t": "腰间所佩的印"}, {"w": "要支", "t": "腰肢。"}]}, {"meaning": "约请;邀请。", "cites": [{"t": "便要还家,设酒杀鸡作食。", "b": "晋·陶潜《桃花源记》"}, {"t": "张良出,要项伯。", "b": "《史记·项羽本纪》"}, {"t": "石崇每要客燕集。", "b": "《世说新语·汰侈门》"}], "words": [{"w": "要引", "t": "邀迎荐举"}, {"w": "要约", "t": "邀约;邀请。"}]}, {"meaning": "约言。以明誓的方式就某事作出庄严的承诺或表示某种决心。亦指所订立的誓约、盟约。", "cites": [{"t": "岂要黄河誓,须勒燕然石。", "b": "唐·崔湜《寒垣行》"}], "words": [{"w": "要约", "t": "立盟;立约;约定"}, {"w": "要契", "t": "契约;盟约。"}]}, {"meaning": "(jiǎo)。探求;求取。", "cites": [{"t": "不庶几,不要幸。", "b": "《晏子春秋·内篇问下》。孙星衍云:“要与徼通。”"}, {"t": "今之人修其天爵,以要人爵。", "b": "《孟子·告子上》。赵岐注:“要,求也。”"}, {"t": "要利之人,犯危何益?", "b": "《吕氏春秋·爱类》。高诱注:“要,徼也。”"}], "words": [{"w": "要禄", "t": "求取利禄"}, {"w": "要福", "t": "祈求幸福。"}]}, {"meaning": "拦阻;截击。", "cites": [{"t": "使数人要于路。", "b": "《孟子·公孙丑下》"}, {"t": "且前日要政,政徒以老母。", "b": "《史记·刺客列传》"}, {"t": "张良出,要项伯。", "b": "《史记·项羽本纪》"}], "words": [{"w": "要勒", "t": "遮拦;阻挡"}, {"w": "要御", "t": "拦阻控制"}, {"w": "要路", "t": "拦路;遮道。"}]}, {"meaning": "(yuē)。胁迫。", "cites": [{"t": "明神洋蠲要盟。", "b": "《左传·襄公九年》"}, {"t": "且要盟无质。", "b": ""}, {"t": "虽不要君,吾不信也。", "b": "《论语·宪问》"}, {"t": "以要晋国之成。", "b": "《国语·晋语三》"}], "words": [{"w": "要市", "t": "以要挟手段谋取利益或迫使对方满足自己的某种要求"}, {"w": "要劫", "t": "胁迫劫待。"}]}, {"meaning": "姓。"}]}, {"pinyin": "yào", "defs": [{"meaning": "要点,纲要。", "cites": [{"t": "事在四方,要在中央。", "b": "《韩非子》"}, {"t": "故其治国也,察要而已矣。", "b": "《商君书》"}], "words": [{"w": "纪要", "t": "记录要点的文字"}, {"w": "扼要", "t": "抓住要点"}, {"w": "要谛", "t": "要义"}, {"w": "要窍", "t": "要诀;关键的办法"}, {"w": "要归", "t": "重点所在;要旨"}, {"w": "要本", "t": "要旨;根本"}, {"w": "要端", "t": "要点"}, {"w": "要令", "t": "主旨;要旨"}, {"w": "要义", "t": "要旨"}, {"w": "要机", "t": "犹要旨。"}]}, {"meaning": "计数的簿书。", "cites": [{"t": "大役与虑,事属其植。受其要,以待考而赏诛。", "b": "《周礼》。郑玄注:“要者,簿书也。考,谓考较其功。”"}], "words": [{"w": "要会", "t": "会计;簿书。"}]}, {"meaning": "权柄。", "cites": [{"t": "事在四方,要在中央,圣人执要,四方来效。", "b": "《韩非子》"}], "words": [{"w": "要贵", "t": "犹显贵,权贵"}, {"w": "要势", "t": "谓权贵的势力。常指居要位有权势者。"}]}, {"meaning": "指重要的地位或职务。", "cites": [{"t": "以吾二人久居内要,常有不善之言,恐祸及人,深宜虑之。", "b": "《晋书》"}], "words": [{"w": "要道", "t": "比喻职位要且有权有势的人。"}]}, {"meaning": "总要。", "cites": [{"t": "要以不能免。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "", "cites": [{"t": "要离之刺庆忌也,仓鹰击于殿上。", "b": "《战国策·魏策》"}]}, {"meaning": "重要,重大。", "cites": [{"t": "增减要语。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "要着", "t": "重要的措施或计谋"}, {"w": "要囚", "t": "重要的囚犯"}, {"w": "要局", "t": "重要部门"}, {"w": "要具", "t": "重要的手段"}, {"w": "要重", "t": "犹重要"}, {"w": "要则", "t": "重要的准则"}, {"w": "要切", "t": "重要适切"}, {"w": "要月", "t": "指农作重要的时令"}, {"w": "要言", "t": "至言,重要的话"}, {"w": "要务", "t": "重要的事务"}, {"w": "要术", "t": "重要的方法和谋略"}, {"w": "要最", "t": "最重要的事理、事物"}, {"w": "要剧", "t": "指重要而政事繁忙的职位"}, {"w": "要事;要犯", "t": ""}]}, {"meaning": "简要。", "cites": [{"t": "故明主好要,而暗主好详。", "b": "《荀子》"}], "words": [{"w": "要屈", "t": "谓简约仪仗、屈尊同众"}, {"w": "要括", "t": "扼要,简括"}, {"w": "要约", "t": "简练,精练"}, {"w": "要言", "t": "言论简扼。"}]}, {"meaning": "地位显要。", "cites": [{"t": "北收要害之郡(要害之郡,政治、经济、军事上都非常重要的城邑)。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "要近", "t": "显要且能接近天子的官位"}, {"w": "要位", "t": "显要地位"}, {"w": "要显", "t": "犹显要。亦指显要之官"}, {"w": "要官", "t": "显要的职务;重要的官位"}, {"w": "要缺", "t": "重要的官位。"}]}, {"meaning": "想要,希望。", "cites": [{"t": "要留清白。", "b": "明·于谦《石灰吟》"}, {"t": "要汝知闻。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "要货", "t": "想出卖"}, {"w": "要待", "t": "想要;待要。"}]}, {"meaning": "使;让;叫。", "cites": [{"t": "扫云物以贞观,要万涂而来归。", "b": "《文选·陆机·吊魏武帝文》。张铣注:“要,犹使也。”"}]}, {"meaning": "表示比较;估计。", "cites": [{"t": "他年纪稍轻一点,脸也要瘦一些。", "b": "巴金《家》"}]}, {"meaning": "表示选择,相当于要么…要么。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1442wx','柬','1','jiǎn','木','9','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(会意。从束,从八。“束”,札束。“八”,分别的意思。本义:挑选,从事物中分别出好坏) 同本义。从作“拣”。", "cites": [{"t": "柬,分别择之也。", "b": "《说文》"}, {"t": "安燕而血气不惰,柬理也。", "b": "《荀子·修身》"}], "words": [{"w": "柬汰", "t": "挑出剔去"}, {"w": "柬拔", "t": "选拔"}, {"w": "柬寄", "t": "选择并委以重任"}, {"w": "柬择", "t": "选择"}, {"w": "柬擢", "t": "选拔。"}]}, {"meaning": "柬埔寨的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1443wx','咸','1','xián','口','9','','[{"pinyin": "xián", "defs": [{"meaning": "(会意。据甲骨文。从戌(xū),从口。戌是长柄大斧,“口”指人头。合起来表示大斧砍人头。本义:杀)。"}, {"meaning": "同本义。", "cites": [{"t": "咸刘厥敌。", "b": "《书·君奭》"}]}, {"meaning": "毕;终。", "cites": [{"t": "迄始皇三载而咸,时、激、地、保、人事乎?", "b": "汉·扬雄《法言》"}]}, {"meaning": "感应。", "cites": [{"t": "…窕则不咸。", "b": "《左传》"}], "words": [{"w": "咸腓", "t": "妄动"}, {"w": "咸感", "t": "阴阳相感,夫妇相和。"}]}, {"meaning": "普遍都,全部。", "cites": [{"t": "咸,皆也,悉也。", "b": "《说文》"}, {"t": "庶绩咸熙。", "b": "《书·尧典》"}, {"t": "周邦咸喜。", "b": "《诗·大雅·崧高》"}, {"t": "村中闻有此人,咸来问讯。", "b": "晋·陶渊明《桃花源记》"}, {"t": "咸怃然。", "b": "唐·柳宗元《柳河东集》"}, {"t": "京城学者咸怪其无征。", "b": "《后汉书·张衡传》"}, {"t": "属吏咸伏渴。", "b": "《明史》"}], "words": [{"w": "咸叨福庇", "t": "都借光沾了福气"}, {"w": "咸宥", "t": "全部宽恕"}, {"w": "咸臻", "t": "全都到达"}, {"w": "咸五登三", "t": "帝德广被,同于五帝而超于三王。"}]}, {"meaning": "共;同。", "cites": [{"t": "敦商之旅,克咸厥功。", "b": "《诗·鲁颂·閟宫》"}]}, {"meaning": "普遍。", "cites": [{"t": "小赐不咸,独恭不优。不咸,民不归也;不优,神弗福也。", "b": "《国语》"}]}, {"meaning": "协和,调和。", "cites": [{"t": "舟中鸣鼓若竞渡,挽人从山石中闻鼓声而咸力。", "b": "《天工开物》"}]}, {"meaning": "咸阳(今为地级市,位于陕西西安西北20公里)。中国古代文化的发祥地。公元前350年秦孝公都咸阳,城市宫殿林立。公元前206年为楚项羽焚毁,简称咸。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1444wx','威','1','wēi','女','9','','[{"pinyin": "wēi", "defs": [{"meaning": "威力;威风。", "cites": [{"t": "威,畏也。", "b": "《说文》"}, {"t": "威也者,力也。", "b": "《吕氏春秋·荡兵》"}, {"t": "有而可畏谓之威《史记·平原君虞卿列传》", "b": ""}, {"t": "严大国之威。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "秦王之威。", "b": ""}, {"t": "威天下不以兵革。", "b": "《孟子·公孙丑下》"}, {"t": "威棱威乎邻国。", "b": "《汉书·李广传》"}, {"t": "威振四海。", "b": "汉·贾谊《过秦论》"}, {"t": "为敛威去。", "b": "《明史》"}], "words": [{"w": "威风杀气", "t": "威风恶煞;盛气凌人"}, {"w": "威弧", "t": "很有威力的弧矢"}, {"w": "威折", "t": "以威力使之折服"}, {"w": "威服", "t": "以威力慑服"}, {"w": "威柄", "t": "威权,权力"}, {"w": "威畏", "t": "以威势使之畏服"}, {"w": "威约", "t": "威势为人制约"}, {"w": "威凌", "t": "以威势相欺凌"}, {"w": "威绥", "t": "以威力使之安定。"}]}, {"meaning": "尊严,威严。", "cites": [{"t": "畏威保位。", "b": "《明史》"}, {"t": "吏惮其威。", "b": ""}], "words": [{"w": "威荣", "t": "尊严与荣华"}, {"w": "威法", "t": "威严的法令"}, {"w": "威神", "t": "尊严的神灵"}, {"w": "威裕", "t": "威严和宽仁"}, {"w": "威敬", "t": "有威严,令人敬重"}, {"w": "威光", "t": "威严的光芒"}, {"w": "威棱", "t": "声势威仪"}, {"w": "威德", "t": "威严与恩德"}, {"w": "威锋", "t": "威德"}, {"w": "威权", "t": "威势与权力"}, {"w": "威灵", "t": "声势威仪"}, {"w": "威声", "t": "威严的名声"}, {"w": "威神", "t": "威仪的神灵"}, {"w": "威化", "t": "声威德化。"}]}, {"meaning": "虐害", "cites": [{"t": "民不畏威,则大威至。", "b": "《老子》"}]}, {"meaning": "古代军事编制单位。", "cites": [{"t": "百户为“威”,设中、前、后、左、右五所,每军百户曰威。", "b": "《南疆逸史》"}]}, {"meaning": "畏惧", "cites": [{"t": "死丧之威,兄弟孔怀。", "b": "《诗·小雅·常棣》"}, {"t": "威,畏也,可畏惧也。", "b": "《释名·释言语》"}, {"t": "见怀思威。", "b": "《国语·晋语四》"}]}, {"meaning": "震慑。", "cites": [{"t": "吾三战而三胜,声威天下。", "b": "《战国策》"}, {"t": "教我先威众。", "b": "《史记·陈涉世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1445wx','歪','1','wāi wǎi','止','9','','[{"pinyin": "wāi", "defs": [{"meaning": "(会意。合不正二字为一字,“不正”为歪。本义:不正,偏斜)。"}, {"meaning": "同本义。", "cites": [{"t": "适值公案桌歪欹（qī）,…其案桌遂不歪欹。", "b": "明·孙高亮《于谦全传》"}], "words": [{"w": "歪辣", "t": "脚跟不正。喻指作风不正派"}, {"w": "歪不横楞", "t": "歪歪扭扭。歪斜不正的样子"}, {"w": "歪不楞", "t": "丑陋"}, {"w": "歪欹", "t": "不正"}, {"w": "歪嘴", "t": ""}]}, {"meaning": "不正当;不正派;不正直。", "cites": [{"t": "你那师父那秃歪刺货往那里去了?", "b": "《红楼梦》"}], "words": [{"w": "歪摆布", "t": "用不正当手段捉弄人"}, {"w": "歪物件", "t": "坏东西。骂人的话"}, {"w": "歪人", "t": "不正派的人"}, {"w": "歪货", "t": "贱货,坏家伙。来路不正的人"}, {"w": "歪剌", "t": "歪剌骨。歪剌货。卑劣下贱的人"}, {"w": "歪歪搭搭", "t": "不正派"}, {"w": "歪意", "t": "邪念,坏心思"}, {"w": "歪行货", "t": "坏家伙"}, {"w": "歪剌姑气", "t": "邪气;冤气"}, {"w": "歪主意;歪念头;歪道理;歪话", "t": "反对的话"}, {"w": "歪憋", "t": "蛮不讲理。"}]}, {"meaning": "躺;侧卧或半躺下休息。", "cites": [{"t": "进了西轩,歪在床上。", "b": "清·庾岭劳人《蜃楼志全传》"}], "words": [{"w": "歪一会", "t": ""}]}, {"meaning": "扭伤。", "cites": [{"t": "方才大老爷出去,被石头绊了一下,歪了腿。", "b": "《红楼梦》"}]}]}, {"pinyin": "wǎi", "defs": [{"meaning": "扭伤。", "cites": [{"t": "被石头绊了一下,歪了腿。", "b": "《红楼梦》"}], "words": [{"w": "歪了脚", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1446wx','研','1','yán yàn','石','9','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从石,幵(jiān)声。本义:细磨)。"}, {"meaning": "同本义。", "cites": [{"t": "打取杏仁,以汤脱去黄皮,熟研,以水和之,绢滤取汁。", "b": "《齐民要术》"}, {"t": "晚上把这药用酒研开,替他敷上。", "b": "《红楼梦》"}], "words": [{"w": "研石", "t": "磨墨的用具"}, {"w": "研弄", "t": "磨墨弄笔。"}]}, {"meaning": "研究;探讨。", "cites": [{"t": "能研诸侯之虑。", "b": "《易·系辞》。注:“研,俞思虑也。”疏:“精也。”"}, {"t": "研核阴阳。", "b": "南朝宋·范晔《后汉书·张衡传》"}], "words": [{"w": "研榷", "t": "研究;商订"}, {"w": "研述", "t": "研究并阐述"}, {"w": "研味", "t": "研究玩味"}, {"w": "研治", "t": "研究"}, {"w": "研省", "t": "研究省察"}, {"w": "研赏", "t": "研究赏析"}, {"w": "研究", "t": "细致审问"}, {"w": "研务", "t": "探究事理。"}]}]}, {"pinyin": "yàn", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1447wx','砖','1','zhuān','石','9','','[{"pinyin": "zhuān", "defs": [{"meaning": "(形声。从石,专声。本义:用粘土烧成的长方形块状建材)。"}, {"meaning": "同本义。", "cites": [{"t": "是犹以塼涂塞江海也。", "b": "《荀子·正论》。注:“塼涂,以涂垒塼也。”"}, {"t": "蒙诏赐银百两,已于扬州小郊北地烧砖。", "b": "《颜氏家训》"}], "words": [{"w": "青砖;红砖;砖匠", "t": "从事铺方砖或雕砖的工人"}, {"w": "砖橛子", "t": "碎砖;断砖"}, {"w": "砖位", "t": "古代朝官班位的标识"}, {"w": "砖塔", "t": "以砖为主要建筑材料的佛塔"}, {"w": "砖块", "t": "块砖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1448wx','厘','1','lí','厂','9','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从里,从“里”,表示与居住家居有关。本义:家福;幸福)。"}, {"meaning": "同本义。", "cites": [{"t": "祠官祝釐。", "b": "《汉书·文帝纪》。如淳注:“福也。”"}, {"t": "上方受釐坐宣室。", "b": "《汉书·贾谊传》"}, {"t": "逆釐三神者。", "b": "扬雄《甘泉赋》。服虔注:“福也。”"}], "words": [{"w": "恭祝新厘", "t": ""}]}, {"meaning": "治理;处理。", "cites": [{"t": "允厘百工,庶绩咸熙。", "b": "《书·尧典》"}, {"t": "釐降二女于妫汭。", "b": "《史记·作信饬百官》"}, {"t": "帝釐下土方。", "b": "《书·序》。马注:“理也。”"}, {"t": "王釐尔成。", "b": "《诗·臣工》。笺:“理也。”"}], "words": [{"w": "厘剔", "t": "治理剔除"}, {"w": "厘和", "t": "治理协和"}, {"w": "厘正", "t": "考据订正;整治改正"}, {"w": "厘盐", "t": "治理盐务。"}]}, {"meaning": "改正;改革。", "cites": [{"t": "釐改制量。", "b": "《国语·周语》"}, {"t": "施行日久,岂一朝所厘?", "b": "《后汉书·梁统传》"}], "words": [{"w": "厘改", "t": "改革;改正"}, {"w": "厘剔", "t": "纠正剔除"}, {"w": "厘祀", "t": "改革祭神制度,废除淫词。"}]}, {"meaning": "整理。", "cites": [{"t": "因取八十一题,厘为九类。", "b": "阮元《畴人传》"}], "words": [{"w": "厘定;厘次", "t": "整理编次。"}]}, {"meaning": "给予,赐予。", "cites": [{"t": "厘尔圭瓒。", "b": "《诗·大雅·江汉》"}], "words": [{"w": "厘降", "t": "屈身下嫁;屈尊而降。"}]}, {"meaning": "重量单位,两的千分之一。"}, {"meaning": "地积单位,亩的百分之一。"}, {"meaning": "利率单位。对于年利一厘为百分之一;对于月利一厘为千分之一。"}, {"meaning": "寡妇。", "cites": [{"t": "兄亡则纳厘嫂。", "b": "范晔《后汉书·西羌传》"}], "words": [{"w": "厘妇", "t": "寡妇。厘通嫠"}, {"w": "厘嫂", "t": "寡嫂。厘通嫠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1449wx','厚','1','hòu','厂','9','','[{"pinyin": "hòu", "defs": [{"meaning": "(会意。从厂(hǎn),表示与山石有关。本义:地壳厚。与“薄”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "谓地盖厚。", "b": "《诗·小雅·正月》"}, {"t": "穷高极远而测深厚。", "b": "《礼记·乐记》。注:“深厚,山川也。”"}, {"t": "厚将崩。", "b": "《左传·隐公元年》"}, {"t": "见于厚土。", "b": "《素问·王常政大论》"}], "words": [{"w": "厚土", "t": "覆土厚"}, {"w": "厚地", "t": "大地"}, {"w": "厚坤", "t": "大坤"}, {"w": "厚厚", "t": "大地。"}]}, {"meaning": "扁平物体上下两面之间距离大的。 与“薄”相对。", "cites": [{"t": "刀刃者无厚。", "b": "《庄子·养生主》"}, {"t": "以无厚入有间。", "b": ""}], "words": [{"w": "厚木板;厚嘴唇;厚膊", "t": "厚的肉干"}, {"w": "厚皮", "t": "脸皮厚"}, {"w": "厚大", "t": "又厚又大"}, {"w": "厚皮馒头", "t": "比喻不切题的文章、言论"}, {"w": "厚厚", "t": "很厚。"}]}, {"meaning": "大。", "cites": [{"t": "不厚其栋。", "b": "《国语·鲁语》。注:“大也。”"}], "words": [{"w": "厚幸", "t": "大幸"}, {"w": "厚福", "t": "大福"}, {"w": "厚德", "t": "大德。"}]}, {"meaning": "丰厚。", "cites": [{"t": "告之者其赏厚而信。", "b": "《韩非子·奸劫弑臣》"}, {"t": "蓄禄不厚,则民不信。", "b": "《墨子·尚贤上》"}, {"t": "崔氏之家财产甚厚。", "b": "元稹《莺莺传》"}, {"t": "奉厚而无劳。", "b": "《战国策·赵策》"}, {"t": "厚赂单于。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "厚贶", "t": "丰厚的赏赐"}, {"w": "厚施", "t": "以丰厚的财物给人"}, {"w": "厚秩", "t": "丰厚的俸禄"}, {"w": "厚俸", "t": "丰厚的俸禄。"}]}, {"meaning": "重;多。", "cites": [{"t": "厚其液而节其帤。", "b": "《周礼·考工记·弓人》。注:“多也。”"}, {"t": "厚资而遣之。", "b": "清·周容《芋老人传》"}], "words": [{"w": "厚诬", "t": "大加毁谤"}, {"w": "厚优", "t": "优厚的照顾"}, {"w": "厚款", "t": "厚意款待"}, {"w": "厚报", "t": "优厚的酬劳。"}]}, {"meaning": "忠厚。", "cites": [{"t": "周勃重厚少文,然安刘氏者必勃也。", "b": "《史记·高祖本纪》"}, {"t": "人心风俗日益厚。", "b": "魏源《海运全案跋》"}, {"t": "宽厚而爱人。", "b": "汉·贾谊《过秦论》"}, {"t": "行厚而辞深。", "b": "唐·柳宗元《柳河东集》"}, {"t": "陈明选宽厚呕煦。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "厚亡", "t": "亡失很多"}, {"w": "厚费", "t": "耗费多"}, {"w": "厚扰", "t": "多多打扰。"}]}, {"meaning": "深。", "cites": [{"t": "必厚其鞈。", "b": "《吕氏春秋·辨士》。注:“深也。”"}], "words": [{"w": "厚交", "t": "深交"}, {"w": "厚结", "t": "深相结交"}, {"w": "厚诬", "t": "深加欺骗、蒙蔽。"}]}, {"meaning": "深厚。", "cites": [{"t": "然公子遇臣厚。", "b": "《史记·魏公子列传》"}, {"t": "陵与子卿素厚。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "厚密", "t": "情义深厚密切"}, {"w": "厚情", "t": "深厚的情意"}, {"w": "厚德", "t": "深厚的恩德"}, {"w": "厚泽", "t": "深厚的恩泽。"}]}, {"meaning": "财富。", "cites": [{"t": "毁国之厚以利其家,臣不谓智。", "b": "《韩非子·有度》"}]}, {"meaning": "优待;推崇。", "cites": [{"t": "因而厚遇之。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "蒙君实视遇厚。", "b": "宋·王安石《答司马谏议书》"}, {"t": "遇足下素厚。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "厚生", "t": "重视养生以保长寿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1450wx','砌','1','qì qiè','石','9','','[{"pinyin": "qì", "defs": [{"meaning": "(形声。从石,切声。本义:台阶)。"}, {"meaning": "同本义。", "cites": [{"t": "雕阑玉砌应犹在,只是朱颜改。", "b": "李煜《虞美人》词"}, {"t": "砌水(滴在台阶上的雨水);砌石(阶石);砌阶(台阶)", "b": ""}]}, {"meaning": "门限,门槛。", "cites": [{"t": "于是玄墀釦砌,玉阶彤庭。", "b": "汉·班固《西都赋》"}]}, {"meaning": "堆砌。", "cites": [{"t": "砌 以青玉。", "b": "《战国策·魏策》"}, {"t": "砌石为磴。", "b": "清·姚鼐《登泰山记》"}, {"t": "砌红砌绿(形容春日花木繁荣的景象)", "b": ""}]}]}, {"pinyin": "qiè", "defs": [{"meaning": "指戏剧。", "cites": [{"t": "诸杂砌:《摸石江》、《梅妃》…。", "b": "陶宗仪《辍耕录》"}]}, {"meaning": "串演。", "cites": [{"t": "俺怕不占场儿砌一个《锦西湖上马娇》。", "b": "汤显祖《牡丹亭》"}]}]}]','jingmo-wenyan');
