INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1455wx','面','1','miàn','面','9','','[{"pinyin": "miàn", "defs": [{"meaning": "(象形。甲骨文字形,里面是“目”字,外面表示面庞。“面”,在古代指人的整个面部。“脸”是魏晋时期才出现,而且只指两颊的上部,唐宋口语中才开始用同“面”本义:脸)。"}, {"meaning": "同本义。", "cites": [{"t": "面,颜前也。", "b": "《说文》"}, {"t": "使万民和说而正王面。", "b": "《周礼·撢人》"}, {"t": "私面私献。", "b": "《周礼·司仪》"}, {"t": "大辂在宾阶面。", "b": "《书·顾命》"}, {"t": "必唾其面。", "b": "《战国策·赵策》"}, {"t": "满面尘灰烟火色。", "b": "唐·白居易《卖炭翁》"}, {"t": "女之靧面。", "b": "明·袁宏道《满井游记》"}, {"t": "椎髻仰面。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "面不厮睹", "t": "脸不对着看,表示生气"}, {"w": "颜面", "t": "脸面;脸部;体面;面子"}, {"w": "满面", "t": "整个面部。"}]}, {"meaning": "外表;表面。", "cites": [{"t": "微澜动水面。", "b": "韩愈《南山诗》"}], "words": [{"w": "面从", "t": "表面顺从。指非出于由衷之愿"}, {"w": "面友", "t": "非以真诚相交的朋友"}, {"w": "面交", "t": "不以真诚相交的朋友"}, {"w": "面朋", "t": "未以真诚相交的朋友。"}]}, {"meaning": "部位;方面。", "cites": [{"t": "四面竹树环合。", "b": "柳宗元《至小丘西小石潭记》"}, {"t": "南面有三谷。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "球的上表面;光明面;四面包围敌人;面面", "t": "各方面,各角度。"}]}, {"meaning": "几何学上称线移动所生成的形迹。", "cites": [{"t": "皆面也。", "b": "蔡元培《图画》"}, {"t": "体面互见。", "b": ""}, {"t": "水面初平云脚低。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "舍体而取面;平面;面积", "t": ""}]}, {"meaning": "当面。", "cites": [{"t": "面语之。", "b": "清·方苞《狱中杂记》"}, {"t": "即面署第一。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "面欺", "t": "当面欺君"}, {"w": "面是背非", "t": "面和心不和"}, {"w": "面陈", "t": "当面陈述"}, {"w": "面违", "t": "当面违逆他人意旨。"}]}, {"meaning": "朝向;面对;面向。", "cites": [{"t": "皆西面而望大王。", "b": "《战国策·秦策五》"}, {"t": "北山愚公者,年且九十,面山而居。", "b": "《列子·汤问》"}, {"t": "面山而居。", "b": ""}, {"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·赵策》"}, {"t": "面墙而立,不成人也。", "b": "《晋书·凉武昭王传》"}, {"t": "开窗面场圃,把酒话桑麻。", "b": "唐·孟浩然《过故人庄》"}, {"t": "南面召见。", "b": "明·宗臣《报刘一丈书》"}, {"t": "背山而面野。", "b": "〔英〕赫胥黎著、严复译《天演论》"}], "words": [{"w": "面壁", "t": "佛家语,指面对墙壁,端坐静修"}, {"w": "面面相窥", "t": "你看我,我看你,互相对看"}, {"w": "面墙而立", "t": "人如不学,就象面向墙壁而立,毫无所见"}, {"w": "面面", "t": "面对面。"}]}, {"meaning": "见面。", "cites": [{"t": "许久不面,请到宫少坐一时,何如?", "b": "《西游记》"}], "words": [{"w": "面圣", "t": "旧时称朝见皇帝为面圣。"}]}, {"meaning": "勉励。", "cites": [{"t": "天迪从子保,面稽天若。", "b": "《书·召诰》"}, {"t": "谋面,用丕训德。", "b": "《书·立政》"}]}, {"meaning": "面向。", "cites": [{"t": "尊壶者面其鼻。", "b": "《礼·少仪》"}]}, {"meaning": "背向。", "cites": [{"t": "马童面之。", "b": "《史记·项羽本纪》"}, {"t": "面而封之。", "b": "《汉书·张欧传》"}]}, {"meaning": "面粉,小麦精细地磨成的粉。", "cites": [{"t": "麪,麦末也。", "b": "《说文》"}], "words": [{"w": "面糊鬼", "t": "用面糊粘成的纸牌"}, {"w": "玉米面;大米面;白面", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1456wx','耐','1','nài','而','9','','[{"pinyin": "nài", "defs": [{"meaning": "(会意。从而,从寸。而亦声。“而”指面颊,“寸”指法度,刑法。在面颊上施刑罚,指剃须。字本作“耏”。从而,从彡。本义:古时一种剃掉胡须两年的刑罚)。"}, {"meaning": "同本义。", "cites": [{"t": "耏,罪不至耏也。", "b": "《说文》。按,不剃发也。"}, {"t": "耏以上请之。", "b": "《汉书·高帝纪》。应劭注:“轻罪不至于耏,完其耏鬓。故曰耏。”"}, {"t": "耐罪亡命。", "b": "《后汉书·高帝纪》。注:“耐,轻刑之名。一岁刑为罚作,二岁刑以上为耐。”"}, {"t": "耏,多须貌。", "b": "《后汉书·章帝纪》注"}, {"t": "从事有亡,卒岁得,可论?耐。", "b": "《睡虎地秦墓竹简》"}], "words": [{"w": "耐罪", "t": "古代剃去鬓须的刑罚。耐,同“耏”。"}]}, {"meaning": "忍耐;忍受。引申为容忍。", "cites": [{"t": "能耐任之则慎行此道也。", "b": "《荀子·仲尼》"}, {"t": "耐以上。", "b": "《汉书·文帝纪》"}, {"t": "此物性不耐寒。", "b": "《齐民要术·种椒》"}, {"t": "华鬓不耐秋。", "b": "李白《古风五十九首》"}], "words": [{"w": "耐痛", "t": "能忍受疼痛"}, {"w": "耐辱", "t": "能忍受屈辱"}, {"w": "耐静", "t": "忍受寂寞,安于清静。"}]}, {"meaning": "禁得起。", "cites": [{"t": "秦兵耐苦战。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "耐旱", "t": "经得起干旱"}, {"w": "耐事", "t": "经得起得失、荣辱等人事之变"}, {"w": "耐酸", "t": "能经受清寒困苦"}, {"w": "耐实", "t": "牢固。"}]}, {"meaning": "适宜;相称。", "cites": [{"t": "青春复随冠冕入,紫禁正耐烟花绕。", "b": "唐·杜甫《洗兵马》"}]}, {"meaning": "无奈;奈何。", "cites": [{"t": "亭午减汗流,北邻耐人聒。", "b": "唐·杜甫《七月三日…呈元二十一曹长》"}], "words": [{"w": "耐何", "t": "奈何。犹对付、应付。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1457wx','耍','1','shuǎ','而','9','','[{"pinyin": "shuǎ", "defs": [{"meaning": "(会意。从而,从女。而,颊毛。盖谓用颊毛戏弄女子。本义:戏耍。一般指不正当的行为)。"}, {"meaning": "玩耍,游玩;消闲取乐。", "cites": [{"t": "长颦知有恨,贪耍不成妆。", "b": "宋·周邦彦《意难忘》"}, {"t": "一群猴子耍了一会,都去那山涧洗澡。", "b": "《西游记》"}], "words": [{"w": "耍水", "t": "玩水,游泳"}, {"w": "耍货", "t": "玩具"}, {"w": "耍拳", "t": "打拳"}, {"w": "耍歇", "t": "玩耍休息。"}]}, {"meaning": "戏谑;捉弄。", "cites": [{"t": "等他来时,诱他去粪窖边,只做参贺他,双手抢住脚,翻筋斗,攧那厮下粪窖去,只是小耍他。", "b": "《水浒传》"}], "words": [{"w": "耍处", "t": "开玩笑;闹着玩儿"}, {"w": "耍窨", "t": "假装糊涂;捉迷藏。"}]}, {"meaning": "舞弄;使用武器、器物等。", "cites": [{"t": "醒时便在院里耍刀弄棒。", "b": "《红楼梦》"}], "words": [{"w": "耍弄", "t": "舞弄"}, {"w": "耍拳", "t": "打拳"}, {"w": "耍狮子", "t": "一种传统的民间舞蹈"}, {"w": "耍枪", "t": "耍花枪"}, {"w": "耍盘子", "t": "即转碟。杂技节目"}, {"w": "耍龙", "t": "一种传统的民间游艺。"}]}, {"meaning": "赌博。", "cites": [{"t": "负者献耍金耍银买燕。", "b": "《清异录》"}], "words": [{"w": "耍钱", "t": "指赌博中压的钱财。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1458wx','牵','1','qiān','牛','9','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从牛,“冖”象牵牛的绳,玄声。本义:牵牛)。"}, {"meaning": "同本义。引申为牵拉。", "cites": [{"t": "牵,引前也。", "b": "《说文》"}, {"t": "牵,引也。", "b": "《广雅》"}, {"t": "飱牵。", "b": "《周礼·宰夫》。司农注:“牲牢可牵而行者。”"}, {"t": "与其牵傍。", "b": "《周礼·牛人》。注:“牵傍,在辕外輓牛也。人御之,居其前曰牵,居其傍曰傍。”"}, {"t": "牵牛悔亡。", "b": "《易·夬》"}, {"t": "牵牛而过堂下者。", "b": "《孟子·梁惠王上》"}, {"t": "牵衣顿足拦道哭。", "b": "唐·杜甫《兵车行》"}, {"t": "回车叱牛牵向北。", "b": "白居易《卖炭翁》"}, {"t": "攀草牵棘。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "牵笼", "t": "拉扯"}, {"w": "牵红", "t": "牵巾。新郎新娘拜堂后,以两家红巾绾同心结,各牵一端而行"}, {"w": "牵扭", "t": "拉住"}, {"w": "牵役", "t": "谓被拉去从事劳役"}, {"w": "牵拖", "t": "拖拉。形容行动困难"}, {"w": "牵拉", "t": "牵引拉住。"}]}, {"meaning": "牵制。", "cites": [{"t": "令出不行谓之牵。", "b": "《管子·法法》"}, {"t": "牵于俗而芜秽。", "b": "《楚辞·招魂》"}, {"t": "此牵乎天者也。", "b": "张衡《西京赋》。注:“犹系也。”"}], "words": [{"w": "牵笼", "t": "牵制束缚"}, {"w": "牵肘", "t": "从旁牵制"}, {"w": "牵物", "t": "为外物所牵制"}, {"w": "牵挽", "t": "牵制"}, {"w": "牵缀", "t": "犹牵制。"}]}, {"meaning": "牵连;牵累。", "cites": [{"t": "道而弗牵则和。", "b": "《礼记·学记》。疏:“谓牵偪。”"}, {"t": "牵复吉。", "b": "《易·小畜》。疏:“谓牵连。”"}], "words": [{"w": "牵枝带梗", "t": "牵连;牵带"}, {"w": "牵惹", "t": "牵连"}, {"w": "牵及", "t": "牵连;关系到"}, {"w": "牵染", "t": "牵累,株连"}, {"w": "牵率", "t": "株连;拖累。"}]}, {"meaning": "拘泥。", "cites": [{"t": "不牵于执。", "b": "《吕氏春秋·离俗》。注:“拘也。”"}], "words": [{"w": "牵文", "t": "谓拘泥于字面"}, {"w": "牵拘", "t": "拘泥;拘束"}, {"w": "牵俗", "t": "拘泥于习俗。"}]}, {"meaning": "指可牵走的牲畜如牛羊猪等。", "cites": [{"t": "脯资饩牵竭。", "b": "《左传·僖公三十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1459wx','鸥','1','ōu','鸟','9','','[{"pinyin": "ōu", "defs": [{"meaning": "(形声。从鸟,区(ōu)声。《说文》:“水鸮也。”本义:水鸮)。"}, {"meaning": "水鸟名。", "cites": [{"t": "惊起一滩鸥鹭。", "b": "宋·李清照《如梦令》"}, {"t": "鸥鹭灭没。", "b": "宋·陆游《过小孤山大孤山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1460wx','残','1','cán','歹','9','','[{"pinyin": "cán", "defs": [{"meaning": "(形声。从歹(è),戋(jiān)声。从“歹”表示与死亡有关。本义:伤害)。"}, {"meaning": "同本义。", "cites": [{"t": "残,伤也。", "b": "《苍颉篇》"}, {"t": "昔智伯瑶残范中行。", "b": "《战国策·秦策》。注:“灭也。”"}, {"t": "废为残贼。", "b": "《诗·大雅·民劳》"}, {"t": "则汝残矣。", "b": "《战国策·齐策》。注:“坏也。”"}, {"t": "凡二十七县残。", "b": "《史记·樊郦滕灌传》。集解:“谓多所杀伤也。”"}, {"t": "张仪之残,樗里疾也。", "b": "《战国策·秦策》。注:“害也。”"}, {"t": "放轼其君则残之。", "b": "《周礼·夏官》"}, {"t": "残名以逞。", "b": "《左传·宣公二年》"}], "words": [{"w": "摧残", "t": "使蒙受严重损失"}, {"w": "残心", "t": "残害人的心"}, {"w": "残贼", "t": "杀害"}, {"w": "残灭", "t": "残杀毁灭"}, {"w": "残夷", "t": "残杀。"}]}, {"meaning": "毁坏;破坏。", "cites": [{"t": "家室立残,亲戚不免于刑戮。", "b": "《荀子·荣辱》"}], "words": [{"w": "残略", "t": "摧毁掠夺"}, {"w": "残坏", "t": "破败;毁坏。"}]}, {"meaning": "凋谢。", "cites": [{"t": "东风无力百花残。", "b": "李商隐《无题》"}], "words": [{"w": "残花;残芳;残英", "t": "凋零的花。即落花。"}]}, {"meaning": "凶恶;狠毒。", "cites": [{"t": "故不疑为吏,严而不残。", "b": "《汉书·隽不疑传》"}], "words": [{"w": "残烈", "t": "残酷剧烈"}, {"w": "残横", "t": "残暴专横。"}]}, {"meaning": "残缺,残废。", "cites": [{"t": "顾自以为身残处秽,动而见忧。", "b": "司马迁《报任安书》"}], "words": [{"w": "残而不废;残卷", "t": "书籍的残存部分;亦指书中未读完的部分"}, {"w": "残脱", "t": "残缺脱漏"}, {"w": "残替", "t": "残缺废弃"}, {"w": "残帙", "t": "残卷"}, {"w": "残梦", "t": "零乱不全的梦。"}]}, {"meaning": "剩余;残余,残存。", "cites": [{"t": "故纯朴不残,孰为牺尊?", "b": "《庄子·马蹄》"}, {"t": "今日之事,何不使我得早处囊中,以苟延残喘乎?", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "残香", "t": "余香"}, {"w": "残客", "t": "剩下未走的客人"}, {"w": "残雪", "t": "剩余而未融尽的雪"}, {"w": "残羹冷炙", "t": "剩下的酒食菜肴。"}]}, {"meaning": "也指凶暴的人,暴虐无道的人。", "cites": [{"t": "当横行天下,为汉家除残去秽。", "b": "《资治通鉴》"}, {"t": "是天下之大残也。", "b": "汉·贾谊《论积贮疏》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1461wx','殃','1','yāng','歹','9','','[{"pinyin": "yāng", "defs": [{"meaning": "(形声。从歺(è),央声。歺,剔肉后残剩的骨头。多与死亡、灾祸有关。本义:祸害,灾难) 同本义。", "cites": [{"t": "殃,咎也。", "b": "《说文》"}, {"t": "殃,败也。", "b": "《广雅》"}, {"t": "殃,禍也。", "b": "《释言》"}, {"t": "众以为殃。", "b": "《礼记·礼运》"}, {"t": "积善之家,必有余庆;积不善之家,必有余殃。", "b": "《易·坤》"}, {"t": "伍子逢殃兮。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "殃煞", "t": "骂人话。祸害;灾星祸祟"}, {"w": "殃榜", "t": "丧亡榜书"}, {"w": "殃人货", "t": "骂人话。给人带来灾祸的东西"}, {"w": "殃咎", "t": "灾祸"}, {"w": "殃毒", "t": "祸害"}, {"w": "殃祸", "t": "灾祸"}, {"w": "殃孽", "t": "奸邪"}, {"w": "遭殃;灾殃", "t": ""}]}, {"meaning": "使受祸害败坏;为害。", "cites": [{"t": "不教民而用之,谓之殃民。", "b": "《孟子·告子下》"}, {"t": "吾主以不贿闻于诸侯,今以梗阳之贿殃之,不可。", "b": "《国语》"}], "words": [{"w": "殃流妻女", "t": "灾祸波及妻子女儿身上"}, {"w": "殃及", "t": "连累;请求"}, {"w": "殃及池鱼", "t": "比喻无端受祸"}, {"w": "殃民", "t": "使百姓受祸害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1462wx','轴','1','zhóu zhòu','车','9','','[{"pinyin": "zhóu", "defs": [{"meaning": "(形声。从车,由声。本义:轮轴)。"}, {"meaning": "同本义。", "cites": [{"t": "轴,持轮也。", "b": "《说文》"}, {"t": "輑谓之轴。", "b": "《方言九》"}, {"t": "服重任,行远道,正直而固者,轴也。", "b": "《列女传·母仪》"}, {"t": "迁于袒,用轴。", "b": "《仪礼·既夕礼》。注:“輁轴也。状如转辚,刻两头为轵。”"}, {"t": "天寒日短银灯续, 欲往从之车脱轴。 ", "b": "宋·苏轼《次韵王巩独眠》"}], "words": [{"w": "车轴;主轴;轴心", "t": "轮轴。"}]}, {"meaning": "织具。引申为一切机枢之称。", "cites": [{"t": "小东大东,杼柚其空。", "b": "《诗·小雅·大东》"}], "words": [{"w": "轴杼", "t": "轴和杼,纺织机上的两个部件。"}]}, {"meaning": "中心,枢纽。", "cites": [{"t": "柂以漕渠,轴以昆仑。", "b": "鲍照《芜城赋》"}], "words": [{"w": "轴辖", "t": "关键。"}]}, {"meaning": "指重要位置。", "cites": [{"t": "当轴处中,括囊不言,容身而去。", "b": "《汉书》"}]}, {"meaning": "指装成卷轴形的书、画。", "cites": [{"t": "所著书有未毕者,多芸与续之成轴也。", "b": "《唐国史补》"}]}, {"meaning": "某些可以旋转之物。", "cites": [{"t": "转轴拨弦。", "b": "唐·白居易《琵琶行(并序)》"}]}]}, {"pinyin": "zhòu", "defs": [{"meaning": "压轴子。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1463wx','轻','1','qīng','车','9','','[{"pinyin": "qīng", "defs": [{"meaning": "(形声。本义:车名)。"}, {"meaning": "轻车。", "cites": [{"t": "轻,轻车也。", "b": "《说文》。段玉裁注:“轻本车名,故字从车。引申为凡轻重之轻。”"}, {"t": "轻车之萃。谓驰敌致师之车也。", "b": "《周礼·车仆》"}, {"t": "使轻车锐骑冲雍门。", "b": "《战国策·齐策》"}]}, {"meaning": "化学元素氢的旧译。"}, {"meaning": "分量不大。与“重”相对。", "cites": [{"t": "轻重同。", "b": "《孟子》。注:“谓斤两。”"}, {"t": "权然后知轻重,度然后知长短。", "b": "《孟子》"}, {"t": "渭城朝雨浥轻尘。", "b": "唐·王维《送元二使安西》"}], "words": [{"w": "轻单", "t": "单薄"}, {"w": "轻省", "t": "负担轻,不费力"}, {"w": "轻肥", "t": "穿轻裘,乘肥马。比喻显贵的人或豪奢的生活"}, {"w": "轻狐", "t": "轻暖的狐裘。"}]}, {"meaning": "微小。", "cites": [{"t": "有轻罪者,赎以金分。", "b": "《淮南子·泛论》"}, {"t": "无势之谓轻。", "b": "《韩非子·解老》"}, {"t": "轻者无罪者。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "轻小", "t": "细小"}, {"w": "轻文", "t": "微小的水波"}, {"w": "轻汗", "t": "些微的汗"}, {"w": "轻雨", "t": "小雨。"}]}, {"meaning": "轻快,轻便。", "cites": [{"t": "师轻而骄。", "b": "《国语·周语》。注:“谓超乘也。”"}, {"t": "轻锐僄狡。", "b": "张衡《西京赋》。注:“谓便利。”"}, {"t": "舟遥遥以轻飔。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "两岸猿声啼不住,轻舟已过万重山。", "b": "唐·李白《早发白帝城》"}, {"t": "轻捷善斗。", "b": "《聊斋志异·促织》"}], "words": [{"w": "轻敲", "t": "轻便。敲:作“巧”"}, {"w": "轻甲", "t": "较为轻便的盔甲战衣"}, {"w": "轻帆", "t": "即轻舟"}, {"w": "轻车", "t": "轻便的车子"}, {"w": "轻劲", "t": "轻快有力"}, {"w": "轻弓", "t": "轻便的弓"}, {"w": "轻舫", "t": "轻航。犹轻舟"}, {"w": "轻航", "t": "轻快的船。"}]}, {"meaning": "轻率,不稳重。", "cites": [{"t": "秦师轻而无礼,必败。", "b": "《左传》"}, {"t": "轻辞古之天子。", "b": "《韩非子·五蠹》"}, {"t": "轻辞天子。", "b": ""}, {"t": "敢以轻心。", "b": "唐·柳宗元《柳河东集》"}, {"t": "不中而轻发。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "轻造", "t": "冒然造访"}, {"w": "轻快", "t": "轻率;不慎重"}, {"w": "轻乔", "t": "轻浮"}, {"w": "轻躁", "t": "轻率急躁"}, {"w": "轻行", "t": "举止轻浮不庄重"}, {"w": "轻侠", "t": "轻举妄动的人。"}]}, {"meaning": "宽松。", "cites": [{"t": "古之君子,其责己也重以周,其待人也轻以约。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "轻吉列", "t": "轻急力。轻轻的,轻易的"}, {"w": "轻省", "t": "舒服。"}]}, {"meaning": "不贵重;贱。", "cites": [{"t": "钱益多而轻。", "b": "《汉书·食货志》。注:“贱也。”"}, {"t": "辨轻重。", "b": "《荀子·富国》。注:“谓尊卑。”"}], "words": [{"w": "轻鲜", "t": "微薄的情意"}, {"w": "轻微", "t": "菲薄"}, {"w": "轻鄙", "t": "微贱。"}]}, {"meaning": "轻佻。", "words": [{"w": "轻狂百势", "t": "轻佻狂放,不拘形骸"}, {"w": "轻薄子", "t": "轻佻浮浪的人"}, {"w": "轻隽", "t": "轻佻俊逸"}, {"w": "轻薄脂粉", "t": "轻浮放荡的女子"}, {"w": "轻轻试试", "t": "妖艳的样子。"}]}, {"meaning": "轻轻地。", "cites": [{"t": "轻拢慢捻抹复挑。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "轻视;不重视。", "cites": [{"t": "轻寡人与。", "b": "《战国策·魏策》"}, {"t": "公子纵轻胜。", "b": "《史记·魏公子列传》"}, {"t": "敢轻吾射。", "b": "宋·欧阳修《归田录》"}, {"t": "轻之而屑间焉。", "b": "清·刘开《问说》"}, {"t": "宣父犹能畏后生,丈夫未可年轻少。", "b": "唐·李白《上李邕》"}], "words": [{"w": "轻人轻己", "t": "轻视别人就是轻视自己"}, {"w": "轻觑", "t": "轻视;鄙薄"}, {"w": "轻意", "t": "轻慢;简慢"}, {"w": "轻量", "t": "轻视"}, {"w": "轻亵", "t": "轻慢;不敬"}, {"w": "轻倨", "t": "傲慢无礼"}, {"w": "轻易", "t": "轻视;不尊重"}, {"w": "轻渎", "t": "轻慢冒犯"}, {"w": "轻利", "t": "轻视名利。"}]}, {"meaning": "使轻;减少。", "cites": [{"t": "而不明世俗之变,不察治民之情,故多赏以致刑,轻刑以去赏。", "b": "《商君书》"}, {"t": "今欲广开田业,轻其赋税。", "b": "《三国志》"}], "words": [{"w": "轻薄", "t": "减轻;减免"}, {"w": "轻约", "t": "减少,减省"}, {"w": "轻弱", "t": "削弱"}, {"w": "轻权", "t": "谓权力削弱。"}]}, {"meaning": "宽大;宽容。", "cites": [{"t": "古之君子…其待人也轻以约。", "b": "唐·韩愈《原毁》"}, {"t": "轻以约乎。", "b": ""}], "words": [{"w": "轻贷", "t": "轻饶;从轻发落"}, {"w": "轻过", "t": "轻恕其罪过"}, {"w": "轻假", "t": "宽容。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1464wx','鸦','1','yā','鸟','9','','[{"pinyin": "yā", "defs": [{"meaning": "鸟名。各种大型的、通常是亮黑色的鸦属(Corvus)成员。", "cites": [{"t": "鸱鸦耆鼠。", "b": "《庄子·齐物论》"}], "words": [{"w": "鸦鹊无声", "t": "鸦雀无声"}, {"w": "鸦巢生凤", "t": "比喻平庸的家庭,出了优秀的子弟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1465wx','皆','1','jiē','白','9','','[{"pinyin": "jiē", "defs": [{"meaning": "(会意。从比,从白。从“比”,有“并”的意思。本义:都,全)。"}, {"meaning": "同本义。", "cites": [{"t": "皆,俱词也。", "b": "《说文》"}, {"t": "百堵皆兴。", "b": ""}, {"t": "皆死皆殡。", "b": "《左传·哀公十一年》"}, {"t": "予及汝皆亡。", "b": "《书·汤誓》"}, {"t": "燕、赵、韩、魏闻之,皆朝于齐。", "b": "《战国策·齐策》"}, {"t": "小人有母,皆尝小人之食。", "b": "《左传·隐公元年》"}, {"t": "皆以美于徐公。", "b": "《战国策·齐策》"}, {"t": "皆自于人欤。", "b": "宋·欧阳修《新五代史·伶官传》"}, {"t": "所在皆是。", "b": "宋·苏轼《石钟山记》"}, {"t": "皆托忠烈之名。", "b": "清·全祖望《梅花岭记》"}, {"t": "环村居者皆猎户。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "吾村十里皆平原", "b": ""}], "words": [{"w": "皆悉", "t": "尽;全都"}, {"w": "皆既", "t": "日月亏蚀全尽"}, {"w": "这件事情人人皆知", "t": ""}]}, {"meaning": ";一同。", "cites": [{"t": "皆行至于阶让。", "b": "《仪礼·聘礼》。注:“犹并也。”"}, {"t": "皆陈殿下。", "b": "《战国策·燕策》"}, {"t": "左右皆流涕。", "b": "唐·李朝威《柳毅传》"}, {"t": "宫中皆恸哭。", "b": ""}, {"t": "一时皆下。", "b": ""}, {"t": "廷中皆大笑。", "b": "唐·柳宗元《柳河东集》"}, {"t": "予及女皆亡。", "b": "《书·汤誓》"}, {"t": "亡国之主不自以为惑。故与桀、纣、幽、厉皆也。", "b": "《吕氏春秋·离谓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1466wx','韭','1','jiǔ','韭','9','','[{"pinyin": "jiǔ", "defs": [{"meaning": "(象形。小篆,象韭菜长在地上的形状。本义:韭菜)。"}, {"meaning": "同本义。", "cites": [{"t": "韭,菜名,一种而久者,故谓之韭。", "b": "《说文》"}, {"t": "囿有见韭。", "b": "《夏小正·正月》"}, {"t": "丹熏之山,其草多韭。", "b": "《山海经·北山经》"}, {"t": "韭曰丰本。", "b": "《礼记·曲礼》"}, {"t": "四之日其蚤,献羔祭韭。", "b": "《诗·豳风·七月》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1467wx','背','1','bēi bèi','月','9','','[{"pinyin": "bēi", "defs": [{"meaning": "人用脊背驮。", "cites": [{"t": "早背胡霜过戍楼,又随寒日下汀州。", "b": "罗邺《雁》"}], "words": [{"w": "背粮食;背头", "t": "男子头发由鬓角起都向后梳的发式"}, {"w": "背锅", "t": "方言。驼背。"}]}]}, {"pinyin": "bèi", "defs": [{"meaning": "(形声。从肉,北声。本义:脊背)。"}, {"meaning": "同本义。", "cites": [{"t": "背,脊也。", "b": "《说文》"}, {"t": "背者,胸中之府。", "b": "《素问·脉要精微论》"}, {"t": "牛足出背上。", "b": "《史记·梁孝王世家》"}, {"t": "然徒步则汗出浃背。", "b": "明·袁宏道《满井游记》"}, {"t": "左手抚鲁直背。", "b": "明·魏学洢《核舟记》"}, {"t": "不呼则杖其背。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "芒刺在背;背袋", "t": "背在背上的口袋"}, {"w": "背花", "t": "旧时刑罚,即用木棒打背脊,伤破处称背花"}, {"w": "背子", "t": "半袖上衣。"}]}, {"meaning": "事物的后面或反面。", "cites": [{"t": "其船背稍夷。", "b": "明·魏学洢《核舟记》"}, {"t": "即以斧破其背,得剑。", "b": "晋·干宝《搜神记》"}]}, {"meaning": "又。", "cites": [{"t": "剑在其背", "b": ""}], "words": [{"w": "乘在浪背上前进;刀背;锯背;斧背", "t": ""}]}, {"meaning": "正北堂屋。", "cites": [{"t": "焉得谖草(萱草),言树(种)之背。", "b": "《诗·卫风·伯兮》"}]}, {"meaning": "背部对着或后部靠着。", "cites": [{"t": "背山而面野。", "b": "〔英〕赫胥黎著·严复译《天演论》"}, {"t": "以缚背刃。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "背山起楼;背水战;背依", "t": "背靠屏风"}, {"w": "背城", "t": "背靠自己的城墙"}, {"w": "背流", "t": "背源而流。"}]}, {"meaning": "转过身;背过。", "cites": [{"t": "背而走,比至其家,失气而死。", "b": "《荀子·解蔽》"}], "words": [{"w": "背画", "t": "向后指画。"}]}, {"meaning": "反叛;背弃;违背。", "cites": [{"t": "言沛公不敢背项王也。", "b": "《史记·项羽本记》"}, {"t": "不顾恩义,畔主背亲。", "b": "《汉书·李广苏建传》"}, {"t": "皆背晋以归梁。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "背反", "t": "背离叛变"}, {"w": "背国", "t": "背叛国家"}, {"w": "背本", "t": "背弃根本。"}]}, {"meaning": "离开。", "cites": [{"t": "生孩六月,慈父见背。(见背:离开了我,指死去。)", "b": "李密《陈情表》"}, {"t": "背井离乡,卧雪眠霜。", "b": "马致远《汉宫秋》"}]}, {"meaning": "避开,不让别人知道。", "cites": [{"t": "好面誉人者,亦好背而毁之。", "b": "《庄子·盗跖》"}], "words": [{"w": "我没有什么背人的事;背人", "t": "避开别人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1468wx','战','1','zhàn','戈','9','','[{"pinyin": "zhàn", "defs": [{"meaning": "(形声。从戈,单(占)声。本义:作战,打仗)。"}, {"meaning": "同本义。", "cites": [{"t": "战,斗也。", "b": "《说文》"}, {"t": "皆陈曰战。", "b": "《左传·庄公十一年》"}, {"t": "春秋敌者言战。", "b": "《公羊传·庄公三十年》"}, {"t": "忠之属也,可以一战。战则请从。", "b": "《左传·庄公十年》"}, {"t": "将军百战死。", "b": "《乐府诗集·木兰诗》"}, {"t": "脱我战时袍。", "b": ""}, {"t": "挟矢以助战。", "b": "明·魏禧《大铁椎传》"}, {"t": "技击利巷战。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "普法交战图。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "时北兵已迫修门外,战、守、迁皆不及施。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "征战", "t": "出征作战"}, {"w": "战阀", "t": "战功"}, {"w": "战垒", "t": "战争中用以防守的堡垒。"}]}, {"meaning": "泛指搏斗,争斗,争胜负,比高低。", "cites": [{"t": "龙战于野。", "b": "《易·坤》"}, {"t": "下骑搏战。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "文战;酒战;西瓜战", "t": ""}]}, {"meaning": "后作“颤”。发抖。", "cites": [{"t": "战栗,惧也。", "b": "《尔雅·释诂》"}, {"t": "股战而栗。", "b": "《汉书·高五王传》"}, {"t": "使民战栗。", "b": "《论语·八佾》"}, {"t": "战战兢兢,如临深渊,如履薄冰。", "b": "《诗·小雅·小旻》"}, {"t": "闻鸣镝而股战。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "战欣欣", "t": "战兢兢"}, {"w": "战钦钦", "t": "战兢兢"}, {"w": "战笃索", "t": "战抖"}, {"w": "战笃速", "t": "战抖"}, {"w": "战都速", "t": "战抖"}, {"w": "战恐", "t": "恐惧发抖"}, {"w": "战动", "t": "颤动;抖动"}, {"w": "战悸", "t": "惶恐发抖。"}]}, {"meaning": "战争;战事。", "cites": [{"t": "王师非乐战,之子慎佳兵。", "b": "陈子昂《送别崔著作东征》"}, {"t": "普法之战。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "战史", "t": "记载战争情况的史书或文章"}, {"w": "战多", "t": "战功"}, {"w": "战征", "t": "征战;战争"}, {"w": "战讯", "t": "战事的消息"}, {"w": "战道", "t": "战争的规律或法则。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1469wx','点','1','diǎn dian','灬','9','','[{"pinyin": "diǎn", "defs": [{"meaning": "(形声。从黑,占声。本义:斑点)。"}, {"meaning": "细小的黑色斑痕。", "cites": [{"t": "点,黑也。", "b": "《说文》。按,小黑曰点。"}], "words": [{"w": "墨点儿;斑点;污点;点缺", "t": "瑕疵,缺点"}, {"w": "点漆", "t": "形容极黑。"}]}, {"meaning": "小滴。", "cites": [{"t": "七八个星天外,两三点雨山前。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "雨点;掉点儿", "t": "落下稀疏的雨点"}, {"w": "点叶", "t": "叶上的斑点"}, {"w": "点璧", "t": "白璧的斑点。"}]}, {"meaning": "汉字笔画名 。如:横、竖、撇、点、折。又指旧时读书标明句逗及品评文章所用“、”号及其动作。如:点撇(文字的点和撇)。"}, {"meaning": "数学名词。数学上表示小数的符号叫小数点,省称为“点”。"}, {"meaning": "古时夜间的计时单位。一夜分五更,一更又分五点。", "cites": [{"t": "五更三点索金车,尽放宫人出看花。", "b": "唐·王建《宫词一百首》"}]}, {"meaning": "一种特制响器,两端作云状,名为云板,也称点。旧时官署、邸宅以打点为报事集众的信号。", "cites": [{"t": "雨村尚未看完,忽闻传点。", "b": "《红楼梦》"}]}, {"meaning": "规定的时间  如:船误点;火车准点到达。"}, {"meaning": "引申为玷污。", "cites": [{"t": "适足以发笑而自点耳。", "b": "《汉书·司马迁传》"}, {"t": "唐虞点灼而毁议。", "b": "《楚辞·怨世》"}], "words": [{"w": "点污", "t": "玷污,特指奸污"}, {"w": "点染", "t": "玷污。"}]}, {"meaning": "用笔加点。多用以描绘物象,审识章句,或表示删除的意思。", "cites": [{"t": "灭谓之点。", "b": "《尔雅·释器》。注:“以笔灭字为点。”"}], "words": [{"w": "点化", "t": "用笔描绘景物;把前人诗句加以改头换面"}, {"w": "点定", "t": "改正文字或句读"}, {"w": "点窜", "t": "改动字句"}, {"w": "点书", "t": "圈点书籍"}, {"w": "点额", "t": "化妆;梳妆。"}]}, {"meaning": "指定,选派。", "cites": [{"t": "可汗大点兵。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "点行", "t": "按照名册顺序抽丁入伍"}, {"w": "点差", "t": "点派差遣"}, {"w": "点菜;点将", "t": ""}]}, {"meaning": "评论。", "cites": [{"t": "指点江山,激扬文字,粪土当年万户侯。", "b": "毛泽东《沁园春·长沙》"}], "words": [{"w": "点文", "t": "评点文章"}, {"w": "点抹", "t": "评点。"}]}, {"meaning": "短暂接触。", "cites": [{"t": "猴首之足,亦仅点半趾,跃陟甚难。", "b": "《徐霞客游记》"}]}, {"meaning": "表示少量。点儿化。", "cites": [{"t": "孤光一点萤。", "b": "清·查慎行《舟夜书所见》"}], "words": [{"w": "多做一点儿工作;上点儿水", "t": ""}]}]}, {"pinyin": "dian", "defs": [{"meaning": "收拾;贿赂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1470wx','虐','1','nüè','虍','9','','[{"pinyin": "nüè", "defs": [{"meaning": "(会意。小篆字形。从虍(hǔ指虎头),爪人。即虎足反爪伤人。隶变后省略“人”字。本义:凶恶,残暴)。"}, {"meaning": "同本义。", "cites": [{"t": "虐,残也。", "b": "《说文》"}, {"t": "厉王虐,国人谤王。", "b": "《国语·周语上》"}, {"t": "民之憔悴于虐政,未有甚于此时者也。", "b": "《孟子·公孙丑上》"}, {"t": "加以官贪吏虐,民日贴妇卖儿,更无休止。", "b": "《聊斋志异·促织》"}], "words": [{"w": "虐世", "t": "残暴的时代"}, {"w": "虐人", "t": "残暴凶狠的人"}, {"w": "虐暴", "t": "暴虐,残暴酷虐"}, {"w": "虐焰", "t": "残暴的气焰"}, {"w": "虐行", "t": "残暴的行为"}, {"w": "虐刻", "t": "残暴苛刻"}, {"w": "虐烈", "t": "残暴酷烈"}, {"w": "虐遇", "t": "虐待。"}]}, {"meaning": "暴烈;险恶。", "cites": [{"t": "遘厉虐疾。", "b": "《书·金縢》。传:“暴也。”"}, {"t": "到州日亭午,余暑秋更虐。", "b": "陈基《通州》"}], "words": [{"w": "虐疾", "t": "重病;恶疾"}, {"w": "虐暑", "t": "酷暑;酷热。"}]}, {"meaning": "无节制;纵情。", "cites": [{"t": "善戏谑兮,不为虐。", "b": "《诗·卫风》。朱熹集传:“善戏谑不为虐者,言其乐易而有节也。”"}]}, {"meaning": "侵害;残害。", "cites": [{"t": "方命虐民,饮食若流。", "b": "孟子·梁惠王下》"}, {"t": "奸官污吏虐民。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "虐人", "t": "残害人民"}, {"w": "虐戕", "t": "残害"}, {"w": "虐害", "t": "残害,残酷迫害"}, {"w": "虐割", "t": "残害。"}]}, {"meaning": "轻视;忽视。", "cites": [{"t": "而又荣古虐今者,比肩叠迹,大抵生则不遇,死而垂声者众焉。", "b": "唐·柳宗元《与友人论为文书》"}]}, {"meaning": "灾害。", "cites": [{"t": "殷降大虐。", "b": "《书·盘庚中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1471wx','临','1','lín lìn','丨','9','','[{"pinyin": "lín", "defs": [{"meaning": "(会意。金文字形,右边是人,左上角象人的眼睛,左下角象众多的器物。整个字形象人俯视器物的样子。本义:从高处往低处察看)。"}, {"meaning": "同本义。", "cites": [{"t": "临,监临也。从卧,品声。", "b": "《说文》。按,隐几视下之称。》"}, {"t": "临,视也。", "b": "《尔雅》"}, {"t": "不临深谿,不知地之厚也。", "b": "《荀子·劝学》"}, {"t": "上帝临女。", "b": "《诗·大雅·大明》"}, {"t": "有亭翼然临于泉上。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "居高临下;如临深渊;临轩", "t": "在殿前平台上接见臣属"}, {"w": "临下", "t": "从高望下"}, {"w": "临见", "t": "居上视下看见。"}]}, {"meaning": "引申为从上监视着。", "cites": [{"t": "临长晋国者。", "b": "《国语·晋语》。注:“监也。”"}, {"t": "今陛下君临四方。", "b": "《宋史·赵普传》"}], "words": [{"w": "临引", "t": "居上察下。今称监察"}, {"w": "临制", "t": "监临控制;指皇后临朝称制"}, {"w": "临政", "t": "亲理政务。"}]}, {"meaning": "面对(上对下,尊对卑)。", "cites": [{"t": "临众发政而治民。", "b": "《墨子·尚贤下》"}, {"t": "把酒临风。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "临表涕零。", "b": "诸葛亮《出师表》"}, {"t": "执策而临之。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "临川", "t": "面对川流"}, {"w": "临穴(面对自己的圹穴亦指面对(别人的)墓穴", "t": ""}, {"w": "临敌", "t": "面对敌人。"}]}, {"meaning": "碰上, 逢着。", "cites": [{"t": "临财无苟得,临难毋苟免。", "b": "《礼记·曲礼上》"}], "words": [{"w": "临头", "t": "落到头上;当头"}, {"w": "临风", "t": "迎风;当风"}, {"w": "临谷", "t": "身临深谷。喻危险恐惧。"}]}, {"meaning": "到,至。后常用作敬辞。", "cites": [{"t": "临其穴。", "b": "《诗·秦风·黄鸟》"}, {"t": "东临碣石(山名),以观沧海。", "b": "曹操《步出夏门行》"}, {"t": "自往临视。", "b": "晋·干宝《搜神记》"}]}, {"meaning": "又。", "cites": [{"t": "王即临之。", "b": ""}, {"t": "临溪而渔。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "光临;莅临;临按", "t": "亲临按问"}, {"w": "临送", "t": "谓亲临送别"}, {"w": "临讯", "t": "谓亲临审讯。"}]}, {"meaning": "攻伐;胁制。", "cites": [{"t": "君临函谷。", "b": "《战国策·西周策》。注:“犹守也。以临韩魏。”注:犹伐也。”"}], "words": [{"w": "临军对阵", "t": "指战场上对峙交锋。"}]}, {"meaning": "照着他人的字画书写或绘画。", "cites": [{"t": "临书爱真迹。", "b": "姚合《秋夕遣怀》"}, {"t": "中国画家自临摹旧作入手。", "b": "蔡元培《图画》"}], "words": [{"w": "临池", "t": "研习书法"}, {"w": "临本", "t": "临摹原作的写本"}, {"w": "临帖", "t": "照着字帖临摹。"}]}, {"meaning": "治理、管理、统治 。", "cites": [{"t": "少欲,则能临其众。", "b": "《韩非子·十过》"}, {"t": "上帝临女。(治理你们。)", "b": "《诗·鲁颂·閟宫》"}, {"t": "居敬而行简,以临其民,不亦可否?", "b": "《论语·雍也》"}], "words": [{"w": "临人", "t": "治理百姓"}, {"w": "临御", "t": "临视统御。指帝王治理天下而言。"}]}, {"meaning": "靠近,逼近(多用于上对下,强对弱)。", "cites": [{"t": "以临二周之郊,诛周主之罪。", "b": "《战国策·秦策一》"}, {"t": "临崩寄臣以大事。", "b": "诸葛亮《出师表》"}], "words": [{"w": "临没", "t": "将沉没时"}, {"w": "临觞", "t": "将要喝酒的时候"}, {"w": "临颖", "t": "临笔。指写信的时候。"}]}, {"meaning": "在…之前,在即将…的时候。", "cites": [{"t": "临别赠言,幸承恩于伟饯。", "b": "王勃《滕王阁序》"}], "words": [{"w": "临歧", "t": "临别时;分别"}, {"w": "临文", "t": "指正在写文章的时候"}, {"w": "临别;临行;临睡", "t": ""}]}]}, {"pinyin": "lìn", "defs": [{"meaning": "哭(很多人哭,或聚众哭,为丧事而悲痛哭泣)。", "cites": [{"t": "临,哭也。", "b": "《集韵》"}, {"t": "国人大临,守陴者皆哭。", "b": "《左传·宣公十二年》"}, {"t": "遂为义帝发丧,临三日。", "b": "《史记·高祖本纪》"}, {"t": "遗昭曰,无发民哭临宫殿中", "b": "《汉书·文帝纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1472wx','览','1','lǎn','见','9','','[{"pinyin": "lǎn", "defs": [{"meaning": "(会意。从见,从监。“监”亦兼表字音。“监”的本义是借水照形,这里表示看。本义:观看)。"}, {"meaning": "同本义。", "cites": [{"t": "览,观也。", "b": "《说文》"}, {"t": "而数览。", "b": "《战国策·齐策》"}, {"t": "皇览揆余于初度兮。", "b": "《离骚》"}, {"t": "又览累累之昌辞。", "b": "《汉书·扬雄传》"}, {"t": "洞庭君览毕。", "b": "唐·李朝威《柳毅传》"}, {"t": "故有所鉴辄省记。", "b": "袁枚《黄生借书说》"}], "words": [{"w": "览观", "t": "阅览"}, {"w": "览读", "t": "阅读"}, {"w": "览阅", "t": "阅览"}, {"w": "览核", "t": "查阅"}, {"w": "览究", "t": "阅读研究。"}]}, {"meaning": "观赏。", "cites": [{"t": "会当凌绝顶,一览众山小。", "b": "杜甫《望岳》"}, {"t": "览物之情,得无异乎?", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "览历", "t": "游览"}, {"w": "览瞩", "t": "极目远望"}, {"w": "览胜;览古", "t": ""}]}, {"meaning": "观察;考察。", "cites": [{"t": "皇览揆予初度兮,肇锡予以嘉名。", "b": "《楚辞·离骚》"}, {"t": "览天下诸侯宾客,言齐能救天下贤士也。", "b": "《史记·孟子荀卿列传》"}], "words": [{"w": "览省", "t": "视察"}, {"w": "览揆", "t": "览观,揆度。后用以称生长"}, {"w": "览观", "t": "观察"}, {"w": "览镜", "t": "照镜"}, {"w": "览察", "t": "审察"}, {"w": "览试", "t": "审察考试。"}]}, {"meaning": "采纳。", "cites": [{"t": "大王览其说,而不察其至实。", "b": "《战国策》"}]}, {"meaning": "采取;采摘。", "cites": [{"t": "欲上青天览明月。", "b": "李白《宣州谢朓楼饯别校书叔云》"}], "words": [{"w": "览取", "t": "揽取。"}]}, {"meaning": "景致。", "cites": [{"t": "因念黄山当生平奇览。", "b": "《徐霞客游记》"}], "words": [{"w": "奇览", "t": "奇妙的景色。"}]}, {"meaning": "唐代州名,在今云南省楚雄县。", "cites": [{"t": "览州,贞观二十三年置。", "b": "《新唐书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1473wx','竖','1','shù','立','9','','[{"pinyin": "shù", "defs": [{"meaning": "纵。与“横”相反。", "cites": [{"t": "緅色斜临,霞文横竖。", "b": "南朝·梁简文帝《明月山铭》"}], "words": [{"w": "竖井", "t": ""}]}, {"meaning": "童仆。", "cites": [{"t": "杨子之邻人亡羊,既率其党,又请杨子之竖追之。", "b": "《列子·说符》"}], "words": [{"w": "竖人", "t": "童仆。"}]}, {"meaning": "宫中供役使的小臣。", "cites": [{"t": "晋侯之竖头须。", "b": "《左传·僖公二十四年》"}], "words": [{"w": "竖臣", "t": "小臣"}, {"w": "竖宦", "t": "宦官。"}]}, {"meaning": "书法的直笔画,从上一直向下。", "cites": [{"t": "努者,中心竖画也。", "b": "张绅《法书通释》"}], "words": [{"w": "王字是三横一竖", "t": ""}]}, {"meaning": "古时对人的蔑称、贱称。", "cites": [{"t": "骂曰:“竖儒,几败而公事!”", "b": "《史记·留侯世家》"}], "words": [{"w": "竖夫", "t": "低贱的人"}, {"w": "竖儒", "t": "对知识分子的鄙称;没见识的儒生"}, {"w": "竖褐", "t": "古代童仆或穷人所穿的粗布短衣。"}]}, {"meaning": "对宦官的蔑称。", "cites": [{"t": "阉竖恐终为其患。", "b": "范晔《后汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1474wx','省','1','shěng xǐng','目','9','','[{"pinyin": "shěng", "defs": [{"meaning": "(会意。从眉省,从屮(chè)。甲骨文和小篆字形,象眼睛观察草。(xǐng)本义:察看)。"}, {"meaning": "王宫禁署,禁中。", "cites": [{"t": "禁台省中,连闼对门。", "b": "左思《魏都赋》"}], "words": [{"w": "省中", "t": "宫禁之中"}, {"w": "省内", "t": "宫禁之内。"}]}, {"meaning": "官署名称。", "cites": [{"t": "投词院直至省,将冤屈叫几声,诉出咱这实情。", "b": "《陈州粜米》"}]}, {"meaning": "行政区域名 。元代中央置中书省,于各路设行中书省,称为行省。明代改行省为布政使司,自后即以省为地方行政区域的通称。", "cites": [{"t": "宋,怀庆青华镇人,工技击,七省好事者皆来学。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "省元", "t": "礼部考试中的第一名进士。因礼部属尚书省,故称。"}]}, {"meaning": "灾祸;过失。", "cites": [{"t": "大省者何?灾省也。", "b": "《公羊传·庄公二十二年》"}, {"t": "王省惟岁,卿士惟月,师尹惟日。", "b": "《书·洪范》"}, {"t": "乃惟省哉。", "b": "《潜夫论·述赦》。王继培云:“省哉,今作眚灾。”"}]}, {"meaning": "减少;精简。", "cites": [{"t": "拜至献酬辞让之节繁,及介省矣。", "b": "《礼记·乡饮酒义》。注;“小减曰省。”"}, {"t": "省囹圄。", "b": "《礼记·月令·仲春》。注:“省,减也。”"}, {"t": "省攻伐之心。", "b": "《战国策·秦策四》。注:“省,减也。”"}, {"t": "省商贾之数。", "b": "《荀子·富国》"}, {"t": "由父省也。", "b": "《史记·吴王濞传》"}, {"t": "故圣王之诛也綦省矣。", "b": "《荀子·仲尼》"}, {"t": "省徭役,减征赋。", "b": "《三国志·吴主传》"}], "words": [{"w": "省刑", "t": "减少或减轻刑罚"}, {"w": "省笔", "t": "减少字的笔画。"}]}, {"meaning": "节约。", "cites": [{"t": "今为计莫若先省国用。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "省时间;能省的就省;省工;省口", "t": "不说话"}, {"w": "省陌(亦作“省钱”把不足一百的钱钞当作一百叫作“省陌”)省衣节食(犹言节衣缩食指生活节俭)", "t": ""}]}, {"meaning": "免除;非除。", "cites": [{"t": "哥哥可省烦恼。", "b": "《水浒全传》"}], "words": [{"w": "这个字不能省;省却", "t": "免去;除掉"}, {"w": "省罢", "t": "裁减;罢免"}, {"w": "省可", "t": "省可里。省得,免得,休要"}, {"w": "省释", "t": "免罪释放。"}]}]}, {"pinyin": "xǐng", "defs": [{"meaning": "同本义。", "cites": [{"t": "省,视也。", "b": "《说文》"}, {"t": "省,察也。", "b": "《尔雅》"}, {"t": "省其文采。", "b": "《礼记·乐记》。注:“审也。”"}, {"t": "退而省其私。", "b": "《论语》。皇疏:“视也。”"}, {"t": "省农功。", "b": "《荀子·王制》。注:“观也。”"}, {"t": "王省惟岁。", "b": "《书·洪范》"}, {"t": "先王以省方观民设教。", "b": "《易·观》"}], "words": [{"w": "省方", "t": "视察四方"}, {"w": "省耕", "t": "古代帝王巡视春耕。"}]}, {"meaning": "检查。", "cites": [{"t": "吾日三省吾身。", "b": "《论语·学而》"}, {"t": "日省月试。", "b": "《礼记·中庸》。注:“考校其成功也。”"}], "words": [{"w": "省心改过", "t": "反省内心,改正错误"}, {"w": "内省;省牲之所", "t": "屠宰、烹饪牛羊等祭品的地方。祭祀前主祭和助祭人要省查祭品,以示虔诚,叫省牲"}, {"w": "反省", "t": ""}]}, {"meaning": "探望,问候(多指对尊长)。", "cites": [{"t": "昏定而晨省。", "b": "《礼记·曲礼》。注:“问其安否何如。”"}, {"t": "陈子灿省兄河南。", "b": "明·魏禧《大铁椎传》"}, {"t": "次日起来,省过贾母,因往王夫人处来。", "b": "《红楼梦》"}], "words": [{"w": "省拜", "t": "谒见。叩拜父母长辈等"}, {"w": "省宫闱", "t": "应召入宫探视"}, {"w": "省候", "t": "探望问候"}, {"w": "省晨", "t": "早晨问候"}, {"w": "省问;省墓", "t": "扫墓。"}]}, {"meaning": "明白。", "cites": [{"t": "我方才这般与你说了,你还不省?", "b": "《西游记》"}], "words": [{"w": "省会", "t": "喻示;晓喻"}, {"w": "省着", "t": "知道;晓得"}, {"w": "省谕", "t": "通知;告知"}, {"w": "省得", "t": "懂得"}, {"w": "省不的", "t": "不明白;不懂。"}]}, {"meaning": "醒悟。", "cites": [{"t": "虽然是眼角儿传情,咱两个口不言心自省。", "b": "《西厢记》"}], "words": [{"w": "不省人事;省得", "t": "醒悟"}, {"w": "省释", "t": "劝化并释放"}, {"w": "深省;猛省", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1475wx','削','1','xiāo xuē','刂','9','','[{"pinyin": "xiāo", "defs": [{"meaning": "(本义读qiào。装刀剑的套子)。"}, {"meaning": "曲刀,书刀,削刀。", "cites": [{"t": "削书刀也。", "b": "《曲礼·金工》注"}]}, {"meaning": "斜着刀略平地切去物体的表层。", "cites": [{"t": "削则削。", "b": "《汉书·礼乐志》。注:“谓有所删去,以刀削简牍也。”"}, {"t": "为天子削瓜。", "b": "《礼记·曲礼》"}, {"t": "公输子削竹木以为鹊。", "b": "《墨子·鲁问》"}, {"t": "指如削葱根,口如含朱丹。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "削铅笔;切削;削瓜", "t": "削去瓜皮。古代的一种礼节;又指削去皮的瓜"}, {"w": "削杖", "t": "古代母丧时子服齐衰所执的木杖,用桐木削成。"}]}, {"meaning": "删除。指删改文字。", "cites": [{"t": "削而投之。", "b": "《左传》"}, {"t": "有司请定法,削则削,笔则笔,救时务也。", "b": "《汉书》。颜师古注:“削者,谓有所删去,以刀削简牍也。”"}], "words": [{"w": "削改", "t": "删改"}, {"w": "削抹", "t": "删改抹去。"}]}, {"meaning": "削除;削减。", "cites": [{"t": "外削幅。", "b": "《仪礼·丧服礼》"}, {"t": "寇至度必攻。主人先削城编,唯勿烧。", "b": "《墨子》"}], "words": [{"w": "削籍", "t": "官吏免职"}, {"w": "削免", "t": "削除"}, {"w": "削迹", "t": "削除车迹。谓不被任用;又作消踪匿迹。谓隐居。"}]}, {"meaning": "掠夺。", "cites": [{"t": "故为吏牧民者竞相剥削。", "b": "《梁书·贺琛传》"}], "words": [{"w": "削夺", "t": "剥夺,夺去"}, {"w": "削敛", "t": "剥削聚敛。"}]}, {"meaning": "分,割裂。", "cites": [{"t": "夫齐,削地而封田婴。", "b": "《战国策·齐策》"}], "words": [{"w": "削小", "t": "将封邑分小。"}]}, {"meaning": "剃;刮。", "cites": [{"t": "好雄强,似出家的子路,削了发的金刚。", "b": "《西厢记诸宫调》"}], "words": [{"w": "削剥", "t": "刮削;亦谓侵蚀"}, {"w": "削发披缁", "t": "剃去头发,身着黑衣。表示出家"}, {"w": "削头", "t": "犹削发。"}]}, {"meaning": "消瘦,纤细瘦长。", "cites": [{"t": "子何清削如此?", "b": "《流江记》"}], "words": [{"w": "削削", "t": "纤弱的样子"}, {"w": "削约", "t": "稀疏细小的样子"}, {"w": "削瘦", "t": ""}]}]}, {"pinyin": "xuē", "defs": [{"meaning": "削弱,削减。", "cites": [{"t": "辩智而鲁削。", "b": "《韩非子·五蠹》"}, {"t": "日削月割。", "b": "宋·苏洵《六国论》"}, {"t": "兵挫地削。", "b": "《史记·屈原贾生列传》"}, {"t": "楚日以削", "b": ""}]}, {"meaning": "徒峭。", "cites": [{"t": "石崖侧削。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "削壁(徒削的山崖)——现专用于合成词中,如“剥削”、“削减”、“瘦削”义同“削(xiāo)”", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1476wx','尝','1','cháng','小','9','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从旨,尚声。“旨”,滋味美。本义:辨别滋味,品尝)。"}, {"meaning": "同本义。", "cites": [{"t": "天子乃以雏尝黍。", "b": "《礼记·月令》"}, {"t": "臣先尝之。", "b": "《礼记·曲礼》"}, {"t": "不敢尝。", "b": "《论语》"}, {"t": "百鬼迪尝。", "b": "《汉书·礼乐志》"}, {"t": "尝其旨否。", "b": "《诗·小雅·甫田》"}], "words": [{"w": "尝酒;尝食", "t": "试辨食物的味道"}, {"w": "尝酎", "t": "祭祀的时候,尝一尝新酒的滋味。"}]}, {"meaning": "尝试。", "cites": [{"t": "尝,试也。", "b": "《小尔雅》"}, {"t": "诸侯方睦于晋,臣请尝人,若何?", "b": "《左传·襄公十八年》"}], "words": [{"w": "尝巧", "t": "试验其技巧"}, {"w": "尝汤戏", "t": "正戏前加演的短戏。"}]}, {"meaning": "经历。", "cites": [{"t": "险阻艰难,备尝之矣。", "b": "《左传·僖公十八年》"}], "words": [{"w": "备尝艰苦;尝到了公职的甜头", "t": ""}]}, {"meaning": "曾经。", "cites": [{"t": "仲永生五年,未尝识书具,忽啼求之。", "b": "宋·王安石《伤仲永》"}, {"t": "予尝求古仁人之心,或异二者之为,何哉?", "b": "宋·范仲淹《岳阳楼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1477wx','昧','1','mèi','日','9','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。从日,未声。从日,与光线有关。本义:昏暗不明)。"}, {"meaning": "同本义。", "cites": [{"t": "昧,冥也。", "b": "《广雅·释诂四》"}, {"t": "时甲子昧爽。", "b": "《书·牧誓》"}, {"t": "日昧昧其将暮。", "b": "《楚辞·九章·怀沙》"}, {"t": "君昧爽而栉冠。", "b": "《荀子·哀公》。注:“昧,闇;爽,明也。谓初晓尚暗之时。”"}, {"t": "神非其所宜而行之则昧。", "b": "《淮南子·原道》"}, {"t": "虽昧必亮。", "b": "《后汉书·苏竟传》"}, {"t": "愚者昧于成事。", "b": "《战国策·赵策》"}, {"t": "惟党人之偷乐兮,路幽昧以险隘。", "b": "《楚辞·离骚》"}, {"t": "轻身而昧大义。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "昧旦", "t": "天未全亮的时候"}, {"w": "昧然", "t": "昏暗不明的样子"}, {"w": "昧昧", "t": "昏暗不明的样子"}, {"w": "昧色", "t": "暮色"}, {"w": "昧明", "t": "天未全明的时刻;拂晓。"}]}, {"meaning": "眼不明的样子。", "cites": [{"t": "耳不听五声之和为聋,目不别五色之章为昧。", "b": "《左传·僖公二十四年》"}]}, {"meaning": "愚昧;糊涂。", "cites": [{"t": "兼弱攻昧。", "b": "《左传·宣公十二年》"}], "words": [{"w": "昧陋", "t": "愚昧浅陋"}, {"w": "味瞀", "t": "昏聩;糊涂"}, {"w": "昧昧", "t": "糊涂无知"}, {"w": "昧错", "t": "糊涂出错。"}]}, {"meaning": "掩蔽;欺骗。", "cites": [{"t": "吾家碑不昧。", "b": "杜甫《回棹》"}], "words": [{"w": "昧公义", "t": "埋没了公理和正义"}, {"w": "昧心咒", "t": "昧了良心该受什么报应的誓言"}, {"w": "昧心钱", "t": "坏了良心赚来的钱"}, {"w": "昧蔽", "t": "隐瞒"}, {"w": "昧诡", "t": "隐秘;诡秘"}, {"w": "昧密", "t": "犹隐晦。"}]}, {"meaning": "违背。", "cites": [{"t": "今日果成妙计,捉了唐僧,就好昧了前言?", "b": "《西游记》"}], "words": [{"w": "昧信", "t": "背信;失信"}, {"w": "昧良心;昧心", "t": ""}]}, {"meaning": "冒犯。", "cites": [{"t": "丞相臣斯昧死言。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "昧死", "t": "冒死;冒昧"}, {"w": "昧犯", "t": "冒犯。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1478wx','盹','1','dǔn','目','9','','[{"pinyin": "dǔn", "defs": [{"meaning": "(形声。从目,屯声。本义:闭目小睡)很短时间的睡眠。", "words": [{"w": "打盹", "t": ""}, {"w": "盹寐", "t": "瞌睡"}, {"w": "盹困", "t": "倦极思睡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1479wx','是','1','shì','日','9','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。小篆字形,从日正。本义:正,不偏斜)。"}, {"meaning": "同本义。", "cites": [{"t": "是,直也。", "b": "《说文》。按,十目烛隐曰直,以日为正曰是。"}, {"t": "而疑是精粗之体。", "b": "《礼记·玉藻》。疏:“谓正也。”"}, {"t": "上九,濡其首,有孚失是。", "b": "《易·未济》"}]}, {"meaning": "对的,正确的。", "cites": [{"t": "王弗是。", "b": "《国语·楚语》。注;“理也。”"}, {"t": "使目非是,无欲见也。", "b": "《荀子·劝学》。注:“谓正道也。”"}, {"t": "立是废非。", "b": "《淮南子·脩务》。注:“善也。”"}, {"t": "彼人是哉。", "b": "《诗·魏风·园有桃》"}, {"t": "虽不谓吾言为是,而亦无词相答。", "b": "清·林觉民《与妻书》"}, {"t": "实迷途其未远,觉今是而昨非。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "是非堆", "t": "招惹是非的人"}, {"w": "是非垓", "t": "是非窝"}, {"w": "是非涡", "t": "矛盾纠纷的中心"}, {"w": "是非场", "t": "矛盾纠纷场所。"}]}, {"meaning": "此,这。", "cites": [{"t": "是谓伐德。", "b": "《诗·小雅·宾之初筵》"}, {"t": "天将降大任于是人也,必先苦其心志。", "b": "《孟子·告子下》"}, {"t": "安有为天下阽危者若是而上不惊者。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "是日", "t": "此日,这一天"}, {"w": "是夕", "t": "这天晚上"}, {"w": "是处", "t": "这里;此处"}, {"w": "是长是短", "t": "这样长这样短;如此这般"}, {"w": "是月", "t": "这个月"}, {"w": "是年", "t": "今年"}, {"w": "是可忍,孰不可忍", "t": ""}]}, {"meaning": "赞同;认为正确;肯定。", "cites": [{"t": "盘庚不为怨者故改其度,度义而后动,是而不见可悔故也。", "b": "宋·王安石《答司马谏议书》"}, {"t": "是己而非人,俗之同病。", "b": "清·刘开《问说》"}], "words": [{"w": "是古非今", "t": "崇尚古代的,贬低现代的"}, {"w": "是是非非", "t": "肯定正确的,否定错误的。指评定是非"}, {"w": "各是其是;深是其言", "t": ""}]}, {"meaning": "遵从,以为法则。", "cites": [{"t": "不法先王,不是礼义。", "b": "《荀子》。杨柳桥诂:“《尔雅》:‘是,则也。’”"}]}, {"meaning": "关系词。表示肯定判断之词。", "cites": [{"t": "正是四国。", "b": "《诗·曹风·鸤鸠》"}, {"t": "吾作此书时,尚是世中一人。", "b": "清·林觉民《与妻书》"}, {"t": "汝是大家子,仕宦于台阁。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "今天是端午节;只能是他来电话", "t": ""}]}, {"meaning": "表示两种事情同一,或后者说明前者。", "cites": [{"t": "原其理,当是为谷中大水冲激,沙土尽去,唯巨石岿然挺立耳。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "他不是学生", "t": ""}]}, {"meaning": "表示让步。", "cites": [{"t": "此去经年,应是良辰美景虚设。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "料子是好料子,就是贵了点", "t": ""}]}, {"meaning": "表示肯定 昨天买的票;他手艺是高明,做出来的东西就是不一样。"}, {"meaning": "“是”不重读时,可省略,只表示一般肯定 问问,没有别的意思。"}, {"meaning": "表示原因、目的。“是”后可加“因为、由于、为了” 平时太骄傲了。"}, {"meaning": "或者。"}, {"meaning": "有时也用完整的“是”字句回答。", "cites": [{"t": "你是上海人还是北京人?", "b": "我是北京人"}]}, {"meaning": "商业、职业或政府的事务、业务或国务。", "cites": [{"t": "君臣不合,则国是(国家正确的方针大计)无从定矣。", "b": "范晔《后汉书》"}], "words": [{"w": "是事", "t": "事事,凡事"}, {"w": "国是", "t": ""}]}, {"meaning": "帮助宾语提前。", "cites": [{"t": "孜孜焉唯进修是急,未之多见也。", "b": "清·刘开《问说》"}, {"t": "主上屈法申恩,吞舟是漏。", "b": "南朝梁·丘迟《与陈伯之书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1480wx','盼','1','pàn','目','9','','[{"pinyin": "pàn", "defs": [{"meaning": "(形声。从目,分声。本义:眼睛黑白分明的样子) 同本义。喻美目流转。", "cites": [{"t": "盼,目黑白分也。", "b": "《说文》"}, {"t": "美目盼兮。", "b": "《诗·卫风·硕人》。传:“盼,白黑分。”"}, {"t": "盼,美目也。", "b": "《字林》"}], "words": [{"w": "盼刀", "t": "旧时相术用语。凶恶的目光"}, {"w": "盼瞩", "t": "流转的目光。"}]}, {"meaning": "顾;看。", "cites": [{"t": "盼,视也。", "b": "《广雅》"}, {"t": "祇宜近盼天都,明日登莲顶。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "盼睇", "t": "顾盼"}, {"w": "盼睐", "t": "欣裳。顾盼和青睐观看"}, {"w": "盼恋", "t": "顾盼留恋。"}]}, {"meaning": "探望。", "cites": [{"t": "生急起揖之,答曰:“将以盼亲。”…媪笑曰:“奇哉!姓名尚自不知,何亲可探?”", "b": "《聊斋志异·婴宁》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1481wx','眨','1','zhǎ','目','9','','[{"pinyin": "zhǎ", "defs": [{"meaning": "(形声。从目,乏声。本义:眼睛一闭一开)。"}, {"meaning": "同本义。", "cites": [{"t": "沼似颇黎镜,当中见鱼眨。", "b": "唐·皮日休《二游诗》"}], "words": [{"w": "眨眨", "t": "眼光闪烁不定的样子"}, {"w": "眨眉", "t": "眨眼"}, {"w": "眨闪", "t": "眼睛开合闪动"}, {"w": "眨动", "t": "眼睑开合。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1482wx','哇','1','wā wa','口','9','','[{"pinyin": "wā", "defs": [{"meaning": "(形声。从口,圭(guī)声。本义:靡曼的乐声)。"}, {"meaning": "同本义。", "cites": [{"t": "哇,谄声也。", "b": "《说文》。按,滔淫之声也。"}, {"t": "含情哇而吟咏。", "b": "张衡《舞赋》"}], "words": [{"w": "哇淫", "t": "鄙俗淫靡"}, {"w": "哇哩", "t": "鄙俗"}, {"w": "哇咬", "t": "俚俗的音乐;民歌。"}]}, {"meaning": "泰国长度单位,泰丈,庹,约等于2米。"}, {"meaning": "呕吐,使胃内容物通过口腔吐出。", "cites": [{"t": "出而哇之。", "b": "《孟子·滕文公下》"}]}, {"meaning": "嚎哭或叫喊(如由于痛苦、生气或要求援助或怜悯)。", "cites": [{"t": "哀哇动梁埃,急觞荡幽默。", "b": "南朝宋·谢灵运《拟魏太子邺中集诗》"}]}]}, {"pinyin": "wa", "defs": [{"meaning": "“啊”受到前一字收音u或ao影响而发生的音变。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1483wx','哄','1','hōng hǒng hòng','口','9','','[{"pinyin": "hōng", "defs": [{"meaning": "(形声。从口,共声。本义:许多人同时发声)。"}, {"meaning": "同本义。", "cites": [{"t": "游人哄笑观俳优。", "b": "宋·孔平仲《上元作》"}], "words": [{"w": "哄笑;哄饮", "t": "聚众饮酒"}, {"w": "哄伙", "t": "形容热闹,盛大"}, {"w": "哄然;哄哄翕翕", "t": "潦潦草草;匆匆忙忙。"}]}, {"meaning": "呵叱。", "cites": [{"t": "叿,呵也。或作哄。", "b": "《集韵》"}, {"t": "驺哄,呵喝声。", "b": "《篇海类篇》"}]}]}, {"pinyin": "hǒng", "defs": [{"meaning": "混。", "cites": [{"t": "四人杂在社火队里,取路哄入封丘门来。", "b": "《水浒传》"}]}]}, {"pinyin": "hòng", "defs": [{"meaning": "吵闹;喧嚣。", "cites": [{"t": "鬨,斗也。从门,共声。", "b": "《说文》"}, {"t": "邹与鲁鬨。", "b": "《孟子》"}], "words": [{"w": "哄堂", "t": "喧笑声盛大,洋溢全堂"}, {"w": "哄然", "t": "喧闹声盛大"}, {"w": "哄堂大笑", "t": "全堂大笑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1484wx','哑','1','yā yǎ','口','9','','[{"pinyin": "yā", "defs": [{"meaning": "(形声。从口,亚声。本义:笑声)。"}, {"meaning": "同本义。", "cites": [{"t": "哑,笑也。", "b": "《说文》"}, {"t": "笑言哑哑。", "b": "《易·震》"}]}, {"meaning": "乌鸦之类的叫声。", "cites": [{"t": "乌之哑哑,鹊之唶唶。", "b": "《淮南子》"}]}, {"meaning": "婴儿学说话的声音。", "cites": [{"t": "哑,哑呕,小儿学言。", "b": "《集韵》"}]}, {"meaning": "相当于现代汉语的“呀”。", "cites": [{"t": "我爷哑!好大蚊子!一口就叮了一个大疙疸!", "b": "《西游记》"}]}, {"meaning": "相当于“呀”。", "cites": [{"t": "你放心,莫哭,我去哑!", "b": "《西游记》"}]}]}, {"pinyin": "yǎ", "defs": [{"meaning": "由于生理缺陷或疾病而失去言语功能。", "cites": [{"t": "吞炭为哑。", "b": "《史记·刺客传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1485wx','显','1','xiǎn','日','9','','[{"pinyin": "xiǎn", "defs": [{"meaning": "(会意。从页(xié)从显,显亦声。今字从页,与人头有联系。本义:头上的装饰品)。"}, {"meaning": "同本义。", "cites": [{"t": "显,头明饰也。", "b": "《说文》。段玉裁注:“头明饰者,冕弁充耳之类。”"}]}, {"meaning": "表面,外面。", "cites": [{"t": "所说阴为厚利而显为名高者也。", "b": "《韩非子》"}]}, {"meaning": "明显;显示得很清楚。", "cites": [{"t": "显,见也。", "b": "《尔雅》。注:“显,明见也。”"}, {"t": "天维显思。", "b": "《诗·周颂·敬之》"}, {"t": "不敢显然布币行礼。", "b": "《国语·吴语》"}, {"t": "故法莫如显,而术不欲见。", "b": "《韩非子·难三》"}], "words": [{"w": "显轿", "t": "没有顶篷、扶手的大椅式轿子。也叫亮轿,明舆"}, {"w": "显亮", "t": "敞亮。"}]}, {"meaning": "显赫,显达。", "cites": [{"t": "高爵显位。", "b": "明·张溥《五人墓碑记》"}, {"t": "赠谥美显", "b": ""}], "words": [{"w": "显融", "t": "显达荣耀"}, {"w": "显人", "t": "闻名天下的人"}, {"w": "显位", "t": "崇高的职位"}, {"w": "显官", "t": "居高位的官员。"}]}, {"meaning": "明,光明。", "cites": [{"t": "我久不画了。如今住的房屋不比园里的显亮,所以没兴头画。", "b": "《红楼梦》"}], "words": [{"w": "显晦", "t": "明与暗。喻出仕与隐居"}, {"w": "显证", "t": "明证。"}]}, {"meaning": "显露;公开。", "cites": [{"t": "嘉木立,美竹露,奇石显。", "b": "柳宗元《钴鉧潭西小丘记》"}], "words": [{"w": "显行", "t": "实施;公开施行"}, {"w": "显戮", "t": "依法公开处决"}, {"w": "显隐", "t": "显现与隐没。"}]}, {"meaning": "传扬;显扬。", "cites": [{"t": "孙膑以此名显天下。", "b": "《史记·孙子吴起列传》"}], "words": [{"w": "显亲", "t": "使双亲显扬"}, {"w": "显亲扬名", "t": "亲属显耀,声名远扬。"}]}, {"meaning": "表现;显示。", "cites": [{"t": "此是亡灵未泯,故来显应。", "b": "《初刻拍案惊奇》"}], "words": [{"w": "显道神", "t": "险道神,显道人。出殡时在送葬队伍最前面的高大的开路神像。"}]}, {"meaning": "见。", "cites": [{"t": "九曲风涛何处显。", "b": "《西厢记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1486wx','冒','1','mào mò','冂','9','','[{"pinyin": "mào", "defs": [{"meaning": "(会意。小篆字形。上为帽子,下边是眼睛。本义:帽子)。"}, {"meaning": "“帽”的古字。帽子。", "cites": [{"t": "著黄冒。", "b": "《汉书·儁不疑传》"}, {"t": "白纱冒者,视朝、听讼、宴见宾客之服也。", "b": "《新唐书》"}], "words": [{"w": "冒絮", "t": "头巾。"}]}, {"meaning": "古代殓尸的布囊,由上下两截合成。", "cites": [{"t": "冒:缁质,长与手齐。", "b": "《仪礼》"}]}, {"meaning": "冒与芼古字通。芼,菜也。", "cites": [{"t": "肥狗之和,冒以山肤。", "b": "枚乘《七发》"}]}, {"meaning": "天子所执之玉。", "cites": [{"t": "天子执冒四寸,以朝诸侯。", "b": "《周礼·考工记·玉人》"}]}, {"meaning": "戴帽。", "cites": [{"t": "山东之卒被甲冒胄以会战。", "b": "《战国策》"}]}, {"meaning": "贪求,不知满足地追求。", "cites": [{"t": "舟人冒利。", "b": "黄宗羲《余姚至省下路程沿革记》"}, {"t": "缙云氏有不才子,贪于饮食,冒于货贿。", "b": "《左传·文公十八年》"}], "words": [{"w": "冒色", "t": "贪恋女色"}, {"w": "冒没", "t": "贪图;贪得"}, {"w": "冒荣", "t": "贪图荣耀"}, {"w": "冒乱", "t": "贪恋淫乱"}, {"w": "冒货", "t": "贪财。"}]}, {"meaning": "盖蒙。", "cites": [{"t": "下土是冒。", "b": "《诗·邶风·日月》"}, {"t": "善恶相冒。", "b": "《汉书·翟方进传》"}, {"t": "蜡和纸灰之类冒之。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "冒阴", "t": "笼罩着阴影。"}]}, {"meaning": "不顾;顶着。", "cites": [{"t": "冒风驰行。", "b": "明·袁宏道《满井游记》"}, {"t": "惟冒险也。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "冒突", "t": "冒进直前"}, {"w": "冒夜", "t": "不顾黑夜"}, {"w": "冒死", "t": "不顾生命危险"}, {"w": "冒寒", "t": "冒着寒冷"}, {"w": "冒刀", "t": "迎着刀锋。"}]}, {"meaning": "假冒。", "cites": [{"t": "冒其未死。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "冒认", "t": "冒名认取"}, {"w": "冒功", "t": "假冒功绩"}, {"w": "冒占", "t": "冒名占有。"}]}, {"meaning": "侵犯;违犯。", "cites": [{"t": "习俗薄恶,民人抵冒。", "b": "《汉书·礼乐志》"}, {"t": "其君贪冒辟邪。", "b": "《国语·周语上》"}, {"t": "有冒上而无忠下。", "b": "《国语·晋语》"}, {"t": "稍近,益狎,荡倚冲冒。", "b": "唐·柳宗元《三戒》"}, {"t": "冒使君。", "b": "明·高启《博鸡者事》"}], "words": [{"w": "冒撞", "t": "冒犯,唐突;莽撞"}, {"w": "冒突", "t": "冲冒;冒犯"}, {"w": "冒昧", "t": "冒犯,无知而妄为"}, {"w": "冒文", "t": "违犯法令条文"}, {"w": "冒法", "t": "违犯法规。"}]}, {"meaning": "嫉妬。", "cites": [{"t": "人之有技,冒疾以恶之。", "b": "《书·秦誓》"}]}, {"meaning": "勉励。", "cites": [{"t": "我咸成文王功于不怠,丕冒。", "b": "《书·君奭》"}]}, {"meaning": "冒失;冒昧。", "cites": [{"t": "此数者用兵之患也,而操皆冒行之。", "b": "《资治通鉴》"}], "words": [{"w": "冒势", "t": "鲁莽,莽撞"}, {"w": "冒失鬼;冒不失", "t": "方言。轻率,鲁莽"}, {"w": "冒行", "t": "冒然行动;冒然实行"}, {"w": "冒撞", "t": "冒失鲁莽。"}]}]}, {"pinyin": "mò", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1487wx','映','1','yìng','日','9','','[{"pinyin": "yìng", "defs": [{"meaning": "(形声。从日,央声。本义:照)。"}, {"meaning": "同本义。", "cites": [{"t": "映,明也。", "b": "《说文新附》"}, {"t": "日阴曰映。", "b": "《通俗文》"}, {"t": "冠盖相映。", "b": "《后汉书·张衡传》"}, {"t": "映日荷花别样红。", "b": "宋·杨万里《晓出净慈寺送林子方》"}, {"t": "映日不可逼视。", "b": "《广东军务记》"}], "words": [{"w": "映耀", "t": "辉映;照耀"}, {"w": "映日", "t": "映照着日光"}, {"w": "辉映", "t": "照耀,映射。"}]}, {"meaning": "反映,因光线照射而显出。", "cites": [{"t": "狭石分花径,长桥映水门。", "b": "北周·庾信《咏画屏风》"}], "words": [{"w": "垂杨柳倒映在水里;放映", "t": "利用强光装置把图片或影片上的形象照射在幕上或墙上"}, {"w": "映入眼帘", "t": ""}]}, {"meaning": "映衬。", "cites": [{"t": "千里莺啼绿映红,水村山郭酒旗风。", "b": "唐·杜牧《江南春绝句》"}], "words": [{"w": "映协", "t": "互相映衬和协"}, {"w": "映媚", "t": "互相映衬而成一种美的景致。"}]}, {"meaning": "遮;隐藏。", "cites": [{"t": "疏条交映。", "b": "吴均《与朱元思书》"}], "words": [{"w": "映掩", "t": "掩映"}, {"w": "映身", "t": "隐身"}, {"w": "映蔽", "t": "遮蔽。"}]}, {"meaning": "阳光。", "cites": [{"t": "山岗有余映,岩阿增重阴。", "b": "王粲《七哀》"}]}, {"meaning": "未时。午后一到 三时。", "cites": [{"t": "梁元帝《纂要》云:“日在午曰亭,在未曰映。”", "b": "明·杨慎《丹铅续录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1488wx','星','1','xīng','日','9','','[{"pinyin": "xīng", "defs": [{"meaning": "(象形。从晶,生声。晶象形。本义:星星)。"}, {"meaning": "同本义  宇宙间发射或反射光的天体。", "cites": [{"t": "星,万物之精,上为列星。", "b": "《说文》。按,散文则统谓之星,对文则五纬为星,二十八宿为辰。"}, {"t": "日月星辰。", "b": "《书·尧典》"}, {"t": "四曰星辰。", "b": "《书·洪范》。郑注:“星,五星也。”"}, {"t": "列星随旋,日月递炤。(炤:照耀)", "b": "《荀子》"}], "words": [{"w": "星筹", "t": "寿算之筹"}, {"w": "星霜", "t": "比喻年月"}, {"w": "星桥", "t": "神话传说中的鹊桥。也作银桥"}, {"w": "星布", "t": "天星密布"}, {"w": "星列", "t": "天星罗列。"}]}, {"meaning": "天文。", "cites": [{"t": "文史星历,近乎卜祝之间。", "b": "司马迁《报任安书》"}], "words": [{"w": "星工", "t": "通晓星象的人"}, {"w": "星文", "t": "星象"}, {"w": "星变", "t": "星象的异常变化。"}]}, {"meaning": "古时特指妇女装饰面颊的美容花点 。"}, {"meaning": "斑白。多指鬓发。", "cites": [{"t": "诗老相过鬓已星,吟魂未减昔年清。", "b": "宋·王伯大《赠戴石屏》"}], "words": [{"w": "星鬓", "t": "发白的鬓发"}, {"w": "星发", "t": "花白的头发。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1489wx','昨','1','zuó','日','9','','[{"pinyin": "zuó", "defs": [{"meaning": "(形声。从日,乍声。本义:隔夜,上一天)。"}, {"meaning": "同本义。", "cites": [{"t": "昨,垒日也。", "b": "《说文》。按,絫日,从日,乍声。"}, {"t": "昨,隔日也。", "b": "《苍颉篇》"}, {"t": "夏日复昨。", "b": "《尔雅》"}, {"t": "周昨来,有中道而呼者。", "b": "《庄子·外物》"}], "words": [{"w": "昨伲", "t": "昨日"}, {"w": "昨而子", "t": "今天的前一天"}, {"w": "昨日子", "t": "昨天"}, {"w": "昨几", "t": "昨天"}, {"w": "昨夜", "t": "昨天夜里"}, {"w": "昨宵", "t": "昨夜"}, {"w": "昨暝", "t": "昨晚。"}]}, {"meaning": "泛指往日;过去。", "cites": [{"t": "觉今是而昨非。", "b": "晋·陶潜《归去来兮辞》"}, {"t": "昨夜见军帖。", "b": "《乐府诗集·木兰诗》"}, {"t": "昨下第。", "b": "唐·李朝威《柳毅传》"}, {"t": "昨间海令为母寿。", "b": "《明史》"}], "words": [{"w": "昨年", "t": "去年"}, {"w": "昨先", "t": "先前"}, {"w": "昨前", "t": "从前"}, {"w": "昨非", "t": "往日的不是"}, {"w": "昨轨", "t": "往昔的轨迹"}, {"w": "昨者", "t": "昔日。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1490wx','咧','1','liě liē lié lie','口','9','','[{"pinyin": "liě", "defs": [{"meaning": "嘴向旁边斜着张开"}]}, {"pinyin": "liē", "defs": [{"meaning": "形容随随便便，满不在乎的样子。"}]}, {"pinyin": "lié", "defs": [{"meaning": "[方言]乱说乱讲"}]}, {"pinyin": "lie", "defs": [{"meaning": "相当于“了”、“啦”、“哩”等。", "cites": [{"t": "老爷们叫你来为开心的,你可哭开自己咧!那不得罪人吗?快别哭咧!", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1491wx','昭','1','zhāo','日','9','','[{"pinyin": "zhāo", "defs": [{"meaning": "(形声。从日,召声。本义:明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "昭,日明也。", "b": "《说文》"}, {"t": "倬彼云汉,昭回于天。", "b": "《诗·大雅·云汉》"}, {"t": "青春受谢,白日昭只。", "b": "《楚辞·大招》"}], "words": [{"w": "昭式", "t": "光明的法度"}, {"w": "昭列", "t": "光明"}, {"w": "昭衍", "t": "光明广布"}, {"w": "昭亮", "t": "明亮"}, {"w": "昭美", "t": "光明美好。"}]}, {"meaning": "彰明,显著。", "cites": [{"t": "所以昭炯戒。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "昭升", "t": "显著地升闻"}, {"w": "昭名", "t": "显著的声名"}, {"w": "昭灼", "t": "明显;显著"}, {"w": "昭明", "t": "显明;显著"}, {"w": "昭速", "t": "明显地招引。"}]}, {"meaning": "光;亮光。", "cites": [{"t": "倬彼云汉,昭回于天。", "b": "《诗·大雅·云汉》"}], "words": [{"w": "昭回", "t": "晨辰光耀回转"}, {"w": "昭耀", "t": "光耀"}, {"w": "昭晳", "t": "光亮。"}]}, {"meaning": "古时宗法制度 ,宗庙次序,始祖居中,二世、四世、六世位于始祖之左方,称“昭”;三世、五世、七世,位于右方,称“穆”。又坟地葬位的左右次序也按此规定排列。"}, {"meaning": "显扬;显示。", "cites": [{"t": "昭陛下圣明。", "b": "诸葛亮《出师表》"}], "words": [{"w": "昭畅", "t": "大大发扬"}, {"w": "昭文", "t": "显扬文采"}, {"w": "昭武", "t": "显扬武威“炤”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1492wx','畏','1','wèi','田','9','','[{"pinyin": "wèi", "defs": [{"meaning": "(会意。据甲骨文意思是鬼手拿杖打人,使人害怕。本义:害怕)。"}, {"meaning": "同本义(对威势、威严的害怕)。", "cites": [{"t": "畏,惧也。", "b": "《广雅·释诂二》"}, {"t": "畏,恐也。", "b": "《广雅·释诂四》"}, {"t": "不畏不怒。", "b": "《列子·黄帝》"}, {"t": "天明畏。", "b": "《书·皋陶谟》"}, {"t": "以小事大者,畏天者也。", "b": "《孟子·梁惠王下》"}, {"t": "公子畏死邪?何泣也?", "b": "《史记·魏公子列传》"}, {"t": "妾之美我者,畏我也。", "b": "《战国策·齐策》"}, {"t": "然畏愬。", "b": "《资治通鉴·唐纪》"}, {"t": "忧谗畏讥。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "巍巍乎可畏。", "b": "明·刘基《卖柑者言》"}, {"t": "畏其唇吻。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "畏威", "t": "畏惧权势"}, {"w": "畏威怀德", "t": "害怕他的威严,怀念他的恩德"}, {"w": "畏之如虎", "t": "像怕老虎那样害怕"}, {"w": "畏天知命", "t": "谓知天命,识时务"}, {"w": "畏死贪生", "t": "害怕死亡,贪恋生存"}, {"w": "畏戒", "t": "畏惧戒惕"}, {"w": "畏附", "t": "畏惧依附。"}]}, {"meaning": "敬;敬服。", "cites": [{"t": "心畏相公。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "畏天恤民", "t": "敬畏上天,爱怜下民"}, {"w": "畏天悯人", "t": "敬畏天命,悯惜世人的困苦"}, {"w": "畏伏", "t": "敬服"}, {"w": "畏俯", "t": "犹敬服"}, {"w": "畏敬", "t": "尊敬;敬重"}, {"w": "畏钦", "t": "尊敬钦佩"}, {"w": "畏爱", "t": "敬佩爱戴"}, {"w": "畏羡", "t": "敬重羡慕。"}]}, {"meaning": "担心。", "cites": [{"t": "畏有家人来洒扫。", "b": "唐·王建《寒食行》"}]}, {"meaning": "避开。", "cites": [{"t": "客子常畏人。", "b": "三国魏·曹丕《杂诗》"}]}, {"meaning": "憎恶;怨恨。", "cites": [{"t": "畏,恶也。", "b": "《广雅》"}, {"t": "是后魏王畏公子之贤能。", "b": "《史记·魏公子列传》"}]}, {"meaning": "死,古代指被兵器杀死。", "cites": [{"t": "人皆见曾点曰:“无乃畏邪?”", "b": "《吕氏春秋》"}]}, {"meaning": "弯曲处。", "cites": [{"t": "夫角之中,恒当弓之畏。", "b": "《考工记》"}]}, {"meaning": "罪。", "cites": [{"t": "畏,罪也。", "b": "《广雅》"}]}, {"meaning": "险恶的。", "cites": [{"t": "畏路不堪论。", "b": "吴国伦《得元乘书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1493wx','趴','1','pā','足','9','','[{"pinyin": "pā", "defs": [{"meaning": "肚子向下卧倒", "words": [{"w": "趴下", "t": ""}, {"w": "趴虎儿", "t": "身体向前跌倒的姿势"}, {"w": "趴窝", "t": "母鸡趴在窝里孵小鸡"}, {"w": "趴窝", "t": "母畜生幼畜前趴在地上不动"}, {"w": "趴窝", "t": "身体垮了"}, {"w": "趴窝", "t": "机器和机动车等发生故障，不能开动"}]}, {"meaning": "身体向前靠在东西上"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1494wx','胃','1','wèi','月','9','','[{"pinyin": "wèi", "defs": [{"meaning": "(象形。据小篆字形。上象口袋形的消化器官,下为肉。本义:人和动物贮藏和消化食物的器官)。"}, {"meaning": "同本义。", "cites": [{"t": "疾在肠胃。", "b": "《韩非子·喻老》"}, {"t": "在肠胃。", "b": ""}], "words": [{"w": "重瓣胃;胃疸", "t": "中医指胃部虚热"}, {"w": "胃气痛", "t": "方言。胃痛"}, {"w": "胃气", "t": "中医指胃的生理功能及其精气;泛指胃病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1495wx','贵','1','guì','贝','9','','[{"pinyin": "guì", "defs": [{"meaning": "(形声。小篆字形,从贝,臾(guì)声。从“贝”,表示与钱物有关。本义:物价高,与“贱”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "贵,物不贱也。", "b": "《说文》"}, {"t": "贵货而贱土。", "b": "《国语·晋语》"}, {"t": "不贵难得之货。", "b": "《老子》"}, {"t": "国之诸市,屦贱踊贵。", "b": "《左传·昭公三年》"}, {"t": "遂白令边郡皆筑仓,以谷贱时增其贾(价)而籴,以利农,谷贵时减贾而粜,名曰常平仓。", "b": "《汉书·食货志上》"}], "words": [{"w": "春雨贵如油;昂贵", "t": "价格很高"}, {"w": "贵腾", "t": "价格暴涨"}, {"w": "贵踊", "t": "物价上涨"}, {"w": "贵贾", "t": "高价。"}]}, {"meaning": "社会地位高。", "cites": [{"t": "贵,尊也。贵贱以物喻。犹尊卑以器喻。", "b": "《广雅》"}, {"t": "一曰爵以驭其贵。", "b": "《周礼·太宰》"}, {"t": "民犹犯贵。", "b": "《礼记·坊记》"}, {"t": "贵贵为其近于君也。", "b": "《礼记·祭义》"}, {"t": "苟富贵,无相忘。", "b": "《史记·陈涉世家》"}], "words": [{"w": "显贵;权贵;亲贵", "t": "帝王的近亲或亲信"}, {"w": "富贵", "t": "有钱又有地位"}, {"w": "贵地", "t": "显达的地位;尊称他人的乡里"}, {"w": "贵途", "t": "升官晋爵的途径"}, {"w": "贵私", "t": "一心想私人占有"}, {"w": "贵不期骄", "t": "显贵者不锲望染上骄恣专横的习气,但仍在不知不觉中滋长起来了。"}]}, {"meaning": "贵重;重要。", "cites": [{"t": "礼之用,和为贵。", "b": "《论语·学而》"}], "words": [{"w": "贵宝", "t": "贵重的宝物"}, {"w": "贵献", "t": "贵重的献礼"}, {"w": "贵器", "t": "贵重的器皿。喻大器或高位"}, {"w": "贵珍", "t": "贵重的珍品。"}]}, {"meaning": "敬辞,尊称与对方有关的事物时用。", "cites": [{"t": "贵房师高要县汤公,就是先祖的门生。", "b": "《儒林外史》"}], "words": [{"w": "贵国;贵府;贵地;贵上下", "t": "询问对方姓名的敬辞"}, {"w": "贵上", "t": "对别人的仆役称其主人的敬称。"}]}, {"meaning": "地位显要的人。", "cites": [{"t": "虽沾巾覆形,不及贵门犬。", "b": "唐·于之贲《山村臾》"}], "words": [{"w": "贵门", "t": "权贵人家"}, {"w": "贵阶", "t": "唐代品秩之制有九品,五品以上称贵阶"}, {"w": "贵游", "t": "没有官职的王公贵族"}, {"w": "贵躬", "t": "指王公贵人。"}]}, {"meaning": "贵州省的简称。", "cites": [{"t": "古人贵朝闻夕死,况君前途尚可。", "b": "《世说新语·自新》"}], "words": [{"w": "云贵高原", "t": ""}]}, {"meaning": "姓。汉有庐江太守贵迁。"}, {"meaning": "抬高物价。", "cites": [{"t": "而粜谷之人贵贱其价。", "b": "《论衡·变动》"}, {"t": "欲民务农,在于贵粟。", "b": "晁错《论贵粟疏》"}]}, {"meaning": "崇尚,重视。", "cites": [{"t": "去谗远色,贱货而贵德。", "b": "《礼·中庸》"}, {"t": "有道之士,贵以近知远,以今知古,以所见知所不见。", "b": "《吕氏春秋·察今》"}, {"t": "圣王者不贵义而贵法。", "b": "《商君书·画策》"}], "words": [{"w": "贵德", "t": "崇尚道德"}, {"w": "贵爱", "t": "珍贵爱重"}, {"w": "贵农贱商", "t": "重农轻商"}, {"w": "贵尚", "t": "崇尚;尊崇"}, {"w": "贵好", "t": "崇尚和喜好"}, {"w": "贵贵", "t": "尊敬显贵的人"}, {"w": "贵敬", "t": "敬重"}, {"w": "贵异", "t": "特别看重;不作一般看待;珍视"}, {"w": "贵信", "t": "尊重和信任。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1496wx','界','1','jiè','田','9','','[{"pinyin": "jiè", "defs": [{"meaning": "(会意。从田,介声。本义:边垂,边境)。"}, {"meaning": "同本义。", "cites": [{"t": "界,境也。", "b": "《说文》。按,田畔也。"}, {"t": "界,垂也。", "b": "《尔雅》"}, {"t": "田边谓之界。", "b": "《急就篇·顷町界亩》颜注"}, {"t": "诸吏卒民非其部界而擅入他部界。", "b": "《墨子·号令》"}, {"t": "去门十里以为界。", "b": "《韩非子·五蠹》"}, {"t": "域民不以封疆之界。", "b": "《孟子·公孙丑下》"}, {"t": "至燕南界。", "b": "《战国策·燕策》"}, {"t": "迎公子于界。", "b": "《史记·魏公子列传》"}, {"t": "境界危恶。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "界分", "t": "分界处;地界"}, {"w": "界约", "t": "两国为明定疆界的界址而缔结的条约"}, {"w": "界贼", "t": "扰乱国境的盗贼"}, {"w": "界至", "t": "指边界。"}]}, {"meaning": "界限;范围。", "cites": [{"t": "是非之封界,分职名象之所起。", "b": "《荀子·正议》"}, {"t": "求而无度量分界,则不能不争。", "b": "《荀子·礼论》"}, {"t": "奢俭之中,以礼为界。", "b": "《后汉书·马融传》"}], "words": [{"w": "界说", "t": "逻辑名词。即定义"}, {"w": "界身子", "t": "北宋开封的一街巷名,为当时的商业区"}, {"w": "界程", "t": "界限和范围"}, {"w": "界墙", "t": "作为分界的墙壁。"}]}, {"meaning": "指某一特殊的境域。", "cites": [{"t": "蓬莱仙界海门通。", "b": "刘沧《宿题天霁寺诗》"}], "words": [{"w": "境界;上界;下界;外界;租界", "t": ""}]}, {"meaning": "毗邻,毗连;接界。", "cites": [{"t": "三国之与秦壤界而患急。", "b": "《战国策·秦策》"}], "words": [{"w": "东界黄海;界边", "t": "边界相接"}, {"w": "界天", "t": "接天。"}]}, {"meaning": "划分。", "cites": [{"t": "瀑布飞流以界道。", "b": "孙卓《游天台山赋》"}], "words": [{"w": "界破", "t": "划破"}, {"w": "界别", "t": "划分;区别"}, {"w": "界朱", "t": "用红笔划成行格"}, {"w": "界路", "t": "交叉路口"}, {"w": "界断", "t": "划断;分开。"}]}, {"meaning": "离间。", "cites": [{"t": "[范雎]界泾阳,抵穰侯而代之。", "b": "扬雄《解嘲》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1497wx','虹','1','hóng','虫','9','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从虫,工声。甲骨文“虹”与杠梁、古玉璜之形相似。本义:雨后天空出现的弧形彩晕。主虹称虹,副虹称霓)。"}, {"meaning": "同本义。", "cites": [{"t": "虹,螮蝀也,状似虫。", "b": "《说文》"}, {"t": "虹霓也,云雾也,风雨也,四时也,此积气之成乎天者也。", "b": "《列子·天瑞》"}, {"t": "虹双出,色鲜盛者为雄,雄曰虹。暗者为雌,雌曰霓。", "b": "《尔雅·释天》疏"}, {"t": "不霁何虹。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "虹亘中天。", "b": "《广东军务记》"}], "words": [{"w": "虹女", "t": "古代把虹比作美人,故称虹霓为虹女"}, {"w": "虹梁", "t": "形状似虹的曲梁"}, {"w": "虹霓", "t": "即彩虹"}, {"w": "虹霓吐颖", "t": "吐气成虹霓。形容有丰富的诗文才华。"}]}, {"meaning": "桥的代称。", "cites": [{"t": "跨虹连绝岸,浮鼋续断航。", "b": "庾信《忝在司水看治谓桥》"}]}, {"meaning": "惑乱。", "cites": [{"t": "彼童而角,实虹小子。", "b": "《诗·大雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1498wx','虾','1','xiā há','虫','9','','[{"pinyin": "xiā", "defs": [{"meaning": "动物名 。节肢动物门,甲壳纲,软甲亚纲,十足目,长尾亚目。许多较小的须,有一细长身体及侧扁的腹部,长足,长而多少带刺状的额。", "cites": [{"t": "虾,鱼名。又,虾虫多须而善游好跃。", "b": "《篇海类编》"}], "words": [{"w": "虾须镯", "t": "金丝编成的镯子"}, {"w": "虾杯", "t": "以海虾虾头与前两脚壳制成的杯子"}, {"w": "虾魁", "t": "即虾姑;指巨虾。"}]}, {"meaning": "像虾一样弯曲", "words": [{"w": "虾腰", "t": "行鞠躬礼"}, {"w": "虾朐", "t": "虾干。比喻貌丑而驼背的人"}]}, {"meaning": "满语对侍卫的称呼。", "cites": [{"t": "王辅臣勇冠三军,所向不当,号曰马鹞子……八王子以辅臣为虾,随入都。", "b": "清·刘献廷《广阳杂记》"}]}]}, {"pinyin": "há", "defs": [{"meaning": "同‘蛤蟆’", "words": [{"w": "虾蟆", "t": ""}, {"w": "虾蟆陵", "t": "在长安城东南,曲江附近,是唐代有名的游乐地区"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1499wx','蚁','1','yǐ','虫','9','','[{"pinyin": "yǐ", "defs": [{"meaning": "(形声。从虫,义声。本作“螘”。本义:蚂蚁)。"}, {"meaning": "膜翅类昆虫名。俗称蚂蚁。", "cites": [{"t": "羊肉不慕蚁,蚁慕羊肉,羊肉螘也。", "b": "《庄子》"}], "words": [{"w": "蚁附蝇趋", "t": "如蚁附膻,如蝇逐臭。意指攀附、奉承"}, {"w": "蚁聚蜂屯", "t": "像蚂蚁和蜜蜂一样杂乱地聚集在一起。"}]}, {"meaning": "玄色。", "cites": [{"t": "麻冕蚁裳。", "b": "《书》。郑玄注:“蚁谓色玄也。”"}], "words": [{"w": "蚁裳", "t": "玄色下衣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1500wx','思','1','sī sāi','心','9','','[{"pinyin": "sī", "defs": [{"meaning": "(会意兼形声。从心,从囟(xìn),囟亦声。囟脑子。古人认为心脑合作产生思想。本义:思考,想;考虑)。"}, {"meaning": "同本义。", "cites": [{"t": "思,容也。", "b": "《说文》"}, {"t": "思曰容,言心之所虑,无不包也。", "b": "《书·洪范》"}, {"t": "钦明文思安安。", "b": "《书·尧典》"}, {"t": "吾尝终日而思矣,不如须臾之所学也。", "b": "《荀子·劝学》"}, {"t": "学而不思则罔,思而不学则殆。", "b": "《论语·为政》"}, {"t": "老年人常思既往,少年人常思将来。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "多思;前思后想;自思;深思熟虑;思疑", "t": "疑惑;疑心"}, {"w": "思郁", "t": "思虑薀结"}, {"w": "思鲈", "t": "比喻抽身归隐"}, {"w": "思劳", "t": "思虑劳累"}, {"w": "思察", "t": "思虑辨察"}, {"w": "思算", "t": "思量盘算;考虑"}, {"w": "思忖", "t": "细细考虑,揣度"}, {"w": "思惟", "t": "思索;考虑"}, {"w": "思乎", "t": "方言。想,考虑"}, {"w": "思省", "t": "考虑;省察"}, {"w": "思度", "t": "考虑,思忖"}, {"w": "思酌", "t": "考虑斟酌"}, {"w": "思裁", "t": "忖度"}, {"w": "思摸", "t": "方言。忖度"}, {"w": "思辨", "t": "思考辨析"}, {"w": "思绎", "t": "思索寻求。"}]}, {"meaning": "思慕;想念。", "cites": [{"t": "家贫则思良妻,国乱则思良相。", "b": "《史记·魏世家》"}, {"t": "已行,非弗思也,祭祀必祝之。", "b": "《战国策·赵策》"}, {"t": "举头望明月,低头思故乡。", "b": "唐·李白《静夜思》"}, {"t": "羁鸟恋旧林,池鱼思故渊。", "b": "晋·陶渊明《归园田居》"}, {"t": "总揽英雄,思贤若渴。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "思慕宿宾", "t": "思念曾住在此地的人"}, {"w": "思功悼枉", "t": "怀念其功绩,伤悲其冤屈"}, {"w": "思忆", "t": "思念,想念"}, {"w": "思女", "t": "思念异性的女子"}, {"w": "思服", "t": "怀念"}, {"w": "思齐", "t": "思慕贤者的风范而效法之,使与之等齐"}, {"w": "思旧", "t": "思念旧友"}, {"w": "思治", "t": "想念治世"}, {"w": "思归", "t": "想望回故乡"}, {"w": "思怀", "t": "怀念"}, {"w": "思眷", "t": "眷念"}, {"w": "思企", "t": "旧时书信语,犹想念"}, {"w": "思顾", "t": "思念"}, {"w": "思亲", "t": "思念父母。亦泛指思念亲人"}, {"w": "思负", "t": "思念罪过"}, {"w": "思存", "t": "思念,念念不忘"}, {"w": "思土", "t": "思念故土"}, {"w": "思且", "t": "犹思存"}, {"w": "思渴", "t": "渴念"}, {"w": "思心", "t": "思恋爱慕之心"}, {"w": "思泳", "t": "思慕咏叹。"}]}, {"meaning": "悲伤,哀愁。", "cites": [{"t": "远望使心思,游子恋所生。", "b": "《乐府诗集·长歌行》"}, {"t": "仰清风以叹息,寄余思于悲絃。", "b": "三国魏·曹植《幽思赋》"}, {"t": "吉士思秋,实感物化。", "b": "晋·张华《励志诗》"}], "words": [{"w": "思秋", "t": "悲秋。"}]}, {"meaning": "思想,思绪,心情。亦指构思。", "cites": [{"t": "晻晻日欲瞑,愁思出门啼。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "弦弦掩抑声声思,似诉平生不得志。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "思功", "t": "苦思之功,创作中的苦心经营"}, {"w": "思力", "t": "思维能力"}, {"w": "思至", "t": "灵感到来,思想集中"}, {"w": "思覃", "t": "深思"}, {"w": "思致", "t": "指人的思想意趣或性情、才思"}, {"w": "思理", "t": "构思;思辨能力;思致,才思情致"}, {"w": "思综", "t": "才思"}, {"w": "思纬", "t": "才思学识"}, {"w": "思意", "t": "心思用意"}, {"w": "思士", "t": "思善感之士"}, {"w": "思事", "t": "心事"}, {"w": "乡思", "t": ""}]}, {"meaning": "特指创作的构思。", "cites": [{"t": "画思入神。", "b": "《新唐书》"}]}, {"meaning": "诉讼", "cites": [{"t": "思,司也。凡有所司捕必静思忖亦然也。", "b": "《释名》"}]}, {"meaning": "诗体的一种。", "cites": [{"t": "以思名者,太白有《静夜思》", "b": "宋·严羽《沧浪诗话》"}]}, {"meaning": "语气词。用于语首,无实义。", "cites": [{"t": "思乐泮水,薄采其芹。", "b": "《诗·鲁颂·泮水》"}]}, {"meaning": "用于句中,无实义。", "cites": [{"t": "兕觥其觩,旨酒思柔。", "b": "《诗·小雅·桑扈》"}]}]}, {"pinyin": "sāi", "defs": [{"meaning": "多胡须的样子", "words": [{"w": "于思", "t": "形容胡须很多。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1501wx','蚂','1','mā mǎ mà','虫','9','','[{"pinyin": "mā", "defs": [{"meaning": "[方言]∶蜻蜓", "words": [{"w": "蚂螂", "t": "‘蜻蜓’的俗称。"}]}]}, {"pinyin": "mǎ", "defs": [{"meaning": "[方言]∶水蛭", "words": [{"w": "蚂蟥", "t": "环节动物，身体长形，稍扁，黑绿色，尾端有吸盘。生活在池沼或水田中，吸食人畜的血液。"}]}, {"meaning": "蚁的通称", "words": [{"w": "蚂蚁", "t": "种类甚多,皆营巢群居,一般雌蚁、雄蚁有翅;工蚁、兵蚁无翅。某些种类对人类有害。"}]}]}, {"pinyin": "mà", "defs": [{"meaning": "[方言]∶蝗虫", "words": [{"w": "蚂蚱", "t": "‘蝗虫’的俗称。"}, {"w": "蚂蚱车子", "t": "独轮车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1502wx','虽','1','suī','虫','9','','[{"pinyin": "suī", "defs": [{"meaning": "(形声。从虫,唯声。古读 (huī)。本义:虫,似蜥蜴而大)。", "cites": [{"t": "秦兵旦暮渡易水,则虽欲长侍足下,岂可得哉?", "b": "《战国策·燕策》"}, {"t": "齐国虽褊小,吾何爱一牛!", "b": "《孟子·梁惠王上》"}], "words": [{"w": "虽故", "t": "虽然"}, {"w": "他虽身负重伤,但坚决不下火线", "t": ""}]}, {"meaning": "即使…也;纵使。", "cites": [{"t": "虽人有百口,手有百指,不能指其一端。", "b": "《虞初新志·秋声诗自序》"}, {"t": "先王之法,经手上世而来者也,人或益之,人或损之,胡可得而法?虽人弗损益,犹若不可得而法。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "仅,只。", "cites": [{"t": "虽有明君,能决之,又能塞之。", "b": "《管子》"}]}, {"meaning": "原本,本。", "cites": [{"t": "你那里休夸口,你虽是一人为害,我与那陈州百姓每分忧。", "b": "《陈州粜米》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1503wx','品','1','pǐn','口','9','','[{"pinyin": "pǐn", "defs": [{"meaning": "(会意,从三口。口代表人,三个表多数,意即众多的人。本义:众多)。"}, {"meaning": "同本义。", "cites": [{"t": "品,众庶也。", "b": "《说文》"}], "words": [{"w": "品人", "t": "众多的人"}, {"w": "品事", "t": "诸多事项"}, {"w": "品物", "t": "各类特定范围之物"}, {"w": "品供", "t": "各种供品"}, {"w": "品象", "t": "众人"}, {"w": "品庶", "t": "众人百姓"}, {"w": "品极", "t": "众多。"}]}, {"meaning": "齐一,相同。", "cites": [{"t": "品,齐也。", "b": "《广雅》"}, {"t": "品其百笾。", "b": "《国语·周语中》"}]}, {"meaning": "事物的种类。", "cites": [{"t": "五品不逊。", "b": "《虞书》。传,谓五常。郑注:父母兄弟子也。"}, {"t": "厥贡惟金三品。", "b": "《书·禹贡》"}, {"t": "果、肴非远方珍异,食非多品。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "货品", "t": "货物或货物的品种"}, {"w": "品汇", "t": "事物的品种类别"}, {"w": "品搭", "t": "按品类等级搭配"}, {"w": "品流", "t": "品类;流别"}, {"w": "品例", "t": "种类"}, {"w": "品件", "t": "花色品种"}, {"w": "用品", "t": "应用的物品"}, {"w": "珍品", "t": "珍贵的物品"}, {"w": "品物", "t": "物品;东西。"}]}, {"meaning": "等级。", "words": [{"w": "品从", "t": "等级"}, {"w": "上品", "t": ""}]}, {"meaning": "中国封建社会的一种官阶、爵阶。", "cites": [{"t": "皇上超擢品卿衔军机章京。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "品子", "t": "品官之子弟"}, {"w": "品次", "t": "位列;品级"}, {"w": "品制", "t": "等级制度"}, {"w": "品命", "t": "官阶;品位"}, {"w": "品著", "t": "指不同品位的服饰"}, {"w": "品从", "t": "正从。指古代官吏的正品与从品"}, {"w": "品爵", "t": "品级爵位"}, {"w": "品令", "t": "选拔官吏的格令。"}]}, {"meaning": "格调。", "cites": [{"t": "诗之品有九。", "b": "《沧浪诗话》"}]}, {"meaning": "法式, 法则。", "cites": [{"t": "乡有俗, 国有法。…品有所成, 故曰人不一事。", "b": "《管子》"}]}, {"meaning": "乐器构件名。指月琴、琵琶等乐器上的弦枕木。"}, {"meaning": "古地名 。唐宋皆有品州, 约在今四川省宜宾地区境内。"}, {"meaning": "评价,衡量。", "cites": [{"t": "于病中犹作《汉晋春秋》,品评卓逸。", "b": "《世说新语·文学》"}, {"t": "品其名位,犹不失下曹从事。", "b": "《资治通鉴》"}], "words": [{"w": "品度", "t": "品评打量"}, {"w": "品择", "t": "品评选择"}, {"w": "品藻", "t": "品评;评论"}, {"w": "品酌", "t": "衡量,斟酌"}, {"w": "品选", "t": "评选"}, {"w": "品头题足", "t": "亦作“品头论足”。指无聊的人随意议论妇女的容貌体态。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1504wx','咽','1','yān yàn yè','口','9','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从口,因声。本义:咽头)。"}, {"meaning": "同本义 消化和呼吸的通道,位于鼻腔、口腔的后方,喉的上方,相应地分为鼻咽、口咽和喉咽三部分。通称咽喉。", "cites": [{"t": "咽,嗌也。", "b": "《说文》。段注:“咽者,因也,言食因于是以上下也。”"}, {"t": "咽,又谓之嗌,气所流通,厄要之处也。", "b": "《释名》"}, {"t": "咽已绝。", "b": "《汉书·息夫躬传》。注:“喉咙。”"}, {"t": "佗尝行道,见有病咽塞者。", "b": "《后汉书·华佗传》"}, {"t": "吾恐秦人食之不得下咽也。", "b": "苏洵《六国论》"}], "words": [{"w": "咽吭", "t": "咽喉。喻指要害处"}, {"w": "咽塞", "t": "病名。喉咙梗塞,呼吸不畅。"}]}, {"meaning": "指颈项。", "cites": [{"t": "搤其咽。", "b": "《汉书·扬雄传》。注:“颈也。”"}], "words": [{"w": "咽项", "t": "指颈项"}, {"w": "咽颈", "t": "指脖子;头。"}]}, {"meaning": "比喻形势险要之地。", "cites": [{"t": "韩,天下之咽喉。", "b": "《战国策·秦策》"}], "words": [{"w": "咽颔", "t": "比喻形势险要之处。"}]}]}, {"pinyin": "yàn", "defs": [{"meaning": "吞入;吞食。", "cites": [{"t": "与旃毛并咽。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "细嚼慢咽;咽水", "t": "咽下口水"}, {"w": "咽苦吐甘", "t": "自己含辛茹苦,而给人以甘美。形容母爱之深。"}]}]}, {"pinyin": "yè", "defs": [{"meaning": "填塞;充塞。", "cites": [{"t": "云霞充咽,则夺日月之明。", "b": "汉·刘向《新序》"}, {"t": "乃饮坤大醉,投于井口,以垲石咽其井。", "b": "唐·裴鉶《传奇·姚坤》"}], "words": [{"w": "咽人", "t": "使人呼吸困难"}, {"w": "咽气", "t": "屏气。不敢喘息,形容惶恐紧张之状"}, {"w": "咽哽", "t": "泣不成声;气塞声断。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1505wx','骂','1','mà','马','9','','[{"pinyin": "mà", "defs": [{"meaning": "(形声。从吅&X({xuān}),马声。吅,喧闹声。本义:用粗语或恶意的话侮辱人)。"}, {"meaning": "同本义。", "cites": [{"t": "对子骂父。", "b": "《世说新语·方正》"}, {"t": "群怪聚骂。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "窃骂侯生。", "b": "《史记·魏公子列传》"}], "words": [{"w": "斥骂", "t": "责骂。用严厉的话责备"}, {"w": "咒骂", "t": "用恶毒的话骂"}, {"w": "笑骂", "t": "讥笑并辱骂"}, {"w": "辱骂", "t": "污辱谩骂。"}]}, {"meaning": "增益", "cites": [{"t": "商则长诈,工则饰骂。", "b": "《盐铁论》"}]}, {"meaning": "痛斥。", "cites": [{"t": "武骂律曰。", "b": "《汉书·李广苏建传》"}, {"t": "骂逆贼。", "b": "宋·文天祥《后序》"}, {"t": "应元骂曰。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "箕踞以骂。", "b": "《战国策·燕策》"}, {"t": "大骂而死。", "b": "清·全祖望《梅花岭记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1506wx','勋','1','xūn','力','9','','[{"pinyin": "xūn", "defs": [{"meaning": "(形声。小篆字作“勲”,从力,熏声。古文从力,员声。本义:特别大的功劳)。"}, {"meaning": "同本义。", "cites": [{"t": "勲,能成王功也。从力,熏声,古文員声。", "b": "《说文》"}, {"t": "勲,功也。", "b": "《尔雅》"}, {"t": "王功曰勲。", "b": "《周礼·司勲》"}, {"t": "圣有谟勲。", "b": "《左传·襄公二十一年》"}, {"t": "勋功有章。", "b": "《尹宙碑》"}, {"t": "追思嘉勋,实不可忘。", "b": "《三国志·郭嘉传》"}, {"t": "策勋十二转。", "b": "《乐府诗集·木兰诗》"}, {"t": "勋重于当世。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "古者人臣,功有五品,以德立宗庙定社稷曰勲。", "b": "《史记·高祖功臣侯者年表序》"}], "words": [{"w": "勋胤", "t": "功勋的后代"}, {"w": "勋垂竹帛", "t": "功勋载入史册,流传后世"}, {"w": "勋力", "t": "功劳"}, {"w": "勋旧", "t": "有功勋的故旧大臣。"}]}, {"meaning": "勋官。", "cites": [{"t": "郎中令,秦官,掌宫殿掖门户,有丞。武帝太初元年,更名光禄勋。", "b": "《汉书·百官公卿表序》"}], "words": [{"w": "勋卫", "t": "侍卫的官"}, {"w": "勋要", "t": "达贵显要"}, {"w": "勋附", "t": "帝王家族及近臣。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1507wx','哗','1','huá huā','口','9','','[{"pinyin": "huá", "defs": [{"meaning": "人声嘈杂,喧闹。", "cites": [{"t": "哗然而骇者。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "有辄哗笑之。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "无敢哗者。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "哗溃", "t": "喧闹中逃散"}, {"w": "哗釦", "t": "大声欢呼"}, {"w": "哗嚣", "t": "喧腾"}, {"w": "哗乱", "t": "群起作乱。"}, {"w": "哗变", "t": "军队突然叛变。"}]}, {"meaning": "形容很响的笑声的", "words": [{"w": "哗笑", "t": "众人放声大笑"}]}]}, {"pinyin": "huā", "defs": [{"meaning": "象声词", "words": [{"w": "铁门哗的一声拉上了;哗啷", "t": "象声词"}, {"w": "哗拉拉", "t": "哗喇喇,哗啦啦。象声词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1508wx','咱','1','zán','口','9','','[{"pinyin": "zán", "defs": [{"meaning": "(形声。从口,自声。本义:我)。"}, {"meaning": "同本义。", "cites": [{"t": "你若无意向咱行,为甚梦中频相见。", "b": "柳永《玉楼春》"}], "words": [{"w": "咱可", "t": "咱们;我们"}, {"w": "咱家", "t": "我"}, {"w": "咱每", "t": "咱们。指我。"}]}, {"meaning": "我们。"}, {"meaning": "称代对话者的双方。", "cites": [{"t": "不怕,你们把守住和他干,我给咱回村集合人去。", "b": "马烽《村仇》"}]}, {"meaning": "用在祈使句末,表示祈使语气,相当于“吧”。", "cites": [{"t": "走了一会,来到门首也。张二哥,咱进去咱。", "b": "《青衫泪》"}]}, {"meaning": "用在陈述句末,表示要做什么的语气。", "cites": [{"t": "当此夜深孤闷之时,我试理一曲消遣咱。", "b": "元·马致远《汉宫秋》"}]}, {"meaning": "——“早晚”两字的合音,用于:“这咱”,“那咱”,“多咱”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1509wx','响','1','xiǎng','口','9','','[{"pinyin": "xiǎng", "defs": [{"meaning": "(形声。从口,鄉声。本义:回声)。"}, {"meaning": "同本义。", "cites": [{"t": "響,声也。", "b": "《说文》"}, {"t": "炎光飞响。", "b": "《剧秦美新》"}, {"t": "黄玉响应。", "b": "《史晨奏铭》"}, {"t": "其受命也如响。", "b": "《易·系辞》"}, {"t": "空谷传响,哀转久绝。", "b": "《水经注·江水》"}, {"t": "云集响应。", "b": "汉·贾谊《过秦论上》"}, {"t": "绝无踪响。", "b": "《聊斋志异·促织》"}], "words": [{"w": "响臻", "t": "响应纷至"}, {"w": "响彻;响效", "t": "同响应。"}]}, {"meaning": "声音。", "cites": [{"t": "泠泠作响。", "b": "吴均《与朱元思书》"}, {"t": "歌台暖响。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "枹止响腾,余韵徐歇。", "b": "苏轼《石钟山记》"}, {"t": "群响毕绝。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "响丁丁", "t": "响泠泠。形容清脆的响声"}, {"w": "响卜", "t": "借听到声音来占卜吉凶"}, {"w": "响钞", "t": "指硬币。"}]}, {"meaning": "音讯。", "cites": [{"t": "(邓)艾得书,大喜,即报书。", "b": "《三国志》。裴松之注引《蜀书》:思闻嘉响。"}]}, {"meaning": "清晰地发出声音。", "cites": [{"t": "村北响缲车。", "b": "宋·苏轼《浣溪沙》词"}], "words": [{"w": "响榧子", "t": "以拇指与中指摩擦发出响声"}, {"w": "响鞭;门铃响了;大钟响了;响房", "t": "旧俗结婚日,喜轿出发前,先在新房前奏乐击鼓,称为响房。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1510wx','哈','1','hā hǎ hà','口','9','','[{"pinyin": "hā", "defs": [{"meaning": "(形声。从口,合声。(shà)本义:以唇啜饮。同“歃”)。"}, {"meaning": "口。", "cites": [{"t": "臾儿、易牙,淄渑之水合者,尝一哈水而甘苦知矣;故圣人之论贤也,见其一行而贤不肖分矣。", "b": "《淮南子·汜论训》"}]}, {"meaning": "笑声 ,表示得意或满意,大多叠用。", "cites": [{"t": "黄檗哈哈大笑。", "b": "道原《景德传灯录》"}]}, {"meaning": "鱼很多的样子。", "cites": [{"t": "哈,鱼多貌。", "b": "《玉篇》"}]}]}, {"pinyin": "hǎ", "defs": [{"meaning": "呵斥。", "cites": [{"t": "姐姐不用哈我,哈我我也是说。", "b": "《儿女英雄传》"}]}]}, {"pinyin": "hà", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1511wx','哆','1','duō','口','9','','[{"pinyin": "duō", "defs": [{"meaning": "形容敲击声。", "cites": [{"t": "张姑娘含着笑,皱着眉,把两只小脚儿点的脚踏儿哆哆的乱响。", "b": "《儿女英雄传》"}]}, {"meaning": "哆哆(喋喋。说话没完没了)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1512wx','咬','1','yǎo','口','9','','[{"pinyin": "yǎo", "defs": [{"meaning": "(形声。从口,交声。《说文》本从“齿”。本义:用牙齿把东西夹住或切断弄碎)。"}, {"meaning": "同本义。", "cites": [{"t": "易子而咬。", "b": "《汉书·食货志》引汉·贾谊《论积贮疏》"}], "words": [{"w": "咬姜呷醋", "t": "节约饮食用度"}, {"w": "咬牙关", "t": "形容痛恨、愤怒或发狠心"}, {"w": "咬瓦", "t": "比喻乏味"}, {"w": "咬定牙根", "t": "亦作“咬定牙关”。形容下定决心,坚忍不拔"}, {"w": "咬钉嚼铁", "t": "形容意志坚定,毫不动摇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1513wx','咳','1','hāi hái ké','口','9','','[{"pinyin": "hāi", "defs": [{"meaning": "叹息。", "cites": [{"t": "黛玉只“咳”了一声,眼中泪直流下来,回身便走。", "b": "《红楼梦》"}]}]}, {"pinyin": "hái", "defs": [{"meaning": "小儿笑。", "cites": [{"t": "咳,小儿笑也。从口,亥声。", "b": "《说文》"}]}, {"meaning": "阻隔。", "cites": [{"t": "颈尾咳于天地乎。", "b": "《晏子春秋》"}]}, {"meaning": "小儿。", "cites": [{"t": "曾不可以告咳婴之貌。", "b": "《史记·扁鹊列传》"}], "words": [{"w": "咳儿;咳咳", "t": "胎儿拳曲貌"}, {"w": "咳婴", "t": "指幼儿刚会笑尚需哺乳。"}]}]}, {"pinyin": "ké", "defs": [{"meaning": "(形声。从口,亥(hāi)声,①(hāi)本义:小儿笑。《史记·扁鹊传》:“曾不以告咳婴之儿。”(咳婴:刚会笑的婴儿) ②咳嗽 )。", "cites": [{"t": "有若老人咳且笑于山谷中者。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "咳唾", "t": "咳嗽吐唾液"}, {"w": "咳逆", "t": "咳嗽病的一种。因气逆而作咳"}, {"w": "咳珠吐玉", "t": "比喻措辞优美"}, {"w": "咳血", "t": "咳嗽咯血。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1514wx','咪','1','mī mǐ','口','9','','[{"pinyin": "mī", "defs": [{"meaning": "形容猫叫声或唤猫声"}, {"meaning": "微笑的样子"}]}, {"pinyin": "mǐ", "defs": [{"meaning": "法国长度单位“米突”的省称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1515wx','哪','1','nǎ na nǎi né něi','口','9','','[{"pinyin": "nǎ", "defs": [{"meaning": "(形声。从口,那声。本义:表疑问的词)。"}, {"meaning": "用于反问,表示肯定、否定或加强语气。", "cites": [{"t": "哪得自任专。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "恨恨哪可论", "b": ""}, {"t": "更哪堪冷落清秋节。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "又不是你的东西,哪能随便拿", "t": ""}]}]}, {"pinyin": "na", "defs": [{"meaning": "“啊”的变体 。表示惊叹、警诫或停顿。也作“那”、“嗱”。", "cites": [{"t": "那,语助。或从口,从奈。", "b": "《集韵》"}], "words": [{"w": "心里该有多甜哪!你要留神哪!看哪,禾苗长得多壮", "t": ""}]}]}, {"pinyin": "nǎi", "defs": [{"meaning": "", "words": [{"w": "哪个;哪天", "t": ""}]}]}, {"pinyin": "né", "defs": []}, {"pinyin": "něi", "defs": [{"meaning": "", "words": [{"w": "哪棵树?;哪帮人?", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1516wx','哟','1','yō yo','口','9','','[{"pinyin": "yō", "defs": [{"meaning": "表示轻微的惊异(有时带玩笑的语气)"}]}, {"pinyin": "yo", "defs": [{"meaning": "用在句尾表示祈使语气。"}, {"meaning": "用在歌词中做衬字。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1517wx','炭','1','tàn','火','9','','[{"pinyin": "tàn", "defs": [{"meaning": "(形声。从火,岸省声。本义:木炭)。"}, {"meaning": "同本义。", "cites": [{"t": "炭,烧木余也。", "b": "《说文》"}, {"t": "火所烧余木曰炭。", "b": "《释名》"}, {"t": "坐于涂炭。", "b": "《孟子》。注:“墨也。”"}, {"t": "可怜身上衣正单,心忧炭贱愿天寒。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "木炭;草炭;骨炭;活性炭;炭炉", "t": "烧木炭的炉子"}, {"w": "炭薪", "t": "柴炭"}, {"w": "炭精纸", "t": "一种涂有炭精供复写的纸"}, {"w": "炭笔", "t": "用细木枝烧焦或用炭粉制成的笔"}, {"w": "炭冰", "t": "炭热而冰冷。喻不能相容"}, {"w": "炭火", "t": "燃烧的炭。"}]}, {"meaning": "火。比喻灾难;困苦。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1518wx','峡','1','xiá','山','9','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从山,夹声。本义:两山夹水处)。"}, {"meaning": "同本义。", "cites": [{"t": "仿洋于山峡之旁。", "b": "《淮南子·原道》。注:“两山之间为峡。”"}, {"t": "峡里谁知有人事,世中遥望空云山。", "b": "王维《桃源行》"}, {"t": "仍下峡路。", "b": "《徐霞客游记·游黄山记》"}, {"t": "从峡度栈以上。", "b": ""}]}, {"meaning": "形容词。狭窄。", "cites": [{"t": "邃岸天高,空谷幽深,涧道之峡,车不方轨,号曰天险。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1519wx','罚','1','fá','罒','9','','[{"pinyin": "fá", "defs": [{"meaning": "(会意。小篆字,从刀,从詈(lì,骂人)。“刀”指刑法。本义:处罚,惩办)。"}, {"meaning": "同本义。", "cites": [{"t": "罰,罪之小者。从刀、从詈,会意。未以刀有所贼,但持刀骂詈则应罚。", "b": "《说文》"}, {"t": "罚上报下之罪也。", "b": "《墨子经》"}, {"t": "三让而罚。", "b": "《周礼·司救》。注:“挞击之也。”"}, {"t": "小刑宪罚。", "b": "《周礼·司市》。注:“播其肆也。”"}, {"t": "忠所罪以遇罚兮。", "b": "《楚辞·惜诵》"}, {"t": "陟罚臧否,不宜异同。", "b": "诸葛亮《出师表》"}, {"t": "皆不应重罚。", "b": "清·方苞《狱中杂记》"}, {"t": "罚所及则思无因怒而滥刑。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "罚规", "t": "处罚的规章"}, {"w": "罚约", "t": "输者受罚的约定"}, {"w": "罚弗及嗣", "t": "惩罚罪犯,但不延及子孙。"}]}, {"meaning": "对有过失、错误的处分。", "cites": [{"t": "如诗不成,罚依金谷酒数。", "b": "李白《春夜宴桃李园序》"}], "words": [{"w": "罚爵", "t": "宴饮时,罚失礼者喝酒的酒器。"}]}, {"meaning": "讨伐;杀。", "cites": [{"t": "致天之罚。", "b": "《书·汤誓》"}], "words": [{"w": "罚极", "t": "因有罪而加以诛杀"}, {"w": "罚罪", "t": "讨伐或惩处有罪者"}, {"w": "罚恶", "t": "惩治恶人"}, {"w": "罚蔽", "t": "罚罪断狱。"}]}, {"meaning": "出钱赎罪。", "cites": [{"t": "五刑不筒,正于五罚", "b": "《书·五刑》"}], "words": [{"w": "罚锾", "t": "纳金赎罪"}, {"w": "罚铜", "t": "纳铜罚罪"}, {"w": "罚赎", "t": "出钱赎罪"}, {"w": "罚俸", "t": "官吏因犯罪而停发薪俸。"}]}, {"meaning": "发誓。", "cites": [{"t": "不是我窦娥罚下这等无头愿,委实的冤情不浅。", "b": "元·关汉卿《窦娥冤》"}]}, {"meaning": "刑罚。", "cites": [{"t": "掌受士之金罚,货罚。", "b": "《周礼·职金》。注:“罚,罚赎也。”"}, {"t": "则好赏恶罚之人,释公行,行私求,比周以相为也。", "b": "《韩非子·有度》"}], "words": [{"w": "罚作", "t": "汉代刑罚之一。处轻罪犯以一年苦役"}, {"w": "罚神", "t": "传说主管刑罚之神。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1520wx','贱','1','jiàn','贝','9','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从贝,戋(qiān)声。本义:价格低)。"}, {"meaning": "同本义。", "cites": [{"t": "贱,买少也。", "b": "《说文》"}, {"t": "籴甚贵,伤民,甚贱伤农。", "b": "《汉书·食货志》"}, {"t": "心忧炭贱愿天寒。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "贱敛贵出", "t": "低价买入,高价售出"}, {"w": "贱酬", "t": "降价付钱"}, {"w": "贱发", "t": "降价发卖"}, {"w": "贱贸", "t": "低价出售"}, {"w": "贱售", "t": "贱卖。"}]}, {"meaning": "地位低下,人格卑鄙。", "cites": [{"t": "贱,卑也。", "b": "《广雅》"}, {"t": "以辨其贵贱老幼废疾。", "b": "《周礼·小司徒》"}, {"t": "贫与贱。", "b": "《论语》。皇疏:“无位曰贱。”"}, {"t": "相如素贱人。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "鄙贱之人。", "b": ""}, {"t": "无贵无贱。", "b": "唐·韩愈《师说》"}, {"t": "其辱人贱行,视五人之死,轻重固何如哉?", "b": "张溥《五人墓碑记》"}, {"t": "野夫贱隶。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "辱人贱行。", "b": "清·刘开《问说》"}], "words": [{"w": "贱族", "t": "卑微的家族"}, {"w": "贱业", "t": "卑微的职业"}, {"w": "贱丈夫", "t": "卑劣贪心的人"}, {"w": "贱伎", "t": "卑浅的技艺"}, {"w": "贱虫", "t": "卑贱的虫豸。用作詈词。"}]}, {"meaning": "自谦的用语。", "cites": [{"t": "贱子因阵败,归来寻旧蹊。", "b": "杜甫《无家别》"}], "words": [{"w": "贱役", "t": "指自己,谦称"}, {"w": "贱荆", "t": "同“贱内”。谦称自己的妻子"}, {"w": "贱造", "t": "谦称自己的生辰八字"}, {"w": "贱降", "t": "谦称自己的生日"}, {"w": "贱日穷见", "t": "自己生日时,杂务繁累。"}]}, {"meaning": "行为卑鄙、下流。", "cites": [{"t": "有贱丈夫焉,心求尤断而登之,以左右望而罔市利。", "b": "《孟子·丑孙丑下》"}], "words": [{"w": "贱相", "t": "令人鄙薄的言谈举止"}, {"w": "贱皮子", "t": "下贱的人。詈词"}, {"w": "贱事", "t": "轻贱之事"}, {"w": "贱伎", "t": "从事卑微技艺的人"}, {"w": "贱工", "t": "低贱的工作"}, {"w": "贱女人;贱类", "t": "下贱东西。詈词"}, {"w": "贱鄙", "t": "下贱卑鄙"}, {"w": "贱流", "t": "卑贱的人"}, {"w": "贱咧咧", "t": "方言。下贱不正派的样子"}, {"w": "贱材", "t": "骂人话。贱人"}, {"w": "贱才", "t": "骂女人的话"}, {"w": "贱种", "t": "卑贱的种族。詈词"}, {"w": "贱婢", "t": "对婢妾、娼优等女子的贬称。"}]}, {"meaning": "使其地位低下。", "cites": [{"t": "朕能生君,能杀君;能贵君,能贱君;能富君,能贫君。", "b": "《后汉书》"}]}, {"meaning": "鄙视,轻视。", "cites": [{"t": "是故明君贵五谷而贱金玉。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "轻贱;贱蔑", "t": "轻贱蔑视"}, {"w": "贱弃", "t": "鄙弃"}, {"w": "贱凌", "t": "轻慢欺凌"}, {"w": "贱侮", "t": "轻慢"}, {"w": "贱卑", "t": "轻视。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1521wx','贴','1','tiē','贝','9','','[{"pinyin": "tiē", "defs": [{"meaning": "(形声。从贝,占声。本义:典当)。"}, {"meaning": "同本义。", "cites": [{"t": "民日贴妇卖儿。", "b": "《聊斋志异·促织》"}], "words": [{"w": "贴钱", "t": "典钱;质钱"}, {"w": "贴典", "t": "典质;典押"}, {"w": "贴子", "t": "典押儿子。"}]}, {"meaning": "贴补。补偿,补益 。", "words": [{"w": "贴夫", "t": "供生活费的姘夫"}, {"w": "津贴;贴赠", "t": "要民补贴漕运亏损"}, {"w": "贴润", "t": "津贴;贴补"}, {"w": "贴赔", "t": "贴补赔偿"}, {"w": "贴截银", "t": "赠贴漕截的银两"}, {"w": "贴费", "t": "贴补耗费"}, {"w": "贴纳", "t": "贴补交纳。"}]}, {"meaning": "粘附;附着。", "cites": [{"t": "龙脊贴连钱,银蹄白踏烟。", "b": "李贺《马诗》"}, {"t": "无不平帖石上。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "贴落", "t": "室内四壁张或悬挂的字画等陈设"}, {"w": "贴边;贴花;剪贴资料;贴标语;贴在墙上;贴挂", "t": "张贴悬挂"}, {"w": "贴例", "t": "贴出的条例。"}]}, {"meaning": "切近,挨近。", "cites": [{"t": "穿花贴水益沾巾。", "b": "杜甫《燕子来舟中作》"}], "words": [{"w": "贴恋", "t": "怜惜,体贴"}, {"w": "贴怪", "t": "为男女搞不正当关系进行撮合"}, {"w": "体贴;贴身", "t": "泛指亲近的人"}, {"w": "贴心;贴衬", "t": "垫衬"}, {"w": "贴脸", "t": "脸和脸相贴"}, {"w": "贴靠", "t": "挨近;靠拢"}, {"w": "贴邻", "t": "近邻;隔壁邻居。"}]}, {"meaning": "不准入场。科举考试中,考生犯规被用蓝笔书其姓名、事故,贴出场门之外,不准入试。当时习惯简称“贴”。", "cites": [{"t": "出了场来,自道头一个就是他贴出,不许进二场了。", "b": "《初刻拍案惊奇》"}]}, {"meaning": "补偿费 。", "words": [{"w": "米贴;房贴", "t": ""}]}, {"meaning": "靶心。", "cites": [{"t": "射六箭皆上垛,内二箭中贴者。", "b": "《金史》"}]}, {"meaning": "适合,妥当 。", "words": [{"w": "贴妥", "t": "妥当、适当"}, {"w": "贴谱", "t": "合乎准则或实际"}, {"w": "贴调", "t": "合拍。不走调"}, {"w": "贴意", "t": "贴心,合意"}, {"w": "贴理", "t": "合乎情理。"}]}, {"meaning": "膏药的一张 。", "words": [{"w": "一贴膏药", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1522wx','贻','1','yí','贝','9','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从贝,台声。从“贝”,与财富有关。本义:赠送)。"}, {"meaning": "同本义。", "cites": [{"t": "贻我彤管。", "b": "《诗·邶风·静女》"}, {"t": "美人之贻。", "b": ""}, {"t": "余嘉其能行古道,作《师说》以贻之。", "b": "唐·韩愈《师说》"}, {"t": "尝贻余核舟一,盖大苏泛赤壁云。", "b": "明·魏学洢《核舟记》"}]}, {"meaning": "遗留。", "cites": [{"t": "贻我来牟。", "b": "《诗·周颂·思文》"}, {"t": "坐贻聋瞽。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "贻累", "t": "连累"}, {"w": "贻笑", "t": "诒笑。被人讥笑"}, {"w": "贻谋", "t": "留下的主意"}, {"w": "贻厥", "t": "贻:留;厥:其"}, {"w": "贻燕", "t": "给后世子孙留下安定的根基"}, {"w": "贻臭万年", "t": "恶名留传后世,万世难除。"}]}, {"meaning": "贻贝属或有关属的海产双壳类软体动物 ,通常有一个卵形或长形贝壳,具一黑色角质层并依动物分泌的细丝状足丝附着在基层。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1523wx','骨','1','gǔ gū','骨','9','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。从冎(guǎ),小篆象去掉肉的骨形,意思是“剐”。从肉,表示骨与肉相连。“骨”是汉字部首之一,从“骨”的字多与骨头和人体有关。本义:骨头)。"}, {"meaning": "同本义。", "cites": [{"t": "骨,肉之覈也。", "b": "《说文》"}, {"t": "骨者,髓之府。", "b": "《素问·脉要精微论》"}, {"t": "风生木与骨。", "b": "《管子·四时》"}, {"t": "马已死,买其骨五百金。", "b": "《战国策·燕策》"}, {"t": "以刀刺骨。", "b": "《韩非子·安危》"}, {"t": "而额焦烂不可辨,左膝以下筋骨尽脱矣。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "尸骨,尸首。指死去的人。", "cites": [{"t": "当时虽觭梦幻想,宁知此为归骨所耶?", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "骨殖;骨朽", "t": "死亡已久。"}]}, {"meaning": "人的品质、气概。", "cites": [{"t": "自是君身有仙骨,世人那得知其故?", "b": "唐·杜甫《送孔巢父发游江东兼呈李白》"}], "words": [{"w": "傲骨;媚骨;骨清", "t": "超凡脱俗,具有神仙资质"}, {"w": "骨格", "t": "品德;气度。"}]}, {"meaning": "比喻文学作品的刚健风格。", "cites": [{"t": "蓬莱文章建安骨,中间小谢又清发。", "b": "唐·李白《宣州谢朓楼饯别校书叔云》"}], "words": [{"w": "骨格", "t": "诗文的体式和风格"}, {"w": "风骨", "t": "诗文雄健有力的风格。"}]}, {"meaning": "比喻瘦劲的书体。", "cites": [{"t": "蔡邕书骨气洞达,爽爽有神。", "b": "唐·张彦远《法书要录》引南朝梁·袁昂《古今书评》"}], "words": [{"w": "骨力", "t": ""}]}]}, {"pinyin": "gū", "defs": [{"meaning": "尚未开放的花朵。"}, {"meaning": "表示声、形、动作。", "words": [{"w": "骨都都", "t": "形容连续不断向外冒"}, {"w": "骨骨农农", "t": "咕咕哝哝;嘀嘀咕咕"}, {"w": "骨辘辘", "t": "象声词。滚动声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1524wx','幽','1','yōu','幺','9','','[{"pinyin": "yōu", "defs": [{"meaning": "同本义。", "cites": [{"t": "幽,隐也。", "b": "《说文》。段注:“幽,从山,犹隐从阜,取遮蔽之意。”"}, {"t": "昆仑旁薄幽。", "b": "《太玄·中》。注:“隐也。”"}, {"t": "雍遏不通曰幽。", "b": "《周书·谥法》"}, {"t": "以致其幽。", "b": "唐·柳宗元《答韦中立论师道书》"}]}, {"meaning": "退隐;潜藏。", "cites": [{"t": "幽居而不淫。", "b": "《礼记》"}, {"t": "南阳之弊幽。", "b": "《战国策》"}], "words": [{"w": "幽隐", "t": "隐居的贤才"}, {"w": "幽士", "t": "幽子,幽人。幽隐之人;隐士"}, {"w": "幽女", "t": "隐居无偶的女子。"}]}, {"meaning": "囚禁。", "cites": [{"t": "公侯失礼则幽。", "b": "《荀子·王霸》。杨倞注:“幽,囚也。”"}, {"t": "栾书中行偃劫而幽之。", "b": "《吕氏春秋·骄恣》"}, {"t": "乃幽武。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "幽困", "t": "囚禁"}, {"w": "幽杀", "t": "拘禁杀害"}, {"w": "幽死", "t": "囚禁而死"}, {"w": "幽劫", "t": "遭囚禁,被胁制"}, {"w": "幽杀", "t": "囚禁处死"}, {"w": "幽废", "t": "幽禁废黜。"}]}, {"meaning": "昏暗;阴暗。", "cites": [{"t": "幽,微也。", "b": "《尔雅》"}, {"t": "幽,冥也。", "b": "《小尔雅》"}, {"t": "幽明之占。", "b": "《史记·五帝纪》"}, {"t": "方世俗之幽昏兮。", "b": "《楚辞·惜誓》"}, {"t": "水府幽深。", "b": "唐·李朝威《柳毅传》"}, {"t": "凄神寒骨,悄怆幽邃。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "至于幽暗昏惑而无物以相之,亦不能至也。", "b": "宋·王安石《游褒禅山记》"}, {"t": "幽晦以多雨。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "幽岩", "t": "深暗的岩洞"}, {"w": "幽房", "t": "深暗的房间"}, {"w": "幽室", "t": "幽暗或没有光亮的房子"}, {"w": "幽隐", "t": "幽暗不明"}, {"w": "幽国", "t": "政治昏暗的国家"}, {"w": "幽暮", "t": "昏暗的傍晚"}, {"w": "幽昧", "t": "昏暗不明。"}]}, {"meaning": "深邃。", "cites": [{"t": "幽,深也。", "b": "《尔雅》"}, {"t": "入于幽谷。", "b": "《易·困》"}, {"t": "幽幽南山。", "b": "《诗·小雅·斯干》。传:“幽幽,深远也。”"}, {"t": "出自幽谷,迁于乔木。", "b": "《诗·小雅·伐木》"}], "words": [{"w": "幽闺弱质", "t": "闺阁中的弱女子"}, {"w": "幽扃", "t": "深锁的门"}, {"w": "幽谷", "t": "深谷"}, {"w": "幽冤", "t": "深冤"}, {"w": "幽闺", "t": "深闺。指旧时女子的卧房"}, {"w": "幽情", "t": "深远或高雅的情思。"}]}, {"meaning": "幽静。", "cites": [{"t": "幽独处乎山中。", "b": "《楚辞·屈原·涉江》"}, {"t": "青云动高兴,幽事亦可悦。", "b": "杜甫《北征》"}], "words": [{"w": "幽轩", "t": "幽静有窗的小室"}, {"w": "幽真", "t": "幽静纯真的情趣"}, {"w": "幽娟", "t": "幽静美好"}, {"w": "幽敞", "t": "幽静宽敞"}, {"w": "幽偏", "t": "静僻之处"}, {"w": "幽坞", "t": "僻静的山坳"}, {"w": "幽隅", "t": "僻静处"}, {"w": "幽栖", "t": "幽僻的栖止之处。"}]}, {"meaning": "幽雅。", "cites": [{"t": "幽赏未已,高谈转清。", "b": "李白《春夜宴桃李园序》"}], "words": [{"w": "幽妍", "t": "清秀"}, {"w": "幽秀", "t": "幽雅秀丽"}, {"w": "幽姿", "t": "幽雅的姿态"}, {"w": "幽致", "t": "幽雅别致。"}]}, {"meaning": "(yǒu)。黑色。", "cites": [{"t": "其桑有幽。", "b": "《诗·小雅·隰桑》"}, {"t": "再命赤靶幽衡。", "b": "《礼记·玉藻》。毛传:“幽,黑色也。”"}]}, {"meaning": "幽静隐蔽的地方。", "cites": [{"t": "虎豹得幽,而威可载也。", "b": "《管子》"}]}, {"meaning": "阴间。", "cites": [{"t": "九幽十八狱,无此黑暗也。", "b": "《聊斋志异》"}], "words": [{"w": "幽冥界", "t": "阴曹地府"}, {"w": "幽孽", "t": "人死后在阴间所受的苦难"}, {"w": "幽神", "t": "鬼神"}, {"w": "幽阴", "t": "阴间。"}]}, {"meaning": "幽州。", "cites": [{"t": "东北曰幽州。", "b": "《周礼·职方式》"}, {"t": "燕曰幽州。", "b": "《尔雅》"}, {"t": "幽州在北,幽昧之地也。", "b": "《释名·释州国》"}]}, {"meaning": "古地名。"}, {"meaning": "在今河北省北部及辽宁等地。"}, {"meaning": "在今北京市及所属通县、房山及河北省武清、永清、安次等县境内。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1525wx','钙','1','gài','钅','9','','[{"pinyin": "gài", "defs": [{"meaning": "一种金属元素，银白色结晶，有延展性。它的化合物在工业上、建筑工程上和医药上用途很大。", "words": [{"w": "缺钙", "t": ""}, {"w": "钙化", "t": "病理学上指局部组织中的钙盐沉积,常见于骨骼成长的早期阶段,亦见于某些病理情况下。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1526wx','钝','1','dùn','钅','9','','[{"pinyin": "dùn", "defs": [{"meaning": "(形声。从金,屯声。本义:不锋利)。"}, {"meaning": "同本义。", "cites": [{"t": "兵不钝锋。", "b": "《文选·檄吴将校部曲》"}, {"t": "庶竭驽钝。", "b": "诸葛亮《出师表》"}], "words": [{"w": "钝刀", "t": "钝兵。不锋利的兵刃。"}]}, {"meaning": "呆;笨拙。", "cites": [{"t": "钝,迟也。", "b": "《广雅·释诂四》"}, {"t": "俗谓愚为钝椎。", "b": "《史记·周勃世家》注"}, {"t": "其刚心勇气消耗钝眊(衰颓)。", "b": "宋·苏轼《教战守策》"}], "words": [{"w": "钝愚", "t": "愚笨;迟钝"}, {"w": "钝货", "t": "蠢货,笨蛋"}, {"w": "钝皮老脸", "t": "厚脸皮"}, {"w": "钝兵", "t": "士气不壮盛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1527wx','钞','1','chāo','钅','9','','[{"pinyin": "chāo", "defs": [{"meaning": "掠取;抢掠", "cites": [{"t": "钞,叉取也。从金,少声。", "b": "《说文》。俗字作抄。"}, {"t": "遮取谓之抄掠。", "b": "《通俗文》"}, {"t": "攻钞郡县。", "b": "《后汉书·公孙瓒传》"}], "words": [{"w": "钞掠", "t": "劫掠骚扰;劫夺他人财物。"}]}, {"meaning": "誊写。也作“抄”。", "cites": [{"t": "溥幼嗜学,所读书必手钞。", "b": "《明史·张溥传》"}], "words": [{"w": "钞白", "t": "抄录的公文副本"}, {"w": "钞胥", "t": "担任誊录钞写工作的小吏。也作“抄胥”。"}]}, {"meaning": "纸币名。现在称纸币为钞票,简称钞。", "cites": [{"t": "递制交钞,与钱并用。", "b": "《金史·食货志三》"}], "words": [{"w": "外钞", "t": "外国的钞票"}, {"w": "冥钞", "t": "迷信人给死人烧的假钞票,有些地方叫纸钱。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1528wx','钟','1','zhōng','钅','9','','[{"pinyin": "zhōng", "defs": [{"meaning": "(形声。左形,右声。鐘:本义:古代打击乐器,青铜制)。"}, {"meaning": "同本义。", "cites": [{"t": "钟,乐钟也。", "b": "《说文》。杨树达曰:“钟者,可捶之物。”"}, {"t": "钟,铃也。", "b": "《广雅·释器》"}, {"t": "垂之和钟。", "b": "《礼记·明堂位》"}, {"t": "钟音之器也。", "b": "《左传·昭公二十一年》"}, {"t": "大钟鼎。", "b": "《淮南子·本经》"}, {"t": "细钧有乐,钟兑音也。", "b": "《国语·周语》"}, {"t": "声如洪钟。", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "又。", "cites": [{"t": "钟磬置水中。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "独以此钟名。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "如钟鼓不绝。", "b": ""}], "words": [{"w": "钟磬", "t": "两种古代乐器"}, {"w": "钟鼎之家", "t": "宴享时列鼎、击钟奏乐的古代贵族家庭"}, {"w": "钟石", "t": "指乐器中的钟和磬"}, {"w": "钟板", "t": "钟和云板"}, {"w": "钟乳", "t": "古钟面隆起的饰物。在钟带间,形似乳,故叫钟乳"}, {"w": "钟室", "t": "悬钟之室"}, {"w": "钟师", "t": "古官名。掌击钟奏乐"}, {"w": "钟鼓", "t": "钟和鼓,两种乐器名。指演奏音乐"}, {"w": "钟吕", "t": "乐钟"}, {"w": "钟鼎", "t": "钟和鼎。上面多铭刻记事表功的文字"}, {"w": "钟鼓之色", "t": "欢欣喜乐的面色"}, {"w": "钟铭", "t": "钟上的铭文。"}]}, {"meaning": "专指佛寺悬挂的钟 。用以作报时、报警、集合的信号。", "cites": [{"t": "姑苏城外寒山寺,夜半钟声到客船。", "b": "唐·张继《枫桥夜泊》"}], "words": [{"w": "钟定", "t": "寺庙在一日既终以后,钟声止息不再敲打"}, {"w": "钟鱼", "t": "形同鲸鱼的撞钟大木"}, {"w": "钟梵", "t": "寺院的钟声和诵经声。"}]}, {"meaning": "泛指一般报时的钟。", "cites": [{"t": "来是空言去绝踪,月斜楼上五更钟。", "b": "唐·李商隐《无题》"}], "words": [{"w": "时钟;石英钟;警钟;挂钟;摆钟;钟漏", "t": "古代报时的漏刻和钟声。"}]}, {"meaning": "(形声。从金,重声。本义: 古时盛酒的器皿。现也称“盅”)。"}, {"meaning": "同本义。", "cites": [{"t": "锺,酒器也。", "b": "《说文》"}, {"t": "受同异同。", "b": "《书·顾命》。按,皆以同为(锺)之。段氏谓古贮酒大器,自锺而注入尊。"}, {"t": "尧舜千钟,孔子百觚。", "b": "《孔从子·儒服》"}, {"t": "有玻璃钟。", "b": "《晋书·崔洪传》"}, {"t": "小龙接过壶来,将酒斟在他盏中,酒比钟高出三五分来,更不漫出。", "b": "《西游记》"}]}, {"meaning": "大酒杯。", "cites": [{"t": "琉璃钟,琥珀浓。", "b": "李贺《将进酒》"}, {"t": "二间夹锺。", "b": "《礼记·明堂位》"}, {"t": "二间夹锺。", "b": "《国语·周语》"}]}, {"meaning": "酒杯、茶杯,与“盅”通。", "cites": [{"t": "尧舜千钟。", "b": "《孔丛子·儒服》"}, {"t": "胡饮后,到酒一举三钟。", "b": "五代·王定保《唐摭言》"}]}, {"meaning": "古容量单位 ,春秋时齐国公室的公量,合六斛四斗。之后亦有合八斛及十斛之制。", "cites": [{"t": "齐旧四量:豆、区、釜、钟…釜十则钟。", "b": "《左传·昭公三年》"}], "words": [{"w": "钟石", "t": "容量单位。一钟受六斛四斗,一石受十斗"}, {"w": "钟庾", "t": "钟和庾。两种容量单位"}, {"w": "钟斛", "t": "钟和斛。两种古容量单位。"}]}, {"meaning": "集聚。", "cites": [{"t": "泽,水之钟也。", "b": "《国语·周语》"}], "words": [{"w": "钟萃", "t": "汇集"}, {"w": "钟聚", "t": "汇集,集聚"}, {"w": "钟泄", "t": "蓄洪和放水"}, {"w": "钟美", "t": "集美"}, {"w": "钟秀", "t": "聚集灵秀之气。"}]}, {"meaning": "介词。适逢,当。", "cites": [{"t": "方今钟百王之季,当阳九之会。", "b": "刘越石《劝进表》"}], "words": [{"w": "钟祸", "t": "惹祸,遭祸"}, {"w": "钟值", "t": "遭逢。"}]}, {"meaning": "寄托。", "cites": [{"t": "经危履险阻,未知命所钟。", "b": "《磐石篇》"}], "words": [{"w": "钟心", "t": "钟情,感情专注"}, {"w": "钟念", "t": "钟爱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1529wx','钢','1','gāng gàng','钅','9','','[{"pinyin": "gāng", "defs": [{"meaning": "铁和碳的合金。经过精炼，不含磷砂等杂质的铁，含碳0.15钢1.7％，比熟铁更坚硬更富于弹性，是工业上极其重要的原料。", "words": [{"w": "钢版", "t": "幅宽较大的板状钢材。"}, {"w": "钢版", "t": "文具名。"}, {"w": "钢版", "t": "指钢质的版片,表面粗糙有细点纹,置于蜡纸下,以针形钢笔在纸上书写,即现透明的笔迹,用以油印。或指钢质电镌的印刷底版,可使文字花纹极细密,多用于印刷票据。"}, {"w": "钢版", "t": "指钢质电镌的印刷底版,可使文字花纹极细密,多用于印刷票据。"}]}]}, {"pinyin": "gàng", "defs": [{"meaning": "把刀在布、皮、石、或缸沿上用力摩擦几下，使锋利些", "words": [{"w": "钢菜刀", "t": ""}]}, {"meaning": "在刀口上加点儿钢，重新打造，使更锋利"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1530wx','钠','1','nà','钅','9','','[{"pinyin": "nà", "defs": [{"meaning": "一种银白色的软的、蜡状而有延展性的金属元素,原子序数11,其化学性质很活泼,用在钠蒸气灯中,尤其在内燃机用的致冷阀中作为一种传热剂 ——元素符号Na。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1531wx','钥','1','yào yuè','钅','9','','[{"pinyin": "yào", "defs": [{"meaning": "门直闩。上穿横闩下插地上的直木。", "cites": [{"t": "户钥,自关而东,陈、楚之间谓之键,自关而西谓之钥。", "b": "《方言》"}]}, {"meaning": "枢要,重要之处。", "cites": [{"t": "又半里,有村在山北之麓,其名曰金村,乃是站之当钥者。", "b": "《徐霞客游记》"}]}, {"meaning": "钥匙。", "cites": [{"t": "钥,锁匙。", "b": "《增补五方元音·驼韵》"}, {"t": "质明启钥。", "b": "清·方苞《狱中杂记》"}, {"t": "无钥,可令铜匠铦开。", "b": "章炳麟《致伯中书》"}], "words": [{"w": "钥牡", "t": "开锁的工具。即钥匙"}, {"w": "钥锔", "t": "钥匙。"}]}, {"meaning": "指锁。", "cites": [{"t": "每夜必手自关门下钥,其钥为外洋上等货,且钥匙仅有一枚,甲自佩之。至明晨,始手自启钥。", "b": "《俏皮话·性命没了钱还可以到手》"}]}, {"meaning": "姓。"}]}, {"pinyin": "yuè", "defs": [{"meaning": "钥匙,开锁的工具。", "cites": [{"t": "银钥开香阁,金台照夜灯。", "b": "《全唐诗》"}], "words": [{"w": "锁钥", "t": ""}]}, {"meaning": "门直闩。上穿横闩下插地上的直木。", "cites": [{"t": "户钥,自关而东,陈、楚之间谓之键,自关而西谓之钥。", "b": "《方言》"}]}, {"meaning": "锁闭。", "cites": [{"t": "嗜欲之萌,耳目可关,而心意可钥。", "b": "《新论》"}]}, {"meaning": "入。", "cites": [{"t": "排阊阖,钥天门。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1532wx','钦','1','qīn','钅','9','','[{"pinyin": "qīn", "defs": [{"meaning": "(形声。从欠,金声。欠,打呵欠,张口舒气。本义:打呵欠的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "钦,欠貌。", "b": "《说文》。段玉裁注:“凡气不足而后欠,钦者,倦而张口之貌也。”"}, {"t": "燮生而钦颐折頞,丑状骇人。", "b": "《后汉书·周燮传》"}, {"t": "开弓发矢,要钦身向外。", "b": "唐·王琚《射经》"}]}, {"meaning": "敬佩;恭敬。", "cites": [{"t": "钦,敬也。", "b": "《尔雅》"}, {"t": "钦有帅。", "b": "《礼记·内则》。注:“敬也。”"}, {"t": "钦,戴氏侗曰:“屏气钦敛之貌,引之为钦敬。", "b": "《说文解字注笺》"}, {"t": "钦念以忱。", "b": "《书·盘庚》"}, {"t": "钦明文,思安安。", "b": "《书·尧典》"}, {"t": "洛邑之内,无不钦敬。", "b": "陆云《与陆典书》"}], "words": [{"w": "钦年", "t": "敬重年长者"}, {"w": "钦奉", "t": "敬奉"}, {"w": "钦若", "t": "敬顺"}, {"w": "钦和", "t": "敬从,敬奉"}, {"w": "钦承", "t": "恭敬地续承或承受"}, {"w": "钦崇", "t": "崇敬"}, {"w": "钦率", "t": "敬遵"}, {"w": "钦隆", "t": "崇敬"}, {"w": "钦心", "t": "敬佩"}, {"w": "钦伏", "t": "敬服"}, {"w": "钦信", "t": "敬佩,信服"}, {"w": "钦挹", "t": "钦佩推崇。"}]}, {"meaning": "假借为“吟”。叹息。", "cites": [{"t": "其音如钦。", "b": "《山海经·东山经》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1533wx','钧','1','jūn','钅','9','','[{"pinyin": "jūn", "defs": [{"meaning": "(形声。从金,匀声。本义:古代重量单位。三十斤为一钧)。"}, {"meaning": "同本义。", "cites": [{"t": "钧,三十斤也。", "b": "《说文》"}, {"t": "入钧金。", "b": "《周礼·大司寇》"}, {"t": "钧衡石。", "b": "《礼记·月令》"}, {"t": "颜高之弓六钧。", "b": "《左传·定公八年》"}, {"t": "吾力足以举百钧。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "钧衡", "t": "钧和衡都是量物的工具,因借为评量人才之意"}, {"w": "千钧一发;雷霆万钧;钧石", "t": "钧和石。四钧为石"}, {"w": "钧金", "t": "三十斤铜"}, {"w": "钧分", "t": "一钧半,合四十五斤。"}]}, {"meaning": "制陶器所用的转轮。", "cites": [{"t": "独化于陶钧之上。", "b": "《史记·邹阳传》。索隐:“范也。”"}, {"t": "陶家名模下圆转者为钧。", "b": "《汉书》注"}, {"t": "大钧播物。", "b": "《汉书·贾谊传》"}, {"t": "钧旋毂转。", "b": "《淮南子·原道》"}], "words": [{"w": "钧甄", "t": "钧和甄。都是制陶用的转轮。"}]}, {"meaning": "相同;相等;均衡;均匀。", "cites": [{"t": "其罪惟钧。", "b": "《书·吕刑》"}, {"t": "敦弓既坚,四鍭既钧。", "b": "《诗·大雅·行苇》"}, {"t": "钧是人也。", "b": "《孟子·告子上》"}, {"t": "是以圣人和之以是非,而休乎天钧。", "b": "《庄子·齐物论》"}, {"t": "善均从众。", "b": "《左传·成公六年》"}, {"t": "钧则曰左右均。", "b": "《礼记·投壶》注:“等也。”"}, {"t": "夫名异则实殊,质同则称钧。", "b": "《论衡·实知》"}], "words": [{"w": "钧平", "t": "均等,相等"}, {"w": "钧等", "t": "均等"}, {"w": "钧德", "t": "功德相同"}, {"w": "钧谐", "t": "均衡和谐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1534wx','钩','1','gōu','钅','9','','[{"pinyin": "gōu", "defs": [{"meaning": "(会意。从金,从句,句亦声。“句”(gōu),弯曲。也具有表意作用。本义:衣带上的钩。引申为“ 钓鱼或挂物用的钩”)。"}, {"meaning": "形状弯曲,用于探取、悬挂器物的用品。可分为钓钩、挂钩、带钩等。", "cites": [{"t": "鉤,曲也。", "b": "《说文》。韵会引作“曲鉤也。”"}, {"t": "鉤,曲也,所以鉤悬物也。", "b": "《玉篇》"}, {"t": "金路鉤。", "b": "《周礼·春官·巾车》"}, {"t": "申孙之矢,集于桓鉤。", "b": "《国语·晋语》。注:“带鉤也。”"}, {"t": "岂谓一鉤金。", "b": "《孟子》"}, {"t": "窃鉤者诛。", "b": "《庄子·胠箧》"}, {"t": "以尔鉤援。", "b": "《诗·大雅·皇矣》。传:“鉤梯也,所以引上城者。”"}, {"t": "作刀剑鉤鐔。", "b": "《汉书·韩延寿传》。注:“兵器也。”"}]}, {"meaning": "镰刀。", "cites": [{"t": "木钩而樵。", "b": "《淮南子》。高诱注:“钩,镰也。”"}]}, {"meaning": "中国古代兵器名,似剑而曲。", "cites": [{"t": "少年别有赠,含笑看吴钩。", "b": "唐·杜甫《后出塞五首》之一"}], "words": [{"w": "钩镰刀", "t": "兵器。"}]}, {"meaning": "汉字的一种笔画名 。"}, {"meaning": "钩取;钩住。", "cites": [{"t": "鉤,取也。", "b": "《小尔雅》"}, {"t": "引鉤箝之辞。", "b": "《鬼谷子·飞箝》"}, {"t": "鉤人枉而出直。", "b": "《管子·宙合》"}, {"t": "把掉在井里的桶钩上来", "b": ""}]}, {"meaning": "引申为逮捕,捉取。", "cites": [{"t": "十四司正副郎好事者,及书吏、狱官、禁卒,皆利系者之多,少有连,必多方钩致。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "从洞里钩鳝鱼;用脚钩绳子;钩颈", "t": "用兵器在颈部钩割首级。"}]}, {"meaning": "探索,探讨。", "cites": [{"t": "记事者必提其要,纂言者必钩其玄。", "b": "唐·韩愈《进学解》"}], "words": [{"w": "钩玄", "t": "探取奥义"}, {"w": "钩沈", "t": "探求幽深的意旨"}, {"w": "钩抉", "t": "探取抉择"}, {"w": "钩校", "t": "探索实情,加以考核"}, {"w": "钩摭", "t": "探求选取。"}]}, {"meaning": "牵连。", "cites": [{"t": "“且矫诏纷出,钩党之捕遍于天下,卒以吾郡之发愤一击,不敢复有株治。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "钩逮", "t": "牵累"}, {"w": "钩婴", "t": "牵连缠绕"}, {"w": "钩党", "t": "互有牵连的同党。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1535wx','钮','1','niǔ','钅','9','','[{"pinyin": "niǔ", "defs": [{"meaning": "(形声。从金,丑声。本义:印鼻,即印把子)。"}, {"meaning": "同本义。", "cites": [{"t": "钮,印鼻也。", "b": "《说文》"}, {"t": "龟纽(钮)之玺。", "b": "《淮南子·说林》。注:“纽系佩服也。”"}, {"t": "诸王金玺龟钮。", "b": "《晋书·舆服志》"}], "words": [{"w": "环钮;狮钮;虎钮;瓦钮", "t": ""}]}, {"meaning": "器物上面可以提携或系绳带的部分。", "cites": [{"t": "妙墨新题森锁钮。", "b": "宋·范成大《知郡安抚》"}]}, {"meaning": "扣。", "cites": [{"t": "来不及钮扣子。", "b": "《官场现形记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1536wx','卸','1','xiè','卩','9','','[{"pinyin": "xiè", "defs": [{"meaning": "(会意。从卩,从止,从午。卩(jié),像人形;止,息止;午,指马。合起来表示停车解马。本义:解马卸车)。"}, {"meaning": "同本义。", "cites": [{"t": "卸,舍车解马也。", "b": "《说文》"}, {"t": "卸,卸马去鞍。", "b": "《广韵》"}, {"t": "空烦卸马鞍。", "b": "杜甫《携酒高亦同过用寒字》"}], "words": [{"w": "卸车;卸鞍", "t": ""}]}, {"meaning": "解除;解下。亦指褪下;脱下。", "cites": [{"t": "你快卸了装束,归顺天恩。", "b": "《西游记》"}, {"t": "功高马卸黄金甲。", "b": "唐·黄滔《李相公》"}], "words": [{"w": "卸剥", "t": "脱"}, {"w": "卸头", "t": "妇女卸去头上的装饰"}, {"w": "卸除", "t": "解除,拆除。"}]}, {"meaning": "凋谢。", "cites": [{"t": "寿星台上,有千年不卸的名花。", "b": "《西游记》"}, {"t": "月光昏,隔水人断孤村;深巷小,黄叶纷纷都卸。", "b": "清·史震林《西青散记》"}]}, {"meaning": "倒塌。", "cites": [{"t": "把身子往后一挣,那垛看墙就拉拉杂杂卸下半堵。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1537wx','缸','1','gāng','缶','9','','[{"pinyin": "gāng", "defs": [{"meaning": "(形声。从缶(fǒu),表示与瓦器有关,工声。(hāng)本义:瓦制长颈容器,可受十升)。"}, {"meaning": "大口而常无颈的陶器。", "cites": [{"t": "醯酱千缸。", "b": "《史记·货殖列传》"}], "words": [{"w": "水缸;缸砚", "t": "用酒缸碎片制成的砚台"}, {"w": "缸面酒", "t": "用缸酿制的酒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1538wx','拜','1','bài','手','9','','[{"pinyin": "bài", "defs": [{"meaning": "(会意。从两手,从下。《说文》古文上象两手,丅为“下”的古体。《说文》引扬雄说:“拜从两手下。”表示双手作揖,或下拜。隶书将“丅”(下)并入右边的“手”之下而成为“拜”,一直沿用至今。本义:古代表示敬意的一种礼节。两手合于胸前,头低到手)。"}, {"meaning": "同本义。", "cites": [{"t": "拜手,稽手。", "b": "《书·召诰》。传:“拜首,首至手。”"}, {"t": "拜,服也。", "b": "《礼记·郊特性》"}, {"t": "平衡曰拜。", "b": "《荀子·大略》"}, {"t": "乐工等罗列上前,连拜且泣。", "b": "宋·王傥《唐语林·雅量》"}, {"t": "拜送书于庭。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "后世指下跪叩头。两腿跪地,两手扶地,低头。后又作为行礼的通称。", "cites": [{"t": "则又再拜,又故迟不起,起则五六揖,始出。", "b": "宗臣《报刘一丈书》"}], "words": [{"w": "纳头四拜;拜了又拜;拜菩萨;拜天地;拜父母", "t": ""}]}, {"meaning": "拜谢。行拜礼表示感谢。", "cites": [{"t": "三年将拜君赐。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "拜恩", "t": "拜谢恩赐"}, {"w": "拜盟", "t": "拜谢结盟。"}]}, {"meaning": "拜见;拜谒。", "cites": [{"t": "则往拜其门。", "b": "《孟子·滕文公下》"}, {"t": "孔子时其亡也,而往拜之。", "b": "《论语·阳货》"}, {"t": "肃拜蒙母,结友而别。", "b": "《资治通鉴·汉纪》"}], "words": [{"w": "拜见", "t": "谒见尊长"}, {"w": "拜亲", "t": "拜见朋友的父母。"}]}, {"meaning": "授与官职;任命。", "cites": [{"t": "拜相如为上大夫。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "公车特征拜郎中。", "b": "《后汉书·张衡传》"}]}, {"meaning": "接受官职;上任。", "cites": [{"t": "于是辞相印不拜。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "拜石", "t": "拜受俸禄"}, {"w": "拜邑", "t": "拜受邑宰。"}]}, {"meaning": "上;献。", "cites": [{"t": "谨拜表以闻。", "b": "李密《陈情表》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1539wx','看','1','kān kàn','目','9','','[{"pinyin": "kān", "defs": [{"meaning": "守护。", "cites": [{"t": "原是一个老军看管。", "b": "《水浒全传》"}], "words": [{"w": "看坡", "t": "守护庄稼"}, {"w": "看陵", "t": "看守皇帝陵墓"}, {"w": "看养", "t": "守护,照料"}, {"w": "看钱奴", "t": "守财奴"}, {"w": "看鸡", "t": "孵鸡"}, {"w": "看肚兜铜钱", "t": "仅有的几个钱"}, {"w": "看坟的打抽丰", "t": "歇后语。吃鬼;向鬼索取财物。比喻极为刻薄,吝啬。"}]}]}, {"pinyin": "kàn", "defs": [{"meaning": "(会意。小篆字形,上面是“手”字的变形,下面是“目”,意思是用手遮住眼睛远望。本义:用手加额遮目而远望)。"}, {"meaning": "同本义。", "cites": [{"t": "看,睎也。(睎,望也。)", "b": "《说文》"}, {"t": "遥看瀑布挂前川。", "b": "李白《望庐山瀑布》"}], "words": [{"w": "这棵雅致的常青树很好看", "t": ""}]}, {"meaning": "探望;问候。", "cites": [{"t": "荀巨伯远看友人疾。", "b": "《世说新语·德行》"}], "words": [{"w": "看理", "t": "探听"}, {"w": "看家", "t": "方言。探亲;看望家庭"}, {"w": "看视", "t": "探望;问候。"}]}, {"meaning": "瞧;观看。", "cites": [{"t": "出门看火伴。", "b": "《乐府诗集·木兰诗》"}, {"t": "晓看红湿处。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "老妇出门看。", "b": "唐·杜甫《石壕吏》"}, {"t": "却看妻子愁何在。", "b": "唐·杜甫《闻官军收河南河北》"}], "words": [{"w": "看着", "t": "眼看着"}, {"w": "看镜", "t": "照镜子"}, {"w": "看电影;看戏;看拉不上", "t": "瞧不顺眼"}, {"w": "看乔", "t": "误解,小看"}, {"w": "看街", "t": "一种临街开的窗户,装有槅子,可以观看街景。"}]}, {"meaning": "料理,准备。", "cites": [{"t": "急炊香饭来看客。", "b": "范成大《田家留客行》"}], "words": [{"w": "看下", "t": "准备,收拾"}, {"w": "看坐", "t": "安排坐位;关照坐下"}, {"w": "看活", "t": "服侍;照顾"}, {"w": "看斋", "t": "准备和尚的饮食"}, {"w": "看坐儿的", "t": "戏院里帮观众安排座位的人"}, {"w": "看板娘", "t": "方言。指商店的女服务员。"}]}, {"meaning": "估量。", "cites": [{"t": "看君颖上去,新月到应圆。", "b": "李白《送别》"}], "words": [{"w": " 看小", "t": "歧视, 看不起"}, {"w": "看长", "t": "看得远,有远见"}, {"w": "看候", "t": "照看,察看情况。"}]}, {"meaning": "看见。", "cites": [{"t": "王戎七岁,尝与诸小儿游。看道边李树多子折枝,诸儿竞走取之,唯戎不动。", "b": "《世说新语·雅量》"}]}, {"meaning": "阅读。", "cites": [{"t": "殷中军被废东阳,始看佛经。", "b": "《世说新语·文学》"}], "words": [{"w": "看书;看报", "t": ""}]}, {"meaning": "观察;察看。", "cites": [{"t": "帝微服往看。", "b": "《世说新语·术解》"}, {"t": "看伺空隙,欲复为乱。", "b": "《三国志·周鲂传》"}]}, {"meaning": "听,闻。", "cites": [{"t": "南岳后,累任作祠官,试说与君看。", "b": "宋·刘克庄《最高楼》"}]}, {"meaning": "物色。", "cites": [{"t": "我家做官的到任所,还望大人替他看所宅舍儿,好搬取家小。", "b": "《金瓶梅词话》"}]}, {"meaning": "当心。", "cites": [{"t": "你倒是去罢,这里有老虎,看吃了你。", "b": "《红楼梦》"}], "words": [{"w": "看野眼", "t": "分神;注意力不集中。"}]}, {"meaning": "“看怎么样”的省略,用在动词或动词结构的后面,表示试一试。", "cites": [{"t": "赵能道:“说的是,再仔细搜一搜看。”", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1540wx','矩','1','jǔ ju','矢','9','','[{"pinyin": "jǔ", "defs": [{"meaning": "(本字作巨,今字作矩。形声。从矢,巨声。本义:矩尺,画直角或方形的工具)。"}, {"meaning": "同本义。", "cites": [{"t": "求榘鑊之所同。", "b": "《离骚》"}, {"t": "不以规矩,不能成方员。", "b": "《孟子·离娄上》"}], "words": [{"w": "矩墨", "t": "曲尺及绳墨。比喻准则、规矩"}, {"w": "矩周规值", "t": "形容如规之相周,矩之相袭"}, {"w": "矩度", "t": "泛指计量长度和角度的用具"}, {"w": "矩绳", "t": "曲尺与墨绳。比喻规矩法则。"}]}, {"meaning": "法度。", "cites": [{"t": "七十而从心所欲,不逾矩。", "b": "《论语·为政》"}], "words": [{"w": "矩法", "t": "规矩法则"}, {"w": "矩则", "t": "规章法则"}, {"w": "矩设", "t": "按规矩设置"}, {"w": "矩诲", "t": "以规矩法度教诲"}, {"w": "矩鑊", "t": "规矩法度。"}]}, {"meaning": "方形。", "cites": [{"t": "榘,方也。", "b": "《广雅》"}, {"t": "员出于方,方出于矩,矩出于九九八十一。故折矩以为句广三、股修四,径隅五。", "b": "《周髀算经》"}], "words": [{"w": "矩形;矩坐", "t": "围成方形而坐"}, {"w": "矩步", "t": "比喻行动谨慎,举步皆合于法度。"}]}]}, {"pinyin": "ju", "defs": [{"meaning": "——见“规矩”(guīju)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1541wx','毡','1','zhān','毛','9','','[{"pinyin": "zhān", "defs": [{"meaning": "(形声。从毛,占声。本义:加工羊毛或其他动物毛而成的块片状材料) 同本义。", "cites": [{"t": "氈,撚毛也。", "b": "《说文》"}, {"t": "共其毳毛为毡,以待邦事。", "b": "《周礼·天官·掌皮》"}], "words": [{"w": "毡单", "t": "毡垫"}, {"w": "毡布", "t": "指毛织成的布"}, {"w": "毡车", "t": "以毛毡为篷的车子"}, {"w": "毡衫", "t": "毡制的衣衫"}, {"w": "毡屋", "t": "即毡帐"}, {"w": "毡席", "t": "毡制的铺垫用具"}, {"w": "毡帽", "t": "毡制的帽子"}, {"w": "毡毯", "t": "毛毡制成的毯子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1542wx','氢','1','qīng','气','9','','[{"pinyin": "qīng", "defs": [{"meaning": "化学元素名。一价非金属元素。在正常情况下,氢是无色、无臭、极易燃烧的双原子气体,在地球上和地球大气中只存在极稀少的游离状态氢 ——元素符号H。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1543wx','怎','1','zěn','心','9','','[{"pinyin": "zěn", "defs": [{"meaning": "(形声。从心,乍(zuò)声。本义:怎么,如何)。"}, {"meaning": "同本义。", "cites": [{"t": "怎禁人临去也回头望!", "b": "马致远《汉宫秋》"}], "words": [{"w": "怎生奈何", "t": "怎么办"}, {"w": "怎的起", "t": "怎么搞的;为什么"}, {"w": "怎禁", "t": "怎么受得"}, {"w": "怎个", "t": "怎么"}, {"w": "怎说", "t": "怎么回事"}, {"w": "怎价", "t": "方言。怎样,如何"}, {"w": "怎得", "t": "安得,怎么能够得到"}, {"w": "怎见得", "t": "犹言怎么知道,怎么看得出;又犹言且看如何"}, {"w": "怎生向", "t": "犹奈何"}, {"w": "怎当得", "t": "怎当。犹怎奈,无奈"}, {"w": "怎奈向", "t": "犹奈何,无奈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1544wx','牲','1','shēng','牜','9','','[{"pinyin": "shēng", "defs": [{"meaning": "(形声。从牛,从生。本义:古代供祭祀用的全牛)。"}, {"meaning": "同本义。", "cites": [{"t": "牲,牛完全也。", "b": "《说文》。按,牛完全当为字之训。"}, {"t": "全曰牲,伤曰牛。", "b": "《谷梁传·哀公元年》"}, {"t": "始养之曰畜,将用之曰牲,是牲者,祭祀之牛也。", "b": "《周礼·庖人》注"}, {"t": "用大牲。", "b": "《易·萃》。郑注:“大牲,牛也。”"}, {"t": "礼不卜常祀,而卜其牲日。牛卜日曰牲。", "b": "《左传·僖公三十一年》"}], "words": [{"w": "牲体", "t": "古时祭祀用的牺牲的躯体"}, {"w": "牲礼", "t": "祭祀时的用牲之礼"}, {"w": "牲玉", "t": "供祭祀用的牺牲和玉器"}, {"w": "牲事", "t": "古代祭祀中有关准备牺牲的事。"}]}, {"meaning": "泛指供祭祀、盟誓及食用的家畜,包括牛、羊、豕、马、犬、鸡等。", "cites": [{"t": "掌牧六牲。", "b": "《周礼·牧人》"}, {"t": "牺牲玉帛,弗敢加也。", "b": "《左传·庄公十年》"}], "words": [{"w": "牲犊", "t": "古代诸侯向天子供膳的小牛"}, {"w": "牲饩", "t": "所献赠的活的牛羊豕"}, {"w": "牲醪", "t": "牲体"}, {"w": "牲头", "t": "祭祀用的牲畜之头"}, {"w": "牲糈", "t": "祭祀用的牲畜和精米"}, {"w": "牲币", "t": "牺牲和币帛"}, {"w": "牲号", "t": "牺牲的名号。"}]}, {"meaning": "指野生动物。", "cites": [{"t": "是故为礼以奉之:为六畜、五牲、三牺,以奉五味。", "b": "《左传·昭公二十五年》"}]}, {"meaning": "生的肉食。", "cites": [{"t": "凡诸侯之礼,上公五积…鼎簋十有二,牲三十有六,皆陈。", "b": "《周礼·掌客》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1545wx','选','1','xuǎn','辶','9','','[{"pinyin": "xuǎn", "defs": [{"meaning": "(形声。从辵(chuò),巽(xùn)声。本义:遣送;放遂)。"}, {"meaning": "同本义。", "cites": [{"t": "选,遣也。", "b": "《说文》"}, {"t": "其母曰:“弗去,惧选。”癸卯,针适晋。", "b": "《左传·昭公元年》"}]}, {"meaning": "假借为“柬”。挑选,选择。", "cites": [{"t": "选,一曰择也。", "b": "《说文》"}, {"t": "圣人,十人曰选。", "b": "《白虎通》"}, {"t": "不可选也。", "b": "《诗·邶风·柏舟》"}, {"t": "命乡论秀士,升之司徒曰选士。", "b": "《礼记·王制》"}, {"t": "昼选男德以象谷明。", "b": "《国语·晋语》"}, {"t": "器成卒选,则士知胜矣。", "b": "《管子·七法》"}, {"t": "案谨募选阅材伎之士。", "b": "《荀子·王制》"}, {"t": "大道之行也,天下为公,选贤与能。", "b": "《礼记·礼运》"}, {"t": "选文以定篇。", "b": "《文心雕龙·序志》"}, {"t": "定选士,胜。", "b": "《管子》"}], "words": [{"w": "选侍", "t": "选入宫中的侍女"}, {"w": "选锋", "t": "挑选出来的精壮兵卒"}, {"w": "选刷", "t": "挑选"}, {"w": "选人", "t": "选用人才"}, {"w": "选士", "t": "挑选人才"}, {"w": "选权", "t": "铨选官吏之权"}, {"w": "选簿", "t": "铨选官吏的簿籍"}, {"w": "选职", "t": "主管铨选官吏的职务。"}]}, {"meaning": "派遣;使令。", "cites": [{"t": "选兵八万人。", "b": "《史记·魏公子列传》"}, {"t": "已选三万人。", "b": "宋·司马光《资治通鉴》"}, {"t": "更选将官。", "b": "清·梁启超《谭嗣同传》"}, {"t": "选巫咸兮叫帝阍,开天庭兮延群神。", "b": "扬雄《甘泉赋》"}], "words": [{"w": "选入外班", "t": "派往外地任职的官员。"}]}, {"meaning": "畏怯。", "cites": [{"t": "恐议者,选软复守和解。", "b": "《汉书·西南夷传》。注:“怯不前之意。”"}]}, {"meaning": "入。", "cites": [{"t": "[舜] 既纳于百揆,宾于四门,选于林木,入于大麓。", "b": "《古列女传》"}]}, {"meaning": "牵引,攀连。", "cites": [{"t": "乃征诸犯令相引数千人,命曰“株送徒。”", "b": "《史记》。司马贞索隐:“应劭云:‘送,当作选。选,引也。’”"}]}, {"meaning": "具有;拥有。", "cites": [{"t": "选徒嚣嚣。", "b": "《诗·小雅·车攻》"}]}, {"meaning": "德行。", "cites": [{"t": "夫民群居而无选,为政以始之。", "b": "《逸周书》"}]}, {"meaning": "片刻,须臾。", "cites": [{"t": "选间食熟。", "b": "《吕氏春秋·任数》。注:“须臾也。”"}, {"t": "选,少选,须臾也。", "b": "《古今韵会举要》"}], "words": [{"w": "选顷", "t": "选间。片刻,一会儿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1546wx','适','1','shì','辶','9','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从辵(chuò),啻(chì)声。本义:往,到)。"}, {"meaning": "同本义。", "cites": [{"t": "適,之也。", "b": "《说文》。段曰:“往自发动言之,适自所到言之。”"}, {"t": "十一月,沛公引兵之薛。", "b": "《汉书·高帝纪》"}, {"t": "辍耕之垄上。", "b": "《史记·陈涉世家》"}, {"t": "适,往也。", "b": "《尔雅》"}, {"t": "民不适攸居。", "b": "《书·盘庚》"}, {"t": "爰其适归。", "b": "《诗·小雅·四月》"}, {"t": "适彼乐土。", "b": "《诗·魏风·硕鼠》"}, {"t": "使适四方。", "b": "《周礼·小行人》"}, {"t": "以适父母舅姑之所。", "b": "《礼记·内则》"}, {"t": "逝将去女,适彼乐国。", "b": "《诗·魏风·硕鼠》"}, {"t": "余自齐安舟行适临汝。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "无所适从;何适;适秦;适远", "t": "到远处去"}, {"w": "适野", "t": "前往野外。"}]}, {"meaning": "归向。", "cites": [{"t": "好恶不愆,民知所适,事与不济。", "b": "《左传·昭公十五年》"}], "words": [{"w": "适归", "t": "往归;归向"}, {"w": "适道", "t": "可以一起学习,而不可以一起完成某种事业或达到某种道德境界。"}]}, {"meaning": "女子出嫁。", "cites": [{"t": "适,女子出嫁。", "b": "《玉篇》"}, {"t": "女年十五许,有适人之道。", "b": "《孔子家语·本命》"}, {"t": "女三人,长适秘书丞钱衮,余尚幼。", "b": "欧阳修《江邻几墓志铭》"}, {"t": "贫贱有此女,始适还家门。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "已适", "t": "已嫁出"}, {"w": "重适", "t": "改嫁。"}]}, {"meaning": "符合,适合。", "cites": [{"t": "适我愿兮。", "b": "《诗·郑风·野有蔓草》"}, {"t": "其风雨则不适。", "b": "《吕氏春秋·明理》"}, {"t": "寒暑适。", "b": "《吕氏春秋·大乐》"}, {"t": "处分适兄意,那得自任专!", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "少无适俗韵,性本爱丘山。", "b": "晋·陶渊明《归园田居》"}], "words": [{"w": "适意", "t": "顺心;满意"}, {"w": "适志", "t": "做事合乎心意"}, {"w": "适变", "t": "适应变化"}, {"w": "适职", "t": "适合职分"}, {"w": "适愿", "t": "符合心愿"}, {"w": "适价", "t": "合适的价格"}, {"w": "适足", "t": "充足适度而不过分"}, {"w": "适例", "t": "恰当的例子。"}]}, {"meaning": "遇。", "cites": [{"t": "世俗见高祖兴于布衣,不达其故,以为适遭暴乱,得奋其剑。", "b": "班彪《王命论》"}]}, {"meaning": "舒适,满足。", "cites": [{"t": "是芙蕖也者,无一时一刻不适耳目之观。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "扫叶席草,酌相劳,意适往反,往往留于山上。", "b": "宋·苏辙《武昌九曲亭记》"}], "words": [{"w": "舒适;适身", "t": "身体感到舒适"}, {"w": "适己", "t": "自得。"}]}, {"meaning": "正好,恰好。", "cites": [{"t": "从上观之适与地平,以至诸峰之顶,亦低于山顶之地面。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "适先生奓户入,闻两童子音琅琅然,不觉莞尔,连呼则则。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "适晤", "t": "恰好遇见"}, {"w": "适逢其会;适然", "t": "恰好如此。"}]}, {"meaning": "偶而,偶然。", "cites": [{"t": "乃有大罪,非终,乃惟眚灾,适尔。", "b": "《书·康诰》"}]}, {"meaning": "刚刚;方才。", "cites": [{"t": "适得府君书,明日来迎汝。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "时已过午,奴辈适至。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "适聆雅奏", "t": "刚才听得所奏之高雅音乐。"}]}, {"meaning": "如果,假如,假定。", "cites": [{"t": "王适有言,必亟听从。", "b": "《韩非子·内储说下》"}]}, {"meaning": "辟领,古丧服之领。系开丧服而成。一说通“积”。", "cites": [{"t": "负广出于适寸。适博四寸,出于衰。", "b": "《仪礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1547wx','秒','1','miǎo','禾','9','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从禾,少声。本义:禾芒)。"}, {"meaning": "同本义。", "cites": [{"t": "秒,禾芒也。", "b": "《说文》"}, {"t": "造计秒忽。", "b": "《汉书·叙传下》。注引刘德:“秒,禾芒也。”"}], "words": [{"w": "秒忽", "t": "秒是禾芒,忽是细丝,比喻微细"}, {"w": "秒末", "t": "微小。"}]}, {"meaning": "末端。", "cites": [{"t": "癸巳七月之秒,余从西俗避暑白雷登海口。", "b": "清·薛福成文"}]}, {"meaning": "计量单位的名称。"}, {"meaning": "时间一分的1/60;特指厘米-克-秒制的时间单位。"}, {"meaning": "角度一分的1/60。"}, {"meaning": "作为测定液体粘度的一个测量单位的时间。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1548wx','香','1','xiāng','香','9','','[{"pinyin": "xiāng", "defs": [{"meaning": "(会意字。据小篆,从黍,从甘。“黍”表谷物;“甘”表香甜美好。本义:五谷的香)。"}, {"meaning": "同本义。", "cites": [{"t": "香,芳也。春秋传曰:“香稷馨香。”", "b": "《说文》。朱骏声曰:“按,谷与酒臭曰香。”"}, {"t": "黍稷靡馨。", "b": "《左传·僖公五年》"}, {"t": "卬盛于豆,于豆于盛,其香始升。", "b": "《诗·大雅·生民》"}]}, {"meaning": "有飶其香,邦家之光。——《诗·周颂·载芟》。", "cites": [{"t": "稻花香里说丰年。", "b": "宋·辛弃疾《西江月》"}, {"t": "淅玉炊香粳。", "b": "韩愈孟郊《城南联句》"}]}, {"meaning": "泛指好闻的气味。", "cites": [{"t": "二十里中香不断,青羊宫到浣花溪。", "b": "陆游《梅花绝句》"}], "words": [{"w": "香鼠", "t": "一种皮毛名贵的貂"}, {"w": "香醪", "t": "芳香的酒"}, {"w": "香楠", "t": "芳香的楠木。"}]}, {"meaning": "气味美好。", "cites": [{"t": "树橘柚者,食 之则甘,嗅之则香。", "b": "《雅南子·外储说左下》"}, {"t": "香远益清。", "b": "宋·周敦颐《爱莲说》"}, {"t": "香而甘也。", "b": "清·周容《春酒堂遗书》"}, {"t": "香且甘者。", "b": ""}], "words": [{"w": "饭热菜香;在病中他吃喝都觉得不香", "t": ""}]}, {"meaning": "受欢迎。", "cites": [{"t": "孰知不问边庭苦,纵死犹闻侠骨香。", "b": "王维《少年行》"}], "words": [{"w": "香饽饽", "t": "比喻受欢迎的人"}, {"w": "香亮", "t": "称心;宠爱"}, {"w": "这首歌曲很吃香", "t": ""}]}, {"meaning": "亲热。", "cites": [{"t": "咱们这么坐着亲香。", "b": "《儿女英雄传》"}], "words": [{"w": "亲香", "t": "亲热、亲近。"}]}, {"meaning": "美好。", "cites": [{"t": "泉香而酒冽。", "b": "欧阳修《醉翁亭记》"}], "words": [{"w": "香土;香玉;香轮;香雨", "t": ""}]}, {"meaning": "草木香料,常掺以木屑做成细条,点燃用以祭祀祖先或神佛。", "cites": [{"t": "爇香于鼎。", "b": "《聊斋志异·促织》"}], "words": [{"w": "香培玉琢", "t": "就像用香料造成、美玉雕出一样"}, {"w": "香积行童", "t": "僧寺伙房的帮厨者。"}]}, {"meaning": "抽;吸(鸦片烟)。", "cites": [{"t": "咱们去香一筒好吗?", "b": "《负曝闲谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1549wx','种','1','chóng zhǒng zhòng','禾','9','','[{"pinyin": "chóng", "defs": [{"meaning": "幼稚。", "cites": [{"t": "种,稚也。", "b": "《玉篇》"}]}]}, {"pinyin": "zhǒng", "defs": [{"meaning": "植物的种子。", "cites": [{"t": "诞降嘉种。", "b": "《诗·大雅·生民》"}, {"t": "其谷宜五种。谓黍、菽、麦、稻也。", "b": "《周礼·职方氏》"}, {"t": "种不得下。", "b": "《汉书·沟洫志》。注:“五谷之子也。”"}, {"t": "宁有种乎?", "b": "《史记·陈涉世家》"}, {"t": "黄芩之种。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "点种", "t": "点播种子"}, {"w": "种籽", "t": "即种子"}, {"w": "种食", "t": "谷种种粮食"}, {"w": "种粮", "t": "谷物的种子"}, {"w": "种实", "t": "即种子"}, {"w": "种粒", "t": "犹种子"}, {"w": "种子田", "t": "也叫“留种田”。"}]}, {"meaning": "人的种族或其他生物的族类。", "cites": [{"t": "种马一物。", "b": "《周礼·校人》"}, {"t": "单于一平荡,种落自奔亡。", "b": "李白《出自蓟北门行》"}], "words": [{"w": "种落", "t": "部族居住的地方"}, {"w": "种人", "t": "同种族的人"}, {"w": "种落", "t": "种族部落"}, {"w": "种众", "t": "同一种族的群众"}, {"w": "种号", "t": "种族名号"}, {"w": "种诛", "t": "族诛"}, {"w": "种豪", "t": "种族中的豪强"}, {"w": "种辈", "t": "同一种族的人"}, {"w": "种孽", "t": "对非我种族的蔑称"}, {"w": "种界", "t": "种族的界限"}, {"w": "种性", "t": "种属的特性。"}]}, {"meaning": "人种。", "cites": [{"t": "本以救国救种为志。", "b": "孙中山《建国方略之一》"}], "words": [{"w": "黄种人;白种人;黑种人;有色人种;蒙古人种;灭种", "t": ""}]}, {"meaning": "种类;类别。", "cites": [{"t": "序六艺为九种。", "b": "《汉书·艺文志》"}], "words": [{"w": "剧种;兵种;工种;军种;种切", "t": "种种切切,一切的意思"}, {"w": "种别", "t": "类别"}, {"w": "种类", "t": "类别。"}]}]}, {"pinyin": "zhòng", "defs": [{"meaning": "(形声。从禾,中(重)声。本义:播种;散布)。"}, {"meaning": "同本义。", "cites": [{"t": "种,先种后熟也。", "b": "《说文》"}, {"t": "黍稷种稑。", "b": "《诗·大雅·閟宫》"}, {"t": "而生种稑之种。", "b": "《周礼·内宰》"}, {"t": "种之黄茂,实方实苞。", "b": "《诗·大雅·生民》"}, {"t": "慎其种,勿使数,亦无使疏。", "b": "《吕氏春秋·辩土》"}, {"t": "仲秋乃劝种麦。", "b": "《礼记·月令》"}, {"t": "一丘之禾,则后种者晚实。", "b": "《梦溪笔谈·采草药》"}, {"t": "皋陶迈种德,德乃降,黎民怀之。", "b": "《书·大禹谟》"}], "words": [{"w": "种田;种子", "t": "下种"}, {"w": "种惠", "t": "施予恩惠"}, {"w": "种祸", "t": "埋下祸根"}, {"w": "种福", "t": "积福"}, {"w": "种祉", "t": "赐福"}, {"w": "种毒", "t": "埋下毒根。"}]}, {"meaning": "种植;栽种。", "cites": [{"t": "东西植松柏,左右种梧桐。", "b": "《乐府诗集·焦仲卿妻》"}, {"t": "条桑腊月下,种杏春风前。", "b": "唐·王维《送六舅归陆浑》"}], "words": [{"w": "种瓜", "t": "栽植瓜果"}, {"w": "种菜", "t": "种植蔬菜"}, {"w": "种栽", "t": "犹栽种"}, {"w": "种插", "t": "插枝栽种"}, {"w": "种殖", "t": "栽种繁殖"}, {"w": "种瓜得瓜", "t": "比喻有其因必得其果。"}]}, {"meaning": "繁殖;养育。", "cites": [{"t": "以肥其身,以种其子孙。", "b": "唐·韩愈《祭鳄鱼文》"}], "words": [{"w": "种鱼", "t": "养鱼。"}]}, {"meaning": "移植;接种。", "cites": [{"t": "种痘而愈,遂传于世。", "b": "《医宗金鉴》"}], "words": [{"w": "种齿", "t": "镶补牙齿"}, {"w": "种牙", "t": "修镶牙齿。"}]}, {"meaning": "培养;培植。", "cites": [{"t": "明州江瑶柱有二种,大者江瑶,小者沙瑶,然沙瑶可种,逾年则成江瑶矣。", "b": "宋·陆游《老学庵笔记》"}], "words": [{"w": "种学", "t": "培养学识"}, {"w": "种学积文", "t": "培养学识,积累文才"}, {"w": "种智", "t": "佛教语。“一切种智”的省称"}, {"w": "种觉", "t": "佛教语。佛证一切种智而大觉圆满,故名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1550wx','秋','1','qiū','禾','9','','[{"pinyin": "qiū", "defs": [{"meaning": "(象形。甲骨文字形为蟋蟀形,虫以鸣秋,借以表达“秋天”的概念。另一写法,是蟋蟀形下加“火”字,表示秋天禾谷熟,似火灼。籀文又添加“禾”旁。本义:收成,成熟的庄稼)。"}, {"meaning": "同本义。", "cites": [{"t": "秋,禾谷熟也。", "b": "《说文》"}, {"t": "秋为白藏。又,秋为收成。", "b": "《尔雅》"}, {"t": "秋者,少阴之选也。", "b": "《春秋繁露·官制象无篇》"}, {"t": "百谷名以其初生为春,熟为秋,故麦以孟夏为秋。", "b": "《月令章句》"}, {"t": "处处田畴尽有秋。", "b": "宋·范成大《颜桥道中》"}, {"t": "收过了秋,天气一凉,病就重起来。", "b": "赵树理《福贵》"}], "words": [{"w": "麦秋", "t": "收割麦子的时候"}, {"w": "秋麦", "t": "成熟的禾稼"}, {"w": "秋禾", "t": "秋熟的谷物"}, {"w": "秋成", "t": "指秋天成熟的庄稼"}, {"w": "秋苗", "t": "也称秋税。官府征收的秋熟谷物赋税"}, {"w": "秋实", "t": "秋季成熟的谷物及果实"}, {"w": "秋登", "t": "秋季谷物成熟。"}]}, {"meaning": "秋季 。四季中的第三季,即八月、九月和十月这三个月。", "cites": [{"t": "秋以为期。", "b": "《诗·卫风·氓》"}, {"t": "发迹入四明,梯空上秋旻。", "b": "韩愈《送惠师》"}], "words": [{"w": "秋场", "t": "秋试。明清科举考试制度,每三年的秋季,在各省省城举行乡试,中试者为举人"}, {"w": "秋狝冬狩", "t": "秋天打猎称“秋狝”,冬天打猎叫“冬狩”"}, {"w": "秋粮", "t": "秋季征收的田赋"}, {"w": "秋荐", "t": "秋场"}, {"w": "秋零", "t": "秋气肃杀,景物凋零"}, {"w": "秋叶", "t": "秋天的落叶"}, {"w": "秋严", "t": "秋气肃杀"}, {"w": "秋黄", "t": "草木至秋而枯黄,亦指秋天枯黄的草木。"}]}, {"meaning": "年。", "cites": [{"t": "上与梁王燕饮,尝从容言曰:“千秋万岁后将传于王。”", "b": "《史记》"}]}, {"meaning": "指某一时期、某一时刻。", "cites": [{"t": "此诚危急存亡之秋也。", "b": "诸葛亮《出师表》"}, {"t": "效命之秋。", "b": "《史记·魏公子列传》"}, {"t": "不问之秋。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "千秋", "t": "很长久的时间"}, {"w": "秋丁", "t": "旧时农历八月第一个丁日是祭祀孔子的日子。"}]}, {"meaning": "悲愁。", "cites": [{"t": "秋之为言愁也。", "b": "《礼记·乡饮酒义》"}], "words": [{"w": "秋士", "t": "愁士,不得意的士子。"}]}, {"meaning": "喻容颜衰老。", "cites": [{"t": "胡未灭,鬓先秋。", "b": "陆游《诉衷情》"}, {"t": "但恐光景晚,宿昔成秋颜。", "b": "李白《春日独酌》"}], "words": [{"w": "秋娘", "t": "泛指年老色衰的妇女"}, {"w": "秋眉", "t": "衰白眉毛"}, {"w": "秋鬓", "t": "衰白的鬓发"}, {"w": "秋颜", "t": "衰老的容颜。"}]}, {"meaning": "古以五色、五行配四时,秋为金,其色白,故指白色。", "cites": [{"t": "春容舍我去,秋发已衰改。", "b": "李白《古诗五十九首》"}], "words": [{"w": "秋容", "t": "指白海棠"}, {"w": "秋鬓", "t": "苍白的鬓发"}, {"w": "秋霜", "t": "喻白发"}, {"w": "秋糯", "t": "雪白的糯米"}, {"w": "秋练", "t": "洁白的丝绢。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1551wx','科','1','kē','禾','9','','[{"pinyin": "kē", "defs": [{"meaning": "(会意。从禾,从斗。“斗”的意思是“量”。合起来指衡量、分别谷子的等级品类。本义:品类,等级)。"}, {"meaning": "同本义。", "cites": [{"t": "科,程也。", "b": "《说文》"}, {"t": "为力不同科。", "b": "《论语·八佾》"}, {"t": "与此同科。", "b": "《论衡·幸偶》"}, {"t": "君歌且休听我歌,我歌今与君殊科。", "b": "韩愈《八月十五夜赠张巧曹》"}], "words": [{"w": "科品", "t": "种类;等级"}, {"w": "科荣", "t": "科第荣华"}, {"w": "科爵", "t": "指封建王朝官员的品级爵位。"}]}, {"meaning": "法令;刑律。", "cites": [{"t": "三仪同科。", "b": "《太玄·玄离》。注:“法也。”"}, {"t": "从水之科满。", "b": "《太玄·从》。注:“法也。”"}, {"t": "若有作奸犯科及为忠善者。", "b": "诸葛亮《出师表》"}], "words": [{"w": "科防互设", "t": "条律禁令交相设置"}, {"w": "科文", "t": "法令条文"}, {"w": "科令", "t": "法令;律条"}, {"w": "科戒", "t": "修道的戒律、法规。"}]}, {"meaning": "科举考试的科目或等第。", "cites": [{"t": "设程试之科,重金爵之赏。", "b": "韦昭《博奕论》"}], "words": [{"w": "科分", "t": "科举中式之年份"}, {"w": "科甲出身", "t": "由科举及第而取得入仕的资格"}, {"w": "科法", "t": "科举取士之法"}, {"w": "科贡", "t": "泛指科举。"}]}, {"meaning": "条款;段落。", "cites": [{"t": "科条既备。", "b": "《战国策·秦策》"}], "words": [{"w": "科段", "t": "指文章的段落或部分"}, {"w": "科条", "t": "科目,项目;条例;谓分类整理成条款、纲目。"}]}, {"meaning": "传统戏剧角色的动作。", "cites": [{"t": "鼓三通,锣三下科。", "b": "《窦娥冤》"}], "words": [{"w": "打科;笑科", "t": ""}]}, {"meaning": "坎;坑。", "cites": [{"t": "其于木也,为科上槁。", "b": "《易·说卦》"}, {"t": "[水]盈科而后进。", "b": "《孟子·离娄下》"}], "words": [{"w": "科子", "t": "坑子"}, {"w": "科臼", "t": "窠臼"}, {"w": "科雉", "t": "刚出窠之雉;幼雉。"}]}, {"meaning": "课税,征税。", "cites": [{"t": "假此科敛丁口。", "b": "《聊斋志异》"}], "words": [{"w": "科派", "t": "摊派"}, {"w": "科差", "t": "向官府缴纳的捐税和承担的差役"}, {"w": "科敛", "t": "聚敛,收取财物。"}]}, {"meaning": "空虚。", "cites": [{"t": "其于木也,为科上槁。", "b": "《易·说卦》。孔颖达疏:“科,空也。阴在内为空。木即空中者,上必枯槁。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1552wx','重','1','chóng zhòng','里','9','','[{"pinyin": "chóng", "defs": [{"meaning": "(字源见“重”zhòng)。"}, {"meaning": "重复,重叠。", "cites": [{"t": "四阿重屋。", "b": "《考工记·匠人》。注:“复笮也。”"}, {"t": "设重帘。", "b": "《周礼·掌次》"}, {"t": "余将董道而不豫兮,固将重昏而终身。", "b": "屈原《涉江》"}, {"t": "王无重世之德。", "b": "《史记·春申君传》"}, {"t": "重金兼紫。", "b": "《后汉书·吕强传》"}, {"t": "圜有九重,孰营度之?", "b": "《楚辞·天问》"}], "words": [{"w": "这两个例子重了;重句", "t": "重复的文句"}, {"w": "重字", "t": "重复的字"}, {"w": "重卦", "t": "重叠八卦"}, {"w": "重席", "t": "重叠的垫席"}, {"w": "重轩", "t": "双重栏杆。"}]}, {"meaning": "双,成对。", "cites": [{"t": "盖二以重。", "b": "《仪礼·少牢礼》"}], "words": [{"w": "重五", "t": "阴历五月初五日,即端阳节"}, {"w": "重瞳", "t": "传说舜与项羽眼中有两个瞳仁。"}]}, {"meaning": "多。", "cites": [{"t": "重器备。", "b": "《左传·成公二年》。注:“犹多也。”"}], "words": [{"w": "重围", "t": "层层包围"}, {"w": "重楼", "t": "道教称气管为重楼。认为气管有十二节,故又叫十二节重楼"}, {"w": "重铠", "t": "多重的护身铁甲"}, {"w": "重听", "t": "听觉不灵。"}]}, {"meaning": "在家庭关系中,属于比 。 如:重孙;重庆(祖父母、父母都健在)。"}, {"meaning": "再次,另一次,重新,又。", "cites": [{"t": "乃重修岳阳楼。", "b": "范仲淹《岳阳楼记》"}, {"t": "新妇谓府吏:“勿复重纷纭。”", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "重,再也。", "b": "《广雅》"}, {"t": "面谀以重陛下过。", "b": "《史记·李斯传》。索隐:“再也。”"}], "words": [{"w": "重逢;重科", "t": "重新判罪"}, {"w": "重行", "t": "再次"}, {"w": "重光", "t": "指日光再现。"}]}, {"meaning": "层。", "cites": [{"t": "京口瓜洲一水间,钟山只隔数重山。", "b": "王安石《泊船瓜洲》"}], "words": [{"w": "兵围数重;一重束缚;重屋", "t": "两层的房屋。"}]}, {"meaning": "怀孕。", "cites": [{"t": "人有重身。", "b": "《素问·奇病论》"}], "words": [{"w": "重身", "t": "怀孕"}, {"w": "重马", "t": "怀孕的马。"}]}]}, {"pinyin": "zhòng", "defs": [{"meaning": "(会意兼形声。金文字形,从东,从壬(tǐng),东亦声。壬,挺立。东,囊袋。人站着背囊袋,很重。《说文》:“重,厚也。”徐锴:“壬者,人在土上,故为厚也。”本义:分量大,与“轻”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "重,厚也。从王,東声。王者安土不迁之意。", "b": "《说文》"}, {"t": "引重致远。", "b": "《易·系辞》。虞注:“坤为重。”"}, {"t": "权然后知轻重。", "b": "《孟子》"}, {"t": "重币也。", "b": "《战国策·齐策四》"}, {"t": "重于九鼎。", "b": "《史记·平原君虞卿列传》"}, {"t": "花重锦官城。", "b": "唐·杜甫《春夜喜雨》"}], "words": [{"w": "重器", "t": "象征国家政权的宝器"}, {"w": "重绢", "t": "厚重的好绢"}, {"w": "军令重于山;沉重", "t": "分量大;程度深"}, {"w": "笨重", "t": "庞大沉重"}, {"w": "过重", "t": "行李、信件等超过规定的重量"}, {"w": "重负荷;重囚", "t": "指犯有重罪的囚犯"}, {"w": "重孝", "t": "最重的丧服。"}]}, {"meaning": "指音强。", "cites": [{"t": "宫谓之重。", "b": "《尔雅》。孙注:“宫音浊而迟,故曰重也。”"}, {"t": "其声重厚,如君之德。", "b": "《汉书·律历志》"}], "words": [{"w": "重读;重音", "t": ""}]}, {"meaning": "大。", "cites": [{"t": "引重鼎不程其力。", "b": "《礼记·儒行》。注:“大鼎也。”"}, {"t": "天下重物也,而不以害其生,又况于它物乎?", "b": "《吕氏春秋》"}, {"t": "权重也。", "b": "《韩非子·五蠹》"}, {"t": "以求重价。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "重赀", "t": "数量很大的钱财"}, {"w": "重科", "t": "重大的罪"}, {"w": "重寄", "t": "重大的付托"}, {"w": "重才", "t": "大才"}, {"w": "重治", "t": "大治"}, {"w": "重柄", "t": "大权"}, {"w": "重星", "t": "大星"}, {"w": "重德", "t": "大德。"}]}, {"meaning": "庄重,慎重。", "cites": [{"t": "存之欲其重。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "重人", "t": "稳重谨慎的人"}, {"w": "重迟", "t": "稳重,持重"}, {"w": "重固", "t": "稳固"}, {"w": "重誓", "t": "庄重的誓言"}, {"w": "重毅", "t": "庄重坚毅"}, {"w": "重诺", "t": "信守诺言"}, {"w": "重始", "t": "慎重于事物、行为的开始"}, {"w": "重详", "t": "慎重思考"}, {"w": "重慎", "t": "慎重"}, {"w": "重举", "t": "举动慎重。"}]}, {"meaning": "重要;紧要。", "cites": [{"t": "总兹戎重。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "重于社稷。", "b": "明·张溥《五人墓碑记》"}, {"t": "重于三十年前。", "b": "孙文《序》?"}], "words": [{"w": "重列", "t": "重要的位次,要职"}, {"w": "重位", "t": "重要职位,高位"}, {"w": "重路", "t": "重要的行政区域"}, {"w": "重质", "t": "重要人质"}, {"w": "重职", "t": "重要官职。"}]}, {"meaning": "贵重;尊贵。", "cites": [{"t": "珍器重宝。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "重客", "t": "贵客"}, {"w": "重敬", "t": "敬重"}, {"w": "重礼", "t": "尊重礼仪"}, {"w": "重直", "t": "犹高价"}, {"w": "重货", "t": "指金银等贵重财物"}, {"w": "重钜", "t": "昂贵。"}]}, {"meaning": "严肃;严明。", "cites": [{"t": "重罚不用。", "b": "《韩非子·五蠹》"}, {"t": "重以周。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "重法", "t": "严酷的刑法"}, {"w": "重辟", "t": "死刑。"}]}, {"meaning": "严重。", "cites": [{"t": "杀人重囚。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "又。", "cites": [{"t": "情稍重。", "b": ""}]}, {"meaning": "重量。", "cites": [{"t": "千钧之重,人不轻举。", "b": "汉·桓宽《盐铁论》"}, {"t": "其耳三寸,其实一升,重一钧。", "b": "《周礼·考工记》"}, {"t": "重四五十斤。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "皮重;失重;体重;载重;荷重;净重;空重;承重;比重;举重;毛重", "t": ""}]}, {"meaning": "指辎重。军中载运粮食、器物的车子。", "cites": [{"t": "楚重至于邲。", "b": "《左传·宣公十二年》"}], "words": [{"w": "重车", "t": "古时的战车。装载衣食的车子"}, {"w": "重载", "t": "古时谓装载辎重等货物。"}]}, {"meaning": "权力,权势。", "cites": [{"t": "然则人主无威,而重在左右矣。", "b": "《韩非子》"}], "words": [{"w": "重爵", "t": "崇高的爵位"}, {"w": "重权", "t": "重大权力。"}]}, {"meaning": "重视;尊重。", "cites": [{"t": "古者重冠礼。", "b": "唐·柳宗元《柳河东集》"}, {"t": "我所高重者。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "益重之。", "b": "宋·司马光《训俭示康》"}, {"t": "雅重瑞名。", "b": "清·张廷玉《明史》"}], "words": [{"w": "重文", "t": "重视文事"}, {"w": "重民", "t": "古代重视农业,所以称农民为重民"}, {"w": "重言", "t": "为人所推重的语言。重视言语"}, {"w": "重身", "t": "重视身高"}, {"w": "重调查研究;重生", "t": "珍重身体,爱惜生命"}, {"w": "重年", "t": "敬重老年人。"}]}, {"meaning": "加重;增加。", "cites": [{"t": "是重吾不德也。", "b": "《汉书·文帝纪》"}], "words": [{"w": "重比", "t": "从严议罪,从重拟刑"}, {"w": "重困", "t": "加重困苦"}, {"w": "重使", "t": "加重役使"}, {"w": "重怒", "t": "增添愤怒"}, {"w": "重税", "t": "从重征税。"}]}, {"meaning": "(dòng)影响。", "cites": [{"t": "且晋人蹙忧以重我。", "b": "《左传·僖公十五年》"}, {"t": "候人不可重也。", "b": "《管子·侈靡》"}]}, {"meaning": "极;甚;十分。", "cites": [{"t": "重寒则热。", "b": "《素问·阴阳应象》"}]}, {"meaning": "特别。", "cites": [{"t": "秦皇帝惜其善击筑,重赦之。", "b": "《史记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1553wx','复','1','fù','夂','9','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。小篆字形,下面的意符“攵”,是甲骨文“止”字的变形,表示与脚或行走有关。上面是声符“畐”(fú)的省形,有“腹满”义,在字中亦兼有表义作用。后来繁化,加义符“彳”(chì),表示行走,现在又简化为“复”。本义:返回,回来)。"}, {"meaning": "同本义。", "cites": [{"t": "復,往来也。", "b": "《说文》"}, {"t": "反复其道。", "b": "《易·复》"}, {"t": "公归不复。", "b": "《诗·豳风·九罭》"}, {"t": "扬触捆復。", "b": "《仪礼·大射仪》"}, {"t": "无往不復。", "b": "《易·泰》"}, {"t": "卒乃復。", "b": "《书·舜典》"}, {"t": "不远而复,先典攸高。", "b": "南朝梁《与陈伯之书》"}, {"t": "数请之,朱亥故不复谢。", "b": "《史记·魏公子列传》"}, {"t": "死者不可復生。", "b": "《公羊传·襄公三十年》"}, {"t": "旦復旦兮。", "b": "《书·大传》"}, {"t": "言不可復也。", "b": "《论语》"}], "words": [{"w": "复还", "t": "回返。"}]}, {"meaning": "引申为恢复。", "cites": [{"t": "更若役,复若赋,则何如?", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "攘除奸凶,兴复汉室,还于旧都。", "b": "诸葛亮《出师表》"}], "words": [{"w": "复国", "t": "恢复邦国"}, {"w": "复性", "t": "恢复善良的本性"}, {"w": "复正", "t": "恢复正规、正常"}, {"w": "复朴", "t": "恢复真朴"}, {"w": "复故", "t": "恢复照旧"}, {"w": "复籍", "t": "恢复学籍;恢复国籍。"}]}, {"meaning": "回归,还原。", "cites": [{"t": "燕日败亡,卒至河上,而齐七十余城皆复为齐。", "b": "《史记·田单列传》"}, {"t": "死者不可复生。", "b": "《公羊传·襄公三十年》"}, {"t": "旦复旦兮。", "b": "《书·大传》"}, {"t": "言不可复也。", "b": "《论语》"}]}, {"meaning": "回答。", "cites": [{"t": "或遇其叱咄,色愈恭,礼愈至,不敢出一言以复。", "b": "明·宋濂《送东阳马生序》"}, {"t": "有复于王者曰。", "b": "《孟子·梁惠王上》"}, {"t": "王辞而不复。", "b": "《史记·司马相如传》"}], "words": [{"w": "复书", "t": "复信,答函"}, {"w": "复谢", "t": "回拜,答谢。"}]}, {"meaning": "报复。", "cites": [{"t": "纵无被坚执锐者北面复匈奴之志。", "b": "汉·桓宽《盐铁论本文》"}], "words": [{"w": "复怨", "t": "报仇。"}]}, {"meaning": "免除。", "cites": [{"t": "民有东骑马一匹者,复卒三人。(免除三人的兵役。)", "b": "汉·晁错《论贵粟疏》"}], "words": [{"w": "复除", "t": "免除徭役"}, {"w": "复租", "t": "免除赋税"}, {"w": "复免", "t": "免除徭役。"}]}, {"meaning": "覆盖。引申为庇护。", "cites": [{"t": "顾我复我。", "b": "《诗·小雅·蓼莪》"}], "words": [{"w": "复土", "t": "盖土"}, {"w": "复载生成", "t": "天复地载,抚育成长。指庇养包容,教育成长"}, {"w": "复瓿", "t": "比喻著作没有价值,只能用来盖盛酱的瓦罐。"}]}, {"meaning": "又,再。中断再开始。", "cites": [{"t": "不行不可复者。", "b": "《管子·牧民》"}, {"t": "司马相如作凡将篇,无复字。", "b": "《汉书·艺文志》"}, {"t": "以一至万,则世世不相复也。", "b": "《汉书·贾山传》"}, {"t": "得复见将军于此。", "b": "《史记·项羽本纪》"}, {"t": "超复受使,固欲益其兵。", "b": "《后汉书·班超梁慬传》"}, {"t": "一狼得骨止,一狼仍从。复投之。", "b": "《聊斋志异·狼三则》"}, {"t": "复前行,欲穷其林。", "b": "晋·陶渊明《桃花源记》"}, {"t": "轻拢慢捻抹复挑,初为《霓裳》后《六幺》。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "复籍;复帐", "t": "妓女接待第二个客人"}, {"w": "复旦", "t": "夜尽复明。"}]}, {"meaning": "有里的衣服。即夹衣。", "cites": [{"t": "複,重衣也。从衣,复声。", "b": "《说文》"}, {"t": "有里曰複,无里曰襌。", "b": "《释名·释衣服》"}, {"t": "夏不失复。", "b": "桓宽《盐铁论》"}], "words": [{"w": "复裈", "t": "双层裤,夹裤"}, {"w": "复襦", "t": "有里的短袄"}, {"w": "复衫", "t": "短袄"}, {"w": "复衾", "t": "絮有絮棉的大被"}, {"w": "复被", "t": "絮有絮绵的被。"}]}, {"meaning": "重复;繁复。", "cites": [{"t": "山重水复疑无路,柳暗花明又一村。", "b": "宋·陆游《游山西村》"}, {"t": "五帝不相复,三代不相袭。", "b": "《史记·秦始皇本纪》。又如:复用(重复运用);复沓(重复;重叠堆积)"}]}, {"meaning": "夹层。", "cites": [{"t": "从复道上。", "b": "《汉书·高帝纪》。师古曰:“上下有道,故曰之复。”"}, {"t": "履中有木者,谓之复舄。", "b": "《方言》"}, {"t": "红罗复斗帐,四角垂香囊。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "复道行空,不霁何虹?", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "复道", "t": "楼阁间架空的通道"}, {"w": "复道回廊", "t": "高楼间或山岩险要处架空的通道、阁道和曲折迂回的走廊"}, {"w": "复哨", "t": "军事用语。即二人为一班的步哨"}, {"w": "复账", "t": "双层的帷账"}, {"w": "复壁", "t": "两层而中空的墙壁,可以藏匿人和物。"}]}, {"meaning": "重叠。", "cites": [{"t": "陶复陶穴。", "b": "《诗·大雅·緜》"}], "words": [{"w": "复嶂", "t": "重叠的岩石山峦"}, {"w": "复岭", "t": "重叠的山峰"}, {"w": "复屋", "t": "上古时代一种楼阁的建筑"}, {"w": "复阁", "t": "重叠的楼阁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1554wx','竿','1','gān','竹','9','','[{"pinyin": "gān", "defs": [{"meaning": "(形声。从竹,干声。本义:竹竿)。"}, {"meaning": "同本义。竹子的主干。", "cites": [{"t": "竿,竹梃也。", "b": "《说文》"}, {"t": "籊籊竹竿。", "b": "《诗·卫风·竹竿》"}, {"t": "禁藏母拊竿。", "b": "《管子》"}, {"t": "竿殳之所揘毕。", "b": "张衡《西京赋》"}, {"t": "大书一“屈”字,以两竿夹揭之,走诉行御史台。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "立竿见影;揭竿为旗;竿木", "t": "古代艺人借以在其上表演各种技艺动作的长竿"}, {"w": "竿殳", "t": "竹杖"}, {"w": "竿首", "t": "竹竿顶端"}, {"w": "竿头", "t": "竹竿的顶端。"}]}, {"meaning": "竹简。", "cites": [{"t": "不离苞苴竿牍。", "b": "《庄子·列御寇》"}, {"t": "阳翟田望勤于竿牍……日发数十函不倦。", "b": "宋·朱彧《萍洲可谈》"}], "words": [{"w": "竿牍", "t": "指书信,古代用竹简书写,故称竿牍。"}]}, {"meaning": "计算长状物的单位,竹一根为一竿。", "cites": [{"t": "一径野花香袭体,数竿幽竹绿依依。", "b": "《西游记》"}, {"t": "如果开窗正对着白色墙壁,太单调了,给补上几竿竹子或几棵芭蕉。", "b": "《苏州园林》"}]}, {"meaning": "方言。用于抽旱烟。", "cites": [{"t": "约摸咂完一竿叶子烟的时候,…听见…有人朝房外跑走的脚步声。", "b": "《大波》"}]}, {"meaning": "以竿悬挂。", "cites": [{"t": "应元乘月黑,束槀为人,人竿一灯,立陴郳间。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "竿旌", "t": "旗杆顶端所饰的雉羽"}, {"w": "竿首", "t": "用竿悬首。"}]}, {"meaning": "请托。", "cites": [{"t": "竿摩,谓相逼近也。今俗以事干人者谓之相竿摩。", "b": "《后汉书·董卓传》注"}], "words": [{"w": "竿摩", "t": "干求,请托。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1555wx','段','1','duàn','殳','9','','[{"pinyin": "duàn", "defs": [{"meaning": "(形声。从殳(shū),耑(duān)声。“殳”,是古代的一种兵器,这里用作意符,表示与手持器械的动作有关。金文字形,会意,字形象手持物在山崖中敲棰石之形。本义:锤击)。"}, {"meaning": "同本义。", "cites": [{"t": "段,椎物也…其藉以椎物之石曰碫。", "b": "《说文》"}], "words": [{"w": "段氏", "t": "锻工。古代金工六种之一。主要从事农具制作。"}]}, {"meaning": "分段;截断。", "cites": [{"t": "段,分段也。", "b": "《广韵》"}, {"t": "后人…以段为分段字,读徒乱切。分段字自应作断,盖古今字之不同如此。", "b": "《说文》段玉裁注"}]}, {"meaning": "碫。砺石。", "cites": [{"t": "美人赠我锦绣段。", "b": "张衡《四愁》"}, {"t": "我有一匹好素绢,重之不减锦绣段。", "b": "杜甫《戏为韦偃双松图歌》"}], "words": [{"w": "段工", "t": "周代冶炼金属的工匠有六,其一为段氏,从事铸造田器钱镈等物。"}]}, {"meaning": "身段;体段。指妇女的身段或体态。", "cites": [{"t": "然大段未改,所以认得。", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1556wx','便','1','biàn pián','亻','9','','[{"pinyin": "biàn", "defs": [{"meaning": "便利,方便。", "cites": [{"t": "便,安也。人有不便更之。从人,从更,会意。", "b": "《说文》"}, {"t": "故自谓便人。", "b": "《礼记·表记》。释文:“谓便习也。”"}, {"t": "或谓救之便。", "b": "《战国策·秦策》。注:“利也。”"}, {"t": "恣所便只。", "b": "《楚辞·大招》。注:“犹安也。”"}], "words": [{"w": "简便", "t": "简单方便"}, {"w": "便郵", "t": "顺便替人传送书信的人"}, {"w": "便中", "t": "方便的时候"}, {"w": "便宜施行", "t": "不及请示,自行斟酌情势以处理。也作“便宜行事”,“便宜从事”。"}]}, {"meaning": "灵便;轻捷。", "cites": [{"t": "以枪上刺刀相搏击,而便捷猛鸷终弗逮。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "便環", "t": "轻丽的样子"}, {"w": "便辞", "t": "巧辩的言辞"}, {"w": "便嬖", "t": "口才辩巧,善于逢迎而为人主所亲信的人。"}]}, {"meaning": "有利于;有益于。", "cites": [{"t": "以便事也。", "b": "《吕氏春秋·忠廉》"}, {"t": "便国不必法古。", "b": "《商君书·更法》"}], "words": [{"w": "便地", "t": "有利的地形地势"}, {"w": "便家", "t": "富翁"}, {"w": "便会", "t": "有利时机"}, {"w": "便风", "t": "顺风。"}]}, {"meaning": "熟习。", "cites": [{"t": "布便弓马。", "b": "《三国志·吕布传》"}]}, {"meaning": "尿、屎。", "cites": [{"t": "郎有醉小便殿上。", "b": "《汉书·张安世传》"}], "words": [{"w": "大便", "t": "屎"}, {"w": "小便;粪便", "t": ""}]}, {"meaning": "有利的机会。", "cites": [{"t": "因利乘便,宰割天下,分裂山河。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "悉听尊便;未得其便", "t": ""}]}, {"meaning": "即;就。", "cites": [{"t": "登即相许和,便可作婚姻。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "即从巴峡穿巫峡,便下襄阳向洛阳。", "b": "唐·杜甫《闻官军收河南河北》"}], "words": [{"w": "敌人还来不及逃跑,我们便抓住了他们;举手便打;提脚便踢;我去年便参加了体操队;有了油,发动机便能开动", "t": ""}]}, {"meaning": "纵使;即使。", "cites": [{"t": "休道司马懿、张郃,便是曹睿亲来,有何惧哉!", "b": "《三国演义》"}], "words": [{"w": "他便来,又如何?便是", "t": "即是,就是。"}]}]}, {"pinyin": "pián", "defs": [{"meaning": "(会意。从人,从更。本义:安适)。"}, {"meaning": "同本义。", "cites": [{"t": "便,安也。人有不便更之。", "b": "《说文》"}, {"t": "故自谓便人。", "b": "《礼记·表记》"}, {"t": "或谓救之便。", "b": "《战国策·秦策》"}], "words": [{"w": "便席", "t": "安于席上"}, {"w": "便散", "t": "安适闲散"}, {"w": "便宁", "t": "安宁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1557wx','俩','1','liǎ liǎng','亻','9','','[{"pinyin": "liǎ", "defs": [{"meaning": "(形声。从人,两声。本义:两个)。"}]}, {"pinyin": "liǎng", "defs": [{"meaning": "——见“伎俩”(jìliǎng)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1558wx','贷','1','dài','贝','9','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从贝,代声。从“贝”,表示与钱财有关。本义:施予;给予)。"}, {"meaning": "同本义。", "cites": [{"t": "贷,施也。", "b": "《说文》"}, {"t": "贷,予也。", "b": "《广雅》"}, {"t": "以财投长曰贷。", "b": "《大戴礼记·千乘》"}, {"t": "凡民之货者。", "b": "《周礼·泉府》。司农注:“谓从官借本贾也。”"}, {"t": "又称贷而益之。", "b": "《孟子》"}, {"t": "不贷无出也。", "b": "《庄子·天运》"}, {"t": "贳贷卖买。", "b": "《汉书·食货志下》"}], "words": [{"w": "贷施", "t": "施舍"}, {"w": "贷恤", "t": "赈施抚恤。"}]}, {"meaning": "借出钱财。", "cites": [{"t": "宁积粟腐仓而不忍贷人一斗。", "b": "《潜夫论·忠贵》"}], "words": [{"w": "贷借", "t": "金钱物品的借出和借入"}, {"w": "贷项", "t": "记入账户贷方的账项"}, {"w": "贷卖", "t": "放贷或出卖。"}]}, {"meaning": "借入。", "cites": [{"t": "贷,借也。", "b": "《广雅》"}, {"t": "庄周家贫,故往贷粟于监河侯。", "b": "《庄子·外物》"}], "words": [{"w": "向银行贷款;贷钱", "t": "借钱"}, {"w": "贷赊", "t": "借贷,赊欠。"}]}, {"meaning": "饶恕,宽恕。", "cites": [{"t": "每具狱上闻,辄贷其死。", "b": "《宋史·刑法志》"}, {"t": "有系狱者,皆挠法贷减。", "b": "《旧唐书·王世充传》"}, {"t": "今姑贷汝。", "b": "明·高启《凫藻集》"}], "words": [{"w": "严惩不贷;贷罪", "t": "免罪"}, {"w": "贷减", "t": "宽宥减罪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1559wx','顺','1','shùn','页','9','','[{"pinyin": "shùn", "defs": [{"meaning": "(会意。从页,从巛。页(xié),头。本义:沿着同一方向)。"}, {"meaning": "同本义。", "cites": [{"t": "顺,循也。", "b": "《释名》"}, {"t": "顺彼长道,屈此群丑。", "b": "《诗·鲁颂·泮水》"}, {"t": "曹操自江陵将顺江东下。", "b": "《资治通鉴》"}, {"t": "顺风而呼,声非加疾也,而闻者彰。", "b": "《荀子·劝学》"}], "words": [{"w": "他顺着篱笆一直爬到大门边;顺流", "t": "水顺地势而流泻;顺着水流的方向"}, {"w": "顺衽", "t": "按衣襟的方向顺序"}, {"w": "顺领", "t": "顺着次序"}, {"w": "顺绪", "t": "顺着次序"}, {"w": "顺数", "t": "顺着次序计数。"}]}, {"meaning": "顺从;顺应。", "cites": [{"t": "顺,从也。", "b": "《广韵》"}, {"t": "顺彼远方。", "b": "《礼记·月令·孟秋》"}, {"t": "不识不和,顺帝之则。", "b": "《墨子·天志中》"}, {"t": "顺天之意。", "b": ""}, {"t": "文王顺纣而不敢逆。武王逆纣而不肯顺。", "b": "《庄子·天运》"}, {"t": "多助之至,天下顺之。", "b": "《孟子·公孙丑下》"}, {"t": "平生衣取蔽寒,食取充腹,亦不敢服垢弊以矫俗干名,但顺吾性而已。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "顺情", "t": "依顺人情"}, {"w": "顺率", "t": "顺应天理而统率仁义之师"}, {"w": "顺变达权", "t": "顺应形势变化而权宜行事"}, {"w": "顺风旗", "t": "比喻随声附和,一边倒"}, {"w": "顺时颐养", "t": "顺应季节变化,注意保养身体"}, {"w": "顺守", "t": "遵循正道而固守之"}, {"w": "顺常", "t": "遵循常道、常典"}, {"w": "顺人", "t": "顺从人心"}, {"w": "顺天", "t": "顺应天道"}, {"w": "顺化", "t": "顺应造化"}, {"w": "顺命", "t": "顺从天命"}, {"w": "顺俗", "t": "随顺习俗"}, {"w": "顺时", "t": "顺应时宜"}, {"w": "顺义", "t": "顺从正当的义理"}, {"w": "顺天应人", "t": "顺承天意而合乎民心"}, {"w": "顺脑顺头", "t": "顺顺从从"}, {"w": "顺行", "t": "遵循道理行动"}, {"w": "顺机", "t": "顺循时机。"}]}, {"meaning": "教诲。", "cites": [{"t": "先王有至德要道,以顺天下。", "b": "《孝经·开宗明义章》"}, {"t": "民有心而兵有顺。", "b": "《庄子·天运》"}, {"t": "顺民之经。", "b": "《管子·牧民》"}, {"t": "是夷是训,于帝其顺。", "b": "《史记·宋世家》"}]}, {"meaning": "道理。", "cites": [{"t": "孝悌,天下之大顺也。力田,为生之本也。", "b": "《汉书》"}]}, {"meaning": "合理的。", "cites": [{"t": "名不正,则言不顺,言不顺,则事不成。", "b": "《论语·子路》"}], "words": [{"w": "顺逆", "t": "顺正与邪逆"}, {"w": "顺政", "t": "顺理的政治"}, {"w": "顺言", "t": "顺理的话"}, {"w": "顺成", "t": "因顺理而成功"}, {"w": "顺备", "t": "合理完备。"}]}, {"meaning": "事情进行顺利,合乎心意。", "cites": [{"t": "曹公,豺虎也,兵天子以征四方,动以朝廷为辞,今日拒之,事更不顺。", "b": "《资治通鉴》"}], "words": [{"w": "顺成", "t": "顺利成就"}, {"w": "顺溜纸", "t": "给鬼神烧纸,以求要办的事得以顺溜"}, {"w": "顺济", "t": "顺利地渡过。"}]}, {"meaning": "逻辑上前后保持一致和合条理的。", "cites": [{"t": "文从字顺各识职。", "b": "韩愈《樊绍述墓志铭》"}]}, {"meaning": "和顺。", "cites": [{"t": "知子之顺之,杂佩以问之;知子之好之,杂佩以报之。", "b": "《诗·郑风·女曰鸡鸣》"}], "words": [{"w": "顺女", "t": "和顺的女子"}, {"w": "顺美", "t": "和顺善良"}, {"w": "顺气", "t": "和顺正直之气"}, {"w": "顺顺", "t": "服服帖帖的样子"}, {"w": "顺亲", "t": "相顺相亲"}, {"w": "顺慈", "t": "和顺慈祥。"}]}, {"meaning": "谨慎。", "cites": [{"t": "君子以顺德,积小以高大。", "b": "《易·升》"}, {"t": "故君子不傲,不隐,不瞽,谨顺其身。", "b": "《荀子·劝学》"}, {"t": "故君子顺其在己者而己矣。", "b": "《淮南子·缪称》"}, {"t": "教以顺于接物,推贤进士为务。", "b": "汉·司马迁《报任安书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1560wx','修','1','xiū','亻','9','','[{"pinyin": "xiū", "defs": [{"meaning": "(形声。从彡(shān),攸(yōu)声。“彡”有装饰义。本义:修饰,装饰)。"}, {"meaning": "同本义。", "cites": [{"t": "修,饰也。", "b": "《说文》"}, {"t": "义之修而礼之藏也。", "b": "《礼记·礼运》。注:“犹饰也。”"}, {"t": "美要眇兮宜修。", "b": "《楚辞》"}, {"t": "以修敬也。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "修容", "t": "整饰容貌"}, {"w": "修词", "t": "修饰词句。亦指作文;文辞"}, {"w": "修饰边幅", "t": "形容注意仪容、衣着祳恼"}, {"w": "修娖", "t": "整理修补。"}]}, {"meaning": "整修;修理。", "cites": [{"t": "古不修墓。", "b": "《礼记·檀弓》"}, {"t": "修橹轒辒。", "b": "《孙子·谋攻》"}, {"t": "修守战之具。", "b": "汉·贾谊《过秦论》"}, {"t": "吾妻死,室坏不修。", "b": "归有光《项脊轩志》"}], "words": [{"w": "修娖", "t": "整理修补"}, {"w": "修完补辑", "t": "修葺整治;补缀损缺"}, {"w": "修月", "t": "古代传说月由七宝合成,人间常有八万二千户给它修治。"}]}, {"meaning": "兴建;建造。", "cites": [{"t": "钟鼓不修。", "b": "《吕氏春秋·先已》"}, {"t": "乃重修岳阳楼。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "修堤梁,通沟浍。", "b": "《荀子·王制》"}], "words": [{"w": "修立", "t": "修建"}, {"w": "修治", "t": "制作"}, {"w": "修构", "t": "修建"}, {"w": "修废", "t": "兴复废业"}, {"w": "修营", "t": "修建"}, {"w": "修辟", "t": "修整开垦。"}]}, {"meaning": "整治。", "cites": [{"t": "管子修之。", "b": "《史记·货殖列传》"}, {"t": "外结好孙权,内修政理。", "b": "《三国志·诸葛亮传》"}, {"t": "修之于朝廷。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "修文偃武", "t": "修明文教,停止武备"}, {"w": "修文", "t": "采取措施加强文治,主要指修治典章制度,提倡礼乐教化等"}, {"w": "修近", "t": "整顿内务"}, {"w": "修言", "t": "统一号令"}, {"w": "修事", "t": "治理政事。"}]}, {"meaning": "实行;从事某种活动。", "cites": [{"t": "地之不休。", "b": "《国语·吴语》。注:“垦也。”"}, {"t": "修其宗庙。", "b": "《礼记·中庸》。注:“谓埽粪也。”"}], "words": [{"w": "修全", "t": "补救;变通"}, {"w": "修削", "t": "进攻;砍杀"}, {"w": "修禊", "t": "古代习俗,在三月三日到水边游玩,以祓除不祥。"}]}, {"meaning": "编纂;撰写;写。", "cites": [{"t": "始末修撰,凡十六载。", "b": "《北史·序传》"}], "words": [{"w": "修撰", "t": "编辑又指掌修国史的官"}, {"w": "修文郎", "t": "称阴曹掌著作之官"}, {"w": "修札", "t": "写信。"}]}, {"meaning": "设。置备。", "cites": [{"t": "修其簠簋。", "b": "《国语·周语》。注:“备也。”"}], "words": [{"w": "修名", "t": "修刺。置备名帖,以作通报姓名之用"}, {"w": "修馔", "t": "准备饭食。"}]}, {"meaning": "循;遵循。", "cites": [{"t": "是以圣人不期修古,不法常可。", "b": "《韩非子·五蠹》"}], "words": [{"w": "修今", "t": "拘守现状"}, {"w": "修古", "t": "遵行古道"}, {"w": "修本", "t": "犹溯源"}, {"w": "修名", "t": "循名,依照名称。"}]}, {"meaning": "修订,修改,改正。", "cites": [{"t": "欲自修改。", "b": "《世说新语·自新》"}]}, {"meaning": "长。", "cites": [{"t": "修,长也。", "b": "《广雅》"}, {"t": "德惠修长。", "b": "《史记·秦始皇纪》。索隐:“修亦长也。”"}, {"t": "邹忌修八尺有余。", "b": "《战国策·齐策》"}, {"t": "云髻峨峨,修眉联娟。", "b": "曹植《洛神赋》"}, {"t": "盖简桃核修狭者为之。", "b": "明·魏学洢《核舟记》"}, {"t": "巨身修尾。", "b": "《聊斋志异·促织》"}, {"t": "庞然修尾。", "b": ""}], "words": [{"w": "修龄", "t": "长龄,长寿"}, {"w": "修短固天", "t": "生命的长短本由天定"}, {"w": "修亘", "t": "连绵不断"}, {"w": "修篁", "t": "修筠。长长的竹子。"}]}, {"meaning": "高;大。", "cites": [{"t": "此地有崇山峻岭,茂林修竹。", "b": "王羲之《兰亭集序》"}], "words": [{"w": "修茂", "t": "树木高而繁茂"}, {"w": "修波", "t": "大波"}, {"w": "修峻", "t": "高峻"}, {"w": "修雅", "t": "高雅,不粗俗"}, {"w": "修皙", "t": "身材高而皮肤白。"}]}, {"meaning": "善;美好。", "cites": [{"t": "伊中情之信修兮。", "b": "张衡《思玄赋》"}], "words": [{"w": "修名", "t": "美好的名声"}, {"w": "修直", "t": "高尚正直"}, {"w": "修眸", "t": "漂亮的眼睛;美目"}, {"w": "修禀", "t": "良好的禀赋。"}]}, {"meaning": "致送师长的酬金。", "cites": [{"t": "降说屦,升坐修。", "b": "《礼记·乡饮酒义》。钱宫詹云:“即仪礼之升堂乃羞,今之修爵。”"}], "words": [{"w": "修金", "t": "学费"}, {"w": "修脡", "t": "旧指送给老师的薪金。修,通“脩”。干肉"}, {"w": "修脯", "t": "旧时称送给教师的礼物或酬金"}, {"w": "修馔", "t": "教师的薪金及饭食。修,通脩,束修。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1561wx','俏','1','qiào','亻','9','','[{"pinyin": "qiào", "defs": [{"meaning": "(形声。从人,肖声。本义:相貌美好)。"}, {"meaning": "有利可图。", "cites": [{"t": "没点胆子哪能找到这么俏的事!", "b": "老舍《骆驼祥子》"}]}, {"meaning": "货物销路好。", "cites": [{"t": "这一批货,现在可俏得很呢!", "b": "茅盾《霜叶红似二月花》"}]}, {"meaning": "相似。", "cites": [{"t": "佹佹成者,俏成也,初非成也;佹佹败者,俏败者也,初非败也;故迷生于俏。", "b": "《列子·力命》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1562wx','保','1','bǎo','亻','9','','[{"pinyin": "bǎo", "defs": [{"meaning": "(会意。甲骨文字形,象用手抱孩子形。金文写作从“人”从“子”。后来为了结构的对称,小篆变成“保”,使人不能因形见义了。本义:背子于背)。"}, {"meaning": "同本义。", "cites": [{"t": "负子于背谓之保,引申之,则负之者为保;更引申之,则有保养之义。然则保本象负子于背之义,许君误以为形声,遂取养之义当之耳。", "b": "唐兰《殷墟文字记》"}]}, {"meaning": "护养;育。", "cites": [{"t": "保,养也。", "b": "《说文》"}, {"t": "若保赤子。", "b": "《书·康诰》"}, {"t": "保抱携持厥妇子。", "b": "《书·召诰》"}, {"t": "长之养之,如保赤子。", "b": "《荀子·议兵》"}, {"t": "儒者之道,古之人若保赤子。", "b": "《孟子·藤文公上》"}], "words": [{"w": "保艾", "t": "安养;养育"}, {"w": "保赤", "t": "抚育幼孩。"}]}, {"meaning": "保佑。", "cites": [{"t": "天地格保。", "b": "《书·召诰》"}], "words": [{"w": "保佐", "t": "保佑;佐助"}, {"w": "保禳", "t": "祈祷消除灾祸。"}]}, {"meaning": "保护;保全;守住。", "cites": [{"t": "父子相保全。", "b": "《淮南子·人间训》"}, {"t": "少有强者不可保。", "b": "唐·韩愈《祭十二郎文》"}, {"t": "有朕位几不保。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "保銮", "t": "保护天子的亲近卫士"}, {"w": "保固", "t": "保卫固守"}, {"w": "保身", "t": "保全身体。"}]}, {"meaning": "保持。", "cites": [{"t": "至今保藏。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "保值", "t": "保持价值"}, {"w": "保光", "t": "保持并发扬光大。"}]}, {"meaning": "保证;担保。", "cites": [{"t": "保为将军破之。", "b": "《资治通鉴》"}], "words": [{"w": "保修", "t": "保养修理"}, {"w": "旱涝保收;保官", "t": "担任保护职能的官员。"}]}, {"meaning": "占有;拥有。", "cites": [{"t": "虽慈父不能保其子。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "保据", "t": "占据"}, {"w": "保宁", "t": "保有并使之安宁。"}]}, {"meaning": "保举;保荐。", "cites": [{"t": "都保你二位做大官。", "b": "《水浒传》"}], "words": [{"w": "保题议叙", "t": "写奏本保荐有功人员"}, {"w": "保题", "t": "向上推荐"}, {"w": "保案", "t": "保举下属的文件。"}]}, {"meaning": "依靠;仗持。", "cites": [{"t": "保君父之命而享其生禄,于是乎得人。", "b": "《左传·僖公二十年》"}], "words": [{"w": "保山", "t": "依山固守"}, {"w": "保栖", "t": "据山以守。"}]}, {"meaning": "保育幼儿的妇女。", "cites": [{"t": "国君世子生,…保受,乃负之。", "b": "《礼记·内则》"}]}, {"meaning": "保护婴儿的包裹衣。", "cites": [{"t": "夫知保抱携持厥妇子。", "b": "《书·召诰》"}, {"t": "措之于参保介之御间。", "b": "《礼记·月令》"}, {"t": "昔成王幼小,越在襁保。", "b": "《后汉书·桓郁传》"}]}, {"meaning": "作保证的人。", "cites": [{"t": "然后导以取保。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "作保;觅保;保山", "t": "媒人;保人"}, {"w": "保中", "t": "在债务关系中居中担保的人。"}]}, {"meaning": "小城(此义后来写作“堡”)。", "cites": [{"t": "南山是保。", "b": "《诗·大雅·崧高》"}, {"t": "焚我郊保。", "b": "《左传·襄公八年》"}, {"t": "战于郎。公叔禺人遇负杖入保者息。", "b": "《礼记·檀弓下》"}, {"t": "所过之邑(城市),大国守城,小国入保。", "b": "《庄子·盗跖》"}]}, {"meaning": "珍贵之物。", "cites": [{"t": "展九鼎保玉。", "b": "《史记·周本纪》"}, {"t": "其形虽有所小用哉然未可以保于周室之九鼎也。", "b": "《淮南子·俶真》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1563wx','促','1','cù','亻','9','','[{"pinyin": "cù", "defs": [{"meaning": "(形声。从人,足声。本义:紧迫。又指急促,赶快)。"}, {"meaning": "同本义。", "cites": [{"t": "促,速也。", "b": "《广韵》"}, {"t": "促,速也。", "b": "《汉书·高帝纪》注"}, {"t": "长来觉日月益促。", "b": "唐·柳宗元《与萧俛书》"}], "words": [{"w": "促柱", "t": "急切的絃音"}, {"w": "促装", "t": "急忙整治行装"}, {"w": "促速", "t": "急速"}, {"w": "促病", "t": "急病。"}]}, {"meaning": "短。时间、距离拉得不长的。", "cites": [{"t": "可命促而意长。", "b": "晋·陆机《吊魏武帝文》"}], "words": [{"w": "促节", "t": "乐曲快板短促"}, {"w": "促死", "t": "立刻死去"}, {"w": "促生", "t": "短促的生命"}, {"w": "促促", "t": "短短的。"}]}, {"meaning": "使加快,催。", "cites": [{"t": "公屡促之,必如约。", "b": "崔铣《记王忠肃公翱三事》"}], "words": [{"w": "月色促归人", "t": ""}]}, {"meaning": "靠近,靠拢。", "cites": [{"t": "合樽促席。", "b": "晋·左思《蜀都赋》"}], "words": [{"w": "促席", "t": "坐席很挨近"}, {"w": "促眉", "t": "蹙眉,皱眉"}, {"w": "促边", "t": "紧靠边沿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1564wx','俄','1','é','亻','9','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从人,我声。本义:倾斜)。"}, {"meaning": "同本义。", "cites": [{"t": "俄,行顷也。", "b": "《说文》"}, {"t": "侧弁之俄。", "b": "《诗·小雅·宾之初筵》"}, {"t": "俄轩冕。", "b": "扬雄《羽猎赋》。注:“卬也。”"}, {"t": "于时曜灵俄景。", "b": "张衡《归田赋》"}], "words": [{"w": "俄景", "t": "偏西的阳光。"}]}, {"meaning": "短暂的时间,一会儿。", "cites": [{"t": "俄而可以为其有矣。", "b": "《公羊传·桓公二年》"}, {"t": "俄见小虫跃起。", "b": "《聊斋志异·促织》"}, {"t": "俄,百千人大呼。", "b": "《虞初新志·秋声诗自序》"}, {"t": "老人俄死,田宅没官。", "b": "《笑林》"}], "words": [{"w": "俄顷时", "t": "不一会儿"}, {"w": "俄且", "t": "即将,马上"}, {"w": "俄延", "t": "拖延,迟延"}, {"w": "俄瞬", "t": "短暂的时间,转瞬间"}, {"w": "俄刻", "t": "顷刻,不长的时间"}, {"w": "俄忽", "t": "一会儿,极短的时间。"}]}, {"meaning": "俄罗斯;俄罗斯人。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1565wx','俐','1','lì','亻','9','','[{"pinyin": "lì", "defs": [{"meaning": "——“伶俐”(línglì):聪慧;机灵。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1566wx','侮','1','wǔ','亻','9','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从人,每声。本义:轻慢,不敬重)。"}, {"meaning": "同本义。", "cites": [{"t": "不侵侮。", "b": "《礼记·曲礼》"}], "words": [{"w": "侮易", "t": "轻慢。"}, {"w": "侮慢", "t": "轻侮傲慢,不敬重他人"}, {"w": "侮忽", "t": "轻视,轻慢"}, {"w": "侮法", "t": "藐视和歪曲法令"}, {"w": "侮笑", "t": "轻慢嘲笑"}, {"w": "侮傲", "t": "傲视和轻慢他人,没有礼貌"}, {"w": "侮诮", "t": "以轻慢的态度加以讥嘲"}, {"w": "侮剧", "t": "轻慢戏弄"}, {"w": "侮薄", "t": "轻视;鄙薄。"}]}, {"meaning": "欺负。", "cites": [{"t": "不侮鳏寡。", "b": "《左传·昭公元年》"}, {"t": "有侮臣者。", "b": "《墨子·公输》"}, {"t": "犯笑侮。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "侮手", "t": "动手;对打"}, {"w": "侮谇", "t": "欺侮斥责"}, {"w": "侮夺", "t": "侮慢他人,侵夺他人所有之物"}, {"w": "侮害", "t": "欺侮侵害"}, {"w": "侮折", "t": "欺侮折辱"}, {"w": "侮文", "t": "歪曲法律条文以行私作恶。"}]}, {"meaning": "用手遮盖。", "cites": [{"t": "侮着眼只是啼哭。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "侮眼啼哭", "t": "捂着眼睛,掩面哭泣。"}]}, {"meaning": "古时奴婢的贱称。", "cites": [{"t": "秦晋之间骂奴婢曰侮。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1567wx','俭','1','jiǎn','亻','9','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从人,佥(qiān)声。本义:自我约束,不放纵)。"}, {"meaning": "同本义。", "cites": [{"t": "俭,约也。", "b": "《说文》"}, {"t": "君子以俭德避难。", "b": "《易·否象传》"}, {"t": "俭德之共也。", "b": "《左传·庄公二十四年》"}, {"t": "严公子广而俭,文而有礼。", "b": "《左传·僖公二十三年》"}, {"t": "恭俭下人。", "b": "司马迁《报任安书》"}], "words": [{"w": "俭貌", "t": "态度谦逊"}, {"w": "俭退", "t": "俭约谦让"}, {"w": "俭然", "t": "自谦的样子。"}]}, {"meaning": "节俭,节省。", "cites": [{"t": "俭于财用,节于衣食。", "b": "《韩非子·难二》"}, {"t": "俭,德之共也;侈,恶之大也。", "b": "《左传·庄公二十四年》"}, {"t": "今先君俭而君侈,令德替矣。", "b": "《国语·鲁语上》"}, {"t": "俭素为美。", "b": "清·梁启超《谭嗣同传》"}, {"t": "以俭为美。", "b": ""}, {"t": "以俭相诟病。", "b": ""}, {"t": "由俭入奢易。", "b": ""}], "words": [{"w": "俭克", "t": "勤俭而能克制"}, {"w": "俭礼", "t": "俭约的礼仪"}, {"w": "俭德", "t": "俭约的品德"}, {"w": "俭戚", "t": "俭约而悲伤。"}]}, {"meaning": "贫乏;贫苦。", "cites": [{"t": "时岁荒民俭。", "b": "《后汉书》"}], "words": [{"w": " 俭贫", "t": "贫乏"}, {"w": "俭乏", "t": "贫乏,生活困难"}, {"w": "俭腹", "t": "腹中空虚。喻指知识贫乏。"}]}, {"meaning": "歉收。", "cites": [{"t": "丰则籴,俭则粜。", "b": "房玄龄《晋书》"}, {"t": "荆扬稻收俭薄。", "b": "《后汉书·陈忠传》"}], "words": [{"w": "俭年", "t": "歉收的年景"}, {"w": "俭时", "t": "歉收的时日"}, {"w": "俭岁", "t": "荒年;歉收的年岁。"}]}, {"meaning": "薄;少。", "cites": [{"t": "恭俭而好礼者,宜歌《小雅》。", "b": "《礼记》"}], "words": [{"w": "俭率", "t": "俭薄"}, {"w": "俭葬", "t": "薄葬"}, {"w": "俭薄", "t": "犹言微薄。"}]}, {"meaning": "险要。", "cites": [{"t": "俗险而百姓不一。", "b": "《荀子·富国》"}, {"t": "惠而不俭,直而不径。", "b": "《大戴礼·曾子立事篇》"}, {"t": "不兴险行以徼幸。", "b": "《大戴礼·曾子本孝篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1568wx','俗','1','sú','亻','9','','[{"pinyin": "sú", "defs": [{"meaning": "(形声。从人,谷(gǔ)声。习俗是人的行为,所以从人。本义:风俗)。"}, {"meaning": "同本义(长期形成的礼节、习惯)。", "cites": [{"t": "俗,习也。", "b": "《说文》"}, {"t": "六曰以俗教安。", "b": "《周礼·大司徒》"}, {"t": "入国而问俗。", "b": "《礼记·曲礼》"}, {"t": "循俗未足多也。", "b": "《淮南子·泛论》"}, {"t": "俗主亏情。", "b": "《吕氏春秋·情欲》。注:“凡君也。”"}, {"t": "移风易俗,天下皆宁。", "b": "《荀子·乐论》"}, {"t": "亦不敢服垢弊以矫俗干名,但顺吾性而已。", "b": "宋·司马光《训俭示康》"}, {"t": "淫侈之俗日日以长,是天下之贼也。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "风俗", "t": "风,指一时普遍流行的风气;俗,指长期形成的礼节、习惯"}, {"w": "习俗", "t": "习惯和风俗"}, {"w": "民俗", "t": "人民群众的风俗习惯"}, {"w": "俗忌", "t": "一般习俗所忌讳的事"}, {"w": "俗化", "t": "民俗教化。"}]}, {"meaning": "佛教称尘世间为俗,与出家相对。", "cites": [{"t": "时有沙门释惠林…世祖命使还俗。", "b": "《宋书·徐堪之传》"}], "words": [{"w": "俗计", "t": "尘世间的生计"}, {"w": "俗缘", "t": "尘缘。指佛门信徒与世俗的人际关系"}, {"w": "俗本", "t": "民间通行的版本"}, {"w": "俗骨", "t": "尘世间人的资质或禀赋"}, {"w": "俗界", "t": "凡界,尘界"}, {"w": "俗纷", "t": "尘世的纷扰"}, {"w": "俗声,俗喧", "t": "尘世的喧扰"}, {"w": "俗间", "t": "世间,尘间。"}]}, {"meaning": "一般人;百姓。", "cites": [{"t": "俗之所欲,因而予之。", "b": "《史记·管晏列传》"}, {"t": "是己而非人,俗之同病。", "b": "清·刘开《问说》"}], "words": [{"w": "僧俗", "t": "僧尼和一般人"}, {"w": "俗家", "t": "指一般人家。对出家人而言"}, {"w": "俗姓", "t": "僧侣未出家前的姓氏"}, {"w": "俗父", "t": "出家人称生父为俗父"}, {"w": "俗众", "t": "群众,普通人"}, {"w": "俗圣", "t": "凡庸人与圣人。"}]}, {"meaning": "平凡;普通;一般。", "cites": [{"t": "请回俗士驾,为君谢逋客。", "b": "孔稚圭《北山移文》"}, {"t": "察其本,乃与俗议之异。", "b": "《史记·李斯列传》"}, {"t": "不论姚花与魏花,只供俗目陪妖姹。", "b": "宋·韩琦《和袁陟节椎龙兴寺芍药》"}, {"t": "夫移风易俗,使天下回心而乡道,类非俗吏之所能为也。", "b": "《汉书·贾谊传》"}], "words": [{"w": "俗手", "t": "技艺、本领平庸的人"}, {"w": "俗俚", "t": "不讲究礼仪;粗俗"}, {"w": "俗嗒嗒", "t": "俗气,无聊"}, {"w": "俗吏", "t": "没有深识远见的平庸官吏"}, {"w": "俗材", "t": "平庸之人"}, {"w": "俗句", "t": "平庸熟滥的诗句"}, {"w": "俗师", "t": "浅薄凡庸的教师、术士"}, {"w": "俗辈", "t": "平庸鄙俗一类人"}, {"w": "俗劣", "t": "平庸鄙陋"}, {"w": "俗手", "t": "技艺平庸的人"}, {"w": "俗笔", "t": "平庸的笔法"}, {"w": "俗调", "t": "平庸鄙俗的情调"}, {"w": "俗主", "t": "平庸的君主。"}]}, {"meaning": "庸俗,不雅,缺乏修养的。", "cites": [{"t": "人瘦尚可肥,士俗不可医。", "b": "苏轼《于潜僧绿筠轩》"}, {"t": "拨乱属膏圣,俗儒安可通。", "b": "唐·李白《登广武古战场怀古诗》"}, {"t": "众人见黛玉年貌虽小,其举止言谈不俗。", "b": "《红楼梦》"}], "words": [{"w": "鄙俗;俗不可耐;俗骨", "t": "庸俗的气质。别于仙骨而言"}, {"w": "俗夫", "t": "俗人,俗士,鄙俗之人"}, {"w": "俗陋", "t": "庸俗鄙陋"}, {"w": "俗物", "t": "对世俗庸人的鄙称"}, {"w": "俗眼", "t": "浅薄势利的世俗人的眼睛"}, {"w": "俗野", "t": "庸俗粗野。"}]}, {"meaning": "世俗。", "cites": [{"t": "少无适俗韵,性本爱丘山。", "b": "晋·陶渊明《归园田居》"}, {"t": "吾不能变心以从俗兮,固将愁苦而终穷。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "俗家", "t": "世俗之家。也指僧人父母之家"}, {"w": "俗流", "t": "世俗之辈"}, {"w": "俗客", "t": "世俗的人"}, {"w": "俗念", "t": "世俗的想法。"}]}, {"meaning": "通俗,流行。", "cites": [{"t": "寡人非能好先王之乐也,直好世俗之乐耳。", "b": "《孟子·梁惠王下》"}, {"t": "孙卿之言既,又因俗说而论之。", "b": "《汉书·刑法志》"}], "words": [{"w": "通俗", "t": "俗话,通俗的谈话"}, {"w": "俗读", "t": "一般人习惯的读音"}, {"w": "俗书", "t": "通俗流行的书体或字。"}]}, {"meaning": "从其习俗。", "cites": [{"t": "上不循于乱世之君,下不俗于乱世之民。", "b": "《荀子》"}]}, {"meaning": "厌烦,腻味。", "cites": [{"t": "若就是这句话呢,我们姑娘在时,我也跟着听俗了。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1569wx','俘','1','fú','亻','9','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从人,孚(fú)声。本义:俘获)。"}, {"meaning": "同本义。", "cites": [{"t": "俘,军所获也。", "b": "《说文》"}, {"t": "以为俘聝。", "b": "《春秋传》。按,死者取左耳为聝,生者为俘。"}, {"t": "俘,取也。", "b": "《尔雅》。李注:“囚敌曰俘。”"}, {"t": "俘二百五十人。", "b": "《左传·宣公二年》"}], "words": [{"w": "生俘", "t": "活捉"}, {"w": "俘斩", "t": "俘获斩首"}, {"w": "俘系", "t": "俘获拴缚"}, {"w": "俘执", "t": "俘获擒捉"}, {"w": "俘敌数千", "t": ""}]}, {"meaning": "缴获;指用战争手段获取对方土地或物质等。", "cites": [{"t": "俘厥宝玉。", "b": "《书·汤誓》"}, {"t": "俘我王官。", "b": "《左传·成公十三年》"}], "words": [{"w": "俘劫", "t": "侵犯掠夺"}, {"w": "俘邑", "t": "在战争中获取,因而对其有所有权的城邑。"}]}, {"meaning": "俘虏。", "cites": [{"t": "夷不乱华,俘不干盟。", "b": "《左传·定公十年》"}], "words": [{"w": "伤俘", "t": "受伤的俘虏"}, {"w": "战俘", "t": "战争中捉住的敌人。"}]}, {"meaning": "珍贵之物。", "cites": [{"t": "齐人来归卫俘。", "b": "《左传·庄公六年经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1570wx','信','1','xìn','亻','9','','[{"pinyin": "xìn", "defs": [{"meaning": "(会意。从人,从言。人的言论应当是诚实的。本义:真心诚意)。"}, {"meaning": "同本义。", "cites": [{"t": "信,诚也。", "b": "《说文》"}, {"t": "有诸已之谓信。", "b": "《孟子》"}, {"t": "信,言合于意也。", "b": "《墨子经》"}, {"t": "信者,诚也。专一不移也。", "b": "《白虎通·情性》"}, {"t": "定身以行事谓之信。", "b": "《国语·晋语》"}, {"t": "期果言当谓之信。", "b": "《贾子道术》"}, {"t": "民不求其所欲而得之谓之信。", "b": "《礼记·经解》"}, {"t": "信誓旦旦。", "b": "《诗·卫风·氓》"}, {"t": "反贼无信!吾不幸误中汝奸计也!", "b": "《三国演义》"}, {"t": "牺牲玉帛,弗敢加也,必以信。", "b": "《左传·庄公十年》"}, {"t": "信而见疑。", "b": "《史记·屈原贾生列传》"}, {"t": "则是无信。", "b": "《世说新语·方正》"}], "words": [{"w": "信行", "t": "信用;守诺言"}, {"w": "信人", "t": "讲守信用的人。"}]}, {"meaning": "真实,不虚伪。", "cites": [{"t": "信言不美,美言不信。", "b": "《老子》"}, {"t": "谓为信然。", "b": "《三国志·诸葛亮传》"}, {"t": "其事信。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "信官", "t": "诚实不欺的官员"}, {"w": "信赏", "t": "悬赏"}, {"w": "信赏钱", "t": "悬赏金"}, {"w": "信人", "t": "诚实的人。"}]}, {"meaning": "相信;信任。", "cites": [{"t": "不我信兮。", "b": "《诗·邶风·击鼓》"}, {"t": "且单于信女,使昫人死生。", "b": "《史记·苏武传》"}, {"t": "不自信。", "b": "《战国策·齐策》"}, {"t": "亲之信之。", "b": "诸葛亮《出师表》"}, {"t": "犹信。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "笑而不信。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "信不及", "t": "不能相信;不敢相信"}, {"w": "不信邪;信得过;信爱", "t": "信任喜爱"}, {"w": "信纳", "t": "相信采纳"}, {"w": "信不信由你;听其言而信其行", "t": ""}]}, {"meaning": "守信用。", "cites": [{"t": "已诺不信则兵弱。", "b": "《荀子·富国》"}, {"t": "小信未孚。", "b": "《左传·庄公十年》"}, {"t": "此四君者,皆明智而忠信。", "b": "贾谊《过秦论》"}, {"t": "信义著于四海。", "b": "晋·陈寿《三国志·诸葛亮传》"}, {"t": "信义安所见。", "b": "《汉书·李广苏建传》"}, {"t": "虏帅失信。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "住宿两夜。", "cites": [{"t": "有客宿宿,有客信信。", "b": "《诗·周颂·有客》"}, {"t": "子庚门于纯门,信于城下而还。", "b": "《左传·襄公十八年》"}]}, {"meaning": "证实;应验。", "cites": [{"t": "其精甚真,其中有信。", "b": "《老子》"}]}, {"meaning": "知晓。", "cites": [{"t": "我父母皆仙人,何可以貌信其年岁乎?", "b": "《聊斋志异》"}, {"t": "早信此生终不遇,当年悔草《长杨赋》。", "b": "陆游《蝶恋花》"}], "words": [{"w": "信道", "t": "知道;料道。"}]}, {"meaning": "信约;盟约。", "cites": [{"t": "以继好结信。", "b": "《左传·襄公元年》"}]}, {"meaning": "符契;凭证。", "cites": [{"t": "行而无信。", "b": "《战国策·燕策》"}], "words": [{"w": "信笼", "t": "内盛物品后封口加盖印信的箱笼"}, {"w": "刻木为信", "t": ""}]}, {"meaning": "持有信物的外交使臣或传送函件或口头消息的人。", "cites": [{"t": "宜急追信改书。", "b": "《资治通鉴》"}, {"t": "越绝粮,使素忠为信,告粜于吴。", "b": "《越绝书》"}, {"t": "司空郑冲驰遣信就阮籍求文。", "b": "《世说新语·文学》"}], "words": [{"w": "信使", "t": "使者。"}]}, {"meaning": "音讯。", "cites": [{"t": "不见眼中人,天长音信断。", "b": "李白《大堤曲》"}], "words": [{"w": "信耗", "t": "信息;消息"}, {"w": "信炮", "t": "按约定信号所放之炮"}, {"w": "信音", "t": "音信;消息"}, {"w": "通风报信;凶信;信鸽;信鸿;信鸟;信问", "t": "信息。"}]}, {"meaning": "书信,信件(晚起义。先秦两汉的书信又用“书”字表示)。", "cites": [{"t": "函使报信。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "信局", "t": "投递信件的机构"}, {"w": "私信;挂号信;平信;死信;匿名信;信箱;信筒;信简", "t": "书信。"}]}, {"meaning": "放任;随便。", "cites": [{"t": "要不拿出纲纪来,信着他胡行乱做,就不成个人家。", "b": "《醒世姻缘传》"}, {"t": "低眉信手续续弹,说尽心中无限事。", "b": "白居易《琵琶行》"}], "words": [{"w": "信口胡沁", "t": "信口胡吣。不顾事实,随便乱说"}, {"w": "信着", "t": "任着;任凭"}, {"w": "信手拈来;信步", "t": ""}]}, {"meaning": "果真,的确。", "cites": [{"t": "若妻信病,赐小豆四十斛,宽假限日。", "b": "《史记·华佗传》"}, {"t": "烟涛微茫信难求。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "信知生难恶。", "b": "唐·杜甫《兵车行》"}, {"t": "信造化之尤物。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1571wx','皇','1','huáng','白','9','','[{"pinyin": "huáng", "defs": [{"meaning": "(象形。金文,象灯火辉煌形。上面的三点,象灯光参差上出之形;中间的部分象灯缸;下面的“土”是灯柱。“皇”即“煌”的古字。本义:灯火辉煌)。"}, {"meaning": "同本义。", "cites": [{"t": "服其命服,朱芾斯皇。", "b": "《诗·小雅·采芑》"}, {"t": "騐皇者,煌煌也。", "b": "《书·帝命》"}]}, {"meaning": "大。", "cites": [{"t": "皇,大也。从自。自始也。始王者,三皇大君也。", "b": "《说文》"}, {"t": "建用皇极。", "b": "《书·洪范》"}, {"t": "上帝是皇。", "b": "《诗·周颂·执竞》"}], "words": [{"w": "皇祜", "t": "大福"}, {"w": "皇业", "t": "大业;帝王的事业"}, {"w": "皇道", "t": "大道"}, {"w": "皇竹", "t": "大竹名。"}]}, {"meaning": "美好。", "cites": [{"t": "皇,美也。", "b": "《广雅·释诂一》"}, {"t": "继序其皇之。", "b": "《诗·周颂·烈文》。传:“美也。”"}, {"t": "皇以间之。", "b": "《诗·周颂·桓》"}], "words": [{"w": "皇土", "t": "美土"}, {"w": "皇直", "t": "美好忠直"}, {"w": "皇想", "t": "美好的怀念。"}]}, {"meaning": "空闲的;有闲暇的。", "cites": [{"t": "不皇出矣。", "b": "《诗·小雅·渐渐之石》"}, {"t": "不皇朝矣。", "b": ""}, {"t": "不僭不滥,不敢怠皇,命以多福。", "b": "《左传·哀公五年》"}, {"t": "孤与其二三臣悼心失图社稷之不皇。", "b": "《左传·昭公七年》"}], "words": [{"w": "皇宁", "t": "闲适;安闲"}, {"w": "皇暇", "t": "空闲;闲暇。"}]}, {"meaning": "", "cites": [{"t": "大臣皆皇惧而退。", "b": "宋·佚名《新编五代史平话》"}], "words": [{"w": "皇惧", "t": "恐慌害怕"}, {"w": "皇遽", "t": "惊恐"}, {"w": "皇骇", "t": "惊慌;恐惧"}, {"w": "皇乱", "t": "惊慌失措。"}]}, {"meaning": "黄白色。", "cites": [{"t": "皇驳其马。", "b": "《诗·豳风·东山》"}], "words": [{"w": "皇驳", "t": "黄白色与赤白色。"}]}, {"meaning": "指天。", "cites": [{"t": "思皇多士。", "b": "《诗·大雅·文王》。传:“天也。”"}, {"t": "皇霸。皇者天也。", "b": "《风俗通》"}], "words": [{"w": "皇命", "t": "天命"}, {"w": "皇穹", "t": "犹皇天"}, {"w": "皇门", "t": "天门"}, {"w": "皇皇天帝", "t": "天。"}]}, {"meaning": "指天神。", "cites": [{"t": "吉日兮辰良,穆将愉兮上皇。", "b": "《楚辞·九歌·东皇太一》"}], "words": [{"w": "皇天上帝", "t": "天帝,上帝"}, {"w": "皇公", "t": "天帝"}, {"w": "皇穹", "t": "指天帝"}, {"w": "皇祗", "t": "天神与地神的并称。"}]}, {"meaning": "君主,天子,皇帝。", "cites": [{"t": "皇丈受天子之富贵。", "b": "元·佚名《武王伐纣平话》"}], "words": [{"w": "皇统", "t": "历代帝王相传的世系"}, {"w": "皇丈", "t": "皇帝的岳父"}, {"w": "皇极", "t": "帝王治世的准则"}, {"w": "皇太孙", "t": "太子死,以太子的儿子为皇储,称为皇太孙。"}]}, {"meaning": "鸟名。凰的古字。传说中的雌凤 。如;皇鸟(传说中的雌凤);皇翼(凤凰的羽翼。借指笙管)。"}, {"meaning": "对神明的敬称。", "cites": [{"t": "伏羲、女娲、神农为三皇。", "b": "《春秋·元命苞》"}], "words": [{"w": "皇祗", "t": "地神"}, {"w": "皇娲", "t": "指女娲氏"}, {"w": "皇羲", "t": "指伏羲氏"}, {"w": "皇娥", "t": "传说中古帝少昊的母亲。"}]}, {"meaning": "匡正。", "cites": [{"t": "皇,正也。", "b": "《释言》"}, {"t": "四国是皇。", "b": "《诗·豳风·破斧》"}, {"t": "皇我万民。", "b": "《穆天子传》"}]}, {"meaning": "往。", "cites": [{"t": "先祖是皇。", "b": "《诗·小雅·信南山》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1572wx','泉','1','quán','水','9','','[{"pinyin": "quán", "defs": [{"meaning": "(象形。甲骨文字形。象水从山崖泉穴中流出的样子。本义:泉水)。"}, {"meaning": "同本义。", "cites": [{"t": "泉,人原也。象水流出成川形。字亦作洤。", "b": "《说文》"}, {"t": "如彼泉流。", "b": "《诗·小雅·小旻》"}, {"t": "泉之竭矣。", "b": "《诗·大雅·召旻》。传:“泉水从中以益者也。”"}, {"t": "泉涓涓而始流。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "酿泉为酒。", "b": "宋·欧阳修《醉翁事记》"}, {"t": "泉香而酒洌。", "b": ""}, {"t": "泉而茗者。", "b": "明·袁宏道《满井游记》"}, {"t": "有泉可汲。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "温泉;矿泉;清泉;泉根", "t": "泉源"}, {"w": "泉脉", "t": "地下伏流的泉水"}, {"w": "泉涌", "t": "泉川喷涌"}, {"w": "泉鱼", "t": "渊鱼"}, {"w": "泉绅", "t": "从高山上飞泻下来的泉水"}, {"w": "泉韵", "t": "泉水声。"}]}, {"meaning": "地下水。", "cites": [{"t": "若阙地及泉,隧而相见,其谁曰不然?", "b": "《左传》"}]}, {"meaning": "泉下,指人死后所在的地方。", "cites": [{"t": "有志者入泉,无为者住世,岂佳事乎?", "b": "鲁迅《书信》"}], "words": [{"w": "泉台之望", "t": "指死者的希望"}, {"w": "泉厥", "t": "黄泉;地下"}, {"w": "泉乡", "t": "泉下"}, {"w": "泉扇", "t": "墓门。亦指阴间"}, {"w": "泉里", "t": "黄泉之下。"}]}, {"meaning": "帛币。古钱币名。", "cites": [{"t": "货泉径一寸,重五铢,右文曰货,左文曰泉,直一也。", "b": "《周礼·外府》注"}], "words": [{"w": "泉儿", "t": "古代钱币的通称"}, {"w": "泉币", "t": "钱币,货币。又称泉货"}, {"w": "泉金", "t": "金钱"}, {"w": "泉布", "t": "帛币和布币"}, {"w": "泉刀", "t": "泉币与刀币"}, {"w": "泉布先生", "t": "钱币的谑称。"}]}, {"meaning": "泉眼。", "cites": [{"t": "熊咆龙吟殷岩泉。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "有泉侧出。", "b": "宋·王安石《游褒禅山记》"}, {"t": "临于泉上。", "b": "宋·欧阳修《醉翁亭记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1573wx','鬼','1','guǐ','鬼','9','','[{"pinyin": "guǐ", "defs": [{"meaning": "(象形。甲骨文字形,下面是个“人”字,上面象一个可怕的脑袋(非“田”字),是人们想象中的似人非人的怪物。“鬼”是汉字部首之一,从“鬼”的字大多与迷信、鬼神有关。本义:迷信的人认为人死后有“灵魂”,称之为“鬼”)。"}, {"meaning": "同本义。", "cites": [{"t": "鬼,人所归为鬼。", "b": "《说文》"}, {"t": "众生必死,死必归士,此之谓鬼。", "b": "《礼记·祭义》"}, {"t": "载鬼一车。", "b": "《易·睽》"}, {"t": "为鬼为蜮。", "b": "《诗·小雅·何人斯》"}, {"t": "苍颉作书鬼夜哭。", "b": "《淮南子·本经》"}, {"t": "身既死兮神以灵,子魂魄兮为鬼雄。", "b": "《楚辞·屈原·国殇》"}, {"t": "吾作此书时,尚是世中一人;汝看此书时,吾已成为阴间一鬼。", "b": "林觉民《与妻书》"}], "words": [{"w": "鬼伯", "t": "鬼王"}, {"w": "鬼雄", "t": "鬼中的强者"}, {"w": "鬼物", "t": "鬼怪,鬼魅。有别于生人,故称鬼物"}, {"w": "鬼教", "t": "说阴间鬼神之事。"}]}, {"meaning": "万物的精怪。", "cites": [{"t": "鬼者,老物之精也。", "b": "《论衡·订鬼》"}, {"t": "庶人庶士无庙,死曰鬼。", "b": "《礼记·祭法》"}, {"t": "山鬼吹灯灭,厨人语夜阑。", "b": "唐·杜甫《移居公安山馆》"}, {"t": "僧是愚氓犹可训,妖为鬼蜮必成灾。", "b": "毛泽东《七律·和郭沫若同志》"}], "words": [{"w": "鬼王", "t": "群鬼的首领"}, {"w": "鬼车", "t": "传说中长有九头的妖鸟"}, {"w": "鬼名", "t": "神灵统率之兵。即神兵"}, {"w": "鬼卒", "t": "即鬼兵、神兵。"}]}, {"meaning": "用于对小孩等表示爱昵的称呼 。如小鬼;机灵鬼。"}, {"meaning": "对人表示轻蔑的称呼。如小气鬼,吝啬鬼。"}, {"meaning": "隐密不测。", "cites": [{"t": "故明主之行制也天,其用人也鬼。", "b": "《韩非子·八经》"}], "words": [{"w": "鬼促促", "t": "鬼鬼祟祟"}, {"w": "鬼诨", "t": "应酬;应付"}, {"w": "鬼慌", "t": "暗里着急;心慌。"}]}, {"meaning": "慧黠,机警。", "cites": [{"t": "这孩子真鬼", "b": ""}, {"t": "突兀压神州,峥嵘如鬼工。", "b": "唐·岑参《高适薛据同登慈恩寺》"}], "words": [{"w": "鬼工", "t": "形容制作的精巧,非人力所能及"}, {"w": "鬼才", "t": "才情怪谲,资质出众的人"}, {"w": "鬼幻", "t": "似鬼神般变化莫测"}, {"w": "鬼出电入", "t": "比喻出没迅速而难测。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1574wx','侵','1','qīn','亻','9','','[{"pinyin": "qīn", "defs": [{"meaning": "(会意。小篆字形从人,手(又)拿扫帚,一步一步地扫地。本义:渐进)。"}, {"meaning": "同本义。", "cites": [{"t": "侵,渐进也。", "b": "《说文》"}, {"t": "侵淫谿谷。", "b": "宋玉《风赋》"}, {"t": "侵淫促节。", "b": "司马相如《上林赋》。注:“渐进之貌。”"}], "words": [{"w": "侵润", "t": "逐渐发展"}, {"w": "侵寻", "t": "渐进"}, {"w": "侵淫", "t": "渐进的样子"}, {"w": "侵寻", "t": "范围逐渐扩大。"}]}, {"meaning": "侵犯:进攻。", "cites": [{"t": "凡师有钟鼓曰伐,无曰侵,轻曰袭。", "b": "《左传·庄公二十九年》"}, {"t": "袭侵之事。", "b": "《国语·晋语》。注:“无钟鼓曰侵。”"}, {"t": "觕者曰侵,精者曰伐。", "b": "《公羊传·庄公十年》"}, {"t": "苞人民、殴牛马曰侵。", "b": "《谷梁传·隐公五年》"}, {"t": "项子牛三侵鲁地。", "b": "《墨子·鲁问》"}, {"t": "韩魏相与争侵地。", "b": "《庄子·让王》"}, {"t": "侵之愈急。", "b": "宋·苏洵《权书·六国论》"}, {"t": "自海入侵。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "入侵", "t": "敌军侵入国境"}, {"w": "侵官暴国", "t": "侵犯他人职守,欺侮当今国君"}, {"w": "侵傍", "t": "侵谤。侵犯"}, {"w": "侵陵", "t": "侵犯欺凌"}, {"w": "侵克", "t": "侵占克扣"}, {"w": "侵匿", "t": "侵占吞没"}, {"w": "侵田", "t": "侵占的田地"}, {"w": "侵斥", "t": "侵占"}, {"w": "侵用", "t": "非法占用公物或他人之物"}, {"w": "侵并", "t": "侵占兼并"}, {"w": "侵耗", "t": "侵吞克扣"}, {"w": "侵匿", "t": "侵吞,侵没"}, {"w": "侵抄", "t": "侵害掠夺"}, {"w": "侵苦", "t": "侵害受苦"}, {"w": "侵冒", "t": "侵害,侵犯。"}]}, {"meaning": "侵蚀。", "cites": [{"t": "加以风雨稍侵,渐致亏坠。", "b": "李百药《北齐书》"}]}, {"meaning": "侵凌。", "cites": [{"t": "侵,凌也。", "b": "《广雅》"}, {"t": "六伐既侵。", "b": "《书·大传三》"}, {"t": "无相侵渎。", "b": "《国语·楚语下》"}, {"t": "义不侵为然诺者也。", "b": "《汉书·除馀传》"}], "words": [{"w": "侵轧", "t": "侵凌排挤,倾轧"}, {"w": "侵虐", "t": "侵凌残害"}, {"w": "侵冤", "t": "侵凌,使之受冤枉"}, {"w": "侵慢", "t": "欺凌轻慢。"}]}, {"meaning": "临近,到。", "cites": [{"t": "隔夜相期侵早发。", "b": "方千《采莲》"}], "words": [{"w": "侵晚", "t": "入夜"}, {"w": "侵明", "t": "天刚亮"}, {"w": "侵晓", "t": "拂晓"}, {"w": "侵早", "t": "凌晨。"}]}, {"meaning": "通“寝。止息。", "cites": [{"t": "下情上而道止,谓之寝。", "b": "《管子·明法》"}]}, {"meaning": "逐渐。", "cites": [{"t": "侵寻于泰山矣。", "b": "《史记·孝武纪》。晋灼曰:“遂往之意也。小颜曰:“渐染之义。”"}]}, {"meaning": "容貌丑陋。", "cites": [{"t": "蚡为人貌侵。", "b": "《汉书·田蚡传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1575wx','禹','1','yǔ','忄','9','','[{"pinyin": "yǔ", "defs": [{"meaning": "(象形。小篆字形。本义:虫名。《说文》:“虫也。”一说为龋虫) 远古夏部落领袖。姒姓,名文命,鲧之子。", "cites": [{"t": "禹、汤被之矣。(禹、汤(都)遭受过。传说夏禹曾经遭到九年水灾,商汤曾经遭到七年旱灾。被,遭受。)", "b": "汉·贾谊《论积贮疏》"}, {"t": "尧、舜、禹、汤…皆应运而生者。", "b": "《红楼梦》"}], "words": [{"w": "禹功", "t": "夏禹治水的功绩"}, {"w": "禹迹", "t": "相传夏禹治水,足迹遍于九州,后因称中国的疆域为禹迹"}, {"w": "禹启", "t": "夏禹及其子启"}, {"w": "禹鼎", "t": "大禹铸的铜鼎。象征国家的命运,代表九州,代表中国。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1576wx','侯','1','hóu hòu','亻','9','','[{"pinyin": "hóu", "defs": [{"meaning": "(象形。从人,从厂(hàn),象张布,矢在其下。甲骨文字形,象射侯张布著矢之形。本义:箭靶)。"}, {"meaning": "同本义。以兽皮或画上兽形的为之。", "cites": [{"t": "矦,春饷所射矦也。", "b": "《说文》"}, {"t": "终日射侯。", "b": "《诗·齐风·猗嗟》"}, {"t": "射有张布谓之矦。", "b": "《小尔雅·广器》"}, {"t": "方十尺曰矦,四尺曰鹄,二尺曰正,四寸曰质。", "b": ""}, {"t": "张矦。", "b": "《左传·成公二年》"}], "words": [{"w": "侯弓", "t": "古代较射时用以射侯之弓。侯,箭靶"}, {"w": "侯道", "t": "箭靶与射者间的距离。"}]}, {"meaning": "诸侯。", "cites": [{"t": "内诸侯禄也,外诸侯嗣也。", "b": "《礼记·王制》"}, {"t": "诸侯则共熊侯豹侯。", "b": "《周礼·司裘》。注:“诸侯谓三公及子弟封于畿内者。”"}], "words": [{"w": "侯氏", "t": "指诸侯个人"}, {"w": "侯王", "t": "泛指诸侯"}, {"w": "侯门", "t": "诸侯之门。"}]}, {"meaning": "古时封建制度五等爵位的第二等。", "cites": [{"t": "赵主之子孙侯者。", "b": "《战国策·赵策》"}, {"t": "王侯将相宁有种乎?", "b": "《史记·陈涉世家》"}, {"t": "未有封侯之赏。", "b": "《史记·项羽本纪》"}, {"t": "王侯以下莫不逾侈。", "b": "《后汉书·张衡传》"}], "words": [{"w": "侯王", "t": "泛指诸侯"}, {"w": "侯印", "t": "侯爵之印信"}, {"w": "侯伯", "t": "侯爵与伯爵。"}]}, {"meaning": "侯服。古代王城外围,按距离远近划分的区域之一。", "cites": [{"t": "五百里侯服。", "b": "《书·禹贡》"}], "words": [{"w": "侯甸", "t": "侯服与甸服"}, {"w": "侯卫", "t": "自侯服至卫服之地"}, {"w": "侯畿", "t": "九畿之一。王畿之外,方五百里的区域为侯畿。"}]}, {"meaning": "封侯。", "cites": [{"t": "俾侯于鲁。", "b": "《诗·鲁颂·閟宫》"}], "words": [{"w": "侯封", "t": "封侯"}, {"w": "侯者", "t": "封侯之人。"}]}, {"meaning": "美。", "cites": [{"t": "洵直且侯。", "b": "《诗·郑风·羔裘》"}], "words": [{"w": "侯鲭", "t": "精美的荤菜。"}]}]}, {"pinyin": "hòu", "defs": [{"meaning": "——“闽侯”(Mǐnhòu):中国东南部福建省的一个县,东邻福州市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1577wx','追','1','zhuī','辶','9','','[{"pinyin": "zhuī", "defs": [{"meaning": "(本义:追赶)。"}, {"meaning": "同本义(使追赶对象回来)。", "cites": [{"t": "追,逐也。", "b": "《说文》"}, {"t": "以比追胥。", "b": "《周礼·小司徒》。注:“逐寇也。”"}, {"t": "公追戎于济西。", "b": "《左传·庄公十八年》"}, {"t": "驰车充国者,追寇之马也。", "b": "《管子·七臣七主》"}, {"t": "追亡逐北。", "b": "汉·贾谊《过秦论》"}, {"t": "壶子曰:“追之!”列子追之不及。", "b": "《庄子·应帝王》"}, {"t": "公使阳处父追之。", "b": "《左传·僖公三十三年》"}, {"t": "汉主追韩信,苍生起谢安。", "b": "唐·杜甫《宴王使君宅题二首》"}, {"t": "闻追豫州。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "追操至南郡。", "b": ""}, {"t": "追购又急。", "b": "宋·文天祥《后序》"}], "words": [{"w": "穷寇勿追;穷追;猛追;追亡", "t": "追逐败亡的人。"}]}, {"meaning": "追求;追取。", "cites": [{"t": "库藏粮饷,都是民脂民膏,你只顾侵来肥己买笑追欢,败坏国家许多大事。", "b": "《水浒全传》"}], "words": [{"w": "追摄", "t": "追取"}, {"w": "追欠", "t": "追缴亏空的款子、拖欠的赋税等"}, {"w": "追欢", "t": "求欢。"}]}, {"meaning": "赶得上;比配。", "cites": [{"t": "除两税外,不许差役追拢。", "b": "《旧唐书·食货志上》"}], "words": [{"w": "追匹", "t": "比配;匹配"}, {"w": "追配", "t": "与前人相匹敌,媲美"}, {"w": "追扰", "t": "追比侵扰。"}]}, {"meaning": "追随,紧紧跟随某人。", "cites": [{"t": "追,隨也。", "b": "《方言十二》"}, {"t": "[《吕氏春秋》]其言有十二月七十有二候,逐日步气,以追寒暑之序,类其物宜而逆为之备。", "b": "唐·柳宗元《时令论》"}, {"t": "追于宇下。", "b": "《资治通鉴》"}], "words": [{"w": "追陶仿谢", "t": "追随、仿效陶渊明、谢灵运去过隐居生活。"}]}, {"meaning": "回溯;追念;召回。", "cites": [{"t": "追亨朝亨。", "b": "《周礼·司尊彝》。注:“犹追祭迁庙之主。”"}, {"t": "盖追先帝。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "深追先帝。", "b": ""}, {"t": "因作《谪九年赋》以自广,是岁腊月,诏追。", "b": "刘禹锡《问天钧赋序》"}], "words": [{"w": "追斋理七", "t": "追奠死者"}, {"w": "追摄", "t": "追念记取"}, {"w": "追叹", "t": "追溯往事而感叹"}, {"w": "追慕", "t": "追念仰慕"}, {"w": "追摧", "t": "追念悲伤"}, {"w": "追恨", "t": "追溯往事而悔恨。"}]}, {"meaning": "补救。", "cites": [{"t": "弗慎厥德,虽悔可追?", "b": "《书·五子之歌》"}, {"t": "是谓追之。", "b": "《素问·调经论》。注:“犹補也。”"}, {"t": "悟以往之不谏,知来者之可追。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "追受其牒。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "追像", "t": "补救"}, {"w": "追补", "t": "特加补救以往的不足或缺陷"}, {"w": "追救", "t": "补救"}, {"w": "追书", "t": "补记。"}]}, {"meaning": "追寻。", "cites": [{"t": "以骥之可以追利避害也。", "b": "《韩非子》"}], "words": [{"w": "追迹", "t": "追寻遗迹"}, {"w": "追掩", "t": "追踪袭击"}, {"w": "追骑", "t": "追寻侦察人、事的真象。"}]}, {"meaning": "追究。", "cites": [{"t": "苟有不晓之问,追难孔子,何伤于义?", "b": "《论衡·问孔》"}], "words": [{"w": "追比", "t": "定期追究;限期完成"}, {"w": "追劾", "t": "追究告发以前在职时所犯的罪过。"}]}, {"meaning": "送别;告别。", "cites": [{"t": "薄言追之,左右绥之。", "b": "《诗·周颂·有客》"}], "words": [{"w": "追赠", "t": "帝王在臣子死后送给他的官爵或称号"}, {"w": "追酒", "t": "饯行"}, {"w": "追饯", "t": "追送饯行。"}]}, {"meaning": "收缴。", "cites": [{"t": "拆了他的山门,毁了他的佛像,追了他的度牒,不放他回乡。", "b": "《西游记》"}]}, {"meaning": "催逼。", "cites": [{"t": "妾家非豪门,官赋日相追。", "b": "《蚕女》"}]}, {"meaning": "又如:追敛(催交租税);追征(催迫征收);追租(催交租税)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1578wx','俊','1','jùn','亻','9','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。从人,雋(jùn)声。本义:才智超群的人)。"}, {"meaning": "同本义。", "cites": [{"t": "俊,材千人也。", "b": "《说文》"}, {"t": "十人者曰豪,百人者曰杰,千人者曰俊,万人者曰英。", "b": "《春秋繁露·爵国》"}, {"t": "德万人者谓之俊。", "b": "《鹖冠子·能天》"}, {"t": "俊士。", "b": "《礼记·王制》"}, {"t": "赞杰俊。", "b": "《礼记·月令》"}], "words": [{"w": "俊选", "t": "俊士和选士"}, {"w": "俊良", "t": "贤能优良之士"}, {"w": "俊物", "t": "杰出人物"}, {"w": "俊群", "t": "才能卓越一类人。"}]}, {"meaning": "光彩。", "cites": [{"t": "那就算你在世街路上留了朋友,俊了师傅了。", "b": "《儿女英雄传》"}]}, {"meaning": "大;高尚。", "cites": [{"t": "俊乂在官。", "b": "《书·皋陶谟》"}, {"t": "克明俊德。", "b": "《书·尧典》"}, {"t": "时有俊风。", "b": "《大戴礼记·夏小正》"}, {"t": "俊鹘抟水禽。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "俊伟", "t": "伟大;高大"}, {"w": "俊德", "t": "大德"}, {"w": "俊风", "t": "大风"}, {"w": "俊马", "t": "好马,快马。"}]}, {"meaning": "漂亮,美丽。", "cites": [{"t": "状极俊健。", "b": "《聊斋志异·促织》"}], "words": [{"w": "俊刮", "t": "俊俏;漂亮"}, {"w": "俊快", "t": "俊美而流畅"}, {"w": "俊庞", "t": "容貌俊秀、漂亮"}, {"w": "俊生", "t": "俊俏,俊美。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1579wx','盾','1','dùn','目','9','','[{"pinyin": "dùn", "defs": [{"meaning": "(象形。小篆字形。上面象盾形,下面是“目”,表示以盾蔽目(身体)。本义:盾牌)。"}, {"meaning": "同本义。", "cites": [{"t": "掌五兵五盾。", "b": "《周礼·司兵》。注:“干橹之属。司戈盾、及舍设藩盾。”"}], "words": [{"w": "盾威", "t": "指军心士气"}, {"w": "盾矛", "t": "矛盾"}, {"w": "盾橹", "t": "古代防护兵器"}, {"w": "盾鼻", "t": "盾牌的把手"}, {"w": "盾墨", "t": "盾鼻上磨墨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1580wx','待','1','dài dāi','彳','9','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从彳(chì),寺声。本义:等待,等候)。"}, {"meaning": "同本义。", "cites": [{"t": "待,逗也。", "b": "《广雅》"}, {"t": "有待而行也。", "b": "《易·归妹》"}, {"t": "窃待于下风。", "b": "《庄子·渔父》"}, {"t": "多行不义,必自毙,子姑待之。", "b": "《左传·隐公元年》"}, {"t": "吾入关,秋毫不敢有所近,籍吏民,封府库,而待将军。", "b": "《史记·项羽本纪》"}, {"t": "与其坐而待之,孰若起而拯之。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "待君久不至,已去。", "b": "《世说新语·方正》"}], "words": [{"w": "待年", "t": "等待长大。指女子待嫁"}, {"w": "待贤", "t": "等候贤人"}, {"w": "待诏", "t": "等待任职的诏令"}, {"w": "待时", "t": "等待时机。"}]}, {"meaning": "以某种态度或行为加之于人或事物,对待。", "cites": [{"t": "此贤君子也,君厚待之。", "b": "《韩非子·喻老》"}, {"t": "古之君子,其责己也重以周,其待人也轻以约。", "b": "韩愈《原毁》"}, {"t": "士别三日,即更刮目相待。", "b": "《资治通鉴·汉纪》"}, {"t": "荣贼并非推心待慰帅者。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "宽待", "t": "宽大对待"}, {"w": "待见", "t": "原谅"}, {"w": "待贤", "t": "礼遇贤者。"}]}, {"meaning": "招待。", "cites": [{"t": "相公前厅待客。", "b": "元·关汉卿《谢天香》"}], "words": [{"w": " 待东", "t": "以主人身分招待"}, {"w": "待用", "t": "接待而拔用"}, {"w": "待慢", "t": "招待不周;冷淡。"}]}, {"meaning": "需要。", "cites": [{"t": "不待告。", "b": "《史记·天官书》。注:“须也。”"}], "words": [{"w": " 自不待言;待教", "t": "需要教育。"}]}, {"meaning": "将，要（古典戏曲小说和现代某些方言的用法）。", "cites": [{"t": "[金老]便待出门,店小二拦住道:“金公,那里去?”", "b": "《水浒传》"}], "words": [{"w": " 待说不说;待好", "t": "即将"}, {"w": "待善", "t": "就要;将要。"}]}, {"meaning": "防备。", "cites": [{"t": "今城郭不完,兵甲不备,不可以待不虞。", "b": "《韩非子·外储说左上》"}]}, {"meaning": "依靠。", "cites": [{"t": "主待农战而尊。", "b": "《商君书·农战》"}]}, {"meaning": "容,让。", "cites": [{"t": "两位头领到大寨食息,待贫道自去赶他。", "b": "《水浒传》"}, {"t": "这也是个彩头,待我见去。", "b": "《灰阑记》"}]}, {"meaning": "要是,如果。", "cites": [{"t": "倘或留住在家中,倒惹得孩儿们不学好了;待不收他,又撇不过柳大郎面皮。", "b": "《水浒传》"}]}]}, {"pinyin": "dāi", "defs": [{"meaning": "[口语]暂时停留，逗留，迟延"}, {"meaning": "[口语]无目的地消磨时间或在某处逗留"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1581wx','徊','1','huái','彳','9','','[{"pinyin": "huái", "defs": [{"meaning": "(形声。从彳chì,表示与行走有关)回环。", "words": [{"w": "徊集", "t": "迂回而至"}, {"w": "徊翔", "t": "盘旋飞行;迂回上下"}, {"w": "徊肠伤气", "t": "肠回转,气伤断。形容内心伤感。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1582wx','衍','1','yǎn','行','9','','[{"pinyin": "yǎn", "defs": [{"meaning": "(会意。从水,从行。本义:水流入海)。"}, {"meaning": "水循河道流汇于海。", "cites": [{"t": "衍,水朝宗于海貌也。", "b": "《说文》"}, {"t": "至今衍于四海。", "b": "《书大传》。注:“犹溢也。”"}, {"t": "水直衍。", "b": "《太玄·法》。注:“达也。”"}]}, {"meaning": "溢出,水满而出。", "cites": [{"t": "东注太湖,衍溢陂池。", "b": "司马相如《上林赋》"}, {"t": "在中也。", "b": "《易·需》。虞注:“流也。”"}], "words": [{"w": "衍溢", "t": "水满溢"}, {"w": "衍涝", "t": "谓雨水满溢。"}]}, {"meaning": "散开。", "cites": [{"t": "衍溢漂疾。", "b": "汉·枚乘《七发》"}]}, {"meaning": "分布。", "cites": [{"t": "千乘方毂,万骑骈罗,衍陈于岐、梁,东横乎大河。", "b": "《后汉书》"}]}, {"meaning": "推演;演述。", "cites": [{"t": "大衍之数五十。", "b": "《易·系辞上》"}], "words": [{"w": "衍说", "t": "讲说"}, {"w": "衍声", "t": "谓文字从声音上演变"}, {"w": "衍形", "t": "谓文字从形体上演变"}, {"w": "衍算", "t": "推算数字"}, {"w": "衍忒", "t": "推算过失。"}]}, {"meaning": "扩展,扩充。", "cites": [{"t": "丘明衍传,迁、固承流,史书始粲然大备。", "b": "章炳麟语"}], "words": [{"w": "衍文义书", "t": "借题发挥的文章"}, {"w": "衍功", "t": "谓广建功业"}, {"w": "衍食", "t": "扩大食邑。"}]}, {"meaning": "动植物孳生繁茂。", "cites": [{"t": "荐草多衍,则六畜易繁也。", "b": "《管子》"}]}, {"meaning": "(yán)绵延。", "cites": [{"t": "二曰衍祭。", "b": "《周礼·春官·大祝》。郑注:“衍,当为延。”"}, {"t": "无迁无衍,命乃长久。", "b": "《管子·白心》"}], "words": [{"w": "衍曼", "t": "绵延不绝貌"}, {"w": "衍嗣", "t": "绵延,继续"}, {"w": "衍庆", "t": "绵延吉庆。"}]}, {"meaning": "以盛、多、过多、多余为特点的。", "cites": [{"t": "国富人衍。", "b": "杜笃《论都赋》"}], "words": [{"w": "衍文", "t": "因抄刊古书而误增的字"}, {"w": "衍溢;衍辞", "t": "多余的辞藻"}, {"w": "衍句", "t": "因缮写、刻版、排牍等错误而多出的句子"}, {"w": "衍字", "t": "因缮写、刻版、排版等错误而多出的字"}, {"w": "衍误", "t": "增衍和讹误。"}]}, {"meaning": "丰富的, 种类多、数量大的。", "cites": [{"t": "仁人绌约,暴人衍矣。", "b": "《荀子》"}]}, {"meaning": "富足的。", "cites": [{"t": "修文则财衍,行武则士要。", "b": "《后汉书》"}]}, {"meaning": "多余。", "cites": [{"t": "岁衍百余万缗,淮俗若之。", "b": "宋之莹《玉壶诗话》"}]}, {"meaning": "山坡。山顶和山脚之间的部分。", "cites": [{"t": "文公梦黄蛇自天下属地,其口止于鄜衍。", "b": "《史记·封禅书》"}]}, {"meaning": "一片软湿的土地;沼泽。", "cites": [{"t": "巡陆夷之曲衍隙兮。", "b": "《楚辞"}]}, {"meaning": "低而平坦之地。", "cites": [{"t": "民之有口…犹其原湿衍活也,衣食于是乎生。", "b": "《国语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1583wx','律','1','lǜ','彳','9','','[{"pinyin": "lǜ", "defs": [{"meaning": "(形声。从彳(chì),聿(yù)声。本义:法律;法令)。"}, {"meaning": "同本义 (多指具体的规则、条文)。", "cites": [{"t": "律,均布也。", "b": "《说文》"}, {"t": "出以律。", "b": "《易师》"}, {"t": "律,法也。", "b": "《尔雅·释诂》"}, {"t": "天下既定,令萧何次律令。", "b": "《汉书·高帝纪》"}, {"t": "兵大律在谨,论敌察众,则胜负可知也。", "b": "《商君书·战法》"}, {"t": "以律非故杀。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "律则", "t": "律条"}, {"w": "律贯", "t": "法律系统"}, {"w": "律科", "t": "法令条文"}, {"w": "律度", "t": "规矩,法度"}, {"w": "律纪", "t": "纪律"}, {"w": "律贯", "t": "指法律系统"}, {"w": "律斩", "t": "依法斩决。"}]}, {"meaning": "律管,古代用来校正乐音标准的管状仪器。以管的长短来确定音阶。从低音算起,成奇数的六个管叫律,成偶数的六个管叫吕。统称十二律。", "cites": [{"t": "截竹为管谓之律。", "b": "蔡邕《月令章句》"}], "words": [{"w": "律本", "t": "指黄钟。黄钟为十二律的开始,其他各律均由此推衍而相生,所以称为律本"}, {"w": "律管", "t": "律琯。用竹管或金属管制成的定音器具。"}]}, {"meaning": "音律,乐律。古人按乐音的高低分为六律和六吕,合称十二律。", "cites": [{"t": "五声六律十二管。", "b": "《礼记·礼运》"}], "words": [{"w": "律尺", "t": "古代用以制定乐律的度尺"}, {"w": "律吕", "t": "乐律的通称"}, {"w": "律均", "t": "古乐的十二律与五韵"}, {"w": "律历", "t": "指乐律和历法。"}]}, {"meaning": "古代爵位的等第。", "cites": [{"t": "有功德于民者,加地进律。", "b": "《礼记·王制》"}]}, {"meaning": "指季节和气候。", "cites": [{"t": "大地回春律,山川扫积阴。", "b": "陆游《春望》"}]}, {"meaning": "约束。", "cites": [{"t": "五伯兼并,而以桓律人。", "b": "《韩非子·难四》"}, {"t": "抱持多反倒,威怒不可律。", "b": "李商隐《娇儿诗》"}], "words": [{"w": "律人", "t": "约束他人"}, {"w": "律身", "t": "律己。"}]}, {"meaning": "遵循。", "cites": [{"t": "劳知而不律先王。", "b": "《荀子·非十二子》"}]}, {"meaning": "击。", "cites": [{"t": "闇漠感突,上击下律。", "b": "枚乘《七发》"}]}, {"meaning": "高。", "cites": [{"t": "南山律律。", "b": "《诗·小雅·蓼莪》"}], "words": [{"w": "律律", "t": "山高峻的样子"}, {"w": "律魁", "t": "高大的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1584wx','很','1','hěn','彳','9','','[{"pinyin": "hěn", "defs": [{"meaning": "(形声。从彳(chì),艮(gèn)声。本义:违逆,不听从)。"}, {"meaning": "同本义。", "cites": [{"t": "很,不听从也。", "b": "《说文》"}, {"t": "美而很。", "b": "《左传·襄公二十六年》。服注:“戾不从教。”"}, {"t": "今王将很天而伐齐", "b": "《国语·吴语》"}], "words": [{"w": "很子", "t": "忤逆的儿子"}, {"w": "很忤;很触", "t": "违犯"}, {"w": "很人", "t": "执拗乖戾的人"}, {"w": "很很", "t": "刚愎貌"}, {"w": "很刚", "t": "暴戾"}, {"w": "很恣", "t": "乖戾恣肆"}, {"w": "很恶", "t": "暴戾凶恶"}, {"w": "很愎", "t": "犹刚愎。"}]}, {"meaning": "争斗;争讼。", "cites": [{"t": "很毋求胜,分毋求多。", "b": "《礼记·曲礼》"}]}, {"meaning": "凶恶,残忍;暴戾,乖戾。假借为“狠”。", "cites": [{"t": "大子痤美而很。", "b": "《左传·襄公二十六年》。杜预注:很,今俗作狠。心狠毒。"}, {"t": "很刚而不和,愎谏而好胜。", "b": "《韩非子·亡徵》"}, {"t": "猛如虎,很如羊,贪如狼,彊不使者,皆斩之。", "b": "《史记·项羽本纪》"}, {"t": "进退自由,傲很天常,若无君父。", "b": "《风俗通义·过誉》"}, {"t": "而顾私恩,傲很自遂。", "b": "《风俗通义·愆礼》"}], "words": [{"w": "很心", "t": "心肠残忍"}, {"w": "很毒", "t": "凶狠毒辣"}, {"w": "很刻", "t": "狠毒忌刻"}, {"w": "很戾", "t": "凶暴乖戾"}, {"w": "很鸷", "t": "凶狠阴险。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1585wx','须','1','xū','页','9','','[{"pinyin": "xū", "defs": [{"meaning": "(本字作“须”。后来写成有鬚,现在又简化为“须”。象形。从页,从彡,页(xié),头,彡(shān),表毛饰。指人面上的毛。本义:胡须)。"}, {"meaning": "同本义。", "cites": [{"t": "须,面毛也。", "b": "《说文》"}, {"t": "须,谓颐下之毛。", "b": "《礼记·礼运》引《说文》"}, {"t": "有君子白皙鬒须眉。", "b": "《左传·昭公二十六年》"}, {"t": "大夫以鱼须文竹。", "b": "《礼记·玉藻》"}, {"t": "美须髯。", "b": "《汉书·高帝纪》"}, {"t": "下担捋髭须。", "b": "《乐府诗集·木兰诗》"}, {"t": "须发尽白。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "须眉浊物", "t": "指趋炎附势,丧失气节的男人"}, {"w": "虬须", "t": "卷曲的胡子"}, {"w": "银须;黄须;长须;软须;须麋", "t": "须眉。"}]}, {"meaning": "野兽的鬚。泛指动、植物身上像须的东西。", "cites": [{"t": "敢捋虎须。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "若得其兽,则献其皮革齿须备。(备:爪)", "b": "《周礼·冥氏》"}, {"t": "撩拨虫须。", "b": "《聊斋志异·促织》"}, {"t": "张毛伸须。", "b": ""}], "words": [{"w": "鲇鱼须;触须;花须;须萼", "t": "花须和花萼"}, {"w": "须枝;须蕊", "t": "花蕊。"}]}, {"meaning": "流苏。", "cites": [{"t": "帛绳缠须。", "b": "《晋书·陆云传》"}], "words": [{"w": "须头", "t": "流苏。"}]}, {"meaning": "片刻。", "cites": [{"t": "不如须臾之所学也。", "b": "《荀子·劝学》"}], "words": [{"w": "须时", "t": "片刻。"}]}, {"meaning": "等待。", "cites": [{"t": "吴起须故人而食。", "b": "《韩非子·外储说左上》"}, {"t": "可须夜鼓声而发。", "b": "《后汉书·班超梁慬列传》"}], "words": [{"w": "须友", "t": "待友"}, {"w": "须待", "t": "期待"}, {"w": "须参", "t": "等着见皇帝"}, {"w": "须奏", "t": "等候上奏。"}]}, {"meaning": "停留。", "cites": [{"t": "昆弟五人,须于洛汭,作《五子之歌》。", "b": "《书·五子之歌序》"}], "words": [{"w": "须留", "t": "停留。"}]}, {"meaning": "需要。", "cites": [{"t": "不须复烦大将。", "b": "《汉书·冯奉世传》"}, {"t": "细雨不须归。", "b": "唐·王之涣《凉州词》"}, {"t": "何须怨杨柳。", "b": "唐·张志和《渔歌子》"}, {"t": "工又须问。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "须行即骑。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "须次", "t": "官吏依次候补官缺。同“需次”。"}]}, {"meaning": "助动词。必要,应当。", "cites": [{"t": "男大须婚,女大须嫁,古今常理。", "b": "《三国演义》"}, {"t": "白日放歌须纵酒,青春作伴好还乡。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "须取无茎叶。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "须阎君来。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "仆须急归营。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "须用", "t": "必须"}, {"w": "须至", "t": "必定。宋以后常作为公文及执照结句用语。有必须办到的意思"}, {"w": "须是", "t": "必须是,一定是"}, {"w": "须得(必得)须合(应当", "t": ""}, {"w": "须当", "t": "应当"}, {"w": "须不如", "t": "该不是。"}]}, {"meaning": "终于。", "cites": [{"t": "但愿得双亲康健,须有日,拜堂前。", "b": "《琵琶记》"}]}, {"meaning": "本是;本来。", "cites": [{"t": "他须没个亲人,料没甚大官司。", "b": "《三刻拍案惊奇》"}], "words": [{"w": "须是", "t": "本是,正是。"}]}, {"meaning": "必然。", "cites": [{"t": "杀了刘备,我女便是望门寡,明日再怎的说亲?须误了我女儿一世!", "b": "《三国演义》"}]}, {"meaning": "相当于“却”。", "cites": [{"t": "你两个好不晓事!这干系须是俺的!", "b": "《水浒传》"}]}, {"meaning": "虽然。", "cites": [{"t": "五月峨眉须近火,木皮领里只如冬。", "b": "曹松《送僧人入蜀过夏》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1586wx','叙','1','xù','又','9','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从攴(pū),余声。本义:秩序,次序)。"}, {"meaning": "同本义(强调一个挨一个的序列)。", "cites": [{"t": "敘,次弟也。", "b": "《说文》。经传亦以序为之。"}, {"t": "百揆时敘。", "b": "《虞书》"}, {"t": "行其秩敘。", "b": "《周礼·宫伯》"}, {"t": "以官府之六叙正群吏。", "b": "《周礼·天官》"}, {"t": "四时不失其叙。", "b": "《淮南子·本经训》"}], "words": [{"w": "叙齿", "t": "序齿"}, {"w": "叙齿而坐", "t": "按年齿大小的顺序入座。"}]}, {"meaning": "依次序排列。", "cites": [{"t": "惇叙九族。", "b": "《书·皋陶谟》"}, {"t": "以敘其财。", "b": "《周礼·司书》"}]}, {"meaning": "叙述,述说。", "cites": [{"t": "纪言以叙之。", "b": "《国语·晋语》"}, {"t": "自叙少小时欢乐事。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "王乃具叙宣王创业之始。", "b": "《世说新语·尤悔》"}, {"t": "畅叙幽情。", "b": "王羲之《兰亭集序》"}], "words": [{"w": "自叙;追叙;倒叙;插叙;铺叙;补叙;叙事;叙心", "t": "抒怀。"}]}, {"meaning": "谈话。", "cites": [{"t": "大家散了,王夫人姊妹不免又叙了半夜的话儿。", "b": "《红楼梦》"}], "words": [{"w": "叙意", "t": "表达心意"}, {"w": "叙觏", "t": "会面叙谈"}, {"w": "叙会", "t": "会面叙谈。"}]}, {"meaning": "记述,著述。", "cites": [{"t": "写情叙事。", "b": "《旧唐书·柳宗元传》"}, {"t": "幸君子书叙之外。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "评定等级、次第,按功提升。", "cites": [{"t": "阎王叙功,从地狱里把你提上第十七层来。", "b": "《儒林外史》"}], "words": [{"w": "叙用", "t": "分等级授官。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1587wx','剑','1','jiàn','刂','9','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从刀,佥(qiān)声。本义:古代兵器。长刃两面,中间有脊,短柄)。"}, {"meaning": "同本义。", "cites": [{"t": "劒,人所带兵也。", "b": "《说文》。注:“今之匕首。”"}, {"t": "昔葛卢之山发而出金,蚩尤受而制之为剑。", "b": "《管子》"}, {"t": "负剑辟咡诏之。", "b": "《礼记·曲礼》"}, {"t": "剑寒花不落,弓晓月逾明。", "b": "虞世南《从军行》"}], "words": [{"w": "剑锷", "t": "剑的锋刃"}, {"w": "剑首", "t": "剑环。用玉或金属制成,上面镂刻有花纹"}, {"w": "剑气", "t": "剑的光芒;比喻人的声望。"}]}, {"meaning": "以剑杀人。", "cites": [{"t": "剑斩虞常。", "b": "东汉·班固《汉书·李广苏建传》"}, {"t": "有司马叔持者,白日于都市手剑父仇。", "b": "潘岳《马穫督诔序》"}]}, {"meaning": "挟在胁下。", "cites": [{"t": "回顾乳者剑汝而立于旁。", "b": "宋·欧阳修《泷冈阡表》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1588wx','逃','1','táo','辶','9','','[{"pinyin": "táo", "defs": [{"meaning": "(形声。从辵(chuò),兆声。本义:逃走,逃跑)。"}, {"meaning": "同本义。", "cites": [{"t": "逃,亡也。", "b": "《说文》"}, {"t": "许由逃之。", "b": "《庄子·外物》"}, {"t": "恒侯体痛,使人索扁鹊,已逃秦矣。", "b": "《韩非子·喻老》"}, {"t": "处于逃。", "b": "《韩非子·内储说上》"}, {"t": "逃未及远。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "脱身以逃。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "逃闪", "t": "逃跑藏匿"}, {"w": "逃越", "t": "逃走"}, {"w": "逃生子", "t": "逃妾所生之子"}, {"w": "逃犯", "t": "逃跑的犯人"}, {"w": "逃军", "t": "军队主将抛下军队独自逃走;逃兵。"}]}, {"meaning": "逃避,回避。", "cites": [{"t": "少则能逃之。", "b": "《孙子·谋攻》"}, {"t": "今我逃楚,楚必骄,骄则可与战矣。", "b": "《左传·襄公十年》"}, {"t": "无所逃于天地间。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "逃税", "t": "逃避纳税"}, {"w": "逃会;逃债;逃学;逃刑", "t": "逃避刑责。"}]}, {"meaning": "离开。", "cites": [{"t": "罢锄用又废,恋乡不忍逃。", "b": "唐·司马札《锄草怨》"}], "words": [{"w": "逃席", "t": "宴会中途不辞而去"}, {"w": "逃徙", "t": "离乡逃奔他处居住"}, {"w": "逃酒", "t": "逃避饮酒,离席先去"}, {"w": "逃伍", "t": "充军者逃离部伍。"}]}, {"meaning": "叛,离,由于关系破裂而脱离。", "cites": [{"t": "醉中往往爱逃禅。", "b": "杜甫《饮中八仙歌》"}], "words": [{"w": "逃禅", "t": "违背佛教戒律"}, {"w": "逃墨", "t": "离弃墨子的学说。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1589wx','食','1','shí sì yì','飠','9','','[{"pinyin": "shí", "defs": [{"meaning": "(会意。从饣皂,饣声。本义:饭,饭食)。"}, {"meaning": "同本义。", "cites": [{"t": "食,饣米也。", "b": "《说文》。按,六谷之饭曰食。"}, {"t": "掌王之食饮。", "b": "《周礼·膳夫》。注:“饭也。”"}, {"t": "治其粮与其食。", "b": "《周礼·廪人》。注:“止居曰食。”"}, {"t": "共王及后之六食。", "b": "《周礼·馔人》。注:“六谷之饭。”"}, {"t": "小人有母,皆尝小人之食矣。", "b": "《左传·隐公元年》"}, {"t": "甘其食,美其服。", "b": "《老子》"}, {"t": "孟尝君使人给其食用,无使乏。", "b": "《战国策·齐策》"}, {"t": "食非多品,器皿非满案,不敢会宾友。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "食次", "t": "酒菜和点心之类;食品"}, {"w": "食店", "t": "饭店"}, {"w": "食垒", "t": "一种有几层屉的食盒"}, {"w": "食嗓", "t": "食道"}, {"w": "食忌", "t": "饮食的禁忌"}, {"w": "食官", "t": "古代掌管饮食的官"}, {"w": "食膳", "t": "膳食,肴馔"}, {"w": "食为民天", "t": "饮食是人民最重要之事。"}]}, {"meaning": "粮食。", "cites": [{"t": "籍兵乞食于西周。", "b": "《战国策·西周策》。注:“粮也。”"}, {"t": "食太阴在卯穰。", "b": "《史记·货殖列传》。索隐:“谓谷也。”"}, {"t": "食,谓农殖嘉谷,可食之物。", "b": "《汉书·食货志》"}, {"t": "卖炭得钱何所营?身上衣裳口中食。", "b": "唐·白居易《卖炭翁》"}, {"t": "百姓孰敢不箪食壶浆以迎将军者乎?", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "口中食", "t": "吃的粮食"}, {"w": "食地", "t": "可种粮食的田地。"}]}, {"meaning": "食物的通称。", "cites": [{"t": "廉者不受嗟来之食。", "b": "《乐羊子妻》"}, {"t": "野兽在深山里没有食吃。", "b": "鲁迅《祝福》"}], "words": [{"w": "猪食;鸡食;猫食", "t": ""}]}, {"meaning": "食禄,俸禄。", "cites": [{"t": "君子谋道而不谋食。", "b": "《论语·卫灵公》"}]}, {"meaning": "食墨亦简作“食”。龟卜的术语。古代龟卜兆与墨画重合叫“食墨”,为吉兆。", "cites": [{"t": "召伯相宅,卜惟洛食。", "b": "《文选·张衡·东京赋》"}]}, {"meaning": "亏损", "cites": [{"t": "易腐败而食之货勿留。", "b": "《史记》"}]}, {"meaning": "特指日蚀或月蚀。", "cites": [{"t": "彼月而食,则维其常。", "b": "《诗·小雅·十月之交》"}, {"t": "日中则昃,月盈则食。", "b": "《易·丰》"}, {"t": "三年春王二月,己巳,日有食之。", "b": "《左传·隐公三年经》"}, {"t": "是故圣王日食则修德,月食则修刑。", "b": "《管子·四时》"}]}, {"meaning": "吃。", "cites": [{"t": "食舍肉。", "b": "《左传·隐公元年》"}, {"t": "长铗归来乎,食无鱼!", "b": "《战国策·齐策四》"}, {"t": "吾恐秦人食之不得下咽也。", "b": "宋·苏洵《六国论》"}, {"t": "狗彘之畜,无失其时,七十者可以食肉矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "废寝忘食;以食食(sì)人;食母;食以草具;吞食;食犬(专供食用的狗", "t": ""}, {"w": "食酒", "t": "饮酒"}, {"w": "食茶", "t": "自己饮用的茶"}, {"w": "食息", "t": "吃饭休息,泛指休息"}, {"w": "食藿悬鹑", "t": "形容贫穷困苦"}, {"w": "食饩", "t": "即“补廪”。生员中的附生递补为廪生"}, {"w": "食獐", "t": "吃獐子"}, {"w": "食肉寝皮", "t": "食其肉而寝处其皮。形容痛恨之极。"}]}, {"meaning": "靠着吃饭;赖以为生。引申为依赖、依靠。", "cites": [{"t": "尊为公侯,食邑万户。", "b": "《汉书·张安世传》"}], "words": [{"w": "食力", "t": "依赖民众的赋税生活"}, {"w": "食采", "t": "受纳采地的租税"}, {"w": "食邑", "t": "卿大夫的封地。收封地的租税以供食用,故称“食邑”,或称“采邑”"}, {"w": "食俸", "t": "官吏每月每岁所受的薪俸。又称“食禄”"}, {"w": "食加", "t": "靠大夫的田亩增加而生活"}, {"w": "食官", "t": "靠官府发的粮食而生活"}, {"w": "食租衣税", "t": "靠收税而生活"}, {"w": "食职", "t": "靠职务所得而生活。"}]}, {"meaning": "享受;受。", "cites": [{"t": "居右,食嘉。", "b": "王充《论衡》"}], "words": [{"w": "自食其果;食征", "t": "享用税收"}, {"w": "食德", "t": "享受先人的德泽"}, {"w": "食报", "t": "受报答或受报应"}, {"w": "食俸", "t": "享受俸禄。"}]}, {"meaning": "垦耕。", "cites": [{"t": "我死则择不食之地而葬我焉。", "b": "《礼记·檀弓上》"}], "words": [{"w": "食力", "t": "依靠自己劳力而生活。"}]}, {"meaning": "背弃。", "cites": [{"t": "尔无不信,朕不食言。", "b": "《书·汤誓》"}], "words": [{"w": "食言而肥", "t": ""}]}, {"meaning": "接受,采纳。", "cites": [{"t": "贤圣不能正不食谏诤之君。", "b": "《盐铁论》"}]}, {"meaning": "祭献,享祀。", "cites": [{"t": "哭汝既不闻汝言,奠汝又不见汝食。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "食监", "t": "官名。汉置。掌管晦时祭祀。"}]}]}, {"pinyin": "sì", "defs": [{"meaning": "拿东西给人吃", "cites": [{"t": "彼留子国,将其来食。", "b": "《诗·王风·丘中有麻》。高亨云:“食通饲,给人以食物吃。”"}, {"t": "饮之食之,教之诲之。", "b": "《诗·小雅·绵蛮》"}, {"t": "左右以君贱之也,食以草具。", "b": "《战国策·齐策》"}, {"t": "吾业是有年矣,吾赖是以食吾躯。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "食监", "t": "监督做饭的官"}, {"w": "食养", "t": "供给生活用品"}, {"w": "食官", "t": "管伙食的官"}, {"w": "食士", "t": "给兵吃饭"}, {"w": "食饥息劳", "t": "使饥饿者饱肚,使劳累者得到休息。"}]}, {"meaning": "饲养 ;喂养;供养。", "cites": [{"t": "自粥于秦客,被褐食牛。", "b": "《史记·商君列传》"}, {"t": "谨食之,时而献焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "食马者不知其能千里而食也。", "b": "唐·韩愈《杂记》"}], "words": [{"w": "食马", "t": "喂马。"}]}, {"meaning": "宴请。", "cites": [{"t": "饷食宾射,共其膳羞之牛。", "b": "《周礼·地官》"}]}]}, {"pinyin": "yì", "defs": [{"meaning": "——用于人名的字。如汉代的郦食其、审食其。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1590wx','盆','1','pén','皿','9','','[{"pinyin": "pén", "defs": [{"meaning": "(形声。从皿,分声。皿,泛指盘碗一类器具。本义:盛东西或洗涤用的器皿。通常为圆形,口大底小,比盘深)。"}, {"meaning": "同本义。", "cites": [{"t": "盆,盎也。", "b": "《说文》"}, {"t": "盆实二鬴,厚半寸,脣寸。", "b": "《考工记·陶人》"}, {"t": "与其盆簝。", "b": "《周礼·牛人》。司农注:“所以盛血。”"}, {"t": "盆器倾侧。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "炭盆", "t": "烧木炭的火盆"}, {"w": "脸盆;大铜盆", "t": "一种较浅的口大底小的盛器,多为圆形"}, {"w": "盆吊", "t": "把囚犯倒吊处死的一种酷刑"}, {"w": "盆冤", "t": "覆盆之冤,喻指蒙受莫白之冤"}, {"w": "盆口精熟", "t": "精通、熟悉赌博的门道。"}]}, {"meaning": "古代量器。容量为古制十二斗八升。", "cites": [{"t": "瓜桃枣李,一本数以盆鼓。", "b": "《荀子》"}]}, {"meaning": "古炊器。", "cites": [{"t": "夫奥者,老妇之祭也。盛于盆,尊于瓶。", "b": "《礼记·食货志》"}]}, {"meaning": "把物浸在水盆里。", "cites": [{"t": "夫人缫,三盆手。", "b": "《礼记》"}]}, {"meaning": "水上涌四溢。也作“湓”。", "cites": [{"t": "青、冀之域淫雨漏河,徐、岱之滨海水盆溢。", "b": "汉·陈忠《因灾异上疏劾中侍伯荣》"}]}, {"meaning": "古代计算量盆所盛数量的单位。古制十二斗八升为一盆。", "cites": [{"t": "今是土之生五谷也,人善治之,则亩数盆,一岁而获之。", "b": "《荀子》"}]}, {"meaning": "计算一般容器盆所盛数量的单位。", "cites": [{"t": "予购三百盆。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "两盆鲜花", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1591wx','胚','1','pēi','月','9','','[{"pinyin": "pēi", "defs": [{"meaning": "(形声。《说文》作“肧”,从月(肉),不声。本义:妇女怀胎一月之称)。"}, {"meaning": "初期发育的幼孢子体,由精细胞和卵细胞结合发展而成。", "cites": [{"t": "肧,妇孕一月也。", "b": "《说文》。字亦作胚。"}, {"t": "胚胎未成。", "b": "《尔雅·释诂法》"}, {"t": "妇孕三月而肧。", "b": "《释文引淮南书文子》"}], "words": [{"w": "胚芽;胚胎;胚种", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1592wx','胧','1','lóng','月','9','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从月,龙声。朦胧:月色不明的样子。引申为“模糊不清”) 同本义。", "cites": [{"t": "灯在月胧明,觉来闻晓莺。", "b": "温庭筠《菩萨蛮》"}], "words": [{"w": "胧月", "t": "微明的月亮"}, {"w": "胧明", "t": "微明"}, {"w": "胧胧", "t": "微明的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1593wx','胆','1','dǎn','月','9','','[{"pinyin": "dǎn", "defs": [{"meaning": "(形声。从肉,詹声。本义:胆囊。动物体内消化器官之一)。"}, {"meaning": "同本义。通称胆或苦胆。", "cites": [{"t": "膽,连肝之府也。", "b": "《说文》。俗字作“胆”。"}, {"t": "胆者,中正之官,决断出焉。", "b": "《素问·灵兰秘典论》。按,形如瓶,长三寸,在肝之短叶间。华佗曰:“胆者,中清之府,号曰将军。主藏而不泻。”"}, {"t": "胆为云,肝为风,肾为雨。", "b": "《淮南子·精神》。注:“胆,金也。”"}, {"t": "剧辛乐毅感恩分,输肝剖胆效英才。", "b": "李白《行路难》"}], "words": [{"w": "胆结石", "t": "胆石症"}, {"w": "胆裂", "t": "胆为之破裂。形容恐惧之甚"}, {"w": "胆裂魂飞", "t": "恐惧惊怖到极点"}, {"w": "胆液", "t": "胆汁。"}]}, {"meaning": "胆子,胆量,勇气。", "cites": [{"t": "勇胆猛戾。", "b": "《荀子·脩身》。注:“有胆气也。”"}, {"t": "虎骑闻之应胆慑。", "b": "岑参《老马川行奉送出师西征》"}], "words": [{"w": "胆落", "t": "丧胆落魄"}, {"w": "胆大如斗", "t": "比喻人的胆量极大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1594wx','胜','1','shèng','月','9','','[{"pinyin": "shèng", "defs": [{"meaning": "(形声。从力,朕(zhèn)声。本义:胜任,禁得起)。"}, {"meaning": "同本义。", "cites": [{"t": "胜,任也。", "b": "《说文》"}, {"t": "胜,克也。", "b": "《尔雅》"}, {"t": "莫之胜说。", "b": "《易·遯》。虞注:“能也。”"}, {"t": "武王靡不胜。", "b": "《诗·商颂·烈祖》。传:“任也。”"}, {"t": "子有幼弱不胜养为累者。", "b": "《管子·入国》。注:“堪也。”"}, {"t": "白头搔更短,浑欲不胜簪。", "b": "唐·杜甫《春望》"}, {"t": "言讫,歔欷流涕,悲不自胜。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "不胜其苦", "t": "苦得受不住"}, {"w": "胜任愉快", "t": "有能力承担并能愉快地完成任务"}, {"w": "胜兵", "t": "能充当士兵参战的人。"}]}, {"meaning": "战胜,打败。", "cites": [{"t": "胜殷遏刘。", "b": "《诗·周颂·武》"}, {"t": "胜,克也。", "b": "《尔雅》"}, {"t": "其势弱于秦,而犹有可以不赂而胜之势。", "b": "宋·苏洵《六国论》"}, {"t": "以守则固,以战则胜。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "以弱胜强,以少胜多", "t": ""}]}, {"meaning": "胜过;超过。", "cites": [{"t": "日出江花胜红火,春来江水绿如蓝。", "b": "唐·白居易《忆江南》"}, {"t": "少年胜于欧洲,则国胜于欧洲。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "胜常", "t": "超过平常"}, {"w": "胜却(胜过)(略胜一筹)", "t": ""}]}, {"meaning": "一说通“称”。相当;相称。", "cites": [{"t": "为礼而不终,耻也;中不胜貌,耻也。", "b": "《国语·晋语四》"}, {"t": "调乃三体相胜。", "b": "《礼记·学记》注"}]}, {"meaning": "克制;制服。", "cites": [{"t": "凡令之行也,必待近者胜也。", "b": "《管子》"}], "words": [{"w": "胜残", "t": "遏制残暴的人。"}]}, {"meaning": "上升。", "cites": [{"t": "卿当日胜贵。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "特指名胜古迹。", "cites": [{"t": "又杂植兰桂竹木于庭,旧时栏楯亦遂增胜。", "b": "明·归有光《项脊轩志》"}, {"t": "三面临江,倒影水中,亦占一山之胜。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "胜迹", "t": ""}]}, {"meaning": "容积单位。", "cites": [{"t": "县前已窖八千斛,率以一胜完一亩。", "b": "宋·苏轼《次韵章传道喜雨》"}]}, {"meaning": "古代妇女首饰。", "cites": [{"t": "胜里金花巧耐寒。", "b": "杜甫《人日》"}], "words": [{"w": "蓬发戴胜", "t": ""}]}, {"meaning": "胜利。", "cites": [{"t": "是故百战百胜,非善之善者也。", "b": "《孙子·谋攻》"}, {"t": "故不战而强弱胜负已判矣。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "胜负兵家之常", "t": "胜利或失败是作战的人常碰到的事"}, {"w": "胜期,胜日", "t": "胜利之日。"}]}, {"meaning": "非常美好;美妙。", "cites": [{"t": "予观夫巴陵胜状,在洞庭一湖。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "四顾奇峰错列,众壑纵横,真黄山绝胜处!", "b": "明·徐宏祖《游黄山记》"}], "words": [{"w": "胜异", "t": "奇妙出众"}, {"w": "胜绝", "t": "绝妙"}, {"w": "胜妙", "t": "佳妙"}, {"w": "胜情,胜致", "t": "高雅的情趣"}, {"w": "胜否", "t": "善恶"}, {"w": "胜侣", "t": "良伴"}, {"w": "胜语", "t": "出众的言语,警句"}, {"w": "胜谈", "t": "高明的言论"}, {"w": "胜处;胜气", "t": "不平凡的气质、气度"}, {"w": "胜士", "t": "佳士,才识过人的人士"}, {"w": "胜致", "t": "优美的景致"}, {"w": "胜事", "t": "美好的事情。"}]}, {"meaning": "尽;完。", "cites": [{"t": "跨州连郡者不可胜数。", "b": "《三国志·诸葛亮传》"}, {"t": "何可胜道也哉!", "b": "宋·王安石《游褒禅山记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1595wx','胞','1','bāo','月','9','','[{"pinyin": "bāo", "defs": [{"meaning": "(形声。从肉,包声。“包”亦兼表字义。本义:胎衣)。"}, {"meaning": "同本义。", "cites": [{"t": "胞,儿生裹也。", "b": "《说文》"}, {"t": "同胞之徒。", "b": "《汉书·东方朔传》"}, {"t": "善臧我儿胞。", "b": "《汉书·外戚传》"}], "words": [{"w": "胞衣地", "t": "埋胞衣的地方"}, {"w": "胞胎", "t": "犹胞衣。常指娘胎。"}]}, {"meaning": "同胞。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1596wx','胖','1','pán pàng','月','9','','[{"pinyin": "pán", "defs": [{"meaning": "安泰舒适。", "cites": [{"t": "心广体胖。", "b": "《礼记·大学》"}]}]}, {"pinyin": "pàng", "defs": [{"meaning": "(会意兼形声。从月(肉),从半,半亦声。半,分牛。本义:古代祭祀时用的半边牲肉) 同本义。", "cites": [{"t": "胖,半体肉也。", "b": "《说文》"}, {"t": "膴胖。", "b": "《周礼·腊人》。注:“胖之言片也,析肉意也。大夫注:膴胖,皆谓夹脊肉。"}, {"t": "司马升羊右胖。", "b": "《仪礼·少牢礼》"}, {"t": "鹄鸮胖。", "b": "《礼记·内则》。注:“谓胁侧薄肉也。”"}]}, {"meaning": "肥胖。", "cites": [{"t": "心广体胖。", "b": "《礼记·大学》。注:“犹大也。”"}], "words": [{"w": "发胖", "t": "身体变胖"}, {"w": "虚胖;胖壮", "t": "肥胖壮实"}, {"w": "胖子年", "t": "方言。富裕的年节"}, {"w": "胖肆", "t": "犹放肆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1597wx','脉','1','mài mò','月','9','','[{"pinyin": "mài", "defs": [{"meaning": "(会意。合起来表示身体里的一种支脉。本义:血管)。"}, {"meaning": "同本义。", "cites": [{"t": "衺犹分也。衺行体中,谓血脉流转于体中也。”朱骏声曰:“按,字俗作脉。”", "b": ""}, {"t": "夫脉者,血之府也。", "b": "《素问·脉要精微论》"}, {"t": "骨著脉通,与体俱生。", "b": "王符《潜夫论·德化》"}], "words": [{"w": "动脉;静脉;脉脉相通", "t": "血管彼此相通。"}]}, {"meaning": "指事物如血管连贯有条理者。", "cites": [{"t": "雪缕青山脉,云生白鹤毛。", "b": "王建《隐者居》"}], "words": [{"w": "山脉;矿脉;命脉", "t": "生命和血脉。又指植物叶子、昆虫翅膀上像血管的组织。"}]}, {"meaning": "脉搏 。心脏收缩时,由于输出血液的冲击引起动脉的跳动。", "cites": [{"t": "如今看了脉息,看小弟说的是不是。", "b": "《红楼梦》"}], "words": [{"w": "脉气", "t": "脉搏所呈现的情况"}, {"w": "脉候", "t": "脉搏变化的情况。"}]}, {"meaning": "号脉,按脉诊病。", "cites": [{"t": "一时李嬷嬷来了,看了半日,问他几句话也无回答,用手向他脉门摸了摸。", "b": "《红楼梦》"}], "words": [{"w": "脉诀", "t": "论述诊脉的典籍"}, {"w": "脉学", "t": "诊脉之学"}, {"w": "脉礼", "t": "诊费的敬称"}, {"w": "脉书", "t": "记录诊脉方法的图书"}, {"w": "脉息", "t": "中医切脉以呼吸为准则。"}]}]}, {"pinyin": "mò", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1598wx','胎','1','tāi','月','9','','[{"pinyin": "tāi", "defs": [{"meaning": "(形声。从肉,台声。本义:未生的幼体,胚胎)。"}, {"meaning": "同本义。", "cites": [{"t": "胎,妇孕三月也。", "b": "《说文》"}, {"t": "胎,始也。", "b": "《尔雅》"}, {"t": "九窍者胎生。", "b": "《庄子·知北游》"}, {"t": "毋杀孩虫胎天飞鸟。", "b": "《礼记·月令》"}, {"t": "三月而胎。", "b": "《淮南子·精神》"}], "words": [{"w": "胎夭", "t": "刚出生及尚未出生的小动物"}, {"w": "胎胞", "t": "胎儿的胞衣"}, {"w": "胎动", "t": "胎儿在母体内蠕动"}, {"w": "胎卵", "t": "胎生与卵生"}, {"w": "胎形;胎位", "t": ""}]}, {"meaning": "事物的根源或初基。", "cites": [{"t": "福生有基,祸生有胎。", "b": "《汉书》"}]}, {"meaning": "植物幼芽。", "cites": [{"t": "奇花初胎。(胎,名词用如动词,开花。)", "b": "清·梁启超《饮冰室合集·文集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1599wx','勉','1','miǎn','力','9','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从力,免声。本义:力所不及而强作)。"}, {"meaning": "同本义。", "cites": [{"t": "勉,彊也。", "b": "《说文》"}, {"t": "丧事不敢不勉。", "b": "《论语·子罕》"}, {"t": "曰勉升降以上下兮。", "b": "《楚辞·离骚》"}, {"t": "勉力不时。", "b": "《荀子·天论》"}], "words": [{"w": "勉意", "t": "勉强;勉为其难。"}]}, {"meaning": "尽力,用尽所有力量。", "cites": [{"t": "尔其勉之。", "b": "《左传·昭公二十年》。注:“谓努力。”"}, {"t": "愿子勉为寡人治之。", "b": "《韩非子·外储说左下》"}, {"t": "公子勉之矣,老臣不能从。", "b": "《史记·魏公子列传》"}, {"t": "知力耕可以得谷,勉贸可以得货。", "b": "《论衡》"}], "words": [{"w": "勉勉", "t": "努力的样子"}, {"w": "勉旃", "t": "努力"}, {"w": "勉农", "t": "努力从事农务"}, {"w": "勉厉", "t": "努力。"}]}, {"meaning": "勉励,鼓励。", "cites": [{"t": "国安不殆,勉农而不偷。", "b": "《商君书·垦令》"}, {"t": "父勉其子,兄勉其弟,妇勉其夫。", "b": "《国语·越语》"}, {"t": "不加勉,而民自尽竭。", "b": "《管子》"}], "words": [{"w": "勉学;勉勖", "t": "勉励"}, {"w": "勉劳", "t": "勉励慰劳"}, {"w": "勉厉", "t": "劝勉鼓励"}, {"w": "勉慰", "t": "勉励安慰"}, {"w": "勉喻,勉谕", "t": "晓谕,劝说。"}]}, {"meaning": "除去,脱掉。", "cites": [{"t": "乃厚其外交而勉之。", "b": "《国语·晋语八》"}, {"t": "七十而无德,虽有微过,亦可以勉矣。", "b": "《大戴礼·曾子立事篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1600wx','狭','1','xiá','犭','9','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从犬,夹声。本义:窄,宽度、广度小)。"}, {"meaning": "同本义。", "cites": [{"t": "阜隘狭而幽险兮。", "b": "《楚辞·怨思》。注:“陋也。”"}, {"t": "其生民也陿阨。", "b": "《汉书·刑法志》。注:“地小也。”"}, {"t": "险道狭路,可击。", "b": "《吴子·料敌》"}, {"t": "初极狭。", "b": "晋·陶渊明《桃花源记》"}, {"t": "修狭者为之。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "狭缝;狭路相逢;狭长", "t": "窄而长"}, {"w": "狭迫", "t": "窄小局促。"}]}, {"meaning": "心胸狭窄。", "cites": [{"t": "小人狭薄,尚为激然之气,战燎于胸中。", "b": "唐·沈亚之《答冯兄书》"}, {"t": "吾直性狭中,多所不堪。", "b": "《文选·嵇康·与山巨源绝交书》。张铣注:“狭中,谓不能容人也。”"}], "words": [{"w": "狭中", "t": "心胸狭窄"}, {"w": "狭促", "t": "心胸、见识狭隘"}, {"w": "狭浅", "t": "狭薄。狭隘浅薄。"}]}, {"meaning": "急促。", "cites": [{"t": "广则容奸,狭则思欲。", "b": "《礼记·乐记》。注:“声急也。”"}]}, {"meaning": "急迫。", "cites": [{"t": "…收租税时,裁阔狭,与民相假货。", "b": "《资治通鉴》"}]}, {"meaning": "小。", "cites": [{"t": "臣见其所持者狭,而所欲者奢,故笑之。", "b": "《史记》"}], "words": [{"w": "狭巷", "t": "小巷"}, {"w": "狭径", "t": "小路"}, {"w": "狭斜子", "t": "居住陋巷无远识的人"}, {"w": "狭庐", "t": "狭小简陋的房屋。"}]}, {"meaning": "少。", "cites": [{"t": "田多可以足其人者为宽乡,少者为狭乡。狭乡授田,减宽乡之半。", "b": "《新唐书·食货志一》"}, {"t": "多虚不如少实,广种不如狭收。", "b": "《农书》"}], "words": [{"w": "狭学", "t": "浅学寡闻之人"}, {"w": "狭韵", "t": "韵书中字数少的韵部。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1601wx','狮','1','shī','犭','9','','[{"pinyin": "shī", "defs": [{"meaning": "犬生二子称“狮”。", "cites": [{"t": "狮,犬生二子。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1602wx','独','1','dú','犭','9','','[{"pinyin": "dú", "defs": [{"meaning": "(形声。从犬,蜀声。犬性好斗,多独居,故字从犬。本义:单独;单一)。"}, {"meaning": "同本义。", "cites": [{"t": "独,犬相得而斗也。羊为群,犬为独也。", "b": "《说文》。段玉裁注:“犬好斗,好斗则独而不群。”"}, {"t": "君子慎其独也。", "b": "《礼记·礼器》"}, {"t": "儒有特立而独行。", "b": "《礼记·儒行》"}, {"t": "我独南行。", "b": "《诗·邶风·击鼓》"}, {"t": "天之生是使独也。", "b": "《庄子·养生主》"}, {"t": "哀吾生之无乐兮,幽独处乎山中。", "b": "《楚辞·屈原·涉江》"}, {"t": "吾以捕蛇独存。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "君今何疾,临路独迟回。", "b": "南朝宋·鲍照《代放歌行》"}, {"t": "不见秘书心若失,百年衰病独登台。", "b": "宋·王安石《怀元度》"}], "words": [{"w": "独角兕(sì)(一种独角的犀牛", "t": ""}, {"w": "独根孤种", "t": "独生子"}, {"w": "独幅", "t": "性格孤僻,不合群"}, {"w": "独脚腿", "t": "孤立无援的人 ;独院;独家院。"}]}, {"meaning": "独特。", "cites": [{"t": "圣人所独见,众人焉知其极?", "b": "《吕氏春秋·制乐》"}], "words": [{"w": "独步", "t": "超群出众,独一无二"}, {"w": "独拔", "t": "超众,特出"}, {"w": "独绝", "t": "独一无二;无与伦比"}, {"w": "独智", "t": "过人的才能;独特的智慧"}, {"w": "独照", "t": "独特的眼光。"}]}, {"meaning": "特,特别地。", "words": [{"w": "独惨", "t": "特惨"}, {"w": "独甚", "t": "特甚。"}]}, {"meaning": "唯独,仅仅。", "cites": [{"t": "子所言者,其人与骨皆已朽矣,独其言在耳。", "b": "《史记·老子韩非列传》"}, {"t": "谢灵运为永嘉守,凡永嘉山水,游历殆遍,独不言此山。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "不独是城里姓贾的多,外省姓贾的也不少。", "b": "《红楼梦》"}, {"t": "别人来得,独你来不得。", "b": "周立波《卜春秀》"}], "words": [{"w": "独言", "t": "只说"}, {"w": "独独", "t": "唯独;独自一个"}, {"w": "独说", "t": "唯独喜欢。说,通“悦”"}, {"w": "独得", "t": "只得到"}, {"w": "独惟", "t": "唯独;只有"}, {"w": "独知", "t": "仅一人知道"}, {"w": "独树", "t": "一株树;一根木"}, {"w": "独拍", "t": "单掌拍击"}, {"w": "独见", "t": "坚持己见,固守节操。"}]}, {"meaning": "岂,难道。", "cites": [{"t": "独为匪民?", "b": "《诗·小雅·何草不黄》"}, {"t": "相如虽驽,独畏廉将军哉。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "兄不能威,独不能断“出”耶?", "b": "《聊斋志异》"}]}, {"meaning": "无子孙的老人。", "cites": [{"t": "老而无子曰独。", "b": "《孟子·梁惠王下》"}, {"t": "矜寡孤独废疾者皆有所养。", "b": "《礼记》"}, {"t": "存幼孤,矜寡独。", "b": "汉·董仲舒《春秋繁露》"}], "words": [{"w": "鳏寡孤独", "t": ""}]}, {"meaning": "无丈夫的妇女。", "cites": [{"t": "乡族贫者,死亡则为具殡葬,嫠独则助营妻娶。", "b": "《后汉书》"}]}, {"meaning": "专断;独裁。", "cites": [{"t": "回闻卫君,其年壮,其行独。", "b": "《庄子·人间世》"}], "words": [{"w": "独断", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1603wx','狰','1','zhēng','犭','9','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从犬,争声。“犬”泛指兽类。本义:传说中的奇兽)同本义。", "cites": [{"t": "[章峨之山]有兽焉,其状如赤豹,…其名曰狰。", "b": "《山海经·西山经》"}], "words": [{"w": "狰狞", "t": "形容面目凶恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1604wx','狡','1','jiǎo','犭','9','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从犬,交声。本义:小狗)。"}, {"meaning": "同本义。", "cites": [{"t": "狡,少狗也。匈奴地有狡犬,巨口而黑身。", "b": "《说文》"}, {"t": "狡狗之死也。", "b": "《淮南子·俶真》"}], "words": [{"w": "狡犬", "t": "狡狗。少壮的狗。"}]}, {"meaning": "传说中的兽名。", "cites": [{"t": "有兽焉,其状如犬而豹文,其角如牛,其名曰狡。", "b": "《山海经》"}]}, {"meaning": "狡猾;狡诈。", "cites": [{"t": "狡,狯也。", "b": "《广雅》"}, {"t": "小儿戏谓之狡狯。", "b": "《通俗文》"}, {"t": "乌鸟之狡,虽善不亲。", "b": "《管子·形势》。注:“谓猜也。”"}, {"t": "东方之钜狡也。", "b": "《吕氏春秋·尊师》。注:“猾也。”"}, {"t": "狡兔有三窟。", "b": "《战国策·齐策四》"}], "words": [{"w": "狡强", "t": "狡赖强辩"}, {"w": "狡客", "t": "狡滑的人"}, {"w": "狡竖", "t": "狡猾的人"}, {"w": "狡扇", "t": "阴谋煽动"}, {"w": "狡桀", "t": "狡猾诡诈。"}]}, {"meaning": "壮健骁勇。", "cites": [{"t": "狡,健也。", "b": "《广雅》"}], "words": [{"w": "狡悍", "t": "壮健勇武"}, {"w": "狡勇", "t": "狡诈勇悍。"}]}, {"meaning": "急促。", "cites": [{"t": "时奏狡弄。", "b": "王褒《洞箫赋》。注:“急也。”"}], "words": [{"w": "狡捷", "t": "灵活敏捷"}, {"w": "狡弄", "t": "急促雄壮的短曲。"}]}, {"meaning": "狂暴。", "cites": [{"t": "乱气狡偾。", "b": "《左传·僖公十五年》"}, {"t": "伪孽昏狡。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "狡虫", "t": "凶恶的害虫"}, {"w": "狡愤", "t": "暴躁不安"}, {"w": "狡戾", "t": "狂暴乖张"}, {"w": "狡暴", "t": "狡猾凶暴。"}]}, {"meaning": "", "cites": [{"t": "及见狡童。", "b": "《诗·山有扶苏》"}], "words": [{"w": "狡好", "t": "容貌秀丽"}, {"w": "狡童", "t": "漂亮而无实才的少年"}, {"w": "狡泽", "t": "佼美而光泽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1605wx','狱','1','yù','犭','9','','[{"pinyin": "yù", "defs": [{"meaning": "讼案。", "cites": [{"t": "夫君臣无狱。", "b": "《国语·周语》"}, {"t": "君子以明庶政,无敢折狱。", "b": "《易·贲》"}], "words": [{"w": "狱辞", "t": "决狱之词"}, {"w": "狱文", "t": "判决狱讼的文书"}, {"w": "狱主", "t": "讼案的当事人。"}]}, {"meaning": "刑狱。", "cites": [{"t": "教,政之本也;狱,政之末也。", "b": "汉·董仲舒《春秋繁露》"}], "words": [{"w": "文字狱;动辄兴狱;狱牒", "t": "刑狱的判决文书"}, {"w": "狱牍", "t": "刑狱的案卷"}, {"w": "狱事", "t": "有关刑狱之事"}, {"w": "狱法", "t": "刑狱之法。"}]}, {"meaning": "刑罚。", "cites": [{"t": "廷议大辟,上终怜其才,故缓其狱。", "b": "清·昭连《啸亭杂录》"}], "words": [{"w": "狱深", "t": "刑罚严酷"}, {"w": "狱刑", "t": "刑罚。"}]}, {"meaning": "监狱,牢房。", "cites": [{"t": "哀我填寡,宜岸宜狱。", "b": "《诗·小雅》。朱熹集传:“岸,亦狱也。《韩诗》作‘犴’。乡亭之系曰犴,朝廷曰狱。”"}], "words": [{"w": "狱家院子", "t": "狱卒"}, {"w": "狱底", "t": "古代监禁重犯的地下室"}, {"w": "狱级", "t": "狱吏"}, {"w": "狱牢", "t": "监狱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1606wx','狠','1','hěn','犭','9','','[{"pinyin": "hěn", "defs": [{"meaning": "(形声。从犬,艮(gèn)声。(wán)本义:犬争斗声。又指凶狠,残忍)。"}, {"meaning": "下定决心。", "cites": [{"t": "他爱钱如命,可是为维持事情,不得不狠了心。", "b": "老舍《骆驼祥子》"}]}, {"meaning": "吃。", "cites": [{"t": "两人登时狠了七碗。", "b": "《金瓶梅》"}]}, {"meaning": "非常。同“很”。", "cites": [{"t": "这家子远得狠哩!相去有五七千里之路。", "b": "《西游记》"}]}, {"meaning": "颇,相当。", "cites": [{"t": "起孟说过想译一篇小说,篇幅是狠短的,可是现在还未寄来。", "b": "鲁迅《书信》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1607wx','贸','1','mào','贝','9','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从贝,卯(mǎo)声。从贝,与财物有关。本义:交换财物,交易)。"}, {"meaning": "同本义。", "cites": [{"t": "贸,易财也。", "b": "《说文》"}, {"t": "贸,市也。", "b": "《尔雅》"}, {"t": "氓之蚩蚩,抱布贸丝。", "b": "《诗·卫风·氓》。传:“买也。”"}, {"t": "工商贸贩于道。", "b": "《晋书·苻坚载记》"}, {"t": "愿以潭上田贸财以缓祸。", "b": "柳宗元《永州八记》"}, {"t": "予贸得其一。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "以臣等贸马;贸籴", "t": "买进粮食"}, {"w": "贸迁", "t": "贩运买卖"}, {"w": "贸载", "t": "指贩运货物的车子"}, {"w": "贸买", "t": "购买"}, {"w": "贸售", "t": "贩卖,出售"}, {"w": "贸货", "t": "买卖货物"}, {"w": "贸贩", "t": "贩卖。"}]}, {"meaning": "改变。", "cites": [{"t": "男女贸功以长生。", "b": "《吕氏春秋·上农》。注:“易也。”"}, {"t": "古今一揆,先后不贸,焉知来者之不如今。", "b": "吴质《在元城与魏公子笺》"}, {"t": "夫事有贸迁,而言无变革。", "b": "《史通·因习》"}], "words": [{"w": "贸名", "t": "改变名称的含义"}, {"w": "贸理", "t": "事情的道理或规则有所改变"}, {"w": "贸换", "t": "交换"}, {"w": "贸位", "t": "变动位置"}, {"w": "贸功", "t": "换工。"}]}, {"meaning": "蒙昧不明。轻率,冒冒失失。", "cites": [{"t": "贸贸然来。", "b": "《礼记·檀弓下》。注:“贸贸,目不明貌。”"}], "words": [{"w": "贸贸然", "t": "冒失;轻率"}, {"w": "贸贸", "t": "形容轻率,考虑不周;眼睛看不清楚的样子"}, {"w": "贸然", "t": "轻率的样子。"}]}, {"meaning": "相等。", "cites": [{"t": "二者名贸实易,不可不察也。", "b": "《商君书·开塞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1608wx','怨','1','yuàn','心','9','','[{"pinyin": "yuàn", "defs": [{"meaning": "(形声。从心,夗(yuàn)声。本义:怨恨;仇恨)。"}, {"meaning": "同本义。", "cites": [{"t": "怨,恚也。", "b": "《说文》"}, {"t": "曰怨乎。", "b": "《论语》。皇疏:“恨也。”"}, {"t": "施行得理,谓之德。反德为怨。", "b": "《贾子道术》"}, {"t": "不怨人取之。", "b": "《淮南子·说山》"}, {"t": "天子甚怨。", "b": "《汉书·李广苏建传》"}, {"t": "人怨恶其君。", "b": "清·黄宗羲《原君》"}, {"t": "怨颇兴。", "b": "清·张廷玉《明史》"}, {"t": "怨愤所积。", "b": "孙文《序》"}], "words": [{"w": "怨怅", "t": "怨畅。怨恨"}, {"w": "怨谤", "t": "怨恨诽谤"}, {"w": "怨恶", "t": "怨恨憎恶"}, {"w": "怨艾", "t": "悔恨自己的错误"}, {"w": "怨詈", "t": "怨恨并咒骂"}, {"w": "恩怨", "t": "恩惠和仇恨"}, {"w": "宿怨", "t": "旧有的怨恨"}, {"w": "怨痛", "t": "怨恨哀痛。"}]}, {"meaning": "责怪;埋怨。", "cites": [{"t": "羌笛何须怨杨柳。", "b": "唐·王之涣《凉州词》"}, {"t": "天下怨谤。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "又。", "cites": [{"t": "胥怨者民也。", "b": ""}, {"t": "盘庚不为怨者故", "b": ""}], "words": [{"w": "抱怨", "t": "埋怨"}, {"w": "怨咎", "t": "埋怨责备"}, {"w": "怨思", "t": "抱怨迂居,怀念故土"}, {"w": "怨责", "t": "埋怨责怪。"}]}, {"meaning": "讥讽。", "cites": [{"t": "诗可以兴,可以观,可以群,可以怨。", "b": "《论语》"}], "words": [{"w": "怨刺", "t": "讽刺"}, {"w": "怨讥", "t": "讥讽。"}]}, {"meaning": "哀怨。", "cites": [{"t": "乐不乐者,其民必怨,其生必伤。", "b": "《吕氏春秋》。高诱注:“怨,悲。”"}, {"t": "痛灵根之夙陨,怨具尔之多丧。", "b": "晋·陆机《叹逝赋》"}], "words": [{"w": "怨切", "t": "悲切"}, {"w": "怨咽", "t": "哀伤呜咽"}, {"w": "怨秋", "t": "悲秋"}, {"w": "怨切", "t": "悲切"}, {"w": "怨笛", "t": "哀怨幽咽的笛声"}, {"w": "怨情", "t": "悲怨的情怀"}, {"w": "怨调", "t": "哀怨的曲调"}, {"w": "怨惜", "t": "悲怨惋惜。"}]}, {"meaning": "仇恨,怨仇。", "cites": [{"t": "此百世之怨。", "b": "《史记·平原君虞卿列传》"}, {"t": "是积怨畜祸也。", "b": "《史记·商君列书》"}, {"t": "举公义,辟私怨。", "b": "《墨子·尚贤》"}]}, {"meaning": "怨家。", "cites": [{"t": "外举不辟怨。", "b": "《礼记·儒行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1609wx','急','1','jí','心','9','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。小篆字形,从心,及声。本义:狭窄)。"}, {"meaning": "紧,紧缩。", "cites": [{"t": "遂生缚布,布曰:“缚太急,小缓之。", "b": "《三国志·吕布传》"}], "words": [{"w": "急亲戚", "t": "最接近的亲戚"}, {"w": "急持", "t": "紧紧抱持"}, {"w": "急窄", "t": "犹紧缩"}, {"w": "急装", "t": "扎缚紧凑的装束"}, {"w": "急绷绷形容把东西拉得很紧", "t": ""}]}, {"meaning": "急躁,着急。", "cites": [{"t": "曰急。", "b": "《书·洪范》。郑注:“急促自用也。”"}, {"t": "急缮其怒。", "b": "《礼记·曲礼》"}, {"t": "国无六年之蓄曰急。", "b": "《礼记·王制》"}, {"t": "西门豹之性急,故佩韦以缓己。", "b": "《韩非子·观行》"}], "words": [{"w": "急吼吼", "t": "性急慌忙的样子"}, {"w": "急撮", "t": "因受人摆弄而急躁"}, {"w": "急屎狗", "t": "性急的狗"}, {"w": "急杀人", "t": "极其着急"}, {"w": "急脚鬼", "t": "性情特别急躁的人。"}]}, {"meaning": "迫切;紧急。", "cites": [{"t": "时恐急。", "b": "《战国策·燕策》"}, {"t": "甚急。", "b": "《史记·项羽本纪》"}, {"t": "事急而不断。", "b": "《资治通鉴》"}, {"t": "江都围急。", "b": "清·全祖望《梅花岭记》"}, {"t": "事急矣。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "急口", "t": "急忙开口"}, {"w": "急脚", "t": "亦作“急脚子”、“急足。送紧急文书的仆役"}, {"w": "急递铺", "t": "元代在军事紧急时,设置急递铺作传递文书的驿站,每天最快要跑四百里"}, {"w": "急且", "t": "急切,仓猝"}, {"w": "急处从宽", "t": "在紧急情况下并不紧张。"}]}, {"meaning": "疾速;快捷;匆忙。", "cites": [{"t": "秦急攻之。", "b": "《战国策·赵策》"}, {"t": "急应河阳役。", "b": "唐·杜甫《石壕吏》"}, {"t": "急挥帜。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "急逐弗失。", "b": ""}], "words": [{"w": "急离披", "t": "急急忙忙落荒而逃"}, {"w": "急玲", "t": "机灵"}, {"w": "急率", "t": "匆忙之间"}, {"w": "急簌簌", "t": "亦作“急飕飕”。急速的"}, {"w": "急手", "t": "急速;快手,动作敏捷。"}]}, {"meaning": "指声音急促。", "cites": [{"t": "大弦嘈嘈如急雨。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "促弦弦转急。", "b": ""}, {"t": "东南风急。", "b": "《资治通鉴》"}], "words": [{"w": "急三台", "t": "唐时一种节拍急促的曲调名"}, {"w": "急拍繁弦", "t": "急管繁弦。形容节拍急促,演奏热闹的乐奏"}, {"w": "急杵", "t": "急促的捣衣声。"}]}, {"meaning": "着急;使焦虑。", "cites": [{"t": "林教头是个性急的人。", "b": "《水许传》"}], "words": [{"w": "真把人急死了;干急;心急;发急", "t": ""}]}, {"meaning": "以…为急,关切;赶快帮助。", "cites": [{"t": "急人之困。", "b": "《史记·魏公子列传》"}, {"t": "而能急之。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "急人之难;急病让夷", "t": "将困难留给自己,将方便让给别人。"}]}, {"meaning": "重视。", "cites": [{"t": "进修是急。", "b": "清·刘开《问说》"}], "words": [{"w": "急公", "t": "热心公益"}, {"w": "急农", "t": "重视农业"}, {"w": "急义", "t": "重义气"}, {"w": "急贤", "t": "重贤;急于求贤。"}]}, {"meaning": "急难,危急的事。", "cites": [{"t": "先国家之急。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "今事有急。", "b": "《史记·项羽本纪》"}, {"t": "公子有急。", "b": "《史记·魏公子列传》"}, {"t": "边境有急。", "b": "汉·贾谊《论积贮疏》"}]}, {"meaning": "假期;休假。", "cites": [{"t": "又不请急。", "b": "沈约《宋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1610wx','饵','1','ěr','饣','9','','[{"pinyin": "ěr", "defs": [{"meaning": "(形声。从食,耳声。本义:糕饼)。"}, {"meaning": "同本义。", "cites": [{"t": "饵,粉饼也。", "b": "《说文》"}, {"t": "鱼胶饵。", "b": "《考工记·弓人》"}], "words": [{"w": "果饵", "t": "果饼。"}]}, {"meaning": "钓鱼用的鱼食。", "cites": [{"t": "临川靡芳饵。", "b": "《文选·傅长虞诗》"}], "words": [{"w": "鱼饵;钓饵", "t": ""}]}, {"meaning": "药饵。", "cites": [{"t": "得而猎之以为饵,可以已大风、挛踠、瘘、疠。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "饵治", "t": "以药饵治病。"}]}, {"meaning": "食物的总称 。"}, {"meaning": "筋腱。", "cites": [{"t": "捶反铡之,去其饵。", "b": "《礼记·内则》"}]}, {"meaning": "吞食。", "cites": [{"t": "适足以饵大国耳。", "b": "《汉书·贾谊传》。注:“谓为其所吞食。”"}], "words": [{"w": "饵名钓禄", "t": "以不正当的手段取得名誉和地位。"}]}, {"meaning": "引诱。", "cites": [{"t": "此所以饵敌,如何去之!", "b": "《三国志》"}], "words": [{"w": "饵诱", "t": "利诱"}, {"w": "饵兵", "t": "诱敌深入的小部队。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1611wx','饶','1','ráo','饣','9','','[{"pinyin": "ráo", "defs": [{"meaning": "(形声。从食,尧声。本义:饱)。"}, {"meaning": "同本义。", "cites": [{"t": "饶,饱也。", "b": "《说文》。 ?"}]}, {"meaning": "富裕,丰足。", "cites": [{"t": "饶,多也。", "b": "《小尔雅》"}, {"t": "饶,益也。汉时谣曰:“今年尚可后年饶。今苏俗买物请益谓之讨饶头。", "b": "《广雅》"}, {"t": "原大则饶,原小则鲜。", "b": "《史记·货殖列传序》"}, {"t": "七十子之徒,赐(子贡)最为饶益", "b": "《史记·货殖列传》"}], "words": [{"w": "饶裕", "t": "富足;富裕"}, {"w": "饶益", "t": "富裕"}, {"w": "饶美", "t": "丰美"}, {"w": "饶富", "t": "富饶,丰足"}, {"w": "饶益", "t": "富裕,使人受益"}, {"w": "饶余", "t": "富足有余"}, {"w": "饶足", "t": "生活富裕"}, {"w": "饶野", "t": "富饶的田野。"}]}, {"meaning": "余;剩。", "cites": [{"t": "饶,余也。", "b": "《玉篇》"}, {"t": "子弟衣食自有余饶。", "b": "诸葛亮《自表后主》"}], "words": [{"w": "饶道", "t": "啰嗦,爱说多余的话"}, {"w": "饶奢", "t": "过分长大"}, {"w": "饶言", "t": "饶舌。"}]}, {"meaning": "安逸。", "cites": [{"t": "沃地之民多不才者,饶也。", "b": "《淮南子》"}]}, {"meaning": "肥沃。", "cites": [{"t": "不爱珍器重宝肥饶之地。", "b": "汉·贾谊《过秦论上》"}, {"t": "掠于饶野,三军足食。", "b": "《孙子》"}], "words": [{"w": "饶沃;饶广", "t": "肥沃广阔。"}]}, {"meaning": "乱。", "cites": [{"t": "疏远微贱者无所告诉,则下饶。", "b": "《管子·版法解》"}]}, {"meaning": "宽恕;宽容。", "cites": [{"t": "日月不相饶,节序昨夜隔。", "b": "唐·杜甫《立秋后题》"}], "words": [{"w": "饶了他吧;饶让 ", "t": "宽恕;让"}, {"w": "饶闲", "t": "放松;使空闲"}, {"w": "饶赦", "t": "饶恕赦免"}, {"w": "饶情", "t": "留情面"}, {"w": "饶假", "t": "宽恕;宽容"}, {"w": "饶借", "t": "容让"}, {"w": "饶免", "t": "宽免。"}]}, {"meaning": "额外增添。", "cites": [{"t": "五贯便依你五贯,只饶我们一瓢吃。", "b": "《水浒传》"}, {"t": "然大王能饶人以爵邑,士之顽钝嗜利无耻者,亦多归汉。", "b": "《史记》"}, {"t": "我唱的是《三国志》,先饶十大曲。", "b": "石君宝《紫云庭》"}], "words": [{"w": "饶受", "t": "自赚;白拿"}, {"w": "饶利", "t": "赚钱"}, {"w": "饶培", "t": "滋益培养"}, {"w": "饶头", "t": "额外增添之物。"}]}, {"meaning": "厚赐;多给。", "cites": [{"t": "又况委法受赂,侵牟百姓者,往往而是也。此所谓不能饶之以财也。", "b": "宋·王安石《上皇帝万言书》"}]}, {"meaning": "古地名。"}, {"meaning": "在今河北省饶阳县东。"}, {"meaning": "当在今山东省东部昌乐县、潍县一带地方。"}, {"meaning": "当在今山西省西南部临汾市一带。"}, {"meaning": "任凭;尽管。", "cites": [{"t": "饶这么严,他们还偷空儿闹个乱子来。", "b": "《红楼梦》"}], "words": [{"w": "这孩子,饶怎么说他就是不听", "t": ""}]}, {"meaning": "不仅。", "cites": [{"t": "他饶骂了人,还说是故典。", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1612wx','蚀','1','shí','虫','9','','[{"pinyin": "shí", "defs": [{"meaning": "(会意。从虫,从食,从人,食亦声。本义:虫等蛀伤物)。"}, {"meaning": "同本义。", "cites": [{"t": "蝕,败创也。", "b": "《说文》。字亦作蚀。"}, {"t": "精铜不蠹蚀。", "b": "梅尧臣《刘原甫古钱劝酒》"}, {"t": "凡物侵蠹皆曰蚀。", "b": "《古今韵会举要》"}]}, {"meaning": "日月食。", "cites": [{"t": "日月薄蚀。", "b": "《史记·天官书》"}, {"t": "其月有薄蚀。", "b": "《吕氏春秋·明理》"}], "words": [{"w": "蚀既", "t": "日月蚀尽。也称“全蚀”"}, {"w": "蚀亏", "t": "犹亏蚀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1613wx','饺','1','jiǎo','饣','9','','[{"pinyin": "jiǎo", "defs": [{"meaning": "包成半圆形的有馅的面食", "words": [{"w": "饺子", "t": "以面粉为皮,内中包馅,略呈三角形的食品"}, {"w": "饺饵", "t": "粉角,即饺子"}, {"w": "蒸饺", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1614wx','饼','1','bǐng','饣','9','','[{"pinyin": "bǐng", "defs": [{"meaning": "(形声。从食,并声。本义:古代面食的通称。后指扁圆形的面制食品)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1615wx','峦','1','luán','山','9','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从山,羉(luán)声。本义:小而尖的山)。"}, {"meaning": "同本义。", "cites": [{"t": "峦,山小而锐者。", "b": "《说文》"}, {"t": "登峦而远望兮。", "b": "《楚辞·自悲》。注:“小山也。”"}, {"t": "陟玉峦兮逍遥。", "b": "《楚辞·守志》。注:“山脊曰峦。玉峦,昆仑山也。”"}, {"t": "丘峦崩摧。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "山峦", "t": "连绵的山"}, {"w": "峦壑", "t": "峰峦和山谷"}, {"w": "峦峤", "t": "峭拔的山峰。"}]}, {"meaning": "泛指山。", "cites": [{"t": "谕以封峦。", "b": "《史记·司马相如传》。集解:“山也。”"}, {"t": "簸丘跳峦。", "b": "《汉书·扬雄传》"}, {"t": "陵峦超壑。", "b": "张衡《西京赋》"}, {"t": "桂殿兰宫,列冈峦之体势。", "b": "王勃《滕王阁序》"}], "words": [{"w": "峦丘", "t": "山丘"}, {"w": "峦穴", "t": "山穴"}, {"w": "峦谷", "t": "山谷。"}]}, {"meaning": "山脉,相连的群山。", "cites": [{"t": "云中乱拍禄山舞,风过重峦下笑声。", "b": "唐·杜牧《过华清宫绝句三首》之三"}]}, {"meaning": "山脊、山梁。", "cites": [{"t": "城堡冈峦。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "山峦为晴雪所说。", "b": "明·袁宏道《满井游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1616wx','弯','1','wān','弓','9','','[{"pinyin": "wān", "defs": [{"meaning": "(形声。本义:拉弓)。"}, {"meaning": "同本义。", "cites": [{"t": "弯,持弓关矢也。", "b": "《说文》"}, {"t": "弯,引也。", "b": "《广雅·释诂一》"}, {"t": "弯綦卫之箭。", "b": "《淮南子·原道》"}, {"t": "弯威弧之拔刺兮。", "b": "《文选·张衡·思玄赋》"}], "words": [{"w": "弯弹", "t": "拉弓射弹"}, {"w": "弯弓", "t": "弯弧。拉弓"}, {"w": "弯卒", "t": "弓兵"}, {"w": "弯弓饮羽", "t": "形容勇猛善战。"}]}, {"meaning": "折,使弯曲。", "cites": [{"t": "定睛再看时,却是史大汉弯跧蹲在东司边。", "b": "明·冯梦龙《喻世明言》"}], "words": [{"w": "弯跧", "t": "身体蜷缩"}, {"w": "弯转", "t": "展转搞到"}, {"w": "弯踦", "t": "弯曲的河岸"}, {"w": "弯躬", "t": "弯下身子"}, {"w": "弯弯扭扭", "t": "弯曲;扭动"}, {"w": "弯身拾禾;越过岩石海岸线向西弯去", "t": ""}]}, {"meaning": "停船靠岸,停泊。", "cites": [{"t": "大爷吩咐急急收了口子,弯了船。", "b": "《儒林外史》"}]}, {"meaning": "水流弯曲之处。", "cites": [{"t": "望别非新馆,开舟即旧弯。", "b": "北周·庾信《应令》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1617wx','将','1','jiāng jiàng qiāng','寸','9','','[{"pinyin": "jiāng", "defs": [{"meaning": "(形声。从寸,酱省声。从“寸”,表示与手有关。(jiàng)本义:将领,带兵的人)。"}, {"meaning": "扶持,扶助。", "cites": [{"t": "将,扶也。", "b": "《广雅》"}, {"t": "无将大车。", "b": "《诗·小雅·无将大车》"}, {"t": "天不我将。", "b": "《诗·大雅·桑柔》"}, {"t": "爷娘闻女来,出郭相扶将。", "b": "《乐府诗集·木兰诗》"}, {"t": "为人将车。", "b": "《史记·田叔传》。索隐:“犹御车也。”"}, {"t": "吏谨将之。", "b": "《荀子·成相》。注:“持也。”"}], "words": [{"w": "将美", "t": "助成好事"}, {"w": "将引", "t": "扶助收纳"}, {"w": "将扶", "t": "扶持;搀扶"}, {"w": "将助", "t": "扶助;支持。"}]}, {"meaning": "奉行,秉承。", "cites": [{"t": "使臣将王命,岂不如贼焉?", "b": "元结《贼退示官吏》"}], "words": [{"w": "将明", "t": "大臣的辅佐赞助。将:奉行;明:辨明"}, {"w": "将命", "t": "奉命。"}]}, {"meaning": "送行。", "cites": [{"t": "耒者弗迎,去者弗将。", "b": "《淮南子·诠言》"}], "words": [{"w": "将意", "t": "致意"}, {"w": "将迎", "t": "送往迎来"}, {"w": "将送", "t": "送行;遣送。"}]}, {"meaning": "携带。", "cites": [{"t": "将家就鱼麦,归老江湖边。", "b": "元结《贼退示官吏》"}], "words": [{"w": "将雏", "t": "携带幼禽"}, {"w": "将带", "t": "携带"}, {"w": "将领", "t": "携带。"}]}, {"meaning": "带领。", "cites": [{"t": "将胡骏马而旧。", "b": "《淮南子·人间训》"}], "words": [{"w": "将领", "t": "带着;率领"}, {"w": "将御", "t": "统帅领导"}, {"w": "将家", "t": "带领家人"}, {"w": "将引", "t": "引导,带领。"}]}, {"meaning": "顺从;随从。", "cites": [{"t": "备物以将形。", "b": "《庄子·庚桑楚》"}, {"t": "将自何所至。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "将顺", "t": "顺着趋势推动以加速其成功。"}]}, {"meaning": "供养;奉养。", "cites": [{"t": "不遑将父。", "b": "《诗·小雅·四牡》"}, {"t": "不遑将母。", "b": ""}], "words": [{"w": "将父", "t": "奉养父亲"}, {"w": "将帮", "t": "奉养。"}]}, {"meaning": "行,进。", "cites": [{"t": "日就月将。", "b": "《诗·敬之》"}]}, {"meaning": "使用。", "cites": [{"t": "菩萨将甚兵器?", "b": "《西游记》"}]}, {"meaning": "就要;将要。", "cites": [{"t": "君将若之何?", "b": "《左传·隐公六年》"}, {"t": "天将降大任。", "b": "《孟子·告子下》"}, {"t": "将以实笾豆。", "b": "明·刘基《卖柑者言》"}, {"t": "将衒外。", "b": ""}, {"t": "将恐深。", "b": "《韩非子·喻老》"}, {"t": "将益深。", "b": ""}, {"t": "将以有为也。(这是唐朝名将南霁云的话,见于韩愈《张中丞传后序》。文天祥引用此语,说明自己想忍辱留生,以图大举。)", "b": "宋·文天祥《后序》"}, {"t": "柳条将舒。", "b": "明·袁宏道《满井游记》"}, {"t": "将自此始。", "b": ""}], "words": [{"w": "将引", "t": "将要;即将;带领"}, {"w": "将然", "t": "指将要发生的事"}, {"w": "将欲", "t": "将要;打算。"}]}, {"meaning": "必,必定。", "cites": [{"t": "将拜君赐。", "b": "《左传·僖公三十三年》"}, {"t": "将有所不可。", "b": "宋·苏轼《教战守》"}, {"t": "民将不安。", "b": ""}], "words": [{"w": "把一切朋友都得罪了,其结果将使我们自陷于孤立", "t": ""}]}, {"meaning": "将近。", "cites": [{"t": "将五十里也。", "b": "《孟子·滕文公》"}]}, {"meaning": "岂;难道。", "cites": [{"t": "若无然,民将能登天乎?", "b": "《国语·楚语》"}]}, {"meaning": "相当于“拿”、“取”。", "cites": [{"t": "将雌剑往。", "b": "晋·干宝《搜神记》"}, {"t": "将子头来。", "b": ""}], "words": [{"w": "将着", "t": "拿着;带着"}, {"w": "将天就地", "t": "谓以高就低"}, {"w": "将本求利", "t": "用本钱谋求利润"}, {"w": "将李代桃", "t": "喻代人受罪或彼此顶替。"}]}, {"meaning": "相当于“把”、“用”。", "cites": [{"t": "将身后托汝。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "将革命进行到底", "t": ""}]}, {"meaning": "连接意思平等的词或词组,表示并列关系,相当于“又”,“且” 。例如:将信将疑。"}, {"meaning": "如果;假若。", "cites": [{"t": "吾将再病。", "b": "清·袁枚《祭妹文》"}, {"t": "将听吾计,用之必胜,留之;将不听吾计,用之必败,去之。", "b": "《孙子》"}]}, {"meaning": "或;抑。", "cites": [{"t": "将有人主张之乎?将无人主张之乎?", "b": "孟郊《上常州卢使君书》"}]}, {"meaning": "用在动词后面,表示动作、行为的趋向或进行。在现代汉语里见于方言。", "cites": [{"t": "宫使驱将惜不得。", "b": "唐·白居易《卖炭翁》"}, {"t": "大虫去了一盏茶时,方才扒将起来。", "b": "《水浒传》"}], "words": [{"w": "走将出来;叫将起来;赶将上去", "t": ""}]}]}, {"pinyin": "jiàng", "defs": [{"meaning": "(形声。从寸,酱省声。本义:将领,带兵的人)。"}, {"meaning": "同本义。", "cites": [{"t": "将,帅也。", "b": "《说文》"}, {"t": "将止不面夷。", "b": "《国语·晋语》。注:“帅也。”"}, {"t": "是将率之事也。", "b": "《荀子·富国》。注:“犹主领也。”"}, {"t": "军必有将。", "b": "《吕氏春秋·执一》。注:“主也。”"}, {"t": "军将皆命卿。", "b": "《周礼·大司马》"}, {"t": "鲁欲使慎子为将军。", "b": "《孟子》"}, {"t": "将谓五官,左右虎贲、羽林、中郎将也。", "b": "《后汉书·桓帝纪》注"}, {"t": "人臣无将。", "b": "《汉书·叔孙通传》"}, {"t": "代廉颇为将。", "b": "汉·刘向《列女传》"}, {"t": "赵将马服君。", "b": ""}, {"t": "诸将请所之。", "b": "《资治通鉴·唐纪》"}, {"t": "诸将皆失色。", "b": ""}, {"t": "将吏敢复有言迎操者。", "b": "《资治通鉴》"}], "words": [{"w": "将器", "t": "将帅之才"}, {"w": "将弁", "t": "将官,武官"}, {"w": "将仕", "t": "将士。对有一定家产而无官位的人的称呼,源于最低一级官阶名称“将仕郎”"}, {"w": "将在外,君命有所不受", "t": "将领在外面打仗,皇帝的命令有的可以不接受。"}]}, {"meaning": "中国象棋中的一子,即“帅”。"}, {"meaning": "统率;率领。", "cites": [{"t": "葛婴将兵。", "b": "《史记·陈涉世家》"}, {"t": "将荆州之军。", "b": "《三国志·诸葛亮传》"}, {"t": "自将三千人。", "b": "《资治通鉴·唐纪》"}, {"t": "李进诚将三千。", "b": ""}, {"t": "将数百之众。(将,带领。)", "b": "汉·贾谊《过秦论》"}, {"t": "括不可使将。", "b": "汉·刘向《列女传》"}, {"t": "其马将胡骏马而归。", "b": "《淮南子·人间训》"}], "words": [{"w": "将将", "t": "驾驭将帅"}, {"w": "将御", "t": "统率"}, {"w": "将率", "t": "率领"}, {"w": "将略", "t": "用兵的谋略。"}]}]}, {"pinyin": "qiāng", "defs": [{"meaning": "愿;请求。用来表示礼貌上的尊敬。", "cites": [{"t": "将子无怒,秋以为期。", "b": "《诗·卫风》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1618wx','奖','1','jiǎng','大','9','','[{"pinyin": "jiǎng", "defs": [{"meaning": "(形声。字本作“奨”,从犬,将省声。本义:驱使狗猛进)。"}, {"meaning": "同本义。", "cites": [{"t": "奖,嗾犬厉之也。", "b": "《说文》。段玉裁注:“《口部》:‘嗾,使犬声也。’厉之,犹勉之也。”"}]}, {"meaning": "劝勉;鼓励。", "cites": [{"t": "奖,劝也。", "b": "《小尔雅》"}, {"t": "以奖善人。", "b": "《左传·昭公二十二年》。疏:“劝也。”"}, {"t": "奖厉太子。", "b": "《汉书·哀帝纪》。注:“劝使也。”"}, {"t": "奖率三军。", "b": "诸葛亮《出师表》"}], "words": [{"w": "奖导", "t": "劝勉诱导"}, {"w": "奖激", "t": "劝勉激励"}, {"w": "奖慰", "t": "劝勉安慰"}, {"w": "奖鉴", "t": "勉励劝戒"}, {"w": "奖蹙威柄", "t": "勉励促成其成为权威者"}, {"w": "奖拔", "t": "勉励提拔。"}]}, {"meaning": "辅助。", "cites": [{"t": "皆奖王室。", "b": "《左传·僖公二十八年》。注:“助也。”"}], "words": [{"w": "奖成", "t": "助成"}, {"w": "奖顺", "t": "顺势助成"}, {"w": "奖就", "t": "助成。"}]}, {"meaning": "奖励。", "cites": [{"t": "优诏奖瑞。", "b": "《明史》"}], "words": [{"w": "奖赉", "t": "奖励"}, {"w": "奖札", "t": "嘉奖证书;奖状"}, {"w": "奖叙", "t": "嘉奖任用;评进爵位"}, {"w": "奖饰", "t": "嘉奖赞美"}, {"w": "奖进", "t": "奖励引进。"}]}, {"meaning": "为了鼓励或表扬而给予的荣誉或财物等 。如:得奖;发奖;大奖;一等奖。亦指可以靠运气(如在抽奖中)得到的某物。如:奖券;中奖。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1619wx','哀','1','āi','口','9','','[{"pinyin": "āi", "defs": [{"meaning": "(形声。从口,衣声。本义:悲痛;悲伤)。"}, {"meaning": "同本义。", "cites": [{"t": "哀,闵也。", "b": "《说文》"}, {"t": "哀,痛也。", "b": "《广雅》"}, {"t": "以凶礼哀邦国之忧。", "b": "《周礼·大宗伯》。注:“救患分灾。”"}, {"t": "舍正路而不由哀哉。", "b": "《孟子》。注:“伤也。”"}, {"t": "呜呼哀哉。", "b": "《柳敏碑》"}, {"t": "有妇人哭于墓间而哀。", "b": "《礼记·檀弓》"}, {"t": "僵卧孤村不自哀。", "b": "宋·陆游《十一月四日风雨大作》"}, {"t": "子言未发而哀乐具乎其前(悲哀、欢乐的神情都先流露了出来)。", "b": "清·黄宗羲《柳敬亭传》。"}], "words": [{"w": "哀咜", "t": "悲哀叹息"}, {"w": "哀诏", "t": "皇上驾崩后,新君通告全国的文书"}, {"w": "哀哉", "t": "表示悲伤或痛惜的感叹词"}, {"w": "哀毁骨立", "t": "形容对父母的故去非常悲哀,以致瘦得皮包骨了。"}]}, {"meaning": "形容声音凄清尖锐。", "cites": [{"t": "杜鹃啼血猿哀鸣。", "b": "唐·白居易《琵琶行(并序)》。"}], "words": [{"w": "哀弦", "t": "悲凉的弦乐声"}, {"w": "哀笳", "t": "悲凉的胡笳声"}, {"w": "哀鸿", "t": "哀鸣的大雁。比喻流离失所的灾民。"}]}, {"meaning": "同情,怜悯。", "cites": [{"t": "君将哀而生之乎。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "天子作诗三章以哀民。", "b": "《穆天子传》 。"}], "words": [{"w": "哀恕", "t": "同情宽恕。"}]}, {"meaning": "慰问;哀悼。", "cites": [{"t": "秦不哀吾之丧而伐吾同姓。", "b": "《左传·僖公三十三年》。"}], "words": [{"w": "哀文", "t": "哀辞。"}]}, {"meaning": "哀求。", "cites": [{"t": "爱公者皆为公惧,劝罄橐以哀之。", "b": "《聊斋志异·妖术》。"}], "words": [{"w": "哀请", "t": "哀告,哀求;苦苦请求"}, {"w": "哀祈", "t": "哀求。"}]}, {"meaning": "爱护。", "cites": [{"t": "国虽弱,令必敬以哀。", "b": "《管子·侈靡》"}, {"t": "各哀其所生。", "b": "《淮南子·说山》"}, {"t": "见与之友,几于不亲;见哀之交,几于不结。", "b": "《管子·形势》"}, {"t": "人主胡可以不务哀。", "b": "《吕氏春秋·报更》"}]}, {"meaning": "哀叹。", "cites": [{"t": "秦人不暇自哀,而后人哀之;后人哀之而不鉴之,亦使后人复哀后人也。", "b": "杜牧《阿房宫赋》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1620wx','亭','1','tíng','亠','9','','[{"pinyin": "tíng", "defs": [{"meaning": "(象形。战国文字字形,其中“T”象矗立的亭柱。小篆以为从高省,丁声。本义:古代设在路旁的公房,供旅客停宿)。"}, {"meaning": "同本义。后指驿亭。", "cites": [{"t": "亭,人所安定也。亭有楼。", "b": "《说文》"}, {"t": "汉家因秦十里一亭。亭,留也。", "b": "《一切经音义经》"}, {"t": "亭,停也,亦人所停集也。", "b": "《释名·释宫释》"}, {"t": "为泗上亭长。", "b": "《汉书·高祖纪》"}, {"t": "安阳城南有一亭,夜不可宿,宿辄杀人。", "b": "晋·干宝《搜神记》"}, {"t": "何处是归程?长亭更短亭。", "b": "李白《菩萨蛮》"}], "words": [{"w": "亭邮", "t": "驿站"}, {"w": "亭民", "t": "驿亭附近的居民"}, {"w": "亭寺", "t": "驿亭。寺,办公的官署"}, {"w": "亭舍", "t": "驿亭的客舍"}, {"w": "亭传", "t": "客栈"}, {"w": "亭置", "t": "邮亭驿站"}, {"w": "亭驿", "t": ""}]}, {"meaning": "亭子。有顶无墙,供休息用的建筑物,多建筑在路旁或花园里。", "cites": [{"t": "西蜀子云亭。", "b": "《三国志·诸葛亮传》"}, {"t": "常记溪亭日暮。", "b": "宋·李清照《如梦令》"}, {"t": "亭东自足下皆云漫。", "b": "清·姚鼐《登泰山记》"}, {"t": "亭西有岱祠。", "b": ""}], "words": [{"w": "亭榭", "t": "亭阁台榭"}, {"w": "亭馆", "t": "供人游憩歇宿的亭台馆舍"}, {"w": "亭槛", "t": "亭子的栏杆;亭子"}, {"w": "亭院", "t": "造有凉亭、楼阁等建筑物的庭园或花园"}, {"w": "亭景", "t": "亭影"}, {"w": "亭落", "t": "亭院;村落"}, {"w": "亭彩", "t": "旧时办喜事扎的亭楼、铭旌。"}]}, {"meaning": "古代设在边塞观察敌情的岗亭。", "cites": [{"t": "百步一亭,高垣丈四尺,厚四尺,为闺门两扇。", "b": "《墨子》"}, {"t": "亭卒上楼扫除,见死妇,大惊,走白亭长。", "b": "汉·应劭《风俗通》"}], "words": [{"w": "亭戍", "t": "古代边境上的岗亭和营垒"}, {"w": "亭吏", "t": "亭长"}, {"w": "亭佐", "t": "亭长的副手"}, {"w": "门亭", "t": "设于城门处的亭"}, {"w": "亭卒", "t": "秦汉亭中的差役。"}]}, {"meaning": "像亭子的小房子 。", "words": [{"w": "书亭;邮亭;亭场", "t": "卖盐的地方"}, {"w": "亭子间", "t": ""}]}, {"meaning": "山梨。", "cites": [{"t": "枇杷橪柿,亭柰厚朴。", "b": "《文选·司马相如·上林赋》"}]}, {"meaning": "秦汉时的基层行政单位。", "cites": [{"t": "大率十里一亭,亭有长。十亭一乡。", "b": "《汉书·百官公卿表上》"}]}, {"meaning": "养育 。", "words": [{"w": "亭育", "t": "养育,培育"}, {"w": "亭毒", "t": "养育;化育。"}]}, {"meaning": "停止。同“停”。", "cites": [{"t": "其水亭居,冬夏不增减,皆以为潜行地下。", "b": "《汉书·西域传上》"}], "words": [{"w": "亭当", "t": "完毕,妥当"}, {"w": "亭居", "t": "水静止的样子。"}]}, {"meaning": "适中,均衡 。", "words": [{"w": "亭匀", "t": "均匀,妥贴。"}]}, {"meaning": "直。姿势挺立的或笔直 。", "words": [{"w": "亭立", "t": "直立;耸立"}, {"w": "亭亭秀秀", "t": "身材修长,容貌、体态俊美"}, {"w": "亭亭款款", "t": "身材修长、缓步走动的样子"}, {"w": "亭亭植立", "t": "花木主干挺拔的"}, {"w": "亭亭当当", "t": "妥当;合宜"}, {"w": "亭亭袅袅", "t": "形容女子身材修长和体态轻盈。"}]}, {"meaning": "正。", "cites": [{"t": "鹤迹秋偏静,松阴午欲亭。", "b": "《和史宫赞》"}], "words": [{"w": "亭决", "t": "公平的判断。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1621wx','亮','1','liàng','亠','9','','[{"pinyin": "liàng", "defs": [{"meaning": "(《说文》一说本作“倞”,后移“人”于“京”下,又变作“儿”,并省去“京”中一竖。本义:明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "亮,明也。", "b": "《说文》。段注:“古人名亮者字明。”"}]}, {"meaning": "诚信;忠诚。", "cites": [{"t": "孟子曰:君子不亮,恶乎执?", "b": "《孟子》"}], "words": [{"w": "亮直", "t": "诚实正直;诚实正直的人"}, {"w": "亮节", "t": "清高的节操"}, {"w": "亮怀", "t": "忠直、坦荡的胸怀。"}]}, {"meaning": "响亮。", "cites": [{"t": "其鸣高亮。", "b": "《诗·小雅·鹤鸣》"}], "words": [{"w": "亮溜", "t": "指声音嘹亮溜圆"}, {"w": "亮彻", "t": "指声音响亮清脆"}, {"w": "亮节", "t": "高亢之声。"}]}, {"meaning": "明白,清楚。", "cites": [{"t": "即蒙亮许,当赐矜擢。", "b": "《宋书·王僧达传》"}], "words": [{"w": "亮拔", "t": "明达章理、才能出众"}, {"w": "亮许", "t": "明察允许"}, {"w": "亮察", "t": "明鉴"}, {"w": "亮照", "t": "亮察。"}]}, {"meaning": "辅佐。", "cites": [{"t": "亮,佐也。", "b": "《小尔雅》"}, {"t": "惟时亮天工。", "b": "《虞书》"}, {"t": "亮彼武王。", "b": "《韩诗·大明》。按,如影之附形,合而相助也。"}], "words": [{"w": "亮工", "t": "辅佐天子以立天下之功"}, {"w": "亮采", "t": "辅佐政事"}, {"w": "亮弼", "t": "辅佐。"}]}, {"meaning": "相信;信任。", "cites": [{"t": "亮,信也。", "b": "《尔雅》"}, {"t": "亮采惠畴。", "b": "《虞书》"}, {"t": "亮采有邦。", "b": "《书·皋谟》"}], "words": [{"w": "亮贤", "t": "相信贤才"}, {"w": "亮天地", "t": "敬信天地。"}]}, {"meaning": "显示;显露。", "cites": [{"t": "乃或亮闇。", "b": "《书·无逸》。按,恶室也。"}], "words": [{"w": "亮台", "t": "旧称戏班组成后的首次演出"}, {"w": "亮盒子摇", "t": "犹“打开天窗说亮话”。盒子,指赌博时押宝的宝盒。"}]}, {"meaning": "谅解;原谅。", "cites": [{"t": "母也天只,不亮人只。", "b": "《诗·鄘风·柏舟》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1622wx','度','1','dù duó','广','9','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从又,庶省声。“又”即手,古代多用手、臂等来测量长度。本义:计量长短的标准,尺码)。"}, {"meaning": "同本义。", "cites": [{"t": "度,法制也。", "b": "《说文》。按,五度,分寸尺丈引也。度起于人手取法,故从又。"}, {"t": "同律度量衡。", "b": "《虞书》"}, {"t": "度然后知长短。", "b": "《孟子》"}, {"t": "执鞭度守门。", "b": "《周礼·司市》"}, {"t": "吾忘持度。", "b": "《韩非子》"}], "words": [{"w": "尺度", "t": ""}]}, {"meaning": "法制;法度。", "cites": [{"t": "公室无度。", "b": "《左传·昭公三年》"}, {"t": "度不可改。", "b": "《左传·昭公四年》"}, {"t": "九曰以度教节。", "b": "《周礼·大司徒》。注:“谓宫室车服之制。”"}, {"t": "度作刑以诘四方。", "b": "《书·吕刑》。马注:“法度也。”"}], "words": [{"w": "度轨", "t": "法度轨范"}, {"w": "度矩", "t": "法度;法则。"}]}, {"meaning": "限度,限额。", "cites": [{"t": "生之有时而用之亡度,则物力必屈。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "每月扣5元,扣满150元为度", "t": ""}]}, {"meaning": "胸襟;器度。", "cites": [{"t": "群臣惊愕,卒起不意,尽失其度。", "b": "《战国策·燕策》"}], "words": [{"w": "气度", "t": ""}]}, {"meaning": "心意,考虑。", "cites": [{"t": "以小舟涉鲸波,出无可奈何,而死固付之度外矣!", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "置之度外", "t": "不介意"}, {"w": "度内", "t": "计虑之内;意料之中。"}]}, {"meaning": "计划。", "cites": [{"t": "盘庚不为怨者故改其度。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "度过,越过。", "cites": [{"t": "年忽忽而日度。", "b": "《楚辞·刘向·九叹·惜贤》"}, {"t": "度百里之限。", "b": "《汉书·王莽传》。师古曰:“度,亦逾越也。”"}, {"t": "将欲度唐虞之隆。", "b": "《汉书·匡衡传》"}, {"t": "则必度越诸子矣。", "b": "《汉书·扬雄传赞》"}, {"t": "黄鹤之飞尚不得过,猿猱欲度愁攀援。", "b": "李白《蜀道难》"}, {"t": "秋月春风等闲度。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "春风不度玉门关。", "b": "唐·王之涣《凉州词》"}, {"t": "度险,下至山坳,暝色已合。", "b": "明·徐宏祖《游黄山记》"}], "words": [{"w": "度岁", "t": "过年"}, {"w": "度与", "t": "递给;交给"}, {"w": "度嘴", "t": "糊口;维持生计"}, {"w": "苦度年关;虚度年华", "t": ""}]}, {"meaning": "僧尼道士劝人离俗出家。", "cites": [{"t": "有一个道士三言两语把人度了去。", "b": "《红楼梦》"}]}, {"meaning": "超度;宗教说法,使死者灵魂得以脱离地狱诸苦难。", "cites": [{"t": "据说虬早已被吕洞宾度上天了。", "b": "《雨中登泰山》"}], "words": [{"w": "度说", "t": "道教佛教语。超度解脱人世的生死苦难,到达仙佛境界"}, {"w": "度脱", "t": "使人脱离人世苦难,到达仙、佛境界"}, {"w": "度数", "t": "星相家迷信说法,以七曜与二十八宿度数相配,推测人事的吉凶。"}]}, {"meaning": "谱写。", "cites": [{"t": "予怀怆然,感慨今昔,因自度此曲。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "度词", "t": "依词谱曲"}, {"w": "度声", "t": "按曲谱唱歌。"}]}, {"meaning": "次。", "cites": [{"t": "一年一度", "b": ""}, {"t": "岐王宅里寻常见,崔九堂前几度闻。", "b": "唐·杜甫《江南逢李龟年》"}]}, {"meaning": "姓。"}]}, {"pinyin": "duó", "defs": [{"meaning": "估计,推测。", "cites": [{"t": "度我至军中,公乃入。", "b": "《史记·项羽本纪》"}, {"t": "他人有心,予忖度之。", "b": "《诗·小雅·巧言》"}], "words": [{"w": "忖度", "t": "猜测,揣度"}, {"w": "测度;度空儿", "t": "趁空儿,瞅空儿。"}]}, {"meaning": "衡量。", "cites": [{"t": "度地居民。", "b": "《礼记·王制》。释文:“量也。”"}]}, {"meaning": "量;计算。", "cites": [{"t": "不度民械。", "b": "《礼记·少仪》。释文:“计也。”"}, {"t": "郑人有欲买履者,先自度其足而置之其坐。", "b": "《韩非子·外储说左上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1623wx','迹','1','jì','辶','9','','[{"pinyin": "jì", "defs": [{"meaning": "同本义。", "cites": [{"t": "赵主父令工施钩梯而缘播吾(山名),刻疏人迹其上。", "b": "《韩非子·外储说左上》"}], "words": [{"w": "浪迹天涯;人迹", "t": "人的足迹"}, {"w": "人迹罕至;迹蹈", "t": "重复走过的路"}, {"w": "迹状", "t": "行迹"}, {"w": "迹响", "t": "踪迹和声响。"}]}, {"meaning": "留下的印子。", "cites": [{"t": "蟆入草间,蹑迹披求。", "b": "《聊斋志异·促织》"}], "words": [{"w": "痕迹;血迹;笔迹;墨迹", "t": ""}]}, {"meaning": "前人留下的事物(主要指建筑或器物)。", "cites": [{"t": "故平公之迹不可明也。", "b": "《韩非子·难一》"}], "words": [{"w": "古迹;胜迹;古城墙的遗迹;史迹;迹相", "t": "表露出来的不很显著的情况,可借以推断过去或将来。"}]}, {"meaning": "功劳。", "cites": [{"t": "如是则其迹长矣。", "b": "《荀子·正名》"}]}, {"meaning": "追踪;追寻。", "cites": [{"t": "逻者见之,知非其国人也,迹其所憩执之。", "b": "岳珂《桯史》"}], "words": [{"w": "迹察", "t": "寻迹察访"}, {"w": "迹盗", "t": "跟踪查捕盗贼"}, {"w": "迹访", "t": "寻访。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1624wx','庭','1','tíng','广','9','','[{"pinyin": "tíng", "defs": [{"meaning": "(形声。从广,廷声。广（yǎn）,就山岩架成的屋。本义:厅堂)。"}, {"meaning": "同本义。", "cites": [{"t": "庭,宫中也。", "b": "《说文》"}, {"t": "是君子之所以骋志意于坛宇宫庭也。", "b": "《荀子·儒效》"}, {"t": "藜棘树于中庭。", "b": "《楚辞·刘向·九叹·思古》。注:“堂下谓之庭。”"}], "words": [{"w": "庭落", "t": "厅堂"}, {"w": "庭庑", "t": "堂下四周的廊屋"}, {"w": "庭炬", "t": "古代庭中照明的火炬"}, {"w": "庭阶", "t": "厅砌。堂前的台阶。"}]}, {"meaning": "堂阶前的地坪。", "cites": [{"t": "胡瞻尔庭有县貆兮。", "b": "《诗·魏风·伐檀》"}, {"t": "徘徊庭树下。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "眄庭柯以怡颜。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "缢于庭树。", "b": ""}, {"t": "严霜结庭兰。", "b": ""}], "words": [{"w": "庭闱", "t": "原指父母居住的地方。借指庭院或家庭"}, {"w": "庭帏", "t": "庭闱"}, {"w": "庭燎", "t": "举行大典礼时设在庭院中照明的火炬"}, {"w": "庭轩", "t": "庭院中的小室"}, {"w": "庭芜", "t": "庭园中丛生的草"}, {"w": "庭阈", "t": "泛指庭院。"}]}, {"meaning": "朝廷,君主受朝问政的地方。", "cites": [{"t": "扬于王庭,柔乘五刚也。", "b": "《易·夬》"}, {"t": "龙辂充庭。", "b": "《文选·张衡·东京赋》。注:“庭,朝廷。”"}, {"t": "拜送书于庭。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "使有禄于国,立义于庭。", "b": "《说苑·立节》"}, {"t": "乞以臣此章与三公九卿贤士大夫议之于庭。", "b": "陈子昂《谏政理书》"}, {"t": "奏事入朝,思睹阙庭,将陈所见。", "b": "唐·魏征《十渐不克终疏》"}], "words": [{"w": "庭争", "t": "在朝廷上据理诤谏"}, {"w": "庭论", "t": "在朝廷中当众评议"}, {"w": "庭庙", "t": "朝廷"}, {"w": "庭议", "t": "议事于朝廷"}, {"w": "庭辩", "t": "在朝廷上辩论"}, {"w": "庭问", "t": "上朝问国事"}, {"w": "庭会", "t": "朝见天子。"}]}, {"meaning": "法庭,司法机关审理案件的处所 。", "words": [{"w": "庭决", "t": "公堂判决"}, {"w": "民庭;刑庭", "t": ""}]}, {"meaning": "官署,政府办公的地方 。", "words": [{"w": "庭参", "t": "庭谒。封建时代,下级官员趋步至官厅,按礼谒见长官。文职北面跪拜,长官立受。武职北面跪叩,自宣衔名,长官坐受"}, {"w": "庭阁", "t": "府署"}, {"w": "庭皋", "t": "府暑。"}]}, {"meaning": "朝觐,到圣地去进香。", "cites": [{"t": "安南负固为逆久不来庭,无所逃于天讨。", "b": "归有光《书安南事》"}]}, {"meaning": "古代指少数民族所辖区域或所都之处。也泛指边疆地方。", "cites": [{"t": "边庭流血如海水,武皇开边意未已。", "b": "杜甫《兵车行》"}]}, {"meaning": "中医学名词。指额部中央 。望诊时常作为诊察头、面部疾病的部位,又叫“天庭”。", "words": [{"w": "庭角", "t": "珠庭日角。谓人的天庭圆满。旧时认为是大贵之相。"}]}, {"meaning": "房屋 。", "words": [{"w": "庭宇", "t": "房舍"}, {"w": "庭户", "t": "门户;门庭"}, {"w": "庭帏", "t": "妇女居住的内室;父母居住处"}, {"w": "庭闱", "t": "内舍。多指父母居住处。"}]}, {"meaning": "唐代州名 。故治在今新疆乌鲁木齐市。"}, {"meaning": "父亲、母亲的或与父或与母有关的 。", "words": [{"w": "庭诰", "t": "古代指家训文字"}, {"w": "庭趋", "t": "承受父教。"}]}, {"meaning": "直的,笔直的。", "cites": [{"t": "播厥百谷,既庭且硕。", "b": "《诗·小雅·大田》"}], "words": [{"w": "庭右", "t": "旧时书信中对人的敬称。谓不敢直指其人,故呼其左右的侍从而禀告之。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1625wx','疮','1','chuāng','疒','9','','[{"pinyin": "chuāng", "defs": [{"meaning": "(形声。从疒(chuáng),仓声。本义:皮肤上肿烂溃疡的病)。"}, {"meaning": "痈、瘫、疽、疖等的总称。", "cites": [{"t": "疮,疮痍也。", "b": "《玉篇》"}, {"t": "所恶成疮痏。", "b": "张衡《西京赋》。薛注:“疮痏,谓瘢痕也。”"}, {"t": "医得眼前疮,剜却心头肉。", "b": "聂夷中《咏田家》"}], "words": [{"w": "疮毒", "t": "诸疮毒肿"}, {"w": "疮疹", "t": "指疹子"}, {"w": "疮疾", "t": "泛指疥癣痈疽等皮肤及外科疾患。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1626wx','疯','1','fēng','疒','9','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。 从疒 (chuáng), 表示与疾病有关。风声。 本义:头风病)。"}, {"meaning": "同本义。", "cites": [{"t": "疯, 头病。", "b": " 《集韵》"}]}, {"meaning": "瘫痪。", "cites": [{"t": "他那半肢疯,半个身子简直不能动。 ", "b": "茅盾《子夜》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1627wx','疫','1','yì','疒','9','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从疒(chuáng),役省声。本义:瘟役)。"}, {"meaning": "同本义。急性传染病流行的通称。", "cites": [{"t": "疫,民皆疾也。", "b": "《说文》"}, {"t": "疫,病流行也。", "b": "《字林》"}, {"t": "氐为天根生疫。", "b": "《史记·天官书》"}, {"t": "鬻棺者欲岁之疫。", "b": "《汉书·刑法志》"}, {"t": "果实早成,民殃于疫。", "b": "《礼记·月令》"}], "words": [{"w": "时疫;疫死", "t": "因染患流行的传染病而死"}, {"w": "疫旱", "t": "传染病与旱灾"}, {"w": "疫症", "t": "疫病"}, {"w": "疫疠", "t": "瘟疫"}, {"w": "疫疾", "t": "疫病;疫病流行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1628wx','疤','1','bā','疒','9','','[{"pinyin": "bā", "defs": [{"meaning": "(形声。从疒(chuáng),巴声。从“疒”表示与疾病有关。本义:疮疤)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1629wx','咨','1','zī','口','9','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从口,次声。本义:商议;征询)。"}, {"meaning": "同本义。", "cites": [{"t": "咨,谋事曰咨。", "b": "《说文》。字亦作谘。"}, {"t": "咨,谋也。", "b": "《尔雅》"}, {"t": "周爰咨诹。", "b": "《诗·皇皇者华》"}, {"t": "咨于故实。", "b": "《国语·周语》"}, {"t": "访问于善为咨。", "b": "《左传·襄公四年》"}, {"t": "咨亲为询。", "b": "《国语·鲁语下》"}, {"t": "悉以咨之。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "咨臣以当世之事。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "以咨诹善道。", "b": ""}, {"t": "遂随使者倒军,署司空户曹掾,引见咨议。", "b": "《三国志·魏志》"}], "words": [{"w": "咨叩", "t": "咨询求教"}, {"w": "咨考", "t": "询问查考"}, {"w": "咨度", "t": "咨询;商酌"}, {"w": "咨问", "t": "咨询;请教"}, {"w": "咨禀", "t": "请教;禀告。"}]}, {"meaning": "叹息;赞叹。", "cites": [{"t": "文王流涕而咨之。", "b": "《吕氏春秋》"}, {"t": "微微老夫,咨既迁绝。", "b": "《汉书·韦贤传》"}, {"t": "对曰:“巢、许狷介之士,不足多慕。”王大咨嗟。", "b": "《世说新语·言语》"}], "words": [{"w": "咨叹", "t": "叹息"}, {"w": "咨闵", "t": "叹息怜恤"}, {"w": "咨惋", "t": "叹惜"}, {"w": "咨咨", "t": "叹息;叹息声。"}]}, {"meaning": "用同“龇”。露出。", "cites": [{"t": "大圣喝了一口,即咨牙咧嘴道:“不好吃!不好吃!”", "b": "《西游记》"}]}, {"meaning": "表示赞赏,相当于“啧”。", "cites": [{"t": "帝曰:“咨!四岳!朕在位七十载,汝能庸命,巽朕位。", "b": "《书·尧典》"}, {"t": "尧曰:“咨!尔舜!天之历数在尔躬,允执其中”。", "b": "《论语·尧曰》"}], "words": [{"w": "咨嗟", "t": "赞叹之声"}, {"w": "咨玩", "t": "赞叹玩赏。"}]}, {"meaning": "旧时公文的一种。咨文的简称 。用于同级机关。", "cites": [{"t": "少保据着萧云仙的详文,咨明兵部。", "b": "《儒林外史》"}], "words": [{"w": "咨称", "t": "公文上说"}, {"w": "咨呈", "t": "具文呈报"}, {"w": "咨注", "t": "载入官牒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1630wx','姿','1','zī','女','9','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从女,次声。本义:姿态)。"}, {"meaning": "同本义(“姿”侧重于呈现的姿势、风度)。", "cites": [{"t": "姿,态也。", "b": "《说文》。按,态者,材艺巧善也。即才能、贤能本字。"}, {"t": "嵇康身长七尺八寸,风姿特秀。", "b": "《世说新语·容止》"}, {"t": "雄姿英发。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}, {"t": "姿态万变。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "无风亦呈袅娜之姿。", "b": "明·李渔《闲情偶寄·种植部》"}]}, {"meaning": "又。", "cites": [{"t": "娇姿欲滴。", "b": ""}, {"t": "直则无姿。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "容貌。", "cites": [{"t": "王汝南少无婚,自求郝普女。…既婚,果有今姿淑德。", "b": "《世说新语·贤缓》"}], "words": [{"w": "姿年", "t": "容貌年龄"}, {"w": "姿形", "t": "容貌体态"}, {"w": "姿神", "t": "容貌,神态"}, {"w": "姿致", "t": "容貌举止"}, {"w": "姿仪", "t": "容貌,仪表。"}]}, {"meaning": "资质(天资,禀赋)。", "cites": [{"t": "姿,材也。", "b": "《汉书·谷永传》注"}, {"t": "资,资也,资取也。", "b": "《释名》"}, {"t": "唯笛因其天姿。", "b": "马融《长笛赋》。注:“天然之姿也。”"}, {"t": "上主之姿也。", "b": "《汉书·谷永传》"}], "words": [{"w": "姿才", "t": "资质,禀赋"}, {"w": "姿禀", "t": "资质,禀赋"}, {"w": "姿质", "t": "资质。"}]}, {"meaning": "气质。", "cites": [{"t": "蒲柳之姿,望秋先零。", "b": "《儒林外史》"}], "words": [{"w": "姿性", "t": "品行;性格。"}]}, {"meaning": "美好;妩媚。", "cites": [{"t": "简选其有姿首者内之掖库。", "b": "《资治通鉴·魏纪》"}], "words": [{"w": "姿调", "t": "美好的风度"}, {"w": "姿望", "t": "优美的丰度"}, {"w": "姿慧", "t": "美貌才智。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1631wx','亲','1','qīn qìng','亠','9','','[{"pinyin": "qīn", "defs": [{"meaning": "(形声。从见,亲(shēn)声。“见”与“至”义相通。本义:亲爱)。"}, {"meaning": "同本义。", "cites": [{"t": "亲,至也。从見,亲声,字亦作儭。", "b": "《说文》"}, {"t": "亲,近也。", "b": "《广雅》"}, {"t": "同人亲也。", "b": "《易·杂卦》"}, {"t": "亲者属也。", "b": "《礼记·大传》"}, {"t": "人之亲其兄之子。", "b": "《孟子》。注:“爱也。”"}, {"t": "爱臣太亲,必危其身。", "b": "《韩非子·爱臣》"}, {"t": "我有亲父兄。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "我有亲父母。", "b": ""}], "words": [{"w": "亲父", "t": "生父"}, {"w": "亲爹", "t": "亲父"}, {"w": "姑表亲;亲如一家;亲心", "t": "亲爱之心;父母爱护子女之心"}, {"w": "亲厚", "t": "亲爱并加以厚待。"}]}, {"meaning": "亲密。与“疏”相对。", "cites": [{"t": "王无亲臣矣。", "b": "《孟子·梁惠王下》"}], "words": [{"w": "亲臣", "t": "亲近可信的臣下"}, {"w": "亲懿", "t": "亲密的朋友。同亲友"}, {"w": "亲比", "t": "亲近依靠"}, {"w": "亲附", "t": "亲近附从"}, {"w": "亲幸", "t": "皇帝或国君对臣子的宠爱。"}]}, {"meaning": "准,准确。", "cites": [{"t": "搭上弓弦,觑的杨志较亲,望后心再射一箭。", "b": "《水浒全传》"}], "words": [{"w": "亲切", "t": "准确;真切。"}]}, {"meaning": "更新。", "cites": [{"t": "亲臣进而故人退。", "b": "《韩非子·亡徵》"}]}, {"meaning": "艰苦。", "cites": [{"t": "体五道之亲苦。", "b": "《王妙晖等造像记》"}]}, {"meaning": "父母。也单指父亲或母亲。", "cites": [{"t": "亲,父母也。", "b": "《礼记·奔丧》注"}, {"t": "冯公子有亲乎?", "b": "《战国策·齐策四》"}, {"t": "归见其亲。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "双亲;亲心", "t": "父母亲爱护子女之心;子女思念双亲之心"}, {"w": "亲丧", "t": "父母之丧。"}]}, {"meaning": "泛指有血统或婚姻关系的人。", "cites": [{"t": "亲,九族。", "b": "《左传·昭公十四年》注"}, {"t": "禄勋,合亲,任良。", "b": "《左传·昭公十四年》"}, {"t": "畔主背亲。", "b": "《汉书·李广苏建传》"}, {"t": "洛阳亲友如相问。", "b": "唐·王昌龄《芙蓉楼送辛渐》诗"}, {"t": "亲朋无一字,老病有孤舟。", "b": "杜甫《登岳阳楼》诗"}], "words": [{"w": "亲难转债", "t": "亲人之间难于借债。比喻愈是亲人愈难求得帮助"}, {"w": "亲党", "t": "亲属"}, {"w": "亲契", "t": "亲朋"}, {"w": "亲识", "t": "亲朋等熟识者。"}]}, {"meaning": "亲密的、可靠的人。", "cites": [{"t": "轻则失亲。", "b": "《左传·僖公五年》。注:“党援也。”"}], "words": [{"w": "亲兵;亲失", "t": "失其所应当亲近的人"}, {"w": "亲委", "t": "宠信"}, {"w": "亲习", "t": "亲近熟悉的人"}, {"w": "亲渥", "t": "情分深厚的人。"}]}, {"meaning": "亲自,亲身。", "cites": [{"t": "亲枉车骑。", "b": "《史记·魏公子列传》"}, {"t": "亲引问委曲。《资治通鉴·唐纪》", "b": ""}, {"t": "亲见忠烈。", "b": "清·全祖望《梅花岭记》"}, {"t": "亲往颐和园。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "亲秉旄钺", "t": "亲自统率军队"}, {"w": "亲炙", "t": "亲见"}, {"w": "亲迎", "t": "古代婚姻六礼之最后一礼。新郎亲自去女家迎娶新娘"}, {"w": "亲任", "t": "亲自担任。"}]}, {"meaning": "亲近;接近。", "cites": [{"t": "无亲陈王者。", "b": "《史记·陈涉世家》"}, {"t": "无使土亲肤。", "b": "《孟子·公孙丑下》"}, {"t": "诸侯亲之。", "b": "《国语·晋语》"}, {"t": "亲贤臣,远小人,此先汉所以兴隆也。", "b": "诸葛亮《出师表》"}, {"t": "不能离死命而去亲他主。", "b": "《韩非子·用人》"}], "words": [{"w": "亲傍", "t": "亲近;套近乎"}, {"w": "亲香", "t": "亲炙。亲热。"}]}]}, {"pinyin": "qìng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1632wx','音','1','yīn','音','9','','[{"pinyin": "yīn", "defs": [{"meaning": "(指事。从言含一。甲骨文“言、音”互用,金文、小篆在“言中加一横,表示所发之音。本义:声音)。"}, {"meaning": "同本义。", "cites": [{"t": "音,声也。生于心,有节于外。谓之音。", "b": "《说文》"}, {"t": "八音。一说笙、祝、鼓、箫、琴、埙、钟、磬也。", "b": "《白虎通·礼乐》"}, {"t": "凡音之起,由人心生也。声成文,谓之音。", "b": "《礼记·乐记》"}, {"t": "夫音,乐之舆也。", "b": "《左传·昭公二十一年》"}, {"t": "鸡狗之音相闻。", "b": "《庄子》"}, {"t": "北音清越。", "b": "宋·苏轼《石钟山记》"}, {"t": "鸟兽音迹。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "音颡", "t": "喉咙"}, {"w": "音强", "t": "指声音的强弱。也叫响度或音势。音的强弱,因发音体振动时之振幅大小而异,振幅大者则音强,振幅小者则音弱"}, {"w": "音制", "t": "音调高下疾徐的节奏"}, {"w": "音频", "t": "人类耳朵能产生反应的声音频率范围。"}]}, {"meaning": "音乐。", "cites": [{"t": "莫不中音。", "b": "《庄子·养生主》"}, {"t": "赵王好音。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "音律;音调", "t": ""}]}, {"meaning": "字的音读。", "cites": [{"t": "乡音无改。", "b": "唐·贺知章《回乡偶书》"}, {"t": "盖音谬也。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "音韵", "t": "指“汉”字字音中的声、韵、调。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1633wx','帝','1','dì','巾','9','','[{"pinyin": "dì", "defs": [{"meaning": "(象形。甲骨文字形,象花蒂的全形。上面象花的子房,中间象花萼(花瓣外面的绿片)。下面下垂的象雌雄花蕊。本义:花蒂)。"}, {"meaning": "天帝,上帝。宗教或神话中称主宰万物的神。最高的天神。古人想像中宇宙万物的主宰。", "cites": [{"t": "帝,上帝,天之神也。", "b": "《字汇》"}, {"t": "帝命不时。", "b": "《诗·大雅·文王》"}]}, {"meaning": "又。", "cites": [{"t": "在帝左右。", "b": ""}, {"t": "兆五帝于四郊。", "b": "《周礼·大宗伯》"}, {"t": "操蛇之神闻之,惧其不已也,告之于帝。", "b": "《列子·汤问》"}], "words": [{"w": "帝乡", "t": "传说中天帝居住的仙乡"}, {"w": "帝君", "t": "古人对神的尊称"}, {"w": "帝江", "t": "传说中的神名。居于“天山”。"}]}, {"meaning": "君主,皇帝。", "cites": [{"t": "帝,王天下之号也。", "b": "《说文》"}, {"t": "帝,君也。", "b": "《尔雅》"}, {"t": "帝乙归妹。", "b": "《易·泰》"}, {"t": "安帝雅闻衡善求学。", "b": "《后汉书·张衡传》"}, {"t": "争强为帝。", "b": "《战国策·赵策》"}, {"t": "揣帝无杀瑞意。", "b": "《明史·海瑞传》"}, {"t": "于是益知西后与帝之不相容矣。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "帝王州", "t": "帝王居住的地方"}, {"w": "帝世", "t": "帝王的世系"}, {"w": "帝储", "t": "皇太子"}, {"w": "帝祚", "t": "帝位"}, {"w": "帝典", "t": "帝王的法制。"}]}, {"meaning": "称帝,为帝。", "cites": [{"t": "陛下承大乱之极,受命而帝,兴明祖宗。", "b": "《后汉书》"}, {"t": "子孙帝王万世之业也。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "尊奉为帝。", "cites": [{"t": "不敢复言帝秦!", "b": "《战国策·赵策三》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1634wx','施','1','shī','方','9','','[{"pinyin": "shī", "defs": [{"meaning": "(形声。从(yǎn),也声。本指旗帜)。"}, {"meaning": "旗飘动。", "cites": [{"t": "旖施,柔顺摇曳之貌。", "b": "《说文》朱骏声通训定声"}, {"t": "施,旗貌。", "b": "《说文》"}, {"t": "旖旎(施)从风。", "b": "《史记·司马相如传》。索隐:“犹阿那也。”"}]}, {"meaning": "假借为“吔”。给,给予。引申为施舍。", "cites": [{"t": "施,予也。", "b": "《广雅》"}, {"t": "德施普也。", "b": "《易·乾》。释文:“与也。”"}, {"t": "施其功事。", "b": "《周礼·内宰》。注:“赋也。”"}, {"t": "齐侯好示务施。", "b": "《国语·晋语》。注:“惠也。”"}, {"t": "旅有施舍。", "b": "《左传·宣公十二年》"}, {"t": "王施舍不倦。", "b": "《左传·昭公十九年》"}, {"t": "留待作遗施,于今无会图。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "施予", "t": "给,给别人恩惠、财物"}, {"w": "施生", "t": "施惠于人,给人生路"}, {"w": "施人", "t": "施恩于人"}, {"w": "施香", "t": "施舍香火钱"}, {"w": "施食", "t": "施舍食物"}, {"w": "施报", "t": "有所施与,则有所报答"}, {"w": "施赈", "t": "施舍财物救济贫民或灾民"}, {"w": "施遣", "t": "施舍赠送"}, {"w": "施泽", "t": "给予恩惠"}, {"w": "乐善好施", "t": ""}]}, {"meaning": "设置;安放。", "cites": [{"t": "施于中林。", "b": "《诗·周南·兔罝》"}, {"t": "施三川而归。", "b": "《史记·韩世家》。正义:“施犹设也。”"}, {"t": "秦政不施。", "b": "《汉书·蒯通传》。师古曰:“施,设也,立也。”"}, {"t": "中有都柱,傍行八道,施关发机。", "b": "《后汉书·张衡传》"}, {"t": "于厅事之东北角,施八尺屏障。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "施髟", "t": "安上假发"}, {"w": "施灵", "t": "设置灵堂"}, {"w": "施关", "t": "设立关卡"}, {"w": "施置", "t": "处置;安排。"}]}, {"meaning": "施行;实行;推行。", "cites": [{"t": "施于有政。", "b": "《论语·为政》。包注:“行也。”"}, {"t": "仁义不施而攻守之势异也。", "b": "汉·贾谊《过秦论上》"}, {"t": "时北兵已迫修门外,战、守、迁皆不及施。", "b": "宋·文天祥《指南录·后序》"}, {"t": "今王发政施仁,使天下仕者皆立于王之朝。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "施为", "t": "施展;作为"}, {"w": "施巧", "t": "施展巧技"}, {"w": "施令,施命", "t": "施行政令"}, {"w": "施张", "t": "施行"}, {"w": "施呈", "t": "施展"}, {"w": "施敬", "t": "施行庄敬之教。"}]}, {"meaning": "散布;铺陈。", "cites": [{"t": "云行雨施。", "b": "《周易·乾卦》"}, {"t": "阴谢阳施。", "b": "潘岳《闻居赋》。注:“布也。”"}], "words": [{"w": "施布", "t": "散布;传布"}, {"w": "施散", "t": "布施散发"}, {"w": "施属", "t": "散布连缀。"}]}, {"meaning": "加;施加。", "cites": [{"t": "己所不欲,勿施于人。", "b": "《论语·卫灵公》"}, {"t": "苟人事不施于其间,则莽莽榛榛。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "面如敷粉,唇若施脂。", "b": "《红楼梦》"}], "words": [{"w": "施肥;施朱", "t": "涂以红色"}, {"w": "施粉", "t": "涂粉"}, {"w": "施检", "t": "加印密封。"}]}, {"meaning": "判罪。", "cites": [{"t": "施生戮死。", "b": "《左传·昭公十四年》。注:“行罪也。”"}], "words": [{"w": "施行", "t": "处决,执行死刑;处置,发落。"}]}, {"meaning": "陈尸示众。", "cites": [{"t": "及文公入,秦人杀冀芮而施之。", "b": "《国语·晋语》"}, {"t": "君子不施其亲。", "b": "《论语》"}, {"t": "为大戮施之。", "b": "《国语·晋语》"}]}, {"meaning": "用;运用。", "cites": [{"t": "施则行。", "b": "《礼记·礼器》。疏:“用也。”"}, {"t": "爪牙之士施。", "b": "《荀子·臣道》。注:“谓展其材也。”"}, {"t": "妾不堪驱使,徒留无所施。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "靡计不施,迄无济。", "b": "《聊斋志异·促织》"}]}, {"meaning": "恩惠,仁慈。", "cites": [{"t": "未报秦施,而伐其师,其为死君乎?——《左传·僖公三十二——三十三年》", "b": ""}], "words": [{"w": "报施", "t": "报恩。"}]}, {"meaning": "旄羽珥,旗竿头上缀饰物。", "cites": [{"t": "楼烦以星施。", "b": "《逸周书》"}]}, {"meaning": "姓。施琅Shī Láng (1621—1696) 中国清朝时将领,福建晋江人。字尊侯,号琢公。初为郑芝龙部将,降清后任水师提督。康熙二十二年(1683年)攻灭台湾的郑氏政权。他建议在台湾驻兵屯守,以备御西方殖民者的侵略,为清政府所采纳。封靖海侯。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1635wx','闺','1','guī','门','9','','[{"pinyin": "guī", "defs": [{"meaning": "(形声。从门,圭声。“圭”亦具有表意作用。本义:上圆下方的小门;小门)。"}, {"meaning": "同本义。", "cites": [{"t": "闺,特立之户也。上圆下方,有似圭。", "b": "《说文》"}, {"t": "俯而出城门,以为小之闺也。", "b": "《荀子·解蔽》"}, {"t": "筚门闺窦之人。", "b": "《左传·襄公十年》"}, {"t": "公孙戍趋而去,未出,至中闺,君(指孟尝君)召而反之。", "b": "《战国策·齐策》"}], "words": [{"w": "闺窦", "t": "穿墙小门"}, {"w": "闺閤", "t": "宫中小门,内宫深处"}, {"w": "闺牖", "t": "宫内的门窗"}, {"w": "闺壸", "t": "内宫。"}]}, {"meaning": "内室。", "cites": [{"t": "室西连于中闺,先妣尝一至。", "b": "归有光《项脊轩志》"}, {"t": "今夫贵人之子,必宫居而闺处。", "b": "汉·枚乘《七发》"}], "words": [{"w": "闺门", "t": "内室的门。有时也称家门"}, {"w": "闺闱", "t": "内室"}, {"w": "闺閤", "t": "内室小门"}, {"w": "闺禁", "t": "宫中后妃居住处。"}]}, {"meaning": "特指女子居住的内室。", "cites": [{"t": "杨家有女初长成,养在深闺人未知。", "b": "白居易《长恨歌》"}, {"t": "可怜无定河边骨,犹是春闺梦里人。", "b": "唐·陈陶《陇西行》"}], "words": [{"w": "闺閤", "t": "女子的卧房。卧房,内室。也作闺阁"}, {"w": "闺阃", "t": "妇女所居的内室"}, {"w": "闺阈", "t": "女子居处的内室。即闺房"}, {"w": "闺声", "t": "来自闺房的笑声。"}]}, {"meaning": "借指妇女。", "cites": [{"t": "人间不见因谁知,万家闺艳求此时。", "b": "唐·刘言史《七夕歌》"}], "words": [{"w": "春闺;闺阃所无", "t": "比喻女子中少有的人才"}, {"w": "闺人", "t": "妇女"}, {"w": "闺妮", "t": "方言。指女儿"}, {"w": "闺艳", "t": "美丽的少女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1636wx','闻','1','wén','门','9','','[{"pinyin": "wén", "defs": [{"meaning": "(形声。从耳,门声。本义:听到)。"}, {"meaning": "同本义。", "cites": [{"t": "闻,知声也。", "b": "《说文》"}, {"t": "闻耳之聪也。", "b": "《墨子经上》"}, {"t": "心不在焉,视而不见,听而不闻。", "b": "《礼记·大学》"}, {"t": "闻佳人兮召予。", "b": "屈原《九歌·湘夫人》"}, {"t": "夜闻汉军四面皆楚歌。", "b": "《史记·项羽本纪》"}, {"t": "妾闻志士不饮盗泉之水。", "b": "《后汉书·列女传》"}, {"t": "闻屏障中。", "b": "《虞初新志·秋声诗自序》"}, {"t": "闻舟中夜弹琵琶者,听其音,铮铮然有京都声。", "b": "白居易《琵琶行(并序)》"}], "words": [{"w": "闻声不食", "t": "听到动物的叫声就不忍心吃它的肉"}, {"w": "闻所不闻", "t": "听到从未听过的事情。也说“闻所未闻”"}, {"w": "闻风响应", "t": "听到风声,便起而响应"}, {"w": "闻雷失箸", "t": "比喻假借其他不相关的事来掩饰自己的实情"}, {"w": "闻鸡起舞", "t": "祖逖与刘琨共被同寝,夜半闻荒鸡鸣,乃与琨起身舞剑。后世比喻有志之士及时奋起。"}]}, {"meaning": "听说;知道。", "cites": [{"t": "闻君行仁政。", "b": "《孟子·滕文公上》"}, {"t": "其闻道也。", "b": "唐·韩愈《师说》"}, {"t": "闻道有先后。", "b": ""}, {"t": "不可得闻。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "闻问", "t": "通音讯,获得音讯"}, {"w": "闻道", "t": "闻知领会道理"}, {"w": "闻说", "t": "听说"}, {"w": "闻得", "t": "听说"}, {"w": "闻知", "t": "听说;知道。"}]}, {"meaning": "传布,传扬。", "cites": [{"t": "贺兰山下阵如云,羽檄交驰日夕闻。", "b": "王维《老将行》"}], "words": [{"w": "闻诵", "t": "传布与称道。"}]}, {"meaning": "闻名,出名。", "cites": [{"t": "名闻天下。", "b": "《史记·魏公子列传》"}, {"t": "闻于诸侯。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "闻达于诸侯。", "b": "诸葛亮《出师表》"}, {"t": "以义闻于东南。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "嗅;嗅到。", "cites": [{"t": "与善人居,如入芝兰之室,久而不闻其香,即与之化矣。", "b": "《孔子家语·六本》"}, {"t": "罗襦襟解,微闻芗泽。", "b": "《史记·滑稽列传》"}], "words": [{"w": "自不可闻", "t": ""}]}, {"meaning": "询问;问候。", "cites": [{"t": "丧牛之凶,终莫之闻也。", "b": "《易·旅象》"}, {"t": "谓他人昆,亦莫我闻。", "b": "《诗·王风·葛藟》"}, {"t": "群公先正,则不我闻。", "b": "《诗·大雅·云汉》"}]}, {"meaning": "知识;见闻。", "cites": [{"t": "且夫我尝闻少仲尼之闻而轻伯夷之义者,始吾弗信。", "b": "《庄子·秋水》"}, {"t": "博闻强志。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "闻见", "t": "见闻。"}]}, {"meaning": "传闻,听到的事情;消息。", "cites": [{"t": "求闻之若此。", "b": "《吕氏春秋·慎行论》"}, {"t": "网罗天下放失旧闻。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "新闻;趣闻;要闻;旧闻;奇闻;见闻", "t": ""}]}, {"meaning": "声望;威望。", "cites": [{"t": "令闻令望。", "b": "《诗·大雅·卷阿》"}, {"t": "前时之闻。", "b": "宋·王安石《伤仲永》"}, {"t": "草野之无闻者。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "闻达;闻誉之施", "t": "指身受美名"}, {"w": "秽闻", "t": "丑恶的名声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1637wx','闽','1','mǐn','门','9','','[{"pinyin": "mǐn", "defs": [{"meaning": "(形声。从虫,门声。本义:古种族名。生活在浙江南部和福建一带,后因称福建为闽)。"}, {"meaning": "同本义。", "cites": [{"t": "閩,东南越也。", "b": "《说文》"}, {"t": "七閩九貉。", "b": "《周礼·职方式》"}, {"t": "閩在海中。", "b": "《山海经·海内经》"}, {"t": "选自閩禺。", "b": "左思《吴都赋》"}], "words": [{"w": "闽中", "t": "泛指福建省地"}, {"w": "闽江", "t": "水名。为福建省第一大河流"}, {"w": "闽关", "t": "指福建通内地的关隘"}, {"w": "闽岭", "t": "福建北部的山岭。"}]}, {"meaning": "五代十国之一 。933年王延钧在长乐(今福州市)称帝,国号闽。历三十七年,后被南唐所灭。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1638wx','阀','1','fá','门','9','','[{"pinyin": "fá", "defs": [{"meaning": "(形声。从门,伐声。本义:阀阅。即仕官人家自序功状而树立在门外左边的柱子)。"}, {"meaning": "同本义 釩 在左曰阀,在右曰阅。——《玉篇》。"}, {"meaning": "功劳 。也作“伐”。", "cites": [{"t": "献诚子煦,积阀亦至夏州节度使。", "b": "《旧唐书·张献诚传》"}]}, {"meaning": "名门巨室,仕宦人家。", "cites": [{"t": "东都仁和里裴尚书宽子孙众盛,实为名阀。", "b": "欧阳修《新唐书·柳玭传》"}], "words": [{"w": "阀阅", "t": "有权势的仕宦人家。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1639wx','阁','1','gé','门','9','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从门,各声。本义:古代放在门上用来防止门自合的长木桩)。"}, {"meaning": "门限。", "cites": [{"t": "閣,所止扉也。门开则旁有两长橜杆辂之,止其自阖也。", "b": "《说文》"}, {"t": "高其闬阁。", "b": "《左传》。"}, {"t": "所以止扉谓之阁。", "b": "《尔雅》。郝懿行疏:“此阁以长木为之,各施于门扇两旁,以止其走扇。”"}]}, {"meaning": "一种架空的小楼房,中国传统建筑物的一种。其特点是通常四周设隔扇或栏杆回廊,供远眺、游憩、藏书和供佛之用。", "cites": [{"t": "接屋连阁。", "b": "《淮南子·主术训》"}, {"t": "五步一楼,十步一阁。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "细瞻景状,与村东大佛阁逼似。", "b": "《聊斋志异·促织》"}], "words": [{"w": "阁中", "t": "楼阁之中"}, {"w": "亭台楼阁;阁仔", "t": "小木板屋"}, {"w": "阁束", "t": "束之高阁"}, {"w": "阁室", "t": "阁道中的小室"}, {"w": "阁馆", "t": "楼阁馆舍"}, {"w": "阁殿", "t": "楼阁官殿。"}]}, {"meaning": "藏书的地方。", "cites": [{"t": "时雄校书天禄阁上。", "b": "《汉书·扬雄传》"}]}, {"meaning": "架空的栈道。用木板架筑在山岩绝险处的道路。", "cites": [{"t": "为栈道木阁而迎王与后于城阳山中。", "b": "《战国策·齐策》"}, {"t": "率所领径先南归,所过烧绝阁道。", "b": "《三国志·魏延传》"}], "words": [{"w": "阁梁", "t": "阁道的横梁"}, {"w": "阁路", "t": "栈道。"}]}, {"meaning": "官署名。内阁的简称。", "cites": [{"t": "会帝有疾,烦懑不乐,召阁臣徐阶议内禅。", "b": "《明史·海瑞传》"}], "words": [{"w": "组阁;入阁;阁老", "t": "大学士及翰林学士入阁办事的大臣"}, {"w": "阁抄", "t": "中央政府的公报"}, {"w": "阁学", "t": "内阁学士。"}]}, {"meaning": "特指女子的卧房。", "cites": [{"t": "开我东阁门,坐我西阁床。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "出阁", "t": ""}]}, {"meaning": "放置,搁置。", "cites": [{"t": "险绝之处,傍凿山崖而施版梁为阁。", "b": "《史记·高祖本纪》集解引崔浩"}], "words": [{"w": "阁笔", "t": "停笔。同搁笔"}, {"w": "阁压", "t": "搁置积压。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1640wx','差','1','chā chà chāi chài cī','工','9','','[{"pinyin": "chā", "defs": [{"meaning": "(会意。小篆,从左(手)。本义:失当;错;相差) 同本义。", "cites": [{"t": "差,贰也,差不相值也。", "b": "《说文》"}, {"t": "乱生其差。", "b": "《荀子·天论》。注:“谬也。”"}, {"t": "称轻重而不差。", "b": "《楚辞·严忌哀时命》"}, {"t": "毋有差贷。", "b": "《礼记·月令仲冬》"}, {"t": "差若毫厘,谬以千里,其此之谓乎?", "b": "《魏书·张普惠传》"}], "words": [{"w": "说差啦;认差了", "t": ""}]}, {"meaning": "区别。", "cites": [{"t": "何必更以多寡为差。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "差别", "t": "区别,分别"}, {"w": "差异", "t": "不同。"}]}]}, {"pinyin": "chà", "defs": []}, {"pinyin": "chāi", "defs": [{"meaning": "指派;派遣。", "cites": [{"t": "一面差人到吴侯处报捷。", "b": "《三国演义》"}], "words": [{"w": "差人", "t": "派遣仆隶"}, {"w": "差委", "t": "委派;派遣。"}]}, {"meaning": "选择。", "cites": [{"t": "差时择日。", "b": "宋玉《高唐赋》"}], "words": [{"w": "差择", "t": "选择"}, {"w": "差选", "t": "挑选,选择。"}]}]}, {"pinyin": "chài", "defs": [{"meaning": "病愈", "cites": [{"t": "后虽小差,犹尚殗殜,无所遣娱。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "大病差后", "t": ""}]}]}, {"pinyin": "cī", "defs": [{"meaning": "限度;界限。", "cites": [{"t": "轻用人力,缮修宫宇,出入无节,喜怒过差。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1641wx','养','1','yǎng','丷','9','','[{"pinyin": "yǎng", "defs": [{"meaning": "(形声。从食,羊声。本义:饲养)。"}, {"meaning": "供养,奉养;抚育。", "cites": [{"t": "养,供养也。", "b": "《说文》。古文从攴,未详。疑厮养作此字。"}, {"t": "凡食养阴气也,凡饮养阳气也。", "b": "《礼记·郊特牲》"}, {"t": "殳能生之不能养之。", "b": "《荀子·礼论》"}, {"t": "养不亏。", "b": "《韩非子·五蠹》"}, {"t": "监门之养。", "b": ""}, {"t": "不食力而养足。", "b": "《韩非子·五蠹》"}, {"t": "养公姥。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "供养卒大恩。", "b": ""}, {"t": "归养。", "b": "《史记·魏公子列传》"}, {"t": "以养父母。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "养娇囡", "t": "因父母溺爱而性格骄纵的姑娘"}, {"w": "养家人", "t": "担负赡养全家生计的人"}, {"w": "养济院", "t": "孤老院。专收鳏寡孤独老人的慈善机构。"}]}, {"meaning": "饲养。", "cites": [{"t": "驯养一虫。", "b": "《聊斋志异·促织》"}, {"t": "于盆而养。", "b": ""}, {"t": "笼养之。", "b": ""}], "words": [{"w": "养鸡;养狗;养牛;养马", "t": ""}]}, {"meaning": "生育。", "cites": [{"t": "家家养男当门户。", "b": "唐·张籍《筑城词》"}], "words": [{"w": "养孩子", "t": ""}]}, {"meaning": "培养,修养。", "cites": [{"t": "立太傅少傅以养之。", "b": "《礼记·文王世子》。注:“犹教之。”"}, {"t": "养其旁条。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "养息机", "t": "修养身心;修炼"}, {"w": "养材儿", "t": "正处在教养阶段学习干活的少年"}, {"w": "养廉银子", "t": "清朝按职务等级,在常俸之外另给官吏的银钱"}, {"w": "养士", "t": "培养人才。"}]}, {"meaning": "保养。", "cites": [{"t": "养其根。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "养其身。", "b": "宋·苏轼《教战守》"}, {"t": "养之太过。", "b": ""}], "words": [{"w": "养身", "t": "保养身体。同养生。"}]}, {"meaning": "治,调养。", "cites": [{"t": "以五味五谷五药养其病。", "b": "《周礼·疾医》"}], "words": [{"w": "养疴", "t": "调养疾病。"}]}, {"meaning": "皮肤受刺激,产生欲搔的感觉。", "cites": [{"t": "骨体肤理辨寒暑疾痒。", "b": "《荀子·荣辱》。杨倞注:“养与痒同。”"}, {"t": "疾、养、凔、热、滑、铍、轻、重,以形体异。", "b": "《荀子·正名》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1642wx','美','1','měi','八','9','','[{"pinyin": "měi", "defs": [{"meaning": "(会意。金文字形,从羊,从大,古人以羊为主要副食品,肥壮的羊吃起来味很美。本义:味美)。"}, {"meaning": "同本义。", "cites": [{"t": "美,甘也。", "b": "《说文》"}, {"t": "然后天地之美生。", "b": "《管子·五行》。注:“谓甘露醴泉之类也。”"}, {"t": "食必珍美。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "美酒;美甘甘", "t": "形容非常甘美或甜蜜"}, {"w": "美味", "t": "美好的滋味;可口的食品"}, {"w": "美食", "t": "味美的食品;吃味美的食物。"}]}, {"meaning": "形貌好看,漂亮。", "cites": [{"t": "美孟姜也。", "b": "《诗·鄘风·桑中》"}, {"t": "美孟弋矣。", "b": ""}, {"t": "我孰与城北徐公美?", "b": "《战国策·齐策》"}, {"t": "梅以曲为美,直则无姿。", "b": "龚自珍《病梅馆记》"}], "words": [{"w": "美姬", "t": "美丽的女子"}, {"w": "美眷", "t": "美丽的女眷;美人"}, {"w": "美色", "t": "姣美的姿色"}, {"w": "美劭", "t": "俊美,秀美。"}]}, {"meaning": "美好。", "cites": [{"t": "晋侯之美也。", "b": "《公羊传·庄公十二年》"}, {"t": "我孰与城北徐公美?", "b": "《战国策·齐策一》"}, {"t": "王为建取妻于秦而美。", "b": "《吕氏春秋·慎行》"}, {"t": "其民愿,其俗美。", "b": "《荀子·王霸》"}, {"t": "芳草鲜美。", "b": "晋·陶渊明《桃花源记》"}, {"t": "天下之美。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "才美不外现。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "良田美池;美除", "t": "好差事,好官职"}, {"w": "美缺", "t": "有利可图的官职,肥缺"}, {"w": "美文", "t": "优美的文辞"}, {"w": "美姿", "t": "美好的姿容"}, {"w": "美禄", "t": "美好的赏赐;指酒"}, {"w": "美才", "t": "出色的才学;杰出的人才"}, {"w": "美中不足", "t": "虽好但还有不足之处"}, {"w": "美玉无瑕", "t": "比喻完美无缺。"}]}, {"meaning": "理想。", "cites": [{"t": "尽美也。", "b": "《论语》。皇疏:“堪合当时之称。”"}], "words": [{"w": "美选", "t": "理想的人选"}, {"w": "美迁", "t": "升任理想的职位"}, {"w": "美拜", "t": "美除、美授。担任好的官位。"}]}, {"meaning": "称美;赞美。", "cites": [{"t": "毛嫱丽姬,人之所美也。", "b": "《庄子·齐物论》"}], "words": [{"w": "美言", "t": "嘉言"}, {"w": "美刺", "t": "称美与讽恶。多用于诗文"}, {"w": "美咏", "t": "赞美咏叹。"}]}, {"meaning": "认为…美;使事物变美,变好。", "cites": [{"t": "吾妻之美我者,私我也。", "b": "《战国策·齐策》"}, {"t": "凡美田之法,绿豆为上,小豆、胡麻次之。", "b": "《齐民要术·耕田》"}], "words": [{"w": "美田", "t": "使田地肥沃"}, {"w": "美政", "t": "使政治美善"}, {"w": "美俗", "t": "使风俗淳美。"}]}, {"meaning": "音调的主观单位,等于频率为1000赫的音的音调的千分之一——尤其用于听觉学。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1643wx','姜','1','jiāng','女','9','','[{"pinyin": "jiāng", "defs": [{"meaning": "(形声。从女,羊声。本义:水名。姜水)。"}, {"meaning": "同本义。", "cites": [{"t": "岐水经姜氏城为姜水。", "b": "《水经注·渭水》注"}, {"t": "黄帝以姬水成,炎帝以姜水成。", "b": "《国语》"}]}, {"meaning": "", "cites": [{"t": "姜,神农居姜水,以为姓。", "b": "《说文》"}], "words": [{"w": "姜太公钓鱼", "t": "姜子牙世称姜太公,即吕尚。曾辅佐周文王、周武王灭商。后被封为齐侯。传说姜子牙在渭水边钓鱼的时候,钓绳端的直钓不设饵。歇后用法,愿者上钩,指事情出于自愿。"}]}, {"meaning": "生姜。", "cites": [{"t": "楠梓姜桂。", "b": "《史记·货殖列传》"}]}, {"meaning": "一种姜属多年生草本植物(Zingiber officinate),作一年生栽培。须根不发达,根茎肥大,呈不规则块状,灰白或黄色,有辛辣味,可作蔬菜、调料,亦入药。", "cites": [{"t": "不撤姜食,不多食。", "b": "《论语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1644wx','叛','1','pàn','又','9','','[{"pinyin": "pàn", "defs": [{"meaning": "(形声。从反,半声。本义:背叛) 同本义。", "cites": [{"t": "叛,乱也。", "b": "《广雅》"}, {"t": "信中涂而叛之。", "b": "《楚辞·逢纷》"}, {"t": "叛者,反背之辞也。", "b": "《左传释例》"}, {"t": "侯不朝,兹谓叛。", "b": "《汉书·五行志》"}, {"t": "叛者五人。", "b": "《公羊传·定公八年》"}, {"t": "天下皆叛之。", "b": "《史记·项羽本纪》"}], "words": [{"w": "众叛亲离;反叛", "t": "叛变"}, {"w": "叛道", "t": "背叛正道"}, {"w": "叛败", "t": "谋叛而败亡"}, {"w": "叛镇", "t": "背叛朝廷的藩镇"}, {"w": "叛附", "t": "叛变后另有依附"}, {"w": "叛服", "t": "叛变或顺服"}, {"w": "叛降", "t": "叛变投敌。"}]}, {"meaning": "零乱的。", "cites": [{"t": "约则义孤,博则辞叛。", "b": "《文心雕龙》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1645wx','送','1','sòng','辶','9','','[{"pinyin": "sòng", "defs": [{"meaning": "(会意。小篆字形)。"}, {"meaning": "同本义。", "cites": [{"t": "送,遣也。", "b": "《说文》。"}, {"t": "送迎无礼。", "b": "《荀子·富国》。注:“致女也。”"}], "words": [{"w": "送嫁", "t": "送亲"}, {"w": "送娘", "t": "方言。送新娘子"}, {"w": "送房", "t": "结婚之夕,亲友陪送新郎入洞房"}, {"w": "送亲", "t": "娘家人送出嫁的姑娘上轿或送新娘到男家。"}]}, {"meaning": "送行;送别。", "cites": [{"t": "寒雨连江夜入吴,平明送客楚山孤。", "b": "唐·王昌龄《芙蓉楼送辛渐》"}, {"t": "太子及宾客知其事者,皆白衣冠以送之。", "b": "《战国策·燕策》"}], "words": [{"w": "送车", "t": "到车站送行;又指送行的车"}, {"w": "送迎钱", "t": "迎送官员的开销"}, {"w": "送任", "t": "送亲属去当人质"}, {"w": "送迎", "t": "送往迎来"}, {"w": "送路", "t": "送行;饯别"}, {"w": "送故迎新", "t": "送旧官,迎新官;送旧岁,迎新年。"}]}, {"meaning": "将东西运去或传交 。又。", "cites": [{"t": "录毕,走送之,不敢稍逾约。", "b": "明·宋濂《送东阳马生序》"}, {"t": "赵王乃斋戒五日,使臣奉璧,拜送书于庭。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "干戈日滋,行者赍,居者送,中外骚扰相奉。", "b": "《汉书·食货志》"}], "words": [{"w": "送茶", "t": "送礼"}, {"w": "送还", "t": "送给"}, {"w": "送款", "t": "表示诚心诚意的投降"}, {"w": "送风", "t": "传递消息,通风报信"}, {"w": "送盏", "t": "递送酒器以劝饮"}, {"w": "送语", "t": "传话"}, {"w": "送意", "t": "传送情意"}, {"w": "送怀", "t": "传达思想感情。"}]}, {"meaning": "遣送。", "cites": [{"t": "愬以槛车送元济诣京师。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "送遣", "t": "遣送,送归"}, {"w": "送转", "t": "方言。送归,送还"}, {"w": "送传", "t": "押送递解"}, {"w": "送官", "t": "送交官府。"}]}, {"meaning": "送葬;送丧。", "cites": [{"t": "丧出江上,白衣冠送者夹岸,酹而器者百里不绝。", "b": "《明史·海瑞传》"}], "words": [{"w": "送老", "t": "安葬老人或长辈"}, {"w": "送横", "t": "为横死者送丧"}, {"w": "送哭", "t": "哀哭而送葬。"}]}, {"meaning": "馈赠。", "cites": [{"t": "今吾且死,而侯生曾无一言半辞送我,我曾有所失哉。", "b": "《史记·魏公子列传》"}, {"t": "(申屠臾)坐为九江太守受故官送有罪,国除。", "b": "《史记·申屠嘉列传》"}], "words": [{"w": "送定", "t": "为定婚,男方给女方家里送聘礼"}, {"w": "送锅", "t": "送饭锅祝贺乔迁之喜"}, {"w": "送粥米", "t": "妇女坐月子时,娘家和亲戚送给她鸡蛋、小米等东西"}, {"w": "送鲜", "t": "赠送新鲜食品"}, {"w": "送赆", "t": "赠送钱财、礼物"}, {"w": "送盘", "t": "方言。送聘礼"}, {"w": "送遗", "t": "赠送"}, {"w": "送汤", "t": "亲友女儿出嫁或生产,送礼致贺。"}]}, {"meaning": "了结;断送。", "cites": [{"t": "夫以慕容超之强,身送东市;姚泓之盛,面缚西都。", "b": "《文选·丘迟·与陈伯之书》"}, {"t": "才上马齐声儿喝道,只这的便是那送了人的根苗。", "b": "《朝野新声太平乐府·张云庄·红绣鞋》"}], "words": [{"w": "送断", "t": "断送;葬送"}, {"w": "送死", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1646wx','类','1','lèi','米','9','','[{"pinyin": "lèi", "defs": [{"meaning": "(形声。从犬,頪(lèi)声。从“犬”,因犬种类最相似。本义:种类)。"}, {"meaning": "同本义。", "cites": [{"t": "类,种类相似,惟犬最甚。", "b": "《说文》"}, {"t": "皆守株之类。", "b": "《韩非子·五蠹》"}, {"t": "无法者以类举。", "b": "《荀子·王制》"}, {"t": "壹统类。—《荀子·非十二子》", "b": ""}, {"t": "其负类反伦,不可胜言也。", "b": "《列子·仲尼》"}, {"t": "王之不王,是折枝之类也。", "b": "《孟子·梁惠王上》"}, {"t": "同类相从,同声相应,固天之理也。", "b": "《庄子·渔父》"}, {"t": "纸灰之类冒之。", "b": "宋·沈括《梦溪笔谈·活板》"}]}, {"meaning": "又。", "cites": [{"t": "亦类此耳。", "b": ""}, {"t": "梨栗枣柿之类。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "类考", "t": "学院的科考"}, {"w": "类族", "t": "事物因习性相近而形成的类别"}, {"w": "类神", "t": "迷信占卜名词。六壬课中十二个用来判别吉凶的“十二支神”的总称。"}]}, {"meaning": "族类。", "cites": [{"t": "吾三番擒之而不杀,诚欲服其心,不欲灭其类也。", "b": "《三国演义》"}]}, {"meaning": "事例;条例。", "cites": [{"t": "举类迩而见义远。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "缺点,毛病。", "cites": [{"t": "民之生也,辟则愚,闭则类。", "b": "《管子·乘马》"}, {"t": "大者大类,小者则治。", "b": "《管子·地员》"}]}, {"meaning": "古祭名,祭天。", "cites": [{"t": "肆类于上帝,禋于六宗。", "b": "《书·尧典下》"}, {"t": "是类是妈祃,是致是附。", "b": "《诗·大雅·皇矣》"}]}, {"meaning": "相似;像。", "cites": [{"t": "遂入,杀孟阳于床。曰:“非君也,不类。”", "b": "《左传·庄公八年》"}, {"t": "不类前人。", "b": "《论衡·自纪》"}, {"t": "与张氏之吝书若不相类。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "又。", "cites": [{"t": "令黄生贫类予,其借书亦类予。", "b": ""}, {"t": "语类楚声。", "b": "明·魏禧《大铁椎传》"}, {"t": "绝类弥勒。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "画虎不成反类犬", "t": ""}]}, {"meaning": "类比;类推。", "cites": [{"t": "义不杀少而杀众,不可谓知类。", "b": "《墨子》"}], "words": [{"w": "类推", "t": ""}]}, {"meaning": "偏,不平。", "cites": [{"t": "夫富贵者则类,傲之;夫贫贱者则求柔之;是非仁人之情也。", "b": "《荀子·不苟》"}]}, {"meaning": "大抵;大都。", "cites": [{"t": "观古今文人,类不护细行。", "b": "三国魏·曹丕《与吴质书》"}, {"t": "走卒类士服。", "b": "宋·司马光《训俭示康》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1647wx','迷','1','mí','辶','9','','[{"pinyin": "mí", "defs": [{"meaning": "(形声。从辵(chuò),米声。本义:迷路;分辨不清)。"}, {"meaning": "同本义。", "cites": [{"t": "迷,惑也。", "b": "《说文》"}, {"t": "烈风雷雨弗迷。", "b": "《书·舜典》"}, {"t": "凡夫失其所欲之路,而妄行之,则为迷。", "b": "《韩非子·解老》"}, {"t": "及行迷之未远。", "b": "《离骚》"}, {"t": "迷不知宠之门。", "b": "《楚辞·惜诵》"}, {"t": "迷其所在。", "b": "《聊斋志异·促织》"}, {"t": "入溆浦余儃佪兮,迷不知吾所如。", "b": "《楚辞·九章·涉江》"}, {"t": "高低冥迷,不知西东。", "b": "杜牧《阿房宫赋》"}, {"t": "遂迷,不复得路。", "b": "晋·陶渊明《桃花源记》"}, {"t": "其若迷。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "无迷其途。", "b": ""}, {"t": "道中迷雾。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "迷离徜彷", "t": "模糊不明"}, {"w": "迷罔;迷岸", "t": "佛家语。指迷惑而不悟的生死流转世界。"}]}, {"meaning": "迷惑,使…辨不清。", "cites": [{"t": "乱花渐欲迷人眼,浅草才能没马蹄。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "迷魂", "t": "迷惑人的事理,使人身不由己"}, {"w": "迷网", "t": "指迷惑人的事物像网罗一样,使人陷落而无以自拔"}, {"w": "迷夺时明", "t": "迷惑、剥夺当今明哲之士的舆论"}, {"w": "迷眩缠陷", "t": "以声色迷惑,为罗网陷阱"}, {"w": "迷途", "t": ""}]}, {"meaning": "迷恋。", "cites": [{"t": "迷花倚石忽已暝(迷恋着花,依倚着石,不觉天色已经晚了。暝,天黑、夜晚)。", "b": "唐·李白《梦游天姥吟留别》"}]}, {"meaning": "昏迷。", "cites": [{"t": "扁鹊遂饮二人毒酒,迷死三日。", "b": "《列子·汤问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1648wx','籽','1','zǐ','米','9','','[{"pinyin": "zǐ", "defs": [{"meaning": "某些植物所结的种子", "words": [{"w": "菜籽", "t": ""}, {"w": "麦籽", "t": ""}, {"w": "籽粒", "t": "谷类的种子;亦指粮食;粮食的颗粒。"}, {"w": "籽骨", "t": "受压较大的肌腱内生成的和中小骨。"}, {"w": "籽棉", "t": "摘下来以后还没有去掉种子的棉花。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1649wx','娄','1','lóu','女','9','','[{"pinyin": "lóu", "defs": [{"meaning": "物体中空的。", "cites": [{"t": "娄,空也。", "b": "《说文》。段玉裁注:“凡中空曰娄,今俗语尚如是。”"}]}, {"meaning": "收敛。", "cites": [{"t": "莫肯下遣,式居娄骄。", "b": "《诗·小雅·角弓》"}]}, {"meaning": "二十八宿之一,西方白虎七宿的第二宿。有白羊座α、β、γ星三颗。"}, {"meaning": "母猪。", "cites": [{"t": "既定尔娄猪。", "b": "《左传·定公十四年》"}]}, {"meaning": "小土丘。", "cites": [{"t": "部娄无松柏。", "b": "《左传·襄公二十四年》"}]}, {"meaning": "多次。", "cites": [{"t": "娄丰年。", "b": "《诗·周颂·桓》"}, {"t": "时上方兴功业,娄举贤良。", "b": "《汉书·公孙弘传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1650wx','前','1','qián','刂','9','','[{"pinyin": "qián", "defs": [{"meaning": "(本义:前进)。"}, {"meaning": "同本义。", "cites": [{"t": "前,进也。", "b": "《广雅》"}, {"t": "然而驱之不前,却之不止。", "b": "《韩非子·外储说右上》"}, {"t": "相如视秦王无意偿赵城,乃前曰。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "罗敷前致词。", "b": "《乐府诗集·陌上桑》"}, {"t": "听妇前致词。", "b": "唐·杜甫《石壕吏》"}, {"t": "狼不敢前。", "b": "《聊斋志异·狼三则》"}, {"t": "驰而前。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "孔子下车而前。", "b": "《庄子》"}], "words": [{"w": "前却", "t": "进退"}, {"w": "前迈", "t": "前行,前进"}, {"w": "前旌", "t": "仪仗中前行的旗帜。"}]}, {"meaning": "引导。", "cites": [{"t": "尸谡祝前。", "b": "《仪礼·特牲礼》。注:“犹导也。”"}, {"t": "张若、謵朋前马。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "前王", "t": "古代举行仪式时在前面引导帝王"}, {"w": "前马", "t": "在马前引导或护卫。"}]}, {"meaning": "进见。", "cites": [{"t": "允乞更一见,然后为诏。诏引前。", "b": "《魏书》"}]}, {"meaning": "剪裁。", "cites": [{"t": "无前则徵多,徵多故富。", "b": "《韩非子·八经》"}]}, {"meaning": "前面,与“后”相对;正面。", "cites": [{"t": "在前上处。", "b": "《诗·邶风·简兮》"}, {"t": "百夫荷素质之旗于王前。", "b": "《周书·克殷》"}, {"t": "近出前后。", "b": "唐·柳宗元《三戒》"}, {"t": "犬坐于前。", "b": "《聊斋志异·狼三则》"}, {"t": "恐前后受敌。", "b": ""}], "words": [{"w": "前队", "t": "前锋"}, {"w": "前途", "t": "前面;前边"}, {"w": "前件", "t": "前已述及的人或事物;逻辑学用语。与“后件”对称。假言判断中规定条件的判断叫“前件”,以前件为条件的判断叫“后件”"}, {"w": "前行", "t": "前锋"}, {"w": "前和", "t": "枪的前额"}, {"w": "前轨", "t": "犹前辙"}, {"w": "前军", "t": "先头部队。"}]}, {"meaning": "与“后”相对,时间在先。", "cites": [{"t": "我未之前闻也。", "b": "《礼记·檀弓》。注:“犹故也。”"}, {"t": "前事之不忘,后事之师也。", "b": "《史记·秦始皇纪赞》"}, {"t": "前知其如此。", "b": "宋·王安石《答司马谏议书》"}, {"t": "前时之闻。", "b": "宋·王安石《伤仲永》"}, {"t": "前人之述。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "说前代事。", "b": "清·周容《芋老人传》"}], "words": [{"w": "前倨后恭", "t": "先傲慢,后谦恭"}, {"w": "前光", "t": "先人的光辉"}, {"w": "前番", "t": "前一次;上一次"}, {"w": "前埭", "t": "上次"}, {"w": "前限", "t": "前次的限期"}, {"w": "前半三世", "t": "前半生"}, {"w": "前家", "t": "前妻"}, {"w": "前家儿", "t": "前妻之子"}, {"w": "前星", "t": "指太子"}, {"w": "前行", "t": "旧时美称吏员"}, {"w": "前绪", "t": "前人的功业。"}]}, {"meaning": "预先;事前。", "cites": [{"t": "可以前知。", "b": "《礼记·中庸》。注:“亦先也。”"}, {"t": "至于怨诽之多,则固前知其如此也。", "b": "《答司马谏议书》"}], "words": [{"w": "日前;生前;午前;前知", "t": "预知;有预见;事先知道"}, {"w": "前算", "t": "事前筹划"}, {"w": "前虑", "t": "事前的谋虑"}, {"w": "前觉", "t": "犹先觉。"}]}, {"meaning": "目前。", "cites": [{"t": "事效见前。", "b": "《汉书·严助传》。注:“前,目前也。”"}]}, {"meaning": "箭竹。", "cites": [{"t": "有竹前檀柘之壤。", "b": "《管子·山国轨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1651wx','首','1','shǒu','首','9','','[{"pinyin": "shǒu", "defs": [{"meaning": "(象形。金文字形,上面是头发和头皮,用以表示头盖;下面是眼睛,用以代表面部。本义:头)。"}, {"meaning": "同本义。", "cites": [{"t": "首,阳也。", "b": "《汉书·天文志》"}, {"t": "首身离兮心不惩。", "b": "《楚辞·九歌·国殇》"}, {"t": "愿言思伯,甘心首疾。", "b": "《诗·卫风·伯兮》"}, {"t": "搔首踟蹰。", "b": "《诗·邶风·静女》"}, {"t": "愿得将军之首以献秦。", "b": "《战国策·燕策》"}, {"t": "以刀劈狼首。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "昂首;叩首;搔首;首功", "t": "以获敌首论功"}, {"w": "首虏", "t": "指斩获敌人的首级"}, {"w": "首枕其股", "t": "让死者的头枕在自己的腿上。这是古代臣下对横遭杀害的君主表示哀痛之礼"}, {"w": "首丘", "t": "归葬故乡;亦指怀念故乡"}, {"w": "首身分离", "t": "被杀,判处斩刑。"}]}, {"meaning": "首领,团体的领导人。", "cites": [{"t": "凡百元首,承天景命。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "元首;酋首;群龙无首", "t": ""}]}, {"meaning": "开端;开头;前端。", "cites": [{"t": "故治民者,刑胜,治之首也。", "b": "《韩非子·心度》"}, {"t": "操军方连船舰,首尾相接。", "b": "《资治通鉴》"}, {"t": "自七月二十六日至是,首尾才六日。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "首事", "t": "开始"}, {"w": "首春", "t": "孟春。指农历正月"}, {"w": "首秋", "t": "孟秋。指农历七月"}, {"w": "首祚", "t": "一年的开头"}, {"w": "首夏", "t": "夏季之始。即“孟夏”。指农历四月"}, {"w": "首岁", "t": "正月。一年的开始。"}]}, {"meaning": "要领。", "cites": [{"t": "予誓告汝群言之首。", "b": "《书·秦誓》"}]}, {"meaning": "剑柄上的环。", "cites": [{"t": "进剑者左首。", "b": "《礼记》"}]}, {"meaning": "位次。方;面。", "cites": [{"t": "史进下首坐了。", "b": "《水浒传》"}], "words": [{"w": "左首;上首;外首;东首;门首", "t": ""}]}, {"meaning": "第一。", "cites": [{"t": "故教化之行也,建首善自京师始。", "b": "《汉书·儒林传序》"}], "words": [{"w": "首公", "t": "以公务为首要。即“奉公”"}, {"w": "首功", "t": "第一等功劳"}, {"w": "首选", "t": "当选为第一。科举时代考试名列第一"}, {"w": "首妻;首位;首名;首恶;首犯;首僧", "t": "当家和尚"}, {"w": "首县", "t": "县城和府城在一处的县,也指知县"}, {"w": "首事", "t": "地方上领头管事的绅士"}, {"w": "首事", "t": "首要的事"}, {"w": "首从", "t": "主犯与从犯。"}]}, {"meaning": "形容迟疑不决。", "cites": [{"t": "先是小月氏胡分居塞内,胜兵者二三千骑,皆勇健富彊,每与羌战,常以少制多。虽首施两端,汉亦收其用。", "b": "《后汉书·邓训传》"}], "words": [{"w": "首施", "t": "迟疑进退不定。同首鼠"}, {"w": "首鼠", "t": "迟疑不决。也作“首施”。"}]}, {"meaning": "告发。", "cites": [{"t": "苟不欲救,请至颐和园首仆而杀仆,可以得富贵也。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "首诉", "t": "出首;控告"}, {"w": "首人", "t": "出面告状的人。"}]}, {"meaning": "自首,犯人自己到有关部门去交代罪行。", "cites": [{"t": "(贼役赃官)一半都来睦县自行投首,拜参张招讨并众官,尽皆准首,复为良民。", "b": "《水浒传》"}], "words": [{"w": "首官", "t": "向官府自首或告发"}, {"w": "自首;首状", "t": "自首或告发的状词"}, {"w": "首免", "t": "指自首而得以从轻发落"}, {"w": "首罪", "t": "自首。"}]}, {"meaning": "头向着。", "cites": [{"t": "鸟飞反故乡兮,狐死必首丘。", "b": "《楚辞·九章·哀郢》"}]}, {"meaning": "向着…出发。", "cites": [{"t": "北首燕路。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "首路", "t": "出发"}, {"w": "首涂", "t": "启程;上路。"}]}, {"meaning": "屈服;服罪。", "cites": [{"t": "虽有降首,曾莫惩革,自此浸以疏慢矣。", "b": "《后汉书》"}]}, {"meaning": "标明;显示。", "cites": [{"t": "所以首其内,而见诸外也。", "b": "《礼记》"}]}, {"meaning": "最早;首先。", "cites": [{"t": "陈涉首难,豪杰蜂起。", "b": "《史记·项羽本纪》"}], "words": [{"w": "首唱", "t": "首先倡导、发起。也作“首倡”"}, {"w": "首创", "t": "创始。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1652wx','逆','1','nì','辶','9','','[{"pinyin": "nì", "defs": [{"meaning": "(形声。从辵(chuò),屰(nì)声。本义:迎,迎接,迎着)。"}, {"meaning": "同本义。", "cites": [{"t": "逆,迎也。关东曰逆,关西曰迎。", "b": "《说文》"}, {"t": "宣公如齐逆女。", "b": "《左传·成公十四年》"}, {"t": "上卿逆于境。", "b": "《国语·周语上》"}, {"t": "楚庄王伐郑,郑伯肉袒牵羊以逆。", "b": "宋·苏轼《留侯论》"}, {"t": "晋侯逆夫人嬴氏以归。", "b": "《左传·僖公二十三年》"}, {"t": "尝过青城山,遇雪,舍于逆旅。", "b": "沈括《梦溪笔谈·人事一》"}, {"t": "陶子将辞逆旅之馆,永归于本宅。", "b": "陶潜《自祭文》"}], "words": [{"w": "逆战", "t": "迎战"}, {"w": "逆厘", "t": "迎福纳吉"}, {"w": "逆劳", "t": "迎劳"}, {"w": "逆暑", "t": "迎夏。迎接暑气到来的祭礼"}, {"w": "逆视", "t": "迎视"}, {"w": "逆送", "t": "迎送"}, {"w": "逆女", "t": "迎接女儿归宁。"}]}, {"meaning": "迎击;迎战。", "cites": [{"t": "并力逆操。", "b": "《资治通鉴》"}], "words": [{"w": "逆涛", "t": "顶着浪涛"}, {"w": "逆击", "t": "迎击"}, {"w": "逆格", "t": "迎击"}, {"w": "逆拒", "t": "迎击,抵御。"}]}, {"meaning": "倒;反;向相反方向活动。", "cites": [{"t": "水逆流百余里。", "b": "郦道元《水经注·江水》"}], "words": [{"w": "逆电流;逆鳞", "t": "倒生的鳞片"}, {"w": "逆向", "t": "反方向"}, {"w": "逆溢", "t": "水倒流泛滥"}, {"w": "逆推", "t": "由下向上、由后向前推测。"}]}, {"meaning": "抵触;不顺;违背。", "cites": [{"t": "逆节伤化,不道。", "b": "《汉书·赵尹韩张两王传》"}, {"t": "本末舛逆,首尾衡决", "b": "汉·贾谊《治安策》"}, {"t": "且以一璧之故,逆强秦之欢,不可。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "忠言逆耳。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "逆时代潮流而动;逆拂", "t": "拂逆"}, {"w": "逆辞", "t": "违背礼数的言辞"}, {"w": "逆意", "t": "违背尊长的心意"}, {"w": "逆节", "t": "违背法度"}, {"w": "逆道", "t": "违背事理"}, {"w": "逆理", "t": "违背事理"}, {"w": "逆负", "t": "违背辜负。"}]}, {"meaning": "颠倒。", "cites": [{"t": "大事于大庙,跻僖公,逆祀也。", "b": "《左传·文公二年》"}], "words": [{"w": "逆毛", "t": "倒向生长的毛"}, {"w": "逆祀", "t": "颠倒祭祀的顺序"}, {"w": "逆折", "t": "倒向回旋"}, {"w": "逆箭", "t": "倒插在袋中的箭。"}]}, {"meaning": "叛乱,谋反。", "cites": [{"t": "恐开奸宄之源,生逆乱之心。", "b": "《后汉书·班超梁传》"}, {"t": "叔侄为逆。", "b": "宋·文天祥《指南录·后序》"}, {"t": "逆阉防伺。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "逆计", "t": "谋反的计划"}, {"w": "逆变", "t": "变乱"}, {"w": "逆属", "t": "叛乱者的亲属"}, {"w": "逆孽", "t": "背叛的罪恶"}, {"w": "逆藩", "t": "叛逆的藩邦、藩臣"}, {"w": "逆谋", "t": "叛逆的阴谋"}, {"w": "逆俦", "t": "逆党。"}]}, {"meaning": "抗拒。", "cites": [{"t": "故专兵一志以逆秦。", "b": "《战国策·齐策三》"}], "words": [{"w": "逆命", "t": "抗拒命令"}, {"w": "逆遣", "t": "拒却;辞绝"}, {"w": "逆呵", "t": "逆拒并呵斥"}, {"w": "逆拒", "t": "拒绝"}, {"w": "逆斥", "t": "排斥。"}]}, {"meaning": "预测;揣度。", "cites": [{"t": "我有亲父兄,…恐不任我意,逆以煎我怀。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "逆志", "t": "猜测其志向"}, {"w": "逆断", "t": "预料;推测"}, {"w": "逆臆", "t": "预料、猜想。"}]}, {"meaning": "事前,预先。", "cites": [{"t": "周、王既入,始至阶头,帝逆遣传诏遏使就东厢。", "b": "《世说新语·方正》"}], "words": [{"w": "逆告", "t": "预告"}, {"w": "逆知", "t": "预先知道"}, {"w": "逆计", "t": "预先想到"}, {"w": "逆诈", "t": "事先即怀疑别人会欺骗自己"}, {"w": "逆备", "t": "预先防备"}, {"w": "逆数", "t": "预测未来"}, {"w": "逆睹", "t": "预见,预知。"}]}, {"meaning": "叛逆。", "cites": [{"t": "数(斥责)吕师孟叔侄为逆。", "b": "文天祥《指南录后序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1653wx','兹','1','cí zī','丷','9','','[{"pinyin": "cí", "defs": [{"meaning": "——“龟兹”(Qiūcí):古代西域的国名,唐代征服东突厥时曾在此设郡,旧址在今新疆库东县一带。"}]}, {"pinyin": "zī", "defs": [{"meaning": "(形声。据《说文》,从艸,滋省声。本义:草木茂盛) 同本义。", "cites": [{"t": "兹,草木多益也。", "b": "《说文》"}, {"t": "五藏之气,故色见青如草兹者死。", "b": "《素问·五藏生成论》"}], "words": [{"w": "兹兹", "t": "增加繁殖。"}]}, {"meaning": "年。", "cites": [{"t": "今兹美禾,来兹美麦。", "b": "《吕氏春秋》"}]}, {"meaning": "草席。", "cites": [{"t": "蓐谓之兹。", "b": "《尔雅》。注:“兹者,蓐席也。”"}, {"t": "毛叔郑奉明水,卫康叔封布兹。", "b": "《史记》"}]}, {"meaning": "现在;此时。", "cites": [{"t": "兹予大享于先生,尔祖其从与享之。", "b": "《书·盘庚上》"}]}, {"meaning": "这个,此。", "cites": [{"t": "总兹戎重。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "挥手目兹去。", "b": "唐·李白《送友人》"}, {"t": "兹游快且愧矣。", "b": "《徐霞客游记·游黄山记》"}, {"t": "而母立于兹。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "兹事体大", "t": "此事牵连甚广,关系重大。"}]}, {"meaning": "这里。", "cites": [{"t": "文王既没,文在不兹乎?", "b": "《论语》"}]}, {"meaning": "益,愈加。", "cites": [{"t": "由由乎兹免。", "b": "《管子·小问》"}, {"t": "行地兹远。", "b": "《管子·小匡》"}, {"t": "赋敛兹重。", "b": "《汉书·五行志七》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1654wx','总','1','zǒng','心','9','','[{"pinyin": "zǒng", "defs": [{"meaning": "(形声。从糸(mì),悤(cōng)声。糸是细丝,细丝常聚合成一束,故从糸。本义:聚束;系扎)。"}, {"meaning": "同本义。", "cites": [{"t": "总,聚束也。", "b": "《说文》"}, {"t": "总,结也。", "b": "《广雅》"}, {"t": "素丝五总。", "b": "《诗·召南·羔羊》"}, {"t": "总角之宴。", "b": "《诗·卫风·氓》"}, {"t": "令徒隶衣七总布。", "b": "《史记·孝景帝》"}, {"t": "总布二匹。", "b": "《汉书·王莽传》"}, {"t": "鸡初鸣,咸盥漱,栉、縦,笄、总。", "b": "《礼记·内则》"}, {"t": "以麻总发。", "b": "《新唐书》"}], "words": [{"w": "总发", "t": "指童年,幼年。同总角"}, {"w": "总角之好", "t": "指幼年相契的朋友。也称“总角之交”"}, {"w": "总丱", "t": "古时儿童束发为两角。"}]}, {"meaning": "聚合;汇集。", "cites": [{"t": "无总于货宝,生生自庸。", "b": "《书·盘庚》"}, {"t": "功名之总也。", "b": "《史记·礼书》"}, {"t": "总揽英雄。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "总萃", "t": "会合聚集"}, {"w": "总集", "t": "聚集,集合;汇集许多人的作品而成的诗文集"}, {"w": "总猥", "t": "聚合的样子"}, {"w": "总聚", "t": "综合聚集"}, {"w": "总总", "t": "聚合的样子"}, {"w": "归总;汇总;拢总", "t": ""}]}, {"meaning": "结,系。", "cites": [{"t": "饮余马于咸池兮,总余辔乎扶桑。", "b": "《楚辞·离骚》"}, {"t": "解扶桑之总辔兮,纵今之遂奔驰。", "b": "《汉书》"}], "words": [{"w": "总辔", "t": "系马。指停驻。"}]}, {"meaning": "统领,统管。", "cites": [{"t": "总要万物于风雨。", "b": "《荀子·哀公》"}, {"t": "公受朝寄,总兵西下。", "b": "《隋书·元谐传》"}, {"t": "总兹戎重。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "总朝政;总己", "t": "统摄自己的职务"}, {"w": "总戍", "t": "主管军务;统管军事的长官"}, {"w": "总帅", "t": "统率;统帅。"}]}, {"meaning": "总括;概括。", "cites": [{"t": "总天下之要,治海内之众。", "b": "《荀子·不苟》"}, {"t": "总此十思。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "总凡", "t": "概括"}, {"w": "总批", "t": "总括性批语"}, {"w": "总微", "t": "概括精微的道理"}, {"w": "总论", "t": "全面而概括的论述。"}]}, {"meaning": "禾稿;连穗带杆的禾把子。", "cites": [{"t": "五百里甸服,百里赋纳总。", "b": "《书·禹贡》。孔传:“禾稿曰总,入之供饲国马。”"}]}, {"meaning": "束穗;流苏 (古代的车马装饰品)。", "cites": [{"t": "王后之五路,重翟,锡厘朱总。", "b": "《周礼》。贾公彦疏:“凡言总者,谓以总为车马之饰,若归人之总,亦既系其本,又垂为饰,故皆谓之总也。”"}], "words": [{"w": "朱总", "t": "朱红色的车饰。"}]}, {"meaning": "整数。", "cites": [{"t": "银子成总了,我差人回家取去!", "b": "《老残游记》"}]}, {"meaning": "麻杆扎成的火把。", "cites": [{"t": "错总之法,横于坐所。", "b": "《管子》"}]}, {"meaning": "全部,全面。", "cites": [{"t": "风流总被雨打风吹去。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "总崩溃;总批发;总目;总代理;总动员;总产量;总成本", "t": ""}]}, {"meaning": "用法同“纵”。纵然;即使。", "cites": [{"t": "莫言塞北无春到,总有春来何处知。", "b": "《度破讷沙》"}, {"t": "年兄总要出家修行,也该与我们作别一声,如今觉得忒歉然了!", "b": "《醒世恒言》"}], "words": [{"w": "总有", "t": "虽然有;即使有"}, {"w": "总做", "t": "纵使"}, {"w": "总然", "t": "纵然;即使"}, {"w": "总饶", "t": "任凭;尽管。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1655wx','炼','1','liàn','火','9','','[{"pinyin": "liàn", "defs": [{"meaning": "(形声。从火,柬声。本义:提炼)。"}, {"meaning": "同本义。用加热等方法使物质溶化并趋于纯净或坚韧。", "cites": [{"t": "炼,铄冶金也。", "b": "《说文》。王筠曰:“煉鍊同字。”"}, {"t": "鍊药瞩虚幌。", "b": "江淹《杂体诗·王征君》"}, {"t": "公宫令舍之堂,皆以炼铜为柱质。", "b": "《韩非子·十过》"}, {"t": "何意百炼钢,化为绕指柔。", "b": "刘琨《重赠卢谌》"}], "words": [{"w": "提炼", "t": "用理化方法从化合物或混合物中提取"}, {"w": "精炼", "t": "提炼精华,除去杂质"}, {"w": "炼石", "t": "烧炼丹石"}, {"w": "炼金", "t": "炼丹"}, {"w": "炼汞", "t": "道家烧炼金石药物,以制成丹药。"}]}, {"meaning": "修炼;锻炼;造就。", "cites": [{"t": "服此二物,炼人身体。", "b": "《抱朴子·金丹》"}], "words": [{"w": "炼丹", "t": "以气功修炼人体精、气、神,谓之内丹"}, {"w": "炼性", "t": "道教谓之修炼心性"}, {"w": "炼养", "t": "修炼养生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1656wx','炸','1','zhá zhà','火','9','','[{"pinyin": "zhá", "defs": [{"meaning": "将旧金属器物加工,使重现光泽。", "cites": [{"t": "妹妹的项圈我瞧瞧,只怕该炸一炸去了。", "b": "《红楼梦》"}]}]}, {"pinyin": "zhà", "defs": [{"meaning": "指物体突然破裂。", "cites": [{"t": "[粗磁碟子]不拿姜汁子和酱预先抹在底子上烤过,一经了火是要炸的。", "b": "《红楼梦》"}], "words": [{"w": "瓶子炸了;爆炸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1657wx','烁','1','shuò','火','9','','[{"pinyin": "shuò", "defs": [{"meaning": "(形声。从火,乐声。本义:发光的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "中夜有大流星长数丈,光烁如电。", "b": "《新唐书·天文志》"}]}, {"meaning": "摇曳;闪烁。", "cites": [{"t": "其外浅处,紫碧浮映,日光所烁也。", "b": "《徐霞客游记》"}]}, {"meaning": "销熔。", "cites": [{"t": "烁金以为刃。", "b": "《周礼·考工记·总敍》"}, {"t": "众口烁金。", "b": "《国语·周语》"}], "words": [{"w": "烁金", "t": "熔化金属;另指伤人的谗言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1658wx','炮','1','bāo páo pào','火','9','','[{"pinyin": "bāo", "defs": [{"meaning": "一种烹调方法。"}]}, {"pinyin": "páo", "defs": [{"meaning": "(形声。从火,包声。(páo)本义:古烹饪法的一种。用烂泥等裹物而烧烤)。"}, {"meaning": "同本义。", "cites": [{"t": "炮,毛炙肉也。字亦作炰。以铁匕贯肉,加于火炙之。", "b": "《说文》"}, {"t": "炮之燔之。", "b": "《诗·小雅·瓠叶》"}, {"t": "亨羊炰羔。", "b": "《汉书·杨恽传》"}, {"t": "炮取豚台若将。", "b": "《礼记·内则》。注:“以涂烧之为名也。”"}], "words": [{"w": "炮食", "t": "烧烤食物"}, {"w": "炮燖", "t": "烧炙"}, {"w": "炮燔", "t": "烧烤"}, {"w": "炮豚", "t": "烤猪"}, {"w": "炮羊", "t": "烤羊"}, {"w": "炮胾", "t": "烤熟的肉块"}, {"w": "炮煎", "t": "烧烤"}, {"w": "炮祭", "t": "古代烧柴祭天的仪式。"}]}, {"meaning": "焚烧,燃烧。", "cites": [{"t": "令尹炮之,尽灭卻卻氏之族、党。", "b": "《左传·昭公二十七年》"}], "words": [{"w": "炮暑", "t": "酷署"}, {"w": "炮土", "t": "瓦。"}]}, {"meaning": "制中药的一种方法,把生药放在热铁锅里炒,使它焦黄爆裂。", "cites": [{"t": "儿为检药笼,桂姜手炮煎。", "b": "陆游《离家示妻子诗》"}]}, {"meaning": "厨师。", "cites": [{"t": "凡为人臣者,犹炮宰和五味而进之君。", "b": "《韩非子·难二》"}]}, {"meaning": "吼叫,咆哮。", "cites": [{"t": "女炰烋于中国,敛怨以为德。", "b": "《诗·大雅·荡》注:“炰烋,《说文》引作咆哮。”"}]}]}, {"pinyin": "pào", "defs": [{"meaning": "“炮”假借为“砲”,大炮。", "cites": [{"t": "敌军果舁炮至。", "b": "清·徐珂《清稗类钞·战事类》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1659wx','炫','1','xuàn','火','9','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从火,玄声。本义:晃眼)。"}, {"meaning": "同本义。", "cites": [{"t": "炫,烂耀也。", "b": "《说文》"}, {"t": "炫光貌。", "b": "《埤仓》"}, {"t": "炫熿干道。", "b": "《战国策·秦策》"}, {"t": "大盆盛水,置剑其上,视之者精芒炫目。", "b": "《晋书》"}], "words": [{"w": "炫视", "t": "目光炫乱"}, {"w": "炫目", "t": "光彩夺目"}, {"w": "炫色", "t": "闪烁光芒"}, {"w": "炫炫", "t": "光耀明亮的样子。"}]}, {"meaning": "显示;夸耀。", "cites": [{"t": "生已沽名炫气豪,死犹虚伪惑儿曹。", "b": "《警世通言》"}], "words": [{"w": "炫的那家世", "t": "夸什么家阀世系;显什么眼"}, {"w": "炫玉求售", "t": "自诩有才,以求施展。"}]}, {"meaning": "形容艳丽。", "cites": [{"t": "袨(炫)服靓妆。", "b": "左思《蜀都赋》"}], "words": [{"w": "炫冶", "t": "艳丽"}, {"w": "炫服", "t": "华艳的衣服"}, {"w": "炫美", "t": "华丽"}, {"w": "炫饰", "t": "盛妆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1660wx','烂','1','làn','火','9','','[{"pinyin": "làn", "defs": [{"meaning": "(形声。从火,阑声。本义:煮烂)。"}, {"meaning": "同本义。", "cites": [{"t": "孏,孰也。", "b": "《说文》。字亦作爛。"}, {"t": "熟而不烂。", "b": "《吕氏春秋·本味》"}, {"t": "三日三夕不烂。", "b": "晋·干宝《搜神记》"}]}, {"meaning": "又。", "cites": [{"t": "此儿头不烂。", "b": ""}, {"t": "是必烂也。", "b": ""}, {"t": "三首俱烂。", "b": ""}], "words": [{"w": "烂饭", "t": "加水较多而煮成的又软又烂的饭"}, {"w": "烂煮", "t": "煮至熟烂"}, {"w": "烂蒸", "t": "蒸至烂熟"}, {"w": "烂椹", "t": "熟透的桑椹。"}]}, {"meaning": "火烧伤。", "cites": [{"t": "焦头烂额为上客。", "b": "《汉书·霍光传》"}]}, {"meaning": "腐烂,腐败。", "cites": [{"t": "烂灰生蝇。", "b": "《淮南子·说山》。注:“腐也。”"}, {"t": "愿凭三寸不烂之舌,往江东说此人来降。", "b": "《三国演义》"}], "words": [{"w": "一场大雨使麦子烂了;烂黄齑", "t": "烂腌菜,比喻爱情不专的人"}, {"w": "烂败", "t": "腐烂"}, {"w": "烂损", "t": "腐烂败坏"}, {"w": "烂碎", "t": "腐烂破碎"}, {"w": "烂溃", "t": "溃烂。"}]}, {"meaning": "明亮、光明;色彩绚丽。", "cites": [{"t": "明星有烂。", "b": "《诗·郑风·女曰鸡鸣》"}, {"t": "烂昭昭兮未央。", "b": "《楚辞·云中君》。注:“光貌。”"}, {"t": "登降炤烂。", "b": "班固《西都赋》。注:“明也。”"}, {"t": "功德烂然。", "b": "《汉书·王莽传》"}], "words": [{"w": "灿烂", "t": "光彩显明耀眼"}, {"w": "烂灼", "t": "灿粒闪灼"}, {"w": "烂熳", "t": "坦率自然,不做作"}, {"w": "烂目", "t": "耀眼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1661wx','剃','1','tì','刂','9','','[{"pinyin": "tì", "defs": [{"meaning": "用刀刮去毛发。", "cites": [{"t": "鬀,剃发也。大人曰髡,小儿曰鬀,尽及身毛曰鬄。", "b": "《说文》"}]}, {"meaning": "后来写作“剃”。", "cites": [{"t": "剃,同鬀。", "b": "《广韵》"}], "words": [{"w": "剃胡子;剃汗毛;剃得干净;剃光头;剃削", "t": "剃去毛发"}, {"w": "剃面;剃工;剃平头;剃刀", "t": ""}]}, {"meaning": "剃度出家 。", "words": [{"w": "剃落", "t": "剃发。落发出家"}, {"w": "剃度", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1662wx','洼','1','wā','氵','9','','[{"pinyin": "wā", "defs": [{"meaning": "(形声。从水,圭(guī)声。本义:深池)。"}, {"meaning": "同本义。", "cites": [{"t": "窪,深池也。从水，窐声。", "b": "《说文》"}, {"t": "马生渥洼水中。", "b": "《汉书·武帝纪》"}, {"t": "似洼者。", "b": "《庄子·齐物论》"}, {"t": "泽无洼水。", "b": "《淮南子·览冥》"}], "words": [{"w": "洼子", "t": "低洼存水的地方。"}]}, {"meaning": "古水名。"}, {"meaning": "“渥洼”的省称。是今甘肃省敦煌县党河的水源之一。", "cites": [{"t": "丹山彩凤,洼水神驹。", "b": "明·陆采《怀香记·司空受掾》"}]}, {"meaning": "古水,今未详。", "cites": [{"t": "洼,水名。", "b": "《广韵·佳韵》"}]}, {"meaning": "“窪”的简化字。"}, {"meaning": "清水。", "cites": [{"t": "窪,清水也。从水,窐声。", "b": "《说文》"}]}, {"meaning": "假借为“窐”。低陷,凹下。", "cites": [{"t": "窪,下也。", "b": "《广雅·释诂一》"}, {"t": "窪则盈。", "b": "《老子·二十二章》"}], "words": [{"w": "洼塌", "t": "凹隐;凹下"}, {"w": "洼坳", "t": "低下"}, {"w": "洼田", "t": "低田"}, {"w": "洼坎", "t": "凹陷"}, {"w": "洼然", "t": "凹陷的样子"}, {"w": "洼尊", "t": "形状凹入如酒尊的岩石。"}]}, {"meaning": "潴积。", "cites": [{"t": "山无峻干,泽无洼水。", "b": "《淮南子》。高诱注:“洼水,渟水。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1663wx','洁','1','jié','氵','9','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从水,絜(jié)声。本义:干净,清洁。按:“洁”和“潔”本是不同的两个字。“洁”本音念jí,是河流名,后来成为“潔”的俗字,现在是“潔”的简化字)。"}, {"meaning": "同本义。", "cites": [{"t": "鲜而不垢,洁也。", "b": "《管子·水地》"}, {"t": "姑洗所以脩洁百物。", "b": "《国语·周语》"}, {"t": "直哉维静絜。", "b": "《史记·五帝纪》"}, {"t": "为人洁白皙。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "整洁", "t": "整齐清洁"}, {"w": "清洁", "t": "没有尘土,油垢等"}, {"w": "洁癖", "t": "过分爱清洁的癖性"}, {"w": "洁疾", "t": "过分爱清洁的特殊行为"}, {"w": "洁粢", "t": "洁净的黍稷。粢:供祭祀的谷类。"}]}, {"meaning": "操行清白,品德高尚。", "cites": [{"t": "联幼清以廉洁兮。", "b": "《楚辞·招魂》"}, {"t": "以著其洁。", "b": "唐·柳宗元《柳河东集》"}, {"t": "风霜高洁。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "洁操", "t": "高尚的操守"}, {"w": "洁廉", "t": "高洁清廉"}, {"w": "洁直", "t": "品德高尚正直"}, {"w": "圣洁", "t": "神圣而纯洁。"}]}, {"meaning": "元代民間戏稱和尚为“洁郎”,省稱“洁”。", "cites": [{"t": "凈扮洁上:“老僧法本,在這普救寺内做長老。”", "b": "《西厢記》"}]}, {"meaning": "使清白。", "cites": [{"t": "欲洁其身。", "b": "《論語.微子》"}, {"t": "修身洁行。", "b": "《史記.魏公子列传》"}], "words": [{"w": "洁行", "t": "使行为高洁"}, {"w": "洁己", "t": "修養己身。"}]}, {"meaning": "分清。", "cites": [{"t": "夫際会之間,請命乞身,何哉:欲洁去就之分也。", "b": "《三国演義》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1664wx','洪','1','hóng','氵','9','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从水,共声。本义:大水)。"}, {"meaning": "同本义。", "cites": [{"t": "洪,洚水也。", "b": "《说文》"}, {"t": "汤汤洪水方割。", "b": "《书·尧典》"}, {"t": "洪水芒芒。", "b": "《诗·商颂·长发》"}, {"t": "洪水横流。", "b": "《孟子·滕文公上》"}], "words": [{"w": "山洪;防洪;蓄洪;分洪;洪河", "t": "大河"}, {"w": "洪峰", "t": ""}]}, {"meaning": "河道陡窄流急之处。", "cites": [{"t": "定国既去逾月,复与参寥师放舟洪下,追怀曩游,已为陈迹,喟然而叹。", "b": "宋·苏轼《百步洪》"}, {"t": "徐州百步洪,吕梁上下二洪。", "b": "明·陆容《菽园杂记》"}]}, {"meaning": "河流分道之处。", "cites": [{"t": "东江木落水分洪,伐尽黄芦洲渚空。", "b": "宋·王安石《东江》诗"}]}, {"meaning": "大。与“小”相对。", "cites": [{"t": "洪波涌起。", "b": "《乐府诗集·曹操·步出夏门行》"}, {"t": "声如洪钟。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "洪烈", "t": "巨大的功绩"}, {"w": "洪仁", "t": "胸怀宽广,仁义待人"}, {"w": "洪范", "t": "大名;伟业"}, {"w": "洪慈", "t": "洪恩。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1665wx','洒','1','sǎ','氵','9','','[{"pinyin": "sǎ", "defs": [{"meaning": "(形声。从水,西声。本义:把水散布在地上)。"}, {"meaning": "同本义。", "cites": [{"t": "洒,滌水也。古文以为灑掃言。", "b": "《说文》"}, {"t": "洒,濯也。", "b": "《字林》"}, {"t": "一洒之者也。", "b": "《孟子》"}, {"t": "洒扫室堂及庭。", "b": "《礼记·内则》"}], "words": [{"w": "黎明即起,洒扫庭除;洒削", "t": "洒水以磨刀"}, {"w": "洒泼", "t": "胡乱挥霍"}, {"w": "扫地先洒些水;洒酒", "t": "把酒浇洒在地上"}, {"w": "洒削", "t": "洒水磨刀。"}]}, {"meaning": "东西散落。", "cites": [{"t": "以灰洒毒之。", "b": "《周礼·赤犮氏》"}, {"t": "掌五寝之掃除粪洒之事。", "b": "《周礼·隶仆》"}, {"t": "弗洒弗掃。", "b": "《诗·唐风·山有枢》"}, {"t": "父生不得供备洒埽之臣。", "b": "《国语·晋语》"}, {"t": "茅飞渡江洒江郊,高者挂罥长林梢。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "洒消毒水;洒敌敌畏;别把汤洒了;洒派", "t": "分派"}, {"w": "洒口", "t": "张口辱骂"}, {"w": "洒花", "t": "撒花"}, {"w": "洒签;洒调", "t": "甩开。"}]}, {"meaning": "开阔 。如洒豁。"}, {"meaning": "咱  ——宋、元时关西一带男子的自称“洒家”的略称。", "cites": [{"t": "洒是厮杀汉。", "b": "《永乐大典》引《张协状元》"}]}, {"meaning": "非常;很。", "cites": [{"t": "咱家待你洒好儿的。", "b": "《三侠五义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1666wx','柒','1','qī','木','9','','[{"pinyin": "qī", "defs": [{"meaning": "“七”的大写。", "cites": [{"t": "壹、 贰、 叁、 肆、 伍、 陆、 柒、 捌、 玖、 拾, 字书皆有之。", "b": "宋·陆游《老学庵笔记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1667wx','浇','1','jiāo','氵','9','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从水,尧声。本义:沃灌,灌溉)。"}, {"meaning": "同本义。", "cites": [{"t": "浇,沃也。", "b": "《说文》"}, {"t": "有酒唯浇赵州土。", "b": "李贺《浩歌》"}, {"t": "浇花亦自有时。", "b": "欧阳修《洛阳风俗记》"}], "words": [{"w": "浇花", "t": "用水灌花"}, {"w": "浇溉", "t": "灌溉"}, {"w": "浇沃", "t": "浇灌。"}]}, {"meaning": "浮薄。浅薄。", "cites": [{"t": "浇醇散朴。", "b": "《庄子·缮性》"}, {"t": "浇天下之淳。", "b": "《淮南子·齐俗》。注:“薄也。”"}, {"t": "自氓俗浇弛。", "b": "《文选·策秀才文》"}], "words": [{"w": "浇风", "t": "浇薄的风气"}, {"w": "浇漓", "t": "风气刻薄,不朴实淳厚"}, {"w": "浇兢", "t": "追名逐利的浮薄风气"}, {"w": "浇季", "t": "道德风俗浮薄的末世。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1668wx','浊','1','zhuó','氵','9','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从水,蜀声。本义:浊水) 同本义。", "cites": [{"t": "浊水出齐郡厉伪山,东北入钜定。", "b": "《说文》。今曰北阳水。"}]}, {"meaning": "源出山东省益都县西南,北流注入小清河。"}, {"meaning": "液体浑浊。与“清”相对。", "cites": [{"t": "载清载浊。", "b": "《诗·小雅·四月》"}, {"t": "浑兮其若浊", "b": "《老子》"}, {"t": "蝉蜕于浊秽。", "b": "《史记·屈原贾生列传》"}, {"t": "浊浪排空。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "浊河", "t": "混浊的河流。特指黄河"}, {"w": "浊酒", "t": "用糯米、黄米等酿制的酒,较混浊。"}]}, {"meaning": "脏,不干净。", "cites": [{"t": "雨门延风凉,洗我昏浊肌。", "b": "姚合《过张邯郸庄》"}], "words": [{"w": "浊醪", "t": "浊酒"}, {"w": "浊污", "t": "污秽"}, {"w": "浊秽", "t": "污浊。亦比喻丑恶鄙陋之事物"}, {"w": "浊溷", "t": "污浊。"}]}, {"meaning": "庸俗。", "cites": [{"t": "你不是凡胎浊骨, 迷本性人间受苦。", "b": "马致远《黄粱梦》"}], "words": [{"w": "浊物", "t": "俗物"}, {"w": "浊气", "t": "俗气"}, {"w": "浊碎", "t": "指庸常琐碎之事"}, {"w": "浊质", "t": "凡庸的姿质。"}]}, {"meaning": "品行坏,卑劣。", "cites": [{"t": "举世皆浊我独清,众人皆醉我独醒,是以见放。", "b": "《楚辞》"}], "words": [{"w": "浊化", "t": "变得贪鄙、卑劣"}, {"w": "浊俗", "t": "卑污庸俗"}, {"w": "浊操", "t": "卑污的操行"}, {"w": "浊气", "t": "不良风气。"}]}, {"meaning": "混乱。", "cites": [{"t": "科条既备,民多伪态;书策稠浊百姓不足。", "b": "《战国策》"}], "words": [{"w": "浊代", "t": "混乱的时代"}, {"w": "浊乱", "t": "搅扰使之混乱;混乱"}, {"w": "浊躁", "t": "紊乱浮躁。"}]}, {"meaning": "昏暗不明。", "cites": [{"t": "浊明外景,清明内景", "b": "《荀子·解蔽》"}, {"t": "阴虹浊太阳,前星遂沦匿。", "b": "李白《商山四皓》"}], "words": [{"w": "浊才料", "t": "糊涂;不省事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1669wx','洞','1','dòng','氵','9','','[{"pinyin": "dòng", "defs": [{"meaning": "(形声。从水,同声。本义:水流急)。"}, {"meaning": "同本义。", "cites": [{"t": "洞,疾流也。", "b": "《说文》"}]}, {"meaning": "窟窿;孔穴。", "cites": [{"t": "心气内洞。", "b": "《素问·四气调神大论》。注:“洞,谓中空也。”"}, {"t": "港洞坑谷。", "b": "马融《长笛赋》"}, {"t": "距洞百余步。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "洞隙", "t": "孔缝"}, {"w": "洞肛", "t": "肛门"}, {"w": "袖子磨破一个洞", "t": ""}]}, {"meaning": "口令中用以代替数目中的“零”。"}, {"meaning": "贯穿;通达。", "cites": [{"t": "转视积薪后,一狼洞其中。", "b": "《聊斋志异·狼三则》"}, {"t": "骈其指,力斫之,可断牛项;横搠之,可洞牛腹。", "b": "《聊斋志异·铁布衫法》"}], "words": [{"w": "洞出", "t": "穿洞而出"}, {"w": "洞壁", "t": "在墙上打洞"}, {"w": "洞连", "t": "连接相通"}, {"w": "洞户", "t": "室与室相通的门户"}, {"w": "洞越", "t": "瑟底两孔相通。"}]}, {"meaning": "通晓;知悉。", "cites": [{"t": "为人鸢肩豺目,洞精矘眄口吟舌言,裁能书计。", "b": "《后汉书·梁冀传》"}], "words": [{"w": "洞习", "t": "通晓熟悉"}, {"w": "洞达", "t": "通晓明白"}, {"w": "洞烛", "t": "明察"}, {"w": "洞冥", "t": "洞察昏暗之处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1670wx','测','1','cè','氵','9','','[{"pinyin": "cè", "defs": [{"meaning": "(形声。从水,则声。本义:度量水的深浅)。"}, {"meaning": "度量;测量。", "cites": [{"t": "测,深所至也。", "b": "《说文》"}, {"t": "测土深。", "b": "《周礼·大司徒》。注:“犹度也。”"}, {"t": "穷高极远,而深深厚。", "b": "《礼记·乐记》。疏:“知也。”"}, {"t": "毋测未至。", "b": "《礼记·少仪》。注:“意度也。”"}, {"t": "抑欲测吾心也。", "b": "《国语·晋语》。注:“度也。”"}, {"t": "大不可量,深不可测。", "b": "《韩非子·主道》"}], "words": [{"w": "测海", "t": "测量海水的深浅。比喻浅薄无知"}, {"w": "测景", "t": "度量日影"}, {"w": "测汽车的速度;测房子的高度;测地", "t": "测定土地的广狭、高低"}, {"w": "测步", "t": "测量。"}]}, {"meaning": "观测,观察。", "cites": [{"t": "夜则测阴,昼则测阳。", "b": "《太玄经》"}], "words": [{"w": "测天", "t": "观测天文。"}]}, {"meaning": "推测、预料。", "cites": [{"t": "夫大国,难测也,惧有伏焉。", "b": "《左传·庄公十年》"}], "words": [{"w": "变化莫测;不测;叵测", "t": "不可推测"}, {"w": "猜测;揣测", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1671wx','洗','1','xǐ xiǎn','氵','9','','[{"pinyin": "xǐ", "defs": [{"meaning": "(形声。从水,先声。据甲骨文,上为足形,下为水形。本义:用水洗脚)。"}, {"meaning": "同本义。", "cites": [{"t": "洗,洒足也。", "b": "《说文》"}, {"t": "洗去足垢。", "b": "《论衡·讥日》"}, {"t": "王方踞床洗。", "b": "《汉书·黥布传》。注:“濯足也。”"}, {"t": "沛公方踞床,使两女子洗足。", "b": "《史记·高祖本纪》"}]}, {"meaning": "假借为洒。用水涤除污垢。", "cites": [{"t": "水在洗东。", "b": "《仪礼·乡饮酒礼》。注:“承盥洗者,弃水器也。”"}, {"t": "上闻后宫欢笑,问其故,左右以贵妃三日洗禄儿对。", "b": "《资治通鉴·唐玄宗天宝十载》"}, {"t": "晴雪所洗。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "洗头", "t": "宋时礼俗。新婚数日后,女家迎女归,并备礼品送女回婿家"}, {"w": "洗耳不听", "t": "喻厌闻世事"}, {"w": "洗钱", "t": "洗儿时赐赠的钱"}, {"w": "洗泥", "t": "即洗尘。置办酒食招待远行而来的客人。"}]}, {"meaning": "免去;除去。", "cites": [{"t": "圣人以此洗心。", "b": "《易·系辞》"}, {"t": "思君厚德委如山,洁诚洗志期暮年。", "b": "南朝宋·鲍照《代白纻舞歌辞》"}], "words": [{"w": "洗脱", "t": "把嫌疑、屈辱洗雪掉"}, {"w": "清洗", "t": "清除"}, {"w": "洗革", "t": "除去。"}]}, {"meaning": "革除。", "cites": [{"t": "小人从前原也作些小道儿上的买卖,后来洗手不干,就在河工上充了一个夫头。", "b": "《儿女英雄传》"}], "words": [{"w": "洗伐", "t": "整顿,革新"}, {"w": "洗手奉职", "t": "谓廉治无私,忠于职守"}, {"w": "洗心", "t": "比喻改过自新。"}]}, {"meaning": "抢光;杀尽。", "cites": [{"t": "巢复入京师,怒民迎王师,纵击杀八万人,血流于路可涉也,谓之洗城。", "b": "《新唐书·黄巢传》"}], "words": [{"w": "洗剥", "t": "搜身脱衣"}, {"w": "洗荡", "t": "杀尽,清洗"}, {"w": "洗劫;洗民", "t": ""}]}, {"meaning": "整治;雕琢。", "cites": [{"t": "一件是祖母绿洗的个东方朔,肩上担着一枝蟠桃。——《梼杌闲评——明珠缘》", "b": ""}], "words": [{"w": "洗竹", "t": "削去丛竹的繁枝"}, {"w": "洗玩", "t": "摆弄,玩赏"}, {"w": "洗削", "t": "磨刀。"}]}, {"meaning": "古代盥洗用的器皿 。形似浅盆。一般用青铜铸造,也有陶质的。", "cites": [{"t": "夙兴,设洗直于东荣。", "b": "《仪礼·士冠礼》"}]}]}, {"pinyin": "xiǎn", "defs": [{"meaning": "洗脚。", "cites": [{"t": "洗,洒足也。", "b": "《说文》"}]}, {"meaning": "姓。同“冼”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1672wx','活','1','huó','氵','9','','[{"pinyin": "huó", "defs": [{"meaning": "(形声。从水,昏(kuò)声。本义:流水声。用本义时读(guō))。"}, {"meaning": "生存。与“死”相对。", "cites": [{"t": "不我活兮。", "b": "《诗·邶风·击鼓》"}, {"t": "不可活。", "b": "《书·太甲》"}, {"t": "民非水火不生活。", "b": "《孟子》"}, {"t": "巫何活焉?", "b": "《楚辞·天问》"}], "words": [{"w": "鱼在水里才能活;这个孩子只活三个月;活到高龄而且精力充沛;活头儿", "t": "生存的趣味。"}]}, {"meaning": "救活。", "cites": [{"t": "臣活之。", "b": "《史记·项羽本纪》"}], "words": [{"w": "活人", "t": "使人活,救活他人"}, {"w": "活国", "t": "救国。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1673wx','派','1','pài pā','氵','9','','[{"pinyin": "pài", "defs": [{"meaning": "(形声。本义:水的支流)。"}, {"meaning": "同本义。", "cites": [{"t": "派,别水也。", "b": "《说文》"}, {"t": "百川派别。", "b": "左思《吴都赋》"}, {"t": "九派乎浔阳。", "b": "郭璞《江赋》"}, {"t": "茫茫九派流中国,沉沉一线穿南北。", "b": "毛泽东《菩萨蛮·黄鹤楼》"}], "words": [{"w": "九派", "t": "一般指长江的很多支流"}, {"w": "派流", "t": "水的支流。"}]}]}, {"pinyin": "pā", "defs": [{"meaning": "英文pass的音译", "words": [{"w": "派司", "t": "桥牌叫牌中的术语,表示不叫"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1674wx','洽','1','qià','氵','9','','[{"pinyin": "qià", "defs": [{"meaning": "(形声。从水,合声。本义:沾湿,浸润)。"}, {"meaning": "同本义。", "cites": [{"t": "洽,沾也。", "b": "《说文》"}, {"t": "仁洽道丰。", "b": "张衡《东京赋》"}, {"t": "是泽南洽而威北畅也。", "b": "《汉书·终军传》"}, {"t": "内洽五藏。", "b": "《淮南子·要略》"}], "words": [{"w": "洽濡", "t": "沾湿,滋润"}, {"w": "洽润", "t": "润泽"}, {"w": "洽衿", "t": "沾湿衣襟。"}]}, {"meaning": "合,符合。", "cites": [{"t": "以洽百礼。", "b": "《诗·小雅·载芟》"}, {"t": "则无以祖洽于众也。", "b": "《礼记·仲尼燕居》"}], "words": [{"w": "洽愿", "t": "称心如愿"}, {"w": "洽意", "t": "合意;中意"}, {"w": "洽悉", "t": "与事切合而详尽。"}]}, {"meaning": "假借为“给”。供应。", "cites": [{"t": "不洽而爟之,使客无得以助攻备。", "b": "《商君书·兵守》"}]}, {"meaning": "周遍;广博。", "cites": [{"t": "元元本本,殚见洽闻。", "b": "班固《西都赋》。注:“洽,遍也。”"}], "words": [{"w": "洽化", "t": "普遍受到薰陶教化"}, {"w": "恰闻", "t": "见识广博"}, {"w": "洽人", "t": "学识渊博的人"}, {"w": "洽客", "t": "广见博闻者"}, {"w": "洽浃", "t": "广博;周遍。"}]}, {"meaning": "和谐;融洽。", "cites": [{"t": "洽比其邻。", "b": "《诗·小雅·正月》"}, {"t": "民之洽也。", "b": "《诗·大雅·板》"}], "words": [{"w": "洽平", "t": "太平盛世,四方融洽"}, {"w": "洽同", "t": "协和统一"}, {"w": "洽和", "t": "和睦"}, {"w": " 洽悦", "t": "和睦欢乐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1675wx','染','1','rǎn','木','9','','[{"pinyin": "rǎn", "defs": [{"meaning": "(形声。从水,杂声。一说从木、从水、从九。会意。古染料多来源于植物,故从木;染料须加工成液体,故从水;染须反复进行,故从九。本义:使布帛等物着色)。"}, {"meaning": "同本义。", "cites": [{"t": "染,以缯为色也。", "b": "《说文》"}, {"t": "掌染草。", "b": "《周礼·序官》。注:“兰ň象斗之属,掌染草,掌以春秋敛染草之物。”"}], "words": [{"w": "染博士", "t": "染色的工匠"}, {"w": "染服", "t": "僧侣所穿的缁衣。因缁衣由黑色染成,故称"}, {"w": "染户", "t": "操染色业的人家"}, {"w": "染茜", "t": "染成大红色"}, {"w": "染采", "t": "将织物染成彩色"}, {"w": "染事", "t": "染色的事务"}, {"w": "染网", "t": "用牲畜血等染网"}, {"w": "一股暖流染红了她的两颊;染指甲;染头发", "t": ""}]}, {"meaning": "传染,感染。", "cites": [{"t": "此所以染者众也。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "染疾", "t": "患病"}, {"w": "染渍", "t": "感染,传染"}, {"w": "染惹", "t": "感染,沾上"}, {"w": "染恙", "t": "染病,传染"}, {"w": "染薰", "t": "沾染香气"}, {"w": "染上了流感", "t": ""}]}, {"meaning": "熏染;影响。", "cites": [{"t": "舜染于许由、伯阳。", "b": "《吕氏春秋·当染》"}, {"t": "渐染砥砺,几乎道真。", "b": "柳宗元《与吕道州温论非国语书》"}], "words": [{"w": "染尚", "t": "濡染崇尚"}, {"w": "染化", "t": "薰陶教化"}, {"w": "染神乱志", "t": "思想受到迷惑扰乱"}, {"w": "染风习俗", "t": "受风俗影响而有所习染"}, {"w": "染丝之变", "t": "比喻受环境影响而变得不同"}, {"w": "染惑", "t": "外物的影响和迷惑"}, {"w": "染上不良习惯;染习", "t": "习染。"}]}, {"meaning": "污染,沾染。", "cites": [{"t": "予独爱莲之出淤泥而不染。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "染染手儿", "t": "沾点光"}, {"w": "染戕", "t": "血染戈矛"}, {"w": "染洁", "t": "操行受到污染"}, {"w": "染痘", "t": ""}]}, {"meaning": "豆豉酱。", "cites": [{"t": "于是具染而已。", "b": "《吕氏春秋》。高诱注:“染,豉酱也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1676wx','洛','1','luò','氵','9','','[{"pinyin": "luò", "defs": [{"meaning": "(形声。从水,各声。本义:水名。指洛水)。"}, {"meaning": "同本义。", "cites": [{"t": "洛,洛水,出左冯翊归德北夷界中,东南入渭。", "b": "《说文》"}]}, {"meaning": "北洛河。发源于陕西省定边县,东南流经志丹、洛川、蒲城等县。"}, {"meaning": "洛阳的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1677wx','浏','1','liú','氵','9','','[{"pinyin": "liú", "defs": [{"meaning": "水深而清澈。", "cites": [{"t": "溱与洧,浏其清矣。", "b": "《诗·郑风·溱有》"}], "words": [{"w": "浏如", "t": "清澈貌"}, {"w": "浏滥", "t": "清净而泛滥。"}]}, {"meaning": "风疾速的样子。", "cites": [{"t": "白露纷以涂涂兮,秋风浏以萧萧。", "b": "《楚辞》"}], "words": [{"w": "浏浏", "t": "风疾的样子"}, {"w": "浏飙,浏飚", "t": "疾风,暴风。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1678wx','济','1','jǐ jì','氵','9','','[{"pinyin": "jǐ", "defs": [{"meaning": "(形声。从水,齐声。本义:水名,即济水。古四渎之一)。"}, {"meaning": "同本义。", "cites": [{"t": "济,济水也。出常山房子赞皇山东入汦", "b": "《说文》"}, {"t": "济水源出赞皇山。", "b": "《穆天子传》"}, {"t": "阴谷皆入济。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "发源于今河南省济源县西王屋山,原在山东境内与黄河并行入渤海。后因黄河改道,下游被黄河淹没。现在黄河下游的河道就是原来济水的河道。"}, {"meaning": "州名。"}, {"meaning": "北魏泰常八年(公元423年)置,治所在今山东省聊城东南。"}, {"meaning": "五代周置,在今山东省巨野县。"}, {"meaning": "金置,在今吉林省农安县。"}, {"meaning": "众多。", "cites": [{"t": "济济多士。", "b": "《左传·成公二年》"}], "words": [{"w": "人才济济;济济", "t": "众多"}, {"w": "济济一堂", "t": "形容许多人聚集在一起"}, {"w": "济济彬彬", "t": "形容人才众多且文雅有礼。"}]}, {"meaning": "整齐美好的样子。", "cites": [{"t": "四骊济济。", "b": "《诗·齐风·载驱》"}], "words": [{"w": "济然;济楚", "t": "整齐清洁"}, {"w": "济济", "t": "整齐美好的样子。"}]}]}, {"pinyin": "jì", "defs": [{"meaning": "渡过水流。", "cites": [{"t": "济乎江湖。", "b": "《楚辞·屈原·涉江》"}, {"t": "济河,围令狐。", "b": "《左传·僖公二十四年》"}, {"t": "直挂云帆济沧海。", "b": "唐·李白《行路难》"}], "words": [{"w": "同舟共济;济胜之具", "t": "指能登山涉水的健康身体"}, {"w": "济水", "t": "渡水"}, {"w": "济涉", "t": "渡水"}, {"w": "济运", "t": "渡水运输。"}]}, {"meaning": "帮助;救助。", "cites": [{"t": "以之事国,则同心而共济。", "b": "欧阳修《朋党论》"}, {"t": "惟以周穷济乏为事。", "b": "《晋书·何攀传》"}, {"t": "济师来攻。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "济人利物;济拔", "t": "从险恶的境地中救出"}, {"w": "济惠", "t": "济会,济惠。周济,照顾"}, {"w": "济物", "t": "帮助他人"}, {"w": "济时", "t": "匡救时世。"}]}, {"meaning": "拯救;救济。", "cites": [{"t": "杀黑龙以济冀州。", "b": "《淮南子·览冥》"}, {"t": "此近难济,恒事攻治,可延岁月。", "b": "《三国志·方伎传》"}], "words": [{"w": "济护", "t": "救护"}, {"w": "济恤", "t": "救济"}, {"w": "济救", "t": "救济"}, {"w": "济众", "t": "救济众人"}, {"w": "济难", "t": "拯救时难"}, {"w": "济施", "t": "救济施舍。"}]}, {"meaning": "成就。", "cites": [{"t": "必以忍,其乃有济。", "b": "《书·君陈》"}, {"t": "故虽有困败,而终济大业。", "b": "《后汉书·荀彧传》"}, {"t": "以济大事。", "b": "《资治通鉴》"}, {"t": "共济世业。", "b": ""}, {"t": "事之不济。", "b": ""}], "words": [{"w": "济胜", "t": "取胜"}, {"w": "济勋", "t": "济功。成就功业"}, {"w": "济办", "t": "成功地把事办妥"}, {"w": "济克", "t": "成功。"}]}, {"meaning": "停;止。", "cites": [{"t": "三月春风不济。", "b": "《淮南子·时则》"}]}, {"meaning": "增加。", "cites": [{"t": "盍请济师于王。(盍:为什么不。)", "b": "《左传·桓公十一年》"}]}, {"meaning": "弥补。", "cites": [{"t": "又因中国文字太难,只得用图画来济文字之穷的产物。", "b": "鲁迅《且介亭杂文》"}]}, {"meaning": "及,比得上。", "cites": [{"t": "果然我们就不济凤丫头了?", "b": "《红楼梦》"}]}, {"meaning": "成;可以。", "cites": [{"t": "所言之事济否?", "b": "《警世通言》"}]}, {"meaning": "渡口,过河的地方。", "cites": [{"t": "川既漾(水流长)而济深。", "b": "王粲《登楼赋》"}]}, {"meaning": "能干,中用。", "cites": [{"t": "你忒不济,不济!又要马骑,又不放我去,似这般看着行李,坐到老罢!", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1679wx','洋','1','yáng','氵','9','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从水,羊声。本义:古水名)。"}, {"meaning": "同本义。"}, {"meaning": "洋水。", "cites": [{"t": "昆仓之丘…洋水出焉,而西南流注于丑涂之水。", "b": "《山海经》"}]}, {"meaning": "又名西乡河。在陕西省南部。源出西乡县星子山,北流合木马河会于西乡县东,东北流注于汉水。", "cites": [{"t": "汉水又东,右会洋水。", "b": "《水经注》"}]}, {"meaning": "旧指海之中心。亦泛指海域 。今指地球表面上被水覆盖的广大的地区,约占地球面积的十分之七,分成四个部分,即太平洋、大西洋、印度洋、北冰洋。"}, {"meaning": "盛多、广大。", "cites": [{"t": "洋,多也。", "b": "《尔雅》。注:“洋,溢也。”"}, {"t": "河水洋洋。", "b": "《诗·卫风·硕人》。传:“盛大也。”"}, {"t": "泌之洋洋。", "b": "《诗·陈风·衡门》"}], "words": [{"w": "洋泌", "t": "涌流不竭的泉水。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1680wx','洲','1','zhōu','氵','9','','[{"pinyin": "zhōu", "defs": [{"meaning": "(形声。从水,州声。“洲”本作“州”,后人加水以别州县之字。本义:水中的陆地)。"}, {"meaning": "同本义。", "cites": [{"t": "关关雎鸠,在河之洲。", "b": "《诗·周南·关雎》"}, {"t": "又有薮曰云连徒洲。", "b": "《国语·楚语》"}, {"t": "淮有三洲。", "b": "《诗·小雅·鼓钟》。传:“淮上地。”"}, {"t": "避渚洲。", "b": "宋·文天祥《后序》"}], "words": [{"w": "洲沚", "t": "洲渚,洲淤。水中小块陆地"}, {"w": "洲岛", "t": "水中陆地"}, {"w": "洲场", "t": "指有所出产的水中陆地"}, {"w": "洲屿", "t": "江中沙洲"}, {"w": "洲浦", "t": "洲溆。洲边。"}]}, {"meaning": "大陆,地球上陆地的大的划区,特指其大小和结构上与岛屿和半岛不同的大片陆地及以山脉为界的大盆地。", "cites": [{"t": "天下有五大洲。", "b": "《明史·外国传》"}], "words": [{"w": "北美洲,南美洲,欧洲,亚洲,非洲,大洋洲,南极洲;七大洲", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1681wx','浑','1','hún hùn','氵','9','','[{"pinyin": "hún", "defs": [{"meaning": "(形声。从水,军声。本义:大水涌流声)。"}, {"meaning": "同本义。", "cites": [{"t": "浑,水喷涌之声也。", "b": "《玉篇》"}, {"t": "浑,混流声也。", "b": "《说文》"}, {"t": "溟海浑濩涌其后。", "b": "《文选·张协·七命》"}, {"t": "浑浑若川。", "b": "《法言·问神》。注:“洪流也。”"}, {"t": "财货浑浑如泉源。", "b": "《荀子·富国》"}]}, {"meaning": "河名。"}, {"meaning": "桑干河上游支流,亦名浑源川,发源于山西省北端西麓。"}, {"meaning": "卢沟河在元明后的别称,因河水浑浊得名,即今永定河。"}, {"meaning": "小辽河,辽河最大的支流。"}, {"meaning": "浑江,又名佟家江,发源于吉林省龙岗山脉。"}, {"meaning": "中国古代少数民族吐谷浑的省称。"}, {"meaning": "浑天说的简称。", "cites": [{"t": "先是儒者论天,互执浑、盖二义,论盖不合于浑,论浑不合于盖。灵恩立义,以浑盖为一焉。", "b": "《梁书》"}]}, {"meaning": "混浊。", "cites": [{"t": "浑,浊也。", "b": "《切韵》"}, {"t": "浑兮其若浊。", "b": "《老子》"}, {"t": "浑沦者,言万物相浑沦未相离也。", "b": "《列子·天瑞》"}, {"t": "贤不肖浑殽。", "b": "《汉书·董仲舒传》"}], "words": [{"w": "浑水", "t": "浑浊不清的水"}, {"w": "浑黄", "t": "浑浊而发黄"}, {"w": "浑浑", "t": "浑浊的样子。"}]}, {"meaning": "简直。", "cites": [{"t": "白头搔更短,浑欲不胜簪。", "b": "杜甫《春望》"}]}, {"meaning": "仍;还。", "cites": [{"t": "巴童浑不寐,半夜有行舟。", "b": "杜甫《十六夜玩月》"}]}, {"meaning": "混,苟且度过。", "cites": [{"t": "只有门下是七八个月的养在府里白浑些酒肉吃吃,一个大钱也不见面。", "b": "《儒林外史》"}]}, {"meaning": "姓。"}]}, {"pinyin": "hùn", "defs": [{"meaning": "混同。同“混”。", "cites": [{"t": "春半花才发,多应不奈寒,北人初未识,浑作杏花看。", "b": "王安石《红梅》"}]}, {"meaning": "胡乱地,随意地。同“混”。", "cites": [{"t": "殷开山疑有伏兵,不去追赶,浑杀人马,收军回营。", "b": "诸圣邻《大唐秦王词话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1682wx','浓','1','nóng','氵','9','','[{"pinyin": "nóng", "defs": [{"meaning": "(形声。从水,农声。本义:露多)。"}, {"meaning": "同本义。", "cites": [{"t": "浓,露多也。", "b": "《说文》"}, {"t": "零露浓浓。", "b": "《诗·小雅·蓼萧》"}], "words": [{"w": "浓浓", "t": "露多的样子。"}]}, {"meaning": "稠密;厚;多。", "cites": [{"t": "浓雾半作。", "b": "《徐霞客游记·游黄山记》"}, {"t": "那和尚生得浓眉大眼。", "b": "《儿女英雄传》"}], "words": [{"w": "浓抹", "t": "厚施脂粉"}, {"w": "浓福", "t": "厚福"}, {"w": "浓烟;浓雾;浓繁", "t": "郁郁葱葱"}, {"w": "浓圈密点", "t": "在文字旁加上许多圆圈或点。常以表示值得注意或精采之处。"}]}, {"meaning": "特指液体或气体中所含某种成分多。与“淡”、“薄”相对。", "cites": [{"t": "宵寒药气浓。", "b": "唐·李贺《昌谷读书示巴童》"}], "words": [{"w": "浓咖啡;浓洌", "t": "浓郁清洌"}, {"w": "浓腴", "t": "指味厚和肥美的食物"}, {"w": "浓醇", "t": "醇厚浓烈"}, {"w": "浓醪", "t": "浓烈的浊酒"}, {"w": "浓酾", "t": "指兴味浓厚"}, {"w": "浓酽", "t": "汁液稠,味道厚。"}]}, {"meaning": "艳丽。", "cites": [{"t": "态浓意远淑且真,肌理细腻骨肉匀。", "b": "唐·杜甫《丽人行》"}], "words": [{"w": "浓姿", "t": "艳丽的姿态"}, {"w": "浓绮", "t": "浓艳绮丽"}, {"w": "浓缛", "t": "浓艳繁丽"}, {"w": "浓桃艳李", "t": "桃花浓丽,李花鲜艳。比喻人容貌俊美,神采焕发。"}]}, {"meaning": "颜色重。", "cites": [{"t": "浓朱衍凡唇。", "b": "晋·左思《娇女诗》"}], "words": [{"w": "浓翠", "t": "深绿"}, {"w": "浓黛", "t": "深黛"}, {"w": "浓睡", "t": "酣睡,沉睡。"}]}, {"meaning": "程度深。", "cites": [{"t": "浓睡不消残酒。", "b": "李清照《如梦令》"}, {"t": "更谁家横笛,吹动浓愁。", "b": "宋·李清照《满庭芳》"}], "words": [{"w": "露浓花瘦;游兴很浓;得意浓时趁早休", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1683wx','津','1','jīn','氵','9','','[{"pinyin": "jīn", "defs": [{"meaning": "(会意。金文字形,从舟,从淮。“淮”表示淮水。泛指一般的河流。船停泊在河旁,用来渡河。本义:渡口)。"}, {"meaning": "同本义。", "cites": [{"t": "津,水渡也。", "b": "《说文》"}, {"t": "又东至于孟津。", "b": "《书·禹贡》"}, {"t": "自黄河泛舟而渡者,皆为津也。", "b": "《水津注·河水》注"}, {"t": "风烟望五津。", "b": "王勃《杜少府之任蜀州》"}, {"t": "孔子过之,使子路问津焉。", "b": "《论语·微子》"}], "words": [{"w": "津梁", "t": "渡口的桥梁"}, {"w": "津人", "t": "在渡口以摆渡为生的人"}, {"w": "津门", "t": "在河流渡口所设置的关隘"}, {"w": "津吏", "t": "掌管桥梁及河流渡口的官吏"}, {"w": "津主", "t": "在关卡或渡口检查商旅货物的官吏"}, {"w": "津要", "t": "渡口要地。比喻险要的交通据点"}, {"w": "津逗", "t": "渡水口"}, {"w": "津逮", "t": "经渡口过河而到达目的地。后常用以比喻为学的门径"}, {"w": "津亭驿馆", "t": "渡口和驿站的亭馆。"}]}, {"meaning": "生物的津液;口水。", "cites": [{"t": "津,液也,汁也。", "b": "《三苍》"}, {"t": "津液充郭。", "b": "《素问·汤液胶醴论》"}, {"t": "令人望梅生津。", "b": "陆佃《埤稚·芥》"}], "words": [{"w": "津沫", "t": "口中津液;涎沫"}, {"w": "津唾", "t": "唾液。"}]}, {"meaning": "涯,岸。", "cites": [{"t": "日出九津。", "b": "《吕氏春秋·求人》。注:“崖也。”"}], "words": [{"w": "津岸", "t": "涯岸;水边"}, {"w": "津涯", "t": "岸;水边"}, {"w": "津步", "t": "码头。"}]}, {"meaning": "汗,由汗腺分泌的一种含盐的液体。", "cites": [{"t": "那魔头看见,就吓得浑身是汗,遍体生津。", "b": "《西游记》"}]}, {"meaning": "渡,乘船过河或湖、海。", "cites": [{"t": "而世士罕有津远者。", "b": "《水经注·河水》"}], "words": [{"w": "津渡", "t": "搭乘渡船的渡口;过渡,渡河"}, {"w": "津济", "t": "渡河"}, {"w": "津人", "t": "渡船的船夫"}, {"w": "津航", "t": "渡船。"}]}, {"meaning": "滋润。", "cites": [{"t": "雨不破块,润叶津茎而已。", "b": "《西京杂记》"}], "words": [{"w": "津润", "t": "滋养润泽"}, {"w": "津湿", "t": "透湿。"}]}, {"meaning": "引申为以资财助人。", "cites": [{"t": "听其歌声,许以必贵,倒囊津置入京,继遂遭际。", "b": "宋·王明清《挥尘录》"}], "words": [{"w": "津送", "t": "津发。资助旅费;安葬"}, {"w": "津遣", "t": "发给费用,遣往朝廷。"}]}, {"meaning": "润泽。", "cites": [{"t": "其民黑而津。", "b": "《周礼·地官·大司徒》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1684wx','恃','1','shì','忄','9','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从心,寺声。本义:依赖,依靠)。"}, {"meaning": "同本义。", "cites": [{"t": "恃,赖也。", "b": "《说文》"}, {"t": "无父何怙,无母何恃?", "b": "《诗·小雅·蓼莪》"}, {"t": "恃有年也。", "b": "《公羊传·桓公三年》"}, {"t": "吾以兰为可恃兮。", "b": "《离骚》。注:“怙也。”"}, {"t": "恃源而往者也。", "b": "《庄子·徐无鬼》"}, {"t": "子何恃而往?", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "老妇恃辇而行。", "b": "《战国策·赵策》"}], "words": [{"w": "仗恃", "t": "倚仗"}, {"w": "恃固", "t": "凭仗地势的险固"}, {"w": "恃势", "t": "倚仗权势"}, {"w": "恃爱", "t": "倚仗对方的爱宠"}, {"w": "恃险", "t": "凭仗地势的险要"}, {"w": "恃宠作娇", "t": "倚仗得宠而柔媚作态"}, {"w": "恃赖", "t": "恃凭。依赖,凭借"}, {"w": "恃众", "t": "依仗人多势众"}, {"w": "恃宠", "t": "依仗宠爱"}, {"w": "恃才傲物", "t": "自负其才,藐视他人"}, {"w": "恃功", "t": "自负功高"}, {"w": "恃明", "t": "自负聪明。"}]}, {"meaning": "持;矜持。", "cites": [{"t": "士有孤而自恃,人主有奋而好独者。", "b": "《吕氏春秋》"}]}, {"meaning": "母亲的代称,母死称失恃。", "cites": [{"t": "六岁失怙恃,不为兄嫂所容。", "b": "《聊斋志异·珠儿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1685wx','恒','1','héng','忄','9','','[{"pinyin": "héng", "defs": [{"meaning": "(会意。金文,从心,从月,从二。“二”,表示天地。本义:永久,永恒)。"}, {"meaning": "同本义。", "cites": [{"t": "恒,常也。", "b": "《说文》"}, {"t": "恒者,久也。", "b": "《易·序卦传》"}, {"t": "恒,德之固也。", "b": "《易·系辞下传》"}, {"t": "无恒安处。", "b": "《诗·小雅·小明》"}, {"t": "以求其恒。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "恒牙", "t": "恒齿。永久齿"}, {"w": "恒风", "t": "持续吹佛的风"}, {"w": "恒舞", "t": "历时长而不中断的舞"}, {"w": "恒制", "t": "长久不变的法则。"}]}, {"meaning": "寻常;普通。", "cites": [{"t": "形貌奇伟,骨体不恒。", "b": "《三国志·吴主传》"}, {"t": "人恒状。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "恒态", "t": "常态"}, {"w": "恒恣", "t": "经常的状态"}, {"w": "恒情", "t": "常情"}, {"w": "恒品", "t": "常类;常物"}, {"w": "恒士", "t": "常人,平凡的人"}, {"w": "恒常", "t": "正常的规律"}, {"w": "恒医", "t": "普通的医生"}, {"w": "恒言", "t": "常用的言语。"}]}, {"meaning": "即恒山 。古山名,在今河北省曲阳西北与山西接壤处。五岳中的北岳。", "cites": [{"t": "五岳:华、岱、恒、衡、嵩。", "b": "张华《博物志》"}]}, {"meaning": "经常,常常。", "cites": [{"t": "人恒过。", "b": "《孟子·告子下》"}, {"t": "国恒亡。", "b": ""}, {"t": "恒答言见。", "b": "三国魏·邯郸淳《笑林》"}], "words": [{"w": "恒谈", "t": "常谈"}, {"w": "恒常", "t": "常常;经常。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1686wx','恢','1','huī','忄','9','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从心,灰声。本义:志气大;大;广大)。"}, {"meaning": "同本义。", "cites": [{"t": "恢,大也。", "b": "《说文》"}, {"t": "不恢于夏家。", "b": "《左传·襄公四年》"}, {"t": "恢郭也。", "b": "《公羊传·文公十五年》"}, {"t": "配稷契兮恢唐功。", "b": "《楚辞·守志》"}, {"t": "恢恑谲怪。", "b": "《庄子·齐物论》"}, {"t": "酒量犹恢。", "b": "李曾伯《沁园春》"}, {"t": "以无厚入有间,恢恢乎其于游刃必有余地矣。", "b": "《庄子·养生主》"}], "words": [{"w": "恢伟", "t": "壮伟,魁伟"}, {"w": "恢奇", "t": "雄伟杰出的样子"}, {"w": "恢台", "t": "广大的样子"}, {"w": "恢卓", "t": "宽大,高明"}, {"w": "恢恢", "t": "宽大广阔的样子"}, {"w": "恢郭", "t": "宽大的外城。"}]}, {"meaning": "扩大;发扬。", "cites": [{"t": "恢,大之也。", "b": "《增韵》"}, {"t": "恢弘志士之气。", "b": "诸葛亮《出师表》"}], "words": [{"w": "恢拓", "t": "扩大,开拓"}, {"w": "恢张", "t": "推广,扩展"}, {"w": "恢大", "t": "弘大"}, {"w": "恢拓", "t": "拓展,开拓扩展"}, {"w": "恢宣", "t": "广为发扬。"}]}, {"meaning": "恢复。", "cites": [{"t": "就西粤恢中原,则一隅甚大。", "b": "顾炎武等辑《东明见闻录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1687wx','恍','1','huǎng','忄','9','','[{"pinyin": "huǎng", "defs": [{"meaning": "(形声。从心,況省声。字本作怳,亦作慌.本义:狂的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "怳,狂之貌。", "b": "《说文》"}, {"t": "怳,狂也。", "b": "《广雅·释诂四》"}, {"t": "临风怳兮浩歌。", "b": "《楚辞·少司命》"}], "words": [{"w": "恍恍", "t": "狂的样子。"}]}, {"meaning": "昏瞆不明的样子。", "cites": [{"t": "追怳忽于地底兮。", "b": "《后汉书·张衡传》"}, {"t": "精神怳惚。", "b": "《神女赋序》。注:“不自觉知之意。”"}], "words": [{"w": "恍恍", "t": "模模糊糊"}, {"w": "恍忽", "t": "形貌模糊不清的样子;神智迷乱不定的样子"}, {"w": "恍惑", "t": "迷惑。"}]}, {"meaning": "心神不安的样子;失意的样子。", "cites": [{"t": "怳若有望而不来。", "b": "宋玉《登徒子好色赋》。注:“失意貌。”"}], "words": [{"w": "恍恍", "t": "心神不宁的样子"}, {"w": "恍惝", "t": "失意怅惘"}, {"w": "恍怆", "t": "失意怅惘的样子"}, {"w": "恍然", "t": "失意的样子,惆怅的样子。"}]}, {"meaning": "猛然;忽然。", "cites": [{"t": "恍惊起而长嗟。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "一旦恍然似有以得其要领者,然后乃敢会众说而折其衷。", "b": "朱熹《中庸章句序》"}]}, {"meaning": "一闪而过。", "cites": [{"t": "方转过山子,只见迎面有一个人影儿一恍。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1688wx','恬','1','tián','忄','9','','[{"pinyin": "tián", "defs": [{"meaning": "(形声。从心,甜省声。本义:安静)。"}, {"meaning": "同本义 (表示心境的安静,平静)。", "cites": [{"t": "恬,安也。", "b": "《说文系传》"}, {"t": "恬,静也。", "b": "《广雅》"}, {"t": "恬淡寡欲。", "b": "曹丕《与吴质书》"}, {"t": "恬然自安。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "恬波", "t": "水面平静无波。比喻太平无事"}, {"w": "恬和", "t": "安静温和"}, {"w": "恬忽", "t": "心中恬静而不受外界杂务所干扰"}, {"w": "恬夷", "t": "安静平和"}, {"w": "恬安", "t": "安静;安逸"}, {"w": "恬澜", "t": "波澜平静。"}]}, {"meaning": "安逸,舒适 。", "words": [{"w": "恬卧", "t": "安卧,指清静无为"}, {"w": "恬愉", "t": "安适愉快"}, {"w": "恬泰", "t": "安逸舒适"}, {"w": "恬逸", "t": "安逸"}, {"w": "恬熙", "t": "安乐"}, {"w": "恬适", "t": "安适"}, {"w": "恬乐", "t": "安乐"}, {"w": "恬嬉", "t": "嬉戏逸乐"}, {"w": "恬娱", "t": "安乐自娱"}, {"w": "恬寂", "t": "谓清静无为。"}]}, {"meaning": "。", "words": [{"w": "恬言柔舌", "t": "甜言蜜语"}, {"w": "恬美", "t": "甘美"}, {"w": "恬脆", "t": "甘美,清脆"}, {"w": "恬酒", "t": "即甜酒。"}]}, {"meaning": "泰然。", "cites": [{"t": "轻非誉而恬失民。", "b": "《荀子·富国》"}], "words": [{"w": "恬退", "t": "安然引退"}, {"w": "恬不知怪", "t": "安然处之,不以为怪"}, {"w": "恬不知羞,恬不知愧", "t": "安然处之,不以为耻"}, {"w": "恬不为怪", "t": "言恬不知怪"}, {"w": "恬如", "t": "安然,泰然"}, {"w": "恬不为意", "t": "处之泰然,满不在乎"}, {"w": "恬而", "t": "安然。"}]}, {"meaning": "淡泊 。", "words": [{"w": "恬憺", "t": "淡泊名利,清静安逸"}, {"w": "恬旷", "t": "恬淡闲适"}, {"w": "恬漠", "t": "内心安静淡泊"}, {"w": "恬退", "t": "安于退让。即淡泊名利"}, {"w": "恬淡无为", "t": "心境清静自适而无所营求"}, {"w": "恬裕", "t": "谓淡泊自足。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1689wx','恤','1','xù','忄','9','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从心,血声。本义:忧虑)。"}, {"meaning": "同本义。", "cites": [{"t": "恤,忧也。", "b": "《说文》"}, {"t": "勿恤其孚。", "b": "《易·泰》"}, {"t": "不印自恤。", "b": "《书·大诰》"}, {"t": "告而忧恤。", "b": "《诗·大雅·桑柔》"}, {"t": "不恤国事。", "b": "王安石《答司马谏议书》"}, {"t": "所图者国恤家仇,所期望者豪杰事功。", "b": "明·张煌言《复郎廷佐书》"}], "words": [{"w": "恤功", "t": "担忧民众的事务"}, {"w": "恤恤", "t": "忧虑的样子"}, {"w": "恤民", "t": "忧虑人民的疾苦。"}]}, {"meaning": "体恤。", "cites": [{"t": "朝廷竟无恤赠之典。", "b": "《隋唐演义》"}, {"t": "恤病讨贰。", "b": "《左传》"}, {"t": "不知存恤。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "恤近忽远", "t": "体恤亲近的人而忽略疏远的人"}, {"w": "恤金", "t": ""}]}, {"meaning": "怜悯。", "cites": [{"t": "司寇宜哀狱,台庭幸恤辜。", "b": "唐·沈佺期《移禁司刑》"}], "words": [{"w": "恤矜", "t": "怜悯。"}]}, {"meaning": "周济。", "cites": [{"t": "以恤礼哀寇乱。", "b": "《周书·大宗伯》"}, {"t": "胡以相恤。", "b": "汉·贾谊《论积贮疏》"}, {"t": "存恤贫无告者。", "b": "《明史》"}, {"t": "隋主闻知大怒,厚恤麦铁杖等,杀监军刘士龙,囚于仲文。", "b": "《隋唐演义》"}], "words": [{"w": "恤邻", "t": "救济近邻"}, {"w": "恤贫", "t": "救济贫民"}, {"w": "恤嫠", "t": "救济"}, {"w": "恤病", "t": "救援有危难的人"}, {"w": "恤患", "t": "济人于患难。"}]}, {"meaning": "安置。", "cites": [{"t": "不遂我遣,恤我九列。", "b": "《汉书》"}]}, {"meaning": "顾及;顾念。", "cites": [{"t": "战胜宜阳,不恤楚交,忿也。", "b": "《战国策》"}], "words": [{"w": "恤刑", "t": "慎用刑法。"}]}, {"meaning": "抚养。", "cites": [{"t": "恤孤寡。", "b": "《礼记·月令》"}, {"t": "恭老恤幼,不忘宾旅。", "b": "《孔子家语·弟子行》"}], "words": [{"w": "恤孤", "t": "抚养孤儿。"}]}, {"meaning": "葬仪。", "cites": [{"t": "俗谚云:“会稽打鼓送恤,吴兴步担令史。”", "b": "《南史》"}], "words": [{"w": "恤典", "t": "丧葬礼仪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1690wx','恰','1','qià','忄','9','','[{"pinyin": "qià", "defs": [{"meaning": "(形声。从心,合声。本义:用心)。"}, {"meaning": "同本义。", "cites": [{"t": "恰,用心也。", "b": "《说文新附》"}], "words": [{"w": "恰恰", "t": "用心的样子。"}]}, {"meaning": "适当;正好。", "cites": [{"t": "恰是湘妃泪尽时。", "b": "贾岛《赠人斑竹柱杖》"}, {"t": "野航恰受两三人。", "b": "杜甫《南邻》"}], "words": [{"w": "恰则", "t": "恰恰"}, {"w": "恰恨", "t": "正不巧"}, {"w": "恰合", "t": "正相符合"}, {"w": "恰限", "t": "正遇上"}, {"w": "恰便似", "t": "正好像"}, {"w": "恰贴", "t": "恰当、妥贴"}, {"w": "恰意", "t": "适合心意"}, {"w": "恰适", "t": "合适。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1691wx','恼','1','nǎo','忄','9','','[{"pinyin": "nǎo", "defs": [{"meaning": "(形声。从心,惱(nǎo)声。本义:恼恨;生气;发怒)。"}, {"meaning": "同本义。", "cites": [{"t": "任汝恼弟示,任汝恼姨舅。", "b": "唐·卢仝《寄男抱孙》"}, {"t": "他呆子着了恼的人,张开嘴…被行者轻轻的提将出来。", "b": "《西游记》"}], "words": [{"w": "恼聒", "t": "烦恼,恼恨"}, {"w": "恼懆", "t": "烦恼忧愁"}, {"w": "恼燥,恼躁", "t": "烦恼不安"}, {"w": "恼悔", "t": "悔恨"}, {"w": "恼闷", "t": "懊恼烦闷"}, {"w": "恼烦", "t": "烦恼"}, {"w": "恼懊", "t": "懊恼。"}]}, {"meaning": "懊恼;烦闷。", "cites": [{"t": "将终,无曾痛恼,但西向坐,正念,云“一切空寂”。", "b": "《陈书·姚察传》"}], "words": [{"w": "恼恨恨", "t": "恼恨貌。愤怒怨恨"}, {"w": "恼害", "t": "犹恼恨"}, {"w": "恼忿忿", "t": "气呼呼,气冲冲"}, {"w": "恼巴巴", "t": "气恼,恼怒"}, {"w": "恼犯", "t": "触犯;激怒"}, {"w": "恼燥", "t": "恼火"}, {"w": "恼骂", "t": "生气漫骂"}, {"w": "恼激", "t": "激怒。"}]}, {"meaning": "打扰。", "cites": [{"t": "不恼着我,就半年也不装他一次。", "b": "《西游记》"}], "words": [{"w": "恼聒", "t": "打扰"}, {"w": "恼乱", "t": "打扰。"}]}, {"meaning": "惹,撩拨。", "cites": [{"t": "千杯绿酒何辞醉,一面红妆恼杀人。", "b": "李白《赠段七娘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1692wx','恨','1','hèn','忄','9','','[{"pinyin": "hèn", "defs": [{"meaning": "(形声。从心,艮(gèn)声。本义:怀恨在心,怨恨)。"}, {"meaning": "同本义。", "cites": [{"t": "恨,怨也。", "b": "《说文》"}, {"t": "今财亡民罢,莫不怨恨。", "b": "《国语·周语下》"}, {"t": "役夫敢申恨。", "b": "唐·杜甫《兵车行》"}, {"t": "恨贯肌骨。", "b": "唐·李朝威《柳毅传》"}, {"t": "亡国之恨。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "恨命", "t": "恨恨地;拼命"}, {"w": "恨恨", "t": "气 忿的样子"}, {"w": "恨穷发极", "t": "愤恨到极点而发怒"}, {"w": "恨五骂六", "t": "投骰子时的叫骂声"}, {"w": "恨如头醋", "t": "比喻非常可恶,令人恨得切齿。"}]}, {"meaning": "遗憾;后悔。", "cites": [{"t": "臣死不恨矣!", "b": "《史记·萧相国世家》"}, {"t": "故死者不抱恨而入地,生者不衔怨而受罪。", "b": "《汉书·王嘉传》"}, {"t": "公子恨之复返。", "b": "《史记·魏公子列传》"}, {"t": "叹息痛恨。", "b": "诸葛亮《出师表》"}, {"t": "恨晨光之熹微。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "以是为恨。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "悔恨;怨恨;恨咤", "t": "遗憾嗟叹"}, {"w": ";恨悔", "t": "悔恨"}, {"w": "恨怅", "t": "遗憾惆怅。"}]}, {"meaning": "违逆;不听从", "cites": [{"t": "今不听,是恨秦也;听之,是恨天下也。", "b": "《战国策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1693wx','举','1','jǔ','丶','9','','[{"pinyin": "jǔ", "defs": [{"meaning": "(形声。小篆字形,从手,舉(yǔ)声。本义:双手托物)。"}, {"meaning": "同本义。", "cites": [{"t": "举,对举也。", "b": "《说文》"}, {"t": "举,擎也。", "b": "《广韵》"}, {"t": "其坚不能自举也。", "b": "《庄子·逍遥游》"}, {"t": "举所佩玉玦。", "b": "《史记·项羽本纪》"}], "words": [{"w": "举桉", "t": "桉同“案”。借指夫妻相敬"}, {"w": "举案", "t": "举起托盘以进奉食品。"}]}, {"meaning": "拿起;提起。", "cites": [{"t": "举全吴之地。", "b": "《资治通鉴》"}, {"t": "举以予人。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "举白", "t": "举杯喝尽。干杯"}, {"w": "举踵", "t": "举起脚跟。比喻切望"}, {"w": "举纲持领", "t": "提起网的总绳,网眼就张开了;提起皮衣领子一抖,衣上的毛就都顺了。比喻办事要抓关键部分。"}]}, {"meaning": "飞,飞起;飘动。", "cites": [{"t": "九万里风鹏正举。", "b": "李清照《渔家傲》"}], "words": [{"w": "举翮", "t": "展翅起飞"}, {"w": "风举", "t": "随风飘动。"}]}, {"meaning": "升起;耸起。", "cites": [{"t": "叔籔,火烈具举。", "b": "《诗·郑风》"}, {"t": "中江举帆。", "b": "《资治通鉴》"}]}, {"meaning": "仰起;抬起。", "cites": [{"t": "举头望明月,低头思故乡。", "b": "唐·李白《静夜思》"}], "words": [{"w": "举眼无亲", "t": "人地生疏,孤单无依"}, {"w": "举手加额", "t": "把手举上额头敬礼。"}]}, {"meaning": "发问;动问。", "cites": [{"t": "主人不问,客不先举。", "b": "《礼记》。孔颖达疏:“举亦问也。客从外来,宜问路中寒热无恙,若主人未问,则客不可先问也。”"}]}, {"meaning": "推荐;选用。", "cites": [{"t": "君子不以言举人,不以人废言。", "b": "《论语·卫灵公》"}, {"t": "建一官而三物成,能举善也。", "b": "《左传·襄公三年》"}, {"t": "傅说举于版筑之间。", "b": "《孟子·告子下》"}, {"t": "胶鬲举于鱼盐之中。", "b": ""}, {"t": "管夷吾举于士。", "b": ""}, {"t": "孙叔敖举于海。", "b": ""}, {"t": "举孝廉不行。", "b": "《后汉书·张衡传》"}], "words": [{"w": "举孝廉", "t": "荐举孝子和廉洁之士"}, {"w": "举保", "t": "推荐,举荐"}, {"w": "举主", "t": "古时推举贤者做官或参加考试,被荐者称荐者为举主。"}]}, {"meaning": "提出;列举。", "cites": [{"t": "举类迩而见义远。", "b": "《史记·屈原贾生列传》"}, {"t": "举数人以训汝。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "举似", "t": "指点,告诉"}, {"w": "举案", "t": "列出罪状并加以查证"}, {"w": "举正", "t": "列举其罪而正之以法"}, {"w": "举陈", "t": "列举陈述"}, {"w": "举驳", "t": "提出理由,予以驳回"}, {"w": "举类", "t": "举例。"}]}, {"meaning": "兴起;发动。", "cites": [{"t": "举事必循法。", "b": "《吕氏春秋·察今》"}, {"t": "举大计亦死。", "b": "《史记·陈涉世家》"}, {"t": "并举而争起。", "b": "《汉书·食货志》引汉·贾谊《论积贮疏》"}], "words": [{"w": "举大事", "t": "指发动夺取政权的武装起义"}, {"w": "举大计", "t": "举大事。"}]}, {"meaning": "施行;办理。", "cites": [{"t": "举先王之政。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "攻克;占领。", "cites": [{"t": "一战而举鄢郢。", "b": "《史记·平原君虞卿列传》"}, {"t": "西举巴蜀。", "b": "汉·贾谊《过秦论》"}, {"t": "戊卒叫,函谷举。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "且秦举咸阳而弃之,何但越也。", "b": "《汉书》"}]}, {"meaning": "成就;成功。", "cites": [{"t": "且壮士不死即已,死即举大名耳。", "b": "《史记·陈涉世家》"}]}, {"meaning": "参加科举考试。", "cites": [{"t": "应举下第。", "b": "唐·李朝威《柳毅传》"}, {"t": "岛初赴举。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "乙先得举。", "b": "清·周容《芋老人传》"}, {"t": "举乡试。", "b": "《明史》"}]}, {"meaning": "又如:举进士;举首(科举考试的第一名)。"}, {"meaning": "取;拾取。", "cites": [{"t": "财务之遗者,民莫之举。", "b": "《吕氏春秋》。高诱注:“举,取也。”"}]}, {"meaning": "攀援。", "cites": [{"t": "木熙者,举梧槚。", "b": "《淮南子》"}]}, {"meaning": "耸立,突起。", "cites": [{"t": "河水翼岸夹山,巍峰峻举。", "b": "《水经注》"}]}, {"meaning": "成立,站得住脚。", "cites": [{"t": "要辞达而理举,故无取乎冗长。", "b": "晋·陆机《文赋》"}]}, {"meaning": "记录;登记。", "cites": [{"t": "举口数,生者著,死民者削。", "b": "《商君书》"}]}, {"meaning": "谈论;称引。", "cites": [{"t": "不惟举之于其口,而又笔之于其书。", "b": "唐·韩愈《原道》"}]}, {"meaning": "复兴。", "cites": [{"t": "继绝世,举废国,治乱持危。", "b": "《礼记》"}]}, {"meaning": "祭祀。", "cites": [{"t": "靡神不举,靡爱斯牲。", "b": "《诗·大雅》"}, {"t": "山川神袛有不举者为不敬。", "b": "《礼记》"}]}, {"meaning": "没收。", "cites": [{"t": "凡货不出于关者,举其货,罚其人。", "b": "《周礼》"}]}, {"meaning": "吃丰盛的饮食。", "cites": [{"t": "王日一举,鼎十有二,物皆有俎。", "b": "《周礼》"}]}, {"meaning": "轻手诊脉。", "cites": [{"t": "举,轻手诊脉之法。", "b": "《中国医学大辞典》"}]}, {"meaning": "榉柳。"}, {"meaning": "肺脊;骨体正脊。", "cites": [{"t": "佐食受牢举如傧。", "b": "《仪礼》"}]}, {"meaning": "古代词性术语之一,相当于现在的名词。"}, {"meaning": "古代重量单位,一举重三两。"}, {"meaning": "全。", "cites": [{"t": "举家锦衣玉食。", "b": "宋·司马光《训俭示康》"}, {"t": "举天下所贡蝴蝶、螳螂、油利挞、青丝额一切异状。", "b": "《聊斋志异·促织》"}], "words": [{"w": "举门", "t": "满门,全家"}, {"w": "举时", "t": "举世"}, {"w": "举族", "t": "全族。"}]}, {"meaning": "皆,都。", "cites": [{"t": "举疾首蹙頞。", "b": "《孟子·梁惠王下》"}, {"t": "举欣欣然有喜色。", "b": "《孟子·梁惠王下》"}, {"t": "杀人如不能举。", "b": "《史记·项羽本纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1694wx','觉','1','jiào jué','见','9','','[{"pinyin": "jiào", "defs": [{"meaning": "睡醒。", "cites": [{"t": "觉,悟也。从见,學省声。", "b": "《说文》"}, {"t": "上欲起贤,未觉。", "b": "《汉书·董卓传》"}, {"t": "觉而之渐台。", "b": "《汉书·邓通传》"}], "words": [{"w": "觉卧", "t": "觉醒时和寝卧时"}, {"w": "觉寤", "t": "睡醒"}, {"w": "觉寝", "t": "自睡中觉醒。"}]}, {"meaning": "比较,较量。", "cites": [{"t": "如此贤不肖相觉。", "b": "《孟子·离娄下》注"}, {"t": "我才不及卿,乃觉三十里。", "b": "《世说新语》"}]}, {"meaning": "俗称睡眠为睡觉。", "cites": [{"t": "且有大觉而后知此其大梦也。", "b": "《庄子·齐物论》"}, {"t": "觉见卧闻。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "惟觉时之枕席。", "b": "唐·李白《梦游天姥吟留别》诗"}], "words": [{"w": "睡了一大觉", "t": ""}]}]}, {"pinyin": "jué", "defs": [{"meaning": "(形声。从见,学省声。本义:醒悟,明白)。"}, {"meaning": "同本义。", "cites": [{"t": "觉,悟也。", "b": "《说文》"}, {"t": "上欲起贤,未觉。", "b": "《汉书·董贤传》"}, {"t": "觉而之渐台。", "b": "《汉书·邓通传》"}, {"t": "且有大觉。", "b": "《庄子·齐物论》"}, {"t": "叔术觉焉。", "b": "《公羊传·昭公三十一年》"}, {"t": "觉今是而昨非。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "觉来", "t": "醒来"}, {"w": "觉悟;如梦初觉", "t": ""}]}, {"meaning": "感觉到,意识到。", "cites": [{"t": "而觉跌千里者。", "b": "《荀子·王霸》。注:“知也。”"}, {"t": "岛不觉。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "常觉一切。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "更觉胆落。", "b": "《广东军务记》"}], "words": [{"w": "觉道", "t": "觉得"}, {"w": "不知不觉;觉发", "t": "发觉。"}]}, {"meaning": "启发;使人觉悟。", "cites": [{"t": "予将以斯道觉斯民也。", "b": "《孟子·万章上》"}]}, {"meaning": "发觉,发现。", "cites": [{"t": "觉无异能者。", "b": "唐·柳宗元《三戒》"}, {"t": "不之觉。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "贤智者之称。", "cites": [{"t": "藏埋于终古,而未寤于前觉也。", "b": "晋·左思《吴都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1695wx','宣','1','xuān','宀','9','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从宀(mián),亘(xuán)声。“宀”与房屋有关。一说据甲骨文为云气舒卷自如之象。本义:帝王的宫殿)。"}, {"meaning": "古代帝王的大室,古宫室名。", "cites": [{"t": "宣,天子宣室也。", "b": "《说文》。按,当训大室也。与宽略同。"}, {"t": "武王破纣牧野,杀之于宣室。", "b": "《淮南子·本经》。注:“宣室,殷宫名,一曰狱也。”"}, {"t": "受釐坐宣室。", "b": "《汉书·孝文纪》。注:“未央前正室也。”"}, {"t": "宣室求贤访逐臣,贾生才调更无伦。", "b": "李商隐《贾生》"}]}, {"meaning": "帝王的诏书。", "cites": [{"t": "黄宣去把团营押。", "b": "汤显祖《紫钗记》"}]}, {"meaning": "宣纸的简称。", "cites": [{"t": "尝至琉璃厂购玉版宣,以瓜子金抵其值。", "b": "《清朝野史大观》"}]}, {"meaning": "璧玉。", "cites": [{"t": "璧大六寸,谓之宣。", "b": "《尔雅·释器》。注:“《汉书》所云瑄玉是也。”"}, {"t": "有秦嗣王敢用吉玉宣璧。", "b": "《双剑誃吉金文选·诅楚文》"}]}, {"meaning": "地名。古州名。治所在今安徽省宣城县。"}, {"meaning": "明代宣府镇 ,驻所在今河北省张家口市(旧宣化市)。"}, {"meaning": "宣布。宣读。", "cites": [{"t": "日宣三德。", "b": "《书·皋谟》。传:“布也。”"}, {"t": "或王命急宣,有时朝发白帝,暮到江陵。", "b": "《水经注·江水》"}, {"t": "肃宣权旨。", "b": "《资治通鉴》"}], "words": [{"w": "宣麻", "t": "宣谕任命将相的诏书。引申为朝廷任命"}, {"w": "宣名", "t": "高声通报姓名"}, {"w": "宣牌", "t": "宋,元时朝廷授给各级官吏以证明其官职身分的铜牌;也指宋代负责速递文书的吏员所带的木牌凭证,刻有吏员姓名和职务。"}]}, {"meaning": "放掉;漏掉。", "cites": [{"t": "节宣其气。", "b": "《左传·昭公元年》。注:“散也。”"}], "words": [{"w": "宣腾", "t": "宣泄,膨胀。"}]}, {"meaning": "宣扬;宣传,广泛传播。", "cites": [{"t": "宣其德行。", "b": "《国语·晋语》"}, {"t": "廉君宣恶言。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "宣坛", "t": "僧、道为演说教义进行法事活动所设的讲台"}, {"w": "宣和", "t": "显示;弘扬"}, {"w": "宣猷赞化", "t": "宣道弘法,赞美教化。"}]}, {"meaning": "传达,多用于传达帝王的诏命。", "cites": [{"t": "国王准奏,叫宣,把妖宣至金阶。", "b": "《西游记》"}], "words": [{"w": "宣令", "t": "传达帝王的命令"}, {"w": "宣命", "t": "传达皇帝的诏命"}, {"w": "宣制", "t": "宣布帝王的诏命。"}]}, {"meaning": "抒写;表白。", "cites": [{"t": "夫民虑之于心,而宣之于口。", "b": "《国语》"}], "words": [{"w": "宣情", "t": "发抒情感"}, {"w": "宣陶", "t": "抒发陶写。"}]}, {"meaning": "通,疏通。", "cites": [{"t": "宣汾、洮,障大泽。", "b": "《左传·昭公元年》"}], "words": [{"w": "宣发", "t": "疏导发散。"}]}, {"meaning": "明白;了解。", "cites": [{"t": "民未知信,未宣其用。", "b": "《左传·僖公二十七年》"}]}, {"meaning": "宽大,空敞。", "cites": [{"t": "用而不匮,广而不宣。", "b": "《左传》"}]}, {"meaning": "骄;骄奢。", "cites": [{"t": "维此哲人,谓我劬劳。维彼愚人,谓我宣骄。", "b": "《诗·小雅·鸿雁》"}]}, {"meaning": "周遍;普遍。", "cites": [{"t": "广延宣问,以考星度,未能雠也。", "b": "《汉书》"}], "words": [{"w": "宣备", "t": "尽备,完备"}, {"w": "宣饮", "t": "遍饮"}, {"w": "宣游", "t": "遍游,周游"}, {"w": "宣省", "t": "遍察"}, {"w": "宣洽", "t": "普遍沾溉。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1696wx','宦','1','huàn','宀','9','','[{"pinyin": "huàn", "defs": [{"meaning": "(会意。从宀mián,表示与家庭房屋有关。从臣。“臣”本奴隶。合起来的意思是家室奴仆。本义:做奴隶主或帝王的奴仆)。"}, {"meaning": "同本义。", "cites": [{"t": "与范蠡人宦于吴。", "b": "《国语·越语》。注:“为臣隶也。”"}], "words": [{"w": "宦女", "t": "服务于宫中的女奴。"}]}, {"meaning": "学习官吏的事务。", "cites": [{"t": "宦,仕也。…犹今试用学习之官也。", "b": "《说文》"}, {"t": "宦三年矣。", "b": "《左传·宣公三年》。注:“学也。”"}, {"t": "宦学事师。", "b": "《礼记·曲礼》"}, {"t": "宦于大夫。", "b": "《礼记·杂记》"}], "words": [{"w": "宦学", "t": "学习做官与六艺;做官与做学问。"}]}, {"meaning": "做官。", "cites": [{"t": "及成公即位,乃宦卿之适而为之田。", "b": "《左传·宣公二年》"}, {"t": "与君离别意,同是宦游人。", "b": "王勃《送杜少府之任蜀州》"}], "words": [{"w": "宦成", "t": "登上显贵地位"}, {"w": "宦况", "t": "为官的情况"}, {"w": "宦味", "t": "做官的况味、感触"}, {"w": "宦途", "t": "做官的经历。"}]}, {"meaning": "官吏。", "cites": [{"t": "本图宦达,不矜名节。", "b": "李密《陈情表》"}, {"t": "承籍有宦官。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "宦牒", "t": "记载官吏姓名爵禄的文书"}, {"w": "宦囊羞涩", "t": "为官者手头贫乏"}, {"w": "宦女", "t": "官家女婢"}, {"w": "宦族", "t": "官宦之家。"}]}, {"meaning": "太监,在内宫侍候女眷或被任为宫廷内侍的割去睾丸的男人。", "cites": [{"t": "夫高,故宦人也。", "b": "《史记·李斯列传》"}, {"t": "宦官尚食比郎中。", "b": "《汉书 ·惠帝纪》。注:“阍寺也。”"}, {"t": "宦者,养也。养阉人使其看宫人,此是小臣。", "b": "《文选·宦者传论》注"}], "words": [{"w": "宦竖", "t": "对宦官的鄙称"}, {"w": "宦人", "t": "太监"}, {"w": "宦寺", "t": "宦官。宦官有宦人、寺人等名,简称宦寺"}, {"w": "宦侍", "t": "宦官"}, {"w": "宦者", "t": "太监。也叫宦人、阉人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1697wx','室','1','shì','宀','9','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。从宀从至。人到屋中就停止了。本义:内室)。"}, {"meaning": "同本义 。堂后之正室。古人房屋内部,前叫“堂”,堂后以墙隔开,后部中央叫“室”,室的东西两侧叫“房”。", "cites": [{"t": "室,实也。", "b": "《说文》。段注:“古者前堂后室。释名曰:“室,实也,人物实满其中也。”"}, {"t": "上古穴居而野处,后世圣人易之以宫室,古者宫室贵贱同称。", "b": "《易·系辞》传"}, {"t": "室,堂之内,人所安止也。", "b": "《说文系传》"}, {"t": "若通而言之,则宫室通名,故《尔雅》云,“宫谓之室,室谓之宫。”别而言之,论其四面穹隆则曰宫,因其贮物充实则曰室。”", "b": "《礼记·曲礼上》疏"}, {"t": "入室又弗见也。", "b": "《礼记·问丧》"}], "words": [{"w": "室间", "t": "室内"}, {"w": "室庑", "t": "居室"}, {"w": "室温", "t": "室内温度"}, {"w": "室隅", "t": "室内角落"}, {"w": "登堂入室;室匣", "t": "内室中贮藏衣物的柜。"}]}, {"meaning": "房屋;房间。", "cites": [{"t": "筑室百堵,西南其户。", "b": "《诗·小雅·斯干》"}, {"t": "户庭无尘杂,虚室有余闲。", "b": "晋·陶渊明《归园田居》"}, {"t": "厅旁一室,为吾与汝双栖之所。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "室家", "t": "居所,住宅;夫妇所居为室,一门之内为家;妻子"}, {"w": "室宇", "t": "房舍;屋宇"}, {"w": "室宅", "t": "房舍住宅"}, {"w": "室事", "t": "建房用材"}, {"w": "室制", "t": "宫殿、屋宇的规模样式"}, {"w": "室舍", "t": "房屋;住所"}, {"w": "室第", "t": "住宅"}, {"w": "室闾", "t": "房舍"}, {"w": "室庐", "t": "居室,房舍。"}]}, {"meaning": "家。", "cites": [{"t": "室人交遍谪我。", "b": "《诗·邶风·北门》"}, {"t": "曩与吾祖居者,今其室十无一焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "室中更无人,惟有乳下孙。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "室老", "t": "家相,家臣中的长者"}, {"w": "室族", "t": "家族"}, {"w": "室祭", "t": "家祭"}, {"w": "室人", "t": "家中的人"}, {"w": "室怒市色", "t": "生家中人的气,却以怒色对待市人,谓迁怒于人。"}]}, {"meaning": "指妻子。", "cites": [{"t": "三十曰壮,有室。", "b": "《礼记·曲礼上》"}], "words": [{"w": "室妾", "t": "妻妾"}, {"w": "室氏", "t": "妻子"}, {"w": "正室;侧室", "t": ""}]}, {"meaning": "墓穴。", "cites": [{"t": "百岁之后,归于其室。", "b": "《诗·唐风·葛生》"}]}, {"meaning": "刀剑的鞘 :与刀刃、猎刀或者其它器械紧密配合的护套。", "cites": [{"t": "拔剑,剑长操其室。", "b": "《战国策·燕策》"}]}, {"meaning": "家人;家族。", "cites": [{"t": "将军既帝室之胄,信义著于四海。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "家产;家财。", "cites": [{"t": "四分公室,季氏择二。", "b": "《左传·昭公五年》"}]}, {"meaning": "娶妻;成家。", "cites": [{"t": "丈夫二十而室,妇女十五而嫁。", "b": "《韩非子》"}]}, {"meaning": "男女同房,交媾。", "cites": [{"t": "[李宝信妻]王氏陷贼中,贼欲逼室之,王氏骂贼,贼怒,遂支解之。", "b": "《金史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1698wx','宫','1','gōng','宀','9','','[{"pinyin": "gōng", "defs": [{"meaning": "(象形。甲骨文字形,象房屋形。在穴居野处时代也就是洞窟。外围象洞门,里面的小框框象彼此连通的小窟,即人们居住的地方。本义:古代对房屋、居室的通称(秦、汉以后才特指帝王之宫))。"}, {"meaning": "同本义。", "cites": [{"t": "宫,室也。", "b": "《说文》"}, {"t": "宫谓之室,室谓之宫。", "b": "《尔雅·释宫》"}, {"t": "古者贵贼同称宫。秦汉以来,惟王者所居称宫焉。", "b": "《释文》"}, {"t": "父子皆异宫。", "b": "《礼记·内则》"}, {"t": "上入执宫功。", "b": "《诗·豳风·七月》"}, {"t": "后世圣人易之以宫室。", "b": "《易·系辞下》"}, {"t": "且许子何不为陶冶,舍皆取诸其宫中而用之?", "b": "《孟子·滕文公上》"}, {"t": "父母闻之,清宫除道,张乐设饮,郊迎三十里。", "b": "《战国策·秦策一》"}, {"t": "父母妻子,皆同其宫。", "b": "《墨子·号令》"}, {"t": "君宫中积珍宝,狗马实外厩,美下充下陈,君家所寡有者,以义耳。", "b": "《战国策·齐策》"}]}, {"meaning": "秦汉以来,宫指宫廷,帝王的住所。", "cites": [{"t": "愿令得补黑衣之数,以卫王宫。", "b": "《战国策·赵策》"}, {"t": "沛公入秦宫。", "b": "《史记·留侯世家》"}, {"t": "宫中府中,俱为一体。", "b": "诸葛亮《出师表》"}, {"t": "作宫阿旁,故天下谓之阿房宫。", "b": "《史记·秦始皇本纪》"}, {"t": "宣德间,宫中尚促织之戏,岁征民间。", "b": "《聊斋志异·促织》"}], "words": [{"w": "宫嫔", "t": "宫廷中的女官"}, {"w": "宫漏", "t": "宫廷里计时用的漏壶"}, {"w": "宫众", "t": "保卫王宫的官吏的子弟。"}]}, {"meaning": "神仙的居处 。如:蓬莱宫;天宫;宫神(守卫天宫的门神)。又指文化活动或娱乐的场所。如:少年宫;文化宫。"}, {"meaning": "五音之一。最古的音阶仅用五音,即宫、商、角、徵、羽。古人通常以宫作为音阶的第一级音。", "cites": [{"t": "鼓宫宫动,鼓角角动,音律同矣。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "宫商", "t": "中国古代五声音阶中的第一、第二两个音阶。常用以代指音乐"}, {"w": "宫调", "t": "古代乐曲曲调的总称。凡以宫为主的调式为“宫”;又凡以商、角、变徵、徵、羽、变宫为主的格式为“调”,统称为“宫调”"}, {"w": "宫商角徵羽", "t": "古代五声音阶的名称。"}]}, {"meaning": "以十二个黄道座的位置作为标志的黄道十二宫之一。"}, {"meaning": "宗庙,神殿,供神的大建筑物。", "cites": [{"t": "于是郡国各除道,缮治宫观名山神祠所,以望幸矣。", "b": "《史记·封禅书》"}], "words": [{"w": "雍和宫;宫馆", "t": "祠庙"}, {"w": "宫庙", "t": "犹宗庙。"}]}, {"meaning": "古代五刑之一。阉割男子生殖器。", "cites": [{"t": "宫辟疑赦。", "b": "《书·吕刑》《传》:“宫,淫刑也。男子割势,妇人幽闭。”"}], "words": [{"w": "宫者", "t": "受过宫刑的男子"}, {"w": "宫罪", "t": "宫刑"}, {"w": "宫割", "t": "施以宫刑"}, {"w": "宫墨", "t": "宫刑与墨刑的并称"}, {"w": "宫罚", "t": "宫刑。"}]}, {"meaning": "古代贵族妇女的卧室。", "cites": [{"t": "以阴礼教六宫。", "b": "《周礼》"}]}, {"meaning": "身体。", "cites": [{"t": "余左执鬼中,右执殇宫。王念孙云:中、宫皆身也。", "b": "《国语·楚语上》"}]}, {"meaning": "(guān)。官府,官舍。", "cites": [{"t": "甸粟而内之三宫。", "b": "《谷梁传·桓公十四年》"}, {"t": "县治宫储,设共具而望幸。", "b": "《汉书·食货志下》"}], "words": [{"w": "宫府", "t": "官府。"}]}, {"meaning": "居住;栖息。", "cites": [{"t": "若但竖数十屋而宫,群数十士而饭,而曰教养尽是矣,何其易也!", "b": "宋·叶适《瑞安县重修县学记》"}]}, {"meaning": "营建宫室房屋。", "cites": [{"t": "重门城,昔齐王芳为司马师废之,宫于此。", "b": "《水经注》"}]}, {"meaning": "围绕。", "cites": [{"t": "君为庐宫之。", "b": "《礼记》"}, {"t": "大山宫小山,霍。", "b": "《尔雅·释山》。疏:宫犹围绕也。谓小山在中,大山在外围绕之,山形若此者名霍"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1699wx','宪','1','xiàn','宀','9','','[{"pinyin": "xiàn", "defs": [{"meaning": "(会意。从心,从目,害省声。心、目并用。本义:敏捷)。"}, {"meaning": "同本义。", "cites": [{"t": "宪,敏也。", "b": "《说文》"}, {"t": "博闻多能曰宪。", "b": "《周书·谥法》"}]}, {"meaning": "喜乐的样子。", "cites": [{"t": "天之方难,无然宪宪。", "b": "《诗·大雅》"}], "words": [{"w": "宪宪", "t": "欣欣。喜悦的样子。"}]}, {"meaning": "法令。", "cites": [{"t": "布宪于国。", "b": "《管子·立政》"}, {"t": "宪,法也。", "b": "《尔雅》"}, {"t": "慎乃宪。", "b": "《书·益稷》"}, {"t": "万邦为宪。", "b": "《诗·小雅·六月》"}, {"t": "此君之宪令。", "b": "《左传·襄公二十八年》"}, {"t": "发虑宪。", "b": "《礼记·学记》"}], "words": [{"w": "宪票", "t": "拘提人犯或处理公务的指令"}, {"w": "宪范", "t": "法式,典范。"}]}, {"meaning": "宪司的省称 。宋代官名,即诸路提点刑狱公事,相当于后世的按察司之职。"}, {"meaning": "方法。", "cites": [{"t": "犹迹求履之宪也。", "b": "《管子》"}]}, {"meaning": "旧时属吏对上司的尊称。", "cites": [{"t": "且等本县见过学宪,再作道理。", "b": "《官场现形记》"}], "words": [{"w": "宪台", "t": "对上官的尊称"}, {"w": "宪训煌煌", "t": "对官员训词的恭维"}, {"w": "宪官", "t": "泛指官员。"}]}, {"meaning": "公布。", "cites": [{"t": "宪谓幡书以明之。", "b": "《周礼·朝士》。杜注"}, {"t": "令群吏宪禁令。", "b": "《周礼·小司徒》。注:“表县之。”"}]}, {"meaning": "效法。", "cites": [{"t": "宪禁于玉宫。", "b": "《周礼·天官》"}, {"t": "宪女史之典戒。", "b": "《寡妇赋》"}], "words": [{"w": "宪写", "t": "仿效;模仿。"}]}, {"meaning": "制裁。", "cites": [{"t": "被宪者多结怨。", "b": "《南齐书》"}], "words": [{"w": "宪墨", "t": "绳之以法。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1700wx','突','1','tū','穴','9','','[{"pinyin": "tū", "defs": [{"meaning": "(会意。从穴,从犬。本义:犬从洞穴中突然窜出)。"}, {"meaning": "狗从穴中突然而出。", "cites": [{"t": "突,犬从穴中暂出也。", "b": "《说文》。徐锴系传:“犬匿于穴中伺人,人不意之,突然而出也。”"}, {"t": "是犹以鞿而御駻突。", "b": "《汉书·刑法志》。注:“恶马也。”"}]}, {"meaning": "急速地向前或向外冲。", "cites": [{"t": "铁骑突出刀枪鸣。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "提九突奔客。", "b": "明·魏禧《大铁椎传》"}, {"t": "驰突巷战。", "b": "明·顾炎武《复庵记》"}, {"t": "突骑。", "b": "《后汉书·光武纪》。注:“言能冲突军陈。”"}], "words": [{"w": "突轶", "t": "袭击;冲击"}, {"w": "突战", "t": "伏兵袭击的战术"}, {"w": "突然袭击", "t": "军事用语。乘敌方不备发动快速进攻"}, {"w": "突骑", "t": "冲破敌军阵地的骑兵"}, {"w": "突门", "t": "正式城门以外的秘密出口"}, {"w": "突将", "t": "冲锋陷阵的骠悍将卒"}, {"w": "突忽", "t": "莽撞唐突貌"}, {"w": "突冒", "t": "冲撞"}, {"w": "突撞", "t": "冲撞"}, {"w": "突冲", "t": "冲撞;猛冲"}, {"w": "突地", "t": "以头触地。"}]}, {"meaning": "触犯。", "cites": [{"t": "汗漫突盗以先之。", "b": "《荀子·王霸》。注:“陵触也。”"}], "words": [{"w": "突冒", "t": "触犯"}, {"w": "突浡", "t": "鲁莽;反常。"}]}, {"meaning": "欺诈。", "cites": [{"t": "突,欺也。", "b": "《广雅》"}]}, {"meaning": "穿;破。", "cites": [{"t": "宵突陈城。", "b": "《左传·襄公二十五年》。注:“穿也。”"}], "words": [{"w": "突羽", "t": "疾飞的箭"}, {"w": "突明", "t": "破晓"}, {"w": "突越", "t": "突破而越过"}, {"w": "突坏", "t": "破坏;冲毁"}, {"w": "突过", "t": "冲过"}, {"w": "突贯", "t": "突破而超越。"}]}, {"meaning": "凸出;高耸。", "cites": [{"t": "子能以杌为突乎?", "b": "《吕氏春秋·任地》"}], "words": [{"w": "突杌", "t": "高耸的样子"}, {"w": "突目", "t": "凸眼睛"}, {"w": "突立", "t": "耸立"}, {"w": "突过", "t": "高出;超越"}, {"w": "突黑", "t": "深黑色"}, {"w": "突险", "t": "险峻貌"}, {"w": "突驾", "t": "凌驾;超越"}, {"w": "突镜", "t": "凸透镜;放大镜"}, {"w": "突怒", "t": "盛怒;突起的样子。"}]}, {"meaning": "烟囱。", "cites": [{"t": "墨突不黔。", "b": "《汉书·叙传》"}, {"t": "百寻之屋以突隙之烟焚。", "b": "《淮南子·人间世》"}], "words": [{"w": "灶突", "t": "烟囱"}, {"w": "突隙", "t": "烟囱的裂缝"}, {"w": "突烟", "t": "烟囱里的炊烟。"}]}, {"meaning": "忽然;猝然。", "cites": [{"t": "突,猝也。", "b": "《广雅》"}, {"t": "突如其来如。", "b": "《易·离》"}, {"t": "盗贼奔突。", "b": "王逸《鲁灵光殿赋》。张注:“唐突也。”"}], "words": [{"w": "突地", "t": "忽然"}, {"w": "突突", "t": "忽然"}, {"w": "突尔", "t": "突然"}, {"w": "突兵", "t": "骤然进攻的军队"}, {"w": "突头突脑", "t": "没头没脑。突然地;出人意料地"}, {"w": "气温突降;突告失踪", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1701wx','穿','1','chuān','穴','9','','[{"pinyin": "chuān", "defs": [{"meaning": "(会意。从牙,从穴。牙在穴中,表示穿通的意思。本义:穿通,穿破)。"}, {"meaning": "同本义。", "cites": [{"t": "穿,通也。", "b": "《说文》"}, {"t": "何以穿我墉。", "b": "《诗·召南·行露》"}, {"t": "何以穿我屋。", "b": ""}, {"t": "强弩之末,势不能穿鲁缟。", "b": "《三国志·诸葛亮传》"}, {"t": "此所谓强弩之末势不能穿鲁缟者也。", "b": "司马光《资治通鉴》"}], "words": [{"w": "穿墉", "t": "在墙上打洞"}, {"w": "穿着鼻", "t": "受人摆布"}, {"w": "穿穴", "t": "犹穿凿"}, {"w": "穿空", "t": "犹穿孔"}, {"w": "穿胸", "t": "胸前穿孔透背。"}]}, {"meaning": "通过、透过(空隙、空间等)。", "cites": [{"t": "乱石穿空,惊涛拍岸。", "b": "苏轼《念奴娇》"}, {"t": "历齐河、长清,穿泰山西北谷。", "b": "姚鼐《登泰山记》"}], "words": [{"w": "穿针", "t": "阴历七月初七日穿针乞巧"}, {"w": "穿心", "t": "从中间通过"}, {"w": "穿城", "t": "穿越城镇。"}]}, {"meaning": "贯通;贯串。", "cites": [{"t": "赍钱三百万,皆用青线穿。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "穿鼻", "t": "用绳索或环贯穿鼻中隔"}, {"w": "穿夜", "t": "方言。通宵"}, {"w": "穿望", "t": "切盼。望穿眼睛的意思。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1702wx','窃','1','qiè','穴','9','','[{"pinyin": "qiè", "defs": [{"meaning": "(会意。 从米,以米为穴,意为虫在穴中偷米吃,是会意字。本义:偷)。"}, {"meaning": "同本义。", "cites": [{"t": "窃,盗自中出曰窃。", "b": "《说文》"}, {"t": "敝舆而欲窃之。", "b": "《墨子·公输》"}, {"t": "凡窃木者有刑罚。", "b": "《周礼·山虞》"}, {"t": "小臣窃。", "b": "《礼记·礼运》"}, {"t": "相窃妻妾。", "b": "《诗·桑中序》"}, {"t": "乃攘窃神祗之牺牲牲用。", "b": "《书·微子》"}, {"t": "奸臣窃命。", "b": "陆机《辩亡论上》"}], "words": [{"w": "窃窥", "t": "偷看"}, {"w": "失窃", "t": "财物被人偷走"}, {"w": "偷窃", "t": "盗窃。用不合法的手段秘密取得"}, {"w": "窃宝;窃铁", "t": "偷取斧钺"}, {"w": "窃药", "t": "偷药"}, {"w": "窃食", "t": "偷吃。"}]}, {"meaning": "篡夺。指非其有而取之;不当受而受之。", "cites": [{"t": "虽赏之不窃,其窃位者与。", "b": "《论语·卫灵公》"}, {"t": "窃比于我老彭。", "b": ""}, {"t": "窃国者为诸侯。", "b": "《庄子·胠箧》"}], "words": [{"w": "窃誉", "t": "窃取声名"}, {"w": "窃政", "t": "窃取政权"}, {"w": "窃食", "t": "窃取俸禄"}, {"w": "窃柄", "t": "窃夺权柄"}, {"w": "剽窃", "t": "抄袭窃取。"}]}, {"meaning": "用作表示自己的谦词。", "cites": [{"t": "窃爱怜之。", "b": "《触詟说赵太后》"}], "words": [{"w": "窃以为", "t": ""}]}, {"meaning": "私下;私自。多用作谦词。", "cites": [{"t": "窃自恕。", "b": "《战国策·赵策》"}, {"t": "窃爱怜之。", "b": ""}, {"t": "窃以为媪。", "b": ""}, {"t": "窃以为与君实游。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "窃念", "t": "私下想念。表示个人意见的谦辞"}, {"w": "窃惟", "t": "私下思惟"}, {"w": "窃比", "t": "谦词。私自比拟"}, {"w": "窃言", "t": "私下谈论"}, {"w": "窃庇", "t": "私下包庇"}, {"w": "窃窃", "t": "暗中;偷偷地"}, {"w": "窃议", "t": "私下议论;私自评论。"}]}, {"meaning": "偷偷地。", "cites": [{"t": "窃骂侯生。", "b": "《史记·魏公子列传》"}, {"t": "窥父不在,窃发盆。", "b": "《聊斋志异·促织》"}]}, {"meaning": "盗贼。", "cites": [{"t": "岂不闻背主作窃,不可定期?", "b": "《三国演义》"}, {"t": "边竟有人焉,其名为窃。", "b": "《庄子》。成玄英疏:“窃,贼也。”"}], "words": [{"w": "窃乞", "t": "盗贼和乞丐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1703wx','客','1','kè','宀','9','','[{"pinyin": "kè", "defs": [{"meaning": "(形声。从宀(mián),表示与家室房屋有关,各声。本义:寄居;旅居,住在异国他乡)。"}, {"meaning": "同本义。", "cites": [{"t": "客,寄也。", "b": "《说文》。段注:“字从各,异词也。故自此托彼曰客。引申之曰宾客。”"}, {"t": "念乡人有客于泾阳者。", "b": "唐·李朝威《柳毅传》"}, {"t": "客莆田徐生为予三致其种,种之生且蕃。", "b": "徐光启《甘薯疏序》"}, {"t": "吾兄寄宿州,吾弟客东川。", "b": "白居易《雨夜有念》"}], "words": [{"w": "客边", "t": "暂寓别人家里"}, {"w": "客纲客纪", "t": "经常出门在外者的法度经验"}, {"w": "客寄", "t": "寄居客地人家。"}]}, {"meaning": "以客礼相待。", "cites": [{"t": "孟尝君客我。", "b": "《战国策》。又如:客帐司(衙门中司接待的官员);客将(泛指一般吏役);客遇(以宾客相待);客礼(接待宾客的礼节)"}]}, {"meaning": "来宾,宾客。", "cites": [{"t": "客,宾 客。", "b": "《广韵》"}, {"t": "有不速之客三人来。", "b": "《易·需》"}, {"t": "主人敬客。则先拜客。", "b": "《礼记·曲礼》。按,客小于宾。"}, {"t": "掌大宾之礼及大客之仪。", "b": "《周礼·大行人》"}, {"t": "诸公之臣相为国客。", "b": "《周礼·象胥》"}, {"t": "济济者,客也。", "b": "《礼记·祭义》"}, {"t": "客之美我者,欲有求于我也。", "b": "《战国策·齐策》"}, {"t": "笑问客从何处来。", "b": "唐·贺知章《回乡偶书》"}, {"t": "时座上有健谈客。", "b": "明·魏禧《大铁椎传》"}, {"t": "客问远方。", "b": "《世说新语·方正》"}], "words": [{"w": "客中", "t": "客人身分"}, {"w": "客位", "t": "客厅"}, {"w": "客长", "t": "对旅客的敬称"}, {"w": "客官", "t": "对客人的敬称;对别部官员的称呼"}, {"w": "客位", "t": "宾客的位次,席位"}, {"w": "客道", "t": "为宾客之道"}, {"w": "客难", "t": "宾客的问难。"}]}, {"meaning": "旅客;旅居他乡的人。", "cites": [{"t": "独在异乡为异客,每逢佳节倍思亲。", "b": "王维《九月九日忆山东兄弟》"}], "words": [{"w": "客舟", "t": "客船。运送旅客的船"}, {"w": "客衣", "t": "客行者的衣着"}, {"w": "客侣", "t": "客旅。旅客。"}]}, {"meaning": "从事某种活动的人。", "cites": [{"t": "吴王好剑客,百姓多疮瘢。", "b": "《后汉书·马廖传》"}], "words": [{"w": "生客;熟客;客家", "t": "买货的一方,客户;雇工。"}]}, {"meaning": "诸侯委派出使他国的使臣。", "cites": [{"t": "凡诸伯子男之臣,以其国之爵相为客而相礼。", "b": "《周礼》"}]}, {"meaning": "在本国做官的外国人。", "cites": [{"t": "臣闻吏议驱客,窃以为过矣。", "b": "李期《谏逐客令》"}, {"t": "鲁客事楚王。", "b": "宋·鲍照《拟古三首》"}], "words": [{"w": "客卿", "t": ""}]}, {"meaning": "商贩,行商。", "cites": [{"t": "见那闯学堂的书客,就买几本旧书。", "b": "《儒林外史》"}]}, {"meaning": "泛指某人。", "cites": [{"t": "有客语省兵,兵省非所先。", "b": "王安石《省兵》"}]}, {"meaning": "鬼怪。", "cites": [{"t": "这荒园堑,怕花妖木客寻常见,去小庭深院。", "b": "汤显祖《牡丹亭》"}]}, {"meaning": "食客,门客。", "cites": [{"t": "欲以客往赴秦军。", "b": "《史记·魏公子列传》"}, {"t": "公子使客斩其仇头。", "b": ""}, {"t": "比门下之客。", "b": "《战国策·齐策》"}, {"t": "问门下诸客。", "b": ""}]}, {"meaning": "用于论份出售的食品。", "cites": [{"t": "他又喊了一客葱花猪肉烧饼和一客肉馒头。", "b": "茅盾《有志者》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1704wx','诫','1','jiè','讠','9','','[{"pinyin": "jiè", "defs": [{"meaning": "(形声。从言,戒声。本义:告诫,警告)。"}, {"meaning": "同本义。", "cites": [{"t": "誡,敕也。", "b": "《说文》"}, {"t": "前车覆,后车诫。", "b": "《汉书》"}]}, {"meaning": "规劝。", "cites": [{"t": "宾临终,诫其二子速侯、回题,令善事帝。", "b": "《北史》"}]}, {"meaning": "警诫。", "cites": [{"t": "发诫布令而敌退。", "b": "《荀子·彊国》"}, {"t": "讥恶为诫。", "b": "《越绝书篇叙外传记》"}], "words": [{"w": "引以为诫", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1705wx','冠','1','guān guàn','冖','9','','[{"pinyin": "guān", "defs": [{"meaning": "(会意。从“冖”(mì),用布帛蒙覆。从“元”(人头),从“寸”(手)。意思是:手拿布帛之类的制品加在人的头上,即“冠”。本义:帽子)。"}, {"meaning": "同本义。", "cites": [{"t": "冠,弁冕之总名也。", "b": "《说文》"}, {"t": "冠至尊也。", "b": "《礼记·问丧》"}, {"t": "缁布冠。", "b": "《仪礼·士冠礼》。注:“今小吏冠。”"}, {"t": "凡甸冠弁服。", "b": "《周礼·司服》"}, {"t": "怒发上冲冠。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "新沐者必弹冠。", "b": "《楚辞·渔父》"}, {"t": "冠盖相望,乘坚策肥。", "b": "汉·晁错《论贵粟疏》"}, {"t": "小民罢市,丧出江上,白衣冠送者夹岸。", "b": "《明史·海瑞传》"}, {"t": "峨大冠,拖长绅者,昂昂乎庙堂之器也,果能建伊皋之业耶?", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "衣冠整齐;怒发冲冠;二十而冠;冠礼;冠巾;冠玉", "t": "帽子上装饰的美玉。后多用来指代美男子"}, {"w": "冠佩", "t": "帽子与佩玉。亦指官吏士绅"}, {"w": "冠绶", "t": "礼帽与印绶。"}]}, {"meaning": "公鸡头上的肉瘤或高出的羽毛。", "cites": [{"t": "旋见鸡伸颈摆扑,临视,则虫集冠上,加丁不释。", "b": "《聊斋志异·促织》"}], "words": [{"w": "鸡冠", "t": ""}]}]}, {"pinyin": "guàn", "defs": [{"meaning": "戴;戴帽子。", "cites": [{"t": "带长铗之陆离兮,冠切云之崔嵬。", "b": "《楚辞·屈原·涉江》"}, {"t": "许子冠乎?曰:“冠”。曰:“奚冠?”曰:“冠素。”", "b": "《孟子·滕文公上》"}, {"t": "孟尝君怪其疾也,衣冠而见之。", "b": "《战国策·齐策》"}], "words": [{"w": "沐猴而冠;冠带", "t": "戴帽系带子。借指穿着官服"}, {"w": "冠巾", "t": "戴上帽子、头巾"}, {"w": "冠狗", "t": "戴帽的狗。比喻不知礼义的人。"}]}, {"meaning": "超出众人;超过;位居第一。", "cites": [{"t": "位冠群臣,声施后世。", "b": "《史记·萧相国世家》"}, {"t": "将军勇冠三军,才为出世,弃燕雀之小志,慕鸿鹄以高翔。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "近世寇莱公豪侈冠一时,然以功业大,人莫之非。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "冠带医生", "t": "大医院有称职的医生"}, {"w": "冠首", "t": "位居于众人之上"}, {"w": "冠绝", "t": "遥居首位"}, {"w": "冠伦", "t": "盖过同辈。"}]}, {"meaning": "古代男子到成年则举行加冠礼,叫做冠。一般在二十岁。", "cites": [{"t": "男子二十冠而字。", "b": "《礼记·曲礼上》"}, {"t": "既加冠,益慕圣贤之道。", "b": "明·宋濂《送东阳马生序》"}, {"t": "冠者五六人,童子六七人,浴乎沂,风乎舞雩,咏而归。", "b": "《论语·先进》"}, {"t": "弱冠弄柔翰。", "b": "左思《咏史》"}], "words": [{"w": "冠字", "t": "古代男子二十岁而冠,并赐以字"}, {"w": "冠士", "t": "已行过冠礼的成年之士"}, {"w": "冠子", "t": "已行过冠礼的男子。指二十岁成年男子"}, {"w": "冠岁", "t": "男子二十岁"}, {"w": "弱冠", "t": "刚成年"}, {"w": "冠者", "t": "指成年人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1706wx','诬','1','wū','讠','9','','[{"pinyin": "wū", "defs": [{"meaning": "欺骗。", "cites": [{"t": "因为诬上,卒从吏议。", "b": "司马迁《报任安书》"}, {"t": "佞誉诬谀。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "诬禄", "t": "假冒有功而受禄。"}]}, {"meaning": "无中生有,捏造事实害人。", "cites": [{"t": "诬善之人,其辞游。", "b": "《易·系辞》"}, {"t": "诬守纳己赇。", "b": "明·高启《书博鸡者事》"}, {"t": "诬去贤使君。", "b": ""}, {"t": "诬太守者。", "b": ""}], "words": [{"w": "诬扳", "t": "犯罪的人诬告攀扯他人"}, {"w": "诬罪", "t": "诬陷使人入罪"}, {"w": "诬系", "t": "捏造事实,使人获罪"}, {"w": "诬良为盗;诬言", "t": "诬罔之言。虚伪骗人的言辞"}, {"w": "诬罔", "t": "诬蔑冤枉"}, {"w": "诬诋", "t": "捏造事实以诋毁人"}, {"w": "诬善", "t": "诬陷,欺骗善良。"}]}, {"meaning": "抹杀。", "cites": [{"t": "而高人所述,不可诬矣。", "b": "隋·王度《古镜记》"}]}, {"meaning": "冤屈。", "cites": [{"t": "其刑矫诬。", "b": "《国语·周语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1707wx','语','1','yǔ yù','讠','9','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从言,吾声。本义:谈论;议论;辩论)。"}, {"meaning": "同本义。", "cites": [{"t": "语,论也。", "b": "《说文》"}, {"t": "于时语语。", "b": "《诗·大雅·公刘》。传:“论难曰语。”"}, {"t": "旦日,卒中往往语。", "b": "《史记》"}, {"t": "子不语:怪、力、乱、神。", "b": "《论语·述而》"}, {"t": "夏虫不可以语于冰者,笃于时也。", "b": "《庄子·秋水》"}], "words": [{"w": "语怪", "t": "谈论怪物"}, {"w": "语冰", "t": "谈论冰"}, {"w": "语议", "t": "言谈议论。"}]}, {"meaning": "交谈,说话。", "cites": [{"t": "语,言也。", "b": "《广雅》"}, {"t": "语使能也。", "b": "《礼记·文王世子》。注:“语,言也。”"}]}, {"meaning": "又。", "cites": [{"t": "既歌而语。", "b": ""}, {"t": "可与晤语。", "b": "《诗·陈风·东门之池》"}, {"t": "笑语卒获。", "b": "《诗·小雅·楚茨》"}, {"t": "尔将可与语大理矣。", "b": "《庄子·秋水》"}, {"t": "旦日,卒中往往语,皆指目陈胜。", "b": "《史记·陈涉世家》"}, {"t": "食不语,寝不言。", "b": "《论语·乡党》"}, {"t": "乃向西北奋头,喃喃细语。", "b": "《北史》"}], "words": [{"w": "语涩", "t": "说话艰难,不流利"}, {"w": "语薄言轻", "t": "语言轻薄;说话轻佻,不稳重"}, {"w": "语吐珠玑", "t": "说话、语言像珠玑般优美"}, {"w": "语不间歇;语冰", "t": "比喻人的识量受到时、地所拘束,见识不广"}, {"w": "语语", "t": "语其所当语。即说所该说的话。"}]}, {"meaning": "鸟兽虫类鸣叫。", "cites": [{"t": "君裙香暖金泥凤,画梁语燕惊残梦。", "b": "前蜀·牛峤《菩萨蛮》"}], "words": [{"w": "语风", "t": "在风中鸣叫"}, {"w": "语燕", "t": "会说话的燕子"}, {"w": "语鸟", "t": "会说话的鸟"}, {"w": "语关关", "t": "形容鸟儿鸣叫之声。"}]}, {"meaning": "说的话。", "cites": [{"t": "张胜闻之,恐前语发。", "b": "《汉书·李广苏建传》"}, {"t": "语曰:“唇亡则齿寒。”", "b": "《谷梁传·僖公二年》"}, {"t": "齐君之语偷。", "b": "《左传·文公十七年》"}], "words": [{"w": "语体诗", "t": "用口语写的诗"}, {"w": "语话", "t": "话语;言语"}, {"w": "土语", "t": "土话"}, {"w": "评语", "t": "评论的话。"}]}, {"meaning": "词语。", "cites": [{"t": "为人性僻躭佳句,语不惊人死不休。", "b": "唐·杜甫《江上值水如海势聊短述》"}], "words": [{"w": "语惊四座;语泄", "t": "密语外泄"}, {"w": "语义", "t": "也称词义。指词语的意义"}, {"w": "语妙天下", "t": "言语精妙,无人可及。"}]}, {"meaning": "语言。", "cites": [{"t": "有楚大夫于此,欲其子之齐语也。", "b": "《孟子·滕文公下》"}], "words": [{"w": "语支", "t": "语言学。依谱系分类法分出的比语族小的语言系统"}, {"w": "语言文字", "t": "语言学与文字学的合称"}, {"w": "语简意赅", "t": "语言简练,意思完备"}, {"w": "语学", "t": "研究言语、文字的性质及用法的学问。"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "告诉,使知道。", "cites": [{"t": "公语之故,且告之悔。", "b": "《左传·隐公元年》"}, {"t": "吾语女。", "b": "《论语·阳货》"}, {"t": "若引其许,若至,语人。", "b": "《三国志·方使传》"}, {"t": "夫语妻曰:“为王作剑,三年乃成…往必杀我。”", "b": "晋·干宝《搜神记》"}, {"t": "贫者语于富者曰…", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "语言", "t": "告诉"}, {"w": "语其友;不以语人", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1708wx','扁','1','biǎn piān','户','9','','[{"pinyin": "biǎn", "defs": [{"meaning": "(会意。从户,从册。本义:在门户上题字)。"}, {"meaning": "同本义。", "cites": [{"t": "扁,署也。", "b": "《说文》"}, {"t": "六曰署书是也。", "b": "《秦书八体》"}], "words": [{"w": "扁表", "t": "题门表彰。"}]}, {"meaning": "匾额,题字的长方形牌子。", "cites": [{"t": "梦至一亭,扁日侍康。", "b": "《宋史·吴皇后传》"}], "words": [{"w": "扁榜", "t": "扁牓。匾额"}, {"w": "扁对", "t": "匾额上的对联。"}]}, {"meaning": "指物体宽而薄。", "cites": [{"t": "儿生,欲令其头扁,皆押之以石。", "b": "《后汉书·东夷列传》"}], "words": [{"w": "扁盒子;扁担;扁食", "t": "方言。水饺、锅贴之类的面食。"}]}]}, {"pinyin": "piān", "defs": [{"meaning": "小。", "cites": [{"t": "乃乘扁舟。", "b": "《汉书·货殖传》"}], "words": [{"w": "扁扁", "t": "狭小。指见识,气度"}, {"w": "扁乘", "t": "小车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1709wx','袄','1','ǎo','衤','9','','[{"pinyin": "ǎo", "defs": [{"meaning": "(形声。从衣,夭声。本义:有衬里的上衣)。"}, {"meaning": "皮衣之类的御寒衣服。", "cites": [{"t": "身上穿着银红撇花半旧大袄。", "b": "《红楼梦》"}], "words": [{"w": "皮袄;袄子", "t": "棉袄的俗称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1710wx','祖','1','zǔ','礻','9','','[{"pinyin": "zǔ", "defs": [{"meaning": "(形声。从示,且(jǔ)。从“示”与祭祀、宗庙有关。本义:祖庙)。"}, {"meaning": "同本义。", "cites": [{"t": "祖,始庙也。", "b": "《说文》。段注:“始兼二义,新庙为始,远庙亦为始。”"}, {"t": "左祖右社。", "b": "《周礼·考工记·匠人》"}, {"t": "受终于文祖。", "b": "《书·舜典》孔传:“文祖者,尧文德之祖庙。”"}, {"t": "启乃下,武王善之,封之于宋,立其祖。", "b": "《荀子·成相》"}], "words": [{"w": "祖祢", "t": "祖祢庙。祖庙与父庙。"}]}, {"meaning": "祖父。", "cites": [{"t": "吾祖死于是。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "与吾祖居者。", "b": ""}, {"t": "吾祖太常公。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "祖宗 ;祖先;自祖父以上各辈尊长。", "cites": [{"t": "祖考来格。", "b": "《书·益稷》"}, {"t": "故先祖基之,子孙成之。", "b": "《盐铁论·结和》"}, {"t": "无念尔祖。", "b": "《诗·大雅·文王》"}], "words": [{"w": "祖积", "t": "祖宗遗传下来"}, {"w": "祖贯", "t": "祖辈居住之处;祖籍"}, {"w": "祖陇", "t": "祖传的土地"}, {"w": "祖烈", "t": "祖宗的功业"}, {"w": "祖家", "t": "同一祖先的家族"}, {"w": "祖训", "t": "祖先的遗训;祖父的训戒。"}]}, {"meaning": "祖师。指言行、功业为后世所宗仰者。", "cites": [{"t": "第一祖摩诃迦叶。", "b": "《景德传灯录》"}], "words": [{"w": "祖心,祖意", "t": "祖师的心意"}, {"w": "祖印", "t": "祖师法印"}, {"w": "祖位", "t": "祖师"}, {"w": "祖系", "t": "祖师世系。"}]}, {"meaning": "帝王的庙号  。从汉代开始,凡创业的国君死,其庙号称为“祖”。如汉称刘邦为汉高祖,唐称李渊为唐高祖。", "cites": [{"t": "盖闻古者祖有功而宗有德。", "b": "《史记·孝文帝本纪》"}]}, {"meaning": "初,开始。亦指事物的本源。", "cites": [{"t": "浮游乎万物之祖。", "b": "《庄子·山木》"}], "words": [{"w": "祖始", "t": "本源;起源"}, {"w": "祖源", "t": "水流的源头"}, {"w": "祖帖", "t": "最早的法帖"}, {"w": "祖本", "t": "书籍、碑帖最先的刻本或拓本。"}]}, {"meaning": "效法;承袭。", "cites": [{"t": "皆祖屈原。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "祖式", "t": "效法;仿效"}, {"w": "祖用", "t": "仿效使用"}, {"w": "祖法", "t": "效法"}, {"w": "祖效", "t": "仿效;效法"}, {"w": "祖尚", "t": "效法"}, {"w": "祖袭", "t": "效法,因袭。"}]}, {"meaning": "熟悉。", "cites": [{"t": "祖识地德。", "b": "《国语·鲁语》"}], "words": [{"w": "祖识", "t": "熟习知悉。"}]}, {"meaning": "出行时祭祀路神。引申为饯行。", "cites": [{"t": "至易水之上,既祖,取道。", "b": "《战国策·燕策》"}], "words": [{"w": "祖道,祖韨", "t": "古人出行时祭祀路神"}, {"w": "祖别", "t": "祖饯送别"}, {"w": "祖行", "t": "饯别将病逝者;饯行。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1711wx','神','1','shén','礻','9','','[{"pinyin": "shén", "defs": [{"meaning": "(会意。从示申。“申”是天空中闪电形,古人以为闪电变化莫测,威力无穷,故称之为神。本义:神灵)。"}, {"meaning": "传说中的天神,即天地万物的创造者或主宰者。", "cites": [{"t": "神,天神引出万物者也。", "b": "《说文》"}, {"t": "以祀天神。", "b": "《周礼·大司乐》。注:“谓五帝及日月星辰也。”"}, {"t": "阳之精气曰神。", "b": "《大戴礼记·曾子天圆》"}, {"t": "操蛇之神闻之,惧其不已也,告之于帝。", "b": "《列子·汤问》"}], "words": [{"w": "神司", "t": "负责某种职责的天神"}, {"w": "神会", "t": "迎神赛会"}, {"w": "神祗", "t": "神指天神,祗指地神。泛指神明"}, {"w": "神浒", "t": "神仙游玩的水边"}, {"w": "神馆", "t": "神仙或神灵所居的馆所"}, {"w": "神歌", "t": "颂神之歌。"}]}, {"meaning": "泛指神灵。", "cites": [{"t": "神,聪明正直而壹者也。", "b": "《左传·庄公三十二年》"}, {"t": "神也者,妙万物而为言者也。", "b": "《易·说卦》"}, {"t": "百神受职焉。", "b": "《礼记·礼运》"}, {"t": "山陵川谷丘陵能出云为风雨,皆曰神。", "b": "《礼记·祭法》"}, {"t": "谷神不死。", "b": "《老子》。注:“五藏之神也。”"}, {"t": "圣而不可知之谓神。", "b": "《孟子》"}, {"t": "是故知鬼神之情状。", "b": "《易·系辞上》"}, {"t": "百神尔主矣。", "b": "《诗·大雅·卷阿》"}, {"t": "神,灵也。", "b": "《广韵》"}, {"t": "田祖有神。", "b": "《诗·小雅·大田》"}, {"t": "小信未孚,神弗福也。", "b": "《左传·庄公十年》"}, {"t": "故作不良计,勿复怨鬼神!", "b": "《古诗为焦仲卿妻作》"}, {"t": "则斯役之价值,直可惊天地,泣鬼神,与武昌革命之役并寿。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "无神论;女神;门神;神惠", "t": "祭神食品"}, {"w": "神道", "t": "神像"}, {"w": "神厨", "t": "供奉神灵的石室或龛子"}, {"w": "神祸", "t": "祭神所用的纸人纸马等东西"}, {"w": "神煞", "t": "神威,威势"}, {"w": "神语", "t": "神敕;神的言语"}, {"w": "神路", "t": "指亡灵所经的路径"}, {"w": "神魂", "t": "灵魂"}, {"w": "神理", "t": "灵魂"}, {"w": "神躬", "t": "犹言神魂。"}]}, {"meaning": "精神。", "cites": [{"t": "登斯楼也,则有心旷神怡,宠辱偕忘。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "何必劳神苦思,代百司之职役哉?", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "方今之时,臣以神遇而不以目视,官知止而神欲行。", "b": "《庄子·养生主》"}], "words": [{"w": "凝神;劳神;聚精会神;神王", "t": "谓精神旺盛。王,通“旺”"}, {"w": "神用", "t": "精神的功能"}, {"w": "神光", "t": "精神;神采"}, {"w": "神合", "t": "精神会合"}, {"w": "神越", "t": "精神超逸;精神散失"}, {"w": "神魂飘荡", "t": "形容精神飘忽。"}]}, {"meaning": "表情;神色。", "cites": [{"t": "俊眼修眉,顾盼神飞。", "b": "《红楼梦》"}], "words": [{"w": "神和", "t": "情意相投"}, {"w": "神色自若", "t": "神情面色镇定如常"}, {"w": "神守", "t": "犹神情"}, {"w": "神候", "t": "神情;气宇"}, {"w": "神崖", "t": "神情傲岸"}, {"w": "神仪", "t": "神情仪表。"}]}, {"meaning": "神奇;神异。", "cites": [{"t": "将军以神武雄才,兼仗父兄之烈,割据江东…当横行天下。", "b": "《资治通鉴》"}, {"t": "若印数十百千本,则极为神速。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "神井", "t": "神奇灵异的井"}, {"w": "神枪", "t": "火枪"}, {"w": "神獒", "t": "一种非常机敏而凶恶的大狗"}, {"w": "神水眼", "t": "眼睛。神水,指眼内津液"}, {"w": "神狗", "t": "骂人的话。古怪的狗东西"}, {"w": "神方", "t": "神奇的方术"}, {"w": "神巧", "t": "神奇巧妙"}, {"w": "神秀", "t": "神奇秀美"}, {"w": "神区", "t": "神奇深幽处"}, {"w": "神逸", "t": "神奇超逸"}, {"w": "神诞", "t": "神奇怪诞"}, {"w": "神贤", "t": "神奇美善"}, {"w": "神剑", "t": "神奇的宝剑"}, {"w": "神骏", "t": "形容文艺作品意境神奇新颖"}, {"w": "神机", "t": "神异的禀赋。"}]}, {"meaning": "灵验。", "cites": [{"t": "验之以事,合契若神。", "b": "《后汉书·张衡传》"}], "words": [{"w": "神验", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1712wx','祝','1','zhòu zhù','礻','9','','[{"pinyin": "zhòu", "defs": [{"meaning": "诅咒。", "cites": [{"t": "否则厥口诅祝。", "b": "《书·无逸》"}, {"t": "侯作侯祝。", "b": "《诗·大雅·荡》"}, {"t": "民或祝诅上。", "b": "《史记·孝文纪》"}, {"t": "南郡极热之地,其人祝树树枯,唾鸟鸟坠。", "b": " 《论衡》"}], "words": [{"w": "祝诅", "t": "祝告鬼神,使加祸别人。"}]}]}, {"pinyin": "zhù", "defs": [{"meaning": "(会意。甲骨文字形,象一个人跪在神前拜神、开口祈祷。从示,从儿口。“儿”是古文“人”字。本义:男巫,祭祀时主持祝告的人,即庙祝)。"}, {"meaning": "同本义。", "cites": [{"t": "祝,祭主赞词者。", "b": "《说文》"}, {"t": "兑为口为巫。", "b": "《易》。按,祝所以悦神也。"}, {"t": "祝将命也。", "b": "《礼记·郊特牲》"}, {"t": "祝,以孝告。嘏以慈告。", "b": "《礼记·礼运》"}, {"t": "有大祝、小祝、丧祝、甸祝、诅祝。", "b": "《周礼·夏官》注"}, {"t": "逸祝册。", "b": "《书·洛诰》"}, {"t": "与巫祝共分其余钱持归。", "b": "褚少孙《西门豹治邺》"}, {"t": "工祝招君,背行先些。", "b": "《楚辞·招魂》。注:“男巫曰祝”"}], "words": [{"w": "祝人", "t": "古代掌祭祀的 "}, {"w": "巫祝", "t": "巫婆师公"}, {"w": "祝伯", "t": "掌宗庙祭祀之官"}, {"w": "祝宗", "t": "古代主持祭祀祈祷者"}, {"w": "祝官", "t": "古代掌管祭祀祝祷等事宜之官"}, {"w": "祝嘏", "t": "祭祀时致祝祷之辞和传达神言的执事人。"}]}, {"meaning": "祭神的祈祷词。", "cites": [{"t": "皇帝、皇后诣天神、地祗位,致奠;阖门读使读祝讫,复位坐。", "b": "《辽史》"}], "words": [{"w": "祝赞", "t": "祝辞,祷告鬼神之文"}, {"w": "祝文", "t": "古代祭祀神鬼或祖先的文辞"}, {"w": "祝规", "t": "祝词中劝勉的话。"}]}, {"meaning": "祝贺。", "cites": [{"t": "犀首跪行,为仪千秋之祝。", "b": "《战国策》"}]}, {"meaning": "祷告,向鬼神求福。", "cites": [{"t": "为仪千秋之祝。", "b": "《战国策·齐策二》"}, {"t": "尸祝齐戒。", "b": "《淮南子·说山》"}, {"t": "祭祀必祝。", "b": "《战国策·赵策》"}, {"t": "望空代祝。", "b": "《聊斋志异·促织》"}], "words": [{"w": "祝罢", "t": "祝祷完毕"}, {"w": "祝献师", "t": "祈祷祭祀鬼神的巫师"}, {"w": "祝白", "t": "祷告"}, {"w": "祝告", "t": "祷告于神灵"}, {"w": "祝庇", "t": "祝告神灵"}, {"w": "祝祓", "t": "求告神录降福除灾"}, {"w": "祝神", "t": "祝祷于神灵。"}]}, {"meaning": "向人祝颂。", "cites": [{"t": "王为群臣祝。", "b": "《吕氏春秋·乐成》"}, {"t": "纯老生日,大家公祝。", "b": "《孽海花》"}], "words": [{"w": "祝冥寿", "t": "为死者祝寿"}, {"w": "祝全队成功;祝他晚安;祝典", "t": "庆祝的典礼"}, {"w": "祝望", "t": "祝愿和盼望"}, {"w": "祝报", "t": "为人祝福,以报恩德"}, {"w": "祝意", "t": "祝贺的心意"}, {"w": "祝庆", "t": "庆祝,庆贺。"}]}, {"meaning": "断;断绝。", "cites": [{"t": "南国之人,祝发而裸。", "b": "《列子》"}, {"t": "子路死,子曰:“噫,天祝予!”", "b": "《公羊传·哀公十四年》"}], "words": [{"w": "祝发", "t": "剃去头发为僧尼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1713wx','祠','1','cí','礻','9','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从示,司声。本义:春祭)。"}, {"meaning": "同本义。", "cites": [{"t": "春祭曰祠,品物少,多文辞也。", "b": "《说文》"}, {"t": "仲春之月祠不用牺牲,用圭璧及皮币。", "b": "《礼记·月令》"}]}, {"meaning": "供奉鬼神、祖先或先贤的庙堂。", "cites": [{"t": "祠,神祠也。", "b": "《汉书·陈胜传》注"}, {"t": "又间令吴广之次所旁丛祠中。", "b": "《史记·陈涉世家》"}], "words": [{"w": "宗祠", "t": "祠堂"}, {"w": "祠灶", "t": "宗祠;祠堂"}, {"w": "祠馆", "t": "犹祠堂。"}]}, {"meaning": "引申为祭祀。", "cites": [{"t": "此秦王之所以庙祠而求也。", "b": "《韩非子·十过》"}], "words": [{"w": "祠求", "t": "祭神祈求"}, {"w": "祠事", "t": "祭礼,祭祀之事"}, {"w": "祠官", "t": "掌管祭祀之官。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1714wx','误','1','wù','讠','9','','[{"pinyin": "wù", "defs": [{"meaning": "谬误;错误。", "cites": [{"t": "误,谬也。", "b": "《说文》"}, {"t": "群臣议皆误。", "b": "《史记·萧相国世家》"}, {"t": "兴尽晚归舟,误入藕花深处。", "b": "李清照《如梦令》"}, {"t": "误落尘网中。", "b": "晋·陶渊明《归田居》"}, {"t": "土木之误。", "b": "清·张廷玉《明史》"}], "words": [{"w": "笔误;误错", "t": "失误差错"}, {"w": "误证", "t": "错误的证明"}, {"w": "误本", "t": "有错字的版本"}, {"w": "误谬", "t": "谬误;差错。"}]}, {"meaning": "耽误。", "cites": [{"t": "郑以救公误之,遂失秦伯。", "b": "《左传·僖公十五年》"}], "words": [{"w": "误却", "t": "耽误掉;失掉。"}]}, {"meaning": "妨害。", "cites": [{"t": "专欲误将军。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "误人不浅;误身", "t": "贻误自身"}, {"w": "误人", "t": "贻害于人"}, {"w": "误惑", "t": "贻误迷惑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1715wx','诱','1','yòu','讠','9','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从言,秀声。字本作“羑”,从厶(sī),从羑(yǒu)。厶,同“私”。羑,诱导。本义:教导;引导;劝导)。"}, {"meaning": "同本义。", "cites": [{"t": "诱,引也。", "b": "《广韵》"}, {"t": "不诱于誉,不恐于诽。", "b": "《荀子·非十二子》"}, {"t": "夫子循循然善诱人,博我以文,约我以礼,欲罢不能。", "b": "《论语·子罕》"}], "words": [{"w": "诱动", "t": "劝诱打动"}, {"w": "诱训", "t": "诱导教诲"}, {"w": "诱进", "t": "诱导进取。"}]}, {"meaning": "引诱。", "cites": [{"t": "无诱于势利。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "盖以诱敌。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "诱兵", "t": "战争时诈败以引诱敌人中计的士兵或引诱敌兵"}, {"w": "诱敌", "t": "诱引敌人进入埋伏的地方。"}]}, {"meaning": "向导,引路。", "cites": [{"t": "步及骤处兮,诱骋先。", "b": "《楚辞·招魂》"}], "words": [{"w": "诱接", "t": "招引接纳;诱纳"}, {"w": "诱协", "t": "利诱协迫。"}]}, {"meaning": "欺狂,诱骗。", "cites": [{"t": "彼美郦生,既为交亲,诱袭军印,岂无他人。", "b": "唐·吕温《繇鹿赋》"}], "words": [{"w": "诱略", "t": "诱骗,掠夺"}, {"w": "诱狎", "t": "诱奸"}, {"w": "诱哄", "t": "诱惑哄骗"}, {"w": "诱巧", "t": "以狡猾手段欺骗人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1716wx','诲','1','huì','讠','9','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从言,每声。本义:教导)。"}, {"meaning": "同本义。", "cites": [{"t": "诲,说教也。", "b": "《说文》"}, {"t": "慢藏诲盗,野容诲淫。", "b": "《易·系辞》"}, {"t": "胥教诲。", "b": "《书·无逸》"}, {"t": "诲尔序爵。", "b": "《诗·大雅·桑柔》"}, {"t": "夫子诲之髽。", "b": "《礼记·檀弓》"}, {"t": "使师曹诲之琴。", "b": "《左传·襄公十四年》"}, {"t": "诲人不倦。", "b": "《论语·述而》"}], "words": [{"w": "诲示", "t": "教导,晓示"}, {"w": "诲诱", "t": "教导循诱"}, {"w": "诲谕", "t": "教诲晓喻"}, {"w": "诲翰", "t": "诲函。对对方书信的敬称。"}]}, {"meaning": "教导的话。", "cites": [{"t": "朝夕纳诲,以辅台德。", "b": "《书·说命上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1717wx','说','1','shuō shuì tuō yuè','讠','9','','[{"pinyin": "shuō", "defs": [{"meaning": "(形声。从言,兑(duì)声。本义:用言语解说,开导,说明)。"}, {"meaning": "同本义。", "cites": [{"t": "说,释也,一曰谈说也。", "b": "《说文》"}, {"t": "说所以明也。", "b": "《墨子·经上》"}, {"t": "子墨子起,再拜曰:“请说之。吾在北方闻子为梯,将以攻宋。宋何罪之有?”", "b": "《墨子·公输》"}, {"t": "勾践说于国人。", "b": "《国语·越语》。注:“解也。”"}, {"t": "佐下军以说焉。", "b": "《左传·昭公九年》。注:“自解说。”"}, {"t": "是欲以我为说于匈奴也。", "b": "《汉书·王莽传》"}], "words": [{"w": "说卦", "t": "“易传”篇名。解说八卦性质、变化和象征"}, {"w": "说经", "t": "讲说经书或演述佛经故事"}, {"w": "说事", "t": "说明事件,事实"}, {"w": "说梦", "t": "说明梦中所见之事"}, {"w": "说戒", "t": "佛教在每月月半、月底说解戒律"}, {"w": "说委", "t": "说明原委"}, {"w": "说到家", "t": "解释得清清楚楚"}, {"w": "说义", "t": "解说义理"}, {"w": "说解", "t": "说明解释"}, {"w": "说家", "t": "注家或评论家"}, {"w": "说法台", "t": "佛教讲道的高台。"}]}, {"meaning": "谈说,讲说。", "cites": [{"t": "得其船,便扶向路,处处志之。及郡下,诣太守,说如此。", "b": "晋·陶渊明《桃花源记》"}, {"t": "低眉信手续续弹,说尽心中无限事。", "b": "白居易《琵琶行》"}, {"t": "汝来床前,为说稗官野史可喜可愕之事,聊资一欢。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "说不了", "t": "话未说完"}, {"w": "说不的", "t": "说不得;说不定,无法肯定"}, {"w": "说兵机", "t": "空谈;夸口"}, {"w": "说古", "t": "吹嘘;吹牛"}, {"w": "说发", "t": "说动"}, {"w": "说杀", "t": "说绝了;没有挽回余地"}, {"w": "说述", "t": "叙述;诉说"}, {"w": "说大口", "t": "说大话"}, {"w": "说方便", "t": "说好话"}, {"w": "说分上", "t": "讲人情"}, {"w": "说平话", "t": "说评书"}, {"w": "说舌头", "t": "说长道短;搬弄是非"}, {"w": "说风情", "t": "讲男女相爱弄情的话。"}]}, {"meaning": "告知;告诉。", "cites": [{"t": "夫差将死,使人说于子胥。", "b": "《国语·吴语》"}]}, {"meaning": "评议;谈论。", "cites": [{"t": "说,论也。", "b": "《广雅·释诂二》"}, {"t": "游于说。", "b": "《礼记·少仪》。疏:“谓论说。”"}, {"t": "稻花香里说丰年,听取蛙声一片。", "b": "宋·辛弃疾《西江月·夜行黄沙道中》"}], "words": [{"w": "说是非", "t": "评说事理的是非"}, {"w": "说谈", "t": "谈论"}, {"w": "说议", "t": "议论"}, {"w": "说结", "t": "商量妥当"}, {"w": "说票", "t": "绑匪向事主谈判赎票事项。"}]}, {"meaning": "劝告;责备。", "cites": [{"t": "六曰说。", "b": "《周礼·太祝》。注:“以辞责之。”"}, {"t": "虽户说以眇论,终不能化。", "b": "《史记·货殖列传序》"}], "words": [{"w": "说发", "t": "说动"}, {"w": "说和", "t": "劝说使和解"}, {"w": "说泛", "t": "说动"}, {"w": "说化", "t": "劝说使感化"}, {"w": "说不上去", "t": "不听劝告"}, {"w": "他父亲说了他一顿", "t": ""}]}, {"meaning": "学说;观点;言论。", "cites": [{"t": "然是说,余尤疑之。", "b": "宋·苏轼《石钟山记》"}, {"t": "神仙之说,所谓为蛇画足。", "b": "清·全祖望《梅花岭记》"}, {"t": "说秦王书十上而说不行。", "b": "《战国策·秦策一》"}], "words": [{"w": "又一说;著书立说;异说;邪说", "t": ""}]}, {"meaning": "古代墨家逻辑的名词,指推理。", "cites": [{"t": "论求群言之比,以名举实,以辞抒意,以说出故。", "b": "《墨子·小取》"}]}, {"meaning": "指说书。", "cites": [{"t": "子之说,能使人慷慨涕泣矣。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "一种文体,通过发表议论或记述事物来说明某个道理。如《爱莲说》、《捕蛇者说》。"}]}, {"pinyin": "shuì", "defs": [{"meaning": "说服;劝说。", "cites": [{"t": "义兴人谓为三横,而处尤剧。或说处杀虎斩蛟,实冀三横唯余其一。", "b": "《世说新语·自新》"}, {"t": "鲰生说我曰:“距关,毋内诸侯,秦地可尽王也。”", "b": "《史记·项羽本纪》"}, {"t": "公子患之,数请魏王,及宾客辩士说王万端。", "b": "《史记·魏公子列传》"}], "words": [{"w": "游说;说士", "t": "游说的人"}, {"w": "说客", "t": "游说之士"}, {"w": "说项", "t": "本意为称道人善,后引申凡替人游说,阐说人情都可称“说项”"}, {"w": "说难", "t": "指用言语说服他人并不容易"}, {"w": "说城", "t": "劝说举城投降"}, {"w": "说导", "t": "劝说开导"}, {"w": "说辞", "t": "游说的话"}, {"w": "说谏", "t": "劝说进谏"}, {"w": "说调", "t": "怂恿,撺掇。"}]}]}, {"pinyin": "tuō", "defs": [{"meaning": "解脱。", "cites": [{"t": "舆说辐,夫妻反目。", "b": "《易·小畜》"}, {"t": "不然,岂其伐人而说甲执冰以游?", "b": "《左传·昭公二十七年》"}, {"t": "降,说履,开坐,修爵无数。", "b": "《荀子·乐论》"}, {"t": "却反,舍于郊,皆说然息。", "b": "《公羊传·定公八年》"}]}]}, {"pinyin": "yuè", "defs": [{"meaning": "古语的读法。", "cites": [{"t": "学而时习之,不亦说乎?", "b": "《论语·学而》"}, {"t": "秦王不说。", "b": "《战国策·魏策》"}, {"t": "宣王说之。", "b": "《韩非子·内诸说上》"}, {"t": "民说之,使王天下,号之曰燧人氏。", "b": "《韩非子·五蠹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1718wx','诵','1','sòng','讠','9','','[{"pinyin": "sòng", "defs": [{"meaning": "(形声。从言,甬(yǒng)声。本义:背诵、朗读)。"}, {"meaning": "同本义。", "cites": [{"t": "诵,讽也。", "b": "《说文》。徐锴曰:“临文为诵。”"}, {"t": "兴道讽诵言语。", "b": "《周礼·大司乐》。注:“背文曰讽,以声节之曰诵。”"}, {"t": "春诵夏弦。", "b": "《礼记·文王世子》"}, {"t": "宴居有师工之诵。", "b": "《国语·楚语》"}, {"t": "子路终身诵之。", "b": "《论语·子罕》"}, {"t": "十五弹箜篌,十六诵诗书。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "坐大厦之下而诵《诗》《书》,无奔真诚之劳矣。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "熟读成诵;过目成诵;背诵;诵经;记诵", "t": "默记和背诵"}, {"w": "诵笃笃", "t": "叽叽咕咕,嘟嘟噜噜"}, {"w": "诵咏", "t": "诵读吟咏"}, {"w": "诵诗", "t": "诵读《诗经》"}, {"w": "诵说", "t": "诵读解说"}, {"w": "诵数", "t": "诵读熟习经书"}, {"w": "诵谏", "t": "诵读诗歌以作为劝戒"}, {"w": "诵忆", "t": "背诵并记住"}, {"w": "诵号", "t": "高声诵经。"}]}, {"meaning": "述说,发表详细内容。", "cites": [{"t": "聊为足下诵其所闻。", "b": "唐·韩佥《答陈生书》"}, {"t": "王之为都者,臣知五人焉,知其罪,惟孔距心,为王诵之。", "b": "《孟子·公孙丑下》"}]}, {"meaning": "颂扬。", "cites": [{"t": "本原事业,只诵功德。", "b": "秦《泰山刻石》"}, {"t": "使百姓歌诵,史官纪德。", "b": "《后汉书·何敞传》"}, {"t": "垂流亿载,世世叹诵。", "b": "汉《司隶校尉杨孟文石门颂》"}], "words": [{"w": "诵德", "t": "颂功。颂扬功德"}, {"w": "诵法", "t": "称颂效法"}, {"w": "诵烈", "t": "颂扬功业。"}]}, {"meaning": "公开。", "cites": [{"t": "平阳侯驰语太尉周勃,勃尚恐不胜,赤敢诵言诛之。", "b": "《汉书·高后纪》"}], "words": [{"w": "诵言", "t": "公然言说。"}]}, {"meaning": "诗篇。", "cites": [{"t": "吉甫作诵,穆如清风。", "b": "《诗·大雅·烝民》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1719wx','垦','1','kěn','土','9','','[{"pinyin": "kěn", "defs": [{"meaning": "(形声。从土,(kěn)声。本义:翻土,开垦)。"}, {"meaning": "同本义。", "cites": [{"t": "垦,耕也。", "b": "《说文新附》"}, {"t": "垦,耕也。", "b": "《广雅·释地》"}, {"t": "土不备垦。", "b": "《国语·周语上》"}, {"t": "叩石垦壤。", "b": "《列子·汤问》"}], "words": [{"w": "垦化", "t": "谓开垦荒地使变为良田"}, {"w": "垦田", "t": "开垦耕地;已开垦的田地"}, {"w": "垦民", "t": "开荒种地的人"}, {"w": "垦草", "t": "垦荒。开垦荒地"}, {"w": "垦耕", "t": "开垦耕作"}, {"w": "垦耨", "t": "犹翻耕"}, {"w": "垦发", "t": "种植"}, {"w": "垦除", "t": "铲除。"}]}, {"meaning": "损伤。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1720wx','退','1','tuì','辶','9','','[{"pinyin": "tuì", "defs": [{"meaning": "(会意。小篆字形。从彳,从日,从攵。彳(chì),小步。攵(suī),足的反写。本义:向后走,后退)。"}, {"meaning": "同本义。", "cites": [{"t": "退,卻也。", "b": "《说文》"}, {"t": "宾三退负序。", "b": "《仪礼·聘礼》"}, {"t": "主人少退。", "b": "《仪礼·乡射礼》"}, {"t": "待坐则必先退席。", "b": "《礼记·玉藻》"}, {"t": "不可以退而谓之退。", "b": "《孙子·谋政》"}, {"t": "暑为之退。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "攻一时敌退。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "敌乃纷退。", "b": ""}], "words": [{"w": "退到院子里;他往后退了几步;退缩", "t": "后退,回缩"}, {"w": "退生", "t": "后退以求生"}, {"w": "退厅", "t": "退堂。旧指官吏问案完毕,退出公堂"}, {"w": "退藏于密", "t": "后退隐藏于秘密之处"}, {"w": "退殿", "t": "君王视朝完毕而退出殿堂"}, {"w": "退出战斗;退罢", "t": "退兵罢 战"}, {"w": "退散", "t": "后退溃散;撤退疏散"}, {"w": "退军", "t": "撤退军队。"}]}, {"meaning": "退却;打退。", "cites": [{"t": "有能助寡人谋而退吴者,吾与之共知越国之政。", "b": "《国语·越语》"}], "words": [{"w": "退敌", "t": "打退敌军"}, {"w": "退败", "t": "退却失败"}, {"w": "退远", "t": "斥退疏远"}, {"w": "退阵", "t": "临阵脱逃"}, {"w": "退送", "t": "把作祟的鬼神驱退送走"}, {"w": "退负", "t": "败退"}, {"w": "退鬼", "t": "驱鬼"}, {"w": "退舍", "t": "退却;退避。"}]}, {"meaning": "引申为减退;下降。", "cites": [{"t": "以图国用,而进退之。", "b": "《周礼·小司寇》。注:“犹损益也。”"}, {"t": "退食自公。", "b": "《诗·召风·羔羊》"}], "words": [{"w": "退财白虎", "t": "使人家消耗钱财,由富变穷的凶神"}, {"w": "退色;退烧;退潮;退率", "t": "几个相关数递减的比率"}, {"w": "退责", "t": "减免债务"}, {"w": "退食自公", "t": "减膳以示节俭"}, {"w": "退味", "t": "兴致减退。"}]}, {"meaning": "辞去官职;退隐。", "cites": [{"t": "夫子践位而退。", "b": "《国语·楚语》"}, {"t": "退亦忧。", "b": "宋·范仲淹《岳阳数记》"}], "words": [{"w": "退听谢事", "t": "放弃权力,摆脱事务"}, {"w": "退休", "t": "辞官家居"}, {"w": "退老", "t": "退休养老"}, {"w": "退征", "t": "辞退官职"}, {"w": "退食", "t": "臣子退朝后在家就食休息"}, {"w": "退黜", "t": "废免;罢退;退落"}, {"w": "退隐", "t": "辞官隐居;后退隐没"}, {"w": "退废", "t": "黜退不用"}, {"w": "退闲", "t": "退职闲居。"}]}, {"meaning": "离去,退出。", "cites": [{"t": "朝廷曰退,燕游曰归。", "b": "《礼记·少仪》"}], "words": [{"w": "退值", "t": "下班"}, {"w": "退伍", "t": "军人服兵役年期届满退出队伍"}, {"w": "退席", "t": "离开座位"}, {"w": "退朝", "t": "古代帝王或诸侯每天早上在朝廷会见大臣商讨大事,退朝就是散会后退出朝廷"}, {"w": "退院", "t": "僧人脱离寺院"}, {"w": "退迹", "t": "退归;退居"}, {"w": "退相", "t": "退居的宰相。"}]}, {"meaning": "谦让。", "cites": [{"t": "毅撝退辞谢。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "退让", "t": "谦逊;礼让"}, {"w": "退听", "t": "退让顺从"}, {"w": "退静", "t": "退让静默。不谋进用"}, {"w": "退逊", "t": "退让;谦逊"}, {"w": "退损", "t": "退让谦抑"}, {"w": "退淡", "t": "退素。谦退淡泊"}, {"w": "退恕", "t": "退让;退避。"}]}, {"meaning": "改悔。", "cites": [{"t": "虽欲有退,众将责焉。", "b": "《国语·晋语二》"}]}, {"meaning": "脱去。", "cites": [{"t": "解下腰上的宽皮带,退下鞋子,盘腿坐在炕桌前边。", "b": "于敏《头一天》"}]}, {"meaning": "返回,归。", "cites": [{"t": "退而甘食其土之有。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "退而思其言。", "b": "明·刘基《卖柑者言》"}, {"t": "敬亭退而凝神。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "天文学上称天体自东向西运行为“退”。", "cites": [{"t": "交道每月退一度余,凡二百四十九交而一期。", "b": "宋·沈括《梦溪笔谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1721wx','既','1','jì','旡','9','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。甲骨文字形,左边是食器的形状,右边象一人吃罢而掉转身体将要离开的样子。本义:吃罢,吃过)。"}, {"meaning": "同本义。", "cites": [{"t": "既,小食也。", "b": "《说文》。罗振玉曰:“即,象人就食;既,象人食既。许训既为小食,义与形不协矣。”"}, {"t": "君既食。", "b": "《礼记·玉藻》"}, {"t": "不拜既爵。", "b": "《义礼·乡饮酒礼》"}]}, {"meaning": "食尽。指日全食或月全食。", "cites": [{"t": "秋,七月,壬辰,朔,日有食之,既。", "b": "《春秋·桓公三年》。杜预注:“既,尽也。”"}, {"t": "其合相当如袭辟者,日既是也。", "b": "汉·王充《论衡》"}]}, {"meaning": "完毕;完了。", "cites": [{"t": "既而曰。", "b": "《公羊传·宣公元年》。注:“事毕也。”"}, {"t": "既者,尽也。有继之辞也。", "b": "《谷梁传》"}, {"t": "既月。", "b": "《虞书》"}, {"t": "董泽之蒲可胜既乎。", "b": "《左传·宣公十二年》"}, {"t": "薮泽肆既。", "b": "《国语·周语》"}, {"t": "吾与汝既其文,未既其实。", "b": "《庄子·应帝王》"}], "words": [{"w": "既济", "t": "六十四卦之。离下坎上。意指万事皆济"}, {"w": "既冠之后", "t": "成年之后。古代男子二十岁行加冠礼,表示已成年。"}]}, {"meaning": "已经。", "cites": [{"t": "既来之,则安之。", "b": "《论语·季氏》"}, {"t": "既祖,取道。(祭过路神,就要上路。祖,临行祭路神,引申为饯行送别。)", "b": "《战国策·燕策》"}, {"t": "既克。", "b": "《左传·庄公十年》"}, {"t": "既其出。", "b": "宋·王安石《游褒禅山记》"}, {"t": "既加冠。", "b": "明·宋濂《送东阳马生序》"}, {"t": "既入宫中,举天下所贡…遍试之,无出其右者。", "b": "《聊斋志异·促织》"}, {"t": "既泣之三日。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "既成", "t": "已经完成"}, {"w": "既位", "t": "已就其位"}, {"w": "既醉以酒,既饱以德", "t": "宾客称主人优厚待客的客气话。"}]}, {"meaning": "不久;随即。", "cites": [{"t": "楚成王以商臣为太子,既欲置公子职。", "b": "《韩非子·内储说下》"}, {"t": "昔李斯与包丘子俱事荀卿,既而李斯入秦。", "b": "《盐铁论·毁学》"}]}, {"meaning": "常用“则”、“就”、“那么”相呼应,相当于“既然”。", "cites": [{"t": "既定策则仆须急归营。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "既要革命,就要有一个革命的党;既以", "t": "既然已经"}, {"w": "既不沙", "t": "既不阿,既不呵,既不唦,既不是呵,既不索。都表示:既然不是这样,如果不是这样,不然的话。"}]}, {"meaning": "跟“且”、“又”、“也”、“还”等词配合,表示同时具有两种情况。", "cites": [{"t": "屈平既嫉之。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "既高且大;既快又好;既坚持原则,又灵活运用", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1722wx','屋','1','wū','尸','9','','[{"pinyin": "wū", "defs": [{"meaning": "(屋的本义是幄,后来“屋”指房屋,另造“幄”字。会意。从尸,从至。尸,与房屋有关,“至”表示来到。人来到这里居住之意。本义:帐幕。“幄”的本字)。"}, {"meaning": "同本义。", "cites": [{"t": "屋,居也。", "b": "《说文》。徐灏曰:“古宫室无屋名。古之所谓屋,非今之所谓屋也。”"}, {"t": "尚不愧于屋漏。", "b": "《诗·大雅·抑》。传:“屋,小帐也。”"}, {"t": "去帝制黄屋左纛。", "b": "《汉书·南粤王佗传》"}, {"t": "去黄屋称制。", "b": "《汉书·陆贾传》。师古曰:“黄屋,谓车上盖也。”"}], "words": [{"w": "屋幕", "t": "帐幕"}, {"w": "屋漏", "t": "古代室内西北隅施设小帐,安插神主,为人所不见的地方。"}]}, {"meaning": "古代半地穴式住室建筑的顶部覆盖。", "cites": [{"t": "是故十围之木,持千钧之屋。", "b": "《淮南子》"}]}, {"meaning": "房舍,房屋。", "cites": [{"t": "以二人居屋十间。", "b": "洪亮吉《治平篇》"}, {"t": "卷我屋上三重茅。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "屋山", "t": "屋脊"}, {"w": "屋山头", "t": "堂屋两端的房檐"}, {"w": "屋桷", "t": "房屋上的椽子"}, {"w": "屋里巷", "t": "家里"}, {"w": "屋除", "t": "阶下,房舍前的台阶"}, {"w": "屋庑", "t": "房子的顶部"}, {"w": "屋头", "t": "房屋的上面"}, {"w": "屋庐", "t": "泛指居室"}, {"w": "屋盖", "t": "屋顶"}, {"w": "屋壁", "t": "房屋的夹墙"}, {"w": "屋基", "t": "房屋的地基"}, {"w": "屋山头", "t": "屋山。指屋脊或山墙"}, {"w": "屋上乌", "t": "屋上的乌鸦。指推爱之所及。"}]}, {"meaning": "室深处。", "cites": [{"t": "屋,奥也。其中温奥也。", "b": "《释名》"}]}, {"meaning": "车盖,车篷子。", "cites": [{"t": "纪信乘黄屋车。", "b": "《史记》"}]}, {"meaning": "终止。", "cites": [{"t": "李纲用之于靖康而宋社屋。", "b": "沈德符《万历野荻编》"}]}, {"meaning": "建屋,盖屋。", "cites": [{"t": "是故丧国之社屋之,不受天阳也。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1723wx','昼','1','zhòu','日','9','','[{"pinyin": "zhòu", "defs": [{"meaning": "(会意。从日,从畫(画)省。从日,表示太阳。从畫,表示一种界限。本义:白天。与“夜”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "昼,明也。日之出入,与夜为介。", "b": "《说文》"}, {"t": "昼者,阳。", "b": "《周髀算经》"}, {"t": "昼夜之象也。", "b": "《易·系辞》。注:“乾为昼。”"}, {"t": "横柯上蔽,在昼犹昏。", "b": "吴均《与朱元思书》"}], "words": [{"w": "昼日昼夜", "t": "日日夜夜"}, {"w": "昼夕", "t": "日夜"}, {"w": "昼眠", "t": "白天睡眠;午睡"}, {"w": "昼锦", "t": "衣锦昼行的省称,称富贵还乡"}, {"w": "昼暮", "t": "日夜"}, {"w": "昼宵", "t": "白昼与黑夜"}, {"w": "昼景", "t": "白昼的日光"}, {"w": "昼伏", "t": "白天隐蔽不动。"}]}, {"meaning": "古地名 。在今山东省淄博市临淄西北。", "cites": [{"t": "孟子去齐,宿于昼。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1724wx','屏','1','píng bǐng bīng','尸','9','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从尸,并声。这里的“尸”是由“广”(yǎn)演变来的,表示与宫室有关的事物。本义:宫殿当门的小墙。又称“照壁”)。"}, {"meaning": "同本义。", "cites": [{"t": "屏,屏蔽也。", "b": "《说文》"}, {"t": "天子在外屏,诸侯在内屏。", "b": "《荀子·大略》"}, {"t": "其社盖于周之屏。", "b": "《吕氏春秋·贵直》"}, {"t": "天子外屏,诸侯内屏。", "b": "《荀子·大路》"}], "words": [{"w": "屏室", "t": "犹言幽深之室。"}]}, {"meaning": "屏风。室内陈设,用以挡风或遮蔽的器具,上面常有字画。", "cites": [{"t": "屏摄之位。", "b": "《国语·楚语下》。注:“屏,屏风也。”"}, {"t": "撤屏视之,一人、一桌、一椅、一扇、一抚尺而已。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "屏围", "t": "屏风"}, {"w": "屏扆", "t": "宫殿上陈设在窗与门户间画有斧形图案的屏风"}, {"w": "屏山", "t": "如屏之山;指屏风"}, {"w": "屏户", "t": "门屏"}, {"w": "屏风儿", "t": "指诏书的草稿格式"}, {"w": "屏室", "t": "幽深之室"}, {"w": "屏著", "t": "指门屏"}, {"w": "屏帐", "t": "室中张设的帷帐"}, {"w": "屏帷", "t": "指内室。"}]}, {"meaning": "屏障之物。", "cites": [{"t": "大邦维屏,大宗惟翰。", "b": "《诗·大雅·板》"}, {"t": "皆正设于屏外。", "b": "《淮南子·时则》"}, {"t": "三镇国之屏蔽,割之何以立国。", "b": "《宋史·李纲传》"}], "words": [{"w": "屏翳", "t": "神话中的风神"}, {"w": "屏插", "t": "笔筒"}, {"w": "屏门", "t": "屏风"}, {"w": "屏泥", "t": "车轼前的装饰。亦用以遮挡泥土"}, {"w": "屏星", "t": "车前用以蔽尘的车挡"}, {"w": "屏面", "t": "古代的一种扇子,用以遮面。"}]}]}, {"pinyin": "bǐng", "defs": [{"meaning": "退避;隐退。", "cites": [{"t": "侯生乃屏人间语。", "b": "《史记·魏公子列传》"}], "words": [{"w": "屏居", "t": "辞官隐居,不问世事"}, {"w": "屏语", "t": "避开他人,私下交谈"}, {"w": "屏伏", "t": "隐退,避匿"}, {"w": "屏移", "t": "退隐。"}]}, {"meaning": "隐藏。", "cites": [{"t": "尔不许我,我乃屏璧与圭。", "b": "《书·金縢》"}], "words": [{"w": "屏匿", "t": "隐藏"}, {"w": "屏迹", "t": "隐避"}, {"w": "屏藏", "t": "隐藏。"}]}, {"meaning": "抑制。抑止不出气。", "cites": [{"t": "宋将军屏息观之。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "屏息", "t": "止住声息。即屏气"}, {"w": "屏气", "t": "暂时抑制呼吸。"}]}, {"meaning": "掩蔽。", "cites": [{"t": "屏王耳目,使不聪明。", "b": "《左传·昭公二十七年》"}], "words": [{"w": "屏处", "t": "隐蔽之处"}, {"w": "屏遮", "t": "遮蔽。"}]}]}, {"pinyin": "bīng", "defs": [{"meaning": "作谦词用于信札中,意为惶恐"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1725wx','屎','1','shǐ','尸','9','','[{"pinyin": "shǐ", "defs": [{"meaning": "大便，粪。", "words": [{"w": "屎盆子", "t": "[方言]比喻恶名或坏事。"}, {"w": "屎蜣螂", "t": "[方言]蜣螂。一种吃屎和动物尸体的黑甲虫。"}, {"w": "屎溺", "t": "粪和尿"}]}, {"meaning": "眼、耳所分泌的东西", "words": [{"w": "眼屎", "t": ""}, {"w": "耳屎", "t": ""}]}, {"meaning": "嘲笑低能的", "words": [{"w": "屎棋", "t": "低劣的棋艺"}, {"w": "屎诗", "t": "低劣的诗句"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1726wx','费','1','fèi','贝','9','','[{"pinyin": "fèi", "defs": [{"meaning": "(形声。从贝,弗声。从“贝”表示与钱财有关。本义:花费 )。"}, {"meaning": "同本义。", "cites": [{"t": "费,散财用也。", "b": "《说文》"}, {"t": "费,耗也。", "b": "《广雅》"}, {"t": "非爱其费也。", "b": "《吕氏春秋·安死》。注:“财也。”"}, {"t": "君子惠而不费。", "b": "《论语·尧曰》"}, {"t": "上不费粟,民不慢农。", "b": "《商君书·垦令》"}], "words": [{"w": "费耗", "t": "费用"}, {"w": "费钞", "t": "花费钱钞"}, {"w": "费钞费贯", "t": "耗贯钱财"}, {"w": "费出", "t": "花费,支出。"}]}, {"meaning": "耗损。", "cites": [{"t": "费神伤魂。", "b": "《吕氏春秋·禁塞》"}, {"t": "伤形费神。", "b": "《墨子·所染》"}, {"t": "用咫尺之木,不费一朝之事。", "b": "《韩非子·外储说左上》"}], "words": [{"w": "费眼", "t": "耗损眼力"}, {"w": "费讲", "t": "费唇舌;难以说解"}, {"w": "费想", "t": "费心,劳神"}, {"w": "费损", "t": "耗费,耗损。"}]}, {"meaning": "浪费。", "cites": [{"t": "国侈则用费,用费则民贫。", "b": "《管子·八观》"}], "words": [{"w": "费资", "t": "挥霍钱财"}, {"w": "费设", "t": "在供设方面花费多"}, {"w": "费捐", "t": "耗费。"}]}, {"meaning": "(fú)。逆,违背。", "cites": [{"t": "君子之道费而隐。", "b": "《礼记·中庸》"}], "words": [{"w": "费民", "t": "违背民意,违逆民心。"}]}, {"meaning": "钱财;费用。", "cites": [{"t": "秦无亡矢遗镞之费。", "b": "汉·贾谊《过秦论》"}, {"t": "求脱械居监外板屋费亦数十金。", "b": "清·方苞《狱中杂记》"}, {"t": "老爷断一千也可,五百也可,与冯家作烧埋之费。", "b": "《红楼梦》"}], "words": [{"w": "道路通行费;报名费;学费;手续费;诊费", "t": ""}]}, {"meaning": "古地名 。在今山东省鱼台县西南。"}, {"meaning": "(bèi)。谬误。", "cites": [{"t": "战而死,而子愠,而犹欲粜,籴仇则愠也,岂不费哉?", "b": "《墨子·鲁问》"}], "words": [{"w": "口费", "t": "因说话不当发生的错误。"}]}, {"meaning": "语句多余,言辞烦琐。", "cites": [{"t": "不辞费。", "b": "《礼记·曲礼上》"}], "words": [{"w": "费名", "t": "多余无用的文句"}, {"w": "费辞", "t": "多费言词;饶舌"}, {"w": "费言", "t": "多余的话。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1727wx','陡','1','dǒu','阝','9','','[{"pinyin": "dǒu", "defs": [{"meaning": "(形声。从阜,走声。从“阜”,表示与地形地势的高低上下有关。本义:山势陡峭) 同本义 。坡度大,近于垂直。", "cites": [{"t": "陡,峻立也。", "b": "《集韵》"}, {"t": "塞者凿之,陡者级之。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "陡山;山陡路险;陡直", "t": "山势峻峭壁立"}, {"w": "陡崖", "t": "陡峭的山崖。"}]}, {"meaning": "程度深,范围广。", "cites": [{"t": "曾经消瘦,每遍犹闲,这番最陡。", "b": "元·王实甫《西厢记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1728wx','逊','1','xùn','辶','9','','[{"pinyin": "xùn", "defs": [{"meaning": "(形声。从辵(chuò),孙声。本义:逃遁)。"}, {"meaning": "同本义。", "cites": [{"t": "遜,遁也。", "b": "《说文》"}, {"t": "吾家耄逊于荒。", "b": "《书·微子》"}, {"t": "是以耆儒硕老,抱其书而远逊。", "b": "汉·扬雄《剧秦美新》"}], "words": [{"w": "逊郊", "t": "天子逃遁于荒野。"}]}, {"meaning": "辞让;退让。", "cites": [{"t": "将逊于位。", "b": "《书·尧典序》"}, {"t": "用率我唐典,敬逊尔位。", "b": "《三国演义》"}, {"t": "以其逊职,是有进阶,式从彝序,无替成命。", "b": "唐·常衮《授李抱玉》"}, {"t": "心想挑了个斜岔儿,把大家逊出去就完了事了。", "b": "《儿女英雄传》"}], "words": [{"w": "逊受", "t": "谦让着接受"}, {"w": "逊辞", "t": "辞让;推辞"}, {"w": "唐尧逊位;逊国", "t": "让国"}, {"w": "逊迹", "t": "退避;隐居"}, {"w": "逊坐", "t": "让坐。"}]}, {"meaning": "谦逊;恭顺。", "cites": [{"t": "五品不逊。", "b": "《虞书》"}, {"t": "危行言逊。", "b": "《论语》。集解:“顺也。”"}, {"t": "辞令逊敏。", "b": "《吕氏春秋·士容》"}, {"t": "与其不逊也宁固。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "逊谢", "t": "恭敬和辞谢"}, {"w": "逊让", "t": "谦虚退让"}, {"w": "逊弟", "t": "敬顺兄长"}, {"w": "逊服", "t": "顺从;服从。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1729wx','眉','1','méi','目','9','','[{"pinyin": "méi", "defs": [{"meaning": "(象形。甲骨文,小篆字形。象目上毛形。本义:眉毛)。"}, {"meaning": "眼上方的弓或嵴,亦指生长在这条嵴上的眉毛。", "cites": [{"t": "眉,目上毛也。", "b": "《说文》"}, {"t": "螓首蛾眉。", "b": "《诗·卫风·硕人》"}, {"t": "报答平生未展眉。", "b": "元稹《遗悲怀》"}], "words": [{"w": "眉心", "t": "双眉之间"}, {"w": "眉间广尺", "t": "两眉间隔宽有一尺,表示人的相貌奇特"}, {"w": "眉泉", "t": "眉头"}, {"w": "眉寸", "t": "双眉之间"}, {"w": "眉下添眉", "t": "比喻重复、多余"}, {"w": "眉弓", "t": "额下长眉毛处突出如弓形的部位"}, {"w": "眉尖", "t": "双眉附近处"}, {"w": "眉柳", "t": "细长如柳叶的眉"}, {"w": "眉脚", "t": "眉梢。"}]}, {"meaning": "借指美女。", "cites": [{"t": "眉,媚也,有妩媚也。", "b": "《释名》"}, {"t": "下眉近戚。", "b": "《仲定碑》"}], "words": [{"w": "眉清目秀,眉目如画", "t": "形容容貌俊美清秀,借指美女。"}]}, {"meaning": "古州名 。故地在今四川省眉山县。"}, {"meaning": "老。", "cites": [{"t": "眉,老也。", "b": "《方言一》"}, {"t": "以介眉寿。", "b": "《诗·豳风·七月》"}], "words": [{"w": "眉寿", "t": "长寿"}, {"w": "眉耇", "t": "高寿,长寿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1730wx','孩','1','hái','子','9','','[{"pinyin": "hái", "defs": [{"meaning": "(形声。从子,亥声。本义:小儿笑)。"}, {"meaning": "同本义。同“咳”。", "cites": [{"t": "咳,小儿笑也。", "b": "《说文》。古文咳从子。内则,孟子则作此字。"}, {"t": "孤女藐焉始孩。", "b": "潘岳《寡妇赋》"}], "words": [{"w": "未孩", "t": "还不会笑。"}]}, {"meaning": "当作婴儿看待。", "cites": [{"t": "圣人在天下,歙歙为天下浑其心,百姓皆注其耳目,圣人皆孩之。", "b": "《老子》"}]}, {"meaning": "抚爱。", "cites": [{"t": "伏惟陛下,昧旦坐朝,留心政术,明罚以纠诸侯,申恩以孩百姓。", "b": "《北齐书》"}]}, {"meaning": "幼小;幼稚。", "cites": [{"t": "孩,少也。", "b": "《广雅》"}, {"t": "忆昔十五心尚孩。", "b": "杜甫《百忧集行》"}], "words": [{"w": "孩赤无知", "t": "年幼无知"}, {"w": "孩幼", "t": "幼儿"}, {"w": "孩抱", "t": "幼小"}, {"w": "孩乳", "t": "幼小"}, {"w": "孩婴", "t": "幼小。"}]}, {"meaning": "幼儿。", "cites": [{"t": "孩,始生小儿。", "b": "《广韵》"}, {"t": "孩提,二三岁之间在襁褓,知孩笑可提抱者也。", "b": "《孟子·尽心上》注"}, {"t": "生孩六月,慈父见背。", "b": "李密《陈情表》"}], "words": [{"w": "孩中颜", "t": "幼儿的面色"}, {"w": "孩幼", "t": "幼儿"}, {"w": "孩儿", "t": "幼儿"}, {"w": "孩稚", "t": "幼儿"}, {"w": "孩婴", "t": "幼儿。"}]}, {"meaning": "未成年的人;孩子。", "cites": [{"t": "纣为孩子时,微子诸其不善之性。", "b": "《论衡·本性》"}], "words": [{"w": "孩提赤子初心", "t": "孩子的纯洁之心"}, {"w": "孩子的房儿", "t": "衣胞"}, {"w": "孩气", "t": "孩子般的脾气或神态"}, {"w": "男孩;女孩;天生自诩是天才,也把天才奖妇孩", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1731wx','陨','1','yǔn','阝','9','','[{"pinyin": "yǔn", "defs": [{"meaning": "(形声。从阜(fù),员声。“阜”指土山,与“高下”义有关。本义:从高处掉下,坠落)。"}, {"meaning": "同本义。", "cites": [{"t": "陨,从高下也。", "b": "《说文》"}, {"t": "陨,坠也。", "b": "《尔雅》"}, {"t": "陨,落也,堕也。", "b": "《玉篇》"}, {"t": "冬十二月陨霜不杀菽。", "b": "《韩非子·内储说上》"}, {"t": "其黄而陨。", "b": "《诗·卫风·氓》"}, {"t": "涕既陨之。", "b": "《诗·小雅·小弁》"}, {"t": "并、汾乔木,望秋先陨。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "启陨箨。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "陨坠", "t": "坠落"}, {"w": "陨泗", "t": "流泪"}, {"w": "陨涕", "t": "落泪"}, {"w": "陨集", "t": "下落聚集。"}]}, {"meaning": "丧失,失去。", "cites": [{"t": "天诱其衷,成王陨命,穆公是以不克逞志于我。", "b": "《左传·成公十三年》"}, {"t": "陨子辱矣。", "b": "《左传·成公二年》"}, {"t": "而陨失其国者。", "b": "《晏子春秋·内篇问上》"}], "words": [{"w": "陨获", "t": "困迫失志"}, {"w": "陨命", "t": "丧失生命"}, {"w": "陨失", "t": "丧失;失落"}, {"w": "陨职", "t": "失职。"}]}, {"meaning": "死。", "cites": [{"t": "巢陨诸樊。", "b": "《左传·襄公三十一年》"}, {"t": "则陨身灭国矣。", "b": "《韩非子·说疑》"}, {"t": "如何不吊,事临垂克,遘疾陨丧!", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "陨殁", "t": "死亡"}, {"w": "陨丧", "t": "死亡"}, {"w": "陨谢", "t": "死的婉词"}, {"w": "陨隧", "t": "死亡的婉称"}, {"w": "陨国", "t": "殉国,为国而死"}, {"w": "陨世", "t": "逝世。"}]}, {"meaning": "毁坏。", "cites": [{"t": "世济其美,不陨其名。", "b": "《史通》"}], "words": [{"w": "陨圮", "t": "倒塌崩坏"}, {"w": "陨绝", "t": "毁灭;灭绝"}, {"w": "陨覆", "t": "覆灭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1732wx','除','1','chú','阝','9','','[{"pinyin": "chú", "defs": [{"meaning": "(形声。从阜,余声。从“阜”,表示与地形地势的高低上下有关。本义:宫殿的台阶)。"}, {"meaning": "同本义。", "cites": [{"t": "除,殿阶也。", "b": "《说文》。按,阶级如山石之高下,故从阜。"}, {"t": "自前殿南下椒除。", "b": "《汉书·王莽传》"}, {"t": "登自东除。", "b": "张衡《东京赋》"}, {"t": "苔痕上除绿,草色入帘青。", "b": "刘禹锡《陋室铭》"}]}, {"meaning": "一般建筑的台阶。", "cites": [{"t": "扶辇下除,触柱折辕。", "b": "《汉书·李广苏建传》"}]}, {"meaning": "泛指台阶。", "cites": [{"t": "听事前除,雨后犹湿。", "b": "《世说新语·政事》"}, {"t": "除谓之阶。", "b": "宋·李诫《营造法式》"}]}, {"meaning": "拜受官位。", "cites": [{"t": "初除之官。", "b": "《汉书·景帝纪》。注:“凡言除者,除故官就新官也。”"}, {"t": "予除右丞相兼柩密使,都督诸路军马。", "b": "文天祥《指南录后序》"}], "words": [{"w": "除授", "t": "授予"}, {"w": "除召", "t": "为任官而被召"}, {"w": "除官", "t": "授官,除去旧职以任新职。"}]}, {"meaning": "清除,去掉。", "cites": [{"t": "除恶务本。", "b": "《书·泰誓》"}, {"t": "然则将军之仇报,而燕国见陵之耻除矣。", "b": "《战国策·燕策》"}], "words": [{"w": "根除", "t": "彻底铲除"}, {"w": "除恶务尽", "t": "清除邪恶势力,务必彻底"}, {"w": "消除", "t": "使不存在,除去。"}]}, {"meaning": "修治、修整。", "cites": [{"t": "郡之贤士大夫请于当道,即除魏阉废祠之址以葬之。", "b": "张溥《五人墓碑记》"}]}, {"meaning": "打扫。", "cites": [{"t": "由帅其属而修除。", "b": "《周礼·典祀》"}], "words": [{"w": "除舍", "t": "打扫房舍"}, {"w": "除宫", "t": "打扫宫殿。比喻宫廷更换主人。"}]}, {"meaning": "诛灭。", "cites": [{"t": "诛乱除害。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "除残祛暴", "t": "驱除残暴邪恶势力。"}]}, {"meaning": "不计算在内。", "cites": [{"t": "而今已矣!除吾死外,当无见期。", "b": "袁枚《祭妹文》"}], "words": [{"w": "除他以外,我都认识", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1733wx','险','1','xiǎn','阝','9','','[{"pinyin": "xiǎn", "defs": [{"meaning": "(形声。从阜,佥(qiàn)声。从“阜”,与地势有关。本义:地势高低悬殊,难以通过)。"}, {"meaning": "同本义。", "cites": [{"t": "险,阻难也。", "b": "《说文》"}, {"t": "军旅思险。", "b": "《礼记·少仪》"}, {"t": "毕力平险。", "b": "《列子·汤问》"}, {"t": "苟有险,余必下推车。", "b": "《左传·成公二年》"}, {"t": "地险,山川丘陵也。", "b": "《易·坎》"}, {"t": "险以远。", "b": "宋·王安石《游褒禅山记》"}, {"t": "常石险远。", "b": ""}], "words": [{"w": "险瘠", "t": "艰险贫瘠"}, {"w": "险易", "t": "艰险与平坦之地"}, {"w": "险戏", "t": "艰险。"}]}, {"meaning": "地势险峻、危险。", "cites": [{"t": "不登险峰,不识天地的辽阔。", "b": "碧野《富春江畔》"}, {"t": "巴、蜀道险,秦之迁人皆居蜀。", "b": "《史记·项羽本纪》"}], "words": [{"w": "险要;险峰;险特", "t": "高峻挺立"}, {"w": "险坂", "t": "陡峭的山坡"}, {"w": "险栈", "t": "险峻的栈道。"}]}, {"meaning": "地势不平。", "cites": [{"t": "苟有险,余必下推车。", "b": "《左传·成公二年》"}], "words": [{"w": "履险如夷", "t": "夷:平;险:不平。"}]}, {"meaning": "邪恶。", "cites": [{"t": "以险徼幸者,其求无厌,偏重必离。", "b": "《左传》"}], "words": [{"w": "险诐", "t": "邪佞不正"}, {"w": "险谲", "t": "邪恶奸诈"}, {"w": "险巧", "t": "奸邪巧诈。"}]}, {"meaning": "艰难;困难。", "cites": [{"t": "安利者常乐易,危害者常忧险。", "b": "《荀子·荣辱》"}]}, {"meaning": "奇特,怪异。", "cites": [{"t": "显县帛十匹,约曰:“险衣来者以赏之。”", "b": "《南史·周弘正传》"}], "words": [{"w": "险衣", "t": "奇异的服装"}, {"w": "险妆", "t": "怪异的妆扮。"}]}, {"meaning": "阴险,难以揣测。", "cites": [{"t": "[潘夫人]性险妒容媚,自始至卒,潜害袁夫人等甚众。", "b": "《三国志·吴志》"}, {"t": "心计险极。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "险怪", "t": "险恶怪诞"}, {"w": "险汙", "t": "险诈恶浊"}, {"w": "险谒", "t": "不正当的请托"}, {"w": "险奸", "t": ""}]}, {"meaning": "危险。", "cites": [{"t": "至险绝处。", "b": "《徐霞客游记·游黄山记》"}, {"t": "涉险而不伤。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "险段", "t": "危险的地段"}, {"w": "险束", "t": "危险狭窄"}, {"w": "险危", "t": "危险。"}]}, {"meaning": "要隘,险要的地带。", "cites": [{"t": "入险而脱。", "b": "《左传·僖公三十三年》"}, {"t": "此为长江之险已与我共之矣。", "b": "《资治通鉴·赤壁之战》"}, {"t": "山溪之险。", "b": "《孟子·公孙丑下》"}, {"t": "国险而民附。", "b": "《三国志·诸葛亮传》"}, {"t": "益州险塞。", "b": ""}, {"t": "险易远近。", "b": "《资治通鉴·唐纪》"}, {"t": "险战之法,一车当兵卒四十人,四十人当一车。", "b": "《六韬·均兵》"}], "words": [{"w": "天险;山险;探险;凭险;无险可守;险战", "t": "险要之地的战斗。"}]}, {"meaning": "道路。", "cites": [{"t": "君子居易以俟命,小人行险以徼幸。", "b": "《礼记·中庸》。郑玄注:“险谓倾危之道”"}]}, {"meaning": "防御工事。", "cites": [{"t": "王公设险以守其国。", "b": "《易·坎》"}], "words": [{"w": "天险", "t": "天然的防御屏障。"}]}, {"meaning": "差一点。", "cites": [{"t": "险把哥儿头打破了,如今扎着绢子还没好。", "b": "《续金瓶梅》"}], "words": [{"w": "险不", "t": "差一点"}, {"w": "险些掉进河里;险些忘了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1734wx','院','1','yuàn','阝','9','','[{"pinyin": "yuàn", "defs": [{"meaning": "(形声。从阜(fù),完声。“阜”是土山,与土、建筑有关。本义:庭院,院子。房屋围墙以内的空地)。"}, {"meaning": "同本义。", "cites": [{"t": "院,垣也。", "b": "《广雅》"}, {"t": "院,周垣也。", "b": "《玉篇》"}, {"t": "有垣墙者曰院。", "b": "《增韵》"}, {"t": "深院月明人静。", "b": "汉·司马光《西江月》"}], "words": [{"w": "前院;后院;深宫大院", "t": ""}]}, {"meaning": "四周有墙垣围绕、自成部分的房屋。", "cites": [{"t": "院东五里。", "b": "宋·王安石《游褒禅山记》"}, {"t": "院僧夜闻大呼。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "驰往油画院。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "画院", "t": "书院。"}]}, {"meaning": "林园。", "cites": [{"t": "试茗蜀井冈,看花竹西院。", "b": "柳贯《送郭子昭经历赴淮东诗》"}]}, {"meaning": "官署。", "cites": [{"t": "早晨七点钟上院,九点下来。", "b": "《官场现形记》"}], "words": [{"w": "殿院;枢密院;行政院;院上行知", "t": "保举已得朝廷批准,由巡抚衙门通知本人的文书"}, {"w": "院君", "t": "有封号的妇人;亦尊称官吏,财主之妻"}, {"w": "院长", "t": "宋朝指军吏节级。后来也称衙门中的公人"}, {"w": "院子家", "t": "给皇帝传递饮食的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1735wx','娃','1','wá','女','9','','[{"pinyin": "wá", "defs": [{"meaning": "(形声。从女,圭(guī)声。本义:美女)。"}, {"meaning": "同本义。", "cites": [{"t": "娃,美也。吴楚衡淮之间曰娃。吴有馆娃之宫。", "b": "《方言》二"}], "words": [{"w": "娃姣", "t": "美女"}, {"w": "娃馆", "t": "宫女的馆舍"}, {"w": "娃儿", "t": "美貌女郎。"}]}, {"meaning": "少女;姑娘。", "cites": [{"t": "邻娃尽著绣裆襦,独自提筐采蚕叶。", "b": "陆龟蒙《陌上桑》"}]}, {"meaning": "儿子或女儿。有亲昵意。", "cites": [{"t": "这该是德顺的娃吧?叫什么名?", "b": "水华、王大化等《惯匪周子山》"}]}, {"meaning": "圜深目的样子。", "cites": [{"t": "娃,圜深目貌。", "b": "《说文》"}]}, {"meaning": "字亦作眭。", "cites": [{"t": "眭,深目也。", "b": "《说文新附》"}]}, {"meaning": "美好。", "cites": [{"t": "吴、楚之间谓好曰娃。", "b": "《说文》"}], "words": [{"w": "娃鬟", "t": "美丽的发髻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1736wx','姥','1','lǎo mǔ','女','9','','[{"pinyin": "lǎo", "defs": [{"meaning": "即母亲的母亲的尊称。", "words": [{"w": "姥姥", "t": "外祖母;对年老妇人的尊称。"}]}]}, {"pinyin": "mǔ", "defs": [{"meaning": "(形声。从女,老声。本义:老年妇女的俗称)。"}, {"meaning": "同本义。", "cites": [{"t": "姥,老母,或作姆,女师也。", "b": "《广韵》"}, {"t": "又尝在蕺山见一老姥。", "b": "《晋书·王羲之传》"}, {"t": "未至十余里,有一客姥,居店卖食。", "b": "《世说新语》"}], "words": [{"w": "姥姥", "t": "称年老女仆。"}]}, {"meaning": "婆,丈夫的母亲。", "cites": [{"t": "便可白公姥。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "公死姥更嫁,孤儿甚可怜。", "b": "《乐府诗集·瑯琊王歌辞》"}], "words": [{"w": "公姥", "t": "公公与婆婆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1737wx','姨','1','yí','女','9','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从女,夷声。本义:妻子的姐妹)。"}, {"meaning": "同本义。", "cites": [{"t": "姨,妻之女弟同出为姨。", "b": "《说文》"}, {"t": "妻之姊妹同出为姨。", "b": "《尔雅》"}, {"t": "蔡哀侯曰吾姨也。", "b": "《左传·庄公十年》"}, {"t": "东宫之妹,邢侯之姨。", "b": "《诗·卫风·硕人》。毛传:“妻之姊妹曰姨。”"}, {"t": "其妻又吾姨也。", "b": "晋·潘安《寡妇赋》"}], "words": [{"w": "姨夫", "t": "妻的姊妹夫;又两男共狎一妓,彼此互称姨夫。"}]}, {"meaning": "母之姊妹。", "cites": [{"t": "继室以其侄,穆姜之姨子也。", "b": "《左传》。孔颖达疏:“据父言之,谓之姨,据子言之,当谓之从母,但子效父语,亦呼为姨。”"}], "words": [{"w": "姨丈人", "t": "妻之姨夫"}, {"w": "姨弟", "t": "姨表弟。"}]}, {"meaning": "父亲的小老婆;庶母。", "cites": [{"t": "母之姊妹曰姨。", "b": "《释名》"}, {"t": "其父之侧庶,亦称姨者,姨本姊妹同事一夫之称,后世无媵之礼,而侧庶实与媵比,故虽非母姊妹,而得借比称之。", "b": "翟灏《通俗篇》"}], "words": [{"w": "姨姨", "t": "称父之妾;称所亲狎的妓女"}, {"w": "姨夫钱", "t": "可供循环挪用的他人的钱财。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1738wx','姻','1','yīn','女','9','','[{"pinyin": "yīn", "defs": [{"meaning": "(会意兼形声。从女,从因,因亦声。本义:女婿家)。"}, {"meaning": "同本义 。结亲的男家,指夫或夫之父。", "cites": [{"t": "姻,婿家也,女之所因,故曰姻。从女,从因,因亦声。", "b": "《说文》"}, {"t": "婿之父为姻。又,婿之党为姻兄弟。", "b": "《尔雅》"}, {"t": "不思旧姻。", "b": "《诗·小雅·我行其野》"}, {"t": "琐琐姻亚。", "b": "《诗·小雅·节南山》"}, {"t": "某以得外昏姻。", "b": "《仪礼·士昏礼记》"}, {"t": "昏媾姻娅。", "b": "《左传·昭公二十五年》。注:“壻父曰姻,两壻相谓曰亚。”"}, {"t": "皆弦姻也。", "b": "《左传·僖公五年》"}], "words": [{"w": "姻母", "t": "对兄弟妻之母、姐妹夫之母以及疏亲前辈之妻的称呼。"}]}, {"meaning": "妻或妻之父。", "cites": [{"t": "昏姻之礼。", "b": "《礼记》。郑玄注:“婿曰昏,妻曰姻。”"}], "words": [{"w": "姻翁", "t": "亲家公。儿子的丈人或女儿的公公"}, {"w": "姻臣", "t": "帝王的外戚"}, {"w": "姻母", "t": "姻伯母。对兄弟妻之母、姐妹夫之母的称呼。"}]}, {"meaning": "姻亲。", "cites": [{"t": "泾阳之妻,则洞庭君之爱女也。淑性茂质,为九姻所重。", "b": "《太平广记》引《异闻集》"}], "words": [{"w": "姻绱", "t": "姻亲;亲戚"}, {"w": "姻妾", "t": "姻亲的婢妾"}, {"w": "姻里", "t": "帝王的姻戚"}, {"w": "姻昵", "t": "近的姻亲"}, {"w": "姻通", "t": "姻亲之谊"}, {"w": "姻族", "t": "有姻亲关系的各家族或其成员"}, {"w": "姻丧", "t": "外亲之丧"}, {"w": "姻连", "t": "姻戚,姻眷,姻媛,姻援,姻私,姻亚,姻好,姻媾,姻懿。都指姻亲"}, {"w": "姻家", "t": "联姻的家族或其成员"}, {"w": "姻兄", "t": "姻亲中同辈弟兄的互称。"}]}, {"meaning": "婚姻。", "cites": [{"t": "源频叨诸府戎禁,预班通彻而托姻结,唯利是求。", "b": "《文选·沈约·奏弹王源》"}], "words": [{"w": "姻缘辐辏", "t": "形容男女结成夫妻从各方面来说都很合适。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1739wx','娇','1','jiāo','女','9','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从女,乔声。本义:妩媚可爱)。"}, {"meaning": "同本义(柔嫩美态)。", "cites": [{"t": "娇,姿也。", "b": "《说文新附》"}, {"t": "娇,女字,亦态。", "b": "《广韵》"}, {"t": "娇,娇姿也。", "b": "《玉篇》"}, {"t": "娇逸未有婚。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "自在娇莺恰恰啼。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "娇儿恶卧踏里裂。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "娇姿欲滴。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "娇影", "t": "娇美动人的影子"}, {"w": "娇娇痴痴", "t": "故作娇痴之态"}, {"w": "娇婢侈童", "t": "娇贵奢侈的婢女童仆"}, {"w": "娇羞", "t": "妩媚含羞的样子"}, {"w": "娇娥", "t": "美丽的妇女"}, {"w": "娇逸", "t": "俊美飘逸"}, {"w": "娇颜", "t": "美丽的容貌"}, {"w": "娇冶", "t": "艳丽"}, {"w": "娇慵", "t": "娇懒;精神不振"}, {"w": "娇奶奶", "t": "娇惰的富家妇人"}, {"w": "娇懒", "t": "懒散倦怠"}, {"w": "娇喘", "t": "娇柔嫩细的喘声"}, {"w": "娇喉", "t": "柔美的歌喉"}, {"w": "娇语", "t": "柔声细语"}, {"w": "娇脆", "t": "嫩脆"}, {"w": "娇狞", "t": "婉转而细弱。"}]}, {"meaning": "柔弱。", "cites": [{"t": "侍儿扶起娇无力。", "b": "唐·白居易《长恨歌》"}], "words": [{"w": "娇怯", "t": "柔美;柔弱"}, {"w": "娇妍", "t": "柔美"}, {"w": "娇荑", "t": "喻柔嫩纤细的手指"}, {"w": "娇怯怯", "t": "柔弱的样子。"}]}, {"meaning": "任性。", "cites": [{"t": "小姐,你性儿忒惯得娇了。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "对儿童的称谓。", "cites": [{"t": "夜相思,投壶不停箭,忆欢作娇时。", "b": "《乐府诗集》"}]}, {"meaning": "爱;宠爱。", "cites": [{"t": "平生所娇儿,颜色白胜雪。", "b": "杜甫《北征》"}], "words": [{"w": "娇娃", "t": "娇生惯养的小孩;美女"}, {"w": "娇饶", "t": "娇生惯养"}, {"w": "娇怜", "t": "宠爱怜惜"}, {"w": "娇饶", "t": "娇纵;娇宠"}, {"w": "娇痴", "t": "天真可爱"}, {"w": "娇爱", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1740wx','姚','1','yáo','女','9','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。从女,兆声。本义:姓) 同本义。相传为虞舜之后。", "cites": [{"t": "姚,虞舜居姚虚,因以为姓。", "b": "《说文》。按,母名握登。大荒南经,帝俊妻娥皇,生此三身之国,姚姓。"}]}, {"meaning": "长。", "cites": [{"t": "其功盛姚远矣!", "b": "《荀子·荣辱》"}, {"t": "雅声远姚。", "b": "《汉书·礼乐志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1741wx','娜','1','nà nuó','女','9','','[{"pinyin": "nà", "defs": [{"meaning": "(形声。从女,那声(nuó)。本义:婀娜,美貌) ——女子人名用字。", "cites": [{"t": "娜,女字。", "b": "《集韵》"}]}]}, {"pinyin": "nuó", "defs": [{"meaning": "——“婀娜”(ē\'nuó)形容姿态柔美。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1742wx','怒','1','nù','心','9','','[{"pinyin": "nù", "defs": [{"meaning": "(形声。从心,奴声。本义:发怒,明显地表形于外的生气)。"}, {"meaning": "同本义。", "cites": [{"t": "怒,恚也。", "b": "《说文》"}, {"t": "怨而不怒。", "b": "《国语·周语》"}, {"t": "薄言往愬,逢彼之怒。", "b": "《诗·邶风·柏舟》"}, {"t": "驴不胜怒。", "b": "唐·柳宗元《三戒》"}, {"t": "吏呼一何怒。", "b": "唐·杜甫《石壕吏》"}, {"t": "王怒。", "b": "晋·干宝《搜神记》"}]}, {"meaning": "又。", "cites": [{"t": "瞋目大怒。", "b": ""}], "words": [{"w": "怒烘烘", "t": "怒哄哄,怒叿叿,怒吽吽。怒气冲冲的样子"}, {"w": "怒恶", "t": "嘖怒,发恨"}, {"w": "怒心", "t": "愤怒之心"}, {"w": "怒忿", "t": "气愤"}, {"w": "怒恚", "t": "愤怒"}, {"w": "怒猊", "t": "愤怒的狮子"}, {"w": "怒恼", "t": "恼怒"}, {"w": "怒愤", "t": "愤怒"}, {"w": "怒噪", "t": "愤怒喧哗。"}]}, {"meaning": "谴责。", "cites": [{"t": "若不可教,而后怒之。", "b": "《礼记·内则》"}], "words": [{"w": "怒怨", "t": "责备"}, {"w": "怒言", "t": "谴责之言"}, {"w": "怒谴", "t": "责怪。"}]}, {"meaning": "奋起;奋发。", "cites": [{"t": "[鹏]怒而飞,其翼若垂天之云。", "b": "《庄子·逍遥游》"}], "words": [{"w": "怒行", "t": "奋斗疾行"}, {"w": "怒马", "t": "奋马"}, {"w": "怒臂", "t": "奋臂。"}]}, {"meaning": "激怒。", "cites": [{"t": "自勇其断,则毋以其敌怒之。", "b": "《史记》"}, {"t": "夫唯义可以怒士,士以义怒可与百战。", "b": "宋·苏洵《权书上》"}]}, {"meaning": "超过。", "cites": [{"t": "刑罚不怒罪,爵赏不踰德。", "b": "《荀子·君子》"}]}, {"meaning": "气势很盛、不可遏止。", "cites": [{"t": "秋高风怒号。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "如怒涛排壑。", "b": "孙文《"}, {"t": "黄花冈七十二烈士事务", "b": ""}]}, {"meaning": "》序。", "cites": [{"t": "飘风怒吹。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "怒水", "t": "湍急的水流"}, {"w": "怒生", "t": "蓬勃生长"}, {"w": "怒芒", "t": "刺射的光芒"}, {"w": "怒华", "t": "花盛开"}, {"w": "怒浪", "t": "汹涌的波浪"}, {"w": "怒张", "t": "波涛汹涌的样子"}, {"w": "怒涌", "t": "猛烈翻腾"}, {"w": "怒发", "t": "勃发"}, {"w": "怒涨", "t": "水势急剧上涨"}, {"w": "怒目切齿", "t": ""}]}, {"meaning": "妻子儿女。", "cites": [{"t": "黄帝、尧、舜诛而不怒。", "b": "《商君书·更法》"}]}, {"meaning": "彗星尾。", "cites": [{"t": "蚩尤之旗,类彗而后曲,…其怒,青黑色。", "b": "《汉书·天文志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1743wx','架','1','jià','木','9','','[{"pinyin": "jià", "defs": [{"meaning": "(形声。从木,加声。本义:棚架)。"}, {"meaning": "同本义。", "cites": [{"t": "葡萄,蔓延性缘,不能自举,作架以承之。", "b": "《齐民要术·种桃》"}]}, {"meaning": "搁置或支持东西的用具。", "cites": [{"t": "借书满架。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "十字架;三脚架;架桩", "t": "原指吃完鸡鸭剩的骨架,江湖暗语指人的尸体"}, {"w": "架阁", "t": "官署中用以保存公文案卷的木架;借指耽搁,放在一旁不管。"}]}, {"meaning": "建造;搭设;支撑。", "cites": [{"t": "架梁之椽。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "架木通之。", "b": "《徐霞客游记·游黄山记》"}, {"t": "架大炮击城。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "架挂", "t": "架设,悬挂"}, {"w": "架屋叠床", "t": "屋上架屋,床上叠床"}, {"w": "架造", "t": "建造"}, {"w": "架构", "t": "构筑,建造。"}]}, {"meaning": "超越,凌驾。", "cites": [{"t": "大略驾群才。", "b": "李白《古风》"}, {"t": "于是士流景慕,务为精密,襞积细微,专相凌架。", "b": "钟嵘《诗品》"}, {"t": "笼张赵于往图,架卓鲁于前箓。", "b": "《文选·孔稚珪·北山移文》"}], "words": [{"w": "架景", "t": "高耸层叠的景象"}, {"w": "架殿", "t": "层出高耸的宫殿。"}]}, {"meaning": "挡架,不让进入。", "cites": [{"t": "举起一根满堂红,架住宝刀。", "b": "《西游记》"}], "words": [{"w": "架隔", "t": "架隔遮截。伸手阻拦"}, {"w": "架数", "t": "招数;技法"}, {"w": "架手", "t": "架势;出手"}, {"w": "他一刀砍来,我拿枪架住", "t": ""}]}, {"meaning": "两柱之间为一架。", "cites": [{"t": "三品,堂五间九架,门三间五架。", "b": "《新唐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1744wx','贺','1','hè','贝','9','','[{"pinyin": "hè", "defs": [{"meaning": "奉送礼物表示庆祝。", "cites": [{"t": "贺,以礼相奉庆也。", "b": "《说文》"}, {"t": "不然,则重币帛,以贺其福而吊其凶。", "b": "《左传·襄公二十八年》"}, {"t": "受天之祜,四方来贺。", "b": "《诗·大雅·下武》"}, {"t": "叔向贺之。", "b": "《国语·晋语》"}, {"t": "是以贺。", "b": ""}, {"t": "何贺之有。", "b": ""}, {"t": "人皆贺之。", "b": "《淮南子·人间训》"}], "words": [{"w": "贺敬", "t": "贺礼"}, {"w": "贺吊往还", "t": "庆贺吊唁往来应酬"}, {"w": "贺冬", "t": "庆祝冬至节"}, {"w": "贺厦", "t": "庆祝大厦落成。"}]}, {"meaning": "嘉奖;犒劳。", "cites": [{"t": "今文余一人贺之。", "b": "《仪礼·觐礼》"}], "words": [{"w": "贺彩", "t": "奖品"}, {"w": "贺功", "t": "庆功"}, {"w": "贺军", "t": "犒劳将士"}, {"w": "贺酒", "t": "表示庆贺的酒宴。"}]}, {"meaning": "增加,增益。", "cites": [{"t": "贺之结于后。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "贺人", "t": "增加人员。"}]}, {"meaning": "锡的别名 。因古时以临贺(今广西贺县)出的锡最出名,因而称锡为贺。", "cites": [{"t": "时珍曰:“…方术家谓之贺,盖锡以临贺出者为美也。”", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1745wx','盈','1','yíng','皿','9','','[{"pinyin": "yíng", "defs": [{"meaning": "(会意。从皿。《说文》:“满器也。”)。"}, {"meaning": "同本义。", "cites": [{"t": "盈,满器也。", "b": "《说文》"}, {"t": "盈莫不有也。", "b": "《墨子经》"}, {"t": "盈,满也。", "b": "《广雅》"}, {"t": "不盈。", "b": "《易·坎》。虞注:“溢也。”"}, {"t": "乐主其盈。", "b": "《礼记·祭义》。注:“盈,犹满也。”"}, {"t": "大庖不盈。", "b": "《诗·小雅·车攻》"}, {"t": "滦水阔不盈丈,而中甚深。", "b": "清·顾祖禹《读史方舆纪要》"}], "words": [{"w": "盈盈", "t": "充盈、充积的样子"}, {"w": "车马盈门;充盈", "t": "充满"}, {"w": "盈抱", "t": "满杯"}, {"w": "盈科", "t": "水多满坑坎"}, {"w": "盈衍", "t": "充斥;充满"}, {"w": "盈庭", "t": "亦作盈廷。充满朝廷"}, {"w": "盈衿", "t": "满胸;满杯"}, {"w": "盈塞", "t": "充满;填塞"}, {"w": "盈漫", "t": "充积散乱。"}]}, {"meaning": "自满;满足。", "cites": [{"t": "穷涯而反,盈量知归。", "b": "南朝梁·任昉《王文宪》序"}], "words": [{"w": "盈厌", "t": "满足"}, {"w": "盈量", "t": "达到所能容纳或经受的最大限度"}, {"w": "盈数", "t": "指十、百、千、万等整数。"}]}, {"meaning": "溢出。", "cites": [{"t": "水流而不盈。", "b": "《易·坎》"}]}, {"meaning": "长,增加。", "cites": [{"t": "进退盈缩变化。", "b": "《战国策·秦策三》"}, {"t": "盈缩卷舒,与时变化。", "b": "《淮南子·俶真》"}, {"t": "冬夏积水,亦时有盈耗也。", "b": "北魏·郦道元《水经注》"}], "words": [{"w": "盈耗", "t": "增减。"}]}, {"meaning": "超过。", "cites": [{"t": "丹蛇逾百尺,玄蜂盈十围。", "b": "南朝宋·鲍照《苦热行》"}]}, {"meaning": "丰满,匀称好看。", "cites": [{"t": "貌丰盈以壮姝兮,苞温润之玉颜。", "b": "《文选·宋玉·神女赋》"}], "words": [{"w": "盈肥", "t": "丰满肥腴"}, {"w": "盈容", "t": "容色庄重。"}]}, {"meaning": "圆满,无残缺。", "cites": [{"t": "三月而盈。", "b": "《礼记·礼运》。疏:“谓月光圆满。”"}], "words": [{"w": "盈月", "t": "满月圆月"}, {"w": "盈冲", "t": "盈满与虚空"}, {"w": "盈昃", "t": "日月圆满或亏缺。"}]}, {"meaning": "有余、多余、多出来,余出", "cites": [{"t": "今有共买物,人出八,盈三;人出七,不足四。", "b": "《九章算术·盈》"}], "words": [{"w": "盈积", "t": "结余"}, {"w": "盈虚", "t": "有余与不足"}, {"w": "盈绌", "t": "有余与不足"}, {"w": "盈羡", "t": "充足有余;盈余"}, {"w": "盈味", "t": "余味。"}]}, {"meaning": "盛,旺盛。", "cites": [{"t": "披竭我盈,故克之(盈,指士气旺盛)。", "b": "《左传·庄公十年》"}], "words": [{"w": "盈虚消息", "t": "古人认为,时运循环,生灭不已,可由盛而衰,也可由衰而盛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1746wx','勇','1','yǒng','力','9','','[{"pinyin": "yǒng", "defs": [{"meaning": "(本作勈,或作恿。形声。从力,甬(yǒng)声。从力,与力气有关。本义:果敢,胆大)。"}, {"meaning": "同本义。", "cites": [{"t": "勇,气也。", "b": "《说文》"}, {"t": "无拳无勇。", "b": "《诗·小雅·巧言》"}, {"t": "尔勇伊何。", "b": ""}, {"t": "勇志之所以敢也。", "b": "《墨子经上》"}, {"t": "勇,文之帅也。", "b": "《国语·周语》"}, {"t": "知死不辟,勇也。", "b": "《左传·昭公二十年》"}, {"t": "勇于就死。", "b": "清·林觉民《与妻书》"}, {"t": "若素名勇。", "b": "明·高启《书博鸡者事》"}, {"t": "兴甚勇。", "b": "《徐霞客游记·游黄山记》"}, {"t": "勇而多艺。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "忠勇", "t": "忠诚而勇敢"}, {"w": "英勇", "t": "勇敢出众"}, {"w": "勇悍", "t": "勇敢强悍"}, {"w": "勇烈", "t": "勇敢猛烈"}, {"w": "勇夫", "t": "勇敢的人"}, {"w": "勇功", "t": "勇敢作战立下的功劳"}, {"w": "勇沉", "t": "勇敢沉着"}, {"w": "勇果", "t": "勇敢果断。"}]}, {"meaning": "勇猛;凶猛。", "cites": [{"t": "勇悍果敢,取众率兵,此下德也。", "b": "《庄子》"}, {"t": "勇,天下之凶德也。", "b": "《吕氏春秋·论威》"}, {"t": "每战,常陷陈却敌,勇冠腾军。", "b": "《三国志》"}], "words": [{"w": "神勇", "t": "形容人非常勇猛"}, {"w": "骁勇", "t": "勇猛"}, {"w": "勇鸷", "t": "勇猛强悍。"}]}, {"meaning": "勇气,勇力。", "cites": [{"t": "可使有勇。", "b": "《论语·先进》"}, {"t": "勇冠三军。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "其勇过人。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1747wx','怠','1','dài','心','9','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从心,台声。本义:懒惰)。"}, {"meaning": "同本义。", "cites": [{"t": "怠,慢也。", "b": "《说文》"}, {"t": "懈,怠也。", "b": "《尔雅》"}, {"t": "怠,赖也。", "b": "《广雅》"}, {"t": "可先而不备,谓之怠。", "b": "《国语·周语》"}, {"t": "吉事虽止不怠。", "b": "《礼记·檀弓》。注:“惰也。”"}, {"t": "毋怠荒。", "b": "《礼记·曲礼》。注:“放散身体也。”"}, {"t": "怠偷甚矣。", "b": "《国语·晋语》"}, {"t": "俾君子易怠。", "b": "《公羊传·文公十二年》"}, {"t": "兵民怠而国弱。", "b": "《商君书·弱民》"}, {"t": "有怠而欲出者,曰:“不出,火且尽。”", "b": "王安石《游褒禅山记》"}], "words": [{"w": "怠荒", "t": "松弛荒废"}, {"w": "怠戏", "t": "怠情职责,纵情嬉戏。"}]}, {"meaning": "疲倦;倦怠。", "cites": [{"t": "怠而后游于清池。", "b": "《汉书·司马相如传》"}], "words": [{"w": "怠容", "t": "疲惫的样子。"}]}, {"meaning": "使…懒惰。", "cites": [{"t": "天大寒,砚冰坚,手指不可屈伸,弗之怠。", "b": "明·宋濂《送东阳马生序》"}]}, {"meaning": "轻漫;骄傲不敬重。", "cites": [{"t": "其民怠沓其君。", "b": "《国语·晋语》"}, {"t": "守卒皆怠炎(王炎)。", "b": "《宋史·杨愿传》"}], "words": [{"w": "怠玩", "t": "指玩忽职守"}, {"w": "怠忽", "t": "轻慢疏忽"}, {"w": "怠沓", "t": "怠慢不敬"}, {"w": "怠废", "t": "怠慢荒废。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1748wx','癸','1','guǐ','癶','9','','[{"pinyin": "guǐ", "defs": [{"meaning": "(象形。甲骨文字形,象二戣(kuí),古代兵器。交叉之形,盖即“戣”之古文。①本义:古代兵器。戟属。②天干的第十位),用作顺序的第十。"}, {"meaning": "估量。", "cites": [{"t": "癸之言揆也,言万物可揆度,故曰癸。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1749wx','蚤','1','zǎo','虫','9','','[{"pinyin": "zǎo", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "蚤,啮人跳蚤。", "b": "《说文》"}, {"t": "鸱鸺夜撮蚤。", "b": "《庄子·秋水》"}, {"t": "得蚤者莫不糜之齿牙,为害身也。", "b": "曹植《贪恶鸟论》"}], "words": [{"w": "沙蚤;水蚤;蚤蚊", "t": "跳蚤和蚊子。亦泛指小虫"}, {"w": "蚤虱", "t": "跳蚤和虱子。亦泛指小害虫。"}]}, {"meaning": "指月初或早晨。", "cites": [{"t": "日至于曾泉,是谓蚤食。", "b": "《淮南子·天文》"}, {"t": "不麾蚤。", "b": "《礼记·礼器》"}, {"t": "四之日其蚤。", "b": "《诗·豳风·七月》"}, {"t": "使遂蚤得处囊中。乃颖脱而出。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "蚤亡", "t": "早亡"}, {"w": "蚤出夜入", "t": "早晨出门,晚上归来"}, {"w": "蚤作", "t": "早晨起身;早起干活"}, {"w": "蚤夜", "t": "昼夜;早晚。"}]}, {"meaning": "(zhǎo)。指甲,脚趾。", "cites": [{"t": "因其蹄蚤。", "b": "《墨子·非乐上》"}, {"t": "是以差论蚤牙之士。", "b": "《墨子·天志下》。注:“蚤作爪。”"}, {"t": "争利如蚤甲而丧其掌。", "b": "《荀子·大略》"}], "words": [{"w": "蚤牙", "t": "爪牙"}, {"w": "蚤甲", "t": "爪甲。"}]}, {"meaning": "指时间在先,和“迟”相对。", "cites": [{"t": "若皆蚤世犹可。", "b": "《国语·周语》"}, {"t": "四之日其蚤。", "b": "《诗·豳风·七月》"}, {"t": "不可不蚤虑。", "b": "《汉书·刘向传》"}, {"t": "旦日不可不蚤自来谢项王。", "b": "《史记·龟策传》"}], "words": [{"w": "蚤世", "t": "早逝,夭折"}, {"w": "蚤食", "t": "即早食"}, {"w": "蚤达", "t": "指年轻时已任高官。早年即已显达得意"}, {"w": "蚤知之士", "t": "先知,有先见之明的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1750wx','柔','1','róu','木','9','','[{"pinyin": "róu", "defs": [{"meaning": "(形声。从木,矛声。本义:树木可曲可直)。"}, {"meaning": "同本义。", "cites": [{"t": "柔,木曲直也。", "b": "《说文》。段注:“凡木曲者可直,直者可曲,曰柔。”"}, {"t": "荏染柔木。", "b": "《诗·小雅·小弁》"}], "words": [{"w": "柔木", "t": "柔软而又坚韧的木。"}]}, {"meaning": "柔弱;细嫩。", "cites": [{"t": "柔,弱也。", "b": "《广雅》"}, {"t": "爰求柔桑。", "b": "《诗·豳风·七月》"}, {"t": "薇亦柔止。", "b": "《诗·小雅·采微》"}, {"t": "柔弱者,生之徒也。", "b": "《说苑·敬慎》"}, {"t": "柔弱者,道之要也 。", "b": "《淮南子·原道》"}, {"t": "柳条将舒未舒,柔梢披风。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "柔枝嫩叶;柔条", "t": "嫩枝"}, {"w": "柔红", "t": "柔嫩的花"}, {"w": "柔莩", "t": "幼芽附着的种子薄膜"}, {"w": "柔荏", "t": "草木枝叶柔韧"}, {"w": "柔桑", "t": "嫩桑叶"}, {"w": "柔稚", "t": "幼嫩。"}]}, {"meaning": "柔软。", "cites": [{"t": "寂寞深闺,柔肠一寸愁千缕。", "b": "李清照《点绛唇》"}], "words": [{"w": "柔滑如荑", "t": "柔荑"}, {"w": "柔穰", "t": "柔软的穰草"}, {"w": "柔暖", "t": "柔软温暖"}, {"w": "柔腴", "t": "柔软丰满"}, {"w": "柔钝", "t": "柔软而不锋利"}, {"w": "柔毳", "t": "柔软的皮毛"}, {"w": "柔革", "t": "柔软的皮革。"}]}, {"meaning": "柔和;温和。", "cites": [{"t": "柔而立。", "b": "《书·皋陶谟》。郑注:“性行和柔。”"}, {"t": "柔而正。", "b": "《礼记·乐记》"}, {"t": "其声和以柔。", "b": "《史记·乐书》"}, {"t": "然则柔风甘雨乃至。", "b": "《管子·四时》"}, {"t": "士不偏不党,柔而坚。", "b": "《吕氏春秋·士容》"}, {"t": "柔色以温之。", "b": "《礼记·内则》"}], "words": [{"w": " 柔谨", "t": "温和恭谨"}, {"w": "柔缓", "t": "温和宽厚"}, {"w": "柔调", "t": "温和地调治"}, {"w": "柔愿", "t": "温和朴实"}, {"w": "柔慈", "t": "温和仁慈"}, {"w": "柔雅", "t": "温和文雅"}, {"w": "柔黄", "t": "嫩黄"}, {"w": "柔良", "t": "柔顺善良"}, {"w": "柔明", "t": "柔顺而聪明"}, {"w": "柔合", "t": "柔顺弥合"}, {"w": "柔讷", "t": "柔顺而不直言"}, {"w": " 柔谦", "t": "柔和谦逊"}, {"w": " 柔嘉", "t": "柔和美善"}, {"w": "柔雌", "t": "柔和"}, {"w": "柔仁", "t": "柔和而仁慈"}, {"w": "柔心", "t": "性情柔和"}, {"w": "柔奸", "t": "表面柔和而内心奸诈"}, {"w": "柔气", "t": "气质柔和的人。"}]}, {"meaning": "温柔。", "cites": [{"t": "柔情绰态,媚于语言。", "b": "曹植《洛神赋》"}], "words": [{"w": "柔媚娇俏", "t": "温柔和顺,妩媚俏丽"}, {"w": "柔婉", "t": "温柔"}, {"w": "柔闲", "t": "温柔、娴淑"}, {"w": "柔娥", "t": "温柔的美女"}, {"w": "柔善", "t": "性格温柔的善良之人"}, {"w": "柔情侠骨", "t": "温柔的情态,侠义的性格"}, {"w": "柔淑", "t": "温柔贤淑"}, {"w": "柔恶", "t": "外似温柔内心恶劣的人"}, {"w": "柔惠", "t": "温顺柔和"}, {"w": "柔习", "t": "温顺驯服"}, {"w": "柔慎", "t": "温顺谨慎"}, {"w": "柔煦", "t": "驯顺。"}]}, {"meaning": "软弱;柔弱。", "cites": [{"t": "蚤见而心柔懦。", "b": "《韩非子·亡征》"}], "words": [{"w": "柔肤弱体", "t": "柔弱的身体"}, {"w": "柔蔓", "t": "柔弱的藤蔓"}, {"w": "柔靡", "t": "柔弱委靡"}, {"w": "柔筋脆骨", "t": "柔弱的筋骨"}, {"w": "柔柯", "t": "柔弱的枝条"}, {"w": "柔脆", "t": "柔弱,软弱"}, {"w": "柔桡", "t": "柔弱苗条。"}]}, {"meaning": "安抚或平息,尤其通过让步。", "cites": [{"t": "柔远能迩。", "b": "《书·舜典》"}, {"t": "怀柔百神。", "b": "《诗·周颂·时迈》"}], "words": [{"w": "柔远", "t": "安抚远人或远方邦国"}, {"w": "柔远能迩", "t": "怀柔远方,优抚近地"}, {"w": "柔软绥怀", "t": "安抚外方归顺者"}, {"w": "柔远镇迩", "t": "安抚远方,安定内地。"}]}, {"meaning": "通过加工使变软。", "cites": [{"t": "柔其肉。", "b": "《礼记·内则》"}], "words": [{"w": "柔麻;柔融", "t": "溶化使柔软。"}]}, {"meaning": "润泽。", "cites": [{"t": "祝融亦能昭显天地之光明,以生柔嘉材者也。", "b": "《国语·郑语》"}, {"t": "厉利剑者,必以柔砥。", "b": "《淮南子·说山》"}, {"t": "灵之圣之,岁殷泽柔。", "b": "南朝·梁·江淹《迎送神升歌》"}]}, {"meaning": "车轮的外周。", "cites": [{"t": "椎车无柔。", "b": "《盐铁论·散不足》"}]}, {"meaning": "汉代侯国名 。治所在今山东省临沂地区境内。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1751wx','垒','1','lěi','土','9','','[{"pinyin": "lěi", "defs": [{"meaning": "(形声。从土,畾(雷)声。本义:军壁,防护军营的墙壁或建筑物)。"}, {"meaning": "同本义。", "cites": [{"t": "垒,军壁也。", "b": "《说文》"}, {"t": "四郊多垒。", "b": "《礼记·曲礼上》"}, {"t": "营军之垒舍。", "b": "《周礼·夏官·量人》"}, {"t": "因垒而降。", "b": "《左传·僖公十九年》"}, {"t": "摩垒而还。", "b": "《左传·宣公十二年》"}, {"t": "于城内更筑坚垒。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "故垒西边。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "垒培", "t": "军营中的围墙等防御工事"}, {"w": "垒尉", "t": "官名。掌理警卫营堡、缉捕盗贼的武官"}, {"w": "垒和", "t": "军营的大门"}, {"w": "垒口", "t": "营垒的入口"}, {"w": "垒舍", "t": "犹营房"}, {"w": "深沟高垒;两军对垒", "t": ""}]}, {"meaning": "把砖、石等重叠砌起来。", "cites": [{"t": "请深垒固军。", "b": "《左传·文公十二年》"}], "words": [{"w": "垒城", "t": "筑垒近大城叫垒城"}, {"w": "垒垒", "t": "相叠重沓的样子"}, {"w": "垒断", "t": "堵截住"}, {"w": "垒块", "t": "积石。比喻胸中郁积的不平之气"}, {"w": "垒垒", "t": "一堆一堆地丛列着"}, {"w": "垒堆", "t": "堆积;拥挤。"}]}, {"meaning": "捆绑。", "cites": [{"t": "甲不解壘,兵不解翳。", "b": "《管子·小匡》"}, {"t": "氐羌之虏也。不憂其壘也。", "b": "《荀子·大略》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1752wx','绑','1','bǎng','纟','9','','[{"pinyin": "bǎng", "defs": [{"meaning": "(形声。从糸(mì),邦声。古无此字。“绑”字出现于元、明之间。本义:捆,缚)。"}, {"meaning": "同本义。", "cites": [{"t": "众军向前,用索绑缚住了。", "b": "《三国演义》"}], "words": [{"w": "绑扎所", "t": "军队在战地特设为伤员包扎、治疗的处所"}, {"w": "绑缚", "t": "捆绑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1753wx','绒','1','róng','纟','9','','[{"pinyin": "róng", "defs": [{"meaning": "(形声。从糸(mì),戎声。本义:鸟兽身上的柔毛)。"}, {"meaning": "熟丝。", "cites": [{"t": "绒,熟练丝。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1754wx','结','1','jiē jié','纟','9','','[{"pinyin": "jiē", "defs": [{"meaning": "植物生长果实", "words": [{"w": "结瓜", "t": ""}]}, {"meaning": "坚硬;牢固", "words": [{"w": "结实", "t": ""}]}, {"meaning": "健壮", "words": [{"w": "结实", "t": ""}]}, {"meaning": "口吃", "words": [{"w": "结巴", "t": ""}]}]}, {"pinyin": "jié", "defs": [{"meaning": "用绳、线、皮条等绾成的疙瘩", "words": [{"w": "蝴蝶结", "t": ""}]}, {"meaning": "关键。", "cites": [{"t": "诚信者,天下之结也。", "b": "《管子》"}]}, {"meaning": "总发,挽发而结之于顶。", "cites": [{"t": "激楚之结,独秀先些。", "b": "《楚辞·招魂》"}, {"t": "程郑山东迁虏也,亦治铸,贾魋结民,富埒卓氏。", "b": "《汉书·货殖传》"}, {"t": "两人皆胡服椎结。", "b": "《汉书·李陵传》"}]}, {"meaning": "比喻心情烦闷,心里有结。", "cites": [{"t": "意有所郁结。", "b": "司马迁《报任安书》"}]}, {"meaning": "牢固。", "cites": [{"t": "今疾已结,促去可得与家相见,五日卒。", "b": "陈寿《三国志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1755wx','绕','1','rào','纟','9','','[{"pinyin": "rào", "defs": [{"meaning": "(形声。从糸(mì),尧声。本义:缠束)。"}, {"meaning": "同本义。", "cites": [{"t": "绕,缠也。", "b": "《说文》"}, {"t": "绕黄山而款牛首。", "b": "张衡《西京赋》。注:“裹也。”"}], "words": [{"w": "把丝绕在卷筒上;绕搭", "t": "缠绕"}, {"w": "绕缭", "t": "缭绕,盘旋围绕"}, {"w": "绕手", "t": "犹棘手"}, {"w": "绕网", "t": "陷入罗网"}, {"w": "绕结", "t": "回旋缠结。"}]}, {"meaning": "环绕。", "cites": [{"t": "白水绕东城。", "b": "唐·李白《送友人》"}, {"t": "黄芦苦竹绕宅生。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "绕梁声", "t": "形容歌声优美动听,长久萦回耳畔"}, {"w": "绕袭", "t": "迂回突袭敌人。"}]}, {"meaning": "迂回绕过。", "cites": [{"t": "一边是陡山,一边是深峪,更无别处好绕。", "b": "《老残游记》"}], "words": [{"w": "绕弯", "t": "波折"}, {"w": "绕过暗礁;绕袭", "t": "绕道袭击。"}]}, {"meaning": "纠缠(如事情或问题)。", "cites": [{"t": "我看昨天晚上你是有点绕住了;遇上急事,谁也保不住迷头。", "b": "老舍《骆驼祥子》"}]}, {"meaning": "弯曲。", "cites": [{"t": "眉连娟以增绕兮,目流睇而横波。", "b": "《文选·傅毅·舞赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1756wx','骄','1','jiāo','马','9','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从马,乔声。本义:六尺高的马) 同本义。", "cites": [{"t": "骄,马高六尺为骄。《诗》曰:“我马唯骄。”", "b": "《说文》"}, {"t": "四牡有骄。", "b": "《诗·卫风·硕人》"}]}, {"meaning": "傲慢;骄矜。", "cites": [{"t": "不敢以其富贵骄士。", "b": "《史记·魏公子列传》"}, {"t": "谏而无骄。", "b": "《礼记·少仪》。注:“谓言行谋从恃知而慢也。”"}, {"t": "骄奢淫泆。", "b": "《左传·隐公三年》。注:“谓恃己凌物。”"}, {"t": "在上不骄。", "b": "《孝经》。注:“无礼为骄。”"}, {"t": "骄泰奢侈。", "b": "《国语·晋语》"}, {"t": "单于益骄。", "b": "《汉书·李广苏建传》"}, {"t": "国王骄奢。", "b": "《后汉书·张衡传》"}, {"t": "偃蹇而骄。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "骄横;骄蹇;骄佚", "t": "骄纵逸乐"}, {"w": "骄悍", "t": "骄纵勇悍"}, {"w": "骄肆", "t": "骄恣放纵"}, {"w": "骄狎", "t": "放纵玩乐"}, {"w": "骄色", "t": "骄矜的神情"}, {"w": "骄骜", "t": "骄傲"}, {"w": "骄侈", "t": "傲慢奢侈"}, {"w": "骄民", "t": "京城的居民。"}]}, {"meaning": "宠爱;爱怜。", "cites": [{"t": "娇儿不离膝。", "b": "杜甫《羌村三首》"}], "words": [{"w": "骄儿", "t": "受宠爱的孩子"}, {"w": "骄弱", "t": "骄惯而软弱"}, {"w": "骄爱", "t": "骄美可爱"}, {"w": "骄肠", "t": "娇媚柔肠"}, {"w": "骄顽", "t": "幼稚可爱的顽童。"}]}, {"meaning": "轻视。", "cites": [{"t": "骄其妻妾。", "b": "《孟子·离娄下》"}, {"t": "君不如予之以骄智伯。", "b": "《韩非子·说林上》"}], "words": [{"w": "骄敌;骄易", "t": "轻慢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1757wx','绘','1','huì','纟','9','','[{"pinyin": "huì", "defs": [{"meaning": "(从糸(mì,与线丝有关),会声。本义:五彩绣品) 同本义。也作“会”。", "cites": [{"t": "绘,会五采绣也。", "b": "《说文》"}, {"t": "杂彩曰绘。", "b": "《小尔雅·广训》"}, {"t": "山龙华虫作绘。", "b": "《虞书》"}], "words": [{"w": "绘绚", "t": "彩绘绚丽。"}]}, {"meaning": "绘画。", "cites": [{"t": "自绘败状。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "绘影写光。", "b": "蔡元培《图画》"}, {"t": "绘像祀之。", "b": "《明史》"}, {"t": "中绘殿阁。", "b": "《聊斋志异·促织》"}], "words": [{"w": "绘像", "t": "画像"}, {"w": "绘画", "t": "作画"}, {"w": "绘本", "t": "画册"}, {"w": "绘卷", "t": "画卷"}, {"w": "绘事后素", "t": "指绘画先以粉地为质然后施加五彩。比喻人有美质,然后可加文饰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1758wx','给','1','gěi jǐ','纟','9','','[{"pinyin": "gěi", "defs": [{"meaning": "交付，送与。"}, {"meaning": "把动作或态度加到对方。"}, {"meaning": "表示对象、目的,相当于‘为’、‘替’。"}, {"meaning": "引进动作行为的主动者,或表示被动语态,相当于‘被’。"}, {"meaning": "表示方向,相当于‘朝’、‘对’、‘向’。"}]}, {"pinyin": "jǐ", "defs": [{"meaning": "(形声。从糸,合声。本义:衣食丰足;充裕)。"}, {"meaning": "同本义。", "cites": [{"t": "给,相足也。", "b": "《说文》"}, {"t": "事之供给。", "b": "《国语·周语》"}, {"t": "岁岁广开,百姓充给。", "b": "《齐民要术·序》"}, {"t": "则日不足,力不给。", "b": "《韩非子·有度》"}, {"t": "要曰强本节用,则人给家足之道也。", "b": "《史记·太史公自序》"}], "words": [{"w": "给富", "t": "丰足富裕"}, {"w": "给足", "t": "丰足。"}]}, {"meaning": "口齿伶利。", "cites": [{"t": "御人以口给,屡憎于人。", "b": "《论语》"}], "words": [{"w": "给口", "t": "口才敏捷"}, {"w": "给捷", "t": "敏捷。"}]}, {"meaning": "充足的供给,以物质给予对方。", "cites": [{"t": "镇国家,抚百姓,给馈饷。", "b": "《史记·高祖本纪》"}, {"t": "给贡职郡县。(像秦国的郡县那样贡纳赋税。给,供。)", "b": "《战国策·燕策》"}, {"t": "给其食用。", "b": "《战国策·齐策四》"}, {"t": "请铸铜记给之。", "b": "《宋史·职官志》"}, {"t": "艺蔬自给。", "b": "清·张廷玉《明史》"}, {"t": "给军民赏月钱。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "补给;配给;自给自足;给使", "t": "供人差使"}, {"w": "给与", "t": "授物与人。"}]}, {"meaning": "授与,交付。", "cites": [{"t": "若残竖子之类,恶能给若金!", "b": "《吕氏春秋》"}]}, {"meaning": "速,捷。", "cites": [{"t": "富必给贫,壮必给老。", "b": "《邓析子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1759wx','绚','1','xuàn','纟','9','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从糸(mì),旬声。本义:美丽,漂亮有文采的样子)。"}, {"meaning": "同本义(含有色彩灿烂多姿的意思)。", "cites": [{"t": "绚,文貌。", "b": "《玉篇》"}, {"t": "松门亘五里,碧彩高下绚。", "b": "皮日休《雨中游包山精舍》"}, {"t": "素以为绚兮。", "b": "《论语·八佾》"}, {"t": "江枫绚似红妆。", "b": "张草《河满子》"}], "words": [{"w": "绚丽;绚文", "t": "绚丽而有文采"}, {"w": "绚采", "t": "文采"}, {"w": "绚素", "t": "白绢绘以文采;在绘画上加施白采。"}]}, {"meaning": "迅疾的样子。", "cites": [{"t": "别辈越群,绚练夐绝。", "b": "颜延之《赭白马赋》"}], "words": [{"w": "绚练", "t": "迅疾的样子。"}]}, {"meaning": "点缀。", "cites": [{"t": "含烟绚碧彩,带露如珠缀。", "b": "唐·刘禹锡《省试风光草际浮》"}], "words": [{"w": "绚染", "t": "渲染。"}]}, {"meaning": "使眩惑迷乱。", "cites": [{"t": "故色绚于目,情惑于心,情色相生,心目相视。", "b": "《清平山堂话本》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1760wx','骆','1','luò','马','9','','[{"pinyin": "luò", "defs": [{"meaning": "(形声。从马,各声。本义:尾和鬣毛黑色的白马)。"}, {"meaning": "同本义。", "cites": [{"t": "骆,马白色黑鬣尾也。", "b": "《说文》"}, {"t": "白马朱鬣骆。", "b": "《广雅》"}, {"t": "驾彼四骆。", "b": "《诗·小雅·四牡》"}]}, {"meaning": "又。", "cites": [{"t": "哔哔骆马。", "b": ""}, {"t": "驾白骆。", "b": "《礼记·月令》"}, {"t": "夏后氏骆马黑鬣。", "b": "《礼记·明唐位》"}, {"t": "骆驿道路。", "b": "《汉书·王莽传》。注:“言不绝。”"}], "words": [{"w": "骆马", "t": "身白鬣黑的马。"}]}, {"meaning": "络绎不绝。", "cites": [{"t": "骆驿道路。", "b": "《汉书·王莽传下》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1761wx','络','1','luò lào','纟','9','','[{"pinyin": "luò", "defs": [{"meaning": "(形声。从糸(mì),表示与丝线有关。各声。本义:缠绕,捆缚)。"}, {"meaning": "同本义。", "cites": [{"t": "络,缠也。", "b": "《广雅》"}, {"t": "有九丘,以水络之。", "b": "《海内经》"}, {"t": "郑绵络些。", "b": "《楚辞·招魂》"}, {"t": "绵络天地。", "b": "《汉书·扬雄传》"}, {"t": "蒙绵摇缀,参差披拂。", "b": "柳宗元《至小丘西小石潭记》"}, {"t": "罗绵其上。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "络着手", "t": "缠着手"}, {"w": "络越子", "t": "用越子缠绕丝或纱"}, {"w": "络索", "t": "耳饰。"}]}, {"meaning": "用网状物兜住。", "cites": [{"t": "黄金络马头。", "b": "《乐府诗·陌上桑》"}], "words": [{"w": "她头络着个发网", "t": ""}]}, {"meaning": "搜罗。", "cites": [{"t": "网络古今,叙述惩劝。", "b": "唐·司马贞《补史记序》"}]}]}, {"pinyin": "lào", "defs": [{"meaning": "用于一些口语词", "cites": [{"t": "倒不如打个络子,把玉络上呢。", "b": "《红楼梦》 "}], "words": [{"w": "络子", "t": "线绳编成的小网袋,可以装物"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1762wx','绝','1','jué','纟','9','','[{"pinyin": "jué", "defs": [{"meaning": "(会意。从糸(mì),表示与线丝有关,从刀,从卩(人)。表示人用刀断丝。本义:把丝弄断)。"}, {"meaning": "同本义。", "cites": [{"t": "绝,断丝也。", "b": "《说文》"}, {"t": "冠缨索绝。", "b": "《史记》"}], "words": [{"w": "绝缨", "t": "冠缨断绝。比喻宽宏大量。"}]}, {"meaning": "引申为断,断绝。", "cites": [{"t": "绝,断也。", "b": "《广雅》"}, {"t": "举鼎绝膑。", "b": "《史记·始皇纪》"}, {"t": "必绝其谋。", "b": "《战国策·秦策》"}, {"t": "楚诚能绝齐。(绝齐,与齐国断绝外交关系。)", "b": "《史记·屈原贾生列传》"}, {"t": "绝秦赵之欢。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "以绝秦望。", "b": ""}, {"t": "得水则为绝。", "b": "《庄子·至乐》"}, {"t": "绝人以玦。", "b": "《荀子·大略》"}, {"t": "秦王惊,自引而起,袖绝。", "b": "《史记·刺客列传》"}, {"t": "绝其望。", "b": "《韩非子·主道》"}, {"t": "即炉火烧绝。", "b": "唐·柳宗元《童区寄传》"}, {"t": "往来而不绝。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "绝卖", "t": "出卖产权;卖掉后再也不许赎回"}, {"w": "绝裙", "t": "扯断衣襟。指去意坚决,难以挽留"}, {"w": "绝祀", "t": "断绝祖先的祭祀。比喻国家灭亡,子嗣全无。"}]}, {"meaning": "割断;切断。", "cites": [{"t": "绝头刳服。", "b": "《韩非子·内储说上》"}, {"t": "今楚国虽小,绝长缩短,犹以数千里。", "b": "《战国策·楚策》"}, {"t": "七曰绝祭。", "b": "《周礼·大祝》。司农注:“不循其本直绝肺以祭也。”"}], "words": [{"w": "绝亢", "t": "斩断脖子"}, {"w": "绝脰", "t": "断颈"}, {"w": "绝膑", "t": "折断膑骨"}, {"w": "绝长补短", "t": "本指计量国土大小。后常用为截取有余以补不足。"}]}, {"meaning": "气息中止;晕死。", "cites": [{"t": "抢呼欲绝。", "b": "《聊斋志异》"}], "words": [{"w": "绝单", "t": "狱吏所填写的犯人死亡单子"}, {"w": "绝类", "t": "灭绝其种类"}, {"w": "绝命辞", "t": "临死前写的文章。"}]}, {"meaning": "断根,无后代。", "cites": [{"t": "子绝四。", "b": "《论语》。皇疏:“无也。”"}], "words": [{"w": "绝业", "t": "已经中断的王业"}, {"w": "绝绪", "t": "没有后代"}, {"w": "绝户计", "t": "断绝别人子孙后代的计谋。"}]}, {"meaning": "横渡;穿越。", "cites": [{"t": "绝江河,横渡过长江黄河。绝,断,横渡。", "b": ""}, {"t": "假舟楫者,非能水也,而绝江河。", "b": "《荀子·劝学》"}, {"t": "乃绝漳水。", "b": "《穆天子传》"}, {"t": "丈人渡之绝江。", "b": "《吕氏春秋·异宝》。注:“过也。”"}], "words": [{"w": "绝塞", "t": "横渡关塞;渡越边塞"}, {"w": "绝漠", "t": "穿越沙漠"}, {"w": "绝险", "t": "越过险阻。"}]}, {"meaning": "落。", "cites": [{"t": "虽萎绝亦何伤兮,哀众芳之芜秽。", "b": "《楚辞》"}]}, {"meaning": "杜绝;摒弃。", "cites": [{"t": "绝世于良。", "b": "《左传·哀公十五年》。注:“犹言弃也。”"}], "words": [{"w": "绝弦", "t": "断弃琴弦,不再使用"}, {"w": "绝学", "t": "弃绝学问;抛开学业"}, {"w": "绝仁弃义", "t": "抛弃世俗的仁义,回复到纯朴的本性。"}]}, {"meaning": "停止。", "cites": [{"t": "嗜酒甘而不能绝于口。", "b": "《吕氏春秋·权勋》。注:“止也。”"}, {"t": "胞之络脉绝也。", "b": "《素问·奇病论》"}, {"t": "不能绝也。", "b": "《墨子·公输》"}, {"t": "夜久语声绝。", "b": "唐·杜甫《石壕吏》"}, {"t": "弱者先绝。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "绝息", "t": "停止"}, {"w": "绝脉", "t": "脉息停止。"}]}, {"meaning": "竭;尽。", "cites": [{"t": "振乏绝。", "b": ""}, {"t": "吕氏春秋·季春》。注:“居而无食曰绝。”", "b": ""}, {"t": "江河山川绝而不流。", "b": "《淮南子·本经》。注:“竭也。”"}, {"t": "绝目尽平原。", "b": "鲍照诗。注:“犹尽也。”"}], "words": [{"w": "绝力", "t": "用尽力气"}, {"w": "绝目", "t": "极目。尽目力之所及"}, {"w": "绝叫", "t": "大声呼叫"}, {"w": "绝阴", "t": "阴气竭尽。阴阳家称农历四月戊辰日为绝阴之日,百事不宜。"}]}, {"meaning": "才技特异,独一无二。", "cites": [{"t": "绝妙好辞。", "b": "《蔡邕题曹娥碑》"}], "words": [{"w": "绝学", "t": "独到的学问"}, {"w": "绝足奔放", "t": "喻千里马疾驰"}, {"w": "绝才", "t": "过人的才能。无人能及的才能"}, {"w": "绝手", "t": "具有第一等才艺的高手。"}]}, {"meaning": "距离远、隔绝难通的。", "cites": [{"t": "殊邻绝党之域。", "b": "扬雄《长杨赋》。注:“远也。”"}], "words": [{"w": "绝域", "t": "极远的地方"}, {"w": "绝地", "t": "极远的地方"}, {"w": "绝垠", "t": "极远的地方"}, {"w": "绝国", "t": "僻远隔绝的邦国"}, {"w": "绝徼", "t": "极为遥远的地方"}, {"w": "绝郡", "t": "边远的郡县"}, {"w": "绝区", "t": "极边远地区。"}]}, {"meaning": "绝对;全然 ——用在否定词前面。", "cites": [{"t": "绝无有者。", "b": "清·方苞《狱中杂记》"}, {"t": "绝无踪响。(绝,绝然,绝对,根本。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "绝不可能;绝无此意;绝非偶然;绝异", "t": "全然不同"}, {"w": "绝无", "t": "全然没有。"}]}, {"meaning": "极,最。", "cites": [{"t": "黄山绝胜处。", "b": "《徐霞客游记·游黄山记》"}, {"t": "至险绝处。", "b": ""}], "words": [{"w": "绝少", "t": "极少"}, {"w": "绝早", "t": "极早"}, {"w": "绝峰", "t": "绝顶。山的最高峰"}, {"w": "绝顶", "t": "山的最高峰"}, {"w": "绝足", "t": "最快的马。喻千里马。"}]}, {"meaning": "指食物断绝的穷困者。", "cites": [{"t": "务蓄积,以备乏绝。", "b": "《盐铁论》"}]}, {"meaning": "罢了,了。", "cites": [{"t": "听言绝,我则沉默默腹内忧,都做了虚飘飘心上喜。", "b": "元·孙仲章《勘头巾》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1763wx','绞','1','jiǎo','纟','9','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(会意。从交,从糸(mì),表示与线丝有关,交亦声。本义:用两股以上的细长条扭结成一根绳索;扭,拧)。"}, {"meaning": "同本义。", "cites": [{"t": "绞,缢也。", "b": "《说文》。段注:“两绳相交而紧谓之绞。”"}, {"t": "绞带。", "b": "《仪礼·丧服》"}, {"t": "绞,横三缩一。", "b": "《仪礼·士丧礼》。注:“所以收束衣服为坚急者也,以布为之。”"}, {"t": "两股相交谓之绞。", "b": "《礼记·杂记》疏"}], "words": [{"w": "绞带", "t": "古代丧礼中所系麻带"}, {"w": "绞绡", "t": "生丝织成的薄纱、薄绸"}, {"w": "把铁丝绞在一起;绞汁", "t": "挤压汁水"}, {"w": "绞巾", "t": "拧毛巾。"}]}, {"meaning": "缠绕。", "cites": [{"t": "根绞怪石,不土而植。", "b": "柳宗元《晋问》"}], "words": [{"w": "绞脚", "t": "包脚布"}, {"w": "绞石", "t": "某种条状物缠绕石头。"}]}, {"meaning": "旧时死刑的一种。缢死;勒死。", "cites": [{"t": "绞缢以戮。", "b": "左传·哀公二年》。注:“绞,所以缢人物。”"}], "words": [{"w": "绞缢", "t": "用绳子勒死。"}]}, {"meaning": "急切。", "cites": [{"t": "至言往至绞。", "b": "《曾子·侈靡》。注:“谓急也。”"}, {"t": "直而无礼则绞。", "b": "《论语·泰伯》。郑注:“绞,急也。”"}, {"t": "叔孙绞而婉。", "b": "《左传·昭公元年》。注:“切也。”"}], "words": [{"w": "绞切", "t": "急切"}, {"w": "绞直", "t": "急躁而率直"}, {"w": "绞急", "t": "急切"}, {"w": "绞讦", "t": "急切指责别人的过失。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1764wx','骇','1','hài','马','9','','[{"pinyin": "hài", "defs": [{"meaning": "(形声。从马,亥声。本义:马受惊)。"}, {"meaning": "同本义。", "cites": [{"t": "骇,惊也。", "b": "《说文》"}, {"t": "马方骇,鼓而惊之。", "b": "《汉书·梅乘传》"}], "words": [{"w": "骇驷", "t": "狂奔的驷马。"}]}, {"meaning": "惊骇;惊诧;惊动。", "cites": [{"t": "录事骇之。", "b": "明·高启《书博鸡者事》"}, {"t": "骇问。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "虎大骇。", "b": "唐·柳宗元《三戒》"}, {"t": "而所谓庸夫愚妇者,奔走骇汗,羞愧俯伏。", "b": "欧阳修《相州昼锦堂纪》"}], "words": [{"w": "骇汗", "t": "因惊恐而流汗"}, {"w": "骇浪", "t": "骇人的大浪"}, {"w": "骇突", "t": "受惊而乱窜"}, {"w": "骇殚", "t": "惊惧。"}]}, {"meaning": "震动。", "cites": [{"t": "而国人大骇。", "b": "《战国策·宋策》"}, {"t": "庶人骇政。", "b": "《荀子·王制》。注:“不安上之策也。”"}], "words": [{"w": "骇世", "t": "震惊当世"}, {"w": "骇俗", "t": "震惊世俗"}, {"w": "骇惊", "t": "震惊。"}]}, {"meaning": "突发;兴起。", "cites": [{"t": "骇,起也。", "b": "《广雅·释言》"}], "words": [{"w": "骇跳", "t": "暴跳"}, {"w": "骇机", "t": "突然触发的弩机。比喻突发的祸难。"}]}, {"meaning": "惊扰;骚动。", "cites": [{"t": "凡鸟之举也,去骇从不骇。", "b": "《吕氏春秋》"}, {"t": "三军万夫,环旋翔佯,晃骇之间,虏骑乘之。", "b": "《新唐书》"}, {"t": "猋骇云讯集。", "b": "《汉书·扬雄传》。注:“动也。”"}, {"t": "哗然而骇者。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "勒取财物,盈千累万,尤属骇人听闻。", "b": "《清史稿·西藏》"}]}, {"meaning": "擂,击。", "cites": [{"t": "燎京薪,骇雷鼓。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "播散。", "cites": [{"t": "于是精移神骇,忽焉思散。", "b": "曹植《洛神赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1765wx','统','1','tǒng','纟','9','','[{"pinyin": "tǒng", "defs": [{"meaning": "(形声。从糸(mì),充声。本义:丝的头绪)。"}, {"meaning": "同本义。", "cites": [{"t": "统,纪也。", "b": "《说文》"}, {"t": "茧之性为丝,然非得工女煮以热汤而抽其统纪。", "b": "《淮南子·泰族训》"}], "words": [{"w": "统绪", "t": "头绪。"}]}, {"meaning": "世代相继的系统。", "cites": [{"t": "求其统类。", "b": "《荀子·解蔽》"}], "words": [{"w": "皇统", "t": "世代相传的帝系"}, {"w": "道统;传统;统承", "t": "继承统绪"}, {"w": "统系", "t": "系统"}, {"w": "统贯", "t": "系统;条贯"}, {"w": "统嗣", "t": "帝统的嗣续关系。"}]}, {"meaning": "纲纪,准则。", "cites": [{"t": "忠信以为质,端悫以为统。", "b": "《荀子·臣道》"}], "words": [{"w": "体统", "t": "体制、格局、规矩等"}, {"w": "统纪", "t": "纲纪"}, {"w": "统类", "t": "纲纪和条例。"}]}, {"meaning": "主管;率领。", "cites": [{"t": "若其所以统之,则无以异于桀纣。", "b": "《荀子·强国》"}, {"t": "反国统万人。", "b": "《战国策·齐策四》"}, {"t": "统兵数万。", "b": "《资治通鉴》"}, {"t": "统军略地。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "统会", "t": "统率会合"}, {"w": "统兵数万;统事", "t": "统理事务"}, {"w": "统楫", "t": "总揽,统领"}, {"w": "统监", "t": "统率监督;驻于保设国或属地的长官。"}]}, {"meaning": "总括;合而为一;统一。", "cites": [{"t": "大一统也。", "b": "《公羊传·隐公元年》"}, {"t": "统楫群元。", "b": "《汉书·儿宽传》"}, {"t": "统大魁以为笙。", "b": "《文选·潘岳·笙赋》"}], "words": [{"w": "一统", "t": "统一"}, {"w": "统税", "t": "货物总纳税一次,其余不再征收者"}, {"w": "统考", "t": "统一考试的简称"}, {"w": "统货", "t": "按统一价格购进或出售的商品"}, {"w": "统捐", "t": "捐税名。货物在一区域内缴税后,可于该地区内通行无阻"}, {"w": "统括", "t": "归纳。总概括"}, {"w": "统一发票", "t": "政府为防止漏税,规定商号一概使用同一种发票"}, {"w": "统括", "t": "总括"}, {"w": "统论(总论):统观(总的观察)", "t": ""}]}, {"meaning": "管理;治理。", "cites": [{"t": "昔者,圣人因阴阳以统天地。", "b": "《列子·天瑞》"}], "words": [{"w": "统内", "t": "管辖范围之内"}, {"w": "统和", "t": "统理协和"}, {"w": "统治", "t": "统率治理"}, {"w": "统理", "t": "统辖治理。"}]}, {"meaning": "犹“通”。"}, {"meaning": "古时用以纪年 。一千五百三十九年为一统。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1766wx','耕','1','gēng','耒','10','','[{"pinyin": "gēng", "defs": [{"meaning": "(形声。从耒(lěi),井声。从“耒”,表示与耕作有关。本义:犁田)。"}, {"meaning": "同本义。翻松田土。", "cites": [{"t": "耕,治田也。", "b": "《正字通》"}, {"t": "耕,犁也。从耒,井声。一曰古者井田,谓从井,会意。", "b": "《说文》。按,人耕曰耕,牛耕曰犁。"}, {"t": "稷之孙曰叔均,是始作牛耕。", "b": "《山海经·海内经》"}, {"t": "凡秋耕欲深,春夏欲浅,犁欲廉。", "b": "《齐民要术·耕田》"}, {"t": "深耕易耨。", "b": "《孟子·梁惠王上》"}, {"t": "耕者忘其犁。", "b": "《乐府诗集·陌上桑》"}, {"t": "长沮、桀溺耦而耕。", "b": "《论语·微子》"}], "words": [{"w": "耕食", "t": "依赖耕田为生"}, {"w": "耕桑", "t": "耕田、种谷、植桑、养蚕。泛指农耕之事"}, {"w": "耕垡", "t": "耕田翻土"}, {"w": "耕植", "t": "耕田种植。"}]}, {"meaning": "种田;播种。", "cites": [{"t": "民之欲利者非耕不得,避害者非战不免,境内之民莫不先务耕战,而后得其所乐。", "b": "《商君书·慎法》"}, {"t": "自耕稼、陶、渔以至为帝,无非取于人者。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "耕牧", "t": "耕种畜牧"}, {"w": "耕战", "t": "耕种与战争"}, {"w": "耕器", "t": "耕种的器具"}, {"w": "耕艺", "t": "泛指耕植。"}]}, {"meaning": "泛指致力于某种工作或事业。", "cites": [{"t": "耕道而得道,猎德而得德。", "b": "汉·扬雄《法言·学行》"}], "words": [{"w": "耕道", "t": "谓致力于研求道之真谛"}, {"w": "笔耕;舌耕;目耕", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1767wx','耘','1','yún','耒','10','','[{"pinyin": "yún", "defs": [{"meaning": "(形声。从耒(lěi),云声。本义:除草)。"}, {"meaning": "同本义。", "cites": [{"t": "植杖而耘耔。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "耘艾", "t": "耕耘与收割。艾同刈"}, {"w": "耘耔", "t": "翻土除草,指农耕"}, {"w": "耘治", "t": "锄草治田"}, {"w": "耘爪", "t": "一种用于水田的除草工具"}, {"w": "耘秽", "t": "铲除杂草"}, {"w": "耘籽", "t": "泛指从事田间劳动。"}]}, {"meaning": "比喻辛勤攻读。", "cites": [{"t": "勉哉耘其业,以待岁晚收。", "b": "唐·韩愈《送刘师服》"}]}, {"meaning": "培土。", "cites": [{"t": "掘荃蕙与射干兮,耘藜藿与蓑荷。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1768wx','耗','1','hào','耒','10','','[{"pinyin": "hào", "defs": [{"meaning": "(形声。从耒(lěi),毛声。本义:一种稻子)。"}, {"meaning": "消息;音信。", "cites": [{"t": "赤岭久无耗,鸿门犹合围。", "b": "李商隐《即日》"}], "words": [{"w": "耗音", "t": "音耗,音信,消息"}, {"w": "耗问", "t": "消息;音信"}, {"w": "耗息", "t": "消息"}, {"w": "恶耗,凶耗", "t": ""}]}, {"meaning": "旧时官府征收钱粮时,以损耗为名,在正额外例有附加部分,称“耗”。"}, {"meaning": "假借为“消”。亏损;消耗。", "cites": [{"t": "耗,消也。", "b": "《苍颉篇》"}, {"t": "永尝敢以耗气也。", "b": "《庄子·达生》。司马注:“损也。”"}, {"t": "改煎金锡则不耗。", "b": "《考工记·函人为量》"}, {"t": "耗,减也。", "b": "《广雅·释诂二》"}, {"t": "亏法以利私,耗国以便家。", "b": "《韩非子·孤愤》"}, {"t": "夫美下而耗上,妨义之本也。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "耗荡", "t": "消耗毁坏"}, {"w": "耗米", "t": "历代从水道转运米粮,每担在正额外另加数斗米,作为沿途耗损之用;对定额所收的正米而言,称之为耗米"}, {"w": "耗失", "t": "减少,损失"}, {"w": "耗力", "t": "耗费力气、力量。"}]}, {"meaning": "损失,受损失;耗费。", "cites": [{"t": "士卒多耗,无尺寸之功。", "b": "《史记·李斯列传》"}], "words": [{"w": "耗敝", "t": "耗费损害"}, {"w": "耗蠹", "t": "耗费损害"}, {"w": "耗燥", "t": "枯竭。"}]}, {"meaning": "歉收。", "cites": [{"t": "五谷皆入,然后制国用。用地小大,视年之丰耗。", "b": "《礼记·王制》"}]}, {"meaning": "土壤瘠薄。", "cites": [{"t": "耗土之人丑。", "b": "《大戴礼记·易本命》。注:“疏薄之地。”"}], "words": [{"w": "耗土", "t": "瘠薄的土地。"}]}, {"meaning": "空虚。", "cites": [{"t": "耗,虚也。", "b": "《玉篇》"}, {"t": "多而乱曰耗。", "b": "《荀子·脩身》。注:“虚竭也。凡物多而易尽曰耗。”"}]}, {"meaning": "零落。", "cites": [{"t": "秋行夏令,华;行春令,荣;行冬令,耗。", "b": "《淮南子》。高诱注:“耗,零落也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1769wx','耙','1','bà pá','耒','10','','[{"pinyin": "bà", "defs": [{"meaning": "用于碎土、平地和消灭杂草的整地农具  按工作部分不同分齿耙、无齿耙、圆盘耙等。"}]}, {"pinyin": "pá", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1770wx','艳','1','yàn','色','10','','[{"pinyin": "yàn", "defs": [{"meaning": "(会意。从豐(fēng),从色。豐,丰大。色,色彩。丰大而有色彩。本义:鲜艳,艳丽)。"}, {"meaning": "同本义。", "cites": [{"t": "艷,好而长也。", "b": "《说文》"}, {"t": "目逆而送之,曰,美而艳。", "b": "《左传·桓公元年》"}, {"t": "艳妻煽方处。", "b": "《诗·小雅·十月之交》"}, {"t": "艳陆离些。", "b": "《楚辞·招魂》。注:“艳,好貌也。”"}, {"t": "窈窕艳城郭。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "艳色", "t": "常用以指美女、美色"}, {"w": "艳段", "t": "宋元杂剧中,在正剧之前表演的一段短剧"}, {"w": "艳质", "t": "美丽的姿质。"}]}, {"meaning": "文辞华丽。", "cites": [{"t": "信言不艳,贯居于好。", "b": "《三国志》"}], "words": [{"w": "艳才", "t": "写作美妙文章的才能"}, {"w": "艳采", "t": "绮丽的文采。"}]}, {"meaning": "过于艳丽的色彩,极为俗气花俏的服饰。", "cites": [{"t": "那日,果然来了几个女人,都是艳装丽服。", "b": "《红楼梦》"}], "words": [{"w": "这布的花色太艳了", "t": ""}]}, {"meaning": "美女。", "cites": [{"t": "吴娃与越艳,窈窕夸铅红。", "b": "《李太白诗》"}], "words": [{"w": "艳波", "t": "美女的眼波"}, {"w": "艳姝", "t": "美女。"}]}, {"meaning": "有关男女爱情方面的事情或著作。", "cites": [{"t": "当她年轻的时候,他们还共同制造过一些动人的艳闻。", "b": "沙汀《淘金记》"}], "words": [{"w": "艳歌", "t": "情歌"}, {"w": "艳约", "t": "情人的约会。"}]}, {"meaning": "照耀;闪耀。", "cites": [{"t": "双歌声断宝杯空,妆光艳瑶席。", "b": "宋·张先《好事近》"}], "words": [{"w": "艳射", "t": "光彩炫耀"}, {"w": "艳晶晶", "t": "光彩闪耀的样子"}, {"w": "艳耀", "t": "照耀,炫耀。"}]}, {"meaning": "羡慕。", "cites": [{"t": "略无慕艳意。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "艳称", "t": "称羡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1771wx','泰','1','tài','水','10','','[{"pinyin": "tài", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "泰,亦作汰。疑泰、太、汰三形实同字。", "b": "朱骏声《说文通训定声》"}]}, {"meaning": "安定平和。", "cites": [{"t": "泰,安也。", "b": "《字汇》"}, {"t": "宇泰定者,发乎天光。", "b": "《庄子·庚桑楚》"}, {"t": "泰而不骄,威而不猛。", "b": "《论语·尧曰》"}, {"t": "以祈国泰民安。", "b": "吴自牧《梦梁录》"}, {"t": "家贫躬耕,粟熟则食粟,…处之泰然也。", "b": "《元史·许衡传》"}, {"t": "否泰如天地。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "泰日", "t": "天下太平的时代"}, {"w": "泰治", "t": "太平安定"}, {"w": "泰定", "t": "安定"}, {"w": "泰和", "t": "太平"}, {"w": "泰平", "t": "政教清平,国泰民安。即太平"}, {"w": "泰通", "t": "国泰政通。"}]}, {"meaning": "奢侈。", "cites": [{"t": "泰,侈也。", "b": "《玉篇》"}, {"t": "约而为泰,难乎有恒矣。", "b": "《论语·述而》"}], "words": [{"w": "泰侈", "t": "骄纵奢侈"}, {"w": "泰靡", "t": "奢靡。"}]}, {"meaning": "骄纵;傲慢。", "cites": [{"t": "骄泰奢侈。", "b": "《国语·晋语》"}, {"t": "以泰于国。", "b": ""}, {"t": "是故君子有大道,必忠信以得之,骄泰以失之。", "b": "《礼记》"}]}, {"meaning": "大之极,极大。", "cites": [{"t": "泰,大也。", "b": "《易·泰卦》释文引马注"}, {"t": "遇泰之需。", "b": "《左传·哀公九年》。疏:“泰者,大也。”"}, {"t": "假尔泰龟有常。", "b": "《礼记·曲礼上》。疏:“泰者,大中之大也。”"}, {"t": "不以泰乎?", "b": "《孟子·滕文公下》"}], "words": [{"w": "泰河", "t": "大河"}, {"w": "泰吕", "t": "大吕"}, {"w": "泰武", "t": "强大的武力"}, {"w": "泰运", "t": "大运,天运"}, {"w": "泰风", "t": "大风,西风。"}]}, {"meaning": "古州名。"}, {"meaning": "五代唐置,明代改称保定府,治所在河北省清苑县。今为保定市。"}, {"meaning": "南唐置,治所在海陵(今江苏省泰州市)。"}, {"meaning": "县名 。在江苏省中部。汉置海陵县,明为泰州,1912年改为泰县。1949年后拆置泰州市。"}, {"meaning": "六十四卦之一。", "cites": [{"t": "象曰:天地交,泰。", "b": "《易·泰》"}]}, {"meaning": "泰国的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1772wx','秦','1','qín','禾','10','','[{"pinyin": "qín", "defs": [{"meaning": "(会意。从禾,从舂省。本义:禾名。假借为专名用字)。"}, {"meaning": "秦,部落名 。嬴姓。相传是伯益的后代。", "cites": [{"t": "秦,伯益之后所封国。", "b": "《说文》。朱骏声曰:“地宜禾,在今甘肃秦州清水县。”"}]}, {"meaning": "古国名 。秦襄公始立国,孝公时,成为战国七雄之一,定都咸阳。"}, {"meaning": "朝代名(公元前221—公元前206年),是由周朝的秦国(在今陕西甘肃一带)统一全中国后建立的中国历史上第一个中央集权的朝代。", "cites": [{"t": "秦王不说。", "b": "《战国策·魏策》"}, {"t": "秦灭韩亡魏。", "b": ""}, {"t": "秦王色挠。", "b": ""}], "words": [{"w": "秦越肥瘠", "t": "喻指相去遥远,互不相关"}, {"w": "秦庭鹿", "t": "指秦朝的政权。"}]}, {"meaning": "汉时西域诸国沿称中国为秦。", "cites": [{"t": "昔为形与影,今为胡与秦。", "b": "《乐府诗选》"}], "words": [{"w": "秦人", "t": "秦代统一后,北方与西方邻国往往称中国人为秦人"}, {"w": "秦地", "t": "汉时西域诸国对中国的称呼。"}]}, {"meaning": "蝉的一种。螓首。", "cites": [{"t": "其尺索刺麤而毛美秦发。", "b": "《史记·扁鹊仓公列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1773wx','珠','1','zhū','王','10','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从玉,朱声。本义:珍珠。蛤蚌壳内由分泌物结成的有光小圆体)。"}, {"meaning": "同本义。", "cites": [{"t": "珠,蚌之阴精。", "b": "《说文》。按,水精也,或生于蚌,阴精所凝。"}, {"t": "珠足以御火灾。", "b": "《国语·楚语》"}, {"t": "水方折者有玉,员折者有珠。", "b": "《尸子》"}, {"t": "渊生珠而岸不枯。", "b": "《淮南子·说山》"}, {"t": "珠盘玉敦。", "b": "《周礼·玉府》"}, {"t": "大珠四枚。", "b": "明·崔铣《记王忠肃公翱三事》"}]}, {"meaning": "又。", "cites": [{"t": "所货西洋珠。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "公受珠。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "出珠授之。", "b": ""}], "words": [{"w": "珠户", "t": "采珠的民户;珠饰的门户"}, {"w": "珠履", "t": "以珍珠为饰的鞋子"}, {"w": "珠碧", "t": "珍珠与碧玉"}, {"w": "珠英", "t": "美如珍珠的花"}, {"w": "珠翠", "t": "珍珠与翠玉"}, {"w": "珠市", "t": "买卖珍珠的集市。"}]}, {"meaning": "珠玉。", "cites": [{"t": "琴号珠柱,书名《玉杯》。", "b": "庾信《小园赋》"}], "words": [{"w": "珠椟", "t": "盛放珠宝的匣子"}, {"w": "珠丸", "t": "用珠玉做的弹丸"}, {"w": "珠箔", "t": "用珠子缀成的帘子。"}]}, {"meaning": "以球形或椭球形体滴下的液体。", "cites": [{"t": "白雨跳珠乱入船。", "b": "苏轼《六月二十七日望湖楼醉书》"}], "words": [{"w": "泪珠;汗珠;露珠", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1774wx','班','1','bān','王','10','','[{"pinyin": "bān", "defs": [{"meaning": "(会意。从玨,从刀。金文,中间是刀,左右是玉。象用刀割玉。本义:分割玉)。"}, {"meaning": "分瑞玉。瑞玉是古代玉质的信物,中分为二,各执其一以为信。", "cites": [{"t": "班,分瑞玉也。", "b": "《说文》"}, {"t": "班瑞于群后。", "b": "《书·舜典》"}], "words": [{"w": "班瑞", "t": "颁还瑞玉;颁赐祥瑞。"}]}, {"meaning": "分开;离群。", "cites": [{"t": "挥手自兹去,萧萧班马鸣。", "b": "李白《送友人》"}], "words": [{"w": "班马", "t": ""}]}, {"meaning": "赏赐;分给。", "cites": [{"t": "晋侯执曹伯,班其所取侵地于诸侯也。", "b": "《公羊传·僖公三十一年》"}], "words": [{"w": "班扬符赏", "t": "颁布相应的赏赐"}, {"w": "班授", "t": "颁发授予"}, {"w": "班散", "t": "分给"}, {"w": "班赐", "t": "颁赐;分赏。"}]}, {"meaning": "分布;铺开。", "cites": [{"t": "遇之于郑郊,班荆相与食。", "b": "《左传·襄公二十六年》"}], "words": [{"w": "班卖", "t": "摊开出卖"}, {"w": "班荆", "t": ""}]}, {"meaning": "颁布", "cites": [{"t": "周公…制礼乐,班度量,而下大服。", "b": "《汉书·翟方进传》"}], "words": [{"w": "班政", "t": "颁布政令"}, {"w": "班论", "t": "颁布"}, {"w": "班布", "t": "犹公布。"}]}, {"meaning": "返回。", "cites": [{"t": "请班师。", "b": "《左传·襄公十年》。注:“还也。”"}], "words": [{"w": "班军", "t": "回师,撤军"}, {"w": "班旋", "t": "犹班师。"}]}, {"meaning": "排列。", "cites": [{"t": "班位于天下。", "b": "《韩非子·存韩》"}]}, {"meaning": "职位等次,位次;等级。", "cites": [{"t": "班在九人。", "b": "《左传·文公六年》。注:“位也。”"}, {"t": "徐勉为吏部尚书,定为十八班。", "b": "《隋书·百官志》"}], "words": [{"w": "班秩", "t": "官员的品级"}, {"w": "班禄", "t": "班位和俸禄"}, {"w": "班资", "t": "官阶和资格。"}]}, {"meaning": "序列;排列等级。", "cites": [{"t": "班,次也。", "b": "《小尔雅》"}, {"t": "班,列也。", "b": "《方言三》"}, {"t": "班,序也。", "b": "《广雅》"}], "words": [{"w": "按部就班;班次", "t": "补授或提升官职的先后次序"}, {"w": "班列", "t": "按班排列。"}]}, {"meaning": "引申朝班。指朝庭上臣下所站的队列。", "cites": [{"t": "班朝治军。", "b": "《礼记·曲礼》"}, {"t": "使鲁为其班。", "b": "《左传·桓公六年》"}], "words": [{"w": "班部", "t": "大臣在朝见时按次序排成的行列"}, {"w": "班台", "t": "古代以司马、司空、司徒为三台,故以泛称朝官之前列显要者。"}]}, {"meaning": "杂色,亦指杂色斑点或斑纹。", "cites": [{"t": "纷总总其离合兮,班陆离其上下。", "b": "屈原《离骚》"}, {"t": "有妇人出于室者,发班白,衣缁布之衣。", "b": "《晏子春秋·外篇》"}, {"t": "班白者不徒行。", "b": "《韩非子·外储说左》"}], "words": [{"w": "班衣戏彩", "t": "《二十四孝》中的故事。言年已古稀的老莱子,身穿花衣,手持玩具,作儿童状以取悦双亲"}, {"w": "班驳", "t": "杂色,色彩斑斓。"}]}, {"meaning": "用于人群。", "cites": [{"t": "忙出来吩咐雇了两班脚子。", "b": "《儒林外史》"}], "words": [{"w": "一班人马", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1775wx','素','1','sù','糸','10','','[{"pinyin": "sù", "defs": [{"meaning": "(会意。小篆字形。上是“垂”,下是糸(mì)。糸,丝。织物光润则易于下垂。本义:没有染色的丝绸)。"}, {"meaning": "同本义。", "cites": [{"t": "素,白致缯也。", "b": "《说文》"}, {"t": "纯以素。", "b": "《礼记·杂记》"}, {"t": "素服哭于库门之外。", "b": "《礼记·檀弓》"}, {"t": "十三能织素,十四学裁衣。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "若士必奴,伏尸二人,流血五步,天下缟素,今日是也。", "b": "《战国策·魏策》"}], "words": [{"w": "素幭", "t": "古代盖在车前横木上的白绸"}, {"w": "素服缟冠", "t": "丧服,素、缟,指白绘。"}]}, {"meaning": "用作写字的丝绸或纸张。", "cites": [{"t": "英骨秀气,洒落毫素。", "b": "唐·李白《化城寺大钟铭》"}]}, {"meaning": "又指用绢帛纸张写的书籍或信件。", "cites": [{"t": "客从远方来,遗我双鲤鱼。呼儿烹鲤鱼,中有尺素书。", "b": "古乐府《饮马长城窟行》"}]}, {"meaning": "本质;本性。", "cites": [{"t": "如彼梓材,弗勤丹漆,虽劳朴斫,终负素质。", "b": "《文选·张华·励志诗》"}], "words": [{"w": "根素", "t": "根本"}, {"w": "素怀", "t": "本心。"}]}, {"meaning": "蔬菜瓜果等副食。", "cites": [{"t": "古之民未知为饮食时,素食而分处。", "b": "《墨子·辞过篇》"}, {"t": "果蓏素食当十石。", "b": "《管子·禁藏》"}], "words": [{"w": "三荤一素;吃素;素什锦", "t": "杂取诸种蔬菜配合而成的一种素肴"}, {"w": "素膳", "t": "素食。"}]}, {"meaning": "旧交。", "cites": [{"t": "素友俱薄世,屡招清景赏。", "b": "唐·韦应物《慈恩伽蓝清会》"}], "words": [{"w": "素故", "t": "旧交"}, {"w": "素情", "t": "旧交,旧情"}, {"w": "素结", "t": "故交"}, {"w": "素旧", "t": "旧交。"}]}, {"meaning": "姓 。三国魏有素利。"}, {"meaning": "白色,雪白。", "cites": [{"t": "秦伯素服郊次,乡向而器。", "b": "《左传·僖公三十二年》"}, {"t": "服尚素玄。", "b": "班固《东都赋》"}, {"t": "娥娥红粉妆,纤纤出素手。", "b": "《古诗十九首》"}, {"t": "要什么素车白马,断送出古陌荒阡?", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "素纸", "t": "白纸;没有写过字的纸"}, {"w": "素衣将敝", "t": "比喻人处境艰难,生活困苦"}, {"w": "素练", "t": "白色的熟绢"}, {"w": "素车", "t": "以白土涂饰的车"}, {"w": "素风", "t": "秋风"}, {"w": "素秋", "t": "即秋季,古代阴阳五行家以金配秋,其色白,故称秋季为“素秋”"}, {"w": "素娥", "t": "指月宫中仙女“嫦娥”。因月色白,故称“素娥”。"}]}, {"meaning": "质朴;不加装饰。", "cites": [{"t": "谈笑有鸿儒,往来无白丁。可以调素琴,阅金经。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "众人皆以奢靡为贵,吾心独以俭素为美。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "素碑", "t": "没有刻字的石碑"}, {"w": "素一", "t": "纯朴简约"}, {"w": "素冠", "t": "素朴无饰的练冠"}, {"w": "素室", "t": "朴实而不加华饰的房间"}, {"w": "素琴", "t": "无装饰的琴"}, {"w": "素妆", "t": "淡妆"}, {"w": "素几", "t": "不加雕饰的小几"}, {"w": "素面朝天", "t": "不加妆饰而面见天子。"}]}, {"meaning": "空,有名无实或有实无名。", "cites": [{"t": "彼君子兮,不素飧兮。", "b": "《诗·魏风·伐檀》"}, {"t": "孔子作《春秋》以示王意,然则孔子之《春秋》,素王之业也;诸子之传书,素相之事也。", "b": "汉·王充《论衡超奇》"}], "words": [{"w": "素放", "t": "无条件释放"}, {"w": "素王", "t": "指有王者之道而无王者之位的人"}, {"w": "素封", "t": "没有官爵封邑但和封君一样富有的人家"}, {"w": "素手", "t": "空手;不带礼物"}, {"w": "素功", "t": "素王的功业"}, {"w": "素官", "t": "没有实际权力的闲官。"}]}, {"meaning": "平素,往常,旧时。", "cites": [{"t": "而五人生于编伍之间,素不闻诗书之训。", "b": "明·张溥《五人墓碑记》"}, {"t": "即入闾左呼子弟素健者,得数十人,遮豪民于道。", "b": "明·高启《书博鸡者事》"}, {"t": "宦官黄锦在侧曰:“此人素有痴 名。”", "b": "《明史·海瑞传》"}], "words": [{"w": "素位", "t": "平日所处的地位"}, {"w": "素守", "t": "平素的操守"}, {"w": "素抱", "t": "平素的志趣、抱负"}, {"w": "素衷", "t": "平素的心意"}, {"w": "素期", "t": "平素所期望的"}, {"w": "素意", "t": "平素的意愿"}, {"w": "素怀", "t": "平素的怀抱"}, {"w": "素著", "t": "一向都很著名"}, {"w": "素孚", "t": "平时很得人心;一贯深受众望。"}]}, {"meaning": "寒素,低微。", "cites": [{"t": "文帝使人问诩自固之术,诩曰:“愿将军恢崇德度,躬素士之业,朝夕孜孜,不违子道,如此而已。", "b": "《三国志·贾诩传》"}], "words": [{"w": "素士", "t": "布衣之士;贫寒的读书人"}, {"w": "素姓", "t": "平民,百姓"}, {"w": "素品", "t": "低微的门第"}, {"w": "素室", "t": "寒门"}, {"w": "素流", "t": "寒素之辈。指门第低微的人"}, {"w": "素族", "t": "寒门"}, {"w": "素门", "t": "清寒之家。与世族豪门相对。"}]}, {"meaning": "诚心的,真情的。", "cites": [{"t": "夫公孙鞅事孝公,极身毋二,…竭智能,示情素。", "b": "《战国策》"}, {"t": "愿诚素之先达兮,解玉佩以要之。", "b": "曹植《洛神赋》"}]}, {"meaning": "预先。", "cites": [{"t": "夫谋,必素见成事焉,而后履之。", "b": "《国语·吴语》"}], "words": [{"w": "素脩", "t": "预先早作准备"}, {"w": "素构", "t": "预先构思草拟"}, {"w": "素赏", "t": "预先行赏"}, {"w": "素定", "t": "预先确定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1776wx','匿','1','nì','匚','10','','[{"pinyin": "nì", "defs": [{"meaning": "(形声。从匚(xǐ),若声(上古读音与匿声相近)。“匚”表示有所藏。本义:隐藏,躲藏)。"}, {"meaning": "同本义。", "cites": [{"t": "匿,亡也。", "b": "《说文》"}, {"t": "匿,藏也。", "b": "《广雅》"}, {"t": "瑾瑜匿瑕。", "b": "《左传·宣公十五年》。注:“亦藏也。”"}, {"t": "而知匿其暱。", "b": "《左传·襄公二十五年》。注:“藏也。”"}, {"t": "匿怨而友其人。", "b": "《论语》。皇疏:“藏也。”"}, {"t": "引车避匿。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "又。", "cites": [{"t": "君畏匿之。", "b": ""}, {"t": "匿于溷藩以免。(藏在厕所里。溷,厕所。藩,篱、墙。)", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "隐匿", "t": "隐藏;躲起来"}, {"w": "藏匿", "t": "藏起来不让人发现"}, {"w": "匿光", "t": "隐藏其光华。比喻才德不外露"}, {"w": "匿怨", "t": "内心隐藏怨恨"}, {"w": "匿意", "t": "隐藏真情"}, {"w": "匿谋", "t": "隐藏其谋略。"}]}, {"meaning": "隐瞒。", "cites": [{"t": "闻崔烈集门生讲传,遂匿姓名,为烈名人质作食。", "b": "《世说新语·文学》"}, {"t": "过举不匿,则官无邪人。", "b": "《商君书·垦令》"}], "words": [{"w": "匿户", "t": "隐瞒不报的户籍"}, {"w": "匿心", "t": "隐瞒真实思想"}, {"w": "匿年", "t": "不肯把真实年龄告人"}, {"w": "匿作", "t": "隐瞒姓名而劳作"}, {"w": "匿訑", "t": "隐瞒欺诈"}, {"w": "匿悃", "t": "隐瞒实情"}, {"w": "匿情", "t": "隐瞒真情"}, {"w": "匿善", "t": "隐瞒才能。"}]}, {"meaning": "假借为“慝”。恶,坏。", "cites": [{"t": "常令不审,则百匿胜。", "b": "《管子·七法》"}, {"t": "故道之所善,中则可从,畸则不可为。匿则大惑。", "b": "《荀子·天论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1777wx','蚕','1','cán','虫','10','','[{"pinyin": "cán", "defs": [{"meaning": "(形声。本义:一种能吐丝结茧的昆虫)。"}, {"meaning": "同本义 。有家蚕、柞蚕等。蚕丝为重要的纤维资源。", "cites": [{"t": "遍身罗绮者,不是养蚕人。", "b": "宋·张俞《蚕妇》"}], "words": [{"w": "蚕舍", "t": "蚕屋。蚕房"}, {"w": "蚕精", "t": "蚕神"}, {"w": "蚕蜕", "t": "蚕眠期所脱的皮。"}]}, {"meaning": "蚕事。养蚕的工作。", "cites": [{"t": "罗敷善蚕桑。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "蚕功", "t": "蚕事"}, {"w": "蚕母", "t": "古时主管蚕事的女官。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1778wx','顽','1','wán','页','10','','[{"pinyin": "wán", "defs": [{"meaning": "(形声。从页(xié),元声。从页。本义:难劈开的囫囵木头)。"}, {"meaning": "同本义。", "cites": [{"t": "纤枝无萧洒,顽干空突兀。", "b": "唐·元稹《画松》"}]}, {"meaning": "凶恶的人。", "cites": [{"t": "岂惜战斗死,为君扫凶顽。", "b": "唐·李白《豫章行》"}]}, {"meaning": "引申为浑圆。", "cites": [{"t": "闻平乐以下,四顾皆土山,而巉厉之石,不挺于陆而藏于水矣。盖山自此而顽,水自此而险也。", "b": "《徐霞客游记》"}]}, {"meaning": "顽固,不驯服。", "cites": [{"t": "顽童穷固。", "b": "《国语·郑语》"}], "words": [{"w": "顽算", "t": "耍弄,算计"}, {"w": "刁顽", "t": "狡猾顽固"}, {"w": "顽户", "t": "旧时官府指拖欠赋税之家"}, {"w": "顽陋", "t": "顽固鄙陋"}, {"w": "顽竖", "t": "顽劣的小子"}, {"w": "顽躯", "t": "顽健的身体"}, {"w": "顽猾", "t": "顽皮狡猾。"}]}, {"meaning": "头脑迟钝; 愚蠢。", "cites": [{"t": "顽,愚也。", "b": "《广雅·释诂一》"}, {"t": "父顽。", "b": "《书·尧典》"}, {"t": "疑自苗人顽,恃险不终役。", "b": "白居易《自蜀江至洞庭湖口有感而作》"}], "words": [{"w": "冥顽不灵;顽仙", "t": "愚笨无知的仙人"}, {"w": "顽昧", "t": "顽劣无知"}, {"w": "顽疏", "t": "愚劣粗疏"}, {"w": "顽卤", "t": "愚昧钝迟。或作“顽鲁”"}, {"w": "顽贪", "t": "顽愚贪婪"}, {"w": "顽恶", "t": "愚蠢桀骜"}, {"w": "顽愚", "t": "愚鲁,资质低下迟钝"}, {"w": "顽鄙", "t": "顽钝鄙拙。"}]}, {"meaning": "坚硬。", "cites": [{"t": "蛮兵如此顽皮,非火攻安能取胜?", "b": "《三侠五义》"}], "words": [{"w": "顽皮", "t": "皮甲坚硬"}, {"w": "顽铁", "t": "坚硬的铁"}, {"w": "顽金", "t": "坚硬的金属"}, {"w": "顽块", "t": "硬土块"}, {"w": "顽重", "t": "又硬又重"}, {"w": "顽肉", "t": "坏死硬化之肉。"}]}, {"meaning": "坚强。", "cites": [{"t": "耄期尚有江湖兴,顽健人言见未曾。", "b": "宋·陆游《示二子》"}]}, {"meaning": "同“玩”。游戏。", "cites": [{"t": "拜了拜本州,就到上海去顽了这多少日子。", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "顽耍子", "t": "玩耍;游逛"}, {"w": "顽不开", "t": "应付不了"}, {"w": "顽耍", "t": "嬉戏,玩乐"}, {"w": "顽游", "t": "顽耍,游玩"}, {"w": "顽具", "t": "玩具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1779wx','盏','1','zhǎn','皿','10','','[{"pinyin": "zhǎn", "defs": [{"meaning": "(形声。从皿,戔(jiān)声。从皿,表示与器皿有关。本义:浅而小的杯子) 同本义。", "cites": [{"t": "横飞玉盏家山晓,远蹀金珂塞草春。", "b": "唐·韩愈《酬振武胡十二丈》诗"}], "words": [{"w": "把盏", "t": "端着酒杯敬客"}, {"w": "盏斝", "t": "泛指酒杯。"}]}, {"meaning": "酒、茶或灯的计量单位。", "cites": [{"t": "那妇人拿起一盏茶来,把帕子去茶盅口边一抹,双手递与和尚。", "b": "《水浒传》"}], "words": [{"w": "红灯一盏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1780wx','匪','1','fěi','匚','10','','[{"pinyin": "fěi", "defs": [{"meaning": "(形声。从匚(fāng),盛物之器。非声。本义:“篚”的古字。竹器,形似竹箧)。"}, {"meaning": "同本义。", "cites": [{"t": "匪,器似竹筐。", "b": "《说文》。按,古者盛币帛以匪,其器椭方。"}, {"t": "共设匪瓮之礼。", "b": "《周礼·肆师》"}]}, {"meaning": "五色相错 斐。", "cites": [{"t": "有匪君子,如切如瑳。", "b": "《诗·卫风·淇奥》"}]}, {"meaning": "假借为“非”,表示否定。", "cites": [{"t": "匪寇,昏媾。", "b": "《易·屯卦》"}, {"t": "比之匪人。", "b": "《易·比卦》"}, {"t": "匪夷所思。", "b": "《易·涣卦》"}, {"t": "先祖匪人。", "b": "《诗·小雅·四月》"}, {"t": "我心匪石,不可转也。", "b": "《诗·邶风·柏舟》"}, {"t": "匪女之为美,美人之贻。", "b": "《诗·邶风·北风》"}], "words": [{"w": "匪懈", "t": "不懈怠,不怠情"}, {"w": "匪独", "t": "不单是"}, {"w": "匪惟", "t": "不是"}, {"w": "匪夷", "t": "不寻常。"}]}, {"meaning": "表示否定,相当于“无”。", "cites": [{"t": "深言匪由衷,白首为无误。", "b": "明·何景明《送崔氏》"}], "words": [{"w": "匪什", "t": "无篇什,谓没有写作才能"}, {"w": "匪止", "t": "不止"}, {"w": "匪啻", "t": "不止,不只"}, {"w": "匪惶", "t": "没有闲暇;来不及。"}]}, {"meaning": "表示关联,用于“非…不…”之类的句式。", "cites": [{"t": "匪安匪舒。", "b": "《诗·大雅·江汉》"}, {"t": "匪富匪势,穷年无冀。", "b": "《抱朴子·外篇·吴失》"}]}, {"meaning": "不仅,不但。", "cites": [{"t": "匪手携之,言示之事;匪面命之,言提其耳。", "b": "《诗·大雅》"}]}, {"meaning": "(bǐ)。那,那个。", "cites": [{"t": "如匪行迈谋,是用不得于道。", "b": "《诗·小雅·小旻》"}, {"t": "彼交匪纾,天子所予。", "b": "《韩诗外传·卷四》"}]}, {"meaning": "行为不正。", "cites": [{"t": "不幸见辱于匪人。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "匪辟", "t": "不正派;邪恶"}, {"w": "匪人", "t": "匪类。行为不端的人;不是亲近的人;盗寇"}, {"w": "匪劣", "t": "品行恶劣的人"}, {"w": "匪昵", "t": "行为不端的亲信。"}]}, {"meaning": "(fēn)。分配。", "cites": [{"t": "以九式的均节财用,…八曰匪颁之式。", "b": "《周礼·天官·大宰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1781wx','捞','1','lāo','扌','10','','[{"pinyin": "lāo", "defs": [{"meaning": "(形声。从手,劳声。本义:从水中寻取东西)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1782wx','栽','1','zāi','木','10','','[{"pinyin": "zāi", "defs": [{"meaning": "(形声本义:筑墙立板)。"}, {"meaning": "同本义。", "cites": [{"t": "栽,筑墙长版也。", "b": "《说文》。古筑墙之法,既度其广轮,先植桢于两头,又植干于两边,而后横施版于干内,以绳束干,实土筑之,一版竣,则层累而上,五版为堵。"}, {"t": "庚寅栽。", "b": "《左传·定公元年》"}, {"t": "里而栽。", "b": "《左传·哀公元年》。注:“设版筑也。”"}, {"t": "凡土功…水昏正而栽。", "b": "《左传》。杜预注:“谓今十月,定昏星而中,于是树板干而兴作。”"}]}, {"meaning": "种植。", "cites": [{"t": "栽,种也。", "b": "《广韵》"}, {"t": "故栽者培之。", "b": "《礼记·中庸》"}, {"t": "花木成畦手自栽。", "b": "王安石《书湖阴先生壁》"}], "words": [{"w": "栽树;栽莳", "t": "栽种,移植"}, {"w": "栽接", "t": "栽培接种。"}]}, {"meaning": "捏造假证嫁祸于清白无罪的人。", "cites": [{"t": "哥啊,不要栽人吗?", "b": "《西游记》"}], "words": [{"w": "栽陷", "t": "栽赃陷害"}, {"w": "栽上罪名;栽害", "t": "诬害"}, {"w": "栽人", "t": "捉弄人,陷害人"}, {"w": "栽划", "t": "犹栽诬"}, {"w": "栽埋", "t": "犹栽赃。"}]}, {"meaning": "跌;摔。", "cites": [{"t": "我何苦叫他栽我一下呢?", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "栽了一交;栽更头", "t": "栽跟头"}, {"w": "栽斤斗", "t": "栽跟头"}, {"w": "栽倒", "t": "跌倒、摔倒。"}]}, {"meaning": "秧子,可以移植的植物幼苗。", "cites": [{"t": "朱草之茎如针,紫芝之栽如豆。", "b": "《论衡·初禀》"}], "words": [{"w": "桃栽;栽蘖", "t": "幼苗。嫩芽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1783wx','捕','1','bǔ','扌','10','','[{"pinyin": "bǔ", "defs": [{"meaning": "(形声。从手,甫声。捕的原始意义是追捕逃亡的奴隶。本义:捕捉,捉拿)。"}, {"meaning": "同本义。", "cites": [{"t": "捕,取也。", "b": "《说文》"}, {"t": "遣吏分曹逐捕诸灌氏支属。", "b": "《汉书·灌夫传》"}, {"t": "吏无追甫之苦。", "b": "《汉书·韩延寿传》"}, {"t": "变斗杀伤捕伍邻。", "b": "《急就篇》"}, {"t": "至高邮,制府檄下,几以捕系死。", "b": "文天祥《指南录·后序》"}, {"t": "他郡国吏欲来捕亡人者,讼共禁弗予。", "b": "《史记·吴王濞列传》"}, {"t": "捕鼠不如狸狌。", "b": "《庄子·秋水》"}, {"t": "捕影而视之。", "b": "《周髀算经》"}, {"t": "武陵人捕鱼为业。", "b": "晋·陶渊明《桃花源记》"}, {"t": "捕者既不至。", "b": "清·梁启超《谭嗣同传》"}, {"t": "而吾以捕蛇独存。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "捕鱼;捕快", "t": "旧时官府中专事捉拿强盗的差役"}, {"w": "捕书", "t": "清代地方衙门掌管捕捉罪犯的书吏"}, {"w": "捕生", "t": "捕捉野生动物。"}]}, {"meaning": "追寻,搜寻。", "cites": [{"t": "而抄捕南海馆之报忽至。", "b": "清·梁启超《谭嗣同传》"}, {"t": "诏使孺卿逐捕。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "捕援", "t": "索求推举。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1784wx','埂','1','gěng','土','10','','[{"pinyin": "gěng", "defs": [{"meaning": "(形声。从土,更声。本义:小坑)。"}, {"meaning": "同本义。", "cites": [{"t": "埂,秦谓坑为埂。", "b": "《说文》"}, {"t": "埂,小坑也。", "b": "《玉篇》"}]}, {"meaning": "田埂,田与田之间便于人走路或蓄水用的高起的长条地方。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1785wx','捂','1','wǔ','扌','10','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从手,吾声。本义:用手扪住)。"}, {"meaning": "抵触。", "cites": [{"t": "人心不同,闻见异辞,班氏所谓疏略抵捂者,依违不悉辩也。", "b": "《史记集解》"}]}, {"meaning": "撑持;斜拄。", "cites": [{"t": "到得这家计坏了,更支捂不住。", "b": "《朱子语类》"}]}, {"meaning": "没入;陷入。", "cites": [{"t": "他用手把蒿草下边的沙刨开,果真找见了湿沙子。他把嘴捂在沙子里吸呀吸呀,什么水分也吸不出。", "b": "杜鹏程《保卫延安》"}]}, {"meaning": "逆;对面。", "cites": [{"t": "若无器,则捂受之。", "b": "《仪礼·既夕礼》。贾公彦疏:“捂即逆也,对面相逢受也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1786wx','振','1','zhèn','扌','10','','[{"pinyin": "zhèn", "defs": [{"meaning": "(形声。从手,辰声。本义:赈济;救济)。"}, {"meaning": "同本义。", "cites": [{"t": "振,举救也。", "b": "《说文》"}, {"t": "振,救也。", "b": "《小尔雅·广言》"}, {"t": "三曰振穷。", "b": "《周礼·大司徒》"}, {"t": "踣弊不振。", "b": "《国语·周语》"}, {"t": "君子以振民育德。", "b": "《易·蛊》。"}], "words": [{"w": "振恤", "t": "赈济"}, {"w": "振贷", "t": "赈济"}, {"w": "振业", "t": "救济之使有产业"}, {"w": "振穷", "t": "救助困穷的人。"}]}, {"meaning": "挽救;救治。", "cites": [{"t": "智困于内而政乱于外,则忘不可振也。", "b": "《韩非子·五蠹》。"}], "words": [{"w": "振理", "t": "救治"}, {"w": "振除", "t": "救治。"}]}, {"meaning": "抖动;摇动。", "cites": [{"t": "振,动也。", "b": "《广雅·释诂一》"}, {"t": "举若振槁。", "b": "《史记·礼书》"}, {"t": "蛰虫始振。", "b": "《礼记·月令》"}, {"t": "六月莎鸡振羽。", "b": "《诗·豳风·七月》"}, {"t": "果敢而振。", "b": "《荀子·荣辱》"}, {"t": "必振衣。", "b": "《史记·屈原贾生列传》"}, {"t": "迁我如振落叶。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "振衣裳。", "b": "清·方苞《左宗毅公逸事》"}]}, {"meaning": "举起;挥动。", "cites": [{"t": "振长策而御宇内。", "b": "贾谊《过秦论》"}, {"t": "然陵振臂一呼,创病皆起。", "b": "李陵《答苏武书》。"}], "words": [{"w": "振羽", "t": "鼓翅"}, {"w": "振豪", "t": "竖起的细毛。"}]}, {"meaning": "震憾;震惊。", "cites": [{"t": "被抑枉而自诬,事无苦而振慑者,怯人也。", "b": "《抱朴子·行品》"}, {"t": "如有地动,尊则振龙。", "b": "《后汉书·张衡传》"}]}, {"meaning": "又。", "cites": [{"t": "振声激扬。", "b": ""}, {"t": "振之以威怒。", "b": "唐·魏征《谏太宗十思疏》。"}], "words": [{"w": "振主", "t": "臣下震动君主"}, {"w": "振色", "t": "震怒变色"}, {"w": "振怒", "t": "震怒"}, {"w": "振恐", "t": "震惊;恐惧"}, {"w": "振悚", "t": "震惊。"}]}, {"meaning": "整治,整顿 [reorganize］。", "cites": [{"t": "班师振旅。", "b": "《书·大禹谟》。"}], "words": [{"w": "振兵", "t": "整顿部队"}, {"w": "振旅", "t": "整顿部队"}, {"w": "振饬", "t": "整顿"}, {"w": "振举", "t": "整顿恢复"}, {"w": "振核", "t": "整顿考核"}, {"w": "振容", "t": "整容"}, {"w": "振饰", "t": "整理修饰。"}]}, {"meaning": "振作;奋起。", "cites": [{"t": "蹶而不复振。", "b": "宋·苏轼《教战守》。"}], "words": [{"w": "振顿", "t": "振作"}, {"w": "振举", "t": "振作;整顿"}, {"w": "振矜", "t": "振作;自尊"}, {"w": "振起", "t": "兴起;奋起。"}]}, {"meaning": "消除。", "cites": [{"t": "贤者死忠以振疑,百姓寓焉。", "b": "《管子》。"}], "words": [{"w": "振耻", "t": "除去耻辱"}, {"w": "振蛊", "t": "清除积弊。"}]}, {"meaning": "发出;生长。", "cites": [{"t": "木体实而花萼振。", "b": "刘勰《文心雕龙》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1787wx','载','1','zǎi zài','车','10','','[{"pinyin": "zǎi", "defs": [{"meaning": "年(唐虞时代用于年名)。", "cites": [{"t": "夏曰岁,商曰祀,周曰年,唐虞曰载。", "b": "《尔雅·释天》"}, {"t": "朕在位七十载。", "b": "《书·尧典》"}, {"t": "汉兴,至孝文四十有余载。", "b": "《史记·文帝本纪》"}], "words": [{"w": "载祀", "t": "年。"}]}, {"meaning": "记载,写在一定的册页里,有郑重的色彩。", "cites": [{"t": "夫有勋而不废,有绩而载。", "b": "《左传·昭公十五年》"}, {"t": "推而广之,不可胜载矣。", "b": "萧统《文选序》"}], "words": [{"w": "登载", "t": "在报刊上印出"}, {"w": "刊载", "t": "在报纸刊物上登载"}, {"w": "记载", "t": "把事情写下来"}, {"w": "附载", "t": "附带记录"}, {"w": "转载", "t": "报刊上刊登别的报刊上发表过的文章"}, {"w": "连载", "t": "连续刊载"}, {"w": "载列", "t": "记载。"}]}, {"meaning": "描绘。", "cites": [{"t": "成功遂事,莫知其状,图弗能载,名弗能举。", "b": "《鶡冠子》"}]}]}, {"pinyin": "zài", "defs": [{"meaning": "(形声。本义:乘坐)。"}, {"meaning": "同本义。", "cites": [{"t": "载,乘也。", "b": "《说文》"}, {"t": "载鬼一车。", "b": "《易·暌》"}, {"t": "命彼后车,谓之载之。", "b": "《诗·小雅·縣蛮》"}, {"t": "陆行载车,水行载舟。", "b": "《史记》"}, {"t": "宁可共载不。", "b": "《乐府诗集·陌上桑》"}, {"t": "上载公子上坐。", "b": "《史记·魏公子列传》"}, {"t": "载以来。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "搭载;载舟", "t": "乘船"}, {"w": "载车", "t": "乘车。"}]}, {"meaning": "用车船装运。", "cites": [{"t": "大车以载,有攸往,无咎。", "b": "《易·大有》"}, {"t": "多载资粮。", "b": "《资治通鉴》"}, {"t": "载燥荻枯柴。", "b": ""}, {"t": "载卷契而行。", "b": "《战国策·齐策四》"}, {"t": "黔无驴,有好事者船载以入。", "b": "柳宗元《三戒》"}], "words": [{"w": "载客;载货;过载", "t": "超载;转装到另一运输工具上"}, {"w": "装载", "t": "用运输工具装"}, {"w": "载送", "t": "以车运送。"}]}, {"meaning": "承载;负担。", "cites": [{"t": "水则载舟,水则覆舟。", "b": "《荀子》"}], "words": [{"w": "载地", "t": "承载大地"}, {"w": "载福", "t": "承受福祉"}, {"w": "载舟覆舟", "t": "以民心向背喻水,帝王为舟,水可载舟覆舟,以此来警戒帝王须随时注意民心向背。"}]}, {"meaning": "担任,担负。", "cites": [{"t": "故不乘天地之资而载一人之身。", "b": "《韩非子》"}], "words": [{"w": "载负", "t": "担负,承受。"}]}, {"meaning": "施行。", "cites": [{"t": "虎豹得幽而威可载也。", "b": "《管子·形势》"}]}, {"meaning": "陈设。", "cites": [{"t": "清酒既载,骍牡既备,以享以祀,以介景福。", "b": "《诗·大雅》"}], "words": [{"w": "载牲", "t": "陈设牺牲,准备祭祀。"}]}, {"meaning": "处;登。", "cites": [{"t": "身宠而载高位,家温而食厚禄。", "b": "汉·董仲舒《举贤良对策三》"}]}, {"meaning": "祭祀。", "cites": [{"t": "癸卯,大哭殇祀而载。", "b": "《穆天子传》"}], "words": [{"w": "载璧", "t": "祭祀时所用的璧玉"}, {"w": "载社", "t": "祭祀社庙。"}]}, {"meaning": "开始。", "cites": [{"t": "春日载阳。", "b": "《诗·豳风》"}, {"t": "东园之树,枝条载荣。", "b": "晋·陶潜《停云》"}]}, {"meaning": "装饰。", "cites": [{"t": "载以银锡。", "b": "《淮南子》"}]}, {"meaning": "词缀。嵌在动词前边。", "cites": [{"t": "载欣载奔。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "载歌载舞", "t": ""}]}, {"meaning": "充满。", "cites": [{"t": "厥声载路。", "b": "《诗·大雅·生民》"}, {"t": "号泣载道。", "b": "《明史》"}], "words": [{"w": "载路", "t": "满路"}, {"w": "载途", "t": "满路"}, {"w": "载地", "t": "充满大地"}, {"w": "载欢", "t": "充满欢乐。"}]}, {"meaning": "车、船等交通工具。", "cites": [{"t": "予乘四载,随山刊木。", "b": "《书·益稷》"}]}, {"meaning": "所装运的物件。", "cites": [{"t": "若乘舟,汝弗济,臭厥载。", "b": "《书·盘庚》"}], "words": [{"w": "重载;装载", "t": ""}]}, {"meaning": "事;事业。", "cites": [{"t": "有能奋庸,熙帝之载。", "b": "《书·舜典》"}]}, {"meaning": "又,且。", "cites": [{"t": "巩顿首载拜。", "b": "曾巩《寄欧阳舍人书》"}], "words": [{"w": "载拜", "t": "再拜。"}]}, {"meaning": "一车所载的容量为一载。", "cites": [{"t": "稽麦百载,天子使祭父受之。", "b": "《穆天子传》"}]}, {"meaning": "少数民族的计量单位。四十两为一载。", "cites": [{"t": "度用手,量用箩,以四十两为一载。论两不论斤。", "b": "明·朱孟震《西南夷风土记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1788wx','赶','1','gǎn','走','10','','[{"pinyin": "gǎn", "defs": [{"meaning": "(形声。从走,旱声。①(gián)本义:兽类翘起尾巴奔跑。《说文》:“举尾走也。”②追赶;驱赶)。"}, {"meaning": "追赶,从后面追上。", "cites": [{"t": "心道进退而刑道滔赶。", "b": "《管子·君臣》。注:“走也。”"}, {"t": "思虑果敢曰赶。", "b": "《周书·谥法》"}, {"t": "多多益辨真难事,半里撑船赶不归。", "b": "宋·张镃《五家林》"}], "words": [{"w": "赶先进;你追我赶;赶逐", "t": "追赶"}, {"w": "赶彀", "t": "追赶"}, {"w": "赶罗", "t": "催逼;逼迫"}, {"w": "赶人不要赶上", "t": "比喻不要逼人太甚"}, {"w": "赶势利", "t": "趋炎附势,依附有势力的人。"}]}, {"meaning": "驱逐。", "cites": [{"t": "厨人馈食于堂,手中盘馔,皆被群禽搏撮,莫可驱赶。", "b": "南唐·刘崇远《金华子》"}], "words": [{"w": "赶苍蝇;赶麻雀;赶下台;赶网儿", "t": "将鱼赶到网里去,喻得到好处"}, {"w": "赶羊", "t": "用六粒骰子掷出分高低的一种玩法。"}]}, {"meaning": "等到 ——跟时间名词组成介词结构,用在动词前面,表示动作、行为到某个时候才发生,多用于口语。", "cites": [{"t": "赶我长大一点,抗日战争爆发了。", "b": "《海市》"}], "words": [{"w": "赶年", "t": "等到过年"}, {"w": "赶年下", "t": "同“赶年”"}, {"w": "赶晚", "t": "等到晚上。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1789wx','起','1','qǐ','走','10','','[{"pinyin": "qǐ", "defs": [{"meaning": "(形声。从走,己声。本义:由躺而坐;由坐而立)。"}, {"meaning": "同本义。", "cites": [{"t": "起,能立也。", "b": "《说文》"}, {"t": "曩子坐,今子起。", "b": "《庄子·齐物论》"}, {"t": "载起载行。", "b": "《诗·小雅·沔水》"}, {"t": "请业则起。", "b": "《礼记·曲礼》"}, {"t": "子墨子起。", "b": "《墨子·公输》"}, {"t": "吾恂恂而起。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "夫起大呼。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "妇亦起大呼。", "b": ""}], "words": [{"w": "起在", "t": "起来"}, {"w": "起舞", "t": "起身而舞。欢欣的样子"}, {"w": "起坐", "t": "起立与坐下"}, {"w": "起谢", "t": "起立谢过。"}]}, {"meaning": "起床。", "cites": [{"t": "起视四境。", "b": "宋·苏洵《六国论》"}, {"t": "不敢同卧起。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "起去", "t": "指起床"}, {"w": "起炕", "t": "起床。"}]}, {"meaning": "产生;发生。", "cites": [{"t": "自董卓以来,豪杰并起,跨州连郡者,不可胜数。", "b": "陈寿《隆中对》"}, {"t": "夫齁声起。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "又。", "cites": [{"t": "火起。", "b": ""}, {"t": "起于远近之比例。", "b": "蔡元培《图画》"}, {"t": "十日而变已起。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "起骒", "t": "驴、马发情"}, {"w": "起病", "t": "生病"}, {"w": "起楞", "t": "一楞楞高起"}, {"w": "起念", "t": "产生某种想法。"}]}, {"meaning": "开始;开端。", "cites": [{"t": "项庄拔剑起舞。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "项伯亦拔剑起舞。", "b": ""}, {"t": "语从何起。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "起末", "t": "始末"}, {"w": "起票", "t": "起码"}, {"w": "起为头", "t": "开头"}, {"w": "起工", "t": "动工;开工。"}]}, {"meaning": "源起;起因于。", "cites": [{"t": "辛苦遭逢起一径。", "b": "宋·文天祥《过零丁洋》诗"}], "words": [{"w": "起首", "t": "发端;原由"}, {"w": "起倒", "t": "说头;缘由"}, {"w": "起本", "t": "起因;由来。"}]}, {"meaning": "起身,动起来,采取行动。", "cites": [{"t": "广起。", "b": "《史记·陈涉世家》"}, {"t": "惊起一滩鸥鹭。", "b": "宋·李清照《如梦令》"}, {"t": "君起以伸其愤。", "b": "张溥《五人墓碑记》"}, {"t": "起而拯之。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "起车", "t": "把货物装车,起程出发"}, {"w": "起押", "t": "押解上路"}, {"w": "起马", "t": "骑马动身启程"}, {"w": "起征", "t": "出征。"}]}, {"meaning": "起义,起事,闹事。", "cites": [{"t": "并举而争起。", "b": "汉·贾谊《论积贮疏》"}, {"t": "并起而亡秦族。", "b": "汉·贾谊《过秦论上》"}, {"t": "海内大乱,将军起兵江东。", "b": "《资治通鉴·赤壁之战》"}, {"t": "王起师于滑。", "b": "《左传·昭公二十六年》。注:“发也。”"}, {"t": "英、霍山师大起。", "b": "清·全祖望《梅花岭记》"}]}, {"meaning": "又。", "cites": [{"t": "起兵不克。", "b": ""}], "words": [{"w": "起点", "t": "点兵"}, {"w": "起碇", "t": "借指军队开拔"}, {"w": "起首", "t": "起事。"}]}, {"meaning": "隆起,凸起,耸立。", "cites": [{"t": "执图诣寺,有古陵蔚起。", "b": "《聊斋志异·促织》"}, {"t": "四面峭壁拔起。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "石峰片片夹起。", "b": "《徐霞客游记·游黄山记》"}]}, {"meaning": "又。", "cites": [{"t": "石块丛起。", "b": ""}]}, {"meaning": "草拟。", "cites": [{"t": "这讣帖底稿,是那个起的呢?", "b": "《二十年目睹之怪现状》"}]}, {"meaning": "使疏松。", "cites": [{"t": "春锄,起地;夏为锄草。", "b": "《种谷》。石声汉校释:“起,使土疏松。”"}]}, {"meaning": "扶持。", "cites": [{"t": "世相起也。", "b": "《国语》。韦昭注:“起,扶持也。”"}]}, {"meaning": "取。", "cites": [{"t": "先在府县起了文书。", "b": "《镜花缘》"}]}, {"meaning": "出身。", "cites": [{"t": "应元起掾吏。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "用在动词后作为补足语,表示动作的向上方向。", "cites": [{"t": "卷起千堆雪。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}, {"t": "小虫跃起。", "b": "《聊斋志异·促织》"}, {"t": "跃起持之哭。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "拿起雨伞就走;抬起头来一看;唱起歌,跳起舞", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1790wx','盐','1','yán','皿','10','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从卤,监声。本义:食盐)。"}, {"meaning": "同本义。", "cites": [{"t": "若作和羹,尔惟盐梅。", "b": "《书·说命下》"}, {"t": "鲁盐漆丝。", "b": "《史记·货殖列传》"}], "words": [{"w": "盐酱口", "t": "说不吉利的话,且得到应验"}, {"w": "盐枭", "t": "私贩食盐的人"}, {"w": "盐斤", "t": "宋代官盐以百斤、千斤为计算单位,故称“盐”为“盐斤”"}, {"w": "盐捕分府", "t": "知府下面专管盐务的同知"}, {"w": "盐钞法", "t": "宋代实行的商人凭盐钞运销食盐的法规,即食盐专卖法"}, {"w": "盐呆子", "t": "蔑称盐商"}, {"w": "盐官", "t": "今浙江海宁"}, {"w": "盐院", "t": "盐政衙门。盐政是管理地区盐务的官员,清代由省的总督或巡抚兼任"}, {"w": "盐丁", "t": "在盐田工作的人"}, {"w": "盐引", "t": "政府授予商人运销官盐的凭证"}, {"w": "盐车", "t": "运盐的车。"}]}, {"meaning": "由金属离子(或铵根离子NH4+)和酸根离子组成的化合物。"}, {"meaning": "含有氢离子的盐叫酸式盐,如:碳酸氢铵(NH4HCO3);硫酸氢钠(NaHSO4);磷酸二氢钾(KH2PO4)。"}, {"meaning": "含有氢氧根离子的盐叫碱式盐,如:碱式碳酸铜(Cu22CO3)。"}, {"meaning": "不含氢氧根离子和氢离子的盐叫正盐,如:氯化钠(NaCl);碳酸钠(Na2CO3)。此外还有复盐(如明矾)等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1791wx','捎','1','shāo shào','扌','10','','[{"pinyin": "shāo", "defs": [{"meaning": "(形声。从手,肖声。本义:选取)。"}, {"meaning": "同本义。", "cites": [{"t": "捎,择也。", "b": "《广雅·释诂》"}, {"t": "捎,自关已西,凡取物之上为挢捎。", "b": "《说文》"}, {"t": "捎,选也。", "b": "《方言》"}]}, {"meaning": "掠拂。", "cites": [{"t": "风捎檐滴难开幌。", "b": "张耒《春阴》"}, {"t": "曳捎星之旃。", "b": "杨雄《羽猎赋》"}], "words": [{"w": "捎", "t": "抽打割勒。捎:拂掠"}, {"w": "捎儿", "t": "手巾"}, {"w": "捎星", "t": "拂到天上的星,形容极高"}, {"w": "捎捩", "t": "拂掠转折。"}]}, {"meaning": "破除;砍杀;芟除。", "cites": [{"t": "拔剑捎罗网。", "b": "曹植《野田黄雀行》"}]}, {"meaning": "捎带;顺带。", "cites": [{"t": "孟姜女时常到村口去看,希望过路的人给捎封信来。", "b": "《孟姜女》"}], "words": [{"w": "捎搭", "t": "装载在牲口背上"}, {"w": "请把这张报捎给她;捎个口信", "t": ""}]}]}, {"pinyin": "shào", "defs": [{"meaning": "扇打。", "cites": [{"t": "这脸上是前日打围,在铁网山教兔鹘捎了一翅膀。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1792wx','捍','1','hàn','扌','10','','[{"pinyin": "hàn", "defs": [{"meaning": "(古字作“扞”,后作“捍”。形声。从手,旱声。本义:抵御;保卫)同本义。", "cites": [{"t": "扞,以手扞,又卫也。", "b": "《广韵》"}, {"t": "亲帅扞之。", "b": "《左传·文公六年》"}, {"t": "此公侯之所以扞城其民也。", "b": "《左传·成公十二年》"}, {"t": "而设以国为王扞秦。", "b": "《战国策·西周策》"}, {"t": "若手足之扞头目。", "b": "《汉书·刑法志》"}, {"t": "能扞大患则祀之。", "b": "《礼记·祭法》"}, {"t": "守一城,捍天下。", "b": "韩愈《张中函传后叙》"}], "words": [{"w": "捍塞", "t": "防堵,阻塞"}, {"w": "捍难", "t": "抵御外侮"}, {"w": "捍遏", "t": "以武力阻隔"}, {"w": "捍城", "t": "护卫城池"}, {"w": "捍救", "t": "捍卫;救援"}, {"w": "捍护", "t": "防卫;护卫"}, {"w": "捍屏", "t": "捍蔽。屏藩。"}]}, {"meaning": "勇猛;强悍。", "cites": [{"t": "彼近吾死而我不听,我则悍矣,彼何罪焉!", "b": "《庄子·大宗师》"}, {"t": "无衔橛而御捍马也。", "b": "《盐铁论·刑德》"}], "words": [{"w": "捍马", "t": "凶悍的烈马“扞”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1793wx','捏','1','niē','扌','10','','[{"pinyin": "niē", "defs": [{"meaning": "(形声。从手,从土,曰声。本义:用手指将软的东西捻成一定形状)。"}, {"meaning": "同本义。", "cites": [{"t": "只见几个婆子手里都捧着一色捏丝戗金五彩大盒子走来。", "b": "《红楼梦》"}], "words": [{"w": "捏泥人儿;捏怪", "t": "塑造怪相"}, {"w": "捏素", "t": "塑像"}, {"w": "捏塑", "t": "以泥塑造。"}]}, {"meaning": "握。", "cites": [{"t": "俺捏住这玉佩慢慢的行将去。", "b": "郑德辉《驺梅香》"}], "words": [{"w": "手内捏一捏,就知分两;手上还捏着那只小篮呢;把钱捏在手里睡觉", "t": ""}]}, {"meaning": "假造。", "cites": [{"t": "王庆听他问的跷蹊,便捏一派假话支吾。", "b": "《水浒传》"}], "words": [{"w": "捏奏", "t": "捏造谎言,上奏朝廷"}, {"w": "捏名", "t": "假造姓名"}, {"w": "捏事", "t": "假造事端"}, {"w": "捏陷", "t": "捏造假证陷害"}, {"w": "捏故", "t": "捏造事端"}, {"w": "捏构", "t": "虚构,编造"}, {"w": "捏报", "t": "谎报"}, {"w": "捏诬", "t": "说谎诬陷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1794wx','埋','1','mái mān','土','10','','[{"pinyin": "mái", "defs": [{"meaning": "(形声.从土,里声.字本作“薶”,甲骨文字形,象在坑中埋狗的形象,是向地神祭献的活动。本义:藏入土中)。"}, {"meaning": "同本义。", "cites": [{"t": "祭器敝则埋之,龟筴敝则埋之,牲死则埋之。", "b": "《礼记·曲礼上》"}, {"t": "生女犹得嫁比邻,生男埋没随百草。", "b": "杜甫《兵车行》"}, {"t": "我死谁埋。", "b": "清·袁枚《祭妹文》"}, {"t": "毁其盆,悉埋于地。", "b": "龚自珍《病梅馆记》"}], "words": [{"w": "埋地雷;埋玉", "t": "比喻英才或美女之死"}, {"w": "埋书", "t": "把盟书埋在地下。古代盟誓时的一种礼仪"}, {"w": "埋狱", "t": "埋没在监狱屋基下的宝剑。比喻埋没人才。"}]}, {"meaning": "古代特指简陋不依礼制而落葬。也泛指葬埋。", "cites": [{"t": "葬不如礼曰埋。(如:按照)", "b": "《释名·释葬制》"}], "words": [{"w": "埋骨", "t": "人死而埋葬屍骨"}, {"w": "埋匿", "t": "埋窆。掩埋尸体"}, {"w": "埋堙", "t": "埋藏。掩埋尸体"}, {"w": "埋魂", "t": "埋葬英魂"}, {"w": "埋蛇", "t": "“埋蛇”为善行仁爱之典"}, {"w": "埋掩", "t": "掩埋,埋葬。"}]}, {"meaning": "藏,掩盖。", "cites": [{"t": "狐埋之而狐搰之。", "b": "《国语·吴语》"}], "words": [{"w": "埋冤", "t": "含冤"}, {"w": "埋情", "t": "昧心"}, {"w": "埋忧", "t": "隐藏忧愁"}, {"w": "埋身", "t": "埋名;隐居"}, {"w": "埋匿", "t": "埋藏"}, {"w": "埋翳", "t": "掩埋;掩盖"}, {"w": "埋覆", "t": "掩蔽;覆盖。"}]}]}, {"pinyin": "mān", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1795wx','捉','1','zhuō','扌','10','','[{"pinyin": "zhuō", "defs": [{"meaning": "(形声。从手,足声。本义:握,持)。"}, {"meaning": "同本义。", "cites": [{"t": "捉,搤也。", "b": "《说文》"}, {"t": "捉,持也。", "b": "《广雅》"}, {"t": "伊便能捉杖打人。", "b": "《世说新语·方正》"}, {"t": "叔武将沐,闻君至,喜,捉发走出。", "b": "《左传》"}, {"t": "孙权捉预手,涕泣而别。", "b": "《三国志》"}], "words": [{"w": "捉发", "t": "手握头发"}, {"w": "捉秤", "t": "拿秤,掌秤"}, {"w": "捉手", "t": "握手"}, {"w": "捉身", "t": "把握身体"}, {"w": "捉船", "t": "撑船,划船"}, {"w": "捉笔", "t": "执笔。"}]}, {"meaning": "又。", "cites": [{"t": "迅不可捉。", "b": ""}, {"t": "余捉蟋蟀。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "捉事人", "t": "捉拿罪犯的公人"}, {"w": "捉生替死", "t": "陷害无罪之人为有罪者抵死"}, {"w": "捉生", "t": "活捉敌人"}, {"w": "捉取", "t": "擒拿;捕捉。"}]}, {"meaning": "戏弄。", "cites": [{"t": "张珙新来,受了别人家捉。", "b": "董解元《西厢》"}], "words": [{"w": "捉掐", "t": "捉弄"}, {"w": "捉狭", "t": "捉弄"}, {"w": "捉搦", "t": "戏弄。"}]}, {"meaning": "捡,拾。", "cites": [{"t": "若见女人一发在地,自言持戒,不肯捉之。", "b": "《百喻经》"}]}, {"meaning": "找,趁。", "cites": [{"t": "当日权且欢天喜地,并无他说。明日捉个空,便一径到临安府前叫起屈来。", "b": "《京本通俗小说》"}, {"t": "你瞧,太太们老在一起,哪有我捉空儿跟他说话的机会。", "b": "茅盾《霜叶红似二月花》"}], "words": [{"w": "捉个空", "t": "找个空子"}, {"w": "捉冷眼", "t": "趁人没看见"}, {"w": "捉脉", "t": "堪舆家据地势,寻找所谓龙脉"}, {"w": "捉空", "t": "趁空"}, {"w": "捉破", "t": "抓出破绽。"}]}, {"meaning": "控制。", "cites": [{"t": "那小二不曾提防,捉脚不定,翻筋斗直跌出门外,磕碎脑后,鲜血直淌。", "b": "《醒世恒言》"}, {"t": "原来杨志吃的酒少,便醒得快,爬将起来,兀自捉脚不住。", "b": "《水浒全传》"}], "words": [{"w": "捉不住", "t": "控制不住"}, {"w": "捉兵", "t": "提调军队"}, {"w": "捉店", "t": "守护店铺。"}]}, {"meaning": "相当于“把”、“将”。", "cites": [{"t": "身边铜钱又无,吃了却捉什么还他?", "b": "《警世通言》"}, {"t": "好得合头痴。向吾宅里坐,却捉主人欺。", "b": "《敦煌变文集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1796wx','捆','1','kǔn','扌','10','','[{"pinyin": "kǔn", "defs": [{"meaning": "(形声。从手,困声。本义:叩击使牢)。"}, {"meaning": "同本义。", "cites": [{"t": "皆衣褐、捆屦、织席以为食。", "b": "《孟子·滕文公》。赵歧注:“织屦欲使坚,故叩之也。”"}]}, {"meaning": "用绳、链或带子系、拴、扎紧。", "cites": [{"t": "贾蓉忍不得便骂了几句,叫人捆起来。", "b": "《红楼梦》"}], "words": [{"w": "捆风", "t": "扯谎说瞎话"}, {"w": "捆身子", "t": "内衣"}, {"w": "捆行李;捆谷草;捆住手脚;把书捆起来", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1797wx','捐','1','juān','扌','10','','[{"pinyin": "juān", "defs": [{"meaning": "(形声。从手,肙(yuān)声。本义:舍弃)。"}, {"meaning": "同本义。", "cites": [{"t": "捐,弃也。", "b": "《说文》。按,粪除秽污谓之捐。故寺人谓之中涓。以涓为之。"}, {"t": "捐殡。", "b": "《谷梁传·宣公十八年》。注:“弃也。”"}, {"t": "而国无捐瘠者。", "b": "《汉书·食货志》。注:“骨不埋者。”孟康曰:“捐,谓民有饥相弃捐者,或谓贫乞者谓捐。”"}, {"t": "捐金于野。", "b": "《后汉书·列女传》"}, {"t": "捐失成功。", "b": ""}], "words": [{"w": "捐世", "t": "弃世。人死的婉辞"}, {"w": "捐馆", "t": "指弃房舍,死亡的婉称。也作“捐馆舍”"}, {"w": "捐身", "t": "牺牲生命"}, {"w": "捐却", "t": "抛弃"}, {"w": "捐灰", "t": "丢弃尘土。"}]}, {"meaning": "除去;废除。", "cites": [{"t": "捐不急之官。", "b": "《史记》"}], "words": [{"w": "捐甲", "t": "脱去铠甲"}, {"w": "捐阶", "t": "除去阶梯"}, {"w": "捐荐", "t": "去掉荐席"}, {"w": "捐除", "t": "废除;消除"}, {"w": "捐书", "t": "废书不读。"}]}, {"meaning": "捐献,贡献。", "cites": [{"t": "富者捐资。", "b": "《广东军务记》"}, {"t": "捐二万五千金。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "捐者麋集。", "b": ""}], "words": [{"w": "捐廉", "t": "官员向政府或为公务捐献自己的养廉银子"}, {"w": "捐纳", "t": "秦代开始准许士民通过向政府捐款纳粮而买官职,历代效法,到清代而滥"}, {"w": "捐选", "t": "挑选吉日。"}]}, {"meaning": "花费;耗用。", "cites": [{"t": "人能捐百万钱嫁女,而不肯捐十万钱教子。", "b": "《五杂俎》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1798wx','损','1','sǔn','扌','10','','[{"pinyin": "sǔn", "defs": [{"meaning": "(形声。从手,员声。本义:减少)。"}, {"meaning": "同本义,与“益”相对。", "cites": [{"t": "损,减也。", "b": "《说文》"}, {"t": "损偏去也。", "b": "《墨子经》"}, {"t": "损德之脩也。", "b": "《易·系辞》"}, {"t": "损益,盛衰之始也。", "b": "《易·杂卦》"}, {"t": "以君之力。曾不能损魁之丘,如太行王屋何?", "b": "《列子·汤问》"}, {"t": "先王之法,经乎上世而来者也,人或益之,人或损之,胡可得而法?", "b": "《吕氏春秋·察今》"}, {"t": "请损之,月攘一鸡。", "b": "《孟子·滕文公下》"}], "words": [{"w": "损年", "t": "短报年岁;寿命减少"}, {"w": "损膳", "t": "减膳"}, {"w": "损薄", "t": "降低标准,减损"}, {"w": "损夺", "t": "削减"}, {"w": "损减", "t": "节制;减少。"}]}, {"meaning": "损失;丧失。", "cites": [{"t": "满招损,谦受益。", "b": "《书·大禹谟》"}, {"t": "大军围城者二十四万,死者六万七千,巷战死乾又七千,凡损卒七万五千有奇。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "损折", "t": "损失"}, {"w": "损败", "t": "损失;损坏"}, {"w": "损阴", "t": "折损了阴德"}, {"w": "损身", "t": "丧身"}, {"w": "损书", "t": "对人书札的敬辞。是说对方不惜贬抑身分写信给自己"}, {"w": "损挹", "t": "谦退。"}]}, {"meaning": "伤害或损害。", "cites": [{"t": "益者三友,损者三友。", "b": "《论语·季氏》"}, {"t": "小人之誉人反为损。", "b": "《淮南子·说山训》"}, {"t": "做的个上梁不正,只待要损人利己惹人憎。", "b": "《元曲选·陈州粜米》"}], "words": [{"w": "损人肥己,损人害己;损友", "t": "有害的朋友"}, {"w": "损生", "t": "损害身体。"}]}, {"meaning": "病情减轻。", "cites": [{"t": "而母杨夫人忽病,谒医久未损。", "b": "宋·叶适《故大宗丞高公墓志铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1799wx','袁','1','yuán','土','10','','[{"pinyin": "yuán", "defs": [{"meaning": "长衣的样子。", "cites": [{"t": "袁,长衣貌。从衣,叀省声。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1800wx','捌','1','bā','扌','10','','[{"pinyin": "bā", "defs": [{"meaning": "用手分开。", "cites": [{"t": "故解捽者不在于捌格。", "b": "《淮南子·说林》"}], "words": [{"w": "捌格", "t": "分解。"}]}, {"meaning": "“八”字的大写。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1801wx','都','1','dōu dū','阝','10','','[{"pinyin": "dōu", "defs": [{"meaning": "全部。"}, {"meaning": "表示全部包括在内。", "cites": [{"t": "渐黄昏,清角吹寒,都在空城。", "b": "姜夔《扬州慢》"}, {"t": "常愿天下有情人都成眷属。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "你的话并不都对;都子", "t": "乞丐"}, {"w": "都把势", "t": "总头目。"}]}]}, {"pinyin": "dū", "defs": [{"meaning": "(形声。从邑,者声。从“邑”,表示与城市有关。本义:建有宗庙的城邑)。"}, {"meaning": "同本义 ,周时各国把国都叫国,把有宗庙或先君神主的城叫都,没有的叫邑。", "cites": [{"t": "都,有先君之旧宗庙曰都。", "b": "《说文》"}, {"t": "距闰王百里为都。", "b": "《周礼》"}, {"t": "凡邑有宗庙先君之主曰都,无曰邑。", "b": "《左传·庄公二十八年》"}, {"t": "先王之制,大都不过参国之一。", "b": "《左传·隐公元年》"}, {"t": "田畴秽,都邑露。", "b": "《荀子·富国》"}], "words": [{"w": "都鄙", "t": "旧时天子宗亲及公卿大夫的采邑"}, {"w": "都家", "t": "周王朝分封给子弟及公卿大夫的采邑"}, {"w": "都亭", "t": "都邑中的传舍"}, {"w": "都甸", "t": "都邑郊外之地。"}]}, {"meaning": "邦国的都城,国都。", "cites": [{"t": "国都曰都,都者,国君所居,人所都会也。", "b": "《释名》"}, {"t": "兴复汉室,还于旧都。", "b": "诸葛亮《出师表》"}, {"t": "秋九月,权迁都建业。", "b": "《三国志·吴主传》"}, {"t": "都门帐饮无绪。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "奠都;定都;故都;国都;京都", "t": "旧时称国都"}, {"w": "旧都", "t": "故都"}, {"w": "迁都;行都", "t": "旧时指临时的首都"}, {"w": "都下", "t": "京都之下。即京城"}, {"w": "都内", "t": "京城内的府库"}, {"w": "都邑", "t": "首都"}, {"w": "都辇", "t": "京师"}, {"w": "都畿", "t": "京都及其附近的地区。"}]}, {"meaning": "引申为城市。", "cites": [{"t": "傅之其人,通邑大都。", "b": "王安石《报任安书》"}, {"t": "召有司案图,指从此以往十五都予赵。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "都道", "t": "都城的街道"}, {"w": "都阃", "t": "都市郭门。引申为守卫城市的统帅。阃:门坎"}, {"w": "都庄", "t": "都城的大道。"}]}, {"meaning": "周代王室子弟及三公的封地、采地。", "cites": [{"t": "凡造都鄙。", "b": "《周礼·大司徒》。注:“都鄙,王子弟公卿大夫采地,其界曰都。鄙所居也。”"}, {"t": "邦都之赋。", "b": "《周礼·大宰》。注:“四郊去国百里,邦甸二百里,家削三百里,邦县四百里;邦都五百里。”"}, {"t": "都城过百雉,国之害也。", "b": "《左传·隐公元年》"}], "words": [{"w": "都鄙,都家", "t": "周公卿、大夫、王子弟的采邑,封地。"}]}, {"meaning": "国家或帝国的行政区域或行政分区。明、清时基层行政区划是图,图下分十庄,图有地保;图上设都,相当于区或乡。", "cites": [{"t": "族长严振先,乃城中十二都的乡约,平日最怕严大老官。", "b": "《儒林外史》"}]}, {"meaning": "建都。", "cites": [{"t": "据天下之雄图,都六合之上游。", "b": "柳宗元《封建论》"}]}, {"meaning": "聚集。", "cites": [{"t": "都,凡也。", "b": "《广雅·释训》"}, {"t": "都部者,都统其众也。", "b": "《后汉书·齐武王縯传》注"}, {"t": "水泽所聚谓之都。", "b": "《水经注·水文注》"}, {"t": "顷择其遗文,都为一集。", "b": "《文选·与吴质书》"}], "words": [{"w": "都居", "t": "水积聚的地方"}, {"w": "都场", "t": "聚会的地方"}, {"w": "都泽", "t": "水流汇聚的草泽地带。"}]}, {"meaning": "美好的样子。", "cites": [{"t": "身长八尺,仪貌都雅。", "b": "《三国志·孙韶传》"}, {"t": "不见于子都。", "b": "《诗·郑风·山有扶苏》。传:“世之美好者也。”"}, {"t": "妻子衣服丽都。", "b": "《战国策·齐策》"}], "words": [{"w": "都冶", "t": "美艳的样子"}, {"w": "都雅", "t": "优美文雅的样子"}, {"w": "都长", "t": "指人美貌而性情温厚"}, {"w": "都鄙", "t": "文雅与卑陋。"}]}, {"meaning": "大。", "cites": [{"t": "军惊而怀都舍。", "b": "《吕氏春秋·察今》"}, {"t": "中有都柱,傍行八道。", "b": "《后汉书·张衡传》"}], "words": [{"w": "都匠", "t": "大匠"}, {"w": "都酿", "t": "大的酿造作坊"}, {"w": "都坑", "t": "公共厕所"}, {"w": "都灶", "t": "蒸炊用的大灶。"}]}, {"meaning": "统统,完全。", "cites": [{"t": "都,凡也。", "b": "《广雅·释训》"}], "words": [{"w": "都齐", "t": "完全,统统"}, {"w": "都数", "t": "总数"}, {"w": "都领", "t": "总领,总管"}, {"w": "都邮", "t": "古指邮驿总站"}, {"w": "都来", "t": "统统;总共;总计"}, {"w": "都凡", "t": "总共。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1802wx','哲','1','zhé','口','10','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。从口,折声。本义:聪明,有智慧) 同本义。", "cites": [{"t": "哲,知也。", "b": "《说文》。古文从三吉(嚞),字亦作喆。作悊"}, {"t": "哲,智也。", "b": "《尔雅》"}, {"t": "世有哲王。", "b": "《诗·大雅·下武》"}, {"t": "哲夫成城,哲妇倾诚。", "b": "《诗·大雅·瞻卬》"}, {"t": "敷求哲人。", "b": "《书·伊训》"}, {"t": "或悊或谋。", "b": "《汉书·叙传》"}, {"t": "知人则哲,能官人。", "b": "《书·皋陶谟》"}], "words": [{"w": "哲士", "t": "聪明智慧、见识超常的人"}, {"w": "哲子", "t": "贤明的人"}, {"w": "哲艾", "t": "指明达的老人"}, {"w": "哲母", "t": "贤明的母亲"}, {"w": "哲匠", "t": "指明达而富有才能的大臣"}, {"w": "哲明", "t": "贤明的宰相、辅臣"}, {"w": "哲夫", "t": "足智多谋的人"}, {"w": "哲思", "t": "精深敏捷的思虑"}, {"w": "哲妇", "t": "多谋虑的妇人"}, {"w": "哲圣", "t": "才德超群的人。"}]}, {"meaning": "贤明的人;有智慧的人。", "cites": [{"t": "尔庶邦君,越尔御事;爽邦由哲。", "b": "《书·大诰》"}], "words": [{"w": "先哲;哲人其萎", "t": "哲人萎,哲萎。为贤者病逝之典,今亦常用作慰唁之词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1803wx','逝','1','shì','辶','10','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从辵(chuò),折声。本义:去;往)。"}, {"meaning": "同本义。", "cites": [{"t": "逝,往也。", "b": "《说文》"}, {"t": "逝,行也。", "b": "《广雅》"}, {"t": "谷旦于逝。", "b": "《诗·陈风·东门之枌》"}, {"t": "君子可逝也。", "b": "《论语·子罕》"}]}, {"meaning": "死亡,去世。", "cites": [{"t": "予为斯序,既痛逝者,并以为国人之读兹编者勖。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "逝殂", "t": "死亡"}, {"w": "逝灭", "t": "消逝,灭亡"}, {"w": "逝路", "t": "死亡之路"}, {"w": "逝没", "t": "死去。"}]}, {"meaning": "表决心。", "cites": [{"t": "逝将去女,适彼乐土。", "b": "《诗·魏风·硕鼠》"}], "words": [{"w": "逝将", "t": "即誓将。"}]}, {"meaning": "助词。无实义,起调整音节的作用。", "cites": [{"t": "乃如之人兮,逝不古处。", "b": "《诗·邶风·日月》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1804wx','捡','1','jiǎn','扌','10','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从手,佥(qiān)声。(jiàn)本义:拱手)。"}, {"meaning": "约束。", "cites": [{"t": "郡事皆以义法令捡式。", "b": "《汉书·黄霸传》"}], "words": [{"w": "捡式", "t": "约束言行的法度、准则"}, {"w": "捡点", "t": "同“检点”。约束自己的言行;检查;逐一查看"}, {"w": "捡局", "t": "拘束,约束"}, {"w": "捡押", "t": "约束,监管。"}]}, {"meaning": "察看;检查。", "cites": [{"t": "捡阅库藏,收其珍宝。", "b": "《后汉书·张湛传》"}], "words": [{"w": "捡括", "t": "稽查"}, {"w": "捡校", "t": "查看,查视"}, {"w": "捡看", "t": "翻捡查看"}, {"w": "捡勘", "t": "查对校勘"}, {"w": "捡察", "t": "调查,稽查。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1805wx','挫','1','cuò','扌','10','','[{"pinyin": "cuò", "defs": [{"meaning": "(形声。从手,坐声。本义:折断;摧折)。"}, {"meaning": "同本义。", "cites": [{"t": "挫,摧也。", "b": "《说文》"}, {"t": "或挫或隳。", "b": "《老子》"}, {"t": "而未尝有所挫也。", "b": "《国语·吴语》。注:“毁折也。”"}], "words": [{"w": "挫折", "t": "劈断,折断"}, {"w": "挫顿", "t": "摧折损伤。"}]}, {"meaning": "失败。", "cites": [{"t": "挫我于内。", "b": "《战国策·秦策》"}], "words": [{"w": "挫顿", "t": "挫败损伤"}, {"w": "挫过", "t": "错过"}, {"w": "挫北", "t": "败北,打败仗。"}]}, {"meaning": "挫伤,折伤。", "cites": [{"t": "顿兵挫锐。", "b": "《淮南子·脩务》"}, {"t": "锐而不挫。", "b": "《淮南子·时则》"}, {"t": "蚊虫之声,闻则挫其精。", "b": "《荀子·解蔽》"}], "words": [{"w": "挫动", "t": "打击;挫折"}, {"w": "挫诎", "t": "摧挫贬黜"}, {"w": "挫强", "t": "挫伤强敌"}, {"w": "挫锋", "t": "锋芒受挫。"}]}, {"meaning": "弯折,收缩。", "cites": [{"t": "久挫于刀笔之前。", "b": "《汉书·陈汤传》"}], "words": [{"w": "一挫身,向远处飞去了把身子一挫,就打算往舱里钻", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1806wx','换','1','huàn','扌','10','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从手,奂(huàn)声。本义:互易)。"}, {"meaning": "同本义。", "cites": [{"t": "换,易也。", "b": "《说文》"}, {"t": "擅相换易。", "b": "《谷梁传·桓公元年》注"}], "words": [{"w": "以帛换酒;换过子", "t": "互相调换"}, {"w": "换了帖", "t": "异姓的人结拜为兄弟时交换写有年龄、籍贯、家世等的帖子。"}]}, {"meaning": "变易,改变。", "cites": [{"t": "几移几换。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "换衣服;换手", "t": "更换操作的人"}, {"w": "换脚手", "t": "换鞋、衣服、手套等"}, {"w": "换易", "t": "调换、更换"}, {"w": "换朝", "t": "改朝换代。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1807wx','挽','1','wǎn','扌','10','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从手,免声。古字从“车”,免声。本义:牵引;拉)。"}, {"meaning": "同本义。", "cites": [{"t": "挽,引也。", "b": "《小尔雅·广诂》"}, {"t": "輓,引之也。", "b": "《说文》"}, {"t": "輓,輓车也。", "b": "《广韵》"}, {"t": "或輓之,或推之。", "b": "《左传·襄公十四年》。注:“前牵曰輓。”"}, {"t": "娄敬脱輓辂。", "b": "《史记·刘敬传》"}, {"t": "转粟輓输以为之备。", "b": "《汉书·韩安国传》"}, {"t": "挽炮车者。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "挽郎", "t": "出葬时,牵绋唱挽歌的少年"}, {"w": "挽强", "t": "拉强弓"}, {"w": "挽满", "t": "拉满弓"}, {"w": "挽车", "t": "拉车"}, {"w": "挽住", "t": "憋住"}, {"w": "挽手儿", "t": "缰绳"}, {"w": "挽歌郎", "t": "出殡时替丧家在灵前唱挽歌的人"}, {"w": "挽强为弱", "t": "使强变弱。"}]}, {"meaning": "悼念死者。", "cites": [{"t": "现今胡三公子替湖州鲁老先生征挽诗,送了十几个斗方在我那里。", "b": "《儒林外史》"}], "words": [{"w": "挽章", "t": "挽词。哀悼死者的词章"}, {"w": "挽诗", "t": "哀悼死者的诗"}, {"w": "挽歌", "t": "哀悼死者的丧歌"}, {"w": "挽联", "t": "哀悼死者的对联"}, {"w": "挽辞", "t": "哀悼死者的言辞。"}]}, {"meaning": "扭转;挽回。", "cites": [{"t": "火攻破敌,挽强为弱。", "b": "《三侠五义》"}], "words": [{"w": "挽狂澜", "t": "扭转局面或风气"}, {"w": "挽正", "t": "纠正"}, {"w": "挽转", "t": "挽回"}, {"w": "挽通", "t": "勾结;买通。"}]}, {"meaning": "请,托。", "cites": [{"t": "怎奈蔡攸处挽心腹催促公人起身。", "b": "《水浒全传》"}]}, {"meaning": "后,迟", "cites": [{"t": "必用此为务,輓近世塗民耳目,则几无行矣。", "b": "《史记·货殖列传》"}], "words": [{"w": "挽近", "t": "近世,近代。同晚近。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1808wx','挚','1','zhì','手','10','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意。从手,从执。本义: 古代初次求见人时所送的礼物,见面礼)。"}, {"meaning": "同本义。", "cites": [{"t": "挚,握持也。", "b": "《说文》。字亦作贽。"}, {"t": "以禽作六挚。孤执皮帛,卿执羔,大夫执雁,士执雉,庶人执鹅,工商执鸡。", "b": "《周礼·大宗伯》"}, {"t": "奠挚见于君。", "b": "《仪礼·士冠礼》"}, {"t": "执挚以相见。", "b": "《礼记·郊特牲》"}, {"t": "先人尝受其挚,阅不终篇,而屡叹葛氏之多子也。", "b": "宋·王安石《葛兵祖墓志铭》"}], "words": [{"w": "挚币", "t": "古时用为祭祀或馈赠礼物的束帛。"}]}, {"meaning": "古国名 。在今河南省汝南县东南。", "cites": [{"t": "挚仲氏任,自彼殷商,来嫁于周。", "b": "《诗·大雅·大明》"}]}, {"meaning": "见面礼。", "cites": [{"t": "奠挚见于君。", "b": "《仪礼·士冠礼》"}, {"t": "以禽作六挚。", "b": "《周礼·春官·大宗伯》"}, {"t": "执挚以相见。", "b": "《礼记·郊特牲》"}]}, {"meaning": "逮;捕;捉。", "cites": [{"t": "挚执妻子。", "b": "《吕氏春秋》"}], "words": [{"w": "挚执", "t": "拘捕。"}]}, {"meaning": "击;搏击。", "cites": [{"t": "行冬令,则风寒不时,鹰隼蚤挚,四鄙入保。", "b": "《淮南子》"}]}, {"meaning": "攫取。", "cites": [{"t": "百卉具零,刚虫搏挚。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "至;到。", "cites": [{"t": "天曷不降威,大命不挚。", "b": "《书·西伯戡黎》"}, {"t": "挚而有别。", "b": "《诗·关雎》传"}]}, {"meaning": "凶猛。", "cites": [{"t": "前有挚兽。", "b": "《礼记·曲礼上》"}, {"t": "趋时若猛兽挚鸟之发。", "b": "《史记·货殖列传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1809wx','热','1','rè','灬','10','','[{"pinyin": "rè", "defs": [{"meaning": "(形声。本义:温度高)。"}, {"meaning": "同本义。跟“冷”相对。", "cites": [{"t": "肺甚畏热。", "b": "《素问·五常变大论》"}, {"t": "清暖寒热,不得不救。", "b": "《韩非子·有度》"}, {"t": "如水益深,如火益热", "b": "《孟子·梁惠王下》"}, {"t": "立厩中仆马之间,……即饥寒毒热不可忍,不去也。", "b": "明·宗臣《报刘一丈书》"}, {"t": "此不为近者热而远者凉乎。", "b": "《列子·汤问》"}], "words": [{"w": "热天;热釜", "t": "热锅"}, {"w": "热浪;炽热;滚热;火热", "t": ""}]}, {"meaning": "满腔热情;热心肠 。如 :热莽(热蟒。感情狂热得不能自制);热气换冷气(好心没好报);热合(热心)。"}, {"meaning": "滚热的物体。", "cites": [{"t": "亏之若月,靡之若热。", "b": "《韩非子·扬权》"}, {"t": "谁能持热,逝不以濯。", "b": "《诗·大雅·桑柔》"}]}, {"meaning": "热气。", "cites": [{"t": "天收其声,地藏其热。", "b": "汉·扬雄《解嘲》"}]}, {"meaning": "中医学亦泛指因外感而引起的热性疾病。", "cites": [{"t": "能已(治)积热。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "热入血室", "t": "热邪进入下焦、胞宫"}, {"w": "热风", "t": "由风邪挟热所致病症"}, {"w": "产褥热;回归热;鹦鹉热;鼠咬热", "t": ""}]}, {"meaning": "激动。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1810wx','恐','1','kǒng','心','10','','[{"pinyin": "kǒng", "defs": [{"meaning": "(形声。从心,巩声。本义:严重害怕,惊恐)。"}, {"meaning": "同本义。", "cites": [{"t": "恐,惧也。", "b": "《说文》"}, {"t": "室如县罄,野无青草,何恃而不恐?", "b": "《左传·僖公二十六年》"}, {"t": "星队木鸣,国人皆恐。", "b": "《荀子·天伦》"}, {"t": "屠大窘,恐前后受其敌。", "b": "《聊斋志异·狼》"}, {"t": "秦王其破璧,乃辞谢。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "又。", "cites": [{"t": "赵王恐。", "b": ""}, {"t": "恐栗,为儿恒状。", "b": "唐·柳宗元《童区寄传》"}, {"t": "舟人大恐。", "b": "宋·苏轼《石钟山记》"}, {"t": "魏王恐。", "b": "《史记·魏公子列传》"}], "words": [{"w": "恐防", "t": "担心,提防"}, {"w": "恐虑", "t": "担心"}, {"w": "恐灼", "t": "惊恐"}, {"w": "恐怯", "t": "畏怯、害怕"}, {"w": "恐畏", "t": "畏惧"}, {"w": "恐急", "t": "惊慌。"}]}, {"meaning": "恐吓,使之害怕。", "cites": [{"t": "伺其危险之陂,以恐其主。", "b": "《韩非子·有度》"}, {"t": "李斯因说秦王,请先取韩以恐他国。", "b": "《史记·高祖本纪》"}], "words": [{"w": "恐呵", "t": "威吓呵斥"}, {"w": "恐胁", "t": "恐吓威胁"}, {"w": "恐逼", "t": "恐吓逼迫"}, {"w": "恐褐", "t": "恫吓威胁。"}]}, {"meaning": "恐怕。", "cites": [{"t": "恐前后受其敌。", "b": "唐·柳宗元《三戒》"}, {"t": "常恐秋节至。", "b": "《乐府诗集·长歌行》"}, {"t": "而恐太后玉体之有所郄也。", "b": "《战国策·赵策》"}, {"t": "恐托付不效。", "b": "诸葛亮《出师表》"}], "words": [{"w": "恐其有误;恐不容易;恐非所愿", "t": ""}]}, {"meaning": "恐怕,表示估计兼担心。", "cites": [{"t": "不治将恐深。", "b": "《韩非子·喻老》"}, {"t": "偿城恐不可得。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "恐为操所光。", "b": "《资治通鉴》"}, {"t": "恐不任我意。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1811wx','捣','1','dǎo','扌','10','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从手,岛声。本义:捣,舂)。"}, {"meaning": "同本义。", "cites": [{"t": "擣,手推也。一曰,筑也。", "b": "《说文》。字亦作“捣”。"}, {"t": "擣肉之脯。", "b": "《仪礼·有司彻》"}, {"t": "所以捣郁也。", "b": "《礼记·杂记》注"}, {"t": "捣麋鹿羊矢(屎)。", "b": "《齐民要术·种谷》"}, {"t": "夜捣戎衣向明月。", "b": "唐·李白《捣衣篇》"}], "words": [{"w": "捣碓", "t": "形容磕头如捣米似的"}, {"w": "捣嗓子", "t": "吃喝。骂人的话"}, {"w": "捣蒜打", "t": "用棍棒自上而下重重击打"}, {"w": "捣磕", "t": "叩头。"}]}, {"meaning": "冲击;攻打。", "cites": [{"t": "批(攻击)亢(吭,咽喉)捣虚。", "b": "《史记·孙膑传》"}, {"t": "杜曲则擣毁。", "b": "《管子·度地》。注:“触也。”"}], "words": [{"w": "捣虚", "t": "攻打敌方空虚之处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1812wx','壶','1','hú','士','10','','[{"pinyin": "hú", "defs": [{"meaning": "(象形。甲骨文字形,象壶形。本义:古代盛器)。"}, {"meaning": "同本义 。深腹,敛口,多为圆形,也有方形、椭圆等形制。", "cites": [{"t": "壶,昆吾圆器也。", "b": "《说文》"}, {"t": "国子执壶浆。", "b": "《公羊传·昭公二十五年》。注:“礼器,腹方口圆曰壶,反之曰方壶,有爵饰。”"}, {"t": "八壶设于西序。", "b": "《仪礼·聘礼》"}, {"t": "引壶觞。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "箪食壶浆。", "b": "《三国志·诸葛亮传》"}, {"t": "一片冰心在玉壶。", "b": "唐·王昌龄《芙蓉楼送辛渐二首》"}, {"t": "炉上有壶。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "壶瓶", "t": "盛酒器"}, {"w": "壶滥", "t": "又名壶鉴。器皿的名称"}, {"w": "壶尊", "t": "古代盛酒器"}, {"w": "壶芦", "t": "指茶壶或酒壶。"}]}, {"meaning": "古代滴水计时的器具。", "cites": [{"t": "狄人出壶。", "b": "《礼记·丧大记》。注:“漏水之器也。"}], "words": [{"w": "壶漏", "t": "古代计时器的一种"}, {"w": "壶郎", "t": "掌管刻漏计时的官员"}, {"w": "壶人", "t": "管理刻漏掌报时的人。"}]}, {"meaning": "古代宴饮时投壶的用具。", "cites": [{"t": "投壶。壶脰脩七寸,口径二寸半,壶高尺二寸,受豆斗五升,壶腹脩五寸。", "b": "《大戴礼记》"}], "words": [{"w": "壶矢", "t": "壶与矢为投壶用具,因以称投壶"}, {"w": "壶飧", "t": "用壶盛水泡饭。"}]}, {"meaning": "瓠瓜,也叫葫芦。", "cites": [{"t": "七月食瓜,八月断壶。", "b": "《诗·豳风·七月》"}, {"t": "尝抱壶而度水者,抱而蒙火。", "b": "《淮南子·说林》"}, {"t": "中流失船,一壶千金。", "b": "《鹖冠子·学问》"}], "words": [{"w": "壶庐", "t": "瓠、匏、蒲芦等瓜类的总称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1813wx','捅','1','tǒng','扌','10','','[{"pinyin": "tǒng", "defs": [{"meaning": "(形声。从手,甬(yǒng)声。本义:引;招引)。"}, {"meaning": "同本义。", "cites": [{"t": "重柔之兵,则噪而恐之,振而捅之,出则击之,不出则回之。", "b": "银雀山汉墓竹简《孙膑兵法》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1814wx','埃','1','āi','土','10','','[{"pinyin": "āi", "defs": [{"meaning": "(形声。从土,矣声。本义:尘土;灰尘) 同本义。", "cites": [{"t": "埃,尘也。", "b": "《说文》"}, {"t": "埃,谓风扬尘也。", "b": "《苍颉篇》"}, {"t": "灰尘曰埃。", "b": "《通俗文》"}, {"t": "野马也,尘埃也,生物之以息相吹也。", "b": "《庄子·逍遥游》"}, {"t": "埃不漫。", "b": "《列子·黄帝》"}, {"t": "溘埃风余上征。", "b": "《离骚》"}, {"t": "风淫所胜,则太虚埃昏。", "b": "《素问·至真要大论》"}, {"t": "上食埃土,下饮黄泉。", "b": "《荀子·劝学》"}], "words": [{"w": "埃尘", "t": "飞扬的尘土"}, {"w": "埃垢", "t": "灰尘污垢"}, {"w": "埃土", "t": "泥土,尘土。"}]}, {"meaning": "埃及的略称。"}, {"meaning": "两种波长单位的任一种。"}, {"meaning": "一百亿分之一米,即10-10米。"}, {"meaning": "镉的红色谱线波长除以6438.4696。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1815wx','挨','1','āi ái','扌','10','','[{"pinyin": "āi", "defs": [{"meaning": "(形声。从手,矣声。本义:以手击背)。"}, {"meaning": "从后推击;打。", "cites": [{"t": "挨,击背也。", "b": "《说文》"}, {"t": "挨,击也。", "b": "《广雅》"}]}, {"meaning": "靠近。", "cites": [{"t": "对垒每欲相摩挨。", "b": "王安石《和王微之登高斋》。"}], "words": [{"w": "挨晚", "t": "傍晚"}, {"w": "学校挨着工厂;挨墙靠壁", "t": ""}]}, {"meaning": "拥挤。", "cites": [{"t": "宝玉挨身而入。", "b": "曹雪芹《红楼梦》。*"}], "words": [{"w": "挨肩擦背", "t": "形容人群拥挤"}, {"w": "挨挨挤挤;挨挨擦擦", "t": ""}]}, {"meaning": "依次,顺次。", "cites": [{"t": "挨次给假回还原籍,省亲祭祖。", "b": "《明实录·洪熙实录》。"}], "words": [{"w": "挨门挨户,挨家比户", "t": "逐家逐户。"}]}]}, {"pinyin": "ái", "defs": [{"meaning": "遭受;忍受。", "cites": [{"t": "这无情棍棒,教我挨不的。", "b": "关汉卿《元曲选·窦娥冤》。"}], "words": [{"w": "挨打;挨批", "t": ""}]}, {"meaning": "拖延;磨蹭。", "cites": [{"t": "你们不替洒家打这夫子,却在背后也慢慢地挨。", "b": "《水浒传》"}]}, {"meaning": "等待。", "cites": [{"t": "好容易挨到三点半钟。", "b": "清·李宝嘉《官场现形记》"}]}, {"meaning": "困难地度过或走过。", "cites": [{"t": "只得挨过此岭,且去沙角镇上了任,却来打听。", "b": "《清平山堂话本》。"}], "words": [{"w": "挨日子", "t": "拖延时日"}, {"w": "那时候挨一天算一天;挨了一年又一年", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1816wx','耻','1','chǐ','耳','10','','[{"pinyin": "chǐ", "defs": [{"meaning": "(形声。从心,耳声。本义:耻辱,可耻的事情)。"}, {"meaning": "同本义(因声誉受损害而至的内心羞愧)。", "cites": [{"t": "耻,辱也。", "b": "《说文》"}, {"t": "君不使无耻。", "b": "《谷梁传·襄公二十九年》"}, {"t": "行己有耻。", "b": "《论语》"}, {"t": "越王苦会稽之耻。", "b": "《吕氏春秋·顺民》"}, {"t": "而患其志行之少耻也。", "b": "《国语·越语上》"}, {"t": "后世且行之而不知以为耻者多矣。", "b": "宋·刘开《问说》"}], "words": [{"w": "无耻(不顾(知)羞耻", "t": ""}, {"w": "羞耻", "t": "不光彩;不体面"}, {"w": "耻心", "t": "知耻之心。"}]}, {"meaning": "羞愧。", "cites": [{"t": "坐縻廪粟而不知耻。", "b": "刘基《卖柑者言》"}], "words": [{"w": "耻愧", "t": "羞愧"}, {"w": "耻惧", "t": "羞愧恐惧。"}]}, {"meaning": "羞辱;侮辱。", "cites": [{"t": "不醉反耻。", "b": "《诗·小雅·宾之初筵》"}, {"t": "左丘明耻之,丘亦耻之。", "b": "《论语·公冶长》"}], "words": [{"w": "耻怍", "t": "犹羞辱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1817wx','耿','1','gěng','耳','10','','[{"pinyin": "gěng", "defs": [{"meaning": "(形声。从火,圣(shèng)省声。本义:耳贴于颊)。"}, {"meaning": "同本义。"}, {"meaning": "明亮,光明。", "cites": [{"t": "跪敷衽(铺开衣襟)以陈辞兮,耿吾既得此中正(指正道)。", "b": "《楚辞·屈原·离骚》"}], "words": [{"w": "耿耀", "t": "照耀"}, {"w": "耿光", "t": "光明;光辉"}, {"w": "耿晶晶", "t": "形容物体明亮闪光的样子"}, {"w": "耿烈", "t": "光明炽热"}, {"w": "耿介", "t": "光明正大。"}]}, {"meaning": "心情不安;悲伤。", "cites": [{"t": "耿耿不寐,如有隐忧。", "b": "《诗·邶风·柏舟》"}], "words": [{"w": "耿耿于心", "t": "形容心中有事牵挂,无法忘却"}, {"w": "耿介", "t": "心中不安"}, {"w": "耿灼", "t": "焦虑不安。"}]}, {"meaning": "刚直。", "cites": [{"t": "参差相叠重重,刚耿陵宇宙。", "b": "唐·韩愈《南山诗》"}, {"t": "人主不除此五蠹之民,不养耿介之士,则海内虽有破亡之国,削灭之朝。", "b": "《韩非子·五蠹》"}], "words": [{"w": "耿介", "t": "耿直;刚直;正大光明"}, {"w": "耿正", "t": "刚强正直"}, {"w": "耿怀", "t": "直率的情怀"}, {"w": "耿挺", "t": "坚贞特立。"}]}, {"meaning": "气忿时头面上血管膨胀,红筋暴露的样子。", "cites": [{"t": "余大先生气得两脸紫涨,颈子里的筋都耿出来。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1818wx','耽','1','dān','耳','10','','[{"pinyin": "dān", "defs": [{"meaning": "(形声。从耳,冘(yín)声。本义:耳朵大而且下垂) 同本义。", "cites": [{"t": "夸父耽耳。", "b": "《淮南子·地形》。高注:“耽耳,耳垂在肩上。”"}], "words": [{"w": "耽毵", "t": "毛长下垂纷披的样子。"}]}, {"meaning": "沉溺。", "cites": [{"t": "于嗟女兮,无与士耽。", "b": "《诗·卫风·氓》"}, {"t": "士之耽兮。", "b": "《诗·卫风·氓》。传:“乐也。”"}, {"t": "妻子好合,如鼓瑟琴,兄弟既翕,和乐且耽。", "b": "《礼记》"}, {"t": "惟耽乐之从。", "b": "《书·无逸》"}, {"t": "耽于女乐,不顾国政,则亡国之祸也。", "b": "《韩非子·十过》"}, {"t": "且耽田家乐。", "b": "李白《赠闾丘处士》"}], "words": [{"w": "耽着", "t": "迷恋"}, {"w": "耽思深思,潜心研究探讨;耽乐", "t": "沈迷于享乐。"}]}, {"meaning": "承受;担负。", "cites": [{"t": "我要及时就死,又耽不起吞金服毒的。", "b": "《红楼梦》"}], "words": [{"w": "耽险", "t": "担风险;危险"}, {"w": "耽待", "t": "耽带。照顾,帮助;宽容;原谅;担当,承受;等候。"}]}, {"meaning": "嗜;喜好。", "cites": [{"t": "你本身做亭长,耽几盏酒。", "b": "元·睢景臣《高祖还乡》"}], "words": [{"w": "耽好", "t": "特别爱好"}, {"w": "耽志", "t": "专心致志"}, {"w": "耽尚", "t": "爱好,尊崇"}, {"w": "耽研", "t": "专心研究"}, {"w": "耽意", "t": "专心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1819wx','聂','1','niè','耳','10','','[{"pinyin": "niè", "defs": [{"meaning": "(会意。从三耳。本义:附耳小语)。"}, {"meaning": "同本义。", "cites": [{"t": "聂,附耳私小语也。", "b": "《说文》"}, {"t": "乃效女儿咕嗫私语。", "b": "《史记·魏其武安侯列传》"}], "words": [{"w": "聂许", "t": "附耳私语"}, {"w": "聂聂", "t": "轻小,轻虚平和的样子。"}]}, {"meaning": "假借为“摄”。握持。", "cites": [{"t": "为人两手聂其耳。", "b": "《山海经·海外北经·聂耳国》"}]}, {"meaning": "古代地名 。在今山东省聊城县东北。"}, {"meaning": "", "cites": [{"t": "聂政之刺韩傀也,白虹贯日。", "b": "《战国策·魏策》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1820wx','恭','1','gōng','小','10','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从心,共声。本义:恭敬,谦逊有礼)。"}, {"meaning": "同本义。", "cites": [{"t": "密人不恭,敢距大邦。", "b": "《诗·大雅·皇矣》"}, {"t": "恭,敬也。", "b": "《尔雅》"}, {"t": "何胤云,在貌为恭,在心为敬,何之所说,从多举也。", "b": "《礼记·曲礼上》疏"}, {"t": "君子敬而无失,与人恭而有礼。", "b": "《论语·颜渊》"}, {"t": "公子执辔愈恭。", "b": "《史记·魏公子列传》"}], "words": [{"w": "恭默", "t": "谦恭沈静不语"}, {"w": "恭倨", "t": "恭敬和傲慢"}, {"w": "恭恪", "t": "心存恭敬而态度谨慎"}, {"w": "恭敬", "t": "犹尊敬"}, {"w": "恭和", "t": "谦恭温和"}, {"w": "恭逢其盛", "t": "亲身经历到那种盛况"}, {"w": "恭素", "t": "恭谨纯朴。"}]}, {"meaning": "奉行。", "cites": [{"t": "今予惟恭行天之罚。", "b": "《书·甘誓》"}], "words": [{"w": "恭承", "t": "敬奉。"}]}, {"meaning": "拱手致礼。", "cites": [{"t": "请过了文昌,大人朝上又打三恭。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1821wx','莽','1','mǎng','艹','10','','[{"pinyin": "mǎng", "defs": [{"meaning": "(会意。从犬,从茻。原意是犬跑到草丛中逐兔,假借为茻,草丛)。"}, {"meaning": "草丛。", "cites": [{"t": "莽,草也。", "b": "《小尔雅》"}, {"t": "暴骨如莽。", "b": "《左传·哀公元年》"}, {"t": "在野曰草芒之臣。", "b": "《孟子》"}, {"t": "罗千乘于林莽。", "b": "《汉书·扬雄传》"}, {"t": "地饶广荐草莽水泉。", "b": "《汉书·景帝纪》。注:“草稠曰荐,深曰莽。”"}, {"t": "伏戎于莽。", "b": "《易·同人》"}], "words": [{"w": "莽林", "t": "泛指草木密集连绵而不能通过的森林;专指热带雨林"}, {"w": "莽渺", "t": "深远而渺茫的样子"}, {"w": "莽草", "t": "一种有毒植物,又称“水莽草”。"}]}, {"meaning": "草。", "cites": [{"t": "食莽饮水,枕块而死。", "b": "《淮南子》"}]}, {"meaning": "茂密;盛多。", "cites": [{"t": "滔滔孟夏兮,草木莽莽。", "b": "《楚辞·九章·怀沙》"}], "words": [{"w": "莽然", "t": "草木茂盛的样子;也指众多的样子。"}]}, {"meaning": "无涯际的样子。", "cites": [{"t": "莽,大也。", "b": "《小尔雅》"}, {"t": "何以为之莽莽也。", "b": "《吕氏春秋·知接》。注:“长大貌。”"}, {"t": "平原莽千里。", "b": "谭嗣同《出潼关渡河》"}], "words": [{"w": "莽沆", "t": "水广大的样子"}, {"w": "莽泱", "t": "辽阔广远的样子"}, {"w": "莽莽苍苍", "t": "无边无际"}, {"w": "?", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1822wx','莱','1','lái','艹','10','','[{"pinyin": "lái", "defs": [{"meaning": "(形声。从艸,来声。本义:草名。即藜)。"}, {"meaning": "草名,又名藜 。一种一年生草本植物。嫩苗可食,生田间、路边、荒地、宅旁等地,为古代贫者常食的野菜。", "cites": [{"t": "莱,蔓华也。", "b": "《说文》"}, {"t": "南山有台,北山有莱。", "b": "《诗·小雅·南山有台》"}]}, {"meaning": "", "cites": [{"t": "莱驹为右。(莱驹作晋侯的车右武士。)", "b": "《左传·僖公三十三年》"}]}, {"meaning": "长满杂草。", "cites": [{"t": "莱五十亩。", "b": "《周礼·遂人》"}, {"t": "莱,野也。", "b": "《越绝书·吴内传》"}, {"t": "田卒污莱。", "b": "《诗·小雅·十月之交》"}]}, {"meaning": "除草。", "cites": [{"t": "若大田猎,则莱山田之野。", "b": "《周礼·地官·山虞》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1823wx','莲','1','lián','艹','10','','[{"pinyin": "lián", "defs": [{"meaning": "(形声。从艸,连声。本义:莲子,荷的种子)。"}, {"meaning": "同本义。", "cites": [{"t": "莲,扶渠之实也。", "b": "《说文》"}, {"t": "荷其实莲。", "b": "《尔雅》。注:“谓房也。”"}, {"t": "益树莲茭。", "b": "《淮南子·本经》"}, {"t": "莲藕觚卢。", "b": "《汉书·司马相如传》"}], "words": [{"w": "莲的", "t": "莲房之实。即莲子"}, {"w": "莲须", "t": "即莲心。本为莲花的雄蕊。又叫莲蕊须"}, {"w": "莲子花", "t": "指爱怜儿子的老人。莲子:谐音怜子。"}]}, {"meaning": "也称芙蓉、芙蕖、菡萏等。多年生草本植物,生浅水中。叶子大而圆,叫荷叶。花有粉红、白色两种。种子叫莲子,包在倒圆锥形的花托内,合称莲蓬。地下茎叫藕。", "cites": [{"t": "接天莲叶无穷碧。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "予独爱莲出淤泥而不染。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "莲社", "t": "东晋高僧居庐山东林寺时结成的文社。因寺内有白莲花,故名"}, {"w": "莲台", "t": "佛像下面的莲花状坐台"}, {"w": "莲炬", "t": "形状如莲花的蜡烛"}, {"w": "莲船", "t": "采莲的船;比喻莲叶为船。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1824wx','莫','1','mò mù','艹','10','','[{"pinyin": "mò", "defs": [{"meaning": "表示否定,相当于“不”。", "cites": [{"t": "莫相知。", "b": "唐·柳宗元《三戒》"}, {"t": "莫敢过其门。", "b": "唐·柳宗元《童区寄传》"}, {"t": "故莫能知。", "b": "宋·苏轼《石钟山记》"}, {"t": "莫能得。", "b": "《史记·魏公子列传》"}], "words": [{"w": "莫得", "t": "没有"}, {"w": "爱莫能助;一筹莫展;莫可奈何", "t": "犹言无可奈何"}, {"w": "莫之奈何", "t": "对它们无可奈何"}, {"w": "莫或", "t": "没有"}, {"w": "莫奈何", "t": "无可奈何。"}]}, {"meaning": "表示劝戒。不要;不可;不能。", "cites": [{"t": "慎莫留。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "莫相忘。", "b": ""}, {"t": "莫愁前路无知己。", "b": "唐·高适《别董大》"}, {"t": "莫用众人。", "b": "《资治通鉴》"}], "words": [{"w": "闲人莫入;莫怪", "t": "不要怪罪"}, {"w": "莫教", "t": "休教,别让"}, {"w": "莫得", "t": "休得,不得"}, {"w": "莫道", "t": "休说,不要说。"}]}, {"meaning": "没有谁;没有什么(指处所或事物)。", "cites": [{"t": "莫能守。", "b": "《墨子·公输》"}, {"t": "莫之许。", "b": "《三国志·诸葛亮传》"}, {"t": "莫敢违。", "b": "《资治通鉴·唐纪》"}, {"t": "莫不然。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "莫大的幸福;莫大欣喜;莫二", "t": "没有第二个;无比。"}]}, {"meaning": "生物体内部的薄皮组织。", "cites": [{"t": "搦脑髓,爪荒莫。", "b": "《韩诗外传·卷十》"}]}, {"meaning": "沙漠。", "cites": [{"t": "狄之广莫,于晋为都。", "b": "《国语·晋语》"}]}, {"meaning": "幕府。", "cites": [{"t": "莫府省约文书籍事。", "b": "《史记·李将军列传》"}]}, {"meaning": "疾苦,病。", "cites": [{"t": "监观四方,求民之莫。", "b": "《诗·大雅·皇矣》"}, {"t": "辞之怿矣,民之莫矣。", "b": "《诗·大雅·板》"}]}, {"meaning": "谟划。", "cites": [{"t": "秩秩大猷,圣人莫之。", "b": "《诗·小雅·巧言》"}]}, {"meaning": "削。", "cites": [{"t": "而刀可以莫铁,则刃游閒也。", "b": "《管子·制分》"}]}, {"meaning": "思慕,向往。", "cites": [{"t": "君子之于天下也,无适也,无莫也。", "b": "《论语·里仁》"}]}, {"meaning": "广漠。", "cites": [{"t": "广莫之野。", "b": "《庄子·逍遥游》"}]}, {"meaning": "寂静。", "cites": [{"t": "田莫不见禽而后反。", "b": "《管子·小匡》"}]}]}, {"pinyin": "mù", "defs": [{"meaning": "(会意。甲骨文字形。从日,从茻(mǎng)。太阳落在草丛中,表示傍晚天快黑了。是“暮”的本字。本义:日落时)。"}, {"meaning": "同本义。", "cites": [{"t": "莫,日且冥也。", "b": "《说文》"}, {"t": "莫,夜也。", "b": "《广雅》"}, {"t": "不夙则莫。", "b": "《诗·齐风·东方未明》"}, {"t": "谁夙知而莫成?", "b": "《诗·大雅·抑》"}, {"t": "维莫之春。", "b": "《诗·周颂·臣工》"}, {"t": "及莫又圣。", "b": "《礼记·文王世子》"}, {"t": "旦莫日进食。", "b": "《战国策·齐策》"}, {"t": "星辰莫同。", "b": "《书·洪范》"}, {"t": "莫夜月明。", "b": "宋·苏轼《石钟山记》"}, {"t": "莫春者。", "b": "《论语·先进》"}], "words": [{"w": "莫夜", "t": "夜晚。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1825wx','莉','1','lì','艹','10','','[{"pinyin": "lì", "defs": [{"meaning": "人名用字。"}, {"meaning": "(mòlì)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1826wx','荷','1','hé hè','艹','10','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从艸,何声。本义:植物名。也称莲,别称芙蕖、芙蓉。地下茎称藕,子实称莲,花叶供观赏)。"}, {"meaning": "植物名。即莲。", "cites": [{"t": "荷,芙蕖叶。", "b": "《说文》"}, {"t": "隰有荷华。", "b": "《诗·郑风·山有扶苏》"}, {"t": "有蒲与荷。", "b": "《诗·陈风·泽陂》"}, {"t": "荷叶之清香。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "荷月", "t": "指农历六月,以荷花盛开,故名荷月"}, {"w": "荷衣", "t": "荷叶"}, {"w": "荷芰", "t": "莲与菱"}, {"w": "荷花", "t": "莲花。也作“莲华”、“荷华”"}, {"w": "荷扇", "t": "荷叶形圆似团扇,故雅称为荷扇。"}]}, {"meaning": "古代酒器荷叶杯的代称。", "cites": [{"t": "明画烛,洗金荷,主人起舞客齐歌。", "b": "宋·辛弃疾《鹧鸪天》"}]}]}, {"pinyin": "hè", "defs": [{"meaning": "用肩扛或担;背负。", "cites": [{"t": "荷担者三夫。", "b": "《列子·汤问》"}, {"t": "以杖荷蓧。", "b": "《论语·微子》"}], "words": [{"w": "荷锄;荷蓧丈人", "t": "担着耘田竹杖的老人;隐士"}, {"w": "荷校", "t": "以肩荷枷。即颈上带枷。校,枷"}, {"w": "荷担", "t": "肩挑东西。"}]}, {"meaning": "肩负,担负。", "cites": [{"t": "子击磬于卫,有荷蒉而过孔氏门者。", "b": "《论语·宪问》"}], "words": [{"w": "荷累", "t": "负累;牵累"}, {"w": "荷担", "t": "承担生活、工作、责任、事业等。"}]}, {"meaning": "承受;承蒙。", "cites": [{"t": "荷天下之重任。", "b": "张衡《东京赋》"}], "words": [{"w": "荷佩", "t": "承受"}, {"w": "荷得", "t": "承蒙;亏得"}, {"w": "荷护", "t": "保佑,佑护"}, {"w": "荷蒙", "t": "承蒙;承受。"}]}, {"meaning": "用于书信中表示感谢或客气 。如感荷;拜荷;荷佩(荷佩。感荷;感激);荷恩(蒙受恩惠);荷眷(荷睠。承受恩宠;承蒙关注)。"}, {"meaning": "古泽名。又水名。也作“菏”。", "cites": [{"t": "菏,泽名,见《夏书》。古本亦作荷。", "b": "《五经文字》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1827wx','获','1','huò','艹','10','','[{"pinyin": "huò", "defs": [{"meaning": "(形声。从犬,蒦(huó)声。按甲骨文从隹从又,表示捕鸟在手。本义:猎得禽兽)。"}, {"meaning": "同本义。", "cites": [{"t": "获,猎所获也。", "b": "《说文》"}, {"t": "田获三狐。", "b": "《易巽》"}, {"t": "舍拔则获。", "b": "《诗·秦风·驷賳》"}, {"t": "谋于野则获。", "b": "《左传·襄公三十一年》"}, {"t": "今日畋乐乎?获多乎?", "b": "司马相如《子虚赋》"}], "words": [{"w": "获兽;获兔;获者", "t": "猎得禽兽者。"}]}, {"meaning": "俘获。", "cites": [{"t": "遇犬获之。", "b": "《诗·小雅·巧言》"}, {"t": "获者取左耳。", "b": "《周礼·大司马》"}, {"t": "不获二毛。", "b": "《礼记·檀弓》"}, {"t": "荻百里孟明视。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "获丑", "t": "俘获敌众"}, {"w": "获夷", "t": "能俘获夷狄者"}, {"w": "获解", "t": "拘捕押送"}, {"w": "拿获", "t": ""}]}, {"meaning": "得到;取得。", "cites": [{"t": "获,得也。", "b": "《小尔雅·广言》"}, {"t": "遭遇时变,以获爵位。", "b": "杨恽《报孙会宗书》"}, {"t": "初虽劳苦,卒获其庆。", "b": "《盐铁论·诛秦》"}, {"t": "获莒挐。", "b": "《左传·僖公元年》"}, {"t": "获宝玉大弓。", "b": "《左传·定公九年》"}, {"t": "获者坐而获。", "b": "《仪礼·乡射礼》"}, {"t": "凡得获货贿人民六畜者。", "b": "《周礼·朝士》"}, {"t": "获有所闻。", "b": "明·宋濂《送东阳马生序》"}, {"t": "幸获名成。", "b": "清·周容《芋老人传》"}, {"t": "两人并获释。", "b": "《明史》"}, {"t": "获矢无算。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "获奖;获匹", "t": "获偶。得到配偶"}, {"w": "获印", "t": "得到官印,意为得官"}, {"w": "获成", "t": "得到和解,得到成功。"}]}, {"meaning": "打猎得到的禽兽。", "cites": [{"t": "狗良则数得兽矣; 田猎之获, 常过人矣。", "b": "《吕氏春秋》"}]}, {"meaning": "中国古代奴婢的贱称。", "cites": [{"t": "行曲则违于臧获, 行直则怒于诸侯。", "b": "《韩非子》"}, {"t": "且夫臧获婢妾,犹能引决,况仆之不得已乎。", "b": "汉·司马迁《报任少卿书》"}]}, {"meaning": "(形声。从禾,蒦(huó)声。本义:收割庄稼)。"}, {"meaning": "同本义。", "cites": [{"t": "获,刈谷也。", "b": "《说文》"}, {"t": "八月剥枣,十月获稻。", "b": "《诗·豳风·七月》"}, {"t": "是获是亩。", "b": "《诗·大雅·生民》"}, {"t": "载获济济。", "b": "《诗·周颂·载芟》"}, {"t": "儒有不陨获于贫贱。", "b": "《礼记·儒行》"}, {"t": "以岁之不获也。", "b": "《国语·吴语》"}, {"t": "一岁而再获之。", "b": "《荀子·富国》"}, {"t": "不耕获。", "b": "《易·无妄》"}, {"t": "耕获菑畬,时时利赖其用。", "b": "徐光启《甘薯疏序》"}], "words": [{"w": "秋获冬藏", "t": ""}]}, {"meaning": "割取草木。", "cites": [{"t": "有冽氿泉,无浸获薪。", "b": "《诗·小雅·大东》"}]}, {"meaning": "收获;收成。", "cites": [{"t": "王公之家,一宴之味,费上农一岁之获,犹食之而不甘。", "b": "唐甄《潜书·大命》"}]}, {"meaning": "得到的成果或利益。", "cites": [{"t": "一树一获者,谷也;一树十获者,木也;一树百获者,人也。", "b": "《管子》"}]}, {"meaning": "木名,榆属,叶如榆,皮坚韧,可作姮索甑带。", "cites": [{"t": "有冽氿泉,无浸穫薪。", "b": "《诗·小雅·大东》。郑玄笺云:檴、落,木名也。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1828wx','晋','1','jìn','日','10','','[{"pinyin": "jìn", "defs": [{"meaning": "(会意。小篆字形,从日。指追着太阳一直前进。本义:上进)。"}, {"meaning": "进。", "cites": [{"t": "晉,进也。日出,万物进。", "b": "《说文》"}, {"t": "晋者,进也。", "b": "《易·序卦》"}, {"t": "王提马而走诸侯晋。", "b": "《周礼·田仆》"}, {"t": "盍孟晋以迨群兮。(盍:为什么不;孟,勉力;迨,赶上;群:大家。)", "b": "班固《幽通赋》"}], "words": [{"w": "晋谒", "t": "晋见;谒见"}, {"w": "晋接", "t": "进见;接见"}, {"w": "晋食", "t": "进献食品。"}]}, {"meaning": "晋升。提高地位、级别或荣誉。", "cites": [{"t": "以功晋知府。", "b": "《清史稿·桂中行传》"}, {"t": "晋封英王。", "b": "《陈玉成》"}], "words": [{"w": "晋封", "t": "晋升加封"}, {"w": "晋秩", "t": "晋升官职或等级"}, {"w": "晋阶", "t": "升级"}, {"w": "晋号", "t": "—hào晋升其称号。"}]}, {"meaning": "低,俯。", "cites": [{"t": "见梓晋然实而俯。", "b": "《尚书大传》"}], "words": [{"w": "晋然", "t": "低垂的样子;俯下的样子。"}]}, {"meaning": "周代诸侯国名 。周成王封弟叔虞于唐,叔虞子燮父改国号为晋,春秋时居有今山西省大部与河北省西南地区,地跨黄河两岸。后被其大夫韩、赵、魏所分而亡。", "cites": [{"t": "子夏之晋。", "b": "《吕氏春秋·慎行论》"}, {"t": "晋师三豕过河。", "b": ""}, {"t": "晋师己亥涉河。", "b": ""}, {"t": "晋于是始墨。(晋国从此以黑衣为丧服。墨,活用为动词,意动用法。)——《左传·僖公三十二——三十三年》", "b": ""}], "words": [{"w": "晋用楚材", "t": "谓一国聘用别国的人才"}, {"w": "晋邦", "t": "指春秋时代的晋国"}, {"w": "晋阳之甲", "t": "喻称地方官吏不满朝廷而举兵向内为兴“晋阳之甲”"}, {"w": "晋棘", "t": "指春秋晋国垂棘之地所产的美玉。"}]}, {"meaning": "朝代名。"}, {"meaning": "司马炎代魏称帝,国号晋,都洛阳,史称西晋(公元265—316年),共四帝,为前赵所灭。", "cites": [{"t": "晋太原中。", "b": "晋·陶渊明《桃花源记》"}, {"t": "无论魏晋。", "b": ""}, {"t": "魏晋氏以下。", "b": "唐·柳宗元《柳河东集》"}, {"t": "晋陶渊明独爱菊。", "b": "宋·周敦颐《爱莲说》"}]}, {"meaning": "司马睿即位建康,保有江南之地,史称东晋(公元317—420年),共十一帝,为刘裕所取代。"}, {"meaning": "五代时,石敬瑭灭后唐称帝,国号晋,都洛阳,史称后晋(公元936—946年)。", "cites": [{"t": "背晋以归染。", "b": "宋·欧阳修《新五代史·伶官传》"}], "words": [{"w": "晋年", "t": "喻指怀念故朝之思"}, {"w": "晋帖", "t": "指晋人的书迹或其摹本、刻帖"}, {"w": "晋京", "t": "晋朝的京城。指洛阳。"}]}, {"meaning": "水名 。源出山西省太原市西南悬瓮山,分北、中、南三渠,东流入汾河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1829wx','恶','1','è wū ě wù','心','10','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从心,亚声。本义:过失)。"}, {"meaning": "同本义。", "cites": [{"t": "恶,过也。", "b": "《说文》"}, {"t": "恶上安西。", "b": "《颜氏家训》"}, {"t": "吾以志前恶。", "b": "《左传·定公五年》"}, {"t": "君子之遏恶扬善。", "b": "《易·象传》"}], "words": [{"w": "恶恶从短", "t": "对于人的过失,不十分苛责,适可而止。"}]}, {"meaning": "泛指一般罪恶。", "cites": [{"t": "恶积祸盈。", "b": "南朝齐·丘迟《与陈伯之书》"}], "words": [{"w": "恶逆", "t": "奸恶逆乱。古代刑律十恶大罪之一"}, {"w": "恶障", "t": "佛语。指杀生、偷盗等妨碍修行的罪恶"}, {"w": "恶头儿", "t": "罪名"}, {"w": "恶心钱儿", "t": "干坏事得来的钱财"}, {"w": "恶孽", "t": "罪恶;弊病。"}]}, {"meaning": "恶人;坏人。", "cites": [{"t": "元恶不待教而诛。", "b": "《荀子·王制》"}], "words": [{"w": "恶杀都来", "t": "刽子手在刑场上逞威风而发出的叫喊声。恶杀:即凶神恶煞。"}]}, {"meaning": "丑陋。", "cites": [{"t": "五曰恶。", "b": "《书·洪范》。传:“丑陋也。”"}, {"t": "人莫知其子之恶。", "b": "《礼记·大学》"}, {"t": "恶者美之充也。", "b": "《管子·枢言》"}, {"t": "今子美而我恶。", "b": "《韩非子·说林上》"}, {"t": "鬼侯有子而好,故入之于纣,纣以为恶。", "b": "《战国策·赵策》"}, {"t": "昔贾大夫恶,取妻而美。", "b": "《左传·昭公二十八年》"}], "words": [{"w": "恶丈夫", "t": "丑陋汉子"}, {"w": "恶女", "t": "容貌丑陋之女。"}]}, {"meaning": "坏;不好。", "cites": [{"t": "廉君宣恶言。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "恶衣恶食,陋车驽马。", "b": "《汉书·王莽传上》"}, {"t": "岁恶不入。", "b": "贾谊《论积贮疏》"}], "words": [{"w": "恶宾", "t": "不受欢迎的客人。即恶客"}, {"w": "恶逆", "t": "不善,不顺。"}]}, {"meaning": "污秽;肮脏。", "cites": [{"t": "色恶不食,臭恶不食。", "b": "《论语·乡党》"}, {"t": "立厩中仆马之间,恶气袭衣裾,即饥寒毒热不可忍,不去也。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "恶路", "t": "恶露。妇女产后由阴道排出的液体"}, {"w": "恶水", "t": "泔水"}, {"w": "恶水缸儿", "t": "泔脚水缸。"}]}, {"meaning": "贫瘠。", "cites": [{"t": "田虽薄恶,收可亩十石。", "b": "《齐民要术·耕田》"}], "words": [{"w": "恶郡", "t": "贫瘠荒远的州郡"}, {"w": "恶处", "t": "贫瘠的地方。"}]}]}, {"pinyin": "wū", "defs": [{"meaning": "表示疑问,相当于“何”、“怎么”。", "cites": [{"t": "恶,安也。", "b": "《广韵》"}, {"t": "恶识宗?", "b": "《左传·襄公二十八年》"}, {"t": "弃父之命,恶用子矣!", "b": "《左传·桓公十六年》"}, {"t": "彼恶知之。", "b": "《孟子·梁惠王上》"}, {"t": "恶能无纪。", "b": "明·袁宏道《满井游记》"}]}, {"meaning": "表示惊讶。", "cites": [{"t": "恶,是何言也?", "b": "《孟子》"}, {"t": "恶,是何言。", "b": "清·梁启超《饮冰室合集·文集》"}]}]}, {"pinyin": "ě", "defs": [{"meaning": "要呕吐的感觉", "words": [{"w": "恶心", "t": "亦指对人和事的厌恶态度。"}]}]}, {"pinyin": "wù", "defs": [{"meaning": "讨厌;憎恶。", "cites": [{"t": "天不为人之恶寒而辍冬。", "b": "《荀子·天论》"}, {"t": "唯仁者,能好人,能恶人。", "b": "《论语·里仁》"}, {"t": "诚好恶何如。", "b": "唐·柳宗元《柳河东集》"}, {"t": "好逸恶劳。", "b": "清·黄宗羲《原君》"}, {"t": "怨恶其君。", "b": ""}], "words": [{"w": "甚恶", "t": "讨厌之极;非常讨厌;反感之至"}, {"w": "恶忌", "t": "厌恶猜忌"}, {"w": "恶生", "t": "厌生"}, {"w": "恶不去善", "t": "不因厌恶其人而抹杀他的优点"}, {"w": "恶杀", "t": "厌恶杀生"}, {"w": "恶紫夺朱", "t": "厌恶以邪代正"}, {"w": "恶嫌", "t": "讨厌"}, {"w": "恶惮", "t": "厌恶畏惧"}, {"w": "恶识", "t": "冒犯;得罪"}, {"w": "恶上", "t": "憎恶长上"}, {"w": "这人真可恶;憎恶", "t": "憎恨;厌恶"}, {"w": "深恶痛绝;恶恶", "t": "憎恨邪恶。"}]}, {"meaning": "嫉妒。", "cites": [{"t": "[刘]表恶其能而不能用也。", "b": "《资治通鉴》"}]}, {"meaning": "诽谤;中伤。", "cites": [{"t": "人之有技,冒疾以恶之。", "b": "《书·秦誓》"}, {"t": "太子痤美而狠,合佐师畏而恶之。", "b": "《左传·襄公二十六年》"}, {"t": "比而恶之。", "b": "《左传·昭公二十七年》"}, {"t": "人有恶苏秦于燕王者,曰:“武安君,天下不信人也。", "b": "《战国策》"}], "words": [{"w": "恶讪", "t": "诽谤。"}]}, {"meaning": "忌讳。", "cites": [{"t": "大史典礼,执简记奉讳恶。", "b": "《礼记》"}]}, {"meaning": "羞耻,羞愧。", "cites": [{"t": "无盖恶之心,非人也。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "恶囊", "t": "窝囊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1830wx','莹','1','yíng','艹','10','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从玉,荧(yíng)省声。本义:珠光的光采)。"}, {"meaning": "同本义。", "cites": [{"t": "莹,玉色。一曰石之次玉者。", "b": "《说文》"}, {"t": "如玉之莹。", "b": "《逸论语》"}, {"t": "良珠度寸,虽有白仞之水,不能掩其莹。", "b": "《韩诗外传》"}], "words": [{"w": "莹华", "t": "光辉。"}]}, {"meaning": "似玉的宝石。", "cites": [{"t": "尚之以琼莹乎而。", "b": "《诗·齐风·著》"}]}, {"meaning": "光洁透明。", "cites": [{"t": "此人之水镜,见之莹然。", "b": "《晋书·乐广传》"}, {"t": "色泽莹润。", "b": "陆游《过小孤山大孤山》"}], "words": [{"w": "莹玉", "t": "光洁透明的玉"}, {"w": "莹滑", "t": "晶莹润滑"}, {"w": "莹静", "t": "晶莹洁白。"}]}, {"meaning": "使明洁。使生光泽。", "cites": [{"t": "夫良玉未剖,与百石相类;名骥未弛,与驽马相杂。乃其剖而莹之,弛而试之,玉石驽骥然后始分。", "b": "《周书·苏绰传》"}], "words": [{"w": "莹拂", "t": "磨拭;使光洁"}, {"w": "莹磨", "t": "谓磨治使光洁"}, {"w": "莹目", "t": "使眼睛明亮。"}]}, {"meaning": "明白;觉悟。", "cites": [{"t": "…其论尚多未莹者。", "b": "梁启超语"}], "words": [{"w": "莹净", "t": "明白,清楚"}, {"w": "莹听", "t": "明听,明白事理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1831wx','莺','1','yīng','艹','10','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从鸟,荣省声。本义:鸟羽有文彩的样子) 同本义。", "cites": [{"t": "春莺,《考声》:‘莺,鸟毛有斑纹貌也。", "b": "唐·慧琳《一切经音义》"}, {"t": "有莺其羽。", "b": "《诗·小雅》"}], "words": [{"w": "莺背色", "t": "浅黄带绿的颜色"}, {"w": "莺粉", "t": "黄色的粉。"}]}, {"meaning": "黄莺 。又称黄鹂、仓庚等。", "cites": [{"t": "暮春三月,江南草长,杂花生树,群莺乱飞。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "千里莺啼绿映红。", "b": "唐·杜牧《江南春绝句》"}], "words": [{"w": "莺花队", "t": "指妓女行列"}, {"w": "莺花寨(莺花市),莺花阵(指妓院", "t": ""}, {"w": "莺语", "t": "莺的鸣叫声"}, {"w": "莺歌", "t": "莺鸣蜿转如歌"}, {"w": "莺谷", "t": "黄莺栖止的山谷。比喻人在显达以前的处境"}, {"w": "莺娇", "t": "莺声娇美。比喻女子美妙的歌声"}, {"w": "莺簧", "t": "莺篁。指莺声悦耳如笙簧。常用以喻指笛声"}, {"w": "莺啭", "t": "莺啼;也形容声音像莺啼般动听。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1832wx','真','1','zhēn','目','10','','[{"pinyin": "zhēn", "defs": [{"meaning": "(会意。小篆字形,从华(huà),从目,从乚(yǐn),从八。《说文》:“仙人变形而登天也。”匕,变化。目,眼睛。乚,隐藏。八,乘载的工具。本义:道家称存养本性或修真得道的人为真人)。"}, {"meaning": "同本义。旧时所谓仙人。", "cites": [{"t": "真,仙人变形而登天也。", "b": "《说文》。按:六经无真字"}, {"t": "夫免乎外内之刑者,唯真人能之。", "b": "《庄子·列御寇》"}, {"t": "归其真宅。", "b": "《列子·天瑞》。注:“太虚之域。”"}, {"t": "而已反其真,而我犹为人猗。", "b": "《庄子·大宗师》"}], "words": [{"w": "真人府", "t": "道人居住的地方"}, {"w": "真仙", "t": "仙人"}, {"w": "真君", "t": "道教对神仙的尊称"}, {"w": "真味", "t": "真实的意旨或意味。"}]}, {"meaning": "本性;本原。", "cites": [{"t": "谨守而勿失,是谓反其真。", "b": "《庄子·秋水》"}], "words": [{"w": "真宰", "t": "宇宙的主宰者;造物主"}, {"w": "真佛", "t": "本身;本人。比喻难以见到的人物"}, {"w": "真力", "t": "本原之力"}, {"w": "真原", "t": "本源"}, {"w": "真源", "t": "本源,本性。"}]}, {"meaning": "身。", "cites": [{"t": "见利而忘其真。", "b": "《庄子·山水》"}]}, {"meaning": "肖像,摹画的人像。", "cites": [{"t": "有僧写得师真,呈师,师曰:“且道似我不似我?”", "b": "《景德传灯录》"}]}, {"meaning": "汉字楷书的别称。", "cites": [{"t": "帝亲书其文,作真、行、草三体。", "b": "《续资治通鉴》"}], "words": [{"w": "真字", "t": "正楷字。"}]}, {"meaning": "古州名。", "cites": [{"t": "广德元年设吐蕃,其后松、…真、…等为行州。", "b": "《新唐书》"}]}, {"meaning": "真实。与假、伪相对。", "cites": [{"t": "假金方用真金镀。", "b": "李绅《答章孝标》"}, {"t": "使真伪毋相乱。", "b": "《汉书·宣帝纪》"}, {"t": "此画果真。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "而同于真。", "b": ""}, {"t": "真者而同。", "b": ""}]}, {"meaning": "亦为佛教观念,与“妄”相对。", "cites": [{"t": "窈兮冥兮,其中有精,其精甚真,其中有信。", "b": "《老子》"}], "words": [{"w": "真人真事;真假难分;真形", "t": "真实的形体或形象"}, {"w": "真教", "t": "纯真的教化"}, {"w": "真笔", "t": "真迹"}, {"w": "真相", "t": "佛教语。犹言本相,实相。后指事物的本来面目或真实情况。"}]}, {"meaning": "正。与副、邪相对。", "cites": [{"t": "恭楷誊真,双手呈与抚台。", "b": "《文明小史》"}], "words": [{"w": "真红", "t": "正红;深红色"}, {"w": "真楷", "t": "指正楷"}, {"w": "真宅", "t": "人死后的真正归宿"}, {"w": "真粹", "t": "品德高超"}, {"w": "真履", "t": "纯正的志行。"}]}, {"meaning": "精;淳。", "cites": [{"t": "发匣琴徽静,开瓶酒味真。", "b": "唐·张祜《乐静》"}], "words": [{"w": "真白", "t": "纯白色"}, {"w": "真金", "t": "纯金;真正的金子"}, {"w": "真钢", "t": "纯钢"}, {"w": "真品", "t": "纯真的品质"}, {"w": "真风", "t": "淳朴的风俗"}, {"w": "真朴", "t": "纯真朴素。"}]}, {"meaning": "本来的,固有的。", "cites": [{"t": "不识庐山真面目,只缘身在此山中。", "b": "宋·苏轼《题西林壁》"}], "words": [{"w": "真态", "t": "本色;天然风致。"}]}, {"meaning": "真诚;诚实,情感真切。", "cites": [{"t": "真者,精诚之至也。…真在内者,神动于外,是所以贵真也。", "b": "《庄子·渔父》"}], "words": [{"w": "真列", "t": "坚贞忠烈"}, {"w": "真忱", "t": "真诚"}, {"w": "真修", "t": "精诚修持"}, {"w": "真信", "t": "真诚"}, {"w": "真笃", "t": "诚挚深厚"}, {"w": "真恳", "t": "真诚恳切"}, {"w": "真至", "t": "情感真挚。"}]}, {"meaning": "清楚;真切。", "cites": [{"t": "我没大看真,不知是四根,不知是六根。", "b": "《醒世姻缘传》"}], "words": [{"w": "听得真;看得真;真亮;真真", "t": "清清楚楚,明明白白。"}]}, {"meaning": "实在;的确。", "cites": [{"t": "真无马邪?", "b": "唐·韩愈《杂说》"}, {"t": "真不知马也。", "b": ""}], "words": [{"w": "这人真好;跑得真快;真不忝", "t": "真不愧"}, {"w": "真可", "t": "真可以;真能够"}, {"w": "真来", "t": "实在;确实。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1833wx','框','1','kuàng','木','10','','[{"pinyin": "kuàng", "defs": [{"meaning": "(形声。从木,匡声。本义:门窗的架子)。"}, {"meaning": "棺门。", "cites": [{"t": "两手据地而欧之不出,喀喀然遂伏而死。", "b": "《列子·说符》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1834wx','梆','1','bāng','木','10','','[{"pinyin": "bāng", "defs": [{"meaning": "(本义:木名)。"}, {"meaning": "梆子,用竹筒或挖空木头做成的发声器。用于巡更或聚众。", "cites": [{"t": "知县才发二梆,不曾坐堂。", "b": "《儒林外史》"}]}, {"meaning": "中国地方戏曲梆子腔打击乐器梆子的简称。"}, {"meaning": "敲打木头的声音。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1835wx','桂','1','guì','木','10','','[{"pinyin": "guì", "defs": [{"meaning": "(形声。从木,圭声。本义:木名。《说文》:“江南木,百药之长。”)。"}, {"meaning": "肉桂(Cinnamomum cassia),常绿乔木,花黄色,果实黑色,树皮可做健胃剂,又可调味。", "cites": [{"t": "芩藭厚朴桂栝蒌。", "b": "《急就篇》"}]}, {"meaning": "月桂属的乔木或灌木,尤指月桂,其叶子被古希腊人用来为德尔斐神桂冠竞技运动的胜利者加冠。"}, {"meaning": "即木犀(Osmanthus fragrans),亦称“桂花”。常绿灌木或小乔木,叶对生、椭圆形,花黄色或黄白色,极芳香,果黑色。花可作香料。", "cites": [{"t": "问讯吴刚何所有,吴刚捧出桂花酒。", "b": "毛泽东《蝶恋花·答李淑一》"}], "words": [{"w": "桂霭", "t": "桂花的香气"}, {"w": "桂魄", "t": "相传月中有桂,因以借指月亮"}, {"w": "桂醑", "t": "桂花美酒"}, {"w": "桂花", "t": "月光"}, {"w": "桂殿凉蟾", "t": "月亮的别称。传说月亮里有桂树和蟾蜍而得名。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1836wx','桔','1','jié jú','木','10','','[{"pinyin": "jié", "defs": [{"meaning": "桔梗,一种多年生草本植物。", "cites": [{"t": "桔,桔梗药草也。从人,吉声。", "b": "《说文》"}, {"t": "今求柴胡桔梗于沮泽,累世不得一焉。", "b": "《战国策·秦策》"}], "words": [{"w": "桔档儿", "t": "高粱秆的顶端细的部分。"}]}, {"meaning": "桔槔 。古代的一种井上汲水工具,是架在水边的杠杆,一端挂水桶,一端坠大石块。"}, {"meaning": "直木。", "cites": [{"t": "桔,直木。", "b": "《说文》"}]}]}, {"pinyin": "jú", "defs": [{"meaning": "“橘”的俗字。", "cites": [{"t": "桔者小而甘,曰松皮,桔皮红不粘肉。", "b": "清·屈大均《广东新语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1837wx','栖','1','qī xī','木','10','','[{"pinyin": "qī", "defs": [{"meaning": "(棲本作“西”。同“栖”。形声。从木,妻声。本义:鸟类歇息)。"}, {"meaning": "同本义。", "cites": [{"t": "鸡栖于厅。", "b": "明·归有光《项脊轩志》"}, {"t": "山有栖鹘。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "栖竿", "t": "捕虫鸟的黏竿"}, {"w": "栖山", "t": "栖息于山。指隐遁"}, {"w": "栖峙", "t": "栖止伫立"}, {"w": "栖荡", "t": "栖息游荡"}, {"w": "栖歇", "t": "栖止,歇止"}, {"w": "栖鸟", "t": "栖宿于树上的鸟"}, {"w": "栖鸟于泉", "t": "使鸟停息于泉中。"}]}, {"meaning": "停留。", "cites": [{"t": "遥谢荷蓧翁,聊得从居栖。", "b": "晋·陶渊明文"}, {"t": "与汝双栖。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "两栖", "t": "水陆两处生活"}, {"w": "栖迟", "t": "游息"}, {"w": "栖所", "t": "居留之地"}, {"w": "栖泊", "t": "居留;停泊;寄居。"}]}, {"meaning": "居住;寄居。", "cites": [{"t": "越王勾践栖于会稽之上。", "b": "《国语·越语上》"}], "words": [{"w": "栖苴", "t": "寄生在树上己枯萎的草"}, {"w": "栖住", "t": "居住"}, {"w": "栖凭", "t": "居住安身"}, {"w": "栖寓", "t": "寄居,暂住"}, {"w": "栖处", "t": "栖居,寄居。"}]}, {"meaning": "居息的处所,止息的地方。", "cites": [{"t": "疲马恋旧秣,羁禽思故栖。", "b": "孟郊《鸦路溪行呈陆中丞诗》"}]}, {"meaning": "床。", "cites": [{"t": "二嫂使治朕栖。", "b": "《孟子·万章上》。注:“栖,床也。”"}]}]}, {"pinyin": "xī", "defs": [{"meaning": "忙忙碌碌;不安定。", "cites": [{"t": "六月栖栖,戎车既饬。", "b": "《诗·小雅·六月》"}], "words": [{"w": "栖屑", "t": "奔忙不安的样子"}, {"w": "栖栖", "t": "忙碌不安的样子"}, {"w": "栖栖默默", "t": "忙碌而失意的样子"}, {"w": "栖遑", "t": "栖皇,栖惶。忙碌不安,奔忙不定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1838wx','档','1','dàng','木','10','','[{"pinyin": "dàng", "defs": [{"meaning": "(形声。从木,当声。本义:器物上用以分格或撑的横木条)。"}, {"meaning": "同本义。", "cites": [{"t": "俗谓横木框档。", "b": "《正字通》"}], "words": [{"w": "床档;十三档算盘", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1839wx','桐','1','tóng','木','10','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。从木,同声。本义:木名,也名“荣”)。"}, {"meaning": "树名  古书中多指梧桐科的梧桐,还有大戟科的油桐,玄参科的泡桐等。", "cites": [{"t": "桐,荣也。", "b": "《说文》"}, {"t": "荣,桐木。", "b": "《尔雅》。按,与梧同类而异,皮青而泽,荚边缀子如乳者为梧,亦谓之青桐。皮白,材中琴瑟,有华无实者为桐,亦谓之梧桐。"}, {"t": "其桐其椅。", "b": "《诗·小雅·湛露》"}, {"t": "桐始华。", "b": "《礼记·月令》"}, {"t": "工之侨得良桐。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "桐人", "t": "桐木偶"}, {"w": "桐子", "t": "梧桐树的果实;油桐的果实"}, {"w": "桐木人", "t": "桐木作的人形"}, {"w": "桐花烟", "t": "桐华烟。桐油烧的烟"}, {"w": "桐杖", "t": "桐木作的手杖;古时为母送丧时拄的孝杖。"}]}, {"meaning": "春秋国名。", "cites": [{"t": "桐叛楚。", "b": "《左传·定公二年》"}]}, {"meaning": "今安徽桐城县北有古桐城。"}, {"meaning": "古地名 。故址在今山西万荣县西。一说在今河北临漳。"}, {"meaning": "儿童", "cites": [{"t": "学则正,否则邪,师哉师哉,桐子之命也。", "b": "《法言·学行》"}], "words": [{"w": "桐子", "t": "儿童,童子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1840wx','株','1','zhū','木','10','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从木,朱声。本义:露出地面的树根)。"}, {"meaning": "同本义。", "cites": [{"t": "株,木根也。", "b": "《说文》。今语转曰桩。"}, {"t": "命曰株送徒。", "b": "《史记·平准书》。集解:“根蒂也。”"}, {"t": "若厥株驹。", "b": "《列子·黄帝》。释文:“枯树本也。”"}, {"t": "田中有株,兔走触株,折颈而死。", "b": "《韩非子·五蠹》"}]}, {"meaning": "又。", "cites": [{"t": "释其来而守株。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "皆守株之类。", "b": ""}], "words": [{"w": "株橛", "t": "树桩、木根"}, {"w": "株蘖", "t": "树木砍伐后根株生出的枝条。"}]}, {"meaning": "泛指草木。", "cites": [{"t": "泽涸无鱼,山童无株。", "b": "汉·焦赣《易林》"}]}, {"meaning": "植根。", "cites": [{"t": "大株于土;萍于水。", "b": "晋·干宝《搜神记》"}], "words": [{"w": "株榾", "t": "残根断树"}, {"w": "株柢", "t": "根祗"}, {"w": "株枸", "t": "枯树根。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1841wx','桥','1','qiáo','木','10','','[{"pinyin": "qiáo", "defs": [{"meaning": "(形声。从木,乔声。本义:桥梁)。"}, {"meaning": "同本义。", "cites": [{"t": "桥,水梁也。从木,乔声。骈木为之者。独木者曰杠。", "b": "《说文》"}, {"t": "宁新中更名安阳,初作河桥。", "b": "《史记·秦本纪》"}, {"t": "洛水桥边春日斜。", "b": "刘禹锡《浪淘沙》"}, {"t": "长桥卧波。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "桥边红药。", "b": "宋·姜夔《扬州慢》"}, {"t": "桥边一带。", "b": "《广东军务记》"}], "words": [{"w": "桥阁", "t": "傍山架木为路。即栈道,阁道"}, {"w": "桥津", "t": "桥头。津,水边渡口。"}]}, {"meaning": "器物上的横杆。", "cites": [{"t": "奉席如桥衡。", "b": "《礼记·曲礼》。注:“井上桔槔。”"}], "words": [{"w": "鞍桥", "t": ""}]}, {"meaning": "架桥,修桥。", "cites": [{"t": "桥孙水,以通邛都。", "b": "《史记·司马相如列传》"}]}, {"meaning": "纠正。", "cites": [{"t": "以桥饰其情性。", "b": "《荀子·儒效》"}, {"t": "掉指桥以偃蹇兮。", "b": "《史记·司马相如列传》"}]}, {"meaning": "高。", "cites": [{"t": "山有桥松,隰有游龙。", "b": "《诗·郑风·山有扶苏》"}, {"t": "于是桥起。", "b": "《庄子·则阳》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1842wx','桦','1','huà','木','10','','[{"pinyin": "huà", "defs": [{"meaning": "(形声。从木,华声。本义:木名。桦木) 桦木属(Betula)植物的泛称。落叶乔木或灌木", "words": [{"w": "白桦", "t": ""}, {"w": "黑桦", "t": ""}, {"w": "小叶桦", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1843wx','栓','1','shuān','木','10','','[{"pinyin": "shuān", "defs": [{"meaning": "(形声。从木,全声。本义:木钉;插子)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1844wx','桃','1','táo','木','10','','[{"pinyin": "táo", "defs": [{"meaning": "(形声。从木,兆声。本义:果木名)。"}, {"meaning": "桃树。", "cites": [{"t": "桃,桃果也。", "b": "《说文》"}, {"t": "桃之夭夭。", "b": "《诗·周南·桃夭》"}, {"t": "园有桃。", "b": "《诗·魏风·园有桃》"}]}, {"meaning": "桃子。", "cites": [{"t": "投我以桃。", "b": "《诗·大雅·抑》"}, {"t": "简桃核修狭者。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "桃来李答", "t": "相互馈赠"}, {"w": "桃李之馈", "t": "送礼,贿赂。"}]}, {"meaning": "指桃树开的花。", "cites": [{"t": "华如桃李。", "b": "《诗·召南·何彼禯矣》"}]}, {"meaning": "指形状像桃的其他果实 。如棉桃。"}, {"meaning": "地名。春秋鲁邑 。故址在今山东省汶上县北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1845wx','格','1','gé gē','木','10','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从木,各声。本义:树木的长枝条)。"}, {"meaning": "同本义。", "cites": [{"t": "格,木长貌。", "b": "《说文》。徐锴系传:“亦谓树高长枝为格。”"}, {"t": "夭娇枝格,偃蹇杪颠。", "b": "司马相如《上林赋》"}, {"t": "角者,言万物皆有枝格如角也。", "b": "《史记·律书》"}, {"t": "草树混淆,枝格相交。", "b": "北周·庾信《小园赋》"}]}, {"meaning": "引申为格子。", "cites": [{"t": "格,椸架也。", "b": "《一切经音义》引苍颉"}, {"t": "共其牛牲之互。", "b": "《周礼·地官·牛人》。注:“互,若今屠家县肉格。”"}, {"t": "窗格上有火燃处。", "b": "《梦溪笔谈·活板》"}, {"t": "每韵为一帖,木格贮之", "b": ""}], "words": [{"w": "五格的书架;格眼", "t": "格子和窟窿"}, {"w": "格子眼", "t": "窗孔"}, {"w": "格目", "t": "项目"}, {"w": "格的", "t": "箭靶。"}]}, {"meaning": "栅栏。", "cites": [{"t": "连云列战格,飞鸟不能逾。", "b": "杜甫《潼关吏》"}], "words": [{"w": "战格", "t": "作战时防御的栅栏。"}]}, {"meaning": "法式;标准;规格。", "cites": [{"t": "言有物而行有格也。", "b": "《礼记·缁衣》"}, {"t": "我劝天公重抖擞,不拘一格降人才。", "b": "清·龚自珍《己亥杂诗》"}, {"t": "武德二年,颁新格(特指法律条文)五十三条。", "b": "《旧唐书·刑法志》"}], "words": [{"w": "格范", "t": "典范;标准"}, {"w": "格尺", "t": "标准"}, {"w": "格令", "t": "法令"}, {"w": "格法", "t": "成法,法度"}, {"w": "格条", "t": "法令条文"}, {"w": "格样", "t": "标准式样;模样。"}]}, {"meaning": "箭靶子。", "cites": [{"t": "夫射,仪度不得,则格的不中。", "b": "《淮南子·兵略》"}], "words": [{"w": "格的", "t": "箭靶中心。"}]}, {"meaning": "表明某词在一定上下文中与其它词之间意义关系的屈折变化形式(如主格、 宾格、 所有格)。"}, {"meaning": "茖葱。山葱。", "cites": [{"t": "桂荏、凫葵,格韮菹于。", "b": "《后汉书·马融传》"}]}, {"meaning": "村落。", "cites": [{"t": "置伯格长,以牧司奸盗贼。", "b": "《史记·酷吏王温舒传》"}]}, {"meaning": "阻止;搁置。", "cites": [{"t": "形格势禁,则自为解耳。", "b": "《史记·孙子吴起列传》附《孙膑传》"}], "words": [{"w": "格沮", "t": "阻止,阻挡"}, {"w": "格格不入", "t": "相互抵触"}, {"w": "格阂", "t": "阻隔,隔阂"}, {"w": "格塞", "t": "阻塞,不通顺"}, {"w": "格碍", "t": "阻碍,障碍"}, {"w": "格笔", "t": "笔架;搁笔,停止写作。"}]}, {"meaning": "纠正,匡正。", "cites": [{"t": "人不足与適(同“谪”)也,政不足闲(非议)也;惟大人为能格君心之非。", "b": "《孟子·离娄上》"}], "words": [{"w": "格非", "t": "匡正邪辟谬误的心"}, {"w": "格心", "t": "匡正思想;归正之心"}, {"w": "格正", "t": "匡正时弊;纠正。"}]}, {"meaning": "推究。", "cites": [{"t": "致知在格物,物格而后知至。", "b": "《礼记·大学》"}], "words": [{"w": "格术", "t": "格物之术"}, {"w": "格量", "t": "推度;衡量"}, {"w": "格物致知", "t": "谓研究事物原理而获得知识"}, {"w": "格候", "t": "谓推算季候节气。"}]}, {"meaning": "击打;格斗。", "cites": [{"t": "格者不舍。", "b": "《荀子·议兵》"}, {"t": "穷寇不格。", "b": "《周书·武称》"}, {"t": "皆可格杀。", "b": "《后汉书·刘盆子传》"}, {"t": "乃解衣就(接受)格。", "b": "《后汉书·钟离意传》"}, {"t": "男儿宁当格斗死,何能怫郁筑长城。", "b": "《玉台新咏·饮马长城窟行》"}], "words": [{"w": "格击", "t": "格斗"}, {"w": "格拒", "t": "抵抗;格斗"}, {"w": "格战", "t": "格斗,搏斗。"}]}, {"meaning": "击杀;搏杀。", "cites": [{"t": "郢人等告定国,定国使谒者以他法劾捕格杀郢人以灭口。", "b": "《史记·荆燕世家》"}], "words": [{"w": "格化", "t": "斩杀"}, {"w": "格敌", "t": "杀敌"}, {"w": "格斩", "t": "击杀。"}]}, {"meaning": "抗拒;抗御。", "cites": [{"t": "尝从行,有所冲陷折关及格猛兽。", "b": "《史记·李将军列传》"}], "words": [{"w": "格拒", "t": "抗拒格斗"}, {"w": "格迕", "t": "抵触,不合。"}]}, {"meaning": "古书借“格”为“佫”。来到,到达。", "cites": [{"t": "光被四表,格于上下。", "b": "《书·舜典》"}, {"t": "格尔众庶,悉听朕言。", "b": "《书·汤誓》"}, {"t": "天迪格保。", "b": "《书·召诰》"}, {"t": "惟先格王。", "b": "《书·高宗肜日》"}, {"t": "祖考来格。", "b": "《书·益稷》"}, {"t": "格于皇天。", "b": "《书·君诰》"}], "words": [{"w": "格思", "t": "来,到。思,语助词。"}]}, {"meaning": "大。", "cites": [{"t": "孝友时格,永乃保之。", "b": "《仪礼·士冠礼》"}, {"t": "以格于主人。", "b": "《仪礼·少牢馈食礼》"}], "words": [{"w": "格命", "t": "皇命。"}]}]}, {"pinyin": "gē", "defs": [{"meaning": "", "words": [{"w": "格登", "t": "走路时脚踏地的声音"}, {"w": "格剌子", "t": "角落;偏僻的地方"}, {"w": "格支支", "t": "物体断裂、撞击、摩擦的声音"}, {"w": "格喳", "t": "木棍断裂声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1846wx','桩','1','zhuāng','木','10','','[{"pinyin": "zhuāng", "defs": [{"meaning": "(形声。从木庄声。舂(chōng)。本义:桩子,打入地中以固基础的木橛)。"}, {"meaning": "同本义。", "cites": [{"t": "樁,橛杙也。", "b": "《说文新附》"}, {"t": "下整高颓,深平险谷,摆桩栝,开林丛。", "b": "唐·李白《大猎赋》"}], "words": [{"w": "船桩;桥桩;短树桩;铁桩;水泥桩;桩歌", "t": "夯歌"}, {"w": "桩橛", "t": "木桩。大者谓桩,小者谓橛。"}]}, {"meaning": "储物备用的内库 。宋代有“封桩库”。"}, {"meaning": "储备;储存。", "cites": [{"t": "除刘宝私财还宝外,余并桩充军须。", "b": "《续资治通鉴》"}], "words": [{"w": "桩管", "t": "储存保管"}, {"w": "桩积", "t": "积存。"}]}, {"meaning": "插;栽。", "cites": [{"t": "武松手到,轻轻地只一提,攧入怀里来,两手揪住,也望大酒缸里只一丢,桩在里面。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1847wx','校','1','jiào xiào','木','10','','[{"pinyin": "jiào", "defs": [{"meaning": "古代刑具。枷械的统称。", "cites": [{"t": "校,木囚也。从木,交声。", "b": "《说文》"}, {"t": "屦校灭趾。", "b": "《易·噬嗑》。"}, {"t": "何校灭耳。注:“若今枷项也。”", "b": ""}, {"t": "大校重牢,五木被体。", "b": "《新唐书》"}]}, {"meaning": "栅栏。", "cites": [{"t": "天子校猎。", "b": "《汉书·司马相如传》。注:“以木相贯穿,总为栏校,遮止禽兽而猎取之。”"}], "words": [{"w": "校猎", "t": "用木栏遮阻而猎取禽兽。校:木栏。"}]}, {"meaning": "“校人”的省称。养马官。", "cites": [{"t": "六厩成校。", "b": "《周礼·校人》"}, {"t": "校正属焉。", "b": "《左传·成公十八年》。注:“主马官。”"}], "words": [{"w": "校人", "t": "周礼官名。马官之长。"}]}, {"meaning": "古代军营的一种建制。亦指“军营”。", "cites": [{"t": "常护军傅校获王。", "b": "《汉书·卫青传》。注:“校者,营垒之称。”"}, {"t": "五校大夫。", "b": "《战国策·中山策》。注:“军营也。”"}], "words": [{"w": "校队", "t": "古时军队的编制单位。亦指部队,队伍"}, {"w": "校联", "t": "谓营垒相联"}, {"w": "校骑", "t": "骑兵队伍"}, {"w": "校垒", "t": "营垒。"}]}, {"meaning": "订正,改正。", "cites": [{"t": "校,度也。", "b": "《广雅》"}, {"t": "后购求得书,以相校,无所遗失。", "b": "《汉书·张安世传》"}, {"t": "年逾八十,犹乎自校书。", "b": "陈寿《三国志》"}], "words": [{"w": "校稿子;校一本书;校书", "t": "校对勘正书中的讹误;古代还指有文才的妓女"}, {"w": "校理", "t": "校勘书籍而加以整理;唐宋官名。掌理校勘整理袐府藏书之事"}, {"w": "校缀", "t": "将散佚的书籍加以校对整理,连缀在一起。"}]}, {"meaning": "考核,考察。", "cites": [{"t": "比校民之有道者。", "b": "《国语·齐语》"}, {"t": "以实校之。", "b": "《资治通鉴》"}], "words": [{"w": "校度", "t": "考察衡量"}, {"w": "校官", "t": "古代专司探察情事的官吏"}, {"w": "校事", "t": "三国时魏、吴均设校事,为皇帝刺探臣民的言行"}, {"w": "校比", "t": "调查户口、财物;考核评定"}, {"w": "校贯", "t": "核点经费"}, {"w": "校数", "t": "数计。"}]}, {"meaning": "较量。", "cites": [{"t": "校武票禽。", "b": "扬雄《长杨赋》"}, {"t": "不与诸弟校竞。", "b": "李延寿《北史》"}], "words": [{"w": "校兵", "t": "交战"}, {"w": "校武", "t": "考较武艺"}, {"w": "较勇", "t": "较量勇力"}, {"w": "校埒", "t": "比武场"}, {"w": "校射", "t": "比试射技和武艺"}, {"w": "校能", "t": "比试才艺"}, {"w": "校棋", "t": "切磋棋艺。"}]}, {"meaning": "对抗;抗衡。", "cites": [{"t": "韩魏之强,足以校于秦。", "b": "《史记》"}, {"t": "而与奥同盟之德国,示威胁俄,俄不敢校,而塞卒吞声。", "b": "梁启超《欧战蠡测》"}]}, {"meaning": "计较;考虑。", "cites": [{"t": "犯而不校。", "b": "《论语》"}, {"t": "其间得失何足校。", "b": "宋·欧阳修《寄圣俞》"}], "words": [{"w": "校怨", "t": "计较怨仇"}, {"w": "校计", "t": "犹计较"}, {"w": "校竞", "t": "犹计较"}, {"w": "校短推长", "t": "校短量长。谓衡量别人的长处和短处。"}]}]}, {"pinyin": "xiào", "defs": [{"meaning": "(形声。从木,交(jiào)声。(jiào)本义:古代拘囚犯人的刑具)。"}, {"meaning": "学堂,学校。", "cites": [{"t": "校,教学之宫。", "b": "《集韵》"}, {"t": "设为庠序学校以教之。庠者,养也;校者,教也;序者,射也。", "b": "《孟子·滕文公上》"}, {"t": "郑人游于幺校。", "b": "《左传·襄公三十一年》。注:“郑国谓学为校。”"}, {"t": "郡国曰学,县、道、邑侯国曰校。", "b": "《汉书·平帝纪》"}, {"t": "夏曰校,殷曰序,周曰庠,学则三代共之,皆所以明人伦也。", "b": "《孟子》"}], "words": [{"w": "校序", "t": "古代称学校"}, {"w": "校室", "t": "古代乡里的公共教育场所"}, {"w": "校学", "t": "学校。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1848wx','核','1','hé hú','木','10','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从木,亥声。本义:果核)。"}, {"meaning": "同本义。", "cites": [{"t": "核,蛮夷以木皮为箧,状如籢尊。", "b": "《说文》"}, {"t": "桃李丑核。", "b": "《尔雅·释木》"}, {"t": "殽核维旅。", "b": "《诗·小雅·宾之初筵》"}, {"t": "其实濡核。", "b": "《素问·五常正大论》"}, {"t": "贻余核舟。", "b": "明·魏学洢《核舟记》"}, {"t": "桃核修狭者。", "b": ""}], "words": [{"w": "枣核;樱桃核;葡萄核;橘核", "t": ""}]}, {"meaning": "有核的果实。", "cites": [{"t": "门启,华堂复阁甚秀,馆中有樽酒盘核。", "b": "《太平广记》引"}]}, {"meaning": "核心;中心。", "cites": [{"t": "文吏不学,世之教无核也。", "b": "王充《论衡·量知》"}]}, {"meaning": "查对;审查。", "cites": [{"t": "凡学问之法,不为无才,难于距师,核道实义,证定是非也。", "b": "《论衡·问孔》"}, {"t": "综核名实。", "b": "《汉书·宣帝纪赞》"}, {"t": "其审核之,务准古法。", "b": "《汉书·刑法志》。颜师古云:核,究其实也。"}, {"t": "研核阴阳。", "b": "《后汉书·张衡传》"}], "words": [{"w": "核正", "t": "查核订正"}, {"w": "核批", "t": "审查批示"}, {"w": "核视", "t": "审查察看"}, {"w": "核夺", "t": "审核决定。"}]}]}, {"pinyin": "hú", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1849wx','样','1','yàng','木','10','','[{"pinyin": "yàng", "defs": [{"meaning": "(形声。从木,羕(yàng)声。本义:栩实,字亦作橡)。"}, {"meaning": "假借为“像”。式样。", "cites": [{"t": "去年中使宣口敕,天上取样人间织。", "b": "唐·白居易《缭绫》"}], "words": [{"w": "样银", "t": "用于测定银子成色的样品"}, {"w": "样儿", "t": "样子。指可供人模仿的式样或效法的标准"}, {"w": "样子间", "t": "陈列样品的处所"}, {"w": "样米", "t": "作为样品的米"}, {"w": "样物", "t": "作为样品之物"}, {"w": "样度", "t": "样式,法式"}, {"w": "样当", "t": "样子,模样"}, {"w": "样制", "t": "物品的样式"}, {"w": "样钱", "t": "钱币铸成后呈验的样品。"}]}, {"meaning": "形状,模样。", "cites": [{"t": "映日荷花别样红。", "b": "宋·杨万里《晓出净慈寺送林子方》"}], "words": [{"w": "样法", "t": "样范"}, {"w": "样色", "t": "花样"}, {"w": "式样", "t": "人造的物体的形状"}, {"w": "走样", "t": "失去原来的样子"}, {"w": "花样", "t": "花纹的式样,也泛指一切式样或种类"}, {"w": "样制", "t": "物品的样式。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1850wx','根','1','gēn','木','10','','[{"pinyin": "gēn", "defs": [{"meaning": "(形声。从木,艮(gèn)声。本义:草木之根)。"}, {"meaning": "植物生长于土中或水中吸收营养的部分。", "cites": [{"t": "根,木株也。", "b": "《说文》"}, {"t": "蔓根为根,直根为柢。", "b": "《说文通训定声》"}, {"t": "根深,则视久。", "b": "《韩非子·解老》"}, {"t": "是谓深根、固柢。", "b": "《老子》"}, {"t": "有根株于下,有荣叶于上。", "b": "《论衡·超奇》"}, {"t": "其无宿根者,候苗成而未有花时采,则根生已足而又未衰。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "斯亦伐根以求木茂,塞源而欲流长也。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "根荄", "t": "根。荄:草根;又指根本,根源"}, {"w": "根茇", "t": "植物的根部"}, {"w": "根柢", "t": "草木的根"}, {"w": "根垓", "t": "根核。植物的根;植根。"}]}, {"meaning": "事物的本源,根由,依据。", "cites": [{"t": "根,始也。", "b": "《广雅·释诂一》"}, {"t": "根者,书之所谓柢也。", "b": "《韩非子·解老》"}, {"t": "万物有所生,而独知守其根。", "b": "《淮南子·原道》"}, {"t": "盖志士仁人所为根心者也。", "b": "《后汉书·宋弘传》"}, {"t": "然病之生也,有根有柢。", "b": "陈亮《与彭子寿祭酒》"}, {"t": "近岁市人转相摹刻诸子百家之书,……其文词学术当倍蓰于昔人,而后生科举之士,皆束书不观,游谈无根,此又何也?", "b": "宋·苏轼《李君山房记》"}], "words": [{"w": "祸根", "t": "祸事的根源;引起灾祸的人或事物"}, {"w": "根浅门微", "t": "根基浅,门第低微"}, {"w": "根儿", "t": "根本"}, {"w": "根气", "t": "根基。指禀赋、气质"}, {"w": "根儿里", "t": "根本;本来"}, {"w": "根苗", "t": "兆头,开头。"}]}, {"meaning": "物体的下部,基部。", "cites": [{"t": "满庭田地湿,荠叶生墙根。", "b": "唐·白居易《早春》"}], "words": [{"w": "根下", "t": "物体的根基附近"}, {"w": "墙根;堤根;根前", "t": "跟前。"}]}, {"meaning": "痼疾。", "cites": [{"t": "自去夏侵暑,入此秋变,头齿眩疼,根痼渐剧。", "b": "《宋书·颜延之传·自陈表》"}], "words": [{"w": "根疵", "t": "痼疾。"}]}, {"meaning": "数学名词。代数方程中未知数的值,或称代数方程式的解;方根的简称。"}, {"meaning": "延续后代的子孙。", "cites": [{"t": "夏堪……零陵太守之根嗣也。", "b": "《相府小史夏堪碑》"}], "words": [{"w": "根嗣", "t": "长子"}, {"w": "根谱", "t": "犹族史"}, {"w": "根祖", "t": "祖宗。"}]}, {"meaning": "植根。", "cites": [{"t": "半生无根着,飘转如断梗。", "b": "金·元好问《出京》诗"}], "words": [{"w": "根着", "t": "植根于地。"}]}, {"meaning": "杜绝;根除。", "cites": [{"t": "若攻之不根,是养疾疴于心腹也。", "b": "《后汉书·西羌传论》"}], "words": [{"w": "根株", "t": ""}]}, {"meaning": "根究;追究。", "cites": [{"t": "其己为民间侵耕地土,更不根究,盖以本议欲以见在牧地,给与民耕,岂可却根究己耕之地,重为搔扰。", "b": "宋·欧阳修《论牧马草地剳子》"}], "words": [{"w": "根勘", "t": "彻底查究"}, {"w": "根究着实", "t": "追根究底,打听清楚"}, {"w": "根刷", "t": "根刮,彻底清查;彻底搜求"}, {"w": "根穷", "t": "彻底追查。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1851wx','索','1','suǒ','糸','10','','[{"pinyin": "suǒ", "defs": [{"meaning": "(会意。意为用绳子把木头束起。于省吾认为是绳索。本义:大绳子)。"}, {"meaning": "同本义 。后泛指各种绳索。", "cites": [{"t": "索,草有茎叶可作绳索。", "b": "《说文》"}, {"t": "其次关木索,被箠楚受辱。", "b": "司马迁《报任安书》"}, {"t": "鹿裘带索,鼓琴而歌。", "b": "《列士·天瑞》"}, {"t": "追讨南度河,使军吏田晏、夏育慕先登,悬索相引。复战于罗亭,大破之。", "b": "《后汉书·段颍传》"}, {"t": "昼尔于茅,宵而索綯。", "b": "《诗·豳风·七月》"}], "words": [{"w": "索苇", "t": "用苇作成的绳索"}, {"w": "索头", "t": "绳头"}, {"w": "索桥", "t": "用绳索连结两岸的桥。"}]}, {"meaning": "法度。", "cites": [{"t": "皆启以商政,疆以周索。", "b": "《左传·定公四年》。杜预注:“索,法也。”"}]}, {"meaning": "中国古地名 。故地在今河南荥阳县。秦末刘邦与项羽战于京、索之间的索,即此地。"}, {"meaning": "索县 。中国汉代建立的县,在今湖南省常德市东。属武陵郡,顺帝时更名汉寿。今为湖南汉寿县。"}, {"meaning": "搜索。", "cites": [{"t": "索,入家搜也。", "b": "《说文》"}, {"t": "忘索之。", "b": "《史记·范睢蔡泽传》"}, {"t": "大索天下。", "b": "《汉书·张良传》"}, {"t": "举国大索。", "b": "《汉书·韩安国传》"}, {"t": "延年索怀中,得重劾。", "b": "《汉书·严延年传》"}, {"t": "居五日,桓侯体痛,使人索扁鹊,已逃秦矣。", "b": "《韩非子·喻老》"}, {"t": "遂闻君将合众于楚,约与食客门下二个人偕,不外索。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "遍索不得;搜索", "t": "搜查"}, {"w": "索隐行怪", "t": "深求隐僻的事而行为怪谲。"}]}, {"meaning": "寻求;探索。", "cites": [{"t": "探求异闻,采摭典故,解其所未改,申其所未申,故以索隐为名。", "b": "唐·司马贞《史记索隐》自序"}, {"t": "路曼曼其修远兮,吾将上下而求索。", "b": "屈原《离骚》"}], "words": [{"w": "索垢寻庇", "t": "无事生非,找荐儿滋事"}, {"w": "索摸", "t": "寻找,寻觅"}, {"w": "索合", "t": "寻求志同道合的人"}, {"w": "索秘", "t": "探索隐微。"}]}, {"meaning": "挑选。", "cites": [{"t": "以索马牛。", "b": "《左传·襄公二年》"}], "words": [{"w": "索牛", "t": "挑选出来的好牛"}, {"w": "索引", "t": "又称引得,把书刊,文献等作品中的重要课题录出按一定的顺序排列,以便检索。"}]}, {"meaning": "求取,讨取。", "cites": [{"t": "县官急索租,租税从何出?", "b": "唐·杜甫《兵车行》"}, {"t": "凡死刑狱上行刑者先俟于门外,使其党入索财物,名曰“斯罗”。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "索战", "t": "讨战"}, {"w": "索号", "t": "回令;求取约定的暗号"}, {"w": "索将", "t": "索取;求取"}, {"w": "索逋", "t": "索要欠款"}, {"w": "索掯", "t": "索取"}, {"w": "索句", "t": "索取诗句"}, {"w": "索米", "t": "求取米粮"}, {"w": "索命", "t": "索取性命"}, {"w": "索饭", "t": "讨取食物。"}]}, {"meaning": "须,应,得。", "cites": [{"t": "一壁厢纳草除根,一边又要差夫,索应付。", "b": "元·睢景臣《[般涉调]哨遍·高祖还乡》"}, {"t": "虽无人窃听,也索悄声儿海誓山盟。", "b": "白仁甫《元曲选·梧桐树》"}], "words": [{"w": "索将", "t": "须使"}, {"w": "索是", "t": "须是,煞是,真是"}, {"w": "只索", "t": "只得"}, {"w": "索须", "t": "必须。"}]}, {"meaning": "捻绳使紧。", "cites": [{"t": "传语又称纣力能索铁伸钩。", "b": "《论衡·语譄》"}, {"t": "矫菌桂以纫蕙兮,索胡绳之纚纚。", "b": "屈原《离骚》"}], "words": [{"w": "索绳", "t": "紧绳。"}]}, {"meaning": "独自,孤单。", "cites": [{"t": "直为亲旧故,未忍言索居。", "b": "晋·陶渊明《和刘柴桑》"}, {"t": "索索无真气,昏昏有俗心。", "b": "北国·庾信《拟咏怀》"}], "words": [{"w": "离群索居;索处", "t": "索居"}, {"w": "索居", "t": "独居一方"}, {"w": "索索", "t": "冷落的样子。"}]}, {"meaning": "涕泪流出貌。", "cites": [{"t": "子綦索然出涕曰:“吾子何为以至于是极也。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "索索落落", "t": "眼泪纷纷落下的样子。"}]}, {"meaning": "索性;干脆。", "cites": [{"t": "只是士大夫不青索性尽底里说话,不可专咎人主。", "b": "宋·朱熹《与魏之履书》"}], "words": [{"w": "索兴", "t": "干脆;直截了当。"}]}, {"meaning": "尽;空。", "cites": [{"t": "悉索敝赋,以讨于蔡。", "b": "《左传·襄公八年》"}], "words": [{"w": "索手", "t": "空手"}, {"w": "索知", "t": "尽知"}, {"w": "索空", "t": "竭尽"}, {"w": "索莫", "t": "空乏穷尽的样子"}, {"w": "索索", "t": "空虚、空乏的样子。"}]}, {"meaning": "古时民间计量单位,十丈为一索。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1852wx','哥','1','gē','口','10','','[{"pinyin": "gē", "defs": [{"meaning": "(会意。从二可。“可”,有“快乐”、“欢乐”的意思。《诗·小雅·正月》:“哿矣富人。”毛传:“哿,可。”王引之《经义述闻》卷六:“哿与哀对文,哀者忧悲,哿者欢乐也。……《毛传》训哿为可,可亦快意惬心之称。”“哥”似即“歌”之本字。本义:歌)。"}, {"meaning": "咏,唱,奏乐。", "cites": [{"t": "召公卒,而民人思召公之政,怀裳树不敢伐哥咏之,作《甘棠》之诗。", "b": "《史记·燕召公世家》"}, {"t": "诚信著于天下,醇德流乎四海,则近者歌讴而乐之,远者执禽而朝之。", "b": "《盐铁论》"}], "words": [{"w": "哥钟", "t": "即歌钟,古代打击乐器"}, {"w": "哥咏", "t": "歌咏。"}]}, {"meaning": "哥哥。", "cites": [{"t": "哥,声也。从二可。", "b": "《说文》。按,发声之语,如可而平,今以称兄之词。"}, {"t": "再拜跪奠大哥于座前,伏维哥孝友慈惠,和易谦恭。", "b": "唐·白居易《祭浮梁大兄文》"}]}, {"meaning": "唐代常称父为哥。"}, {"meaning": "宋代著名瓷窑“哥窑”的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1853wx','速','1','sù','辶','10','','[{"pinyin": "sù", "defs": [{"meaning": "(形声。从辵(chuò),束声。本义:速度快)。"}, {"meaning": "同本义。", "cites": [{"t": "速,疾也。", "b": "《说文》"}, {"t": "不微至,无以为戚速也。", "b": "《周礼·考工记·总目》"}]}, {"meaning": "字亦作“遬”。", "cites": [{"t": "轻则僄遬。", "b": "《荀子·议兵》"}, {"t": "则莫能以速中。", "b": "《周礼·考工记·弓人》"}, {"t": "王速出令。", "b": "《孟子·梁惠王下》"}, {"t": "子济而陈,迟速唯命。", "b": "《左传·僖公三十三年》"}, {"t": "知幸与不幸,则其读书也必专,而其归书也必速。", "b": "清·袁枚《黄生借书说》"}, {"t": "今不速往,恐为操所先。", "b": "《资治通鉴》"}], "words": [{"w": "收效甚速;速速", "t": "非常快速"}, {"w": "速捷", "t": "快速敏捷"}, {"w": "速战速决", "t": "用最快的速度发动战争,以达到预期的目的;比喻凡事必须进行得快,才能迅速结束"}, {"w": "速食店", "t": "快餐店。"}]}, {"meaning": "加速,加快。", "cites": [{"t": "交语速装束,络绎如浮云。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "速熟", "t": "使农作物生长期短、成熟较快。"}]}, {"meaning": "邀请。", "cites": [{"t": "主人速宾。", "b": "《仪礼·乡饮酒礼》"}, {"t": "何以速我狱。", "b": "《诗·召南·行露》"}, {"t": "有不速之客三人来,敬之终吉。", "b": "《易·需》"}], "words": [{"w": "速客", "t": "请客"}, {"w": "速帖", "t": "请帖。"}]}, {"meaning": "招致。", "cites": [{"t": "君子多欲则贪慕富贵,枉道速祸。", "b": "宋·司马光《训俭示康》"}, {"t": "至丹以荆卿为计,始速祸焉。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "速辜", "t": "招来罪过"}, {"w": "速福", "t": "召福"}, {"w": "速祸", "t": "招来祸害"}, {"w": "速罪", "t": "招致罪祸。"}]}, {"meaning": "催促。", "cites": [{"t": "樊子使来速铭,曰:“不则无以掩诸幽。”乃序而铭之。", "b": "唐·韩愈《贞曜先生墓志铭》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1854wx','逗','1','dòu','辶','10','','[{"pinyin": "dòu", "defs": [{"meaning": "(形声。从辵(chuò),豆声。本义:止住,停留)。"}, {"meaning": "同本义。", "cites": [{"t": "逗,止也。", "b": "《说文》"}, {"t": "廷尉奏恢逗桡。当斩。", "b": "《汉书·韩安国传》"}, {"t": "逗留不进。", "b": "《汉书·匈奴传》"}, {"t": "逗华阴之湍渚。", "b": "《思元赋》"}], "words": [{"w": "逗延", "t": "逗留;停留"}, {"w": "逗宿", "t": "留宿"}]}, {"meaning": "度,时间的延续。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1855wx','栗','1','lì','木','10','','[{"pinyin": "lì", "defs": [{"meaning": "(会意。甲骨文象结了果实的栗树形。本义:木名。果实也称栗,可食)。"}, {"meaning": "一种落叶乔木,果实叫栗子,果仁味甜,可以吃。木材坚实,供建筑和制器具用;树皮可供鞣皮及染色用;叶子可喂柞蚕。", "cites": [{"t": "栗,栗木也。", "b": "《说文》"}, {"t": "树之榛栗。", "b": "《诗·鄘风·定之方中》"}, {"t": "练主用栗。", "b": "《公羊传·文公二年》"}, {"t": "哀公同社于宰我,宰我对曰:“夏后氏以松,殷人以柏,周人以栗。”", "b": "《论语》"}], "words": [{"w": "栗主", "t": "用栗木做成的神牌位"}, {"w": "栗跗", "t": "栗花。"}]}, {"meaning": "任一种栗属的乔木或灌木结的可食的甜味坚果。", "cites": [{"t": "果至于梨栗枣之类。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "栗黄", "t": "即栗子。因其肉色鲜黄而得名"}, {"w": "栗爆", "t": "栗子在火炉中烘煨而爆裂"}, {"w": "栗犊", "t": "小牛。因小牛初生时角如栗而得名。"}]}, {"meaning": "谷实饱满。", "cites": [{"t": "实坚实好,实颖实栗。", "b": "《诗·大雅·民劳》"}, {"t": "凡苗自函活以至颖栗,早者食水三斗,晚者食水五斗,失水即枯。", "b": "《天工开物》"}]}, {"meaning": "坚实。", "cites": [{"t": "缜密以栗,知也。", "b": "《礼记·聘义》"}], "words": [{"w": "栗理", "t": "坚实有文理"}, {"w": "栗然", "t": "坚实密致貌"}, {"w": "栗密", "t": "谨严,缜密"}, {"w": "栗温", "t": "质地密致而润泽。"}]}, {"meaning": "庄敬,严肃。", "cites": [{"t": "命汝典乐,教胄子,直而温,宽而栗。", "b": "《书·舜典》"}], "words": [{"w": "栗斯", "t": "谨慎恭敬的样子。"}]}, {"meaning": "恐惧。", "cites": [{"t": "临其穴,惴惴其栗。", "b": "《诗·秦风·黄鸟》。毛传:“栗,惧也。”"}, {"t": "吾甚栗之。", "b": "《庄子·人间世》"}, {"t": "慄深林兮惊层巅。(使深林战慄,使层巅震惊。)", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "股栗欲堕。", "b": "明·魏禧《大铁椎传》"}, {"t": "恐栗。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "战栗", "t": "发抖"}, {"w": "栗栗", "t": "戒惧的样子;众多的样子"}, {"w": "栗缩", "t": "因恐惧而颤栗畏缩"}, {"w": "栗斯", "t": "看人的脸色。"}]}, {"meaning": "哆嗦,发抖。", "cites": [{"t": "疟之始发也,先起于毫毛,伸欠,乃作寒慄鼓颔。", "b": "《素问》"}, {"t": "战战栗栗,日慎一日。", "b": "《韩非子·初见秦》"}, {"t": "股战而栗。", "b": "《史记·齐悼惠王世家》"}, {"t": "襄王闻之,颜色变作,身体战栗。", "b": "《战国策·楚策》"}, {"t": "登高不栗。", "b": "《庄子》"}], "words": [{"w": "栗栗可惧", "t": "形容很害怕"}, {"w": "不寒而栗", "t": ""}]}, {"meaning": "忧伤。", "cites": [{"t": "将乍往而未半,怵悼栗而怂兢。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "历阶。", "cites": [{"t": "栗阶升,听命,降拜。", "b": "《仪礼·聘礼》"}]}, {"meaning": "分开。", "cites": [{"t": "有敦瓜苦,烝在栗薪。", "b": "《诗·豳风·东山》"}]}, {"meaning": "寒、凉。", "cites": [{"t": "凓,寒也。", "b": "《说文》"}, {"t": "二之二凓。", "b": "《诗·豳风·七月》"}], "words": [{"w": "栗冽", "t": "寒冷的样子"}, {"w": "栗烈", "t": "凛冽。形容严寒。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1856wx','贾','1','gǔ jiǎ jià','贝','10','','[{"pinyin": "gǔ", "defs": [{"meaning": "(形声。本义:做买卖)。"}, {"meaning": "同本义。", "cites": [{"t": "贾,市也。", "b": "《说文》"}, {"t": "父母已去,兄嫂令我行贾。", "b": "《乐府诗集·孤儿行》"}, {"t": "鄙谚曰:“长袖善舞,多财善贾。”", "b": "《韩非子·五蠹》"}], "words": [{"w": "贾资", "t": "做买卖的资金"}, {"w": "贾道", "t": "做买卖之道"}, {"w": "贾贸", "t": "买卖;交易"}, {"w": "贾贷", "t": "买卖。"}]}, {"meaning": "坐卖。泛指卖。", "cites": [{"t": "极赏则民贾其上。", "b": "《周书·命训》"}, {"t": "以商贾阜货而行市。", "b": "《周礼·地官·司市》。注:“商店卖物曰贾。”"}, {"t": "齐高固入晋师,桀石以投人,禽之,而乘其车,击桑本焉,以徇齐垒。曰:“欲勇者,贾余余勇。”", "b": "《左传·成公二年》"}], "words": [{"w": "贾欺", "t": "兜售谎言"}, {"w": "贾用", "t": "卖东西"}, {"w": "贾勇", "t": "出卖勇力。"}]}, {"meaning": "买。", "cites": [{"t": "贾余馀勇。", "b": "《左传·成公二年》"}, {"t": "平子每岁贾马。", "b": "《左传·昭公二十九年》"}], "words": [{"w": "贾马", "t": "买马"}, {"w": "贾田", "t": "买田"}, {"w": "贾官", "t": "买取官职。"}]}, {"meaning": "谋求;求取。", "cites": [{"t": "谋于众不以贾好。", "b": "《国语·晋语》"}], "words": [{"w": "贾誉", "t": "沽名钓誉"}, {"w": "贾诚", "t": "博取忠诚的名声"}, {"w": "贾国", "t": "谋取国柄"}, {"w": "贾利", "t": "求取利益"}, {"w": "贾息", "t": "经商求利。"}]}, {"meaning": "招引,招惹。", "cites": [{"t": "吾焉用此以贾害也。", "b": "《左传·桓公十年》"}, {"t": "不怀宝以贾害,不饰表以招累。", "b": "《晋书·张华传·鹪鹩赋》"}], "words": [{"w": "贾害", "t": "自惹祸害"}, {"w": "贾憎", "t": "招致憎恨"}, {"w": "贾怠", "t": "招致百姓怠惰。"}]}, {"meaning": "商人。古时特指囤积营利的坐商,古时候称行商为“商”,坐商为“贾”。后泛指商人。", "cites": [{"t": "耕者皆欲耕于王之野,商贾皆欲藏于王之市。", "b": "《孟子·梁惠王上》"}, {"t": "贾竖易动以利。", "b": "《史记·留侯世家》"}, {"t": "商贾相与歌于市。", "b": "宋·苏轼《喜雨亭记》"}, {"t": "一日,新贾合两部为大会。", "b": "《马伶传》"}], "words": [{"w": "贾田", "t": "商贾人家所受的田"}, {"w": "贾胡", "t": "指古代西域的商人"}, {"w": "贾竖", "t": "商人奴才"}, {"w": "贾侩", "t": "商人、市侩。"}]}, {"meaning": "古官名 。", "cites": [{"t": "郈鲂假使为贾正焉。", "b": "《左传·昭公二十五年》"}], "words": [{"w": "贾正", "t": "古官名。掌管城市商业,调节物价。"}]}]}, {"pinyin": "jiǎ", "defs": [{"meaning": "(形声。从贝,覀(xià)声。(gǔ)本义:做买卖)。"}, {"meaning": "中国古国名 。姬姓,唐叔虞少子公明封此。后为晋所灭。地在今山西省襄汾县东。"}, {"meaning": "一种鸟的名字。鹰属。"}, {"meaning": "", "cites": [{"t": "贾余庆献谄于后。(贾为南宋的右丞相,充任祈请使与文天祥一同出使元营。他和吕师孟都是通敌卖国的,所以说“构恶”、“献谄”。)", "b": "宋·文天祥《后序》"}], "words": [{"w": "贾董", "t": "汉贾谊和董仲舒的并称。二人以文才著名。"}]}, {"meaning": "姓。"}]}, {"pinyin": "jià", "defs": [{"meaning": "价格,价值。", "cites": [{"t": "我待贾者也。", "b": "《论语·子罕》"}, {"t": "求善贾而沽诸?", "b": ""}, {"t": "从许子之道,则市贾不贰。", "b": "《孟子·滕文公上》"}, {"t": "有者,半贾而卖。", "b": "晁错《论贵粟疏》"}, {"t": "求食者皆多人所共得利之事,以作此鬻卖于市,得价以归,乃得食焉。", "b": "《论衡·刺孟》"}, {"t": "而贾咸贵。", "b": "《汉书·宣帝纪》"}, {"t": "问君贾几何?", "b": "《汉书·杨朴传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1857wx','酌','1','zhuó','酉','10','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从酉(yǒu),从勺,勺亦声。从“酉”与酒有关。本义:斟酒)。"}, {"meaning": "同本义。", "cites": [{"t": "酌,盛酒行觞也。", "b": "《说文》"}, {"t": "尸升,坐取爵酌。", "b": "《仪礼·有司彻》。"}, {"t": "酒曰清酌。", "b": "《礼记·曲礼》"}, {"t": "缩酌用茅。", "b": "《礼记·郊特牲》"}, {"t": "盖酌之也。", "b": "《公羊传·僖公八年》"}, {"t": "及祭,酌仆。", "b": "《周礼·夏官》"}, {"t": "引壶觞以自酌。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "因命酌互举。", "b": "唐·李朝威《柳毅传》"}, {"t": "以我酌油知之。", "b": "宋·欧阳修《归田录》"}, {"t": "以钱覆其口,徐以杓酌油沥之。", "b": "欧阳修《卖油翁》"}, {"t": "无多酌我,我乃酒狂。", "b": "《汉书·盖宽饶传》"}], "words": [{"w": "酌献", "t": "斟酒以献;酌酒献客;酌酒祭神"}, {"w": "酌羽", "t": "酌酒。羽,羽觞之省,代指酒"}, {"w": "酌言", "t": "酌酒。言,助词"}, {"w": "酌醴", "t": "酌酒。"}]}, {"meaning": "饮酒。", "cites": [{"t": "花间一壶酒,独酌无相亲。", "b": "李白《月下独酌》"}, {"t": "引壶觞以自酌,眄庭柯以怡颜。", "b": "陶潜《归去来辞》"}], "words": [{"w": "酌别", "t": "饮酒告别"}, {"w": "酌杯", "t": "饮酒"}, {"w": "酌鲁", "t": "饮薄酒"}, {"w": "酌霞", "t": "比喻饮美酒。"}]}, {"meaning": "斟酌,择善而行。", "cites": [{"t": "酌今昔而减之。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "酌议", "t": "斟酌商议"}, {"w": "酌责", "t": "酌情责罚"}, {"w": "酌从", "t": "酌情顺从"}, {"w": "酌古御今", "t": "择古之善者以为治今的借鉴"}, {"w": "酌古准今", "t": "择取古代之事,用来比照今天的情况"}, {"w": "酌估", "t": "估计"}, {"w": "酌度", "t": "酌量;度量。"}]}, {"meaning": "舀取。", "cites": [{"t": "以杓酌油沥之。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "酌饮", "t": "挹取流质食物而饮"}, {"w": "酌取", "t": "挹取,舀取。"}]}, {"meaning": "酒的代称。", "cites": [{"t": "折寒梅以为羞兮,洒飞泉以为酌。", "b": "邹智《吊刘忠定公文》"}], "words": [{"w": "酌奠", "t": "以酒祭奠"}, {"w": "酌焉不竭", "t": "比喻取之不尽、用之不竭。"}]}, {"meaning": "中国古代的一种酒器。", "cites": [{"t": "主人受酌降。", "b": "《仪礼·有司徹》"}, {"t": "华酌既陈,有琼浆些。", "b": "《楚辞·招魂》"}], "words": [{"w": "酌金馔玉", "t": "形容饮食的豪侈讲究"}, {"w": "酌金馔玉", "t": "喝酒的杯子是金的,盛菜肴的器皿是玉的。极言饮宴的奢侈豪华。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1858wx','配','1','pèi','酉','10','','[{"pinyin": "pèi", "defs": [{"meaning": "(形声。从酉,己声。按:一说不从“己”声,应是“妃”省声。本义:用不同的酒配制而成的颜色)。"}, {"meaning": "同本义。", "cites": [{"t": "配,酒色也。", "b": "《说文》。吴善述广义校订:“配即《内则》注所谓以清与糟相配也。”"}]}, {"meaning": "假借为“妃”。配偶,夫妻的称呼。后多指妻。", "cites": [{"t": "遇其配主。", "b": "《易·丰》"}, {"t": "天立厥配。", "b": "《诗·大雅·皇矣》"}, {"t": "配稷契兮恢唐功。", "b": "《楚辞·王逸·九思守志》"}], "words": [{"w": "元配;继配;配匹", "t": "配偶"}, {"w": "配耦", "t": "配偶"}, {"w": "配头", "t": "方言。配偶"}, {"w": "配丽", "t": "配偶。"}]}, {"meaning": "结婚,婚配。", "cites": [{"t": "安得配君子,共乘双飞鸾。", "b": "李白《感兴》"}], "words": [{"w": "配人", "t": "出嫁,嫁人"}, {"w": "配嫁", "t": "婚配出嫁。"}]}, {"meaning": "衬托,陪衬。", "cites": [{"t": "独有太白配残月。", "b": "韩愈《东方半明》"}], "words": [{"w": "红花配绿叶;配衬", "t": "陪衬,衬托。"}]}, {"meaning": "分给;配给。", "cites": [{"t": "妒令潜配上阳宫,一生遂生空房宿。", "b": "白居易《上阳白发人》"}], "words": [{"w": "调配", "t": "调动分配"}, {"w": "搭配", "t": "按一定目的安排分配"}, {"w": "配率", "t": "分配的比率"}, {"w": "配当", "t": "分配,配合"}, {"w": "配钱", "t": "折合为现钱。"}]}, {"meaning": "充军, 流放。", "cites": [{"t": "配向江南卑湿地。", "b": "白居易《缚戎人》"}], "words": [{"w": " 配格", "t": "依罪情的大小、流刑的轻重定配所远近的规定"}, {"w": "配隶", "t": "流放充军"}, {"w": "配防", "t": "发配罪人守边"}, {"w": "配没", "t": "把罪人的家属发配为奴隶。"}]}, {"meaning": "配享。 如:配神(配享神灵);配祔(配享);配祭(配享);配极(配享于宗庙);配享(古代以有功于王朝的贤人或功臣,附祭在孔庙、帝王庙或其他祠庙中;以功臣附祭于祖庙)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1859wx','翅','1','chì','羽','10','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从羽,支声。本义:鸟类、昆虫的翅膀)。"}, {"meaning": "同本义。", "cites": [{"t": "翅,翼也。", "b": "《说文》"}, {"t": "审视,巨身修尾,青项金翅。", "b": "《聊斋志异·促织》"}], "words": [{"w": "翅关", "t": "翅膀"}, {"w": "翅趫", "t": "像张开两翼的样子"}, {"w": "翅羽", "t": "鸟类两翅上的长羽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1860wx','辱','1','rǔ','辰','10','','[{"pinyin": "rǔ", "defs": [{"meaning": "(会意。甲骨文字形,是“辰”下加脚(止)或加手(又,寸)的形象。①本义:耕作。“辰”是“蜃”的本字,古代以蜃为农具进行耕作。这个意义后来写作“耨”(nòu)。②引申义:耻辱) 同引申义。", "cites": [{"t": "辱,耻也。", "b": "《说文》"}, {"t": "恭近于礼,远耻辱也。", "b": "《论语·学而》"}, {"t": "心旷神怡,宠辱皆忘。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "衣食足而知荣辱。", "b": "《史记·货殖列传序》"}], "words": [{"w": "奇耻大辱;荣辱;羞辱;忍辱负重;蒙受屈膝之辱;辱害", "t": "耻辱和损害"}, {"w": "辱残", "t": "受耻辱和残害。"}]}, {"meaning": "使…受辱;侮辱。", "cites": [{"t": "南辱于楚,寡人耻之。", "b": "《孟子·梁惠王上》"}, {"t": "使于四方,不辱君命。", "b": "《论语·子路》"}, {"t": "我见相如,必辱之。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "足以辱晋;辱邈", "t": "辱没,玷辱"}, {"w": "辱抹", "t": "辱末,辱灭,辱模,辱么,辱莫"}, {"w": "辱没", "t": "玷污,玷辱"}, {"w": "辱玷", "t": "玷辱"}, {"w": "辱污", "t": "玷辱。"}]}, {"meaning": "埋没。", "cites": [{"t": "使吾子辱在泥涂久矣。", "b": "《左传·襄公三十年》"}, {"t": "千里马常有,而伯乐不常有。故虽有名马,只辱于奴隶人之手,骈死于槽枥之间,不以千里称也。", "b": "唐·韩愈《杂说四首》"}]}, {"meaning": "谦词。承蒙。", "cites": [{"t": "辱收寡君,寡君之愿也。", "b": "《左传·僖公四年》"}, {"t": "何至更辱馈遗,则不才益将何以报焉。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "辱游", "t": "对朋友的自称谦词"}, {"w": "辱子", "t": "对别人谦称自己的儿子"}, {"w": "辱临", "t": "对他人来临的敬词。有屈尊枉驾之意"}, {"w": "辱知", "t": "谦辞。受人赏识或提拔"}, {"w": "辱蒙;辱临;辱赐;辱承指教;辱荷", "t": "承蒙。"}]}, {"meaning": "压下去,挫。", "cites": [{"t": "往者弗送,来者弗止,或击其迂,或辱其锐。", "b": "《银雀山汉墓竹简·孙膑兵法》"}]}, {"meaning": "隆重;厚。", "cites": [{"t": "故缘地之利,承从天之指,辱举其死。", "b": "《管子》"}]}, {"meaning": "黑。", "cites": [{"t": "大白若辱。", "b": "《老子》"}]}, {"meaning": "湿润。", "cites": [{"t": "土润辱暑。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1861wx','唇','1','chún','口','10','','[{"pinyin": "chún", "defs": [{"meaning": "(形声。从口,辰声。本义:嘴唇)。"}, {"meaning": "同本义。", "cites": [{"t": "脣,缘也,口之缘也。", "b": "《释名·释形体》"}, {"t": "谚所谓辅车相依,脣亡齿寒者。", "b": "《左传·僖公五年》"}, {"t": "唇焦口燥呼不得。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "唇吻", "t": "言语"}, {"w": "唇红齿白", "t": "形容面貌俊美"}, {"w": "唇不离腮", "t": "比喻亲密无间,形影不离"}, {"w": "唇齿之邦", "t": "非常亲密、利害攸关的邻邦。"}]}, {"meaning": "边缘。", "cites": [{"t": "用胶泥刻字,薄如钱唇。", "b": "沈括《梦溪笔谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1862wx','夏','1','xià','夂','10','','[{"pinyin": "xià", "defs": [{"meaning": "(会意。据小篆字形,从页,从臼,从攵。页(xié),人头。臼(jù),两手,攵(suī),两足。合起来象人形。本义:古代汉民族自称)。"}, {"meaning": "同本义。也称华夏、诸夏。", "cites": [{"t": "夏,中国之人也。", "b": "《说文》。朱骏声曰:“就全地言之,中国在西北一小隅。故陈公子少西字夏,郑公孙夏字西。”"}]}, {"meaning": "泛指中国。", "cites": [{"t": "蛮夷猾夏。", "b": "《书·舜典》。孔传:“夏,华夏。”"}, {"t": "春秋内其国而外诸夏。", "b": "《公羊传·成公十五年》。注:“诸夏外土诸侯也。谓之夏者,大总下上言之辞也。”"}, {"t": "此之谓夏声。", "b": "《左传·襄公二十九年》。服注:“与诸夏同风。”"}, {"t": "东夏之命。", "b": "《吕氏春秋·察今》。注:“东方也。”"}], "words": [{"w": "夏盟", "t": "古代华夏诸国间的结盟"}, {"w": "夏声", "t": "古代中原地区的民间音乐。"}]}, {"meaning": "朝代名。"}, {"meaning": "中国历史上的第一王朝,系传说中禹的儿子启所建立,奴隶制国家,建都安邑(今山西省夏县北),即夏后氏。", "cites": [{"t": "构木钻燧于夏后氏。", "b": "《韩非子·五蠹》"}, {"t": "始于虞夏。", "b": "蔡元培《图画》"}, {"t": "夏后皋。", "b": "《左传·僖公三十三年》"}, {"t": "虞夏以来。", "b": "《史记·货殖列传》"}], "words": [{"w": "夏礼", "t": "夏代的礼法"}, {"w": "夏书", "t": "记载夏代史事的书"}, {"w": "夏甲", "t": "夏朝君主孔甲。"}]}, {"meaning": "封建割据政权或农民起义政权称号 东晋末,公元407年匈奴贵族赫连勃勃建夏国,建都统万城(今陕西横山西北) 隋末窦建德于公元618年建立夏国,都乐寿(今河北献县) 北宋仁宗时,赵元昊于1032年建立夏国,史称西夏,都兴州(今宁夏回族自治区银川东南) 元末明玉珍于公元1362年建立夏国,都重庆。"}, {"meaning": "大屋。", "cites": [{"t": "曾不知夏之为丘兮,孰两东门之可芜?", "b": "《楚辞·哀郢》"}, {"t": "见若覆夏屋者矣。", "b": "《礼记·檀弓上》"}]}, {"meaning": "夏季。一年的第二季,中国习惯指立夏到立秋的三个月时间,也指农历“四、五、六”三个月。", "cites": [{"t": "四月维夏,六月徂暑。", "b": "《诗·小雅·四月》"}], "words": [{"w": "夏汛", "t": "夏季汛期"}, {"w": "夏安居", "t": "僧徒在四月十六日至七月十五日禁止外出,又称“坐夏”"}, {"w": "夏畦", "t": "夏天治理田畦"}, {"w": "夏苗", "t": "夏季的禾苗或田猎。"}]}, {"meaning": "大。", "cites": [{"t": "夏,大也。", "b": "《尔雅》"}, {"t": "于我乎夏屋渠渠。", "b": "《诗·秦风·权舆》。传:“大也。”"}, {"t": "[夏]此字本谊训大也。万物宽假之时也。", "b": "朱骏声《说文通训定声》"}, {"t": "自关而西,秦晋之间,凡物之壮大者而爱伟之,谓之夏。", "b": "《方言》"}], "words": [{"w": "夏李", "t": "大李"}, {"w": "夏屋", "t": "大屋"}, {"w": "夏海", "t": "大海。"}]}, {"meaning": "华彩,即五色。", "cites": [{"t": "秋染夏。", "b": "《周礼》"}], "words": [{"w": "夏翟", "t": "夏狄。羽毛五色的野鸡"}, {"w": "夏缦", "t": "古代卿乘坐的五采车。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1863wx','砸','1','zá','石','10','','[{"pinyin": "zá", "defs": [{"meaning": "重物掉落在物体上,或用重物撞击。", "cites": [{"t": "又把宝玉的一碗茶砸的碗碎茶流。", "b": "《红楼梦》"}]}, {"meaning": "指责,数落。", "cites": [{"t": "他昨日对着大妗子好不拿话儿砸我,说我纵容着你要他图你喜欢哩。", "b": "《金瓶梅词话》"}]}, {"meaning": "合,闭合。", "cites": [{"t": "张老婆儿在一旁观了,也不住的点头砸嘴。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1864wx','砰','1','pēng','石','10','','[{"pinyin": "pēng", "defs": [{"meaning": "(形声。从石,平声。象声词)。"}, {"meaning": "撞击。", "cites": [{"t": "门响了,李维勤进来,重重将门砰上,满面怒容。", "b": "茅盾《清明前后》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1865wx','砾','1','lì','石','10','','[{"pinyin": "lì", "defs": [{"meaning": "(从石,乐声。本义:小石,碎石) 同本义。", "cites": [{"t": "飞沙走砾。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "砾石;砾洲", "t": "沙洲"}, {"w": "砾琇", "t": "碎石与美石。比喻丑或美的人或事物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1866wx','础','1','chǔ','石','10','','[{"pinyin": "chǔ", "defs": [{"meaning": "(形声。从石,楚声。本义:柱脚石,垫在房屋柱子下的石头)。"}, {"meaning": "同本义。", "cites": [{"t": "云蒸柱础润。", "b": "《淮南子·说林》。"}], "words": [{"w": "础石;", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1867wx','破','1','pò','石','10','','[{"pinyin": "pò", "defs": [{"meaning": "(形声。从石,皮声。本义:石头开裂;破碎,碎裂)。"}, {"meaning": "同本义。", "cites": [{"t": "破,石碎也。", "b": "《说文》"}, {"t": "石破天惊逗秋雨。", "b": "李贺《李凭箜篌引》"}, {"t": "沉船、破甑。", "b": "《史记·项羽本纪》"}, {"t": "卵破子死。", "b": "《荀子·劝学》"}, {"t": "秦王恐其破璧。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "爆破", "t": "用炸药炸毁"}, {"w": "破瓦", "t": "古代一种占卜方法。使瓦碎裂,观其纹理以定吉凶祸福"}, {"w": "破卵倾巢", "t": "碎裂鸟卵,倾覆鸟巢"}, {"w": "破剥", "t": "破裂剥落"}, {"w": "破坠", "t": "破裂坠落"}, {"w": "破溃", "t": "破裂崩溃"}, {"w": "破块", "t": "敲碎土块。"}]}, {"meaning": "破坏;损坏。", "cites": [{"t": "破,坏也。", "b": "《广雅》"}, {"t": "淫破义疏。", "b": "《左传·隐公三年》。疏:“谓破败。”"}, {"t": "语小天下莫能破焉。", "b": "《礼记·中庸》"}], "words": [{"w": "破折", "t": "破坏折断"}, {"w": "破禁", "t": "破坏或违反禁令戒条"}, {"w": "破盘", "t": "祭祀后吃祭奠的菜肴"}, {"w": "破质", "t": "破坏质体;改变本质"}, {"w": "破亲", "t": "破坏别人的婚姻"}, {"w": "破击", "t": "破坏和袭击"}, {"w": "破斗", "t": "破坏和战斗"}, {"w": "破没", "t": "破损覆没。"}]}, {"meaning": "破亡;衰败;毁灭。", "cites": [{"t": "国破山河在。", "b": "杜甫《春望》"}], "words": [{"w": "破亡", "t": "破败灭亡"}, {"w": "破凶", "t": "破其国,杀其身"}, {"w": "破走", "t": "击破败走"}, {"w": "破殄", "t": "破灭;消灭"}, {"w": "破家", "t": "毁灭家庭;使国家破灭"}, {"w": "破巢", "t": "破毁了的鸟巢"}, {"w": "破残", "t": "毁坏;破损;破败残缺。"}]}, {"meaning": "击溃;攻破。", "cites": [{"t": "今沛公先破秦入咸阳。", "b": "《史记·项羽本纪》"}], "words": [{"w": "破城", "t": "攻破城邑"}, {"w": "破沮", "t": "因战败而丧失士气"}, {"w": "破阵", "t": "击破敌阵"}, {"w": "破屋", "t": "击穿房屋"}, {"w": "破军", "t": "击破敌军"}, {"w": "破却", "t": "击退"}, {"w": "破逐", "t": "击破并驱逐"}, {"w": "破陷", "t": "攻破;攻克"}, {"w": "破坚摧刚", "t": "谓攻破摧毁强敌"}, {"w": "破胜", "t": "击破战胜"}, {"w": "破敌", "t": "击败敌军"}, {"w": "破关", "t": "攻克险阻难关。"}]}, {"meaning": "破除;解除。", "cites": [{"t": "贤于己者,问焉以破其疑。", "b": "清·刘开《问说》"}], "words": [{"w": "破邪", "t": "破除邪恶"}, {"w": "破妄", "t": "破除妄念"}, {"w": "破执", "t": "佛教语。谓破除有实我、有实法的执见"}, {"w": "破恶", "t": "破除邪恶"}, {"w": "破惑", "t": "解惑;破除疑惑"}, {"w": "破弃", "t": "破除;抛弃"}, {"w": "破结", "t": "破除结念"}, {"w": "破滞", "t": "破除凝塞;解除烦闷。"}]}, {"meaning": "透;穿;揭穿。", "cites": [{"t": "这位姑娘可不是一句话了事的人,此刻要一语道破,必弄到满盘皆空。", "b": "《儿女英雄传》"}], "words": [{"w": "破云", "t": "穿透云层"}, {"w": "破空", "t": "划破长空"}, {"w": "破奸发伏", "t": "揭露隐藏的坏人。"}]}, {"meaning": "射中。", "cites": [{"t": "则固已破其奸谋而折其骄气。", "b": "宋·苏轼《教战守策》"}], "words": [{"w": "破帖", "t": "射穿箭靶。"}]}, {"meaning": "敲;打。", "cites": [{"t": "刽子手左右服侍,军校在前,招旗在后,一起破锣,一起破鼓,出了钱塘门。", "b": "《岳飞传》"}]}, {"meaning": "助词。了。", "cites": [{"t": "怎生出的这恶气?我则题破这庙宇,便是我生之愿。", "b": "元·马致远《荐福碑》"}]}, {"meaning": "尽;遍。", "cites": [{"t": "读书破万卷,下笔如有神。", "b": "唐·杜甫诗"}]}, {"meaning": "碎裂;不完整。", "cites": [{"t": "吾庐独破受冻死亦足。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "破不剌", "t": "破烂不堪"}, {"w": "破丢不答", "t": "破破烂烂"}, {"w": "破句", "t": "不完整的句子"}, {"w": "破陆续", "t": "破破烂烂"}, {"w": "破烂流丢", "t": "破烂不堪的样子"}, {"w": "破设设", "t": "破杀杀。破破烂烂"}, {"w": "破家破伙", "t": "破烂家当"}, {"w": "破零二落", "t": "破烂零散。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1868wx','原','1','yuán','厂','10','','[{"pinyin": "yuán", "defs": [{"meaning": "(会意。小篆字形。象泉水从山崖里涌出来。从厂(hǎn),象山崖石穴形。从泉。本义:水源,源泉)。"}, {"meaning": "“源”的古字。水源,水流起头的地方。", "cites": [{"t": "原,水泉本也。", "b": "《说文》。俗字作“源”。"}, {"t": "原泉混混。", "b": "《孟子》"}, {"t": "原流、泉浡。", "b": "《淮南子·原道》"}, {"t": "犹塞川原为潢洿也。", "b": "《汉书·食货志》"}, {"t": "有本有原。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "原泉", "t": "源泉"}, {"w": "原流", "t": "源流。"}]}, {"meaning": "起源;根本;根由。", "cites": [{"t": "必达于礼乐之原。", "b": "《礼记·孔子闲居》。注:“犹本也。”"}, {"t": "原小则鲜。", "b": "《史记·货殖列传》。"}]}, {"meaning": "又。", "cites": [{"t": "衣食之原。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "原大则饶。", "b": ""}], "words": [{"w": "原故", "t": "原因"}, {"w": "原凶", "t": "凶杀案的主犯"}, {"w": "原曲", "t": "原委和底细。"}]}, {"meaning": "原野。", "cites": [{"t": "广平曰原。", "b": "《尔雅》"}, {"t": "拘诸原。", "b": "《左传·僖公三十三年》"}, {"t": "川原无际。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "南望原隰。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "原燎", "t": "原野上大火延烧"}, {"w": "原色", "t": "原野的景色"}, {"w": "原陵", "t": "平原与丘陵。"}]}, {"meaning": "原来。", "cites": [{"t": "原不过此数。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "原道", "t": "原来说;原来"}, {"w": "原起", "t": "原来;起初"}, {"w": "原自", "t": "本来;原来"}, {"w": "原身", "t": "原来的身形"}, {"w": "原心", "t": "本心,本意"}, {"w": "原价", "t": "原来的价格"}, {"w": "原额", "t": "原来规定的数额。"}]}, {"meaning": "本来。", "cites": [{"t": "若果为原版所有。", "b": "《书林清话》"}], "words": [{"w": "原底子", "t": "本来;从前"}, {"w": "原说", "t": "本来说"}, {"w": "原形毕露", "t": "本来面貌。"}]}, {"meaning": "推究。", "cites": [{"t": "原心定罪。", "b": "《汉书·薛宣传》。注:“谓寻其本也。”"}, {"t": "原其理,当是为谷大水冲激……唯巨石岿然挺立耳。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "原庄宗。", "b": "宋·欧阳修《伶官传》"}], "words": [{"w": "原情", "t": "推究本情"}, {"w": "原察", "t": "推究考察"}, {"w": "原君;原毁", "t": ""}]}, {"meaning": "宽恕。", "cites": [{"t": "因任己明而原省次之。", "b": "《庄子·天道》"}], "words": [{"w": "原宥", "t": "原谅宽恕"}, {"w": "原刑", "t": "恕罪"}, {"w": "原省", "t": "宽恕并免除其罪"}, {"w": "原降", "t": "原宥而减罪"}, {"w": "原赦", "t": "宽恕赦免。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1869wx','套','1','tào','大','10','','[{"pinyin": "tào", "defs": [{"meaning": "(会意。从大,从长。套在外面的东西比被套者要大、长。本义:罩在外面的东西)。"}, {"meaning": "地势弯曲的地方。常作地名用字。", "cites": [{"t": "明宗战胡卢套、杨村,为梁兵所败。", "b": "《新五代史》"}]}, {"meaning": "圈套。", "cites": [{"t": "话说唐三藏固住元阳,出离了烟花苦套。", "b": "《西游记》"}], "words": [{"w": "套子", "t": ""}]}, {"meaning": "罩在外面。", "cites": [{"t": "下边穿着条香色洋布夹裤,套着双青缎子套裤。", "b": "《儿女英雄传》"}], "words": [{"w": "套袖", "t": "套在衣袖外保护衣服。"}]}, {"meaning": "用计哄骗或诈诱。", "cites": [{"t": "宝钗便在炕上坐了,慢慢的闲言中套问他年纪家乡等语,留心窥察。", "b": "《红楼梦》"}], "words": [{"w": "套弄", "t": "设计骗取"}, {"w": "套供", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1870wx','逐','1','zhú','辶','10','','[{"pinyin": "zhú", "defs": [{"meaning": "(会意。甲骨文字形,象人(脚)在豕等动物后面追逐的样子。“止”小篆改从辵(chuò)。本义:追赶)。"}, {"meaning": "同本义 (含有使追赶对象离开或消灭的意思)。", "cites": [{"t": "逐,追也。", "b": "《说文》"}, {"t": "丧马勿逐。", "b": "《易·暌》"}, {"t": "良马逐。", "b": "《易·大畜》"}, {"t": "乘白龟兮逐文鱼。", "b": "《楚辞·河伯》"}, {"t": "遂逐齐师。", "b": "《左传·左公十年》"}, {"t": "孺卿逐捕。", "b": "《汉书·李广苏建传》"}, {"t": "简子怒,驱车逐之。", "b": "马中锡"}, {"t": "中山狼传》", "b": ""}, {"t": "噪而相逐。", "b": "明·张溥《五人墓碑记》"}, {"t": "急逐弗失。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "逐逐", "t": "追逐;急于得利"}, {"w": "逐驾", "t": "追随尊驾;跟随君主左右"}, {"w": "逐胜", "t": "乘胜追击敌人"}, {"w": "逐射", "t": "骑马追射以赌输赢"}, {"w": "逐利", "t": "追逐利润"}, {"w": "逐兔", "t": "追逐兔子。比喻争夺帝位。"}]}, {"meaning": "驱逐。", "cites": [{"t": "文公逐卫侯而立叔武。", "b": "《公羊传》"}, {"t": "去年为尔逐黄雀,雨多屋漏泥土落。", "b": "唐·冯著《燕衔泥》"}, {"t": "非秦者去,为客者逐。", "b": "李斯《谏逐客书》"}], "words": [{"w": "逐夫", "t": "被拼斥、放逐的人"}, {"w": "逐客", "t": "驱逐由外国来本国游说或做官的人;指被朝廷贬谪外放的人;赶走来访的客人。"}]}, {"meaning": "放逐;流放。", "cites": [{"t": "信非吾罪而弃逐合,何日夜而忘之?", "b": "《楚辞·九章·哀郢》"}, {"t": "后先生盖千祀兮,余逐而浮湘。", "b": "柳宗元《吊屈原赋》"}], "words": [{"w": "逐迁", "t": "放逐贬谪。"}]}, {"meaning": "竞争。", "cites": [{"t": "遂于计谋。", "b": "《韩非子·五蠹》"}], "words": [{"w": "逐兔", "t": "比喻争天下"}, {"w": "逐势", "t": "竞逐权势"}, {"w": "逐走", "t": "赛跑"}, {"w": "逐争", "t": "争夺。"}]}, {"meaning": "追求。", "cites": [{"t": "任君逐利轻汇海,莫把风涛似妾轻。", "b": "唐·刘得仁《贾妇怨》"}, {"t": "逐利之情。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "逐奇", "t": "追求新奇"}, {"w": "逐文", "t": "追求辞藻文采"}, {"w": "逐名趋势", "t": "追求名声和权势"}, {"w": "逐利", "t": "求取好处。"}]}, {"meaning": "流荡。", "cites": [{"t": "故《风》之所以为不逐者,取是以节之也。", "b": "《荀子》"}]}, {"meaning": "随,跟随。", "cites": [{"t": "逐流牵荇叶,沿岸摘芦苗。", "b": "唐·储光羲《江南曲》"}, {"t": "凉逐之生。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "逐便", "t": "乘便,顺便"}, {"w": "逐时", "t": "随时"}, {"w": "逐队", "t": "随众而行"}, {"w": "逐群", "t": "随群。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1871wx','烈','1','liè','灬','10','','[{"pinyin": "liè", "defs": [{"meaning": "(形声。从火,列声。“火”字在下面一般写作四点。本义:火势猛)。"}, {"meaning": "同本义。", "cites": [{"t": "烈,火猛也。", "b": "《说文》"}, {"t": "如火烈烈。", "b": "《诗·商颂·长发》"}, {"t": "夫火烈,民望而畏之。", "b": "《左传·昭公二十年》"}, {"t": "火烈风猛。", "b": "《资治通鉴》"}], "words": [{"w": "烈烧", "t": "炽烈的野火"}, {"w": "烈燧", "t": "炽烈的烽火"}, {"w": "烈烈", "t": "猛火炎炽貌"}, {"w": "烈光", "t": "炽热的阳光。"}]}, {"meaning": "猛烈;激烈。", "cites": [{"t": "其使民也酷烈。", "b": "《荀子·议兵》"}, {"t": "一之曰觱发,二之曰栗烈。", "b": "《诗·豳风·七月》"}, {"t": "迅雷风烈必变。", "b": "《论语·乡党》"}, {"t": "冬日烈烈。", "b": "《诗·小雅·四月》"}, {"t": "穷冬烈风,大雪深数尺。", "b": "宋濂《送东阳马生序》"}, {"t": "烈风雷雨弗迷。", "b": "《书·舜典》"}, {"t": "铲刈秽草,伐去恶木,烈火而焚之。", "b": "柳宗元《永州八记》"}], "words": [{"w": "烈毒", "t": "剧毒"}, {"w": "烈栗", "t": "剧烈的震动"}, {"w": "烈盛", "t": "猛烈"}, {"w": "烈寒", "t": "严寒"}, {"w": "烈烈轰轰", "t": "轰轰烈烈。形容气魄宏伟,声势浩大。"}]}, {"meaning": "刚直;坚贞。", "cites": [{"t": "贞魂烈魄怜巾帼。", "b": "李慈铭《感事》"}], "words": [{"w": "烈汉", "t": "性格刚烈的男子汉"}, {"w": "烈直", "t": "刚烈耿直"}, {"w": "烈性子", "t": "性格刚烈。"}]}, {"meaning": "光明;显赫。", "cites": [{"t": "君有烈名。", "b": "《国语》"}, {"t": "休有烈光。", "b": "《诗·周颂·载见》"}], "words": [{"w": "烈文", "t": "光明文采"}, {"w": "烈光", "t": "光辉、荣耀"}, {"w": "烈烈", "t": "鲜明灿烂的样子。"}]}, {"meaning": "严厉;严重。", "cites": [{"t": "文人画士之祸之烈到此矣。", "b": "龚自珍《病梅馆记》"}], "words": [{"w": "烈君", "t": "严厉的君主。"}]}, {"meaning": "美好;优美。", "cites": [{"t": "声烈遐布。", "b": "嵇康《琴赋》"}]}, {"meaning": "功业。", "cites": [{"t": "成王不能共事天地,修文、武之烈。", "b": "《汉书·王莽传上》"}, {"t": "兼仗父兄之烈。", "b": "《资治通鉴》"}], "words": [{"w": "烈所", "t": "功业之所在"}, {"w": "烈祖", "t": "建立功业的先祖"}, {"w": "烈烈", "t": "功业德行显赫貌。"}]}, {"meaning": "恶疾。", "cites": [{"t": "肆戎疾不殄,烈假不瑕。", "b": "《诗·大雅·思齐》"}]}, {"meaning": "行列。", "cites": [{"t": "叔在薮,火烈具举。", "b": "《诗·郑风·大叔于田》"}]}, {"meaning": "烧。", "cites": [{"t": "益烈山泽而焚之。", "b": "《孟子·滕文公上》"}, {"t": "你去那受刑法尸骸上烈些纸钱。", "b": "关汉卿《窦娥冤》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1872wx','殊','1','shū','歹','10','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从攴(è),朱声。小篆字形。攴,分解后剩下的骨头。隶变为“歹”。本义:斩首,断其首身而死)。"}, {"meaning": "同本义。", "cites": [{"t": "殊,死也。", "b": "《说文》。汉令曰:蛮夷长有罪当殊之。"}, {"t": "其赦天下殊死以下。", "b": "《汉书·高帝纪》。注:“斩刑也。”"}, {"t": "今世殊死者相枕也。", "b": "《庄子·在宥》"}]}, {"meaning": "引申为死。", "cites": [{"t": "太子即自刭,不殊。", "b": "《史记·淮南王刘安列传》"}], "words": [{"w": "不殊", "t": "不死。"}]}, {"meaning": "断绝。", "cites": [{"t": "殊,断也。", "b": "《广雅》"}, {"t": "断其后之木而弗殊。", "b": "《左传·昭公二十三年》"}]}, {"meaning": "分开;离开。", "cites": [{"t": "官而衣食之,殊身而后止,此之谓养疾。", "b": "《管子》"}]}, {"meaning": "分;区别。", "cites": [{"t": "法家不别亲疏,不殊贵贱,一断于法。", "b": "《史记·太史公自序》"}]}, {"meaning": "超过。", "cites": [{"t": "母氏年殊七十。", "b": "《后汉书·梁统传》"}]}, {"meaning": "异;不同。", "cites": [{"t": "而万殊为一。", "b": "《淮南子·本经》。注:“异也。”"}, {"t": "始皇既没,余威震于殊俗。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "殊等", "t": "指人或事物的不同等级"}, {"w": "殊方", "t": "异域;他乡"}, {"w": "殊文", "t": "不同形体的文字"}, {"w": "殊文别语", "t": "不同的文字与语言"}, {"w": "殊类", "t": "不同的类别"}, {"w": "殊礼", "t": "不同的礼制"}, {"w": "殊称", "t": "不同的名称;特殊的名称"}, {"w": "殊心", "t": "异心。不同的志趣、认识和思想感情"}, {"w": "殊目", "t": "不同的名称"}, {"w": "殊俗", "t": "不同的风俗习惯。"}]}, {"meaning": "特异;出众;突出。", "cites": [{"t": "坐中数千人,皆言夫婿殊。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "殊观", "t": "奇观;异观"}, {"w": "殊庭", "t": "异域。指神仙居住的地方"}, {"w": "殊胜", "t": "特异;绝佳"}, {"w": "殊乡", "t": "异乡。多指仙乡"}, {"w": "殊形", "t": "奇异的形状"}, {"w": "殊奇", "t": "奇特"}, {"w": "殊相", "t": "奇异的状貌"}, {"w": "殊翁", "t": "文采奇特的雁颈毛。"}]}, {"meaning": "特别,独特。", "cites": [{"t": "然侍卫之臣不懈于内,忠志之士忘身于外者,盖追先帝之殊遇,欲报之于陛下也。", "b": "诸葛亮《出师表》"}], "words": [{"w": "殊觉", "t": "特别觉得"}, {"w": "殊礼", "t": "特殊的礼遇"}, {"w": "殊渴", "t": "特别渴望"}, {"w": "殊遇", "t": "特殊的待遇;破格重用"}, {"w": "殊奖", "t": "特别的奖励"}, {"w": "殊选", "t": "破格选用"}, {"w": "殊赏", "t": "特别的赏赐"}, {"w": "殊态", "t": "特殊的姿态"}, {"w": "殊量", "t": "特殊的才能。即大器"}, {"w": "殊容(特殊的容貌)殊恩(特别的恩惠)", "t": ""}]}, {"meaning": "很;甚。", "cites": [{"t": "老臣今者殊不欲食,乃自强步,日三四里。", "b": "《战国策·赵策》"}, {"t": "廉君宣恶言,而君畏匿之,恐惧殊甚。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "古法采草药多用二月、八月,此殊未当。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "殊难相信;殊久", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1873wx','殉','1','xùn','歹','10','','[{"pinyin": "xùn", "defs": [{"meaning": "(形声。从歹(本作歺),旬声。歺(è),剔过肉剩下的骨头,常与“死亡”有关。本义:殉葬;以人从葬)。"}, {"meaning": "同本义。", "cites": [{"t": "殉,用人送死也。", "b": "《玉篇》"}, {"t": "王缢于芋尹申亥氏。申亥以其二女殉而葬之。", "b": "《左传》"}, {"t": "死者用生者之器也,不殆于用殉乎哉。", "b": "《礼记·檀弓下》"}, {"t": "与城为殉。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "殉死;殉葬", "t": ""}]}, {"meaning": "献身或丧生。", "cites": [{"t": "今世俗之君子,多危身弃生以殉物。", "b": "《庄子·让王》"}], "words": [{"w": "殉义", "t": "为道义而死"}, {"w": "殉财", "t": "为财而死"}, {"w": "殉物", "t": "为追求物质利益而死"}, {"w": "殉身", "t": "为达到某种目的而献身。"}]}, {"meaning": "贪,追求。", "cites": [{"t": "游子殉高位于生前,志士思重名于身后。", "b": "晋·陆机《豪士赋序》"}], "words": [{"w": "殉私", "t": "谋求私利"}, {"w": "殉业", "t": "专心致志于学业或功业。"}]}, {"meaning": "随;跟从。", "cites": [{"t": "将复之,恐不能胜,故驱其所爱子弟以殉之。", "b": "《孟子》。赵岐注:“殉,从也。”"}], "words": [{"w": "殉没", "t": "舍身以追随死者"}, {"w": "殉义", "t": "遵从道义。"}]}, {"meaning": "从葬的人。", "cites": [{"t": "天子杀殉,众者数百,寡者数十。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1874wx','顾','1','gù','页','10','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从页(xié),头。表示与头有关。雇声。本义:回头看)。"}, {"meaning": "同本义。", "cites": [{"t": "顾,环视也。", "b": "《说文》"}, {"t": "顾见汉骑司马吕马童。", "b": "《史记·项羽本纪》"}, {"t": "顾瞻周道。", "b": "《诗·桧风·匪风》"}, {"t": "眷言顾之,潸焉出涕。", "b": "《诗·小雅·大东》"}, {"t": "车中,不内顾,不疾言,不亲指。", "b": "《论语·乡党》"}, {"t": "庄子持竿不顾。", "b": "《庄子·秋水》"}, {"t": "友人惭,不下引之。元方入门,不顾。", "b": "《世说新语·方正》"}, {"t": "荆轲顾笑武阳,前为谢曰:“北蛮夷之鄙人,未尝见天子,故振慑。”", "b": "《战国策·燕策》"}], "words": [{"w": "顾瞻", "t": "回首环视;眷顾;关照"}, {"w": "顾盼生辉", "t": "一回首,一注目,都有无限光彩。比喻眉目传神"}, {"w": "顾返", "t": "回头,回家"}, {"w": "顾笑", "t": "回头而笑"}, {"w": "顾望", "t": "回视,观望。有谦让、畏忌或踌躇不前的意思。"}]}, {"meaning": "观看,瞧。", "cites": [{"t": "顾我则笑。", "b": "《诗·邶风·终风》"}, {"t": "惠顾前好。", "b": "《左传·宣公十二年》"}, {"t": "徘徊四顾,见虫伏壁上。", "b": "《聊斋志异·促织》"}, {"t": "未及见贼而士卒离散,君臣相顾,不知所归。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "四顾无人;相顾一笑;顾观", "t": "观看"}, {"w": "顾眺", "t": "眺望,远望"}, {"w": "顾影惭形", "t": "看着身影,心感内疚。"}]}, {"meaning": "访问,拜访。", "cites": [{"t": "此人可就见,不可屈致也。将军宜枉驾顾之。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "光顾;枉顾;三顾茅庐;顾聘", "t": "拜访聘请"}, {"w": "顾访", "t": "探视访问"}, {"w": "顾临", "t": "过访。"}]}, {"meaning": "照顾,关怀。", "cites": [{"t": "子布、元表诸人各顾妻子,挟持私虑,深失所望。", "b": "宋·司马光《资治通鉴》"}, {"t": "三岁贯汝,莫我肯顾。", "b": "《诗·魏风·硕鼠》"}, {"t": "夫人臣出万死不顾一生之计。", "b": "汉·司马迁《报任安书》"}, {"t": "不顾思义。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "顾睦", "t": "照顾"}, {"w": "顾揽", "t": "照管"}, {"w": "顾管", "t": "照顾,照管"}, {"w": "顾报", "t": "顾念报答。"}]}, {"meaning": "眷念,顾及。", "cites": [{"t": "屈平既嫉之,虽流放,眷顾楚国,系心怀王。", "b": "《史记·屈原贾生列传》"}, {"t": "愿君顾先王之宗庙,姑反国统万人乎?", "b": "《战国策·齐策》"}], "words": [{"w": "顾惯", "t": "顾念"}, {"w": "顾哀", "t": "眷念哀怜"}, {"w": "顾思", "t": "眷顾思念"}, {"w": "顾重", "t": "顾念重视。"}]}, {"meaning": "顾虑;考虚。", "cites": [{"t": "大行不顾细谨,大礼不辞小让。", "b": "《史记·项羽本纪》"}, {"t": "世溷浊而莫余知兮,吾方高驰而不顾。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "顾畏", "t": "顾虑畏惧"}, {"w": "顾惮", "t": "顾忌"}, {"w": "顾累", "t": "忧虑麻烦"}, {"w": "顾忧", "t": "操心。"}]}, {"meaning": "出钱请人做事。", "cites": [{"t": "天下女徒已论,归家,顾山钱月三百。", "b": "《汉书·平帝纪》"}, {"t": "如此使用民财以顾其功。", "b": "《汉书·晁错传》"}], "words": [{"w": "顾倩", "t": "雇用"}, {"w": "顾募", "t": "雇佣征募"}, {"w": "顾唤", "t": "雇请。"}]}, {"meaning": "表示轻微的转折,相当于“而”、“不过”。", "cites": [{"t": "顾自以为身残处秽。", "b": "汉·司马迁《报任安书》"}, {"t": "如姬之欲为公子死,无所辞,顾未有路耳。", "b": "《史记·魏公子列传》"}, {"t": "吾每念,常痛于骨髓,顾计不知所出耳!", "b": "《战国策·燕策》"}]}, {"meaning": "反而,却。", "cites": [{"t": "今三川、周室,天下之市朝也,而王不争焉,顾争于戎狄。", "b": "《战国策·秦策一》"}, {"t": "人之立志,顾不如蜀鄙之僧哉?", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "顾荷", "t": "反而受到。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1875wx','轿','1','jiào','车','10','','[{"pinyin": "jiào", "defs": [{"meaning": "(形声。从车,乔声。本义:轿子)。"}, {"meaning": "竹舆。古代过山用的交通工具。", "cites": [{"t": "舆轿而逾领。", "b": "《汉书·严助传》"}], "words": [{"w": "山轿", "t": "过山用的竹制舆车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1876wx','较','1','jiào','车','10','','[{"pinyin": "jiào", "defs": [{"meaning": "(形声。从车,交声。本义:车箱两旁板上的横木。士大夫以上的乘车,较上饰有曲铜钩)。"}, {"meaning": "同本义。", "cites": [{"t": "以其隧之半为之较崇。", "b": "《考工记·舆人》"}, {"t": "猗重较兮。", "b": "《诗·淇澳》。释文:“车两旁上出轼者。”"}], "words": [{"w": "重较", "t": "两重横木。"}]}, {"meaning": "车箱。", "cites": [{"t": "金薄缪龙,为舆倚较。", "b": "《后汉书》"}]}, {"meaning": "概略;大旨。", "cites": [{"t": "此其大较也。", "b": "《史记·货殖列传》"}, {"t": "斯其大较也。", "b": "嵇康《乐无哀乐论》"}]}, {"meaning": "较量。", "cites": [{"t": "长短相较。", "b": "《老子》。释文:“较,较量深浅也。”"}, {"t": "鲁人猎较。", "b": "《孟子·万章下》。注:“猎较者,田猎较夺禽兽。”"}, {"t": "大车不较。", "b": "《史记·田完世家》。索隐:“较者,校量也。”"}, {"t": "不敢与较。", "b": "《聊斋志异·促织》"}, {"t": "较秦之所得与战胜而得者。", "b": "宋·苏洵《六国论》"}, {"t": "较死为苦。", "b": "清·林觉民《与妻书》"}, {"t": "较前此之仳离。", "b": "《广东军务记》"}, {"t": "为之者较少。", "b": "蔡元培《图画》"}], "words": [{"w": "较射", "t": "比较射技"}, {"w": "较赛", "t": "比赛胜负"}, {"w": "较艺", "t": "较量技艺"}, {"w": "较估", "t": "比较估计"}, {"w": "较量", "t": "比较衡量。"}]}, {"meaning": "用同“校”。"}, {"meaning": "竞逐。", "cites": [{"t": "鲁人猎较,孔子亦猎较。", "b": "《孟子·万章下》。赵岐注云:“猎较者,田猎相较夺禽兽,得之以祭,时俗所尚,以为吉祥"}], "words": [{"w": "较力", "t": "角力;比武"}, {"w": "较猎", "t": "比赛谁打猎收获多"}, {"w": "较竞", "t": "竞逐"}, {"w": "较对", "t": "竞争对抗"}, {"w": "较逐", "t": "角逐,竞争追求。"}]}, {"meaning": "明显。", "cites": [{"t": "较,明也。", "b": "《广雅》"}, {"t": "此其尤大彰明较著者也。", "b": "《史记·伯夷传》"}, {"t": "白气较然。", "b": "《汉书·谷永传》"}], "words": [{"w": "较炳", "t": "较著。较明。显著明白"}, {"w": "较然", "t": "明显的样子"}, {"w": "较言", "t": "明白说明"}, {"w": "较明", "t": "明显;明白"}, {"w": "较近", "t": "明显切近。"}]}, {"meaning": "正直。", "cites": [{"t": "鹄之言较,较者直也。射所以直己志。", "b": "《仪礼·大射仪》"}, {"t": "较兮。", "b": "《书·大传》。注:“谓直道者也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1877wx','顿','1','dú dùn','页','10','','[{"pinyin": "dú", "defs": [{"meaning": "——“冒顿”(Mòdú):汉匈奴族的单于(chán yú)。"}]}, {"pinyin": "dùn", "defs": [{"meaning": "(形声。从页(xié),屯声。从“页”,表示与头有关。本义:叩头,磕头)。"}, {"meaning": "同本义。", "cites": [{"t": "顿,下首也。", "b": "《说文》"}, {"t": "二曰顿首。", "b": "《周礼·大祝》。注:“拜头叩地也。”"}], "words": [{"w": "顿颡", "t": "屈膝下拜,以额叩地,多在请罪投降时用"}, {"w": "顿筑", "t": "以头或物撞地"}, {"w": "顿头", "t": "磕头"}, {"w": "顿膝", "t": "下跪。"}]}, {"meaning": "用脚底或用脚使劲往下踩。", "cites": [{"t": "顿足失色。", "b": "《聊斋志异·促织》"}, {"t": "牵衣顿足拦道哭。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "顿脚;顿足", "t": "以足跺地。形容着急、悲痛的样子。"}]}, {"meaning": "倒下,跌倒。", "cites": [{"t": "故兵不顿而利可全。", "b": "《孙子·谋攻》"}], "words": [{"w": "顿仆", "t": "僵仆"}, {"w": "顿落", "t": "低落"}, {"w": "顿碌", "t": "折腾"}, {"w": "顿毙", "t": "倒毙"}, {"w": "顿擗", "t": "崩倒;倒塌。"}]}, {"meaning": "舍弃;废弃。", "cites": [{"t": "文六龙顿辔。", "b": "《文选安陆昭王碑》"}], "words": [{"w": "顿脱", "t": "甩掉"}, {"w": "顿罔", "t": "撤除围猎之网。"}]}, {"meaning": "劳累疲弊。", "cites": [{"t": "故兵不顿而利可全。", "b": "《孙子·谋攻》"}, {"t": "兵甲顿,士民病。", "b": "《韩非子·初见秦》"}, {"t": "号呼而转徙,饥渴而顿踣。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "顿卒", "t": "困苦。也作顿悴"}, {"w": "顿悴", "t": "困厄憔悴。"}]}, {"meaning": "古国名。在今河南省商水县北,于公元前496被楚灭。"}, {"meaning": "立刻。", "cites": [{"t": "家人习奢已久,不能顿俭,必致失所。", "b": "宋·司马光《训俭示康》"}, {"t": "亡国之恨顿生。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "顿喝一口家乡水;顿改前非;顿尔", "t": "忽然"}, {"w": "顿豁", "t": "突然开朗"}, {"w": "顿绝", "t": "一下子断绝"}, {"w": "顿饱", "t": "一下子吃饱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1878wx','毙','1','bì','比','10','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从死,敝声。在先秦古书中的獘,在流传中往往被改成斃。本义:仆倒;倒下去)。"}, {"meaning": "同本义。", "cites": [{"t": "郑人击简子中肩,毙于车中。", "b": "《左传·哀公二年》"}, {"t": "多行不义必自斃。", "b": "《左传·隐公元年》"}, {"t": "射其右,斃于车中。", "b": "《左传·成公二年》"}], "words": [{"w": "毙死", "t": "仆倒而死"}, {"w": "毙踣", "t": "倒毙。"}]}, {"meaning": "垮台,失败。", "cites": [{"t": "多行不义,必自毙。", "b": "《左传》"}]}, {"meaning": "引申为死。", "cites": [{"t": "与犬,犬斃;与小臣,小臣亦斃。", "b": "《左传·僖公四年》"}, {"t": "及扑入手,已股落腹裂,斯须就毙。", "b": "《聊斋志异·促织》"}], "words": [{"w": "毙命;毙伤", "t": ""}]}, {"meaning": "杀死。", "cites": [{"t": "贼连毙者三。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "以刀劈狼首,又数刀毙之。", "b": "《聊斋志异·狼三则》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1879wx','致','1','zhì','至','10','','[{"pinyin": "zhì", "defs": [{"meaning": "同本义。", "cites": [{"t": "致,送诣也。", "b": "《说文》"}, {"t": "君子以致命遂志。", "b": "《易·象下传》"}, {"t": "远莫致之。", "b": "《诗·卫风·竹竿》"}, {"t": "卿致馆。", "b": "《诗·卫风·聘礼》"}, {"t": "殷人既葬而致事。", "b": "《仪礼·曾子问》"}, {"t": "远方莫不致其珍。", "b": "《荀子·解蔽》"}, {"t": "令曰:“得李广必生致之。”", "b": "《史记·李将军列传》"}, {"t": "致敬亭于幕府。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "致电上海。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "致聘", "t": "送交定亲礼品。"}]}, {"meaning": "招引;招致。", "cites": [{"t": "致天下之士。", "b": "汉·贾谊《过秦论》"}, {"t": "致食客三千人。(致,招致,招徕。)", "b": "《史记·魏公子列传》"}, {"t": "不可屈致。", "b": "《三国志·诸葛亮传》"}, {"t": "今宜厚待刘禅,以致孙休。", "b": "《三国演义》"}, {"t": "致孤危托落。(致,招致,造成。)", "b": "清·袁枚《祭妹文》"}, {"t": "致此疾困。", "b": "《明史》"}], "words": [{"w": "导致", "t": "引起"}, {"w": "致病;致残;致人", "t": "招致人才"}, {"w": "致士", "t": "招引贤士"}, {"w": "致聘", "t": "征聘。"}]}, {"meaning": "造成;导致。", "cites": [{"t": "何意致不厚。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "致负诚托。", "b": "唐·李朝威《柳毅传》"}, {"t": "致孤危托落。", "b": "清·袁枚《祭妹文》"}, {"t": "致郁郁死。", "b": "清·周容《芋老人传》"}], "words": [{"w": "致得", "t": "致使。"}]}, {"meaning": "求取;获得。", "cites": [{"t": "家贫,无从致书以观。(致,弄到、取得,这里指买到。动词。)", "b": "明·宋濂《送东阳马生序》"}, {"t": "余幼好书,家贫难致。", "b": "清·袁枚《黄生借书说》"}, {"t": "无以致疑。", "b": "清·刘开《问说》"}, {"t": "致一己之能。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "数数百金。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "致知格物", "t": "获得知识在于研究事物"}, {"w": "致效", "t": "效力"}, {"w": "致养", "t": "得到养育。"}]}, {"meaning": "表达。", "cites": [{"t": "妇前致问。", "b": "唐·杜甫《石壕吏》"}, {"t": "致殷勤之意。", "b": "《资治通鉴》"}], "words": [{"w": "致诚", "t": "表达诚挚的情意"}, {"w": "致精", "t": "显示精巧。"}]}, {"meaning": "奉献;献纳。", "cites": [{"t": "事父母能竭其力,事君能致其身。", "b": "《论语》"}], "words": [{"w": "致君泽民", "t": "为皇帝效力,为百姓造福"}, {"w": "致身", "t": "原指献身。后用作出仕之典"}, {"w": "致福", "t": "古代臣子祭祀后,将祭肉奉献给国君,表示为君王和国家添福。"}]}, {"meaning": "转告;回报。", "cites": [{"t": "荆轲遂见太子,言田光己死,致光之言。", "b": "《史记》"}], "words": [{"w": "致事", "t": "上报施政情况。"}]}, {"meaning": "施加;施行。", "cites": [{"t": "君子以折狱致刑。", "b": "《易·丰》"}, {"t": "我乃明致天罚。", "b": "《书·多士》"}], "words": [{"w": "致化", "t": "施行教化"}, {"w": "致罚", "t": "施加惩罚"}, {"w": "致礼", "t": "向人施礼。"}]}, {"meaning": "归还;交还。", "cites": [{"t": "惟臣寻事,自致房陵、上庸,而复乞身自放于外。", "b": "《三国演义》"}], "words": [{"w": "致政", "t": "致仕"}, {"w": "致仕", "t": "辞去官职"}, {"w": "致位", "t": "辞去职位。"}]}, {"meaning": "到达。", "cites": [{"t": "然则厕足而垫之致黄泉。", "b": "《庄子·外物》"}, {"t": "卒先致缘陵。", "b": "《管子·大匡》"}]}, {"meaning": "又。", "cites": [{"t": "邢君出致于齐。", "b": ""}]}, {"meaning": "极,尽。", "cites": [{"t": "致赏则匮。", "b": "《管子·君臣下》"}, {"t": "致忠信。", "b": "《荀子·君道》"}, {"t": "致思于天文。", "b": "《后汉书·张衡传》"}], "words": [{"w": "致曲", "t": "尽力研究细微的事理。"}]}, {"meaning": "情趣;兴致。", "cites": [{"t": "[蒋]干还,称瑜雅量高致。", "b": "《三国志》"}, {"t": "无穷逸致。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "有致", "t": "富有情趣"}, {"w": "别致;景致;致度", "t": "神采风度。"}]}, {"meaning": "书卷,契据。", "cites": [{"t": "献田宅者操书致。", "b": "《礼记·曲礼》"}]}, {"meaning": "结构上细密。", "cites": [{"t": "作为淫巧,以荡上心,必功致为上。", "b": "《礼记·月令》"}], "words": [{"w": "精致", "t": "精巧细致"}, {"w": "密致", "t": "结构紧密;致密。"}]}, {"meaning": "周密。", "cites": [{"t": "德产之致也精微。", "b": "《礼记·礼器》"}, {"t": "桉其狱,皆文致不可得反。", "b": "《汉书·严延年传》"}], "words": [{"w": "细致", "t": "精细周密。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1880wx','柴','1','chái zhài','木','10','','[{"pinyin": "chái", "defs": [{"meaning": "(形声。从木,此声。本义:捆束的细木小柴)。"}, {"meaning": "同本义。", "cites": [{"t": "大者可析谓之薪,小者合束谓之柴。", "b": "《礼记·月令》注"}, {"t": "乃取蒙冲斗舰十艘,载燥荻枯柴。", "b": "《资治通鉴》"}]}, {"meaning": "泛指木柴,小木散材,也指作燃料的木柴。", "cites": [{"t": "柴,小木散材也。", "b": "《说文》"}, {"t": "树枳棘与薪柴。", "b": "《楚辞·愍命》。注:“枯枝为柴。”"}, {"t": "是时东郡烧草,以故薪柴少。", "b": "《汉书·沟洫志》"}], "words": [{"w": "柴荆", "t": "乡里用木板、荆条编制而成的门"}, {"w": "柴禾", "t": "木柴;柴草"}, {"w": "木柴;劈柴;柴水", "t": "打柴汲水"}, {"w": "柴市", "t": "木柴交易处"}, {"w": "柴山", "t": "生长矮小灌木杂草的山。"}]}, {"meaning": "烧柴祭天。后又写作“祡”。", "cites": [{"t": "岁二月,东巡守,至于岱宗,柴。", "b": "《书·舜典》"}, {"t": "柴望秩于山川。", "b": "《书·舜典》"}, {"t": "柴于上帝。", "b": "《礼记·大传》"}, {"t": "柴而望祀山川。", "b": "《礼记·王制》"}]}, {"meaning": "注:“柴,祭天告至也。”。"}, {"meaning": "姓。"}]}, {"pinyin": "zhài", "defs": [{"meaning": "编木维护四周。", "cites": [{"t": "[周武王]乃封比干之墓,表商容之闾,柴箕子之门。", "b": "《淮南子》"}], "words": [{"w": "柴护", "t": "编木围其四面,使不受破坏。"}]}, {"meaning": "覆盖。", "cites": [{"t": "掘新井而柴焉。", "b": "《管子》"}]}, {"meaning": "阻塞;闭塞。", "cites": [{"t": "佞人相汲引而柴正路,俊哲处下位而不见知。", "b": "《抱朴子》"}], "words": [{"w": "柴门", "t": "杜门,闭门"}, {"w": "柴路", "t": "堵塞道路"}, {"w": "柴塞", "t": "堵塞。"}]}, {"meaning": "防守的栅栏篱障。", "cites": [{"t": "羽(关羽)闻之,住不渡,而结柴营。", "b": "《三国志·吴志》"}], "words": [{"w": "柴栅", "t": "栅栏"}, {"w": "柴楂", "t": "木栏,栅栏"}, {"w": "柴篱", "t": "木栅栏,藩篱。"}]}, {"meaning": "也指村墅。", "cites": [{"t": "其游止,有孟城坳、华子冈、文杏馆、斤竹岭、鹿柴…。", "b": "唐·王维《辋川集序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1881wx','桌','1','zhuō','木','10','','[{"pinyin": "zhuō", "defs": [{"meaning": "(形声。从木,卓省声。桌字本作“卓”。卓有高而直立之义。后来人们又根据“棹”是木制的特点另制“桌”字。俗又作“棹”。本义:桌子)。"}, {"meaning": "同本义。", "cites": [{"t": "一桌,一椅。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "古称几案。", "cites": [{"t": "上与讲官俗共一桌,真不啻天颜咫尺矣。", "b": "明·文隶《列皇小识》"}], "words": [{"w": "桌巾", "t": "桌布"}, {"w": "桌屏", "t": "摆在桌上当作装饰的小屏风"}, {"w": "桌帏", "t": "亦称“桌帷”同“桌围”。围在桌子边的装饰物,多以布或绸缎做成"}, {"w": "桌裙", "t": "即桌帏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1882wx','虑','1','lǜ','虍','10','','[{"pinyin": "lǜ", "defs": [{"meaning": "(形声。从思,虍(hū)声。本义:思虑,谋划)。"}, {"meaning": "同本义。", "cites": [{"t": "虑,谋思也。", "b": "《说文》"}, {"t": "非士无与虑国。", "b": "《墨子·亲士》"}, {"t": "弗虑弗图。", "b": "《诗·小雅·雨无止》"}, {"t": "礼之中焉,能思索谓之能虑。", "b": "《荀子·礼论》"}, {"t": "臣闻智者千虑,必有一失;愚者千虑,必有一得。", "b": "《史记·淮阴侯列传》"}, {"t": "深谋远虑。", "b": "汉·贾谊《过秦论》"}, {"t": "足下更虑之。", "b": "《战国策·燕策》"}], "words": [{"w": "考虑", "t": "思索问题,以便做出决定"}, {"w": "虑尽", "t": "谋划穷尽"}, {"w": "虑佚", "t": "思虑放荡失当"}, {"w": "虑事多暗", "t": "考虑事情不明"}, {"w": "虑思", "t": "思虑,考虑"}, {"w": "虑计", "t": "思虑筹划。"}]}, {"meaning": "用绳结缀。", "cites": [{"t": "今子有五石之瓠,何不虑以为大樽,而浮于江湖。", "b": "《庄子·逍遥游》"}]}, {"meaning": "忧虑。", "cites": [{"t": "虑人逼取。", "b": "清·袁枚《黄生借书说》"}, {"t": "将军勿虑。", "b": "《资治通鉴》"}, {"t": "虑患之具。", "b": "苏轼《教战守》"}, {"t": "虑戚吾心。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "不足为虑;虑恐", "t": "忧虑"}, {"w": "虑难", "t": "忧虑灾难"}, {"w": "虑患", "t": "忧虑祸患"}, {"w": "虑忆", "t": "忧虑,挂念。"}]}, {"meaning": "审察,讯察。", "cites": [{"t": "大理寺掌折狱详刑,凡罪系者五日一虑。", "b": "《唐书·百官志》"}], "words": [{"w": "虑免", "t": "讯察赦免"}, {"w": "虑问", "t": "对囚犯进行审问"}, {"w": "虑囚", "t": "讯察记录囚犯的罪状。"}]}, {"meaning": "思想;意念。", "cites": [{"t": "此皆良实,志虑忠纯。", "b": "诸葛亮《出师表》"}, {"t": "衡于虑。", "b": "《孟子·告子下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1883wx','监','1','jiān jiàn','皿','10','','[{"pinyin": "jiān", "defs": [{"meaning": "(会意。甲骨文字形,左边是一个人睁大眼睛在往下看(臣,竖目),右边是个器皿。金文又在器皿上加一小横,表示器中有水。古人以水为镜,“监”就是一个人弯着腰,睁大眼睛,从器皿的水中照看自己的面影。本义:监督,察看督促)。"}, {"meaning": "同本义。", "cites": [{"t": "監,临下也。", "b": "《说文》"}, {"t": "立其监。", "b": "《周礼·太宰》。注:“谓公侯伯子男各监一国。”"}, {"t": "何用不监。", "b": "《诗·小雅·节南山》"}, {"t": "监,察也。", "b": "《方言十二》"}, {"t": "使监谤者。", "b": "《国语·周语》。注:“察也。”"}, {"t": "以监其上下之所好。”", "b": ""}, {"t": "乃以吴叔为假王,监诸将以西击荥阳。", "b": "《史记·陈涉世家》"}, {"t": "王怒,得卫巫,使监谤者。", "b": "《国语·周语上》"}, {"t": "夷门监者。", "b": "《史记·魏公子列传》"}, {"t": "刚毅监斩。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "监临", "t": "自上而下地监督视察"}, {"w": "监修", "t": "监督编修"}, {"w": "监觑", "t": "查看"}, {"w": "监解", "t": "明察,分辨。"}]}, {"meaning": "统领,率领。", "cites": [{"t": "迪将其后,监我士师工。", "b": "《书·洛诰》"}], "words": [{"w": "监御", "t": "统领"}, {"w": "监统", "t": "监督统理。"}]}, {"meaning": "牢狱。", "cites": [{"t": "监五室。", "b": "清·方苞《狱中杂记》"}, {"t": "监外板屋。", "b": ""}], "words": [{"w": "监铺", "t": "临时拘留所"}, {"w": "监仓", "t": "监狱"}, {"w": "监规", "t": "监狱的规章制度"}, {"w": "监比", "t": "坐监追征。"}]}, {"meaning": "监督、指导或劝告的人。", "cites": [{"t": "命四监大合百县之秩刍。", "b": "《礼记·月令》。注:“山林川泽之官。”"}], "words": [{"w": "学监", "t": "清末在中等以上学堂设立的学官。"}]}, {"meaning": "指诸候。", "cites": [{"t": "乃施典于邦国,而建其牧,立其监。", "b": "《周礼·太宰》"}]}]}, {"pinyin": "jiàn", "defs": [{"meaning": ""}, {"meaning": "借鉴。", "cites": [{"t": "我不可不监于有夏,亦不可不监于有殷。", "b": "《书·召诰》"}, {"t": "监观四方,求民之莫。", "b": "《诗·大雅·皇矣》"}, {"t": "成汤监于夏桀,故主其心而慎治之。", "b": "《荀子·解蔽》"}]}, {"meaning": "照。", "cites": [{"t": "人无于水监,当于民监。", "b": "《书·酒诰》"}, {"t": "明神降之,监其德也。", "b": "《左传·庄公三十二年》"}, {"t": "昔有仍氏,生女发黑而甚美,光可监人。", "b": "《列女传·晋羊叔姬》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1884wx','紧','1','jǐn','糸','10','','[{"pinyin": "jǐn", "defs": [{"meaning": "(会意。从臤(qiān),坚。从糸(mì),细丝。本义:缠丝急)。"}, {"meaning": "同本义。", "cites": [{"t": "紧,缠丝急也。", "b": "《说文》"}, {"t": "弛紧急之弦张兮。", "b": "傅毅《舞赋》"}]}, {"meaning": "急促;迫切。", "cites": [{"t": "紧,急也。", "b": "《广雅》"}, {"t": "心紧絭兮伤怀。", "b": "《楚辞·疾世》"}], "words": [{"w": "紧事", "t": "急事"}, {"w": "紧绸", "t": "紧凑;急促"}, {"w": "紧溜", "t": "急流;要紧时刻;紧要关头"}, {"w": "紧水", "t": "湍急的水流"}, {"w": "紧切慢八", "t": "慢慢地;一天一天地。"}]}, {"meaning": "猛烈;激急。", "cites": [{"t": "我有一句,这一句就是“一夜北风紧”。", "b": "《红楼梦》"}], "words": [{"w": "紧张", "t": ""}]}, {"meaning": "紧实,牢固。", "cites": [{"t": "戈戟之紧。", "b": "《管子·问》。注:“紧,谓其坚彊者。”"}], "words": [{"w": "紧固", "t": "牢固。"}]}, {"meaning": "距离近;密接无间。", "cites": [{"t": "其化紧敛。", "b": "《素问·气交变大论》"}], "words": [{"w": "紧身", "t": "贴身衣服"}, {"w": "紧屯屯", "t": "方言。形容非常紧密"}, {"w": "紧洞洞", "t": "方言。形容紧密"}, {"w": "紧峭", "t": "紧凑"}, {"w": "紧健", "t": "紧凑有力。"}]}, {"meaning": "使紧或更紧;收束。", "cites": [{"t": "其化紧敛。", "b": "《素问·气交变大论》"}], "words": [{"w": "紧身;紧缩;紧弦,紧索;紧绳", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1885wx','党','1','dǎng','儿','10','','[{"pinyin": "dǎng", "defs": [{"meaning": "(形声。从黑,尚声。“党”、“黨”在古代是两个字,现在“党”是“黨”的简化字。简化字“党”,从儿(人,尚声)本义:晦暗不明。“党”指集团时,在古代一般只用于贬义,与现代汉语不同)。"}, {"meaning": "不鲜明。", "cites": [{"t": "黨,不鲜也。", "b": "《说文》"}, {"t": "嘉兴谓衣物敝垢不鲜曰烟党。", "b": "蒋礼鸿《义府续貂》"}]}, {"meaning": "美,善,正直", "cites": [{"t": "党,善也;美也。", "b": "《广雅》"}, {"t": "元而致实,博而党正,是士君子之辩者也。", "b": "《荀子》"}]}, {"meaning": "知晓,解悟。", "cites": [{"t": "法先王,顺礼义,党学者。", "b": "《荀子》"}]}, {"meaning": "偏私,偏袒。", "cites": [{"t": "子党于师人。", "b": "《韩非子·外储》"}, {"t": "群而不党。", "b": "《论语》。孔注:“助也。”"}]}, {"meaning": "又。", "cites": [{"t": "吾闻君子不党。孔注:“相助匿曰党。”", "b": ""}]}, {"meaning": "结伙。", "cites": [{"t": "性贪而狠,党豺为虐。", "b": "明·马中锡《中山狼传》"}]}, {"meaning": "古代地方户籍编制单位。五百家为党。", "cites": [{"t": "五族为党。", "b": "《周礼·大司徒》。注:“百家,党正,各掌其党之政令教治。”"}, {"t": "君实乡州藏焉。", "b": "《管子·山权数》。注:“三千五百家为党,此非周制。”"}, {"t": "操当以肃还付乡党。", "b": "《资治通鉴》"}], "words": [{"w": "党人", "t": "同一乡里的人"}, {"w": "党正", "t": "周代所设地方组织的长官。"}]}, {"meaning": "朋辈。指意气相投的人。", "cites": [{"t": "辨说得其党。", "b": "《礼记·仲尼燕居》。注:“类也。”"}, {"t": "睦于父母之党。", "b": "《礼记·坊记》。注:“犹亲也。”"}, {"t": "嗟哉吾党二三子,安得至老不更归。", "b": "韩愈《山石》"}], "words": [{"w": "党友", "t": "指志道相近、立场相似的人"}, {"w": "党援", "t": "指与自己同道而给予援助的人。"}]}, {"meaning": "朋党;由私人利害关系结成的小集团。", "cites": [{"t": "无偏无党。", "b": "《书·洪范》。注:“朋党。”"}, {"t": "各于其党。", "b": "《论语·里仁》"}, {"t": "惟党人之偷乐兮。", "b": "《楚辞·离骚》"}, {"t": "使其党入索财物。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "死党;余党", "t": "未消灭尽的党羽"}, {"w": "党恶", "t": "结党作恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1886wx','逞','1','chěng','辶','10','','[{"pinyin": "chěng", "defs": [{"meaning": "(形声。从辵(chuò),呈声。本义:通,通达)。"}, {"meaning": "同本义。", "cites": [{"t": "逞,通也。", "b": "《说文》。傅云龙古语考补正:“通,达也,是其本义。通有行义,无疾义。”"}]}, {"meaning": "快意,实现,使称心。", "cites": [{"t": "今民馁而君逞欲。", "b": "《左传·桓公六年》"}, {"t": "使归就戮于秦,以逞寡君之志。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "逞志", "t": "逐心如意,以求快意"}, {"w": "逞欲", "t": "逐心如意,以求得到欲望的满足"}, {"w": "逞心", "t": "快意;称心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1887wx','晒','1','shài','日','10','','[{"pinyin": "shài", "defs": [{"meaning": "(曬俗作晒。形声。左形,右声。本义:在阳光下曝干或取暖)。"}, {"meaning": "暴晒;晒干。", "cites": [{"t": "曬,暴也。", "b": "《说文》"}, {"t": "暴五谷之类。晋秦之间谓之曬。", "b": "《方言七》"}, {"t": "答曰:“我晒书。”", "b": "刘义庆《世说新语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1888wx','眠','1','mián','目','10','','[{"pinyin": "mián", "defs": [{"meaning": "(形声。从目,民声。本义:闭上眼睛)。"}, {"meaning": "同本义。", "cites": [{"t": "眠,寐也。", "b": "《玉篇》"}, {"t": "吾子有疾,虽不能省视,而竟夕不眠。", "b": "《后汉书·第五伦传》"}, {"t": "致命于帝,然后得眠些。", "b": "《楚辞·招魂》"}, {"t": "余峨之山有兽焉,见人则眠。", "b": "《山海经·东山经》"}, {"t": "久之,目似瞑,意暇甚。", "b": "《聊斋志异·狼》"}]}, {"meaning": "睡觉。", "cites": [{"t": "不眠忧战伐。", "b": "杜甫《宿江边阁》"}, {"t": "春眠不觉晓,处处闻啼鸟。", "b": "孟浩然《春晓》"}], "words": [{"w": "不眠之夜;失眠", "t": "夜间睡不着"}, {"w": "安眠", "t": "安稳地熟睡"}, {"w": "眠食", "t": "睡眠和饮食。"}]}, {"meaning": "横卧;平放。", "cites": [{"t": "眠琴绿阴,上有飞瀑。", "b": "司空图《诗品》"}], "words": [{"w": "眠桅", "t": "横倒桅杆"}, {"w": "眠倒", "t": "横倒;放下。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1889wx','晓','1','xiǎo','日','10','','[{"pinyin": "xiǎo", "defs": [{"meaning": "(象形。从日,尧声。本义:天明)。"}, {"meaning": "同本义。今专指天刚亮。", "cites": [{"t": "晓,明也。", "b": "《说文》"}, {"t": "冥冥之中,独见晓焉。", "b": "《淮南子·俶真》"}, {"t": "晓驾炭车辗冰辙。", "b": "唐·白居易《卖炭翁》"}, {"t": "晓看红湿处。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "晓当尽戮之。", "b": "《资治通鉴·唐纪》"}, {"t": "梳晓鬟也。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "晓风残月。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "破晓", "t": "刚亮"}, {"w": "拂晓", "t": "天快亮"}, {"w": "晓雾;晓舌", "t": "鸟拂晓叫"}, {"w": "晓暝", "t": "天将亮的时候"}, {"w": "晓行;晓鸡初啼;晓星;晓岚;鸡鸣报晓;晓夕", "t": "日夜"}, {"w": "晓天,晓色", "t": "拂晓时的天色"}, {"w": "晓月,晓魄", "t": "拂晓残月。"}]}, {"meaning": "清晨。", "cites": [{"t": "晓光浮野,朝烟承日回。", "b": "梁·简文帝《侍游新亭应令诗》"}], "words": [{"w": "晓日", "t": "朝阳"}, {"w": "晓夕;晓光", "t": "清晨的日光"}, {"w": "晓妆", "t": "晨妆"}, {"w": "晓昏", "t": "朝夕"}, {"w": "晓霜", "t": "早上的霜露。"}]}, {"meaning": "明白,了解。", "cites": [{"t": "晓,慧也;快也;智也。", "b": "《广雅》"}, {"t": "晓然以至道。", "b": "《荀子·臣道》。注:“明喻之貌。”"}, {"t": "明主不深晓,以为仆沮贰师,而为李陵游说。", "b": "《汉书·司马迁传》"}, {"t": "上晓音律。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "使使晓武。", "b": "《汉书·李广苏建传》"}, {"t": "展玩不可晓。", "b": "《聊斋志异·促织》"}], "words": [{"w": "晓白", "t": "通畅明白"}, {"w": "晓旨", "t": "明白用意"}, {"w": "晓析", "t": "了解"}, {"w": "晓知,晓明", "t": "通达,明白。"}]}, {"meaning": "告知,使明白。", "cites": [{"t": "是仆终已不得舒愤懑以晓左右。", "b": "《汉书·司马迁传》"}], "words": [{"w": "晓喻", "t": "通告;告诉"}, {"w": "晓世", "t": "使世人知道"}, {"w": "晓告", "t": "告知"}, {"w": "晓字", "t": "告示。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1890wx','哮','1','xiào','口','10','','[{"pinyin": "xiào", "defs": [{"meaning": "(形声。从口,孝声。本义:野兽的吼声)。"}, {"meaning": "同本义。", "cites": [{"t": "哮,豕惊声也。", "b": "《说文》"}, {"t": "虎声谓之哮唬。", "b": "《通俗文》"}, {"t": "哮阚之兽。", "b": "曹植《七启》。注:“虎怒也。”"}, {"t": "熊罴哮我东,虎豹号我西。", "b": "唐·杜甫《石龛》"}, {"t": "水声澎湃,兽群哮而游。", "b": "《游泸山记》"}], "words": [{"w": "哮吼", "t": "野兽吼叫"}, {"w": "咆哮", "t": "吼叫"}, {"w": "哮唬", "t": "虎啸声"}, {"w": "哮阚", "t": "猛兽咆哮。多用以比喻震怒。"}]}, {"meaning": "呼喊。", "cites": [{"t": "哮,呼也。", "b": "《集韵》"}], "words": [{"w": "哮吼", "t": "泛指大声喊叫;又指声威震慑"}, {"w": "哮咷", "t": "嚎啕。大声哭叫"}, {"w": "哮悍", "t": "形容勇猛强悍。"}]}, {"meaning": "哮症的简称。", "cites": [{"t": "治哮治积方。", "b": "《丹溪先生心法》"}], "words": [{"w": "哮吼", "t": "病症名。"}]}, {"meaning": "猪的惊叫声。", "cites": [{"t": "哮,豕惊声也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1891wx','唠','1','láo lào','口','10','','[{"pinyin": "láo", "defs": [{"meaning": "说起来没完。"}]}, {"pinyin": "lào", "defs": [{"meaning": "", "words": [{"w": "唠扯;唠咯", "t": "闲谈,聊天"}, {"w": "唠嗑", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1892wx','鸭','1','yā','鸟','10','','[{"pinyin": "yā", "defs": [{"meaning": "水禽名。俗称鸭子。", "cites": [{"t": "春江水暖鸭先知。", "b": "宋·苏轼《惠崇"}, {"t": "春江晚景", "b": ""}]}, {"meaning": "》。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1893wx','晃','1','huǎng huàng','日','10','','[{"pinyin": "huǎng", "defs": [{"meaning": "(会意。从日,光亦声。本义:明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "晃,明也。", "b": "《说文》"}, {"t": "晃,暉也。", "b": "《广雅·释言》"}, {"t": "天晃朗以弥高兮。", "b": "潘岳《秋兴赋》"}, {"t": "或晃朗而拓落。", "b": "左思《魏都赋》"}], "words": [{"w": "晃烂", "t": "明亮有光彩"}, {"w": "晃然", "t": "明亮的样子"}, {"w": "晃朗", "t": "晃晃,明亮的样子"}, {"w": "晃昱", "t": "明亮;辉煌。"}]}, {"meaning": "引申为美俊。", "cites": [{"t": "却怎睃趁着你头上放毫光,打扮的特来晃。", "b": "元·王实甫《西厢记》"}]}]}, {"pinyin": "huàng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1894wx','哺','1','bǔ','口','10','','[{"pinyin": "bǔ", "defs": [{"meaning": "(形声。从口,甫声。本义:口中含嚼的食物) 同本义。", "cites": [{"t": "辍饭吐哺。", "b": "《汉书·高帝纪》"}, {"t": "稚子咽哺。", "b": "《汉书·匈奴传赞》"}, {"t": "周公吐哺,天下归心。", "b": "曹操《短歌行》"}], "words": [{"w": "一饭三吐哺", "t": ""}]}, {"meaning": "吃食。", "cites": [{"t": "众人皆醉,何不餔其糟而啜其醨?", "b": "《楚辞·渔父》"}, {"t": "子之从于子敖来,徒餔啜也。", "b": "《孟子·离娄上》"}], "words": [{"w": "哺啜", "t": "饮食;吃喝。"}]}, {"meaning": "喂养。泛指禽兽喂养幼仔。", "cites": [{"t": "乳孙哺子,教得生狞。", "b": "李贺《猛虎行》"}, {"t": "有一老父过请饮,吕后因餔之。", "b": "《史记·高祖本纪》"}], "words": [{"w": "哺食", "t": "哺养。喂养"}, {"w": "哺鞠", "t": "犹哺育;养育"}, {"w": "哺坊", "t": "孵雏鸡的作坊"}, {"w": "哺鸡", "t": "母鸡孵卵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1895wx','晌','1','shǎng','日','10','','[{"pinyin": "shǎng", "defs": [{"meaning": "白天。", "cites": [{"t": "春兰!没晌没夜的,你干什么哩?", "b": "粱斌《红旗谱》"}]}, {"meaning": "片刻,一会儿。泛指比较短的一段时间。", "cites": [{"t": "半晌恰方言。", "b": "王实甫《西厢记》"}], "words": [{"w": "半晌", "t": "过了好一会儿"}, {"w": "一晌", "t": "指片刻,过了一些时间。"}]}, {"meaning": "量词", "cites": [{"t": "今北方有田者,亦不计亩,但以人工穷日之力为数,曰有田若干晌云。", "b": "清·高士奇《天禄识余》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1896wx','剔','1','tī','刂','10','','[{"pinyin": "tī", "defs": [{"meaning": "(形声。从刀,易声。本义:分解骨肉,把肉刮下)。"}, {"meaning": "同本义。", "cites": [{"t": "剔,解骨也。", "b": "《说文》。按,即为鬄之或体。"}, {"t": "去骨曰剔。", "b": "《通俗文》"}], "words": [{"w": "剔股;剔肉;剔骨头", "t": ""}]}, {"meaning": "挑;拔。", "cites": [{"t": "斜拔玉钗灯影畔,剔开红焰救飞蛾。", "b": "唐·张祜《赠内人》"}], "words": [{"w": "用小刀剔他的牙齿;剔牙杖;剔目", "t": "剜出眼珠"}, {"w": "剔灯", "t": "挑灯。"}]}, {"meaning": "用喙或舌舔整理 。", "words": [{"w": "剔翎", "t": ""}]}, {"meaning": "剪削。", "cites": [{"t": "剔削根节,断其脉络。", "b": "唐·杜牧《杭州新造南亭子记》"}]}, {"meaning": "疏导 。", "words": [{"w": "剔拨", "t": "指点,指教。"}]}, {"meaning": "清除 。", "words": [{"w": "剔除", "t": ""}]}, {"meaning": "挑捡;搜寻 。", "words": [{"w": "剔抉", "t": "挑选。"}]}, {"meaning": "弦乐弹奏指法之一,中指向外为剔 。", "words": [{"w": "轻挑慢剔", "t": ""}]}, {"meaning": "理发。", "cites": [{"t": "其次剔毛发,婴金铁受辱。", "b": "汉·司马迁《报任少卿书》"}, {"t": "妇人皆剪剔以著假髻。", "b": "《北史·齐幼主纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1897wx','晕','1','yūn yùn','日','10','','[{"pinyin": "yūn", "defs": [{"meaning": "昏倒。", "cites": [{"t": "魏老儿上了一夹棍,贾魏氏上了一拶子,两个人都晕绝过去。", "b": "《老残游记》"}], "words": [{"w": "晕绝", "t": "昏厥"}, {"w": "头晕", "t": "头脑昏乱"}, {"w": "晕昏", "t": "昏迷"}, {"w": "晕迷", "t": "昏眩。"}]}]}, {"pinyin": "yùn", "defs": [{"meaning": "(形声。从日,军声。本义:日月周围形成光圈)。"}, {"meaning": "同本义。"}, {"meaning": "日月周围的光圈。", "cites": [{"t": "晕,日月气也。", "b": "《说文新附》"}, {"t": "晕,卷也。气在外卷结之也,日月俱然。", "b": "《释名》"}, {"t": "晕适背穴。", "b": "《汉书·天文志》"}, {"t": "日月晕适,云风,此天之客气,其发见亦有大运。", "b": "《史记》"}], "words": [{"w": "月晕", "t": "月亮有光环"}, {"w": "晕珥", "t": "晕和珥。泛指日、月旁的光晕"}, {"w": "晕蚀", "t": "日月之晕与食。"}]}, {"meaning": "环形花纹或波纹。", "cites": [{"t": "木有瘿,石有晕,犀有通,以取妍于人,皆物之病也。", "b": "宋·苏轼《答李端叔书》"}], "words": [{"w": "晕光", "t": "彩虹的光彩。"}]}, {"meaning": "光环 。围绕于乳头周围的有色环(乳晕),或围绕于水疱或脓疱周围的有色的环。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1898wx','蚌','1','bàng bèng','虫','10','','[{"pinyin": "bàng", "defs": [{"meaning": "(形声。从虫,丰声。本义:一种软体动物。有的能产珍珠)。"}, {"meaning": "同本义。", "cites": [{"t": "离为蚌。", "b": "《易·说卦》"}, {"t": "蚌方出曝,而鹬啄其肉,蚌合而其喙。", "b": "《战国策·燕策》"}, {"t": "巨 蜯函蛛。", "b": "《文选·左思·南都赋》"}, {"t": "民食果菰 蜯蛤腥臊恶臭。", "b": "《韩非子·五蠹》"}], "words": [{"w": "蚌蛤", "t": "蚌与蛤。长者曰蚌,圆者曰蛤"}, {"w": "蚌壳", "t": "蚌的外壳。"}]}, {"meaning": "美珠。", "cites": [{"t": "蚌,美珠。", "b": "《类篇·虫部》"}]}]}, {"pinyin": "bèng", "defs": [{"meaning": "蚌埠的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1899wx','畔','1','pàn','田','10','','[{"pinyin": "pàn", "defs": [{"meaning": "(形声。从田,半声。本义:田界)。"}, {"meaning": "同本义。", "cites": [{"t": "畔,田界也。", "b": "《说文》。段玉裁注:“田界者,田之竟处也。”按,一户百亩,百亩有界。"}, {"t": "如农之有畔。", "b": "《左传》"}, {"t": "修其疆畔。", "b": "《国语·周语》"}]}, {"meaning": "界限;疆界。", "cites": [{"t": "吟泽畔之江滨。", "b": "《楚辞·逢纷》"}, {"t": "江河之畔无隐夫。", "b": "《楚辞·愍命》"}], "words": [{"w": "畔岸", "t": "边际;范围限制"}, {"w": "畔涯", "t": "边际"}, {"w": "畔衅", "t": "边界争端"}, {"w": "畔际", "t": "界限;边际"}, {"w": "畔界", "t": "疆界。"}]}, {"meaning": "边,旁边。", "cites": [{"t": "牧羊于道畔。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "枕畔;桥畔", "t": ""}]}, {"meaning": "泮宫,古代学校。", "cites": [{"t": "饮酒畔宫。", "b": "汉《史晨词孔庙奏铭》"}, {"t": "兴文偃武,脩序畔校。", "b": "汉《成皋令任伯嗣碑》"}]}, {"meaning": "背叛;叛变。", "cites": [{"t": "畔主背亲。", "b": "《汉书·李广苏建传》"}, {"t": "寡助之至,亲戚畔之。", "b": "《孟子·公孙丑下》"}], "words": [{"w": "畔亡", "t": "叛亡"}, {"w": "畔心", "t": "谋叛的念头"}, {"w": "畔臣", "t": "背叛君国的臣子"}, {"w": "畔弑", "t": "叛国弑君"}, {"w": "畔乱", "t": "武装叛变"}, {"w": "畔虑", "t": "背叛的谋划"}, {"w": "畔离", "t": "背叛。"}]}, {"meaning": "违背;背离。", "cites": [{"t": "沈乱于酒,畔官离次。", "b": "《书·胤征》"}, {"t": "寡助之至,亲戚畔之。", "b": "《孟子·公孙丑下》"}, {"t": "其为人也,上忘而下畔。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "畔约", "t": "背约"}, {"w": "畔道", "t": "背离原则,正道"}, {"w": "畔废", "t": "不遵守贡物之制"}, {"w": "畔援", "t": "违离,改易。"}]}, {"meaning": "离,离开。", "cites": [{"t": "拘于习俗,而无敢畔其范围而已。", "b": "严复《原强》"}]}, {"meaning": "躲避。", "cites": [{"t": "连忙溜开畔入芦课荡里数只数。", "b": "《中国歌谣资料》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1900wx','蚣','1','gōng','虫','10','','[{"pinyin": "gōng", "defs": [{"meaning": "——见“蜈蚣”wúgōng。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1901wx','蚊','1','wén','虫','10','','[{"pinyin": "wén", "defs": [{"meaning": "蚊子。", "cites": [{"t": "飞蚊伺暗声如雷。", "b": "刘禹锡《聚蚊谣》"}, {"t": "虽得一饷乐,有如聚飞蚊。", "b": "唐·韩愈《醉赠张秘书》"}, {"t": "细若蚊足。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "蚊力", "t": "比喻力量微小"}, {"w": "蚊市", "t": "黄昏时,蚊子聚集如市。形容蚊子甚多"}, {"w": "蚊首", "t": "比喻极细微、就像蚊首一般"}, {"w": "蚊负", "t": "比喻能力不足而负担重任。即无法胜任之意"}, {"w": "蚊雷", "t": "蚊子飞集时如雷鸣的声音。后也比喻谤的言论"}, {"w": "蚊睫", "t": "蚊子的睫毛。比喻极细微之物"}, {"w": "蚊幌", "t": "蚊帐"}, {"w": "蚊厨", "t": "夏天用以避蚊子的帷帐"}, {"w": "蚊蝇", "t": "蚊虫苍蝇。亦喻纷扰的世情"}, {"w": "蚊蚁", "t": "蚁虫蚂蚁。比喻坏人"}, {"w": "蚊响", "t": "蚊虫聚飞发出的声音"}, {"w": "蚊聚", "t": "蚊虫集聚"}, {"w": "蚊翼", "t": "蚊虫的翅膀。比喻极小的事物"}, {"w": "蚊烟,蚊烟香", "t": "即蚊香"}, {"w": "蚊阵", "t": "犹言蚊群"}, {"w": "蚊眉", "t": "蚁子的眉毛。比喻极小的地方"}, {"w": "蚊吟", "t": "蚊子振翅所发出的声音"}, {"w": "蚊虻", "t": "一种危害牲兽的虫类;比喻轻微的危害"}, {"w": "蚊母鸟", "t": "即夜鹰。昼伏夜出,捕食蚊虻"}, {"w": "蚊虻负山", "t": "比喻力弱者担重任,难以信任"}, {"w": "蚊思负山", "t": "比喻力量虽微却愿担起重任。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1902wx','蚪','1','dǒu','虫','10','','[{"pinyin": "dǒu", "defs": [{"meaning": "——见“蝌蚪”(kēdǒu)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1903wx','蚓','1','yǐn','虫','10','','[{"pinyin": "yǐn", "defs": [{"meaning": "蚯蚓。", "cites": [{"t": "蚓无爪牙之利,筋骨之强。", "b": "《荀子·劝学》"}], "words": [{"w": "蚓曲", "t": "古代说传说蚯蚓夏夜能发出鸣声,其鸣声叫做蚓曲。也称“蚓笛”"}, {"w": "蚓操", "t": "蚯蚓唯壤土、水而自足,别无所求。比喻人只知守小节而不鸣大义"}, {"w": "蚓窍", "t": "相传蚯蚓的孔穴可以发声成曲。比喻微不足道的音响,通常作为自谦之词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1904wx','哨','1','shào','口','10','','[{"pinyin": "shào", "defs": [{"meaning": "(形声。从口,肖声。本义:口小不能容的,一说口歪不正的)。"}, {"meaning": "同本义。", "cites": [{"t": "哨,不容也。", "b": "《说文》"}, {"t": "哨,口不容也。", "b": "《韵会》引《说文》"}, {"t": "某有枉矢哨壶。", "b": "礼记·投壶》"}], "words": [{"w": "哨壶", "t": "口不正的壶。"}]}, {"meaning": "细狭尖锐。", "cites": [{"t": "哨,小也。", "b": "《后汉书·马融传》注"}, {"t": "大匈哨后。", "b": "马融《广成颂》"}], "words": [{"w": "哨棒", "t": "行路防身的长木棍"}, {"w": "哨腿", "t": "长腿。指高个子。"}]}, {"meaning": "巡逻。", "cites": [{"t": "质明,避哨竹林中。", "b": "《 指南录 后序》"}], "words": [{"w": "哨口", "t": "巡逻了望的关卡、岗哨"}, {"w": "哨船", "t": "在江中巡逻警戒的小兵船"}, {"w": "哨骑", "t": "巡逻骑的马。"}]}, {"meaning": "侦察。", "cites": [{"t": "男亲哨见,当道并无寨栅,军皆屯于山上。", "b": "《三国演义》"}], "words": [{"w": "哨路", "t": "探路"}, {"w": "哨见", "t": "探见"}, {"w": "哨军", "t": "侦察巡逻的士兵。"}]}, {"meaning": "撮口或用哨子发出响声。", "cites": [{"t": "张顺略哨一声,只见江上渔船撑扰来到岸边。", "b": "施耐庵《水浒传》"}], "words": [{"w": "哨聚", "t": "召集,聚集。"}]}, {"meaning": "吹;喷。", "cites": [{"t": "阴风飒飒,是神兵口内哨来烟;黑雾漫漫,是鬼祟暗中喷出气。", "b": "《西游记》"}]}, {"meaning": "叫;鸟叫。", "cites": [{"t": "行者又嚎,沙弥又哨,你须不夺人之好。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "一队人马。古代军事术语。泛称战阵的两翼或军队的一支、一队。", "cites": [{"t": "宋江传令李俊等领水兵六百,分为两哨。", "b": "施耐庵《水浒传》"}]}, {"meaning": "古代军队编制单位 。明永乐时分步骑军为中军、左右掖、左右哨,合为五军。清咸丰后立勇营,其制以百人为哨,三哨为一旗,五哨为一营。", "cites": [{"t": "而营、哨各官,亦多属旧人。", "b": "梁启超《谭嗣同传》"}]}, {"meaning": "哨兵。", "cites": [{"t": "质明,避哨竹林中,逻者数十骑,几无所逃死。", "b": "宋·文天祥《指南录·后序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1905wx','哩','1','li lī lǐ','口','10','','[{"pinyin": "li", "defs": [{"meaning": "用在陈述句末,表示肯定、猜测、夸张、强调等语气。"}, {"meaning": "[方言]用于句中并列成分之后,表示例举。"}]}, {"pinyin": "lī", "defs": [{"meaning": "稀疏、分散、时断时续的样子 ", "words": [{"w": "哩哩啦啦", "t": "零零散散或断断续续的样子。"}]}]}, {"pinyin": "lǐ", "defs": [{"meaning": "英里的旧称。英美制长度单位，一哩等于5280英尺，合1609米。（中国大陆地区已停用此字，写作\'英里\'）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1906wx','圃','1','pǔ','囗','10','','[{"pinyin": "pǔ", "defs": [{"meaning": "(形声。从囗,甫声。囗(wéi),围的古体字。从囗的字往往表示某一个范围或区域。本义:种植果木瓜菜的园地。周围常无垣篱)。"}, {"meaning": "同本义。", "cites": [{"t": "圃,种菜曰圃。", "b": "《说文》"}, {"t": "二曰园圃毓草木。", "b": "《周礼·太宰》。注:“树果蓏曰圃。”"}, {"t": "九月筑场圃。", "b": "《诗·豳风·七月》"}, {"t": "薮有圃草。", "b": "《国语·周语》"}, {"t": "其泽薮曰圃田。", "b": "《周礼·职方》"}, {"t": "开轩面场圃,把酒话桑麻。", "b": "唐·孟浩然《过故人庄》"}, {"t": "尝射于家圃(场地)。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "花圃", "t": "种花草的园地"}, {"w": "园圃", "t": "种蔬菜花果、树木的场所"}, {"w": "苗圃;圃畦", "t": "种蔬菜花果的园畦"}, {"w": "圃田", "t": "种植果木瓜菜的园地;大田;喻指事物聚集的地方。"}]}, {"meaning": "帝王贵族游乐观赏的地方。", "cites": [{"t": "赵王游于圃中。", "b": "《韩非子·外储说右下》"}]}, {"meaning": "种菜。亦指种菜的人。", "cites": [{"t": "我杏也,往年老圃种我时,费一核耳。", "b": "明·马中锡《中山狼传》"}, {"t": "是(这)特(只是)老妇老圃者之为也。", "b": "唐·柳宗元《非国语·三川震》"}, {"t": "吾不如老圃。", "b": "《论语·子路》"}]}, {"meaning": "大。", "cites": [{"t": "薮有圃草,囿有林池。", "b": "《国语·周语中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1907wx','哭','1','kū','口','10','','[{"pinyin": "kū", "defs": [{"meaning": "(会意。甲骨文字形,从(xuān),表示号呼;中间象一人擗踊的样子。本义:悲痛出声,声泪俱下)。"}, {"meaning": "同本义(有声有泪)。", "cites": [{"t": "哭,哀声也。", "b": "《说文》"}, {"t": "哭声震天动地。", "b": "张博《五人墓碑记》"}, {"t": "秦伯素服郊次,向师而哭。", "b": "《左传·僖公三十三年》"}, {"t": "蹇叔之子与师,哭而送之。", "b": "《左传·僖公三十二年》"}, {"t": "有妇人哭于墓者而哀。", "b": "《苛政猛于虎》"}], "words": [{"w": "哭哭嘶嘶", "t": "边哭边喊"}, {"w": "哭唠叨", "t": "方言。边哭边诉说"}, {"w": "哭踊", "t": "哭泣踊跳。为古代丧礼的一种仪节"}, {"w": "哭临", "t": "到现场啼哭。古代帝王的丧事,往往集众举哀叫哭临。"}]}, {"meaning": "吊唁,祭奠死者并慰问家属。", "cites": [{"t": "则哭以厌之。", "b": "《汉书·王莽传》。注:“哭 者所以告哀也。”"}], "words": [{"w": "哭先祖", "t": ""}]}, {"meaning": "歌。", "cites": [{"t": "昔雍门子以哭见于孟尝君。", "b": "《淮南子·览冥训》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1908wx','哦','1','é ó','口','10','','[{"pinyin": "é", "defs": [{"meaning": "吟咏。", "cites": [{"t": "日哦招隐诗,月诵归田赋。", "b": "宋·梅尧臣《招隐堂寄题乐郎中》"}], "words": [{"w": "哦吟", "t": "吟咏,吟诗。"}]}, {"meaning": "用以表示喜悦、惊异或强烈的感情。"}]}, {"pinyin": "ó", "defs": [{"meaning": "表示疑问、惊奇等。", "cites": [{"t": "哦!你就是来霞士。", "b": "《儒林外史》"}], "words": [{"w": "哦!会有这样的人?", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1909wx','恩','1','ēn','心','10','','[{"pinyin": "ēn", "defs": [{"meaning": "(形声。从心,因声。本义:恩惠)。"}, {"meaning": "同本义。", "cites": [{"t": "恩,惠也。", "b": "《说文》"}, {"t": "恩者,仁也。", "b": "《礼记·丧服四制》"}, {"t": "如此,则上下之恩结矣。", "b": "《韩非子·用人》"}, {"t": "夫人有恩而背之,不祥莫大焉。", "b": "明·马中锡《中山狼传》"}]}, {"meaning": "又。", "cites": [{"t": "先生之恩,生死而骨肉也。", "b": ""}], "words": [{"w": "忘恩;报恩;恩润", "t": "恩惠德泽"}, {"w": "恩义", "t": "恩情与道义"}, {"w": "恩分", "t": "恩惠情分"}, {"w": "恩惠教化古代多指官方对人民而言;恩田", "t": "佛家田。三福之一。指父母。"}]}, {"meaning": "情谊。", "cites": [{"t": "大丈夫处世,遇知己之主,外托君臣之义,内结骨肉之恩,言必行,计必从。", "b": "《三国演义》"}]}, {"meaning": "恩爱,亲爱。", "cites": [{"t": "明主知之,故不养恩爱之心而增威严之势。", "b": "《韩非子·六反》"}], "words": [{"w": "恩客", "t": "妓女对特别亲爱的客人的称呼"}, {"w": "恩意", "t": "恩爱的心意"}, {"w": "恩狎", "t": "宠爱亲热"}, {"w": "恩慈", "t": "宠爱慈惠。"}]}, {"meaning": "恩赐,加恩。", "cites": [{"t": "傅太后恩赵太后。", "b": "《汉书·外戚传》"}, {"t": "彼不我恩(加恩,优待)也。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "恩赍", "t": "恩赐的财物"}, {"w": "恩台", "t": "老百姓对地方官的尊称"}, {"w": "恩相", "t": "对长官的尊称"}, {"w": "恩家", "t": "奴仆尊称主人"}, {"w": "恩主", "t": "对施恩于己者的敬称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1910wx','鸯','1','yāng','鸟','10','','[{"pinyin": "yāng", "defs": [{"meaning": "——见“鸳鸯”(yuānyang)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1911wx','唤','1','huàn','口','10','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从口,奂(huàn)声。本义:呼,叫,)。"}, {"meaning": "同本义。", "cites": [{"t": "唤,呼也。", "b": "《说文新附》"}, {"t": "不闻爷娘唤女声。", "b": "《乐府诗集·木兰诗》"}, {"t": "千呼万唤始出来。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "唤门", "t": "在门外叫内边的人开门"}, {"w": "唤应", "t": "呼应,照应"}, {"w": "唤字叫背", "t": "掷钱猜正反面赌博。"}]}, {"meaning": "呼唤使来。", "cites": [{"t": "虑诸公不奉诏,于是先唤周侯、丞相入。", "b": "《世说新语·方正》"}], "words": [{"w": "唤取", "t": "呼请"}, {"w": "唤集", "t": "召集"}, {"w": "唤铁", "t": "一种响铁器,敲击时可以招唤鸟兽。"}]}, {"meaning": "啼叫,禽鸟发出叫声。", "cites": [{"t": "东方欲明星烂烂,汝南晨鸡登坛唤。", "b": "《乐府诗集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1912wx','唁','1','yàn','口','10','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从口,言声。本义:对遭遇非常变故者的慰问。后多指对遭遇丧事的人的慰问)。", "cites": [{"t": "公孙于齐,齐侯唁公于野井。", "b": "《左传》"}], "words": [{"w": "唁奠", "t": "吊唁祭奠"}, {"w": "唁劳", "t": "对遭丧事者进行慰问"}, {"w": "唁慰", "t": "对死者家属表示安慰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1913wx','哼','1','hēng hng','口','10','','[{"pinyin": "hēng", "defs": [{"meaning": "(形声。从口,亨声。本义:痛苦作声)。"}, {"meaning": "同本义。訇的俗字。", "cites": [{"t": "且睡在床上推病,口里哼哼囋囋的不绝。", "b": "《西游记》"}], "words": [{"w": "哼贲", "t": "呻吟。通“唧”"}, {"w": "哼儿哈儿", "t": "呵斥的声音"}, {"w": "哼哼囋囋", "t": "痛苦时的呻吟声"}, {"w": "哼哼唧唧", "t": "象声词。形容病痛的呻吟声"}, {"w": "痛得直哼", "t": ""}]}]}, {"pinyin": "hng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1914wx','唧','1','jī','口','10','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从口,即声。本义:象声词。唧唧:杂乱细碎的声音;秋虫鸣声) 同本义", "words": [{"w": "唧唧哝哝", "t": "小声唠叨"}, {"w": "唧唧咕咕", "t": "小声唠叨"}, {"w": "唧唧啾啾", "t": "小声唠叨"}]}, {"meaning": "突然有力的喷射出"}, {"meaning": "吸水上喷"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1915wx','啊','1','ā á ǎ à a','口','10','','[{"pinyin": "ā", "defs": [{"meaning": "(形声。从口,阿声。本义:叹词)表示惊叹或赞颂", "words": [{"w": "啊哈", "t": "表示语气的叹词"}, {"w": "啊呀", "t": "表示惊讶"}]}]}, {"pinyin": "á", "defs": [{"meaning": "表示追问或要求再说一遍"}]}, {"pinyin": "ǎ", "defs": [{"meaning": "表示惊疑或疑惑"}]}, {"pinyin": "à", "defs": [{"meaning": "表示应诺等的叹词。"}, {"meaning": "表示醒悟。"}, {"meaning": "表示惊异或赞叹。"}, {"meaning": "用来表示悲痛、遗憾或忧伤。"}]}, {"pinyin": "a", "defs": [{"meaning": "表示语气。"}, {"meaning": "用在感叹句末,加强感叹语气。"}, {"meaning": "用在陈述句或祈使句,表示肯定、辨明、请求、劝止、警告、催促、命令等。"}, {"meaning": "用在问句末尾。"}, {"meaning": "在有疑问指代词的问句或选择问句里,用来和缓语气。"}, {"meaning": "用在打招呼的话里。"}, {"meaning": "用在重复的动词后面,表示过程长。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1916wx','唉','1','āi ài','口','10','','[{"pinyin": "āi", "defs": [{"meaning": "(形声。从口,矣声。本义:表示答应)。"}, {"meaning": "同本义。", "cites": [{"t": "唉,应也。", "b": "《说文》"}, {"t": "唉,予知之。", "b": "《庄子·知北游》。释文:“应声。”"}, {"t": "勤唉厥生。", "b": "《韦贤讽谏诗》"}], "words": [{"w": "“你一定要去呀!”“唉,我是要去的”", "t": ""}]}, {"meaning": "假借为诶。表示叹息。", "cites": [{"t": "亚父受玉斗,置之地,拔剑撞而破之,曰:“唉!竖子不足与谋”。", "b": "《史记·项羽本纪》。"}], "words": [{"w": "“唉!”他又长长地叹了口气;唉!管不了他!", "t": ""}]}]}, {"pinyin": "ài", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1917wx','唆','1','suō','口','10','','[{"pinyin": "suō", "defs": [{"meaning": "(形声。本义:怂恿人做坏事)。"}, {"meaning": "同本义。", "cites": [{"t": "怎禁猪八戒气不忿,在旁漏八分儿唆嘴道“师父,说起这个女子,他是此间农妇,…却怎么栽他是个妖怪?", "b": "《西游记》"}], "words": [{"w": "唆讼", "t": "教唆诉讼的简称"}, {"w": "唆教", "t": "挑拨;唆弄"}, {"w": "唆掇", "t": "撺掇;怂恿"}, {"w": "唆犯", "t": "调唆;撺掇"}, {"w": "唆哄", "t": "教唆哄骗"}, {"w": "唆激", "t": "教唆挑动"}, {"w": "唆冷", "t": "挑拨,使疏远、冷漠"}, {"w": "唆说", "t": "挑拨"}, {"w": "唆送", "t": "挑拨;教唆"}, {"w": "唆诱", "t": "挑动诈骗"}, {"w": "唆摆", "t": "调唆摆布"}, {"w": "唆嘴", "t": "摆弄口舌"}, {"w": "唆拨", "t": "教唆挑拨"}, {"w": "唆诈", "t": "教唆哄骗"}, {"w": "唆毒", "t": "狠毒地挑拨"}, {"w": "唆令", "t": "唆使。"}]}, {"meaning": "犹噀。喷。", "cites": [{"t": "被先生咬破中指,向西唆了,狂风起,楚兵三人都在阵中。", "b": "《七国春秋平话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1918wx','罢','1','bà ba','罒','10','','[{"pinyin": "bà", "defs": [{"meaning": "(会意。从网,从能。表示用网捕住有贤能的人。“网”在字的上部楷书多写作“罒”。本义:罢官;免去;解除)。"}, {"meaning": "同本义。", "cites": [{"t": "可以罢官之无事者,去器之无用者。", "b": "《吕氏春秋·仲冬》"}, {"t": "窦太后大怒,乃罢逐赵绾、王臧等。", "b": "《史记·魏其武安侯列传》"}, {"t": "闻君罢官意,我抱汉川湄。", "b": "李白《赠汉阳辅录事二首》"}, {"t": "徐阶罢相里居。", "b": "《明史·海瑞传》"}, {"t": "复请之,吾辈无生理,而主谳者亦各罢去。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "罢谢", "t": "辞官去职"}, {"w": "罢归", "t": "辞职或免官归里。"}]}, {"meaning": "停止。", "cites": [{"t": "于是罢酒。", "b": "《史记·魏公子列传》"}], "words": [{"w": "罢休;罢兵", "t": "停止战争"}, {"w": "罢手", "t": "停止;住手"}, {"w": "罢业", "t": "停业;罢工"}, {"w": "罢战", "t": "停战;停止争斗。"}]}, {"meaning": "完毕。", "cites": [{"t": "既罢归国。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "及反,市罢,遂不得履。", "b": "《韩非子·郑人买履》"}, {"t": "曲罢曾教善才服。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "吃罢了饭;罢散", "t": "谓结束。"}]}, {"meaning": "废除;取消。", "cites": [{"t": "愿罢盐铁、酒榷、均输,所以进本退末。", "b": "《盐铁论·本议》"}], "words": [{"w": "罢弃", "t": "废除"}, {"w": "罢废", "t": "废弃。"}]}]}, {"pinyin": "ba", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1919wx','峭','1','qiào','山','10','','[{"pinyin": "qiào", "defs": [{"meaning": "(形声。从山,肖声。《说文》:从阜。本义:陡直)。"}, {"meaning": "同本义。", "cites": [{"t": "峭,陵也。从阜,肖声。斗直曰峭。", "b": "《说文》"}, {"t": "峭,高也。字亦作峭。", "b": "《广雅》"}, {"t": "上峭山。", "b": "《淮南子·脩务》"}, {"t": "涧深,峭如墙。", "b": "《韩非子·内储说上》"}, {"t": "峭拔险怪。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "高岩峭壁。", "b": ""}, {"t": "峭拔秀丽。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "峭壁拔起。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "峭壑阴森。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "峭拔", "t": "特立高耸"}, {"w": "峭岸", "t": "陡岸"}, {"w": "峭谷", "t": "险峻的山谷"}, {"w": "峭坂", "t": "高陡的山坡"}, {"w": "峭卓", "t": "高峻陡直"}, {"w": "峭岫", "t": "陡峭的峰峦"}, {"w": "峭削", "t": "陡峭如削"}, {"w": "峭峙", "t": "耸立"}, {"w": "峭峭", "t": "高峻,高。"}]}, {"meaning": "挺拔;直立而高耸。", "cites": [{"t": "白浪如山那可渡,狂风愁杀峭帆人。", "b": "李白《横江词》"}, {"t": "披林入峭茜,攀磴陟崔嵬。", "b": "张说《过蜀道山》"}], "words": [{"w": "峭帆", "t": "耸立的船帆。亦借指驾船"}, {"w": "峭危", "t": "高耸陡峭"}, {"w": "峭崛", "t": "刚健挺拔"}, {"w": "峭耸", "t": "高耸;陡峭"}, {"w": "峭秀", "t": "挺拔秀丽。"}]}, {"meaning": "严峻。", "cites": [{"t": "错为人峭直刻深。", "b": "《汉书·晁错传》"}, {"t": "宰相刻削(峭)。", "b": "《四子讲德论》"}], "words": [{"w": "峭直", "t": "严峻刚直"}, {"w": "峭鲠", "t": "严峻刚直"}, {"w": "峭冷", "t": "严峻冷漠"}, {"w": "峭刑", "t": "严刑"}, {"w": "峭法", "t": "严峻的法令"}, {"w": "峭洁", "t": "严峻高洁。"}]}, {"meaning": "苛刻,严酷。", "cites": [{"t": "冷露滴梦破,峭风梳骨寒。", "b": "孟郊《秋怀》"}], "words": [{"w": "冷峭", "t": "冷气逼人;比喻为人刻薄,话语尖刻"}, {"w": "峭险", "t": "严酷阴险"}, {"w": "峭薄", "t": "刻薄。"}]}, {"meaning": "高超不凡。", "cites": [{"t": "西岳高僧名贯休,孤情峭拔凌清秋。", "b": "欧阳炯《贯休应梦罗汉画歌》"}], "words": [{"w": "峭异", "t": "特出不凡"}, {"w": "峭特", "t": "峭拔独特"}, {"w": "峭汉", "t": "特殊人物。"}]}, {"meaning": "陡岩,坡度极大的山崖。", "cites": [{"t": "独临青峭倚长松。", "b": "王安石《观王氏雪图》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1920wx','峨','1','é','山','10','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从山,我声。本义:山势高峻。常“峨峨”连用)泛指高大。", "cites": [{"t": "峨,嵯峨也。", "b": "《说文》"}, {"t": "峨,高也。", "b": "《广雅·释诂四》"}, {"t": "冠浮云之峨峨。", "b": "《楚辞·惜贤》"}, {"t": "中峨冠而多髯者为东坡。", "b": "明·魏学洢《核舟记》"}, {"t": "峨大冠、拖长绅者,昂昂乎庙堂之器也,果能建伊、皋之业耶。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "峨然", "t": "高貌"}, {"w": "峨巍", "t": "高魇样子"}, {"w": "峨舸", "t": "高大的船"}, {"w": "峨冠", "t": "高的冠冕"}, {"w": "峨冕", "t": "高冠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1921wx','峰','1','fēng','山','10','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。从山,峯(fēng)声。本义:山顶)。"}, {"meaning": "同本义。", "cites": [{"t": "峯,山耑也。", "b": "《说文新附》"}, {"t": "夹岸高山…争高直指,千百成峰。", "b": "吴均《与朱元思书》"}], "words": [{"w": "山峰", "t": "山的突出的尖顶"}, {"w": "高峰;孤峰;峰岫,峰朵,峰头;峰腹", "t": "山峰中部。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1922wx','圆','1','yuán','囗','10','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从囗(wéi),员声。本义:圆形)。"}, {"meaning": "同本义。", "cites": [{"t": "圆,圜全也。", "b": "《说文》"}, {"t": "圆而神。", "b": "《易·系辞》"}, {"t": "天道曰圆,地道曰方。", "b": "《大戴礼记·曾子天圆》"}, {"t": "中吾规者谓之圆。", "b": "《墨子·天志》"}, {"t": "水圆折者有珠。", "b": "《淮南子·地形》"}, {"t": "百工为方以矩,为圆以规。", "b": "《墨子·法仪》"}, {"t": "方圆两炮台。", "b": "《广东军务记》"}], "words": [{"w": "圆丢丢", "t": "圆溜溜"}, {"w": "圆浑", "t": "浑圆"}, {"w": "圆领", "t": "明朝官员的常礼服。其胸前背后加有不同图案的补子以区别官阶的,叫补服"}, {"w": "滚圆", "t": "极圆。"}]}, {"meaning": "圆通;灵活。", "cites": [{"t": "如今到外头去作官,自然非家居可比,总得学些圆通。", "b": "《儿女英雄传》"}], "words": [{"w": "圆便", "t": "变通的办法"}, {"w": "圆媚", "t": "处世圆滑,善于逢迎"}, {"w": "圆活", "t": "圆滑。指处世变通灵活;周全。"}]}, {"meaning": "圆满;完整。", "cites": [{"t": "蓍之德,圆而神。", "b": "《易·系辞上》"}], "words": [{"w": "圆图", "t": "录取名单;古时县考时用以公布考生中考的榜牌"}, {"w": "圆成", "t": "佛教语。成就圆满;圆满成功"}, {"w": "圆妙", "t": "佛教语。圆满融通"}, {"w": "圆明", "t": "佛教语。彻底领悟。"}]}, {"meaning": "丰满;周全。", "cites": [{"t": "其粟圆而薄糠。", "b": "《吕氏春秋·审时》"}], "words": [{"w": "圆湛", "t": "饱满的样子"}, {"w": "圆匀", "t": "丰满匀称。"}]}, {"meaning": "婉转;圆润。", "cites": [{"t": "深圆似轻簧。", "b": "白居易《题周家歌者》"}], "words": [{"w": "圆丽", "t": "圆润秀丽。"}]}, {"meaning": "圆周。", "cites": [{"t": "右手画圆,左手画方。", "b": "《韩非子》"}]}, {"meaning": "指天。", "cites": [{"t": "载圆履方。", "b": "《淮南子》"}], "words": [{"w": "圆天", "t": "古人认为无呈圆形,故称“圆天”"}, {"w": "圆方", "t": "古人认为天圆地方,因此“圆方”代称天地"}, {"w": "圆空", "t": "天空,天"}, {"w": "圆象", "t": "天象"}, {"w": "圆盖", "t": "圆宰,圆苍,圆精,圆灵。都指天。"}]}, {"meaning": "丸,圆而小的东西。", "cites": [{"t": "炒肉片,煎肉圆,闷青鱼。", "b": "《儒林外史》"}]}, {"meaning": "使圆满,成全。", "cites": [{"t": "你只依着师傅这话,就算给师傅圆上这个脸了。", "b": "《儿女英雄传》"}], "words": [{"w": "圆备", "t": "完成"}, {"w": "圆就", "t": "成全;圆满"}, {"w": "圆亲", "t": "娶亲,成亲"}, {"w": "圆谎", "t": "掩盖弥补谎话中的漏洞"}, {"w": "自圆其说", "t": ""}]}, {"meaning": "旋转。", "cites": [{"t": "(王述)但性急为累,尝食鸡子,以筋刺之,不得,便大怒掷地,鸡子团转不止。", "b": "《晋书》"}], "words": [{"w": "圆旋", "t": "回旋"}, {"w": "圆转", "t": "旋转"}, {"w": "圆折", "t": "水流旋转曲折。"}]}, {"meaning": "团圆,散而重聚。", "cites": [{"t": "试问古来几曾见破镜能重圆?", "b": "清·林觉民《与妻书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1923wx','峻','1','jùn','山','10','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。从山,雋(jùn)声。本义:高而陡峭)。"}, {"meaning": "同本义。", "cites": [{"t": "山峻高而蔽日兮。", "b": "《楚辞·屈原·涉江》"}, {"t": "山道峻隘。", "b": "《北齐书·高昂传》"}, {"t": "是犹上高陵之颠堕峻溪之下而求生。", "b": "《韩非子·奸劫弑臣》"}], "words": [{"w": "峻危", "t": "高耸险峻"}, {"w": "峻朵", "t": "高峻的山峰"}, {"w": "峻岭", "t": "崇高的山岭"}, {"w": "峻绝", "t": "极为陡峭。"}]}, {"meaning": "严酷,严厉。", "cites": [{"t": "乃峻责租调。", "b": "《新唐书·李实传》"}, {"t": "严刑峻法。", "b": "《论衡·非韩》"}, {"t": "因以峻文诋之。", "b": "《后汉书·朱浮传》"}], "words": [{"w": "峻政", "t": "苛政"}, {"w": "峻责", "t": "严厉责求"}, {"w": "峻拒", "t": "断然拒绝"}, {"w": "峻辞", "t": "断然辞绝。"}]}, {"meaning": "大;高大。", "cites": [{"t": "克明峻德。", "b": "《礼记·大学》"}], "words": [{"w": "峻宇", "t": "高大的屋宇"}, {"w": "峻德", "t": "大德"}, {"w": "峻命", "t": "大命,指天帝或帝王的命令"}, {"w": "峻博", "t": "博大。"}]}, {"meaning": "增高,加高。", "cites": [{"t": "群臣白帝更峻京邑城隍,以从《周易》设险之义。", "b": "《魏书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1924wx','贼','1','zéi','贝','10','','[{"pinyin": "zéi", "defs": [{"meaning": "(会意。小篆字形,从戈,则声。从戈,刀毁贝。 本义:残害;伤害)。"}, {"meaning": "同本义。", "cites": [{"t": "贼,败也。", "b": "《说文》"}, {"t": "害良为贼。", "b": "《荀子·修身》"}, {"t": "不僭不贼,鲜不为则。", "b": "《诗·大雅·抑》"}, {"t": "寒暑弗能害,禽兽弗能贼。", "b": "《庄子·秋水》"}, {"t": "毁则为贼。", "b": "《左传·文公十八年》。杜预注:“毁则,坏法也。”"}, {"t": "下广汉廷尉狱,又坐贼杀不辜。", "b": "《汉书·赵尹韩张两王传》"}], "words": [{"w": "贼毫", "t": "书法的败笔。指笔锋之劣"}, {"w": "贼伦", "t": "毁弃伦常,败坏道德"}, {"w": "贼仁", "t": "毁弃仁爱"}, {"w": "贼蚀", "t": "受到的歪曲损害"}, {"w": "贼义", "t": "毁弃道义"}, {"w": "贼害", "t": "残害、伤害"}, {"w": "贼蠹", "t": "危害"}, {"w": "贼殃", "t": "祸害。"}]}, {"meaning": "特指杀害。", "cites": [{"t": "贼民之主,不忠。", "b": "《左传·宣公二年》"}, {"t": "宣公骤谏,公患之,使鉏贼之。", "b": ""}, {"t": "杀人不忌为贼。", "b": "《左传·昭公十四年》"}, {"t": "刑杀不正谓之贼。", "b": "《烈女传·辩通》"}], "words": [{"w": "贼斗", "t": "残杀格斗"}, {"w": "贼残", "t": "残害"}, {"w": "贼场", "t": "讨贼的战场"}, {"w": "贼杀", "t": "杀害"}, {"w": "贼性", "t": "残杀之性"}, {"w": "贼刑", "t": "刑杀"}, {"w": "贼诛", "t": "杀害。"}]}, {"meaning": "先秦两汉时期,贼指作乱叛国危害人民的人。", "cites": [{"t": "商君,秦之贼。秦强而贼入魏,弗归,不可。", "b": "《史记·商君列传》"}, {"t": "讨贼复兴之效。", "b": "诸葛亮《出师表》"}, {"t": "其实汉贼也。", "b": "《资治通鉴》"}, {"t": "几落贼手死。", "b": "宋·文天祥《指南录后序》"}, {"t": "贼中险易远近。", "b": "《资治通鉴·唐纪》"}, {"t": "西后及贼臣忌益甚。(贼臣,指当时反对变法维新的顽固派。)", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "卖国贼;工贼;贼子", "t": "反叛,叛乱或叛逆的人"}, {"w": "贼臣", "t": "叛逆不忠的臣子"}, {"w": "贼官", "t": "为敌方效力的伪官。"}]}, {"meaning": "刺客,杀人的人。", "cites": [{"t": "大索天下,求贼甚急,为张良故也。", "b": "《史记·留侯世家》"}, {"t": "燕王昏乱,其太子丹乃阴令荆轲为贼。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "偷窃或抢劫的人(先秦两汉用“盗”,多指偷窃者,很少指抢劫者;用贼,多指抢劫财物者,后来才指偷窃者)。", "cites": [{"t": "使长安丞龚奢叩堂户晓贼。", "b": "《汉书·赵尹韩张两王传》"}, {"t": "贼二人得我,我幸皆杀之矣。", "b": "唐·柳宗元《童区寄传》"}, {"t": "大盗积贼,杀人重囚,气杰旺,染此者,十不一二。", "b": "方苞《狱中杂记》"}, {"t": "贼能且众。", "b": "明·魏禧《大铁椎传》"}, {"t": "一贼提刀。", "b": ""}, {"t": "贼应声落马。", "b": ""}, {"t": "令贼知也。", "b": ""}], "words": [{"w": "盗贼", "t": "强盗和小偷"}, {"w": "窃贼", "t": "小偷儿"}, {"w": "贼不空手", "t": "比喻势在必得"}, {"w": "贼属", "t": "贼寇的家眷亲属。"}]}, {"meaning": "骂人的字眼。", "cites": [{"t": "老贼欲废汉自立。", "b": "《资治通鉴》"}, {"t": "与老贼势不两立。", "b": ""}, {"t": "贼臣忌益甚。", "b": "清·梁启超《谭嗣同传》"}, {"t": "此乃荣贼。", "b": ""}]}, {"meaning": "祸害。", "cites": [{"t": "淫侈之欲日日以长,是天下之大贼也。", "b": "贾谊《论积贮疏》"}]}, {"meaning": "敌人;仇敌。", "cites": [{"t": "环顾国内,贼氛方炽。(敌人的气焰正嚣张。氛,气,气焰。方,副词。炽,火旺盛。)", "b": "孙文《黄花冈七十二烈士事略序》"}, {"t": "谄谀我者,吾贼也。", "b": "《荀子·修身》"}]}, {"meaning": "邪恶,不正派。", "cites": [{"t": "寒暑不和,贼气相奸。", "b": "《史记·龟策列传》"}], "words": [{"w": "贼贱", "t": "卑贱;下贱"}, {"w": "贼尘", "t": "有害的灰尘。喻欺君罔上者"}, {"w": "贼忒忒", "t": "形容眼神不正派"}, {"w": "贼智", "t": "鬼点子,狡猾办法"}, {"w": "老鼠真贼", "t": ""}]}, {"meaning": "残暴;狠毒。", "cites": [{"t": "内怀诈以御主心,外挟贼吏以为威重。", "b": "《汲黯列传》"}, {"t": "[郭解]少时阴贼。", "b": "《史记·游侠列传》"}], "words": [{"w": "贼深", "t": "心肠残酷,用法深刻"}, {"w": "贼暴", "t": "残虐;暴虐"}, {"w": "贼悍", "t": "残暴凶悍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1925wx','贿','1','huì','贝','10','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从贝,有声。本义:财物)。"}, {"meaning": "同本义。", "cites": [{"t": "贿,财也。", "b": "《尔雅》"}, {"t": "窃贿为盗。", "b": "《左传·文公十八年》"}, {"t": "以尔车来,以我贿迁。", "b": "《诗·卫风·氓》"}, {"t": "商贾阜通货贿。", "b": "《周礼·太宰》。注:“金玉曰货,布帛曰贿。”"}, {"t": "贿用束纺。", "b": "《仪礼·聘礼》。注:“贿予人财之言也。”"}, {"t": "先诸侯之贿,聚于公室。", "b": "《左传·襄公二十四年》"}, {"t": "假货居贿。", "b": "《国语·晋语》"}], "words": [{"w": "贿交", "t": "以财物相交"}, {"w": "贿货", "t": "财物"}, {"w": "贿赂", "t": "财货。"}]}, {"meaning": "赠送财物。", "cites": [{"t": "孟献子聘于周,王以为有礼,厚贿之。", "b": "《左传·宣公九年》"}, {"t": "贿用周室之璧。", "b": "《穆天子传》"}, {"t": "宋人重贿之。", "b": "《左传·襄公二十年》"}], "words": [{"w": "贿赠", "t": "以财物奉赠"}, {"w": "贿谢", "t": "赠礼酬谢。亦指赠送或酬谢的礼物"}, {"w": "贿币", "t": "赠送的礼物。"}]}, {"meaning": "用财物买通别人。", "cites": [{"t": "政刑驰紊,贿货公行。", "b": "《陈书·后主沈皇后传》"}], "words": [{"w": "贿免", "t": "用财物买通"}, {"w": "贿嘱", "t": "贿赂嘱托"}, {"w": "贿遗", "t": "行贿的财物"}, {"w": "贿卖", "t": "收受贿赂,卖官爵,通关节。"}]}, {"meaning": "受贿。", "cites": [{"t": "居官必贿。", "b": "宋·司马光《训俭示康》"}, {"t": "非贿得之。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "污贿不饬。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1926wx','赂','1','lù','贝','10','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从贝,各声。从“贝”,表示与钱财有关。本义:赠送财物)。"}, {"meaning": "同本义。", "cites": [{"t": "赂,遗也。", "b": "《说文》"}, {"t": "大赂南金。", "b": "《诗·鲁颂·泮水》"}, {"t": "骊姬赂二王。", "b": "《国语·晋语》"}, {"t": "因厚赂单于,答其善意。", "b": "《汉书·苏武传》"}, {"t": "割国之锱铢而赂之。", "b": "《荀子·富国》"}, {"t": "仅汉,汉之赂遗王财物,不可胜言。", "b": "《汉书·张骞传》"}, {"t": "于是从散约解,争割地而赂秦。", "b": "贾谊《过秦论》"}], "words": [{"w": "赂贿", "t": "用财物买通别人。"}]}, {"meaning": "行贿,用钱、物买通别人。", "cites": [{"t": "六国破灭,非兵不利、战不善,弊在赂秦。", "b": "宋·苏洵《六国论》"}, {"t": "富者赂数十百金。", "b": "方苞《狱中杂记》"}], "words": [{"w": "贿赂", "t": "古代一般用“赇”字表示。如“受赇枉法。”中古时,“赇”与“赂”可以同义连用,这时的赂就是带贬义的“赂”了"}, {"w": "赂门", "t": "行贿的途径"}, {"w": "赂息", "t": "行贿以求息事"}, {"w": "赂买", "t": "行贿买通"}, {"w": "赂结", "t": "以行贿而结交"}, {"w": "赂赠", "t": "行贿。"}]}, {"meaning": "赠送的财物和钱。", "cites": [{"t": "货赂将甚厚。", "b": "《荀子·富国》"}, {"t": "数之王命,取赂而还。", "b": "《左传·庄公二十八年》"}, {"t": "家贫,货赂不足以自赎。", "b": "司马迁《报任安书》"}, {"t": "王及列士皆有馈赂。", "b": "《左传·哀公十一年》"}], "words": [{"w": "赂田", "t": "赠送的田"}, {"w": "赂地", "t": "赠送的土地"}, {"w": "赂贿", "t": "用来买通别人的财物"}, {"w": "赂器", "t": "指受贿得来的器物。"}]}, {"meaning": "美玉。", "cites": [{"t": "元龟象齿,大赂南金。", "b": "《诗·鲁颂·泮水》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1927wx','赃','1','zāng','贝','10','','[{"pinyin": "zāng", "defs": [{"meaning": "(形声。左形,右声。本义:赃物) 同本义。", "cites": [{"t": "以赃获罪,没其先居之财。", "b": "《列子·天瑞》"}], "words": [{"w": "赃仗", "t": "赃证"}, {"w": "赃派", "t": "栽赃诬陷"}, {"w": "栽赃", "t": "坐赃。把赃物或违禁物暗放在别人处,诬告他犯法"}, {"w": "窝赃;追赃;分赃;退赃;销赃;赃品", "t": "赃物"}, {"w": "赃银", "t": "赃款。"}]}, {"meaning": "贪污;行贿。", "cites": [{"t": "纳贿曰赃。", "b": "《广韵》"}, {"t": "南阳太守韩昭坐赃,下狱死。", "b": "《后汉书·质帝纪》"}, {"t": "所在虏掠,赃各千万计,并斩之。", "b": "《魏书·世祖纪》"}], "words": [{"w": "赃秽", "t": "贪赃纳贿"}, {"w": "赃罪", "t": "贪污受贿罪"}, {"w": "赃贿", "t": "贪赃纳贿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1928wx','钱','1','qián','钅','10','','[{"pinyin": "qián", "defs": [{"meaning": "(形声。从金,戔(jiān)声。(jiǎn)本义:农具名,即铁铲。上古时期曾以农具作为交易媒介,其后铸造货币又仿其形为之,因此引申为货币、钱财)。"}, {"meaning": "金属货币。特指铜钱。", "cites": [{"t": "一曰货也。古者货贝而宝龟。周太公立九府圜法,乃用泉,至秦废贝行钱。", "b": "《说文解字》锴注"}, {"t": "龟贝金钱。", "b": "《史记·平准书》。索隐:“本名泉,言货之如流泉也。”"}, {"t": "景王二十一年将铸大钱。", "b": "《国语·周语》。注:“钱者,金币之名,古曰泉,后转曰钱。”"}, {"t": "下有积钱。", "b": "《史记·天官书》"}, {"t": "卖炭得钱何所营?", "b": "唐·白居易《卖炭翁》"}, {"t": "以钱覆其上。", "b": "宋·欧阳修《归田录》"}, {"t": "自钱孔入。", "b": ""}, {"t": "而钱不湿。", "b": ""}], "words": [{"w": "钱眼", "t": "铜钱中的方孔。喻指金钱"}, {"w": "钱价", "t": "铜钱折合成银两的价格"}, {"w": "钱范", "t": "铸造金属货币用的模子"}, {"w": "钱幕", "t": "钱镘。钱币的背面"}, {"w": "钱缗", "t": "穿钱的绳子"}, {"w": "钱品", "t": "钱的质地、形制"}, {"w": "钱花花", "t": "小钱,铜板。"}]}, {"meaning": "像铜钱的东西。", "cites": [{"t": "空室无人行则生苔藓,或青或紫,一名绿钱。", "b": "晋·崔豹《古今注》"}]}, {"meaning": "衡名。"}, {"meaning": "公制重量单位。一公斤的十分之一为一公两。一公两的十分之一为一公钱。"}, {"meaning": "市制重量单位。中国市制中计算质量和重量的一种单位。以前是一市斤的十六分之一(现在是十分之一)为市两,一市两的十分之一为一市钱。"}, {"meaning": "旧营造库平制。两的十分之一为钱。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1929wx','钳','1','qián','钅','10','','[{"pinyin": "qián", "defs": [{"meaning": "(形声。从金,甘声。本义:金属夹具)。"}, {"meaning": "古刑具。束颈的铁圈。", "cites": [{"t": "钳,以铁有所劫束也。", "b": "《说文》"}, {"t": "皆弛解钳。", "b": "《后汉书·光武纪》"}, {"t": "古之刑在项曰钳,今之链锁。", "b": "清·阮葵生《茶余客话》"}], "words": [{"w": "钳铁", "t": "古代束颈的刑具"}, {"w": "钳髠", "t": "钳和髠。古代束颈、剃发之刑"}, {"w": "钳釱", "t": "古代两种刑具名,钳与釱"}, {"w": "钳扭", "t": "束颈缚手的刑具"}, {"w": "钳锁", "t": "小儿的金属首饰;又指古代用以束颈、锁身的两种刑具。"}]}, {"meaning": "古代刑罚。用铁圈束颈、手、足。", "cites": [{"t": "烧铁钳灼。", "b": "《汉书·江充传》"}, {"t": "自髠钳为王家奴。", "b": "《汉书·高帝纪》"}, {"t": "楚人将钳我于市。", "b": "《汉书·楚元王传》。注:“以铁束颈也。”"}], "words": [{"w": "钳奴", "t": "受过钳刑而被充作奴隶的人"}, {"w": "钳赭", "t": "犯人身穿赤衣,以铁束颈的刑法"}, {"w": "钳梏", "t": "以铁箍束颈,以木械铐手"}, {"w": "钳徒", "t": "被施钳刑的人"}, {"w": "钳市", "t": "束颈游街。"}]}, {"meaning": "(钳为箝的简化字)。"}, {"meaning": "夹住。", "cites": [{"t": "箝,谓牵持缄束,令不得脱也。", "b": "《鬼谷子·飞箝注》"}], "words": [{"w": "钳束", "t": "控制;约束"}, {"w": "钳锁", "t": "钳制"}, {"w": "钳塞", "t": "控制阻遏"}, {"w": "钳马", "t": "以钳衔马口使之不能食粟。"}]}, {"meaning": "紧闭。", "cites": [{"t": "箝语烧书。", "b": "《汉书·异姓诸侯王表》"}, {"t": "而君自闭箝天下之口。", "b": "《汉书·爰盎传》"}], "words": [{"w": "钳口侧目", "t": "口不敢言,斜目而视,谓敢怒不敢言"}, {"w": "钳语", "t": "禁止人们相互交谈。指控制言论"}, {"w": "钳默", "t": "闭口不言"}, {"w": "钳结", "t": "钳口结舌。"}]}, {"meaning": "探求;探测。", "cites": [{"t": "箝知休咎。", "b": "《太玄玄莹》。注:“求也。”"}], "words": [{"w": "钳求", "t": "探求"}, {"w": "钳揣", "t": "探测。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1930wx','钻','1','zuān zuàn','钅','10','','[{"pinyin": "zuān", "defs": [{"meaning": "(形声。从金,赞(占)声。古时“钻”、“鑽”是两个字。“钻”本是镊子,又作刑具。现在是“鑽”的简化字。本义:穿孔)。"}, {"meaning": "同本义。", "cites": [{"t": "栌梨曰钻之。", "b": "《尔雅》。按,防有虫于孔,钻视之也。"}, {"t": "钻龟陈卦。", "b": "《荀子·王制》"}, {"t": "钻燧取火。", "b": "《论语》"}], "words": [{"w": "钻一个眼;钻木取火;钻入", "t": "穿入"}, {"w": "钻山", "t": "在山墙上开门或开洞。山墙,指房子两侧的墙,形如山"}, {"w": "钻孔", "t": "用钻头在器物上钻挖圆孔"}, {"w": "钻穴", "t": "钻挖洞穴。指男女非礼的结合"}, {"w": "钻燧", "t": "钻木取火。燧是用来磨擦生热,以取得火种的工具,古分阳燧、木燧两种"}, {"w": "钻火", "t": "钻木取火。"}]}, {"meaning": "钻研,集中精力学习,推究事理。", "cites": [{"t": "仰之弥高,钻之弥坚。", "b": "《论语》"}], "words": [{"w": "钻仰", "t": "探求力索,钻研仰望。用以表示深入研究的意思"}, {"w": "钻味", "t": "深入体会"}, {"w": "钻摩", "t": "指努力研究"}, {"w": "钻厉", "t": "深入研究,发愤勉励。厉通励。"}]}, {"meaning": "投机钻营。", "cites": [{"t": "钱物用多常是解,权门路便不兽钻。", "b": "张鎡《南湖集》"}], "words": [{"w": "钻心", "t": "钻营之心"}, {"w": "钻天", "t": "爬上最高统治阶层"}, {"w": "钻头觅缝", "t": "投机钻营;千方百计力争"}, {"w": "钻天打洞", "t": "极力钻谋,无孔不入。"}]}, {"meaning": "进入。", "cites": [{"t": "还我江山还我权,刀山火海爷敢钻。", "b": "《中国歌谣资料》"}], "words": [{"w": "钻入", "t": "穿入;进入"}, {"w": "钻心", "t": "进入心中"}, {"w": "钻门出户", "t": "走家串房"}, {"w": "钻天令", "t": "升为高官"}, {"w": "钻天杨", "t": "一种落叶乔木,叶子呈三角形"}, {"w": "钻天柳", "t": "一种落叶乔木,叶子呈长形。"}]}, {"meaning": "穿过。", "cites": [{"t": "渐渐地太阳光从浓雾中钻出来了。", "b": "茅盾《雾》"}]}]}, {"pinyin": "zuàn", "defs": [{"meaning": "钻孔的器具。", "cites": [{"t": "钻,所以穿也。从金,赞声。", "b": "《说文》"}, {"t": "钻谓之鍴。", "b": "《方言九》"}, {"t": "其次用钻笮。", "b": "《国语·鲁语》"}, {"t": "钻,穿物之锥也。", "b": "《字汇》"}]}, {"meaning": "钻石的简称。", "cites": [{"t": "钻有五色,金、黑、红者为贵…", "b": "《海国见闻录》"}], "words": [{"w": "十七钻的手表;钻戒", "t": "镶着钻石的戒指"}, {"w": "钻珠", "t": "小而圆的钻石。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1931wx','钾','1','jiǎ','钅','10','','[{"pinyin": "jiǎ", "defs": [{"meaning": "碱金属族的一价金属元素,呈银白色,质软,有光泽,熔点低,比钠更活泼,在空气中很快氧化,与水激烈反应,放出氢气而自行着火,主要用作还原剂及用于合成中 ——元素符号K。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1932wx','铁','1','tiě','钅','10','','[{"pinyin": "tiě", "defs": [{"meaning": "(形声。从金,臷(zhì)声。本义:化学元素。符号Fe。一种很重的可锻、有延展性和有磁性的、主要是两价和三价的金属元素,纯铁为银白色,但在潮湿空气中容易生锈)。"}, {"meaning": "同本义。", "cites": [{"t": "铁,黑金也。", "b": "《说文》"}, {"t": "铁锁长三丈。", "b": "《墨子·备穴》"}, {"t": "邯郸郭纵以冶铁成业。", "b": "《史记·货殖列传》"}], "words": [{"w": "铁冶", "t": "冶铁工场"}, {"w": "铁山", "t": "产铁的矿山"}, {"w": "铁石", "t": "铁与石;铁矿石"}, {"w": "铁锡", "t": "铁和锡"}, {"w": "铁砂", "t": "含铁的矿砂"}, {"w": "铁炭", "t": "铁和炭"}, {"w": "铁皮", "t": "铁的外层"}, {"w": "铁精", "t": "纯铁。"}]}, {"meaning": "铁制的器物。", "cites": [{"t": "柄铁折叠环复", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "铁花", "t": "金属器物的光泽"}, {"w": "铁戒尺", "t": "佛教徒戴在头上的环形物"}, {"w": "铁尺", "t": "铁戒尺;用来体罚的铁板子"}, {"w": "铁锚", "t": "用来作为停船时稳定船身的铁制大钩子"}, {"w": "铁鼓", "t": "铁制的战鼓"}, {"w": "铁绠", "t": "铁索,铁绳"}, {"w": "铁牌", "t": "铁制的牌子"}, {"w": "铁钵", "t": "铁制的钵。僧人化缘求食的用具"}, {"w": "铁钩", "t": "铁制的钩子"}, {"w": "铁箍", "t": "铁制的圆环,用以箍物。如木桶之类可用铁箍箍住,使不松开。"}]}, {"meaning": "指兵器 。", "words": [{"w": "铁蒺藜骨朵", "t": "古代的一种兵器,以铁或硬木制成,为一长棒,顶端为附有铁刺的长圆形头"}, {"w": "铁蒺藜", "t": "军用的铁制三角物,尖刺如蒺藜籽。常布设于地上或浅水中,阻碍人马、车辆行动"}, {"w": "铁兵", "t": "铁制兵器"}, {"w": "铁杖", "t": "铁制的棍棒"}, {"w": "铁衣", "t": "用铁片制成的战衣。"}]}, {"meaning": "赤黑色的马。", "cites": [{"t": "乘玄路,驾铁骊。", "b": "《礼记·月令》"}]}, {"meaning": "古丘名 。春秋时卫地。在今河南濮阳北。", "words": [{"w": "铁力", "t": "复姓"}, {"w": "铁弗", "t": "复姓"}, {"w": "铁伐", "t": "复姓。"}]}, {"meaning": "黑色 。", "words": [{"w": "铁色", "t": "像铁的颜色。即铁灰色"}, {"w": "铁骢", "t": "毛色青黑的马"}, {"w": "铁骊", "t": "毛色青黑如铁的马"}, {"w": "铁连钱", "t": "指马身上黑色的钱形斑点"}, {"w": "铁藓", "t": "黑色苔藓。"}]}, {"meaning": "比喻坚固 。", "words": [{"w": "铁郭", "t": "形容外城坚固如铁"}, {"w": "铁壁", "t": "比喻城壁或屋壁的坚固"}, {"w": "铁纱帽", "t": "比喻稳固的官职"}, {"w": "铁脚板", "t": "形容善于长途行走的脚"}, {"w": "铁屋", "t": "比喻监狱。"}]}, {"meaning": "比喻坚强不屈;强硬 。", "words": [{"w": "铁石", "t": "比喻意志坚强刚毅"}, {"w": "铁誓", "t": "坚定不二、至死不变的誓言"}, {"w": "铁砚未穿", "t": "除非铁砚磨穿,所定志向决不动摇。比喻意志坚定,未达既定目的,决不改变"}, {"w": "铁心肠", "t": "形容意志坚定,不为感情所动。"}]}, {"meaning": "驳不倒的 。", "words": [{"w": "铁的事实", "t": ""}]}, {"meaning": "。", "words": [{"w": "铁雀", "t": ""}]}, {"meaning": "下决心 。", "words": [{"w": "残酷的现实使他铁了心", "t": ""}]}, {"meaning": "板着面孔(表情严肃) 。", "words": [{"w": "他总是铁着脸", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1933wx','铃','1','líng','钅','10','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从金,令声。本义:金属制成的响器。又为打击乐器。形似钟而小)。"}, {"meaning": "同本义。", "cites": [{"t": "大祭祀,鸣铃以应鸡人。", "b": "《周礼·春官·巾车》"}], "words": [{"w": "铃杵", "t": "一种有柄的铃"}, {"w": "铃语", "t": "风铃的声音"}, {"w": "铃铎", "t": "挂在楼阁寺院檐角的铃"}, {"w": "铃铛寿星", "t": "小儿帽子及手镯上的点缀饰品。寿星钉于帽上,铃铛挂于镯上,因此用于譬喻一切零星的点缀物品。"}]}, {"meaning": "铃状物 。 如:铃柝(打更用的梆子);棉铃; 杠铃。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1934wx','铅','1','qiān yán','钅','10','','[{"pinyin": "qiān", "defs": [{"meaning": "青金。", "cites": [{"t": "铅,青石也。", "b": "《说文》"}, {"t": "铅松怪石。", "b": "《书·禹贡》"}, {"t": "或髡钳以鈆杵舂。", "b": "《汉书·江都易王非传》"}, {"t": "药物秘海岳,采铅青溪滨。", "b": "唐·李白《古风五十九首》"}]}, {"meaning": "古时也指锡类。", "cites": [{"t": "莫邪为顿兮,铅刀为銛。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "一种重而柔软、有延展性、可塑性而没有弹性的二价或四价的金属元素,元素符号Pb。原子序数82,刚切割时呈蓝白色,但在潮湿空气中很快失去光泽而变暗灰色,它大多以化合状态存在。", "cites": [{"t": "莫邪为钝兮,铅刀为銛。", "b": "汉·贾谊《吊屈原赋》"}], "words": [{"w": "铅刀", "t": "铅制的刀,不够锋利。比喻才力微薄,有鄙视或自谦之意"}, {"w": "铅汞", "t": "古代炼丹家以铅和汞来提炼药物,服食可以长寿,因此称炼丹为铅汞。"}]}, {"meaning": "铅粉。"}, {"meaning": "古时用以点校书文或绘画的颜料。", "cites": [{"t": "寝则怀铅笔,行则诵文书。", "b": "《东观汉记》"}]}]}, {"pinyin": "yán", "defs": [{"meaning": "遵循,因袭。", "cites": [{"t": "越月逾时,则必反铅过故乡。", "b": "《荀子·礼论》。杨??注:“铅与沿同,循也。”"}]}, {"meaning": "", "cites": [{"t": "铅氏,《华阳国志》云:“江州官族有铅氏。”", "b": "《姓氏寻源》"}]}, {"meaning": "铅山(Yánshān),县名,在江西省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1935wx','缺','1','quē','缶','10','','[{"pinyin": "quē", "defs": [{"meaning": "(形声。从缶(fǒu),夬(guài)声。缶,瓦器。“夬”也有表意作用。水缺为“决”,玉缺为“玦”,器缺为“缺”,都有破损之意。本义:器具破损) 同本义。引申为缺漏而不完整。", "cites": [{"t": "缺,器破也。", "b": "《说文》"}, {"t": "入休乎缺甃之崖。", "b": "《庄子·秋水》"}, {"t": "周室既微,载籍残缺。", "b": "《汉书·艺文志》"}, {"t": "既破我斧,又缺我斨。", "b": "《诗·豳风·破斧》"}], "words": [{"w": "墙缺了一块;缺落", "t": "破损剥落"}, {"w": "缺啮", "t": "折角,破损"}, {"w": "缺坏", "t": "破缺损坏"}, {"w": "缺触", "t": "残缺剥蚀"}, {"w": "缺唇", "t": "又叫“缺嘴”,上唇缺损。一名兔唇"}, {"w": "缺圮", "t": "残缺倒塌。"}]}, {"meaning": "短少;缺乏。", "cites": [{"t": "缺王道之仪。", "b": "《汉书·司马相如传下》"}, {"t": "于此微缺然。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "缺盐;缺油;缺员;缺这少那;缺人;缺月", "t": "月缺,不圆的月亮"}, {"w": "缺势", "t": "缺后角的一种坐垫"}, {"w": "这本书缺两页", "t": ""}]}, {"meaning": "空隙;缺口。", "cites": [{"t": "锋口为缺。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "缺呀", "t": "缺口开张貌。"}]}, {"meaning": "亏缺。", "cites": [{"t": "人有悲欢离合,月有阴晴圆缺,此事古难全。", "b": "宋·苏轼《水调歌头》"}], "words": [{"w": "缺月", "t": "不圆之月"}, {"w": "缺蟾", "t": "缺月。"}]}, {"meaning": "缺陷。引申为遗憾。", "cites": [{"t": "犹欲保残守缺。", "b": "《文选·刘歆·移太常博士书》"}], "words": [{"w": "缺事", "t": "工作上的缺失;感到缺憾的事"}, {"w": "缺限", "t": "缺陷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1936wx','氧','1','yǎng','气','10','','[{"pinyin": "yǎng", "defs": [{"meaning": "一种非金属元素,原子序数8,主要是两价,一般是无色无嗅无味不可燃的双原子气体,稍溶于水,是地球上含量最丰富的元素之一,以游离状态存在于空气中,按体积计,空气含氧达21%,并以化合状态存在于水、大多数普通岩石、矿物(例如氧化物、硅酸盐、碳酸盐),以及多种多样的有机化合物(例如醇、酸、脂肪、碳水化合物、蛋白质) ——元素符号O。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1937wx','氨','1','ān','气','10','','[{"pinyin": "ān", "defs": [{"meaning": "氮和氢的化合物NH3 比空气轻,有极强的刺激性气味,易溶于水,冷却加压下很易冷凝成液体,因此常用液氨蒸发吸热来人工致冷。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1938wx','特','1','tè','牜','10','','[{"pinyin": "tè", "defs": [{"meaning": "(形声。从牛,寺声。本义:雄性的牛马)。"}, {"meaning": "同本义。", "cites": [{"t": "特,朴特,牛父也。", "b": "《说文》"}, {"t": "凡马,特居四之一。", "b": "《周礼·夏官·校人》"}, {"t": "特,牡牛也。", "b": "《玉篇》"}], "words": [{"w": "特处士", "t": "赋予公牛以处士头衔"}, {"w": "特牛", "t": "一头公牛。"}]}, {"meaning": "泛指牛。", "cites": [{"t": "高辛氏人家生一犬,初如小特。", "b": "樊绰《蛮书》"}]}, {"meaning": "三岁兽。", "cites": [{"t": "胡瞻尔庭有县特兮?", "b": "《诗·魏风·伐檀》"}]}, {"meaning": "独特,特异;突出;特别。", "cites": [{"t": "士之特立独行,适于义而已。", "b": "韩愈《伯夷颂》"}, {"t": "何其无特操与?", "b": "《庄子·齐物论》"}, {"t": "然后知是山之特立,不与培塿为类。", "b": "柳宗元《始得西山宴游记》"}, {"t": "臣超区区,特蒙神灵。", "b": "《后汉书·班超传》"}], "words": [{"w": "特达", "t": "特别通晓事理"}, {"w": "特支", "t": "特别支出。源于宋时朝廷发给军士的特别赏赐"}, {"w": "特等;特旨", "t": "特诏;帝王的特别诏令"}, {"w": "特命", "t": "特别命令"}, {"w": "特绝", "t": "卓绝"}, {"w": "特表", "t": "非凡的仪表。"}]}, {"meaning": "单独;单单;特地。", "cites": [{"t": "夫国岂特为车哉?", "b": "《吕氏春秋·君守》"}, {"t": "岂特为宫室哉?", "b": "《吕氏春秋·分职》"}, {"t": "我特以三国城从之。", "b": "《战国策·秦策四》"}, {"t": "使韩信特将北击之。", "b": "《汉书·张良传》"}, {"t": "而彭祖乃今以久特闻。", "b": "《庄子·逍遥游》"}, {"t": "且姑墨、温宿二王特为龟兹所置。", "b": "《后汉书·班超传》"}, {"t": "特怪老人。", "b": "清·周容《芋老人传》"}, {"t": "特赏侍郎。", "b": "清·梁启超《谭嗣同传》"}, {"t": "特为天之所厚。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "特特", "t": "特地"}, {"w": "特骨地", "t": "故意地"}, {"w": "今特汇上;特为此事而来;特加", "t": "特别给与"}, {"w": "特遣;特约;特故", "t": "特意"}, {"w": "特甚", "t": "特别厉害"}, {"w": "特生", "t": "孤独生长,独立生长"}, {"w": "特为", "t": "独个儿干"}, {"w": "特将", "t": "独自统率指挥军队。"}]}, {"meaning": "只,仅,不过。", "cites": [{"t": "特以诈佯为。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "特示故人。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "特自皇古迄今。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "特为变至微。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1939wx','牺','1','xī','牜','10','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从牛,羲声。本义:做祭品用的毛色纯一的牲畜)。"}, {"meaning": "同本义。", "cites": [{"t": "牺,宗庙之牲也。", "b": "《说文》"}, {"t": "今殷民乃攘窃神祇之牺牷牲用。", "b": "《书·微子》。传:“色纯曰牺。”"}, {"t": "共其牺牲。", "b": "《周礼·牧人》。注:“毛羽完具也。”"}, {"t": "宗庙曰刍豢、山川曰牺牲。", "b": "《大戴礼记·曾子大圆》"}, {"t": "自惮其牺也。", "b": "《左传·昭公二十二年》"}, {"t": "牺牲玉帛。(古代祭祀用的祭品。牺牲,名词,古代供祭祀用的牲畜,指猪、牛、羊等。玉,指玉器。帛,丝织品。)", "b": "《左传·庄公十年》"}], "words": [{"w": "牺牛", "t": "古代祭祀用的纯色牛"}, {"w": "牺羊", "t": "古代祭祀用的纯色羊"}, {"w": "牺牢", "t": "供宴飨或祭祀用的牛、羊、猪"}, {"w": "牺宰", "t": "古代祭祀时掌管牺牲的官吏。"}]}, {"meaning": "指伏羲氏。", "cites": [{"t": "于穆二圣,仁等春生,除弃周汉遐轨牺庭。", "b": "《魏书·程骏传》"}], "words": [{"w": "牺年", "t": "伏羲氏之世。借指太平盛世"}, {"w": "牺皇", "t": "羲皇。称伏羲氏。"}]}, {"meaning": "酒樽名(以前读suō,今读xī)。", "cites": [{"t": "牺,酒尊名。", "b": "《集韵》"}], "words": [{"w": "牺人", "t": "官名。专掌供设酒醴的官吏"}, {"w": "牺羽", "t": "古代雕饰于酒樽的禽鸟图案"}, {"w": "牺杓", "t": "瓢的别称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1940wx','造','1','zào','辶','10','','[{"pinyin": "zào", "defs": [{"meaning": "(形声。从辵(chuò),告声。本义:到;往某地去)。"}, {"meaning": "同本义。", "cites": [{"t": "造,就也。", "b": "《说文》"}, {"t": "咸造勿亵在王庭。", "b": "《书·盘庚》"}, {"t": "凡四方之宾 客造焉。", "b": "《周礼·司门》"}, {"t": "造于西阶下。", "b": "《仪礼·士丧礼》"}, {"t": "而造大国之城下。", "b": "《战国策·宋策》"}, {"t": "造饮辄尽。", "b": "陶渊明《五柳先生传》"}, {"t": "明日造朝。", "b": "唐·柳宗元《柳河东集》"}, {"t": "造玉清宫。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "造左公第。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "径造袁所寓之法华寺。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "造劫历世", "t": "佛教语。来到人世间经历一番苦难生活"}, {"w": "造历幻缘", "t": "佛教语。去到人世间经历一番像梦幻一样的情缘"}, {"w": "造适", "t": "寻访"}, {"w": "造胜", "t": "访求胜迹"}, {"w": "造门", "t": "上门;到别人家去。"}]}, {"meaning": "拜访。", "cites": [{"t": "庾公造周伯仁。", "b": "《世说新语·言语》"}], "words": [{"w": "夜造", "t": "深夜前往造访"}, {"w": "造府拜瞻", "t": "敬辞。到府上去拜访"}, {"w": "造请", "t": "前往问候、拜见"}, {"w": "造谒", "t": "造请"}, {"w": "造谢", "t": "登门致谢。"}]}, {"meaning": "假借为“作”,制造;制作。", "cites": [{"t": "复造候风地动仪。", "b": "《后汉书·张衡传》"}, {"t": "王将伐吴,造船于蜀。", "b": "《晋书·吾彦传》"}, {"t": "因造玉清宫,伐山取材,方有人见之。", "b": "《梦溪笔谈·雁荡山》"}], "words": [{"w": "造第", "t": "建造府第"}, {"w": "造恶", "t": "作恶"}, {"w": "造逆", "t": "开始纂逆作乱"}, {"w": "造房子;仿造", "t": "模仿一定的式样制造"}, {"w": "打造", "t": "制造"}, {"w": "建造", "t": "建筑;修建。"}]}, {"meaning": "虚构;伪造。", "cites": [{"t": "我生之初,尚无造。", "b": "《诗·王风》"}], "words": [{"w": "造言生衅", "t": "造谣生事"}, {"w": "造言", "t": "造谣"}, {"w": "造语", "t": "造作谣言"}, {"w": "造言生事", "t": "造设谣言,滋生事端"}, {"w": "捏造", "t": "假造事实。"}]}, {"meaning": "培养;造就;创造。", "cites": [{"t": "屈原造为宪令。", "b": "《史记·屈原贾生列传》"}, {"t": "天造草昧。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "民国肇造。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "创造;造士", "t": "造就人才"}, {"w": "造字", "t": "创造文字"}, {"w": "造怀", "t": "抒写胸怀。"}]}, {"meaning": "撰写;汇集。", "cites": [{"t": "非禹,益不不能行远《山海》不造。", "b": "王充《论衡》"}], "words": [{"w": "造册", "t": "编制簿籍"}, {"w": "造述", "t": "著述;著作。"}]}, {"meaning": "制定。", "cites": [{"t": "怀王使屈原造为宪令。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "造施", "t": "制订并实施"}, {"w": "造律", "t": "制订律令"}, {"w": "造设", "t": "制订建立。"}]}, {"meaning": "建立。", "cites": [{"t": "遂迁许都,造我京畿。", "b": "《三国志·武帝纪》"}], "words": [{"w": "造立", "t": "建筑;建造"}, {"w": "造邦", "t": "创立国家"}, {"w": "造国", "t": "新创立的国家"}, {"w": "造谊", "t": "创立新义"}, {"w": "造说", "t": "立说。"}]}, {"meaning": "成就。", "cites": [{"t": "肆成人有德,小子有造", "b": "《诗·大雅·思齐》"}], "words": [{"w": "造士", "t": "古时称学术道业已有成就的人"}, {"w": "造秀", "t": "成绩优异"}, {"w": "造人", "t": "学业有成就之人。"}]}, {"meaning": "时代。", "cites": [{"t": "公侯之有冠礼也,夏之末造也。", "b": "《仪礼·士冠礼》"}]}, {"meaning": "忽然;仓卒。", "cites": [{"t": "造受命于君前,则书于笏。", "b": "《礼记》"}, {"t": "景公造然变色。", "b": "《韩非子·难二》"}], "words": [{"w": "造此", "t": "仓猝,匆忙"}, {"w": "造子", "t": "一会儿。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1941wx','乘','1','chéng shèng','丿','10','','[{"pinyin": "chéng", "defs": [{"meaning": "(会意。甲骨文字形,从大(人)从木,表示人爬在树上。“大”象“人”正面。本义:登,升)。"}, {"meaning": "同本义。", "cites": [{"t": "乘,升也。", "b": "《玉篇》"}, {"t": "亟其乘屋。", "b": "《诗·豳风·七月》"}, {"t": "却叔虎将乘城。", "b": "《国语·晋语一》"}, {"t": "淮阴侯复乘之。", "b": "《史记·高帝纪》"}, {"t": "俱乘高台。", "b": "《列子·黄帝》"}], "words": [{"w": "乘槎", "t": "神话中指乘木排上天"}, {"w": "乘城", "t": "登城;守城"}, {"w": "乘屋", "t": "登上屋顶。"}]}, {"meaning": "骑;坐。", "cites": [{"t": "昔人已乘黄鹤去,此地空余黄鹤楼。", "b": "唐·崔颢《黄鹤楼》"}, {"t": "公与之乘。战于长勺。", "b": "《左传·庄公十年》"}], "words": [{"w": "乘车;乘舟", "t": "乘船"}, {"w": "乘奔", "t": "乘坐奔驰的快马"}, {"w": "乘轩", "t": "乘坐大夫的车子"}, {"w": "乘桴", "t": "乘坐竹木小筏以代舟船。后用以比喻避世。"}]}, {"meaning": "驱马驾车;驾驭。", "cites": [{"t": "服牛乘马。", "b": "《易·系辞下》"}, {"t": "乘肥马,衣轻裘。", "b": "《论语·雍也》"}], "words": [{"w": "乘驭", "t": "驱使车马行进;驱使;役使"}, {"w": "乘云", "t": "驾云;驭云"}, {"w": "乘马", "t": "驾马,用马驾车。"}]}, {"meaning": "趁着;利用。", "cites": [{"t": "乘今之时,因无之助。", "b": "汉·贾谊《治安策》"}, {"t": "其锋不可犯,而其未可乘。", "b": "宋·苏轼《留侯论》"}, {"t": "于是乘其厉声以呵,则噪而相逐。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "乘衅", "t": "乘机;趁空子"}, {"w": "乘闲", "t": "趁着空闲"}, {"w": "乘空", "t": "趁着空闲"}, {"w": "乘胜", "t": "趁着胜利的形势。"}]}, {"meaning": "凭持;依仗。", "cites": [{"t": "因利乘便。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "乘利席胜", "t": "凭借着胜利的形势"}, {"w": "乘正", "t": "依据正道"}, {"w": "乘利", "t": "凭借有利的形势。"}]}, {"meaning": "冒着。", "cites": [{"t": "自京师乘风雪,历齐河、长清…至于泰安。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "交错(出现)。", "cites": [{"t": "兵旱相乘,天下大屈。", "b": "汉·贾谊《论积贮疏》"}, {"t": "顾自民国肇造,变乱纷乘。", "b": "孙文《黄花冈七十二烈士事略·序》"}]}]}, {"pinyin": "shèng", "defs": [{"meaning": "用以指车兵。", "cites": [{"t": "而卒乘辑睦,事不奸矣。", "b": "《左传》"}]}, {"meaning": "春秋时晋国的史书。后用以称一般的史书。", "cites": [{"t": "晋之《乘》,楚之《梼杌》,鲁之《春秋》,一也。", "b": "《孟子》"}], "words": [{"w": "乘籍", "t": "史书。"}]}, {"meaning": "古时计物以四为乘。", "cites": [{"t": "郑商人弦高将市于周,遇之,以乘韦先牛十二犒师。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "乘处", "t": "四个同处"}, {"w": "乘壶", "t": "四个壶"}, {"w": "乘禽", "t": "成双而群居的鸟。"}]}, {"meaning": "用以计算车子。", "cites": [{"t": "公车千乘。", "b": "《诗·鲁颂·閟宫》"}, {"t": "驾我乘马。", "b": "《诗·陈风·株林》"}, {"t": "晋师乘和。", "b": "《左传·成公十二年》"}, {"t": "于是为长安君约车百乘。", "b": "《战国策·赵策》"}, {"t": "孟尝君予车五十乘,金五百斤,西游于梁。", "b": "《战国策·齐策》"}], "words": [{"w": "乘丘", "t": "形同马车的土丘"}, {"w": "乘白", "t": "古代指战车和军旗"}, {"w": "乘车", "t": "安车;古代行丧葬礼所用的魂车"}, {"w": "乘马", "t": "四匹马拉的车"}, {"w": "乘传", "t": "古代驿站用的四匹下等马拉的车子"}, {"w": "乘广", "t": "春秋时楚王或主帅率领的兵车"}, {"w": "乘路", "t": "即王路。周代天子所乘之车。"}]}, {"meaning": "用以计算马。四匹。", "cites": [{"t": "路车乘马。", "b": "《诗·小雅·采菽》"}, {"t": "乘马在厩。", "b": "《诗·小雅·鸳鸯》"}, {"t": "陈文子有马十乘。", "b": "《论语》。刘宝楠正义:“一乘是四匹马。”"}], "words": [{"w": "乘黄", "t": "四匹黄色的马"}, {"w": "乘黄朱", "t": "四匹黄毛朱鬃的马"}, {"w": "乘鸨", "t": "四匹黑白杂毛的马。"}]}, {"meaning": "用以计算船只。", "cites": [{"t": "舫千余乘。", "b": "《宋书》"}]}, {"meaning": "用以计算田地、区域的单位,犹丘。"}, {"meaning": "用以计算轿子、梯子等。", "cites": [{"t": "一乘素轿,将二姐儿抬来。", "b": "《红楼梦》"}]}, {"meaning": "军赋的计算单位。古井田制,九夫为井,十六井为丘,四丘为甸,一甸土地所出的军赋叫乘(包括战车、甲士和步卒)。", "cites": [{"t": "且鲁赋八百乘,君之贰也!", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1942wx','敌','1','dí','攵','10','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从攴(pū),啇(dí)声。本义:匹敌;对等)。"}, {"meaning": "同本义。", "cites": [{"t": "敌,仇也。", "b": "《说文》"}, {"t": "敌,匹也。", "b": "《尔雅》"}, {"t": "四国之兵敌。", "b": "《战国策·秦策》。注:“强弱等也。”"}, {"t": "且夫自敌以下。", "b": "《国语·楚语》"}, {"t": "敌国宾至。", "b": "《国语·周语》"}, {"t": "敌则能战之。", "b": "《孙子·谋攻》"}], "words": [{"w": "试看天下谁能敌;敌体", "t": "彼此地位相等,不分上下"}, {"w": "敌礼", "t": "平等的礼节"}, {"w": "匹敌", "t": "谓才艺相当"}, {"w": "势均力敌", "t": ""}]}, {"meaning": "抵抗;抵挡。", "cites": [{"t": "(司马懿)乃魏之名将,恐汝不能敌之。", "b": "《三国演义》"}], "words": [{"w": "敌不住;寡不敌众", "t": ""}]}, {"meaning": "攻击。", "cites": [{"t": "屠大窘,恐前后受其敌。", "b": "《聊斋志异·狼三则》"}]}, {"meaning": "仇敌;敌人。", "cites": [{"t": "秦人开关延敌。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "政敌;天敌;敌不可假", "t": "不可宽容敌人"}, {"w": "敌垒", "t": "敌人的营垒"}, {"w": "敌特;敌探", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1943wx','秤','1','chèng chēng','禾','10','','[{"pinyin": "chèng", "defs": [{"meaning": "利用杠杆原理量物体轻重的器具", "words": [{"w": "秤权", "t": "秤锤"}, {"w": "秤等", "t": "用秤或戥子测量轻重,掂量"}]}, {"meaning": "中国古代重量单位。十五斤为一秤。", "cites": [{"t": "俺有敕命一道,封宋江为镇国大将军,总领辽兵大元帅,赐与金一提,银一秤,权当信物。", "b": "《水浒传》"}]}]}, {"pinyin": "chēng", "defs": [{"meaning": "用秤量物之轻重。", "words": [{"w": "秤量", "t": "用秤衡计物体重量"}, {"w": "秤薪量水", "t": "谓勤俭持家"}]}, {"meaning": "权衡;衡量", "words": [{"w": "秤停", "t": "衡量斟酌"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1944wx','租','1','zū','禾','10','','[{"pinyin": "zū", "defs": [{"meaning": "(形声。从禾,且(jū)声。从禾,与谷物有关。本义:田赋,征收的农产品,又指按田地征收的捐税)。"}, {"meaning": "同本义。", "cites": [{"t": "租,田赋也。", "b": "《说文》"}, {"t": "租,税也。", "b": "《广雅》"}, {"t": "敛财曰赋,敛谷曰税,田税曰租。", "b": "《急就篇》"}, {"t": "租籍者,所以强求也。", "b": "《管子·国蓄》"}, {"t": "其赐天下民今年田租之半。", "b": "《汉书·文帝纪》"}, {"t": "县官急索租。", "b": "唐·杜甫《兵车行》"}, {"t": "当其租入。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "租更", "t": "指田赋和践更的钱"}, {"w": "租委", "t": "输纳的田赋"}, {"w": "租刍", "t": "田赋"}, {"w": "租输", "t": "上缴的田赋"}, {"w": "租限", "t": "旧时地主规定佃户交租的期限。"}]}, {"meaning": "赋税。", "cites": [{"t": "关市之租,府库之征,粟什一。", "b": "《管子》"}, {"t": "李牧为赵将居边,军市之租,皆自用响士。", "b": "《史记·张释之冯唐列传》"}, {"t": "使吏致千金与市租,请以奉宾客。", "b": "《晏子春秋》"}], "words": [{"w": "租入", "t": "缴纳的赋税"}, {"w": "租民", "t": "纳税的人"}, {"w": "租车", "t": "输纳租赋的车辆"}, {"w": "租责", "t": "所欠赋税。"}]}, {"meaning": "租赁;租用。", "cites": [{"t": "租户于主有连姻。", "b": "《宋史·刘宰传》"}], "words": [{"w": "租头", "t": "租金,租钱"}, {"w": "租摺", "t": "租约"}, {"w": "租费(又叫“租金”,“租银”)租种(承租他人的土地来耕种)", "t": ""}]}, {"meaning": "征收租税。", "cites": [{"t": "募民耕滦河旷地,十年始租。", "b": "《辽史·食货志》"}]}, {"meaning": "积聚。", "cites": [{"t": "予所蓄租,予口卒暗。", "b": "《诗·豳风·鸱鴞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1945wx','积','1','jī','禾','10','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从禾,责声。从“禾”,表示与农作物有关。本义:堆积谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "积,聚也。", "b": "《说文》。按,禾谷之聚曰积。"}, {"t": "令野修道委积。", "b": "《周礼·大司徒》。注:“少曰委,多曰积。”"}, {"t": "掌邦之委积。", "b": "《周礼·遗人》。疏:“三十里言委,五十里言积。”"}, {"t": "故人主积其食,守其用。", "b": "《盐铁论·错币》"}], "words": [{"w": "积谷", "t": "存积米谷以备灾荒"}, {"w": "积居", "t": "聚积;囤积"}, {"w": "积仓", "t": "贮存谷物的粮仓。"}]}, {"meaning": "累积;堆叠。", "cites": [{"t": "积土成山,风雨兴焉。(积土成为高山,风雨就能从山里兴起,即指积土成山能使气侯发生变化而兴风作雨。兴,起,产生。焉,于是,从这里。)", "b": "《荀子·劝学》"}, {"t": "积水成渊。", "b": ""}, {"t": "积薪其中。", "b": "《聊斋志异·狼三则》"}, {"t": "转视积薪后。", "b": ""}, {"t": "大风扬积雪。", "b": "清·姚鼐《登泰山记》"}, {"t": "积善成德。", "b": "《荀子·劝学》"}, {"t": "能已积热。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "祖父积子孙弃者。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "积石", "t": "堆聚的石头"}, {"w": "积委", "t": "累聚,储存"}, {"w": "积威", "t": "累积而成的威势"}, {"w": "积重", "t": "财物的累聚、蓄积"}, {"w": "积气", "t": "积聚的气。"}]}, {"meaning": "蕴积,积蓄。", "cites": [{"t": "商贾以币之变多积货逐利。", "b": "《史记·平准书》"}, {"t": "乃积乃仓。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "积中", "t": "蕴积于心中"}, {"w": "积伐", "t": "蕴蓄才能并自我夸耀"}, {"w": "积志", "t": "蓄志,夙愿。"}]}, {"meaning": "滞留。", "cites": [{"t": "天道运而无所积。", "b": "《庄子·无道》"}], "words": [{"w": "积污", "t": "积滞污秽"}, {"w": "积塞", "t": "积滞堵塞"}, {"w": "积抱", "t": "郁积的怀抱"}, {"w": "积忿", "t": "忿恨郁积于心"}, {"w": "积怒", "t": ""}]}, {"meaning": "累计。", "cites": [{"t": "积于今。(算到现在。积,累计。)", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "指贮积起来的钱物等。", "cites": [{"t": "主国五积。", "b": "《周礼·司仪》"}, {"t": "共其牢礼积膳之牛。", "b": "《周礼·牢人》"}, {"t": "居则具一日之积。", "b": "《左传·僖公三十三年》。注:“刍米禾薪。”"}, {"t": "完者,使守积。", "b": "《汉书·刑法志》"}, {"t": "士卒死伤如积。", "b": "司马迁《报任安书》"}, {"t": "畜积足恃。(积,动词用作名词,积蓄的东西。蓄同积。)", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "积陈", "t": "蓄积陈粮"}, {"w": "积滞", "t": "滞积的水流"}, {"w": "积实", "t": "指谷粟财货等"}, {"w": "积委", "t": "指积贮的财物"}, {"w": "积苏", "t": "聚积的柴草。"}]}, {"meaning": "衣裙的褶子。", "cites": [{"t": "襞积褰绉,纡徐委曲。", "b": "《史记·司马相如列传》"}, {"t": "美襞积以酷烈兮,允麈邈而难。", "b": "《文选·张衡·思玄赋》"}]}, {"meaning": "功劳。", "cites": [{"t": "积厚者流泽广,积薄者流泽狭也。", "b": "《荀子·礼论》"}, {"t": "考积幽穷。", "b": "《汉·北海相景君碑》"}]}, {"meaning": "长久。", "cites": [{"t": "所居之官辄积年不徙。", "b": "《后汉书》"}], "words": [{"w": "积日累岁", "t": "形容时间长久"}, {"w": "积祖", "t": "祖祖辈辈;一贯"}, {"w": "积世", "t": "累世,历代"}, {"w": "积雨", "t": "久雨。"}]}, {"meaning": "习惯的;积久渐成的。", "cites": [{"t": "常俗生于积习。", "b": "汉·蔡邕《述行赋》"}], "words": [{"w": "积窃", "t": "惯偷"}, {"w": "积贼", "t": "惯偷"}, {"w": "积悃", "t": "久积的诚挚之心"}, {"w": "积赌", "t": "长期赌博;老赌客。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1946wx','秧','1','yāng','禾','10','','[{"pinyin": "yāng", "defs": [{"meaning": "(形声。从禾,央声。本义:植物的幼苗)。"}, {"meaning": "稻的初生幼苗。", "cites": [{"t": "秧,禾若秧穰也。", "b": "《说文》。谓秆上皮葳蕤之状。"}, {"t": "秧,今俗谓稻之初生者曰秧。", "b": "清·段玉裁《说文解字注》"}], "words": [{"w": "秧信", "t": "谓可插秧的信息"}, {"w": "秧秧", "t": "稻苗茂密貌"}, {"w": "秧针", "t": "指水稻秧苗的叶尖如针"}, {"w": "秧马", "t": "古代农民拔秧时所坐的器具。"}]}, {"meaning": "泛指草木初生可以移植的幼苗。", "cites": [{"t": "秧,今谓苗初生者曰秧。", "b": "清·朱骏声《说文通训定声》"}], "words": [{"w": "桑秧;松秧;菜秧,瓜秧;树秧", "t": ""}]}, {"meaning": "插。", "cites": [{"t": "唤客煎茶山店远,看人秧稻午风凉。", "b": "黄庭坚《新喻道中寄元明》"}], "words": [{"w": "秧稻", "t": "犹育稻。"}]}, {"meaning": "泛指栽种。", "cites": [{"t": "要秧豆角,可以给你留条田塍。", "b": "周立波《山乡巨变》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1947wx','秩','1','zhì','禾','10','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从禾,失声。本义:聚积)。"}, {"meaning": "同本义。", "cites": [{"t": "秩,积也。", "b": "《说文》"}, {"t": "大合百县之秩刍。", "b": "《礼记·月令》"}, {"t": "九十日有秩。", "b": "《礼记·王制》"}, {"t": "故人君御谷物之秩相胜,而操事于其不平之间。", "b": "《管子》"}], "words": [{"w": "秩秩", "t": "积聚的样子。"}]}, {"meaning": "按次序排列。", "cites": [{"t": "天秩有理。", "b": "《书·皋陶谟》"}]}, {"meaning": "祭祀。", "cites": [{"t": "望秩于山川。", "b": "《书·舜典》"}], "words": [{"w": "秩望", "t": "望祭,远祭。"}]}, {"meaning": "秩序;次序。", "cites": [{"t": "秩,次也。", "b": "《广雅》"}, {"t": "秩,序也。", "b": "《释言》"}, {"t": "寅宾出日,平秩东作。", "b": "《书·尧典》"}, {"t": "贱者咸得秩进。", "b": "《汉书·谷永传》"}], "words": [{"w": "秩进", "t": "依次进用"}, {"w": "秩次", "t": "次序,指官阶的高下"}, {"w": "秩叙", "t": "次序,次第;轮班宿卫的次序"}, {"w": "秩然", "t": "秩序井然"}, {"w": "秩如", "t": "条理井然貌。"}]}, {"meaning": "官吏的俸禄。", "cites": [{"t": "行其秩叙。", "b": "《周礼·宫伯》。注:“禄禀也。”"}, {"t": "而收膳夫之秩。", "b": "《左传·庄公十九年》。注:“禄也,调谷也。”"}, {"t": "官人益秩,庶人益禄。", "b": "《荀子·强国》"}], "words": [{"w": "显秩", "t": "高官厚禄"}, {"w": "食秩", "t": "靠领取薪俸为生"}, {"w": "秩服", "t": "爵禄与服饰的等级"}, {"w": "秩米", "t": "官吏的俸食"}, {"w": "秩俸", "t": "俸禄。"}]}, {"meaning": "官吏的职位或品级。", "cites": [{"t": "教之防利,委之常秩。", "b": "《左传·文公六年》"}], "words": [{"w": "秩分", "t": "官位名分"}, {"w": "秩位", "t": "犹职位"}, {"w": "秩宗", "t": "古代掌宗庙祭祀的官"}, {"w": "秩望", "t": "官位和声望"}, {"w": "秩訾", "t": "官职与钱财"}, {"w": "秩满", "t": "官吏任期届满"}, {"w": "秩礼", "t": "古代辩上下、贵贱之礼。"}]}, {"meaning": "常态。", "cites": [{"t": "秩,常也。", "b": "《尔雅》"}, {"t": "九十日月秩。", "b": "《礼记》。郑玄注:“秩,常也,有常膳。”"}, {"t": "是曰既醉,不知其秩。", "b": "《诗·小雅·宾之初筵》"}]}, {"meaning": "礼器爵的等级次第。", "cites": [{"t": "行其秩叙。", "b": "《周礼·天官·宫伯》"}, {"t": "衣服礼秩如适。", "b": "《左传·庄公八年》"}, {"t": "天子秩而祭之。", "b": "《公羊传·僖公三十一年》"}]}, {"meaning": "十年为一秩。十年。", "cites": [{"t": "已开第七秩,饱食仍安眼。", "b": "白居易《思旧》"}], "words": [{"w": "秩官", "t": "常设之官"}, {"w": "秩酒", "t": "按常规赐与老臣的酒"}, {"w": "秩膳", "t": "常备精美之食"}, {"w": "秩叙", "t": "正常的次序"}, {"w": "秩薪", "t": "按规定数量交给官家的木柴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1948wx','称','1','chèn chēng chèng','禾','10','','[{"pinyin": "chèn", "defs": [{"meaning": "符合,相当。", "cites": [{"t": "令作诗,不能称前时之闻。", "b": "宋·王安石《伤仲永》"}, {"t": "薄罚不为慈,诛严不为戾,称俗而行也。", "b": "《韩非子·王蠹》"}, {"t": "夫才德不称,固自知之矣。", "b": "宗臣《报刘一丈书》"}], "words": [{"w": "对称;相称;称合", "t": "相当"}, {"w": "称任", "t": "称职,犹胜任"}, {"w": "称位", "t": "与职位相符。"}]}]}, {"pinyin": "chēng", "defs": [{"meaning": "(形声。从禾,爯(chēng)声。(chèng)本义:称量物体轻重的器具。这个意义后来写作“秤”。又指称量)。"}, {"meaning": "测定重量。", "cites": [{"t": "苦称量之不审兮。", "b": "《楚辞·惜誓》。注:“称所以知轻重。”"}]}, {"meaning": "叫做;称呼;号称;把…说成。", "cites": [{"t": "称帝而治。", "b": "《战国策·秦策》"}, {"t": "幸蒙大恩,赐号称王。", "b": "《汉书·李广苏建传》"}, {"t": "马伶,名锦,字云将,其先西域人,当时犹称马回回云。", "b": "清·侯方域《马伶传》"}], "words": [{"w": "自称;通称;称名", "t": "称呼名字"}, {"w": "称作", "t": "叫做"}, {"w": "统称", "t": "总起来叫"}, {"w": "称讳", "t": "称呼名字"}, {"w": "称孤", "t": "称王,称帝。"}]}, {"meaning": "述说;声称。", "cites": [{"t": "旄期称道不乱者。", "b": "《礼记·射义》"}, {"t": "知其不足称也。", "b": "《国语·晋语》"}, {"t": "手把文书口称敕。", "b": "唐·白居易《卖炭翁》"}, {"t": "今诚以吾众诈自称公子扶苏、项燕。", "b": "《史记·陈涉世家》"}], "words": [{"w": "口称", "t": "口头上说"}, {"w": "宣称", "t": "声称。"}]}, {"meaning": "举起。", "cites": [{"t": "称彼兕觥。", "b": "《诗·豳风·七月》"}, {"t": "称尔戈,比尔干,立尔矛。", "b": "《书·收誓》"}, {"t": "元祀惟称。", "b": "张衡《东京赋》。注:“皆训举也。”"}], "words": [{"w": "称觥", "t": "举杯祝酒"}, {"w": "称觞", "t": "举杯敬酒。"}]}, {"meaning": "称赞,赞扬。", "cites": [{"t": "禹称善人,不善人远。", "b": "《左传·宣公十六年》"}, {"t": "使人高贤称誉己者,心之力也。", "b": "《淮南子·人间》"}, {"t": "称誉者登进,忤恨者诛伤。", "b": "《汉书·刘向传》"}, {"t": "将军向宠…晓畅军事,尝用于昔日,先帝称之曰能。", "b": "诸葛亮《出师表》"}, {"t": "近年共称柳敬亭之说书。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "称扬", "t": "称赞,赞许"}, {"w": "称赏不已", "t": "连连称赞"}, {"w": "称奖", "t": "称赞夸奖。"}]}, {"meaning": "举事,领兵造反。", "cites": [{"t": "敢行称乱。", "b": "《书·汤誓》"}, {"t": "而称兵以害我。", "b": "《左传·襄公二十七年》"}, {"t": "不可以称兵。", "b": "《吕氏春秋·孟春》"}], "words": [{"w": "称乱", "t": "举兵作乱。"}]}, {"meaning": "举荐。", "cites": [{"t": "繁称文辞,天下不治。", "b": "《战国策·秦策》"}], "words": [{"w": "称贤", "t": "举用贤能"}, {"w": "称荐", "t": "举荐。"}]}]}, {"pinyin": "chèng", "defs": [{"meaning": "(称为“稱”的简化字) 测定物体轻重的器具,后作“秤”。", "cites": [{"t": "称,铨也。", "b": "《说文》"}, {"t": "角斗称。", "b": "《淮南子·时则》。注;“量器也。”"}], "words": [{"w": "过称", "t": "用秤量。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1949wx','秘','1','bì mì','禾','10','','[{"pinyin": "bì", "defs": [{"meaning": "秘鲁的简称。"}]}, {"pinyin": "mì", "defs": [{"meaning": "(形声。从禾,必(bì)声。 本义:一种香草)。"}, {"meaning": "不可测知;不公开。", "cites": [{"t": "祕,神也。从示,必声。", "b": "《说文》"}, {"t": "祕舞更奏。", "b": "张衡《西京赋》"}, {"t": "祕器。", "b": "《后汉书·袁安传》。注:“棺也。”"}, {"t": "祕宝。", "b": "《后汉书·班彪传》。传:“河图之属。”"}, {"t": "祕经。", "b": "《后汉书·苏竟传》。注:“图纬书也。”"}, {"t": "其事秘,世莫知也。", "b": "《史记·武帝本纪》"}], "words": [{"w": "秘箓", "t": "秘文"}, {"w": "秘法", "t": "秘术,秘密的方法"}, {"w": "秘狱", "t": "也称掖庭狱,汉代专指幽囚罪人于皇宫掖庭而不作公开审理的监狱。"}]}, {"meaning": "稀奇,世上少有。", "cites": [{"t": "博学强记,多奇篇秘籍。", "b": "《唐诗纪事·段成式》"}], "words": [{"w": "秘怪", "t": "神奇怪异"}, {"w": "秘珍", "t": "罕见珍品"}, {"w": "秘异", "t": "奇异"}, {"w": "秘籍", "t": "珍贵罕见的书籍"}, {"w": "秘宝", "t": "不常见的珍异宝物。"}]}, {"meaning": "隐藏;保守秘密。", "cites": [{"t": "丞相斯为上崩在外,恐诸公子及天下有变,乃秘之,不发表。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "秘惜", "t": "隐藏珍惜,不以示人"}, {"w": "秘郁", "t": "隐秘,隐藏"}, {"w": "秘丘", "t": "山林之所,隐居之处。"}]}, {"meaning": "秘密、奥妙的事物。", "cites": [{"t": "而此秘未睹。", "b": "《宋书·谢灵运传论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1950wx','透','1','tòu','辶','10','','[{"pinyin": "tòu", "defs": [{"meaning": "(形声。从辵,秀声。本义:跳,跳跃)。"}, {"meaning": "同本义。", "cites": [{"t": "透,跳也。", "b": "《说文新附》"}, {"t": "妃知不免,乃透井死。", "b": "《南史·后妃传下》"}, {"t": "或群跳而电透。", "b": "《文选·王廷寿王孙赋》"}, {"t": "事穷奔透,自然沈溺。", "b": "《南齐书·垣崇祖传》"}], "words": [{"w": "透索", "t": "跳索的游戏"}, {"w": "透掷", "t": "跳跃"}, {"w": "透水", "t": "跳水"}, {"w": "透井", "t": "跳井。"}]}, {"meaning": "穿过,透过。", "cites": [{"t": "渐渐透出。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "透渡", "t": "乘渡船过河"}, {"w": "透眼儿", "t": "小洞"}, {"w": "透映", "t": "渗透并反映。"}]}, {"meaning": "更加。", "cites": [{"t": "他贩来的便宜,就透便宜的卖了。", "b": "《二十年目睹之怪现状》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1951wx','笔','1','bǐ','毛','10','','[{"pinyin": "bǐ", "defs": [{"meaning": "(会意。从竹,从聿。“聿”(yù),是“笔”的本字,小篆象以手执笔。古时毛笔笔杆都是以竹制成,故从竹。简化字“笔”,“从竹从毛”会意,指旧时用的毛笔。此字最早见于北齐隽修罗碑,是六朝时的俗字。也见于《集韵》。本义:毛笔)。"}, {"meaning": "同本义。", "cites": [{"t": "筆,秦谓之筆。从聿从竹。", "b": "《说文》。按,此秦制字。秦以竹为之,加竹。"}, {"t": "史载笔,士载言。", "b": "《礼记·曲礼》"}, {"t": "不能竟书而搁笔。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "毛笔;钢笔;圆珠笔;笔削", "t": "修改文章"}, {"w": "笔帕之敬", "t": "雅洁的礼品"}, {"w": "笔楮难穷", "t": "文字难以充分表达。楮:纸的代称。"}]}, {"meaning": "笔法。曲笔,伏笔。", "cites": [{"t": "以细笔钩勒形廓者也。", "b": "蔡元培《图画》"}]}, {"meaning": "书写;记载。", "cites": [{"t": "至于为《春秋》,笔则笔,削则削,子夏之徒不能赞一辞。", "b": "《史记·孔子世家》"}], "words": [{"w": "代笔;笔资", "t": "笔头上的功夫"}, {"w": "笔吏", "t": "专门抄写文字的小吏。"}]}, {"meaning": "用于款项、书画的量,如:一笔款;三笔账;写得一笔好字。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1952wx','笑','1','xiào','竹','10','','[{"pinyin": "xiào", "defs": [{"meaning": "(会意。从竹,从夭。杨承庆曰,“竹得风其体夭屈,如人之笑”。字或从竹,从夭。本义:因喜悦开颜或出声)。"}, {"meaning": "同本义。", "cites": [{"t": "笑,喜也。", "b": "《说文》。杨承庆曰:“竹得风,其体夭屈,如人之笑也。李阳冰刊定说文从之。”"}, {"t": "竹为乐器,君子乐然后笑也。", "b": "《字林》。朱骏声曰:“此字古皆从犬,本义犬狎人声也。从犬,箾省声。”"}, {"t": "一握为笑。", "b": "《易·萃》"}, {"t": "载笑载言。", "b": "《诗·卫风·氓》"}, {"t": "言笑晏晏。", "b": ""}, {"t": "两小儿笑曰。", "b": "《列子·汤问》"}, {"t": "乐然后笑,人不厌其笑。", "b": "《论语·宪问》"}, {"t": "止增笑耳。", "b": "《聊斋志异·狼三则》"}, {"t": "笑而止之。", "b": "《列子·汤问》"}, {"t": "笑而不顾。", "b": "清·周容《芋老人传》"}], "words": [{"w": "笑唏唏", "t": "笑嘻嘻"}, {"w": "笑咍咍", "t": "大声地笑"}, {"w": "笑浪", "t": "无拘束地大笑"}, {"w": "笑面夜叉", "t": "外貌和气、心地狠毒的人。"}]}, {"meaning": "讥笑;嘲笑。", "cites": [{"t": "顾我则笑。", "b": "《诗·邶风·终风》"}, {"t": "以五十步笑百步,则何如?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "笑端", "t": "笑柄"}, {"w": "笑骂从汝", "t": "我行我素,不顾他人饥笑责骂"}, {"w": "笑弄", "t": "讥笑;嘲弄"}, {"w": "笑侮", "t": "嘲笑戏弄。"}]}, {"meaning": "玩笑;逗乐。", "cites": [{"t": "勿以为笑。", "b": "《诗·大雅·板》"}], "words": [{"w": "笑嗷", "t": "喜笑;玩闹"}, {"w": "笑乐院本", "t": "戏曲演出在正戏前加演的小戏"}, {"w": "笑耍头回", "t": "宋元时说书人在开讲正书前,先讲一个小故事作引子。"}]}, {"meaning": "比喻花朵开放。", "cites": [{"t": "露浓晞晚笑,风劲浅残香。", "b": "唐太宗《赋得残菊花》"}], "words": [{"w": "笑笑", "t": "花盛开的样子"}, {"w": "笑靥金", "t": "菊花的别称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1953wx','笋','1','sǔn','竹','10','','[{"pinyin": "sǔn", "defs": [{"meaning": "(形声。从竹,尹(yǐn)声。本义:竹笋)。"}, {"meaning": "竹子初从土里长出的嫩芽,味鲜美,可以做菜,也叫“竹笋”。", "cites": [{"t": "筍,竹胎也。", "b": "《说文》。字亦作笋。"}, {"t": "绚笋及蒲。", "b": "《诗·大雅·韩奕》"}, {"t": "苞笋抽节。", "b": "左思《吴都赋》"}, {"t": "如筀竹笋,有二月生者,有三四月生者,有五月方生者谓之晚筀。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "笋玉", "t": "喻指女人的手指"}, {"w": "笋剥", "t": "像剥笋似地脱掉,剥光"}, {"w": "笋枯", "t": "笋干"}, {"w": "笋鞭", "t": "竹的地下茎"}, {"w": "笋尖", "t": "笋的尖嫩部分"}, {"w": "笋衣", "t": "笋壳。"}]}, {"meaning": "竹的青皮。", "cites": [{"t": "敷重笋席。", "b": "《书·顾命》。郑注:“析竹青皮也。”"}, {"t": "如竹箭之有筠也。", "b": "《礼记·礼器》"}], "words": [{"w": "笋席", "t": "用篾青所编的竹席"}, {"w": "笋鞋", "t": "以竹皮或笋壳做成的鞋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1954wx','债','1','zhài','亻','10','','[{"pinyin": "zhài", "defs": [{"meaning": "(形声。从人,责声。本作“责”,“债”为后起字。本义:欠别人的钱财)。"}, {"meaning": "同本义。", "cites": [{"t": "债,债负也。", "b": "《说文新附》"}, {"t": "于是有买田宅,鬻子孙,以偿债者矣。", "b": "《汉书·论贵粟疏》"}], "words": [{"w": "债壳子", "t": "负了一身债的穷官"}, {"w": "债赖", "t": "债权人否认借债给他人"}, {"w": "债累", "t": "负债;债务"}, {"w": "债桩", "t": "比喻被债务包围的人"}, {"w": "内债", "t": "国家向本国公民借的债"}, {"w": "外债", "t": "国家向外国借的债"}, {"w": "公债", "t": "国家向公民或向外国借的债"}, {"w": "举债", "t": "借债"}, {"w": "背债", "t": "欠债。"}]}, {"meaning": "借贷。", "cites": [{"t": "债车受载。", "b": "《穆天子传》"}]}, {"meaning": "讨债。", "cites": [{"t": "往有商人,贷他半钱,久不得偿,即更往债。", "b": "《百喻经》"}]}, {"meaning": "租赁。", "cites": [{"t": "债车受载。", "b": "《穆天子传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1955wx','借','1','jiè','亻','10','','[{"pinyin": "jiè", "defs": [{"meaning": "(形声。从人,昔声。本义:借,借进,借出)。"}, {"meaning": "借进。", "cites": [{"t": "借,假也。", "b": "《说文》。朱骏声曰:“即藉字之转注。古只作藉。”"}, {"t": "借,假借也。", "b": "《广韵》"}, {"t": "借无不给。", "b": "《晋书·阮裕传》"}, {"t": "借旁近与之。", "b": "宋·王安石《伤仲永》"}, {"t": "允修借书。", "b": "清·袁枚《黄生借书说》"}, {"t": "书非借不能读。", "b": ""}, {"t": "借者之用心。", "b": ""}, {"t": "其借书亦类予。", "b": ""}], "words": [{"w": "求借", "t": "请求别人借给"}, {"w": "挪借", "t": "暂时借用别人的钱"}, {"w": "借当", "t": "借人东西去当铺当钱"}, {"w": "借当头", "t": "借将要拿去典当的东西"}, {"w": "借典", "t": "借,借用。"}]}, {"meaning": "借出。", "cites": [{"t": "有马者,借人乘之。", "b": "《论语·卫灵公》"}, {"t": "权势不可以借人。", "b": "《韩非子·内储说下》"}], "words": [{"w": "他借书给我们;借给他几块钱;借一肩儿", "t": "挑担者让别人替自己挑一会,自己可以休息一下"}, {"w": "借借", "t": "借出"}, {"w": "借赁", "t": "租借。"}]}, {"meaning": "帮助。", "cites": [{"t": "水天空阔,恨东风,不借世间英物。", "b": "文天祥《念奴娇》"}]}, {"meaning": "假托;借口。", "cites": [{"t": "若苟有以藉口。", "b": "《左传·成公二年》"}], "words": [{"w": "借言", "t": "借口,假托的理由"}, {"w": "借情", "t": "假托某种情况或缘故。"}]}, {"meaning": "凭借;依靠。", "cites": [{"t": "借子杀之。", "b": "《墨子·公输》"}, {"t": "其可以借以美名者,以外权重之。", "b": "《韩非子·孤愤》"}, {"t": "借天降大雨。", "b": "《广东军务记》"}, {"t": "借寨墙为蔽。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "借征入境。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "借倩", "t": "托请"}, {"w": "借水行舟", "t": "借用别人的力量或条观条件办事"}, {"w": "借步檐躲雨", "t": "喻指借他人力量庇护自己"}, {"w": "借势儿", "t": "乘机。"}]}, {"meaning": "相当于“假使”,“假设”,“假如”,“即使”。", "cites": [{"t": "借第令母斩。", "b": "《史记·陈涉世家》"}], "words": [{"w": "借使", "t": "假设连词。假如,倘若;即使,纵然"}, {"w": "借若", "t": "犹假如"}, {"w": "借或", "t": "即或,即使"}, {"w": "借如", "t": "假设连词。假如,如果;即如,例如。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1956wx','值','1','zhí','亻','10','','[{"pinyin": "zhí", "defs": [{"meaning": "(形声。从人,直声。字本作“直”。本义:措置,放置)。"}, {"meaning": "同本义。", "cites": [{"t": "值,措也。", "b": "《说文》"}, {"t": "值,本作直。…值与置同,故《说文》训值为措,训措为置,互相转注,其音义并同。", "b": "《说书丛录》"}]}, {"meaning": "持,拿住。", "cites": [{"t": "无冬无夏,值其鹭羽。", "b": "《诗·陈风·宛丘》"}]}, {"meaning": "遇到,碰上。", "cites": [{"t": "值河间岁试。", "b": "诸葛亮《出师表》"}]}, {"meaning": "又。", "cites": [{"t": "后值倾覆。", "b": ""}], "words": [{"w": "值遇;正值国庆,老友相逢,真是高兴", "t": ""}]}, {"meaning": "值班。", "cites": [{"t": "家父前日退值回来。", "b": "《老残游记》"}], "words": [{"w": "值日功曹", "t": "旧时朝廷值日官"}, {"w": "值年班", "t": "每年轮流在规定的时间值勤"}, {"w": "值月", "t": "在当值的那一月承应差事或担任某项工作"}, {"w": "值年", "t": "在当值的那一年承应差事或担任某项工作。"}]}, {"meaning": "价值相当。", "cites": [{"t": "游人五陵去,宝剑值千金。", "b": "孟浩然《送朱大人入寨》"}, {"t": "价是值二千贯,只没个识主。", "b": "《水浒传》"}], "words": [{"w": "这匹马值三百美元;这个州赠予的木材和铁值几百万美元;它值多少钱", "t": ""}]}, {"meaning": "价值;数值。", "cites": [{"t": "可值千万金。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "币值;产值", "t": ""}]}, {"meaning": "价钱。", "cites": [{"t": "黄金美者,其值与黑钱一万六千倍。", "b": "《天工开物》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1957wx','倚','1','yǐ','亻','10','','[{"pinyin": "yǐ", "defs": [{"meaning": "(形声。从人,奇声。本义:斜靠着)。"}, {"meaning": "同本义。", "cites": [{"t": "倚,依也。", "b": "《说文》"}, {"t": "参天两地而倚数。", "b": "《易·说卦》"}, {"t": "倚柱而笑。", "b": "《史记·刺客列传》"}, {"t": "倚于郎门。", "b": "《韩非子·内储说下》"}, {"t": "故曰:“祸兮福之所倚。", "b": "《韩非子·解老》"}, {"t": "荡倚冲冒。", "b": "唐·柳宗元《三戒》"}, {"t": "右臂挂念珠倚之——珠可历历数也。——明·魏学《核舟记》", "b": ""}, {"t": "倚一横木。", "b": ""}, {"t": "奔倚其下。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "倚望", "t": "父母倚门望子"}, {"w": "倚身", "t": "把身体靠在某一物体上"}, {"w": "倚门", "t": "靠着门。"}]}, {"meaning": "依靠;依赖。", "cites": [{"t": "祸兮福之所倚。", "b": "《老子》"}], "words": [{"w": "倚负", "t": "依附;跟从"}, {"w": "倚叠", "t": "互相依靠勾结"}, {"w": "倚人庐下", "t": "依靠别人生活"}, {"w": "倚借", "t": "依赖;倚仗"}, {"w": "倚任", "t": "倚重信任"}, {"w": "倚信", "t": "倚重信任"}, {"w": "倚官挟势", "t": "倚仗官府的权势"}, {"w": "倚酒三分醉", "t": "仗着喝点酒,就装出醉态来。形容借一点因由,故意扩大事态。"}]}, {"meaning": "拄。", "cites": [{"t": "倚杖自叹息。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "依照,合着。", "cites": [{"t": "倚嫔御歌。", "b": "宋·王谠《唐语林·雅量》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1958wx','俺','1','ǎn','亻','10','','[{"pinyin": "ǎn", "defs": [{"meaning": "[方言] 我", "cites": [{"t": "都道是金玉良缘,俺只念木石前盟。", "b": "《红楼梦》"}], "words": [{"w": "俺那儿", "t": "我家里那个。指丈夫"}, {"w": "俺不去", "t": ""}]}, {"meaning": "[方言] 我的", "words": [{"w": "俺爹", "t": ""}]}, {"meaning": "[方言] 我们的", "words": [{"w": "俺村", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1959wx','倾','1','qīng','亻','10','','[{"pinyin": "qīng", "defs": [{"meaning": "(会意兼形声。从人,从顷,顷亦声。“顷”有偏侧的意思。从人,多表示人的动作行为。本义:偏侧)。"}, {"meaning": "同本义。", "cites": [{"t": "倾,仄也。", "b": "《说文》"}, {"t": "倾则奸。", "b": "《礼记·曲礼下》。注:“倾或为侧。”疏:“倾,欹侧也。”"}, {"t": "安无倾。", "b": "《论语·季氏》"}, {"t": "重钧则衡不倾。", "b": "《淮南子·说山》"}, {"t": "日既西倾。", "b": "曹植《洛神赋》"}, {"t": "倾耳而听。", "b": "《战国策·秦策》"}, {"t": "高下相倾。", "b": "《老子》。释文:“不正貌。”"}, {"t": "俯身倾耳。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "倾葵", "t": "向日葵。借指尽忠"}, {"w": "倾倚", "t": "偏斜不正"}, {"w": "倾低", "t": "倾斜,歪斜"}, {"w": "倾昃", "t": "偏斜;不正"}, {"w": "倾返", "t": "形容峰峦险峻,向下倾斜"}, {"w": "倾柯", "t": "使枝条倾斜下垂"}, {"w": "倾倚", "t": "倾斜,歪斜。"}]}, {"meaning": "倾塌,倒下。", "cites": [{"t": "安无倾。", "b": "《论语·季氏》"}, {"t": "高台未倾。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "对此欲倒东南倾。", "b": "唐·李白《梦游天姥吟留别》诗"}, {"t": "樯倾楫摧。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "倾崩", "t": "崩溃"}, {"w": "大厦将倾;倾国", "t": "倾覆邦国;形容容貌极美"}, {"w": "倾朝", "t": "倾覆朝廷"}, {"w": "倾弛", "t": "倒塌残破。"}]}, {"meaning": "向往,钦佩。", "cites": [{"t": "一坐尽倾。", "b": "《汉书·司马相如传》"}], "words": [{"w": "倾奉", "t": "倾心敬奉"}, {"w": "倾瞩", "t": "倾心向往。"}]}, {"meaning": "倒出来。", "cites": [{"t": "往往取酒还独倾。", "b": "白居易《琵琶行(并序)》诗"}], "words": [{"w": "倾囊相助", "t": ""}]}, {"meaning": "倾轧。", "cites": [{"t": "以利相倾。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "倾挤", "t": "倾轧排挤"}, {"w": "倾黜", "t": "倾轧罢免。"}]}, {"meaning": "用尽;竭尽。", "cites": [{"t": "倾家竭产。", "b": "《三国志·蜀书》"}, {"t": "倾城远追送。", "b": "孙楚《征西官属诗》"}], "words": [{"w": "倾家费产", "t": "竭尽全部家产"}, {"w": "倾身", "t": "竭尽全力"}, {"w": "倾忱", "t": "竭尽诚心"}, {"w": "倾尽", "t": "尽心竭力"}, {"w": "倾觞", "t": "尽觞。谓畅饮"}, {"w": "倾国", "t": "全国,举国"}, {"w": "倾家", "t": "全家;拿出全部家产"}, {"w": "倾献", "t": "全部献出。"}]}, {"meaning": "超过,胜过。", "cites": [{"t": "欲以倾诸将相。", "b": "《汉书·田竕传》。注:“逾越而胜之也。”"}]}, {"meaning": "衰败。", "cites": [{"t": "下塞上聋,邦其倾矣。", "b": "韩愈《子产不毁乡校颂》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1960wx','倒','1','dǎo dào','亻','10','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从人,到声。本义:倒下)。"}, {"meaning": "同本义。", "cites": [{"t": "对此欲倒东南倾。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "倒头", "t": "躺下睡觉;死亡"}, {"w": "倒路", "t": "亦路倒。死在路上"}, {"w": "倒卓", "t": "倒栽"}, {"w": "倒断", "t": "山倒锁断"}, {"w": "倒指", "t": "屈指,屈指计算"}, {"w": "倒路死", "t": "诅咒人死在路上"}, {"w": "倒床", "t": "卧倒在床上。"}]}, {"meaning": "失败,败落。", "cites": [{"t": "于今日卿等门户倒矣。", "b": "《三国志·曹爽传》"}], "words": [{"w": "倒灶", "t": "倒霉"}, {"w": "倒扁儿", "t": "向人挪借钱财或货以应急需"}, {"w": "倒满", "t": "倒霉;晦气。"}]}, {"meaning": "坍塌;垮台。", "cites": [{"t": "中间力拉崩倒之声。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": " 倒口子", "t": "决口"}, {"w": "倒溃", "t": "倒塌崩溃"}, {"w": "倒坏", "t": "倒塌崩坏。"}]}, {"meaning": "将货物或商店企业作价给人。", "cites": [{"t": "我东头街上谈家当铺折了本,要倒于人。", "b": "《儒林外史》"}], "words": [{"w": "倒盘", "t": "把全店存货作价盘售"}, {"w": "倒本", "t": "赚回本钱。"}]}]}, {"pinyin": "dào", "defs": [{"meaning": "上下、前后颠倒。", "cites": [{"t": "倒筴侧龟于君前。", "b": "《礼记·曲礼》"}, {"t": "倒影江中。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "倒序", "t": "颠倒次序"}, {"w": "倒用印", "t": "将印信颠倒使用"}, {"w": "倒错", "t": "颠倒错乱"}, {"w": "倒景", "t": "倒影"}, {"w": "倒三不着两", "t": "行事无准则,颠三倒四。"}]}, {"meaning": "向相反方向移动。", "cites": [{"t": "酒酣渴月使倒行。", "b": "李贺《秦王饮酒》"}], "words": [{"w": "倒车;倒回", "t": "退却;倒退"}, {"w": "倒兵", "t": "掉转武器向己方攻击"}, {"w": "倒仰", "t": "仰面跌倒"}, {"w": "倒跟脚", "t": "指脚跟向后突出。"}]}, {"meaning": "将容器倾斜或反转,使里面的东西出来。", "cites": [{"t": "倒杯开水", "b": ""}, {"t": "倒垃圾", "b": ""}], "words": [{"w": "倒熟话", "t": "重复老一套的话"}, {"w": "倒囷", "t": "尽出仓里的贮米"}, {"w": "倒垃圾", "t": ""}]}, {"meaning": "表示跟一般情理相反。", "cites": [{"t": "不曾与天下分忧,倒来苦害俺这里百姓。", "b": "《陈州粜米》"}], "words": [{"w": "倒不得", "t": "岂肯"}, {"w": "妹妹倒比姐姐高", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1961wx','倘','1','tǎng cháng','亻','10','','[{"pinyin": "tǎng", "defs": [{"meaning": "表示假设。", "cites": [{"t": "倘三年犹不得。", "b": "清·候方域《壮悔堂文集》"}, {"t": "倘复请之。", "b": "清·方苞《狱中杂记》"}, {"t": "汝倘有灵。", "b": "清·袁枚《祭妹文》"}, {"t": "倘国人皆…奋斗。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "倘若", "t": "假如。"}]}]}, {"pinyin": "cháng", "defs": [{"meaning": "同‘徜徉’", "words": [{"w": "倘佯", "t": "指安闲自在的徘徊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1962wx','俱','1','jù','亻','10','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从人,具声。本义:走在一起,在一起)。"}, {"meaning": "同本义。", "cites": [{"t": "俱,皆也。", "b": "《说文》"}, {"t": "而仪与之俱。", "b": "《战国策·齐策》。注:“偕也。”"}, {"t": "道可载而与之俱也。", "b": "《庄子·天运》"}, {"t": "臣客屠者朱亥可与俱。", "b": "《史记·魏公子列传》"}, {"t": "百余人俱。", "b": "《汉书·李广苏建传》"}, {"t": "与李陵俱。", "b": ""}, {"t": "处与之俱。", "b": "《世说新语·自新》"}, {"t": "使与书俱。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "等同。", "cites": [{"t": "所谓后者应不俱也。", "b": "《素问·三部九侯论》。注:“犹同也。”"}, {"t": "伊尹、箕子才俱也,伊尹为相,箕子为奴。", "b": "《论衡》"}]}, {"meaning": "皆;全;都。", "cites": [{"t": "其势不俱生。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "俱为一体。", "b": "诸葛亮《出师表》"}, {"t": "三首俱烂。", "b": "晋·干宝《搜神记》"}, {"t": "野径云俱黑。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "战具俱办。", "b": "《资治通鉴》"}]}, {"meaning": "一起;一同。", "cites": [{"t": "父子俱在军中。", "b": "《史记·魏公子列传》"}, {"t": "俱诣孙权。", "b": "《资治通鉴》"}, {"t": "水陆俱下。", "b": ""}, {"t": "与璧俱碎。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "君与俱来。", "b": "《三国志·诸葛亮传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1963wx','倡','1','chāng chàng','亻','10','','[{"pinyin": "chāng", "defs": [{"meaning": "(形声。从人,昌声。本义:唱歌的艺人)。"}, {"meaning": "同本义。", "cites": [{"t": "倡,乐也。", "b": "《说文》"}, {"t": "倡,俳也。", "b": "《声类》"}, {"t": "倡,优乐也。", "b": "《字林》"}, {"t": "令倡俳赢戏坐中。", "b": "《汉书·广川惠王越传》。注:“乐人也。”"}, {"t": "孝武李夫人本以倡进。", "b": "《汉书·外戚传》"}, {"t": "幸倡郭舍人。", "b": "《汉书·东方朔传》"}, {"t": "孝武李夫人本以倡进。", "b": "《汉书·外戚传》"}, {"t": "优旃者,秦倡。", "b": "《史记·滑稽列传》"}, {"t": "问其人,本长安倡女。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "倡家", "t": "歌楼酒馆。也 指妓院。"}]}, {"meaning": "泛指中国古代表演歌舞杂戏的艺人。又称:倡人,倡优,倡伎,倡女,倡家,倡俳,倡排,倡妇。", "cites": [{"t": "臣之所造能倡者。", "b": "《列子·汤问》。注:“倡,俳优也。”"}, {"t": "吾闻楚之铁剑利而倡优拙。", "b": "《史记·范雎列传》"}, {"t": "击鼓歌吹作俳倡。", "b": "《后汉书·霍光传》"}], "words": [{"w": "倡卒", "t": "军中表演歌舞百戏者。"}]}, {"meaning": "妓女 。也作“娼”。", "cites": [{"t": "昔为倡家女,今为荡子妇。", "b": "《古诗十九首》"}], "words": [{"w": "倡姥", "t": "老娼妇"}, {"w": "倡伎", "t": "娼妓。"}]}]}, {"pinyin": "chàng", "defs": [{"meaning": "(形声。从人,昌声。(chāng)本义:表演歌舞的人)。"}, {"meaning": "领唱,发声先唱。", "cites": [{"t": "叔兮伯兮,倡予和女。", "b": "《诗·郑风·萚兮》"}, {"t": "一倡而三叹。", "b": "《礼记·乐记》"}], "words": [{"w": "倡作", "t": "首唱之作"}, {"w": "倡和", "t": "一人首倡,他人相和,互相应答。"}]}, {"meaning": "提倡。", "cites": [{"t": "今诚以吾众为天下倡,宜多应者。", "b": "《汉书·陈胜传》"}], "words": [{"w": "倡明", "t": "提倡并阐明"}, {"w": "倡义", "t": "首倡大义。"}]}, {"meaning": "倡导,先导;带头。", "cites": [{"t": "妇人倡俑。", "b": "《礼记·檀弓》"}], "words": [{"w": "倡工", "t": "带头破土动工"}, {"w": "倡道", "t": "在前面导引"}, {"w": "倡国", "t": "领先之国。"}]}, {"meaning": "歌唱。", "cites": [{"t": "壹倡而三叹,有遗音者矣。", "b": "《礼记·乐记》"}, {"t": "物有微而陨性兮,声有隐而先倡。", "b": "《楚辞·九章·悲回风》"}, {"t": "千人倡,万人和,山陵为之震动,川谷为之荡波。", "b": "《汉书·司马相如传》"}], "words": [{"w": "倡呼", "t": "歌唱欢呼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1964wx','候','1','hòu','亻','10','','[{"pinyin": "hòu", "defs": [{"meaning": "(形声。古文作“矦”。从人,侯声。本义:守望;侦察)。"}, {"meaning": "同本义。", "cites": [{"t": "矦,伺望也。", "b": "《说文》"}, {"t": "矦,覗也。", "b": "《广雅·释诂三》"}, {"t": "市有候馆。", "b": "《周礼·遗人》。注:“楼可以观望者也。”"}], "words": [{"w": "候馆", "t": "用以瞭望的高楼"}, {"w": "候楼", "t": "用以瞭望的楼"}, {"w": "侯遮", "t": "侦探敌情"}, {"w": "候徼", "t": "在国境线上巡察警戒"}, {"w": "候车", "t": "侦察敌情的战车。"}]}, {"meaning": "等候。", "cites": [{"t": "稚子候门。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "即候苗成。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "候春发遣。", "b": "清·方苞《狱中杂记》"}, {"t": "移顺天府羁候。", "b": ""}], "words": [{"w": "候时", "t": "等候时机"}, {"w": "候对", "t": "等候帝王召对"}, {"w": "候结", "t": "等候审判;结案"}, {"w": "候补道", "t": "等候实缺的候补道员。"}]}, {"meaning": "敬候。", "cites": [{"t": "彼矦人兮。", "b": "《诗·曹风·候人》。传:“道路迎送宾客者。”"}], "words": [{"w": "候拜", "t": "迎候拜见"}, {"w": "候人", "t": "周礼官名。掌管在路上迎送宾客等事"}, {"w": "候驾", "t": "迎候帝王。"}]}, {"meaning": "看望;问候。", "cites": [{"t": "遣人候问。", "b": "《汉书·李广苏建传》"}, {"t": "候太公太母起居。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "候札", "t": "问候的信札"}, {"w": "候函", "t": "问候的信函"}, {"w": "候省", "t": "探视问候"}, {"w": "候敬", "t": "问候时敬赠的礼物。"}]}, {"meaning": "预测;占验。", "cites": [{"t": "梦者六候。", "b": "《列子·周穆王》"}], "words": [{"w": "候天", "t": "占验天象,以卜吉凶祸福"}, {"w": "候物", "t": "占验物候"}, {"w": "候星", "t": "占验星象"}, {"w": "候气", "t": "占验节气的变化。"}]}, {"meaning": "服侍。", "cites": [{"t": "性柔顺好礼,每帝视朝退,常具冠帔候接,佐御馔。", "b": "《宋史》"}]}, {"meaning": "官吏。"}, {"meaning": "驿站,驿馆。", "cites": [{"t": "旧南海献龙眼、荔支,十里一置,五里一候。", "b": "《后汉书》"}], "words": [{"w": "候舍", "t": "接待过往官员或其他宾客的馆舍"}, {"w": "候置", "t": "驿站。"}]}, {"meaning": "古代计时单位。五天为一候。", "cites": [{"t": "歧伯曰:“五日谓之候,三候谓之气,六气谓之时,四时谓之岁。”", "b": "《素问》"}]}, {"meaning": "引申为节候,时令。", "cites": [{"t": "北陆候才变,南枝花已开。", "b": "唐·韩偓《早玩雪梅有怀亲属》"}]}, {"meaning": "症候。", "cites": [{"t": "[马嗣明]为人诊候,一年前知其生死。", "b": "《北齐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1965wx','赁','1','lìn','贝','10','','[{"pinyin": "lìn", "defs": [{"meaning": "(形声。从贝,任声。本义:给人做雇工)。"}, {"meaning": "同本义。", "cites": [{"t": "穷困,赁佣于齐,为酒人保。", "b": "《史记·栾布列传》"}], "words": [{"w": "赁工", "t": "雇工"}, {"w": "赁力", "t": "出卖劳力"}, {"w": "赁作", "t": "受雇为人劳作"}, {"w": "赁保", "t": "受人雇用"}, {"w": "赁书", "t": "受雇为人抄写"}, {"w": "赁佣", "t": "受雇为佣工。"}]}, {"meaning": "租用、租借。", "cites": [{"t": "每店皆有驴赁客乘。", "b": "杜佑《通典》"}], "words": [{"w": "赁屋;赁书;赁居", "t": "租用房屋居住"}, {"w": "赁约", "t": "租借契约"}, {"w": "赁租", "t": "出租;租借。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1966wx','俯','1','fǔ','亻','10','','[{"pinyin": "fǔ", "defs": [{"meaning": "(会意。从页(xié),表示与头有关,从逃省。取低头逃跑意。现在简化为“从人府声”的形声字。本义:低头)。"}, {"meaning": "同本义。", "cites": [{"t": "俯而纳屦。", "b": "《礼记·曲礼上》"}, {"t": "俯而闚其户。", "b": "《公羊传·宣公六年》"}, {"t": "仰视宇宙之大,俯察品类之盛。", "b": "晋·王羲之《兰亭集序》"}], "words": [{"w": "俯擗", "t": "低头捶胸,悲伤之极的样子"}, {"w": "俯偻", "t": "低头曲背"}, {"w": "俯听", "t": "俯首而听"}, {"w": "俯鉴", "t": "低头照视。"}]}, {"meaning": "弯腰屈身。", "cites": [{"t": "余立侍左右,援疑质理,俯身倾耳以请。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "俯步", "t": "俯身而行"}, {"w": "俯躬", "t": "弯下身子"}, {"w": "俯镜", "t": "弯身下视照影。"}]}, {"meaning": "在蛰伏的状态中的越冬。", "cites": [{"t": "蛰虫咸俯在内,皆墐其户。", "b": "《礼记祔》"}]}, {"meaning": "上对下行动的敬辞。", "cites": [{"t": "是故明君制民之产,必使仰足以事父母,俯足以畜妻子。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "俯准", "t": "敬辞。允准;答应"}, {"w": "俯从", "t": "敬辞。听从,允许"}, {"w": "俯同", "t": "敬辞。屈驾;劳驾"}, {"w": "俯垂护佑", "t": "敬辞。垂怜保佑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1967wx','倍','1','bèi','亻','10','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从人,(tǒu)声。本义:通“背”。反;背向)。"}, {"meaning": "同本义。", "cites": [{"t": "倍,反也。", "b": "《说文》"}, {"t": "倍正南方。", "b": "《周髀算经下》"}, {"t": "兵法右倍山陵,前左水泽。", "b": "《史记·淮阴侯传》"}]}, {"meaning": "背弃;背叛", "cites": [{"t": "无倍畔之心。", "b": "《汉书·贾谊传》"}, {"t": "教而不称师谓之倍。", "b": "《荀子·大略》"}, {"t": "而民不倍。", "b": "《礼记·大学》"}, {"t": "愿伯具言臣之不敢倍德也。", "b": "《史记·项羽本纪》"}], "words": [{"w": "倍畔", "t": "同背叛"}, {"w": "倍上", "t": "背叛尊上。"}]}, {"meaning": "违反;违背。", "cites": [{"t": "倍本弃事而安怠傲。", "b": "《墨子·非儒》"}, {"t": "倍其公法,损其正心,专听大臣者,危主也。", "b": "《管子·任法》"}, {"t": "倍道而妄行,则天不能使之吉。", "b": "《荀子·天论》"}], "words": [{"w": "倍言", "t": "违背信约"}, {"w": "倍时", "t": "违时,错过时机"}, {"w": "倍情", "t": "违背情实。"}]}, {"meaning": "加倍,照原数等加。", "cites": [{"t": "为近利市三倍。", "b": "《易·说卦》"}, {"t": "乘上之急,所卖必倍。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "倍日", "t": "一天时间当两天用"}, {"w": "倍半", "t": "超出一倍和仅有其半。谓一多一少,差距甚大"}, {"w": "倍多", "t": "成倍增加。"}]}, {"meaning": "背诵。", "cites": [{"t": "郑注:“倍文曰讽”。", "b": "《周礼·大司乐》"}, {"t": "读书倍文,功力兼人。", "b": "韩信《韩滂墓志铭》"}], "words": [{"w": "倍文", "t": "背诵书文"}, {"w": "倍讽", "t": "背诵"}, {"w": "倍读", "t": "背诵。"}]}, {"meaning": "倍数。", "cites": [{"t": "尝以十倍之地,百万之师,叩关而攻秦。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "五倍;三的五倍是十五;倍百", "t": "百倍"}, {"w": "倍差", "t": "一倍半。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1968wx','倦','1','juàn','亻','10','','[{"pinyin": "juàn", "defs": [{"meaning": "(形声。从人,卷声。本义:疲倦,劳累)。"}, {"meaning": "同本义。", "cites": [{"t": "倦,疲也。", "b": "《汉书·司马相如传》集注"}, {"t": "倦狭路之迫隘。", "b": "潘岳《西征赋》"}, {"t": "不继之以倦。", "b": "《礼记·表记》"}, {"t": "居之无倦。", "b": "《论语》"}, {"t": "士卒罢倦。", "b": "《汉书·严助传》"}, {"t": "文倦于事。", "b": "《战国策·齐策四》"}, {"t": "劳苦倦极。", "b": "《史记·屈原贾生列传》"}, {"t": "鸟倦飞而知还。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "相公倦。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "困倦", "t": "疲乏想睡"}, {"w": "倦程", "t": "倦于旅程"}, {"w": "倦飞", "t": "疲于飞行。以鸟自比,比喻归隐"}, {"w": "倦怯", "t": "倦怠而没心绪"}, {"w": "倦惫", "t": "疲倦困惫"}, {"w": "倦闷", "t": "疲倦烦闷"}, {"w": "倦劳", "t": "疲倦劳累。"}]}, {"meaning": "懈怠,厌烦,厌倦。", "cites": [{"t": "诲人不倦。", "b": "《论语》"}, {"t": "则徧而不倦。", "b": "《国语·晋语》。注:“懈也。”"}], "words": [{"w": "闷倦", "t": "烦闷厌倦"}, {"w": "倦游", "t": "厌于游宦而想辞官"}, {"w": "倦笔", "t": "不经心的手笔"}, {"w": "倦世", "t": "厌倦于俗世的生活。"}]}, {"meaning": "蹲坐,双臂贴近身体弯下腰去,或蜷腿并用臀部贴近地面", "cites": [{"t": "方倦龟壳而食蛤梨。", "b": "《淮南子》"}]}, {"meaning": "衰减。", "cites": [{"t": "居贫苦而志不倦。", "b": "《论衡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1969wx','健','1','jiàn','亻','10','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从人,建声。本义:强有力)。"}, {"meaning": "同本义。", "cites": [{"t": "健,伉也。", "b": "《说文》"}, {"t": "震其究为健。", "b": "《易·说卦传》"}, {"t": "四健骄也。", "b": "《韩诗外传》"}, {"t": "天行健,君子以自强不息。", "b": "《易·乾》"}, {"t": "天下健者。", "b": "清·梁启超《谭嗣同传》"}, {"t": "与汝幸双健。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "健举", "t": "刚劲有力"}, {"w": "健舞", "t": "刚健风格的舞蹈。"}]}, {"meaning": "健康;健壮。", "cites": [{"t": "纵有健妇把锄犁,禾生垄亩无东西。", "b": "杜甫《兵车行》"}, {"t": "健卒十人。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "子弟素健。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "健节", "t": "健壮,有力"}, {"w": "健夫", "t": "强壮的男子。"}]}, {"meaning": "敏捷;高明;有才能。", "cites": [{"t": "楚客来使者多健,与寡人争辞,寡人数穷焉。", "b": "《战国策·秦策》"}], "words": [{"w": "健妇", "t": "能干的妇女。"}]}, {"meaning": "善于;擅长。", "cites": [{"t": "有健啖客。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "健讼", "t": "好打官司,以诉讼为能事"}, {"w": "健笔", "t": "文笔练达明畅。指精于写作"}, {"w": "健羡", "t": "贪婪无厌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1970wx','臭','1','chòu xiù','自','10','','[{"pinyin": "chòu", "defs": [{"meaning": "(会意。从犬,从自(鼻)。狗鼻特别灵敏,故从二字会意。(xiù)本义:闻气味)。"}, {"meaning": "气味之总名。", "cites": [{"t": "臭,禽走臭而知其迹者,犬也。", "b": "《说文》"}, {"t": "无起秽以自臭。", "b": "《书·盘庚》。疏:“古者香气秽气皆名之臭。”"}, {"t": "其臭如兰。", "b": "《易·系辞传》"}, {"t": "巽为臭。", "b": "《易·说卦》"}, {"t": "鼻欲綦臭。", "b": "《荀子·王霸》。注:“臭,气也。”"}, {"t": "香臭芬郁腥臊洒酸奇臭以鼻异。", "b": "《荀子·正名》"}]}, {"meaning": "难闻的气味。", "cites": [{"t": "惠公改葬申生,臭彻于外。", "b": "《国语·晋语》"}], "words": [{"w": "臭不 可当", "t": "极言其臭"}, {"w": "臭短臊长", "t": "各种污言秽语"}, {"w": "臭皮囊", "t": "肉体;躯壳。"}]}, {"meaning": "香气。", "cites": [{"t": "同心之言,其臭如兰。", "b": "《易·系辞上》"}]}, {"meaning": "腐败。", "cites": [{"t": "若乘舟,汝弗济,臭厥载。", "b": "《书·盘庚中》"}]}]}, {"pinyin": "xiù", "defs": [{"meaning": "气味的总称。", "cites": [{"t": "人通于鼻者谓之臭。臭者,气也。", "b": "朱骏声《说文通训定声》"}, {"t": "无起秽以自臭。", "b": "《书·盘庚》。疏:“古者,香气、秽气皆名为臭。”"}, {"t": "薋葹妒其臭,茞芟兰竟被芟。", "b": "《红楼梦》"}, {"t": "上天之载,无声无臭。", "b": "《诗·大雅·文王》。郑玄笺:“耳不闻声音,鼻不闻香臭。”"}, {"t": "口之于味也,目之于色也,耳之于声也,鼻之于臭也,四肢之于安佚也,性也。", "b": "《孟子》"}], "words": [{"w": "乳臭;臭味", "t": "气味;比喻志趣;比喻同类"}, {"w": "臭败", "t": "气味败坏。"}]}, {"meaning": "“嗅”的古字。用鼻子辨别气味。", "cites": [{"t": "彼臭之而无嗛于鼻。", "b": "《荀子·荣辱》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1971wx','射','1','shè','寸','10','','[{"pinyin": "shè", "defs": [{"meaning": "(本作“射”。会意。金文字形,象箭在弦上,手(寸)在发放。小篆把弓矢形讹变成“身”字,误。本义:用弓发箭使中远处目标)。"}, {"meaning": "同本义。", "cites": [{"t": "射,弓弩发于身而中于远也。", "b": "《说文》"}, {"t": "三曰五射。", "b": "《周礼·保氏》"}, {"t": "射者,男子之事也。", "b": "《礼记·射义》"}, {"t": "以射策甲科为郎。", "b": "《汉书·萧望之传》。注:“射之言投射也。”"}, {"t": "射声校尉。", "b": "《后汉书·光武纪》"}, {"t": "常能为汉伏弩射之。", "b": "《汉书·李广苏建传》"}, {"t": "应元往来驰射,发一矢辄殪一贼。", "b": "邵长蘅《青门剩稿》"}], "words": [{"w": "射鹄", "t": "射箭的靶子"}, {"w": "射日", "t": "古代神话。传说尧时有十二日并出,庄稼尽被晒枯,后羿射落九日,为民除了害"}, {"w": "射牛", "t": "古代帝王、诸侯祭祀天地、宗庙,必亲自射牛以示隆重"}, {"w": "射利", "t": "比喻急于追求财利如射矢之速。"}]}, {"meaning": "用推力、压力或弹力送出。", "cites": [{"t": "连放火箭,直射北门外方圆两炮台。", "b": "《三元里抗英》"}], "words": [{"w": "射门;射弹;射击;射工", "t": "传说中能含沙射影的毒虫"}, {"w": "喷射;注射", "t": ""}]}, {"meaning": "猜度。", "cites": [{"t": "是何鸟也?王射之。", "b": "《吕氏春秋·重言》"}], "words": [{"w": "射虎", "t": "猜灯谜。灯谜,又如灯虎、文虎"}, {"w": "射覆", "t": "一种酒令。用相连的字句隐寓事物,使人猜度。"}]}, {"meaning": "打赌。", "cites": [{"t": "于是使射千镒之重,争千里之逐。", "b": "汉·枚乘《七发》"}]}, {"meaning": "谋求,逐取。", "cites": [{"t": "江淮豪贾射利。", "b": "《新唐书·食货志》"}], "words": [{"w": "射利", "t": "谋取财礼。"}]}, {"meaning": "照射,放射。", "cites": [{"t": "有红光一缕起土桥,直射城内。", "b": "《阎典史传》"}]}, {"meaning": "循着,顺着。", "cites": [{"t": "夜非深林荟丛,不能藏蔽,无闻儿啼,即射声而至。", "b": "清·黄宗羲《金孺人墓志铭》"}]}, {"meaning": "瞬间地斜视。", "cites": [{"t": "又冷冷地射了屠维岳一眼。", "b": "茅盾《子夜》"}]}, {"meaning": "拦阻。", "cites": [{"t": "谋为石岸,以射水势。", "b": "明·张居正《方氏建水榭铭》"}]}, {"meaning": "嘲弄。", "cites": [{"t": "编成而名之曰《三闲集》,尚以射仿吾也。", "b": "鲁迅《三闲集》"}]}, {"meaning": "指投壶 。把箭投向壶里,按投中次数多少决定胜负。输了罚酒。", "cites": [{"t": "射者中,弈者胜,觥筹交错,起坐而喧哗者,众宾欢也。", "b": "宋·欧阳修《醉翁亭记》"}]}, {"meaning": "放箭的人。", "cites": [{"t": "羿不为拙射变其彀率。", "b": "《孟子》"}]}, {"meaning": "圭璋上端锐出部分。", "cites": [{"t": "大璋、中璋九寸,边璋七寸。射四寸。", "b": "《周礼·考工记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1972wx','躬','1','gōng','身','10','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从身,弓声。从“身”的字多与身体有关。本义:整个身体)。"}, {"meaning": "同本义。", "cites": [{"t": "躬,身也。", "b": "《说文》"}, {"t": "信圭矦守之,躬圭伯守之。", "b": "《考工记·玉人》。按,琢为人形,信直躳曲。"}, {"t": "吾党有直躬者。", "b": "《论语》。孔注:“直身而行。”"}, {"t": "躬腠胝无胈。", "b": "《史记·司马相如传》。索隐:“体也。”"}, {"t": "我鞠躬不敢息。", "b": "马中锡《中山狼传》"}, {"t": "百姓愁苦,靡所错躬(指安身)。", "b": "《汉书·元帝纪》"}, {"t": "臣鞠躬尽瘁,死而后已。", "b": "诸葛亮《后出师表》"}], "words": [{"w": "躬体", "t": "身体"}, {"w": "躬先士卒", "t": "身先士卒"}, {"w": "躬擐", "t": "身穿。擐:穿。"}]}, {"meaning": "生命。", "cites": [{"t": "见南郢之流风兮,殒余躬于沅、湘。", "b": "汉·刘向《九叹·远游》"}]}, {"meaning": "手臂从肘到腕的部分。泛指手臂。", "cites": [{"t": "歌终,顾而流涕,张躬而舞。", "b": "《晏子春秋·内篇谏下》"}, {"t": "倍中以为躬。倍躬以为左右舌,谓侯之上下幅布也。", "b": "《仪礼·乡射礼记》"}], "words": [{"w": "长躬", "t": "衣服的中间部分较长。"}]}, {"meaning": "自身;自己。", "cites": [{"t": "已躬命之。", "b": "《仪礼·士昏礼记》。注:“犹亲也。”"}, {"t": "静言思之,躬自悼之。", "b": "《诗·卫风·氓》"}, {"t": "百官之非,宜由联躬。", "b": "《史记·教本纪》"}, {"t": "王若行之,将妨于国家,靡王躬身。", "b": "《国语·越语下》"}], "words": [{"w": "躬自", "t": "自己"}, {"w": "躬化", "t": "以自身的德行感化别人"}, {"w": "反躬自问", "t": ""}]}, {"meaning": "亲身;亲自。", "cites": [{"t": "臣本布衣,躬耕于南阳。", "b": "诸葛亮《出师表》"}, {"t": "史公治兵,往来相城,必躬左公弟,候太公、太母起居。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "童子何知,躬逢胜饯。", "b": "唐·王勃《滕王阁序》"}], "words": [{"w": "躬耕乐道", "t": "亲自耕种,乐守圣贤之道"}, {"w": "躬身", "t": "亲身,自身"}, {"w": "躬稼", "t": "亲身从事农事"}, {"w": "躬卒", "t": "亲自率领;亲身实行。"}]}, {"meaning": "稍微向前弯身,以表尊敬。", "cites": [{"t": "桓公变躬迁席,拱手而问曰:“敢问何谓其本?”", "b": "《管子·霸形》"}], "words": [{"w": "躬身下拜;躬敛", "t": "屈身敛衽。古代妇女行礼时的动作"}, {"w": "躬身", "t": "俯屈身体,以示恭敬。"}]}, {"meaning": "困苦危难。", "cites": [{"t": "潞子之为善也躬,足以亡尔。", "b": "《公羊传·宣公十五年》"}, {"t": "躬为匹夫而不愿富,贵为诸侯而无财。", "b": "《大戴礼·哀公问五义篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1973wx','息','1','xī','心','10','','[{"pinyin": "xī", "defs": [{"meaning": "(会意兼形声。从心,从自,自亦声。自,鼻子。古人以为气是从心里通过鼻子呼吸的。本义:喘气;呼吸)。"}, {"meaning": "同本义。", "cites": [{"t": "息,喘也。", "b": "《说文》"}, {"t": "亦孔之。", "b": "《诗·大雅·桑柔》。笺:“如仰疾风,不能息也。”"}, {"t": "尚不敢惕息。", "b": "《汉书·扬雄传》。注:“出入气也。”"}, {"t": "则心惕息。", "b": "《汉书·司马迁传》。注:“喘息也。”"}, {"t": "武气绝,半日复息。", "b": "《汉书·苏武传》"}, {"t": "随形势为沟墙,庶息响相闻,易于守御。", "b": "《明史·王复传》"}], "words": [{"w": "喘息", "t": "急促呼吸"}, {"w": "息息", "t": "呼吸;气息出入"}, {"w": "息窒", "t": "窒息,呼吸困难"}, {"w": "息响", "t": "呼吸的声音"}, {"w": "息贲", "t": "中医病名。指呼吸急促、气逆上奔的症候。"}]}, {"meaning": "叹气。", "cites": [{"t": "北山愚公长息。", "b": "《列子·汤问》"}, {"t": "喟然大息。", "b": "《汉书》"}, {"t": "闵王太息。", "b": "《战国策·齐策》。注:“长出气也。”"}], "words": [{"w": "叹息", "t": "叹气"}, {"w": "息悒", "t": "叹息忧闷。"}]}, {"meaning": "停止,停息。", "cites": [{"t": "息,安也。", "b": "《广雅》"}, {"t": "息,休也。", "b": "《释言》"}, {"t": "细人之爱人也以姑息。", "b": "《礼记·檀弓》。注:“犹安也。”"}, {"t": "而不得息。", "b": "《吕氏春秋·适威》。注:“安也。”"}, {"t": "臣必致死礼以息楚。", "b": "《左传·昭公八年》"}, {"t": "莫不敢遑息。", "b": "《诗·召南·殷其靁》"}, {"t": "君子以自强不息。", "b": "《易·乾》"}, {"t": "维子之故,使我不能息兮。", "b": "《诗·郑风·狡童》"}, {"t": "昼夜不息。", "b": "《广东军务记》"}, {"t": "请息交以绝游。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "无时而息。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "兵革既未息,儿童尽东征。", "b": "杜甫《羌村三首》"}], "words": [{"w": "息口", "t": "停口"}, {"w": "息手", "t": "停手"}, {"w": "息糜", "t": "制止;停止"}, {"w": "息言", "t": "停止言事"}, {"w": "息甲", "t": "解除盔甲。停战。"}]}, {"meaning": "休息。", "cites": [{"t": "民亦劳止,汔可小息。", "b": "《诗·大雅·民劳》"}, {"t": "鸡鸣入机织,夜夜不得息。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "息景", "t": "息影。退隐闲居"}, {"w": "息劳", "t": "休息"}, {"w": "息喘", "t": "喘息。比喻紧张活动中的短暂休息"}, {"w": "作息", "t": "工作和休息"}, {"w": "歇息", "t": "休息"}, {"w": "息力", "t": "休息。"}]}, {"meaning": "滋息;生长。", "cites": [{"t": "消息盈虚,终则有始。", "b": "《庄子·秋水》"}], "words": [{"w": "息马", "t": "畜养、蕃息马匹"}, {"w": "息人,息民", "t": "使人民得到休养生息。"}]}, {"meaning": "平息。", "cites": [{"t": "望峰息心。", "b": "《艺文类聚·吴均·与朱元思书》"}], "words": [{"w": "息事", "t": "平息事端"}, {"w": "息喘", "t": "平息喘气。"}]}, {"meaning": "消除。", "cites": [{"t": "息子贡之志。", "b": "《韩非子·五蠹》"}], "words": [{"w": "息望", "t": "不再生妄想"}, {"w": "息虑", "t": "消除担忧;消除杂念。"}]}, {"meaning": "熄灭;消失。", "cites": [{"t": "彖曰:“革,水火相息”。", "b": "《易·革》"}, {"t": "日月出矣,而爝火不息。", "b": "《庄子·消遥游》"}], "words": [{"w": "息了心", "t": "断了念头;死心"}, {"w": "息灭", "t": "熄灭;绝灭"}, {"w": "息机", "t": "熄灭机心。"}]}, {"meaning": "气息,呼吸时出入的气。", "cites": [{"t": "生物之以息相吹也。", "b": "《庄子·逍遥游》"}, {"t": "屏息观之。", "b": "明·魏禧《大铁椎传》"}, {"t": "半日复息。", "b": "《汉书·李广苏建传》"}, {"t": "数息可达。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "一息尚存;鼻息", "t": ""}]}, {"meaning": "利息,利钱。", "cites": [{"t": "岁余不入,贷钱者多不能与其息,客奉将不给。", "b": "《史记·孟尝君传》"}], "words": [{"w": "息利", "t": "利息"}, {"w": "息金", "t": "利钱,利息。"}]}, {"meaning": "消息。", "cites": [{"t": "至今已八九日,并无息耗,不免忧疑。", "b": "欧阳修《熙宁四年与大寺丞书》"}], "words": [{"w": "信息", "t": "音信;消息"}, {"w": "息耗", "t": "消息,信息。"}]}, {"meaning": "亲生子女。", "cites": [{"t": "汝息为我子,汝亲为我翁。", "b": "张籍《董公诗》"}], "words": [{"w": "息子", "t": "亲生儿子"}, {"w": "息女", "t": "亲生女儿"}, {"w": "息男", "t": "亲生儿子。"}]}, {"meaning": "春秋时诸侯国名 。故址在今河南省息县北。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1974wx','倔','1','jué juè','亻','10','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从人,屈声。本义:顽强,固执)。"}, {"meaning": "同本义。", "cites": [{"t": "倔强倨傲。", "b": "《盐铁论》"}, {"t": "倔强,谓强梁也。亦双声连语。", "b": "《后汉书·张李彭卢传》注"}], "words": [{"w": "倔僵", "t": "亦作“倔彊”、“倔犟”。强硬直傲,不屈于人。"}]}, {"meaning": "突出的。也作“崛”。", "cites": [{"t": "蹑足行伍之间,而倔起阡陌之中。", "b": "《史记》"}], "words": [{"w": "倔起", "t": "突起,突然兴起。"}]}]}, {"pinyin": "juè", "defs": [{"meaning": "", "words": [{"w": "倔巴;倔然", "t": "生硬鲁莽的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1975wx','徒','1','tú','彳','10','','[{"pinyin": "tú", "defs": [{"meaning": "(形声。从辵(chuò),土声。本义:步行) 同本义。", "cites": [{"t": "徒,步行也。", "b": "《说文》"}, {"t": "我徒我御。", "b": "《诗·小雅·黍苗》"}, {"t": "君子耆老不徒行。", "b": "《礼记·王制》"}, {"t": "徒递来告。", "b": "《国语·吴语》"}, {"t": "无徒骥于锱坛之宫。", "b": "《庄子·徐无鬼》"}, {"t": "败其徒兵于洧上。", "b": "《左传·襄公元年》"}, {"t": "以吾从大夫之后,不可徒行也。", "b": "《论语·先进》"}, {"t": "贲其趾,舍车而徒。", "b": "《易·贲》"}, {"t": "自京师徒步入华山为黄冠。", "b": "顾炎武《复庵记》"}], "words": [{"w": "徒徙", "t": "无舟船乘载而徒步过水"}, {"w": "徒跣", "t": "赤足步行"}, {"w": "徒践", "t": "赤足步行"}, {"w": "徒杠", "t": "供徒步行走的小桥"}, {"w": "徒负", "t": "徒步负荷"}, {"w": "徒行", "t": "步行;无事闲行。"}]}, {"meaning": "步兵,兵卒(周代盛行车战,车上的兵称“甲士”,车后跟着步行的兵叫“徒”)。", "cites": [{"t": "帅徒以往。", "b": "《左传·昭公二十五年》"}], "words": [{"w": "徒骥", "t": "步兵与骑兵"}, {"w": "徒兵,徒卒", "t": "步兵"}, {"w": "徒士", "t": "步兵。没有兵器、铠甲装备的战士"}, {"w": "徒甲", "t": "徒卒和甲士"}, {"w": "徒卫", "t": "卫兵"}, {"w": "徒侯", "t": "徒卒侯吏"}, {"w": "徒师", "t": "步卒,步军。"}]}, {"meaning": "徒党,同一类或同一派别的人。", "cites": [{"t": "原屏咎之徒也。", "b": "《左传·宣公十二年》"}, {"t": "岂为我徒。", "b": "《左传·襄公三十年》"}, {"t": "圣人之徒也。", "b": "《孟子·滕文公下》"}, {"t": "外之有徒,祸乃始牙。", "b": "《管子·版法》"}, {"t": "郯子之徒。", "b": "唐·韩愈《师说》"}, {"t": "佞誉诬谀之徒。", "b": "唐·柳宗元《柳河东集》"}, {"t": "得志之徒。", "b": "明·张溥《五人墓碑记》"}, {"t": "与其徒置酒酣歌。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "党徒;僧徒;教徒;徒属", "t": "随从人员"}, {"w": "徒侣", "t": "徒伴,朋辈;同伴。"}]}, {"meaning": "服徭役的人。", "cites": [{"t": "迁徙之徒。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "徒御", "t": "拉车和驾车的人"}, {"w": "徒役", "t": "服劳役的人"}, {"w": "徒奴", "t": "服劳役的罪犯和奴隶"}, {"w": "徒夫", "t": "服劳役的罪人"}, {"w": "徒士", "t": "服役的人"}, {"w": "徒隶", "t": "服劳役的犯人"}, {"w": "徒孥", "t": "泛指罪犯,犯人。"}]}, {"meaning": "门徒,弟子。", "cites": [{"t": "仲尼之徒。", "b": "《孟子·梁惠王上》"}, {"t": "传诸其徒。", "b": "唐·韩愈《朱文昌校昌黎先生集》"}], "words": [{"w": "徒侣", "t": "门徒;学生"}, {"w": "徒友", "t": "门徒和朋友"}, {"w": "徒羽", "t": "门徒;党羽"}, {"w": "徒党", "t": "门徒;党羽"}, {"w": "徒属", "t": "门徒;部属"}, {"w": "门徒", "t": ""}]}, {"meaning": "奴仆。", "cites": [{"t": "时望甚崇,家徒甚殷。", "b": "白行简《李娃传》"}]}, {"meaning": "独,仅仅。", "cites": [{"t": "徒以喏。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "徒以吾两人在。", "b": ""}, {"t": "徒慕君之高义。", "b": ""}, {"t": "徒见操书。", "b": "《资治通鉴》"}], "words": [{"w": "不徒无益,反而有害;徒有其表", "t": ""}]}, {"meaning": "徒然,枉然。", "cites": [{"t": "徒留无所施。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "老大徒伤悲。", "b": "《乐府诗集·长歌行》"}, {"t": "徒见欺。", "b": "《史记·廉颇蔺相列传》"}, {"t": "徒糜弹药。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "徒苦", "t": "徒然受苦;白吃苦"}, {"w": "徒恨", "t": "徒然抱恨"}, {"w": "徒食", "t": "空坐以食而无所事事"}, {"w": "徒善", "t": "空有善心"}, {"w": "徒尔;徒说", "t": "白说;空说"}, {"w": "徒语", "t": "徒言,白说"}, {"w": "徒处", "t": "无所为"}, {"w": "徒设", "t": "虚设。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1976wx','徐','1','xú','彳','10','','[{"pinyin": "xú", "defs": [{"meaning": "(形声。从彳(chì),余声。双人旁与行走有关。本义:慢步走)。"}, {"meaning": "同本义。", "cites": [{"t": "徐,安行也。", "b": "《说文》"}, {"t": "乃徐有说。", "b": "《易·困》。虞注:“坤为徐。”"}, {"t": "徐其攻而留其日。", "b": "《战国策·宋策》"}, {"t": "故其疾如风,其徐如林。", "b": "《孙子·军争》"}, {"t": "摄提运衡,徐至于射宫。", "b": "《文选·张衡·东京赋》"}]}, {"meaning": "散开。", "cites": [{"t": "執徐之岁,岁早旱,晚水。", "b": "《淮南子》"}]}, {"meaning": "缓慢。", "cites": [{"t": "不徐不疾,得之于手而应于心。", "b": "《庄子·天道》"}, {"t": "入而徐趋。", "b": "《战国策·赵策》"}, {"t": "此事当徐议之。", "b": "《宋史》"}, {"t": "徐有得也。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "徐而察之。", "b": "宋·苏轼《石钟山记》"}, {"t": "余韵徐歇。", "b": ""}, {"t": "徐以杓酌油沥之。", "b": "宋·欧阳修《归田录》"}, {"t": "清风徐来,水波不兴。", "b": "苏轼《前赤壁赋》"}], "words": [{"w": "徐议", "t": "从容商议"}, {"w": "清风徐来;徐回", "t": "缓慢地回旋运转"}, {"w": "徐行", "t": "缓慢前行"}, {"w": "徐步", "t": "缓慢步行"}, {"w": "徐呼", "t": "发声舒缓的弱音"}, {"w": "徐疾", "t": "或慢或快。"}]}, {"meaning": "安闲的样子。", "cites": [{"t": "宜为人主,安徐而重固。", "b": "《国语》"}], "words": [{"w": "徐言", "t": "缓言;低声细语"}, {"w": "徐婉", "t": "舒缓委婉"}, {"w": "徐详", "t": "舒缓安详。"}]}, {"meaning": "全,都", "cites": [{"t": "鲁人徐伤归父之无后也。", "b": "《公羊传·成公十五年》"}]}, {"meaning": "古州名。古徐州的简称 ,古九州之一。古徐州约在今江苏、山东、安徽的部分地区。汉以后各代皆置徐州,辖地常有变更,大致都在今淮北一带。多以彭城(今江苏徐州市)或下邳(今江苏邳县)为治所。"}, {"meaning": "古国名。", "cites": [{"t": "仁义而徐亡。", "b": "《韩非子·五蠹》"}, {"t": "循徐鲁之力。", "b": ""}]}, {"meaning": "", "cites": [{"t": "徐夫人(姓徐,名夫人。一个收藏匕首的人)", "b": ""}]}, {"meaning": "——《战国策·燕策》。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1977wx','殷','1','yān yīn','殳','10','','[{"pinyin": "yān", "defs": [{"meaning": "黑红色", "words": [{"w": "殷妍", "t": "红艳"}, {"w": "殷殷", "t": "殷红的样子"}]}]}, {"pinyin": "yīn", "defs": [{"meaning": "(会意。从殷从殳。本义:盛乐)。", "cites": [{"t": "殷,作乐之盛称殷。", "b": "《说文》。按,殷者,舞之容,殳者,舞之器。"}, {"t": "五年而殷祭。", "b": "《公羊传·文公二年》"}, {"t": "服除而后殷祭。", "b": "《礼记·曾子问》"}, {"t": "月半不殷奠。", "b": "《仪礼·士丧礼》"}, {"t": "先王以作乐崇德,殷荐之上帝,以配祖考。", "b": "《易·豫》。王弼注:“用此殷盛之乐荐祭上帝也。”"}, {"t": "神其来思,时歆荐殷。", "b": "《金史》"}]}, {"meaning": "大。", "cites": [{"t": "殷,大也;众也。", "b": "《广雅》"}, {"t": "夫精,小之微也;郛,大之殷也。", "b": "《庄子》"}], "words": [{"w": "殷奠", "t": "大祭"}, {"w": "殷喜", "t": "大喜"}, {"w": "殷祭", "t": "盛大的祭典"}, {"w": "殷袔", "t": "天子、诸侯在太庙对远近祖先的盛大合祭"}, {"w": "殷殷轸轸", "t": "盛大众多的样子"}, {"w": "殷礼", "t": "盛大的祭礼"}, {"w": "殷事", "t": "指初一、十五日的盛大祭祀。"}]}, {"meaning": "众,多。", "cites": [{"t": "士与女,殷其盈矣。", "b": "《诗·郑风·溱洧》"}], "words": [{"w": "殷大", "t": "众多"}, {"w": "殷众", "t": "众多"}, {"w": "殷猥", "t": "繁杂"}, {"w": "殷远", "t": "繁多而深远"}, {"w": "殷碎", "t": "繁杂琐碎"}, {"w": "殷广", "t": "繁多而广泛"}, {"w": "殷繁", "t": "繁多;众多"}, {"w": "殷旷", "t": "繁多而拖延日久。"}]}, {"meaning": "盛。", "cites": [{"t": "殷岩泉。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "殷盛", "t": "茂盛;繁盛"}, {"w": "殷流", "t": "盛行"}, {"w": "殷殷屯屯", "t": "繁盛的样子"}, {"w": "殷炽", "t": "殷阗。繁盛"}, {"w": "殷草", "t": "茂盛的草。"}]}, {"meaning": "富裕。", "cites": [{"t": "民殷国富。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "殷户", "t": "殷实的人家"}, {"w": "殷充", "t": "充裕,丰盛"}, {"w": "殷足", "t": "殷实,富足"}, {"w": "殷昌", "t": "富庶,昌盛"}, {"w": "殷阜", "t": "富足"}, {"w": "殷厚", "t": "殷实,富裕"}, {"w": "殷然", "t": "充裕"}, {"w": "殷强", "t": "富裕强健"}, {"w": "殷饶", "t": "富饶,富裕"}, {"w": "殷盈", "t": "丰盈,富足。"}]}, {"meaning": "深,深切。", "cites": [{"t": "在殷忧而弗违。", "b": "陆机《叹逝赋》"}, {"t": "情意甚殷。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "殷握", "t": "深深地了解;掌握"}, {"w": "殷谢", "t": "深切致谢。"}]}, {"meaning": "恳切。", "cites": [{"t": "书中情意其殷。", "b": "宗臣《报刘一丈书》"}], "words": [{"w": "殷挚", "t": "恳切诚挚"}, {"w": "殷重", "t": "恳切深厚。"}]}, {"meaning": "殷朝 。公元前14世纪到公元前11世纪,是商代迁都于殷(今河南省安阳市西北小屯村)后改用的称号。", "cites": [{"t": "殷周之世。", "b": "《韩非子·五蠹》"}], "words": [{"w": "殷士", "t": "殷人"}, {"w": "殷正", "t": "殷历正月。相当于农历十一月"}, {"w": "殷冬", "t": "旧历十一月"}, {"w": "殷民", "t": "殷商的百姓。亦指殷代遗民"}, {"w": "殷宗", "t": "殷人的宗祀。指殷朝"}, {"w": "殷契", "t": "殷墟书契的省称,即殷商甲骨文字"}, {"w": "殷理", "t": "刑法"}, {"w": "殷虚", "t": "殷墟"}, {"w": "殷见", "t": "殷同。周代各方诸侯于一年四季分批朝见天子"}, {"w": "殷国", "t": "周代天子在侯国行殷见之礼"}, {"w": "殷历", "t": "起于周末而传于汉初的六种古历之一;亦指殷商时所用历法。"}]}, {"meaning": "古都邑名 ,在今河南省安阳市小屯村,商的第十代君王盘庚迁都于此。后世称为“殷墟”。"}, {"meaning": "深厚的情意。", "cites": [{"t": "有怀载殷。", "b": "张昭远《旧唐书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1978wx','舰','1','jiàn','舟','10','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从舟,监声。本义:大型的战船)。"}, {"meaning": "同本义。", "cites": [{"t": "舰,版屋舟。", "b": "《玉篇》"}, {"t": "舰,御敌船", "b": ""}, {"t": "舳舻千里,前驱不过百舰。", "b": "《文选·陆机·辨亡论下》"}, {"t": "方连船舰。", "b": "《资治通鉴》"}, {"t": "十舰最著前。", "b": ""}, {"t": "北舰十余里。", "b": "宋·文天祥《 后序》"}], "words": [{"w": "巡洋舰;驱逐舰;航空母舰;舰户", "t": "船舰的门户。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1979wx','舱','1','cāng','舟','10','','[{"pinyin": "cāng", "defs": [{"meaning": "(形声。从舟,仓声。本义:船上居人置物的部位)。"}, {"meaning": "船或飞机中分隔开来载人或装东西的部分。", "cites": [{"t": "中轩敞者为舱。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "客舱", "t": ""}]}, {"meaning": "船上用来盛水、油或液体的分隔仓柜。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1980wx','般','1','bān bō pán','舟','10','','[{"pinyin": "bān", "defs": [{"meaning": "种,类。", "cites": [{"t": "草木知春不久归,百般红紫斗芳菲。", "b": "唐·韩愈《晚春》"}], "words": [{"w": "这般东西;百般劝解;般般", "t": "种种;样样;件件。"}]}, {"meaning": "搬运。", "cites": [{"t": "般,运也。", "b": "《玉篇》"}, {"t": "自行般运出卖以办岁计。", "b": "《资治通鉴》"}], "words": [{"w": "般运", "t": "搬担。搬运"}, {"w": "般剥", "t": "搬运,驳运。"}]}, {"meaning": "布,颁布。", "cites": [{"t": "灵之来,神哉沛,先以雨,般裔裔。", "b": "《汉书·礼乐志》"}]}, {"meaning": "斑纹。", "cites": [{"t": "马黑脊而般臂蝼。", "b": "《周礼·内饔》"}, {"t": "般般之兽。", "b": "《史记·司马相如传》。索隐:“般般,文采之貌也。”"}]}]}, {"pinyin": "bō", "defs": []}, {"pinyin": "pán", "defs": [{"meaning": "大船。", "cites": [{"t": "般,大船也。", "b": "《玉篇》"}]}, {"meaning": "水边的高地。", "cites": [{"t": "般,水涯堆也。", "b": "《汉书音义》"}]}, {"meaning": "囊。", "cites": [{"t": "诸母般。", "b": "《谷梁传》。范宁注:“般,囊也。所以盛朝夕所须。”"}]}, {"meaning": "大。", "cites": [{"t": "般,大也。", "b": "《广雅》"}, {"t": "般乐怠敖,是自求祸也。", "b": "《孟子·公孙丑上》"}, {"t": "般乐饮酒。", "b": "《孟子·尽心下》"}], "words": [{"w": "般乐", "t": "大肆作乐。"}]}, {"meaning": "相连。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1981wx','航','1','háng','舟','10','','[{"pinyin": "háng", "defs": [{"meaning": "船;方舟。", "cites": [{"t": "航,船也。", "b": "《广韵》"}, {"t": "航,方舟也。本作斻。", "b": "《集韵》"}, {"t": "大者以为舟航柱梁。", "b": "《淮南子·主术》"}, {"t": "譬临河而无航。", "b": "《后汉书·张衡传》"}, {"t": "长鲸吞航。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "航人", "t": "船夫。"}]}, {"meaning": "渡过。", "cites": [{"t": "峡甚逼仄,故一木航之。", "b": "《徐霞客游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1982wx','途','1','tú','辶','10','','[{"pinyin": "tú", "defs": [{"meaning": "(形声。从辵(chuò),余声。本义:道路)。"}, {"meaning": "同本义。", "cites": [{"t": "途,道也。", "b": "《广韵》"}, {"t": "徐亦训道。字古借涂,后变作途。又作塗。", "b": "朱骏声《说文通训定声》"}, {"t": "堂途谓之陈。又,路,旅途也。", "b": "《尔雅·释宫》"}, {"t": "当途梧邱。", "b": "《尔雅·释邱》"}, {"t": "而不利说途也。", "b": "《战国策·齐策》"}, {"t": "经途九轨。", "b": "张衡《东京赋》"}, {"t": "长揖当途人。", "b": "郭璞《游仙诗》。注:“当仕路也。”"}, {"t": "天明登前途。", "b": "唐·杜甫《石壕吏》"}, {"t": "仁义之途。", "b": "唐·韩愈《朱文昌校昌黎先生集》"}, {"t": "负者歌于途。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "无速其途。", "b": ""}, {"t": "途中两狼,缀行甚远。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "途轨", "t": "路途"}, {"w": "途辙", "t": "路上之车迹"}, {"w": "途毙", "t": "因贫病冻饿而死在道路上"}, {"w": "途说", "t": "道途之说"}, {"w": "途陌", "t": "道路"}, {"w": "途水", "t": "取道水路"}, {"w": "通途;沿途;归途;长途跋涉", "t": ""}]}, {"meaning": "职位。", "cites": [{"t": "时辈多得途,亲朋屡相敕。", "b": "元稹《寄吴士矩端公五十韵》"}]}, {"meaning": "途径;路子。", "cites": [{"t": "古之立国家者,开本末之途,通有无之用。", "b": "《盐铁论·本议》"}], "words": [{"w": "途程", "t": "方法,办法"}, {"w": "途途是道", "t": "头头是道。说话或做事很有条理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1983wx','拿','1','ná','手','10','','[{"pinyin": "ná", "defs": [{"meaning": "(会意。手合起来,表示握持,字本作“挐”。从手。奴声。本义:握持)。"}, {"meaning": "同本义。", "cites": [{"t": "手里拿串拍板。", "b": "《水浒传》"}], "words": [{"w": "从架上拿书;用钳子拿钉子;他拿起帽子和大衣走了;别拿我的东西", "t": ""}]}, {"meaning": "捉拿。", "cites": [{"t": "差人拿不将他来;差人都合他是一个人,谁肯拿他?", "b": "《醒世姻缘传》"}], "words": [{"w": "缉拿", "t": "搜查捉拿"}, {"w": "拿不将", "t": "拿不了"}, {"w": "拿究", "t": "捉拿查究"}, {"w": "拿捕", "t": "捉拿;逮捕"}, {"w": "拿访", "t": "捉拿查访"}, {"w": "拿送", "t": "逮捕解送"}, {"w": "拿解", "t": "逮捕解送。"}]}, {"meaning": "刁难。", "cites": [{"t": "因怕金桂拿他,所以不敢透漏。", "b": "《红楼梦》"}], "words": [{"w": "拿把;拿捏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1984wx','耸','1','sǒng','耳','10','','[{"pinyin": "sǒng", "defs": [{"meaning": "(形声。从耳,从声。本义:耳聋) 同本义。", "cites": [{"t": "子野听耸,离朱目眩。", "b": "马融《广成颂》"}, {"t": "耸,聋也…生而聋,陈、楚、江、淮之间谓之耸。荆阳之间及山之东西双聋者谓之耸。", "b": "《方言》。郭璞注:“言无所闻常耸耳也。”"}], "words": [{"w": "耸昧", "t": "既聋又瞎。即昏瞶。"}]}, {"meaning": "高起;矗立。", "cites": [{"t": "予观雁荡诸峰,皆峭拔险,上耸千尺。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "耸人瞻仰", "t": "众人耸立瞻仰"}, {"w": "耸秀", "t": "高耸秀丽"}, {"w": "耸出", "t": "高耸突出"}, {"w": "耸耳", "t": "高起的耳朵;竖起耳朵"}, {"w": "耸然", "t": "高耸貌"}, {"w": "耸峭", "t": "高耸陡峭"}, {"w": "耸突", "t": "高耸突起"}, {"w": "耸干", "t": "高挺的树干"}, {"w": "耸擢", "t": "高耸突出"}, {"w": "耸耸", "t": "竖起貌;挺立貌"}, {"w": "耸翠", "t": "形容山峦、树木等高耸苍翠。"}]}, {"meaning": "比喻出众,不凡。", "cites": [{"t": "又有一人,披紫裳,执青玉,貌耸神溢,立于君左。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "耸壑昂霄", "t": "矗立山谷间,高耸入云霄。比喻超拔出众,出人头地。"}]}, {"meaning": "劝勉。", "cites": [{"t": "教之春秋而为之,耸善而抑恶焉。", "b": "《国语·楚语上》。又如:耸恿(劝说);耸劝(劝导;警惕自勉)"}]}, {"meaning": "惊动;惊惧。", "cites": [{"t": "耸之以行。", "b": "《左传·昭公元年》"}, {"t": "驷氏耸。", "b": "《左传·昭公十九年》"}, {"t": "身耸除洁。", "b": "《国语·周语下》"}, {"t": "体轻似无骨,观者皆耸神。", "b": "刘禹锡《观柘枝舞》"}], "words": [{"w": "危言耸听;耸惧", "t": "恐惧。即悚惧"}, {"w": "耸激", "t": "犹激励"}, {"w": "耸踊", "t": "欢腾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1985wx','爹','1','diē','父','10','','[{"pinyin": "diē", "defs": [{"meaning": "(形声。从父,多声。本义:父亲)。"}, {"meaning": "对老者、长者的尊称。", "cites": [{"t": "女(徐七娘)常呼项[四郎] 为阿爹…", "b": "王明清《摭青杂说》"}]}, {"meaning": "旧时对官长的尊称或作官长的代称。", "cites": [{"t": "比及爹有这个心,小人打听在肚里了。", "b": "关汉卿《鲁斋郎》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1986wx','舀','1','yǎo','臼','10','','[{"pinyin": "yǎo", "defs": [{"meaning": "(会意。上为“爪”,下为“臼”(jiù),象伸手掏取之形。本义:用瓢勺取物) 同本义", "words": [{"w": "舀一瓢水", "t": ""}, {"w": "舀粥", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1987wx','爱','1','ài','爫','10','','[{"pinyin": "ài", "defs": [{"meaning": "(形声。从心,旡(jì)声。本义:亲爱;喜爱)。"}, {"meaning": "对人或事物有深厚真挚的感情。", "cites": [{"t": "惠,爱也。", "b": "《尔雅》"}, {"t": "爱施者,仁之端也。", "b": "《说苑·说丛》"}, {"t": "君子自爱,仁之至也。", "b": "《法言》"}, {"t": "爱亲者不敢恶于人。", "b": "《孝经》。沈宏曰:“亲至结心为爱。”"}, {"t": "爱共叔段,欲立之。", "b": "《左传·隐公元年》"}, {"t": "停车坐爱枫林晚,霜叶红于二月花。", "b": "杜牧《山行》"}, {"t": "父母之爱子也,则为之计深远。", "b": "《战国策》"}, {"t": "公夫人甚爱女。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "爱其子,择师而教之。", "b": "唐·韩愈《师说》"}, {"t": "非疏骨肉爱过客。", "b": "《韩非子·五蠹》。"}], "words": [{"w": "爱幸", "t": "喜爱宠幸"}, {"w": "爱乐", "t": "喜爱"}, {"w": "爱敬", "t": "亲爱恭敬;喜爱敬重"}, {"w": "爱劳动;爱祖国;爱人民", "t": ""}]}, {"meaning": "男女间有情。", "cites": [{"t": "结发为夫妻,恩爱两不疑。", "b": "《古诗四首》之三,见《文选》卷二十九"}, {"t": "孟尝君舍人有与君之夫人相爱者。", "b": "《战国策·齐策》。"}], "words": [{"w": "爱色", "t": "喜欢女色。"}]}, {"meaning": "喜好。", "cites": [{"t": "爱听古人节义事。", "b": "清·袁枚《祭妹文》"}, {"t": "晋陶渊明独爱菊。", "b": "宋·周敦颐《爱莲说》"}, {"t": "秦爱纷奢,人亦念其家。", "b": "杜牧《阿房宫赋》。"}], "words": [{"w": "爱玩", "t": "爱好玩赏。后用以指爱好的玩物或对游玩的喜好。"}]}, {"meaning": "爱护。", "cites": [{"t": "吴广素爱人。", "b": "《史记·陈涉世家》"}, {"t": "好自将爱,一年便健。", "b": "《三国志·方伎传》。"}], "words": [{"w": "爱人以德", "t": "按照道德标准去爱护帮助他人"}, {"w": "爱物", "t": "爱护万物。"}]}, {"meaning": "爱惜,珍惜。", "cites": [{"t": "爱莫助之。", "b": "《礼记·表记》。注:“犹惜也。”"}, {"t": "千金之子,不死于盗贼,何哉?其身之可爱,而盗贼不足以死也。", "b": "苏轼《留侯论》"}, {"t": "尔爱其羊,我爱其礼。", "b": "《论语·八佾》"}, {"t": "不爱死,义也。", "b": "柳宗元《驳复仇议》"}, {"t": "国事至此,予不得爱身。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "爱身", "t": "爱惜生命,贪生怕死。"}]}, {"meaning": "舍不得;吝惜。", "cites": [{"t": "齐国虽褊小,吾何爱一牛。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "又。", "cites": [{"t": "百姓皆以王为爱也。", "b": ""}, {"t": "是故甚爱必大费,多藏必厚亡。", "b": "《老子》四十四章"}, {"t": "不爱珍器重宝肥饶之地。", "b": "汉·贾谊《过秦论》。"}], "words": [{"w": "爱吝", "t": "爱惜,吝啬。"}]}, {"meaning": "贪。", "cites": [{"t": "文臣不爱钱,武臣不惜死,天下平矣。", "b": "《宋史·岳飞传》"}]}, {"meaning": "友爱。", "cites": [{"t": "兄爱弟敬。", "b": "《左传·隐公三年》"}]}, {"meaning": "怜悯、怜恤、同情。", "cites": [{"t": "若爱重伤,则如勿伤;爱其二毛,则如服焉。", "b": "《左传·僖公二十二年》"}]}, {"meaning": "惠;仁爱。", "cites": [{"t": "古之遗爱也。", "b": "《左传·昭公二十年》"}, {"t": "爱多者则法不立,威寡者则下侵上。", "b": "《韩非子》。"}], "words": [{"w": "爱惠", "t": "仁慈恩惠。"}]}, {"meaning": "尊称对方的女儿为“令爱”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1988wx','豺','1','chái','豸','10','','[{"pinyin": "chái", "defs": [{"meaning": "(形声。从豸(zhì),才声。从“豸”,表示与野兽有关。本义:野兽名。形似犬而残猛如狼,俗名豺狗) 同本义。", "cites": [{"t": "豺,狼属,狗声。", "b": "《说文》。字亦作犲。"}, {"t": "豺,狗足。", "b": "《尔雅》"}, {"t": "豺似狗,白色,有爪牙。迅捷,善搏噬也。", "b": "《苍颉篇·解诂》"}, {"t": "豺则祭兽。", "b": "《吕氏春秋·季秋》。注:“似狗而长毛,其色黄。"}, {"t": "搏豺狼。", "b": "《史记·司马相如传》"}, {"t": "曹公,豺虎也。", "b": "《资治通鉴》"}]}, {"meaning": "按,一种野犬,比狼小,毛色较黄,胆子也较狼小,有时夜间成群猎食,但多半是单独或成对出猎,主要吃腐肉或小动物(如家禽)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1989wx','豹','1','bào','豸','10','','[{"pinyin": "bào", "defs": [{"meaning": "(形声。从豸,勺声。“豸”(zhì),象形字,本指长脊的野兽。本义:豹子) 同本义。", "cites": [{"t": "豹,似虎圆文。", "b": "《说文》"}, {"t": "南山兽多猛豹。", "b": "《山海经·南山经》"}], "words": [{"w": "豹尾", "t": "豹的尾巴;用豹尾做装饰的车或旗等"}, {"w": "豹跳", "t": "暴跳;躁怒之相"}, {"w": "豹隐", "t": "喻隐居。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1990wx','颁','1','bān','页','10','','[{"pinyin": "bān", "defs": [{"meaning": "(形声。从页,分声。“页”本音念xié,意思是头,汉字部首之一。从“页”的字多与头有关。(fén)本义:脑袋很大的样子) 鬓。", "cites": [{"t": "颁,一曰鬓也。", "b": "《说文》"}, {"t": "谨庠序之教,申之以孝悌之义,颁白者不负戴于道路矣。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "颁白", "t": "指鬓发花白。同斑白。"}]}, {"meaning": "又假借为“攽”。颁发;分赏。", "cites": [{"t": "匪颁之式。", "b": "《周礼·大宰》。司农注:“谓班赐也。”"}, {"t": "遂颁禽。", "b": "《周礼·小宗伯》。注:“谓以予群臣。”"}, {"t": "以时颁其衣裘。", "b": "《周礼·天官·宫伯》"}, {"t": "颁爵位。", "b": "《礼记·礼运》"}, {"t": "出御府珠玉玩好之物,颁赐王公以下各有差。", "b": "《晋书》"}, {"t": "凡有颁犒,均给军吏。", "b": "《宋史·岳飞传》"}, {"t": "昔先皇颁僧保所货西洋珠于侍臣,某得八焉。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "颁奖", "t": "分发奖品"}, {"w": "颁赉", "t": "同颁赐"}, {"w": "颁禽", "t": "古时天子四季田猎,将所获猎物分赐群臣,称为颁禽。"}]}, {"meaning": ",发布;公布。", "cites": [{"t": "颁,布也。", "b": "《小尔雅》"}, {"t": "颁告朔于邦国。", "b": "《周礼·大史》"}, {"t": "秋颁学。", "b": "《周礼·大胥》"}, {"t": "颁度量而天下大服。", "b": "《礼记·明堂位》"}], "words": [{"w": "颁布", "t": "公布"}, {"w": "颁诏", "t": "皇帝公布命令。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1991wx','颂','1','sòng','页','12','','[{"pinyin": "sòng", "defs": [{"meaning": "(形声。从页(xié),公声。从“页”的字一般与“头”有关。本义:容貌,仪容)。"}, {"meaning": "同本义。", "cites": [{"t": "颂,貌也。", "b": "《说文》"}, {"t": "鲁徐生善为颂。", "b": "《汉书·儒林传》"}, {"t": "庶考斯之颂仪。", "b": "《杨统碑》。经传皆以容为之。"}]}, {"meaning": "这个意义后来写作“容”。"}, {"meaning": "占兆之词。", "cites": [{"t": "其颂皆千有二百。", "b": "《周礼·大卜》"}]}, {"meaning": "《诗经》的六义之一 。与风、雅、赋、比、兴合称六义。指《诗经》中三种诗歌类型之一,即收集在《周颂》、《鲁颂》、《商颂》中的祭祀时用的舞曲歌辞。"}, {"meaning": "歌颂。", "cites": [{"t": "从天而颂之,孰与制天命而用之。", "b": "《荀子·天论》"}, {"t": "什一行而颂声作矣。", "b": "《公羊传·宣公十五年》"}], "words": [{"w": "颂椒", "t": "歌颂皇后"}, {"w": "颂子", "t": "文体的一种"}, {"w": "颂古", "t": "佛家语。指选过去的公案,用诗句来颂出它的思想精义"}, {"w": "颂美", "t": "赞扬他人的功德。"}]}, {"meaning": "朗读。", "cites": [{"t": "颂其诗,读其书。不知其人,可否?", "b": "《孟子·万章下》"}, {"t": "少为书生,家以农亩为业,而专精颂读,昼夜不息。", "b": "《后汉书·逸民传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1992wx','翁','1','wēng','羽','10','','[{"pinyin": "wēng", "defs": [{"meaning": "(形声。从羽,公声。本义:鸟颈毛)。"}, {"meaning": "同本义。", "cites": [{"t": "翁,颈毛也。", "b": "《说文》"}, {"t": "鸟头上毛曰翁。翁,一身之最上。", "b": "唐·玄应《一切经音义》"}]}, {"meaning": "假借为“公”。父亲。", "cites": [{"t": "翁,父也。", "b": "《广雅·释亲》"}, {"t": "吾翁及汝翁。", "b": "《汉书·项藉传》"}], "words": [{"w": "翁媪", "t": "年老的父母。同“翁妪”。"}]}, {"meaning": "泛称男性老人。", "cites": [{"t": "凡尊老,周晋秦陇谓之公,或谓之翁。", "b": "《方言》六"}, {"t": "卖炭翁。", "b": "唐·白居易《卖炭翁》"}, {"t": "老翁逾墙走。", "b": "唐·杜甫《石壕吏》"}, {"t": "独与老翁别。", "b": ""}, {"t": "卖油翁。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "塞翁失马;渔艄翁;翁翁", "t": "祖父;对老年男子的尊称"}, {"w": "翁甫", "t": "对老者的尊称"}, {"w": "翁长", "t": "对老者的尊称。"}]}, {"meaning": "腾涌。", "cites": [{"t": "俞樾议:“翁当为滃。《文选·江赋》曰:‘气滃渤而雾杳。’翁博犹滃渤也,博与渤亦一声之转。”", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1993wx','胰','1','yí','月','10','','[{"pinyin": "yí", "defs": [{"meaning": "胰腺  一种大的复合性消化腺,位于第一腰椎的前方,胃的后方,形状略似铁锤,胰头被十二指肠环绕,通过胰管胆总管合成胆胰管后与十二指肠相通。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1994wx','脆','1','cuì','月','10','','[{"pinyin": "cuì", "defs": [{"meaning": "(会意。从肉,绝省声。本义:易折断)。"}, {"meaning": "同本义。", "cites": [{"t": "其脃易泮。", "b": "《老子》"}, {"t": "脃薄。", "b": "《后汉书·许荆传》"}, {"t": "华而不实,脆而不坚。", "b": "毛泽东《改造我们的学习》"}], "words": [{"w": "脆断", "t": "脆而折断"}, {"w": "脆薄", "t": "不坚牢"}, {"w": "脆帮根儿咬", "t": "比喻做事应抓住主要矛盾"}, {"w": "脆促", "t": "生命脆弱而短暂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1995wx','脂','1','zhī','月','10','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从肉,旨声。本义:动植物所含的油脂)。"}, {"meaning": "同本义。", "cites": [{"t": "脂,戴角者脂,无角者膏。", "b": "《说文》"}, {"t": "有羽者脂。", "b": "《易·本命》"}, {"t": "脂,肪也。", "b": "《广苍》"}, {"t": "脂膏以膏之。", "b": "《礼记·内则》。疏:“凝者为脂,释者为膏。"}, {"t": "肤如凝脂。", "b": "《诗·卫风·硕人》"}, {"t": "宗庙之事,脂者膏者以为牲。", "b": "《周礼·考工记·梓人》"}], "words": [{"w": "脂灰", "t": "油脂和石灰,犹今油灰之类"}, {"w": "脂水", "t": "旧指妇人盥洗后的剩水;或指石油;脓水"}, {"w": "脂炬", "t": "即脂烛"}, {"w": "脂韦", "t": "油脂和软皮。"}]}, {"meaning": "胭脂。", "cites": [{"t": "邀人傅脂粉,不自着罗衣。", "b": "王维《西施咏》"}], "words": [{"w": "脂粉客", "t": "油头粉面的风流子弟"}, {"w": "脂粉钱", "t": "旧指女私蓄。"}]}, {"meaning": "涂油使润滑。", "cites": [{"t": "我车已载脂。", "b": "杜甫《赤谷》"}], "words": [{"w": "脂车", "t": "油涂车轴,以利运转。借指驾车出行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1996wx','胸','1','xiōng','月','10','','[{"pinyin": "xiōng", "defs": [{"meaning": "(形声。从肉,匈声。本作“匈”,胸是后起字。本义:胸膛)。"}, {"meaning": "同本义。", "cites": [{"t": "胸满腹胀。", "b": "《素问·腹中论》"}, {"t": "两手紧抱胸前。", "b": "宋·宋慈《洗冤录》"}], "words": [{"w": "胸雪", "t": "雪白的胸部。倒文。多见于五代词。"}]}, {"meaning": "内心;心里。", "cites": [{"t": "忧苦欲何为,缠绵胸与臆。", "b": "晋·陆机《赴洛》"}], "words": [{"w": "胸衾", "t": "胸怀;胸襟"}, {"w": "胸藏锦绣", "t": "比喻富有才识"}, {"w": "胸藏翰墨", "t": "比喻极有学识"}, {"w": "胸中大有丘壑", "t": "比喻思虑深远;亦作胸中有了丘壑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1997wx','胳','1','gē gé','月','10','','[{"pinyin": "gē", "defs": [{"meaning": "(形声。从肉,各声。本义:腋下) 同本义。", "cites": [{"t": "胳谓之腋。", "b": "《广雅》"}, {"t": "胳,腋下也。", "b": "《说文》"}, {"t": "肘后曰胳。", "b": "《埤苍》"}, {"t": "胳之高下可以运肘。", "b": "《礼记·深衣》。俗字作袼。"}]}]}, {"pinyin": "gé", "defs": [{"meaning": "牲畜的后胫骨"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1998wx','脏','1','zāng zàng','月','10','','[{"pinyin": "zāng", "defs": [{"meaning": "弄污。", "cites": [{"t": "咱一来是为行好,二来也怕脏了我的店。", "b": "《儿女英雄传》"}]}]}, {"pinyin": "zàng", "defs": [{"meaning": "(形声。左形,右声。本义:中医学以心、肝、脾、肺、肾为五脏。后因以为身体内脏的通称)同本义。", "cites": [{"t": "脏,五脏也。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('1999wx','脐','1','qí','月','10','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从肉,齐声。本义:肚脐)。"}, {"meaning": "螃蟹腹部的厣,雌者圆形称“团脐”,雄者尖形称“尖脐”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2000wx','胶','1','jiāo','月','10','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。古代“胶”用动物的皮煮制而成,所以从“肉”。段玉裁说:“皮近肉,故字从肉。”本义:粘性物质,用动物的皮角或树脂制成)。"}, {"meaning": "同本义。", "cites": [{"t": "胶也者,以为和也。", "b": "《考工记·弓人》"}], "words": [{"w": "胶鳔", "t": "用鱼鳔煮治而成的胶"}, {"w": "胶漆", "t": "胶与漆。比喻事物的结合非常紧密;或比喻交情深厚"}, {"w": "胶青", "t": "胶清。已制成的色质纯正的胶质"}, {"w": "胶革", "t": "用皮革熬成的胶。"}]}, {"meaning": "橡胶。"}, {"meaning": "", "cites": [{"t": "胶鬲举于鱼盐之中。(胶鬲起初是鱼盐贩子。西伯(文王)发现了他,举荐给商纣王。)", "b": "《孟子·告子下》"}]}, {"meaning": "牢固。", "cites": [{"t": "德音孔胶。", "b": "《诗·小雅·隰桑》"}], "words": [{"w": "胶固", "t": "牢固。"}]}, {"meaning": "诡辩的。", "cites": [{"t": "胶,诈也。", "b": "《方言三》"}, {"t": "胶,欺也。", "b": "《广雅》"}, {"t": "牵胶而喻侈。", "b": "左思《魏都赋》"}], "words": [{"w": "胶言", "t": "诡辩不合法度的言论。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2001wx','脑','1','nǎo','月','10','','[{"pinyin": "nǎo", "defs": [{"meaning": "(形声。本义:脑髓)。"}, {"meaning": "同本义。", "cites": [{"t": "匘,头髓也。从匕,匕,相比著也。巛象发,囟象脑形。", "b": "《说文》。按,囟头会匘盖也。字亦作腦。"}, {"t": "蹙于(脑)而休于气。", "b": "《考工记·弓人》"}, {"t": "其荣发也。", "b": "《素问·五藏生气篇》。注:“脑为髓海。”"}, {"t": "人精在脑。", "b": "《春秋元命苞》"}, {"t": "晋侯梦与楚子搏,楚子伏己而盐其脑,是以惧。", "b": "《左传·僖公二十八年》"}]}, {"meaning": "头部。", "cites": [{"t": "云台之高,堕者拆脊碎脑。", "b": "《淮南子·俶真》"}], "words": [{"w": "脑箍", "t": "用刑时套在头上的刑具"}, {"w": "脑揪", "t": "揪住头发"}, {"w": "摇头晃脑;脑瓜;脑杓", "t": "头的后部"}, {"w": "脑后", "t": "头的后部。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2002wx','脓','1','nóng','月','10','','[{"pinyin": "nóng", "defs": [{"meaning": "(形声。从肉,农声。本义:从疮口流出的黄绿色粘液) 同本义。", "cites": [{"t": "脓血流离。", "b": "《聊斋志异·促织》"}], "words": [{"w": "脓血", "t": "脓和血的混合物"}, {"w": "脓团", "t": "脓包。身体局部组织化脓时因脓液积聚而形成的隆起物。"}]}, {"meaning": "腐烂。", "cites": [{"t": "稻苗长七八寸,陈草复起,以镰水芟之,草悉脓死。", "b": "《齐民要术》"}]}, {"meaning": "肥硕。", "cites": [{"t": "玄熊素肤,肥豢脓肌。", "b": "《文选·曹植·七启八首》"}]}, {"meaning": "浓厚。特指浓烈的酒。", "cites": [{"t": "甘脆肥脓,命之腐肠之药。", "b": "汉·枚乘《七发》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2003wx','逛','1','guàng','辶','10','','[{"pinyin": "guàng", "defs": [{"meaning": "外出散步;闲游;游览。", "cites": [{"t": "平生最喜游山逛水。", "b": "宗璞《西湖漫笔》"}], "words": [{"w": "逛庙", "t": "赶庙会"}, {"w": "逛厂", "t": "指逛游北京琉璃厂一带集市"}, {"w": "逛膀子", "t": "闲游"}, {"w": "逛景", "t": "游览景致。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2004wx','狸','1','lí','犭','10','','[{"pinyin": "lí", "defs": [{"meaning": "(狸为貍的俗字。形声。从豸(zhì),长脊的野兽,里声。本义:狸子,也叫野猫、山猫)。"}, {"meaning": "同本义。", "cites": [{"t": "捕鼠不知狸狌,此家猫也。", "b": "《庄子·秋水》"}, {"t": "一之日于貉,取彼狐狸,为公子裘。", "b": "《诗·豳风·七月》"}]}, {"meaning": "黄鼠狼的别名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2005wx','狼','1','láng','犭','10','','[{"pinyin": "láng", "defs": [{"meaning": "(形声。从犬,良声。本义:狼)。"}, {"meaning": "同本义。", "cites": [{"t": "狼,似犬,锐头,白颊,高前广后。", "b": "《说文》"}, {"t": "并驱从两狼兮。", "b": "《诗·齐风·还》"}]}, {"meaning": "凶狠。", "cites": [{"t": "狼,俍也。", "b": "《广雅》"}, {"t": "秦国之俗贪狼。", "b": "《淮南子·要略》"}, {"t": "狼戾不可止。", "b": "《淮南子·览冥》"}], "words": [{"w": "虎狼", "t": "比喻凶恶残暴的人"}, {"w": "狼戾", "t": "比喻人的性格贪婪残暴,像狼一样凶狠"}, {"w": "狼心", "t": "喻狠毒贪婪的心"}, {"w": "狼心狗行", "t": "比喻心肠狠毒贪婪,行为卑鄙无耻"}, {"w": "狼性", "t": "凶恶的心性。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2006wx','卿','1','qīng','卩','10','','[{"pinyin": "qīng", "defs": [{"meaning": "(会意。甲骨文字形,像二人向食之形。《说文》:“从卯,皂(bī)声。”“卯,事之制也。”本义:飨食)。"}, {"meaning": "古时高级长官或爵位的称谓。汉以前有六卿,汉设九卿,北魏在正卿下还有少卿。以后历代相沿,清末始废。", "cites": [{"t": "卿,六卿。天官冢宰、地官司徒、春官宗伯、夏官司马、秋官司寇、冬官司空也。", "b": "《说文》"}, {"t": "诸侯之上大夫卿。", "b": "《礼记·王制》。注:“上大夫曰卿。”"}, {"t": "卿大夫豹饰。", "b": "《管子·揆度》"}, {"t": "大国三卿,皆命于天子;次国三卿,二卿命于天子,一卿命于其君;小国二卿,皆命于其君。", "b": "《礼记·王制》"}, {"t": "有卿之名。", "b": "《国语·晋语》"}, {"t": "五大夫三卿。", "b": ""}, {"t": "以相如功大,拜为上卿。", "b": "《史记》"}, {"t": "荐笏言于卿士。", "b": "唐·柳宗元《柳河东集》"}, {"t": "王公卿相。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "有卿士。", "b": "清·周容《芋老人传》"}], "words": [{"w": "卿相", "t": "指中央行政机构的长官"}, {"w": "卿贰", "t": "侍郎的别称;次于九卿的少卿。清代一般为三品到五品的虚衔。"}]}, {"meaning": "古代用为第二人称,表尊敬或爱意。", "cites": [{"t": "今卿廓开大计,正与孤同。", "b": "《资治通鉴》"}, {"t": "卿今当塗。", "b": "《资治通鉴·汉纪 》"}, {"t": "岂欲卿治经。", "b": ""}, {"t": "卿言多务。", "b": ""}, {"t": "卿今者不略。", "b": ""}]}, {"meaning": "古代朋友、夫妇间的爱称。", "cites": [{"t": "卿子冠军。", "b": "《汉书·高帝纪》。集注:“卿子,时人相褒尊之辞。”"}, {"t": "卫人谓之庆卿。", "b": "《史记·刺客传》。索隐:“时人尊重之号。”"}, {"t": "我自不驱卿,逼迫有阿母。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "将领。秦以前天子、诸侯之将帅皆以卿为之。", "cites": [{"t": "卿无共御,立军尉以摄之。", "b": "《左传》"}]}, {"meaning": "祥瑞,福泽。", "cites": [{"t": "百工相和而歌卿云,帝乃倡之曰:卿云烂兮,糺缦缦兮。", "b": "《尚书大传·虞夏传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2007wx','逢','1','féng','辶','10','','[{"pinyin": "féng", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关。夆(fēng)声。本义:遭逢,遇见)。"}, {"meaning": "同本义。", "cites": [{"t": "逢,遇也。", "b": "《说文》"}, {"t": "魑魅罔两,莫能逢之。", "b": "《左传·宣公三年》"}, {"t": "而亲以逢殆。", "b": "《楚辞·天问》"}]}, {"meaning": "又。", "cites": [{"t": "逢彼白雉。", "b": ""}, {"t": "萍水相逢,尽是他乡之客。", "b": "王勃《滕王阁序》"}, {"t": "落花时节又逢君。", "b": "唐·杜牧《江南春绝句》"}, {"t": "相逢何必曾相识。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "逢辰", "t": "遇到好的时刻"}, {"w": "逢会", "t": "遇到时机;相会,会合"}, {"w": "逢场", "t": "遇到或到达某场合"}, {"w": "逢晤", "t": "当面相遇。"}]}, {"meaning": "迎,迎接。", "cites": [{"t": "道而得神,是谓逢福。", "b": "《国语·周语上》。注:“逢,迎也。”"}, {"t": "逢君之恶。", "b": "《孟子·告子下》"}, {"t": "主人能爱客,终日有逢迎。", "b": "唐·王维《与卢象集朱家》"}]}, {"meaning": "迎合。", "cites": [{"t": "逢君之恶其罪大。", "b": "《孟子·告子下》"}], "words": [{"w": "逢君", "t": "迎合君主的心意"}, {"w": "逢意", "t": "迎合他人心意"}, {"w": "逢合", "t": "迎合"}, {"w": "逢恶导非", "t": "逢迎坏人,助长恶行。"}]}, {"meaning": "大的。", "cites": [{"t": "子孙其逢。", "b": "《书·洪范》"}, {"t": "丘少居鲁,衣逢掖之衣。", "b": "《礼记·儒行》"}], "words": [{"w": "逢掖", "t": "宽大的衣袖"}, {"w": "逢长", "t": "久长"}, {"w": "逢衣", "t": "古时儒者所穿的一种宽袖衣。"}]}, {"meaning": "(fēng)。"}, {"meaning": "壮大,茂盛。", "cites": [{"t": "身其康强,子孙其逢吉。", "b": "《书·洪范》"}], "words": [{"w": "逢昌", "t": "壮大昌盛。"}]}, {"meaning": "宽大。", "cites": [{"t": "逢衣浅带,解果其冠。", "b": "《荀子·儒效》"}, {"t": "汝逢衣徒也。", "b": "《列子·皇帝》"}]}, {"meaning": "烽火。古代边防要塞报警的烟火。", "cites": [{"t": "大汉之德,逢涌原泉。", "b": "《汉书·司马相如传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2008wx','鸵','1','tuó','鸟','10','','[{"pinyin": "tuó", "defs": [{"meaning": "鸵鸟。"}, {"meaning": "鸵鸟属(Struthio)的一种善跑而不会飞的平胸鸟类,头和颈有茸毛,身上有软羽,大腿几乎赤裸,足有二趾,翼和尾有值钱的大羽,因此而为人饲养。", "cites": [{"t": "鸵,大鸟,驼蹄,如汉元帝时,有鸟如马驹,故名驼鸟,因鸟族作“鸵”。", "b": "《正字通》"}]}, {"meaning": "自欺欺人者,行径类似传说中鸵鸟般的人;可联想到驼鸟习性的人。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2009wx','留','1','liú','田','10','','[{"pinyin": "liú", "defs": [{"meaning": "(会意。从田,从丣,丣亦(yǒu)声。从“田”,表示停留的地方。本义:停留,留下)。"}, {"meaning": "同本义(停止在某一处所,含有不动的意思)。", "cites": [{"t": "畱,止也。", "b": "《说文》"}, {"t": "令之留于酸枣。", "b": "《战国策·秦策》"}, {"t": "灵连蜷兮既留。", "b": "《楚辞·云中君》"}, {"t": "风气留其处。", "b": "《素问·虐论》"}, {"t": "乃令张良留谢。", "b": "《史记·项羽本纪》"}, {"t": "城入赵而璧留秦。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "留五百人。", "b": "《资治通鉴·唐纪》"}, {"t": "雪上空留。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "要留清白在人间。", "b": "明·于谦《石灰吟》"}, {"t": "留像于馆。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "逗留", "t": "暂时停留"}, {"w": "留舍", "t": "留宿"}, {"w": "留住", "t": "对城市年轻人的泛称"}, {"w": "留居", "t": "保守,维持现状。停住,居留"}, {"w": "留身", "t": "宋代大臣朝见,请求退朝时独留面奏机宜"}, {"w": "留客住", "t": "一种头上装有倒钩的长枪。"}]}, {"meaning": "使不离开;挽留。", "cites": [{"t": "廷椽起矣。状河伯留客之久,若皆罢去归矣。", "b": "《史记·滑稽列传》"}, {"t": "昔子瑜在柴桑时,孔明来吴,孤欲使子瑜留之。", "b": "《三国演义》"}], "words": [{"w": "留行", "t": "挽留,使不离去"}, {"w": "留款", "t": "挽留款待"}, {"w": "留欢", "t": "留客欢宴"}, {"w": "留饮", "t": "留客宴饮;留下宴饮。"}]}, {"meaning": "引申为扣留。", "cites": [{"t": "赵高因留所赐扶苏玺书。", "b": "《史记·李斯列传》"}, {"t": "因留沛公。", "b": "《史记·项羽本纪》"}, {"t": "匈奴留汉使。", "b": "《汉书·李广苏建传》"}]}, {"meaning": "又。", "cites": [{"t": "汉亦留之。", "b": ""}, {"t": "武留匈奴。", "b": ""}], "words": [{"w": "留系", "t": "拘押,拘留"}, {"w": "留身", "t": "拘留人身"}, {"w": "留碍", "t": "阻碍,障碍。"}]}, {"meaning": "保存;遗留。", "cites": [{"t": "人生自古谁无死,留取丹心照汗青!", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "留头", "t": "旧习。女孩幼时剃发,逐渐长大时开始蓄发,叫“留头”"}, {"w": "留存", "t": "存留,保存"}, {"w": "留取", "t": "留存。"}]}, {"meaning": "滞留;拖延;搁置。", "cites": [{"t": "无留居。", "b": "《庄子·山水》。注:“滞守之谓。”"}, {"t": "宿留海上。", "b": "《汉书·郊祀志》。注:“有所须待也。”"}], "words": [{"w": "留中", "t": "留于宫中不发。皇帝将臣下的奏章留在宫中,不批复不交议"}, {"w": "留事", "t": "积压的公务"}, {"w": "留连", "t": "耽搁;拖延"}, {"w": "留时", "t": "延误时日。"}]}, {"meaning": "水流动。", "cites": [{"t": "留动而生物。", "b": "《庄子·天地》"}]}, {"meaning": "杀。", "cites": [{"t": "贤不可威,能不可留。", "b": "《管子·侈靡》"}]}, {"meaning": "长久。", "cites": [{"t": "留,久也。", "b": "《尔雅》"}, {"t": "悉数之乃留。", "b": "《礼记·儒行》。注:“久也。”"}], "words": [{"w": "留年", "t": "延年。亦指长寿"}, {"w": "留瘦", "t": "中医指久病而体瘦。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2010wx','鸳','1','yuān','鸟','10','','[{"pinyin": "yuān", "defs": [{"meaning": "(形声。从鸟,夗(yuàn)声。本义:“鸳鸯”的省称)。"}, {"meaning": "同本义。", "cites": [{"t": "鸳,鸳鸯也。", "b": "《说文》"}, {"t": "鹊好外反,鸳好内思。", "b": "陆佃《埤雅》"}, {"t": "鸳鸯于飞。", "b": "《诗·小雅·鸳鸯》"}, {"t": "鸳鸯,水鸟,凫类也。雌雄未尝相离,人得其一,则一思而死,故曰匹鸟。", "b": "晋·崔豹《古今注·鸟兽》"}], "words": [{"w": "鸳鸯瓦脊", "t": "互相成对的瓦建成的屋脊"}, {"w": "鸳鸯拐", "t": "两脚向左或向右踢起"}, {"w": "鸳鸯客", "t": "同在一桌饮酒、吃饭的两人。"}]}, {"meaning": "比喻同事,同僚。", "cites": [{"t": "芸阁编充栋,鸳班礼绝邻。", "b": "明·李东阳《寿琼山邱先生》"}], "words": [{"w": "鸳行鹭序簿", "t": "在职官员的名册。鸳行、鹭序指朝官井然有序的行列"}, {"w": "鸳班", "t": "文武朝官的排列。"}]}, {"meaning": "比喻配偶,夫妻。", "cites": [{"t": "鸳会阻,夕雨凄飞。", "b": "宋·柳永《两同心》"}], "words": [{"w": "鸳帏凤枕", "t": "喻夫妻床上枕边事"}, {"w": "鸳枕", "t": "夫妻共眠用的枕头"}, {"w": "鸳侣", "t": "配偶,夫妻"}, {"w": "鸳鸯偶", "t": "比喻和睦的夫妇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2011wx','皱','1','zhòu','皮','10','','[{"pinyin": "zhòu", "defs": [{"meaning": "(形声。从皮,刍(chú)声。本义:皮肤因松弛而起的纹路)。"}, {"meaning": "同本义。", "cites": [{"t": "莫道韶华镇长在,发白面皱专相待。", "b": "唐·李贺《嘲少年》"}, {"t": "面皮嘴唇烧的紫绛皱裂。", "b": "《红楼梦》"}], "words": [{"w": "皱皮", "t": "皮肤上的皱纹"}, {"w": "皱文", "t": "皱纹。"}]}, {"meaning": "衣、物等经折叠而显出痕迹。", "cites": [{"t": "前低划开阔,烂漫堆众皱。", "b": "唐·韩愈《南山诗》"}], "words": [{"w": "皱褶", "t": "褶皱。指衣服上折叠的纹路"}, {"w": "皱彀", "t": "喻指水面的微波。"}]}, {"meaning": "收缩;紧蹙。", "cites": [{"t": "琼窗春断双蛾皱。", "b": "南唐·李煜《采桑子》"}], "words": [{"w": "皱白", "t": "指残花"}, {"w": "打皱", "t": "起皱纹"}, {"w": "衣裳皱了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2012wx','饿','1','è','饣','10','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从食,我声。本义:饥之甚。按:在古代,“饥”与“饿”存在着程度上的差别。“饥”指一般的肚子饿;“饿”是严重的饥饿)。"}, {"meaning": "同本义 。与“饱”相对。", "cites": [{"t": "饿,饥也。", "b": "《说文》"}, {"t": "饿,无食久馁也。", "b": "《六书故》"}, {"t": "饿,甚于饥也。", "b": "《正字通》"}, {"t": "有死者曰大饥,无死者曰大饿。", "b": "《谷梁传》疏引徐邈说"}, {"t": "无一月饿。", "b": "《淮南子·说山》"}, {"t": "家有常业,虽饥不饿。", "b": "《韩非子·饰邪》"}], "words": [{"w": "饿隶", "t": "饥饿的人;形容干瘠的样子"}, {"w": "饿损", "t": "饿坏"}, {"w": "饿杀鬼", "t": "方言。贪吃的人"}, {"w": "饿病", "t": "饥饿致病。"}]}, {"meaning": "使受饿;感到饥饿。", "cites": [{"t": "饿其体肤。", "b": "《孟子·告子下》"}, {"t": "伯夷、叔齐饿于首阳之下。", "b": "《论语·季氏》"}], "words": [{"w": "孩子饿了;别饿着小猪", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2013wx','馁','1','něi','饣','10','','[{"pinyin": "něi", "defs": [{"meaning": "(形声。从食,委声。本义:饥饿)。"}, {"meaning": "同本义。", "cites": [{"t": "餒,饥也。", "b": "《说文》"}, {"t": "餒,饥也。", "b": "《广雅》"}, {"t": "餒,饿也。", "b": "《三苍》"}, {"t": "闵其粥糜冻餒之患。", "b": "《王纯碑》"}, {"t": "今民馁而君逞欲。", "b": "《左传·桓公六年》"}, {"t": "吾有馁而已。", "b": "《左传·襄公二十年》。注:“饿也。”"}, {"t": "我馁甚。", "b": "马中锡《中山狼传》"}, {"t": "冻馁之患。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "馁殍", "t": "饿殍"}, {"w": "馁疾", "t": "饥饿病困"}, {"w": "馁毙", "t": "饿死"}, {"w": "馁馑", "t": "饿死"}, {"w": "馁士", "t": "饥饿之士"}, {"w": "馁腹", "t": "饿着肚子。"}]}, {"meaning": "气馁;泄气,丧气。", "cites": [{"t": "其为气也配义与道。于是,馁也。", "b": "《孟子·公孙丑》"}], "words": [{"w": "馁堕", "t": "空虚,落下。指怒气已消失"}, {"w": "胜勿骄,败勿馁;馁怯", "t": "气馁胆怯"}, {"w": "馁荏", "t": "气势软弱"}, {"w": "馁却", "t": "因气馁而退却"}, {"w": "馁弱", "t": "气馁软弱。"}]}, {"meaning": "指鱼腐烂变质。", "cites": [{"t": "鱼馁而肉败,不食。", "b": "《论语·乡党》"}]}, {"meaning": "泛指食物腐烂变质。", "cites": [{"t": "食物馁败,生虫,欣然食之。", "b": "黄叔璥《台海使槎录》"}], "words": [{"w": "馁败", "t": "腐烂变质。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2014wx','凌','1','líng','冫','10','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从仌(bīng,冰,夌líng)声。本义:冰)。"}, {"meaning": "同本义。", "cites": [{"t": "涉江莫涉凌,得意须得朋。", "b": "孟郊《寒江吟》"}], "words": [{"w": "凌冰", "t": "流水中的冰块"}, {"w": "凌灾", "t": "因冰块堵塞河道导致河水泛滥"}, {"w": "凌床", "t": "冰床"}, {"w": "凌室", "t": "古代的藏冰室。"}]}, {"meaning": "积冰。", "cites": [{"t": "鱼矜鳞而并凌兮,鸟登木而失条。", "b": "《文选·张衡·思玄赋》"}]}, {"meaning": "凌驾;压倒。", "cites": [{"t": "凌冬不雕。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "凌出华林部。", "b": "清·侯方域《壮悔堂文集》"}], "words": [{"w": "凌铄", "t": "压倒"}, {"w": "凌砾", "t": "犹言压倒,超过"}, {"w": "凌跨", "t": "超越"}, {"w": "凌迈", "t": "超越"}, {"w": "凌等", "t": "超越等级。"}]}, {"meaning": "欺侮。", "cites": [{"t": "终刚强兮不可凌。", "b": "屈原《国殇》"}], "words": [{"w": "凌逼", "t": "欺凌压迫"}, {"w": "凌藉", "t": "欺凌"}, {"w": "凌折", "t": "欺压,折辱"}, {"w": "凌尚", "t": "凌辱尊长"}, {"w": "凌忽", "t": "欺辱,轻慢"}, {"w": "凌虐", "t": "欺压,侵犯;虐待。"}]}, {"meaning": "“凌”假借为“夌”。侵犯。", "cites": [{"t": "终刚强兮不可凌。", "b": "屈原《国殇》"}], "words": [{"w": "凌圣", "t": "侵犯神灵"}, {"w": "凌犯", "t": "侵犯;侵扰"}, {"w": "凌折", "t": "侵犯"}, {"w": "凌践", "t": "侵害摧残"}, {"w": "凌踏", "t": "侵害摧残"}, {"w": "凌突", "t": "侵犯;冲撞。"}]}, {"meaning": "升,登上(只有于有相当高度的地方)。", "cites": [{"t": "攻将凌其城。", "b": "《商君书·赏刑》"}, {"t": "会当凌绝顶,一览众山小。", "b": "杜甫《望岳》"}], "words": [{"w": "凌虚", "t": "升上天空"}, {"w": "凌翥", "t": "高飞"}, {"w": "凌励", "t": "同凌厉。凌空高飞"}, {"w": "凌腾", "t": "上升,升腾。"}]}, {"meaning": "战栗。", "cites": [{"t": "虎豹之凌遽。", "b": "《汉书·扬雄传上》。注:“凌,战栗也。”"}]}, {"meaning": "迫近。", "cites": [{"t": "凌晨过骊山。", "b": "杜甫《自京赴奉先县咏怀五百字》"}], "words": [{"w": "凌晓", "t": "清晨"}, {"w": "凌薄", "t": "迫近"}, {"w": "凌摩", "t": "迫近,接近。"}]}, {"meaning": "越过,渡过。", "cites": [{"t": "金舟不能凌阳侯之波。", "b": "葛洪《抱朴子》"}]}, {"meaning": "杂乱。", "cites": [{"t": "风入春松正凌乱。", "b": "元稹《五弦弹》"}], "words": [{"w": "凌乱", "t": "杂乱而没有次序。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2015wx','凄','1','qī','冫','10','','[{"pinyin": "qī", "defs": [{"meaning": "(淒俗作“凄”。形声。从水,妻声。本义:云雨兴起的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "淒,雨云起也。", "b": "《说文》"}, {"t": "有渰淒淒。", "b": "《诗·小雅·大田》"}], "words": [{"w": "凄凄", "t": "云兴起的样子。"}]}, {"meaning": "寒冷。", "cites": [{"t": "淒其以风。", "b": "《诗·邶风·绿衣》"}, {"t": "西南曰淒风。", "b": "《吕氏春秋·有始》"}, {"t": "秋气潜以淒泪兮。", "b": "《汉书·外戚传》"}, {"t": "凄神寒骨。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "凄其", "t": "寒冷的样子"}, {"w": "凄凄", "t": "寒凉"}, {"w": "凄急", "t": "寒凉而迅急"}, {"w": "凄风", "t": "寒冷的风"}, {"w": "凄凛", "t": "寒冷。"}]}, {"meaning": "凄凉。", "cites": [{"t": "善为凄戾之词。", "b": "钟嵘《诗品》"}], "words": [{"w": "凄断", "t": "极度凄凉悲痛"}, {"w": "凄瑟", "t": "凄凉萧瑟"}, {"w": "凄单", "t": "凄凉孤单"}, {"w": "凄亮", "t": "凄凉"}, {"w": "凄戾", "t": "悲惊;辛酸"}, {"w": "凄神", "t": "触景生情,引起凄凉情绪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2016wx','恋','1','liàn','心','10','','[{"pinyin": "liàn", "defs": [{"meaning": "(形声。本义:留恋,依依不舍)。"}, {"meaning": "同本义。", "cites": [{"t": "孌,慕也。字亦作戀。", "b": "《说文》"}, {"t": "有孚恋如思也。", "b": "《易·小畜·子夏传》"}, {"t": "羁鸟恋旧林,池鱼思故渊。", "b": "晋·陶潜《归田园居五首》"}], "words": [{"w": "贪恋", "t": "十分留恋"}, {"w": "眷恋", "t": "深切地留念"}, {"w": "依恋", "t": "留恋"}, {"w": "恋土", "t": "依恋乡土,慕恋故里"}, {"w": "恋主", "t": "依恋主人,不忍离去。"}]}, {"meaning": "思念,怀念。", "cites": [{"t": "征夫怀远路,游子恋故乡。", "b": "汉·苏武《诗》之四"}], "words": [{"w": "恋恩", "t": "怀念恩泽"}, {"w": "恋旧", "t": "怀念老朋友。"}]}]}]','jingmo-wenyan');
