('2017wx','桨','1','jiǎng','木','10','','[{"pinyin": "jiǎng", "defs": [{"meaning": "(形声。从木,将声。本义:划船用具。短小者称桨)  同本义。", "cites": [{"t": "金桨木兰船,戏采江南莲。", "b": "南朝梁·刘孝威《采莲曲》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2018wx','浆','1','jiāng','水','10','','[{"pinyin": "jiāng", "defs": [{"meaning": "(从水,将声。本义:饮料)。"}, {"meaning": "古代一种微酸的饮料。", "cites": [{"t": "浆,酢浆也。", "b": "《说文》"}, {"t": "饮酒浆饮俟于东房。", "b": "《仪礼·公食礼》"}, {"t": "箪食壶浆。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "浆水", "t": "一种饮料"}, {"w": "浆糗", "t": "饮料与干粮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2019wx','衰','1','cuī shuāi','亠','10','','[{"pinyin": "cuī", "defs": [{"meaning": "古代用粗麻布制成的毛边丧服。", "cites": [{"t": "共丧衰亦如之。", "b": "《周礼·天官·内司服》"}, {"t": "无衰麻之服。", "b": "《荀子·礼论》"}, {"t": "子墨衰緻,梁弘御戎,莱驹为右。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "衰衣", "t": "衰服。古代的丧服"}, {"w": "衰杖", "t": "居丧用的麻緻与哭丧棒"}, {"w": "衰冠", "t": "丧服,衰衣丧冠。"}]}]}, {"pinyin": "shuāi", "defs": [{"meaning": "(会意。从衣,从冄(rǎn)。“冄”象草毛茸茸的样子。是“蓑衣”的“蓑”的本字。（suǒ）本义:蓑衣。)。"}, {"meaning": "力量减退,衰落,没落。与“盛”相对。", "cites": [{"t": "衰则气复反入。", "b": "《素问·疟论》。注:“谓病衰退也。”"}, {"t": "一鼓作气,再而衰,三而竭。", "b": "《左传·庄公十年》"}, {"t": "呜呼!盛衰之理,虽曰天命,岂非人事哉!", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "衰末", "t": "衰落微末"}, {"w": "衰旺", "t": "衰落与旺盛"}, {"w": "衰季", "t": "衰微末世"}, {"w": "衰废", "t": "衰败颓废"}, {"w": "衰宗", "t": "殁落残败的宗族"}, {"w": "衰门", "t": "寒门"}, {"w": "衰薄", "t": "颓废浇薄。多指道德风尚。"}]}, {"meaning": "减少;削弱。", "cites": [{"t": "其周德之衰乎。", "b": "《左传·襄公二十九年》。注:“小也。”"}, {"t": "昔周道衰微。", "b": "《谷梁传序》。疏:“谓衰弱陵迟。”"}, {"t": "余幼好此奇服兮,年既老而不衰。", "b": "《楚辞·屈原·涉江》"}, {"t": "日食饮得无衰乎?", "b": "《战国策·赵策》"}], "words": [{"w": "风势渐衰;衰颓", "t": "衰败"}, {"w": "衰止", "t": "衰减而止息"}, {"w": "衰乏", "t": "衰退疲乏"}, {"w": "衰色", "t": "指姿色衰减的女子。"}]}, {"meaning": "枯萎;凋谢。", "cites": [{"t": "明朝风起应吹尽,夜惜衰红把火看。", "b": "唐·白居易《惜牡丹花》"}, {"t": "是处红衰翠减,苒苒物华休。", "b": "宋·柳永《八声甘州·对潇潇雨洒江天》"}, {"t": "常恐秋节至焜黄华叶衰。", "b": "《乐府诗辞·长歌行》"}], "words": [{"w": "衰红", "t": "凋谢的花"}, {"w": "衰条", "t": "枯枝"}, {"w": "衰黄", "t": "枯黄。"}]}, {"meaning": "衰老。", "cites": [{"t": "年衰志悯。", "b": "《淮南子·主术》。注:“老也。”"}, {"t": "人之老也形盖衰。", "b": "《吕氏春秋·去宥》。注:“肌肤消也。”"}, {"t": "而臣衰,窃爱怜之。", "b": "《战国策·战策》"}, {"t": "其无宿根者,即候苗成而未有花时采,则根生已足而又未衰。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "衰颜", "t": "衰老的容颜"}, {"w": "衰暮", "t": "老年;晚年"}, {"w": "衰冗", "t": "衰老冗废"}, {"w": "衰年", "t": "衰老之年"}, {"w": "衰枯", "t": "衰老干枯"}, {"w": "衰耄", "t": "衰老;年老糊涂。"}]}, {"meaning": "人老时鬓发疏落变白。", "cites": [{"t": "塞上长城空自许,镜中衰鬓已先斑。", "b": "陆游《剑南诗稿》"}], "words": [{"w": "衰白", "t": "人老时鬓发疏落变白"}, {"w": "衰鬓", "t": "年老而疏白的鬓发。多指暮年。"}]}, {"meaning": "衰弱。", "cites": [{"t": "老妪力虽衰,请从吏夜归。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "衰癃", "t": "衰弱多病"}, {"w": "衰迈", "t": "衰弱老迈"}, {"w": "衰困", "t": "衰弱困顿"}, {"w": "衰窿", "t": "衰弱抱病。"}]}, {"meaning": "懈怠。", "cites": [{"t": "年既老而不衰。", "b": "《楚辞·涉江》。注:“懈也。”"}], "words": [{"w": "衰葸", "t": "懈怠畏惧"}, {"w": "衰惰", "t": "怠惰"}, {"w": "衰堕", "t": "懈怠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2020wx','衷','1','zhōng zhòng','亠','10','','[{"pinyin": "zhōng", "defs": [{"meaning": "(形声。从衣。中声。本义:贴身的内衣)。"}, {"meaning": "同本义。", "cites": [{"t": "衷,里亵衣。", "b": "《说文》。段玉裁注:“亵衣有在外者,衷则在内者也。”"}], "words": [{"w": "衷衣", "t": "里衣,内衣"}, {"w": "衷服", "t": "贴身内衣。"}]}, {"meaning": "内心。", "cites": [{"t": "汝不察吾衷。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "衷怀歉仄", "t": "心里感到内疚抱歉"}, {"w": "衷言", "t": "心里话"}, {"w": "衷素", "t": "内心真情。"}]}, {"meaning": "中心,中央。", "cites": [{"t": "佩,衷之旗也。", "b": "《左传·闵公二年》"}, {"t": "发命之不衷。", "b": "《左传·昭公十六年》"}, {"t": "服之不衷。", "b": "《左传·僖公二十四年》"}], "words": [{"w": "衷正", "t": "中正。"}]}, {"meaning": "贴身穿着;穿在里面。", "cites": [{"t": "或衷其襦。", "b": "《谷梁传》"}, {"t": "楚人衷甲。", "b": "《左传·襄公二十七年》"}, {"t": "今人服公裳必衷以背子。", "b": "宋·程大昌《演繁露·背子中禅》"}], "words": [{"w": "衷襦", "t": "衬在里面的短衣"}, {"w": "衷甲", "t": "在衣服里面穿铠甲。"}]}, {"meaning": "引申为包围。", "cites": [{"t": "衷戎师,前后击之,尽殪。", "b": "《左传》"}]}, {"meaning": "正;正派。", "cites": [{"t": "楚辟我衷。", "b": "《左传·昭公六年》。注:“正也。”"}, {"t": "发命之不衷。", "b": "《左传·昭公十六年》。注:“当也。”"}, {"t": "史馆取为衷据。", "b": "清·章学诚《邵与桐别传》"}], "words": [{"w": "衷据", "t": "正确的根据。"}]}, {"meaning": "善;福。", "cites": [{"t": "今天降衷于吴。", "b": "《国语·吴语》"}, {"t": "和衷哉。", "b": "《书·皋谟》。传:“善也。”"}]}, {"meaning": "忠诚。", "cites": [{"t": "欲对衷言不从。", "b": "《荀子·成相》。注:“诚也。”"}, {"t": "不从命乃衷。", "b": "《荀子·子道》"}], "words": [{"w": "衷愚", "t": "愚忠。尽忠而不明事理。多用作臣子上言于帝王的自谦之词"}, {"w": "衷赤", "t": "赤诚之心。"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhòng", "defs": [{"meaning": "适合,恰当。", "cites": [{"t": "服之不衷,身之灾也。", "b": "《左传·僖公二十四年》。注:“犹适也。”"}, {"t": "而后立衷焉。", "b": "《左传·庄公六年》。注:“节适也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2021wx','高','1','gāo','高','10','','[{"pinyin": "gāo", "defs": [{"meaning": "(象形。甲骨文字形,象楼台重叠之形。汉字部首之一。从“高”的字多与高大或建筑有关。本义:离地面远;从下向上距离大)。"}, {"meaning": "同本义。", "cites": [{"t": "高,崇也,像台观高之形。", "b": "《说文》"}, {"t": "巽为高。", "b": "《易·说卦》传"}, {"t": "穷高极远,而测深厚。", "b": "《礼记·乐记》"}, {"t": "不登高山,不知天之高也。", "b": "《荀子·劝学》"}, {"t": "无楚、韩之患,则大王高枕而卧,国必无忧矣。", "b": "《战国策·魏策》"}, {"t": "高树多悲风,海水扬其波。", "b": "曹植《野田黄雀行》"}, {"t": "城非不高也,池非不深也。", "b": "《孟子·公孙丑下》"}, {"t": "最高日观峰,在长城南十五里。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "高平", "t": "指土地高而平"}, {"w": "高丘", "t": "高的土山"}, {"w": "高坛", "t": "高耸的祭坛"}, {"w": "高燥", "t": "指土地较高而又干燥。"}]}, {"meaning": "等级在上,超越流俗或标准。", "cites": [{"t": "轻辞天子,非高也,势薄也。", "b": "《韩非子·五蠹》"}, {"t": "于是高材疾足者先得焉。", "b": "《史记·淮阴侯列传》"}, {"t": "则今之高爵显位,一旦抵罪,或脱身以逃,不能容于远近。", "b": "明·张溥《五人墓碑记》"}, {"t": "居庙堂之高,则忧其民。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "高世", "t": "高出世人"}, {"w": "高仙", "t": "崇高的仙人"}, {"w": "高作", "t": "高着;绝招"}, {"w": "高轨", "t": "高尚的规范、崇高的典范"}, {"w": "高品", "t": "品德高尚的人,技艺高超的人。"}]}, {"meaning": "敬称,称别人的事物。", "cites": [{"t": "高台未倾,爱妾尚在,悠悠尔心,亦何可言。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "高情远致,弟子早已伏膺。", "b": "《晋书·孙楚传》"}, {"t": "素不相识,动问官人高姓大名?", "b": "《水浒传》"}], "words": [{"w": "高邻", "t": "对邻居的敬称"}, {"w": "高作", "t": "大作。对他人诗文的敬称"}, {"w": "高喻", "t": "敬称他人的教谕"}, {"w": "高诲", "t": "尊称别人的教诲。"}]}, {"meaning": "空泛,不切实际。", "cites": [{"t": "孔公诸清谈高论,嘘枯吹生,并无军旅之才,执锐之干。", "b": "《后汉书·郑太传》"}], "words": [{"w": "高言", "t": "夸大不实的言论"}, {"w": "高虚", "t": "官位高而不负实际责任"}, {"w": "高沧", "t": "不实的言谈。即空谈。"}]}, {"meaning": "年长,年老。", "cites": [{"t": "且陛下春秋高,法令亡常,大臣亡罪夷灭者数十家。", "b": "《汉书·苏武传》"}], "words": [{"w": "高寿;高龄", "t": ""}]}, {"meaning": "高大;远大;盛大。", "cites": [{"t": "观其坐高堂,骑大马,醉醲而饫肥鲜者。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "高殿", "t": "高大的殿堂"}, {"w": "高台", "t": "高大的楼台或台榭"}, {"w": "高榭", "t": "高大的台榭"}, {"w": "高坟", "t": "高大的坟墓"}, {"w": "高廪", "t": "高大的米仓"}, {"w": "高馆", "t": "高大的馆阁。"}]}, {"meaning": "声调激越。", "cites": [{"t": "有吏夜扣门,高声催纳粟。", "b": "唐·白居易《纳粟》"}], "words": [{"w": "高咏", "t": "吟咏时声音激越"}, {"w": "高鸣", "t": "高声鸣叫。"}]}, {"meaning": ""}, {"meaning": "肥沃,膏腴。", "cites": [{"t": "[张禹]为人谨厚,然内殖货财,多买田至四百顷,皆泾渭溉灌,极高腴上贾。", "b": "《汉纪·孝成纪三》"}]}, {"meaning": "甘美。", "cites": [{"t": "高粱之变,足生大丁,受如持虚。", "b": "《素问·生气通天论》"}]}, {"meaning": "由下至上的距离。", "cites": [{"t": "山不在高,有仙则名。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "太行、王屋二山,方七百里,高万仞。", "b": "《列子·汤问》"}], "words": [{"w": "标高;加高;增高", "t": ""}]}, {"meaning": "高处。", "cites": [{"t": "吾尝跂而望矣,不如登高之博见也。", "b": "《荀子·劝学》"}]}, {"meaning": "膏肓,古代医学指心下。", "cites": [{"t": "爰从寝疾,遽致高肓。", "b": "吴《寻阳公主墓誌》"}]}, {"meaning": "泛指城外,野外。", "cites": [{"t": "仲春之月:玄鸟至。至之日,以太牢祠于高禖,天子亲往。", "b": "《礼记·月令》"}]}, {"meaning": "加高,提高。", "cites": [{"t": "高其闬闳,厚其墙垣。", "b": "《左传·襄公三十一年》"}, {"t": "牛困人饥日已高,市南门外泥中歇。", "b": "唐·白居易《卖炭翁》"}, {"t": "欲居之以为利,而高其直,亦吾售者。", "b": "《聊斋志异·促织》"}], "words": [{"w": "高发", "t": "官位高升"}, {"w": "高捷", "t": "科举考试高中"}, {"w": "高枕", "t": "加高枕头。"}]}, {"meaning": "尊崇,敬重。", "cites": [{"t": "世上所高,莫若皇帝。", "b": "《庄子·盗跖》"}, {"t": "愈穷愈荣,虽死,天下愈高之。", "b": "《吕氏春秋》"}, {"t": "贵财贱义,高富下贫。", "b": "《汉书·地理志》"}]}, {"meaning": "远离,隐居。", "cites": [{"t": "赋诗归来,高蹈独善。", "b": "南朝宋·颜延年《陶征士诔》"}], "words": [{"w": "高步", "t": "脱离世俗,迈向高远的理想"}, {"w": "高逝", "t": "远离世俗,不求名利;远去"}, {"w": "高声栖", "t": "远居山林,不问俗事"}, {"w": "高遁", "t": "避世而隐居山林。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2022wx','郭','1','guō','阝','10','','[{"pinyin": "guō", "defs": [{"meaning": "(形声。从邑,从“邑”,表示与城郭有关。本义:在城的外围加筑的一道城墙)。"}, {"meaning": "同本义。内城叫城,外城叫郭。", "cites": [{"t": "郭,外城也。", "b": "《说文》"}, {"t": "城外为之郭。", "b": "《管子·度地》"}, {"t": "爷娘闻女来,出郭相扶将。", "b": "《乐府诗集·木兰诗》"}, {"t": "三里之城,七里之郭,环而攻之而不胜。", "b": "《孟子·公孙丑下》"}, {"t": "门闭,因逾郭而入。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "郭围", "t": "外城边沿"}, {"w": "郭术", "t": "城墙和道路"}, {"w": "郭郛", "t": "外城。"}]}, {"meaning": "泛指城市。", "cites": [{"t": "东家有贤女,窈窕艳城郭。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "青山横北郭,白水绕东城。", "b": "李白《送友人》"}], "words": [{"w": "郭邑", "t": "城邑"}, {"w": "郭外", "t": "城外。"}]}, {"meaning": "外部,外周。", "cites": [{"t": "又钱无轮郭文章,不便人用。", "b": "《后汉书·董卓传》"}], "words": [{"w": "轮郭", "t": "轮廓。物体的外周、边框。"}]}, {"meaning": "春秋国名 。在今山东省北部。"}, {"meaning": "皮。", "cites": [{"t": "津液充郭。", "b": "《素问·汤液醪醴论》"}], "words": [{"w": "津液充郭", "t": "津液使外皮充实、润泽。"}]}, {"meaning": "(guǒ)。古代棺材外面套的大棺。", "cites": [{"t": "病甚,临卒,将无棺郭。", "b": "汉《楚相孙叔敖碑》"}]}, {"meaning": "(kuò)。"}, {"meaning": "开拓。", "cites": [{"t": "鼓者,郭也。春分之音也。", "b": "《风俗通义·鼓》"}]}, {"meaning": "空。", "cites": [{"t": "夫胀者,皆在于脏腑之外,排脏腑而郭胸胁,胀皮肤,故命曰胀。", "b": "《灵枢·胀论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2023wx','席','1','xí','巾','10','','[{"pinyin": "xí", "defs": [{"meaning": "(“蓆”的古字。会意。从巾,庶省声。天子诸侯的席有刺绣镶边,故从巾。席用来待广大宾客,故从“庶”省。本义:供坐卧铺垫的用具。后又曾写作“蓆”) 同本义。", "cites": [{"t": "席,藉也。礼天子诸侯席有黼绣纯饰。", "b": "《说文》。按,即筵也。方幅如巾,故从巾。"}, {"t": "设莞筵纷纯,加缫,席画纯。", "b": "《周礼·司几筵》。疏:“初在地者一重,谓之筵。重在上者,即谓之席。”"}, {"t": "设之曰筵,坐之曰席。", "b": "《礼记·祭统》注"}, {"t": "我心匪席,不可卷也。", "b": "《诗·邶风·柏舟》"}, {"t": "结发同枕席。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "觉时之枕席。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "席地而卧。", "b": "清·方苞《狱中杂记》"}, {"t": "席地倚墙。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "席包", "t": "以苇席或高粱篾席制的包"}, {"w": "席具", "t": "铺垫用具"}, {"w": "席户", "t": "悬席为户。比喻房子的简陋"}, {"w": "席号", "t": "以草席搭建的临时棚屋"}, {"w": "席荐", "t": "席子与草荐,都是草编的坐卧用具。"}]}, {"meaning": "座位;席位。", "cites": [{"t": "席而无上下,则乱于席次矣。", "b": "《孔子家语》"}, {"t": "变色离席。(大惊失色离开座位)。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "席舍", "t": "贡院中的试场座位、考舍"}, {"w": "席尊", "t": "首席"}, {"w": "上席;下席;硬席;专席;来宾席;被告席", "t": ""}]}, {"meaning": "成桌的饭菜,酒筵。", "cites": [{"t": "饮酒酣,武安起为寿,坐皆避席优。", "b": "《史记·魏其武安侯列传》"}, {"t": "所赐者兴,受爵,降席下,奠爵,再拜稽首。", "b": "《仪礼·燕礼》。郑玄注:“席下,席西也。”"}], "words": [{"w": "席尊", "t": "指主持酒席的人"}, {"w": "席面", "t": "宴席上与主人对席的客位"}, {"w": "流水席;还席", "t": ""}]}, {"meaning": "职位。", "cites": [{"t": "常恐诸子侈席势凌人。", "b": "《旧唐书·房乔传》"}, {"t": "这钱谷一席,有个小徒很过得去,可以叫他来效劳。", "b": "《负曝闲谈》"}, {"t": "步武离台席,徊翔集帝梧。", "b": "唐·刘禹锡《赠杨尚书》"}]}, {"meaning": "旧称所司职务为席,如管刑名的幕宾称刑席,管钱谷的称钱席;教师称教席。", "cites": [{"t": "每一个人替他们安置一席,倒也不难。", "b": "《文明小史》"}]}, {"meaning": "船帆。", "cites": [{"t": "早行篙师怠,席挂风不正。", "b": "杜甫《早发》"}]}, {"meaning": "铺席,登席就坐。", "cites": [{"t": "乃席宾。", "b": "《仪礼·乡饮酒礼》"}, {"t": "必正席,先尝之。", "b": "《论语》。皇疏:“犹坐也。”"}, {"t": "席于门中。", "b": "《仪礼·特性馈食礼》"}, {"t": "赵旃夜至于楚军,席于军门之外。", "b": "《左传·宣公十二年》"}]}, {"meaning": "凭借,倚仗。", "cites": [{"t": "吕产、吕禄席太后之宠。", "b": "《汉书·刘向传》"}]}, {"meaning": "垫,压。", "cites": [{"t": "相枕席于道路。", "b": "班固《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2024wx','准','1','zhǔn','冫','10','','[{"pinyin": "zhǔn", "defs": [{"meaning": "(准本为凖的俗字,现为凖的简化字。但在未简化前,准习用的意义,与凖字有别)。"}, {"meaning": "公文用语 。始于唐·五代  表示允许,认可。", "cites": [{"t": "乃于战所,准当时兵士,人种树一株,以旌武功。", "b": "《周书·文帝纪下》"}], "words": [{"w": "批准;照准;准如所请  引申为比照,作某类事物看待准前例办理;准平原;准尉  表示依据、根据准某部函", "t": ""}]}, {"meaning": "折充;抵充。", "cites": [{"t": "连身上外盖衣服,脱下准了店钱。", "b": "《醒世恒言》"}, {"t": "新旧钱暂兼行,新钱千准银一两,旧钱准七钱。", "b": "《清史稿》"}, {"t": "我有心看上她,与我家做个媳妇,就准了这四十两银子;岂不两得其便。", "b": "《窦娥冤》"}], "words": [{"w": "准价", "t": "折价"}, {"w": "可准", "t": "可以抵偿"}, {"w": "准算", "t": "折算;抵帐。"}]}, {"meaning": "(形声。从水,隼(sǔn)声。本义:平,不倾斜)。"}, {"meaning": "同本义(取义于水平,侧重于平稳)。", "cites": [{"t": "凖,平也。", "b": "《说文》。字亦俗作准。段玉裁注:“谓水之平也。天下莫平于水,水平谓之凖”"}, {"t": "推而放诸东海而凖。", "b": "《礼记·祭义》。注:“犹平也。”"}]}, {"meaning": "亦指其他物体的平。", "cites": [{"t": "輈注则利凖,利凖则久,和则安。", "b": "《周礼·考工记》"}], "words": [{"w": "准望", "t": "测绘地图的方法之一。"}]}, {"meaning": "轻重相当;均等。", "cites": [{"t": "与天地准,故能弥纶天地之道。", "b": "《易·系辞》"}, {"t": "幸少从女言,得厚息,略相准。", "b": "《聊斋志异》"}]}, {"meaning": "古代测量水平的仪器。", "cites": [{"t": "凖者,所以揆平取正也。", "b": "《汉书·律历志上》"}], "words": [{"w": "准平", "t": "测量平面的仪器。"}]}, {"meaning": "标准;法则。", "cites": [{"t": "礼者,节之凖也。", "b": "《荀子·致士》"}], "words": [{"w": "准式,准格", "t": "标准,准则"}, {"w": "准限", "t": "标准。"}]}, {"meaning": "箭靶,靶子", "cites": [{"t": "我有平肩舆,前途犹准的。", "b": "杜甫《郑典设自施州归》"}], "words": [{"w": "准的", "t": "箭靶;标准;准则"}, {"w": "准执", "t": "箭靶"}, {"w": "准鹄", "t": "即正鹄。箭靶。引申为目标"}, {"w": "准式", "t": "标准;楷模"}, {"w": "准格", "t": "犹言标准、规格。"}]}, {"meaning": "鼻子。", "cites": [{"t": "君不见高阳酒徒起草中,长揖山东隆准公。", "b": "李白《梁甫吟》"}]}, {"meaning": "允许;批准 。唐、宋以来公文上许可的批语,俗作“准”。", "cites": [{"t": "乃于战所,准当时兵士,人种树一株,以旌武功。", "b": "《周书·文帝纪下》"}, {"t": "我要放他,你又苦苦的不准。", "b": "《儿女英雄传》"}], "words": [{"w": "准查记录;准行", "t": "准许;许可"}, {"w": "准奏", "t": "君主批准臣属的奏章。"}]}, {"meaning": "仿效,效法。", "cites": [{"t": "始都乐寿,号金城宫,备百官,准开皇故事。", "b": "《新唐书》"}], "words": [{"w": "准遵", "t": "遵循;依照"}, {"w": "准据", "t": "依据"}, {"w": "准拟", "t": "遵循;模仿。"}]}, {"meaning": "瞄准。", "cites": [{"t": "修胫者使之跖钁,强脊者使之负土,眇者使之准,伛者使之涂,各有所宜。", "b": "《淮南子》"}], "words": [{"w": "准度", "t": "测量,衡量"}, {"w": "准裁", "t": "衡量,裁定"}, {"w": "准量", "t": "计量;估量。"}]}, {"meaning": "测量,度量。", "cites": [{"t": "轼始至颖,遣吏以水平准之,淮之涨水高于新沟几一丈。", "b": "《宋史》"}]}, {"meaning": "揣测,揣度。", "cites": [{"t": "仁君处位而不安,大夫隐道而不言,群臣准上意而怀当。", "b": "《淮南子》"}]}, {"meaning": "按照,依照。", "cites": [{"t": "若体规画圆,准方作矩,终为人之臣仆,乌尚得谓之诗哉。", "b": "《答章秀才论诗书》"}], "words": [{"w": "准式", "t": "依照准则或样式"}, {"w": "准律", "t": "依照法律"}, {"w": "准据", "t": "依据。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2025wx','座','1','zuò','广','10','','[{"pinyin": "zuò", "defs": [{"meaning": "(形声。从广(yǎn),坐声。“坐”的后起字。本义:座位)。"}, {"meaning": "同本义。供人坐的地方,也指位置,座次。", "cites": [{"t": "隔座送钩春酒暖。", "b": "唐·李商隐《无题》"}, {"t": "座上有健啖客。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "宝座", "t": "指帝王或神佛的座位"}, {"w": "上座", "t": "坐位分尊卑时,最尊的坐位叫上座"}, {"w": "落座", "t": "坐到位置上"}, {"w": "满座;空座;首座;末座;楼座;茶座;专座;雅座", "t": ""}]}, {"meaning": "坐具。", "cites": [{"t": "清辇道于上林,肃华台之金座。", "b": "《梁书》"}], "words": [{"w": "石座;软座;硬座;玉座;蒲座", "t": ""}]}, {"meaning": "引申为在座的人。", "cites": [{"t": "凄凄不似向前声,满座重闻皆掩泣。", "b": "唐·白居易《琵琶行》"}, {"t": "座中泣下谁最多?", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2026wx','症','1','zhēng zhèng','疒','10','','[{"pinyin": "zhēng", "defs": [{"meaning": "腹中结块的病。", "cites": [{"t": "脉沉重而中散者,因寒食成症。", "b": "晋·王叔和《脉经》"}], "words": [{"w": "病症", "t": "病征。按:病征的 “症”,在古时只作“證”。症是近代的俗字"}, {"w": "症坚", "t": "症结"}, {"w": "症痼", "t": "腹中积久未消的痞块"}, {"w": "症瘕", "t": "腹中结块的病。喻固陋寡闻"}, {"w": "症噎", "t": "腹中结块,食塞咽喉。"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "症候;病象。古通“證”。", "cites": [{"t": "荔枝核性太热,补阴,人有阴症寒疾者,取七枚煎汤饮之,汗出便差。亦治疝气。", "b": "《五杂俎·物部三》"}], "words": [{"w": "死症", "t": "绝症。无法治好的病"}, {"w": "险症", "t": "危险的症候"}, {"w": "顽症", "t": "难治或久治不愈的病症"}, {"w": "崩症", "t": "子宫大量出血的病"}, {"w": "症象", "t": "症状。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2027wx','病','1','bìng','疒','10','','[{"pinyin": "bìng", "defs": [{"meaning": "(形声。疒形丙声。本义:上古时指重病)。"}, {"meaning": "同本义。", "cites": [{"t": "病,疾加也。", "b": "《说文》"}, {"t": "疾病外内皆埽。", "b": "《仪礼·既夕礼》。注:“疾甚曰病。”"}, {"t": "坎为心病。", "b": "《易·说卦》"}, {"t": "疾病而立之。", "b": "《左传·襄公十九年》"}, {"t": "故得病寝衽,畏惧鬼至。", "b": "王充《论衡·订鬼》"}, {"t": "与死人同病者,不可生也。", "b": "《韩非子·孤愤》"}, {"t": "行年四十而有内热之病以死。", "b": "《庄子·达生》"}], "words": [{"w": "病革", "t": "病势危急将死"}, {"w": "病亟", "t": "病革。"}]}, {"meaning": "生理上或心理上不正常的状态。", "cites": [{"t": "君之病在肌肤。", "b": "《韩非子·喻老》"}, {"t": "性伤谓之病。", "b": "《荀子·正名》"}, {"t": "张良多病,未尝特将也。", "b": "《史记·留侯世家》"}], "words": [{"w": "病笃", "t": "病势沉重"}, {"w": "病疽", "t": "毒疮类疾病"}, {"w": "病困", "t": "受疾病的困扰"}, {"w": "病革", "t": "病势危急将死"}, {"w": "病亟", "t": "病革。"}]}, {"meaning": "缺点,毛病,瑕疵。", "cites": [{"t": "不如舜,不如周公,吾之病也。", "b": "唐·韩愈《原毁》"}, {"t": "至于不孚之病,则尤不才为甚。", "b": "宗臣《报刘一丈书》"}, {"t": "人皆嗤吾固陋,吾不以为病。", "b": "宋·司马光《训俭示康》"}, {"t": "然今日庭诘弘,诚中弘之病。", "b": "《史记·平津侯主父列传》"}, {"t": "砭切政病。", "b": "《新唐书·杜希全传》"}], "words": [{"w": "病累", "t": "指文章中有瑕疵或累赘的字句"}, {"w": "语病;通病", "t": "一般都有的缺点"}, {"w": "毛病", "t": "缺点"}, {"w": "弊病", "t": "事情上的毛病;弊端。"}]}, {"meaning": "疾苦,痛苦。", "cites": [{"t": "长其孤,问其病。", "b": "《国语·吴语》"}]}, {"meaning": "困难,不利。", "cites": [{"t": "利则东收齐,病则西侵秦。", "b": "《史记·商君列传》"}]}, {"meaning": "枯萎。", "cites": [{"t": "沉舟侧畔千帆过,病树前头万木春。", "b": "唐·刘禹锡《酬乐天扬州初逢席上见赠》"}], "words": [{"w": "病树", "t": "即将枯死的树木"}, {"w": "病叶", "t": "枯叶;黄叶"}, {"w": "病草", "t": "枯萎变黄的草。"}]}, {"meaning": "生病。", "cites": [{"t": "未果,寻病终。", "b": "晋·陶渊明《桃花源记》"}, {"t": "人病则忧惧,忧惧见鬼出。", "b": "王充《论衡·订鬼》"}, {"t": "弥子瑕母病。", "b": "《韩非子·说难》"}, {"t": "见一人病咽塞。", "b": "《三国志·方伎传》"}], "words": [{"w": "孩子病了;病状", "t": "请病假的文状"}, {"w": "病忘", "t": "患健忘的病症"}, {"w": "病恹恹", "t": "久病慵懒的样子。"}]}, {"meaning": "担心,忧虑。", "cites": [{"t": "君子病无能焉。", "b": "《论语·卫灵公》"}], "words": [{"w": "病滞", "t": "犹郁滞"}, {"w": "病俗", "t": "犹言忧民忧俗"}, {"w": "病疚", "t": "愧悔不安。"}]}, {"meaning": "苦恼,困恼。", "cites": [{"t": "向吾不为斯役,则久已病矣。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "病涉", "t": "苦于涉水渡川。"}]}, {"meaning": "疲累,倦困。", "cites": [{"t": "今日病矣,余助苗长矣。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "病乏", "t": "困乏;因病惫乏"}, {"w": "病喙", "t": "非常疲乏,呼吸困难。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2028wx','疾','1','jí','疒','10','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。甲骨文字形,从大(人),从矢,字形象人腋下中箭。段玉裁《说文解字注》:“矢能伤人,矢之去甚速,故从矢会意。”本义:受兵伤。泛指疾病)。"}, {"meaning": "轻微的叫疾。", "cites": [{"t": "疾,病也。", "b": "《说文》。段注:“析言之则病为疾加,浑言之则疾亦病也。”"}, {"t": "君有疾在腠理,不治将恐深。", "b": "《韩非子·喻老》"}, {"t": "伯牛有疾,子问之。", "b": "《论语·雍也》"}]}, {"meaning": "泛指病。", "cites": [{"t": "司马子反辞以心疾。", "b": "《韩非子·十过》"}], "words": [{"w": "疾革", "t": "病情加重"}, {"w": "疾损", "t": "病情减转,病情好转"}, {"w": "疾动", "t": "发病;疾病发作"}, {"w": "疾棘", "t": "病危。"}]}, {"meaning": "疫疠;发生疫疠。", "cites": [{"t": "疾在腠理。", "b": "《韩非子·喻老》"}, {"t": "寡人无疾。", "b": ""}, {"t": "君有疾。", "b": ""}, {"t": "已有疾疫。", "b": "《资治通鉴》"}], "words": [{"w": "疾疫", "t": "发生疫病"}, {"w": "疾疠", "t": "瘟疫"}, {"w": "疾疟", "t": "指疟疾"}, {"w": "疾厉", "t": "即疾疠。"}]}, {"meaning": "痛苦;忧患。", "cites": [{"t": "问之民所疾苦。", "b": "《史记·滑稽列传》"}, {"t": "身自疾痛。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "疾痛惨怛;疾困", "t": "疾苦;疾疢"}, {"w": "疾吏", "t": "病困的小官吏。"}]}, {"meaning": "缺点,毛病,瑕疵。", "cites": [{"t": "必有窃疾。", "b": "《墨子·公输》"}, {"t": "寡人有疾,寡人好色。", "b": "《孟子·梁惠王下》"}, {"t": "孔子贤者,所刺讥皆中诸侯之疾。", "b": "《史记》"}]}, {"meaning": "快速;急速。", "cites": [{"t": "奋疾而不拔。", "b": "《礼记·乐记》"}, {"t": "征鸟厉疾。", "b": "《礼记·月令》"}, {"t": "而疾讨陈。", "b": "《左传·襄公五年》"}, {"t": "何来疾也。", "b": "《战国策·齐策四》"}, {"t": "不能疾走。", "b": "《战国策·赵策》"}, {"t": "草枯鹰眼疾。", "b": "唐·王维《观猎》"}, {"t": "疾驰入仆营。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "疾快", "t": "快速"}, {"w": "疾言", "t": "言语急迫"}, {"w": "疾进", "t": "急速进行"}, {"w": "疾疾", "t": "迅速的样子;急遽不安的样子。"}]}, {"meaning": "敏捷;轻快。", "cites": [{"t": "春风得意马蹄疾,一日看尽长安花。", "b": "孟郊《登科后》"}], "words": [{"w": "疾伶", "t": "机敏伶俐"}, {"w": "疾俏", "t": "动作轻快灵活"}, {"w": "疾跳", "t": "精悍,机灵。"}]}, {"meaning": "急剧而猛烈。", "cites": [{"t": "疾风知劲草,板荡识诚臣。", "b": "李世民《赐萧瑀》"}], "words": [{"w": "疾威", "t": "暴虐残酷"}, {"w": "疾雨", "t": "急骤的雨"}, {"w": "疾雷", "t": "急雷,突然响起的雷。比喻汹涌的波涛。"}]}, {"meaning": "强大,宏大。", "cites": [{"t": "顺风而呼,声非加疾也。", "b": "《荀子·劝学》"}]}, {"meaning": "患病,生一般的病。", "cites": [{"t": "寒暑不能使之疾。", "b": "《荀子·天论》"}], "words": [{"w": "疾色", "t": "患病的脸色"}, {"w": "疾耗", "t": "患病的坏消息"}, {"w": "疾作", "t": "疟疾发作。"}]}, {"meaning": "厌恶;憎恨。", "cites": [{"t": "尔无忿疾于顽。", "b": "《书·君陈》"}, {"t": "疾夫舍曰欲之而必为之辞。", "b": "《论语·季氏》"}, {"t": "生而有疾恶焉。", "b": "《荀子·大略》"}, {"t": "有亡而无疾。", "b": "《荀子·大略》。杨倞注:“疾同嫉,嫉恨。"}, {"t": "疾其君者。", "b": "《孟子·梁惠王上》"}, {"t": "愤世疾邪。", "b": "明·刘基《卖柑者言》"}, {"t": "疾大户兼并。", "b": "清·张廷玉《明史》"}], "words": [{"w": "疾恶", "t": "憎恨恶人"}, {"w": "疾心", "t": "憎恶之心"}, {"w": "疾吏", "t": "憎恨狱吏。"}]}, {"meaning": "嫌怨。", "cites": [{"t": "疾王听之不聪。(听,名词。聪,耳明。)", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "疾怨", "t": "怨恨。"}]}, {"meaning": "妒忌。", "cites": [{"t": "人之有技,冒疾以恶之。", "b": "《书·秦誓》"}, {"t": "公私之分明,则小人不疾贤,而不肖者不妒功。", "b": "《商君书·修权》"}, {"t": "膑至,庞涓恐其贤于己,疾之。", "b": "《史记·孙子吴起列传》"}], "words": [{"w": "疾裘妒枕", "t": "夫妻间对双方有外遇的嫉妒"}, {"w": "疾夫", "t": "妒忌者"}, {"w": "疾心", "t": "心生妒忌"}, {"w": "疾忌", "t": "妒忌。"}]}, {"meaning": "忧虑。", "cites": [{"t": "草食之兽,不疾易薮;水生之虫,不疾易水。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2029wx','斋','1','zhāi','文','10','','[{"pinyin": "zhāi", "defs": [{"meaning": "(形声。从示,斎齐省声。本义:斋戒,旧指祭祀前整洁身心)。"}, {"meaning": "同本义。", "cites": [{"t": "斋,戒洁也。", "b": "《说文》"}, {"t": "王斋日三举。盖王日一举。", "b": "《周礼·膳夫》"}, {"t": "日中及夕则馂余斋,则每食一太牢也。", "b": "《周礼·太牢》"}, {"t": "斋必变食,至不多食。", "b": "《论语》"}, {"t": "秦王虽斋。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "遂许斋五日", "b": ""}, {"t": "秦王斋五日。", "b": ""}, {"t": "专意斋醮。", "b": "《明史》"}]}, {"meaning": "施舍饭食给僧、道或穷苦人。", "cites": [{"t": "张待诏娘子盛一碗饭,一碗羹,斋这无眼婆婆。", "b": "《清平山堂话本》"}], "words": [{"w": "斋僧敬道", "t": "对和尚道士虔诚有礼,供食舍钱"}, {"w": "斋衬钱", "t": "施舍给佛寺的钱币。"}]}, {"meaning": "素食。", "cites": [{"t": "我们是行脚僧,遇庄化饭,适处求斋。", "b": "《西游记》"}], "words": [{"w": "斋粮", "t": "僧尼的生活用粮"}, {"w": "斋供", "t": "供奉神佛的食品。"}]}, {"meaning": "屋舍,多指学舍 。如斋房(学舍;书房);养心斋;斋长(舍长。指旧时学校宿舍的主管人员)。"}, {"meaning": "专指拜忏诵经、祈祷求福一类活动。", "cites": [{"t": "今日俸钱过十万,与君营奠复营斋。", "b": "唐·元稹《遣悲怀》"}], "words": [{"w": "斋献", "t": "敬献祭礼。"}]}, {"meaning": "斋宫的简称。", "cites": [{"t": "王即斋宫,百官御事,各即其斋三日。", "b": "《国语》"}]}, {"meaning": "商店用名 。今北京有荣宝斋,苏州有采芝斋。"}, {"meaning": "庄重;恭敬。", "cites": [{"t": "洁斋俟兮惠音声。", "b": "宋玉《登徒子好色赋》"}], "words": [{"w": "斋如", "t": "严肃而谨慎的样子"}, {"w": "斋明", "t": "无所不明,无所偏颇"}, {"w": "斋庄", "t": "严肃庄敬"}, {"w": "斋肃", "t": "专一庄敬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2030wx','疹','1','zhěn','疒','10','','[{"pinyin": "zhěn", "defs": [{"meaning": "病。", "cites": [{"t": "遂动旧疹,缠绵经月。", "b": "《洛阳伽蓝记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2031wx','疼','1','téng','疒','10','','[{"pinyin": "téng", "defs": [{"meaning": "(形声。从疒(chuáng),冬声。本义:痛)。"}, {"meaning": "同本义 (仅表示身体上的难受)。", "cites": [{"t": "疼,痛也。", "b": "《广雅》"}, {"t": "寒胜其热,则骨疼肉枯。", "b": "《灵枢经·刺节真邪》"}, {"t": "丝细缲多女手疼,扎扎千声不盈尺。", "b": "白居易《嫽绫》"}], "words": [{"w": "疼痒", "t": "痛痒。"}]}, {"meaning": "疼爱。", "cites": [{"t": "满庭花落地,则有谁疼?", "b": "孟称舜《桃花人面》"}], "words": [{"w": "疼热", "t": "疼爱,爱护"}, {"w": "疼顾", "t": "关心照顾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2032wx','疲','1','pí','疒','10','','[{"pinyin": "pí", "defs": [{"meaning": "(形声。从疒,皮声。病字旁念chuáng,据甲骨文,象人躺在床上害病的样子。以它作形旁的字一般与疾病有关。本义:疲乏;困倦)。"}, {"meaning": "同本义。", "cites": [{"t": "疲,劳也。", "b": "《说文》"}, {"t": "疲,乏也。", "b": "《玉篇》"}, {"t": "苶然疲役。", "b": "《庄子·齐物论》"}, {"t": "疲马之死也。", "b": "《淮南子·俶真》"}, {"t": "士民疲病于内。", "b": "《韩非子·初见秦》"}, {"t": "夫以疲病之卒御狐疑之众。", "b": "《资治通鉴》"}], "words": [{"w": "精疲力尽;疲敝", "t": "疲乏困苦"}, {"w": "疲玩", "t": "疲塌轻忽"}, {"w": "疲曳", "t": "疲弱困顿,比喻年老"}, {"w": "疲钝", "t": "疲倦困顿"}, {"w": "疲顽", "t": "疲困倦怠"}, {"w": "疲匮", "t": "疲累困乏"}, {"w": "疲弊", "t": "困苦穷乏,是疲敝"}, {"w": "疲人", "t": "疲困之人"}, {"w": "疲耗", "t": "困顿耗损"}, {"w": "疲匮", "t": "劳累穷乏"}, {"w": "疲羸", "t": "困苦穷乏。"}]}, {"meaning": "衰老;衰弱。", "cites": [{"t": "以疲马犬羊为币。", "b": "《管子·小筐》。注:“谓瘦也。”"}], "words": [{"w": "疲癃", "t": "衰老龙钟或有残疾的人"}, {"w": "疲冗", "t": "衰弱无能"}, {"w": "疲劣", "t": "衰弱恶劣"}, {"w": "疲羸", "t": "衰弱。"}]}, {"meaning": "厌倦。", "cites": [{"t": "我自乐此,不为疲也。", "b": "《后汉书·光武帝纪》"}]}, {"meaning": "停止。", "cites": [{"t": "余欣秦土,忽有此经。…载玩载咏,欲疲不能,遂佐对校。", "b": "晋·道安《鞞婆沙序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2033wx','脊','1','jǐ','月','10','','[{"pinyin": "jǐ", "defs": [{"meaning": "(本义:背中间的骨头)。"}, {"meaning": "同本义。", "cites": [{"t": "脊,背吕也。", "b": "《说文》"}, {"t": "举肺脊。", "b": "《仪礼·特性礼》"}, {"t": "坎为美脊。", "b": "《易·说卦传》"}, {"t": "或碎脑以折脊。", "b": "李白《大猎赋》"}], "words": [{"w": "脊杖", "t": "在罪犯脊背上施加的杖刑"}, {"w": "脊令", "t": "脊令原。即“鹡鸰”,水鸟名。常比喻兄弟,或兄弟友爱,急难相顾。"}]}, {"meaning": "理,条理。", "cites": [{"t": "有伦有脊。", "b": "《诗·小雅·正月》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2034wx','效','1','xiào','攵','10','','[{"pinyin": "xiào", "defs": [{"meaning": "(形声。从攴(pū),交声。“攴”有致力的意思。本义:献出;尽力)。"}, {"meaning": "同本义。", "cites": [{"t": "司城荡意诸来奔,效节于府人而出。", "b": "《左传》"}, {"t": "异日韩王纳地效玺。", "b": "《史记》"}], "words": [{"w": "效力;效绩", "t": "呈献功绩"}, {"w": "效玺", "t": "呈献国君的印章,表示臣服"}, {"w": "效己", "t": "贡献一己之力"}, {"w": "效芹", "t": "自称贡献微薄。"}]}, {"meaning": "明白。", "cites": [{"t": "由此效之也。", "b": "《荀子·正论》"}, {"t": "乡也,效门室之辨。", "b": "《荀子·儒效》"}, {"t": "效,明也。", "b": "《方言十三》"}]}, {"meaning": "考查。考核。", "cites": [{"t": "彼将任我以事而效我以功。", "b": "《庄子·列御寇》"}], "words": [{"w": "效试", "t": "考核试验"}, {"w": "效志", "t": "查核心志"}, {"w": "效情", "t": "验以情理。"}]}, {"meaning": "授还,授。", "cites": [{"t": "宣王有志,而后效官。", "b": "《左传·昭公二十六年》。注:“授也。”"}], "words": [{"w": "效官;效业", "t": "授官。"}]}, {"meaning": "显示;呈现。", "cites": [{"t": "信者效其忠。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "效祉", "t": "呈现福祉"}, {"w": "效祥", "t": "呈露祥瑞。"}]}, {"meaning": "效验,验证。", "cites": [{"t": "何以效之。", "b": "汉·王充《论衡·订鬼篇》"}]}, {"meaning": "效劳,效忠。", "cites": [{"t": "杀身自效。", "b": "《汉书·李广苏建传》"}]}, {"meaning": "摹仿;师法。", "cites": [{"t": "效,像也。", "b": "《说文》。字亦作俲"}, {"t": "效者,为之法也。", "b": "《墨子·小取》"}, {"t": "君子是则是傚。", "b": "《诗·小雅·鹿鸣》"}, {"t": "民胥傚矣。", "b": "《诗·小雅·角弓》"}, {"t": "尤而傚之。", "b": "《左传·襄公二十五年》"}, {"t": "则而傚之。", "b": "《孝经》"}]}, {"meaning": "字又作傚。", "cites": [{"t": "教之为言傚也。上行之,下傚之。", "b": "《元命苞》"}, {"t": "知崇礼卑。崇效天,卑法地。", "b": "《易·系辞上》"}, {"t": "父亲不思报国酬恩,捐躯尽节,效儿女子之计。", "b": "《封神演义》"}, {"t": "欲效野夫。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "效学", "t": "仿效,学习"}, {"w": "效蹙", "t": "不善模仿而弄巧成拙"}, {"w": "效好", "t": "学好"}, {"w": "效作", "t": "仿作"}, {"w": "效戾", "t": "效尤"}, {"w": "效慕", "t": "仿效"}, {"w": "效邮", "t": "效尤"}, {"w": "东施效颦;上行下效", "t": ""}]}, {"meaning": "功效;效果;结果。", "cites": [{"t": "效亦大矣。", "b": "《淮南子·脩务》"}, {"t": "彊弱存亡之效。", "b": "《荀子·议兵》"}, {"t": "以德为効。", "b": "《汉书·刘向传》"}, {"t": "用兵之效。", "b": "宋·苏洵《六国论》"}, {"t": "效则归于天择。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "自其效观。", "b": ""}, {"t": "愿大王少留意,臣请奏其效。", "b": "《战国策·秦策一》"}, {"t": "此其效也(效:效验,验证)。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "药效;生效;失效;无效;投效;肥效;速效;后效;时效;见效;疗效;实效;奏效;特效;成效;有效", "t": ""}]}, {"meaning": "经验。", "cites": [{"t": "外夷战备日新,老将多恃旧效,昧于改图,故致无功。", "b": "康有为《上清帝第二书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2035wx','离','1','lí','忄','10','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从隹(zhuī),表示与鸟类有关,离声。“离”是“鹂”的本字,因而声符亦兼表字义。本义:鸟名。即黄鹂,也称仓庚,鸣声清脆动听)。"}, {"meaning": "同本义。", "cites": [{"t": "离,离黄仓庚也。", "b": "《说文》"}, {"t": "離为雉、九家,離为鸟,为飞、为鹤、为黄。", "b": "《易·说卦》"}, {"t": "离则配禹。", "b": "《颜氏家训》"}, {"t": "流離之子。", "b": "《诗·邶风·旌丘》"}, {"t": "两个黄鹂鸣翠柳,一行白鹭上青天。", "b": "杜甫《绝句》"}]}, {"meaning": "长离,传说中的凤鸟,比喻有才华的人。", "cites": [{"t": "双鸾游兰渚,二离扬清晖。", "b": "傅长虞《赠何劭王济》"}]}, {"meaning": "八卦之一,象征火。", "cites": [{"t": "离,为火,为日。", "b": "《易·说卦》"}]}, {"meaning": "古代女子出嫁时系的佩巾。", "cites": [{"t": "申佩离以自思。", "b": "《汉书·外戚传》"}]}, {"meaning": "古代传说中没有角的龙。", "cites": [{"t": "如虎如罴,如豺如离。", "b": "《史记·周本纪》"}]}, {"meaning": "山棃。", "cites": [{"t": "桂椒栏,檗离朱杨。", "b": "汉·司马相如《子虚赋》"}]}, {"meaning": "香草。", "cites": [{"t": "扈江离与辟芷兮,纫秋兰以为佩。", "b": "《楚辞·离骚》"}]}, {"meaning": "离假借为“剺”。离开;离别。", "cites": [{"t": "正大夫离居。", "b": "《诗·小雅·雨无止》"}, {"t": "少小离家老大回。", "b": "《回乡偶书》"}, {"t": "今当远离。", "b": "诸葛亮《出师表》"}, {"t": "离臣虏之劳。", "b": "《韩非子·五蠹》"}, {"t": "离城三里。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "离吾乡七百里。", "b": "清·袁枚《祭妹文》"}, {"t": "离离原上草……萋萋满别情。", "b": "唐·白居易《赋得古原草送别》"}], "words": [{"w": "脱离", "t": "离开"}, {"w": "偏离", "t": "离开正道"}, {"w": "离了母", "t": "离了谱;失去本来面目"}, {"w": "离人", "t": "与亲人分别的人"}, {"w": "离恨", "t": "离别的愁恨"}, {"w": "离格儿", "t": "出格"}, {"w": "离了眼", "t": "看花了眼"}, {"w": "离丧", "t": "指亲人死亡。"}]}, {"meaning": "分散,离散。跟 “合”相对。", "cites": [{"t": "邦分崩离析而不能守也。", "b": "《论语·季氏》"}, {"t": "不愿离而离。", "b": "清·林觉民《与妻书》"}, {"t": "约从离衡。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "离合", "t": "分合;聚散"}, {"w": "离聚", "t": "分和合"}, {"w": "离鹤", "t": "失群的鹤"}, {"w": "离会", "t": "指两国君主相会,而彼此意见不一致,不能定是非善恶。"}]}, {"meaning": "假借为“罹”。遭受。", "cites": [{"t": "雉离于罿。", "b": "《诗·王风·兔爰》"}, {"t": "离桓之罪。", "b": "《国语·晋语》"}], "words": [{"w": "离骚", "t": "遭遇到忧患"}, {"w": "离恨天", "t": "遭逢恨事之天"}, {"w": "离尤", "t": "遭受罪愆"}, {"w": "离殃", "t": "遭受,罹祸。"}]}, {"meaning": "割取。", "cites": [{"t": "牛羊之肺,离而不提心。", "b": "《礼记·少仪》"}], "words": [{"w": "离肺", "t": "割去肺脏。"}]}, {"meaning": "断绝;判别。", "cites": [{"t": "一年离经辨志。", "b": "《礼记·学记》"}], "words": [{"w": "离经", "t": "离析经书的文句章节"}, {"w": "离辞", "t": "离析辞句。"}]}, {"meaning": "违背,背离。", "cites": [{"t": "失法离令。", "b": "《商君书·画策》"}, {"t": "众叛亲离。", "b": "《左传》"}], "words": [{"w": "离上", "t": "背叛君上"}, {"w": "离次", "t": "离弃职守"}, {"w": "离判", "t": "弃去形体,超越形躯"}, {"w": "离志", "t": "异心,背离的心志。"}]}, {"meaning": "距离;相距。", "cites": [{"t": "只是小人家离得远了。", "b": "《水浒传》"}]}, {"meaning": "又。", "cites": [{"t": "离这里还有多少路。", "b": ""}]}, {"meaning": "罗列,陈列。", "cites": [{"t": "夜峰何离离,明日落石底。", "b": "李贺《长歌续短歌》"}], "words": [{"w": "离离", "t": "罗列的样子。"}]}, {"meaning": "经历。", "cites": [{"t": "载离寒暑。", "b": "《诗·小雅·小明》"}, {"t": "离一二旬,则人畜弃捐旷野而不反(返)。", "b": "《汉书·西域传上》"}]}, {"meaning": "附丽,附着。", "cites": [{"t": "六五之言,离王公也。", "b": "《易·离》"}, {"t": "月离于毕,俾滂沱也。", "b": "《诗·小雅·渐渐之石》"}]}, {"meaning": "二,两;双。", "cites": [{"t": "离坐离立,无往参焉。", "b": "《礼记·曲礼上》"}, {"t": "离,丽也。", "b": "《易·离卦》"}]}, {"meaning": "又。", "cites": [{"t": "明两作离。", "b": ""}, {"t": "盖取诸离。", "b": "《易·系辞下》"}, {"t": "离不言会。", "b": "《公羊传·桓公五年》。注:“二国会曰离。”"}, {"t": "则不敢正坐离立。", "b": "《后汉书·和熹邓皇后纪》"}], "words": [{"w": "离立", "t": "并立。"}]}, {"meaning": "成双,成对。", "cites": [{"t": "父母存不养,出离者几何人?", "b": "《管子·问》"}, {"t": "宿离不贷。", "b": "《礼记·月令》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2036wx','紊','1','wěn','糸','10','','[{"pinyin": "wěn", "defs": [{"meaning": "(形声。从糸(mì),文声。本义:乱)。"}, {"meaning": "同本义。", "cites": [{"t": "紊,乱也。", "b": "《说文》"}, {"t": "有条而不紊。", "b": "《书·盘庚上》"}], "words": [{"w": "紊纷", "t": "纷乱"}, {"w": "紊淆", "t": "紊乱"}, {"w": "紊弃", "t": "杂乱并弃失"}, {"w": "紊绪", "t": "混乱序分"}, {"w": "紊入", "t": "参杂进去"}, {"w": "紊淆", "t": "混乱。"}]}, {"meaning": "繁盛。", "cites": [{"t": "其运风,其化呜,紊启坼。", "b": "《素问》。张隐庵集注:“紊,繁盛也。”"}]}, {"meaning": "扰乱。", "cites": [{"t": "恐众官齐言,有紊太师清听。", "b": "明·许仲琳《卦神演义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2037wx','唐','1','táng','口','10','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。小篆作字形。从口,庚声。本义:大话)。"}, {"meaning": "广大。", "cites": [{"t": "平原唐其坛曼兮。", "b": "扬雄《甘泉赋》"}], "words": [{"w": "唐唐", "t": "广大;浩荡"}, {"w": "唐皇", "t": "气势宏伟盛大。"}]}, {"meaning": "朝代名。唐朝。", "cites": [{"t": "唐人尚未盛为之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "刻唐贤今人诗赋。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "自唐显庆以来。", "b": "清·姚鼐"}, {"t": "登泰山记》", "b": ""}, {"t": "备于唐。", "b": "蔡元培《图画》"}]}, {"meaning": "传说中古帝尧政权的称号。", "cites": [{"t": "唐虞之世。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "唐年", "t": "唐尧时代。借称太平盛世"}, {"w": "唐风", "t": "唐尧的遗风"}, {"w": "唐许", "t": "唐尧许由的并称"}, {"w": "唐尧", "t": "古帝名。帝喾之子。初封于陶,号陶唐氏。"}]}, {"meaning": "五代之一。公元 923年,李存勖继后梁称帝,国号唐,史称后唐,也简称唐,历四帝,十三年, 936年禅位后晋。"}, {"meaning": "五代时十国之一。公元 937年李升于金陵称帝,国号唐,史称南唐。共历三帝,三十九年。 975年,为宋所灭。"}, {"meaning": "古国名。"}, {"meaning": "相传为祁姓,尧的后代,在今山丁翼城西。"}, {"meaning": "周所建,姬姓,在今湖北省隋县镇,公元前505年为楚所灭。"}, {"meaning": "古代庙堂前或宗庙内的大路。", "cites": [{"t": "庙中路谓之唐。", "b": "《尔雅·释宫》"}, {"t": "中唐有甓。", "b": "《诗·陈风·防有鹊巢》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2038wx','瓷','1','cí','瓦','10','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从瓦,次声。本义:用高岭土烧制成的质料。也指瓷器) 同本义。", "cites": [{"t": "肴止于脯、醢、菜羹,器用瓷、漆。", "b": "司马光《训俭示康》"}], "words": [{"w": "瓷碗;细瓷;瓷枕;瓷仙", "t": "瓷器的人物造像"}, {"w": "瓷注", "t": "陶瓷茶壶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2039wx','资','1','zī','贝','10','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从贝,次声。从贝,与财富有关。本义:钱财)。"}, {"meaning": "同本义。", "cites": [{"t": "资,货也。", "b": "《说文》"}, {"t": "资,川也。", "b": "《广雅》"}, {"t": "怀其资", "b": "《易·旅》"}, {"t": "丧乱蔑资。", "b": "《诗·大雅·板》"}, {"t": "资用乏绝,去秦而归。", "b": "《战国策·秦策一》"}, {"t": "既至秦,持千金之资币物,厚遗秦王宠臣中庶子蒙嘉。", "b": "《战国策·燕策》"}, {"t": "应得之资。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "富者捐资。", "b": "《广东军务记》"}, {"t": "中家以上,皆竭资取得。", "b": "清·方苞《狱中杂记》"}, {"t": "厚资而遣之。", "b": "清·周容《芋老人传》"}], "words": [{"w": "投资", "t": "把资金投入企业"}, {"w": "内资;外资;集资;薪资", "t": "工资"}, {"w": "茶资", "t": "茶钱"}, {"w": "资业", "t": "资产"}, {"w": "借资", "t": ""}]}, {"meaning": "费用。", "cites": [{"t": "问几月之资。", "b": "《仪礼·聘礼》"}, {"t": "致马资于有司。", "b": "《礼记·少仪》"}, {"t": "军资所出,国以富饶。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "资斧不裕", "t": "旅费盘缠不宽裕"}, {"w": "资装", "t": "盘缠与行装"}, {"w": "川资", "t": "旅费"}, {"w": "邮资", "t": "邮费"}, {"w": "资值", "t": "衣食之值"}, {"w": "开资", "t": ""}]}, {"meaning": "资历;资格。", "cites": [{"t": "昔先君仲尼与君先人伯阳有师资之尊。", "b": "《世说新语·言语》"}, {"t": "愔自以资望少。", "b": "《晋书·郄愔传》"}, {"t": "资轻望浅,舆论不孚。", "b": "《大波》"}], "words": [{"w": "资履;资任", "t": "资格;资历"}, {"w": "资名", "t": "资历名望"}, {"w": "资级", "t": "资格和品级"}, {"w": "资秩", "t": "资历和品质"}, {"w": "资籍", "t": "资格履历。"}]}, {"meaning": "天赋;天资。", "cites": [{"t": "然大王资侮人。", "b": "《汉书·陈平传》"}, {"t": "绝世之资,必不如专门之夙习也。", "b": "魏源《默觚下·治篇》"}], "words": [{"w": "资质愚钝", "t": "天资愚鲁、蠢笨"}, {"w": "资质甚鲁", "t": "天资愚笨"}, {"w": "资略", "t": "才智、见识"}, {"w": "资补", "t": "天资素质"}, {"w": "资望", "t": "丰姿仪容。"}]}, {"meaning": "条件。", "cites": [{"t": "三资者备。", "b": "《战国策·秦策一》"}]}, {"meaning": "资料;材料。", "cites": [{"t": "每相见必以欧战为一谈资。", "b": "梁启超《欧战蠡测》"}]}, {"meaning": "粮食。", "cites": [{"t": "唯是脯资。", "b": "《左传·僖公三十三年》"}, {"t": "资穷困。", "b": "《国语·晋语四》。注:“资廪也。”"}, {"t": "南军谷少,而资储不如北。", "b": "《后汉书》"}], "words": [{"w": "资饟", "t": "粮饷"}, {"w": "资粮", "t": "粮食。"}]}, {"meaning": "水名 。发源于湖南省武冈县,北流入洞庭湖。"}, {"meaning": "凭借。", "cites": [{"t": "若据而有之,此帝王之资也。", "b": "《资治通鉴》"}, {"t": "夫无者,诚万物之所资。", "b": "《世说新语·文学》"}, {"t": "以资切磋。", "b": "清·刘开《问说》"}]}, {"meaning": "能力;作用。", "cites": [{"t": "何况因万乘之权,假圣王资乎。", "b": "邹阳《狱中上梁王书》"}]}, {"meaning": "资助;供给。", "cites": [{"t": "资之以币帛。", "b": "《韩非子·说疑》"}, {"t": "固大王资余兵。", "b": "《史记·项羽本纪》"}], "words": [{"w": "资馈", "t": "馈赠;出资帮助"}, {"w": "资禄", "t": "提供俸禄"}, {"w": "资给", "t": "供给财用"}, {"w": "资给馆谷", "t": "供给宾客的宿食。"}]}, {"meaning": "给予。", "cites": [{"t": "王资臣万金而游。", "b": "《战国策》"}, {"t": "如姬资之三年。(“资”,为……悬赏,为动用法;“之”,指杀如姬之父的仇人。)", "b": "《史记·魏公子列传》"}], "words": [{"w": "资给馆谷", "t": "供给宾客的宿食。"}]}, {"meaning": "救助;帮助。", "cites": [{"t": "尧何以助汝?", "b": "《庄子》"}, {"t": "此殆天所以资将军,将军岂有意乎?", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "资全", "t": "周济"}, {"w": "资政", "t": "帮助治理国政"}, {"w": "资辅", "t": "资助;帮助。"}]}, {"meaning": "蓄积。", "cites": [{"t": "夏则资皮,冬则资絺,旱则资舟,水则资车,以待令也。", "b": "《国语·越语上》"}], "words": [{"w": "资聚", "t": "积聚"}, {"w": "资储", "t": "积蓄,贮备。"}]}, {"meaning": "取,取用。", "cites": [{"t": "富其国者资之天下,欲富天下则资之天地。", "b": "王安石《与马运判书》"}], "words": [{"w": "资取", "t": "获取;取得"}, {"w": "资福", "t": "取福,求福"}, {"w": "资纵", "t": "取用无度。"}]}, {"meaning": "锋利。", "cites": [{"t": "旅于处,得其资斧。", "b": "《易·旅》"}], "words": [{"w": "资辩", "t": "利口善辩。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2040wx','凉','1','liáng liàng','冫','10','','[{"pinyin": "liáng", "defs": [{"meaning": "(形声。从水,京声。本义:寒)。"}, {"meaning": "同本义。", "cites": [{"t": "北风其凉。", "b": "《诗·邶风·北风》"}, {"t": "北风谓之凉风。", "b": "《尔雅·释天》"}, {"t": "凉风至。", "b": "《礼记·月令》"}, {"t": "凉雨时降。", "b": "《素问·五常政大论》"}, {"t": "凉州,西方所在寒凉也。", "b": "《释名·释州国》"}, {"t": "水浆,醴凉。", "b": "《周礼·浆人》"}]}, {"meaning": "微寒,稍冷。", "cites": [{"t": "日初出,沧沧凉凉。", "b": "《列子·汤问》。注引《字林》:“凉,微寒。”"}, {"t": "曰燠,曰寒。", "b": "《书·洪范》。疏:“燠是热之始,暑是热之极;凉是冷之始,寒是冷之极。”"}, {"t": "凉风起天末,君子意如何?", "b": "唐·杜甫《天末怀李白》"}], "words": [{"w": "冬暖夏凉;凉生生", "t": "微凉貌"}, {"w": "凉宇", "t": "凉秋的天空"}, {"w": "凉吹", "t": "凉风"}, {"w": "凉榻", "t": "竹制矮床"}, {"w": "凉轿", "t": "一种无帷轿"}, {"w": "凉衣", "t": "凉衫;内衣"}, {"w": "凉风", "t": "初秋凉爽的西南风。八风之一。"}]}, {"meaning": "薄;轻微;刻薄。", "cites": [{"t": "职凉善背。", "b": "《诗·大雅·桑柔》"}, {"t": "虢多凉德。", "b": "《左传·庄公三十二年》"}], "words": [{"w": "凉德", "t": "薄德"}, {"w": "凉能", "t": "才能微薄"}, {"w": "凉菲", "t": "才德微薄"}, {"w": "凉厚", "t": "薄与厚"}, {"w": "凉薄", "t": "微薄,浅薄"}, {"w": "凉驳", "t": "浅薄芜杂。"}]}, {"meaning": "诚信。", "cites": [{"t": "民之罔极,职凉善背。", "b": "《诗·大雅·桑柔》"}]}, {"meaning": "国名 。东晋十六国时期建立在今甘肃省一带的政权,国号皆称“凉”。有前凉、后凉、北凉、南凉、西凉等。"}, {"meaning": "辒辌,丧车。", "cites": [{"t": "棺载辒凉车中。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "姓。"}]}, {"pinyin": "liàng", "defs": [{"meaning": "辅佐。", "cites": [{"t": "凉彼武王。", "b": "《诗·大雅·大明》。传:“佐也。”"}], "words": [{"w": "凉贰", "t": "副贰。特指太子。凉,辅佐。"}]}, {"meaning": "信,实。", "cites": [{"t": "凉曰不可,覆背善詈。", "b": "《诗·大雅·桑柔》"}, {"t": "君子作法于凉。", "b": "《左传·昭公四年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2041wx','站','1','zhàn','立','10','','[{"pinyin": "zhàn", "defs": [{"meaning": "(形声。从立,占声。本义:直立)。"}, {"meaning": "站立,直立。以基本直立的姿势用双脚或一脚支撑自己。", "cites": [{"t": "凡射,或对贼、对把,站定观把子或贼人,不许看扣。", "b": "明·戚继光《纪效新书》"}], "words": [{"w": "站门子", "t": "妓女站在门口招人或接客"}, {"w": "站眙", "t": "久立而不行走"}, {"w": "站堂", "t": "旧时衙门开审时,差役排列在公堂上以应差"}, {"w": "站柜台", "t": "指营业员在商品柜台内侧卖货。"}]}, {"meaning": "蒙古语的音译。驿站,古时传递军政文书的人中途换马、食宿或转递之所 。元代驿站称“站赤”,省称“站”。明改站为“驿”,清代“驿”、“站”并称。", "cites": [{"t": "贾琏这番进京,若按站走时,本该出月到家。", "b": "《红楼梦》"}], "words": [{"w": "站夫", "t": "驿站的役夫"}, {"w": "站驿", "t": "元代驿站"}, {"w": "站船", "t": "旧称在航程有驿站递次接待的官船"}, {"w": "站户", "t": "元代服役于站驿之户称“站户”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2042wx','剖','1','pōu','刂','10','','[{"pinyin": "pōu", "defs": [{"meaning": "(形声。从刀,咅(pǒu)声。本义:破开,中分)。"}, {"meaning": "同本义。", "cites": [{"t": "剖,判也。", "b": "《说文》"}, {"t": "剖,分也。", "b": "《广雅》"}, {"t": "剖伛之背。", "b": "《战国策·宋策》。注:“劈也。”"}, {"t": "比干剖。", "b": "《庄子·胠箧》。释文:“谓割心也。”"}, {"t": "剖刑而莫邪已。", "b": "《荀子·彊国》"}, {"t": "剖冰济水,不惮艰难。", "b": "《吴子·料敌》"}, {"t": "我先君惠公有不腆之田,与女剖分而食之。", "b": "《左传·襄公十四年》"}, {"t": "予贸得其一,剖之,如有烟扑口鼻。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "剖心", "t": "破开胸腹以割心;开布诚心,竭诚相见"}, {"w": "剖判", "t": "分割,破开;辨析"}, {"w": "剖列", "t": "分列"}, {"w": "剖割", "t": "分割"}, {"w": "剖肝沥胆", "t": "比喻以赤诚之心相待。"}]}, {"meaning": "分辨;分析。", "cites": [{"t": "通人暗于好恶兮,岂昏惑而能剖?", "b": "张衡《思玄赋》"}], "words": [{"w": "剖玄", "t": "解说深奥的道理"}, {"w": "剖决", "t": "判决,断事"}, {"w": "剖断", "t": "分析决断"}, {"w": "剖白", "t": "分析表白"}, {"w": "剖豁", "t": "解释"}, {"w": "剖决机宜", "t": "适时、准确地分析决策"}, {"w": "剖明", "t": "辨明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2043wx','竞','1','jìng','立','10','','[{"pinyin": "jìng", "defs": [{"meaning": "(会意。甲骨文字形,象二人竞逐。本义:争竞;角逐;比赛)。"}, {"meaning": "同本义。", "cites": [{"t": "競,逐也。", "b": "《说文》"}, {"t": "职竞用力。", "b": "《诗·大雅·桑柔》"}, {"t": "犹不能与罗者竞多。", "b": "《淮南子·原道》"}, {"t": "相与优游,竞畅于宇宙之间。", "b": "《淮南子·俶真》"}, {"t": "竞于道德。", "b": "《韩非子·五蠹》"}, {"t": "负势竞上。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "物竞之无所争。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "而与之竞火器。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "竞进", "t": "争逐拥进"}, {"w": "竞斗", "t": "争斗,打斗"}, {"w": "竞心", "t": "争强好胜之心"}, {"w": "竞逐", "t": "角逐,竞争"}, {"w": "竞爽", "t": "争胜,争强。"}]}, {"meaning": "争辩。", "cites": [{"t": "前在修文令曹,有山东学士与关中太史竞历。", "b": "《颜氏家训》。王利器集解:“竞历,谓争论历法。”"}]}, {"meaning": "强劲。", "cites": [{"t": "心则不竞。", "b": "《左传·僖公七年》"}], "words": [{"w": "竞朗", "t": "刚正爽利"}, {"w": "竞爽", "t": "精明强干。"}]}, {"meaning": "繁忙的。", "cites": [{"t": "敝邑有社稷之事,使肥与有职竞焉。", "b": "《左传·哀公二十三年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2044wx','部','1','bù','阝','10','','[{"pinyin": "bù", "defs": [{"meaning": "(形声。从邑,(fǒu)声。从“邑”表示与行政区域有关。本义:古汉地名。约在今甘肃省天水、清水、秦安、两当、礼县、徽县一带)。"}, {"meaning": "同本义。", "cites": [{"t": "部,天水狄部。", "b": "《说文》"}]}, {"meaning": "古代军事编制单位,后泛指部队,军队。", "cites": [{"t": "瑜为前部大督。", "b": "《三国志·周瑜传》"}], "words": [{"w": "部阵", "t": "队伍"}, {"w": "部校", "t": "部队;泛称武官"}, {"w": "部将", "t": "部下的武官;军中偏将。"}]}, {"meaning": "中央行政官署。有时也称一般衙署、地方行政官署。", "cites": [{"t": "还部白府君。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "部费", "t": "向吏部行贿以便批准任职所用的钱"}, {"w": "部尺", "t": "由工部制造的标准尺"}, {"w": "部曹", "t": "旧指京师各部司官"}, {"w": "部堂", "t": "清代各部尚书、侍郎称部堂。又各省总督多带兵部尚书衔者,也叫部堂"}, {"w": "国防部;外交部;财政部", "t": ""}]}, {"meaning": "地区。古代监察或行政区域名。", "cites": [{"t": "河东二十八县,分为两部。", "b": "《汉书·尹翁归传》"}]}, {"meaning": "部落。", "cites": [{"t": "曾祖莫护跋,魏初率其诸部入居辽西。", "b": "《晋书》"}]}, {"meaning": "分类,门类。", "cites": [{"t": "名属教坊第一部。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "部索", "t": "分部搜索"}, {"w": "部居", "t": "分门别类的排列"}, {"w": "古籍分经、史子、集四部", "t": ""}]}, {"meaning": "统率。", "cites": [{"t": "汉王部五诸侯兵。", "b": "《史记·项羽本纪》"}], "words": [{"w": "部人", "t": "被统率的人"}, {"w": "部握", "t": "统管,掌握"}, {"w": "部率", "t": "统率。"}]}, {"meaning": "安排,布置。", "cites": [{"t": "部署诸将。", "b": "《汉书·高帝纪》。注:“分部而署置。”"}], "words": [{"w": "部索", "t": "部署搜索罪人。"}]}, {"meaning": "用于书籍、机器、电影等。", "cites": [{"t": "则此一部开国血史。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "一部书,两部机器,三部电影", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2045wx','旁','1','bàng páng','方','10','','[{"pinyin": "bàng", "defs": [{"meaning": "(古通“傍”)。"}, {"meaning": "依傍;依附。", "cites": [{"t": "匈奴大发十余万骑,南旁塞至符奚庐山。", "b": "《汉书·赵充国传》"}], "words": [{"w": "旁沿", "t": "依附沿袭"}, {"w": "旁缘", "t": "依仗。"}]}, {"meaning": "靠近。", "cites": [{"t": "吾灵尚依依旁汝也。", "b": "清·林觉民《与妻书》"}, {"t": "引渭穿渠起长安,旁南山下,至河三百余里。", "b": "《汉书》"}, {"t": "四时之内,飘风怒吹,或西发西洋,或东起北海,旁午交扇,无时而息。", "b": "〔英〕赫胥黎著、严复译《天演论》"}], "words": [{"w": "旁午", "t": "将近中午"}, {"w": "旁车", "t": "靠近车子。"}]}, {"meaning": "依照;仿效。", "cites": [{"t": "扬雄又旁《离骚》作重一篇,名曰《广骚》;又旁《惜诵》以下至《怀沙》一卷,名曰《畔牢愁》。", "b": "《汉书》"}]}, {"meaning": "诽谤。", "cites": [{"t": "不窥密,不旁狎,不道旧故。", "b": "《礼记·少仪》"}]}]}, {"pinyin": "páng", "defs": [{"meaning": "(形声。从二阙,方声。本义:大;广)。"}, {"meaning": "同本义。", "cites": [{"t": "旁,溥也。", "b": "《说文》"}, {"t": "旁,广也。", "b": "《广雅》"}, {"t": "旁求俊彦。", "b": "《书·太甲上》。传:“旁,非一方。”"}, {"t": "群后旁戾。", "b": "张衡《东京赋》"}]}, {"meaning": "又。", "cites": [{"t": "旁震八鄙。", "b": ""}, {"t": "陶冶大炉,旁薄群生。", "b": "《汉书·扬雄传》"}, {"t": "将旁礴万物以为一世蕲乎乱。", "b": "《庄子·逍遥游》"}, {"t": "杂能旁魄而无用。", "b": "《荀子·性恶》。注:“旁魄,广博也。”"}], "words": [{"w": "旁畅", "t": "广通博晓"}, {"w": "旁行", "t": "广泛流传"}, {"w": "旁收", "t": "广泛收罗"}, {"w": "旁求", "t": "四处征求;广泛搜求"}, {"w": "旁施", "t": "广施"}, {"w": "旁开", "t": "广开"}, {"w": "旁薄", "t": "旁礴、旁魄。广博;无际;广被充塞"}, {"w": "旁罗", "t": "遍布"}, {"w": "旁瞩", "t": "遍视"}, {"w": "旁靡", "t": "普及"}, {"w": "旁罗", "t": "遍及"}, {"w": "旁雪", "t": "普遍洗雪"}, {"w": "旁通", "t": "遍通。"}]}, {"meaning": "别的,其他的。", "cites": [{"t": "此吾所以旁推交通,而以为之文也。", "b": "唐·柳宗元《答韦中立论师 道书》"}], "words": [{"w": "旁入", "t": "其他收入"}, {"w": "旁言", "t": "他人的话"}, {"w": "旁省", "t": "别的宫廷"}, {"w": "旁推", "t": "由此及彼地推论"}, {"w": "旁讼", "t": "诉讼涉及他人"}, {"w": "旁寄", "t": "别有寄托"}, {"w": "旁贷", "t": "谓推卸他人。"}]}, {"meaning": "旁边。古同“傍”。", "cites": [{"t": "旁,犹边也,侧也。", "b": "《玉篇》"}, {"t": "其旁可以圉风寒,上可以圉雪霜露。", "b": "《墨子·节用中》"}, {"t": "旁天子而立于堂上。", "b": "《逸周书·王会》"}, {"t": "士旁三揖。", "b": "《礼记·丧大记》"}, {"t": "遂旁设一虚坐,置琵琶于其上。", "b": "宋·王傥《唐语林·雅量》"}, {"t": "斫其正,养其旁条。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "两旁", "t": "左右两边"}, {"w": "旁首", "t": "旁边"}, {"w": "旁训", "t": "正文旁边附注的释义或音读"}, {"w": "旁生", "t": "旁边生长"}, {"w": "旁立", "t": "在旁边侍立"}, {"w": "旁仄", "t": "近侧;左右。"}]}, {"meaning": "附近。", "cites": [{"t": "天之中央亦高四旁六万里。", "b": "《周髀算经》"}], "words": [{"w": "四旁", "t": "前后左右很近的地方"}, {"w": "近旁", "t": "附近;旁边"}, {"w": "旁民", "t": "附近之民"}, {"w": "旁谷", "t": "附近的山谷"}, {"w": "旁近;旁郡", "t": "附近的州郡"}, {"w": "旁座", "t": "指邻座的人。"}]}, {"meaning": "辅助,辅佐。", "cites": [{"t": "日有志极而无旁,终老独以离异兮。", "b": "《楚辞·屈原·九章》。注:“旁,辅也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2046wx','旅','1','lǚ','方','10','','[{"pinyin": "lǚ", "defs": [{"meaning": "(会意。甲骨文字形,象众人站在旗下。旗,指军旗;人,指士兵。小篆字形,表示旌旗;从“从”,表示众人,即士兵。本义:古代军队五百人为一旅)。"}, {"meaning": "军队编制单位。上古一般以五百人为旅,齐制二千人为旅。现代指师以下的单位,基本上由司令部和两个或者两个以上的团或大队组成的战术和行政单位。", "cites": [{"t": "旅,军之五百人为旅。", "b": "《说文》"}, {"t": "孙策以天下为三分,众才一旅。", "b": "庾信《哀江南赋序》"}, {"t": "全旅为上。", "b": "《孙子·谋攻》"}]}, {"meaning": "又。", "cites": [{"t": "破旅次之。", "b": ""}], "words": [{"w": "旅长;两旅兵", "t": ""}]}, {"meaning": "军队。", "cites": [{"t": "加之以师旅。", "b": "《论语·先进》"}, {"t": "所以佐百姓之急,足军旅之费。", "b": "桓宽《盐铁论》"}], "words": [{"w": "劲旅", "t": "强有力的队伍"}, {"w": "振旅", "t": "休整军队。"}]}, {"meaning": "在外的人,旅人。", "cites": [{"t": "行旅者皆欲出于王之涂。", "b": "《孟子·梁惠王上》"}, {"t": "商旅不行,樯倾楫摧。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "旅颜", "t": "旅人困顿愁苦的面色"}, {"w": "旅怀", "t": "羁旅者的情怀"}, {"w": "旅尘", "t": "旅人身上的尘土"}, {"w": "旅愁", "t": "羁旅者的愁闷心情"}, {"w": "旅梦", "t": "旅人思乡之梦。"}]}, {"meaning": "旅行;旅途。", "cites": [{"t": "羁旅长堪醉,相留畏晓钟。", "b": "戴叔伦《江乡故人偶集客舍》"}], "words": [{"w": "旅邸", "t": "旅舍"}, {"w": "旅衣", "t": "行装;旅途中穿的服装"}, {"w": "旅况", "t": "旅途的情怀或景况"}, {"w": "旅泊", "t": "旅途中行舟暂时停泊"}, {"w": "旅宿", "t": "旅途夜宿。"}]}, {"meaning": "旅馆。", "cites": [{"t": "天地一逆旅,同悲万古尘。", "b": "李白《拟古》"}], "words": [{"w": "旅壁", "t": "旅舍墙壁"}, {"w": "旅主", "t": "旅舍主人。"}]}, {"meaning": "众人;众子弟。", "cites": [{"t": "闭门旅距。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "华堂旅会。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "旅力", "t": "众力"}, {"w": "旅见", "t": "众人一起进见"}, {"w": "旅揖", "t": "官爵相同的人众伙一起作揖。"}]}, {"meaning": "次序。", "cites": [{"t": "宾以旅酬于西阶上。", "b": "《仪礼》"}]}, {"meaning": "脊骨。", "cites": [{"t": "旅力方刚,经营四方。", "b": "《诗·小雅·北山》"}, {"t": "形貌魁梧,旅力过人。", "b": "《三国志·典韦传》"}]}, {"meaning": "寄居外地,旅居。", "cites": [{"t": "故捨汝而旅食京师,以求斗斛之禄。", "b": "唐·韩愈《祭十二郎文》"}, {"t": "羁旅之臣。", "b": "《左传·庄公二十二年》"}], "words": [{"w": "旅骨", "t": "客死他乡者的尸骨"}, {"w": "旅冢", "t": "客死他乡者之墓"}, {"w": "旅寄", "t": "寄居他乡"}, {"w": "旅葬", "t": "客死葬于他乡"}, {"w": "旅魂", "t": "客死他乡者的鬼魂。"}]}, {"meaning": "旅行。", "cites": [{"t": "旅思倦摇摇。", "b": "谢朓《之宣城郡出新林浦向板桥》"}]}, {"meaning": "俱,一同。", "cites": [{"t": "吾不欲匹夫之勇也,欲其旅进旅退也。", "b": "《国语·越语上》"}], "words": [{"w": "旅升", "t": "成群升上"}, {"w": "旅占", "t": "谓与众人共同占卜。"}]}, {"meaning": "不种而生,野生。", "cites": [{"t": "中庭生旅谷,井上生旅葵。", "b": "《乐府诗集·十五从军征》"}], "words": [{"w": "旅生;旅葵", "t": "野生的葵菜"}, {"w": "旅谷", "t": "野生的谷物。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2047wx','畜','1','chù xù','田','10','','[{"pinyin": "chù", "defs": [{"meaning": "(会意。甲骨文字形)。"}, {"meaning": "(表示牵引,下象出气的牛鼻形。牛鼻被牵着,说明是已被人类驯服豢养的家畜。本义:家畜) 同本义。", "cites": [{"t": "畜,田畜也。", "b": "《说文》"}, {"t": "大畜时也,小畜寡也。", "b": "《易·杂卦》"}, {"t": "家养谓之畜,野生谓之兽。", "b": "《左传·昭公二十三年》疏"}, {"t": "古者六畜不相为用。", "b": "《左传·僖公十九年》"}, {"t": "拥众数万,马畜弥山,富贵如此!", "b": "《汉书·李广苏建传》"}], "words": [{"w": "家畜、牲畜、幼畜、畜牧", "t": "饲养的禽兽"}, {"w": "畜牲", "t": "指牛、马、羊、鸡、狗、猪等六畜。"}]}]}, {"pinyin": "xù", "defs": [{"meaning": "饲养。", "cites": [{"t": "畜鸟者则勿佛也。", "b": "《礼记·曲礼》"}, {"t": "畜鸾皇只。", "b": "《楚辞·大招》"}, {"t": "则架竹为巢,下畜牛羊豕。", "b": "《徐霞客游记》"}], "words": [{"w": "畜置", "t": "饲养。"}]}, {"meaning": "养育。", "cites": [{"t": "天下谁畜之。", "b": "《左传·哀公二十六年》"}, {"t": "仰不足以事父母,俯不足以畜妻子。", "b": "《孟子·梁惠王上》"}, {"t": "鸡豚狗彘之畜", "b": ""}, {"t": "尔不畜我,复我邦家。", "b": "《诗·小雅·我行其野》"}], "words": [{"w": "畜爱", "t": "养育爱护。"}]}, {"meaning": "培养;培植。", "cites": [{"t": "君子以多识前言往行,以畜其德。", "b": "《易·大畜》"}], "words": [{"w": "人逸马畜", "t": ""}]}, {"meaning": "顺从,驯服。", "cites": [{"t": "孝者畜也。顺于道,不逆于伦,是之为畜。", "b": "《礼记·祭统》"}, {"t": "汝共作我畜民。", "b": "《书·盘庚中》"}]}, {"meaning": "喜欢,喜爱。", "cites": [{"t": "拊我畜我,长我育我。", "b": "《诗·小雅·蓼莪》"}]}, {"meaning": "积;积聚", "cites": [{"t": "比必有所畜。", "b": "《易·序卦》"}, {"t": "畜种菽粟,不足以食之。", "b": "《墨子·七患》"}, {"t": "畜积收藏于秋冬。", "b": "《荀子·天论》"}, {"t": "既畜王资而承故国之衅。", "b": "《韩非子·五蠹》"}, {"t": "小娥父畜巨产,隐名商贾间。", "b": "唐·李公佐《谢小娥传》"}], "words": [{"w": "畜恨", "t": "积恨"}, {"w": "畜聚", "t": "积储;积累;积储的财物"}, {"w": "畜德", "t": "修积德行"}, {"w": "畜锐", "t": "积蓄锐气。"}]}, {"meaning": "收容。", "cites": [{"t": "身边畜得一婢,小名金杏。", "b": "《警世通言》"}, {"t": "获罪于两君,天下谁畜之?", "b": "《左传》"}], "words": [{"w": "畜妾", "t": "娶小老婆"}, {"w": "畜之", "t": "容纳之意。"}]}, {"meaning": "保存;收藏。", "cites": [{"t": "[李生] 又畜一短剑,甚利。", "b": "唐·蒋防《霍小玉传》"}], "words": [{"w": "畜藏", "t": "积蓄储藏"}, {"w": "畜秽", "t": "藏秽,有丑恶的行为。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2048wx','阅','1','yuè','门','10','','[{"pinyin": "yuè", "defs": [{"meaning": "(形声。从门,说省声。象在门里清点东西。本义:在门内考察、计算事物)。"}, {"meaning": "同本义。", "cites": [{"t": "阅,具数于门中也。", "b": "《说文》"}]}, {"meaning": "引申为计算。", "cites": [{"t": "阅,具也。", "b": "《小尔雅》"}, {"t": "阅,数也。", "b": "《广雅》"}, {"t": "商人阅其祸败之衅,必始于火。", "b": "《左传·襄公九年》。注:“阅,犹数也。”"}], "words": [{"w": "阅问", "t": "逐一询问。"}]}, {"meaning": "察看;视察,考查。", "cites": [{"t": "常以秋、岁末之时阅其民。", "b": "《管子》"}], "words": [{"w": "阅实", "t": "查对实事"}, {"w": "阅狱", "t": "查看监狱"}, {"w": "阅审", "t": "审核"}, {"w": "阅稼", "t": "查看禾苗生长情况"}, {"w": "阅试", "t": "审查考试。"}]}, {"meaning": "检阅。", "cites": [{"t": "马端敏公新贻亲临校场阅射。", "b": "清·薛福成《庸盦笔记》"}], "words": [{"w": "阅武", "t": "检阅军队。"}]}, {"meaning": "看;阅读。", "cites": [{"t": "阅金经。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "苏黄共阅。", "b": "明·魏学洢《核舟记》"}, {"t": "公阅毕。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "阅卷", "t": "评阅试卷"}, {"w": "阅荐", "t": "审阅荐举"}, {"w": "阅看", "t": "阅读"}, {"w": "阅正", "t": "审阅指正。"}]}, {"meaning": "经历。", "cites": [{"t": "那夜跳窗而出,原来就是此楼,思之恍如昨日,不想早阅三年。", "b": "《铁花仙史》"}], "words": [{"w": "阅日", "t": "过日子"}, {"w": "阅月", "t": "经过一月"}, {"w": "阅岁", "t": "经过一年"}, {"w": "阅世", "t": "经历时世。"}]}, {"meaning": "观赏。", "cites": [{"t": "历观今古,无臣下与君上同坐阅戏者。", "b": "唐·吕道生《安禄山》"}], "words": [{"w": "阅胜", "t": "观赏美景"}, {"w": "阅戏", "t": "看戏。"}]}, {"meaning": "总聚;汇集。", "cites": [{"t": "川阅水以成川。", "b": "陆机《叹逝赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2049wx','羞','1','xiū','羊','10','','[{"pinyin": "xiū", "defs": [{"meaning": "(会意兼形声。据甲骨文,以手持羊,表示进献。小篆从羊,从丑,丑亦声。“丑”是手的讹变。本义:进献)。"}, {"meaning": "同本义。", "cites": [{"t": "羞,进献也。从羊,羊所进也。", "b": "《说文》"}, {"t": "以式法掌祭祀之戒具,与其荐羞。", "b": "《周礼·宰夫》。注:“庶羞,内羞”。按,内羞,房中之羞也。"}, {"t": "共其笾荐羞之实。", "b": "《周礼·笾人》。注:“荐羞皆进也。”"}, {"t": "可荐于鬼神,可羞于王公。", "b": "《左传》"}], "words": [{"w": "羞豆", "t": "古代祭祀宴享时进献食物的一种盛器"}, {"w": "羞膳", "t": "进献食品。"}]}, {"meaning": "推荐;进用。", "cites": [{"t": "有武德以羞为正卿。", "b": "《国语·晋语九》"}]}, {"meaning": "假借为“丑”。感到耻辱。", "cites": [{"t": "或承之羞。", "b": "《易恒》"}, {"t": "惟口启羞。", "b": "《礼记·缁人》"}, {"t": "无作神羞。", "b": "《左传·襄公十八年》"}, {"t": "杀身无益,适足增羞。", "b": "汉·李陵《答苏武书》"}], "words": [{"w": "羞怍", "t": "羞耻,惭愧。"}]}, {"meaning": "因惭愧而难为情。", "cites": [{"t": "吾羞,不忍为之下。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "十四为君妇,羞颜未尝开。", "b": "唐·李白《长干行》"}, {"t": "一则贾环羞口难开,二则贾环也不在意。", "b": "《红楼梦》"}], "words": [{"w": "羞蛾", "t": "美女的双眉"}, {"w": "羞人子", "t": "羞答答的"}, {"w": "羞杀人", "t": "羞死人"}, {"w": "羞红", "t": "因害羞而脸红"}, {"w": "羞脚", "t": "因怕羞而不敢向前"}, {"w": "羞懒", "t": "羞愧。"}]}, {"meaning": "嘲弄;侮辱。", "cites": [{"t": "那老子信了婆子的言语,带水带浆的羞辱毁骂了儿子几次。", "b": "《初刻拍案惊奇》"}], "words": [{"w": "羞污", "t": "玷污"}, {"w": "羞戮", "t": "羞辱"}, {"w": "羞薄", "t": "轻视;鄙薄"}, {"w": "羞丑", "t": "羞辱出丑。"}]}, {"meaning": "怕。", "cites": [{"t": "看朱渐成碧,羞日不禁风。", "b": "唐·刘禹锡《赠眼医婆罗门僧》"}], "words": [{"w": "羞影", "t": "怕看影子"}, {"w": "羞明", "t": ""}]}, {"meaning": "熟的食物。", "cites": [{"t": "燕与羞俶,献无常数。", "b": "《仪礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2050wx','羔','1','gāo','灬','10','','[{"pinyin": "gāo", "defs": [{"meaning": "(会意。从羊,从火,下面的四点由“火”变来。甲骨文字形正象羊在火上。本义:小羊)。"}, {"meaning": "同本义。", "cites": [{"t": "羔,羊子也。", "b": "《说文》"}, {"t": "凡祭祀饰羔。", "b": "《周礼·羊人》"}, {"t": "卿执羔。", "b": "《周礼·大宗伯》。注:“取其群而不失之类。”"}, {"t": "羔取其执之不鸣,杀之不号,乳必跪而受之,类死义知礼者也。", "b": "《公羊传·庄公二十四年》注"}, {"t": "献羔祭韭。", "b": "《诗·豳风·七月》"}, {"t": "羔裘豹饰。", "b": "《诗·郑风·羔裘》"}], "words": [{"w": "羔裘", "t": "古代诸侯用为朝服的小羊皮袍"}, {"w": "羔雁", "t": "羔羊和大雁;为订婚的一种礼物;古代用为卿、大夫的贽礼"}, {"w": "羔币", "t": "古代用羔皮作币帛,用作征聘贤士的礼品"}, {"w": "羔犊", "t": "羊羔和犊。常比喻弱的一方。"}]}, {"meaning": "树秧或菜秧。", "cites": [{"t": "黄菘养土羔,老楮生树鸡。", "b": "《东坡集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2051wx','瓶','1','píng','瓦','10','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从瓦,并声。《说文》本从缶。缶(fǒu),瓦器,即陶制器皿。本义:汲水器)。"}, {"meaning": "古代比缶小的容器,用以汲水,也用以盛酒食。", "cites": [{"t": "瓶,瓮也。(瓮,汲瓶也)。", "b": "《说文》"}, {"t": "缶其小者谓之瓶。", "b": "《方言》五"}, {"t": "羸其瓶。", "b": "《易·井》"}, {"t": "新盆槃瓶。", "b": "《仪礼·士丧礼》"}]}, {"meaning": "泛指腹大颈长的容器。", "cites": [{"t": "盛于盆,尊于瓶。", "b": "《礼记·礼器》"}, {"t": "吾一瓶一缽足矣。", "b": "清·彭端叔《为学一首示子侄》"}], "words": [{"w": "花瓶", "t": "插花用的瓶子"}, {"w": "瓷瓶;暖瓶;两瓶牛奶;喝了一瓶酒;瓶彝", "t": "祭器"}, {"w": "瓶落水", "t": "“不”的隐语。瓶子掉进水里,水往瓶里灌,挤出空气,发出不、不、不的声音,故称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2052wx','拳','1','quán','手','10','','[{"pinyin": "quán", "defs": [{"meaning": "(形声。夲义:紧握的手。俗称拳头)。"}, {"meaning": "同本义。", "cites": [{"t": "拳,手也。", "b": "《说文》。按,张之为掌,卷之为拳。”"}, {"t": "鲁君许诺,乃使吏鞟其拳。", "b": "《吕氏春秋》"}], "words": [{"w": "挥拳;赤手空拳", "t": ""}]}, {"meaning": "弓弩。", "cites": [{"t": "士张空拳。", "b": "《汉书·李广传》"}]}, {"meaning": "屈曲;卷曲。", "cites": [{"t": "其棱细则拳曲。", "b": "《庄子·人间世》"}, {"t": "手不得拳,膝不得屈。", "b": "《颜氏家训·勉学》"}], "words": [{"w": "拳拳弯弯", "t": "卷曲的样子"}, {"w": "拳毛", "t": "卷曲的毛发"}, {"w": "拳挛", "t": "拳曲;屈曲"}, {"w": "拳毛", "t": "毛发卷曲"}, {"w": "拳足", "t": "卷曲脚爪"}, {"w": "拳发", "t": "头发卷曲。"}]}, {"meaning": "勇壮。", "cites": [{"t": "无拳无勇。", "b": "《诗·巧言》。传:“力也。”"}, {"t": "有拳勇股肱之力。", "b": "《国语·齐语》。注:“人勇为拳。”"}], "words": [{"w": "拳果", "t": "壮勇果断"}, {"w": "拳勇", "t": "勇壮"}, {"w": "拳捷", "t": "勇壮敏捷"}, {"w": "拳猛", "t": "勇猛"}, {"w": "拳腕", "t": "犹勇力"}, {"w": "拳儇", "t": "勇壮矫捷。"}]}, {"meaning": "诚挚。", "cites": [{"t": "拳拳之忠,终不能自列。", "b": "司马迁《报任安书》"}, {"t": "不胜拳拳。", "b": "《汉书·贡禹传》"}], "words": [{"w": "拳拳好善", "t": "诚心诚意行善"}, {"w": "拳挚", "t": "诚挚。"}]}, {"meaning": "表示动量,用于拿拳头打人的动作。", "cites": [{"t": "你便在我脸上打一百拳也不妨!", "b": "《水浒传》"}]}, {"meaning": "表示物量,相当于“桩”、“件”。", "cites": [{"t": "我这一去,不得一拳儿好买卖不回来。", "b": "张国宾《合汗衫》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2053wx','粉','1','fěn','米','10','','[{"pinyin": "fěn", "defs": [{"meaning": "(会意。从米,从分,分亦声。本义:米细末。亦指谷类、豆类作物子实的细末)。"}, {"meaning": "同本义。", "cites": [{"t": "粉,傅面者也。", "b": "《说文》"}, {"t": "藻火粉米。", "b": "《书·益稷》。郑注:“粉米,白米也。”"}, {"t": "石崇厕常有十余婢侍列,皆丽服藻饰,置甲煎粉、沉香汁之属,无不毕备。", "b": "《世说新语·汰侈》"}]}, {"meaning": "妆饰用的白色粉末,亦有染成红色者。", "cites": [{"t": "何平叔美姿仪,面至白,魏明帝疑其傅粉。", "b": "《世说新语·容止》"}], "words": [{"w": "脂粉;粉面", "t": "傅粉的脸。"}]}, {"meaning": "用米、豆类或马铃薯等淀粉制成的食品,特指粉条或粉丝。", "cites": [{"t": "他一时慌了,弯下腰去抓那粉汤。", "b": "《儒林外史》"}], "words": [{"w": "米粉;炒粉;凉粉;粉汤", "t": "粉丝汤"}, {"w": "粉团", "t": "食品名。用糯米制成,外裹芝麻,置油中炸熟,犹今之麻团。"}]}, {"meaning": "研成粉末;粉碎。", "cites": [{"t": "粉,分也。研米使分散也。", "b": "《释名》"}], "words": [{"w": "粉零麻碎", "t": "极言粉碎"}, {"w": "粉骨捐躯", "t": "谓粉碎骨,献出生命。"}]}, {"meaning": "白色的;带白色的;粉红色的。", "cites": [{"t": "粉粳五十斛。", "b": "《红楼梦》"}], "words": [{"w": "粉粳", "t": "呈粉红色的粳米"}, {"w": "粉巾", "t": "白色汗巾"}, {"w": "粉白", "t": "形容女子面容白皙、姣好;亦形容洁白"}, {"w": "粉色", "t": "白色;亦指粉红色。常用以形容有关艳情的事件。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2054wx','料','1','liào','斗','10','','[{"pinyin": "liào", "defs": [{"meaning": "(会意。从斗,从米,表示用斗量米。本义:称量)。"}, {"meaning": "计数;计量;核计。", "cites": [{"t": "料,量也。从斗,米在其中,会意。", "b": "《说文》"}, {"t": "宣王料民于太原。", "b": "《国语·晋语》。注:“数也。”"}, {"t": "楚师可料也。", "b": "《国语·楚语》"}, {"t": "夫古者不料民而知其多少。", "b": "《国语·周语上》"}], "words": [{"w": "料校", "t": "计数检核"}, {"w": "料民", "t": "计点人数"}, {"w": "料数", "t": "计数"}, {"w": "料算", "t": "估算。"}]}, {"meaning": "估量;揣度;料想。", "cites": [{"t": "捭之者,料其情也。", "b": "《鬼谷子·捭阖》"}, {"t": "不复料其虚实。", "b": "《资治通鉴》"}, {"t": "料大王士卒足以当项王乎。", "b": "《史记·项羽本纪》"}, {"t": "大王自料,勇悍仁强,孰与项王?", "b": "《史记·淮阳侯列传》"}], "words": [{"w": "料知", "t": "犹估计"}, {"w": "料来", "t": "估计;料想"}, {"w": "料量", "t": "估计,测度"}, {"w": "料道", "t": "估计到,预料"}, {"w": "料得", "t": "预测到;估计到"}, {"w": "料敌", "t": "估量、判断敌情"}, {"w": "料知", "t": "料想到"}, {"w": "料然", "t": "料想"}, {"w": "料莫", "t": "想来"}, {"w": "料猜", "t": "猜测"}, {"w": "料世", "t": "揣度时势。"}]}, {"meaning": "选择,挑选。", "cites": [{"t": "逊料得精兵八千余人。", "b": "《三国志·陆逊传》"}], "words": [{"w": "料人", "t": "选择人才"}, {"w": "料取", "t": "选取"}, {"w": "料选", "t": "挑选;拣选"}, {"w": "料择", "t": "选择"}, {"w": "料拣", "t": "选择,拣择。"}]}, {"meaning": "安排,料理;管理。", "cites": [{"t": "料,理也。", "b": "《玉篇》"}, {"t": "比当料理。", "b": "《晋书·王徽之传》"}, {"t": "导后料检中书故事。", "b": "《晋书·周顗传》"}, {"t": "料检太祖巾箱。", "b": "《宋书·王僧绰传》"}, {"t": "琴童料持下晌午饭。", "b": "王实甫《西厢记》"}], "words": [{"w": "料持", "t": "料理,安排;对付,收拾"}, {"w": "料吏", "t": "指管理胥吏"}, {"w": "料度机宜", "t": "料理事务"}, {"w": "料实", "t": "清点,查实"}, {"w": "料检", "t": "犹查点;清理"}, {"w": "料视", "t": "照料"}, {"w": "料高", "t": "看守;登高守望。是一种苦役。"}]}, {"meaning": "小看。", "cites": [{"t": "常言“海水不可斗量”,你休料我。", "b": "明·冯梦龙《喻世明言》"}]}, {"meaning": "丢,撂。", "cites": [{"t": "我何不把银子料在水里,也呼地的响一声?", "b": "《醒世恒言》"}]}, {"meaning": "敌,对付。", "cites": [{"t": "问众官:“你怎生料敌?”", "b": "《三国志平话》"}]}, {"meaning": "隋及唐宋时官吏于俸禄外所津贴的食料、口粮。", "cites": [{"t": "官优有禄料。", "b": "白居易《咏所乐》"}], "words": [{"w": "料食", "t": "犹俸禄"}, {"w": "料钱", "t": "唐宋旧制,官吏除俸禄外,有时另给食料或折钱发给,称料钱。"}]}, {"meaning": "供人畜食用或为植物提供营养的物品。", "cites": [{"t": "每月但(只)是纳草纳料的,有些常例钱。", "b": "《水浒传》"}], "words": [{"w": "马料;饮料;肥料;草料;料袋", "t": "盛装牲口草料的口袋"}, {"w": "料谷", "t": "饲养牲口的谷物"}, {"w": "料槽", "t": "放置牲口食料的食槽。"}]}, {"meaning": "宗,番。", "cites": [{"t": "一连打了两料,打得宋江皮开肉绽,鲜血迸流。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2055wx','益','1','yì','皿','10','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。小篆字形。象器皿中有水漫出。从皿,从水。“水”已隶变。本义:“溢”的本字。水漫出)。"}, {"meaning": "同本义。", "cites": [{"t": "益,饶也。", "b": "《说文》。按,从水,浮于四,会意。字亦作溢。"}]}, {"meaning": "引申为水涨。", "cites": [{"t": "澭水暴益。", "b": "《吕氏春秋》"}]}, {"meaning": "在某些方面增加(如体积、数量、程度等)。", "cites": [{"t": "损益,盛衰之始也。", "b": "《易·杂卦传》"}, {"t": "人或益之,人或损之,胡可得而法?", "b": "《吕氏春秋·察今》"}, {"t": "有所广益。", "b": "诸葛亮《出师表》"}, {"t": "斟酌损益。", "b": ""}, {"t": "大有所益。", "b": "《资治通鉴·汉纪》"}], "words": [{"w": "增益;延年益寿;益甲", "t": "增兵"}, {"w": "益兵", "t": "增加兵力"}, {"w": "益封", "t": "增加封邑"}, {"w": "益军", "t": "益兵"}, {"w": "益损", "t": "增减;兴革"}, {"w": "益算", "t": "增加岁数"}, {"w": "益赋", "t": "增加赋税。"}]}, {"meaning": "助;补助。", "cites": [{"t": "与我齐者,吾不与处,无益我者也。", "b": "《吕氏春秋·贵当》"}]}, {"meaning": "扩大,加大。", "cites": [{"t": "民众城小,则益城。", "b": "《谷梁传》"}]}, {"meaning": "富裕。", "cites": [{"t": "其家必日益。", "b": "《吕氏春秋·贵当》"}]}, {"meaning": "骄傲自满。", "cites": [{"t": "有貌愿而益, 有长若不肖。", "b": "《庄子》"}]}, {"meaning": "更加。", "cites": [{"t": "君之疾在肌肤,不治将益深。", "b": "《韩非子·喻老》"}, {"t": "如水益深,如火益热。", "b": "《孟子》"}, {"t": "益狎。", "b": "唐·柳宗元《三戒》"}, {"t": "香远益清。", "b": "宋·周敦颐《爱莲说》"}, {"t": "敌行益还。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "精益求精;益用伤悼", "t": "更加悲伤"}, {"w": "益复", "t": "更加;越发"}, {"w": "益发", "t": "更加,越发。"}]}, {"meaning": "渐渐。", "cites": [{"t": "益习其怕,又近出前后(习,熟悉,习惯)。", "b": "唐·柳宗元《三戒》"}]}, {"meaning": "任何一种好处或利益 ——跟“害”相对。", "cites": [{"t": "谦得益。", "b": "宋·欧阳修《新五代史·伶官传·序》"}, {"t": "无益吾事。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "有益于身。", "b": "清·刘开《问说》"}, {"t": "取善之益。", "b": ""}], "words": [{"w": "受益不浅", "t": ""}]}, {"meaning": "州名 。汉武帝所置十三刺史部之一。辖境约当今四川省折多山,云南省怒山、哀牢山以东,甘肃省武都、两当,陕西省秦岭以南,湖北省郧县、保康西北,贵州省除东边以外地区。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2056wx','兼','1','jiān','丷','10','','[{"pinyin": "jiān", "defs": [{"meaning": "(会意。小篆字形,从又(手),从秝(lì)。字形象一手持两棵庄稼。本义:一手执两禾。引申为同时进行几桩事情或占有几样东西)。"}, {"meaning": "同时具有或涉及几种事务或若干方面。", "cites": [{"t": "兼,并也。", "b": "《说文》"}, {"t": "兼执之,以进。", "b": "《仪礼·聘礼》。注:“犹两也。”"}, {"t": "兼巾之。", "b": "《仪礼·士昏礼》。注:“六豆共巾也。”"}, {"t": "兼诸弣。", "b": "《仪礼·乡射礼》。注:“并矢于弣。”"}, {"t": "不可得兼。", "b": "《孟子·告子上》"}, {"t": "丞相兼枢密使。", "b": "宋·文天祥《 后序》"}, {"t": "兼百花之长。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "兼筑雕刻。", "b": "蔡元培《图画》"}], "words": [{"w": "兼祧", "t": "一子兼作两房的后嗣。祧继承上代"}, {"w": "兼资", "t": "与通;并有"}, {"w": "兼署", "t": "官吏除本职外,又兼理其他职务"}, {"w": "兼味", "t": "指两种以上的菜肴。"}]}, {"meaning": "合并,由部分合成整体。", "cites": [{"t": "约从离衡,兼韩、魏、燕、楚、齐、赵、宋、卫、中山之众。", "b": "贾谊《过秦论》"}]}, {"meaning": "并吞;兼并。", "cites": [{"t": "其兼天下不难矣。", "b": "《韩非子·亡征》"}, {"t": "孺子长矣,而相吾室,欲兼我也。", "b": "《左传·昭公八年》"}], "words": [{"w": "兼列", "t": "犹兼并"}, {"w": "兼畜", "t": "犹兼并,并吞"}, {"w": "兼弱攻昧", "t": "吞并弱者攻打昏者。"}]}, {"meaning": "倍,加倍。", "cites": [{"t": "王馈兼金一百。", "b": "《孟子》。注:“其价兼倍于常者。”"}, {"t": "利不兼,赏不倍。", "b": "《马王堆汉墓帛书》"}, {"t": "读书倍文,功力兼人。", "b": "唐·韩愈《韩滂墓志铭》"}, {"t": "兼旬愈。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "兼只", "t": "几只,数只"}, {"w": "兼日", "t": "连日,不止一日"}, {"w": "兼旬", "t": "二十天"}, {"w": "兼通", "t": "通晓两门或两门以上的学问或技艺。"}]}, {"meaning": "重复;累积。", "cites": [{"t": "[家人]重金兼紫,相继为藩辅。", "b": "《后汉书·宦者吕强传》"}]}, {"meaning": "尽;竭尽。", "cites": [{"t": "圣人纵其欲、兼其情,而制焉者理矣。", "b": "《荀子》"}, {"t": "夫日兼照天下,一物不能当也。人君兼照一国,一人不能壅也。", "b": "《韩非子》"}]}, {"meaning": "同,连同。", "cites": [{"t": "寒暑不兼时而至。", "b": "《韩非子·显学》"}]}, {"meaning": "全部;整个。", "cites": [{"t": "兼天下之众,莫敢不为其所好,而辟其所恶。", "b": "《商君书》"}], "words": [{"w": "兼裒", "t": "广为聚集。"}]}, {"meaning": "表示另一方面,可译为“还”、“同时”、“再加上”之类。", "cites": [{"t": "兼有步兵。", "b": "宋·司马光《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "兼仗父兄之烈。", "b": ""}, {"t": "兼与药相粘。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "兼用刺激。", "b": "蔡元培《图画》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2057wx','烤','1','kǎo','火','10','','[{"pinyin": "kǎo", "defs": [{"meaning": "(形声。从火,考声。本义:用火烘熟或烤干)。"}, {"meaning": "暴晒。", "cites": [{"t": "炙热的阳光烤着他瘦长的身子。", "b": "巴金《将军集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2058wx','烘','1','hōng','火','10','','[{"pinyin": "hōng", "defs": [{"meaning": "(形声。从火,共声。本义:烧,焚烧)。"}, {"meaning": "同本义。", "cites": [{"t": "烘,燎也。", "b": "《尔雅·释言》"}, {"t": "卬烘于歁。", "b": "《诗·小雅·白华》"}], "words": [{"w": "烘眼", "t": "角膜炎之类的眼病,俗称“红眼”"}, {"w": "烘焰", "t": "光焰"}, {"w": "烘腾腾", "t": "火旺盛貌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2059wx','烦','1','fán','火','10','','[{"pinyin": "fán", "defs": [{"meaning": "(会意。从页(xié),从火。从“页”表示与头部有关;从“火”,表示发烧。本义:头痛发烧)。"}, {"meaning": "烦躁,烦闷。", "cites": [{"t": "烦,热头痛也。", "b": "《说文》"}, {"t": "烦则喘喝。", "b": "《素问·生气通天论》。注:“谓烦躁。”"}, {"t": "烦气为虫。", "b": "《淮南子·精神》。按,旱热也。"}, {"t": "阿兄得闻之,怅然心中烦。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "新鬼烦冤旧鬼哭。(烦,愁苦。)", "b": "唐·杜甫《兵车行》"}, {"t": "至于烦乃止也已,无以生疾。", "b": "《左传·昭公元年》"}], "words": [{"w": "心烦", "t": "心里烦躁"}, {"w": "烦积", "t": "烦闷积郁"}, {"w": "烦困", "t": "烦躁疲劳"}, {"w": "烦怨", "t": "烦恼怨恨。"}]}, {"meaning": "烦琐;繁多。", "cites": [{"t": "小人不避其禁,故刑烦。", "b": "《商君书·算地》"}, {"t": "法省则不烦。", "b": "《淮南子·主术》。注:“多也。”"}, {"t": "世浊则礼烦。", "b": "《吕氏春秋·音初》"}, {"t": "列五王之德,烦烦如繁诸乎。", "b": "《大戴礼记·少间》。注:“众也。”"}, {"t": "以奉使称臣,频烦至吴。", "b": "《三国志·费伟传》"}, {"t": "话休絮烦。", "b": "《水浒传》"}], "words": [{"w": "烦务", "t": "繁杂的事务"}, {"w": "烦细", "t": "繁杂琐碎"}, {"w": "烦富", "t": "繁多;庞杂"}, {"w": "烦几", "t": "繁杂的政事"}, {"w": "烦鄙", "t": "繁杂卑俗"}, {"w": "要言不烦", "t": ""}]}, {"meaning": "乱;纠缠。", "cites": [{"t": "拨烦理乱,兼肃文教。", "b": "《晋书·刘颂传》"}], "words": [{"w": "烦委", "t": "杂乱堆积"}, {"w": "烦悖", "t": "牵缠;纷乱"}, {"w": "烦悖", "t": "纷乱谬误"}, {"w": "烦舌", "t": "纷繁杂乱;心情烦闷,思绪混乱。"}]}, {"meaning": "相烦;烦劳。", "cites": [{"t": "烦,劳也;扰也。", "b": "《广雅》"}, {"t": "卫者趋数烦志。", "b": "《礼记·乐记》"}, {"t": "数则烦,烦则不敬。", "b": "《礼记·祭义》"}, {"t": "不可以烦大臣。", "b": "《战国策·秦策》"}, {"t": "是好不好,烦大巫妪为人报河伯。", "b": "《史记·滑稽列传》"}], "words": [{"w": "烦交", "t": ""}]}, {"meaning": "搅扰;烦扰。", "cites": [{"t": "水烦则鱼鼈不大。", "b": "《史记·乐书》"}, {"t": "农时惮烦民。", "b": "王安石《杂咏》"}, {"t": "以物烦其性命乎。", "b": "《淮南子·俶真》"}], "words": [{"w": "烦散", "t": "烦扰散乱"}, {"w": "烦累", "t": "烦扰;劳累"}, {"w": "烦搅", "t": "烦扰;搅扰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2060wx','烧','1','shāo','火','10','','[{"pinyin": "shāo", "defs": [{"meaning": "(形声。从火,尧声。本义:使物着火)。"}, {"meaning": "同本义。", "cites": [{"t": "烧,爇也。", "b": "《说文》"}, {"t": "雏烧。", "b": "《礼记·内则》。注:“烧烟,于火中也。”"}, {"t": "齐之北泽烧火。", "b": "《管子·轻重甲》。注:“猎而行火曰烧。”"}, {"t": "卖炭翁,伐薪烧炭南山中。", "b": "唐·白居易《卖炭翁》"}, {"t": "烧尽北船,延及岸上营落。", "b": "《资治通鉴》"}], "words": [{"w": "干柴好烧;他把衣服烧了一个洞;烧葬", "t": "烧焚祭品"}, {"w": "烧丹炼汞", "t": "道家用朱砂水银等物炼成金丹以求长生不老"}, {"w": "烧糊了卷子", "t": "喻外貌丑陋"}, {"w": "烧埋钱", "t": "烧化埋葬死人的费用"}, {"w": "烧冷灶", "t": "敷衍不得时的人"}, {"w": "烧利市", "t": "商人在开始营业时烧纸祭献福神"}, {"w": "烧琴煮鹤", "t": "比喻糟蹋美好的事物。"}]}, {"meaning": "烹调方法之一。先用油炸,再加汤汁炒或炖,或先煮熟再用油炸。", "cites": [{"t": "西崦人家应最乐,煮葵烧笋饷春耕。", "b": "苏轼《新城道中诗》"}]}, {"meaning": "野火。", "cites": [{"t": "夕照红于烧,晴空碧胜蓝。", "b": "白居易《秋思诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2061wx','烛','1','zhú','火','10','','[{"pinyin": "zhú", "defs": [{"meaning": "(形声。从火,蜀声。本义:古代照明用的火炬)。"}, {"meaning": "同本义。", "cites": [{"t": "烛,庭燎大烛也。", "b": "《说文》。按,燋也。未爇曰燋,执之曰日烛,树地曰庭燎。苇薪为之,小者麻蒸为之。"}, {"t": "执烛于西阶上。", "b": "《仪礼·燕礼》"}, {"t": "共坟烛庭燎。", "b": "《周礼·司烜氏》。注:“树于门外,曰大庭燎。”"}, {"t": "独不见跋。", "b": "《礼记·曲礼》"}, {"t": "火在地曰燎,执之曰烛。", "b": "《仪礼·士丧礼》注"}, {"t": "举烛者,尚明也。", "b": "《韩非子·外储说左上》"}, {"t": "昼短苦夜长,何不秉烛游?", "b": "《古诗十九首·生年不满百》"}, {"t": "江月亭前桦烛香,龙门阁上驮声长。", "b": "陆游《雪夜感旧》"}], "words": [{"w": "烛火", "t": "火炬,火把"}, {"w": "烛炬", "t": "指火炬或蜡烛。"}]}, {"meaning": "蜡烛(始于唐代)。", "cites": [{"t": "高堂粉壁图蓬瀛,烛前一见沧洲清。", "b": "李白《同族弟金城尉叔卿烛照山水壁画歌》"}, {"t": "烛分歌扇泪,雨送酒船香。", "b": "李商隐《夜饮》"}, {"t": "淮阳多病偶求欢,客袖侵霜与烛盘。", "b": "杜牧《初冬夜饮》"}], "words": [{"w": "烛信", "t": "插蜡烛用的签子"}, {"w": "烛奴", "t": "雕刻成人形的烛台;泛指一般烛台"}, {"w": "烛心", "t": "蜡烛中心用以点火的灯草、纱线等。"}]}, {"meaning": "照;照亮。", "cites": [{"t": "夫日,兼烛天下。", "b": "《韩非子·内储说上》"}, {"t": "望见青枫城里火光烛天。", "b": "《儒林外史》"}, {"t": "名高天下而光烛邻国。", "b": "《史记·鲁仲连邹阳列传》"}, {"t": "明烛南天。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "烛银", "t": "精光闪耀的银子"}, {"w": "烛天(照耀天空)烛明(照亮", "t": ""}, {"w": "烛夜", "t": "照亮黑夜"}, {"w": "烛幽", "t": "照亮昏暗"}, {"w": "烛远", "t": "光照远方"}, {"w": "烛临", "t": "由上向下照射。"}]}, {"meaning": "洞察。", "cites": [{"t": "智术之士,必远见而明察,不明察,不能烛私。", "b": "《韩非子·孤愤》"}], "words": [{"w": "烛知", "t": "明察洞悉"}, {"w": "烛物", "t": "明察事物"}, {"w": "烛微", "t": "观察入微"}, {"w": "烛察", "t": "明察,洞察"}, {"w": "烛鉴", "t": "明鉴,明察。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2062wx','烟','1','yān','火','10','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从火,因声。本义:物质因燃烧而产生的气体)。"}, {"meaning": "同本义。", "cites": [{"t": "火壮则煙微。", "b": "陆机《连珠》"}, {"t": "煙炎之毁熸。", "b": "《后汉书·蔡邕传》"}, {"t": "日照香炉生紫烟。", "b": "李白《望庐山瀑布》"}, {"t": "烟焰迷漫。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "烟扑口鼻。", "b": "明·刘基《卖柑者言》"}, {"t": "烟炎张天。", "b": "宋·司马光《资治通鉴》"}, {"t": "烟焰雾雨。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "烟斜雾横(互文,表烟雾斜横。斜 横:升腾缭绕)。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "烟火邻居", "t": "指紧邻"}, {"w": "烟扛扛", "t": "形容烟雾腾腾的样子"}, {"w": "烟爨", "t": "炊烟"}, {"w": "烟蓬", "t": "小火轮客舱顶上的散座"}, {"w": "烟祀", "t": "香烟与祭祀。引申为后代"}, {"w": "烟尘", "t": "比喻战乱;借指参与战乱的部队"}, {"w": "烟井", "t": "住户;人家"}, {"w": "烟火", "t": "火警,火灾"}, {"w": "烟焰", "t": "烟和火焰"}, {"w": "夕烟", "t": "黄昏时的烟雾"}, {"w": "风烟", "t": "随风吹散的烟"}, {"w": "油烟;炊烟", "t": ""}]}, {"meaning": "烟状物;云气;雾气。", "cites": [{"t": "草树浮煙。", "b": "《素问·六元正纪大论》。注:“燥气也。”"}, {"t": "煙埃朦郁。", "b": "《素问·五常正大论》。注:“土气也。”"}, {"t": "烟涛微茫。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "向来之烟霞。", "b": ""}, {"t": "红烟蔽其左。", "b": "唐·李朝威《柳毅传》"}, {"t": "荒烟蔓草。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "烟霞成癖", "t": "有游山玩水的癖好"}, {"w": "烟雾尘天", "t": "乌烟瘴气;乱七八糟"}, {"w": "烟霞帐", "t": "绘有山水图画的帐帘帏幕"}, {"w": "烟缠", "t": "缠绵无力"}, {"w": "烟锁", "t": "烟雾笼罩"}, {"w": "烟娇", "t": "美女"}, {"w": "烟塍", "t": "雾气弥漫田塍"}, {"w": "烟蓑雨笠", "t": "蓑衣和斗笠"}, {"w": "烟月", "t": "云雾笼罩的月亮。"}]}, {"meaning": "堵塞。", "cites": [{"t": "凡待烟冲云梯临之法,必应城以御之。", "b": "《墨子·杂守》"}, {"t": "春秋行礼,以共烟祀。", "b": "汉《鲁相史晨祠孔庙奏铭》。"}]}, {"meaning": "烟草。", "cites": [{"t": "菸,草名,别名淡巴菰,一曰菸草。产自吕宋,明时始入中国。……采叶干之,切为细丝,可制各种之菸。……字俗借“烟”。", "b": "《中华大字典》"}], "words": [{"w": "烟窝", "t": "烟斗"}, {"w": "烟萝", "t": "藤萝一类的植物"}, {"w": "烟荷包", "t": "装烟丝用的小袋子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2063wx','烙','1','lào luò','火','10','','[{"pinyin": "lào", "defs": [{"meaning": "(形声。从火,各声。本义:把食物放在烧热的器物上焙熟)。"}, {"meaning": "用高温的金属烧灼。引申为打上或留下标志。", "cites": [{"t": "烧之剔之,刻之烙之。", "b": "《庄子·马蹄》"}], "words": [{"w": "烙花", "t": ""}]}, {"meaning": "用烙器(烧灼器)或烧灼剂烫。", "cites": [{"t": "沙僧只叫:“脚底烙得慌!”", "b": "《西游记》"}], "words": [{"w": "烙铁", "t": ""}]}]}, {"pinyin": "luò", "defs": [{"meaning": "灼;烧烤。", "cites": [{"t": "鞭、烙之数,風烙三十者鞭三百,烙五十者鞭五百。", "b": "《遼史》"}], "words": [{"w": "炮烙", "t": "古酷刑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2064wx','递','1','dì','辶','10','','[{"pinyin": "dì", "defs": [{"meaning": "(形声。从辵(chuò),虒(sī)声。本义:轮流;交替)。"}, {"meaning": "同本义。", "cites": [{"t": "递,更易也。", "b": "《说文》"}, {"t": "国之递甚也。", "b": "《战国策·齐策六》"}, {"t": "二八侍宿射递代些。", "b": "《楚辞·招魂》"}, {"t": "诈术递用。", "b": "《吕氏春秋·先巳》"}, {"t": "合场递进。", "b": "傅毅《舞赋》"}, {"t": "日月递炤(照)。", "b": "《荀子·天论》"}], "words": [{"w": "递嬗", "t": "不断地更迭、变化"}, {"w": "递代", "t": "互相替换"}, {"w": "递衣", "t": "轮流换穿同一件衣服"}, {"w": "递兴", "t": "交替兴起"}, {"w": "递迁", "t": "更易变化。"}]}, {"meaning": "特指通过驿站传递公文、货物等。", "cites": [{"t": "驿传旧有三等,曰步递,马递,急脚递。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "递运", "t": "转运;驿站运输。"}]}, {"meaning": "顺次地;一个一个地。", "cites": [{"t": "向使秦复爱六国之人,则递三世可至万世而为君,谁得而族灭也。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "递加;递减;递相", "t": "顺次,一个接一个,各自"}, {"w": "递转", "t": "依次转动"}, {"w": "递演", "t": "逐步演变"}, {"w": "递毁", "t": "依次毁废"}, {"w": "递化", "t": "顺次改变"}, {"w": "递日", "t": "一日接一日。"}]}, {"meaning": "驿车;驿马。", "cites": [{"t": "黄衣小使录姓名,领出长安乘递行。", "b": "唐·白居易《缚戎人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2065wx','涛','1','tāo','氵','10','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从水,寿声。本义:大波)。"}, {"meaning": "同本义。", "cites": [{"t": "涛,大波也。", "b": "《说文新附》"}, {"t": "扬波涛于碣石。", "b": "《后汉书·班彪传上》"}, {"t": "何必湘渊与涛濑?", "b": "《汉书·扬雄传上》"}, {"t": "水泫沄而涌涛。", "b": "《文选·张衡·思玄赋》"}, {"t": "烟涛微茫信难求。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "惊涛拍岸。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}, {"t": "怒涛排壑。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "涛水", "t": "波涛汹涌的大水"}, {"w": "涛雪", "t": "波涛激汤,水花如雪"}, {"w": "涛雷", "t": "波涛汹涌,声大如雷"}, {"w": "涛波", "t": "大波,波涛。"}]}, {"meaning": "像波涛一样的声音。", "cites": [{"t": "阴壑寒生万树涛。", "b": "明·王世贞《沸水岩》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2066wx','浙','1','zhè','氵','10','','[{"pinyin": "zhè", "defs": [{"meaning": "(形声。从水,折声。本义:水名。浙江,即钱塘江)。"}, {"meaning": "同本义 ,水名。即今钱塘江,上游为新安江。", "cites": [{"t": "浙,江水东至会稽山阴为浙江。", "b": "《说文》。按,即禹贡三江之南江也,但江故道今不可考,世俗以钱塘江当之。非是。钱唐江古谓之浙江。"}]}, {"meaning": "古州名,浙州 。其境约当今贵州习水县一带。"}, {"meaning": "浙江省的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2067wx','涝','1','láo lào','氵','10','','[{"pinyin": "láo", "defs": [{"meaning": "(形声。从水,劳声。本义:水名。在陕西省。源出秦岭,北流入渭水) 同本义。"}, {"meaning": "又名潦水。在陕西省户县、周至两县界上,源出秦岭,为关中八川之一。", "cites": [{"t": "涝水北注甘水,而乱流入于渭。", "b": "《水经注》"}]}, {"meaning": "汾水支流。源出山西省浮山县西北,西流至临汾市北注入汾水。"}]}, {"pinyin": "lào", "defs": [{"meaning": "水淹没;雨多成灾。", "cites": [{"t": "雨久成水,故其域恒涝也。", "b": "《晋书·袁甫传》"}], "words": [{"w": "涝漉", "t": "浸润其中"}, {"w": "涝疏旱溉", "t": "指庄稼受涝应排水,受旱应灌溉"}, {"w": "沥涝", "t": "沥水淹了庄稼"}, {"w": "内涝", "t": "地势低洼,积水不能及时排水而造成的涝灾"}, {"w": "涝洼地", "t": "低洼易淹的田地。"}]}, {"meaning": "浇水,灌溉。", "cites": [{"t": "公今早晚班春去,强劝涝田补岁饥。", "b": "宋·王安石《和钱学士喜雪》"}]}, {"meaning": "奶酪。", "cites": [{"t": "什么叫做涝?…原来是牛奶。", "b": "清·蘧园《负曝闲谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2068wx','浦','1','pǔ','氵','10','','[{"pinyin": "pǔ", "defs": [{"meaning": "(形声。从水,甫声。本义:水滨)。"}, {"meaning": "同本义。", "cites": [{"t": "浦,濒也。", "b": "《说文》"}, {"t": "率彼淮浦。", "b": "《诗·大雅·常武》"}, {"t": "江浦之橘。", "b": "《吕氏春秋·本味》"}, {"t": "望涔阳兮极浦。", "b": "《楚辞·湘君》"}, {"t": "召洛浦之宓妃。", "b": "张衡《思玄赋》"}], "words": [{"w": "浦淑", "t": "水边的美女"}, {"w": "浦帆", "t": "水滨的帆船"}, {"w": "浦溆", "t": "水边"}, {"w": "浦鸥", "t": "水边的鸥鸟"}, {"w": "浦滩", "t": "滩岸。"}]}, {"meaning": "江河与支流的汇合处。", "cites": [{"t": "还为越王禽于三江之浦。", "b": "《战国策·秦策》"}], "words": [{"w": "浦口", "t": "小河入江的地方"}, {"w": "浦海", "t": "江河的入海口。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2069wx','酒','1','jiǔ','酉','10','','[{"pinyin": "jiǔ", "defs": [{"meaning": "(会意。从水,从酉(yǒu)。“酉”本义就是酒。“酉”亦兼表字音。本义:用高粱、大麦、米、葡萄或其他水果发酵制成的饮料)。"}, {"meaning": "同本义。", "cites": [{"t": "酒,就也。所以就人性之善恶。", "b": "《说文》"}, {"t": "酒曰清酌。", "b": "《礼记·曲礼》"}, {"t": "酒食者,所以令欢也。", "b": "《礼记·乐记》"}, {"t": "酒者所以养老也,所以养病也。", "b": "《礼记·射义》"}, {"t": "酒,百乐之长。又,酒者,天下之美禄。", "b": "《汉书·食货志》"}, {"t": "不为酒困。", "b": "《论语·子罕》"}], "words": [{"w": "酒肆", "t": "酒店"}, {"w": "酒水", "t": "酒;筵席"}, {"w": "酒生", "t": "酒保,酒店伙计"}, {"w": "酒务", "t": "酒店。"}]}, {"meaning": "以酒荐祖庙。", "cites": [{"t": "卜辞所载之酒字为祭名。考古者酒熟而荐祖庙,然后天子与群臣饮之于朝。", "b": "罗振玉《殷虚文字类编》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2070wx','涉','1','shè','氵','10','','[{"pinyin": "shè", "defs": [{"meaning": "(会意。从水步。甲骨文字形。中间是水,两边两只脚,象涉水之形。本义:趟水过河)。"}, {"meaning": "同本义。", "cites": [{"t": "涉,徒行濿水也。", "b": "《说文》"}, {"t": "冯河,徒涉也。", "b": "《尔雅》。注:“无舟而渡水曰徒涉。”"}, {"t": "繇膝以上为涉。", "b": "《释水》"}, {"t": "过度谓之涉济。", "b": "《方言七》"}, {"t": "送子涉淇。", "b": "《诗·卫风·氓》"}, {"t": "澭水暴益,荆人弗知,循表而夜涉,溺死者千有余人。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "涉水登山", "t": "涉渡溪水并攀登山岭"}, {"w": "涉浅", "t": "徒步趟过浅水"}, {"w": "涉厉", "t": "涉水。厉,连衣涉水"}, {"w": "跋山涉水", "t": ""}]}, {"meaning": "泛指渡水。", "cites": [{"t": "楚人有涉江者,其剑自舟中坠于水。", "b": "《吕氏春秋·察今》"}, {"t": "晋师己亥涉河也。", "b": "《察传》"}], "words": [{"w": "涉人", "t": "船夫"}, {"w": "涉江", "t": "渡河,过河。"}]}, {"meaning": "经历,经过。", "cites": [{"t": "杭有卖果者,善藏柑,涉寒暑不溃。", "b": "明·刘基《卖柑者言》"}, {"t": "然后可以刚健强力,涉险而不伤。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "涉难", "t": "经历艰难"}, {"w": "涉旬", "t": "经过十天"}, {"w": "涉手", "t": "经手"}, {"w": "涉月", "t": "经月"}, {"w": "涉朔", "t": "经月"}, {"w": "涉阅", "t": "经历。"}]}, {"meaning": "牵涉,涉及,关连。", "cites": [{"t": "不相参涉,皆悉赡举。", "b": "《宋书·刘穆之传》"}], "words": [{"w": "涉疑", "t": "有跟某件事情发生牵连的嫌疑"}, {"w": "涉虚", "t": "假话;空话。"}]}, {"meaning": "跋涉。", "cites": [{"t": "吾闻负重涉远,不择地而休。", "b": "清·和邦额《夜谭随录》"}]}, {"meaning": "行走。", "cites": [{"t": "故乡路遥远,川陆不可涉。", "b": "南朝宋·谢灵运《登上戎石鼓山》"}]}, {"meaning": "至,到。", "cites": [{"t": "驱中国士众远涉江湖之间,不习水土;必生疾病。", "b": "《资治通鉴》"}]}, {"meaning": "游玩,游览。", "cites": [{"t": "园日涉以成趣,门虽设而常关。", "b": "晋·陶潜《归去来兮辞》"}]}, {"meaning": "入,进入。", "cites": [{"t": "不虞君之涉吾地也,何故?", "b": "《左传·僖公四年》"}], "words": [{"w": "涉秋", "t": "进入秋天"}, {"w": "涉足", "t": ""}]}, {"meaning": "涉猎。指阅读学习。", "cites": [{"t": "博涉书记。", "b": "《后汉书·仲长统传》"}], "words": [{"w": "涉目", "t": "过目,看过"}, {"w": "涉意", "t": "留意;在意"}, {"w": "涉略", "t": "涉猎,浏览。"}]}, {"meaning": "便语,喋喋。", "cites": [{"t": "朱鲔涉血于友于。", "b": "丘迟《与陈伯之书》"}]}, {"meaning": "渡口。", "cites": [{"t": "匏有苦叶,济有深涉。", "b": "《诗·邶风·氓》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2071wx','消','1','xiāo','氵','10','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从水,肖声。本义:消除;消灭)。"}, {"meaning": "同本义。", "cites": [{"t": "消,尽也。", "b": "《说文》"}, {"t": "消息阴阳。", "b": "枚乘《七发》。注:“消,灭也。”"}, {"t": "消雰埃于中宸。", "b": "张衡《西京赋》。注:“消,散也。”"}, {"t": "热多则筋弛骨消。", "b": "《素问·皮部论》。注:“消,烁也。”"}, {"t": "鸟兽之害人者消,然后人得平土而居之。", "b": "《孟子》"}, {"t": "诏求隐学之士能消灾复异者。", "b": "《三国志·魏志》"}, {"t": "娘娘一肚子气没地方散去,借酒消愁。", "b": "京剧《贵妃醉酒》"}], "words": [{"w": "消索", "t": "灭尽,散亡"}, {"w": "消炎", "t": "消除炎症;消除炎热"}, {"w": "消弭", "t": "消灭停止。"}]}, {"meaning": "消失,完全不存在。", "cites": [{"t": "内君子而外小人,君子道长,小人道消也。", "b": "《易·泰》"}, {"t": "观其不合而散逐消藏,则未尝不恨其道之难行也。", "b": "宋·曾巩《上杜相公书》"}], "words": [{"w": "消败", "t": "消失,衰败"}, {"w": "消挫", "t": "消散。"}]}, {"meaning": "减削。", "cites": [{"t": "消,减也。", "b": "《广雅》"}, {"t": "心思消缩,齿发凋耗,常恐卒填沟壑,独遗恨于无穷也。", "b": "宋·曾巩《再乞登对状》"}, {"t": "其间有户消落之家。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "消折", "t": "耗损;亏损"}, {"w": "消兵", "t": "减少兵员"}, {"w": "消沮", "t": "削减;减弱。"}]}, {"meaning": "消磨,打发。", "cites": [{"t": "无酒能消夜,随僧早闭门。", "b": "唐·方干《冬夜泊僧舍》"}, {"t": "乐琴书以消忧。", "b": "《文选·陶潜·归去来辞》"}], "words": [{"w": "消脱", "t": "消磨"}, {"w": "消日", "t": "消磨时光"}, {"w": "消取", "t": "排遣。取,语助词。"}]}, {"meaning": "享受;受用。", "cites": [{"t": "一片绿衫消不得,腰金拖紫是何人?", "b": "白居易《哭从弟诗》"}], "words": [{"w": "消花", "t": "花销。用掉的费用"}, {"w": "消淹", "t": "享用。"}]}, {"meaning": "售出。", "cites": [{"t": "因作者正苦于无人知道,因而没有消路。", "b": "鲁迅《书信集·致曹聚仁》"}], "words": [{"w": "消倒", "t": "犹倒卖"}, {"w": "消流", "t": "销售流通"}, {"w": "消售", "t": "销售;卖出 。"}]}, {"meaning": "禁受,经受。", "cites": [{"t": "更能消几番风雨,匆匆春又归去。", "b": "辛弃疾《摸鱼儿词》"}], "words": [{"w": "消任", "t": "禁受"}, {"w": "消消", "t": "犹言受得了"}, {"w": "消得", "t": "禁得起。"}]}, {"meaning": "抵得上,配得上。", "cites": [{"t": "莫夸十万兵威盛,消个忠良效顺无?", "b": "司空图《淮西诗》"}], "words": [{"w": "消不得", "t": "抵不上"}, {"w": "消得", "t": "值得;配得。"}]}, {"meaning": "需要;须。", "cites": [{"t": "那里消半碗饭时,那小官人命归泉世。", "b": "《警世通言》"}, {"t": "不消多事,随分便好。", "b": "《水浒传》"}], "words": [{"w": "消不的", "t": "不消;要不了"}, {"w": "不消说", "t": ""}]}, {"meaning": "消息。", "cites": [{"t": "两头往来,传消寄信都是我。", "b": "《救风尘》"}], "words": [{"w": "消耗", "t": "消息。"}]}, {"meaning": "糖尿病。", "cites": [{"t": "素有消疾,自为宰相,谢病不视事。", "b": "《后汉书》"}], "words": [{"w": "消中", "t": "即消渴"}, {"w": "消症", "t": "消疾。即消渴病"}, {"w": "消渴", "t": "中医学病名。口渴,善饥,尿多,消瘦。包括糖尿病、尿崩症等。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2072wx','涡','1','guō wō','氵','10','','[{"pinyin": "guō", "defs": [{"meaning": "水名。今称涡河。", "cites": [{"t": "濄水,首受淮阳扶沟浪汤洰东入淮。从水,过声。", "b": "《说文》"}]}, {"meaning": "古州名 。故地在今安徽省。"}]}, {"pinyin": "wō", "defs": [{"meaning": "(形声。本义:水的旋流)。"}, {"meaning": "酒窝,嘴角附近的小凹陷。", "cites": [{"t": "不知诗中道何语,但觉两颊生微涡。", "b": "苏轼《百步洪二首》"}]}, {"meaning": "沾染。", "cites": [{"t": "怕燕泥香点涡在琴书上。", "b": "《牡丹亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2073wx','浩','1','hào','氵','10','','[{"pinyin": "hào", "defs": [{"meaning": "(形声。从水,告声。本义:水势浩大)。"}, {"meaning": "同本义。", "cites": [{"t": "浩,浇也。从水,告声。虞书曰:“洪水浩浩。", "b": "《说文》。按,浇者,许以声训。”"}, {"t": "浩,遶也,水大也。", "b": "《字林》"}, {"t": "浩,浩流也。", "b": "《广雅》"}, {"t": "浩浩沅湘。", "b": "《楚辞·怀沙》"}, {"t": "浩浩瀚瀚。", "b": "《淮南子·俶真》"}, {"t": "曰浩泽。", "b": "《淮南子·地形》"}], "words": [{"w": "浩波", "t": "大波,洪波"}, {"w": "浩汗", "t": "浩浩,浩然,浩瀚。水盛大的样子"}, {"w": "浩洋", "t": "水流广阔洪大的样子。"}]}, {"meaning": "广远;盛大。", "cites": [{"t": "浩浩,滔天。", "b": "《书·尧典》。传:“盛大。”"}, {"t": "陈竽瑟兮浩倡。", "b": "《楚辞·东皇太一》。注:“大也。”"}], "words": [{"w": "浩壤", "t": "广阔的土地"}, {"w": "浩渺", "t": "广阔无边"}, {"w": "浩然", "t": "盛大纯一的样子;不可堵塞的样子;浩然之气的省称"}, {"w": "浩烦", "t": "浩大繁多"}, {"w": "浩滂", "t": "盛大。"}]}, {"meaning": "丰富,众多。", "cites": [{"t": "丧祭有余曰浩。", "b": "《礼记·王制》。注:“犹饶也。”"}], "words": [{"w": "浩博", "t": "广大众多"}, {"w": "浩漫", "t": "众多的样子;广阔的样子"}, {"w": "浩穰", "t": "盛大众多的样子"}, {"w": "浩侈", "t": "繁多。"}]}, {"meaning": "远;无边无际。", "cites": [{"t": "心飞扬兮浩荡。", "b": "《楚辞·河伯》。注:“志放貌也。”"}], "words": [{"w": "浩乎无际", "t": "广大无际"}, {"w": "浩浩漫漫", "t": "大雾无边无际。"}]}, {"meaning": "傲慢。", "cites": [{"t": "浩倨者则不亲。", "b": "《孔子家语·三怨》"}], "words": [{"w": "浩居", "t": "浩裾,浩倨。傲倨,怠慢不恭貌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2074wx','海','1','hǎi','氵','10','','[{"pinyin": "hǎi", "defs": [{"meaning": "(形声。从水,每声。本义:大海,海洋)。"}, {"meaning": "百川会聚之处。后指邻接大陆而区域范围小于洋的咸水水体。", "cites": [{"t": "海,天池也。以纳百川者。从水,每声。", "b": "《说文》。按,海势圆,就地心也。海味咸,湿热之气蒸也。海气绿,穹苍之映,云雾不能隔也。"}, {"t": "祖天地之左海也。", "b": "《礼记·乡饮酒义》。注:“海水之委也。”"}, {"t": "孙叔敖举于海。", "b": "《孟子·告子下》"}, {"t": "前途似海。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "半壁见海日。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "近海", "t": "靠近陆地的海域"}, {"w": "沿海", "t": "靠海的一带"}, {"w": "海岳", "t": "大海和山岳"}, {"w": "海藏", "t": "大海。藏:海的总汇。"}]}, {"meaning": "海水。", "cites": [{"t": "煮海为盐。", "b": "《汉书·晁错传》"}], "words": [{"w": "海老", "t": "海水枯竭"}, {"w": "海望", "t": "海水逢望日涨潮的现象。"}]}, {"meaning": "古人认为陆地四周皆为海,故用以指僻远地区。", "cites": [{"t": "九夷、八狄、七戎、六蛮谓之四海。", "b": "《尔雅·释地》"}, {"t": "作九夷八蛮六戎五狄、校人四海山川注:四海犹四方也。", "b": "《周礼·调人》"}], "words": [{"w": "海北", "t": "泛指僻远的北方"}, {"w": "海夷", "t": "边境少数民族或来自海外的外国人"}, {"w": "海土", "t": "海内的土地"}, {"w": "海方", "t": "犹四海。极言广远之地。"}]}, {"meaning": "在月球表面或火星表面上一种相当大的暗区。"}, {"meaning": "大口,大嘴巴。", "cites": [{"t": "面皮微白,海下无须。此人就是赛叔和李怀春。", "b": "清·郭小亭《济公全传》"}]}, {"meaning": "很多的。", "cites": [{"t": "凡地大物博得皆得谓之海。", "b": "段玉裁《说文解字注》"}], "words": [{"w": "那年闹霍乱,死的人海啦!东西海着哩,管你们酒足饭饱", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2075wx','涂','1','tú','氵','10','','[{"pinyin": "tú", "defs": [{"meaning": "(形声。从水,余声。本义:涂水)。"}, {"meaning": "同本义。"}, {"meaning": "古水名。即今云南省之牛栏江。发源于寻甸,北流至威宁折向西北,至鲁甸县注入金沙江。", "cites": [{"t": "涂,水。出益州牧靡南山,西北入渑。", "b": "《说文》"}]}, {"meaning": "洞涡水支流。在山西省榆次县境。"}, {"meaning": "道路。也作“途”。", "cites": [{"t": "出于玉之涂。", "b": "《孟子·梁惠王上》"}, {"t": "乡也混然涂之人也。", "b": "《荀子·儒效》"}, {"t": "涂巷之人也。", "b": "《荀子·劝学》"}, {"t": "故辟门除涂,以迎吾人。", "b": "《荀子·王霸》"}], "words": [{"w": "涂次", "t": "路上;途中"}, {"w": "涂夫", "t": "路人"}, {"w": "涂巷", "t": "道路;街坊"}, {"w": "涂轨", "t": "本指车行之道。引申谓路子,途径"}, {"w": "涂数", "t": "途程"}, {"w": "涂迹", "t": "轨迹,途径"}, {"w": "涂辙", "t": "车轮的痕迹"}, {"w": "涂道", "t": "路途。"}]}, {"meaning": "十二月。古月名。", "cites": [{"t": "十二月为涂。", "b": "《尔雅》"}]}, {"meaning": "“塗”的简化字。"}, {"meaning": "泥,泥巴。", "cites": [{"t": "塗,泥也。", "b": "《广雅》"}, {"t": "见豕负涂。", "b": "《易·睽》"}, {"t": "厥土惟塗泥。", "b": "《书·禹贡》"}, {"t": "如塗塗附。", "b": "《诗·小雅·角弓》"}, {"t": "冻塗。", "b": "《礼记·夏小正》"}, {"t": "坐于塗炭。", "b": "《孟子》"}], "words": [{"w": "涂车", "t": "用泥涂制成而饰以彩色的车子。为古时送葬的明器"}, {"w": "涂炭", "t": "泥淖和炭灰。喻污浊之地。亦谓污浊。"}]}, {"meaning": "道路。", "cites": [{"t": "道听塗说。", "b": "《论语》"}, {"t": "遇诸塗。", "b": ""}, {"t": "长塗中宿。", "b": "司马相如《上林赋》"}, {"t": "天下何思何虑?天下同归而殊涂,一致而百虑。", "b": "《易·系辞下》"}, {"t": "立之涂,匠者不顾。", "b": "《庄子·逍遥游》"}, {"t": "明乎坦涂。", "b": "《庄子·秋水》"}, {"t": "七圣皆迷,无所问涂。适遇牧马童子问涂焉。", "b": "《庄子·徐无鬼》"}]}, {"meaning": "引申指途径;门路。", "cites": [{"t": "国乱者,民多私义;兵弱者,民多私勇。则削国之所以取爵禄者多涂,亡国之所以贱爵轻禄。", "b": "《商君书》"}]}, {"meaning": "涂抹;粉刷物品。", "cites": [{"t": "涂明耳目。", "b": "《史记·货殖列传》"}], "words": [{"w": "涂白", "t": "在树干上涂抹白涂剂"}, {"w": "涂附", "t": "在污泥上再涂上污泥。比喻以恶附恶"}, {"w": "涂地", "t": "涂抹、漫布于地"}, {"w": "涂墍", "t": "用泥涂抹屋顶或墙壁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2076wx','浴','1','yù','氵','10','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从水,谷(yù)声。本义:洗澡)。"}, {"meaning": "同本义。", "cites": [{"t": "浴,洒身也。", "b": "《说文》"}, {"t": "共王之沐浴。", "b": "《周礼·宫人》"}, {"t": "浴去身垢。", "b": "《论衡·讥月》"}, {"t": "浴乎沂。", "b": "《论语·先进》"}, {"t": "新浴者必振衣。", "b": "《史记·屈原贾生列传》"}, {"t": "浴于汤池。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "沐浴", "t": "洗澡;比喻受润泽"}, {"w": "浴淴", "t": "洗澡"}, {"w": "淋浴", "t": "喷水洗澡"}, {"w": "浴桶", "t": "洗澡用的大桶。"}]}, {"meaning": "鸟飞忽上忽下。", "cites": [{"t": "黑鸟浴,黑鸟者何也?乌也。浴也者,飞乍高乍下也。", "b": "《大戴礼记》"}]}, {"meaning": "沉浸;浸染。", "cites": [{"t": "久浴文化,则渐悟人类之尊严。", "b": "鲁迅《坟·文化偏至论》"}], "words": [{"w": "浴蚕", "t": "浸洗蚕子。古代育蚕选种的方法。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2077wx','浮','1','fú','氵','10','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从水,孚(fú)声。本义:漂流,漂浮)。"}, {"meaning": "同本义。", "cites": [{"t": "浮,氾也。", "b": "《说文》"}, {"t": "载沉载浮。", "b": "《诗·小雅·菁菁者莪》"}, {"t": "浮,漂也。浮游也。", "b": "《广雅》"}, {"t": "乘桴浮于海。", "b": "《论语·公冶长》"}, {"t": "浮于济漯。", "b": "《书·禹贡》"}, {"t": "过夏首而西浮兮。", "b": "《楚辞·哀郢》"}, {"t": "浮天无岸。", "b": "《文选·桦·海赋》"}, {"t": "皓月千里,浮光跃金。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "交语速装束,络绎如浮云。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "游水(如挥动手脚或摆动翅鳍或尾巴)推进身体。", "cites": [{"t": "蒙冲斗舰乃以千数,操悉浮以沿江。", "b": "《资治通鉴》"}], "words": [{"w": "浮涉", "t": "乘舟渡水"}, {"w": "浮淫", "t": "划船游乐"}, {"w": "浮舟", "t": "行船。"}]}, {"meaning": "超过。", "cites": [{"t": "罪俘于桀。", "b": "《书伪泰誓》"}, {"t": "康乃甘心鹰犬,搏噬善类,其罪又浮于高拱。", "b": "《明史·海瑞传》"}], "words": [{"w": "人浮于事;浮征", "t": "超额征收"}, {"w": "浮冒", "t": "虚报;假冒。"}]}, {"meaning": "用满杯酒罚人。", "cites": [{"t": "使苏子美读之,必浮白曰:“惜乎击之不中!”", "b": "《聊斋志异》"}], "words": [{"w": "浮白", "t": "罚酒;借指满饮。"}]}, {"meaning": "在表面上。", "cites": [{"t": "耻名之浮于行也。", "b": "《礼记·表记》"}], "words": [{"w": "浮文套语", "t": "不疼不痒的客套话"}, {"w": "浮气", "t": "非常微弱的气息。"}]}, {"meaning": "轻薄;轻佻。", "cites": [{"t": "教以乐,以疏其秽,而镇其浮。", "b": "《国语·楚语》"}, {"t": "浮浪书生亦贪利,史笥经箱为盗囊。", "b": "梅尧臣《闻进士贩茶》"}], "words": [{"w": "粗心浮气;浮逸", "t": "轻浮放荡"}, {"w": "浮浪", "t": "轻薄放荡。"}]}, {"meaning": "空虚;无根据。又空虚不实。", "cites": [{"t": "有苗时采,则虚而浮。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "浮称", "t": "虚名"}, {"w": "浮言", "t": "没有实际意义的话"}, {"w": "浮幻", "t": "不切实际的幻想"}, {"w": "浮理", "t": "捏造的理由"}, {"w": "浮文", "t": "虚华无实的文章"}, {"w": "浮词", "t": "虚饰无根据的言辞"}, {"w": "浮议", "t": "无根据、不足信的言论。"}]}, {"meaning": "疏松细碎的土。", "cites": [{"t": "壤土之次曰五浮。", "b": "《管子》"}]}, {"meaning": "(hú)。葫芦。", "cites": [{"t": "百人抗浮,不若一人挈而趋。", "b": "《淮南子》"}]}, {"meaning": "虫名。", "cites": [{"t": "浮游有殷。", "b": "《大戴礼·夏小正》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2078wx','涣','1','huàn','氵','10','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从水,奂(huàn)声。本义:流散,离散)。"}, {"meaning": "同本义。", "cites": [{"t": "涣,流散也。", "b": "《说文》"}, {"t": "方涣涣兮。", "b": "《诗·郑风·溱洧》"}, {"t": "涣者离也。", "b": "《易·序卦传》"}, {"t": "则涣然离矣。", "b": "《汉书·刑法志》"}, {"t": "涣兮。", "b": "《老子》。注:“涣者解散。”"}, {"t": "涣乎成功。", "b": "《刘熊碑》"}, {"t": "功德涣彰。", "b": "《戚伯著碑》"}], "words": [{"w": "涣然冰释", "t": "如冰之溶解消散。多用以指误会、疑难的消散"}, {"w": "涣驰", "t": "涣散。分散,不集中"}, {"w": "涣泮", "t": "消释,融化"}, {"w": "涣衍", "t": "蔓延,扩散。"}]}, {"meaning": "水很大的。", "cites": [{"t": "清音应空谷,潜波涣寒塘。", "b": "吕同老《丹泉》"}]}, {"meaning": "又泛指盛貌。", "cites": [{"t": "纂辞奋笔,涣若不思。", "b": "韩愈文"}]}, {"meaning": "鲜明的。同“焕”。", "cites": [{"t": "涣烂兮其溢目也。", "b": "《后汉书·延笃传》"}], "words": [{"w": "涣烂", "t": "光明灿烂的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2079wx','涤','1','dí','氵','10','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从水,条声。本义:洗)。"}, {"meaning": "同本义。", "cites": [{"t": "涤,洒也。", "b": "《说文》"}, {"t": "射人宿视涤。", "b": "《仪礼·大射仪》"}, {"t": "水曰清涤。", "b": "《礼记·曲礼》"}, {"t": "及执事,视涤濯。", "b": "《周礼·太宰》"}], "words": [{"w": "涤篆", "t": "洗印。用以检查印是否有缺陷"}, {"w": "涤濯", "t": "洗涤"}, {"w": "涤耳", "t": "洗耳。"}]}, {"meaning": "除,清除。", "cites": [{"t": "进明德而崇业,涤饕餮之贪欲。", "b": "张衡《东京赋》"}], "words": [{"w": "涤瑕", "t": "洗除瑕疵。有改过迁善之意"}, {"w": "涤地无类", "t": "荡涤无遗。形容清除得彻底。"}]}, {"meaning": "打扫。", "cites": [{"t": "十月涤场。", "b": "《诗·豳风·七月》"}], "words": [{"w": "涤场", "t": "打扫场地。"}]}, {"meaning": "涤宫,古代宫中饲养祭祀牲畜的房子。", "cites": [{"t": "古者帝牛必在涤三月,以致严洁。", "b": "《续资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2080wx','流','1','liú','氵','10','','[{"pinyin": "liú", "defs": [{"meaning": "(会意。本义:水流动)。"}, {"meaning": "同本义。", "cites": [{"t": "观其流泉。", "b": "《诗·大雅·公刘》"}, {"t": "顄淡滂流。", "b": "《文选·马融·长笛赋》"}, {"t": "血流殷地。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "黄河流水。", "b": "《乐府诗集·林兰诗》"}, {"t": "碧水东流自此回。", "b": "唐·李白《望天门山》"}, {"t": "桃花流水鳜鱼肥。", "b": "唐·张志和《渔歌子》"}]}, {"meaning": "顺水漂流。", "cites": [{"t": "譬彼舟流,不知所届。", "b": "《诗·小雅·小弁》"}], "words": [{"w": "流觞", "t": "在环曲水道;旁宴聚时,将杯放入水中,任其漂流,如停在某人面前,某人当即取饮"}, {"w": "流柿", "t": "江中漂流的木片"}, {"w": "流泊", "t": "在水面漂流"}, {"w": "流花", "t": "水面漂流的落花。"}]}, {"meaning": "漂没;移动不定;流浪。", "cites": [{"t": "君子和而流。", "b": "《礼记》"}], "words": [{"w": "流穴", "t": "辖转流落,居无定所"}, {"w": "流沔", "t": "流连沉溺。"}]}, {"meaning": "传布;扩散。", "cites": [{"t": "其故家贵俗,流风善政,犹有存者。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "流风", "t": "遗风"}, {"w": "流称", "t": "传颂"}, {"w": "流闻", "t": "辗转传闻;流播"}, {"w": "流迈", "t": "传播远方"}, {"w": "流声", "t": "流播名声,流传的名声"}, {"w": "流誉", "t": "传播声誉"}, {"w": "流语", "t": "流传的话。"}]}, {"meaning": "放逐,流放,古代五刑之一。", "cites": [{"t": "虽放流。", "b": "《史记·屈原贾生列传》"}, {"t": "流于彘。(彘,晋地,在现在山西省霍县。周厉王后来被流放到彘。)", "b": "《国语·召公谏厉王止谤》"}], "words": [{"w": "流递", "t": "将犯人送到远处管制"}, {"w": "流户", "t": "流放边区服劳役的人家"}, {"w": "流逐", "t": "流放"}, {"w": "流囚", "t": "被流放的囚徒。"}]}, {"meaning": "停留,停止。", "cites": [{"t": "旁行而不流。", "b": "《易·系辞上》"}]}, {"meaning": "求取。", "cites": [{"t": "参差荇菜,左右流之。", "b": "《诗·周南·关雎》"}]}, {"meaning": "河川;江河的流水。", "cites": [{"t": "顺流而东行,至于北海。", "b": "《庄子》"}, {"t": "通流入海。", "b": "清·张廷玉《明史》"}, {"t": "不积小流。", "b": "《荀子·劝学》"}, {"t": "临清流。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "从流飘荡。", "b": "吴均《与朱元思书》"}], "words": [{"w": "流川", "t": "江河的流水"}, {"w": "流温", "t": "谓流水温和"}, {"w": "流涧", "t": "山间的流水。"}]}, {"meaning": "流派;派别。", "cites": [{"t": "道家者流,盖出于史官。", "b": "《汉书·艺文志》"}]}, {"meaning": "品类;等级。", "cites": [{"t": "滑稽之流。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "三教九流;流亚", "t": "同一类人物"}, {"w": "流比", "t": "同类比照类推"}, {"w": "流伍", "t": "同辈;同类"}, {"w": "流序", "t": "流品,等级。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2081wx','润','1','rùn','氵','10','','[{"pinyin": "rùn", "defs": [{"meaning": "(形声。从水, 闰(rùn)声。本义:雨水下流,滋润万物)。"}, {"meaning": "同本义。", "cites": [{"t": "润,水曰润下。", "b": "《说文》"}, {"t": "润,渍也。", "b": "《广雅》"}, {"t": "润之以风雨。", "b": "《易·系辞》"}, {"t": "雨润万物。", "b": "《论衡·雷虚》"}, {"t": "温润而泽。", "b": "《礼记·聘义》"}, {"t": "随风潜入夜,润物细无声。", "b": "唐·杜甫《春夜喜雨》"}], "words": [{"w": "润一润喉咙;润下", "t": "雨水下以滋润万物"}, {"w": "润雨", "t": "受雨水滋润"}, {"w": "润改", "t": "滋润涵养"}, {"w": "润滋", "t": "滋润。"}]}, {"meaning": "修饰,使有光彩。", "cites": [{"t": "润,饰也。", "b": "《广雅》"}, {"t": "必待明圣润色。", "b": "《汉书·终军传》"}], "words": [{"w": "润屋", "t": "装饰房屋"}, {"w": "润正", "t": "润色纠正"}, {"w": "润笔之绢", "t": "为人作诗文书画所得的报酬"}, {"w": "润改", "t": "润色修改。"}]}, {"meaning": "使得到好处,扶助。", "cites": [{"t": "泽加百姓,功润诸侯。", "b": "《汉书》"}]}, {"meaning": "潮湿。", "cites": [{"t": "衣润费垆烟。", "b": "宋·周邦彦《满庭芳·风老莺雏》"}], "words": [{"w": "润肺爽口", "t": "痛快;酣畅"}, {"w": "润浸", "t": "浸湿;浸透"}, {"w": "润溽", "t": "湿润"}, {"w": "润滋滋", "t": "润湿的样子。"}]}, {"meaning": "细腻光滑。", "cites": [{"t": "嵌岩窦穴,怪奇万状,色泽莹润,亦与它石迥异。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "润气", "t": "光泽"}, {"w": "润腻", "t": "光滑细腻;润泽细腻。"}]}, {"meaning": "润水 。淮河支流。在今安徽省西北部。发源于临泉县,东南流至润河集入淮,今称润河。"}, {"meaning": "古州名。"}, {"meaning": "隋置。治所在今江苏省镇江市。"}, {"meaning": "辽置。治海阳,故城在今秦皇岛市西北部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2082wx','涧','1','jiàn','氵','10','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从水,间声。本义:夹在两山间的水沟)。"}, {"meaning": "同本义。", "cites": [{"t": "涧,山夹水也。", "b": "《说文》"}, {"t": "于涧之中。", "b": "《诗·召南·采蘩》"}, {"t": "时鸣春涧中。", "b": "唐·王维《鸟鸣涧》"}, {"t": "陕西大涧。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "溪涧。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "涧谷", "t": "溪涧山谷"}, {"w": "涧籁", "t": "山涧的水声。"}]}, {"meaning": "古代数词。万万沟为涧,即1064。"}, {"meaning": "水名。", "cites": [{"t": "一曰涧水,出宏农西安东南入洛。", "b": "《说文》"}]}, {"meaning": "源出河南渑池县东北,东南流会渑水,东流经新安县南,到洛阳市西折,东南入洛河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2083wx','涕','1','tì','氵','10','','[{"pinyin": "tì", "defs": [{"meaning": "(形声。从水,弟声。先秦时期,“涕”指眼泪,后来出现了“泪”,两字就同义并用了。本义:眼泪)。"}, {"meaning": "同本义。", "cites": [{"t": "涕,泣也。", "b": "《说文》。段注:“泣也二字当作目液也三字。转写之误也。毛传皆云:“自目出曰涕。”"}, {"t": "悲愁垂涕。", "b": "《列子·汤问》"}, {"t": "涕流离而从横。", "b": "司马相如《长门赋》"}, {"t": "涕零如雨。", "b": "《诗·小雅·小明》"}, {"t": "长太息以掩涕兮,哀民生之多艰。", "b": "《楚辞·离骚》"}, {"t": "临表涕零。", "b": "诸葛亮《出师表》"}, {"t": "汪然出涕。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "涕泪满衣裳。", "b": "唐·杜甫《闻官军收河南河北》"}, {"t": "德威流涕。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "涕泗", "t": "眼泪和鼻涕"}, {"w": "痛哭流涕", "t": ""}]}, {"meaning": "鼻涕。", "cites": [{"t": "目泪下落,鼻涕长一尺。", "b": "王褒《僮约》"}, {"t": "攀柏悲号,涕泪著树,树皆枯。", "b": "《晋书·王褒传》"}], "words": [{"w": "涕唾", "t": "鼻涕和唾液"}, {"w": "涕泪", "t": "鼻涕和眼泪。亦专指眼泪。"}]}, {"meaning": "痰。", "cites": [{"t": "肺中寒,吐浊涕。", "b": "《金匮要略》"}]}, {"meaning": "流泪;哭泣。", "cites": [{"t": "涕,涕流貌。", "b": "《说文》"}, {"t": "不敢唾涕。", "b": "《礼记·内则》"}, {"t": "父母唾涕不见。", "b": ""}, {"t": "因笑王、谢诸人,登高怀远,也学英雄涕。", "b": "陈高《念奴娇》"}], "words": [{"w": "涕欷", "t": "流泪叹息"}, {"w": "涕淫淫", "t": "泪流不止的样子"}, {"w": "涕洟", "t": "涕泪俱下;哭泣"}, {"w": "涕血", "t": "泣血"}, {"w": "涕泗滂沱(沲)(涕泪如雨", "t": ""}, {"w": "涕涟", "t": "泪流不断的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2084wx','浪','1','làng','氵','10','','[{"pinyin": "làng", "defs": [{"meaning": "波浪,水因风吹、石激而形成的涌动。", "cites": [{"t": "风起浪涌。", "b": "《世说新语·雅量》"}, {"t": "长风破浪会有时,直挂云帆济沧海。", "b": "李白《行路难》"}, {"t": "温泉毖涌而自浪。", "b": "左思《魏都赋》"}], "words": [{"w": "风浪", "t": "水面上的风和波浪"}, {"w": "激浪", "t": "汹涌急剧的波浪"}, {"w": "浪波", "t": "浪头。波浪"}, {"w": "浪淘淘", "t": "波浪翻滚的样子。"}]}, {"meaning": "放荡;放纵。", "cites": [{"t": "谑浪笑敖。", "b": "《诗·邶风·终风》"}], "words": [{"w": "浪弟子", "t": "称行为放荡、不知检束的青年人"}, {"w": "浪事", "t": "不好的事;令人生厌的事"}, {"w": "浪荡鬼", "t": "对放荡不检的人的鄙称。"}]}, {"meaning": "言词不干净;随口说脏话。", "cites": [{"t": "小岭这个令,浪得很!好好的说一个飞觞解秽罢。", "b": "清·魏子安《花月痕》"}]}, {"meaning": "无用。", "cites": [{"t": "你这个不知死活的东西!这府里希罕你的那扔不了的浪东西!", "b": "《红楼梦》"}]}, {"meaning": "破烂。", "cites": [{"t": "这府里希罕你的那朽不了的浪东西?", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2085wx','浸','1','jìn','氵','10','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从水,籀文寝声。本义:古水名。浸水) 同本义。", "cites": [{"t": "浸,浸水也。出魏郡武安东北,入呼沱水。", "b": "《说文》。朱骏声按,出今河南彰德府武安县,入虖沱河。"}], "words": [{"w": "巨浸", "t": "大湖。"}]}, {"meaning": "泡在水里,被水渗入。", "cites": [{"t": "冽彼下泉,浸彼苞稂。", "b": "《诗·曹风·下泉》"}, {"t": "其浸五湖。", "b": "《周礼·职方氏》"}, {"t": "浸渊之草。", "b": "《吕氏春秋·木味》"}], "words": [{"w": "浸淬", "t": "把金属工件烧红,然后浸入水中急速冷却,以增加其硬度或改变其物理、化学性能"}, {"w": "浸蚀", "t": "因液体浸泡而腐蚀或损伤"}, {"w": "浸濡", "t": "因受水渍而湿透。"}]}, {"meaning": "灌溉。", "cites": [{"t": "一日浸百畦。", "b": "《庄子·天地》"}], "words": [{"w": "浸溉", "t": "灌溉"}, {"w": "浸水", "t": "用水灌溉,泡水,置于水中。"}]}, {"meaning": "渗入;渗透。", "cites": [{"t": "浸润之谮。", "b": "《论语·颜渊》。皇疏:“浸渊,犹渐渍也。”"}, {"t": "上漏下湿,润浸北房。", "b": "《淮南子·原道》"}], "words": [{"w": "浸浸", "t": "汗、水等渗出貌。"}]}, {"meaning": "淹没。", "cites": [{"t": "别时茫茫江浸月。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "浸包", "t": "包容"}, {"w": "浸害", "t": "指涝灾"}, {"w": "浸漫", "t": "犹弥漫,多指水;涨溢"}, {"w": "浸荡", "t": "侵蚀冲荡。"}]}, {"meaning": "滋润。喻施恩惠。", "cites": [{"t": "泽浸昆虫。", "b": "张衡《东京赋》。注:“润也。”"}], "words": [{"w": "浸潭", "t": "浸润广衍"}, {"w": "浸育", "t": "浸毓。滋润养育"}, {"w": "浸漉", "t": "浸润。喻恩泽下施"}, {"w": "浸泽", "t": "润泽。喻普施恩译。"}]}, {"meaning": "仔细看。", "cites": [{"t": "乃始揽物引类,览取挢掇,浸想宵类…引人之意,系之无极。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2086wx','涨','1','zhǎng zhàng','氵','10','','[{"pinyin": "zhǎng", "defs": [{"meaning": "(形声。从水,张声。本义:水上升)。"}, {"meaning": "同本义。", "cites": [{"t": "江涨柴门外,儿童报急流。", "b": "唐·杜甫《江涨》"}, {"t": "冰入春风涨御沟,上林花气欲飞浮。", "b": "宋·王安石《祥云》"}, {"t": "渭流涨腻,弃脂水也。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "涨滩", "t": "由于河水上涨,泥沙堆积成可供耕植的陆地"}, {"w": "涨痕", "t": "涨水的痕迹"}, {"w": "涨溢", "t": "水流上涨泛滥。"}]}, {"meaning": "增长;高出。", "cites": [{"t": "涨少霾草树。(霾:埋。)", "b": "杜甫《缆船苦风戏题》"}], "words": [{"w": "高涨;价格涨落;涨级", "t": "提高工资级别。"}]}, {"meaning": "大水貌。", "cites": [{"t": "涨,大水。", "b": "《广韵》"}, {"t": "跻江津而起涨。", "b": "《文选·郭璞·江赋》。注:“涨,水大之貌。”"}, {"t": "云霞肃山涨。", "b": "江淹《望荆山诗》"}, {"t": "君不见野涨连天浸茅屋,十家五家相向哭!", "b": "王撰《中秋山塘曲》"}]}, {"meaning": "盛,茂盛。", "cites": [{"t": "梅残数点雪,麦涨一川云。", "b": "《西游记》"}]}]}, {"pinyin": "zhàng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2087wx','烫','1','tàng','火','10','','[{"pinyin": "tàng", "defs": [{"meaning": "(本作汤)。"}, {"meaning": "以热水温物。", "cites": [{"t": "叫浑家把肠子煮了,烫起酒来。", "b": "《儒林外史》"}], "words": [{"w": "烫酒", "t": "用热水暖酒。也称暖酒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2088wx','涩','1','sè','氵','10','','[{"pinyin": "sè", "defs": [{"meaning": "(形声。从水,歰声。声符(歰sè)为本字,象四只脚两两相抵,表示不滑,是会意字。本义:不滑溜)。"}, {"meaning": "同本义。", "cites": [{"t": "濇,不滑也。", "b": "《说文》"}, {"t": "短而濇。", "b": "《素问·至真要大论》"}, {"t": "濇,文歰,今作澀,不滑也。", "b": "《一切经音义》"}, {"t": "始余有佩刀甚良,至是涩不可拔。", "b": "刘禹锡《砥石赋·序》"}], "words": [{"w": "涩噎", "t": "因不滑润而梗噎"}, {"w": "涩道", "t": "刻有花纹的倾斜石砌"}, {"w": "涩巴巴", "t": "形容不滑润"}, {"w": "涩浪", "t": "古代宫墙基垒石凹入,作文纹状"}, {"w": "涩脉", "t": "脉动往来不流利,虚细而迟。"}]}, {"meaning": "味不甘滑。", "cites": [{"t": "酸涩如棠梨。", "b": "杜甫《病桔》"}], "words": [{"w": "涩苦", "t": "又涩又苦"}, {"w": "涩赤", "t": "干涩发红"}, {"w": "涩重", "t": "干涩沉重。"}]}, {"meaning": "说话、写文章迟钝艰难、生硬、不流畅。", "cites": [{"t": "生而舌短,涩于言论。", "b": "《宋书·南郡王(刘)义宣传》"}], "words": [{"w": "生涩", "t": "言词、文字等不流畅"}, {"w": "文句艰涩;涩笔", "t": "看似拟古不流利,实则庄茂而沉着有力的笔法"}, {"w": "涩僻", "t": "文词生涩冷僻"}, {"w": "涩辞", "t": "言语迟钝"}, {"w": "涩体", "t": "艰涩难读、自成一格的文章体式。"}]}, {"meaning": "道路险阻;不通畅的。", "cites": [{"t": "冰泉冷涩弦凝绝,凝绝不通声暂歇。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "涩难", "t": "险阻"}, {"w": "涩道", "t": "无级次的石砌陡斜小路"}, {"w": "涩滞", "t": "险阻;不通畅。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2089wx','涌','1','chōng yǒng','氵','10','','[{"pinyin": "chōng", "defs": [{"meaning": "多用于地名。"}]}, {"pinyin": "yǒng", "defs": [{"meaning": "(形声。从水,甬(yǒng)声。本义:水向上冒)。"}, {"meaning": "同本义。", "cites": [{"t": "涌,滕也。", "b": "《说文》"}, {"t": "涌,出也。", "b": "《广雅》"}, {"t": "滥泉正出。正出,涌出也。", "b": "《尔雅·释水》"}, {"t": "泉暴出者曰涌。", "b": "《论衡·状留》"}, {"t": "醴泉涌于清室,通川过于中庭。", "b": "汉·司马相如《上林赋》"}, {"t": "泉暴出者曰涌。", "b": "汉·王充《论衡》"}], "words": [{"w": "涌沸", "t": "喷涌出沸腾的水"}, {"w": "涌泉", "t": "水向上喷出的泉。"}]}, {"meaning": "引申指云、雾、烟、气等上腾冒出。", "cites": [{"t": "洪波涌起。", "b": "《乐府诗集·曹操·步出夏门行》"}, {"t": "云烟沸涌。", "b": "唐·李朝威《柳毅传》"}, {"t": "亦浪涌。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "风云腾涌。", "b": ""}]}, {"meaning": "水奔涌,翻腾。", "cites": [{"t": "江间波浪兼天涌,塞上风云接地阴。", "b": "唐·杜甫《秋兴》"}], "words": [{"w": "涌溜", "t": "汹涌的水流"}, {"w": "涌溜溜", "t": "形容翻卷飘动"}, {"w": "涌湍", "t": "激流;奔流"}, {"w": "涌裔", "t": "水波腾涌貌"}, {"w": "涌激", "t": "汹涌激荡"}, {"w": "涌沸", "t": "翻腾"}, {"w": "排排巨浪向岸边涌来", "t": ""}]}, {"meaning": "“湧”另见yǒng。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2090wx','悖','1','bèi','忄','10','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从心,孛(bèi)声。本义:违反,违背)。"}, {"meaning": "同本义。", "cites": [{"t": "悖其所辞。", "b": "《荀子·正名》。注:“违也。”"}, {"t": "毋悖于时。", "b": "《礼记·月令》。注:“犹逆也。”"}, {"t": "故新相反,前后相悖。", "b": "《韩非子·定法》"}], "words": [{"w": "悖言", "t": "违逆之言"}, {"w": "悖暴", "t": "背理凶暴"}, {"w": "并行不悖", "t": ""}]}, {"meaning": "掩蔽。", "cites": [{"t": "上悖日月之明。", "b": "《庄子·胠箧》。司马注:“悖,薄食也。”"}, {"t": "山野悖其心迹,烟雾养其神爽。", "b": "《上刘右相书》"}]}, {"meaning": "叛乱。", "cites": [{"t": "周成王,管、蔡悖乱,周公东征。", "b": "《论衡·恢国篇》"}, {"t": "殄熄暴悖,乱贼灭亡。", "b": "《史记》"}]}, {"meaning": "惑乱;糊涂。", "cites": [{"t": "足以喻治之所悖。", "b": "《荀子·正名》。注:“惑也。”"}, {"t": "先生老悖乎?", "b": "《战国策·楚策》"}], "words": [{"w": "悖惘", "t": "昏聩了"}, {"w": "悖耄", "t": "老朽昏庸。"}]}, {"meaning": "荒谬;谬误。", "cites": [{"t": "计有一二者难悖也。", "b": "《战国策·秦策》。注:“误也。”"}, {"t": "疏达而不悖。", "b": "《淮南子·原道》。注:“谬也。”"}, {"t": "以此任物,亦必悖矣。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "悖妄", "t": "荒谬狂妄。"}]}, {"meaning": "背谬,行不通。", "cites": [{"t": "守法而弗变则悖。", "b": "《吕氏春秋·察今》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2091wx','悟','1','wù','忄','10','','[{"pinyin": "wù", "defs": [{"meaning": "(形声,从心,吾声。本义:理解,明白)。"}, {"meaning": "同本义。", "cites": [{"t": "悟,觉也。", "b": "《说文》"}, {"t": "悟彼蟋蟀唱。", "b": "《文选·谢混游西池诗》"}, {"t": "慧然独悟。", "b": "《素问·八正神明论》"}, {"t": "未悟见出,意不自得。", "b": "《后汉书·张酺传》"}, {"t": "悟已往之不谏。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "闻而悟之。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "悟前狼假寐。", "b": "《聊斋志异·狼三则》"}, {"t": "悟大光明法。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "觉悟", "t": "由迷惑而明白;由模糊而认清"}, {"w": "悟心", "t": "悟性。对事物理解和分析的能力"}, {"w": "悟宗", "t": "明了、会通佛理之宗旨"}, {"w": "悟悦", "t": "因了悟而喜悦"}, {"w": "悟理", "t": "领会道理"}, {"w": "悟物", "t": "了悟物理"}, {"w": "悟明", "t": "了悟真言"}, {"w": "悟佛", "t": "了悟佛理"}, {"w": "悟禅", "t": "参悟禅理"}, {"w": "悟道参玄", "t": "宗教语。领会和推究宗教中玄妙之理。"}]}, {"meaning": "觉醒;觉悟", "cites": [{"t": "行事,适有卧厌不悟者,谓此为天所厌邪?", "b": "王充《论衡·问孔》"}, {"t": "凄凄节序高,寥寥心悟永。", "b": "江淹《杂体诗》"}, {"t": "怛惊悟兮无闻。", "b": "《文选·潘岳·寡妇赋》"}], "words": [{"w": "悟觉", "t": "觉悟"}, {"w": "悟门", "t": "觉悟的门径。"}]}, {"meaning": "启发;使觉悟。", "cites": [{"t": "冀悟迷惑之心。", "b": "《论衡·对作》"}], "words": [{"w": "悟主", "t": "使主上觉悟"}, {"w": "悟发", "t": "启发。"}]}, {"meaning": "相对。", "cites": [{"t": "过耳悟目之交。", "b": "《潜夫论·明忠》"}, {"t": "悟言不如罢,从夕至清朝。", "b": "《文选·谢惠连·泛湖归出楼中玩月》"}], "words": [{"w": "悟对", "t": "聚会。"}]}, {"meaning": "抵触。", "cites": [{"t": "大意无所拂悟,…。", "b": "《韩非子》"}, {"t": "国无刑罚,则百姓之悟相侵也立见。", "b": "《吕氏春秋·荡兵》"}, {"t": "人不敢悟视。", "b": "《战国策·燕策三》"}, {"t": "大忠无所拂悟,辞言无所击排。", "b": "《史记·老子韩非列传》"}, {"t": "今人卒得鬼刺痱悟,杀雄鸡以傅其心上。", "b": "《风俗通议·雄鸡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2092wx','悄','1','qiǎo','忄','10','','[{"pinyin": "qiǎo", "defs": [{"meaning": "(形声。从心,肖声。本义:忧愁的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "悄,忧也。", "b": "《说文》"}, {"t": "忧心悄悄。", "b": "《诗·邶风·柏舟》"}, {"t": "劳心悄兮。", "b": "《诗·陈风·月出》"}, {"t": "诀后悄切。", "b": "《文选·潘岳·笙赋》"}], "words": [{"w": "悄切", "t": "形容声音忧愁凄切"}, {"w": "悄怆", "t": "哀伤,忧伤"}, {"w": "悄悄", "t": "忧愁的样子"}, {"w": "悄悒", "t": "因思念而忧郁"}, {"w": "悄戚", "t": "悲痛忧伤。"}]}, {"meaning": "寂静无声。", "cites": [{"t": "东船西舫悄无言,唯见江心秋月白。", "b": "白居易《琵琶行》"}, {"t": "悄怆幽邃。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "悄默声儿", "t": "不声不响"}, {"w": "悄促促", "t": "静悄悄"}, {"w": "悄悄", "t": "寂静的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2093wx','悍','1','hàn','忄','10','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从手,旱声。本义:勇猛)。"}, {"meaning": "同本义。", "cites": [{"t": "悍,勇也。", "b": "《说文》"}, {"t": "悍戇好斗。", "b": "《荀子·大略》"}, {"t": "虽有悍如冯敬者。", "b": "《汉书·贾谊传》"}, {"t": "且其人剽悍。", "b": "《汉书·陈汤传》"}, {"t": "上患吴会稽轻悍。", "b": "《汉书·吴王濞传》"}], "words": [{"w": "悍酋", "t": "勇猛的首领"}, {"w": "悍夫", "t": "勇士"}, {"w": "悍志", "t": "勇猛之气"}, {"w": "悍壮", "t": "勇武强壮。"}]}, {"meaning": "凶狠,蛮横。", "cites": [{"t": "悍吏之来吾乡。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "悍鸷", "t": "凶暴、蛮横的性情"}, {"w": "悍吏", "t": "凶暴蛮横的官吏"}, {"w": "悍妻", "t": "凶悍的妻子"}, {"w": "悍戾", "t": "凶横怪戾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2094wx','悔','1','huǐ','忄','10','','[{"pinyin": "huǐ", "defs": [{"meaning": "(形声。从心,每声。本义:悔恨,懊悔) 同本义。", "cites": [{"t": "悔,恨也。", "b": "《说文》"}, {"t": "宜无悔怒。", "b": "《诗·大雅·云汉》"}, {"t": "此讲之悔也。", "b": "《战国策·秦策》"}, {"t": "悔不杀汤于夏台。", "b": "《淮南子·泛论》"}, {"t": "虽九死其犹未悔。", "b": "《楚辞·离骚》"}, {"t": "怀王悔,追张仪,不及。", "b": "《史记·屈原列传》"}, {"t": "天其以礼悔祸于许。", "b": "《左传·隐公十一年》"}, {"t": "可悔故也。", "b": "宋·王安石《答司马谏议书》"}, {"t": "悔其随之。", "b": "宋·王安石《游褒禅山记》"}, {"t": "己为有悔。", "b": ""}, {"t": "可以无悔矣。", "b": ""}], "words": [{"w": "悔亲", "t": "因反悔而废弃婚约"}, {"w": "悔谢", "t": "悔过请罪"}, {"w": "悔心革命", "t": "痛改前非"}, {"w": "悔悟心行", "t": "反省思想、行为"}, {"w": "悔尤", "t": "悔恨与过错。"}]}, {"meaning": "过失;灾祸。", "cites": [{"t": "庶无罪悔。", "b": "《诗·大雅·抑》"}, {"t": "悔吝者言乎其小疵也。", "b": "《易·系辞》"}, {"t": "尚速有悔于予身。", "b": "《公羊传·襄公二十九年》"}], "words": [{"w": "悔亡", "t": "祸害消除"}, {"w": "悔吝", "t": "灾祸"}, {"w": "悔咎", "t": "过错;祸殃"}, {"w": "悔戾", "t": "罪过。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2095wx','悯','1','mǐn','忄','10','','[{"pinyin": "mǐn", "defs": [{"meaning": "(形声。从心,闵(mǐn)声。本义:怜恤) 同本义。", "cites": [{"t": "隋堤柳,悯亡国也。", "b": "白居易《新乐府序》"}, {"t": "人远悲天悯人之怀,岂为一己之不遇乎?", "b": "清·黄宗羲《朱人远墓志铭》"}], "words": [{"w": "悯人之凶", "t": "原谅、可怜凶恶之人。形容看透世情,慈悲为怀,无所计较"}, {"w": "悯念", "t": "怜悯"}, {"w": "悯宥", "t": "怜悯宽宥"}, {"w": "悯笑", "t": "怜悯讪笑;可怜亦复可笑"}, {"w": "悯贫", "t": "怜恤贫苦的人"}, {"w": "悯然", "t": "哀怜的样子。"}]}, {"meaning": "忧愁;烦闷。", "cites": [{"t": "阨穷而不悯。", "b": "《孟子》"}, {"t": "曲罢悯然。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "悯默", "t": "因忧伤而沉默"}, {"w": "悯悯", "t": "忧伤的样子"}, {"w": "悯愧", "t": "忧伤怀惭"}, {"w": "悯叹", "t": "忧伤叹息"}, {"w": "悯时病俗", "t": "忧虑时俗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2096wx','悦','1','yuè','忄','10','','[{"pinyin": "yuè", "defs": [{"meaning": "(形声。从心,说省声。本作“说”。本义:高兴,愉快) 同本义。", "cites": [{"t": "悦,犹说也,拭也,解脱也。若人心有郁结能解释之也。", "b": "《说文系传统论》"}]}, {"meaning": "“说”、“悦”古今字。", "cites": [{"t": "客见太子有悦色也。", "b": "枚乘《七发》"}, {"t": "怒可以复喜,愠可以复悦。", "b": "《孙子》"}, {"t": "桓侯又不悦。", "b": "《韩非子·喻老》"}, {"t": "张飞等不悦。", "b": "《三国志·诸葛亮传》"}, {"t": "权大悦。", "b": "《资治通鉴》"}], "words": [{"w": "悦心", "t": "愉悦心情"}, {"w": "悦情", "t": "欢乐之情"}, {"w": "悦笑", "t": "欢乐笑谑"}, {"w": "悦喜", "t": "喜悦"}, {"w": "悦畅", "t": "和畅,欢畅"}, {"w": "悦乐", "t": "快乐"}, {"w": "悦泽", "t": "光润悦目"}, {"w": "心悦诚服", "t": ""}]}, {"meaning": "顺服,悦服,从心里佩服。", "cites": [{"t": "悦,服也。", "b": "《尔雅·释诂》。义疏:“孟子所谓“中心悦而诚服”是也。”"}, {"t": "理义之悦我心,犹刍豢之悦我口。", "b": "《孟子·告子上》"}], "words": [{"w": "悦仁服德", "t": ""}]}, {"meaning": "喜,喜欢。", "cites": [{"t": "士为知己者用,女为悦己者容。", "b": "司马迁《报任少卿书》"}, {"t": "悦亲戚之情话。", "b": "晋·陶渊明《归去来兮辞》"}]}, {"meaning": "又如;悦义(爱慕道义);悦慕(爱慕敬慕)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2097wx','害','1','hài hé','宀','10','','[{"pinyin": "hài", "defs": [{"meaning": "(会意。从宀(mián),从口,丰(gài)声。从“宀”、从“口”,意思是言从家起,而“言”又往往是危害的根源。本义:伤害,损害)。"}, {"meaning": "同本义。", "cites": [{"t": "害,伤也。", "b": "《说文》"}, {"t": "害所得而恶也。", "b": "《墨子·经上》"}, {"t": "斗怒害也。", "b": "《荀子·臣道》"}, {"t": "害者,利之反也。", "b": "《韩非子·六反》"}, {"t": "周知其利害。", "b": "《周礼·职方式》"}, {"t": "志士仁人,无求生以害仁,有杀身以成仁。", "b": "《论语·卫灵公》"}, {"t": "邪曲之害公也。", "b": "《史记·屈原贾生列传》"}, {"t": "恐其害己。", "b": "《韩非子·五蠹》"}], "words": [{"w": "害心", "t": "害人害物的心思。即杀心"}, {"w": "害马", "t": "本指损伤马的自然本性。后凡足以损害同类或团体的人,都称为害马或害群之马"}, {"w": "害虐", "t": "伤害虐待"}, {"w": "害身", "t": "伤害身体。"}]}, {"meaning": "妨碍,妨害。", "cites": [{"t": "害,妨也。", "b": "《字汇》"}, {"t": "曰:“许子奚为不自织?”曰:“害于耕。”", "b": "《孟子·滕文公上》"}], "words": [{"w": "他设置重重障碍,这可害了我", "t": ""}]}, {"meaning": "谋杀,谋害。", "cites": [{"t": "复行扰害。", "b": "《广东军务记》"}, {"t": "医言无害。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "他在去上班的路上被害;他为仇人所害", "t": ""}]}, {"meaning": "妒忌。", "cites": [{"t": "上官大夫与之同列,争宠,而心害其能。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "招致某种后果。", "cites": [{"t": "你这负心汉,害天灾的!", "b": "关汉卿《救风尘》"}]}, {"meaning": "加祸。", "cites": [{"t": "鬼神害盈而福谦。", "b": "《易·谦彖》"}]}, {"meaning": "灾害。祸害。", "cites": [{"t": "时多疾病毒伤之害。", "b": "《淮南子·脩务》"}, {"t": "必兴天下之利,除去天下之害。", "b": "《墨子·兼爱中》"}, {"t": "有公害。", "b": "清·黄宗羲《原君》"}, {"t": "一己之害。", "b": ""}, {"t": "天下释其害。", "b": ""}], "words": [{"w": "害咎", "t": "灾祸"}, {"w": "害患", "t": "祸患"}, {"w": "害灾", "t": "灾害。"}]}, {"meaning": "险要的处所。", "cites": [{"t": "守位以仁,不恃隘害。", "b": "张衡《东京赋》"}]}]}, {"pinyin": "hé", "defs": [{"meaning": "何不。", "cites": [{"t": "王害不违卜。", "b": "《书·大诰》"}, {"t": "薄汙我私,薄澣我衣,害澣害否,归宁父母。", "b": "《诗·周南·葛覃》"}, {"t": "时日害丧,予及女偕亡。", "b": "《孟子·梁惠王上》"}, {"t": "予害敢不于祖宗安人图功所终?", "b": "《汉书·翟方进传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2098wx','宽','1','kuān','宀','10','','[{"pinyin": "kuān", "defs": [{"meaning": "(形声。从宀(mián),表示与房屋有关,苋(kuān)声。本义:房屋宽敞)。"}, {"meaning": "同本义。", "cites": [{"t": "宽,屋宽大也。", "b": "《说文》"}, {"t": "府寺宽敞。", "b": "《后汉书·刘般传》"}], "words": [{"w": "宽厂", "t": "宽敞"}, {"w": "宽空", "t": "宽畅,不阻塞"}, {"w": "宽转", "t": "宽敞有余地。"}]}, {"meaning": "广阔;面积大。与“狭”相对。", "cites": [{"t": "云水洞庭宽。", "b": "张祜《送韦整尉长沙》"}]}, {"meaning": "横的距离大。", "cites": [{"t": "阶庭宽窄才容足。", "b": "白居易《题新居寄元八》"}], "words": [{"w": "宽乡", "t": "指地广人稀之地"}, {"w": "宽平", "t": "指宽阔平坦之处"}, {"w": "宽衍", "t": "宽阔平坦。"}]}, {"meaning": "度量宽宏;宽厚。", "cites": [{"t": "宽兮绰兮。", "b": "《诗·卫风·淇奥》。传:“宽能容众。”"}, {"t": "言宽以居之。", "b": "《易·文》"}, {"t": "宽而栗。", "b": "《书·皋谟》。郑注:“谓度量宽宏。”"}, {"t": "文帝宽,不忍罚。", "b": "《汉书·吴王刘濞传》"}, {"t": "宽哉,不被于利。", "b": "《韩非子·说林下》"}, {"t": "不知将军宽之至此也。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "宽厚而爱人。", "b": "汉·贾谊《过秦论》"}, {"t": "陈明选宽厚呕煦。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "宽洪", "t": "心胸宽阔器量大"}, {"w": "宽猛相济", "t": "指施政时要宽严相辅而行"}, {"w": "宽民", "t": "待民众宽厚,不苛刻"}, {"w": "宽泽", "t": "宽仁有恩德"}, {"w": "宽绰", "t": "宽弘广大。多指器量。"}]}, {"meaning": "宽坐(多坐一会儿。留坐的敬词)宽松;松弛。紧的反义词。", "cites": [{"t": "虽褐宽博,吾不惴焉。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "宽余", "t": "肥大,宽松"}, {"w": "宽褪", "t": "过分肥大"}, {"w": "宽衫", "t": "古人穿在外面的长袍,具有普通礼服的性质。"}]}, {"meaning": "多;富裕。", "cites": [{"t": "以二人居室十间,公田一顷,宽然有余矣。", "b": "洪亮吉《治平篇》"}], "words": [{"w": "宽饮", "t": "劝酒之词。表示请人多喝些酒。"}]}, {"meaning": "放松;放宽。", "cites": [{"t": "则械系不稍宽。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "又。", "cites": [{"t": "终亦稍宽之。", "b": ""}, {"t": "衣带渐宽终不悔,为伊消得人憔悴。", "b": "宋·柳永《凤栖梧》"}], "words": [{"w": "宽制", "t": "放宽法制"}, {"w": "宽律", "t": "放宽刑律"}, {"w": "宽放", "t": "放宽"}, {"w": "宽限", "t": "宽延期限。"}]}, {"meaning": "宽免;宽恕。", "cites": [{"t": "杀人者不死而伤人者不刑,是谓惠暴而宽贼也。", "b": "《荀子·正论》"}, {"t": "遂宽其同气之罪。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "宽贳", "t": "宽恕;宽赦"}, {"w": "宽护", "t": "宽恕庇护"}, {"w": "宽减", "t": "从宽减免"}, {"w": "宽缓", "t": "宽容而不急迫。"}]}, {"meaning": "减轻。", "cites": [{"t": "宽徭役。", "b": "《盐铁论·诛秦》"}], "words": [{"w": "宽征", "t": "减轻或缓征赋税"}, {"w": "宽痛", "t": "减轻痛苦"}, {"w": "宽徭", "t": "减轻徭役。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2099wx','家','1','jiā gū jie','宀','10','','[{"pinyin": "jiā", "defs": [{"meaning": "(会意。甲骨文字形,上面是“宀”(mián),表示与室家有关,下面是“豕”,即猪。古代生产力低下,人们多在屋子里养猪,所以房子里有猪就成了人家的标志。本义:屋内,住所)。"}, {"meaning": "同本义。", "cites": [{"t": "家,居也。从宀,豭省声。", "b": "《说文》"}, {"t": "家人内也。", "b": "《易·杂卦传》"}, {"t": "上地家七人。", "b": "《周礼·小司徒》。注:“有夫有妇,然后为家。”"}, {"t": "夙夜浚明有家。", "b": "《书·皋谟》"}, {"t": "开国承家。", "b": "《易·师》"}, {"t": "室为夫妇所居,家谓一门之内。", "b": "《诗·周南·桃夭》注"}, {"t": "便要还家,设酒杀鸡作食。", "b": "陶潜《桃花源记》"}]}, {"meaning": "引申表示住宅、房屋。", "cites": [{"t": "平原君家楼临民家。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "家庭,人家。", "cites": [{"t": "数口之家,可以无饥矣。", "b": "《孟子·梁惠王上》"}, {"t": "治天下之国若治一家。", "b": "《墨子·尚同下》"}, {"t": "家半三军。", "b": "《国语·晋语》"}, {"t": "视吾家所寡有者。", "b": "《战国策·齐策四》"}, {"t": "长铗归来乎,无以为家!", "b": ""}, {"t": "家绘像祀之。", "b": "《明史》"}], "words": [{"w": "养家;持家;安家;家第", "t": "对对方家庭的敬称"}, {"w": "家数", "t": "家族;武艺招数、招式"}, {"w": "家庙", "t": "供奉祭祀祖先的祠堂"}, {"w": "家缘", "t": "家业,家产"}, {"w": "家私", "t": "家产"}, {"w": "家赀", "t": "家私财产"}, {"w": "家计", "t": "家业,家产。"}]}, {"meaning": "指夫或妻。", "cites": [{"t": "女有家,男有室,无相渎也。", "b": "《左传·桓公十八年》"}, {"t": "固乱流其鲜终兮,浞又贪夫厥家。", "b": "《楚辞·离骚》"}], "words": [{"w": "家婆", "t": "家主婆;当家婆"}, {"w": "家公", "t": "丈夫"}, {"w": "家花", "t": "喻自己的妻子"}, {"w": "家婆", "t": "妻子;主妇。"}]}, {"meaning": "大夫统治的政治区域,即卿大夫或卿大夫的采地食邑。", "cites": [{"t": "丘也闻有国有家者。", "b": "《论语·季氏》"}, {"t": "王曰:何以利吾国?大夫曰:何以利吾家?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "家甲", "t": "古时卿大夫的私人武装"}, {"w": "家主", "t": "春秋时对卿大夫的称谓"}, {"w": "家老", "t": "上古大夫家臣中的长者"}, {"w": "家臣", "t": "春秋时各国卿大夫的臣属"}, {"w": "家邦", "t": "本指家和国,亦泛指国家"}, {"w": "家国", "t": "家与国,亦指国家。"}]}, {"meaning": "娘家。", "cites": [{"t": "卿但暂还家。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "谢家来贵门。", "b": ""}, {"t": "今日还家去。", "b": ""}, {"t": "且暂还家去。", "b": ""}]}, {"meaning": "学术或艺术流派。", "cites": [{"t": "焚百家之言,以愚黔首。", "b": "贾谊《过秦论》"}], "words": [{"w": "家数", "t": "流派风格;家法传统。多用于诗、文、技艺等"}, {"w": "家言邪学", "t": "自成一家的偏见。儒家指儒家以外的学说。"}]}, {"meaning": "经营某种行业的人家或具有某种身分的人。", "cites": [{"t": "农家少闲月。", "b": "白居易《观刈麦》"}], "words": [{"w": "农家;厂家;渔家;行家;东家;庄家", "t": ""}]}, {"meaning": "掌握某种专门学识或从事某种工作、担任某种职务的人。", "cites": [{"t": "地学之家。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "政治家;艺术家;专家;科学家;社会活动家;作家", "t": ""}]}, {"meaning": "指某一集团或某一方面 。 如: 三家条约。"}, {"meaning": "家财,财产。", "cites": [{"t": "皆没其家而迁之蜀。", "b": "《史记·吕不韦列传》"}]}, {"meaning": "又如:分家;发家;家破人亡;抄家。"}, {"meaning": "朝廷。", "cites": [{"t": "争先入公家。", "b": "《吕氏春秋·贵卒》。注:“公之朝也。”"}]}, {"meaning": "又如:汉家(即汉朝);随家(即隋朝);家历(皇朝的历数)。"}, {"meaning": "都城。", "cites": [{"t": "其国家,宫室、车旗、衣服、礼仪,皆以九为节。", "b": "《周礼》。郑玄注:“国家,国之所居,谓城方也。”"}, {"t": "紫泉宫殿锁烟霞,欲取芜城作帝家。", "b": "唐·李商隐《隋宫》"}]}, {"meaning": "帝王或太子。", "cites": [{"t": "三家,三皇也。", "b": "《后汉书·马融传》注"}]}, {"meaning": "又如:家吏(皇后或太子的官属)。"}, {"meaning": "古代医书上指患某种病的人。", "cites": [{"t": "喘家,作桂枝汤,加厚朴、杏子佳。", "b": "《伤寒论》"}]}, {"meaning": "私家的,个人的 ,与“公”相对。", "cites": [{"t": "今大道既隐,天下为家。", "b": "《礼记·礼运》"}, {"t": "家祭勿忘告乃翁。", "b": "陆游《示儿》"}]}, {"meaning": "娶妻;成家。", "cites": [{"t": "及少康之未家兮,留有虞之二姚。", "b": "《楚辞·离骚》"}], "words": [{"w": "家道", "t": "成家之道。"}]}, {"meaning": "安家;定居。", "cites": [{"t": "家,居其地曰家。", "b": "《正志通》"}, {"t": "既去职,遂家于汝州。", "b": "唐·韩愈《崔评事墓志铭》"}]}, {"meaning": "稼穑。种谷曰稼,收获曰穑。", "cites": [{"t": "弊也者家也。", "b": "《管子·侈靡》"}, {"t": "陶家事亲。", "b": "《大戴礼·五帝德篇》"}]}]}, {"pinyin": "gū", "defs": [{"meaning": "", "words": [{"w": "阿家", "t": "称婆婆"}, {"w": "阿家阿翁", "t": ""}]}]}, {"pinyin": "jie", "defs": [{"meaning": "词尾。", "words": [{"w": "成年家;整天家", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2100wx','宵','1','xiāo','宀','10','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从宀(mián),肖声。从“门”表夜间昏暗。本义:夜晚)。"}, {"meaning": "同本义。", "cites": [{"t": "宵,夜也。", "b": "《说文》"}, {"t": "宵中星。", "b": "《书·尧典》"}, {"t": "禁宵行者。", "b": "《周礼·司寤氏》"}, {"t": "甘暝太宵之长。", "b": "《淮南子·精神》。注:“长夜之中也。”"}, {"t": "宵扈宵。", "b": "《尔雅·释鸟》。樊注:“夜为农驱兽者也。”"}, {"t": "昼尔于茅,宵尔索宵。", "b": "《诗·豳风·七月》"}, {"t": "晓战随金鼓,宵眠抱玉鞍。", "b": "李白《塞下曲》"}, {"t": "今宵酒醒何处。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "宵烟", "t": "指夜晚的烟雾"}, {"w": "宵宿", "t": "住宿;住宿的地方"}, {"w": "宵夕", "t": "晚上"}, {"w": "宵中", "t": "夜里,晚上"}, {"w": "宵分", "t": "半夜,深夜"}, {"w": "宵行", "t": "夜间出行"}, {"w": "宵征", "t": "宵行,夜行"}, {"w": "宵朗", "t": "夜空晴朗。"}]}, {"meaning": "前半夜。", "cites": [{"t": "禁宵行者,夜游者。", "b": "《周礼·秋官》"}]}, {"meaning": "丝织品的一种。", "cites": [{"t": "姆纅笄宵衣。", "b": "《仪礼·士昏礼》"}], "words": [{"w": "宵衣", "t": "黑色的丝服。古代妇女助祭时所穿。宵,通“绡”。"}]}, {"meaning": "假借为“小”。小。", "cites": [{"t": "宵雅肆三。", "b": "《礼记·乐记》。注:“宵之言小也。”"}, {"t": "宵人之离外刑者。", "b": "《庄子·列御寇》。注:不由明坦之途者,谓之宵人。”"}, {"t": "毋桐好逸,毋迩宵人。", "b": "《汉书·武五子传》。颜注:“无好逸游之事,迩小人也。”"}], "words": [{"w": "宵碎", "t": "小而细碎"}, {"w": "宵民", "t": "小民。普通老百姓。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2101wx','宴','1','yàn','宀','10','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从宀(mián),妟(yàn)声。“宀”表示房屋,“妟”是“安”意思,也有表意作用。本义:请人吃饭喝酒,聚会在一起喝酒吃饭 )。"}, {"meaning": "同本义。", "cites": [{"t": "宴,安也。", "b": "《说文》。按,此字当为宴飨正字,亦作醼,作讌。"}, {"t": "君子以饮食宴乐。", "b": "《易·需》。郑注:“宴,享宴也。”"}, {"t": "吉甫宴喜。", "b": "《汉书·陈汤传》引诗六月"}, {"t": "宾客大宴。", "b": "《虞初新志·秋声诗自序》"}, {"t": "太守宴。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "宴酣之乐。", "b": ""}, {"t": "添酒回灯重开宴。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "宴犒", "t": "设宴犒赏"}, {"w": "宴赏", "t": "设宴犒赏"}, {"w": "宴饯", "t": "设宴招待"}, {"w": "宴好", "t": "泛指宴饮聚会"}, {"w": "宴衍", "t": "宴饮作乐"}, {"w": "宴位", "t": "宴饮之处"}, {"w": "宴笑", "t": "宴饮欢笑"}, {"w": "宴娱", "t": "宴饮娱乐"}, {"w": "宴饫;宴歌", "t": "宴饮歌唱"}, {"w": "宴聚", "t": "宴饮聚会。"}]}, {"meaning": "进餐。", "cites": [{"t": "逾庖而宴。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "(假借为“安”。安闲,安逸)。", "cites": [{"t": "是与太子宴者也。", "b": "《汉书·贾谊传》。注:“谓安居。”"}, {"t": "乃宴斯息。", "b": "张衡《东京赋》。注:“安也。”"}, {"t": "宴安鳩毒。", "b": "《左传》。孔颖达疏:“宴安自逸,若鳩毒之药。"}], "words": [{"w": "宴坐", "t": "安坐;闲坐"}, {"w": "宴私", "t": "谓公余闲居之时"}, {"w": "宴玩", "t": "闲暇时赏玩"}, {"w": "宴服", "t": "日常闲居时穿的衣服"}, {"w": "宴居", "t": "闲居。一般指公余无事时"}, {"w": "宴宴", "t": "安闲逸乐的样子"}, {"w": "宴处", "t": "安居;闲居"}, {"w": "宴语", "t": "闲谈"}, {"w": "宴慰", "t": "闲居"}, {"w": "宴堕", "t": "闲散不整的样子"}, {"w": "宴默", "t": "安居静穆"}, {"w": "宴逸", "t": "逸乐。"}]}, {"meaning": "安定,没有战事或动乱。", "cites": [{"t": "今军旅甫罢,三边宴然。", "b": "《辽史》"}], "words": [{"w": "宴清", "t": "形容国内安定天下太平"}, {"w": "宴如", "t": "安定平静的样子"}, {"w": "宴然", "t": "安定的样子;平安貌"}, {"w": "宴适", "t": "安适"}, {"w": "宴宁", "t": "安定。"}]}, {"meaning": "喜乐;欢乐。", "cites": [{"t": "宴尔新昏。", "b": "《诗·邶风·谷风》"}, {"t": "衡父不忍数年之不宴。", "b": "《左传·成公二年》。注:“乐也。”"}, {"t": "乐宴乐。", "b": "《论语》。孔注:“宴乐沈,荒淫渎。”"}, {"t": "极宴娱心意,戚戚何所迫!", "b": "《古诗十九首》"}]}, {"meaning": "内室。", "cites": [{"t": "君子以响晦入宴息。", "b": "《易·随》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2102wx','宾','1','bīn','宀','10','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从贝,冥(mián)声。甲骨文字形,会意。上面象屋形,下面是“人”和“止”。表示客人来到屋下,即宾客到门。金文将“止”改为“贝”,小篆从之。王国维说:“金文及小篆易从止为从贝者,乃后起之字。”本义:地位尊贵、受人尊敬的客人,贵客)。"}, {"meaning": "同本义。", "cites": [{"t": "賓,所敬也。", "b": "《说文》。按,从貝者,宾礼必有贽。"}, {"t": "宾者,接人以义者也。", "b": "《礼记·乡饮酒义》"}, {"t": "谋宾介。", "b": "《仪礼·乡饮礼》。注:“贤者为宾,其次为介,又其次为众宾。”"}, {"t": "诸侯、诸伯、诸子、诸男之相为宾也。诸公之臣相为国客,是散文宾客通称,对称则宾尊而客卑,宾大而客小。", "b": "《周礼·司仪》"}, {"t": "我有嘉宾,鼓瑟吹笙。", "b": "《诗·小雅·鹿鸣》"}, {"t": "宾出,主人拜送。", "b": "《荀子·礼论》"}, {"t": "相待如宾。", "b": "《左传·僖公三十三年》"}, {"t": "众宾团坐。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "古州名 。汉郁林郡地。唐贞观五年置宾州,亦曰安城郡。至德二年改为领方郡。元初为宾州路,寻复为宾州。清属广西思恩府。今为宾阳县。"}, {"meaning": "接引客人。用宾客的礼节相待。礼敬。", "cites": [{"t": "宾于四门。", "b": "《书·舜典》。郑注:“宾,槟也。”"}, {"t": "寅宾出日,平秩东作。", "b": "《书·尧典》"}, {"t": "协其礼,宾而见之。", "b": "《周礼·大行之》"}, {"t": "宾者以告列子。", "b": "《列子·黄帝》"}, {"t": "内史宾侯,北向而立。", "b": "《穆天子传六》。注:“宾侯,傧相。”"}, {"t": "稍稍宾客其父。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "宾天", "t": "旧指帝王死亡,后亦泛指尊者亡故"}, {"w": "宾兴", "t": "宾贡。周代的选举法,自乡小学举拔贤能,以宾礼相对待,以升于国学;指乡试。"}]}, {"meaning": "服从,归服。", "cites": [{"t": "诸侯咸来宾从。", "b": "《史记·五帝本记》"}], "words": [{"w": "宾从", "t": "归顺,服从"}, {"w": "宾服", "t": "臣服;服帖。"}]}, {"meaning": "排斥;弃绝。", "cites": [{"t": "先生居山林,食芋栗,厌葱韭,以宾寡人,久矣夫!", "b": "《庄子·徐无鬼》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2103wx','窍','1','qiào','穴','10','','[{"pinyin": "qiào", "defs": [{"meaning": "(形声。从穴,巧声。本义:孔,洞)。"}, {"meaning": "同本义。", "cites": [{"t": "空中而多窍。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "窍穴", "t": "洞穴;窟窿"}, {"w": "窍隙", "t": "孔洞;缝隙"}, {"w": "窍星", "t": "小洞"}, {"w": "窍坎", "t": "洞穴"}, {"w": "窍窦", "t": "孔穴"}, {"w": "窍凿", "t": "洞穴"}, {"w": "窍木", "t": "中空之木。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2104wx','窄','1','zhǎi','穴','10','','[{"pinyin": "zhǎi", "defs": [{"meaning": "(形声。从穴,乍声。本义:狭小)。"}, {"meaning": "同本义。", "cites": [{"t": "窄,陿也。", "b": "《广雅》"}, {"t": "齐室逼窄。", "b": "《华山亭碑》"}, {"t": "素标插人头,前途渐就窄。", "b": "陶潜《杂诗》"}], "words": [{"w": "窄索", "t": "窄小"}, {"w": "窄溜溜", "t": "形容窄"}, {"w": "窄逼逼", "t": "形容非常狭窄"}, {"w": "窄鳖鳖", "t": "非常狭窄的样子"}, {"w": "窄逼", "t": "狭隘;狭小"}, {"w": "窄窄别别", "t": "形容非常狭隘"}, {"w": "窄束", "t": "狭隘"}, {"w": "窄仄", "t": "狭隘"}, {"w": "窄生生", "t": "形容狭小"}, {"w": "窄陋", "t": "狭小简陋"}, {"w": "窄窄", "t": "狭小,狭窄。"}]}, {"meaning": "短缺;生活不宽裕。", "cites": [{"t": "乱世诛求急,黎民糠窄。", "b": "唐·杜甫《驱竖子摘苍耳》"}], "words": [{"w": "窄巴", "t": ""}]}, {"meaning": "整齐;漂亮。", "cites": [{"t": "遮遮掩掩衫儿窄。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "窄窄", "t": "漂漂亮亮。"}]}, {"meaning": "使缩小。", "cites": [{"t": "这院墙却是用瓦摆就的古老钱,丁大爷窄步而行。", "b": "《三侠五义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2105wx','容','1','róng','宀','10','','[{"pinyin": "róng", "defs": [{"meaning": "(会意兼形声。小徐本“从宀,谷(gǔ)。”大徐本看作会意。“宀”是房屋,“谷”是空虚的山洼,都有盛受的意思。本义:容纳)。"}, {"meaning": "同本义。", "cites": [{"t": "容,盛也。", "b": "《说文》"}, {"t": "君子以容民畜众。", "b": "《易·师》"}, {"t": "言宽大包容。", "b": "《汉书·五行志》"}, {"t": "故曰心容。", "b": "《荀子·解蔽》"}, {"t": "广则容奸。", "b": "《史记·乐书》"}, {"t": "可容一人居。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "容隐", "t": "包庇,隐瞒"}, {"w": "容足", "t": "仅容立足"}, {"w": "容接", "t": "容纳接待"}, {"w": "容盛", "t": "覆载,容纳"}, {"w": "容民", "t": "容纳民众"}, {"w": "容民畜众", "t": "容纳畜养民众"}, {"w": "容畜", "t": "容纳养育"}, {"w": "容受", "t": "容纳接受"}, {"w": "容放", "t": "容纳置放。"}]}, {"meaning": "宽容。", "cites": [{"t": "则今高爵显位,一旦抵罪,或脱身以逃,不能容于远近。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "容庶", "t": "宽容饶恕"}, {"w": "容物", "t": "度量宽大,能够容人"}, {"w": "容谅", "t": "宽容原谅"}, {"w": "容借", "t": "宽容"}, {"w": "容宽", "t": "宽容,宽恕"}, {"w": "容覆", "t": "宽容涵纳"}, {"w": "容纵", "t": "宽容放纵。"}]}, {"meaning": "允许,许可。", "cites": [{"t": "胡乱容他买碗吃罢。", "b": "《水浒传》"}], "words": [{"w": "容耐", "t": "容忍"}, {"w": "一首不容轻易解释的诗;容止", "t": "允许栖止"}, {"w": "详情容后函告;此事不容耽搁", "t": ""}]}, {"meaning": "收留。", "cites": [{"t": "无适小国,将不女容焉。", "b": "《左传》"}]}, {"meaning": "应当。", "cites": [{"t": "然则建巳之月为纯阳,不容都无复阴也。", "b": "《词诠引》"}]}, {"meaning": "等待,待。", "cites": [{"t": "容移时,有小黄头奴至。", "b": "《宣和遗事》"}]}, {"meaning": "需要。", "cites": [{"t": "齐卫之间不容数日行。", "b": "《韩非子》"}]}, {"meaning": "假借为“用”。使用。", "cites": [{"t": "兵无所容其刃。", "b": "《老子·五十章》"}]}, {"meaning": "仪容;容貌,容颜(容貌神色)。", "cites": [{"t": "物有其容。", "b": "《左传·昭公九年》"}, {"t": "孔德之容。", "b": "《老子》"}, {"t": "然自执政以来,忧勤国事,休休有容,有足多者。", "b": "《明史·海瑞传》"}, {"t": "一肌一容,尽态极妍。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "整容;遗容;音容;容颜", "t": "脸色"}, {"w": "笑容可掬;愁容;怒容;病容;容冶", "t": "容貌美艳"}, {"w": "容华", "t": "容貌,容颜"}, {"w": "容辉", "t": "仪容风采"}, {"w": "容质", "t": "容仪与资质"}, {"w": "容表", "t": "仪表,风采"}, {"w": "容妆", "t": "容貌妆饰。"}]}, {"meaning": "模式,样式。", "cites": [{"t": "凡为甲,必先为容。", "b": "《周礼·考工记·匠人》"}]}, {"meaning": "法则,规律。", "cites": [{"t": "夫物有常容,因乘以导之,因随物之容。", "b": "《韩非子》"}]}, {"meaning": "礼仪;礼法。", "cites": [{"t": "容台振而掩覆。", "b": "《淮南子·览冥》"}], "words": [{"w": "容典", "t": "礼容之法则"}, {"w": "容则", "t": "容典"}, {"w": "容台", "t": "行礼之台。"}]}, {"meaning": "一种佩饰用的刀。", "cites": [{"t": "佩刀,在佩旁之刀也,或曰容刀。", "b": "《释名》"}]}, {"meaning": "古州名 。在今广西壮族自治区东南部,邻接广东省。汉属合浦县,晋初置荡昌县,属合浦郡,梁改为阴石县,并置阴石郡,陈改为奉化县,隋改为普宁县,宋为容州,元为容州路,后降为州,明改为容县,属梧州府。"}, {"meaning": "常绿乔木。", "cites": [{"t": "种木胥容,榆桃柳楝。", "b": "《管子·地员》"}]}, {"meaning": "适宜,合宜。", "cites": [{"t": "因势合变,遇时之容。", "b": "《文选 》"}]}, {"meaning": "表示反问。难道;岂。", "cites": [{"t": "苟时未可,容得已乎?", "b": "《三国志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2106wx','宰','1','zǎi','宀','10','','[{"pinyin": "zǎi", "defs": [{"meaning": "(会意。从宀(mián),从辛。“宀”表屋子。辛,奴隶,罪人。本义:充当家奴的罪人)。"}, {"meaning": "同本义。", "cites": [{"t": "宰,罪人在屋下执事者。", "b": "《说文》"}]}, {"meaning": "一说古代贵族家中的管家或奴隶总管。", "cites": [{"t": "宰右执镫,左执盖。", "b": "《仪礼》。郑玄注:“宰谓太宰,宰夫之长也。”"}]}, {"meaning": "一说宰为手工业奴隶。"}, {"meaning": "古代官吏的通称。", "cites": [{"t": "宰者,官也。", "b": "《周礼·目录》"}, {"t": "乃立天官冢宰。", "b": "《周礼·序官》"}, {"t": "宰命司马戒众介。", "b": "《仪礼·聘礼》。注:“上卿贰君事者也。诸侯谓司徒为宰。”按,凡周官宰夫,仪礼大射仪宰胥,左襄廿六传宰旅,哀三传宰人,皆谓太宰之属,吏也。"}, {"t": "宰者何?官也。", "b": "《公羊传》"}, {"t": "宰严限追比。", "b": "《聊斋志异·促织》"}, {"t": "翼日进宰。", "b": ""}, {"t": "宰见其小。", "b": ""}, {"t": "宰以卓异闻。", "b": ""}], "words": [{"w": "宰人", "t": "周代冢宰的属官。后泛指官员;掌管膳食之官"}, {"w": "宰夫", "t": "周代天官冢宰的属官"}, {"w": "宰夫衙", "t": "太平天国主管屠宰的官署名。"}]}, {"meaning": "古官名。辅佐国君执政的百官之长。", "cites": [{"t": "天子之宰,通于四海。", "b": "《谷梁传·僖公九年》"}], "words": [{"w": "宰士", "t": "宰相的属官"}, {"w": "宰臣", "t": "帝王的重臣;宰相"}, {"w": "宰府", "t": "宰相办公之所"}, {"w": "宰柄", "t": "宰相的权柄"}, {"w": "宰牧", "t": "宰相与州牧的并称。"}]}, {"meaning": "屠宰者;厨工。", "cites": [{"t": "凡为人臣者,犹炮宰和五味而进之君。", "b": "《韩非子·难二》"}, {"t": "平为宰,分肉食甚均。", "b": "《史记·陈丞相世家》"}]}, {"meaning": "冢,坟墓。", "cites": [{"t": "若尔之年者,宰上之木拱矣。", "b": "《公羊传》"}], "words": [{"w": "宰木", "t": "坟墓上的树木"}, {"w": "宰隧", "t": "墓道"}, {"w": "宰树", "t": "坟墓上的树木。"}]}, {"meaning": "宰杀牲畜并割肉。", "cites": [{"t": "烹羊宰牛且为乐。", "b": "李白《将进酒》"}, {"t": "宰肉不平而斗。", "b": "《唐书·邓处纳传》"}], "words": [{"w": "宰夫", "t": "宰人。屠宰者;厨工"}, {"w": "宰生", "t": "屠夫"}, {"w": "宰猪;宰鸡;杀猪宰羊", "t": ""}]}, {"meaning": "分割疆土;主宰。", "cites": [{"t": "因利乘便,宰割天下。", "b": "贾谊《过秦论》"}, {"t": "使平得宰天下,亦如此肉矣!", "b": "《汉书·陈平传》"}], "words": [{"w": "宰世", "t": "掌管、治理天下"}, {"w": "宰民", "t": "掌治民众"}, {"w": "宰匠", "t": "主宰;掌治"}, {"w": "宰肉", "t": "未遇时怀有大志;从处理小事中可以看出治理国家的才能"}, {"w": "宰摄", "t": "主宰"}, {"w": "宰总", "t": "犹主宰"}, {"w": "宰席", "t": "主席的地位"}, {"w": "宰匠;宰主", "t": "主宰者。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2107wx','案','1','àn','木','10','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从木,安声。本义:木制的盛食物的矮脚托盘)。"}, {"meaning": "同本义。", "cites": [{"t": "赵王张敖自持案进食。", "b": "《史记·田叔列传》"}, {"t": "妻为具食,不敢于鸿前仰视,举案齐眉。", "b": "《后汉书·梁鸿传》"}, {"t": "对案不能食,拔剑击柱长叹息。", "b": "南朝宋·鲍照《拟行路难》"}], "words": [{"w": "捧案;案杯", "t": "案酒。"}]}, {"meaning": "无靠背的坐具。", "cites": [{"t": "师田,则张幕设案。(师田:出师或田猎。)", "b": "《周礼·天官》"}]}, {"meaning": "长方形的桌子。", "cites": [{"t": "案,几属。", "b": "《说文》"}, {"t": "权拔刀斫前奏案。", "b": "《三国志·周瑜传》"}, {"t": "庑下一人伏案卧。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "成妻纳钱案上。", "b": "《聊斋志异·促织》"}], "words": [{"w": "书案;伏案;条案,拍案", "t": "拍桌子。"}]}, {"meaning": "案件。", "cites": [{"t": "这么说来,却怎么了结此案?", "b": "《红楼梦》"}], "words": [{"w": "办案;破案;定案;结案;案由", "t": "案件的内容提要。"}]}, {"meaning": "官府处理公事的文书、成例。", "cites": [{"t": "终朝理文案,薄暮不遑瞑。", "b": "陆机《答张士然》"}, {"t": "无案牍之劳形。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "方案;提案;议案;草案", "t": ""}]}, {"meaning": "狱讼的案卷。", "cites": [{"t": "取案末独身无亲戚者二人易汝名。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "又。", "cites": [{"t": "竟行之,案末二人立决。", "b": ""}], "words": [{"w": "案记", "t": "卷宗文录"}, {"w": "案检", "t": "案卷。"}]}, {"meaning": "按语。同“按”。", "cites": [{"t": "案:黄帝葬于桥山,犹曰君臣葬其衣冠。", "b": "《论衡·道虚》"}], "words": [{"w": "加案", "t": ""}]}, {"meaning": "按;用手向下压。", "cites": [{"t": "案灌夫项,令谢。", "b": "《史记·魏其武安侯列传》"}]}, {"meaning": "考查,研求。", "cites": [{"t": "召有司案图。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "案贤圣之言,上下多相违,其文前后多相伐者。", "b": "王充《论衡·问孔》"}], "words": [{"w": "案举", "t": "考核并举荐"}, {"w": "案事", "t": "考问事实"}, {"w": "案首", "t": "查考记录。又指清朝科举考试时县、府及院试的头名。"}]}, {"meaning": "查办。", "cites": [{"t": "收案致法。", "b": "《汉书·赵尹韩张两王传》"}, {"t": "下有司案验。", "b": "《汉书·息夫躬传》"}], "words": [{"w": "案坐,案治", "t": "查办"}, {"w": "案验", "t": "审案定罪"}, {"w": "案杀", "t": "查办处死。"}]}, {"meaning": "查讯、审问。", "cites": [{"t": "使长安丞案贤。", "b": "《汉书·赵尹韩张两传》"}]}, {"meaning": "又。", "cites": [{"t": "出有案问。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "案之罪立具。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "案验甚急。", "b": ""}]}, {"meaning": "切。", "cites": [{"t": "则刺其足心各三所,案之,无出血,病旋已。", "b": "《史记·扁鹊仓公列传》"}, {"t": "朕使侍医伍宏等内侍案脉。", "b": "《汉书·王嘉传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2108wx','请','1','qǐng','讠','10','','[{"pinyin": "qǐng", "defs": [{"meaning": "情况,实情。", "cites": [{"t": "上下请通。", "b": "《墨子·尚同中》"}, {"t": "四璧而知请。", "b": "《管子·白心》"}]}, {"meaning": "(形声。从言,青声。本义:拜访)。"}, {"meaning": "同本义。", "cites": [{"t": "请,谒也。", "b": "《说文》"}, {"t": "使人为秋请。", "b": "《史记·吴王濞传》。集解引律云:“秋曰请。”"}, {"t": "不得入朝请。汉律盖改周礼之觐为请也。", "b": "《史记·魏其武安侯传》"}, {"t": "公子往,数请之,朱亥故不复谢。", "b": "《史记·魏公子列传》"}, {"t": "公卿相造请禹。", "b": "《史记·酷吏列传》"}], "words": [{"w": "请谒", "t": "拜见。"}]}, {"meaning": "请求;要求。", "cites": [{"t": "请,求也。", "b": "《广雅·释诂三》"}, {"t": "墓地不请。", "b": "《礼记·王制》"}, {"t": "夫请者,非可诒托而往也,必亲之者也。", "b": "《谷梁传·定公元年》"}, {"t": "臣是以无请也。", "b": "《韩非子·喻老》"}, {"t": "请为王吹竽。", "b": "《韩非子·内诸说上》"}, {"t": "曹刿请见。", "b": "《左传·庄公十年》"}, {"t": "力请客。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "请命乞身", "t": "请求离职退休"}, {"w": "请一个示", "t": "请求指示"}, {"w": "请了训", "t": "请求训示"}, {"w": "请蠲", "t": "请求免除田赋"}, {"w": "请期", "t": "婚礼之一,在行聘之后,请求女家同意婚期"}, {"w": "请咨", "t": "请求给予咨文"}, {"w": "请和", "t": "求和"}, {"w": "请托", "t": "走后门;拉关系。"}]}, {"meaning": "询问。", "cites": [{"t": "摈者去请事。", "b": "《仪礼·士昏礼》。注:“犹问也。”"}], "words": [{"w": "请仙", "t": "扶乩求仙,以卜休咎"}, {"w": "请日", "t": "卜问吉日"}, {"w": "请故", "t": "诘问其事故"}, {"w": "请罪", "t": "责问对方己有何罪。"}]}, {"meaning": "召;邀请。", "cites": [{"t": "战则请从。", "b": "《左传·庄公十年》"}], "words": [{"w": "请唤", "t": "请召呼唤"}, {"w": "请会", "t": "一种邀请他人参加的小型贷款形式"}, {"w": "请召", "t": "招请"}, {"w": "请逆", "t": "请人往迎"}, {"w": "请卖爵子", "t": "即请爵卖子"}, {"w": "请香头", "t": "请巫婆下神"}, {"w": "请不将", "t": "请不了;不能请。"}]}, {"meaning": "告诉。", "cites": [{"t": "主人答,再拜,乃请。", "b": "《仪礼》。郑玄注:“请,告也,告宾以射事。”"}]}, {"meaning": "在请求时用作表示礼貌。", "cites": [{"t": "请说之。", "b": "《墨子·公输》"}, {"t": "请从吏夜归。", "b": "唐·杜甫《石壕吏》"}, {"t": "请先言人之老少。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "请进来;请喝茶吧", "t": ""}]}, {"meaning": "请教,请示。", "cites": [{"t": "请所之。", "b": "《资治通鉴·唐纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2109wx','朗','1','lǎng','月','10','','[{"pinyin": "lǎng", "defs": [{"meaning": "(形声。从月,良声。本义:明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "朗,明也。", "b": "《说文》"}, {"t": "高朗令终。", "b": "《诗·大雅·既醉》"}, {"t": "其圣能光远宣朗。", "b": "《国语·楚语下》"}, {"t": "新而不朗。", "b": "《淮南子·原道》"}, {"t": "朗月垂光。", "b": "嵇康《琴赋》"}, {"t": "复行数十步,豁然开朗。", "b": "陶潜《桃花源记》"}, {"t": "天朗气清。", "b": "王羲之《兰亭集序》"}], "words": [{"w": "朗白", "t": "明亮发白"}, {"w": "朗朗", "t": "光明亮洁的样子;声音清脆嘹亮"}, {"w": "朗鉴", "t": "明鉴"}, {"w": "朗亮", "t": "雪亮"}, {"w": "朗明", "t": "明亮"}, {"w": "朗净", "t": "明净"}, {"w": "朗烈", "t": "明亮"}, {"w": "朗朗烈烈", "t": "大大方方;理直气壮。"}]}, {"meaning": "声音清晰响亮。", "cites": [{"t": "朗咏清川飞夜霜。", "b": "李白《劳劳亭歌》"}], "words": [{"w": "朗言", "t": "响亮的话;说大话;任意胡说"}, {"w": "朗然", "t": "形容声音响亮"}, {"w": "朗吟", "t": "高声的吟诵"}, {"w": "朗弹", "t": "大声弹奏"}, {"w": "朗畅", "t": "谓声音响亮流畅。"}]}, {"meaning": "明察。", "cites": [{"t": "公达潜朗。", "b": "袁宏《三国名臣序赞》"}]}, {"meaning": "又。", "cites": [{"t": "公瑾英达朗心独见。", "b": ""}], "words": [{"w": "朗心", "t": "明察之心;光明之心"}, {"w": "朗照", "t": "明察,明鉴"}, {"w": "朗抱", "t": "旷达的胸襟"}, {"w": "朗畅", "t": "明白畅达"}, {"w": "朗朗彻", "t": "明白透彻"}, {"w": "朗练", "t": "明白凝炼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2110wx','诸','1','zhū','讠','10','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从言,者声。本义:辩,问辩) 同本义。", "cites": [{"t": "诸,辩也。", "b": "《说文》。按,者亦意辩词也。"}, {"t": "诸诸便便,辩也。", "b": "《尔雅》"}, {"t": "穷研细诸问,岂得信虚辞!", "b": "《敦煌变文集·燕子赋》"}], "words": [{"w": "诸问", "t": "问辩。"}]}, {"meaning": "众;各。", "cites": [{"t": "诸郡县苦秦吏。", "b": "《史记·陈涉世家》"}, {"t": "西和诸戎。", "b": "《三国志·诸葛亮传》"}, {"t": "诸道桥梁。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "又。", "cites": [{"t": "诸将皆失色。", "b": ""}, {"t": "诸越则桃李冬实。(诸越,即“百越”,指两广地区。)", "b": "宋·沈括《梦溪笔谈》"}, {"t": "诸峰之顶,亦低于山顶之地面。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "仆必能从诸君子之后。(诸君子,指谭嗣同等)", "b": "清·梁启超《谭嗣同传》"}, {"t": "率诸少年。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "诸余", "t": "诸般;种种"}, {"w": "编辑部诸先生;诸恶", "t": "各种恶行"}, {"w": "诸种", "t": "各种;各个种族"}, {"w": "诸众", "t": "众多"}, {"w": "诸相", "t": "佛教指一切事物外观的形态。"}]}, {"meaning": "代人,代事,代物,相当于“之”。", "cites": [{"t": "告诸往而知来者。", "b": "《论语·学而》"}, {"t": "与诸乎?", "b": "《左传·僖公十三年》"}, {"t": "诸人不知,瞒不得你。", "b": "《西厢记》"}], "words": [{"w": "诸处", "t": "别处"}, {"w": "诸人", "t": "别人"}, {"w": "诸方", "t": "别的地方。"}]}, {"meaning": "作定语,相当于“其”。", "cites": [{"t": "无效齐庆封弑其君而弱其孤,以盟诸大夫!", "b": "《史记·楚世家》"}]}, {"meaning": "表示语气,相当于“啊”。", "cites": [{"t": "日居月诸,照临下土。", "b": "《诗·邶风·日月》"}]}, {"meaning": "干果。", "cites": [{"t": "桃诸,藏桃也。诸,储也。藏以为储,待给冬月用之也。", "b": "《释名》"}]}, {"meaning": "古地名 。春秋时鲁邑,在今山东省诸城县西南。", "cites": [{"t": "城诸及防。", "b": "《春秋》"}]}, {"meaning": "“之于”的合音。", "cites": [{"t": "君子求诸己。", "b": "《论语·卫灵公》"}, {"t": "投诸渤海之尾。", "b": "《列子·汤问》"}, {"t": "穆公访诸蹇叔。", "b": "《左传·僖公三十三年》"}, {"t": "谋诸漆工,作断纹焉。(诸:之于。)", "b": "明·刘基《郁离子·千里马篇》"}]}, {"meaning": "又。", "cites": [{"t": "谋诸篆工。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "匣而埋诸土。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "献诸朝。", "b": ""}, {"t": "献诸抚军。", "b": "《聊斋志异·促织》"}, {"t": "归而形诸梦。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "“之乎”的合音。", "cites": [{"t": "虽有粟,吾得而食诸?", "b": "《论语》"}, {"t": "王尝语庄子以好乐,有诸?", "b": "《孟子·梁惠王上》"}, {"t": "子闻诸?", "b": "《左传》"}]}, {"meaning": "相当于“于”。", "cites": [{"t": "宋人资章甫适诸越。", "b": "《庄子·逍遥游》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2111wx','诺','1','nuò','讠','10','','[{"pinyin": "nuò", "defs": [{"meaning": "(形声。从言,若声。本义:表示)。"}, {"meaning": "同本义(一般用于上对下、尊对卑或平辈之间,卑对尊用“谨诺” )。", "cites": [{"t": "诺,应也。", "b": "《说文》。按,应词也。缓应曰诺,疾应曰唯。"}, {"t": "莫敢不诺。", "b": "《诗·鲁颂·閟宫》"}, {"t": "太后曰:“诺。恣君之所使之。”", "b": "《战国策·赵策四》"}, {"t": "孟尝君不说,曰:“诺,先生休矣。", "b": "《战国策·齐策》"}], "words": [{"w": "诺诺", "t": "连声应诺"}, {"w": "诺唯", "t": "应诺"}, {"w": "诺许", "t": "许诺;应允。"}]}, {"meaning": "古时批字于公文之尾,表示许可叫“诺”,犹今签字。", "cites": [{"t": "是谁画诺谁传诏,一纸明贻万国羞!", "b": "清·黄遵宪《述闻》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2112wx','读','1','dòu dú','讠','10','','[{"pinyin": "dòu", "defs": [{"meaning": "语句中的停顿。古代诵读文章,分句和读,极短的停顿叫读,稍长的停顿叫句,今以逗号标志。也作“逗”。", "cites": [{"t": "句读之不知,惑之不解。", "b": "唐·韩愈《师说》"}, {"t": "援引他经,失其句读,以无为有,其可闵笑也,不可胜记也。", "b": "晋·何休《春秋公羊注疏序》"}]}]}, {"pinyin": "dú", "defs": [{"meaning": "(形声。从言,卖声。本义:读书)。"}, {"meaning": "籀书,抽释理解书的意义。", "cites": [{"t": "读,诵书也。", "b": "《说文》"}, {"t": "主人习其读而问其传。", "b": "《公羊传·定公元年》"}, {"t": "读其书。", "b": "《孟子》"}, {"t": "相随观读,讽述以谈。", "b": "《论衡·谈天》"}], "words": [{"w": "读法", "t": "诵读法令"}, {"w": "读祝", "t": "祭祀时宣读祈祷文"}, {"w": "读鞫", "t": "审判时,宣读起诉理由。"}]}, {"meaning": "阅读。", "cites": [{"t": "好读书,不求甚解。", "b": "晋·陶潜《五柳先生传》"}, {"t": "则其读书也必专,而其归书也必速。", "b": "清·袁枚《黄生借书说》"}, {"t": "楚人贫居,读《淮南方》。", "b": "邯郸淳《笑林》"}], "words": [{"w": "读报;默读", "t": "不出声地读书"}, {"w": "朗读;读律", "t": "学习法律"}, {"w": "读画", "t": "用心鉴赏绘画的意境,风格"}, {"w": "读过", "t": "读毕"}, {"w": "读杂志;审读", "t": "审查阅读。"}]}, {"meaning": "说。", "cites": [{"t": "读,说也。", "b": "《广雅·释诂二》"}, {"t": "号而读之也。", "b": "《庄子·则阳》"}]}, {"meaning": "文体名。属于题跋一类。用以记心得于书后,以备遗忘。", "cites": [{"t": "题读始于唐,跋书起于宋。", "b": "徐师曾《文体明辨》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2113wx','扇','1','shān shàn','户','10','','[{"pinyin": "shān", "defs": [{"meaning": "摇扇。", "cites": [{"t": "吹,扇助也。", "b": "《方言十二》"}, {"t": "艳妻扇方处。", "b": "《诗·小雅·十月之交》。毛本作煽。"}, {"t": "一扇息火,二扇生风,三扇下雨。", "b": "《西游记》"}], "words": [{"w": "扇风", "t": "摇扇以生风"}, {"w": "扇暍", "t": "传说周武王曾替中暑人扇风取凉"}, {"w": "扇枕温衾", "t": "对父母老人极尽孝道之意。"}]}, {"meaning": "施展。", "cites": [{"t": "宋官御史,坐行赇免,居林下,大扇威虐。", "b": "《聊斋志异》"}]}, {"meaning": "煽动、鼓动。", "cites": [{"t": "奸谄颇相扇构。", "b": "《晋书·谢安传》"}], "words": [{"w": "扇构", "t": "煽动众人借机迫害"}, {"w": "扇诱", "t": "煽惑引诱"}, {"w": "扇惑", "t": "煽动蛊惑"}, {"w": "扇聚", "t": "煽动纠合。"}]}, {"meaning": "泛指兴起、发生。", "cites": [{"t": "云雷方扇,鞠义旅以勤王。", "b": "《梁书》"}]}, {"meaning": "扑打。", "cites": [{"t": "忽有皂雕,飞起直来台上扇妲己。", "b": "《武王伐纣平话》"}]}, {"meaning": "炽盛。", "cites": [{"t": "阎妻骄扇,日以不臧。", "b": "《汉书·谷永传》"}, {"t": "逮乎江左,此道弥扇。", "b": "《梁书·谢举传论》"}, {"t": "暨乎暮年,此风愈扇。", "b": "《北史》"}]}]}, {"pinyin": "shàn", "defs": [{"meaning": "(会意。从户从翅省。户,单扇门;从翅,像鸟的翅膀,可以张合。本义:门扇)。"}, {"meaning": "同本义。", "cites": [{"t": "扇,扉也。门两旁如羽翼也。", "b": "《说文》"}, {"t": "乃修阖扇。", "b": "《礼记·月令》。注:“用竹葦曰扇。”"}], "words": [{"w": "扇板", "t": "门板"}, {"w": "扇扉", "t": "门扇"}, {"w": "窗扇;隔扇;火狐皮帽的耳扇", "t": ""}]}, {"meaning": "扇子。", "cites": [{"t": "箑,自关而西谓之扇。", "b": "《方言五》。按,即菨也。"}, {"t": "盖以杨门之扇。", "b": "《吕氏春秋》。注:“屏也。”"}, {"t": "有蒲葵扇五万。", "b": "《晋书·谢安传》"}], "words": [{"w": "芭蕉扇;羽毛扇;蒲扇;电扇;扇市", "t": "以出售扇子等夏季用品为主的市集"}, {"w": "扇拂", "t": "拂除灰尘的扇子"}, {"w": "扇坠", "t": "悬于扇柄的饰物"}, {"w": "扇月", "t": "圆月。以其如团扇,故称。"}]}, {"meaning": "毛巾、盖头之类织品。", "cites": [{"t": "候扇举而清叫,野闻声而应媒。", "b": "《文选·潘岳·射雉赋》"}]}, {"meaning": "用于门、窗等扁形器物。", "cites": [{"t": "旁开小窗,左右各四,共八扇。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "一扇门;两扇窗", "t": ""}]}, {"meaning": "遮蔽。", "cites": [{"t": "榆性扇地,其阴下五谷不生。", "b": "贾思勰《齐民要术》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2114wx','诽','1','fěi','讠','10','','[{"pinyin": "fěi", "defs": [{"meaning": "(形声。从言,非声。本义:背地议论,指责他人)。"}, {"meaning": "同本义。", "cites": [{"t": "诽,谤也。", "b": "《说文》。按,放言曰谤,微言曰诽、曰讥。”"}, {"t": "诽,明恶也。", "b": "《墨子经上》"}, {"t": "至于怨诽之多,则固前知其如此也。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "又如;诽怨(责备怨恨);诽议(责难,非议)。"}, {"meaning": "毁谤。", "cites": [{"t": "经诽誉。", "b": "《淮南子·本经》"}, {"t": "贤者诽。", "b": "《吕氏春秋·决胜》"}, {"t": "而废格沮诽。", "b": "《汉书·食货志》。注:“谓非上所行。”"}, {"t": "赏者有诽焉,不足以劝。", "b": "《韩非子·八经》"}], "words": [{"w": "诽诽", "t": "众说纷纷的样子"}, {"w": "诽章", "t": "谤书,谤毁他人的奏章"}, {"w": "诽讥", "t": "毁谤讥讽"}, {"w": "诽誉", "t": "毁谤和赞誉"}, {"w": "诽诋", "t": "诽谤诋毁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2115wx','袜','1','wà mò','衤','10','','[{"pinyin": "wà", "defs": [{"meaning": "穿在脚上的东西,针织或编织的足套。", "words": [{"w": "袜才", "t": "比喻才识短浅的自谦词"}, {"w": "袜线", "t": "比喻技艺多而无一精者"}, {"w": "袜桶", "t": "袜筒"}, {"w": "袜带", "t": "系袜所用的带"}]}, {"meaning": "穿袜子。", "cites": [{"t": "客初至时,不冠不袜。", "b": "清·魏禧《大铁椎传》"}]}]}, {"pinyin": "mò", "defs": [{"meaning": "抹胸", "words": [{"w": "抹胸", "t": "俗称肚兜"}]}, {"meaning": "掩盖;覆蔽", "words": [{"w": "袜首", "t": "袜额。古代武士所用的束发头巾;亦指戴束发头巾的武士打扮"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2116wx','袖','1','xiù','衤','10','','[{"pinyin": "xiù", "defs": [{"meaning": "(古字作褎。形声。从衣,由声。本义:衣袖)。"}, {"meaning": "同本义。", "cites": [{"t": "褎,袂也。", "b": "《说文》。字亦作褎、作袖"}, {"t": "攘袖见素手。", "b": "《文选·曹子建·乐府》"}, {"t": "长袖善舞。", "b": "《韩非子》"}], "words": [{"w": "袖搭", "t": "衣袖多由两片布料缝合而成,靠近袖口的一截称为袖搭"}, {"w": "袖佉", "t": "袖子的边口。"}]}, {"meaning": "袖口。", "cites": [{"t": "袖,衣袂端也。", "b": "唐·慧琳《一切经音义》"}]}, {"meaning": "藏物于袖中。", "cites": [{"t": "袖四十斤铁椎椎杀晋鄙。", "b": "《史记·魏公子列传》"}, {"t": "袖金以私之。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "袖占", "t": "在衣袖内占卜"}, {"w": "袖演", "t": "袖占"}, {"w": "袖刃", "t": "在衣袖中暗藏兵器"}, {"w": "袖手", "t": "藏手于袖,表示闲逸的神态;也指不能或不欲参与其事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2117wx','袍','1','páo','衤','10','','[{"pinyin": "páo", "defs": [{"meaning": "有夹层、中着棉絮的长衣。", "cites": [{"t": "衣敝縕袍。", "b": "《论语》。按,衣有箸者,今之绵衣,或曰箸以乱麻曰袍。"}, {"t": "纩为茧,縕为袍。", "b": "《礼记·玉藻》"}], "words": [{"w": "袍子", "t": ""}]}, {"meaning": "外衣。", "cites": [{"t": "袍者,表衣之通称。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2118wx','被','1','bèi pī','衤','10','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从衣,皮声。本义:睡眠时用以覆体的夹被;被子)。"}, {"meaning": "同本义。", "cites": [{"t": "被,寝衣,长一身有半。", "b": "《说文》"}, {"t": "翡翠珠被。", "b": "《楚辞·招魂》"}, {"t": "谣俗被服饮食奉生送死之具也。", "b": "《史记·货殖列传·序》"}, {"t": "外人颇有公孙布被之讥。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "棉被;夹被;毛巾被;被窝", "t": "覆以棉被,容人安睡的地方"}, {"w": "被卧", "t": "睡眠用的被子。"}]}, {"meaning": "表面。"}, {"meaning": "被覆;遮盖。", "cites": [{"t": "被袗衣。", "b": "《孟子·尽心下》"}, {"t": "被练三千。", "b": "《左传·襄公三年》。疏:“被是被覆衣着之名。”"}, {"t": "皋兰被径兮。", "b": "《楚辞·招魂》"}, {"t": "乃祖吾离被苫盖。", "b": "《左传·襄公十四年》"}, {"t": "凝霜被野草。", "b": "三国魏·阮籍《咏怀》"}, {"t": "如被冰雪。", "b": "《聊斋志异·促织》"}], "words": [{"w": "被体", "t": "涂满全体"}, {"w": "被覆", "t": "覆盖,掩蔽;亦专指覆盖在地面的草木等自然物。"}]}, {"meaning": "蒙受,遭受。", "cites": [{"t": "秦王复击轲,被八创。", "b": "《战国策·燕策》"}, {"t": "其被轰击者,则断壁危楼。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "寡人不详,被于宗庙之祟。", "b": "《战国策·齐策》"}, {"t": "禹、汤被之矣。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "被水", "t": "遭水灾"}, {"w": "被命", "t": "奉命;受命。"}]}, {"meaning": "及;到达。", "cites": [{"t": "东渐于海,西被于流沙。", "b": "《书·禹贡》"}], "words": [{"w": "被及", "t": "延及,广及。"}]}, {"meaning": "加;施加。", "cites": [{"t": "允恭克让,光被四表(四海之外)。", "b": "《书·尧典》"}]}, {"meaning": "表示被动:叫;让。", "cites": [{"t": "妆成每被秋娘妒。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "幸借天降大雨,房屋未被火烧。", "b": "《广州军务记》"}, {"t": "风流总被雨打风吹去。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "芦花被微风吹起;歌本儿被人借走了", "t": ""}]}]}, {"pinyin": "pī", "defs": [{"meaning": "(后作“披”)。"}, {"meaning": "搭衣于肩背。", "cites": [{"t": "操吴戈兮被犀甲,车错毂兮短兵接。", "b": "《楚辞·屈原·国殇》"}, {"t": "被明月兮佩宝璐。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "被巾", "t": "披巾"}, {"w": "被缁", "t": "披上缁衣。谓出家当僧尼"}, {"w": "被以虎文", "t": "披上虎皮。喻指添加声势"}, {"w": "被衣", "t": "把衣服披在肩背上"}, {"w": "被练", "t": "古代徒兵的一种披在甲外的练袍;亦借指披练袍的徒兵。"}]}, {"meaning": "穿着。", "cites": [{"t": "同舍生皆被绮绣。", "b": "明·宋濂《送东阳马生序》"}, {"t": "将军身被坚执锐。", "b": "《史记·陈涉世家》"}], "words": [{"w": "被甲持兵", "t": "被甲执兵,被甲载兵。被坚执锐"}, {"w": "被坚执锐", "t": "被甲执锐。穿坚固甲胄,握锐利武器。谓上阵战斗或作好战斗准备"}, {"w": "被朱佩紫", "t": "穿红袍,挂紫绶。谓身为大官"}, {"w": "被孝", "t": "穿着守丧的服饰。"}]}, {"meaning": "打开。", "cites": [{"t": "微管仲,吾其被发左衽矣。", "b": "《论语·宪问》"}], "words": [{"w": "被发", "t": "发不束而披散"}, {"w": "被发左衽", "t": "头发披散不束,衣襟向左掩。古代指中原地区以外少数民族的装束,借指中原地区的人受少数民族统治"}, {"w": "被发佯狂", "t": "披散头发,装作疯狂。古时作为一种避世全身的行为"}, {"w": "被发跣足", "t": "披头散发,赤着脚"}, {"w": "被发缨冠", "t": "披发散缨。形容匆忙急迫不及整束。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2119wx','祥','1','xiáng','礻','10','','[{"pinyin": "xiáng", "defs": [{"meaning": "(形声。从示,羊声。本义:凶吉的预兆,预先显露出来的迹象)。"}, {"meaning": "同本义。", "cites": [{"t": "无道曰祥。", "b": "《周书·武顺》"}, {"t": "吉事有祥。", "b": "《易·系辞》"}, {"t": "辰马,农祥也。", "b": "《国语·周语》"}, {"t": "将有大祥。", "b": "《左传·昭公十八年》。注:“变异之气。”"}, {"t": "卓问肃曰:“此何祥也?”", "b": "《三国演义》"}, {"t": "是何祥也,吉凶焉在?", "b": "《左传·僖公十六年》"}]}, {"meaning": "特指吉兆。", "cites": [{"t": "以观妖祥,辨吉凶。", "b": "《周礼·春官》。郑玄注:“妖祥,善恶之征。”"}, {"t": "袭于休祥。", "b": "《国语·周语》。注:“福之先见者也。”"}, {"t": "台不过望氛祥。", "b": "《国语·楚语》。注:“吉气为祥。”"}, {"t": "不祥之气。", "b": "《老子·佳兵》。注:“喜也。”"}, {"t": "期而小祥。", "b": "《仪礼·士虞礼记》。注:“吉也。”"}]}, {"meaning": "特指凶兆。", "cites": [{"t": "亳有祥,桑谷共生于朝。", "b": "《书·咸有一德》。孔传:“祥,妖怪。”"}, {"t": "孽狐为之祥。", "b": "《庄子·庚桑楚》。李注:“怪也。”"}], "words": [{"w": "祥桑", "t": "妖桑,不吉祥之桑。"}]}, {"meaning": "幸福。", "cites": [{"t": "神光并见,咸受祯祥。", "b": "《汉书》"}]}, {"meaning": "吉利。", "cites": [{"t": "祥,福也。从示,羊声。一云善。", "b": "《说文》"}, {"t": "祥,善也。", "b": "《尔雅》。李注:“福之善也。”"}, {"t": "文定厥祥。", "b": "《诗·大雅·大明》"}, {"t": "忠言信慈祥。", "b": "《仪礼·士相见礼》"}, {"t": "是谓大祥。", "b": "《礼记·礼运》"}, {"t": "弃德不祥。", "b": "《左传·僖公三年》"}, {"t": "知渊中之鱼者不祥。", "b": "《韩非子·说林上》"}, {"t": "且夫天下盖有不仁不祥者。", "b": "《墨子》"}, {"t": "寡人不祥。", "b": "《战国策·齐策四》"}, {"t": "俄而祥风。", "b": "唐·李朝威《柳毅传》"}, {"t": "心知不祥。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "祥禽", "t": "瑞禽"}, {"w": "祥符", "t": "吉祥的符瑞"}, {"w": "祥英", "t": "瑞雪。"}]}, {"meaning": "好的;善的。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2120wx','课','1','kè','讠','10','','[{"pinyin": "kè", "defs": [{"meaning": "(形声。从言,果声。本义:考核)。"}, {"meaning": "同本义(根据一定的标准验核)。", "cites": [{"t": "课,试也。", "b": "《说文》"}, {"t": "操杀生之柄,课群臣之能者也。", "b": "《韩非子·定法》"}, {"t": "成器不课不用,不试不藏。", "b": "《管子·七发》"}, {"t": "有官而无课,是无官也;有课而无赏罚,是无课也。", "b": "苏洵《上皇帝书》"}], "words": [{"w": "课其事业;课试", "t": "试验,考核"}, {"w": "课绩", "t": "考绩。"}]}, {"meaning": "督促完成指定的工作。", "cites": [{"t": "课家人负物百斤,环舍趋走。", "b": "《后汉书》"}]}, {"meaning": "按规定的内容和分量讲授或学习。", "cites": [{"t": "每晚同鲁小姐课子到三更四鼓。", "b": "《儒林外史》"}], "words": [{"w": "课子", "t": "教子读书"}, {"w": "课读", "t": "按规定的内容和数量教授或学习。"}]}, {"meaning": "征收赋税;差派劳役。", "cites": [{"t": "是岁,始课南徐州侨民租。", "b": "《宋书·孝武帝本纪》"}], "words": [{"w": "课役", "t": "徵抽财税,分派徭役"}, {"w": "课以重税", "t": ""}]}, {"meaning": "占卜。", "cites": [{"t": "有日者,能课,使之课,莫不奇中。", "b": "惠洪《冷斋夜话》"}], "words": [{"w": "课筒", "t": "占卜的签筒"}, {"w": "课语讹言", "t": "胡说八道。"}]}, {"meaning": "税款,税。", "cites": [{"t": "免其课役。", "b": "魏征《隋书》"}], "words": [{"w": "国课;盐课;课口", "t": "唐时赋税有租、庸、调,其应纳赋税的人口称为课口"}, {"w": "课户", "t": "应纳赋税的民户。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2121wx','冥','1','míng','冖','10','','[{"pinyin": "míng", "defs": [{"meaning": "(会意。小篆字形,从日,从六,冖(mì)声。日,太阳,日数十,十六日而月始亏,幽暗也。本义:昏暗)。"}, {"meaning": "同本义。", "cites": [{"t": "冥,幽也。", "b": "《说文》"}, {"t": "冥,暗也。", "b": "《广雅》"}, {"t": "冥者,明之藏也。", "b": "《太玄·玄文》"}, {"t": "维尘冥冥。", "b": "《诗·无将大车》"}, {"t": "擿埴索涂,冥行而已矣。", "b": "《法言·修身》"}, {"t": "冥火薄天,兵车雷运。", "b": "枚乘《七发》"}, {"t": "其庙独冥。", "b": "《汉书·五行志》"}], "words": [{"w": "冥冥", "t": "昏暗"}, {"w": "冥冥灭灭", "t": "昏暗不明的样子"}, {"w": "冥蒙", "t": "晦暗不明"}, {"w": "冥升", "t": "暗升;后指不断攀登"}, {"w": "冥幻", "t": "暗淡虚幻。"}]}, {"meaning": "深远;幽深。", "cites": [{"t": "临万丈之绝冥。", "b": "孙绰《游天台山赋》。注:“幽深也。”"}, {"t": "高低冥迷,不知西东。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "冥绝", "t": "杳远隔绝"}, {"w": "冥寞", "t": "广漠无边"}, {"w": "冥缅", "t": "幽远的样子"}, {"w": "冥翳", "t": "高远"}, {"w": "冥冥", "t": "幽深的样子。"}]}, {"meaning": "愚昧。", "cites": [{"t": "寡人惷愚冥烦。", "b": "《礼记·哀公问》。注:“言不能明理此事。”"}, {"t": "不然,则是鳄鱼冥顽不灵。", "b": "韩愈《祭鳄鱼文》"}], "words": [{"w": "冥昧", "t": "蒙昧"}, {"w": "冥迷", "t": "迷糊"}, {"w": "冥愚", "t": "愚昧"}, {"w": "冥烦", "t": "寓顽。"}]}, {"meaning": "虚空渺茫。", "cites": [{"t": "至道之精,窈冥冥。", "b": "《庄子·在宥》。注:“皆了无也。”"}], "words": [{"w": "冥空", "t": "空虚渺茫"}, {"w": "冥思", "t": "空想"}, {"w": "冥浮", "t": "依稀渺茫的样子。"}]}, {"meaning": "静默。", "cites": [{"t": "冥然兀坐,万籁有声。", "b": "归有光《项脊轩志》"}], "words": [{"w": "冥心危坐", "t": "端正地坐着,静静地思考问题"}, {"w": "冥寂", "t": "幽静"}, {"w": "冥漠", "t": "静寂"}, {"w": "冥默", "t": "玄默沉静"}, {"w": "冥寞", "t": "玄默,冥寂"}, {"w": "冥冥", "t": "沉默不语的样子。"}]}, {"meaning": "潜心,专心。", "cites": [{"t": "无冥冥之志,无昭昭之明。", "b": "《荀子·劝学》。注:“专默精诚之谓也。”"}, {"t": "冥搜未已。", "b": "《聊斋志异·促织》"}], "words": [{"w": "冥求", "t": "潜心探索"}, {"w": "冥心", "t": "潜心苦思"}, {"w": "冥志", "t": "静心"}, {"w": "冥索", "t": "潜心探究。"}]}, {"meaning": "迷信人称人死后进入的世界,即“地府”、“阴间”。", "cites": [{"t": "人皆以为冥谪(谪:处罚)。", "b": "方苞《狱中杂记》"}], "words": [{"w": "冥曹", "t": "阴曹地府。迷信者认为,在世间作恶的人,死后要在这里受审治罪"}, {"w": "冥阴界", "t": "鬼魂活动的阴间世界"}, {"w": "冥宅", "t": "为死者焚化的纸房子,传说死者能在阴间使用"}, {"w": "冥事", "t": "阴间的事情。"}]}, {"meaning": "海。", "cites": [{"t": "北冥有鱼,其名为鲲。", "b": "《庄子·消遥游》"}, {"t": "是鸟也,海运则将徒于南冥。南冥者,天池也。", "b": ""}]}, {"meaning": "闭上眼睛。", "cites": [{"t": "彼至人者,归精神乎无始,而甘冥乎无何有之乡。", "b": "《庄子·列御寇》"}], "words": [{"w": "冥目", "t": "闭上眼睛;死去"}, {"w": "冥坐", "t": "闭目而坐。"}]}, {"meaning": "暗合,默契。", "cites": [{"t": "神与理冥。", "b": "高允《征士颂》"}], "words": [{"w": "冥合", "t": "暗合"}, {"w": "冥契", "t": "默契,暗相投合;指意气相投的好友"}, {"w": "冥符", "t": "默契,暗合。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2122wx','谁','1','shéi shuí','讠','10','','[{"pinyin": "shéi", "defs": [{"meaning": "——“谁”(shuí)的又音。"}]}, {"pinyin": "shuí", "defs": [{"meaning": "(形声。从言,隹(zhuī)声。金文字形,象鸟在叫。①基本义:什么人。《左传·隐公元年》:“其谁曰不然?”②什么。《说文》:“何也。”)。"}, {"meaning": "哪个人或哪些人。", "cites": [{"t": "莫愁前路无知己,天下谁人不识君", "b": "唐·高适《别董大》"}], "words": [{"w": "那是谁;站在门口的人是谁;这个单位谁当政;你把书给了谁?谁承望", "t": "谁想到"}, {"w": "谁家子", "t": "谁,何人"}, {"w": "谁子", "t": "谁氏,何人"}, {"w": "谁当", "t": "谁人,何人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2123wx','调','1','diào tiáo zhōu','讠','10','','[{"pinyin": "diào", "defs": [{"meaning": "(形声。从言,周声。(tiáo)本义:声音调和;协调)。"}, {"meaning": "选拔或提拔官吏。", "cites": [{"t": "调故吏。", "b": "《汉书·昭帝纪》。注:“谓发选也。”"}, {"t": "调关东轻车锐卒。", "b": "《汉书·宣帝纪》"}, {"t": "十年不得调,亡所知名。", "b": "《汉书》"}, {"t": "婿竟不调。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "调头", "t": "换地方;自主的妓女迁居"}, {"w": "调职", "t": "公务员调换服务单位。"}]}, {"meaning": "征用,提取,征发。", "cites": [{"t": "特选横调。", "b": "《后汉书·左雄传》。注:“征也。”"}], "words": [{"w": "调发", "t": "征发"}, {"w": "调练", "t": "征调操练"}, {"w": "调取", "t": "发命令取人。"}]}, {"meaning": "调动。", "cites": [{"t": "我是个调虎离山计,哄你去来征战。", "b": "《西游记》"}], "words": [{"w": "调人;调干部;调遣;调阵子", "t": "调阵。舞台上演员扮兵将调兵布阵的样子"}, {"w": "调补", "t": "调动填补官职空缺"}, {"w": "调派", "t": "分派"}, {"w": "调拨", "t": "调遣分派"}, {"w": "调三惑四", "t": "挑拨离间。"}]}, {"meaning": "计算;调查。", "cites": [{"t": "调立城邑。", "b": "《汉书·晁错传》"}, {"t": "要害之处,通川之道,调立城邑,毋下千家。", "b": "《汉书》"}]}, {"meaning": "", "cites": [{"t": "杨志调过朴刀便打。", "b": "《水浒传》"}]}, {"meaning": "格调,人的才气风格 。", "cites": [{"t": "谁爱风流高格调。", "b": "唐·秦韬玉《贫女》"}], "words": [{"w": "才调;雅调", "t": ""}]}]}, {"pinyin": "tiáo", "defs": [{"meaning": "(形声。从言,周声。本义:和谐;协调) 同本义。", "cites": [{"t": "调,和也。", "b": "《说文》"}, {"t": "合得周密谓之调。", "b": "《贾子道术》"}, {"t": "调和乐也。", "b": "《荀子·臣道》"}, {"t": "弓矢既调。", "b": "《诗·小雅·车攻》"}, {"t": "调悦者,情之道也。", "b": "《大戴礼记·子张问入官》"}, {"t": "调而应之。", "b": "《庄子·知北游》"}, {"t": "帝善其调达,乃敕一御妓奏笛。", "b": "《晋书·桓伊传》"}, {"t": "若水旱不调,宁燥不湿。", "b": "贾思勰《齐民要术》"}], "words": [{"w": "调元", "t": "调和大化阴阳的元气"}, {"w": "调序", "t": "调和"}, {"w": "调琴", "t": "调和琴弦,弹琴"}, {"w": "调畅", "t": "调和通畅"}, {"w": "调适", "t": "调和顺适"}, {"w": "调调", "t": "风吹物摇动的样子"}, {"w": "调变", "t": "调和,调理。"}]}, {"meaning": "调节。", "cites": [{"t": "调竽笙篪篁。", "b": "《礼记·月令》"}], "words": [{"w": "调排", "t": "调整安排"}, {"w": "调风", "t": "整顿风俗"}, {"w": "调气", "t": "调节四时的气候"}, {"w": "调息", "t": "调节呼吸。"}]}, {"meaning": "驯服;训练。", "cites": [{"t": "无鞭策,虽造父不能调驷马。", "b": "《盐铁论》"}]}, {"meaning": "调治;调养(调治保养)。", "cites": [{"t": "法酒调神气,清琴入性灵。", "b": "刘禹锡《昼居池上亭独吟》"}], "words": [{"w": "调鼎持衡", "t": "比喻治理国家"}, {"w": "调息", "t": "调养休息"}, {"w": "调治", "t": "医疗;疗治。"}]}, {"meaning": "嘲笑。", "cites": [{"t": "唐僧渊目深而鼻高,王丞相每调之。", "b": "《世说新语》"}], "words": [{"w": "调喉", "t": "取笑"}, {"w": "调侃", "t": "用言语戏弄;嘲弄。"}]}, {"meaning": "搀合 。", "words": [{"w": "调三窝四", "t": "搬弄是非"}, {"w": "调白", "t": "挑唆"}, {"w": "调味", "t": ""}]}, {"meaning": "经搅拌、摇晃。", "words": [{"w": "调和鼎鼐", "t": "在鼎里调和食物。比喻辅佐皇帝治理国家。亦喻宰相之职"}, {"w": "调匀;调色", "t": ""}]}, {"meaning": "调节音高或使之入调 。", "words": [{"w": "调弦;调高一个小三度或大三度", "t": ""}]}, {"meaning": "演奏。", "cites": [{"t": "何处调琴,惺惺地把醉魂呼醒?", "b": "董解元《西厢记诸宫调》"}]}, {"meaning": "调济。", "cites": [{"t": "故盐铁均输,所以通委财而调缓急,罢之不便也。", "b": "《盐铁论》"}]}, {"meaning": "调戏。", "cites": [{"t": "李师师再与燕青把盏,又把言语来调他。", "b": "《水浒传》"}], "words": [{"w": "调光", "t": "勾引;调情"}, {"w": "调引", "t": "引逗;勾引。"}]}, {"meaning": "掷;丢。", "cites": [{"t": "我看了,搬起一块大石,调打下去。", "b": "《西游记》"}]}, {"meaning": "耍 。", "words": [{"w": "调嘴调舌", "t": "耍嘴皮"}, {"w": "调嘴", "t": "耍嘴皮子"}, {"w": "调脾", "t": "耍脾气;顽皮。"}]}, {"meaning": "调弄,弹奏。", "cites": [{"t": "可以调素琴。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "烹调,调味。", "cites": [{"t": "一鼎之调。", "b": "《吕氏春秋·察今》"}]}]}, {"pinyin": "zhōu", "defs": [{"meaning": "清晨,早晨", "cites": [{"t": "未见君子,惄如调饥。", "b": "《诗·周南·汝坟》"}], "words": [{"w": "调饥", "t": "朝饥。早晨没吃东西时的饥饿状况。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2124wx','冤','1','yuān','冖','10','','[{"pinyin": "yuān", "defs": [{"meaning": "(会意。从兔,从冖(mì)。“冖”表示覆盖。兔子被覆盖住了,卷曲不能伸。或从冖,表示在房屋内。本义:屈缩;不舒展)。"}, {"meaning": "同本义。", "cites": [{"t": "冤,屈也。从兔,在冂下不得走,益屈折也。", "b": "《说文》"}, {"t": "冤,曲也。", "b": "《广雅》"}, {"t": "冤颈折翼,庸得往兮!", "b": "《汉书·息夫躬传》。颜师古注:“冤,屈也”"}], "words": [{"w": "冤曲", "t": "弯曲"}, {"w": "冤伏", "t": "屈伏"}, {"w": "冤延", "t": "宛延。长曲的样子。"}]}, {"meaning": "枉曲,冤屈。", "cites": [{"t": "哀枯杨之冤雏兮。", "b": "《楚辞·离世》。注:“冤,烦冤也。”"}, {"t": "我今日负屈衔冤哀告天。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "冤苦钱", "t": "囚犯送给狱卒的贿赂"}, {"w": "冤业", "t": "含冤的鬼魂。"}]}, {"meaning": "冤仇,仇敌。", "cites": [{"t": "无冤尤。", "b": "《盐铁论·毁学》"}, {"t": "掠拷冤滥。", "b": "《后汉书·杨终传》"}, {"t": "孤魂抱深冤。", "b": "韩愈《谢自然》"}], "words": [{"w": "冤衍", "t": "冤仇;罪咎"}, {"w": "冤业之症", "t": "指由于结冤造孽而得的病症"}, {"w": "冤冤相报", "t": "冤家对头世世代代循环以恶相报。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2125wx','谅','1','liàng','讠','10','','[{"pinyin": "liàng", "defs": [{"meaning": "(形声。从言,京声。本义:诚实;信实)。"}, {"meaning": "同本义。", "cites": [{"t": "谅,信也。", "b": "《说文》"}, {"t": "众信曰谅。", "b": "《方言一》"}, {"t": "请肆简谅。", "b": "《礼记·内则》"}, {"t": "友直友谅。", "b": "《论语》"}, {"t": "易直子谅之心。", "b": "《礼记·祭义》"}, {"t": "私直怜兮何极,心怦怦兮谅直。", "b": "《楚辞·九辩》"}], "words": [{"w": "谅直(诚信正直) ;谅士(诚信之士", "t": ""}, {"w": "谅节", "t": "高尚的节操"}, {"w": "谅实", "t": "真诚。"}]}, {"meaning": "固执,坚持己见。", "cites": [{"t": "君子贞而不谅。", "b": "《论语·卫灵公》"}]}, {"meaning": "谅解。", "cites": [{"t": "母也天只,不谅人只。", "b": "《诗·鄘风·柏舟》"}, {"t": "未必谅某此心也。", "b": "欧阳修《与刁景纯学士书》"}], "words": [{"w": "本着互谅互让的精神;谅情", "t": "体谅实情。"}]}, {"meaning": "宽恕或容忍。", "cites": [{"t": "谅其至冤。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "谅宥", "t": "原谅"}, {"w": "尚希见谅", "t": ""}]}, {"meaning": "料想,认为。", "cites": [{"t": "自谅前事年远,无人推剥。", "b": "《京本通俗小说·冯玉梅庆团圆》"}], "words": [{"w": "谅不见怪;谅必如此;谅来", "t": "想来;料想"}, {"w": "谅他也不会这样做", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2126wx','谆','1','zhūn','讠','10','','[{"pinyin": "zhūn", "defs": [{"meaning": "(形声。本义:教诲恳切耐心的样子)。"}, {"meaning": "同本义。多叠用,也单用。", "cites": [{"t": "谆,告晓之熟也。", "b": "《说文》。字亦作訰。"}, {"t": "诲尔谆谆。", "b": "《诗·大雅·抑》"}, {"t": "不必谆谆。", "b": "《史记·司马相如传》。集解:“告之丁宁也。”"}, {"t": "天与之者,谆谆然命之乎?", "b": "《孟子》"}, {"t": "通使也与唐敖行礼,再再谆托。", "b": "《镜花缘》"}], "words": [{"w": "谆谆醇醇", "t": "恳切淳厚"}, {"w": "谆谆教导;谆谕", "t": "谆谆告谕"}, {"w": "谆熟", "t": "再三告诫要牢记在心。"}]}, {"meaning": "诚恳;忠诚。", "cites": [{"t": "谆谆忠谨之貌也。", "b": "《后汉书·卓茂传》注"}, {"t": "吾嫉惰游者,怜子愚且谆。", "b": "韩愈《送惠师》"}], "words": [{"w": "谆笃", "t": "诚恳笃实"}, {"w": "谆朴", "t": "忠厚朴实"}, {"w": "谆问", "t": "恳切询问"}, {"w": "谆托", "t": "恳切相托"}, {"w": "谆切", "t": "诚实恳切。"}]}, {"meaning": "辅佐。", "cites": [{"t": "曾孙蒯聩以谆赵鞅之故,敢昭告于皇祖文王、烈祖康叔、文祖襄公、昭考灵公。", "b": "《国语·晋语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2127wx','谈','1','tán','讠','10','','[{"pinyin": "tán", "defs": [{"meaning": "(形声。从言,炎声。本义:说,谈论)。"}, {"meaning": "同本义。", "cites": [{"t": "谈,语也。", "b": "《说文》。字亦作谭。"}, {"t": "不敢戏谈。", "b": "《诗·小雅·节南山》"}, {"t": "三日不谈。", "b": "《庄子·天运》"}, {"t": "宏为人谈笑多闻。", "b": "《汉书·公孙宏传》"}, {"t": "坐谈问之。", "b": "《战国策·齐策》"}, {"t": "不假仆一二谈也。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "谈笑而死。", "b": "明·张溥《五人墓碑记》"}, {"t": "女子毋多谈。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "谈笑自若;谈聚", "t": "相聚在一起尽情交谈"}, {"w": "谈会", "t": "聚在一起谈论"}, {"w": "洽谈", "t": "接洽商谈"}, {"w": "座谈", "t": "不拘形式地讨论"}, {"w": "谈天", "t": "谈论天文。"}]}, {"meaning": "称赞。", "cites": [{"t": "那个将军不喝采,那个把我不谈羡?", "b": "元·佚名《飞刀对箭》"}], "words": [{"w": "谈荐", "t": "称赞和推荐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2128wx','谊','1','yì','讠','10','','[{"pinyin": "yì", "defs": [{"meaning": "(会意兼形声。从言,从宜,宜亦声。宜,表示合宜。本义:合宜的道德、行为或道理)。"}, {"meaning": "同本义 。古“谊”与“义”同。", "cites": [{"t": "舍生取谊。", "b": "班固《幽通赋》"}, {"t": "素闻先生高谊。", "b": "《公孙龙子·迹府》"}, {"t": "武王行大谊。", "b": "《汉书·董仲舒传》"}], "words": [{"w": "谊士", "t": "义士"}, {"w": "谊主", "t": "指明礼义的国君。"}]}, {"meaning": "意义,意思。", "cites": [{"t": "会意者,比类合谊。", "b": "《说文解字叙》"}, {"t": "儒者竞复比谊会意。", "b": "《风俗通义·序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2129wx','剥','1','bō bāo','刂','10','','[{"pinyin": "bō", "defs": [{"meaning": "(会意。从刀,从录,“录”又兼作声符。“录”,《说文》:“刻割也。”本义:削;剥离;剥脱,即去掉物体表面上的东西)。"}, {"meaning": "同本义。", "cites": [{"t": "剥,裂也。", "b": "《说文》"}, {"t": "剥,离也。", "b": "《广雅》"}, {"t": "或剥或亨。", "b": "《诗·小雅·楚茨》"}, {"t": "然不剥脱,不砥厉,则不可以断绳。", "b": "《荀子·强国》。注:“剥脱,谓刮去其生涩。”"}, {"t": "冬日至,令剥阴木而水之。", "b": "《周礼·秋官》。注:“刊、剥互言耳,皆谓斫去次地之皮。”"}, {"t": "溪头卧剥莲蓬。", "b": "宋·辛弃疾《清平乐·村居》"}], "words": [{"w": "剥除", "t": "削去"}, {"w": "剥割", "t": "割削"}, {"w": "剥制", "t": "剥取或削除外皮,加工制作"}, {"w": "剥皮", "t": "剥去外皮。"}]}, {"meaning": "割裂。", "cites": [{"t": "是剥是菹。", "b": "《诗·小雅·信南山》"}]}, {"meaning": "脱落。", "cites": [{"t": "实熟则剥。", "b": "《庄子》"}, {"t": "汉隶岁久,风雨剥蚀,故其字无复锋芒。", "b": "陆游《老学庵笔记》"}], "words": [{"w": "剥落", "t": "剥损脱落;落地,没有选上"}, {"w": "剥缺", "t": "剥落残缺"}, {"w": "剥坏", "t": "剥落损坏。"}]}, {"meaning": "强制除去。", "cites": [{"t": "裸剥士女。", "b": "房玄龄《晋书》"}], "words": [{"w": "剥庐", "t": "剥夺他人荫庇之所;穷困的居所"}, {"w": "剥放", "t": "斥退。"}]}, {"meaning": "盘剥;掠夺。", "cites": [{"t": "故为吏牧民者竞相剥削。", "b": "《梁书·贺琛传》"}, {"t": "患在于剥夺之不已。", "b": "元稹《钱货议状》"}], "words": [{"w": "剥害", "t": "盘剥伤害"}, {"w": "剥褫", "t": "革除;褫夺。"}]}, {"meaning": "伤害。", "cites": [{"t": "剥丧元良。", "b": "《书·泰誓中》"}], "words": [{"w": "剥丧", "t": "伤亡"}, {"w": "剥戮", "t": "伤害杀戮"}, {"w": "剥丧", "t": "伤亡;丧乱。"}]}]}, {"pinyin": "bāo", "defs": [{"meaning": "[口语]去掉外面的皮或其他东西", "words": [{"w": "剥花生", "t": ""}, {"w": "剥碗豆", "t": ""}, {"w": "剥葱皮", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2130wx','恳','1','kěn','心','10','','[{"pinyin": "kěn", "defs": [{"meaning": "(形声。从心,(kěn)声。本义:诚恳,真诚)同本义。", "cites": [{"t": "恳,信也。", "b": "《广雅·释诂一》"}, {"t": "至诚曰恳。", "b": "《一切经音义》四引《通俗文》"}, {"t": "意气勤勤恳恳。", "b": "《汉书·司马迁传》。师古曰:“恳恳,至诚也。”"}, {"t": "又乖恳愿。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "恳悃", "t": "真心诚意"}, {"w": "恳款", "t": "殷切诚恳"}, {"w": "恳曲", "t": "诚恳委婉"}, {"w": "恳言", "t": "诚挚之言"}, {"w": "恳直", "t": "诚挚切直。"}]}, {"meaning": "请求,表露愿望和要求。", "cites": [{"t": "恳恩拯救。", "b": "《广东军务记》"}], "words": [{"w": "恳乞", "t": "请求"}, {"w": "恳央", "t": "恳求"}, {"w": "恳祈", "t": "祈求"}, {"w": "恳告", "t": "恳求。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2131wx','展','1','zhǎn','尸','10','','[{"pinyin": "zhǎn", "defs": [{"meaning": "(形声。小篆字形假卧的人形。从尸,与人体动作有关。本义:转动)。"}, {"meaning": "同本义。", "cites": [{"t": "展,转也。", "b": "《说文》"}, {"t": "展,转,反侧也。", "b": "《广雅》"}, {"t": "展转伏枕。", "b": "《韩诗泽陂》"}, {"t": "忧心展转。", "b": "《楚辞·惜贤》"}, {"t": "展眼已是夏末秋初。", "b": "《红楼梦》"}], "words": [{"w": "展动", "t": "翻动"}, {"w": "展轮", "t": "转轮。多指启程出行"}, {"w": "展思", "t": "展转思念。"}]}, {"meaning": "舒展;伸展。", "cites": [{"t": "侈必展。", "b": "《国语·晋语》"}, {"t": "盗跖大怒,两展其足,案剑瞋目。", "b": "《庄子·盗跖》"}], "words": [{"w": "展放", "t": "舒展"}, {"w": "展眉舒眼", "t": "眼、眉舒展开来。形容称心如意而高兴的样子"}, {"w": "展舒", "t": "舒展"}, {"w": "展怀", "t": "舒怀,开怀。"}]}, {"meaning": "张开;展现或进入视野。", "cites": [{"t": "破笼展翅当远去。", "b": "柳宗元《鹧鸪词》"}], "words": [{"w": "展卷", "t": "展开卷状物"}, {"w": "展目", "t": "犹放眼"}, {"w": "展阅", "t": "展读,观览"}, {"w": "展诵", "t": "开卷诵读"}, {"w": "展拓(开辟,扩充)展见(展现", "t": ""}, {"w": "展陈", "t": "显示、呈现。"}]}, {"meaning": "延长;放宽。", "cites": [{"t": "令冬月益展一月,卒吾事矣。", "b": "《史记·王温鉥列传》"}], "words": [{"w": "展赈", "t": "指延长赈济的日期"}, {"w": "展延", "t": "延展"}, {"w": "展日", "t": "延期。"}]}, {"meaning": "陈述;申述。", "cites": [{"t": "天子非展义不巡守。", "b": "《左传》"}], "words": [{"w": "话已跟大家展直了;展谢", "t": "致谢,陈谢"}, {"w": "展仪", "t": "申其礼仪。"}]}, {"meaning": "施展,发挥。", "cites": [{"t": "儿童惯识呼鸠曲,闾巷曾闻展骥才。(骥:千里马)", "b": "明·罗贯中《全图绣像三国演义》"}], "words": [{"w": "展爪", "t": "施展手段"}, {"w": "展施", "t": "施展发挥。"}]}, {"meaning": "陈列;展览。", "cites": [{"t": "百官之属,各展其物。", "b": "《左传·襄公三十一年》"}, {"t": "展车马。", "b": "《左传·成公十六年》"}, {"t": "敢展谢其不恭。", "b": "《左传·哀公二十年》。注:“展,陈也。”"}, {"t": "贡之机密,展之力用。", "b": "《后汉书·边让传》"}], "words": [{"w": "展品", "t": ""}]}, {"meaning": "省视;视察。", "cites": [{"t": "大祭祀,展牺牲。", "b": "《周礼》"}], "words": [{"w": "展省", "t": "省视、看"}, {"w": "展墓", "t": "省视坟墓。"}]}, {"meaning": "瞻仰。", "cites": [{"t": "展先人之墓,宁祖母于堂。", "b": "宋·王安石《上徐兵部书》"}], "words": [{"w": "展拜", "t": "拜谒,行跪拜之礼"}, {"w": "展奉", "t": "敬辞。看望侍奉"}, {"w": "展脚伸腰", "t": "下拜"}, {"w": "展敬", "t": "祭拜;省侯致敬。"}]}, {"meaning": "演奏。", "cites": [{"t": "引江总以下,展乐赋诗。", "b": "《陈书》"}]}, {"meaning": "又如:展乐(奏乐);展玩(玩赏)。"}, {"meaning": "揩抹。", "cites": [{"t": "将宝瓶抬出,放在三层门外,展得干净。", "b": "《西游记》"}]}, {"meaning": "又如:展灰(抹去灰尘)。"}, {"meaning": "诚实。", "cites": [{"t": "展矣君子。", "b": "《诗·邶风·雄雉》"}]}, {"meaning": "诚然;确实。", "cites": [{"t": "諓如之人兮,邦之媛也。(真像这个人啊,才是一国的女人呢。)", "b": "《诗·慵风·君子偕老》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2132wx','剧','1','jù','刂','10','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。本义:甚;厉害,严重)。"}, {"meaning": "同本义。", "cites": [{"t": "剧,甚也。", "b": "《文选》注引《说文》。朱骏声曰:“即勮字之误文。”"}, {"t": "何其剧欤。", "b": "《剧秦美新》"}, {"t": "口吃不能剧谈。", "b": "《汉书·扬雄传》"}, {"t": "即疾剧,留屯毋行。", "b": "《汉书·赵充国传》"}, {"t": "不以梦剧乱知谓之静。", "b": "《荀子·解蔽》"}]}, {"meaning": "繁多;繁忙。", "cites": [{"t": "犹然而材剧志大。", "b": "《荀子·非十二子》。注:“繁多也。”"}, {"t": "事剧而功寡。", "b": "《商君书·算地》"}], "words": [{"w": "剧月", "t": "农忙之月"}, {"w": "剧繁", "t": "繁忙的事物"}, {"w": "剧烦", "t": "繁剧。亦指繁杂的事物"}, {"w": "剧事", "t": "艰巨,繁杂的事务"}, {"w": "剧地", "t": "繁杂难治之地。"}]}, {"meaning": "艰难。", "cites": [{"t": "执务私事,不辞剧易。", "b": "范晔《后汉书》"}], "words": [{"w": "剧地", "t": "形势险要之地"}, {"w": "剧口", "t": "讲述烦难"}, {"w": "剧易", "t": "艰难"}, {"w": "剧韵", "t": "险韵。"}]}, {"meaning": "巨,大。", "cites": [{"t": "材剧志大,闻见杂博。", "b": "《荀子·十二子》"}], "words": [{"w": "剧贼", "t": "大盗;强贼"}, {"w": "剧寇", "t": "剧贼"}, {"w": "剧恶", "t": "大恶"}, {"w": "剧虏", "t": "势力强大的敌寇。"}]}, {"meaning": "急促;疾速。", "cites": [{"t": "二世而亡,何其剧与?", "b": "扬雄《剧秦美新》"}], "words": [{"w": "剧气", "t": "气喘,呼吸急促"}, {"w": "剧然", "t": "突然,猛然"}, {"w": "剧读", "t": "疾读,流畅的朗读。"}]}, {"meaning": "戏耍。", "cites": [{"t": "妾发初覆额,折花门前剧。", "b": "李白《长干行》"}]}, {"meaning": "古县名 。故址在今山东省寿光县东南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2133wx','屑','1','xiè','尸','10','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从尸,肖声。本义:碎末) 同本义。", "cites": [{"t": "时造船,木屑及竹头悉令举掌之。", "b": "《晋书·陶侃传》"}], "words": [{"w": "米屑;屑涕", "t": "屑泣。谓涕泪纷纷下落"}, {"w": "屑候", "t": "杂有姜桂碎末的干粮。"}]}, {"meaning": "研成碎末。", "cites": [{"t": "客至,屑槟榔、龙脑、香蛤以进。", "b": "《新唐书》"}], "words": [{"w": "屑玉", "t": "碾碎玉石。多指仙家屑玉为食"}, {"w": "屑没", "t": "破碎沉没"}, {"w": "屑骨", "t": "犹言粉身碎骨。"}]}, {"meaning": "顾惜;介意。", "cites": [{"t": "天屑临文王慈,是以老而无子者,有所得终其寿。", "b": "《墨子》"}], "words": [{"w": "屑意", "t": "介意,放在心上"}, {"w": "屑临", "t": "顾视"}, {"w": "屑怀", "t": "介意。"}]}, {"meaning": "常用否定式,不屑,即不惜顾一眼。", "cites": [{"t": "不屑毁誉。", "b": "《后汉书》"}]}, {"meaning": "用拳头击打。", "cites": [{"t": "皇甫殿直掿得拳头没缝,去顶门上屑那厮一椷。", "b": "《清平山堂话本》"}], "words": [{"w": "屑一暴", "t": "凿击一拳。"}]}, {"meaning": "不安。", "cites": [{"t": "不唯迁客须怬屑,见说居人也寂寥。", "b": "唐·白居易《送人贬信州判官》"}]}, {"meaning": "轻忽的。", "cites": [{"t": "尔乃不大宅天命,尔乃屑播天命。", "b": "《书·多方》"}], "words": [{"w": "屑如", "t": "倏忽的样子。"}]}, {"meaning": "清洁,整洁。", "cites": [{"t": "宴尔新昏,不我屑以。", "b": "《诗·邶风·谷风》"}, {"t": "乞人不屑也(屑,洁,引申为值得)。", "b": "《孟子·告子上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2134wx','弱','1','ruò','弓','10','','[{"pinyin": "ruò", "defs": [{"meaning": "(会意。小篆字形,两把弯曲的弓,“彡”(shān)象毛羽之形,合起来表示柔弱。本义:气力小;势力差)。"}, {"meaning": "同本义。与“强”相对。", "cites": [{"t": "弱,桡也。上象桡曲,彡象毛氂桡弱也。", "b": "《说文》"}, {"t": "栋桡,本末弱也。", "b": "《易·大过》"}, {"t": "颉遇王子弱焉。", "b": "《左传·襄公二十六年》"}, {"t": "志弱而事强。", "b": "《淮南子·原道》"}, {"t": "辅隙者则国必弱。", "b": "《孙子·谋攻》"}, {"t": "众散为弱。", "b": "《左传·哀公十年》"}, {"t": "有土者不可以言贫,有民者不可以言弱。", "b": "《商君书·错法》"}, {"t": "两争曰弱。", "b": "《周书·武顺》"}, {"t": "然操能克绍,以弱为强者,非惟天时,抑亦人谋也。", "b": "陈寿《隆中对》"}, {"t": "弱者道之用。", "b": "《老子》"}, {"t": "弱湍驰文舫,闲谷矫鸣鸥。", "b": "陶潜《游斜川》"}], "words": [{"w": "弱植", "t": "软弱无能,无法扶植"}, {"w": "弱道", "t": "道家语。柔弱之道"}, {"w": "弱人", "t": "势弱之人"}, {"w": "弱湍", "t": "舒缓的流水"}, {"w": "弱力", "t": "力量单薄;能力不强的人"}, {"w": "弱才", "t": "才能平庸低下"}, {"w": "弱孤", "t": "力孤力弱"}, {"w": "弱门", "t": "胆小之人。"}]}, {"meaning": "纤柔;软弱。", "cites": [{"t": "苗其弱也欲孤。", "b": "《吕氏春秋·辨士》"}, {"t": "弱柳青槐拂地垂。", "b": "唐·卢照邻《长安古意》"}], "words": [{"w": "弱约", "t": "柔弱美好"}, {"w": "弱骨", "t": "骨柔软;伶仃瘦骨"}, {"w": "弱劣", "t": "软弱无力"}, {"w": "弱愿", "t": "柔顺善良"}, {"w": "弱蒂", "t": "细弱的叶柄或花蒂"}, {"w": "弱腕", "t": "微细的手腕"}, {"w": "弱藻", "t": "柔弱的水草。"}]}, {"meaning": "虚弱;瘦弱。", "cites": [{"t": "小人弱息,当得一子。", "b": "《南史·周盘龙传》"}, {"t": "你妹妹远路才来,身子又弱。", "b": "《红楼梦》"}], "words": [{"w": "弱甲", "t": "老弱之兵"}, {"w": "弱疾", "t": "身体瘦弱的疾病"}, {"w": "弱息", "t": "柔弱的女子。"}]}, {"meaning": "年幼,年少。", "cites": [{"t": "汝心之固,固不可彻,曾不若孀妻弱子。", "b": "《列子·汤问》"}], "words": [{"w": "弱笄", "t": "未成年的少女"}, {"w": "弱丧", "t": "年少时丧失故居"}, {"w": "弱岁", "t": "少年,弱冠的年龄"}, {"w": "弱年", "t": "幼年"}, {"w": "弱口", "t": "人口中之幼小者"}, {"w": "弱年", "t": "年少;弱冠之年"}, {"w": "弱辰", "t": "幼年"}, {"w": "弱弟", "t": "幼弟。"}]}, {"meaning": "不足,略少。", "cites": [{"t": "黄道日之所行也,…与赤道交于角五少弱。", "b": "《晋书》"}]}, {"meaning": "坏。", "cites": [{"t": "有些儿好弱,你根柢不舍!", "b": "《西厢记诸宫调》"}]}, {"meaning": "衰败。", "cites": [{"t": "姜族弱矣,而妫将始昌。", "b": "《左传·昭公三年》"}]}, {"meaning": "丧失。", "cites": [{"t": "又弱一个焉,姜其危哉!", "b": "《左传》"}]}, {"meaning": "减少。", "cites": [{"t": "不弱兵,欲攻齐。", "b": "《战国策》"}]}, {"meaning": "削弱。", "cites": [{"t": "专祸楚国,弱寡王室。", "b": "《左传·昭公二十七年》"}, {"t": "诸侯恐惧,会盟而谋弱秦。", "b": "汉·贾谊《过秦论上》"}], "words": [{"w": "弱寡", "t": "削弱孤立"}, {"w": "弱敌", "t": "削弱敌人。"}]}, {"meaning": "侵害。", "cites": [{"t": "鲁为齐弱久矣。", "b": "宋·苏轼《论孔子》"}]}, {"meaning": "败。", "cites": [{"t": "战而不胜,则国亡兵弱,身死名息。", "b": "《韩非子》"}]}, {"meaning": "惧怕。", "cites": [{"t": "别人弱他官府,我却不弱他。", "b": "《古今小说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2135wx','陵','1','líng','阝','10','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从阜(fù),表示与地形地势的高低上下有关。夌(líng)声。本义:大土山)。"}, {"meaning": "同本义。", "cites": [{"t": "陵,大阜也。", "b": "说文》"}, {"t": "如山如阜,如冈如陵。", "b": "《诗·小雅·天保》"}, {"t": "殽有二陵焉。", "b": "《左传·僖公三十二年》"}, {"t": "陵阜陆墐。", "b": "《国语·齐语》"}, {"t": "鸿渐于陵。", "b": "《易·渐卦》"}, {"t": "古陵蔚起。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "循陵而走。", "b": ""}], "words": [{"w": "陵谷", "t": "山岭和深谷"}, {"w": "陵谷变迁", "t": "高山深谷变换位置。比喻世事变化"}, {"w": "陵丘", "t": "后高前低平的大丘"}, {"w": "陵居", "t": "居住在高陵地区"}, {"w": "陵隰", "t": "山陵和低湿之地"}, {"w": "陵阿", "t": "山陵"}, {"w": "陵衍", "t": "高而广的丘陵地。"}]}, {"meaning": "引申指帝王陵墓。", "cites": [{"t": "乐游原上望昭陵。", "b": "杜牧《将赴吴兴登乐游原》"}, {"t": "乃强起扶杖,执图诣寺后,有古陵蔚起。", "b": "《聊斋志异·促织》"}, {"t": "举一滴可包陵谷。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "其南陵,其北陵;陵屋", "t": "帝王墓地的建筑"}, {"w": "陵田", "t": "陵墓旁的田地"}, {"w": "陵表", "t": "墓碑;墓表"}, {"w": "陵户", "t": "看守帝王陵墓的人"}, {"w": "陵寝;陵庙", "t": ""}]}, {"meaning": "山,山头。", "cites": [{"t": "故用兵之法,高陵勿向。", "b": "《孙子·军争》"}, {"t": "山无陵,江水为竭。", "b": "《乐府诗集·鼓吹曲辞一》"}]}, {"meaning": "升,登。", "cites": [{"t": "陵重巘。", "b": "张衡《西京赋》"}], "words": [{"w": "陵云", "t": "升上云霄。比喻超尘绝俗或神仙的境界"}, {"w": "陵霄", "t": "升上云霄。比喻志气高远。通凌云。"}]}, {"meaning": "超越,逾越。", "cites": [{"t": "陵水经地。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "陵忽", "t": "超越;欺侮"}, {"w": "陵架", "t": "超越其上"}, {"w": "陵越", "t": "超越。也作凌越"}, {"w": "凌迈", "t": "超越。"}]}, {"meaning": "欺侮;欺压。", "cites": [{"t": "在上位,不陵下。", "b": "《礼记》"}, {"t": "为巡缴所陵。", "b": "宋·文天祥《指南录·后序》"}, {"t": "见陵之耻。", "b": "《战国策·燕策》"}, {"t": "修成子仲骄恣陵折,吏民皆患苦之。", "b": "《加急记·外戚世家》"}], "words": [{"w": "陵折", "t": "欺压,折辱"}, {"w": "陵虐", "t": "欺侮虐待。也作凌虐"}, {"w": "陵侮", "t": "欺侮。"}]}, {"meaning": "日渐衰微。", "cites": [{"t": "帝王之道,日以陵夷。", "b": "《汉书·成帝纪》"}], "words": [{"w": "陵夷", "t": "渐次衰颓。同陵迟"}, {"w": "陵弛", "t": "渐次衰颓、废弛。"}]}, {"meaning": "凌驾。", "cites": [{"t": "(宁成)好气,为人小吏,必陵其长吏。", "b": "《史记·酷吏列传》"}], "words": [{"w": "凌架", "t": "凌驾"}, {"w": "陵跨", "t": "跨越;凌驾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2136wx','祟','1','suì','示','10','','[{"pinyin": "suì", "defs": [{"meaning": "(会意。从示,从出。示,与鬼神有关。表示鬼魅出来作怪。本义:鬼神制造的灾祸) 同本义。", "cites": [{"t": "寡人不祥,被于宗宙之祟,沉于谄谀之臣,开罪于君,", "b": "《战国策·齐策》"}], "words": [{"w": "祸祟", "t": "灾祸"}, {"w": "祟书", "t": "迷信者认为,人害病是鬼神作祟,而且鬼神何日何时作祟,可在书上查出,此书称为“祟书”"}, {"w": "祟恶", "t": "指鬼神所作祸害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2137wx','陶','1','táo yáo','阝','10','','[{"pinyin": "táo", "defs": [{"meaning": "(形声。从阜,匋(táo)声,阜,土山。从“阜”,与土有关。本义:陶丘)。"}, {"meaning": "同本义。本为两重的山丘,后为地名专称。在今山东省定陶县。因陶丘在定陶,故定陶亦省称陶。", "cites": [{"t": "陶,再成丘也。", "b": "《说文》"}, {"t": "再成为陶丘。", "b": "《尔雅》。孙注:“形如累两盆。”"}, {"t": "陶丘于高山上一重作之,如陶灶也。", "b": "《释名》"}, {"t": "在济阴,《夏书》曰,东至于陶丘北,陶丘有尧城,尧尝所居,故尧号陶唐氏。", "b": "《说文》"}], "words": [{"w": "陶丘", "t": "重叠的山丘。"}]}, {"meaning": "瓦器,陶器。", "cites": [{"t": "器用陶匏。", "b": "《礼记·郊特牲》"}, {"t": "陶器必良火齐必得。", "b": "《吕氏春秋·仲冬纪》"}, {"t": "以粟易械器者,不为厉陶治。", "b": "《孟子·滕文公上》。朱注:“陶,为甑者;冶,为釜铁者。”"}], "words": [{"w": "彩陶", "t": "带有彩绘花纹的陶器"}, {"w": "白陶", "t": "殷代用高岭土烧成的白色陶器"}, {"w": "陶甓", "t": "陶砖"}, {"w": "陶桴", "t": "陶瓦与木棍。"}]}, {"meaning": "制作瓦器。", "cites": [{"t": "陶,作瓦器也。", "b": "《玉篇》"}, {"t": "陶子河滨。", "b": "《吕氏春秋·慎人》"}, {"t": "譬若陶人之埏埴。", "b": "《淮南子·精神》"}, {"t": "万室之国,一人陶。", "b": "《孟子·告子下》"}], "words": [{"w": "陶渔", "t": "制陶与捕鱼"}, {"w": "陶钧", "t": "制陶用的转轮"}, {"w": "陶埴", "t": "烧制砖瓦"}, {"w": "陶俑", "t": "古代陪葬用的陶制偶人"}, {"w": "陶人", "t": "陶工,陶师,陶家。烧制陶器的匠人。"}]}, {"meaning": "陶冶,化育。", "cites": [{"t": "文王能陶冶天下之士。", "b": "王安石《上仁宗皇帝言事书》"}, {"t": "延师择友,陶成佳士。", "b": "范景文《贺王甥申之首入泮宫序》"}], "words": [{"w": "陶熔", "t": "培养教育"}, {"w": "陶成", "t": "培养,教晦"}, {"w": "陶写", "t": "抒发,陶冶"}, {"w": "陶化", "t": "陶铸化育"}, {"w": "陶育", "t": "造就化育。"}]}, {"meaning": "烤灼,炎炽。", "cites": [{"t": "跻日中于昆吾兮,憩炎天之所陶。", "b": "《后汉书》"}]}, {"meaning": "快乐。", "cites": [{"t": "共陶暮春时。", "b": "《文选·谢灵运·酬从弟惠连》"}, {"t": "何以称这情,浊酒且自陶。", "b": "陶渊明《己酉岁九月九日》"}], "words": [{"w": "陶春", "t": "使人快乐的春天"}, {"w": "陶欣", "t": "快乐欣喜"}, {"w": "陶煦", "t": "和乐的样子。"}]}, {"meaning": "姓。"}]}, {"pinyin": "yáo", "defs": [{"meaning": "窑灶。", "cites": [{"t": "《集训》:“陶,烧瓦器土室也。”", "b": "《一切经音义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2138wx','陷','1','xiàn','阝','10','','[{"pinyin": "xiàn", "defs": [{"meaning": "(会意兼形声。从阜(fù);从臽,臽(xiān)亦声。据金文,象人掉进陷阱形。本义:坠入,掉进)。"}, {"meaning": "同本义。", "cites": [{"t": "陷,高下也。一曰陊也。", "b": "《说文》"}, {"t": "不可陷也。", "b": "《论语》。孔注:“下也。”"}, {"t": "上陷而不振。", "b": "《国语·鲁语》。注:“坠也。”"}, {"t": "一拥而入,人马俱陷。", "b": "《三国志通俗演义》"}], "words": [{"w": "陷狱", "t": "入狱"}, {"w": "沉陷", "t": "地面陷下去。"}]}, {"meaning": "陷溺,淹没。", "cites": [{"t": "陷没而死。", "b": "宋·文天祥《 后序》"}], "words": [{"w": "陷溺", "t": ""}]}, {"meaning": "陷害。", "cites": [{"t": "三长史皆害汤(张汤),欲陷之。", "b": "《史记》"}], "words": [{"w": "诬陷", "t": "诬告陷害"}, {"w": "陷灭", "t": "陷害诛灭。"}]}, {"meaning": "攻破。", "cites": [{"t": "[灌孟] 战常陷坚。", "b": "《史记》"}], "words": [{"w": "陷敌", "t": "陷队。冲入敌阵"}, {"w": "陷坚", "t": "攻破敌军坚强的阵地。同陷锐。"}]}, {"meaning": "陷入,落在不利的境地。", "cites": [{"t": "身虽陷败,彼观其意,且欲得其当而报于汉。", "b": "汉·司马迁《报任少卿书》"}], "words": [{"w": "陷败", "t": "遭到失败"}, {"w": "陷误", "t": "陷入误区"}, {"w": "陷身", "t": "身陷泥坑、火坑。"}]}, {"meaning": "陷阱 。诱捕猎物或诱杀动物用的坑。", "cites": [{"t": "鱼可使之吞钩,虎可使之入陷。", "b": "《齐丘子》"}], "words": [{"w": "陷车", "t": "古时押解犯人的囚车。"}]}, {"meaning": "缺点;过失。", "cites": [{"t": "陷而入于恭。", "b": "《国语》"}], "words": [{"w": "缺陷", "t": "欠缺或不够完善的地方。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2139wx','陪','1','péi','阝','10','','[{"pinyin": "péi", "defs": [{"meaning": "(形声。从阜(fù),咅(pǒu)声。左耳旁为“阜”的变形。阜,土山。本义:重叠的土堆)。"}, {"meaning": "同本义。", "cites": [{"t": "陪,重土也。", "b": "《说文》。朱骏声通训:“按,重阜也,所谓再成邱也。”"}, {"t": "分之土田陪敦,陪犹山也。", "b": "《左传·定公四年》。注:“增也。”"}]}, {"meaning": "辅佐之臣,公卿之臣。", "cites": [{"t": "陪臣也。", "b": "《广雅》"}], "words": [{"w": "陪贰", "t": "副手,助手"}, {"w": "陪推", "t": "以推官出任主考官的副官。"}]}, {"meaning": "伴随,陪伴。", "cites": [{"t": "以无陪无卿。", "b": "《诗·大雅·荡》。传:“无陪贰也。”"}, {"t": "自称曰陪臣某。", "b": "《礼记·曲礼》。注:“重也。”"}, {"t": "陪臣敢辞。", "b": "《左传·僖公十二年》。注:“重也。诸侯之臣于天子故曰陪臣。”"}, {"t": "士有陪乘。", "b": "《国语·鲁语》。注:“犹重也。”"}, {"t": "行则陪乘。", "b": "《周礼·齐右》"}], "words": [{"w": "奉陪", "t": "敬辞,陪伴"}, {"w": "陪位", "t": "在席位上奉陪"}, {"w": "陪京", "t": "陪侍京都,陪都"}, {"w": "陪乘", "t": "伴随主车的车子"}, {"w": "陪床的", "t": "陪房,随嫁仆婢"}, {"w": "陪花", "t": "陪酒女郎"}, {"w": "陪奉", "t": "陪同侍奉。"}]}, {"meaning": "增加。", "cites": [{"t": "飱有陪鼎。", "b": "《左传·昭公五年》。注:“陪,加也。”"}], "words": [{"w": "陪敦", "t": "增厚"}, {"w": "陪鼎", "t": "增加的食鼎。鼎,古代用来盛食物的器具。"}]}, {"meaning": "辅佐;帮助。", "cites": [{"t": "秉德以陪朕。", "b": "《汉书·文帝纪》"}], "words": [{"w": "陪堂", "t": "帮闲,帮人做事的食客。"}]}, {"meaning": "赔偿,偿还。", "cites": [{"t": "在放牧处相觝,请陪半价。", "b": "唐·白居易《判题》"}], "words": [{"w": "陪告", "t": "赔话,解释说明。"}]}, {"meaning": "违背。", "cites": [{"t": "尔德不明,以无陪无侧。", "b": "《韩诗外传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2140wx','娱','1','yú','女','10','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从女,吴声。本义:快乐,欢娱) 同本义。", "cites": [{"t": "娱,乐也。", "b": "《说文》。经传多以虞为之。"}, {"t": "夏康娱以自纵。", "b": "《楚辞·离骚》"}, {"t": "穷身极娱。", "b": "张衡《西京赋》"}, {"t": "诸侯不娱。", "b": "《周书·程典》"}, {"t": "朝野多欢娱。", "b": "张景阳《咏史诗》"}], "words": [{"w": "娱娱", "t": "喜乐的样子"}, {"w": "娱快", "t": "欢快,愉快"}, {"w": "娱玩", "t": "玩乐"}, {"w": "娱放", "t": "娱恣,纵情欢乐"}, {"w": "娱笑", "t": "欢笑和悦"}, {"w": "娱嬉", "t": "戏乐"}, {"w": "娱戏", "t": "娱乐游戏。"}]}, {"meaning": "戏乐,使欢乐。", "cites": [{"t": "羌声色兮娱人。", "b": "《楚辞·九歌·东君》"}, {"t": "设张辟以娱君兮。", "b": "《楚辞·九章·惜诵》"}, {"t": "以相娱乐。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "无所娱遣。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "娱神悦目", "t": "欣赏美好景物,使精神愉快"}, {"w": "娱老", "t": "娱悦地欢度晚年"}, {"w": "娱志", "t": "娱悦心志"}, {"w": "娱亲", "t": "使父母欢乐"}, {"w": "娱妻弄子", "t": "和妻子儿女玩乐。"}]}, {"meaning": "排遣,抒发。", "cites": [{"t": "遵江夏以娱忧。", "b": "《楚辞》"}], "words": [{"w": "娱哀", "t": "排遣哀伤"}, {"w": "娱悲", "t": "排遣悲伤"}, {"w": "娱忧", "t": "排遣忧愁"}, {"w": "娱志", "t": "寄托高尚的志向"}, {"w": "娱喜", "t": "消遣嬉戏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2141wx','娟','1','juān','女','10','','[{"pinyin": "juān", "defs": [{"meaning": "(形声。从女,肙(yuān)声。本义:美好,多指姿态美)。"}, {"meaning": "同本义。", "cites": [{"t": "娟然如拭。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "娟好", "t": "秀丽"}, {"w": "娟丽", "t": "秀丽"}, {"w": "娟洁", "t": "秀丽,清雅"}, {"w": "娟魄", "t": "月亮的别名"}, {"w": "娟妩", "t": "清秀妩媚。"}]}, {"meaning": "姿态柔美的。", "cites": [{"t": "美人娟娟隔秋水,濯足洞庭望八荒。", "b": "唐·杜甫《寄韩谏议注》"}, {"t": "遇一二八女郎,姿致娟娟,顾之微笑,似将有言。", "b": "《聊斋志异》"}]}, {"meaning": "长曲的样子。", "cites": [{"t": "始出西南楼,纤纤如玉钩。未映东北墀,娟娟似娥眉。", "b": "鲍照诗"}]}, {"meaning": "明媚貌。", "cites": [{"t": "月光娟娟,照见众齿。", "b": "鲁迅《集外集拾遗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2142wx','恕','1','shù','心','10','','[{"pinyin": "shù", "defs": [{"meaning": "(形声。从心,如声。本义:恕道,体谅) 同本义。", "cites": [{"t": "恕,仁也。", "b": "《说文》"}, {"t": "彊恕而行,求仁莫近焉。", "b": "《孟子》"}, {"t": "以心度物曰恕。", "b": "《声类》"}, {"t": "以己量人谓之恕。", "b": "《贾子道术》"}, {"t": "恕,明也。", "b": "《墨子经上》"}, {"t": "忠恕违道不远。", "b": "《礼记·中庸》。注:“恕,忖也。忖度其义于人。”"}, {"t": "子贡问曰:“有一言而可以终身行之者乎?”子曰:“其恕乎!己所不欲,勿施于人。”", "b": "《论语·卫灵公》"}], "words": [{"w": "恕直", "t": "宽仁正直"}, {"w": "恕心", "t": "仁爱之心"}, {"w": "恕实", "t": "忠实,老实"}, {"w": "恕道", "t": "宽仁之道。"}]}, {"meaning": "饶恕,宽恕。", "cites": [{"t": "老臣病足,曾不能疾走,不得见久矣,窃自恕而恐太后玉体之有所郄也,故愿望见太后。", "b": "《战国策·赵策》"}, {"t": "故今具道所以,冀君实或见恕也。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "恕谅", "t": "宽谅,原谅"}, {"w": "恕免", "t": "饶恕;宽免"}, {"w": "恕辞", "t": "开脱或原谅的言辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2143wx','娥','1','é','女','10','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从女,我声。本义:女子容貌美好。常“娥媌”、“娥娥”、“娥姣”等连用,形容女子美貌) 同本义。", "cites": [{"t": "娥媌靡曼者。", "b": "《列子·周穆王》。注:“妖好也。”"}], "words": [{"w": "娥姣", "t": "容貌美好"}, {"w": "娥苗", "t": "妖艳美好。"}]}, {"meaning": "传说中尧女舜妻的字。", "cites": [{"t": "娥,帝尧之女舜妻娥皇字也。秦晋谓好曰姪娥。", "b": "《说文》"}], "words": [{"w": "娥皇女英", "t": "相传是尧的两个女儿,同嫁给虞舜为妃。后舜出巡时死于苍梧之野,她二人奔丧到南方,投湘水而死。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2144wx','娘','1','niáng','女','10','','[{"pinyin": "niáng", "defs": [{"meaning": "(形声。从女,良声。本义:对妇女的泛称,多指少女)。"}, {"meaning": "同本义。", "cites": [{"t": "见娘喜容媚,愿得结金兰。", "b": "古乐府《子夜歌》"}], "words": [{"w": "渔娘;厨娘;婆娘;老板娘;娘行", "t": "女性通称"}, {"w": "娘们", "t": "女人"}, {"w": "娘娘庙", "t": "俗谓送子女神之庙"}, {"w": "娘子关", "t": "一称苇泽关。在山西省平定县东北,河北省井陉县西。相传唐平阳公主率军驻此"}, {"w": "新娘;姑娘", "t": ""}]}, {"meaning": "又。", "cites": [{"t": "爷娘唤女。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "爷娘闻女来。", "b": ""}, {"t": "耶娘妻子走相送。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "我出生时我娘死了;爹娘;娘母", "t": "母亲"}, {"w": "娘母子", "t": "母亲。"}]}, {"meaning": "奴婢对女主人也称娘。", "cites": [{"t": "那秋菊拾着鞋儿道:“娘这个鞋,只好盛我一个脚指头儿罢。”", "b": "《金瓶梅词话》"}]}, {"meaning": "称长一辈或年长的已婚妇女。", "cites": [{"t": "娘以指叩门。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "娘妗", "t": "舅母"}, {"w": "大娘;婶娘;姨娘", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2145wx','通','1','tōng tòng','辶','10','','[{"pinyin": "tōng", "defs": [{"meaning": "(形声。从辵(chuò),甬(yǒng)声。本义:没有堵塞,可以通过)。"}, {"meaning": "同本义。", "cites": [{"t": "通,达也。", "b": "《说文》"}, {"t": "往来不穷谓之通。", "b": "《易·系辞》"}, {"t": "推而行之谓之通。", "b": ""}, {"t": "坎为通。", "b": "《易·说卦》"}, {"t": "道远难通。", "b": "《国语·晋语》。注:“至也。”"}, {"t": "血脉欲其通也。", "b": "《吕氏春秋·达郁》。注:“利也。”"}, {"t": "凝绝不通声暂歇。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "中通外直。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "通衢大道", "t": "四通八达的大道,指交通要道"}, {"w": "通漕", "t": "直通水运"}, {"w": "通塞", "t": "指境遇的顺利与滞涩"}, {"w": "通水", "t": "通水运;能行船的地域"}, {"w": "通畅", "t": "通行无阻的"}, {"w": "通川", "t": "有河川流通的地方"}, {"w": "通邑", "t": "四通八达的城市。"}]}, {"meaning": "通往。", "cites": [{"t": "指通豫南。", "b": "《列子·汤问》"}, {"t": "道不通。", "b": "《史记·陈涉世家》"}, {"t": "才通人。", "b": "晋·陶渊明《桃花源记》"}, {"t": "北通巫峡。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "通天", "t": "通往天界。后用以形容本能非凡"}, {"w": "通吊", "t": "至丧家吊唁。"}]}, {"meaning": "传递;传达。", "cites": [{"t": "主簿通语言。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "通其意。", "b": "汉·贾谊《过秦论》"}, {"t": "信耗莫通。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "通状", "t": "申递各级官厅的上行公文"}, {"w": "通信;通消息;通辞", "t": "呈递书面意见;传达话语"}, {"w": "通化", "t": "传达教化"}, {"w": "通书", "t": "通信"}, {"w": "通问", "t": "互相致意问候;互通信息。"}]}, {"meaning": "沟通;接通。", "cites": [{"t": "阡陌交通。", "b": "晋·陶渊明《桃花源记》"}, {"t": "旁推交通。", "b": "唐·柳宗元《柳河东集》"}, {"t": "始能少通。", "b": "清·梁启超《谭嗣同传》"}, {"t": "通流入海。", "b": "清·张廷玉《明史》"}], "words": [{"w": "通同造意", "t": "串通谋划"}, {"w": "通脚", "t": "跑腿说合"}, {"w": "通灵", "t": "与神灵相通"}, {"w": "通房连阁;通源", "t": "源头相通"}, {"w": "通属", "t": "连接"}, {"w": "通同", "t": "串通,勾结。"}]}, {"meaning": "往来友好。", "cites": [{"t": "数通使相窥观。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "通家至契", "t": "世代有交情的好友"}, {"w": "通谱", "t": "同姓的人互认为同族"}, {"w": "通正", "t": "和畅平正"}, {"w": "通关", "t": "交往联系"}, {"w": "通欢", "t": "往来交好"}, {"w": "通交", "t": "结交;交往。"}]}, {"meaning": "了解;精通。", "cites": [{"t": "因入京师,观太学,遂通五经。", "b": "《后汉书·张衡传》"}, {"t": "子厚少精敏,无不通达。", "b": "韩愈《柳子厚墓志铭》"}, {"t": "不能通其意。", "b": "唐·韩愈《杂说》"}, {"t": "诸母皆通文。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "通玄", "t": "通晓深奥的道理"}, {"w": "通方", "t": "通达道术"}, {"w": "通心", "t": "内心通达"}, {"w": "通明", "t": "洞晓事物的道理"}, {"w": "通幽", "t": "通晓幽深的道理"}, {"w": "通悟", "t": "洞达事理,而具有高度的领悟力。"}]}, {"meaning": "通报;说 。", "words": [{"w": "通报", "t": "通知禀报"}, {"w": "互通姓名;通志", "t": "表达意趣志向"}, {"w": "通呈", "t": "通报呈递。"}]}, {"meaning": "疏通;开通。", "cites": [{"t": "疏之欲其通。", "b": "唐·柳宗元《柳河东集》"}, {"t": "政通人和。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "通路", "t": "开通道路"}, {"w": "用泻药通便;通急", "t": "排解急难"}, {"w": "通堙", "t": "开浚堵塞的水道"}, {"w": "通沟", "t": "疏通沟渠"}, {"w": "通瘀", "t": "疏通瘀滞。"}]}, {"meaning": "流通,互相交换。", "cites": [{"t": "商而通之。", "b": "《史记·货殖列传》"}, {"t": "通鱼盐。", "b": ""}], "words": [{"w": "通关节", "t": "暗中行贿、勾通官吏"}, {"w": "通刺", "t": "通报名刺;交往。"}]}, {"meaning": "陈述 。"}, {"meaning": "如:通款(向敌方表示愿意降服);通诚(在神前表白诚意)。"}, {"meaning": "通奸,过非婚性生活 。"}, {"meaning": "如:与人有通。"}, {"meaning": "调和。", "cites": [{"t": "以通八风。", "b": "吕氏春秋·慎行论》"}]}, {"meaning": "整个,全部。", "cites": [{"t": "皆通习之。", "b": "唐·韩愈《师说》"}], "words": [{"w": "通班马步快", "t": "全体骑马、步行的捕快"}, {"w": "通悉", "t": "都知道;全部了解"}, {"w": "通国", "t": "全国,整个国家"}, {"w": "通般", "t": "全部,全面"}, {"w": "通检", "t": "全部检查"}, {"w": "通览", "t": "遍观。"}]}, {"meaning": "博识。", "cites": [{"t": "博览古今者为通人。", "b": "《论衡·超奇》"}], "words": [{"w": "通品", "t": "博学多识、才能出众的人"}, {"w": "通士", "t": "学识丰富而通达事理的读书人"}, {"w": "通雅", "t": "博识多才,品格雅正。"}]}, {"meaning": "总共 。", "words": [{"w": "通共", "t": "总计"}, {"w": "通计", "t": "总计"}, {"w": "通纽", "t": "总合,合在一起"}, {"w": "通址", "t": "合计;总共。"}]}, {"meaning": "共同 。", "words": [{"w": "通财", "t": "共享财物"}, {"w": "通性", "t": "一般人所共有的性质"}, {"w": "通同", "t": "共同"}, {"w": "通谋", "t": "共同合谋。"}]}, {"meaning": "透彻 。", "words": [{"w": "通平", "t": "通畅平正"}, {"w": "通妥", "t": "通顺妥帖"}, {"w": "通快", "t": "通畅快捷。"}]}, {"meaning": "在某一方面,技术高超、有独创性或聪明灵巧的人 。", "words": [{"w": "通方", "t": "通晓为政之道"}, {"w": "万事通;日本通;中国通;美国通", "t": ""}]}, {"meaning": "古州名。"}, {"meaning": "西魏设。在今四川达县。"}, {"meaning": "五代周置,在今江苏省南通县。"}, {"meaning": "金置。在今北京市通县。"}, {"meaning": "乐器名。", "cites": [{"t": "又立为四器,名之为通。通受声广九寸,宣声长九尺,临岳高一寸二分。", "b": "《隋书》"}]}, {"meaning": "古代土地面积单位 。十井为通。", "cites": [{"t": "地方一里为井,井十为通。", "b": "《汉书》"}]}, {"meaning": "药名。马粪。"}, {"meaning": "遍;次 。", "words": [{"w": "说了一通", "t": ""}]}, {"meaning": "用于文书电报。", "words": [{"w": "一通电报", "t": ""}]}, {"meaning": "很;十分 。", "words": [{"w": "通圆", "t": "十分圆满"}, {"w": "通黄", "t": "很黄。"}]}, {"meaning": "总是。", "cites": [{"t": "心邱听着这些话,只微微的笑,通不言语。", "b": "《花月痕》"}]}]}, {"pinyin": "tòng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2146wx','能','1','néng','月','10','','[{"pinyin": "néng", "defs": [{"meaning": "(象形。金文作字形象熊形。本义:熊)。"}, {"meaning": "传说中的一种像熊的兽。", "cites": [{"t": "能,熊属。足似鹿。", "b": "《说文》"}, {"t": "梦黄能入于寝门。", "b": "《左传·昭公七年》。贾注:“兽也。”"}, {"t": "近者三奸悉破碎,羽窟无底幽黄能。", "b": "唐·韩愈《忆昨行和张十一》"}]}, {"meaning": "才能,能力。", "cites": [{"t": "各奏尔能。", "b": "《诗·小雅·宾之初筵》"}, {"t": "无异能者。", "b": "唐·柳宗元《三戒》"}, {"t": "募有能捕之者。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "有千里之能。", "b": "唐·韩愈《杂说》"}, {"t": "表恶其能。", "b": "《资治通鉴》"}], "words": [{"w": "能处", "t": "本事;能耐"}, {"w": "无能", "t": "没有能力"}, {"w": "低能", "t": "能力低下"}, {"w": "逞能", "t": "显示自己能干"}, {"w": "各尽所能;能解", "t": "犹能耐,才能。"}]}, {"meaning": "有才能的人。", "cites": [{"t": "将能而君不能御。", "b": "《孙子·谋攻》"}, {"t": "贤能为之用。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又。", "cites": [{"t": "智能之士。", "b": ""}, {"t": "贼能且众。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "嫉贤妒能", "t": ""}]}, {"meaning": "形状。", "cites": [{"t": "此阴阳更胜之变,病之形能也。", "b": "《素问·阴阳应象大论》"}]}, {"meaning": "能够,主、客条件具备,会作,会做,会完成。", "cites": [{"t": "孔子不能决。", "b": "《列子·汤问》"}, {"t": "不能指其一端。", "b": "《虞初新志·秋声诗自序》"}, {"t": "安能辨我雄与雌。", "b": "《乐府诗集·木兰诗》"}, {"t": "假舟楫者,非能水也,而绝江河。", "b": "《荀子·劝学》"}, {"t": "壮士,能复饮乎?", "b": "《史记·项羽本纪》"}, {"t": "夏礼,吾能言之。", "b": "《论语·八佾》"}, {"t": "肉食者鄙,未能远谋。", "b": "《左传·庄公十年》"}, {"t": "能以足音辨人。", "b": "明·归有光《项脊轩志》"}, {"t": "能使人慷慨涕泣矣。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "能使人欢咍(hāi嗢wà噱jué)矣。(欢咍,欢快。咍,喜悦。嗢噱,大笑不止。)", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "富者不能致。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "能臣", "t": "能尽为臣之道者"}, {"w": "能迩", "t": "能安抚邻国而与之和睦相处"}, {"w": "能胜任", "t": "有做某事所需的能力或资源。"}]}, {"meaning": "会;善于。", "cites": [{"t": "寡人已知将军能用兵矣。", "b": "《史记·孙子吴起列传》"}], "words": [{"w": "能军", "t": "擅长治军"}, {"w": "能因", "t": "善于因势成事"}, {"w": "能言", "t": "长于辩论;有独到的见解"}, {"w": "能法", "t": "善于执行法令"}, {"w": "能书", "t": "善于抄写;擅长书法"}, {"w": "能群", "t": "谓善于组织人力和物力。"}]}, {"meaning": "友好,亲善;和睦。", "cites": [{"t": "下不能其上。", "b": "《韩非子》"}]}, {"meaning": "忍受。", "cites": [{"t": "食水者善游能寒。", "b": "《淮南子·地形》"}]}, {"meaning": "表示指示或程度,相当于“如此”、“这样”。", "cites": [{"t": "忍能对面为盗贼。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "能格", "t": "怎么这样;为何如此"}, {"w": "能概", "t": "怎么这样;为何发此"}, {"w": "能亨", "t": "如此;这样。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2147wx','难','1','nán nàn','隹','10','','[{"pinyin": "nán", "defs": [{"meaning": "(形声。从隹(zhuī)?声。从隹,与鸟有关。①本义:支翅鸟。②假借为困难)。"}, {"meaning": "困难;艰难;不容易。", "cites": [{"t": "非为织作迟,君家妇难为。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "蜀道之难,难于上青天。", "b": "李白《蜀道难》"}], "words": [{"w": "难句", "t": "难得的佳句"}, {"w": "难老", "t": "难于衰老"}, {"w": "难行", "t": "难于施行;不容易走"}, {"w": "难治", "t": "不容易治理"}, {"w": "难航", "t": "不易舟行"}, {"w": "难期", "t": "难及,难于企及"}, {"w": "难义", "t": "不易索解的辞旨"}, {"w": "难极", "t": "不易穷尽"}, {"w": "难疑", "t": "相互讨论不易索解,心存迷惑的要义"}, {"w": "难乎为继", "t": "指前人做得太好,不易照样继续下去。"}]}, {"meaning": "不可;不好。", "cites": [{"t": "桓谭作论,明弱水之难航。", "b": "汉·王褒《灵坛碑文》"}]}, {"meaning": "为难,畏难;感到困难。", "cites": [{"t": "今寇众我寡,难与持久。(难与,“难与之”的省略。之,指代曹军。)", "b": "《资治通鉴》"}, {"t": "难测也。", "b": "《左传·庄公十年》"}, {"t": "铁衣冷难着。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "天下事有难易乎。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "余幼女书,家贫难致。", "b": "清·袁枚《黄生借书说》"}]}, {"meaning": "使感到困难。", "cites": [{"t": "今不行礼于卫,而藩其君舍以难之。", "b": "《左传》"}]}, {"meaning": ""}, {"meaning": "恐惧。", "cites": [{"t": "故君子恭而不难。", "b": "《荀子·君道》。注:“难读为戁,惧也。”"}]}, {"meaning": "敬。", "cites": [{"t": "不戢不难,受福不那。", "b": "《诗·小雅·桑扈》"}]}, {"meaning": "驱除疫鬼之祭。", "cites": [{"t": "命有司大难。", "b": "《礼记·月令》"}]}]}, {"pinyin": "nàn", "defs": [{"meaning": "灾难;祸害,人为而产生的祸害。", "cites": [{"t": "三军既惑且疑,则诸侯之难至矣。", "b": "《孙子·谋攻》"}, {"t": "非刘豫州莫可以当曹操者,然豫州新败之后,安能抗此难乎?", "b": "《资治通鉴》"}, {"t": "危难之间。", "b": "诸葛亮《出师表》"}, {"t": "以免于难。", "b": "《国语·晋语》"}, {"t": "芟夷大难。", "b": "《资治通鉴》"}, {"t": "故及于难。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "排难解纷;苦难", "t": "痛苦和灾难"}, {"w": "逃难", "t": "逃灾"}, {"w": "落难", "t": "遭遇灾难,陷入困境"}, {"w": "蒙难", "t": "遭受到人为的灾祸"}, {"w": "罹难", "t": "遇灾遇险而死"}, {"w": "避难", "t": "躲避灾难或迫害。"}]}, {"meaning": "兵难,指反抗或叛乱。", "cites": [{"t": "一夫作难而七庙隳。", "b": "贾谊《过秦论》"}], "words": [{"w": "发难", "t": "发动反抗或叛乱"}, {"w": "首难", "t": "首先发难。"}]}, {"meaning": "怨仇;仇敌。", "cites": [{"t": "将西南以与秦为难。", "b": "《战国策》"}]}, {"meaning": "诘问;责难。", "cites": [{"t": "追难孔子,何伤于人?", "b": "王充《论衡·问孔》"}, {"t": "交相问难。", "b": "清·刘开《问说》"}], "words": [{"w": "刁难", "t": "故意使人为难"}, {"w": "难言", "t": "非难的言论"}, {"w": "难极", "t": "诘难"}, {"w": "驳难", "t": "反驳责难"}, {"w": "责难", "t": "指摘非难"}, {"w": "非难", "t": "指摘和责问。"}]}, {"meaning": "抵挡;拒斥。", "cites": [{"t": "难壬人。", "b": "宋·王安石《答司马谏议书》"}, {"t": "難德允元,而难任人。", "b": "《书·舜典》"}], "words": [{"w": "阻难", "t": "阻挠留难。"}]}, {"meaning": "论说;争辩。", "cites": [{"t": "死生之说,存亡之难。", "b": "《史记·五帝本纪》"}], "words": [{"w": "难说", "t": "讨论解说"}, {"w": "难诘", "t": "讨论责问"}, {"w": "难驳", "t": "攻讨反击。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2148wx','预','1','yù','页','10','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从页(xié), 予声。本义:安乐。经典通用“豫”字)。"}, {"meaning": "同本义。", "cites": [{"t": "仙亭日登眺,虎丘时游预。", "b": "唐·白居易《和微之诗》"}]}, {"meaning": "预先,事先。事先有准备", "cites": [{"t": "预备走舸。(豫备轻快的小船。豫,同“预”,预先。舸,船;走舸,快船,偏正式词组。)", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "预虑", "t": "事先考虑"}, {"w": "预筮", "t": "预卜吉凶"}, {"w": "预借元宵", "t": "预先点放灯"}, {"w": "预日", "t": "提前一天"}, {"w": "预图", "t": "预先考虑"}, {"w": "预置", "t": "事前陈设。"}]}, {"meaning": "参与", "cites": [{"t": "凡事相及为预。", "b": "《珠丛》"}, {"t": "且灌夫何预也?", "b": "《汉书·灌夫传》。师古曰:“预读曰豫。预,干也。”"}, {"t": "次日设朝,董太后降旨,封皇子协为陈留王,董重为骠骑将军,张让等共预朝政。", "b": "《三国演义》"}], "words": [{"w": "预席", "t": "参加宴会"}, {"w": "预选", "t": "参与考试选拔"}, {"w": "预会", "t": "参加集会"}, {"w": "预宴", "t": "赴宴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2149wx','桑','1','sāng','木','10','','[{"pinyin": "sāng", "defs": [{"meaning": "(会意。从桑,从木。桑者。神桑也。本义:植物名)。"}, {"meaning": "一种桑属的落叶乔木 。树皮有浅裂,叶子椭圆形,花单性,花被黄绿色,叶子是蚕的饲料,嫩枝的韧皮纤维可造纸,果实可以吃,嫩枝、根的白皮、叶和果实均可入药。", "cites": [{"t": "桑,蚕所食叶木。", "b": "《说文》"}, {"t": "桑者,中央之本也。", "b": "《贾子胎教》"}, {"t": "以桑弧蓬矢六,射天地四方。", "b": "《礼记·内则》"}, {"t": "系子包桑。", "b": "《易·否》"}, {"t": "无折我树桑。", "b": "《诗·郑风·将仲子》"}, {"t": "天子命桑。", "b": "《穆天子传》"}, {"t": "开轩面场圃,把酒话桑麻。", "b": "唐·孟浩然《过故人庄》"}], "words": [{"w": "桑麻", "t": "农事;农村;农民"}, {"w": "桑土", "t": "桑树的根"}, {"w": "桑户", "t": "编桑条为门户。指贫者所居。比喻家贫"}, {"w": "桑里", "t": "即桑梓、乡里。借指同乡人"}, {"w": "桑濮", "t": "指男女之间的不正当会合"}, {"w": "桑中", "t": "比喻幽会、私奔"}, {"w": "桑落", "t": "美酒名"}, {"w": "桑中之约", "t": "指男女幽会"}, {"w": "桑中之奔", "t": "指男女私奔"}, {"w": "桑间月下", "t": "男女幽会。"}]}, {"meaning": "桑叶。", "cites": [{"t": "采桑城南隅。", "b": "古乐府《陌上桑》"}], "words": [{"w": "桑眼", "t": "桑叶的嫩芽"}, {"w": "桑落", "t": "桑叶凋零。"}]}, {"meaning": "采桑叶。", "cites": [{"t": "吴之边邑处女桑于境上。", "b": "《吕氏春秋》"}], "words": [{"w": "桑姑", "t": "采桑女子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2150wx','绢','1','juàn','纟','10','','[{"pinyin": "juàn", "defs": [{"meaning": "(形声。从糸(mì,表示与线丝有关),肙(yuān)声。本义:生丝织物。厚而疏者称绢)。"}, {"meaning": "同本义。", "cites": [{"t": "绢,缯如麦绢者。从糸,肙声。谓粗厚之丝为之。", "b": "《说文》"}, {"t": "治丝麻,捆布绢,以为民衣。", "b": "《墨子·辞过》"}], "words": [{"w": "绢地", "t": "书画之绢底"}, {"w": "绢帖", "t": "以绢作底的书帖"}, {"w": "绢丝", "t": "织纺工程的产品。光滑润美,手感柔和,适于制造轻软的高级织物。"}]}, {"meaning": "指书画、装璜物件。", "cites": [{"t": "堂上绢素开欲裂,一见犹能动毛发。", "b": "王安石诗"}]}, {"meaning": "使缠绕或包住;使环绕或网住。", "cites": [{"t": "绢猑蹄。", "b": "《后汉书·马融传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2151wx','绣','1','xiù','纟','10','','[{"pinyin": "xiù", "defs": [{"meaning": "(形声。从糸,秀声。从“糸”(mì)与丝织有关。本义:刺绣) 同本义 。用彩色线在布帛上刺成花、鸟、图案等。", "cites": [{"t": "绣,五采备也。", "b": "《说文》。按考工记,以言画缋之事。则凡黹与画之五采备者,皆曰绣也。"}, {"t": "絺绣。", "b": "《书·益稷》。郑注:“刺者为绣。”按,谓针缕所紩者,其色备五采。紩者,黹字。郑以刺释黹,非以刺释绣也。"}, {"t": "妾自绣腰襦。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "著我绣夹裙。", "b": ""}, {"t": "朝绣夹裙。", "b": ""}, {"t": "灿若图绣。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "绣幌", "t": "乡花的帷幔,窗帘"}, {"w": "绣鹄", "t": "锦绣的飞禽图梆"}, {"w": "绣鹄", "t": "绣花的头巾"}, {"w": "绣佛", "t": "用彩色的丝刺绣成的佛像"}, {"w": "绣被", "t": "绣有彩色花纹的衾被。"}]}, {"meaning": "绣花的衣服。", "cites": [{"t": "富贵不归故乡,如衣绣之夜行,谁知之者?", "b": "《史记》"}], "words": [{"w": "绣文", "t": "彩色绣花的丝织品或衣服"}, {"w": "绣衣、绣服", "t": "用彩线刺绣的丝绸衣服"}, {"w": "绣裳", "t": "绣衣。"}]}, {"meaning": "绣花的物品。", "cites": [{"t": "绣十匹,锦三十匹。", "b": "《史记·匈奴列传》"}], "words": [{"w": "湘绣;苏绣", "t": ""}]}, {"meaning": "绘饰华美的。", "cites": [{"t": "文绣有常。", "b": "《礼记·月令》"}, {"t": "黼衣绣裳。", "b": "《诗·秦风·终南》"}], "words": [{"w": "绣毬", "t": "用五色丝绸扎成的球状物"}, {"w": "绣错", "t": "色彩错杂如绣。"}]}, {"meaning": "华丽,精致如绣。", "cites": [{"t": "绣羽衔花他自得,红颜骑行我无缘。", "b": "杜甫《草堂诗笺》"}, {"t": "骈四俪六,锦心绣口。", "b": "柳宗元《乞巧文》"}], "words": [{"w": "绣口锦心", "t": "形容辞句华丽、文思优美"}, {"w": "绣阁琼楼", "t": "精美秀丽的楼舍"}, {"w": "绣闼", "t": "雕绘华美的宫中小门"}, {"w": "绣草", "t": "沿阶草。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2152wx','验','1','yàn','马','10','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从马。佥(jiǎn)声。本义:马名)。"}, {"meaning": "同本义。", "cites": [{"t": "验,马名。", "b": "《说文》"}]}, {"meaning": "证据;凭证。", "cites": [{"t": "何以为验。", "b": "《史记·晋世家》"}, {"t": "商君之法,舍人无验者坐之。", "b": "《史记·商君列传》"}], "words": [{"w": "验左", "t": "佐证;证据。"}]}, {"meaning": "效验,灵验。", "cites": [{"t": "自然之验。", "b": "《史记·货殖列传》"}], "words": [{"w": "验方", "t": "有效验的药方"}, {"w": "明效大验", "t": "极为显著的效验。"}]}, {"meaning": "征象;征兆。", "cites": [{"t": "黄为物熟验,白为人老效。", "b": "《论衡》"}]}, {"meaning": "检查;检验。", "cites": [{"t": "亦验其辞于正前。", "b": "《战国策·齐策》"}, {"t": "验之以理。", "b": "《吕氏春秋·填行论》"}, {"t": "验之以事(用事实验证它)。", "b": "《后汉书·张衡传》"}, {"t": "欲验之,但取芦菔、地黄辈观(验:检验,证明)。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "历验各种僵石。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "验煤;验金;验护照;验数", "t": "查数"}, {"w": "验复", "t": "复查"}, {"w": "验实", "t": "检查核实"}, {"w": "验试", "t": "检查试验"}, {"w": "验解", "t": "查实后解送"}, {"w": "验票", "t": "查单据、票证。"}]}, {"meaning": "试验。", "cites": [{"t": "赵高欲为乱,恐群臣不听,乃先设验。", "b": "《史记·秦始皇本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2153wx','继','1','jì','纟','10','','[{"pinyin": "jì", "defs": [{"meaning": "同本义(把断了的丝接续上)。", "cites": [{"t": "继,续也。", "b": "《说文》"}, {"t": "大人以继明照于四方。", "b": "《易·象传》。注:“谓不绝也。”"}, {"t": "折琼枝以继佩。", "b": "《楚辞·离骚》"}, {"t": "齐人未尝赂秦,终继五国迁灭。", "b": "宋·苏洵《六国论》"}, {"t": "先后相继。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "学即继以问。", "b": "清·刘开《问说》"}], "words": [{"w": "继继", "t": "前后相继,接续不断"}, {"w": "继踪", "t": "继续前人所做的事"}, {"w": "继踵", "t": "步履前后相接。指相传不绝"}, {"w": "继志", "t": "继续前辈的志意。"}]}, {"meaning": "继承。", "cites": [{"t": "今夫封建者,继世而理。", "b": "柳宗元《封建论》"}, {"t": "继吾志事。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "九族无可继。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "继世", "t": "儿继承父的地位"}, {"w": "继轨", "t": "承继祖业"}, {"w": "继体", "t": "继承王位"}, {"w": "继绪", "t": "继承祖业;传祚无穷。"}]}, {"meaning": "随后;跟着。", "cites": [{"t": "宾继主君。", "b": "《周礼·司仪》"}, {"t": "瑜等率轻锐继其后。", "b": "《资治通鉴》"}], "words": [{"w": "继而", "t": ""}]}, {"meaning": "挂,拴缚;系念。", "cites": [{"t": "言“以”者,见行遂意也。见继重在遂。", "b": "《公羊传·宣公元年》何休注"}], "words": [{"w": "继念", "t": "系念"}, {"w": "继绊", "t": "系绊,束缚牵制"}, {"w": "继缠", "t": "系缠,纠缠。"}]}, {"meaning": "子孙后代。", "cites": [{"t": "有无肠之国无继子。", "b": "《山海经·大荒北经》"}, {"t": "赵主之子孙侯者,其继有在者乎?", "b": "《战国策》"}]}, {"meaning": "后援。", "cites": [{"t": "围之不继。", "b": "《左传·僖公三十三年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2154wx','骏','1','jùn','马','10','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。本义:良马)。"}, {"meaning": "同本义。", "cites": [{"t": "骏,马之良材也。", "b": "《说文》"}, {"t": "天子八骏。", "b": "《穆天子传》"}, {"t": "天子赐许男骏马十六。", "b": ""}, {"t": "东市买骏马。", "b": "《乐府诗集·木兰诗》"}, {"t": "将胡骏马而归。", "b": "《淮南子·人间训》"}], "words": [{"w": "骏骨", "t": "骏马的骨头。比喻贤才"}, {"w": "骏驭", "t": "良马拉的车驾"}, {"w": "骏乘", "t": "骏良,骏马,骏骁,骏珍,骏骑,骏驹。都指良马。"}]}, {"meaning": "迅速。", "cites": [{"t": "骏奔走在庙。", "b": "《诗·周颂·清庙》"}], "words": [{"w": "骏发", "t": "迅速耕作"}, {"w": "骏逸", "t": "本指马行急速。引申为超凡出众、才华纵逸"}, {"w": "骏奔", "t": "急走,快跑"}, {"w": "骏骥", "t": "良马。"}]}, {"meaning": "高大,大。", "cites": [{"t": "骏,大也。", "b": "《尔雅》"}, {"t": "骏命不易。", "b": "《诗·大雅·文王》"}, {"t": "遹骏有声。", "b": "《诗·大雅·文王有声》"}], "words": [{"w": "骏命", "t": "上天或天子重大的命令"}, {"w": "骏庞", "t": "笃厚,大厚"}, {"w": "骏业", "t": "宏伟的事业"}, {"w": "骏功", "t": "大功"}, {"w": "骏烈", "t": "盛业。"}]}, {"meaning": "才智杰出。", "cites": [{"t": "收天下之豪杰、有天下之骏雄。", "b": "《管子·七发》"}, {"t": "雄骏不创寿于旗幢。", "b": "《韩非子·大体》"}, {"t": "诽骏疑杰兮,固庸态也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "骏异", "t": "优异"}, {"w": "骏概", "t": "英武的气概"}, {"w": "骏彩", "t": "华美"}, {"w": "骏徒", "t": "优秀的学生。"}]}, {"meaning": "长。", "cites": [{"t": "浩浩昊天,不骏其德。", "b": "《诗·小雅·雨无止》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2155wx','球','1','qiú','王','11','','[{"pinyin": "qiú", "defs": [{"meaning": "(形声。从玉,求声。本义:美玉)。"}, {"meaning": "同本义。", "cites": [{"t": "球,王磬也。", "b": "《说文》。按,古以为磬,亦为笏,亦为刀室饰。"}, {"t": "球琳琅珰。", "b": "《书·禹贡》。郑注:“美玉也。”"}, {"t": "天球。", "b": "《书·顾命》。郑注:“雍州所贡之玉色如天者。”"}], "words": [{"w": "球琳", "t": "球与琳,都是美玉名"}, {"w": "球玉", "t": "美玉"}, {"w": "球琲", "t": "玉串"}, {"w": "球府", "t": "玉府。古代皇室藏宝之府库"}, {"w": "球琳器", "t": "比喻贤才"}, {"w": "球璧", "t": "泛指珍宝"}, {"w": "球玉", "t": "玉磬"}, {"w": "球音", "t": "玉磬的声音"}, {"w": "球琳", "t": "玉磬。"}]}, {"meaning": "法。", "cites": [{"t": "受大球小球,为下国缀旒。", "b": "《诗·商颂·长发》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2156wx','琐','1','suǒ','王','11','','[{"pinyin": "suǒ", "defs": [{"meaning": "(形声。本义:玉件相击发出的细碎声音)。"}, {"meaning": "同本义。", "cites": [{"t": "琐,玉声也。", "b": "《说文》"}]}, {"meaning": "也作“琐琐”。", "cites": [{"t": "玉珂声琐琐,锦帐梦悠悠。", "b": "唐·杜牧《送刘三复郎中赴阙》"}]}, {"meaning": "镂玉为连环叫琐,后以金属为之,作“锁”。连环;锁链。", "cites": [{"t": "古来绕绕,委曲如琐。", "b": "《后汉书·仲长统传·述志诗》"}]}, {"meaning": "锁链形的纹饰。", "cites": [{"t": "卿卿不惜琐窗春,支作长楸走马身。", "b": "唐·李商隐《房人不遇留别馆》"}], "words": [{"w": "琐闱", "t": "镌刻连琐图案的宫中旁门"}, {"w": "琐闼", "t": "镌刻连琐图案的宫中小门。"}]}, {"meaning": "加在门、箱等上面使人不能随便开启的器具", "cites": [{"t": "锁,铁锁门键也。", "b": "《说文新附》。郑珍新附考:“锁,本作琐。”"}]}, {"meaning": "宫禁 宫门的禁令的代称。", "cites": [{"t": "曲阳侯根骄奢僭上,赤墀青琐。", "b": "《汉书》"}]}, {"meaning": "玉屑。", "cites": [{"t": "琐,玉屑。", "b": "《洪武正韵》"}]}, {"meaning": "古地名。"}, {"meaning": "春秋郑地。约在河南省新郑县北。"}, {"meaning": "春秋晋地。约在河北省大名县。又作“沙”、“沙泽”。"}, {"meaning": "春秋楚地。约在安微省霍丘县东。"}, {"meaning": "细碎,细小。", "cites": [{"t": "成魁琐。", "b": "《太玄·成》。注:“细也。”"}, {"t": "琐,碎也。", "b": "《后汉书·刘梁传》注"}, {"t": "琐琐。", "b": "《易·旅》。郑注:“犹小小。”"}, {"t": "凡此琐琐,虽为陈迹,然我一日未死,则一日不能忘。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "形容人品卑劣,猥琐。", "cites": [{"t": "琐琐姻亚,则无膴（wǔ）(膴仕,高位厚禄)。", "b": "《诗·小雅·节南山》"}], "words": [{"w": "琐贱", "t": "地位卑微"}, {"w": "琐劣", "t": "猥琐拙劣"}, {"w": "琐任", "t": "卑微的职务"}, {"w": "琐猥", "t": "庸俗卑微"}, {"w": "琐运", "t": "卑贱的命运。"}]}, {"meaning": "琐碎。", "cites": [{"t": "王隐、何法盛之徒,所撰《晋史》,乃专访州闾细事,委巷琐言,聚而编之。", "b": "唐·刘知几《史通·书事》"}], "words": [{"w": "琐近", "t": "琐碎而浅近"}, {"w": "琐言", "t": "琐碎的言谈"}, {"w": "琐卒", "t": "零散的兵力"}, {"w": "琐故", "t": "琐细的典故"}, {"w": "琐记", "t": "记述琐事的一种文章体裁"}, {"w": "琐务", "t": "琐碎的事务"}, {"w": "琐脞", "t": "繁琐"}, {"w": "琐说", "t": "琐细的论述。"}]}, {"meaning": "仔细。", "cites": [{"t": "吉善其言,召东曹案边长吏,琐科条其人。", "b": "《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2157wx','理','1','lǐ','王','11','','[{"pinyin": "lǐ", "defs": [{"meaning": "(形声。从玉,里声。本义:加工雕琢玉石)。"}, {"meaning": "同本义。", "cites": [{"t": "理,治玉也。顺玉之文而剖析之。", "b": "《说文》"}, {"t": "理者,成物之文也。长短大小、方圆坚脆、轻重白黑之谓理。", "b": "《韩非子·解老》"}, {"t": "王乃使玉人理其璞而得宝焉,遂命曰:“和氏之璧。”", "b": "《韩非子·和氏》"}, {"t": "郑人谓玉未理者璞。", "b": "《战国策·秦策三》"}]}, {"meaning": "治理;管理。", "cites": [{"t": "不可胜理。", "b": "《战国策·秦策一》"}, {"t": "圣人之所在,则天下理焉。", "b": "《吕氏春秋·劝学》"}, {"t": "夫能理三苗。", "b": "《淮南子·原道》"}, {"t": "以昭陛下平明之理。", "b": "诸葛亮《出师表》"}, {"t": "贫困如故时,始复上街头理其故业。", "b": "黄宗羲《柳敬亭传》"}, {"t": "为天下理财。", "b": "王安石《答司马谏议书》"}, {"t": "理事自若。", "b": "《后汉书·卓茂传》"}], "words": [{"w": "当家理事;理官", "t": "治理狱讼的官员"}, {"w": "理民", "t": "治理人民"}, {"w": "理国", "t": "治理国家。"}]}, {"meaning": "整理,使有条理、有秩序。", "cites": [{"t": "分茧理丝。", "b": "《晋书·左芬传》"}, {"t": "当户理红妆。", "b": "《乐府诗集·木兰诗》"}]}, {"meaning": "又。", "cites": [{"t": "当窗理云鬓。", "b": ""}], "words": [{"w": "理妆", "t": "整理妆饰"}, {"w": "理丝", "t": "抽理蚕丝"}, {"w": "理鬓", "t": "梳理鬓发"}, {"w": "理顺", "t": ""}]}, {"meaning": "温习;熟习。", "cites": [{"t": "被服罗裳衣,当户理清曲。", "b": "《古诗十九首》"}], "words": [{"w": "理书", "t": "温习功课"}, {"w": "理乐", "t": "练习演奏乐曲"}, {"w": "理曲", "t": "练习歌曲。"}]}, {"meaning": "区分;辨别。", "cites": [{"t": "理道之远近而致贡。", "b": "《荀子·王制》"}], "words": [{"w": "理音", "t": "辨别声音。"}]}, {"meaning": "理睬,理会。", "cites": [{"t": "只顾玩笑,并不理他。", "b": "《红楼梦》"}], "words": [{"w": "不理", "t": "不闻不问"}, {"w": "理值", "t": "理睬"}, {"w": "理识", "t": "犹理睬。"}]}, {"meaning": "操理。", "cites": [{"t": "始复上街头理其故业。", "b": "清·黄宗羲《柳敬亭传》"}]}, {"meaning": "纹理;条理。", "cites": [{"t": "井井兮有其理也。", "b": "《荀子·儒效》"}, {"t": "璧袭无理。", "b": "《淮南子·览冥》"}, {"t": "知分理之可相别异也。", "b": "《说文解字·叙》"}, {"t": "圭形石质,苍色腻理。", "b": "刘禹锡《砥石赋》"}], "words": [{"w": "理比", "t": "纹理相次"}, {"w": "理路", "t": "纹理,纹路。"}]}, {"meaning": "法律;司法官。", "cites": [{"t": "弦子旗为理。", "b": ""}, {"t": "管子·小匡》", "b": ""}, {"t": "遂下于理。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "理刑厅", "t": "理刑官员。"}]}, {"meaning": "道理,义理。", "cites": [{"t": "井井兮其有理也。", "b": "《荀子·儒效》"}, {"t": "恶积祸盈,理至焦烂。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "势不同而理同。", "b": "柳宗元《送薛存义序》"}, {"t": "是未明天地之理,万物之情者也。", "b": "《庄子·秋水》"}, {"t": "理实如兄言。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "天下之理得矣。", "b": "宋·王安石《答司马谏议书》"}, {"t": "验之以理。", "b": "《吕氏春秋·慎行论》"}, {"t": "理无专在。", "b": "清·刘开《问说》"}]}, {"meaning": "又。", "cites": [{"t": "理有未安,妄以臆度。", "b": ""}], "words": [{"w": "无理", "t": "没有道理"}, {"w": "在理", "t": "合乎道理"}, {"w": "理致", "t": "义理情致,思想情趣"}, {"w": "理窟", "t": "义理会聚处;道理深奥处"}, {"w": "理顺", "t": "道理顺当;理由正当。"}]}, {"meaning": "使者。", "cites": [{"t": "行理之命,无月不至。", "b": "《左传·昭公十三年》。注:“行理,使人通聘问者。”"}]}, {"meaning": "媒人。", "cites": [{"t": "吾令蹇修以为理。", "b": "《楚辞·屈原·离骚》"}]}, {"meaning": "狱官。", "cites": [{"t": "孟秋之月:命理瞻伤。", "b": "《礼记·月令》"}, {"t": "李离者,晋文公之理也。", "b": "《史记·循吏列传》"}]}, {"meaning": "治理得很好。", "cites": [{"t": "本事不理。", "b": "《荀子·天论》"}, {"t": "运极则化,理乱相承。", "b": "《后汉书·蔡邕传》"}, {"t": "一切治理,威名流闻。", "b": "《汉书·赵尹韩张两王传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2158wx','琉','1','liú','王','11','','[{"pinyin": "liú", "defs": [{"meaning": "琉璃。"}, {"meaning": "亦指琉璃灯座。"}, {"meaning": "一盏琉璃。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2159wx','琅','1','láng','王','11','','[{"pinyin": "láng", "defs": [{"meaning": "(形声。从玉,良声。本义:似玉的美石或青色的珊瑚)。"}, {"meaning": "同本义。", "cites": [{"t": "琅,琅玕似珠者。", "b": "《说文》"}, {"t": "厥贡惟球琳琅玕。", "b": "《书·禹贡》。传:“石似玉。”"}], "words": [{"w": "琳琅", "t": "美玉,比喻优美珍贵的东西"}, {"w": "琅花", "t": "琅华。琅玕树所开之花,常以美称白花。"}]}, {"meaning": "门环。", "cites": [{"t": "木门仓琅根,谓宫门铜锾,言将尊贵也。", "b": "《汉书》"}]}, {"meaning": "洁白、华美如玉。", "cites": [{"t": "已过重阳半月天,琅华千点照寒烟。", "b": "皮日休《奉和鲁望白菊诗》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2160wx','捧','1','pěng','扌','11','','[{"pinyin": "pěng", "defs": [{"meaning": "(形声。从手,奉声。本义:两手承托。古多作“奉”)。"}, {"meaning": "同本义。", "cites": [{"t": "捧,两手承也。", "b": "《广韵》"}, {"t": "捧馈而哭。", "b": "《穆天子传》。注:“捧,两手持也。”"}, {"t": "捧土以塞孟津,多见其不知量也。", "b": "《后汉书·朱浮传》"}, {"t": "君与康先生捧诏恸哭。", "b": "清·梁启超《谭嗣同传》"}, {"t": "两手捧头及剑奉之。", "b": "晋·干宝《搜神记》"}], "words": [{"w": "捧戴", "t": "托举;扶拥"}, {"w": "捧脚", "t": "捧承他人的脚。形容随从众多"}, {"w": "捧檄", "t": "接受诏书为官就任"}, {"w": "捧头鼠窜", "t": "形容抱头而逃、狼狈至极"}, {"w": "捧茗", "t": "端茶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2161wx','堵','1','dǔ','土','11','','[{"pinyin": "dǔ", "defs": [{"meaning": "(形声。从土,者声。本义:墙壁)。"}, {"meaning": "同本义。", "cites": [{"t": "堵,垣也。五版为一堵。", "b": "《说文》"}, {"t": "环堵之室。", "b": "《淮南子·原道》"}, {"t": "止如堵墙。", "b": "《尉缭子·战威》"}], "words": [{"w": "堵墙", "t": "墙垣,土墙。用来比喻密集的人群"}, {"w": "堵垣", "t": "墙。"}]}, {"meaning": "古代墙壁的面积单位,古代用板筑法筑土墙,五板为一堵,板的长度就是堵的长度,五层板的高度就是堵的高度。", "cites": [{"t": "百堵皆作。", "b": "《诗·小雅·鸿雁》"}], "words": [{"w": "堵雉", "t": "墙垣的长度和高度。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2162wx','措','1','cuò','扌','11','','[{"pinyin": "cuò", "defs": [{"meaning": "(形声。从手,昔声。本义:放置,安放)。"}, {"meaning": "同本义。", "cites": [{"t": "措,置也。", "b": "《说文》。"}, {"t": "则民无所措手足。", "b": "《论语·子路》"}, {"t": "学之弗能,弗措也。", "b": "《礼记·中庸》。疏:“学不至于能,不措置休废也。”"}, {"t": "几致刑措。", "b": "《汉书·文帝纪》。师古曰:“措,置也。民不犯法,无所刑也。”"}], "words": [{"w": "措置", "t": "安放;料理"}, {"w": "措身", "t": "安身,置身"}, {"w": "措手", "t": "着手处理"}, {"w": "措手不迭", "t": "形容做事迅速敏捷。"}]}, {"meaning": "废弃;搁置。", "cites": [{"t": "驱天下之人入于罪,又缓而慢之以滋其懈怠,此刑之所以不措也。", "b": "柳宗元《断刑论下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2163wx','描','1','miáo','扌','11','','[{"pinyin": "miáo", "defs": [{"meaning": "(形声。从手,苗声。本义:依样摹写或绘画)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2164wx','域','1','yù','土','11','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从土,或(yù)声。土,表示疆土。“域”本作“或”,与“国”同义。“从口,从戈,以守一。一,地也。”为会意字。本义:疆界,疆域)。"}, {"meaning": "同本义。", "cites": [{"t": "域,邦也。", "b": "《说文》。按,或者,封也,国者,邦也:天子诸侯所守土为域,所建都为邦。"}, {"t": "以保尔域。", "b": "《汉书·韦元成传》。注:“谓封邑也。”"}, {"t": "正域彼四方。", "b": "《诗·商颂·玄鸟》"}, {"t": "驱一世之民,济之仁寿之域。", "b": "《汉书》"}], "words": [{"w": "域野", "t": "境内乡野"}, {"w": "域内", "t": "域中"}, {"w": "域外", "t": "境外;国外。"}]}, {"meaning": "地区,区域。", "cites": [{"t": "出百死,入绝域。", "b": "《汉书》"}, {"t": "卿曹与我俱在绝域,欲立大功以求富贵。", "b": "《后汉书·班超传》"}], "words": [{"w": "异域;西域", "t": ""}]}, {"meaning": "范围。", "cites": [{"t": "是管仲亦在所去之域矣。", "b": "《韩非子》"}]}, {"meaning": "茔地,坟地。", "cites": [{"t": "葛生蒙棘,蔹蔓於域。", "b": "《诗·唐风·葛生》"}], "words": [{"w": "域兆", "t": "坟墓的界址;墓地。"}]}, {"meaning": "局限。", "cites": [{"t": "政治家之眼,域於一人一事,诗人之眼,则通古今而观之。", "b": "王国维《人间词话》"}], "words": [{"w": "域域", "t": "形容浅狭无知。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2165wx','捺','1','nà','扌','11','','[{"pinyin": "nà", "defs": [{"meaning": "(形声。从手,奈声。本义:用手重按)。"}, {"meaning": "同本义。", "cites": [{"t": "先须捺后脚,然后勒前腰。", "b": "《游仙窟》"}], "words": [{"w": "捺上花冠;捺头向水下;捺印", "t": "盖指模或图章"}, {"w": "捺抉", "t": "用力挤压"}, {"w": "捺弮", "t": "向下弯曲如弓弩。形容禾穗丰硕。"}]}, {"meaning": "搁置;扣压。", "cites": [{"t": "这事断断破不得,既承头翁好心,千万将呈子捺下。", "b": "《儒林外史》"}]}, {"meaning": "汉字笔画的一种,向右斜下,近末端微有波折。古又名“磔”。", "cites": [{"t": "俗云捺,捺之祖磔法也,今人作捺多是。", "b": "《书法离鉤·八磔》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2166wx','掩','1','yǎn','扌','11','','[{"pinyin": "yǎn", "defs": [{"meaning": "(会意。从手,从奄,奄亦声。本义:遮蔽)。"}, {"meaning": "同本义。", "cites": [{"t": "掩,敛也。小上曰掩。", "b": "《说文》"}, {"t": "掩练帛,广终幅。", "b": "《仪礼·士丧礼》。注:“裹首也。”"}, {"t": "掩薄草渚。", "b": "《史记·司马相如传》"}, {"t": "空正掩日。", "b": "《周髀算经》"}, {"t": "掩口胡卢而笑。", "b": "《聊斋志异·促织》"}, {"t": "掩其上哉。", "b": "清·方域《壮梅堂文集》"}, {"t": "手巾掩口。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "势拔五岳掩赤诚。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "掩圹", "t": "将棺木放入墓穴内,加土掩埋"}, {"w": "掩心", "t": "护胸的铠甲"}, {"w": "掩土", "t": "盖土埋葬"}, {"w": "掩面", "t": "盖在尸体面部的白色的布或绢"}, {"w": "掩著", "t": "掩盖剽窃他人文章的痕迹。"}]}, {"meaning": "藏。", "cites": [{"t": "掩贼为臧。", "b": "《左传·文公十八年》。注:“匿也。”"}, {"t": "处必掩身。", "b": "《礼记·月令》"}], "words": [{"w": "掩掩缩缩", "t": "躲躲藏藏"}, {"w": "掩敛", "t": "遮藏躲闪"}, {"w": "掩败", "t": "掩饰失败"}, {"w": "掩秘", "t": "隐瞒,秘而不宣。"}]}, {"meaning": "止。", "cites": [{"t": "掩,止也。", "b": "《方言》十三"}, {"t": "掩以绝灭。", "b": "王褒《洞箫赋》。注:“止息貌。”"}, {"t": "掩细柳而抚剑。", "b": "潘岳《西征赋》。注:“止也。”"}]}, {"meaning": "关闭;合上。", "cites": [{"t": "为掩户。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "掩亚", "t": "关闭"}, {"w": "掩关", "t": "关闭;关门。"}]}, {"meaning": "抹杀。", "cites": [{"t": "一眚掩大德。", "b": "《左传·僖公三十三年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2167wx','捷','1','jié','扌','11','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从手,疌(jié)声。本义:战利品)。"}, {"meaning": "同本义。", "cites": [{"t": "捷,猎也。军获得也。", "b": "《说文》"}, {"t": "军得曰捷。", "b": "《谷梁传》"}, {"t": "六月,齐侯来献戎捷。", "b": "《春秋·庄公三十一年》"}]}, {"meaning": "胜利。", "cites": [{"t": "一月三捷。", "b": "《诗·小雅·采薇》"}], "words": [{"w": "大捷;祝捷大会;首战告捷;捷书;捷书", "t": "报告战胜的文书。"}]}, {"meaning": "成功。", "cites": [{"t": "捷,吾以女为夫人。", "b": "《左传·庄公八年》"}, {"t": "事若不捷。", "b": "《国语·吴语》"}]}, {"meaning": "敏捷;迅速。", "cites": [{"t": "捷,疾也。", "b": "《小尔雅》"}, {"t": "夫唯捷径以窘步。", "b": "《楚辞·离骚》。注:“疾也。”"}, {"t": "则事业捷成。", "b": "《荀子·君子》"}, {"t": "吴起之智可谓捷矣。", "b": "《吕氏春秋·贵卒》"}, {"t": "趫捷之徒。", "b": "张衡《西京赋》"}, {"t": "征夫捷捷。", "b": "《诗·大雅·烝民》"}, {"t": "搏捷矢。", "b": "《庄子·徐无鬼》"}, {"t": "得之捷乎?", "b": "《列子·汤问》"}, {"t": "捷慑逐物。", "b": "《后汉书·赵壹传》"}, {"t": "捷敏辩给。", "b": "《韩非子》"}], "words": [{"w": "捷给", "t": "言辞敏捷,应对不穷"}, {"w": "捷才", "t": "才思敏捷的人"}, {"w": "捷绸", "t": "捷快而稠密"}, {"w": "捷巧", "t": "敏捷巧妙。"}]}, {"meaning": "旁出,斜出,抄行近道。", "cites": [{"t": "待我,不如捷之速也。", "b": "《左传·成公二十六年》"}, {"t": "不如捷而行也。", "b": "《国语·晋语》。注:“旁出为捷。”"}]}, {"meaning": "赶上。", "cites": [{"t": "岂驾鹅之能捷。", "b": "《汉书·扬雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2168wx','排','1','pái pǎi','扌','11','','[{"pinyin": "pái", "defs": [{"meaning": "(形声。从手,非声。本义:推挤,推开)。"}, {"meaning": "同本义。", "cites": [{"t": "排,挤也。", "b": "《说文》"}, {"t": "排,推也。", "b": "《广雅》"}, {"t": "献笑不及排。", "b": "《庄子·大宗师》"}, {"t": "排淮泗。", "b": "《孟子》"}, {"t": "力能排南山。", "b": "诸葛亮《梁父吟》"}, {"t": "哙乃排闼直入。", "b": "《史记·樊哙列传》"}], "words": [{"w": "排闼", "t": "推门。闼:门"}, {"w": "排门而入;排户", "t": "推门"}, {"w": "排阁", "t": "推门"}, {"w": "排墙", "t": "推倒墙壁"}, {"w": "排阖", "t": "推开门扇"}, {"w": "排雾", "t": "推开云雾"}, {"w": "排斡", "t": "推移运转。"}]}, {"meaning": "排斥;排挤。", "cites": [{"t": "抵排异端。", "b": "韩愈《进学解》"}, {"t": "诸儒内怀不服,相与排之。", "b": "《后汉书·贾逵传》"}], "words": [{"w": "排害", "t": "排挤;迫害"}, {"w": "排陷", "t": "排挤,陷害"}, {"w": "排击", "t": "排斥抨击"}, {"w": "排困", "t": "排斥困辱"}, {"w": "排毁", "t": "排斥诋毁,抨击"}, {"w": "排摈", "t": "排斥摈弃"}, {"w": "排告", "t": "排挤诬告"}, {"w": "排逐", "t": "排挤斥逐。"}]}, {"meaning": "疏通;排解。", "cites": [{"t": "为人排患释难、解纷乱而无所取也。", "b": "《战国策·赵策》"}, {"t": "如怒涛排壑,不可遏抑。", "b": "孙文《黄花冈七十二烈士事略》序"}], "words": [{"w": "排荡", "t": "犹排除"}, {"w": "排释", "t": "排解,调解"}, {"w": "排抑", "t": "排遣克制"}, {"w": "排闷", "t": "排遣烦闷"}, {"w": "排容", "t": "豪放;奔放。"}]}, {"meaning": "安排;准备。", "cites": [{"t": "排下筵席,管待众头领。", "b": "《水浒传》"}], "words": [{"w": "排当", "t": "宫廷官府安排宴席"}, {"w": "排局", "t": "设圈套;置骗局"}, {"w": "排备", "t": "安排,准备"}, {"w": "排顿", "t": "安排,准备。"}]}, {"meaning": "排列;编次。", "cites": [{"t": "松排山面千重翠,月点波心一颗珠。", "b": "唐·白居易《春题湖上》"}], "words": [{"w": "排次", "t": "依次排列"}, {"w": "排班", "t": "排队站立"}, {"w": "排栅", "t": "军事防御设施。用巨木排列连成的栏栅"}, {"w": "排推", "t": "排列成行,依次向前"}, {"w": "排连", "t": "排行相连"}, {"w": "排仗", "t": "排设仪仗"}, {"w": "排偶", "t": "排比对偶"}, {"w": "排单", "t": "名单。"}]}, {"meaning": "斥责,数落。", "cites": [{"t": "汉主思贤才,贾生被排迁。", "b": "唐·吴筠《览古》"}], "words": [{"w": "排腔", "t": "说三道四"}, {"w": "排说", "t": "数说别人的不是"}, {"w": "排数", "t": "斥责,数落"}, {"w": "排揎", "t": "埋怨;责备。"}]}, {"meaning": "古代的演员。也作“俳”。", "cites": [{"t": "或作泥车瓦狗,马骑倡排。", "b": "《潜夫论》"}]}, {"meaning": "依次,一个接一个。", "cites": [{"t": "排家搜捉,缉捕凶首。", "b": "《水浒全传》"}], "words": [{"w": "排门册籍", "t": "挨门挨户造的簿册"}, {"w": "排门人等", "t": "挨门挨户的人们"}, {"w": "排头儿", "t": "逐个"}, {"w": "排家", "t": "挨家挨户"}, {"w": "排排坐", "t": "平起平坐。"}]}]}, {"pinyin": "pǎi", "defs": [{"meaning": "", "words": [{"w": "把这双鞋排一排;排囊", "t": "鼓风用的革囊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2169wx','焉','1','yān','灬','11','','[{"pinyin": "yān", "defs": [{"meaning": "(象形。小篆字形。像鸟形。本义:焉鸟)。"}, {"meaning": "鸟名。", "cites": [{"t": "旦,北而徂山之曲,乃见苍翠一林,其中则楮烟墨宇,椒枥坎地,群焉胙充,飞而不举。", "b": "唐·黄滔《唐城客梦》"}]}, {"meaning": "(yán)。额。", "cites": [{"t": "身长七尺,面长三尺,焉广三寸,鼻目耳具,而名动天下。", "b": "《荀子·非相》。高亨云:“焉,盖颜之借字。”"}]}, {"meaning": "表示指示,相当于“之”。", "cites": [{"t": "草木无知,叩焉何益?", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "心不在焉", "t": ""}]}, {"meaning": "哪里或那里。", "cites": [{"t": "且焉置土石。", "b": "《列子·汤问》"}, {"t": "富者不能至,而贫者至焉。(焉,代词,那里,指南海。)", "b": "清·彭端淑《为学一首示子侄》"}]}, {"meaning": "什么。", "cites": [{"t": "今王公大人骨肉之亲、无故富贵、面目美好者,焉故必知哉?", "b": "《墨子》"}]}, {"meaning": "怎么。", "cites": [{"t": "食其禄,焉避其难?", "b": "《三国志》"}]}, {"meaning": "兼有介词“于”加代词“此”的语法功能,相当于“于是”、“于此”。", "cites": [{"t": "二陵焉。", "b": "《左传·僖公三十三年》"}, {"t": "不择事而问焉。", "b": "清·刘开《问说》"}, {"t": "伏焉。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "于是,就,乃,则 。表示两件事或数个事接连发生。", "cites": [{"t": "始皇巡陇西、北地,出鸡头山,过回中,焉作信宫渭南。", "b": "《史记》"}], "words": [{"w": "焉始乘舟", "t": ""}]}, {"meaning": "于是 。表示前后承接,古代汉语中多与“乃”连用。", "cites": [{"t": "西王母为王谣,王和之,其辞哀。焉乃观日之出入,一日行万里。", "b": "《列子》"}]}, {"meaning": "表示结构,用于前置的宾语之后,相当于“之”,“是”。", "cites": [{"t": "今王播弃黎老,而孩童焉比谋。", "b": "《国语》"}]}, {"meaning": "后缀,表示状态,用于形容词、副词之后,相当于“然”、“样子”。", "cites": [{"t": "其心休休焉,其如有容。", "b": "《书·秦誓》"}]}, {"meaning": "用于句中表示停顿,相当于“啊”。", "cites": [{"t": "且以五帝之圣焉而死,三王之仁焉而死…", "b": "《史记》"}]}, {"meaning": "用于句尾,表示陈述或肯定,相当于“矣”、“呢”。", "cites": [{"t": "及至秦之季世,焚《诗》《书》,坑术士,六艺从此缺焉。", "b": "《史记》"}]}, {"meaning": "用于句尾,表示疑问,相当于“乎”、“吗”。", "cites": [{"t": "嗟行之人,胡不比焉?", "b": "《诗·唐风》"}]}, {"meaning": "用于句尾,表示感叹,相当于“呢”、“啊”。", "cites": [{"t": "使其中无可欲者,虽无石椁,又何戚焉?", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2170wx','掉','1','diào','扌','11','','[{"pinyin": "diào", "defs": [{"meaning": "(形声。从手,卓声。本义:摇,摆动)。"}, {"meaning": "同本义。", "cites": [{"t": "掉,摇也。", "b": "《说文》"}, {"t": "且郦生一士,伏轼掉三寸之舌,下齐七十余城。", "b": "《史记·淮阴侯列传》"}, {"t": "末大未折,尾大不掉。", "b": "《左传·昭公十一年》"}], "words": [{"w": "掉尾巴;掉荡", "t": "摇荡"}, {"w": "掉眩", "t": "肢体摇动旋转"}, {"w": "掉擘", "t": "甩着臂膊走,又谓攘臂奋起"}, {"w": "掉舌", "t": "鼓舌,指游说、谈论"}, {"w": "掉嘴弄舌", "t": "摇唇鼓舌;搬弄是非"}, {"w": "掉栗", "t": "战栗。"}]}, {"meaning": "弄,卖弄。", "cites": [{"t": "言必据书史,断章破句,以代常谈,俗谓之掉书袋。", "b": "《南唐书·彭利用传》"}], "words": [{"w": "掉罨子", "t": "耍花招,卖弄花招。"}]}, {"meaning": "划。", "cites": [{"t": "见前面两个人,掉着一只舡来。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2171wx','捶','1','chuí','扌','11','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从手,垂声。本义:棒打)。"}, {"meaning": "同本义。", "cites": [{"t": "捶,以杖击也。", "b": "《说文》"}, {"t": "捶笞膑脚。", "b": "《荀子·正论》。注:“捶笞皆杖击也。”"}], "words": [{"w": "捶鼓;捶衣裳;捶楚", "t": "用杖或板拷打。"}]}, {"meaning": "马杖", "cites": [{"t": "檄以马捶。", "b": "《庄子·至乐》"}, {"t": "一尺之捶,日取其半,万世不竭。", "b": "《庄子·天下》"}, {"t": "捶马衔走。", "b": "《公羊传·定公八年》何注"}, {"t": "执捶拊以鞭笞天下。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "捶策", "t": "扬鞭击马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2172wx','赦','1','shè','赤','11','','[{"pinyin": "shè", "defs": [{"meaning": "(形声。从攴(pū),赤声。本义:宽免罪过)。"}, {"meaning": "同本义。", "cites": [{"t": "赦,置也。", "b": "《说文》。段注:“赦与捨音义同。非专谓赦罪也。后捨行而赦废。赦专为赦罪矣。”"}, {"t": "掌三刺三宥三赦之法。", "b": "《周礼·司刺》"}, {"t": "赦止者免止之罪辞也。", "b": "《公羊传·昭公十八年》"}, {"t": "先时者杀无赦。", "b": "《书·伪允征》"}, {"t": "君子以赦过宥罪。", "b": "《易·象卦》。疏:“谓放免。”"}, {"t": "臣从其计,大王亦幸赦臣。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "宽容。", "cites": [{"t": "先有司,赦小过,举贤才。", "b": "《论语·子路》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2173wx','堆','1','duī','土','11','','[{"pinyin": "duī", "defs": [{"meaning": "(象形。从土,隹(zhuī)声。本义:土堆)。"}, {"meaning": "土墩,沙墩或水中聚集的礁石。", "cites": [{"t": "逾陇堆兮渡漠。", "b": "《楚辞·疾世》"}, {"t": "激堆埼。", "b": "司马相如《上林赋》"}, {"t": "呼水中沙堆为墠。", "b": "《尔雅·释水》注"}]}, {"meaning": "堆积。", "cites": [{"t": "堆,聚土。", "b": "《说文》"}], "words": [{"w": "堆堵", "t": "堆积堵塞"}, {"w": "堆绢", "t": "堆纱花。用彩绢制成花鸟人物形状,缀附于屏障上"}, {"w": "堆山塞海", "t": "形容财物极为丰富"}, {"w": "堆红", "t": "漆器上所堆成的朱色花纹"}, {"w": "堆案", "t": "累积案头。指积压很多文书。"}]}, {"meaning": "用来计量成堆的东西。", "cites": [{"t": "卷起千堆雪。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "一堆垃圾;一堆谷子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2174wx','推','1','tuī','扌','11','','[{"pinyin": "tuī", "defs": [{"meaning": "(形声。从手,隹(zhuī)声。本义:手向外用力使物体移动或向前移动)。"}, {"meaning": "同本义。", "cites": [{"t": "推,排也。", "b": "《说文》"}, {"t": "推,軵也,前也。", "b": "《仓颉篇》"}, {"t": "若己推而内之沟中。", "b": "《孟子·万章上》"}, {"t": "苟有险,余必下推车。", "b": "《左传·成公二年》"}, {"t": "推堕附马河中。", "b": "明·宋濂《送东阳马生序》"}, {"t": "始欲着推字。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "作推敲之势。", "b": ""}], "words": [{"w": "推毂", "t": "推动车轮轴,使车前进"}, {"w": "推抢", "t": "推拥抢夺,争抢"}, {"w": "推沟", "t": "推下沟"}, {"w": "推行", "t": "推动物体向前"}, {"w": "推引", "t": "推动;推拉"}, {"w": "推天抢地", "t": "形容乱推乱搡"}, {"w": "推转", "t": "推出处死。"}]}, {"meaning": "推移,变化、移动和发展。按顺序更换。", "cites": [{"t": "与世推移。", "b": "《史记·屈原贾生列传》"}, {"t": "推赤心于天下。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "推革", "t": "推移变易"}, {"w": "推次", "t": "相推以次第"}, {"w": "推换", "t": "推移变换"}, {"w": "推遇", "t": "随着遭遇而推移变迁"}, {"w": "推涉", "t": "推移;更易"}, {"w": "推变", "t": "推移变化"}, {"w": "推荡", "t": "推移"}, {"w": "推嬗", "t": "推移演变。"}]}, {"meaning": "寻求;探索。", "cites": [{"t": "旁推交通。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "推求;推索", "t": "推求寻索"}, {"w": "推迹", "t": "根据迹象推求"}, {"w": "推极", "t": "推求穷究"}, {"w": "推详", "t": "推究详察"}, {"w": "推纠", "t": "推究纠察"}, {"w": "推原", "t": "从本原上推究"}, {"w": "推案", "t": "考查推求"}, {"w": "推讨", "t": "推究探讨。"}]}, {"meaning": "推行,推广施行。", "cites": [{"t": "推其所为。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "推销", "t": ""}]}, {"meaning": "推测;推断。", "cites": [{"t": "推此志也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "推言", "t": "推断论说。"}]}, {"meaning": "排除,除。", "cites": [{"t": "则不可推。", "b": "《诗·大雅·云汉》"}], "words": [{"w": "推陈致新", "t": "推陈出新。排除陈旧的,生出新的来。"}]}, {"meaning": "推让;让与。", "cites": [{"t": "解衣衣我,推食食我。", "b": "《史记》"}]}, {"meaning": "刺;杀。", "cites": [{"t": "曲刃钩之,直兵推之。", "b": "《晏子春秋》"}]}, {"meaning": "夺去生命;处死。", "cites": [{"t": "哥哥,你只好推了这牛子休。", "b": "《警世通言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2175wx','埠','1','bù','土','11','','[{"pinyin": "bù", "defs": [{"meaning": "同本义。", "cites": [{"t": "埠,见《大明律》,官牙埠头,船埠头。谓主舶客商买卖货物也。", "b": "《篇海类编》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2176wx','掀','1','xiān','扌','11','','[{"pinyin": "xiān", "defs": [{"meaning": "(形声。从手,欣声。本义:举起)。"}, {"meaning": "同本义。", "cites": [{"t": "掀,举出也。", "b": "《说文》"}, {"t": "乃掀公以出于淖。", "b": "《左传·成公十六年》"}], "words": [{"w": "掀掀", "t": "高举的样子"}, {"w": "掀然", "t": "高举的样子;飞扬的样子"}, {"w": "掀擢", "t": "举拔,拔擢"}, {"w": "掀拳裸袖", "t": "高举拳头,卷起衣袖。表示心情激动。"}]}, {"meaning": "撩起;揭开。", "cites": [{"t": "刘老老掀帘进去。", "b": "《红楼梦》"}], "words": [{"w": "掀揭", "t": "掀起,揭开。"}]}, {"meaning": "翻;推。", "cites": [{"t": "有觉南方重,无疑厚地掀。", "b": "李咸用《庐山诗》"}], "words": [{"w": "掀天", "t": "翻天。极言声势之大"}, {"w": "掀扬", "t": "折腾,磨折。"}]}, {"meaning": "攻取。", "cites": [{"t": "记少年骏马走韩卢,掀东郭。", "b": "辛弃疾《满江红·和廓之雪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2177wx','授','1','shòu','扌','11','','[{"pinyin": "shòu", "defs": [{"meaning": "(会意。从手,从受,受声。本义:给予;交给)。"}, {"meaning": "同本义。", "cites": [{"t": "授,予也。", "b": "《说文》。按,“授”应是后起字。"}, {"t": "则从而授之。", "b": "《周礼·邻长》"}, {"t": "献俘授馘。", "b": "《左传·僖公二十八年》。注:“数也。”"}, {"t": "今日必授。", "b": "《国语·鲁语》。注:“与也。”"}, {"t": "君言当击,甚与孤合,此天以君授孤也。", "b": "《资治通鉴》"}, {"t": "议法度而修之于朝廷,以授之于有司,不为侵官。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "授受", "t": "交接;交付和接受"}, {"w": "授兵", "t": "把武器给战士"}, {"w": "授官厅", "t": "官府;衙门"}, {"w": "授玉", "t": "给予玉圭"}, {"w": "授室", "t": "把家事交给新妇"}, {"w": "授赏", "t": "奖赏"}, {"w": "授简", "t": "给予简札"}, {"w": "授以全权;授位", "t": "授予职位"}, {"w": "授政", "t": "授予帝位。"}]}, {"meaning": "交还,奉还。", "cites": [{"t": "子犯授公子载璧。", "b": "《国语·晋语四》。注:“授,还也。”"}]}, {"meaning": "任命。", "cites": [{"t": "如今且说贾雨村授了应天府,一到任就有件人命官司详至案下。", "b": "《红楼梦》"}]}, {"meaning": "又如：授正(任命官长);授用(任用);授能(任用有才能的人)。"}, {"meaning": "传授。", "cites": [{"t": "授之书而习其句读者。", "b": "唐·韩愈《师说》"}, {"t": "天下无以易李伶,李伶即又不肯授我。", "b": "侯方域《马伶传》"}], "words": [{"w": "授经", "t": "讲授经书"}, {"w": "授堂", "t": "讲授学业的堂室。"}]}, {"meaning": "接受。", "cites": [{"t": "凡授嫔妇功,及秋献功。", "b": "《周礼·天官·典妇功》"}, {"t": "再拜授币。", "b": "《周礼·秋官·司仪》"}, {"t": "惠公没,文公授之。", "b": "《韩非子·难二》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2178wx','捻','1','niǎn niē','扌','11','','[{"pinyin": "niǎn", "defs": [{"meaning": "(形声。从手,念声。本义:用手指搓转)。"}, {"meaning": "同本义。", "cites": [{"t": "轻拢慢捻抹复挑。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "捻就", "t": "揉缩"}, {"w": "捻髯", "t": "用手指搓着腮上的胡须"}, {"w": "捻断髭须", "t": "比喻费尽心思"}, {"w": "捻绳;捻灯芯;将两股纱捻成一根线", "t": ""}]}, {"meaning": "领导。", "cites": [{"t": "驱梨园领袖,总编修师首,捻杂剧班头。", "b": "贾仲明《凌波仙》"}]}, {"meaning": "拿;捏;提;举。", "cites": [{"t": "闲捻紫箫吹。", "b": "杜牧《杜秋娘》"}], "words": [{"w": "捻着汗", "t": "捏着汗。"}]}, {"meaning": "用线、纸等搓成的条状物。", "cites": [{"t": "宁恋本乡一捻土,莫爱他乡万两金。", "b": "《西游记》"}], "words": [{"w": "灯捻;纸捻儿", "t": ""}]}]}, {"pinyin": "niē", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2179wx','教','1','jiāo jiào','攵','11','','[{"pinyin": "jiāo", "defs": [{"meaning": "把知识和技能传授给别人。", "cites": [{"t": "十三教汝织。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "教其不知,而恤其不足。", "b": "《左传》"}], "words": [{"w": "教课;教书;手把手教;教唱歌;教倌", "t": "教入塾"}, {"w": "教老者", "t": "方言,教员"}, {"w": "教率", "t": "教授引导"}, {"w": "教书匠", "t": "对教师的谑称。"}]}, {"meaning": "使;令;让。", "cites": [{"t": "曲罢能教善才服。", "b": "唐·白居易《琵琶行》"}]}]}, {"pinyin": "jiào", "defs": [{"meaning": "(会意。从攴(pū),从孝,孝亦声。“攴”,篆体象以手持杖或执鞭。在奴隶社会,奴隶主要靠鞭杖来施行他们的教育、教化。本义:教育,指导)。"}, {"meaning": "同本义。", "cites": [{"t": "上所施下所效也。", "b": "《说文》"}, {"t": "以教国子弟。", "b": "《周礼·师氏》。注:“教之者,使识旧事也。”"}, {"t": "教也者,长善而救其失者也。", "b": "《礼记·学记》"}, {"t": "教者,民之寒暑也。", "b": "《礼记·乐记》"}, {"t": "教,文之施也。", "b": "《国语·周语》"}, {"t": "精华,教政之本也。", "b": "《春秋繁露》"}, {"t": "君有此教士三万人。", "b": "《管子·小匡》"}, {"t": "修教三年。", "b": "《韩非子·五蠹》"}, {"t": "宁有政教。", "b": "《史记·货殖列传》"}, {"t": "择师而教。", "b": "唐·韩愈《师说》"}, {"t": "以教吾子。", "b": "唐·柳宗元《柳河东集》"}, {"t": "昨日蒙教。", "b": "宋·王安石《答司马谏议书》"}, {"t": "所以见教。", "b": ""}], "words": [{"w": "教治", "t": "教化,教育"}, {"w": "教禁", "t": "教化和禁令"}, {"w": "教读", "t": "教师"}, {"w": "教读老夫子", "t": "教书老先生"}, {"w": "教民", "t": "教育人民"}, {"w": "教迪", "t": "教育开导启迪"}, {"w": "教帖", "t": "古代公侯、大臣所下的手谕、命令"}, {"w": "教当", "t": "教唆"}, {"w": "教示", "t": "教导、训诲"}, {"w": "教戒", "t": "教导和训戒"}, {"w": "教告", "t": "教导教诲"}, {"w": "教演", "t": "教练,演练"}, {"w": "教阅", "t": "操演,检阅"}, {"w": "教坊司", "t": "管理伎乐的机构,专司音乐、戏曲、舞蹈的教习、排练及演出等事宜"}, {"w": "教门儿", "t": "某种人,某类职业的人"}, {"w": "教引嬷嬷", "t": "教日常礼节的老年妇女。"}]}, {"meaning": "叫;让。", "cites": [{"t": "教我先威众。", "b": "《史记·陈涉世家》"}, {"t": "教善才服。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "教从何处。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "教令", "t": ""}]}, {"meaning": "教育;教材。", "cites": [{"t": "五教,诗、书、乐、易、春秋也。", "b": "《礼记·经解》"}, {"t": "明七教以兴民德:父子兄弟夫妇君臣、长幼、朋友、宾客也。", "b": "《礼记·王制》"}], "words": [{"w": "教刑", "t": "古时学校里使用的刑罚"}, {"w": "教席,教职", "t": "教师的职位"}, {"w": "教术", "t": "教法,教数。教育的方法"}, {"w": "教泽", "t": "教育的恩泽"}, {"w": "教象", "t": "教育规则的条文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2180wx','掏','1','tāo','扌','11','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从手,匋(táo)声。本义:挖取)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2181wx','掐','1','qiā','扌','11','','[{"pinyin": "qiā", "defs": [{"meaning": "用指甲切断或截取,摘。", "cites": [{"t": "香菱等在山石边掐凤仙花呢。", "b": "《红楼梦》"}], "words": [{"w": "把杈子掐掉", "t": ""}]}, {"meaning": "镶嵌。", "cites": [{"t": "黛玉换上掐金挖云红香羊皮小靴。", "b": "《红楼梦》"}], "words": [{"w": "掐牙", "t": "在衣服滚边镶上一条极细的滚条,稍稍露在外面作装饰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2182wx','掠','1','lüè','扌','11','','[{"pinyin": "lüè", "defs": [{"meaning": "(形声。从手,京声。本义:抢劫,夺取)。"}, {"meaning": "同本义。", "cites": [{"t": "掠,夺取也。", "b": "《说文新附》"}]}, {"meaning": "按:掠是“略”的分别字,以别于经略、简略的略。", "cites": [{"t": "已恶而掠美为昏。", "b": "《左传·昭公十四年》"}, {"t": "输掠其聚。", "b": "《左传·昭公二十年》"}, {"t": "几世几年,剽掠其人。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "掠美", "t": "夺取他人的优点或成就"}, {"w": "掠卤", "t": "掳掠,抢夺"}, {"w": "掠掇", "t": "动手动脚"}, {"w": "掠贩的", "t": "拐卖人口的人"}, {"w": "掠阵", "t": "夺取阵地"}, {"w": "掠抄", "t": "抢劫"}, {"w": "掠剩", "t": "抢劫后的剩余之物"}, {"w": "掠盗", "t": "抢劫,抄掠"}, {"w": "掠贩", "t": "用抢骗等方式贩卖人口。"}]}, {"meaning": "拷打;拷问。", "cites": [{"t": "毒掠百姓。", "b": "《南史·柳仲礼传》"}], "words": [{"w": "掠治", "t": "拷问犯人"}, {"w": "掠考", "t": "掠拷。笞击拷问"}, {"w": "掠杀", "t": "拷打而死"}, {"w": "掠理", "t": "拷打讯问"}, {"w": "掠笞", "t": "拷打;苔击。"}]}, {"meaning": "拂过。", "cites": [{"t": "髻鬟之始掠。", "b": "明·袁宏道《满井游记》"}, {"t": "掠江东南去。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "浮光掠影。", "b": "清·冯班《沧浪诗话纠谬》"}], "words": [{"w": "掠地", "t": "擦过或拂过地面"}, {"w": "掠海", "t": "拂过海面"}, {"w": "掠袭", "t": "犹飘拂。"}]}, {"meaning": "砍伐;砍。", "cites": [{"t": "[武松]赶上一刀,掠断了马脚。", "b": "《水浒传》"}]}, {"meaning": "梳理。", "cites": [{"t": "镜儿里不住照,把须鬓掠了重掠。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "掠子", "t": "发篦"}, {"w": "掠头", "t": "梳子"}, {"w": "掠削", "t": "梳理齐整貌。"}]}, {"meaning": "扔;抛。", "cites": [{"t": "春梅把鞋掠在地下。", "b": "明·笑笑生《金瓶梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2183wx','掂','1','diān','扌','11','','[{"pinyin": "diān", "defs": [{"meaning": "(形声。从手,店声。本义:以手称物)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2184wx','培','1','péi','土','11','','[{"pinyin": "péi", "defs": [{"meaning": "(形声。从土,咅(pǒu)声。本义:给植物或墙堤等的根基垒土)。"}, {"meaning": "同本义。", "cites": [{"t": "培,培敦土田山川也。", "b": "《说文》。按,垒土也。"}, {"t": "若见垒培。", "b": "《国语·晋语》。注:“垒墼曰培。”"}, {"t": "故栽者培之。", "b": "《礼记·中庸》"}, {"t": "凿培而遁之。", "b": "《淮南子·齐俗》。注:“培屋后墙也。”"}, {"t": "高培则拔。", "b": "《吕氏春秋·辨土》。注:“培田侧也。”"}], "words": [{"w": "培户", "t": "昆虫把土堆在洞穴周围。"}]}, {"meaning": "(píng)。"}, {"meaning": "凭借、依靠。", "cites": [{"t": "而后乃今培风。", "b": "《庄子·逍遥游》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2185wx','接','1','jiē jié','扌','11','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从手,妾声。本义:两手交叉)。"}, {"meaning": "交合;会合。", "cites": [{"t": "接,交也。", "b": "《说文》"}, {"t": "接,合也。", "b": "《广雅》"}, {"t": "昼日三接。", "b": "《易·晋》"}, {"t": "两君偃兵接好。", "b": "《国语·吴语》。注:“合也。”"}, {"t": "兵刃既接。", "b": "《孟子·梁惠王上》"}, {"t": "车鉷毂兮短兵接。", "b": "《楚辞·九歌·国殇》"}, {"t": "兵不接刃。", "b": "《吕氏春秋·怀宠》"}, {"t": "敌皆以走为利,则刃无与接。", "b": "《吕氏春秋·爱士》"}]}, {"meaning": "迎接。", "cites": [{"t": "笙箫细乐,却安排接驾。", "b": "《宣和遗事》"}], "words": [{"w": "接场", "t": "迎接从科举考场回来的生员"}, {"w": "接构", "t": "联合"}, {"w": "接三", "t": "人死后三日举行的迎接魂魄归来的仪式"}, {"w": "接煞", "t": "为接死人灵魂回家而举行的仪式。"}]}, {"meaning": "接见;接待。", "cites": [{"t": "接遇宾客。", "b": "《史记·屈原贾生列传》"}, {"t": "尽礼相接。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "接伴", "t": "接待外国使臣"}, {"w": "接待使", "t": "陪同官员;担任迎接、陪伴来宾使命的人"}, {"w": "接遇", "t": "接待"}, {"w": "接对", "t": "接待应对。"}]}, {"meaning": "靠近;接触。", "cites": [{"t": "车错毂兮短兵接。", "b": "《楚辞·九歌·国殇》"}, {"t": "宾立接西塾。", "b": "《仪礼·聘礼》"}], "words": [{"w": "接物", "t": "与外物接触;与人交往"}, {"w": "接膝", "t": "膝盖相接。指彼此对坐靠得很近"}, {"w": "接仗", "t": "交战,打仗"}, {"w": "接席", "t": "坐席相接。多形容亲近"}, {"w": "接翅", "t": "翅膀碰着翅膀。形容禽鸟多。"}]}, {"meaning": "连续;继续。", "cites": [{"t": "心不怡之长久兮,忧与愁其相接。", "b": "《楚辞·九章·哀郢》"}, {"t": "圣人食足以接气。", "b": "《淮南子·精神》"}, {"t": "故使工人为木材以接手。", "b": "《战国策·秦策五》"}], "words": [{"w": "接响", "t": "接连不断的声响"}, {"w": "接轸", "t": "车辆相连而行。比喻靠近"}, {"w": "接脚", "t": "一个跟着一个,紧接在后;接替;接脚夫,接脚婿。妇女丈夫死后再招的后夫"}, {"w": "接偈", "t": "接诵偈语。"}]}, {"meaning": "连接。", "cites": [{"t": "接天莲叶无穷碧。", "b": "宋·杨万里《晓出净慈寺送林子方》"}, {"t": "与国邻接。", "b": "《资治通鉴》"}, {"t": "首尾相接。", "b": ""}], "words": [{"w": "接武", "t": "前后足迹相连接。形容步子很小"}, {"w": "接境", "t": "地界相连,交界"}, {"w": "接衫", "t": "上下用两种颜色的料子拼接起来的长衫。"}]}, {"meaning": "承接,收受。", "cites": [{"t": "汉兴,接秦之敝。", "b": "《史记·平准书》"}], "words": [{"w": "接茶", "t": "女方允婚,接受男方聘礼"}, {"w": "接丝鞭", "t": "女方招亲时,送给男方丝鞭,男方接丝就表示同意"}, {"w": "接凑", "t": "能够接续。"}]}, {"meaning": "缚。", "cites": [{"t": "武士反接之。", "b": "《史记》"}]}, {"meaning": "交往,交情。", "cites": [{"t": "君子之接如水。", "b": "《礼记·表记》"}]}, {"meaning": "姓。"}]}, {"pinyin": "jié", "defs": [{"meaning": "迅速,敏捷。", "cites": [{"t": "先事虑事谓之接,接则事优成。", "b": "《荀子·大略》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2186wx','掷','1','zhì','扌','11','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从手,郑声。本义:扔,抛)。"}, {"meaning": "同本义。", "cites": [{"t": "荆轲废,乃引其匕首以掷秦王。", "b": "《史记·刺客列传》"}, {"t": "少间,帘内掷一纸出。", "b": "《聊斋志异·促织》"}, {"t": "[崔]莺解裙带掷于梁。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "掷丸", "t": "辽俗,于正旦抛掷饼团以惊鬼"}, {"w": "掷骰", "t": "掷色,掷博,掷博齿,掷卢,掷钱。掷骰子之类的种种赌博游戏"}, {"w": "掷铁饼", "t": ""}]}, {"meaning": "投射。", "cites": [{"t": "多情过客,空费汝、星眸小掷。", "b": "清·许田《解语花》"}], "words": [{"w": "掷目", "t": "投以目光。"}]}, {"meaning": "腾跃,将自身抛入空中。", "cites": [{"t": "澄波月上见鱼掷,晚径叶多闻犬行。", "b": "唐·周贺《晚题江馆》"}], "words": [{"w": "掷身", "t": "纵身"}, {"w": "掷倒", "t": "逆行连倒,翻筋斗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2187wx','控','1','kòng','扌','11','','[{"pinyin": "kòng", "defs": [{"meaning": "(形声。从手,空声。本义:开弓)。"}, {"meaning": "同本义。", "cites": [{"t": "控,引也。", "b": "《说文》"}, {"t": "控弦破左的。", "b": "曹植《白马篇》"}, {"t": "或控弦以弊筋骨。", "b": "《抱扑子·金丹》"}, {"t": "将军角弓不得控。", "b": "唐·岑参《白雪歌送武判官归京》"}], "words": [{"w": "控弦", "t": "拉弓,持弓"}, {"w": "控弦之士", "t": "士兵。控弦:开弓射箭"}, {"w": "控背", "t": "控身。躬身行礼。"}]}, {"meaning": "勒马。", "cites": [{"t": "控骄马,鞭袅芦花。", "b": "董解元《西厢记》"}], "words": [{"w": "控抑", "t": "抑制"}, {"w": "控勒", "t": "勒住马缰"}, {"w": "控马", "t": "驾驭马匹,骑马。"}]}, {"meaning": "控制。", "cites": [{"t": "控蛮荆而引瓯、越。", "b": "王勃《滕王阁序》"}], "words": [{"w": "控单", "t": "盖东西的布单等"}, {"w": "控扼", "t": "控制扼守"}, {"w": "控番引夷", "t": "控制、吸引文化落后的异族。"}]}, {"meaning": "投。", "cites": [{"t": "时则不至,而控于地而已矣。", "b": "《庄子·逍遥游》"}]}, {"meaning": "悬。", "cites": [{"t": "只见是三间大厅,帘拢高控,静悄悄全无人迹。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2188wx','探','1','tàn','扌','11','','[{"pinyin": "tàn", "defs": [{"meaning": "(形声。从手,罙(shēn)声。本义:摸取)。"}, {"meaning": "同本义。", "cites": [{"t": "探,远取之也。", "b": "《说文》。按,远取犹深取也。"}, {"t": "探,取也。", "b": "《尔雅》。注:“摸取也。”"}, {"t": "必探筹而定分。", "b": "《铨言》。注:“捉筹也。”"}, {"t": "则惟尔多方探天之威。", "b": "《书·多方》"}, {"t": "见不善如探汤。", "b": "《论语·季氏》"}, {"t": "不待探筹投钩而公。", "b": "《荀子·君道》"}, {"t": "日中如探汤。", "b": "《列子·汤问》"}, {"t": "探石发穴。", "b": "《聊斋志异·促织》"}], "words": [{"w": "探丸", "t": "摸取药丸;又指摸取弹丸以决定谋杀官吏之事"}, {"w": "探囊", "t": "伸手到袋中摸取。"}]}, {"meaning": "探求。", "cites": [{"t": "前来一探。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "探本", "t": "探求根本"}, {"w": "探真", "t": "探求玄理"}, {"w": "探意", "t": "探求本意"}, {"w": "探微", "t": "探索微妙的事理"}, {"w": "探源", "t": "寻求源头;探求本源。"}]}, {"meaning": "打听。", "cites": [{"t": "探,试也。", "b": "《释言》。注:“刺探尝试。”"}], "words": [{"w": "探声候气", "t": "探听消息,等候动静"}, {"w": "探事", "t": "探听消息"}, {"w": "探讯", "t": "探信,打听消息"}, {"w": "探侦", "t": "打听。"}]}, {"meaning": "看望。", "cites": [{"t": "蓬山此去无多路,青鸟殷勤为探看。", "b": "唐·李商隐《无题》"}], "words": [{"w": "探望;探病", "t": "看望病人"}, {"w": "探房", "t": "新娘过门的次日,娘家人前往看望。"}]}, {"meaning": "侦察。", "cites": [{"t": "探颐索隐。", "b": "《易·系辞上》。疏:“窥探。”"}], "words": [{"w": "探细", "t": "侦察"}, {"w": "探刺", "t": "暗中侦察"}, {"w": "探伺", "t": "侦察"}, {"w": "探虎穴", "t": "冒险"}, {"w": "探使", "t": "负有侦察任务的使者"}, {"w": "探候", "t": "侦察打听"}, {"w": "探报", "t": "谍报。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2189wx','据','1','jū jù','扌','11','','[{"pinyin": "jū", "defs": [{"meaning": "——“拮据”(jiéjū):经济上紧张、缺少钱用。"}]}, {"pinyin": "jù", "defs": [{"meaning": "(形声。本义:手靠着;靠着)。"}, {"meaning": "同本义。", "cites": [{"t": "据,杖持也。", "b": "《说文》"}, {"t": "冯几据杖。", "b": "《战国策·燕策》"}, {"t": "据轼低头。", "b": "《庄子·盗跖》"}]}, {"meaning": "依靠,凭借。", "cites": [{"t": "不可以据。", "b": "《诗·邶风·柏舟》"}, {"t": "神必据我。", "b": "《左传·僖公五年》"}, {"t": "诚据其势。", "b": "《史记·平原君虞卿列传》"}, {"t": "北据汉沔。", "b": "《三国志·诸葛亮传》"}, {"t": "向后据地。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "据着", "t": "凭着"}, {"w": "据梧", "t": "依靠着梧桐树"}, {"w": "据争", "t": "据理争辩"}, {"w": "据恃", "t": "凭仗"}, {"w": "据高临下", "t": "凭借高处俯控低处"}, {"w": "据凭", "t": "依仗。"}]}, {"meaning": "根据。", "cites": [{"t": "据于德。", "b": "《论语》"}, {"t": "据法而治者,吏习而民安。", "b": "《商君书·更法》"}], "words": [{"w": "据经", "t": "依据经典"}, {"w": "据乱", "t": "据乱世之史"}, {"w": "据常", "t": "根据常理"}, {"w": "据依", "t": "依据"}, {"w": "据古", "t": "尊依古道。"}]}, {"meaning": "占有,占据。", "cites": [{"t": "乃入据陈。", "b": "《史记·陈涉世家》"}, {"t": "据其栅。", "b": "《资治通鉴·唐纪》"}, {"t": "据而有之。", "b": "《资治通鉴》"}, {"t": "悉为逆据。", "b": "《广东军务记》"}], "words": [{"w": "据鞍", "t": "跨鞍。后用以指年老而壮志不减"}, {"w": "据凡", "t": "占据要位"}, {"w": "据重", "t": "占据要位"}, {"w": "据窃", "t": "窃据,非法占据。"}]}, {"meaning": "按着。", "cites": [{"t": "稽首据掌致诸地。", "b": "《礼记·玉藻》。注:“以左手覆按右手也。”"}], "words": [{"w": "据地", "t": "手按着地。"}]}, {"meaning": "安;定。", "cites": [{"t": "上党民走赵,赵军长平,以按据上党民。", "b": "《史记》"}]}, {"meaning": "古西域的长度单位。相当于晋代的十里。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2190wx','掘','1','jué','扌','11','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从手,屈声。本义:挖)。"}, {"meaning": "同本义。", "cites": [{"t": "掘,搰也。", "b": "《说文》"}, {"t": "掘,穿也。", "b": "《广雅》"}, {"t": "掘褚师定子之墓。", "b": "《左传·哀公二十六年》"}, {"t": "阙(掘)地下冰而床焉。", "b": "《左传·僖公二十五年》"}, {"t": "掘坎南顺。", "b": "《仪礼·既夕记》"}, {"t": "土中有水,弗掘无泉。", "b": "《淮南子·说林》"}, {"t": "断木为杵,掘地为臼。", "b": "《易·系辞》"}, {"t": "掘野鼠去草实。", "b": "《汉书·李广苏建传》"}, {"t": "掘地深逾寻丈。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "掘室", "t": "掘地而成的房间"}, {"w": "掘阅", "t": "小虫化生,穿地而出。阅,通穴"}, {"w": "掘藏", "t": "发掘埋藏之物。指得到意外之财"}, {"w": "掘穴", "t": "打洞。"}]}, {"meaning": "竭尽;穷尽。", "cites": [{"t": "虚而不掘,动而愈出。", "b": "《老子》"}]}, {"meaning": "突起;翘起。", "cites": [{"t": "穷巷掘门。", "b": "《战国策·秦策》"}, {"t": "洪臺掘其独出兮。", "b": "《汉书·扬雄传》"}, {"t": "唯北狄野心,掘强沙塞之间。", "b": "丘迟《与陈伯之书》"}, {"t": "掘强岁月之间。", "b": "《后汉书·卢芳传论》"}], "words": [{"w": "掘尾", "t": "翘尾巴"}, {"w": "掘起", "t": "崛起;突起。"}]}, {"meaning": "愚笨;粗劣。", "cites": [{"t": "田农掘业,而秦阳以盖一州。", "b": "《史记·货殖列传》"}], "words": [{"w": "掘笔", "t": "秃笔"}, {"w": "掘头船", "t": "简陋、头尾不显著的小船。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2191wx','掺','1','càn chān shān shǎn','扌','11','','[{"pinyin": "càn", "defs": [{"meaning": "古时候的一种鼓曲名。也指击鼓三次。", "cites": [{"t": "镗鎝《渔阳掺》,怨抑胡笳断。", "b": "《乐府诗集·横吹曲辞》"}]}]}, {"pinyin": "chān", "defs": [{"meaning": "搓;涂抹。", "cites": [{"t": "墨污白水,大蒜敲碎摩掺,用水洗即白。", "b": "《格物粗谈·服饰》"}]}]}, {"pinyin": "shān", "defs": [{"meaning": "细小。", "cites": [{"t": "掺,细也。", "b": "《方言》。戴震疏证:“掺,细小也。”"}]}, {"meaning": "女手纤美的样子。", "cites": [{"t": "掺掺女手,可以缝裳。", "b": "《诗·魏风·葛屦》"}]}]}, {"pinyin": "shǎn", "defs": [{"meaning": "执持,握持。", "cites": [{"t": "掺执子之祛兮。", "b": "《诗·郑风·遵大路》"}], "words": [{"w": "掺手", "t": "握手"}, {"w": "掺袂", "t": "执袖。犹握别。"}]}, {"meaning": "操守。", "cites": [{"t": "君生也,即有殊掺。", "b": "《隶释》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2192wx','职','1','zhí','耳','11','','[{"pinyin": "zhí", "defs": [{"meaning": "(形声。从耳,只(戠zhí)声。“职”是“记”的意思。段玉裁:“凡言职者,谓其善听也。”故从耳。本义:识;记。职为识之本字)。"}, {"meaning": "同本义。", "cites": [{"t": "职,记微也。", "b": "《说文》"}, {"t": "章画职墨兮,前度未改。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "主管;任职。", "cites": [{"t": "天职生覆。", "b": "《列子·天端》。注:“主也。”"}, {"t": "职于南京。", "b": "《明史》"}], "words": [{"w": "职称言路", "t": "做谏官"}, {"w": "职任民社", "t": "管理人民与国家"}, {"w": "职客", "t": "红、白喜事的主持人"}, {"w": "职内", "t": "古官名。掌邦赋收入。"}]}, {"meaning": "尽职;称职。", "cites": [{"t": "其不职或贪暴,免归田里,以明赏罚之信。", "b": "《新唐书》"}], "words": [{"w": "职办", "t": "称职而能办事。"}]}, {"meaning": "职务;职业;职责。", "cites": [{"t": "诸侯朝于天子曰述职。述职者,述所职也。", "b": "《孟子》"}, {"t": "设官分职。", "b": "《周礼·太宰》"}, {"t": "自去史职。", "b": "《后汉书·张衡传》"}, {"t": "代百司之职。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "将尽厥职。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "专职", "t": "由专人担任的职务"}, {"w": "革职", "t": "撤职"}, {"w": "职役", "t": "犹职事。多指较为低贱的职务"}, {"w": "职事僧", "t": "寺院中分管各项职务的僧人。"}]}, {"meaning": "职位;执行事务所。", "cites": [{"t": "解辫清职。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "迁我京职。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "宰相之职。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "职任", "t": "指官员的职位和职责"}, {"w": "职僚", "t": "职官僚属"}, {"w": "职钱", "t": "官吏在职时所得的俸钱。"}]}, {"meaning": "贡赋,向朝庭交的财物。", "cites": [{"t": "职如郡县。(像秦国的郡县那样贡纳赋税。)", "b": "《战国策·燕策》"}], "words": [{"w": "职贡", "t": "职方的贡物。各地以时入员的货品。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2193wx','基','1','jī','土','11','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从土,其声。本义:墙基)。"}, {"meaning": "同本义。", "cites": [{"t": "基,墙始也。", "b": "《说文》"}, {"t": "度幽宅兆基。", "b": "《仪礼·士丧礼》"}, {"t": "止基迺理?", "b": "《诗·大雅·公刘》"}, {"t": "于墙基之所,方整深耕。", "b": "《齐民要术·园篱》"}], "words": [{"w": "基扃", "t": "城阙"}, {"w": "基趾", "t": "凡墙脚、城脚居下承上的,都叫基趾。又指基础、基业"}, {"w": "基墟", "t": "旧基址。"}]}, {"meaning": "泛指一切建筑物的根脚。", "cites": [{"t": "高者必以下为基。", "b": "《淮南子·原道》"}, {"t": "太武殿基高二丈八尺。", "b": "《晋书·石季龙载记》"}], "words": [{"w": "基阶", "t": "阶基"}, {"w": "基雉", "t": "宫室与城垣的基础"}, {"w": "基筑", "t": "建筑物的基础"}, {"w": "基构", "t": "建筑物的基础和结构。"}]}, {"meaning": "基础;事业的根本。", "cites": [{"t": "邦家之基。", "b": "《诗·小雅·南山有台》"}], "words": [{"w": "基兆", "t": "根本;基础"}, {"w": "基原", "t": "根源"}, {"w": "基图", "t": "基绪,基业。作为根基的事业。"}]}, {"meaning": "一周年,一整月或一昼夜。", "cites": [{"t": "流化八基,迁荡阴令。", "b": "《汉·荡阴令张迁表颂》"}, {"t": "基月有成。", "b": "《汉·成皋令任伯嗣碑》"}, {"t": "恩洽化布,未基有成。", "b": "《汉·高阳令杨著碑》"}, {"t": "于诗三基。", "b": "《后汉书·郎传》"}]}, {"meaning": "奠定基础;创建。", "cites": [{"t": "所以基社稷而固邦统,古之制也。", "b": "唐·韩愈《顺宗实录二》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2194wx','聆','1','líng','耳','11','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从耳,令声。本义:细听)。"}, {"meaning": "同本义。", "cites": [{"t": "聆广乐之九奏兮。", "b": "张衡《思玄赋》"}, {"t": "宝玉接过来,一面目视其文,耳聆其歌。", "b": "《红楼梦》"}, {"t": "扣而聆之。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "聆偈", "t": "听经"}, {"w": "聆受", "t": "倾听并接受"}, {"w": "聆训", "t": "听受训教"}, {"w": "聆教", "t": "聆听教晦"}, {"w": "聆音察理", "t": "听到声音就能明察事理。"}]}, {"meaning": "明了,清楚。", "cites": [{"t": "观读之者,晓然若盲之开目,聆然若聋之通耳。", "b": "汉·王充《论衡》"}], "words": [{"w": "聆聆", "t": "明了,清楚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2195wx','勘','1','kān','力','11','','[{"pinyin": "kān", "defs": [{"meaning": "(形声。从力,甚声。本义:校订,核对)。"}, {"meaning": "同本义(考订核实异同)。", "cites": [{"t": "勘,校也。", "b": "《说文新附》"}, {"t": "每获一书,即共同勘校。", "b": "李清照《金石录后序》"}], "words": [{"w": "勘合", "t": "验证,核对。文书上加盖印信,一分为二,当事双方各执一半,作为凭证"}, {"w": "勘对", "t": "核对;注定"}, {"w": "勘婚", "t": "婚前男女两家互相查考生辰八字、门第等。"}]}, {"meaning": "审问。", "cites": [{"t": "当堂对勘。", "b": "《聊斋志异》"}], "words": [{"w": "勘正", "t": "审问核实"}, {"w": "勘问", "t": "盘问;审问"}, {"w": "勘鞠", "t": "审讯"}, {"w": "勘当", "t": "审问核察。"}]}, {"meaning": "查看;调查。", "cites": [{"t": "又推勘妖魔作怪之由。", "b": "洪仁玕《太平天日》"}], "words": [{"w": "勘灾", "t": "查看灾情"}, {"w": "勘破", "t": "看破"}, {"w": "堪舆", "t": "看风水。"}]}, {"meaning": "判断。", "cites": [{"t": "天也,你错勘贤愚枉做天!", "b": "《窦娥冤》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2196wx','聊','1','liáo','耳','11','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从耳,卯(mǎo)声。本义:耳鸣)。"}, {"meaning": "同本义。", "cites": [{"t": "聊,耳鸣也。", "b": "《说文》"}, {"t": "横舟航而济湘兮,耳聊啾而戃慌。", "b": "刘向《九叹》"}], "words": [{"w": "聊啾", "t": "耳鸣。"}]}, {"meaning": "依赖,凭藉。", "cites": [{"t": "百姓不聊生。", "b": "《战国策·秦策》"}, {"t": "衣与缪与不女聊。", "b": "《荀子·子道》"}, {"t": "上下相愁民无所聊。", "b": "《战国策·秦策》"}, {"t": "苦不聊生,自经于道树。", "b": "《史记·平津侯主父列传》"}, {"t": "穷饿无聊。", "b": "宋·文天祥《指南录后序》"}, {"t": "不复聊赖", "b": "《聊斋志异·促织》"}], "words": [{"w": "聊生;聊赖", "t": ""}]}, {"meaning": "略微,略。", "cites": [{"t": "开春理常业,岁功聊可观。", "b": "陶渊明《庚戌岁九月中于西田获早稻》"}], "words": [{"w": "聊陈愚见;聊胜一筹", "t": "略微高出一点"}, {"w": "聊胜于无", "t": "比没有稍好一些"}, {"w": "聊聊", "t": "稀少。"}]}, {"meaning": "姑且,暂且。", "cites": [{"t": "聊与之谋。", "b": "《诗·邶风·泉水》"}, {"t": "聊资一欢。", "b": "清·袁枚《祭妹文》"}, {"t": "聊相为言之。", "b": "唐·韩愈《朱文公较昌黎先生集》"}, {"t": "聊举数人以训汝。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "聊当", "t": "权当;犹如"}, {"w": "聊复", "t": "暂且"}, {"w": "聊报涓埃", "t": "姑且略微报答。"}]}, {"meaning": "惊恐,恐惧的样子。", "cites": [{"t": "聊兮栗兮。", "b": "枚乘《七发》"}], "words": [{"w": "聊栗", "t": "恐惧的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2197wx','娶','1','qǔ','女','11','','[{"pinyin": "qǔ", "defs": [{"meaning": "(会意兼形声。从女,从取,取亦声。本义:男子结婚。把女子接过来成亲)。"}, {"meaning": "同本义。", "cites": [{"t": "娶,取妇也。", "b": "《说文》"}, {"t": "勿为娶女。", "b": "《易·姤卦》"}, {"t": "椒举娶于申公子牟。", "b": "《左传·襄公二十六年》"}, {"t": "娶妻如之何?", "b": "《孟子·万章上》"}, {"t": "娶妇后不过二人。", "b": "清·洪亮吉《治平篇》"}, {"t": "各娶妇。", "b": ""}, {"t": "孙又娶妇。", "b": ""}], "words": [{"w": "迎娶", "t": "娶妻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2198wx','著','1','zhù','艹','11','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从艸,者声。“艸”长在地面上,表示显露。本义:明显,显著;突出) 同本义。", "cites": [{"t": "著,明也。", "b": "《小尔雅》"}, {"t": "名著而男女有别。", "b": "《礼记·大传》"}, {"t": "著不息者,天也。", "b": "《礼记·乐记》"}, {"t": "宋人有酤酒者,升概甚平,遇客甚谨,为酒甚美,县帜甚高著。", "b": "《韩非子·外储说右上》"}, {"t": "王氏门强,汝兄弟尚幼,不欲使此声著。", "b": "《世说新语·仇隙》"}, {"t": "此臣素著狂直于也。", "b": "《汉书·朱云传》"}], "words": [{"w": "著海内", "t": "天下著名"}, {"w": "昭著", "t": "明显"}, {"w": "卓著", "t": "突出的好"}, {"w": "著姓", "t": "有显著名声的家族;使姓氏显著"}, {"w": "著号", "t": "著名;著称。"}]}, {"meaning": "显现;显扬。", "cites": [{"t": "其不善而著其善。", "b": "《礼记·大学》"}, {"t": "诚则形,形则著。", "b": "《礼记·中庸》"}, {"t": "而日月之名久著于天地。", "b": "《韩非子·功名》"}, {"t": "病郑也。著郑伯之罪也。", "b": "《谷梁传·僖公六年》"}, {"t": "信义著于四海。", "b": "《三国志·诸葛亮传》"}, {"t": "以著其洁。", "b": "唐·柳宗元《柳河东集》"}, {"t": "最著者二。", "b": "清·侯方域《壮悔堂文集》"}]}, {"meaning": "又。", "cites": [{"t": "华林部独著。", "b": ""}], "words": [{"w": "颇著成效;著白", "t": "明白"}, {"w": "著相", "t": "佛教语。有意识地表现出来的形象状态。"}]}, {"meaning": "写作;撰述,用文字显明地表述。", "cites": [{"t": "始知文章合为时而著,歌诗合为事而作。", "b": "白居易《与元九书》"}, {"t": "仆诚已著此书。", "b": "汉·司马迁《报任安书》"}, {"t": "著《灵宪》。", "b": "《后汉书·张衡传》"}, {"t": "著书之日。", "b": "唐·柳宗元《柳河东集》"}, {"t": "携所著书。", "b": "清·梁启超《谭嗣同传》"}, {"t": "著之于所进呈书之中。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "著作郎", "t": "主管天下文章、著作的官吏"}, {"w": "著作人", "t": "古人称为著作者。指书籍的作者"}, {"w": "编著", "t": "参考利用已有的资料写成书。"}]}, {"meaning": "画图。", "cites": [{"t": "尧、舜所以昌,桀、纣所以亡,皆著于堂。", "b": "《淮南子》"}]}, {"meaning": "明了。", "cites": [{"t": "彼知丘之著于己也。", "b": "《庄子》"}]}, {"meaning": "登记,记载。", "cites": [{"t": "荆州非少人也,而著籍者寡。", "b": "《论游户自实》"}], "words": [{"w": "著令", "t": "书面写定的规章制度"}, {"w": "著名", "t": "写上名字或名称"}, {"w": "著籍", "t": "记姓名于宫门的门籍;记名于某学者门下为弟子;登记在户籍上。"}]}, {"meaning": "标出。", "cites": [{"t": "书其贾数而著其物,若今时题署物。", "b": "《周礼》"}]}, {"meaning": "建立;引申为成就。", "cites": [{"t": "故先王著其教焉。", "b": "《礼记》"}], "words": [{"w": "著庸", "t": "立功"}, {"w": "著称", "t": "命名。给予名称。"}]}, {"meaning": "土著 。指定居不迁的人。", "cites": [{"t": "流民占著者五万余口。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2199wx','菱','1','líng','艹','11','','[{"pinyin": "líng", "defs": [{"meaning": "柳叶菜科,菱属植物的泛称 。一年生水生草本,叶子略呈三角形,叶柄有气囊,夏天开花,白色。果实有硬壳,有角,可供食用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2200wx','勒','1','lè lēi lei','力','11','','[{"pinyin": "lè", "defs": [{"meaning": "(形声。从革,力声。从“革”,表示与皮革有关。本义:套在马头上带嚼子的笼头)。"}, {"meaning": "同本义。", "cites": [{"t": "勒,马头络衔也。", "b": "《说文》"}, {"t": "勒面绩总。", "b": "《周礼·巾车》"}, {"t": "案勒一具。", "b": "《汉书·匈奴传》。注:“马辔也。”"}, {"t": "弓矢鞍勒。", "b": "《后汉书·乌桓鲜卑传》"}, {"t": "缨辔贝勒。", "b": "《仪礼·既夕礼》"}], "words": [{"w": "马勒;勒面", "t": "古代马面饰。"}]}, {"meaning": "对数能量损失,中子能量损失的一种量度,等于中子初始能量与在慢化过程中任一点上能量之比的自然对数值。"}, {"meaning": "勒克司的简称(照度单位)。"}, {"meaning": "约束;收紧缰绳以止住马骡等或使马转身。", "cites": [{"t": "勒骐骥而更驾兮,造父为我操之。", "b": "《楚辞·九章·思美人》"}, {"t": "扬桴上陇坂,勒骑下平原。", "b": "虞世南《出塞》"}], "words": [{"w": "勒马;勒帛", "t": "系帛作腰带"}, {"w": "勒限", "t": "给一定的期限"}, {"w": "勒口", "t": "套上带嚼口的笼头"}, {"w": "勒子", "t": "妇女用的,由形如两片叶子连接起来的帽圈。"}]}, {"meaning": "统率。", "cites": [{"t": "勒兵,下令军中。", "b": "《史记·魏公子列传》"}], "words": [{"w": "勒兵", "t": "治军,操练或指挥军队,陈兵。检阅军队"}, {"w": "勒卒", "t": "部署、操练士卒"}, {"w": "亲勒六军", "t": ""}]}, {"meaning": "割,划。", "cites": [{"t": "宋江按住那婆娘,右手却早刀落,去那婆惜嗓子上只一勒,鲜血飞出。", "b": "《水浒传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "lēi", "defs": [{"meaning": "", "words": [{"w": "勒紧裤带", "t": ""}]}]}, {"pinyin": "lei", "defs": [{"meaning": "", "cites": [{"t": "[房钱]现在涨到五十块了,听说还要涨勒。", "b": "巴金《猪与鸡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2201wx','黄','1','huáng','黄','11','','[{"pinyin": "huáng", "defs": [{"meaning": "(象形。金文象蝗虫形。当是“蝗”的本字。本义:蝗虫)。"}, {"meaning": "黄色。", "cites": [{"t": "黄,地之色也。", "b": "《说文》"}, {"t": "黄为土色,位在中央。", "b": "《论衡·騐符》"}, {"t": "黄中之色也。", "b": "《左传·昭公十二年》"}, {"t": "黄者中也。", "b": "《礼记·郊特牲》"}, {"t": "天玄而地黄,解得黄矢。", "b": "《易·坤》"}, {"t": "绿衣黄里。", "b": "《诗·邶风·绿衣》"}, {"t": "绿衣黄裳。", "b": ""}, {"t": "千里黄云白日曛。", "b": "唐·高适《别董大》"}, {"t": "地履其黄。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "得张黄盖。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "黄烘烘", "t": "形容金黄色"}, {"w": "黄干干", "t": "形容很黄"}, {"w": "黄骝", "t": "黄红色的骏马"}, {"w": "黄盖", "t": "帝王车上所用的黄色车盖。"}]}, {"meaning": "垮掉,坏了事。", "cites": [{"t": "薛蟠听了这话,又怕闹黄了宝蟾之事,忙又赶来骂秋菱。", "b": "《红楼梦》"}]}, {"meaning": "黄赤色的马。", "cites": [{"t": "有骄有皇,有骊有黄。", "b": "《诗·鲁颂·駉》"}, {"t": "路车乘黄。", "b": "《诗·秦风·渭阳》"}]}, {"meaning": "金印。", "cites": [{"t": "怀银黄,垂三组。", "b": "《汉书·酷吏传·杨仆》"}, {"t": "佩紫怀黄。", "b": "南朝梁·丘迟《与陈伯之书》"}]}, {"meaning": "古国名 ,在今河南省潢川县西。"}, {"meaning": "粪便。", "cites": [{"t": "脐以上皮热,肠中热,则出黄如糜。", "b": "《灵枢经》"}]}, {"meaning": "牛黄。", "cites": [{"t": "牛有黄在胆。", "b": "宋·苏轼《格物粗谈》"}]}, {"meaning": "黄犬。", "cites": [{"t": "左牵黄,右擎苍。", "b": "宋·苏轼《江城子·密州出猎》"}]}, {"meaning": "热病。", "cites": [{"t": "古父老言五十年前,多患热黄。", "b": "唐·李肇《唐国史补》"}]}, {"meaning": "烟叶。", "cites": [{"t": "茶黄互市,为制夷之要。", "b": "清·魏源《默觚下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2202wx','菲','1','fēi fěi','艹','11','','[{"pinyin": "fēi", "defs": [{"meaning": "花草的香气很浓的——常叠用。", "cites": [{"t": "菲菲,香也。", "b": "《广雅》"}, {"t": "芳菲菲兮满堂。", "b": "《楚辞·东皇太一》"}, {"t": "别来春物已再菲,西望不见红日围。", "b": "苏轼《作书寄王晋卿忆前年寒食北城之游》"}], "words": [{"w": "菲薇", "t": "草木茂密的样子。"}]}, {"meaning": "一种无色结晶烃C14H10,熔点约100°C,其母核由某些生物碱降解生成,用于染料和药物的合成。"}, {"meaning": "菲律宾的简称。"}]}, {"pinyin": "fěi", "defs": [{"meaning": "(形声。从艹,非声。本义:菲菜,一种芜菁类植物。又名芴、刹恕⑼凉)?。"}, {"meaning": "同本义。", "cites": [{"t": "菲,芴也。", "b": "《说文》"}, {"t": "菲,芴。", "b": "《尔雅》。注:“即土瓜也。”"}, {"t": "采葑采菲。", "b": "《诗·邶风·谷风》"}], "words": [{"w": "采菲", "t": "采集菲菜。"}]}, {"meaning": "(fèi)。刖足,即断足,古代五刑之一。", "cites": [{"t": "治古无肉刑,而有象刑:墨黥;慅婴;共、艾毕;菲,对屦;杀、赭衣而不纯。", "b": "《荀子·正论》"}]}, {"meaning": "(fèi)。草鞋,蔴鞋。", "cites": [{"t": "不杖,不菲,不次。", "b": "《礼记·曾子问》"}, {"t": "手为错,足下无菲。", "b": "《古诗·孤儿行》"}]}, {"meaning": "微薄;使之微薄。", "cites": [{"t": "菲,薄也。", "b": "《小尔雅》"}, {"t": "不以菲废礼。", "b": "《礼记·坊记》"}, {"t": "菲饮食。", "b": "《论语》"}, {"t": "菲履赭衣。", "b": "《汉书·刑法志》。注:“草履也。”"}, {"t": "卑宫菲食。", "b": "陆机《辨亡论》"}], "words": [{"w": "菲陋", "t": "才学微薄"}, {"w": "菲葑", "t": "比喻微贱之人"}, {"w": "菲才寡学", "t": "才能小而学识浅"}, {"w": "菲己", "t": "待己菲薄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2203wx','萌','1','méng','艹','11','','[{"pinyin": "méng", "defs": [{"meaning": "(形声。从艸,明声。本义:草木的芽)。"}, {"meaning": "同本义。", "cites": [{"t": "萌,草芽也。", "b": "《说文》"}, {"t": "句者毕出,萌者尽达。", "b": "《礼记·月令》。注:“句,屈生者;芒而直曰萌。”"}, {"t": "乃舍萌于四方。", "b": "《周礼·春官·占梦》"}, {"t": "是其日夜之所息,雨露之所润,非无萌蘖之生焉。", "b": "《孟子·告子上》"}, {"t": "目注勾萌,以望其拆。", "b": "《聊斋志异·葛巾》"}], "words": [{"w": "萌甲", "t": "嫩芽,花木的芽苞。"}]}, {"meaning": "比喻事情刚刚显露的发展趋势或情况;开端。", "cites": [{"t": "圣人见微而知萌。", "b": "《韩非子·说林上》"}], "words": [{"w": "萌兆", "t": "预兆"}, {"w": "萌象", "t": "事物的萌芽和征象"}, {"w": "萌孽", "t": "祸端;邪恶。"}]}, {"meaning": "人民。", "cites": [{"t": "奸巧边萌。", "b": "《史记·三王世家》"}, {"t": "轨谓高田之萌曰。", "b": "《管子·山国轨》"}], "words": [{"w": "萌人", "t": "乡民"}, {"w": "萌俗", "t": "民俗"}, {"w": "萌庶", "t": "萌隶。百姓"}, {"w": "萌黎", "t": "人民,平民"}, {"w": "萌隶", "t": "平民,人民。"}]}, {"meaning": "农民。", "cites": [{"t": "四鄙之萌人闻之。", "b": "《墨子·尚贤上》"}]}, {"meaning": "草木发芽。", "cites": [{"t": "草木萌动。", "b": "《礼记·月令》"}], "words": [{"w": "萌茁", "t": "草木发芽"}, {"w": "萌动", "t": "开始发芽"}, {"w": "萌发", "t": "发芽。"}]}, {"meaning": "开始;产生。", "cites": [{"t": "知者见于未萌。", "b": "《商君书·更法》"}, {"t": "亲法,则奸无所萌。", "b": "《韩非子·心度》"}, {"t": "今日反情已萌,可速诛之。", "b": "《三国演义》"}], "words": [{"w": "萌阳", "t": "新生的阳气。我国古代谓宇宙间有阴阳二气,阴主衰落,而阳主新生"}, {"w": "萌达", "t": "发生滋长"}, {"w": "萌通", "t": "萌发生长"}, {"w": "萌起", "t": "开始;发生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2204wx','萝','1','luó','艹','11','','[{"pinyin": "luó", "defs": [{"meaning": "(形声。从艸,罗声。本义:植物名。指某些蔓生植物,即“莪”) 同本义。", "cites": [{"t": "萝,莪也。蒿属。", "b": "《说文》"}], "words": [{"w": "女萝;藤萝;茑萝;萝蓏", "t": "女萝和瓜类。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2205wx','菌','1','jūn jùn','艹','11','','[{"pinyin": "jūn", "defs": [{"meaning": "低等植物的一大类,不开花,没有茎和叶子,不含叶绿素,不能自己制造养料,靠寄生生活,种类很多如细菌、真菌等。"}]}, {"pinyin": "jùn", "defs": [{"meaning": "", "words": [{"w": "菌芝", "t": "即灵芝"}, {"w": "菌阁", "t": "形如菌状之阁"}, {"w": "菌蟪", "t": "朝菌和蟪蛄"}, {"w": "菌蠢", "t": "谓如菌类之短小丛生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2206wx','萎','1','wěi','艹','11','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从艸,委声。本义:枯槁、凋谢)。"}, {"meaning": "同本义。", "cites": [{"t": "萎,蔫也。", "b": "《广韵》"}, {"t": "萎,草木枯死。", "b": "《集韵》"}, {"t": "虽萎绝其何伤兮,哀众芳之芜秽。", "b": "《楚辞·离骚》"}, {"t": "萎,草木菸也。", "b": "《一切经音义》九引声类"}, {"t": "无木不萎。", "b": "《诗·小雅·谷风》"}], "words": [{"w": "萎绝", "t": "草木枯落"}, {"w": "萎枯", "t": "干枯"}, {"w": "萎败", "t": "枯萎"}, {"w": "萎悴", "t": "枯萎;憔悴。"}]}, {"meaning": "引申指病危。", "cites": [{"t": "哲人其萎乎?", "b": "《礼记·檀弓上》。注:“萎,病也。”"}, {"t": "虽萎绝其亦何伤兮!", "b": "《楚辞·离骚》"}], "words": [{"w": "萎约", "t": "身体患病并陷穷困"}, {"w": "萎折", "t": "死亡"}, {"w": "萎哲", "t": "指有才智者之死亡"}, {"w": "萎绝", "t": "死亡;消亡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2207wx','菜','1','cài','艹','11','','[{"pinyin": "cài", "defs": [{"meaning": "(形声。采声。上古时期,菜只指蔬菜,不包括肉类、蛋类,到了中古以后,菜就包括内类、蛋 类及其熟食在内了。本义:蔬菜)。"}, {"meaning": "同本义。", "cites": [{"t": "菜,草之可食者。", "b": "《说文》"}, {"t": "皮弁祭菜。", "b": "《礼记·学记》。注:“芹藻之属。”"}, {"t": "习舞释菜。", "b": "《礼记·月令》"}, {"t": "乃奠菜。", "b": "《仪礼·士昏礼》"}, {"t": "古禹十年水,汤七年旱,而天下无菜色者。", "b": "《荀子·富国》"}, {"t": "孙叔敖相楚,栈车牝马,粝饼菜羹。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "种菜;干菜", "t": "晒干的蔬菜"}, {"w": "菜食", "t": "以食菜为主。"}]}, {"meaning": "按特殊风味制作的食品。", "cites": [{"t": "饭菜精洁,醢酱调美。", "b": "《北史·胡叟传》"}], "words": [{"w": "中国菜;素菜;川菜;广东菜;荤菜", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2208wx','萄','1','táo','艹','11','','[{"pinyin": "táo", "defs": [{"meaning": "——如“葡萄”（pútao）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2209wx','菊','1','jú','艹','11','','[{"pinyin": "jú", "defs": [{"meaning": "(形声。从艸,匊(jú)声。本义:植物名,通称“菊花”)。"}, {"meaning": "同本义 。多年生草本植物。叶子卵形有柄,边缘有缺刻或锯齿。秋季开花,供观赏,有的品种可入药。", "cites": [{"t": "采菊东篱下。", "b": "晋·陶渊明《饮酒诗》"}, {"t": "松菊犹存。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "还束就菊花。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "陶渊明独爱菊。", "b": "宋·周敦颐《爱莲说》"}, {"t": "菊,花之隐逸者。", "b": ""}, {"t": "菊之爱,陶后鲜有闻。", "b": ""}], "words": [{"w": "菊实", "t": "菊花的果实、种子"}, {"w": "菊枕", "t": "菊花枕头"}, {"w": "菊灯", "t": "菊花形状的灯笼"}, {"w": "菊水", "t": "在河南省西南部。古作“鞠水”,也叫“菊潭。”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2210wx','菩','1','pú','艹','11','','[{"pinyin": "pú", "defs": [{"meaning": "菩提(音译):意为正觉。指对佛教“真理”的觉悟。", "cites": [{"t": "菩,梵言菩提,汉言王道。", "b": "《广韵》"}]}, {"meaning": "又指觉悟的智慧和觉悟的途径;亦指树名,即菩提树。"}, {"meaning": "“菩萨”:佛教名词。梵文菩提萨埵(Bodhi-sattva)之省,原为释迦牟尼修行而未成佛时的称号,后泛用为对大乘思想的实行者的称呼;亦指人们崇拜的偶像;或比喻心肠仁慈的人。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2211wx','萍','1','píng','艹','11','','[{"pinyin": "píng", "defs": [{"meaning": "(会意兼形声。从水,苹,苹亦声。本义:浮萍) 同本义。", "cites": [{"t": "萍,苹也。水草也。", "b": "《说文》"}, {"t": "蓱始生。", "b": "《礼记·月令》。注:“蓱,萍也。其大者曰蘋。”"}, {"t": "山河破碎风飘絮,身世浮沉雨打萍。", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "萍合", "t": "浮萍易散,飘泊不定,故用以比喻暂时的聚合"}, {"w": "萍浮", "t": "浮萍飘迹水面。比喻人行踪飘泊不定"}, {"w": "萍飘梗泛", "t": "踪迹飘泊无定"}, {"w": "萍迹", "t": "喻人四处飘流,行踪无定"}, {"w": "萍流", "t": "飘流。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2212wx','菠','1','bō','艹','11','','[{"pinyin": "bō", "defs": [{"meaning": "藜科。一二年生草本，叶子略呈三角形，根略带红色，雌雄异株。原产伊朗。现为我国主要食用菜之一。"}, {"meaning": "凤梨科，多年生草本。叶大，边缘有锯齿；果实香甜，外部呈鳞片状。产于热带，我国广东、广西、台湾等地均有种植。又叫凤梨。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2213wx','萤','1','yíng','艹','11','','[{"pinyin": "yíng", "defs": [{"meaning": "动物名。节肢动物门,昆虫纲。萤火虫。", "cites": [{"t": "萤,萤火。", "b": "《广韵》"}, {"t": "萤火獜也。", "b": "《广雅》"}, {"t": "腐草为萤。", "b": "《礼记·月令·季夏》。注:“萤,飞虫营火也。”"}, {"t": "红烛秋光冷画屏,轻罗小扇扑流萤。", "b": "唐·杜牧《秋夕》诗"}], "words": [{"w": "萤焰", "t": "萤火虫发出的亮光"}, {"w": "萤光", "t": "萤火虫发出的光"}, {"w": "萤点", "t": "指萤火虫"}, {"w": "萤案", "t": "用萤光照明,以诵读诗书"}, {"w": "萤烛", "t": "萤光与烛光。比喻微光、微力。"}]}, {"meaning": "比喻微弱的亮光。", "cites": [{"t": "长河晴散雾,列宿曙分萤。", "b": "唐·韩愈《和崔舍人·咏月》"}], "words": [{"w": "萤灯", "t": "喻灯光微弱如萤火"}, {"w": "萤囊", "t": "晋车胤家贫,夏夜读书,以囊盛萤火照明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2214wx','营','1','yíng','艹','11','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从宫,荧(yíng)省声。宫,房子,与居住有关。本义:四周垒土而居)。"}, {"meaning": "同本义。", "cites": [{"t": "营,币居也。", "b": "《说文》。段玉裁注:“币居,谓围绕而居。”桂馥义证:“营谓周垣。”"}, {"t": "众目营方。", "b": "《五等论》。注:“布居也。”"}, {"t": "冬则居营窟。", "b": "《礼记·礼运》。按,四围拥土也。"}]}, {"meaning": "围绕;缠绕。", "cites": [{"t": "以朱丝营社。", "b": "《公羊传·庄公二十五年》"}, {"t": "日中,为大臣欺诬;日且入,为妻妾役使所营。", "b": "《汉书》"}], "words": [{"w": "营回", "t": "萦回,盘旋往复"}, {"w": "营合", "t": "环绕合拢,形成包围圈"}, {"w": "营周", "t": "循环"}, {"w": "营绕", "t": "环绕。"}]}, {"meaning": "建造。", "cites": [{"t": "尝加营葺。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "营作", "t": "建造"}, {"w": "营宫", "t": "营建宫室"}, {"w": "营饰", "t": "建筑装璜"}, {"w": "营筑", "t": "建筑;修建"}, {"w": "营缮", "t": "修缮,修建"}, {"w": "营绘", "t": "营建绘饰。"}]}, {"meaning": "经营。", "cites": [{"t": "召伯营之。", "b": "《诗·小雅·黍苗》"}, {"t": "如有营。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "私营", "t": "私人经营"}, {"w": "营市", "t": "经商。"}]}, {"meaning": "测量;度量。", "cites": [{"t": "营,度也。", "b": "《广雅》"}, {"t": "圜测九重,孰营度之?", "b": "《楚辞·天问》"}]}, {"meaning": "谋求。", "cites": [{"t": "问我得钱何所营。", "b": "唐·白居易《卖炭翁》"}, {"t": "百计营谋不能脱。", "b": "《聊斋志异》。又如:营活(谋生);营己(谋求自己的利益);营内(为后宫谋利);营谋(谋求);营虑(操心);营图(图谋);营谋(为达某一目的而想方设法)"}]}, {"meaning": "迷惑。", "cites": [{"t": "精神乱营。", "b": "《淮南子·原道》"}, {"t": "不足以营其精神。", "b": ""}, {"t": "则目不营于色。", "b": "《淮南子·本经》"}, {"t": "所以营或耳目。", "b": "《汉书·刘向传》"}], "words": [{"w": "营勾", "t": "勾引;勾搭"}, {"w": "营罔", "t": "迷惑、欺骗"}, {"w": "营信", "t": "受迷惑而相信"}, {"w": "营众", "t": "惑众。"}]}, {"meaning": "耕作。", "cites": [{"t": "或从十五北防河,便至四十西营田。", "b": "杜甫《兵车行》"}]}, {"meaning": "军营,营寨。", "cites": [{"t": "营中之事。", "b": "诸葛亮《出师表》"}, {"t": "出营立观。", "b": "《资治通鉴》"}, {"t": "撤兵移营。", "b": "《广东军务记》"}, {"t": "驰入仆营。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "营防", "t": "营防及防御工事"}, {"w": "营门", "t": "军营之门"}, {"w": "营卫", "t": "军营的护卫"}, {"w": "营壁", "t": "营垒。"}]}, {"meaning": "军队编制的一级,主要由一个司令部和两个以上的连、炮兵连或类似单位组成。", "cites": [{"t": "营哨各官。", "b": "清·梁启超《谭嗣同传》。又如:营长;营副"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2215wx','乾','1','qián gān','乙','11','','[{"pinyin": "qián", "defs": [{"meaning": "(俗作乹。形声。从乙,倝声(gàn)。乙,象植物屈曲生长的样子。本义:上出) 同本义。", "cites": [{"t": "乾,上出也。", "b": "《说文》。段注:此乾字之本义也。自有文字以后,乃用为卦名,而孔子释之曰健也。健之义生于上出,上出为乾,下注则为湿,故乾与湿相对,俗别其音,古无是也。”"}]}, {"meaning": "八卦的首卦;天。", "cites": [{"t": "达于上者谓之乾。凡上达者莫若气,天为积气,故乾为天。", "b": "朱骏声《说文通训定声》"}, {"t": "乾,天也。", "b": "《易·说卦传》"}, {"t": "乾,阳物也。", "b": "《易·系辞传》"}, {"t": "乾刚坤柔。", "b": "《易·杂卦传》"}, {"t": "乾为天、为圜、为君、为父、为玉、为金、为寒、为冰、为大赤、为良马、为老马、为瘠马、为驳马、为木果。", "b": "《易·说卦》"}], "words": [{"w": "乾方", "t": "天方"}, {"w": "乾元", "t": "天"}, {"w": "乾施", "t": "上天的施予"}, {"w": "乾首", "t": "天的高处"}, {"w": "乾刚", "t": "天道刚健"}, {"w": "乾象", "t": "天象"}, {"w": "乾启", "t": "上天的启示"}, {"w": "乾钧", "t": "天钧,北极之地,泛指北方"}, {"w": "乾道", "t": "天道。"}]}, {"meaning": "姓。"}]}, {"pinyin": "gān", "defs": [{"meaning": "沒有水分或缺乏水分的。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2216wx','萧','1','xiāo','艹','11','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从艸,肃声。本义:艾蒿)。"}, {"meaning": "同本义。", "cites": [{"t": "萧,艾蒿也。", "b": "《说文》"}, {"t": "萧萩。", "b": "《尔雅》。注:“即蒿。”"}, {"t": "共萧茅。", "b": "《周礼·甸师》"}, {"t": "彼采萧兮。", "b": "《诗·王风·采葛》"}], "words": [{"w": "萧艾", "t": "臭草名。比喻不肖或平凡无才"}, {"w": "萧敷艾荣", "t": "比喻凡事委曲求全,以致飞黄腾达。"}]}, {"meaning": "古国名 。春秋时宋的附庸,灭于楚。地在今安徽省萧县西北。", "cites": [{"t": "楚子伐萧。", "b": "《左传》"}]}, {"meaning": "县名 。在安徽省北端,东邻江苏省,西接河南省。秦置县。"}, {"meaning": "", "cites": [{"t": "萧君圭君玉(萧君圭,字君玉)。", "b": "宋·王安石《游褒禅山记》"}]}, {"meaning": "萧条,冷落;荒凉。", "cites": [{"t": "天寒夜长,风气萧索,鸿雁于征,草木黄落。 ", "b": "晋·陶潜《自祭文》"}, {"t": "蚊蚋归丰草,枯叶散萧林。", "b": "晋·刘伶《北芒客舍》"}, {"t": "满目萧然。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "屋舍萧然。", "b": "清·张廷玉《明史》"}], "words": [{"w": "萧屑", "t": "凄凉寂寞"}, {"w": "萧梢", "t": "草木凋落而萧条的景象。"}]}, {"meaning": "稀疏。", "cites": [{"t": "说到知音,自古无多,白发萧疏,青灯寂寞,老子婆娑。", "b": "元·张可久《折桂令·读史有感》"}], "words": [{"w": "萧然;萧瑟", "t": ""}]}, {"meaning": "(sù)。恭敬;严肃。", "cites": [{"t": "吾恐季孙之忧,不在颛臾而在萧墙之内也。", "b": "《论语·季氏》"}, {"t": "此皆衅发萧墙而祸延四海者也。", "b": "《后汉书·傅蘷传》"}]}, {"meaning": "洒脱。", "cites": [{"t": "下泊降茅仙,萧闲隐洞天。", "b": "唐·顾况《山居即事》"}], "words": [{"w": "萧闲", "t": "洒脱悠闲"}, {"w": "萧放", "t": "萧洒放浪"}, {"w": "萧远", "t": "萧洒远逸。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
