INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2219wx','械','1','xiè','木','11','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从木,戒声。本义:脚镣手铐一类的刑具)。"}, {"meaning": "同本义。", "cites": [{"t": "械,桎梏也。", "b": "《说文》"}, {"t": "拘罪人曰桁械。谓穿木加足曰械,大械曰桁。", "b": "《通俗文》"}, {"t": "在手曰械。", "b": "《后汉书·吴传》注"}, {"t": "械系敬广武。", "b": "《汉书·娄敬传》"}, {"t": "三缢加别械。", "b": "清·方苞《狱中杂记》"}, {"t": "求脱械。", "b": ""}, {"t": "地上刑械。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "械送", "t": "加刑具押送"}, {"w": "械索", "t": "泛指刑具。用刑具拷掠"}, {"w": "械节", "t": "枷械等刑具的结合处"}, {"w": "械解", "t": "戴上刑具押送"}, {"w": "械颈", "t": "加械于颈。"}]}, {"meaning": "器械,用具。", "cites": [{"t": "有械于此,一日浸百畦。", "b": "《庄子·天地》"}, {"t": "云梯之械。", "b": "《墨子公输》"}, {"t": "攻械尽。", "b": ""}, {"t": "以牒为械。", "b": ""}], "words": [{"w": "械用", "t": "器械用具"}, {"w": "械器", "t": "器械;器具"}, {"w": "械具", "t": "机械用具。"}]}, {"meaning": "拘系;枷住;拘束。", "cites": [{"t": "苟入狱,不问罪之有无,必械手足。", "b": "清·方苞《狱中杂记》"}, {"t": "半与城门充校尉,谁将斜谷械阳陵。", "b": "龚自珍《己亥杂诗》"}], "words": [{"w": "械致", "t": "拘系押送"}, {"w": "械槛", "t": "拘系于囚车。"}]}, {"meaning": "治。", "cites": [{"t": "桥揉斤械。", "b": "《文选·马融·长笛赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2220wx','彬','1','bīn','彡','11','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从彡(shān),焚省声(省去“火”)。本义:文质兼备的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "份,文质备也。《论语》曰:“文质份份。”彬,古文份。", "b": "《说文》"}, {"t": "文质彬彬。", "b": "《论语·雍也》。集解引包注:“彬彬,文质相半之貌。”"}, {"t": "孝哀彬彬。", "b": "《汉书·系传下》"}]}, {"meaning": "富有文采的。", "cites": [{"t": "颂优游以彬蔚,论精微而朗畅。", "b": "陆机《文赋》"}], "words": [{"w": "彬驳", "t": "文采错杂的样子"}, {"w": "彬彬君子", "t": "文质兼备的人"}, {"w": "彬彬济济", "t": "人才盛多的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2221wx','梦','1','mèng','木','11','','[{"pinyin": "mèng", "defs": [{"meaning": "(会意。小篆字形,由“宀”(房子)、“爿”(床)、“夢”(不明也)三字合成。意为夜间在床上睡觉,眼前模糊看不清,即作梦。“夢”由“苜”(mò,眼看不清)、“宀”(人的变形)、“夕”(晚间)三字会意。本义:睡眠中的幻象)。"}, {"meaning": "同本义。", "cites": [{"t": "妇梦中咳嗽。", "b": "《虞初新志·秋声诗自序》"}, {"t": "铁马冰河入梦来。", "b": "宋·陆游《十一月四日风雨人作》"}, {"t": "形诸梦。", "b": "清·袁枚《黄生借书说》"}, {"t": "梦中得我。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "梦迷", "t": "梦后刚醒,尚未完全摆脱梦境"}, {"w": "梦梦铳铳", "t": "形容睡得迷迷糊糊"}, {"w": "梦梦查查", "t": "迷迷糊糊"}, {"w": "梦思", "t": "梦中的思念"}, {"w": "梦中梦", "t": "喻幻境。极言虚幻"}, {"w": "梦中", "t": "睡梦之中"}, {"w": "梦语", "t": "睡梦中说的话"}, {"w": "梦啼妆泪红阑干(梦中啼哭,擦了脂粉的脸上流满了一道道红色的(泪痕)妆,这里指脸上的脂粉阑干,纵横错乱的样子)", "t": ""}]}, {"meaning": "做梦。", "cites": [{"t": "王梦见一儿。", "b": "晋·干宝《搜神记》"}, {"t": "卧则梦闻。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "我欲因之梦吴越。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "夜深忽梦少年事。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "梦枕", "t": "传说中会使人做梦的枕头"}, {"w": "梦花", "t": "梦见花朵。指汉·马融梦食花,文思大进事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2222wx','婪','1','lán','女','11','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从女,林声。本义:贪食)。"}, {"meaning": "同本义。", "cites": [{"t": "婪,贪也。", "b": "《说文》"}, {"t": "贪惏无厌。", "b": "《左传·昭公二十八年》"}, {"t": "众皆竞进而贪婪兮,冯不厌乎求索。", "b": "《楚辞·离骚》。注:“爱财曰贪,爱食曰婪。”"}, {"t": "婪酣大肚遭一饱。", "b": "韩愈《月蚀诗效玉·川子作》"}, {"t": "澄当婪尾,则知婪为自谦之辞。", "b": "《唐音癸签》"}, {"t": "贪婪无餍。", "b": "《左传·昭公二十八年》"}], "words": [{"w": "婪取", "t": "贪婪索取"}, {"w": "婪沓", "t": "贪婪"}, {"w": "婪官", "t": "贪官"}, {"w": "婪酣", "t": "贪婪饮食"}, {"w": "婪肆", "t": "贪赃不法。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2223wx','梗','1','gěng','木','11','','[{"pinyin": "gěng", "defs": [{"meaning": "(形声。从木,更声。本义:一种树)。"}, {"meaning": "刺榆(Hemiptelea davidii)的古名。", "cites": [{"t": "梗,山枌榆。荚可为芜荑也。", "b": "《说文》。按,叶小于常榆,刺如柘刺,其木坚韧,中犊车材,即诗之山有枢。"}]}, {"meaning": "有刺的草木。", "cites": [{"t": "凡草木刺人,自关而东,或谓之梗。", "b": "《西京赋》"}, {"t": "梗木为之靡拉。", "b": "《方言三》"}], "words": [{"w": "梗林", "t": "多刺的林丛"}, {"w": "梗莽", "t": "荆棘草莽"}, {"w": "梗刺", "t": "草木茎上有刺针。"}]}, {"meaning": "草本植物的枝茎。", "cites": [{"t": "桃梗土偶。", "b": "《战国策·秦策》"}, {"t": "今求柴胡桔梗于沮泽。", "b": "《战国策·齐策》"}], "words": [{"w": "菠菜梗;梗子", "t": "植物的枝或茎"}, {"w": "荷梗;芹菜梗", "t": ""}]}, {"meaning": "阻塞;阻碍。", "cites": [{"t": "元恶未黜,天邑犹梗。", "b": "《梁书·高帝纪》"}, {"t": "是时道路梗涩,人怀危惧,承每遇艰险,处之夷然。", "b": "《晋书·王承传》"}], "words": [{"w": "梗涩", "t": "阻塞难通"}, {"w": "梗化", "t": "阻塞教化;妨碍管教"}, {"w": "梗滞", "t": "阻塞"}, {"w": "梗拒", "t": "阻拦拒绝"}, {"w": "梗沮", "t": "阻扰;干扰"}, {"w": "梗碍", "t": "阻塞。"}]}, {"meaning": "假借为“抗”。抵御;抗拒。", "words": [{"w": "梗命", "t": "抗命"}, {"w": "梗寇", "t": "作梗御寇"}, {"w": "梗骜", "t": "亦指桀骜不驯的人。"}]}, {"meaning": "食留咽中。", "cites": [{"t": "谁生厉阶,至今为梗。", "b": "《诗·大雅·桑柔》"}]}, {"meaning": "耿直,刚正。", "cites": [{"t": "子文都,性梗直,仕周,为右侍上士。", "b": "《北史·汝阴王天赐传》附修义"}], "words": [{"w": "梗梗", "t": "正直坚定的样子"}, {"w": "梗令之人", "t": "梗直的人"}, {"w": "梗野", "t": "率直粗鲁。"}]}, {"meaning": "强硬;凶猛。", "cites": [{"t": "梗,猛也。", "b": "《方言二》"}, {"t": "锄其强梗。", "b": "《淮南子·原道》"}], "words": [{"w": "梗化", "t": "强硬"}, {"w": "梗悍", "t": "强横"}, {"w": "梗强", "t": "强横凶暴。"}]}, {"meaning": "大略。", "cites": [{"t": "略举其梗概。", "b": "左思《吴都赋》。注:“粗言也。”"}, {"t": "概,略也。", "b": "《方言十三》"}], "words": [{"w": "梗概;梗迹", "t": "隐约细微的行迹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2224wx','梧','1','wú','木','11','','[{"pinyin": "wú", "defs": [{"meaning": "屋梁上两头起支架作用的斜柱。", "cites": [{"t": "斜柱,其名有五:一曰斜柱,二曰梧,三曰迕,四曰枝樘,五曰叉手。", "b": "《营造法式》"}]}, {"meaning": "古地名。"}, {"meaning": "在今河南省荥阳县附近。", "cites": [{"t": "晋师城梧及制。", "b": "《左传》"}]}, {"meaning": "在今江苏省徐州西部。", "cites": [{"t": "楚国,县七…梧。", "b": "《汉书》"}]}, {"meaning": "支撑。", "cites": [{"t": "炳乃故升茅屋,梧鼎而爨。", "b": "《后汉书》"}]}, {"meaning": "违背;抵触。", "cites": [{"t": "甚多疏略,或有抵梧。", "b": "《汉书·司马迁传》。颜师古云:梧,相支柱不安也。"}]}, {"meaning": "俣俣,魁伟貌。", "cites": [{"t": "余以为其人计魁梧奇伟。", "b": "《史记·留侯世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2225wx','梢','1','shāo','木','11','','[{"pinyin": "shāo", "defs": [{"meaning": "(形声。从木,肖声。本义:树木的末端)。"}, {"meaning": "同本义。", "cites": [{"t": "梢,梢木也。", "b": "《说文》"}, {"t": "梢,梢擢。", "b": "《尔雅》。注:“谓木无枝柯,梢擢长而杀者。”"}, {"t": "开花寄树梢。", "b": "白居易《有木诗》"}, {"t": "高者挂罥长林梢。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "树梢;枝梢", "t": ""}]}, {"meaning": "树木的枝条。", "cites": [{"t": "曳梢肆柴。", "b": "《淮南子·兵略》。注:“小柴也。”"}], "words": [{"w": "梢头;梢条;梢棒", "t": "亦作“哨棒”。一种兵器,木棒。"}]}, {"meaning": "事物的末尾或一段时间的尽头。", "cites": [{"t": "被云梢。", "b": "《汉书·扬雄传》"}], "words": [{"w": "眉梢;春梢", "t": ""}]}, {"meaning": "舵尾。", "cites": [{"t": "梢,船舵尾也。", "b": "《广韵》。又如:在梢上坐着"}]}, {"meaning": "竹竿。", "cites": [{"t": "饰玉梢以舞歌,体招摇若永望。", "b": "《汉书·礼乐志》"}]}, {"meaning": "一伙人。", "cites": [{"t": "隐约下来一梢人。", "b": "《吕梁英雄传》"}]}, {"meaning": "击,冲激;扫。", "cites": [{"t": "梢沟三十里而广倍。", "b": "《周礼·考工记·匠人》"}], "words": [{"w": "叫兔鹘梢了一翅膀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2226wx','梅','1','méi','木','11','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从木,每声。本义:楠木)。"}, {"meaning": "同本义。", "cites": [{"t": "其木多梅梓。", "b": "《山海经·中山经》"}, {"t": "有条有梅。", "b": "《诗·秦风·终南》"}, {"t": "墓门有梅。", "b": "《诗·陈风·墓门》。按,子青不可食。"}]}, {"meaning": "梅树 。蔷薇科,落叶乔木,少有灌木。早春开花,后生叶芽。花以白色、淡红色为主。气味清香。核果近球形,未熟时为青色,成熟后一般呈黄色,味极酸。", "cites": [{"t": "灵山其木多桃李梅杏。", "b": "《山海经·中山经》"}, {"t": "梅之欹之疏之曲,又非……之民能以其智力为也。", "b": "清·龚自珍《病梅馆记》"}, {"t": "梅以曲为美,直则无姿;以欹为美,正则无景;以疏为美……", "b": ""}]}, {"meaning": "梅树的果实,称酸果,即酸梅子。", "cites": [{"t": "摽有梅。", "b": "《诗·召南·摽有梅》。陆疏:“杏类也。”"}], "words": [{"w": "梅仁", "t": "梅实之仁"}, {"w": "梅瓜", "t": "以梅子汁腌制的瓜"}, {"w": "梅汁", "t": "梅子制成的调味汁液或饮料"}, {"w": "梅林止渴", "t": "犹言望梅止渴。"}]}, {"meaning": "马鞭。", "cites": [{"t": "穆王七梅,夫何为周流?", "b": "《楚辞·天问》"}]}, {"meaning": "", "cites": [{"t": "入榛薄,食荐梅。", "b": "《淮南子·览冥》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2227wx','检','1','jiǎn','木','11','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从木,佥(qiān)声。本义:书匣上的标签)。"}, {"meaning": "同本义。", "cites": [{"t": "检,书署也。", "b": "《说文》。按,今字作签。"}, {"t": "辄皂囊施检。", "b": "《后汉书·公孙瓒传》"}], "words": [{"w": "检封", "t": "缄封,封藏"}, {"w": "检素", "t": "封好的信,书信。"}]}, {"meaning": "法式,法度。", "cites": [{"t": "检,法度也。", "b": "《苍颉篇》"}, {"t": "然物有恒姿,而思无定检。", "b": "《文心雕龙·物色》"}], "words": [{"w": "检式", "t": "法式;制度"}, {"w": "检押", "t": "也作“检柙”,“检狎”。规矩,法度;或匡正。"}]}, {"meaning": "品行;节操。", "cites": [{"t": "初,朗少时虽涉猎文学,然不治素检,以吏能见称。", "b": "《三国志》"}]}, {"meaning": "约束,限制。", "cites": [{"t": "德亡首褒不检。", "b": "《汉书·王莽传》。注:“局之。”"}, {"t": "自此致身绳检外,肯教世路日兢兢。", "b": "司徒空《退栖》"}], "words": [{"w": "检束", "t": "整顿好行装"}, {"w": "检勑", "t": "检点,整饬"}, {"w": "检邪", "t": "制止邪气"}, {"w": "检勒", "t": "检点约束"}, {"w": "检局", "t": "约束,节制。"}]}, {"meaning": "考查,察验。", "cites": [{"t": "骠骑执法以检下。", "b": "《后汉书·周黄徐姜申屠传》。注:“犹察也。”"}], "words": [{"w": "检还", "t": "查点清楚后归还"}, {"w": "抄检", "t": "搜查,查抄"}, {"w": "检尸", "t": "验尸"}, {"w": "检视", "t": "检查,料理"}, {"w": "检详", "t": "审查考核。"}]}, {"meaning": "收敛,约束言行;收聚。", "cites": [{"t": "检身若不及。", "b": "《书·伊训》。《正义》云:检,谓自摄敛也。"}, {"t": "狗彘食人食而不知检。", "b": "《孟子·梁惠王上》"}, {"t": "此数检百里之地也。", "b": "《管子·山权数》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2228wx','梳','1','shū','木','11','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从木,疏省声。本义:梳子) 同本义。", "cites": [{"t": "梳,理发也。", "b": "《说文》"}, {"t": "梳,栉也。", "b": "《广雅》"}, {"t": "梳,言其齿疏也。", "b": "《释名》"}, {"t": "朝有讽谏,犹发之有梳。", "b": "《新唐书·吴兢传》"}], "words": [{"w": "木梳;梳枇", "t": "齿稀的叫梳,齿密的叫枇"}, {"w": "梳掠", "t": "梳子。小的叫梳,大的叫掠"}, {"w": "梳行", "t": "买卖梳子的牙行"}, {"w": "梳背", "t": "压发梳一类妆饰品"}, {"w": "梳掌", "t": "梳子的柄。"}]}, {"meaning": "用梳整理头发。", "cites": [{"t": "头蓬不暇梳。", "b": "杨雄《长杨赋》"}, {"t": "贼如梳,军如篦。", "b": "《明史·洪钟传》"}, {"t": "绿云扰扰,梳晓鬟也。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "予九岁,憩书斋,汝梳双髻,披单缣来,温《缁衣》一章。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "梳云", "t": "梳整像乌云一般的头发"}, {"w": "梳裹", "t": "梳理头发包裹头巾。指化妆"}, {"w": "梳沐", "t": "梳洗"}, {"w": "梳雪", "t": "梳理白发"}, {"w": "梳栉", "t": "梳理头发。"}]}, {"meaning": "整理。", "cites": [{"t": "白鸟梳翎立岸莎。", "b": "温庭筠《游南塘》"}], "words": [{"w": "梳爬", "t": "整理"}, {"w": "梳翎", "t": "鸟类梳理自身羽毛。"}]}, {"meaning": "梳笼;梳拢;梳弄 。指妓女首次按客伴宿。", "cites": [{"t": "这等就说标致;他家里还有一个粉头,排行三姐,号“玉堂春”,有十二分颜色。鸨儿索价太高,还未梳栊。", "b": "《警世通言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2229wx','梯','1','tī','木','11','','[{"pinyin": "tī", "defs": [{"meaning": "(形声。从木,弟声。本义:便利人上下攀登(尤其建筑物)的用具或设备)。"}, {"meaning": "同本义。", "cites": [{"t": "梯,木阶也。", "b": "《说文》"}, {"t": "为云梯之械。", "b": "《史记·孟荀传》"}, {"t": "闻子为梯。", "b": "《墨子·公输》"}, {"t": "身登青云梯。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "梯而下之。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "(梯,名词用如动词,用梯子。)。", "cites": [{"t": "悬者通梯接之。", "b": "《徐霞客游记·游黄山记》"}, {"t": "梯冲死土。", "b": "清·邵长衡《青门剩稿》"}], "words": [{"w": "楼梯;云梯", "t": "攻城或救火时用的长梯"}, {"w": "阶梯", "t": "台阶和梯子"}, {"w": "梯航", "t": "梯与船"}, {"w": "梯梁", "t": "凿梯架桥"}, {"w": "梯磴", "t": "梯子的梯级"}, {"w": "软梯", "t": ""}]}, {"meaning": "形状像梯的分级的东西。", "cites": [{"t": "梯,阶也。", "b": "《广雅》"}, {"t": "蹝步陵丹梯。", "b": "谢灵运诗"}, {"t": "以为乱梯。", "b": "《国语·越语》。注:“阶也。”"}], "words": [{"w": "梯田;梯桥", "t": "设于园圃之中,供游览用的梯形通道。"}]}, {"meaning": "凭,依着。", "cites": [{"t": "梯,凭也,若梯邪倚著也。", "b": "《字汇》"}, {"t": "西王母梯几而戴胜杖。", "b": "《山海经》"}]}, {"meaning": "用梯子攀登 。", "words": [{"w": "梯登", "t": "缘梯攀登"}, {"w": "梯城", "t": "缘梯登城。"}]}, {"meaning": "攀登。", "cites": [{"t": "航海梯山各一家。", "b": "黄庭坚《和中玉使君晚秋开天宁节道场》"}], "words": [{"w": "梯山航海;梯霞", "t": "道教谓升天登仙"}, {"w": "梯崖;梯陟", "t": "登高攀险"}, {"w": "梯林", "t": "攀登山林"}, {"w": "梯附", "t": "攀附。"}]}, {"meaning": "谋求 。", "words": [{"w": "梯肥", "t": "谋取肥缺"}, {"w": "梯荣", "t": "谋求禄位。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2230wx','桶','1','tǒng','木','11','','[{"pinyin": "tǒng", "defs": [{"meaning": "(形声。从木,甬(yǒng)声。本义:量器名)。"}, {"meaning": "古量器名。方形斛。", "cites": [{"t": "桶,木方,受六升。", "b": "《说文》。段玉裁注:“疑当作方斛,受六升。”"}, {"t": "方斛谓之桶。", "b": "《广雅》"}, {"t": "角斗桶。", "b": "《吕氏春秋·仲春》"}, {"t": "平斗桶。", "b": "《史记·商君书》"}]}, {"meaning": "同“捅”。", "cites": [{"t": "晁大官儿,你消停,别把话桶得紧了,收不进去。", "b": "《醒世姻缘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2231wx','梭','1','suō','木','11','','[{"pinyin": "suō", "defs": [{"meaning": "(形声。本义:织机的构件) 梭子。", "cites": [{"t": "梭,织具也。", "b": "《通俗文》"}, {"t": "机梭声札札,牛驴走纷纷。", "b": "唐·白居易《朱陈村》"}], "words": [{"w": "梭布", "t": "土布。因用梭子织出"}, {"w": "穿梭;无梭织机;梭杼", "t": "机杼。指织布机"}, {"w": "梭肚", "t": "梭子中粗部分"}, {"w": "梭布", "t": "家庭木机所织之布。"}]}, {"meaning": "织布梭往复的次数。", "cites": [{"t": "一梭声尽重一梭,玉腕不停罗袖卷。", "b": "唐·王建《织锦曲》"}]}, {"meaning": "穿梭 。比喻往来频繁,运行快速。", "cites": [{"t": "纷纷织女梭。", "b": "南朝宋·鲍照《代堂上歌行》"}], "words": [{"w": "日月如梭;梭梭", "t": "往复如梭。形容频繁"}, {"w": "梭过", "t": "很快地穿过"}, {"w": "梭天摸地", "t": "上窜下跳。喻到处逃窜。"}]}, {"meaning": "悠荡。", "cites": [{"t": "人人吹唱人人欢,高打秋千好快乐。梭罗梭,梭着李婆!", "b": "梨园戏《陈三五娘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2232wx','救','1','jiù','攵','11','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。从攴(pū),轻轻敲击,求声。本义:止;禁止;阻止)。"}, {"meaning": "同本义。", "cites": [{"t": "救,止也。", "b": "《说文》"}, {"t": "救,犹禁也。以礼防禁人之过者也。", "b": "《周礼·司救》注"}, {"t": "使之相救。", "b": "《周礼·大司徒》。注:“救,救凶灾也。”"}, {"t": "今有同室之人斗者,救之,虽被发缨冠而救之可也。", "b": "《孟子·离娄下》"}], "words": [{"w": "救止", "t": "阻止;纠正"}, {"w": "救祸", "t": "消除祸乱"}, {"w": "救灭", "t": "扑灭"}, {"w": "救熄", "t": "亦作“救息”。扑灭"}, {"w": "救扑", "t": "扑灭。"}]}, {"meaning": "援救别人。", "cites": [{"t": "救,助也。", "b": "《广雅》"}, {"t": "扶服救之。", "b": "《礼记·檀弓》"}, {"t": "匍匐救之。", "b": "《孔子闲居》"}, {"t": "民困而不知救。", "b": "明·刘基《卖柑者言》"}, {"t": "设法筹救。", "b": "清·梁启超《谭嗣同传》"}, {"t": "救我圣主。", "b": ""}, {"t": "足下欲救。", "b": ""}], "words": [{"w": "解救", "t": "使脱离危险或困难"}, {"w": "救穷", "t": "救济穷困"}, {"w": "救度", "t": "救拔并使脱离苦难,多指神仙超度之事"}, {"w": "救落", "t": "救助;说情;救护。"}]}, {"meaning": "治疗。", "cites": [{"t": "是救病而饮之以堇也。", "b": "《吕氏春秋·劝学》"}], "words": [{"w": "急救", "t": "紧急救治"}, {"w": "救药", "t": "医疗救治。也用来比喻挽救、补救"}, {"w": "救病", "t": "治病"}, {"w": "救疾", "t": "救治病人;治病"}, {"w": "救疗", "t": "救治;医治。"}]}, {"meaning": "纠正。", "cites": [{"t": "知其心,然后能救其失。", "b": "《礼记》"}], "words": [{"w": "救正", "t": "纠正"}, {"w": "救弊", "t": "匡除纠正弊害"}, {"w": "救奢", "t": "纠正奢靡"}, {"w": "救过", "t": "纠正过失。"}]}, {"meaning": "求助于人。", "cites": [{"t": "求救于齐。", "b": "《战国策·赵策》"}, {"t": "请救于魏。", "b": "《史记·魏公子列传》"}, {"t": "奉命求救。", "b": "《资治通鉴》"}, {"t": "百千求救声。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "“捄”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2233wx','曹','1','cáo','曰','11','','[{"pinyin": "cáo", "defs": [{"meaning": "古代指诉讼的原告和被告。即两曹。", "cites": [{"t": "两曹,今俗所谓原告被告也。", "b": "《说文》段玉裁注"}]}, {"meaning": "古代分科办事的官署或部门。", "cites": [{"t": "品其名位,犹不失下曹从事。", "b": "《资治通鉴》"}], "words": [{"w": "曹干", "t": "官署中的干事人员"}, {"w": "曹掾", "t": "泛指一般官员"}, {"w": "曹务", "t": "古代官署中分类所管理的事务"}, {"w": "法曹", "t": "唐、宋地方司法机关。"}]}, {"meaning": "双方;班;组。", "cites": [{"t": "分曹并进。", "b": "《楚辞·招魂》。注:“偶也。”"}, {"t": "率其曹偶。", "b": "《史记·黥布传》。索隐:“辈也。”"}, {"t": "乃造其曹。", "b": "《诗·大雅·公刘》。传:“群也。”"}]}, {"meaning": "辈,等于现代汉语中的“们”。", "cites": [{"t": "尔曹身与名俱灭,不废江河万古流。", "b": "唐·杜甫《戏为六绝句(之二)》"}], "words": [{"w": "尔曹", "t": "你们这些人"}, {"w": "儿曹", "t": "孩子们。"}]}, {"meaning": "古国名。"}, {"meaning": "西周的诸侯国。"}, {"meaning": "古西域国名。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2234wx','副','1','fù','刂','11','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从刀,畐(fú)声。(pì)本义:用刀剖开。《说文》:“判也。”《诗·大雅》:“不坼不副。”)。"}, {"meaning": "相称,符合。", "cites": [{"t": "盛名之下,其实难副。", "b": "李固《遗黄琼书》"}], "words": [{"w": "名副其实;副顺", "t": "顺应,随顺。"}]}, {"meaning": "交付,付与。", "cites": [{"t": "只恐重重世缘在,事须三度副苍生。", "b": "唐·刘禹锡《和仆射牛相公寓言》"}]}, {"meaning": "非正的(区别于“正”或“主”)。", "cites": [{"t": "副将军史德威慨然任之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "副研", "t": "副研究员。仅次于研究员的高级研究人员"}, {"w": "副将", "t": "副总兵"}, {"w": "副榜", "t": "明代乡试、会试中,于正式名额取的较优秀者"}, {"w": "副爷", "t": "将领的属僚"}, {"w": "副贡", "t": "副贡生,乡试中副榜录取的入国子监。"}]}, {"meaning": "次要的。", "cites": [{"t": "误中副车。", "b": "《汉书·张良传》。师古曰:“副,谓后乘也。”"}], "words": [{"w": "副产品;副次", "t": "次要。"}]}, {"meaning": "辅助职务;副手;助手。", "cites": [{"t": "乃令秦武阳为副。", "b": "《战国策·燕策》"}], "words": [{"w": "团副;大队副;中队副;三副", "t": ""}]}, {"meaning": "书籍、文献的副本。", "cites": [{"t": "副在有司。", "b": "《汉书·高惠高后文功臣表》。师古曰:“副,贰也。其列侯功籍,已藏于宗庙;副贰之本,又在有司。”"}], "words": [{"w": "副启", "t": "正式信件之外附加的信"}, {"w": "副封", "t": "副本"}, {"w": "副墨", "t": "副本;书籍、著作或文件正本之外的复制本。"}]}, {"meaning": "副词的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2235wx','票','1','piāo piào','示','11','','[{"pinyin": "piāo", "defs": [{"meaning": "(会意。本义: 火飞)。"}, {"meaning": "同本义。", "cites": [{"t": "见票如累明。", "b": "《太玄·沈》。注:“飞光也。”"}]}, {"meaning": "轻举的样子。", "cites": [{"t": "票然逝。", "b": "《汉书·礼乐志》。注:“轻举意。”"}], "words": [{"w": "票票", "t": "轻浮"}, {"w": " 票然", "t": "轻举的样子。"}]}, {"meaning": "摇动。", "cites": [{"t": "票昆仑。", "b": "《汉书·扬雄传下》。注:“犹言摇动也。”"}], "words": [{"w": " 票忽", "t": "飘忽"}, {"w": " 票轻", "t": "飘摇。"}]}]}, {"pinyin": "piào", "defs": [{"meaning": "迅疾;轻捷。", "cites": [{"t": "为票姚校尉。", "b": "《汉书·霍去病传》。注:“劲疾貌。”"}, {"t": "校武票禽。", "b": "《汉书·扬雄传》"}], "words": [{"w": "票勇", "t": "行动迅疾勇猛"}, {"w": "票健", "t": "敏捷强劲"}, {"w": "票禽", "t": "轻疾的飞禽"}, {"w": "票贼", "t": "迅猛的盗贼"}, {"w": "票轻", "t": "轻疾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2236wx','酝','1','yùn','酉','11','','[{"pinyin": "yùn", "defs": [{"meaning": "(形声。从酉(yǒu),昷(wēn)声。简体字“云”声。从“酉”,与酒有关。本义:酿酒)。"}, {"meaning": "同本义。", "cites": [{"t": "酝,酿也。", "b": "《说文》"}, {"t": "壁也瓦瓮,白沴沴满贮村醪;架上磁瓶,香馥馥新开社酝。——《梼杌闲评——明珠缘》", "b": ""}, {"t": "或秋藏冬发,或春醒夏成。", "b": "曹植《曹子建集》"}, {"t": "酒则九酝醴,十旬兼清。", "b": "张衡《南都赋》"}], "words": [{"w": "酝酒", "t": "酿酒"}, {"w": "酝户", "t": "专事酿酒的人家"}, {"w": "酝造", "t": "酿造,制作。"}]}, {"meaning": "逐渐造成。", "cites": [{"t": "公盖酝百家之精,兼六朝秀,而一禀之。", "b": "明·凌义渠《代贺吴云麓荣封序》"}]}, {"meaning": "酒。", "cites": [{"t": "宜城酝始熟,阳翟曲新调。", "b": "《随书》"}], "words": [{"w": "酝醪", "t": "酒酿"}, {"w": "酝香", "t": "酒香"}, {"w": "酝熟", "t": "酒己成熟。"}]}, {"meaning": "酒曲。", "cites": [{"t": "酝,酒母也。", "b": "《仓颉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2237wx','酗','1','xù','酉','11','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从酉(yǒu),凶声。“酉”与酒有关。本义:无节制地喝酒,酒后昏迷乱来)。"}, {"meaning": "同本义。", "cites": [{"t": "下邳周丘,无行酗酒。", "b": "《史记·吴王濞列传》"}, {"t": "酗淫自恣,前后告喻,曾无悛改。", "b": "《三国志》"}], "words": [{"w": "酗戕", "t": "酒后杀人"}, {"w": "酗讼", "t": "因酗酒而争讼"}, {"w": "酗淫", "t": "酗酒淫乐。"}]}, {"meaning": "撒酒疯。", "cites": [{"t": "弟弼,好酒而酗。", "b": "《北史·牛弘传》"}, {"t": "素酗于酒,戚党多畏避之。", "b": "《聊斋志异》"}], "words": [{"w": "酗讼", "t": "因酗酒而起争讼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2238wx','厢','1','xiāng','厂','11','','[{"pinyin": "xiāng", "defs": [{"meaning": "(形声。从厂(hǎn)相声。从厂,与房屋有关。本义:东西廊)。"}, {"meaning": "同本义。", "cites": [{"t": "厢,廊也。", "b": "《说文新附》"}, {"t": "室有东西厢曰庙。", "b": "《尔雅·释宫》。孙注:“厢,夹室前堂。”李注:“厢,谓宗庙殿有东西小堂也。”"}, {"t": "下雕辇于东厢。", "b": "张衡《东京赋》"}, {"t": "徘徊东西厢,孤妾谁与俦。", "b": "唐·韦应物诗"}]}, {"meaning": "厢房,在正房前面两侧的房屋。", "cites": [{"t": "吕后侧耳于东厢听。", "b": "《汉书·周昌传》。师古曰:“正寝之东西室皆曰箱,言似箱箧之形。”"}, {"t": "月暗西厢,凤去秦楼。", "b": "元·王实甫《西厢记》"}, {"t": "东厢扶案。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "东厢;西厢;厢房;厢库", "t": "纸扎的房屋"}, {"w": "厢悬", "t": "古代礼乐制度。悬钟磬类乐器于厢室中。"}]}, {"meaning": "堂屋的东西墙。", "cites": [{"t": "蒺藜蔓乎东厢。", "b": "《楚辞》"}]}, {"meaning": "边;旁。", "cites": [{"t": "怕不是我身厢有甚么缠魂不定?", "b": "汤显祖《南柯记》"}], "words": [{"w": "两厢;这厢;那厢;让开大路,占领两厢", "t": ""}]}, {"meaning": "车厢。", "cites": [{"t": "于是先生乃舒虹霓以蕃尘,倾雪盖以蔽明,倚瑶厢而徘徊,总众辔而安行。", "b": "阮籍《大人先生传》"}]}, {"meaning": "用同“箱”。箱箧。", "cites": [{"t": "又把豆子磨了一厢豆腐,也都卖了。", "b": "《儒林外史》"}, {"t": "打开这药厢,将小舍人放在里面。", "b": "纪君祥《赵氏孤儿》"}], "words": [{"w": "厢子", "t": "箱子"}, {"w": "一厢豆腐", "t": ""}]}, {"meaning": "类似厢的隔间  车厢。"}, {"meaning": "镶嵌。用同“镶”。", "cites": [{"t": "阶檐上,真个放着一柄金厢白玉珪。", "b": "《西游记》"}], "words": [{"w": "厢嵌", "t": "镶嵌。"}]}, {"meaning": "用花边、滚边、带、条子给…装。", "cites": [{"t": "以白鹿纸厢边,不可用绢。", "b": "文震亨《长物志·装贴》"}], "words": [{"w": "厢白旗", "t": "镶白旗。清代八旗之一"}, {"w": "厢红旗", "t": "镶红旗。清代八旗之一"}, {"w": "厢黄旗", "t": "镶黄旗。清代八旗之一。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2239wx','戚','1','qī','戈','11','','[{"pinyin": "qī", "defs": [{"meaning": "(形声。从戉,尗声。戉:(yuè),斧子。本义:古兵器名,斧的一种)。"}, {"meaning": "同本义。亦用为舞具。", "cites": [{"t": "戚,戉也。", "b": "《说文》"}, {"t": "干戈戚扬。", "b": "《诗·大雅·公刘》"}, {"t": "朱干玉戚。", "b": "《礼记·明堂位》"}, {"t": "执干戚舞。", "b": "《韩非子·五蠹》"}], "words": [{"w": "戚扬", "t": "斧钺。"}]}, {"meaning": "亲属,亲戚。", "cites": [{"t": "何谓六戚?父母兄弟妻子。", "b": "《吕氏春秋》"}], "words": [{"w": ";戚好", "t": "亲戚友好"}, {"w": "戚里", "t": "戚畹。帝王外戚所居住的地方"}, {"w": "戚属", "t": "母及妻的亲属"}, {"w": "戚爱", "t": "亲属和宠爱的人"}, {"w": "戚家", "t": "贵戚之家;亲戚家"}, {"w": "外戚", "t": "指帝王的母族、妻族"}, {"w": "戚宠", "t": "外戚亲贵。"}]}, {"meaning": "忧愁;悲伤", "cites": [{"t": "心之忧矣,自始伊戚。", "b": "《诗·小雅·小明》"}, {"t": "貌若甚戚者。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "又。", "cites": [{"t": "蒋氏大戚。", "b": ""}, {"t": "婉贞独戚然。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "汝又虑戚吾心。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "戚容", "t": "愁容"}, {"w": "戚切", "t": "悲切"}, {"w": "戚休", "t": "休戚。忧愁和欢乐"}, {"w": "戚欣", "t": "忧愁与欢乐"}, {"w": "戚言", "t": "忧戚的言词"}, {"w": "戚嗟", "t": "忧伤嗟叹"}, {"w": "戚意", "t": "忧伤的心情"}, {"w": "戚惨", "t": "悲伤"}, {"w": "戚忧", "t": "忧伤"}, {"w": "戚颜", "t": "忧伤的容颜。"}]}, {"meaning": "亲近,亲密。", "cites": [{"t": "未可以戚我先王。", "b": "《书·金滕》"}], "words": [{"w": "戚疏", "t": "亲疏。"}]}, {"meaning": "假借为“促”（cù）。疾速。", "cites": [{"t": "凡察车之道,欲其朴属而微至。…不微至,无以为戚速也。", "b": "《周礼·考工记·总序》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2240wx','硅','1','guī','石','11','','[{"pinyin": "guī", "defs": [{"meaning": "一种四价的非金属元素,以化合物的形式,作为仅次于氧的最丰富的元素存在于地壳中,通常是在电炉中由碳还原二氧化硅而制得的,主要以合金的形式使用(如硅铁合金),也与陶瓷材料一起用于金属陶瓷中,或用作半导体材料(如在晶体管中)和光生电池的元件 ——元素符号Si。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2241wx','硕','1','shuò','石','11','','[{"pinyin": "shuò", "defs": [{"meaning": "(形声。从页(xié),石声。页,头。本义:头大)。"}, {"meaning": "同本义。", "cites": [{"t": "硕,头大也。", "b": "《说文》"}]}, {"meaning": "引申为大。", "cites": [{"t": "硕鼠硕鼠,无食我黍。", "b": "《诗·魏风·硕鼠》"}, {"t": "硕果不食。", "b": "《易·剥》"}, {"t": "彼其之子,硕大无朋。", "b": "《诗·唐风·椒聊》"}], "words": [{"w": "壮硕;肥硕;硕德", "t": "大德"}, {"w": "硕见", "t": "高见"}, {"w": "硕大;硕画;硕望;硕量;硕谋", "t": "远大的谋略"}, {"w": "硕虑", "t": "深远的思虑。"}]}, {"meaning": "比喻坚固。", "cites": [{"t": "孤与将军,恩如骨肉…而忍绝王命,明弃硕交,实为佞人所构会也。", "b": "《文选·阮瑀·为曹公作书与孙权》"}]}, {"meaning": "学识渊博、德高望重的。", "cites": [{"t": "又患无硕师名人与游,尝趋百里之外从乡之先达执经叩问。", "b": "明·宋濂《送东阳马生序》"}, {"t": "弱冠游学都下,通儒硕学,必造门质疑。", "b": "《南史·顾越传》"}], "words": [{"w": "硕老", "t": "年高望重的博学之士"}, {"w": "硕彦", "t": "品节高尚、学问渊博的名流"}, {"w": "硕隽", "t": "学识渊博、俊拔出众的人才。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2242wx','奢','1','shē shá','大','11','','[{"pinyin": "shē", "defs": [{"meaning": "(形声。从大,者声。本义: 奢侈,不节俭)。"}, {"meaning": "同本义。用钱没有节制，过分享受。", "cites": [{"t": "奢,张也。", "b": "《说文》。徐灏曰:“奢者侈靡放纵之义。故曰‘张’,言其张大也。”"}, {"t": "奢言淫乐而显侈靡。", "b": "司马相如《子虚赋》"}, {"t": "礼,与其奢也,宁俭。", "b": "《论语·八佾》"}, {"t": "常以俭得之,以奢失之。", "b": "《韩非子·十过》"}, {"t": "反俭曰奢,言夸大于人也。", "b": "《太平御览》引《说文》"}, {"t": "秦爱纷奢,人亦念其家。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "时国王骄奢,不遵典宪。", "b": "《后汉书·张衡传》"}], "words": [{"w": "奢尚", "t": "奢侈的风尚"}, {"w": "奢欲", "t": "奢侈的欲望"}, {"w": "奢绮", "t": "奢侈华丽"}, {"w": "奢薄", "t": "风俗奢侈,人情,浇薄"}, {"w": "奢阔", "t": "奢侈阔绰"}, {"w": "奢愿", "t": "过分的愿望"}, {"w": "奢溢", "t": "奢侈过制"}, {"w": "奢僭", "t": "奢侈逾礼"}, {"w": "奢佚", "t": "骄奢放纵。"}]}, {"meaning": "过分。", "cites": [{"t": "欲起一台,以为奢费而不作。", "b": "《潜夫论·俘侈》"}, {"t": "摘鲜焙芳旋封裹,至精至好且不奢。", "b": "唐·卢仝《走笔谢孟谏议寄新茶》"}]}, {"meaning": "出色;美好。", "cites": [{"t": "玉面添娇舞态奢。", "b": "唐·刘禹锡《和乐天柘枝》"}], "words": [{"w": "奢遮煞", "t": "好到顶点;充其量。"}]}, {"meaning": "夸张,夸大。", "cites": [{"t": "光夫人显改光生的时所造茔制,而更奢大之。", "b": "《汉书·宣帝纪》"}, {"t": "故夫夸目者尚奢,惬心者贵当。", "b": "陆机《文赋》"}]}, {"meaning": "胜过。", "cites": [{"t": "彼肆人之男女,丽美奢乎许史。", "b": "《文选·张衡·西京赋》"}]}]}, {"pinyin": "shá", "defs": [{"meaning": "姓", "cites": [{"t": "明代有奢崇明", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2243wx','盔','1','kuī','皿','11','','[{"pinyin": "kuī", "defs": [{"meaning": "(形声。从皿,灰声。本义:钵)。"}, {"meaning": "同本义。盂一类容器。", "cites": [{"t": "盔,盔器,盂属也。", "b": "《龙龛手鉴》"}]}, {"meaning": "首铠。古代战士用以保护头部的帽子。也指消防人员或矿工带的金属帽子。", "cites": [{"t": "三通鼓罢,袁绍金盔金甲,锦袍玉带,立马阵前。", "b": "《三国演义》"}], "words": [{"w": "盔缨", "t": "头盔上的丝织饰物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2244wx','爽','1','shuāng shuǎng','爻','11','','[{"pinyin": "shuāng", "defs": [{"meaning": "——如“肃爽”(sùshuāng):古骏马名。", "cites": [{"t": "唐成公如楚,有两肃爽马,子常欲之,弗与。", "b": "《左传·定公三年》"}]}]}, {"pinyin": "shuǎng", "defs": [{"meaning": "(会意。甲骨文字形,像人左右腋下有火,表示明亮(从于省吾说)。本义:明亮;亮)。"}, {"meaning": "同本义。", "cites": [{"t": "爽,明也。", "b": "《说文》"}, {"t": "时甲子昧爽。", "b": "《书·牧誓》"}, {"t": "爽邦由哲。", "b": "《书·大诰》"}, {"t": "二惠竞爽犹可。", "b": "《左传·昭公三年》"}, {"t": "风泽清旷,气爽节和。", "b": "郦道元《水经注·庐江水》"}], "words": [{"w": "神清目爽;爽旦", "t": "黎明,清晨"}, {"w": "爽别", "t": "清亮"}, {"w": "爽拔", "t": "清朗秀技"}, {"w": "爽明", "t": "黎明"}, {"w": "爽曙", "t": "明晓"}, {"w": "爽豁", "t": "清楚而明显。"}]}, {"meaning": "畅快;舒适。", "cites": [{"t": "老太太心里不大爽。", "b": "《红楼梦》"}], "words": [{"w": "爽怿", "t": "舒畅愉快"}, {"w": "爽利", "t": "痛快;干脆;利落"}, {"w": "身体不爽;爽然", "t": "开朗舒畅的样子"}, {"w": "爽节", "t": "天高气爽的气节。"}]}, {"meaning": "明白;明智。", "cites": [{"t": "兹心不爽,而昏乱百度。", "b": "《左传·昭公元年》"}], "words": [{"w": "爽明", "t": "明白"}, {"w": "爽练", "t": "明达"}, {"w": "爽慧", "t": "明慧"}, {"w": "爽异", "t": "聪颖特出"}, {"w": "爽悟", "t": "聪颖;明达。"}]}, {"meaning": "开朗;豪爽。", "cites": [{"t": "温豪爽有风慨。", "b": "《晋书·桓温传》"}], "words": [{"w": "爽伉", "t": "豪爽刚直"}, {"w": "爽荡", "t": "大方;气派"}, {"w": "爽恺", "t": "高亢利落;不拖泥带水"}, {"w": "爽侠", "t": "有豪侠气概"}, {"w": "爽慨", "t": "爽直慷慨"}, {"w": "爽恺", "t": "豪爽而随和"}, {"w": "爽俊", "t": "豪爽秀俊。"}]}, {"meaning": "开阔;宽阔。", "cites": [{"t": "沃野爽且平。", "b": "晋·陆机《齐讴行》"}], "words": [{"w": "爽闿", "t": "高大宽敞"}, {"w": "爽耸", "t": "形容地势高而开阔。"}]}, {"meaning": "差错,失误。", "cites": [{"t": "女也不爽。", "b": "《诗·卫风·氓》"}, {"t": "言爽,日反其信。", "b": "《国语·周语》"}, {"t": "伦理无爽。", "b": "《文心雕龙·论说》"}, {"t": "帘内掷一纸出,即道人意中事,无毫发爽。", "b": "《聊斋志异·促织》"}], "words": [{"w": "爽忒", "t": "差失"}, {"w": "爽缪", "t": "谬误"}, {"w": "爽行", "t": "过失的行为"}, {"w": "爽法", "t": "违背礼法"}, {"w": "爽言", "t": "违背诺言。"}]}, {"meaning": "丧失;失去。", "cites": [{"t": "昔昭王娶于房,曰房后,实有爽德。", "b": "《国语·周语》"}, {"t": "郭汲还州,尚不欺于童子,文侯校猎,宁爽约于虞人。", "b": "唐·李商隐《为张周封上杨相公启》"}], "words": [{"w": "爽越", "t": "丧失"}, {"w": "爽误", "t": "失误"}, {"w": "爽实", "t": "失实"}, {"w": "爽德", "t": "失德"}, {"w": "爽信", "t": "失信;不守信用"}, {"w": "爽期", "t": "失约;违背约定的时间。"}]}, {"meaning": "伤败;败坏。", "cites": [{"t": "五音令人耳聋,五味令人口爽。", "b": "《老子》"}], "words": [{"w": "爽口", "t": "伤败胃口"}, {"w": "爽伤", "t": "败坏,病伤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2245wx','聋','1','lóng','耳','11','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从耳,龙声。本义:丧失听觉能力)。"}, {"meaning": "同本义。", "cites": [{"t": "聋,无闻也。", "b": "《说文》"}, {"t": "聋者无以与乎钟鼓之声。", "b": "《庄子·逍遥游》"}, {"t": "耳不听五声之和为聋,目不别五色之章为昧。", "b": "《左传·僖公二十四年》"}]}, {"meaning": "愚昧;不明事理。", "cites": [{"t": "郑昭,宋聋。", "b": "《左传·宣公十四年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2246wx','袭','1','xí','龙','11','','[{"pinyin": "xí", "defs": [{"meaning": "(形声。从衣,从两“龙”(tà)省声。本义:死者穿的衣服,衣襟在左边)。"}, {"meaning": "同本义。", "cites": [{"t": "袭,左衽袍也。", "b": "《说文》。按,凡敛死者,左衽,不纽。"}, {"t": "陈袭事于房中,西领南上,不綪。", "b": "《仪礼·士丧礼》。郑玄注:“袭事,谓衣服也。”"}], "words": [{"w": "袭衣", "t": "尸衣;也指古代行礼时穿在裼衣外面的上衣"}, {"w": "袭玩", "t": "衣着器用。"}]}, {"meaning": "衣一套为一袭。", "cites": [{"t": "赐衣被一袭。", "b": "《汉书·昭帝纪》。注:“一称也。犹今一副。"}, {"t": "乃命留五时衣各一袭。", "b": "《后汉书·东平宪王苍传》"}, {"t": "袈衣一袭,止用一两。", "b": "《三宝太监西洋记通俗演义》"}], "words": [{"w": "袭衣", "t": "成套衣服"}, {"w": "袭衣兼食", "t": "成套衣服,多盘菜肴。谓生活优裕。"}]}, {"meaning": "层,重。", "cites": [{"t": "棺椁数袭。", "b": "《吕氏春秋》"}]}, {"meaning": "因袭,照旧搬用。", "cites": [{"t": "今袭迹于齐晋,欲国安存,不可得也。", "b": "《韩非子·孤愤》"}, {"t": "五帝不相复,三代不相袭。", "b": "《史记·秦始皇本纪》"}, {"t": "汉兴,仍袭秦制。", "b": "《后汉书·宦官传论》"}, {"t": "袭译欧西人之言。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "沿袭", "t": "依照旧传统办理"}, {"w": "袭因", "t": "依照旧例"}, {"w": "袭迹", "t": "依照前人的遗迹。"}]}, {"meaning": "继承。", "cites": [{"t": "世官九等,皆有袭职,有替职。", "b": "《明史·职官志一》"}, {"t": "贲瑞早已辞世,贲玺依例袭了侯爵。", "b": "《一层楼》"}], "words": [{"w": "世袭", "t": "指帝位、爵位等世代相传"}, {"w": "袭职", "t": "继承官职"}, {"w": "袭位", "t": ""}]}, {"meaning": "重复。", "cites": [{"t": "赵孟曰:“吾卜于此起兵,事不再令,卜不袭吉。行也。”", "b": "《左传·哀公十年》。杜预注:“袭,重也。”"}], "words": [{"w": "袭吉", "t": "卜若不吉则止,不可因而重卜;重卜而得吉,叫做“袭吉”。"}]}, {"meaning": "调合;合。", "cites": [{"t": "天地比,齐秦袭。", "b": "《荀子》"}], "words": [{"w": "袭从", "t": "言两者相合"}, {"w": "袭然", "t": "合一的样子。"}]}, {"meaning": "袭击,乘其不备,偷偷地进攻。", "cites": [{"t": "凡师有钟鼓曰伐,无曰侵,轻曰袭。", "b": "《左传·庄公二十九年》"}, {"t": "掩人不备,行不假途,人衔枚,马勒缰,昼伏夜行,为袭也。", "b": "《白虎通·诛伐》"}, {"t": "城上早插蜀兵旗号:原来已被魏延袭了。", "b": "《三国演义》"}, {"t": "慧室袭月。", "b": "《战国策·魏策》"}, {"t": "荆人欲袭宋。", "b": "《吕氏春秋·察今》"}, {"t": "恐汉袭之。", "b": "《汉书·李广苏建》"}, {"t": "谋袭蔡州。", "b": "《资治通鉴·唐纪》"}, {"t": "率众袭之。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "偷袭;奔袭;侵袭;奇袭;夜袭;空袭", "t": ""}]}, {"meaning": "衣上加衣。", "cites": [{"t": "寒不敢袭,痒不敢搔。", "b": "《礼记》"}]}, {"meaning": "穿衣。", "cites": [{"t": "衣尸曰袭。袭,匝也,以衣周匝覆之也。", "b": "《释名·释丧制》"}], "words": [{"w": "袭尸", "t": "为死者穿衣"}, {"w": "袭朝服", "t": ""}]}, {"meaning": "盖。", "cites": [{"t": "张甲乙而袭翠被。", "b": "张衡《西京赋》"}], "words": [{"w": "袭裘", "t": "古代盛礼时,掩上裼衣而不使羔裘见于外。"}]}, {"meaning": "触及;熏染;侵袭。", "cites": [{"t": "芳气袭人是酒香。", "b": "《红楼梦》"}], "words": [{"w": "袭人", "t": "侵袭到人。薰人。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2247wx','盛','1','chéng shèng','皿','11','','[{"pinyin": "chéng", "defs": [{"meaning": "放在祭器里的谷物。", "cites": [{"t": "盛,黍稷在器中以祀者也。", "b": "《说文》"}, {"t": "天子亲耕以共粢盛。", "b": "《谷梁传·桓公十四年》。注:“黍稷曰粢,在器曰盛。”"}], "words": [{"w": "粢盛", "t": ""}]}, {"meaning": "器皿,如杯、碗之类。", "cites": [{"t": "旨酒一盛兮。", "b": "《左传·哀公十三年》。注:“一器也。”"}, {"t": "食粥于盛。", "b": "《礼记·丧大记》"}]}, {"meaning": "春秋时国名 。即郕。故址在今山东省宁阳县东北。"}, {"meaning": "整饬;端正。", "cites": [{"t": "盛服将朝,尚早,坐而假寐。", "b": "《左传》"}]}]}, {"pinyin": "shèng", "defs": [{"meaning": "(形声。从皿,成声。(chéng)本义:盛在祭器中的黍稷)。"}, {"meaning": "旺盛;兴盛。", "cites": [{"t": "唐虞之际,于斯为盛。", "b": "《论语·泰伯》"}, {"t": "国家之盛。", "b": "韩愈《送孟东野序》"}, {"t": "物盛则衰。", "b": "《史记·蔡泽列传》"}, {"t": "盛衰之理,虽曰天命,岂非人事哉!", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "盛古", "t": "指远古兴盛时代"}, {"w": "盛族", "t": "名门望族"}, {"w": "盛气", "t": "气势旺盛"}, {"w": "盛阳", "t": "旺盛的阳气。"}]}, {"meaning": "茂盛。", "cites": [{"t": "人间四月芳菲尽,山寺桃花始盛开。", "b": "唐·白居易《游大林寺》"}], "words": [{"w": "盛茂", "t": "茂盛。"}]}, {"meaning": "丰盛。", "cites": [{"t": "有盛馔,必变色而作。", "b": "《论语》"}, {"t": "俯祭品类之盛。", "b": "王羲之《兰亭集序》"}]}, {"meaning": "盛大;隆重。", "cites": [{"t": "官盛任使。", "b": "《礼记·中庸》。疏:“谓官之盛大。”"}, {"t": "且立石于其墓之门,以旌其所为。呜呼,亦盛矣哉!", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "盛作", "t": "犹大作"}, {"w": "盛烈", "t": "盛大的功业"}, {"w": "盛乐", "t": "盛大的乐曲"}, {"w": "盛礼", "t": "盛大的礼仪。"}]}, {"meaning": "众,多;极充足。", "cites": [{"t": "盛,多也。", "b": "《广雅》"}, {"t": "民以殷盛,国以富强。", "b": "李斯《谏逐客书》"}], "words": [{"w": "盛多", "t": "众多。"}]}, {"meaning": "大,高,显赫。", "cites": [{"t": "位卑则足羞,官盛则近谀。", "b": "唐·韩愈《师说》"}]}, {"meaning": "美好。", "cites": [{"t": "早有许多盛妆丽服之姬妾丫鬟迎着。", "b": "《红楼梦》第三回"}], "words": [{"w": "盛心", "t": "深厚美好的情意"}, {"w": "盛轨", "t": "美好的典范"}, {"w": "盛则", "t": "美好的法则"}, {"w": "盛美", "t": "美善;称美"}, {"w": "盛藻", "t": "华美的辞藻。"}]}, {"meaning": "范围广大;广泛。", "cites": [{"t": "唐人尚未盛为之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "赵亦盛设兵以待秦。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "盛行;盛传", "t": ""}]}, {"meaning": "极力;表程度深。", "cites": [{"t": "今又盛寒,马无稿草。", "b": "《资治通鉴》"}, {"t": "已而简子至,求狼弗得,盛怒。", "b": "马中锡《中山狼传》"}], "words": [{"w": "盛酌", "t": "盛情款待"}, {"w": "盛言", "t": "极力申说"}, {"w": "盛推", "t": "极力推许"}, {"w": "盛道", "t": "极力称说"}, {"w": "盛夸", "t": "极力夸大。"}]}, {"meaning": "极点;顶点。", "cites": [{"t": "尧者,圣人之盛也。", "b": "王安石《九变而赏罚可言》"}]}, {"meaning": "赞美。", "cites": [{"t": "盛夏后之致美。", "b": "张衡《东京赋》"}], "words": [{"w": "盛口", "t": "交口称誉"}, {"w": "盛尊", "t": "尊贵至极"}, {"w": "盛介", "t": "盛价。对别人的尊称"}, {"w": "盛使", "t": "对对方办事人员的敬称"}, {"w": "盛从", "t": "称对方仆从的客套话。"}]}, {"meaning": "抚育。", "cites": [{"t": "周公盛养成王。", "b": "《书·大传·金縢》"}], "words": [{"w": "盛养", "t": "培育。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2248wx','匾','1','biǎn','匚','11','','[{"pinyin": "biǎn", "defs": [{"meaning": "同“扁”。形体的厚度比长度、宽度小;不圆", "words": [{"w": "匾毛", "t": "羽毛。因形状扁平,故称。亦借指鸟类"}, {"w": "匾食", "t": "水饺"}]}, {"meaning": "匾额", "words": [{"w": "光荣匾", "t": ""}, {"w": "匾式", "t": "匾额"}, {"w": "匾对", "t": "匾额和对联"}]}, {"meaning": "上面绣字的丝制横幅", "words": [{"w": "绣金匾", "t": ""}]}, {"meaning": "用竹蔑编成的器具,圆形平底框很浅,用来养蚕或盛粮食", "words": [{"w": "针线匾", "t": ""}, {"w": "养蚕团匾", "t": ""}, {"w": "匾篮儿", "t": "浅边的篮子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2249wx','雪','1','xuě','雨','11','','[{"pinyin": "xuě", "defs": [{"meaning": "(会意。从雨,从彗,彗(huì)省声。本义:空气中的水汽,冷却到摄氏零度以下时,就有部分凝结成冰晶,由空中降下,叫做雪)。"}, {"meaning": "同本义。", "cites": [{"t": "今我来思,雨雪霏霏。", "b": "《诗·小雅·采薇》"}, {"t": "春洩气为雨,雨凝为雪。", "b": "谢惠莲《雪赋》题注引《五经通训》"}, {"t": "平地尺为大雪。", "b": "《左传·隐公九年》"}, {"t": "麻衣如雪。", "b": "《诗·曹风·蜉虫游》"}, {"t": "[孟冬之月]行秋令,则雪霜不时,小兵时起,土地侵削。", "b": "《礼记·月令》"}, {"t": "平生所娇儿,颜色白胜雪。", "b": "杜甫《北征》诗"}], "words": [{"w": "雪案萤窗", "t": "比喻勤学苦读"}, {"w": "雪里鸿", "t": "即雪泥鸿爪"}, {"w": "雪浪纸", "t": "一种有波浪形暗纹的宣纸。"}]}, {"meaning": "借喻白色。", "cites": [{"t": "雪衣雪发青玉嘴,群捕鱼儿溪影中。", "b": "唐·杜牧《鹭鸶》"}, {"t": "君不见高堂明镜悲白发,朝如青丝暮成雪。", "b": "李白《将进酒》"}], "words": [{"w": "雪厾", "t": "白银"}, {"w": "雪练", "t": "色泽像雪白的绢一样"}, {"w": "雪花银", "t": "白银"}, {"w": "雪肌", "t": "白细如雪的肌肤"}, {"w": "雪色", "t": "白色。"}]}, {"meaning": "比喻高洁。", "cites": [{"t": "松品落落,雪格索索。", "b": "前蜀·贯休《送姜道士归南岳》"}, {"t": "一别高人又十年,霜筋雪骨健依然。", "b": "宋·杨万里诗"}, {"t": "松品落落,雪格索索。", "b": "唐·贯休《送姜道士归南岳》"}], "words": [{"w": "雪格", "t": "比喻高洁的品格"}, {"w": "雪淡", "t": "态度淡漠,不热心。"}]}, {"meaning": "下雪。", "cites": [{"t": "于时始雪,五处俱贺。", "b": "《世说新语》"}], "words": [{"w": "雪夜访普", "t": "宋太祖赵匡胤曾于雪夜到大臣赵普家商谈国事的故事"}, {"w": "雪峰", "t": "积雪的山峰"}, {"w": "雪云", "t": "降雪的阴云。"}]}, {"meaning": "洗刷,昭雪。", "cites": [{"t": "大夫种辅翼越王勾践而为之报怨雪耻。", "b": "《淮南子·氾论》"}], "words": [{"w": "雪正", "t": "昭雪更正"}, {"w": "雪谤", "t": "洗雪污蔑之词。"}]}, {"meaning": "擦净;揩干。", "cites": [{"t": "黍者,非饭之也,以雪桃也。", "b": "《韩非子》"}, {"t": "有言不可道,雪泣忆兰芳。", "b": "唐·李白《自溧水道哭王炎》"}], "words": [{"w": "雪泣", "t": "揩拭眼泪"}, {"w": "雪除", "t": "清除"}, {"w": "雪烦", "t": "消除烦闷"}, {"w": "雪涕", "t": "拭泪"}, {"w": "雪桃", "t": "拭桃。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2250wx','辅','1','fǔ','车','11','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从车,甫声。本义:车旁横木。辅所以益辐,使之能重载)。"}, {"meaning": "同本义。", "cites": [{"t": "輔,人颊车也。", "b": "《说文》。按,当作木夹车也。"}, {"t": "若车之有辅。", "b": "《吕氏春秋·权勋》"}, {"t": "辅,小木。", "b": "《尔雅》。按,车辅木之小者。"}, {"t": "其车既载,乃弃尔辅。", "b": "《诗·小雅·正目》"}], "words": [{"w": "辅材", "t": "制作车轮外旁夹毂的直木材料。"}]}, {"meaning": "助手。", "cites": [{"t": "夫将者国之辅也。", "b": "《孙子·谋攻》"}]}, {"meaning": "面颊。", "cites": [{"t": "谚所谓“辅车相依,唇亡齿寒”者,其虞、虢之谓也。", "b": "《左传·僖公五年》。杜预注:“辅,颊辅;车,牙车。”"}], "words": [{"w": "辅牙", "t": "颊辅和牙床。比喻相互倚助"}, {"w": "辅车", "t": "颊辅与牙床"}, {"w": "辅颊", "t": "上颌与面颊。泛指面颊。"}]}, {"meaning": "人的颊骨。", "cites": [{"t": "团辅圆颐,菡萏芙蓉。", "b": "《周小史》"}]}, {"meaning": "旧指京城附近的地方。", "cites": [{"t": "公一女,嫁为畿辅某官某妻。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "衡少善属文,游于三辅。", "b": "《后汉书·张衡传》"}], "words": [{"w": "汉代的“三辅”、“六辅”;辅墙", "t": "内墙。"}]}, {"meaning": "佐助,从旁帮助。", "cites": [{"t": "览民德焉错辅。", "b": "《楚辞·离骚》"}, {"t": "士仓又辅之。", "b": "《战国策·秦策五》"}, {"t": "辅周则国必强,辅隙则国必弱。", "b": "《孙子·谋攻》"}, {"t": "愿夫子辅吾志,明以教我。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "辅翼", "t": "辅佐;帮助"}, {"w": "辅弼", "t": "辅佐;帮助"}, {"w": "辅世", "t": "辅助世人"}, {"w": "辅臣", "t": "辅助的臣子"}, {"w": "辅成", "t": "助成。"}]}, {"meaning": "护卫。", "cites": [{"t": "城阙辅三秦,风烟望五津。", "b": "唐·王勃《杜少府之任蜀州》"}]}, {"meaning": "(bǔ)。捕捉。", "cites": [{"t": "圣人能辅时,不能违时。", "b": "《管子·霸言》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2251wx','辆','1','liàng','车','11','','[{"pinyin": "liàng", "defs": [{"meaning": "(形声。从车,两声。古代的车一般有两个轮子,故车一乘即称一两,后来写作“辆”,总称为“车辆”)。"}, {"meaning": "指鞋一双。", "cites": [{"t": "一辆小鞋儿。", "b": "汤显祖《紫钗记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2252wx','颅','1','lú','页','11','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。从页(xié),盧声。从“页”,表示与头有关。本义:头盖骨)。"}, {"meaning": "同本义。", "cites": [{"t": "首身分离,暴骨草泽,头颅僵仆,相望于境。", "b": "《战国策·秦策四》"}], "words": [{"w": "颅脑", "t": "头骨和脑子。"}]}, {"meaning": "头,头颅。", "cites": [{"t": "俽余志之精锐,拟青颅而点项。", "b": "《文选·潘岳·射雉赋》"}]}, {"meaning": "额头。", "cites": [{"t": "头陷颅碎。", "b": "《后汉书·马融传》"}], "words": [{"w": "颅颡", "t": "额头。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2253wx','虚','1','xū','虍','11','','[{"pinyin": "xū", "defs": [{"meaning": "(“墟”的古字)(形声。小篆字。从丘,虍(hū)声。丘,山丘。本义:大土山)。"}, {"meaning": "同本义。", "cites": [{"t": "虚,大丘也。昆仑丘谓之昆仑虚。", "b": "《说文》"}, {"t": "河出昆仑虚。", "b": "《尔雅》"}, {"t": "虚邑。", "b": "《易·升》"}, {"t": "升彼虚矣,以望楚矣。", "b": "《诗·傭风·定之方中》"}, {"t": "以游逍遥之虚。", "b": "《庄子·天运》"}], "words": [{"w": "虚莽", "t": "墟丘和草莽。"}]}, {"meaning": "住所;处所。", "cites": [{"t": "郑国,今河南之新郑,本高辛氏火正祝融之虚也。", "b": "《汉书》"}]}, {"meaning": "故城;废址;废墟;荒地。", "cites": [{"t": "凡十三岁而社稷为虚。", "b": "《汉书·贾谊传》"}, {"t": "无由不通,无虚不败。", "b": "《逸周书·文政》"}], "words": [{"w": "虚土", "t": "荒芜之地"}, {"w": "虚荒", "t": "荒芜,荒废"}, {"w": "虚空", "t": "犹荒野。空旷无人之处"}, {"w": "虚墓", "t": "墟墓。丛葬的基地。"}]}, {"meaning": "乡村市集。", "cites": [{"t": "之虚所卖之。", "b": "唐·柳宗元《柳河东集·童区寄传》"}, {"t": "一虚皆惊", "b": ""}], "words": [{"w": "虚市;虚里", "t": "墟里,村庄"}, {"w": "虚邑", "t": "墟落;村落"}, {"w": "虚所", "t": "集市"}, {"w": "虚城", "t": "墟落和城邑"}, {"w": "虚落", "t": "墟落。村庄。"}]}, {"meaning": "孔洞;空隙。引申为薄弱环节。", "cites": [{"t": "若循虚而出入,则亦无能履也。", "b": "《淮南子·泛论》"}], "words": [{"w": "虚隙", "t": "空隙,漏洞。"}]}, {"meaning": "空际,天空。引申为凌空。", "cites": [{"t": "浩浩乎如冯虚御风,而不知其所止。", "b": "宋·苏轼《前赤壁赋》"}], "words": [{"w": "虚皇", "t": "天帝,指玉帝"}, {"w": "虚碧", "t": "指清澈碧蓝的天空"}, {"w": "虚檐", "t": "凌空的房檐"}, {"w": "虚极,虚象", "t": "指太空"}, {"w": "虚亡", "t": "高空;太空。"}]}, {"meaning": "指抽象的理论。", "cites": [{"t": "亭林之学成于贵实;予之学出于导虚。", "b": "清·包世臣《艺舟双楫》"}], "words": [{"w": "虚比浮词", "t": "不切实际的空泛之谈"}, {"w": "虚空横拟", "t": "凭空想像"}, {"w": "虚喻浮言", "t": "说空话;说没有根据的话"}, {"w": "虚灵", "t": "生动而不可捉摸"}, {"w": "虚见", "t": "无根之论;浮浅之见。"}]}, {"meaning": "空虚,与“实”相对。", "cites": [{"t": "虚,空也。", "b": "《尔雅》"}, {"t": "无虚不败。", "b": "《周书·文政》。注:“国无人谓之虚。”"}, {"t": "有凭虚公子者。", "b": "张衡《西京赋》"}, {"t": "仓府两虚,国弱。", "b": "《商君书·去强》"}, {"t": "盈虚者如彼,而卒莫消长也。", "b": "苏轼《赤壁赋》"}, {"t": "良贾深藏若虚,君子盛德容貌若愚。", "b": "《史记》"}], "words": [{"w": "虚箦", "t": "屁"}, {"w": "虚火", "t": "为一点小事而过分张扬"}, {"w": "虚爵", "t": "空的饮酒器"}, {"w": "虚壑", "t": "空谷"}, {"w": "虚器", "t": "中空的器物"}, {"w": "虚花", "t": "虚幻不实。"}]}, {"meaning": "稀少。", "cites": [{"t": "自此贼情渐虚,官兵始知所向,以至擒殄。", "b": "宋·王弥大《清溪弄兵录》"}]}, {"meaning": "虚弱。", "cites": [{"t": "虚稼先死。", "b": "《吕氏春秋·辨土》。注:“根不实也。”"}], "words": [{"w": "虚劣", "t": "虚弱"}, {"w": "虚城", "t": "虚弱的城邑"}, {"w": "虚孱", "t": "虚弱无能"}, {"w": "虚顿", "t": "虚弱疲惫"}, {"w": "虚弊", "t": "虚弱疲敝,贫乏疲困"}, {"w": "虚惫", "t": "虚弱疲惫。"}]}, {"meaning": "谦虚。", "cites": [{"t": "足下虚心。", "b": "《汉书·李广苏建传》"}, {"t": "心不能虚。", "b": "清·刘开《问说》"}, {"t": "心之不虚", "b": ""}], "words": [{"w": "虚中", "t": "谦虚;虚心"}, {"w": "虚己", "t": "犹虚心"}, {"w": "虚忝", "t": "谦词。谓无其实而空受荣宠"}, {"w": "虚受", "t": "虚心接受"}, {"w": "虚恭", "t": "谦虚、恭敬。"}]}, {"meaning": "虚假,不真实。", "cites": [{"t": "皆存想虚致,未必有其实也。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "虚科", "t": "虚情假意"}, {"w": "虚脾甜口", "t": "虚情假意"}, {"w": "虚脾胃", "t": "虚情假意"}, {"w": "虚下", "t": "演出中演员暂时退场"}, {"w": "虚嚣", "t": "虚假不实;欺诈。"}]}, {"meaning": "道教语。指无欲无为的思想境界。", "cites": [{"t": "致虚极。", "b": "《老子》。魏源本义:“虚者无欲也。”"}, {"t": "所以贵无为无思为虚者,谓其意无所制也。", "b": "《韩非子》"}], "words": [{"w": "虚皇坛", "t": "道教太虚神的祭坛"}, {"w": "虚夷", "t": "恬淡寡欲"}, {"w": "虚玄", "t": "指道家思想。老子主张虚一静观和玄览,故称。"}]}, {"meaning": "使空出。", "cites": [{"t": "公子从车骑,虚左,自迎夷门侯生。", "b": "《史记·魏公子列传》"}, {"t": "天子复思,且征以代,虚吏部左承位以待之。", "b": "唐·韩愈《王公神道碑铭》"}, {"t": "虚而浮。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "旁设一虚坐。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "虚中乐喜。", "b": "清·刘开《问说》"}], "words": [{"w": "虚左", "t": "虚尊位以待贤能的人。古代车位以左为尊,故虚以待之"}, {"w": "虚宁", "t": "帝位空悬。"}]}, {"meaning": "居住。", "cites": [{"t": "非其里而虚之,非礼也。", "b": "《荀子·大略》"}]}, {"meaning": "使成为废墟。", "cites": [{"t": "此其所以丧九牧之地,而虚宗庙之国也。", "b": "《荀子》"}]}, {"meaning": "耗费。", "cites": [{"t": "虚其府库,以备车马。", "b": "《墨子》"}, {"t": "浑邪率数万之众来降,[汉]虚府库赏赐,发良民侍养,譬若奉骄子。", "b": "《史记》"}]}, {"meaning": "徒然,白白地。", "cites": [{"t": "贾生年少虚垂涕。", "b": "李商隐《安定城楼》"}, {"t": "好景虚设。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "虚邀", "t": "空邀;白请"}, {"w": "虚生", "t": "徒然活着,白活"}, {"w": "虚花", "t": "白白地耗费"}, {"w": "虚过", "t": "白白地度过"}, {"w": "虚劳", "t": "白费力气"}, {"w": "虚费", "t": "白白地消耗"}, {"w": "虚废", "t": "白白丢弃。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2254wx','彪','1','biāo','彡','11','','[{"pinyin": "biāo", "defs": [{"meaning": "(会意。从虎,从彡(shān)。“彡”,《说文》:“象其文也。”本义:虎身的斑纹)。"}, {"meaning": "同本义。", "cites": [{"t": "彪,虎文也。", "b": "《说文》"}, {"t": "以其弸中而彪外也。", "b": "《法言·君子》。注:“文也。”"}]}, {"meaning": "借喻为文采。", "cites": [{"t": "炳如彪如,尚文昭如。", "b": "扬雄《太玄·文》"}], "words": [{"w": "彪文", "t": "文采丰盛的样子"}, {"w": "彪章", "t": "文采美盛的样子。"}]}, {"meaning": "虎,幼虎。", "cites": [{"t": "熊彪顾盼,鱼龙起伏。", "b": "庾信《枯树赋》"}], "words": [{"w": "彪虎", "t": "猛虎"}, {"w": "彪口", "t": "比喻险要之地。"}]}, {"meaning": "旧小说、戏曲里用于队伍。", "cites": [{"t": "见一彪人马到庄门,匹头里几面旗舒。", "b": "元·睢景臣《哨遍·高祖还乡》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2255wx','雀','1','què qiāo qiǎo','隹','11','','[{"pinyin": "què", "defs": [{"meaning": "(会意。从小隹。“隹”是短尾鸟的泛称,上加三点表示小。本义:麻雀)。"}, {"meaning": "同本义。", "cites": [{"t": "雀,依人小乌也。", "b": "《说文》"}, {"t": "从雀嗷嗷。", "b": "宋玉《高唐赋》"}, {"t": "雀跃而游。", "b": "《庄子·在宥》"}, {"t": "小者至于燕雀。", "b": "《礼记·月令》"}, {"t": "青雀白鹄舫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "雀盲症;雀舌牙茶", "t": "嫩芽茶"}, {"w": "雀子", "t": "麻雀"}, {"w": "雀爪", "t": "像麻雀的爪形,为绘画法中的一种名称"}, {"w": "雀立", "t": "跳跃。一说:竦身而立"}, {"w": "雀豹", "t": "指勇猛的雀"}, {"w": "雀钗", "t": "雀形的钗头"}, {"w": "雀罗", "t": "捕捉麻雀的网子"}, {"w": "雀儿肠肚", "t": "比喻气量小"}, {"w": "雀喜", "t": "早晨雀噪是喜庆之兆"}, {"w": "雀儿", "t": "麻雀,小鸟。"}]}, {"meaning": "泛指小鸟,鸟。", "cites": [{"t": "二人雀弁执惠。", "b": "《书·顾命》。郑注:“赤黑曰雀。”"}], "words": [{"w": "雀舫", "t": "古代鸟形游船"}, {"w": "雀翎", "t": "孔雀或鶡的羽毛"}, {"w": "雀马鱼龙", "t": "泛指珍禽异兽"}, {"w": "雀金泥", "t": "用孔雀毛织成的毛料。"}]}]}, {"pinyin": "qiāo", "defs": [{"meaning": "即‘雀斑’", "words": [{"w": "雀子", "t": "雀斑"}]}]}, {"pinyin": "qiǎo", "defs": [{"meaning": "[方言]用于“家雀儿”（jiāqiǎor）、“雀盲眼”（qiǎomángyǎn）。", "words": [{"w": "雀盲眼", "t": "[方言]∶夜盲,也指夜盲人的眼睛"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2256wx','堂','1','táng','土','11','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从土,尚声。“尚”有“高”义。本义:殿堂。高于一般房屋,用于祭献神灵、祈求丰年)。"}, {"meaning": "同本义。", "cites": [{"t": "堂,殿也。", "b": "《说文》。段注:“古曰堂,汉以后曰殿。古上下皆称堂,汉上下皆称殿。至唐以后,人臣无有称殿者矣。”"}, {"t": "殿,堂之高大者也。", "b": "《说文古本考》"}, {"t": "立于西堂。", "b": "《书·顾命》"}, {"t": "吾见封之若堂者矣。", "b": "礼记·檀弓》。注:“堂形四方而高。”"}, {"t": "王坐于堂上。", "b": "《孟子·梁惠王上》"}, {"t": "燕坐于华堂之上。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "观其坐高堂。", "b": "明·刘基《卖柑者言》"}, {"t": "华堂旅会。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "堂上", "t": "殿堂上"}, {"w": "堂下", "t": "宫殿、厅堂阶下"}, {"w": "堂宇", "t": "殿堂的顶棚"}, {"w": "堂事", "t": "于正厅祭祀祖先之事"}, {"w": "堂阶", "t": "堂下的台阶"}, {"w": "堂阁", "t": "殿堂楼阁"}, {"w": "堂廉", "t": "殿堂的侧边。"}]}, {"meaning": "后泛指房屋的正厅。", "cites": [{"t": "审堂下之阴。", "b": "《吕氏春秋·察今》"}, {"t": "堂前松柱。", "b": "晋·干宝《搜神记》"}, {"t": "崔九堂前几度闻。", "b": "唐·杜甫《江南逢季龟年》"}, {"t": "堂有炼珍。", "b": "清·周容《芋老人传》"}], "words": [{"w": "堂轴", "t": "挂在厅堂壁上的字画"}, {"w": "高堂", "t": "高大的厅堂"}, {"w": "堂户", "t": "门庭之内"}, {"w": "堂筵", "t": "堂中坐席"}, {"w": "堂坳", "t": "堂的低处;泛指低洼之处"}, {"w": "堂扁", "t": "厅堂上的题额"}, {"w": "堂室", "t": "厅堂和内室"}, {"w": "堂前", "t": "正房前面;正厅"}, {"w": "堂房", "t": "堂和房。"}]}, {"meaning": "旧时官府议论政事、审理案件的地方。", "cites": [{"t": "宾客满堂。", "b": "《史记·魏公子列传》"}], "words": [{"w": "堂参", "t": "于公堂上参谒上司"}, {"w": "大堂", "t": "衙门中审理案件的厅堂"}, {"w": "过堂;堂食", "t": "堂馔。堂餐。唐时政事堂的公膳"}, {"w": "堂案", "t": "唐代宰相政事堂的文书档案"}, {"w": "堂厨", "t": "政事堂的公膳房。"}]}, {"meaning": "山上宽阔平坦的地方。", "cites": [{"t": "外堂即向东之坞。", "b": "《徐霞客游记》"}]}, {"meaning": "高显的样子。", "cites": [{"t": "刊层平堂,设切崖。", "b": "《文选·张衡·西京赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2257wx','常','1','cháng','巾','11','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从巾,尚声。本义:旗)。"}, {"meaning": "同本义。", "cites": [{"t": "纪于太常。", "b": "《书·君牙》。传:“王之旌旗画日月曰太常。"}, {"t": "载是常服。", "b": "《诗·小雅·六月》"}]}, {"meaning": "裙子。", "cites": [{"t": "叔旦泣涕于常,悲不能对。", "b": "《逸周书》"}, {"t": "常,下裙也。", "b": "《说文》。朱骏声曰:“常裳二字,经传截然分开,并不通借。”"}]}, {"meaning": "规则,规律。", "cites": [{"t": "陈常于时夏。", "b": "《诗·周颂·思文》"}, {"t": "天行有常,不为尧存,不为桀亡。", "b": "《荀子·天论》"}], "words": [{"w": "常古", "t": "旧法,常法"}, {"w": "常故", "t": "旧例;常例"}, {"w": "常式", "t": "法式。"}]}, {"meaning": "古代长度单位。一丈六尺为常。", "cites": [{"t": "寻舒两肱也,倍寻谓之常。", "b": "《小尔雅·广度》"}, {"t": "蒲筵常。", "b": "《仪礼·公食礼》。注:“丈六尺曰常,半常曰寻。”"}, {"t": "酋予常有四尺。", "b": "《考工记》"}, {"t": "争寻常以尽其民。", "b": "《左传·成公十二年》"}, {"t": "不过墨丈寻常之间。", "b": "《国语·周语》"}, {"t": "寻常之沟。", "b": "《庄子·庚桑楚》"}]}, {"meaning": "恒久;长久不变。", "cites": [{"t": "常,质也。", "b": "《广雅》"}, {"t": "未变常也。", "b": "《易象下传》。虞注:“恒也。”"}, {"t": "鲁邦是常。", "b": "《诗·鲁颂·閟宫》"}, {"t": "天命靡常。", "b": "《诗·大雅·文王》"}, {"t": "日月以为常。", "b": "《国语·越语》"}, {"t": "故官无常贵,而民无终贱。", "b": "《墨子·尚贤》"}, {"t": "圣人无常师。", "b": "唐·韩愈《师说》"}], "words": [{"w": "常德", "t": "始终不变的品德"}, {"w": "常心", "t": "固执不变的心"}, {"w": "常安", "t": "永久的平安。"}]}, {"meaning": "一般;普通;正常。", "cites": [{"t": "其有常。", "b": "《诗·唐风·鸨羽》"}, {"t": "则维其常。", "b": "《诗·小雅·十月之交》"}, {"t": "顾人之常情,由俭入奢易,由奢入俭难。", "b": "宋·司马光《训俭示康》"}, {"t": "且欲与常马等不可得。", "b": "唐·韩愈《杂说》"}, {"t": "白乐天游大林寺诗云:“人间四月芳菲尽,山寺桃花始盛开。”盖常理也。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "常时", "t": "平时;平日"}, {"w": "常言", "t": "平常的话;普通的话。"}]}, {"meaning": "经常,常常。", "cites": [{"t": "常生常化者,无时不生,无时不化。", "b": "《列子》"}, {"t": "汉王急,推堕孝惠、鲁元车下;滕公常下,收载之,如是者三。", "b": "《史记·项羽本纪》"}, {"t": "良因异之,常习诵之。", "b": "《史记·留侯世家》"}, {"t": "千里马常有,而伯乐不常有。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "常见面;常则是", "t": "经常是,总是"}, {"w": "常时", "t": "时常,常常"}, {"w": "常参官", "t": "日常参朝的官吏"}, {"w": "常惺惺", "t": "佛教语。指头脑经常或长久保持清醒"}, {"w": "常经", "t": "经常"}, {"w": "常赁", "t": "经常受雇于人。"}]}, {"meaning": "曾经。", "cites": [{"t": "子常语诸梁也曰:凡事若小若大,寡不道以权成。", "b": "《庄子·人间世》"}, {"t": "主父常游于此。", "b": "《韩非子·外储说左上》"}, {"t": "夫日、月之有蚀,风雨之不时,怪星之常见,是无世而不常有之。", "b": "《荀子·天论》"}, {"t": "高祖为亭长时,常告归之田。", "b": "《史记·高祖本纪》"}, {"t": "项伯常杀人,从良匿。", "b": "《史记·留侯世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2258wx','眶','1','kuàng','目','11','','[{"pinyin": "kuàng", "defs": [{"meaning": "眼眶。", "cites": [{"t": "涣余涕之盈眶。", "b": "柳宗元《吊屈原文》"}], "words": [{"w": "热泪盈眶;夺眶而出", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2259wx','匙','1','chí shi','匕','11','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从匕(bǐ),是声。“匕”食器。本义:古时盛食物的器具。后来的茶匙、汤匙,即由它演变而来)。"}, {"meaning": "姓。"}]}, {"pinyin": "shi", "defs": [{"meaning": "——如“钥匙”(yàoshì)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2260wx','晨','1','chén','日','11','','[{"pinyin": "chén", "defs": [{"meaning": "(会意。从臼,从辰,辰时也。辰亦声。本义:星名。即房星) 清晨。", "cites": [{"t": "晨,早昧爽也。", "b": "《说文》"}, {"t": "晨,早也。", "b": "《尔雅》"}, {"t": "夜乡晨。", "b": "《诗·小雅·庭燎》"}, {"t": "昏定而晨省。", "b": "《礼记·曲礼》"}, {"t": "丙之晨。", "b": "《国语·晋语》。注:“早朝也。”"}, {"t": "而以昏晨犯山川。", "b": "《韩非子·解老》"}, {"t": "晨起不辨衣履。", "b": "清·周容《芋老人传》"}, {"t": "从者多艰其昏晨之往来。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "凌晨五时;霜晨;晨步", "t": "清晨散步"}, {"w": "晨省", "t": "早晨向父母问安"}, {"w": "晨安", "t": "早安"}, {"w": "晨暝", "t": "旦夕"}, {"w": "晨旭", "t": "朝日"}, {"w": "晨旦", "t": "天亮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2261wx','睁','1','zhēng','目','11','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从目,争声。本义:张开眼睛)。"}, {"meaning": "同本义。", "cites": [{"t": "武行者睁着双眼喝道:“你这厮好不晓道理。”", "b": "《水浒传》"}], "words": [{"w": "睁眼苫眉", "t": "装模作样"}, {"w": "睁着眼做,合着眼受", "t": "比喻自作自受,心甘情愿"}, {"w": "睁着眼跳黄河", "t": "比喻进退维谷,走上绝路。"}]}, {"meaning": "看,望;瞪。", "cites": [{"t": "偏偏他却转回程,不敢上前来冲道,闪在傍边仔细睁。", "b": "《天雨花》"}], "words": [{"w": "目睁口呆", "t": "惊惧得瞪大双眼,说不出话来"}, {"w": "圆睁环眼", "t": "眼睛瞪得又大又圆"}, {"w": "睁目张须", "t": "瞪起眼,胡须竖起。形容怒气冲天的神态。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2262wx','眯','1','mī mí mǐ','目','11','','[{"pinyin": "mī", "defs": [{"meaning": "眼皮微微合拢  如:眯着眼睛笑;眯萋(眯睎,眯齐。两眼微合成缝的样子);眯缝(眼皮微合而不全闭)。"}]}, {"pinyin": "mí", "defs": [{"meaning": "", "words": [{"w": "眯梦", "t": "梦魇"}, {"w": "眯语", "t": "梦话。"}]}]}, {"pinyin": "mǐ", "defs": [{"meaning": "(形声。从目,米声。(mǐ)本义:灰沙等物入眼) 同本义。", "cites": [{"t": "眯,草入目中也。", "b": "《说文》"}, {"t": "夫播糠眯目,则天地四方易位矣。", "b": "《庄子·天运》"}, {"t": "故若眯而抚,若跌而据。", "b": "《淮南子·缪称》。注:“眯,芥入目也。”"}, {"t": "蒙尘而眯。", "b": "《淮南子·说林》"}], "words": [{"w": "砂子眯眼了;眯膜", "t": "目不明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2263wx','眼','1','yǎn','目','11','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从目,艮(gèn)声。本义:眼珠)。"}, {"meaning": "同本义。", "cites": [{"t": "眼,目也。", "b": "《说文》"}, {"t": "眼,限也。瞳子限限而出也。", "b": "《释名》"}, {"t": "巽为多白眼。", "b": "《易·说卦》"}, {"t": "比干剖心,子胥抉眼,忠之祸也。", "b": "《庄子·盗跖》"}]}, {"meaning": "泛指眼睛。", "cites": [{"t": "莫自使眼枯,收汝泪纵横。", "b": "杜甫《新安吏》"}], "words": [{"w": "眼馋肚饱", "t": "贪得无厌;不知足"}, {"w": "眼意心期", "t": "眼中传意,心中期待"}, {"w": "眼黄地黑", "t": "心怀叵测,见财起意"}, {"w": "眼空四海", "t": "目中无人,妄自尊大"}, {"w": "眼张失道", "t": "睁大眼睛,说不出话来。形容受惊而痴呆的样子"}, {"w": "眼里出火", "t": "形容极贪婪的神情"}, {"w": "眼同检验", "t": "会同人员,共同检验"}, {"w": "眼皮子薄", "t": "比喻气量小,喜欢斤斤计较"}, {"w": "眼上眼下", "t": "上下端详"}, {"w": "眼盻盻", "t": "喻指极为厌恶憎恨的人。"}]}, {"meaning": "耳目;眼线。", "cites": [{"t": "当下就带孙小二做眼,飞马赶到北关门下。", "b": "《警世通言》"}]}, {"meaning": "见证。", "cites": [{"t": "教地方公同作眼,将梁公家家财什物变卖了。", "b": "《古今小说》"}], "words": [{"w": "眼证", "t": "当场目睹可作证的人;见证人。"}]}, {"meaning": "指孔;洞穴。", "cites": [{"t": "泉眼无声惜细流。", "b": "杨万里《小池》"}], "words": [{"w": "眼子", "t": "孔洞"}, {"w": "眼孔", "t": "孔;小洞。"}]}, {"meaning": "围棋用语。成片的白子或黑子中间的空心,在这个空心中对手不能下子。", "cites": [{"t": "探春因一块棋受了敌,算来算去总得了两个眼。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2264wx','悬','1','xuán','心','11','','[{"pinyin": "xuán", "defs": [{"meaning": "(形声。从心,县声。本作“县”,象断首倒挂,后加“系”。假借为行政区域的“县”后,另加“心”字表示悬挂。本义:吊挂)。"}, {"meaning": "同本义。", "cites": [{"t": "悬者植梯接之。", "b": "《徐霞客游记·游黄山记》"}, {"t": "以叵幅悬之。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "倒悬之。", "b": "清·张廷玉《明史》"}], "words": [{"w": "悬丝诊脉", "t": "传说古代中医诊脉法之一。不见面将丝线系于病人腕上诊脉治病"}, {"w": "悬壁", "t": "相学术语。指脸部接近耳垂下端处的部位。"}]}, {"meaning": "凭空设想;揣测。", "cites": [{"t": "你们做的事,须自己承认。怎么悬定得罪?——《梼杌闲评——明珠缘》", "b": ""}], "words": [{"w": "悬度", "t": "无根据地揣测、估计"}, {"w": "悬料", "t": "凭空臆测"}, {"w": "悬猜", "t": "揣测,猜想。"}]}, {"meaning": "系连,关联。", "cites": [{"t": "吏者,民之所悬命也。", "b": "《管子》"}, {"t": "王之命悬于遂手。", "b": "《史记·平原君虞卿列传》"}]}, {"meaning": "悬钟、磬等乐器的架子。", "cites": [{"t": "宿燎设悬。", "b": "唐·柳宗元《道州文宣王庙碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2265wx','野','1','yě','里','11','','[{"pinyin": "yě", "defs": [{"meaning": "(形声。从里,予声。《尔雅·释言》:“里,邑也。”本义:郊外;野外)。"}, {"meaning": "同本义。", "cites": [{"t": "野,郊外也。", "b": "《说文》"}, {"t": "邑外谓之郊,郊外谓之野。", "b": "《说文》。段注"}, {"t": "龙战于野。", "b": "《易·坤》"}, {"t": "王朝至于商郊牧野。", "b": "《书·牧誓》"}, {"t": "七月在野。", "b": "《诗·豳风·七月》"}, {"t": "体国经野。", "b": "《周礼》。注:“谓一百里以外三等采地之中。”"}, {"t": "永州之野产异蛇。", "b": "柳宗元《捕蛇者说》"}, {"t": "捐金于野。", "b": "《后汉书·列女传》"}, {"t": "野茫茫。", "b": "《乐府诗集·杂歌谣辞·敕勒歌》"}, {"t": "光照旷野。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "野外", "t": "郊外"}, {"w": "野生;野渡", "t": "郊野的渡口。"}]}, {"meaning": "原野,田野。", "cites": [{"t": "野火烧不尽,春风吹又生。", "b": "白居易《赋得古原草送别》"}], "words": [{"w": "野盘", "t": "可容身的山野之地"}, {"w": "野马", "t": "浮游的云气"}, {"w": "野井", "t": "乡野间的井水"}, {"w": "野次", "t": "原野"}, {"w": "野老", "t": "居于田野的老人"}, {"w": "野色", "t": "原野的景色"}, {"w": "野战", "t": "军队在旷野作战"}, {"w": "野霭", "t": "山野中的云气。"}]}, {"meaning": "指民间。与朝廷相对。", "cites": [{"t": "朝野清晏,国富兵强。", "b": "《晋书》"}], "words": [{"w": "野乘", "t": "私家记载的史书"}, {"w": "野录", "t": "私人撰述的史乘。同“野史、野乘”"}, {"w": "野人之芹", "t": "乡下人的菲薄礼品"}, {"w": "野服", "t": "乡居朴素的服装。对官服而言。"}]}, {"meaning": "非家养的;野生的。"}, {"meaning": "动物未经人畜养的。", "cites": [{"t": "野蜂巢。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "野鹤步罡", "t": "喻步履蹒跚"}, {"w": "野鸡翎", "t": "雉的尾羽"}, {"w": "野鹤", "t": "野生的鹤。"}]}, {"meaning": "植物未经人工种植培养的。", "cites": [{"t": "野芳发而幽香(野花开了,有一股清幽的香味,芳,香花。发,开放)。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "野谷是资", "t": "只取野谷为食"}, {"w": "野蔌", "t": "野菜。如薇笋之类。"}]}, {"meaning": "不驯服,不受拘束。", "cites": [{"t": "狼子野心。", "b": "《左传·宣公四年》"}], "words": [{"w": "野猫", "t": "喻举动粗鲁,不守规矩或行为放肆的人。"}]}, {"meaning": "粗鲁,粗野,野蛮,不文雅。", "cites": [{"t": "野哉由也!", "b": "《论语》"}, {"t": "朔风野大。", "b": "清·袁枚《祭妹文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2266wx','啪','1','pā','口','11','','[{"pinyin": "pā", "defs": [{"meaning": "微弱的或轻微的拍打声。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2267wx','啦','1','la lā','口','11','','[{"pinyin": "la", "defs": [{"meaning": "是语气词“了”(le)和“啊”(a)的合音,兼有语气词“了”和“啊”的作用。"}, {"meaning": "用在句末表示喜悦、赞叹、惊奇、气愤。"}, {"meaning": "用在句末,表示情况已经变化或将要出现新的情况。"}, {"meaning": "用在句末,表示肯定、解释、劝止。"}, {"meaning": "用在句末,表示疑问。"}, {"meaning": "用在列举的事项之后,表示停顿。"}]}, {"pinyin": "lā", "defs": [{"meaning": "闲扯,闲谈", "words": [{"w": "啦呱", "t": "闲聊"}, {"w": "人人都愿意和他啦", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2268wx','曼','1','màn','曰','11','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。小篆字形,从又,冒声。又,手。从“又”与手的动作有关。本义:长)。"}, {"meaning": "同本义。", "cites": [{"t": "曼,引也。", "b": "《说文》"}, {"t": "孔曼且硕,万民是若。", "b": "《诗·鲁颂·閟宫》"}, {"t": "韩娥因曼声哀哭。", "b": "《列子·汤问》"}, {"t": "侯同曼声之歌。", "b": "《淮南子·泛论》"}, {"t": "娥眉曼睩。长发曼鬋。", "b": "《楚辞·招魂》"}, {"t": "曼寿。", "b": "《汉书·礼乐志》"}, {"t": "曼辞以自解。", "b": "《汉书·司马迁传》"}, {"t": "路曼曼其修远兮,吾将上下而求索。", "b": "《楚辞·离骚》"}, {"t": "曼声歌之。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "曼胡", "t": "无刃的长戟。一作镘胡"}, {"w": "曼寿", "t": "长寿"}, {"w": "曼啸", "t": "长啸"}, {"w": "曼志", "t": "远大的志向"}, {"w": "曼靡", "t": "形容乐声悠长而柔和"}, {"w": "曼曼", "t": "形容距离远或时间长。"}]}, {"meaning": "柔美;细润。", "cites": [{"t": "秀曼都雅,一军惊视。", "b": "《新唐书·李光颜传》"}], "words": [{"w": "曼睇", "t": "媚视,美盼"}, {"w": "曼颊", "t": "细嫩的面颊"}, {"w": "曼丽", "t": "柔媚美丽"}, {"w": "曼妙", "t": "美艳;柔美"}, {"w": "曼帛", "t": "细腻精美的丝帛"}, {"w": "曼理", "t": "细腻的肌肤。"}]}, {"meaning": "延长;拉长。", "cites": [{"t": "曼余目以流观兮。", "b": "《楚辞·九章·哀郢》"}]}, {"meaning": "没有。", "cites": [{"t": "行有之也,病曼之也。", "b": "《法言·五百》"}]}, {"meaning": "蔓延。", "cites": [{"t": "遂至延曼连州。", "b": "《汉书·王莽传下》"}]}, {"meaning": "古时对南方少数民族的泛称。", "cites": [{"t": "楚子诱戎曼子杀之。", "b": "《公羊传·昭公十六年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2269wx','晦','1','huì','日','11','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从日,每声。本义:阴历每月的最后一天)。"}, {"meaning": "同本义。", "cites": [{"t": "晦,月尽也。", "b": "《说文》"}, {"t": "三十日日月合宿,谓之晦。", "b": "《论衡·四讳》"}, {"t": "陈不违晦。", "b": "《左传·成公十七年》"}, {"t": "朝菌不知晦朔。", "b": "《庄子·逍遥游》"}, {"t": "不知晦朔。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "戊申晦。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "晦望", "t": "农历每月末一日与十五日"}, {"w": "晦景", "t": "晦日,晦节"}, {"w": "晦日", "t": "农历每月最后的一天。"}]}, {"meaning": "夜;晚。", "cites": [{"t": "晦淫惑疾。", "b": "《左传·昭公元年》。注:“夜也。”"}], "words": [{"w": "晦明", "t": "从黑夜到天明。即昼夜"}, {"w": "晦晓", "t": "夜晚与天明"}, {"w": "晦魄", "t": "夜月"}, {"w": "风雨如晦", "t": ""}]}, {"meaning": "昏暗。", "cites": [{"t": "晦而休。", "b": "《国语·鲁语》。注:“冥也。”"}, {"t": "是时雷电晦冥。", "b": "《汉书·高帝纪》"}, {"t": "幽晦以多雨。", "b": "《楚辞·屈原·涉江》"}, {"t": "道途显晦。", "b": "唐·李朝威《柳毅传》"}, {"t": "晦明变化。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "晦冥", "t": "昏暗"}, {"w": "晦蒙", "t": "昏暗"}, {"w": "晦盲", "t": "昏暗不明"}, {"w": "晦芒", "t": "昏暗。"}]}, {"meaning": "义理深微;隐晦;含蓄。", "cites": [{"t": "志而晦。", "b": "《左传·成公十四年》"}], "words": [{"w": "晦伏", "t": "隐晦不显"}, {"w": "晦昧", "t": "隐晦不明"}, {"w": "晦窒", "t": "晦涩不通"}, {"w": "晦塞", "t": "晦涩不畅。"}]}, {"meaning": "草木凋零。", "cites": [{"t": "寂历百草晦。", "b": "江淹《诗》。注:“凡草木华实荣茂谓之明,枝叶凋伤谓之晦。”"}], "words": [{"w": "晦在", "t": "凋零将尽,健在的已经很少了。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2270wx','晚','1','wǎn','日','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从日,免声。本义:傍晚;黄昏)。"}, {"meaning": "同本义。", "cites": [{"t": "晚,莫也。", "b": "《说文》"}, {"t": "晚,暮也。", "b": "《广韵》"}, {"t": "四时失序,则辰星作异。…政急则出蚤,政缓则出晚。", "b": "《汉书·李寻传》"}, {"t": "晚成单罗衫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "晚泊沙夹。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "一屠晚归。", "b": "《聊斋志异·狼三则》"}, {"t": "望晚日照城郭。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "晚曦", "t": "晚霞"}, {"w": "晚夕", "t": "傍晚,晚上"}, {"w": "晚半天儿", "t": "晚夕,晚晌,晚间,晚上"}, {"w": "晚钟", "t": "傍晚的钟声"}, {"w": "晚寒", "t": "傍晚的寒气"}, {"w": "晚晴;晚饷", "t": "晚餐"}, {"w": "晚阴", "t": "傍晚时的阴霾"}, {"w": "晚来", "t": "傍晚。"}]}, {"meaning": "夜晚。", "cites": [{"t": "晚星没。", "b": "庾信《对烛赋》"}], "words": [{"w": "晚吹", "t": "夜晚的风"}, {"w": "晚头", "t": "晚上"}, {"w": "晚月", "t": "夜月"}, {"w": "晚炬", "t": "夜间的火炬"}, {"w": "晚漏", "t": "晚更"}, {"w": "晚魄", "t": "月亮"}, {"w": "晚逻", "t": "夜间巡逻。"}]}, {"meaning": "晚年。", "cites": [{"t": "晚出榆关逐北征,惊沙飞迸冲貂袍。", "b": "温庭筠《塞寒行》"}], "words": [{"w": "晚运", "t": "晚年。运指时期"}, {"w": "晚涂", "t": "晚年"}, {"w": "晚境", "t": "晚年的境遇;晚年"}, {"w": "晚悟", "t": "晚年觉悟。"}]}, {"meaning": "旧时官场后辈对前辈、下级对上级称晚生,简言曰晚。多用于书信。", "cites": [{"t": "恕治晚不能躬送了。", "b": "《儒林外史》"}]}, {"meaning": "时间靠后。属于或关于时间上或发展上的后期阶段的。", "cites": [{"t": "兴尽晚归舟。", "b": "宋·李清照《如梦令》"}, {"t": "事之晚矣。", "b": "《资治通鉴·汉纪》"}, {"t": "土气有早晚。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "自有早晚。", "b": ""}, {"t": "后种者晚实。", "b": ""}], "words": [{"w": "晚唐;晚父;晚母", "t": "后母;继母"}, {"w": "晚爷", "t": "后父"}, {"w": "晚妻", "t": "后续之妻"}, {"w": "晚嫁", "t": "再嫁"}, {"w": "晚伯母", "t": "伯父后来续娶的妻子"}, {"w": "晚进", "t": "后进;后辈"}, {"w": "晚婆", "t": "晚娘,继母。"}]}, {"meaning": "迟,在规定的、通常的或恰当的时间以后来的或做的。", "cites": [{"t": "大器晚成。", "b": "《老子》四十一章"}], "words": [{"w": "晚达", "t": "显达较迟"}, {"w": "晚日", "t": "近日;最近几天"}, {"w": "晚歇", "t": "第二次嫁人"}, {"w": "晚客;晚茶", "t": "迟采摘的茶叶"}, {"w": "晚麦", "t": "迟熟的麦"}, {"w": "晚代", "t": "近世"}, {"w": "晚禾", "t": "晚稻"}, {"w": "晚甲", "t": "迟发的芽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2271wx','啄','1','zhuó','口','11','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从口,豖(chù)声。本义:鸟用嘴取食)。"}, {"meaning": "同本义。", "cites": [{"t": "啄,鸟食也。", "b": "《说文》"}, {"t": "啄啮也。", "b": "《广雅》"}, {"t": "谁家燕子啄春泥。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "檐牙高啄。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "径进以啄。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "幸啄不中。", "b": ""}], "words": [{"w": "啄抱", "t": "禽鸟幼雏破壳而出"}, {"w": "啄啄", "t": "禽鸟取食的样子"}, {"w": "啄饮", "t": "啄食饮水"}, {"w": "啄噪", "t": "啄食鸣叫"}, {"w": "啄木", "t": ""}]}, {"meaning": "敲击。", "cites": [{"t": "归来残月窥窗角,星初落,几回欲把朱扉啄,人知觉。", "b": "潘必正《杨柳枝》"}]}, {"meaning": "咬。", "cites": [{"t": "虎豹九关,啄害下人些。", "b": "《楚辞·宋玉·招魂》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2272wx','啡','1','fēi','口','11','','[{"pinyin": "fēi", "defs": [{"meaning": "——见“咖啡”(kāfēi)、“吗啡”(mǎfēi)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2273wx','距','1','jù','足','11','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从足,巨声。本义:鸡爪)。"}, {"meaning": "同本义。", "cites": [{"t": "距,鸡距也。", "b": "《说文》"}, {"t": "后阺为之金距。", "b": "《左传》"}, {"t": "不鸣不将无距。", "b": "《汉书·五行志》。注:“距,鸡附足骨,斗时所用刺之。”"}, {"t": "虽有钩针芒距。", "b": "《淮南子·原道》"}, {"t": "长皆及俎距。", "b": "《仪礼·少牢礼》。注:“胫中当横节也。”"}, {"t": "公输之刻凤也,冠距未成。", "b": "《列子》"}]}, {"meaning": "距离。", "cites": [{"t": "距随长武。", "b": "《仪礼·乡射礼记》"}], "words": [{"w": "苗距;槽距;差距;焦距;行距;株距;距国", "t": "介于大国之间,或两面受敌的国家"}, {"w": "距随", "t": "古人射箭站立时两脚的间隔距离。"}]}, {"meaning": "倒刺。"}, {"meaning": "古代兵器锋刃上的倒刺。"}, {"meaning": "钓钩上的倒刺。"}, {"meaning": ""}, {"meaning": "抗拒;抵御。", "cites": [{"t": "墨子九距之。", "b": "《墨子·公输》"}, {"t": "密人不恭,敢距大邦。", "b": "《诗·大雅·皇矣》"}, {"t": "断足以距难。", "b": "《荀子·君道》"}, {"t": "楚闻之,发兵距之阳夏,不得前。", "b": "《史记·高祖本纪》"}]}, {"meaning": "拒绝。", "cites": [{"t": "闲先圣之道,距杨墨,放淫辞。", "b": "《孟子·滕文公下》"}, {"t": "其无距言。", "b": "《潜夫论·明闇》"}, {"t": "受而不距。", "b": "《风俗通义·愆礼》"}, {"t": "距关,毋内诸侯。(距,与“拒”通,抵檝、守卫。)", "b": "《史记·项羽本纪》"}], "words": [{"w": "距捍", "t": "抵抗防御"}, {"w": "距谏饰非", "t": "不听劝谏,掩饰过错"}, {"w": "距关", "t": "闭关据守"}, {"w": "距难", "t": "拒绝并加以责难;抗拒祸患。"}]}, {"meaning": "离;距离。", "cites": [{"t": "距小孤一里。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "距其院东五里。", "b": "宋·王安石《游褒禅山记》"}, {"t": "距洞百余步。", "b": ""}, {"t": "距圆明园十里,有村曰谢庄。(距,距离。)", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "至,到达。", "cites": [{"t": "距陆而止。", "b": "《庄子·渔父》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2274wx','趾','1','zhǐ','足','11','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从足,止声。古所谓趾,指足,不指脚趾。脚指叫做指,趾是“止”的后起字。本义:脚)。"}, {"meaning": "同本义。", "cites": [{"t": "三之日于耜,四之日举趾。", "b": "《诗·豳风·七月》"}, {"t": "贲其趾。", "b": "《易·贲卦》"}, {"t": "屦校灭趾。", "b": "《易·噬嗑卦》"}, {"t": "麟之趾。", "b": "《诗·周南·麟之趾》"}, {"t": "今君若步玉趾。", "b": "《左传·昭公七年》"}, {"t": "足趾之所不蹈。", "b": "左思《吴都赋》。王力注:“足趾是同义词连用,‘趾’不是足指。”"}], "words": [{"w": "趾股", "t": "腿脚"}, {"w": "趾踵", "t": "脚"}, {"w": "趾踵相接", "t": "形容人数之多"}, {"w": "趾爪", "t": "脚爪。"}]}, {"meaning": "脚指头。", "cites": [{"t": "右手攀右趾若啸呼状。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "脚趾", "t": "脚前端的分支"}, {"w": "鹅鸭之类趾间有蹼;趾绊", "t": "本屐上的趾袢儿"}, {"w": "趾趾", "t": "足尖轻轻着地行走的声音。"}]}, {"meaning": "支撑器物的脚。", "cites": [{"t": "鼎颠趾。", "b": "《易·鼎》"}]}, {"meaning": "基址。", "cites": [{"t": "略基趾。", "b": "《左传·宣公十一年》"}, {"t": "亭亭峻趾。", "b": "左思《魏都赋》"}, {"t": "去上西山趾。", "b": "阮籍《咏怀》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2275wx','啃','1','kěn','口','11','','[{"pinyin": "kěn", "defs": [{"meaning": "(形声。从口,肯声。本义:用牙齿剥食坚硬的东西)。"}, {"meaning": "坑,害。", "cites": [{"t": "我的大太爷?那真啃死小人了!", "b": "《官场现形记》"}]}, {"meaning": "咳嗽声。", "cites": [{"t": "这不是小事,的确该三思而后行。…啃,啃…依我愚见,…啃,啃…暂时压一下,莫忙交到会上。", "b": "李劼人《大波》"}]}, {"meaning": "“龈”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2276wx','跃','1','yuè','足','11','','[{"pinyin": "yuè", "defs": [{"meaning": "(形声。从足,翟(dí)声。本义:跳跃)。"}, {"meaning": "同本义。", "cites": [{"t": "跃,跳也。", "b": "《广雅》"}, {"t": "涌趯(跃)邪阴。", "b": "《汉书·李寻传》。师古曰:“趯字与跃同。”"}, {"t": "骐骥一跃。", "b": "《荀子·劝学》"}, {"t": "浮光跃金。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "跃掷径出。", "b": "《聊斋志异·促织》"}, {"t": "若将跃舞。", "b": ""}, {"t": "跃起持之。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "跃龙门", "t": "比喻科举考试"}, {"w": "跃如", "t": "踊跃的样子"}, {"w": "跃治", "t": "比喻人好炫耀以求表现"}, {"w": "跃马横戈", "t": "骑马奔跃,横握长戈"}, {"w": "跃动", "t": "跳动"}, {"w": "跃跃", "t": "跳动的样子。又指跳跃迅速的样子"}, {"w": "跃跃欲试", "t": "心动而想尝试。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2277wx','略','1','lüè','田','11','','[{"pinyin": "lüè", "defs": [{"meaning": "(形声。从田,各声。本义:封疆土地)。"}, {"meaning": "同本义。", "cites": [{"t": "略,经略土地也。", "b": "《说文》"}, {"t": "天子经略土地,定城国,制诸侯。", "b": "《左传·昭公七年》"}]}, {"meaning": "巡视;巡行。", "cites": [{"t": "公曰:“吾将略地焉。”", "b": "《左传·隐公五年》"}], "words": [{"w": "略地", "t": "巡视侵边境"}, {"w": "略阵", "t": "巡视阵地。"}]}, {"meaning": "抢劫;夺取。", "cites": [{"t": "略,求也。秦晋之间搜,就室曰搜,于道曰略。略,强取也。", "b": "《方言》二"}, {"t": "以略狄土。", "b": "《左传·襄公十五年》"}, {"t": "略共武夫。", "b": "《左传·成公十二年》"}, {"t": "牺牲不略。", "b": "《国语·齐语》"}, {"t": "少君年四五岁时,家贫,为人所略卖。", "b": "《史记·外戚世家》"}, {"t": "渤海又多劫略相随。", "b": "《汉书·龚遂传》"}, {"t": "略定东南。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "又。", "cites": [{"t": "统军略地。", "b": ""}, {"t": "进兵北略地。", "b": "《战国策·燕策》"}], "words": [{"w": "略取", "t": "夺取"}, {"w": "略人", "t": "略夺人口"}, {"w": "略卖", "t": "劫掠贩卖"}, {"w": "略通", "t": "略取和开通"}, {"w": "略有", "t": "据有;掠得"}, {"w": "略野", "t": "攻占原野"}, {"w": "略城", "t": "攻占城市。"}]}, {"meaning": "忽略。", "cites": [{"t": "不以先进略后生。", "b": "王安石《谢王司封启》"}]}, {"meaning": "又 如: 略迹原心(撇开表面的事实,而从其用心上加以原谅);略迹论心(撇开表面的事实而评论其用心)。"}, {"meaning": "省去;省略。", "cites": [{"t": "自非略其秽,集其精英,盖欲兼功,大半难矣。", "b": "萧统《文选序》"}]}, {"meaning": "疆界。", "cites": [{"t": "略,界也。", "b": "《小尔雅》"}, {"t": "王与之武公之略,自虎牢以东。", "b": "《左传·庄公二十一年》"}, {"t": "略秦伯以河外列城五,东尽虢略。", "b": "《左传 ·僖公十五年》"}]}, {"meaning": "要点;概要;概况。", "cites": [{"t": "我为汝言其大略。", "b": "《庄子·大宗师》"}], "words": [{"w": "大略", "t": ""}]}, {"meaning": "谋略。", "cites": [{"t": "孙吴之略。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "宏才大略;略不世出", "t": "谋略高明,世所少有"}, {"w": "略术", "t": "谋略道术。"}]}, {"meaning": "简明、简洁;简略。", "cites": [{"t": "加一字太详,减一字太略。", "b": "刘知几《史通》"}], "words": [{"w": "略节", "t": "简要的禀帖"}, {"w": "略传", "t": "简略的传记"}, {"w": "略意", "t": "略陈本意"}, {"w": "略要", "t": "概要。"}]}, {"meaning": "锋利。", "cites": [{"t": "有略其耜,俶载南亩。", "b": "《诗·周颂·载芟》"}]}, {"meaning": "大约,大致。", "cites": [{"t": "老略知书。", "b": "清·周容《芋老人传》"}, {"t": "略已平矣。", "b": "《资治通鉴》"}], "words": [{"w": "略等", "t": "大约相等,差不多"}, {"w": "略绰", "t": "阔大;大略"}, {"w": "略订", "t": "约略计算"}, {"w": "略约", "t": "约略。"}]}, {"meaning": "全;皆。", "cites": [{"t": "敬亭丧失其资略尽。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "略无慕艳意。", "b": "明·宋濂《送东阳马生序》"}, {"t": "归燕略无三月事。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "略无", "t": "全无"}, {"w": "略识之无", "t": "初识文字,认字不多。"}]}, {"meaning": "简略地;稍微。", "cites": [{"t": "略语则阙,详说则繁。", "b": "《文心雕龙·物色》"}], "words": [{"w": "略约", "t": "简略配制"}, {"w": "略陈", "t": "简要地陈述"}, {"w": "略情", "t": "把事情看得很随便"}, {"w": "略及", "t": "稍微提及"}, {"w": "略言之;略述", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2278wx','蚯','1','qiū','虫','11','','[{"pinyin": "qiū", "defs": [{"meaning": "环节动物，身体细长柔软，生活于土中，以带有机物的土壤为食，使土壤疏松，对农作物有益。可作鱼和家禽的食饵，可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2279wx','蛀','1','zhù','虫','11','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从虫,主声。本义:蛀虫)。"}, {"meaning": "同本义。", "cites": [{"t": "蠹侵嘉树,蛀耗米珠。", "b": "明·顾大韶《又后虱赋》"}], "words": [{"w": "蛀食", "t": "谓蛀虫咬吃"}, {"w": "蛀心虫", "t": "二化螟、三化螟、大螟、玉米螟等幼虫的统称"}, {"w": "蛀书蠹", "t": "蛀蚀书卷的蠹鱼。借指只知啃书本读书的人"}, {"w": "蛀书虫", "t": "蛀书蠹。"}]}, {"meaning": "蠹蚀;被蛀虫咬坏。", "cites": [{"t": "木犀蛀者,用芝麻带壳悬树上。", "b": "宋·苏轼《格物粗谈》"}], "words": [{"w": "蛀孔", "t": "虫蛀咬后留下的孔洞"}, {"w": "蛀蚀", "t": "因被虫蛀而受损伤。常比喻伤害"}, {"w": "蛀牙", "t": "龋齿的俗称"}, {"w": "蛀齿", "t": "即龋齿。齿质受腐蚀的病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2280wx','蛇','1','shé yí','虫','11','','[{"pinyin": "shé", "defs": [{"meaning": "(形声。从虫,它声。本写作“它”。甲骨文字形,是象形字。本义:一种爬行动物)。"}, {"meaning": "同本义。", "cites": [{"t": "蛇,它或从虫。", "b": "《说文》"}, {"t": "蛇乘龙。", "b": "《左传·襄公二十八年》。注:“蛇,元武之宿,虚危之星。”"}, {"t": "为虺弗摧,为蛇将若何?", "b": "《国语·吴语》。注:“虺小蛇大也。"}, {"t": "龙蛇之孽。", "b": "《洪紀·五行志》。注:“蛇龙之类也。”"}, {"t": "龙首其中蛇交。", "b": "《仪礼·乡射礼记》"}, {"t": "维虺维蛇。", "b": "《诗·小雅·斯干》"}, {"t": "永州之野产异蛇,黑质而白章。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "蛇豕", "t": "比喻贪婪残暴的人"}, {"w": "蛇虺", "t": "喻指阴狠毒辣的人"}, {"w": "蛇食", "t": "像蛇吃东西一般地吞食"}, {"w": "蛇蜕", "t": "蛇所脱下的皮"}, {"w": "蛇解", "t": "即蛇脱皮"}, {"w": "蛇入鼠出", "t": "比喻行动隐秘"}, {"w": "蛇行鼠步", "t": "形容胆小谨慎"}, {"w": "蛇盘鬼附", "t": "比喻相互勾结"}, {"w": "蛇蟠蚓结", "t": "比喻互相勾结"}, {"w": "蛇心佛口", "t": "喻指假冒伪善、内心狠毒而表面和善"}, {"w": "蛇雀之报", "t": "自述感恩图报的词语。即视己为蛇、雀而报恩。"}]}, {"meaning": "象征国君、君子等。", "cites": [{"t": "有蛇自泉宫出,入于国,如先君之数。", "b": "《左传》"}]}]}, {"pinyin": "yí", "defs": [{"meaning": "——见“委蛇”(wēiyí)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2281wx','唬','1','hǔ xià','口','11','','[{"pinyin": "hǔ", "defs": [{"meaning": "虚张声势、夸大事实来吓人。", "cites": [{"t": "唬,虎声也。从口虎。", "b": "《说文》"}], "words": [{"w": "你别唬人;唬吓", "t": "吓唬"}, {"w": "唬弄", "t": "糊弄。欺骗;蒙混。"}]}]}, {"pinyin": "xià", "defs": [{"meaning": "恐惧,害怕。", "cites": [{"t": "唬得目瞪口呆。", "b": "《红楼梦》"}], "words": [{"w": "唬杀", "t": "吓死;吓坏了。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2282wx','累','1','léi lěi lèi','糸','11','','[{"pinyin": "léi", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,畾(雷)声。本义:绳索)。"}, {"meaning": "同本义。也作“缧”。", "cites": [{"t": "累,一曰大索也。", "b": "《说文》"}, {"t": "两释累囚。", "b": "《左传·成公三年》"}, {"t": "以剑斫绝累。", "b": "《汉书·李广传》"}], "words": [{"w": "累绁", "t": "绑罪犯的绳索。引申为囚禁,牢狱"}, {"w": "系累", "t": "系结绳索"}, {"w": "累囚", "t": "被拘囚的人。"}]}, {"meaning": "重叠;接连成串。", "cites": [{"t": "层台累榭,临高山些。", "b": "《楚辞·招魂》"}], "words": [{"w": "累棋", "t": "堆叠棋子"}, {"w": "累叠", "t": "堆叠"}, {"w": "累纸", "t": "接连许多张纸。"}]}, {"meaning": "拘系;捆绑。", "cites": [{"t": "系累其弟子。", "b": "《孟子·梁惠王下》"}, {"t": "系累其老弱妇女。", "b": "《史记》"}], "words": [{"w": "累坠", "t": "拖累,累赘"}, {"w": "累囚", "t": "被拘系的俘囚。"}]}]}, {"pinyin": "lěi", "defs": [{"meaning": "(会意。字本象土块相积之形;从糸(mì),细丝,织物由细丝积累而成,因而也取积累的意思。隶变以后写作“累”。本义:堆积,积聚)。"}, {"meaning": "同本义。", "cites": [{"t": "一丝而累。", "b": "《后汉书·列女传》"}]}, {"meaning": "又。", "cites": [{"t": "累寸不已。", "b": ""}], "words": [{"w": "危如累卵;累堆", "t": "累赘"}, {"w": "累瓦结绳", "t": "比喻堆砌重复,多余无用的言词"}, {"w": "累丸", "t": "叠积弹丸"}, {"w": "累重", "t": "累积厚重"}, {"w": "累茵", "t": "本指铺积茵、毯之类,以侍亲坐。后因称对已故父母的哀思为累茵之悲。"}]}, {"meaning": "玷污。", "cites": [{"t": "赵王反形未露,逆谋未彰,今遽用兵伐之,恐伤先帝之爱,有累陛下之仁。", "b": "明·孙高亮《于谦全传》"}, {"t": "薄产累尽。", "b": "《聊斋志异·促织》"}, {"t": "累汝至此者。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "连续;多次。", "cites": [{"t": "累召不应。", "b": "《后汉书·张衡传》"}]}, {"meaning": "(累:屡次。今有双音词“累次”。召:被征召。应:应召)。", "cites": [{"t": "累官故不失州郡也。", "b": "《资治通鉴》"}, {"t": "狂走者累日。", "b": "唐·柳宗元《柳河东集》"}, {"t": "倍赏累罚。", "b": "《韩非子·五蠹》"}]}, {"meaning": "又。", "cites": [{"t": "累世絜驾。", "b": ""}], "words": [{"w": "累七", "t": "七个七,即四十九天"}, {"w": "累世之亲", "t": "世代都成姻亲"}, {"w": "累旬", "t": "连续数十日"}, {"w": "累减", "t": "依次递减"}, {"w": "累宵", "t": "连夜"}, {"w": "累捷", "t": "连续得胜"}, {"w": "累战", "t": "连战,持续战。"}]}, {"meaning": "姓。"}]}, {"pinyin": "lèi", "defs": [{"meaning": "罪行;过失。", "cites": [{"t": "同是一累,而未判其得失。", "b": "《世说新语》"}], "words": [{"w": "罪累", "t": "罪过。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2283wx','鄂','1','è','阝','11','','[{"pinyin": "è", "defs": [{"meaning": "古地名。"}, {"meaning": "湖北省的简称 。因清代省会武昌是隋以后鄂州的治所而得名。"}, {"meaning": "边界。", "cites": [{"t": "纷被丽而亡鄂。", "b": "《文选·扬雄·甘泉赋》"}]}, {"meaning": "惊愕。", "cites": [{"t": "象鄂不怿。", "b": "《史记·五帝本纪》"}, {"t": "“孺子,下取履!”良鄂然,欲殴之。", "b": "《史记·留侯世家》"}, {"t": "群臣皆惊鄂失色,莫敢发言,但唯唯而已。", "b": "《汉书·霍光传》"}], "words": [{"w": "鄂然", "t": "吃惊的样子。"}]}, {"meaning": "花托。", "words": [{"w": "鄂鄂", "t": "花开放的样子"}, {"w": "鄂不", "t": "花萼和花托"}, {"w": "鄂足", "t": "花托。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2284wx','唱','1','chàng','口','11','','[{"pinyin": "chàng", "defs": [{"meaning": "(形声。从口,昌声。“唱”字经传以“倡”为之。本义:领唱)。"}, {"meaning": "同本义。", "cites": [{"t": "唱,导也。", "b": "《说文》"}, {"t": "取其唱予和女。", "b": "《左传·昭公十六年》注"}, {"t": "唱和有应。", "b": "《荀子·乐论》"}, {"t": "晷漏肃唱。", "b": "《文选·左思·魏都赋》"}], "words": [{"w": "唱和", "t": "唱歌时此唱彼和。"}]}, {"meaning": "倡导;发起", "cites": [{"t": "为天下唱,宜多应者。", "b": "《史记·陈涉世家》"}, {"t": "予三十年前所主唱之三民主义、五权宪法,为诸先烈所不惜牺牲生命以争之者。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "唱义", "t": "倡导起义"}, {"w": "唱谋", "t": "率先策划"}, {"w": "唱始", "t": "倡始;首倡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2285wx','患','1','huàn','心','11','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从心,毌guàn)声。“串”即“毌”(贯)字。本义:担忧,忧虑。"}, {"meaning": "同本义。", "cites": [{"t": "患,忧也。", "b": "《说文》"}, {"t": "不患人之不已知,患其不能也。", "b": "《论语·宪问》"}, {"t": "书文止于一者谓之忠,持二中者谓之患,患人之忠,不一者也。", "b": "《春秋·繁露》"}, {"t": "患货之不足。", "b": "《国语·晋语》"}, {"t": "患秦兵之来。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "患志之不立。", "b": "《世说新语·自新》"}, {"t": "何患不能。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "患累", "t": "忧患"}, {"w": "患御", "t": "害怕服兵役"}, {"w": "患忧", "t": "忧患"}, {"w": "患失", "t": "生怕失去。"}]}, {"meaning": "憎恶;讨厌;厌烦。", "cites": [{"t": "患,恶也。", "b": "《广雅·释诂三》"}, {"t": "戊不好学患申公。", "b": "《汉书·申公传》"}], "words": [{"w": "患苦", "t": "厌恶"}, {"w": "患毒", "t": "痛恨"}, {"w": "患恶", "t": "厌恶"}, {"w": "患忌", "t": "嫌忌。"}]}, {"meaning": "苦于。", "cites": [{"t": "患,苦也。", "b": "《广雅》"}, {"t": "近日南方赋重,北方患徭多,民困官贫,急宜省事。", "b": "《清史稿》"}]}, {"meaning": "祸患,祸害。", "cites": [{"t": "惟事事,乃其有备,有备无患。", "b": "《书·说命中》"}, {"t": "论伦无患。", "b": "《礼记·乐记》"}, {"t": "此阴阳不适之患也。", "b": "《吕氏春秋·重己》"}, {"t": "恶为君之患也。", "b": "《吕氏春秋·贵生》"}, {"t": "无敌国外患。", "b": "《孟子·告子下》"}, {"t": "为乡里所患。", "b": "《世说新语·自新》"}, {"t": "为操后患。", "b": "《资治通鉴》"}, {"t": "用兵之患。", "b": ""}]}, {"meaning": "疾病;毛病。", "cites": [{"t": "人之患在好为人师。", "b": "唐·柳宗元《答韦中立论师道书》"}], "words": [{"w": "患子", "t": "病人"}, {"w": "患处;防患于未然;后患无穷;有备无患;消除后患", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2286wx','啰','1','luō luó luo','口','11','','[{"pinyin": "luō", "defs": [{"meaning": "a.说话絮絮叨叨；b.办事不痛快，使人感觉麻烦。"}]}, {"pinyin": "luó", "defs": [{"meaning": "啰唣"}]}, {"pinyin": "luo", "defs": [{"meaning": "放在句末,表示一种情况或感情。"}, {"meaning": "用在句末表示情况的变化。"}, {"meaning": "表示赞叹。"}, {"meaning": "表示祈使。"}, {"meaning": "用在句末,表示肯定。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2287wx','唾','1','tuò','口','11','','[{"pinyin": "tuò", "defs": [{"meaning": "(形声。从口,垂声。本义:口液,唾沫) 同本义。", "cites": [{"t": "唾,口液也。", "b": "《说文》"}, {"t": "脾为涎,肾为唾。", "b": "《素问》"}, {"t": "汝身已见唾成珠,汝伯何由发如漆!", "b": "唐·杜甫《醉歌行》"}], "words": [{"w": "唾腺", "t": "唾液腺"}, {"w": "唾沫星", "t": "口液的细小点子"}, {"w": "唾盂", "t": "痰盂"}, {"w": "唾壶", "t": "一种大肚痰盂。"}]}, {"meaning": "吐唾沫。", "cites": [{"t": "必唾其面。", "b": "《战国策·赵策》"}, {"t": "不顾而唾。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "唾面", "t": "往人的脸上吐唾沫"}, {"w": "唾背", "t": "朝人背影吐唾沫"}, {"w": "唾脡", "t": "吐唾于肉酱上。谓设谋独占"}, {"w": "唾涕", "t": "吐唾沫"}, {"w": "唾掌;唾手;唾玉", "t": "口吐珠玉。形容工于诗文。"}]}, {"meaning": "拖长。表示鄙弃不乐的样子。", "cites": [{"t": "道士唾着脸,不答应。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2288wx','唯','1','wéi','口','11','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从口,隹(zhuī)声。本义:急声回答声) 同本义。", "cites": [{"t": "唯者,应之速而无疑也。", "b": "《助字辨略》朱注"}, {"t": "子曰:“参乎!吾道一以贯之。”曾子曰:“唯。”", "b": "《论语·里仁》"}, {"t": "秦王跽而请曰:“先生何以幸教寡人?”范睢曰:“唯,唯。”", "b": "《史记·范睢蔡泽列传》"}], "words": [{"w": "唯阿", "t": "唯、阿同为应对 语词。比喻差别不大"}, {"w": "唯俞", "t": "应答辞"}, {"w": "唯唯", "t": "恭逊的应辞"}, {"w": "唯诺", "t": "应答;连 声应诺而不表异议。"}]}, {"meaning": "只有,只是。", "cites": [{"t": "唯圣人为能和。", "b": ""}, {"t": "唯北狄野心。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "唯余其一。", "b": "吴均《与朱元思书》"}, {"t": "唯巨石岿然。", "b": "《吕氏春秋·慎行论》"}], "words": [{"w": "唯心(佛教语,谓一切诸法(指万事万物),唯有内心无心外之法也称“唯识”", "t": ""}, {"w": "唯谨", "t": "唯有谨慎。"}]}, {"meaning": "以,因为。", "cites": [{"t": "唯无德也。", "b": "《国语·晋语》"}, {"t": "冀之既病,则亦唯君故。", "b": "《左传》"}]}, {"meaning": "表示希望、祈使。", "cites": [{"t": "唯大王与群臣熟计议之。", "b": "《史记》"}]}, {"meaning": "表示听任、任随 。常和“所”搭配。", "cites": [{"t": "唯所纳之,无不如志。", "b": "《左传》"}]}, {"meaning": "虽然,纵使 ——表示让步关系。", "cites": [{"t": "[公孙]弘、[张]汤深心疾黯,唯天子亦不说也。", "b": "《史记》"}]}, {"meaning": "表示肯定。", "cites": [{"t": "如地如天,何私何亲;如月如日,唯君之节。", "b": "《管子》"}]}, {"meaning": "用于句首,无实义。", "cites": [{"t": "唯求则非邦。", "b": "《论语·先进》"}, {"t": "唯天子,受命于天。", "b": "《礼记·表记》"}, {"t": "今乃立六国后,唯无复立者。", "b": "《汉书》"}, {"t": "唯进修是急。", "b": "清·刘开《问说》"}, {"t": "唯师心自用。", "b": ""}, {"t": "唯道之所成。", "b": ""}]}]}]','jingmo-wenyan');
