INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2291wx','啸','1','xiào','口','11','','[{"pinyin": "xiào", "defs": [{"meaning": "(形声。从口,肃声。本义:撮口作声,打口哨)。"}, {"meaning": "同本义。", "cites": [{"t": "啸,吹声也。", "b": "《说文》"}, {"t": "其嘨也歌。", "b": "《诗·召南·江有汜》"}, {"t": "不嘨不指。", "b": "《礼记·内则》"}, {"t": "激于舌端而清谓之啸。", "b": "《封氏闻见记》"}, {"t": "登东皋以舒啸。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "俯仰啸歌。", "b": "明·归有光《项脊轩志》"}, {"t": "若啸呼状。", "b": "明·魏学洢《核舟记》"}, {"t": "倚修木而啸。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "啸傲林泉", "t": "在幽静的山林泉水环抱中隐居"}, {"w": "啸吟", "t": "长啸哀叹"}, {"w": "啸指", "t": "以指夹唇吹之作声。"}]}, {"meaning": "呼召,号召。", "cites": [{"t": "嘨者,谓若有所召命,若齐庄抚楹而歌耳。", "b": "《匡缪正俗》"}, {"t": "招具该备,永啸呼些。", "b": "《楚辞》"}], "words": [{"w": "啸引;啸召", "t": "呼唤;召唤"}, {"w": "啸合", "t": "召唤聚集"}, {"w": "啸侣", "t": "呼叫同类;召唤同伴"}, {"w": "啸侣命俦", "t": "召唤同伴"}, {"w": "啸命", "t": "高声命令。"}]}, {"meaning": "鸟兽等的长声鸣叫。", "cites": [{"t": "虎啸猿啼。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "乳虎啸谷。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "鸟啸;啸萃", "t": "鸣叫而聚集"}, {"w": "啸吼", "t": "长声吼叫"}, {"w": "啸风", "t": "呼风"}, {"w": "风嘶雨啸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2292wx','崖','1','yá','山','11','','[{"pinyin": "yá", "defs": [{"meaning": "(形声。从山,厓(yá)声。本义:岸;水边)。"}, {"meaning": "同本义。", "cites": [{"t": "崖,高边也。", "b": "《说文》"}, {"t": "崖,岸。高边也。…此云高边,崖则水之边而峭高者也。", "b": "《说文句读》"}, {"t": "渊生珠而崖不枯。", "b": "《荀子·劝学》"}, {"t": "望厓洒而高岸。", "b": "《尔雅·释丘》。按:“厓之峻而高者,岸也,即岸也。”"}, {"t": "伯有廷劳于黄崖。", "b": "《左传·襄公二十八年》"}, {"t": "泾流之大,两涘渚崖之间,不辨牛马。", "b": "《庄子·秋水》"}, {"t": "君其涉于江而浮于海,望之而不见其崖。", "b": "《庄子·山水》"}, {"t": "穹崖巨谷。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "蹑履登崖。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "石崖侧削。", "b": "《徐霞客游记·游黄山记》"}, {"t": "四眺重崖,皆悬绝无径,而西崖尤为峻峭。", "b": "《徐霞客游记》"}], "words": [{"w": "崖谷", "t": "悬崖深谷"}, {"w": "崖口", "t": "山崖间的豁口"}, {"w": "崖垠", "t": "山崖的边际"}, {"w": "崖畔", "t": "山崖边"}, {"w": "崖岭", "t": "高崖峻岭"}, {"w": "崖穴", "t": "山洞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2293wx','崎','1','qí','山','11','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从山,奇声。本义:崎岖,地面高低不平的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "崎岖,倾侧也。", "b": "《广雅》"}], "words": [{"w": "崎崟", "t": "山峰高低不平的地方"}, {"w": "崎岭", "t": "形容山路险阻不平。"}]}, {"meaning": "险峻。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2294wx','崭','1','zhǎn','山','11','','[{"pinyin": "zhǎn", "defs": [{"meaning": "(形声。从山,斩声。双音词“崭岩”。本义:山高而险峻的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "崭岩嵾嵯。", "b": "《史记·司马相如传》"}, {"t": "谿谷崭岩兮水曾波。", "b": "《楚辞·招隐士》"}, {"t": "仰视所登之处,崭然在云汉。", "b": "《徐霞客游记》"}], "words": [{"w": "崭岩", "t": "险峻"}, {"w": "崭崒", "t": "陡峭高峻"}, {"w": "崭绝", "t": "险峻陡峭的样子;事物超群不寻常"}, {"w": "崭阢", "t": "高峻"}, {"w": "崭崖", "t": "陡峻的山崖"}, {"w": "崭露头角", "t": "比喻显示出突出的才能和本领"}, {"w": "崭崭", "t": "高峻;突出。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2295wx','逻','1','luó','辶','11','','[{"pinyin": "luó", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,罗声。本义:巡察,巡逻)。"}, {"meaning": "同本义。", "cites": [{"t": "逻者数十骑。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "逻伺", "t": "巡罗侦察"}, {"w": "逻弋", "t": "巡逻"}, {"w": "逻守", "t": "巡逻守卫"}, {"w": "逻役", "t": "巡逻的差役"}, {"w": "逻捕", "t": "巡察搜捕。"}]}, {"meaning": "遮拦。", "cites": [{"t": "蛛蝥结网工遮逻。", "b": "黄庭坚《演雅》"}], "words": [{"w": "逻打", "t": "拦截殴打"}, {"w": "逻送", "t": "捕捉解送"}, {"w": "逻惹", "t": "招惹"}, {"w": "逻楂儿", "t": "找岔子。"}]}, {"meaning": "用同“捋”。", "cites": [{"t": "又只见那洞外跳出几个小妖,在外边吆吆喝喝,伸拳逻袖,弄棒拈枪,依旧喜喜欢欢耍了。", "b": "《西游记》"}], "words": [{"w": "逻袖", "t": "捋起袖子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2296wx','崔','1','cuī','山','11','','[{"pinyin": "cuī", "defs": [{"meaning": "(形声。从山,隹(zhuī)声。本义:高大)。"}, {"meaning": "同本义。", "cites": [{"t": "崔,大高也。", "b": "《说文》"}, {"t": "南山崔崔。", "b": "《诗·齐风·南山》"}, {"t": "大山崔,百卉殖。", "b": "《乐府诗集》"}], "words": [{"w": "崔巍", "t": "高峻雄伟"}, {"w": "崔崔", "t": "高大的样子。"}]}, {"meaning": "春秋时齐国邑名,在今山东省章丘县西北。", "cites": [{"t": "成请老于崔,崔子许之。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2297wx','帷','1','wéi','巾','11','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从巾,隹(zhuī)声。从巾,与丝织品有关。“帷”是帷幕。本义:围在四周的布幕) 同本义。", "cites": [{"t": "帷,在旁曰帷。", "b": "《说文》"}, {"t": "车帷裳。", "b": "《诗·卫风·氓》"}, {"t": "蒲蒻蔺席帐帷幢。", "b": "《急就篇》"}, {"t": "在旁曰帷,在上曰幕。", "b": "《说文通训定声》"}, {"t": "即将女出帷中。", "b": "《史记·滑稽列传》"}, {"t": "披帷西向立。", "b": "《史记·项羽本纪》"}, {"t": "揽辔褰帷。", "b": "清·周容《芋老人传》"}], "words": [{"w": "帷薄", "t": "帐幔叫帷,竹簾叫薄。可供分隔内外之用"}, {"w": "帷盖", "t": "车上的帷幕和顶盖"}, {"w": "帷堂", "t": "丧礼所用的帷幕。设在堂上,以分隔内外"}, {"w": "帷帏", "t": "犹帷幄。借指君主"}, {"w": "帷幌", "t": "室内的帷幔。"}]}, {"meaning": "用幕布遮挡。", "cites": [{"t": "周武王乃使人帷而守之。", "b": "《新书·连语》"}], "words": [{"w": "帷房", "t": "张帷的房屋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2298wx','崩','1','bēng','山','11','','[{"pinyin": "bēng", "defs": [{"meaning": "(形声。从山,朋声。本义:山倒塌)。"}, {"meaning": "同本义。", "cites": [{"t": "梁山崩。", "b": "《左传·成公五年》"}], "words": [{"w": "山崩地裂", "t": ""}]}, {"meaning": "崩裂;倒塌。", "cites": [{"t": "中间力拉崩倒之声,火爆声,呼呼风声,百千齐作。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "崩拆", "t": "倒塌断裂"}, {"w": "崩陷", "t": "倒塌陷落"}, {"w": "崩陨", "t": "塌陷"}, {"w": "崩损", "t": "崩塌损坏"}, {"w": "崩坠", "t": "倒塌坠落。"}]}, {"meaning": "古代把天子的死看得很重,常用山塌下来比喻,由此从周代开始帝王死称“崩”。", "cites": [{"t": "故临崩寄臣以大事也。", "b": "诸葛亮《出师表》"}, {"t": "越二月,帝崩。", "b": "《明史·海瑞传》"}], "words": [{"w": "崩驾", "t": "帝王之死"}, {"w": "崩殂", "t": "崩背,崩逝。又指帝王之死。"}]}, {"meaning": "崩溃;垮台;败坏。", "cites": [{"t": "不义不昵,厚将崩。", "b": "《左传·隐公元年》"}, {"t": "三年不为乐,乐必崩。", "b": "《论语·阳货》"}], "words": [{"w": "崩阙", "t": "败坏"}, {"w": "崩动", "t": "煽动败坏。"}]}, {"meaning": "破裂,迸裂。", "cites": [{"t": "天崩地塌壮士死。", "b": "吴士玉《玉带生歌奉和漫堂先生》"}], "words": [{"w": "谈崩了;崩裂", "t": "物体突然破裂"}, {"w": "崩云", "t": "破裂的云彩"}, {"w": "把气球吹崩了", "t": ""}]}, {"meaning": "血崩,指妇科“崩症”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2299wx','崇','1','chóng','山','11','','[{"pinyin": "chóng", "defs": [{"meaning": "(形声。从山,宗声。本义:山大而高)。"}, {"meaning": "同本义。", "cites": [{"t": "崇,嵬高也。", "b": "《说文》。按,字亦作嵩、作崧。"}, {"t": "融降于崇山。", "b": "《国语·周语》。注:“崇,崇高山也。夏居阳城,崇高所近。”"}], "words": [{"w": "崇亘", "t": "高峻绵延"}, {"w": "崇崖", "t": "高峻的山崖"}, {"w": "崇阿", "t": "高大的山丘"}, {"w": "崇山", "t": "高山"}, {"w": " 崇崇", "t": "高耸的样子。"}]}, {"meaning": "高;高大。", "cites": [{"t": "崇,高也。", "b": "《尔雅》"}, {"t": "与黄比崇。", "b": "张衡《西京赋》"}, {"t": "崇崇圜邶。", "b": "扬雄《甘泉赋》"}, {"t": "广与崇方。", "b": "《考工记·梓人》"}, {"t": "大侯之崇,见鹄于参。", "b": "《仪礼·大射仪》"}, {"t": "于是封之,崇四尺。", "b": "《礼记·檀弓》"}, {"t": "明道德之广崇。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "崇墉", "t": "高大的城墙"}, {"w": "崇榘", "t": "高峻的城墙。"}]}, {"meaning": "高贵。", "cites": [{"t": "天子曰崇城,言崇高也。", "b": "《白虎通》"}], "words": [{"w": "崇阀", "t": "高贵显赫之家"}, {"w": "崇阶", "t": "高位,高官"}, {"w": "崇卑", "t": "高低,高下。"}]}, {"meaning": "兴盛。", "cites": [{"t": "建明德而崇业。", "b": "张衡《东京赋》。注:“犹兴也。”"}], "words": [{"w": "崇业", "t": "兴业"}, {"w": "崇盛", "t": "隆盛,极其荣宠。"}]}, {"meaning": "尊崇,推崇。", "cites": [{"t": "崇事宗庙社稷。", "b": "《礼记·祭统》"}, {"t": "莽遂崇鬼神淫祀。", "b": "《汉书·郊祀志》"}], "words": [{"w": "崇正黜邪", "t": "推崇正气,摒弃邪恶"}, {"w": "崇实", "t": "注重实际"}, {"w": "崇德", "t": "崇尚道德。也指崇尚有德者"}, {"w": "崇儒", "t": "尊崇儒学。"}]}, {"meaning": "充满。", "cites": [{"t": "主人坐奠爵于西楹南介右,再拜崇酒。", "b": "《仪礼·乡饮酒礼》"}, {"t": "六成复缀以崇。", "b": "《礼记·乐记》"}, {"t": "泛崇蘭些。", "b": "《楚辞·招魂》"}], "words": [{"w": "崇奸", "t": "聚集许多恶人。"}]}, {"meaning": "终,尽", "cites": [{"t": "谁谓宋远,曾不崇朝。", "b": "《诗·卫风·河广》"}, {"t": "周流四海,曾不崇日。", "b": "《荀子· 赋》"}, {"t": "存亡之效,不崇朝而决。", "b": "《三国志·凉茂传》"}], "words": [{"w": "崇替", "t": "灭亡。即终替"}, {"w": "崇朝", "t": "一个早上。比喻时间的短暂"}, {"w": "崇日", "t": "终日,一日。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2300wx','崛','1','jué','山','11','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从山,屈声。本义:高起,突起)。"}, {"meaning": "同本义。", "cites": [{"t": "崛,山短高也。", "b": "《说文》"}, {"t": "崛,特立也。", "b": "《埤苍》"}, {"t": "神明崛其特起。", "b": "张衡《西京赋》"}, {"t": "洪台崛其独出兮。", "b": "《文选·扬雄·甘泉赋》"}], "words": [{"w": "崛岉", "t": "高耸的样子"}, {"w": "崛起", "t": "特起,高出"}, {"w": "崛兴", "t": "崛起,兴起"}, {"w": "崛出", "t": "特出"}, {"w": "崛郁", "t": "特出的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2301wx','婴','1','yīng','女','11','','[{"pinyin": "yīng", "defs": [{"meaning": "(会意。从女,賏(yīng)。“賏”是颈项链。本义:妇女颈饰,似现代的项链)。"}, {"meaning": "同本义。", "cites": [{"t": "婴,颈饰也。", "b": "《说文》"}, {"t": "喉下称婴。", "b": "《释名》"}]}, {"meaning": "初生的女孩。", "cites": [{"t": "见人方引婴儿欲投之江中。", "b": "《吕氏春秋·察今》"}]}, {"meaning": "亦泛指初生儿。", "cites": [{"t": "人始生曰婴。", "b": "《释名》"}, {"t": "我独泊兮,其未兆,如婴儿之未孩。", "b": "《老子》"}, {"t": "自哂同婴孩", "b": "杜甫《山寺》"}], "words": [{"w": "男婴;女婴;妇婴;婴子", "t": "婴儿。又叫“婴人”"}, {"w": "婴儿子", "t": "幼儿"}, {"w": "婴耄", "t": "幼儿和老人"}, {"w": "婴弱", "t": "幼小"}, {"w": "婴提", "t": "幼儿"}, {"w": "婴稚", "t": "幼年"}, {"w": "婴孺", "t": "幼儿"}, {"w": "婴年", "t": "少年,儿时。"}]}, {"meaning": "系到颈上;戴。", "cites": [{"t": "辟之,是犹使处女婴宝珠、佩宝玉,负戴黄金,而遇中山之盗也。", "b": "《荀子·富国》"}], "words": [{"w": "婴衿", "t": "犹衿缨。结缨于襟。"}]}, {"meaning": "缠绕,反复盘绕其上。", "cites": [{"t": "白婴茀。", "b": "《楚辞·天问》"}, {"t": "隗乎共相婴。", "b": "扬雄《甘泉赋》。注:“婴,绕也。”"}, {"t": "是与天和相婴薄。", "b": "《淮南子·要略》。注:“婴,绕抱也。”"}, {"t": "释斤斧之用,而欲婴以芒刃。", "b": "《汉书·贾谊传》"}, {"t": "借问之何之?世网婴我身。", "b": "《文选·赴洛道中作》"}], "words": [{"w": "婴怀", "t": "萦怀;牵挂在心"}, {"w": "婴意", "t": "挂心,在意"}, {"w": "婴纶", "t": "羁缚"}, {"w": "婴物", "t": "萦怀世务;纠缠于外界事物。"}]}, {"meaning": "触犯。", "cites": [{"t": "教诲之,调一之,则兵劲城固,敌国不敢婴也。", "b": "《荀子·强国》"}, {"t": "民和齐则兵劲城固,敌国不敢婴也。", "b": "《荀子·乐论》"}, {"t": "说者能无婴人主之逆鳞,则几矣。", "b": "《韩非子·说难》"}], "words": [{"w": "婴触", "t": "触犯"}, {"w": "婴罪", "t": "获罪。"}]}, {"meaning": "绕,围绕。", "cites": [{"t": "必将婴城固守。", "b": "《汉书·蒯通传》"}, {"t": "其次剔毛发婴金铁受辱。", "b": "《文选·司马迁·报任少卿书》"}], "words": [{"w": "婴城坚守", "t": "绕城固守"}, {"w": "婴守", "t": "环城固守"}, {"w": "婴城", "t": "环城而守"}, {"w": "婴薄", "t": "环绕接近。"}]}, {"meaning": "遭受;遇。", "cites": [{"t": "今我元元,婴此饥馑。", "b": "晋·袁宏《后汉纪》"}], "words": [{"w": "婴症", "t": "患病;疾病缠身"}, {"w": "婴罹", "t": "遭受,触陷罗网。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2302wx','圈','1','juān juàn quān','囗','11','','[{"pinyin": "juān", "defs": [{"meaning": "把禽畜关在栅栏里。", "cites": [{"t": "鼻赤象,圈巨狿。", "b": "《文选·张衡·西京赋》"}], "words": [{"w": "把羊群圈起来", "t": ""}]}, {"meaning": "闷在;关闭。", "cites": [{"t": "我只恨天天圈在家里,一点儿做不得主,行动就有人知道。", "b": "《红楼梦》"}]}]}, {"pinyin": "juàn", "defs": [{"meaning": "(形声。从囗(wéi,表示被围),卷声。本义:家畜的小围栏)。"}, {"meaning": "同本义。", "cites": [{"t": "圈,养畜之闲也。", "b": "《说文》"}, {"t": "圈属。", "b": "《管子·立政》。注:“羊豕之类也。”"}, {"t": "登虎圈。", "b": "《汉书·张释之传》。注:“养兽之所。”"}, {"t": "从行登虎圈。", "b": "《史记·张释之列传》"}], "words": [{"w": "圈牢", "t": "关养家畜的地方"}, {"w": "圈槛", "t": "圈禁野兽的栅栏"}, {"w": "羊圈;猪圈;狗圈", "t": ""}]}, {"meaning": "国,城邑。", "cites": [{"t": "大圈闳闳,小圈交之。", "b": "汉·扬雄《太玄·交》"}]}]}, {"pinyin": "quān", "defs": [{"meaning": "曲木做成的饮器。", "cites": [{"t": "毋没而杯圈不能饮焉,口泽之气存焉尔!", "b": "《礼记》"}]}, {"meaning": "注:“屈木所为,谓厄匜之属。”。", "cites": [{"t": "似圈似臼。", "b": "《庄子·齐物论》"}]}, {"meaning": "圈子,环行物。", "cites": [{"t": "天下为之圈。", "b": "《淮南子·原道》"}], "words": [{"w": " 眼圈;画个圈;银项圈;包围圈", "t": ""}]}, {"meaning": "区域;范围。", "cites": [{"t": "是故有生于无,实出于虚,天下为之圈,则名实同居。", "b": "《淮南子》"}]}, {"meaning": "用圈作记号。", "cites": [{"t": "圈去到字。", "b": "宋·洪迈《容斋续笔》"}, {"t": "复圈去而改为入。", "b": ""}], "words": [{"w": "圈声", "t": "用红笔在句子停顿处加圈"}, {"w": "圈占", "t": "划定界限并占领之。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2303wx','铐','1','kào','钅','11','','[{"pinyin": "kào", "defs": [{"meaning": "(形声。从金,考声。本义:手铐) 同本义", "words": [{"w": "镣铐", "t": "脚镣和手铐"}, {"w": "铐子", "t": "手铐"}]}, {"meaning": "戴上手铐"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2304wx','铛','1','chēng dāng','钅','11','','[{"pinyin": "chēng", "defs": [{"meaning": "烙饼或做菜用的平底浅锅。", "cites": [{"t": "鼎铛玉石,金块珠砾,弃掷逦迤。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "铛头", "t": "厨师。"}]}]}, {"pinyin": "dāng", "defs": [{"meaning": "锒铛。锁系囚人的铁索。", "cites": [{"t": "铛,锒铛也。从金,当声。", "b": "《说文》。按,锁曰锒铛。"}]}, {"meaning": "女子的耳饰。", "cites": [{"t": "足履革屣,耳悬金铛。", "b": "《北史》"}]}, {"meaning": "钟鼓的声音。", "cites": [{"t": "铛铛晓漏。", "b": "徐陵《与杨仆射书》"}], "words": [{"w": "铛铛", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2305wx','铝','1','lǚ','钅','11','','[{"pinyin": "lǚ", "defs": [{"meaning": "带蓝色的银白色三价金属元素,延展性好,有韧性并能发出——元素符号Al。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2306wx','铜','1','tóng','钅','11','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。从金,同声。本义:金属名,古称赤金)。"}, {"meaning": "同本义。", "cites": [{"t": "铜,赤金也。", "b": "《说文》"}, {"t": "章山之铜,所谓丹阳铜也。今世有白铜,盖点化为之,非其本质。", "b": "《汉书·货殖列传》"}, {"t": "以精铜铸成。", "b": "《后汉书·张衡传》"}, {"t": "首衔同凡。", "b": ""}]}, {"meaning": "铜铸的货币。也用以泛指金钱。"}, {"meaning": "铜制乐器。", "cites": [{"t": "太子生而泣,太师吹铜,曰:“声中某律”。", "b": "汉·贾谊《胎教》"}]}, {"meaning": "铜印。", "cites": [{"t": "不由其德,五两之纶,半通之铜,亦泰矣。", "b": "《法言》"}]}, {"meaning": "铜镜。", "cites": [{"t": "对客心如怯,窥铜只自怜。", "b": "明·袁宏道《病起偶题》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2307wx','铭','1','míng','钅','11','','[{"pinyin": "míng", "defs": [{"meaning": "(形声。从金,名声。从金,与钟鼎器物有关。本义:在器物上雕刻文字)。"}, {"meaning": "同本义。", "cites": [{"t": "铭者,自名也。自名以称扬其先祖之美而明著之后世者也。", "b": "《礼记·祭统》"}, {"t": "铭,明旌也。", "b": "《礼记·檀弓》"}, {"t": "铭书于王之大常。", "b": "《周礼·司勋》。注:“铭之言名也。”"}, {"t": "名,题勒也。", "b": "《字林》"}, {"t": "其铭有之。", "b": "《国语·晋语》。注:“刻器曰铭。”"}, {"t": "铭功会稽岭。", "b": "李白《古风五十九首·三》"}], "words": [{"w": "铭功", "t": "在金石上刻文字来记下功勋"}, {"w": "铭戒", "t": "在金石等物品上,刻下言辞,以为劝诫"}, {"w": "铭勒", "t": "镌刻金石,以记述功德。"}]}, {"meaning": "牢记不忘。", "cites": [{"t": "铭心立报,永矣无贰。", "b": "《三国志·周鲂传》"}], "words": [{"w": "铭佩;铭意", "t": "刻记于胸中的心志"}, {"w": "铭戢", "t": "表示感谢别人的恩惠而深藏于心里"}, {"w": "铭篆", "t": "比喻感激很深,没齿难忘"}, {"w": "铭戴", "t": "感戴人的恩惠,铭刻于心,永远不忘。"}]}, {"meaning": "为着确立持久的或公开的记载而刻写或题写的文辞(古多刻于钟鼎,秦汉以后有的刻在石碑上)。", "cites": [{"t": "钟鼎之铭。", "b": "《韩非子·外储说左上》"}], "words": [{"w": "墓志铭;商汤《盘铭》;正考父《鼎铭》", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2308wx','铲','1','chǎn','钅','11','','[{"pinyin": "chǎn", "defs": [{"meaning": "(形声。从金,产声。本义:用以铲削的铁器)。"}, {"meaning": "铲子。", "words": [{"w": "铁铲;煤铲", "t": ""}]}, {"meaning": "古兵器。形似铲。", "cites": [{"t": "铲,长小尺一丈,尾有刃,以便后刺。", "b": "明·茅元仪《武备志》"}]}, {"meaning": "削平;铲除。", "cites": [{"t": "铲,削平也。", "b": "《苍颉篇》"}, {"t": "即更取器用,铲刈秽草。", "b": "柳宗元《钴鋂潭西小丘记》"}], "words": [{"w": "铲煤;铲土;把地铲平", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2309wx','银','1','yín','钅','11','','[{"pinyin": "yín", "defs": [{"meaning": "(形声。从金,艮(gèn)声。本义:一种白色金属,通称银子)。"}, {"meaning": "同本义 。一种白色的金属元素,能发出响亮声音,有延展 性和良好的韧性,可达到高度抛光状态,在化合物中主要以一价形式存在,是所有物质中具有最高导热性和导电性的物质,在自然界中以自生式共生状态(如在脆银矿、辉银矿、淡红银矿、深红银矿和角银矿中)存在——元素符号Ag。", "cites": [{"t": "钿头银篦。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "金银华美之服。", "b": "宋·司马光《训俭示康》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2310wx','矫','1','jiǎo jiáo','矢','11','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从矢,乔声。本义:把箭杆揉直的一种器具。引申为“正曲使直”)。"}, {"meaning": "把弯曲的物体弄直。", "cites": [{"t": "矫,直也。", "b": "《广雅》"}, {"t": "坎为矫輮。", "b": "《易·说卦传》"}, {"t": "古枸木必将待櫽括烝矫然后直。", "b": "《荀子·性恶》"}], "words": [{"w": "矫矢", "t": "矫直箭矢"}, {"w": "矫揉", "t": "使物或曲或直。矫是改直,揉是变曲"}, {"w": "矫直", "t": "矫正弯曲使之直"}, {"w": "矫枉", "t": "矫正弯曲。比喻纠正偏邪。"}]}, {"meaning": "匡正;纠正。", "cites": [{"t": "以矫饰人之情性而正之。", "b": "《荀子·性恶》"}, {"t": "其刑矫诬。", "b": "《国语·周语》"}, {"t": "以绳墨自矫。", "b": "《庄子·天下》"}, {"t": "以身矫之。", "b": "清·张廷玉《明史》"}], "words": [{"w": "矫世", "t": "纠正世俗之失"}, {"w": "矫世变俗", "t": "谓纠正和改变不良的世风民俗"}, {"w": "矫激", "t": "矫正;偏激"}, {"w": "矫舌", "t": "使舌头发音正确"}, {"w": "矫奸", "t": "抑制奸邪"}, {"w": "矫异", "t": "抑制差别"}, {"w": "矫情镇物", "t": "故意抑制情感,表示镇定,使人不测"}, {"w": "矫世励俗", "t": "改正世风,激励世俗。"}]}, {"meaning": "假托;诈称。", "cites": [{"t": "矫王命以杀之。", "b": "《谷梁传·宣公十五年》"}, {"t": "[弦高]遇之殽,矫以郑伯之命而犒师焉。", "b": "《公羊传·僖公三十三年》"}, {"t": "乃矫郑伯之命以劳之。", "b": "《吕氏春秋·悔过》"}, {"t": "非其事而居之,矫也。", "b": "《大戴礼记·曾子立事》"}, {"t": "彼用无为有,故谓矫。", "b": "《墨子·非命》"}, {"t": "矫君命。", "b": "《战国策·齐策四》"}, {"t": "矫魏王令。", "b": "《史记·魏公子列传》"}, {"t": "矫杀晋鄙。", "b": ""}], "words": [{"w": "矫夺", "t": "假托君命而强行夺取"}, {"w": "矫称", "t": "假托名义而加宣扬"}, {"w": "矫命", "t": "假托命令"}, {"w": "矫旨", "t": "假托帝王诏命"}, {"w": "矫制", "t": "指假托君命行事。"}]}, {"meaning": "高举。", "cites": [{"t": "矫茲媚以私处兮。", "b": "《楚辞·惜诵》。注:“举也。”"}, {"t": "矫首而遐观。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "仰矫首以遥望兮。", "b": "《后汉书·张衡传》"}, {"t": "矫顾怒步。", "b": "唐·李朝威《柳毅传》"}, {"t": "矫首昂视。", "b": "明·魏学洢《核舟记》"}, {"t": "矫首昂视。(抬头仰望。矫,抬举。)。又如:矫手(举手);矫翼(振翅);矫首(昂首;抬头)", "b": ""}]}, {"meaning": "拂逆,违背。", "cites": [{"t": "以矫俗干名。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "矫情干誉", "t": "故违常情,以求美誉"}, {"w": "矫俗", "t": "故意违反世俗人情,以显示自己的清高不凡。"}]}, {"meaning": "飞。", "cites": [{"t": "矫,飞也。《《广雅·释估三》", "b": ""}, {"t": "晒夏蟲之疑冰,整轻翮而思矫。", "b": "《文选·孙卓·游天台山赋》"}, {"t": "鹤矫閬风,麟腾玉京。", "b": "《当涂李宰君画赞》"}, {"t": "放弓一长啸,目送孤鸿矫。", "b": "宋·苏轼《人日猎城南》"}]}, {"meaning": "勇武的样子。", "cites": [{"t": "矫矫虎臣。", "b": "《诗·鲁颂·泮水》"}], "words": [{"w": "矫任", "t": "恣意任性。"}]}]}, {"pinyin": "jiáo", "defs": [{"meaning": "[方言] 指强词夺理，无理取闹"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2311wx','甜','1','tián','甘','11','','[{"pinyin": "tián", "defs": [{"meaning": "(会意。从甘,从舌。舌头能品尝甜味。本义:味甘)。"}, {"meaning": "像糖或蜜的味道。", "cites": [{"t": "甛,美也。", "b": "《说文》"}, {"t": "甜,甘也。", "b": "《广雅》"}, {"t": "草木不复抽,百味失苦甜。", "b": "韩愈《苦寒》"}], "words": [{"w": "甜物", "t": "甜的食品"}, {"w": "甜酒", "t": "甘甜的米酒"}, {"w": "甜雪", "t": "甘甜的雪水"}, {"w": "甜酸苦辣", "t": "指种种不同的味道"}, {"w": "甜香", "t": ""}]}, {"meaning": "比喻幸福;快乐 。", "words": [{"w": "甜沃沃", "t": "形容幸福愉快。"}]}, {"meaning": "美好 。", "words": [{"w": "甜差", "t": "美差"}, {"w": "甜冤对", "t": "俏冤家"}, {"w": "甜淡", "t": "柔和淡雅"}, {"w": "甜俏", "t": "柔和娇媚"}, {"w": "甜俗", "t": "软熟媚俗"}, {"w": "甜软", "t": "甜蜜温柔。"}]}, {"meaning": "形容睡得酣畅 。", "words": [{"w": "甜睡;甜乡", "t": "梦乡。"}]}, {"meaning": "指美言 。", "words": [{"w": "甜口儿", "t": "善于说奉承话的嘴"}, {"w": "甜句儿", "t": "甜言"}, {"w": "甜言", "t": "美言;好话"}, {"w": "甜言软语,甜言媚语", "t": "温柔体贴的话"}, {"w": "甜话儿", "t": "甜言蜜语"}, {"w": "甜嘴蜜舌", "t": "甜言蜜语。"}]}, {"meaning": "酣睡,熟睡。", "cites": [{"t": "一枕余甜昏又晓,凭谁拨转通天穷。", "b": "明·汤显祖《邯郸记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2312wx','秸','1','jiē','禾','11','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从禾,皆声。农作物的茎杆。如:麦秸) 谷物脱粒后的茎杆 。如:秸子;秸杆;秸席(禾秆做的席子。古代祀神时所用)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2313wx','梨','1','lí','木','11','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从木,利声。梨为棃的俗字。本义:木名。果实也称梨)。"}, {"meaning": "同本义。", "cites": [{"t": "棃,梨果也。", "b": "《说文》"}, {"t": "楂棃姜桂。", "b": "《礼记·内则》"}, {"t": "千树万树梨花开。", "b": "唐·岑参《白雪歌送武判官归京》"}]}, {"meaning": "落叶乔木,叶子卵形。花多白色,果子多汁,可食。如:梨枣(古代印书的木刻板。因多用梨木、枣木刻成,故称);梨栗(梨树和栗树);梨云(梨雪,梨英,梨霜,梨蕊,梨花。梨树的花,一般为纯白色)。又指梨树的果实。如:梨果(梨子);梨头(小梨);梨条(用梨子所做的条状果脯);梨干(梨子加工制的果干)。"}, {"meaning": "黎民,人民。", "cites": [{"t": "棃烝殷,罔荒饥。", "b": "汉《竹邑侯相张寿碑》"}, {"t": "棃庶赖祉。", "b": "汉《桐柏淮源庙碑》"}], "words": [{"w": "梨元", "t": "亦作黎元。民众,梨,通“黎”"}, {"w": "梨氓", "t": "亦作黎氓。黎民,民众。梨,通“黎”。"}]}, {"meaning": "黑;年老 。指老人面色如冻梨。", "cites": [{"t": "梨,老也。东齐曰眉,燕代之北鄙曰梨。", "b": "《方言》"}, {"t": "班黑谓之棃黮。", "b": "《通俗文》"}, {"t": "九十曰鲐背,或曰冻梨皮,有斑点如冻梨色也。", "b": "《释名》"}]}, {"meaning": "割。", "cites": [{"t": "是故博带棃,大袂裂,文绣染。", "b": "《管子·五辅》"}, {"t": "分棃单于,磔裂属国。", "b": "《汉书·扬雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2314wx','犁','1','lí','牛','11','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从牛,利声。本义:牛耕)。"}, {"meaning": "同本义。", "cites": [{"t": "犂,耕也。", "b": "《说文》。字亦作犁。"}, {"t": "犁其庭。", "b": "《汉书·匈奴传》。注:“耕也。”"}, {"t": "犂牛之子。", "b": "《论语》。皇疏:“或音梨,谓耕犂也。”"}, {"t": "古墓犁为田,松柏摧为薪。", "b": "《古诗十九首》"}], "words": [{"w": "犁耕", "t": "用犁耕田;耕田"}, {"w": "犁花", "t": "犁翻的土块"}, {"w": "犁春", "t": "春耕。"}]}, {"meaning": "及,等到。", "cites": [{"t": "犂二十五年,吾冢上柏大矣。", "b": "《史记·晋世家》"}]}, {"meaning": "耕地的农具。我国春秋时代,就已用牛拉犁耕田。", "cites": [{"t": "耕者忘其犁。", "b": "《乐府诗集·陌上桑》"}, {"t": "纵有健妇把锄犁。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "犁锄", "t": "犁和锄"}, {"w": "犁锄之厄", "t": "死亡的命运。"}]}, {"meaning": "黑(在黑的意义上,黧、黎、犁实同一词)。", "cites": [{"t": "形容枯槁,面目犁黑。", "b": "《战国策·齐策一》"}, {"t": "犁旦。", "b": "《史记·南越列传》。索隐:“犁,黑也。天未明尚黑时也。”"}], "words": [{"w": "犁眉驹", "t": "良马名。毛黄色,眉黑。犁,通“黧”"}, {"w": "犁黑", "t": "黧黑,暗黑色。犁,通“犂”"}, {"w": "犁老", "t": "指老人。老人面色黧黑,故称犁,通“黧”"}, {"w": "犁明", "t": "犁曙黎明。犂,通“黎”。"}]}, {"meaning": "众多之意。", "cites": [{"t": "今商王受,力行无度,播弃犂老。", "b": "《书·泰誓中》"}], "words": [{"w": "犁元,犁民", "t": "黎民百姓。犂,通“黎”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2315wx','秽','1','huì','禾','11','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从禾,岁声。本义:荒废;长满野草)。"}, {"meaning": "同本义。", "cites": [{"t": "秽,芜也。从草,岁声。字亦作秽。", "b": "《说文》"}, {"t": "涂薉则塞。", "b": "《荀子·王霸》"}, {"t": "国之薉孽也。", "b": "《荀子·大略》"}, {"t": "粤地涂泥多草薉。", "b": "《考工记·总目》注"}, {"t": "并稻潜秽。", "b": "《文选·班固·西都》"}, {"t": "民贫,则田瘠以秽。", "b": "《荀子·富国》"}], "words": [{"w": "秽草", "t": "杂草,恶草"}, {"w": "秽荒", "t": "荒芜;杂草丛生"}, {"w": "秽莽", "t": "杂草;恶草。"}]}, {"meaning": "弄脏,弄污。", "cites": [{"t": "面一旦不修饰,则尘垢秽之;心一朝不思善,则邪恶入之。", "b": "汉·蔡邕《女诫》"}]}, {"meaning": "杂乱。", "cites": [{"t": "即更取器用,铲刈秽草。", "b": "柳宗元《永州八记》"}], "words": [{"w": "秽累", "t": "文字杂乱累赘"}, {"w": "秽谈", "t": "秽杂的谈论"}, {"w": "秽杂", "t": "杂乱;污浊而杂乱;秽亵。"}]}, {"meaning": "肮脏;污浊。", "cites": [{"t": "秽,不净也。", "b": "《玉篇》"}, {"t": "于是百姓涤瑕荡秽而镜至清。", "b": "《文选·班固·东都赋》"}, {"t": "蝉蜕于浊秽。", "b": "《史记·屈原贾生列传》"}, {"t": "除残去秽。", "b": "《资治通鉴》"}], "words": [{"w": "秽垢", "t": "污浊"}, {"w": "秽物", "t": "肮脏的东西"}, {"w": "秽言", "t": "肮 脏下流的话"}, {"w": "秽慝", "t": "污浊,邪恶。"}]}, {"meaning": "罪过。", "cites": [{"t": "若其负秽临深,虚誓愆祈,则有海童邀路,马衔当蹊。", "b": "《文选·木华·海赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2316wx','移','1','yí','禾','11','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从禾,多声。本义:移秧)。"}, {"meaning": "同本义。泛指移植。", "cites": [{"t": "移,禾相倚移也。", "b": "《说文》。徐灏注:“戴氏侗曰:‘移,移秧也。凡种稻必先苗之而移之,迁移之义取焉,别作。灏按:禾苗茂密乃移种之。’”"}], "words": [{"w": "移花", "t": "移植花木"}, {"w": "移根", "t": "犹移植"}, {"w": "移种,移莳", "t": "犹移植。"}]}, {"meaning": "假借为“迻”。移动。", "cites": [{"t": "则民不移。", "b": "《国语·齐语》。注:“徙也。”"}, {"t": "弗能移也。", "b": "《国语·晋语》。注:’动也。”"}, {"t": "徐趋皆用是,疾趋则欲发,而手足毋移。", "b": "《礼记》"}, {"t": "移兵先击。", "b": "《史记·魏公子列传》"}, {"t": "撤兵移营。", "b": "《广东军务记》"}, {"t": "寻移刑部。", "b": "清·张廷玉《明史》"}, {"t": "移顺天府。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "移户", "t": "所迁移的民户"}, {"w": "移帐", "t": "迁徒篷帐"}, {"w": "移籍", "t": "移居"}, {"w": "移垦", "t": "迁徙垦荒"}, {"w": "移寝", "t": "迁徙卧处"}, {"w": "移寓", "t": "移居,迁居"}, {"w": "移步", "t": "挪步"}, {"w": "移云掩月", "t": "喻以假代真,巧加掩饰"}, {"w": "移船泊岸", "t": "自动迁就"}, {"w": "移窠", "t": "指婴儿满月时移入他人的房中"}, {"w": "移山", "t": "移动山岳。"}]}, {"meaning": "转移。", "cites": [{"t": "荐人或起家至二千石,权移主上。", "b": "《史记》"}], "words": [{"w": "移奖", "t": "把奖赏转移给他人"}, {"w": "移茶客人", "t": "旧时上海妓院的定例,初次逛院的客人要挑选一个合意的妓女。这种嫖客称“移茶客人”"}, {"w": "移商刻羽", "t": "移商拨羽。奏出优美动听的曲调"}, {"w": "移赃", "t": "转移赃物或赃款"}, {"w": "移营", "t": "转移营地。"}]}, {"meaning": "变动;改变。", "cites": [{"t": "时位之移人。", "b": "清·周容《芋老人传》"}, {"t": "世易时移。", "b": "《吕氏春秋·察今》"}, {"t": "守节情不移。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "不知几移。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "移天换斗", "t": "喻力大谋高,能使天地星辰改变位置"}, {"w": "移心", "t": "改变心意"}, {"w": "移志", "t": "改变意志;动心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2317wx','笨','1','bèn','竹','11','','[{"pinyin": "bèn", "defs": [{"meaning": "(形声。从竹,本声。本义:竹里。指竹的内表面) 竹子的内层。通称“竹黄”。", "cites": [{"t": "笨,竹里也。从竹,本声。", "b": "《说文》。徐锴系传:“笨,竹白也。”"}, {"t": "竹其表曰笢,其里曰笨,谓中之白质者也。其白如纸,可手揭者,谓之竹孚俞。", "b": "《广雅·释草》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2318wx','笼','1','lóng lǒng','龙','11','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从竹,龙声。本义:竹笼)。"}, {"meaning": "用竹片编成的盛物的器具。", "cites": [{"t": "笼,举土器也。", "b": "《说文》"}, {"t": "共丘笼。", "b": "《周礼·遂师》"}, {"t": "貂裘而负笼。", "b": "《淮南子·说山》"}, {"t": "荷笼负锸。", "b": "《汉书·王莽传》"}, {"t": "青丝为笼系。", "b": "《乐府诗集·陌上桑》"}]}, {"meaning": "又。", "cites": [{"t": "桂枝为笼钩。", "b": ""}], "words": [{"w": "笼臿", "t": "盛土的笼和铲挖泥土的锹"}, {"w": "笼篰", "t": "竹笼和小竹篓"}, {"w": "笼屉", "t": "蒸笼。"}]}, {"meaning": "饲养鸟、虫、家禽等的笼子。", "cites": [{"t": "闭以雕笼。", "b": "祢衡《鹦鹉赋》"}, {"t": "以天下为之笼,则雀无所逃。", "b": "《庄子·庚桑楚》"}, {"t": "若脱笼之鹄。", "b": "明·袁宏道《满井游记》"}, {"t": "中儿正织鸡笼。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "蟋蟀笼虚。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "掇置笼中。", "b": ""}, {"t": "笼归。(装在笼子里,带回家去。笼,名词用为动词,装在笼子里。)。又如:牢笼;木笼;笼驯(把鸟兽关在笼中使之驯服);笼狎(将动物畜养于笼中加以戏弄);笼阿(鸟笼中的一角);笼鸟槛猿(笼中鸟与槛中猿。比喻受拘禁而不得自由的人)", "b": ""}]}, {"meaning": "生火。", "cites": [{"t": "脚炉手炉也交出去了,你可逼着他们给你笼上。", "b": "《红楼梦》"}]}, {"meaning": "在袖内藏东西。", "cites": [{"t": "笼盖四野。", "b": "《乐府诗集·杂歌谣辞·敕勒歌》"}], "words": [{"w": "笼馒头;笼袖", "t": "把两手相对伸入两袖中。"}]}]}, {"pinyin": "lǒng", "defs": [{"meaning": "笼罩;遮掩。", "cites": [{"t": "烟笼寒水月笼沙。", "b": "杜牧《泊秦淮》"}], "words": [{"w": "笼天地于形内,挫万物于笔端", "t": "天地虽大,都可概括进形象,万物虽多,都可描绘于笔下。挫,折,有收拾役使的意思"}, {"w": "笼葱", "t": "青翠葱绿。"}]}, {"meaning": "包括;包罗。", "cites": [{"t": "丘之小不能一亩,可以笼而有之。", "b": "唐·柳宗元《钴鉧潭西小丘记》"}], "words": [{"w": "笼罗", "t": "包罗"}, {"w": "笼取", "t": "收罗"}, {"w": "笼利", "t": "搜罗财利。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2319wx','笛','1','dí','竹','11','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从竹,由声。本义:笛子,管乐器名,竹制,左一孔为吹口,次孔加竹膜,右六孔皆上出,又谓之横吹)。"}, {"meaning": "同本义。", "cites": [{"t": "笛,七孔龠也。", "b": "《说文》。按,笛长尺有四寸。马融长笛赋,谓羌笛四孔,京君明加一孔,以备五音,是汉时五孔笛。"}, {"t": "龠谓之笛。", "b": "《广雅》"}], "words": [{"w": "笛竹", "t": "用以制笛的竹子"}, {"w": "笛吹", "t": "吹笛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2320wx','笙','1','shēng','竹','11','','[{"pinyin": "shēng", "defs": [{"meaning": "(形声。从竹,生声。本义:簧管乐器) 同本义。", "cites": [{"t": "笙,十三簧象凤之身也。笙,正月之音,物生故谓之笙。", "b": "《说文》"}, {"t": "大笙谓之巢,小者谓之和。", "b": "《尔雅》"}, {"t": "笙长四尺。", "b": "《风俗通》"}, {"t": "三人吹笙,一人吹和。盖小者。", "b": "《仪礼·乡射礼记》注"}, {"t": "我有嘉宾,鼓瑟吹笙。", "b": "《诗·小雅·鹿鸣》"}], "words": [{"w": "笙弄", "t": "弄笙"}, {"w": "笙簧", "t": "簧管乐器"}, {"w": "笙咽", "t": "笙的音质失调"}, {"w": "笙竽", "t": "笙和竽"}, {"w": "笙匏", "t": "笙和匏"}, {"w": "笙筑", "t": "笙和筑"}, {"w": "笙暖", "t": "对笙簧加热,使音质清亮"}, {"w": "笙籁", "t": "笙和籁。古管乐器"}, {"w": "笙镛", "t": "亦作“笙庸”。古乐器名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2321wx','符','1','fú','竹','11','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从竹,付声。从“竹”,表示与竹子有关。本义:古代朝廷传达命令或调兵将用的凭证,双方各执一半,以验真假)。"}, {"meaning": "符信。", "cites": [{"t": "符,信也。汉制以竹长六寸分而相合。", "b": "《说文》。按,有铜虎符,竹使符,或曰五寸,古用圭璋,其后乃以符代之。"}, {"t": "门关用符节。", "b": "《周礼·掌节》。注:“如今官中诸官诏符也。”"}, {"t": "若合符节。", "b": "《孟子》"}, {"t": "封皇帝玺符节。", "b": "《汉书·高帝纪》"}, {"t": "晋鄙合符,疑之,举手视公子。", "b": "《史记·魏公子列传》"}], "words": [{"w": "符玺", "t": "古代帝王的印章"}, {"w": "符宝郎", "t": "古官名。即“符玺郎”,掌管皇帝八宝及国家的符节"}, {"w": "符契", "t": "符券契约一类文书的统称"}, {"w": "符传", "t": "古代符信之一。用于出入门关。"}]}, {"meaning": "征兆。", "cites": [{"t": "守尔天符。", "b": "《答宾戏》。注:“相命也。”"}, {"t": "以风符应合于天地。", "b": "《史记·李武纪》"}, {"t": "天之所与必先赐以符瑞。", "b": "《汉书·刘辅传》"}], "words": [{"w": "符兆", "t": "征兆"}, {"w": "符应", "t": "天降祥瑞的征兆和人事相应"}, {"w": "符表", "t": "显露的征兆"}, {"w": "符瑞", "t": "吉祥的征兆。"}]}, {"meaning": "符箓,旧时道士用来驱鬼召神或治病延年的神秘文书。", "cites": [{"t": "也有送符水的,也有荐僧道的,总不见效。", "b": "《红楼梦》"}], "words": [{"w": "符水也叫神水道士用以治病;符壳", "t": "道家的符录。亦比喻《金刚经》"}, {"w": "符书", "t": "符箓。"}]}, {"meaning": "莩甲。草木种子外皮。", "cites": [{"t": "甲者,言万物剖符甲而出也。", "b": "《史记·律书》"}]}, {"meaning": "符合;相同。", "cites": [{"t": "岂非道之所符;而自然之验邪?", "b": "《史记·货殖列传·序》"}], "words": [{"w": "符同", "t": "符合;相同"}, {"w": "符协", "t": "符合;相同"}, {"w": "符会", "t": "符合"}, {"w": "符应", "t": "符合"}, {"w": "符验", "t": "证验,符合应验。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2322wx','第','1','dì','竹','11','','[{"pinyin": "dì", "defs": [{"meaning": "(形声。从竹,弟声。本写作“弟”。本义:次第,次序)。"}, {"meaning": "同本义。有时也用于数字前表示次序。", "cites": [{"t": "第,次也。", "b": "《小尔雅·广诂》"}, {"t": "书称题亦言第,因其第次也。", "b": "《释名·释书契》。按,用于书册次弟字,故又加竹。”"}, {"t": "楚国第。", "b": "《左传·哀公十六年》。释文:“次第也。”"}, {"t": "然臣辈惜程艺天下第一。", "b": "宋·王傥《唐语林·雅量》"}, {"t": "此印者才毕,则第二板已具。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "等第", "t": "名次等级"}, {"w": "第次", "t": "等级;次第"}, {"w": "第老的", "t": "排行最小的"}, {"w": "第三本《诗经》", "t": "指宋朱熹编注的《诗经传》"}, {"w": "第六感觉", "t": "指眼、耳、鼻、舌、身五官所属的视、听、嗅、味、触觉五种感觉以外的敏锐感觉。"}]}, {"meaning": "大官的住宅。本指古代按一定品级为王侯功臣建造的大宅院,后也通称上等房屋为第。", "cites": [{"t": "北阙甲第。", "b": "张衡《西京赋》。薛注:“馆也。”"}, {"t": "公大怒…出…旬乃还第。", "b": "明·崔铣《记王忠肃公翱三事》"}], "words": [{"w": "第宇", "t": "官邸"}, {"w": "第舍", "t": "宅第,住宅"}, {"w": "第室,第屋", "t": "第宅"}, {"w": "第馆", "t": "第宅"}, {"w": "府第;宅第;私第;门第;进士第", "t": ""}]}, {"meaning": "科第。科举时代考试合格列入的等第。也指取得的功名。", "cites": [{"t": "十余年,书生用(因)甲第为相国。", "b": "清·周容《芋老人传》"}], "words": [{"w": "及第;落第;不第", "t": ""}]}, {"meaning": "仅;只;只是;尽管;只管。", "cites": [{"t": "此人可方比干,第朕非纣耳。", "b": "《明史·海瑞传》"}, {"t": "君第重射,臣能令君胜。", "b": "《史记·孙子吴起列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2323wx','敏','1','mǐn','攵','11','','[{"pinyin": "mǐn", "defs": [{"meaning": "(形声。从攴(pū),每声。甲骨文字形,像用手整理头发的样子。本义:动作快)。"}, {"meaning": "同本义。", "cites": [{"t": "敏,疾也。", "b": "《说文》"}, {"t": "曾孙不怒,农夫克敏。", "b": "《诗·小雅·甫田》"}, {"t": "君子欲纳于言而敏于行。", "b": "《论语·里仁》"}, {"t": "敏于事而慎于言。", "b": "《论语·学而》"}], "words": [{"w": "敏给", "t": "敏捷"}, {"w": "敏赡", "t": "敏捷而多智"}, {"w": "敏睿", "t": "敏捷聪慧"}, {"w": "敏疾", "t": "敏捷,迅速"}, {"w": "敏思", "t": "才思敏捷"}, {"w": "敏才", "t": "敏捷的才思。"}]}, {"meaning": "思想敏锐,反应快。", "cites": [{"t": "回虽不敏,请事斯语矣。", "b": "《论语·颜渊》"}, {"t": "是故聪与敏,可恃而不可恃也。", "b": "彭端淑《为学一首示子侄》"}, {"t": "我虽不敏。", "b": "《孟子·梁惠王上》"}, {"t": "礼成而加之以敏。", "b": "《左传·僖公三十三年》。注:“审当于事也。”"}], "words": [{"w": "敏悟", "t": "聪敏伶俐;善解人意"}, {"w": "敏博", "t": "聪明博学"}, {"w": "敏达", "t": "敏捷而通达事理"}, {"w": "敏隽", "t": "聪明俊秀"}, {"w": "敏智", "t": "聪敏机智"}, {"w": "敏识", "t": "聪明博识"}, {"w": "敏瞻", "t": "机灵多智;敏捷而丰富。"}]}, {"meaning": "勤勉。", "cites": [{"t": "敏而好学,不耻下问。", "b": "《论语·公冶长》"}, {"t": "人道敏政。", "b": "《礼记·中庸》。注:“犹勉也。”"}], "words": [{"w": "敏行", "t": "指勉力修身"}, {"w": "敏求", "t": "勉力以求"}, {"w": "敏学", "t": "勤勉好学。"}]}, {"meaning": "假借为“拇”。足大指。", "cites": [{"t": "履帝武(足迹)敏,歆,攸介攸止。", "b": "《诗·大雅·生民》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2324wx','做','1','zuò','亻','11','','[{"pinyin": "zuò", "defs": [{"meaning": "(“做”是“作”后起的分别字,“作”近代写作“做”)。"}, {"meaning": "作。从事某种工作或活动。", "cites": [{"t": "我且不做买卖,和你一同家去。", "b": "《水浒全传》"}], "words": [{"w": "做道路", "t": "做生意;从事拦路抢劫、偷盗活动"}, {"w": "做夫", "t": "服劳役;作劳动力"}, {"w": "大事做不来,小事又不做;做不得;做不了;做嗄", "t": "干什么。"}]}, {"meaning": "制作,制造。", "cites": [{"t": "此处最好,只是还少一个酒幌,明日竟做一个来。", "b": "《红楼梦》"}], "words": [{"w": "做妖撒妖", "t": "做出妖形怪状的样子"}, {"w": "做势", "t": "做出表面竟向的动作"}, {"w": "做弊", "t": "作弊,舞弊"}, {"w": "做衣服;这种糖是甜菜做的", "t": ""}]}, {"meaning": "充当。", "cites": [{"t": "马二先生做东,大盘大碗请差人吃着。", "b": "《儒林外史》"}], "words": [{"w": "做大头", "t": "当傻瓜"}, {"w": "做中", "t": "充当交易、借贷等关系中的中间证明人"}, {"w": "做虎豹", "t": "充当恶人"}, {"w": "做厂", "t": "当工人"}, {"w": "做线", "t": "打听消息,充当耳目。"}]}, {"meaning": "斗,争斗。", "cites": [{"t": "你使这等见识,我拼的和你做一场。", "b": "《桃花女》"}]}, {"meaning": "杀害,谋害。", "cites": [{"t": "难道他们竟串通一气,来做我们的。", "b": "《官场现形记》"}]}, {"meaning": "代,替。", "cites": [{"t": "见公公时,做我传语他,只教他今夜小心则个。", "b": "《古今小说》"}, {"t": "你们做老拙传话谏议,道张公教送这瓜来。", "b": "《喻世明言》"}]}, {"meaning": "定价;算作。", "cites": [{"t": "他那一路上的人恐怕旁边人有不帮衬的,打破头屑,做张做智的圆成着,做了五十两银子,卖了。", "b": "《醒世姻缘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2325wx','袋','1','dài','衣','11','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从衣,代声。本义:有口的盛器,囊属。也指衣袋) 同本义。", "cites": [{"t": "羊骨杂他骨,作五袋盛之。", "b": "《南史·羊鸦仁传》"}], "words": [{"w": "网袋;塑料袋;旅行袋;工具袋;子弹袋;烟叶袋;水泥袋", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2326wx','悠','1','yōu','心','11','','[{"pinyin": "yōu", "defs": [{"meaning": "(形声。从心,攸(yōu)声。本义:忧思)。"}, {"meaning": "同本义。", "cites": [{"t": "悠,忧也。", "b": "《说文》"}, {"t": "悠,思也。", "b": "《尔雅》"}, {"t": "悠悠我里。", "b": "《诗·小雅·十月之交》。注:“忧也。”"}, {"t": "悠悠苍天兮。", "b": "《楚辞·初放》"}, {"t": "悠哉悠哉,辗转反侧。", "b": "《诗·周南·关睢》"}, {"t": "西北秋风至,楚客心悠哉。", "b": "南朝梁·江淹《杂体诗三十首》"}], "words": [{"w": "悠然", "t": "忧伤的样子"}, {"w": "悠忧", "t": "忧伤。"}]}, {"meaning": "做事从容不迫。", "cites": [{"t": "听安老爷这等说,便道:“喂!你悠着点儿,老头子!我一个出家人,不当家花拉的,你叫我那儿养小子去呀?”", "b": "《儿女英雄传》"}]}, {"meaning": "长;远。", "cites": [{"t": "今吾道路悠远。", "b": "《国语·吴语》。注:“长也。”"}, {"t": "悠远长怀。", "b": "《史记·司马相如传》"}, {"t": "江山悠隔,朝宗无阶。", "b": "《晋书》"}, {"t": "於乎悠哉,朕未有艾。", "b": "《诗·周颂·访落》"}, {"t": "山海隔中州,相去悠且长。", "b": "汉·苏武《诗四首》"}], "words": [{"w": "悠永", "t": "久远"}, {"w": "悠修", "t": "遥远"}, {"w": "悠逖", "t": "远方"}, {"w": "悠婉", "t": "悠扬婉转"}, {"w": "悠短", "t": "长短"}, {"w": "悠裔", "t": "辽远"}, {"w": "悠漫", "t": "漫长"}, {"w": "悠缅", "t": "久远;遥远"}, {"w": "悠邈", "t": "久远"}, {"w": "悠阔", "t": "辽阔"}, {"w": "悠旷", "t": "遥远。"}]}, {"meaning": "飘扬的样子。", "cites": [{"t": "建辰旒之太常,纷焱悠以容裔。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "悠气儿", "t": "微弱的气息"}, {"w": "悠奕", "t": "飘逸姣丽的样子"}, {"w": "悠柔", "t": "悠扬柔和"}, {"w": "悠逸", "t": "飘逸"}, {"w": "悠婉", "t": "悠扬婉转。"}]}, {"meaning": "闲适的样子。", "cites": [{"t": "采菊东篱下,悠然见南山。", "b": "晋·陶潜《饮酒二十首》"}], "words": [{"w": "悠闲;悠暇", "t": "闲适"}, {"w": "悠溶", "t": "安闲的样子。"}]}, {"meaning": "众多。", "cites": [{"t": "看福寿有,子女悠,夫人又。", "b": "明·汤显祖《牡丹亭》"}], "words": [{"w": "悠悠", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2327wx','偿','1','cháng','亻','11','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从人,赏声。本义:归还,赔偿)。"}, {"meaning": "同本义。", "cites": [{"t": "偿,还也。", "b": "《说文》"}, {"t": "偿,复也。", "b": "《广雅》"}, {"t": "西邻责言不可偿也。", "b": "《左传·僖公十五年》"}, {"t": "使吏召诸民当偿者悉来合券。", "b": "《战国策·齐策四》"}], "words": [{"w": "偿债", "t": "偿还欠债"}, {"w": "偿付", "t": "归还所欠的债。"}]}, {"meaning": "补偿,抵偿。", "cites": [{"t": "相如视秦王无意偿赵城。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "偿罪;偿死", "t": "抵命"}, {"w": "得不偿失", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2328wx','偶','1','ǒu','亻','11','','[{"pinyin": "ǒu", "defs": [{"meaning": "(形声。从人,禺声。禺,通常读yù,又音ǒu。本义:仿人形制成的木偶)。"}, {"meaning": "同本义。", "cites": [{"t": "偶,相人也。", "b": "《说文》。按,相人者,像人也。一名俑。"}, {"t": "鲁以偶人,而孔子叹。", "b": "《淮南子·缪称》"}, {"t": "见偶人与偶人相与语。", "b": "《史记·孟尝君列传》"}], "words": [{"w": "头偶;偶戏", "t": "木偶戏。"}]}, {"meaning": "伙伴;同伴;与人共处。", "cites": [{"t": "乃率其曹偶,亡之江中。", "b": "《史记·黥布列传》"}], "words": [{"w": "偶行", "t": "结伴同行"}, {"w": "偶攻", "t": "结伙攻击"}, {"w": "偶耕", "t": "两人并耕"}, {"w": "偶影", "t": "与影为偶,形容孤独"}, {"w": "偶寝", "t": "同睡。"}]}, {"meaning": "配合。", "cites": [{"t": "汝明勗偶王,在亶,乘兹大命。", "b": "《书·君奭》"}]}, {"meaning": "匹对;配偶。", "cites": [{"t": "汝幸而偶我,又何不幸而生今日之中国。(偶,动词。与…为配偶,这里作“嫁”字解释。)", "b": "清·林觉民《与妻书》"}], "words": [{"w": "良偶;丧偶;偶成", "t": "配成婚姻"}, {"w": "偶配", "t": "结成配偶"}, {"w": "偶婚", "t": "即对偶婚。"}]}, {"meaning": "假借为“遇”。遇合,得到赏识。", "cites": [{"t": "然士亦有遇合,贤者多如此二子,不得尽意,岂可胜道哉!", "b": "《史记·范雎蔡泽列传赞》"}]}, {"meaning": "相对。", "cites": [{"t": "偶视也先俯。", "b": "《荀子·脩身》"}, {"t": "有敢偶言《诗》《书》者弃市。", "b": "司马迁《史记·秦始皇本纪》"}], "words": [{"w": "偶视", "t": "相对而视"}, {"w": "偶坐", "t": "相对而坐;同坐;陪坐"}, {"w": "偶言", "t": "相聚议论。"}]}, {"meaning": "偶然;偶尔。", "cites": [{"t": "偶命厨者。", "b": "清·周容《芋老人传》"}, {"t": "偶陈戏乐。", "b": "清·张廷玉《明史》"}, {"t": "天子偶用一物,未必不过此已忘;而奉行者即为定例。", "b": "《聊斋志异·促织》"}], "words": [{"w": "偶兴", "t": "偶然产生的意趣"}, {"w": "偶一", "t": "偶或;偶然"}, {"w": "偶成", "t": "偶然成功"}, {"w": "偶发", "t": "偶然发生"}, {"w": "偶题", "t": "偶然而题。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2329wx','偎','1','wēi','亻','11','','[{"pinyin": "wēi", "defs": [{"meaning": "(形声。从人,畏声。本义:亲近)。"}, {"meaning": "同本义。", "cites": [{"t": "不偎不爱。", "b": "《列子·黄帝》"}, {"t": "天毒偎人爱人。", "b": "《山海经·海内经》"}], "words": [{"w": "偎爱", "t": "相亲爱"}, {"w": "偎妻靠妇", "t": "依恋妻子"}, {"w": "偎红倚翠", "t": "亲狎女色;狎妓"}, {"w": "偎干就湿", "t": "形容母育儿之苦。"}]}, {"meaning": "依傍,紧靠着。", "cites": [{"t": "灞岸晴来送别频,相偎相倚不胜春。", "b": "唐·罗隐《柳》。又如:偎守(偎依厮守);偎并(偎依并立);偎怜(偎依怜爱);偎拥(偎依拥挤);紧偎着母亲的婴儿"}]}, {"meaning": "哄;安慰;劝导。", "cites": [{"t": "只怕女儿不肯,须是缓缓的偎他。", "b": "明·冯梦龙《警世通言》"}], "words": [{"w": "偎留", "t": "款留。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2330wx','偷','1','tōu','亻','11','','[{"pinyin": "tōu", "defs": [{"meaning": "(形声。从人,俞声。本义:苟且;马虎)。"}, {"meaning": "同本义。", "cites": [{"t": "偷,苟且也。", "b": "《说文》"}, {"t": "其下偷以幸。", "b": "《国语·晋语一》"}, {"t": "安肆曰偷。", "b": "《礼记·表记》"}, {"t": "存者且偷生。", "b": "唐·杜甫《石壕吏》"}, {"t": "偷性命于榛莽。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "诸司素偷惰。", "b": "清·张廷玉《明史》"}], "words": [{"w": "偷的锣儿敲不得", "t": "喻不能声张"}, {"w": "偷存", "t": "偷生;苟活"}, {"w": "偷合", "t": "苟且迎合"}, {"w": "偷弛", "t": "苟且松弛"}, {"w": "偷免", "t": "苟免"}, {"w": "偷快", "t": "苟求快乐"}, {"w": "偷幸", "t": "苟且侥幸"}, {"w": "偷苟", "t": "苟且。"}]}, {"meaning": "浅薄;不厚道。", "cites": [{"t": "则民不偷。", "b": "《论语·泰伯》"}], "words": [{"w": "偷俗", "t": "浅薄的人情风俗"}, {"w": "偷风", "t": "浅薄的社会风气"}, {"w": "偷浅", "t": "浅薄。"}]}, {"meaning": "轻视。", "cites": [{"t": "子大叔、子羽谓子产曰:“韩子亦无几术,晋国亦未可以贰。晋国、韩子不可偷也。”", "b": "《左传》"}]}, {"meaning": "取。", "cites": [{"t": "柳占三春色,莺偷百鸟声。", "b": "唐·温庭筠《太子西池》"}]}, {"meaning": "窃取。", "cites": [{"t": "偷,盗也。", "b": "《广韵》"}, {"t": "楚有善为偷者。", "b": "《淮南子·道应训》"}, {"t": "偷者,天下之盗也。", "b": ""}, {"t": "专操国柄以偷天下。", "b": "《后汉书·陈元传》"}], "words": [{"w": "偷钱;偷东西;偷嘴;偷吃东西;从停车场偷了一辆车;从银柜偷钱;偷了配方,并开始自己制造这种产品", "t": ""}]}, {"meaning": "盗窃他人钱物的人。", "cites": [{"t": "群偷惊走。", "b": "《晋书·王献之传》"}], "words": [{"w": "小偷", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2331wx','您','1','nín','心','11','','[{"pinyin": "nín", "defs": [{"meaning": "注意:用于多数时不加词尾“们”,两个人称“您俩”或“您二位”,三个人称“您仨”或“您三位”,三个人以上称“您诸位”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2332wx','售','1','shòu','口','11','','[{"pinyin": "shòu", "defs": [{"meaning": "(形声。从口,雔省声。雔(chóu)。本义:卖出去)。"}, {"meaning": "同本义。", "cites": [{"t": "售,卖出手也。", "b": "《说文新附》"}, {"t": "卖之,不可偻售也。", "b": "《荀子·儒效》"}, {"t": "吾售之,人取之,未尝有言,而独不足子所乎?", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "售卖", "t": "卖出;出售。"}]}, {"meaning": "买。", "cites": [{"t": "欲居之以为利,而高其值,亦无售者。", "b": "《聊斋志异·促织》"}, {"t": "问其价,曰:“止四百。”余怜而售之。", "b": "唐·柳宗元《钴鉧潭西小丘记》"}, {"t": "欲居之以为利,而高其直,亦无售者。", "b": "《聊斋志异·促织》"}], "words": [{"w": "售世", "t": "行世。"}]}, {"meaning": "引申为酬谢。", "cites": [{"t": "一日,以花来献,予售以斗酒。", "b": "宋·沈作喆《寓简》"}]}, {"meaning": "推行;施展。", "cites": [{"t": "挟邪作蛊,于是不售。", "b": "张衡《西京赋》"}], "words": [{"w": "售奸", "t": "施展阴谋诡计"}, {"w": "售迹", "t": "发迹。谓扬名立业"}, {"w": "售赇", "t": "行贿"}, {"w": "售谤", "t": "散播毁谤他人的言语。"}]}, {"meaning": "指女子得嫁。", "cites": [{"t": "更遭丧乱嫁不售,一生抱恨长咨嗟。", "b": "杜甫《负薪行》"}], "words": [{"w": "售子", "t": "妇女改嫁所带之子。"}]}, {"meaning": "考试得中。", "cites": [{"t": "邑有成名者,操童子业,久不售。(谓长久没有考取秀才。)", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2333wx','停','1','tíng','亻','11','','[{"pinyin": "tíng", "defs": [{"meaning": "(形声。从人,亭声。本义:停止,止息)。"}, {"meaning": "同本义。", "cites": [{"t": "停,定也,定于所在也。", "b": "《释名·释言语》"}, {"t": "潢汙行潦之水。", "b": "《左传·隐公三年》。注:“潢汙,停水。”"}, {"t": "停杯投箸不能食。", "b": "唐·李白《行路难》"}, {"t": "琵琶声停欲语迟。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "余亦停弗上。", "b": "《徐霞客游记·游黄山记》"}, {"t": "时方冬停遣。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "停床", "t": "指亡故"}, {"w": "停市", "t": "停止交易"}, {"w": "停刑", "t": "停止执行刑罚"}, {"w": "停步", "t": "停止前进。"}]}, {"meaning": "停留,暂时居住。", "cites": [{"t": "停数日。", "b": "晋·陶渊明《桃花源记》"}, {"t": "停于大室之隅。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "停留长智", "t": "耽搁久了,自会想出主意来"}, {"w": "停伫", "t": "停留伫立"}, {"w": "停逗", "t": "停留"}, {"w": "停眠", "t": "停留住宿"}, {"w": "停待", "t": "等待;停留"}, {"w": "停缓", "t": "停留缓行"}, {"w": "停蓄", "t": "停留蓄积"}, {"w": "停积", "t": "停留蓄积。"}]}, {"meaning": "停放;停泊。", "cites": [{"t": "停车坐爱枫林晚,霜叶红于二月花。", "b": "杜牧《山行》"}, {"t": "停船暂借问,或恐是同乡。", "b": "崔颢《长干行》"}], "words": [{"w": "停丧挂孝", "t": "停棺在家等待吊丧,悬挂孝幛,戴孝尽礼"}, {"w": "停柩", "t": "停灵。停放灵柩或在埋葬前暂时停放。"}]}, {"meaning": "蓄积 。", "words": [{"w": "停蓄", "t": "停积"}, {"w": "停食", "t": "积食"}, {"w": "停浸", "t": "聚积"}, {"w": "停涵", "t": "停蓄沉浸"}, {"w": "停塌", "t": "屯积"}, {"w": "停潦", "t": "积水。"}]}, {"meaning": "抚育 。", "words": [{"w": "停育;停毒", "t": "化育;养育。"}]}, {"meaning": "耸立 。", "words": [{"w": "停停", "t": "耸立貌;高貌。"}]}, {"meaning": "停滞 。", "words": [{"w": "停阴", "t": "集结不散的阴云"}, {"w": "停云", "t": "停止不动的云"}, {"w": "停云落月", "t": "在信中表示对友人的思慕。"}]}, {"meaning": "成数,总数分成几份,其中一份叫一停 。", "words": [{"w": "十停人中有八停人去了", "t": ""}]}, {"meaning": "行人停留宿食的处所 。", "words": [{"w": "停传", "t": "宿站"}, {"w": "停落", "t": "驿亭村落"}, {"w": "停居", "t": "租寓之所。"}]}, {"meaning": "停当。妥贴;妥当 。", "words": [{"w": "停妥", "t": "停当妥贴"}, {"w": "停稳", "t": "妥贴"}, {"w": "停腾", "t": "停当"}, {"w": "停脱", "t": "停当"}, {"w": "停停当当", "t": "妥妥贴贴"}, {"w": "停停脱脱", "t": "稳稳当当。"}]}, {"meaning": "平均的 。", "words": [{"w": "停分", "t": "均分,各据一半"}, {"w": "停匀", "t": "匀称"}, {"w": "停直", "t": "匀而直。"}]}, {"meaning": "正值。", "cites": [{"t": "自非停午夜分,不见曦月。", "b": "《水经注·江水》"}, {"t": "持钵安行,出彼祗树,不逾停午,以福众生。", "b": "梁·沈约《千僧愿会文》"}], "words": [{"w": "停午", "t": "正午。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2334wx','偏','1','piān','亻','11','','[{"pinyin": "piān", "defs": [{"meaning": "(形声。从人,扁声。本义:不正,倾斜)。"}, {"meaning": "同本义。", "cites": [{"t": "偏,颇也。", "b": "《说文》"}, {"t": "无偏无颇。", "b": "《书·洪范》"}, {"t": "势有偏侧。", "b": "南朝宋·谢灵运《山居赋》"}], "words": [{"w": "偏岸", "t": "斜岸"}, {"w": "偏偏倒倒", "t": "东倒西歪。形容站不稳"}, {"w": "偏侧", "t": "犹倾侧;偏斜"}, {"w": "偏倒", "t": "倾斜。"}]}, {"meaning": "边远。", "cites": [{"t": "心远地自偏。", "b": "晋·陶渊明《饮酒》"}], "words": [{"w": "偏邦", "t": "远离中原地区的边远小国"}, {"w": "偏伯", "t": "边远地方的长官"}, {"w": "偏海", "t": "边远的滨海地区"}, {"w": "偏泽", "t": "边远之地"}, {"w": "偏州", "t": "僻远之州"}, {"w": "偏陬", "t": "僻远之地。"}]}, {"meaning": "片面,侧重于某一方面或某一部分。", "words": [{"w": "偏为", "t": "偏向;偏袒"}, {"w": "偏任", "t": "片面信任"}, {"w": "偏行", "t": "片面实行"}, {"w": "偏定", "t": "片面论定"}, {"w": "偏解", "t": "片面的见解"}, {"w": "偏辞", "t": "片面之词"}, {"w": "偏裨", "t": "偏将与裨将。"}]}, {"meaning": "偏私;不公正;不公平。", "cites": [{"t": "王道荡荡,不偏不党;王道平平,不党不偏。", "b": "《墨子·兼爱下》"}, {"t": "通则骄而偏。", "b": "《荀子·不苟》"}], "words": [{"w": "偏佞", "t": "偏私奸巧"}, {"w": "偏指", "t": "偏私的意愿"}, {"w": "偏徇", "t": "偏私曲从"}, {"w": "偏护", "t": "偏私的袒护"}, {"w": "偏执", "t": "固执"}, {"w": "偏介", "t": "孤高偏执"}, {"w": "偏吝", "t": "偏执鄙吝"}, {"w": "偏令", "t": "偏颇的政令"}, {"w": "偏曲", "t": "偏颇隐晦"}, {"w": "偏政", "t": "偏颇的政教"}, {"w": "偏恣", "t": "偏颇任性"}, {"w": "偏说", "t": "偏颇、片面的言论"}, {"w": "偏质", "t": "偏颇之性"}, {"w": "偏论", "t": "偏颇的议论。"}]}, {"meaning": "假借为“遍”。普遍。", "cites": [{"t": "则不可偏观也。", "b": "《墨子·小取》"}]}, {"meaning": "扁舟,小船。", "cites": [{"t": "乘偏舟于五湖。", "b": "《后汉书·隗嚣传》"}]}, {"meaning": "疾飞,飘扬。"}, {"meaning": "部属。", "cites": [{"t": "举其偏,不为党。", "b": "《左传·襄公三年》"}]}, {"meaning": "配偶的一方。", "cites": [{"t": "但以偏亲垂老,生计屡空,聊复靦颜以居,未能投劾而去。", "b": "宋·秦观《谢馆职启》"}], "words": [{"w": "偏栖", "t": "独居。"}]}, {"meaning": "倾侧。", "cites": [{"t": "太阳已偏到西边去。", "b": "老舍《四世同堂》"}]}, {"meaning": "表示时间,相当于“正的”、“恰巧”。", "cites": [{"t": "正是扬帆时,偏逢江上客。", "b": "唐·皇甫冉《曾东游以诗寄之》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2335wx','躯','1','qū','身','11','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从身,区声。本义:身体)。"}, {"meaning": "同本义。", "cites": [{"t": "躯,体也。", "b": "《说文》"}, {"t": "籍柔覆温之躯。", "b": "明·刘基《卖柑者言》"}, {"t": "赖是以食吾躯。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "躯老", "t": "躯劳。身体,身段"}, {"w": "血肉之躯;躯量", "t": "身材"}, {"w": "躯躬", "t": "身体。引申指生命"}, {"w": "躯材", "t": "身材"}, {"w": "躯身", "t": "身躯。"}]}, {"meaning": "身孕。", "cites": [{"t": "其母怀躯,阳气内养。", "b": "《三国志》"}]}, {"meaning": "“躯口”的省称。宋元时代女真族和蒙古族称被俘获并强迫服劳役的汉族人为“躯口”。", "cites": [{"t": "你道要女儿着钱赎个婢,要厮儿着钞买一个躯。", "b": "佚名《刘弘嫁婢》"}]}, {"meaning": "身体的数目。", "cites": [{"t": "中有丈八金像一躯,中长金像十躯,绣珠像三躯。", "b": "北魏·杨衒之《洛阳伽蓝记》"}], "words": [{"w": "一躯死尸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2336wx','兜','1','dōu','儿','11','','[{"pinyin": "dōu", "defs": [{"meaning": "兜鍪,即胄,古代头盔名。", "words": [{"w": "兜鞬", "t": "头盔和皮革制的弓箭袋,也泛指武器装备"}, {"w": "兜鍪铠", "t": "战士戴的头盔和铠甲"}, {"w": "兜巾", "t": "有后兜的帽子。"}]}, {"meaning": "迷惑;受蒙蔽。", "cites": [{"t": "在列者献诗,使勿兜。", "b": "《国语·晋语》。注:“感也。”"}], "words": [{"w": "兜罗", "t": "笼络;收拾"}, {"w": "兜结", "t": "奉承,巴结"}, {"w": "兜答", "t": "兜搭。周折;麻烦;难对付;心眼多。"}]}, {"meaning": "包裹;围绕;环绕。", "cites": [{"t": "腰间解下麻索来,兜住卢俊义肚皮去那松树上只一勒,反拽过脚来绑在树上。", "b": "《水浒传》"}], "words": [{"w": "在城里兜了一圈;兜翻", "t": "捆绑拖翻。"}]}, {"meaning": "用瓢勺等取东西。", "cites": [{"t": "一个客人便去揭开桶盖,兜了一瓢,拿上便吃。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2337wx','假','1','jiǎ jià xiá','亻','11','','[{"pinyin": "jiǎ", "defs": [{"meaning": "(形声。从人,叚(jiǎ)声。“叚”亦兼表字义。本义:不是真的)。"}, {"meaning": "同本义(跟“真”相反)。", "cites": [{"t": "假,非真也。", "b": "《说文》"}, {"t": "假,今不然也。", "b": "《墨子·经上》"}, {"t": "假寐永叹。", "b": "《诗·小雅·小弁》。笺:“不脱冠衣而寐曰假寐。”"}, {"t": "为假上将军。", "b": "《史记·项羽纪》"}, {"t": "假令单于初立。", "b": "《汉书·匈奴传》"}, {"t": "大丈夫定诸侯,即为真王耳,何以假为?", "b": "《史记·淮阴侯列传》"}, {"t": "乃悟前狼假寐,盖以诱敌。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "假姨姨", "t": "假亲戚,冒充的亲戚"}, {"w": "假言", "t": "虚假不实的言语"}, {"w": "假女", "t": "鸨儿称自己认作养女的妓女"}, {"w": "假局", "t": "假局子。诱人的骗局,圈套"}, {"w": "假子", "t": "非亲身的儿子,如干儿子、前夫之子等。"}]}, {"meaning": "代理,非正式。", "cites": [{"t": "周公旦假为天子七年。", "b": "《韩非子·难二》"}], "words": [{"w": "假摄", "t": "代理职务"}, {"w": "假髻", "t": "人造的发髻"}, {"w": "假吏", "t": "暂时代理职务的官吏"}, {"w": "假守", "t": "古代称权宜派遣而非正式任命的地方官。"}]}, {"meaning": "借。兼指借出和借入。", "cites": [{"t": "假,借也。", "b": "《广雅》"}, {"t": "假尔大龟有常。", "b": "《礼记·曲礼》"}, {"t": "而假手于我寡人。", "b": "《左传·隐公十一年》"}, {"t": "唯器与名不可以假人。", "b": "《左传·成公二年》"}, {"t": "晋侯复假道于虞以伐虢。", "b": "《左传·僖公五年》"}, {"t": "以书假余。", "b": "明·宋濂《送东阳马生序》"}, {"t": "假诸人。", "b": ""}, {"t": "而强假焉。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "假榻", "t": "借住"}, {"w": "假馆", "t": "借馆舍以住宿;借用书塾读书"}, {"w": "假宿", "t": "借宿"}, {"w": "假以辞色", "t": "好言好语、和颜悦色的对待"}, {"w": "假途灭虢", "t": "春秋时晋国向虞国借路攻打虢国。灭虢回兵时把虞国了灭掉了。后以此比喻以“假途”为名,行灭他国之实的计策。"}]}, {"meaning": "租赁;雇佣。", "cites": [{"t": "久假而不归。", "b": "《孟子·尽心上》"}], "words": [{"w": "假居", "t": "租屋而居;暂借居住"}, {"w": "假税", "t": "租赁应缴的税"}, {"w": "假赁", "t": "借,租借。"}]}, {"meaning": "凭借。", "cites": [{"t": "假舆马者。", "b": "《荀子·劝学》"}, {"t": "假舟楫者。", "b": ""}, {"t": "善假于物也。", "b": ""}], "words": [{"w": "假力于人", "t": "凭借他人的力量"}, {"w": "假助", "t": "借助"}, {"w": "假虎", "t": "比喻借用他人之事作威作福的人"}, {"w": "假虎张威", "t": "狐假虎威。"}]}, {"meaning": "授予;给予。", "cites": [{"t": "假大兵权。", "b": "清·梁启超《谭嗣同传》"}, {"t": "假吾人彭聃之寿。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "假兵权", "t": "给予兵权"}, {"w": "假人", "t": "授予人"}, {"w": "假年", "t": "给以岁月。指延长寿命"}, {"w": "假息", "t": "苟延残喘。"}]}, {"meaning": "宽容;宽饶。", "cites": [{"t": "大臣犯法,无所宽假。", "b": "《北史·魏世祖纪》"}], "words": [{"w": "假易", "t": "宽纵;宽容"}, {"w": "假纵", "t": "宽纵。"}]}, {"meaning": "赞美,表彰。", "cites": [{"t": "假以溢我,我其收之。", "b": "《诗·周颂·维天之命》"}, {"t": "假乐君子,显显令德。", "b": "《诗·大雅·假乐》"}, {"t": "假而礼之,厚而勿欺,则天下之士至矣。", "b": "《管子·小问》"}]}, {"meaning": "假设,如果。", "cites": [{"t": "假之有人而欲南,无多。", "b": "《荀子·正名》"}, {"t": "假其惊怖斯言。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "假饶", "t": "如果;假若"}, {"w": "假似", "t": "如果;假设"}, {"w": "假之", "t": "假若"}, {"w": "假而", "t": "假如。"}]}, {"meaning": "暂且;权宜。", "cites": [{"t": "吾未哺食,请假设草具。", "b": "柳宗元《段太尉逸事状》"}], "words": [{"w": "假嘈", "t": "胡乱应付"}, {"w": "假延", "t": "暂且延缓"}, {"w": "假埋", "t": "假葬。暂时埋葬以待改葬"}, {"w": "假翮", "t": "暂时依附。"}]}, {"meaning": "凭借。", "cites": [{"t": "君子生非异也,善假于物也。", "b": "《荀子·劝学》"}, {"t": "愿假宠以请予诸侯。", "b": "《左传·昭公四年》"}, {"t": "假此科敛丁口。", "b": "《聊斋志异》"}]}, {"meaning": "当。", "cites": [{"t": "假今之世。", "b": "《荀子》"}]}]}, {"pinyin": "jià", "defs": [{"meaning": "休假。", "cites": [{"t": "聊假日以消忧。", "b": "王粲《登楼赋》"}], "words": [{"w": "放假三天;假限", "t": "假期,假期的期限"}, {"w": "假休", "t": "休假"}, {"w": "假告", "t": "告假"}, {"w": "假卒", "t": "休假的士兵。"}]}]}, {"pinyin": "xiá", "defs": [{"meaning": "远。", "cites": [{"t": "彼且择日而登假。", "b": "《庄子·德充符》"}, {"t": "告丧,曰天王登假。", "b": "《礼记·曲礼下》"}, {"t": "其不能乘云升假亦明矣。", "b": "《淮南子·齐俗》"}, {"t": "又二十有八年,天下大治,几若华胥氏之国,而帝登假。", "b": "《列子·黄帝》"}], "words": [{"w": "假尔攸仰", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2338wx','衅','1','xìn','血','11','','[{"pinyin": "xìn", "defs": [{"meaning": "(会意。从爨省,爨(cuàn),灶。从酉(yǒu),与酒有关,表祭祀。分,表示分布。合起来表杀牲以祭。本义:古代血祭新制的器物。杀牲,用其血涂于器物缝隙中来祭祀)。"}, {"meaning": "同本义。", "cites": [{"t": "釁,血祭也。", "b": "《说文》"}, {"t": "隋衅。", "b": "《周礼·大祝》。注:“谓荐血也。”"}, {"t": "大师掌衅祈号祝。", "b": "《周礼·小祝》"}, {"t": "不以累臣衅鼓。", "b": "《左传·僖公三十三年》"}, {"t": "车甲衅而藏之府库。", "b": "《礼记·乐记》"}, {"t": "将以衅钟。", "b": "《孟子》"}, {"t": "衅鼓旗甲兵。", "b": "《吕氏春秋·慎大》"}, {"t": "桓公践位,令衅社塞祷。", "b": "《管子·小问》。注:“杀牲以血浇落于社曰衅社。”"}, {"t": "缚之,杀以衅鼓。", "b": "《韩非子》"}], "words": [{"w": "衅宝镇及宝器;衅钟;衅宝刀;衅社", "t": "杀牲取血以祭社神"}, {"w": "衅鼓", "t": "杀人或杀牲以血涂鼓行祭。"}]}, {"meaning": "涂。", "cites": [{"t": "比至,三衅、三浴之。", "b": "《国语》。韦昭注:“以香涂身曰衅。”"}], "words": [{"w": "衅尸", "t": "古代丧礼以鬯酒涂尸"}, {"w": "衅浴", "t": "用芳香涂身后沐浴以除秽恶。引申为认真研究,用精取宏"}, {"w": "衅鬯", "t": "涂尸的香酒。"}]}, {"meaning": "缝隙;裂痕。", "cites": [{"t": "会闻用师,观衅而动。", "b": "《左传·宣公十二年》。孔颖达疏:“衅是间隙之名。今人谓瓦裂龟裂皆为衅。”"}, {"t": "为室三重,户闭,涂衅必周。", "b": "《后汉书·律历志上》"}], "words": [{"w": "衅会", "t": "有衅可乘的时机。"}]}, {"meaning": "祸患;祸乱。", "cites": [{"t": "夫功全则誉显,业谢则衅生。", "b": "《后汉书》"}], "words": [{"w": "衅首", "t": "祸乱之首"}, {"w": "衅逆", "t": "叛乱"}, {"w": "衅辱", "t": "蒙祸受辱"}, {"w": "衅累", "t": "祸患与事端的牵连"}, {"w": "衅祸", "t": "祸乱。"}]}, {"meaning": "罪过。", "cites": [{"t": "衅门子弟不得居宿卫近侍之官。", "b": "《通志》"}], "words": [{"w": "衅情", "t": "罪情,罪恶的用心"}, {"w": "衅恶", "t": "罪恶"}, {"w": "衅稔恶盈", "t": "罪大恶极"}, {"w": "衅故", "t": "罪情,罪行。"}]}, {"meaning": "过失。", "cites": [{"t": "人无衅焉,妖不自作。", "b": "《左传·庄公十四年》"}], "words": [{"w": "衅咎", "t": "过失,罪过"}, {"w": "衅眚", "t": "过失"}, {"w": "衅过", "t": "过失,罪"}, {"w": "衅弊", "t": "缺失,弊端。"}]}, {"meaning": "争端。引起争执的事端。", "cites": [{"t": "想此事大半衅由姚婆,毒谋出于方贼,今已父子并诛,斩草除根,大仇已报,余人无罪,不可妄及。", "b": "《石点头》"}], "words": [{"w": "边衅;挑衅", "t": "借端生事,企图引起冲突或战争"}, {"w": "寻衅", "t": ""}]}, {"meaning": "征兆。", "cites": [{"t": "近览刘氏倾覆之衅。", "b": "《三国志》"}], "words": [{"w": "衅兆", "t": "征兆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2339wx','徘','1','pái','彳','11','','[{"pinyin": "pái", "defs": [{"meaning": "(形声。从彳,非声。彳读chì,表示小步行走)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2340wx','徙','1','xǐ','彳','11','','[{"pinyin": "xǐ", "defs": [{"meaning": "(形声。从辵(chuò),止声。本义:迁移)。"}, {"meaning": "同本义 (平行或由上而下的移动)。", "cites": [{"t": "徙,迻也。", "b": "《说文》"}, {"t": "徙,移也。", "b": "《广雅》"}, {"t": "若徙于他。", "b": "《周礼·比长》。注:“谓出居异乡也。”"}, {"t": "死徙无出乡。", "b": "《孟子》注:“谓爰土易居平肥硗也。”"}, {"t": "百里徙。", "b": "《荀子·成相》。注:“迁也。”"}, {"t": "徙武北海。", "b": "东汉·班固《汉书·李广苏建传》"}, {"t": "号呼而转徙。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "非死则徙。雾徙于后。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "徙倚", "t": "徘徊;留连"}, {"w": "徙贯", "t": "迁地居住,更换籍贯"}, {"w": "迁徙", "t": "迁移"}, {"w": "徙居", "t": "徙次,即迁居,徙家,徙道。迁居。"}]}, {"meaning": "改变,变化。", "cites": [{"t": "具生器以适墓,象徙道也。", "b": "《荀子·礼论》。注:“迁改也。”"}, {"t": "时已徙矣,而法不徙,以此为治,岂不难哉?", "b": "《吕氏春秋·察今》"}], "words": [{"w": "徙意", "t": "改变意念"}, {"w": "徙义", "t": "见义即改变意念而从之。"}]}, {"meaning": "贬谪。", "cites": [{"t": "于是孔明废之为庶人,徙之汶山。", "b": "《三国演义》"}], "words": [{"w": "徙放", "t": "流放"}, {"w": "徙逐", "t": "放逐"}, {"w": "徙废", "t": "贬谪废弃"}, {"w": "徙锢", "t": "贬谪禁锢"}, {"w": "徙边", "t": "将犯人流放边境服劳役。"}]}, {"meaning": "搬走,搬开。", "cites": [{"t": "徙其大舟。", "b": "《国语·吴语》。注:“取也。”"}, {"t": "叔孙已死,竖牛因不发丧也,徙其府库重宝空之而奔齐。", "b": "《韩非子·内储说上》"}], "words": [{"w": "徙薪", "t": "见“徙薪曲突”。引申为代国家灭除灾祸,战功颇丰。"}]}, {"meaning": "调职。", "cites": [{"t": "衡不慕当世,所居之官辄积年不徙。", "b": "《后汉书·张衡传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2341wx','得','1','dé de děi','彳','11','','[{"pinyin": "dé", "defs": [{"meaning": "(会意。金文字形,右边是“贝”(财货)加“手”,左边是“彳”,表示行有所得。手里拿着财货,自然是有所得。本义:得到,获得)。"}, {"meaning": "同本义(本来没有而争取得来成为己有)。", "cites": [{"t": "得,行有所得也。", "b": "《说文》"}, {"t": "三人行必得我师焉。", "b": "《论语》。释文:“本或作必有。”"}, {"t": "缘木求鱼,虽不得鱼,无后灾。", "b": "《孟子·梁惠王上》"}, {"t": "佳婿难得。", "b": "《世说新语·假谲》"}, {"t": "卖炭得钱何所营。", "b": "唐·白居易《卖炭翁》"}, {"t": "工之侨得良桐焉。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "得人心;各得其所;得肆", "t": "得志,肆意"}, {"w": "得闲儿", "t": "有空闲时间;得空"}, {"w": "得胜回头", "t": "宋元说书人在开讲正书前先说一段小故事作引子,叫得胜回头"}, {"w": "得职", "t": "获得官职"}, {"w": "得情报;得钱;得奖", "t": ""}]}, {"meaning": "找到。", "cites": [{"t": "知得而不知丧。", "b": "《易·文言》"}, {"t": "虑而后后能得。", "b": "《礼记·大学》。注:“谓得事之宜也。”"}, {"t": "至德不得。", "b": "《庄子·秋水》"}, {"t": "既而得其尸于井。", "b": "《聊斋志异·促织》"}]}, {"meaning": "得知。", "cites": [{"t": "故无术者得于不用。", "b": "《韩非子》"}, {"t": "礼得其报则乐。", "b": "《礼记·乐记》。注:“谓晓其义。”"}, {"t": "武王得之矣。", "b": "《吕氏春秋·义赏》。注:“犹知也。”"}]}, {"meaning": "捕获。", "cites": [{"t": "然得而腊之以为饵。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "成功;完成。", "cites": [{"t": "已经传人画图样去了。明日就得。", "b": "《红楼梦》"}], "words": [{"w": "得算", "t": "计谋成功"}, {"w": "得策", "t": "谋略得当。"}]}, {"meaning": "适,合。", "cites": [{"t": "傲啸东轩下,聊复得此生。", "b": "陶渊明《饮酒》"}]}, {"meaning": "具备。", "cites": [{"t": "积善成德,而神明自得。", "b": "《荀子·劝学》"}]}, {"meaning": ",恩惠,感恩。", "cites": [{"t": "所识穷乏者得我欤。", "b": "《孟子·告子上》"}, {"t": "地广而不得者国危,兵强而凌敌者身亡。", "b": "《盐铁论·击之》"}]}, {"meaning": "助动词。能,能够。", "cites": [{"t": "孔子下,欲与之言,趋而避之,不得与之言。", "b": "《论语·微子》"}, {"t": "以是人多以书假余,余因得遍观群书。", "b": "宋濂《送东阳马生序》"}, {"t": "进退不得,为之奈何?", "b": "《吴子·应变》"}, {"t": "沛公军霸上,未得与项羽相见。", "b": "《史记·项羽本纪》"}]}, {"meaning": "得意,满足。", "cites": [{"t": "意气扬扬,甚自得也。", "b": "《史记·管晏列传》"}, {"t": "常使两情皆得,彼此俱畅。", "b": "《世说新语·文学》"}], "words": [{"w": "洋洋得意", "t": ""}]}, {"meaning": "看到。", "cites": [{"t": "林尽水源,便得一山。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "收获,心得。", "cites": [{"t": "古人之观于天地、山川、草木、虫鱼、鸟兽,往往有得。", "b": "宋·王安石《游褒禅山记》"}, {"t": "开郑有得,便欣然忘食。", "b": "《南史·陶潜传》"}]}, {"meaning": "德,道德,有德之人。", "cites": [{"t": "尚得推贤不失序。", "b": "《荀子》"}]}, {"meaning": "必须,应该。", "cites": [{"t": "君为我呼入,吾得兄事之。", "b": "《史记·项羽本纪》"}]}, {"meaning": "合适;正确。", "cites": [{"t": "于彼计则得。", "b": "马中锡《中山狼传》"}, {"t": "历古今之得失。", "b": "《汉书》"}]}]}, {"pinyin": "de", "defs": []}, {"pinyin": "děi", "defs": [{"meaning": "绝对必要或应当去做。", "cites": [{"t": "犹得备晨炊。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "有错误就得批评;做得好就得表扬", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2342wx','衔','1','xián','行','11','','[{"pinyin": "xián", "defs": [{"meaning": "口含。", "cites": [{"t": "蟾蜍衔之。", "b": "《后汉书·张衡传》"}], "words": [{"w": "燕子衔泥;衔环相报", "t": "衔环"}, {"w": "衔刀", "t": "口中叼刀"}, {"w": "衔土", "t": "口含泥土"}, {"w": "衔口垫背", "t": "古代一种殓葬习俗:给死人口含珠、玉或米。死尸褥下放钱。"}]}, {"meaning": "怀藏。", "cites": [{"t": "衔之次骨。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "衔恩", "t": "感恩"}, {"w": "衔悔", "t": "怀有悔恨之心"}, {"w": "衔匿", "t": "深藏在心里"}, {"w": "衔恤", "t": "心怀忧伤"}, {"w": "衔哀", "t": "心怀哀痛。"}]}, {"meaning": "奉接,接受。", "cites": [{"t": "贾昌衔保家活命之恩,无从报效。", "b": "《醒世恒言》"}], "words": [{"w": "衔命", "t": "奉行命令。"}]}, {"meaning": "把两物互相接起来或缚住。", "cites": [{"t": "且把粮车首尾衔,权做寨栅。", "b": "《水浒全传》"}]}, {"meaning": "包含,蕴含。", "cites": [{"t": "衔远山。", "b": "宋·范仲淹《岳阳楼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2343wx','盘','1','pán','皿','11','','[{"pinyin": "pán", "defs": [{"meaning": "(形声。从皿,般声。皿,盘碗一类器具。本义:盘子,浅而敞口的盛物器)。"}, {"meaning": "同本义。", "cites": [{"t": "及日中则如盘盂。", "b": "《列子·汤问》"}, {"t": "毛遂奉铜盘而跪进之楚王。", "b": "《史记·平原君虞卿列传》"}, {"t": "谁知盘中餐,粒粒皆辛苦。", "b": "唐·李绅《悯农》"}], "words": [{"w": "盘羞", "t": "盘盛的食品"}, {"w": "冷盘", "t": "盛在盘子里的凉菜"}, {"w": "茶盘", "t": "放茶壶茶杯的盘子"}, {"w": "盘儿", "t": "脸盘儿"}, {"w": "盘器", "t": "盘类器皿"}, {"w": "盘担", "t": "内装盘馔的礼盒担子。"}]}, {"meaning": "古代的一种盥洗用具。", "cites": [{"t": "沐用瓦盘。", "b": "《礼记·丧大记》"}], "words": [{"w": "盘匜", "t": "古代盥洗器皿盘与匜的并称。盘以承水,匜以注水。"}]}, {"meaning": "大石。", "cites": [{"t": "则国安於盘石。", "b": "《荀子·富国》"}, {"t": "所谓盘石之宗也。", "b": "《汉书·文帝纪》"}], "words": [{"w": "盘石桑苞", "t": "盘石,大石;桑苞,即苞桑,根深柢固的桑树。"}]}, {"meaning": "礼物。"}, {"meaning": "订婚时男方送给女方的彩礼。", "cites": [{"t": "盘里衣裳头面,我到屋里办得来。", "b": "《孽海花》"}]}, {"meaning": "系于腰间盛手巾等的小囊。", "cites": [{"t": "贝一女子,猛兽自后断其盘囊。", "b": "《晋书·邓攸传》"}]}, {"meaning": "围绕;缠绕。", "cites": [{"t": "则盘纡隐深。", "b": "《文选·嵇康·琴赋》"}, {"t": "虎踞龙盘今胜昔,天翻地覆慨而慷。", "b": "毛泽东《七律·人民解放军占领南京》"}], "words": [{"w": "盘锦", "t": "用金线在丝织物上盘出的图案"}, {"w": "盘陀石", "t": "高低不平的石头。盘陀:螺旋形"}, {"w": "盘缴", "t": "盘搅。花销"}, {"w": "盘步", "t": "通行"}, {"w": "盘踅", "t": "回旋,打转"}, {"w": "盘蛇", "t": "盘绕曲折貌。"}]}, {"meaning": "盘问,盘查。", "cites": [{"t": "且请先生和儿子出来相见,盘他一盘。", "b": "《醒世恒言》"}], "words": [{"w": "盘驳;盘诘", "t": "盘问"}, {"w": "盘考", "t": "盘察考问"}, {"w": "盘验", "t": "盘查检验"}, {"w": "盘辟", "t": "查问,辩驳。"}]}, {"meaning": "攀爬。", "cites": [{"t": "悄悄行至半山,见一株大树,就盘将上去。", "b": "《说岳全传》"}]}, {"meaning": "徘徊,逗留。"}, {"meaning": "盘曲,回绕。", "cites": [{"t": "水澹澹而盘纡兮。", "b": "宋玉《高唐赋》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2344wx','舶','1','bó','舟','11','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从舟,白声。本义:大船,海船) 同本义。", "cites": [{"t": "昔孙权装大船,名之曰“长安”亦曰大舶。", "b": "郦道元《水经注》"}], "words": [{"w": "舶物", "t": "用船舶运来的外国货物"}, {"w": "舶主", "t": "古代波斯国的别名。船舶的主人"}, {"w": "舶来", "t": "用船从国外运来;外来"}, {"w": "舶船", "t": "巨船。大船"}, {"w": "舶贾", "t": "国外来的商人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2345wx','船','1','chuán','舟','11','','[{"pinyin": "chuán", "defs": [{"meaning": "(形声。本义:水运工具。古称舟)。"}, {"meaning": "同本义。", "cites": [{"t": "船,舟也。", "b": "《说文》。段注:“古人言舟,汉人言船,毛以今语释古,故云舟即今之船也。”"}, {"t": "小曰舟,大曰船。", "b": "《说文义证》"}, {"t": "有渔父者,下船而来。", "b": "《庄子·渔父》"}, {"t": "便舍船,从口入。", "b": "陶潜《桃花源记》"}, {"t": "姑苏城外寒山寺,夜半钟声到客船", "b": "张继《枫桥夜泊》"}], "words": [{"w": "船坞", "t": "船厂;停泊、修理或制造船只的地方"}, {"w": "船把板", "t": "船主"}, {"w": "船不漏针", "t": "比喻绝无遗失"}, {"w": "船多不碍路", "t": "数量虽多,但互不妨碍"}, {"w": "船横芦篚嚣", "t": "轩然大波;闹出乱子"}, {"w": "船人", "t": "船夫。也作舩人"}, {"w": "船头", "t": "船的前部;船老大。"}]}, {"meaning": "用船运载。", "cites": [{"t": "蔡人告饥,船粟往哺。", "b": "韩愈《平淮西碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2346wx','舵','1','duò','舟','11','','[{"pinyin": "duò", "defs": [{"meaning": "(形声。从舟,它声。本义:船尾用以控制行向的装置) 同本义。也作柁、杕", "words": [{"w": "把舵", "t": "掌舵。也指应用偏航运动原理制作的飞机末尾部分的附着有纹摺的,或可活动的辅助机翼,在飞行时用来控制其水平动向"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2347wx','斜','1','xié','斗','11','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从斗,余声。本义:用斗倒出)。"}, {"meaning": "舀出。", "cites": [{"t": "斜,抒也。", "b": "《说文》"}], "words": [{"w": "斜酒", "t": "舀酒。"}]}, {"meaning": "侧着移动,向偏离正中或正前方的方向移动。", "cites": [{"t": "门子才斜签着坐下。", "b": "《葫芦僧判断葫芦案》"}, {"t": "飞腾暮景斜。", "b": "《杜位宅守岁》"}], "words": [{"w": "斜签", "t": "侧着身子"}, {"w": "斜躺", "t": "斜着下垂。"}]}, {"meaning": "不正,歪斜。", "cites": [{"t": "明月斜挂。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "斜风细雨。", "b": "唐·张志和《渔歌子》"}, {"t": "青山郭外斜。", "b": "唐·孟浩然《过故人庄》"}, {"t": "烟斜雾横。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "斜月三星", "t": "心字的隐喻"}, {"w": "斜射路", "t": "抄近路在田中踩踏出来的斜道"}, {"w": "斜柯", "t": "倾侧;敲侧"}, {"w": "斜刺", "t": "斜刺里"}, {"w": "斜径", "t": "歪斜的小路。"}]}, {"meaning": "不专诚。", "cites": [{"t": "又想:“师父万一心斜,走到西方,亦无用处。”", "b": "《西游记》"}]}, {"meaning": "巷。", "cites": [{"t": "长安有狭斜,狭斜不容车。", "b": "古乐府《长安有狭斜行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2348wx','盒','1','hé','皿','11','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从皿,合声。从“皿”,表示与器皿有关。本义:底盖相合的盛器) 同本义。", "cites": [{"t": "合,器名。", "b": "《广韵》"}, {"t": "合子,盛物器。", "b": "《正韵》"}], "words": [{"w": "盒仗", "t": "礼盒挑子"}, {"w": "盒礼", "t": "盒装的礼物"}, {"w": "盒菜", "t": "盒子包装的副食品"}, {"w": "盒担", "t": "盒形盛物器,叠合为两组,用扁担挑起输送。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2349wx','鸽','1','gē','鸟','11','','[{"pinyin": "gē", "defs": [{"meaning": "(形声。从鸟,合声。本义:鸽子) 同本义。", "cites": [{"t": "鸽,鸠属。从鸟,合声。形同勃姑。", "b": "《说文》"}], "words": [{"w": "野鸽;家鸽;信鸽;鸽绕", "t": "指禅通凌虚之境,有如鸽子绕行天空一般"}, {"w": "鸽竿", "t": "用鸽子作饵的捕鹰长竿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2350wx','敛','1','liǎn','攵','11','','[{"pinyin": "liǎn", "defs": [{"meaning": "(形声。从攴(pū),佥(qiān)。本义:收集,聚集)。"}, {"meaning": "同本义(收集的对象是物,常是财物)。", "cites": [{"t": "敛,收也。", "b": "《说文》"}, {"t": "既射则敛之。", "b": "《周礼·夏官·缮人》。注:“敛,藏也。”"}, {"t": "狗彘食人之食不知敛。", "b": "《汉书·食货志》"}, {"t": "鞭挞其夫家,聚敛贡城阙。", "b": "杜甫《自京赴奉先县咏怀五百字》"}, {"t": "敛赀财以送其行。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "敛局", "t": "邀人聚赌,从中抽头"}, {"w": "敛衣", "t": "聚集零碎布头所制成的衣服。"}]}, {"meaning": "收获。", "cites": [{"t": "自种自敛,服箱以走。", "b": "柳宗元《牛赋》"}], "words": [{"w": "敛材", "t": "采集可食的百草根实"}, {"w": "敛实", "t": "收割庄稼"}, {"w": "敛获", "t": "收获。"}]}, {"meaning": "征收。", "cites": [{"t": "豹因重敛百姓。", "b": "《韩非子·外储说左下》"}, {"t": "邺三老、廷椽尝岁赋敛百姓,收取其钱得数百万。—《史记·滑稽列传》", "b": ""}, {"t": "赋敛之毒有甚是蛇。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "稍敛众以去。", "b": "明·高君《书博鸡者事》"}, {"t": "成不敢敛户口。", "b": "《聊斋志异·促织》"}], "words": [{"w": "征敛", "t": "旧指官府向民间征捐敛财"}, {"w": "聚敛", "t": "重税搜刮"}, {"w": "敛法", "t": "收税的准则。"}]}, {"meaning": "收缩;退缩。", "cites": [{"t": "秦、楚合而为一以临韩,韩必敛手。", "b": "《史记·春申君列传》"}]}, {"meaning": "如又:敛额(皱眉);敛退(退缩);敛策(收束马鞭。比喻隐退不仕);敛手(缩手不敢乱动)。"}, {"meaning": "入殓。", "cites": [{"t": "衣尸棺曰敛。", "b": "《释名·释丧制》"}, {"t": "敛般,请以机封。", "b": "《礼记·檀弓下》。注:“敛,下棺于椁。”"}, {"t": "桐棺足以周身,外椁足以周棺,敛形悬封,濯衣幅巾。", "b": "《后汉书·周磐传》"}, {"t": "醵金为敛。", "b": "清·张廷玉《明史》"}], "words": [{"w": "敛殡", "t": "入殓而殡葬"}, {"w": "敛藏", "t": "犹敛葬"}, {"w": "敛葬", "t": "入殓安葬"}, {"w": "敛形", "t": "衣覆其形"}, {"w": "敛埋", "t": "收敛埋葬"}, {"w": "敛衾", "t": "古代大殓时盖尸体的被子"}, {"w": "敛席", "t": "盖尸席。"}]}, {"meaning": "收敛,约束言行。", "cites": [{"t": "为敛威去。", "b": "清·张廷玉《明史》"}], "words": [{"w": "敛戢", "t": "收敛,止息"}, {"w": "敛抑", "t": "收敛节制"}, {"w": "敛马", "t": "勒马。"}]}, {"meaning": "整肃;整理。", "cites": [{"t": "诸侯敛衽。", "b": "桓宽《盐铁论》"}], "words": [{"w": "敛甲", "t": "犹束甲。整理盔甲,表示准备战斗"}, {"w": "敛声屏气", "t": "毫无声音,不敢出大气"}, {"w": "敛衽", "t": "提起衣襟夹于带间,表示恭敬。"}]}, {"meaning": "赋税。", "cites": [{"t": "省刑薄敛。", "b": "陈亮《上孝宗皇帝第一书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2351wx','悉','1','xī','心','11','','[{"pinyin": "xī", "defs": [{"meaning": "(会意。从心,从采。采（biàn）,辨别。心中加以辨别,很详细。本义:详尽) 同本义。", "cites": [{"t": "悉,详尽也。", "b": "《说文》"}, {"t": "悉,尽也。", "b": "《尔雅》"}, {"t": "占不悉。", "b": "《史记·平准书》。索隐:“尽也。”"}, {"t": "时上所问禽兽簿甚悉。", "b": "《汉书·张释之传》"}, {"t": "至孅至悉。", "b": "汉·贾谊《论积贮疏》"}, {"t": "词不悉心。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "纤悉", "t": "详细;详尽"}, {"w": "详悉", "t": "详细而全面"}, {"w": "悉数", "t": "一一列举。"}]}, {"meaning": "详尽地叙述。", "cites": [{"t": "书不能悉意。", "b": "汉·司马迁《报任安书》"}]}, {"meaning": "详尽的知道,了解。", "cites": [{"t": "文亦宜然,随时变改,难可详悉。", "b": "南朝梁·萧统《文选》序"}, {"t": "亟相亮其悉朕意。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "欣悉", "t": "高兴地详尽了解"}, {"w": "洞悉", "t": "很清楚地知道"}, {"w": "熟悉", "t": "知道得很清楚"}, {"w": "来函敬悉;探悉;惊悉;详悉", "t": "详细知道。"}]}, {"meaning": "尽其所有。", "cites": [{"t": "以公之与民已悉矣。", "b": "《谷梁传·宣公十五年》。注:“谓尽其力也。”"}, {"t": "悉浮以沿江。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "悉锐", "t": "尽其全部精锐"}, {"w": "悉甲", "t": "尽其甲兵"}, {"w": "悉索", "t": "尽其所有;搜括。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2352wx','欲','1','yù','欠','11','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从欠,谷(yù)声。“欠”表示有所不足,故产生欲望。本义:欲望;嗜欲) 同本义。", "cites": [{"t": "欲,贪欲也。", "b": "《说文》。俗字亦作慾。"}, {"t": "欲者,情之应也。", "b": "《荀子·正名》"}, {"t": "六欲。", "b": "《吕氏春秋·贵生》。注:“生死耳目口鼻也。”"}, {"t": "以欲竭其精。", "b": "《论语》。注:“乐色曰欲。”"}, {"t": "然则诸侯之地有限,暴秦之欲无厌。", "b": "苏洵《六国论》"}, {"t": "厉而不刚者,则欲夺之也。", "b": "三国魏·刘劭《人物志》"}], "words": [{"w": "欲令智昏", "t": "欲火使人丧失理智"}, {"w": "欲障", "t": "嗜欲"}, {"w": "欲海", "t": "佛教语。情欲令人迷本性,沉沦于生死大海"}, {"w": "欲界", "t": "佛教语。三界之一,在色界之下,包括欲天、人间和地狱等"}, {"w": "欲心", "t": "情欲之心"}, {"w": "欲事", "t": "男女情欲之事"}, {"w": "欲尘", "t": "佛教语。佛家谓财、色、食、名、睡五欲污身如尘埃,故称。"}]}, {"meaning": "想要;希望。", "cites": [{"t": "无欲速,无见小利。欲速,则不达。", "b": "《论语·子路》"}, {"t": "欲洁其身而乱大伦。", "b": "《论语·微子》"}, {"t": "晋鄙…曰:“…今单车来代之,何如哉?”欲无听。", "b": "《史记·魏公子列传》"}, {"t": "孤岂欲卿治经为博士耶!", "b": "《资治通鉴·汉纪》"}, {"t": "故人远我,欲以火器困我也。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "欲踵", "t": "想要放效"}, {"w": "欲待", "t": "想要、打算"}, {"w": "欲人勿知,莫若勿为", "t": "想要别人不知道,最好自己不去做"}, {"w": "欲速则不达", "t": "性急求快反而不能达到目的"}, {"w": "欲益反损", "t": "想把事情做好,结果反而弄坏。"}]}, {"meaning": "爱好;喜爱。", "cites": [{"t": "欲,爱也。", "b": "《增韵》"}, {"t": "人情欲厚恶薄。", "b": "《论衡·案书》"}, {"t": "故卤莽其性者,欲恶之孽,为性萑苇蒹葭。", "b": "《庄子·则阳》"}, {"t": "天下之欲疾其君者,皆欲赴诉于王。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2353wx','彩','1','cǎi','彡','11','','[{"pinyin": "cǎi", "defs": [{"meaning": "(形声。从彡(shān),采声。从“彡”表示与图画、文饰相关。本义:文采,文章才华)。"}, {"meaning": "同本义。", "cites": [{"t": "延之与陈郡谢灵运俱以词彩齐名。", "b": "《宋书·颜延之传》"}]}, {"meaning": "彩色的丝织品。又作“綵”。", "cites": [{"t": "杂彩三百匹,交广市鲑珍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "彩仗", "t": "彩饰的仪仗"}, {"w": "剪彩;张灯结彩", "t": ""}]}, {"meaning": "指某些赌博、竞赛等赢得的财物。", "cites": [{"t": "大博争雄好彩来,全盘一掷万人开。", "b": "—李白《送外甥郑灌从军》"}], "words": [{"w": "彩战", "t": "指博戏争胜"}, {"w": "中彩;得彩;彩品", "t": "竞赛的奖品。"}]}, {"meaning": "彩色,各种颜色。", "cites": [{"t": "朝辞白帝彩云间。", "b": "李白《早发白帝城》"}], "words": [{"w": "五彩;彩章", "t": "彩色涂饰"}, {"w": "彩错", "t": "色彩交错"}, {"w": "彩服", "t": ""}]}, {"meaning": "得好运。", "cites": [{"t": "且休提这恩德无涯,单则是子母团圆,大古里彩。", "b": "元·关汉卿《蝴蝶梦》"}], "words": [{"w": "彩气", "t": "吉利的兆头"}, {"w": "彩头", "t": "好运道的预兆;又指竞赛赢得的奖品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2354wx','领','1','lǐng','页','11','','[{"pinyin": "lǐng", "defs": [{"meaning": "(形声。从页(xié),令声。从“页”,表示与头有关。本义:脖子)。"}, {"meaning": "同本义。", "cites": [{"t": "领,项也。", "b": "《说文》"}, {"t": "领,项也。", "b": "《广雅·释亲》"}, {"t": "领如蝤蛴。", "b": "《诗·卫风·硕人》"}, {"t": "缅然引领南望。", "b": "《国语·楚语上》"}, {"t": "及君之嗣也,我君景公引领西望曰:“庶抚我乎!”", "b": "《左传》"}], "words": [{"w": "领门儿", "t": "衣领;领口"}, {"w": "领鬃", "t": "鬃毛"}, {"w": "领颚", "t": "下巴"}, {"w": "领腰", "t": "脖子与腰部"}, {"w": "领圈", "t": "项圈。"}]}, {"meaning": "领子,衣领。", "cites": [{"t": "若挈裘领。", "b": "《荀子·劝学》。"}], "words": [{"w": "领抹", "t": "领系、领戏。外衣领上的系巾"}, {"w": "领口;领盘儿", "t": "托领"}, {"w": "领章;领结", "t": ""}]}, {"meaning": "山道,山坡", "cites": [{"t": "舆轿而逾领。", "b": "《汉书·严助传》"}]}, {"meaning": "统领,居上领导指挥。", "cites": [{"t": "各领万人,与备俱进。", "b": "《三国志·吴主传》"}], "words": [{"w": "领盘", "t": "主持定婚仪式"}, {"w": "领家的", "t": "妓院老鸨"}, {"w": "领护", "t": "统治"}, {"w": "领御", "t": "统率支配"}, {"w": "领衔;领袖", "t": ""}]}, {"meaning": "带领;引导。", "cites": [{"t": "识以领之,方能中鹄。", "b": "清·袁枚《续诗品》"}], "words": [{"w": "领道", "t": "在前引路"}, {"w": "领首", "t": "带头"}, {"w": "领工", "t": "带领从事劳动。"}]}, {"meaning": "兼任。", "cites": [{"t": "为尚书,领行营节度使。", "b": "柳宗元《段太尉逸事状》"}]}, {"meaning": "治理。", "cites": [{"t": "领恶而全好者欤。", "b": "《礼记·仲尼燕居》"}], "words": [{"w": "领牧", "t": "治理,管辖"}, {"w": "领理", "t": "治理"}, {"w": "领职", "t": "守职,治理政事"}, {"w": "领料", "t": "管理、照料。"}]}, {"meaning": "理解, 懂得。", "cites": [{"t": "领父子君臣之节。", "b": "《礼记·乐记》"}], "words": [{"w": " 领悟; 领略;领解;领会;领览", "t": "领会,理解"}, {"w": "领握", "t": "领会掌握"}, {"w": "领悟", "t": "明白,理解。"}]}, {"meaning": "接受, 受取。", "cites": [{"t": "李典领命,自去典兵埋伏。", "b": "《三国演义》"}], "words": [{"w": "领命", "t": "照指示办"}, {"w": "领诺", "t": "答应,领命"}, {"w": "领纸", "t": "向公家领取钱物的收据。"}]}, {"meaning": "美好。", "cites": [{"t": "君子纯终领闻。", "b": "《汉书·扬雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2355wx','脚','1','jiǎo jué','月','11','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从肉,却声。本义:胫,小腿)。"}, {"meaning": "同本义。", "cites": [{"t": "脚,胫也。", "b": "《说文》"}, {"t": "捶笞膑脚。", "b": "《荀子·正论》"}], "words": [{"w": "脚膀", "t": "指小腿"}, {"w": "脚胫", "t": "小腿"}, {"w": "腿杆", "t": "方言。腿。"}]}, {"meaning": "足的别称。", "cites": [{"t": "雄兔脚扑朔。", "b": "《乐府诗集·木兰诗》"}, {"t": "脚著谢公屐。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "脚炉", "t": "烘脚的小铜炉"}, {"w": "脚踏", "t": "炕前供垫脚用的矮凳"}, {"w": "脚踪", "t": "足迹"}, {"w": "脚驴", "t": "供人雇用骑行的驴子。"}]}, {"meaning": "某物的底座(作为它的支承部件)。", "cites": [{"t": "水面初平云脚低。", "b": "唐·白居易《钱塘湖春行》"}], "words": [{"w": "根脚;杯脚;山脚;墙脚;脚灯;脚底下人", "t": ""}]}, {"meaning": "帮手。", "cites": [{"t": "我又不能自去,少不得要他作脚。", "b": "《红楼梦》"}]}]}, {"pinyin": "jué", "defs": [{"meaning": "传统戏曲中的人物类型。", "cites": [{"t": "崛,山短高也。", "b": "《说文》"}, {"t": "崛,特立也。", "b": "《埤苍》"}, {"t": "神明崛其特起。", "b": "张衡《西京赋》"}, {"t": "洪台崛其独出兮。", "b": "《文选·扬雄·甘泉赋》"}], "words": [{"w": "脚儿", "t": "也作“角儿”、“脚色”"}, {"w": "脚色", "t": "出身履历;演员;人物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2356wx','脖','1','bó','月','11','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从肉,孛(bèi)声。本义:颈项。俗称脖子)。"}, {"meaning": "同本义。", "cites": [{"t": "青龙偃月刀,九九八十一斤,脖子里着一下。", "b": "关汉卿《单刀会》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2357wx','脯','1','fǔ pú','月','11','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从肉,甫声。本义:干肉)。"}, {"meaning": "同本义。", "cites": [{"t": "吾子淹久于敝邑,唯是脯资饩牵竭矣。", "b": "《左传·僖公三十三年》"}, {"t": "谓加姜桂锻治者谓之,不加姜桂以盐干之者谓之脯。", "b": "《周礼·天官》注"}], "words": [{"w": "肉脯;牛脯;脯饩", "t": "干肉和生肉"}, {"w": "脯糗", "t": "干肉和干粮"}, {"w": "脯腊", "t": "干肉"}, {"w": "脯枣", "t": "干肉和枣类果品。"}]}, {"meaning": "制干肉。", "cites": [{"t": "辜谏者,脯诸侯,俎方伯,剖人心,破人胫。", "b": "《抱朴子》"}], "words": [{"w": "脯醢", "t": "古代把人做成肉干或剁成肉酱的酷刑。"}]}]}, {"pinyin": "pú", "defs": [{"meaning": "", "words": [{"w": "脯子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2358wx','豚','1','tún','豕','11','','[{"pinyin": "tún", "defs": [{"meaning": "(会意。小篆作字形从彖省。彖(shǐ),猪。从手(又)持肉,用于祭祀。本义:小猪,猪)。"}, {"meaning": "同本义。", "cites": [{"t": "豚,小豕也。", "b": "《说文》"}, {"t": "猪其子谓之豚。", "b": "《方言八》"}, {"t": "豚鱼吉。", "b": "《易·中孚》"}, {"t": "豚曰腯肥。", "b": "《礼记·曲礼》"}, {"t": "鸡豚狗彘之畜。", "b": "《孟子·梁惠王上》"}, {"t": "郑县人卖豚,人问其价。", "b": "《韩非子·外储说左下》"}, {"t": "阳货欲见孔子,孔子不见,归孔子豚。", "b": "《论语·阳货》"}], "words": [{"w": "豚子", "t": "谦称自己的儿子"}, {"w": "豚犬", "t": "猪与狗"}, {"w": "豚鱼", "t": "豚和鱼。泛指无知的动物"}, {"w": "豚犊", "t": "愚蠢如猪的小孩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2359wx','脸','1','liǎn','月','11','','[{"pinyin": "liǎn", "defs": [{"meaning": "(形声。从肉,佥(qiān)声。古代表示人的整个面部用“面”。“脸”字在魏晋时期才出现,只表示两颊的上部,到了唐宋时期,口语中才用“脸”表示整个面部。本义:两颊的上部)。"}, {"meaning": "同本义。", "cites": [{"t": "蛾眉与曼脸,见此空愁人。", "b": "吴均《小垂手》"}, {"t": "满面黄沙满鬓风,眉销残黛脸销红。", "b": "白居易《昭君怨》"}, {"t": "头圆筋骨紧,两脸明且光。", "b": "杜牧《冬至日寄小侄阿宜》"}], "words": [{"w": "脸蛋", "t": "脸的两旁部分"}, {"w": "脸巴子", "t": "面颊"}, {"w": "脸上", "t": "面颊之上。"}]}, {"meaning": "脸面,人头的前部,包括下巴、嘴、鼻、颊、眼,且通常包括前额。", "cites": [{"t": "脸波春傍窈娘堤。", "b": "白居易《天津桥》"}, {"t": "你看你的脸…尽是血,我都不认识你了。", "b": "曹禺《雷雨》"}]}, {"meaning": "指某些物体的前部。", "cites": [{"t": "东西房全是敞脸的,是存车的所在。", "b": "老舍《骆驼祥子》"}], "words": [{"w": "鞋脸;城门脸;脸戏儿", "t": "鞋面子"}, {"w": "脸壳子", "t": "方言。喻指虚伪的表面"}, {"w": "门脸儿", "t": "城门附近的地方;商店的门面。"}]}, {"meaning": "脸色;脸上的表情。", "cites": [{"t": "谁知你转背儿著他人也,又另是一样脸。", "b": "清·吴骞《扶风传信录》"}], "words": [{"w": "急赤白脸", "t": "心里着急,脸色难看"}, {"w": "哭丧着脸;涎着脸;绷脸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2360wx','脱','1','tuō','月','11','','[{"pinyin": "tuō", "defs": [{"meaning": "(形声。从肉,兑(duì)声。本义:肉去皮骨)。"}, {"meaning": "同本义。", "cites": [{"t": "脱,消肉臞也。", "b": "《说文》"}, {"t": "肉去骨曰脱。", "b": "《尔雅》"}, {"t": "肉曰脱之,鱼曰作之,枣曰新之。", "b": "《礼记·内则》"}, {"t": "其状若脱。", "b": "《列子·天瑞》"}, {"t": "筋骨尽脱矣。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "离;脱离。", "cites": [{"t": "则脱然愈。", "b": "《公羊传·昭公十九年》。注:“疾除貌也。”"}, {"t": "言脱于口。", "b": "《管子·霸形》"}, {"t": "蠃蚌脱壳。", "b": "[英]赫胥黎著、严复译《天演论》"}, {"t": "鱼不可脱于深渊。", "b": "《韩非子·喻老》"}, {"t": "善建不拔,善抱不脱。", "b": ""}], "words": [{"w": "脱祸", "t": "摆脱祸害"}, {"w": "脱了干系;脱凡", "t": "脱离凡俗"}, {"w": "脱尸", "t": "灵魂脱离尸体"}, {"w": "脱出", "t": "离出"}, {"w": "脱清", "t": "脱离干系"}, {"w": "脱卯", "t": "榫头离开卯眼"}, {"w": "脱难", "t": "脱离患难。"}]}, {"meaning": "脱落;掉落。", "cites": [{"t": "霜露既降,木叶尽脱。", "b": "宋·苏轼《后赤壁赋》"}, {"t": "草拂之而色变,木遭之而叶脱。", "b": "欧阳修《秋声赋》"}], "words": [{"w": "脱羽;脱毛;脱叶", "t": ""}]}, {"meaning": "脱下,取下。", "cites": [{"t": "脱衣就功。", "b": "《国语·齐语》"}, {"t": "虎贲之士脱剑。", "b": "《孔子家语·辨乐》"}, {"t": "揽裙脱丝履。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "脱我战时袍。", "b": "《乐府诗集·木兰诗》"}, {"t": "脱帽著帩头。", "b": "《乐府诗集·陌上桑》"}, {"t": "脱械居监外。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "脱巾", "t": "脱下头巾"}, {"w": "脱白", "t": "脱去白衣,进入仕途"}, {"w": "脱肩", "t": "脱衣露肩"}, {"w": "脱械", "t": "去掉刑具"}, {"w": "脱脚", "t": "脱去鞋袜"}, {"w": "脱褐", "t": "脱去粗衣"}, {"w": "脱素穿色", "t": "脱掉白色的孝服,换上艳丽的服装。表示守孝期已过"}, {"w": "脱白挂绿", "t": "脱去便装,换上官服。指已登科及第"}, {"w": "脱剥", "t": "脱掉;剥去。"}]}, {"meaning": "逃。", "cites": [{"t": "幸得脱矣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "自度不得脱。", "b": "宋·文天祥《指南录后序》"}, {"t": "脱京口。", "b": ""}, {"t": "脱笼之鹄。", "b": "明·袁宏道《满井游记》"}, {"t": "脱人于死。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "脱去", "t": "逃走"}, {"w": "脱走", "t": "脱身逃走或隐遁"}, {"w": "脱免", "t": "脱身免祸或免灾"}, {"w": "脱命", "t": "脱逃得命"}, {"w": "脱监", "t": "脱狱。越狱"}, {"w": "脱樊", "t": "逃出樊笼"}, {"w": "脱网", "t": "漏网,逃脱"}, {"w": "脱窜", "t": "逃窜"}, {"w": "脱归", "t": "脱身逃归"}, {"w": "脱放", "t": "放走;释放。"}]}, {"meaning": "失去;散落,缺漏。", "cites": [{"t": "脱去章句,是以难知。", "b": "《抱朴子·钧世》"}], "words": [{"w": "脱气", "t": "泄气;没出息"}, {"w": "脱光", "t": "日月失去光辉"}, {"w": "脱色", "t": "失色"}, {"w": "脱简", "t": "原指简片散失。后泛指书本有缺页或文字有脱漏"}, {"w": "脱角", "t": "折脱兽角。"}]}, {"meaning": "照着描画;临摹。", "cites": [{"t": "彩笔描画我娘形,像貌仪容脱似真。", "b": "王仲文《王祥卧冰》"}]}, {"meaning": "过去。", "cites": [{"t": "老子曰:“夫巧知神圣之人,吾自以为脱焉。”", "b": "《庄子·天道》"}]}, {"meaning": "冒出,说出。", "cites": [{"t": "颖脱而出。", "b": "唐·柳宗元《至小丘西小石潭记》"}]}, {"meaning": "指病情突变、阴阳相离而致生命垂危的病理及其症候。", "cites": [{"t": "脱之名,惟阳气骤越,阴阳相离,汗出如油,六脉垂绝,一时急迫之症,方名为脱。", "b": "《临证指南医案·脱》"}]}, {"meaning": "又指中风脱证。", "cites": [{"t": "凡中风昏倒,…最要分别闭与脱二证明白。", "b": "《医宗必读》"}]}, {"meaning": "表示频度,相当于“偶尔”。", "cites": [{"t": "事既未然,脱可免祸。", "b": "《后汉书》"}]}, {"meaning": "表示推断,相当于“或者”。", "cites": [{"t": "脱时过,止寒温而已。", "b": "《世说新语》"}]}, {"meaning": "表示假设,相当于“倘若”。", "cites": [{"t": "脱获回耗。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "脱使", "t": "犹倘使。表示假设"}, {"w": "脱或", "t": "倘或"}, {"w": "脱若", "t": "倘若。"}]}, {"meaning": "洒脱;放任。", "cites": [{"t": "舒而脱脱兮,无感我帨兮。", "b": "《诗·召南·野有死麇》"}, {"t": "则脱然而喜矣。", "b": "《淮南子·精神》"}], "words": [{"w": "脱然", "t": "轻松愉快、无拘无束的样子"}, {"w": "脱直", "t": "爽快,耿直。"}]}, {"meaning": "疏忽,轻漫。", "cites": [{"t": "无礼则脱。", "b": "《左传·僖公三十二年》"}, {"t": "入险自脱。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2361wx','象','1','xiàng','豕','11','','[{"pinyin": "xiàng", "defs": [{"meaning": "(象形。甲骨文字形,突出其长鼻。本义:大象,一种哺乳动物)。"}, {"meaning": "象科的,特别是象属(Elephas)和非洲象属(Loxodonta)的体型极大而粗重的几乎无毛的四足动物。", "cites": [{"t": "象,南越大兽,长鼻牙,三年一乳。像鼻牙四足尾 之形。", "b": "《说文》"}, {"t": "祷过之山多象。", "b": "《山海经·南山经》"}, {"t": "穷奇象犀。", "b": "《汉书·司马相如传》"}, {"t": "其民乘象以战。", "b": "《汉书·张骞传》"}, {"t": "元龟象齿,大赂南金。", "b": "《诗·鲁颂·泮水》"}, {"t": "象有齿以焚其身。", "b": "《左传·襄公二十四年》"}], "words": [{"w": "象口", "t": "象状香炉口"}, {"w": "象王", "t": "象中最大者,佛家喻佛。"}]}, {"meaning": "象牙的省称。", "cites": [{"t": "南方之美者,有梁山之犀象焉。", "b": "《尔雅》。注:“象牙骨。”"}, {"t": "佩其象揥。", "b": "《诗·狂风·葛屦》。传:“象揥所以为饰。”"}, {"t": "用两象尊。", "b": "《周礼·司尊彝》。司农注:“以象骨饰尊。”"}, {"t": "持一象笏至(象笏,象牙做的笏。笏,封建时代臣子上朝用的手板,有事可以记在上面,备忘)。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "象床", "t": "象牙装饰的床"}, {"w": "象路", "t": "以象牙为饰的车"}, {"w": "象管", "t": "以象牙为饰的笔"}, {"w": "象箸", "t": "象牙筷子。"}]}, {"meaning": "人的外貌。", "cites": [{"t": "象恭滔天。", "b": "《书·尧典》"}], "words": [{"w": "丑象", "t": ""}]}, {"meaning": "肖像,用水墨画、油画、素描或其他绘画手法描绘的人面部的像。", "cites": [{"t": "上瞻兮遗象,下临兮泉壤。", "b": "潘岳《寡妇赋》"}, {"t": "尝图裴楷象,颊上加三毛,观者觉神明殊胜。", "b": "《晋书·顾恺之传》"}, {"t": "往往留象。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "绘象祀之。", "b": "清·张廷玉《明史》"}], "words": [{"w": "象教", "t": "佛教的别称。释加牟尼去世后,佛门弟子刻木为佛、教化众生,故名"}, {"w": "象设", "t": "原指佛像。泛指遗像。"}]}, {"meaning": "象征。", "cites": [{"t": "白者西方之色,刑戮之象也。", "b": "韩愈《为宰相贺白龟状》"}], "words": [{"w": "征象;象表", "t": "征象"}, {"w": "象兆", "t": "征兆。"}]}, {"meaning": "形状;样子;景象。", "cites": [{"t": "杌陧之象。", "b": "孙文《< 黄花冈七十二烈士事略> 序》"}], "words": [{"w": "万象", "t": "宇宙间的一切景象。"}]}, {"meaning": "法,法令。", "cites": [{"t": "象以典刑。", "b": "《虞书》。传:“法也。”"}, {"t": "设象以为民纪,式权以相应。", "b": "《国语》"}]}, {"meaning": "道理。", "cites": [{"t": "执大象,天下往。", "b": "《老子》"}], "words": [{"w": "脉象;病象", "t": ""}]}, {"meaning": "假借为“像”。类似;好像。", "cites": [{"t": "见乃谓之象。又,象也者,像此者也。", "b": "《易·系辞》"}, {"t": "象者,各辨一及之义者也。", "b": "《易·略例》"}, {"t": "物生而后有象。", "b": "《左传·僖公十五年》"}, {"t": "天象盖笠。", "b": "《周髀算经》"}, {"t": "女必象汝。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "象意", "t": "如意"}, {"w": "活象;极象;象恭", "t": "貌似恭敬"}, {"w": "象肖", "t": "德业与先人相似"}, {"w": "象貌", "t": "像事物的容貌"}, {"w": "象龚", "t": "貌似恭敬。"}]}, {"meaning": "摹拟。", "cites": [{"t": "千变万化,事各缪形,随色象类,曲得其情。", "b": "《鲁灵光殿赋》"}, {"t": "因势象形。", "b": "明·魏学洢《核舟记》"}, {"t": "赫赫可象。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "象体", "t": "量体"}, {"w": "象生", "t": "纸、棉糊扎成的人物形象,用于祭祀或作为玩具"}, {"w": "象模象样", "t": "认真地"}, {"w": "象眼块", "t": "菱形。"}]}, {"meaning": "描绘。", "cites": [{"t": "公在荆州,或象其义,白须红颜,谓公方壮。", "b": "《王荆州画像赞》"}], "words": [{"w": "象物", "t": "描摹物象"}, {"w": "象说", "t": "描摹,解说。"}]}, {"meaning": "效法。", "cites": [{"t": "人君为饮食为此,故左右象之。", "b": "《墨子》"}], "words": [{"w": "象贤", "t": "效法先人的贤德。"}]}, {"meaning": "想像。", "cites": [{"t": "故诸人之所以意想者,皆谓之象也。", "b": "《韩非子》"}], "words": [{"w": "象事", "t": "想像事情。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2362wx','够','1','gòu','夕','11','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从多,句(gōu)声。本义:聚,多) 同本义。", "cites": [{"t": "繁富夥够,非可单究。", "b": "晋·左思《魏都赋》"}], "words": [{"w": "够使", "t": "够多。"}]}, {"meaning": "手等达到,触及。", "cites": [{"t": "[鸣凤]伸手去摘,但是她的身子短了一点,够不着。", "b": "巴金《家》"}], "words": [{"w": "够不着", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2363wx','逸','1','yì','辶','11','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。从辵(chuò)兔。兔子善于奔逃。本义:逃跑)。"}, {"meaning": "同本义。", "cites": [{"t": "逸,失也。从辵兔,兔谩訑善逃也。", "b": "《说文》"}, {"t": "随侯逸。", "b": "《左传·桓公八年》。注:“逸,逃也。”"}, {"t": "马逸不能止。", "b": "《国语·晋语五》。注:“逸,奔也。”"}, {"t": "取之以逸逃于褒。", "b": "《国语·郑语》。注:“逸,亡也。”"}, {"t": "无教逸欲有邦。", "b": "《书·皋陶谟》"}, {"t": "见一赤兔,每搏辄逸。", "b": "《北史》"}], "words": [{"w": "逸犯", "t": "逃犯"}, {"w": "逸亡", "t": "逃亡"}, {"w": "逸窜", "t": "逃窜"}, {"w": "逸盗", "t": "在逃的盗匪"}, {"w": "逸禽", "t": "逃逸之鸟"}, {"w": "逸马", "t": "奔逃的马"}, {"w": "逸匪", "t": "指在逃的匪徒"}, {"w": "逸飞", "t": "指漏网的鸟"}, {"w": "逸逃", "t": "逃亡。"}]}, {"meaning": "奔跑。", "cites": [{"t": "马逸不能止。", "b": "《左传·成公二年》"}, {"t": "逸,奔也。", "b": "《玉篇》"}, {"t": "彘逸出于窦中,马退而却。", "b": "《韩非子·外储说右下》"}, {"t": "疾逸道左。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "逸踊", "t": "犹奔跑"}, {"w": "逸尘", "t": "马奔跑时扬起的尘土"}, {"w": "逸骑", "t": "奔跑的马"}, {"w": "逸骏", "t": "善奔驰的马"}, {"w": "逸驰", "t": "犹奔驰"}, {"w": "逸象", "t": "奔走的象"}, {"w": "逸兔", "t": "奔走的兔"}, {"w": "逸走", "t": "奔跑。"}]}, {"meaning": "超越。", "cites": [{"t": "亮少有逸群之才。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "逸才", "t": "超人的才智"}, {"w": "逸足", "t": "比喻才能超越出众的人"}, {"w": "逸伦", "t": "超越同辈"}, {"w": "逸德", "t": "马有超群的禀性"}, {"w": "逸艺", "t": "高超的技艺"}, {"w": "逸侪", "t": "超过同辈"}, {"w": "逸操", "t": "高洁的情操"}, {"w": "逸品", "t": "超越流俗的艺术修养或艺术品"}, {"w": "逸珠", "t": "稀世难求的珍珠。比喻人有超绝凡常的嘉德"}, {"w": "逸格", "t": "超越流俗的高尚格调。"}]}, {"meaning": "释放;从约束、禁闭、奴役下释放出来。", "cites": [{"t": "乃逸楚囚。", "b": "《左传》"}], "words": [{"w": "逸水", "t": "犹洪水。"}]}, {"meaning": "隐逸,退出社会而隐居起来。", "cites": [{"t": "兴灭国,继绝世,举逸民,天下之民归心焉。", "b": "《论语》"}], "words": [{"w": "逸士", "t": "隐居山林的读书人"}, {"w": "逸妻", "t": "遁世隐士的妻子"}, {"w": "逸迹", "t": "犹遁迹。指隐居"}, {"w": "逸彦", "t": "遁世隐居的才德之士"}, {"w": "逸叟", "t": "遁世隐居的老人"}, {"w": "逸伏", "t": "犹隐伏。"}]}, {"meaning": "散失,亡失。", "cites": [{"t": "然则夏后、周公之典逸矣。", "b": "柳宗元《时令论上》"}], "words": [{"w": "逸诗;逸简", "t": "散失的简册"}, {"w": "逸编", "t": "散失的篇章"}, {"w": "逸记", "t": "散失的记载"}, {"w": "逸品", "t": "指散失的物品"}, {"w": "逸言", "t": "散失之言"}, {"w": "逸句", "t": "散失的文句"}, {"w": "逸失", "t": "散失;失落。"}]}, {"meaning": "闲适;安乐。", "cites": [{"t": "民莫不逸。", "b": "《诗·小雅·十月之交》笺:“逸,逸豫也。”"}, {"t": "而又不自安恬逸。", "b": "《国语·吴语》。注:“逸,乐也。”"}, {"t": "为之者劳,居之者逸。", "b": "张衡《东京赋》"}, {"t": "国治身逸。", "b": "《吕氏春秋·察贤》。注:“逸,不劳也。”"}, {"t": "足以逸身煖骸而矣。", "b": "《吕氏春秋·重己》"}, {"t": "身安逸乐。", "b": "《史记·货殖列传》"}, {"t": "能逸而能劳。", "b": "宋·苏轼《教战守》"}, {"t": "无穷逸致。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "好逸恶劳。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "逸豫", "t": "安乐"}, {"w": "逸境", "t": "安乐闲适的境地。"}]}, {"meaning": "疾速。", "cites": [{"t": "良骏逸足。", "b": "《文选·傅奕·舞赋》。注:“逸,疾也。”"}, {"t": "朔阳逸骇于扶桑之津。", "b": "《文选·木华·海赋》。注;“言出疾也。”"}, {"t": "夫子奔逸绝尘。", "b": "《庄子·田子方》"}, {"t": "良骏逸足,跄捍凌越。", "b": "《老残游记》"}, {"t": "逸骇(迅疾升起);逸翮(指疾飞的鸟)", "b": ""}]}, {"meaning": "放纵;荒淫。", "cites": [{"t": "夫婿乐逸。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "逸党", "t": "荒淫放荡的一伙人"}, {"w": "逸遨", "t": "放纵遨游"}, {"w": "逸游", "t": "放纵游乐"}, {"w": "逸志", "t": "纵欲放荡之志"}, {"w": "逸声", "t": "淫声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2364wx','猜','1','cāi','犭','11','','[{"pinyin": "cāi", "defs": [{"meaning": "(形声。从犬,青声。本义:疑恨;忌恨)。"}, {"meaning": "同本义。", "cites": [{"t": "猜,恨贼也。", "b": "《说文》。按,字从犬,如狡狯狂猛之类,本以言犬,移以言人。"}, {"t": "耦俱无猜。", "b": "《左传·僖公九年》。注:“两无猜恨。”"}, {"t": "猜,恨也。", "b": "《方言十二》"}, {"t": "夫子从君,而守臣丧邑,虽吾子亦有猜焉。", "b": "《左传·昭公七年》"}], "words": [{"w": "猜忍", "t": "猜忌残忍"}, {"w": "猜迫", "t": "疑忌而加以逼迫"}, {"w": "猜忿", "t": "疑忌愤恨"}, {"w": "猜刻", "t": "疑忌而刻薄"}, {"w": "猜虐", "t": "疑忌暴虐"}, {"w": "猜狠", "t": "疑忌而凶狠"}, {"w": "猜贰", "t": "疑忌而有二心"}, {"w": "猜惮", "t": "疑忌畏惧"}, {"w": "猜谋", "t": "因疑忌而采取的计谋。"}]}, {"meaning": "揣测;推测。", "cites": [{"t": "当夜猜三划五,吃了半夜,把二百文都吃完了。", "b": "《儒林外史》"}], "words": [{"w": "猜谜语;猜灯谜;猜料", "t": "猜测料想"}, {"w": "猜量", "t": "猜测估量。"}]}, {"meaning": "起疑心。", "cites": [{"t": "猜,疑也。", "b": "《释言》"}, {"t": "寡君猜焉。", "b": "《左传·昭公三年》。注:“疑也。”"}]}, {"meaning": "怀疑;疑心。", "cites": [{"t": "虽吾子亦有猜焉。", "b": "《左传·昭公七年》"}], "words": [{"w": "猜警", "t": "因疑心而警戒。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2365wx','猪','1','zhū','犭','11','','[{"pinyin": "zhū", "defs": [{"meaning": "猪只 ,组成猪科(Suidae)的各种哺乳动物的任一种,四肢短小,尾短,体毛稀疏,鼻面短凹或平直,耳大下垂或前挺,被毛较粗,有黑、白或黑白花等色,汁腺不发达,热时喜浸水散热;特指家养种的成员。", "cites": [{"t": "猪,豕而三毛丛居者。从豕,者声。", "b": "《说文》。按,豕子也。"}], "words": [{"w": "猪魈", "t": "猪怪;猪精"}, {"w": "猪膀胱", "t": "又称“猪尿泡”、“猪胞”、“猪尿脬”、“猪脬”"}, {"w": "小猪", "t": "又叫“猪牙子”、“猪仔”、“猪娃”、“猪娃子”"}, {"w": "母猪", "t": "又叫“猪婆”、“猪婆子”、“猪娘”。"}]}, {"meaning": "水积聚。", "cites": [{"t": "大野既猪。", "b": "《书·禹贡》"}, {"t": "规偃猪。", "b": "《左传·襄公二十五年》"}, {"t": "以猪畜水。", "b": "《周礼·地官·稻人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2366wx','猎','1','liè','犭','11','','[{"pinyin": "liè", "defs": [{"meaning": "(形声。从犬,巤(liè)声。本义:打猎,捕捉禽兽)。"}, {"meaning": "同本义。", "cites": [{"t": "猎,放猎逐禽也。", "b": "《说文》"}, {"t": "不狩不猎,胡瞻尔庭有县貆兮?", "b": "《诗·魏风·伐檀》"}, {"t": "执弓挟矢以猎。", "b": "《礼记·月令》"}, {"t": "楚蒍艾猎,字叔敖。", "b": "《左传·宣公十一年》"}, {"t": "吏所猎也。", "b": "《太玄·毅》。注:“捕也。”"}, {"t": "将军猎渭城。", "b": "唐·王维《观猎》"}, {"t": "单于出猎。", "b": "《汉书·李广苏建传》"}, {"t": "教我猎虫所。", "b": "《聊斋志异·促织》"}], "words": [{"w": "猎火", "t": "打猎时焚山以驱兽的火"}, {"w": "猎围", "t": "猎捕禽兽的围子"}, {"w": "猎士", "t": "打猎的壮士"}, {"w": "猎夫", "t": "猎手、猎民、猎者、猎客、猎师、猎徒。猎人"}, {"w": "猎食", "t": "捕捉或寻找食物;谋食。"}]}, {"meaning": "搜求,追求。", "cites": [{"t": "猎德而得德。", "b": "扬雄《法言·学行》"}], "words": [{"w": "猎酒", "t": "索取酒食"}, {"w": "猎精", "t": "撷取精华"}, {"w": "猎俊", "t": "搜求有才智的人。"}]}, {"meaning": "夺取。", "cites": [{"t": "方将上猎三灵之流,下决醴泉之滋。", "b": "《文选·扬雄·羽猎赋》"}], "words": [{"w": "猎取", "t": "夺取"}, {"w": "猎鹿", "t": "喻夺取天下"}, {"w": "猎古调", "t": "迅速地拨腿转身。"}]}, {"meaning": "踩,践踏。", "cites": [{"t": "不杀老弱,不猎禾稼。", "b": "《荀子·议兵》"}]}, {"meaning": "越过;掠过。", "cites": [{"t": "[风]猎蕙草。", "b": "宋玉《风赋》"}, {"t": "不躐(猎)等也。", "b": "《礼记·学记》"}]}, {"meaning": "用手捋齐。", "cites": [{"t": "猎缨正襟危坐。", "b": "《史记·日者传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2367wx','猫','1','māo máo','犭','11','','[{"pinyin": "māo", "defs": [{"meaning": "家猫,久已被人类驯养的一种食肉类动物 ,通常被认为是一个独立的种,虽然可能是由几种旧大陆的小型野猫的杂交后代中通过自然选择而最后衍生的,有一些变种,主要的区别在于皮毛的长短,体形以及尾的有无。", "cites": [{"t": "迎猫,为其食田鼠也。", "b": "《礼记》"}], "words": [{"w": "猫儿眼", "t": "宝石名称,又名“猫睛石”。以晶莹透明如猫眼而得名"}, {"w": "猫虎", "t": "猫和虎。古代以为有益于农事的神物"}, {"w": "猫儿食", "t": "指人饭量小,食无定时"}, {"w": "猫尿", "t": "方言。指酒。表示憎厌或讥讽。"}]}, {"meaning": "姓。"}]}, {"pinyin": "máo", "defs": [{"meaning": "", "words": [{"w": "猫腰", "t": "弯腰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2368wx','凰','1','huáng','几','11','','[{"pinyin": "huáng", "defs": [{"meaning": "中国古代传说中的鸟名,雄的叫“凤”,雌的叫“凰”", "words": [{"w": "凤求凰", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2369wx','猖','1','chāng','犭','11','','[{"pinyin": "chāng", "defs": [{"meaning": "猖狂的人。", "cites": [{"t": "苏枯弱强,龈其奸猖。", "b": "唐·韩愈《曹成王碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2370wx','猛','1','měng','犭','11','','[{"pinyin": "měng", "defs": [{"meaning": "(形声。从犬,孟声。本义:健壮的狗) 同本义。", "cites": [{"t": "猛,健犬也。", "b": "《说文》"}, {"t": "驱猛兽。", "b": "《孟子》"}, {"t": "猛虞趪趪。", "b": "张衡《西京赋》。注:“怒也。”"}], "words": [{"w": "大猛", "t": "大狗。"}]}, {"meaning": "凶恶可怕。", "cites": [{"t": "公之狗甚猛。", "b": "《韩诗外传》"}, {"t": "粗厉猛起。", "b": "《礼记·乐记》"}, {"t": "苛政猛于虎。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "如猛兽奇鬼。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "猛利", "t": "犹凶暴"}, {"w": "猛戾", "t": "凶暴乖张"}, {"w": "猛急", "t": "犹暴躁"}, {"w": "猛暴", "t": "凶残暴戾。"}]}, {"meaning": "勇猛;威猛。", "cites": [{"t": "威而不猛。", "b": "《论语》"}, {"t": "便捷猛鸷。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "命猛将统兵。", "b": "《资治通鉴·赤壁之战》"}, {"t": "雄发指危冠,猛气冲长缨。", "b": "陶潜《咏荆轲》"}], "words": [{"w": "猛进", "t": "勇猛精进"}, {"w": "猛决", "t": "勇猛果决"}, {"w": "猛勇", "t": "威猛勇敢"}, {"w": "猛气", "t": "勇猛的气势和气概。"}]}, {"meaning": "猛烈(强烈;刚烈)。", "cites": [{"t": "火烈风猛。", "b": "《资治通鉴》"}, {"t": "猛浪若奔。", "b": "吴均《与朱元思书》"}], "words": [{"w": "猛火", "t": "猛烈燃烧的火"}, {"w": "猛迅", "t": "猛烈而迅速"}, {"w": "凶猛", "t": "凶恶强大。"}]}, {"meaning": "忽然,突然。", "cites": [{"t": "[荀]彧猛省曰:“吾儿忘却!”", "b": "《三国演义》"}], "words": [{"w": "猛不乍", "t": "突然"}, {"w": "猛古丁", "t": "突然"}, {"w": "猛可", "t": "突然"}, {"w": "猛生,猛乍", "t": "突然。"}]}, {"meaning": "非常,甚。", "cites": [{"t": "阅史披图,猛欲追谟于贤圣;宵衣旰食,每勤顾问于臣邻。", "b": "明·陈汝元《金莲记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2371wx','祭','1','jì zhài','示','11','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。甲骨文字形,左边是牲肉;左边是“又”(手);中间象祭桌。表示以手持肉祭祀神灵。古人杀牲,一是为自己吃,再就是常把牲肉放在祭台上,“祭”字就是有酒肉的祭祀,即牲祭。本义:祭祀)。"}, {"meaning": "同本义。", "cites": [{"t": "祭,祀也。", "b": "《说文》"}, {"t": "祭之为言索也。", "b": "《说苑·权谋》"}, {"t": "祭者,荐其时也,荐其敬也,荐其美也,非享味也。", "b": "《谷梁传·成公十七年》"}, {"t": "无牲而祭曰荐,荐而加牲曰祭。", "b": "《公羊传·桓公八年》注"}, {"t": "祭者,所以追养继孝也。", "b": "《礼记·祭统》"}, {"t": "祭于公,不宿肉。祭肉不出三日。", "b": "《论语·乡党》"}, {"t": "以灵鼓鼓社祭。", "b": "《周礼·地官》"}], "words": [{"w": "公祭死难烈士;主祭;陪祭;祭扫", "t": "祭祀并扫墓。"}]}]}, {"pinyin": "zhài", "defs": [{"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2372wx','馅','1','xiàn','饣','11','','[{"pinyin": "xiàn", "defs": [{"meaning": "被包裹的人或物。", "cites": [{"t": "城外土馒头,馅草在城里。", "b": "宋·阮阅《诗话总龟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2373wx','馆','1','guǎn','饣','11','','[{"pinyin": "guǎn", "defs": [{"meaning": "(形声。从食,官声。“馆”,供宿供膳,所以从“食”。它的异体字作“舘”,说明“馆”属于房舍一类。本义:高级客舍,宾馆)。"}, {"meaning": "同本义。", "cites": [{"t": "馆,客舍也。", "b": "《说文》"}, {"t": "五十里有市,市有候馆。候馆有积。", "b": "《周礼·遗人》"}, {"t": "适子之馆兮。", "b": "《诗·郑风·缁衣》"}, {"t": "于豳斯馆。", "b": "《诗·大雅·公刘》"}, {"t": "晋师三日馆谷。", "b": "《左传·僖公二十八年》"}, {"t": "楚公子围聘于郑,…将入馆。", "b": "《左传·昭公元年》"}, {"t": "郑穆公使视客馆,则束载,厉兵秣马矣。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "馆人", "t": "负责管理馆舍招待宾客的人"}, {"w": "馆客", "t": "接待宾客,安置于馆舍"}, {"w": "馆驿", "t": "馆舍驿站。"}]}, {"meaning": "房舍华丽的。官署、学塾、书房、商坊、展览处所等都可命名为馆。", "cites": [{"t": "公馆复。", "b": "《礼记·曾子问》。注:“若今县官舍也。”"}, {"t": "及蒩馆。", "b": "《周礼·司巫》"}, {"t": "辟病梅之馆以贮之。", "b": "清·龚自珍《病梅馆记》"}, {"t": "余是夕宿于日本使馆。", "b": "梁启超《谭嗣同传》"}, {"t": "明年在我们行事里替你寻一个馆(此指塾师教书之处)。", "b": "《儒林外史》"}, {"t": "凡有名者,往往留像于馆。", "b": "薛福成《观巴黎油画记》"}], "words": [{"w": "馆地", "t": "学馆;教书工作"}, {"w": "建馆;馆伴", "t": "在使馆里接待陪伴外国使节,亦指从事这种工作的人"}, {"w": "馆伴使", "t": "亦称“伴使”。接待陪同外国使节的官员"}, {"w": "茶馆;饭馆;酒馆;咖啡馆;理发馆;照相馆;博物馆;美术馆;体育馆;图书馆;文化馆;展览馆", "t": ""}]}, {"meaning": "住,住宿。", "cites": [{"t": "师还,馆于虞。", "b": "《左传·僖公元年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2374wx','凑','1','còu','冫','11','','[{"pinyin": "còu", "defs": [{"meaning": "(形声。从水,奏声。本义:水流会合)。"}, {"meaning": "同本义。", "cites": [{"t": "凑,水会也,聚也。", "b": "《广韵》"}, {"t": "凑,水上人所会也。", "b": "《 说文》。"}, {"t": "顺波凑而下降。", "b": "《楚辞·九叹·逢纷》。注:“聚也。”"}]}, {"meaning": "聚集。", "cites": [{"t": "趋舍相凑。", "b": "《淮南子·原道》。注:“所合也。”"}, {"t": "则人物归之,繈至而辐凑。", "b": "《史记·货殖列传》"}], "words": [{"w": "凑队", "t": "集合在一起"}, {"w": "凑聚", "t": "集合,聚集"}, {"w": "凑泊", "t": "凝聚,结合"}, {"w": "凑会", "t": "聚集,会合。"}]}, {"meaning": "奔向;趋。", "cites": [{"t": "衰世凑学。", "b": "《淮南子·精神》。注:“趋也。”"}], "words": [{"w": "凑亟", "t": "急切"}, {"w": "凑手不及", "t": "事情来得太快,出人意料,来不及应付。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2375wx','减','1','jiǎn','冫','11','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从水,咸声。本义:减少,由全体中去掉一部分)。"}, {"meaning": "同本义。", "cites": [{"t": "减,渻也。", "b": "《说文》"}, {"t": "减,少也。", "b": "《广雅》"}, {"t": "减,尽也。", "b": "《管子·宙合》"}, {"t": "谮始既减。", "b": "《韩诗·巧言》。传:“少也。”"}, {"t": "克减侯宣多。", "b": "《左传·文公十七年》"}, {"t": "太仆减谷食。", "b": "《汉书·元帝纪》"}, {"t": "为减舆从。", "b": "清·张廷玉《明史》"}, {"t": "增减要语。", "b": "清·方苞《狱中杂记》"}, {"t": "今昔而减。", "b": "清·洪亮吉《治平篇》"}, {"t": "减一分则喜。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "减算", "t": "减少税收;减少年寿"}, {"w": "减膳", "t": "吃素或减少菜肴"}, {"w": "减了口里的", "t": "减少饮食。"}]}, {"meaning": "不足;不到;少于。", "cites": [{"t": "王右军年减十岁时,大将军甚爱之。", "b": "《世说新语》"}]}, {"meaning": "诛,杀。", "cites": [{"t": "减二卿。", "b": "《史记·赵世家》"}]}, {"meaning": "降低;减轻。", "cites": [{"t": "不为末减。", "b": "《左传·昭公十四年》。注:“轻也。”"}], "words": [{"w": "减流", "t": "从轻流放罪犯"}, {"w": "减等", "t": "减轻刑罚的等级;从轻判刑;减低等级"}, {"w": "减降", "t": "减轻降低"}, {"w": "减汰", "t": "削减淘汰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2376wx','毫','1','háo','毛','11','','[{"pinyin": "háo", "defs": [{"meaning": "(毫为豪的俗字。形声。从毛,高省声。本义:长而尖的毛)。"}, {"meaning": "同本义。", "cites": [{"t": "未成毫狗。", "b": "《尔雅·释畜》"}], "words": [{"w": "毫光", "t": "如毫毛的光芒 "}, {"w": "毫芒", "t": "毫毛的细尖"}, {"w": "毫黍", "t": "毫毛与黍粒。比喻极微小"}, {"w": "毫眉", "t": "老年人的眉毛。因其毛长,故称。"}]}, {"meaning": "毛笔的头部;毛笔。", "words": [{"w": "毫端", "t": "毛笔笔尖"}, {"w": "毫笺", "t": "毛笔和精美的纸张"}, {"w": "毫管", "t": "指毛笔"}, {"w": "毫墨", "t": "笔和墨。借指文字、图画。"}]}, {"meaning": "比喻极细小的东西,细微。", "cites": [{"t": "明足以察秋毫之之末。", "b": "《孟子·梁惠王上》"}, {"t": "锐思于毫芒之内。", "b": "班固《答宾戏》"}], "words": [{"w": "毫分", "t": "比喻极细微"}, {"w": "毫忽", "t": "一点点儿。十忽为丝,十丝为毫,十毫为厘"}, {"w": "毫厘不爽", "t": "一点儿也不差"}, {"w": "毫芥", "t": "比喻极细微的事物。"}]}, {"meaning": "单位名。"}, {"meaning": "长度单位,等于千分之一寸或1/30毫米。"}, {"meaning": "重量单位,等于千分之一钱或0.005克。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2377wx','烹','1','pēng','灬','11','','[{"pinyin": "pēng", "defs": [{"meaning": "(形声。从火,亨声。本义:烧煮)。"}, {"meaning": "同本义。", "cites": [{"t": "烹,煮也。", "b": "《集韵》"}, {"t": "故曰:“治大国者若烹小鲜。", "b": "《韩非子·解老》"}, {"t": "卒买鱼烹食。", "b": "《史记·陈涉世家》"}], "words": [{"w": "烹炮", "t": "烹调的手艺"}, {"w": "烹鲜", "t": "比喻治理国家"}, {"w": "烹龙炮凤", "t": "形容山珍海味"}, {"w": "烹石", "t": "煎药"}, {"w": "烹炙", "t": "烹煮煎烤"}, {"w": "烹庖", "t": "烹治;烹煮"}, {"w": "烹茗", "t": "煮茶或沏茶"}, {"w": "烹宰", "t": "宰杀烹煮牲畜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2378wx','庶','1','shù zhù','广','11','','[{"pinyin": "shù", "defs": [{"meaning": "众多。", "cites": [{"t": "庶,屋下众也。", "b": "《说文》"}, {"t": "既庶且多。", "b": "《诗·大雅·卷阿》"}, {"t": "明庶风至。", "b": "《春秋考异郵》"}, {"t": "庶众也。", "b": "《尔雅》"}, {"t": "庶明厉翼。", "b": "《书·皋谟》"}, {"t": "制义庶乎以行之。", "b": "《国语·周语》"}, {"t": "寒暑不时,以伤庶物。", "b": "《庄子·渔夫》"}, {"t": "且地学之家,历验各种僵石,知动植庶品,率皆递有变迁。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "庶常", "t": "众多有养德的官员"}, {"w": "庶类", "t": "众多物类"}, {"w": "庶官", "t": "百官,众官"}, {"w": "庶士", "t": "众士,多士;军士"}, {"w": "庶事", "t": "诸事,众事"}, {"w": "庶草", "t": "百草众草"}, {"w": "庶征", "t": "许多迹象"}, {"w": "庶尹", "t": "百官之长。同“庶正”"}, {"w": "庶卉", "t": "众草"}, {"w": "庶兄弟", "t": "众兄弟"}, {"w": "庶邦", "t": "诸侯众国。"}]}, {"meaning": "各种。", "cites": [{"t": "以清酌庶羞之奠,致祭于亡友曼卿之墓下。", "b": "欧阳修《祭石曼卿文》"}], "words": [{"w": "庶羞", "t": "各种佳肴"}, {"w": "庶政", "t": "一切政务,各种政务"}, {"w": "庶僚", "t": "朝中百官"}, {"w": "庶吉士", "t": "官名。翰林院的庶常馆,选擅长文学书法之新进士,入院学习,称之"}, {"w": "庶绩", "t": "各种功绩,众多的功业。"}]}, {"meaning": "几乎,将近,差不多。", "cites": [{"t": "王之好乐甚,则齐国其庶几乎?", "b": "《孟子·梁惠王下》"}], "words": [{"w": "庶可", "t": "差不多可以。"}]}, {"meaning": "百姓;平民。", "cites": [{"t": "将军魏武之子孙,于今为庶为清门。", "b": "唐·杜甫《丹青引》"}, {"t": "三后之姓,于今为庶,王所知也。(三后:夏、商、周三代帝王。)", "b": "《左传·昭公三十二年》"}], "words": [{"w": "庶黎", "t": "平民,百姓"}, {"w": "庶女", "t": "平民的女儿"}, {"w": "庶萌", "t": "众民,百姓。"}]}, {"meaning": "庶子,非嫡配所生的孩子;宗族的旁支。", "cites": [{"t": "分势不贰,庶適(同嫡)不争。", "b": "《韩非子·八经·起礼》"}, {"t": "天乎,仲为不道,杀嫡立庶。", "b": "《左传·文公十八年》"}], "words": [{"w": "庶孙", "t": "庶出的孙子"}, {"w": "庶孽", "t": "妾媵之子;庶生之子"}, {"w": "庶长", "t": "庶出的长者"}, {"w": "庶弟", "t": "庶出之弟"}, {"w": "庶兄", "t": "庶出之兄"}, {"w": "庶叔", "t": "庶出之叔父。"}]}, {"meaning": "也许;或许。", "cites": [{"t": "君姑修政而亲兄弟之国,庶免于难。", "b": "《左传·桓公六年》"}, {"t": "而今而后,庶几无愧。", "b": "《宋史·文天祥传》"}], "words": [{"w": "庶或", "t": "或许"}, {"w": "庶报", "t": "也许可以报答"}, {"w": "庶或", "t": "也许;或许"}, {"w": "庶易为力", "t": "或许容易办到。"}]}, {"meaning": "幸而,幸得。", "cites": [{"t": "庶几哉!桔逾淮弗为枳矣。", "b": "明·徐光启《甘薯疏序》"}, {"t": "朕宿昔庶几获承尊位。", "b": "班固《汉书·公孙宏传》"}], "words": [{"w": "遮定", "t": "幸得安定。"}]}, {"meaning": "但愿,希冀。", "cites": [{"t": "(伍举)惧而奔郑,引领南望曰:“庶几赦余。”", "b": "《左传·襄公二十六年》"}], "words": [{"w": "庶竭驽钝", "t": "希望竭尽自己的微薄才力。"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhù", "defs": [{"meaning": "煮。", "cites": [{"t": "甲骨文‘庶’字是从火石、石亦声的会意兼形声字,也即‘煮’的本字…‘庶’之本义,乃以火燃石而煮,是根据古人实际生活而象意依声而造字的。", "b": "于省吾《甲骨文字释林》"}, {"t": "庶氏下士一人,徒四人。", "b": "《周礼·秋官》"}], "words": [{"w": "庶虫", "t": "除虫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2379wx','麻','1','má mā','麻','11','','[{"pinyin": "má", "defs": [{"meaning": "(会意。从广(yǎn),从林(fèi)。广表示房子,林指削制的麻皮。合而表示在家里劈麻,进行剥制。本义:麻类植物的总名。古代专指大麻) 同本义 。桑科,一年生草本,雌雄异株。茎部韧皮纤维长坚韧,可供纺织。有大麻、亚麻、苎麻、黄麻、剑麻、蕉麻等,俗称“火麻”。", "cites": [{"t": "麻,枲也。", "b": "《说文》。按,枲已缉者曰麻。"}, {"t": "丘中有麻。", "b": "《诗·王风·丘中有麻》"}, {"t": "可以沤麻。", "b": "《诗·陈风·东门之池》"}, {"t": "麻冕。", "b": "《论语》。孔注:“缁布冠也。”"}, {"t": "缌麻三月。", "b": "《仪礼·丧服》"}, {"t": "雨脚如麻未断绝。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "仙之人兮列如麻。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "我麻日已长,我土日已广。", "b": "陶潜《归园田居》"}, {"t": "雄者名麻枲,雌者名苴麻。", "b": "《本草纲目·大麻》"}], "words": [{"w": "麻田", "t": "种麻的田地"}, {"w": "麻炬", "t": "用麻干作成的火把"}, {"w": "麻畦", "t": "麻田"}, {"w": "麻蒸", "t": "去皮的麻秆"}, {"w": "麻稭", "t": "麻的茎"}, {"w": "麻苇", "t": "麻与芦苇"}, {"w": "麻苎", "t": "大麻与苎麻。"}]}, {"meaning": "麻的茎皮纤维。", "cites": [{"t": "不续其麻,市也婆娑。", "b": "《诗·陈风·东门之枌》"}], "words": [{"w": "麻搭", "t": "一种在长杆顶端缚扎散麻蘸吸泥水灭火的工具"}, {"w": "麻核桃", "t": "用麻结成球结"}, {"w": "麻槌", "t": "旧时刑具,用麻绞扎而成的带疙瘩短鞭"}, {"w": "麻屣鹑衣", "t": "麻鞋破衣。"}]}, {"meaning": "麻布丧服,亲属死后穿的白色麻布衣服。", "cites": [{"t": "麻不加于采。", "b": "《礼记·杂记下》"}], "words": [{"w": "披麻戴孝;麻衣", "t": "孝服"}, {"w": "麻裙", "t": "服丧时穿的麻布裙。"}]}, {"meaning": "代指唐宋时的诏书 ,因为是用黄、白麻纸写的,故名。", "cites": [{"t": "三麻九制笔如神。", "b": "刘克庄《内翰洪公舜俞哀》"}], "words": [{"w": "麻命", "t": "任命的诏书"}, {"w": "麻词", "t": "麻辞。任命宰相的诏书"}, {"w": "麻尾", "t": "诏书结尾。"}]}, {"meaning": "脸部皮肤的痘瘢,俗称麻子脸。", "cites": [{"t": "南京柳麻子,黧黑,满面疤。", "b": "《柳敬亭说书》"}], "words": [{"w": "麻皮", "t": "麻子脸皮。"}]}, {"meaning": "形容众多,混乱。", "cites": [{"t": "麻麻胡子红脸蛋。", "b": "王老九《张老汉卖余粮》"}], "words": [{"w": "麻麻", "t": "浓密的样子"}, {"w": "麻乱", "t": "纷乱"}, {"w": "麻列", "t": "比喻众多。"}]}, {"meaning": "穿丧服。", "cites": [{"t": "麻者不绅。", "b": "《礼记·杂记》"}]}, {"meaning": "麻木。", "cites": [{"t": "走的我这两腿酸麻。", "b": "秦简夫《孝义士赵礼让肥》"}]}, {"meaning": "姓。"}]}, {"pinyin": "mā", "defs": [{"meaning": "天色", "words": [{"w": "麻麻黑", "t": "天刚黑或天快黑"}]}, {"meaning": "天色", "words": [{"w": "麻麻亮", "t": "[方言]∶天刚有点儿亮"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2380wx','庵','1','ān','广','11','','[{"pinyin": "ān", "defs": [{"meaning": "(闇的俗字作庵或菴)。"}, {"meaning": "圆顶草屋。", "cites": [{"t": "草圆屋谓之庵。", "b": "《释名·释宫室》"}, {"t": "庵,舍也。", "b": "《广雅》"}, {"t": "亲人菴庐。", "b": "《后汉书·皇甫规传》"}, {"t": "居河之湄,结划为庵。", "b": "《神仙传·焦先传》。"}], "words": [{"w": "庵舍", "t": "设在墓旁的草屋"}, {"w": "庵庐", "t": "草舍。"}]}, {"meaning": "尼姑的住所。", "cites": [{"t": "一定另外或村庄或尼庵寻个下处。", "b": "《红楼梦》。"}], "words": [{"w": "水月庵;庵堂", "t": "尼姑庵。"}]}, {"meaning": "庙宇。", "cites": [{"t": "既登峰头,一庵翼然,为文殊院。", "b": "《徐霞客游记·游黄山》。"}], "words": [{"w": "庵舍", "t": "小寺庙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2381wx','痊','1','quán','疒','11','','[{"pinyin": "quán", "defs": [{"meaning": "病除;病愈。", "cites": [{"t": "今予病少痊,予又且复游于六合之外。", "b": "《庄子》"}], "words": [{"w": "痊除,痊疴,痊差,痊较", "t": "痊愈"}, {"w": "痊瘥;痊济,痊疗", "t": "病愈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2382wx','痒','1','yǎng','疒','11','','[{"pinyin": "yǎng", "defs": [{"meaning": "(形声。从疒(chuáng),养声。本义:一种皮肤不适、引人欲搔的感觉)。"}, {"meaning": "形容某些难以抑制的强烈愿望。", "cites": [{"t": "花前技痒又成诗。", "b": "宋·陆游《还东》"}], "words": [{"w": "痒滋滋", "t": "形容按捺不下某种兴奋的情绪"}, {"w": "痒酥酥", "t": "形容产生某种难以压抑的强烈愿望;形容轻松愉快的感觉"}, {"w": "痒处", "t": "指心里怀的强烈愿望或身上存在的突出问题。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2383wx','痕','1','hén','疒','11','','[{"pinyin": "hén", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,艮(gèn)声。本义:疮伤痊愈后留下的疤)。"}, {"meaning": "同本义。", "cites": [{"t": "痕,胝瘢也。", "b": "《说文》"}, {"t": "创瘢曰痕。", "b": "《通俗文》"}], "words": [{"w": "痕瑕", "t": "瘢痕,斑点"}, {"w": "痕挞", "t": "伤痕"}, {"w": "痕瘕", "t": "疤痕。比喻曾犯过罪"}, {"w": "伤痕", "t": ""}]}, {"meaning": "泛指痕迹。", "cites": [{"t": "鸟归沙有迹,帆过浪无痕。", "b": "贾岛《江亭晚望》"}, {"t": "苔痕上阶绿。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "空余泪痕。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "痕垢", "t": "污垢"}, {"w": "痕印", "t": "痕迹;烙印"}, {"w": "痕沫", "t": "水沫的痕迹"}, {"w": "痕秽", "t": "污秽的痕迹"}, {"w": "痕影", "t": "痕迹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2384wx','廊','1','láng','广','11','','[{"pinyin": "láng", "defs": [{"meaning": "(形声。从广(yǎn),郎声。从“广”,表示与房屋有关。本义:厅堂周围的屋)。"}, {"meaning": "同本义。", "cites": [{"t": "平公恐惧,优于廊室之间。", "b": "《韩非子·十过》"}], "words": [{"w": "廊房", "t": "廊室。殿堂周围的房舍"}, {"w": "廊屋", "t": "廊室"}, {"w": "廊庑", "t": "堂前的廊屋;屋檐下的过道或独立有顶的通道。"}]}, {"meaning": "走廊。", "cites": [{"t": "高柳早莺啼,长廊春雨响。", "b": "王维《谒瑀上人》"}, {"t": "入门穿廊,过前后厅。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "回廊", "t": "曲折环绕的走廊"}, {"w": "游廊", "t": "连接两个或几个独立建筑物的走廊"}, {"w": "廊牙", "t": "廊檐下像牙齿般的装饰"}, {"w": "廊厩", "t": "围廊旁的房舍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2385wx','康','1','kāng','广','11','','[{"pinyin": "kāng", "defs": [{"meaning": "(会意。康为穅的本字。从禾,康声。本义:谷皮;米糠)。"}, {"meaning": "同本义。", "cites": [{"t": "康,谷皮也。", "b": "《说文》。字亦作穅。"}, {"t": "尘垢粃穅。", "b": "《庄子·逍遥游》"}, {"t": "亦食穅何覈耳。", "b": "《汉书·陈平传》"}, {"t": "播康迷目。", "b": "《庄子·天运》"}]}, {"meaning": "五路通达的大路,泛指大路。", "cites": [{"t": "五达谓之康,六达谓之庄。", "b": "《尔雅》"}, {"t": "公驱及之康内。", "b": "《晏子春秋·内篇谏上》"}, {"t": "微服游于康衢。", "b": "《列子·仲尼》"}]}, {"meaning": "安乐,安定。", "cites": [{"t": "民康乐。", "b": "《礼记·乐记》"}, {"t": "无己大康,职思其居。", "b": "《诗·唐风·蟋蟀》"}, {"t": "上下和洽,海内康平。", "b": "《汉书·宣帝纪》"}, {"t": "日康娱以自忘兮。", "b": "《楚辞·离骚》"}], "words": [{"w": "康乐", "t": "安乐"}, {"w": "康阜", "t": "安和富足"}, {"w": "康娱", "t": "欢娱安乐"}, {"w": "康福", "t": "安乐,富裕。"}]}, {"meaning": "健康。", "cites": [{"t": "命如南山石,四体康且直。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "康健", "t": "安康强健"}, {"w": "康胜", "t": "康健安泰"}, {"w": "康宁", "t": "健康平安。"}]}, {"meaning": "太平;安宁。", "cites": [{"t": "海、沂之康,实赖王祥,邦国不空,别驾之功。", "b": "《晋书》"}], "words": [{"w": "康时", "t": "太平盛世"}, {"w": "康乂", "t": "安治,太平无事。乂:治理"}, {"w": "康适", "t": "安适,安舒"}, {"w": "康日", "t": "谓太平岁月。"}]}, {"meaning": "丰足;富裕。", "cites": [{"t": "迄用康年。", "b": "《世说新语·周臣臣》"}], "words": [{"w": "康年", "t": "丰年。"}]}, {"meaning": "四通八达的;四面八方的。", "cites": [{"t": "为开第康庄之路。", "b": "《史记·孟子荀卿列传》"}, {"t": "酌彼大康。", "b": "《世产新语·小甫宾》"}], "words": [{"w": "康衢", "t": "通向四面八方的宽阔大路"}, {"w": "康功", "t": "平整道路之事"}, {"w": "康庄;康逵", "t": "康庄大道"}, {"w": "康途", "t": "康衢,犹坦途,大道。指生死之道"}, {"w": "康爵", "t": "一说大的酒杯。"}]}, {"meaning": "空。", "cites": [{"t": "酌彼康爵,以奏尔时。", "b": "《诗·小雅·宾之初筵》"}, {"t": "斡弃周鼎兮宝康瓠。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "康瓠", "t": "空酒器,比喻腹中空空的庸才。"}]}, {"meaning": "褒扬;赞美。", "cites": [{"t": "康周公,故以赐鲁也。", "b": "《礼记》"}]}, {"meaning": "使安定。", "cites": [{"t": "文王康之。", "b": "《荀子·王制》"}], "words": [{"w": "康护", "t": "安定维护"}, {"w": "康隆", "t": "使安定兴盛。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2386wx','庸','1','yōng','广','11','','[{"pinyin": "yōng", "defs": [{"meaning": "(会意。小篆字形。从用,从庚。“庚更”同音,表更换。先做某事,然后更换做别的事。本义:用;需要)。"}, {"meaning": "同本义。", "cites": [{"t": "庸,用也。", "b": "《说文》"}, {"t": "畴咨若时登庸。", "b": "《书·尧典》"}, {"t": "我生之初,尚无庸。", "b": "《诗·王风·兔爰》"}, {"t": "齐子庸止。", "b": "《诗·齐风·南山》"}]}, {"meaning": "靖潜庸回。——《左传·文公十八年》。", "cites": [{"t": "庸動长老。", "b": "《国语·周语中》"}, {"t": "请始无庸战。", "b": "《国语·越语上》"}]}, {"meaning": "常与否定副词“无”、“勿”、“弗”连用。", "cites": [{"t": "无稽之言勿听,弗询之谋勿庸。", "b": "《书·大禹谟》"}, {"t": "我无庸去,只是教阁下个至良极美的法则。", "b": "《礼记》"}], "words": [{"w": "无庸讳言;无庸细述;毋庸讳言;庸释", "t": "舍弃。"}]}, {"meaning": "任用。", "cites": [{"t": "名之所在,上之所庸。", "b": "清·顾炎武《日知录》"}], "words": [{"w": "庸庸", "t": "任用应受任用的人"}, {"w": "登庸", "t": "选拔重用。"}]}, {"meaning": "受雇用,出卖劳动力。", "cites": [{"t": "买庸而决窦。", "b": "《韩非子·五蠹》"}], "words": [{"w": "庸作", "t": "受雇而为人劳作"}, {"w": "庸仆", "t": "佣工、仆役"}, {"w": "庸僦", "t": "雇佣租赁。"}]}, {"meaning": "酬其功劳。", "cites": [{"t": "亲亲故故,庸庸劳劳,仁之杀也。", "b": "《荀子·大畧》"}], "words": [{"w": "庸勋", "t": "酬劳有功的人。"}]}, {"meaning": "平常。", "cites": [{"t": "庸,常也。", "b": "《尔雅》"}, {"t": "此庸夫之怒也。", "b": "《战国策·魏策》"}, {"t": "恒丝庸帛。", "b": "《论衡·量知》"}, {"t": "布帛寻常,庸人不释。", "b": "《韩非子》"}], "words": [{"w": "庸德", "t": "常德,一般的道德规范"}, {"w": "庸人", "t": "常人"}, {"w": "庸众", "t": "常人;一般的人"}, {"w": "庸情", "t": "犹俗虑,常人的心志"}, {"w": "庸格", "t": "常例"}, {"w": "庸音", "t": "常音。喻指平庸的文辞和言论"}, {"w": "庸民", "t": "平民;普通的人"}, {"w": "庸凡", "t": "平凡。"}]}, {"meaning": "平庸。", "cites": [{"t": "任重职大,非庸材所能堪。", "b": "《汉书·薛宣传》"}], "words": [{"w": "庸庸碌碌", "t": "形容人平庸,没有志气"}, {"w": "庸涩", "t": "平庸晦涩"}, {"w": "庸下", "t": "平庸低下"}, {"w": "庸懦", "t": "平庸懦弱"}, {"w": "庸伍", "t": "才识平庸之辈"}, {"w": "庸臣", "t": "平庸之臣"}, {"w": "庸朽", "t": "庸下衰朽"}, {"w": "庸主", "t": "平庸的君主"}, {"w": "庸君", "t": "平庸之君;昏君"}, {"w": "庸鄙", "t": "平庸鄙俗"}, {"w": "庸腐", "t": "平庸陈腐;平庸迂腐"}, {"w": "庸儒", "t": "平庸的儒者。"}]}, {"meaning": "昏庸,庸下。", "cites": [{"t": "不有乱常,则多庸暗。", "b": "《晋书·惠帝纪论》"}], "words": [{"w": "庸暗", "t": "昏庸愚昧"}, {"w": "庸朽", "t": "庸下衰朽。"}]}, {"meaning": "功勋。", "cites": [{"t": "现克一堡之庸,酬通侯之锡者,又何若不伦?", "b": "清·魏源《圣武记》"}], "words": [{"w": "庸功", "t": "庸伐,庸勋,庸绩。功勋;功绩"}, {"w": "庸器", "t": "古代铭功的铜器。"}]}, {"meaning": "受雇用的人。", "cites": [{"t": "庸人訾厉。", "b": "《管子·入国》"}, {"t": "取庸而强饭之。", "b": "《淮南子·缪称》"}], "words": [{"w": "庸保", "t": "受雇充任杂役的人"}, {"w": "庸仆", "t": "佣工、仆役。"}]}, {"meaning": "劳苦。", "cites": [{"t": "我生之初,尚无庸;我生之后,逢此百凶。", "b": "《诗·王风》"}]}, {"meaning": "受雇者的工钱。", "cites": [{"t": "写书取庸自给。", "b": "《新唐书》"}], "words": [{"w": "庸钱", "t": "工资。"}]}, {"meaning": "古国名,在今湖北省。", "cites": [{"t": "庸蜀之南。", "b": "唐·柳宗元《柳河东集》"}]}, {"meaning": "或许,大概。", "cites": [{"t": "虽王之国,庸独利乎?", "b": "《汉书》"}]}, {"meaning": "表示反问,可译为“难道”、“岂”、“哪里”。", "cites": [{"t": "庸非昔日之乐。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "庸知其年之先后。", "b": "唐·韩愈《师说》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2387wx','鹿','1','lù','鹿','11','','[{"pinyin": "lù", "defs": [{"meaning": "(象形。甲骨文字形,象鹿的头角四足之形。本义:鹿科动物的总称。种类很多,通常雄鹿有角)。"}, {"meaning": "同本义。", "cites": [{"t": "鹿,山兽也。", "b": "《说文》"}, {"t": "即鹿无虞。", "b": "《易·屯》"}, {"t": "呦呦鹿鸣。", "b": "《诗·小雅·鹿鸣》"}, {"t": "鹿中容八算。", "b": "《仪礼·乡射礼记》"}], "words": [{"w": "鹿中", "t": "刻成鹿形的木器"}, {"w": "鹿伏鹤行", "t": "形容小心警惕的样子。"}]}, {"meaning": "比喻政权,爵位。", "cites": [{"t": "秦失其鹿,天下共逐之。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "鹿台", "t": "古台名。故址在今河南汤阴朝歌镇南,相传为殷纣王所造。武王伐纣,纣兵败,登台自焚而死。"}]}, {"meaning": "方形粮仓。", "cites": [{"t": "市无赤米,而囷鹿空虚。", "b": "《国语·吴语》"}]}, {"meaning": "山脚。", "cites": [{"t": "秋八月辛卯,沙鹿崩。", "b": "《谷梁传·僖公十四年》"}]}, {"meaning": "竹箱。", "cites": [{"t": "而囷鹿空虚。", "b": "《国语·吴语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2388wx','盗','1','dào','皿','11','','[{"pinyin": "dào", "defs": [{"meaning": "(会意。甲骨文字形,意思是:看到人家的器皿就会贪婪地流口涎,存心不善。本义:盗窃,偷东西)。"}, {"meaning": "同本义。", "cites": [{"t": "盜,私利物也。", "b": ""}, {"t": "窃货曰盗。", "b": "《荀子·脩身》"}, {"t": "君子不为盗,贤人不为窃。", "b": "《庄子·山水》"}, {"t": "窃人之财犹谓之盗。", "b": "《左传·僖公二十四年》"}, {"t": "盗器为奸。", "b": "《左传·文公十八年》"}, {"t": "盗名不如盗货。", "b": "《荀子·不苟》"}, {"t": "如姬果盗兵符与公子。", "b": "《史记·魏公子列传》"}, {"t": "齐国人善盗乎?", "b": "《晏子春秋·内篇杂下》"}], "words": [{"w": "偷盗", "t": "偷窃"}, {"w": "盗跖下惠", "t": "跖和柳下惠,两人虽是兄弟,但跖被诬为大盗,而柳下惠却被视为圣人"}, {"w": "盗名", "t": "偷取美名。"}]}, {"meaning": "抢掠劫持。", "cites": [{"t": "遂共盗而残之。", "b": "《列子·说符》"}]}, {"meaning": "私通。", "cites": [{"t": "闻平居家时,盗其嫂。", "b": "《汉书·陈平传》"}]}, {"meaning": "偷盗财物的人(先秦两汉用“盗”)。", "cites": [{"t": "其犹穿窬(跳墙)之盗也与。", "b": "《论语·阳货》"}, {"t": "盗起而不知御,民困而不知救。", "b": "刘基《卖柑者言》"}, {"t": "乃托言有盗,令人修墙。", "b": "《世说新语·或溺》"}]}, {"meaning": "抢劫财物的人,强盗。", "cites": [{"t": "职盗为寇。", "b": "《诗·大雅·桑柔》"}, {"t": "闻盗贼之名,则掩耳而不愿听。", "b": "宋·苏轼《教战守》"}, {"t": "天下何故不谓子为盗丘?", "b": "《庄子·盗跖》"}, {"t": "所以遣将守关者,备他盗之出入与非常也。", "b": "《史记·项羽本纪》"}, {"t": "是故寇盗处处蚁合。", "b": "《世说新语·识鉴》"}], "words": [{"w": "盗竽", "t": "盗魁;盗首"}, {"w": "盗目", "t": "盗贼头目"}, {"w": "海盗;窃国大盗", "t": ""}]}, {"meaning": "偷偷地,暗中地。", "cites": [{"t": "民亦间盗铸钱。", "b": "《史记·平准书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2389wx','章','1','zhāng','立','11','','[{"pinyin": "zhāng", "defs": [{"meaning": "(会意。从音十。音指音乐,“十”是个位数已终了的数,合起来表示音乐完毕。本义:音乐的一曲)。"}, {"meaning": "同本义。今称“乐章”。", "cites": [{"t": "章,乐竟为一章。", "b": "《说文》"}, {"t": "读乐章。", "b": "《礼记·曲礼》。疏:“谓乐书之篇章。”"}, {"t": "诵明月之诗,歌窈窕之章。", "b": "苏轼《前赤壁赋》"}, {"t": "王乃为歌诗四章,令乐人歌之。", "b": "《史记·吕太后本纪》"}], "words": [{"w": "章夏", "t": "古代乐章名。“九夏”之一。"}]}, {"meaning": "棵;根。", "cites": [{"t": "山居千章之材。", "b": "《史记·货殖列传》"}]}, {"meaning": "在绘画或刺绣上,赤与白相间的花纹叫“章”。", "cites": [{"t": "青与赤谓之文,赤与白谓之章。", "b": "《周礼·考工记》注"}, {"t": "永州之野产异蛇,黑质而白章。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "章采", "t": "花纹和色彩"}, {"w": "章服", "t": "按官品而花饰不同的官服"}, {"w": "章绂", "t": "标志官品等级的彩色绶带等饰物"}, {"w": "章黼", "t": "鲜明的黑白花纹"}, {"w": "章绣", "t": "华丽的刺绣品。"}]}, {"meaning": "红白相间的丝织品。", "cites": [{"t": "终日不成章,泣涕零如雨。", "b": "《古诗十九首》"}]}, {"meaning": "文章。诗歌的段落。亦指文章的段或篇。", "cites": [{"t": "积句而成章,积章而成篇。", "b": "《文心雕龙》"}, {"t": "言出为论,下笔成章。", "b": "《三国志·陈思王植传》"}, {"t": "《缁衣》章。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "章什", "t": "指诗歌的篇章"}, {"w": "章指", "t": "于每篇文章之末,总括其大义,或用韵语写成,称为章指"}, {"w": "章句", "t": "文章的段落称章;词意完整,可以成言的称句"}, {"w": "章回小说", "t": "以章回分段叙事的长篇小说"}, {"w": "章句小儒", "t": "指不能通达大义而拘泥于辨析章句的小儒生。"}]}, {"meaning": "法规;规章。", "cites": [{"t": "王风哀以思,周道荡无章。", "b": "南朝宋·谢瞻《张子房》"}], "words": [{"w": "章条", "t": "章程;规则"}, {"w": "章度", "t": "程式"}, {"w": "章宪", "t": "国家的规章法令。"}]}, {"meaning": "法律条目。", "cites": [{"t": "与父老约法三章耳。", "b": "《史记·高祖本纪》"}], "words": [{"w": "约法三章;简章;党章", "t": ""}]}, {"meaning": "印章。", "cites": [{"t": "又用篆章一。", "b": "明·魏学《核舟记》"}, {"t": "家藏伪章。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "公章;图章;私章;章印", "t": "指官印"}, {"w": "章组", "t": "官印以及佩带"}, {"w": "章绶", "t": "官印和系印的丝带。"}]}, {"meaning": "标记;徽章。", "cites": [{"t": "分为五选,异其旗章,勿使冒乱。", "b": "汉·刘向《说苑》"}], "words": [{"w": "章表", "t": "标记;象征。"}]}, {"meaning": "指旌旗。", "cites": [{"t": "变非声章,弗能移也。", "b": "韦昭注:“章,旌旗也。”"}], "words": [{"w": "章旗", "t": "绣有徽号的旗帜。"}]}, {"meaning": "奏章,臣下呈给皇上的书面报告。", "cites": [{"t": "章以谢恩,奏以按劾,表以陈情,议以执异。", "b": "《文心雕龙》"}, {"t": "温《缁衣》一章。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "章奏", "t": "汉制,群臣上书有章、奏、表、驕议之别,后则通称臣子上陈给皇帝的文件为章奏"}, {"w": "章疏", "t": "臣下向君上进呈的言事文书"}, {"w": "章满公车", "t": "形容奏章之多。"}]}, {"meaning": "大木材。", "cites": [{"t": "东园主章。", "b": "《汉书·百官公卿表》"}]}, {"meaning": "彰明,明显,显著。", "cites": [{"t": "平章百姓。", "b": "《书·尧典》"}, {"t": "赏罚无章。", "b": "《左传·襄公二十七年》。疏:“章,明也。”"}, {"t": "而尧舜之所以章也。", "b": "《吕氏春秋·知度》"}, {"t": "钟之与磬也,近之则钟音充,远之则磬音章。", "b": "《淮南子》"}], "words": [{"w": "章灼", "t": "明白显著。光辉照耀"}, {"w": "章章", "t": "显明的样子。同“彰彰”"}, {"w": "章然", "t": "明显的样子。"}]}, {"meaning": "条理化。", "cites": [{"t": "其为言也,杂乱而无章。", "b": "韩愈《送孟东野序》"}]}, {"meaning": "显示;表明。", "cites": [{"t": "且夫兄弟之怨,不徵於他,利乃外矣。章怨外利,不义。", "b": "《国语·周语中》。韦昭注:“章,明也。”"}], "words": [{"w": "章著", "t": "显露;分明"}, {"w": "章理", "t": "显明的道理"}, {"w": "章视", "t": "明示;诏告。"}]}, {"meaning": "彰明,表彰。", "cites": [{"t": "章之以论,禁之以刑。", "b": "《荀子》"}], "words": [{"w": "章明", "t": "显扬"}, {"w": "章闻", "t": "传闻;著闻。"}]}, {"meaning": "上奏章告发。", "cites": [{"t": "被诏书为将作大匠,为受罚者所章,拜议郎。", "b": "汉·蔡邕《太尉乔公碑》"}], "words": [{"w": "章表", "t": "奏表"}, {"w": "章书", "t": "奏章"}, {"w": "章左", "t": "指奏章终了空白处"}, {"w": "章报", "t": "具奏章上报。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2390wx','竟','1','jìng','立','11','','[{"pinyin": "jìng", "defs": [{"meaning": "(会意。从音,从人。本义:奏乐完毕)。"}, {"meaning": "同本义。", "cites": [{"t": "竟,乐曲尽为竟。", "b": "《说文》"}, {"t": "凡乐成则告备。", "b": "《周礼》。汉·郑玄注:“成,谓所奏一竟。”"}]}, {"meaning": "泛指结束,完毕。", "cites": [{"t": "竟,终也。", "b": "《玉篇》"}, {"t": "竟,穷也。", "b": "《广雅》"}, {"t": "谮始竟背。", "b": "《诗·大雅·瞻卬》。笺:“犹终也。”"}, {"t": "振于无竟。", "b": "《庄子·齐物论》"}, {"t": "秦王竟酒。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "语竟。", "b": "唐·李朝威《柳毅传》"}, {"t": "不能竟书而欲搁笔。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "竟学", "t": "学完,学到底"}, {"w": "未竟之业;事竟", "t": ""}]}, {"meaning": "追究。", "cites": [{"t": "此县官重太后,故不竟也。", "b": "《汉书》"}]}, {"meaning": "终于;到底。", "cites": [{"t": "平原君竟与毛遂偕。", "b": "《史记·平原君虞卿列传》"}, {"t": "竟怒不救楚。", "b": "《史记·屈原贾生列传》"}, {"t": "竟无语凝噎。", "b": "宋·柳永《雨霖铃》"}, {"t": "婿竟不调。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}]}, {"meaning": "竟然;倒。含出乎意料之意。", "cites": [{"t": "竟杀蛟而出。", "b": "《世说新语·自新》"}], "words": [{"w": "竟尔", "t": "竟自。竟然"}, {"w": "竟是", "t": "还是,毕竟是"}, {"w": "竟不然", "t": "何不,倒不如。"}]}, {"meaning": "全部;完全;整个。", "cites": [{"t": "恩施下竟同学。", "b": "《汉书·王莽传》。注:“周徧也。”"}, {"t": "君竟日不出门。", "b": "清·梁启超《谭嗣同传》"}, {"t": "竟三夜罢。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "竟以宗庙社稷。", "b": "清·周容《芋老人传》"}, {"t": "竟成痼疾。", "b": "清·方苞《狱中杂记》"}, {"t": "竟行之。", "b": ""}], "words": [{"w": "竟天", "t": "满天"}, {"w": "竟天价", "t": "满天地"}, {"w": "竟体", "t": "全身"}, {"w": "竟夕", "t": "整夜,整个晚上"}, {"w": "竟世", "t": "终生;一辈子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2391wx','商','1','shāng','口','11','','[{"pinyin": "shāng", "defs": [{"meaning": "(会意。从阩,章省声。本义:计算,估量)。"}, {"meaning": "同本义。", "cites": [{"t": "商,从外知内也。", "b": "《说文》。段注:“汉律志云:商之言章也。物成熟可章度也。”"}, {"t": "商,度也。", "b": "《广雅》"}, {"t": "虏必商军进退,稍引去。", "b": "《汉书·赵充国传》"}], "words": [{"w": "商略", "t": "估计"}, {"w": "商算", "t": "计算"}, {"w": "商度", "t": "测量"}, {"w": "商羊", "t": "传说中一种能预知雨的鸟"}, {"w": "商谜", "t": "猜谜"}, {"w": "商功", "t": "古代九章算术之一,即测量体积、计算工程用工的方法。"}]}, {"meaning": "引申为商议,商讨;商量。", "cites": [{"t": "商兑。", "b": "《易·兑》。注:“商量裁判之谓也。”"}, {"t": "操与众商议,欲立植为世子。", "b": "《三国演义·杨修之死》"}], "words": [{"w": "商通", "t": "勾通;相互商量以取得一致意见"}, {"w": "协商;商校", "t": "商度,衡量"}, {"w": "商串", "t": "商量串通"}, {"w": "商决", "t": "商量决定"}, {"w": "商宜", "t": "商量如何处理"}, {"w": "商订", "t": "商讨订正"}, {"w": "商借", "t": "商量借用"}, {"w": "商通", "t": "彼此商量并取得一致意见"}, {"w": "商论", "t": "磋商讨论"}, {"w": "商略", "t": "商讨。"}]}, {"meaning": "经商,贩卖货物。", "cites": [{"t": "商旅不行。", "b": "《易·复》"}, {"t": "商而无盈。", "b": "王充《论衡》"}], "words": [{"w": "商市", "t": "买卖货物的场所。"}]}, {"meaning": "揣测,臆度。", "cites": [{"t": "巧商而善意,广见而多记。", "b": "王充《论衡》"}]}, {"meaning": "商业。", "cites": [{"t": "商不出,则三宝绝。", "b": "《史记·货殖列传序》"}], "words": [{"w": "经商;商利", "t": "经商的利润"}, {"w": "商道", "t": "通商的道路"}, {"w": "商铺", "t": "商店"}, {"w": "商棍", "t": "商界的不良分子。"}]}, {"meaning": "商人。", "cites": [{"t": "郑商人弦高将市于周。", "b": "《左传·僖公三十三年》"}, {"t": "商人重利轻别离,前月浮梁买茶去。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "商贾皆欲藏于王之市。", "b": "《孟子·梁惠王上》"}, {"t": "豪吏富商积货储物以待其急。", "b": "《盐铁论·本议》"}], "words": [{"w": "布商;坐商;商凭", "t": "商人的营业证"}, {"w": "商民", "t": "商贾,商沽。商人。"}]}, {"meaning": "秋季 。古人把五音与四季相配,商音配秋,因以商指秋季。"}, {"meaning": "春秋时诸侯国宋的别称 。周灭商后,封商贵族微子的后代于宋,故宋又称商。"}, {"meaning": "象声词。铃摇击的声音。", "cites": [{"t": "胜姑便将两手七铃同时取起,商商价乱摇。", "b": "《老残游记》"}]}, {"meaning": "星宿名,指心宿。", "cites": [{"t": "人生不相见,动如参与商。", "b": "杜甫《赠卫八处士》"}]}, {"meaning": "篇章,乐竟为一章,引申为诗文的篇章。", "cites": [{"t": "修宪命,审诗商,禁淫声,以时顺修,使夷俗邪音不敢乱雅,太师之事也。", "b": "《荀子·王制》"}, {"t": "观民风俗,审诗商,命禁邪言,息淫声。", "b": "汉·贾谊《新书·辅佐篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2392wx','族','1','zú','方','11','','[{"pinyin": "zú", "defs": [{"meaning": "(会意。本义:箭头)。"}, {"meaning": "同本义。", "cites": [{"t": "族,矢锋也。束之族族也。", "b": "《说文》。"}]}, {"meaning": "家族,氏族。", "cites": [{"t": "克明俊德,以亲九族。", "b": "《书·尧典》。陆德明释文:“上自高祖,下至玄孙,凡九族。”"}], "words": [{"w": "大族", "t": "人口多、分支繁的家族"}, {"w": "族氏", "t": "宗族姓氏"}, {"w": "族正", "t": "清时聚族而居的地方;挑选族中地位名望最高的人主持和裁决本族事务,名为“族正”。"}]}, {"meaning": "姓氏,表明家族、宗族系统的称号。", "cites": [{"t": "亡秦族矣。", "b": "汉·贾谊《过秦论》"}, {"t": "其诗以养父母、收族为意。(收:聚,团结)", "b": "宋·王安石《伤仲永》"}, {"t": "繁衍之族。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "族地", "t": "一姓一族的土地"}, {"w": "族姓", "t": "同姓的亲族;家族姓氏;世族大姓。"}]}, {"meaning": "古代百家为一族。", "cites": [{"t": "四闾为族,使之相葬。", "b": "《周礼》。郑玄注:“闾,二十五家;族,百家。”"}], "words": [{"w": "族长", "t": ""}]}, {"meaning": "品类,种类。", "cites": [{"t": "士大夫之族。", "b": "唐·韩愈《师说》"}, {"t": "莫不族布。", "b": "明·刘基《诚意伯刘文成公文集》"}]}, {"meaning": "筋骨交错聚结的地方。", "cites": [{"t": "每至于族,吾见其难为,怵然为戒。", "b": "《庄子·养生主》"}]}, {"meaning": "灭族。把。", "cites": [{"t": "族秦者,秦也,非天下也。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "族诛", "t": "族灭。一人犯罪,整个家族、亲属被诛灭。"}]}, {"meaning": "丛聚。", "cites": [{"t": "云气不待族而雨,草木不待黄而落。", "b": "《庄子》"}], "words": [{"w": "族生", "t": "丛生"}, {"w": "族居", "t": "群居;聚居"}, {"w": "族云", "t": "凝聚的云气。"}]}, {"meaning": "众多。", "cites": [{"t": "行久之物,族必起于少", "b": "《韩非子·喻老》"}], "words": [{"w": "族庖", "t": "众庖。指一般的厨师。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2393wx','旋','1','xuán xuàn','方','11','','[{"pinyin": "xuán", "defs": [{"meaning": "同本义。", "cites": [{"t": "旋,周旋,旌旗之指麾也。", "b": "《说文》"}, {"t": "旋入雷渊。", "b": "《楚辞·招魂》。注:“旋,转也。”"}, {"t": "旋式正綦。", "b": "《史记·日者列传》。索隐:“旋,转也。”"}, {"t": "鲵旋之潘为渊。", "b": "《列子·黄帝》。注:“旋,谓盘旋也。”"}, {"t": "湍濑旋渊吕梁之深。", "b": "《淮南子·俶真》"}, {"t": "水深则回。", "b": "《荀子·致士》。注:“回,旋流也。水深不湍峻则多旋流也。”"}, {"t": "周旋中规,折旋中矩。", "b": "《礼记·玉藻》"}, {"t": "周旋序顺。", "b": "《国语·周语》。注:“周旋,容止也。”"}, {"t": "列星随旋,日月递炤。", "b": "《荀子·天论》"}], "words": [{"w": "旋辟", "t": "进退周旋,环绕"}, {"w": "旋式", "t": "转动罗盘"}, {"w": "旋弄", "t": "转动摆弄"}, {"w": "旋盘", "t": "转碟。"}]}, {"meaning": "返回或归来。", "cites": [{"t": "旋,还也。", "b": "《小尔雅》"}, {"t": "旋,回也。", "b": "《字林》"}, {"t": "桃今与楼齐,我行尚未旋。", "b": "李白《寄东鲁二稚子》"}], "words": [{"w": "旋盖", "t": "重新盖造"}, {"w": "旋止", "t": "归来"}, {"w": "旋仅", "t": "回归"}, {"w": "旋走", "t": "来回走动。"}]}, {"meaning": "绕行。", "cites": [{"t": "绕日而疾旋。", "b": "清·谭嗣同《仁学上》"}], "words": [{"w": "旋曲", "t": "盘旋曲折"}, {"w": "旋行", "t": "回旋而行"}, {"w": "旋折", "t": "盘旋曲折。"}]}, {"meaning": "小便。", "cites": [{"t": "夷射姑旋焉。", "b": "《左传·定公三年》"}], "words": [{"w": "旋便", "t": "小便"}, {"w": "旋溷", "t": "大小便。"}]}, {"meaning": "圆。", "cites": [{"t": "工倕旋而盖规矩,指与物化而不以心稽。", "b": "《庄子》"}], "words": [{"w": "旋阑儿", "t": "圆领大袖的衣衫。"}]}, {"meaning": "圈儿。", "cites": [{"t": "[燕青] 借力便旋四、五旋,旋到献台边。", "b": "《水浒全传》"}], "words": [{"w": "手掌上的老茧一旋又一旋", "t": ""}]}, {"meaning": "东汉时地名,即“旋门关” 。故址在今河南省荥阳县西汜水镇西南。"}, {"meaning": "立即,随即。", "cites": [{"t": "憔悴孤虚,旋生旋灭。", "b": "《天演论·察变》"}, {"t": "黠鼠伺我侧,乍去旋来归。", "b": "清·张际亮《石亭》"}, {"t": "旋改为满。", "b": "宋·洪迈《容斋续笔》"}, {"t": "旋刻之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "旋升宁夏道。", "b": "清·梁启超《谭嗣同传》"}, {"t": "旋见一白酋督印度卒约百人。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "旋日", "t": "一日之间"}, {"w": "旋而", "t": "顷刻,不久"}, {"w": "旋葬", "t": "随即安葬"}, {"w": "旋得旋失", "t": "很快地得与失。"}]}, {"meaning": "同时进行。", "cites": [{"t": "深锁雷门宴上才,旋看歌舞旋传杯。", "b": "唐·章碣《陪浙西王侍郎夜宴》"}], "words": [{"w": "旋蒸热卖", "t": "即“现蒸现卖”或“现砍现装”。谓平时不关心,但为了某种目的,就临时表现得非常热情。"}]}, {"meaning": "逐渐。", "cites": [{"t": "东风千树易老,怕红颜旋减,芳意偷变。", "b": "宋·周密《齐天乐》"}]}, {"meaning": "随意,漫然。", "cites": [{"t": "好鞍好马乞与人,十千五千旋沽酒。", "b": "李白《少年行》"}]}, {"meaning": "姓。"}]}, {"pinyin": "xuàn", "defs": [{"meaning": "转轴。", "cites": [{"t": "绦旋光堪摘,轩楹势可呼。", "b": "唐·杜甫《画鹰》"}]}, {"meaning": "温酒器。通称“旋子”。", "cites": [{"t": "旋,温器也,旋之汤中以温酒。", "b": "元·戴侗《六书故》"}]}, {"meaning": "茶炊。", "cites": [{"t": "小可是卖茶的,今日烧得这旋锅儿热了,看有甚么人来。", "b": "元·秦简夫《东堂老》"}]}, {"meaning": "铜锡盘。", "cites": [{"t": "常熟丘郡家食橱内,锡旋置熟鸡半只。", "b": "明·冯梦龙《古今谭概》"}]}, {"meaning": "回旋着切削。", "cites": [{"t": "[旋]谓以绳转轴裁木为器者也。", "b": "三国魏·周成《难字》"}], "words": [{"w": "旋工", "t": ""}]}, {"meaning": "用旋温酒。", "cites": [{"t": "老王,这酒寒,快旋热酒来。", "b": "元·康进之《李逵负荆》"}]}, {"meaning": "屡次,常常。", "cites": [{"t": "剧谈频剪烛,久坐旋更衣。", "b": "陆游《夜兴》"}], "words": [{"w": "旋旋", "t": "频频。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2394wx','望','1','wàng','月','11','','[{"pinyin": "wàng", "defs": [{"meaning": "(会意。甲骨文字形,上面是“臣”象眼睛,下面是“壬”(tǐng)。象一个人站在土地上远望。小篆又加“月”字,表望的对象。本义:远望)。"}, {"meaning": "同本义。", "cites": [{"t": "望,出亡在外望其还也。", "b": "《说文》。按,此字疑当训远视也。"}, {"t": "望,远视也。", "b": "《玉篇》"}, {"t": "豕望视而交睫腥。", "b": "《礼记·内则》。注:“望视,远视也。”"}, {"t": "邻邑相望,鸡狗之音相闻。", "b": "《庄子·胠箧》"}, {"t": "望之而不能见也,逐之而不能及也。", "b": "《庄子·天运》"}, {"t": "吾尝跂而望矣,不如登高之博见也。", "b": "《荀子·劝学》"}, {"t": "扁鹊望桓侯。", "b": "《韩非子·喻老》"}, {"t": "举头望明月。", "b": "唐·李白《静夜思》"}, {"t": "风烟望五津。", "b": "唐·王勃《杜少府之任蜀州》"}, {"t": "潭西南而望。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "望台", "t": "指轮船驾驶台"}, {"w": "望楼", "t": "望远守卫的楼房"}, {"w": "望阙", "t": "望着皇宫"}, {"w": "望乞", "t": "希望;乞求"}, {"w": "望国", "t": "遥望故国"}, {"w": "望睹", "t": "了望,眺望"}, {"w": "望乡", "t": "遥望故乡"}, {"w": "望祭", "t": "望礼。遥望而祭"}, {"w": "望拜", "t": "远远望见即行叩拜"}, {"w": "望祀", "t": "遥望祭祀"}, {"w": "望眼", "t": "远眺的眼睛。"}]}, {"meaning": "遥祭,指古代帝王祭祀山川、日月、星辰。", "cites": [{"t": "旅上帝及四望。", "b": "《周礼·大宗伯》。注:“五岳四镇四渎。”"}, {"t": "犹三望。", "b": "《左传·僖公三十一年》。注:“分野之星,国中山川皆因郊祀,望而祭之。”"}], "words": [{"w": "望祀", "t": "古代遥祭山川地袛之礼"}, {"w": "望拜", "t": "遥望拜祭"}, {"w": "望表", "t": "古代祭祀山川时所立的木制标志。"}]}, {"meaning": "希望,期望。", "cites": [{"t": "日夜望将军至,岂敢反乎?", "b": "《史记·项羽本纪》"}, {"t": "王如知此,则无望民之多于邻国也。", "b": "《孟子·梁惠王上》"}, {"t": "非汉所望。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "望岁", "t": "盼望丰收"}, {"w": "望祈", "t": "盼望"}, {"w": "望幸", "t": "臣民、妃嫔希望皇帝临幸"}, {"w": "望巴巴", "t": "望眼巴巴。"}]}, {"meaning": "看望。", "cites": [{"t": "望其言是实。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "探望;拜望;看望", "t": ""}]}, {"meaning": "比较。", "cites": [{"t": "以人望人,则贤者可知己矣。", "b": "《礼记·表记》"}]}, {"meaning": "怨恨,责怪。", "cites": [{"t": "绛侯望袁盎。", "b": "《史记·袁盎晁错传》"}, {"t": "时人望之。", "b": "《后汉书·贾彪传》"}, {"t": "不意君望臣深也。", "b": "《史记·张耳陈馀传》"}, {"t": "黯褊心,不能无少望。", "b": "《汉书·汲黯传》"}], "words": [{"w": "望沮", "t": "怨恨沮丧"}, {"w": "望言", "t": "怨言。"}]}, {"meaning": "接近。", "cites": [{"t": "望秋先陨。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "望七", "t": "将至七十岁"}, {"w": "望五", "t": "年龄近五十岁"}, {"w": "望四", "t": "接近四十岁"}, {"w": "望秋", "t": "临近秋天。"}]}, {"meaning": "名望。", "cites": [{"t": "德隆望尊。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "望轻", "t": "声望低微"}, {"w": "德高望重;望姓", "t": "有声望的氏族"}, {"w": "望重", "t": "名望大"}, {"w": "望臣", "t": "有威望的大臣"}, {"w": "望雅", "t": "声望清高。"}]}, {"meaning": "希望;盼望。", "cites": [{"t": "以绝秦望。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "甚失孤望。", "b": "《资治通鉴》"}]}, {"meaning": "望日,夏历每月十五,天文学上指月亮圆的那一天。", "cites": [{"t": "三月之望。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "望后", "t": "望日之后;向后"}, {"w": "望夜", "t": "农历十五日之夜。"}]}, {"meaning": "边际。", "cites": [{"t": "神覆宇宙而无望。", "b": "《吕氏春秋·下贤》"}]}, {"meaning": "仪容。", "cites": [{"t": "季通弟季良风望闲雅。", "b": "《北史》"}]}, {"meaning": "有名的人。", "cites": [{"t": "吾子楚国之望也。", "b": "《左传·昭公十二年》"}]}, {"meaning": "窗口。", "cites": [{"t": "[画轮车]左右开四望。", "b": "《晋书》"}]}, {"meaning": "唐代行政区划的等级之一。", "cites": [{"t": "文宗世,宰相韦处厚建议,复置两辅、六雄、十望、十紧州别驾。", "b": "《新唐书》"}], "words": [{"w": "望前走", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2395wx','率','1','lǜ shuài','玄','11','','[{"pinyin": "lǜ", "defs": [{"meaning": "规格;标准。", "cites": [{"t": "有军功者,各以率受上爵。", "b": "《史记》"}]}, {"meaning": "古重量名。", "cites": [{"t": "其罚百率。", "b": "《史记·周本纪》"}]}]}, {"pinyin": "shuài", "defs": [{"meaning": "(象形。甲骨文字形,象捕鸟的丝网。本义:捕鸟的丝网)。"}, {"meaning": "同本义。", "cites": [{"t": "率,捕鸟毕也。", "b": "《说文》。象丝网上下其竿柄也。"}]}, {"meaning": "榜样;表率;楷模。", "cites": [{"t": "刺史,古之方伯,上所委任,一州表率也。", "b": "班固《汉书·何武传》"}], "words": [{"w": "率下", "t": "作为下属表率"}, {"w": "率示", "t": "示范,作为榜样"}, {"w": "率物", "t": "做众人的榜样"}, {"w": "率身", "t": "自身作出榜样"}, {"w": "率时", "t": "为时人的表率"}, {"w": "率众", "t": "为众人表率"}, {"w": "率导", "t": "以自身的表率行为对他人进行教导。"}]}, {"meaning": "领导者,统帅,首领。", "cites": [{"t": "将率不能,则兵弱。", "b": "《荀子·富国》"}, {"t": "率师以来,惟敌是求。", "b": "《左传·宣公十二年》"}, {"t": "将率不亲,士卒不使。", "b": "《春秋繁露·五行相胜》"}, {"t": "王之将率有如子路者乎?", "b": "《史记·孔子世家》"}, {"t": "贪鄙在率不在下,教训在政不在民也。", "b": "《盐铁论·疾贪》"}]}, {"meaning": "部队。", "cites": [{"t": "[葛洪]攻[石]冰别率,破之。", "b": "房玄龄《晋书》"}]}, {"meaning": "用网捕鸟兽。", "cites": [{"t": "悉率百禽。", "b": "《文选·张衡》"}, {"t": "东京赋", "b": ""}]}, {"meaning": "率领;带领", "cites": [{"t": "方叔率止。", "b": "《诗·小雅·采芑》"}, {"t": "将军身率益州之众出于秦川。", "b": "《三国志·诸葛亮传》"}, {"t": "瑜等率轻锐继其后,雷鼓大震,北军大坏。", "b": "《资治通鉴》"}], "words": [{"w": "率师", "t": "率领军队"}, {"w": "率俾", "t": "率领"}, {"w": "率众", "t": "率领众人"}, {"w": "率将", "t": "带领"}, {"w": "率勒", "t": "统率"}, {"w": "率厉", "t": "率领督促"}, {"w": "率御", "t": "统御,统率指挥"}, {"w": "率导", "t": "率领"}, {"w": "率道", "t": "领导。"}]}, {"meaning": "劝导;引导。", "cites": [{"t": "周仁(言行合乎仁)之谓信,率义之谓勇。", "b": "《左传·哀公十六年》"}, {"t": "不愆不忘,率由旧章。", "b": "《诗·大雅·假乐》"}], "words": [{"w": "率勉", "t": "劝勉"}, {"w": "率厉", "t": "激励;勉励"}, {"w": "率民", "t": "引导百姓"}, {"w": "率俗", "t": "对某种社会风气加以引导提倡。"}]}, {"meaning": "遵行;遵循。", "cites": [{"t": "率由旧章。", "b": "《诗·大雅·假乐》"}, {"t": "率由群匹。", "b": ""}, {"t": "然一家之中有子弟十人,其不率教者常有一二。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "率常", "t": "遵行常道"}, {"w": "率从", "t": "依循,顺从"}, {"w": "率教", "t": "遵奉礼教"}, {"w": "率履", "t": "遵行礼教,躬行教令"}, {"w": "率由", "t": "遵循,沿用"}, {"w": "率法", "t": "遵循法度。"}]}, {"meaning": "沿着;顺着。", "cites": [{"t": "率西水浒,至于岐下。", "b": "《诗·大雅·绵》"}, {"t": "此吾所以敢率性就死不顾汝也。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "率口", "t": "随口;顺口"}, {"w": "率心", "t": "任其心意"}, {"w": "率任", "t": "任性;放纵"}, {"w": "率情", "t": "任意;犹秉性;顺其性情;徇情。"}]}, {"meaning": "顺服;顺从。", "cites": [{"t": "时率意独驾,不由径路。", "b": "《晋书·阮籍传》"}], "words": [{"w": "率服", "t": "全来归顺;臣服"}, {"w": "率化", "t": "归顺"}, {"w": "率俾", "t": "顺从"}, {"w": "率从", "t": "顺从;跟从。"}]}, {"meaning": "类似。", "cites": [{"t": "故其著书十余万言,大抵率寓言也。", "b": "《史记》"}]}, {"meaning": "草率:轻率。", "cites": [{"t": "子路率尔而对。", "b": "《论语·先进》"}], "words": [{"w": "率尔", "t": "轻率的样子"}, {"w": "粗率", "t": "粗略草率"}, {"w": "率成", "t": "草率写成"}, {"w": "率民", "t": "轻浮之民"}, {"w": "率易", "t": "轻率,随便"}, {"w": "率略", "t": "草率;粗俗,疏忽"}, {"w": "率笔", "t": "犹败笔"}, {"w": "率就", "t": "轻易而就;随便。"}]}, {"meaning": "急速。", "cites": [{"t": "凉风率已厉,游子寒无衣。", "b": "《古诗十九首》"}], "words": [{"w": "率悟", "t": "捷悟,敏悟"}, {"w": "率健", "t": "敏捷健壮。"}]}, {"meaning": "直率;坦率。", "cites": [{"t": "率心奉上,不顾嫌疑。", "b": "《魏书·张衮传》"}], "words": [{"w": "率素", "t": "质实朴素"}, {"w": "率至", "t": "爽直;直率"}, {"w": "率易", "t": "率直平易"}, {"w": "率意", "t": "直率,按照本意"}, {"w": "率达", "t": "坦率豁达"}, {"w": "率躁", "t": "率直急躁"}, {"w": "率实", "t": "坦率真实。"}]}, {"meaning": "粗鲁。", "cites": [{"t": "气高语率,令人自远。", "b": "明·袁宏道《谢于楚历山草引》"}]}, {"meaning": "皆,都。", "cites": [{"t": "或曰:“六国互丧,率赂秦耶?”", "b": "宋·苏洵《权书·六国论》"}], "words": [{"w": "率天", "t": "犹普天"}, {"w": "率土式望", "t": "全国百姓翘首盼望"}, {"w": "率同", "t": "一同;共同"}, {"w": "率皆", "t": "都是。"}]}, {"meaning": "大约,大概。", "cites": [{"t": "大率用根者,若有宿根,须取无茎叶时采。", "b": "宋·沈括《梦溪笔谈》"}]}, {"meaning": "一般说来。", "cites": [{"t": "案大才之人,率多侈纵,无实事之验。", "b": "汉·王充《论衡·案书》"}]}, {"meaning": "自,由,从。", "cites": [{"t": "溥天之下,莫非王土。率土之滨,莫非王臣。", "b": "《诗·小雅·北山》"}], "words": [{"w": "率土", "t": "“率土之滨”之省称"}, {"w": "率由", "t": "由来;犹皆由"}, {"w": "率初", "t": "自始"}, {"w": "率幸", "t": "一向受到宠信。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2396wx','阎','1','yán','门','11','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从门,臽(xiàn)声。本义:内巷内的门,亦指里巷)。"}, {"meaning": "同本义。", "cites": [{"t": "閻,里中门也。", "b": "《说文》"}, {"t": "隐于穷阎漏屋。", "b": "《荀子·儒效》。注:“里门也。”"}, {"t": "兴于闾阎。", "b": "《汉书·循吏传》注"}, {"t": "便旋闾阎。", "b": "张衡《西京赋》。注:“里中门曰阎。”"}], "words": [{"w": "阎闾", "t": "里巷内外的门"}, {"w": "阎术", "t": "里巷"}, {"w": "阎亲", "t": "乡亲。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2397wx','阐','1','chǎn','门','11','','[{"pinyin": "chǎn", "defs": [{"meaning": "(形声。从门,单声。本义:开,打开)。"}, {"meaning": "同本义。", "cites": [{"t": "阐,开也。", "b": "《说文》"}, {"t": "看山倚前户,待月阐东扉。", "b": "唐·白居易诗"}]}, {"meaning": "开辟;开拓。", "cites": [{"t": "阐并天下。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "阐辟", "t": "开辟,开拓"}, {"w": "阐拓", "t": "开拓。"}]}, {"meaning": "讲明白。", "cites": [{"t": "隐则胜阐矣。", "b": "《吕氏春秋·决胜》"}], "words": [{"w": "阐证", "t": "阐述证明"}, {"w": "阐综", "t": "阐明综合"}, {"w": "阐择", "t": "阐明辨别。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2398wx','着','1','zhāo zháo zhe zhuó','目','11','','[{"pinyin": "zhāo", "defs": [{"meaning": "(著的俗字)。"}, {"meaning": "放置。", "cites": [{"t": "文成示温,温以着坐处。", "b": "晋·陶潜《晋故西征大将军长史孟府君传》"}], "words": [{"w": "着盐", "t": "搁盐;炒菜放盐"}, {"w": "板上着碗", "t": ""}]}, {"meaning": "安顿。", "cites": [{"t": "更有南堂堪着客,不忧门外故人车。", "b": "宋·苏轼《南堂》"}]}, {"meaning": "围棋的下子;下棋落子。", "cites": [{"t": "某有仆能棋,欲试数着不敢?", "b": "元·蒋正子《山房随笔》"}], "words": [{"w": "棋高一着;高着", "t": ""}]}, {"meaning": "为达到某种目的而采取的一步;策略。", "cites": [{"t": "三十六着,走为上着。", "b": "《水浒传》"}], "words": [{"w": "失着", "t": "失策"}, {"w": "着儿", "t": "计策;手段"}, {"w": "着着", "t": "一步一步地,逐渐地;亦指样样;每一样"}, {"w": "三十六着,走为上着", "t": ""}]}, {"meaning": "是;对 。用于答语,表示同意。", "cites": [{"t": "着!着!着!就是这么着。", "b": "《儿女英雄传》"}], "words": [{"w": "着,咱们就这么办", "t": ""}]}]}, {"pinyin": "zháo", "defs": [{"meaning": "(著的俗字)。"}, {"meaning": "燃烧。", "cites": [{"t": "以火煮令一着一灭。", "b": "《物类相感志》"}], "words": [{"w": "火着得很旺;着火点", "t": "可燃物质开始燃烧时所需要的最低温度。"}]}, {"meaning": "遇;受到。", "cites": [{"t": "庭花着雨晴方见,野客叩门去始知。", "b": "宋·陆游《午寝》"}], "words": [{"w": "着雨;着水;着恼", "t": "生气;发怒"}, {"w": "着疑", "t": "怀疑;起疑心。"}]}, {"meaning": "觉得。", "cites": [{"t": "惟有垂泪,十分着急。", "b": "《镜花缘》"}], "words": [{"w": "为此着恼;越寻思越着昏", "t": ""}]}, {"meaning": "中,恰好合上。", "cites": [{"t": "依方位,百下百着。", "b": "《西游记》"}], "words": [{"w": "着手", "t": "上当,落入圈套"}, {"w": "着道儿", "t": "中计;上当"}, {"w": "着魔", "t": "比喻迷恋某种事物到了几乎失去理智的地步。"}]}, {"meaning": "得当,对。", "cites": [{"t": "只因用人不着,半路被贼人劫将去了。", "b": "《水浒全传》"}]}, {"meaning": "用在动词后,表示已经达到目的或有了结果。", "cites": [{"t": "鸡猪鱼蒜,逢着就吃;生老病死,时至则行。", "b": "《因话录》"}], "words": [{"w": "猜着了;打着了", "t": ""}]}]}, {"pinyin": "zhe", "defs": [{"meaning": "(著的俗字)。"}, {"meaning": "用在谓语之后,表示动作正在进行或状态的持续。", "cites": [{"t": "道着姓名人不识。", "b": "唐·白居易《恻恻吟》"}], "words": [{"w": "他们正说着话呢;门敞着", "t": ""}]}, {"meaning": "用在句末,表示命令、祈使或一般告语。", "cites": [{"t": "这短命,等得我苦也!老娘先打两个耳刮子着。", "b": "《水浒全传》"}], "words": [{"w": "听着;快着点儿", "t": ""}]}, {"meaning": "用在某些名词后,表示“呢”。", "cites": [{"t": "吾师,你却如何正等得这贼首着?", "b": "《水浒传》"}]}]}, {"pinyin": "zhuó", "defs": [{"meaning": "(着为著的俗字)。"}, {"meaning": "穿。", "cites": [{"t": "恂常私着胡服。", "b": "《资治通鉴》"}, {"t": "将军角弓不得控,都护铁衣冷难着。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "说着了小服,从西门进来了。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "着衣", "t": "穿衣"}, {"w": "着绯", "t": "穿红色官服。古代官服颜色不同,表示官吏品级的高低。唐制四品服深绯,五品服浅绯。后常以“著绯”指当了中级官员。"}]}, {"meaning": "附着;加…于上。", "cites": [{"t": "血脉不复归,必燥着母脊。", "b": "《三国志·方伎传》"}, {"t": "今殴民而归之农,皆著于本。", "b": "汉·贾谊《论积贮疏》"}, {"t": "始欲着推字。", "b": "宋·胡仔《苕溪渔隐丛话》"}]}, {"meaning": "又。", "cites": [{"t": "又欲着敲字。", "b": ""}, {"t": "手足无可着处。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "着生植物", "t": "植物学名词。即附生植物"}, {"w": "着浅", "t": "搁浅。"}]}, {"meaning": "接触;挨上。", "cites": [{"t": "牧童敲火牛砺角,谁复着手为摩挲。", "b": "韩愈《石鼓歌》"}, {"t": "此手那可使箸贼!", "b": "《世说新语·雅量》"}, {"t": "野船着岸又春草,水鸟带飞夕阳。", "b": "唐·朱庆馀《南湖》"}], "words": [{"w": "着地", "t": "贴着地面"}, {"w": "着末", "t": "撩拨;沾染"}, {"w": "着肉", "t": "贴身"}, {"w": "着莫", "t": "引惹;牵缠"}, {"w": "着脚", "t": "涉足。"}]}, {"meaning": "安置,放置。", "cites": [{"t": "以犀柄尘尾着柩中,因恸绝。", "b": "《世说新语·伤逝》"}, {"t": "新添水槛供垂钓,故着浮槎替入舟。", "b": "杜甫《江上值水如海势》"}]}, {"meaning": "差使;打发。", "cites": [{"t": "姑娘那边这两年不时着人问信。", "b": "《镜花缘》"}, {"t": "蒋爷叫小童着官人将邓车解到知府衙门收入监中。", "b": "《小五义》"}], "words": [{"w": "着叠", "t": "打发"}, {"w": "着人前来领取", "t": ""}]}, {"meaning": "关切。", "cites": [{"t": "怎比得玉天仙知心着意。", "b": "吴昌龄《张天师》"}], "words": [{"w": "着己", "t": "亲近;贴心"}, {"w": "着紧", "t": "紧要;重要;抓紧;赶紧;着意;留意"}, {"w": "着趣", "t": "知趣。"}]}, {"meaning": "生长;增添。", "cites": [{"t": "画蛇着足无处用,两鬓雪白趋尘埃。", "b": "韩愈《感春》"}, {"t": "王伦那厮不肯胡乱着人,因此我们弟兄们看了这船样,一齐都心懒了。", "b": "《水浒传》"}], "words": [{"w": "着迹", "t": "留有痕迹。多用以比喻艺术作品有斧凿之迹而不自然,没有达到浑然一体的境地。"}]}, {"meaning": "用。", "cites": [{"t": "每至公坐,广谈,仲治不能对;退,着笔对广,广又不能答。", "b": "《世说新语·文学》"}, {"t": "江绕屋,水随船,买得风光不着钱。", "b": "徐积《谁学得》"}]}, {"meaning": "开。", "cites": [{"t": "来时绮窗前,寒梅着花未。", "b": "王维《杂诗》"}]}, {"meaning": "结。", "cites": [{"t": "春根夏苗秋着子。", "b": "苏轼《周教授索枸杞因以诗赠》"}]}, {"meaning": "命令 。旧时公文用语。", "cites": [{"t": "着先赴礼部,即照前次试题各补诗赋一卷,仍发誊录。", "b": "《镜花缘》"}, {"t": "老爷大怒,已告知县主,着公差捉拿题诗人与小姐了。", "b": "清·崔象川《白圭志》"}], "words": [{"w": "着令", "t": "命令;责成。"}]}, {"meaning": "助词。用于动词之后。", "cites": [{"t": "莫愁春已过,看着又新春。", "b": "司空图《退居漫题》"}]}, {"meaning": "泛指服装。", "cites": [{"t": "男女衣著,悉如外人。", "b": "晋·陶潜《桃花源记》"}]}, {"meaning": "酒器。", "cites": [{"t": "着,殷尊也。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2399wx','羚','1','líng','羊','11','','[{"pinyin": "líng", "defs": [{"meaning": "羊名。羚羊  ,毛灰黄色,柔软细密。角可入药。"}, {"meaning": "小羊。", "cites": [{"t": "羚,羊子。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2400wx','盖','1','gài gě','皿','11','','[{"pinyin": "gài", "defs": [{"meaning": "(形声。从艸,盍(hé)声。本义:用芦苇或茅草编成的覆盖物)。"}, {"meaning": "苫,用茅草编成的遮盖物,可以蔽体或覆屋顶。", "cites": [{"t": "李巡曰:“编菅茅以覆屋曰苫。", "b": "《尔雅》。按,覆屋用茅若苇。苇不白,惟茅白也。"}, {"t": "乃祖吾离被苫盖,蒙荆棘,以来归我先君。", "b": "《左传·襄公十四年》"}], "words": [{"w": "苫盖", "t": "茅草覆盖物。"}]}, {"meaning": "雨伞。", "cites": [{"t": "今王公贵人处于重屋之下,出则乘舆,风则袭裘,雨则御盖,凡所以虑患之具莫不备至。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "车篷。", "cites": [{"t": "县尉得张黄盖、拥纛,前驱清道而后行,非故事,邑人以为荣。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "庭有枇杷树,吾妻死之年所手植也,今己亭亭如盖矣。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "盖弓", "t": "车盖弓。古代车上支撑车盖的弓形木架。"}]}, {"meaning": "容器的盖子。", "cites": [{"t": "其牙机巧制,皆隐在尊中,覆盖周密无际。", "b": "《后汉书·张衡传》"}], "words": [{"w": "壶盖;盒盖;引擎盖;照像机镜头罩盖;窄口瓶盖;盖盅", "t": "一种有盖子的茶杯。"}]}, {"meaning": "(hé)。门扇。", "cites": [{"t": "还复瞻被九盖皆继。", "b": "《荀子·宥坐》"}]}, {"meaning": "遮蔽;掩盖;引申为概括。", "cites": [{"t": "盖,加也,加物上也。", "b": "《释名·释言语》"}, {"t": "盆盖井口,毋令烟上泄。", "b": "《墨子·备穴》"}, {"t": "日月欲明,而浮云盖之。", "b": "《淮南子·说林》"}, {"t": "所盖多矣。", "b": "《左传·成公二年》"}, {"t": "我今将修饰之,拊循之,掩盖之。", "b": "《荀子·王制》"}, {"t": "治舍盖屋。", "b": "王褒《僮约》"}, {"t": "堂北五步,据层崖积石,嵌空垤块,杂木异草盖覆其上。", "b": "唐·白居易《庐山草堂记》"}, {"t": "员径八尺,合盖隆起,形似酒尊。", "b": "《后汉书·张衡传》"}], "words": [{"w": "盖脸", "t": "遮羞"}, {"w": "盖抹", "t": "掩盖;遮掩"}, {"w": "盖藏", "t": "掩盖;隐藏。"}]}, {"meaning": "引申为胜过、超出。", "cites": [{"t": "功盖天下。", "b": "《庄子·应帝王》"}, {"t": "况刘豫州王室之胄,英才盖世,众士慕仰,若水之归海。", "b": "《资治通鉴》"}], "words": [{"w": "盖代", "t": "绝代,绝世。"}]}, {"meaning": "(hài)。伤害,杀害。", "cites": [{"t": "群后之逮在下,明明棐常,鳏寡无盖。", "b": "《书·吕刑》"}, {"t": "谟盖都君,咸我绩。", "b": "《孟子·万章上》"}], "words": [{"w": "相盖", "t": "相害;加害。"}]}, {"meaning": "关闭。", "cites": [{"t": "盖天下,视海内,长举而无止,为之有道乎?", "b": "《管子·山权数》"}]}, {"meaning": "因为,由于。", "cites": [{"t": "然侍卫之臣不懈于内,忠志之士忘身于外者,盖追先帝之殊遇,欲报之于陛下也。", "b": "诸葛亮《出师表》"}, {"t": "不赂者以赂者丧,盖失强援,不能独完。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "盖缘", "t": "因为"}, {"w": "盖因", "t": "因为"}, {"w": "有所不知,盖未学也", "t": ""}]}, {"meaning": "发语词。", "cites": [{"t": "盖闻天地之数,有十二万九千六百岁为一元。", "b": "《西游记》"}, {"t": "盖一岁之犯死者二焉;其余,则熙熙而乐。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "盖儒者所争,尤在于名实,名实已明,而天下之理得矣。", "b": "宋·王安石《答司马谏议书》"}]}, {"meaning": "表示推测,相当于“大约”、“大概”。", "cites": [{"t": "盖余所至,比好游者尚不能十一。", "b": "宋·王安石《游褒禅山记》"}, {"t": "予以未时还家,而汝以辰时气绝。四支犹温,一目未瞑,盖犹忍死待予也。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "却,则。", "cites": [{"t": "凡百元首,承天景命,善始者实繁,克终者盖寡。", "b": "唐·魏征《谏太宗十思疏》"}]}, {"meaning": "(hé)。"}, {"meaning": "何。", "cites": [{"t": "技盖至此乎?", "b": "《庄子·养生主》"}]}, {"meaning": "何不。", "cites": [{"t": "我任我辇,我车我牛,我行既集,盖云归哉?", "b": "《诗·小雅·黍苗》"}]}]}, {"pinyin": "gě", "defs": [{"meaning": "古地名 。战国齐盖邑,汉置盖县,北齐废。故城在今山东省沂水县西北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2401wx','眷','1','juàn','目','11','','[{"pinyin": "juàn", "defs": [{"meaning": "(形声。本义:回头看)。"}, {"meaning": "同本义。", "cites": [{"t": "眷,顾也。", "b": "《说文》"}, {"t": "乃卷西顾。", "b": "《诗·大雅·皇矣》"}], "words": [{"w": "眷言", "t": "回顾的样子。言:语助词,无义。"}]}, {"meaning": "思慕,眷恋。", "cites": [{"t": "眷然有归与之情。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "眷存", "t": "关注:垂念"}, {"w": "眷眷", "t": "思慕向往的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2402wx','粘','1','nián zhān','米','11','','[{"pinyin": "nián", "defs": [{"meaning": "(形声。从米,占声。本义:具有粘性)", "words": [{"w": "粘粥", "t": "粘稠的粥"}, {"w": "踩在一些粘东西上;粘涎", "t": "口涎;亦在方言中谓言语、举止不爽利,令人乏味"}, {"w": "粘稠", "t": "浓厚而带粘性"}, {"w": "粘粘涎涎", "t": "形容言语不简要。"}]}]}, {"pinyin": "zhān", "defs": [{"meaning": "东西互相附着连结在一起", "words": [{"w": "粘合", "t": "粘贴胶合"}, {"w": "粘竿", "t": "一种顶端涂粘质,用以捕鸟的竹竿"}, {"w": "粘着", "t": "用胶质把物体固定在一起。亦指执着,不能超脱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2403wx','粗','1','cū','米','11','','[{"pinyin": "cū", "defs": [{"meaning": "(形声。从米,且声。本义:糙米)。"}, {"meaning": "同本义。", "cites": [{"t": "粗,疏也。", "b": "《说文》。按,粝米也。禾黍粟十六斗大半斗为米一斛。"}, {"t": "粮则无矣,麤则有之。", "b": "《左传》"}], "words": [{"w": "粗糠", "t": "糠。稻、麦,谷子等农作物子实的皮或壳。"}]}, {"meaning": "粗粮。", "cites": [{"t": "凡九谷,皆随精粗,差其耗损而供焉。", "b": "《新唐书》"}]}, {"meaning": "中国古代哲学范畴,指事物的表面现象。", "cites": [{"t": "可以言论者,物之粗也;可以意致者,物之精也。", "b": "《庄子》"}]}, {"meaning": "不精,粗糙。", "cites": [{"t": "粗,大也。凡不精者皆曰粗。", "b": "《广雅》"}, {"t": "其器高以粗。", "b": "《礼记·月令》"}, {"t": "其声粗以厉。", "b": "《礼记·乐记》"}, {"t": "粗布之衣。", "b": "《荀子·正名》"}], "words": [{"w": "粗粝", "t": "糙米;粗俗简陋的饭食"}, {"w": "粗恶", "t": "粗糙,低劣"}, {"w": "粗食", "t": "粗糙不精的食物"}, {"w": "粗粗", "t": "即粗糙"}, {"w": "粗腿;粗砂;粗重", "t": "粗大笨重的家具。"}]}, {"meaning": "粗疏;粗略。", "cites": [{"t": "愚者之言,芴然而粗。", "b": "《荀子·正名》。注:“粗,疏略也。”"}], "words": [{"w": "粗断", "t": "谦辞。胡乱裁决"}, {"w": "粗忽", "t": "粗疏,疏忽"}, {"w": "粗心浮气", "t": "不细致;不沉着。"}]}, {"meaning": "刚,才。", "cites": [{"t": "言粗毕,有五六盗自丛薄间跃出。", "b": "《太平广记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2404wx','粒','1','lì','米','11','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从米,立声。本义:米粒,谷粒)。"}, {"meaning": "养活。", "cites": [{"t": "生我百谷,粒我烝民。", "b": "晋·傅咸《喜雨赋》"}]}, {"meaning": "成。", "cites": [{"t": "烝民乃粒,万邦作乂。", "b": "《书·皋陶谟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2405wx','断','1','duàn','斤','11','','[{"pinyin": "duàn", "defs": [{"meaning": "(会意。本义:截断,截开)。"}, {"meaning": "同本义。", "cites": [{"t": "断,截也。", "b": "《说文》"}, {"t": "断木为杵。", "b": "《易·系辞下》"}, {"t": "三日断五匹,大人故嫌迟。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "公孙弘断发而为越王骑。", "b": "《韩非子·说林下》"}, {"t": "是断手而续以玉也,故世有易身之患。", "b": "《韩非子·用人》"}], "words": [{"w": "断梗", "t": "断枝。比喻飘泊无定;指微贱的东西"}, {"w": "断金", "t": "同心协力,坚固难移"}, {"w": "断袖", "t": "旧时指男宠;比喻友情深厚"}, {"w": "断颡", "t": "断头;砍头"}, {"w": "断袖之宠", "t": "男宠"}, {"w": "断头话", "t": "决绝的话"}, {"w": "断裳", "t": "截断裳衣。"}]}, {"meaning": "断开;断绝。", "cites": [{"t": "断者架木通之。", "b": "《徐霞客游记·游黄山记》"}, {"t": "切肉肉断而发不断。", "b": "《韩非子·内储说下》"}, {"t": "天门中断楚江开。", "b": "唐·李白《望天门山》"}], "words": [{"w": "断纹", "t": "琴上涂漆的裂纹"}, {"w": "断头香", "t": "燃至中途熄灭的香。迷信者以为再烧此香,即对神佛不敬,来世必遭报应。"}]}, {"meaning": "拦截;拦劫。", "cites": [{"t": "坐断兵马禀缣。", "b": "《后汉书·杜茂传》"}, {"t": "因军兴,断盗数千万。", "b": "《后汉书·盖勋传》。注:“断,谓割截。”"}], "words": [{"w": "断取", "t": "截取"}, {"w": "断盗", "t": "拦截抢劫。"}]}, {"meaning": "判断;裁决。", "cites": [{"t": "事不目见耳闻,而臆断其有无,可乎。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "断配", "t": "判决发配"}, {"w": "断决", "t": "判决"}, {"w": "断冤", "t": "审理冤狱"}, {"w": "断遣", "t": "断决,处理"}, {"w": "断没", "t": "判断没收归公。"}]}, {"meaning": "分;区分;划分。", "cites": [{"t": "断,段也,分为异段。", "b": "《释名》"}], "words": [{"w": "断限", "t": "划定的年代界限"}, {"w": "断方", "t": "划为方形。"}]}, {"meaning": "斩杀,宰杀。", "cites": [{"t": "大者立断。", "b": "《汉书·淮南历王长传》"}], "words": [{"w": "断除", "t": "除灭,杀掉"}, {"w": "断杀", "t": "砍杀"}, {"w": "断首", "t": "砍头。"}]}, {"meaning": "绝对;一定。", "cites": [{"t": "断无消息石榴红。", "b": "唐·李商隐《无题》"}], "words": [{"w": "他的话断不可信;断无此理;断无", "t": "绝无"}, {"w": "断省", "t": "明断"}, {"w": "断黑", "t": "全黑"}, {"w": "断喝", "t": "极严厉的吆喝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2406wx','剪','1','jiǎn','刀','11','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从刀,前声。本义:用剪刀铰断)。"}, {"meaning": "同本义。本作“前”,通作“翦”,俗作“剪”。", "cites": [{"t": "剪,齐断也。", "b": "《说文》"}, {"t": "勿剪勿伐。", "b": "《诗·召南·甘棠》"}], "words": [{"w": "剪截铺", "t": "衣料店"}, {"w": "剪筒", "t": "存放剪掉的蜡花的用具"}, {"w": "剪直", "t": "直截了当,径直"}, {"w": "剪断", "t": "亦作“简断”。利落,不啰嗦"}, {"w": "剪鬃", "t": "剪去颈后的长毛。指短发。"}]}, {"meaning": "砍伐 ;截断。", "cites": [{"t": "松柏不剪。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "剪伐", "t": "砍伐;割刈"}, {"w": "剪断", "t": "切断,打断"}, {"w": "剪边", "t": "夺取别人所爱的妓女。"}]}, {"meaning": "除灭。杀戮。", "cites": [{"t": "此文王之所以止殃剪妖也。", "b": "《吕氏春秋·制乐》"}], "words": [{"w": "剪屠", "t": "大肆杀戮"}, {"w": "剪覆", "t": "全部消灭"}, {"w": "剪弃", "t": "除去"}, {"w": "剪落", "t": "削除"}, {"w": "剪迹", "t": "犹灭迹。"}]}, {"meaning": "拦截。", "cites": [{"t": "小人只在此大树坡剪径。", "b": "《水浒传》"}], "words": [{"w": "剪江", "t": "在江中破浪而行"}, {"w": "剪径强人", "t": "劫路的强盗"}, {"w": "剪手", "t": "拦路抢劫的强盗。"}]}, {"meaning": "扫;挥动。", "cites": [{"t": "林冲把朴刀杆剪了一下,蓦地跳将出来。", "b": "《水浒全传》"}, {"t": "剪尾能惊獐鹿,咆哮吓杀狐狸。", "b": "《三遂平妖传》"}]}, {"meaning": "辩白,驳斥。", "cites": [{"t": "张千、李万说一句,妇人就剪一句,妇人说得句句有理,张千、李万抵搪不过。", "b": "《古今小说》"}]}, {"meaning": "交刀,剪刀。", "cites": [{"t": "断恨并州无快剪,牵愁织女少长丝。", "b": "清·孙枝蔚《思春辞》"}], "words": [{"w": "磨剪;剪简", "t": "放蜡花的工具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2407wx','兽','1','shòu','丷','11','','[{"pinyin": "shòu", "defs": [{"meaning": "(象形。小篆字形。上象耳,中象头,下象足踩地。兽本是禽兽的总称。古另有“獸”字,指捕捉禽兽的活动。二字通用。本义:禽兽的总称)。"}, {"meaning": "四足的哺乳动物,多指野兽。", "cites": [{"t": "兽,守备者。", "b": "《说文》"}, {"t": "四足而毛谓之兽。", "b": "《尔雅·释鸟》"}, {"t": "兽毛虫总号。", "b": "《释兽释文》。按,兽中可畜养者则曰兽。"}, {"t": "兽,狐狼之属。", "b": "《周礼·庭氏》注"}, {"t": "大兽公之。", "b": "《周礼·兽人》"}, {"t": "搏兽于敖。", "b": "《诗·小雅·车攻》"}, {"t": "猛兽步高岗。", "b": "曹操《却东西门行》"}, {"t": "兽同足者而俱行。", "b": "《战国策·齐策》"}, {"t": "山有猛兽。", "b": "《淮南子·说山训》"}, {"t": "山深而兽往之。", "b": "《史记·货殖列传序》"}], "words": [{"w": "兽目", "t": "野兽的眼睛"}, {"w": "兽工", "t": "殷制天子六工之一。即治皮革的工匠"}, {"w": "兽人", "t": "居心险恶、有如禽兽之人"}, {"w": "兽骇", "t": "兽类受惊时狂奔乱窜"}, {"w": "兽吻", "t": "门环上的装饰物;虎口"}, {"w": "兽臣", "t": "古官名。掌管山泽、田猎之事"}, {"w": "兽头大门", "t": "豪门显贵、宫殿寺观之正门上的门环,一般用铜制或鎏金的兽头铺首,故称"}, {"w": "兽铤", "t": "兽疾走。"}]}, {"meaning": "干肉。", "cites": [{"t": "实兽于其上,东首。", "b": "《仪礼》"}]}, {"meaning": "比喻野蛮、残忍。", "cites": [{"t": "外内乱,鸟兽行,则灭之。", "b": "《周礼·夏官·大司马》"}], "words": [{"w": "兽心;兽欲;兽行", "t": "比喻极端野蛮残忍、丧失人性的行为。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2408wx','焊','1','hàn','火','11','','[{"pinyin": "hàn", "defs": [{"meaning": "焊接 。用低熔点的合金于熔后流过洁净之金属面,冷却后,可使各种金属互相接合,叫做銲。俗作焊。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2409wx','焕','1','huàn','火','11','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从火,奂(huàn)声。本义:火光) 同本义。", "cites": [{"t": "焕,火光也。", "b": "《说文新附》"}]}, {"meaning": "光亮,鲜明。", "cites": [{"t": "焕乎其有文章。", "b": "《论语》。集解:“明也。”"}], "words": [{"w": "焕乎", "t": "光亮的样子"}, {"w": "焕炳", "t": "光耀明亮"}, {"w": "焕发", "t": "光彩四现"}, {"w": "焕焕", "t": "显赫的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2410wx','清','1','qīng','氵','11','','[{"pinyin": "qīng", "defs": [{"meaning": "(形声。从水,青声。“青”,碧绿透彻,也有表意作用。本义:水清)。"}, {"meaning": "同本义。与“浊”相对。", "cites": [{"t": "沧浪之水清兮。", "b": "《孟子》"}, {"t": "河水清且涟猗。", "b": "《诗·魏风·伐檀》"}, {"t": "举身赴清池。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "临清流而赋诗。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "发之欲其清。", "b": "唐·柳宗元《柳河东集》"}, {"t": "水尤清冽。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "清直", "t": "河水清澈顺流貌"}, {"w": "清波", "t": "清澈的水流"}, {"w": "清泚", "t": "清清的河水"}, {"w": "清涟", "t": "清澈的细水波"}, {"w": "清活活", "t": "水清澈而流动貌"}, {"w": "清照", "t": "清澈明亮"}, {"w": "清悠悠", "t": "清澈明亮貌"}, {"w": "清深", "t": "水色清澈"}, {"w": "清酤", "t": "清圣。清酒"}, {"w": "清雨", "t": "清净的雨"}, {"w": "清英", "t": "清酒"}, {"w": "清茗", "t": "清茶。"}]}, {"meaning": "清洁;洁净;纯洁。", "cites": [{"t": "京室密清。", "b": "张衡《东京赋》"}, {"t": "圣人守清道而抱雌节。", "b": "《淮南子·原道》"}, {"t": "身中清。", "b": "《书·微子》"}, {"t": "太清之始也。", "b": "《淮南子·本经》"}, {"t": "伏清白以死直兮。", "b": "《楚辞·离骚》"}], "words": [{"w": "清人", "t": "纯洁的人"}, {"w": "清交", "t": "纯洁的交情"}, {"w": "清休", "t": "纯洁美善"}, {"w": "清行", "t": "纯洁的品行。"}]}, {"meaning": "清明。", "cites": [{"t": "视若清明。", "b": "《礼记·玉藻》"}, {"t": "中心不定,则外物不清。", "b": "《荀子·解蔽》。注:“明审也。”"}], "words": [{"w": "清化", "t": "清明的教化"}, {"w": "清治", "t": "清明的治绩。"}]}, {"meaning": "清凉。", "cites": [{"t": "清有余也。", "b": "《吕氏春秋·有度》"}, {"t": "其候清切。", "b": "《素问·五常正大论》。注:“大凉也。”"}, {"t": "清风半夜鸣蝉。", "b": "宋·辛弃疾《西江月》"}, {"t": "清风徐来。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "清快", "t": "清凉爽快"}, {"w": "清风明月", "t": "清凉的风,明亮的月"}, {"w": "清宫", "t": "清凉的宫室"}, {"w": "清室", "t": "清凉的屋室"}, {"w": "清软", "t": "清凉柔和。"}]}, {"meaning": "清冷,凄清。", "cites": [{"t": "渌水荡漾清猿啼。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "清角吹寒。", "b": "宋·姜夔《扬州慢》"}, {"t": "更那堪冷落清秋节。", "b": "宋·柳永《雨霖铃》"}]}, {"meaning": "清平;太平。", "cites": [{"t": "当纣之时,居北海之滨,以待天下之清也。", "b": "《孟子·万章下》"}], "words": [{"w": "清世", "t": "清平盛世"}, {"w": "清夷", "t": "清平安定。"}]}, {"meaning": "寂静。", "cites": [{"t": "以其境过清,不可久居。", "b": "柳宗元《至小丘西小石潭记》"}]}, {"meaning": "清雅高尚。", "cites": [{"t": "举世皆浊我独清,众人皆醉我独醒。", "b": "《楚辞·渔父》"}], "words": [{"w": "清修如鹤", "t": "指人品高洁"}, {"w": "清立", "t": "清高特立"}, {"w": "清抗", "t": "清高超拔。"}]}, {"meaning": "清白。", "cites": [{"t": "正直清廉而谦者,宜歌风。", "b": "《史记·乐书》"}], "words": [{"w": "清廉", "t": "清白廉洁"}, {"w": "清心涂胆", "t": "心地清白,肝胆可照"}, {"w": "清洁", "t": "贞洁"}, {"w": "清操", "t": "清白的操守"}, {"w": "清臣", "t": "志行清白的人。"}]}, {"meaning": "清静;恬静。", "cites": [{"t": "太清之始也,和顺以寂漠。", "b": "《淮南子》"}], "words": [{"w": "清淡天和", "t": "清净淡泊,远离尘世"}, {"w": "清冲", "t": "恬静淡泊"}, {"w": "清佚", "t": "清静安逸。"}]}, {"meaning": "清正。", "cites": [{"t": "清徽雅量,众议攸归。", "b": "《晋书·殷浩等传论》"}, {"t": "吴郡张融,清抗绝俗,虽王公贵人,视之傲如也。", "b": "《南史》"}], "words": [{"w": "清耿耿", "t": "清正耿直"}, {"w": "清抗", "t": "清高正直"}, {"w": "清良", "t": "清正贤良"}, {"w": "清忠", "t": "清正忠诚"}, {"w": "清徽", "t": "清正的风操。高雅的谈吐"}, {"w": "清劲", "t": "清正刚直。"}]}, {"meaning": "清廉。", "cites": [{"t": "夙夜惟寅,直哉惟清。", "b": "《书·舜典》"}, {"t": "少嗜学,履尚清鲠。", "b": "《新唐书·赵宗儒传》"}]}, {"meaning": "又如:清鲠(清廉鲠直):清俭(清廉俭朴);清头(清廉);清己(以清廉之德要求自己);清公(清廉公正)。"}, {"meaning": "清香、清馨、清醇。", "cites": [{"t": "香远益清。", "b": "宋·周敦颐《爱莲说》"}]}, {"meaning": "无余。", "cites": [{"t": "六月之内交清。", "b": "《广东军务记》"}]}, {"meaning": "纯粹。", "cites": [{"t": "清神生心,心生规,规生矩。", "b": "《管子·轻重己》"}, {"t": "其气不清则欲瞑。", "b": "《灵枢·大惑论》"}]}, {"meaning": "朝代名 。公元1616—1911年,满族人爱新觉罗·努尔哈赤所建。初名后金,1636年改为清。1644年入关,定都北京。", "cites": [{"t": "视清季有加。", "b": "孙文《黄花冈七十二烈士事略序》"}]}, {"meaning": "滤去酒糟的甜酒。", "words": [{"w": "清酌庶羞", "t": "祭祀用酒和众多佳肴。"}]}, {"meaning": "粪槽,厕所。", "cites": [{"t": "修採清,易道路。", "b": "《荀子·王制》"}]}, {"meaning": "清除。", "cites": [{"t": "请诛晁错,以清君侧。", "b": "《汉书·晁错传》"}], "words": [{"w": "清跸", "t": "帝王出行时清除道路,禁止行人;也作属某人管辖,不受别人侵扰的地盘,含敬意"}, {"w": "清革", "t": "清除"}, {"w": "清烟道", "t": ""}]}, {"meaning": "付款结 。 如: 帐清了吗。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2411wx','添','1','tiān','氵','11','','[{"pinyin": "tiān", "defs": [{"meaning": "(形声。从水,忝声。本义:增加,增补)。"}, {"meaning": "同本义 。", "words": [{"w": "添嘴送舌", "t": "添言加语;搬弄是非"}]}, {"meaning": "。", "words": [{"w": "她最近添了一个女孩儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2412wx','鸿','1','hóng','鸟','11','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从鸟,江声。本义:大雁)。"}, {"meaning": "同本义 。雁属中类似天鹅的大型种类旧时的泛称。", "cites": [{"t": "鸿,鹄也。", "b": "《说文》"}, {"t": "鸿渐于干。", "b": "《易·渐》"}, {"t": "鸿雁于飞。", "b": "《诗·小雅·鸿雁》"}], "words": [{"w": "鸿冥", "t": "鸿鸟飞入苍冥"}, {"w": "鸿飞", "t": "鸿鸟飞翔"}, {"w": "鸿爪", "t": "比喻往事遗留的痕迹"}, {"w": "鸿渐", "t": "鸿鸟飞翔由低处逐渐进于高位。比喻官职升迁或渐入佳境"}, {"w": "鸿嗷", "t": "鸿鸟哀鸣,比喻灾民的悲号。"}]}, {"meaning": "鹄。即天鹅。", "cites": [{"t": "燕雀安知鸿鹄之志。", "b": "《史记·陈涉世家》。按,凡鸿鹄连文者即鹄也。"}], "words": [{"w": "鸿骞凤立", "t": "鸿鹄高飞,凤凰挺立。比喻超群杰出"}, {"w": "鸿翼", "t": "天鹅的羽翼"}, {"w": "鸿举", "t": "天鹅高飞远翔。"}]}, {"meaning": "洪水", "cites": [{"t": "鲧陻鸿水,汨陈其五行。", "b": "《汉石经·尚书·洪范》"}, {"t": "禹有功,抑下鸿。", "b": "《荀子·成相》"}, {"t": "不任汨鸿,师何以尚之?", "b": "《楚辞·屈原·天问》"}, {"t": "当帝尧之时,鸿水滔天。", "b": "《史记·夏本纪》"}, {"t": "禹抑洪水。", "b": "《史记·河渠书》"}], "words": [{"w": "鸿水", "t": "大水。即洪水"}, {"w": "鸿泉", "t": "洪水的源头"}, {"w": "鸿体", "t": "洪水的主流"}, {"w": "鸿波", "t": "洪水。"}]}, {"meaning": "即豆雁 。一种带褐色的欧亚普通雁(Anser fabalis),嘴有一豆形斑。"}, {"meaning": "大。", "cites": [{"t": "原生受命于贞节兮,鸿永路有嘉名。", "b": "《楚辞·刘向·九欢·逢纷》"}, {"t": "撞鸿钟,建九旒。", "b": "《文选·扬雄·羽猎赋》"}, {"t": "夫鸿均之世,何物不乐。", "b": "王褒《四子讲德论》"}, {"t": "鸿,大也。", "b": "《淮南子·鸿烈序》"}], "words": [{"w": "鸿猷", "t": "大道理"}, {"w": "鸿文", "t": "巨著,大作"}, {"w": "鸿名", "t": "大名,崇高的声誉"}, {"w": "鸿休", "t": "洪福"}, {"w": "鸿绪", "t": "大业,大统"}, {"w": "鸿志", "t": "大志,壮志。"}]}, {"meaning": "形容学识渊博。", "cites": [{"t": "能精思著文、连结篇章者为鸿儒。", "b": "《论衡·超奇》"}], "words": [{"w": "鸿生", "t": "指博学之士"}, {"w": "鸿博", "t": "学识渊博"}, {"w": "鸿儒", "t": "学识渊博的儒者"}, {"w": "鸿儒硕辅", "t": "学识渊博的学者,功勋卓著的臣士。"}]}, {"meaning": "旺盛,兴盛。", "cites": [{"t": "神农以鸿。", "b": "《吕氏春秋·执一》。注:“盛也。”"}], "words": [{"w": "鸿均", "t": "太平,升平"}, {"w": "鸿明", "t": "昌盛清明"}, {"w": "鸿威", "t": "盛威"}, {"w": "鸿祚", "t": "鼎盛的王业。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2413wx','淋','1','lín lìn','氵','11','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从水,林声。本义:浇)。"}, {"meaning": "同本义。让水或其他液体自上落下。", "cites": [{"t": "淋,以水沃也。", "b": "《说文》"}, {"t": "被淋洒其靡靡兮。", "b": "王褒《洞箫赋》"}], "words": [{"w": "用水淋头;日晒水淋;淋浴", "t": ""}]}, {"meaning": "浸渍。", "cites": [{"t": "淋,渍也。", "b": "《广雅》"}], "words": [{"w": "淋浪", "t": "沾湿的样子"}, {"w": "淋淋漓漓", "t": "沾湿下滴的样子"}, {"w": "淋淫", "t": "浸渍。"}]}, {"meaning": "山水奔流的样子;雨下的样子。", "cites": [{"t": "淋沐,山水下貌。", "b": "《说文》"}, {"t": "洪淋淋焉,若白鹭之下翔。", "b": "枚乘《七发》"}], "words": [{"w": "淋雨", "t": "霖雨,大雨"}, {"w": "淋淋", "t": "水倾斜的样子"}, {"w": "淋头盖脑", "t": "比喻来势猛。"}]}, {"meaning": "形容水、血、汗、泪等连续下滴貌。", "cites": [{"t": "滴滴点点淋一桌子汁水。", "b": "《水浒传》"}], "words": [{"w": "淋津", "t": "流滴的样子"}, {"w": "淋涔", "t": "水流滴的样子"}, {"w": "淋浪", "t": "流滴不止的样子"}, {"w": "淋漉", "t": "流滴的样子"}, {"w": "淋雨", "t": "连绵雨。"}]}]}, {"pinyin": "lìn", "defs": [{"meaning": "酿酒。", "cites": [{"t": "僧人这里是个苦地方,没甚么好吃的,就是一蛊素酒,倒是咱们庙里自己淋的。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2414wx','涯','1','yá','氵','11','','[{"pinyin": "yá", "defs": [{"meaning": "(会意兼形声。从水,从厓(yá),厓亦声。厓,山边。本义:水边)。"}, {"meaning": "同本义。", "cites": [{"t": "涯,水边也。", "b": "《说文新附》"}, {"t": "各在天一涯。", "b": "《古诗十九首》"}, {"t": "大海亦有洼,高山亦有岑。", "b": "孟郊《病客吟》"}], "words": [{"w": "涯欸", "t": "水边;岸"}, {"w": "涯灌", "t": "岸边丛木"}, {"w": "涯邻", "t": "崖畔。"}]}, {"meaning": "岸,靠近大水体的陆地;特指靠近滨海的陆地。", "cites": [{"t": "驾舟载男女,筑宫东海涯。", "b": "虞集《题商学士画》"}]}, {"meaning": "边际;极限。", "cites": [{"t": "横无际涯。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "无涯之憾。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "望无涯;涯限", "t": "边际;限度"}, {"w": "涯垠", "t": "涯泄、涯津、涯畔。"}]}, {"meaning": "限制,约束。", "cites": [{"t": "约少不自涯,早爱虫鸟,逐食推迁,未谐夙愿。", "b": "沈约《答沈麟士书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2415wx','淹','1','yān','氵','11','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从水,奄声。本义:古水名,即今金沙江的一段) 同本义。在四川省南部。即今金沙江自发源地至四川省攀枝花市的一段。", "cites": [{"t": "淹水,一曰复水也,出今四川宁远府徼外,合金沙江入江。", "b": "《字林》"}]}, {"meaning": "浸泡。", "cites": [{"t": "淹芳芷于腐井兮。", "b": "刘向《九叹·怨思》"}, {"t": "淹之以乐好。", "b": "《礼记·儒行》。注:“谓浸渍也。”"}], "words": [{"w": "淹荠燎菜", "t": "形容肮脏、破旧"}, {"w": "淹渍", "t": "浸泡,淹浸。"}]}, {"meaning": "淹没;沉没。", "cites": [{"t": "宅中水淹。", "b": "《北史·皇甫和传》"}], "words": [{"w": "淹沉", "t": "沉溺。"}]}, {"meaning": "逗留;挽留。", "cites": [{"t": "淹回水而凝滞。", "b": "《楚辞·屈原·涉江》"}, {"t": "为从者之淹。", "b": "《左传·僖公三十三年》"}, {"t": "淹久于敝邑。", "b": ""}], "words": [{"w": "淹息", "t": "逗留休息"}, {"w": "淹回", "t": "徘徊;逗留"}, {"w": "淹泊", "t": "停留;滞留。"}]}, {"meaning": "以盐渍食物。", "cites": [{"t": "煎鱼切肝,羊淹鸡寒。", "b": "《盐铁论·散不足》"}]}, {"meaning": "广博;深入。", "cites": [{"t": "平子淹通(通达),故虑周而藻密。", "b": "《文心雕龙·体性》"}, {"t": "淹究经术。", "b": "欧阳修《新唐书》"}], "words": [{"w": "淹贯精微", "t": "渊博贯通、精深微妙"}, {"w": "淹泓", "t": "渊深广大"}, {"w": "淹明", "t": "渊博通达"}, {"w": "淹洽", "t": "渊博;深通"}, {"w": "淹决", "t": "深通。"}]}, {"meaning": "时间长。", "cites": [{"t": "淹,久也。", "b": "《尔雅》"}, {"t": "无令舆师淹于居地。", "b": "《左传·成公二年》"}, {"t": "日月忽其不淹兮。", "b": "《离骚》"}, {"t": "王师淹病矣。", "b": "《公羊传·宣公十二年》"}], "words": [{"w": "淹留", "t": "久留"}, {"w": "淹滞", "t": "长久停留。比喻有才德者沉沦下位或没有升迁。"}]}, {"meaning": "迟缓。", "cites": [{"t": "淹速之度兮,语予其期。", "b": "贾谊《鹏鸟赋》"}], "words": [{"w": "淹迟", "t": "缓慢;迟缓"}, {"w": "淹懈", "t": "迟怠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2416wx','渠','1','qú','氵','11','','[{"pinyin": "qú", "defs": [{"meaning": "(形声。从水,榘(qú)省声。本义:水停积处,也指人工开凿的水道)。"}, {"meaning": "同本义。", "cites": [{"t": "渠,水所居。", "b": "《说文》"}, {"t": "渠,坑也。", "b": "《广雅·释水》"}, {"t": "门闾沟渠必步。", "b": "《礼记·曲礼》。疏:“沟也。”"}], "words": [{"w": "干渠", "t": "从水源引水的渠道"}, {"w": "支渠;毛渠;渠堑", "t": "沟渠"}, {"w": "灌溉渠;渠田", "t": "水田"}, {"w": "渠长", "t": "古官名。掌管河川的官;盗贼的首领"}, {"w": "渠水", "t": "引水的沟;沟渠中的水。"}]}, {"meaning": "濠沟。", "cites": [{"t": "景霍以为城,而汾、河、涑、浍以为渠。", "b": "《国语》"}]}, {"meaning": "水名。"}, {"meaning": "渠江,在四川省境内。"}, {"meaning": "渠水,在湖南省靖县境内。一名渠河。"}, {"meaning": "古州名 。治所在今四川省渠县。"}, {"meaning": "疾速。", "cites": [{"t": "夫水激而流渠。", "b": "《管子·地数》"}]}, {"meaning": "他。", "cites": [{"t": "渠会永无缘。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "渠人", "t": "他人;其他人"}, {"w": "渠伊", "t": "方言。他,他们"}, {"w": "渠辈", "t": "他们"}, {"w": "渠侬", "t": "方言。他,她。"}]}, {"meaning": "开凿沟渠。", "cites": [{"t": "量力不足,不敢渠地而耕。", "b": "《吕氏春秋》"}], "words": [{"w": "渠堰", "t": "拦水或巩固堤防的建筑物。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2417wx','渐','1','jiān jiàn','氵','11','','[{"pinyin": "jiān", "defs": [{"meaning": "流入;入。", "cites": [{"t": "东渐于海。", "b": "《书·禹贡》"}], "words": [{"w": "渐渐", "t": "流淌的样子。"}]}, {"meaning": "淹没,浸泡。", "cites": [{"t": "其渐之滫,君子不近,庶人不服。", "b": "《荀子·劝学》"}, {"t": "淇水汤汤,渐车帏裳。", "b": "《诗·卫风·氓》"}, {"t": "渐,渍也。", "b": "《广雅》"}, {"t": "是渐之也。", "b": "《荀子·议兵》"}, {"t": "渐之滫中。", "b": "《史记·三王世家》"}, {"t": "治大地渐台。", "b": "《史记·孝武纪》"}, {"t": "泽兰渐被径。", "b": "《文选·谢灵运·游南亭诗》"}], "words": [{"w": "渐浸", "t": "浸润,渍染"}, {"w": "渐涵", "t": "渐渍。犹浸润。引申为渍染,感化"}, {"w": "渐摩", "t": "渐磨。浸润;教育感化"}, {"w": "渐及", "t": "润泽普及。"}]}, {"meaning": "熏染,可染。", "cites": [{"t": "俗之渐民久。", "b": "《史记·货殖列传》"}], "words": [{"w": "渐染", "t": "渍染;沾染"}, {"w": "渐导", "t": "熏染,引导"}, {"w": "渐濡", "t": "浸染,熏染。"}]}, {"meaning": "欺诈。", "cites": [{"t": "上幽险则下渐诈矣。", "b": "《荀子·正论》"}], "words": [{"w": "渐巧", "t": "诈伪"}, {"w": "渐行", "t": "诈行,以欺诈行事"}, {"w": "渐毒", "t": "欺诈"}, {"w": "渐诈", "t": "欺诈。"}]}, {"meaning": "潜伏。", "cites": [{"t": "知虑渐深,则一之以易良。", "b": "《荀子·修身》"}, {"t": "意岂将军忘湛渐之火?", "b": "《汉书·谷永传》"}], "words": [{"w": "渐心", "t": "潜心"}, {"w": "沉渐", "t": ""}]}]}, {"pinyin": "jiàn", "defs": [{"meaning": "(形声。从水,斩声。本义:古水名。即今新安江及其下游钱塘江)。"}, {"meaning": "古水名。", "cites": [{"t": "渐,渐水出丹阳黟南蛮中,东入海。", "b": "《说文》"}, {"t": "渐江,山海经谓之浙江也。", "b": "《水经注·渐江水》。按,即今之钱塘江,古大江与钱塘江通。"}]}, {"meaning": "逐渐。", "cites": [{"t": "乱花渐欲迷人眼。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "渐闻水声。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "渐拍渐止。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "渐次间", "t": "渐渐,逐渐"}, {"w": "渐至佳境", "t": "渐入佳境。逐渐好转或兴味逐渐浓厚"}, {"w": "渐积", "t": "逐渐发展,积聚。"}]}, {"meaning": "立刻。", "cites": [{"t": "正是严冬天气,彤云密布,朔风渐起,却早纷纷扬扬卷下一天大雪来。", "b": "《水浒传》"}]}, {"meaning": "缓慢。", "cites": [{"t": "为变盖渐。", "b": "[英]赫胥黎著、严复译《天演论》"}]}, {"meaning": "疏导河川。", "cites": [{"t": "渐九川。", "b": "《史记》"}]}, {"meaning": "加剧。", "cites": [{"t": "疾大渐。", "b": "《尚书》"}, {"t": "王曰:“呜呼!疾大渐,惟几。”", "b": "《书·顾命》。孔传:“自叹其疾大进笃,惟危殆。”"}, {"t": "汝寒温不节,虚实失度,病由饥饱、色欲、精虑、烦散,非天非鬼,虽渐,可攻也。", "b": "《列子》"}]}, {"meaning": "成长;滋长。", "cites": [{"t": "自下之渐。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "渐包", "t": "渐苞。不断滋长;丛生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2418wx','淑','1','shū','氵','11','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从水,叔声。本义:水清澈)。"}, {"meaning": "同本义。", "cites": [{"t": "淑,清湛也。", "b": "《说文》"}, {"t": "其何能淑。", "b": "《诗·大雅·桑柔》。按,清也。"}], "words": [{"w": "淑淑", "t": "清净"}, {"w": "淑清", "t": "明朗;纯净"}, {"w": "淑然", "t": "清纯的样子。"}]}, {"meaning": "“淑”假借为“俶”。善良;美好。", "cites": [{"t": "遇人之不淑矣。", "b": "《诗·王风·中谷有蓷》"}, {"t": "淑人君子。", "b": "《诗·曹风·鳲鸠》"}, {"t": "窈窕淑女,君子好逑。", "b": "《诗·周南·关雎》"}, {"t": "淑,善也。", "b": "《尔雅》"}, {"t": "有私淑艾者。", "b": "《孟子》"}, {"t": "九侯淑女。", "b": "《楚辞·招魂》"}, {"t": "淑人君子,其仪一兮。", "b": "《荀子·劝学》"}, {"t": "未获至论之淑真也。", "b": "《潜夫论·论荣》"}, {"t": "将军向宠,性行淑均。", "b": "诸葛亮《出师表》"}], "words": [{"w": "淑艾", "t": "美好;善良"}, {"w": "淑人", "t": "心地善良之人;明清对三品官之妻的封号"}, {"w": "淑慎", "t": "美善而敬慎"}, {"w": "淑懿", "t": "美善;良善"}, {"w": "淑景", "t": "美景"}, {"w": "淑媛", "t": "美好善良的女子"}, {"w": "淑慝", "t": "好坏;善恶"}, {"w": "淑女", "t": "悠闲洁净的女子"}, {"w": "帝王对高官家属的一种封号;淑士", "t": "淑人,善人"}, {"w": "淑尤", "t": "特别美善"}, {"w": "淑化", "t": "良善的风尚。"}]}, {"meaning": "美丽。", "cites": [{"t": "淑好之人,戚施之所妒也。", "b": "桓宽《盐铁论·非鞅》"}], "words": [{"w": "淑貌", "t": "美丽的容貌"}, {"w": "淑姿", "t": "优美的姿态容貌"}, {"w": "淑尤", "t": "优美出众,美善过人"}, {"w": "淑丽", "t": "犹淑美。贤淑美丽"}, {"w": "淑美", "t": "美丽贤淑"}, {"w": "淑令", "t": "美丽"}, {"w": "淑好", "t": "美丽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2419wx','淌','1','tǎng','氵','11','','[{"pinyin": "tǎng", "defs": [{"meaning": "(形声。从水,尚声。本义:流下)。"}, {"meaning": "同本义。", "cites": [{"t": "打大前日,河里就淌凌。", "b": "《老残游记》"}], "words": [{"w": "淌凌", "t": "流淌冰块"}, {"w": "他脸上淌着汗水;淌眼泪;淌眼抹泪", "t": "一边哭泣,一边擦眼泪"}, {"w": "伤口淌血", "t": ""}]}, {"meaning": "用同“趟”,在浅水里走。", "cites": [{"t": "他咬上了牙,淌着水不管高低深浅的跑起来。", "b": "老舍《骆驼祥子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2420wx','混','1','hún hùn','氵','11','','[{"pinyin": "hún", "defs": [{"meaning": "(形声。从水,昆声。本义:水势盛大)。"}, {"meaning": "同本义。", "cites": [{"t": "混,丰流也。", "b": "《说文》"}, {"t": "汩乎混流。", "b": "司马相如《子虚赋》"}, {"t": "或混沦乎泥沙。", "b": "郭璞《江赋》"}], "words": [{"w": "混沦", "t": "水旋转的样子"}, {"w": "混澒", "t": "水流漫涌回旋的样子"}, {"w": "混瀁", "t": "水大无边的样子。"}]}, {"meaning": "浑浊,水多泥多杂质而不清澈。", "cites": [{"t": "时混混兮浇饡。", "b": "《楚辞·王逸·九思·伤时》。注:“混混,浊也。”"}, {"t": "玄混之中。", "b": "《文选·班固·典引》"}], "words": [{"w": "混混", "t": "浑浊"}, {"w": "混秽", "t": "使混浊污秽"}, {"w": "混浑", "t": "浑浊不清。"}]}, {"meaning": "全部。同“浑”。", "cites": [{"t": "辑政蹈故,混不加修。", "b": "明·方孝孺《张彦辉文集序》"}]}, {"meaning": "整个。同“浑”。"}]}, {"pinyin": "hùn", "defs": [{"meaning": "混同,混合搀杂。", "cites": [{"t": "若能类善物以混厚民人者。", "b": "《国语·周语下》"}, {"t": "吿尧之时,混吾之美在下。", "b": "《管子·侈靡》"}, {"t": "有物混成,先天地生。", "b": "《老子》"}, {"t": "天下混而为一。", "b": "《淮南子·览冥》"}, {"t": "六合既混。", "b": "《太玄·玄图》"}, {"t": "混逐蔓延。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "混融", "t": "混和。混和融合"}, {"w": "混淆", "t": "混杂"}, {"w": "混挠", "t": "混杂;搅乱"}, {"w": "混缠", "t": "搅在一起;纠缠"}, {"w": "混羼", "t": "混杂;搀杂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2421wx','淮','1','huái','氵','11','','[{"pinyin": "huái", "defs": [{"meaning": "(形声。从水,隹(zhuī)声。本义:水名。也称淮河) 同本义。", "cites": [{"t": "淮,淮水也。", "b": "《说文》。朱骏声曰:“出今河南南阳府桐柏县桐柏山,经安微至江苏清河县合于河,经安东县至云梯关入海。”"}, {"t": "江淮河济为四渎。", "b": "《尔雅》"}, {"t": "其浸淮泗。", "b": "《周礼·职方式》"}, {"t": "淮左名都。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "淮洪", "t": "淮河与洪河,一说淮河中的洪水。也比喻善言健谈"}, {"w": "淮军", "t": "李鸿章在安徽一带组织的军队"}, {"w": "淮南耆阳", "t": "淮河以南的年高而有声望的人。"}]}, {"meaning": "大。", "cites": [{"t": "淮雨。", "b": "《尚书大传》。注:“大雨之名也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2422wx','淆','1','xiáo','氵','11','','[{"pinyin": "xiáo", "defs": [{"meaning": "(形声。从水,肴(yáo)声。本义:错杂;混杂)。"}, {"meaning": "同本义。", "cites": [{"t": "淆,乱也,杂也。", "b": "《字汇》"}], "words": [{"w": "淆舛", "t": "混杂错乱"}, {"w": "淆紊", "t": "混杂纷乱"}, {"w": "淆讹", "t": "搅乱,弄错。"}]}, {"meaning": "彻底地搀和;搅合。", "cites": [{"t": "澄之不清,淆之不浊,不可量也。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2423wx','渊','1','yuān','氵','11','','[{"pinyin": "yuān", "defs": [{"meaning": "(会意。《说文》古文字形,外边大框象水潭,里面是打漩的水。本义:打漩涡的水)。"}, {"meaning": "同本义。", "cites": [{"t": "渊,回水也。", "b": "《说文》"}, {"t": "水出地而不流,命曰渊水。,", "b": "《管子·度地》"}, {"t": "鲵桓之审为渊,止水之审为渊,流水之审为渊。", "b": "《庄子·应帝王》"}, {"t": "或跃在渊。", "b": "《易·乾》"}], "words": [{"w": "渊环", "t": "回旋环绕"}, {"w": "渊洑", "t": "水流汹涌起伏的样子。"}]}, {"meaning": "深潭。", "cites": [{"t": "如临深渊。", "b": "《论语》。孔注:“潭也。”"}, {"t": "鱼潜在渊。", "b": "《诗·小雅·鹤鸣》"}, {"t": "不测不渊。", "b": "汉·贾谊《过秦论》"}, {"t": "潜龙腾渊。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "渊沦", "t": "潭中微波"}, {"w": "渊涂", "t": "泥潭"}, {"w": "渊潭", "t": "深潭"}, {"w": "渊跃", "t": "龙在渊中跃动欲飞。"}]}, {"meaning": "人或物聚集的处所。", "cites": [{"t": "略茺裔之地,不如保殖五谷之渊。", "b": "《后汉书》"}], "words": [{"w": "渊府", "t": "指财物或文书等集聚的地方。"}]}, {"meaning": "深;深远;渊博。", "cites": [{"t": "渊,深也。", "b": "《小尔雅》"}, {"t": "其心塞渊。", "b": "《诗·邶风·燕燕》"}, {"t": "渊渊其渊。", "b": "《礼记·中庸》"}], "words": [{"w": "渊微", "t": "渊博细致、见微知著"}, {"w": "渊才", "t": "渊博的才能"}, {"w": "渊匠", "t": "学识,渊博的人"}, {"w": "渊衷", "t": "内心"}, {"w": "渊心", "t": "渊深的内心"}, {"w": "渊玄", "t": "深邃;深奥"}, {"w": "渊奥", "t": "深奥。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2424wx','淫','1','yín','氵','11','','[{"pinyin": "yín", "defs": [{"meaning": "(形声。从水,侌(yín)声。本义:浸淫;浸渍)。"}, {"meaning": "同本义。", "cites": [{"t": "淫,侵淫随理也。", "b": "《说文》。徐锴注:“随其脉理而浸渍也。”"}, {"t": "善防者水淫之。", "b": "《考工记·匠人》"}, {"t": "女娲积芦苇以止淫水。", "b": "《淮南子·览冥》。注:“平地出水为淫水。”"}]}, {"meaning": "涂染。", "cites": [{"t": "谏帛,以栏为灰,渥淳其帛,实诸泽器,淫之以蜃。", "b": "《周礼》。郑玄注:“淫,薄粉之,令帛白”"}], "words": [{"w": "淫溢", "t": "逐渐浸染。"}]}, {"meaning": "特指通奸; 奸淫。", "cites": [{"t": "男女不淫。", "b": "《管子·小匡》"}], "words": [{"w": "淫奔", "t": "淫乱放荡;私跟男子交往"}, {"w": "淫垢", "t": "淫媾。奸污"}, {"w": "淫污", "t": "奸污。"}]}, {"meaning": "放纵;恣肆。", "cites": [{"t": "其无淫于观。", "b": "《书·无逸》。疏:郑玄云:“淫,放恣也。”"}]}, {"meaning": "贪欲;贪心。", "cites": [{"t": "吾闻国之昏,不由声色,必由奸利好乐声色者淫也,贪奸者惑也。", "b": "汉·刘向《说苑·反质》"}], "words": [{"w": "淫心", "t": "贪心"}, {"w": "淫思", "t": "淫欲之念。"}]}, {"meaning": "惑乱,沉湎;沉浸。", "cites": [{"t": "富贵不能淫,贫贱不能移。", "b": "《孟子·滕文公下》"}], "words": [{"w": "淫溺", "t": "迷恋沉溺。多指酒色。耽于积习;沉迷于癖好。"}]}, {"meaning": "侵淫;侵犯。", "cites": [{"t": "足於性者,天损不能入;贞於期者,时累不能淫。李善注:“淫,犹侵也”。", "b": "《文选·陆机》"}]}, {"meaning": "(yóu)。遨游。", "cites": [{"t": "不淫意于法之外。", "b": "《管子·明法》。孙星衍云:“《韩非子·有度》篇淫作游。”"}, {"t": "归来兮,不可以久淫些。", "b": "《楚辞·招魂》。洪兴祖补注:“淫,游也。”"}]}, {"meaning": "过度,无节制;滥。引申为过失。", "cites": [{"t": "罔淫于乐。", "b": "《书·大禹谟》。传:“淫,过也。”"}, {"t": "不淫其色。", "b": "《诗·关雎序》。疏:“淫者,过也,过其度量谓之为淫。”"}, {"t": "骄奢淫泆。", "b": "《左传·隐公三年》。疏:“淫,谓耆欲过度。”"}, {"t": "齐八政以防淫。", "b": "《礼记·王制》。疏:“淫,谓过奢侈。”"}, {"t": "淫侈之俗。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "淫用", "t": "过度役用"}, {"w": "淫行", "t": "过分的行为;不合礼制的行为"}, {"w": "淫宴", "t": "不合礼制、越规逾节的宴会"}, {"w": "淫酗", "t": "饮酒无度"}, {"w": "淫费", "t": "过分花费;不正当的花费"}, {"w": "淫滥", "t": "过度;越轨"}, {"w": "淫杀", "t": "滥杀"}, {"w": "淫潦", "t": "久雨积水为灾"}, {"w": "淫滞", "t": "长久停留"}, {"w": "淫佚", "t": "荒淫无度"}, {"w": "淫声邪语", "t": "淫乱狎邪的声音语言"}, {"w": "淫夫", "t": "淫荡的男子"}, {"w": "淫汰", "t": "骄纵奢侈"}, {"w": "淫长", "t": "浮华奢侈的风尚"}, {"w": "淫物", "t": "奢华无用的玩物"}, {"w": "淫侈", "t": "奢侈;浮夸,夸大"}, {"w": "淫惑", "t": "荒淫惑乱"}, {"w": "淫愚", "t": "惑乱愚弄"}, {"w": "淫巫", "t": "惑乱人心的巫师。"}]}, {"meaning": "犹大。指规模广,程度深,力量强。", "cites": [{"t": "既有淫威,降福孔夷。", "b": "《诗·周颂·有客》"}], "words": [{"w": "淫威", "t": "盛大的礼仪、法度"}, {"w": "淫祸", "t": "大祸。"}]}, {"meaning": "邪恶,奸邪。", "cites": [{"t": "善人劝焉,淫人惧焉。", "b": "《左传·昭公三十一年》"}], "words": [{"w": "淫人", "t": "邪恶的人"}, {"w": "淫悖", "t": "邪恶违道"}, {"w": "淫诈", "t": "奸诈。"}]}, {"meaning": "乱杂;邪乱。", "cites": [{"t": "迁而不淫,复而不厌。", "b": "《左传·襄公二九年》"}], "words": [{"w": "淫心", "t": "邪乱的思想;淫乱的念头"}, {"w": "淫气", "t": "淫邪之气。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2425wx','渔','1','yú','氵','11','','[{"pinyin": "yú", "defs": [{"meaning": "(会意。从水,从鱼。小篆从二鱼。本义:捕鱼)。"}, {"meaning": "同本义。", "cites": [{"t": "渔,捕鱼也。", "b": "《说文》"}, {"t": "命渔师伐蛟,命渔师始渔。", "b": "《礼记·月令》"}, {"t": "獭祭鱼然后渔。", "b": "《诗·鲡传》"}, {"t": "渔者走渊。", "b": "《淮南子·说林》"}, {"t": "以渔采为业。", "b": "《汉书·王莽传》"}, {"t": "临溪而渔,溪深而鱼肥。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "渔樵", "t": "打鱼砍柴"}, {"w": "渔采", "t": "捕捞采集"}, {"w": "渔事", "t": "捕渔业"}, {"w": "渔弋", "t": "捕鱼猎禽"}, {"w": "渔泽", "t": "可供垂钓的水泽"}, {"w": "渔矶", "t": "可供垂钓的水边岩石"}]}, {"meaning": "掠夺。", "cites": [{"t": "民方苦于侵渔,果所在响应。", "b": "方勺《方腊起义》"}], "words": [{"w": "渔色渔财", "t": "猎取美女和财物"}, {"w": "渔猎女色", "t": "似捕鱼打猎那样谋取、玩弄女性"}, {"w": "渔人得利", "t": "比喻双方相争,却让第三者坐收其利。"}]}, {"meaning": "猎取,寻觅。", "cites": [{"t": "小鸡在笼子里悠然地渔着食。", "b": "郭沫若《归去来·鸡之归去来》"}]}, {"meaning": "捕鱼的人。", "cites": [{"t": "神心重丘壑,散步怀渔樵。", "b": "南朝梁·刘孝威《奉和六月壬午应令诗》"}], "words": [{"w": "渔父之图", "t": "比喻行动之中别有所图"}, {"w": "渔叟", "t": "渔翁"}, {"w": "渔蓑", "t": "渔人的蓑衣"}, {"w": "渔樵", "t": "渔人和樵夫"}, {"w": "渔乡", "t": "渔民聚居的地区"}, {"w": "渔阳三弄", "t": "渔阳三叠,渔阳曲,渔阳鼓,渔阳掺,渔阳操。均为渔阳参挝,鼓曲名"}, {"w": "渔阳鼙鼓", "t": "指公元755年安禄山于渔阳举兵叛唐事。鼙鼓,骑兵用的小鼓。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2426wx','淘','1','táo','氵','11','','[{"pinyin": "táo", "defs": [{"meaning": "(本作“洮”。形声。从水匋(táo)声。本义:用水冲洗,去除杂质)。"}, {"meaning": "同本义。", "cites": [{"t": "浪淘尽。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}]}, {"meaning": "疏浚。", "cites": [{"t": "每遇春时,官差大夫监淘在城渠,别开坑盛淘出者泥,谓之泥盆。", "b": "宋·孟元老《东京梦华录》"}], "words": [{"w": "淘浚", "t": "疏通,挖浚"}, {"w": "淘掘", "t": "掏挖,挖掘"}, {"w": "淘河", "t": ""}]}, {"meaning": "以液汁拌和食品。", "cites": [{"t": "宋金戴了破毡笠,吃了茶淘冷饭。", "b": "《警世通言·宋小官团圆破毡笠》"}]}, {"meaning": "怄。", "cites": [{"t": "防暗箭,淘闲气。", "b": "鲁迅语"}]}, {"meaning": "耗费。", "cites": [{"t": "但说起来,吃药既不见效,枉淘坏了身子。", "b": "《醒世恒言》"}], "words": [{"w": "淘神;淘空", "t": "淘虚。耗费净尽"}, {"w": "淘渌", "t": "淘碌。销蚀。多指色欲伤身"}, {"w": "淘渲", "t": "折腾;鬼混。"}]}, {"meaning": "“淘淘”同“滔滔”。水汹涌澎湃的。", "cites": [{"t": "浪淘淘扬子江。", "b": "张可久《水仙子·归兴》"}]}, {"meaning": "顽皮的。", "cites": [{"t": "他淘是淘,可从来不撒谎", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2427wx','淳','1','chún','氵','11','','[{"pinyin": "chún", "defs": [{"meaning": "(形声。(zhūn)本义:浇灌)。"}, {"meaning": "敦厚;质朴;朴实。", "cites": [{"t": "浇天下之淳,析天下之朴。", "b": "《淮南子·齐俗》"}], "words": [{"w": "淳良", "t": "朴实善良"}, {"w": "淳古", "t": "古代朴质的风尚精神"}, {"w": "淳和", "t": "淳朴而温和"}, {"w": "淳风", "t": "淳朴的风俗"}, {"w": "淳粹", "t": "朴实完善。"}]}, {"meaning": "味道浓厚的。一说通“醇”。", "cites": [{"t": "淳,浓也。", "b": "《三苍》"}, {"t": "淳酒味甘,饮之者醉不相知。", "b": "《论衡·自然》"}], "words": [{"w": "淳浓", "t": "浓度高"}, {"w": "淳雄", "t": "浑厚雄健。"}]}, {"meaning": "味咸的。", "cites": [{"t": "表淳卤。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "淳卤", "t": "盐碱地。"}]}, {"meaning": "纯粹。", "cites": [{"t": "以淳粹之气,生敦庞之民。", "b": "《潜夫论·本训》"}, {"t": "至于道者,精微淳粹,而莫知其体。", "b": "《隋书·经籍志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2428wx','液','1','yè','氵','11','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。从水,夜声。本义:汁,流质)。"}, {"meaning": "同本义。", "cites": [{"t": "液,汁也。", "b": "《字林》"}, {"t": "人有精气津液。", "b": "《素问·调经论》。注:“精之渗于空窍,留而不行者为液也。”"}, {"t": "鼻出清液。", "b": "《素问·腹中论》"}, {"t": "观炎气之相仍兮,窥烟液之所积。", "b": "《楚辞》"}, {"t": "尚恐丹液迟,志愿不及申。", "b": "唐·李白《古风》"}], "words": [{"w": "泪液", "t": "眼内泪腺分泌的无色透明液体"}, {"w": "胃液;津液;唾液;溶液", "t": ""}]}, {"meaning": "冰冻融解;溶化。", "cites": [{"t": "渔兮其若冰之液者,不改积藏。", "b": "《文子》"}, {"t": "每至正月,烧去枯叶。地液辄耕垅。", "b": "《齐民要术》"}], "words": [{"w": "液液", "t": "融解的样子;津润的样子"}, {"w": "液蹣", "t": "脂液流出。"}]}, {"meaning": "浸渍。", "cites": [{"t": "凡为弓,冬析干而春液角。", "b": "《周礼》"}]}, {"meaning": "润。", "cites": [{"t": "滋液渗漉,何生不育。", "b": "汉·司马相如《封禅文》"}]}, {"meaning": "渗漏。", "cites": [{"t": "木器液,金器腥,圣人饮于土,食于土,故埏埴以为器。", "b": "《尉缭子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2429wx','淤','1','yū','氵','11','','[{"pinyin": "yū", "defs": [{"meaning": "(形声。从水,於(yú)声。本义:水中沉淀的泥沙)。"}, {"meaning": "同本义。", "cites": [{"t": "春夏干燥, 少水时也, 故使河流迟, 贮淤而稍浅。 ", "b": "《汉书》"}], "words": [{"w": "淤滩", "t": "淤泥形成的滩地"}, {"w": "引淤肥田", "t": ""}]}, {"meaning": "泥沙冲积成的地带。", "cites": [{"t": "楚人种麦满河淤,仰看浮槎栖古木。", "b": "宋·苏轼《河复》"}]}, {"meaning": "将含有大量淤泥的河水引入低洼地,令其沉淀以改良土壤。", "cites": [{"t": "阳武县民邢晏等三百六十四户言。”田沙碱瘠薄,乞淤溉…以助兴修。", "b": "《宋史·河渠志》"}]}, {"meaning": "又如：淤田(用水将淤泥引入农田);淤溉(引含有大量淤泥的水灌田,使淤泥沉淀,以改良土壤,增加肥力)。"}, {"meaning": "滞塞,不流通。", "cites": [{"t": "淤,淀滓浊泥也。", "b": "《说文》。字亦作“阏”。"}, {"t": "渠成而用溉注填阏之水。", "b": "《汉书·沟洫志》。注:“阏,读与淤同…填阏,谓壅泥也。”"}], "words": [{"w": "淤涌", "t": "淤塞的水流"}, {"w": " 淤停", "t": "水淤积不流"}, {"w": " 淤阏", "t": "堵塞。水流不通。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2430wx','淡','1','dàn','氵','11','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从水,炎声。本义:味淡;味道不浓,不咸)。"}, {"meaning": "同本义。", "cites": [{"t": "淡,薄味也。", "b": "《说文》"}, {"t": "淡而不厌。", "b": "《礼记·中庸》"}, {"t": "君子淡以成。", "b": "《礼记·表记》。注:“无酸酢少味也。”"}, {"t": "淡也者,五味之中也。", "b": "《管子·水地》"}, {"t": "大味必淡。", "b": "《汉书·扬雄传》。注:“谓无主味也。”"}, {"t": "其水淡而清。", "b": "《世说新语·言语》"}], "words": [{"w": "淡酒;淡味;淡句", "t": "平淡乏味的诗句"}, {"w": "淡而不厌", "t": "指诗文恬淡而不乏味"}, {"w": "淡菜", "t": ""}]}, {"meaning": "稀薄。", "cites": [{"t": "天高云淡,望断南飞雁。", "b": "毛泽东《清平乐·六盘山》"}], "words": [{"w": "淡水白酒", "t": "薄酒"}, {"w": "淡蛾", "t": "淡眉"}, {"w": "淡烟", "t": "轻烟"}, {"w": "淡粥", "t": "稀粥。"}]}, {"meaning": "冷淡,不热情。", "cites": [{"t": "钧与人交,始若淡薄,既久乃益固。", "b": "《唐书·卢钧传》"}], "words": [{"w": "冷淡", "t": "不热情,不亲热"}, {"w": "淡悠悠", "t": "不介意的样子"}, {"w": "淡话", "t": "不痛不痒的话;可说可不说的话。"}]}, {"meaning": "淡雅。", "cites": [{"t": "欲把西湖比西子,淡妆浓抹总相宜。", "b": "宋·苏轼《饮湖上初晴雨后》"}], "words": [{"w": "淡净", "t": "淡雅素净"}, {"w": "淡妆浓抹", "t": "淡雅和浓艳两种不同的妆饰打扮。"}]}, {"meaning": "淡泊,不追求名利。", "cites": [{"t": "且君子之交淡若水,小人之交甘若醴。", "b": "《庄子·山水》"}], "words": [{"w": "淡如", "t": "恬淡寡欲,不追求名利"}, {"w": "淡泊自甘", "t": "乐于恬淡生活,不以清贫为苦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2431wx','淀','1','diàn','氵','11','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从水,殿声。本义:沉淀下来的泥滓)。"}, {"meaning": "同本义。", "cites": [{"t": "淀谓之滓。", "b": "《广雅》"}], "words": [{"w": "淀塞", "t": "淤塞。"}]}, {"meaning": "蓝靛。一种蓝色染料。", "cites": [{"t": "身色皆蓝淀,情田尽虎狼。", "b": "《敦煌变文集》"}]}, {"meaning": "淤积。", "cites": [{"t": "汴渠有二十年不浚,岁岁堙淀。", "b": "沈括《梦溪笔谈》"}]}, {"meaning": "沉淀。", "cites": [{"t": "豆腐,以黄豆为之。造法:水浸磨浆,滤去滓,煎成,淀以盐卤汁,就釜收之。", "b": "徐珂《清稗类钞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2432wx','深','1','shēn','氵','11','','[{"pinyin": "shēn", "defs": [{"meaning": "(形声。从水,深声(shēn)。本是河流名。深浅的深,本作“深”。本义:水名)。"}, {"meaning": "古水名 。即今湘水支流之一的潇水。今潇水上源至江华县一段仍称深水。", "cites": [{"t": "深,深水。出桂阳南平,西入营道。", "b": "《说文》"}]}, {"meaning": "从上到下或从外到内的距离。", "cites": [{"t": "穷高极远,而测深厚。", "b": "《礼记·乐记》。注:“深厚,山川也。”"}, {"t": "测土深。", "b": "《周礼·大司徒》"}, {"t": "深四尺。", "b": "《仪礼·觐礼》"}, {"t": "问其深,则好游者不能穷也。", "b": "宋·王安石《游褒禅山记》"}, {"t": "山下皆石穴罅,不知其浅深。", "b": "宋·苏轼《石钟山记》"}]}, {"meaning": "水深。与“浅”相对。", "cites": [{"t": "深矣远矣。", "b": "《老子》。注:“深不可测也。”"}, {"t": "深蒲。", "b": "《周礼·醢人》。司农注:“蒲蒻入水深,故曰深蒲。”"}, {"t": "郦元以为下临深潭,微风鼓浪,水石相击,声如洪钟。", "b": "宋·苏轼《石钟山记》"}, {"t": "先茔在杭,江广河深,势难归葬。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "深潭", "t": "深水池"}, {"w": "深广", "t": "指水、山谷等深邃而广阔"}, {"w": "深堑", "t": "深沟"}, {"w": "深隍", "t": "深而无水的护城壕"}, {"w": "深沦", "t": "深水"}, {"w": "深泓", "t": "深潭"}, {"w": "深泥", "t": "很深的泥泞"}, {"w": "深池", "t": "深的护城河。"}]}, {"meaning": "引申为距离大。", "cites": [{"t": "遥闻深巷中犬吠。", "b": "《虞初新志·秋声诗自序》"}, {"t": "入之愈深,其进愈难,而其见愈奇。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "深衢", "t": "岔路处"}, {"w": "深禁", "t": "深宫"}, {"w": "深堂", "t": "深处的厅堂"}, {"w": "山侧的深裂隙;深峭", "t": "深邃陡峭"}, {"w": "深峻", "t": "深川峻岭。喻指旅途"}, {"w": "深衣", "t": "古代诸侯、大夫、士家居衣裳,又是庶人的常礼服。上衣和下裳相连,前后深长"}, {"w": "深靓", "t": "深邃宁静"}, {"w": "深谷底下一条河;深坑", "t": ""}]}, {"meaning": "玄妙,深奥。", "cites": [{"t": "夫易,圣人之所以极深而研几也。", "b": "《易·系辞》"}], "words": [{"w": "深微", "t": "深奥精微"}, {"w": "深诣", "t": "造诣很深"}, {"w": "深赜", "t": "深奥精微"}, {"w": "深严", "t": "深邃严密"}, {"w": "深隐", "t": "深奥隐晦"}, {"w": "深迂", "t": "深奥曲折。"}]}, {"meaning": "深刻;深远。", "cites": [{"t": "大贤之深谋远虑,岂庸人所及哉?", "b": "宋·司马光《训俭示康》"}, {"t": "以求思之深而无不在也。", "b": "宋·王安石《游褒禅山记》"}, {"t": "而又含有音乐及诗歌之意味,故感人尤深。", "b": "蔡元培《图画》"}], "words": [{"w": "深心", "t": "细心;多心"}, {"w": "深心达算", "t": "老谋深算;内心精予计算"}, {"w": "深相砥砺", "t": "互相切磋探讨,以求深入理解"}, {"w": "深致", "t": "意义深远"}, {"w": "深闳", "t": "深远宏大"}, {"w": "深策", "t": "深远周密的计策"}, {"w": "深渺", "t": "深远,深微"}, {"w": "深赡", "t": "深刻而丰富"}, {"w": "深切著明", "t": "深刻而显明"}, {"w": "深大", "t": "深重广大。"}]}, {"meaning": "苛刻。", "cites": [{"t": "狱中多冤人,用刑深刻。", "b": "《后汉书·光武帝纪》"}], "words": [{"w": "深酷", "t": "苛刻严酷"}, {"w": "深故", "t": "执法苛刻严峻,故意加人罪名。"}]}, {"meaning": "深厚;亲密。", "cites": [{"t": "即长者之不忘老父,知老父之念长者深也。", "b": "明·宗臣《报刘一丈书》"}, {"t": "纵豆蔻词工,青楼梦好,难赋深情。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "交情深;深仁厚泽", "t": "深厚的仁爱和恩惠"}, {"w": "深眷", "t": "深切的关怀、照顾。"}]}, {"meaning": "历时久。", "cites": [{"t": "夜深忽梦少年事。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "深秋", "t": ""}]}, {"meaning": "大,重大。", "cites": [{"t": "子布、元表诸人各顾妻子,挟持私虑,深失所望。", "b": "《资治通鉴》"}, {"t": "然则古人所深耻者,后世且行之而不以为耻者多矣。", "b": "清·刘开《问说》"}], "words": [{"w": "深恩", "t": "大恩。"}]}, {"meaning": "深重;厉害、严重。", "cites": [{"t": "君有疾在腠理,不治将恐深。", "b": "《韩非子·喻老》"}]}, {"meaning": "很,甚。", "cites": [{"t": "面深墨。", "b": "《孟子·滕文公上》。注:“深,甚也。”"}], "words": [{"w": "深恐;深奸", "t": "内心非常奸诈"}, {"w": "深企", "t": "非常仰慕"}, {"w": "深娴", "t": "非常熟悉"}, {"w": "深罪", "t": "很怪罪;过分责备"}, {"w": "深韪", "t": "深以为是"}, {"w": "深荷", "t": "深肥;承蒙。"}]}, {"meaning": "测量。", "cites": [{"t": "彼将处乎不深之度,而藏乎无端之纪。", "b": "《列子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2433wx','涮','1','shuàn','氵','11','','[{"pinyin": "shuàn", "defs": [{"meaning": "(形声。从水,刷声。本义:荡洗。用水摇动或放在水里摆动洗清)。"}, {"meaning": "同本义。", "cites": [{"t": "涮,涮洗也。", "b": "《广韵》"}], "words": [{"w": "涮罐子;把衣服涮一涮;把瓶子涮干净", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2434wx','涵','1','hán','氵','11','','[{"pinyin": "hán", "defs": [{"meaning": "(形声。从水,圅声。本义:水泽众多) 同本义。", "cites": [{"t": "涵,水泽多也。", "b": "《说文》"}, {"t": "涵泳乎其中。", "b": "左思《吴都赋》"}, {"t": "涵,沉也。", "b": "《方言》十"}], "words": [{"w": "涵碧", "t": "形容水色碧绿深沉。"}]}, {"meaning": "浸润;滋润。", "cites": [{"t": "僭始既涵。", "b": "《诗·小雅·巧言》。按,谓浸润渐渍也。传训容,谓借为含"}], "words": [{"w": "涵煦", "t": "滋润覆照"}, {"w": "涵濡", "t": "滋润,浸渍"}, {"w": "涵浸", "t": "浸渍,滋润"}, {"w": "涵畅", "t": "滋润化育,使之发扬"}, {"w": "涵润", "t": "滋润。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2435wx','婆','1','pó','女','11','','[{"pinyin": "pó", "defs": [{"meaning": "——婆娑。"}, {"meaning": "(形声。从女,波声。本义:舞貌)。"}, {"meaning": "舞。", "cites": [{"t": "婆娑,舞也。", "b": "《尔雅》"}]}, {"meaning": "盘旋;停留。", "cites": [{"t": "婆娑虖术艺之场,休息虖篇籍之囿。", "b": "《汉书》"}]}, {"meaning": "分散;扶疏。", "cites": [{"t": "风鸿洞而不绝兮,优娆娆以婆娑。", "b": "《文选·王褒·洞箫赋》"}]}, {"meaning": "舒展。", "cites": [{"t": "醉时眠石上,肢体自婆娑。", "b": "唐·姚合《游河阳河岸》"}]}, {"meaning": "母。", "cites": [{"t": "阿婆不嫁女,那得孙儿抱?", "b": "《乐府诗集·佚名·折杨柳枝歌》"}]}, {"meaning": "古代广西少数民族对老人的称谓。", "cites": [{"t": "婆,男亦称婆。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2436wx','梁','1','liáng','木','11','','[{"pinyin": "liáng", "defs": [{"meaning": "(会意。从木,从水,刅(chuāng)声。从“木”从“水”,表示用木料在水上造桥。本义:水桥)。"}, {"meaning": "同本义。", "cites": [{"t": "梁,水桥也。", "b": "《说文》"}, {"t": "梁丽可以冲城。", "b": "《庄子·秋水》。司马注:“小船也。”"}, {"t": "除道梁溠。", "b": "《左传·庄公四年》"}, {"t": "谨关梁。", "b": "《礼记·月令》"}, {"t": "十一月舆梁成。", "b": "《孟子》"}, {"t": "十月成梁。", "b": "《国语·周语》"}, {"t": "津梁之上。", "b": "《国语·晋语》"}, {"t": "造桥为梁,不显其光。", "b": "《诗·大雅·大明》"}, {"t": "兹郑子引辇上高梁而不能支。", "b": "《韩非子·外储说右下》"}, {"t": "泽无舟梁。", "b": "《庄子》"}], "words": [{"w": "河梁", "t": "桥,又借指送别之地"}, {"w": "津梁", "t": "渡和桥梁"}, {"w": "桥梁", "t": "桥"}, {"w": "梁缘", "t": "为得到好的报应而做的修桥补路之类的好事"}, {"w": "梁头", "t": "桥头"}, {"w": "梁津", "t": "桥梁与渡口"}, {"w": "梁栈", "t": "桥梁。"}]}, {"meaning": "房梁。", "cites": [{"t": "兔从狗窦入,雉从梁上飞。", "b": "《乐府诗集·十五从军征》"}, {"t": "架梁之椽。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "横梁;悬梁", "t": "在房梁上上吊"}, {"w": "梁楹", "t": "屋“梁和大柱"}, {"w": "梁倚", "t": "如屋梁一般的相依附、倚靠"}, {"w": "梁木其坏", "t": "以梁木的折毁来比喻贤哲的死亡。"}]}, {"meaning": "稻粱", "cites": [{"t": "养以刍豢黍梁。", "b": "《淮南子·人间》"}], "words": [{"w": "梁肉", "t": "粱肉。泛指美酒佳肴。梁,通“粱”。"}]}, {"meaning": "山谷之间的延绵高地 。如:梁端(山顶);山梁。又指身体或物体上居中拱起或成弧形的部分。如:脊梁;鼻梁;深辀(古代车子的曲辕);梁冠(有横脊的冠)。"}, {"meaning": "堤堰;鱼堰。", "cites": [{"t": "毋逝我梁,毋发我笱。", "b": "《诗·邶风·谷风》"}, {"t": "隄谓之梁。", "b": "《尔雅》。注:“即桥也,或曰石绝水者为梁。”"}, {"t": "梁,水隄也。", "b": "《水经注·济水注》"}, {"t": "掌以时渔为梁。", "b": "《周礼·渔人》。司农注:“水偃也。偃水为关空,以笱承其空。”"}], "words": [{"w": "梁笱", "t": "泛指捕鱼具。梁,水中所筑的捕鱼之坝。"}]}, {"meaning": "国名。"}, {"meaning": "周时诸侯国。"}, {"meaning": "战国七雄之一,即魏。魏惠王于公元前362年迁都大梁,故称梁。", "cites": [{"t": "游于梁。", "b": "《战国策·齐策四》"}]}, {"meaning": "又。", "cites": [{"t": "梁使三反。", "b": ""}]}, {"meaning": "朝代名。"}, {"meaning": "南朝萧衍(梁武帝)所建(公元502—557年)。"}, {"meaning": "五代朱温(梁太祖)所建,史称后梁(公元907年—923年)。", "cites": [{"t": "梁,吾仇也。(黄巢部将朱温,叛变投降唐朝后,赐名全忠,受封为梁王。唐僖宗时,朱全忠拟谋杀李克用,李克用也屡次上表请求讨伐朱全忠。从此,梁、晋之间战争不息,仇恨日深。)", "b": "宋·欧阳修《伶官传·序》"}]}, {"meaning": "又。", "cites": [{"t": "背晋以归梁。", "b": ""}, {"t": "函梁君臣之首。", "b": ""}]}, {"meaning": "古九州之一 。辖境即今陕西省南部及四川省全部。"}, {"meaning": "", "cites": [{"t": "梁弘御戎。(梁弘给他驾驶兵车。御,驾御;戎,兵车。)", "b": "《左传·僖公三十三年》"}]}, {"meaning": "架桥、修桥。", "cites": [{"t": "令尹斗祁、莫敖屈重除道梁溠。", "b": "《左传·庄公四年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2437wx','渗','1','shèn','氵','11','','[{"pinyin": "shèn", "defs": [{"meaning": "(形声。从水,参(shēn)声。本义:水往下渗透)。"}, {"meaning": "同本义。", "cites": [{"t": "渗,下漉也。", "b": "《说文》"}, {"t": "滋液渗漉。", "b": "《汉书·司马相如传》。注:“谓润泽下究。”"}, {"t": "泽渗离而下降。", "b": "《汉书·扬雄传》"}, {"t": "百年老屋,尘泥渗漉,雨泽下注。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "水枯竭。", "cites": [{"t": "[到产之]自淮入泗,泗水渗,日裁行十里。", "b": "《南史》"}]}, {"meaning": "其他事物渐渐侵入。", "cites": [{"t": "远陂春日渗,犹有水禽飞。", "b": "唐·司空图《独望》"}]}, {"meaning": "人从空隙中挤进、穿入。", "cites": [{"t": "那儿正中围集着一大堆人,渗进去一看,原来也就是打诗谜的。", "b": "郭沫若《创造十年续篇》"}]}, {"meaning": "睡。", "cites": [{"t": "原来他方才合着桃仁杏花引子服一丸子乌金丸,躺在屋里就渗着了。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2438wx','情','1','qíng','忄','11','','[{"pinyin": "qíng", "defs": [{"meaning": "(形声。从心,青声。本义:感情)。"}, {"meaning": "同本义。", "cites": [{"t": "情,人之阴气有欲者也。", "b": "《说文》"}, {"t": "何谓人情?喜怒哀惧爱恶欲七者,弗学击能。", "b": "《礼记·礼运》又"}, {"t": "人情者,圣王之田也。", "b": ""}, {"t": "情伪相感。", "b": "《易·系辞》。虞注:“情阳也。”"}, {"t": "情者,阴之化也。", "b": "《白虎通·情形》"}, {"t": "情者,性之质也。", "b": "《荀子·正名》"}, {"t": "天若有情天亦老。", "b": "李贺《金铜仙人辞汉歌》"}, {"t": "览物之情", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "情所欲居。", "b": "清·黄宗羲《原君》"}, {"t": "遂利之情。", "b": ""}], "words": [{"w": "情熟", "t": "亲密"}, {"w": "情款", "t": "情意诚挚融洽"}, {"w": "情悃", "t": "情意;感情真挚,诚心诚意"}, {"w": "情热", "t": "感情深厚"}, {"w": "情肠", "t": "感情;情意"}, {"w": "情悰", "t": "情愫;感情,本心;真情实意"}, {"w": "无情", "t": "没有感情;不留情"}, {"w": "友情", "t": "朋友的感情;友谊"}, {"w": "情交", "t": "情感相通"}, {"w": "情好", "t": "情谊,交情"}, {"w": "情志", "t": "情感志趣"}, {"w": "情思", "t": "思念之情"}, {"w": "情切", "t": "感情真切。"}]}, {"meaning": "本性。", "cites": [{"t": "情,性也。", "b": "《吕氏春秋·上德》注"}, {"t": "夫物之不齐,物之情也。", "b": "《孟子·滕文公上》"}], "words": [{"w": "情性", "t": "天赋的本性"}, {"w": "情心", "t": "本性;性情"}, {"w": "情尚", "t": "性情与爱好"}, {"w": "情品", "t": "性格"}, {"w": "情素", "t": "真情;本心"}, {"w": "情行", "t": "犹品行。"}]}, {"meaning": "爱情。", "cites": [{"t": "唯将旧物表深情。", "b": "白居易《长恨歌》"}, {"t": "落日故人情。", "b": "唐·李白《送友人》"}, {"t": "愿天下有情人皆成眷属。", "b": "清·林觉民《与妻书》"}, {"t": "巾短情长。", "b": ""}], "words": [{"w": "情窦", "t": "爱情的萌芽"}, {"w": "情谈款叙", "t": "慢慢地谈情说爱"}, {"w": "情天", "t": "爱情的境界"}, {"w": "情田", "t": "播种爱情之田。"}]}, {"meaning": "实情,情况。", "cites": [{"t": "情,谓情实。", "b": "《周礼·天官》疏"}, {"t": "虚则知实之情。", "b": "《韩非子·主道》"}, {"t": "今人主不掩其情。", "b": "《韩非子·二柄》"}, {"t": "俱以情告。", "b": "《世说新语·自新》"}, {"t": "犹夫人之情。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "情词", "t": "有关罪情的供词"}, {"w": "情真", "t": "真情;事实"}, {"w": "内情", "t": "内部情况"}, {"w": "详情", "t": "详细的情形。"}]}, {"meaning": "私情;人情;情分。", "cites": [{"t": "不戴其情。", "b": "《淮南子·缪称》。注:“诚也。”"}, {"t": "执法而不求其情。", "b": "苏洵《上韩枢密书》"}], "words": [{"w": "情势", "t": "人情关系"}, {"w": "情常", "t": "常情"}, {"w": "情义", "t": "人情道义"}, {"w": "人情", "t": "情面;人之常情"}, {"w": "求情", "t": "请求对方答应或宽恕"}, {"w": "情曲", "t": "心曲,心里事。"}]}, {"meaning": "情趣,兴趣。", "cites": [{"t": "鸟啄灵雏恋落晖,村情山趣顾亡机。", "b": "段成式《题谷隐蘭若诗》"}], "words": [{"w": "情兴", "t": ""}]}, {"meaning": "道理;情理。", "cites": [{"t": "兵之情主速,乘人之不及。", "b": "《孙子·九地》"}, {"t": "缘物之情。", "b": "《吕氏春秋·慎行论》"}, {"t": "及人之情。", "b": ""}], "words": [{"w": "情款", "t": "情由"}, {"w": "情因", "t": "情由"}, {"w": "情本", "t": "事情的根由"}, {"w": "情旨", "t": "犹情由"}, {"w": "情纪", "t": "情理法纪。"}]}, {"meaning": "形态;情态;姿态。", "cites": [{"t": "含娇含态情不一。", "b": "卢照邻《长安古意》"}], "words": [{"w": "情儿", "t": "态度"}, {"w": "情迹", "t": "情状"}, {"w": "情首", "t": "谓出首自白其情状"}, {"w": "情踪", "t": "犹情状。"}]}, {"meaning": "真诚,真实。", "cites": [{"t": "民之情伪尽知之矣。", "b": "《左传·僖公二十八年》"}, {"t": "力极者厚赏,情尽者名立。", "b": "《韩非子·守道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2439wx','惜','1','xī','忄','11','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从心,昔声。本义:哀痛,哀伤)。"}, {"meaning": "同本义。", "cites": [{"t": "惜,痛也。", "b": "《说文》"}, {"t": "惜者,哀也。", "b": "《楚辞·惜誓序》"}, {"t": "为陛下惜之。", "b": "汉·贾谊《论积贮疏》"}, {"t": "惜其用武不终。", "b": "宋·苏洵《六国论》"}, {"t": "岁月为可惜。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "可惜", "t": "值得惋惜"}, {"w": "痛惜", "t": "沉痛地惋惜"}, {"w": "惜伤", "t": "哀伤。"}]}, {"meaning": "珍惜,爱惜,重视而不糟蹋耗费。", "cites": [{"t": "为天下惜死。", "b": "《吕氏春秋·长利》"}, {"t": "大禹圣者乃惜寸阴;至于众人,当惜分阴。", "b": "《晋书·陶侃传》"}, {"t": "视之不甚惜。", "b": "宋·苏洵《六国论》"}, {"t": "臣辈惜程艺。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "汝辈所惜。", "b": ""}, {"t": "朕不自谨惜。", "b": "清·张廷玉《明史》"}], "words": [{"w": "吝惜", "t": "过分爱惜"}, {"w": "怜惜", "t": "同情爱惜"}, {"w": "珍惜", "t": "珍重爱惜"}, {"w": "惜玉", "t": "对女子的温情爱护"}, {"w": "惜体面", "t": "爱面子"}, {"w": "惜福", "t": "富有而不肯过分享受"}, {"w": "惜护", "t": "十分爱护"}, {"w": "惜名", "t": "爱惜名声。"}]}, {"meaning": "惋惜。", "cites": [{"t": "惜其不成,是以就极刑而无愠色。", "b": "司马迁《报任安书》"}], "words": [{"w": "爱惜", "t": "惋惜、同情。"}]}, {"meaning": "哀怜、哀悯。", "cites": [{"t": "惜余年老而日衰兮,岁忽忽而不反。", "b": "《楚辞·惜誓》"}, {"t": "杨意不逢,抚凌云而自惜。", "b": "《滕王阁序》"}]}, {"meaning": "贪婪,贪求。", "cites": [{"t": "惜诵以致愍兮,发愤以抒情。", "b": "《楚辞·惜诵》"}]}, {"meaning": "吝惜;舍不得。", "cites": [{"t": "子卿视陵,岂偷生之士,而惜死之人哉?", "b": "李陵《答苏武书》"}, {"t": "驱将惜不得。", "b": "唐·白居易《卖炭翁》"}, {"t": "不惜牺牲生命。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "惜吝", "t": "吝惜;舍不得"}, {"w": "不惜工本;不惜金玉", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2440wx','惭','1','cán','忄','11','','[{"pinyin": "cán", "defs": [{"meaning": "(形声。从心,斩声。本义:羞愧)同本义。", "cites": [{"t": "慙,媿也。", "b": "《说文》"}, {"t": "不直失节谓之慙。", "b": "《小尔雅》"}, {"t": "富者有惭色。", "b": "清·彭端淑《为学一首示子侄》"}, {"t": "羊子大惭。", "b": "《后汉书·列女传》"}], "words": [{"w": "大言不惭;惭叹", "t": "惭愧感叹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2441wx','悼','1','dào','忄','11','','[{"pinyin": "dào", "defs": [{"meaning": "(形声。从心,卓声。本义:恐惧)。"}, {"meaning": "同本义。", "cites": [{"t": "悼,惧也。陈楚谓惧曰悼。", "b": "《说文》"}, {"t": "隐悼播越。", "b": "《国语·晋语》"}, {"t": "恐惧从处曰悼。", "b": "《周书·谥法》"}, {"t": "怵悼栗而耸兢。", "b": "张衡《西京赋》"}, {"t": "中心是悼。", "b": "《诗·桧风·羔裘》。注:“动也。”"}, {"t": "心栗手悼,书不成字。", "b": "陈寿《三国志》"}], "words": [{"w": "悼栗", "t": "因惊恐而战栗"}, {"w": "悼慑", "t": "害怕。"}]}, {"meaning": "悲痛;哀伤。", "cites": [{"t": "悼,哀也。", "b": "《广雅》"}, {"t": "七年曰悼。", "b": "《礼记·曲礼》。注:“怜爱也。”"}, {"t": "年中早夭曰悼。", "b": "《周书·谥法》"}, {"t": "静言思之,躬自悼矣。", "b": "《诗·卫风·氓》"}, {"t": "昔者,楚欲攻宋,墨子闻而悼之。", "b": "《淮南子·修务训》"}], "words": [{"w": "痛悼;恸悼;伤悼;哀悼", "t": "悲痛地追念"}, {"w": "悲悼", "t": "伤心悼念"}, {"w": "悼丧", "t": "悲伤沮丧。"}]}, {"meaning": "悼念。", "cites": [{"t": "帝闻之而悼之。", "b": "魏妆《魏书》"}], "words": [{"w": "悼恩", "t": "感怀恩德。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2442wx','惧','1','jù','忄','11','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从心,瞿声。本义:害怕,恐惧)。"}, {"meaning": "同本义。", "cites": [{"t": "惧,恐也。", "b": "《说文》"}, {"t": "是以举天下之人,皆恐惧振动惕栗,不敢为淫暴。", "b": "《墨子·尚同中》"}, {"t": "楚兵惧,自秦归。", "b": "《史记·屈原列传》"}, {"t": "夫大国,难测也,惧有伏焉。", "b": "《左传·庄公十年》"}, {"t": "故有知非以虑是,则谓之惧。", "b": "《荀子·解蔽》"}, {"t": "喜怒哀惧爱恶欲。", "b": "《礼记·礼运》"}, {"t": "勇者不惧。", "b": "《论语·子罕》"}], "words": [{"w": "惧思", "t": "因恐惧而慎重考虑"}, {"w": "惧选", "t": "害怕获罪"}, {"w": "惧高症", "t": "心理学名词。身处高处所产生的过分恐惧反应,不敢往下看、双腿发软、颤抖或晕眩等。"}]}, {"meaning": "恐吓。", "cites": [{"t": "危以动,则民不与也;惧以语,则民不应也。", "b": "《易》"}, {"t": "围徐以惧吴。", "b": "《左传·昭公十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2443wx','惕','1','tì','忄','11','','[{"pinyin": "tì", "defs": [{"meaning": "(形声。从心,易声。本义:害怕,放心不下)。"}, {"meaning": "同本义。", "cites": [{"t": "惕,惧也。", "b": "《玉篇》"}, {"t": "惕,敬也。", "b": "《说文》"}, {"t": "夕惕若厉。", "b": "《易·乾》。郑注:“惧也。”"}, {"t": "岂不使诸侯之心惕惕焉。", "b": "《国语·楚语》。注:“惧也。”"}, {"t": "无日不惕,岂敢忘职?", "b": "《左传·襄公二十二年》"}, {"t": "行人皆怵惕。", "b": "李白《古风五十九首》"}, {"t": "愧惕惭惧。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "惕息", "t": "忧心戒惧,不敢喘息。形容恐惧到了极点"}, {"w": "惕惕", "t": "忧心戒惧;忧劳"}, {"w": "惕 虑", "t": "戒慎谋虑"}, {"w": "惕心", "t": "心有所惧。"}]}, {"meaning": "忧伤。", "cites": [{"t": "血去惕出。", "b": "《易·小畜》。虞注:“忧也。”"}, {"t": "抱拙终身,以死谁惕。", "b": "柳宗元《乞巧文》"}], "words": [{"w": "惕然", "t": "忧虑的样子"}, {"w": "惕想", "t": "忧思。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2444wx','惟','1','wéi','忄','11','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从心,隹(zhuī)声。本义:思考;思念)。"}, {"meaning": "同本义。", "cites": [{"t": "惟,凡思也。", "b": "《说文》"}, {"t": "臣窃惟事势。", "b": "贾谊《治安策》"}, {"t": "吾惟之,坚子固不足遣。", "b": "《汉书·张良传》"}], "words": [{"w": "惟思", "t": "思虑"}, {"w": "惟度", "t": "思考忖度"}, {"w": "惟念", "t": "思念;考虑。"}]}, {"meaning": "为,是。", "cites": [{"t": "万邦黎献,共惟帝臣。", "b": "《书·益稷》"}, {"t": "不变惟何。", "b": "[英]赫胥黎著、严复译《天演论》"}]}, {"meaning": "有。", "cites": [{"t": "相亦惟终。", "b": "《礼记》"}]}, {"meaning": "听从,随从。", "cites": [{"t": "大国苟不以为然也,则亦惟命耳。", "b": "刘献廷《广阳杂记》"}], "words": [{"w": "惟惟", "t": "听从顺服的样子。"}]}, {"meaning": "愿,希望。", "cites": [{"t": "若草庵见毁一节,成功之后,万惟留心。", "b": "《英烈传》"}], "words": [{"w": "惟所欲为", "t": "想干什么就干什么,任意而为。"}]}, {"meaning": "在于。", "cites": [{"t": "德惟善政,政在养民。", "b": "《书·大禹谟》"}]}, {"meaning": "用来限定范围,相当于“只有”、“只是”。", "cites": [{"t": "惟明克允。", "b": "《书·舜典》"}, {"t": "惟士为能。", "b": "《孟子·梁惠王上》"}, {"t": "惟闻女叹息。", "b": "《乐府诗集·木兰诗》"}, {"t": "惟吾德馨。", "b": "唐·刘禹锡《陋室铭》"}, {"t": "惟有乳下孙。", "b": "杜甫《石壕吏》"}, {"t": "惟手熟尔。", "b": "宋·欧阳修《归田录》"}, {"t": "惟,独也。常语也。或作唯、维。", "b": "清·王引之《经传释词》"}], "words": [{"w": "惟一惟精", "t": "精诚专事,毫无杂念"}, {"w": "惟义是从", "t": "只要有道理就坚决服从"}, {"w": "惟口起羞", "t": "谓言语不慎,招致羞辱"}, {"w": "惟利是求", "t": "一心为利,别的什么都不顾"}, {"w": "惟精惟一", "t": "精纯专一。"}]}, {"meaning": "相当于“犹”、“还”。", "cites": [{"t": "惟,犹犹也。", "b": "裴学海《古书虚字集释》"}]}, {"meaning": "用在句首,表希望、祈使。", "cites": [{"t": "先王无流连之乐,荒亡之行,惟君所行也。", "b": "《孟子·梁惠王下》"}, {"t": "惟思既往。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "惟思将来。", "b": ""}, {"t": "惟留恋也。", "b": ""}, {"t": "惟希望也。", "b": ""}]}, {"meaning": "表示并列关系,相当于“与”、“和”。", "cites": [{"t": "告尔四国多方,惟尔殷侯尹民。", "b": "《书·多方》"}]}, {"meaning": "表示顺承关系,相当于“则”。", "cites": [{"t": "德威惟畏,德明惟明。", "b": "《书·吕刑》"}]}, {"meaning": "表示让步关系,相当于“即使”、“虽然”。", "cites": [{"t": "惟信亦为大王不如也。", "b": "《史记·淮阴候列传》"}]}, {"meaning": "由于,以。", "cites": [{"t": "亦惟汝故,以丕从厥志。", "b": "《书·盘庚中》"}]}, {"meaning": "用在年、月、日之前。", "cites": [{"t": "惟二月既望(既望:农历每月十六日)", "b": ""}]}, {"meaning": "用于句首,无实义。", "cites": [{"t": "惟士无田,则亦不祭。", "b": "《孟子》"}]}, {"meaning": "用在句中,起调整音节的作用。", "cites": [{"t": "无疆惟休,亦无疆惟恤。", "b": "《召诰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2445wx','惊','1','jīng','忄','11','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从马,敬声。本义:马受惊)。"}, {"meaning": "同本义。", "cites": [{"t": "驚,马骇也。", "b": "《说文》"}, {"t": "襄子至桥而马惊。", "b": "《战国策·赵策一》"}], "words": [{"w": "惊嘶", "t": "马受惊而嘶叫"}, {"w": "惊尘", "t": "车马疾驶所扬起的尘土"}, {"w": "惊镳", "t": "惊马。"}]}, {"meaning": "惊动;震惊。", "cites": [{"t": "宫庭震惊。", "b": "《楚辞·招魂》"}, {"t": "其生若惊。", "b": "《吕氏春秋·慎大》"}, {"t": "震惊百里。", "b": "《易·震卦》。郑注:“惊之言警戒也。”"}, {"t": "皆惊忙。", "b": "《乐府诗集·木兰诗》"}, {"t": "月出惊山鸟。", "b": "唐·王维《鸟鸣涧》"}, {"t": "惊问信之。", "b": "明·魏禧《大铁椎传》"}, {"t": "惊为生人。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "惊唬", "t": "惊动,吓唬"}, {"w": "惊耍", "t": "用惊吓的办法开玩笑;耍笑"}, {"w": "惊闺", "t": "惊闺叶。货郎为招徕顾客而使用的一种手摇响器。"}]}, {"meaning": "动。", "cites": [{"t": "波澜不惊。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "惊慌,恐惧。", "cites": [{"t": "秦王惊,自引而起。", "b": "《战国策·燕策》"}, {"t": "闻人声亦惊起。", "b": "苏轼《石钟山记》"}], "words": [{"w": "惊恍", "t": "惊慌,害怕"}, {"w": "惊怖", "t": "惊慌恐怖,惊吓"}, {"w": "惊报", "t": "灾祸的先兆"}, {"w": "惊疑", "t": "惊慌疑惑"}, {"w": "惊嘬嘬", "t": "非常提心、害怕的样子"}, {"w": "惊怖惕息", "t": "战战兢兢,恐惧不安的样子。"}]}, {"meaning": "纷乱。", "cites": [{"t": "莫敢直言,其生若惊。", "b": "《吕氏春秋》"}, {"t": "细尘障路起,惊花乱眼飘。", "b": "北周·庾信《侠客行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2446wx','惦','1','diàn','忄','11','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从心,店声。本义:惦记,挂念) 同本义", "words": [{"w": "惦算", "t": "总在计算,盘算"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2447wx','悴','1','cuì','忄','11','','[{"pinyin": "cuì", "defs": [{"meaning": "(形声。从心,卒声。本义:忧愁,悲伤)。"}, {"meaning": "同本义。", "cites": [{"t": "人力雕残,百姓愁悴。", "b": "《晋书·凉武昭王李玄盛传》"}], "words": [{"w": "悴民", "t": "指忧时而不得志的人"}, {"w": "悴沮", "t": "忧伤沮丧。"}]}, {"meaning": "憔悴;枯萎。", "cites": [{"t": "屈原…颜色憔悴,形容枯槁。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "悴容", "t": "憔悴的面容"}, {"w": "悴槁", "t": "枯槁"}, {"w": "悴颜", "t": "憔悴的脸色"}, {"w": "悴薄", "t": "衰弱单薄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2448wx','惋','1','wǎn','忄','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从心,宛声。本义:怨恨,叹惜) 同本义。", "cites": [{"t": "守穷者贫贱,惋叹泪如雨。", "b": "曹操《善哉行》"}, {"t": "皆叹惋。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "中医学术语。内热。", "cites": [{"t": "夫志悲者惋,惋则冲阴。", "b": "《素问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2449wx','惨','1','cǎn','忄','11','','[{"pinyin": "cǎn", "defs": [{"meaning": "(形声。从心,参声。本义:残酷,狠毒)。"}, {"meaning": "同本义。", "cites": [{"t": "惨,毒也。", "b": "《说文》"}, {"t": "惨毒行于民。", "b": "《汉书·陈汤传》"}, {"t": "苛惨失中。", "b": "《后汉书·周纺传》。注:“虐也。”"}, {"t": "惨如蜂虿。", "b": "《荀子·议兵》"}], "words": [{"w": "惨虐", "t": "残酷暴虐"}, {"w": "惨无人理", "t": "惨无人道。"}]}, {"meaning": "悲痛;伤心。", "cites": [{"t": "惨于腹。", "b": "《列子·杨朱》。释文:“惨,痛也。”"}, {"t": "惨怛于心。", "b": "《汉书·元帝纪》。师古曰:“惨,痛也。”"}, {"t": "醉不成欢惨将别。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "死事之惨,以辛亥三月二十九日围攻两广督署之役为最。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "凄惨", "t": "凄凉悲惨"}, {"w": "悲惨", "t": "处境或遭遇极其痛苦,令人伤心"}, {"w": "惨不忍言", "t": "不忍心把悲惨情形说出口。"}]}, {"meaning": "厉害;程度严重。", "cites": [{"t": "冰霜惨烈。", "b": "张衡《西京赋》"}, {"t": "下阴潜以惨禀兮。", "b": "扬雄《甘泉赋》"}], "words": [{"w": "惨阳", "t": "阳气盛极而炎热。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2450wx','惯','1','guàn','忄','11','','[{"pinyin": "guàn", "defs": [{"meaning": "(形声。从心,贯声。本义:习惯,惯常) 同本义。", "cites": [{"t": "惯,习也。", "b": "《尔雅》"}, {"t": "譬如田猎,射御惯,则能获禽。", "b": "《左传·襄公三十一年》"}, {"t": "谓客曰:“宗军人,惯啖粗食。”", "b": "《宋书·宗悫传》"}, {"t": "但是她俩劳动惯了,离开土地就不舒服,所以还是回了家。", "b": "《回忆我的母亲》"}], "words": [{"w": "惯熟", "t": "因经常做某事而动作熟练;因经常见面而熟悉习惯"}, {"w": "惯历", "t": "惯常经过,不止一次经过"}, {"w": "惯经", "t": "习惯,惯常所经历的"}, {"w": "惯有", "t": "常有,习惯所具有。"}]}, {"meaning": "纵容;迁就。", "cites": [{"t": "别把孩子给惯坏了", "b": ""}], "words": [{"w": "惯宠", "t": "宠爱纵容。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2451wx','寇','1','kòu','宀','11','','[{"pinyin": "kòu", "defs": [{"meaning": "(会意。从宀(mián),表示与室家房屋有关,从元(人),从攴(pū),表示持械击打。意思是手持器械的人,侵犯到房子里来打人。本义:入侵;侵犯)。"}, {"meaning": "同本义。", "cites": [{"t": "寇,暴也。与败贼 同义(朋侵)。", "b": "《说文》"}, {"t": "寇贼奸宄。", "b": "《书·舜典》。传:“群行攻劫曰寇。”郑注:“强取为寇。”"}, {"t": "凡兵作于内为乱,于外为寇。", "b": "《左传·文公七年》"}, {"t": "大兵不寇。", "b": "《吕氏春秋·贵公》"}, {"t": "匈奴背叛不臣,数为寇暴于边鄙。", "b": "《盐铁论·本议》"}, {"t": "吐蕃发十万兵寇西川。", "b": "《资治通鉴》"}], "words": [{"w": "寇戎", "t": "来犯的敌军"}, {"w": "寇虐(侵掠残害之行)寇钞(攻劫掠夺", "t": ""}, {"w": "寇剽", "t": "抢劫"}, {"w": "寇钞", "t": "亦作“寇抄”。劫掠"}, {"w": "寇攘", "t": "劫掠;侵扰"}, {"w": "寇窃", "t": "抢劫;盗窃。"}]}, {"meaning": "砍伐。", "cites": [{"t": "山木自寇也,膏火自煎也。", "b": "《庄子·人间世》"}]}, {"meaning": "入侵者。", "cites": [{"t": "西山寇盗莫相侵。", "b": "杜甫《登楼》"}]}, {"meaning": "敌人。", "cites": [{"t": "岂可复留此残寇,使长为国家之忧者。", "b": "《资治通鉴》"}]}, {"meaning": "贼兵,敌军。", "cites": [{"t": "在宋城上而待楚寇矣。", "b": "《墨子·公输》"}, {"t": "今寇众我寡。", "b": "《资治通鉴》"}], "words": [{"w": "寇乱", "t": "外寇与内乱。兵起于外为寇,起于内为乱。"}]}, {"meaning": "盗匪。", "cites": [{"t": "北与寇往来其间。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "寇逆", "t": "贼寇,叛逆"}, {"w": "寇劫", "t": "指行劫的群盗"}, {"w": "寇戎", "t": "匪患与战争"}, {"w": "寇奸", "t": "寇贼奸宄。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2452wx','寅','1','yín','宀','11','','[{"pinyin": "yín", "defs": [{"meaning": "(象形。据甲骨文为矢形。小篆讹变。本义:恭敬) 同本义。", "cites": [{"t": "寅,居敬也。", "b": "《说文》"}, {"t": "寅,敬也。", "b": "《尔雅》"}, {"t": "夙夜惟寅。", "b": "《书·舜典》"}, {"t": "严恭寅畏。", "b": "《书·无逸》"}, {"t": "寅哉寅哉。", "b": "《周书·祭公》"}, {"t": "寅宾出日。", "b": "《书·尧典》"}], "words": [{"w": "寅亮", "t": "恭敬信奉"}, {"w": "寅畏", "t": "恭敬畏惧"}, {"w": "寅清", "t": "言行恭谨,持心清正。"}]}, {"meaning": "地支的第三位。", "cites": [{"t": "寅,髌也。正月易气动,去黄泉欲上出,侌尚强也。", "b": "《说文》。段玉裁注:“髌,字之误也,当作ń。”"}], "words": [{"w": "星次序数之一古代天文学十二星次中的“析木”为寅", "t": ""}]}, {"meaning": "用以纪时,指凌晨三至五时。", "cites": [{"t": "寅不通光,而卯则日出。", "b": "《西游记》"}], "words": [{"w": "寅正一刻", "t": "四点一刻。"}]}, {"meaning": "五行属木。", "cites": [{"t": "寅,木也。", "b": "《论衡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2453wx','寄','1','jì','宀','11','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从宀(mián),表示与家室房屋有关,奇声。本义:寄居)。"}, {"meaning": "同本义。", "cites": [{"t": "寄,托也。", "b": "《说文》"}, {"t": "寄公者,何失地之君也。", "b": "《仪礼·丧服》传"}, {"t": "可以寄百里之命。", "b": "《论语》。皇疏:“寄是暂寄有反之目也。”"}, {"t": "老妻寄异县,十口隔风雪。", "b": "杜甫《自京赴奉先县咏怀五百字》"}], "words": [{"w": "寄籍", "t": "寄居外地而附以户籍的叫寄籍"}, {"w": "寄庄", "t": "在外地买地设庄,收租。"}]}, {"meaning": "委托,托付。", "cites": [{"t": "令可以寄政。", "b": "《国语·齐语》"}, {"t": "先帝知臣谨慎,故临崩寄臣以大事也。", "b": "诸葛亮《出师表》"}, {"t": "倚南窗以寄傲。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "寄命", "t": "委以重任;生命如寄旅,因此比喻短暂的生命"}, {"w": "寄付", "t": "委托;托付"}, {"w": "寄任", "t": "指所委托的重要责任;托付重任。"}]}, {"meaning": "依赖;依附。", "cites": [{"t": "托根附树身,开花寄树梢。", "b": "白居易《有木诗》"}, {"t": "蛮烟瘴雨土卑湿,留我寄命与兹乡。", "b": "黄景仁《洞庭行赠大归包川》"}], "words": [{"w": "寄命", "t": "寄身;托身"}, {"w": "寄口", "t": "依靠别人生活。"}]}, {"meaning": "寄放;寄存。", "cites": [{"t": "前以一匹锦相寄,今可见还。", "b": "《南史·江淹传》"}], "words": [{"w": "寄包", "t": "寄存行李;喻指寄宿"}, {"w": "寄物", "t": "寄存的东西;寄托某件物品作为凭证。"}]}, {"meaning": "寄托。", "cites": [{"t": "依南窗以寄傲,审容膝之易安。", "b": "陶潜《归去来兮辞》"}, {"t": "先王寄理于竹帛。", "b": "《韩非子·安危》"}], "words": [{"w": "寄怀", "t": "寄托情志;用真诚的心意待人"}, {"w": "寄意", "t": "寄托情意。"}]}, {"meaning": "托人递送。", "cites": [{"t": "女寄言于母。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "寄声", "t": "托人口头传达问候"}, {"w": "寄外", "t": "妻子寄信或他物给丈夫"}, {"w": "寄言", "t": "寄语、带信"}, {"w": "寄奉", "t": "敬词。谓通过邮递奉呈。"}]}, {"meaning": "人物名。", "cites": [{"t": "寄伪儿啼。(区寄假装像小孩子的啼哭。儿,名词作状语,表示比喻,像小孩子似的。)", "b": "唐·柳宗元《童区寄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2454wx','寂','1','jì','宀','11','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从宀(mián),叔声。本义:静悄悄,没有声音)。"}, {"meaning": "同本义。", "cites": [{"t": "寂,无人声。", "b": "《说文》"}, {"t": "寂寥宇宙。", "b": "《四子讲德论》"}, {"t": "寂兮寥兮,独立不改。", "b": "《老子》"}, {"t": "寂然不动。", "b": "《易·系辞上》"}, {"t": "四面竹树环合,寂寥无人。", "b": "柳宗元《永州八记》"}, {"t": "满坐寂然。", "b": "《虞初新志·秋声诗自序》"}, {"t": "人视端容寂。", "b": "明·魏学洢《核舟记》"}, {"t": "俄而寂然。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "寂寂悄悄", "t": "悄悄地,不弄出声音地"}, {"w": "寂密", "t": "隐密"}, {"w": "寂天寞地", "t": "悄无声息。"}]}, {"meaning": "安详闲静,心志淡泊。", "cites": [{"t": "旷然无忧患,寂然无思虑。", "b": "嵇康《养生论》"}], "words": [{"w": "寂泊", "t": "恬静淡泊,不追求名利"}, {"w": "寂漠", "t": "清静;恬淡。"}]}, {"meaning": "寂寞;孤单;冷落。", "cites": [{"t": "廓落寂而无友兮,谁可与玩此遗芳。", "b": "严忌《哀时命》"}], "words": [{"w": "寂处", "t": "寂寞独处"}, {"w": "寂漠", "t": "冷落;凄凉"}, {"w": "寂淹", "t": "孤寂滞留。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2455wx','宿','1','sù xiǔ xiù','宀','11','','[{"pinyin": "sù", "defs": [{"meaning": "(形声。据甲骨文,象人睡在室内席子上。本义:住宿;过夜)。"}, {"meaning": "同本义。", "cites": [{"t": "宿,止也。", "b": "《说文》"}, {"t": "出宿于干。", "b": "《诗·邶风·泉水》"}, {"t": "言就尔宿。", "b": "《诗·小雅·我行其野》"}, {"t": "戒及宿之日。", "b": "《周礼·大史》"}, {"t": "孟子去齐,宿于昼。", "b": "《孟子·公孙丑下》"}, {"t": "止子路宿,杀鸡为黍而食之。", "b": "《论语·微子》"}, {"t": "旦辞爷娘去,暮宿黄河边。", "b": "《乐府诗集·木兰诗》"}, {"t": "不得已,度姓名,诡蹄迹,草行露宿,日与北骑相出没长淮间。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "宿歇", "t": "住宿,睡觉"}, {"w": "宿坛", "t": "住宿"}, {"w": "宿泊", "t": "住宿;安歇"}, {"w": "宿夜然诺", "t": "存留过夜的诺言"}, {"w": "宿客", "t": "投宿的旅客"}, {"w": "宿宿", "t": "连住两夜"}, {"w": "宿顿", "t": "临时寄住"}, {"w": "宿止", "t": "住宿"}, {"w": "宿地", "t": "住宿的地方"}, {"w": "宿所", "t": "住宿过夜的处所。"}]}, {"meaning": "值宿守卫,守夜。", "cites": [{"t": "哀王三弟,其弟章,入宿卫于汉,吕太守封为朱虚侯。", "b": "《史记·齐悼惠王世家》"}], "words": [{"w": "宿直", "t": "值夜"}, {"w": "宿卫", "t": "在宫中值宿护卫。"}]}, {"meaning": "处于。", "cites": [{"t": "我生之辰,月宿南斗。牛奋其角,箕张其口。", "b": "唐·韩愈《三星行》"}]}, {"meaning": "隐含;寄寓。", "cites": [{"t": "在西洋有一句成语,叫做健全的精神,宿于健全的身体。", "b": "蔡元培《普通教育和职业教育》"}]}, {"meaning": "安心;安于。", "cites": [{"t": "官宿其业,其物乃至。", "b": "《左传》"}]}, {"meaning": "古代官道上设立的住宿站。", "cites": [{"t": "三十里有宿,宿有路室。", "b": "《周礼》"}], "words": [{"w": "宿息", "t": "上古称宾客于道路休息住宿之处。"}]}, {"meaning": "夜。", "cites": [{"t": "不出宿夕,人必危之矣。", "b": "《战国策·赵策》"}], "words": [{"w": "宿露", "t": "夜露"}, {"w": "宿雾", "t": "夜雾"}, {"w": "宿膳", "t": "夜餐"}, {"w": "宿夕", "t": "一个晚上。比喻短时间内"}, {"w": "宿烟", "t": "夜里的烟雾"}, {"w": "宿云", "t": "夜晚的云气。"}]}, {"meaning": "栖宿之鸟。", "cites": [{"t": "子钓而不纲,弋不射宿。", "b": "《论语》"}]}, {"meaning": "有名望的人。", "cites": [{"t": "迟先生有制礼作乐之才,乃是南邦名宿。", "b": "《儒林外史》"}]}, {"meaning": "从前,往日。", "cites": [{"t": "内负宿心,外恧良朋。", "b": "三国魏·嵇康《幽愤》"}], "words": [{"w": "宿意;宿传", "t": "往昔的传说"}, {"w": "宿孽", "t": "前世的罪孽"}, {"w": "宿顾", "t": "以往的关照。"}]}, {"meaning": "老的,积久的。", "cites": [{"t": "民有宿逋不可诚于上供者,必代而输之。", "b": "唐·杜牧《吏部尚书·崔公行状》"}], "words": [{"w": "宿气", "t": "旧怨;旧仇"}, {"w": "宿愤", "t": "旧怨;旧恨"}, {"w": "宿罪", "t": "旧有的罪过"}, {"w": "宿好", "t": "老交情"}, {"w": "宿恩", "t": "以往的恩德"}, {"w": "宿嫌", "t": "旧日的嫌隙"}, {"w": "宿旧", "t": "旧友"}, {"w": "宿威", "t": "素有的威名"}, {"w": "宿老", "t": "老前辈"}, {"w": "宿齿", "t": "年老之人。"}]}, {"meaning": "隔夜的,前一夜的。", "cites": [{"t": "桃红复含宿雨,柳绿更带春烟。", "b": "唐·王维《田园乐》"}, {"t": "臣闻千里餽粮,士有饥色;樵苏后爨,师不宿饱。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "宿料", "t": "隔夜的草料"}, {"w": "宿雨", "t": "隔夜的雨"}, {"w": "宿租", "t": "隔年的租税"}, {"w": "宿酲", "t": "酒醉隔夜未醒。"}]}, {"meaning": "前一年的,隔年的。", "cites": [{"t": "元狩三年,遣谒者劝月水灾郡种宿麦。", "b": "《汉书·武帝纪》"}], "words": [{"w": "宿麦", "t": "隔年成熟的麦"}, {"w": "宿雪", "t": "积留过冬的雪。"}]}, {"meaning": "老成阅历久的。", "cites": [{"t": "王肃以宿德显授。", "b": "三国魏·应休琏《与侍郎曹长思书》"}], "words": [{"w": "宿兵", "t": "宿素习练之兵"}, {"w": "宿艾", "t": "老成长者"}, {"w": "宿生", "t": "老成博学的读书人"}, {"w": "宿吏", "t": "阅历多的官吏"}, {"w": "宿彦", "t": "老成而有才德之士。"}]}, {"meaning": "前世注定的。", "cites": [{"t": "以此常欲焚笔弃砚为喑默人,而习气宿业,未能尽去。", "b": "宋·苏轼《答刘沔都曹书》"}], "words": [{"w": "宿业", "t": "指前世行善或作恶所造成而见于今世的后果"}, {"w": "宿慧", "t": "前世带来的慧根"}, {"w": "宿殃", "t": "前世注定的灾殃"}, {"w": "宿败", "t": "注定要失败"}, {"w": "宿福", "t": "前世注定的福分。"}]}, {"meaning": "旧欠的。", "cites": [{"t": "逋租宿债勿复收。", "b": "《宋书·武帝纪》"}], "words": [{"w": "宿债", "t": "旧欠的债务"}, {"w": "宿值", "t": "久欠的债"}, {"w": "宿赋", "t": "积欠的赋税。"}]}, {"meaning": "平素,平日。", "cites": [{"t": "官宿其业,其物乃至。", "b": "《左传·昭公二十九年》"}, {"t": "子路无宿诺。", "b": "《论语·颜渊》"}, {"t": "奈何忘宿志而惭儿女子乎?", "b": "《后汉书·王霸妻传》"}, {"t": "宿志在人外,清心游物初。", "b": "宋·陆游《幽居》"}, {"t": "表招诱有力,威怀兼洽 ,其 姦猾宿贼,更为效用,万里肃青。", "b": "《后汉书·刘表传》"}], "words": [{"w": "宿愿;宿容", "t": "平日的容颜"}, {"w": "宿寇", "t": "惯匪"}, {"w": "宿心,宿志", "t": "平日的心愿。"}]}, {"meaning": "预先;早先。", "cites": [{"t": "善属文,举笔便成,无所改定,时人常以为宿构。", "b": "《三国志·王粲传》"}], "words": [{"w": "宿构", "t": "预先构思"}, {"w": "宿闻", "t": "早已知闻"}, {"w": "宿虑", "t": "预先思考、谋划"}, {"w": "宿读", "t": "预先读过。"}]}]}, {"pinyin": "xiǔ", "defs": [{"meaning": "用于计算夜。", "cites": [{"t": "军士今夜且歇一宿,以养锐气。", "b": "《三国演义》"}], "words": [{"w": "住了一宿", "t": ""}]}]}, {"pinyin": "xiù", "defs": [{"meaning": "星座的古名。星宿 。二十八宿:坐落在黄道的星宿,按照中国古代的分法,共有二十八个。黄道是日在星际所行的路。", "cites": [{"t": "天果积气,日月星宿不当坠邪?", "b": "《列子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2456wx','窒','1','zhì','穴','11','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从穴,至声。洞穴狭小阻塞,故从穴。本义:阻塞,不通)。"}, {"meaning": "同本义。", "cites": [{"t": "窒,塞也。", "b": "《说文》"}, {"t": "有孚窒。", "b": "《易·讼》。虞注:“塞止也。”"}, {"t": "精不流则气郁,郁处头则为肿为风…处鼻则为鼽为窒。", "b": "《吕氏春秋·尽数》。注:“不通也。”"}, {"t": "穹窒熏鼠。", "b": "《诗·豳风·七月》"}], "words": [{"w": "窒塞;窒阂", "t": "闭塞,阻隔。"}]}, {"meaning": "抑止住使不发泄。", "cites": [{"t": "损,君子以惩忿窒欲。", "b": "《易·损》"}], "words": [{"w": "窒抑", "t": "阻遏;抑制"}, {"w": "窒欲", "t": "抑制欲望"}, {"w": "窒滞", "t": "阻碍"}, {"w": "窒沮", "t": "阻滞"}, {"w": "窒郁", "t": "抑郁;沉闷"}, {"w": "窒士", "t": "不得志的文人。"}]}, {"meaning": "障碍物。", "cites": [{"t": "有窒皆通。", "b": "《丞相答刺罕赠谥制》"}], "words": [{"w": "窒烦", "t": "排除烦乱的心情。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2457wx','窑','1','yáo','穴','11','','[{"pinyin": "yáo", "defs": [{"meaning": "(会意。从穴,从缶(fǒu)。穴,土室;缶,瓦器。表示烧制瓦器的地方。本义:烧砖瓦陶瓷器的灶)。"}, {"meaning": "同本义。", "cites": [{"t": "窯,烧瓦灶也。", "b": "《说文》"}, {"t": "陶灶曰窯。", "b": "《通俗文》"}, {"t": "文采纂组者,燔功之窑也。", "b": "《管子·七臣七主》"}, {"t": "穴内口为灶,令如窑,令容七八员艾,左右窦皆如此。", "b": "《墨子》"}], "words": [{"w": "窑头土坯", "t": "窑头上未经烧制的砖瓦坯。比喻土里土气,未曾受教化的人"}, {"w": "窑神", "t": "旧称主宰砖瓦窑的神灵"}, {"w": "窑烟", "t": "烧制砖瓦陶瓷等的灶里冒出的烟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2458wx','密','1','mì','宀','11','','[{"pinyin": "mì", "defs": [{"meaning": "(形声。从山,宓(mì)声。本义:形状象堂屋的山)。"}, {"meaning": "同本义(意思是山多)。", "cites": [{"t": "密,山如堂者。", "b": "《说文》"}, {"t": "松柏之鼠,不知堂密之有美枞。", "b": "《尸子》"}]}, {"meaning": "隐蔽的地方。", "cites": [{"t": "不窥密。", "b": "《礼记·少仪》。注:“隐曲处也。”"}]}, {"meaning": "假借为“比”。稠密;多。", "cites": [{"t": "密,稠 也,疏之对也。", "b": "《增韵》"}, {"t": "密云不雨。", "b": "《易·小畜卦》"}, {"t": "加密石焉。", "b": "《国语·晋语八》"}, {"t": "以陈楚之密迩于楚。", "b": "《左传·文公十七年》"}, {"t": "密布字印。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "密则无态。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "文理有疏密;斫直删密;密札札,密匝匝", "t": "严实稠密的样子"}, {"w": "密茂", "t": "茂密"}, {"w": "密茫茫", "t": "繁茂密集无边无际的样子"}, {"w": "密茸茸", "t": "密集丛生的样子"}, {"w": "密丛丛", "t": "茂盛丛集的样子。"}]}, {"meaning": "亲密(强调关系上的亲近)。", "cites": [{"t": "情好日密。", "b": "《三国志·诸葛亮传》"}, {"t": "昵交密友,亦不半在。", "b": "陆机《叹逝赋序》"}], "words": [{"w": "密近", "t": "帝王左右亲近信用的人"}, {"w": "密坐", "t": "靠近而坐,形容关系亲密。"}]}, {"meaning": "秘密的,隐密的,慎密的。", "cites": [{"t": "密移造化出闽山,禁御新栽荔枝丹。", "b": "《宣和殿荔枝》"}, {"t": "密通洞庭。", "b": "唐·李朝威《柳毅传》"}, {"t": "密奏请皇上。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "宦人密侍;出密诏示之;荣禄密谋;奉有密诏;密章", "t": "秘密奏章"}, {"w": "密启", "t": "秘密的书画"}, {"w": "密揭", "t": "秘密的奏疏式文告"}, {"w": "密幄", "t": "密室"}, {"w": "密诏", "t": "秘密的诏书。"}]}, {"meaning": "紧密。", "cites": [{"t": "其土欲故,其筑欲密。", "b": "柳宗元《种树郭橐驼传》"}]}, {"meaning": "安宁;安定;安静。", "cites": [{"t": "成王不敢康,夙夜基命宥密。", "b": "《诗·周颂·昊天有成命》"}, {"t": "密,静也。", "b": "《尔雅·释诂》"}, {"t": "四海遏密八音。", "b": "《书·舜典》。传:“密,静也。”"}, {"t": "止旅乃密。", "b": "《诗·大雅·公刘》"}, {"t": "京室密清。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "密如", "t": "安定的样子"}, {"w": "密清", "t": "安静洁净。"}]}, {"meaning": "严密。", "cites": [{"t": "古之为国者,甚虑敌深,其防患密。", "b": "辛弃疾《美芹十论》"}, {"t": "刘桢壮而不密。", "b": "曹丕《典论论文》"}, {"t": "凡道必周密。", "b": "《管子·内业》"}], "words": [{"w": "密心", "t": "精细的用心"}, {"w": "密巧", "t": "精细,纤巧"}, {"w": "密石", "t": "纹理细密的石料"}, {"w": "密要", "t": "精密准确"}, {"w": "密科", "t": "繁苛的法律条文。"}]}, {"meaning": "不语。", "cites": [{"t": "公密而不应。", "b": "《庄子·达生》"}]}, {"meaning": "接近。", "cites": [{"t": "以敝邑介在东表,密迩仇雠,寡君将君是望。", "b": "《左传·襄公三年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2459wx','谋','1','móu','讠','11','','[{"pinyin": "móu", "defs": [{"meaning": "(形声。从言,某声。本义:考虑;谋划)。"}, {"meaning": "同本义(侧重于商议出办法或盘算出主意)。", "cites": [{"t": "虑难曰谋。", "b": "《说文》"}, {"t": "聪作谋。", "b": "《书·洪范》"}, {"t": "咨难为谋。", "b": "《左传·襄公四年》"}, {"t": "谁适与谋。", "b": "《诗·小雅·苍伯》"}, {"t": "在事为诗,未发为谋。", "b": "《春秋·说题辞》"}, {"t": "心思为谋。", "b": "《论衡·超奇》"}, {"t": "谋及子孙,可谓死君乎。", "b": "《左传·僖公三十三年》"}, {"t": "未能远谋。", "b": "《左传·庄公十年》"}, {"t": "肉食者谋之。", "b": ""}, {"t": "聚室而谋。", "b": "《列子·汤问》"}, {"t": "谋诸漆工。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "谋谟殚神", "t": "筹谋划策,竭尽全力"}, {"w": "不谋而合;合谋", "t": "共同策划"}, {"w": "谋及庶人", "t": "与百姓共商国事"}, {"w": "思谋", "t": "方言。思索;考虑"}, {"w": "谋始", "t": "于开始时慎重考虑"}, {"w": "谋章", "t": "考虑文章的篇章结构。"}]}, {"meaning": "计议;商议。", "cites": [{"t": "谋,议也。", "b": "《广雅》"}, {"t": "聚室而谋。", "b": "《列子·汤问》"}], "words": [{"w": "谋迹", "t": "议其行事"}, {"w": "谋阙", "t": "商议补救缺失"}, {"w": "谋合", "t": "合伙同谋。"}]}, {"meaning": "图谋;营求。", "cites": [{"t": "君子谋道不谋食。", "b": "《论语·卫灵公》"}, {"t": "亦宜自谋。", "b": "诸葛亮《出师表》"}, {"t": "谋袭蔡州。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "谋论", "t": "谋划揣摩"}, {"w": "谋断", "t": "谋划决断"}, {"w": "谋为不轨", "t": "图谋不轨"}, {"w": "谋首", "t": "主谋者"}, {"w": "谋犹", "t": "计谋。也作谋猷"}, {"w": "谋干", "t": "谋求;钻营"}, {"w": "谋虚逐妄", "t": "谋求追逐虚幻不实的东西"}, {"w": "谋道", "t": "探求事理和道义等。"}]}, {"meaning": "咨询。", "cites": [{"t": "载驰载驱,周爰咨谋。", "b": "《诗·小雅》"}, {"t": "咨事为谋。", "b": "《国语·鲁语》"}], "words": [{"w": "谋筮", "t": "问卜"}, {"w": "谋询", "t": "咨询"}, {"w": "谋龟", "t": "问卜。"}]}, {"meaning": "策略,计谋。", "cites": [{"t": "辩说属辞,饰非诈谋。", "b": "《韩非子·存韩》"}, {"t": "小不忍则乱大谋。", "b": "《论语》"}, {"t": "无以小谋败大作。", "b": "《礼记·缁衣》。注:“小臣之谋也。”"}, {"t": "非常之谋难于猝发。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "谋不逮下", "t": "谋略不及下等水平"}, {"w": "谋定后动", "t": "计划稳妥之后再采取行动"}, {"w": "计谋", "t": "战争中欺蒙并智胜敌人的策略"}, {"w": "足智多谋;有勇无谋", "t": ""}]}, {"meaning": "媒介。", "cites": [{"t": "君臣之会,六者谓之谋。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2460wx','谍','1','dié','讠','11','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从言,枼(yè)声。本义:间谍,细作)。"}, {"meaning": "间谍。", "cites": [{"t": "谍,军中反间也。", "b": "《说文》"}, {"t": "掌斩杀贼谍而搏之。", "b": "《周礼·掌戮》"}, {"t": "搏贼谍。", "b": "《周礼·环人》。注:“反间为国贼。”"}, {"t": "晋人获秦谍。", "b": "《左传·宣公八年》"}, {"t": "谍报敌情至。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "防谍;谍贼", "t": "暗探和叛国贼"}, {"w": "谍人", "t": "间谍。"}]}, {"meaning": "传递的情报。", "cites": [{"t": "宁边军数日间连受八十余谍。", "b": "《续资治通鉴》"}]}, {"meaning": "书札。", "cites": [{"t": "太史公读春秋历谱谍。", "b": "《史记·十二诸侯年表序》"}]}, {"meaning": "又。", "cites": [{"t": "宫童效异,披图案谍。", "b": "《汉书·礼乐志》"}, {"t": "故一介之策,各有攸建,子长谍之,爓然有第。", "b": "《后汉书·张衡传》"}]}, {"meaning": "暗中窥伺敌情或秘密。", "cites": [{"t": "罗人欲伐之,使伯嘉谍之。", "b": "《左传·恒公十二年》"}], "words": [{"w": "谍探", "t": "侦察"}, {"w": "谍查", "t": "侦察,探听。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2461wx','谎','1','huǎng','讠','11','','[{"pinyin": "huǎng", "defs": [{"meaning": "(形声。从言,荒声。本义:谎言,假话)。"}, {"meaning": "梦中讲的话。", "cites": [{"t": "谎,梦言也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2462wx','谐','1','xié','讠','11','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从言,皆声。本义:和谐)。"}, {"meaning": "同本义(强调配合得匀称)。", "cites": [{"t": "谐,和也。", "b": "《尔雅》"}, {"t": "克谐以孝。", "b": "《书·尧典》"}, {"t": "掌司万民之难而谐和之。", "b": "《周礼·调人》"}, {"t": "如乐之和,无所不谐。", "b": "《左传·襄公十一年》"}, {"t": "如其克谐,天下可定也。", "b": "《资治通鉴·赤壁之战》"}, {"t": "夫妻谐老。", "b": "《初刻拍案惊奇》"}], "words": [{"w": " 谐当", "t": "妥当"}, {"w": "谐和", "t": "各组成部分之间协调地相互联系在一起的"}, {"w": "谐调", "t": "和谐"}, {"w": "谐奏", "t": "和协地演奏"}, {"w": "谐律", "t": "谐合于音律。"}]}, {"meaning": "言语或行为有趣而引人发笑。", "cites": [{"t": "上以朔口谐辞给,好作问之。", "b": "《汉书·东方朔传》"}, {"t": "心亲不复异新旧,使脱巾屦相谐嬉。", "b": "宋·王安石《和刘贡甫燕集之作》"}, {"t": "醉中共笑语,往往杂谐谚。", "b": "明·高启《赠杨荥阳》"}], "words": [{"w": "谐易", "t": "诙谐平易"}, {"w": "谐辞", "t": "戏谑之辞"}, {"w": "谐谚", "t": "诙谐谚语"}, {"w": "谐画", "t": "富于谐趣的话。"}]}, {"meaning": "办妥,办成功。", "cites": [{"t": "恐事不谐,反遭其害。", "b": "《三国演义》"}, {"t": "今事不谐,不过赤族,为社稷死,岂不快乎?", "b": "《宋史》"}], "words": [{"w": "谐当", "t": "妥当。"}]}, {"meaning": "商定。", "cites": [{"t": "当之官者,皆先至西园谐价,然后得去。", "b": "《后汉书》"}], "words": [{"w": "谐价", "t": "议价成交。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2463wx','袱','1','fú','衤','11','','[{"pinyin": "fú", "defs": [{"meaning": "妇女的包头巾。", "cites": [{"t": "首取帛为袱,体用衾自裹。", "b": "元·方回文"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2464wx','祷','1','dǎo','礻','11','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从示,寿声。向神求福的一种迷信行为)。"}, {"meaning": "祈祷,祈神求福。", "cites": [{"t": "祷,告事求福也。", "b": "《说文》"}, {"t": "祷,祭也。", "b": "《广雅》"}, {"t": "五曰祷。", "b": "《周礼·大祝》。注:“祷,贺庆言福祚之辞。”"}, {"t": "候禳祷词之祝号。", "b": "《周礼·小祝》。疏:“求福谓之祷,报赛谓之祠。”"}, {"t": "既伯既祷。", "b": "《诗·小雅·吉日》"}, {"t": "子疾病,子路请祷。", "b": "《论语·述而》"}, {"t": "秦襄王病,百姓为之祷;病愈,杀牛塞祷。", "b": "《韩非子·外储说右下》"}, {"t": "以身祷于桑林之际。", "b": "《淮南子·主术》"}], "words": [{"w": "祷巫", "t": "犹言巫祝祈祷"}, {"w": "祷祀", "t": "有事祷求鬼神而致祭"}, {"w": "祷雨", "t": "祈神降雨"}, {"w": "祷祈", "t": "祈祷"}, {"w": "祷牲", "t": "祈祷时所用的祭牲。"}]}, {"meaning": "盼望——书信中用作敬词,表示期望和请求。", "cites": [{"t": "君臣不同道,下以名祷。", "b": "《韩非子·扬权》"}], "words": [{"w": "切祷;是所至祷;祷切", "t": "书信客套用语,表示祈求急切"}, {"w": "祷盼", "t": "书信客套用语,表示祈求、盼望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2465wx','祸','1','huò','礻','11','','[{"pinyin": "huò", "defs": [{"meaning": "(形声。从示,楇(kuā)声。本义:灾祸,祸患)。"}, {"meaning": "同本义。", "cites": [{"t": "禍,害也。神不福也。", "b": "《说文》"}, {"t": "禍灾杀礼。", "b": "《周礼·掌客》"}, {"t": "禍兮福所倚。", "b": "《史记·屈原贾生列传》"}, {"t": "逆其类者谓之禍。", "b": "《荀子·天论》"}, {"t": "来不由我,古谓之祸。", "b": "《论衡·累害》"}, {"t": "鱼无失水之祸。", "b": "《韩非子·大体》"}, {"t": "不顾国政,则亡国之祸也。", "b": "《韩非子·十过》"}, {"t": "近者祸及身。", "b": "《战国策·赵策》"}, {"t": "不能为祸。", "b": "《淮南子·人间训》"}, {"t": "祸且及汝。", "b": "明·魏禧《大铁椎传》"}, {"t": "祸至无日。", "b": "《资治通鉴》"}, {"t": "文人画士之祸。", "b": "清·龚自珍《病梅馆记》"}, {"t": "祸及枯骨。", "b": "《广东军务记》"}], "words": [{"w": "祸基", "t": "灾祸根由"}, {"w": "祸不旋踵", "t": "比喻祸害来势迅猛,连脚后跟都来不及掉转"}, {"w": "祸至无日", "t": "比喻祸患的急迫"}, {"w": "祸中有福", "t": "不幸中有幸。"}]}, {"meaning": "罪。", "cites": [{"t": "罪祸有律。", "b": "《荀子·成相》。注:“祸,亦罪也。”"}]}, {"meaning": "灾荒之处。", "cites": [{"t": "有祸则反。", "b": "《太玄经·玄文》"}]}, {"meaning": "作祸;加害。", "cites": [{"t": "子木有祸人之心,武有仁人之心。", "b": "《左传·昭公元年》"}], "words": [{"w": "祸国", "t": "加害于国"}, {"w": "祸国殃民;祸世", "t": "危害社会"}, {"w": "祸计", "t": "恶计"}, {"w": "祸人", "t": "害人。"}]}, {"meaning": "遭难;受害。", "cites": [{"t": "刘恭见赤眉众乱,知其必败,自恐兄弟俱祸。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2466wx','谓','1','wèi','讠','11','','[{"pinyin": "wèi", "defs": [{"meaning": "(形声。从言,胃声。本义:告诉)。"}, {"meaning": "同本义。", "cites": [{"t": "谓,报也。", "b": "《说文》"}, {"t": "人以谓霍氏。", "b": "《汉书·霍光传》。注:“告语也。”"}, {"t": "太后明谓左右。", "b": "《战国策·赵策》"}, {"t": "谓安陵君曰。", "b": "《战国策·魏策》"}, {"t": "谓唐雎曰。", "b": ""}, {"t": "谓岛曰。", "b": "宋·胡仔《苕溪渔隐丛话》"}]}, {"meaning": "说。", "cites": [{"t": "谓,说也。", "b": "《广雅·释诂二》"}, {"t": "世溷浊莫吾知,人心不可谓兮。", "b": "《楚辞·九章·怀沙》"}, {"t": "请往谓项伯,言沛公不敢背项王也。", "b": "《史记·项羽本纪》"}, {"t": "不可谓智。", "b": "《墨子·公输》"}, {"t": "不可谓仁。", "b": ""}, {"t": "不可谓忠。", "b": ""}, {"t": "不可谓知类。", "b": ""}, {"t": "谓天盖高,不敢不局。", "b": "《诗·小雅》"}]}, {"meaning": "评论。", "cites": [{"t": "子谓子贱:“君子哉若人!”", "b": "《论语》"}]}, {"meaning": "称为。", "cites": [{"t": "谓之文也。", "b": "《论语》"}, {"t": "谓为三横。", "b": "《世说新语·自新》"}, {"t": "谓之天门。", "b": "清·姚鼐《登泰山记》"}, {"t": "皆谓之天门。", "b": ""}], "words": [{"w": "何谓", "t": "什么叫做"}, {"w": "称谓", "t": ""}]}, {"meaning": "认为,以为。", "cites": [{"t": "谓为信然。", "b": "《三国志·诸葛亮传》"}, {"t": "皆谓已死。", "b": "《世说新语·自新》"}, {"t": "太守谓谁。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "予谓菊。", "b": "宋·周敦颐《爱莲说》"}]}, {"meaning": "意料。", "cites": [{"t": "不谓严挺之乃有此儿也。", "b": "《唐语林》"}]}, {"meaning": "援助。", "cites": [{"t": "故节于身,谓于民。", "b": "《晏子春秋》"}]}, {"meaning": "", "cites": [{"t": "醉而不出,是谓伐德。", "b": "《诗·小雅·宾之初筵》"}]}, {"meaning": "因为。", "cites": [{"t": "亦不以众人之观易其情貌,亦不谓众人之不观不易其情貌。", "b": "《列子》"}, {"t": "啬之谓术也生于道理。", "b": "《韩非子·解老》"}, {"t": "有一人不得其所,则谓之不乐。", "b": "《盐铁论·忧边》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2467wx','谚','1','yàn','讠','11','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从言,彦声。本义:谚语) 同本义。", "cites": [{"t": "谚,传言也。字亦作喭。", "b": "《说文》"}, {"t": "故谚有之曰。", "b": "《礼记·大学》"}, {"t": "谵有之曰。", "b": "《国语·越语》。注:“谚俗之善谣也。”"}, {"t": "谚所谓“辅车相依,唇亡齿寒”者,其虞、虢之谓也。", "b": "《左传》"}, {"t": "谚曰。", "b": "《史记·货殖列传》"}], "words": [{"w": "农谚;谚言", "t": "俗语、直语、直接明说的俗话"}, {"w": "“无知便是福”是个古谚", "t": ""}]}, {"meaning": "慰问死者家属。", "cites": [{"t": "谚者,直语也。丧言亦不及文,故吊亦称谚。", "b": "《文心雕龙·书记》"}]}, {"meaning": "粗野不恭。", "cites": [{"t": "乃逸乃谚,既诞。", "b": "《书·无逸》"}], "words": [{"w": "谚号", "t": "以鄙俗的称呼加于人或物"}, {"w": "谚诞", "t": "鄙俗诞妄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2468wx','谜','1','mí mèi','讠','11','','[{"pinyin": "mí", "defs": [{"meaning": "(会意兼形声。从言,迷声。本义:谜语)。"}, {"meaning": "同本义。", "cites": [{"t": "谜,隐言也。", "b": "《广韵》。按,谜是后起字"}]}, {"meaning": "而君子嘲隐,化为谜语。", "cites": [{"t": "谜也者,回互其辞,使昏迷也。", "b": "《文心雕龙·谐隐》"}], "words": [{"w": "猜谜;谜语;灯谜", "t": "贴在灯上的谜语。"}]}]}, {"pinyin": "mèi", "defs": [{"meaning": "猜谜儿", "words": [{"w": "谜儿", "t": "[口语]谜语"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2469wx','逮','1','dài dǎi','辶','11','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从辵(chuò),隶(dài)声。本义:赶上;及;到)。"}, {"meaning": "同本义。", "cites": [{"t": "逮,唐逮及也。", "b": "《说文》。按,逮者,行相及也。古曰唐逮。"}, {"t": "逮于袁娄而与之盟。", "b": "《公羊传·成公二年》"}, {"t": "群后之逮在下。", "b": "《书·吕刑》"}, {"t": "逮事父母。", "b": "《礼记·曲礼》"}, {"t": "上不及尧、舜,下不逮周、孔,亦一时之懿士。", "b": "《世说新语·排调》"}, {"t": "纵轻体以迅赴,景追形而不逮。", "b": "曹植《七启》"}, {"t": "政逮于大夫四世矣。", "b": "《论语·季氏》"}, {"t": "敌出不意,大惊扰,以枪上刺刀相搏击,而便捷猛鸷终弗逮。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "逮及", "t": "达到,到了某种程度"}, {"w": "逮夜", "t": "到了晚上"}, {"w": "逮至", "t": "及至;等到。"}]}, {"meaning": "逮捕,抓人(人在捉拿称“逮”,人逃亡而追拿称“捕”)。", "cites": [{"t": "以罪过连逮。", "b": "《史记·始皇纪》"}, {"t": "逮治党与。", "b": "《汉书·王莽传》。注:“捕也。”"}, {"t": "使者遂逮守,胁服,夺其官。", "b": "明·高启《博鸡者事》"}, {"t": "五人者,盖当蓼州周公之被逮,激于义而死焉者也。", "b": "张溥《五人墓碑记》"}, {"t": "被逮之前一日。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "逮系", "t": "拘捕囚禁"}, {"w": "逮坐", "t": "逮捕问罪"}, {"w": "逮狱", "t": "逮捕入狱。"}]}]}, {"pinyin": "dǎi", "defs": [{"meaning": "捉,特指经过追赶或试图抓住", "words": [{"w": "逮蚊子", "t": ""}, {"w": "逮特务", "t": ""}, {"w": "猫逮老鼠", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2470wx','敢','1','gǎn','攵','11','','[{"pinyin": "gǎn", "defs": [{"meaning": "(会意。本义:勇敢,有胆量) 同本义。", "cites": [{"t": "敢,进取也。", "b": "《说文》"}, {"t": "敢,勇也。", "b": "《广雅》"}, {"t": "信理遂惔谓之敢。", "b": "《贾子道术》"}, {"t": "洁廉而果敢者也。", "b": "《大戴礼记·文王官人》。注:“不忧不惧也。”"}, {"t": "天下有中敢直其身。", "b": "《荀子·性恶》"}, {"t": "刚毅勇敢不以伤人。", "b": "《荀子·非十二子》"}, {"t": "九国之师,逡巡而不敢进。", "b": "贾谊《过秦论》"}, {"t": "袭与凌统俱为前部,各将敢死百人。", "b": "《三国志·董袭传》"}, {"t": "于是平原君从之,得敢死之士三千人。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "敢毅", "t": "勇敢刚毅"}, {"w": "敢士", "t": "勇士"}, {"w": "敢直", "t": "果敢正直"}, {"w": "敢勇", "t": "果敢英勇"}, {"w": "敢断", "t": "果敢决断。"}]}, {"meaning": "有胆量做某种事情。", "cites": [{"t": "乡之行劫缚者,侧目莫敢过其门。", "b": "唐·柳宗元《童区寄传》"}, {"t": "寡人帅不腆吴国之役,遵汶之上,不敢左右,唯好之故。", "b": "《国语·吴语》"}, {"t": "人不敢与忤视。", "b": "《战国策·燕策》"}, {"t": "人人自以为必死,然畏愬,莫敢违。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "敢说;敢想;敢干;敢士", "t": "敢死之士"}, {"w": "敢勇当先", "t": "勇于承担责任。"}]}, {"meaning": "谦词,自言冒昧。", "cites": [{"t": "寡君闻吾子将步师出于敝邑,敢犒从者。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "敢言;敢请;我敢预言;敢问", "t": "请问;相问。"}]}, {"meaning": "岂敢;哪敢。", "cites": [{"t": "奉事循公姥,进止敢自专?", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "感荷君子德,恍若乘朽栈。", "b": "韩愈《赠张籍》"}, {"t": "先生之恩,生死而肉骨也,敢不努力以效龟蛇之诚。", "b": "明·马中锡《中山狼传》"}]}, {"meaning": "大约。", "cites": [{"t": "你子母二位敢未打火?", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2471wx','尉','1','wèi yù','寸','11','','[{"pinyin": "wèi", "defs": [{"meaning": "(会意。“尉”是“熨”的古字。表示用火熨烫缯布使之平展。本义:烫平衣服的火斗,熨斗)。"}, {"meaning": "同本义。", "cites": [{"t": "尉,从上按下也。…持火以尉申缯也。", "b": "《说文》"}, {"t": "火斗曰熨。", "b": "《通俗文》"}], "words": [{"w": "尉斗", "t": "藉热力烫平衣服的火斗。"}]}, {"meaning": "中国古代官名 。掌管军事。春秋时晋国上中下三军均设尉。", "cites": [{"t": "八月官尉。", "b": "《淮南子·时则》"}, {"t": "将归死于尉氏。", "b": "《左传·襄公二十一年》"}, {"t": "忿恚尉。", "b": "《史记·陈涉世家》"}, {"t": "尉笞广。", "b": ""}, {"t": "尉挺剑。", "b": ""}, {"t": "夺而杀尉。", "b": ""}], "words": [{"w": "尉侯", "t": "古代守边的都尉与伺敌的斥侯"}, {"w": "尉律", "t": "汉律令为廷尉所掌管,故称“尉律”"}, {"w": "尉廨", "t": "县尉的官署"}, {"w": "尉史", "t": "汉代郡尉之属官。"}]}, {"meaning": "军衔名 。在士之上,校之下。分上尉、中尉、少尉。"}, {"meaning": "官名。县官的副职。", "cites": [{"t": "赴饶之德兴尉。", "b": "宋·苏轼《石钟山记》"}, {"t": "丞尉闻之。", "b": "清·周容《芋老人传》"}, {"t": "陈明选代为尉。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "新尉陈明选。", "b": ""}]}, {"meaning": "“慰”的本字。安慰。", "cites": [{"t": "所过并使劳尉。", "b": "《后汉书·王丹传》"}, {"t": "所以尉荐走卒。", "b": "《汉书·胡建传》"}], "words": [{"w": "尉安", "t": "安抚"}, {"w": "尉承", "t": "安尉侍奉"}, {"w": "尉悦", "t": "欣慰"}, {"w": "慰纳", "t": "安抚结纳"}, {"w": "尉劳", "t": "慰劳"}, {"w": "尉解", "t": "安慰宽解"}, {"w": "尉荐", "t": "慰藉"}, {"w": "尉藉", "t": "慰劳,抚慰。"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "", "cites": [{"t": "尉,姓。古有尉缭子著书。", "b": "《广韵》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2472wx','屠','1','tú','尸','11','','[{"pinyin": "tú", "defs": [{"meaning": "(形声。从尸,者声。“尸”,祭祀时代表死者受祭的活人,与人有关。本义:宰杀牲畜)。"}, {"meaning": "同本义。", "cites": [{"t": "屠,刳也。", "b": "《说文》"}, {"t": "屠,刳剥畜牲也。", "b": "《六书故》"}, {"t": "舞阳侯樊哙者,沛人也,以屠狗为事。", "b": "《史记·樊哙列传》"}, {"t": "进自屠羊。", "b": "《后汉书·何进传》"}, {"t": "屠者朱亥。", "b": "《史记·魏公子列传》"}, {"t": "鼓刀屠者。", "b": ""}], "words": [{"w": "屠沽", "t": "杀猪卖酒"}, {"w": "屠狗", "t": "杀狗;称操贱业的人"}, {"w": "屠杀", "t": "屠宰杀戮"}, {"w": "屠肆", "t": "肉铺,宰杀牲畜的地方"}, {"w": "屠工", "t": "屠子,屠夫。以宰杀牲畜为职业的人"}, {"w": "屠牛", "t": "以宰牛为职业的人。"}]}, {"meaning": "大屠杀,残杀。", "cites": [{"t": "何勤子屠母。", "b": "《楚辞·天问》。注:“裂剥也。”"}, {"t": "今屠沛。", "b": "《汉书·高帝纪》。注:“谓破取城邑,诛杀其人,如屠六畜然。”"}], "words": [{"w": "屠灭", "t": "残杀灭绝"}, {"w": "屠烂", "t": "杀戳碎烂"}, {"w": "屠剔", "t": "杀戮"}, {"w": "屠尽", "t": "杀尽;摧毁"}, {"w": "屠剿", "t": "诛杀剿灭"}, {"w": "屠绝", "t": "灭绝"}, {"w": "屠人", "t": "杀人"}, {"w": "屠噬", "t": "残杀吞并"}, {"w": "屠刘", "t": "屠杀"}, {"w": "屠溃", "t": "因畏诛杀而溃逃"}, {"w": "屠馘", "t": "屠杀"}, {"w": "屠破", "t": "屠杀破坏"}, {"w": "屠毒", "t": "杀害;毒害。"}]}, {"meaning": "分裂。", "cites": [{"t": "屠裂天下。", "b": "《后汉书·仲长统传》"}, {"t": "国孤国屠。", "b": "《逸周书》"}]}, {"meaning": "以宰杀牲畜为职业的人。", "cites": [{"t": "一屠晚归,担中肉尽,止有剩骨。", "b": "《聊斋志异·狼》"}], "words": [{"w": "屠沽小辈", "t": "屠夫和卖酒者一类的小人物"}, {"w": "屠钓", "t": "屠夫与钓者"}, {"w": "屠贩", "t": "屠夫与商贩"}, {"w": "屠沽", "t": "屠夫与卖酒的人"}, {"w": "屠牧", "t": "屠夫和牧人"}, {"w": "屠儿", "t": "对屠户的蔑称。"}]}, {"meaning": "古地名 。在今陕西省长安县东南。", "cites": [{"t": "韩侯出祖,出宿于屠。", "b": "《诗·大雅·韩奕》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2473wx','弹','1','dàn tán','弓','11','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从弓,单声。本义:弹丸)。"}, {"meaning": "同本义。", "cites": [{"t": "弹,行丸也。", "b": "《说文》"}, {"t": "长安大道边,挟弹谁家儿?", "b": "唐·苏涣《变律》其三"}], "words": [{"w": "枪弹;弹子涡", "t": "卵石"}, {"w": "枪林弹雨", "t": "形容战斗激烈"}, {"w": "弹丸黑子", "t": "形容地域狭小。"}]}, {"meaning": "形状像弹丸的东西,如圆形的果实;禽鸟的卵等。", "cites": [{"t": "其法乃以凫弹数十,黄、白各聚一器。", "b": "宋·周密《齐东野语》"}]}, {"meaning": "弹弓。", "cites": [{"t": "援弹飞丸,应弦而落。", "b": "《魏书》"}]}]}, {"pinyin": "tán", "defs": [{"meaning": "(形声。从弓,单声。本义:用弹弓发射弹丸)。"}, {"meaning": "同本义。", "cites": [{"t": "弹,行丸也。", "b": "《说文》"}, {"t": "[灵公]从台上弹人,而观其辟丸也。", "b": "《左传》"}], "words": [{"w": "弹力", "t": "弹射的力量"}, {"w": "弹丸", "t": "供弹弓发射用的泥丸、石丸、铁丸。也指子弹弹头"}, {"w": "弹射", "t": "利用弹力、压力等射出"}, {"w": "弹金", "t": "发射弹丸。"}]}, {"meaning": "弹击。", "cites": [{"t": "新沐者必弹冠。", "b": "《楚辞·渔父》"}, {"t": "倚柱弹其剑。", "b": "《战国策·齐策四》"}, {"t": "复弹其铗。", "b": ""}, {"t": "复弹其剑铗。", "b": ""}, {"t": "善弹琵琶。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "弹唱", "t": "一边弹奏,一边演唱"}, {"w": "弹冠", "t": "弹去冠上的灰尘"}, {"w": "弹棉花;弹弓", "t": "手工弹花的工具。"}]}, {"meaning": "用手指拨动而演奏。", "cites": [{"t": "弹琴看文君,春风吹鬓影。", "b": "李贺《咏怀》"}], "words": [{"w": "弹琴;弹击", "t": "演奏乐器"}, {"w": "弹弦", "t": "弹丝。弹奏弦乐器"}, {"w": "弹纬", "t": "张弦弹奏。"}]}, {"meaning": "批评,揭发。", "cites": [{"t": "旌善以兴化,弹邪而矫俗。", "b": "《三国志·陶谦传》"}, {"t": "仆常好人讥弹其文。有不善者,应时改定。", "b": "曹植《与杨德祖》"}], "words": [{"w": "抨弹", "t": "抨击"}, {"w": "弹议", "t": "弹劾评议"}, {"w": "弹黜", "t": "弹劾罢黜"}, {"w": "弹文", "t": "弹劾官员过错的奏疏"}, {"w": "弹正", "t": "纠弹;纠正"}, {"w": "弹断", "t": "讥评"}, {"w": "弹激", "t": "激烈率直地予以抨击。"}]}, {"meaning": "针刺。", "cites": [{"t": "弹疽不严,必半复聚。", "b": "《资治通鉴》"}]}, {"meaning": "测定重量。", "cites": [{"t": "拿来天平上弹着。", "b": "元·佚名《陈州粜米》"}], "words": [{"w": "弹算", "t": "掂量估模"}, {"w": "弹斤估两", "t": "形容掂量轻重。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2474wx','隋','1','suī suí','阝','11','','[{"pinyin": "suī", "defs": [{"meaning": "(形声。从肉,隓省声。隓(huī),城墙倒塌,“隋”字从肉,本义同肉有关。(suī)本义:残余的祭品) 同本义。", "cites": [{"t": "隋,裂肉也。", "b": "《说文》。"}, {"t": "赞隋。", "b": "《周礼·小祝》。注:“隋尸之祭也。”"}, {"t": "既祭则藏其隋。", "b": "《周礼·守祧》。注:“尸所祭肺脊黍稷之属。”"}]}]}, {"pinyin": "suí", "defs": [{"meaning": "周代诸侯国名。", "words": [{"w": "隋珍", "t": "隋珠"}, {"w": "隋珠(隋侯之珠)隋珠弹雀(隋侯的明月珠是无价之宝,用它弹麻雀,得不偿失)", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2475wx','堕','1','duò huī','土','11','','[{"pinyin": "duò", "defs": [{"meaning": "(形声。从土,隋声。甲骨文字形,右边是“阜”(象陡坡),左边是倒过来的“人”。会意。表示人从陡坡上掉下。本义:毁坏)。"}, {"meaning": "同本义。", "cites": [{"t": "堕,败城阜曰堕。", "b": "《说文》"}, {"t": "万事堕哉。", "b": "《书·益稷》"}, {"t": "堕名城,杀豪杰,收天下之兵聚之咸阳。", "b": "西汉·贾谊《过秦论》"}, {"t": "周道衰,法度堕。", "b": "《汉书·刑法志》"}, {"t": "敌人纷堕如落叶。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "堕废", "t": "毁坏;衰落"}, {"w": "堕罪", "t": "降罪"}, {"w": "堕地", "t": "落地。指出生"}, {"w": "堕局", "t": "落入骗避"}, {"w": "堕睫", "t": "落泪"}, {"w": "堕坠", "t": "跌落"}, {"w": "飞机堕海", "t": ""}]}, {"meaning": "假借为“惰”。懒散;懈怠。", "cites": [{"t": "臣下堕而不忠,则卑辱困穷。", "b": "《管子·形势》"}, {"t": "动无堕容,口无虚言。", "b": "《淮南子·兵略》"}], "words": [{"w": "堕慢", "t": "懈怠轻慢"}, {"w": "堕夫", "t": "懒汉"}, {"w": "堕民", "t": "惰民"}, {"w": "堕怠", "t": "怠慢;懒惰"}, {"w": "堕倪", "t": "怠惰傲慢"}, {"w": "堕容", "t": "精神不振,有怠惰之色。"}]}]}, {"pinyin": "huī", "defs": [{"meaning": "损毁;败坏。", "cites": [{"t": "堕军实而长寇仇。", "b": "《左传·僖公三十二年》"}, {"t": "不能以游堕事。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "堕圮", "t": "毁坏;倒塌"}, {"w": "堕泥", "t": "毁灭;消失"}, {"w": "堕域", "t": "毁域"}, {"w": "堕突", "t": "毁坏,破坏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2476wx','随','1','suí','阝','11','','[{"pinyin": "suí", "defs": [{"meaning": "(形声。从辵(chuò))。"}, {"meaning": "同本义。", "cites": [{"t": "隨,从也。", "b": "《说文》"}, {"t": "隨无故也。", "b": "《易·杂卦》"}, {"t": "隨山刊木循也。", "b": "《书·禹贡》"}, {"t": "无纵诡隨。", "b": "《诗·大雅·民劳》"}, {"t": "凡庭实隨入。", "b": "《仪礼·聘礼》。注:“不并行也。”"}, {"t": "距隨长武。", "b": "《仪礼·乡射礼记》"}, {"t": "列星随旋。", "b": "《荀子·天论》"}, {"t": "主失其神,虎随其后。", "b": "《韩非子·杨权》"}, {"t": "子行而我随之。", "b": "《韩非子·说林上》"}, {"t": "随风潜入夜,润物细无声。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "太守即遣人随其往,寻向所志,遂迷,不复得路。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "随任", "t": "晚辈跟随做官的长辈在任所生活"}, {"w": "随直", "t": "随班值日"}, {"w": "随班", "t": "跟班值勤"}, {"w": "随扈", "t": "随从"}, {"w": "随身灯", "t": "点在死人脚头的灯"}, {"w": "随坐", "t": "即连坐。受他人牵连而被判罪"}, {"w": "随宦", "t": "跟从父兄做官在外"}, {"w": "随随步口", "t": "步步紧跟"}, {"w": "随起举哀", "t": "随同死者亲眷一起号哭。"}]}, {"meaning": "依顺;依从。", "cites": [{"t": "隨,顺也。", "b": "《广雅》"}, {"t": "今黛玉见了这里许多事情不合家中之式,不得不随的,少不得一一改过来,因而接了茶。", "b": "《红楼梦》"}, {"t": "法和所得奴婢,尽免之,曰:“各随缘去。”", "b": "《北齐书·陆法和传》"}], "words": [{"w": "随善善缘", "t": "佛教指见人行善心欢喜;自己行善结好缘"}, {"w": "随邪", "t": "随斜。顺从邪恶,无主见"}, {"w": "随愿", "t": "如愿;称心"}, {"w": "随时制宜", "t": "作事善于变通,不拘常法"}, {"w": "随缘不变", "t": "佛家语。意指随顺世间环境取舍行止,但有所不为。"}]}, {"meaning": "听任某人自愿去做。", "cites": [{"t": "有志矣,不随以止也。", "b": "王安石《游褒禅山记》"}, {"t": "业精于勤荒于嬉,行成于思毁于随。", "b": "唐·韩愈《进学解》"}], "words": [{"w": "随你的便;去不去随你;随念即到", "t": "指神仙佛祖能随意念之所至,立刻到达某一地。"}]}, {"meaning": "接着,随即。", "cites": [{"t": "客以剑拟王,王头随堕汤中。", "b": "晋·干宝《搜神记》"}, {"t": "有郭四者,凡四杀人,复以矜疑减等,随遇赦。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "随次", "t": "随即;马上"}, {"w": "随宜", "t": "随即。"}]}, {"meaning": "六十四卦之一,震下兑上。", "cites": [{"t": "象曰:泽中有雷,随。", "b": "《易·随》"}]}, {"meaning": "中国周代国名 。姬姓。春秋后期为楚之附庸。地在今湖北随县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2477wx','蛋','1','dàn','虫','11','','[{"pinyin": "dàn", "defs": [{"meaning": "骂人的话 。放在某些名词或形容词的后面,组成代表人的词。如:坏蛋;糊涂蛋。 放在某些动词后面,使那个动作带有贬意。如:捣蛋;滚蛋;完蛋。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2478wx','隅','1','yú','阝','11','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从阜(fù),禺(yú)声。“阜”是土山,有土则可用于建筑,因而从“阜”的字有的与建筑有关。本义:山水弯曲边角处)。"}, {"meaning": "同本义。", "cites": [{"t": "隅,陬也。", "b": "《说文》"}, {"t": "既登览乎隅椒,复临泛乎汪洋。", "b": "明·徐渭《缇芝赋》"}], "words": [{"w": "山隅;隅椒", "t": "山角与山顶"}, {"w": "隅隈", "t": "角落和弯曲之处"}, {"w": "隅陬", "t": "角落。"}]}, {"meaning": "角,角落。", "cites": [{"t": "俟我于城隅。", "b": "《诗·邶风·静女》"}, {"t": "宫隅之制七雉,城隅之制九雉。", "b": "《考工记·匠人》"}, {"t": "抠衣趋隅。", "b": "《礼记·曲礼》"}, {"t": "日出东南隅。", "b": "《乐府诗集·陌上桑》"}, {"t": "采桑城南隅。", "b": ""}, {"t": "停于大室之隅。", "b": "唐·李朝威《柳毅传》"}, {"t": "折过墙隅。", "b": "《聊斋志异·促织》"}], "words": [{"w": "隅头", "t": "墙角;拐角"}, {"w": "城隅", "t": "城的一角"}, {"w": "向隅", "t": "面对着屋子的一个角落。"}]}, {"meaning": "边远的地方。", "cites": [{"t": "咫只雪山路,归飞西海隅。", "b": "杜甫《送蔡希鲁都尉还陇右》"}], "words": [{"w": "隅谷", "t": "神话中日落的地方"}, {"w": "隅镇", "t": "边远小镇"}, {"w": "隅夷", "t": "神话中的日出处"}, {"w": "隅辟", "t": "边境,国境"}, {"w": "隅官", "t": "边地官员。"}]}, {"meaning": "事物的部分或片面。", "cites": [{"t": "举端自理,滞隅则失。", "b": "《后汉书》"}], "words": [{"w": "隅见", "t": "片面的见解"}, {"w": "隅曲", "t": "偏狭之见"}, {"w": "隅积", "t": "部分和总体。"}]}, {"meaning": "边;旁。", "cites": [{"t": "昏将举火,执烛隅坐,错总之法,横子坐所。", "b": "《管子》"}], "words": [{"w": "隅坐", "t": "坐位的侧边"}, {"w": "隅目", "t": "斜眼而视,怒视。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2479wx','隆','1','lóng','阝','11','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从生,降省声。本义:高)。"}, {"meaning": "丰大;高。", "cites": [{"t": "隆,丰大也。", "b": "《说文》"}, {"t": "宛中隆。", "b": "《尔雅·释山》。注:“山中央高。”"}, {"t": "虽隆薛之城。", "b": "《战国策·齐策一》"}, {"t": "隆准而龙颜。", "b": "《史记·高祖纪》"}, {"t": "段干木之隆。", "b": "《吕氏春秋·秋期贤》"}, {"t": "降冲以攻。", "b": "《淮南子·泛论》"}, {"t": "德隆望尊。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "隆穷", "t": "隆起的样子"}, {"w": "隆颓", "t": "高低不平的样子"}, {"w": "隆岳", "t": "高山"}, {"w": "隆恩", "t": "皇帝给予的特大的恩典。"}]}, {"meaning": "国家逢勃发展;隆盛。", "cites": [{"t": "陛下都洛阳,岂欲与周室比隆哉?", "b": "《史记·刘敬叔孙通列传》"}, {"t": "汉室之隆。", "b": "诸葛亮《出师表》"}], "words": [{"w": "兴隆", "t": "兴盛"}, {"w": "隆替", "t": "兴废"}, {"w": "隆替无步", "t": "即好坏各不相关。"}]}, {"meaning": "指程度深。", "cites": [{"t": "隆冬,贫者席地而卧。", "b": "方苞《狱中杂记》"}], "words": [{"w": "隆情厚谊", "t": "情谊深厚"}, {"w": "隆寒", "t": "严寒,酷寒"}, {"w": "隆冬", "t": ""}]}, {"meaning": "升高;增高。", "cites": [{"t": "虽隆薛之城至于天,犹之无益也。", "b": "《战国策》"}], "words": [{"w": "隆平", "t": "升平。"}]}, {"meaning": "尊崇。", "cites": [{"t": "学之经,莫速乎好其人,隆礼次之。", "b": "《荀子》"}], "words": [{"w": "隆礼", "t": "重用;重视"}, {"w": "隆德", "t": "尊德,崇高的品德"}, {"w": "隆贵", "t": "尊贵,显贵。"}]}, {"meaning": "高出;高起。", "cites": [{"t": "圆径八尺,合盖隆起。", "b": "《后汉书·张衡传》"}]}, {"meaning": "使成长。", "cites": [{"t": "臣莽夙夜养育隆就孺子。", "b": "《汉书》"}]}, {"meaning": "使兴盛。", "cites": [{"t": "隆国保家。", "b": "房玄龄《晋书》"}, {"t": "克定天下,以隆王室。", "b": "曹操《褒枣祗令》"}]}, {"meaning": "假借为“降”。下,落。", "cites": [{"t": "天命融隆火。", "b": "《墨子·非攻下》"}, {"t": "云者为雨乎?雨者为云乎?孰隆施是?", "b": "《庄子·天运》"}, {"t": "毋犯天之隆。", "b": "《管子·轻重己》"}]}, {"meaning": "常用于雷声或炮声。", "cites": [{"t": "枪声隆然。", "b": "《清稗类钞·战事类》"}], "words": [{"w": "黄洋界上炮声隆", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2480wx','隐','1','yǐn','阝','11','','[{"pinyin": "yǐn", "defs": [{"meaning": "藏匿;隐蔽。", "cites": [{"t": "隐,蔽也。", "b": "《说文》"}, {"t": "隐,微也。", "b": "《尔雅》"}, {"t": "隐五刃。", "b": "《国语·齐语》。注:“隐藏也。”"}, {"t": "则事可以隐定。", "b": ""}, {"t": "隐忌雍蔽之人。", "b": "《荀子·致仕》。注:“隐,亦蔽也。”"}, {"t": "桓公管仲虽善匿,弗能隐矣。", "b": "《吕氏春秋·重言》。注:“隐,蔽也。”"}, {"t": "则盘纡隐深。", "b": "《文选·嵇康·琴赋》。注:“隐,幽深邃也。”"}, {"t": "昔帝鸿氏有不才子,掩义隐贼,好行凶德。", "b": "《左传·文公十八年》"}, {"t": "故隐居屠间。", "b": "《史记·魏公子列传》"}, {"t": "可以隐形。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "日月隐耀。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "各隐卷底。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "隐占身体", "t": "隐藏、掩护自己真实面目"}, {"w": "隐遁", "t": "隐藏"}, {"w": "隐谋", "t": "隐密计划"}, {"w": "隐秀", "t": "隐藏智慧,不露锋芒或才华"}, {"w": "隐候", "t": "在暗处等待"}, {"w": "隐耀", "t": "隐藏光辉,隐藏身体。比喻才华不外露"}, {"w": "隐身术", "t": "古代方士所隐蔽自己身形而使他人不可见的一种法术"}, {"w": "隐冒", "t": "隐匿冒充"}, {"w": "隐翳", "t": "掩蔽;遮蔽"}, {"w": "隐掩", "t": "遮蔽掩护。"}]}, {"meaning": "隐瞒。", "cites": [{"t": "父为子隐,子为父隐。", "b": "《论语·子路》"}, {"t": "上以无隐。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "隐欺", "t": "隐瞒欺骗"}, {"w": "隐情", "t": "隐瞒情况"}, {"w": "隐拒", "t": "隐瞒抵赖"}, {"w": "隐忍", "t": "忍耐,不露真情。"}]}, {"meaning": "隐测,审度。", "cites": [{"t": "又隐实户口,料出无名万余人,以充军实。", "b": "《晋书·庾冰传》"}], "words": [{"w": "隐心", "t": "审度"}, {"w": "隐实", "t": "查证落实;核实。"}]}, {"meaning": "怜悯。", "cites": [{"t": "隐其无罪。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "隐恤", "t": "哀怜抚恤"}, {"w": "隐恻", "t": "恻隐,同情怜惜"}, {"w": "隐痛", "t": "内心深感苦痛"}, {"w": "隐爱", "t": "恻隐疼爱"}, {"w": "隐愍", "t": "怜悯"}, {"w": "隐亲", "t": "怜悯抚恤。"}]}, {"meaning": "隐逸不出。", "cites": [{"t": "隐者也。", "b": "《论语·微子》"}, {"t": "反国而隐焉。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "隐辟", "t": "隐退回避"}, {"w": "隐静", "t": "避世隐居"}, {"w": "隐学", "t": "隐居避世,读书自娱"}, {"w": "隐吏", "t": "退隐的官吏"}, {"w": "隐相", "t": "深居简出,不露面。"}]}, {"meaning": "塞,堵塞。", "cites": [{"t": "士不隐塞,庶人不数罟。", "b": "《诗·小雅·鱼丽》"}], "words": [{"w": "隐塞", "t": "堵塞。"}]}, {"meaning": "隐没;熄灭。", "cites": [{"t": "隐武事,行文道。", "b": "《国语·齐语》"}, {"t": "隐武行文。", "b": "《春秋繁露·五行变救》"}, {"t": "日斜光隐见,风还影合离。", "b": "南朝·梁简文帝《咏栀子花》"}], "words": [{"w": "隐形", "t": "隐没形体"}, {"w": "隐灭", "t": "隐没消失"}, {"w": "隐微", "t": "隐约细微"}, {"w": "隐显", "t": "隐没与显现"}, {"w": "隐息", "t": "休止"}, {"w": "隐忽", "t": "时隐时现。"}]}, {"meaning": "精深;微妙。", "cites": [{"t": "《春秋》推见至隐,《易》本隐之以显。", "b": "《史记·司马相如列传论》"}, {"t": "《谷梁》简约而隐要,宜存于世。", "b": "《宋书·礼志一》"}], "words": [{"w": "隐要", "t": "精深简要"}, {"w": "隐训", "t": "诡僻的训释"}, {"w": "隐书", "t": "旨意隐秘之书"}, {"w": "隐略", "t": "隐晦粗略"}, {"w": "隐奥", "t": "隐晦深奥。"}]}, {"meaning": "用同“稳”(wěn)。安稳;稳定。", "cites": [{"t": "隐练职位。", "b": "汉《荡阴令张迁表颂》"}, {"t": "即便求隐。", "b": "汉《李翕析里桥輔阁颂》"}], "words": [{"w": "隐坐", "t": "稳坐;安坐。"}]}, {"meaning": "威重的样子,深沉稳重。", "cites": [{"t": "鲜之为人通率,在高祖坐,言无所隐,时人甚惮焉。而隐厚笃实,瞻卹亲故。", "b": "《宋书·郑鲜之传》"}], "words": [{"w": "隐冥", "t": "深沉含蓄"}, {"w": "隐厚", "t": "稳重忠厚"}, {"w": "隐隐桓桓", "t": "威武的样子"}, {"w": "隐重", "t": "威重。"}]}, {"meaning": "殷盛。", "cites": [{"t": "尔乃邑居隐账。", "b": "左思《蜀都赋》"}], "words": [{"w": "隐赈", "t": "富庶繁盛"}, {"w": "隐蔼", "t": "茂盛的样子。"}]}, {"meaning": "矮墙。", "cites": [{"t": "逾隐而待之。", "b": "《左传·襄公二十三年》"}]}, {"meaning": "痛苦;疾苦。", "cites": [{"t": "勤恤民隐而除其害也。", "b": "《国语》"}]}, {"meaning": "隐居的人。", "cites": [{"t": "贪夫殉身,圣亦保之;烈士殉名,隐亦好之。", "b": "王闿运《邹汉勋传》"}], "words": [{"w": "隐佚", "t": "隐逸者。"}]}, {"meaning": "隐语。", "cites": [{"t": "齐威王之时喜隐。", "b": "《史记·滑稽列传》"}]}, {"meaning": "隐衷,隐情。", "cites": [{"t": "孤癖之隐。", "b": "清·龚自珍《病梅馆记》"}]}, {"meaning": "櫽栝,矫正竹木弯曲的工具。", "cites": [{"t": "故遂隐栝。", "b": "何休《公羊经传解诂序》"}, {"t": "夫弃隐栝之法。", "b": "《韩非子·难势》"}, {"t": "训考量隐栝。", "b": "《后汉书·邓训传》"}]}, {"meaning": "暗暗地。", "cites": [{"t": "隐中胸怀。", "b": "《聊斋志异·促织》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2481wx','婚','1','hūn','女','11','','[{"pinyin": "hūn", "defs": [{"meaning": "(形声。从女,昏声。因为古时黄昏迎亲,故“昏”亦兼表字义。本义:妇家)。"}, {"meaning": "妻之家。", "cites": [{"t": "婚,妇家也。礼,娶妇以昏时。妇人阴也,故曰婚。婚,妇家也。", "b": "《说文》。王筠句读:“下文:姻,婿家也。”"}]}, {"meaning": "妻之父。", "cites": [{"t": "妇之父为婚。", "b": "《尔雅》"}, {"t": "妇之父曰婚,言婿亲迎用昏,又恒以昏夜成礼也。", "b": "《释名·释亲属》"}]}, {"meaning": "通婚。婚姻关系。", "cites": [{"t": "约为婚姻。", "b": "《史记·项羽本纪》"}, {"t": "自附为婚姻。", "b": "《史记·魏公子列传》"}, {"t": "便可做婚姻。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "婚友", "t": "有婚姻关系的亲戚和朋友"}, {"w": "婚媾", "t": "婚姻,嫁娶"}, {"w": "婚阀", "t": "婚姻门第。和显贵的人家结为婚姻"}, {"w": "婚会", "t": "婚礼;结婚。"}]}, {"meaning": "男女结为夫妇,结婚。", "cites": [{"t": "婚者,昏时行礼,故曰婚。", "b": "《白虎通·嫁娶》"}, {"t": "娇逸未有婚。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "初婚三四个月。", "b": "清·林觉民《与妻书》"}, {"t": "秦昭王与楚婚。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "婚姤", "t": "结婚"}, {"w": "婚宦", "t": "结婚和仕宦"}, {"w": "婚仪", "t": "结婚的仪式"}, {"w": "婚币", "t": "婚娶的聘礼。"}]}, {"meaning": "特指男子娶妇 。如:完婚;成婚。也指女子出嫁。如:婚田(女子出嫁时,陪嫁的田地)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2482wx','婶','1','shěn','女','11','','[{"pinyin": "shěn", "defs": [{"meaning": "叔母。父亲弟弟的妻子。", "cites": [{"t": "及抱入姆、婶房中。", "b": "吴自牧《育子》"}], "words": [{"w": "婶母", "t": "婶娘;婶婶。都指叔父之妻"}, {"w": "婶太太", "t": "对别人叔母的尊称。"}]}, {"meaning": "兄、嫂称弟之妻。", "cites": [{"t": "兄弟,婶子害什么病?", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2483wx','婉','1','wǎn','女','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从女,宛声。本义:柔顺)。"}, {"meaning": "同本义。", "cites": [{"t": "婉,顺也。", "b": "《说文》"}, {"t": "妇听而婉。", "b": "《左传·昭公二十六年》"}, {"t": "恶而婉。", "b": "《左传·襄公二十六年》。服注:“婉,顺也。”"}], "words": [{"w": "婉软", "t": "柔和的样子"}, {"w": "婉艳", "t": "柔顺华美"}, {"w": "婉嫕", "t": "婉静。温顺娴静"}, {"w": "婉容", "t": "和顺的仪容"}, {"w": "婉悦", "t": "恭顺和悦"}, {"w": "婉弱", "t": "和顺谦恭"}, {"w": "婉柔", "t": "温顺柔弱。"}]}, {"meaning": "柔美。", "cites": [{"t": "婉娈邀恩宠,百态隨所施。", "b": "《金瓶梅》"}], "words": [{"w": "婉娈", "t": "漂亮的娈童"}, {"w": "婉婉深深", "t": "柔美精深"}, {"w": "婉仪", "t": "美好的仪态"}, {"w": "婉美", "t": "美好;柔美"}, {"w": "婉奕", "t": "柔美的样子"}, {"w": "婉好", "t": "美好,美妙"}, {"w": "婉冶", "t": "美丽"}, {"w": "婉慧", "t": "柔美聪慧"}, {"w": "婉婉", "t": "柔美,美好"}, {"w": "婉然", "t": "美好的样子。"}]}, {"meaning": "委婉;曲折。", "cites": [{"t": "经吾婉解。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "婉切", "t": "委婉贴切"}, {"w": "婉折", "t": "婉转曲折"}, {"w": "婉笃", "t": "委婉真挚"}, {"w": "婉缛", "t": "文辞婉转曲折而富文采"}, {"w": "婉词", "t": "婉言。委婉的言辞"}, {"w": "婉晦", "t": "委婉而含蓄"}, {"w": "婉言微词", "t": "委婉而又精妙的语言。"}]}, {"meaning": "简约。", "cites": [{"t": "大而婉,险而易。", "b": "《左传》"}]}, {"meaning": "非常喜欢或喜爱。", "cites": [{"t": "婉彼二人,不忍加罪。", "b": "《文选·阮瑀·为曹公作书与孙权》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2484wx','颇','1','pō','皮','11','','[{"pinyin": "pō", "defs": [{"meaning": "(形声。从页,皮声。页(xié),人头。本义:头偏)。"}, {"meaning": "同本义。", "cites": [{"t": "颇,头偏也。", "b": "《说文》"}]}, {"meaning": "偏,倾斜,不平正。", "cites": [{"t": "循绳墨而不颇。", "b": "《楚辞·离骚》"}, {"t": "天不颇覆,地不偏载。", "b": "《史记·匈奴列传》"}, {"t": "无偏无颇,遵王之义。", "b": "《书·洪范》"}], "words": [{"w": "颇覆", "t": "偏至一侧,只覆盖一部分。喻偏颇不公平;倾覆,倾倒"}, {"w": "颇廻", "t": "偏差不正"}, {"w": "颇侧", "t": "偏侧,不正"}, {"w": "颇缘", "t": "饰有斜纹的边缘。"}]}, {"meaning": "偏邪,不公正。", "cites": [{"t": "君刑已颇,何以为盟主?", "b": "《左传·昭公二年》"}, {"t": "朝廷不颇。", "b": "《荀子·臣道》"}, {"t": "刑之颇纇。", "b": "《左传·昭公十六年》"}, {"t": "书辞无颇。", "b": "《左传·昭公十二年》"}, {"t": "人用侧颇僻。", "b": "《汉书·王嘉传》"}], "words": [{"w": "偏颇", "t": "偏于一方,不公正"}, {"w": "颇子", "t": "歪心邪意;歹心"}, {"w": "颇僻", "t": "偏颇邪僻"}, {"w": "颇偏", "t": "不公平。也作“偏颇”"}, {"w": "颇邪", "t": "偏颇邪恶"}, {"w": "颇说", "t": "邪说"}, {"w": "颇险", "t": "邪恶不正"}, {"w": "颇辞", "t": "不正之辞"}, {"w": "颇类", "t": "偏颇不平"}, {"w": "颇激", "t": "偏激。"}]}, {"meaning": "略微;稍。", "cites": [{"t": "颇通诸子百家之书。", "b": "《史记·贾生列传》"}, {"t": "周以来乃颇可著。", "b": "《史记·三代世表》"}, {"t": "山界颇开。", "b": "《徐霞客游记·滇游日记》"}], "words": [{"w": "颇识几字,颇可", "t": "稍可"}, {"w": "颇有用;颇败", "t": "稍微击败"}, {"w": "颇采", "t": "稍稍采用"}, {"w": "颇脱", "t": "时或,间或"}, {"w": "颇讥", "t": "略有讥刺。"}]}, {"meaning": "很;甚。", "cites": [{"t": "初至北营,抗辞慷慨,上下颇惊动,北亦未敢遽轻吾国。", "b": "宋·文天祥《指南录·后序》"}, {"t": "然小孤之旁,颇有沙洲葭苇。。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "颇颇", "t": "很是;甚是"}, {"w": "颇为出色;颇多;颇少;颇佳;颇甚", "t": "极甚"}, {"w": "颇为得体", "t": "甚为切当。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2485wx','颈','1','gěng jǐng','页','11','','[{"pinyin": "gěng", "defs": [{"meaning": "脖子 ——用于“脖颈儿”。"}]}, {"pinyin": "jǐng", "defs": [{"meaning": "(形声。从刀,巠声。从“页”,表示与头有关。本义:颈项)。"}, {"meaning": "同本义。", "cites": [{"t": "颈,头茎也。", "b": "《说文》"}, {"t": "小人莫不延颈举踵而愿曰。", "b": "《荀子·荣辱》"}, {"t": "譬之是犹欲寿而歾颈也。", "b": "《荀子·彊国》"}, {"t": "喜则交颈相靡。", "b": "《庄子·马蹄》"}, {"t": "折颈而死。", "b": "《韩非子·五蠹》"}, {"t": "颈血溅大王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "伸颈,侧目。", "b": "《虞初新志·秋声诗自序》"}, {"t": "抚其颈曰。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "颈血", "t": "刎颈时流出的血。比喻不惜一死。"}]}, {"meaning": "脖子的前面部分。", "cites": [{"t": "颈在前,项在后。", "b": "《广韵》"}]}, {"meaning": "一星名。", "cites": [{"t": "七星;颈,为员官,主急事。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2486wx','绩','1','jì','纟','11','','[{"pinyin": "jì", "defs": [{"meaning": "把麻纤维披开接续起来搓成线。", "cites": [{"t": "绩,缉也。从糸,责声。", "b": "《说文》"}, {"t": "不绩其麻。", "b": "《诗·陈风·东门之枌》"}, {"t": "八月载绩。", "b": "《诗·豳风·七月》。传:“载绩,丝事毕而麻事起矣。”"}, {"t": "公父文伯退朝,朝母。其母方绩。", "b": "《国语·鲁语下》"}], "words": [{"w": "绩绪", "t": "搓麻线"}, {"w": "绩女", "t": "纺织的女郎"}, {"w": "绩火", "t": "夜晚纺织时用来照明的灯火"}, {"w": "绩纺", "t": "泛指纺纱,绩麻诸事。即纺绩。"}]}, {"meaning": "成就;功业。", "cites": [{"t": "绩,功也,又,业也,又,事也,又,成也。字亦作勣。", "b": "《尔雅》"}, {"t": "勣,功也。", "b": "《声类》"}, {"t": "庶绩咸熙。", "b": "《书·尧典》"}, {"t": "远绩禹功。", "b": "《左传·昭公元年》。按,迹也。"}, {"t": "大奔曰败绩。", "b": "《左传·庄公十一年》"}, {"t": "伯尊其无绩乎。", "b": "《谷梁传·成公五年》"}, {"t": "男女效绩。", "b": "《国语·鲁语》"}, {"t": "维禹之绩。", "b": "《诗·大雅·文王有声》"}], "words": [{"w": "绩用", "t": "绩效,功用"}, {"w": "绩迒", "t": "功效,工作的成绩"}, {"w": "绩阀", "t": "功绩。书功状以榜门叫阀"}, {"w": "绩谋", "t": "功勋与智谋。"}]}, {"meaning": "下裳。", "cites": [{"t": "赐皮弁素绩。", "b": "《汉书》。颜师古注:素绩,谓素裳也。朱衣而素裳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2487wx','绪','1','xù','纟','11','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从糸(mì),者声。本义:丝的头)。"}, {"meaning": "同本义。", "cites": [{"t": "绪,丝端也。", "b": "《说文》"}, {"t": "凡茧滚沸时,以竹签拨动水面丝绪。", "b": "《天工开物》"}], "words": [{"w": "绪余", "t": "抽丝后留在蚕茧上的残丝。"}]}, {"meaning": "头绪,开端。", "cites": [{"t": "反覆终始,不知其端绪。", "b": "《淮南子·精神训》"}, {"t": "扰百绪于眼前。", "b": "谢庄《曲池赋》"}], "words": [{"w": "端绪", "t": "头绪"}, {"w": "入绪", "t": "有了头绪"}, {"w": "绪次", "t": "头绪。"}]}, {"meaning": "情绪,心情。", "cites": [{"t": "都门帐饮无绪。", "b": "柳永《雨霖铃》"}, {"t": "幽情苦绪何人见。", "b": "《聊斋志异》"}, {"t": "霜轻两鬓欲相侵,悉绪无端不可寻。", "b": "唐·李频《长安寓居寄柏侍郎》"}], "words": [{"w": "愁绪", "t": "忧愁的情绪"}, {"w": "情绪", "t": "情思意绪。"}]}, {"meaning": "次序。", "cites": [{"t": "诞敢纪其绪。", "b": "《书·大诰》"}]}, {"meaning": "世系。", "cites": [{"t": "系唐统,接汉绪。", "b": "陆游《丞相率文武官僚贺寿皇正旦表》"}], "words": [{"w": "绪胄", "t": "世系和后代。"}]}, {"meaning": "前人遗留下来的未竟的事业。", "cites": [{"t": "缵禹之绪。", "b": "《诗·鲁颂·閟宫》"}, {"t": "荒坠厥绪,覆宗绝祀。", "b": "《书·五子之歌》"}], "words": [{"w": "绪功", "t": "未完成的功业;遗业。"}]}, {"meaning": "姓。明代有绪纪、绪珊。"}, {"meaning": "余留的,遗留下来的。", "cites": [{"t": "唉秋冬之绪风。", "b": "《楚辞·涉江》"}, {"t": "先王有绪言而去。", "b": "《庄子·渔父》"}, {"t": "道之真以治身,其绪余以为国家,其土苴以治天下。", "b": "《庄子》"}], "words": [{"w": "绪风", "t": "残余之风。即“余风”"}, {"w": "绪音", "t": "余音"}, {"w": "绪余", "t": "事物之残余或主体以外所剩余"}, {"w": "绪业", "t": "遗业,事业。"}]}, {"meaning": "寻绎;整理。", "cites": [{"t": "苍为计相时,绪正律历。", "b": "《汉书》"}], "words": [{"w": "绪次", "t": "整理编排"}, {"w": "绪正", "t": "理出头绪,排正序次。"}]}, {"meaning": "叙述。", "cites": [{"t": "会病不起,余与伯成绪其志而为之。", "b": "宋·赵衍《重刊李长吉诗集序》"}]}, {"meaning": "顺;顺从。", "cites": [{"t": "仁君年壮气盛,绪信所嬖。", "b": "《文选》"}], "words": [{"w": "绪信", "t": "依从信赖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2488wx','续','1','xù','纟','11','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从糸(mì),卖(yù)声。本义:连接起来,接上)。"}, {"meaning": "同本义。", "cites": [{"t": "续,联也。", "b": "《说文》"}, {"t": "续,继也。", "b": "《尔雅》"}, {"t": "续衽钩边。", "b": "《礼记·深衣》"}, {"t": "貂不足,狗尾续。", "b": "《晋书·赵王伦传》"}, {"t": "是断手而续以玉也。", "b": "《韩非子·用人》"}, {"t": "一时人急智生,把自己头发拔下一绺,登时把弓弦续好。", "b": "《儒林外史》"}], "words": [{"w": "续弦;续篇;续编", "t": ""}]}, {"meaning": "继续。", "cites": [{"t": "岁时更续。", "b": "《周礼·巾车》"}, {"t": "刑者不可复续。", "b": "《史记·扁仓传》"}, {"t": "亡秦之续。", "b": "《史记·项羽本纪》"}, {"t": "以夜续昼,由是获声誉。", "b": "《三国志》"}, {"t": "续发众人。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "续终", "t": "继续到底"}, {"w": "续续", "t": "相继不绝,连续不断"}, {"w": "持续", "t": "延续不断。"}]}, {"meaning": "继承。", "cites": [{"t": "汝复为太史,则续吾祖矣。", "b": "《史记·太史公自序》"}], "words": [{"w": "续世", "t": "谓世代继承。"}]}, {"meaning": "妻子死后再娶。", "cites": [{"t": "才死了老婆…他在奶奶庙大会上见过小芹一面,愿意续她。", "b": "赵树理《小二黑结婚》"}], "words": [{"w": "续母", "t": "继母"}, {"w": "续弦;续继", "t": "妻死再娶。"}]}, {"meaning": "传递。", "cites": [{"t": "教顺施续,而知能流通,由此观之,学不可已明矣。", "b": "《淮南子·脩务》"}]}, {"meaning": "后同于前,旧事重演。", "cites": [{"t": "谗言繁兴,延及寡君之绍续昆裔。", "b": "《国语》"}], "words": [{"w": "续约", "t": "当一个条约的时效将终,再拟一个条约,作为辅助性条款,用以延续正约的期限或补充正约的不足者,谓之。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2489wx','骑','1','qí','马','11','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从马,奇声。本义:跨马)。"}, {"meaning": "同本义。", "cites": [{"t": "骑,跨马也。", "b": "《说文》"}, {"t": "步骑罗些。", "b": "《楚辞·招魂》"}, {"t": "脱身独骑。", "b": "《史记·项羽本纪》"}, {"t": "其子好骑。", "b": "《淮南子·人间训》"}, {"t": "骑大马。", "b": "明·刘基《卖柑者言》"}, {"t": "骑马挟矢。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "骑射", "t": "骑马射箭"}, {"w": "骑寇", "t": "骑马入侵的贼寇,也是对北方游牧民族的鄙称"}, {"w": "骑猎", "t": "骑马打猎"}, {"w": "骑战", "t": "骑马打仗。"}]}, {"meaning": "跨于物上或两边叫骑,跨坐。", "cites": [{"t": "不骑衡。", "b": "《史记·袁盎传》"}], "words": [{"w": "骑两头马", "t": "比喻两头观望,看风向"}, {"w": "骑鲸", "t": "乘鲸;借指死亡或隐遁"}, {"w": "骑驴觅驴", "t": "是说忘记自己已有又向外追求"}, {"w": "骑鹤上扬州", "t": "比喻妄想、奢望。"}]}, {"meaning": "跨越。", "cites": [{"t": "爽气收回骑月雨,快风散尽满天云。", "b": "宋·陆游《村社祷晴有应》"}]}, {"meaning": "马。", "cites": [{"t": "前有车骑。", "b": "《礼记·曲礼》"}, {"t": "不闻爷娘唤女声,但闻燕山胡骑鸣啾啾。", "b": "《乐府诗集·木兰诗》"}, {"t": "下骑搏战。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "坐骑", "t": "供人骑的马"}, {"w": "车骑", "t": "车和马。"}]}, {"meaning": "骑兵;骑马的人。", "cites": [{"t": "沛公旦日从百余骑来见项王。", "b": "《史记·项羽本纪》"}, {"t": "宦骑与黄门附马。", "b": "《汉书·李广苏建传》"}]}, {"meaning": "又。", "cites": [{"t": "宦骑亡。", "b": ""}, {"t": "骑乃得过。", "b": "《资治通鉴》"}, {"t": "谍报敌骑至。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "骑邑", "t": "骑士的居邑"}, {"w": "轻骑", "t": "轻装的骑兵"}, {"w": "骁骑", "t": "勇猛的骑兵"}, {"w": "骑军", "t": "骑兵部队"}, {"w": "骑操", "t": "骑兵操练。"}]}, {"meaning": "侍从。", "cites": [{"t": "公孙弘断发而为越王骑。", "b": "《韩非子》"}]}, {"meaning": "用于马,相当于“匹”。", "cites": [{"t": "挣下一头牛儿,一骑马儿。", "b": "《醒世恒言》"}]}, {"meaning": "&X（{jì}） 一人一马的合称。", "cites": [{"t": "骑千余。", "b": "《史记·陈涉世家》"}, {"t": "东方千余骑。", "b": "《乐府诗集·陌上桑》"}, {"t": "翩翩两骑来是谁。", "b": "唐·白居易《卖炭翁》诗"}, {"t": "贼二十余骑。", "b": "明·魏禧《大铁椎传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2490wx','绰','1','chāo chuò chuo','纟','11','','[{"pinyin": "chāo", "defs": [{"meaning": "抓取。", "cites": [{"t": "绰枪上马。", "b": "《水浒传》"}], "words": [{"w": "绰起一根棍子", "t": ""}]}]}, {"pinyin": "chuò", "defs": [{"meaning": "(形声。从糸(mì),卓声。本义:宽大,舒缓)。"}, {"meaning": "同本义。", "cites": [{"t": "宽兮绰兮。", "b": "《诗·卫风·淇奥》"}], "words": [{"w": "绰步", "t": "大步"}, {"w": "绰板婆", "t": "大脚婆娘"}, {"w": "绰绰", "t": "宽舒裕如。"}]}, {"meaning": "姿态柔美。", "cites": [{"t": "柔情绰态,媚于语言。", "b": "曹植《洛神赋》"}], "words": [{"w": "绰态", "t": "柔媚多姿"}, {"w": "绰俏", "t": "漂亮;俊俏。"}]}, {"meaning": "端正。", "cites": [{"t": "曾经绰立侍丹墀,绽蕊宫花拂面权。", "b": "唐·元稹《酬孝甫见赠诗》"}], "words": [{"w": "绰立", "t": ""}]}]}, {"pinyin": "chuo", "defs": [{"meaning": "——见“宽绰”(kuānchuo)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2491wx','绳','1','shéng','纟','11','','[{"pinyin": "shéng", "defs": [{"meaning": "(形声。从糸(mì),蝇省声。本义:绳子)。"}, {"meaning": "同本义。", "cites": [{"t": "绳,索也。", "b": "《说文》"}, {"t": "大者谓之索,小者谓之绳。", "b": "《小尔雅》"}, {"t": "巽为绳直。", "b": "《易·说卦》"}, {"t": "作结绳而为网罟。", "b": "《易·系辞传》"}, {"t": "言纶之绳。", "b": "《诗·小雅·采绿》"}, {"t": "民结绳而用之。", "b": "《庄子·胠箧》"}, {"t": "病者困剧…若见鬼把椎锁绳纆,立守其旁。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "绿碧青丝绳。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "绳床", "t": "交床;交椅"}, {"w": "绳缢跌扑", "t": "用绳子吊死,跌倒摔死"}, {"w": "绳文", "t": "文字未创造以前,结绳代替文字,称为绳文"}, {"w": "绳桥", "t": "用绳索连结两岸的桥"}, {"w": "绳头", "t": "绳的一端"}, {"w": "绳戏", "t": "即绳伎。走绳之杂戏"}, {"w": "绳络", "t": "绳编的网状饰物"}, {"w": "绳床瓦灶", "t": "以绳为床,以瓦为灶。比喻生活贫困。"}]}, {"meaning": "墨线。", "cites": [{"t": "其绳则直。", "b": "《诗·大雅·緜》"}, {"t": "孔子曰:“木受绳则直。”", "b": "《孔子家语》"}, {"t": "故木受绳则直。", "b": "《荀子·劝学》"}, {"t": "南江则极清澈,合处如引绳,不相乱。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "绳尺", "t": "指墨线和量尺。皆为匠人所用的工具。"}]}, {"meaning": "准则;法度。", "cites": [{"t": "王道有绳。", "b": "《商君书·开塞》"}, {"t": "故智术能法之士用,则贵重之臣必在绳之外矣。", "b": "《韩非子·孤愤》"}], "words": [{"w": "绳尺", "t": "标准;法度"}, {"w": "绳治", "t": "以法治罪"}, {"w": "绳度", "t": "法度,准绳;悬度。以绳索相牵引而越度"}, {"w": "绳直", "t": "犹准绳"}, {"w": "绳规", "t": "犹法规"}, {"w": "绳律", "t": "规矩格律。"}]}, {"meaning": "水名。"}, {"meaning": "金沙江的古称。"}, {"meaning": "山东省的南阳水、北阳水。"}, {"meaning": "继承,通“承”。", "cites": [{"t": "绳其祖武。", "b": "《诗·大雅·下武》"}], "words": [{"w": "绳法", "t": "继承效法"}, {"w": "绳祖", "t": "继承祖先业迹。"}]}, {"meaning": "衡量。", "cites": [{"t": "未可明诏大号以绳天下之梅也。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "绳尺", "t": "衡量"}, {"w": "绳量", "t": "衡量。"}]}, {"meaning": "纠正。", "cites": [{"t": "故举兵绳之。", "b": "《孙膑兵法》"}], "words": [{"w": "绳愆", "t": "纠正过失"}, {"w": "绳正", "t": "以墨线正曲直。引申为纠正错误"}, {"w": "绳逐", "t": "纠正挑剔别人的过失而加以斥退"}, {"w": "绳愆纠缪", "t": "纠正过失错误"}, {"w": "绳劾", "t": "弹劾;纠正。"}]}, {"meaning": "约束;制裁。", "cites": [{"t": "绳之以法,断之以刑。", "b": "桓宽《盐铁论·大论》"}], "words": [{"w": "绳约", "t": "拘束,限制"}, {"w": "绳之以法", "t": "以法律纠治不法之人。指犯罪者接受法律的制裁"}, {"w": "绳束", "t": "约束;束缚"}, {"w": "绳按", "t": "亦作“绳案”。约束制裁。"}]}, {"meaning": "称赞。", "cites": [{"t": "绳息妫以语楚子。", "b": "《左传·庄公十四年》"}]}, {"meaning": "直的;正的。", "cites": [{"t": "洁白清廉中绳,愈穷愈荣。", "b": "《吕氏春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2492wx','维','1','wéi','纟','11','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从糸(mì),隹(zhuī)声。本义:系物的大绳)。"}, {"meaning": "同本义。", "cites": [{"t": "维,紘也。", "b": "《玉篇》"}, {"t": "维,车盖系也。", "b": "《说文》"}, {"t": "维,系也。", "b": "《广雅》"}, {"t": "斡维焉系。", "b": "《楚辞·天问》"}, {"t": "维王之大常。", "b": "《周礼·节服氏》。注:“维之以缕。”"}, {"t": "居其维首。", "b": "《左传·昭公十年》。疏:“纲也。”"}, {"t": "天柱折,地维绝。", "b": "《淮南子·天文训》"}], "words": [{"w": "维纲", "t": "用以系物和提网的绳。亦指维系、保持。"}]}, {"meaning": "隅,角落。", "cites": [{"t": "维,隅也。", "b": "《广雅》"}, {"t": "东北为报德之维也。", "b": "《淮南子·天文》"}], "words": [{"w": "四维", "t": "四角"}, {"w": "维那", "t": "寺院里地位次于首座的僧职"}, {"w": "维岳降神", "t": "高山降其神灵。"}]}, {"meaning": "关键。", "cites": [{"t": "人君者,摄天地之政,秉四海之维。", "b": "《后汉书·陈蕃传》"}, {"t": "法令为维纲。", "b": "《管子·禁藏》"}], "words": [{"w": "维纲", "t": "纲纪;法度。"}]}, {"meaning": "几何学上指空间独立而互相正交的方位数,通常的空间有三维,平面或曲面有二维,直线或曲线只有一维。"}, {"meaning": "网。", "cites": [{"t": "维,网也。", "b": "《集韵》"}]}, {"meaning": "古地名 。故地在今四川省理县。"}, {"meaning": "拴;系。", "cites": [{"t": "絷之维之,以永今朝。", "b": "《诗·小雅·白驹》"}, {"t": "诸侯维舟。", "b": "《尔雅》。李注:“中央左右相维持者曰维舟。”"}, {"t": "牛马维娄。", "b": "《公羊传·昭公二十五年》。注:“系马曰维。”"}], "words": [{"w": "维舟", "t": "系船靠岸停泊"}, {"w": "维絷", "t": "羁绊束缚,强被挽留"}, {"w": "维娄", "t": "系缚;羁縻"}, {"w": "维梢", "t": "系船停泊"}, {"w": "维楫", "t": "系船之绳和船桨"}, {"w": "维绳", "t": "用绳系缚。比喻加以束缚"}, {"w": "维结", "t": "连结"}, {"w": "维城", "t": "连接城池以藩卫邦国。"}]}, {"meaning": "思考,计度", "cites": [{"t": "维万世之安。", "b": "《史记·秦楚之际月表》"}], "words": [{"w": "维度", "t": "思念;计度。"}]}, {"meaning": "维持;维系。", "cites": [{"t": "四方是维。", "b": "《诗·小雅·节南山》"}], "words": [{"w": "维匡", "t": "扶持匡正"}, {"w": "维挽", "t": "维护,挽救。"}]}, {"meaning": "表示判断,相当于“乃”、“是”、“为”。", "cites": [{"t": "众维鱼矣。", "b": "《诗·小雅·谷风》"}], "words": [{"w": "维听", "t": "是听"}, {"w": "维恭维敬", "t": "毕恭毕敬。形容十分恭敬的样子。"}]}, {"meaning": "由于。", "cites": [{"t": "维子之故。", "b": "《诗·郑风·狡童》"}], "words": [{"w": "维是", "t": "由于是…。"}]}, {"meaning": "相当于“与”。", "cites": [{"t": "贲鼓维镛。", "b": "《诗·大雅·灵台》"}, {"t": "与百官之政事师尹,维旅牧相,宣序民事。", "b": "《国语》"}]}, {"meaning": "独。", "cites": [{"t": "维予与女。", "b": "《诗·小雅·谷风》"}], "words": [{"w": "维能", "t": "唯独能够。"}]}, {"meaning": "用于句首,无义。", "cites": [{"t": "维以不永伤。", "b": "《诗·周南·卷耳》"}, {"t": "维昔黄帝,法天则天。", "b": "《史记·太史公自序》"}]}, {"meaning": "用于句中,帮助判断。", "cites": [{"t": "我马维驹。", "b": "《诗·小雅·皇皇者华》"}, {"t": "我马维骐》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2493wx','绵','1','mián','纟','11','','[{"pinyin": "mián", "defs": [{"meaning": "(会意。从帛,从糸(mì)。本义:丝棉,精丝绵,新丝绵)。"}, {"meaning": "同义。", "cites": [{"t": "绛缇絓紬丝絮绵。", "b": "《急就篇》。颜注:“渍茧擘之,精者为绵,粗者为絮。今则谓新者为绵,故者为絮。”"}, {"t": "身衣布衣,木緜皁帐。", "b": "《资治通鉴》"}, {"t": "吴绵软如云。", "b": "白居易《新制布裘》"}], "words": [{"w": "绵子", "t": "丝绵"}, {"w": "绵衣", "t": "内装丝绵的衣服"}, {"w": "绵帛", "t": "丝绵绢帛的总称"}, {"w": "绵矩", "t": "加工丝绵的工具。"}]}, {"meaning": "丝絮状物。", "cites": [{"t": "想见东郊携手日,海棠如雪柳飞绵。", "b": "陆游《醉中怀眉山旧游》"}, {"t": "隋堤上,曾见几番,拂水飘绵送行色。", "b": "周邦彦《兰陵王》"}]}, {"meaning": "姓。春秋齐有绵驹。"}, {"meaning": "接连不断。", "cites": [{"t": "绵绵瓜瓞,民之初生。", "b": "《诗·大雅·绵》"}, {"t": "緜,连也。", "b": "《广雅·释诰四》"}, {"t": "郑绵络些。", "b": "《楚辞·招魂》"}, {"t": "緜日月而不衰。", "b": "《文选·张衡·思玄赋》"}, {"t": "绵地千里。", "b": "《后汉书·西羌传》"}], "words": [{"w": "绵连", "t": "连续不绝"}, {"w": "绵络", "t": "连续不绝"}, {"w": "绵联", "t": "连绵不绝的样子"}, {"w": "绵长", "t": "延续久远。"}]}, {"meaning": "久远。", "cites": [{"t": "微睇緜藐。", "b": "司马相如《上林赋》。注:“远视貌。”"}, {"t": "鸟屿緜邈。", "b": "左思《吴都赋》。注:“广远貌。”"}], "words": [{"w": "绵暧", "t": "久远,悠远"}, {"w": "绵眇", "t": "遥远、悠远、远视的样子"}, {"w": "绵野", "t": "遥远的郊野。"}]}, {"meaning": "薄弱;软弱。", "cites": [{"t": "越人绵力薄材,不能陆战。", "b": "《汉书·严助传》"}], "words": [{"w": "绵弱", "t": "柔弱,薄弱"}, {"w": "绵幂", "t": "微细"}, {"w": "绵劣", "t": "才能薄弱,智力低下"}, {"w": "绵力", "t": "谦词,能力薄弱。"}]}, {"meaning": "病重。", "cites": [{"t": "不图所患,遂尔绵笃。", "b": "《晋书·陶侃传》"}], "words": [{"w": "绵笃", "t": "病危,病势沉重"}, {"w": "绵惙", "t": "病势垂危。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2494wx','绷','1','bēng běng bèng','纟','11','','[{"pinyin": "bēng", "defs": [{"meaning": "(形声。从糸(mì),朋声。本义:束缚,捆绑)。"}, {"meaning": "缠束;包扎。", "cites": [{"t": "繃,束也。", "b": "《说文》"}, {"t": "禹葬会稽,桐棺三寸,葛以繃之。", "b": "《墨子·节葬篇》"}, {"t": "襁,即今儿小儿繃也。今俗犹云繃小儿矣。", "b": "《汉书·宣帝纪》注"}], "words": [{"w": "绷吊拷讯", "t": "捆绑并吊起来拷问"}, {"w": "绷爬吊拷,绷巴吊拷,绷扒吊拷", "t": "强行脱衣服,捆好吊起来拷打。"}]}]}, {"pinyin": "běng", "defs": []}, {"pinyin": "bèng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2495wx','绸','1','chóu','纟','11','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从糸,周声。本义:缠绕)。"}, {"meaning": "同本义。", "cites": [{"t": "绸,缪也。", "b": "《说文》"}, {"t": "绸,缠也。", "b": "《广雅》"}, {"t": "绸缪束薪,三星在天。", "b": "《诗·唐风·绸缪》。毛传:“绸缪犹缠绵也。”"}]}, {"meaning": "捆缚。", "cites": [{"t": "薜荔柏兮蕙绸,荃桡兮兰旌。", "b": "屈原《九歌》。王逸注:“绸,束缚也。”"}]}, {"meaning": "致密;稠密。", "cites": [{"t": "彼君子女,绸直如发。", "b": "《诗·小雅·都人士》。"}], "words": [{"w": "绸直", "t": "情情慎密,操行正直"}, {"w": "绸沓", "t": "密集。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2496wx','综','1','zèng zōng','纟','11','','[{"pinyin": "zèng", "defs": [{"meaning": "织布机上使经线上下交错以受纬线的一种装置。", "cites": [{"t": "推而往,引而来者,综也。", "b": "《古列女传》"}]}]}, {"pinyin": "zōng", "defs": [{"meaning": "(形声。从糸(mì),宗声(zòng)。 ①本义:织布机上使经线上下交错以受纬线的一种装置 ②编织。聚总,集合)。"}, {"meaning": "总聚;总合。", "cites": [{"t": "错综其数。", "b": "《易·系辞》。孔颖达疏:“错谓交错,综谓总聚。”"}, {"t": "网罗天下放失旧闻,略考其行事,综其终始。", "b": "司马迁《报任少卿书》"}], "words": [{"w": "综理", "t": "综合处理事务;总管"}, {"w": "综析", "t": "综合与分析"}, {"w": "综校", "t": "综合校理"}, {"w": "综核", "t": "综合起来而加以考核。"}]}, {"meaning": "治理。", "cites": [{"t": "由地曹郎综吏部。", "b": "《唐故朝仪郎神道碑》"}], "words": [{"w": "综典", "t": "总管,总揽"}, {"w": "综理", "t": "掌管一切,总合处理"}, {"w": "综事", "t": "综理事务"}, {"w": "综治", "t": "全面治理。"}]}, {"meaning": "归纳。", "cites": [{"t": "正流俗之华说,综孔氏之旧章。", "b": "《七启》"}]}, {"meaning": "精通。", "cites": [{"t": "当今好之者寡,故世虽多通才达学而未能综于此耳。", "b": "《新唐书》"}], "words": [{"w": "综练", "t": "广泛研习,样样精通。"}]}, {"meaning": "起皱纹。", "cites": [{"t": "车板上有些血条子,被阳光晒得综起来,发着腥臭。", "b": "老舍《四世同堂》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2497wx','绽','1','zhàn','纟','11','','[{"pinyin": "zhàn", "defs": [{"meaning": "(形声。从糸(mì),定声。糸,细丝。本义:衣服裂开)。"}, {"meaning": "同本义 。俗称“开线”。", "cites": [{"t": "衣裳绽裂。", "b": "《礼记·内则》"}], "words": [{"w": "绽破", "t": "衣缝裂开"}, {"w": "将绽", "t": "衣缝快要裂开。"}]}, {"meaning": "饱满、开裂。特指花果。", "cites": [{"t": "春色方盈野,枝枝绽翠英。", "b": "北周·庾信《杏花》"}], "words": [{"w": "绽花", "t": "花苞绽放"}, {"w": "绽蕊", "t": "开放的花。"}]}, {"meaning": "缝补。", "cites": [{"t": "茅茨覆宫殿,封章绽帷帐。", "b": "唐·杜牧《感怀》"}], "words": [{"w": "绽衣", "t": "缝衣。"}]}, {"meaning": "破费;花费。", "cites": [{"t": "多参白水江湖酒,少绽黄边风月钱。", "b": "明·汤显祖《还魂记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2498wx','绿','1','lù lǜ','纟','11','','[{"pinyin": "lù", "defs": [{"meaning": "一种野菜。", "cites": [{"t": "终朝采绿,不盈一掬。", "b": "《诗·小雅·绿竹猗猗》"}]}, {"meaning": "又用于绿林(绿林山)、绿营(清代汉人地方武装)、鸭绿江等。"}]}, {"pinyin": "lǜ", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,录声。本义:青中带黄的颜色)。", "words": [{"w": "水绿", "t": "浅绿色"}, {"w": "碧绿", "t": "青绿色"}, {"w": "绿耳", "t": "骏马名。为“周穆王”八骏之一。因其毛为绿色,故名"}, {"w": "绿竹", "t": "绿色的竹子"}, {"w": "绿沈", "t": "浓绿色,深绿色。凡弓、枪衣甲及其它器物饰以绿漆或为绿色的都可加上绿沈二字"}, {"w": "绿波", "t": "碧波,澄绿的水波"}, {"w": "绿衫", "t": "“唐”时低层官吏所穿的绿色衣衫。"}]}, {"meaning": "颜色昏暗,乌黑色。", "cites": [{"t": "绿云扰扰。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "绿鬓", "t": "乌黑而光亮的鬓发。引申为青春年少的容颜"}, {"w": "绿媛", "t": "有乌黑头发的美女"}, {"w": "绿云", "t": "女子乌黑光亮的秀发。"}]}, {"meaning": "呈现绿色。", "cites": [{"t": "春风又绿江南岸,明月何时照我还?", "b": "宋·王安石《泊船瓜洲》"}], "words": [{"w": "绿化", "t": "种植花、草、树木,使周围一片碧绿,在城市可以使环境优美卫生,在山区可防止水土流失"}, {"w": "绿浮", "t": "指绿茶泡出的液汁"}, {"w": "绿油", "t": "用油彩饰为绿色"}, {"w": "绿意", "t": "指春天草木葱翠的气象"}, {"w": "绿威威", "t": "形容呈现一片绿色。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2499wx','缀','1','zhuì','纟','11','','[{"pinyin": "zhuì", "defs": [{"meaning": "同本义。", "cites": [{"t": "缀,合箸也。", "b": "《说文》"}, {"t": "缀衣。", "b": "《书·立政》。传:“掌衣服。”"}, {"t": "出缀衣于庭。", "b": "《书·顾命》"}, {"t": "为下国缀旒。", "b": "《诗·大雅·长发》"}, {"t": "缀甲厉兵。", "b": "《战国策·秦策一》"}], "words": [{"w": "缀甲", "t": "缝制甲衣"}, {"w": "缀拾", "t": "采集连缀"}, {"w": "缀纯", "t": "连缀杂彩以为缘边"}, {"w": "缀葺", "t": "修补;缝补"}, {"w": "缀缀", "t": "相连缀的样子。"}]}, {"meaning": "著作。组织文字以成篇章。", "cites": [{"t": "伺其疲倦,即谕之缀诗赋。", "b": "白行简《李娃传》"}, {"t": "李藩侍郎尝缀李贺歌诗,为之集序未成。", "b": "《李长吉歌诗》"}, {"t": "夜书细字缀语言,雨目眵昏头雪白。", "b": "韩愈《短灯檠歌》"}], "words": [{"w": "缀集", "t": "连缀聚集。常指著述,编辑"}, {"w": "缀法", "t": "旧时小学里教导学生作文、造句的方法。连缀已读过的文字,改白话为文言,或改文言为白话,均属缀法之列。"}]}, {"meaning": "装饰。", "cites": [{"t": "饰以文犀,雕以翠绿,缀以骊龙之珠,错以荆山之玉。", "b": "曹植《七启》"}, {"t": "赤缀户也,白缀牖也。", "b": "《大戴礼记》"}], "words": [{"w": "缀映", "t": "点缀映衬"}, {"w": "缀饰", "t": "点缀装饰。"}]}, {"meaning": "连结。", "cites": [{"t": "缀,连也。", "b": "《广雅》"}, {"t": "缀鬼谷于北辰。", "b": "《楚辞·远逝》"}, {"t": "青树翠曼,蒙络摇缀,参差披拂。", "b": "柳宗元《至小丘西小石潭记》"}, {"t": "缀行甚远。(紧随着走了很远。缀,连结,这里是紧跟的意思。)", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "缀恩", "t": "联系亲情"}, {"w": "缀行", "t": "连接成行"}, {"w": "缀连", "t": "组合;连属"}, {"w": "缀接", "t": "联系"}, {"w": "缀组", "t": "系结印绶。"}]}, {"meaning": "物件边缘的装饰。", "cites": [{"t": "纲户朱缀,刻方连些。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2500wx','巢','1','cháo','巛','11','','[{"pinyin": "cháo", "defs": [{"meaning": "(象形。小篆字形,下边是树木,木上是三只鸟和鸟窝。合起来表示鸟栖于树窝上。本义:鸟窝)。"}, {"meaning": "同本义。", "cites": [{"t": "巢,鸟在木上曰巢,在穴曰窠。", "b": "《说文》"}, {"t": "鸟之所乳谓之巢。", "b": "《小尔雅》"}, {"t": "夏则居橧巢。", "b": "《孔子家语·问礼》"}, {"t": "维鹊有巢,维鸠居之。", "b": "《诗·召南·鹊巢》"}]}, {"meaning": "又泛指其他动 物的巢穴。", "cites": [{"t": "长安城南有鼠衔黄蒿、柏叶,上民冢柏及榆树上为巢。", "b": "《汉书·五行志》"}]}, {"meaning": "古人住的巢穴。", "cites": [{"t": "有圣人作,构木为巢以避群害。", "b": "《韩非子·五蠹》"}]}, {"meaning": "筑巢。", "cites": [{"t": "燕雀乌鹊,巢堂坛兮。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "巢幕", "t": "筑巢于帷幕之上。喻处境危险。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2501wx','琴','1','qín','王','12','','[{"pinyin": "qín", "defs": [{"meaning": "(本作“珡”。象形。小篆字形,象乐器形,上面“玨”象弦和弦柱,下面象琴身。本义:拨弦乐器。俗称古琴)。"}, {"meaning": "同本义。", "cites": [{"t": "琴,弦乐也。神农所作,洞越练朱五弦,周加二弦,象形。古文从瑟金省声。", "b": "《说文》"}, {"t": "神农氏琴长三尺六寸六分,上有五弦,曰宫商角徵羽,文王增二弦,曰少宫、少商。", "b": "《广雅·释乐》"}, {"t": "乐琴书以消忧。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "琴史", "t": "琴和史籍"}, {"w": "琴书", "t": "琴与书;谈论琴艺的典籍"}, {"w": "琴床", "t": "琴案;琴几"}, {"w": "琴柱", "t": "琴上用以系弦的柱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2502wx','琳','1','lín','王','12','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从玉,林声。本义:美玉)。"}, {"meaning": "同本义。", "cites": [{"t": "琳,美玉也。", "b": "《说文》"}, {"t": "琳,玉也。", "b": "《尔雅》"}, {"t": "琳珉昆吾。", "b": "《汉书·司马相如传》。注:“玉也。”"}, {"t": "厥贡惟救琳琅玕。", "b": "《书·禹贡》。郑注:“琳,美石也。”"}], "words": [{"w": "琳珉", "t": "美玉名"}, {"w": "琳华", "t": "仙界的花"}, {"w": "琳札", "t": "珍贵的书札"}, {"w": "琳珪", "t": "美玉"}, {"w": "琳球", "t": "指美玉"}, {"w": "琳与", "t": "美玉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2503wx','琢','1','zhuó zuó','王','12','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从玉,豖(chù)声。本义:雕刻加工玉石)。"}, {"meaning": "同本义。", "cites": [{"t": "琢,治玉也。", "b": "《说文》"}, {"t": "雕谓之琢。", "b": "《尔雅》"}, {"t": "玉不琢,不成器。", "b": "《礼记·学记》"}, {"t": "和之璧,井里之厥也。玉人琢之,为天子宝。", "b": "《荀子》"}, {"t": "如琢如磨。", "b": "《诗·卫风·淇奥》。毛传:“玉曰琢,石曰磨。”"}]}, {"meaning": "撰文时的修改加工,琢磨。", "cites": [{"t": "良工存旧笔,老叟琢新诗。", "b": "赵汴《游青城山》"}, {"t": "浅斟杯酒红生颊,细琢歌词稳称声。", "b": "苏轼《和致仕张郎中春书》"}], "words": [{"w": "琢句", "t": "修饰文句"}, {"w": "琢刻", "t": "修饰文辞。"}]}]}, {"pinyin": "zuó", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2504wx','琼','1','qióng','王','12','','[{"pinyin": "qióng", "defs": [{"meaning": "(形声。左形,右声。本义:赤色玉)。"}, {"meaning": "同本义。泛指美玉。", "cites": [{"t": "投我以木瓜,报之以琼琚。", "b": "《诗·卫风·木瓜》"}, {"t": "精琼靡与秋菊兮。", "b": "《汉书·扬雄传》"}, {"t": "楚子玉自为琼弁玉缨。", "b": "《左传·僖公二十八年》"}], "words": [{"w": "琼斝", "t": "一种玉质酒器"}, {"w": "琼窗", "t": "玉砌的窗户。比喻窗户异常华美"}, {"w": "琼琚", "t": "美好的佩玉"}, {"w": "琼珠", "t": "美玉所制的珍珠"}, {"w": "琼音", "t": "玉声。比喻清脆美好的声音。"}]}, {"meaning": "博具,相当于后来的骰子。", "cites": [{"t": "行五道而投琼曰搏,不投琼曰塞。", "b": "成玄英《庄子注疏》"}]}, {"meaning": "比喻雪。", "cites": [{"t": "雪地里踏着碎琼乱玉。", "b": "《水浒传》"}], "words": [{"w": "琼玉", "t": "比喻霜雪"}, {"w": "琼田", "t": "形容晶莹如玉的江湖田野"}, {"w": "琼妃", "t": "喻雪花"}, {"w": "琼玖", "t": "喻冰雪"}, {"w": "琼花", "t": "喻雪花。"}]}, {"meaning": "府名。琼州 。汉置珠崖、儋耳郡;三国吴复置珠崖郡;晋废;唐贞观五年,始置琼州;宋迁治所于今海南省琼山县南;明改置琼州府;清仍之;民国废;今设海南省。"}, {"meaning": "喻事物的美好。", "cites": [{"t": "我欲乘风归去,又恐琼楼玉宇,高处不胜寒。", "b": "苏轼《水调头歌》词"}, {"t": "华酌既陈,有琼浆些。", "b": "《楚辞》"}], "words": [{"w": "琼酥金脍", "t": "指极名贵的食品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2505wx','斑','1','bān','文','12','','[{"pinyin": "bān", "defs": [{"meaning": "(形声。本作“班”,从文,辡(biàn)声。本义:杂色的花纹或斑点)。"}, {"meaning": "同本义。", "cites": [{"t": "辬,驳文也。", "b": "《说文》。徐锴曰:“今作斑也。”"}, {"t": "管中窥豹,时见一斑。", "b": "《晋书·王献之传》"}, {"t": "唯余望乡泪,更染竹成斑。", "b": "宋之问《晚泊湘江》"}], "words": [{"w": "汗斑;斑马;斑污", "t": "斑点污渍"}, {"w": "雀斑;豹子的斑;油斑", "t": ""}]}, {"meaning": "行列;位次。", "cites": [{"t": "登斑叙优。", "b": "汉《竹邑侯相张寿碑》"}, {"t": "于是揖五瑞,斑宗彝。", "b": "魏《孔羡碑》"}]}, {"meaning": "色彩驳杂的;灿烂多彩的。", "cites": [{"t": "斑,驳也,文也。", "b": "《广韵》"}, {"t": "上辬华以交纷。", "b": "张衡《西京赋》"}, {"t": "斑白者不提挈。", "b": "《礼记·王制》"}, {"t": "拉虎摧斑。", "b": "曹植《七启》"}, {"t": "中有小斑纹。", "b": "洪适《歙砚说》"}], "words": [{"w": "斑彪", "t": "色彩斑杂的小老虎"}, {"w": "斑尾", "t": "彩色斑烂的羽尾"}, {"w": "斑剥", "t": "斑驳"}, {"w": "斑阑", "t": "斑兰,斑斓。色彩错杂灿烂。"}]}, {"meaning": "毛色花白的。", "cites": [{"t": "塞上长城空自许,镜中衰鬓已先斑。", "b": "宋·陆游《书愤》"}], "words": [{"w": "斑苍", "t": "花白色"}, {"w": "斑驺", "t": "毛色青白相杂的骏马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2506wx','替','1','tì','曰','12','','[{"pinyin": "tì", "defs": [{"meaning": "(形声。本作“竝”。从竝,白声。竝(bìng),二人并立。本义:废弃)。"}, {"meaning": "同本义。", "cites": [{"t": "竝,废也。", "b": "《说文》。俗字作替。"}, {"t": "不替孟明。", "b": "《左传·僖公三十二年》"}, {"t": "勿替引之。", "b": "《诗·小雅·楚茨》"}, {"t": "胡不自替。", "b": "《诗·大雅·召》"}, {"t": "唯独居思念前世之崇替。", "b": "《国语·楚语》"}, {"t": "謇朝谇而夕替。", "b": "《离骚》"}], "words": [{"w": "久替", "t": "长期废弃。"}]}, {"meaning": "停止。", "cites": [{"t": "荐可而替不。", "b": "《国语·晋语》。注:“去也。”"}], "words": [{"w": "替手", "t": "停手。"}]}, {"meaning": "消亡,泯灭。", "cites": [{"t": "君之冢嗣其替乎。", "b": "《国语·晋语》。注:“灭也。”"}], "words": [{"w": "替罪", "t": "诛灭有罪者。"}]}, {"meaning": "衰微;衰落。", "cites": [{"t": "风颓化替。", "b": "房玄龄《晋书》"}], "words": [{"w": "兴替", "t": "兴盛与衰亡。"}]}, {"meaning": "代替。", "cites": [{"t": "从此替爷征。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "我替他去;替力", "t": "代为出力"}, {"w": "替当", "t": "顶替充当"}, {"w": "替归", "t": "轮替而归"}, {"w": "替天行道", "t": "代行上天的意旨"}, {"w": "替罪", "t": "代人受过"}, {"w": "替下来;替我一下", "t": ""}]}, {"meaning": "衰亡。", "words": [{"w": "朝代兴替", "t": ""}]}, {"meaning": "松弛;怠惰。", "cites": [{"t": "于是乎下陵上替。", "b": "《左传》"}], "words": [{"w": "替懈", "t": "替解;懈怠。"}]}, {"meaning": "替身,替代别人的人。对正身而言。常指代人受罪的人 。", "words": [{"w": "替僧", "t": "明朝,代替皇帝出家的僧人"}, {"w": "替头", "t": "替身。"}]}, {"meaning": "抽屉。", "cites": [{"t": "及薨,帝常思见之,遂为通替棺,欲见则引替睹尸。", "b": "《南史·宋·孝武殷淑传》"}, {"t": "十娘取钥开锁,内皆抽替小箱。", "b": "《警世通言》"}]}, {"meaning": "为;给 。", "words": [{"w": "替人受罪;替我去商店买东西", "t": ""}]}, {"meaning": "同,和。", "cites": [{"t": "天下多少“斯文”,若论起肚子里来,正替你一般哩。", "b": "《西游记》"}]}, {"meaning": "次、批、起。", "words": [{"w": "一替两替", "t": "一次两次"}, {"w": "替另", "t": "再一次。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2507wx','揍','1','zòu','扌','12','','[{"pinyin": "zòu", "defs": [{"meaning": "(形声。从手,奏声。本义:打)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2508wx','款','1','kuǎn','欠','12','','[{"pinyin": "kuǎn", "defs": [{"meaning": "(会意。从欠,塞。省。本义:真诚;诚恳)。"}, {"meaning": "同本义。", "cites": [{"t": "款,诚也。", "b": "《广雅·释诂一》"}, {"t": "谒款天神。", "b": "《史记·司马相如传》"}, {"t": "欲效其款款之愚。", "b": "《汉书·司马迁传》"}]}, {"meaning": "又。", "cites": [{"t": "辞气愿款,有足感动人者。", "b": "《后汉书·江革传》"}, {"t": "愚款端悫,则合之以礼乐。", "b": "《荀子·修身》"}], "words": [{"w": "款服", "t": "诚心归服"}, {"w": "款款深深", "t": "亲切;恳挚"}, {"w": "款交", "t": "至交"}, {"w": "款语", "t": "亲切谈话"}, {"w": "款语温言", "t": "真诚而柔和的话"}, {"w": "款心", "t": "诚心"}, {"w": "款迎", "t": "热情、殷切地欢迎"}, {"w": "款住", "t": "殷勤地留住"}, {"w": "款洽", "t": "诚恳接待;亲切交谈。"}]}, {"meaning": "空;空洞,不真实。", "cites": [{"t": "款启寡闻之民。", "b": "《庄子·达生》"}, {"t": "实不中其声者谓之款。", "b": "《汉书·司马迁传》"}]}, {"meaning": "又。", "cites": [{"t": "款言不听,奸乃不生。", "b": ""}], "words": [{"w": "款言", "t": "空话"}, {"w": "款空", "t": "空洞,空疏"}, {"w": "款足", "t": "中间空的鼎足。"}]}, {"meaning": "缓,慢。", "cites": [{"t": "吴宫夜长官漏款,纻幕四垂灯焰暖。", "b": "元稹《冬白纻》"}, {"t": "点水晴蜒款款飞。", "b": "杜甫《曲江》"}], "words": [{"w": "款段", "t": "从容徐缓的样子"}, {"w": "款慢", "t": "慢慢地"}, {"w": "款踏", "t": "缓缓地走,慢走。"}]}, {"meaning": "事项,条款。", "cites": [{"t": "现今暴骨停尸,是坐着那一款罪犯招因。", "b": "《元曲选·神奴儿》"}], "words": [{"w": "条约的第六条第三款;款状", "t": "记录罪行的文件"}, {"w": "款目", "t": "条款"}, {"w": "款项", "t": "项目;条目。"}]}, {"meaning": "样子;样式;格式。", "cites": [{"t": "又劣弱不中于款。", "b": "《聊斋志异·促织》"}], "words": [{"w": "不中于款", "t": "不合规格。中,符合。款,款式,规格"}, {"w": "款制", "t": "式样"}, {"w": "款儿", "t": "样子;式样。引申为“架子”。"}]}, {"meaning": "架子。", "cites": [{"t": "今儿当着这些人,倒做起方子的款儿来了。", "b": "《红楼梦》"}]}, {"meaning": "款识,古代钟鼎彝器上铸刻的文字。", "cites": [{"t": "今此鼎细小,又有款识。", "b": "《汉书》"}]}, {"meaning": "条理。", "cites": [{"t": "不然,雷雨乱了,显得大圣无款也。", "b": "《西游记》"}]}, {"meaning": "款待,殷勤招待。", "cites": [{"t": "以款人事。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "款延", "t": "款待"}, {"w": "款迓", "t": "殷勤接待"}, {"w": "款宴", "t": "设宴款待"}, {"w": "款遇", "t": "款待"}, {"w": "款谢", "t": "款待答谢。"}]}, {"meaning": "敲,叩。", "cites": [{"t": "款关请见。", "b": "《史记·商君列传》"}, {"t": "海外殊俗,重泽款塞。", "b": "《史记·太史公自序》"}, {"t": "一旦款门来告。", "b": "柳宗元《钴鉧潭记》"}], "words": [{"w": "款打", "t": "敲打"}, {"w": "款塞", "t": "叩塞门"}, {"w": "款关", "t": "叩关"}, {"w": "款徼", "t": "叩塞门。"}]}, {"meaning": "求和;议和。", "cites": [{"t": "顾战款异局也,远近异势也。", "b": "王家桢《王少司马奏疏》"}], "words": [{"w": "款局", "t": "和议的局面"}, {"w": "款计", "t": "议和之计"}, {"w": "款议", "t": "和谈。"}]}, {"meaning": "留;歇息。", "cites": [{"t": "湖山有意留侬款。", "b": "杨万里《诚斋集》"}], "words": [{"w": "款玩", "t": "逗留玩耍。"}]}, {"meaning": "归顺。", "cites": [{"t": "辄屈膝叩首迎款。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2509wx','堪','1','kān','土','12','','[{"pinyin": "kān", "defs": [{"meaning": "(形声。从土,甚声。本义:地面高起)。"}, {"meaning": "同本义。", "cites": [{"t": "堪,地突也。谓土之坟起者。", "b": "《说文》"}, {"t": "堪坏得之,以袭昆仑。", "b": "《庄子·大宗师》"}], "words": [{"w": "堪岩", "t": "山形幽深。"}]}, {"meaning": "指天道。", "cites": [{"t": "堪舆徐行。雄以音知雌。", "b": "《淮南子·天文》。许君注:“堪,天道,舆,地道。盖堪为高处,舆为下处。天高地下之义也。”"}, {"t": "屡堪舆以壁垒兮。", "b": "扬雄《甘泉赋》。注:“天地总名也。”"}, {"t": "倏然堪舆变。", "b": "陆龟蒙、皮日休《开元寺楼看雨联句》"}], "words": [{"w": "堪舆", "t": "天地;风水,亦指风水先生"}, {"w": "堪舆家", "t": "古时为占候卜筮者之一种,后专称以相地看风水为职业者,俗称“风水先生”。"}]}, {"meaning": "勉强承受。"}, {"meaning": "人不堪其忧,回也不改其乐。——《论语·雍也》。", "cites": [{"t": "国不堪贰,君将若之何?", "b": "《左传·隐公元年》"}, {"t": "未堪家多难。", "b": "《诗·周颂·小毖》"}, {"t": "往攻之,予必使汝大堪之。", "b": "《墨子·非攻下》"}, {"t": "口弗堪也。", "b": "《国语·晋语一》"}, {"t": "零落难堪。", "b": "明·李渔《闲情偶寄·种植部》"}, {"t": "众不能堪。", "b": "明·张溥《五人墓碑记》"}, {"t": "非人世所堪。", "b": "宋·文天祥《指南录后序》"}]}, {"meaning": "《更哪堪冷落清秋节。——宋·柳永《雨霖铃》》。", "words": [{"w": "堪忍", "t": "忍受"}, {"w": "不堪一击", "t": ""}]}, {"meaning": "能够;可以。", "cites": [{"t": "众云并不堪用,正令烧除。", "b": "《世说新语·捷悟》"}, {"t": "白璧堪裁且作环。", "b": "李商隐《和友人戏赠》"}], "words": [{"w": "堪叹", "t": "可叹;可惜"}, {"w": "堪可", "t": "正好;正可以"}, {"w": "堪能", "t": "能够。才能;擅长"}, {"w": "堪火", "t": "方言。险些;几乎"}, {"w": "堪称佳作;不堪设想", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2510wx','塔','1','d tǎ','土','12','','[{"pinyin": "d", "defs": [{"meaning": "——见“圪塔”(gēda):即“圪垯”。"}]}, {"pinyin": "tǎ", "defs": [{"meaning": "(形声。从土,荅(dá)声。本义:佛塔,亦作“浮屠”)。"}, {"meaning": "同本义。晋、宋译经时始造“塔”字。塔为形高而顶尖的佛教建筑物,多为五层七级,也有高至十三级的,初为藏佛骨(舍利子)的地方,后世也藏经于其中,俗称宝塔。", "cites": [{"t": "塔势如涌出,孤高耸天宫。", "b": "唐·岑参《与高适薛据同登慈恩寺浮图》"}], "words": [{"w": "塔庙", "t": "寺庙"}, {"w": "塔院", "t": "建有佛塔的院子"}, {"w": "塔铃", "t": "佛塔上的风铃"}, {"w": "塔头", "t": "佛塔顶部"}, {"w": "宝塔;佛塔", "t": ""}]}, {"meaning": "表示块、片。", "cites": [{"t": "小人姓刘,名唐,祖贯东潞州人氏,因这鬓边有这塔朱砂记,人都唤小人做赤发鬼。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2511wx','搭','1','dā','扌','12','','[{"pinyin": "dā", "defs": [{"meaning": "(形声。从手,荅声。本义:打,击)。"}, {"meaning": "同本义。", "cites": [{"t": "常于并州市搭杀人者。", "b": "《北齐书·神武纪》"}], "words": [{"w": "搭面", "t": "抽打面部"}, {"w": "扑搭;搭墩", "t": "跌坐。"}]}, {"meaning": "披;挂;戴。", "cites": [{"t": "行者的眼乖,见他屋檐下,有一条搭衣的绳子。", "b": "《西游记》"}], "words": [{"w": "把衣服搭在篙子上;肩搭道衣;软帽搭在头上", "t": ""}]}, {"meaning": "架设。", "cites": [{"t": "又在西花厅上,搭了一座菊花假山。", "b": "《老残游记》"}], "words": [{"w": "搭舞台;搭浮桥;搭厂", "t": "搭棚;搭台。"}]}, {"meaning": "搁;接触。", "cites": [{"t": "他两个搭上手,却才赌斗。", "b": "《西游记》"}], "words": [{"w": "两根电线搭上了;勾肩搭背", "t": ""}]}, {"meaning": "勾搭,勾引。", "cites": [{"t": "阎婆惜自从和那小张三两个搭上,并无半点情分在这宋江身上。", "b": "《水浒全传》"}]}, {"meaning": "钩。", "cites": [{"t": "叫轿夫歇下轿子,拨去葱管,搭起轿帘。", "b": "《水浒传》"}]}, {"meaning": "书法笔锋。凡上笔带起下笔,上字带起下字都叫“搭”。"}, {"meaning": "短衣。", "cites": [{"t": "中有病夫披白搭。", "b": "宋·林逋《深居杂兴》"}]}, {"meaning": "块,处。", "cites": [{"t": "珍哥的脸就如三月的花园,一搭青,一搭紫,一搭绿,一搭红。", "b": "《醒世姻缘传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2512wx','堰','1','yàn','土','12','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从土,匽(yàn)声。本义:拦河坝)。"}, {"meaning": "同本义。", "cites": [{"t": "东出千金堰。", "b": "《文选·沈约·三月三日率尔成篇诗》"}, {"t": "堰,潜堰也,潜筑土以壅水也。", "b": "《广雅》"}, {"t": "长分桥西有千金堰。", "b": "《洛阳伽蓝记》"}], "words": [{"w": "都江堰;堰塘", "t": "筑有堤堰的蓄水池"}, {"w": "堰埭", "t": "截水的土堰"}, {"w": "堰埭", "t": "壅水的土坝。"}]}, {"meaning": "池塘。", "cites": [{"t": "桌椅板凳在田里堰里飘着。", "b": "闻一多《荒村》"}], "words": [{"w": "一口堰;满满的一堰水", "t": ""}]}, {"meaning": "堵。", "cites": [{"t": "堰,壅水也。", "b": "《说文》"}, {"t": "谁家能堰东流水?", "b": "唐·卢照邻《行路难》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2513wx','揩','1','kāi','扌','12','','[{"pinyin": "kāi", "defs": [{"meaning": "(形声。从手,皆声。本义:擦抹;摩擦) 同本义。", "cites": [{"t": "揩,摩也。", "b": "《字林》"}, {"t": "揩,磨也。", "b": "《广雅》"}, {"t": "揩枳落,突棘藩。", "b": "张衡《西京赋》"}, {"t": "我方坐垢难磨揩。", "b": "梅尧臣《送方进士游庐山》"}], "words": [{"w": "揩锉", "t": "摩擦"}, {"w": "揩面", "t": "洗脸;擦脸"}, {"w": "揩磨", "t": "琢磨"}, {"w": "揩背", "t": "揩擦背部"}, {"w": "揩痒", "t": "在固定的硬物上摩擦以解痒"}, {"w": "揩抹", "t": "擦去;抹去"}, {"w": "把桌子揩干净;揩免", "t": "抹去。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2514wx','越','1','yuè','走','12','','[{"pinyin": "yuè", "defs": [{"meaning": "(形声。从走,戉(yuè)声。本义:经过,越过)。"}, {"meaning": "同本义。", "cites": [{"t": "越,度也。", "b": "《说文》"}, {"t": "越,渡也。", "b": "《广雅》"}, {"t": "越十七扼。", "b": "《吕氏春秋·长攻》"}, {"t": "越陌度阡。", "b": "曹操《短歌行》"}, {"t": "崖可越焉?", "b": "《楚辞·天问》"}, {"t": "越天都之胁。", "b": "明·袁宏道《满井游记》"}, {"t": "予越其右。", "b": ""}, {"t": "越长城之限。", "b": "清·姚鼐《登泰山记》"}, {"t": "越中岭。", "b": ""}], "words": [{"w": "越位;越度", "t": "跨越"}, {"w": "越绝", "t": "越过,度过"}, {"w": "越陌度阡", "t": "穿过田间小路"}, {"w": "越冬", "t": "过冬。"}]}, {"meaning": "超越,跃过。", "cites": [{"t": "戒勿越。", "b": "《礼记·曲礼》"}, {"t": "如今敕令吾,不越一家,搜捉太子并胡嵩。", "b": "《武王伐纣平话》"}], "words": [{"w": "越墙而逃;越级升迁;越先", "t": "超过,超越。"}]}, {"meaning": "超过;超出。", "cites": [{"t": "越职逾法,以取名誉。", "b": "《汉书·宣帝纪》"}, {"t": "必使为善者不越月逾时而得其赏。", "b": "柳宗元《断刑论下》"}], "words": [{"w": "越礼", "t": "不守礼规;超越礼仪范围"}, {"w": "越次", "t": "越出位次;越出序列"}, {"w": "越职;越分", "t": "超过本分"}, {"w": "越俎", "t": "比喻逾越自己的职分而代人做事"}, {"w": "越规", "t": "超越规范。"}]}, {"meaning": "传播,宣扬。", "cites": [{"t": "使越于诸侯。", "b": "《国语·晋语》"}]}, {"meaning": "失坠;坠落。", "cites": [{"t": "乃有不吉不迪,颠越不恭,暂遇奸宄。", "b": "《书·盘庚中》"}]}, {"meaning": "劫夺,抢劫。", "cites": [{"t": "杀越人于货,暋不畏死。", "b": "《书·康诰》"}], "words": [{"w": "越货", "t": "抢劫财物。"}]}, {"meaning": "及、到。", "cites": [{"t": "越明年,政通人和,百废具兴。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "越明年,贫者自南海还。", "b": "清·彭端淑《为学一首示子侄》"}]}, {"meaning": "无义。", "cites": [{"t": "越,于也。於也。", "b": "《广韵》"}, {"t": "越至于今。", "b": "《书·微子》"}, {"t": "越其罔有黍稷。", "b": "《书·盘庚上》"}, {"t": "越兹丽刑。", "b": "《书·吕刑》"}]}, {"meaning": "古国名。也称“於越” ,姒姓,相传始祖为夏少康庶子无佘。封于会稽。春秋末越王勾践卧薪尝胆,终灭吴称要霸,战国时为楚灭。", "cites": [{"t": "越人语天姥。", "b": "唐·李白《梦游天姥吟留别》"}]}, {"meaning": "古民族名。", "cites": [{"t": "南抚夷越。", "b": "《三国志·诸葛亮传》"}, {"t": "胡越为一体。", "b": "唐·魏征《谏太宗十思疏》"}]}, {"meaning": "古时江浙粤闽之地越族所居,谓之百越。越与“粤”通,百越亦作百粤。"}, {"meaning": "地域的代称。"}, {"meaning": "指广东、广西地区,也作中国南方的泛称。", "cites": [{"t": "为越之雪。", "b": "唐·柳宗元《答韦中立论师道书》"}, {"t": "越蜀吠怪。", "b": ""}], "words": [{"w": "越鸟南栖", "t": "南方的鸟飞到北方,也会栖歇在南边的树枝上。比喻思想之情。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2515wx','趁','1','chèn','走','12','','[{"pinyin": "chèn", "defs": [{"meaning": "(形声。本义:追逐)。"}, {"meaning": "同本义。", "cites": [{"t": "急逐趁之,蟆入草间。", "b": "《聊斋志异·促织》"}], "words": [{"w": "疾趁", "t": "急追"}, {"w": "趁逐", "t": "追逐;追求"}, {"w": "趁赶", "t": "追逐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2516wx','趋','1','qū','走','12','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从走,刍声。本义:快步走)。"}, {"meaning": "同本义。", "cites": [{"t": "趋,走也。", "b": "《说文》。按,疾行曰趋,疾趋曰走。”"}, {"t": "走而不趋。", "b": "《礼记·王藻》"}, {"t": "帷薄之外不趋。", "b": "《礼记·曲礼》"}, {"t": "则负匮揭箧担囊而趋。", "b": "《庄子·胠箧》"}, {"t": "急趋之,折过墙隅,迷其所往。", "b": "《聊斋志异·促织》"}, {"t": "步趋动作。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "趋蹑", "t": "快速尾随"}, {"w": "趋行", "t": "急行;赶路"}, {"w": "趋走", "t": "疾走"}, {"w": "趋风", "t": "快走如风。比喻快步向前走或表示向对方致敬"}, {"w": "趋趋", "t": "小步急行的样子"}, {"w": "趋拜", "t": "急往拜见。"}]}, {"meaning": "步,行走。", "cites": [{"t": "盈盈公府步,冉冉府中趋。", "b": "《古乐府·陌上桑》"}], "words": [{"w": "趋趄", "t": "抬腿做出要走的架势"}, {"w": "趋跄", "t": "步行快慢有节奏,合乎礼节"}, {"w": "趋蹲", "t": "趋锵。行动整齐而有节奏。"}]}, {"meaning": "古代的一种礼节,小步快走,表示恭敬。", "cites": [{"t": "赐带剑履上殿,入朝不趋。", "b": "《史记·萧相国世家》"}], "words": [{"w": "趋庭", "t": "称承受父亲教导"}, {"w": "趋出", "t": "小步疾行退出。示恭敬"}, {"w": "趋走", "t": "小步疾行,以示庄敬"}, {"w": "趋进", "t": "小步疾行而前,表示敬意的一种动作。"}]}, {"meaning": "奔赴;趋向。", "cites": [{"t": "前者止,后者趋,辇乃止。", "b": "《韩非子·外储说下》"}, {"t": "夜趋高邮。", "b": "宋·文天祥《指南录后序》"}, {"t": "趋真州扬州。", "b": ""}, {"t": "尝趋百里外。", "b": "明·宋濂《送东阳马生序》"}, {"t": "前趋直上。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "局势趋于稳定;大势所趋;趋前;售价已趋上升;趋跄", "t": "奔走侍奉"}, {"w": "趋走", "t": "供差遣奔走;亦作仆役别名"}, {"w": "趋厮", "t": "供差遣的童仆"}, {"w": "趋世", "t": "奔走于世俗之事"}, {"w": "趋赴", "t": "奔赴。"}]}, {"meaning": "催促。", "cites": [{"t": "卫音趋数烦志。", "b": "《礼记·乐记》"}, {"t": "使者驰传督趋。", "b": "《汉书·食货志上》"}, {"t": "趋具食。", "b": "《汉书·酷吏咸宣传》"}, {"t": "令趋销印。", "b": "《汉书·高帝纪》"}, {"t": "若不趋降。", "b": ""}]}, {"meaning": "志趣。", "cites": [{"t": "言眇而趋深。", "b": "《论衡·定贤》"}], "words": [{"w": "趋尚", "t": "情趣;好尚。"}]}, {"meaning": "节奏。", "cites": [{"t": "足蹀《阳阿》之舞,而手会《绿水》之趋。", "b": "《淮南子》。高诱注:“趋,投节也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2517wx','超','1','chāo','走','12','','[{"pinyin": "chāo", "defs": [{"meaning": "(形声。从走,召声。本义:跃上;跳过,跃过)。"}, {"meaning": "同本义。", "cites": [{"t": "超,跳也。", "b": "《说文》"}, {"t": "超乘者五百乘。", "b": "《吕氏春秋·悔过》。注:“巨踊上车也。”"}, {"t": "超回志度。", "b": "《楚辞·九章·抽思》"}, {"t": "超五岭兮嵯峨。", "b": "《楚辞·九思·伤时》"}, {"t": "方投石超距。", "b": "《史记·白起王翦传》"}, {"t": "挟泰山以超北海。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "超乘", "t": "跃登战车"}, {"w": "超足", "t": "腾跃"}, {"w": "超步", "t": "跨登;迈步"}, {"w": "超次", "t": "超越等级升迁。"}]}, {"meaning": "提拔;擢升。", "cites": [{"t": "故莫敢超等逾官。", "b": "《管子·法禁》"}], "words": [{"w": "超拜", "t": "越级升授官职"}, {"w": "超阶", "t": "指超级擢升的官职。"}]}, {"meaning": "超过;胜过。", "cites": [{"t": "超五帝侔三王者,必此法也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "每亩超千斤;超俗", "t": "超越凡俗;出众。"}]}, {"meaning": "超脱,超凡。", "cites": [{"t": "虽有荣观燕处超然。", "b": "《老子》。注:“超然远避而不处也。”"}], "words": [{"w": "超逸", "t": "超然脱俗,俊逸高雅。"}]}, {"meaning": "远;遥远。", "cites": [{"t": "平原忽兮路超远。", "b": "《楚辞·九歌·国殇》"}], "words": [{"w": "超然", "t": "遥远的样子。"}]}, {"meaning": "惆怅,若有所失。", "cites": [{"t": "武侯超然不对。", "b": "《庄子·徐无鬼》"}, {"t": "于是二子愀然改容,超若自失,逡巡避席。", "b": "《文选·司马相如·上林赋》"}], "words": [{"w": "超忽", "t": "迷惘,怅然自失。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2518wx','揽','1','lǎn','扌','12','','[{"pinyin": "lǎn", "defs": [{"meaning": "(形声。从手,览声。本义:执,持)。"}, {"meaning": "同本义。", "cites": [{"t": "俱可手揽。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "揽跋", "t": "揽辔跋涉"}, {"w": "揽镜", "t": "持镜;对镜"}, {"w": "揽持", "t": "把持;掌握"}, {"w": "揽摄", "t": "把持。"}]}, {"meaning": "采摘。", "words": [{"w": "揽月", "t": "摘月。喻壮举"}, {"w": "揽取", "t": "摘取,收取"}, {"w": "揽结", "t": "采摘系结。"}]}, {"meaning": "招引;兜揽。", "cites": [{"t": "总揽英雄,思贤若渴。", "b": "《三国志》"}], "words": [{"w": "揽脚", "t": "脚夫招揽顾客"}, {"w": "揽事", "t": "管闲事"}, {"w": "揽买卖", "t": ""}]}, {"meaning": "提,撩起。", "cites": [{"t": "揽裙脱丝履,举身赴清池。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "观看。", "cites": [{"t": "而欲为人之国者,此揽乎三王之利,而不见其患者也。", "b": "《庄子·在宥》"}, {"t": "流揽无穷,归神日母。", "b": "汉·枚乘《七发》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2519wx','堤','1','dī','土','12','','[{"pinyin": "dī", "defs": [{"meaning": "(形声。从土,是声。本义:河堤,堤坝)。"}, {"meaning": "同本义。", "cites": [{"t": "隄,唐也。", "b": "《说文》"}, {"t": "完堤防。", "b": "《礼记·月令》"}, {"t": "脩堤梁。", "b": "《荀子·王制》"}, {"t": "河堤绕绿水。", "b": "唐·李白《赠清漳明府侄聿》"}], "words": [{"w": "河堤;海堤;堤埽", "t": "堤和埽。亦泛指堤坝"}, {"w": "堤唐", "t": "高出地面的中庭甬道。"}]}, {"meaning": "陶器的底座。", "cites": [{"t": "蓼菜成行,瓶瓯有堤。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2520wx','提','1','dī tí','扌','12','','[{"pinyin": "dī", "defs": [{"meaning": "——用于“提防”(dīfang)、“提溜”(dīliu)等。"}]}, {"pinyin": "tí", "defs": [{"meaning": "(形声。从手,是声。本义:悬持;悬空拎着物品)。"}, {"meaning": "同本义。", "cites": [{"t": "提,挈也。", "b": "《说文》"}, {"t": "匪面命之,言提其耳。", "b": "《诗·大雅·抑》"}, {"t": "提刀而立。", "b": "《庄子·养生主》"}, {"t": "一贼提刀。", "b": "明·魏禧《大铁锥传》"}, {"t": "椊下提殴之。", "b": "明·高启《书博鸡者事》"}, {"t": "提竹筒丝笼。", "b": "《聊斋志异·促织》"}], "words": [{"w": "提壶,提桶;提开水;提掳", "t": "拎,拿"}, {"w": "提举", "t": "提而举之。"}]}, {"meaning": "引申为带领;统领。古代如提督、提举、提点、提刑、提学、提法诸官名,皆取此义。", "cites": [{"t": "今又提一旅孤军。", "b": "宋·岳飞《五岳祠盟记》"}], "words": [{"w": "提军", "t": "率领军队"}, {"w": "提动", "t": "调动"}, {"w": "提兵", "t": "率领军队。"}]}, {"meaning": "紧紧拿着;执持。", "cites": [{"t": "以是与天子提衡,争秩于诸侯。", "b": "《管子·轻重己》"}], "words": [{"w": "提握;提笔", "t": "握笔。指写文章"}, {"w": "提刀", "t": "持刀。"}]}, {"meaning": "说起,提及。", "cites": [{"t": "三桩儿誓愿明提遍。", "b": "关汉卿《窦娥冤》"}], "words": [{"w": "提秽", "t": "话语不干净;指责"}, {"w": "提名抖姓", "t": "提名道姓"}, {"w": "提念", "t": "说起。"}]}, {"meaning": "指出;举出。", "cites": [{"t": "记事者必提其要,纂言者必钩其玄。", "b": "唐·韩愈《进学解》"}]}, {"meaning": "提拔;提升。", "cites": [{"t": "感其提拔之恩。", "b": "房玄龄《晋书》。"}], "words": [{"w": "提引", "t": "提拔"}, {"w": "提奖", "t": "提拔奖励。"}]}, {"meaning": "携带。", "cites": [{"t": "提一匕首。", "b": "《战国策·燕策》"}, {"t": "奉承亲戚,提挈妻子而寄托之。", "b": "《墨子·兼爱下》"}]}, {"meaning": "掷。", "cites": [{"t": "皇太子引博局提吴太子,杀之。", "b": "《汉书·吴王濞传》。师古曰:“提,掷也。”"}, {"t": "拔剑四面提出。", "b": "《汉书·王莽传下》"}, {"t": "宛市百姓共提击之。", "b": ""}, {"t": "以冒絮提文帝。", "b": "《史记·绛侯周勃世家》"}]}, {"meaning": "请求回答或要求提供消息 。", "words": [{"w": "提问题;提方案;提要求;提意见", "t": ""}]}, {"meaning": "提醒 。", "words": [{"w": "提撕点醒", "t": "提醒;提引"}, {"w": "提撕", "t": "提引;提醒"}, {"w": "提亮", "t": "提醒"}, {"w": "提点", "t": "提醒指点"}, {"w": "提省", "t": "提醒。"}]}, {"meaning": "扶持 。", "words": [{"w": "提掇", "t": "提携。帮助,照顾"}, {"w": "提援", "t": "营救;解脱"}, {"w": "提掖", "t": "挟住两腋将人拎起。"}]}, {"meaning": "传讯,指提取犯人 。"}, {"meaning": "如:提事(捕快);提犯人;提问(传讯审问);提解(押送犯人或财物)。"}, {"meaning": "一种垂直向上舀油、酒等的器具,有很长的把儿,往往按舀液体的斤两制成大小不等的一套 。", "words": [{"w": "油提;酒提", "t": ""}]}, {"meaning": "提梁。篮、壶等的提手 。", "words": [{"w": "提炉", "t": "有提梁的香炉。"}]}, {"meaning": "用于提着的物体,其重量没有确数。", "words": [{"w": "一提金;一提银", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2521wx','博','1','bó','十','12','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从十,尃(fū)声。“十”意思是四方中央齐备。“尃”有分布之义。本义:大)。"}, {"meaning": "同本义。与“小”相对。", "cites": [{"t": "博,大通也。", "b": "《说文》"}, {"t": "戎车孔博。", "b": "《诗·鲁颂·泮水》"}, {"t": "岂必褒衣博带。", "b": "《淮南子·泛论》"}, {"t": "丰丽博敞。", "b": "王逸《鲁灵光殿赋》"}, {"t": "倚沼畦瀛兮遥望博。", "b": "《楚辞·招魂》"}, {"t": "不学博依。", "b": "《礼记·学记》"}], "words": [{"w": "宽衣博带;博硕", "t": "粗大;宽大"}, {"w": "博硕肥腯", "t": "古时献牲祭神的祝祷辞,是说六畜肥大。"}]}, {"meaning": "宽广;广搏。", "cites": [{"t": "博闻强志,明于治乱,娴于辞令。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "广博", "t": "范围大,方面多"}, {"w": "博闻", "t": "见闻广博"}, {"w": "博引旁搜", "t": "考证完备广博,引证资料丰富充实。"}]}, {"meaning": "众多;丰富。", "cites": [{"t": "博我以文,约我以礼。", "b": "《论语·子罕》"}], "words": [{"w": "地大物博;博祸", "t": "多种祸害"}, {"w": "博富", "t": "丰富广博"}, {"w": "博杂", "t": "多而杂乱。"}]}, {"meaning": "广泛;普遍。", "cites": [{"t": "风雨博施。", "b": "《荀子·天论》"}], "words": [{"w": "博览群书;博施", "t": "普遍施与"}, {"w": "博物洽闻", "t": "博见广闻"}, {"w": "博考", "t": "广泛地考查。"}]}, {"meaning": "渊博,知道得多。", "cites": [{"t": "君子博学而日参省乎己,则知明而行无过矣。", "b": "《荀子·劝学》"}], "words": [{"w": "渊博", "t": "学识深而且广。"}]}, {"meaning": "赌,博弈。", "cites": [{"t": "与闵公博。", "b": "《公羊传·庄公十二年》"}, {"t": "则博塞以游。", "b": "《庄子·骈拇》"}, {"t": "或以游博持掩为事。", "b": "《后汉书·王符传》"}, {"t": "不有博奕者乎。", "b": "《论语·阳货》"}, {"t": "或饮或博。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "博剧", "t": "博戏,赌博"}, {"w": "博弈", "t": "古六博戏与古围棋。"}]}, {"meaning": "取得。", "cites": [{"t": "博个封妻荫子。", "b": "《水浒传》"}], "words": [{"w": "博笑", "t": "谦词。换取别人一笑"}, {"w": "博鬻", "t": "换取"}, {"w": "博名", "t": "获取好名声。"}]}, {"meaning": "换取。", "cites": [{"t": "屠毒天下之肝脑,离散天下之子女,以博我一人之产业,曾不惨然。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "博易", "t": "交易;贸易"}, {"w": "博征", "t": "通过以物易物的方式进行征收。"}]}, {"meaning": "争斗,博斗。", "cites": [{"t": "一日,博鸡者遨于市。", "b": "明·高启《书博鸡者事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2522wx','揭','1','jiē','扌','12','','[{"pinyin": "jiē", "defs": [{"meaning": "标志。", "cites": [{"t": "峨嵋为泉阳之揭。", "b": "郭璞《江赋》"}]}, {"meaning": "揭揭。"}, {"meaning": "修长的样子。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2523wx','喜','1','xǐ','口','12','','[{"pinyin": "xǐ", "defs": [{"meaning": "(会意。甲骨文上面是“鼓”本字,下面是“口”。“鼓”表示欢乐,“口”是发出欢声。本义:快乐;高兴)。"}, {"meaning": "同本义(乐之见于谈笑曰喜。喜,形于色)。", "cites": [{"t": "喜,乐也。", "b": "《说文》"}, {"t": "人喜则斯陶。", "b": "《礼记·檀弓》"}, {"t": "其志为喜。", "b": "《素问·五远行大论》"}, {"t": "既见君子,我心则喜。", "b": "《诗·小雅·菁菁》"}, {"t": "陈胜、吴广喜,念鬼。", "b": "《史记·陈涉世家》"}, {"t": "嘿然大喜。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "虎因喜。", "b": "唐·柳宗元《三戒》"}, {"t": "不以物喜。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "三保亦自喜。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "喜容原好,愁容也好,蓦地间怒容越好。", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "喜洽", "t": "喜恰。和颜悦色;热情"}, {"w": "喜之不尽", "t": "无限欢喜"}, {"w": "喜匆匆", "t": "喜欢,兴奋的样子"}, {"w": "喜欢不杀", "t": "很喜欢;喜欢死了"}, {"w": "喜上眉梢", "t": "眉宇间露出喜悦的表情。"}]}, {"meaning": "容易。", "cites": [{"t": "人命难知,计算喜错。", "b": "《百喻经·婆罗门杀子喻》"}]}, {"meaning": "喜爱;爱好。", "cites": [{"t": "喜为吏。", "b": "《汉书·黄霸传》"}, {"t": "齐威王之时喜隐。", "b": "《史记·滑稽列传》"}, {"t": "宽仁喜儒术。", "b": "《淮南子·宪王钦传》"}, {"t": "盖孔子晚而喜《易》。", "b": "《史记·田敬仲完世家》"}, {"t": "最喜小儿。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "少年人常喜事。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "老人犹喜。", "b": "清·周容《芋老人传》"}]}, {"meaning": "妇女怀孕。", "cites": [{"t": "叫大夫瞧了,又说并不是喜。", "b": "曹雪芹《红楼梦》"}], "words": [{"w": "喜信", "t": "指怀孕"}, {"w": "喜脉", "t": "妇女怀孕的脉象"}, {"w": "喜弹", "t": "孵不成雏鸭的鸭蛋。也叫“鸭馄饨”。"}]}, {"meaning": "喜事。", "cites": [{"t": "固庆其喜而吊其忧。", "b": "《国语·鲁语》"}, {"t": "内家报喜车凌晓,太史占祥斗挂秋。", "b": "宋·秦观《庆张君俞都尉留后得子》"}, {"t": "喜宴前枉唤新郎,洞房中依然触觉。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "喜兆", "t": "喜事的征兆"}, {"w": "喜信", "t": "唐代进士及第的家报;喜庆事情的先兆。"}]}, {"meaning": "痘疹 。旧俗孩子出痘时,常因惧得天花而讳言之,又以痘既发出便可平安,故用“喜”字代指,以求吉利。", "cites": [{"t": "姐儿发热是见喜了,并非别症。", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2524wx','彭','1','péng','彡','12','','[{"pinyin": "péng", "defs": [{"meaning": "(会意。从壴(zhù),从彡。“壴”在古文字中象鼓形。彡(shān),毛饰形。本义:鼓声) 同本义。", "cites": [{"t": "彭,鼓声也。", "b": "《说文》。朱骏声按:从鼓省,从彡。会意。彡即三也,击鼓以三通为率。"}, {"t": "一鼓作气,再而衰,三而竭。", "b": "《左传·庄公十年》"}]}, {"meaning": "古国名 。在今四川省彭山县。"}, {"meaning": "古水名。"}, {"meaning": "在湖北省房县。"}, {"meaning": "在河南省鲁山县东南。"}, {"meaning": ";彭泽先生(东晋大诗人陶潜。因曾任彭泽令,故名“彭泽先生”)。"}, {"meaning": "侧,边。", "cites": [{"t": "九四,匪其彭。", "b": "《易·大有》"}, {"t": "若彭有水浊非常者。", "b": "《墨子·备穴》"}]}, {"meaning": "水流声。", "cites": [{"t": "彭濞涌溢。", "b": "《殽阬君神祠碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2525wx','揣','1','chuǎi chuāi chuài','扌','12','','[{"pinyin": "chuǎi", "defs": [{"meaning": "(会意。本义:测量;量度)。"}, {"meaning": "同本义。", "cites": [{"t": "揣,量也。", "b": "《说文》"}, {"t": "度量曰揣。", "b": "《方言》十二"}, {"t": "揣高卑。", "b": "《左传·昭公三十二年》"}, {"t": "不揣其本而齐其末。", "b": "《孟子·告子下》"}]}, {"meaning": "猜想,推测;估量。", "cites": [{"t": "淮主调说以取尊贵,是名为揣。", "b": "《论衡·逢遇》"}, {"t": "内符者,揣之主也。", "b": "《鬼谷子·摩》"}, {"t": "简练以为揣摩。", "b": "《战国策·秦策》"}, {"t": "生揣我何念。", "b": "《汉书·陆贾传》"}, {"t": "方进揣知其指。", "b": "《汉书·翟方进传》"}], "words": [{"w": "揣料", "t": "估量;估计"}, {"w": "揣夺", "t": "估摸,猜度"}, {"w": "揣摹", "t": "猜测,估量。"}]}, {"meaning": "捶击。", "cites": [{"t": "揣而锐之,不可长保。", "b": "《老子·九章》"}], "words": [{"w": "揣挫", "t": "捶击折辱。"}]}]}, {"pinyin": "chuāi", "defs": [{"meaning": "放在衣服里"}, {"meaning": "怀孕", "words": [{"w": "揣驹", "t": "牲畜怀胎"}]}, {"meaning": "强给;给与", "words": [{"w": "揣与", "t": "强加给;给与"}, {"w": "揣巴", "t": "胡乱吃"}]}]}, {"pinyin": "chuài", "defs": [{"meaning": "挣扎。", "cites": [{"t": "待伊揣几合,赢些方便。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "挣揣", "t": "挣扎。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2526wx','插','1','chā','扌','12','','[{"pinyin": "chā", "defs": [{"meaning": "(形声。从手,臿(chā)声。本义:刺入、挤放进去)。"}, {"meaning": "同本义。", "cites": [{"t": "插,刺内也。", "b": "《说文》"}, {"t": "沉吟放拨插弦中。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "是日城内遍插白旗。", "b": "《广州军务记》"}], "words": [{"w": "插花筵席", "t": "流水席,即客人随到随开的筵席"}, {"w": "插标", "t": "古人出售物品时,把茅草插在物品上表示出售"}, {"w": "插管", "t": "双肩式大门的门闩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2527wx','揪','1','jiū','扌','12','','[{"pinyin": "jiū", "defs": [{"meaning": "(形声。从手,秋声。本义:收聚)。"}, {"meaning": "同本义。", "cites": [{"t": "佺揪聚军中币万余匹,悉袍、带并与之。", "b": "《新唐书》"}]}, {"meaning": "抓;扯住。", "cites": [{"t": "郑屠右手拿刀,左手便来要揪鲁达。", "b": "《水浒传》"}], "words": [{"w": "揪捽", "t": "抓住;扭住"}, {"w": "揪扯", "t": "揪抓拉扯"}, {"w": "揪撇", "t": "抛到一边"}, {"w": "揪采", "t": "瞅睬。看顾;理睬;扭拉"}, {"w": "揪痧", "t": "民间治疗某些疾病的一些方法。通常用手指揪颈部、咽喉部、额部,使局部皮肤充血。"}]}, {"meaning": "抽打。", "cites": [{"t": "拨县里捉得去办,办理拐逃,揪二百藤条,收仔长监。", "b": "清·韩邦庆《海上花列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2528wx','搜','1','sōu','扌','12','','[{"pinyin": "sōu", "defs": [{"meaning": "搜索;搜查。", "cites": [{"t": "搜,求也。秦晋之间曰搜,就室曰搜。", "b": "《方言二》"}, {"t": "于是惠子恐,搜于国中,三日三夜。", "b": "《庄子·秋水》"}], "words": [{"w": "搜弊", "t": "搜查弊端,弄清欺诈行为"}, {"w": "搜猜", "t": "搜查,搜寻"}, {"w": "搜筒", "t": "搜检,搜查"}, {"w": "搜看", "t": "搜索检查,搜查"}, {"w": "搜阅", "t": "搜查,查看"}, {"w": "搜山煮海", "t": "严密搜查各个角落"}, {"w": "搜伏", "t": "搜索隐伏之敌"}, {"w": "搜刷", "t": "搜索。"}]}, {"meaning": "寻求。", "cites": [{"t": "时太子詹事周捨撰《礼疑义》,自汉魏至于齐梁,并加搜采。", "b": "《梁书·孔休源传》"}], "words": [{"w": "搜剔", "t": "搜寻,寻找"}, {"w": "搜遗", "t": "寻找、检查遗漏之处"}, {"w": "搜须捉虱", "t": "竭力搜寻"}, {"w": "搜刷", "t": "搜捕,清查"}, {"w": "搜才", "t": "寻求贤才"}, {"w": "搜句", "t": "寻求佳句"}, {"w": "搜抉", "t": "搜求选择"}, {"w": "搜吟", "t": "寻觅诗句"}, {"w": "搜拔", "t": "寻求选拔"}, {"w": "搜奇;搜采", "t": ""}]}, {"meaning": "检查,检点。", "cites": [{"t": "不肯搜自己狂为,只待要觅别人破绽。", "b": "《西厢记》"}]}, {"meaning": "选择。", "cites": [{"t": "王安丰选女婿,从挽郎搜其胜者。", "b": "《世说新语》"}]}, {"meaning": "挖,掏。", "cites": [{"t": "着这逼绰刀子搜开这墙阿,磕掉我靠倒这墙。", "b": "《珠砂担》"}]}, {"meaning": "打猎。", "cites": [{"t": "春振旅以搜。", "b": "《汉书》"}]}, {"meaning": "消除,清除"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2529wx','煮','1','zhǔ','灬','12','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(形声。从火,者声。本义:把东西放在有水的锅里加热使熟) 同本义。", "cites": [{"t": "东煮海水为盐。", "b": "《汉书》"}, {"t": "命妪煮芋。", "b": "清·周容《芋老人传》"}]}, {"meaning": "又。", "cites": [{"t": "妪煮芋进。", "b": ""}, {"t": "时挑野菜和根煮,旋斫生柴带叶烧。", "b": "杜荀鹤《山中寡妇》"}, {"t": "若是射得下来,村房人家,讨些水,煮瀑得熟,也得充饥。", "b": "《水浒传》"}], "words": [{"w": "煮瀑", "t": "即煮泡,放在水中煮"}, {"w": "煮爆", "t": "煮"}, {"w": "煮汤", "t": "熬药"}, {"w": "煮海", "t": "煮海水为盐"}, {"w": "煮井", "t": "煮盐井之水为盐"}, {"w": "煮汁", "t": "药物和水熬成汁液"}, {"w": "煮酒", "t": "烫酒,酿酒;热的酒"}, {"w": "煮雪", "t": "用雪水烧茶或作饭。"}]}, {"meaning": "煮盐,熟盐 。熬干含盐的水分,提取食盐。", "cites": [{"t": "齐有渠展之盐,燕有辽东之煮。", "b": "《管子·地数》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2530wx','援','1','yuán','扌','12','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从手,爰(yuán)声。本义:拉,引)。"}, {"meaning": "同本义。", "cites": [{"t": "援,引也。", "b": "《说文》"}, {"t": "无然畔援。", "b": "《诗·大雅·皇矣》"}, {"t": "不援其所不及。", "b": "《礼记·缁衣》"}, {"t": "不援上。", "b": "《礼记·中庸》"}, {"t": "男女授受不亲,嫂溺手援非正。", "b": "《豆棚闲话》"}, {"t": "右抚剑,左援带,命驱之出。", "b": "《左传》"}], "words": [{"w": "援及", "t": "动起"}, {"w": "援推", "t": "引之使来,推之使去。"}]}, {"meaning": "攀援。", "cites": [{"t": "猱蝯善援。", "b": "《尔雅》"}, {"t": "桃李之垂行者,莫之援也。", "b": "《吕氏春秋·下贤》"}, {"t": "夫为四邻之援。", "b": "《国语·鲁语上》"}, {"t": "猿猱欲渡愁攀援。", "b": "李白《蜀道难》"}, {"t": "石崖侧削则援崖。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "援系", "t": "犹攀附。旧谓求婚之谦词。"}]}, {"meaning": "擢拔,引进推荐。", "cites": [{"t": "某官异材秀出,博学名家,…今乃援而进之,论者惜其晚矣。", "b": "苏轼《答曾舍人启》"}], "words": [{"w": "援进", "t": "提拔任用"}, {"w": "援拾", "t": "提携收录。"}]}, {"meaning": "引用。", "cites": [{"t": "援赦减等。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "援纳", "t": "援例纳银捐官"}, {"w": "援例", "t": "清朝规定捐一定数额的银子,可得到官职或监生资格"}, {"w": "援例监", "t": "按照常规捐钱取得国子监监生的资格"}, {"w": "有例可援;援验", "t": "引证。"}]}, {"meaning": "拯救,相救。", "cites": [{"t": "今天下溺矣,夫子之不援,何也。", "b": "《孟子》"}], "words": [{"w": "抗美援朝;援手", "t": "伸手拉人一把以解救其困厄"}, {"w": "援拯", "t": "援救,帮助"}, {"w": "援应", "t": "声援接应。"}]}, {"meaning": "助,救助。", "cites": [{"t": "为卿后援。", "b": "《资治通鉴》"}, {"t": "盖失强援。", "b": "宋·苏洵《六国论》"}]}, {"meaning": "篱笆。", "cites": [{"t": "好事者怜之,编竹成援,遂之生植。", "b": "柳宗元《孤松》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2531wx','搀','1','chān','扌','12','','[{"pinyin": "chān", "defs": [{"meaning": "(形声。从手,毚(chán)声。本义:扶,牵挽)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2532wx','裁','1','cái','衣','12','','[{"pinyin": "cái", "defs": [{"meaning": "(形声。从衣,(zāi)声。本义:裁制,剪裁)。"}, {"meaning": "同本义。", "cites": [{"t": "裁,制衣也。", "b": "《说文》"}, {"t": "夷衾质杀之,裁犹冒之。", "b": "《礼记·丧大记》。注:“犹制也。”"}, {"t": "十四学裁衣。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "裁此百日功,唯将一朝舞。", "b": "唐·韦应物《杂体》"}], "words": [{"w": "套裁;剪裁;对裁;裁衣", "t": "裁剪衣料制作衣服。"}]}, {"meaning": "裁定;判断。", "cites": [{"t": "大王裁其罪。", "b": "《战国策·秦策》。注:“制也。”"}, {"t": "裁大者众之所比也。", "b": "《管子·地形》。注:“断也。”"}, {"t": "公羊辨而裁。", "b": "《谷梁传·序》。注:“谓善能裁断。”"}, {"t": "今请姑娘裁夺着,再添些也使得。", "b": "《红楼梦》"}], "words": [{"w": "裁示", "t": "裁决并指示"}, {"w": "裁答", "t": "裁决答复。"}]}, {"meaning": "删除;削减。", "cites": [{"t": "而裁其贾以招民。", "b": "《汉书·食货志》。注:“谓减省之也。”"}, {"t": "又裁节邮传冗费。", "b": "《明史·海瑞传》"}], "words": [{"w": "裁革", "t": "减免"}, {"w": "裁人", "t": "裁员。裁减人员。"}]}, {"meaning": "杀戮。", "cites": [{"t": "跪而自裁。", "b": "《汉书·贾谊传》"}]}, {"meaning": "体制。", "cites": [{"t": "取殊裁于八都。", "b": "张衡《西京赋》"}], "words": [{"w": "裁制", "t": "规模制式。"}]}, {"meaning": "刚刚。", "cites": [{"t": "裁日阅数人。", "b": "《汉书·王贡两龚鲍传序》"}, {"t": "手裁举。", "b": "《聊斋志异·促织》"}, {"t": "抵透光处,炬裁尽。", "b": "《徐霞客游记·游黄山记》"}]}, {"meaning": "仅仅。", "cites": [{"t": "裁买城西数亩地,槀葬而已。", "b": "《汉书·马援传》"}, {"t": "裁封数百户。", "b": ""}, {"t": "士生一世,但取衣食裁足。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2533wx','搁','1','gē gé','扌','12','','[{"pinyin": "gē", "defs": [{"meaning": "(形声。从手,阁声。本义:放,放置)。"}, {"meaning": "同本义。", "cites": [{"t": "况且我又年轻,不压人,怨不得不把我搁在眼里。", "b": "《红楼梦》"}], "words": [{"w": "搁手", "t": "放开手,作罢"}, {"w": "搁开", "t": "放下,放开"}, {"w": "再搁点糖", "t": ""}]}, {"meaning": "停顿;耽搁。", "cites": [{"t": "原来这一向因凤姐病了,李纨探春料理家务,不得闲暇;接着过年过节,许多杂事,竟将诗社搁起。", "b": "《红楼梦》七十回"}], "words": [{"w": "延搁", "t": "拖延耽搁"}, {"w": "这事搁一搁再说;搁煞", "t": "方言。谓搁置不周转或不流通;耽搁"}, {"w": "搁误", "t": "耽误。"}]}]}, {"pinyin": "gé", "defs": [{"meaning": "经受,承受。", "cites": [{"t": "不过是脸软心慈,搁不住人求两句罢了。", "b": "《红楼梦》十六回"}, {"t": "再结实的身子骨儿,搁得住这么折腾吗?", "b": ""}], "words": [{"w": "搁栅", "t": "支承地板、楼板或天花板的梁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2534wx','搓','1','cuō','扌','12','','[{"pinyin": "cuō", "defs": [{"meaning": "(形声。从手,差声。本义:两掌互相摩擦)。"}, {"meaning": "同本义。", "cites": [{"t": "搓,手搓碎也。", "b": "《广韵》"}, {"t": "搓,搓挪也。", "b": "《康熙字典》"}], "words": [{"w": "搓手;搓手顿足", "t": "形容焦急不耐烦的样子"}, {"w": "搓熟的汤团", "t": "比喻服服贴贴"}, {"w": "搓草绳;搓挪", "t": ""}]}, {"meaning": "急迫。", "cites": [{"t": "填词莺啭切,促轸雁声搓。", "b": "袁桷《播州宣抚杨资德》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2535wx','搂','1','lōu lǒu','扌','12','','[{"pinyin": "lōu", "defs": [{"meaning": "(形声。从手,娄声。本义:引,拉拢)。"}, {"meaning": "同本义。", "cites": [{"t": "搂,曳聚也。", "b": "《说文》"}, {"t": "五霸者,搂诸侯以伐诸侯者也。", "b": "《孟子·告子下》"}], "words": [{"w": "搂伐", "t": "拉拢、挟持他国一起征伐"}, {"w": "搂沟子", "t": "奉迎拍马"}, {"w": "搂搜", "t": "乖张;执拗"}, {"w": "搂搜索落", "t": "找岔子数落人。"}]}, {"meaning": "搂抱;用手或工具把东西向自己面前聚集。", "cites": [{"t": "逾东家墙而搂其处子,则得妻。", "b": "《孟子·告子下》"}], "words": [{"w": "搂耙", "t": "锄地,培土"}, {"w": "搂干草", "t": ""}]}, {"meaning": "拨。", "cites": [{"t": "拽开步,双手使钯,将荆棘左右搂开。", "b": "《西游记》"}]}]}, {"pinyin": "lǒu", "defs": [{"meaning": "用臂膀抱住或怀抱。", "cites": [{"t": "早被外祖母抱住,搂入怀中。", "b": "《红楼梦》"}], "words": [{"w": "搂处", "t": "搂抱处女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2536wx','搅','1','jiǎo','扌','12','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从手,觉声。本义:扰乱)。"}, {"meaning": "同本义。", "cites": [{"t": "搅,乱也。", "b": "《说文》"}, {"t": "袛搅我心。", "b": "《诗·小雅·何人斯》"}], "words": [{"w": "搅攘", "t": "扰乱"}, {"w": "搅恼", "t": "搅扰"}, {"w": "搅家精", "t": "拨弄是非、寻衅闹事,搅得家庭不和的人"}, {"w": "搅尸灵", "t": "方言。顽皮、捣乱,使不安宁。"}]}, {"meaning": "胡闹;嬉戏。", "cites": [{"t": "这不是搅吗!", "b": "《儿女英雄传》"}], "words": [{"w": "搅七念三", "t": "胡闹"}, {"w": "搅诨", "t": "戏谑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2537wx','壹','1','yī','士','12','','[{"pinyin": "yī", "defs": [{"meaning": "(形声。小篆字形。从壶,吉声。“一”的大写。本义:专一)。"}, {"meaning": "同本义。", "cites": [{"t": "壹,专一也。", "b": "《说文》"}, {"t": "君子壹教,凝子壹学,亟成。", "b": "《荀子·大略》"}, {"t": "与人之壹也。", "b": "《左传·文公三年》。注:“壹,无贰心。”"}, {"t": "若琴瑟之专壹,谁能听之?", "b": "《左传·昭二十年》"}], "words": [{"w": "壹心", "t": "同心;专心"}, {"w": "壹德", "t": "谓一心一意"}, {"w": "壹意", "t": "专心致志"}, {"w": "壹定", "t": "一贯不变,固定不变。"}]}, {"meaning": "统一;一致。", "cites": [{"t": "圣人之为国也,壹赏,壹刑,壹教。", "b": "《商君书·赏刑》"}], "words": [{"w": "壹同", "t": "统一"}, {"w": "壹统", "t": "一统"}, {"w": "壹意", "t": "统一意志"}, {"w": "壹体", "t": "一致,如同一个整体"}, {"w": "壹气", "t": "元气,统一不杂之气。"}]}, {"meaning": "皆;一概;一律。", "cites": [{"t": "自天子以至于庶人,壹是皆一修身为本。", "b": "《礼记·大学》"}], "words": [{"w": "壹是", "t": "一概,一律"}, {"w": "壹概", "t": "一概,犹言齐一"}, {"w": "壹切", "t": "一切;全部"}, {"w": "壹匡", "t": "一匡。使一切得到匡正。"}]}, {"meaning": "一样;等同;同一。", "cites": [{"t": "镇静者修之,则壹。", "b": "《国语·晋语七》"}], "words": [{"w": "壹齐", "t": "齐一,划一"}, {"w": "壹体", "t": "如同一个整体。"}]}, {"meaning": "“一”的大写。", "cites": [{"t": "节以壹惠。", "b": "《礼记·表记》"}, {"t": "君答壹拜。", "b": "《仪礼·士相见礼》"}]}, {"meaning": "——常用于支票、银行票据等,以避免差错或涂改。", "cites": [{"t": "古书及汉人用字,如一之与壹,二之与贰,三之与叁,其义皆同。", "b": "《容斋五笔》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2538wx','握','1','wò','扌','12','','[{"pinyin": "wò", "defs": [{"meaning": "(形声。从手,屋声。本义:攥在手里,执持)。"}, {"meaning": "同本义。", "cites": [{"t": "握,搤持也。", "b": "《说文》"}, {"t": "握,持也。", "b": "《广韵》"}, {"t": "长尺有握。", "b": "《仪礼·乡射礼》"}, {"t": "私握臣手。", "b": "《楚辞·九章·怀少》"}, {"t": "怀瑾握瑜。", "b": "《楚辞·九章·怀沙》"}, {"t": "手握刀。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "握君", "t": "如意的别称"}, {"w": "握篆", "t": "手握官印"}, {"w": "握算", "t": "执算筹以计数。亦指谋划"}, {"w": "握镜", "t": "执持明镜"}, {"w": "握节", "t": "持守符节。不辱君命"}, {"w": "握炭流汤", "t": "握炽炭,蹈沸汤。不畏危难,敢于用命。"}]}, {"meaning": "屈指成拳。", "cites": [{"t": "终日握而手不掜。", "b": "《庄子·庚桑楚》"}], "words": [{"w": "握固", "t": "屈指成拳"}, {"w": "握拳透爪", "t": "形容愤怒到极点。"}]}, {"meaning": "掌握。", "cites": [{"t": "握踣家五十室。", "b": "《管子·戒》"}, {"t": "谨执其柄而固握之。", "b": "《韩非子·主道》"}], "words": [{"w": "握枢", "t": "掌握中枢之权"}, {"w": "握机", "t": "掌握天下的权柄"}, {"w": "握雾拿云", "t": "驾驭云雾"}, {"w": "握柄", "t": "掌权"}, {"w": "握要", "t": "掌握要领"}, {"w": "握守", "t": "把手。"}]}, {"meaning": "控制。", "cites": [{"t": "握乱以治天下。", "b": "皮日休《原化》"}]}, {"meaning": "用同“捂(wǔ”)。遮盖。", "cites": [{"t": "[黛玉] 说着,便两手握起脸来。", "b": "《红楼梦》"}]}, {"meaning": "一把的容量。", "cites": [{"t": "贻我握椒。", "b": "《诗·陈风》"}]}, {"meaning": "一拳的长度。", "cites": [{"t": "宗朝之牛角握。", "b": "《礼记·王制》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2539wx','搔','1','sāo','扌','12','','[{"pinyin": "sāo", "defs": [{"meaning": "(形声。从手,蚤声。本义:用指甲轻刮)。"}, {"meaning": "同本义。", "cites": [{"t": "搔,括也。", "b": "《说文》"}, {"t": "而敬仰搔之。", "b": "《礼记·内则》。注:“摩也。”"}, {"t": "足可搔而绝。", "b": "《汉书·枚乘传》。集注:“谓抓也。”"}, {"t": "白头搔更短,浑欲不胜簪。", "b": "杜甫《春望》"}], "words": [{"w": "搔背", "t": "以指甲搔脊背"}, {"w": "搔掐", "t": "以指甲抓刮"}, {"w": "搔扪", "t": "爬搔抚摸"}, {"w": "搔摸", "t": "呵痒"}, {"w": "搔首", "t": "爬搔头部"}, {"w": "搔耙", "t": "以指爪或他物抓刮爬梳。"}]}, {"meaning": "骚扰;骚乱。", "cites": [{"t": "残贼天下,万民搔动。", "b": "《淮南子·兵略训》"}, {"t": "吴起长兵攻取,楚人搔动,相与泣悼王。", "b": "《盐铁论·非鞅》"}, {"t": "所在搔扰,更为烦苛。", "b": "《三国志·陆凯传》"}], "words": [{"w": "搔动", "t": "骚动;扰乱"}, {"w": "搔扰", "t": "动乱不安,扰乱"}, {"w": "搔搔", "t": "忧虑的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2540wx','揉','1','róu','扌','12','','[{"pinyin": "róu", "defs": [{"meaning": "(形声。从手, 柔声。本义: 使木弯曲或伸直)。"}, {"meaning": "同本义。", "cites": [{"t": "揉木为耒。", "b": "《易·系辞下》"}, {"t": "揉辐必齐。", "b": "《考工记·轮人》"}], "words": [{"w": "揉辐", "t": "烤木使直,以作车轴"}, {"w": "揉斫", "t": "砍削烤揉"}, {"w": "揉木为耒", "t": ""}]}, {"meaning": "驯服。", "cites": [{"t": "揉此万邦,闻于四国。", "b": "《诗·大雅·嵩高》"}], "words": [{"w": "揉耳", "t": "顺耳。"}]}, {"meaning": "牵引。", "cites": [{"t": "孤舟倦鵐轧,短缆因牵揉。", "b": "宋·苏轼《新滩阻风》"}]}, {"meaning": "攀援。", "cites": [{"t": "余赤足跳草莽中,揉木缘崖,莲舟不能从。", "b": "《徐霞客游记》"}]}, {"meaning": "混杂。", "cites": [{"t": "帷其纷楺而将落兮。", "b": "宋玉《九辩》"}, {"t": "不相揉杂。", "b": "《世说新语·文学》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2541wx','斯','1','sī','斤','12','','[{"pinyin": "sī", "defs": [{"meaning": "(会意。从斤,其声。其所以盛木柿。斤,斧子。本义:劈;砍)。"}, {"meaning": "同本义。", "cites": [{"t": "斯,析也。", "b": "《说文》"}, {"t": "墓门有棘,斧以斯之。", "b": "《诗·陈风·墓门》"}, {"t": "有斯明享。", "b": "《书·酒诰》。郑注:“析也。”"}, {"t": "厮(斯)舆之卒。", "b": "《汉书·严助传》。注:“析薪者也。”"}]}, {"meaning": "扯裂。", "cites": [{"t": "斯,裂也。", "b": "《广雅》。王念孙疏证:“今俗语犹呼手裂为斯。”"}]}, {"meaning": "分开。", "cites": [{"t": "斯而析之,精至于无伦,大至于不可围。", "b": "《庄子》"}]}, {"meaning": "距离;离开。", "cites": [{"t": "华胥氏之国…不知斯齐国几千万里。", "b": "《列子·黄帝》"}]}, {"meaning": "“斯”假借为“此”,这,这个。", "cites": [{"t": "斯,此也。", "b": "《尔雅·释诂》"}, {"t": "斯言之玷。", "b": "《诗·大雅·抑》"}, {"t": "登斯楼也,则有去国怀乡,忧馋畏讥,满目萧然,感极而悲者矣。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "而毅宗之语公主,亦曰:“若何为生我家?”痛哉斯言。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "斯世", "t": "此世,今世"}, {"w": "斯人", "t": "此人"}, {"w": "生于斯,长于斯", "t": ""}]}, {"meaning": "则。就 ——表示承接上文,得出结论。", "cites": [{"t": "人之性,心有忧丧则悲,悲则哀,哀斯愤,愤斯怒,怒斯动,动则手足不静。", "b": "《淮南子》"}]}, {"meaning": "古时干粗杂活的奴隶或仆役。引申为卑贱。", "cites": [{"t": "旅琐琐,斯其所取灾。", "b": "《易·旅》"}, {"t": "乡官部吏,职斯禄薄。", "b": "《后汉书·左雄传》上疏"}], "words": [{"w": "斯役", "t": "厮役。指干杂事的劳役"}, {"w": "斯养", "t": "即厮养。奴仆。"}]}, {"meaning": "白色。", "cites": [{"t": "有兔斯首,炮之燔之。", "b": "《诗·小雅·瓠叶》"}]}, {"meaning": "表示结构,相当于“之”、“的”。", "cites": [{"t": "秩秩斯干,幽幽南山。", "b": "《诗·小雅·斯干》"}]}, {"meaning": "用在倒装宾语和动词之间,以确指行为的对象,相当于“是”。", "cites": [{"t": "笃公刘,于京斯依。", "b": "《诗·大雅·公刘》"}]}, {"meaning": "用在形容词之后,相当于“然”。", "cites": [{"t": "王赫斯怒,爰整其旅。", "b": "《诗·大雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2542wx','期','1','qī','月','12','','[{"pinyin": "qī", "defs": [{"meaning": "(形声。从月,其声。金文从日,其声。战国古文从日,丌（qí）声。日、月都有表时间的意思。本义:约会,约定)。"}, {"meaning": "同本义。", "cites": [{"t": "期,会也。", "b": "《说文》。段注:“会者,合也,期者,邀约之意,所以为会合也。”"}, {"t": "归妹愆期。", "b": "《易·归妹》"}, {"t": "若旬虚期于月津。", "b": "《管子·侈靡》。注:“匝一月曰期。”"}, {"t": "而不能期月守也。", "b": "《礼记·中庸》"}, {"t": "叔孙旦而立期焉。", "b": "《左传·昭公二十三年》"}, {"t": "与老人期,后何也?", "b": "《史记·留侯世家》"}, {"t": "与友期行。", "b": "《世说新语·方正》"}]}, {"meaning": "又。", "cites": [{"t": "期日中。", "b": ""}, {"t": "期我决斗。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "期要", "t": "约定,预先约定"}, {"w": "期期", "t": "约定期限"}, {"w": "期会", "t": "约期集合;预定期限推行政令"}, {"w": "期约", "t": "约期;约会"}, {"w": "期克", "t": "严格规定时间"}, {"w": "期信", "t": "约定的时间"}, {"w": "期刻", "t": "克期。约定时间。"}]}, {"meaning": "会,会合。", "cites": [{"t": "期于司理。", "b": "《国语·周语》"}, {"t": "言议期命。", "b": "《荀子·正论》"}, {"t": "几万民之期于市者。", "b": "《周礼·司市》"}], "words": [{"w": "期话", "t": "会晤交谈"}, {"w": "期战", "t": "会战。"}]}, {"meaning": "希望。", "cites": [{"t": "良剑期乎断。", "b": "《吕氏春秋·察 今》"}]}, {"meaning": "又。", "cites": [{"t": "不期乎镆铘。", "b": ""}, {"t": "良马期乎千里。", "b": ""}, {"t": "不期骥骜。", "b": ""}, {"t": "百年曰期颐。", "b": "《礼记·曲礼》"}, {"t": "彼于刑者,缚者,非相仇也,期有得耳。", "b": "方苞《狱中杂记》"}], "words": [{"w": "期勖", "t": "寄希望、勉励"}, {"w": "期寄", "t": "期望"}, {"w": "期厉", "t": "期望勉励"}, {"w": "期愿", "t": "期望;愿望。"}]}, {"meaning": "预定的时间;选定的日子;期限。", "cites": [{"t": "星辰者,天之期也。", "b": "《淮南子·天文》"}, {"t": "前期十日。", "b": "《周礼·大宰》"}, {"t": "会天大雨,道不通,度已失期。", "b": "《史记·陈涉世家》"}, {"t": "惟待死期耳。", "b": "清·梁启超《谭嗣同传》"}, {"t": "临期成此大节。", "b": "清·全祖望《梅花岭记》"}, {"t": "五年为期。", "b": "清·龚自珍《病梅馆记》"}, {"t": "死期至矣。", "b": "《聊斋志异·促织》"}], "words": [{"w": "工期", "t": "工程的期限"}, {"w": "过期", "t": "超过期限"}, {"w": "约期", "t": "约定日期"}, {"w": "刑期", "t": "服刑的期限"}, {"w": "任期", "t": "担任职务的法定期限"}, {"w": "期契", "t": "誓约,约期"}, {"w": "期节", "t": "时节"}, {"w": "期质", "t": "寿命"}, {"w": "期程", "t": "时间;时间和路程。"}]}, {"meaning": "极,限度。", "cites": [{"t": "征敛无期。", "b": "《吕氏春秋·怀宠》"}], "words": [{"w": "期程", "t": "行旅的时日路程"}, {"w": "期度", "t": "限度,法度。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2543wx','欺','1','qī','欠','12','','[{"pinyin": "qī", "defs": [{"meaning": "(形声。从欠,其声。“欠”与出气、说话有关。本义:欺骗)。"}, {"meaning": "同本义。", "cites": [{"t": "欺,诈欺也。", "b": "《说文》"}, {"t": "仁义修立谓之任,反任为欺。", "b": "《贾子道术》"}, {"t": "禄不遂行兹谓欺。", "b": "《京房易传》"}, {"t": "徒见欺。", "b": "《史记·廉颇蔺相如列传》"}]}, {"meaning": "又。", "cites": [{"t": "尚不相欺。", "b": ""}, {"t": "甚矣哉为欺也。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "又。", "cites": [{"t": "世之为欺者。", "b": ""}], "words": [{"w": "欺诳", "t": "欺瞒"}, {"w": "欺上罔下", "t": "对上欺骗,对下隐瞒"}, {"w": "欺诞", "t": "夸大欺骗"}, {"w": "欺谩", "t": "欺骗"}, {"w": "欺三瞒四", "t": "隐蔽实情欺骗他人"}, {"w": "欺天罔人", "t": "骗天骗人"}, {"w": "欺天罔地", "t": "欺骗天地。极言人之背理昧心"}, {"w": "欺心", "t": "自己欺骗自己心怀不轨,起坏心思"}, {"w": "欺君罔上", "t": "欺骗蒙蔽君上。"}]}, {"meaning": "欺诈,用狡猾奸诈的手段骗人。", "cites": [{"t": "苏秦欺寡人。", "b": "《战国策·秦策》。注:“诈也。”"}, {"t": "欺诬诈伪也。", "b": "《荀子·性恶》。注:“诳也。”"}], "words": [{"w": "欺谬", "t": "欺诈背信"}, {"w": "欺猾", "t": "欺诈奸猾"}, {"w": "欺罔", "t": "诈骗迷惑"}, {"w": "欺诡", "t": "欺诈"}, {"w": "欺弊", "t": "欺诈蒙骗。"}]}, {"meaning": "欺压,欺侮。", "cites": [{"t": "南村群童欺我老无力,忍能对面为盗贼。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "欺藐", "t": "欺负小看"}, {"w": "仗势欺人;欺蔑", "t": "欺负蔑视"}, {"w": "欺傲", "t": "欺侮轻慢"}, {"w": "欺枉", "t": "欺负。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2544wx','联','1','lián','耳','12','','[{"pinyin": "lián", "defs": [{"meaning": "(会意。从耳,从丝。战国文字,中间是耳,两边是丝相联。本义:连结)。"}, {"meaning": "同本义。", "cites": [{"t": "聯,连也。从耳,耳连于颊也。从糸,糸连不绝也。会意。", "b": "《说文》。段注:“周人用联字,汉人用连字,古今字也。”"}, {"t": "三曰官联,以会官治。", "b": "《周礼·天官·大宰》。司农注:“连事通职,相佐助也。”"}, {"t": "聯,聯绵不绝也。", "b": "《声类》。按,凡联续、联合、牵联、结联字,经传皆以连为之。"}, {"t": "联袂度危桥,萦回出林杪。", "b": "柳宗元《与崔策登西山》"}], "words": [{"w": "联垂", "t": "一种发式。周围头发梳成许多根细辫子"}, {"w": "联襟", "t": "即连襟。姊妹丈夫之间的亲戚关系"}, {"w": "联缀", "t": "连系,联集在一块"}, {"w": "联珠", "t": "连串的珍珠"}, {"w": "联华", "t": "花开并蒂"}, {"w": "联裾", "t": "联袂。"}]}, {"meaning": "联合;联系。", "cites": [{"t": "臣恐羌复结联他种,宜未及然为之备。", "b": "《汉书·赵充国传》"}, {"t": "三曰联兄弟。", "b": "《周礼·大司徒》。注:“犹合也。”"}, {"t": "联名请益王即位。", "b": "清·吴研人《痛史》"}]}, {"meaning": "缝。", "cites": [{"t": "[宋敦]穿了一件新联的洁白湖绸道袍。", "b": "明·冯梦龙《警世通言》"}], "words": [{"w": "一件新联的道袍", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2545wx','葫','1','hú','艹','12','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从芔,胡声。本义:蔬菜名。即“大蒜”)。", "cites": [{"t": "蒜有大小,大蒜为葫,小蒜为蒜。", "b": "《尔雅翼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2546wx','散','1','sǎn sàn','攵','12','','[{"pinyin": "sǎn", "defs": [{"meaning": "逍遥,懒散。", "cites": [{"t": "庸众驽散。", "b": "《荀子·脩身》。注:“散,不拘检者也。”"}], "words": [{"w": "懒散;散人", "t": "闲散无用或不为世用的人。后多指隐士"}, {"w": "散袒", "t": "假日;消闲"}, {"w": "散旦", "t": "散弹,散诞。舒散;不受拘束"}, {"w": "散适", "t": "闲适"}, {"w": "散闲", "t": "消遥自在,无拘无束"}, {"w": "散宕", "t": "放逸"}, {"w": "散懒", "t": "精神松散,行动散漫。"}]}, {"meaning": "潇洒;洒脱。", "cites": [{"t": "王夫人神情散朗,故有林下风气。", "b": "《世说新语》"}], "words": [{"w": "散朗", "t": "飘逸爽朗。"}]}, {"meaning": "挂名职务,没有或很少有工作却可以领工资。", "cites": [{"t": "初,晋世散骑常持选望甚重,与侍中不异,其后职任闲散,用人渐轻。", "b": "《宋书·孔觊传》"}], "words": [{"w": "散位", "t": "闲散的职位"}, {"w": "散外", "t": "闲散而无一定职守的官职"}, {"w": "散地", "t": "闲散之地。多指闲散的官职"}, {"w": "散男", "t": "无职守或封邑的男爵"}, {"w": "散役", "t": "没有固定职事的差役"}, {"w": "散官", "t": "有官名而无固定职事之官。"}]}, {"meaning": "杂乱;错杂。", "cites": [{"t": "散入珠帘湿罗幕,狐裘不暖锦衾薄。", "b": "唐·岑参《白雪歌送武判官归京》"}], "words": [{"w": "散迹", "t": "行踪不定"}, {"w": "散散的", "t": "无定向,杂乱"}, {"w": "散紊", "t": "散乱"}, {"w": "散殊", "t": "各不相同"}, {"w": "散生日", "t": "散寿。通常的小生日,区别于逢五、逢十的整生日"}, {"w": "散东家", "t": "百戏杂耍艺人"}, {"w": "散名", "t": "散杂的名称。"}]}, {"meaning": "零碎;不集中的。", "cites": [{"t": "已而夕阳在山,人影散乱,太守归而宾客从也。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "散盐", "t": "粉末盐"}, {"w": "散钱", "t": "零散的钱币"}, {"w": "散滞", "t": "遗留下来的零碎物品"}, {"w": "散碎", "t": "零碎"}, {"w": "散处", "t": "分散居住"}, {"w": "散犯", "t": "单独或零散监禁的囚犯"}, {"w": "散茶", "t": "未压制成块、成片的茶"}, {"w": "散户", "t": "零星小户。"}]}, {"meaning": "粗疏 [careless;inatten-tive］。如：散落(疏忽)；散拙(散漫粗疏)。"}, {"meaning": "药粉。", "cites": [{"t": "与散两钱服之。", "b": "《后汉书·华佗传》"}], "words": [{"w": "平胃散;麻沸散;散子", "t": "药面儿。"}]}, {"meaning": "姓。"}]}, {"pinyin": "sàn", "defs": [{"meaning": "(本义:分散)。"}, {"meaning": "同本义。", "cites": [{"t": "散,杂肉也。", "b": "《说文》"}, {"t": "漆叶青黏散。谓药,石为屑杂和也。", "b": "《后汉书·华陀传》"}, {"t": "散木也。", "b": "《庄子·人间世》。注:“不在可用之数曰散木。”"}, {"t": "于是从散约败,争割地而赂秦。", "b": "汉·贾谊《过秦论》"}, {"t": "未及见贼而士卒离散。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "乌云散了;四散", "t": "向四面分散"}, {"w": "散盘", "t": "散伙"}, {"w": "散走", "t": "四散奔逃"}, {"w": "散佚", "t": "散失"}, {"w": "散没", "t": "分散隐没"}, {"w": "散众", "t": "不专门跟随某一主人或专门负责某事的杂役"}, {"w": "散亡", "t": "分散逃亡"}, {"w": "散叛", "t": "离散背叛"}, {"w": "散流", "t": "流体四散而流"}, {"w": "散涣", "t": "形容水四散而流。"}]}, {"meaning": "散发,使分散。", "cites": [{"t": "离散天下之子女,以博我一人之产业。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "散福", "t": "分食祭祀后的食品,布福"}, {"w": "散子", "t": "撒种"}, {"w": "散灰扃户", "t": "在地上撒灰,将门户关锁"}, {"w": "散花", "t": "使花朵飘散"}, {"w": "散金", "t": "散发钱财"}, {"w": "散传", "t": "分支传播"}, {"w": "散振", "t": "为救济人而分发财物"}, {"w": "散配", "t": "分发"}, {"w": "散财", "t": "分发财物"}, {"w": "散赡", "t": "散发财务以接济别人"}, {"w": "散积", "t": "散发所积存的财务"}, {"w": "散赐", "t": "分赐。"}]}, {"meaning": "敞开。", "cites": [{"t": "欲写,先散怀抱,任情恣情,然后书之。", "b": "蔡邕《笔论》"}], "words": [{"w": "散衣襟", "t": ""}]}, {"meaning": "排遣。", "cites": [{"t": "[以]虫篆散忧乐。", "b": "鲍照《蜀四贤》"}], "words": [{"w": "散散儿", "t": "散散心"}, {"w": "散愁;散荡", "t": "散心,解闷"}, {"w": "散适", "t": "走动散心"}, {"w": "散想", "t": "舒散心怀"}, {"w": "散虑", "t": "排遣忧愁。"}]}, {"meaning": "逃,逃走。", "cites": [{"t": "壮者散而之四方。", "b": "《孟子·梁惠王下》"}]}, {"meaning": "放,放牧。", "cites": [{"t": "马散之华山之阳。", "b": "《礼记·乐记》"}]}, {"meaning": "杂乱,纷乱。", "cites": [{"t": "不与物散,粹之至也。", "b": "《淮南子·原道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2547wx','惹','1','rě','心','12','','[{"pinyin": "rě", "defs": [{"meaning": "(形声。从心,若声。本义:招引)。"}, {"meaning": "同本义。", "cites": [{"t": "春风不为吹愁去,春日偏能惹恨长。", "b": "何逊《九日侍宴乐游苑》"}], "words": [{"w": "惹口面", "t": "惹麻烦"}, {"w": "惹邪", "t": "魅人"}, {"w": "惹起", "t": "引起"}, {"w": "惹口舌", "t": "引起口角是非。"}]}, {"meaning": "引起。", "cites": [{"t": "到处顽耍,惹的乡下孩子们三五成群跟着他笑。", "b": "《儒林外史》"}, {"t": "只因清明都来西湖上闲玩,惹出一场事来。", "b": "《清平山堂话本·西湖三塔记》"}]}, {"meaning": "沾染;染上。", "cites": [{"t": "二月杨花轻复微,春风摇荡惹人衣。", "b": "唐·薛涛《柳絮》"}, {"t": "晓随天仗入,暮惹御香归。", "b": "岑参《寄左省杜拾遗》"}, {"t": "时时勤拂拭,勿使惹尘埃。", "b": "慧能《六祖坛经·自序品》"}]}, {"meaning": "牵引。", "cites": [{"t": "古竹老梢惹碧云,茂陵归卧叹清贫。", "b": "唐·李贺《昌谷北园新笋四首》"}]}, {"meaning": "牵挂。", "cites": [{"t": "阿几时教我腹内无烦恼,心上无萦惹。", "b": "元·关汉卿《拜月亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2548wx','葬','1','zàng','艹','12','','[{"pinyin": "zàng", "defs": [{"meaning": "(会意。小篆字形。从“死”,在“茻”(mǎng)中,“一”其中,所以荐之。指人死后盖上草席埋藏在丛草中。荐,草席覆盖。本义:人死用草覆盖埋葬,后用棺木埋入土中)。"}, {"meaning": "同本义。", "cites": [{"t": "葬,臧也。", "b": "《说文》"}, {"t": "葬也者,藏也。", "b": "《礼记·檀弓》"}, {"t": "故葬埋敬藏其形也。", "b": "《荀子·礼论》"}, {"t": "赐钱二百万以葬。", "b": "《汉书·李广苏建传》"}, {"t": "分其汤肉葬之。", "b": "晋·干宝《搜神记》"}, {"t": "而卒葬之。", "b": "宋·王安石《游褒禅山记》"}, {"t": "以衣冠葬之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "葬堂", "t": "为古代我国南方少数民族处置死者遗骨的一种方式"}, {"w": "葬式", "t": "葬礼"}, {"w": "葬虞", "t": "葬礼和虞祭。虞祭行于葬日,故用“葬虞”借指下葬的日期。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2549wx','募','1','mù','力','12','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从力,莫声。本义:招募;征召) 同本义。", "cites": [{"t": "募,广求也。", "b": "《说文》"}, {"t": "招延募选。", "b": "《荀子·议兵》"}, {"t": "谨募选阅材货之上。", "b": "《荀子·王制》。注:“招也。”"}, {"t": "安集吏民,顺俗而教,简募良材,以备不虞。", "b": "《吴子》"}], "words": [{"w": "募选", "t": "从应募的人中选择合适的人"}, {"w": "募缘", "t": "化缘"}, {"w": "募召", "t": "招募"}, {"w": "募民", "t": "征募民众"}, {"w": "募格", "t": "募人从军,杀敌的赏格。"}]}, {"meaning": "假借为“膜”。", "cites": [{"t": "募原之间,留著于脉。", "b": "《灵枢·百病始生》"}, {"t": "治之以胆募俞。", "b": "《素问·奇病论》。注:“胸腹曰募。”"}], "words": [{"w": "募俞", "t": "指人体胸腹部的募穴和背脊部的俞穴,皆为脏腑经气结聚输注之处"}, {"w": "募原", "t": "中医泛指隔间及肠胃之外脂膜的部位。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2550wx','葛','1','gé gě','艹','12','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从艸,曷(hé)声。本义:一种植物,纤维可以织布)。"}, {"meaning": "葛布。指以葛为原料制成的布、衣、带等。", "cites": [{"t": "卒时,佥都御史王用汲入视,葛帏敞籯,有寒士所不堪者,因泣下醵金为敛。", "b": "《明史·海瑞传》"}], "words": [{"w": "葛巾", "t": "用葛布缝制的头巾"}, {"w": "葛衣", "t": "葛布制成的衣服"}, {"w": "葛帔", "t": "用葛制成的披肩"}, {"w": "葛纱", "t": "以葛的纤维织成的纱布。"}]}, {"meaning": "夏衣的代称。", "cites": [{"t": "一葛一裘经岁,一钵一瓶终日,老子旧家风。", "b": "辛弃疾《水调歌头》"}, {"t": "父母岁有裘葛之遗,无冻馁之患矣。", "b": "明·宋濂《送东阳马生序》"}]}]}, {"pinyin": "gě", "defs": [{"meaning": "", "words": [{"w": "葛天氏", "t": "葛天。传说中的远古帝名。一说为远古时期的部落名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2551wx','董','1','dǒng','艹','12','','[{"pinyin": "dǒng", "defs": [{"meaning": "(形声。从艸,重声。①本义:草名,即鼎蕫。②督察)。"}, {"meaning": "监督;督察。", "cites": [{"t": "董之用威。", "b": "《书·大禹谟》。传:“董,督也。”"}, {"t": "董逋逃。", "b": "《左传·文公六年》"}, {"t": "董之以武师。", "b": "《左传·昭公十年》"}, {"t": "出则监察而董是非。", "b": "《后汉书·陈忠传》"}, {"t": "虽董之以严刑,振之以威怒,终苟免而不怀仁,貌恭而不心服。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "董正", "t": "监督纠正"}, {"w": "董统鹰扬", "t": "为督察纲纪而大展雄才"}, {"w": "董治", "t": "监督管理"}, {"w": "董摄", "t": "监督治理。"}]}, {"meaning": "正,守正。", "cites": [{"t": "董,正也。", "b": "《尔雅·释诂》"}, {"t": "随人使少师董成。", "b": "《左传·桓公六年》"}, {"t": "而辱使董振择之。", "b": "《左传·昭公三年》"}, {"t": "余将董道而不豫兮,固将重昏而终身。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "董道", "t": "守正道"}, {"w": "董役", "t": "正其事理"}, {"w": "董齐", "t": "征伐之使归一统。"}]}, {"meaning": "古地名。春秋时晋地,在今山西省万荣县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2552wx','葡','1','pú','艹','12','','[{"pinyin": "pú", "defs": [{"meaning": "葡萄糖的简称。"}, {"meaning": "葡萄。", "cites": [{"t": "落叶藤本植物，果实圆形或椭圆形，味甜可食，亦可酿酒；", "b": ""}, {"t": "这种植物的果实或像其形者，如\\"葡葡干\\"。\\"葡葡酒\\"。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2553wx','敬','1','jìng','攵','12','','[{"pinyin": "jìng", "defs": [{"meaning": "(会意。从攴(pū),以手执杖或执鞭,表示敲打,从苟(jí),有紧急、急迫之义。本义:恭敬;端肃。恭在外表,敬存内心)。"}, {"meaning": "同本义。", "cites": [{"t": "敬,肃也。", "b": "《说文》"}, {"t": "毋不敬何允。", "b": "《礼记·曲礼》。注:“在貌为恭,在心为敬。”"}, {"t": "宾客主恭,祭祀主敬。", "b": "《礼记·少仪》"}, {"t": "入门主敬,升堂主慎。", "b": "《仪礼·聘礼》"}, {"t": "敬德之聚也。", "b": "《左传·僖公二十三年》"}, {"t": "敬诺。", "b": "《战国策·赵策》"}, {"t": "敬受命。", "b": "《史记·陈涉世家》"}, {"t": "敬进如姬。", "b": "《史记·魏公子列传》"}, {"t": "敬闻命关。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "敬让", "t": "恭敬谦让"}, {"w": "敬诚缉熙", "t": "恭敬诚实而光明"}, {"w": "敬身", "t": "施礼"}, {"w": "敬慎", "t": "恭敬谨慎。"}]}, {"meaning": "慎重地对待,不怠慢不苟且;敬谨。", "cites": [{"t": "敬,警也,恒自肃警也。", "b": "《释名·释言语》"}, {"t": "既敬既戒。", "b": "《诗·大雅·常武》。笺:“敬之言警也。”"}, {"t": "敬事而信。", "b": "《论语·学而》"}, {"t": "居敬而行简。", "b": "《论语·雍也》"}, {"t": "慎始而敬之。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "敬事", "t": "谨慎做事;恭谨伺侯"}, {"w": "敬信", "t": "慎重而守信"}, {"w": "敬独", "t": "在独处时能谨慎不苟"}, {"w": "敬逊", "t": "敬慎谦逊"}, {"w": "敬虔", "t": "庄敬虔诚"}, {"w": "敬明", "t": "谨慎严明。"}]}, {"meaning": "尊重,尊敬。", "cites": [{"t": "严大国之威以修敬也。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "敬贤礼士。", "b": "《资治通鉴》"}, {"t": "北虽貌敬。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "敬学", "t": "尊重学问"}, {"w": "敬服", "t": "敬伏。敬重佩服"}, {"w": "敬事后食", "t": "先考虑国事然后考虑自己"}, {"w": "敬老", "t": "尊敬老人"}, {"w": "敬老慈幼", "t": "尊敬老人,慈爱儿童"}, {"w": "敬老怜贫", "t": "尊敬年长的人,怜悯贫困的人。"}]}, {"meaning": "自愿转让毋需抵偿的东西,捐赠或赠的礼品。", "cites": [{"t": "于库房取书仪十两,送与苏雨为程敬。", "b": "冯梦龙《警世通言》"}], "words": [{"w": "节敬;茶敬", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2554wx','葱','1','cōng','艹','12','','[{"pinyin": "cōng", "defs": [{"meaning": "(形声。从艸,悤(cōng)声。本义:葱,一种蔬菜)。"}, {"meaning": "有圆筒状中空叶的植物之一 。多年生草本植物。叶子圆筒形,中空,鳞茎圆柱形,开小白花。种类很多。可作蔬菜或调味品,亦可作药用。", "cites": [{"t": "蔥,蔥菜也。", "b": "《说文》"}, {"t": "葱有冬春二种,有胡葱、木葱、山葱,二月别小葱,六月别大葱,夏葱曰小,冬葱曰大。", "b": "《齐民要术》"}, {"t": "指如削葱根,口如含朱丹。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2555wx','蒋','1','jiǎng','艹','12','','[{"pinyin": "jiǎng", "defs": [{"meaning": "(形声。从艸,将声。(jiāng)本义:植物名。即“茭白”)。"}, {"meaning": "古国名 。姬姓,始封之君为周公之子,在今河南固始县。一说在今河南光山,春秋时灭于楚。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2556wx','蒂','1','dì','艹','12','','[{"pinyin": "dì", "defs": [{"meaning": "(形声。从艸,帝声。本义:花、叶或瓜、果与枝茎连结的部分)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2557wx','落','1','luò là lào luō','艹','12','','[{"pinyin": "luò", "defs": [{"meaning": "(形声。从艸,洛声。本义:叶落,花落)。"}, {"meaning": "同本义。", "cites": [{"t": "落,凡草曰零,木曰落。", "b": "《说文》"}, {"t": "草木黄落。", "b": "《礼记·月令》"}, {"t": "及荣华之未落兮。", "b": "《楚辞·离骚》"}, {"t": "唯草木之零落兮。", "b": ""}, {"t": "桑之未落,其叶沃若。", "b": "《诗·卫风·氓》"}, {"t": "人闲桂花落。", "b": "唐·王维《鸟鸣涧》"}, {"t": "落英缤纷。", "b": "晋·陶渊明《桃花源记》"}, {"t": "叶落树下。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "纷堕如落叶。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "落红", "t": "落花"}, {"w": "落花媒人", "t": "不正当男女关系的撮合人"}, {"w": "落英缤纷", "t": "落地零乱的样子"}, {"w": "落木", "t": "落叶"}, {"w": "落花时节", "t": "指暮春季节。"}]}, {"meaning": "泛指下落;下坠。", "cites": [{"t": "山高月小,水落石出。", "b": "苏轼《后赤壁赋》"}, {"t": "牙齿半落左耳聋。", "b": "杜甫《复阴》"}, {"t": "飞流直下三千尺,疑是银河落九天。", "b": "李白《望庐山瀑布》"}, {"t": "其印自落。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "鸡鸣月落。", "b": "明·魏禧《大铁椎传》"}, {"t": "贼应声落。", "b": ""}], "words": [{"w": "贼应声落;落土", "t": "指太阳或月亮下山"}, {"w": "落山", "t": "指太阳下山"}, {"w": "落羽", "t": "指受伤坠地的鸟"}, {"w": "涨落;落生", "t": "射落生灵,即猎取鸟类"}, {"w": "落帽", "t": "帽子为风吹落"}, {"w": "落絮", "t": "落下的丝絮。比喻飘落的柳絮;比喻飘落的雪花"}, {"w": "落潮", "t": "退潮"}, {"w": "落雁沉魚", "t": "形容女子貌美所用之詞"}, {"w": "落坐", "t": "坐下"}, {"w": "落台", "t": "下台;了結"}, {"w": "落地罩", "t": "可以坠到地面的帷幕。"}]}, {"meaning": "掉进。", "cites": [{"t": "不可落于敌人之手。", "b": "清·全祖望《梅花岭記》"}, {"t": "几落贼手死。", "b": "宋·文天祥《诚意伯刘文成公文集》"}], "words": [{"w": "落局", "t": "落入骗局"}, {"w": "落夜", "t": "入夜。"}]}, {"meaning": "耽误;荒废。", "cites": [{"t": "夫子阖行邪?无落吾事。", "b": "《庄子·天地》"}], "words": [{"w": "落索", "t": "萧索"}, {"w": "落然", "t": "荒废的样子。"}]}, {"meaning": "衰败。", "cites": [{"t": "盛而不落者,未之有也。", "b": "《管子·宙合》"}], "words": [{"w": "落漠", "t": "落拓,潦倒"}, {"w": "落羽", "t": "羽毛摧落。比喻失意"}, {"w": "落薄", "t": "落魄;潦倒失意"}, {"w": "落拓", "t": "落魄;穷困失意;放荡不羁"}, {"w": "落膘", "t": "指牲畜变瘦。"}]}, {"meaning": "止息;停留;亦指留下。", "cites": [{"t": "众婆子步下围随至一垂花门前落下。", "b": "《红楼梦》。又如:落市(歇市,停止营业);落草(停止);落夜(住宿,过夜)"}]}, {"meaning": "得到。", "cites": [{"t": "俺若是一心行正,落一个万古名扬。", "b": "《射柳捶丸》"}], "words": [{"w": "落不的", "t": "得不到"}, {"w": "落来", "t": "得到某种结果"}, {"w": "落定", "t": "成为定局"}, {"w": "落保", "t": "担保。"}]}, {"meaning": "古代宫室建成时举行祭礼。", "cites": [{"t": "楚子成章华之台,愿与诸侯落之。", "b": "《左传·昭公七年》"}], "words": [{"w": "落成", "t": ""}]}, {"meaning": ""}, {"meaning": "用网状物兜住。", "cites": [{"t": "落马首,穿牛鼻,是谓人。", "b": "《庄子·秋水》"}]}, {"meaning": "中医的经络系統。", "cites": [{"t": "原人血脉经落骨髓。", "b": "《汉书·艺文志》"}]}, {"meaning": "衰败;零落;稀疏。", "cites": [{"t": "家贫,宾客益落。", "b": "《史記》"}, {"t": "门前冷落鞍马稀。", "b": "白居易《琵琶行(并序)》"}], "words": [{"w": "落解粥", "t": "极稀的粥"}, {"w": "落然", "t": "冷落"}, {"w": "落堕", "t": "零落"}, {"w": "落驿", "t": "稀疏,零落。"}]}, {"meaning": "居处。", "cites": [{"t": "矗不知几千万落。", "b": "唐·杜枚《阿房宫赋》"}], "words": [{"w": "院落;部落;村落", "t": ""}]}]}, {"pinyin": "là", "defs": [{"meaning": "丢了,漏掉", "words": [{"w": "丢三落四", "t": ""}]}, {"meaning": "忘了拿,没注意取"}, {"meaning": "落后"}, {"meaning": "没有上,误"}]}, {"pinyin": "lào", "defs": [{"meaning": "捞,赚。", "cites": [{"t": "把东西开个花账儿,落他二三两银子。", "b": "《西游记》"}], "words": [{"w": "落褒贬", "t": "落下不是"}, {"w": "落亏欠", "t": "欠下人情债。"}]}]}, {"pinyin": "luō", "defs": [{"meaning": "[方言]形容态度大方。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2558wx','韩','1','hán','韦','12','','[{"pinyin": "hán", "defs": [{"meaning": "(形声。从韦,倝(gàn)声。从“韦”,取围绕,周匝之义。本义:井垣)。"}, {"meaning": "井上的木栏。", "cites": [{"t": "韩,井垣 也。", "b": "《说文》"}]}, {"meaning": "古国名。"}, {"meaning": "中国周朝时的一个诸侯国,在今山西省韩城县。"}, {"meaning": "战国七雄之一。后为秦所灭。今山西省东部和河南省西北部。"}, {"meaning": "1897—1910年朝鲜的国名 ,1910年被日本吞并。第二次世界大战后,朝鲜南半部称“大韩民国”,简称“韩国”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2559wx','朝','1','cháo zhāo','月','12','','[{"pinyin": "cháo", "defs": [{"meaning": "(会意。甲骨文字形,从日在草中,从月。字象太阳已出草中而月亮尚未隐没形。(zhāo)本义:早晨)。"}, {"meaning": "早晨省亲,子、媳向父母、公婆请安。", "cites": [{"t": "晨见曰朝…子于父母、妇于舅姑皆是。", "b": "《说文解字注笺》"}, {"t": "昧爽而朝。(昧爽:黎明。朝:省视父母)", "b": "《礼记·内则》"}, {"t": "邦君诸侯,莫肯朝夕。(夕:指晚上省视帝王)", "b": "《诗·小雅·雨无止》"}]}, {"meaning": "朝见,封建时代臣见君。", "cites": [{"t": "盛服将朝,尚早,坐而假寐。", "b": "《左传·宣公二年》"}, {"t": "相如每朝时,常称病。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "燕、赵、韩、魏闻之,皆朝于齐。", "b": "《战国策·齐策》"}, {"t": "割地而朝者三十有六国。", "b": "《韩非子·五蠹》"}]}, {"meaning": "使…朝见。", "cites": [{"t": "欲辟土地,朝秦楚。", "b": "《孟子·梁惠王上》"}, {"t": "武丁朝诸侯有天下。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "朝冠", "t": "百官上朝时戴的帽子"}, {"w": "朝参", "t": "上朝参谒"}, {"w": "朝天", "t": "拜见天子、天帝。"}]}, {"meaning": "泛指拜见。", "cites": [{"t": "常先朝陵夫人上食,然后敢归家。", "b": "《史记·张丞相列传》"}]}, {"meaning": "会聚;召。", "cites": [{"t": "耆老皆朝于庠。", "b": "《礼记·王制》"}]}, {"meaning": "朝廷。古时亦称:朝堂,朝宁,朝冶,朝苑,朝省,朝家。", "cites": [{"t": "赐带剑履上殿,入朝不趋。(趋:快步走。)", "b": "《史记·萧相国世家》"}, {"t": "易之以百金,献诸朝。", "b": "明·刘基《郁离子·千里马篇》"}], "words": [{"w": "朝国", "t": "朝廷,国家"}, {"w": "朝典", "t": "朝廷的典章礼制"}, {"w": "朝使", "t": "朝廷派出的使者。"}]}, {"meaning": "朝代,指同一姓帝王连续继承王位的时代。", "cites": [{"t": "南朝四百八十寺,多少楼台烟雨中。", "b": "杜牧《江南春杂句》"}], "words": [{"w": "唐朝;清朝", "t": ""}]}, {"meaning": "某一个帝王的统治时期。", "cites": [{"t": "三顾频烦天下计,两朝开济老臣心。(两朝:刘备和刘禅统治时期。)", "b": "杜甫《蜀相》"}, {"t": "当是时,本朝定鼎改元二年矣。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "三朝元老;一朝天子一朝臣", "t": ""}]}, {"meaning": "朝班,古代群臣朝见帝王时按官品分班排列的位次 。又称:朝列,朝次,朝序,朝伦;朝部;朝著。"}, {"meaning": "表示动作针对的方向。", "cites": [{"t": "银烛朝天紫陌长,禁城春色晓苍苍。", "b": "唐·贾至《早朝大明宫呈两省僚友》"}], "words": [{"w": "朝前看;大门朝东开;应该朝好的方面想", "t": ""}]}]}, {"pinyin": "zhāo", "defs": [{"meaning": "(会意。甲骨文字形,上下为“莽”字,中间为“日”,“月”。表明太阳已从草丛升起,月亮还未落,是早晨。本义:指日出到早餐时,泛指早晨)。"}, {"meaning": "同本义。", "cites": [{"t": "朝,旦也。", "b": "《说文》"}, {"t": "朝,早也。", "b": "《尔雅·释诂》"}, {"t": "自朝至于日中。", "b": "《书·无逸》"}, {"t": "周人祭日以朝及誾。", "b": "《礼记·祭义》。注:“朝,日出时也。”"}, {"t": "温恭朝夕,执事有恪。", "b": "《诗·商颂·那》"}, {"t": "有时朝发白帝,暮到江陵。", "b": "《水经注·江水》"}, {"t": "朝露待日晞。", "b": "《乐府诗集·长歌行》"}, {"t": "朝雨浥轻尘。", "b": "唐·王维《送元二使安西》"}, {"t": "朝歌夜弦。(弦:弹琴。)", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "朝雉徒歌", "t": "像早晨的山鸡一样鸣叫高歌"}, {"w": "朝趁暮食", "t": "形容穷苦,早上挣到钱,晚上才得吃"}, {"w": "朝上;朝夕乌", "t": "同“朝夕鸟”。朝去暮归的乌鸦"}, {"w": "朝夕相处", "t": "彼此天天在一起"}, {"w": "朝日", "t": "早晨初升的太阳"}, {"w": "朝旦;朝不及夕", "t": "极言处境危急"}, {"w": "朝升暮合", "t": "谓零碎地籴米。形容生活艰难,勉强度日"}, {"w": "朝成暮遍", "t": "早晨刚写成,晚上就到处流传。形容文章流传迅速"}, {"w": "朝成暮毁", "t": "形容翻新之速"}, {"w": "朝夷暮跖", "t": "早被誉为伯夷,晚被贬作盗跖。形容时论毁誉多变"}, {"w": "朝欢暮乐", "t": "终日欢乐;日夜寻欢作乐"}, {"w": "朝市", "t": "早市。"}]}, {"meaning": "日;天。", "cites": [{"t": "虽与之天下,不能一朝居也。", "b": "《孟子·告子下》"}, {"t": "三战之所亡,一朝而复之。", "b": "《史记·鲁仲连邹阳列传》"}], "words": [{"w": "今朝;明朝", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2560wx','辜','1','gū','辛','12','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从辛,古声。“辛”,是受刑的意思。本义:罪行)。"}, {"meaning": "同本义。", "cites": [{"t": "辜,罪也。", "b": "《说文》。段注:“辜本非常重罪,引申之凡有罪者皆曰辜。”"}, {"t": "民之无辜。", "b": "《诗·小雅·正月》"}, {"t": "无罪无辜。", "b": "《诗·小雅·十月之交》"}, {"t": "天乎无辜。", "b": "《公羊传·宣公六年》"}, {"t": "至齐,见辜人焉。", "b": "《庄子·则阳》"}, {"t": "赏无功之人,罚不辜之民,非所谓明也。", "b": "《韩非子·说疑》"}, {"t": "至海陵,如高沙,常恐无辜死。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "死有余辜;无辜", "t": ""}]}, {"meaning": "灾难,祸害。", "cites": [{"t": "害遍生民,辜及朽骨。", "b": "《汉书》"}]}, {"meaning": "(gù)。原故,原因。", "cites": [{"t": "般纷纷其离此尤兮,亦夫子之辜也。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "惩罚,治罪。", "cites": [{"t": "挟目而辜。", "b": "《说苑·杂言》"}]}, {"meaning": "肢解,分裂肢体。", "cites": [{"t": "杀王之亲者辜之。", "b": "《周礼·秋官·掌戮》"}, {"t": "大罪莫重辜磔于市。", "b": "《韩非子·内储说上》"}], "words": [{"w": "辜磔", "t": "肢解躯体并弃于市的一种酷刑"}, {"w": "辜人", "t": "受辜磔刑弃于市的人。"}]}, {"meaning": "辜负,亏负。", "cites": [{"t": "幸得展张今日翅,不能辜负昔时心。", "b": "唐·白居易《戊申岁暮咏怀》"}], "words": [{"w": "辜恩不报;辜人誓言;辜恩背义", "t": "辜负恩德背弃大义,做出对不起别人的事。"}]}, {"meaning": "专固,垄断。", "cites": [{"t": "初置騄骥监丞,领受郡国调马。豪右辜榷,马匹至二百万。", "b": "《后汉书·灵帝纪》"}], "words": [{"w": "辜较", "t": "垄断,剥夺他人利益"}, {"w": "辜榷", "t": "独占,垄断,专固。"}]}, {"meaning": "(kǔ)。困扰。", "cites": [{"t": "楚与中国侠(挟)而击之,郑罢弊危亡,终身愁辜。", "b": "《春秋繁露·竹林》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2561wx','葵','1','kuí','艹','12','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从艸,癸声。本义:植物名。指“冬葵”,古代主要的蔬菜。《说文》:“菜也。”也指“向日葵”)。"}, {"meaning": "蔬菜名。我国古代重要蔬菜之一。可腌制,称葵菹。", "cites": [{"t": "葵,葵菜也。", "b": "《说文》"}, {"t": "七月亨葵及菽。", "b": "《诗·豳风·七月》"}, {"t": "夏用葵。", "b": "《仪礼·士虞礼记》"}, {"t": "其实葵菹。", "b": "《周礼·醢人》"}], "words": [{"w": "葵倾", "t": "像葵花向日一样地倾慕"}, {"w": "葵藿", "t": "葵花。比喻下级唯上级之命是从。"}]}, {"meaning": "菊科草本植物 。有锦葵、蜀葵、秋葵、向日葵等。", "cites": [{"t": "葵犹能卫其足。", "b": "《左传·成公十七年》"}, {"t": "蔠葵蘩露。", "b": "《尔雅》"}, {"t": "青青园中葵。", "b": "《乐府诗集·长歌行》"}], "words": [{"w": "葵心", "t": "葵花向日而倾,比喻向往思慕之心"}, {"w": "葵心菊脑", "t": "葵心指葵实,菊脑指菊花。"}]}, {"meaning": "假借为“揆”。审度。", "cites": [{"t": "葵,揆也。", "b": "《尔雅》"}, {"t": "乐只君子,天子葵之。", "b": "《诗·小雅·采菽》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2562wx','棒','1','bàng','木','12','','[{"pinyin": "bàng", "defs": [{"meaning": "(形声。从木,奉声。本义:棍,杖)。"}, {"meaning": "同本义。", "cites": [{"t": "人马逼战,刀不如棒。", "b": "《魏书·尔朱荣传》"}], "words": [{"w": "棒糖;棍棒;棒打鸳鸯", "t": "以强硬手段,破坏他人的夫妇关系,或指阻挠男女的婚事。"}]}, {"meaning": "用棍棒打。", "cites": [{"t": "其或迟违,则赤棒棒之。", "b": "《北齐书·琅琊王(萧)俨传》"}], "words": [{"w": "棒杀", "t": "用棍棒打死"}, {"w": "棒毒", "t": "用棒毒打。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2563wx','棱','1','lēng líng','木','12','','[{"pinyin": "lēng", "defs": [{"meaning": "(俗作“楞”和“稜”。形声。从木,夌(líng)声。本义:有四角的木)。"}, {"meaning": "同本义。", "cites": [{"t": "上觚稜而栖金爵。", "b": "班固《西都赋》"}, {"t": "木四方为棱。", "b": "汉·服虔《通俗文》"}]}, {"meaning": "威势。", "cites": [{"t": "威稜憺乎邻国。", "b": "《汉书·李广传》"}, {"t": "刚稜疾恶。", "b": "《后汉书·王允传》。注:“威稜也。”"}], "words": [{"w": "棱光", "t": "威严的目光"}, {"w": "棱眼", "t": "威严的眼睛"}, {"w": "棱棱", "t": "威严的样子。"}]}]}, {"pinyin": "líng", "defs": [{"meaning": "——“穆棱”(Mùlíng):县名。在黑龙江省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2564wx','棋','1','qí','木','12','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从木,其声。本义:古时通称博奕的子为棋) 同本义。", "cites": [{"t": "棊,博棊也。", "b": "《说文》"}, {"t": "五簙或谓之棊。", "b": "《方言》"}, {"t": "故行棊者。", "b": "《淮南子·泰族》。注:“谓六博也。”"}, {"t": "休与之山,其上有石焉,名曰帝台之棋。", "b": "《山海经·中山经》。注;“博棋也。”"}, {"t": "尧造围棊,以教子丹朱,或云舜以子商均愚,故作围棊教之。", "b": "《博物志》"}, {"t": "山出棋置。", "b": "《史记·货殖列传》"}], "words": [{"w": "棋枰", "t": "棋盘"}, {"w": "棋子", "t": "一种干粮"}, {"w": "象棋;国际象棋;围棋;跳棋", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2565wx','椰','1','yē','木','12','','[{"pinyin": "yē", "defs": [{"meaning": "椰子树  一种常绿乔木,树干直立,不分枝。叶子丛生顶部。核果椭圆形,外果皮黄褐色,内果皮为角质的硬壳,果肉白色多汁,含脂肪。果肉可吃,也可榨油。果肉内的汁可做饮料,外果皮和中果皮的纤维可制船缆和刷子,叶子可编席和盖棚。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2566wx','植','1','zhí','木','12','','[{"pinyin": "zhí", "defs": [{"meaning": "(形声。从木,直声。本义:关闭门户用的直木)。"}, {"meaning": "同本义。", "cites": [{"t": "植,户植也。", "b": "《说文》。按,古门外闭,中竖直木,以铁了鸟关之,可加锁者。"}, {"t": "季孙与邑人争门关,决植。", "b": "《墨子·非儒》"}, {"t": "夏屋宫驾,县联房植。", "b": "《淮南子·本经》"}]}, {"meaning": "木柱。", "cites": [{"t": "于四角立植而县。", "b": "《考工记·匠人》注"}, {"t": "城上百步一楼,楼四植,植皆为通舄。", "b": "《墨子》。"}]}, {"meaning": "引申为支柱,柱本。", "cites": [{"t": "井植生梓,而不容瓮,沟植生条,而不容舟。", "b": "《淮南子·览冥》。注:“谓材也。”"}, {"t": "君子谓坚能用法矣,法者国之植也。", "b": "明·冯梦龙《智囊补》"}]}, {"meaning": "特指筑城墙两端所竖的木柱。", "cites": [{"t": "大役,与虑事,属其植。", "b": "《周礼·夏官·大司马》"}]}, {"meaning": "又指悬挂蚕箔的柱子。", "cites": [{"t": "槌,宋、魏、陈、楚、江、淮之间谓之植。", "b": "《方言》"}]}, {"meaning": "(zhì)。志向。", "cites": [{"t": "上无固植。", "b": "《管子·法法》。注:“植,志也。”"}, {"t": "弱颜固植。", "b": "《楚辞·招魂》"}]}, {"meaning": "栽种;种植;生长。", "cites": [{"t": "植,种也。", "b": "《广雅·释地》"}, {"t": "我有田畴,而子产植之。", "b": "《吕氏春秋·乐成》。注:“植,长也。”"}, {"t": "东西植松柏。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "杂兰植桂竹。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "又。", "cites": [{"t": "所手植也。", "b": ""}, {"t": "种植之利。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "植秀", "t": "种植花木"}, {"w": "植林", "t": "植树造林"}, {"w": "植治", "t": "用大量栽培植物的方法治理沙漠"}, {"w": "植养", "t": "培植"}, {"w": "植成", "t": "长成"}, {"w": "植柳", "t": "插柳。"}]}, {"meaning": "立;树立。", "cites": [{"t": "令获者植旌。", "b": "《周礼·田仆》"}, {"t": "植其杖而芸。", "b": "《论语·微子》"}, {"t": "植杖而耘耔。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "植刃道上。", "b": "唐·柳宗元《童区寄传》"}, {"t": "亭亭净植。", "b": "宋·周敦颐《爱莲说》"}, {"t": "植梯接之。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "植行", "t": "谓所立的品行"}, {"w": "植志", "t": "立志"}, {"w": "植弓", "t": "立身"}, {"w": "植表", "t": "树立标竿"}, {"w": "植品", "t": "树立人品,培植好的品质"}, {"w": "植德", "t": "立德"}, {"w": "植操", "t": "树立志向操行。"}]}, {"meaning": "建立。", "cites": [{"t": "其实皆植党营私,为蠹国害民之事。", "b": "顾炎武《日知录》"}], "words": [{"w": "植学", "t": "立学"}, {"w": "植言", "t": "立言"}, {"w": "植礼", "t": "建立礼仪制度"}, {"w": "植义", "t": "植意;立意。"}]}, {"meaning": "竖立。", "cites": [{"t": "诸侯必值耳。", "b": "《淮南子·人世间》"}], "words": [{"w": "植发", "t": "头发竖起"}, {"w": "植发冲冠", "t": "头发直竖,顶起帽子。形容盛怒或踊跃之状"}, {"w": "植鳍", "t": "竖起的鱼鳍。"}]}, {"meaning": "(zhì)。安放,放置。", "cites": [{"t": "植璧秉珪。", "b": "《书·金縢》。疏:“植,古置字。”"}, {"t": "植其杖而芸。", "b": "《论语·微子》"}, {"t": "天下之势倒植矣。", "b": "贾谊《威不信》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2567wx','森','1','sēn','木','12','','[{"pinyin": "sēn", "defs": [{"meaning": "(会意。从林从木。本义:树木丛生繁密)。"}, {"meaning": "同本义。", "cites": [{"t": "森,木多貌。", "b": "《说文》"}, {"t": "林多木长貌。", "b": "《字林》"}, {"t": "森槮柞朴。", "b": "马融《长笛赋》"}, {"t": "弹言鸟于森木。", "b": "左思《蜀都赋》"}], "words": [{"w": "森标", "t": "树丛的顶端"}, {"w": "森木", "t": "高耸繁茂的树木"}, {"w": "森沉", "t": "林木繁茂幽深"}, {"w": "森阴", "t": "林木幽深繁密"}, {"w": "森萃", "t": "茂密"}, {"w": "森朗", "t": "繁密而又清朗。"}]}, {"meaning": "满;罗列。", "cites": [{"t": "其中戈矛森聚,京露其颖。", "b": "《聊斋志异》"}], "words": [{"w": "森布", "t": "繁密排列"}, {"w": "森聚", "t": "聚集,密集。"}]}, {"meaning": "众多,众盛。", "cites": [{"t": "森奉璋以阶列。", "b": "杨雄《甘泉赋》"}, {"t": "百神森其备从兮。", "b": "张衡《思玄赋》。注:“众貌。”"}, {"t": "溪涧树林,森然布列。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "森列", "t": "形容数量众多,如森林一般排列"}, {"w": "森罗", "t": "形容数量众多,如森林一般排列"}, {"w": "森罗宝殿", "t": "迷信传说中阴间阎罗王处理公务的殿堂"}, {"w": "森仗", "t": "众多的仪卫。"}]}, {"meaning": "高耸。峙立。", "cites": [{"t": "秭归正面有一大片铁青色礁石,森然耸立江面。", "b": "《长江三峡》"}], "words": [{"w": "森悚", "t": "因惊惧而耸立"}, {"w": "森立", "t": "耸立;森严地排列"}, {"w": "森森张", "t": "伸张耸竖"}, {"w": "森动", "t": "耸动"}, {"w": "森霄", "t": "直立于云端"}, {"w": "森幻", "t": "高耸而奇幻"}, {"w": "森拱", "t": "高大"}, {"w": "森挺", "t": "高耸直立"}, {"w": "森峭", "t": "高耸峭拔"}, {"w": "森梢", "t": "高耸挺拔。"}]}, {"meaning": "阴沉,幽暗。", "cites": [{"t": "眇默诸境森。", "b": "顾况《游子吟》"}], "words": [{"w": "森敞", "t": "幽暗而宽敞"}, {"w": "森薄", "t": "阴凉逼人"}, {"w": "森岑", "t": "形容幽暗阴冷"}, {"w": "森森森然", "t": "昏眩"}, {"w": "森邃", "t": "幽深"}, {"w": "森寂", "t": "幽深岑寂。"}]}, {"meaning": "森严,严峻。", "cites": [{"t": "快剑长戟森相向。", "b": "杜甫《李潮八分小篆歌》"}], "words": [{"w": "森逼", "t": "森严逼人"}, {"w": "森卫", "t": "警卫森严"}, {"w": "森肃", "t": "森严,严肃"}, {"w": "森凛", "t": "森严可畏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2568wx','焚','1','fén','火','12','','[{"pinyin": "fén", "defs": [{"meaning": "(会意。从火,从林。甲骨文字形,象火烧丛木。古人田猎,为了把野兽从树林里赶出来,就采用焚林的办法。本义:烧山)。"}, {"meaning": "用火烧山林宿草。", "cites": [{"t": "焚,烧田也。", "b": "《说文》"}, {"t": "焚咸丘。", "b": "《公羊传·桓公七年》。传:“焚之者何,樵之也;樵之者何,以火攻也。”"}, {"t": "焚林而田。", "b": "《韩非子·难一》"}]}, {"meaning": "烧。", "cites": [{"t": "焚,烧也。", "b": "《广雅》"}, {"t": "焚如死如弃如。", "b": "《易·离》"}, {"t": "遂从而尽焚之。", "b": "《左传·成公十三年》"}, {"t": "乃焚大槐。", "b": "《庄子·外物》。司马注:“谓霹雳时烧大树也。”"}, {"t": "焚百家之言,以愚黔首。", "b": "汉·贾谊《过秦论》"}, {"t": "焚拜如前人。", "b": "《聊斋志异·促织》"}], "words": [{"w": "玩火者必自焚;焚舟", "t": "烧毁渡船"}, {"w": "焚池", "t": "祭祀时焚化祭品的器物"}, {"w": "焚黄", "t": "烧掉黄表纸。祭告家庙祖坟,祷文写在黄表纸上"}, {"w": "焚灼", "t": "烧、焚烧"}, {"w": "焚帛", "t": "焚烧纸帛。"}]}, {"meaning": "旧时的一种酷刑。用火烧死。", "cites": [{"t": "焚炙忠良。", "b": "《书·泰誓上》"}, {"t": "凡杀其亲者焚之。", "b": "《周礼·掌戮》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2569wx','椅','1','yǐ yī','木','12','','[{"pinyin": "yǐ", "defs": [{"meaning": "(形声。从木,奇声。①本义:木名。即山桐子。《诗·銿风·定之方中》:“树之榛栗,椅桐梓漆。”这个意义读yī。②椅子。本字作“倚”)。"}, {"meaning": "椅子, 有靠背的坐具。", "cites": [{"t": "椅,坐具后有倚者,今人俗呼椅子。", "b": "《正字通》"}], "words": [{"w": "椅杌", "t": "椅子和凳子"}, {"w": "椅背", "t": "椅披。椅子的靠背。"}]}, {"meaning": "轿子。", "cites": [{"t": "皇帝乘椅,自便殿举至西便门。", "b": "《辽史》"}]}]}, {"pinyin": "yī", "defs": [{"meaning": "落叶乔木，木材可以制器物。大风子科,落叶乔木。果实为浆果,球形,红色。", "words": [{"w": "椅梧", "t": "椅树和梧桐树。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2570wx','椒','1','jiāo','木','12','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从木,叔声。本义:花椒)。"}, {"meaning": "同本义。芸香科植物 。落叶灌木或小乔木。具香气。单数羽状复叶,果实作调味料,并可提芳香油入药。种子可榨油,叶制农药。", "cites": [{"t": "焚椒兰也。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "椒科", "t": "泛指各种调味佐料"}, {"w": "椒图", "t": "椒涂。神话传说中一种形似螺蚌的动物,性好闭口,古代常把它画在门上做装饰。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2571wx','棵','1','kē','木','12','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从木,果声。本义:指植物的株数)"}, {"meaning": "植物的大小"}, {"meaning": "指某些植物的茎", "words": [{"w": "棵秆", "t": "某些植物的茎"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2572wx','棍','1','gǔn gùn','木','12','','[{"pinyin": "gǔn", "defs": [{"meaning": "能够转动,用以缠绕线、弦的旋纽。", "cites": [{"t": "棍,转也。谓箜篌上转绳也。", "b": "唐·玄应《一切经音义》"}]}]}, {"pinyin": "gùn", "defs": [{"meaning": "棍棒。", "cites": [{"t": "是那一个实丕丕将着粗棍敲,打的来痛杀杀精皮掉。", "b": "《元曲选·纪君祥·赵氏孤儿》"}], "words": [{"w": "大棍;齐眉棍;三节棍;二节棍;大梢子棍;手捎子棍", "t": ""}]}, {"meaning": "品行很坏的人。", "cites": [{"t": "山儿,我如今放你去,若拿得这两个棍徒,将功折罪;若拿不得,二罪俱罚。", "b": "元·康进之《李逵负荆》"}], "words": [{"w": "赌棍;淫棍;恶棍;棍虎;棍类;棍精", "t": "老光棍"}, {"w": "讼棍;棍徒", "t": "恶棍,无赖之徒"}, {"w": "棍骗", "t": "无赖,拐骗"}, {"w": "棍蠹", "t": "无赖汉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2573wx','椎','1','chuí zhuī','木','12','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从木,隹(zhuī)声。本义:槌子,敲击的器具)。"}, {"meaning": "捶击的工具。后亦为兵器。", "cites": [{"t": "椎,所以击也。", "b": "《说文》"}, {"t": "椎,棒椎也。", "b": "《广韵》"}, {"t": "杼上终葵首。", "b": "《考工记·玉人》。疏:“终葵,椎也。”"}], "words": [{"w": "椎拍", "t": "用椎拍击"}, {"w": "椎斧", "t": "椎和斧"}, {"w": "椎凿", "t": "槌子和凿子"}, {"w": "椎锻", "t": "锤子和打铁用的砧石"}, {"w": "椎额", "t": "额头突出如椎"}, {"w": "椎塘", "t": "臼。"}]}, {"meaning": "用椎打击。", "cites": [{"t": "椎,击也。", "b": "《说文》"}, {"t": "五日一椎牛。", "b": "《史记·张释之冯唐传》"}, {"t": "椎秦始皇博浪之中。", "b": "《后汉书·冯衍传》"}], "words": [{"w": "椎楚", "t": "杖刑"}, {"w": "椎牛", "t": "击杀牛"}, {"w": "椎坐", "t": "捶击坐具"}, {"w": "椎秦", "t": "椎击秦皇。"}]}]}, {"pinyin": "zhuī", "defs": [{"meaning": "椎骨。", "cites": [{"t": "三椎下间主胸中热。", "b": "《素问·刺热篇》。王冰注:“脊节谓之椎。”"}], "words": [{"w": "胸椎;腰椎", "t": ""}]}, {"meaning": "锥(锥属植物)的古称。", "cites": [{"t": "椎,木名。似栗而小。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2574wx','棉','1','mián','木','12','','[{"pinyin": "mián", "defs": [{"meaning": "(会意。从木,从帛。植物名)。"}, {"meaning": "木棉,也叫“攀枝花”、“英雄树”。", "cites": [{"t": "棉,木棉,树名。《吴录》云:其实如酒杯,中有绵如蚕绵,可作布。", "b": "《广韵》"}]}, {"meaning": "植物名 。一年生草本或多年生灌木。棉属的任何一种植物,其特征是直立、自由分枝、叶互生、分裂、花大,乳白色或黄色,迅速转变红色,由一个杯形的总苞包入叶腋内,产生蒴果,当成熟时裂开,因此露出种子和附着的纤维。"}, {"meaning": "比喻耳根软,不坚持己见。", "cites": [{"t": "到底是那里来的孩子?他不过哄我们那个棉花耳朵的爷罢了,纵有孩子,也不知张姓王姓的!", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2575wx','棚','1','péng','木','12','','[{"pinyin": "péng", "defs": [{"meaning": "(形声。从木,朋声。本义:用竹、木搭成的篷架或小屋)。"}, {"meaning": "同本义。", "cites": [{"t": "棚,栈也。", "b": "《说文》。按,编木横竖为之皆曰栈曰棚,今谓于上以蔽下者曰棚。段玉裁注:“《通俗文》曰:‘板阁曰栈,连阁曰棚。’析言之也。许云:‘棚,栈也。’浑言之也。”"}, {"t": "高棚跨路,广幕陵云。", "b": "《隋书·柳彧传》"}], "words": [{"w": "窝棚", "t": "简陋的小屋"}, {"w": "棚井", "t": "棚户进庐"}, {"w": "棚摊", "t": "有棚子的货摊"}, {"w": "棚阁", "t": "用竹、木等搭建的篷架、陋屋"}, {"w": "棚杠", "t": "旧时为丧家承办搭棚,扛抬灵柩、冥器等事宜者。"}]}, {"meaning": "楼阁。我国传统楼房的一种,供远眺、游憩、藏书、供佛等用。也指类似棚阁的结构与设施。", "cites": [{"t": "连阁曰棚。", "b": "《通俗文》"}, {"t": "负米往来七十步,其二十步上下棚除。", "b": "《九章算术·商功章》。刘薇。注:“棚,阁也。除邪道也。”"}, {"t": "棚阁,《苍颉篇》:楼阁也。谓重屋复道者也。", "b": "玄应《一切经音义》"}], "words": [{"w": "棚阁", "t": "作战时,在城上用木架设的瞭望台"}, {"w": "棚帘", "t": "棚阁珠帘。"}]}, {"meaning": "朋党,帮派。", "cites": [{"t": "玄宗时,士子殷盛,每岁进士到省者常不减千余人,在馆诸生更相造诣,互结朋党,以相渔夺,号之为棚。推声望者为棚头。", "b": "《封氏闻见记·贡举》"}]}, {"meaning": "清末陆军编制,兵士十四人为一棚。", "cites": [{"t": "钱塘县回了抚台,派了两棚兵带了洋枪出去剿狗。", "b": "《二刻拍案惊奇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2576wx','棕','1','zōng','木','12','','[{"pinyin": "zōng", "defs": [{"meaning": "植物名。棕榈的省称 。本作椶。", "cites": [{"t": "椶,栟榈也。", "b": "《说文》"}], "words": [{"w": "龙棕;蜡棕;扇棕;棕片", "t": "棕衣。棕皮"}, {"w": "棕车", "t": "以棕为盖顶的车"}, {"w": "棕笋", "t": "棕榈的花苞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2577wx','棺','1','guān','木','12','','[{"pinyin": "guān", "defs": [{"meaning": "(形声。从木,官声。本义:棺材,装殓尸体的器具) 同本义。亦称:棺木,棺函,棺柩,棺衬。", "cites": [{"t": "棺,榇也,所以掩尸。孝经郑注:“周尸为棺。”", "b": "《说文》"}, {"t": "棺之为言完,所以藏尸令完全也。", "b": "《白虎通》"}, {"t": "阳作木棺,有虞氏用瓦棺。", "b": "《古文考》"}], "words": [{"w": "棺材本", "t": "借指养老的钱"}, {"w": "棺材座子", "t": "棺材下面的底座"}, {"w": "棺尸", "t": "棺材中的尸体"}, {"w": "棺衾", "t": "棺材和衾被。泛指殓尸之具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2578wx','榔','1','láng','木','12','','[{"pinyin": "láng", "defs": [{"meaning": "槟榔,又叫桄榔。", "cites": [{"t": "榔,俗桹子。凡宾桹、桄桹皆从良,或单作郎。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2579wx','椭','1','tuǒ','木','12','','[{"pinyin": "tuǒ", "defs": [{"meaning": "(形声。从木,隋声。本义:长圆形,狭长) 同本义。", "cites": [{"t": "其方圆锐椭不同,盛水各异,其于灭火钧也。", "b": "《淮南子》"}]}, {"meaning": "指某些长圆形的容器。", "cites": [{"t": "椭,车笭中椭椭器也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2580wx','惠','1','huì','心','12','','[{"pinyin": "huì", "defs": [{"meaning": "(会意。从心,从叀(zhuān)。本义:仁爱)。"}, {"meaning": "同本义。", "cites": [{"t": "惠,仁也。", "b": "《说文》"}, {"t": "爱民好与曰惠。柔质慈民曰惠。", "b": "《周书·谥法》"}, {"t": "分人以财谓之惠。", "b": "《孟子》"}, {"t": "心省恤人谓之惠。", "b": "《贾子道术》"}, {"t": "孙讨虏聪明仁惠。", "b": "《资治通鉴》"}, {"t": "夫慈者不忍,而惠者好与也。", "b": "《韩非子·内储说上》"}, {"t": "其养民也惠。", "b": "《论语·公冶长》"}, {"t": "彭有守多惠政。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "惠声", "t": "仁爱而有德泽的美名"}, {"w": "惠育", "t": "用仁心爱德加以养育"}, {"w": "惠化", "t": "仁爱的教化"}, {"w": "惠心", "t": "仁慈的心。"}]}, {"meaning": "柔顺;顺从。", "cites": [{"t": "义征不惠。", "b": "《史记·司马相如传》"}, {"t": "荆南怀惠。", "b": "《魏都赋》"}], "words": [{"w": "惠音", "t": "和谐的乐音;对他人书信的尊称"}, {"w": "惠气", "t": "和顺之气"}, {"w": "惠来", "t": "招抚使之归顺。"}]}, {"meaning": "聪慧。", "cites": [{"t": "巧文辩惠则贤。", "b": "《国语·晋语九》"}, {"t": "先言而后当者,惠也。", "b": "《晏子春秋·外篇》"}, {"t": "惠者知其不可两守,乃取一焉。", "b": "《管子·宙合》"}, {"t": "甚矣,汝之不惠。", "b": "《列子·汤问》"}, {"t": "观君所言,将不早惠乎。", "b": "《后汉书·孔融传》"}, {"t": "曲眉丰颊,清声而便体,秀外而惠中。", "b": "唐·韩愈《送李愿归盘谷序》"}], "words": [{"w": "惠悟", "t": "聪敏"}, {"w": "惠美", "t": "聪明美丽"}, {"w": "惠丽", "t": "聪明美丽"}, {"w": "惠黠", "t": "聪慧。"}]}, {"meaning": "恩惠。", "cites": [{"t": "小惠未徧。", "b": "《左传·庄公十年》"}, {"t": "大王加惠。", "b": "《战国策·魏策》"}, {"t": "君之惠。", "b": "《左传·僖公三十二年》"}, {"t": "从君惠而免之。", "b": ""}, {"t": "今缓刑罚,行宽惠,是利奸邪而害善人也。", "b": "《韩非子·难二》"}], "words": [{"w": "惠渥", "t": "深厚的恩泽"}, {"w": "惠义", "t": "恩义"}, {"w": "惠润", "t": "恩泽。"}]}, {"meaning": "恩爱;宠爱。", "cites": [{"t": "小人怀惠。", "b": "《论语》。苞注:“恩也。”"}, {"t": "惠而好我,携手同归。", "b": "《诗·邶风·北风》"}]}, {"meaning": "古兵器名。三棱矛。", "cites": [{"t": "二人雀弁,执惠,立于毕命之内。", "b": "《书·顾命》"}]}, {"meaning": "惠赠;给予好处。", "cites": [{"t": "君必惠民而己。", "b": "《韩非子·外储说右上》"}], "words": [{"w": "惠贶", "t": "提到人家馈赠的客气说法"}, {"w": "惠鲜", "t": "施恩惠给贫困的人"}, {"w": "惠而不费", "t": "加恩惠给人,而无所浪费损失。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2581wx','惑','1','huò','心','12','','[{"pinyin": "huò", "defs": [{"meaning": "(形声。从心,惑声。本义:疑惑,分辨不清)。"}, {"meaning": "同本义。", "cites": [{"t": "内惑于郑袖。", "b": "《史记·屈原贾生列传》"}, {"t": "为奴婢所惑。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "惑眩", "t": "迷乱;混乱"}, {"w": "惑疾", "t": "迷乱之病"}, {"w": "惑变", "t": "迷乱变化"}, {"w": "惑易", "t": "精神失常"}, {"w": "惑志", "t": "疑心"}, {"w": "惑误 ", "t": "使人疑而误之。"}]}, {"meaning": "迷惑,使…辨不清。", "cites": [{"t": "嫣然一笑,惑阳城,迷下蔡。", "b": "宋玉《登徒子好色赋》"}, {"t": "以惑愚瞽。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "惑动", "t": "迷惑动摇"}, {"w": "惑主", "t": "迷惑君主"}, {"w": "惑术", "t": "迷惑人心之术"}, {"w": "惑惑", "t": "迷惑"}, {"w": "惑众", "t": "迷惑众人"}, {"w": "造谣惑众;妖言惑众;惑世", "t": ""}]}, {"meaning": "迷失。", "cites": [{"t": "广不谢大将军而起行…惑失道。后大将军。", "b": "《汉书》"}]}, {"meaning": "糊涂,令人不解。", "cites": [{"t": "不亦惑乎。", "b": "《吕氏春秋·察今》"}, {"t": "传道受业解惑。", "b": "唐·韩愈《师说》"}, {"t": "孰能无惑。", "b": ""}, {"t": "幽暗昏惑。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "惑实", "t": "糊涂"}, {"w": "惑人", "t": "昏庸糊涂的人"}, {"w": "惑主", "t": "昏君"}, {"w": "惑突", "t": "糊涂,疑惑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2582wx','逼','1','bī','辶','12','','[{"pinyin": "bī", "defs": [{"meaning": "(形声。从辵(chuò),畐(fú)声。本义:接近,靠近)。"}, {"meaning": "同本义(仅表示空间距离的接近、靠近)。", "cites": [{"t": "逼,近也。", "b": "《说文新附》"}, {"t": "秦兵逼淝水而陈。(陈:布阵)", "b": "《资治通鉴》"}, {"t": "鸡健进,逐逼之,虫已在爪下矣。", "b": "《聊斋志异·促织》"}, {"t": "不可偪也。", "b": "《国语·郑语》"}, {"t": "是故入小而不偪。", "b": "《淮南子·兵略》"}, {"t": "逼,近也。", "b": "《小尔雅·广诂》"}], "words": [{"w": "逼水", "t": "迫近水边"}, {"w": "逼曙", "t": "天快亮的时候"}, {"w": "逼战", "t": "近战。"}]}, {"meaning": "逼迫,即紧紧催促。", "cites": [{"t": "又荆州之民附操者,逼兵势耳。", "b": "《资治通鉴》"}, {"t": "其家逼之,乃投水而死。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "心虑人逼取。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "逼主", "t": "臣子胁迫君主"}, {"w": "逼取", "t": "强迫索取"}, {"w": "逼索", "t": "逼取。以强力索取"}, {"w": "逼人太甚", "t": "过分逼迫人而不留余地。"}]}, {"meaning": "驱逐;追赶。", "cites": [{"t": "鸡健进,逐逼之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "逼逐", "t": "驱逐"}, {"w": "逼邪", "t": "驱邪。"}]}, {"meaning": "狭窄。", "cites": [{"t": "人稠网密,地逼势胁。", "b": "曹植《七启》"}], "words": [{"w": "逼窄", "t": "很狭窄。同逼侧"}, {"w": "逼侧", "t": "相迫近。即狭窄。也作逼仄"}, {"w": "逼邻", "t": "近邻。紧邻。"}]}, {"meaning": "危急,紧急。", "cites": [{"t": "粮食乏绝,进退逼急。", "b": "《后汉书·董卓传》"}], "words": [{"w": "逼切", "t": "迫切,急切"}, {"w": "逼急", "t": "急迫。"}]}, {"meaning": "很,程度深。", "cites": [{"t": "山石似马,望之逼真。", "b": "《水经注·沔水》"}], "words": [{"w": "逼冷", "t": "极冷"}, {"w": "逼似", "t": "很相似"}, {"w": "副真", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2583wx','粟','1','sù','米','12','','[{"pinyin": "sù", "defs": [{"meaning": "(会意,象草木果实下垂的样子。后隶变为“西”。本义:粟子,谷子)。"}, {"meaning": "同本义 今北方通称“谷子”,去皮后叫“小米”。一种粗糙、抗旱、但不耐霜冻的一年生禾草(Setaria italica),具有粗而重的长穗状花序,可作谷物、干草和饲料。", "cites": [{"t": "粟,嘉谷实也。", "b": "《说文》"}, {"t": "其粟麦粳稻之属各依土地,贮之州县。", "b": "《旧唐书·食货志下》"}, {"t": "输不必金,出粟、菽、帛、布及它物者听。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "粟入", "t": "税粟的收入"}, {"w": "粟粒", "t": "谷物的颗粒。"}]}, {"meaning": "谷粒 。未去皮壳者为粟,已舂去糠则为米。", "cites": [{"t": "迁淳安知县。布袍脱粟,令老仆艺蔬自给。", "b": "《明史·海瑞传》"}], "words": [{"w": "粟饭", "t": "糙米饭。"}]}, {"meaning": "粮食的统称。", "cites": [{"t": "苟粟多而财有余,何为而不成?", "b": "汉·贾谊《论积贮疏》"}, {"t": "马之千里者,一食或尽粟一石。", "b": "唐·韩愈《杂说》"}, {"t": "臣闻地广者粟多,国大者人众。", "b": "李斯《谏逐客令》"}], "words": [{"w": "粟土", "t": "宜于种植谷物的土壤"}, {"w": "粟陈贯朽", "t": "粟红贯朽"}, {"w": "粟红贯朽", "t": "粮有余而腐坏,钱久不用,穿钱的绳子也乱了,比喻太平盛世,钱粮丰饶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2584wx','棘','1','jí','木','12','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。从二-朿(cì)。“朿”是“刺”的本字。两个“朿”字并排立着,表示棘树多刺,是矮小而成丛莽的灌木。本义:丛生的小枣树)。"}, {"meaning": "酸枣树。一种落叶乔木,有刺。果实较枣小,味酸,种子、果皮、根可入药。", "cites": [{"t": "棘,小枣丛生者。", "b": "《说文》"}, {"t": "實于丛棘。", "b": "《易·坎》"}, {"t": "园有棘。", "b": "《诗·魏风·园有桃》"}, {"t": "伐棘枣以为矜。", "b": "《淮南子·兵略》"}, {"t": "香径长洲尽棘丛,奢云艳雨只悲风。", "b": "陆龟蒙《吴宫怀古》"}], "words": [{"w": "棘薪", "t": "指酸枣树已长成薪柴。"}]}, {"meaning": "泛指有芒刺的草木。", "cites": [{"t": "攀草牵棘。", "b": "《徐霞客游记·游黄山记》"}, {"t": "虫伏棘根。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又如荆棘丛生;披荆斩棘;棘针科(有棘刺的植物,荆棘丛);棘匕(枣木做的饭匙。匕:饭勺或羹匙);棘楚(即荆棘。有芒刺的草木)。"}, {"meaning": "四轴海绵骨针,其中辐肋等长或近于等长。"}, {"meaning": "古代兵器名。合戈矛为一体,可以直刺与横击。", "cites": [{"t": "子都拔棘以逐之。", "b": "《左传·隐公十一年》"}, {"t": "越棘大弓,天子之戎器也。", "b": "《礼记·明堂位》"}], "words": [{"w": "棘门", "t": "宫门。即戟门。古代帝王宿处门口武士执戟或插戟于地守卫,称棘门。"}]}, {"meaning": "中国地名。"}, {"meaning": "春秋鲁国的都城,在今山东省肥城县南。"}, {"meaning": "春秋楚国的都城,在今河南省永城县南。"}, {"meaning": "棱角整饬,锋刃锐利。", "cites": [{"t": "仁失斯翼,如矢斯棘,如鸟斯革。", "b": "《诗·小雅·斯干》"}]}, {"meaning": "办事艰难。", "cites": [{"t": "[尧曲]语其艰棘,未有如斯之甚也。", "b": "唐·刘知几《史通》"}]}, {"meaning": "急切,急迫。", "cites": [{"t": "匪棘其欲,遹追来孝。", "b": "《诗·大雅·文王有声》"}, {"t": "岂不日戒,猃狁孔棘。", "b": "《诗·小雅·采薇》"}]}, {"meaning": "瘦弱;土地不肥沃。", "cites": [{"t": "庶见素冠兮,棘人栾栾兮。", "b": "《诗·桧风·素冠》"}, {"t": "凡耕之大方……棘者欲肥,肥者欲棘。", "b": "《吕氏春秋·任地篇》"}, {"t": "地可使肥,又可使棘。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2585wx','酣','1','hān','酉','12','','[{"pinyin": "hān", "defs": [{"meaning": "(会意。从酉,从甘,甘亦声。从“酉”,表示与酒有关。“甘”也具有表意作用。本义:酒喝得很畅快)。"}, {"meaning": "同本义。", "cites": [{"t": "酣,酒乐也。", "b": "《说文》"}, {"t": "酣,乐也。", "b": "《广雅》"}, {"t": "酒酣,上击筑自歌。", "b": "《汉书·高帝纪》"}, {"t": "代君至酒酣。", "b": "《吕氏春秋·长攻》"}, {"t": "秦王饮酒酣。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "酒酣,公子起,为寿侯生前。", "b": "《史记·魏公子列传》"}, {"t": "宴酣之乐。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "酣湑", "t": "畅饮欢乐"}, {"w": "酣饫", "t": "酒醉饭饱"}, {"w": "酣歌", "t": "畅饮乐极而歌唱"}, {"w": "酣兴", "t": "尽情喝酒的乐趣"}, {"w": "酣叫", "t": "畅饮且大声地呼叫"}, {"w": "酣放", "t": "嗜酒畅饮而行为放纵"}, {"w": "酣酣", "t": "畅饮醉酒的样子"}, {"w": "酣宴", "t": "纵情饮宴。"}]}, {"meaning": "浓盛;盛美。", "cites": [{"t": "荷花落日红酣。", "b": "宋·王安石《题西太一宫壁》"}], "words": [{"w": "酣春", "t": "春色最盛美的时候"}, {"w": "酣酣", "t": "形容景色极盛美。"}]}, {"meaning": "尽情地;痛快地。", "cites": [{"t": "酣饮不知醉。", "b": "曹丕《善哉行》"}, {"t": "战酣日暮。", "b": "《淮南子·览冥》"}], "words": [{"w": "酣闹处", "t": "激烈之时"}, {"w": "酣斗", "t": "激烈战斗"}, {"w": "酣鏖", "t": "战斗剧烈而持久。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2586wx','酥','1','sū','酉','12','','[{"pinyin": "sū", "defs": [{"meaning": "(会意。从禾,从酉(yǒu)。酥指食品,因而与禾、酉(代表酒)有关。本义:酪类。由牛羊乳制成。又称“酥油”)。"}, {"meaning": "同本义。", "cites": [{"t": "十万军城百万类,酥油香暖夜如烝。", "b": "唐·薛能《影灯夜》"}], "words": [{"w": "酥团", "t": "用牛羊乳制成的酪类食品,色白光润"}, {"w": "酥酡", "t": "古印度以乳酪作成的食品"}, {"w": "酥酪", "t": "以牛羊乳所制成的一种食品"}, {"w": "酥蜜", "t": "酥酪与蜂蜜。"}]}, {"meaning": "酒。", "cites": [{"t": "天竺国谓酒为酥。", "b": "宋·窦平《酒谱·异域酒》"}], "words": [{"w": "酥酒", "t": "古时酒名"}, {"w": "酥醪", "t": "奶酒。"}]}, {"meaning": "面粉加酒、糖等制成的一种点心,松而易碎。", "cites": [{"t": "已倾潘子错著水,更觅君家为甚酥。(为甚酥,一种油果名)", "b": "宋·苏轼《戏刘监食求米粉饼》"}, {"t": "塞北送酥一盒至。", "b": "《三国演义》"}], "words": [{"w": "桃酥;芝麻酥;酥饼;酥糖", "t": "用面粉、芝麻与糖制成的食品"}, {"w": "酥签", "t": "一种酥松的糕点。"}]}, {"meaning": "搽脸的油脂。", "cites": [{"t": "暖酥消,腻云亸,终日厌厌倦梳裹。", "b": "宋·柳永《定风波》"}]}, {"meaning": "肢体松软的。缺乏力量、肌肉松弛的。", "cites": [{"t": "休道冲动那厮,这一会儿连小闲也酥倒了。", "b": "《元曲选·关汉卿·救风尘》"}], "words": [{"w": "酥懈", "t": "酸软倦怠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2587wx','厨','1','chú','厂','12','','[{"pinyin": "chú", "defs": [{"meaning": "(形声。从广(yǎn),尌(shù)声。本义:厨房)。"}, {"meaning": "同本义。", "cites": [{"t": "厨,庖屋也。", "b": "《说文》"}, {"t": "《孟子》始有厨字,是周初名庖,周末名厨也。", "b": "《说文句读》"}, {"t": "厨主食者也。", "b": "《苍颉篇》"}, {"t": "是以君子远庖厨也。", "b": "《孟子·梁惠王上》"}, {"t": "饰厨传,俗字误作厨。", "b": "《汉书·宣帝纪》"}, {"t": "三日入厨下,洗手作羹汤。", "b": "张籍《新嫁娘》"}, {"t": "厨冷难留乌止屋。", "b": "白居易《酬梦得贫居咏怀》"}, {"t": "轩东故尝为厨,人往,从轩前达。", "b": "归有光《项脊轩志》"}], "words": [{"w": "厨下", "t": "厨房"}, {"w": "厨头", "t": "厨房"}, {"w": "厨仓", "t": "厨房与粮仓"}, {"w": "厨帐", "t": "账幕式厨房。"}]}, {"meaning": "操办官食的官。", "cites": [{"t": "贤母病,长安厨给祠食。", "b": "《汉书·王嘉传》"}], "words": [{"w": "厨吏", "t": "厨宰。主持炊事的小吏"}, {"w": "厨兵", "t": "炊事兵"}, {"w": "厨役", "t": "担任炊事的仆役。"}]}, {"meaning": "菜肴。", "cites": [{"t": "夫人设厨。", "b": "班固《汉武帝内传》"}], "words": [{"w": "厨膳", "t": "厨馔,饭菜"}, {"w": "厨珍", "t": "珍贵美味的食品"}, {"w": "厨车", "t": "运食物的车。"}]}, {"meaning": "烹饪;烹调。", "cites": [{"t": "竹里行厨,花下提壶。", "b": "元·曹德《折桂令》"}], "words": [{"w": "厨养臣", "t": "掌管君主膳食的官员。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2588wx','厦','1','shà xià','厂','12','','[{"pinyin": "shà", "defs": [{"meaning": "(厦俗作厦。古通作夏。形声。从广,夏声。广(yǎn)表示房屋。“夏”古有“大”的意思。见《尔雅·释诂》。本义:大屋子)。"}, {"meaning": "同本义。", "cites": [{"t": "安得广厦千万间,大庇天下寒士俱欢颜。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "厦子", "t": "小厢房;小屋"}, {"w": "厦处", "t": "住所。"}]}, {"meaning": "大。", "cites": [{"t": "厦屋一揆,华屏齐荣。", "b": "晋·左思《魏都赋》"}], "words": [{"w": "厦屋", "t": "高大的屋。"}]}]}, {"pinyin": "xià", "defs": [{"meaning": "", "words": [{"w": "鹰厦铁路", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2589wx','硬','1','yìng','石','12','','[{"pinyin": "yìng", "defs": [{"meaning": "(形声。从石,更声。本义:坚硬)。"}, {"meaning": "同本义 。与“软”相对。", "cites": [{"t": "山原川泽,土有硬软。", "b": "《通典》"}, {"t": "由于血压长期升高,可促使细小动脉硬化。", "b": "唐时华等《高血压病》"}], "words": [{"w": "硬米糁", "t": "未煮熟的米饭"}, {"w": "硬牌", "t": "旧制在府官到达前,必派前站带木牌先行通知地方官绅人等迎接"}, {"w": "硬帮", "t": "坚硬"}, {"w": "硬撑撑", "t": "坚硬结实"}, {"w": "硬胎", "t": "硬质的衬里"}, {"w": "硬倔倔", "t": "形容物体坚硬"}, {"w": "硬拐拐", "t": "形容坚硬而有棱角"}, {"w": "硬触触", "t": "形容坚硬扎手"}, {"w": "硬戗", "t": "形容坚硬有力。"}]}, {"meaning": "结实。", "cites": [{"t": "十日一放,令其陆梁舒展,令马硬实也。", "b": "北魏·贾思勰《齐民要术》"}], "words": [{"w": "硬挣", "t": "硬朗;刚强"}, {"w": "硬棒棒", "t": "结实"}, {"w": "硬实", "t": "方言。健壮结实。"}]}, {"meaning": "生硬。", "cites": [{"t": "有些同志过分强调直译,硬译。", "b": "郭沫若《雄鸡集》"}], "words": [{"w": "硬搬", "t": "生搬硬套"}, {"w": "硬译", "t": "按照原文逐字逐句地直译"}, {"w": "硬拐", "t": "生硬的转弯"}, {"w": "硬语", "t": "生硬的词句"}, {"w": "硬声硬气", "t": "语气生硬。"}]}, {"meaning": "倔强,执拗。", "cites": [{"t": "石秀道:“嫂嫂,你休要硬诤;教你看个证见。", "b": "《水浒传》"}], "words": [{"w": "硬口", "t": "嘴硬"}, {"w": "硬打挣", "t": "强辩;抵赖"}, {"w": "硬行", "t": "强行;强制"}, {"w": "硬劲", "t": "倔强脾气。"}]}, {"meaning": "坚强,强硬。", "cites": [{"t": "若父亲是个硬挣的,定然卫护儿女,与老婆反目厮闹,不许他凌辱。", "b": "《醒世恒言》"}], "words": [{"w": "硬保山", "t": "有身分有地位且能说得起话的保人"}, {"w": "硬出头", "t": "故意出面领头干某件事。有贬义"}, {"w": "硬绷", "t": "态度坚决、强硬;坚硬。"}]}, {"meaning": "能力强;质量好。", "cites": [{"t": "必须彻底解决,派硬手去。", "b": "蒋子龙《乔厂长上任记》"}], "words": [{"w": "硬功夫;硬手", "t": "高手;能手。"}]}, {"meaning": "确实;真正。", "cites": [{"t": "乡亲!硬是要得!", "b": "老舍《不成问题的问题》"}], "words": [{"w": "硬是", "t": "确实是"}, {"w": "硬该揍", "t": ""}]}, {"meaning": "勉强。", "cites": [{"t": "你到底是年过六旬的人,硬撑是不行的。", "b": "张英《老年突击队》"}], "words": [{"w": "硬强着", "t": "迫使;强逼着"}, {"w": "硬坐", "t": "强加罪名"}, {"w": "硬打挣", "t": "强挣扎"}, {"w": "硬扎子", "t": "硬充好汉。"}]}, {"meaning": "强。", "cites": [{"t": "我也硬不多儿,只战个平手。", "b": "《西游记》"}], "words": [{"w": "硬正", "t": "强有力的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2590wx','硝','1','xiāo','石','12','','[{"pinyin": "xiāo", "defs": [{"meaning": "硝石。", "cites": [{"t": "硝,药石也。方书硝七种。", "b": "《正字通》"}], "words": [{"w": "硝子石", "t": "硝石。又称假水晶;也喻指眼睛"}, {"w": "硝云弹雨", "t": "硝烟如云,子弹像雨。形容激烈的战斗。"}]}, {"meaning": "经过硝制变软的皮革。", "cites": [{"t": "若南方短毛革硝,其如纸薄。", "b": "《天工开物》"}]}, {"meaning": "用朴芒硝等鞣制皮革使变软。", "cites": [{"t": "要送到皮园里硝了,赶出来做成坐褥,新年好放在马上骑坐。", "b": "《醒世姻缘传》"}, {"t": "走了硝,天冷怎穿!", "b": "《西游记》"}], "words": [{"w": "硝熟", "t": "用芒硝、朴硝等揉制皮革使之变软。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2591wx','确','1','què','石','12','','[{"pinyin": "què", "defs": [{"meaning": "(形声。左形,右声。本作“碻”、“塙”。本义:坚固)。"}, {"meaning": "同本义。", "cites": [{"t": "确乎能其事者而已矣。", "b": "《庄子·应帝王》"}, {"t": "確乎其不可拔。", "b": "《易·乾卦》"}, {"t": "夫乾確然,示人易矣。", "b": "《易·系辞下》"}, {"t": "乐则行之,忧则违之,确乎其不可拔,潜龙也。", "b": "《易·乾》"}]}, {"meaning": "敲击。", "cites": [{"t": "乐亦不复剖析文句,直以尘尾柄确几。", "b": "《世说新语·文学》"}]}, {"meaning": "竞争。", "cites": [{"t": "李广才气,天下亡双,自负其能,数与虏确。", "b": "《汉书·李广传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2592wx','硫','1','liú','石','12','','[{"pinyin": "liú", "defs": [{"meaning": "硫磺。一种非金属的、多价的、无味无嗅不溶于水的元素 ——元素符号S。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2593wx','雁','1','yàn','隹','12','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从隹(zhuī),从人,厂(hǎn)声,隹,短尾鸟。厂,石山之涯岩,也有表意作用。本义:鸟名)。"}, {"meaning": "鸟类的一属,形状略像鹅,颈和翼较长,足和尾较短,羽毛淡紫褐色,善于游泳和飞行。", "cites": [{"t": "雁,雁鸟也。", "b": "《说文》"}, {"t": "纳采纳吉,请期皆用雁。", "b": "《仪礼·士昏礼》"}, {"t": "下大夫相见以雁。", "b": "《仪礼·士相见礼》"}, {"t": "朔风飘胡雁,惨澹带沙砾。", "b": "唐·杜甫《遣兴五首》"}], "words": [{"w": "雁塔题名", "t": "借指考中进士"}, {"w": "雁杳鱼沉", "t": "雁字鱼书。杳无音信"}, {"w": "雁天", "t": "雁至秋而南翔,故称秋天为雁天"}, {"w": "雁户", "t": "指漂泊异乡居处无定的民户。雁因时迁徙,故以雁为喻"}, {"w": "雁奴", "t": "在雁群中专司警戒的雁"}, {"w": "雁字", "t": "雁飞行时所排成的行列。雁群飞行时,常排成“一”字或“人”字形,故云。也指官吏的排班"}, {"w": "雁臣", "t": "指外帮的臣子朝觐有时,如雁的往返有定候。"}]}, {"meaning": "伪造的,假的。", "cites": [{"t": "鲁以其雁往。", "b": "《韩非子·说林下》。曾廷枚云:“真赝,本作真雁,后人加贝。”"}, {"t": "浸渍数日,漆絮败溃,雁迹尽露。", "b": "宋·王明清《挥尘后录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2594wx','殖','1','shi zhí','歹','12','','[{"pinyin": "shi", "defs": [{"meaning": "——如“骨殖”(gǔshi):尸骨。"}]}, {"pinyin": "zhí", "defs": [{"meaning": "(形声。从歺(è),直声。歺,残骨,隶书写作“歹”。本义:脂膏因放置时间过久而变质)。"}, {"meaning": "同本义。", "cites": [{"t": "殖,殖膏久殖也。", "b": "《说文》"}]}, {"meaning": "生长,繁殖。", "cites": [{"t": "我有田畴,子产殖之。", "b": "《左传·襄公三十年》"}, {"t": "其生不殖。", "b": "《左传·昭公元年》"}, {"t": "五谷所殖。", "b": "《吕氏春秋·孟春》"}, {"t": "同姓不婚,恶不殖也。", "b": "《国语·晋语四》"}, {"t": "松柏之下,其草不殖。", "b": "《左传·襄公二十九年》"}], "words": [{"w": "生殖", "t": "生物产生幼小个体以繁殖后代"}, {"w": "养殖", "t": "培育和繁殖。"}]}, {"meaning": "经营,从事买卖活动。", "cites": [{"t": "父宗善殖财货,富拟王侯。", "b": "《新五代史》"}], "words": [{"w": "货殖", "t": "古代指经营商业和工矿业"}, {"w": "殖私", "t": "营谋私利"}, {"w": "殖利", "t": "生利;营利。"}]}, {"meaning": "种植。", "cites": [{"t": "稷降播种,农殖嘉谷。", "b": "《书·吕型》"}], "words": [{"w": "殖种", "t": "种植"}, {"w": "垦殖", "t": "开荒生产。"}]}, {"meaning": "树立,立。", "cites": [{"t": "上得民心,以殖义方。", "b": "《国语·周语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2595wx','裂','1','liè liě','衣','12','','[{"pinyin": "liè", "defs": [{"meaning": "(会意。从衣,从列,列亦声。本义:裁剪后的丝绸残余)。"}, {"meaning": "同本义。", "cites": [{"t": "裂,缯余也。", "b": "《说文》"}, {"t": "垂带而厉(裂)。", "b": "《诗·小雅·都人士》"}, {"t": "纪裂繻,公谷以履为之。", "b": "《左传·隐公二年》"}], "words": [{"w": "裂繻", "t": "汉制,裂缯帛为符信,凭以出入关隘。"}]}, {"meaning": "裁剪;扯裂。", "cites": [{"t": "裂,裁也。", "b": "《广雅》"}, {"t": "裂裳帛而与之。", "b": "《左传》"}, {"t": "旌旗裂。", "b": "《资治通鉴·唐纪》"}, {"t": "娇儿恶卧踏里裂。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "声如裂帛。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "裂帛", "t": "撕裂布帛;裁剪布帛作为书信"}, {"w": "裂素", "t": "裁剪白绢以绘画作文"}, {"w": "裂破", "t": "撕坏"}, {"w": "裂裳", "t": "撕裂衣裳。"}]}, {"meaning": "割,分。", "cites": [{"t": "裂,分也。", "b": "《广雅》"}, {"t": "裂地而封之。", "b": "《庄子》"}], "words": [{"w": "裂土", "t": "割据土地"}, {"w": "裂石流云", "t": "裂开山石,震动云霄。形容声音高昂响亮"}, {"w": "裂土", "t": "给有功之臣分封土地"}, {"w": "裂饼", "t": "分饼。亦指把所爱之物分赐他人"}, {"w": "裂地", "t": "划分土地"}, {"w": "裂拆", "t": "分裂,裂开。"}]}, {"meaning": "分裂;裂开。", "cites": [{"t": "衣裳绽裂。", "b": "《礼记·内则》"}, {"t": "道术将为天下裂。", "b": "《庄子·天下》。注:“分离也。”"}, {"t": "目眦尽裂。", "b": "《史记·项羽本记》"}, {"t": "四极废,九州裂。", "b": "《淮南子》"}, {"t": "马首裂。", "b": "明·魏禧《大铁椎传》"}, {"t": "股落腹裂。", "b": "《聊斋志异·促织》"}], "words": [{"w": "分裂", "t": "整体的事物分开"}, {"w": "爆裂", "t": "突然破裂"}, {"w": "裂眼", "t": "形容极其愤怒的样子"}, {"w": "裂肤", "t": "皮肤冻裂。形容严寒的样子"}, {"w": "裂冠毁冕", "t": "碎裂其冠,毁坏其冕。比喻绝意仕进"}, {"w": "裂冕挂冠", "t": "比喻抛弃冠晚,不再为官;挂冠求去,致仕归隐"}, {"w": "裂地", "t": "地面坼裂;使地面开裂"}, {"w": "裂眦", "t": "裂眥。因发怒而眼睛睁得极大,眼眶似乎要裂开。形容极其忿怒的神态"}, {"w": "裂绝", "t": "破坏断绝"}, {"w": "烈敝", "t": "破裂损坏。"}]}]}, {"pinyin": "liě", "defs": [{"meaning": "", "words": [{"w": "裂着怀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2596wx','雄','1','xióng','隹','12','','[{"pinyin": "xióng", "defs": [{"meaning": "(形声。从隹(zhuī),厷(gōng)声。从隹,与鸟有关。本义:公鸟)。"}, {"meaning": "同本义。", "cites": [{"t": "雄,鸟父也。", "b": "《说文》"}, {"t": "谁知鸟之雌雄。", "b": "《诗·小雅·正月》"}, {"t": "雄雉于飞。", "b": "《诗·邶风·雄雉》"}, {"t": "但见悲鸟号古木,雄飞雌从绕林间。", "b": "李白《蜀道难》"}], "words": [{"w": "雄父", "t": "公鸡。"}]}, {"meaning": "泛指动植物能产生精细胞的。", "cites": [{"t": "雄狐绥绥。", "b": "《诗·齐风·南山》"}, {"t": "走亦曰雄。", "b": "《周礼·庖人》注"}, {"t": "双兔傍地走,安能辨我是雄雌。", "b": "《木兰诗》"}, {"t": "雄兔脚扑朔。", "b": "《乐府诗集·木兰诗》"}, {"t": "剑有雄雌。", "b": "晋·干宝《搜神记》"}, {"t": "一雄一雌", "b": ""}], "words": [{"w": "雄鸟;雄蕊;雄花;雄孤;雄猿;雄竹", "t": ""}]}, {"meaning": "指男子。", "cites": [{"t": "淳死之后,新妇遗腹得雄,便以为家门之幸。", "b": "明·夏完淳《狱中上母书》"}]}, {"meaning": "指为首者,居前列者。", "cites": [{"t": "有夫出征,而丧其雄。", "b": "《左传·襄公十年》"}]}, {"meaning": "杰出的人物。", "cites": [{"t": "刘备,天下枭雄。", "b": "《资治通鉴》"}], "words": [{"w": "雄长", "t": "称雄,称霸"}, {"w": "雄豪", "t": ""}]}, {"meaning": "强有力的国家。", "cites": [{"t": "今数雄已灭。", "b": "《资治通鉴》"}, {"t": "绝世之雄。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "战国七雄", "t": ""}]}, {"meaning": "比喻高强、胜利。", "cites": [{"t": "愿与汉王挑战决雌雄。", "b": "《史记》"}]}, {"meaning": "雄壮;雄伟。", "cites": [{"t": "雄词惊四座,压倒群英。", "b": "明·朱鼎《玉镜台记·开场》"}], "words": [{"w": "雄烈", "t": "雄伟的功业"}, {"w": "雄尊", "t": "雄伟庄严"}, {"w": "雄词", "t": "气势雄壮的词句"}, {"w": "雄远", "t": "宏伟远大"}, {"w": "雄盛", "t": "雄壮强盛"}, {"w": "雄奇", "t": "雄伟奇特。"}]}, {"meaning": "威武。", "cites": [{"t": "是故聪明秀出谓之英,胆力过人谓之雄。", "b": "三国魏·刘劭《人物志·英雄》"}], "words": [{"w": "雄悍", "t": "勇武强悍"}, {"w": "雄毅", "t": "勇武刚毅"}, {"w": "雄姿;雄雄", "t": "形容威势盛大的样子"}, {"w": "雄骏", "t": "威武英俊,才智出众的人。"}]}, {"meaning": "雄健,刚健;豪放。", "cites": [{"t": "吾用兵三十年,未见以少击众,有雄捷如马将军者。", "b": "《旧唐书·马璘传》"}], "words": [{"w": "雄爽", "t": "雄健豪爽"}, {"w": "雄捷", "t": "雄健矫捷"}, {"w": "雄艳", "t": "雄健美丽"}, {"w": "雄古", "t": "雄健古朴"}, {"w": "雄势", "t": "勇猛威风"}, {"w": "雄儿", "t": "健儿。"}]}, {"meaning": "强有力;杰出。", "cites": [{"t": "少年雄于地球。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "国雄于地球。", "b": ""}], "words": [{"w": "雄才", "t": "杰出的才能"}, {"w": "雄英", "t": "出类拔萃"}, {"w": "雄宗", "t": "杰出的宗匠"}, {"w": "雄异", "t": "杰出卓异"}, {"w": "雄略", "t": "非凡的谋略"}, {"w": "雄强", "t": "强劲有力。"}]}, {"meaning": "优胜;称雄。", "cites": [{"t": "[班壹] 当孝惠高后时,以财雄边。", "b": "《汉书》。颜师古注:“班氏以多财而为边地之雄豪。”"}, {"t": "米元章、赵子昂、董元宰各以书雄一代。", "b": "清·汪中《述学·别录》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2597wx','颊','1','jiá','页','12','','[{"pinyin": "jiá", "defs": [{"meaning": "(形声。从页(xié),表示与头有关,夹声。本义:面颊,脸的两侧从眼到下颌部分)。"}, {"meaning": "同本义。", "cites": [{"t": "颊,面旁也。", "b": "《说文》"}, {"t": "咸其辅颊舌。", "b": "《易·咸》。虞注:“耳目之间称辅颊。”"}, {"t": "未能开笑颊,先欲换愁魂。", "b": "戎昱《闺情》"}], "words": [{"w": "颊辅", "t": "面颊"}, {"w": "颊适", "t": "容貌调适,没有迎拒的表情"}, {"w": "颊车", "t": "下牙床骨;牙慧,蹈袭陈言"}, {"w": "颊颧", "t": "颊权。颧骨。"}]}, {"meaning": "侧,旁边。", "cites": [{"t": "湖桥北颊花坞,水阁西头竹村。", "b": "宋·文同《湖桥》"}]}, {"meaning": "堂内正室旁边的房间。", "cites": [{"t": "中和堂上东南颊,独有人间万里风。", "b": "宋·苏轼《中和堂东南颊下瞰海门洞》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
