('2598wx','雳','1','lì','雨','12','','[{"pinyin": "lì", "defs": [{"meaning": "——见“霹雳”pīlì。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2599wx','暂','1','zàn','日','12','','[{"pinyin": "zàn", "defs": [{"meaning": "(形声。从日,斩声。从日,与时间有关。本义:时间短) 同本义。", "cites": [{"t": "暂,不久也。", "b": "《说文》"}, {"t": "宇文新州之懿范,暫帷暂驻。", "b": "唐·王勃《滕王阁序》"}, {"t": "暂则封舱,久则封港。", "b": "林则徐《政书》。又如:暂劳(一时的劳苦);暂欢(短时间的欢乐);暂云(行云,浮云)"}]}, {"meaning": "暂时。", "cites": [{"t": "但暂还家。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "求假暂归。", "b": ""}, {"t": "饮食拱揖不暂去。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "暂来", "t": "暂时逗留"}, {"w": "暂往", "t": "暂时离去。"}]}, {"meaning": "刚刚;方才。", "cites": [{"t": "玉管初调,鸣弦暂抚。", "b": "庾信《春赋》"}, {"t": "逢观暂巧笑,还泪已啼妆。", "b": "南朝梁·何逊《七夕》"}]}, {"meaning": "仓卒;突然。", "cites": [{"t": "妇人暂而免诸国。", "b": "《左传·僖公三十三年》"}, {"t": "广暂腾而上胡儿马。", "b": "《史记·李将军列传》"}, {"t": "如听仙乐耳暂明。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "暂晓", "t": "突然显现。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2600wx','雅','1','yǎ yā','隹','12','','[{"pinyin": "yǎ", "defs": [{"meaning": "(形声。从隹,牙声。从隹(zhuī),与鸟有关。(yā)本义:鸟名,乌鸦的一种。《说文》:“楚乌也。”)。"}, {"meaning": "正确;合乎规范。", "cites": [{"t": "雅者,正也。言王政之所由废兴也。", "b": "《毛诗序》"}, {"t": "文章尔雅。", "b": "《史记·三王世家》。索隐:皆训正也。"}, {"t": "雅之为言正也。", "b": "《风俗通·声音》"}, {"t": "雅者,古正也。", "b": "《白虎通·礼乐》。按:说文疋下古文,以为诗大雅字。疋字隶体似正,故傅会训正,其实古文借疋为諝,后又借雅为諝也。风,讽也。雅,諝也,颂,诵也。此四始之本字。"}, {"t": "辞令就得谓之雅。", "b": ""}, {"t": "君子安雅。", "b": "《荀子·荣辱》。注:“正而有美德者谓之雅。”"}, {"t": "察纳雅言。", "b": "诸葛亮《出师表》"}], "words": [{"w": "雅道", "t": "正道,大道"}, {"w": "雅音", "t": "正音"}, {"w": "雅算", "t": "正确的决策"}, {"w": "雅学", "t": "正道之学。指儒家经典之学。"}]}, {"meaning": "高尚;美好。", "cites": [{"t": "张耳雅游。", "b": "《史记·张耳陈馀传》"}, {"t": "忽忘雅素。", "b": "《汉书·张禹传》"}, {"t": "雅步擢纤腰。", "b": "《陆云诗》。注:“闲雅谓妖丽也。”"}, {"t": "都督阎公之雅望。", "b": "王勃《滕王阁序》"}], "words": [{"w": "雅操", "t": "称弹奏乐曲高雅精妙"}, {"w": "雅望", "t": "美好的愿望"}, {"w": "雅篇", "t": "优美的篇章"}, {"w": "雅像", "t": "雅相"}, {"w": "雅量高致", "t": "气度不凡,情趣高尚"}, {"w": "雅驯", "t": "温文不俗"}, {"w": "雅坐", "t": "文静地坐着"}, {"w": "雅人深致", "t": "风雅的人有深远的意趣"}, {"w": "雅俗", "t": "雅士与俗人"}, {"w": "雅客", "t": "高雅的客人。"}]}, {"meaning": "素常;向来。", "cites": [{"t": "予雅道冠,拄杖二癖,每自笑叹。", "b": "宋·陆游《老学庵笔记》"}, {"t": "安帝雅闻衡善术学。", "b": "《后汉书·张衡传》"}], "words": [{"w": "雅好", "t": "平素所喜好"}, {"w": "雅志", "t": "平素的志向"}, {"w": "雅尚", "t": "平素的喜好"}, {"w": "子所雅;善雅鼓琴", "t": ""}]}, {"meaning": "表示程度很甚,相当于“很”、“极”。", "cites": [{"t": "帝雅重瑞名。", "b": "《明史》"}], "words": [{"w": "雅重", "t": "甚为敬重。"}]}, {"meaning": "平素的交情。", "cites": [{"t": "况与左右无一日之雅,而敢求交乎?", "b": "宋·苏轼《与谢民师推官书》"}], "words": [{"w": "同朝之雅;同寅之雅;雅素", "t": "故旧的情谊"}, {"w": "雅故", "t": "故交,旧友。"}]}, {"meaning": "《诗经》中六义之一。", "cites": [{"t": "古诗有六义焉:一曰风,二曰赋,三曰比,四曰兴,五曰雅,六曰颂。", "b": "《诗序》"}, {"t": "风土之音曰“风”,朝廷之音曰“雅”,宗庙之音曰“颂”。", "b": "宋·郑樵《通志》总序"}]}, {"meaning": "训诂中多有名雅的书。", "cites": [{"t": "《尔雅》:尔,昵也;昵,近也;雅,义也;义,正也。五方之言不同,皆以近正为主也。", "b": "《释名》"}], "words": [{"w": "《尔雅》", "t": ""}, {"w": "《广雅》", "t": ""}, {"w": "《通雅》", "t": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "yā", "defs": [{"meaning": "", "cites": [{"t": "雅,楚乌也。一名鷽,一名卑居,秦谓之雅。", "b": "《说文》。按:“大而纯黑反哺者乌,小而不纯黑不反哺者雅。雅即乌之转声。字亦作鸦,作鵶。”"}, {"t": "流之为鵰。", "b": "《书·古太誓》。郑注:“鸦乌也。”"}, {"t": "鸱鸦耆鼠。", "b": "《庄子·齐物论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2601wx','翘','1','qiáo qiào','羽','12','','[{"pinyin": "qiáo", "defs": [{"meaning": "(形声。从羽,尧声。羽,鸟毛。本义:鸟尾上的长羽)。"}, {"meaning": "同本义。", "cites": [{"t": "翘,尾长毛也。", "b": "《说文》"}, {"t": "斑尾扬翘。", "b": "潘岳《射雉赋》"}, {"t": "砥室翠翘,挂曲琼些。", "b": "《楚辞·招魂》"}], "words": [{"w": "翠翘", "t": "用翠鸟尾羽做的拂尘用具"}, {"w": "翘英", "t": "华丽的尾羽。"}]}, {"meaning": "鸟尾。", "cites": [{"t": "摇翘奋羽,驰风骋雨,游无穷兮。", "b": "刘向《九叹》"}]}, {"meaning": "泛指动物的尾部。"}, {"meaning": "抬起。", "cites": [{"t": "翘思慕远人。", "b": "曹植《杂诗》"}, {"t": "翘然矜鸣。", "b": "《聊斋志异·促织》"}], "words": [{"w": "翘心", "t": "悬念;一心向往"}, {"w": "翘思", "t": "翘首而思念,悬念"}, {"w": "翘遥", "t": "轻举的样子"}, {"w": "翘关", "t": "扛举城门的门闸。形容力气大。唐代列为武举举重的科目。"}]}, {"meaning": "揭露。", "cites": [{"t": "粗而翘之。", "b": "《礼记·儒行》。疏:“起发也。”"}], "words": [{"w": "翘过", "t": "举发别人过失。"}]}, {"meaning": "高;危。", "cites": [{"t": "翘翘错薪。", "b": "《诗·周南·汉广》"}, {"t": "予室翘翘。", "b": "《诗·豳风·鸱鴞》"}]}]}, {"pinyin": "qiào", "defs": [{"meaning": "", "words": [{"w": "翘胡子;当他踏上这块板时,板翘了起来", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2602wx','辈','1','bèi','车','12','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从车,非声。本义:百辆车)。"}, {"meaning": "同本义。", "cites": [{"t": "辈,若军发车,百辆为辈。", "b": "《说文》"}]}, {"meaning": "也指车列,车队。", "cites": [{"t": "稠人广众,荐宠下辈。(下车来推崇赞扬他们。)", "b": "《史记》"}]}, {"meaning": "世;辈分。", "cites": [{"t": "古人不可见,前辈谁复继?", "b": "杜甫《赠李邕》"}], "words": [{"w": "前辈;后辈;长辈;晚辈", "t": ""}]}, {"meaning": "某类人。", "cites": [{"t": "若辈得无苦贫乎?", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "汝辈所惜罗程艺耳。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "吾辈处今日之中国。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "我辈;侪辈;流辈;朋辈;鼠辈;辈类", "t": "同辈,同类。"}]}, {"meaning": "群,队。", "cites": [{"t": "当先破贼大辈,然后围及得解。", "b": "《三国志·满宠传》"}]}, {"meaning": "等级;类别。", "cites": [{"t": "马有上中下辈。", "b": "《史记·孙子吴起列传》"}]}, {"meaning": "成批地。", "cites": [{"t": "名臣辈出。", "b": "范晔《后汉书》"}]}, {"meaning": "表示人的多数,批。", "cites": [{"t": "匈奴留汉使郭吉、路充国等前后十余辈。", "b": "《汉书·李广苏建传》"}, {"t": "高使人请子婴数辈,子婴不行。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2603wx','悲','1','bēi','忄','12','','[{"pinyin": "bēi", "defs": [{"meaning": "(形声。从心,非声。本义:哀伤;痛心)。"}, {"meaning": "同本义。", "cites": [{"t": "悲,痛也。", "b": "《说文》"}, {"t": "悲,伤也。", "b": "《广雅》"}, {"t": "忧心且悲。", "b": "《诗·小雅·鼓钟》"}, {"t": "我心伤悲。", "b": "《诗·召南·草虫》"}, {"t": "并于肺则悲。", "b": "《素问·宣明五气篇》"}, {"t": "至于悲谷。", "b": "《淮南子·天文》。注:“西南方之大壑也。言深峻,临其上令人悲思,故名。”"}, {"t": "何哭之甚悲也。", "b": "晋·干宝《搜神记》"}, {"t": "少壮不努力,老大徒伤悲。", "b": "《乐府诗集·长歌行》"}, {"t": "不以物喜,不以己悲。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "悲怆", "t": "悲伤"}, {"w": "悲怨", "t": "悲痛怨恨"}, {"w": "悲惋", "t": "悲伤惋惜"}, {"w": "悲吟", "t": "悲伤哀叹"}, {"w": "悲忧", "t": "悲伤忧虑"}, {"w": "悲郁", "t": "悲伤忧郁"}, {"w": "悲涕", "t": "悲痛的眼泪"}, {"w": "悲哭", "t": "悲痛号哭"}, {"w": "悲怒", "t": "悲痛愤怒"}, {"w": "悲疚", "t": "悲痛"}, {"w": "悲戚", "t": "悲痛忧伤"}, {"w": "悲恻", "t": "悲痛。"}]}, {"meaning": "悲哀。", "cites": [{"t": "故遂忍悲为汝言之。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "悲雨", "t": "因悲哀而泪下如雨"}, {"w": "悲哽", "t": "悲哀哽咽。"}]}, {"meaning": "悲壮;悲凉。", "cites": [{"t": "戍角悲吟。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "悲角", "t": "悲壮的号角声"}, {"w": "悲风", "t": "凄厉的风声"}, {"w": "悲默", "t": "忧伤沉默。"}]}, {"meaning": "悲愤。", "cites": [{"t": "余闻而愈悲。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "眷念;怅望。", "cites": [{"t": "游子悲故乡。", "b": "《汉书·高帝纪》。颜师古注:“悲谓顾念也。”"}], "words": [{"w": "悲思", "t": "思念,怅念。"}]}, {"meaning": "哀怜;怜悯。", "cites": [{"t": "悲予志焉。", "b": "宋·文天祥《指南录·后序》"}, {"t": "余悲之。", "b": "唐·柳宗元《捕蛇者说》"}]}, {"meaning": "感叹,慨叹。", "cites": [{"t": "悲哉世也。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "又以悲夫古书之不存。", "b": "宋·王安石《游褒禅山记》"}]}, {"meaning": "可悲。", "cites": [{"t": "以此为治,岂不悲哉!", "b": "《吕氏春秋·察今》"}]}, {"meaning": "悲叹。", "cites": [{"t": "发其志士之悲哉?", "b": "明·张溥《五人墓碑记》"}]}, {"meaning": "佛教语,愿解他人痛苦之心。悲是大乘佛教菩萨概念的基本特点。", "cites": [{"t": "大悲,拔一切众生苦。", "b": "《大智度论》。又如:慈悲;大慈大悲;悲智"}]}, {"meaning": "苦。", "cites": [{"t": "吾于佗文不知蹇涩,惟作诗甚苦,悲唫累日,仅能成篇。", "b": "宋·胡仔《杜少陵三》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2604wx','紫','1','zǐ','糸','12','','[{"pinyin": "zǐ", "defs": [{"meaning": "(形声。从糸(mì),此声。本义:紫色,蓝和红组成的颜色)。"}, {"meaning": "同本义。", "cites": [{"t": "紫,帛黑赤色也。", "b": "《说文》"}, {"t": "恶紫之夺朱也。", "b": "《论语》。孔注:“间色之好者。”"}, {"t": "玄冠紫緌。", "b": "《礼记·玉藻》"}, {"t": "紫衣狐裘。", "b": "《左传·哀公七年》"}, {"t": "红紫不以为亵服。", "b": "《论语》"}, {"t": "紫绮为上襦。", "b": "《乐府诗集·陌上桑》"}, {"t": "佩紫怀黄。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "披紫衣。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "又。", "cites": [{"t": "披紫裳。", "b": ""}, {"t": "绾黄纾紫。", "b": "清·周容《芋老人传》"}], "words": [{"w": "紫棠色", "t": "黑里带红的颜色"}, {"w": "紫玉", "t": "紫色的宝玉;箫笛。古人多截紫竹为箫笛,因称箫笛为紫玉"}, {"w": "紫衣", "t": "紫色的衣服;紫色的袈裟"}, {"w": "紫衫", "t": "紫色的衣衫。"}]}, {"meaning": "与帝王、皇宫有关的事物。", "cites": [{"t": "正阳门径通黄道,长朝殿端拱紫垣。", "b": "《水浒传》"}], "words": [{"w": "紫微垣", "t": "星座名。星相家认为由它的明暗可以判断皇家的兴衰。"}]}, {"meaning": "紫色的衣服和绶带。", "cites": [{"t": "齐桓公好服紫,一国尽服紫。", "b": "《韩非子》"}, {"t": "怀金垂紫。", "b": "《后汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2605wx','凿','1','záo','凵','12','','[{"pinyin": "záo", "defs": [{"meaning": "(形声。从金,鑿(zuò)省声。从金,表示与金属制品有关。本义:凡穿物使通都称凿)。"}, {"meaning": "同本义。", "cites": [{"t": "凿,穿木也。", "b": "《说文》"}, {"t": "重木刊凿之。", "b": "《仪礼·士丧礼》"}, {"t": "皆是水凿之穴。(凿,这里是冲刷的意思。)", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "凿巾", "t": "在覆盖死者脸部的巾上,正对口部的位置,剪开一通孔"}, {"w": "凿穴", "t": "开造洞穴。"}]}, {"meaning": "挖掘;开凿。", "cites": [{"t": "凿地为坎。", "b": "《汉书·李广苏建传》"}, {"t": "水凿之穴。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "水凿之处。", "b": ""}, {"t": "千锤万凿出深山。", "b": "明·于谦《石灰吟》"}], "words": [{"w": "凿溉", "t": "开渠灌溉"}, {"w": "凿龙", "t": "开凿龙门。指大禹治水,凿龙门以导流"}, {"w": "凿饮", "t": "掘井而饮。"}]}, {"meaning": "开通。", "cites": [{"t": "然张骞凿空,其后使往者皆称博望侯。", "b": "《史记·张骞列传》"}]}, {"meaning": "穿凿附会。", "cites": [{"t": "所恶于智者,为其凿也。", "b": "《孟子·离娄下》"}], "words": [{"w": "凿说", "t": "穿凿附会之说"}, {"w": "凿脱", "t": "穿凿附会造成失误"}, {"w": "凿言", "t": "穿凿附会地说。"}]}, {"meaning": "戳,用手指头猛地一推。", "cites": [{"t": "那婆子揪住郓哥,凿上两个栗暴。", "b": "《水浒全传》"}]}, {"meaning": "舂米使之精白。", "cites": [{"t": "粢食不凿,昭其俭也。", "b": "《左传·桓公二年》"}], "words": [{"w": "凿八", "t": "指捣米一石,可得八斗。"}]}, {"meaning": "引申为冲刷。", "cites": [{"t": "如大小龙湫、水帘、初月谷之类,皆是水凿之穴。", "b": "《梦溪笔谈》"}]}, {"meaning": "敲击,捶打。", "words": [{"w": "凿得生疼;凿了三下", "t": ""}]}, {"meaning": "凿子。", "cites": [{"t": "其次用钻凿。", "b": "《汉书·刑法志》"}, {"t": "凿齿持盾。", "b": "《山海经·海外南经》"}, {"t": "释椎凿而上。", "b": "《庄子·天道》"}], "words": [{"w": "平凿;圆弧凿;菱形凿", "t": ""}]}, {"meaning": "古代用以施行黥刑的刑具。因指黥刑。", "cites": [{"t": "天下好知,而百姓求竭矣。于是乎锯制焉,绳墨杀焉,椎凿决焉。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2606wx','辉','1','huī','车','12','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从光。军声。本义:光;光辉)。"}, {"meaning": "同本义。", "cites": [{"t": "煇,光也。", "b": "《说文》"}, {"t": "庭燎有煇。", "b": "《诗·小雅·庭燎》"}, {"t": "故德煇动于内。", "b": "《礼记·乐记》"}, {"t": "观国之煇。", "b": "《汉书·韦玄成传》"}], "words": [{"w": "辉辉", "t": "光耀的样子"}, {"w": "辉烂", "t": "光辉灿烂"}, {"w": "辉风", "t": "光辉的风范"}, {"w": "辉容", "t": "光辉的仪容。"}]}, {"meaning": "晨光。", "cites": [{"t": "朝旦为辉,日中为光。", "b": "《三国志·魏志》"}]}, {"meaning": "产生光彩;照耀。", "cites": [{"t": "石韫玉而山辉,水怀珠而川媚。", "b": "陆机《文赋》"}], "words": [{"w": "辉丽", "t": "照亮"}, {"w": "辉张", "t": "发扬光大"}, {"w": "辉焕", "t": "照耀,映照。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2607wx','敞','1','chǎng','攵','12','','[{"pinyin": "chǎng", "defs": [{"meaning": "将高起的土地筑成平台,用以远望。"}, {"meaning": "同本义。", "cites": [{"t": "敞,平治高土,可以远望也。", "b": "《说文》"}]}, {"meaning": "显露;露出。", "cites": [{"t": "奇踪隐五百,一朝敞神界。", "b": "陶潜《桃花源诗》"}]}, {"meaning": "(形声。从攴(pū),尚声。本义:宽敞)。"}, {"meaning": "宽敞。", "cites": [{"t": "其母死,贫无以葬,然乃行营高敞地。", "b": "《史记·淮阴侯列传》"}, {"t": "中轩敞者为舱。", "b": "清·张潮《核舟记》"}], "words": [{"w": "敞平", "t": "宽阔平坦"}, {"w": "敞阔", "t": "宽阔清静。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2608wx','棠','1','táng','木','12','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从木,尚声。本义:乔木名) 同本义。甘棠,有红、白两种。白棠即棠梨。", "cites": [{"t": "棠,牡曰棠,牝曰杜。", "b": "《说文》"}, {"t": "野棠开尽飘香玉。", "b": "李洞《绣岭宫词》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2609wx','赏','1','shǎng','贝','12','','[{"pinyin": "shǎng", "defs": [{"meaning": "(形声。从贝,尚声。本义:赏赐;奖给)。"}, {"meaning": "同本义。", "cites": [{"t": "赏,赐有功也。", "b": "《说文》"}, {"t": "赏,上报下之功也。", "b": "《墨子经》"}, {"t": "三年有赏于大邦。", "b": "《易·未济》"}, {"t": "尧能赏均刑法。", "b": "《礼记·祭法》"}, {"t": "善人富谓之赏。", "b": "《左传·襄公二十八年》"}, {"t": "赏田。", "b": "《周礼·载师》"}, {"t": "宜付有司论其刑赏。", "b": "诸葛亮《出师表》"}, {"t": "未有封侯之赏。", "b": "《史记·项羽本纪》"}], "words": [{"w": "赏捞", "t": "赏赐捞劳"}, {"w": "赏口", "t": "供赏赐为奴仆的人口"}, {"w": "赏田", "t": "赏赐的田地"}, {"w": "赏首", "t": "第一个受赏者"}, {"w": "赏设", "t": "犒赏"}, {"w": "赏赣", "t": "赏赐"}, {"w": "赏地", "t": "赏赐田地。"}]}, {"meaning": "玩赏;欣赏。", "cites": [{"t": "奇文共欣赏,疑义相与析。", "b": "陶渊明《移居》"}, {"t": "杜郎俊赏,算而今重到须惊。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "赏遇", "t": "受到赏识礼遇"}, {"w": "赏月", "t": "赏玩月景"}, {"w": "赏鉴", "t": "欣赏;鉴赏"}, {"w": "赏会", "t": "玩赏聚会"}, {"w": "赏得", "t": "欣赏投合"}, {"w": "赏际", "t": "欣赏的趣味相投合。"}]}, {"meaning": "称颂,赞扬。", "cites": [{"t": "善则赏之。", "b": "《左传·襄公十四年》"}], "words": [{"w": "赞赏", "t": "赞美赏识"}, {"w": "赏激", "t": "赞赏鼓励"}, {"w": "赏纳", "t": "称赞结纳"}, {"w": "赏悦", "t": "称赏喜悦"}, {"w": "赏重", "t": "赏识尊重。"}]}, {"meaning": "尊重。", "cites": [{"t": "其所赏者,明圣也。", "b": "《管子·霸言》"}, {"t": "赏贤使能以次之。", "b": "《荀子·王霸》"}], "words": [{"w": "赏贤", "t": "尊重贤者。"}]}, {"meaning": "赐予或奖给的东西。", "cites": [{"t": "群臣吏民能面刺寡人之过者,受上赏。", "b": "《战国策·齐策》"}], "words": [{"w": "赏率", "t": "奖赏的标准"}, {"w": "赏私", "t": "礼物"}, {"w": "受赏;赏罚分明;赏金", "t": ""}]}, {"meaning": "量词。计量土地面积的单位。也作“晌”"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2610wx','掌','1','zhǎng','手','12','','[{"pinyin": "zhǎng", "defs": [{"meaning": "本义:手掌,手心。", "cites": [{"t": "掌,手中也。", "b": "《说文》"}, {"t": "指其掌。", "b": "《论语·八佾》"}, {"t": "易于反掌,安于泰山。", "b": "枚乘《谏吴王书》"}], "words": [{"w": "掌上", "t": "手掌之上。极言容易"}, {"w": "掌上观纹", "t": "比喻极其容易,毫不费力"}, {"w": "掌文", "t": "手掌纹路所呈现的近乎文字的形状。"}]}, {"meaning": "四足动物带爪的脚。", "cites": [{"t": "熊掌,亦我所欲也。", "b": "《孟子·告子上》"}]}, {"meaning": "用手掌打。", "cites": [{"t": "蹶松析,掌蒺藜。", "b": "扬雄《羽猎赋》"}], "words": [{"w": "掌嘴", "t": ""}]}, {"meaning": "主管,负责。", "cites": [{"t": "舜使益掌火,益烈山泽而焚之,禽兽逃匿。", "b": "《孟子·滕文公上》"}], "words": [{"w": "掌家", "t": "管家"}, {"w": "掌土", "t": "指掌管工部事务。因古代工部负责土木建造和水利工程等,故称"}, {"w": "掌文", "t": "掌管文翰"}, {"w": "掌计", "t": "掌握考核"}, {"w": "掌节", "t": "掌握节令"}, {"w": "掌选", "t": "主持选拔举荐"}, {"w": "掌礼", "t": "主持礼仪"}, {"w": "掌灶", "t": "主持烹调。"}]}, {"meaning": "支撑。", "cites": [{"t": "只觉头重身轻,满眼金星乱迸,实实掌不住。", "b": "《红楼梦》"}], "words": [{"w": "掌不住", "t": "支撑不住;忍不住。"}]}, {"meaning": "忍住。", "cites": [{"t": "连贾珍也掌不住笑了。", "b": "《红楼梦》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2611wx','晴','1','qíng','日','12','','[{"pinyin": "qíng", "defs": [{"meaning": "(形声。从日,青声。青古指蓝色,也有表意作用。《说文》作“夝”。意思是夜间(夕)雨止,出现星星。本义:雨止无云,天气晴朗) 同本义。", "cites": [{"t": "夝,雨而夜除星见也。从夕,生声。夜曰夕生。", "b": "《说文》"}, {"t": "夝,雨止无云也。", "b": "《苍颉篇》"}, {"t": "天,夝而见景星。", "b": "《汉书·天文志》"}, {"t": "微雨新晴,六合清朗。", "b": "潘岳《闲居赋》"}, {"t": "晴川历历汉阳树。", "b": "唐·崔颢《黄鹤楼》诗"}, {"t": "冬夏晴雨。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "为晴雪所洗。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "晴岚", "t": "晴日山中的雾气"}, {"w": "放晴", "t": "阴雨后转晴"}, {"w": "晴川", "t": "晴天下的江面"}, {"w": "晴日", "t": "晴天"}, {"w": "晴昊", "t": "晴空"}, {"w": "晴雪", "t": "天晴后的积雪"}, {"w": "晴虚", "t": "晴空。虚,太空。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2612wx','睐','1','lài','目','12','','[{"pinyin": "lài", "defs": [{"meaning": "瞳仁不正。", "cites": [{"t": "睐,目瞳子不正也。从目,来声。", "b": "《说文》"}]}, {"meaning": "旁视,斜视。", "cites": [{"t": "明眸善睐。", "b": "曹植《洛神赋》。李善注:“睐,旁视也。”"}]}, {"meaning": "眺望。", "cites": [{"t": "极目睐左阁,回顾眺右狭。", "b": "南朝宋·谢灵运《登上戍石鼓山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2613wx','暑','1','shǔ','日','12','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从日,者声。本义:炎热) 同本义。", "cites": [{"t": "暑,热也。", "b": "《说文》。暑近湿如蒸,热近燥如烘,"}, {"t": "一寒一暑。", "b": "《易·系辞》"}, {"t": "六月徂暑。", "b": "《诗·小雅·四月》"}, {"t": "土润溽暑。", "b": "《礼记·月令》"}, {"t": "寒暑燥湿风火。", "b": "《《素问·天玄纪大论》"}, {"t": "冬日则寒冻,夏日则暑伤。", "b": "《韩非子·人间训》"}, {"t": "乌兽稀毛,其性能暑。", "b": "晁错《言守边备塞疏》"}, {"t": "触风雨,犯寒暑,呼嘘毒疠,往往而死者相藉也。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "轻霜露而狎风雨,是故寒暑不能为之毒。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "暑溽", "t": "夏天闷热的气候"}, {"w": "暑岁", "t": "炎热干旱的年岁"}, {"w": "暑夏", "t": "炎热的夏季"}, {"w": "暑寒", "t": "天气炎热与寒冷"}, {"w": "暑湿", "t": "炎热潮湿。"}]}, {"meaning": "炎热的日子。", "cites": [{"t": "寒往则暑来,暑往则寒来。", "b": "《易·系辞下》"}, {"t": "寒暑不兼时而至。", "b": "《韩非子·显学》"}]}, {"meaning": "夏季。", "cites": [{"t": "寒暑易节,始一返焉。", "b": "《列子·汤问》"}, {"t": "杭有卖果者,善藏柑,涉寒暑不溃。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "暑月", "t": "夏月"}, {"w": "暑雨", "t": "夏季的雨"}, {"w": "暑伏", "t": "夏季中的伏时。是一年之中最热的时期"}, {"w": "暑雨祁寒", "t": "夏大雨,冬大寒"}, {"w": "暑夜", "t": "炎夏之夜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2614wx','最','1','zuì','曰','12','','[{"pinyin": "zuì", "defs": [{"meaning": "(会意。小篆字形,从冃(mào),从取。本义:冒犯夺取)。"}, {"meaning": "同本义。", "cites": [{"t": "最,犯而取之。从曰,从取。会意。", "b": ""}, {"t": "公既诸将一禀睿筭,与贼遌,最,遂下之。", "b": "明·刘三吾《许国襄简王公神道碑铭》"}]}, {"meaning": "聚,聚合。", "cites": [{"t": "得其常心,物所为最之哉?", "b": "《庄子·德充符》"}, {"t": "冬收五藏,最万物。", "b": "《管子·禁藏》。注:“最,聚也。”"}, {"t": "民举所最粟。", "b": "《管子·地数》"}]}, {"meaning": "总计;合计。", "cites": [{"t": "最其行能,多不及中。", "b": "《潜夫论》"}]}, {"meaning": "古代考核政绩或军功时划分的等级,以上等为最。跟“殿”相对。", "cites": [{"t": "犹无益于殿最也。", "b": "班固《答宾戏》。注:“上功曰最。”"}, {"t": "有里课之,最者,赐田典日旬。", "b": "《睡虎地秦墓竹简·厩苑律》"}], "words": [{"w": "最吏", "t": "表现特别,考绩最优的官吏"}, {"w": "最尤", "t": "特异,突出"}, {"w": "最吏", "t": "考绩优秀的官吏"}, {"w": "最殿", "t": "功绩最劣等者"}, {"w": "最课", "t": "官吏考课的最高成绩。"}]}, {"meaning": "假借为“绝”。表示程度,相当于“极”、“尤”。", "cites": [{"t": "秦之水泔最而稽。", "b": "《管子·水地》。注:“绝也。”"}, {"t": "中侯仍拜稽首受最。", "b": "《尚书》。注:“要言也。”"}, {"t": "最从高帝。", "b": "《史记·绛侯周勃世家》。索隐:“都凡也。”"}, {"t": "最下者与之争。", "b": "《史记·货殖列传》"}, {"t": "最爱湖东行不足。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "最喜小儿无赖,溪头卧剥莲蓬。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "最著前。(排在最前头。著,居于。)", "b": "《资治通鉴》"}, {"t": "最著者二。", "b": "清·侯方域《壮悔堂文集》"}], "words": [{"w": "我对他最了解;他熟悉情况,最有发言权;在班里数小李最会唱歌;最品", "t": "极品"}, {"w": "最能", "t": "最习于水性。能,习"}, {"w": "最启", "t": "最前头,最先进"}, {"w": "最殿", "t": "在最后面;最落后。"}]}, {"meaning": "首位。", "cites": [{"t": "都署之役为最。", "b": "孙文《序》"}, {"t": "课殿最以闻。", "b": "《汉书·宣帝纪》。注:“凡要之首也。”"}], "words": [{"w": "世界之最", "t": ""}]}, {"meaning": "凡要,即簿书的纲要、总目。", "cites": [{"t": "愿奉三年计最。", "b": "《汉书》"}], "words": [{"w": "最目", "t": "簿书的总目,总括文书内容的提要或目次"}, {"w": "最观", "t": "综观。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2615wx','晰','1','xī','日','12','','[{"pinyin": "xī", "defs": [{"meaning": "光亮。", "cites": [{"t": "日月沈晖,三光寝晰。", "b": "南朝宋·谢灵运《庐山慧远法师诔》"}], "words": [{"w": "晰晰", "t": "光亮的样子。"}]}, {"meaning": "清楚;明白。", "cites": [{"t": "钱献之辨之甚晰。", "b": "《清稗类钞》"}], "words": [{"w": "清晰", "t": "清楚"}, {"w": "十分明晰;晰毛辨发", "t": "连毛发也能清楚地分辨。形容析理入微。"}]}, {"meaning": "白,多指皮肤。", "cites": [{"t": "为人洁白晰。", "b": "《乐府诗集·陌上桑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2616wx','量','1','liáng liàng liang','里','12','','[{"pinyin": "liáng", "defs": [{"meaning": "(形声。本义:用量器计算容积或长度)。"}, {"meaning": "同本义。", "cites": [{"t": "量,称轻重也。", "b": "《说文》。段注:“称者,铨也。汉志曰:量者,所以量多少也。衡权者,所以均物平轻重也。此训量为称轻重者,有多少斯有轻重,视其多少可辜搉其重轻也,其字之所以从重也。”"}, {"t": "苦称量之不审也兮。", "b": "《楚辞·惜誓》"}, {"t": "为之斗斛以量之。", "b": "《庄子·胠箧》"}, {"t": "不量凿而正枘兮。", "b": "《楚辞·离骚》"}, {"t": "量入以为出。", "b": "《礼记·王制》"}], "words": [{"w": "比量", "t": "不用尺而用手、绳、棍等大概地量一量;比试"}, {"w": "量柴头数米角比喻做事小气吝啬,斤斤计较;量地", "t": "丈量土地"}, {"w": "量酒", "t": "量酒人,量酒博士。都指酒店中接待顾客的伙计"}, {"w": "量珠", "t": "以斗量明珠以买侍妾。后指纳妾为量珠之聘"}, {"w": "量视(衡量;看待)料量(计量", "t": ""}, {"w": "量校", "t": "以量器测定校核。"}]}, {"meaning": "衡量,酌量。", "cites": [{"t": "事君者量而后入。", "b": "《礼记·少仪》。注:“量其事意合成否。”"}, {"t": "量功名日,分财用,平板干。", "b": "《左传》"}, {"t": "则胜负之数,存亡之理,当与秦相较,或未易量。", "b": "苏洵《六国论》"}, {"t": "进步未可量。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "度德量力。", "b": "《三国志·诸葛亮传》"}, {"t": "量敌之众寡。", "b": "宋·王安石《答司马谏议书》"}, {"t": "量力而处之。", "b": "《资治通鉴》"}]}, {"meaning": "双。", "cites": [{"t": "未知一生当箸几量屐?", "b": "《世说新语·雅量》"}]}]}, {"pinyin": "liàng", "defs": [{"meaning": "量器,计算物体容积的器具,如斗斛一类的容器。", "cites": [{"t": "齐旧四量:豆、区、釜、钟。", "b": "《左传》"}], "words": [{"w": "量度", "t": "测量容量和长度的标准"}, {"w": "量鼓", "t": "古量器名。量可知斗斛之数;鼓是量器名。"}]}, {"meaning": "度量;器量。", "cites": [{"t": "上(皇上)少有大量。", "b": "李延寿《南史》"}], "words": [{"w": "量窄", "t": "气量狭小"}, {"w": "量浅", "t": "器量狭小"}, {"w": "量气", "t": "气量"}, {"w": "量识", "t": "识量,器量见识。"}]}, {"meaning": "容量,容受事物的限度。", "cites": [{"t": "唯酒无量,不及乱。", "b": "《论语·乡党》"}], "words": [{"w": "酒量;饭量;容量;量中", "t": "指满足一定数额。"}]}, {"meaning": "标准;规格。", "cites": [{"t": "黄金者,用之量也。", "b": "《管子·乘马》"}], "words": [{"w": "量度", "t": "计量多少和长短的标准。"}]}, {"meaning": "抱负。", "cites": [{"t": "瑜雅量高致。", "b": "《三国志》"}]}, {"meaning": "才华。", "cites": [{"t": "刘备以亮有殊量。", "b": "《三国志》"}]}, {"meaning": "估量;揣度。", "cites": [{"t": "蚍蜉撼大树,可笑不自量。", "b": "韩愈《调张籍诗》"}, {"t": "愿将军量力而处之。", "b": "《资治通鉴》"}], "words": [{"w": "量入为出;忖量;量抹", "t": "量视。轻视,蔑视"}, {"w": "量人", "t": "衡量长短,以至苛责于人"}, {"w": "量才称职", "t": "审量人的才能,授予适当的职务。"}]}, {"meaning": "料想。", "cites": [{"t": "自君别我后,人事不可量。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "量度", "t": "量忖。思量,考虑"}, {"w": "量他不敢来", "t": ""}]}]}, {"pinyin": "liang", "defs": [{"meaning": "——见“打量”(dǎliang);“掂量”(diāngliang)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2617wx','鼎','1','dǐng','鼎','12','','[{"pinyin": "dǐng", "defs": [{"meaning": "(象形。甲骨文字形,上面的部分象鼎的左右耳及鼎腹,下面象鼎足。本义:古代烹煮用的器物)。"}, {"meaning": "同本义 。盛行于商、周。用于煮盛物品,或置于宗庙作铭功记绩的礼器。统治者亦用作烹人的刑具。", "cites": [{"t": "鼎,三足两耳,和五味之宝器也。", "b": "《说文》"}], "words": [{"w": "鼎峙", "t": "比喻三方并峙,如鼎之三足"}, {"w": "鼎铉", "t": "指鼎"}, {"w": "鼎鼐", "t": "鼎、鼐均为古代炊具,用来调和五味。旧时用以比喻宰相治理国家。"}]}, {"meaning": "显赫,盛大。", "cites": [{"t": "高门鼎贵。", "b": "晋·左思《吴都赋》"}], "words": [{"w": "大名鼎鼎;鼎甲", "t": "豪门大族"}, {"w": "鼎姓", "t": "豪族,大姓"}, {"w": "鼎能", "t": "大才能。指能力超群,举世无匹"}, {"w": "鼎族", "t": "巨族,豪门贵族。"}]}, {"meaning": "变革。", "cites": [{"t": "鼎新麾一举,革故法三章。", "b": "李商隐《赠送前刘五经映》"}, {"t": "鼎革固天启。", "b": "徐浩《谒禹庙》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2618wx','喷','1','pēn pèn','口','12','','[{"pinyin": "pēn", "defs": [{"meaning": "(形声。从口,贲(bì或bēn)声。本义:怒叱)。"}, {"meaning": "同本义。", "cites": [{"t": "喷,咤也。", "b": "《说文》。徐灏注笺:“今俗语犹谓咤人曰喷。”"}]}, {"meaning": "泉水自地下涌出;喷出,喷射。", "cites": [{"t": "子不见夫唾者乎?喷则大者如珠,小者如雾,杂而下者不可胜数也。", "b": "《庄子》"}], "words": [{"w": "喷噀", "t": "喷出"}, {"w": "喷沫", "t": "喷涌泡沫"}, {"w": "喷沸", "t": "喷涌沸腾"}, {"w": "喷筒", "t": "旧时装火药以喷射的火器"}, {"w": "喷激", "t": "喷涌激荡"}, {"w": "喷蛆", "t": "詈词。乱扯,胡说。"}]}, {"meaning": "马嘘气或鼓鼻。", "cites": [{"t": "其马喷沙。", "b": "《穆天子传》"}], "words": [{"w": "喷吼", "t": "吐气长鸣"}, {"w": "喷振", "t": "谓禽兽鼓鼻喷气,振发。形容气势雄猛"}, {"w": "喷嘶((马)嘘气嘶叫)", "t": ""}]}]}, {"pinyin": "pèn", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2619wx','喳','1','zhā chā','口','12','','[{"pinyin": "zhā", "defs": [{"meaning": "(形声。从口,查声。本义:啁啾;震颤声)。"}, {"meaning": "同本义。", "cites": [{"t": "隔窗野鹊儿喳喳地叫。", "b": "《西厢记》"}], "words": [{"w": "喳喳", "t": "鸟鸣声;高叫声"}, {"w": "唧唧喳喳", "t": ""}]}, {"meaning": "下级(或仆人)对上级(或主人)的应诺声。", "cites": [{"t": "只见那家人连声应道:“喳!喳!”回头就去了。", "b": "《老残游记》"}]}]}, {"pinyin": "chā", "defs": [{"meaning": "低语声"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2620wx','晶','1','jīng','日','12','','[{"pinyin": "jīng", "defs": [{"meaning": "(会意。甲骨文字形,从三日,表示光亮之意。本义:光亮,明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "晶,精光也。", "b": "《说文》。徐灏曰:“晶即星之象形文。”"}, {"t": "天高日晶。", "b": "欧阳修《秋声赋》"}], "words": [{"w": "晶天", "t": "清澈明亮的天空"}, {"w": "晶沁", "t": "亮光透入"}, {"w": "晶英", "t": "光亮;闪亮"}, {"w": "晶波", "t": "闪亮的水波。"}]}, {"meaning": "清明;晴朗。", "cites": [{"t": "八月凉风天气晶,万里无云河汉明。", "b": "宋之问《明河篇》"}], "words": [{"w": "晶莹;晶天", "t": "澄澈明亮的天空。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2621wx','喇','1','lā lá lǎ la','口','12','','[{"pinyin": "lā", "defs": [{"meaning": "形容忽然发出的声音。", "words": [{"w": "忽喇喇", "t": ""}, {"w": "哗喇", "t": "象声词"}, {"w": "呼喇", "t": ""}]}]}, {"pinyin": "lá", "defs": [{"meaning": "流出来的口水。"}, {"meaning": "一半。"}]}, {"pinyin": "lǎ", "defs": [{"meaning": "唢呐的俗称", "words": [{"w": "喇叭", "t": "一种木管乐器,上细下粗,最下端的口部向四周扩张。"}, {"w": "扬声器", "t": "汽车喇叭。"}, {"w": "喇叭裤", "t": "裤脚大大地张开的裤子。"}, {"w": "喇伙", "t": "[方言]∶流氓结伙。"}, {"w": "喇嘛", "t": "藏语意为‘上师’。喇嘛教对僧侣的尊称。"}]}]}, {"pinyin": "la", "defs": [{"meaning": "形容食油或含油食物日久变坏的味道。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2622wx','遇','1','yù','辶','12','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从辵(chuò),禺(yù)声。本义:相逢,不期而会)。"}, {"meaning": "同本义。", "cites": [{"t": "遇,逢也。", "b": "《说文》"}, {"t": "遇主于巷。", "b": "《易·暌》。崔注:“遇者,不期而会。”"}, {"t": "乃遇汝鸠汝方。", "b": "《书·序》"}, {"t": "诸侯未及期相见曰遇。", "b": "《礼记·曲礼》"}, {"t": "子路从而后,遇丈人。", "b": "《论语》"}, {"t": "夏,公及宋公遇于清;遇者何?不期也。", "b": "《公羊传》"}], "words": [{"w": "遇庭", "t": "和父母相见"}, {"w": "遇人不淑", "t": "指女子嫁了不好的丈夫"}, {"w": "遇缺补正", "t": "指遇到员额出缺时,得补任为官。"}]}, {"meaning": "遭受。", "cites": [{"t": "遇人之艰难矣。", "b": "《诗·卫风·中谷有蓷》"}]}, {"meaning": "又。", "cites": [{"t": "遇人之不淑矣。", "b": ""}, {"t": "公等遇雨,皆已失期。", "b": "《史记·陈涉世家》"}], "words": [{"w": "遇厄", "t": "遭逢灾难"}, {"w": "遇疾", "t": "生病"}, {"w": "遇谗", "t": "遭受谗言的陷害"}, {"w": "遇谴", "t": "遭到谴责"}, {"w": "遇难", "t": "遭到灾难"}, {"w": "遇谤", "t": "遭到毁谤"}, {"w": "遇乱", "t": "遭遇战乱。"}]}, {"meaning": "对待、相待。", "cites": [{"t": "衔恩遇。", "b": "《广绝交论》"}, {"t": "公子遇臣厚。", "b": "《史记·魏公子列传》"}], "words": [{"w": "冷遇", "t": "冷淡的待遇"}, {"w": "礼遇", "t": "尊敬有礼的待遇"}, {"w": "优遇", "t": "优待。"}]}, {"meaning": "抵挡;对付。", "cites": [{"t": "无用吾之所短,遇人之所长。", "b": "《荀子·大略》"}], "words": [{"w": "遇敌", "t": "抵挡敌军;对付敌方。"}]}, {"meaning": "遇合;投合。", "cites": [{"t": "王何不与寡人遇。", "b": "《战国策·秦策》。注:“合也。”"}, {"t": "善仕不如遇合。", "b": "《史记·佞幸列传序》"}]}, {"meaning": "接触。", "cites": [{"t": "方今之时,臣以神遇,不以目视。", "b": "《庄子·养生主》"}, {"t": "木遇之而叶脱。", "b": "欧阳修《秋声赋》"}]}, {"meaning": "际遇;机会。", "cites": [{"t": "百世之良遇也。", "b": "三国吴·韦昭《博弈论》"}], "words": [{"w": "机遇", "t": "好的境遇;机会"}, {"w": "良遇", "t": "好机会。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2623wx','喊','1','hǎn','口','12','','[{"pinyin": "hǎn", "defs": [{"meaning": "(形声。从口,咸声。本义:尝味)。"}, {"meaning": "同本义。", "cites": [{"t": "狄牙能喊,狄牙不能齐不齐之口。", "b": "《法言·问神》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2624wx','遏','1','è','辶','12','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从辵(chuò),曷声。本义:抑制;阻止,阻拦)。"}, {"meaning": "阻止。", "cites": [{"t": "遏,止也。", "b": "《尔雅·释诂》"}, {"t": "君子以遏恶扬善。", "b": "《易·大有卦》"}, {"t": "夏王率遏众力。", "b": "《书·汤誓》"}, {"t": "胜殷遏刘。", "b": "《诗·周颂·武》"}, {"t": "式遏寇虐。", "b": "《诗·大雅·民劳》"}, {"t": "声振林木,响遏行云。", "b": "《列子·汤问》"}, {"t": "锄其直,遏其生气。", "b": "清·龚自珍《病梅馆记》"}, {"t": "到中流击水,浪遏飞舟。", "b": "毛泽东《沁园春·长沙》"}], "words": [{"w": "遏捺", "t": "按捺,遏止"}, {"w": "遏密", "t": "指皇帝死后禁绝演奏作乐"}, {"w": "遏讼", "t": "阻止诉讼"}, {"w": "遏塞", "t": "阻塞"}, {"w": "遏刘", "t": "抑制暴乱,阻止杀伐。"}]}, {"meaning": "断绝。", "cites": [{"t": "四海遏密八音。", "b": "《书·舜典》"}], "words": [{"w": "遏佚", "t": "断绝;丧失"}, {"w": "遏绝", "t": "诛灭;灭绝。"}]}, {"meaning": "伤害。", "cites": [{"t": "命之不易,无遏尔躬。", "b": "《诗·大雅·文王》"}]}, {"meaning": "遮拦;遮蔽。", "cites": [{"t": "扑击遏夺。", "b": "《吕氏春秋·安死》"}, {"t": "片善亦不遏。", "b": "孟郊《投所知》"}], "words": [{"w": "遏阳", "t": "遮阳"}, {"w": "遏逸", "t": "掩盖和丢弃"}, {"w": "遏隐", "t": "遮掩;掩盖。"}]}, {"meaning": "堰。", "cites": [{"t": "以嘉平二年,立遏于水…遏高一丈,东西长三十丈,南北广七十余步。", "b": "《水经注·鲍丘水》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2625wx','晾','1','liàng','日','12','','[{"pinyin": "liàng", "defs": [{"meaning": "(形声。从日,京声。本义:晒干)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2626wx','景','1','jǐng','日','12','','[{"pinyin": "jǐng", "defs": [{"meaning": "(形声。从日,京声。本义:日光)。"}, {"meaning": "同本义。", "cites": [{"t": "景,日光也。", "b": "《说文》"}, {"t": "浊明外景,清明内景。", "b": "《荀子·解蔽》"}, {"t": "四时和谓之景风。", "b": "《尔雅》"}, {"t": "南方景风。", "b": "《广雅》。按,犹日光风也。"}, {"t": "日出天而耀景。", "b": "江淹《别赋》"}, {"t": "朱光驰北陆,浮景忽西沈。", "b": "《文选·张载·七哀诗》"}, {"t": "流景曜之韡晔。", "b": "张衡《西京赋》"}, {"t": "景翳翳以将入。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "至若春和景明。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "景曜", "t": "光彩"}, {"w": "景光", "t": "亮光"}, {"w": "景焕", "t": "光彩照射"}, {"w": "景辉", "t": "光辉。"}]}, {"meaning": "风景,景致。", "cites": [{"t": "四时之景不同。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "正则无景。", "b": "清·龚自珍《病梅馆记》"}, {"t": "景状益近于自然。", "b": "蔡元培《图画》"}, {"t": "山水必自实景。", "b": ""}], "words": [{"w": "西湖十景;景儿", "t": "风景画"}, {"w": "景候", "t": "不同时候的景象"}, {"w": "景澄", "t": "风景清明"}, {"w": "景趣", "t": "由景色而生的情趣"}, {"w": "景语", "t": "诗词中描写景物的文字"}, {"w": "景概", "t": "景观"}, {"w": "秋景;晚景;夜景", "t": ""}]}, {"meaning": "景象;情况。", "cites": [{"t": "晚景之计如何?", "b": "《琵琶记》"}]}, {"meaning": "古代出门御尘的罩衣。", "cites": [{"t": "妇乘以几,姆加景,乃驱。", "b": "《仪礼》"}]}, {"meaning": "钟乳,即钟面上隆起的部分。"}, {"meaning": "中国山名。"}, {"meaning": "指河北省邯郸县境的景山。"}, {"meaning": "指河南省景山。"}, {"meaning": "仰慕。", "cites": [{"t": "何令人之景慕一至于此。", "b": "李白《与韩荆州书》"}], "words": [{"w": "景伏", "t": "敬仰信服"}, {"w": "景企", "t": "景仰企慕"}, {"w": "景附", "t": "旧附,随从"}, {"w": "景从", "t": "比喻紧密追随"}, {"w": "景佩", "t": "仰慕佩服。"}]}, {"meaning": "大的。", "cites": [{"t": "景星者,大星也。", "b": "《白虎通·封禅》"}, {"t": "承天景命。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "景业", "t": "大勋业。多指帝位"}, {"w": "景福", "t": "大福"}, {"w": "景山", "t": "大山;高山"}, {"w": "景功", "t": "大功"}, {"w": "景员", "t": "广大的疆域。员:幅员,疆界。"}]}, {"meaning": "祥瑞。", "cites": [{"t": "辛卯夜,若景光十有二期。", "b": "《汉书·武帝纪》"}], "words": [{"w": "景光", "t": "瑞祥的光气。也指恩德"}, {"w": "景云", "t": "瑞祥的云气"}, {"w": "景瑞", "t": "吉兆。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2627wx','畴','1','chóu','田','12','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从田,寿声。本义:已耕作的田地)。"}, {"meaning": "同本义。", "cites": [{"t": "畴,耕地也。", "b": "《苍颉篇》"}, {"t": "畴,耕治之田也。象耕屈之形。", "b": "《说文》"}, {"t": "取我田畴而伍之。", "b": "《左传·襄公三十年》"}, {"t": "田畴荒芜。", "b": "《国语·周语 》"}, {"t": "修农圃之畴。", "b": "《汉书·萧望之传》"}, {"t": "农人告余以春及,将有事于西畴。", "b": "陶渊明《归去来兮辞》"}], "words": [{"w": "田畴", "t": "田地"}, {"w": "畴陇", "t": "畦田;田亩。"}]}, {"meaning": "同类,类别", "cites": [{"t": "十日不食,无畴类尽死矣。", "b": "《管子·枢言》"}, {"t": "人与人相畴,家与家相畴。", "b": "《国语·齐语》。注:“畴,匹也。”"}, {"t": "夫物各有畴。", "b": "《战国策·齐策三》"}, {"t": "翼佐之功,超世无畴。", "b": "《三国志·董昭传》"}, {"t": "不畀洪范九畴。", "b": "《书·洪范》"}, {"t": "草木畴生,禽兽群焉,物各从其类也。", "b": "《荀子·劝学》"}], "words": [{"w": "范畴;畴类", "t": "同类;同辈"}, {"w": "畴偶", "t": "成对;两两相伴。"}]}, {"meaning": "壅土。", "cites": [{"t": "畴以肥壤。", "b": "《淮南子·俶真训》"}]}, {"meaning": "报酬,酬答", "cites": [{"t": "畴匹妇其已泰。", "b": "《文选·潘岳·西征赋》"}], "words": [{"w": "畴答", "t": "酬谢;用财物表示谢意"}, {"w": "畴劳", "t": "酬谢出力的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2628wx','践','1','jiàn','足','12','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从足,戋(jiān)声。本义:踩,践踏)。"}, {"meaning": "同本义。", "cites": [{"t": "践,履也。", "b": "《说文》"}, {"t": "践之者,籍之也。", "b": "《书大传》"}, {"t": "敦彼行苇,牛羊勿践履。", "b": "《诗·大雅·行苇》"}, {"t": "大夫、士入君门不践阈。", "b": "《礼记·曲礼上》"}, {"t": "鸟兽践啄。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "践踹", "t": "践踏"}, {"w": "践冰", "t": "踏在冰上。比喻处于危险之境"}, {"w": "践阼", "t": "踏上主阶,行主人之事"}, {"w": "践石", "t": "上马时的垫脚石。即“上马石”。"}]}, {"meaning": "履行;实现。", "cites": [{"t": "不足以践礼。", "b": "《仪礼·士相见礼》。注:“行也。”"}, {"t": "修身践言,谓之善行。", "b": "《礼记·曲礼》"}], "words": [{"w": "实践;践言", "t": "实践过去说过的话"}, {"w": "践信", "t": "践言,守信"}, {"w": "践修", "t": "履行和修治"}, {"w": "践盟", "t": "履行约定的事。"}]}, {"meaning": "登上,承袭。", "cites": [{"t": "周公践天子之位。", "b": "《礼记·明堂位》"}, {"t": "夫然后之中国,践天子位焉。", "b": "《孟子·万章上》"}], "words": [{"w": "践祚", "t": "登上王位。祚:君位"}, {"w": "践位", "t": "即位,登上帝位"}, {"w": "践极", "t": "登帝位。"}]}, {"meaning": "依循,顺着。", "cites": [{"t": "不践迹。", "b": "《论语》。孔注:“循也。”"}, {"t": "践墨隨敌,以决战事。", "b": "《孙子·九地》"}], "words": [{"w": "践墨", "t": "遵守规律、法律"}, {"w": "践绳", "t": "遵循法度规矩"}, {"w": "践期", "t": "遵循约定的期限"}, {"w": "践德", "t": "遵循道德规范。"}]}, {"meaning": "灭除。", "cites": [{"t": "成王既践奄,将其君于蒲姑。", "b": "《书·蔡仲之命》"}, {"t": "成王东伐淮夷,遂践奄。", "b": "《书·成王政(征)序》"}, {"t": "凡有血气之类弗身践也。", "b": "《礼记·玉藻》"}, {"t": "此文王之所以践妖也。", "b": "《韩诗外传·卷三》"}], "words": [{"w": "践灭", "t": "摧残,除灭"}, {"w": "践伐", "t": "剪伐,诛灭。"}]}, {"meaning": "凭借。", "cites": [{"t": "践华为城,因河为池。", "b": "汉·贾谊《新书·过秦论上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2629wx','跋','1','bá','足','12','','[{"pinyin": "bá", "defs": [{"meaning": "(形声。从足,犮(bó)声。本义:草中行走,越山过岭)。"}, {"meaning": "同本义。", "cites": [{"t": "文公躬擐甲胄,跋履山川。", "b": "《左传·成公十三年》"}, {"t": "跋涉山川,蒙犯霜露。", "b": "《左传·襄公二十八年》"}, {"t": "大夫跋涉,我心则怃。", "b": "《诗·鄘风 ·载驰》"}], "words": [{"w": "跋援", "t": "犹攀登"}, {"w": "跋履", "t": "登山涉水。"}]}, {"meaning": "扭转。", "cites": [{"t": "跋马望君非一度,冷猿秋雁不胜悲—严武《巴岭答杜二见忆》", "b": ""}], "words": [{"w": "跋马", "t": "勒紧马绳,使马回转。"}]}, {"meaning": "踏,踩。", "words": [{"w": "跋浪", "t": "踏浪;破浪"}, {"w": "跋足", "t": "踮起脚跟。"}]}, {"meaning": ""}, {"meaning": "", "cites": [{"t": "烛不见跋,尊客之前不叱狗,让食不唾。", "b": "《礼记·曲礼上》"}, {"t": "烛尽见跋。", "b": "《聊斋志异·邵女》"}]}, {"meaning": "文体的一种。附在正文之后。即后序。", "cites": [{"t": "后人题跋多盈巨轴矣。", "b": "《梦溪笔谈》"}], "words": [{"w": "跋尾", "t": "题写文字于书卷之后。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2630wx','跌','1','diē','足','12','','[{"pinyin": "diē", "defs": [{"meaning": "(形声。从足,失声。本义:失足摔倒)。"}, {"meaning": "同本义。", "cites": [{"t": "失蹑曰跌。", "b": "《通俗文》"}, {"t": "跌而不振。", "b": "《汉书·晁错传》。注:“足失据也。”"}, {"t": "若跌而据。", "b": "《淮南子·缪称》"}], "words": [{"w": "他跌伤了;跌磕", "t": "挫折,栽筋斗"}, {"w": "跌翻", "t": "跌倒,摔倒"}, {"w": "跌跌滚滚", "t": "跌交打滚的样子"}, {"w": "跌跌爬爬", "t": "连跌带爬"}, {"w": "跌坐", "t": "身体迅速坐下。"}]}, {"meaning": "失足。喻指犯过失。", "cites": [{"t": "一跌将赤吾之族。", "b": "《汉书·扬雄传》"}], "words": [{"w": "跌磕", "t": "受到挫折"}, {"w": "跌磕蹭蹬", "t": "倒霉;不顺利"}, {"w": "跌失", "t": "闪失"}, {"w": "跌蹼", "t": "喻指挫折和灾难。"}]}, {"meaning": "放荡不羁。", "cites": [{"t": "肆者何?跌也。", "b": "《公羊传·庄公二十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2631wx','跑','1','páo pǎo','足','12','','[{"pinyin": "páo", "defs": [{"meaning": "(形声。从足,包声。本义:兽用足刨地) 同本义。", "cites": [{"t": "滕公驾至东都门,马鸣跼不肯定,以足跑地久之。", "b": "《西京杂记》"}, {"t": "跑,足跑地也。", "b": "《广韵》"}]}]}, {"pinyin": "pǎo", "defs": [{"meaning": "急走。", "cites": [{"t": "跑,趵也。", "b": "《广雅·释言》"}, {"t": "红缰跑骏马,金镞掣秋鹰。", "b": "唐·马戴《边将》"}], "words": [{"w": "长跑", "t": "长距离跑步"}, {"w": "跑解马", "t": "表演马术"}, {"w": "跑冰", "t": "滑冰;溜冰"}, {"w": "跑竹马", "t": "民间娱乐活动之一种"}, {"w": "跑搭", "t": "奔走,奔忙"}, {"w": "跑路", "t": "奔走"}, {"w": "跑踏", "t": "奔走;奔忙。"}]}, {"meaning": "逃走;躲避。", "cites": [{"t": "你当真叫他回去,跑不了一顿饱打。", "b": "《老残游记》"}], "words": [{"w": "逃跑", "t": "逃走"}, {"w": "别让特务跑了;跑走", "t": "逃走;走掉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2632wx','跛','1','bǒ','足','12','','[{"pinyin": "bǒ", "defs": [{"meaning": "(形声。从足,皮声。本义:瘸,腿或脚有毛病)同本义。", "cites": [{"t": "跛,行不正也。", "b": "《说文》"}, {"t": "立毋跛。", "b": "《礼记·典礼上》"}, {"t": "眇能视,跛能履。", "b": "《易·履卦》"}, {"t": "此独以跛之故。", "b": "《淮南子·人间训》"}], "words": [{"w": "跛足", "t": "脚残废有病。同跛脚、瘸腿"}, {"w": "跛蹇", "t": "一脚残废"}, {"w": "跛蹩", "t": "跛行"}, {"w": "跛蹶", "t": "失足跌倒。"}]}, {"meaning": "瘸腿的人。", "cites": [{"t": "盲跛不能讲,死亡在迟速。", "b": "梅尧臣《田家语》"}], "words": [{"w": "眇跛", "t": "瞎子与瘸子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2633wx','遗','1','wèi yí','辶','12','','[{"pinyin": "wèi", "defs": [{"meaning": "给予;馈赠。", "cites": [{"t": "相遗以水。", "b": "《韩非子·五蠹》"}, {"t": "欲厚遗之。", "b": "《史记·魏公子列传》"}, {"t": "置币遗单于。", "b": "《汉书·李广苏建传》"}, {"t": "裘葛之遗。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "遗贼", "t": "给予戕害;遭害"}, {"w": "遗赂", "t": "赠送财物"}, {"w": "遗劳", "t": "馈赠;犒劳"}, {"w": "遗酌", "t": "济助"}, {"w": "遗送", "t": "赠送"}, {"w": "遗金", "t": "赠送金钱。"}]}, {"meaning": "送交;交付。", "cites": [{"t": "遗赵王书。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "遗魏王及公子书。", "b": "《史记·魏公子列传》"}, {"t": "遗权书曰。", "b": "《资治通鉴》"}, {"t": "以书遗操。", "b": ""}], "words": [{"w": "遗书", "t": "投书;寄信"}, {"w": "遗使", "t": "遣使"}, {"w": "遗秉", "t": "发放粮食"}, {"w": "遗大", "t": "赋予重大任务。"}]}, {"meaning": "输送。", "cites": [{"t": "强国之民,父遗其子,兄遗其弟,妻遗其夫,皆曰:“不得,无返!”", "b": "《商召书》"}]}, {"meaning": "加给。", "cites": [{"t": "王事敦我,政事一埤遗我。", "b": "《诗·邶风》"}]}]}, {"pinyin": "yí", "defs": [{"meaning": "(形声。从辵(chuò),贵声。本义:遗失)。"}, {"meaning": "同本义。", "cites": [{"t": "遗,亡也。", "b": "《说文》"}, {"t": "遗,离也。", "b": "《释言》"}, {"t": "不遐遗。", "b": "《易·泰》"}, {"t": "君惟不遗德刑。", "b": "《左伟·成公十六年》。注:“失也。”"}, {"t": "得人遗契者。", "b": "《列子·说符》。注:“弃也。”"}, {"t": "亡矢遗镞。", "b": "汉·贾谊《过秦论》"}, {"t": "羊子尝行路,得遗金一饼。", "b": "《后汉书·列女传》"}, {"t": "小学而大遗。", "b": "唐·韩愈《师说》"}, {"t": "行若遗。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "遗簪坠屡", "t": "失落的簪和鞋。比喻旧有的东西"}, {"w": "遗佚", "t": "散失亡佚"}, {"w": "遗逸", "t": "指散失之物"}, {"w": "遗宝", "t": "遗落的宝物"}, {"w": "遗简", "t": "失散的书籍。"}]}, {"meaning": "遗漏,因疏忽而漏掉。", "cites": [{"t": "刑过不避大臣,赏善不遗匹夫。", "b": "《韩非子》"}], "words": [{"w": "遗珠弃璧", "t": "喻遗弃俊才"}, {"w": "遗才", "t": "有才能而未被发现或重用的人"}, {"w": "遗贤", "t": "受埋没而不为世所知的贤人。"}]}, {"meaning": "遗弃;舍弃。", "cites": [{"t": "故旧不遗。", "b": "《论语·泰伯》"}, {"t": "必遗乎今。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "遗世", "t": "抛弃世事,避世"}, {"w": "遗荣", "t": "放弃荣华富贵,辞官归隐。"}]}, {"meaning": "不自主地排泄。", "cites": [{"t": "朔尝醉入殿中,小遗殿上。", "b": "《汉书》"}], "words": [{"w": "遗溺", "t": "遗尿。不自由的排尿"}, {"w": "遗精;遗溲", "t": "小便失禁。"}]}, {"meaning": "残存。留下。", "cites": [{"t": "地有遗利,民有余力。", "b": "汉·晁错《论贵粟疏》"}], "words": [{"w": "遗孽", "t": "残留下来的坏人"}, {"w": "遗噍", "t": "残存未死的人"}, {"w": "遗黎", "t": "亡国或改朝换代后不事新朝的人民。"}]}, {"meaning": "遗忘。", "cites": [{"t": "三日遗忘。", "b": "《汉书·刑法志》。注:“忽忘也。”"}, {"t": "审毫厘之小计,遗天下之大数。", "b": "《史记》"}], "words": [{"w": "遗失", "t": "遗忘;忘记"}, {"w": "遗倦", "t": "忘记疲倦。"}]}, {"meaning": "遗留。", "cites": [{"t": "因遗策。", "b": "汉·贾谊《过秦论》"}, {"t": "访其遗踪。", "b": "宋·苏轼《石钟山记》"}, {"t": "忠烈遗骸。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "遗安", "t": "指隐居田园,淡泊自守,不以官禄遗留子孙,而遗之以德行"}, {"w": "遗下", "t": "留下"}, {"w": "遗讥", "t": "让后人讥笑。"}]}, {"meaning": "堕,落下;下垂。", "cites": [{"t": "目眇眇而遗泣。", "b": "《楚辞》"}], "words": [{"w": "遗英", "t": "落花"}, {"w": "遗粒", "t": "遗落的谷粒"}, {"w": "遗坠", "t": "掉落。"}]}, {"meaning": "遗失之物。", "cites": [{"t": "高祖取楚如拾遗。", "b": "《汉书》"}, {"t": "道不拾遗。", "b": "《史记·商君列传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2634wx','蛙','1','wā','虫','12','','[{"pinyin": "wā", "defs": [{"meaning": "(形声。从虫,圭声。本义:田鸡类动物。青蛙) 同本义。", "cites": [{"t": "…苏俗谓之田鸡,扬州谓之水鸡,亦曰吠蛤。", "b": "《说文》"}, {"t": "听取蛙声一片。", "b": "宋·辛弃疾《西江月·夜行黄沙道中》"}], "words": [{"w": "蛙市", "t": "夜晚蛙群聚集而鸣,称为蛙市"}, {"w": "蛙吹", "t": "蛙鸣"}, {"w": "蛙角", "t": "将头发束起,形状宛如青蛙头上左右凸出而对称的部分"}, {"w": "蛙怒", "t": "形容青蛙叫声很大,有如鼓气发怒"}, {"w": "蛙蛤", "t": "蛙的一种。"}]}, {"meaning": "凹隐。扳着脸的样子。", "cites": [{"t": "那陈经济把脸儿蛙着不言语。", "b": "《金瓶梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2635wx','蛛','1','zhū','虫','12','','[{"pinyin": "zhū", "defs": [{"meaning": "蜘蛛。", "cites": [{"t": "蚁穿万孔萃,蛛挂千丝扰。", "b": "《次韵王子钦》"}], "words": [{"w": "蛛丝", "t": "蜘蛛吐出腹内分泌物而形成的丝"}, {"w": "蛛煤", "t": "蜘蛛网和烟尘"}, {"w": "蛛蝥", "t": "蜘蛛的别名"}, {"w": "蛛螫", "t": "毒害。"}]}]}]','jingmo-wenyan');
