INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2637wx','蜒','1','yán','虫','12','','[{"pinyin": "yán", "defs": [{"meaning": "蜿蜒,龙蛇爬行。", "cites": [{"t": "南有炎火千里,蝮蛇蜒只。", "b": "《楚辞》"}], "words": [{"w": "蜒蜒", "t": "龙蛇之类曲折爬行的样子"}, {"w": "蜒蜿", "t": "蜿蜒。龙蛇曲折爬行的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2638wx','蛤','1','gé há','虫','12','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从虫,合声。本义:蛤蜊) 同本义。产于浅海泥沙中,也可以人工养殖。肉可食。", "cites": [{"t": "民食果蓏蜯蛤,腥臊恶臭而伤腹胃,民多疾病。", "b": "《韩非子·五蠹》"}], "words": [{"w": "蛤子", "t": "小蛤蜊"}, {"w": "蛤蟹", "t": "蛤蜊与螃蟹"}, {"w": "蛤灰", "t": "以蚌蛤壳烧成的灰"}, {"w": "蛤像", "t": "蛤蛎的佛像"}, {"w": "蛤蛎", "t": "即蛤蜊。"}]}]}, {"pinyin": "há", "defs": [{"meaning": "", "words": [{"w": "蛤鱼", "t": "青蛙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2639wx','喝','1','hē hè','口','12','','[{"pinyin": "hē", "defs": [{"meaning": "(形声。从口,曷声。(yè)本义:声音幽咽。如:嘶喝。又指饮。特指饮酒) 饮。北方称饮为喝  。如:喝水;喝茶;喝汤;喝咖啡。"}, {"meaning": "用以表示惊讶。同“嗬”。"}]}, {"pinyin": "hè", "defs": [{"meaning": "大声喊叫。", "cites": [{"t": "喝声之幽也。", "b": "《广苍》"}, {"t": "嗌不喝。", "b": "《庄子·庚桑楚》"}], "words": [{"w": "呼幺喝六;喝神弄鬼", "t": "形容大喊大叫"}, {"w": "喝号", "t": "大声吆喝"}, {"w": "喝拳", "t": "高声划拳"}, {"w": "喝报", "t": "大声报告"}, {"w": "喝喊", "t": "呼喊。"}]}, {"meaning": "买卖时吆定商品的价钱。", "cites": [{"t": "主人家接来,解开包袱,逐疋翻看一过,将称准一准,喝定价格,递与一个客人。", "b": "《醒世恒言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2640wx','鹃','1','juān','鸟','12','','[{"pinyin": "juān", "defs": [{"meaning": "(形声。从鸟,肙(yuān)声。本义:鸟名,即杜鹃)又名郭公、杜宇、布谷、子规。一种常见的鸟,上体灰褐色,下体白色而具暗色横斑,其显著特点是双音节叫声,并把卵产于别的鸟巢中为它代孵,吃毛虫,是益鸟。", "words": [{"w": "鹃血", "t": "传说杜鹃啼声凄苦,日夜不停,甚至口中流血。常比喻悲怨之深"}, {"w": "鹃魂", "t": "借指冤魂"}, {"w": "鹃啼", "t": "形容思念之苦或悲怨极深。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2641wx','喂','1','wèi','口','12','','[{"pinyin": "wèi", "defs": [{"meaning": "(餵、喂是近代的“餧”字) 喂食。", "cites": [{"t": "餧,饲也。", "b": "《玉篇》"}, {"t": "季春之月,餧兽之药,毋出九门。", "b": "《礼记·月令》"}, {"t": "如以肉餧虎。", "b": "《汉书·张耳陈馀传》"}, {"t": "骥不骤进而求服兮,凤亦不贪餧而妄食。", "b": "《楚辞·九辩》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2642wx','喘','1','chuǎn','口','12','','[{"pinyin": "chuǎn", "defs": [{"meaning": "(形声。从口,耑(duān)声。本义:喘息,急速地呼吸)。"}, {"meaning": "同本义。", "cites": [{"t": "喘,疾息也。", "b": "《说文》"}, {"t": "其发咳喘。", "b": "《素问·五常正大论》"}, {"t": "牛喘吐舌。", "b": "《汉书·丙吉传》"}, {"t": "喘喘然将死。", "b": "《庄子·大宗师》"}], "words": [{"w": "心跳气喘;累得直喘;喘喝", "t": "中气不顺,口鼻有声的样子"}, {"w": "喘乏", "t": "气喘困乏。"}]}, {"meaning": "轻声说话。", "cites": [{"t": "礼义以为文,伦类以为理,喘而言。", "b": "《荀子·臣道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2643wx','喉','1','hóu','口','12','','[{"pinyin": "hóu", "defs": [{"meaning": "喉头。", "cites": [{"t": "喉,咽也。", "b": "《说文》"}, {"t": "喉咽者,量肠之府也。", "b": "《后汉书·马融传》"}, {"t": "断其喉。", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "喉吻", "t": "喉头与嘴唇"}, {"w": "喉头气 ", "t": "因生气发怒而感到喉头憋闷"}, {"w": "喉韵", "t": "饮茶后喉头产生的甘爽的回味。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2644wx','喻','1','yù','口','12','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从口,俞声。本义:告知,把情况通知某人。同“谕”)。"}, {"meaning": "同本义。", "cites": [{"t": "喻,告也。", "b": "《广雅》"}, {"t": "教之以利,而喻诸德者也。", "b": "《礼记·文王世子》"}, {"t": "[灌婴]乃留兵屯荥阳,使使喻齐王及诸侯与连和,以待吕氏之变而诛之。", "b": "《史记》"}]}, {"meaning": "晓喻;开导。", "cites": [{"t": "前后告喻,曾无悛改。", "b": "《三国志》"}], "words": [{"w": "喻勉", "t": "开导勉励"}, {"w": "喻教", "t": "开导教育。"}]}, {"meaning": "知晓;明白。", "cites": [{"t": "君子喻于义。", "b": "《论语·里仁》。皇疏:“喻,晓也。”"}, {"t": "单足以喻则单。", "b": "《荀子·正名》。注:“喻,晓也。”"}, {"t": "以喻客意。", "b": "《后汉书·杜笃传》"}, {"t": "征于色,发于声,而后喻。", "b": "《孟子·告子下》"}], "words": [{"w": "家喻户晓;喻旨", "t": "知晓旨意"}, {"w": "喻愿", "t": "对某事明白并乐于为之"}, {"w": "喻以利害;劝喻;不可以理喻", "t": ""}]}, {"meaning": "比喻。", "cites": [{"t": "罕譬而喻。", "b": "《礼记·学记》"}, {"t": "在于早谕教。", "b": "《汉书·贾谊传》"}, {"t": "不足以喻其美。", "b": "《警世通言》"}], "words": [{"w": "喻名", "t": "比称;形容"}, {"w": "喻为“生物树”", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2645wx','啼','1','tí','口','12','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从口,帝声。本义:放声痛心地哭)。"}, {"meaning": "同本义。", "cites": [{"t": "嗁,号也。", "b": "《说文》。段注:“号,痛声也。”"}, {"t": "见人方引婴儿欲投之江中,婴儿啼。", "b": "《吕氏春秋·察今》"}, {"t": "妇啼一何苦。", "b": "唐·杜甫《石壕吏》"}, {"t": "忽啼求之。", "b": "宋·王安石《伤仲永》"}, {"t": "儿醒大啼。", "b": "《虞初新志·秋声诗自序》"}, {"t": "含乳啼。", "b": ""}, {"t": "儿惧,啼告母。", "b": "《聊斋志异·促织》"}], "words": [{"w": "啼呼", "t": "哭叫,叫唤"}, {"w": "啼饥", "t": "因饥饿而号哭"}, {"w": "啼天哭地", "t": "非常悲惨"}, {"w": "啼咽", "t": "悲哽。"}]}, {"meaning": "叫鸣。", "cites": [{"t": "自在娇莺恰恰啼。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "千里莺啼绿映红。", "b": "唐·杜牧《江南春绝句》"}, {"t": "渌水荡漾清猿啼。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "虎啸猿啼。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "啼叫;啼唤", "t": "鸣叫"}, {"w": "啼唱", "t": ""}]}, {"meaning": "哭泣。", "cites": [{"t": "儿含乳啼声。", "b": "林嗣环《口技》"}], "words": [{"w": "啼哭郎君", "t": "指办事无能,只知啼哭了事者。"}]}, {"meaning": "眼泪  。", "words": [{"w": "啼妆女", "t": "形容女子姿色迷人。东汉时,妇女以粉拭目下,有似哭啼泪痕,故名"}, {"w": "啼眼", "t": "泪眼"}, {"w": "啼痕", "t": "泪痕"}, {"w": "啼妆", "t": "借指美人的泪痕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2646wx','喧','1','xuān','口','12','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从口,宣声。“宣”有“宣扬”义,也有表义作用。本义:声音大而嘈杂)。"}, {"meaning": "同本义。", "cites": [{"t": "喧,大语也。", "b": "《玉篇》"}, {"t": "结庐在人境,而无车马喧。", "b": "陶潜《饮酒》"}, {"t": "上林催猎响,河桥争渡喧。", "b": "北周·庚信《同州还》"}, {"t": "夜风一何喧,大舶双橹。", "b": "宋·王安石《金山寺》"}, {"t": "蛙蛤徒自喧,蛟龙卧如蛰。", "b": "陆游《喜雨》"}], "words": [{"w": "喧议", "t": "喧闹议论"}, {"w": "喧埃", "t": "尘世的喧嚷"}, {"w": "喧吓", "t": "喧哗恐吓"}, {"w": "喧卑", "t": "喧闹低下"}, {"w": "喧哄", "t": "喧闹。"}]}, {"meaning": "显赫。", "cites": [{"t": "赫兮喧兮者,威仪也。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2647wx','嵌','1','qiàn','山','12','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。本义:山谷深的样子)。"}, {"meaning": "张开的样子。", "cites": [{"t": "金人仡仡其承钟虚兮,嵌岩岩其龙鳞。", "b": "《文选·扬雄·甘泉赋》"}, {"t": "嵌岩窦穴。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "山洞,岩洞。", "cites": [{"t": "结庐就嵌窟,剪苕通径行。", "b": "唐·孟浩然《游明禅师西山兰若》"}], "words": [{"w": "嵌岩", "t": "山中的洞穴"}, {"w": "嵌窟;嵌窦", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2648wx','幅','1','fú','巾','12','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从巾,畐(fú)声。从“巾”表示与布帛有关。声符“畐”训“满”(参“福”字条),在字中亦兼有表义作用。布帛的宽度(广)与“满”有相通之处,故可以引申。本义: 布帛的宽度)。"}, {"meaning": "同本义。古制一幅为二尺二寸。今为布帛、呢绒等宽度的通称。", "cites": [{"t": "幅,布帛广也。", "b": "《说文》"}, {"t": "布帛二尺二寸为幅。", "b": "《汉书·食货志》"}, {"t": "半幅终幅。", "b": "《仪礼·士丧礼》。注:“半幅一尺,终幅二尺。”"}, {"t": "邪幅在下。", "b": "《诗·小雅·采菽》。注:“邪缠束,故名邪幅。”"}, {"t": "幅巾。", "b": "《后汉书·符融传》。注:“以一幅为之。”"}], "words": [{"w": "单幅,双幅;宽幅的白布;幅裂", "t": "像布幅一样割裂"}, {"w": "幅巾", "t": "古代用全幅细绢裹头的头巾。男子用以束发,也叫幞头"}, {"w": "幅练", "t": "成幅的白练。"}]}, {"meaning": "引申指地面或书画面的广狭。", "cites": [{"t": "幅陨既长。", "b": "《诗·商颂·长发》"}, {"t": "幅者,所以正曲枉也。", "b": "《列女传·母仪》"}, {"t": "即连楮为巨幅,广二丈,大书一“屈”字。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "篇幅;振幅", "t": ""}]}, {"meaning": "指布帛或纸张。", "cites": [{"t": "其男子衣以横幅,但结束相连,略无缝缀。", "b": "《晋书》"}]}, {"meaning": "覆盖,用东西遮在…上面。", "cites": [{"t": "一茎竹稿剔船尾,两幅青幕幅船头。", "b": "白居易《泛小舱》"}]}, {"meaning": "古称富贵寿考为福。", "cites": [{"t": "幅陨既长,有娀方将。", "b": "《诗·商颂·长发》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2649wx','帽','1','mào','巾','12','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从巾,冒声。巾是丝织品,表示材料。字本作“月”,象帽形,又作“冒”。本义:帽子)。"}, {"meaning": "同本义。", "cites": [{"t": "少年见罗敷,脱帽著帩头。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "帽凭", "t": "盈满的样子"}, {"w": "帽正", "t": "帽子前缘正中的装饰,一般为珠或玉"}, {"w": "帽襻儿", "t": "帽子上布制的扣纽带"}, {"w": "礼帽", "t": "跟礼服相配的帽子"}, {"w": "帽套", "t": "加于帽外的衣饰"}, {"w": "帽钉", "t": "即铆钉。因其头形如帽,故名。"}]}, {"meaning": "形状或作用像帽子或各种保护头部的物件。", "cites": [{"t": "投笔掷帽丁丁然,磨墨隆隆然。", "b": "《聊斋志异·口技》:注。此指笔套。"}], "words": [{"w": "笔帽", "t": "套在笔头上保护笔的套儿"}, {"w": "安全帽;螺钉帽", "t": ""}]}, {"meaning": "戴帽。", "cites": [{"t": "见人头未帽。", "b": "陆龟蒙《南泾渔夫》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2650wx','赋','1','fù','贝','12','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从贝,武声。从“贝”,表示与财物有关。本义:征收)。"}, {"meaning": "同本义。", "cites": [{"t": "赋,敛也。", "b": "《说文》"}, {"t": "赋,税也。", "b": "《广雅》"}, {"t": "厥赋惟上上错。", "b": "《书·禹贡》。传:“谓土地所生,以供天子。”"}, {"t": "七赋之所养。", "b": "《法言·问道》"}, {"t": "而令贡赋。", "b": "《小司徒》。注:“谓出车徒给徭役也。”"}, {"t": "太医以王命聚之,岁赋其二。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "赋银", "t": "征收税银"}, {"w": "赋粟", "t": "征收田赋"}, {"w": "赋里", "t": "征收商业税"}, {"w": "赋币", "t": "征收财物。"}]}, {"meaning": "缴纳赋税。", "cites": [{"t": "讼者平,赋者均。", "b": "唐·柳宗元《送薛存义序》"}], "words": [{"w": "赋金", "t": "交纳税款。"}]}, {"meaning": "给予;授予。", "cites": [{"t": "出高库之兵以赋民。", "b": "《吕氏春秋》"}, {"t": "为百姓困乏献其田宅者二百三十人,以口赋贫民。", "b": "《汉书·平帝纪》"}, {"t": "公属百官,赋职任功。", "b": "《国语·晋语》"}], "words": [{"w": "赋命", "t": "天所授予的命运;给予生命"}, {"w": "赋给", "t": "分配发给"}, {"w": "赋食", "t": "布散饮食"}, {"w": "赋政", "t": "颁布政令"}, {"w": "赋质", "t": "上天赋予的资质"}, {"w": "赋灵", "t": "天赋的灵性,生性"}, {"w": "赋就", "t": "天生的"}, {"w": "赋禀", "t": "天生具有的智能、性情"}, {"w": "赋职", "t": "授与职事。"}]}, {"meaning": "做诗。", "cites": [{"t": "一言均赋,四韵俱成。", "b": "唐·王勃《滕王阁序》"}, {"t": "衔觞赋诗,以乐其志。", "b": "晋·陶渊明《五柳先生传》"}]}, {"meaning": "诵读;吟咏。", "cites": [{"t": "不歌而诵谓之赋。", "b": "《汉书·艺文志》"}, {"t": "公入而赋。", "b": "《左传·隐公元年》"}, {"t": "公子赋《河水》,公赋《六月》。", "b": "《左传·僖公二十三年》"}, {"t": "登东皋以舒啸,临清流而赋诗。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "赋诗", "t": "吟诗;写诗"}, {"w": "赋笔", "t": "写诗用的笔"}, {"w": "赋声", "t": "善于辞赋的名声"}, {"w": "赋咏", "t": "创作和吟诵诗文。"}]}, {"meaning": "陈述。", "cites": [{"t": "纵豆蔻词工,青楼梦好,难赋深情。", "b": "宋·姜夔《扬州慢》"}]}, {"meaning": "颁布。", "cites": [{"t": "明命使赋。", "b": "《诗·大雅·丞民》"}]}, {"meaning": "又。", "cites": [{"t": "赋政于外。", "b": ""}]}, {"meaning": "田赋;赋税。", "cites": [{"t": "以九赋敛财贿。", "b": "《周礼·太宰》"}, {"t": "薄赋敛,广畜积。", "b": "汉·晁错《论贵粟疏》"}]}, {"meaning": "又。", "cites": [{"t": "取于有余,以供上用,则贫民之赋可损。", "b": ""}, {"t": "未若复吾赋不幸之甚也。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "赋算", "t": "赋税"}, {"w": "赋徭", "t": "赋税与徭役"}, {"w": "赋钱", "t": "税钱"}, {"w": "赋禄", "t": "赋税与禄赏"}, {"w": "赋租", "t": "赋税,租税。"}]}, {"meaning": "特指民赋,即征收的兵车、武器、衣甲或银钱。", "cites": [{"t": "税以足食,赋以足兵。", "b": "《汉书·刑法志》"}, {"t": "千乘之国,可使治其赋也。", "b": "《论语·公治长》"}, {"t": "乘白马而过关,则顾白马之赋。", "b": "《韩非子·外储说左上》"}, {"t": "不腆敝赋。", "b": "《左传·成公二年》"}]}, {"meaning": "徭役;兵役。", "cites": [{"t": "敞邑以赋。", "b": "《左传·隐公四年》。注:“兵也。以田赋出兵,故谓之赋。”"}], "words": [{"w": "贡赋", "t": "贡品和徭役。"}]}, {"meaning": "兵,军队。", "cites": [{"t": "千乘之国,可使治其赋也。", "b": "《论语·公冶长》"}], "words": [{"w": "赋舆", "t": "指兵车;泛指军事"}, {"w": "王赋", "t": "王军。"}]}, {"meaning": "中国古代文体,盛行于汉魏六朝,是韵文和散文的综合体,通常用来写景叙事,也有以较短篇幅抒情说理的。", "cites": [{"t": "乃重修岳阳楼,增其旧制,刻唐贤今人诗赋于其上。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "乃作《怀沙》之赋。", "b": "汉·司马迁《屈原贾生列传》"}], "words": [{"w": "赋客", "t": "善于作辞赋的人"}, {"w": "赋韵", "t": "指分韵作诗"}, {"w": "赋论", "t": "辞赋和议论文"}, {"w": "赋铭", "t": "辞赋和铭文"}, {"w": "赋歌", "t": "辞赋和歌曲"}, {"w": "赋颂", "t": "赋和颂。两种文体。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2651wx','赌','1','dǔ','贝','12','','[{"pinyin": "dǔ", "defs": [{"meaning": "(形声。从贝,者声。本义:用财物作注比输赢)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2652wx','赎','1','shú','贝','12','','[{"pinyin": "shú", "defs": [{"meaning": "(形声。左形,右声。本义:用财物换回人或抵押品)。"}, {"meaning": "同本义。", "cites": [{"t": "宋人以兵车百乘,文马百驷,以赎华元于郑。", "b": "《左传·宣公二年》"}, {"t": "其时传说也更加纷繁,说他可以赎出的也有。", "b": "《为了忘却的纪念》"}], "words": [{"w": "赎生", "t": "购买生物来放生"}, {"w": "赎票", "t": "出钱赎回被匪徒绑走的肉票。"}]}, {"meaning": "用财物脱罪或抵免过失。", "cites": [{"t": "骞后期当斩,赎为庶人。", "b": "《汉书·张骞传》。又如:赎刑(用财物抵免刑罚);赎命(以财物营救犯人,使脱免刑罚);赎锾(用钱赎罪;赎罪的金钱);赎钱(赎罪的钱);赎银(用以赎罪的银钱);赎绢(赎罪用的绢帛);赎庸(出钱以免除劳役)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2653wx','赐','1','cì','贝','12','','[{"pinyin": "cì", "defs": [{"meaning": "(形声。从贝,易声。从“贝”,表示与钱财有关。本义:赏赐)。"}, {"meaning": "给予;上给予下。", "cites": [{"t": "赐,予也。", "b": "《说文》"}, {"t": "上予下曰赐。", "b": "《正字通》"}, {"t": "长者赐,少者贱者不敢辞。", "b": "《礼记·曲礼》"}, {"t": "策勋十二转,赏赐百千强。", "b": "《乐府诗集·木兰诗》"}, {"t": "大王及宗室所赐币帛,尽以与军吏、士大夫。", "b": "刘向《列女传·赵将括母》"}, {"t": "若从君惠而免之,三年将拜君赐。", "b": "《左传》"}], "words": [{"w": "赐光", "t": "赏脸,赏光"}, {"w": "赐环", "t": "将放逐之臣赦罪召还"}, {"w": "赐第", "t": "皇上敕建的府第"}, {"w": "赐田", "t": "君主所赐予的田地"}, {"w": "赐官", "t": "赐予设置家臣以治家邑的权力。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2654wx','赔','1','péi','贝','12','','[{"pinyin": "péi", "defs": [{"meaning": "(形声。从贝,咅(pǒu)声。“贝”是古代货币,与财产买卖有关。本义:补还损失)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2655wx','黑','1','hēi','黑','12','','[{"pinyin": "hēi", "defs": [{"meaning": "(会意。小篆字形,上面是古“囱”字,即烟囱;下面是“炎”(火)字,表示焚烧出烟之盛。合起来表示烟火熏黑之意。本义:黑色)。"}, {"meaning": "同本义。", "cites": [{"t": "黑,火所熏之色也。", "b": "《说文》"}, {"t": "纯黑而反哺者,谓之乌。", "b": "《小尔雅》"}, {"t": "坤为黑。", "b": "《易·说卦》"}, {"t": "黑气乃辱。", "b": "《素问·气交变大论》"}, {"t": "郑公孙黑。", "b": "《左传·襄公二十九年》"}, {"t": "楚公子黑肱。", "b": "《左传·昭公元报》"}, {"t": "大夫黑弓,礼也。", "b": "《荀子·大略》"}], "words": [{"w": "黑气", "t": "黑色的水气"}, {"w": "黑章", "t": "黑色的花纹"}, {"w": "黑麻", "t": "黑色的胡麻"}, {"w": "黑眸", "t": "黑色的眸子"}, {"w": "黑斑", "t": "黑色的斑点"}, {"w": "黑参参", "t": "黑乎乎。"}]}, {"meaning": "昏暗无光。", "cites": [{"t": "天阴黑。", "b": "《资治通鉴·唐纪》"}, {"t": "月黑见渔灯。", "b": "清·查慎行《舟夜书所见》诗"}], "words": [{"w": "黑处", "t": "暗处,光线不明的地方"}, {"w": "黑狱", "t": "暗无日光的牢房"}, {"w": "黑天黑地", "t": "天地一片漆黑"}, {"w": "黑塔窟", "t": "昏暗的样子。"}]}, {"meaning": "黑色物质、物体。"}, {"meaning": "黑色黍米。", "cites": [{"t": "冬,王使周公阅来聘,飨有昌襡、白、黑、形盐。", "b": "《左传》"}]}, {"meaning": "黑色的猪羊。", "cites": [{"t": "来方禋祀,以其骍黑。", "b": "《诗·小雅·大田》。毛传:“骍,牛也。黑,羊豕也。”"}]}, {"meaning": "黑龙江省的简称。"}, {"meaning": "说…的坏话,诽谤 。 如: 黑了良心。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2656wx','铸','1','zhù','钅','12','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从金,寿声。甲骨文字形,会意。上面是双手拿“鬲”(lì,古炊具),下面是“皿”;鬲、皿表熔化金属的锅炉。中间象被熔铸的金属。小篆变为形声字。本义:铸造)。"}, {"meaning": "同本义 。锤炼,雕琢金属或以液态非金属材料(如塑料)浇制成器的统称。", "cites": [{"t": "铸以为金人。", "b": "汉·贾谊《过秦论》"}, {"t": "以精铜铸成。", "b": "《后汉书·张衡传》"}], "words": [{"w": "铸印", "t": "铸造金属印章"}, {"w": "铸冶", "t": "销冶金属铸造器物"}, {"w": "铸兵", "t": "铸造兵器"}, {"w": "铸作", "t": "铸造"}, {"w": "铸金", "t": "熔铸金属成物"}, {"w": "铸铜", "t": "炼铜。"}]}, {"meaning": "造就。", "cites": [{"t": "或曰:“人可铸与?”曰:“孔子铸颜渊矣。”", "b": "《法言·学行》"}], "words": [{"w": "铸人", "t": "造就人才"}, {"w": "铸颜", "t": "比喻培养或造就人才。"}]}, {"meaning": "锤炼;雕琢。", "cites": [{"t": "虽取熔经意,亦自铸伟辞。", "b": "《文心雕龙》"}], "words": [{"w": "铸词", "t": "锤炼文辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2657wx','铺','1','pū pù','钅','12','','[{"pinyin": "pū", "defs": [{"meaning": "(形声。从金,甫声。本义:衔门环的底座。又称“铺首”)。"}, {"meaning": "同本义。", "cites": [{"t": "铺,箸门铺首也。", "b": "《说文》"}, {"t": "挤玉户以撼金铺兮。", "b": "司马相如《长门赋》"}, {"t": "金琐银铺。", "b": "何晏《景福殿赋》"}, {"t": "铜龟蛇铺首鸣。", "b": "《汉书·哀帝纪》"}, {"t": "金铺交映。", "b": "西晋·左思《蜀都赋》"}], "words": [{"w": "铺手", "t": "铺首。"}]}, {"meaning": "铜器名。豆属。其上为一平的直壁浅盘。铺与豆的区别在于它没有细长的把柄,在盘下连铸一较宽的高圈足。", "cites": [{"t": "铺,亦古器名,有公刘铺,有天尹养铺,形亦如簠,但簠方而铺圆耳。", "b": "明·杨慎《丹铅总录》"}]}, {"meaning": "把东西展开或摊平。", "cites": [{"t": "铺,陈也。", "b": "《广雅》"}, {"t": "铺敦淮汶。", "b": "《诗·大雅·常武》"}, {"t": "引笔铺纸。", "b": "唐·白居易《与元九书》"}], "words": [{"w": "铺房", "t": "指旧俗在婚期前一日,女方派人到婿家去铺设卧房"}, {"w": "铺眉苫眼", "t": "装模作样"}, {"w": "铺苫", "t": "铺展,铺垫"}, {"w": "铺堆", "t": "堆;装"}, {"w": "铺陈", "t": "指被褥等卧具"}, {"w": "铺排", "t": "铺叙;铺陈"}, {"w": "铺腾", "t": "铺张;挥霍;喷;散发"}, {"w": "铺张扬厉", "t": "形容过分铺张,讲穷排场。"}]}, {"meaning": "安排,摆设。", "cites": [{"t": "铺时绎思。", "b": "《左传·宣公十二年》"}], "words": [{"w": "铺派", "t": "安排。"}]}, {"meaning": "披挂;覆盖。", "cites": [{"t": "闲铺羽服居仙窟,自着金莲造化功。", "b": "唐·吕岩《七言》"}]}]}, {"pinyin": "pù", "defs": [{"meaning": "商店。俗作“铺”。", "cites": [{"t": "铺,贾肆也。", "b": "《韵会》"}, {"t": "铺,俗作舖。", "b": "《正字通》"}], "words": [{"w": "饭铺;杂货铺;当铺;铺家", "t": "店家,商店"}, {"w": "铺席", "t": "店铺;商店;商人"}, {"w": "铺行", "t": "店铺和商行"}, {"w": "铺舍", "t": "指商店"}, {"w": "匠人铺", "t": "制造或修理物品或机械的店"}, {"w": "铁匠铺", "t": ""}]}, {"meaning": "驿站。古代传递公文和投递信件的地方。现多用于地名。", "cites": [{"t": "元制,设急递铺,以达四方文书之往来。", "b": "《元史·兵志四》"}], "words": [{"w": "铺司", "t": "古代负责掌理公文邮件等传送事宜的官员"}, {"w": "铺兵", "t": "古代担任传送公文、邮件的兵士"}, {"w": "铺舍", "t": "古代掌理传送公文邮件的处所"}, {"w": "铺马", "t": "驿站中专门传送皇帝诏书的马匹"}, {"w": "铺递", "t": "传送公文的驿站。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2658wx','链','1','liàn','钅','12','','[{"pinyin": "liàn", "defs": [{"meaning": "(形声。从金,连声。(liàn)本义:铅矿)。"}, {"meaning": "链条。", "cites": [{"t": "今人以锒铛之类相连属者为链。", "b": "《六书故》"}], "words": [{"w": "铁链;锁链", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2659wx','销','1','xiāo','钅','12','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从金,肖声。本义:熔化金属)。"}, {"meaning": "同本义。", "cites": [{"t": "销,铄金也。", "b": "《说文》"}, {"t": "销车以斗七命。", "b": "《淮南子·泛论》"}, {"t": "收天下兵,聚之咸阳,销以为钟鐻。", "b": "《史记·秦始皇本纪》"}, {"t": "销锋镐。", "b": "汉·贾谊《过秦论》"}, {"t": "今出黄金银物百五十种,千八百余斤,销冶以供军用。", "b": "《三国志·魏志》"}, {"t": "女娲销炼五色石以补苍天。", "b": "《论衡·谈天》"}], "words": [{"w": "销冶", "t": "熔炼,熔铸,熔冶"}, {"w": "销炼", "t": "熔化冶炼"}, {"w": "销钱", "t": "熔化钱币。"}]}, {"meaning": "溶化;消融。", "cites": [{"t": "雪霜顿销释,土脉膏且黏。", "b": "唐·韩愈《苦寒》"}, {"t": "一天大事,竟如此瓦解冰销。", "b": "《官场现形记》"}]}, {"meaning": "清失;消除;消散。", "cites": [{"t": "是圣人仆也,是自埋于民,自藏于畔,其声销,其志无穷。", "b": "《庄子·则阳》"}, {"t": "销忧者莫若酒。", "b": "《汉书·东方朔传》"}, {"t": "夫明者起福于无形,销患于未然。", "b": "《汉书·刘向传》"}], "words": [{"w": "销患", "t": "化除祸患。也作“销祸”"}, {"w": "销距", "t": "化除敌人的抵抗。"}]}, {"meaning": "耗尽,毁灭。", "cites": [{"t": "薰以香自烧,膏以明自销。", "b": "《汉书·龚胜传》"}], "words": [{"w": "销刃", "t": "销毁兵刃"}, {"w": "销化", "t": "消失而化为无形"}, {"w": "销失", "t": "即“消失”"}, {"w": "销沉", "t": "消失沉没。指时光的流逝。"}]}, {"meaning": "排遣,打发。", "cites": [{"t": "饱食醉酒,忽忽无事,以此销日,以此终年。", "b": "北齐·颜之推《颜氏家训》"}], "words": [{"w": "销日", "t": "排遣时间"}, {"w": "销夏", "t": "排遣炎热的夏天。"}]}, {"meaning": "衰敝;衰残。", "cites": [{"t": "周公遗化销微,孔氏庠序衰坏。", "b": "《汉书·地理志下》"}], "words": [{"w": "销乏", "t": "疲劳;消耗;亏损;衰败"}, {"w": "销志", "t": "意志渐趋消沉,无法乐观。"}]}, {"meaning": "消耗,耗费。", "cites": [{"t": "典了庄宅,卖了田土,销乏了几多钱物。", "b": "《冤家债主》"}, {"t": "他就只好背了家具到外边和别的匠人碰个伙,顾个零花销。", "b": "《李家庄的变迁》"}], "words": [{"w": "销缴", "t": "开销;花费;注销交纳"}, {"w": "销算", "t": "决算,计算收支总帐。"}]}, {"meaning": "注销。", "cites": [{"t": "民户之受害者莫甚于已纳重追,皆由案吏不相关照,乡胥不与销豁。", "b": "元·胡太初《昼帘绪论》"}], "words": [{"w": "销豁", "t": "注销豁免。"}]}, {"meaning": "卖,出售。", "cites": [{"t": "我游上海考书肆,群书何者销流多?", "b": "康有为《闻菽园居士欲为政变说部诗以速之》"}], "words": [{"w": "经销", "t": ""}]}, {"meaning": "古代的一种刀。", "cites": [{"t": "羊头之销,虽水断龙舟,…", "b": "《淮南子》"}]}, {"meaning": "生铁。", "cites": [{"t": "屠者弃销而锻者拾之,所缓急异也。", "b": "《淮南子》"}]}, {"meaning": "生丝缯;帆网。", "cites": [{"t": "连弩以射,销车以斗。", "b": "《淮南子·泛论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2660wx','锁','1','suǒ','钅','12','','[{"pinyin": "suǒ", "defs": [{"meaning": "(形声)。"}, {"meaning": "置于可启闭的器物上,以钥匙或暗码(如字码机构、时间机构、自动释放开关、磁性螺线管等)打开的扣件。", "cites": [{"t": "柄铁折叠环复,如锁上练,引之长丈许。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "锁管", "t": "锁簧插入的锁身"}, {"w": "锁孔", "t": "锁眼"}, {"w": "锁梃儿", "t": "锁的销子"}, {"w": "上锁", "t": ""}]}, {"meaning": "一种用铁环钩连而成的刑具。", "cites": [{"t": "若见鬼把椎锁绳纆,立守其旁。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "锁靠", "t": "束缚手腕的刑具"}, {"w": "锁韁", "t": "枷锁和韁绳。"}]}, {"meaning": "链子。", "cites": [{"t": "俄有赤龙长千余尺,电目血舌,朱鳞火鬣,项掣全锁,锁牵玉柱,千雷万霆,激绕其身。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "锁子", "t": "锁链"}, {"w": "锁甲", "t": "锁子铠,锁子错甲,即锁子甲。"}]}, {"meaning": "加锁,用锁锁住。", "cites": [{"t": "长安布衣淮比数,反锁衡门守环堵。", "b": "唐·杜甫《秋雨叹》"}], "words": [{"w": "锁闭", "t": "加锁关闭"}, {"w": "锁禁", "t": "关锁禁闭"}, {"w": "锁锢", "t": "关销禁闭"}, {"w": "锁院", "t": "科举考试时,为防作弊,封锁试场之门,称为“锁院”。宋代有机密则锁闭院门上奏。因又称机密之奏为锁院。"}]}, {"meaning": "束缚。", "cites": [{"t": "僧辩既入,背泉而坐,曰:“鲍郎有罪,令旨使我锁卿,卿勿以故意见期。”因出令示泉,锁之床下。", "b": "《梁书·鲍泉传》"}], "words": [{"w": "锁缚", "t": "用铁链或绳索捆缚"}, {"w": "锁索", "t": "用铁链系束"}, {"w": "锁士", "t": "囚禁的士人。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2661wx','锄','1','chú','钅','12','','[{"pinyin": "chú", "defs": [{"meaning": "(形声。从金,助声。本义:锄头。一种长柄农具,其刀身平薄而横装,专用于中耕、除草、疏松植株周围的土壤) 同本义。", "cites": [{"t": "纵有健妇把锄犁,禾生陇亩无东西。", "b": "杜甫《兵车行》"}], "words": [{"w": "大锄;小锄", "t": ""}]}, {"meaning": "用锄头整理田地,除草。", "cites": [{"t": "大儿锄豆溪东,中儿正织鸡笼。", "b": "辛弃疾《清平乐·村居》"}], "words": [{"w": "锄社", "t": "古代北方农村的一种组织。平时协同耕作,有事时则互相帮助"}, {"w": "锄耘", "t": "耕作农地。也作鉏耘"}, {"w": "锄谷", "t": "耕作。"}]}, {"meaning": "根除,铲除。", "cites": [{"t": "又不可使天下之民斫直,删密,锄正,以夭梅病梅为业以术钱也。", "b": "龚自珍《病梅馆记》"}], "words": [{"w": "锄拔", "t": "去除"}, {"w": "锄理", "t": "清理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2662wx','锅','1','guō','钅','12','','[{"pinyin": "guō", "defs": [{"meaning": "(形声。从金,咼(kuā)声。本义:炊事用具,圆形中凹,多用铁制)。"}, {"meaning": "车釭。即车轴外面的铁圈。", "cites": [{"t": "车釭,燕、齐、海、岱之间谓之锅。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2663wx','锈','1','xiù','钅','12','','[{"pinyin": "xiù", "defs": [{"meaning": "金属表面所生的氧化物。", "cites": [{"t": "鏽,铁生衣也。", "b": "《集韵》"}, {"t": "刀子锈用木贼草擦之,则锈自落。", "b": "《物类相感志》"}], "words": [{"w": "锈彩", "t": "古金属的锈斑。"}]}, {"meaning": "锈病 。植物受真菌类锈菌寄生而引起的一种病害,此病害对农林生产危害很大。"}, {"meaning": "生锈。", "cites": [{"t": "令人感激坐流涕,锈涩短刀何足云。", "b": "宋·欧阳修《日本刀歌》"}], "words": [{"w": "锁锈了;螺丝钉锈得厉害;锈涩", "t": "生锈"}, {"w": "锈蚀", "t": "生锈剥蚀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2664wx','锋','1','fēng','钅','12','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。从金,夆fēng声。本义:刀、剑等的尖端或锐利部分)。"}, {"meaning": "同本义。", "cites": [{"t": "底厉锋锷。", "b": "《汉书·萧望之传》"}], "words": [{"w": "锋端", "t": "指刀剑等兵器的刃口"}, {"w": "锋镝", "t": "刀刃和箭头。泛指武器"}, {"w": "锋锷", "t": "锋刃。泛指刀剑。"}]}, {"meaning": "借指刀、剑等有刃的兵器。", "cites": [{"t": "且天下锐精持锋欲为陛下所为者甚众。", "b": "《史记·淮阴侯列传》"}], "words": [{"w": "锋钲", "t": "利剑和铜钲"}, {"w": "锋栝", "t": "刀与箭。引申为战争"}, {"w": "锋矢", "t": "刀和箭。"}]}, {"meaning": "泛指器物尖锐犀利的部分。", "cites": [{"t": "方家以磁石磨针锋,则能指南。", "b": "《梦溪笔谈》"}], "words": [{"w": "针锋;笔锋;锋毫", "t": "毛笔的尖端。"}]}, {"meaning": "队伍的前列。", "cites": [{"t": "布常为军锋。", "b": "《史记·黥布列传》"}], "words": [{"w": "锋行", "t": "军队的先锋。"}]}, {"meaning": "昆虫名。比喻众多。", "cites": [{"t": "今三年之间,灾异锋起,大小毕具。", "b": "《汉书·谷永传》"}]}, {"meaning": "用锋翻地。", "cites": [{"t": "凡秋收之后…速锋之,地垣润泽而不坚硬。", "b": "《齐民要术》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2665wx','锌','1','xīn','钅','12','','[{"pinyin": "xīn", "defs": [{"meaning": "一种蓝白色的晶状的二价金属元素,有低至中等的硬度,纯时有延性,主要用作钢铁的保护性涂层 ——元素符号Zn。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2666wx','锐','1','ruì','钅','12','','[{"pinyin": "ruì", "defs": [{"meaning": "(形声。从金,兑声。本义:芒)。"}, {"meaning": "同本义。", "cites": [{"t": "锐,芒也。", "b": "《说文》。段玉裁注:“芒者,草耑也。”"}]}, {"meaning": "精锐的军队或士卒。", "cites": [{"t": "赵王出轻锐以寇其后,秦数不利。", "b": "《战国策》"}, {"t": "瑜等率轻锐继其后。", "b": "《资治通鉴》"}]}, {"meaning": "锐气,勇往直前的气势。", "cites": [{"t": "武夫奋略,战士讲锐。", "b": "蔡邕《释诲》"}]}, {"meaning": "锐利的兵器。", "cites": [{"t": "夫被坚执锐,义不如公。", "b": "《史记》"}, {"t": "将军身披坚执锐。", "b": "《史记·陈涉世家》"}]}, {"meaning": "锋利。", "cites": [{"t": "锐,利也。", "b": "《广雅》"}, {"t": "锐喙决吻。", "b": "《周礼·考工记》"}, {"t": "长其尾而锐其剽者邪?", "b": "《荀子·赋》"}, {"t": "柔而不刚,锐而不挫。", "b": "《淮南子·时则训》"}], "words": [{"w": "锐兵", "t": "犀利的兵器"}, {"w": "锐锋", "t": "利刃"}, {"w": "锐居", "t": "锐利,锋利"}, {"w": "锐喙", "t": "尖利的嘴巴。"}]}, {"meaning": "精锐。", "cites": [{"t": "秦特出锐师取地而韩随之。", "b": "《韩非子·存韩》"}], "words": [{"w": "锐旅", "t": "精锐部队"}, {"w": "锐士", "t": "精锐的兵士"}, {"w": "锐卒", "t": "精锐的士卒"}, {"w": "锐师", "t": "精锐的军队"}, {"w": "锐器", "t": "精良锐利的兵器"}, {"w": "锐骑", "t": "精锐勇猛的骑兵。"}]}, {"meaning": "勇猛;急速。", "cites": [{"t": "其进锐者,其退速。", "b": "《孟子·尽心上》"}], "words": [{"w": "锐悍", "t": "勇猛强悍"}, {"w": "锐将", "t": "勇猛善战的将领"}, {"w": "锐景", "t": "迅疾的身影"}, {"w": "锐进", "t": "迅速进军"}, {"w": "锐很", "t": "猛烈而倔强"}, {"w": "锐果", "t": "快速而果敢。"}]}, {"meaning": "急切。", "cites": [{"t": "夫进取之情锐,而安民之誉迟,是故侵百姓以利己者,在位所不惮。", "b": "陆机《五等诸侯论》"}]}, {"meaning": "坚定,坚决。", "cites": [{"t": "是时,上方征讨四夷,锐志武功,不暇留意礼文之事。", "b": "《汉书·礼乐志》"}], "words": [{"w": "锐意;锐志", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2667wx','甥','1','shēng','生','12','','[{"pinyin": "shēng", "defs": [{"meaning": "(形声。从男,生声。本义:姐妹的儿子)。"}, {"meaning": "同本义。", "cites": [{"t": "甥,谓我舅者,我谓之甥。", "b": "《说文》"}, {"t": "舅谓姊妹之子曰甥。甥亦生也。出配他男而生,故其制字男傍作生也。", "b": "《释名》"}, {"t": "青阳,方雷氏之甥也。", "b": "《国语·晋语》"}, {"t": "余宗老涂山,左公甥也。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "甥徒", "t": "外甥辈"}, {"w": "甥孙", "t": "姊妹之孙"}, {"w": "甥婿", "t": "外甥和女婿;外甥女婿"}, {"w": "甥舅", "t": "外甥和舅舅,亦指女婿和岳父。"}]}, {"meaning": "古代为姑之子、舅之子、妻之兄弟、姊妹之夫的通称。", "cites": [{"t": "妻党。姑之子为甥,舅之子为甥,妻之兄弟为甥,姊妹之夫为甥。", "b": "《尔雅·释亲》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2668wx','掰','1','bāi','手','12','','[{"pinyin": "bāi", "defs": [{"meaning": "张开。", "cites": [{"t": "我时常掰着嘴儿说一阵,劝一阵,哭一阵!", "b": "《红楼梦》"}], "words": [{"w": "掰脸", "t": "翻脸"}, {"w": "掰交情", "t": "使交情破裂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2669wx','短','1','duǎn','矢','12','','[{"pinyin": "duǎn", "defs": [{"meaning": "(会意。从矢,豆声。从“矢”,表示短不短可以用矢来量。古代弓长箭短,量长的用弓作标准,量短的用箭作标准。本义:不长)。"}, {"meaning": "同本义 。指两端距离小。与“长”相对。指空间或指时间。", "cites": [{"t": "短,有所长短,以矢为正。", "b": "《说文》。按,短,不长也。"}, {"t": "以其长见与短见也。", "b": "《吕氏春秋·长见》。注:“近也。”"}, {"t": "帝尧长,帝舜短,文王长,周公短,仲尼长,子弓短。", "b": "《荀子·非相》"}, {"t": "老臣以媪为长安君计短也。", "b": "《战国策·赵策》"}], "words": [{"w": "短趁", "t": "打短工"}, {"w": "短盘驴子", "t": "短途来往的驴子"}, {"w": "短盘", "t": "分段作短程行走"}, {"w": "短票", "t": "借贷的凭证,借约"}, {"w": "短绠", "t": "短绳。比喻才学浅薄"}, {"w": "短梦", "t": "短暂的梦。"}]}, {"meaning": "寿命短促。", "cites": [{"t": "凶短折。", "b": "《书·洪范》。郑注:“未冠曰短。”"}], "words": [{"w": "短局促", "t": "短卒律,短古取。短促"}, {"w": "短岁", "t": "短命,早死。"}]}, {"meaning": "浅薄,简陋。", "cites": [{"t": "问之人以穷其短。", "b": "清·刘开《问说》"}], "words": [{"w": "短才", "t": "智慧低下或才智笨拙的人"}, {"w": "短笔", "t": "自谦文笔拙劣。同拙笔"}, {"w": "短供", "t": "指粗简的菜肴。"}]}, {"meaning": "引申为不足,缺乏。", "cites": [{"t": "西人长火器而短技击。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "不短钱花;短头", "t": "缺德;有罪;至少"}, {"w": "短乏", "t": "犹贫乏"}, {"w": "短欠", "t": "少;欠缺"}, {"w": "短吃少穿", "t": "谓衣食困乏。"}]}, {"meaning": "指摘缺点,揭发过失。", "cites": [{"t": "令尹子兰闻之,大怒,卒使上官大夫短屈原于顷襄王。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "短恶", "t": "揭短,说坏话"}, {"w": "短毁", "t": "谗言中伤"}, {"w": "短状", "t": "检查书,供状。"}]}, {"meaning": "指短路。拦路抢夺。", "cites": [{"t": "看他穿的袄子布衫靴子帽,则怕有短路的。", "b": "明·徐伯株《贫富兴衰记》"}]}, {"meaning": "缺点;过失。", "cites": [{"t": "兼百花之长而各去其短。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "短儿", "t": "过失;隐私;缺点"}, {"w": "短道儿", "t": "坏主意"}, {"w": "短话", "t": "关于别人缺点,错失的话"}, {"w": "揭短;取长补短", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2670wx','智','1','zhì','日','12','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意兼形声。从日,从知,知亦声。“知”的后起字。本义:聪明,智力强) 同本义。", "cites": [{"t": "然后智生于忧患。", "b": "《荀子》引《孟子》"}, {"t": "甚智其子。", "b": "《韩非子·说难》"}, {"t": "不可谓智。", "b": "《墨子·公输》"}, {"t": "智术浅短。", "b": "《三国志·诸葛亮传》"}, {"t": "少年智则国智。", "b": "清·梁启超《少年中国说》"}], "words": [{"w": "智赛隋何,机强陆贾", "t": "二人均为汉、楚时代智囊人物。意为聪明经顶,灵活异常"}, {"w": "智数", "t": "才智;见识。"}]}, {"meaning": "智慧,智谋。", "cites": [{"t": "智,烛也。", "b": "《法言·脩身》"}, {"t": "智,性也。", "b": "《韩非子·显学》"}, {"t": "智者,心之府也。", "b": "《淮南子·俶真》"}, {"t": "四时能变谓之智。", "b": "《管子》"}, {"t": "凡人之智,能见已然,不能见将然。", "b": "贾谊《治安策》"}], "words": [{"w": "智着", "t": "智慧;知识"}, {"w": "才智", "t": "智慧和才能"}, {"w": "智刃", "t": "智慧之刃。"}]}, {"meaning": "计谋;策略。", "cites": [{"t": "道德上通而智故消灭也。", "b": "《淮南子·览冥》。注:“智故,巧诈也。”"}], "words": [{"w": "智计", "t": "计谋;智谋"}, {"w": "智术", "t": "指君主通晓控制和使用臣下的策略、手段"}, {"w": "智量", "t": "计策,计谋"}, {"w": "智算", "t": "谋划,计算"}, {"w": "智虑", "t": "智谋;谋划。"}]}, {"meaning": "知识。", "cites": [{"t": "所以知之在人者谓之知。知有所合谓之智。", "b": "《荀子》"}]}, {"meaning": "智士。有智慧的人。", "cites": [{"t": "语曰:“仁不轻绝,智不轻怨。”", "b": "《战国策》"}], "words": [{"w": "智地", "t": "智士集中之地。"}]}, {"meaning": "春秋时晋国地名 ,在今山西省永济县北。"}, {"meaning": "知道,认识。", "cites": [{"t": "狗犬不智其名也。", "b": "《墨子·经说下》"}, {"t": "而不智也。", "b": "《墨子·号令》"}, {"t": "得此六者而君父不智也。", "b": "《管子·法法》。王念孙云:“智与知同。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2671wx','氮','1','dàn','气','12','','[{"pinyin": "dàn", "defs": [{"meaning": "一种普通的非金属元素,原子序数7,游离态的氮通常为无色、无嗅、无味的不溶性双原子惰性气体,约占空气的78%(按体积计) ——元素符号N。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2672wx','毯','1','tǎn','毛','12','','[{"pinyin": "tǎn", "defs": [{"meaning": "厚实有毛绒的织品。", "cites": [{"t": "毯,毛席。", "b": "《广韵》。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2673wx','氯','1','lǜ','气','12','','[{"pinyin": "lǜ", "defs": [{"meaning": "卤族的一种普遍非金属一价和高价元素,其最熟知的形式是重的、绿黄色、难闻的刺激性有毒气体 ——元素符号Cl。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2674wx','鹅','1','é','鸟','12','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从鸟,我声。本义:家禽名。头大,喙扁阔,颈长,尾短。羽毛为白色或黑色)。"}, {"meaning": "同本义。鸭科中一明确亚科的鸟 ,亲缘关系是在天鹅和鸭之间,额部有橙黄色或黑褐色肉质突起,有一高的稍扁平的嘴,腿中等长,身体通常较鸭大,颈也较鸭长。"}, {"meaning": "鹅骄(形容像鹅一般高傲);。"}, {"meaning": "鹅顶椅(靠背高的椅子);。"}, {"meaning": "鹅眼(古代钱币名称。魏时所锖);。"}, {"meaning": "鹅头(讹头。讹诈,敲竹杠);。"}, {"meaning": "鹅项懒凳(狭长的矮凳);。"}, {"meaning": "鹅梨角儿(形容像鹅梨一样的发髻);。"}, {"meaning": "鹅掌鸭信(鹅趾掌,鸭舌头。可做名菜)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2675wx','剩','1','shèng','刂','12','','[{"pinyin": "shèng", "defs": [{"meaning": "(形声。从刀,乘声。本义:剩余;余下)。"}, {"meaning": "同本义。", "cites": [{"t": "一屠晚归,担中肉尽,止有剩骨。", "b": "《聊斋志异·狼三则》"}, {"t": "使野无闲田,民无剩力。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "剩员", "t": "多余的人员"}, {"w": "剩语", "t": "多余的话"}, {"w": "剩货", "t": ""}]}, {"meaning": "多。", "cites": [{"t": "且容侬,多种竹,剩栽梅。", "b": "宋·方岳《最高楼》"}]}, {"meaning": "表示程度,相当于“更”、“更加”。", "cites": [{"t": "剩,盖也。", "b": "《字汇》"}]}, {"meaning": "表示无条件限制,相当于“尽管”。", "cites": [{"t": "老去风情应不到,凭君剩把芳尊倒。", "b": "宋·欧阳修《蝶恋花》"}]}, {"meaning": "余留下来  所剩无几;给你剩多少?。"}, {"meaning": "阉割。", "cites": [{"t": "拟供厨者宜剩之。剩法,生十余日,用布裹齿脉碎之。", "b": "《齐民要术》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2676wx','稍','1','shāo shào','禾','12','','[{"pinyin": "shāo", "defs": [{"meaning": "(形声。从禾,肖声。本义:禾末)。"}, {"meaning": "同本义。", "cites": [{"t": "稍,出物有渐也。", "b": "《说文》。按,此字当训禾末,与秒为谷芒者别。"}], "words": [{"w": "稍秣", "t": "给牛马吃的草料。"}]}, {"meaning": "俸禄,官吏的薪水。", "cites": [{"t": "均其稍食。", "b": "《周礼·内宰》。注:“吏禄禀也。”"}, {"t": "今诸生学于太学,县官日有廪之供。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "稍食", "t": "月俸,按月而给的廪食"}, {"w": "稍饩", "t": "月俸,廪食"}, {"w": "稍房", "t": "堆放稻粮的屋子。"}]}, {"meaning": "逐渐。", "cites": [{"t": "献孝之后,稍以蚕食六国。", "b": "《史记·秦楚之际月表》"}, {"t": "稍,渐也。", "b": "《汉书·郊祀志》集注"}, {"t": "渐渐,犹稍稍也。", "b": "《一切经音义》"}, {"t": "吏稍侵辱之。", "b": "《汉书·周勃传》"}, {"t": "稍出近之,慭慭然,莫相知。", "b": "唐·柳宗元《三戒》"}, {"t": "其后稍蚕食魏。", "b": "《史记·魏公子列传》"}], "words": [{"w": "稍杀", "t": "渐衰;稍差。"}]}, {"meaning": "略微;稍微。", "cites": [{"t": "稍,稍小也。", "b": "《广雅》"}, {"t": "门人弟子填其室,未尝稍降辞色。", "b": "明·宋濂《送东阳马生序》"}, {"t": "乃使人复葺南阁子,其制稍异于前。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "稍姑", "t": "稍微,姑且"}, {"w": "稍胜一筹;稍息", "t": "略微休养生息;略微停止;小憩;歇息一会儿"}, {"w": "产品的质量稍差了些,要注意保证质量;这大衣稍长了一点", "t": ""}]}, {"meaning": "表示范围,相当于“只”、“但”。", "cites": [{"t": "山豁何时断,江平不肯流。稍知花改岸,始验鸟随舟。", "b": "杜甫《陪王使君晦日泛江》"}]}, {"meaning": "表示程度深,相当于“颇”、“甚”。", "cites": [{"t": "姐姐稍亲文墨,君瑞博通今古。", "b": "董解元《西厢记诸宫调》"}]}, {"meaning": "小。", "cites": [{"t": "凡王之稍事,设荐脯醢。", "b": "《周礼·天官·膳夫》"}]}]}, {"pinyin": "shào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2677wx','程','1','chéng','禾','12','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从禾,呈声。本义:称量谷物,并用作度量衡的总名)。"}, {"meaning": "度量衡的总称。", "cites": [{"t": "按度程。", "b": "《礼记·月令》"}, {"t": "程者,物之准也。", "b": "《荀子·致仕》"}]}, {"meaning": "法式;章程,规格。", "cites": [{"t": "张苍定章程。", "b": "《汉书·高帝纪》"}], "words": [{"w": "章程", "t": "书面写定的组织规程或办事条例"}, {"w": "程考", "t": "按科举常规考试"}, {"w": "程品", "t": "法式;规范"}, {"w": "程法", "t": "程式;法则。"}]}, {"meaning": "典范;法度。", "cites": [{"t": "匪先民是程。", "b": "《诗·小雅》"}, {"t": "后世以为法程。", "b": "《吕氏春秋·慎行》"}], "words": [{"w": "程律", "t": "法律"}, {"w": "程墨", "t": "作为范本阅读的八股文选集。"}]}, {"meaning": "限度;期限;定额。", "cites": [{"t": "明宵有程。", "b": "《魏都赋》"}], "words": [{"w": "程额", "t": "定额;定限"}, {"w": "程期", "t": "期限"}, {"w": "程限", "t": "达到的期限。"}]}, {"meaning": "路程;行程。", "cites": [{"t": "淮左名都,竹西佳处,解鞍少驻初程。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "全程", "t": "全部路程"}, {"w": "程老", "t": "谓在路途中死亡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2678wx','稀','1','xī','禾','12','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从禾,希声。本义:稀疏)。"}, {"meaning": "同本义。", "cites": [{"t": "稀,疏也。", "b": "《说文》"}, {"t": "月明星稀。", "b": "《文选·曹操·短歌行》。经传皆以希为之。"}, {"t": "重露成涓滴,稀星乍有无。", "b": "唐·杜甫《倦夜》"}, {"t": "种豆南山下,草盛豆苗稀。", "b": "晋·陶潜《归园田居》"}], "words": [{"w": "稀棱挣", "t": "稀疏的样子"}, {"w": "稀撒撒", "t": "稀剌剌"}, {"w": "稀星", "t": "稀疏的星"}, {"w": "稀零零", "t": "极稀疏"}, {"w": "稀稀落落", "t": "稀疏的样子;稀疏冷落的样子。"}]}, {"meaning": "少,不多。", "cites": [{"t": "相见常日稀。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "鞍马稀。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "死者尚稀。", "b": "清·方苞《狱中杂记》"}, {"t": "自想此梦稀奇,心下疑惑。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "稀稀罕儿", "t": "稀罕少见的东西"}, {"w": "稀行", "t": "不常来;稀客。"}]}, {"meaning": "薄,不浓。", "cites": [{"t": "我们的衙门里每天煮了十几大锅的稀饭施给穷人。", "b": "巴金《灭亡》"}], "words": [{"w": "稀流薄荡", "t": "形容液体稀薄波动"}, {"w": "稀解粥", "t": "稀粥"}, {"w": "稀溜溜;稀淡", "t": "极淡,不浓密。"}]}, {"meaning": "很;极。形容程度深。", "cites": [{"t": "床上的铺盖已经掀得稀乱,一个凳子躺在被铺上。", "b": "鲁迅《而已集·再谈香港》"}], "words": [{"w": "稀不相干", "t": "一点儿也不相干"}, {"w": "稀秃湿", "t": "湿透了"}, {"w": "稀醉", "t": "烂醉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2679wx','税','1','shuì','禾','12','','[{"pinyin": "shuì", "defs": [{"meaning": "(形声。从禾,兑(duì)声。本义:田赋,征收的农产品)。"}, {"meaning": "同本义。", "cites": [{"t": "税,租也。", "b": "《说文》"}, {"t": "敛财曰赋,敛谷曰税,田税曰租。", "b": "《急就篇》注"}, {"t": "初税亩。", "b": "《谷梁传·宣公十五年》"}, {"t": "税十取一。", "b": "《大戴礼记·主言》"}, {"t": "有税有赋。", "b": "《汉书·食货志》。注:“税者,田租也。”"}, {"t": "论九税之利。", "b": "《周礼·掌交》"}, {"t": "有税有赋,税以足食,赋以足兵。", "b": "《汉书·刑法志》"}]}, {"meaning": "泛指一切赋税。", "cites": [{"t": "税谓公田什一及工商衡虞之入也。", "b": "《汉书·食货志》"}, {"t": "后世有关税、牙税、契税及芦课、茶课、矿课之类,亦税也。", "b": "《说文通训定声》"}, {"t": "省刑罚,薄税敛。", "b": "《孟子·梁惠王上》"}, {"t": "秘书监杨万里。奏输帛于官,谓之税。", "b": "《宋史·食货志》"}], "words": [{"w": "税政", "t": "税收政策"}, {"w": "税珰", "t": "掌管税收的宦官"}, {"w": "税敛", "t": "税收"}, {"w": "税粮", "t": "元明两代征收米、麦等实物的赋税"}, {"w": "税项", "t": "税收的款项"}, {"w": "税赋", "t": "田赋"}, {"w": "税课", "t": "赋税"}, {"w": "税厘", "t": "海关税和厘金税的合称"}, {"w": "税租", "t": "租税。田租和赋税"}, {"w": "税银", "t": "税金。"}]}, {"meaning": "细疏布制的丧服。", "cites": [{"t": "公丧之如税服,终身。", "b": "《左传·襄公二十七年》"}], "words": [{"w": "税服", "t": "用细而疏的布制成的丧服。"}]}, {"meaning": "利息。", "cites": [{"t": "今富商大贾,多放钱货中家子弟,为之保人,趋走与臣仆等勤,收税与封君比入。", "b": "《后汉书》"}]}, {"meaning": "征收或交纳赋税。", "cites": [{"t": "赵简主出税者,吏请轻重。", "b": "《韩非子·外储说右下》"}, {"t": "耕者则重税。", "b": "《韩非子·显学》"}, {"t": "草市迎江货,津桥税海商。", "b": "唐·王建《汴路即事》"}, {"t": "太华之山,悬崖之嵌,有松可荫,有地可蔬,有泉可汲,不税于官,不隶于宫观之籍。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "税民", "t": "向人民征收赋税"}, {"w": "税入", "t": "征税收入"}, {"w": "税户", "t": "纳税户"}, {"w": "税名", "t": "征税的名目"}, {"w": "税吏", "t": "旧时的专职征收赋税的人员"}, {"w": "税帖", "t": "旧时官府给予纳税人的纳税凭证。"}]}, {"meaning": "租赁。", "cites": [{"t": "生跪拜,前致词曰:“闻兹地隙院,愿税以居,信乎?”", "b": "唐·白行简《李娃传》"}], "words": [{"w": "税居", "t": "租赁房屋"}, {"w": "税米", "t": "即租米"}, {"w": "税屋", "t": "租借房屋"}, {"w": "税寓", "t": "租房居住"}, {"w": "税第", "t": "税屋"}, {"w": "税舍", "t": "驻宿的馆舍。"}]}, {"meaning": "释放,解脱。", "cites": [{"t": "郑人所献楚囚也,使税之。", "b": "《左传·成公九年》"}, {"t": "此譬之犹马驾而不税,弓张而不弛。", "b": "《墨子·三辩》"}, {"t": "不税冕而行。", "b": "《孟子·告子下》"}, {"t": "吾未知所税驾也。", "b": "《史记·李斯列传》"}, {"t": "乃税马于华山,说收于桃林。", "b": "《吕氏春秋·慎大》"}], "words": [{"w": "税马", "t": "放马"}, {"w": "税说", "t": "以言语游说他人"}, {"w": "税调", "t": "放置调度。"}]}, {"meaning": "原指向死者赠送衣被 ,后泛指赠人财物。", "cites": [{"t": "未仕者不敢税人,如税人则以父兄之命。", "b": "《礼记·檀弓上》"}, {"t": "及平原君(朱建)母死,…辟阳侯(审食其)乃奉百金往税。", "b": "《史记·郦生·陆贾传》"}], "words": [{"w": "税人", "t": "以物赠送人"}, {"w": "税邑", "t": "犹食邑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2680wx','筐','1','kuāng','竹','12','','[{"pinyin": "kuāng", "defs": [{"meaning": "(形声。从竹,匡声。本义:筐子,盛东西的方形竹器)。"}, {"meaning": "同本义。后亦用柳条或荆条等编成。", "cites": [{"t": "维筐及筥。", "b": "《诗·召南·采筥筥》。注:方曰筐,圆曰筥"}, {"t": "载筐及筥。", "b": "《诗·周颂·良耜》"}, {"t": "錡釜之器。", "b": "《左传·隐公三年》"}, {"t": "具扑曲筥筐。", "b": "《淮南子·时则》。注:“员底曰筥。”"}, {"t": "约者有筐箧之藏。", "b": "《荀子·荣辱》"}, {"t": "糗一筐。", "b": "《国语·楚语》"}, {"t": "背筐,手长鑱。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "筐篚", "t": "盛物竹器"}, {"w": "筐簏", "t": "盛物的竹器"}, {"w": "筐笼", "t": "泛指盛物竹器"}, {"w": "筐箩", "t": "箩筐。竹篾等编的盛器"}, {"w": "筐篓", "t": "盛物的两种竹器。"}]}, {"meaning": "簪。", "cites": [{"t": "柱不可以摘齿,筐不可以持屋。", "b": "《淮南子》。高诱注:“筐, 小簪也。”"}]}, {"meaning": "", "cites": [{"t": "大夫不里椁,士不虞筐。", "b": "《礼记》"}], "words": [{"w": "筐当", "t": "匡当。用以限定所制物件形状、大小的框架。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2681wx','等','1','děng','竹','12','','[{"pinyin": "děng", "defs": [{"meaning": "(会意。从竹,寺声。寺官曹之等平也,寺者,简册杂积之地,寺亦声。本义:整齐的简册)。"}, {"meaning": "同本义。", "cites": [{"t": "等,齐简也。", "b": "《说文》"}]}, {"meaning": "等级;辈分。", "cites": [{"t": "士阶三等。", "b": "《吕氏春秋·召类》"}, {"t": "皆陛下故等夷。", "b": "《史记·留侯世家》。索隐:“言等辈也。”"}, {"t": "同名同食曰同等。", "b": "《大戴礼记·少间》"}, {"t": "请自贬三等。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "优等;等例", "t": "等级差别,地位高低的差别"}, {"w": "等子", "t": "宋代的御林军;标本,样本"}, {"w": "等分", "t": "等级名分"}, {"w": "等外品", "t": "质量差,不列入等级的产品"}, {"w": "等列", "t": "等级品位"}, {"w": "等别", "t": "等级。"}]}, {"meaning": "台阶。", "cites": [{"t": "出降一等。", "b": "《论语·乡党》"}]}, {"meaning": "类型;样子。", "cites": [{"t": "爻有等。", "b": "《易·系辞》。注:“类也”"}, {"t": "呀,真个下雪了,有这等异事。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "此等人;等侪,等俦", "t": "同类。"}]}, {"meaning": "等同,使一样。", "cites": [{"t": "以等邦国。", "b": "《周礼·大宗伯》。注:“犹齐等也。”"}, {"t": "与无法等。", "b": "《淮南子·主术》。注:“同也。”"}, {"t": "我行法,当等贵贱,均贫富。", "b": "《资治通鉴》"}], "words": [{"w": "等作", "t": "等同;当作"}, {"w": "相等;大小不等;等头", "t": "齐头,齐等"}, {"w": "等伦", "t": "同辈;同类的人。"}]}, {"meaning": "等待,等候。", "cites": [{"t": "父母年年等驾回。", "b": "范成大《州桥诗》"}, {"t": "有个官人请说话,商议些事务,专等,专等。", "b": "《水浒传》"}], "words": [{"w": "等车", "t": "候车"}, {"w": "等人", "t": "等候别人"}, {"w": "等米下锅", "t": "比喻经济拮据而急需。"}]}, {"meaning": "区别等次。", "cites": [{"t": "以等其功。", "b": "《周礼·司勋》。注:“犹差也。”"}, {"t": "然后立乐等。", "b": "《礼记·乐记》。注:“差也。”"}], "words": [{"w": "等列", "t": "分等级"}, {"w": "等衰,等杀", "t": "等差"}, {"w": "等务", "t": "不同的事务。"}]}, {"meaning": "程度、数量相等。", "cites": [{"t": "等,齐也。", "b": "《广雅·释诂四》"}, {"t": "示有等威。", "b": "《左传·文公十五年》"}, {"t": "等赋府库者,货之流也。", "b": "《荀子·富国》"}]}, {"meaning": "用在人称代词或指人的名词后面,表示复数。", "cites": [{"t": "臣等不肖,请辞去。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "我等;彼等;一干人等", "t": ""}]}, {"meaning": "列举后煞尾。", "cites": [{"t": "与樊哙夏候婴靳强纪信等四人持剑盾步走。", "b": "《史记·项羽本纪》"}], "words": [{"w": "长江、黄河、黑龙江、珠江等四大河流", "t": ""}]}, {"meaning": "表示列举未尽(可叠用)。", "cites": [{"t": "关羽、张飞等不悦。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "购置笔、纸等", "t": ""}]}, {"meaning": "一样,同样。", "cites": [{"t": "今亡亦死,举大计亦死,等死,死国可乎。", "b": "《史记·陈涉世家》"}, {"t": "有法者而不用,与无法等。", "b": "《淮南子·主术》"}], "words": [{"w": "等夷", "t": "等侪。同等地位的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2682wx','筑','1','zhù','竹','12','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从木,筑声。本义:筑墙。古代用夹板夹住泥土,用木杆把土砸实)。"}, {"meaning": "捣土使坚实。", "cites": [{"t": "築,捣也。", "b": "《说文》"}, {"t": "不筑,必将有盗。(筑,这里指把坏墙修复。)", "b": "《韩非子·说难》"}], "words": [{"w": "筑踏", "t": "捣土并以足踏之,使之坚实。"}]}, {"meaning": "修建;建造(仅指建筑物从无到有的建造)。", "cites": [{"t": "曰止曰时,筑垒于兹。", "b": "《诗·大雅·绵》"}, {"t": "齐人将薛。", "b": "《孟子·梁惠王下》"}, {"t": "甸人筑坎坎。", "b": "《仪礼·既夕礼》"}, {"t": "筑场圃,十月纳禾稼。", "b": "《诗·豳风》"}, {"t": "北筑长城。", "b": "汉·贾谊《过秦论》"}, {"t": "更筑坚垒。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "筑石寨土堡。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "筑捺", "t": "修筑整治,务使坚实"}, {"w": "筑垒", "t": "建筑土垒"}, {"w": "筑室反耕", "t": "建筑房舍,分兵耕田"}, {"w": "筑建", "t": "兴筑建造。"}]}, {"meaning": "打,击。", "cites": [{"t": "老孙把头伸在那里,你且筑一下儿,看可能魂消气泄。", "b": "《西游记》"}], "words": [{"w": "筑球", "t": "古代的杖击或以足踢球。"}]}, {"meaning": "切断。", "cites": [{"t": "切脯筑肉。", "b": "《古文苑·王褒·僮约》"}]}, {"meaning": "捅。", "cites": [{"t": "贼以刀筑其口,使不得言。", "b": "《三国志》"}]}, {"meaning": "装填。", "cites": [{"t": "筑包于司。", "b": "《典故纪闻》"}], "words": [{"w": "筑础", "t": "犹奠基。"}]}, {"meaning": "拾取。", "cites": [{"t": "尽起而筑之,岁则大熟。", "b": "《书·金滕》"}]}, {"meaning": "捣土用的杵。", "cites": [{"t": "傅说举于版筑之间。", "b": "《孟子·告子下》"}, {"t": "称畚筑,程土物。", "b": "《左传·宣公十一年》。孔颖达疏:“畚者,盛土之器;筑者,筑土之杵。”"}, {"t": "身自持筑臿。", "b": "《史记·秦始皇本纪》"}, {"t": "身负板筑。", "b": "《史记·黥布传》。注:“杵也。”"}, {"t": "破荆和以继築。", "b": "《楚辞·离世》。注:“木杵也。”"}]}, {"meaning": "指建筑物。", "cites": [{"t": "畏人成小筑,褊性合幽栖。", "b": "杜甫《畏人》"}], "words": [{"w": "筑底巷", "t": "一头不通的死胡同。"}]}, {"meaning": "(形声。筑(旧读zhú),会意兼形声。从竹,从巩(gǒng),巩亦声。竹是乐器,巩是抱持。表示抱持乐器。“筑”是古代乐器名。)。"}, {"meaning": "古击弦乐器 。已失传,大体形似筝,颈细而肩圆。演奏时,以左手握持,右手以竹尺击弦发音。", "cites": [{"t": "筑,以竹曲五絃之乐也。", "b": "《说文》"}, {"t": "高祖击筑。", "b": "《史记·高祖记》"}, {"t": "竽瑟空侯琴筑筝。", "b": "《急就篇》。颜注:筑形如小瑟而细颈,以竹击之。”"}, {"t": "渐离击悲筑。", "b": "陶渊明《咏荆轲》"}]}, {"meaning": "水名 。即今汉水支流南河及其支流马栏河。"}, {"meaning": "贵州省贵阳市的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2683wx','策','1','cè','竹','12','','[{"pinyin": "cè", "defs": [{"meaning": "(形声。从竹,朿(cì)声。“朿”,指带有芒刺的植物,作“策”的声符,同时兼表字义。本义:竹制的马鞭(头上有尖刺))。"}, {"meaning": "同本义。引申为驾驭马匹的工具,包括缰绳之类。", "cites": [{"t": "軓前十尺而策半之。", "b": "《考工记·舟人》"}, {"t": "则仆执策立于马前。", "b": "《礼记·曲礼》"}, {"t": "绕朝赠之以策。", "b": "《左传·文公十三年》"}, {"t": "左师为已短策。", "b": "《左传·襄公十七年》"}, {"t": "伤吻敝策。", "b": "《汉书·王褒传》"}, {"t": "齐闵王将之鲁,夷维子执策而从。", "b": "《战国策·赵策》"}, {"t": "执策而临之。", "b": "唐·韩愈《杂说》"}, {"t": "振长策而御宇内。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "策辔", "t": "马鞭与马缰"}, {"w": "策彗", "t": "以带叶竹帚制作的马鞭。"}]}, {"meaning": "策略;计谋。", "cites": [{"t": "立盐铁,始张利官以给之,非长策也。", "b": "汉·桓宽《盐铁论·本议》"}, {"t": "惠文、武、昭襄蒙故业,因遗策。", "b": "汉·贾谊《过秦论》"}, {"t": "予更欲一觇北,归而求救国之策。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "上策;下策;失策", "t": "策略上失误"}, {"w": "策无遗算", "t": "谋略周密准确,没有遗漏失算之处。"}]}, {"meaning": "中国古代用竹片或木片记事著书,成编的叫做策。", "cites": [{"t": "单执一札谓之为简,连编诸简乃名为策。", "b": "《左传·序》疏"}, {"t": "凡命诸侯及孤卿大夫,则策命之。", "b": "《周礼·春官》"}, {"t": "书策稠浊,百姓不足。", "b": "《战国策·秦策一》"}], "words": [{"w": "策府", "t": "帝王藏书之所"}, {"w": "策简", "t": "指簿册文书"}, {"w": "策牍", "t": "简策版牍。后指书写用的纸张。"}]}, {"meaning": "策书。古代君主对臣下封土、授爵、免官或发布其他敕令的文件。引申为策命;策免。", "cites": [{"t": "策勋十二转,赏赐百千强。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "策命", "t": "用策书任命"}, {"w": "策拜", "t": "帝王以策书命官"}, {"w": "策文", "t": "诏书之类的文告。"}]}, {"meaning": "古代称应试者对答的文字为策。也指一种议论文体。", "cites": [{"t": "《治安策》", "b": "汉·贾谊"}, {"t": "《教战守策》", "b": "宋·苏轼"}], "words": [{"w": "策套", "t": "科举时代应试者应付策问考试的材料"}, {"w": "策学", "t": "科举时代供考生应付考试的短文集"}, {"w": "策题", "t": "科举策试的试题"}, {"w": "策第", "t": "策试和选评。"}]}, {"meaning": "古代用以计算的筹子(小竹片)。", "cites": [{"t": "善数不用筹策。", "b": "《老子》"}], "words": [{"w": "策筹", "t": "同“筹策”。古代计算工具。"}]}, {"meaning": "卜筮用的蓍草。", "cites": [{"t": "詹尹乃端策拂龟。", "b": "《楚辞·卜居》"}, {"t": "错龟数策。", "b": "《战国策·秦策》"}], "words": [{"w": "端策", "t": "把蓍草摆正。"}]}, {"meaning": "用鞭棒驱赶骡马役畜等。引申为驾驭。", "cites": [{"t": "将入门,策其马。", "b": "《论语·雍也》"}, {"t": "乘坚策肥,履丝曳缟。", "b": "汉·晁错《论贵粟疏》"}, {"t": "策之不以其道。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "鞭策;策马", "t": "鞭马"}, {"w": "策马飞舆", "t": "驾马车疾行。"}]}, {"meaning": "拄着;拄着棍杖。引申为搀扶;架起。", "cites": [{"t": "策扶老以流憩,时矫首而遐观。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "策杖", "t": "执持拐杖。又称扶杖、拄杖"}, {"w": "策踵", "t": "扶杖接踵而来"}, {"w": "策立", "t": "站立。"}]}, {"meaning": "谋划;策划。", "cites": [{"t": "故策之而知得失之计。", "b": "《孙子·虚实》"}], "words": [{"w": "策效", "t": "谋划效力"}, {"w": "策驭", "t": "谋划掌握"}, {"w": "策选", "t": "谋划选取。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2684wx','筛','1','shāi','竹','12','','[{"pinyin": "shāi", "defs": [{"meaning": "(形声。从竹,师声。本义:一种竹器,筛子) 同本义。", "cites": [{"t": "滤泉花满筛。", "b": "唐·李洞《喜鸾公自蜀归》"}], "words": [{"w": "筛子喂驴", "t": "歇后语。筛子喂驴,豆必漏下。漏豆谐“漏透”,即用光、穷极之意。"}]}, {"meaning": "用筛子过物。", "cites": [{"t": "筛土筑阿房之宫。", "b": "《汉书·贾山传》"}]}, {"meaning": "摇动;抖动。", "cites": [{"t": "摇漾无声,一任风筛,依约翠侵帘隙。", "b": "清·江昉《疏影》"}]}, {"meaning": "洒;分散地落下。", "cites": [{"t": "先将叶著怀中令暖,用刀剪碎,筛于纸上。", "b": "明·戴羲《养余月令》"}]}, {"meaning": "把酒盛在容器里,放在火上使热。", "cites": [{"t": "两个老婆子蹲在外面火盆上筛酒。", "b": "《红楼梦》"}]}, {"meaning": "胡言乱语。", "cites": [{"t": "则你那小鬼头胡乱筛,俺判官头何处买?", "b": "明·汤显祖《牡丹亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2685wx','筒','1','tǒng','竹','12','','[{"pinyin": "tǒng", "defs": [{"meaning": "(形声。从竹,同声。本义:竹筒,粗大的竹管)。"}, {"meaning": "同本义。", "cites": [{"t": "筒,通箫也。", "b": "《说文》"}, {"t": "筒,竹管也。", "b": "《三苍》"}, {"t": "筩,断竹也。", "b": "《说文》"}, {"t": "教吏为缿筩。", "b": "《汉书·李广汉传》。注:“竹筩也,如今官受密事筩也。”?"}, {"t": "伶伦制十二筩,以听凤鸣。", "b": "《汉书·律历志》"}], "words": [{"w": "筒箭", "t": "放在竹筒里发射的箭矢"}, {"w": "筒竹", "t": "竹筒"}, {"w": "筒炙", "t": "古时利用竹筒熏烤的一种烹调方法。也叫“黄炙”。"}]}, {"meaning": "泛指管筒状器物。", "cites": [{"t": "以筒水灌之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "邮筒;笔筒;筒竹", "t": "犹鞭炮"}, {"w": "筒车", "t": "一种引水灌田的机械设备"}, {"w": "筒轮", "t": "筒车取水所用的轮盘。"}]}, {"meaning": "竹名 。也称“射筒竹”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2686wx','筏','1','fá','竹','12','','[{"pinyin": "fá", "defs": [{"meaning": "(形声。从竹,伐声。本义:筏子) 同本义。", "cites": [{"t": "筏,大曰筏,小曰桴,乘之渡水。", "b": "《广韵》"}, {"t": "重五斤以上诸林木,渥水中,无过一筏。", "b": "《墨子·杂守》"}, {"t": "无数涪江筏,鸣桡总发时。", "b": "杜甫《奉送崔都水翁下峡》"}], "words": [{"w": "筏渡", "t": "用筏子渡水"}, {"w": "筏工", "t": "以撑筏子为业的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2687wx','答','1','dā dá','竹','12','','[{"pinyin": "dā", "defs": [{"meaning": "——义同“答”(dá),专用于“答应”、“答理”等词。"}]}, {"pinyin": "dá", "defs": [{"meaning": "(形声。从竹,合声。①本义:以竹补篱。②答谢,报答)。"}, {"meaning": "回话;应对。", "cites": [{"t": "听言则答。", "b": "《诗·小雅·雨无止》"}, {"t": "既发则答君而俟。", "b": "《仪礼·乡射礼记》"}, {"t": "见渔人,乃大惊,问所以来。具答之。", "b": "陶潜《桃花源记》"}, {"t": "兰芝仰头答:“理实如兄言。”", "b": "《乐府诗集·古诗为焦仲卿妻作》"}, {"t": "渔歌互答。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "皆缄口不答。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "应答如流;答教", "t": "预先写好的准备答问的书面文字"}, {"w": "答言", "t": "用言语回答"}, {"w": "答语", "t": "回答的话;应对的话。"}]}, {"meaning": "报礼;报答。引申为酬答。", "cites": [{"t": "适不答兹谓不次。", "b": "《仪礼·五行志》。注:“报也。”"}, {"t": "因厚赂单于,答(报答)其善意。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "答施", "t": "报答恩惠"}, {"w": "答效", "t": "报效;为报答恩德而为对方尽力。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2688wx','筋','1','jīn','竹','12','','[{"pinyin": "jīn", "defs": [{"meaning": "(会意。从肉,从力,从竹。因为竹多筋,故从“竹”。本义:附着在骨上的韧带)。"}, {"meaning": "同本义。", "cites": [{"t": "筋,肉之力也。", "b": "《说文》"}, {"t": "诸筋者,皆属于节。", "b": "《素问·五藏生成论》"}, {"t": "强者在内而摩其筋。", "b": "《考工记·弓人》"}, {"t": "劳其筋骨。", "b": "《孟子·告子下》"}, {"t": "筋骨之强。", "b": "《荀子·劝学》"}, {"t": "先折筋骨。", "b": "清·方苞《狱中杂记》"}, {"t": "筋骨尽脱。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "筋皮", "t": "筋骨与皮肉"}, {"w": "筋厮锁", "t": "身体已肢解,只剩筋络相连。比喻山河破碎"}, {"w": "筋血", "t": "精力与血汗"}, {"w": "筋条", "t": "身体结实强健"}, {"w": "筋马", "t": "筋骨强健而不过于肥壮的马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2689wx','筝','1','zhēng','竹','12','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从竹,争声。从竹,与乐器有关。本义:拨弦乐器。形似瑟。筝是拨弦乐器,战国时已流行于秦地,故又称“秦筝”) 同本义。", "cites": [{"t": "筝,鼓弦竹身乐也。", "b": "《说文》"}, {"t": "筝,五弦筑身乐也。", "b": "《御览》引《说文》"}, {"t": "挟人筝而弹纬。", "b": "《楚辞·愍命》。注:“小琴也。”"}, {"t": "竽瑟空侯琴筑筝。", "b": "《急就篇》"}], "words": [{"w": "筝人", "t": "弹筝的人"}, {"w": "筝阮", "t": "秦筝与阮咸。古代的两种拨弦乐器"}, {"w": "筝妓", "t": "弹筝的艺妓"}, {"w": "筝柱", "t": "筝上的弦柱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2690wx','傲','1','ào','亻','12','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。从人,敖声。本义:骄傲;傲慢无理)。"}, {"meaning": "同本义。", "cites": [{"t": "傲,倨也。", "b": "《说文》"}]}, {"meaning": "经传以敖为之。", "cites": [{"t": "凡视上于面则敖。", "b": "《礼记·曲礼》"}, {"t": "彼交匪敖。", "b": "《诗·小雅·桑柔》"}, {"t": "不吴不敖。", "b": "《诗·周颂·丝衣》"}, {"t": "敖而无足数者。", "b": "《史记·游侠传》"}, {"t": "执币,傲。", "b": "《左传·文公九年》"}, {"t": "齐音傲辟乔志。", "b": "《礼记·乐记》"}, {"t": "图傲救世之士哉。", "b": "《庄子·天下》"}, {"t": "弟敬爱兄谓之悌,反悌为傲。", "b": "《贾子道术》"}, {"t": "令尹甚傲而好兵,子必谨敬。", "b": "《韩非子·内储说下》"}, {"t": "傲不可长,欲不可纵。", "b": "魏征《十三斩不克终疏》"}], "words": [{"w": "傲兀", "t": "高傲不屈的样子"}, {"w": "傲睨", "t": "傲然睨视,形容倨傲,看不上一切"}, {"w": "傲态", "t": ""}]}, {"meaning": "急躁。", "cites": [{"t": "不问而告谓之傲。", "b": "《荀子·劝学》"}]}, {"meaning": "傲慢而轻视。", "cites": [{"t": "民慕其利而傲其罪。", "b": "《韩非子·六反》"}, {"t": "恃才傲物。 ", "b": "《南史·萧子显传》"}], "words": [{"w": "傲俗", "t": "蔑视俗人"}, {"w": "傲上", "t": "对上倨傲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2691wx','傅','1','fù','亻','12','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从人,尃(fū)声。本义:辅佐)。"}, {"meaning": "同本义。", "cites": [{"t": "傅,相也。", "b": "《说文》。按,与俌略同。"}, {"t": "傅,傅之德义。", "b": "《汉书·贾谊传》。师古曰:“傅,辅也。”"}, {"t": "郑伯傅王。", "b": "《左传·僖公二十八年》"}], "words": [{"w": "傅父", "t": "古代辅育王室子女的年长男性保育人员"}, {"w": "傅御", "t": "古代辅佐君王或诸侯办事的官员"}, {"w": "傅弼", "t": "辅弼;辅佐。"}]}, {"meaning": "辅导。", "cites": [{"t": "有楚大夫于此,欲其子之齐语也,则使齐人傅诸?使楚人傅诸?", "b": "《孟子》"}, {"t": "今日傅教帝。", "b": "《汉书·陈平传》"}], "words": [{"w": "傅姆", "t": "古时辅导、保育贵族子女的年老妇人"}, {"w": "傅相", "t": "古时辅导国君、诸侯王之官"}, {"w": "傅导", "t": "辅导。"}]}, {"meaning": "靠近,迫近。", "cites": [{"t": "傅,近也。", "b": "《小尔雅》"}, {"t": "重欲傅人。", "b": "《考工记·庐人》"}, {"t": "亦傅于天。", "b": "《诗·小雅·菀柳》"}], "words": [{"w": "傅郭", "t": "靠近外城"}, {"w": "傅近", "t": "靠近。"}]}, {"meaning": "依附,依凭。", "cites": [{"t": "皮之不存,毛将安傅?", "b": "《左传·僖公十四年》"}], "words": [{"w": "傅堞", "t": "凭借城堞"}, {"w": "傅丽", "t": "依靠。"}]}, {"meaning": "附着。", "cites": [{"t": "辩士见一端,或以意傅着星历,虚造匈奴、乌孙、西羌之难。", "b": "《汉书·息夫躬傅》"}, {"t": "毋为虎傅翼,将飞入邑,择人而食之。", "b": "《韩非子》"}], "words": [{"w": "傅人", "t": "依附于他人"}, {"w": "傅于", "t": "附着。"}]}, {"meaning": "捎带,随带。", "cites": [{"t": "边人驩激,执弓傅矢,唯恐不得进。", "b": "《宋史》"}]}, {"meaning": "以财物助丧事。", "cites": [{"t": "若国札丧则令傅补之。", "b": "《周礼·秋官下·小行人》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2692wx','牌','1','pái','片','12','','[{"pinyin": "pái", "defs": [{"meaning": "(形声。从片,卑声。“片”指锯开的木头的一半,又泛指扁而薄的东西。本义:题榜,招牌)。"}, {"meaning": "户籍板。犹今之户口簿。", "cites": [{"t": "簧牌,籍也。", "b": "《广雅》"}]}, {"meaning": "“牌军”的略称。", "cites": [{"t": "一直奔回家来,又和李牌寻了一黄昏。", "b": "《水浒传》"}]}, {"meaning": "指“万岁龙牌”。", "cites": [{"t": "有天万寿,跟了抚台拜牌。", "b": "《官场现形记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2693wx','堡','1','bǎo bǔ pù','土','12','','[{"pinyin": "bǎo", "defs": [{"meaning": "(形声。从土,保声。堡是后起字。本义:土筑的小城)。"}, {"meaning": "同本义。", "cites": [{"t": "据险筑堡以自固。", "b": "《晋书·符登载记》"}]}, {"meaning": "又。", "cites": [{"t": "关中堡壁三千余所。", "b": ""}], "words": [{"w": "碉堡;堡障", "t": "用于防守的小土城。"}]}, {"meaning": "指堡垒。", "cites": [{"t": "送将军登空堡上。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "城堡", "t": "堡垒式的小城"}, {"w": "碉堡", "t": ""}]}]}, {"pinyin": "bǔ", "defs": [{"meaning": "", "words": [{"w": "吴堡县", "t": "在陕西省"}, {"w": "柴沟堡", "t": "在河北省。"}]}]}, {"pinyin": "pù", "defs": [{"meaning": "—— 地名用字。五里铺、十里铺等的“铺”字,有的地区写作“堡”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2694wx','集','1','jí','隹','12','','[{"pinyin": "jí", "defs": [{"meaning": "同本义。", "cites": [{"t": "集,群鸟在木上也。", "b": "《说文》"}, {"t": "集,会也。", "b": "《尔雅》"}, {"t": "集于苞栩。", "b": "《诗·唐风·鸨羽》"}, {"t": "黄鸟于飞,集于灌木。", "b": "《诗·周南·葛覃》"}], "words": [{"w": "集隼", "t": "栖息的隼鸟"}, {"w": "集凤", "t": "凤停于树。"}]}, {"meaning": "引申为停留。", "cites": [{"t": "人皆集于苑,己独集于枯。", "b": "《国语》"}, {"t": "齐集有其一。", "b": "《孟子·梁惠王上》"}, {"t": "沙鸥翔集。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "旋见鸡伸颈摆扑;临视,则虫集冠上,力可不释。", "b": "《聊斋志异·促织》"}]}, {"meaning": "集合;聚集;收集。", "cites": [{"t": "人皆集于苑。", "b": "《国语·晋语》"}, {"t": "今乘诸军未集,宜速击之。", "b": "《资治通鉴》"}, {"t": "皆集于此。", "b": "明·宋濂《送东阳马生序》"}, {"t": "四面集。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "集凑", "t": "收集拼凑"}, {"w": "集叠", "t": "收取,打叠"}, {"w": "集贤院", "t": "唐文学三馆之一。掌秘书图籍等事"}, {"w": "集缀", "t": "聚集联缀,编辑。"}]}, {"meaning": "依就。", "cites": [{"t": "有命既集。", "b": "《诗·大雅·大明》"}], "words": [{"w": "集服", "t": "顺从,服从"}, {"w": "集附", "t": "归心,顺服。"}]}, {"meaning": "至;遭受。", "cites": [{"t": "不其集亡。", "b": "《国语·晋语》。注:“至也。”"}], "words": [{"w": "集蓼", "t": "遭遇苦难"}, {"w": "集枯", "t": "遭到冷遇。"}]}, {"meaning": "成功。", "cites": [{"t": "谋夫孔多,是用不集。?", "b": ""}, {"t": "此车一人殿之,可以集事。", "b": "《左传·成公二年》"}], "words": [{"w": "集事", "t": "成事;成功。"}]}, {"meaning": "召集。", "cites": [{"t": "莫不毕集。", "b": "清·侯方域《壮悔堂文集》"}, {"t": "集诸将而语。", "b": "清·全祖望《梅花岭记》"}, {"t": "集谢庄少年。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": ""}, {"meaning": "和协,安抚。", "cites": [{"t": "问所以安集百姓。", "b": "《史记·曹相国世家》"}, {"t": "而吏安集之不称之效也。", "b": "《汉书·匡衡传》"}, {"t": "安集洛阳。", "b": "《后汉书·杜诗传》"}, {"t": "安集吏民,顺俗而教。", "b": "《吴子·图国》"}]}, {"meaning": "安定。", "cites": [{"t": "天下初定,远方黔首未集。", "b": "《史记·秦始皇本纪》"}, {"t": "几可以解释安集。", "b": "《汉书·王莽传下》"}, {"t": "存抚天下,安集中国。", "b": "《文选·司马相如·喻巴蜀檄》"}]}, {"meaning": "集子,诗文的汇集。", "cites": [{"t": "顷撰其遗文,都为一集。", "b": "曹丕《与吴质书》"}], "words": [{"w": "文集;诗集;地图集;画集", "t": ""}]}, {"meaning": "集镇,市镇。", "cites": [{"t": "那山里关帝庙有两处,集东一个,集西一个。", "b": "《老残游记》"}, {"t": "山东兖州府汶上县有个幺村,叫做薛家集,这集上有百十来人家,都是务农为业。", "b": "《儒林外史》"}]}, {"meaning": "集部,中国图书的经、史、子、集四部分类法把诗文等作品列为集部。", "cites": [{"t": "至唐始分为四类,曰经、史、子、集。", "b": "《新唐书》"}]}, {"meaning": "中国古州名 。北魏废帝三年(公元554年)改东巴州置。取东北集川水为名,寄治梁州(今陕西省汉中市)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2695wx','焦','1','jiāo','灬','12','','[{"pinyin": "jiāo", "defs": [{"meaning": "(会意。金文字形,上面是“隹”(zhuī),短尾鸟,下面是“火”。把鸟放在火上烤。本义:物经火烧而变黄或成炭)。"}, {"meaning": "同本义。", "cites": [{"t": "焦,火所伤也。", "b": "《说文》"}, {"t": "焦,火烧黑也。", "b": "《玉篇》"}, {"t": "濡灸之举焦。", "b": "《礼记·内则》"}, {"t": "凡气因火变则为焦。", "b": "《素问》"}], "words": [{"w": "焦盆", "t": "焦杯。焚纸的火池"}, {"w": "焦鎚", "t": "一种烤熟的饼食"}, {"w": "焦尾", "t": "焦桐,焦尾瑟。东汉蔡邕用一端有焦痕的桐木所制的琴。后多指名贵的琴"}, {"w": "焦霹雳", "t": "能对人畜、植物或建筑物造成很大危害的霹雷。"}]}, {"meaning": "干枯;枯焦。", "cites": [{"t": "五谷焦死。", "b": "《墨子·非攻下》"}], "words": [{"w": "焦芽", "t": "枯焦的幼芽"}, {"w": "焦死", "t": "枯死"}, {"w": "焦瘦", "t": "枯瘦。"}]}, {"meaning": "叫喊,吵闹。", "cites": [{"t": "梅香嗏省闹,小姐哎你休焦", "b": ""}]}, {"meaning": "着急。", "cites": [{"t": "假如你焦他没有房屋,何不替他娶上一个孙媳妇。", "b": "《儒林外史》"}], "words": [{"w": "焦劳", "t": "焦躁不安"}, {"w": "焦躁", "t": "着急而烦躁"}, {"w": "焦闷", "t": "焦躁烦闷"}]}, {"meaning": "干燥。", "cites": [{"t": "少洎之则焦而不熟。", "b": "《吕氏春秋·应言》"}, {"t": "唇焦口燥呼不得。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "烧焦的。", "cites": [{"t": "楚人一炬,可怜焦土。", "b": "唐·杜牧《阿房宫赋》"}]}, {"meaning": "物体烧焦所产生的气味。", "cites": [{"t": "焦,臭也。", "b": "《广雅》"}, {"t": "其臭焦。", "b": "《礼记·月令》"}], "words": [{"w": "焦苦、焦味", "t": "物体烧焦发出的气味。"}]}, {"meaning": "焦耳的简称 ——符号J。"}, {"meaning": "古国名 。姬姓,在今河南陕县南,春秋时灭亡。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2696wx','傍','1','bàng','亻','12','','[{"pinyin": "bàng", "defs": [{"meaning": "(形声。从人,旁声。本义:靠近,临近)同本义。", "cites": [{"t": "傍,近也。", "b": "《说文》"}, {"t": "双兔傍地走。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "傍边", "t": "靠近边沿"}, {"w": "傍通", "t": "靠近四方通达之地"}, {"w": "傍境", "t": "边境"}, {"w": "傍户而立", "t": ""}]}, {"meaning": "辅佐。", "cites": [{"t": "四贤傍之。", "b": "《新书》"}]}, {"meaning": "旁边,侧。", "cites": [{"t": "傍,近也。", "b": "《说文》。按,与旁别,四旁四方皆当作此,犹边际也。"}, {"t": "傍,侧也。", "b": "《广韵》"}, {"t": "玄应声恸哭,酸感傍人。", "b": "《世说新语·夙惠》"}, {"t": "白马金具装,横行辽水傍。", "b": "孔稚圭《白马篇》"}, {"t": "两家求合葬,合葬华山傍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "傍门", "t": "佛教指学佛而得正误者为正果,指外道为傍门;道家以修炼金丹、全身保真为正道,余皆为傍门"}, {"w": "傍支", "t": "分支"}, {"w": "傍览", "t": "从旁观看、打量"}, {"w": "傍观", "t": "在近旁观看"}, {"w": "傍若无人", "t": "好像旁边没有人在,形容神情态度高傲自如。"}]}, {"meaning": "唐代州名。在今云南双柏县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2697wx','储','1','chǔ','亻','12','','[{"pinyin": "chǔ", "defs": [{"meaning": "(形声。从人,诸声。本义:积蓄备用)。"}, {"meaning": "同本义。", "cites": [{"t": "储,偫也。", "b": "《说文》"}, {"t": "储,贮也。储亦备也,谓蓄物以为备曰储也。", "b": "《一切经音义》"}, {"t": "小人德无储。", "b": "曹子建诗?"}, {"t": "盈衍储邸。", "b": "王元长《曲水诗序》"}, {"t": "府无储钱,库无甲兵。", "b": "《韩非子·十过》"}, {"t": "储兵马以待之。", "b": "《汉书·何并传》"}, {"t": "丰年岁登,则储积以备乏绝。", "b": "《盐铁论·力耕》"}], "words": [{"w": "储粮备荒;冬储白菜;储邸", "t": "储存物品的府库"}, {"w": "储峙", "t": "蓄备"}, {"w": "储款", "t": "将钱存入银行"}, {"w": "储书", "t": "藏书"}, {"w": "储敛", "t": "聚集资财"}, {"w": "储才", "t": "积聚人才"}, {"w": "储养", "t": "谓聚集人才并供养之。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2698wx','皓','1','hào','白','12','','[{"pinyin": "hào", "defs": [{"meaning": "(形声。从白,告声。本作“皜”。本义:光明)。"}, {"meaning": "同本义。", "cites": [{"t": "日出皓兮。", "b": "《诗·陈风·月出》"}, {"t": "皓月千里。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "皓月", "t": "明月"}, {"w": "皓旰", "t": "光明亮丽"}, {"w": "皓颢", "t": "明亮洁白"}, {"w": "皓洁", "t": "明亮洁白。"}]}, {"meaning": "白;洁白。", "cites": [{"t": "皓,白也。", "b": "《小尔雅》"}, {"t": "白石皓皓。", "b": "《诗·唐风·扬之水》"}, {"t": "皓皓乎不可尚已。", "b": "《孟子·滕文公上》"}, {"t": "有五六老叟,庞眉皓发。", "b": "《后汉书·刘庞传》"}, {"t": "曼理皓齿。", "b": "《韩非子·杨权》"}, {"t": "延颈秀项,皓质呈露。", "b": "曹植《洛神赋》"}, {"t": "绛皓驳色。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "皓腕", "t": "素腕,指女子洁白的手腕"}, {"w": "皓皓", "t": "洁白的样子;光明的样子"}, {"w": "皓手", "t": "洁白的手"}, {"w": "皓然", "t": "洁白的样子"}, {"w": "皓齿明眸", "t": "洁白的牙齿,明亮的眼睛。"}]}, {"meaning": "广大的样子。", "cites": [{"t": "闇乎天下之晦盲也,皓天不复,忧无疆也。", "b": "《荀子·赋》"}, {"t": "皓天舒白日。", "b": "左思《咏史》"}, {"t": "太皓悦和,雷声乃发 。又如:皓然(元气盛大流行的样子);皓天(天的泛称;即昊天);皓荡(广阔天边的样子)", "b": ""}]}, {"meaning": "借指老翁。", "cites": [{"t": "送尔长江万里心,他年来访南山皓。", "b": "李白《金陵歌送别范宣》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2699wx','皖','1','wǎn','白','12','','[{"pinyin": "wǎn", "defs": [{"meaning": "春秋时国名 。汉置县。在今安徽省潜山县北。", "cites": [{"t": "《禹贡》扬州之域,春秋时为皖国,战国属楚,秦属九江郡,二汉属庐江郡。", "b": "顾祖禹《读史方舆纪要》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2700wx','粤','1','yuè','米','12','','[{"pinyin": "yuè", "defs": [{"meaning": "助词。古与“聿”、“越”、“曰”通用,用于句首或句中。", "cites": [{"t": "粤,于也。审慎之词也。从于,从寀,会意。", "b": "《说文》"}, {"t": "粤,曰也。又,于也。", "b": "《尔雅》"}, {"t": "粤三日丁亥。", "b": "《书·召诰》"}, {"t": "粤詹(瞻)雒伊。", "b": "《史记·周本纪》"}, {"t": "尚粤其几,沦神域兮。", "b": "班固《幽通赋》"}], "words": [{"w": "粤若", "t": "发语词。用于句首以起下文。"}]}, {"meaning": "旧地名 。百粤之地,即今广东和广西等地。", "cites": [{"t": "予弱冠粤行。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "粤东", "t": "广乐省的别称"}, {"w": "粤寇", "t": "清朝统治阶级对太平天国起义者的污蔑之词"}, {"w": "粤海", "t": "指中国南部广东一带的海域,又作为广东和广州的代称"}, {"w": "粤峤", "t": "指五岭以南地区。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2701wx','奥','1','ào','大','12','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。本义:古时指房屋的西南角。古时祭祀设神主或尊者居坐之处)。"}, {"meaning": "同本义。", "cites": [{"t": "奥,宛也。室之西南隅。", "b": "《说文》"}, {"t": "燔柴于奥。", "b": "《礼记·礼器》"}, {"t": "西南隅谓之奥。", "b": "《尔雅》"}, {"t": "司宫筵于奥。", "b": "《仪礼·少牢礼》"}, {"t": "设于奥。", "b": "《仪礼·士丧礼》"}, {"t": "经堂入奥。", "b": "《楚辞·招魂》"}], "words": [{"w": "奥阼", "t": "室之西南隅,为尊者、主人之位。"}]}, {"meaning": "泛指室内深处。", "cites": [{"t": "室无奥阼。", "b": "《仲尼燕居》"}, {"t": "无能老蝙蝠,乘夜出堂奥。", "b": "张耒《夏日杂感》"}], "words": [{"w": "堂奥", "t": ""}]}, {"meaning": "宫廷内机密的地方。", "cites": [{"t": "出入往来禁奥。", "b": "《三国志·董昭传》"}], "words": [{"w": "奥主", "t": "国内之主。比喻国君。奥有深居内室之意。"}]}, {"meaning": "深。", "cites": [{"t": "野无奥草。", "b": "《国语·周语》。注:“深也。”"}, {"t": "结根坚且奥。", "b": "陆机《塘上行》"}], "words": [{"w": "奥处", "t": "深居"}, {"w": "奥室", "t": "内室;深宅"}, {"w": "奥祉", "t": "深厚的福祉。"}]}, {"meaning": "深奥,精深不易理解。", "cites": [{"t": "雅诰奥义。", "b": "《书·序》。释文:“深也。”"}, {"t": "遂与对榻讲论经奥义。", "b": "脱脱等《宋史》"}, {"t": "抑之欲其奥。", "b": "柳宗元《答韦中立论师道书》"}, {"t": "水亭陋室,曲有奥趣。", "b": "柳宗元《永州龙兴寺东丘记》"}, {"t": "皆曲有奥思。", "b": "李格非《洛阳名园记》"}], "words": [{"w": "奥说", "t": "奥妙的学说"}, {"w": "奥深", "t": "高深不易理解。"}]}, {"meaning": "奥地利的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2702wx','街','1','jiē','行','12','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从行,圭声。“街”,小篆象纵横相交的十字路。本义:四路相通的大道)。"}, {"meaning": "城市的大道,两边有房屋的、比较宽阔的道路,通常指开设商店的区段。", "cites": [{"t": "街,四通道也。", "b": "《说文》"}, {"t": "街,交道也。", "b": "《三苍》"}, {"t": "街衢相经。", "b": "张衡《西京赋》"}, {"t": "殷之法,刑弃灰于街者。", "b": "《韩非子·内储说上》"}, {"t": "街谈巷议。", "b": "张衡《西京赋》"}, {"t": "适通渠公之街。", "b": "《庄子·徐无鬼》"}, {"t": "六多所以街天地也。", "b": "《管子·五行志》。注:“街犹阴阳多也。”"}], "words": [{"w": "大街小巷;街市", "t": "街巷;市井"}, {"w": "街鼓", "t": "街上报更的鼓"}, {"w": "街基", "t": "街直。台阶"}, {"w": "街道厅", "t": "清代管理京城道路、沟渠的衙门"}, {"w": "街官", "t": "街使。负责巡察市街的官员"}, {"w": "街卒", "t": "古时负责清扫道路的人。"}]}, {"meaning": "市集。", "cites": [{"t": "公孙枝徙,自敷于街。", "b": "《吕氏春秋·不苟》"}], "words": [{"w": "街店", "t": "街市上的店铺"}, {"w": "街面上", "t": "市面"}, {"w": "街景", "t": "街市的景象"}, {"w": "街肆", "t": "街市店铺"}, {"w": "街滑子", "t": "街溜子。方言。指游荡街衢、不务正业的奸滑之徒"}, {"w": "街镇", "t": "市镇。"}]}, {"meaning": "径路。", "cites": [{"t": "请言气街。胸气有街,腹气有街…", "b": "《灵枢经》"}, {"t": "此肾之街也。", "b": "《素问·热穴论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2703wx','惩','1','chéng','心','12','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从心,征声。本义:警戒;鉴戒)。"}, {"meaning": "同本义。", "cites": [{"t": "惩,戒也。", "b": "《玉篇》"}, {"t": "惩,恐也。", "b": "《广雅》"}, {"t": "则民有所惩。", "b": "《礼记·表记》"}, {"t": "不惩其心。", "b": "《诗·小雅·节南山》"}], "words": [{"w": "惩毖", "t": "受创于前,当戒慎于后"}, {"w": "惩纠", "t": "告戒督察"}, {"w": "惩示", "t": "警告。"}]}, {"meaning": "处罚。", "cites": [{"t": "惩恶而劝善。", "b": "《左传·成公十四年》"}, {"t": "惩肆而去贪。", "b": "《左传·成公三十一年》"}], "words": [{"w": "惩劝", "t": "责罚与奖赏"}, {"w": "惩恶劝善", "t": "贬斥坏人,奖励好人"}, {"w": "惩创", "t": "惩戒;警惕。"}]}, {"meaning": "改定。", "cites": [{"t": "变律改经,一皆惩革。", "b": "陆倕《新刻漏铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2704wx','御','1','yù','彳','12','','[{"pinyin": "yù", "defs": [{"meaning": "(会意。甲骨文字形。左为“行”的省写,中为绳索形,右是“人”形。意为人握辔行于道中,即驾驶车马。本义:驾驶车马)。"}, {"meaning": "同本义。也作“驭”。", "cites": [{"t": "御,使马也。", "b": "《说文》"}, {"t": "徒御不惊。", "b": "《诗·小雅·车攻》"}, {"t": "以御见,侍中。", "b": "《汉书·荀彘传》"}, {"t": "礼乐射御书数。", "b": "《周礼·大司徒》"}, {"t": "梁弘御戎。", "b": "《左传·僖公三十三年》"}, {"t": "夫以疲病之卒御狐疑众…甚未足畏。", "b": "《资治通鉴》"}], "words": [{"w": "御轮", "t": "赶车"}, {"w": "御策", "t": "驾驭马匹的鞭子"}, {"w": "御正", "t": "驾驶使不偏斜"}, {"w": "御夫", "t": "驾驭车马的人。"}]}, {"meaning": "后亦泛指驾驭一切运行或飞行之物。", "cites": [{"t": "御轻舟而上溯,浮长川而忘反。", "b": "三国魏·曹植《洛神赋》"}], "words": [{"w": "御天", "t": "控御天道"}, {"w": "御气", "t": "制御血气"}, {"w": "御物", "t": "驾驭万物。"}]}, {"meaning": "统治;治理。", "cites": [{"t": "振长策而御宇内,吞二周而亡诸侯。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "御世", "t": "治理天下"}, {"w": "御民", "t": "统治人民"}, {"w": "御宇", "t": "统治天下。"}]}, {"meaning": "统率;率领。", "cites": [{"t": "皇帝亲御六师,即离三蜀,霜戈万队,铁马千群。", "b": "《旧唐书》"}], "words": [{"w": "御兵", "t": "统率军队。"}]}, {"meaning": "使用;应用。", "cites": [{"t": "不可以御蓬。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "御器", "t": "使用器具。"}]}, {"meaning": "载,装运。", "cites": [{"t": "乘六马,御妇人以出正闺。", "b": "《说苑》"}]}, {"meaning": "抵挡。", "cites": [{"t": "无御之者。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "不知御。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "御寒", "t": ""}]}, {"meaning": "违逆。", "cites": [{"t": "天下服而无御,四境 静而无虞。", "b": "《新书》"}], "words": [{"w": "御便殿", "t": "皇帝驾临便殿。"}]}, {"meaning": "指侍奉皇帝的妃嫔。", "cites": [{"t": "倚嫔御歌。", "b": "宋·王谠《唐语林·雅量》"}]}, {"meaning": "驾驶车马的人。", "cites": [{"t": "徒御不惊,大庖不盈。", "b": "《诗·小雅》"}, {"t": "腊月,陈王之汝阴,还至下城父,其御庄贾杀以降秦。", "b": "《史记》"}]}, {"meaning": "车和马。", "cites": [{"t": "沙市放船寒月白,渚宫留御古苔斑。", "b": "王安石《送王龙图》"}]}, {"meaning": "仆役,侍从,陪伴主人提供服务的人。", "cites": [{"t": "宾御如浮云,从风各消散。", "b": "李白《南奔书怀》"}]}, {"meaning": "宫中女官名。", "cites": [{"t": "王御不参一族。", "b": "《国语》。韦昭注:“御,妇官也。”"}]}, {"meaning": "对帝王所作所为及所用物的敬称。", "cites": [{"t": "出御便殿。", "b": "清·张廷玉《明史》"}], "words": [{"w": "御膳", "t": "皇帝的饮食"}, {"w": "御笔", "t": "皇帝亲笔书写"}, {"w": "御酒", "t": "专供皇帝、宫廷饮用的酒"}, {"w": "御弟", "t": "皇上的弟弟"}, {"w": "御状", "t": "向皇帝告状。"}]}, {"meaning": "息止;禁止;阻止。", "cites": [{"t": "夫易广矣大矣,以言乎远则则不御。", "b": "《易·系辞上》"}, {"t": "亦以御冬。", "b": "《诗·邶风·谷风》"}, {"t": "于是又节用御欲。", "b": "《荀子·荣辱》"}], "words": [{"w": "御水", "t": "避水旱灾"}, {"w": "御火", "t": "避火灾"}, {"w": "御守", "t": "防守"}, {"w": "御捍", "t": "防御,保卫"}, {"w": "御寇", "t": "防御贼寇"}, {"w": "御备", "t": "防备。"}]}, {"meaning": "抵御。", "cites": [{"t": "亦以御冬。", "b": "《诗·邶风·谷风》"}, {"t": "御寒暑之美服。", "b": "《公羊传·桓公八年》"}, {"t": "晋人御师必于殽。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "御凶", "t": "抗拒凶邪之气"}, {"w": "御战", "t": "为抵御敌人的侵犯而作战。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2705wx','循','1','xún','彳','12','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从彳,盾声。彳(chì),双人旁,与行走有关。本义:顺着,沿着)。"}, {"meaning": "同本义。", "cites": [{"t": "循,行顺也。", "b": "《说文》"}, {"t": "循道而趋。", "b": "《庄子·天道》"}, {"t": "循墙而走。", "b": "《庄子·列御寇》"}, {"t": "率循大下。", "b": "《书·顾命》"}, {"t": "五星循轨。", "b": "《淮南子·本经》"}, {"t": "循天者,与道游者也。", "b": "《淮南子·原道》"}, {"t": "循山而南。", "b": "《左传·昭公二十三年》"}, {"t": "循表而夜涉。", "b": "《吕氏春秋·察今》"}, {"t": "循陵而走,见蹲石鳞鳞。", "b": "《聊斋志异·促织》"}, {"t": "循以入。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "循轨", "t": "依轨道而行"}, {"w": "循箫", "t": "沿街叫卖的人。"}]}, {"meaning": "按照;依序。", "cites": [{"t": "因任而授官,循名而责实。", "b": "《韩非子·定法》"}, {"t": "奉事循公姥,进止敢自专。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "循例", "t": "依照常例"}, {"w": "循名责实", "t": "按其名而求其实"}, {"w": "循次", "t": "依次"}, {"w": "循依", "t": "依照。"}]}, {"meaning": "遵循,仿效。", "cites": [{"t": "昏微循迹。", "b": "《楚辞·天问》。注:“循,遵也。”"}, {"t": "循绳墨而不颇。", "b": "屈原《离骚》"}, {"t": "无有作好,遵王之道。", "b": "《书·洪范》"}], "words": [{"w": "循古", "t": "遵循古制"}, {"w": "循道", "t": "遵循正道"}, {"w": "循桡", "t": "遵行"}, {"w": "循检", "t": "遵照规矩"}, {"w": "循蹈", "t": "遵循。"}]}, {"meaning": "遵守。", "cites": [{"t": "卿大夫以循法为节。", "b": "《礼记·射义》"}, {"t": "大人作而弟子循。", "b": "《淮南子·汜论训》"}], "words": [{"w": "循律", "t": "遵循法律、制度"}, {"w": "循分", "t": "遵守本分。"}]}, {"meaning": "巡视。", "cites": [{"t": "循行国邑。", "b": "《礼记·月令》"}, {"t": "循,巡也。", "b": "《珠丛》"}, {"t": "徼循长杨以东。", "b": "《汉书·东方朔传》。注:“行视也。”"}], "words": [{"w": "循览", "t": "浏览。"}]}, {"meaning": "步行。", "cites": [{"t": "今重甲循兵,不可以逾险。", "b": "《战国策》"}, {"t": "拊循和辑。", "b": "《汉书·赵充国传》"}, {"t": "拊循勉百姓。", "b": "《汉书·萧何传》"}, {"t": "子反收余兵,拊循欲复战。", "b": "《史记·晋世家》"}, {"t": "拊循和辑。", "b": "《汉书·赵充国传》"}, {"t": "拊循勉百姓。", "b": "《汉书·萧何传》"}, {"t": "子反收余兵,拊循欲复战。", "b": "《史记·晋世家》"}], "words": [{"w": "循步", "t": "行步,慢步。"}]}, {"meaning": "安抚。", "cites": [{"t": "内牧百姓,循抚其心。", "b": "《战国策》"}], "words": [{"w": "循拊", "t": "安抚;抚慰"}, {"w": "循抚", "t": "安抚。"}]}, {"meaning": "抚慰;摩;抚摩。", "cites": [{"t": "缪缪肫肫,其事不可循。", "b": "《荀子·哀公》"}, {"t": "循石,非彼无石。", "b": "《公孙龙子·坚白论》"}, {"t": "视之不见,听之不闻,循之不得,故曰易也。", "b": "《列子·天瑞》"}, {"t": "而数数自循其刀环。", "b": "《汉书·李陵传》"}], "words": [{"w": "循玩", "t": "抚摩赏玩。"}]}, {"meaning": "恭谨。", "cites": [{"t": "臣以济循事王,王能亡燕…", "b": "《战国策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2706wx','艇','1','tǐng','舟','12','','[{"pinyin": "tǐng", "defs": [{"meaning": "(形声。从舟,廷声。本义:轻便小船)。"}, {"meaning": "同本义。", "cites": [{"t": "岸上无人小艇斜。", "b": "唐·孙光宪《竹枝词》"}, {"t": "以小艇游庙中。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "游艇;救生艇;橡皮艇;鱼雷艇;艇板", "t": "跳板"}, {"w": "艇子", "t": "小船;亦指船夫。"}]}, {"meaning": "大船 。", "words": [{"w": "登陆艇;潜水艇", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2707wx','舒','1','shū','舌','12','','[{"pinyin": "shū", "defs": [{"meaning": "(会意兼形声。从舍,从予,予亦声。本义:伸展,舒展)。"}, {"meaning": "同本义。", "cites": [{"t": "舒,伸也。", "b": "《说文》"}, {"t": "匪安匪舒。", "b": "《诗·大雅·江汉》"}, {"t": "舒,展也。", "b": "《广雅》"}, {"t": "舒勃,展也。东齐之间,凡展物谓之舒勃。", "b": "《方言亢》"}, {"t": "赢缩卷舒。", "b": "《淮南子·本经》。注:“舒,散也。”"}, {"t": "舒忧娱哀。", "b": "《楚辞·怀沙》"}, {"t": "然而蛾脸不舒,巾袖无光。", "b": "唐·李朝威《柳毅传》"}, {"t": "在那里舒头探脑价望。", "b": "《水浒传》"}, {"t": "把拳头舒过来。", "b": "《儒林外史》"}], "words": [{"w": "舒卷", "t": "张开或卷起"}, {"w": "舒手", "t": "松手;伸手"}, {"w": "舒头", "t": "伸头"}, {"w": "舒直立", "t": "伸腰直立"}, {"w": "舒勃", "t": "开展,展开"}, {"w": "舒眉", "t": "展眉。快乐无忧的样子"}, {"w": "舒啸", "t": "舒怀啸歌"}, {"w": "舒筋活血", "t": "使筋肉舒适,血脉流通"}, {"w": "舒启", "t": "伸展"}, {"w": "舒达", "t": "伸展分布"}, {"w": "舒布", "t": "展开;散布。"}]}, {"meaning": "展现。", "cites": [{"t": "缺月向人舒窈窕,三星当户照绸缪。", "b": "宋·苏轼《浣溪沙》"}]}, {"meaning": "宣泄积滞,抒发。", "cites": [{"t": "退而论书策,以舒其愤。", "b": "汉·司马迁《报任安书》"}], "words": [{"w": "舒愤", "t": "抒发愤懑"}, {"w": "舒忧", "t": "抒发忧思,忧虑"}, {"w": "舒泄", "t": "抒发,发泄"}, {"w": "舒和", "t": "抒发阳和之气"}, {"w": "舒情", "t": "抒发情怀"}, {"w": "舒泻", "t": "抒发,发泄。"}]}, {"meaning": "徐;迟缓;舒缓。", "cites": [{"t": "舒,舒缓也。", "b": "《说文》"}, {"t": "舒,缓也。", "b": "《尔雅》"}, {"t": "舒,迟也。", "b": "《广雅》"}, {"t": "舒而脱脱兮。", "b": "《诗·召南·野有死麕》"}, {"t": "舒窈纠兮。", "b": "《诗·陈风·月出》。传:“迟也。”"}, {"t": "君子容舒迟。", "b": "《礼记·玉藻》"}], "words": [{"w": "舒舒", "t": "缓慢的祥子"}, {"w": "舒和", "t": "舒缓和顺"}, {"w": "舒扬", "t": "举止从容不迫"}, {"w": "舒暇", "t": "从容不迫貌"}, {"w": "舒迟", "t": "犹舒徐。从容不迫貌"}, {"w": "舒慢", "t": "迟缓懈怠"}, {"w": "舒徐", "t": "自如;从容不迫。"}]}, {"meaning": "舒畅。", "cites": [{"t": "宾客意少舒。", "b": "林嗣环《口技》"}], "words": [{"w": "舒摊", "t": "舒适"}, {"w": "舒怀", "t": "开怀;心情舒畅"}, {"w": "舒舒", "t": "心胸安和宽广的样子。"}]}, {"meaning": "宽;广阔。", "cites": [{"t": "万里长江横渡,极目楚天舒。", "b": "毛泽东《水调歌头游泳》"}]}, {"meaning": "古国名 。春秋时为徐所灭。后置县,故城在今安徽省庐江县西。"}, {"meaning": "徐缓。", "cites": [{"t": "登东皋以舒啸,临清流而赋诗。", "b": "晋·陶渊明《归去来兮辞》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2708wx','逾','1','yú','辶','12','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从辵(chuò),俞声。本义:越过,经过)。"}, {"meaning": "同本义。", "words": [{"w": "逾迈", "t": "走过;时光易逝"}, {"w": "逾墙钻穴", "t": "指男女偷情;跳墙钻洞"}, {"w": "逾墉", "t": "越过城墙"}, {"w": "逾墙", "t": "越过矮墙"}, {"w": "逾假不归", "t": "即假期已满而未归营"}, {"w": "逾轨", "t": "越轨。"}]}, {"meaning": "超过;胜过。", "cites": [{"t": "无敢昏逾。", "b": "《书·顾命》"}, {"t": "日月逾迈。", "b": "《书·秦誓》"}, {"t": "物或逾秋不死,亦如人年多度百至于三百也。", "b": "汉·王充《论衡·气寿》"}, {"t": "越职逾法,以取名誉。", "b": "《汉书·宣帝纪》"}, {"t": "去逾四十里,之虚所卖之。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "逾千", "t": "超过一千"}, {"w": "逾出", "t": "突出,超过一般"}, {"w": "逾立", "t": "超过三十岁"}, {"w": "逾世", "t": "超过当代人"}, {"w": "逾冠", "t": "超过二十岁。"}]}, {"meaning": "指晋升职位。", "cites": [{"t": "臣不逾级,则主位安。", "b": "汉·贾谊《服疑》"}], "words": [{"w": "逾格", "t": "破格"}, {"w": "逾进", "t": "超级提升。"}]}, {"meaning": "更加。", "cites": [{"t": "美超远而逾迈。", "b": "《楚辞·九章·哀郢》"}, {"t": "乱乃逾甚。", "b": "《淮南子》"}], "words": [{"w": "逾加", "t": "更加"}, {"w": "逾甚", "t": "更甚,过甚"}, {"w": "逾世", "t": "更加放纵。"}]}, {"meaning": "远。", "cites": [{"t": "福逾刺凤。", "b": "《汉书·叙传》。注:“远也。”"}, {"t": "毋踰言。", "b": "《礼记·投壶》"}, {"t": "志之所在,踰于千里。", "b": "《淮南子·主术》"}, {"t": "遥逝兮逾远,缅邈兮长乖。", "b": "晋·潘岳《寡妇赋》"}], "words": [{"w": "逾言", "t": "遥相谈话"}, {"w": "逾处", "t": "远离居处"}, {"w": "逾望", "t": "遥望;远望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2709wx','番','1','fān pān','田','12','','[{"pinyin": "fān", "defs": [{"meaning": "(象形。小篆字形,上面象野兽的足掌和爪,下面的“田”象兽足踩出的印子。①本义:兽足。②更替,替代,轮流)。"}, {"meaning": "更替,轮值。", "cites": [{"t": "顿兵一万,番代往来。", "b": "《北史·贺弼传》"}, {"t": "漏鼓移则番代。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "番代", "t": "轮流更换"}, {"w": "番休", "t": "轮流休息"}, {"w": "番更", "t": "轮流巡夜。"}]}, {"meaning": "次,回。", "cites": [{"t": "迭为三番。", "b": "《列子·汤问》"}], "words": [{"w": "几番风雨;番把", "t": "几次"}, {"w": "番番是福", "t": "每件事都吉利。"}]}, {"meaning": "片;枚;块。", "cites": [{"t": "宫中造清思院新殿,用铜镜三千片,黄白金薄十万番。", "b": "《旧唐书》"}]}, {"meaning": "古代计算纸张的单位。", "cites": [{"t": "[杜暹]秩满归,吏以纸万番赆之,暹为受百番。", "b": "《新唐书》"}]}, {"meaning": "草木茂盛。", "cites": [{"t": "子子孙孙,永永番昌。", "b": "汉《白石神君碑》"}]}, {"meaning": "篱笆。", "cites": [{"t": "抗折其貌以象墁(màn以泥茨涂屋)茨番阏(è雍塞)也。", "b": "《荀子·礼论》。杨倞注:“番,读为藩。藩篱也。”"}]}]}, {"pinyin": "pān", "defs": [{"meaning": "", "cites": [{"t": "皇父卿士,番维司徒。", "b": "《诗·小雅》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2710wx','释','1','shì','采','12','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从采(biàn),睪(yì)声。采,有辨别、分析义。本义:脱掉,解下)。"}, {"meaning": "同本义。", "cites": [{"t": "释,解也。从采,取其分别物也。睪声。", "b": "《说文》"}, {"t": "释获。", "b": "《仪礼·大射仪》"}, {"t": "释左骖,以公命赠孟明。", "b": "《左传·僖公三十三年》"}, {"t": "昭公出奔,民如释重负。", "b": "《谷梁传·昭公二十九年》"}, {"t": "主人释服。", "b": "《仪礼》"}], "words": [{"w": "释绂", "t": "解下印绶。指致仕罢官"}, {"w": "释褐", "t": "除去平民的衣服,换上官服。即“作官”。"}]}, {"meaning": "解释。", "cites": [{"t": "[夫差]乃使行人奚斯释言于齐。", "b": "《国语·吴语》"}], "words": [{"w": "释情消迹", "t": "消除误会;予以和解"}, {"w": "释言", "t": "以言语自作解释"}, {"w": "释例", "t": "说明所著书的凡例。"}]}, {"meaning": "释放;赦免。", "cites": [{"t": "怀王竟听郑袖,复释去张仪。", "b": "《史记·屈原贾生列传》"}, {"t": "豪民气尽,以额叩头,谢不敢。乃释之。", "b": "明·高启《书博鸡者事》"}]}, {"meaning": "舍弃;抛弃。", "cites": [{"t": "故释先王之法,而法其所以为法。", "b": "《吕氏春秋·察今》"}, {"t": "乃请释子服何于吴。", "b": "《左传·哀公八年》"}, {"t": "君其释申生也。", "b": "《国语·晋语》。注:“释,舍也。”"}], "words": [{"w": "释法", "t": "舍弃法令而不施用。"}]}, {"meaning": "放下;放开。", "cites": [{"t": "有卖油翁释担而立。", "b": "宋·欧阳修《归田录》"}, {"t": "庖丁释刀对曰:“臣之所好者,道也。”", "b": "《庄子·养生主》"}], "words": [{"w": "力叮不释", "t": "用力叮住不放。"}]}, {"meaning": "消失。", "cites": [{"t": "虽欲爱君,惑不释也。", "b": "《国语·晋语》"}]}, {"meaning": "溶化;消融。", "cites": [{"t": "涣兮其若冰之将释。", "b": "《老子》"}], "words": [{"w": "如冰之将释", "t": "就像冰将消融那样。"}]}, {"meaning": "泡在水里或其他液体里。", "cites": [{"t": "欲濡肉,则释而煎之以醢。", "b": "《礼记·内则》"}]}, {"meaning": "发,射出。", "cites": [{"t": "若虞机张,往省括于度,则释。", "b": "《书·太甲上》"}]}, {"meaning": "解除;免除。", "cites": [{"t": "不以一己之害为害,而使天下释其害。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "释去仔肩", "t": "卸掉责任;放下重担"}, {"w": "释憾", "t": "解除心中的怨恨。指报复"}, {"w": "释难", "t": "解除困难"}, {"w": "释闷", "t": "解闷儿;排遣烦闷"}, {"w": "释四增美", "t": "除去邪僻之念,增加美善的质性。"}]}, {"meaning": "淘米。", "cites": [{"t": "释之叟叟,烝之浮浮。", "b": "《诗·大雅·生民》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2711wx','禽','1','qín','忄','12','','[{"pinyin": "qín", "defs": [{"meaning": "(象形。本义:走兽总名)。"}, {"meaning": "同本义。", "cites": [{"t": "禽,走兽总名。", "b": "《说文》"}, {"t": "禽者何?鸟兽之总名", "b": "《白虎通》"}, {"t": "命主祠祭禽于四方。", "b": "《礼记·月令》。疏:“兽之通名也。”"}, {"t": "傅翼戴角,分牙布爪,仰飞俯走,谓之禽兽。", "b": "《列子·黄帝》"}, {"t": "六禽。", "b": "《周礼·庖人》。注:“宜为羔豚、犊、麝、雉、鴈。凡鸟兽未孕曰禽。”"}, {"t": "终日而不获一禽。", "b": "《孟子·滕文公下》"}, {"t": "吾有一术,名五禽之戏。一曰虎,二曰鹿,三曰熊,四曰猿,五曰鸟。", "b": "《三国志·华陀传》"}, {"t": "虎亦诸禽之雄也。", "b": "汉·王充《论衡·遭虎》"}]}, {"meaning": "鸟类的总称。", "cites": [{"t": "二足而羽谓之禽。", "b": "《尔雅》"}, {"t": "六禽。", "b": "《周礼·庖人》。司农注:“鴈、鹑、鷃、雉、鸠、鸽也。”"}, {"t": "田有禽虞。", "b": "《易·师》"}, {"t": "执禽者左首。", "b": "《礼记·曲礼》。疏:“鸟也。”"}, {"t": "越禽不恋燕。", "b": "李白《左风五十九首》"}], "words": [{"w": "鸣禽;禽言", "t": "鸟语。指鸟类啼鸣"}, {"w": "禽语", "t": "鸟语;鸟鸣"}, {"w": "禽卵", "t": "鸟卵"}, {"w": "禽戏", "t": "禽鸟嬉戏"}, {"w": "家禽", "t": ""}]}, {"meaning": "捕获鸟兽。", "cites": [{"t": "之日狩,允禽。", "b": "《甲骨文合集》"}, {"t": "两者不肯相舍,渔者得而并禽之。", "b": "《战国策·燕策二》"}], "words": [{"w": "禽色", "t": "田猎与女色"}, {"w": "禽荒", "t": "沈迷于田猎。"}]}, {"meaning": "捕捉。", "cites": [{"t": "外仆髡屯禽之以献。", "b": "《左传·僖公三十三年》"}, {"t": "一时收禽。", "b": "《后汉书·张衡传》"}, {"t": "将军禽操。", "b": "《资治通鉴》"}], "words": [{"w": "禽囚", "t": "被擒获的俘虏"}, {"w": "禽夷", "t": "擒灭"}, {"w": "禽制", "t": "捉拿制伏"}, {"w": "禽殄", "t": "擒获歼灭"}, {"w": "禽俘", "t": "擒获"}, {"w": "禽疾", "t": "指需要迅速擒拿的人"}, {"w": "禽剪", "t": "擒灭"}, {"w": "禽虏", "t": "擒捉敌人。"}]}, {"meaning": "战胜。", "cites": [{"t": "虞、虢共守之,晋不能禽也。", "b": "《新序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2712wx','腊','1','là xī','月','12','','[{"pinyin": "là", "defs": [{"meaning": "(形声。从肉,巤(liè)声。本义:年终祭祀) 祭名。古代阴历十二月的一种祭祀。冬至后第三个戌日祭祀众神。", "cites": [{"t": "冬至后三戌,腊祭百神。", "b": "《说文》。字亦作臈。"}, {"t": "夏曰嘉平,殷曰清祀,周曰大蜡,汉曰腊。", "b": "蔡邕《独断》"}, {"t": "腊先祖五祀。", "b": "《礼记·月令》"}, {"t": "虞不腊矣。", "b": "《左传·僖公五年》"}], "words": [{"w": "腊日", "t": "古时腊祭之日。农历十二月初八"}, {"w": "腊祭", "t": "古时岁终祭祀"}, {"w": "腊会", "t": "古代腊祭时的集会"}, {"w": "腊鼻", "t": "本为劣等鹞鹰,喻指无能之人。"}]}, {"meaning": "农历十二月。", "cites": [{"t": "腊后花期知渐近,寒梅已作东风信。", "b": "晏殊《蝶恋花》"}]}, {"meaning": "人出生后七天。", "cites": [{"t": "人之初生,以七日为腊;人之初死,以七日为忌。", "b": "《玉笑零音》"}]}]}, {"pinyin": "xī", "defs": [{"meaning": "(形声。从肉,昔声。本义:干肉) 同本义。", "cites": [{"t": "腊,脯也。", "b": "《广雅·释器》"}, {"t": "噬腊肉。", "b": "《曷·噬》"}, {"t": "鱼腊。", "b": "《穆天子传》。注:“干鱼。”"}, {"t": "无腊与肤。", "b": "《仪礼·有司彻》。注:“腊为庶羞。”"}, {"t": "布千匹,腊五百斤。", "b": "《晋书·谢安传》"}], "words": [{"w": "腊肉", "t": "干肉"}, {"w": "腊人", "t": "古官名。掌干肉。"}]}, {"meaning": "晒干;制成干肉。", "cites": [{"t": "然得而腊之以为饵。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "腊田", "t": "干枯的田。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2713wx','脾','1','pí','月','12','','[{"pinyin": "pí", "defs": [{"meaning": "(形声。从月(肉);卑声。本义:脾脏。人和脊椎动物的内脏之一,是贮血和产淋巴与抗体的器官,有调节新陈代谢的作用。中医称“五脏”之一)。"}, {"meaning": "同本义。", "cites": [{"t": "脾,土藏也。", "b": "《说文》"}, {"t": "脾者,谓之主。", "b": "《春秋元命苞》"}, {"t": "祭先脾。", "b": "《礼记·月令》"}], "words": [{"w": "脾土", "t": "中医用语,指脾"}, {"w": "脾析", "t": "牛胃"}, {"w": "脾家", "t": "脾脏所在之处"}, {"w": "脾和", "t": "脾性相合,意气相投"}, {"w": "脾味", "t": "兴趣爱好;脾性,脾气。"}]}, {"meaning": "大腿。", "cites": [{"t": "鸿蒙方将拊脾雀跃而游。", "b": "《庄子·在宥》"}, {"t": "达于右脾。", "b": "《公羊传·桓公四年》"}]}, {"meaning": "牛胃。", "cites": [{"t": "嘉殽脾臄,或歌或咢。", "b": "《诗·大雅·行苇》"}, {"t": "蠃醢脾析。", "b": "《周礼·天官·醢人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2714wx','腋','1','yè','月','12','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。从肉,夜声。本作“亦”,“大”(人)下两点表示腋的部位。本义:胳肢窝)。"}, {"meaning": "同本义。", "cites": [{"t": "胳谓之腋。", "b": "《广雅》"}, {"t": "珍裘非一腋。", "b": "《文选·卢谌答魏子悌诗》。注引《埤苍》:“腋在肘后。”"}, {"t": "赴水则接腋持颐,蹶泥则没足灭跗。", "b": "《庄子》"}], "words": [{"w": "腋毛;腋翅", "t": "腋下生翅,意犹飞身"}, {"w": "腋臊", "t": "腋臭,狐臭。"}]}, {"meaning": "禽兽翅膀或前腿内侧和胸部相连的部分。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2715wx','腔','1','qiāng','月','12','','[{"pinyin": "qiāng", "defs": [{"meaning": "(会意兼形声。从月(肉),从空,空亦声。本义:人和动物体内的空处)。"}, {"meaning": "同本义。", "cites": [{"t": "腔,内空也。从肉,从空,空亦声。", "b": "《说文新附》"}], "words": [{"w": "腔子", "t": "胸腔"}, {"w": "口腔;胸腔;生殖腔;胚盘下腔;胸膜腔;心腔;肾球囊腔;颅腔;腹腔;肠腔;子宫腔;髓腔", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2716wx','腕','1','wàn','月','12','','[{"pinyin": "wàn", "defs": [{"meaning": "(形声。从肉,宛声。本义:臂下端与手掌相连可以活动的部分)。"}, {"meaning": "同本义。", "words": [{"w": "腕表", "t": "手表"}, {"w": "腕脱", "t": "手腕脱位。形容书写忙迫紧张"}, {"w": "腕钏", "t": "手镯"}, {"w": "腕法", "t": "写字用腕的方法"}, {"w": "腕头", "t": "犹言手上"}, {"w": "腕阑", "t": "手镯类的饰物。"}]}, {"meaning": "和臂相仿的任何某些突起物。"}, {"meaning": "海百合的放射线。"}, {"meaning": "头足类的触手。"}, {"meaning": "似触手的突起物。"}, {"meaning": "某些水母脑内的白色带状物。"}, {"meaning": "构成鳃足类触手冠的任意卷曲的肌肉附肢。"}, {"meaning": "手段;伎俩。", "cites": [{"t": "何功使愿果,尽力输老腕。", "b": "元·张雨诗"}]}, {"meaning": "握。", "cites": [{"t": "腕,握也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2717wx','鲁','1','lǔ','鱼','12','','[{"pinyin": "lǔ", "defs": [{"meaning": "(会意。甲骨文从鱼,从口,“口”象器形。整个字形象鱼在器皿之中。本义:鱼味美,嘉)。"}, {"meaning": "同本义。", "cites": [{"t": "(古鲁字)从曰,不从白,彝器每言“鲁休”,“纯鲁”,阮氏元云:“鲁本义盖为嘉,从鲁入口,嘉美也。”", "b": "林义光《文源》"}]}, {"meaning": "迟钝,愚钝。", "cites": [{"t": "参也鲁。", "b": "《论语》"}, {"t": "鲁人以为敏。", "b": "《左传》"}, {"t": "容居,鲁人也。", "b": "《礼记·檀弓》"}], "words": [{"w": "鲁拙", "t": "笨拙"}, {"w": "鲁人", "t": "鲁钝的人,愚钝的人。"}]}, {"meaning": "中国春秋时国名 ,在山东省南部。周武王封其弟周公旦于鲁。战国时为楚所灭。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2718wx','猩','1','xīng','犭','12','','[{"pinyin": "xīng", "defs": [{"meaning": "猩猩的省称。"}, {"meaning": "鲜红色。", "cites": [{"t": "俄而大轿内抬着一个乌帽猩袍的官府来了。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
