('2719wx','猬','1','wèi','犭','12','','[{"pinyin": "wèi", "defs": [{"meaning": "兽名。即刺猬。", "cites": [{"t": "矢如猬毛。", "b": "宋·司马光《资治通鉴·唐纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2720wx','猾','1','huá','犭','12','','[{"pinyin": "huá", "defs": [{"meaning": "(形声。从犬,骨声。本义:狡诈,狡猾) 同本义。", "cites": [{"t": "猥胥报充里正。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "猾虏", "t": "狡猾之徒"}, {"w": "猾伯", "t": "最狡猾虚妄的人"}, {"w": "狡胥", "t": "狡猾的小吏"}, {"w": "猾恶", "t": "狡猾奸恶。"}]}, {"meaning": "弄,播弄。", "cites": [{"t": "遇兆,挟以衔骨,齿牙为猾,戎夏交捽。", "b": "《国语》"}]}]}]','jingmo-wenyan');
