('2721wx','猴','1','hóu','犭','12','','[{"pinyin": "hóu", "defs": [{"meaning": "像猴子一样攀援纠缠。", "cites": [{"t": "宝玉听话,便猴向凤姐身上立刻要牌。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2722wx','惫','1','bèi','心','12','','[{"pinyin": "bèi", "defs": [{"meaning": "(形声。从心,備声。本义:疲乏,困顿)。"}, {"meaning": "同本义。", "cites": [{"t": "疲极曰惫。", "b": "《通俗文》"}, {"t": "单惫于戏笑。", "b": "《列子·黄帝》"}, {"t": "往来惛惫,通于大神。", "b": "《荀子赋》"}, {"t": "何先生之惫耶?", "b": "《庄子·山水》"}, {"t": "三年克之,惫也。", "b": "《易·既济》"}], "words": [{"w": "疲惫", "t": "非常疲乏"}, {"w": "惫喘", "t": "疲惫而喘息"}, {"w": "惫劳", "t": "疲劳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2723wx','然','1','rán','灬','12','','[{"pinyin": "rán", "defs": [{"meaning": "(会意兼形声。下形,上声。四点是火的变形。声符读yàn,是狗肉的意思,下面加火以烤狗肉。本义:燃烧)。"}, {"meaning": "同本义。“然”是“燃”的本字。", "cites": [{"t": "然,烧也。", "b": "《说文》"}]}, {"meaning": "俗字作“燃”。", "cites": [{"t": "若火之始然。", "b": "《孟子》"}, {"t": "蒸间容蒸,然者处下焉。", "b": "《管子·弟子职》"}, {"t": "夜然脂照城外。", "b": "《三国志·刘馥传》"}], "words": [{"w": "然海", "t": "古代传说中的油海,其水可燃"}, {"w": "然脂", "t": "点油脂或蜡烛照明"}, {"w": "然灰", "t": "死灰复燃"}, {"w": "然除", "t": "烧毁"}, {"w": "然火", "t": "点火"}, {"w": "然炬", "t": "点燃火炬"}, {"w": "然脂", "t": "泛指点燃火炬"}, {"w": "然犀", "t": "传说点燃犀牛的角可以照见怪物。后以明察事务为然犀"}, {"w": "然灯", "t": "点灯。"}]}, {"meaning": "明白。", "cites": [{"t": "夫燧之取火于日,慈石之引铁,蟹之败漆,葵之乡日,虽有明智,弗能然也。", "b": "《淮南子·览冥》"}]}, {"meaning": "耀;照耀。", "cites": [{"t": "然目之绮,裂鼻之馨。", "b": "杨衒之《洛阳伽蓝记·正始寺》"}]}, {"meaning": "以为…对;同意。", "cites": [{"t": "广以为然。", "b": "《史记·陈涉世家》"}, {"t": "愬然之。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "然纳", "t": "同意采纳"}, {"w": "然疑", "t": "半信半疑,犹豫不决"}, {"w": "然赞", "t": "赞同"}, {"w": "然然可可", "t": "犹唯唯诺诺"}, {"w": "然可", "t": "同意"}, {"w": "然诺", "t": "答允,许诺"}, {"w": "然许", "t": "然信。许诺;信守诺言"}, {"w": "然信", "t": "然诺,许诺"}, {"w": "然可", "t": "应允。"}]}, {"meaning": "形成。", "cites": [{"t": "楹之铭曰:毋曰胡残,其祸将然。", "b": "《大戴礼记》"}]}, {"meaning": "宜;合适。", "cites": [{"t": "所谓无不治者,因物之相然也。", "b": "《淮南子》"}]}, {"meaning": "但是,然而。", "cites": [{"t": "[虎]甚恐,然往来视之,觉无异能者。", "b": "唐·柳宗元《三戒》"}, {"t": "然不自意能先入关破秦。", "b": "《史记·项羽本纪》"}], "words": [{"w": "然且", "t": "然而;尚且"}, {"w": "然如", "t": "然而。"}]}, {"meaning": "于是。", "cites": [{"t": "孔子曰:“其男子有死之志,妇人有保西河之志。吾所伐者不过四五人。”灵公曰:“善。”然不伐蒲。", "b": "《史记》"}]}, {"meaning": "是,对  假借为嘫。", "cites": [{"t": "然,应也。", "b": "《广雅》"}, {"t": "子曰:然。", "b": "《论语·阳货》"}, {"t": "不侵为然诺者也。", "b": "《史记·张耳陈馀传》"}, {"t": "公见其妻曰:“此子之内子邪?”晏子对曰:“然,是也。”", "b": "《晏子春秋》"}]}, {"meaning": "如此,这样,那样。", "cites": [{"t": "虽有槁暴,不复挺者,輮使之然也。", "b": "《荀子·劝学》"}, {"t": "河内凶,则移其民于河东,移其粟于河内;河东凶亦然。", "b": "《孟子》"}], "words": [{"w": "理所当然;其实不然", "t": ""}]}, {"meaning": "用作形容词或副词的词尾,表示状态,有“如”的意义。", "cites": [{"t": "庞然大物也。", "b": "唐·柳宗元《三戒》"}, {"t": "康肃忿然曰。", "b": "宋·欧阳修《卖油翁》"}], "words": [{"w": "突然;斐然;欣然;惠然;贸然;蔚然", "t": ""}]}, {"meaning": "用作句末语气词,表示比拟,有“…的样子”之意。常与“如”、“若”连用,有“如…一般”、“像…一样”之意。", "cites": [{"t": "人之视己,如见其肺肝然,则何益矣?", "b": "《礼记》"}]}, {"meaning": "用作句末语气词,表示断定或决定,相当于古汉语的“焉”、“也”。", "cites": [{"t": "穆公召县子而问然。", "b": "《礼记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2724wx','馈','1','kuì','饣','12','','[{"pinyin": "kuì", "defs": [{"meaning": "(形声。从食,贵声。本义:以食物送人)。"}, {"meaning": "同本义。", "cites": [{"t": "馈,饷也。", "b": "《说文》"}, {"t": "陈馈八簋。", "b": "《诗·小雅·伐木》"}, {"t": "君有馈焉曰献。", "b": "《礼记·檀弓》"}, {"t": "国胡以馈之。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "馈孰", "t": "献熟食"}, {"w": "馈食", "t": "献熟食"}, {"w": "馈飱", "t": "进献饭食"}, {"w": "馈馔", "t": "以食物送人"}, {"w": "馈献", "t": "献熟食。"}]}, {"meaning": "进食。", "cites": [{"t": "在中馈。", "b": "《易·家人》。释文:“食也。”"}], "words": [{"w": "馈养", "t": "进食奉养。"}]}, {"meaning": "赠送。", "cites": [{"t": "馈,遗也。", "b": "《广雅》"}, {"t": "古者致物于人,尊之则曰献,通行曰馈。", "b": "《周礼·天官》注"}, {"t": "馈者,上下通称。故祭祀于神而言馈。阳货馈孔子豚而言馈,乡党云朋友之馈,是上下通言馈。", "b": "《仪礼·士虞礼》疏"}, {"t": "于是诸侯之大于戍齐,齐人馈之以饩。", "b": "《左传·桓公六年》"}, {"t": "王及列士,皆有馈赂。", "b": "《左传·哀公十一年》"}, {"t": "朋友之馈,虽车马,非祭肉不拜。", "b": "《论语·乡党》"}], "words": [{"w": "馈选", "t": "中选"}, {"w": "馈岁", "t": "旧岁年终亲友互相馈赠"}, {"w": "馈饷", "t": "赠与财物"}, {"w": "馈赆", "t": "赠送远行者的财物。"}]}, {"meaning": "祭祀。", "cites": [{"t": "祭祀自孰始曰馈食。馈食者,食道也。", "b": "《仪礼·特牲馈食礼》注"}], "words": [{"w": "馈奠", "t": "丧中祭奠之事"}, {"w": "馈祀", "t": "以酒饭祭鬼神。"}]}, {"meaning": "饮食之事。", "cites": [{"t": "燕养馈羞,汤沐之馔,如他日。", "b": "《仪礼·既夕礼》"}]}, {"meaning": "食物。", "cites": [{"t": "先生将食,弟子馔馈。", "b": "《管子·弟子职》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2725wx','馋','1','chán','饣','12','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从食,毚(chán)声。本义:贪嘴,贪食)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2726wx','装','1','zhuāng','衣','12','','[{"pinyin": "zhuāng", "defs": [{"meaning": "(形声。从衣,壮声。本义:行装)。"}, {"meaning": "同本义。", "cites": [{"t": "装,裹也。", "b": "《说文》"}, {"t": "橐中装。", "b": "《史记·郦生陆贾传》"}, {"t": "简元辰而俶装。", "b": "张衡《思玄赋》。注:“束也。”"}, {"t": "顾形影,自整装。", "b": "《文选·傅毅·舞赋》"}, {"t": "于是约车治装,载卷契而行。", "b": "《战国策·齐策四》"}, {"t": "为装遣荆轲。", "b": "《战国策·燕策》"}], "words": [{"w": "装囊", "t": "行囊,远行者携带的袋子"}, {"w": "装束", "t": "束装,整理行装。"}]}, {"meaning": "服装。", "cites": [{"t": "富者赂数十百金,贫亦罄衣装。", "b": "方苞《狱中杂记》"}], "words": [{"w": "童装;春装;夏装;冬装;男装;女装;猎装;学生装;军装;古装;装束", "t": "衣着穿戴。"}]}, {"meaning": "装饰;打扮(指一般的装点)。", "cites": [{"t": "体美容冶,不待饰装。", "b": "《文选·宋玉·登徒子好色赋》"}, {"t": "交语速装束,络绎如浮云。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "千金装马鞍,百金装刀头。", "b": "唐·杜甫《后出塞》"}, {"t": "宝装屏风。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "装柳", "t": "给死者穿衣前,摆顺理平其手脚"}, {"w": "装奁", "t": "女子梳装用的镜匣"}, {"w": "装背", "t": "装裱书画。"}]}, {"meaning": "装作,假装。", "cites": [{"t": "也不言语,只装鬼脸。", "b": "《红楼梦》"}, {"t": "今人做诗,多爱装造言语。", "b": "盛如梓《庶斋老学丛谈》"}], "words": [{"w": "装煞臭幺", "t": "摆臭架子"}, {"w": "装套子", "t": "设置圈套"}, {"w": "装腔", "t": "说假话装得若有其事的样子。"}]}, {"meaning": "贮放;藏。", "cites": [{"t": "乃装黄金千溢,置褐器中。", "b": "《史记》"}]}, {"meaning": "运载。", "cites": [{"t": "私奴装粮食来。", "b": "《晋书》"}]}, {"meaning": "装入;放进。", "cites": [{"t": "征衣一倍装绵厚,犹虑交河雪冻深。", "b": "唐·陈陶《水调词》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2727wx','蛮','1','mán','虫','12','','[{"pinyin": "mán", "defs": [{"meaning": "(形声。本义:中国古代对南方各族的泛称。旧时也用以泛指四方的少数民族)。"}, {"meaning": "同本义。", "cites": [{"t": "蛮,南蛮也。", "b": "《说文》"}, {"t": "蛮畿。", "b": "《周礼·大司马》"}, {"t": "蛮服。又,四夷、八蛮、七闽、九貉、五戎、六狄之人民。", "b": "《周礼·职方氏》"}, {"t": "九夷、八狄、七戎、六蛮谓之四海。", "b": "《尔雅·释地》"}, {"t": "三百里蛮。", "b": "《书·禹贡》"}, {"t": "蛮荆来威。", "b": "《诗·小雅·采芑》"}, {"t": "蛮夷要服。", "b": "《国语·周语》"}, {"t": "瘴疠浮三蜀,风云暗百蛮。", "b": "杜甫《闷》"}], "words": [{"w": "蛮声哈剌", "t": "南方叽哩呱拉的声音"}, {"w": "蛮人", "t": "指南方人"}, {"w": "蛮布", "t": "蛮人所织的布"}, {"w": "蛮风", "t": "指南方蛮地的风;蛮地的风情习俗,引申为粗野的风俗"}, {"w": "蛮烟", "t": "南方蛮地的瘴烟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2728wx','就','1','jiù','尢','12','','[{"pinyin": "jiù", "defs": [{"meaning": "(会意。京尤会意。“京”意为高,“尤”意为特别。本义:到高处去住)。"}, {"meaning": "同本义。", "cites": [{"t": "就,就高也。从京从尤。尤,异于凡也。", "b": "《说文》。桂馥注:“此言人就高以居也。”孔广居注:“京,高丘也。古时洪水横流,故高丘之异于凡者人就之。”"}]}, {"meaning": "靠近;走近;趋向。", "cites": [{"t": "就,即也。", "b": "《广韵》"}, {"t": "主人就东阶,客就西阶。", "b": "《礼记·曲礼》"}, {"t": "不就利,不违害。", "b": "《庄子·齐物论》"}, {"t": "不知就先,不知就后。", "b": "《庄子·大宗师》"}, {"t": "禹趋就下风,立而问焉。", "b": "《庄子·天地》"}, {"t": "夫子休就舍。", "b": "《庄子·说剑》"}, {"t": "金就砺则利。", "b": "《荀子·劝学》"}, {"t": "去故乡而就远兮。", "b": "《楚辞·九章·哀郢》"}, {"t": "还来就菊花。", "b": "唐·孟浩然《过故人庄》"}, {"t": "就吾求寒衣。", "b": "《资治通鉴·唐纪》"}, {"t": "持就火炀之。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "就童子试。", "b": "清·周容《芋老人传》"}], "words": [{"w": "就书", "t": "前往从学"}, {"w": "就利", "t": "趋利,求利"}, {"w": "就第", "t": "归回宅第;回家"}, {"w": "就和", "t": "接近。"}]}, {"meaning": "归于。", "cites": [{"t": "处工就官府,处商就井市。", "b": "《国语》"}], "words": [{"w": "就化", "t": "归顺,向化"}, {"w": "就班", "t": "按次序归位"}, {"w": "就款", "t": "归顺臣服。"}]}, {"meaning": "完成;成功。", "cites": [{"t": "三窟已就,君姑高枕为乐矣。", "b": "《战国策·齐策》"}, {"t": "组已就而效之,其组异善。", "b": "《韩非子·外储说右上》"}, {"t": "以就懿德。", "b": "《后汉书·列女传》"}, {"t": "瞬息可就。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "指物作诗立就。", "b": "宋·王安石《伤仲永》"}, {"t": "某业所就。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "就亲", "t": "成就婚事,成亲"}, {"w": "就名", "t": "成就功名。"}]}, {"meaning": "迁就;将就。", "cites": [{"t": "刑罚不审则有辟就。", "b": "《管子》"}], "words": [{"w": "半推半就;牵就;就着", "t": "就便;顺便"}, {"w": "就滑", "t": "随便;方便。"}]}, {"meaning": "登上;开始,启。", "cites": [{"t": "于是荆轲就车而去。", "b": "《史记·刺客列传》"}], "words": [{"w": "就道", "t": "上路"}, {"w": "就涂", "t": "上路,动身。"}]}, {"meaning": "从。", "cites": [{"t": "就其不忘一芋。", "b": "清·周容《芋老人传》"}], "words": [{"w": "就中", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2729wx','敦','1','dūn duì','攵','12','','[{"pinyin": "dūn", "defs": [{"meaning": "(形声。从“攴”,表示与以手持械的动作有关。本义:投掷)。"}, {"meaning": "厚道。诚朴宽厚;厚重;笃实。", "cites": [{"t": "说礼乐而敦诗书。", "b": "《左传·僖公二十七年》"}, {"t": "乞言,从求善言,可以为政者,敦使受之。", "b": "《诗·行苇·序》郑笺"}, {"t": "尽力莫如敦笃。", "b": "《左传·成公十三年》"}, {"t": "敦祗恭厚。", "b": "《韩非子·难言》"}, {"t": "乐者敦和。", "b": "《礼记·乐记》"}, {"t": "乃夫敦乐而无忧。", "b": "《礼记·乐记》"}, {"t": "敦外亲。", "b": "《汉书·鲍宣传》"}], "words": [{"w": "敦雅", "t": "敦厚文雅"}, {"w": "敦固", "t": "敦厚巩固"}, {"w": "敦笃", "t": "敦厚笃实"}, {"w": "敦勉", "t": "敦厚勤勉"}, {"w": "敦至", "t": "笃实周全"}, {"w": "敦善", "t": "敦良,敦厚善良。"}]}, {"meaning": "厚实。", "cites": [{"t": "使虞敦匠。", "b": "《孟子·公孙丑下》。注:“敦匠,厚作棺也。”"}, {"t": "丘一成为敦丘,再成为陶丘。", "b": "《尔雅·释丘》"}], "words": [{"w": "敦实的身材;敦丘", "t": "一层的小山丘"}, {"w": "敦崇", "t": "结实高大"}, {"w": "敦然", "t": "粗厚结实"}, {"w": "敦密", "t": "厚实密致"}, {"w": "敦敦实实", "t": "身体壮实。"}]}, {"meaning": "勤勉,专心且刻苦地完成任务。", "cites": [{"t": "軥录疾力,以敦比其事业,而不敢怠傲。", "b": "《荀子·荣辱》"}], "words": [{"w": "敦习", "t": "敦学。勤勉学习"}, {"w": "敦敦", "t": "孜孜不息"}, {"w": "敦比", "t": "孜孜不息地工作。"}]}, {"meaning": "友谊深厚。", "cites": [{"t": "徒作千里曲,弦绝念弥敦。", "b": "谢灵运《入彭蠡湖口》"}], "words": [{"w": "敦故", "t": "敦旧。亲厚故旧"}, {"w": "敦序", "t": "亲睦和顺"}, {"w": "敦伦", "t": "夫妻间的性生活。"}]}, {"meaning": "丰富,丰厚。", "cites": [{"t": "敦厐纯固于是乎成。", "b": "《国语·周语上》"}, {"t": "民生敦厐。", "b": "《左传·成公十六年》"}], "words": [{"w": "敦物", "t": "丰富的物产"}, {"w": "敦庞", "t": "丰厚富足;同“敦厐”。"}]}, {"meaning": "督促;管理。", "cites": [{"t": "使虞敦匠事。", "b": "《孟子·公孙丑下》"}], "words": [{"w": "敦逼", "t": "催促逼迫"}, {"w": "敦率", "t": "遵守,恪守"}, {"w": "敦比", "t": "治理;办理"}, {"w": "敦世厉俗", "t": "促使世俗风尚纯朴起来。"}]}, {"meaning": "劝导并勉励。", "cites": [{"t": "敦众神使式道兮。", "b": "《汉书·扬雄传》"}], "words": [{"w": "敦晓", "t": "劝勉开导"}, {"w": "敦诱", "t": "劝勉诱导"}, {"w": "敦教", "t": "勉励教诲。"}]}]}, {"pinyin": "duì", "defs": [{"meaning": "古代食器 。青铜制。盖和器身都作半圆球形,各有三足或圈足,上下合成球形,盖可倒置。流行于战国时期。", "cites": [{"t": "有虞氏之两敦。", "b": "《礼记·明堂位》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2730wx','斌','1','bīn','文','12','','[{"pinyin": "bīn", "defs": [{"meaning": "文质兼备的。", "cites": [{"t": "斌，文质貌。亦作彬。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2731wx','痘','1','dòu','疒','12','','[{"pinyin": "dòu", "defs": [{"meaning": "(形声。从疒(chuáng),豆声。本义:病名。俗称天花,也叫痘疮或天疮)。"}, {"meaning": "指痘苗。特指牛痘苗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2732wx','痢','1','lì','疒','12','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,利声。本义:病名。即“痢疾”) 同本义。", "cites": [{"t": "凡山水甚强寒,饮之皆令人痢。", "b": "曹操《魏武令》"}], "words": [{"w": "痢症", "t": "痢疾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2733wx','痪','1','huàn','疒','12','','[{"pinyin": "huàn", "defs": [{"meaning": "瘫痪。", "cites": [{"t": "痪,瘫痪,四体麻痹不仁,皆因风寒暑湿所致。", "b": "《正字通》"}, {"t": "[水萍] 治左瘫右痪。", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2734wx','痛','1','tòng','疒','12','','[{"pinyin": "tòng", "defs": [{"meaning": "(形声。从疒,甬声。疒(chuáng),与疾病有关。本义:疼痛)。"}, {"meaning": "同本义。", "cites": [{"t": "痛,病也。", "b": "《说文》"}, {"t": "坎为耳痛。", "b": "《易·说卦》"}, {"t": "桓侯体痛。", "b": "《韩非子·喻老》"}, {"t": "身体痛。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "病痛恐惧。", "b": ""}, {"t": "身自疾痛。", "b": ""}], "words": [{"w": "痛不欲生;痛定思痛;创巨痛深;累得酸痛;痛毒", "t": "痛苦,残酷"}, {"w": "痛疾", "t": "病痛"}, {"w": "痛脚", "t": "疼痛的脚"}, {"w": "痛煞", "t": "疼痛之甚"}, {"w": "痛痹", "t": "病名。中医指以疼痛剧烈为主症的痹症"}, {"w": "痛痒", "t": "疼痛,发痒。"}]}, {"meaning": "痛恨。", "cites": [{"t": "自痛负汉。", "b": "《汉书·李广苏建传》"}, {"t": "叹息痛恨。", "b": "诸葛亮《出师表》"}], "words": [{"w": "痛入骨髓", "t": "形容痛恨到极点"}, {"w": "深恶痛绝", "t": "极端痛恨、厌恶"}, {"w": "痛绝", "t": "痛恨到极点。"}]}, {"meaning": "痛惜;怜惜;叹惜。", "cites": [{"t": "苦痛之。", "b": "《吕氏春秋·博志》"}, {"t": "哀痛未尽,思慕未忘。", "b": "《荀子·礼论》"}]}, {"meaning": "又如痛惋(谓极其怅恨而惋惜)。"}, {"meaning": "痛爱,怜爱。", "cites": [{"t": "痛玉不痛身,抱璞求所归。", "b": "孟郊《古兴》"}], "words": [{"w": "痛爱", "t": "怜爱;疼爱;关切喜爱"}, {"w": "痛热", "t": "疼爱亲热。"}]}, {"meaning": "痛苦,身体或精神感到非常难受。", "cites": [{"t": "疾痛惨怛。", "b": "《史记·屈原贾生列传》"}, {"t": "痛定思痛。", "b": "宋·文天祥《指南录·后序》"}, {"t": "痛何如哉?", "b": ""}], "words": [{"w": "痛毒", "t": "痛苦之甚"}, {"w": "痛疾", "t": "痛苦"}, {"w": "痛恼", "t": "痛苦烦恼"}, {"w": "痛伤", "t": "痛苦忧伤"}, {"w": "痛挠", "t": "痛苦难受。"}]}, {"meaning": "悲痛;悲伤。", "cites": [{"t": "痛哉斯言。", "b": "清·黄宗羲《原君》"}, {"t": "滋可痛已。", "b": "孙文《黄花冈七十二烈士事略·序》"}, {"t": "既痛逝者。", "b": ""}], "words": [{"w": "痛切", "t": "悲痛哀切"}, {"w": "痛心拔脑,痛心疾首", "t": "形容悲痛到极点"}, {"w": "痛怛", "t": "哀痛悲伤"}, {"w": "痛咽", "t": "悲伤哀泣貌"}, {"w": "痛恻", "t": "悲痛哀伤"}, {"w": "痛惭", "t": "悲痛惭愧"}, {"w": "痛绝", "t": "悲痛到极点"}, {"w": "痛伤", "t": "悲痛伤心。"}]}, {"meaning": "痛快;尽兴。", "cites": [{"t": "登城痛饮。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "痛醉", "t": "尽情地饮酒至醉"}, {"w": "痛肠", "t": "犹衷肠;衷情"}, {"w": "痛谈", "t": "尽情地交谈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2735wx','童','1','tóng','立','12','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。重省声。(qiān),罪。本义:男奴仆)。"}, {"meaning": "同本义。", "cites": [{"t": "得童仆贞。", "b": "《易·旅》"}, {"t": "童子执帚。", "b": "《仪礼·既夕礼记》"}, {"t": "小童持斧。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "童奴", "t": "仆役"}, {"w": "童隶", "t": "犹童仆"}, {"w": "童仆", "t": "家僮和仆人"}, {"w": "童妾", "t": "婢女;小妾。"}]}, {"meaning": "小孩。年幼未成年的人。", "cites": [{"t": "匪我求童蒙。", "b": "《易·蒙卦》"}, {"t": "成童舞象。", "b": "《礼记·内则》"}, {"t": "童寄者。", "b": "唐·柳宗元《童区寄传》"}, {"t": "童微伺其睡。", "b": ""}, {"t": "将杀童。", "b": ""}, {"t": "持童抵主人所。", "b": ""}], "words": [{"w": "童子", "t": "儿童;未成年的男子"}, {"w": "童子科", "t": "科举考试中为儿童、少年设立的科目"}, {"w": "童幼", "t": "童年;儿童"}, {"w": "童角", "t": "一种儿童发式"}, {"w": "童蒙", "t": "指无知的儿童;指童年"}, {"w": "童稚", "t": "儿童;小孩"}, {"w": "童趣", "t": "儿童的情趣。"}]}, {"meaning": "指处女或童男的贞操。", "cites": [{"t": "至期与女俱入房,亲以手去其童。", "b": "元·周达观《真腊风土记》"}]}, {"meaning": "又如童男子(从未接近女色的男子);童真(童贞)。"}, {"meaning": "眼珠", "cites": [{"t": "周生亦有言,舜盖重童子,项羽又重童子,岂其苗裔邪?", "b": "《汉书·陈用项籍传赞》"}], "words": [{"w": "童子", "t": "瞳人;瞳仁;眼珠。"}]}, {"meaning": "牛羊等未生角或无角。", "cites": [{"t": "童牛之告。", "b": "《易·大畜》"}]}, {"meaning": "又如童牛(无角之牛);童羊(无角的公羊)。"}, {"meaning": "山岭,田地无草木。如童土(没有草木的土地);童秃(光秃);童阜(光秃的土山);童枯(光秃枯竭);童童(光秃的样子)。"}, {"meaning": "植物无枝干或无果实。如童木(无枝干的树木);童稂(形似禾苗而不结实的一种野草);童梁(禾生穗而不实者)。"}, {"meaning": "头秃;没有头发。如童首(秃头);童颠(秃顶)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2736wx','竣','1','jùn','立','12','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。本义:退位)。"}, {"meaning": "同本义。", "cites": [{"t": "有司已于事而竣。", "b": "《国语》。韦昭注:“竣,伏退也。”"}]}, {"meaning": "完成,事毕。", "cites": [{"t": "晓夜并工,克期告竣。", "b": "《三国演义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2737wx','阔','1','kuò','门','12','','[{"pinyin": "kuò", "defs": [{"meaning": "(形声。从门,活声。本义:阔大,很开阔)。"}, {"meaning": "同本义。", "cites": [{"t": "阔,疏也。", "b": "《说文》"}, {"t": "阔,稀也。", "b": "《汉书·沟洫志》集注"}, {"t": "阔,远也。", "b": "《尔雅》"}, {"t": "缓步阔视。", "b": "《列子·黄帝》"}, {"t": "于嗟阔兮。", "b": "《诗·邶风·击鼓》"}, {"t": "阔大渊深,不可测也。", "b": "《吕氏春秋·论人》"}, {"t": "湖阔数十里。", "b": "李白《陪从祖济南太守泛鹊山湖》"}, {"t": "广厦阔屋。", "b": "《淮南子·齐俗训》"}, {"t": "暮霭沈沈楚天阔。", "b": "柳永《雨霖铃》"}], "words": [{"w": "阔绝", "t": "隔绝,差别很大"}, {"w": "阔略", "t": "疏略;粗疏"}, {"w": "阔落", "t": "宽疏,不细密"}, {"w": "阔寥", "t": "稀少"}, {"w": "阔疏", "t": "粗疏"}, {"w": "阔希", "t": "稀疏。"}]}, {"meaning": "宽横的距离大。", "cites": [{"t": "有江千里阔。", "b": "白居易《寄微之》"}], "words": [{"w": "阔狭", "t": "广狭,宽窄"}, {"w": "阔叶树;阔达", "t": "旷达不拘小节"}, {"w": "阔涧", "t": "较宽的山间小溪"}, {"w": "阔朗", "t": "宽阔明亮"}, {"w": "阔颡", "t": "宽阔的额部"}, {"w": "阔臆", "t": "宽阔的胸部。"}]}, {"meaning": "迂阔,不切实际。", "cites": [{"t": "王道迂阔而莫为。", "b": "唐·李华《吊古战场文》"}], "words": [{"w": "阔论", "t": " 不切实际的大话"}, {"w": "阔迂", "t": "拘泥而不切实际。"}]}, {"meaning": "侈大,荣显,富有。", "cites": [{"t": "何阴阳之难测,伟二仪之奓阔。", "b": "《晋书·成公绥传》"}], "words": [{"w": "阔老;阔天阔地", "t": "指大手大脚,大肆挥霍"}, {"w": "阔客", "t": "有钱客"}, {"w": "阔拓", "t": "阔绰"}, {"w": "阔少爷", "t": "有钱人家的子弟"}, {"w": "阔人家", "t": "富家。"}]}, {"meaning": "久不相见。", "cites": [{"t": "阔别稍久,眷与时长。", "b": "王羲之《问慰诸帖》"}], "words": [{"w": "阔悰", "t": "阔别的心情"}, {"w": "阔怀", "t": "阔别的情怀"}, {"w": "阔踪", "t": "阔别后的行止情况"}, {"w": "阔情", "t": "久别之情。"}]}, {"meaning": "胸襟开阔,才思敏捷。", "cites": [{"t": "武为人嗜酒,阔达敢言。", "b": "《后汉书·马武传》"}], "words": [{"w": "阔达", "t": "豁达。气量大,性格开朗。"}]}, {"meaning": "离别。", "cites": [{"t": "于嗟阔兮!不我活兮!", "b": "《诗·邶风·击鼓》"}]}, {"meaning": "放宽,宽缓。", "cites": [{"t": "阔其租赋。", "b": "《汉书·王莽传下》"}, {"t": "驰网阔禁。", "b": "《三国志·明帝纪》注"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2738wx','善','1','shàn','口','12','','[{"pinyin": "shàn", "defs": [{"meaning": "(会意,从言,从羊。言是讲话。羊是吉祥的象征。本义:吉祥)。"}, {"meaning": "同本义。", "cites": [{"t": "善,吉也。", "b": "《说文》"}, {"t": "来者以善日邪时,孰与邪日善时?", "b": "《汉书·翼奉传》"}], "words": [{"w": "善时", "t": "吉时"}, {"w": "善祥", "t": "吉祥;吉兆"}, {"w": "善征", "t": "吉兆"}, {"w": "善日", "t": "吉日。"}]}, {"meaning": "好;美好。", "cites": [{"t": "母氏圣善。", "b": "《诗·邶风·凯风》"}, {"t": "善,德之建也。", "b": "《国语·晋语》"}, {"t": "善人国之主也。", "b": "《左传·襄公三十年》"}, {"t": "所以善代者乃万故。", "b": "《吕氏春秋·长攻》。注:“善好也。”"}, {"t": "择其善者而从之,其不善者而改之。", "b": "《论语·述而》"}, {"t": "岂人主之子孙则敢不善哉?", "b": "《战国策·赵策》"}], "words": [{"w": "善风", "t": "良好的风气"}, {"w": "善言", "t": "美言;说好话"}, {"w": "善处", "t": "好办法"}, {"w": "善马", "t": "良马"}, {"w": "善少", "t": "好少年"}, {"w": "善秀", "t": "佳穗。比喻资质甚佳,才品出众。"}]}, {"meaning": "善良;好心。", "cites": [{"t": "供养三德为善。", "b": "《左传·昭公十二年》"}, {"t": "又尽善也。", "b": "《论语·八佾》。皇疏:“善者,理事不恶之名。”"}, {"t": "因厚赂单于,答其善意。", "b": "《汉书·苏武传》"}], "words": [{"w": "善熟", "t": "和善"}, {"w": "善德", "t": "善良,以德待人"}, {"w": "善善", "t": "犹“善罢干休”;顺顺当当"}, {"w": "善觑", "t": "好心看待"}, {"w": "善眉善眼", "t": "面孔和善"}, {"w": "善模善样", "t": "模样和善"}, {"w": "善性", "t": "善良的本性"}, {"w": "善顺", "t": "善良和顺。"}]}, {"meaning": "慈善。", "cites": [{"t": "恐恐然惟惧其人之不得善之利。一善易修也,一艺易能也。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "善事;善举;善友", "t": "佛教教友"}, {"w": "善信", "t": "佛教称虔诚信仰佛教的人"}, {"w": "善胜", "t": "非常善良;慈善信佛"}, {"w": "善根", "t": "佛教用语。指人所以能为善的根性"}, {"w": "善堂", "t": "旧指育婴堂、养老院等慈善机构。"}]}, {"meaning": "表示应诺。对,好。", "cites": [{"t": "王曰:“善!”", "b": "《战国策·齐策》"}, {"t": "先主:“善?”", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "高明,工巧。", "cites": [{"t": "善闭,无关键而不可开;善结,无绳约而不可解。", "b": "《老子》"}, {"t": "吹籁工为善声。", "b": "《论衡·逢遇》"}], "words": [{"w": "善手", "t": "高手,能手"}, {"w": "善工", "t": "高手。"}]}, {"meaning": "熟悉,经常看到或经历,易于辨认。", "cites": [{"t": "识其品式,辨其条理;善其用,定其体,则“默而成之,不言而信”。", "b": "王夫之《周易外传》"}], "words": [{"w": "善便", "t": "善变。不费力,轻易"}, {"w": "善查", "t": "好对付的人。又作“善荐八”。"}]}, {"meaning": "善于,擅长。有做好或处理好某事的才能或技巧。", "cites": [{"t": "善戏谑兮。", "b": "《诗·卫风·淇奥》"}, {"t": "大便辟,友善柔,友便佞,损矣!", "b": "《论语·季氏》"}, {"t": "奕秋,通国之善弈者也。", "b": "《孟子·告子上》"}, {"t": "秦皇帝惜其善击筑。", "b": "《史记·刺客列传》"}, {"t": "杭有卖果者,善藏柑。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "善宽", "t": "善解;善于迎合"}, {"w": "善丹青", "t": "擅长画画"}, {"w": "善时", "t": "善于把握时机"}, {"w": "善柔", "t": "善于阿谀奉承"}, {"w": "善喻", "t": "善于教喻"}, {"w": "善贷", "t": "善于施与"}, {"w": "善渊", "t": "善于保持沉默"}, {"w": "善诱", "t": "善于诱导"}, {"w": "善贾", "t": "长于贸易,善于做生意"}, {"w": "善富", "t": "善于保持富有地位"}, {"w": "善文", "t": "擅长为文"}, {"w": "善化", "t": "擅长教化。"}]}, {"meaning": "修治。", "cites": [{"t": "善刀而藏之。", "b": "《庄子·养生主》"}, {"t": "故有善迩而远至。", "b": "《易·略例》。注:“善,修治也。”"}], "words": [{"w": "善刀", "t": "拭刀而加以收藏。比喻收敛自己的才华。"}]}, {"meaning": "羡慕。", "cites": [{"t": "善万物之得时,感吾生之行休。", "b": "陶渊明《归去来辞》"}]}, {"meaning": "喜爱。", "cites": [{"t": "其所善者,吾则行之;其所恶者,吾则改之。", "b": "《左传》"}]}, {"meaning": "认为好。", "cites": [{"t": "[常]忌信道任数,不从下人,故为权势所不善。", "b": "《华阳国志》"}]}, {"meaning": "赞许。", "cites": [{"t": "使孔子欲表善颜渊。", "b": "王充《论衡》"}], "words": [{"w": "善善", "t": "赞扬人家的优点、美德"}, {"w": "善颂善祷", "t": "赞美能寓规劝于颂祷之中"}, {"w": "善善从长", "t": "本是称道别人的善德渊源流长。后转为赞扬人家向善弃恶、舍短取长。"}]}, {"meaning": "友好,亲善。", "cites": [{"t": "余宗老涂山,左公甥也,与先君子善,谓狱中语乃亲得之于史公云。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "善气迎人", "t": ""}]}, {"meaning": "好人;好事;好处。", "cites": [{"t": "存抚良善。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "赏善不遗匹夫。", "b": "《韩非子·有度》"}]}, {"meaning": "好好地。", "cites": [{"t": "今姑贷汝,后不善自改,且复妄言,我当焚汝庐,戕汝家矣!", "b": "明·高启《书博鸡者事》"}, {"t": "秦王必喜而善见臣。", "b": "《战国策·燕策》"}]}, {"meaning": "多;常;易。", "cites": [{"t": "风从北来者,大率不能甘而善苦。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "善变;善疑;善怀", "t": "多所怀思。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2739wx','翔','1','xiáng','羽','12','','[{"pinyin": "xiáng", "defs": [{"meaning": "(形声。从羽,羊声。本义:翅膀平直不动盘旋地飞)。"}, {"meaning": "同本义。", "cites": [{"t": "翔,回飞也。", "b": "《说文》"}, {"t": "鸢鸟丑其飞也翔。", "b": "《尔雅·释鸟》"}, {"t": "凤以之翔。", "b": "《淮南子·原道》。注:“大飞不动曰翔。”"}, {"t": "虽欲翱翔。", "b": "《淮南子·俶真》。注:“直刺不动曰翔。”"}, {"t": "色斯举矣,翔而后集。", "b": "《论语·乡党》"}, {"t": "翦翎送笼中,使看百鸟翔。", "b": "韩愈《调张籍》"}]}, {"meaning": "悠闲自在地行走。", "cites": [{"t": "柴门何萧条,狐兔翔我宇。", "b": "曹植《梁甫行》"}], "words": [{"w": "翔步", "t": "缓步。比喻可以从缓进行的事"}, {"w": "翔翔", "t": "安舒的样子。"}]}, {"meaning": "飞后停息。", "cites": [{"t": "飞不妄集,翔必择林。", "b": "《鹦鹉赋》"}, {"t": "沙鸥翔集。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "回顾。", "cites": [{"t": "后弱则翔。", "b": "《考工记·矢人》。注:“回顾也。”"}, {"t": "凝听翔立,若有所伺。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "详尽。", "cites": [{"t": "自宣元后,单于称藩臣西域服从,其土地山川王侯户数道里远近翔实矣。", "b": "《汉书·西域传》"}, {"t": "亦治今文学,博洽翔实。", "b": "《近代学风之地理的分布》"}], "words": [{"w": "翔集", "t": "周详无遗地采录收集。"}]}, {"meaning": "吉利。", "cites": [{"t": "丰其屋,天际翔也。", "b": "《易·丰》"}, {"t": "翔风起,甘露降。", "b": "《论衡·是应》"}], "words": [{"w": "翔洽", "t": "上下融洽"}, {"w": "翔风", "t": "祥风。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2740wx','羡','1','xiàn','八','12','','[{"pinyin": "xiàn", "defs": [{"meaning": "(会意。本义:羡慕,因喜爱而希望得到)。"}, {"meaning": "同本义。", "cites": [{"t": "羡,贪欲也。", "b": "《说文》"}, {"t": "羡,贪慕也。", "b": "《广韵》"}, {"t": "慕欲曰羡。", "b": "《字林》"}, {"t": "帝谓文王,无然畔援,无然歆羡。", "b": "《诗·大雅·皇矣》"}, {"t": "临河而羡鱼,不如归家织网。", "b": "《淮南子·说林训》"}], "words": [{"w": "歆羡", "t": "羡慕"}, {"w": "艳羡", "t": "十分羡慕"}, {"w": "称羡", "t": "称赞羡慕"}, {"w": "欣羡", "t": "喜爱而羡慕"}, {"w": "叹羡", "t": "赞叹羡慕。"}]}, {"meaning": "超过,盖过。", "cites": [{"t": "德隆乎三皇,功羡于五帝。", "b": "司马相如《上林赋》"}], "words": [{"w": "羡田", "t": "在已入藉或规定的土地数目之外另占有的田地,是不纳租赋的隐匿田"}, {"w": "羡利", "t": "盈利。"}]}, {"meaning": "富余,足够而多余。", "cites": [{"t": "四方有羡。", "b": "《诗·小雅·十月之交》"}, {"t": "以羡补不足。", "b": "《孟子·滕文公下》"}, {"t": "钧羡不足。", "b": "《管子·国蓄》"}, {"t": "以其余为羡。", "b": "《周礼·小司徒》"}, {"t": "喜乐无羡赏,忿怒无羡刑。", "b": "《晏子春秋》"}, {"t": "浮食奇民,欲擅管山海之货,以致富羡。", "b": "《史记·平准书》"}, {"t": "虽残文羡语,皆不敢忽。", "b": "《元史·许谦传》"}], "words": [{"w": "羡力", "t": "多余的力量"}, {"w": "羡田", "t": "余田,指不纳租税的私垦田地"}, {"w": "羡溢", "t": "富饶丰足。"}]}, {"meaning": "长。", "cites": [{"t": "壁羡以起度。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2741wx','普','1','pǔ','日','12','','[{"pinyin": "pǔ", "defs": [{"meaning": "(会意兼形声。小篆字形,从日,从并。“并”亦可以看作声。“普”是二人并排站着。本义:日无光)。"}, {"meaning": "同本义。", "cites": [{"t": "普,日无色也。", "b": "《说文》。徐锴注:“日无光,则近远皆同。”"}]}, {"meaning": "遍,普遍;全面。", "cites": [{"t": "普天之下。", "b": "《孟子·万章下》"}, {"t": "广矣普矣。", "b": "《文选·宋评论·高唐赋》"}, {"t": "天丽且弥,地普而深。", "b": "《汉书·扬雄传下》"}, {"t": "普施明法。", "b": "《史记·秦始皇本纪》"}, {"t": "普天一统,于是定矣。", "b": "《三国志·吴主传》"}], "words": [{"w": "普席", "t": "全席"}, {"w": "普及本", "t": "即普及版"}, {"w": "普天", "t": "遍天下"}, {"w": "普加", "t": "普遍赐与;普遍施与"}, {"w": "普存", "t": "普遍富足"}, {"w": "普讯", "t": "遍及;普遍"}, {"w": "普施", "t": "普遍施与"}, {"w": "普恩", "t": "普施的恩泽。"}]}, {"meaning": "广大。", "cites": [{"t": "圣人之德,若天之高,若地之普。", "b": "《墨子》"}]}, {"meaning": "吐蕃俗称丈夫(成年男子)为普。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2742wx','粪','1','fèn','米','12','','[{"pinyin": "fèn", "defs": [{"meaning": "(会意。小篆字形,从采(矢)。合起来表示双手持簸箕清除污秽。本义:扫除)。"}, {"meaning": "同本义。", "cites": [{"t": "粪,弃除也。", "b": "《说文》"}, {"t": "堂上不粪,则郊草不芸。", "b": "《荀子·强国》"}], "words": [{"w": "粪除", "t": "扫除"}, {"w": "粪洒", "t": "洒扫。"}]}, {"meaning": "施肥。", "cites": [{"t": "凡粪种。", "b": "《周礼·草人》。注:“凡所以粪种者,皆谓煮取汁也。”"}, {"t": "却是走马以粪。", "b": "《老子》。注:“粪田也。”"}], "words": [{"w": "粪治", "t": "施肥治田"}, {"w": "粪种", "t": "古代的一种耕种方法。"}]}, {"meaning": "屎,粪便。", "cites": [{"t": "一亩之稼,则粪溉者先芽。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "粪清", "t": "粪汁"}, {"w": "粪溷", "t": "粪坑;厕所"}, {"w": "马粪;牛粪;粪棋", "t": "低劣的棋艺。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2743wx','尊','1','zūn','寸','12','','[{"pinyin": "zūn", "defs": [{"meaning": "(会意。甲骨文字形,象双手捧着尊,从酉,从収(gǒng)。小篆从酋,从収。或作寸。本义:酒器)。"}, {"meaning": "同本义。", "cites": [{"t": "尊,酒器也。", "b": "《说文》。字亦作罇。"}, {"t": "辩六尊之名物。", "b": "《周礼·大宗伯》。司农注:“献尊、象尊、著尊、壶尊、大尊、山尊。”"}, {"t": "尊用牺象山罍。", "b": "《礼记·明堂位》"}, {"t": "侧尊。", "b": "《仪礼·士冠礼》"}, {"t": "形似酒尊。", "b": "《后汉书·张衡传》"}, {"t": "皆隐在尊中。", "b": ""}, {"t": "尊则振龙。", "b": ""}, {"t": "一尊还酹江月。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "携尊", "t": "端起酒器"}, {"w": "尊觯", "t": "尊谭。泛指酒器"}, {"w": "尊爵", "t": "泛指礼器或酒器"}, {"w": "尊彝", "t": "尊、彝均为古代酒器"}, {"w": "尊中弩", "t": "酒尊中的弩影。"}]}, {"meaning": "敬重;推崇。", "cites": [{"t": "尊贤而重士。", "b": "汉·贾谊《过秦论》"}, {"t": "尊五美,屏四恶,斯可以从政矣。", "b": "《论语》"}], "words": [{"w": "尊人", "t": "尊敬他人"}, {"w": "尊上", "t": "尊敬长上"}, {"w": "尊明", "t": "尊敬地对待并明示于人"}, {"w": "尊贤", "t": "尊敬贤者"}, {"w": "尊优", "t": "尊敬优待"}, {"w": "尊齿", "t": "敬重年长者。"}]}, {"meaning": "重视。", "cites": [{"t": "牟夷非卿而书,尊地也。", "b": "《左传》"}, {"t": "置诗、书、重攻战,尊首级。", "b": "《新唐书》"}, {"t": "子思言“尊德性”,而归于“道问学,问且先于学也。(《礼记·中庸》:“故君子尊德性而道问学。”意思是君子尊崇高尚的道德品质,然后归结到由勤问好学入手。言:论。德性:高尚的道德品质。道:经由,名词用如动词。且:况且、并且、而且,表递进的连词。先:指先提出来,动词。子思:孔伋,孔子的孙子,传说《中庸》是他作的。)", "b": "清·刘开《问说》"}], "words": [{"w": "尊用", "t": "重用"}, {"w": "尊异", "t": "格外重视。"}]}, {"meaning": "减损。", "cites": [{"t": "子深其深,浅其浅,益其益,尊其尊。", "b": "《墨子》"}]}, {"meaning": "撙。节制;谦抑。", "cites": [{"t": "谦尊而光。", "b": "《易·谦》"}, {"t": "大者不难卑身尊位以下之。", "b": "《韩非子·说疑》"}], "words": [{"w": "尊节", "t": "克制;遵守法度"}, {"w": "尊让", "t": "克制谦让。"}]}, {"meaning": "遵行,遵从。", "cites": [{"t": "尊五美,屏四恶。", "b": "《论语·尧曰》"}, {"t": "行既已尊之。", "b": "《韩诗外传》"}, {"t": "守者必善,而君尊用之,然后可以守也。", "b": "《墨子》"}]}, {"meaning": "置酒,把酒倒入杯、碗、尊中。", "cites": [{"t": "夫奥老妇之祭也,盛于盆,尊于瓶。", "b": "《礼记》"}], "words": [{"w": "尊醮", "t": "酌酒。"}]}, {"meaning": "尊奉。", "cites": [{"t": "见其尊己也。", "b": "唐·韩愈《原毁》"}, {"t": "尊尚勇武。", "b": "宋·苏轼《教战守》"}]}, {"meaning": "尊贵;高贵。", "cites": [{"t": "天子者,执位圣尊。", "b": "《荀子》"}, {"t": "位尊而无功。", "b": "《战国策·赵策》"}, {"t": "媪尊长安君之位。", "b": ""}, {"t": "履至尊。", "b": "汉·贾谊《过秦论》"}, {"t": "非尊于齐楚…", "b": ""}, {"t": "始吾读孟轲书,然后知孔子之道尊。", "b": "唐·韩愈《读》"}, {"t": "德隆望尊。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "尊大", "t": "尊贵伟大;至高至大"}, {"w": "尊安", "t": "尊贵安泰"}, {"w": "尊客", "t": "尊贵的宾客"}, {"w": "尊遂", "t": "尊贵显达"}, {"w": "尊胜", "t": "尊贵;尊严"}, {"w": "尊肃", "t": "尊贵庄严"}, {"w": "尊优", "t": "地位尊贵,生活优裕"}, {"w": "尊爵", "t": "尊贵的爵位。"}]}, {"meaning": "高,高出。", "cites": [{"t": "天尊地卑,乾坤定矣。", "b": "《易·系辞》"}, {"t": "虞庆为屋,谓匠人曰:“屋太尊。”", "b": "《韩非子》"}], "words": [{"w": "尊远", "t": "高远"}, {"w": "尊位", "t": "高位"}, {"w": "尊者", "t": "称辈分或地位高的人"}, {"w": "尊盛", "t": "位高势盛"}, {"w": "尊属", "t": "辈分高的亲属"}, {"w": "尊官", "t": "高官。"}]}, {"meaning": "年龄大。", "cites": [{"t": "间有年尊人不识羞耻,亦复为之。", "b": "吴自牧《梦梁录》"}, {"t": "一族之中,惟李清年齿最尊,推为族长。", "b": "《醒世恒言》"}], "words": [{"w": "尊老", "t": "称年高的长辈"}, {"w": "尊年", "t": "高龄"}, {"w": "尊宿", "t": "年老而有名望的高僧"}, {"w": "尊齿", "t": "高龄。"}]}, {"meaning": "重要;紧要。", "cites": [{"t": "为客治饭而自藜藿,名尊于实也。", "b": "《淮南子》"}], "words": [{"w": "尊要", "t": "重要"}, {"w": "尊秘", "t": "重要而深秘。"}]}, {"meaning": "敬词。"}, {"meaning": "称呼父亲 称别人的父亲。如:尊上,尊大人(称人父母);尊大君(称人父亲);尊甫、尊公(称别人父亲);尊侯(敬称别人父亲);尊堂(敬称他人母亲);令尊  称自己的父亲、母亲。如:尊慈,尊萱(对自己母亲的敬称);家尊。亦以称“伯叔”。"}, {"meaning": "称盛酒器。", "cites": [{"t": "何时一尊酒,重与细论文?", "b": "唐·杜甫《春日怀李白》"}]}, {"meaning": "称塑像。", "cites": [{"t": "龛中各有人像一尊,手中各持种种乐器作吹奏式。", "b": "郭沫若《女神之再生》"}], "words": [{"w": "一尊佛像", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2744wx','奠','1','diàn','大','12','','[{"pinyin": "diàn", "defs": [{"meaning": "(象形。金文字形,上面是“酋”(即“酒”),下面象放东西的基物。本义:设酒食以祭)。"}, {"meaning": "同本义。特指初死时的备供品敬礼。", "cites": [{"t": "奠,置祭也。", "b": "《说文》"}, {"t": "于以奠之。", "b": "《诗·召南·采蘋》"}, {"t": "共其奠牛。", "b": "《周礼·牛人》。注:“丧所荐馈曰奠。”"}, {"t": "舍奠于其庙。", "b": "《礼记·祭统》。注:“非时不而祭曰奠。”"}, {"t": "故既奠。", "b": "《礼记·郊特牲》。注:“谓荐熟时也。”"}, {"t": "有司以几宴舍奠于其墓。", "b": "《礼记·檀弓》"}, {"t": "奠汝又不见汝食。", "b": "清·袁牧《祭妹文》"}], "words": [{"w": "祭奠", "t": "为死者举行仪式,表示追念"}, {"w": "奠馔", "t": "置食物以祭"}, {"w": "奠飨", "t": "置酒食以祭祀。"}]}, {"meaning": "荐献;敬献。", "cites": [{"t": "主人坐,奠爵于阶前。", "b": "《仪礼·乡饮酒》"}], "words": [{"w": "奠献", "t": "献祭品以祀死者"}, {"w": "奠仪", "t": "送给丧家用于祭奠的钱物"}, {"w": "奠雁", "t": "古代婚俗。新郎用雁作见面礼到女家迎亲,表示不再娶他人。"}]}, {"meaning": "定;确定,规定。", "cites": [{"t": "无地奠位。", "b": "扬雄《太玄》"}, {"t": "奠高山大川。", "b": "《书·禹贡》。传:“奠,定也。”"}, {"t": "皆辨其物而奠其禄。", "b": "《周礼·天官·职币》"}], "words": [{"w": "奠位", "t": "定位"}, {"w": "奠居", "t": "定居;安居。"}]}, {"meaning": "祭品。", "cites": [{"t": "使建中远具时羞之奠。", "b": "韩愈《祭十二郎文》"}], "words": [{"w": "奠馈", "t": "祭品"}, {"w": " 奠分", "t": "旧俗治丧,各家分摊送给丧家的奠礼"}, {"w": "奠敬", "t": "奠仪。代作祭品而送给丧家的钱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2745wx','道','1','dào','辶','12','','[{"pinyin": "dào", "defs": [{"meaning": "(形声。从辵(chuò),首声。本义:供行走的道路)。"}, {"meaning": "同本义。", "cites": [{"t": "道,所行道也。", "b": "《说文》"}, {"t": "一达谓之道。", "b": "《尔雅》"}, {"t": "道坦坦。", "b": "《易·履》"}, {"t": "百夫有洫,洫上有途,千夫有浍,浍上有道,万夫有川,川上有路。", "b": "《周礼·地官·遂人》。注:“途容车一轨道容二轨,路容三轨。”"}, {"t": "大道甚夷,而民好径。", "b": "《老子》五十三章"}, {"t": "道听而途说。", "b": "《论语·阳货》"}, {"t": "从此道至吾军,不过二十里耳。", "b": "《史记·项羽本纪》"}, {"t": "道渴而死。", "b": "《山海经·海外北经》"}, {"t": "今天大雨,道不通,度已失期。", "b": "《史记·陈涉世家》"}], "words": [{"w": "大道,问道于盲;要道;人行道;车道;康庄大道;道友", "t": "出门在外对素不相识的同路人的客气称呼"}, {"w": "道店", "t": "设在道路旁的旅店。"}]}, {"meaning": "道德,道义、正义。", "cites": [{"t": "得道多助,失道寡助。", "b": "《孟子·公孙丑下》"}, {"t": "伐无道,诛暴秦。", "b": "《史记·陈涉世家》"}], "words": [{"w": "道光", "t": "道德的光辉"}, {"w": "道术", "t": "道德学术;又指医道、医术。"}]}, {"meaning": "道教的教义。", "cites": [{"t": "豪家少年岂知道,来绕百匝脚不停。", "b": "韩愈《华山女》"}]}, {"meaning": "道教;道士。", "cites": [{"t": "阿兄形似道,而神锋太俊。", "b": "《世说新语·赏誉》"}, {"t": "二郗奉道,二何奉佛;皆以财贿。", "b": "《世说新语·排调》"}], "words": [{"w": "道情", "t": "道士所唱的歌,以警世劝善为内容"}, {"w": "道疏(道家拜天地祈福的文表),道粮(道士的口粮", "t": ""}, {"w": "道行", "t": "僧道修炼的功夫。"}]}, {"meaning": "路程;行程。", "cites": [{"t": "日夜不处,倍道兼程。", "b": "《孙子·军争》"}], "words": [{"w": "远道,近道;道里睽隔", "t": "两地离得很远。"}]}, {"meaning": "方式,方法;技能。", "cites": [{"t": "为开其资财之道也。", "b": "晁错《论贵粟疏》"}, {"t": "深谋远虑,行军用兵之道,非及向时之士也。", "b": "贾谊《过秦论》"}, {"t": "策之不以其道。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "生财之道;养生之道;道艺", "t": "道业。谋生手段;职业;工作。"}]}, {"meaning": "地域的区划名 。汉制,县有蛮夷的称“道”。后泛指一般行政区域。明清时指在省府之间设置的监察区。如“凤庐道”。"}, {"meaning": "学术 或宗教教义。", "cites": [{"t": "悦周公、仲尼之道。", "b": "《孟子·滕文公上》"}, {"t": "然墨之道,兼爱为本,吾终当有以活汝。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "传道;道书", "t": "宣传宗教教义的著述文章。"}]}, {"meaning": "指宇宙的本体及其规律。", "cites": [{"t": "脩道而贰,则天不能祸。", "b": "《荀子·天论》"}, {"t": "闻道百,以为莫己若者,我之谓也。", "b": "《庄子·秋水》"}, {"t": "师者,所以传道受业解惑也。", "b": "唐·韩愈《师说》"}, {"t": "臣之所好者,道也;进乎技矣。", "b": "《庄子·养生主》"}]}, {"meaning": "方向;志向。", "cites": [{"t": "不得通其道,故述往事,思来者。", "b": "司马迁《报任安书》"}], "words": [{"w": "志同道合", "t": ""}]}, {"meaning": "说,讲。", "cites": [{"t": "万户侯岂足道哉!", "b": "《史记·李将军列传》"}, {"t": "不足为外人道也。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "常言道;能说会道;一语道破;道定", "t": "说定,说准"}, {"w": "道话", "t": "谈话,说话"}, {"w": "道达", "t": "说清楚,讲明白;表达,传达"}, {"w": "道知", "t": "告知,说明"}, {"w": "道丧", "t": "报丧。"}]}, {"meaning": "取道,经过。", "cites": [{"t": "从郦山下,道芷阳间行。", "b": "《史记·项羽本纪》"}, {"t": "道海安、如皋,凡三百里。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "道经", "t": "路过。"}]}, {"meaning": "引导,疏导。", "cites": [{"t": "知周乎万物而道济天下。", "b": "《易·系辞上》"}, {"t": "道之以政,齐之以刑,民免而无耻。", "b": "《论语·为政》"}, {"t": "道民之门,在上之所先。", "b": "《管子·牧民》"}, {"t": "乃学辟谷,道引轻身。", "b": "《史记·留侯世家》"}]}, {"meaning": "料;想,以为。", "cites": [{"t": "刘太公惊呆了,只道这早晚正说因缘,劝那大王,却听的里面叫救人。", "b": "《水浒传》"}]}, {"meaning": "从,由。", "cites": [{"t": "诸使者道长安来。", "b": "《汉书·淮南传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2746wx','遂','1','suí suì','辶','12','','[{"pinyin": "suí", "defs": [{"meaning": "—如“半身不遂”（bànshēn-bùsuí）(身体一侧发生瘫痪)。"}]}, {"pinyin": "suì", "defs": [{"meaning": "(形声。从辵(chuò))。"}, {"meaning": "同本义。", "cites": [{"t": "遂,亡也。", "b": "《说文》"}]}, {"meaning": "行,往。", "cites": [{"t": "遂,往也。", "b": "《广雅·释诂一》"}, {"t": "不能遂。", "b": "《易·大壮》"}, {"t": "遂贤良。", "b": "《礼记·月令》"}], "words": [{"w": "遂行", "t": "通行;顺适地进行。"}]}, {"meaning": "称心如意;使得到满足。", "cites": [{"t": "他年如遂隐,五老是知音。", "b": "唐·李中碧《庐山》"}, {"t": "王吉曰:长卿久宦游不遂,而来过我。", "b": "《史记·司马相如列传》"}], "words": [{"w": "遂怀", "t": "遂愿"}, {"w": "遂隐", "t": "满足隐遁的愿望"}, {"w": "遂初", "t": "旧时辞去官职,实现隐退的本愿。"}]}, {"meaning": "顺利地完成;成功。", "cites": [{"t": "上无乏用,百事乃遂。", "b": "《礼记·月令》"}, {"t": "四者无一遂。", "b": "汉·司马迁《报任安书》"}, {"t": "令遂前功。", "b": "《后汉书·班超传》"}, {"t": "介子推之从晋公子,既反国而隐焉,又范君之所有志而不遂者也。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "遂初", "t": "辞官归隐,达到原来的愿望"}, {"w": "遂过", "t": "促成过失"}, {"w": "遂志", "t": "实现志愿;满足愿望"}, {"w": "遂事", "t": "成就事业;完成某事"}, {"w": "遂功", "t": "成功。建立功业。"}]}, {"meaning": "通达。", "cites": [{"t": "此其垦田,足以食其民;都邑遂路,足以处其民。", "b": "《商君书·箅地》"}], "words": [{"w": "遂达", "t": "通达。"}]}, {"meaning": "生长。", "cites": [{"t": "禾稼春生,人必加功焉,故五谷得遂长。", "b": "《淮南子·修务》"}], "words": [{"w": "遂长", "t": "生长;成长"}, {"w": "遂字", "t": "生长,成长。"}]}, {"meaning": "决断。", "cites": [{"t": "春秋之义亡遂事,汉家之法有矫制。", "b": "《汉书·冯奉世传》"}], "words": [{"w": "遂事", "t": "决断事情"}, {"w": "遂疑", "t": "决疑。"}]}, {"meaning": "坠落,往下沉", "cites": [{"t": "震遂泥。", "b": "《易·震》"}, {"t": "其贼人多,故天祸之,使遂失其国家。", "b": "《墨子·法仪》"}, {"t": "人有此三行,虽有大过,天其不遂乎。", "b": "《荀子·修身》"}, {"t": "若是,则大事殆乎弛,小事殆乎遂。", "b": "《荀子·王制》"}]}, {"meaning": "又如:遂失(坠失;废弛);遂亡(坠亡;废弛)。"}, {"meaning": "道路。", "cites": [{"t": "使开阶立遂。", "b": "《春秋演孔圆》。宋均注:“道也。”"}, {"t": "禽夫差于干遂。", "b": "《史记·苏秦传》。索隐:“遂者,道也。”"}], "words": [{"w": "遂路", "t": "道路。"}]}, {"meaning": "射者穿的臂衣。", "cites": [{"t": "袒决遂。", "b": "《仪礼》"}]}, {"meaning": "田间排水的小沟。", "cites": [{"t": "凡诒野,夫间有遂,遂上有径。", "b": "《周礼·地官·遂人》"}]}, {"meaning": "《注》:“遂,广深二尺”。又,遂人,周代官名,地官之属。"}, {"meaning": "水道。", "cites": [{"t": "迷者不问路,溺者不问遂(可以涉水而过的路);亡人好独。", "b": "《荀子·大略》"}]}, {"meaning": "就;于是 。多用于书面语。", "cites": [{"t": "赵王于是遂遣相如奉璧西入秦。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "齐侯游于姑棼,遂田于贝丘。", "b": "《左传·庄公八年》"}, {"t": "如不能守以终表,则遂取以来。", "b": "唐·韩愈《祭十二郎文》"}, {"t": "不幸吕师孟构恶于前,贾于庆献谄于后,予羁縻不得还,国事遂不可收拾。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "遂尔", "t": "于是;就"}, {"w": "遂乃", "t": "于是,就"}, {"w": "伤者经过包扎抢救,流血遂止;因天气恶劣,郊游计划遂告落空", "t": ""}]}, {"meaning": "竟然。", "cites": [{"t": "若遂不改,方思仆言。", "b": "南朝梁·丘迟《与陈伯之书》"}]}, {"meaning": "表示最后的结果,终于,到底。", "cites": [{"t": "曹操比于袁绍,则名微而众寡,然操遂能克绍,以弱为强者,非惟天时,抑亦人谋也。", "b": "《三国志·诸葛亮传》"}, {"t": "历险数次,遂达峰顶。", "b": "《徐霞客游记·游黄山记》"}, {"t": "寻向所志,遂迷,不复得路。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "顺利的。", "cites": [{"t": "可遂破也。", "b": "《资治通鉴》"}, {"t": "小儿辈遂已破贼。", "b": ""}]}, {"meaning": "已成,终了。", "cites": [{"t": "成事不说,遂事不谏,既往不咎。", "b": "《论语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2747wx','曾','1','céng zēng','曰','12','','[{"pinyin": "céng", "defs": [{"meaning": "(形声。从八,从曰。本义未明。副词。用来加强语气)。"}, {"meaning": "过去发生过——表示有过某些行为或情况。", "cites": [{"t": "江南好,风景旧曾谙。", "b": "唐·白居易《忆江南》"}, {"t": "斜阳草树,寻常巷陌,人道寄奴曾住。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}], "words": [{"w": "曾不", "t": "不曾"}, {"w": "几年前我曾见过他一面;我曾去过杜坪乡", "t": ""}]}, {"meaning": "竟,竟然;尚。", "cites": [{"t": "以残年余力,曾不能毁山之一毛,其如土石何?", "b": "《列子·汤问》"}]}, {"meaning": "重叠。", "cites": [{"t": "有虞之王,烧曾薮,斩群害,以为民利。", "b": "《管子·轻重戊》"}, {"t": "大厦曾架,拟于昆仑。", "b": "《淮南子·本经》"}, {"t": "荡胸生曾云。", "b": "杜甫《望岳》"}]}]}, {"pinyin": "zēng", "defs": [{"meaning": "重。指中间隔两代的亲属关系。", "cites": [{"t": "自此而曾焉。", "b": "清·洪亮吉《治平篇》"}, {"t": "曾元时不分。", "b": ""}, {"t": "计高曾之时。", "b": ""}, {"t": "视高曾之时。", "b": ""}, {"t": "高曾时为一户者。", "b": ""}], "words": [{"w": "曾翁", "t": "称他人的曾祖父"}, {"w": "曾玄", "t": "曾孙和玄孙。"}]}, {"meaning": "谦词。犹“末”。", "cites": [{"t": "曾臣彪将率诸侯以讨焉。", "b": "《左传》"}], "words": [{"w": "曾臣", "t": "末臣。"}]}, {"meaning": "高举的样子。", "cites": [{"t": "[凤皇]曾逝万仞之上。", "b": "刘安《淮南子·览冥》"}]}, {"meaning": "“增”的本字。增加。", "cites": [{"t": "所以动心忍性,曾益其所不能。", "b": "《孟子·告下子》"}, {"t": "曾欷歔余郁邑兮。", "b": "《楚辞·离骚》"}], "words": [{"w": "曾思", "t": "反复思考"}, {"w": "曾折", "t": "曾挠。屈曲貌"}, {"w": "曾益", "t": "增加,增强"}, {"w": "曾巢", "t": "在高物上架巢"}, {"w": "曾逝", "t": "高飞远去。"}]}, {"meaning": "乃,竟。", "cites": [{"t": "曾不若孀妻弱子。", "b": "《列子·汤问》"}, {"t": "曾不能疾走。", "b": "《战国策·赵策》"}, {"t": "曾不惨然。", "b": "清·黄宗羲《原君》"}, {"t": "长曾不盈寸。", "b": "明·魏学《核舟记》"}]}, {"meaning": "表示相承,相当于“则”、“是”、“就”。", "cites": [{"t": "我曾无闾里之闻,穷巷之知者何?", "b": "《淮南子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2748wx','焰','1','yàn','火','12','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从火,臽(xiàn)声。本义:火苗)。"}, {"meaning": "同本义。", "cites": [{"t": "烟焰迷漫 。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "烟焰雾雨。", "b": "清·邵长蘅《青门剩稿》。又如:内焰(火焰的中间部分);外焰(火焰最外层);焰段(见“艳段”);焰烘烘(焰腾腾。火焰旺盛的样子;引申为情绪激昂);焰头上(喻指兴旺发达);焰焰(火苗起初的样子)"}]}, {"meaning": "火光;辉光。", "cites": [{"t": "凿石有余焰,年命已凋颓矣。", "b": "晋·葛洪《抱朴子》"}], "words": [{"w": "焰红", "t": "火红"}, {"w": "焰光", "t": "光焰;光华"}, {"w": "焰然", "t": "鲜明貌。"}]}, {"meaning": "光亮。", "cites": [{"t": "雨昏陋巷灯无焰,风过贫家壁有声。", "b": "袁枚《随园诗话》"}]}, {"meaning": "燃烧。", "cites": [{"t": "俯而观之,其光自土而出,若焰薪火。", "b": "唐·张读《宣室志》"}], "words": [{"w": "焰蜡", "t": "正在燃烧的蜡烛"}, {"w": "焰灰", "t": "物体燃烧后的余烬"}, {"w": "焰腾腾", "t": "火势猛烈貌。"}]}, {"meaning": "照耀。", "cites": [{"t": "动鳞甲于鲸鱼,焰光芒于鸣鹤。", "b": "北周·庾信《灯赋》"}, {"t": "野燎焰天。", "b": "清·魏源《圣武记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2749wx','港','1','gǎng','氵','12','','[{"pinyin": "gǎng", "defs": [{"meaning": "(形声。从水,巷声。本义:江河的分流)。"}, {"meaning": "同本义 。今多用于河流名。", "cites": [{"t": "道于杨墨老庄佛之学,而欲之圣人之道,犹航断港绝潢,以望至于海也。", "b": "唐·韩愈《送王秀才序》"}], "words": [{"w": "港鱼", "t": "港养的鱼产"}, {"w": "港养", "t": "养殖海产生物的一种方式"}, {"w": "港渎", "t": "河渠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2750wx','滞','1','zhì','氵','12','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从水,带声。本义:水流不畅)。"}, {"meaning": "同本义。", "cites": [{"t": "滞,凝也。", "b": "《说文》"}, {"t": "凡珍异之有滞者。", "b": "《周礼·廛人》"}, {"t": "淹回水而凝滞。", "b": "《楚辞·涉江》"}, {"t": "流而不滞。", "b": "《淮南子·时则训》"}]}, {"meaning": "积压。长期积存,未作处理。", "cites": [{"t": "敛市之不售,货之滞于民用者。", "b": "《周礼·泉府》"}, {"t": "尚书省滞讼不决者,诏征平治。", "b": "《新唐书》"}], "words": [{"w": "滞狱", "t": "指因积压或拖延未予审决的案件"}, {"w": "滞讼", "t": "积压的讼案"}, {"w": "滞积", "t": "积压"}, {"w": "滞货", "t": "积压的货物。"}]}, {"meaning": "停止;阻塞;静止。", "cites": [{"t": "是故能天运地滞,轮转而无废。", "b": "《淮南子·原道训》"}], "words": [{"w": "滞用", "t": "停止运用"}, {"w": "滞淹", "t": "闭塞,不通畅"}, {"w": "滞越", "t": "阻塞"}, {"w": "滞著", "t": "阻塞;不能宣泄。"}]}, {"meaning": "郁积。", "cites": [{"t": "气不沈滞。", "b": "《国语·周语》。注:“积也。”"}, {"t": "得此佳作,终日喜快,滞闷冰释。", "b": "宋·苏轼《与王定国书》"}], "words": [{"w": "滞念", "t": "凝结在心中的思念"}, {"w": "滞思,滞想", "t": "凝聚心头的想念"}, {"w": "滞怒", "t": "积于心中的愤怒"}, {"w": "滞气", "t": "郁积之气"}, {"w": "滞愤", "t": "积愤。"}]}, {"meaning": "凝聚,积聚。", "cites": [{"t": "戚戚多滞念,置酒宴所欢。", "b": "晋·陆机《拟青青陵上柏》"}], "words": [{"w": "滞念", "t": "心中凝结的思念"}, {"w": "滞血", "t": "淤积的血液"}, {"w": "滞底", "t": "凝集。"}]}, {"meaning": "陷入;沉抑。", "cites": [{"t": "卿方当富贵,必不容久滞屈。", "b": "《南史》"}], "words": [{"w": "滞羽", "t": "喻陷于困境不能施展才能的人"}, {"w": "滞抑", "t": "受压制"}, {"w": "滞屈", "t": "贤人沉抑,不得升进"}, {"w": "滞淹", "t": "人沉抑于下而不得升进。"}]}, {"meaning": "暂时停留于某处;逗留。", "cites": [{"t": "几宵因月滞三湘。", "b": "姚鹄《送黄颇归袁》"}], "words": [{"w": "滞淫", "t": "长期旷废;长久停留;久雨不停"}, {"w": "滞游", "t": "久游未归"}, {"w": "滞客", "t": "久处下位而未得升迁的人。"}]}, {"meaning": "遗落;遗漏。", "cites": [{"t": "此有滞穗。", "b": "《诗·小雅·大田》"}], "words": [{"w": "滞器", "t": "遗漏未用的人才。"}]}, {"meaning": "久,长期。", "cites": [{"t": "敢告滞积以纾执事。", "b": "《国语·鲁语》。注:“久也。”"}, {"t": "且眩瞀滞疾,不堪久待。", "b": "《后汉书·韦彪传》"}], "words": [{"w": "滞病", "t": "久病"}, {"w": "滞疾", "t": "久病"}, {"w": "滞役", "t": "长期供职"}, {"w": "滞耻", "t": "久未洗雪的耻辱。"}]}, {"meaning": "反应迟钝;缺乏活力、生气或成效。", "cites": [{"t": "卿年少壮,而心力多滞。", "b": "《金史·宗尹传》"}], "words": [{"w": "滞碾人", "t": "言语、行为愚笨的人"}, {"w": "滞夯", "t": "不灵便"}, {"w": "滞拙", "t": "迟钝笨拙"}, {"w": "滞色", "t": "面带晦气"}, {"w": "滞晦", "t": "呆滞而暗淡。"}]}, {"meaning": "固执;拘泥。", "cites": [{"t": "故良知不滞于见闻,而亦不离于见闻。", "b": "明·吕坤《别尔赡书》"}], "words": [{"w": "滞固", "t": "固执而不变通"}, {"w": "滞执", "t": "固执;不通达"}, {"w": "滞隅", "t": "谓偏执一端"}, {"w": "滞痼", "t": "拘执"}, {"w": "滞疑", "t": "拘泥和疑虑。"}]}, {"meaning": "深奥;不易通晓。", "cites": [{"t": "弘正特善玄言,兼明释典,虽硕德名僧,莫不请质疑滞。", "b": "《南史》"}], "words": [{"w": "滞例", "t": "难解的条例"}, {"w": "滞说", "t": "难理解的说法"}, {"w": "滞义", "t": "疑难的意义。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2751wx','湖','1','hú','氵','12','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从水,胡声。本义:陆地上聚积的大水体)。"}, {"meaning": "湖泊,积水的大泊。", "cites": [{"t": "湖,大陂也。", "b": "《说文》"}, {"t": "扬州浸有五湖。浸,川泽所仰以灌溉也。", "b": "《周礼·职方》。按:古言鸿隙大陂,言汪汪千顷陂,皆谓大池也。凡大泽蓄水,南方名曰湖。”"}, {"t": "江海陂湖园池。", "b": "《汉书·元帝纪》。注:“深水也。”"}, {"t": "战于五湖。", "b": "《国语·越语》"}], "words": [{"w": "湖池", "t": "湖泊池沼"}, {"w": "湖胶", "t": "湖水结冰"}, {"w": "湖埭", "t": "湖的堤坝"}, {"w": "湖海", "t": "湖与海的合称;泛指天下之地。"}]}, {"meaning": "古县名 。在今河南省灵宝县西。"}, {"meaning": "古水名 。在河南省灵宝县西南,发源于夸父山,北流入黄河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2752wx','湘','1','xiāng','氵','12','','[{"pinyin": "xiāng", "defs": [{"meaning": "(形声。从水,相声。本义:湘江)。"}, {"meaning": "同本义。", "cites": [{"t": "湘,湘水也。出零陵阳海山北入江。", "b": "《说文》。朱骏声曰:“出今广西桂林府兴安县海阳山,与漓水同源,经湖南长沙府湘阴县至磊石山八为二派,又合入洞庭湖曰湘口,许云入江未详。”"}, {"t": "沈玉躬兮湘汨。", "b": "《楚辞·涉江》"}, {"t": "宁赴湘流,葬于江鱼之腹中。", "b": "《楚辞·渔父》"}], "words": [{"w": "湘灵", "t": "湘水之神"}, {"w": "湘帘", "t": "用湘妃竹做的帘子"}, {"w": "湘累", "t": "指屈原"}, {"w": "湘妃之泪", "t": "形容悲愤的泪水"}, {"w": "湘娥", "t": "指舜妃娥皇女英"}, {"w": "湘江旧迹", "t": "指湘妃哭舜的传说。"}]}, {"meaning": "湘山。"}, {"meaning": "即君山。在湖南省岳阳市西南洞庭湖中。"}, {"meaning": "即黄陵山。在湖南省湘潭市北。"}, {"meaning": "烹煮。", "cites": [{"t": "于以湘之,维锜及釜。", "b": "《诗·召南·采蘋》"}], "words": [{"w": "湘鱼", "t": "烹鱼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2753wx','渣','1','zhā','氵','12','','[{"pinyin": "zhā", "defs": [{"meaning": "(形声。从水,查声。本义:渣滓,物质经提炼或使用后的残余部分)。"}, {"meaning": "同本义。", "cites": [{"t": "今人谓糟滓为苴作,侧加反,俗字作渣,乃沮之形变也。", "b": "章炳麟《新方言》"}], "words": [{"w": "渣柜", "t": "方言。垃圾箱"}, {"w": "油渣儿;豆腐渣;沉渣;废渣;炉渣;钢渣;麻渣;煤渣;蔗渣", "t": ""}]}, {"meaning": "碎屑。", "cites": [{"t": "若木于是乎倒覆,折扶桑而为渣。", "b": "《南齐书》"}], "words": [{"w": "渣子", "t": "碎屑"}, {"w": "渣渣", "t": "碎片;碎屑"}, {"w": "面包渣儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2754wx','渤','1','bó','氵','12','','[{"pinyin": "bó", "defs": [{"meaning": "水涌的样子。", "cites": [{"t": "鲸归穴兮渤溢,鳌载山兮低昂。", "b": "元稹《有酒》"}], "words": [{"w": "渤溢", "t": "水涌起的样子"}, {"w": "渤荡", "t": "涨潮。"}]}, {"meaning": "古州名 。辽置。约在今长春市附近。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2755wx','渺','1','miǎo','氵','12','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从水,眇(miǎo)声。本义:水面辽阔)。"}, {"meaning": "同本义。", "cites": [{"t": "四际渺弥。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "浩渺", "t": "形容水面辽阔"}, {"w": "渺冥", "t": "渺远"}, {"w": "渺弥", "t": "水流旷远的样子"}, {"w": "渺漭", "t": "水势辽阔的样子"}, {"w": "渺绵", "t": "水流不断的样子。"}]}, {"meaning": "遥远;邈远;渺茫。", "cites": [{"t": "渺渺兮余怀,望美人兮天一方。", "b": "苏轼《前赤壁赋》"}], "words": [{"w": "渺茫", "t": "辽阔的样子;模糊不清;虚妄无凭;难以预期;没有把握;空虚"}, {"w": "渺莽", "t": "烟波辽阔无际的样子"}, {"w": "渺无人烟", "t": "一片渺茫,没有人家"}, {"w": "渺漠", "t": "广漠无际。"}]}, {"meaning": "微小;藐小。", "cites": [{"t": "寄蜉蝣于天地,渺沧海之一粟。", "b": "苏轼《前赤壁赋》"}]}, {"meaning": "又如渺无影响(没有一点儿踪影);渺小(藐小;微小);渺不足道(非常微小,不值得一谈)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2756wx','湿','1','shī','氵','12','','[{"pinyin": "shī", "defs": [{"meaning": "(会意兼指事。从水,顯(xiǎn或jìn)声。本义:潮湿)。"}, {"meaning": "同本义。", "cites": [{"t": "溼,幽溼也。从水,一所以覆也。覆土而有水,故溼也。", "b": "《说文》"}, {"t": "肾其畏溼。", "b": "《素问·五常正大论》。注:“溼,土气也。”"}, {"t": "必因角干之溼以为之柔。", "b": "《考工记·弓人》。注:“溼,犹生也。字多以濕为之。”"}, {"t": "濕,濕水,也东郡东武阳入海。从水,濕声。桑钦云,出平原高唐。", "b": "《说文》。按,本指水名,假借为濕。"}, {"t": "是犹恶湿而居下也。", "b": "《孟子·公孙丑上》"}, {"t": "住近湓江地低湿,黄芦苦竹绕宅生。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "新鬼烦冤旧鬼哭,天阴雨湿声啾啾。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "湿洳", "t": "低湿"}, {"w": "湿渍渍", "t": "湿漉漉"}, {"w": "湿风", "t": "湿润的风"}, {"w": "湿薪", "t": "潮湿的柴薪"}, {"w": "湿浸浸", "t": "湿答答。形容潮湿的样子或给人以潮湿的感觉"}, {"w": "湿渌渌", "t": "潮湿的样子。"}]}, {"meaning": "迟缓;不通畅。", "cites": [{"t": "天寒则腠理闭;气湿不行,水下留于膀胱,则为溺与气。", "b": "《灵枢·五癃津液别》"}, {"t": "力贵突,智贵卒。得之则儵为上,胜之则湿为下。", "b": "《吕氏春秋》。高诱注:“湿犹迟久之也。”"}]}, {"meaning": "沾湿,淋湿。", "cites": [{"t": "散入珠帘湿罗幕,孤裘不暖锦衾薄。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "有书生避雨檐下,衣湿袖单,影乃益瘦。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2757wx','温','1','wēn','氵','12','','[{"pinyin": "wēn", "defs": [{"meaning": "(形声。从水,昷声。本义:水名)。"}, {"meaning": "古水名。"}, {"meaning": "即今贵州省遵义市东的洪江。"}, {"meaning": "即今南盘江上游。"}, {"meaning": "温江,岷江支流,在今四川省温江县。"}, {"meaning": "古州名 。唐置,治所在今浙江省温州市,辖今永嘉、乐清、瑞安、平阳、文成、泰顺等县地。", "cites": [{"t": "上无元年,始置温州…。", "b": "《读史方舆纪要》"}]}, {"meaning": "温暖,暖和。", "cites": [{"t": "阴气温,故温气应之。", "b": "《论衡·寒温》"}, {"t": "衣皮带茭,冬则不轻而温,夏则不轻而清。", "b": "《墨子·辞过》"}, {"t": "温风始至。", "b": "《礼记·月令·季夏》"}, {"t": "覆温之躯。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "四支犹温。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "温清", "t": "冬温夏清"}, {"w": "温谷", "t": "温暖的山谷"}, {"w": "温房", "t": "温暖的房屋"}, {"w": "温奥", "t": "温湿和暖"}, {"w": "温煦", "t": "和暖"}, {"w": "温庐", "t": "温馨和暖的房舍"}, {"w": "温暾", "t": "煖而不热"}, {"w": "温郁", "t": "温暖。"}]}, {"meaning": "温和,温厚;和气。", "cites": [{"t": "终温且惠,淑慎其身。", "b": "《诗·邶风·燕燕》"}], "words": [{"w": "温克", "t": "温和恭敬并有克制力"}, {"w": "温念", "t": "亲切的思念"}, {"w": "温仁", "t": "温和仁爱"}, {"w": "温言", "t": "温和的言辞"}, {"w": "温好", "t": "柔和优美"}, {"w": "温实", "t": "温厚诚实"}, {"w": "温愿", "t": "温厚恭谨"}, {"w": "温诚", "t": "温厚诚朴"}, {"w": "温富", "t": "温厚富足"}, {"w": "温敏", "t": "温厚聪敏"}, {"w": "温顾", "t": "温存"}, {"w": "温柔乡", "t": "喻美色迷人之境"}, {"w": "温栗", "t": "温和而严谨。"}]}, {"meaning": "富足。", "cites": [{"t": "其温厚矣。", "b": "《荀子·荣辱》。注:“足也。”"}, {"t": "居皆温厚。", "b": "《汉书·张敝传》"}], "words": [{"w": "温厚", "t": "富足"}, {"w": "温户", "t": "富裕人家。"}]}, {"meaning": "复习。", "cites": [{"t": "温故而知新。", "b": "《礼记·中庸》"}, {"t": "温《缁衣》一章。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "温故知新;温故", "t": "复习学过的知识"}, {"w": "温旧稿", "t": "比喻操旧业;干老营生"}, {"w": "温课", "t": ""}]}, {"meaning": "蕴藏,蕴积。", "cites": [{"t": "饮酒温克。", "b": "《诗·小雅·小宛》。《笺》云:虽醉犹能温藉自持以胜。"}, {"t": "柔色以温之。", "b": "《礼记·内则》。郑玄注:温藉也。"}, {"t": "视其温辞,可以知其塞怨。", "b": "《春秋繁露·楚庄王》"}, {"t": "治敢往,少温藉。", "b": "《汉书·酷吏义纵传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2758wx','渴','1','kě','氵','12','','[{"pinyin": "kě", "defs": [{"meaning": "(形声。从水,曷声。本义:水干 )。"}, {"meaning": "口渴。", "cites": [{"t": "渴,饥渴。", "b": "《广韵》"}, {"t": "苟无饥渴。", "b": "《诗·王风·言子于役》"}, {"t": "载饥载渴。", "b": "《诗·小雅·采薇》"}, {"t": "日高人渴漫思茶。", "b": "宋·苏轼《浣溪沙》"}], "words": [{"w": "好渴;当你渴的时候到罐子那里去喝水", "t": ""}]}, {"meaning": "比喻迫切。", "cites": [{"t": "饥渴而顿踣。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "思贤如渴。", "b": "《三国志·诸葛亮传》"}, {"t": "除烦渴之疾。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "渴仰", "t": "非常仰慕"}, {"w": "渴懑", "t": "非常抑郁"}, {"w": "渴见", "t": "急望见到"}, {"w": "渴贤", "t": "迫切地慕求贤才。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2759wx','溃','1','kuì','氵','12','','[{"pinyin": "kuì", "defs": [{"meaning": "(形声。从水,贵声。本义:水冲破堤岸)。"}, {"meaning": "同本义。", "cites": [{"t": "溃,决也。", "b": "《说文系传》"}, {"t": "溃,漏也。", "b": "《说文》"}, {"t": "溃,旁决也。", "b": "《苍颉篇》"}, {"t": "不遵其道曰洚,亦曰溃。", "b": "《水经注·河水》注"}, {"t": "沸溃渝溢。", "b": "木华《海赋》。注:乱流貌。”"}, {"t": "溃淡淡而并入。", "b": "宋玉《高唐赋》。注:“水相交过也。”"}, {"t": "渟涔障溃。", "b": "《文选·长笛赋》"}, {"t": "千丈之堤,以蝼蚁之穴溃。", "b": "《韩非子·喻老》"}, {"t": "川壅而溃,伤人必多。", "b": "《国语·周语上》"}, {"t": "溃渭洞河。", "b": "班固《西都赋》"}], "words": [{"w": "溃围", "t": "突围"}, {"w": "溃冒", "t": "冲决泛滥"}, {"w": "溃溢", "t": "堤防崩溃,洪水泛滥"}, {"w": "溃滥", "t": "溃决泛滥"}, {"w": "溃渱", "t": "水流广大的样子"}, {"w": "溃溃", "t": "水流的样子"}, {"w": "溃流", "t": "谓水喷涌而出"}, {"w": "溃濩", "t": "波浪相激汹涌的样子。"}]}, {"meaning": "引申为冲破。", "cites": [{"t": "孝文时,河决酸枣,东溃金堤。", "b": "《史记·河渠书》"}, {"t": "直夜溃围南出,驰走。(直夜:当夜。)", "b": "《史记·项羽本纪》"}]}, {"meaning": "战败;大败。", "cites": [{"t": "兑则若莫邪之利锋,当之者溃。", "b": "《荀子·议兵》"}, {"t": "而民不至于惊溃。", "b": "宋·苏轼《教战守》"}, {"t": "夹攻潼关,官军大溃。", "b": "《旧唐书·黄巢传》"}], "words": [{"w": "溃窜", "t": "四处逃散"}, {"w": "溃亡", "t": "失败逃散"}, {"w": "溃走", "t": "败逃"}, {"w": "溃奔", "t": "败逃"}, {"w": "溃却", "t": "失败而退却。"}]}, {"meaning": "毁坏。", "cites": [{"t": "燔溃其祖庙。", "b": "《墨子·非攻》"}], "words": [{"w": "溃裂", "t": "崩溃"}, {"w": "溃遁", "t": "崩溃遁逃"}, {"w": "溃坠", "t": "崩溃。"}]}, {"meaning": "腐烂。", "cites": [{"t": "掌肿疡、溃疡、金疡、折疡之祝药劀杀之齐。", "b": "《周礼·疡医》"}, {"t": "八方分崩,中夏鱼溃。", "b": "《后汉书·刘陶传》"}, {"t": "发溃痈肿。", "b": "《素问·五常正大论》"}, {"t": "涉寒暑不溃。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "溃痈", "t": "恶性脓疮溃疡"}, {"w": "溃引", "t": "溃烂漫延"}, {"w": "溃裂", "t": "溃烂;破裂。"}]}, {"meaning": "达到。", "cites": [{"t": "筑室于道谋,是用不溃于成。", "b": "明·刘基《卖柑者言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2760wx','溅','1','jiàn','氵','12','','[{"pinyin": "jiàn", "defs": [{"meaning": "(从水,贱声。本义:用污水挥洒)。"}, {"meaning": "同本义。", "cites": [{"t": "溅,污洒也。", "b": "《说文》。段玉裁注:“谓用污水挥洒也。”"}]}, {"meaning": "液体受到冲激向四外飞射。", "cites": [{"t": "颈血溅大王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "溅沫惊飞鸟。", "b": "张九龄《庐山望瀑布》"}], "words": [{"w": "溅血", "t": "飞溅的鲜血"}, {"w": "溅沫", "t": "飞溅的水花"}, {"w": "溅泪", "t": "飞洒眼泪"}, {"w": "溅了一脸水;钢花四溅", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2761wx','滑','1','huá','氵','12','','[{"pinyin": "huá", "defs": [{"meaning": "(形声。从水,骨声。本义:滑溜,光滑)。"}, {"meaning": "同本义。", "cites": [{"t": "间关莺语花底滑。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "道中迷雾冰滑。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "滑擦", "t": "滑擦擦。形容很光滑"}, {"w": "滑出律", "t": "形容光滑"}, {"w": "滑踏", "t": "滑溜;不便行走"}, {"w": "滑刺溜", "t": "形容非常光滑。"}]}, {"meaning": "狡诈;油滑。亦指狡猾的人。", "cites": [{"t": "吏谨将之无铍(pī通披)滑。", "b": "《荀子·成相》"}, {"t": "为人上,操下如束湿薪。滑贼任威。", "b": "《史记·酷吏列传·宁成》"}], "words": [{"w": "滑贼", "t": "狡猾狠戾"}, {"w": "滑民", "t": "狡猾之民"}, {"w": "滑人", "t": "滑头的人"}, {"w": "滑鬼", "t": "狡诈或油滑的人。"}]}, {"meaning": "浮华不实。", "cites": [{"t": "但有时也会使革命精神转成浮滑。", "b": "鲁迅《集外集拾遗补编》"}]}, {"meaning": "滑动;滑过。", "cites": [{"t": "间关莺语花底滑。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "道中迷雾冰滑。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "滑擦", "t": "打滑"}, {"w": "滑垒", "t": "滑步上垒"}, {"w": "滑落;滑了一跤;滑下;滑倒;在错误的道路上越滑越远;滑行;滑雪", "t": ""}]}, {"meaning": "中药。滑石。", "cites": [{"t": "以滑养窍。", "b": "《周礼》"}]}, {"meaning": "中医脉象之一,指脉搏跳动流畅。", "cites": [{"t": "老先生这脉息,右寸略见弦滑。", "b": "《儒林外史》"}]}, {"meaning": "古国名 。在今河南。", "cites": [{"t": "灭滑而还。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2762wx','湃','1','pài','氵','12','','[{"pinyin": "pài", "defs": [{"meaning": "湃湃"}, {"meaning": "冰镇或用冷水浸;漂", "words": [{"w": "湃茶", "t": "将热茶放在冷水中。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2763wx','渝','1','yú','氵','12','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从水,俞声。本义:水由净变污,引申为改变,变)。"}, {"meaning": "同本义。", "cites": [{"t": "渝,变污也。", "b": "《说文》"}, {"t": "渝盟,无享国。", "b": "《左传·桓公元年》"}, {"t": "彼其之子,舍命不渝。", "b": "《诗·郑风·羔裘》"}, {"t": "明誓固在,不可渝也。", "b": "《宋史》"}], "words": [{"w": "渝涅", "t": "由白变黑。比喻更改初衷"}, {"w": "渝移", "t": "变易"}, {"w": "渝节", "t": "变节"}, {"w": "渝变", "t": "变更,变化。"}]}, {"meaning": "泛滥。", "cites": [{"t": "沸溃渝溢。", "b": "木华《海赋》"}], "words": [{"w": "渝溢", "t": "盈溢。"}]}, {"meaning": "(shū)。通达。", "cites": [{"t": "弗震弗渝。", "b": "《国语·周语上》"}, {"t": "渝食于野。", "b": "《墨子·非乐上》"}, {"t": "其以先后智渝者也。", "b": "《管子·侈靡》"}]}, {"meaning": "中国四川省重庆市的别称 。因自隋至宋渝州治此而得名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2764wx','湾','1','wān','氵','12','','[{"pinyin": "wān", "defs": [{"meaning": "(形声。从水,弯声。本义:河水弯曲处)。"}, {"meaning": "同本义。", "cites": [{"t": "湾,水曲也。", "b": "《广韵》"}, {"t": "潮来汹涌,水浸湾环。", "b": "《西游记》"}], "words": [{"w": "河湾;湾矶", "t": "弯曲水流中的石头"}, {"w": "湾湾", "t": "水边湾曲处"}, {"w": "湾头", "t": "水湾"}, {"w": "湾埼", "t": "弯曲的水岸"}, {"w": "湾澳", "t": "弯曲的水边"}, {"w": "湾回", "t": "河水弯曲处"}, {"w": "湾浦", "t": "水流弯曲的水滨"}, {"w": "湾曲", "t": "水湾曲折处"}, {"w": "湾山角络", "t": "偏僻的地方。"}]}, {"meaning": "系泊,在水湾处停泊。", "cites": [{"t": "就桥下湾住船,上岸独步。", "b": "明·冯梦龙《喻世明言》"}], "words": [{"w": "把船湾在那边", "t": ""}]}, {"meaning": "用于水或水面,相当于“处”。", "cites": [{"t": "一湾斜照水,三版顺风船。", "b": "唐·钱起《江行无题一百首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2765wx','渡','1','dù','氵','12','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从水,度声。本义:渡过,过水)。"}, {"meaning": "同本义。", "cites": [{"t": "渡,济也。", "b": "《说文》。朱骏声曰:“子史皆以度为之。”"}, {"t": "度江河,亡维楫。", "b": "《汉书·贾谊传》。按,后世分用,渡河不写作“度。”"}, {"t": "然后渡扬子江。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "渡仔", "t": "渡子。摆渡的人"}, {"w": "渡杯", "t": "比喻高僧的行踪"}, {"w": "渡客", "t": "乘船,渡江河的人"}, {"w": "夜渡沅江", "t": ""}]}, {"meaning": "通过,由此地、此时移到彼地彼时。", "cites": [{"t": "茅飞渡江洒江郊。", "b": "唐·杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "渡径", "t": "从小路走来。"}]}, {"meaning": "摆渡处(常用于地名)。", "cites": [{"t": "春潮带雨晚来急,野渡无人舟自横。", "b": "唐·韦应物《滁州西涧》"}]}, {"meaning": "渡船。", "cites": [{"t": "火照放下被卷,也蹲下来,等候搭渡。", "b": "陈残云《香飘四季》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2766wx','游','1','yóu','氵','12','','[{"pinyin": "yóu", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "游,旌旗之流也。", "b": "《说文》"}, {"t": "为下国缀旒。", "b": "《诗·长发》"}, {"t": "鞶厉游缨,昭其数也。", "b": "《左传·桓公十二年》"}]}, {"meaning": "江河的一段。", "cites": [{"t": "溯游从之,宛在水中央。", "b": "《诗·秦风》"}], "words": [{"w": "上游;下游;中游", "t": ""}]}, {"meaning": "鸟媒,猎人驯养用以招引野鸟的家鸟。", "cites": [{"t": "恐吾游之晏起,虑原禽之罕至。", "b": "《文选·潘岳·射雉赋》"}]}, {"meaning": "古水名 。淮河下游分支。由今江苏省涟水县、灌南县至连云港市入黄海。"}, {"meaning": "人或动物在水里浮行或潜泳。", "cites": [{"t": "其父善游。", "b": "《吕氏春秋·察今》"}, {"t": "子岂遽善游。", "b": ""}, {"t": "鱼游于沸鼎。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "游鱼细石。", "b": "吴均《与朱元思书》"}]}, {"meaning": "流动,不固定。", "cites": [{"t": "皆若空游无所依。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "游衍", "t": "游游衍衍。游荡;游乐;干干停停,拖延时间"}, {"w": "游花插趣", "t": "游荡作乐"}, {"w": "游回磨转", "t": "团团转"}, {"w": "游行", "t": "到处漫游。"}]}, {"meaning": "遨游;游览;游玩,优游逍遥。", "cites": [{"t": "噬肯来遊。", "b": "《诗·唐风·有杕之杜》"}, {"t": "遊毋倨。", "b": "《礼记·曲礼》。注:“行也。”"}, {"t": "膳饮从于遊。", "b": "《礼记·王制》。注:“谓出入上观。”"}, {"t": "厥壤可遊。", "b": "《封禅文》。注:“遨也。”"}, {"t": "文王不敢盘于遊用。", "b": "《书·无逸》"}, {"t": "同游者。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "游人虽未盛。", "b": "明·袁宏道《满井游记》"}, {"t": "余游巴黎。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "游春白相", "t": "春游;踏青"}, {"w": "游学呈子", "t": "报告本人外出,请求保留学籍的呈文"}, {"w": "游仙", "t": "漫游仙界。"}]}, {"meaning": "结交;交游。", "cites": [{"t": "此真吾所愿从游。", "b": "《史记·郦生传》"}, {"t": "又患无硕师名人与游。", "b": "明·宋濂《送东阳马生序》"}, {"t": "息交以绝游。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "游艺", "t": "外出游学,以文交友"}, {"w": "游合", "t": "交游聚会"}, {"w": "游从", "t": "相随同游;交往,特指与长辈交往"}, {"w": "游集", "t": "从各处来聚集。"}]}, {"meaning": "游说;宣扬。", "cites": [{"t": "孔子东游。", "b": "《列子·汤问》"}], "words": [{"w": "游夫", "t": "游说的人"}, {"w": "游化", "t": "潜移默化;云游教化"}, {"w": "游慝", "t": "凭借游说从事邪恶活动。"}]}, {"meaning": "孝察,学习。", "cites": [{"t": "游于三辅。", "b": "《后汉书·张衡传》"}]}, {"meaning": "出访。", "cites": [{"t": "劝东游。", "b": "清·梁启超《谭嗣同传》"}, {"t": "劝君东游。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2767wx','滋','1','zī','氵','12','','[{"pinyin": "zī", "defs": [{"meaning": "滋水。", "cites": [{"t": "滋水出牛饮山白陉谷,东入呼沱。从水,兹声。", "b": "《说文》"}]}, {"meaning": "一名兹水,今名磁河。源出河北省阜平县西部南坨山东,今为潴龙河支流。"}, {"meaning": "浆,液汁。", "cites": [{"t": "墨井盐池,玄滋素液。", "b": "左思《魏都赋》"}, {"t": "流光驿驿,甘滋泥泥。", "b": "邹阳《酒赋》"}]}, {"meaning": "滋味。", "cites": [{"t": "丧有疾,食肉饮酒,必有草木之滋焉,以为姜桂之谓也。", "b": "《礼记》"}]}, {"meaning": "滋生;繁殖。", "cites": [{"t": "滋,益也。", "b": "《说文》"}, {"t": "无使滋蔓。", "b": "《左传·隐公元年》。服注:“益也。”"}, {"t": "草木庳小不滋。", "b": "《吕氏春秋·明理》"}, {"t": "事滋无成。", "b": "《左传·襄公八年》"}, {"t": "树德务滋,除恶务本。", "b": "《书·泰誓下》"}], "words": [{"w": "滋疑", "t": "引起怀疑"}, {"w": "滋乳", "t": "滋生繁衍"}, {"w": "滋漫", "t": "滋生蔓延"}, {"w": "滋演", "t": "滋生演变"}, {"w": "滋蕃", "t": "滋生繁育"}, {"w": "滋茂", "t": "植物生长繁茂"}, {"w": "滋硕", "t": "竹长茂盛"}, {"w": "滋荣", "t": "生长繁茂。"}]}, {"meaning": "栽种。", "cites": [{"t": "播江离与滋菊兮,愿春日以为糗芳。", "b": "《楚辞》"}], "words": [{"w": "滋培", "t": "栽培;养育"}, {"w": "滋植", "t": "培植。"}]}, {"meaning": "增长 (今国之疵,民之病,有滋而无损焉,乌所谓言之效邪?)——王安石《上田正言书二》。", "words": [{"w": "滋殖", "t": "增加;增长。"}]}, {"meaning": "更加,愈益 ——表示程度。", "cites": [{"t": "去人滋久,思人滋生。", "b": "魏源《默觚上》"}, {"t": "滋可痛已。(更加使人悲痛。可,值得。已,同“矣”。)", "b": "孙文《序》"}]}, {"meaning": "脏污,污浊。", "cites": [{"t": "不获世之滋垢。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "滋垢", "t": "污垢"}, {"w": "滋泥", "t": "污浊的烂泥"}, {"w": "滋秽", "t": "污秽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2768wx','渲','1','xuàn','氵','12','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从水,宣声。本义:一种绘画方法,先把颜料涂在纸上,再用笔蘸水涂抹使色彩浓淡适宜) 同本义。", "cites": [{"t": "以水墨再三而淋之,谓之渲。", "b": "宋·郭熙《林泉高致·画诀》"}], "words": [{"w": "渲染", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2769wx','溉','1','gài','氵','12','','[{"pinyin": "gài", "defs": [{"meaning": "(形声。从水,既声。本义:灌注)。"}, {"meaning": "同本义。", "cites": [{"t": "溉,灌也。", "b": "《广韵》"}, {"t": "溉,一曰灌注也。", "b": "《说文》"}, {"t": "此渠皆可行舟,有余则用溉。", "b": "《汉书·沟洫志》"}, {"t": "西门豹引漳水溉邺,以富魏之河内。", "b": "《史记·河渠书》"}, {"t": "一亩之稼,则粪溉者先芽。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "溉田", "t": "灌溉田亩"}, {"w": "溉汲", "t": "汲水浇田"}, {"w": "溉浸;溉灌", "t": "灌溉"}, {"w": "溉沃万顷", "t": ""}]}, {"meaning": "洗,洗涤。", "cites": [{"t": "挹彼注兹,可以濯溉。", "b": "《诗·大雅·泂酌》"}, {"t": "谁能亨鱼?溉之釜。", "b": "《诗·桧风·匪风》"}, {"t": "器之溉者不写。", "b": "《礼记·曲礼上》"}], "words": [{"w": "溉釜;溉盥", "t": "洗涤。"}]}, {"meaning": "漆饰酒尊。", "cites": [{"t": "泂酌彼行潦,挹彼注兹,可以濯溉。", "b": "《诗·大雅·泂酌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2770wx','愤','1','fèn','忄','12','','[{"pinyin": "fèn", "defs": [{"meaning": "(形声。从心,贲(bēn)声。从“心”,表示与心情等有关。本义:郁结于心;憋闷)。"}, {"meaning": "同本义。", "cites": [{"t": "愤,懑也。", "b": "《说文》"}, {"t": "发愤以杼情。", "b": "《楚辞·九章·惜诵》"}, {"t": "志意蕴愤。", "b": "《后汉书·王符传》"}], "words": [{"w": "愤切", "t": "内心极度愤懑"}, {"w": "愤悁", "t": "愤懑郁积"}, {"w": "愤薄", "t": "郁结,充塞"}, {"w": "愤厥", "t": "由于愤气郁结造成的痉挛昏厥。"}]}, {"meaning": "充盈,旺盛。", "cites": [{"t": "愤,盈也。", "b": "《方言十二》"}, {"t": "阳瘅愤盈。", "b": "《国语·周语》"}], "words": [{"w": "愤盈", "t": "充溢,积满;气愤,愤懑"}, {"w": "愤盛", "t": "积满,充盈。"}]}, {"meaning": "愤怒;怨恨。同“忿”。", "cites": [{"t": "所以昭炯戒,激众愤,图报复也。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "袁人大愤,然未有以报也。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "愤怨", "t": "愤怒怨恨"}, {"w": "愤心", "t": "愤怒或愤激之心"}, {"w": "愤忿", "t": "愤怒"}, {"w": "愤沮", "t": "怨恨沮丧"}, {"w": "愤痛", "t": "愤怒悲痛"}, {"w": "愤咤", "t": "愤怒。"}]}, {"meaning": "发,奋。", "cites": [{"t": "愤于中则应干外。", "b": "《淮南子·脩务》"}], "words": [{"w": "发愤忘食;发愤图强;愤迅", "t": "奋迅"}, {"w": "愤勇", "t": "奋勇"}, {"w": "愤起", "t": "奋发而起。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2771wx','慌','1','huāng huǎng huang','忄','12','','[{"pinyin": "huāng", "defs": [{"meaning": "(形声。从心,荒声。本义:急忙,忙乱) 同本义。", "cites": [{"t": "怎这样慌?五日内我还便罢了!", "b": "明·梦觉道人《三刻拍案惊奇》"}, {"t": "偏偏我们走的慌,未带银子。", "b": "《施公案》"}], "words": [{"w": "走得太慌;慌不择路", "t": "慌里慌张,顾不上选择道路"}, {"w": "慌慌速速", "t": "匆忙,慌张"}, {"w": "慌速", "t": "慌张急促。"}]}, {"meaning": "散亡。", "cites": [{"t": "仆夫慌悴,散若流兮。", "b": "《楚辞》。王逸注:“慌,亡也。言己欲求贤人而未遭遇,仆御之人感怀愁悴,欲散亡而去,若水之流,不可复还也。”"}]}]}, {"pinyin": "huǎng", "defs": [{"meaning": "", "words": [{"w": "慌忽", "t": "模糊不清"}, {"w": "慌荒", "t": "黯淡迷茫的样子。"}]}]}, {"pinyin": "huang", "defs": [{"meaning": "", "words": [{"w": "闹得慌;累得慌", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2772wx','惰','1','duò','忄','12','','[{"pinyin": "duò", "defs": [{"meaning": "(形声。从心,隋省声。本义:不恭敬)。"}, {"meaning": "同本义。", "cites": [{"t": "惰,不敬也。", "b": "《说文》"}, {"t": "滕成公来会葬,惰而多涕。", "b": "《左传·襄公三十一年》"}, {"t": "今者治平日久,天下之人骄惰脆弱。", "b": "宋·苏轼《教战守策》"}], "words": [{"w": "惰傲", "t": "怠慢"}, {"w": "惰慢", "t": "懈怠不敬;懈怠涣散"}, {"w": "惰肆", "t": "怠慢放肆"}, {"w": "惰骄", "t": "骄傲懈怠"}, {"w": "惰偷", "t": "懈怠苟且,懒惰。"}]}, {"meaning": "懈怠;懒惰。", "cites": [{"t": "惰,懒也。", "b": "《广雅》"}, {"t": "佚而不隋,劳而不慢。", "b": "《荀子·非十二子》"}, {"t": "避其锐气,击其惰归。", "b": "《孙子·军争》"}, {"t": "诸司素偷惰。", "b": "《明史·海瑞传》"}], "words": [{"w": "惰懈", "t": "懒惰懈怠"}, {"w": "惰力", "t": "不图进取的消极落后力量"}, {"w": "惰心", "t": "怠懒的思想"}, {"w": "惰失", "t": "怠惰失职"}, {"w": "惰劣", "t": "怠惰无能"}, {"w": "惰侈", "t": "懒惰奢侈。"}]}, {"meaning": "衰败。", "cites": [{"t": "雄而不修者,其后必惰。", "b": "《墨子·脩身》"}], "words": [{"w": "惰坏", "t": "败坏"}, {"w": "惰君", "t": "败坏国事之君。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2773wx','愕','1','è','忄','12','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从心,咢声。本义:惊讶)。"}, {"meaning": "同本义 愕,惊也。——《广雅·释诂一》。", "cites": [{"t": "愕,然欲殴之。", "b": "《汉书·张良传》"}, {"t": "犹愕眙而不能阶。", "b": "班固《西都赋》"}, {"t": "成骇立愕呼。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "成益愕,急逐趁之,蟆入草间。", "b": ""}, {"t": "先生且喜且愕,舍狼而前。", "b": "马中锡《中山狼传》"}], "words": [{"w": "愕怪", "t": "惊奇"}, {"w": "愕窒", "t": "惊惶得不敢出气"}, {"w": "愕梦", "t": "惊愕而梦。"}]}, {"meaning": "直言。", "cites": [{"t": "愕愕者不以天下为忧。", "b": "《管子·白心》"}, {"t": "万里之朝,日闻唯唯,而后闻诸生之愕愕,此乃公卿之良药针石。", "b": "《盐铁论·国疾》"}, {"t": "謇愕之操,华首弥固。", "b": "《后汉书·陈蕃传》"}], "words": [{"w": "愕愕", "t": "直言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2774wx','愣','1','lèng','忄','12','','[{"pinyin": "lèng", "defs": [{"meaning": "(楞的异体字)(形声。本义:呆,失神;傻气)。"}, {"meaning": "同本义 。发愣(发呆);愣呆呆(失神的样子);愣神(发呆)。"}, {"meaning": "塞。", "cites": [{"t": "只见他卟的一声,吹着了火纸,就把那烟袋往嘴里给愣入。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2775wx','惶','1','huáng','忄','12','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从心,皇声。本义:恐惧,惊慌) 同本义。", "cites": [{"t": "惶,惶恐也。", "b": "《说文》"}, {"t": "惶,惧也。", "b": "《广雅》"}, {"t": "秦王方环柱走,卒惶急,不知所为。", "b": "《史记·刺客列传》"}, {"t": "孟贲狎猛虎而不惶。", "b": "《潜夫论·卜列》"}, {"t": "多官惶惶,只得散去。", "b": "明·梦觉道人《三刻拍案惊奇》"}], "words": [{"w": "惶惶", "t": "惊恐不安"}, {"w": "遑迫", "t": "惊慌"}, {"w": "惶汗", "t": "惊惧而汗流"}, {"w": "惶沮", "t": "恐惧沮丧"}, {"w": "惶怖", "t": "恐惧害怕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2776wx','愧','1','kuì','忄','12','','[{"pinyin": "kuì", "defs": [{"meaning": "(形声。从心,鬼声。本义:惭愧)。"}, {"meaning": "同本义。同“媿”。", "cites": [{"t": "小则如愧。", "b": "《礼记·儒行》"}, {"t": "尚不愧于屋漏。", "b": "《诗·大雅·抑》"}, {"t": "不愧于人。", "b": "《诗·小雅·何人斯》"}, {"t": "虽颜惭未知心愧。", "b": "《魏书·列女传》"}, {"t": "纵上不杀我,我不愧于心乎?", "b": "《史记·张耳陈余列传》"}, {"t": "谌虽暴抗,然闻言则大愧流汗。", "b": "柳宗元《段太尉逸事状》"}, {"t": "能不愧老人之言否。", "b": "清·周容《芋老人传》"}, {"t": "下恐愧吾师矣。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "兹游快且愧矣。", "b": "《徐霞客游记·游黄山记》"}, {"t": "兼愧贵家子。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "愧心", "t": "内心惭愧"}, {"w": "愧悔", "t": "惭愧后悔"}, {"w": "愧服", "t": "衷心佩服他人,自惭不如"}, {"w": "愧灼", "t": "极言惭愧之意"}, {"w": "愧天作人", "t": "上愧对天理,下愧对人事。"}]}, {"meaning": "折辱人;使羞惭。", "cites": [{"t": "昭王闻之,欲愧之以辞。", "b": "《战国策·齐策》"}], "words": [{"w": "愧辱", "t": "羞辱。"}]}, {"meaning": "责人罪咎。", "cites": [{"t": "是故君子不以其所能病人,不以人之所不能者愧人。", "b": "《礼记·表记》。注:“病、愧谓罪咎之。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2777wx','愉','1','yú','忄','12','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从心,俞声。本义:和悦,快乐) 同本义。", "cites": [{"t": "愉,乐也。", "b": "《说文》"}, {"t": "愉,喜也;说也。", "b": "《广雅》"}, {"t": "他人是愉。", "b": "《诗·唐风·山有枢》"}, {"t": "其进之也,敬之愉。", "b": "《礼记·祭义》"}, {"t": "愉愉如也。", "b": "《论语》"}, {"t": "心愉于内。", "b": "《史记·司马相如传》"}, {"t": "桀之治天也,使天下瘁瘁焉,人苦其性,是不愉也。", "b": "《庄子》"}, {"t": "上称三皇五帝之业,以愉其意。", "b": "《吕氏春秋》"}], "words": [{"w": "愉怡", "t": "快乐和悦"}, {"w": "愉心", "t": "愉悦心情"}, {"w": "愉目", "t": "悦目"}, {"w": "愉色", "t": "和悦的神色。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2778wx','慨','1','kǎi','忄','12','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从心,既声。本义:不得志而愤激)。"}, {"meaning": "同本义。", "cites": [{"t": "慨,忼慨壮士不得志也。", "b": "《说文》"}, {"t": "副将军史德威慨然任之。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "愤慨;慨切", "t": "愤激而恳切"}, {"w": "慨爽", "t": "慷慨爽朗"}, {"w": "慨慷", "t": "情绪激昂。"}]}, {"meaning": "疲惫的样子。", "cites": [{"t": "慨焉如不及,其反而息。", "b": "《礼记·檀弓下》。注:“慨,惫貌。”"}]}, {"meaning": "假借为“嘅”。感慨,叹息(因悲痛、不愉快而发出的叹息)。", "cites": [{"t": "情慨慨而长怀兮。", "b": "《楚辞·怨思》。注:“叹貌。”"}, {"t": "慨长思而怀古。", "b": "《文选·张衡·东京赋》"}, {"t": "慨含唏而增愁。", "b": "《文选·张衡·思玄赋》"}, {"t": "自以本志不遂,深自慨失。", "b": "《晋书·谢安传》"}, {"t": "万方声一慨,吾道竟何之?", "b": "杜甫《秦州杂诗》"}], "words": [{"w": "慨慷", "t": "感慨;激动"}, {"w": "慨慨", "t": "叹息的样子"}, {"w": "慨叹", "t": "感慨叹息"}, {"w": "慨念", "t": "感慨,怀念"}, {"w": "慨恨", "t": "感慨遗恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2779wx','割','1','gē','刂','12','','[{"pinyin": "gē", "defs": [{"meaning": "(形声。从刀,害声。本义:用刀分解牲畜的骨肉)。"}, {"meaning": "同本义。泛指用刀截断。", "cites": [{"t": "割,断也。", "b": "《广雅·释诂一》"}, {"t": "割鸡焉用牛刀。", "b": "《论语·阳货》"}, {"t": "犹未能操刀而使割也。", "b": "《左传·襄公三十一年》"}, {"t": "日钦劓割夏邑。", "b": "《书·多方》"}], "words": [{"w": "割鲜", "t": "割杀畜兽"}, {"w": "割烹", "t": "割切烹调"}, {"w": "割刀", "t": "切割之刀。"}]}, {"meaning": "分割;割取。", "cites": [{"t": "东割膏腴之地。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "割宅", "t": "划分宅区"}, {"w": "割壤", "t": "划分土地;裂地分封。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2780wx','寒','1','hán','宀','12','','[{"pinyin": "hán", "defs": [{"meaning": "(会意。金文外面是“宀”(mián),即房屋;中间是“人”;人的左右两边是四个“草”,表示很多;下面两横表示“冰”。寒冷是一种感觉,人们虽能感觉到,但是却看不见。于是古人就采用上述四个形体来创造这个字,人踡曲在室内,以草避寒,表示天气很冷。本义:冷,寒冷)。"}, {"meaning": "同本义。", "cites": [{"t": "寒,冻也。", "b": "《说文》"}, {"t": "凉是冷之始,寒是冷之极。", "b": "《列子·汤问》注"}, {"t": "乾为寒。", "b": "《易·说卦》"}, {"t": "若不可寻也,亦可寒也。", "b": "《左传·哀公十二年》"}, {"t": "以享司寒。", "b": "《左传·昭公四年》"}, {"t": "北方曰寒风。", "b": "《吕氏春秋·有始》"}, {"t": "岁寒,然后知松柏之后凋也。", "b": "《论语·子罕》"}, {"t": "饥渴寒暑,是事之变。", "b": "《庄子·德充符》"}, {"t": "寒光照铁衣。", "b": "《乐府诗集·木兰诗》"}, {"t": "寒雨连江夜入吴。", "b": "唐·王昌龄《芙蓉楼送辛渐》"}, {"t": "凄神寒骨。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "心忧炭贱愿天寒。", "b": "唐·白居易《卖炭翁》"}], "words": [{"w": "寒肃", "t": "寒冷肃杀"}, {"w": "寒悄", "t": "冷气侵入"}, {"w": "寒衾", "t": "冰冷的床铺"}, {"w": "寒噤", "t": "由于天冷而咬紧牙关或牙齿打战。"}]}, {"meaning": "卑微;低微。", "cites": [{"t": "吾本寒家。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "寒官", "t": "下级官吏"}, {"w": "寒品", "t": "出身寒微的人"}, {"w": "寒族", "t": "寒微的家族"}, {"w": "寒穷", "t": "寒微贫穷。"}]}, {"meaning": "声音凄凉。", "cites": [{"t": "杀气三时作阵云,寒声一夜传刁斗。", "b": "高适《燕歌行》"}], "words": [{"w": "寒吟", "t": "哀鸣。"}]}, {"meaning": "凋零;枯萎。", "cites": [{"t": "花寒鹦鹉病,春去杜鹃愁。", "b": "张可久《小山乐府》"}], "words": [{"w": "寒枝", "t": "寒冬凋零的林木。"}]}, {"meaning": "恐惧;战栗。", "cites": [{"t": "若是王以十成郑,梁氏寒心。", "b": "《战国策·秦策四》"}, {"t": "寒心酸鼻。", "b": "《高唐赋》。注:“寒心,谓战栗也。”"}]}, {"meaning": "特指终止盟约。", "cites": [{"t": "遂寒前盟。", "b": "宋·王明清《挥尘后录》"}]}, {"meaning": "寒冷的季节。与“暑”相对。", "cites": [{"t": "寒暑易节。", "b": "《列子·汤问》"}, {"t": "犯寒暑。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "涉寒暑。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "寒暄", "t": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2781wx','富','1','fù','宀','12','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从宀(miān),表示与房屋宫室有关。畐(fú)声。声符亦兼表字义。“畐”本像人腹满之形(参“福”字条),合“宀”为之,以示富人安居宫室,丰于饮馔之义。本义:财产多,富裕)。"}, {"meaning": "同本义(古跟“贫”,今跟“穷”相对)。", "cites": [{"t": "富,备也。一曰厚也。", "b": "《说文》"}, {"t": "富家大吉。", "b": "《易·家人》。疏:“禄位昌盛也。”"}, {"t": "二曰富。", "b": "《书·洪范》。疏:“家丰财货也。”"}, {"t": "以富得民。", "b": "《周礼·太宰》。注:“谓薮中财物。”"}, {"t": "殷人贵富而尚齿。", "b": "《礼记·祭义》。注:“臣能世禄曰富。”"}, {"t": "富人食稻与粱,贫子食糟与糠。", "b": "曹丕《上留田》"}], "words": [{"w": "富甲", "t": "首屈一指的富户"}, {"w": "富岁", "t": "富裕的年岁。即丰年"}, {"w": "富殖", "t": "财货丰裕"}, {"w": "富室", "t": "富有人家"}, {"w": "富贵浮云", "t": "视富贵如过眼烟云,不屑一顾"}, {"w": "富力", "t": "财力"}, {"w": "富赡", "t": "资财丰足;渊博高超"}, {"w": "富贾", "t": "富有的坐商;泛指富商。"}]}, {"meaning": "(fú)。古称富贵寿考为福。", "cites": [{"t": "何神不富?", "b": "《诗·大雅·瞻卬》。传:“富,福也。”?"}, {"t": "富也者,福也。", "b": "《礼记·郊特牲》"}, {"t": "典狱非讫于威,惟讫于富。", "b": "《书·吕刑》"}], "words": [{"w": "饶福", "t": "请求降福。"}]}, {"meaning": "多的;丰盛的。", "cites": [{"t": "富岁子弟多赖。", "b": "《孟子》。注:“丰年也。”"}, {"t": "且喜家中书籍最富。", "b": "《镜花缘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2782wx','寓','1','yù','宀','12','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从宀,禺(yù)声。宀,表示房屋。本义:寄居,寄住)。"}, {"meaning": "同本义。", "cites": [{"t": "寓,寄也。", "b": "《说文》"}, {"t": "国无寄寓。", "b": "《国琼·周语》"}, {"t": "诸侯不臣寓公。", "b": "《礼记·郊特牲》"}, {"t": "无寓人于我室。", "b": "《孟子》"}, {"t": "径造袁所寓。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "寓逆旅主人。", "b": "明·宋濂《送东阳马生序》"}, {"t": "围所寓舍。", "b": "宋·文天祥《后序》"}, {"t": "同寓数十人。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "寄寓", "t": "寄居"}, {"w": "寓士", "t": "寄居之人"}, {"w": "寓泊", "t": "寄住"}, {"w": "寓食", "t": "寄食。寄居在别人家里生活"}, {"w": "寓客", "t": "寄居他乡的人;外来暂住的旅客。"}]}, {"meaning": "寄托。", "cites": [{"t": "大夫寓祭器于大夫。", "b": "《礼记·曲礼》"}, {"t": "得臣与寓目焉。", "b": "《左传·僖公二十八年》"}, {"t": "寓形宇内。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "寓之酒。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "寓形", "t": "寄托其形体"}, {"w": "寓物", "t": "托物;寄于物"}, {"w": "寓性", "t": "不用本姓,改用有寄托或隐含某种意义的姓氏"}, {"w": "寓情", "t": "寄托情志。"}]}, {"meaning": "寄递;投寄。", "cites": [{"t": "子产寓书于子西。", "b": "《左传·襄公二十四年》"}], "words": [{"w": "寓书", "t": "寄信。"}]}, {"meaning": "住所。", "cites": [{"t": "方访君寓。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "有几间草房作寓;寓屋", "t": "住所。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2783wx','窜','1','cuàn','穴','12','','[{"pinyin": "cuàn", "defs": [{"meaning": "(会意。从鼠,从穴。老鼠在洞穴里,表示“隐匿”、“逃窜”。简化为“窜”,形声,从穴,串声。本义:躲藏)。"}, {"meaning": "奔逃。", "words": [{"w": "逃窜", "t": "逃跑流窜"}, {"w": "窜亡", "t": "逃亡;逃跑"}, {"w": "窜走", "t": "逃跑;潜逃。奔走;乱跑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2784wx','窝','1','wō','穴','12','','[{"pinyin": "wō", "defs": [{"meaning": "巢穴,窟,尤指用作隐藏或避难用的洞穴。", "cites": [{"t": "窩,穴居也。", "b": "《集韵》"}], "words": [{"w": "贼窝;土匪窝;窝窝凹凹", "t": "偏僻处。"}]}, {"meaning": "蜷伏。", "cites": [{"t": "咕唧也窝在那里了。", "b": "《儿女英雄传》"}]}, {"meaning": "胡乱裹缠、蒙盖。", "cites": [{"t": "冷冰冰窝着被儿,呆答答靠着枕头。", "b": "刘兑《金童玉女娇红记》"}]}, {"meaning": "陷。", "cites": [{"t": "那三儿只叫得一声,“我的妈呀!”镗,把个铜旋子扔了;咕咕,也窝在那里了。", "b": "《儿女英雄传》"}]}, {"meaning": "撮,噘。", "cites": [{"t": "只见陶三窝起嘴唇,打了两个胡哨,外面又进来两三个大汉。", "b": "《老残游记》"}]}, {"meaning": "团弄,卷。", "cites": [{"t": "须臾,剃下发来,窝作一团,塞在那柜纥络里。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2785wx','窖','1','jiào','穴','12','','[{"pinyin": "jiào", "defs": [{"meaning": "(形声。从穴,告声。从“穴”,表示与洞穴有关。本义:方形地窖)。"}, {"meaning": "藏谷麦的地穴。", "cites": [{"t": "窖,地藏也。", "b": "《说文》"}, {"t": "穿窦窖。", "b": "《礼记·月令》。注:“椭曰窦,方曰窖。”"}, {"t": "置入窖中。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "酒窖;菜窖;窖货", "t": "为预防腐烂变质而贮藏在地窖内的蔬菜果品等货物。"}]}, {"meaning": "坑;穴。", "cites": [{"t": "饥狗盈窖,嗼然。", "b": "《吕昏春秋·首时》"}], "words": [{"w": "窖穴;粪窖", "t": ""}]}, {"meaning": "贮藏;埋藏。", "cites": [{"t": "秦之败也,豪杰皆争取金玉,而任氏独窖仓粟。", "b": "《史记·货殖列传》"}], "words": [{"w": "啥东西都窖在地下;窖藏", "t": "地窖内贮藏或埋藏的财物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2786wx','窗','1','chuāng','穴','12','','[{"pinyin": "chuāng", "defs": [{"meaning": "(象形。从穴,囱(cōng)声。“窗”本作“囱”(cōng),小篆字,象天窗形,即在屋上留个洞,可以透光,也可以出烟(后来灶突也叫“囱”)。后加“穴”字头构成形声字。本义:天窗)。"}, {"meaning": "同本义。泛指房屋、车船上通气透光的洞口。", "cites": [{"t": "囱,在墙曰牅,在屋曰囱。窗,或从穴。", "b": "《说文》"}, {"t": "四旁两夹窗。", "b": "《考工记·匠人》。注:“窗助户为明。”"}, {"t": "天窗绮疎。", "b": "王逸《鲁灵光殿赋》"}, {"t": "凿窗启牖,以助户明也。", "b": "《论衡·别通》"}, {"t": "前辟四窗,垣墙周庭。", "b": "归有光《项脊轩志》"}, {"t": "当窗理云鬓,对镜帖花黄。", "b": "北朝乐府《木兰诗》"}, {"t": "旁开小窗,左右各四,共八扇。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "窗下", "t": "窗户下;上学读书"}, {"w": "窗友", "t": "旧时指塾中同学"}, {"w": "窗格", "t": "有格子的窗户;又称窗槅"}, {"w": "窗子眼", "t": "窗格子"}, {"w": "窗下功夫", "t": "指学问。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2787wx','窘','1','jiǒng','穴','12','','[{"pinyin": "jiǒng", "defs": [{"meaning": "(形声。从穴,君声。本义:生活或处境困迫,没有办法)。"}, {"meaning": "同本义。", "cites": [{"t": "窘,迫也。", "b": "《说文》"}, {"t": "又窘阴雨。", "b": "《诗·小雅·正月》。传:“困也。”"}, {"t": "夫唯捷径以窘步。", "b": "《离骚》"}, {"t": "窘若囚拘。", "b": "贾谊《服鸟赋》"}, {"t": "窘于饥寒。", "b": "《列子·黄帝》"}, {"t": "贼窘自归。", "b": "《汉书·郭解传》"}, {"t": "穷窘之来,所由有渐。", "b": "《齐民要术·序》"}, {"t": "屠大窘,恐前后受其敌。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "窘极", "t": "极端窘迫"}, {"w": "窘冗", "t": "困迫繁忙"}, {"w": "窘辱", "t": "窘迫凌辱"}, {"w": "窘涩", "t": "窘迫;为难"}, {"w": "窘穷", "t": "窘迫穷困"}, {"w": "窘敝", "t": "窘迫疲敝"}, {"w": "窘暴", "t": "穷困"}, {"w": "窘乏", "t": "困穷贫乏"}, {"w": "窘匮", "t": "贫乏,缺乏"}, {"w": "窘绝", "t": "艰困;穷尽。"}]}, {"meaning": "急的。", "cites": [{"t": "窘,急也。", "b": "《广雅》"}], "words": [{"w": "窘步", "t": "急步"}, {"w": "窘惶", "t": "窘惧。急迫惶恐。"}]}, {"meaning": "使为难,迫使对方陷入困境。", "cites": [{"t": "项籍使将兵,数窘汉王。", "b": "《史记·季布栾布列传》"}, {"t": "是狼为虞人所窘,求救于我。", "b": "马中锡《中山狼传》"}], "words": [{"w": "窘怖", "t": "为难恐惧"}, {"w": "窘定", "t": "窘住。窘迫、为难起来。"}]}, {"meaning": "要;切要。", "cites": [{"t": "窘乎哉,消者瞿瞿,孰知其要!", "b": "《素问》"}]}, {"meaning": "拘禁;局限。", "cites": [{"t": "飞鸣彼何乐,窘束此何冤!", "b": "唐·白居易《赎鸡》"}], "words": [{"w": "窘束", "t": "约束;拘谨"}, {"w": "窘默", "t": "拘谨缄默"}, {"w": "窘然", "t": "拘束貌"}, {"w": "窘涩", "t": "局促,不流畅。"}]}, {"meaning": "屡;仍。", "cites": [{"t": "安辩而邪,赐顽以荒,敢行称乱,窘出荐亡。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2788wx','遍','1','biàn','辶','12','','[{"pinyin": "biàn", "defs": [{"meaning": "(形声。本义:走遍) 同本义。", "cites": [{"t": "徧,徧也。", "b": "《说文》"}, {"t": "徧于群神。", "b": "《虞书》"}, {"t": "凡永嘉山水,游历殆遍。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "遍衙门告不成。", "b": "《陈州粜米》"}]}, {"meaning": "泛指普遍。", "cites": [{"t": "室人交徧摧我。", "b": "《诗·邶风·北门》"}, {"t": "公子引侯生坐上坐,遍赞宾客。", "b": "《史记·魏公子列传》"}], "words": [{"w": "满山遍野;遍窥", "t": "周览,尽见"}, {"w": "遍体", "t": "浑身,全身。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2789wx','雇','1','gù hù','隹','12','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从隹(zhuī),表示与鸟类有关。户声。(hù)本义:鸟名。即九雇,一种候鸟)。"}, {"meaning": "出钱让人给自己做事。", "cites": [{"t": "雇,傭也。", "b": "《集韵》"}, {"t": "以见钱直。", "b": "《后汉书·桓帝纪》"}, {"t": "倍雇南部所得生口,以还北虏。", "b": "《冯书·南匈奴传》"}], "words": [{"w": "雇唤", "t": "雇请"}, {"w": "雇觅", "t": "雇佣"}, {"w": "雇募", "t": "出钱招募"}, {"w": "雇直", "t": "雇用的酬劳"}, {"w": "雇借", "t": "雇用"}, {"w": "雇船", "t": ""}]}, {"meaning": "受雇。", "cites": [{"t": "展筑外城一十一里有余,役兵及雇夫共五十七万有余工。", "b": "宋·苏轼《乞罢宿城状》"}], "words": [{"w": "雇伙", "t": "被雇用的人"}, {"w": "雇夫", "t": "受雇用的人"}, {"w": "雇役", "t": "受雇的仆役。"}]}, {"meaning": "给价,付报酬。", "cites": [{"t": "凡敷钱,先视州若县应用雇直多少,随户等均取。", "b": "《南史·食货志》"}], "words": [{"w": "雇直", "t": "付酬,付费。"}]}]}, {"pinyin": "hù", "defs": [{"meaning": "古籍中鸟名。通作扈。", "cites": [{"t": "九雇,农桑候鸟。", "b": "《说文·隹部》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2790wx','裕','1','yù','衤','12','','[{"pinyin": "yù", "defs": [{"meaning": "(形声,从衣,谷(yù)声。衣物丰饶。本义:富饶。财物多。也指使富饶)。"}, {"meaning": "同本义。", "cites": [{"t": "裕,衣物饶也。", "b": "《说文》"}, {"t": "有孚裕无咎。", "b": "《易·晋》"}, {"t": "天地裕于万物。", "b": "《法言·孝至》"}, {"t": "包众容物谓之裕。", "b": "《贾子道术》"}, {"t": "裕其众庶。", "b": "《国语·吴语》"}, {"t": "此今兄弟,绰绰有裕。", "b": "《诗·小雅·角弓》"}], "words": [{"w": "裕后光前", "t": "造福后辈,光耀祖先"}, {"w": "裕民", "t": "使民众富裕"}, {"w": "裕饶", "t": "富饶"}, {"w": "裕民足国", "t": "裕国足民。使人民富裕,国家丰足。"}]}, {"meaning": "宽裕。", "cites": [{"t": "布施优裕也。", "b": "《国语·周语》"}], "words": [{"w": "裕利", "t": "大利,暴利"}, {"w": "裕裕", "t": "宽余自如的样子"}, {"w": "裕宽", "t": "松弛。不紧张"}, {"w": "裕如", "t": "自如的样子"}, {"w": "裕蛊", "t": "宽纵坏人。"}]}, {"meaning": "教导。", "cites": [{"t": "乃由裕民。", "b": "《书·康诰》"}], "words": [{"w": "裕民", "t": "教导民众。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2791wx','裤','1','kù','衤','12','','[{"pinyin": "kù", "defs": [{"meaning": "(形声。从衣,库声。本义:裤子。古指套裤,今为成人满裆裤及小儿开裆裤的通称) 同本义。", "cites": [{"t": "底下绛裤红鞋,鲜艳夺目。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2792wx','裙','1','qún','衤','12','','[{"pinyin": "qún", "defs": [{"meaning": "(形声。从衣,君声。《说文》从“巾”。本义:下裳,古代男女都有下裳)。"}, {"meaning": "古指下裳,今专指裙子。", "cites": [{"t": "裙,下裳也。", "b": "《说文》"}, {"t": "裙,下裳也。裙,群也,联接群幅也。", "b": "《释名》"}, {"t": "著我绣夹裙,事事四五通。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "缃绮为下裙。", "b": "《乐府诗集·陌上桑》"}, {"t": "揽裙脱丝履。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "出入无完裙。", "b": "唐·杜甫《石壕吏》"}, {"t": "血色罗裙翻酒污。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "连衣裙;连衫裙;围裙;短裙;超短裙;裙布钗荆", "t": "形容妇女服饰俭朴"}, {"w": "裙袄", "t": "衣裤"}, {"w": "裙门", "t": "裙子的前幅"}, {"w": "裙刀", "t": "压衣服用的佩刀"}, {"w": "裙幄", "t": "用裙子张挂连结而成的帷幕"}, {"w": "裙衫", "t": "女子所着的衣衫和裙子。因以喻妇女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2793wx','禅','1','chán shàn','礻','12','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从示,单声。从“示”,表示与鬼神有关。(shàn)本义:古代帝王辟基祭地) 佛教语。梵语“禅那”之略。原指静坐默念", "words": [{"w": "禅法", "t": "佛法"}, {"w": "禅坐", "t": "指僧侣端坐静修"}]}, {"meaning": "表示与佛教有关的事物", "words": [{"w": "禅门", "t": "佛教禅宗的教门"}, {"w": "禅床", "t": "和尚用来打坐和睡觉的床"}]}, {"meaning": "指禅房", "words": [{"w": "禅室", "t": "禅房"}, {"w": "禅阁", "t": "禅房"}]}]}, {"pinyin": "shàn", "defs": [{"meaning": "(形声。从示,单声。从“示”的字多与鬼神祭祀有关。本义:古代帝王祭地礼)。"}, {"meaning": "同本义。", "cites": [{"t": "禅,祭天也。", "b": "《说文》"}, {"t": "正失禅谓壇墠。", "b": "《风俗通》"}]}, {"meaning": "注:“除地于梁甫之阴,为墠之祭地也。变墠为禅神之也。”。", "cites": [{"t": "禅于始衍。", "b": "《史记·卫将军传》"}, {"t": "禅,祭地于梁阴。", "b": "《续汉书·祭祀志》"}, {"t": "封禅刻石纪号也,是墠为祭地,坛为祭天。", "b": ""}, {"t": "是以封泰山而禅梁父。", "b": "《大戴礼记》"}]}, {"meaning": "让位。"}, {"meaning": "帝王让位给他姓。", "cites": [{"t": "遂禅之。", "b": "《书·尧典》"}, {"t": "禅五世。", "b": "《史记·惠景间侯者年表》"}, {"t": "帝光禅位于虞舜。", "b": "《三国志·文帝纪》"}], "words": [{"w": "禅位", "t": "将帝位传让给别人"}, {"w": "受禅", "t": ""}]}, {"meaning": "也指传位于继承人。", "cites": [{"t": "至孝惠时,唯独长沙全,禅五世,以无嗣绝。", "b": "《史记》"}], "words": [{"w": "禅文", "t": "禅让皇位的文书"}, {"w": "禅诰", "t": "禅让皇位的诰书。"}]}, {"meaning": "传授。", "cites": [{"t": "万物皆种也,以不同形式相禅。", "b": "《庄子·寓言》"}, {"t": "而不知其禅之者。", "b": "《庄子·山水》。司马注:“授予也。”"}], "words": [{"w": "禅代", "t": "替代"}, {"w": "禅变", "t": "变化"}, {"w": "禅化", "t": "变迁转化。"}]}, {"meaning": "引申为继承。", "cites": [{"t": "四先生殁后,广仲尚能禅其家学。", "b": "全祖望《书宋史胡文定公传后》"}]}, {"meaning": "尽。", "cites": [{"t": "尧能禅均刑法以仪民,言其德无所不施。", "b": "《周礼·春官下·大司乐》郑注"}]}, {"meaning": "独断专行。", "cites": [{"t": "善禅其主,以集精微。", "b": "《韩非子·说疑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2794wx','禄','1','lù','礻','12','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从示,录声。本义:福气、福运)。"}, {"meaning": "同本义。", "cites": [{"t": "禄,福也。", "b": "《说文》"}, {"t": "福禄如茨。", "b": "《诗·小雅·瞻彼洛矣》"}, {"t": "使女受禄如天。", "b": "《仪礼·少牢馈食礼》"}, {"t": "又重之以寡君之不禄。", "b": "《国语·晋语》"}, {"t": "短折不禄。", "b": "《仪礼·曲礼》"}, {"t": "其胤维何?天被尔禄。", "b": "《诗·大雅·既醉》"}, {"t": "而后可以殿邦国,同福禄,来远人。", "b": "《左传·襄公十一年》"}, {"t": "儿已薄禄相。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "禄祚", "t": "福分和寿命"}, {"w": "禄命", "t": "古代宿命论者认为人生的盛衰,祸福、寿天、贵贱等均由天定"}, {"w": "禄相", "t": "有禄的相的样子。旧时相术认为人的形体、气色等与人的贵贱贫富、天寿等有关"}, {"w": "禄气", "t": "食禄之气运。"}]}, {"meaning": "官吏的俸给。", "cites": [{"t": "恽幸有余禄。", "b": "杨恽《报孙会宗书》"}, {"t": "你就起个名字,叫作禄蠹。", "b": "《红楼梦》"}], "words": [{"w": "高官厚禄;爵禄", "t": "爵位和俸禄"}, {"w": "薄禄", "t": "薪水"}, {"w": "禄蠹", "t": "领取官俸的蛀虫"}, {"w": "禄仕", "t": "为食俸禄而居官"}, {"w": "禄糈", "t": "古代官吏的俸给。"}]}, {"meaning": "册籍。", "cites": [{"t": "皆辨其物而奠其禄。", "b": "《周礼·天官下·职币》"}]}, {"meaning": "给予俸禄。", "cites": [{"t": "故,上贤,禄天下;次贤,禄一国;下贤,禄田邑。", "b": "《荀子》"}], "words": [{"w": "禄绝", "t": "死的讳辞"}, {"w": "禄亲", "t": "禄养。以俸禄养亲"}, {"w": "禄使", "t": "给俸禄供使用"}, {"w": "禄勋", "t": "给予有功者以俸禄。"}]}, {"meaning": "总领。", "cites": [{"t": "社稷不定,臣禄齐国之政。", "b": "《管子·大匡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2795wx','谢','1','xiè','讠','12','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从言,射声。本义:向人认错道歉)。"}, {"meaning": "同本义。", "cites": [{"t": "自谢曰。", "b": "《战国策·赵策》"}, {"t": "长跪而谢。", "b": "《战国策·魏策》"}, {"t": "旦日不可不蚤自来谢项王。", "b": "《史记·项羽本纪》"}, {"t": "惊谢曰。", "b": "清·周容《芋老人传》"}], "words": [{"w": "谢咎", "t": "引咎自退;悔过;谢罪"}, {"w": "谢错", "t": "认错赔不是"}, {"w": "谢室", "t": "待罪之室。"}]}, {"meaning": "用言辞委婉地推辞拒绝。", "cites": [{"t": "乃召拜黯为淮阳太守,黯伏谢不受命。", "b": "《史记·汲黯列传》"}, {"t": "谢媒人。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "楚而谢。", "b": "唐·李朝威《柳毅传》"}, {"t": "谢客矣。", "b": "明·宗臣《报刘一丈书》"}, {"t": "子退而休之,谢医却药。 ", "b": "宋·苏轼《盖公堂记》"}], "words": [{"w": "谢医", "t": "谢绝医疗"}, {"w": "谢金", "t": "谢绝礼金。"}]}, {"meaning": "辞去官职。", "cites": [{"t": "若此儿不救,便当回舟谢职,无复游宦之兴矣。", "b": "《南齐书·王僧虔传》"}, {"t": "当亦谢官去,岂令心事违。", "b": "唐·王维《送张五归山》"}], "words": [{"w": "谢老", "t": "告老还乡"}, {"w": "谢事", "t": "卸去官职"}, {"w": "谢政", "t": "致仕退休"}, {"w": "谢役", "t": "辞去差使"}, {"w": "谢职", "t": "卸去官职。"}]}, {"meaning": "告辞;告别。", "cites": [{"t": "广不谢大将军而起行。", "b": "《史记·李将军列传》"}, {"t": "侯生视公子色终不变,乃谢客就车。", "b": "《史记·魏公子列传》"}, {"t": "故不复谢。", "b": ""}, {"t": "不报谢?", "b": ""}, {"t": "过谢侯生。", "b": ""}, {"t": "往昔初阳岁,谢家来贵门。", "b": "《古诗为焦仲卿妻作》"}], "words": [{"w": "谢了扰", "t": "告辞"}, {"w": "谢别", "t": "告别,辞别。"}]}, {"meaning": "告诉,告诫。", "cites": [{"t": "谢汉使。", "b": "《汉书·李广苏建传》"}, {"t": "多谢后世人,戒之慎勿忘。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "以言辞相问候。", "cites": [{"t": "至府,为我多谢问赵君。", "b": "《史记·赵广汉传》"}, {"t": "界上亭长寄声谢我,何以不为致问?", "b": ""}]}, {"meaning": "感谢。", "cites": [{"t": "休谢之。", "b": "《三国演义》"}, {"t": "哙拜谢,起,立而饮之。", "b": "《史记·项羽本纪》"}, {"t": "且谢曰。", "b": "唐·李朝威《柳毅传》"}, {"t": "虽死必谢。", "b": ""}], "words": [{"w": "谢承", "t": "感谢;答谢"}, {"w": "谢荷", "t": "感谢"}, {"w": "谢候", "t": "致谢并问候"}, {"w": "谢私", "t": "感谢私下帮助。"}]}, {"meaning": "逝去。", "cites": [{"t": "诏曰:弟勰所生母潘早龄谢世,显号未加。", "b": "《魏书·彭城王勰传》"}], "words": [{"w": "谢宾客", "t": "死亡的委婉说法"}, {"w": "谢世", "t": ""}]}, {"meaning": "酬谢。", "cites": [{"t": "婚礼不许多用盘盒猪羊糖饼,不许厚礼物谢媒。", "b": "明·海瑞《禁约》"}, {"t": "受人十万,谢客数千,又重馈部吏。", "b": "《潜夫论》"}], "words": [{"w": "谢土", "t": "修建完毕,祭祀土神的礼义活动"}, {"w": "谢犒", "t": "酬谢;犒劳"}, {"w": "谢银", "t": "酬谢用的银子"}, {"w": "谢灶诰", "t": "祭灶王爷的青词。"}]}, {"meaning": "衰败,衰落。", "cites": [{"t": "宿觉名未谢,残山今尚存。", "b": "宋·叶适《宿觉庵》"}, {"t": "花之既谢。", "b": "明·李渔《闲情偶寄·种植部》"}]}, {"meaning": "逊让;不如。", "cites": [{"t": "既鲸鲵折首,西夏底定,便宜诉其本怀,避贤谢拙。", "b": "《宋书·王宏传》"}], "words": [{"w": "谢拙", "t": "自谦愚笨而辞职。"}]}, {"meaning": "避免,避开。", "cites": [{"t": "必以俪辞为文,何缘《十翼》不能一致,岂波澜既尽有所谢短乎?", "b": "章炳麟《文学总略》"}]}, {"meaning": "又如:谢短(避其所短)。"}, {"meaning": "古邑名 。在今河南省唐河南。", "cites": [{"t": "于邑于谢,南国是式。", "b": "《大雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2796wx','谣','1','yáo','讠','12','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。)。", "cites": [{"t": "有章句曰歌,无章曲曰谣。", "b": "《韩诗章句》"}, {"t": "辨妖祥于谣。", "b": "《国语·晋语》"}, {"t": "其歌声比余谣。", "b": "《书·大传》"}, {"t": "西王母为王谣。", "b": "《列子·周穆王》"}, {"t": "心之忧矣,我歌且谣。", "b": "《诗·魏风·园有桃》"}]}, {"meaning": "流言。", "cites": [{"t": "众女嫉余之娥眉兮,谣诼谓余以善淫。", "b": "《楚辞·离骚》"}], "words": [{"w": "谣诱", "t": "花言巧语,诱人上当。"}]}, {"meaning": "行歌,乐曲。", "cites": [{"t": "吾闻文、成之世,童谣有之。", "b": "《左传·昭公二十五年》"}, {"t": "好为庐山谣。", "b": "李白《庐山谣》"}], "words": [{"w": "谣曲", "t": "谣言。风谣,歌谣"}, {"w": "民谣;童谣", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2797wx','谤','1','bàng','讠','12','','[{"pinyin": "bàng", "defs": [{"meaning": "(形声兼会意。从言,旁声。本义:在背后公开地议论或批评某人的短处)。"}, {"meaning": "同本义。", "cites": [{"t": "谤,毁也。", "b": "《说文》。按,谤者道人之实,事与诬谮不同。大言曰谤,小言曰诽,曰讥。"}, {"t": "厉王虐,国人谤王。", "b": "《国语·周语上》"}, {"t": "有能谤讥于市朝。", "b": "《战国策·齐策》"}, {"t": "以致天下怨谤也。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "谤书", "t": "攻击别人或揭发别人隐私的文书;亦专指《史记》。"}]}, {"meaning": "诽谤。", "cites": [{"t": "信而见疑,忠而被谤,能无怨乎?", "b": "《史记·屈原贾生列传》"}, {"t": "是故事修而谤兴。", "b": "唐·韩愈《原毁》"}], "words": [{"w": "谤言", "t": "公开指责他人的话。同谤议"}, {"w": "谤誉", "t": "毁谤或赞誉。"}]}, {"meaning": "诅咒。", "cites": [{"t": "进胙者莫不谤令尹。", "b": "《左传·昭公二十七年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2798wx','谦','1','qiān','讠','12','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从言,兼声。本义:谦虚,谦逊) 同本义。", "cites": [{"t": "谦,敬也。", "b": "《说文》。按,侧重于内心上的恭顺谨慎。"}, {"t": "谦,逊让也。", "b": "《玉篇》"}, {"t": "谦也者,致恭以存其位者也。又,谦者,德之柄也。", "b": "《易·系辞》"}, {"t": "谦谦君子,用涉大川。", "b": "《易·谦》"}, {"t": "皆谦而礼交之。", "b": "《史记·魏公子列传》"}, {"t": "谦得益。", "b": "宋·欧阳修《新五代史·伶官传(序)》"}, {"t": "非苟为谦。", "b": "清·刘开《问说》"}], "words": [{"w": "谦洽", "t": "谦虚和蔼"}, {"w": "谦光", "t": "虽谦抑而辉光益显"}, {"w": "谦冲", "t": "谦虚"}, {"w": "谦克", "t": "谦逊自制"}, {"w": "谦厚", "t": "谦逊温厚。"}]}, {"meaning": "嫌疑。", "cites": [{"t": "贵而不为夸,信而不处谦。", "b": "《荀子·仲尼》"}]}, {"meaning": "丧失。", "cites": [{"t": "爵位不谦,田宅不亏。", "b": "《逸周书·武称》"}]}, {"meaning": "同时具备若干方面。", "cites": [{"t": "齐君由谦杀之恐不辜。", "b": "《墨子·明鬼下》"}]}, {"meaning": "满足。", "cites": [{"t": "此之谓自谦。", "b": "《礼记·大学》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2799wx','犀','1','xī','牛','12','','[{"pinyin": "xī", "defs": [{"meaning": "犀牛。", "cites": [{"t": "犀,南徼外牛,一角在鼻,一角在顶,似豕,从牛,尾声。", "b": "《说文》"}, {"t": "犀,似水牛,猪头,大腹,庳脚,脚有三蹄,黑色,三角,一顶上,一额上,一鼻上,鼻上者即食角也。小而不椭,好食棘,亦有一角者。", "b": "《尔雅》郭注"}, {"t": "水犀之甲。", "b": "《国语·越语》。注:’今徼外所送,有山犀、有水犀。水犀之皮有珠甲,山犀则无。”"}, {"t": "黄支国献犀牛。", "b": "《汉书·平帝纪》"}, {"t": "正南以文献为献。", "b": "《周书·王会篇》。按,犀角搅汤解诸毒药。"}, {"t": "荆有云梦,犀兕麋鹿满之。", "b": "《墨子·公输》"}], "words": [{"w": "犀牛望月", "t": "形容长久盼望"}, {"w": "犀分", "t": "划分。古代传说有水兽名水犀,出入有光,水为之分开,故云。"}]}, {"meaning": "犀牛皮。", "cites": [{"t": "犀衣颁七校,骏骑给千屯。", "b": "张逸少《北征凯旋诗》"}], "words": [{"w": "犀帖", "t": "薄犀皮制的帷幔"}, {"w": "犀革", "t": "犀牛皮。"}]}, {"meaning": "犀牛角 。可入药,也可制器。", "cites": [{"t": "饰以文犀。", "b": "《文选·曹植·七启》"}], "words": [{"w": "犀箸", "t": "用犀牛角做的筷子"}, {"w": "犀尘", "t": "犀柄尘尾。"}]}, {"meaning": "锋利;坚固。", "cites": [{"t": "虽有犀舟劲楫,…,有须者也。", "b": "《后汉书》"}], "words": [{"w": "犀烛", "t": "比喻能明察事理者"}, {"w": "犀光", "t": "锐利的目光"}, {"w": "犀舟", "t": "坚固的船只"}, {"w": "犀车", "t": "坚固的车子"}, {"w": "犀兵", "t": "锋利的兵器"}, {"w": "犀刻", "t": "观察事物锐利深刻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2800wx','属','1','shǔ zhǔ','尸','12','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从尾,蜀声。“尾”与身体相连。①(zhǔ)本义:连接。②类,族)。"}, {"meaning": "种类。亦特指牲类。", "cites": [{"t": "忠之属也,可以一战。", "b": "《左传·庄公十年》"}, {"t": "土地平旷,屋舍俨然,有良田美池桑竹之属。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "金属;属禽", "t": "分别飞禽的种类。"}]}, {"meaning": "亲属。", "cites": [{"t": "是疾易传染,遘者虽戚属,不敢同卧起。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "家属", "t": "户主外的家庭成员"}, {"w": "军属;眷属;属从", "t": "指按亲属关系而从其丧服"}, {"w": "属党", "t": "亲属"}, {"w": "属姓", "t": "同宗"}, {"w": "属疏", "t": "宗族关系疏远。"}]}, {"meaning": "侪辈。指同一类人。", "cites": [{"t": "若属皆且为所虏。", "b": "《史记·项羽本纪》"}, {"t": "有宁越徐尚苏秦杜赫之属为之谋。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "官属;部属。", "cites": [{"t": "徒属皆曰:“敬受命”。", "b": "《史记·陈涉世家》"}, {"t": "六卿分职各率其属。", "b": "《书·周官》"}, {"t": "台谒当以属礼。", "b": "《明史·海瑞传》"}], "words": [{"w": "下属", "t": "部下"}, {"w": "属名", "t": "南北朝时,壮丁为了逃避繁苛的赋役,多投身于豪门势族为附隶,称为属名"}, {"w": "属别", "t": "下属的类别"}, {"w": "属官", "t": "属下的官吏"}, {"w": "属佐", "t": "指下属佐助人员"}, {"w": "属役", "t": "仆役,佣人"}, {"w": "属部", "t": "部下,部属。"}]}, {"meaning": "生物分类系统上所用的等级之一 。动植物分类以种为单位,相近的种合为属,相近的属合为科。"}, {"meaning": "归属;隶属。", "cites": [{"t": "十三学得琵琶成,名属教坊第一部。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "小孤属舒州宿松县。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "属邦", "t": "附属国"}, {"w": "属心", "t": "诚心归附"}, {"w": "属车", "t": "随从的车辆。也称副车"}, {"w": "属城", "t": "隶属的县城"}, {"w": "属妇", "t": "指妾"}, {"w": "属僚", "t": "属下,部下。"}]}, {"meaning": "系;是。", "cites": [{"t": "今营中枪弹火药皆在荣贼之手,而营哨各官,亦多属旧人。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "查明属实", "t": ""}]}]}, {"pinyin": "zhǔ", "defs": [{"meaning": "继续;连接(侧重于互相衔接)。", "cites": [{"t": "亡国破家相随属。", "b": "《史记·屈原贾生列传》"}, {"t": "冠盖相属。", "b": "《史记·魏公子列传》"}, {"t": "常有高猿长啸,属引凄异。", "b": "《水经注·江水》"}, {"t": "挽炮车者,络绎相属。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "属纩", "t": "用新棉放在临死病人鼻前,验其是否有气"}, {"w": "属界", "t": "毗连地带"}, {"w": "属连", "t": "相连缀"}, {"w": "属志", "t": "犹连心"}, {"w": "属引", "t": "连续不断"}, {"w": "属文", "t": "连缀字句为文章"}, {"w": "属读", "t": "连读"}, {"w": "属聚", "t": "聚集"}, {"w": "属丝", "t": "连续之丝"}, {"w": "属好", "t": "结好"}, {"w": "属怨", "t": "结怨"}, {"w": "前后相属", "t": ""}]}, {"meaning": "缀辑;撰写。", "cites": [{"t": "屈平属草稿未定。", "b": "《史记·屈原贾生列传》"}, {"t": "衡少善属文。", "b": "《后汉书·张衡传》"}], "words": [{"w": "属文", "t": "撰写文章。属句;属章;属笔"}, {"w": "属辞", "t": "撰写诗文。属咏"}, {"w": "属书", "t": "著作"}, {"w": "属对", "t": "诗文对仗"}, {"w": "属缀", "t": "著作"}, {"w": "属稿", "t": "起草文稿"}, {"w": "属诗", "t": "作诗。"}]}, {"meaning": "使聚集在一起;集合。", "cites": [{"t": "齐师将兴,陈成子属孤子,三日朝。", "b": "《左传》"}], "words": [{"w": "属民", "t": "聚集民众"}, {"w": "属兵", "t": "调集士兵"}, {"w": "属役", "t": "聚集下役"}, {"w": "属神", "t": "会聚群神"}, {"w": "属游", "t": "聚游"}, {"w": "属行", "t": "集结军队。"}]}, {"meaning": "托付;委托。", "cites": [{"t": "属孟尝君。", "b": "《战国策·齐策四》"}, {"t": "属予作文以记之。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "属巡盐御史。", "b": "《明史》"}], "words": [{"w": "属请", "t": "请托"}, {"w": "属调", "t": "寄托的情调"}, {"w": "属累", "t": "托付"}, {"w": "属国", "t": "委托国事"}, {"w": "属邦", "t": "付托国事"}, {"w": "属任", "t": "委任,任用"}, {"w": "属寓", "t": "寄托"}, {"w": "属吏", "t": "交给执法官吏处理"}, {"w": "属命", "t": "委身托命"}, {"w": "属情", "t": "寄情。"}]}, {"meaning": "叮嘱;告诫", "cites": [{"t": "属儿善藏之,勿遣俗子见。", "b": "陆游《北窗试笔》"}], "words": [{"w": "属付", "t": "叮嘱"}, {"w": "属令", "t": "告戒。"}]}, {"meaning": "推托;借口。", "cites": [{"t": "[房法乘]常属疾不治事。", "b": "《资治通鉴》"}], "words": [{"w": "属国", "t": "委弃国家;委托国事"}, {"w": "属疾", "t": "托病;生病。"}]}, {"meaning": "关注。", "cites": [{"t": "师属之目。", "b": "《左传·定公十四年》"}, {"t": "则恐国人之属耳目于我也。", "b": "《国语·晋语五》"}, {"t": "坐者皆属目卑下之。", "b": "《汉书·盖宽饶传》"}]}, {"meaning": "佩带。", "cites": [{"t": "若不获命,其左执鞭弭,右属橐鞬,以与君周旋。", "b": "《左传·僖公二十三年》"}]}, {"meaning": "关连 神情与苏、黄不属。——明·魏学洢《核舟记》。"}, {"meaning": "跟随。", "cites": [{"t": "项王渡淮,骑能属者百余人耳。", "b": "《史记·项羽本纪》"}]}, {"meaning": "(zhù)倾注。", "cites": [{"t": "酌玄酒,三属于尊。", "b": "《仪礼·士昏礼》"}, {"t": "水属不理孙。", "b": "《周礼·考工记·匠人》。郑玄注:“属,读为注。”"}, {"t": "是时天雨,虹下属宫中。", "b": "《汉书·燕剌王旦传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2801wx','屡','1','lǚ','尸','12','','[{"pinyin": "lǚ", "defs": [{"meaning": "(从尸,娄声。本义:多次) 同本义。", "cites": [{"t": "屡当死。", "b": "宋·文天祥《指南录后序》"}, {"t": "公屡促之。", "b": "明·崔铣《记王忠肃公翱三事》"}, {"t": "帝屡欲召。", "b": "清·张廷玉《明史》"}, {"t": "屡撩之。", "b": "《聊斋志异·促织》"}], "words": [{"w": "屡空", "t": "经常贫乏而一无所有。后用以指贫穷、衣食不继"}, {"w": "屡常", "t": "平常,平时"}, {"w": "屡复", "t": "多次告白"}, {"w": "屡舞", "t": "频频歌舞"}, {"w": "屡试不售", "t": "多次参加科举考试都落榜了"}, {"w": "屡迁", "t": "多次变易,多次变迁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2802wx','强','1','jiàng qiáng qiǎng','弓','12','','[{"pinyin": "jiàng", "defs": [{"meaning": "倔强;固执。", "cites": [{"t": "申生甚好仁而彊。", "b": "《国语·晋语》"}], "words": [{"w": "强气", "t": "倔强脾气"}, {"w": "强颜", "t": "指人不知羞耻"}, {"w": "强团练", "t": "宋代杭州俗谚。指性情倔强,对人倔傲的人"}, {"w": "强头别脑", "t": "形容倔强的神气。"}]}, {"meaning": "僵硬。", "cites": [{"t": "一连吃了四五剂,口不歪了,只是舌根还有些强。", "b": "《儒林外史》"}]}]}, {"pinyin": "qiáng", "defs": [{"meaning": "(形声。从虫,弘声。本义:米中小虫)。"}, {"meaning": "同本义。"}, {"meaning": "襁褓。", "cites": [{"t": "成王少在强葆之中。", "b": "《史记·鲁周公世家》"}]}, {"meaning": "(通彊。弱的反义词)。"}, {"meaning": "弓有力。", "cites": [{"t": "彊,弓有力也。", "b": "《说文》"}, {"t": "强,健也。", "b": "《广韵》"}, {"t": "材官引彊。", "b": "《史记·绛侯世家》"}, {"t": "强弩之末。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "强弩", "t": "用机括发射的强弓。"}]}, {"meaning": "强盛;势力大。", "cites": [{"t": "不可谓强。", "b": "《墨子·公输》"}, {"t": "兵革之强。", "b": "《战国策·秦策》"}, {"t": "天下强国无过齐者。", "b": "《战国策·齐策》"}, {"t": "自胜者强。", "b": "《老子》"}, {"t": "赵强而燕弱。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "以弱为强。", "b": "《三国志·诸葛亮传》"}, {"t": "少年强则国强。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "强家", "t": "势力强盛的卿大夫"}, {"w": "强雄", "t": "强盛"}, {"w": "强寿", "t": "强盛而长久"}, {"w": "强对", "t": "强大的对手"}, {"w": "强元", "t": "以强大立足天下"}, {"w": "强兵", "t": "强大的军队"}, {"w": "强阵", "t": "强大的军队"}, {"w": "强旅", "t": "强大的军队"}, {"w": "强弱", "t": "强大与弱小。"}]}, {"meaning": "强健;健壮,有力。", "cites": [{"t": "筋骨之强。", "b": "《荀子·劝学》"}, {"t": "以强壮出。", "b": "《汉书·李广苏建传》"}, {"t": "刚健强力。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "强仕", "t": "四十岁。这年龄的人各方面已经成熟,正好出仕做官"}, {"w": "身强力壮;强死", "t": "人尚壮健而死于非命。"}]}, {"meaning": "刚强;坚决。", "cites": [{"t": "四十曰强。", "b": "《礼记·曲礼》"}, {"t": "强立而不反。", "b": "《礼记·学记》。注:“临事不惑也。”"}, {"t": "彊而义。", "b": "《书·皋陶谟》。传:“无所屈挠也。”"}, {"t": "彊忍不义。", "b": "《国语·楚语》"}, {"t": "申生甚好仁而彊。", "b": "《国语·晋语》"}], "words": [{"w": "强果", "t": "坚强果敢"}, {"w": " 强执", "t": "坚强固执。"}]}, {"meaning": "强横。", "cites": [{"t": "凶强侠气。", "b": "《世说新语·自新》"}], "words": [{"w": "强汗", "t": "强横勇猛"}, {"w": "强戾", "t": "强横凶暴"}, {"w": "强虐", "t": "强横暴虐"}, {"w": "强狠", "t": "强横凶狠。"}]}, {"meaning": "强暴。", "cites": [{"t": "彊,暴也。", "b": "《尔雅》"}, {"t": "侯彊侯以。", "b": "《诗·周颂·载芟》"}, {"t": "曾是彊御。", "b": "《诗·大雅·荡》"}], "words": [{"w": "强俊", "t": "强暴而又才智出众"}, {"w": "强虏", "t": "强暴的敌人"}, {"w": "强塞", "t": "强暴固执"}, {"w": "强鸷", "t": "强暴凶狠。"}]}, {"meaning": "优越;好。", "cites": [{"t": "博闻强志。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "强起", "t": "强如。胜过;比…更好"}, {"w": "比他强;比昨天强;我们的劳动条件一年比一年强;博闻强记;强处", "t": ""}]}, {"meaning": "略多于…的。", "cites": [{"t": "策勋十二转,赏赐千百强。", "b": "《木兰诗》"}], "words": [{"w": "三分之一强", "t": ""}]}, {"meaning": "强有力的弓。", "cites": [{"t": "挽弓当挽强。", "b": "杜甫《前出塞》"}]}, {"meaning": "强者。", "cites": [{"t": "弱固不可以敌强。", "b": "《孟子》"}]}, {"meaning": "使强,加强。", "cites": [{"t": "其为食也,足以增气充虚,彊体适腹而已矣。", "b": "《墨子·辞过》"}]}, {"meaning": "姓。"}]}, {"pinyin": "qiǎng", "defs": [{"meaning": "强制,强迫。", "cites": [{"t": "强饮强食。", "b": "《考工记·梓人》"}, {"t": "三君皆将强死。", "b": "《左传·文公十年》"}], "words": [{"w": "强匄", "t": "仗势索取"}, {"w": "强媒硬保", "t": "强迫做媒,包办成亲"}, {"w": "强劝架", "t": "连拉带劝;拉偏架"}, {"w": "强邀", "t": "夺取"}, {"w": "强风情", "t": "强作风流情事"}, {"w": "强为", "t": "硬干;蛮干"}, {"w": "强起", "t": "强迫不愿做官的人任官就职。"}]}, {"meaning": "劝勉。", "cites": [{"t": "强之。", "b": "《周礼·司谏》。注:“犹劝也。”"}, {"t": "君如彼何哉?强为善而已矣。", "b": "《孟子》"}]}, {"meaning": "勉强。", "cites": [{"t": "功不可彊成。", "b": "《淮南子·脩务》"}, {"t": "乃自强步。", "b": "《战国策·赵策》"}, {"t": "不可强夺。", "b": "《聊斋志异·狼三则》"}, {"t": "虽欲强聒。", "b": "宋·王安石《答司马谏议书》"}, {"t": "再四强之。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "牵强;强词夺正", "t": "强词夺理"}, {"w": "强勉", "t": "勉强"}, {"w": "强词", "t": "勉强说出来的话"}, {"w": "强口", "t": "勉强"}, {"w": "强应", "t": "勉强答应"}, {"w": "强不知以为知", "t": ""}]}, {"meaning": "竭力;尽力。", "cites": [{"t": "知困然后能自强也。", "b": "《礼记·学记》。注:“修业不敢倦。”"}, {"t": "强焉日有孳孳。", "b": "《礼记·表记》"}, {"t": "大臣强谏。", "b": "《战国策·赵策》"}, {"t": "强忍与言。", "b": "明·宗臣《报刘一丈书》"}, {"t": "将军强留之。", "b": "清·魏禧《大铁椎传》"}, {"t": "而强假焉。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "强恕", "t": "努力行忠恕之道"}, {"w": "强力", "t": "勉力"}, {"w": "强仁", "t": "勉力行仁"}, {"w": "强步", "t": "勉力步行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2803wx','粥','1','yù zhōu','米','12','','[{"pinyin": "yù", "defs": [{"meaning": "卖。", "cites": [{"t": "则使其贾粥之。", "b": "《周礼·巫马》"}, {"t": "不粥祭器。", "b": "《礼记·曲礼下》"}, {"t": "田里不粥。", "b": "《礼记·王制》"}]}, {"meaning": "又。", "cites": [{"t": "戎器不粥于市。", "b": ""}], "words": [{"w": "粥画", "t": "卖画的。"}]}, {"meaning": "养育。", "cites": [{"t": "初俊羔助厥母粥。俊也者大也,粥也者养也。", "b": "《大戴礼记》"}]}, {"meaning": "嫁出。", "cites": [{"t": "请粥庶弟之母。", "b": "《礼记》。郑玄注:“粥,谓嫁之也。”"}]}]}, {"pinyin": "zhōu", "defs": [{"meaning": "(形声。字本作“鬻”。从鬻(古文“鬲”字),米声。鬲,古烹饪器。本义:稀饭) 同本义。", "cites": [{"t": "粥,驙也。", "b": "《广雅》"}, {"t": "驙粥之食。", "b": "《礼记·檀弓》。疏:“厚曰驙,稀曰粥。”"}, {"t": "崇为客作豆粥。", "b": "《晋书·石崇传》"}, {"t": "恃粥耳。", "b": "《战国策·赵策》"}, {"t": "粥以糊口。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "粥饭僧", "t": "只吃粥饭而不努力修行的僧人"}, {"w": "粥鼓", "t": "谓僧寺集众食粥时击鼓"}, {"w": "弱饧", "t": "甜粥。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2804wx','疏','1','shū','疋','12','','[{"pinyin": "shū", "defs": [{"meaning": "(会意。“疋”有通的意思。本义:疏导,开通)。"}, {"meaning": "同本义。", "cites": [{"t": "疏,通也。", "b": "《说文》。疋者,破包足动也。孕则塞,生则通。因转注为开通分远之谊,俗字作疎,故汉疏广之后,隐其半为束氏。"}, {"t": "疏为川谷,以导其气。", "b": "《国语·周语》。注:“通也。”"}, {"t": "禹疏九河。", "b": "《孟子·滕文公上》"}, {"t": "疏为川渎、沟洫、陂池。", "b": "《柳宗元《天说》"}, {"t": "水之利害,自古而然。禹疏沟洫,随山浚川。", "b": "《史记·河渠书赞》"}], "words": [{"w": "疏决", "t": "疏浚;开通"}, {"w": "疏漏", "t": "漏水"}, {"w": "疏源", "t": "疏通水源"}, {"w": "疏瀹", "t": "疏浚,疏通"}, {"w": "疏辟", "t": "疏通开浚"}, {"w": "疏涤", "t": "疏浚清理;疏通清除"}, {"w": "疏治", "t": "疏通治理"}, {"w": "疏凿", "t": "打通阻塞,使流畅无阻。"}]}, {"meaning": "分开; 分散。", "cites": [{"t": "知伯围襄子于晋阳,襄子疏队而击之,大败知伯。", "b": "《淮南子·道应》"}, {"t": "疏石兰兮为芳。", "b": "屈原《湘夫人》"}], "words": [{"w": "疏分", "t": "犹瓜分"}, {"w": "疏析", "t": "分开;隔开"}, {"w": "疏索", "t": "分散;离散"}, {"w": "疏逸", "t": "散失"}, {"w": "疏越", "t": "疏散。"}]}, {"meaning": "分赐,分给。", "cites": [{"t": "疏爵分禄以褒贤。", "b": "《盐铁论·毁学》"}], "words": [{"w": "疏封", "t": "分封。帝王把土地或爵位分赐给臣子"}, {"w": "疏爵", "t": "分封爵位。"}]}, {"meaning": "清除;排除。", "cites": [{"t": "教之乐,以疏其秽,而镇其浮。", "b": "《国语·楚语》"}], "words": [{"w": "疏决", "t": "清除积滞、疏通管道"}, {"w": "疏整", "t": "疏理整顿"}, {"w": "疏瀹", "t": "洗涤沐浴"}, {"w": "疏林", "t": "修剪林木的枝条"}, {"w": "疏剔", "t": "清理剔除。"}]}, {"meaning": "雕刻,画饰。", "cites": [{"t": "赵主父令工施钓梯而缘播吾,刻疏人迹其上。", "b": "《韩非子·外储说左上》"}], "words": [{"w": "疏玉", "t": "玉雕绘饰"}, {"w": "疏柱", "t": "刻镂彩画的柱子"}, {"w": "疏镂", "t": "雕刻。"}]}, {"meaning": "分条记录或分条陈述。", "cites": [{"t": "抚军大悦,以金笼进上,细疏其能。", "b": "《聊斋志异·促织》"}], "words": [{"w": "疏名", "t": "分别署名"}, {"w": "疏举", "t": "逐条列举"}, {"w": "疏记", "t": "分条记载"}, {"w": "疏条", "t": "逐条陈述。"}]}, {"meaning": "疏忽;粗疏。", "cites": [{"t": "有疏,则为强国制也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "疏懒", "t": "散漫;疏忽"}, {"w": "疏略", "t": "疏忽大意"}, {"w": "疏虞", "t": "疏忽;差错"}, {"w": "疏防", "t": "疏于防备"}, {"w": "疏遗", "t": "疏忽遗漏"}, {"w": "疏懒", "t": "松懈;懈怠"}, {"w": "疏简", "t": "散慢,随便"}, {"w": "疏庸", "t": "疏懒;懒散"}, {"w": "疏惰", "t": "疏懒;懒散。"}]}, {"meaning": "注释,解释。", "cites": [{"t": "不能诵疏与注,一切弃之。", "b": "柳冕《与权德舆书》"}, {"t": "《庄子义疏》八卷。", "b": "《隋书·经籍志》"}, {"t": "恐不可户说,辄以是疏先焉。", "b": "明·徐光启《甘薯疏序》"}]}, {"meaning": "疏远,不亲近 。亦指离间,使疏远。", "cites": [{"t": "疏屈平而信上夫大夫,令严子兰。", "b": "《史记·屈原贾生列传》"}, {"t": "非疏骨肉爱过客也,多少之心异也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "疏慢", "t": "疏远而怠慢"}, {"w": "疏阔", "t": "疏远"}, {"w": "疏异", "t": "新鲜别致之意"}, {"w": "疏落", "t": "疏远;冷落"}, {"w": "疏木", "t": "疏远"}, {"w": "疏外", "t": "疏远见外"}, {"w": "疏斥", "t": "疏远排斥。"}]}, {"meaning": "稀疏;稀少。", "cites": [{"t": "疏,阔也。", "b": "《玉篇》"}, {"t": "天网灰灰,疏而不失。", "b": "《老子》"}, {"t": "以疏为美,密则无态。", "b": "龚自珍《病梅馆记》"}, {"t": "疏条交映,有时见日。", "b": "《艺文类聚·吴均·与朱元思书》"}, {"t": "窗外疏梅筛月影,依稀掩映。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "疏阔", "t": "远离;不在一起"}, {"w": "疏少", "t": "稀少"}, {"w": "疏微", "t": "稀少"}, {"w": "疏班", "t": "稀疏地布列"}, {"w": "疏细", "t": "稀疏而纤细"}, {"w": "疏网", "t": "稀疏的网。喻宽大的法律。"}]}, {"meaning": "粗略;不周密。", "cites": [{"t": "其于计疏矣。", "b": "《史记·范雎蔡泽列传》"}], "words": [{"w": "疏野", "t": "粗略草率"}, {"w": "疏卤", "t": "粗疏轻率"}, {"w": "疏悟", "t": "粗疏不顺人情"}, {"w": "疏庸", "t": "粗疏平庸"}, {"w": "疏率", "t": "粗疏轻率;粗略草率"}, {"w": "疏傲", "t": "粗疏傲慢"}, {"w": "疏愚", "t": "粗疏笨拙。"}]}, {"meaning": "粗糙。亦指糙米。", "cites": [{"t": "彼疏斯粺,胡不自替?", "b": "《诗·大雅·召旻》"}], "words": [{"w": "疏水箪瓢", "t": "粗糙的饮食,简陋的食具"}, {"w": "疏茹", "t": "泛指粗食"}, {"w": "疏食", "t": "粗粝的饭食,糙米饭"}, {"w": "疏薄", "t": "粗糙简单的饭食"}, {"w": "疏条", "t": "粗壮的枝条。"}]}, {"meaning": "久;长远。", "cites": [{"t": "且王者之不作,未有疏于此时者也。", "b": "《孟子》"}], "words": [{"w": "疏豁", "t": "疏阔。久别"}, {"w": "疏旷", "t": "远离;远隔"}, {"w": "疏逖", "t": "指荒远之地。"}]}, {"meaning": "迂阔;不切实际。", "cites": [{"t": "虽有区区之意,亦已疏矣。", "b": "嵇康《与山巨源绝交书》"}], "words": [{"w": "疏内", "t": "迂阔而木讷"}, {"w": "疏介", "t": "迂阔耿介"}, {"w": "疏涩", "t": "迂阔拘谨"}, {"w": "疏凝(迂阔固执)疏野(旷野", "t": ""}, {"w": "疏豁", "t": "开阔;敝亮"}, {"w": "疏妄", "t": "虚妄不实"}, {"w": "疏网", "t": "虚妄不实。"}]}, {"meaning": "远亲。泛指关系疏远的人。", "cites": [{"t": "故饥岁之春,幼弟不饷;穰岁之秋,疏客必食。", "b": "《韩非子·五蠹》"}], "words": [{"w": "疏房", "t": "即远族,远房"}, {"w": "疏宗", "t": "远房宗族"}, {"w": "疏客", "t": "关系疏远的客人"}, {"w": "疏丧", "t": "关系疏远者或远宗、远亲的丧事"}, {"w": "疏属", "t": "远宗;旁系亲属"}, {"w": "疏从", "t": "指堂房亲属"}, {"w": "疏族", "t": "远族;远亲。"}]}, {"meaning": "奏章。亦指上奏章。", "cites": [{"t": "寰再上疏丑诋,瑞亦屡疏乞休,慰留不允。", "b": "《明史·海瑞传》"}], "words": [{"w": "疏封", "t": "奏疏;奏章"}, {"w": "疏草", "t": "即疏稿。奏章的草稿"}, {"w": "疏直", "t": "上疏直陈"}, {"w": "疏奏", "t": "臣下向帝王上本进言"}, {"w": "疏陈", "t": "上疏陈述。"}]}, {"meaning": "书信。", "cites": [{"t": "虽书疏往返,未足解其劳结(思念之苦)。", "b": "曹丕《与吴质书》"}]}, {"meaning": "僧道拜忏时所焚化的祈祷文。", "cites": [{"t": "今日是员外生辰,小道送疏在此。", "b": "《京本通俗小说·志诚张主管》"}], "words": [{"w": "疏头", "t": "旧时向鬼神祈福的祝文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2805wx','隔','1','gé','阝','12','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从阜,鬲(gé)声。从“阜”,表示与地势高低上下有关。本义:阻隔、遮断)。"}, {"meaning": "同本义。", "cites": [{"t": "隔,障也。", "b": "《说文》"}, {"t": "右有陇坻之隘,隔阂华戎。", "b": "《文选·张衡·西京赋》"}, {"t": "隔篁竹,闻水声,如鸣佩环。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "把一间房隔成两间;隔越", "t": "阻隔,隔绝"}, {"w": "隔碍", "t": "阻隔。即隔越。"}]}, {"meaning": "间隔;距离。", "cites": [{"t": "隔了七八年,虽模样儿出脱的齐整,然大段未改,所以认得。", "b": "《红楼梦》"}], "words": [{"w": "隔涉", "t": "远隔"}, {"w": "隔三差五", "t": "每隔不长;时常"}, {"w": "隔岸", "t": "河的对岸"}, {"w": "隔了这么多天", "t": ""}]}, {"meaning": "隔绝;断绝。", "cites": [{"t": "誓不相隔卿,且暂还家去。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "不相合。", "cites": [{"t": "至于士庶贵贱之隔,俗以为常。", "b": "北齐·颜之推《颜氏家训》"}]}, {"meaning": "抑制。", "cites": [{"t": "核小者,曰“益智”,含之隔涎秽。", "b": "《齐民要术》引《广志》"}]}, {"meaning": "(jī)。打,敲打。", "cites": [{"t": "拮隔鸣球,掉八列之舞。", "b": "《汉书·扬雄传下》"}]}, {"meaning": "界限。", "cites": [{"t": "褒贬不甚明,得失无大隔。", "b": "唐·魏玄同《请吏部各择寮属疏》"}]}, {"meaning": "格子。", "cites": [{"t": "走了进去,三间花厅,隔子中间,悬着斑竹帘。", "b": "《儒林外史》"}]}, {"meaning": "膈膜。", "cites": [{"t": "脾生隔,肺生骨。", "b": "《管子·水地》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2806wx','隙','1','xì','阝','12','','[{"pinyin": "xì", "defs": [{"meaning": "(会意。从阜(fù)亦声。阜,土山,与土有关。本义:墙上开裂的裂缝)。"}, {"meaning": "同本义。也泛指孔穴、空隙。", "cites": [{"t": "隙,壁际孔也。", "b": "《说文》"}, {"t": "隙,裂也。", "b": "《广雅》"}, {"t": "墙之隙坏,谁之咎也。", "b": "《左传》"}, {"t": "若驷之过隙。", "b": "《礼记·三年问》"}, {"t": "二间夹钟出四隙之细也。", "b": "《国语·周语下》"}, {"t": "柳每以暇日隙壁窥韩(韩翃)所居,即萧然葭艾,闻客至,必名人。", "b": "唐·孟棨《本事诗》"}, {"t": "谚曰:“蠹众而木折,隙大而墙坏。”", "b": "《商君书·修权》"}], "words": [{"w": "裂隙;罅隙;隙穴", "t": "空隙与洞穴"}, {"w": "隙地", "t": "空地"}, {"w": "隙积", "t": "带有空隙垛体的体积。"}]}, {"meaning": "空子。", "cites": [{"t": "辅隙则国必弱。", "b": "《孙子·谋攻》"}, {"t": "狡冠窥窬,伺国瑕隙。", "b": "《汉书·刘琨劝进表》"}, {"t": "连抵其隙。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "无隙可乘;乘隙突围;乘隙;无隙可寻", "t": ""}]}, {"meaning": "要道;孔道。", "cites": [{"t": "及秦文、德、缪居雍,隙陇、蜀之货物而多贾。", "b": "《史记》"}]}, {"meaning": "空闲的地方或时间。", "cites": [{"t": "宋、郑之间有隙地焉。", "b": "《左传·哀公十二年》"}, {"t": "蒐于农隙。", "b": "《国语·周语上》"}, {"t": "三农之隙。", "b": "张衡《东京赋》"}, {"t": "秋冬之隙。", "b": "宋·苏轼《教战守》"}, {"t": "隙地未尽辟。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "隙日", "t": "空闲时日"}, {"w": "农隙;空隙", "t": ""}]}, {"meaning": "感情的裂痕。", "cites": [{"t": "太常卿滕胤,素与诸葛恪有隙。", "b": "《三国演义》"}, {"t": "与操有隙。", "b": "《资治通鉴·赤壁之战》"}], "words": [{"w": "隙恼", "t": "隔阂,不和睦。"}]}, {"meaning": "缺点,过失。", "cites": [{"t": "辅周则国必强,辅隙则国必弱。", "b": "《孙子》"}]}, {"meaning": "怨恨。", "cites": [{"t": "两个在翠云山前,不论亲情,却只讲仇隙。", "b": "《西游记》"}], "words": [{"w": "仇隙", "t": "怨恨"}, {"w": "隙难", "t": "怨仇"}, {"w": "隙憾", "t": "仇隙;仇恨。"}]}, {"meaning": "分裂。", "cites": [{"t": "黄色的脸色转化成了苍白色。嘴是隙着的。", "b": "郭沫若《北伐途次》"}], "words": [{"w": "隙末", "t": "指交谊终至于破裂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2807wx','隘','1','ài','阝','12','','[{"pinyin": "ài", "defs": [{"meaning": "(形声。籀文从阜,益声。阜,土山,从“阜”的字多与地势有关。本义:狭窄;狭小)。"}, {"meaning": "同本义。", "cites": [{"t": "隘,陋也。", "b": "《说文》"}, {"t": "君子以为隘矣。", "b": "《礼记·礼器》。注:“狭陋也。”"}, {"t": "相逢狭路间,道隘不容车。", "b": "《古诗十九首》"}, {"t": "诞置之隘巷,牛间腓字之。", "b": "《诗·大雅·生民》"}]}, {"meaning": "引申为心胸狭窄。", "cites": [{"t": "伯夷隘,柳下惠不恭。", "b": "《孟子·公孙丑上》"}, {"t": "或言其太隘。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "又。", "cites": [{"t": "此为宰相听事诚隘。", "b": ""}], "words": [{"w": "狭隘", "t": "宽度小;  局限在一个小范围内;不宏大。"}]}, {"meaning": "险要的通道,通常处在陡峭山谷的两个山峰之间。", "cites": [{"t": "一人守隘,万夫莫向。", "b": "左思《蜀都赋》"}, {"t": "筑石寨土堡于要隘。", "b": "清·徐珂《清稗类钞·战事类》。"}], "words": [{"w": "要隘", "t": "险要的关口。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2808wx','媒','1','méi','女','12','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从女,某声。本义:婚姻介绍人,媒人)。"}, {"meaning": "同本义。", "cites": [{"t": "媒,谋也。谋合二姓。", "b": "《说文》"}, {"t": "匪我愆期,子无良媒。", "b": "《诗·卫风·氓》"}, {"t": "不待父母之命,媒妁之言,钻穴隙相窥,逾墙相从。", "b": "《孟子·滕文公下》"}, {"t": "县令遣媒来。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "媒人婆迷了路儿,没的说了", "t": "做媒的迷了路,没有说合对象了"}, {"w": "媒人婆拾马粪,越发越晒", "t": "说媒人不怕碰钉子,面皮就像马粪那样,越碰钉子越厚"}, {"w": "媒红", "t": "酬谢媒人的布帛之类的彩礼"}, {"w": "媒钱", "t": "酬谢媒人的彩礼"}, {"w": "媒伯", "t": "婚姻介绍人"}, {"w": "媒姥", "t": "媒妇,媒妪,媒媪,媒妈妈,媒婆。"}]}, {"meaning": "媒介。", "cites": [{"t": "媒,谋合异类使和成者。", "b": "《周礼·媒氏注》"}, {"t": "洞房清宫,命曰寒热之媒。", "b": "枚乘《七发》"}], "words": [{"w": "媒子", "t": "媒翳、媒头。捕鸟用的鸟媒。"}]}, {"meaning": "介绍;招致。", "cites": [{"t": "随而媒孽其短。", "b": "《汉书·司马迁传》。注:“谓遘合会之。”"}], "words": [{"w": "媒怨", "t": "招来忿恨"}, {"w": "媒孽", "t": "喻挑拨是非,陷人于罪"}, {"w": "媒谱", "t": "捏造过恶,诬害他人"}, {"w": "媒绍", "t": "介绍;举荐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2809wx','絮','1','xù','糸','12','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从糸(mì),如声。本义:粗丝绵)。"}, {"meaning": "同本义。", "cites": [{"t": "絮,敝绵也。", "b": "《说文》。按,好者为绵,恶者为絮。"}, {"t": "絮三斤。", "b": "《汉书·高帝纪》。古无木绵,以絮纳袷中,谓之装褚,曰袍。"}, {"t": "剖其中,干若败絮。", "b": "明·刘基《卖柑者言》"}, {"t": "败絮其中。", "b": ""}], "words": [{"w": "絮衣", "t": "绵衣"}, {"w": "絮缯", "t": "丝帛之类的总称。"}]}, {"meaning": "经过弹制的棉花胎。", "cites": [{"t": "他们的婴孩没有棉衣,只好成天躺在土炕上那一堆破絮里。——茅盾《“战时景气”宠儿——宝鸡》", "b": ""}], "words": [{"w": "絮帛", "t": "棉絮与布帛"}, {"w": "絮棉;絮缕", "t": "棉絮与丝缕。泛指微细之物。"}]}, {"meaning": "像絮一样轻柔、洁白的东西。", "cites": [{"t": "无风杨柳漫天絮,不雨棠梨满地花。", "b": "范成大《碧瓦》"}, {"t": "山河破碎风飘絮。", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "芦絮;絮暖", "t": "指春暖絮飞之时"}, {"w": "柳絮", "t": "柳花之飞絮。"}]}, {"meaning": "棉花。", "cites": [{"t": "蛮夷不蚕,采木绵为絮。", "b": "《艺文类聚》"}]}, {"meaning": "头上巾。", "cites": [{"t": "巴蜀名头上巾为冒絮。", "b": "《续方言疏证》"}, {"t": "又如:絮巾(巾絮。古代的一种头巾)", "b": ""}]}, {"meaning": "在衣服、被褥里铺丝棉、棉花等物。", "cites": [{"t": "明朝驿使发,一夜絮征袍。", "b": "《子夜吴歌四首》"}], "words": [{"w": "絮衣", "t": "内铺丝棉的衣服"}, {"w": "絮纩", "t": "棉袄,棉袍"}, {"w": "絮袄", "t": "内充丝绵或棉絮的冬季上衣。"}]}, {"meaning": "优弱寡断。", "cites": [{"t": "时有一事,富公疑之,久而不决。韩曰:公又絮。", "b": "清·翟灏《通俗编》"}]}, {"meaning": "说话啰唆。", "cites": [{"t": "今又以言语烦琐为絮,所谓絮叨叨是也。", "b": "《通俗编·言笑》"}], "words": [{"w": "絮絮答答", "t": "唠叨不休"}, {"w": "絮咶", "t": "唠叨"}, {"w": "絮絮聒聒", "t": "唠叨不休"}, {"w": "絮繁", "t": "唠叨"}, {"w": "絮气", "t": "形容文字牵扯烦琐,意思不鲜明。"}]}, {"meaning": "因多次重复而厌烦。", "cites": [{"t": "既是他嫌那玫瑰膏子吃絮了,把这个拿两瓶子去。", "b": "《红楼梦》"}], "words": [{"w": "絮繁", "t": "厌烦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2810wx','嫂','1','sǎo','女','12','','[{"pinyin": "sǎo", "defs": [{"meaning": "(形声。从女,叟声。本义:兄之妻)。"}, {"meaning": "同本义。", "cites": [{"t": "嫂,兄妻也。", "b": "《说文》"}, {"t": "女子谓兄之妻为嫂。", "b": "《尔雅》"}, {"t": "是嫂亦可谓之母乎?", "b": "《礼记太传》"}, {"t": "兄弟嫂妹妻妾皆窃笑之。", "b": "《史记·苏秦列传》"}], "words": [{"w": "表嫂;大嫂;嫂溺叔援", "t": "变通;权变。古时男女授受不亲,有人问孟子:阿嫂落水该不该救:孟子说应该。男女授爱不亲是“经”,伸手救援是“权”。必要时要从权。后人遂称“经权达变”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2811wx','媚','1','mèi','女','12','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。从女,眉声。“眉”也有示意作用,表示以目媚人。本义:爱;喜爱)。"}, {"meaning": "同本义。", "cites": [{"t": "媚,说也。", "b": "《说文》"}, {"t": "思媚周姜。", "b": "《诗·大雅·思齐》。传:“爱也。”"}, {"t": "媚兹一人。", "b": "《诗·大雅·下武》"}], "words": [{"w": "媚子", "t": "所爱之人;爱子"}, {"w": "媚好", "t": "爱悦"}, {"w": "媚靥", "t": "女子两颊讨人喜欢的酒窝。"}]}, {"meaning": "逢迎取悦。", "cites": [{"t": "人服媚之如是。", "b": "《左传·宣公三年》"}, {"t": "若是乃能媚于神。", "b": "《国语·周语》"}, {"t": "吴音相媚好。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "自媚于众。", "b": "宋·王安石《答司马谏议书》"}, {"t": "欲媚上官。", "b": "《聊斋志异·促织》"}, {"t": "甘言媚词。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "谄媚", "t": "用卑贱的态度向人讨好"}, {"w": "媚上", "t": "取悦主上"}, {"w": "媚色", "t": "取悦于人的神态"}, {"w": "媚世", "t": "讨好世俗的人"}, {"w": "媚抚", "t": "抚爱;取悦"}, {"w": "媚术", "t": "逢迎谄媚的伎俩"}, {"w": "媚爱", "t": "取悦;取宠"}, {"w": "媚灶", "t": "比喻阿附权贵。"}]}, {"meaning": "姿态可爱,侧重于婀娜多姿,逗人爱。", "cites": [{"t": "媚,美也。", "b": "《尔雅》"}, {"t": "媚,好也。", "b": "《广雅》"}, {"t": "烟视媚行。", "b": "《吕氏春秋·不屈》"}, {"t": "石韫玉而山辉,水怀珠而川媚。", "b": "陆机《文赋》"}, {"t": "绿筱(竹)媚清涟。", "b": "谢灵运《过始宁墅》"}], "words": [{"w": "明媚", "t": "景物鲜明可爱;眼睛明亮动人"}, {"w": "媚好", "t": "美好;娇美"}, {"w": "媚秀", "t": "娇美秀丽"}, {"w": "媚曼", "t": "娇美"}, {"w": "媚景", "t": "谓春景;美好的景物"}, {"w": "媚娇", "t": "容貌声音妩媚动人"}, {"w": "媚趣", "t": "优美动人的意趣。"}]}, {"meaning": "假借为“魅”。具有魅力,具有诱惑力或吸引力的。", "cites": [{"t": "鬼媚不能欺。", "b": "《列子·方命》"}], "words": [{"w": "媚人的景色", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2812wx','婿','1','xù','女','12','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从女,胥声。或作“壻”。本义:古时女子称夫为婿)。"}, {"meaning": "同本义。", "cites": [{"t": "壻,夫也。", "b": "《说文》"}, {"t": "女子之夫为壻。", "b": "《尔雅》"}, {"t": "壻执雁入。", "b": "《礼记·昏义》"}, {"t": "壻御轮三周。", "b": "《诗·有女同车》笺"}, {"t": "赵有侧室曰穿,晋君之壻也。", "b": "《左传·文公十二年》"}, {"t": "东房少妇婿从军,每听乌啼知夜分。", "b": "李瑞《乌栖曲》"}, {"t": "汉贵将独有奉车都尉,天子姊婿,爵为通侯,当先降之。", "b": "《后汉书》"}, {"t": "若是姻缘早,把风流婿招,少什么美夫妻图画在碧云高。", "b": "汤显祖《牡丹亭·写真》"}], "words": [{"w": "夫婿", "t": "丈夫。"}]}, {"meaning": "成年男子的美称。", "cites": [{"t": "桓温有英雄之才,愿陛下勿以常人遇之,常婿畜之。", "b": "《晋书·桓温传》"}]}, {"meaning": "女儿、妹妹或其他晚辈的丈夫。", "cites": [{"t": "婿固不遣。", "b": "《史记·平原君虞卿列传》"}, {"t": "婿竟不调。", "b": ""}, {"t": "本来就没有儿子…祥子的确不错,但是提到儿婿两当,还差得多呢!", "b": "老舍《骆驼祥子》"}], "words": [{"w": "赘婿", "t": "入赘的女婿"}, {"w": "女婿", "t": "女儿的丈夫。"}]}, {"meaning": "作女婿;作夫婿。", "cites": [{"t": "况舜婿于天子,顽嚣嫚戾者独不畏之,又从而杀之耶?", "b": "唐·陆龟蒙《杂说》"}, {"t": "晟请以一子婿延赏女,延赏不许。", "b": "宋·孔平仲《续世说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2813wx','登','1','dēng','癶','12','','[{"pinyin": "dēng", "defs": [{"meaning": "(象形。本义:上车)。"}, {"meaning": "同本义。", "cites": [{"t": "登,上车也。", "b": "《说文》"}, {"t": "登,陞也。", "b": "《尔雅》"}, {"t": "登车则有光矣。", "b": "《礼记·玉藻》"}, {"t": "登轼而望之。", "b": "《左传·庄公十年》"}]}, {"meaning": "升,上,从下而上。", "cites": [{"t": "登席不由前。", "b": "《礼记·玉藻》。注:“升也。”"}, {"t": "欲释阶而登天兮。", "b": "《楚辞·惜诵》。注:“上也。”"}, {"t": "诞上登于岸。", "b": "《诗·大雅·皇矣》"}, {"t": "登斯楼也。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "从人四五百,郁郁登郡门。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "捷足先登;登宝", "t": "登基;帝王即位"}, {"w": "登筵", "t": "登上筵席"}, {"w": "登平", "t": "上升"}, {"w": "登仙", "t": "声名直上或升迁高官。"}]}, {"meaning": "进献。", "cites": [{"t": "农乃登黍。", "b": "《吕氏春秋》"}], "words": [{"w": "登隆", "t": "进上隆贵的"}, {"w": "登仪", "t": "进献礼物"}, {"w": "登闲", "t": "进入马厩"}, {"w": "登荐", "t": "进献。"}]}, {"meaning": "增加。", "cites": [{"t": "皆登一焉。", "b": "《左传·昭公三年》。注:“加也。”"}], "words": [{"w": "登降", "t": "增减"}, {"w": "登损", "t": "增减"}, {"w": "登曜", "t": "增添光彩。"}]}, {"meaning": "成熟;丰收。", "cites": [{"t": "五谷不登,禽兽逼人。", "b": "《孟子·滕文公》"}, {"t": "风雨时节,五谷登熟。", "b": "《淮南子·览冥》"}, {"t": "禾稼登熟。", "b": "《越绝书·纪吴王占梦》"}], "words": [{"w": "登年", "t": "丰年"}, {"w": "登秋", "t": "秋收"}, {"w": "登衍", "t": "丰收"}, {"w": "五谷丰登", "t": ""}]}, {"meaning": "登记;记载。", "cites": [{"t": "掌登万民之数。", "b": "《周礼·秋官·司民》"}], "words": [{"w": "登下", "t": "登记与削除"}, {"w": "登纪", "t": "登记。"}]}, {"meaning": "成,引申为定。", "cites": [{"t": "登是南邦。", "b": "《诗·大雅·崧高》"}, {"t": "登其夫家之众寡。", "b": "《周礼·遂人》"}, {"t": "年谷不登。", "b": "《礼记·曲礼》"}, {"t": "蚕事既登。", "b": "《礼记·月令》"}, {"t": "不登于器。", "b": "《左传·隐公五年》"}, {"t": "且不登叛人也。", "b": "《左传·襄公二年》"}]}, {"meaning": "谓科举考试中选。", "cites": [{"t": "登博学弘词科。", "b": "欧阳修《新唐书》"}], "words": [{"w": "登龙", "t": "登龙门。比喻科举中试"}, {"w": "登科发甲", "t": "考中进士为“登科”。发甲同登科"}, {"w": "登乡荐", "t": "考取乡试。"}]}, {"meaning": "蹲;呆。", "cites": [{"t": "荆公见屋傍有个坑厕,讨一张毛纸,走去登东。", "b": "《京本通俗小说·拗相公》"}]}, {"meaning": "又如:登东(解手。东:东圊,厕所);登坑(蹲茅坑)。"}, {"meaning": "穿。", "cites": [{"t": "(宝玉)登着青缎粉底小朝靴。", "b": "《红楼梦》"}]}, {"meaning": "又如:登云履(法师做法术时穿的鞋);登上鞋。"}, {"meaning": "上路,登程。", "cites": [{"t": "天明登前途,独与老翁别。", "b": "唐·杜甫《石壕吏》"}]}, {"meaning": "古代祭器名。", "cites": [{"t": "卬盛于豆,于豆于登。", "b": "《诗·大雅·生民》"}], "words": [{"w": "登豆", "t": "泛指祭器和食器。"}]}, {"meaning": "高。", "cites": [{"t": "不哀年之不登。", "b": "《国语·晋语》。注:“高也。”"}, {"t": "涉三皇之登闳。", "b": "《汉书·扬雄传》"}], "words": [{"w": "登闳", "t": "高远,高大。"}]}, {"meaning": "即刻。", "cites": [{"t": "登即相许和,便可作婚姻。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "登时", "t": "马上;立刻"}, {"w": "登场", "t": "当场"}, {"w": "登答", "t": "立刻答复。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2814wx','缅','1','miǎn','纟','12','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从糸(mì),面声。本义:微丝)。"}, {"meaning": "同本义。", "cites": [{"t": "缅,微丝也。", "b": "《说文》"}]}, {"meaning": "缅甸的简称。"}, {"meaning": "遥远。", "cites": [{"t": "举下缅也。", "b": "《谷梁传·庄公三年》"}, {"t": "缅然引领南望。", "b": "《国语·楚语》"}], "words": [{"w": "缅然", "t": "遥远的样子"}, {"w": "缅求", "t": "远求"}, {"w": "缅渺", "t": "遥远的样子"}, {"w": "缅远", "t": "久远;辽远;遥远"}, {"w": "缅迈", "t": "远行。"}]}, {"meaning": "尽貌。", "cites": [{"t": "冀阙缅其堙尽。", "b": "潘岳《西征赋》"}], "words": [{"w": "缅述", "t": "尽情叙说,备叙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2815wx','缆','1','lǎn','纟','12','','[{"pinyin": "lǎn", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,览声。本义:系船用的粗绳)。"}, {"meaning": "同本义。", "cites": [{"t": "结缆排鱼网。", "b": "杜甫《舟中》"}], "words": [{"w": "新船砍缆下水", "t": ""}]}, {"meaning": "拴;系。", "cites": [{"t": "急系缆。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "缆舟", "t": "以索系船"}, {"w": "缆系", "t": "用缆栓住。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2816wx','缉','1','jī qī','纟','12','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝、缠织有关。本义:绩,把麻搓成线)。", "cites": [{"t": "众妇夜缉灯烘。", "b": "宋·苏轼《次子由诗相庆》"}], "words": [{"w": "缉绩", "t": "纺织,编织"}, {"w": "缉取", "t": "搓成"}, {"w": "缉麻", "t": "绩麻"}, {"w": "缉妇", "t": "从事纺绩的妇女。"}]}, {"meaning": "搜捕。", "cites": [{"t": "访缉纠诘。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "缉听", "t": "向各处去搜集消息"}, {"w": "缉凶", "t": "搜捕凶犯"}, {"w": "缉擒", "t": "捉拿;缉拿"}, {"w": "缉探人", "t": "侦察人员。"}]}, {"meaning": "继续。", "cites": [{"t": "授几有缉御。", "b": "《诗·大雅·行苇》"}], "words": [{"w": "缉熙", "t": "本指逐渐达到光明,后因以指光明"}, {"w": "缉御", "t": "侍者连续更替地侍候着"}, {"w": "缉绪", "t": "继承传统。"}]}, {"meaning": "会合;和睦", "cites": [{"t": "适道已来,四十九载,妙应事多,宜加总缉,共成区畛。", "b": "《广弘明集·沈约·佛记序》"}, {"t": "有所缉缀。", "b": "《魏书·高允传》"}, {"t": "转将深意谕旁人,缉缀疵瑕遣潜说。", "b": "元稹《苦乐相倚曲》"}, {"t": "思所以镇定民心,缉宁外内。", "b": "《三国志·吴书·陆抗传》注"}, {"t": "还贤与能,群臣缉睦。", "b": "《陈书·虞荔传》"}], "words": [{"w": "缉缀", "t": "搜辑。引申为编撰书稿"}, {"w": "缉众", "t": "聚众"}, {"w": "缉宁", "t": "使祥宁安和。"}]}]}, {"pinyin": "qī", "defs": [{"meaning": "缝衣边。", "cites": [{"t": "缉,下横缝,缉其下也。", "b": "《释名·释衣服》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2817wx','缎','1','duàn','纟','12','','[{"pinyin": "duàn", "defs": [{"meaning": "(形声。从糸(mì),段声。本义:缝贴于鞋跟的革片、丝绦之类)。"}, {"meaning": "同本义。", "cites": [{"t": "履舄鞜襞绒缎紃。", "b": "《急就篇》"}]}, {"meaning": "一种质地厚密而有光泽的丝织物。", "cites": [{"t": "诏赐抚臣名马衣缎。", "b": "《聊斋志异·促织》"}], "words": [{"w": "缎疋", "t": "缎的总称。亦泛指丝织品"}, {"w": "缎匹", "t": "即缎疋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2818wx','缓','1','huǎn','纟','12','','[{"pinyin": "huǎn", "defs": [{"meaning": "(形声。从糸(mì),爰(yuán)声。本义:宽松;宽大)。"}, {"meaning": "慢;不急迫。与“急”相对。", "cites": [{"t": "缓,舒也。", "b": "《广韵》"}, {"t": "夫人于事己者过急,于事人者过缓。", "b": "《战国策·卫策》"}, {"t": "民事不可缓也。", "b": "《孟子·滕文公上》"}], "words": [{"w": "缓缓", "t": "缓慢的样子。同徐徐"}, {"w": "缓步代车", "t": "慢步行走以代替乘车。同安步当车"}, {"w": "缓辔而行", "t": "信马由缰地慢走。"}]}, {"meaning": "延期,延迟。", "cites": [{"t": "今夫缓于事己者,安能急于事人?", "b": "《战国策·卫策》"}, {"t": "君子以议狱缓死。", "b": "《易·中孚》"}], "words": [{"w": "缓死", "t": "宽缓减免死刑;延长寿命"}, {"w": "缓召", "t": "军事用语。应受动员召集或临时召集的后备军人以及国民兵,因故延缓征召的,称为缓召"}, {"w": "缓决", "t": "法律名词,对已宣判死刑的犯人,依据特定的状况,于一定时期内暂缓处决。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2819wx','缔','1','dì','纟','12','','[{"pinyin": "dì", "defs": [{"meaning": "(形声。从糸(mì),帝声。本义:结在一起)。"}, {"meaning": "同本义。", "cites": [{"t": "缔,结不解也。", "b": "《说文》"}, {"t": "合从缔交。", "b": "贾谊《过秦论》。注:“连接也。”"}, {"t": "缔交翩翩。", "b": "左思《吴都赋》"}], "words": [{"w": "缔婚", "t": "结婚"}, {"w": "缔生", "t": "联结而生"}, {"w": "缔连", "t": "联结。"}]}, {"meaning": "引申为郁结。", "cites": [{"t": "气缭转而自缔。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2820wx','缕','1','lǚ','纟','12','','[{"pinyin": "lǚ", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关。娄声。本义:麻线)。"}, {"meaning": "同本义。", "cites": [{"t": "缕,线也。", "b": "《说文》。段注:“凡蚕者为丝,麻者为缕。”"}, {"t": "麻缕丝絮轻重同,则贾相若。", "b": "《孟子·滕文公上》"}, {"t": "有布缕之征。", "b": "《孟子》。注:“紩铠甲之缕也。”"}, {"t": "余音袅袅,不绝如缕。", "b": "苏轼《赤壁赋》"}, {"t": "或断绝众缕,绕带手腕。", "b": "《潜夫论·俘侈》"}], "words": [{"w": "缕綦", "t": "用线织綦"}, {"w": "缕綵", "t": "用各色不同的线缕成其文采。"}]}, {"meaning": "泛指细而长的东西,线状物。", "cites": [{"t": "汉氏诸陵无不发掘,乃至烧取玉匣金缕。", "b": "《三国志·文帝纪》"}, {"t": "杨柳风轻,展尽黄金缕。", "b": "冯延己《鹊踏枝》"}], "words": [{"w": "缕子脍", "t": "食品名。以细切的鱼肉制成"}, {"w": "缕肉羹", "t": "肉丝羹"}, {"w": "缕金", "t": "金丝;以金丝为饰"}, {"w": "缕金百蝶穿花大红洋缎窄裉袄", "t": "指在大红洋缎的衣面上用金线绣成百蝶穿花图案的紧身袄。裉,上衣前后两幅在腋下合缝的部分"}, {"w": "缕细", "t": "细如丝缕。"}]}, {"meaning": "帛。", "cites": [{"t": "故为祷朝缕绵。", "b": "《管子·侈靡》。注:“帛也。”"}], "words": [{"w": "缕绵", "t": "绸帛丝绵。"}]}, {"meaning": "一条一条地,详尽地。", "cites": [{"t": "其功业相次千万者,不可复缕举也。", "b": "葛洪《抱朴子》"}], "words": [{"w": "缕细", "t": "底细,详情"}, {"w": "缕责", "t": "细责,苛责。"}]}, {"meaning": "一丝,一股。", "cites": [{"t": "红光一缕。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "一缕烟;千丝万缕;一缕幽香", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2821wx','骗','1','piàn','马','12','','[{"pinyin": "piàn", "defs": [{"meaning": "(形声。从马,扁声。本义:跃而上马)。"}, {"meaning": "跃上马背而骑乘;骑。同“騗”。", "cites": [{"t": "骗,谓跃上马也。", "b": "《纂文》"}], "words": [{"w": "骗马", "t": "飞身上马;勾引、调戏妇女"}, {"w": "骗石", "t": "上马或登车用的垫脚石。"}]}, {"meaning": "引诱,吸引。", "cites": [{"t": "一步一回头,景象时时变。越走得崎岖,越骗得神健。", "b": "清·徐大椿《游山乐》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2822wx','编','1','biān','纟','12','','[{"pinyin": "biān", "defs": [{"meaning": "(形声。从糸(mì),扁声。本义:顺次排列,编结在一起)。"}, {"meaning": "同本义。", "cites": [{"t": "编,次简也。", "b": "《说文》"}, {"t": "以绳次物曰编。", "b": "《声类》"}, {"t": "春秋编年,四时具而后为年。", "b": "《谷梁传·桓公元年》"}, {"t": "且请编之于令,永为国典。", "b": "柳宗元《驳复仇议》"}], "words": [{"w": "编号;编组;编队;编户", "t": "编入户籍的普通人家"}, {"w": "编民", "t": "编入户籍的平民"}, {"w": "编人", "t": "户籍编制之内的贫民。也称编民"}, {"w": "编次", "t": "按顺序编排"}, {"w": "编蒲", "t": "编订蒲叶使成册,以为书写之用。"}]}, {"meaning": "交织,编结。", "cites": [{"t": "编结沮。", "b": "《四子讲德论》。颜注:“犹编发也。”"}, {"t": "总编一根大辫,黑亮如漆。", "b": "《红楼梦》"}]}, {"meaning": "编辑;创作。", "cites": [{"t": "编书其罪。", "b": "《汉书·诸葛丰传》"}, {"t": "春秋编年。", "b": "《谷梁传·桓公元年》"}], "words": [{"w": "编杂志;编述", "t": "著述;编辑"}, {"w": "编订", "t": "编纂修订。"}]}, {"meaning": "连接。", "cites": [{"t": "编町成篁。", "b": "张衡《西京赋》。注:“连也。”"}], "words": [{"w": "编町", "t": "连绵于畎亩之中。"}]}, {"meaning": "用来穿联竹简的绳子。", "cites": [{"t": "孔子晚而喜《易》…读《易》,韦编三绝。", "b": "《史记·孔子世家》"}, {"t": "读之韦编三绝。", "b": "《汉书·儒林传》"}, {"t": "手不停披于百家之编。", "b": "韩愈《进学解》"}], "words": [{"w": "编韦", "t": "编联竹简的皮条或绳子。"}]}, {"meaning": "书籍。", "cites": [{"t": "并以为国人读兹编者勖。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "编简", "t": "书籍;史册"}, {"w": "编珠", "t": "类书名。其书集故事成语为对偶。"}]}, {"meaning": "姓。汉代有编盲意。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2823wx','骚','1','sāo','马','12','','[{"pinyin": "sāo", "defs": [{"meaning": "(形声。从马,蚤声。本义:刷马)。"}, {"meaning": "同本义。", "cites": [{"t": "骚,摩马。", "b": "《说文》。段玉裁注:“人曰搔,马曰骚,其意一也。摩马,如今人之刷马。”"}]}, {"meaning": "骚动;动乱。", "cites": [{"t": "骚,扰也。", "b": "《说文》。按,谓马扰动也。"}, {"t": "骚,动也。", "b": "《尔雅》"}, {"t": "徐方绎骚。", "b": "《诗·大雅·常武》"}, {"t": "南阳骚动。", "b": "《后汉书·李通传》。注:“骚,亦动也。”"}, {"t": "九年而王室始骚。", "b": "《国语·郑语》"}], "words": [{"w": "骚害", "t": "骚扰,伤害"}, {"w": "骚骚", "t": "急迫的样子"}, {"w": "骚杀", "t": "下垂飘动的样子"}, {"w": "骚边", "t": "骚扰边境。"}]}, {"meaning": "抓,挠,以指甲轻刮。", "cites": [{"t": "其人坚劲,寡有疥骚,终无瘠酲。", "b": "《管子·地员》"}, {"t": "花县征徭,衡门贫困,两事不堪骚首。", "b": "明·王錂《寻亲记》"}]}, {"meaning": "跛行。", "cites": [{"t": "吴楚偏蹇曰骚。", "b": "《方言》"}]}, {"meaning": "忧愁。", "cites": [{"t": "骚,愁也。", "b": "《楚辞·离骚·序》"}, {"t": "故忧愁幽思而作《离骚》。", "b": "《史记·屈原贾生列传》。索隐引应劭:“骚,忧也。”"}, {"t": "作离骚赋。", "b": "《汉书·贾谊传》。师古曰:“忧动曰骚。”"}, {"t": "小弁之诗作,离骚之辞兴。", "b": "《史记·冯奉世传赞》"}, {"t": "德义不行,则迩者骚离,而远者距远。", "b": "《国语·楚语上》"}, {"t": "骚吾心,则固僵仆烦愦愈不可过矣。", "b": "唐·柳宗元《答韦中立论师道书》"}], "words": [{"w": "骚离", "t": "忧愁而离心。"}]}, {"meaning": "忧愁。", "cites": [{"t": "“离骚”者,犹离忧也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "骚屑", "t": "纷扰不安的样子;状声词,风声"}, {"w": "骚骚", "t": "忧思郁闷的样子。"}]}, {"meaning": "腋臭、狐臭。", "cites": [{"t": "食之不骚。", "b": "《山海经》"}], "words": [{"w": "骚气", "t": "腥气"}, {"w": "骚臭", "t": "腥臭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2824wx','缘','1','yuán yuàn','纟','12','','[{"pinyin": "yuán", "defs": [{"meaning": "器物的边沿。", "cites": [{"t": "低下头去把嘴唇搁在杯缘。", "b": "茅盾《蚀·追求》"}], "words": [{"w": "缘石", "t": "砌筑在车行道与人行道之间的长条形石块或混凝土块,用以保护人行道并使车行道的路边水流通畅"}, {"w": "缘海", "t": "边缘海;沿海,接海"}, {"w": "缘边", "t": "沿边。指边境。"}]}, {"meaning": "原故,理由。", "cites": [{"t": "璞皆知其名姓及巧诈缘由。", "b": "沈约《宋书》"}]}, {"meaning": "因缘;缘分。", "cites": [{"t": "渠会永无缘。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "言谈大自缘。", "b": ""}, {"t": "画与书法为缘。", "b": "蔡元培《图画》"}]}, {"meaning": "又。", "cites": [{"t": "画与建筑雕刻为缘。", "b": ""}], "words": [{"w": "缘悭", "t": "无缘分"}, {"w": "缘业", "t": "姻缘"}, {"w": "缘会", "t": "缘分"}, {"w": "缘契", "t": "缘分"}, {"w": "缘便", "t": "机缘便利"}, {"w": "缘悭一面", "t": "无缘相见"}, {"w": "缘悭分浅", "t": "缺少缘分。"}]}, {"meaning": "因为;由于。", "cites": [{"t": "缘物之情。", "b": "《吕氏春秋·慎行论》"}, {"t": "缘愁似个长。", "b": "唐·李白《秋浦歌》"}, {"t": "缘土气有早晚。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "缘何", "t": "因何,为何"}, {"w": "缘坐", "t": "因牵连而获罪。同连坐"}, {"w": "缘底", "t": "因何;为什么。"}]}, {"meaning": "向上爬,攀援。", "cites": [{"t": "以若所为,求若所欲,犹缘木而求鱼也。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "缘竿", "t": "杂技的一种。即爬竿的特技"}, {"w": "缘木", "t": "爬树"}, {"w": "缘心", "t": "攀援事物之心"}, {"w": "缘竿", "t": "杂技中的爬竿节目"}, {"w": "缘跻", "t": "攀登。"}]}, {"meaning": "牵连。", "cites": [{"t": "百姓有罪,皆案之以法,其缘坐则老幼不免。", "b": "《隋书·刑法志》"}], "words": [{"w": "缘坐", "t": "连坐。因牵连而获罪"}, {"w": "缘累", "t": "牵累。"}]}, {"meaning": "沿着;顺着。", "cites": [{"t": "缘之以方城。", "b": "《荀子·议兵》"}, {"t": "末技游食之民,转而缘南畮,则畜积足。(南畮,泛指农田;畮,通“亩”。)", "b": "汉·贾谊《论积贮疏》"}, {"t": "缘溪行,忘路之远近。", "b": "晋·陶潜《桃花源记》"}], "words": [{"w": "缘头上脸", "t": "借故寻事"}, {"w": "缘例", "t": "沿袭惯例"}, {"w": "缘情体物", "t": "顺导性情,描摹物状"}, {"w": "缘手", "t": "随手;顺手"}, {"w": "缘情", "t": "因循人情;顺乎人情"}, {"w": "缘习", "t": "因袭。"}]}, {"meaning": "因凭借。", "cites": [{"t": "则缘耳而知声可也,缘月而知形可也。", "b": "《荀子·正名》"}], "words": [{"w": "缘私", "t": "因公便私,假公济私"}, {"w": "缘循", "t": "杖物而行,不能自立"}, {"w": "缘附", "t": "攀附;依附"}, {"w": "缘傅", "t": "缘附;依附"}, {"w": "缘夤", "t": "夤缘。攀附上升。指拉拢关系。"}]}]}, {"pinyin": "yuàn", "defs": [{"meaning": "(形声。从糸(mì),彖(tuàn)声。从糸,与衣物有关。本义:古时衣服的边饰)同本义。", "cites": [{"t": "缘,衣纯也。", "b": "《说文》"}, {"t": "缘谓之纯。", "b": "《尔雅》。注:“衣缘饰也。”"}, {"t": "缘广寸半。", "b": "《礼记·玉藻》。注:“饰边也。”"}, {"t": "常衣大练,裙不加缘。", "b": "《后汉书》"}], "words": [{"w": "衣缘", "t": "衣边。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2825wx','瑟','1','sè','王','13','','[{"pinyin": "sè", "defs": [{"meaning": "(指事。从珡,必声。本义: 古代拨弦乐器。形似古琴,每弦一柱,但无征位)。", "words": [{"w": "调瑟", "t": "调准瑟弦的音"}, {"w": "琴瑟", "t": "琴与瑟。"}]}, {"meaning": "古水名 。即今河南省罗山县的小黄河。"}, {"meaning": "庄重严谨。"}, {"meaning": "明洁。", "cites": [{"t": "瑟彼玉瓒,黄流在中。", "b": "《诗·大雅·早麓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2826wx','鹉','1','wǔ','鸟','13','','[{"pinyin": "wǔ", "defs": [{"meaning": "——见“鹦鹉”（yīngwǔ）。鸟名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2827wx','瑞','1','ruì','王','13','','[{"pinyin": "ruì", "defs": [{"meaning": "(形声。从玉,耑(zhuān)声。本义:玉制的符信,作凭证用)。"}, {"meaning": "同本义。", "cites": [{"t": "瑞,以玉为信也。", "b": "《说文》"}, {"t": "掌玉瑞器之藏。", "b": "《周礼·典瑞》。注;“符信也,人执以见曰瑞。”"}, {"t": "成六瑞益王所用镇圭也。", "b": "《周礼·小行人》"}, {"t": "以圭为瑞。", "b": "《礼记·礼器》"}, {"t": "司马请瑞。", "b": "《左传·哀公十四年》"}], "words": [{"w": "瑞珪", "t": "天子赐的作为凭信的圭玉"}, {"w": "瑞节", "t": "玉节;瑞与节"}, {"w": "瑞令", "t": "符命"}, {"w": "瑞玉", "t": "玉制信物。"}]}, {"meaning": "吉祥的事物。", "cites": [{"t": "世间谓之圣王之瑞,为圣母来矣。", "b": "《论衡·指瑞》"}], "words": [{"w": "瑞桢", "t": "吉祥。"}]}, {"meaning": "征兆。", "cites": [{"t": "禹亲把天之瑞令,以征有苗。", "b": "《墨子·非攻下》"}], "words": [{"w": "祥瑞", "t": ""}]}, {"meaning": "古州名。"}, {"meaning": "唐州名。故治在今辽宁省绥中县北。"}, {"meaning": "宋州名。故治在今江西省高安县。"}, {"meaning": "吉祥,吉利。", "cites": [{"t": "日月星辰瑞历,是禹桀之所同也。", "b": "《荀子·天论》"}], "words": [{"w": "瑞雪霏霏;瑞应", "t": "祥瑞的感应"}, {"w": "瑞星", "t": "吉祥之星"}, {"w": "瑞相", "t": "吉祥的征兆"}, {"w": "瑞物", "t": "吉祥之物"}, {"w": "瑞光", "t": "吉祥之光"}, {"w": "瑞日,瑞月", "t": "象征吉祥的日、月"}, {"w": "瑞兽", "t": "象征吉祥之兽"}, {"w": "瑞露", "t": "象征吉祥之露。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2828wx','瑰','1','guī','王','13','','[{"pinyin": "guī", "defs": [{"meaning": "(形声。从玉, 鬼声。本义: 美玉; 美石) 同本义。", "cites": [{"t": "瑰,攻瑰火齐也。", "b": "《说文》"}, {"t": "赤玉攻瑰。", "b": "《史记·司马相如传》"}, {"t": "何以赠之,琼瑰玉佩。", "b": "《诗·秦风·渭阳》"}], "words": [{"w": "瑰琼", "t": "美石;美玉"}, {"w": "瑰瓒", "t": "美玉与不纯的玉"}, {"w": "瑰室", "t": "玉石砌成的房子。"}]}, {"meaning": "珍贵;珍奇。", "cites": [{"t": "固瑰材而究奇,抗应龙之虹梁。", "b": "班固《西都赋》"}], "words": [{"w": "瑰艳", "t": "珍奇"}, {"w": "瑰秘", "t": "不为世人所知的珍宝"}, {"w": "瑰货", "t": "珍奇的物品"}, {"w": "瑰材", "t": "珍奇的栋梁材。"}]}, {"meaning": "奇特;杰出。", "cites": [{"t": "而世之奇伟、瑰怪、非常之观常在于险远,而人之所罕至焉。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "瑰僻", "t": "奇异少见"}, {"w": "瑰磊", "t": "形容卓越,特出"}, {"w": "瑰颖", "t": "奇特的才智"}, {"w": "瑰特", "t": "奇特"}, {"w": "瑰怪", "t": "奇特,珍贵"}, {"w": "瑰卓", "t": "瑰异卓越"}, {"w": "瑰材", "t": "有杰出才能的人。"}]}, {"meaning": "瑰丽,华丽,美丽。", "cites": [{"t": "轶态横出,瑰姿谲起。", "b": "汉·傅毅《舞赋》"}, {"t": "攒珍宝之玩好,纷瑰丽以奓靡。", "b": "汉·张衡《西京赋》"}], "words": [{"w": "瑰姿", "t": "美妙的姿态容貌"}, {"w": "瑰迈", "t": "美丽而超逸"}, {"w": "瑰绝", "t": "瑰丽绝伦"}, {"w": "瑰杰", "t": "俊美奇伟"}, {"w": "瑰轶", "t": "瑰丽超逸"}, {"w": "瑰景", "t": "奇美的景色"}, {"w": "瑰秀", "t": "瑰异秀美。"}]}, {"meaning": "伟,大", "cites": [{"t": "程千里身长七尺,骨桐瑰岸。", "b": "《册府元龟·总录·形貌》"}], "words": [{"w": "瑰瑰赖赖", "t": "形容肌肉隆起"}, {"w": "瑰岸", "t": "形容人的气概雄伟,相貌魁梧"}, {"w": "瑰硕", "t": "魁伟;健壮"}, {"w": "瑰木", "t": "巨大的木头"}, {"w": "瑰大", "t": "硕大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2829wx','瑙','1','nǎo','王','13','','[{"pinyin": "nǎo", "defs": [{"meaning": "(形声。从玉,匘(nǎo)声。双音词“玛瑙”) ——见“玛瑙”(mǎnǎo)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2830wx','魂','1','hún','鬼','13','','[{"pinyin": "hún", "defs": [{"meaning": "(形声。从鬼,云声。本义:灵魂,古人想象的能离开人体而存在的精神)。"}, {"meaning": "同本义。", "cites": [{"t": "魂,阳气也。", "b": "《说文》"}, {"t": "人生始化为魄,既生魄,阳曰魂。", "b": "《左传·昭公七年》"}, {"t": "聊乐我魂。", "b": "《韩诗·出其东门》"}, {"t": "魂者,精气也。", "b": "《论衡·纪妖》"}, {"t": "精气为物,游魂为变。", "b": "《易·系辞》"}, {"t": "随神而来往者谓之魂。", "b": "《灵枢经》"}, {"t": "魂去尸长留。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "魂悸以魄动。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "魂识", "t": "心灵;魂灵"}, {"w": "魂气", "t": "灵魂"}, {"w": "魂骸", "t": "死者的灵魂和躯体"}, {"w": "魂质", "t": "灵魂和实体。"}]}, {"meaning": "精神,神志 。如:断魂;梦魂萦绕;神魂颠倒;魂交(精神相感应,结合);魂鉴(精神理智)。泛指一切事物的精灵。如:花魂;诗魂;柳魂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2831wx','肆','1','sì','聿','13','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从长,聿(yù)声。本义:摆设;陈列)。"}, {"meaning": "同本义。", "cites": [{"t": "肆,极陈也。", "b": "《说文》。朱骏声曰:“此字本训长。”"}, {"t": "肆,陈也。", "b": "《广韵》"}, {"t": "或剥或享,或肆或将。", "b": "《诗·小雅·楚茨》"}, {"t": "肆筵设席,授几有缉御。", "b": "《诗·大雅·行苇》"}], "words": [{"w": "肆筵", "t": "摆设筵席"}, {"w": "肆肆", "t": "并列的样子。"}]}, {"meaning": "古时处死刑后陈尸示众。", "cites": [{"t": "吾力犹能肆诸市朝。", "b": "《论语·宪局》"}], "words": [{"w": "肆刑", "t": "极刑"}, {"w": "肆掠", "t": "陈尸示众和鞭笞"}, {"w": "肆鬯(陈尸设鬯为古浴尸之礼)肆器(古代陈尸之器)", "t": ""}]}, {"meaning": "进献解体牺牲。", "cites": [{"t": "以肆献裸享先王。", "b": "《周礼·春官·大宗伯》"}], "words": [{"w": "肆享", "t": "祭祀宗庙"}, {"w": "肆献", "t": "进牺牲,献醴酒。古代吉礼的一种"}, {"w": "肆祀", "t": "祭名。谓以全牛全羊祭祀祖先"}, {"w": "肆瘗", "t": "祭名。谓祭山后将所用牲玉埋于山中"}, {"w": "肆类", "t": "类,祭名。称祭天之礼。"}]}, {"meaning": "侵犯;冲突 以毒刺螫人);肆诈(肆行诈骗);肆剽(大肆劫掠);肆暴(滥施暴力,行凶)。"}, {"meaning": "恣纵,放肆。", "cites": [{"t": "不得安肆矣。", "b": "《汉书·吴王濞传》。师古曰:“肆,纵也。”"}, {"t": "故不为轩冕肆志。", "b": "《庄子·缮性》。注:“肆志,放纵其志。”"}, {"t": "深闳而肆。", "b": "《庄子·天下》"}, {"t": "惟北门外方,圆两炮台,被逆占据后,肆行无忌。", "b": "《三元里人民抗英》"}, {"t": "昔(周)穆王欲肆其心,周行天下。", "b": "《左传·昭公十二年》"}], "words": [{"w": "肆逆", "t": "随意虐害百姓"}, {"w": "肆毒", "t": "任意毒害"}, {"w": "肆讥腾谤", "t": "大肆讥诮,谤言沸腾"}, {"w": "肆掠", "t": "大肆掠夺"}, {"w": "肆奢", "t": "放纵,奢侈"}, {"w": "肆欲", "t": "纵欲"}, {"w": "肆饮", "t": "纵情饮酒"}, {"w": "肆横", "t": "恣意横行"}, {"w": "肆纵", "t": "肆意放纵"}, {"w": "肆手", "t": "放手。谓随意,任意"}, {"w": "肆心", "t": "恣意"}, {"w": "肆志", "t": "快意;随心;纵情"}, {"w": "肆言", "t": "无所顾忌地说话;纵言。"}]}, {"meaning": "宣扬;扩展。", "cites": [{"t": "晋天福初,允以国朝频肆赦,乃进《驳赦论》", "b": "《旧五代史·张允传》"}], "words": [{"w": "肆布", "t": "散布"}, {"w": "肆芳", "t": "散发芳香"}, {"w": "肆议", "t": "肆义。进言献策,提出意见。"}]}, {"meaning": "延伸,扩张 。", "cites": [{"t": "夫晋何厌之有?既东封郑,又欲肆其西封。", "b": "《左传·僖公三十年》"}], "words": [{"w": "肆通", "t": "畅通,四通八达"}, {"w": "肆募", "t": "广泛征集"}, {"w": "肆察", "t": "广泛地视察"}, {"w": "肆体", "t": "舒展身体。"}]}, {"meaning": "极力,勤苦。", "cites": [{"t": "瞻仰二祖,厥庸孔肆。", "b": "《文选·张衡·东京赋》"}, {"t": "轮匠肆目,不乏奚仲之妙;瞽史清耳,而无伶伦之察。", "b": "《文选·陆机·演连珠》"}], "words": [{"w": "肆心", "t": "用心;尽力"}, {"w": "肆目", "t": "尽其目力"}, {"w": "肆既", "t": "竭尽"}, {"w": "肆勤", "t": "尽力勤劳"}, {"w": "肆业", "t": "勤于所业。多指农业。"}]}, {"meaning": "店铺(上古时代表示商店)。", "cites": [{"t": "正其肆,陈其货贿。", "b": "《周礼》"}, {"t": "肆,市中陈物处也。", "b": "《文选·游西池》注"}, {"t": "帝命三市店肆,皆设帷帐。", "b": "《隋书·裴矩传》"}, {"t": "吾得升斗之水然活耳,君乃言此,曾不知早索我于枯鱼之肆。", "b": "《庄子·外物》"}], "words": [{"w": "肆廛", "t": "街市,店铺"}, {"w": "肆宇", "t": "肆宅"}, {"w": "肆宅", "t": "店铺"}, {"w": "肆业", "t": "泛指店务或其他类似业务"}, {"w": "肆头", "t": "街头,市上。"}]}, {"meaning": "手工业作坊。", "cites": [{"t": "百工居肆,以成其事。", "b": "《论语·子张》"}]}, {"meaning": "古代编悬乐器的单位,悬钟十六为肆。", "cites": [{"t": "凡县钟磬,半为堵,全为肆。", "b": "《周礼》"}]}, {"meaning": "“四”的大写,用于支票等上,以避免错误或更改。"}, {"meaning": "长;常。", "cites": [{"t": "其诗孔硕,其风肆好。", "b": "《诗·大雅·崧高》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2832wx','摄','1','shè','扌','13','','[{"pinyin": "shè", "defs": [{"meaning": "(形声。从手,聂声。本义:牵曳)。"}, {"meaning": "同本义。", "cites": [{"t": "摄,引持也。", "b": "《说文》"}, {"t": "摄车从之。", "b": "《左传·襄公二十三年》"}], "words": [{"w": "摄力", "t": "引力"}, {"w": "摄弓", "t": "张弓注矢作射击准备"}, {"w": "摄水", "t": "引水。"}]}, {"meaning": "执;持。", "cites": [{"t": "庭实皮,则摄之。", "b": "《礼记·聘礼》。注:“右手并执前足,左手并后足也。”"}, {"t": "摄少马兹。", "b": "《国语·吴语》"}, {"t": "皆摄弓而驰,荷兵而走。", "b": "司马相如《喻巴蜀檄》"}], "words": [{"w": "紧紧摄住娘的手指;摄守", "t": "掌管"}, {"w": "摄知", "t": "执掌。"}]}, {"meaning": "拘捕。", "cites": [{"t": "摄少司马兹与王士五人。", "b": "《国语·吴语》"}]}, {"meaning": "辅助、佐助。", "cites": [{"t": "朋友攸摄。", "b": "《诗·大雅·既醉》"}, {"t": "摄,佐也。", "b": "《左传·襄公三十一年》"}]}, {"meaning": "吸引。", "cites": [{"t": "磁石摄铁,不摄鸿毛。", "b": "顾况《广陵白沙大云寺牌》"}]}, {"meaning": "拍照。", "cites": [{"t": "摄影纪盛游,或左亦或右。", "b": "郑泽《壬子秋日钝庵邀摄影像作诗奉呈》"}]}, {"meaning": "假借为“代”。代理,兼理。", "cites": [{"t": "若王不与祭,则摄位。", "b": "《周礼·大宗伯》。注:“代行其祭祀。”"}, {"t": "不书即位,摄之。", "b": "《左传·隐公元年》"}, {"t": "摄王位。", "b": "《礼记·明堂位》。疏:“代也。”"}, {"t": "用助祭之服亲迎,摄盛也。", "b": "《仪礼·士昏礼》注"}, {"t": "羊舌鲋摄司马。", "b": "《左传·昭公十三年》"}], "words": [{"w": "摄行", "t": "代理执行"}, {"w": "摄相", "t": "代理宰相"}, {"w": "摄位", "t": "代理君主行事"}, {"w": "摄行", "t": "代人处理职务"}, {"w": "摄祚", "t": "摄政"}, {"w": "摄职", "t": "代理官职"}, {"w": "摄辅", "t": "摄政辅佐"}, {"w": "摄领", "t": "代理"}, {"w": "摄选", "t": "兼任吏部尚书。"}]}, {"meaning": "上台阶时提起长衣。", "cites": [{"t": "予乃摄衣而上。", "b": "苏轼《后赤壁赋》"}], "words": [{"w": "摄齐", "t": "提起衣摆。"}]}, {"meaning": "收敛,聚。", "cites": [{"t": "摄缄縢(绳索),固扃鐍(钥匙),一人之智力,不能胜天下欲得之者之众。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "摄心", "t": "收敛心神"}, {"w": "摄念,摄意", "t": "收敛心神"}, {"w": "摄敛", "t": "聚集"}, {"w": "摄想", "t": "聚精会神地思念。"}]}, {"meaning": "整顿;整理。", "cites": [{"t": "侯生摄敝衣冠,直上载公子上坐。", "b": "《史记·魏公子列传》"}], "words": [{"w": "摄衣", "t": "整饬衣装"}, {"w": "摄衽", "t": "整饬衣襟"}, {"w": "摄袂", "t": "整理衣袖。"}]}, {"meaning": "保养。", "cites": [{"t": "动无死地,而谓之善摄生。", "b": "《韩非子·解老》"}]}, {"meaning": "又如:摄护(保护);摄养(保养;养生)。"}, {"meaning": "借贷。", "cites": [{"t": "冉子摄束帛乘马而将之。", "b": "《礼记·檀弓》"}]}, {"meaning": "夹,箝。", "cites": [{"t": "千乘之国,摄乎大国之间。", "b": "《论语》"}]}, {"meaning": "恐惧,威胁,使慑服。", "cites": [{"t": "不然,则武震以摄威之。", "b": "《左传·襄公十一年》"}, {"t": "时屈时伸,弱柔如薄苇,非摄夺也。", "b": "《淮南子·汜论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2833wx','摸','1','mō','扌','13','','[{"pinyin": "mō", "defs": [{"meaning": "(形声。从手,莫声。本义:用手接触或轻摩物体)。"}, {"meaning": "同本义。", "cites": [{"t": "邕读(曹娥碑),能手摸其文读之。", "b": "《后汉书·蔡邕传》"}], "words": [{"w": "摸脸;摸摸她的手;这衣料摸着很软;摸索", "t": "抚摩,以手接触"}, {"w": "摸挲", "t": "亦作“摸娑”。抚摩"}, {"w": "摸牌", "t": "玩牌。"}]}, {"meaning": "用手探取。", "cites": [{"t": "摸地上刑械。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "摸鱼;从口袋里摸出一把钥匙来", "t": ""}]}, {"meaning": "描摹;模仿;描绘;拓印。", "cites": [{"t": "余少时常有志乎兹事,得国本,绝人事而摸得之。", "b": "唐·韩愈《画记》"}], "words": [{"w": "摸写", "t": "描写,描绘;仿效"}, {"w": "摸拟", "t": "模仿,仿效。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2834wx','填','1','tián zhèn','土','13','','[{"pinyin": "tián", "defs": [{"meaning": "(形声。从土,真声。本义:充塞)。"}, {"meaning": "同本义。", "cites": [{"t": "填,塞也。", "b": "《说文》"}, {"t": "填坑满谷。", "b": "《史记·司马相如传》"}, {"t": "填如也。", "b": "《荀子·大略》"}, {"t": "宾客亦填门。", "b": "《汉书·郑当时传》"}, {"t": "负草填之。", "b": "《资治通鉴》"}, {"t": "门人弟子填其室。", "b": "明·宋濂《送东阳马生序》"}, {"t": "填塞门户。", "b": "《聊斋志异·促织》"}], "words": [{"w": "填馅", "t": "填空;代替"}, {"w": "填引", "t": "加引"}, {"w": "填坑满谷", "t": "塞满坑谷"}, {"w": "填街", "t": "充塞街道"}, {"w": "填咽", "t": "充满空间"}, {"w": "填盈", "t": "充满"}, {"w": "填宫", "t": "古代犯官家属没入宫廷"}, {"w": "填门", "t": "填户。形容登门人多"}, {"w": "填噎", "t": "堵塞,拥挤。"}]}, {"meaning": "填写,写入 。", "words": [{"w": "填纳税表;填报", "t": "填写上报"}, {"w": "填造", "t": "填写编制"}, {"w": "填红", "t": "旧时官员用红笔填写年月日"}, {"w": "填具", "t": "填写具呈"}, {"w": "填画", "t": "填写描画。"}]}, {"meaning": "补充 。", "words": [{"w": "填替", "t": "补充代替"}, {"w": "填纳", "t": "补缴。"}]}, {"meaning": "涂饰,涂抹 。", "words": [{"w": "填金;填白", "t": "在瓷器的深色图案中填月白色瓷"}, {"w": "填漆", "t": ""}]}, {"meaning": "跌落 。", "words": [{"w": "填笮", "t": "颠仆困顿"}, {"w": "填死", "t": "送死"}, {"w": "填仆", "t": "倾跌仆倒。"}]}, {"meaning": "白白 。", "words": [{"w": "填限", "t": "白白作出牺牲"}, {"w": "填送", "t": "把财物白白送人"}, {"w": "填嗓", "t": "把财物白白送人"}, {"w": "填还", "t": "白送;填补。"}]}]}, {"pinyin": "zhèn", "defs": [{"meaning": "安定。", "cites": [{"t": "上患吴、会稽轻悍,无壮王以填之。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2835wx','搏','1','bó','扌','13','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从手,尃(fū)声。本义:搏斗,对打)。"}, {"meaning": "同本义。", "cites": [{"t": "搏,索持也。", "b": "《说文》"}, {"t": "搏,击也。", "b": "《广雅》"}, {"t": "屏左右而相搏。", "b": "《谷梁传·僖公元年》"}, {"t": "晋侯梦与楚子博。", "b": "《左传·僖公二十八年》"}, {"t": "鸷虫攫博。", "b": "《礼记·儒行》。疏:“以脚取之为攫,以翼击之为搏。”"}, {"t": "搏扶摇羊角而上者。", "b": "《庄子·逍遥游》"}, {"t": "搏战获王。", "b": "《史记·卫将军骠骑传》"}, {"t": "以坚毅不挠之精神,与民贼相搏。", "b": "孙文《黄花冈七十二烈士事略序》"}]}, {"meaning": "捕捉。", "cites": [{"t": "搏谍贼。", "b": "《周礼·夏宫·环人》"}], "words": [{"w": "搏执", "t": "拘捕"}, {"w": "搏获", "t": "捕获"}, {"w": "搏撠", "t": "揪住"}, {"w": "搏狩", "t": "狩猎。"}]}, {"meaning": "执持;拾取,击取。", "cites": [{"t": "摭紫贝,搏耆龟。", "b": "张衡《西京赋》"}, {"t": "螳螂执翳而搏之。", "b": "《庄子·山水》"}, {"t": "益习其声,又近出前后,终不敢搏。(扑上去抓。)", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "搏杖", "t": "扶杖,抱杖"}, {"w": "搏弊", "t": "人虽疲困,但也自持完成礼仪。"}]}, {"meaning": "轻击;击。", "cites": [{"t": "搏埴之工二。", "b": "《周礼·总叙》"}, {"t": "弹琴博髀。", "b": "李斯《谏逐客书》"}, {"t": "因搏心大哭。", "b": "《汉书·王莽传下》"}, {"t": "水石相搏。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "搏鸷", "t": "猛烈拍击"}, {"w": "搏膺", "t": "捶胸,表示愤怒"}, {"w": "搏影", "t": "拍击影子。影随物动,故不能拍到。比喻不能成功或不易捉摸。"}]}, {"meaning": "夺取。", "cites": [{"t": "铄金百镒,盗跖不搏。", "b": "《史记·李斯列传》"}], "words": [{"w": "搏斗;搏击", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2836wx','塌','1','tā','土','13','','[{"pinyin": "tā", "defs": [{"meaning": "因凹陷而倒塌。", "cites": [{"t": "塌,堕也。", "b": "《广雅》"}, {"t": "天崩地塌壮士死。", "b": "吴士玉《玉带生歌奉和漫堂先生》"}, {"t": "忽忆雨时秋井塌。", "b": "杜甫《苏端薛复筵简薛华醉歌》"}], "words": [{"w": "塌岸", "t": "朽坏、坍塌的埽岸或堤岸"}, {"w": "房子塌了;倒塌", "t": "建筑物倒下来"}, {"w": "塌翼", "t": ""}]}, {"meaning": "精神委顿 。", "cites": [{"t": "皆垂头塌翼,莫所凭恃。", "b": "陈琳《讨曹操檄文》"}], "words": [{"w": "塌拉", "t": "衣着不整的样子"}, {"w": "塌飒", "t": "不得志;不顺心"}, {"w": "塌趿", "t": "方言。形容目闭失神的样子"}, {"w": "塌然", "t": "哀痛、失意或落陷的样子"}, {"w": "塌塌撒撒", "t": "萎靡不振的样子"}, {"w": "塌翼", "t": "翅膀下垂。比喻失意不得志"}, {"w": "塌飒", "t": "失意消沉的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2837wx','鼓','1','gǔ','鼓','13','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。甲骨文字形,左边是鼓的本字,右边是“支”(pū),表示手持棒槌击鼓。本义:鼓,一种打击乐器)。"}, {"meaning": "同本义。", "cites": [{"t": "鼓,郭也。春分之音。", "b": "《说文》"}, {"t": "鼓,廓也。张皮以冒之,其中空也。", "b": "《释名·释乐器》"}, {"t": "击鼓其镗。", "b": "《诗·邶风·击鼓》"}, {"t": "皮曰鼓。", "b": "《汉书·律历志上》"}, {"t": "抱玉枪兮击鸣鼓。", "b": "《楚辞·屈原·国殇》"}, {"t": "瑜等率轻锐继其后,雷鼓大震。", "b": "宋·司马光《资治通鉴》"}, {"t": "百姓阗王钟鼓之乐。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "鼓面。", "cites": [{"t": "鼓长八尺,鼓四尺,中围加三分之一。", "b": "《周礼》"}]}, {"meaning": "指鼓声。", "cites": [{"t": "可堪回首,佛狸祠下,一片神鸦社鼓。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}]}, {"meaning": "钟磬被敲击之处。", "cites": [{"t": "铣间谓之于,于上谓之鼓。", "b": "《周礼》"}, {"t": "令二人蹲踞而背倚之,漏鼓移则番代。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "四鼓,愬至城下。", "b": "《资治通鉴·唐纪》"}]}, {"meaning": "古国名。春秋时鼓国,在今河北省晋县,白狄的一支,为晋国所灭。"}, {"meaning": "古代量器名。四钧为石,四石为鼓。", "cites": [{"t": "献米者操量鼓。", "b": "《礼记》"}]}, {"meaning": "击鼓进攻。", "cites": [{"t": "鼓,击鼓也。", "b": "《说文》"}, {"t": "公将鼓之。", "b": "《左传·庄公十年》"}, {"t": "子有钟鼓,弗鼓弗考。", "b": "《诗·唐风·山有枢》"}, {"t": "夫战,勇气也。一鼓作气,再而衰;三而竭。", "b": "《左传·庄公十年》"}], "words": [{"w": "鼓行", "t": "古代作战时,击鼓进兵,鸣钲则止,故称行进为鼓行"}, {"w": "鼓险", "t": "乘敌军陷入险地时,击鼓攻击。"}]}, {"meaning": "泛指敲击, 弹奏。", "cites": [{"t": "吾王之好鼓乐,夫何使我至于此极也!", "b": "《孟子·梁惠王上》"}, {"t": "虎鼓瑟兮鸾回车,仙之人兮列如麻。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "鼓腹讴歌", "t": "拍着肚皮唱歌。表示吃得饱而歌颂世道好"}, {"w": "鼓腹含哺", "t": "口含食物,手拍肚子。形容饱食终日、无所用心的安乐生活"}, {"w": "鼓缶", "t": "击缶。"}]}, {"meaning": "挥动。", "cites": [{"t": "臣乃市井鼓刀屠者。", "b": "《史记·魏公子列传》"}], "words": [{"w": "鼓刀", "t": "挥动屠刀,杀牲割肉。"}]}, {"meaning": "拍打;振动。", "cites": [{"t": "郦元以为下临深潭,微风鼓浪,水石相搏,声如洪钟。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "鼓翼", "t": "振翅而飞"}, {"w": "鼓掌", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2838wx','摆','1','bǎi','扌','13','','[{"pinyin": "bǎi", "defs": [{"meaning": "(形声。从手,罢声。本义:撇开;摆脱)。"}, {"meaning": "同本义。", "cites": [{"t": "何当摆俗累,浩荡乘沧溟?", "b": "杜甫《桥陵》"}], "words": [{"w": "摆落", "t": "摆脱。"}]}, {"meaning": "排列;放置。", "cites": [{"t": "说话时,已摆了茶果子来。", "b": "《红楼梦》"}], "words": [{"w": "摆正", "t": "摆放端正"}, {"w": "摆八卦阵;摆酒席", "t": ""}]}, {"meaning": "挥手,左右摇动手。", "cites": [{"t": "…把手一摆,意思是请兄弟在阶沿上坐下。", "b": "鲁迅《故事新编》"}], "words": [{"w": "摆手", "t": "挥手。"}]}, {"meaning": "来回或上下地摇动。", "cites": [{"t": "旋见鸡伸颈摆扑。", "b": "《聊斋志异·促织》"}, {"t": "天坼地裂,宫殿摆簸。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "摆尾巴;摆簸", "t": "摇晃颠簸"}, {"w": "摇摆", "t": "向相反的方向来回地移动或变动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2839wx','携','1','xié','扌','13','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从手,隽(jùn)声。本义:提着)。"}, {"meaning": "同本义(把地上的物品举提起来)。", "cites": [{"t": "携,提也。", "b": "《说文》"}, {"t": "如璋如圭,如取如携。", "b": "《诗·大雅·板》"}], "words": [{"w": "携壶;携带", "t": "提挈,照顾"}, {"w": "携酒牵羊;携杖", "t": ""}]}, {"meaning": "拿着,持。", "cites": [{"t": "闲携杖,漫出门,官槐满路叶纷纷。", "b": "清·孔尚任《桃花扇》"}], "words": [{"w": "携盘;携帚", "t": ""}]}, {"meaning": "牵挽;挽扶。", "cites": [{"t": "相携于道。", "b": "《淮南子·览冥》"}, {"t": "吾与汝并肩携手。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "携抱", "t": "牵挽扶抱"}, {"w": "携率", "t": "率领"}, {"w": "携将", "t": "扶持"}, {"w": "相携于道;携幼扶老;携扶;携负", "t": "牵背。"}]}, {"meaning": "带,随身一道。", "cites": [{"t": "携其妻子。", "b": "《公羊传·襄公二十七年》"}, {"t": "于是夫负妇戴,携子入于海。", "b": "《庄子·让王》"}, {"t": "民扶老携幼。", "b": "《战国策·齐策四》"}, {"t": "携幼入室。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "携童几数人。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "携子同行;携女归宁;携行;携家眷同行;携款潜逃;携械投诚", "t": ""}]}, {"meaning": "离;背离;离散。", "cites": [{"t": "招携以礼,怀远以德。", "b": "《左传·僖公七年》"}, {"t": "不如私许复曹,卫以以携之。", "b": "《左传·僖公二十八年》"}, {"t": "其刑矫诬,百姓携贰。", "b": "《国语·周语上》"}, {"t": "须要宣布皇灵,携其党羽,则王直势孤,自不能容。", "b": "《西湖二集》"}], "words": [{"w": "携爽", "t": "背离"}, {"w": "携弛", "t": "有二心而松懈"}, {"w": "携泮", "t": "离散"}, {"w": "携贰", "t": "有二心,叛离"}, {"w": "携背", "t": "背离,背叛"}, {"w": "携叛", "t": "背叛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2840wx','搬','1','bān','扌','13','','[{"pinyin": "bān", "defs": [{"meaning": "(形声。从手,般声。本义:挪动)。"}, {"meaning": "同本义。", "cites": [{"t": "师见僧搬土次,乃以一块土放僧担上。", "b": "《五灯会元·文益禅师》"}], "words": [{"w": "搬起石头打自己的脚;把货物搬走;他早就搬走了;搬场", "t": "迁居。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2841wx','摇','1','yáo','扌','13','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。从手,本义:摇动;摆动)。"}, {"meaning": "同本义。", "cites": [{"t": "摇,动也。", "b": "《说文》"}, {"t": "摇,作也。", "b": "《尔雅》"}, {"t": "摇者不定。", "b": "《管子·心术》"}, {"t": "复命摇作。", "b": "《庄子·则阳》"}, {"t": "夹而摇之。", "b": "《考工记·矢人》"}, {"t": "四顾何茫茫,东风摇百草。", "b": "《古诗十九首》"}, {"t": "蒙络摇缀。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "痒不得搔,痹不得摇。", "b": "柳宗元《断刑论》"}, {"t": "摇头而歌。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "动摇承之。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "摇旗打鼓", "t": "四处张扬,闹得满城风雨"}, {"w": "摇铃打鼓", "t": "摇旗打鼓"}, {"w": "摇颭", "t": "摇摆颤动。形容女人走路的妖娆姿态"}, {"w": "摇风", "t": "谓风吹摆动"}, {"w": "摇摆气势", "t": "摇头摆尾,虚张声势"}, {"w": "摇席破座", "t": "兴奋得坐不安移"}, {"w": "摇唇鼓舌", "t": "凭借能言善辩而游说煽动。"}]}, {"meaning": "动摇。", "cites": [{"t": "本根一摇,忧患非浅。", "b": "《新唐书·狄仁杰传》"}], "words": [{"w": "摇心", "t": "人心动摇"}, {"w": "摇易", "t": "动摇更易"}, {"w": "摇悦", "t": "一会儿动摇,一会儿喜悦的矛盾心理。"}]}, {"meaning": "疾。", "cites": [{"t": "摇,疾也。", "b": "《广雅》"}, {"t": "将摇举,谁与期。", "b": "《汉书·礼乐志》"}, {"t": "遂乃风举云摇,浮游溥览。", "b": "汉·班固《西都赋》"}], "words": [{"w": "摇举", "t": "腾升高举。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2842wx','搞','1','gǎo','扌','13','','[{"pinyin": "gǎo", "defs": [{"meaning": "((gǎo)形声。从手,高声。本义:做,干,办,弄)。"}, {"meaning": "同本义。", "cites": [{"t": "你们这里的事我搞不来,你们不是革命,是胡闹。", "b": "《潘虎》"}], "words": [{"w": "搞得不坏;搞价", "t": "商议价钱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2843wx','塘','1','táng','土','13','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从土,唐声。本义:堤岸)。"}, {"meaning": "同本义。", "cites": [{"t": "池塘生春草。", "b": "谢灵运《登池上楼》"}], "words": [{"w": "塘岸", "t": "堤岸"}, {"w": "塘埝,塘埭", "t": "塘坝"}, {"w": "塘堰", "t": "小型蓄水工程。现指塘坝"}, {"w": "塘坟", "t": "近海盐区无山地,盐民死后在海堤下掘一缺口将棺材埋入"}, {"w": "塘丁税", "t": "水利税。"}]}, {"meaning": "方形水池  中古时圆的叫池,方的叫塘。", "cites": [{"t": "下者飘转沉塘坳。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "蝉声集古寺,鸟影度寒塘。", "b": "杜甫《和裴迪登新津寺》"}], "words": [{"w": "塘池", "t": "池塘"}, {"w": "泥塘", "t": "烂泥淤积的洼地"}, {"w": "苇塘;塘坳", "t": "池塘;低洼地"}, {"w": "塘泥", "t": ""}]}, {"meaning": "小坑 。如:火塘。又特指点播旱地作物的窝子。如:打塘点播;包谷一塘也没有点下去。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2844wx','摊','1','tān','扌','13','','[{"pinyin": "tān", "defs": [{"meaning": "(形声。从手,难声。本义:平铺)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2845wx','聘','1','pìn','耳','13','','[{"pinyin": "pìn", "defs": [{"meaning": "(形声。从耳,甹(pīng)声。探问消息要靠耳朵,故从“耳”。本义:访问,探问)。"}, {"meaning": "同本义。", "cites": [{"t": "聘,访也。", "b": "《说文》"}, {"t": "聘,问也。", "b": "《尔雅》"}, {"t": "靡使归聘。", "b": "《诗·小雅·采薇》"}, {"t": "季冬聘王梦。", "b": "《周礼·占梦》"}, {"t": "聘申叔于陈蔡兮。", "b": "《后汉书·冯衍传》"}, {"t": "诸侯使大夫问于诸侯曰聘。", "b": "《礼记·曲礼》"}, {"t": "凡诸侯之邦交岁相问也,殷相聘也。", "b": "《周礼·大行人》"}], "words": [{"w": "聘弓", "t": "古代聘问时持用之弓"}, {"w": "聘贡", "t": "聘问朝贡"}, {"w": "聘享", "t": "聘问献纳"}, {"w": "聘使", "t": "奉命聘问。"}]}, {"meaning": "旧时称订婚、迎娶之礼。", "cites": [{"t": "聘则为妻。", "b": "《礼记·内则》"}], "words": [{"w": "聘定", "t": "犹婚约。"}]}, {"meaning": "女子订婚或出嫁。", "cites": [{"t": "声伯之母不聘。", "b": "《左传·成公十一年》"}], "words": [{"w": "聘嫁", "t": "出嫁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2846wx','斟','1','zhēn','斗','13','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从斗,甚声。本义:用勺子舀取)。"}, {"meaning": "同本义。", "cites": [{"t": "斟,勺也。", "b": "《说文》"}, {"t": "斟,酌也。", "b": "《广雅》"}, {"t": "孔子穷乎陈蔡之间,藜羹不斟,七日不尝粒。", "b": "《吕氏春秋》"}, {"t": "太行何艰哉,北斗不可斟。", "b": "唐·顾况《游子吟》"}, {"t": "其御羊斟不与。", "b": "《左传·宣公二年》"}, {"t": "羊羹不斟,而宋国危。", "b": "《淮南子·鏐称》"}]}, {"meaning": "用壶倒酒或茶水。", "cites": [{"t": "主人有酒且莫斟,听我一曲悲来吟。", "b": "唐·李白《悲歌行》"}], "words": [{"w": "斟酒;斟一杯水;斟泻", "t": "倾注"}, {"w": "斟茶;给她斟一杯酒", "t": ""}]}, {"meaning": "考虑,考虑好坏,比较长短。", "cites": [{"t": "斟量功伐。", "b": "《颜氏家训·省事》"}], "words": [{"w": "斟酌损益", "t": "仔细考虑,反复商讨,以决定增减、兴革"}, {"w": "斟勺", "t": "考虑,吸取"}, {"w": "斟裁", "t": "斟酌决定"}, {"w": "斟量", "t": "酌量;估量。"}]}, {"meaning": "汤汁,羹汁。", "cites": [{"t": "斟,汁也。", "b": "《方言三》"}, {"t": "厨人进斟,因反斗以击代王,杀之。", "b": "《史记·张仪列传》"}]}, {"meaning": "古国名 。相传为夏同姓诸侯之国。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2847wx','蒜','1','suàn','艹','13','','[{"pinyin": "suàn", "defs": [{"meaning": "(形声。从艸,祘(suàn)声。本义:一种多年生草本植物。有大蒜、小蒜两种)。"}, {"meaning": "同本义 。百合科,多年生宿根草本。地下鳞茎有白皮包裹,内有小鳞茎,叫“蒜瓣”。根椐蒜瓣的大小分大瓣种和小瓣种。大蒜种西汉时从西域传入。小蒜种由山蒜移栽,从古已有。蒜苗、蒜苔作蔬菜,蒜头作佐料和入药。", "cites": [{"t": "蒜,荤菜也。", "b": "《说文》"}, {"t": "蒜,菜之美者", "b": "《齐民要术》引《说文》"}], "words": [{"w": "蒜果", "t": "蒜头"}, {"w": "蒜气", "t": "腋下的气味。即狐臭"}, {"w": "蒜锤子", "t": "禅杖柄上所装蒜头状的锤"}, {"w": "蒜条", "t": "即蒜苗。蒜的花茎;亦指细长而形似蒜苗者。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2848wx','勤','1','qín','力','13','','[{"pinyin": "qín", "defs": [{"meaning": "(形声。右形,左声。本义:劳累,劳苦)。"}, {"meaning": "尽力多做,不断地做。", "cites": [{"t": "勤,劳也。", "b": "《说文》"}, {"t": "文王既勤止。", "b": "《诗·周颂·赍》"}, {"t": "勤者,有事则收之。", "b": "《礼记·玉藻》。注:“执劳辱之事也。”"}, {"t": "厥父母勤劳稼穑。", "b": "《书·天逸》"}, {"t": "何勤子屠母,而死兮竟地?", "b": "《楚辞·天问》"}, {"t": "会数而礼勤。", "b": "宋·司马光《训俭示康》"}, {"t": "勤且艰若此。", "b": "明·宋濂《送东阳马生序》"}, {"t": "忧勤国事。", "b": "《明史》"}, {"t": "好学而不勤问。", "b": "《国语·晋语》"}, {"t": "四体不勤。", "b": "《论语·微子》"}, {"t": "勤而无所。", "b": "《左传·僖公三十二年》"}, {"t": "以贪勤民。", "b": ""}, {"t": "昼夜勤作息。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "勤力得", "t": "勤劳的人"}, {"w": "勤儿", "t": "能手"}, {"w": "勤紧", "t": "勤劳"}, {"w": "勤学", "t": "努力学习"}, {"w": "勤勤", "t": "劳苦的样子"}, {"w": "勤能", "t": "勤勉而又有才能。"}]}, {"meaning": "为某人某事尽力;帮助。", "cites": [{"t": "秦人勤我也。", "b": "《国语·晋语》"}, {"t": "今君其不勤民。", "b": "《左传·僖公二十八年》。注:“尽心尽力,无所爱惜为勤。”"}, {"t": "勤天子之难。", "b": "《吕氏春秋·不广》"}], "words": [{"w": "勤民", "t": "尽心尽力于民事"}, {"w": "勤事", "t": "尽心尽力于职事。"}]}, {"meaning": "竭,完。", "cites": [{"t": "绵绵若存,用之不勤。", "b": "《老子·六章》"}, {"t": "力勤则匮。", "b": "《淮南子·主术》"}]}, {"meaning": "劳倦,辛苦。", "cites": [{"t": "或问民听勤。", "b": "《法言·先知》。注:“苦也。”"}, {"t": "万民多有勤苦冻馁。", "b": "《墨子·兼爱下》"}], "words": [{"w": "勤心苦胝", "t": "辛苦劳作"}, {"w": "勤动", "t": "辛勤劳动"}, {"w": "勤辱", "t": "辛勤。"}]}, {"meaning": "次数多,经常。", "cites": [{"t": "愿得勤来看,无令便逐风。", "b": "唐·韩愈《木芙蓉》"}], "words": [{"w": "勤洗澡;他来得很勤", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2849wx','靴','1','xuē','革','13','','[{"pinyin": "xuē", "defs": [{"meaning": "(形声。从革,化声。革,皮革。本义:高到踝骨以上的长筒鞋) 同本义。", "cites": [{"t": "尝有人著靴骑驴,至兆门外。", "b": "《晋书》"}], "words": [{"w": "靴叶子", "t": "塞藏在靴筒内可折叠的票夹"}, {"w": "靴桶", "t": "靴靿。靴筒"}, {"w": "靴衫", "t": "乘马时所穿的衣服"}, {"w": "靴袍", "t": "穿靴时所服的官袍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2850wx','靶','1','bǎ bà','革','13','','[{"pinyin": "bǎ", "defs": [{"meaning": "练习射箭或射击用的目标", "words": [{"w": "靶场", "t": "练习射击(如用弓、枪炮或导弹)的场地"}]}, {"meaning": "供加速器、原子核反应堆、放射性源等发出的粒子流轰击的实物样品，用以研究核反应，获得放射性同位素或产生Ｘ射线等。"}]}, {"pinyin": "bà", "defs": [{"meaning": "(形声。从革,巴声。从“革”,表示与皮革有关。本义:辔首垂下部,即辔革)。"}, {"meaning": "同本义。", "cites": [{"t": "靶,辔革也。", "b": "《说文》。按,辔首车。"}]}, {"meaning": "缰绳。", "cites": [{"t": "王良执靶。", "b": "《汉书·王褒传》"}]}, {"meaning": "刀剑等物的柄", "cites": [{"t": "又有以骨为九子靶者,五色斑烂。", "b": "《北齐书·徐之才传》"}], "words": [{"w": "靶儿镜子", "t": "有柄可以拿在手里的镜子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2851wx','鹊','1','què','鸟','13','','[{"pinyin": "què", "defs": [{"meaning": "(形声。从鸟,昔声。字本从隹,隶变作鸟。见《说文》“舃”字注。本义:喜鹊)。"}, {"meaning": "同本义。", "cites": [{"t": "维鹊有巢,维鸠居之。", "b": "《诗·召南·鹊巢》"}, {"t": "鹊始巢。", "b": "《礼记·月令·季冬》"}, {"t": "明月别枝惊鹊。", "b": "宋·辛弃疾《西江月》诗"}]}, {"meaning": "鸦科的鹊属和若干其他属的许多鸟之一,它与松鸦亲缘关系密切,但有一长而分等级的尾,体羽通常为黑色和白色。", "cites": [{"t": "维鹊有巢,维鸠居之。", "b": "《诗·召南》"}], "words": [{"w": "红嘴蓝鹊;鹊音", "t": "好消息"}, {"w": "鹊报", "t": "喜鹊报喜。旧俗以闻鹊声为喜兆"}, {"w": "鹊噪", "t": "鹊声喧闹。旧俗认为是一种喜兆"}, {"w": "鹊喜", "t": "鹊噪报喜。旧俗以鹊噪为喜兆。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2852wx','蓝','1','lán','艹','13','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从艸,监声。本义:蓼蓝)。"}, {"meaning": "同本义 。蓼科一年生草本植物。叶形似蓼而味不辛,干后变暗蓝色,可加工成靛青,作染料。叶也供药用。又泛指叶含蓝汁可制蓝靛作染料的植物。", "cites": [{"t": "蓝,染青草也。", "b": "《说文》"}, {"t": "终朝采蓝。", "b": "《诗·小雅·采绿"}, {"t": "青,取之于蓝而青于蓝。", "b": "《荀子·劝学》"}, {"t": "春来江水绿如蓝。", "b": "唐·白居易《忆江南》"}], "words": [{"w": "木蓝、菘蓝、马蓝等", "t": ""}]}, {"meaning": "佛寺。梵语伽蓝的简称。", "cites": [{"t": "宝刹名蓝之外,又家供养佛堂。", "b": "清·阮元《小沧浪笔谈》"}]}, {"meaning": "颜色的一种。像晴天天空的颜色。", "cites": [{"t": "秋鳸窃蓝。", "b": "《尔雅·释鸟》。注:“青也。”"}, {"t": "上有蔚蓝天。", "b": "杜甫《冬到金华山观》"}, {"t": "以蓝手巾裹头。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "蓝郁郁", "t": "蓝蓝"}, {"w": "蓝榜", "t": "乡会试时,只要答卷不合规定,或者有了污损,就把它用蓝笔写出,截角张榜公布,并取消该考生的考试资格"}, {"w": "蓝湛湛", "t": "形容极蓝。"}]}, {"meaning": "假借为“褴”。衣服破烂。", "cites": [{"t": "筚路蓝缕。", "b": "《左传·宣公十二年》"}], "words": [{"w": "蓝蓝", "t": "衣服破旧的样子"}, {"w": "蓝蒌", "t": "形容衣服破旧。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2853wx','墓','1','mù','土','13','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从土,莫声。本义:上古时期凡掘塘穴葬棺木,盖土与堆平,不植树者称墓。泛指坟墓)。"}, {"meaning": "同本义。后不加区别,统称作墓。", "cites": [{"t": "墓,丘也。", "b": "《说文》"}, {"t": "墓,冢也。", "b": "《广雅》"}, {"t": "墓,土也。", "b": "《论衡·讥日》"}, {"t": "冢茔之地。", "b": "《周礼·墓大夫》注"}, {"t": "适墓不登垄。", "b": "《礼记·曲礼》"}, {"t": "古也墓而不坟。", "b": "《礼记·檀弓》。注:“墓谓兆域,今之封茔也。”"}, {"t": "古墓犁为田,松柏摧为薪。", "b": "《古诗十九首》"}, {"t": "古也墓而不坟。", "b": "《礼记·檀弓上》"}, {"t": "且立石于墓之门,以旌其所为。", "b": "张溥《五人墓碑记》"}], "words": [{"w": "墓庐", "t": "墓旁的房屋"}, {"w": "墓隧", "t": "墓前或墓室前的甬道"}, {"w": "墓堂", "t": "坟墓前的祭堂"}, {"w": "墓庭", "t": "坟墓周围的庭院。"}]}, {"meaning": "葬。", "cites": [{"t": "因以宜阳郭为墓。", "b": "《战国策·秦策》。注:“葬也。”"}, {"t": "去今之墓而葬焉。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "墓穴", "t": "埋棺材的坑穴"}, {"w": "墓俑", "t": "殉葬用的偶像。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2854wx','幕','1','mù','巾','13','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从巾,莫声。本义:覆布,帐篷的顶布)。"}, {"meaning": "同本义。", "cites": [{"t": "幕,帷在上曰幕。", "b": "《说文》"}, {"t": "舞于鲁君之幕下。", "b": "《谷梁传·定公十年》"}, {"t": "楚幕有乌。", "b": "《左传·庄公二十八年》"}, {"t": "夫子之在此也,犹燕之巢于幕上。", "b": "《左传·襄公二十九年》"}, {"t": "举袂成幕。(袂:mèi:袖子)", "b": "《战国策·齐策一》"}], "words": [{"w": "幕幕", "t": "覆布周密的样子"}, {"w": "幕燕", "t": "筑巢于幕上的燕子"}, {"w": "幕下", "t": "帐幕之下;幕府中。"}]}, {"meaning": "帐幕;篷帐。", "cites": [{"t": "风动将军幕。", "b": "杜甫《西山》"}, {"t": "平沙列万幕,部伍各见招。", "b": "杜甫《后出塞》"}], "words": [{"w": "幕庭", "t": "营帐前的空地"}, {"w": "幕帷", "t": "帐幕"}, {"w": "幕席", "t": "帐幕和座席;幕宾的职位"}, {"w": "幕竿", "t": "张帐幕用的长竿。"}]}, {"meaning": "垂挂的帘幕。", "cites": [{"t": "文窗绣户盘绮幕。", "b": "鲍照《拟行路难十八首·三》"}]}, {"meaning": "假借为“漠”。沙漠。", "cites": [{"t": "常以为汉兵不能度幕轻留。", "b": "《史记·卫将军骠骑列传》"}, {"t": "比年遣大将军卫青、霍去病攻祁连绝大幕。", "b": "《汉书·五行志中之下》"}]}, {"meaning": "覆盖。", "cites": [{"t": "雪幕其顶。", "b": "《徐霞客游记·滇游日记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2855wx','蓬','1','péng','艹','13','','[{"pinyin": "péng", "defs": [{"meaning": "(形声。从艸,逢声。本义:草名。蓬蒿)。"}, {"meaning": "同本义。", "cites": [{"t": "蓬,蒿也。", "b": "《说文》"}, {"t": "彼茁者蓬。", "b": "《诗·召南·驺虞》"}, {"t": "桑蓬矢六。", "b": "《礼记·内则》"}, {"t": "若纵火于秋蓬。", "b": "《楚辞·沈江》。注:“蒿也。”"}, {"t": "飘萍浮而蓬转。", "b": "潘岳《西征赋》?"}]}, {"meaning": "某些植物果实的外苞。", "cites": [{"t": "乃复蒂下生蓬,蓬中结实,亭亭独立,犹似未开之花", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "莲蓬", "t": ""}]}, {"meaning": "散乱。", "cites": [{"t": "蓬头突须。", "b": "《庄子·说剑》"}, {"t": "西王母蓬发。", "b": "《西山经·玉山》"}], "words": [{"w": "蓬首", "t": "头发散乱像飞蓬一样"}, {"w": "蓬葆", "t": "蓬草和羽葆。比喻头发散乱"}, {"w": "蓬乱", "t": "形容须发或草木凌乱"}, {"w": "蓬发", "t": "蓬松、散乱的头发"}, {"w": "蓬鬓", "t": "鬓发蓬乱。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2856wx','蓄','1','xù','艹','13','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从艸,畜声。本义:积聚,储藏)。"}, {"meaning": "同本义。", "cites": [{"t": "蓄,积也。", "b": "《说文》"}, {"t": "蓄,聚也。", "b": "《广雅》"}, {"t": "我有旨蓄,亦以御冬。", "b": "《诗·邶风·谷风》"}, {"t": "洪恩素蓄。", "b": "张衡《东京赋》"}, {"t": "蓄积者,天下之太命也。", "b": "《贾子·无蓄》"}, {"t": "无三年之蓄。", "b": "《礼记·王制》"}, {"t": "蓄积索,田畴荒。", "b": "《韩非子·初见秦》"}, {"t": "积货滋多,蓄怨滋厚。", "b": "《国语·楚语下》"}, {"t": "将军蓄米,将疗饥乎;将破敌乎?", "b": "《新五代史》"}], "words": [{"w": "蓄火", "t": "蓄留火种"}, {"w": "蓄菜", "t": "把蔬菜制成菜干、咸菜等加以储藏。也指菜干,咸菜等"}, {"w": "蓄余", "t": "储蓄节余的财物"}, {"w": "蓄毓", "t": "储积培育"}, {"w": "蓄租", "t": "积聚"}, {"w": "蓄艾", "t": "本指蓄藏多年之艾以治久病,后比喻应长期积蓄以备急用。"}]}, {"meaning": "畜养。", "cites": [{"t": "使得植桑麻、蓄鸡豚,以为岁时伏腊婚嫁之资。", "b": "《美芹十论》"}, {"t": "视成所蓄。", "b": "《聊斋志异·促织》"}, {"t": "蓄劣物。", "b": ""}], "words": [{"w": "蓄内", "t": "蓄养内人"}, {"w": "蓄私", "t": "蓄养妾媵私人。"}]}, {"meaning": "等待。", "cites": [{"t": "盍远迹以飞声兮,孰谓时之可蓄?", "b": "《后汉书》"}]}, {"meaning": "积蓄。", "cites": [{"t": "国无九年之蓄曰不足,无六年之蓄曰急。", "b": "《礼记》"}], "words": [{"w": "私蓄;余蓄", "t": ""}]}, {"meaning": "冬菜,用白菜或芥菜叶做成的干菜。", "cites": [{"t": "芳菰精粺,霜蓄露葵。", "b": "《文选·曹植"}, {"t": "七启", "b": ""}]}, {"meaning": "》。张铣注:“蓄,菜名。此物与葵,宜于霜露之时。”。", "words": [{"w": "蓄菜", "t": "指菜干、咸菜等。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2857wx','蒲','1','pú','艹','13','','[{"pinyin": "pú", "defs": [{"meaning": "(形声。从水丱,浦声。本义:植物名。香蒲)。"}, {"meaning": "同本义。", "cites": [{"t": "蒲,水草也。可以作席。", "b": "《说文》"}, {"t": "有蒲与荷。", "b": "《诗·陈风·泽陂》"}, {"t": "共其苇蒲之事。", "b": "《周礼·泽虞》。注:“以为席。”"}, {"t": "男执蒲璧。", "b": "《周礼·大宗伯》。注:“蒲为席,所以安人。”"}], "words": [{"w": "蒲甸儿", "t": "亦作“蒲垫”。用蒲草编的坐垫"}, {"w": "蒲柳", "t": "比喻身微低贱"}, {"w": "蒲草毛窝", "t": "一种用蒲草编成的深帮圆底鞋子,里面杂有鸡毛、芦花等物"}, {"w": "蒲鞭示辱", "t": "以薄为鞭,薄罚示耻"}, {"w": "蒲帆", "t": "用蒲叶编成的船帆。"}]}, {"meaning": "即今人所称“水杨”。也称“蒲杨”、“蒲柳”。", "cites": [{"t": "不流束蒲。", "b": "《诗·王风·扬之水》"}], "words": [{"w": "蒲柳", "t": "植物名,即水杨。质性柔弱且又树叶早落,所以用来比喻衰弱的体质"}, {"w": "蒲姿", "t": "蒲柳之姿"}, {"w": "蒲杨", "t": "蒲柳。"}]}, {"meaning": "古邑名。"}, {"meaning": "春秋卫地,战国属魏。在今河南省长垣县。"}, {"meaning": "春秋晋地,在今山西省隰县西北。"}, {"meaning": "伏地而行。", "cites": [{"t": "奉壶饮冰以蒲伏焉。", "b": "《左传·昭公十三年》"}], "words": [{"w": "蒲伏", "t": "匍匐。伏地而行"}, {"w": "蒲服", "t": "蒲伏,伏地膝行"}, {"w": "蒲望", "t": "蒲伏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2858wx','蓉','1','róng','艹','13','','[{"pinyin": "róng", "defs": [{"meaning": "四川成都市的简称 。五代后蜀孟昶于宫苑城上遍植木芙蓉,因名成都为芙蓉城,后简称蓉城或蓉。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2859wx','蒙','1','mēng méng měng','艹','13','','[{"pinyin": "mēng", "defs": [{"meaning": "欺骗或哄骗", "words": [{"w": "蒙骗", "t": "欺骗"}]}, {"meaning": "胡乱猜测"}, {"meaning": "昏迷,暂时失去知觉的"}]}, {"pinyin": "méng", "defs": [{"meaning": "(形声。从艸,冡(méng)声。本义:草名)。"}, {"meaning": "草名。即菟丝 。旋花科。一年生缠绕寄生草本。茎很细,呈丝状,黄白色,随处生有吸盘,附着在豆科、菊科、藜科等植物上。叶退化,开白色小花。种子入药。"}, {"meaning": "云气。", "cites": [{"t": "秋天虽是昼夜停匀时候,究竟日出日入,有蒙气传光,还觉得夜是短的。", "b": "《老残游记》"}], "words": [{"w": "蒙气传光", "t": "日出之前与刚落之后,光线虽不能直接照射大地,地上仍相当明亮,这是因为空中大气的折光作用所致"}, {"w": "蒙气", "t": "古指包围地球外面的大气。"}]}, {"meaning": "遮蔽;覆盖。", "cites": [{"t": "葛生蒙楚。", "b": "《诗·唐风·葛生》"}, {"t": "以幕蒙之。", "b": "《左传·昭公十三年》"}, {"t": "蒙络摇缀。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "时蒙卷轴。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "蒙络", "t": "掩盖缠绕"}, {"w": "蒙翳", "t": "掩蔽,覆盖"}, {"w": "蒙覆", "t": "覆盖;掩蔽"}, {"w": "蒙幕", "t": "覆盖"}, {"w": "蒙袂", "t": "用袖子蒙住脸。谓不愿见人。"}]}, {"meaning": "欺骗,隐瞒。", "cites": [{"t": "上下相蒙。", "b": "《左传·僖公二十四年》"}], "words": [{"w": "蒙事", "t": "方言。作假骗人"}, {"w": "蒙混", "t": "用欺骗手段使人相信虚假的事物"}, {"w": "蒙骗", "t": "欺骗"}, {"w": "蒙哄", "t": "用虚伪的手段欺骗别人。"}]}, {"meaning": "承继,继承。", "cites": [{"t": "汝之纯明而不克蒙其泽乎?", "b": "韩愈《祭十二郎文》"}, {"t": "孝公既没,惠文、武、昭襄,蒙故业,因遗策(承接已有的基业,沿袭前代的策略)。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "蒙受。", "cites": [{"t": "以蒙大难。", "b": "《易·明夷》。郑注:“遭也。”"}, {"t": "寻蒙国恩,除臣洗马。", "b": "李密《陈情表》"}, {"t": "蒙其赏赐。", "b": "东汉·班固《汉书·李广苏建传》"}], "words": [{"w": "幸蒙大恩;蒙斧铖汤镬;蒙羞", "t": "蒙受耻辱"}, {"w": "蒙辜", "t": "受罪"}, {"w": "蒙泽", "t": "蒙受恩泽"}, {"w": "蒙难", "t": "遭受灾难。"}]}, {"meaning": "敬词。承蒙。", "cites": [{"t": "昨日蒙教。", "b": "宋·王安石《答司马谏议书》"}, {"t": "过蒙拔擢,岂敢盘桓。", "b": "李密《陈情表》"}], "words": [{"w": "不蒙见察;蒙君实视遇;蒙幸", "t": "犹幸蒙,幸运地受到"}, {"w": "蒙恩", "t": "承蒙恩惠"}, {"w": "蒙允", "t": "承蒙允许"}, {"w": "蒙教", "t": "承蒙教诲。"}]}, {"meaning": "迷茫,广阔而看不清。弥漫笼罩", "words": [{"w": "蒙晦", "t": "迷茫昏暗貌"}]}, {"meaning": "幼稚,暗昧不明。", "cites": [{"t": "匪我求童蒙,童蒙求我。", "b": "《易·蒙》"}], "words": [{"w": "蒙士", "t": "蒙昧无知,学识浅薄的人"}, {"w": "蒙幼", "t": "不懂事的幼童"}, {"w": "蒙师", "t": "启蒙的老师,教育孩童的老师。"}]}, {"meaning": "阴暗。", "cites": [{"t": "曰蒙,恒风若。", "b": "《书·洪范》。传:“蒙,阴暗也。”"}]}, {"meaning": "引申为蒙昧无知。", "cites": [{"t": "民非蒙愚也。", "b": "《战国策·韩策》"}], "words": [{"w": "蒙陋", "t": "蒙昧浅陋"}, {"w": "蒙士", "t": "浅学无知之士"}, {"w": "蒙迷", "t": "犹蒙昧。"}]}, {"meaning": "自称谦词。犹愚。", "cites": [{"t": "蒙之所见,及此而已。", "b": "柳宗元《答元饶州论政理书》"}], "words": [{"w": "蒙拾", "t": "学识不高的人拾取前人文词缀连成章,不敢自言创作,便称蒙拾。"}]}, {"meaning": "盲,目失明。", "cites": [{"t": "循蒙招尤。", "b": "《素问·五藏生成篇》"}]}, {"meaning": "细雨的样子。", "cites": [{"t": "我来自东,零雨其濛。", "b": "《诗·豳风·东山》"}], "words": [{"w": "蒙雨", "t": "毛毛细雨"}, {"w": "蒙蒙松松", "t": "细雨迷茫的样子。"}]}, {"meaning": "广大 。"}, {"meaning": "弥漫,笼罩。", "cites": [{"t": "但见愁云漠漠,惨雾濛濛。", "b": "《三国演义》"}], "words": [{"w": "蒙昧", "t": "迷茫,昏暗"}, {"w": "蒙漠", "t": "迷茫昏暗。"}]}, {"meaning": "古水名。"}, {"meaning": "沱江支流。在四川省彭县境。"}, {"meaning": "即蒙江。在今广西梧州。"}, {"meaning": "忠厚的样子。", "cites": [{"t": "那呆子虽是心性愚顽,却只是一味蒙直。", "b": "《西游记》"}], "words": [{"w": "蒙直", "t": "忠厚老实。"}]}]}, {"pinyin": "měng", "defs": [{"meaning": "蒙古", "words": [{"w": "蒙古族", "t": "中国少数民族之一"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2860wx','蒸','1','zhēng','艹','13','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。烝声。本义:麻秆)。"}, {"meaning": "同本义。", "cites": [{"t": "蒸,析麻中干也。", "b": "《说文》。今俗谓之麻骨棓,古烛用之,故凡用麻干葭苇竹木为烛皆曰蒸。"}, {"t": "蒸,炬也。", "b": "《广雅》"}, {"t": "故云烛用蒸也。", "b": "《仪礼》疏"}]}, {"meaning": "细小的木柴。", "cites": [{"t": "共祭祀之薪蒸材木。", "b": "《周礼·委人》。注:“给炊及燎,粗者曰薪,细者曰蒸。”"}, {"t": "蒸间容蒸然者处下。", "b": "《管子·弟子职》。注:“细薪也。”"}, {"t": "以薪以蒸。", "b": "《诗·小雅》"}], "words": [{"w": "蒸薪", "t": "木柴。"}]}, {"meaning": "中药炮制法之一 。将药物隔水蒸熟,以便于制剂。如茯苓、厚朴蒸后易于切片。或加酒拌蒸,如大黄、地黄经蒸制后,熟大黄的泻下减弱,熟地黄便成温性而滋肾补血。"}, {"meaning": "假借为“烝”。气体上升。", "cites": [{"t": "蒸灵液以播云。", "b": "嵇康《琴赋》。注:“气上貌。”"}, {"t": "阴阳陶蒸。", "b": "张华《鹪鹩赋》。注:“气上山貌。”"}, {"t": "日气蒸云。", "b": "《广东军务记》"}], "words": [{"w": "蒸樊", "t": "热气郁勃上升"}, {"w": "蒸郁", "t": "湿气旺盛上升。"}]}, {"meaning": "古代祭祀时以牲之全体置于俎上。", "cites": [{"t": "冬祭曰蒸。", "b": "《尔雅》"}], "words": [{"w": "蒸禋", "t": "祭祀。"}]}, {"meaning": "烧煮。", "cites": [{"t": "素汤米饭蒸卷馒头。", "b": "《西游记》"}], "words": [{"w": "蒸粟", "t": "蒸熟的粟子是黄色的,因以蒸粟比喻黄色"}, {"w": "蒸暑", "t": "闷热,暑热如蒸"}, {"w": "蒸黎", "t": "蒸煮野菜。"}]}, {"meaning": "同“烝”。众,多。", "cites": [{"t": "天生蒸民。", "b": "《孟子·告子上》"}, {"t": "立我蒸民。", "b": "《列子·仲尼》"}, {"t": "莘莘蒸徒。", "b": "左思《魏都赋》"}], "words": [{"w": "蒸天价", "t": "满天地;通天地"}, {"w": "蒸人", "t": "众人"}, {"w": "蒸民", "t": "众民,人民"}, {"w": "蒸庶", "t": "百姓,众民"}, {"w": "蒸黎", "t": "民众。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2861wx','献','1','xiàn','犬','13','','[{"pinyin": "xiàn", "defs": [{"meaning": "(会意。从犬,鬳(yàn)声。“犬”代表进献之物。本义:献祭)。"}, {"meaning": "同本义。", "cites": [{"t": "献,宗庙犬,名羹献。犬肥者以献之。", "b": "《说文》"}, {"t": "犬曰羹献。", "b": "《礼记·曲礼》。按,礼凡荐腥谓之献。"}, {"t": "献禽以祭祖。", "b": "《周礼·大司马》"}, {"t": "献羔祭韭。", "b": "《诗·豳风·七月》"}, {"t": "荐晡醢,三献。(三献:陈祭品三次献酒。)", "b": "《仪礼·聘礼》"}], "words": [{"w": "献尸", "t": "向代表死人的尸者进献祭品"}, {"w": "献帛", "t": "祭祀礼仪之一,献上巾帕"}, {"w": "献爵", "t": "祭祀礼仪之一,献酒"}, {"w": "献台", "t": "祭台。"}]}, {"meaning": "下对上、卑对尊的进献。", "cites": [{"t": "献,进也。", "b": "《广雅》"}, {"t": "春献鳖蜃,秋献龟鱼。", "b": "《周礼·鳖人》"}, {"t": "有献于公。", "b": "《左传·隐公元年》"}, {"t": "称献于公。", "b": "《左传·隐公元年》"}, {"t": "称远近而等贡献。", "b": "《荀子·正论》"}, {"t": "献俘,授馘。", "b": "《左传·僖公二十八年》"}, {"t": "谨使臣良奉白璧一双,再拜献大王足下。", "b": "《史记·项羽本纪》"}, {"t": "请献十金。", "b": "《墨子·公输》"}, {"t": "时而献焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "献之太常。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "献诸朝。", "b": ""}], "words": [{"w": "献馘", "t": "杀敌立功"}, {"w": "献新", "t": "进奉应时的新鲜食品"}, {"w": "献曲", "t": "进献乐曲。"}]}, {"meaning": "呈现;现露。", "cites": [{"t": "虽惠心妍状,愈献丑焉。", "b": "《后汉书·皇后纪上》"}], "words": [{"w": "献地理图", "t": "比喻揭穿底细"}, {"w": "献好儿", "t": "讨好"}, {"w": "献台", "t": "比武台;赛台。"}]}, {"meaning": "进。", "cites": [{"t": "献岁发春兮,汩吾南征。", "b": "《楚辞》"}], "words": [{"w": "献岁", "t": "一年的开始。"}]}, {"meaning": "古时特指主人向宾客敬酒。", "cites": [{"t": "为宾为客,献酬交错。", "b": "《诗·小雅·楚茨》"}, {"t": "主人坐取爵实之,宾之席前西北面,献宾。", "b": "《仪礼》"}], "words": [{"w": "献酬", "t": "饮酒时相互酬劝"}, {"w": "献酬交错", "t": "献酬。"}]}, {"meaning": "庆贺。", "cites": [{"t": "晋献文子成室,晋大夫发焉。", "b": "《礼记》"}], "words": [{"w": "献寿", "t": "祝寿。"}]}, {"meaning": "熟知历史掌故的人。", "cites": [{"t": "文献不足故也。(文:典籍)", "b": "《论语·八佾》"}]}, {"meaning": "进献的东西。", "cites": [{"t": "吏或多赋以为献,而诸侯王尤多,民疾之。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2862wx','椿','1','chūn','木','13','','[{"pinyin": "chūn", "defs": [{"meaning": "同本义。", "cites": [{"t": "上古有大椿者。", "b": "《庄子·逍遥游》。司马注:“椿木一名橓。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2863wx','禁','1','jīn jìn','示','13','','[{"pinyin": "jīn", "defs": [{"meaning": "胜任,承受得起。", "cites": [{"t": "不能禁失吾之悲。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "禁久", "t": "经久,耐久"}, {"w": "禁奈", "t": "禁得起,受得起"}, {"w": "禁不过", "t": "禁不的,禁不起。承受不住,受不了"}, {"w": "禁当", "t": "担当;承受"}, {"w": "禁招", "t": "招架;忍受。"}]}]}, {"pinyin": "jìn", "defs": [{"meaning": "(形声。从示,林声。本义:禁忌)。"}, {"meaning": "同本义。", "cites": [{"t": "禁,吉凶之忌也。", "b": "《说文》"}, {"t": "使帅其属而掌邦禁。", "b": "《周礼·秋官》。注:“禁所以防奸也。囿人掌囿游之游禁。”"}, {"t": "入意而问禁。", "b": "《礼记·曲礼》"}], "words": [{"w": "禁条", "t": "即“禁忌”"}, {"w": "禁肉", "t": "佛家禁忌肉食"}, {"w": "禁忌日", "t": "元代制度,以每月初一、初八、十五日、二十三日为四斋日,禁止行刑和宰杀生物,又称“禁忌日”"}, {"w": "禁果", "t": "犹太教、基督教故事中禁止亚当及其妻夏娃采食的果子。"}]}, {"meaning": "帝王宫殿。", "cites": [{"t": "天子所居曰禁中。禁中者,门户有禁,非待御者不得入,故曰禁中。", "b": "朱骏声《说文通训定声》"}], "words": [{"w": "禁内", "t": "宫内"}, {"w": "禁外", "t": "宫外"}, {"w": "禁宫", "t": "宫殿"}, {"w": "禁闼", "t": "宫门。借指皇宫。闼:门"}, {"w": "禁省", "t": "警卫森严的皇宫。"}]}, {"meaning": "禁令;含有禁戒性的规条及法令。", "cites": [{"t": "侠以武犯禁。", "b": "《韩非子·五蠹》"}], "words": [{"w": "开禁", "t": "解除禁令"}, {"w": "犯禁", "t": "违犯禁令"}, {"w": "禁典", "t": "指朝廷法令"}, {"w": "禁罔", "t": "张布如网的禁令法律"}, {"w": "禁法", "t": "禁令,禁条。"}]}, {"meaning": "衣服的结带。", "cites": [{"t": "其冠绝,其缨禁缓。", "b": "《荀子·非十二子》"}]}, {"meaning": "禁止;制止。", "cites": [{"t": "禁,止也。", "b": "《广雅》"}, {"t": "严刑重罚以禁之。", "b": "《韩非子·奸劫弑臣》"}, {"t": "禁先其本者治。", "b": "《韩非子·心度》"}, {"t": "吏奸而不知禁。", "b": "明·刘基《卖柑者言》"}, {"t": "禁人之窥伺者。", "b": "清·黄宗羲《原君》"}, {"t": "长号不自禁。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "严禁", "t": "严格禁止"}, {"w": "查禁", "t": "检查禁止"}, {"w": "禁治", "t": "制止;管住"}, {"w": "禁锢善类", "t": "禁止正直的人做官与进行政治活动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2864wx','楚','1','chǔ','木','13','','[{"pinyin": "chǔ", "defs": [{"meaning": "(形声。从林,疋(shū)声。本义:灌木名。又名荆,牡荆)。"}, {"meaning": "同本义 。落叶灌木,开青色或紫色的穗状小花,鲜叶可入药,或小乔木,枝干坚韧,可做杖。", "cites": [{"t": "楚,丛木也。一名荆。", "b": "《说文》"}, {"t": "言刈其楚。", "b": "《诗·周南·汉广》"}, {"t": "不流束楚。", "b": "《诗·王风·扬之水》"}, {"t": "夏楚二物。", "b": "《礼记·学记》"}, {"t": "楚扑长如笴。", "b": "《仪礼·乡射礼》"}, {"t": "民无箠楚之忧。", "b": "《汉书·汉延寿传》"}], "words": [{"w": "楚棘", "t": "荆棘"}, {"w": "楚焞", "t": "古时占卜用以灼龟的木棒。以荆木制成"}, {"w": "楚藿", "t": "用荆条做的捕鱼笼"}, {"w": "楚楚", "t": "丛生的样子;鲜明的样子"}, {"w": "楚木", "t": "丛生之木"}, {"w": "楚林", "t": "丛林。"}]}, {"meaning": "周朝时国名。"}, {"meaning": "周代诸侯国,战国时七雄之一。熊绎受封于周成王,立国于荆山一带,都丹阳(今湖北秭归东南)。周人称为荆蛮。后建都于郢(今湖北江陵西北纪王城)。春秋战国时国势强盛,疆域由湖北、湖南扩展到今河南、安徽、江苏、浙江、江西和四川。战国末,屡败于秦,公元前223年为秦所灭。"}, {"meaning": "秦楚之际,陈胜在陈县(今河南淮阳)建立张楚政权,自号楚王;汉元年,项羽自立为西楚霸王,都下邳(今江苏睢宁西北),汉六年,国除。"}, {"meaning": "五代十国之一。马殷据今湖南,都长沙,称楚王。后为南唐所灭。"}, {"meaning": "酸辛痛苦。", "cites": [{"t": "慷慨含辛楚。", "b": "陆机诗"}, {"t": "妇始楚而谢,终泣而对曰…", "b": "李朝威《柳毅传》"}], "words": [{"w": "楚辱", "t": "苦痛与耻辱"}, {"w": "楚痛", "t": "痛苦"}, {"w": "楚酷", "t": "痛楚。"}]}, {"meaning": "齐整;清晰。", "cites": [{"t": "笾豆有楚。", "b": "《诗·小雅·宾之初筵》"}], "words": [{"w": "一清二楚;楚洁", "t": "整洁"}, {"w": "楚楚可爱", "t": "形容陈设整齐,令人喜爱。"}]}, {"meaning": "鲜艳,华丽。", "cites": [{"t": "不韦使楚服而见。", "b": "《战国策·秦策》"}, {"t": "衣裳楚楚。", "b": "《诗·曹风·蜉蝣》"}], "words": [{"w": "楚服", "t": "美盛的服饰"}, {"w": "楚丽", "t": "华美绚丽。"}]}, {"meaning": "拷打。", "cites": [{"t": "入狱楚掠。", "b": "《新唐书·严郢传》"}], "words": [{"w": "楚挞", "t": "笞打,拷打"}, {"w": "楚拷", "t": "拷打。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2865wx','楷','1','kǎi jiē','木','13','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从木,皆声。 ①(jiē)本义:木名。即“黄连木”。楷树枝干疏而不屈,因以形容刚直 ②法式,典范)。"}, {"meaning": "法式,典范。", "cites": [{"t": "楷,法也。", "b": "《广雅》"}, {"t": "今世行之,后世以为楷。", "b": "《礼记·儒行》"}], "words": [{"w": "楷法", "t": "法则;典范"}, {"w": "楷栻", "t": "同“楷式”"}, {"w": "楷素", "t": "楷模"}, {"w": "为此所楷", "t": ""}]}, {"meaning": "姓。"}]}, {"pinyin": "jiē", "defs": [{"meaning": "落叶乔木，木材可制器具，种子可榨油，树皮和叶子可制栲胶。", "words": [{"w": "楷木", "t": "黄连木"}, {"w": "楷床", "t": "黄连木制的床。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2866wx','榄','1','lǎn','木','13','','[{"pinyin": "lǎn", "defs": [{"meaning": "木名。橄榄的省称", "words": [{"w": "榄仁", "t": "橄榄核内柔软的部分"}, {"w": "榄香", "t": "即橄榄香"}, {"w": "榄糖", "t": "橄榄糖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2867wx','想','1','xiǎng','心','13','','[{"pinyin": "xiǎng", "defs": [{"meaning": "(形声。心形相声。本义:想念;怀念;羡慕)。"}, {"meaning": "同本义。", "cites": [{"t": "想,冀思也。", "b": "《说文》"}, {"t": "览物想故国。", "b": "杜甫《客居》"}, {"t": "遥想公瑾当年,小乔初嫁了,雄姿英发。", "b": "苏轼《念奴娇》"}], "words": [{"w": "想似", "t": "深切的怀念"}, {"w": "想思", "t": "想念。"}]}, {"meaning": "思考,思索。", "cites": [{"t": "入景响之无应兮,闻省想而不可得。", "b": "《楚辞·九章·悲回风》"}, {"t": "后来还亏得文琴替我竭力想法,找了原经手人,向周中堂讨主意。", "b": "《二十年目睹之怪现状》"}], "words": [{"w": "冥思苦想;想来想去", "t": "反复的多方思考"}, {"w": "想度", "t": "考虑,衡量。"}]}, {"meaning": "希望,想要。", "cites": [{"t": "那时他老人家正在用功,想中那名进士。", "b": "《儿女英雄传》"}], "words": [{"w": "想闻", "t": "想望,仰慕。"}]}, {"meaning": "料想;猜想。", "cites": [{"t": "余读孔氏书,想见其本人。", "b": "《史记·孔子世家论》"}], "words": [{"w": "想料", "t": "料想。"}]}, {"meaning": "想象。", "cites": [{"t": "想早励良规。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "思念存想,自见异物也。", "b": "王充《论衡》"}]}, {"meaning": "好像,如同。", "cites": [{"t": "云想衣裳花容,春风指槛露华浓。", "b": "李白《清平调词三首》"}]}, {"meaning": "怀念、回想。", "cites": [{"t": "想当年。", "b": "宋·辛弃疾《永遇乐·京口北固亭怀古》"}, {"t": "以慰长想。", "b": "明·宗臣《报刘一丈书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2868wx','槐','1','huái','木','13','','[{"pinyin": "huái", "defs": [{"meaning": "(形声。从木,鬼声。本义:木名。槐树)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2869wx','榆','1','yú','木','13','','[{"pinyin": "yú", "defs": [{"meaning": "榆树。", "cites": [{"t": "榆,白枌。", "b": "《说文》。按,榆皮色赤,其白者为枌也。荚可食,亦可为酱。"}, {"t": "堇萱枌榆。", "b": "《礼记·内则》"}, {"t": "我决起而飞抢榆枋。", "b": "《庄子·逍遥游》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2870wx','楼','1','lóu','木','13','','[{"pinyin": "lóu", "defs": [{"meaning": "(形声。从木,娄声。本义:楼房,两层以上的房屋)。"}, {"meaning": "同本义。", "cites": [{"t": "楼,重屋也。", "b": "《说文》"}, {"t": "西北有高楼,上与浮云齐。", "b": "《古诗十九首》"}, {"t": "五步一楼,十步一阁。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "教室楼;办公楼;科技楼;楼额", "t": "楼上的匾额"}, {"w": "楼观", "t": "高楼的泛称;道观的观名"}, {"w": "楼外楼", "t": "楼外有楼。楼房相连属"}, {"w": "楼角", "t": "高楼的檐角"}, {"w": "楼舍", "t": "楼房。"}]}, {"meaning": "楼房的一层。", "cites": [{"t": "欲穷千里目,更上一层楼。", "b": "王之涣《登鹳雀楼》"}], "words": [{"w": "一楼;二楼", "t": ""}]}, {"meaning": "建筑在高处的建筑物 。如:楼子(楼阁);楼榭(高台之上的房屋,泛指楼房);楼堞(城楼上的矮墙)。又指有上层的车船,其上层也叫楼。如:楼车(古代战车。上设望楼);楼舟工(楼船)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2871wx','概','1','gài','木','13','','[{"pinyin": "gài", "defs": [{"meaning": "(形声。从木,既声。本义:量米粟时刮平斗斛(hú)用的木板。量米粟时,放在斗斛上刮平,不使过满)。"}, {"meaning": "同本义。", "cites": [{"t": "同权槩而就衡。", "b": "《楚辞·惜誓》"}, {"t": "斛甬,正权概。", "b": "《礼记·月令》"}, {"t": "槩者,平量者也。", "b": "《韩非子·外储说》"}], "words": [{"w": "概量", "t": "概和斗斛等量谷物的器具。"}]}, {"meaning": "节操,风度。", "cites": [{"t": "而不概于王心邪。", "b": "《史记·范雎传》。按,平也。"}, {"t": "夫西河魏土……漂然皆有节概,知去就之分。", "b": "《汉书·杨敞传》附杨恽《报孙会宗书》"}], "words": [{"w": "概尚", "t": "气节"}, {"w": "气概", "t": "人遇事表现出来的态度、气势。"}]}, {"meaning": "景象;状况。", "cites": [{"t": "故山多药物,胜概(美丽的景象)忆桃源。", "b": "唐·杜甫《奉留赠集贤院崔于二学士》"}]}, {"meaning": "引申为刮平,不使过量。", "cites": [{"t": "夫水,徧与诸生而无为也,似德。……盈不求概,似正。", "b": "《荀子·宥坐》"}, {"t": "而不概于王心邪。", "b": "《史记·范雎传》。按,平也。"}], "words": [{"w": "概平", "t": "用概刮平"}, {"w": "概准", "t": "用平物的量器刮平。"}]}, {"meaning": "衡量;量,限量。", "cites": [{"t": "食飨不为槩。", "b": "《礼记·曲礼》。注:“量也。”"}], "words": [{"w": "概志", "t": "衡量心志"}, {"w": "概量", "t": "用量器确定谷物的多少;比喻衡量事物的标准。"}]}, {"meaning": "灌溉,洗涤。", "cites": [{"t": "澡概胸中,洒练五脏。", "b": "《枚乘·七发》"}]}, {"meaning": "又如;概盂(洗涤盂钵)。"}, {"meaning": "感慨。", "cites": [{"t": "夫婢妾贱人,感概而自杀,非能勇也。", "b": "《汉书·季布栾布田叔传赞》"}], "words": [{"w": "概然", "t": "感慨的样子。"}]}, {"meaning": "一律,一概。", "cites": [{"t": "余以所闻由光义至高,其文辞不少概见,何哉?", "b": "《史记·伯夷列传》"}], "words": [{"w": "概不考虑;概不赊欠;概行", "t": "一律施行"}, {"w": "概视", "t": "一律看待"}, {"w": "概用", "t": "一概使用。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2872wx','赖','1','lài','贝','13','','[{"pinyin": "lài", "defs": [{"meaning": "(形声。从贝,剌(là)声。本义:得益;赢利)。"}, {"meaning": "同本义。", "cites": [{"t": "赖,赢也。", "b": "《说文》"}, {"t": "赖,取也。", "b": "《方言十三》"}, {"t": "先王岂有赖焉。", "b": "《国语·周语》。注:“利也。”"}, {"t": "相语以利,相示以赖,相陈以知贾。", "b": "《国语》"}, {"t": "为魏则益,为秦则不赖矣。", "b": "《战国策》"}], "words": [{"w": "赖利", "t": "得利。"}]}, {"meaning": "依靠;依赖;依恃、凭藉。", "cites": [{"t": "奸人赖赏而富。", "b": "《韩非子·诡使》"}, {"t": "王室之不坏,繄伯舅是赖。", "b": "《左传·襄公十四年》"}, {"t": "以有补于人君,人君赖之。", "b": "《论衡·逢遇》"}, {"t": "而赖吾之德。", "b": "《国语·晋语》"}]}, {"meaning": "又。", "cites": [{"t": "赖子存之。", "b": ""}, {"t": "吾赖是以食吾躯。", "b": "明·刘基《卖柑者言》"}, {"t": "赖肤觉之助。", "b": "蔡元培《图画》"}], "words": [{"w": "赖衣求食;赖天", "t": "依靠上天的庇卫"}, {"w": "赖庇", "t": "依靠别人的庇卫。"}]}, {"meaning": "懒惰。", "cites": [{"t": "富岁子弟多赖。", "b": "《孟子·告子上》"}], "words": [{"w": "赖精", "t": "极无赖的人"}, {"w": "赖象磕瓜子", "t": "歇后语为“解不了饥”。"}]}, {"meaning": "利;好处。", "cites": [{"t": "先王岂有赖焉。", "b": "《国语·周语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2873wx','酪','1','lào','酉','13','','[{"pinyin": "lào", "defs": [{"meaning": "(形声。从酉(yǒu),各声。本义:乳酪)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2874wx','酬','1','chóu','酉','13','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从酉,夀声。本义:客人给主人祝酒后,主人再次给客人敬酒作答)。"}, {"meaning": "同本义。", "cites": [{"t": "酬,主人进客也。", "b": "《说文》。凡主人酌宾曰献,宾还酌主人曰醋,主人又自饮以酌宾曰酬。"}], "words": [{"w": "酬献", "t": "相互劝酒"}, {"w": "酬劝", "t": "劝酒。"}]}, {"meaning": "酬答,报答。", "cites": [{"t": "主人酬宾。", "b": "《仪礼·士冠礼》。注:“饮宾客而从之以财货,曰酬,所以申畅厚意也。”"}, {"t": "交酬好货皆厚。", "b": "《国语·周语》。注:“交酬相酬之币也。”"}, {"t": "吾无以酬之。", "b": "《左传·昭公二十七年》"}, {"t": "不有死者,无以酬圣主。", "b": "梁启超《谭嗣同传》"}, {"t": "天将以酬长厚者。", "b": "《聊斋志异·促织》"}], "words": [{"w": "酬知", "t": "酬报知己者"}, {"w": "酬赏", "t": "报答他人而赏给财物。"}]}, {"meaning": "应对;对答。", "cites": [{"t": "可与酬酢。", "b": "《易·系辞》。注:“犹应对也。”"}], "words": [{"w": "酬抗", "t": "酬对;对答"}, {"w": "酬决", "t": "应对决断"}, {"w": "酬奉", "t": "旧时奉召应对诗文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2875wx','感','1','gǎn hàn','心','13','','[{"pinyin": "gǎn", "defs": [{"meaning": "(形声。从心,咸声。本义:感动)。"}, {"meaning": "同本义。思想感情受外界事物的影响而激动。", "cites": [{"t": "感,动人心也。", "b": "《说文》"}, {"t": "感而遂通,天下之故。", "b": "《易·系辞》。虞注:“动也。”"}, {"t": "帝感其诚,命夸娥氏二子负二山。", "b": "《列子·汤问》"}, {"t": "羊子感其言,复还终业。", "b": "《后汉书·列女传》"}], "words": [{"w": "感格", "t": "感动,感化"}, {"w": "感咽", "t": "受感动而悲伤,泣不成声"}, {"w": "感涕", "t": "感动而涕泪俱下"}, {"w": "感慕", "t": "感动而思慕"}, {"w": "感悦", "t": "感动悦服"}, {"w": "感人肺腑", "t": "使人的内心深受感动"}, {"w": "感天动地", "t": "感动天地"}, {"w": "感哽", "t": "感动得泣不成声。"}]}, {"meaning": "感应,影响。", "words": [{"w": "感制", "t": "感应制约"}, {"w": "感会", "t": "感应会合"}, {"w": "感验", "t": "应验"}, {"w": "感变", "t": "感应变动。"}]}, {"meaning": "感触;触动感慨。", "cites": [{"t": "天地感而万物化生。", "b": "《易·成》"}, {"t": "登斯楼也,则有去国怀乡,忧谗畏讥,满目萧然,感极而悲者也。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "感目", "t": "触目"}, {"w": "感事", "t": "受外界事物的触动"}, {"w": "感逆", "t": "触犯,冒犯"}, {"w": "感悔", "t": "受到触动而悔改。"}]}, {"meaning": "感谢;感激。", "cites": [{"t": "新妇谓府吏:“感君区区怀!”", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "感荷君子德,恍若乘朽栈。", "b": "韩愈《赠张籍》"}, {"t": "远辱专人惠书,辅以药物,极济所乏,衰疾有赖矣,感刻,感刻。", "b": "宋·苏轼《与张元明书》"}], "words": [{"w": "感刻", "t": "深深感激"}, {"w": "感荷", "t": "感谢,感佩"}, {"w": "感篆", "t": "感激而铭记在心"}, {"w": "感仰", "t": "感戴敬仰"}, {"w": "感喜", "t": "感激喜悦"}, {"w": "感颂", "t": "感激颂扬。"}]}, {"meaning": "感慨,感伤。", "cites": [{"t": "感时花溅泪,恨别鸟惊心。", "b": "唐·杜甫《春望》"}, {"t": "至于长者之抱才而困,则又令我怆然有感。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "感忾", "t": "感叹。同“感慨”"}, {"w": "感切", "t": "伤感凄切"}, {"w": "感时", "t": "感慨时事的变迁或时势的变化"}, {"w": "感悼", "t": "感伤哀悼,伤感"}, {"w": "感恻", "t": "感伤悲痛。"}]}, {"meaning": "思念。", "cites": [{"t": "感物众而思深。", "b": "何晏《景福殿赋》。注:“犹思也。”"}], "words": [{"w": "感思", "t": "思念"}, {"w": "感逝", "t": "感念往昔"}, {"w": "感逝山阳", "t": "表示对亡友的哀念。"}]}, {"meaning": "感染,感受。多用于疾病。", "cites": [{"t": "太夫人并无别症,偶感了些风寒。", "b": "《红楼梦》"}], "words": [{"w": "感风", "t": "谓中风;宋代太学诸生请假外宿,例以“感风”为辞"}, {"w": "感疾", "t": "染病"}, {"w": "感通", "t": "有感于此而通于彼。"}]}, {"meaning": "迷惑。", "cites": [{"t": "使人不能执一者,物感之也。", "b": "《吕氏春秋》"}]}, {"meaning": "(jiǎn)。减损,减少。", "cites": [{"t": "其满为感,其虚为亡。", "b": "《管子·侈靡》"}]}]}, {"pinyin": "hàn", "defs": [{"meaning": "假借为“撼”。摇动。", "cites": [{"t": "夏则雷霆,霹雳之所感也。", "b": "枚乘《七发》"}], "words": [{"w": "感突", "t": "冲撞奔突貌"}, {"w": "无感", "t": "不能撼动"}, {"w": "感帨", "t": "指男子对女子非礼相陵"}, {"w": "感移", "t": "谓动摇之使其改变"}, {"w": "感动", "t": "动摇。"}]}, {"meaning": "假借为“憾”。怨恨。", "cites": [{"t": "王贪而无信,唯蔡于感。", "b": "《左传·昭公十一年》。注:“楚常恨其不服顺。”"}, {"t": "何感而上书归卫将军富平侯印?", "b": "《汉书·张安世传》"}], "words": [{"w": "释感", "t": "化解仇恨"}, {"w": "怀感", "t": "怀恨"}, {"w": "感恨", "t": "怨恨,不满"}, {"w": "感恚", "t": "愤恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2876wx','碍','1','ài','石','13','','[{"pinyin": "ài", "defs": [{"meaning": "(形声。从石,疑声。本义:妨碍,阻挡)。"}, {"meaning": "同本义。", "cites": [{"t": "碍,止也。", "b": "《说文》"}, {"t": "限至曰碍。", "b": "《通俗文》"}, {"t": "孰能碍之。", "b": "《列子·力命》。注:“止也。”"}, {"t": "碍诸以礼乐。", "b": "《法言·问道》。注:“限也。”"}, {"t": "直视无碍", "b": "吴均《与朱元思书》"}, {"t": "咱们别在这里碍手碍脚的", "b": "《红楼梦》。"}]}, {"meaning": "遮蔽;掩盖。", "cites": [{"t": "云雾不礙其视。", "b": "《列子·黄帝》"}, {"t": "四角碍白日,七层摩苍穹。", "b": "岑参《与高适薛据同登慈恩寺》"}]}, {"meaning": "牵挂。", "cites": [{"t": "洞同覆载,而无所碍。", "b": "《淮南子·缪称》。注:“挂也。”"}, {"t": "那时我身入空门,一身无碍,万缘俱寂。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2877wx','碘','1','diǎn','石','13','','[{"pinyin": "diǎn", "defs": [{"meaning": "一种非金属一价和多价元素,原子序数53,属于卤素,主要用于医药(例如用于抗菌、治疗呆小病和甲状腺肿)、照相和分析 ——元素符号I。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2878wx','碑','1','bēi','石','13','','[{"pinyin": "bēi", "defs": [{"meaning": "(形声。从石,卑声。本义:古时宫、庙门前用来观测日影及拴牲畜的竖石)。"}, {"meaning": "竖石。", "cites": [{"t": "碑,竖石也。", "b": "《说文》"}, {"t": "上当碑南陈。", "b": "《仪礼·聘礼》。注:“宫必有碑,所以识日景引阴阳也。宗庙则丽牲焉以取毛血。其材,宫庙以石,窆用木。”"}, {"t": "公室设丰碑。", "b": "《礼记·檀弓》"}, {"t": "君牵牲…既入庙门,丽(拴)于碑。", "b": "《礼记·祭义》"}]}, {"meaning": "石碑。石上刻着文字,作为纪念物或标记,也用以刻文告。秦代称刻石,汉以后称碑。", "cites": [{"t": "碑,被也。此本葬时所设也。施鹿卢以绳被其上,引以下棺也。臣子追述君父之功,美以书其上,后人因焉。无故建于道陌之头显见之处,名其文就谓之碑也。", "b": "《释名·释典艺》"}, {"t": "有碑仆道。", "b": "宋·王安石《游褒禅山记》"}, {"t": "有碑载其事。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "楔形碑;碑文;碑记;石碑;丰碑;界碑;路碑;墓碑;里程碑", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2879wx','碎','1','suì','石','13','','[{"pinyin": "suì", "defs": [{"meaning": "(形声。从石,卒声。“石”是汉字部首之一,从“石”的字与石头有关。本义:破碎)。"}, {"meaning": "同本义。", "cites": [{"t": "碎,细破也。", "b": "《广韵》"}, {"t": "拊之不时,则缺衔毁首碎胸。", "b": "《庄子·人间世》"}, {"t": "毂已破碎。", "b": "《荀子·法行》"}, {"t": "不敢以全物予之,为其碎之之怒也。", "b": "《列子·黄帝?"}, {"t": "大王必欲急臣,臣头今与璧俱碎于柱矣。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "碎首", "t": "撞碎其头"}, {"w": "碎折", "t": "破碎断裂"}, {"w": "碎扯百裂", "t": "撕裂得粉碎"}, {"w": "碎身粉骨", "t": "身体粉碎。指死亡。"}]}, {"meaning": "琐细;繁杂。", "cites": [{"t": "米盐靡密,初若烦碎,然霸精力能推行之。", "b": "《汉书·黄霸传》"}], "words": [{"w": "碎小", "t": "琐细;自称家人儿女。"}]}, {"meaning": "零星;细小。", "cites": [{"t": "乱点碎红山杏发。", "b": "白居易《南湖早春》"}], "words": [{"w": "碎 砒", "t": "粉末;特小的碎块"}, {"w": "碎玉", "t": "喻指牙齿"}, {"w": "碎剐", "t": "一小块一小块地割取"}, {"w": "碎碎", "t": "细细;零星;象声词"}, {"w": "碎滴", "t": "细小的水珠"}, {"w": "碎布;碎屑", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2880wx','碰','1','pèng','石','13','','[{"pinyin": "pèng", "defs": [{"meaning": "(形声。从石,并声。本义:两物相触或相撞)。"}, {"meaning": "同本义。", "cites": [{"t": "掽,蒲孟切,彭去声,搕掽,撞也。", "b": "《字汇》。段注:“今俗谓卒然相遇曰掽。”按,掽是晚起字,今字作“碰”"}], "words": [{"w": "小车碰到电线杆;鸡蛋碰石头;碰头", "t": "磕响头,表示惶恐服罪"}, {"w": "碰关", "t": "方言。充其量;到了顶点"}, {"w": "碰磕", "t": "相撞,冲撞。"}]}, {"meaning": "触犯。", "cites": [{"t": "俺们这个玉大人真是了不得,赛过活阎王,碰着了就是个死。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2881wx','碗','1','wǎn','日','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "一种圆形凹心盛食品的器具,在形式上通常接近半球形,一般比盘子深,比茶杯大和重。", "cites": [{"t": "芙蓉玉碗,莲子金杯。", "b": "北周·庾信《春赋》"}], "words": [{"w": "饭碗;瓷碗;搪瓷碗;摆碗筷;碗泥", "t": "烧制瓷器的粘土"}, {"w": "碗窑", "t": "烧制瓷器的窑。"}]}, {"meaning": "用来计量用碗装的饮食。", "cites": [{"t": "滑出出,水冷冷,两碗来素匾食。", "b": "明·朱有《豹子和尚自还俗》"}]}, {"meaning": "宋朝以来灯笼一盏叫一碗。", "cites": [{"t": "正劝不开,只见两三碗灯笼飞也似来。", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2882wx','碌','1','lù liù','石','13','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从石,录声。本义:石青色)。"}, {"meaning": "小石", "words": [{"w": "碌碌", "t": "多石的样子;玉石美好"}]}, {"meaning": "矿物名", "words": [{"w": "碌青", "t": "即石碌。一种颜料,也可入药"}]}, {"meaning": "平庸无能", "words": [{"w": "碌碌公", "t": "[方言]指技能平庸的人"}, {"w": "碌碌庸庸", "t": "平庸而无所作为"}, {"w": "碌碌无奇", "t": "平凡,无特殊才能"}]}, {"meaning": "繁忙", "words": [{"w": "碌乱", "t": "忙乱"}, {"w": "碌碌营营", "t": "辛苦繁忙"}]}, {"meaning": "哆嗦,颤动", "words": [{"w": "碌都", "t": ""}]}]}, {"pinyin": "liù", "defs": [{"meaning": "石制的圆柱形农具用来轧谷物,平场地。", "words": [{"w": "碌碡", "t": "农具，用来轧脱谷粒或轧平场院。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2883wx','尴','1','gān','尢','13','','[{"pinyin": "gān", "defs": [{"meaning": "a.处境窘困，不易处理。b.神色、态度不正常。"}, {"meaning": "尴尬的局面。", "cites": [{"t": "这一来，我倒有些尴尬了，下面的话怎么说呢!--《百合花》", "b": ""}, {"t": "潘虎显得有些尴尬我是自己竖竿子的。”--《潘虎》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2884wx','雷','1','léi lèi','雨','13','','[{"pinyin": "léi", "defs": [{"meaning": "(象形。甲骨文,中间象闪电,圆圈和小点表示雷声。整个字形象雷声和闪电相伴而作。小篆变成了会意字,从雨,下象雷声相连之形,表示打雷下雨。本义:云层放电时发出的巨响)。"}, {"meaning": "同本义。", "cites": [{"t": "靁,阴阳薄动,靁雨生物者也。", "b": "《说文》"}, {"t": "阴阳合为雷。", "b": "《春秋·玄命苞》"}, {"t": "雷者,阴中之阳也。", "b": "《白虎通》"}, {"t": "仲春,雷乃发声,仲秋,雷始收声。", "b": "《礼记·月令》"}, {"t": "雷以动之,风以散之,雨以润之。", "b": "《易·说卦》"}, {"t": "阴阳相薄为雷。", "b": "《淮南子·坠形》"}, {"t": "天下应之如雷霆。", "b": "《荀子·儒效》"}, {"t": "如雷如霆,徐方震惊。", "b": "《诗·大雅·常武》"}, {"t": "峭壁呀呀虎擘口,恶滩汹汹雷出吼。", "b": "杨万里《檄风伯》"}], "words": [{"w": "雷火", "t": "因雷击所起的火"}, {"w": "雷光", "t": "闪电的光茫"}, {"w": "雷吼", "t": "形容响声大如雷鸣"}, {"w": "雷气", "t": "雄壮的气概"}, {"w": "雷奋", "t": "如雷霆的振动"}, {"w": "雷干", "t": "气候天气苦热"}, {"w": "雷谤", "t": "比喻猛烈毁谤"}, {"w": "雷驰", "t": "形容快如雷电闪击"}, {"w": "雷腾云奔", "t": "如雷电风云般的奔腾。"}]}, {"meaning": "剧响,巨大声响 。", "cites": [{"t": "雷霆乍起", "b": "唐·杜牧《阿房宫赋》"}]}, {"meaning": "古酒器名。", "cites": [{"t": "君于是造立礼器…雷、洗、觞、觚。", "b": "《隶释·汉鲁相韩敕造孔庙礼器碑》"}]}, {"meaning": "打雷。", "cites": [{"t": "故雷则掩耳。", "b": "《吕氏春秋·贵生》"}, {"t": "无冬雷,地冬霆。", "b": "《管子·七臣七主》"}]}, {"meaning": ",敲击。", "cites": [{"t": "雷鼓大震。", "b": "《资治通鉴》"}]}, {"meaning": "姓。"}]}, {"pinyin": "lèi", "defs": [{"meaning": "", "words": [{"w": "官家出游雷大鼓", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2885wx','零','1','líng','雨','13','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从雨,令声。本义:下雨。指落细雨)。"}, {"meaning": "同本义。", "cites": [{"t": "零,余雨也。", "b": "《说文》"}, {"t": "零雨其濛。", "b": "《诗·豳风·东山》"}], "words": [{"w": "零雨", "t": "徐徐飘落的雨。"}]}, {"meaning": "引申为如雨一般地落下;降落。", "cites": [{"t": "今当远离,临表涕零。", "b": "诸葛亮《出师表》"}, {"t": "灵雨既零,命彼倌人。", "b": "《诗·鄘风·定之方中》"}, {"t": "阿母得闻之,零泪应声落。", "b": "《孔雀东南飞》"}, {"t": "零露溥兮。", "b": "《诗·郑风·野有蔓草》"}, {"t": "柯叶汇而而零茂。", "b": "《文选·班固·幽通赋》"}, {"t": "涕零如雨。", "b": "《诗·小雅·小明》"}], "words": [{"w": "零泪", "t": "落泪"}, {"w": "零露", "t": "自天空陨落露珠"}, {"w": "感激涕零", "t": ""}]}, {"meaning": "凋零,凋落。", "cites": [{"t": "悼芳草之先零。", "b": "《楚辞·远游》"}, {"t": "惟草木之零落兮,恐差人之迟暮。", "b": "《楚辞·离骚》"}, {"t": "岁暮百草零,疾风高冈裂。", "b": "杜甫《自京赴奉先县咏怀五百字》"}], "words": [{"w": "零替", "t": "散落,衰败"}, {"w": "零茂", "t": "凋落和茂盛。"}]}, {"meaning": "比喻人死亡或到暮年。", "cites": [{"t": "海内知识,零落殆尽。", "b": "汉·孔融《论盛孝章书》"}]}, {"meaning": "零碎,零散。", "cites": [{"t": "何必受这些零气。", "b": "《红楼梦》"}], "words": [{"w": "零嘴", "t": "零食"}, {"w": "零花", "t": "零星的棉花"}, {"w": "零讯", "t": "零星的消息"}, {"w": "零阶光栅光谱;一个数的零次幂", "t": ""}]}, {"meaning": "表示没有数量。", "cites": [{"t": "我们毕竟不是从零开始的", "b": ""}]}, {"meaning": "假借为“灵”。神灵。", "cites": [{"t": "公其乡零。", "b": "《张公神碑》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2886wx','雾','1','wù','雨','13','','[{"pinyin": "wù", "defs": [{"meaning": "接近地面的水蒸气，遇冷凝结后飘浮在空气中的小水点。与云的区别只是雾较贴近地面;有时区别于霭的是不太透明。", "words": [{"w": "雾霭", "t": "雾气，形容雾气腾腾的样子。"}, {"w": "雾化", "t": "指使液体经过特殊装置化成小滴,成雾状喷射出去。"}, {"w": "雾沉沉", "t": "指很浓重的雾气。"}, {"w": "雾合", "t": "如云雾般的聚合。"}, {"w": "雾析", "t": "雾气消散。"}, {"w": "雾岑", "t": "云雾缭绕的山峰。"}, {"w": "雾会", "t": "如云雾般聚集在一起。形容其多。"}, {"w": "雾驳", "t": "形容事物像雾色一样斑斓驳杂。"}]}, {"meaning": "比喻轻细的", "words": [{"w": "雾绡", "t": "像薄雾一般的轻纱"}]}, {"meaning": "比喻浓密的", "words": [{"w": "雾鬣", "t": "细密的鬣毛"}]}, {"meaning": "比喻头发的堆卷盘旋,有如雾气的舒腾", "words": [{"w": "雾鬟", "t": "形容女子头发像云雾般的堆卷盘旋"}, {"w": "雾鬓风鬟", "t": "形容女子发髻松散的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2887wx','雹','1','báo','雨','13','','[{"pinyin": "báo", "defs": [{"meaning": "(形声。从雨,包声。本义:冰雹) 同本义。", "cites": [{"t": "阳之专气为雹。", "b": "《大戴礼记·曾子天圆》。注:“阳气在雨,温暖如汤,阴气薄之不相入,转而为雹,盖犹沸汤在闭器而沈于泉,则为冰也。”"}, {"t": "寒水胜火,则为冰雹。", "b": "《素问·六元正纪大论》"}, {"t": "霰雪雨雹,一时皆下。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "雹霰", "t": "冰雹夹杂雪珠而下。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2888wx','辐','1','fú','车','13','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从车,畐(fú)声。“畐”有“腹满”义(参“福”字条),而“辐”为圆形,与人腹满之形相类,因而“畐”在字中亦兼有表义作用。本义:辐条。插入轮毂以支撑轮圈的细条)。"}, {"meaning": "同本义。", "cites": [{"t": "辐,轮轑也。", "b": "《说文》"}, {"t": "辐也者,以为直指也。", "b": "《考工记·轮人》"}, {"t": "三十辐共一毂。", "b": "《老子》"}, {"t": "众辐凑于前。", "b": "《汉书·刘向传》"}, {"t": "坎坎伐辐兮,置之河之侧兮。", "b": "《诗·魏风·伐檀》"}], "words": [{"w": "轮辐;辐集", "t": "聚集"}, {"w": "辐聚", "t": "聚集。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2889wx','辑','1','jí ji','车','13','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。本义:车箱)。"}, {"meaning": "同本义。泛指车子。", "cites": [{"t": "辑,车和辑也。", "b": "《说文》"}, {"t": "辑,合材为车,咸相得谓之辑。", "b": "《六书故》"}, {"t": "推于御也,齐辑乎辔衔之际。", "b": "《列子·汤问》"}]}, {"meaning": "聚集。", "cites": [{"t": "甲辑而兵聚。", "b": "《韩非子·说林》"}], "words": [{"w": "辑辑", "t": "群集的样子。"}]}, {"meaning": "敛,拖着不使脱落。", "cites": [{"t": "望于山川,遍于群神,辑五瑞。", "b": "《书·舜典》"}, {"t": "有饿者,蒙袂辑屦,贸贸然来。", "b": "《礼记》"}]}, {"meaning": "把各种来源的书面材料或项目经加工汇编成一个文件或一册,汇编成一套文件或丛书。", "cites": [{"t": "辞之辑也。", "b": "《诗·大雅·板》"}, {"t": "辑黄花冈烈士事略。", "b": "孙文《黄花冈七十二烈士事略序》"}], "words": [{"w": "辑佚书", "t": "辑集佚书。又指已经亡佚的古书,被后人从其他各种书籍中收集起来那些引用过的之句,然后尽量按原书整理成一个辑本"}, {"w": "辑略", "t": "汉刘歆所撰七略之一。是一篇论述当时已出版的群书及学术源流的提要"}, {"w": "辑佚", "t": "辑录散佚的有关资料"}, {"w": "辑刊", "t": "编集刻印。"}]}, {"meaning": "连缀。", "cites": [{"t": "饰以玫瑰,辑以翡翠。", "b": "《韩非子·外储》"}]}, {"meaning": "和谐,和睦。", "cites": [{"t": "其天下辑睦。", "b": "《左传·襄公十九年》"}], "words": [{"w": "辑穆", "t": "和睦"}, {"w": "辑和", "t": "和谐;团结"}, {"w": "辑辑", "t": "声音柔和。也作“习习”"}, {"w": "辑柔", "t": "精神安和柔顺。"}]}]}, {"pinyin": "ji", "defs": [{"meaning": "——见“逻辑”(luóji)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2890wx','输','1','shū','车','13','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从车,俞声。本义:转运,运送)。"}, {"meaning": "同本义。", "cites": [{"t": "输,委输也。", "b": "《说文》"}, {"t": "运所有,输所无。", "b": "《淮南子·泛南训》"}, {"t": "输积聚以贷。", "b": "《左传·襄公九年》"}, {"t": "春申道缀基毕输。", "b": "《荀子·成相》"}, {"t": "秦于是乎输粟于晋。", "b": "《左传·僖公十三年》"}, {"t": "输之于宫以为食器。", "b": "《韩非子·十过》"}, {"t": "一旦不能有,输来其间。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "输供", "t": "输送供给"}, {"w": "输将", "t": "运送"}, {"w": "输场", "t": "唐代转运物资的货场"}, {"w": "输发", "t": "输送和调发粮草、军队"}, {"w": "输转", "t": "转运"}, {"w": "输将", "t": "运送,输运"}, {"w": "输遣", "t": "运送。"}]}, {"meaning": "交出;缴纳。", "cites": [{"t": "已乃劝输巨室,令曰:“输(捐献)不必金,出粟、菽、帛、布及它物者听。”", "b": "清·邵长蘅《阎典史传》"}, {"t": "笺诉天公休掠剩,半偿私债半输(缴纳)官。", "b": "宋·范成大《四时田园杂兴》"}], "words": [{"w": "输诚", "t": "献纳诚心"}, {"w": "输分", "t": "捐送财礼分子"}, {"w": "输征", "t": "缴纳赋税"}, {"w": "输货", "t": "献纳财货"}, {"w": "输期", "t": "缴纳租税的期限"}, {"w": "输税", "t": "纳税"}, {"w": "输粮", "t": "缴纳租税"}, {"w": "输纳", "t": "多指赈济或交税的捐献"}, {"w": "输财助边", "t": "捐献财物,帮助边境的防卫"}, {"w": "输芒", "t": "传说蟹于八月稻熟时,腹中有一稻芒,献于海神。"}]}, {"meaning": "传达,表达。", "cites": [{"t": "当面输心背面笑。", "b": "杜甫《莫相疑行》"}], "words": [{"w": "输心", "t": "献纳诚心,表白忠诚的心意"}, {"w": "输心贴意", "t": "真心实意。输心:表示真心"}, {"w": "输写", "t": "倾吐,抒发情意。"}]}, {"meaning": "报告;告诉。", "cites": [{"t": "常以国情输楚。", "b": "《战国策·秦策》"}], "words": [{"w": "输敌", "t": "报告敌方"}, {"w": "输情", "t": "表示真情。"}]}, {"meaning": "灌输;灌注。", "cites": [{"t": "险出三峡右,长输不尽溪。", "b": "苏轼《庐山二胜栖贤三峡桥》"}], "words": [{"w": "输灌", "t": "灌输。"}]}, {"meaning": "堕;堕坏。", "cites": [{"t": "屡顾尔仆,不输尔载。", "b": "《诗·小雅·正月》"}]}, {"meaning": "负,失败。", "cites": [{"t": "昨日输了一陈,挫动锐气。", "b": "《群英会蒋干中计》"}, {"t": "虽然是输赢无定,也须知报应分明。", "b": "《陈州粜米》"}], "words": [{"w": "输服", "t": "认输"}, {"w": "输眼", "t": "方言。以目测某事物的准确程度打赌,输了的叫“输眼”"}, {"w": "输筹", "t": "负局;失利。"}]}, {"meaning": "不及,赶不上。", "cites": [{"t": "平生奇绝输此游。", "b": "黄遵宪《下水船歌》"}], "words": [{"w": "输与", "t": "比不上;给与"}, {"w": "输小", "t": "甘愿处于低下地位"}, {"w": "输款", "t": "投诚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2891wx','督','1','dū','目','13','','[{"pinyin": "dū", "defs": [{"meaning": "(形声。从目,叔声。本义:察看督促,监督)。"}, {"meaning": "同本义。", "cites": [{"t": "督,察也。", "b": "《说文》"}, {"t": "禁督逆祀命者。", "b": "《周礼·春官·大祝》"}, {"t": "植中枢,立督虑。", "b": "《太玄卷一周》"}, {"t": "行督责之术。", "b": "《史记·李斯传》"}, {"t": "离娄督绳。", "b": "《汉书·王褒传》"}, {"t": "督责大臣。", "b": "《汉书·公孙贺传》"}, {"t": "闻将军有意督过之。", "b": "《汉书·高帝纪》"}, {"t": "亮使马谡督诸军在前。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "统率,指挥。", "cites": [{"t": "旋见一白酋督印度卒约百人。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "统帅诸军的将领。", "cites": [{"t": "审知故松山殉难督师洪公果死耶?", "b": "清·全祖望《梅花岭记》"}, {"t": "遂以周瑜、程普为左右督,将兵与备并力逆操。", "b": "《资治通鉴》"}], "words": [{"w": "督镇", "t": "清代对省一级文武官员的统称"}, {"w": "督臣", "t": "即总督"}, {"w": "督署", "t": "总督衙门"}, {"w": "督篆", "t": "总督的大印。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2892wx','频','1','pín','页','13','','[{"pinyin": "pín", "defs": [{"meaning": "(会意。从步,从页。页(xié):人头。《说文》认为步是“涉”的省略。人将要渡河,见水深,皱眉而止。本义:皱眉)。"}, {"meaning": "同本义。", "cites": [{"t": "已频顣曰。", "b": "《孟子》"}], "words": [{"w": "频蹙", "t": "皱眉蹙额,忧愁不乐的样子。"}]}, {"meaning": "接近;临近。", "cites": [{"t": "百姓流亡,频于涂炭。", "b": "晋·潘岳文"}]}, {"meaning": "重复,连续。", "cites": [{"t": "频,连也。", "b": "《字汇》"}, {"t": "频年服役。", "b": "《后汉书·杨终传》"}], "words": [{"w": "频日", "t": "连续多日"}, {"w": "频世", "t": "连续两代"}, {"w": "频岁", "t": "连年。"}]}, {"meaning": "危急;紧急。", "cites": [{"t": "于科有哀,国步斯频。", "b": "《诗·大雅·桑柔》"}]}, {"meaning": "假借为“滨”。水边。"}, {"meaning": "屡次;频繁。", "cites": [{"t": "是时,地数震裂,众灾频降。", "b": "《后汉书·李云传》"}, {"t": "近于京师,频得足下所为文,读之甚善。", "b": "欧阳修《与石推官第一书》"}], "words": [{"w": "频荐齿颊", "t": "总挂在嘴边"}, {"w": "频送", "t": "接连传送。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2893wx','龄','1','líng','齿','13','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从齿,令声。从牙齿来看年龄的长幼,所以从“齿”。本义:年龄)。"}, {"meaning": "同本义。", "cites": [{"t": "通子垂九龄,但觅梨与栗。", "b": "陶渊明《责子》"}], "words": [{"w": "学龄儿童;高龄;龄齿", "t": "年龄。"}]}, {"meaning": "年限;年数。", "cites": [{"t": "暂游越万里,少别数千龄。", "b": "鲍照《代升天行》"}], "words": [{"w": "工龄;党龄;教龄", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2894wx','鉴','1','jiàn','金','13','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从金,监声。本义:古代用来盛水或冰的青铜大盆)。"}, {"meaning": "同本义。", "cites": [{"t": "鑑,大盆也,一曰鑑诸,可以取明水于月。", "b": "《说文》。徐灏曰:“鑑,古祇作堅,从皿以盛水也。其后范铜为之,而用以照形者,亦谓之鑑,声转为镜。”"}, {"t": "鑑谓之镜。", "b": "《广雅》"}, {"t": "借明于鑑以炤之。", "b": "《淮南子·主术》"}, {"t": "我心匪鑒。", "b": "《诗·邶风·柏舟》"}, {"t": "卫灵公有妻三人,同鑑而浴。", "b": "《庄子》"}, {"t": "春始治鑑。", "b": "《周礼》"}], "words": [{"w": "鉴诸", "t": "古代承露取水的器具"}, {"w": "鉴燧", "t": "方诸和阳燧。"}]}, {"meaning": "借鉴,可以作为警戒或引为教训的事。", "cites": [{"t": "槛外诸鉴。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "引以为鉴;前车之覆,后车之鉴;鉴戒", "t": "以过去的经验为教训。"}]}, {"meaning": "明察,审查。", "cites": [{"t": "谿极则不鑒。", "b": "《吕氏春秋·适音》"}, {"t": "不能鉴听。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "鉴彻", "t": "明察"}, {"w": "鉴达人", "t": "鉴事人。明察事理的人"}, {"w": "鉴貌辨色", "t": "察颜观色;看脸色行事"}, {"w": "鉴事", "t": "明察事理。"}]}, {"meaning": "借鉴,鉴戒。", "cites": [{"t": "哀之而不鉴之。", "b": "唐·杜牧《阿房宫赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2895wx','睛','1','jīng','目','13','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从目,青声。本义:眼珠)。"}, {"meaning": "同本义。", "cites": [{"t": "虽达视犹不能见其睛。", "b": "《淮南子·主术》"}], "words": [{"w": "定睛一看;画龙点睛;火眼金睛", "t": ""}]}, {"meaning": "眼睛。", "cites": [{"t": "那行者睁睛看处,真个的背在身上。", "b": "《西游记》"}, {"t": "偷睛斜望,春光只隔流苏帐。", "b": "明·陆采《明珠记》"}]}, {"meaning": "视力。", "cites": [{"t": "阳气上走于目而为睛,其别气走于耳而为听。", "b": "《灵枢经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2896wx','睹','1','dǔ','目','13','','[{"pinyin": "dǔ", "defs": [{"meaning": "(形声。从目,者声。本义:见,看见)。"}, {"meaning": "同本义。", "cites": [{"t": "睹,见也。", "b": "《说文》"}, {"t": "圣人作而万物睹。", "b": "《易·文言传》"}, {"t": "今我睹子之难穷也。", "b": "《庄子·秋水》"}, {"t": "云霞明灭或可睹。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "令人目不忍睹。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "有目共睹;睹睐", "t": "看见;发现"}, {"w": "睹闻", "t": "亲见亲闻"}, {"w": "睹始知终", "t": "看见事物的开始阶段,就预见到它的最终结果"}, {"w": "睹记", "t": "见闻与记忆。"}]}, {"meaning": "察看。", "cites": [{"t": "赵简子将袭卫,使史默往睹之。", "b": "《吕氏春秋·召类》"}], "words": [{"w": "耳闻目睹;秋毫必睹", "t": ""}]}, {"meaning": "明白;懂得。", "cites": [{"t": "不务深迂而难睹。", "b": "《论衡》"}], "words": [{"w": "睹事", "t": "懂事,明晓事理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2897wx','睦','1','mù','目','13','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从目,坴(lù)声。本义:和好,亲近)。"}, {"meaning": "同本义。", "cites": [{"t": "睦,目顺也。", "b": "《说文》"}, {"t": "讲信修睦。", "b": "《礼记·礼运》。注:“皆训亲。”"}, {"t": "睦于父母之堂。", "b": "《礼记·坊记》"}, {"t": "则百姓亲睦。", "b": "《孟子》"}, {"t": "九族既睦。", "b": "《书·尧典》"}], "words": [{"w": "睦友", "t": "和睦友爱"}, {"w": "睦睦", "t": "和睦,亲密"}, {"w": "睦亲", "t": "对宗族和睦,对外亲友好"}, {"w": "睦族", "t": "和睦亲族。"}]}, {"meaning": "", "cites": [{"t": "睦,敬和也。", "b": "《说文》"}], "words": [{"w": "睦睦", "t": "恭敬的样子。"}]}, {"meaning": "古州名。睦州的简称。"}, {"meaning": "隋置。故地在今湖北省长阳县东。"}, {"meaning": "隋置。故地在今浙江省淳安县西。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2898wx','瞄','1','miáo','目','13','','[{"pinyin": "miáo", "defs": [{"meaning": "(形声。从目,苗声。本义:注视目标;视力集中到一点上)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2899wx','睫','1','jié','目','13','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从目,疌(jié)声。本义:眼睫毛) 同本义。", "cites": [{"t": "吾不贵其用智之如目见毫毛而不见其睫也。", "b": "《史记·越世家》"}], "words": [{"w": "睫眸", "t": "睫毛和眼珠。比喻眼前事理"}, {"w": "睫眼间", "t": "比喻极短的时间"}, {"w": "目不交睫", "t": ""}]}, {"meaning": "迅速而无意地眨眼。", "cites": [{"t": "矢来注眸子,而眶不睫。", "b": "《列子·仲尼》"}], "words": [{"w": "睫睫", "t": "目动的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2900wx','睡','1','shuì','目','13','','[{"pinyin": "shuì", "defs": [{"meaning": "(会意。从目,垂声。指眼睑下垂,打瞌睡。本义:坐着打瞌睡)。"}, {"meaning": "同本义。", "cites": [{"t": "睡,坐寐也。", "b": "《说文》"}, {"t": "读书欲睡,引锥自剌其股。", "b": "《战国策·秦策》"}, {"t": "孝公既见卫鞅,语事良久,孝公时时睡,弗听。", "b": "《史记·商君列传》"}], "words": [{"w": "睡晌觉", "t": "睡午觉"}, {"w": "睡寐", "t": "瞌睡;打盹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2901wx','睬','1','cǎi','目','13','','[{"pinyin": "cǎi", "defs": [{"meaning": "理睬,答理。", "cites": [{"t": "不是远老泰山为人忒歹,亲女婿昂然不睬。", "b": "王实甫《破窑记》"}, {"t": "王太太不倸,坐着不动。", "b": "《儒林外史》"}], "words": [{"w": "不睬;不要睬他", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2902wx','嗜','1','shì','口','13','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从口,耆(shì)声。本义:爱好)。"}, {"meaning": "同本义。", "cites": [{"t": "嗜,嗜欲,喜之也。", "b": "《说文》"}, {"t": "屈到嗜芰。", "b": "《韩非子·难四》"}, {"t": "性嗜酒。", "b": "《世说新语·简傲》"}, {"t": "余幼时即嗜学。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "嗜学", "t": "非常好学"}, {"w": "嗜癖", "t": "嗜好而入迷"}, {"w": "嗜胆", "t": "嗜食苦胆。比喻特异的习性"}, {"w": "嗜茗", "t": "爱好喝茶"}, {"w": "嗜古", "t": "好古"}, {"w": "嗜书", "t": "爱好读书"}, {"w": "嗜杀", "t": "喜好杀戮"}, {"w": "嗜枣", "t": "指特殊的嗜好"}, {"w": "嗜爱", "t": "嗜欲;爱好。"}]}, {"meaning": "贪求。", "cites": [{"t": "吾闻国家败政,必用奸人而嗜其疾味。", "b": "《国语·楚语下》"}, {"t": "邠人偷嗜暴恶者。", "b": "柳宗元《段太尉逸事状》"}, {"t": "今世之嗜取者,遇货不避。", "b": "柳宗元《蝜蝂传》"}], "words": [{"w": "嗜利", "t": "贪求私利;贪图钱财"}, {"w": "嗜血", "t": "猛兽贪于血食,后亦用以形容人凶残成性。"}]}, {"meaning": "贪求的东西。", "cites": [{"t": "嗜欲无限。", "b": "《韩非子·解老》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2903wx','鄙','1','bǐ','阝','13','','[{"pinyin": "bǐ", "defs": [{"meaning": "(形声。从邑,啚(bǐ)声。本义:五百家(周代户口单位))。"}, {"meaning": "同本义。", "cites": [{"t": "鄙,五酂为鄙。", "b": "《说文》"}, {"t": "五家为邻,五邻为里,四里为酂,五酂为鄙,五鄙为县,五县为遂。", "b": "《周礼·遂人》"}, {"t": "县都之治。", "b": "《周礼·宰夫》。注:“五百家为鄙。”"}, {"t": "以八卿治都鄙。", "b": "《周礼·太宰》。注:“都之所居曰鄙。都鄙距国五百里,为王子弟公卿大夫采地。”"}, {"t": "命司徒,循行县鄙。", "b": "《吕氏春秋》。高诱注:“鄙,五百家也。”"}]}, {"meaning": "采邑;小邑。", "cites": [{"t": "辩其邦国都鄙。", "b": "《周书·职方》。注:“邑曰鄙。”"}, {"t": "四鄙入保。", "b": "《礼记·月令》。注:“界上邑。”"}], "words": [{"w": "鄙野", "t": "郊外偏远的地方"}, {"w": "边鄙残破", "t": ""}]}, {"meaning": "边邑;边境。", "cites": [{"t": "群公子皆鄙。", "b": "《左传·庄公二十六年》。注:“边邑也。”"}, {"t": "匈奴背叛不臣,数为寇暴于边鄙。", "b": "《盐铁论·本议》"}, {"t": "蜀之鄙有二僧。", "b": "清·彭端叔《为学一首示子侄》"}], "words": [{"w": "鄙疆", "t": "边境"}, {"w": "鄙县", "t": "边鄙小县"}, {"w": "鄙邑", "t": "边城。"}]}, {"meaning": "郊野;郊外。", "cites": [{"t": "余睹李将军悛悛如鄙人。", "b": "《史记·李将军列传》"}], "words": [{"w": "鄙生", "t": "乡野儒生。"}]}, {"meaning": "小;狭。", "cites": [{"t": "询天下之异文鄙(琐屑)事以快言论。", "b": "清·刘开《问说》"}], "words": [{"w": "鄙狭", "t": "狭窄"}, {"w": "鄙吝", "t": "形容心胸狭窄。"}]}, {"meaning": "见识浅薄,行为低下。", "cites": [{"t": "以为鄙吝。", "b": "宋·司马光《训俭示康》"}, {"t": "人贱物亦鄙。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "肉食者鄙,未能远谋。", "b": "《左传·庄公十年》"}], "words": [{"w": "鄙朴", "t": "朴实粗俗"}, {"w": "鄙萎", "t": "丑陋而没有精神。"}]}, {"meaning": "粗俗,庸俗;质朴。", "cites": [{"t": "性好作诗,词语鄙俚。", "b": "《金史·斜卯爱实传》"}, {"t": "今之争斗,非鄙(粗俗,低下)也,财寡也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "鄙俚", "t": "乡土的、朴实的。也转为粗俗的意思"}, {"w": "鄙朴", "t": "朴实粗陋"}, {"w": "鄙秽", "t": "粗俗恶劣。"}]}, {"meaning": "自称的谦词。", "cites": [{"t": "鄙夫寡识。", "b": "张衡《东京赋》"}], "words": [{"w": "鄙老", "t": "老人自谦之词"}, {"w": "鄙事", "t": "对自己所做琐事的谦词。"}]}, {"meaning": "视为浅陋。", "cites": [{"t": "过我而不假道,鄙我也。", "b": "《左传·宣公十四年》"}, {"t": "孔子鄙其小器。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "鄙笑", "t": "轻视而嘲笑"}, {"w": "鄙厌", "t": "鄙视厌恶"}, {"w": "鄙慢", "t": "轻视怠慢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2904wx','嗦','1','suo','口','13','','[{"pinyin": "suo", "defs": [{"meaning": "—“哆嗦”（duōsuo）发抖,战栗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2905wx','愚','1','yú','心','13','','[{"pinyin": "yú", "defs": [{"meaning": "(会意。从心,从禺(yù)。从心,与性情有关。禺,猴属,兽之愚者。本义:愚蠢,愚昧)。"}, {"meaning": "同本义。", "cites": [{"t": "愚,戆也。", "b": "《说文》"}, {"t": "三赦,曰惷愚。", "b": "《周礼·司刺》"}, {"t": "靡哲不愚。", "b": "《诗·大雅·抑》"}]}, {"meaning": "又。", "cites": [{"t": "哲人之愚。", "b": ""}, {"t": "非是是非谓之愚。", "b": "《荀子·脩身》"}, {"t": "深知祸福谓之知,反知为愚。", "b": "《贾子道术》"}, {"t": "以惑愚瞽。", "b": "明·刘基《卖柑者言》"}, {"t": "使君一何愚。", "b": "《乐府诗集·陌上桑》"}, {"t": "愚人所为愚。", "b": "唐·韩愈《师说》"}, {"t": "愚者亦明。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "愚若胶柱", "t": "胶住调节乐弦的柱再去弹奏,只能弹出单一无变化的音调。比喻愚笨到像去胶柱,拘泥而不知变通"}, {"w": "愚戆", "t": "愚蠢而刚直"}, {"w": "愚騃", "t": "痴笨"}, {"w": "愚浊", "t": "愚笨;糊涂。"}]}, {"meaning": "自称之谦词。", "cites": [{"t": "愚以为营中之事。", "b": "诸葛亮《出师表》"}, {"t": "愚谓大计。", "b": "《资治通鉴》"}, {"t": "愚有片言,望丞相察之。", "b": "《三国演义》"}], "words": [{"w": "愚兄", "t": "对同辈而年轻于己者的自我谦称"}, {"w": "愚老", "t": "老人自谦之词"}, {"w": "愚臣", "t": "大臣对君主自称的谦词"}, {"w": "愚意", "t": "对自己意见的谦称"}, {"w": "愚怀", "t": "谦指己见。"}]}, {"meaning": "敦厚。", "cites": [{"t": "故《诗》之失愚,《书》之失诬。", "b": "《孔子家语》。王肃注:“愚,敦厚。”"}], "words": [{"w": "愚款", "t": "单纯朴实"}, {"w": "愚鲠", "t": "敦厚鲠直。"}]}, {"meaning": "蒙蔽;欺骗。", "cites": [{"t": "以愚黔首。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "愚学", "t": "愚弄儒学"}, {"w": "愚锢", "t": "愚弄禁锢"}, {"w": "愚聋", "t": "蒙蔽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2906wx','暖','1','nuǎn','日','13','','[{"pinyin": "nuǎn", "defs": [{"meaning": "(形声。从日,爰(yuán)声。“煗”,从火,耎(ruǎn)声。本义:温度不冷也不热) 同本义。", "cites": [{"t": "煖,温也。", "b": "《说文》。字亦作煗、作暖。"}, {"t": "海多大风,冬煗。", "b": "《国语·鲁语上》"}, {"t": "孔席不煗。", "b": "《汉书·系传上》"}, {"t": "七十非帛不煖。", "b": "《礼记·王制》"}, {"t": "清暖寒热,不得不救。", "b": "《韩非子·有度》"}, {"t": "爆竹声中一岁除,春风送暖入屠苏。", "b": "王安石《元日》"}, {"t": "早莺争暖树。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "狐裘不暖。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "歌台暖响。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "春江水暖鸭先知。", "b": "宋·苏轼《惠崇春江晚景》"}], "words": [{"w": "暖谷", "t": "冬温的山谷"}, {"w": "暖阳阳", "t": "形容温暖宜人"}, {"w": "暖景", "t": "春暖时的景色"}, {"w": "暖丝", "t": "形容温暖的感觉"}, {"w": "暖煦", "t": "温暖"}, {"w": "暖意", "t": "温暖的意味;温暖的情味"}, {"w": "暖炉", "t": "冬日御寒取暖的火炉"}, {"w": "暖霁", "t": "雨止天气和暖。"}]}, {"meaning": "使温暖。", "cites": [{"t": "到来日牵羊担酒,与叔父暖痛去。", "b": "李直夫《虎头牌》"}], "words": [{"w": "暖心话", "t": "使人心里感到温暖的话"}, {"w": "暖耳", "t": "保暖耳朵的器物"}, {"w": "暖酒", "t": "温酒"}, {"w": "把手暖一暖;兄弟情谊暖胸怀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2907wx','盟','1','méng','皿','13','','[{"pinyin": "méng", "defs": [{"meaning": "(会意。甲骨文字形,下面象个盘盂,中间放着牛耳。古代盟会要割牲歃(shà)血,主盟人手执牛耳,掘穴埋牲。本义:在神前发誓结盟)。"}, {"meaning": "同本义。", "cites": [{"t": "割牛耳盛朱盘,取其血歃于玉敦。", "b": "《说文》"}, {"t": "盟,歃血誓也。", "b": "《三苍》"}, {"t": "掌盟载之法。凡邦国有疑会同,则掌其盟约之载,及其礼仪,北面谓明神。", "b": "《周礼·司盟》"}, {"t": "掌盟诅。", "b": "《周礼·诅祝》。注:“盟诅,主于要誓,大事曰盟,小事曰诅。”"}, {"t": "约信曰誓,涖牲曰盟。", "b": "《礼记·曲礼》"}, {"t": "再会而盟。", "b": "《左传·昭公十三年》"}, {"t": "君子屡盟。", "b": "《诗·小雅·巧言》"}, {"t": "为坛而盟。", "b": "《史记·陈涉世家》"}, {"t": "秦伯说,与郑人盟。", "b": "《左传·僖公三十年》"}, {"t": "屈完及诸侯盟。", "b": "《左传·僖公四年》"}], "words": [{"w": "盟主", "t": "古代诸侯盟会中的领袖或主持者;泛指同盟首领或倡导者。喻主要的事物;主宰"}, {"w": "盟坛", "t": "古代缔结盟约时所设的坛场"}, {"w": "盟会", "t": "犹会盟。古代诸侯间的集会结盟。"}]}, {"meaning": "个人向天发誓,永不变心。", "cites": [{"t": "终待说山盟海誓,这恩情到此非容易。", "b": "赵长卿《贺新郎》"}], "words": [{"w": "盟文", "t": "盟誓的文辞"}, {"w": "盟契", "t": "盟约。又称盟要,盟信"}, {"w": "盟心", "t": "盟誓在心"}, {"w": "海誓山盟", "t": "对着山海盟誓。极言男女相爱,坚贞不渝。"}]}, {"meaning": "盟约;誓辞。", "cites": [{"t": "与结盟好。", "b": "《资治通鉴·赤壁之战》"}, {"t": "要盟也,神不听。", "b": "《史记·孔子世家》"}], "words": [{"w": "盟友;盟好", "t": "同盟友好。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2908wx','歇','1','xiē','欠','13','','[{"pinyin": "xiē", "defs": [{"meaning": "(形声。从欠。曷(hé)声。歇息与出气有关,故从“欠”。本义:休息)。"}, {"meaning": "同本义(侧重于放松身体的紧张状态以消除疲劳)。", "cites": [{"t": "歇,息也。", "b": "《说文》"}, {"t": "牛困人饥日已高,市南门外泥中歇。", "b": "唐·白居易《卖炭翁》"}, {"t": "彼时黛玉自在床上歇午,丫环们皆出去自便,满屋内静悄悄的。", "b": "《红楼梦》"}], "words": [{"w": "歇泊", "t": "休息"}, {"w": "歇子", "t": "小歇;稍憩"}, {"w": "歇午", "t": "歇中,歇晌。皆指午间休息"}, {"w": "歇夏", "t": "歇伏,伏天休息"}, {"w": "歇晚", "t": "晚上休息"}, {"w": "歇热", "t": "乘凉。"}]}, {"meaning": "停止,中止活动。", "cites": [{"t": "余韵徐歇。", "b": "宋·苏轼《石钟山记》"}, {"t": "声暂歇。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "骤雨初歇。", "b": "宋·柳永《雨霖铃》"}, {"t": "要歇业的店铺,暂时不准歇。", "b": "茅盾《动摇》"}], "words": [{"w": "歇令", "t": "停止,住手"}, {"w": "歇浪", "t": "关掉;打烊。"}]}, {"meaning": "留宿 。在旅店等处住宿。", "cites": [{"t": "张主管闲坐半晌,安排歇宿。", "b": "《京本通俗小说》"}], "words": [{"w": "歇家", "t": "旅舍;住宿处;兼搞跑腿、牵线的客店;客店主人"}, {"w": "歇卧", "t": "睡觉,过夜"}, {"w": "歇店", "t": "住客店;客店。"}]}, {"meaning": "竭,尽,到了尽头。", "cites": [{"t": "难未歇也。", "b": "《左传·襄公二十九年》"}, {"t": "灯青兰膏歇,落照飞蛾舞。", "b": "李贺《伤心行》"}], "words": [{"w": "歇绝", "t": "消失"}, {"w": "歇微", "t": "衰退消失"}, {"w": "歇灭", "t": "息灭,消失"}, {"w": "歇落 ", "t": "消失。"}]}, {"meaning": "凋零,花、木、草枯萎。", "cites": [{"t": "春木有荣歇,此节无凋零。", "b": "陈子昂《与东方左史虬修竹篇》"}]}, {"meaning": "气味散发;消散。", "cites": [{"t": "歇,气越泄。", "b": "《说文》"}]}, {"meaning": "曾经。", "cites": [{"t": "我屋里家主婆从来勿曾说歇,耐倒要管起我来哉。", "b": "《海上花列传》"}]}, {"meaning": "表示动作次数,相当于“番”、“次”。", "cites": [{"t": "又嘱咐两三歇。", "b": "《西厢记诸宫调》"}]}, {"meaning": "表示一段时间,相当于“一会儿”。", "cites": [{"t": "老身直去县前那家有好酒,买一瓶来,有好歇儿担阁。", "b": "《水浒传》"}, {"t": "好半歇到岸。", "b": "《反美华工禁约文学集》"}], "words": [{"w": "歇歇", "t": "一会儿,形容时间短"}, {"w": "歇子", "t": "一会儿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2909wx','暗','1','àn','日','13','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从日,音声。本义:昏暗)。"}, {"meaning": "同本义。与“明”相对。", "cites": [{"t": "暗,日无光也。", "b": "《说文》"}, {"t": "日中光明,故其出入时光暗,故大。", "b": "《论衡·说日》"}, {"t": "体之感何自起?曰,起于远近之比例,明暗之掩映。", "b": "蔡元培《图画》"}], "words": [{"w": "昏暗", "t": "光线不足"}, {"w": "暗中摸索", "t": "在黑暗中寻找探索。"}]}, {"meaning": "昏昧,愚昧;不明白。", "cites": [{"t": "上暗则政险。", "b": "《荀子·天率》"}], "words": [{"w": "暗昧", "t": "真假不明;暧昧,含糊不清"}, {"w": "暗主", "t": "昏庸的君主。"}]}, {"meaning": "隐秘。", "cites": [{"t": "别有幽愁暗恨生,此时无声胜有声。", "b": "白居易《琵琶行》"}], "words": [{"w": "暗记儿;暗号", "t": ""}]}, {"meaning": "默默地。", "cites": [{"t": "暗算乡程隔数州,欲归无计泪空流。", "b": "杜荀鹤《旅寓诗》"}, {"t": "孺人半夜觉寝,促有光暗诵。", "b": "归有光《先妣事略》"}], "words": [{"w": "暗诵", "t": "默诵,背诵"}, {"w": "暗数", "t": "默默记数"}, {"w": "暗写", "t": "默写。"}]}, {"meaning": "秘密;暗中。", "cites": [{"t": "曹节王甫,暗杀太后。", "b": "《后汉书·宦者传》"}, {"t": "孤犬无猛噬,长箭不暗射。", "b": "元好问《驱猪行》"}]}, {"meaning": "天黑。", "cites": [{"t": "车驾逼暗乃还,漏已尽。", "b": "《晋书·职官志》"}]}, {"meaning": "使昏暗。", "cites": [{"t": "大车扬飞尘,亭午暗阡陌。", "b": "李白《古风》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2910wx','暇','1','xiá','日','13','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从日,叚(xiá)声。本义:空闲,闲暇) 同本义。", "cites": [{"t": "暇,闲也。", "b": "《说文》"}, {"t": "不敢自暇自逸。", "b": "《书·无逸》"}, {"t": "好以瑕。", "b": "《左传·成公十六年》"}, {"t": "救亡不暇,安得王哉?", "b": "《韩非子·外储说右下》"}, {"t": "安得使予多暇日,又多闲由", "b": ""}]}, {"meaning": "——龚自珍《病梅馆记》。", "cites": [{"t": "将吊不暇。", "b": "《国语·晋语》"}, {"t": "炊不暇熟。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "暇时;暇刻", "t": "空闲的时间"}, {"w": "暇晷", "t": "空闲的时日"}, {"w": "暇景", "t": "空闲的时光。"}]}, {"meaning": "悠闲。", "cites": [{"t": "久之,且似瞑,意暇甚。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "暇裕", "t": "悠闲不迫"}, {"w": "暇适", "t": "闲暇舒适。"}]}, {"meaning": "从容,不慌不忙,大方自如。", "cites": [{"t": "谢便起舞,神意甚暇。", "b": "清·魏源《默觚下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2911wx','照','1','zhào','灬','13','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从火,昭声,字亦作炤。本义:明亮;光明) 同本义。", "cites": [{"t": "照,明也。", "b": "《说文》"}, {"t": "亦孔之炤。", "b": "《诗·小雅·正月》"}, {"t": "月出照兮。", "b": "《诗·陈风·月出》"}, {"t": "昔者十日并出,万物皆照。", "b": "《庄子》"}, {"t": "远近照闻。", "b": "《郯令景君阙铭》"}, {"t": "盛德炤明。", "b": "《谯敏碑》"}, {"t": "炤之以祸灾。", "b": "《荀子·修身》"}], "words": [{"w": "照彻", "t": "透明晶莹 "}, {"w": "照澄", "t": "明朗清爽“炤”。"}]}, {"meaning": "照射,照耀。", "cites": [{"t": "照耀煇煌。", "b": "《淮南子·本经》"}, {"t": "日月递炤。", "b": "《荀子·天论》。注:“炤与照同。”"}, {"t": "指日月使延照兮。", "b": "《楚辞·灵怀》。注:“知也。”"}, {"t": "照我秦氏楼。", "b": "《乐府诗集·陌上桑》"}, {"t": "寒光照铁衣。", "b": "《乐府诗集·木兰诗》"}, {"t": "留取丹心照汗青。", "b": "宋·文天祥《过零丁洋》"}, {"t": "星光照旷野。", "b": "明·魏禧《大铁椎传》"}, {"t": "日照城郭。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "回光反照;照烂", "t": "犹灿烂"}, {"w": "照覆", "t": "日照天覆。喻帝王之明睿恩威"}, {"w": "照焕", "t": "辉耀"}, {"w": "照夜", "t": "光耀黑夜中"}, {"w": "照灼", "t": "光芒四射;闪耀。"}]}, {"meaning": "映照;反射影像。", "cites": [{"t": "湖月照我影。", "b": "李白《梦游天姥吟留别》"}, {"t": "满园深浅色,照在绿波中。", "b": "唐·王维《游春曲二首》"}, {"t": "照花前后镜,花面交相映。", "b": "唐·温庭筠《菩萨蛮》"}], "words": [{"w": "照镜子;照见", "t": "以光照或反光物中映见"}, {"w": "照夜", "t": "光耀黑夜中"}, {"w": "照面", "t": "照见容颜。"}]}, {"meaning": "照顾;照料。", "cites": [{"t": "虽则是平分天道,高头偏俺照。", "b": "明·汤显祖《牡丹亭·虏谍》"}], "words": [{"w": "照觑", "t": "照顾;照料"}, {"w": "照庇", "t": "照应保护"}, {"w": "照呼", "t": "方言。照顾。"}]}, {"meaning": "察知;明白。", "cites": [{"t": "心照神交,惟我与子。", "b": "潘岳《夏侯常侍诛》"}], "words": [{"w": "照了", "t": "彻见;洞晓"}, {"w": "照知", "t": "明察"}, {"w": "照察 ", "t": "明察,照见"}, {"w": "照燎", "t": "明察"}, {"w": "照览", "t": "明察"}, {"w": "照鉴", "t": "明察"}, {"w": "查照;照奸", "t": "察知奸邪"}, {"w": "照微", "t": "察见隐微"}, {"w": "照得", "t": "查察而得。"}]}, {"meaning": "(zhào)。显示。", "cites": [{"t": "照乎知万物。", "b": "《管子·内业》"}, {"t": "不可以照期。", "b": "《文子缵义·精诚》"}, {"t": "彼日月之照明兮。", "b": "《楚辞·九辩》"}]}, {"meaning": "日光。", "cites": [{"t": "远岸秋沙白,连山晚照红。", "b": "杜甫《秋野》"}]}, {"meaning": "凭据;证明。", "cites": [{"t": "钱却有,何以为照。", "b": "《喻世明言》"}], "words": [{"w": "无照行车;照提", "t": "凭据。"}]}, {"meaning": "表示方向,可加助词“着”,相当于“对”、“向”。", "cites": [{"t": "过了一个小石桥,照着那极窄的石磴走上去,又是一座大庙。", "b": "《儒林外史》"}], "words": [{"w": "照着", "t": "对着;朝着。"}]}, {"meaning": "按,依。按原样或某种标准做。", "cites": [{"t": "凡分田,照人口,不论男妇。", "b": "太平天国《天朝田亩制度》"}], "words": [{"w": "照式", "t": "照样,按原样"}, {"w": "照例;照数", "t": "依照一定的数量。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2912wx','畸','1','jī','田','13','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从田,奇声。本义:零片的田地)。"}, {"meaning": "同本义。", "cites": [{"t": "畸,残田也。", "b": "《说文》。段注:“残田者,余田不整齐者也。”"}, {"t": "道千乘之国。", "b": "《论语·学而》。集解:“三百一十六里有畸。”"}], "words": [{"w": "畸余", "t": "未被侵占的残余土地"}, {"w": "畸零", "t": "小块零散土地。"}]}, {"meaning": "不整齐的,不正规的。", "cites": [{"t": "墨子有见于齐,无见于畸。", "b": "《荀子·天论》。注:“畸,谓不齐也。”"}], "words": [{"w": "畸形;畸态", "t": "畸形病态。"}]}, {"meaning": "脱俗的,超群的。", "cites": [{"t": "敢问畸人。", "b": "《庄子·大宗师》"}], "words": [{"w": "畸人", "t": "与世俗格格不入的人"}, {"w": "畸士", "t": "犹畸人。独行拔俗之人"}, {"w": "畸行", "t": "超俗的、非凡的行为"}, {"w": "畸民", "t": "畸客。高行拔俗之人。"}]}, {"meaning": "单数的,奇数的。跟“双”、“偶”相对。", "cites": [{"t": "畸人者,畸于人而侔于天。", "b": "《庄子·大宗师》。司马注:“畸,不耦也。”"}, {"t": "畸则不可为。", "b": "《荀子·天论》"}], "words": [{"w": "畸日", "t": "单日。即逢一、三、五、七、九等的日子。跟“双日”相对。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2913wx','跨','1','kuà','足','13','','[{"pinyin": "kuà", "defs": [{"meaning": "(形声。从足,夸声。本义:迈步,越过)。"}, {"meaning": "同本义。", "cites": [{"t": "跨,渡也。", "b": "《说文》。段注:“谓大其两股间,以有所越也。”"}, {"t": "不跨其国。", "b": "《国语·晋语》"}, {"t": "康王跨之。", "b": "《左传·昭公十三年》"}], "words": [{"w": "跨进大门;跨过小沟;跨蹑", "t": "跨踏;跨步"}, {"w": "跨巽", "t": "跨到或达到“巽”的方位"}, {"w": "跨火", "t": "跨过火堆。为一种民俗"}, {"w": "跨踪", "t": "跨越。"}]}, {"meaning": "超过。", "cites": [{"t": "乃览秦制,跨周法。", "b": "张衡《西京赋》"}], "words": [{"w": "跨灶", "t": "比喻儿子胜过父亲"}, {"w": "跨俗", "t": "超越世俗"}, {"w": "跨年", "t": "从旧年底到新年初的时间。"}]}, {"meaning": "骑。", "words": [{"w": "跨战马去草原;跨鹤", "t": "乘鹤。比喻成仙"}, {"w": "跨青牛", "t": "相传老子骑青牛出函谷关仙去。"}]}, {"meaning": "横于上。", "cites": [{"t": "跨谷弥阜。", "b": "《文选·张衡·西京赋》"}], "words": [{"w": "跨街楼", "t": "联结街道两旁楼房而横跨在街道上空的楼。又称过街楼"}, {"w": "跨所", "t": "跨院,正院旁边的院子"}, {"w": "跨虹", "t": "喻指拱形桥。"}]}, {"meaning": "挎。", "cites": [{"t": "智深到座前领了法贴,辞了长老,背上包裹,跨了戒刀禅杖。", "b": "《水浒传》"}], "words": [{"w": "跨菜篮子;跨刀", "t": "挎着腰刀。"}]}, {"meaning": "占据。", "cites": [{"t": "跨州连郡者不可胜数。", "b": "《三国志·诸葛亮传》"}]}, {"meaning": "又。", "cites": [{"t": "若跨有荆益。", "b": ""}], "words": [{"w": "跨蹈", "t": "占有"}, {"w": "跨据", "t": "据有"}, {"w": "跨有", "t": "据有。"}]}, {"meaning": "指两腿之间", "cites": [{"t": "能死,剌我;不能,出跨下。", "b": "《汉书·韩信传》"}], "words": [{"w": "跨下之辱", "t": "从他人胯下爬过去的屈辱。比喻胸怀大志的人,能忍辱负重"}, {"w": "跨下", "t": "两腿之间。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2914wx','跷','1','qiāo','足','13','','[{"pinyin": "qiāo", "defs": [{"meaning": "(形声。从足,尧声。本义:举足)。"}, {"meaning": "同本义。", "cites": [{"t": "蹻,举足行高也。从足,喬声。", "b": "《说文》"}, {"t": "可蹻足而待也。", "b": "《汉书·高帝纪》"}, {"t": "莫不蹻足抗首。", "b": "扬雄《长杨赋》"}], "words": [{"w": "跷蹄辇脚", "t": "高举脚,轻落足"}, {"w": "跷着腿坐着;跷足", "t": "举足"}, {"w": "跷腿", "t": "抬脚举步。"}]}, {"meaning": "踮起脚后跟。", "cites": [{"t": "跷起脚来,把一个一个脸面都看遍,哪个也不是菊英。", "b": "赵树理《三里湾》"}], "words": [{"w": "跷足", "t": "踮起脚跟。"}]}, {"meaning": "跛。", "cites": [{"t": "他一跷一拐地努力走着。", "b": "茅盾《脱险杂记》"}], "words": [{"w": "跷足", "t": "跛足"}, {"w": "跷脚", "t": "跛足;瘸腿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2915wx','跳','1','tiào','足','13','','[{"pinyin": "tiào", "defs": [{"meaning": "(形声。从足,兆声。本义:跃)。"}, {"meaning": "同本义。", "cites": [{"t": "跳,…一曰跃也。", "b": "《说文》"}, {"t": "特跳此者。", "b": "《左传·襄公二十五年》"}, {"t": "跳往助之。", "b": "《列子·汤问》"}, {"t": "狂生跳掷叫号", "b": ""}]}, {"meaning": "——清·纪昀《阅微草堂笔记》。", "words": [{"w": "跳蹋", "t": "由生气或着急而顿足"}, {"w": "跳索", "t": "杂技中的一种绳技"}, {"w": "跳鳞", "t": "跳出水面的鱼"}, {"w": "跳踯", "t": "上下跳跃。"}]}, {"meaning": "越过障碍 。", "words": [{"w": "跳墙;跳过篱笆;跳读", "t": "跳越章节读书"}, {"w": "跳墙蓦圈", "t": "指偷盗的行为"}, {"w": "跳门限", "t": "另换门庭"}, {"w": "跳河", "t": "越过河;投河。"}]}, {"meaning": "内动;一起一伏地跳 。", "words": [{"w": "心跳;眼皮跳;跳跃", "t": "跳动"}, {"w": "跳踉", "t": "跳跃;跳动"}, {"w": "跳峦", "t": "喻指起伏的山峦"}, {"w": "跳萧", "t": "扑腾,跳动。"}]}, {"meaning": "上冒;冒出 。", "words": [{"w": "跳显", "t": "显露;显示"}, {"w": "跳浪", "t": "冲动,激动"}, {"w": "跳蹙", "t": "形容水势汹涌奔腾"}, {"w": "跳波", "t": "翻腾的波浪"}, {"w": "跳沫", "t": "飞沫"}, {"w": "跳花", "t": "溅起来的水花"}, {"w": "跳石", "t": "矗出水面的石头。"}]}, {"meaning": "逃走。", "cites": [{"t": "汉王跳。", "b": "《史记·高祖纪》"}], "words": [{"w": "跳驱", "t": "疾速奔驰"}, {"w": "跳追", "t": "疾速追逐"}, {"w": "跳攻", "t": "快速奔袭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2916wx','跺','1','duò','足','13','','[{"pinyin": "duò", "defs": [{"meaning": "顿足,用脚猛力踏地", "words": [{"w": "跺脚", "t": "顿足,举脚猛力踩地"}, {"w": "跺蹬", "t": "跺足,跺脚"}, {"w": "跺泥", "t": "脚用力蹬地"}, {"w": "跺打", "t": "用力踩踏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2917wx','跪','1','guì','足','13','','[{"pinyin": "guì", "defs": [{"meaning": "(形声。从足,危声。本义:屈膝,单膝或双膝着地,臀部抬起,伸直腰股)。"}, {"meaning": "同本义。", "cites": [{"t": "跪,拜也。", "b": "《说文》"}, {"t": "跪,两膝拄地所以拜也。", "b": "《说文通训定声》"}, {"t": "仲宣跪而称曰。", "b": "《文选·谢庄·月赋》"}, {"t": "(乐羊子)一年来归,妻跪问其故。", "b": "《后汉书·列女传》"}, {"t": "秦王色挠,长跪而谢之。", "b": "《战国策·魏策》"}, {"t": "遥望老子杖藜而来,先生且喜且愕,舍狼而前,跪拜啼泣。", "b": "马中锡《中山狼传》"}], "words": [{"w": "授立不跪;长跪,半跪;跪拜;跪射;跪下祈祷;跪香拜佛", "t": "为长辈祈福寿的一种拜佛仪式。"}]}, {"meaning": "指足。", "cites": [{"t": "门者刖跪。", "b": "《韩非子·内储说下》"}], "words": [{"w": "蟹六跪", "t": "螃蟹六支脚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2918wx','路','1','lù','足','13','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从足,各声。本义:道路)。"}, {"meaning": "同本义。", "cites": [{"t": "路,道也。", "b": "《说文》"}, {"t": "路,途也。", "b": "《尔雅》"}, {"t": "百夫有洫,洫上有途,千户有浍,浍上有道,万夫有川,川上有路。", "b": "《周礼·地官》。注:“途容乘车一轨,道容二轨,路容三轨。”"}, {"t": "路漫漫其修远兮,吾将上下而求索。", "b": "屈原《离骚》"}, {"t": "遵彼大路兮。", "b": "《诗·郑风·遵大路》"}, {"t": "艮为径路。", "b": "《易·说卦》"}, {"t": "遂迷,不复得路。", "b": "陶潜《桃花源记》"}], "words": [{"w": "路奠", "t": "出殡时,亲友在灵柩经过的路上设供桌祭奠"}, {"w": "路赆", "t": "友人相赠的路费"}, {"w": "路引", "t": "行路的通行凭证"}, {"w": "路歧", "t": "路歧人。宋元时对沿街卖艺人的俗称;贫贱的人"}, {"w": "路次", "t": "路途,途中"}, {"w": "路村", "t": "因道路而形成的村落"}, {"w": "路票", "t": "通行证"}, {"w": "路货", "t": "在运输途中的货物"}, {"w": "路遥知马力,日久见人心", "t": "要走远路,才知道马力的强弱;结交朋友长久,才知人心的善恶。"}]}, {"meaning": "路程;行程。", "cites": [{"t": "缘溪行,忘路之远近。", "b": "陶潜《桃花源记》"}]}, {"meaning": "引申为思想或行动的途径。", "cites": [{"t": "登仕路。", "b": "清·周容《芋老人传》"}, {"t": "忠谏之路。", "b": "诸葛亮《出师表》"}, {"t": "顾未有路。", "b": "《史记·魏公子列传》"}], "words": [{"w": "路子", "t": "指门路。"}]}, {"meaning": "车。", "cites": [{"t": "筚路蓝缕,以启山林。", "b": "《左传·宣公十二年》"}, {"t": "乘大路趋越席以养安。", "b": "《荀子·正论》"}], "words": [{"w": "路车", "t": "古代诸侯乘坐的车子"}, {"w": "路马", "t": "古代天子、诸侯所乘路车的马。"}]}, {"meaning": "地区;方面;路线。", "cites": [{"t": "甘宁等三路战船,纵横水面。", "b": "《三国演义》"}], "words": [{"w": "路塍", "t": "田埂。"}]}, {"meaning": "比喻权位。", "cites": [{"t": "夫子当路于齐。", "b": "《孟子·公孙丑》"}]}, {"meaning": "宋元时行政区域名。", "cites": [{"t": "都督诸路军马。", "b": "宋·文天祥《指南录后序》"}, {"t": "烽火扬州路。", "b": "宋·辛弃疾《京口北固亭怀古》"}], "words": [{"w": "路分", "t": "宋元时路制的区域范围。"}]}, {"meaning": "经过。", "cites": [{"t": "路不周以左转兮,指西海以为期。", "b": "《楚辞·离骚》"}]}, {"meaning": "暴露。", "cites": [{"t": "彼可诈者,怠慢者也,路亶者也。", "b": "《荀子·议兵》"}]}, {"meaning": "败坏。", "cites": [{"t": "国家乃路。", "b": "《管子·四时》"}, {"t": "是率天下而路也。", "b": "《孟子·滕文公上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2919wx','跤','1','jiāo','足','13','','[{"pinyin": "jiāo", "defs": [{"meaning": "跟头。", "words": [{"w": "跌了一跤", "t": ""}, {"w": "摔跤", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2920wx','跟','1','gēn','足','13','','[{"pinyin": "gēn", "defs": [{"meaning": "(形声。从足,艮(gèn)声。本义:足后为跟)。"}, {"meaning": "同本义。", "cites": [{"t": "跟,足踵也。", "b": "《说文》"}, {"t": "足后曰跟,在下方着地,一体任之,象木根也。", "b": "《释名·释形体》"}, {"t": "阽焦原而跟趾。", "b": "张衡《思玄赋》"}, {"t": "诘曲犹能辨跟肘。", "b": "苏轼《凤翔八观》"}], "words": [{"w": "跟蹠", "t": "脚后跟"}, {"w": "跟踵", "t": "脚后跟"}, {"w": "跟胫", "t": "脚跟与小腿"}, {"w": "跟趾", "t": "脚后跟。"}]}, {"meaning": "器官的基底部分。亦指物体的底部或后部。", "cites": [{"t": "每册之跟,自书精楷以表之。", "b": "《清稗类钞·鉴赏类》"}], "words": [{"w": "崖跟", "t": "山崖底部"}, {"w": "跟底", "t": "底部。"}]}, {"meaning": "追随于后。", "cites": [{"t": "有元地脚保识人前去跟寻。", "b": "吴自牧《梦粱录》"}], "words": [{"w": "跟我来;跟他走;小偷一直跟着他;跟屁股", "t": "紧跟不舍。"}]}, {"meaning": "穿着(鞋),趿。", "cites": [{"t": "驾长檐车,跟高齿屐。", "b": "北齐·颜之推《颜氏家训》"}]}, {"meaning": "和,同。", "cites": [{"t": "甚么王八蛋的客,有胆子的快来跟三爷碰碰。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2921wx','遣','1','qiǎn','辶','13','','[{"pinyin": "qiǎn", "defs": [{"meaning": "(形声。从辵(chuò)。本义:释放)。"}, {"meaning": "同本义。", "cites": [{"t": "遣,纵也。", "b": "《说文》"}, {"t": "遣之日读诔。", "b": "《周礼·太史》。注:“谓祖庙之庭,大奠将行时也。”"}, {"t": "大丧饰遣车。", "b": "《周礼·巾车》"}, {"t": "书遣于策。", "b": "《仪礼·既夕礼》"}, {"t": "遣车视牢具。", "b": "《礼记·杂记》。“送葬载牲体之车也。”"}, {"t": "遣车一乘。", "b": "《礼记·檀弓》。注:“人臣赐车马者,乃得有遣车”。按,此字古专于用凶礼。"}], "words": [{"w": "遣俘", "t": "遣还俘虏"}, {"w": "遣还", "t": "犹遣返。"}]}, {"meaning": "派。派去。", "cites": [{"t": "赵王于是遂遣相如奉璧西入秦。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "权意不欲遣质。", "b": "《三国志·周瑜传》注"}, {"t": "乃遣张良往立信为齐王,征其兵击楚。", "b": "《史记·淮阴侯列传》"}, {"t": "愿勿遣。", "b": "汉·刘向《列女传》"}, {"t": "王终遣之。", "b": ""}, {"t": "太守即遣人随其往,寻向所志。", "b": "《桃花源记》"}, {"t": "遣李进诚。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "调遣", "t": "调派;差遣"}, {"w": "差遣", "t": "分派到外面去工作"}, {"w": "遣使", "t": "派遣使者"}, {"w": "遣人去请医生;遣价", "t": "差遣仆人"}, {"w": "遣官", "t": "派遣官员"}, {"w": "遣员", "t": "差遣人员"}, {"w": "遣军", "t": "派遣军队。"}]}, {"meaning": "贬谪;放逐。", "cites": [{"t": "姜氏与子犯谋醉而遣之。", "b": "《左传·僖公二十三年》"}, {"t": "遣归故郡。", "b": "《汉书·孔光传》"}, {"t": "帝不悦而遣太子。", "b": "《潜夫论》"}], "words": [{"w": "遣归", "t": "贬谪、释放或休弃而令归"}, {"w": "遣谪", "t": "流放边远地区"}, {"w": "遣刑", "t": "清代放逐犯人到极边远的地方去服苦役的刑罚"}, {"w": "遣斥", "t": "斥逐"}, {"w": "遣犯", "t": "指放逐在边地服刑的囚犯"}, {"w": "遣流", "t": "发配,流放。"}]}, {"meaning": "发送;打发。", "cites": [{"t": "笑而遣之。", "b": "宋·欧阳修《归田录》"}, {"t": "婿固不遣。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}, {"t": "厚资而遣之。", "b": "清·周容《芋老人传》"}, {"t": "时方冬停遣。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "遣日", "t": "打发时光,消遣"}, {"w": "遣书", "t": "发信"}, {"w": "遣发", "t": "打发,排遣"}, {"w": "遣闲", "t": "打发闲暇"}, {"w": "遣嫁", "t": "出嫁"}, {"w": "自遣", "t": "排遣愁闷,安慰自己。"}]}, {"meaning": "抒发。", "cites": [{"t": "奈何天,伤怀日,寂寥时,试遣愚衷。", "b": "《红楼梦》"}], "words": [{"w": "遣哀", "t": "抒发哀思"}, {"w": "遣欲", "t": "排除欲念"}, {"w": "遣除", "t": "犹排除"}, {"w": "遣恶", "t": "除恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2922wx','蜈','1','wú','虫','13','','[{"pinyin": "wú", "defs": [{"meaning": "节肢动物，由许多环节构成，每节有脚一对，头部的脚像钩子，能分泌毒液，捕食小虫，中医入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2923wx','蜗','1','wō','虫','13','','[{"pinyin": "wō", "defs": [{"meaning": "软体动物，有螺旋形扁圆的硬壳，头部有两对触角。吃嫩叶，对农作物有害。某些种类可供食用。", "words": [{"w": "蜗发", "t": "蜗牛状的发型,多为古代小儿发型"}, {"w": "蜗窄", "t": "像蜗壳那样窄小"}, {"w": "蜗角虚名", "t": "比喻很小的虚名"}, {"w": "蜗角蝇头", "t": "比喻极微小的利益"}, {"w": "蜗蜒", "t": "即蜗牛"}, {"w": "蜗跡", "t": "即蜗涎"}, {"w": "蜗痕", "t": "蜗涎。"}]}, {"meaning": "喻窄小的住所。"}, {"meaning": "软体动物，壳如笋状，螺层长，壳顶尖，生活于湖池中。"}, {"meaning": "软体动物，壳淡玳瑁色，壳口边缘略翻出，生活于湖溪中。亦称‘螺蛳’。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2924wx','蛾','1','é yǐ','虫','13','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从虫,我声。本义:蛾子。昆虫。形似蝴蝶,体躯一般粗大,四翅,静止时平放体侧。多在夜间飞行)。"}, {"meaning": "同本义。", "cites": [{"t": "禽兽虫蛾。", "b": "《列子·黄帝》"}, {"t": "朱蛾其状如蛾。", "b": "《山海经·海内北经》"}], "words": [{"w": "蛾罗", "t": "即蛾子"}, {"w": "蛾蝶", "t": "指飞蛾"}, {"w": "蛾眉", "t": "指飞蛾。"}]}, {"meaning": "蛾眉的简称。", "cites": [{"t": "扬蛾微眺。", "b": "魏·曹丕《答繁钦书》"}], "words": [{"w": "蛾黄", "t": "淡黄色"}, {"w": "蛾黛", "t": "女子画眉用的青黑色颜料。"}]}]}, {"pinyin": "yǐ", "defs": [{"meaning": "蚂蚁", "cites": [{"t": "扶服蛾伏。", "b": "《文选·扬雄》"}, {"t": "蜂蛾微命,力何固?", "b": "《楚辞》"}], "words": [{"w": "蛾子", "t": "幼蚁"}, {"w": "蛾附蜂屯", "t": "像蚂蚁和蜜蜂一样聚集"}, {"w": "蛾封", "t": "蚂蚁衔土于穴外堆成的小丘"}, {"w": "蛾斗", "t": "蚂蚁争斗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2925wx','蜂','1','fēng','虫','13','','[{"pinyin": "fēng", "defs": [{"meaning": "(形声。从虫,夆(fēng)声。本义:蜂,一种昆虫。有蜜蜂、胡蜂、细腰蜂等。特指“蜜蜂”)。"}, {"meaning": "同本义。", "cites": [{"t": "蜂,飞虫螫人者。", "b": "《说文》"}, {"t": "蜂虿有毒。", "b": "《左传·僖公十二年》"}, {"t": "蜂目而豺声。", "b": "《汉书·文元传》"}, {"t": "蜜为液,蜂则阳物也。", "b": "《论衡·言毒》"}], "words": [{"w": "蜂虿", "t": "蜂与蝎子。泛指小毒虫"}, {"w": "蜂臣", "t": "指蜂王以外的众蜂"}, {"w": "蜂扇蚁聚", "t": "蜂翅扇动,蚂蚁聚合。比喻人虽众多起不了大作用。"}]}, {"meaning": "比喻众多成群。", "cites": [{"t": "楚蜂起之将。", "b": "《史记·项羽本纪》"}, {"t": "蜂午并起。", "b": "《汉书·刘向传》"}, {"t": "谗言之徒蜂生。", "b": "《汉书·中山靖王胜传》"}, {"t": "乡民蚁拥蜂攒,布满山麓。", "b": "《广东军务记》"}], "words": [{"w": "蜂出", "t": "群拥而出"}, {"w": "蜂至", "t": "群集而至"}, {"w": "蜂溃", "t": "像蜂群四处飞散样逃亡"}, {"w": "蜂出泉流", "t": "像群蜂倾巢,如泉水涌流"}, {"w": "蜂合豕突", "t": "如群蜂聚集,似野猪奔突。比喻众人杂沓会合,横冲直撞"}, {"w": "蜂簇", "t": "群蜂簇拥。"}]}, {"meaning": "兵器的尖端。引申为锐势,势头。", "cites": [{"t": "今君起江东,楚蜂起之将皆争附君者,以君世世楚将,为能复立楚之后也。", "b": "《汉书·陈胜项籍传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2926wx','蜕','1','tuì','虫','13','','[{"pinyin": "tuì", "defs": [{"meaning": "(形声。从虫,兑(duì)声。本义:蝉、蛇之类脱皮去壳)。"}, {"meaning": "蝉、蛇等脱皮。亦谓鸟换羽。", "cites": [{"t": "蜕,蝉蛇所解皮也。", "b": "《说文》"}, {"t": "蝉蜕于浊秽。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "蜕蝉", "t": "蝉脱壳。"}]}, {"meaning": "尸体。", "cites": [{"t": "师素不立文字,临去乃为此,与遗蜕俱存。", "b": "《徐霞客游记》"}]}, {"meaning": "动物的化石。", "cites": [{"t": "于淮、济间得一龙蜕,长数十尺。", "b": "《五杂俎·卷九》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2927wx','嗅','1','xiù','口','13','','[{"pinyin": "xiù", "defs": [{"meaning": "(形声。从口,臭声。字本作“臭”,由“犬、自(鼻)”会意,狗的鼻子灵敏,善于闻嗅。本义:用鼻子辨别气味) 同本义。", "cites": [{"t": "食之则甘,嗅之则香。", "b": "《韩非子·外储说左下》"}], "words": [{"w": "嗅石", "t": "神兽名"}, {"w": "嗅闻", "t": "用鼻子辨别气味。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2928wx','嗡','1','wēng','口','13','','[{"pinyin": "wēng", "defs": [{"meaning": "飞虫特有的持续刺耳声或很快的不规则的震动产生的声音", "words": [{"w": "嗡嗡营营", "t": ""}, {"w": "嗡营", "t": ""}]}, {"meaning": "京二胡，胡琴的一种。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2929wx','嗓','1','sǎng','口','13','','[{"pinyin": "sǎng", "defs": [{"meaning": "喉咙", "words": [{"w": "嗓子", "t": ""}]}, {"meaning": "发音器官的声带及发出的声音", "words": [{"w": "嗓音", "t": ""}]}, {"meaning": "爱打击、揭发别人的短处或隐私", "words": [{"w": "嗓磕", "t": "讥笑,取笑"}]}, {"meaning": "[方言]吞塞", "cites": [{"t": "播开门闩钻进来,抹抹索索找饭嗓。", "b": "清·蒲松龄《聊斋俚曲集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2930wx','署','1','shǔ','罒','13','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从网,者声。部署任务,各有系统,故从网。本义:布置;部署)。"}, {"meaning": "同本义。", "cites": [{"t": "署,都署有所系属。", "b": "《说文》"}, {"t": "署,置也。", "b": "《广雅》"}, {"t": "署位之表也。", "b": "《国语·鲁语》"}, {"t": "部署诸将。", "b": "《汉书·高帝纪》"}], "words": [{"w": "部署", "t": "安排;布置"}, {"w": "署用", "t": "署理任用"}, {"w": "署事", "t": "处理事务"}, {"w": "署置", "t": "设置官署任用官吏。"}]}, {"meaning": "签名,签署。", "cites": [{"t": "吏呼名至史公,公瞿然注视,呈卷,即面署第一。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "冯湲署曰“能”。", "b": "《战国策·齐策》"}], "words": [{"w": "署笺", "t": "署名于章奏"}, {"w": "署券", "t": "签署券约"}, {"w": "署押", "t": "在文书上签名,押字"}, {"w": "署榜", "t": "开列姓名,张榜示人"}, {"w": "署议", "t": "上书议事。因上书须署名,故称"}, {"w": "署衔", "t": "加书官职品爵于姓名上。"}]}, {"meaning": "代理、暂任或试充官职。", "cites": [{"t": "署南平教谕。", "b": "《明史·海瑞传》"}, {"t": "太守宗资先闻其名,请署功曹,委任政事。", "b": "范晔《后汉书·范雎传》"}], "words": [{"w": "署印", "t": "代理官职"}, {"w": "署任", "t": "暂摄原任"}, {"w": "署缺", "t": "本官出缺,由他官暂代其职"}, {"w": "署事", "t": "官员任职,以一年为期的叫署事;代理管事"}, {"w": "署院", "t": "代理抚台"}, {"w": "署印老爷", "t": "代理官员。"}]}, {"meaning": "公署;官署。办理公务的机关。", "cites": [{"t": "署,官舍曰署。", "b": "《篇海类篇》。署使用于战国时期,常称官署,公署。"}, {"t": "夫署,所以朝夕虞君命也。", "b": "《国语·鲁语》"}, {"t": "宣帝即时召武待诏宦者署。", "b": "《汉书·苏武传》"}, {"t": "学士入署,常视日影为候。", "b": "《新唐书·李程传》"}], "words": [{"w": "署府", "t": "泛指官署。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2931wx','置','1','zhì','罒','13','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意。从网直,有亦声。网直宜赦。本义:赦罪,释放)。"}, {"meaning": "同本义。", "cites": [{"t": "置,赦也。", "b": "《说文》"}, {"t": "见十置一。", "b": "《汉书·尹赏传》。注:“放也。”"}, {"t": "高帝曰:“置之。”乃释通之罪。", "b": "《史记·淮阴侯列传》"}, {"t": "斩首捕虏,比三百石以上者皆杀之,无有所置。", "b": "《史记·吴王濞列传》"}]}, {"meaning": "安放;搁;摆。", "cites": [{"t": "覆杯水于坳堂之上,则芥为之舟,置杯焉则胶。", "b": "《庄子·逍遥游》"}, {"t": "项王则受璧,置之坐上。", "b": "《史记·项羽本纪》"}, {"t": "置酒长安道,同心与我违。", "b": "王维《送綦母潜落第还乡》"}], "words": [{"w": "置锥之地", "t": "安身立足之地"}, {"w": "置室", "t": "安置妻室;取妻"}, {"w": "置酒", "t": "陈设酒筵"}, {"w": "置社", "t": "古时大夫、士庶共同设置的供奉社神之所"}, {"w": "置立", "t": "设立"}, {"w": "安置;置措", "t": "措置"}, {"w": "置散", "t": "安置在闲散的职位"}, {"w": "置棋不定", "t": "弈棋时不知如何下子"}, {"w": "置锥之地", "t": "安放锥子的地方。比喻极狭小的、赖以安身立命的地方"}, {"w": "置手", "t": "插手。"}]}, {"meaning": "设置,建立,设立。", "cites": [{"t": "于是秦始征晋河东;置官司马。", "b": "《左传·僖公十五年》"}, {"t": "置园邑三百家。", "b": "《汉书·霍光传》"}, {"t": "置以为像兮。", "b": "《楚辞·屈原·九章》"}, {"t": "汉之所置傅相,方握其事。", "b": "汉·贾谊《汉安策》"}], "words": [{"w": "置社", "t": "“周”时大夫与庶民所共设置的社稷神"}, {"w": "置顿", "t": "设置供人停留和食宿的处所"}, {"w": "置都", "t": "建都。"}]}, {"meaning": "豁免。", "cites": [{"t": "晋王归晋阳,休兵行赏,命州县举贤才,黜贪残,置租赋,抚孤穷。", "b": "明·李贽《史纲评要·后梁纪》"}]}, {"meaning": "废弃;舍弃。", "cites": [{"t": "置大立少,乱之本也。", "b": "《晏子春秋·内篇谏上》"}, {"t": "沛公则置车骑。", "b": "《史记·项羽本纪》"}], "words": [{"w": "置之高阁", "t": "比喻弃置一旁,不睬不用"}, {"w": "置后", "t": "古时大夫死后无子,为死者别置后嗣、暂为丧主之称。"}]}, {"meaning": "搁置;放下;放在一边。", "cites": [{"t": "坎坎伐檀兮,置之河之干兮。", "b": "《诗·魏风·伐檀》"}, {"t": "且焉置土石。", "b": "《列子·汤问》"}], "words": [{"w": "置阁", "t": "耽搁;迟延"}, {"w": "置之不问", "t": "搁在一边,不予过问"}, {"w": "置之死地而后生", "t": "置于不战则死的境地,然后方能奋勇战斗,取胜得生。"}]}, {"meaning": "购买;置办。", "cites": [{"t": "郑人有且置履者。", "b": "《韩非子》"}], "words": [{"w": "置产", "t": "购置产业"}, {"w": "置田;置房子", "t": ""}]}, {"meaning": "(zhí)。树立。", "cites": [{"t": "凡试庐事置而摇之。", "b": "《周礼·考工记·庐人》"}, {"t": "夫孝置之而塞乎天地。", "b": "《礼记·祭义》"}]}, {"meaning": "古代传递文书的驿站。", "cites": [{"t": "五十里而一置。", "b": "《韩非子·难势》"}, {"t": "德之流行,速于置郵而传命。", "b": "《孟子·公孙丑上》"}]}, {"meaning": "驿车;驿马。", "cites": [{"t": "十里一置飞尘灰,五里一堠兵马催。", "b": "苏轼《荔枝叹》"}], "words": [{"w": "置邮", "t": "用马车传递文书信息。亦谓传递文书信息的驿站。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2932wx','罪','1','zuì','罒','13','','[{"pinyin": "zuì", "defs": [{"meaning": "(会意。从辛,从自,言罪人蹙鼻苦辛之忧,自亦声。本义:作恶或犯法的行为)。"}, {"meaning": "同本义。", "cites": [{"t": "辠,犯法也。", "b": "《说文》。秦以辠似皇字,改用罪。"}, {"t": "辜辟戾辠也。经传皆以罪为之。", "b": "《尔雅》"}, {"t": "畏此罪罟。", "b": "《诗·小雅·小明》"}, {"t": "君子以赦过宥罪。", "b": "《易·解卦象下传》"}, {"t": "无功不赏,无罪不罚。", "b": "《荀子·王制》"}, {"t": "离桓之罪。", "b": "《国语·晋语》"}, {"t": "或闻无罪。", "b": "《史记·陈涉世家》"}, {"t": "恶不忍闻,罪不容诛。", "b": "《汉书》"}, {"t": "治臣之罪。", "b": "诸葛亮《出师表》"}, {"t": "某知罪矣。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "罪首", "t": "罪魁祸首"}, {"w": "罪失", "t": "罪愆和过失"}, {"w": "罪眚", "t": "罪愆,罪过"}, {"w": "罪瑕", "t": "罪愆"}, {"w": "罪祸", "t": "罪愆"}, {"w": "罪累", "t": "罪过"}, {"w": "罪悔", "t": "罪过"}, {"w": "罪殃", "t": "罪过"}, {"w": "罪辜", "t": "罪咎"}, {"w": "罪衅", "t": "罪行;过恶"}, {"w": "罪例", "t": "犯罪的案例。"}]}, {"meaning": "罪人。", "cites": [{"t": "乃惟四方之多罪,逋逃是崇是长。", "b": "《书·牧誓》"}, {"t": "吾见强弩长戟,诛罪安民,以取公侯者有矣。", "b": "北齐·颜之推《颜氏家训》"}], "words": [{"w": "罪囚", "t": "罪犯"}, {"w": "罪孥", "t": "罪犯的家属"}, {"w": "罪徒", "t": "服刑的囚犯"}, {"w": "罪疾", "t": "邪恶的罪人"}, {"w": "罪脑", "t": "罪首"}, {"w": "罪隶", "t": "古时罪人家属之男性没入官府为奴者。"}]}, {"meaning": "过失;错误。", "cites": [{"t": "王曰:“此则寡人之罪也。”", "b": "《孟子·公孙丑下》"}, {"t": "此天之亡我,非战之罪也。", "b": "《史记》"}, {"t": "不替孟明,孤之过也。大夫问罪?且吾不以一眚掩大德。", "b": "《左传》"}], "words": [{"w": "罪诟", "t": "过错;诟病"}, {"w": "罪失", "t": "罪愆和过失"}, {"w": "罪负", "t": "过失。"}]}, {"meaning": "刑罚。", "cites": [{"t": "墨罪五百,劓罪五百…杀罪五百。", "b": "《汉书·刑法志》"}]}, {"meaning": "捕鱼竹网。", "cites": [{"t": "罪,捕鱼器", "b": "《字汇补》"}]}, {"meaning": "归罪于。", "cites": [{"t": "禹、汤罪己,其兴也悖焉。", "b": "《左传·庄公十一年》"}, {"t": "朕若罪宗宪,后日谁肯为国家任事?", "b": "明·孙高亮《于谦全传》"}], "words": [{"w": "不罪", "t": "不怪罪;不归罪于"}, {"w": "罪己", "t": "把罪咎归于自己"}, {"w": "罪谴", "t": "罪责"}, {"w": "罪坐", "t": "归罪;连坐。"}]}, {"meaning": "惩罚;治罪。", "cites": [{"t": "有过不罪,无功受赏,虽亡不变亦可乎?", "b": "《韩非子·五蠹》"}, {"t": "乃劝种麦,无或失时,行罪无疑。", "b": "《吕氏春秋》。高诱注:“罪,罚也。”"}, {"t": "宗宪无以罪。", "b": "《明史》"}], "words": [{"w": "罪人不孥", "t": "治罪止于本人,不累及妻和子女"}, {"w": "罪法", "t": "罪罚"}, {"w": "罪辱", "t": "处罚折辱"}, {"w": "罪律", "t": "治罪的律条。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2933wx','罩','1','zhào','罒','13','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从网,卓声。本义:捕鱼的竹笼)。"}, {"meaning": "同本义。", "cites": [{"t": "持罩入深水,金鳞大如手。", "b": "唐·温庭筠《罩鱼歌》"}], "words": [{"w": "罩罗", "t": "泛指捕鱼或捕鸟的竹器"}, {"w": "罩笼", "t": "泛指捕鱼的竹器。"}]}, {"meaning": "捕鸟的竹笼或掩网。", "cites": [{"t": "弛罩出凤雏。", "b": "三国魏·曹植《孟车篇》"}]}, {"meaning": "覆盖;套在外面。", "cites": [{"t": "荷塘烟罩小斋虚,景物皆宜入画图。", "b": "唐·司空图《王官》"}], "words": [{"w": "罩笼", "t": "笼罩"}, {"w": "罩褂", "t": "罩衣"}, {"w": "罩袖", "t": "方言。套在衣袖外面的套袖。"}]}, {"meaning": "超越。", "cites": [{"t": "其文博诞空类,大者罩天地之表,细者入毫纤之内。", "b": "晋·皇甫谧《三都赋序》"}], "words": [{"w": "罩过", "t": "超过;胜过。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2934wx','蜀','1','shǔ','虫','13','','[{"pinyin": "shǔ", "defs": [{"meaning": "(象形。从虫。上目象蜀头形,中象其身蜎蜎。本义:蛾蝶类的幼虫"}, {"meaning": "同本义。", "cites": [{"t": "蜀,葵中蚕也。", "b": "《说文》"}, {"t": "蜎蜎者蜀。", "b": "《诗·东山》。传:“桑蚕也。”"}, {"t": "欲小则化为蚕蠋。", "b": "《管子·水池》"}, {"t": "鳣似蛇,禹似蜀,人见蛇则惊骇,见蜀则毛起。", "b": "《韩非子》"}]}, {"meaning": "古族名、国名、郡名 ,在今四川一带。", "cites": [{"t": "蜀,西僻之国也。", "b": "《战国策·秦策》"}, {"t": "南取汉中,西举巴、蜀。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "蜀江", "t": "蜀郡之内的江河"}, {"w": "蜀魄", "t": "杜鹃鸟的代称。传说蜀君杜宇死后,他的魂魄化作杜鹃鸟"}, {"w": "蜀王春恨", "t": "传说杜鹃春天啼鸣时声音悲切,以致嘴角流血"}, {"w": "蜀郡", "t": "秦灭古蜀国,始置蜀郡"}, {"w": "蜀都", "t": "古代蜀国的都城"}, {"w": "蜀帝", "t": "泛指蜀的君主"}, {"w": "蜀叟", "t": "古族名。叟中一支"}, {"w": "蜀中", "t": "蜀,古国名,为秦所灭。有今四川省中部地。因泛称蜀地为“蜀中”"}, {"w": "蜀王", "t": "蜀国的君王"}, {"w": "蜀罗", "t": "蜀中织造的轻罗"}, {"w": "蜀道", "t": "蜀中的道路"}, {"w": "蜀栈", "t": "蜀中的栈道"}, {"w": "蜀本", "t": "宋时蜀中刻印的书"}, {"w": "蜀山", "t": "蜀地山岳的泛称"}, {"w": "蜀川", "t": "蜀地的川流"}, {"w": "蜀茶", "t": "蜀地所产的茶"}, {"w": "蜀客", "t": "指旅居在外的蜀人"}, {"w": "蜀国", "t": "泛指蜀地。"}]}, {"meaning": "朝代名 。三国时蜀汉的简称。旧地在今四川、云南、贵州一带。", "cites": [{"t": "蜀兵伤者极多。", "b": "《三国演义·失街亭》"}]}, {"meaning": "中国四川省的别称。", "cites": [{"t": "蜀之鄙有二僧。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "蜀刀", "t": "四川出产的小刀"}, {"w": "蜀桐", "t": "蜀地所产的桐木"}, {"w": "蜀都", "t": "古时四川称为蜀,蜀都指今四川省成都市。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2935wx','幌','1','huǎng','巾','13','','[{"pinyin": "huǎng", "defs": [{"meaning": "窗帘、帷幔。", "cites": [{"t": "幌,帷也。", "b": "《集韵》"}, {"t": "何时倚虚幌,双照泪痕干。", "b": "唐·杜甫《月夜》"}]}, {"meaning": "随意走动。", "cites": [{"t": "须是再多幌个时辰,才好去回话。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2936wx','错','1','cuò','钅','13','','[{"pinyin": "cuò", "defs": [{"meaning": "(形声。从金,昔声。本义:用金涂饰,镶嵌)。"}, {"meaning": "同本义。", "cites": [{"t": "错,金涂也。今所谓镀金。俗字作镀。", "b": "《说文》"}, {"t": "金银要饰谓之错镂。", "b": "《通俗文》"}, {"t": "鼎错日用而不足贵。", "b": "《淮南子·说山》"}], "words": [{"w": "错臂", "t": "用丹青画饰手臂。"}]}, {"meaning": "互相磨擦。", "cites": [{"t": "错,磨也。", "b": "《广雅》"}, {"t": "错者所以治锯。", "b": "《列女传·仁智》"}, {"t": "八卦相错。", "b": "《易·说卦》。虞注:“摩也。”"}], "words": [{"w": "错牙", "t": ""}]}, {"meaning": "杂。", "cites": [{"t": "错,杂也。", "b": "《小尔雅》"}, {"t": "错综其数。", "b": "《易·系辞传》"}, {"t": "交错以辩。", "b": "《仪礼·特牲礼》"}, {"t": "车错毂兮短兵接。", "b": "《楚辞·国殇》"}], "words": [{"w": "错石", "t": "彩石,错杂叠积各种石头而成文彩"}, {"w": "错列", "t": "错杂排列"}, {"w": "错戾", "t": "错杂,交杂"}, {"w": "错行", "t": "交替运行"}, {"w": "错落", "t": "交错纷杂。"}]}, {"meaning": "废弃。", "cites": [{"t": "殷既错天命。", "b": "《书·微子序》"}]}, {"meaning": "琢玉用的粗磨石。", "cites": [{"t": "锡贡磬错。", "b": "《书·禹贡》。孔传:“治玉石曰错。”"}]}, {"meaning": "适于磨光或磨快刀具的石头;磨石。", "cites": [{"t": "它山之石,可以为错。", "b": "《诗·小雅·鹤鸣》"}]}, {"meaning": "杂乱;交错。", "cites": [{"t": "觥筹交错。", "b": "欧阳修《醉翁亭记》"}, {"t": "而境界危恶,层见错出,非人世所堪。", "b": "文天祥《指南录·后序》"}], "words": [{"w": "错文", "t": "交错为文"}, {"w": "错落", "t": "不一致"}, {"w": "错合", "t": "交互配合。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2937wx','锚','1','máo','钅','13','','[{"pinyin": "máo", "defs": [{"meaning": "(形声。从金,苗声。本义:船停泊时所用的设备。一般为铁制或钢制)同本义 。如:锚具(船首两侧各有艏锚一具,另有备有锚、流锚及小型锚等);锚缆(系锚的粗绳或铁链);锚链孔(艏之两旁各有一小孔,以备起锚时将锚链由此孔收进,锚则紧贴于外之钢板上)。又指可以依靠的人或物(如在危急时)。如:我们以它作为系住灵魂的坚固牢靠的锚。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2938wx','锡','1','xī','钅','13','','[{"pinyin": "xī", "defs": [{"meaning": "化学名词。一种略带蓝色的白色光泽的低熔点金属元素,在化合物内是二价或四价,不会被空气氧化,主要以二氧化物(锡石)和各种硫化物(例如硫锡石)的形式存在 ——元素符号Sn。", "cites": [{"t": "金锡连丹。", "b": "《史记·货殖列传》"}], "words": [{"w": "锡古子", "t": "形如鼓的有盖锡锅。"}]}, {"meaning": "细麻布。", "cites": [{"t": "用锡若絺。", "b": "《仪礼·大射仪》"}, {"t": "于是郑女曼姬,被阿锡。", "b": "《史记·司马相如传》"}], "words": [{"w": "锡衣", "t": "细布所制的衣服"}, {"w": "锡衰", "t": "由平滑的细麻所制成的衣服。"}]}, {"meaning": "给予;赐给。", "cites": [{"t": "申锡无疆,及尔斯所。", "b": "《诗·商颂·烈祖》"}, {"t": "人有见宋王者,锡车十乘。", "b": "《庄子·列御寇》"}, {"t": "诗曰:“孝子不匮,永锡尔类。", "b": "《左传·隐公元年》"}, {"t": "老亲母若肯见教,胜予锡我百朋矣。", "b": "《宛如约》"}], "words": [{"w": "锡赉", "t": "赏赐"}, {"w": "锡命", "t": "天子赐与诸侯爵位、服饰等诰命。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2939wx','锣','1','luó','钅','13','','[{"pinyin": "luó", "defs": [{"meaning": "带卷边的青铜圆盘 ,通常用槌子击打就发出柔和而洪亮、能传得很远的声音。", "cites": [{"t": "鸣锣聚众。", "b": "《广东军务记》"}]}, {"meaning": "又。", "cites": [{"t": "鸣锣会集。", "b": ""}, {"t": "鸣锣传递。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2940wx','锤','1','chuí','钅','13','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从金,垂声。本义:古代重量单位) 同本义。"}, {"meaning": "八铢。", "cites": [{"t": "锤,八铢也。", "b": "《说文》"}, {"t": "有千金之璧,而无锱锤之礛诸。", "b": "《淮南子·诠言》"}]}, {"meaning": "十二两。", "cites": [{"t": "虽割国之锱锤以事人。", "b": "《淮南子·诠言》"}]}, {"meaning": "六铢。", "cites": [{"t": "铢六则锤。", "b": "《风俗通义》"}]}, {"meaning": "锤形物。", "cites": [{"t": "曾招渔侣下清浔,独茧初随一锤深。", "b": "唐·陆龟蒙《顷自桐江得一钓车》"}]}, {"meaning": "打;击。", "cites": [{"t": "千锤万凿出深山,烈火焚烧若等闲。", "b": "于谦《石灰吟》"}], "words": [{"w": "锤锻", "t": "锤击;锻造"}, {"w": "锤淬", "t": "锤击并淬火"}, {"w": "锤炉", "t": "锻打。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2941wx','锥','1','zhuī','钅','13','','[{"pinyin": "zhuī", "defs": [{"meaning": "(形声。从金,隹(zhuī)声。本义:钻孔的工具)。"}, {"meaning": "同本义。", "cites": [{"t": "锥,锐也。", "b": "《说文》"}, {"t": "锥,利也。", "b": "《释名·释用器》"}, {"t": "引锥自刺其股。", "b": "《战国策·秦策一》"}, {"t": "锥之处囊中。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "锥刀", "t": "用以雕刻的锥形小刀。比喻微小"}, {"w": "锥矢", "t": "一种税利的短箭"}, {"w": "锥囊", "t": "锥处囊中"}, {"w": "锥行衰", "t": "立锥形"}, {"w": "锥行之陈", "t": "前尖如锥的阵形"}, {"w": "锥毛", "t": "喻细微之物"}, {"w": "锥刀之末", "t": "比喻微小利益,也比喻小事。"}]}, {"meaning": "形如尖锥的东西。", "cites": [{"t": "疾如锥矢。", "b": "《淮南子·兵略》。注:“金镞翦羽之矢也。”"}, {"t": "冰销田地芦锥短,春入枝条柳眼低。", "b": "元稹《寄乐天诗》"}], "words": [{"w": "改锥;玄武岩锥;寄生熔岩锥;重力锥;视锥;生长锥;受精锥;测温锥", "t": ""}]}, {"meaning": "用锥刺。", "cites": [{"t": "苏生患睡,亲锥其股。", "b": "《新论》"}], "words": [{"w": "锥股", "t": "本苏秦夜读用锥自刺其股以解除睡意的故事。后用以比喻发愤求学"}, {"w": "锥书", "t": "装订书籍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2942wx','锦','1','jǐn','钅','13','','[{"pinyin": "jǐn", "defs": [{"meaning": "(形声。从帛,金声。本义:有彩色花纹的丝织品)。"}, {"meaning": "同本义。", "cites": [{"t": "锦,襄邑织文。", "b": "《说文》。朱骏声按,染丝织成文章也。汉襄邑县贡织文。”"}, {"t": "皆奉玉锦束请觌。", "b": "《仪礼·聘礼》。注:“玉锦,锦之文纤缛者也。”"}, {"t": "衣锦尚絅。", "b": "《礼记·中庸》"}, {"t": "锦衣狐裘。", "b": "《诗·秦风·终南》"}], "words": [{"w": "锦囊", "t": "锦制的袋子"}, {"w": "锦衾", "t": "锦制的大被"}, {"w": "锦帆", "t": "锦制的帆"}, {"w": "锦覆", "t": "以织锦遮掩羞丑,喻作美言庇护。"}]}, {"meaning": "比喻鲜艳华美的。", "cites": [{"t": "沙鸥翔集,锦鳞游泳。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "锦文", "t": "鲜明华丽的花纹"}, {"w": "锦石", "t": "有色彩花纹的石头"}, {"w": "锦瑟", "t": "装饰华丽的瑟"}, {"w": "锦币", "t": "鲜丽的彩帛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2943wx','键','1','jiàn','钅','13','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从金,建声。本义:鼎上贯通两耳的横杠)。"}, {"meaning": "同本义。", "cites": [{"t": "键,铉也。", "b": "《说文》。段玉裁注:“谓鼎扃也。以木横关鼎耳而举之。非是则既炊之鼎不可举也。故谓之关键。”"}]}, {"meaning": "车辖。安在车轴两端,管住车轮不脱离轴的铁棍。", "cites": [{"t": "键,一曰车辖也。", "b": "《说文》"}, {"t": "题无四寸之键,则车不行。", "b": "《尸子》"}]}, {"meaning": "钥匙。", "cites": [{"t": "诚九流之津涉,六艺之铃键。", "b": "汉·郭璞《尔雅序》"}, {"t": "户钥,自关而东,陈楚之间谓之键。", "b": "《方言五》"}]}, {"meaning": "竖着插的门闩。", "cites": [{"t": "横曰关,竖曰键。", "b": "《字书》"}, {"t": "五寸之键,制开阖之门。", "b": "《说苑·谈丛》"}], "words": [{"w": "键闭", "t": "门闩;锁钥。"}]}, {"meaning": "锁簧,也称“锁须”。", "cites": [{"t": "掌授管键,以启闭国门。", "b": "《周礼·司门》"}]}, {"meaning": "“关”、“键”连用,泛指门闩,后来比喻事物中最紧要的部分,起决定性的因素。", "cites": [{"t": "善闭,无关键而不可开。", "b": "《老子》"}, {"t": "神居胸臆,而志气统其关键。", "b": "《文心雕龙·神思》"}]}, {"meaning": "闩门。", "cites": [{"t": "于是键其门而去。", "b": "张读《宣室志》"}, {"t": "生丁其时命所存,六淫汹涌无键阍。", "b": "明·刘基《长歌行》"}], "words": [{"w": "键阍", "t": "关锁门户"}, {"w": "键关", "t": "闭门。喻入门的途径"}, {"w": "键户", "t": "关闭门户。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2944wx','锯','1','jù','钅','13','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从金,居声。本义:析解木石等的齿形工具)。"}, {"meaning": "同本义。", "cites": [{"t": "锯,枪唐也。", "b": "《说文》"}, {"t": "锯者所以治木也。", "b": "《列女传·仁智》。据古史考曰,孟庄子作锯,又按鲁语,中刑用刀锯。"}, {"t": "门者皆无得挟斧斤凿锯椎。", "b": "《墨子·备城门》"}], "words": [{"w": "手锯;电锯;拉锯;锯齿;锯梁", "t": "锯子当中支撑锯把的木梁。"}]}, {"meaning": "古刑具。", "cites": [{"t": "中刑用刀锯。", "b": "《国语·鲁语》"}], "words": [{"w": "刀锯", "t": "刀和锯,古代的刑具。"}]}, {"meaning": "用锯子切割。", "cites": [{"t": "绳锯木断,水滴石穿。", "b": "《鹤林玉露》"}], "words": [{"w": "锯木料;锯匠", "t": "锯木的工匠"}, {"w": "锯屑", "t": "锯木屑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2945wx','锰','1','měng','钅','13','','[{"pinyin": "měng", "defs": [{"meaning": "一种灰白色多价金属元素,通常硬而脆,类似铁但无磁性 ——元素符号为Mn。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2946wx','矮','1','ǎi','矢','13','','[{"pinyin": "ǎi", "defs": [{"meaning": "(形声。从矢,委声。本义:身材短)。"}, {"meaning": "同本义(古汉语多用短,少用矮)。", "cites": [{"t": "矮,短人也。", "b": "《说文新附》"}, {"t": "道州地产民多矮,每年常配乡户,竟以其男号为矮奴。", "b": "《旧唐书·阳城传》。"}], "words": [{"w": "又矮又胖;矮个", "t": "身材短小的人。"}]}, {"meaning": "低,不高。", "cites": [{"t": "矮墙低屋的,难道都不怕亲戚们听见笑话了吗?", "b": "《红楼梦》。"}], "words": [{"w": "矮屋", "t": "低小的小屋。"}]}, {"meaning": "情感不高尚的;卑下的。", "cites": [{"t": "当着矮人,别说矮话。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2947wx','辞','1','cí','辛','13','','[{"pinyin": "cí", "defs": [{"meaning": "(会意。本义:诉讼,打官司)。"}, {"meaning": "同本义。", "cites": [{"t": "辞,讼也。", "b": "《说文》。按,分争辩讼谓之辞。"}, {"t": "善于辞案条教。", "b": "《后汉书·周纡传》。注:“辞案犹今案牍也。”"}, {"t": "皇帝请问下民,鳏寡有辞于苗。", "b": "《书·吕刑》"}]}, {"meaning": "口供。", "cites": [{"t": "明清于单辞,无或私家于狱之两辞。", "b": "《书·吕刑》"}, {"t": "无情者不得尽其辞。", "b": "《礼记·大学》"}, {"t": "其次不辱辞令。", "b": "司马迁《报任少卿书》"}, {"t": "辞布者。", "b": "《周礼·司市故书》。司农注:“辞布,辞讼泉物者也。”"}, {"t": "狱辞无谋故者。", "b": "方苞《狱中杂记》"}, {"t": "有诏即讯,辞服。", "b": "《汉书·赵君韩张两王传》"}, {"t": "使犯死者自春而穷其辞。", "b": "柳宗元《断刑论下》"}]}, {"meaning": "言辞;文辞。", "cites": [{"t": "安定辞。", "b": "《礼记·曲礼》。疏:“言语也。”"}, {"t": "不以文害辞。", "b": "《孟子》。注:“诗人所歌咏之辞。”"}, {"t": "辞也者,兼异实之名,以论一意也。", "b": "《荀子·正名》。注:“说事之言辞。”"}, {"t": "欲以广主上之意,塞睚眦之辞。", "b": "司马迁《报任安书》"}]}, {"meaning": "又。", "cites": [{"t": "其次不辱辞令。", "b": ""}, {"t": "撰长书以为贽,辞甚畅达。", "b": "明·宋濂《送东阳马生序》"}, {"t": "其文约,其辞微,其志洁,其行廉。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "辞色", "t": "言辞和容色"}, {"w": "辞容", "t": "表情;面色"}, {"w": "辞旨", "t": "言语或文章的主旨、含意。"}]}, {"meaning": "特指政令之词。", "cites": [{"t": "近者奉辞伐罪,旄麾南指,刘琮束手。", "b": "《三国志》裴松之注引"}]}, {"meaning": "借口,口实。", "cites": [{"t": "君子疾夫舍日曰欲之而必为之辞。", "b": "《论语·季氏》"}, {"t": "曹公,豺虎也,挟天子以征四方,动以朝廷为辞。", "b": "《资治通鉴》"}], "words": [{"w": "辞头", "t": "说法;借口。"}]}, {"meaning": "中国古代一种介于诗歌和散文之间的体裁,也叫赋,或辞赋并称。", "cites": [{"t": "且携所著书及诗文辞稿本数册,家书一箧托焉。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "楚辞", "t": ""}]}, {"meaning": "说讲。", "cites": [{"t": "使人辞于狐突。", "b": "《礼记·檀弓》。注:“告也。”"}, {"t": "无辞不相接也。", "b": "《礼记·表记》。注:“辞所以通情也。”"}, {"t": "无伤也,请辞于军。", "b": "柳宗元《段太尉逸事状》"}]}, {"meaning": "辞别;告别。", "cites": [{"t": "朝辞白帝彩云间。", "b": "李白《早发白帝城》"}, {"t": "过北郭骚之门而辞。", "b": "《吕氏春秋·士节》。注:“辞者别也。”"}, {"t": "旦辞爷娘去,暮宿黄河边。", "b": "北朝乐府《木兰诗》"}, {"t": "故人西辞黄鹤楼。", "b": "李白《黄鹤楼送孟浩然之广陵》"}], "words": [{"w": "不辞而别;辞朝", "t": "进朝辞谢皇帝"}, {"w": "辞世颂", "t": "遗书"}, {"w": "辞年", "t": "辞岁。除夕之夜。"}]}, {"meaning": "推却不受。", "cites": [{"t": "以王父命辞父命。", "b": "《公羊传·哀公三年》"}, {"t": "“卿今当涂掌事,不可不学!”(吕)蒙辞以军中多务。", "b": "《资治通鉴》"}], "words": [{"w": "辞让", "t": "推让"}, {"w": "辞不获命", "t": "辞谢推让而未获允许。"}]}, {"meaning": "审讯。", "cites": [{"t": "单于使卫律召武受辞。", "b": "班固《汉书·李广苏建传》"}]}, {"meaning": "遣去。", "cites": [{"t": "郑穆公使视客馆,则束载、厉兵、秣马矣。使皇武子辞焉。", "b": "《左传》"}, {"t": "辞八人者,而后王安之。", "b": "《左传·襄公二十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2948wx','稚','1','zhì','禾','13','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从禾,隹(zhuī)声。本义:晚植的谷类。引申为幼禾)。"}, {"meaning": "同本义。", "cites": [{"t": "稺,幼禾也。", "b": "《说文》。字亦作穉,作稚。"}, {"t": "稚,幼稼也。", "b": "《韩诗传》"}, {"t": "考灵曜百谷稚熟。", "b": "《尚书》。注:“晚熟曰稚。”"}], "words": [{"w": "稚稼", "t": "迟期种植的稻谷。"}]}, {"meaning": "孩子,儿童。", "cites": [{"t": "使老稚转乎沟壑。", "b": "《孟子·滕文公上》"}], "words": [{"w": "稚年", "t": "少年;童年;幼年"}, {"w": "稚幼", "t": "幼儿,幼童"}, {"w": "稚乳", "t": "婴幼儿;孩童"}, {"w": "稚儿", "t": "幼儿;幼子。"}]}, {"meaning": "幼小;年幼(含有晚出生的意思,与“长”相对)。", "cites": [{"t": "言皆告稚子王。", "b": "《书·立政》"}, {"t": "樨朱颜只。", "b": "《楚辞·大招》。注:“幼也。”"}, {"t": "怀王稚子。", "b": "《史记·屈原贾生列传》"}, {"t": "稚子侯门。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "稚态", "t": "幼儿的神情;天真的情态"}, {"w": "稚女", "t": "幼女;少女"}, {"w": "稚小", "t": "幼小;年少"}, {"w": "稚弟", "t": "幼弟;年小的弟弟"}, {"w": "稚幼", "t": "幼小;幼稚无知。"}]}, {"meaning": "物体细小。", "cites": [{"t": "盖稚水流耳。", "b": "《水经注》"}, {"t": "纯雄其名樨蜂。", "b": "《列子·无瑞》。注:“小也。”"}], "words": [{"w": "稚钱", "t": "梁武帝时官铸的小钱"}, {"w": "稚榻", "t": "小床"}, {"w": "稚蜂", "t": "蜂名;小蜂"}, {"w": "稚犬", "t": "小狗。"}]}, {"meaning": "古称妇女年不到五十。", "cites": [{"t": "卫之稚质。", "b": "《淮南子·脩务》。注:“亦少女也。”"}], "words": [{"w": "稚妻", "t": "年少之妻"}, {"w": "稚质", "t": "年少貌美的女子"}, {"w": "稚秀", "t": "年轻秀丽。"}]}, {"meaning": "晚;暮。", "cites": [{"t": "曙戒勿怠,后稚逢殃。", "b": "《管子》"}], "words": [{"w": "稚颜", "t": "童颜。"}]}, {"meaning": "骄傲放纵;傲慢。", "cites": [{"t": "而工以雕文刻镂相稚也,谓之逆。", "b": "《管子》。尹知章注:“稚,骄也。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2949wx','稠','1','chóu','禾','13','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从禾,周声。本义:禾多而密)。"}, {"meaning": "多。", "cites": [{"t": "稠,多也。", "b": "《说文》。按,禾多也。"}, {"t": "歌者稠。", "b": "《礼记·文王世子》注"}, {"t": "书策稠浊。", "b": "《战国策·秦策》。注:“多也。”"}, {"t": "稠人广众。", "b": "《汉书·灌夫传》"}, {"t": "忆往者峥嵘岁月稠。", "b": "毛泽东《沁园春·长沙》"}], "words": [{"w": "稠人", "t": "众人"}, {"w": "稠人广坐", "t": "很多人聚会的场所"}, {"w": "稠伙", "t": "犹稠众"}, {"w": "稠众", "t": "众多。"}]}, {"meaning": "繁密。", "cites": [{"t": "稠,密也。", "b": "《玉篇》"}]}, {"meaning": "亦作“绸”。", "cites": [{"t": "绸直如发。", "b": "《诗·小雅·都人》。传:“密直如发也。”"}], "words": [{"w": "稠云", "t": "密集的云"}, {"w": "稠掩掩", "t": "密集而隐约无光"}, {"w": "稠林", "t": "密林。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2950wx','颓','1','tuí','页','13','','[{"pinyin": "tuí", "defs": [{"meaning": "(会意。从页（xié）,从秃。页,人头。本义:头秃。原作“穨”)。"}, {"meaning": "同本义。本作“跕”。", "cites": [{"t": "穨,秃貌。从秃,贵声。", "b": "《说文》。字亦作颓。"}, {"t": "颓,首秃也。", "b": "《六书故》"}]}, {"meaning": "委靡,消沉。", "cites": [{"t": "颓然乎其间。(颓然,形容醉倒的样子。)", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "颓卒", "t": "委靡衰老的士卒"}, {"w": "颓思", "t": "颓丧的心意"}, {"w": "颓尔", "t": "厌伏不振貌"}, {"w": "颓堕委靡", "t": "体力精神衰退不振。"}]}, {"meaning": "詈词。恶劣之意。", "cites": [{"t": "今日颓天,百般的难得晚。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "下坠。也作“隤”。", "cites": [{"t": "泰山其颓乎?", "b": "《礼记·檀弓上》"}, {"t": "嗣业是步士升山,颓石四面以击贼。", "b": "《新唐书》"}]}, {"meaning": "也指暴风从上而下。", "cites": [{"t": "习习谷风,维风及颓。", "b": "《诗·小雅·谷风》"}, {"t": "焚轮谓之颓。", "b": "《尔雅》。李注:“暴风从上下降谓之颓。颓,下也。”"}, {"t": "颓乎其顺也。", "b": "《礼记·檀弓》"}]}, {"meaning": "倾斜;衰败。", "cites": [{"t": "[马]尻欲颓而方。", "b": "《齐民要术》。石声汉校释:“[马的]臀部要斜下,要方正。”"}]}, {"meaning": "坍塌,崩坏。", "cites": [{"t": "似这般都付与断井颓垣。", "b": "明·汤显祖《牡丹亭·惊梦》"}], "words": [{"w": "颓剥", "t": "颓坏剥落"}, {"w": "颓云", "t": "坠落的云"}, {"w": "颓垣", "t": "倾塌的墙"}, {"w": "颓唐", "t": "陨坠貌"}, {"w": "颓关", "t": "倾塌缺损"}, {"w": "颓裂", "t": "崩裂。"}]}, {"meaning": "衰微;衰败;敝败。", "cites": [{"t": "晋风日已颓。", "b": "李白《古风五十九首》"}, {"t": "汉室倾颓,奸臣窃命,主上蒙尘。", "b": "陈寿《隆中对》"}, {"t": "风俗颓弊。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "颓惰", "t": "懈怠;堕落"}, {"w": "颓陵", "t": "衰替"}, {"w": "颓法", "t": "敝败的法典"}, {"w": "颓败", "t": "犹败坏"}, {"w": "颓坏", "t": "败坏"}, {"w": "颓亏", "t": "衰败缺损"}, {"w": "颓毁", "t": "毁坏"}, {"w": "颓替", "t": "犹陵夷;衰颓"}, {"w": "颓弛", "t": "脱落;弃置。"}]}, {"meaning": "雄马生殖器。", "cites": [{"t": "有汗时休去檐下拴,渲时休教侵着颓。", "b": "元·马致远《耍孩儿》"}]}, {"meaning": "颊下。", "cites": [{"t": "颓,颊下。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2951wx','愁','1','chóu','心','13','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从心,秋声。字亦作“愀”。本义:忧虑,发愁)。"}, {"meaning": "同本义。", "cites": [{"t": "愁,忧也。", "b": "《说文》"}, {"t": "孔子愀然作色而对。", "b": "《礼记·哀公问》"}, {"t": "见善愀然。", "b": "《荀子·脩身》"}, {"t": "哀而不愁,乐而不荒。", "b": "《左传·襄公二十九年》"}, {"t": "暝色入高楼,有人楼上愁。", "b": "李白《菩萨蛮》"}, {"t": "江晚正愁余,山深闻鹧胡。", "b": "辛弃疾《菩萨蛮》"}, {"t": "白发三千丈,缘愁似个长。", "b": "李白《秋浦歌》"}, {"t": "莫愁前路无知己,天下谁人不识君!", "b": "高适《别董大》"}], "words": [{"w": "不愁吃,不愁穿;愁坐", "t": "含忧默坐"}, {"w": "愁思", "t": "忧愁的心绪"}, {"w": "愁绝", "t": "忧愁到极点"}, {"w": "愁怀勃勃", "t": "心中有万端愁绪;非常忧戚"}, {"w": "愁海", "t": "比喻愁深。"}]}, {"meaning": "使受苦。", "cites": [{"t": "伤形费神,愁力劳意。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2952wx','筹','1','chóu','竹','13','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从竹,夀声。本义:计数的用具)。"}, {"meaning": "壶矢。古代投壶用的签子,形如箭笴。", "cites": [{"t": "筹,壶矢也。", "b": "《说文》。谓投壶之矢为 筹。"}, {"t": "筹室中五扶。", "b": "《礼记·投壶》。注:“矢也。”"}, {"t": "箭筹八十。", "b": "《仪礼·乡射礼》"}]}, {"meaning": "签筹;算筹 。木或象牙等制成的小棍儿或小片儿,用来计数或作为领取的物品的凭证。", "cites": [{"t": "射者中,弈者胜,觥筹交错。", "b": "欧阳修《醉翁亭记》"}], "words": [{"w": "竹筹;筹马", "t": "古时投壶计数的用具。"}]}, {"meaning": "算计。", "cites": [{"t": "运筹帷幄之中。", "b": "《史记·高祖纪》"}], "words": [{"w": "筹设", "t": "计划设置"}, {"w": "筹计", "t": "盘算"}, {"w": "筹昏", "t": "谓无法算计。"}]}, {"meaning": "策划。", "cites": [{"t": "命康与四卿及同志速设法筹救。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "统筹", "t": "统一筹划"}, {"w": "筹运", "t": "制定策略;谋划。犹运筹"}, {"w": "筹历", "t": "推算历法。"}]}, {"meaning": "条,个,位。用以指人的多少。", "cites": [{"t": "背后只见赶上三筹好汉,也将杀来。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2953wx','签','1','qiān','竹','13','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从竹,佥声。本义:署名押字)。"}, {"meaning": "公文体制的一种。"}, {"meaning": "标识,标签。", "cites": [{"t": "籤,验也。", "b": "《说文》"}, {"t": "记识曰籤。与检略同。", "b": "《通俗文》"}], "words": [{"w": "书签;签题", "t": "书册的标签"}, {"w": "签筹", "t": "古代滴水计时器中指示时刻的指针"}, {"w": "标签;浮签;签帙", "t": "标签和书套"}, {"w": "签轴", "t": "加有标签便于检取的卷轴"}, {"w": "签牌", "t": "标签。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2954wx','简','1','jiǎn','竹','13','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从竹,间声。本义:竹简。古代书写了文字的狭长竹片)。"}, {"meaning": "同本义。战国至魏晋时代的书写材料,是削制成的狭长竹片或木片,竹片称“简”,木片称“札”或“牍”,统称为“简”。若干简编缀在一起的叫“策”(册)。", "cites": [{"t": "畏此简书。", "b": "《诗·小雅·出车》"}, {"t": "执简记。", "b": "《礼记·王制》。注:“策书也。”"}, {"t": "小简而长。", "b": "《考工记·弓人》"}, {"t": "昭王读法十余简而睡卧矣。", "b": "《韩非子·外储说左下》"}, {"t": "南史氏闻太史尽死,执简以往。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "简素", "t": "竹简与缣素。古代用来记载文字的竹帛"}, {"w": "简书", "t": "古代的公文书于竹简,称为简书"}, {"w": "简札", "t": "古代用以书写的竹简木札"}, {"w": "简帛", "t": "简牍与帛。古代书写用品。"}]}, {"meaning": "书籍;信札。", "cites": [{"t": "呻吟槁简,诵死人之语。", "b": "《盐铁论·大论》"}, {"t": "辱致来简,受赐无量。", "b": "柳宗元《答贡士元公瑾论仕进书》"}], "words": [{"w": "简末", "t": "文牍书简末幅"}, {"w": "简策", "t": "指书籍"}, {"w": "简囊", "t": "装书籍的袋子"}, {"w": "简书", "t": "泛指文书,信札。"}]}, {"meaning": "古兵器。鞭类。", "cites": [{"t": "其人年少,虎体人形,腕悬铁简,身挂绿袍。", "b": "《薛仁贵征辽事略》"}], "words": [{"w": "简格", "t": "盛放弩矢的用具及放刀剑的架子。"}]}, {"meaning": "水名 。古黄河下游的支流之一,故道约在今山东省阳信县、栗陵县境。"}, {"meaning": "简省;简易;简单。", "cites": [{"t": "繁文简节之音作。", "b": "《礼记·乐记》。注:“少易也。”"}, {"t": "未为简易。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "郦元之简。", "b": "宋·苏轼《苏东坡全集·石钟山记》"}], "words": [{"w": "简绝", "t": "简练,爽快"}, {"w": "简至", "t": "治事简易,思想通达"}, {"w": "简编凛烈", "t": "历史是无情的"}, {"w": "简选", "t": "简择选拔"}, {"w": "简阔", "t": "简略宽疏。"}]}, {"meaning": "大。", "cites": [{"t": "吾党之小子狂简。", "b": "《论语》"}, {"t": "周之简圭。", "b": "《淮南子·说山》"}], "words": [{"w": "简圭", "t": "大的玉圭"}, {"w": "简珠", "t": "大珠。"}]}, {"meaning": "选择。", "cites": [{"t": "简能而用。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "盖简桃核。", "b": "清·魏学洢《核舟记》"}], "words": [{"w": "简放", "t": "选出遣散"}, {"w": "简界", "t": "精选之后"}, {"w": "简选", "t": "简择选拔"}, {"w": ";简卜", "t": "择日卜问"}, {"w": "简才", "t": "选择贤才"}, {"w": "简用", "t": "选用"}, {"w": "简拔", "t": "选拔,选用提拔。"}]}, {"meaning": "检查;检验。", "cites": [{"t": "细细简认,件件都是王庆的。", "b": "《水浒传》"}], "words": [{"w": "简尸", "t": "验尸"}, {"w": "简较", "t": "查阅;核对"}, {"w": "简验", "t": "检查验看"}, {"w": "简孚", "t": "稽核属实,真确可信。"}]}, {"meaning": "谏诤,直言规劝。", "cites": [{"t": "犹之未远,是用大简。", "b": "《左传·成公八年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2955wx','筷','1','kuài','竹','13','','[{"pinyin": "kuài", "defs": [{"meaning": "夹饭或其他东西用的一对细棍儿", "words": [{"w": "筷筒", "t": "盛放筷子的器具"}, {"w": "筷箧", "t": "盛放筷子的小盒"}, {"w": "筷笼子", "t": "即筷筒"}, {"w": "牙筷", "t": ""}, {"w": "竹筷", "t": ""}, {"w": "碗筷", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2956wx','毁','1','huǐ','殳','13','','[{"pinyin": "huǐ", "defs": [{"meaning": "(形声。从“土”,表示与瓦器有关。本义:瓦器缺损)。"}, {"meaning": "毁坏;破坏。", "cites": [{"t": "毁山一毛。", "b": "《列子·汤问》"}, {"t": "毁于椟中。", "b": "《论语·季氏》"}, {"t": "毁其外门。", "b": ""}, {"t": "毁其盆。", "b": "清·龚自珍《病梅馆记》"}, {"t": "毁,缺也。", "b": "《说文》。段注:“缺者,器破也,因为凡破之称。”"}, {"t": "毁,坏也。", "b": "《小尔雅·广言》"}, {"t": "不敢毁伤。", "b": "《孝经·开宗明义》"}, {"t": "兑为毁折。", "b": "《易·说卦传》"}, {"t": "毁泉台。", "b": "《春秋·文公十六年》"}, {"t": "毁信废忠。", "b": "《左传·文公十八年》"}, {"t": "然明谓子产曰:“毁乡校何如?”", "b": "《左传·襄公三十一年》"}, {"t": "毁人之国,而非久也。", "b": "《孙子·谋攻》"}], "words": [{"w": "毁弃", "t": "损坏废弃"}, {"w": "毁节", "t": "败坏操守"}, {"w": "毁车杀马", "t": "毁坏车马。表示隐退不仕"}, {"w": "毁夷", "t": "摧毁夷平。"}]}, {"meaning": "哀毁,旧指居丧时因悲哀过度而损害健康。", "cites": [{"t": "毁不危身。", "b": "《礼记·檀弓》。注:“憔悴将灭性。”"}], "words": [{"w": "毁疾", "t": "守丧时因过分哀伤而生病"}, {"w": "毁瘠", "t": "因哀伤过度而瘦得皮包骨"}, {"w": "毁颜", "t": "面有忧色"}, {"w": "毁死", "t": "因居丧过哀致死"}, {"w": "毁病", "t": "因居丧过哀而生病。"}]}, {"meaning": "废除,除去。", "cites": [{"t": "至于庙门不毁墙。", "b": "《礼记·杂记上》"}]}, {"meaning": "败坏;灭。", "cites": [{"t": "壹毁魏氏之威。", "b": "《战国策·秦策》。注:“败也。”"}, {"t": "自毁其家。", "b": "《左传·庄公三十年》"}], "words": [{"w": "烧毁;焚毁", "t": ""}]}, {"meaning": "掉落。", "cites": [{"t": "男八岁毁齿,女七岁毁齿。", "b": "《白虎通·嫁娶》"}], "words": [{"w": "毁齿", "t": "儿童乳齿脱落,更换新齿;又指换齿的儿童,指童年或少年时。"}]}, {"meaning": "毁谤。", "cites": [{"t": "每言未尝不毁孟尝君也。", "b": "《战国策·齐策》。注:“谤也。”"}, {"t": "德高而毁来。", "b": "唐·韩愈《原毁》"}, {"t": "舅姑毁黜。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "毁言", "t": "毁谤的言论"}, {"w": "毁诋", "t": "毁谤"}, {"w": "毁訾", "t": "恶骂"}, {"w": "毁短", "t": "揭发诽谤他人的短处"}, {"w": "毁誉相半", "t": "毁谤和称誉各半。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2957wx','舅','1','jiù','臼','13','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。从男,臼声。本义:舅父,指母之兄或弟)。"}, {"meaning": "同本义。", "cites": [{"t": "母之兄、弟。妻之父为外舅,从男,臼声。凡异姓之称,不得称父,则舅之。", "b": "《说文》"}, {"t": "王之元舅。", "b": "《诗·大雅·崧高》"}, {"t": "于舅家见。", "b": "宋·王安石《伤仲永》"}, {"t": "复到舅家。", "b": ""}], "words": [{"w": "舅氏", "t": "对舅的尊称"}, {"w": "舅公", "t": "父亲的舅父"}, {"w": "舅弟", "t": "舅父的儿子,年纪小于自己的。即表弟"}, {"w": "舅兄", "t": "舅父之子年长于己者。"}]}, {"meaning": "称妻之父。", "cites": [{"t": "婿亲迎,见于舅姑。", "b": "《礼记·坊记》"}]}, {"meaning": "古时天子称异姓大邦诸侯为伯舅,异姓小邦诸侯为叔舅。又诸侯称异姓大夫为舅。", "cites": [{"t": "小邦则曰叔舅。", "b": "《仪礼·觐礼》"}, {"t": "使孔赐伯舅胙。", "b": "《左传·僖公九年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2958wx','鼠','1','shǔ','鼠','13','','[{"pinyin": "shǔ", "defs": [{"meaning": "(象形。头部象锐利的鼠牙,下象足、脊背、尾巴形。本义:老鼠)。"}, {"meaning": "同本义。", "cites": [{"t": "鼠,穴虫之总名也。", "b": "《说文》"}, {"t": "谁谓鼠无牙?", "b": "《诗·召南·行露》"}, {"t": "鼠小虫,性盗窃。", "b": "《汉书·五行志》"}, {"t": "鼠者,人之所薰也。", "b": "《说苑·善说》"}, {"t": "里谚曰:“欲投鼠而忌器。”", "b": "汉·贾谊《陈政事疏》"}, {"t": "逆夷各狐凭鼠伏。", "b": "《三元里人民抗英》"}], "words": [{"w": "鼠窜而狼忙", "t": "形容逃窜得匆忙狼狈"}, {"w": "鼠牙雀角", "t": "比喻强暴侵凌,引起争讼"}, {"w": "鼠盗蜂起", "t": "封建统治阶级对小股农民起义的污蔑"}, {"w": "鼠腹蜗肠", "t": "形容器量狭小"}, {"w": "鼠市", "t": "一种戏鼠的器具"}, {"w": "鼠布", "t": "以鼠毛制成的布"}, {"w": "鼠裘", "t": "用鼠皮制的裘袍。"}]}, {"meaning": "十二生肖之一。", "cites": [{"t": "昔在武川镇生汝兄弟,大者属鼠,次者属兔,汝身属蛇。", "b": "《周书》"}]}, {"meaning": ",忧;病。", "cites": [{"t": "鼠思泣血。", "b": "《诗·小雅·雨无止》"}, {"t": "狸头愈鼠,鸡头已瘘。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2959wx','催','1','cuī','亻','13','','[{"pinyin": "cuī", "defs": [{"meaning": "(形声。从人,崔声。本义:催促,促使) 同本义。", "cites": [{"t": "交徧催我。", "b": "《诗·邶风·室人》"}, {"t": "鸿仪催零金。", "b": "《侯成碑》"}, {"t": "都门帐饮无绪,留恋处兰舟催发。", "b": "柳永《雨霖铃》"}, {"t": "葡萄美酒夜光杯,欲饮琵琶马上催。", "b": "王翰《凉州词》"}], "words": [{"w": "催比", "t": "催征"}, {"w": "催并", "t": "催促;催逼"}, {"w": "催迸", "t": "同“催并”"}, {"w": "催科", "t": "催租;亦指催缴钱粮的小吏"}, {"w": "催命鬼", "t": "催人早死的鬼使"}, {"w": "催索", "t": "催讨,催着要。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2960wx','傻','1','shǎ','亻','13','','[{"pinyin": "shǎ", "defs": [{"meaning": "头脑蠢笨,不谙事理,缺乏想象力。", "cites": [{"t": "贾母喜欢,便起名为傻大姐。", "b": "《红楼梦》"}], "words": [{"w": "傻厮", "t": "傻角。傻瓜,呆子"}, {"w": "傻大头", "t": "傻子"}, {"w": "傻儿凹", "t": "呆子"}, {"w": "傻相", "t": "愚蠢可笑的样子"}, {"w": "傻不愣登", "t": "形容愚蠢、糊涂的样子"}, {"w": "傻冲打的", "t": "傻冲乱打人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2961wx','像','1','xiàng','亻','13','','[{"pinyin": "xiàng", "defs": [{"meaning": "(形声。从人,从象,象亦声。本义:相貌相似)。"}, {"meaning": "同本义。", "cites": [{"t": "像,似也。", "b": "《说文》。段注:“然韩非之前只有象字,无像字。韩非以后小篆即作像。许断不以象释似,复以象释像矣。系辞曰,爻也者,效此者也。象也者,像此者也。又曰,象也者,像也。…盖象为古文,圣人以像释之。虽他本像亦作象。然郑康成、王辅本非不可信也。凡形像、图像、想像字皆当从人,而学者多作象,象行而像废矣。”"}, {"t": "影之像形也。", "b": "《荀子·富国》"}, {"t": "女必像汝,我心甚慰。", "b": "林觉民《与妻书》"}, {"t": "以情乃一人之情,说张三要像张三,难通融于李四。", "b": "清·李渔《闲情偶寄》"}, {"t": "脸上处处像他哥哥,可是那种神气又不完全像他的哥哥。", "b": "老舍《黑白李》"}], "words": [{"w": "像形", "t": "与某事物形状相似"}, {"w": "像似", "t": "好像"}, {"w": "像形奇名", "t": "比拟其形状而讹易本名"}, {"w": "像煞", "t": "活像,好像"}, {"w": "像姑", "t": "男妓。"}]}, {"meaning": "模拟。", "cites": [{"t": "于是民人被发文身以像鳞虫。", "b": "《淮南子·原道训》"}]}, {"meaning": "仿效。", "cites": [{"t": "中立君树,前植群树,以像朝班。", "b": "《辽史》"}, {"t": "行比伯夷,置以为像兮。", "b": "《楚辞·九章》"}]}, {"meaning": "依随,顺遂。", "cites": [{"t": "像了他意,再无妒忌。", "b": "《古今小说》"}], "words": [{"w": "像心如意", "t": "顺心如意"}, {"w": "像心称意", "t": "称心满意"}, {"w": "像心适意", "t": "随心所欲"}, {"w": "像心像意", "t": "顺遂心愿。"}]}, {"meaning": "立像,或比照人物形象绘画或雕塑图像。", "cites": [{"t": "邑先大夫皆像于两傍。", "b": "宋·叶适文"}, {"t": "遂合塑工像之。", "b": "《茶香室续钞》"}]}, {"meaning": "雕像。", "cites": [{"t": "有彭郎像。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "有小姑像", "b": ""}, {"t": "想古宗庙,既无像主,又藏于寝,盖不禁人游观。", "b": "清·王夫之《读四书大全说》"}], "words": [{"w": "像主", "t": "图绘或塑刻的神主像"}, {"w": "像座;像塔", "t": "佛像与佛塔"}, {"w": "像铭", "t": "石刻的画像铭文。"}]}, {"meaning": "法式。", "cites": [{"t": "行比伯夷,置以为像兮。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2962wx','躲','1','duǒ','身','13','','[{"pinyin": "duǒ", "defs": [{"meaning": "(形声。从身,朵声。①本义:身。②避开,隐匿)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2963wx','魁','1','kuí','鬼','13','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从斗,鬼声。“斗”,长柄酒勺。本义:汤勺,调羹。长柄大头)。"}, {"meaning": "同本义。", "cites": [{"t": "魁,羹抖也。", "b": "《说文》"}, {"t": "授以魁柄。", "b": "《汉书·梅福传》"}, {"t": "太子洗马荀子骥家中以龙铜魁作食欻鸣。", "b": "晋·郭璞《易洞林》"}]}, {"meaning": "古星名。北斗七星的第一至第四星,一说为北斗第一星。", "cites": [{"t": "平旦建者魁。", "b": "《汉书·天文志》"}, {"t": "那北斗正斜倚在紫微垣的西边上面,杓在上,魁在下。", "b": "《老残游记》"}], "words": [{"w": "魁星", "t": "即“奎宿”,原为二十八宿之一。后被古人附会为主管文运之神"}, {"w": "魁杓", "t": "指北斗星"}, {"w": "魁冈", "t": "河魁星与天冈星的合称"}, {"w": "魁罡", "t": "河魁星与天罡星的合称"}, {"w": "魁冈", "t": "北斗星的斗魁、天冈二星"}, {"w": "魁衡", "t": "北斗七星中的第一星和第五星。"}]}, {"meaning": "首领,领头人。", "cites": [{"t": "诸公之间陈遵为雄,闾里之侠原涉为魁。", "b": "《汉书·游侠传》。又如:罪魁祸首;盗魁;魁柄(比喻朝廷的大权;借喻宰相之位);魁帅(领袖,首领);魁杰(首领人物)"}]}, {"meaning": "小丘。", "cites": [{"t": "夫周,高山,广川、大薮也,故能生是良材,而幽王荡以为魁陵、粪土、沟渎。", "b": "《国语》"}], "words": [{"w": "魁陵", "t": "小土丘"}, {"w": "魁父", "t": "小丘。"}]}, {"meaning": "居首位,第一。", "cites": [{"t": "不疾学而能为魁士,名人者,未之有也。", "b": "《吕氏春秋》"}], "words": [{"w": "魁甲", "t": "古代科举考试,称进士第一名为魁甲"}, {"w": "魁解", "t": "“明”“清”乡试称解试,中式的举人第一名称魁解,也称解元"}, {"w": "魁选", "t": "选中第一名。即首选"}, {"w": "魁品", "t": "高档的品级。"}]}, {"meaning": "高大,壮伟。", "cites": [{"t": "始以薛公为魁然也,今视之,乃渺小丈夫耳。", "b": "《史记·孟尝君列传》"}], "words": [{"w": "魁峨", "t": "魁伟"}, {"w": "魁肥", "t": "魁梧高大;体躯肥胖"}, {"w": "魁堆", "t": "高突的样子"}, {"w": "魁杰", "t": "形容身体雄伟高大。同魁伟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2964wx','衙','1','yá','彳','13','','[{"pinyin": "yá", "defs": [{"meaning": "(形声。从行,吾声。(yú)本义:列队行进的样子)。"}, {"meaning": "旧时官署之称。", "cites": [{"t": "诸州县长官在公衙亦准此。", "b": "张昭远《旧唐书·仪卫志》"}, {"t": "衙,衙府也。", "b": "《广韵》"}, {"t": "衙门,本牙门之讹,《周礼》谓之旌门,郑氏司常注所云,巡狩兵车之会,皆建太常是也,其旗两边刻绘如牙状,故亦曰牙旗,后时因谓营门曰雅门。", "b": "《陔余丛考》"}, {"t": "每日衙门虚寂,无复诉讼者。", "b": "《北齐书·宋世良传》"}], "words": [{"w": "衙头", "t": "金人军队的统帅部"}, {"w": "衙职", "t": "官衙中的职役"}, {"w": "衙庭", "t": "官署的庭堂"}, {"w": "衙堂", "t": "官署的大堂"}, {"w": "衙里", "t": "衙署内"}, {"w": "衙子", "t": "在衙门中当差的人。"}]}, {"meaning": "唐代谓天子所居之处。", "cites": [{"t": "群臣始朝于宣政衙。", "b": "张昭远《旧唐书·仪卫志》"}], "words": [{"w": "衙队", "t": "宫廷卫队。"}]}, {"meaning": "衙参。", "cites": [{"t": "病卧四更后,愁闻报早衙。", "b": "李洞《江干即事》"}], "words": [{"w": "衙日", "t": "衙参之日"}, {"w": "衙喏", "t": "衙参时兵卒的声诺。"}]}, {"meaning": "坐衙,官吏坐堂审案。", "cites": [{"t": "值城隍早衙,喊冤以投。", "b": "《聊斋志异》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2965wx','微','1','wēi','彳','13','','[{"pinyin": "wēi", "defs": [{"meaning": "(会意。从彳(chì);--(wēi)声。本义:隐秘地行走)。"}, {"meaning": "同本义。", "cites": [{"t": "微,隐行也。", "b": "《说文》"}, {"t": "崔杼微逆光。", "b": "《左传·襄公十九年》"}], "words": [{"w": "微行", "t": "便装出行,不想让人知其尊贵的身分。"}]}, {"meaning": "藏匿,隐蔽。", "cites": [{"t": "其徒微之。", "b": "《左传·哀公十六年》"}, {"t": "微而臧。", "b": "《礼记·学记》"}], "words": [{"w": "微没", "t": "隐没"}, {"w": "微奸", "t": "隐藏的邪恶"}, {"w": "微阵", "t": "隐蔽的兵力"}, {"w": "微情", "t": "隐藏而不显露的感情"}, {"w": "微意", "t": "隐藏之意"}, {"w": "微道", "t": "隐蔽或偏僻的小路。"}]}, {"meaning": "衰微,衰落。", "cites": [{"t": "固以微矣。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "微缺", "t": "衰败残缺"}, {"w": "微灭", "t": "衰败灭绝。"}]}, {"meaning": "非,不是。", "cites": [{"t": "虽微晋而已。", "b": "《礼记·檀弓下》"}, {"t": "微我无酒,以敖以游。", "b": "《诗·邶风·柏舟》"}, {"t": "微夫人之力不及此。", "b": "《左传·僖公三十年》"}, {"t": "神农黄帝,犹有可非,微独舜汤。", "b": "《吕氏春秋·离俗》"}], "words": [{"w": "微与", "t": "不应该这样"}, {"w": "微独", "t": "不单是,不仅仅。"}]}, {"meaning": "微小;轻微。", "cites": [{"t": "微,小也。", "b": "《广雅·释诂二》"}, {"t": "叶公子高微小短瘠。", "b": "《荀子·非相》。注:“微,细也”。"}, {"t": "名微而众寡。", "b": "《三国志·诸葛亮传》"}, {"t": "微风鼓浪。", "b": "宋·苏轼《石钟山记》"}, {"t": "微波入焉。", "b": ""}, {"t": "岭峤微草。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "微恙", "t": "小病"}, {"w": "微行", "t": "小径;便装出行"}, {"w": "微雨", "t": "细雨"}, {"w": "微蔑", "t": "指极微小的东西"}, {"w": "微仪", "t": "谦辞。微不足道的礼物"}, {"w": "微忱", "t": "一点儿诚意;些须诚心"}, {"w": "微词", "t": "隐约的讥喻"}, {"w": "微力", "t": "微小的力量"}, {"w": "微功", "t": "细小的功劳。"}]}, {"meaning": "卑贱。", "cites": [{"t": "虞舜侧微。", "b": "《书·序》"}, {"t": "刍荛之微。", "b": "清·刘开《问说》"}], "words": [{"w": "微时", "t": "尚未出名的时候"}, {"w": "微介", "t": "卑贱而耿直"}, {"w": "微名", "t": "微贱之名"}, {"w": "微门", "t": "卑微的门第。"}]}, {"meaning": "日月亏缺的。", "cites": [{"t": "日居月诸,胡迭而微。", "b": "《诗·邶风·柏舟》"}]}, {"meaning": "秘密,偷偷。", "cites": [{"t": "微视其睡。", "b": "唐·柳宗元《童区寄传》"}, {"t": "于此微缺。", "b": "清·袁枚《祭妹文》"}, {"t": "微闻有鼠。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "微伺", "t": "暗中伺察"}, {"w": "微攻", "t": "暗中侵害"}, {"w": "微逆", "t": "暗中迎回"}, {"w": "微知", "t": "暗中探悉"}, {"w": "微随", "t": "暗中跟随"}, {"w": "微察", "t": "暗中侦察 "}, {"w": "微谋", "t": "密谋"}, {"w": "微讽", "t": "暗中讽喻"}, {"w": "微验", "t": "暗中侦察"}, {"w": "微扣", "t": "暗中询问。"}]}, {"meaning": "精妙。", "cites": [{"t": "口多微辞。", "b": "《登徒子·好色赋》"}, {"t": "诸侯有能微妙以节。", "b": "《荀子·议兵》"}, {"t": "其辞微。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "稍微,稍稍。", "cites": [{"t": "但微颔之。", "b": "宋·欧阳修《归田录》"}, {"t": "土膏微润。", "b": "明·袁宏道《满井游记》"}, {"t": "微笑默叹。", "b": "《虞初新志·秋声诗自序》"}, {"t": "婉贞微叹。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "微闻", "t": "隐约听到"}, {"w": "微露", "t": "微微显露。"}]}, {"meaning": "要没有,要不是。", "cites": [{"t": "微斯人,吾谁与归。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "古单位名。"}, {"meaning": "古代极小的量度单位。一寸的百分之一,或一两的百万分之一。", "cites": [{"t": "忽,十微。微,十纤。", "b": "《察微算经》"}]}, {"meaning": "角度、弧度的单位,一秒的六十分之一。"}, {"meaning": "秘密之事。", "cites": [{"t": "夫田子将有大事,而我示之知微,我必危矣。", "b": "《韩非子》"}]}, {"meaning": "古诸侯国名。"}, {"meaning": "殷代畿内之封地。", "cites": [{"t": "帝乙长子曰微子启。", "b": "《史记》"}]}, {"meaning": "殷周时西南夷之国。", "cites": [{"t": "及庸、…微、…人。", "b": "《书·牧誓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2966wx','愈','1','yù','心','13','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从心,俞声。本义:病好了。这个意义后来又写作“瘉”、“癒”) 同本义。", "cites": [{"t": "瘉,病瘳也。", "b": "《说文》"}, {"t": "幸上病瘉。", "b": "《汉书·卢绾传》"}, {"t": "至日中间差瘉。", "b": "《汉书·李寻传》"}, {"t": "周王病瘉。", "b": "《战国策·周策》"}, {"t": "武益愈。", "b": "《汉书·李广苏建传》"}, {"t": "因天气和暖,黛玉之疾渐愈。", "b": "《红楼梦》"}, {"t": "兼旬愈。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "愈合", "t": "伤口长好。"}]}, {"meaning": "胜过。", "cites": [{"t": "一暴之功,犹愈于十日之寒也。", "b": "清·顾炎武《与潘次耕札》"}]}, {"meaning": "更加;越发。", "cites": [{"t": "政事愈蹙。", "b": "《诗·小雅·小明》"}, {"t": "愈束缚牢甚。", "b": "唐·柳宗元《童区寄传》"}, {"t": "闻而愈悲。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "雪愈甚。", "b": "宋·司马光《资治通鉴·唐纪》"}, {"t": "入之愈深。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "我愈觉得这些孩子可爱了;家乡离我愈近了;愈更", "t": "更加"}, {"w": "愈扇", "t": "更加发扬"}, {"w": "愈愈", "t": "益甚"}, {"w": "愈出愈奇", "t": "越来越奇异。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2967wx','遥','1','yáo','辶','13','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。从辵(chuò))。"}, {"meaning": "同本义。", "cites": [{"t": "遥,远也。", "b": "《广雅》"}, {"t": "遥,远也。梁楚曰遥。", "b": "《方言六》"}, {"t": "遥遥,远也。", "b": "《广雅》"}, {"t": "倚沼畦瀛兮遥望博。", "b": "《楚辞·招魂》。注:“遥,远也。”"}, {"t": "可登而路遥。", "b": "《徐霞客游记·游黄山记》"}, {"t": "遥闻深巷中犬吠。", "b": "《虞初新志·秋声诗自序》"}, {"t": "遥闻汝哭声。", "b": "清·林觉民《与妻书》"}, {"t": "遥语应元。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "遥天", "t": "远天"}, {"w": "遥祭", "t": "向着远方而祭祀"}, {"w": "遥领", "t": "间接治理,由远处控制监督"}, {"w": "遥遥华胄", "t": "指远古时候的名门后裔"}, {"w": "遥心", "t": "心向远方"}, {"w": "遥目", "t": "远望"}, {"w": "遥仰", "t": "对远地的人表示敬仰。"}]}, {"meaning": "时间长。", "cites": [{"t": "勤思终遥夕。", "b": "何劭《杂诗》"}], "words": [{"w": "遥夕", "t": "长夜"}, {"w": "遥久", "t": "长久。"}]}, {"meaning": "飘荡。", "cites": [{"t": "魂魄归徕,无远遥只。(只:语气词,无实义)", "b": "《楚辞·大招》"}], "words": [{"w": "遥袅", "t": "飘遥缭绕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2968wx','腻','1','nì','月','13','','[{"pinyin": "nì", "defs": [{"meaning": "(形声。从肉,贰(èr)声。本义:肥)。"}, {"meaning": "同本义。", "cites": [{"t": "腻,肥也。", "b": "《说文》"}, {"t": "靡颜腻理。", "b": "《楚辞·招魂》"}, {"t": "石钱差复藉,厚叶皆蟠腻。", "b": "唐·李贺《昌谷》"}]}, {"meaning": "细腻。", "cites": [{"t": "肌理细腻骨肉匀。", "b": "杜甫《丽人行》"}], "words": [{"w": "腻泽", "t": "细腻光润"}, {"w": "腻玉", "t": "纹理细腻润泽的玉。形容光滑细润"}, {"w": "腻理", "t": "肌理细润"}, {"w": "腻云", "t": "比喻光泽的发髻。"}]}, {"meaning": "厌烦。", "cites": [{"t": "见了别人就怪腻的。", "b": "《红楼梦》"}], "words": [{"w": "这些话我都听腻了;玩腻了", "t": ""}]}, {"meaning": "积污垢。", "cites": [{"t": "见耶背面啼,垢腻脚不袜。", "b": "杜甫《北征》"}]}, {"meaning": "油腻。", "cites": [{"t": "渭流涨腻。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "腻歪", "t": "腻味。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2969wx','腰','1','yāo','月','13','','[{"pinyin": "yāo", "defs": [{"meaning": "(形声。从肉,要声。本作“要”。本义:紧接肋或胸以下的部分;胸和髋之间的身体的一部分)。"}, {"meaning": "同本义。", "cites": [{"t": "楚王好细腰,宫中多饿死。", "b": "《后汉书》"}], "words": [{"w": "腰板", "t": "人的腰和背。多就姿势而言。亦借指体格"}, {"w": "腰腿", "t": "腰部和腿部的活动能力。"}]}, {"meaning": "指某物的中部或中间部分。", "cites": [{"t": "半山腰", "b": ""}], "words": [{"w": "腰房", "t": "两进院子中间的房子"}, {"w": "腰封", "t": "束在礼品中间的绢带,上面写明送礼者和收礼人的名号"}, {"w": "腰门", "t": "中门"}, {"w": "山腰;锅炉炉腰", "t": ""}]}, {"meaning": "佩在腰上。", "cites": [{"t": "腰白玉之环。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "腰金衣紫", "t": "腰挂金印,身穿紫袍,指做了大官"}, {"w": "腰舟", "t": "古人以瓠系在腰间,用以渡水,谓“腰舟”"}, {"w": "腰佩", "t": "古代系在腰间以别官阶的一种佩件"}, {"w": "腰扇", "t": "古代佩在腰间可以折叠的团扇"}, {"w": "腰袱", "t": "系在腰间的包袱。多用以藏钱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2970wx','腥','1','xīng','月','13','','[{"pinyin": "xīng", "defs": [{"meaning": "腥气,泛指肉鱼、类及油脂的臭气味。", "cites": [{"t": "腥臊并御。", "b": "《楚辞·屈原·涉江》。注:“臭也。”"}, {"t": "王之厨馔,腥蝼不可飨。", "b": "《列子·周穆王》"}, {"t": "水居者腥。", "b": "《吕氏春秋·本味》"}, {"t": "扁地腥云。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "这碗鱼汤有点腥;腥腻", "t": "腥气油腻"}, {"w": "血腥;腥臭;土腥气", "t": ""}]}, {"meaning": "病猪肉中像星或米粒的息肉。", "cites": [{"t": "豕盲眡而交睫,腥。", "b": "《周礼·内饔》"}]}, {"meaning": "生肉。", "cites": [{"t": "君赐腥,必熟而荐之。", "b": "《论语·乡党》"}, {"t": "膳膏腥。", "b": "《礼记·内则》"}, {"t": "胖如脯而腥者。", "b": "《周礼·内饔》郑注"}]}, {"meaning": "丑恶。", "cites": [{"t": "腥闻在上,故天降丧于殷。", "b": "《书·酒诰》"}], "words": [{"w": "腥德", "t": "丑恶的品德"}, {"w": "腥闻", "t": "丑恶的名声或恶名远播。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2971wx','腮','1','sāi','月','13','','[{"pinyin": "sāi", "defs": [{"meaning": "颊 。亦称“腮巴”、“腮巴子”、“腮斗”、“腮颊”、“腮帮”、“腮帮子”。", "cites": [{"t": "莲花泛水,艳如越女之腮。", "b": "萧统《十二月启》"}], "words": [{"w": "腮庞", "t": "面颊,面容"}, {"w": "腮斗儿", "t": "腮,脸蛋儿。"}]}, {"meaning": "水生动物的呼吸器官。", "cites": [{"t": "裴初不信,乃鲙鲤鱼无腮者,令左右食之。", "b": "唐·段成式《酉阳杂俎》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2972wx','腹','1','fù','月','13','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从肉,复声。此为后起形声字,初文应即“畐”(fú)字,象人腹部之形。本义:肚子)。"}, {"meaning": "同本义。", "cites": [{"t": "腹,厚也。", "b": "《说文》。按,脐上下两旁也。"}, {"t": "坤为腹。", "b": "《易·说卦传》"}, {"t": "入于左腹。", "b": "《易·明夷》"}, {"t": "腹者至阴之所居。", "b": "《素问·评热病论》"}, {"t": "自脐以下曰水腹。", "b": "《释名》"}, {"t": "腹饥不得食。", "b": "晁错《论贵粟疏》"}], "words": [{"w": "腹痛", "t": "肚子痛"}, {"w": "腹肠", "t": "肚肠,肚子"}, {"w": "腹围", "t": "腰带"}, {"w": "腹如垂瓠", "t": "形容肚皮松瘪难看"}, {"w": "腹便便", "t": "形容肚子肥满。"}]}, {"meaning": "内心。", "cites": [{"t": "腹诽而心谤。", "b": "《汉书·灌夫传》"}], "words": [{"w": "腹诽", "t": "口里不说,心里不以为然"}, {"w": "腹记", "t": "暗记在心"}, {"w": "腹热", "t": "内心焦急"}, {"w": "腹悲", "t": "心里暗悲"}, {"w": "腹咏", "t": "内心歌咏"}, {"w": "腹咒", "t": "心中咒骂。"}]}, {"meaning": "怀抱。", "cites": [{"t": "先妣出入操作必腹之。", "b": "方苞《王处士墓表》"}]}, {"meaning": "容纳。", "cites": [{"t": "巴蛇腹象,足觌厥大。", "b": "柳宗元《天对》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2973wx','腺','1','xiàn','月','13','','[{"pinyin": "xiàn", "defs": [{"meaning": "生物体内能分泌某些化学物质的组织 。由腺细胞组成,如人体内的唾液腺、汗腺、胰腺、甲状腺、肾上腺等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2974wx','鹏','1','péng','鸟','13','','[{"pinyin": "péng", "defs": [{"meaning": "(形声。从鸟,朋声。“鹏”是传说中最大的一种鸟,由鲲变化而成。本义:大鹏)。"}, {"meaning": "同本义。", "cites": [{"t": "朋,神鸟也。朋,古文凤。鹏,亦古文凤。", "b": "《说文》"}, {"t": "化而为鸟,其名为鹏。", "b": "《庄子·逍遥游》"}], "words": [{"w": "鹏术", "t": "大鹏鸟高飞远举之术。"}]}, {"meaning": "比喻前程远大。", "cites": [{"t": "鹏图仍矫翼,熊轼且移轮。", "b": "杜甫《赠肖二十》"}], "words": [{"w": "鹏路", "t": "鹏飞的路程极远。多用以比喻仕途的飞黄腾达"}, {"w": "鹏图", "t": "鹏鸟奋飞,去程遥远。比喻伟大的志向或远大的前程"}, {"w": "鹏鸟高飞", "t": "比喻人飞黄腾达。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2975wx','腾','1','téng','月','13','','[{"pinyin": "téng", "defs": [{"meaning": "(形声。从马,朕(zhèn)声。本义:马奔腾)。"}, {"meaning": "同本义。", "cites": [{"t": "腾,传也。", "b": "《说文》。谓传车马驰。"}, {"t": "腾,奔也。", "b": "《广雅》"}, {"t": "腾众车使径待。", "b": "《离骚》"}, {"t": "腾驴驘以驰逐。", "b": "《楚辞·愍命》"}, {"t": "腾驾步游。", "b": "《楚辞·大招》"}, {"t": "士饱而歌,马腾于槽。", "b": "韩愈《平淮西碑》"}], "words": [{"w": "奔腾", "t": "许多马跳跃着奔跑"}, {"w": "腾夷", "t": "在平地上奔驰。喻宦途顺利"}, {"w": "腾逐", "t": "奔驰追赶"}, {"w": "腾藉", "t": "奔腾践踏"}, {"w": "腾噬", "t": "奔腾咬啮"}, {"w": "腾驾", "t": "使车马奔驰"}, {"w": "腾嬉", "t": "奔腾嬉戏。"}]}, {"meaning": "奔驰。", "cites": [{"t": "潜龙腾渊。", "b": "清·梁启超《饮冰室合集·文集》"}]}, {"meaning": "跳跃。", "cites": [{"t": "遂相腾击。", "b": "《聊斋志异·促织》"}], "words": [{"w": "腾那", "t": "窜跳躲闪。指武功"}, {"w": "腾身", "t": "跃身,纵身"}, {"w": "腾超", "t": "跳跃腾空"}, {"w": "腾距", "t": "跳跃"}, {"w": "腾身而过;腾希", "t": "腾跃于空中"}, {"w": "腾奔", "t": "腾跃奔驰"}, {"w": "腾轩", "t": "腾跃高举"}, {"w": "腾倚", "t": "或腾跃或倚立"}, {"w": "腾闪", "t": "腾跃闪避"}, {"w": "腾驰", "t": "腾跃奔驰"}, {"w": "腾跣", "t": "赤足腾跃"}, {"w": "腾奋", "t": "腾跃奋飞"}, {"w": "万马奔腾;腾踯", "t": "腾空跳跃,向上跳"}, {"w": "腾霄", "t": "腾空,冲天"}, {"w": "腾凌", "t": "腾跃"}, {"w": "腾逸", "t": "腾空跨越"}, {"w": "腾击", "t": "腾空攻击。"}]}, {"meaning": "使房屋空出。", "cites": [{"t": "不如就把书院腾了出来。", "b": "《官场现形记》"}], "words": [{"w": "腾房子给客人住", "t": ""}]}, {"meaning": "升入空中;上升。", "cites": [{"t": "天气下降,地气上腾。", "b": "《礼记·月令》"}], "words": [{"w": "升腾", "t": "向上升起"}, {"w": "腾上", "t": "向上升"}, {"w": "腾降", "t": "升降"}, {"w": "腾掉", "t": "升空漂动"}, {"w": "腾矫", "t": "飞升,升高"}, {"w": "腾薄", "t": "上下起伏"}, {"w": "腾海", "t": "升于海上"}, {"w": "腾起", "t": "升起"}, {"w": "腾蛟起凤;腾化", "t": "飞升成仙"}, {"w": "腾达", "t": "升腾;上浮"}, {"w": "腾掷", "t": "向上飞起"}, {"w": "腾冲", "t": "飞上天空"}, {"w": "腾举", "t": "飞升"}, {"w": "腾骞", "t": "飞升,升空。"}]}, {"meaning": "传递。", "cites": [{"t": "枹止响腾。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "腾羞", "t": "传送食物"}, {"w": "腾告", "t": "传告"}, {"w": "腾榜", "t": "传递文告"}, {"w": "腾书", "t": "传递书信"}, {"w": "腾倒", "t": "转移挪动"}, {"w": "腾言", "t": "传言"}, {"w": "腾呼", "t": "传呼。"}]}, {"meaning": "翻腾。", "cites": [{"t": "不震不腾。", "b": "《诗·鲁颂·閟宫》"}, {"t": "百川沸腾。", "b": "《诗·小雅·十月之交》"}, {"t": "忽风云腾涌,急系缆。", "b": "陆游《过小孤山大孤山》"}], "words": [{"w": "腾波", "t": "翻腾的波浪"}, {"w": "腾踊", "t": "水翻腾上涌"}, {"w": "腾倾", "t": "腾涌倾注"}, {"w": "腾溢 ", "t": "翻腾漫溢"}, {"w": "腾扬", "t": "翻腾上涌。"}]}, {"meaning": "驾;乘。", "cites": [{"t": "腾驴赢以驰逐。", "b": "《楚辞·刘向·九叹·愍命》"}], "words": [{"w": "腾龙", "t": "驾龙,乘龙。"}]}, {"meaning": "凌驾。", "cites": [{"t": "为人臣者,变故易常,而巧官以谄上,谓之腾。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2976wx','腿','1','tuǐ','月','13','','[{"pinyin": "tuǐ", "defs": [{"meaning": "胫和股的总称 。人和动物主要用来支承身体并使身体从一点移到另一点(特别是以行走的方式)的肢体之一。", "cites": [{"t": "石人战摇腿。", "b": "唐·韩愈《嘲鼾睡》"}], "words": [{"w": "腿花", "t": "棍子打在腿上;腿伤"}, {"w": "大腿;粗腿;腿股", "t": "大腿"}, {"w": "腿脡", "t": "腿码,腿銗腿,言其直而修长"}, {"w": "腿胯", "t": "腰以下至大腿的部分。常指奔跑时用力之处"}, {"w": "腿套", "t": "套在裤外使小腿保暖的用品"}, {"w": "腿腕", "t": "脚与小腿之间的部分"}, {"w": "腿裆,腿洼子", "t": "两股之间;胯下"}, {"w": "腿弯", "t": "股胫间弯曲处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2977wx','鲍','1','bào','鱼','13','','[{"pinyin": "bào", "defs": [{"meaning": "盐腌的鱼。", "cites": [{"t": "如入鲍鱼之肆,久而不闻其臭。", "b": "《孔子家语·六本》"}], "words": [{"w": "鲍舍", "t": "存放鲍鱼的房舍"}, {"w": "鲍室", "t": "存放鲍鱼的房室"}, {"w": "鲍肆", "t": "鲍鱼之肆。卖盐渍鱼的商店。比喻小人聚居之所。"}]}, {"meaning": "鲍鱼,鳆鱼的别名。即石决明 。腹足纲软体动物,海味珍品,贝壳入药。"}, {"meaning": "腹足纲前鳃亚纲鲍科鲍属海产贝类。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2978wx','猿','1','yuán','犭','13','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从犬,袁声。猿似犬,故从犬。本义:灵长类动物,形态与猴相似) 同本义。", "cites": [{"t": "蝯善援,禺属。", "b": "《说文》。通常写作“猨、猿”。"}, {"t": "貉逾汶则死。", "b": "《考工记·总目》。注:“貉或为猨。谓善缘木之猨也。”"}, {"t": "毋教猱升木。", "b": "《诗·小雅·角弓》。传:“猱,猨属。”"}, {"t": "猿狙之便自山林来。", "b": "《庄子·天地》"}, {"t": "猿之所以寿者,好引其末,是故气四越。", "b": "汉·董仲舒《春秋繁露》"}], "words": [{"w": "猿猴献果", "t": "指将人的四肢在胸前捆在一起的姿势"}, {"w": "猿狖", "t": "猿猴"}, {"w": "猿眩", "t": "猿临悬崖而目眩。极言险峻"}, {"w": "猿臂", "t": "臂长如猿,运用自如,亦比喻攻守自如的作战形势。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2979wx','颖','1','yǐng','页','13','','[{"pinyin": "yǐng", "defs": [{"meaning": "(形声。从禾,顷声。从禾与农作物有关。本义:谷穗。亦称“颖片”。指禾本科植物小穗基部的二枚苞片)。"}, {"meaning": "同本义。", "cites": [{"t": "颖,禾末也。从禾,顷声。谓贯于穗及近于穗之芒秒。", "b": "《说文》"}, {"t": "禾穗谓之颖。", "b": "《小尔雅》"}, {"t": "异亩同颖。", "b": "《书·归禾序》"}, {"t": "实颖实贾。", "b": "《诗·大雅·生民》"}, {"t": "嘉禾重颖。", "b": "应贞《晋武帝华林园林》"}], "words": [{"w": "颖果", "t": "干果的一种,种皮和果皮合而为一,里面只有一粒种子。"}]}, {"meaning": "锥芒。", "cites": [{"t": "乃颖脱而出,非特其末见而已。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "颖脱", "t": "将锥放在囊中,终将全部脱出。比喻能充分显露内在的才能"}, {"w": "短颖羊毫笔", "t": ""}]}, {"meaning": "聪敏。", "cites": [{"t": "灵运幼便颖悟。", "b": "《南史·谢灵运传》"}, {"t": "君性颖异。", "b": "邓文原《苏府君墓表》"}], "words": [{"w": "颖拔绝伦", "t": "聪敏过人,找不出第二个人"}, {"w": "颖秀", "t": "聪慧出众"}, {"w": "颖哲", "t": "聪慧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2980wx','触','1','chù','角','13','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从角,蜀声。本义:以角撞物)。"}, {"meaning": "用角抵人或物。", "cites": [{"t": "触,牴也。", "b": "《说文》"}, {"t": "兽穷则触。", "b": "《新序杂事》"}, {"t": "触槐而死。", "b": "《左传》"}, {"t": "羝羊触藩。", "b": "《易·大壮》"}], "words": [{"w": "触藩", "t": "以角触撞藩篱"}, {"w": "触藩羝羊", "t": "公羊抵触藩篱,角被挂,无法摆脱很焦急。"}]}, {"meaning": "撞,碰。", "cites": [{"t": "手之所触。", "b": "《庄子·养生主》"}], "words": [{"w": "触损", "t": "伤害"}, {"w": "触抵", "t": "抵触顶撞"}, {"w": "触搏", "t": "撞击。"}]}, {"meaning": "遇到;遭受。", "cites": [{"t": "触草木,尽死。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "触受", "t": "触及,遭受"}, {"w": "触值", "t": "遭遇"}, {"w": "触祸", "t": "遭受祸殃。"}]}, {"meaning": "干犯,冒犯。", "cites": [{"t": "去礼义,触刑法。", "b": "《汉书·元帝纪》"}], "words": [{"w": "触突", "t": "触犯;刺激"}, {"w": "触抵", "t": "触犯罪过"}, {"w": "触冒", "t": "冒犯,冲犯。"}]}, {"meaning": "佛家语。与色、声、香、味、法合称“六尘”。", "cites": [{"t": "人之嗜欲,著于声、色、香、味、触、法,而仁义即由嗜欲而起。", "b": "章炳麟《菌说》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2981wx','解','1','jiě jiè xiè','角','13','','[{"pinyin": "jiě", "defs": [{"meaning": "(会意。从刀,从牛,从角。表示用刀把牛角剖开。本义:分解牛,后泛指剖开)。"}, {"meaning": "同本义。", "cites": [{"t": "解,判也,从刀,判牛角。", "b": "《说文》"}, {"t": "鹿角解。", "b": "《吕氏春秋·仲夏》"}, {"t": "皆众理解也。", "b": "《汉书·贾谊传》"}, {"t": "解牛之时。", "b": "《庄子·养生主》"}, {"t": "所解数千。", "b": ""}, {"t": "磔然已解。", "b": ""}, {"t": "四肢解尽。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "解腕", "t": "断腕"}, {"w": "解手刀", "t": "随身携带的小佩刀。又称解腕尖刀"}, {"w": "解角", "t": "锯取鹿角"}, {"w": "解破", "t": "解剖。"}]}, {"meaning": "解体,离散。", "cites": [{"t": "解,散也。", "b": "《广雅》"}, {"t": "恐天下解也。", "b": "《汉书》"}], "words": [{"w": "土崩瓦解;解札", "t": "裘毛败坏散落"}, {"w": "解泽", "t": "散布恩泽"}, {"w": "解落", "t": "散落分离"}, {"w": "解续", "t": "分合"}, {"w": "解窜", "t": "离散逃窜"}, {"w": "解结", "t": "溃散。"}]}, {"meaning": "分解,熔化。", "cites": [{"t": "冰皮始解。", "b": "明·袁宏道《满井游记》"}, {"t": "急解令休止。", "b": "《聊斋志异·促织》"}]}, {"meaning": "解除,解围。", "cites": [{"t": "解燕国之围。", "b": "《战国策·燕策》"}, {"t": "颜太师以兵解。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "解厄", "t": "解除厄难"}, {"w": "解厌", "t": "解除饥饿;充饥。厌:通“餍”,饱"}, {"w": "解祟", "t": "解除祸害"}, {"w": "解疗", "t": "除病"}, {"w": "解秽", "t": "解除秽恶;除去秽气"}, {"w": "解斋", "t": "解除斋戒。"}]}, {"meaning": "解开。", "cites": [{"t": "闭约而无解。", "b": "《荀子·非十二子》"}, {"t": "解纲。", "b": "《仪礼·大射仪》"}, {"t": "解带为城。", "b": "《墨子·公输》"}, {"t": "解辫请职。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "解鞍少驻初程。", "b": "宋·姜夔《扬州慢》"}, {"t": "解其棕缚。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "解缆;解扣儿;解衣服;解铃系铃;解包裹;解绶", "t": "解去印绶,指辞去官职"}, {"w": "解维", "t": "解缆,即下系船的绳索;开船。"}]}, {"meaning": "解释,说明。", "cites": [{"t": "师者,所以传道受业解惑。", "b": "唐·韩愈《师说》"}, {"t": "解其惑也。", "b": ""}, {"t": "经吾婉解。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "解字", "t": "解说文字的结构和意义"}, {"w": "解论", "t": "解说讨论"}, {"w": "解喻", "t": "说明比喻"}, {"w": "解梦", "t": "解说梦兆"}, {"w": "解义", "t": "解释词义或文义。"}]}, {"meaning": "晓悟;明白。", "cites": [{"t": "终不解矣。", "b": "唐·韩愈《师说》"}, {"t": "惑之不解。", "b": ""}], "words": [{"w": "解悟", "t": "领会,觉悟"}, {"w": "令人不解;通俗易解;解豁", "t": "弄明白;解开"}, {"w": "解拆", "t": "分解;排解"}, {"w": "解会", "t": "领会,理解"}, {"w": "解人", "t": "通达言语、文辞意趣的人。"}]}, {"meaning": "脱去;松开。", "cites": [{"t": "解衣以活友。", "b": "马中锡《中山狼传》"}, {"t": "解屦不敢当阶。", "b": "《礼记·曲礼上》。疏:“脱也。”"}], "words": [{"w": "解褐", "t": "解下平民所穿的布衣,换上官服"}, {"w": "解冠", "t": "脱帽"}, {"w": "解巾", "t": "脱去隐居时所系的方巾,表示出去做官"}, {"w": "解珥", "t": "脱去耳饰。古代妇女请罪的表示。"}]}, {"meaning": "打开,开放。", "cites": [{"t": "严城解扉。", "b": "《后汉书·耿纯列传》"}], "words": [{"w": "解帆", "t": "开船"}, {"w": "解菜", "t": "解素。开荤。"}]}, {"meaning": "缓解。", "cites": [{"t": "太后之色少解。", "b": "《战国策·赵策》"}]}, {"meaning": "助动词。能,会,得。", "cites": [{"t": "苦雨终风也解晴。", "b": "苏轼《六月二十日夜渡海》"}]}, {"meaning": "道家以为修道者死后魂魄脱离尸体而成仙,称为“尸解”。", "cites": [{"t": "形解销化,依于鬼神之事。", "b": "《史记》"}]}, {"meaning": "见解,见识。", "cites": [{"t": "融玄义无师法,而神解过人。", "b": "《南史》"}]}]}, {"pinyin": "jiè", "defs": [{"meaning": "(词源见jiě声解)。"}, {"meaning": "古代乡举,举送入试 。唐宋时举进士者由地方推荐发送入京的称为“解”。", "cites": [{"t": "天下之士屏居山林,令监司守臣解送。", "b": "《宋史·举志》"}], "words": [{"w": "解元", "t": "明清科举时代,乡试称解试。解试第一名称为解元"}, {"w": "解首", "t": "同解元"}, {"w": "解牌", "t": "登录乡试录取名单的一种文书"}, {"w": "解荐", "t": "推荐选送"}, {"w": "解头", "t": "解元"}, {"w": "解榜", "t": "唐、宋时解试中式的榜文。"}]}, {"meaning": "押送财物或犯人。", "cites": [{"t": "押解了武松,出孟州衙门便行。", "b": "《水浒传》"}], "words": [{"w": "押解", "t": "押送犯人"}, {"w": "起解", "t": "犯人被押送"}, {"w": "解官", "t": "将犯人押解到官府"}, {"w": "解阙", "t": "将罪犯押解到朝廷。"}]}, {"meaning": "兑换。", "cites": [{"t": "我有一锭大银,解了十两小银使用了。", "b": "《水浒传》"}]}]}, {"pinyin": "xiè", "defs": [{"meaning": "兽名。", "cites": [{"t": "角解豸终。", "b": "《太玄·难》。注:“獬豸者,直兽也。”"}], "words": [{"w": "解豸", "t": "传说中神兽名。"}]}, {"meaning": "官署,官吏办事的地方。", "cites": [{"t": "事私门而完解舍。", "b": "《韩非子》"}], "words": [{"w": "解舍", "t": "官府,官舍。"}]}, {"meaning": "古地名 。春秋周畿内地,有二,大解在今河南省洛阳市南,小解在今河南省洛阳市西南。", "cites": [{"t": "王师军于汜,于解。", "b": "《左传》"}]}, {"meaning": "松懈;懒散,做事不抓紧。", "cites": [{"t": "解,缓也。", "b": "《易·杂卦传》注"}, {"t": "三日不解。", "b": "《礼记·杂记一》。注:“倦也。”"}, {"t": "夙夜匪解,以事一人。", "b": "《诗·大雅·生民》"}], "words": [{"w": "解弛", "t": "懈怠松弛"}, {"w": "解休", "t": "松懈;休息"}, {"w": "解怠", "t": "松懈,懒情。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2982wx','煞','1','shā shà','灬','13','','[{"pinyin": "shā", "defs": [{"meaning": "弄死,杀死。", "cites": [{"t": "立性凶暴,多行煞戮。", "b": "杨衒之《洛阳伽蓝记》"}], "words": [{"w": "令杖煞之;打煞人了", "t": ""}]}, {"meaning": "停止;结束。", "cites": [{"t": "煞住脚往里细听。", "b": "《红楼梦》"}], "words": [{"w": "收煞;煞住", "t": "止住,收住"}, {"w": "煞果", "t": "方言。最后;结果"}, {"w": "煞后", "t": "殿后,走在最后面"}, {"w": "煞场", "t": "科举考试结束;一出戏结束"}, {"w": "煞落", "t": "干脆利落"}, {"w": "煞年", "t": "年终。"}]}, {"meaning": "削弱,损坏。", "cites": [{"t": "此刻的话,很近于大煞风景。", "b": "鲁迅《且介亭杂文二集》"}], "words": [{"w": "煞水", "t": "驱除湿气"}, {"w": "煞手锏", "t": "杀手锏。喻出奇制胜的手段和方法"}, {"w": "煞渴", "t": "消渴;解渴。"}]}, {"meaning": "甚么,啥。", "cites": [{"t": "刘姥姥心中想着:这是什么东西,有煞用处呢?", "b": "《红楼梦》"}]}]}, {"pinyin": "shà", "defs": [{"meaning": "指迷信的凶神恶鬼之类。", "cites": [{"t": "鄂城之俗,于新丧避煞最严。", "b": "王同轨《耳谈》"}], "words": [{"w": "凶神恶煞;煞神;煞耗", "t": "指凶神"}, {"w": "煞星", "t": "对人不利的灾星"}, {"w": "煞鬼", "t": "恶鬼。"}]}, {"meaning": "很,极。", "cites": [{"t": "那一片灯光,从半空倒映在乌蓝的海面上……煞是好看。", "b": "《海滨仲夏夜》"}], "words": [{"w": "煞实", "t": "确实;努力"}, {"w": "煞是", "t": "确实,非常"}, {"w": "煞生受", "t": "很为难"}, {"w": "煞时间", "t": "霎时间,极短的时间"}, {"w": "煞末", "t": "方言。末尾;最后"}, {"w": "煞不如", "t": "远不及"}, {"w": "煞有", "t": "的确有一套"}, {"w": "煞黑", "t": "全黑"}, {"w": "煞费心机", "t": "费尽心思。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2983wx','雏','1','chú','隹','13','','[{"pinyin": "chú", "defs": [{"meaning": "(形声。从隹(zhuī),刍声。本义:小鸡)。"}, {"meaning": "同本义。", "cites": [{"t": "雏,鸡子也。", "b": "《说文》"}, {"t": "乃以雏尝黍。", "b": "《礼记·月令》。注:“新鸡也。”"}, {"t": "有人于此,力不能胜一匹雏,则为无力人矣。", "b": "《孟子》"}]}, {"meaning": "引申为幼禽。", "cites": [{"t": "雏烧。", "b": "《礼记·内则》。疏:“鸟之小者也。”"}], "words": [{"w": "雏雉", "t": "幼雉"}, {"w": "雏禽", "t": "幼鸟"}, {"w": "雏莺", "t": "幼莺。也喻指幼龄的歌妓。"}]}, {"meaning": "幼小的动物。", "cites": [{"t": "乳虎,曾纩息之未定兮,乃敢探其穴,而啖其雏。", "b": "宋·苏轼《思子台》"}]}, {"meaning": "幼儿。", "cites": [{"t": "丈夫生儿有如此二雏者,名位岂肯卑微休!", "b": "唐·杜甫《徐卿二子歌》"}, {"t": "挈妇将雏鬓有丝。", "b": "鲁迅《七律·无题》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2984wx','馍','1','mó','饣','13','','[{"pinyin": "mó", "defs": [{"meaning": "面制食品，北方地区特指馒头。用酵母或发粉制成的面食，通常指馒头。", "words": [{"w": "白面馍", "t": ""}, {"w": "蒸馍", "t": ""}, {"w": "馍馍", "t": "馒头;面粉做的食品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2985wx','馏','1','liú liù','饣','13','','[{"pinyin": "liú", "defs": [{"meaning": "加热使液体化成蒸气以分离液体混合物", "words": [{"w": "蒸馏", "t": "加热使液体化成蒸气后再凝成纯净的液体"}, {"w": "干馏", "t": "加热分解已隔热的固体燃料。"}]}]}, {"pinyin": "liù", "defs": [{"meaning": "(形声。从食,留声。本义:蒸饭) 把凉了的熟食品再蒸热。", "words": [{"w": "馏馒头", "t": "把凉饭馏一馏"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2986wx','酱','1','jiàng','酉','13','','[{"pinyin": "jiàng", "defs": [{"meaning": "(会意。从肉,从酉。酒以和酱也。爿声。古文从酉,爿声。籀文从酉,从皿,爿声。本义:用盐醋等调料腌制而成的肉酱)。"}, {"meaning": "用麦、面、豆等发酵制成的调味品。", "cites": [{"t": "酱用百有二十瓮。", "b": "《周礼·膳夫》"}, {"t": "不得其酱。", "b": "《论语》"}, {"t": "濡鸡醢酱,濡鱼卵酱。", "b": "《礼记·内则》"}], "words": [{"w": "黄酱;炸酱;甜酱;豆瓣酱;酱坊;酱豆", "t": "盛酱的食器"}, {"w": "酱瓜", "t": "即越瓜"}, {"w": "酱清", "t": "古代调味品。相当于今之酱油。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2987wx','禀','1','bǐng','示','13','','[{"pinyin": "bǐng", "defs": [{"meaning": "(会意。禀为禀的俗字。本义:给予谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "禀,赐谷也。", "b": "《说文》"}, {"t": "既禀称事。", "b": "《礼记·中庸》。注:“稍食也。”"}, {"t": "食闻吏禀当受粥者,或以陈粟。", "b": "《汉书·文帝纪》"}, {"t": "葬阵亡者,禀其家五岁。", "b": "《新唐书·宪宗纪》"}], "words": [{"w": "禀赡", "t": "指以公粮赈济百姓"}, {"w": "禀谷", "t": "官府给予粮食"}, {"w": "禀粮", "t": "供给粮食"}, {"w": "禀食", "t": "公家配给粮食。"}]}, {"meaning": "赋予;给与。", "cites": [{"t": "禀,予也。", "b": "《广雅》"}, {"t": "天禀其性。", "b": "《汉书·礼乐志》"}], "words": [{"w": "禀质", "t": "天资"}, {"w": "禀才", "t": "天赋的才华"}, {"w": "禀分", "t": "天赋的资质"}, {"w": "禀形", "t": "天赋的形貌"}, {"w": "禀体", "t": "天赋的体质。"}]}, {"meaning": "承受。", "cites": [{"t": "臣下罔收禀命。", "b": "《书·说命》"}], "words": [{"w": "禀令", "t": "承受命令"}, {"w": "禀化", "t": "承受天地自然的化育"}, {"w": "禀灵", "t": "秉受灵秀之气。"}]}, {"meaning": "报告。", "cites": [{"t": "夏侯惇入帐,禀请夜间口号。", "b": "《三国演义》"}], "words": [{"w": "禀陈", "t": "下级对上级陈述报告"}, {"w": "禀牍", "t": "对上级有所陈述的文件"}, {"w": "禀知", "t": "将事情或情况告知尊长。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2988wx','痹','1','bì','疒','13','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从疒(chuáng),畀(bì)声。本义:痹症。中医指由风、寒、湿等引起的肢体疼痛或麻木的病) 同本义。", "cites": [{"t": "痹,湿病也。", "b": "《说文》"}, {"t": "五藏大府、痹十二,病方三十卷。", "b": "《汉书·艺文志》。注:“风湿之病。”"}, {"t": "危坐一时,痹不得摇。", "b": "嵇康《与山巨源绝交书》"}], "words": [{"w": "痹厥", "t": "神经系病。肢体疼痛麻木"}, {"w": "痹顽", "t": "人体某一部分的感觉完全或部分丧失。"}]}, {"meaning": "气郁闷。", "cites": [{"t": "冬刺夏分,病不愈,气上,发为诸痹。", "b": "《诊要经终论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2989wx','廓','1','kuò','广','13','','[{"pinyin": "kuò", "defs": [{"meaning": "(形声。从广(yǎn),郭声。“广”甲骨文、金文象屋墙屋顶形,这里表示与建筑物有关。本义:通“郭”。外城)。"}, {"meaning": "同本义。", "cites": [{"t": "匈奴无城廓之守。", "b": "《盐铁论·论功》"}], "words": [{"w": "城廓", "t": "内外城的城墙,指城池。"}]}, {"meaning": "物体的外缘。", "cites": [{"t": "白描,以细笔钩勒形廓者也。", "b": "蔡元培《图画》"}], "words": [{"w": "轮廓;耳廓", "t": ""}]}, {"meaning": "大,广大;空阔。", "cites": [{"t": "窈而深,廓其有容。", "b": "韩愈《送李愿归盘谷序》"}], "words": [{"w": "廓如", "t": "宽宏;宽阔"}, {"w": "廓大", "t": "宽阔"}, {"w": "廓落", "t": "宽大的样子;空寂的样子"}, {"w": "廓廓", "t": "空旷、开阔的样子。"}]}, {"meaning": "空寂;孤独。", "cites": [{"t": "廓然独居。", "b": "班固《汉书》"}], "words": [{"w": "廓处", "t": "独自居处。"}]}, {"meaning": "开拓,扩大。", "cites": [{"t": "狭隘褊小,则廓之以广大。", "b": "《荀子》"}, {"t": "尔乃廓开九币。", "b": "张衡《西京赋》"}], "words": [{"w": "廓土", "t": "开拓疆域"}, {"w": "廓开", "t": "扩张,开展"}, {"w": "廓恢", "t": "扩大,发展"}, {"w": "廓充", "t": "扩充"}, {"w": "廓大镜", "t": "放大镜"}, {"w": "廓大", "t": "扩大。"}]}, {"meaning": "清除。", "cites": [{"t": "廓妖气于远服。", "b": "《北史·隋纪上·文帝》"}], "words": [{"w": "廓清", "t": "清理;肃清"}, {"w": "廓平", "t": "廓清平定"}, {"w": "廓定", "t": "廓清平定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2990wx','痴','1','chī','疒','13','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从疒(chuáng),疑声。本义:不聪慧;迟钝)。"}, {"meaning": "同本义。", "cites": [{"t": "癡,不慧也。字俗作痴。", "b": "《说文》"}], "words": [{"w": "痴哑", "t": "痴呆喑哑"}, {"w": "痴呆呆", "t": "傻乎乎。"}]}, {"meaning": "疯癫,癫狂。", "cites": [{"t": "此人素有痴名。", "b": "《明史·海瑞传》"}]}, {"meaning": "发呆。", "cites": [{"t": "那边哭的自己伤心,却不道这边听的早已痴倒了。", "b": "《红楼梦》"}]}, {"meaning": "颠狂病。", "cites": [{"t": "今子独坏形貌,蒙耻辱,为狂痴,光曜晻而不宣。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2991wx','痰','1','tán','疒','13','','[{"pinyin": "tán", "defs": [{"meaning": "气管、支气管或肺泡黏膜分泌出来的黏液。", "words": [{"w": "痰厥", "t": "中风不省人事"}, {"w": "痰诞", "t": "痰与口水。偏指痰"}, {"w": "痰沫", "t": "带痰的唾沫"}, {"w": "痰病,痰气", "t": "中医指精神性疾病"}, {"w": "痰火,痰症", "t": "中医术语。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2992wx','廉','1','lián','广','13','','[{"pinyin": "lián", "defs": [{"meaning": "(形声。从广(yǎn),兼声。从“广”,表示与房屋有关。本义:厅堂的侧边)。"}, {"meaning": "同本义。", "cites": [{"t": "廉,仄也。", "b": "《说文》。按,堂之侧边曰廉,故从广。天子之堂九尺,诸侯七尺,大户五尺,士三尺。堂边皆如其高。"}, {"t": "设席于堂廉东上。", "b": "《仪礼·乡饮礼》。郑玄注:“侧边曰廉。”"}, {"t": "故陛九级上,廉远地,则堂高。", "b": "《汉书·贾谊传》"}]}, {"meaning": "边。", "cites": [{"t": "边谓之廉,角谓之隅。", "b": "《九章算术》"}, {"t": "入鲜水北句廉上。", "b": "《汉书·赵充国传》。注:“谓水岸曲而有廉棱也。”"}]}, {"meaning": "棱角。亦指物体露出棱角;有棱角。", "cites": [{"t": "进而眂之,欲其帱之廉也。", "b": "《周礼》"}, {"t": "哀以立廉。", "b": "《礼记·乐记》。注:“廉,廉隅也。”"}], "words": [{"w": "廉正", "t": "有棱角而方正"}, {"w": "廉利", "t": "锋利"}, {"w": "廉角", "t": "廉隅,廉棱。棱角"}, {"w": "廉锷", "t": "棱角锋利。"}]}, {"meaning": "旧称有节操、不苟取的人。", "cites": [{"t": "廉干如古人某。", "b": "清·周容《芋老人传》"}, {"t": "若翁廉。", "b": "明·崔铣《记王忠肃公翱三事》"}]}, {"meaning": "正直;刚直;品行方正。", "cites": [{"t": "廉,稜也。", "b": "《广雅》。按,凡稜利之义,实借为也。"}, {"t": "紾而博廉。", "b": "《考工记·弓人》。注:“严利也。”"}, {"t": "其器廉以深。", "b": "《吕氏春秋·孟秋》。注:“利也,象金断割。”"}, {"t": "廉而不刿。", "b": "《荀子·不苟》"}, {"t": "古之矜也廉。", "b": "《论语·阳货》"}, {"t": "人犯其难,我享其利,非廉也。", "b": "《庄子》"}, {"t": "廉者不受嗟来之食。", "b": "《后汉书·列女传》"}, {"t": "其行廉。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "廉倨", "t": "廉正而倨傲。"}]}, {"meaning": "廉洁。", "cites": [{"t": "廉,清也。", "b": "《广雅》"}, {"t": "摩廉者诘也。", "b": "《鬼谷子》"}, {"t": "取伤廉章指。廉,人之高行也。", "b": "《孟子》"}, {"t": "辞利刻歉谓之廉。", "b": "《贾子·道术》"}, {"t": "一曰廉善,二曰廉能。", "b": "《周礼·小宰》"}, {"t": "洁廉而果敢者也。", "b": "《大戴礼记·文王官人》"}, {"t": "联幼清以廉洁兮。", "b": "《楚辞·招魂》。注:“不受曰廉。”"}, {"t": "廉之欲其节。", "b": "唐·柳宗元《柳河东集》"}, {"t": "其待己也廉。", "b": "唐·韩愈《原毁》"}]}, {"meaning": "又。", "cites": [{"t": "待其身其已廉", "b": ""}], "words": [{"w": "清廉", "t": "清白廉洁"}, {"w": "廉吏", "t": "廉洁的官吏"}, {"w": "廉白", "t": "廉洁"}, {"w": "廉公", "t": "清廉公正"}, {"w": "廉俸", "t": "清制。官员除正俸外,只有养廉费,二者合称廉俸"}, {"w": "廉介", "t": "廉洁耿直"}, {"w": "廉慎", "t": "清廉谨慎"}, {"w": "廉节", "t": "清廉而有节操"}, {"w": "廉让", "t": "清廉逊让"}, {"w": "廉简", "t": "清廉简洁"}, {"w": "廉秽", "t": "清廉和贪秽"}, {"w": "廉辨", "t": "指清廉明辨。"}]}, {"meaning": "狭窄。", "cites": [{"t": "凡秋耕欲深,春夏欲浅;犁欲廉,劳欲再。", "b": "《齐民要术》"}]}, {"meaning": "", "cites": [{"t": "而信廉爱之说。", "b": "《韩非子·五蠹》"}]}, {"meaning": "考察,视察。", "cites": [{"t": "一曰廉善,二曰廉能,三曰廉敬。", "b": "《周礼·天官·小宰》"}, {"t": "武从事廉得其罪。", "b": "《汉书·何武传》"}, {"t": "察贰廉空。", "b": "张衡《西京赋》"}, {"t": "察廉皆视也。", "b": ""}, {"t": "人君不廉而变。", "b": "《管子·正世》。注:“察也”。"}], "words": [{"w": "廉按", "t": "查究"}, {"w": "廉察", "t": "视察,查访"}, {"w": "廉举", "t": "即察举。汉代官员选拔的一种制度"}, {"w": "廉车", "t": "按察使的别称。"}]}, {"meaning": "绝,断。", "cites": [{"t": "外不廉而内不挫。", "b": "《周礼·考工记·轮人》。注:“绝也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2993wx','靖','1','jìng','青','13','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从立,青声。本义:立容安静)。"}, {"meaning": "同本义。", "cites": [{"t": "靖,立竫也。", "b": "《说文》"}, {"t": "自作不靖。", "b": "《书·盘庚》"}, {"t": "靖共尔位。", "b": "《诗·小雅·小明》"}, {"t": "虎靖衡门。", "b": "《樊阳令杨君碑》"}, {"t": "靖以待命犹可,动必忧。", "b": "《左传·昭公二十五年》"}, {"t": "清靖而无私虑。", "b": "《淮南子·精神》"}, {"t": "清靖寡欲,与物无竞。", "b": "《北史·袁韦修传》"}, {"t": "既防溢而靖志兮,迨我暇以翱翔。", "b": "张衡《思玄赋》"}], "words": [{"w": "靖密", "t": "安静致密"}, {"w": "靖冥", "t": "宁静幽深"}, {"w": "靖默", "t": "沉静缄默"}, {"w": "靖重", "t": "安祥凝重。"}]}, {"meaning": "安定;和平。", "cites": [{"t": "靖,安也。", "b": "《广雅》"}], "words": [{"w": "靖晏", "t": "平静安逸,太平无事"}, {"w": "靖遏", "t": "安定。"}]}, {"meaning": "善。", "cites": [{"t": "东门之栗,有靖家室。", "b": "《太平御览》"}]}, {"meaning": "细小。", "cites": [{"t": "靖,一曰细貌。", "b": "《说文》"}, {"t": "有小人国,名曰靖人。", "b": "《山海经·大荒东经》"}], "words": [{"w": "靖人", "t": "短小的人。也作净人、诤人"}, {"w": "靖言", "t": "小人巧言。"}]}, {"meaning": "谦卑恭敬的样子。", "cites": [{"t": "士处靖。", "b": "《管子·大匡》。注:“卑敬貌。”"}], "words": [{"w": "靖恭", "t": "恭敬谨慎"}, {"w": "靖共", "t": "敬慎谦恭。共,通恭。"}]}, {"meaning": "使安定。", "cites": [{"t": "以靖乡土。", "b": "《明史》"}], "words": [{"w": "靖边", "t": "安定边境"}, {"w": "靖匡", "t": "安定、挽救、扶助。"}]}, {"meaning": "止息。", "cites": [{"t": "诸侯靖兵,好以为事。", "b": "《左传·昭公十三年》"}], "words": [{"w": "靖兵", "t": "息兵,休战。"}]}, {"meaning": "平定。", "cites": [{"t": "日靖四方。", "b": "《诗·周颂·我将》"}], "words": [{"w": "靖难", "t": "靖乱。平定乱事"}, {"w": "靖青绥", "t": "安抚。"}]}, {"meaning": "治理。", "cites": [{"t": "靖,治也。", "b": "《尔雅》"}, {"t": "俾予靖之。", "b": "《诗·小雅·菀柳》"}, {"t": "肆其靖之。", "b": "《昊天有成命》"}], "words": [{"w": "靖国", "t": "安治国家。"}]}, {"meaning": "思念。", "cites": [{"t": "靖,思也。东齐海岱之间曰靖。", "b": "《方言》卷一"}]}, {"meaning": "立。", "cites": [{"t": "既防溢而靖志兮,迨我暇以翱翔。", "b": "《文选·张衡·思玄赋》"}]}, {"meaning": "图谋。", "cites": [{"t": "实靖夷我邦。", "b": "《诗·大雅·召旻》"}]}, {"meaning": "表彰。", "cites": [{"t": "不靖其能,其谁从之?", "b": "《左传·昭公元年》"}, {"t": "封比干之墓,靖箕子之宫,表商容之闾。", "b": "《吕氏春秋·慎大览》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2994wx','新','1','xīn','斤','13','','[{"pinyin": "xīn", "defs": [{"meaning": "(形声。从斤,从木,辛声。据甲骨文,左边是木,右边是斧子。指用斧子砍伐木材。本义:用斧子砍伐木材。“新”是“薪”的本字)。"}, {"meaning": "砍伐树木。", "cites": [{"t": "新,取木也。", "b": "《说文》"}, {"t": "且彼亦知“新”之为义乎?衣之始裁为之“初”,木之始伐谓之“新”。", "b": "章炳麟《论承用“维新”二字之荒谬》"}]}, {"meaning": "更新,使之新。", "cites": [{"t": "如何新畬。", "b": "《诗·周颂·臣工》"}, {"t": "旧染污俗,咸与唯新。", "b": "《书·胤征》"}], "words": [{"w": "新民", "t": "使民更新"}, {"w": "新美", "t": "刷新使之美好"}, {"w": "新醮", "t": "改嫁"}, {"w": "新梢", "t": "新长出的树梢。"}]}, {"meaning": "初次出现。与“旧”相对。", "cites": [{"t": "于彼新田。", "b": "《诗·小雅·采芑》"}, {"t": "宴尔新昏。", "b": "《诗·邶风·谷风》"}, {"t": "新台有洒。", "b": "《诗·邶风·新台》"}, {"t": "谁家新燕啄春呢。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "变易新声。", "b": "宋·王谠《唐语林·雅量》"}, {"t": "故日新。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "新夷目。", "b": "《广东军务记》"}], "words": [{"w": "新板洋钱", "t": "指清代机铸的雕有龙形图案的银元"}, {"w": "新发子硎", "t": "喻初入学的学生"}, {"w": "新文", "t": "新闻;新鲜事儿;过分追求新奇的文章;时文。"}]}, {"meaning": "新洁;新鲜;清新。", "cites": [{"t": "新鲜自求珍。", "b": "扬雄《太玄·务》"}, {"t": "柳色新。", "b": "唐·王维《送元二使安西》"}, {"t": "如镜之新。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "新鲜衣服", "t": "新鲜洁净的衣服"}, {"w": "新莺出谷", "t": "形容鸟鸣悦耳"}, {"w": "新切", "t": "清新而贴切"}, {"w": "新句", "t": "诗文中清新优美的语句"}, {"w": "新光", "t": "新鲜的光彩"}, {"w": "新米", "t": "指本年新收获的米。"}]}, {"meaning": "开始的。", "cites": [{"t": "必为新圣笑矣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "新年下", "t": "农历新年;春节"}, {"w": "新元", "t": "新春元旦"}, {"w": "新吉", "t": "农历元旦"}, {"w": "新年新岁", "t": "农历春节期间"}, {"w": "新朔", "t": "指农历每月初一"}, {"w": "新阳", "t": "初春。"}]}, {"meaning": "结婚或结婚不久。", "cites": [{"t": "但见新人笑,那闻旧人哭。", "b": "唐·杜甫《佳人》"}], "words": [{"w": "新妇", "t": "新结婚的女子"}, {"w": "新官", "t": "新郎。亦称“新官人”"}, {"w": "新姑娘", "t": "刚结婚或结婚不久的女子"}, {"w": "新娘子", "t": "新娘"}, {"w": "新婚燕尔", "t": "极言新婚欢乐。燕,宴,安乐的样子。"}]}, {"meaning": "没有用过的。", "cites": [{"t": "衣不如新,人不如故。", "b": "汉·佚名《古艳歌》"}], "words": [{"w": "新笔", "t": ""}]}, {"meaning": "新近;刚刚。", "cites": [{"t": "太后新用事。", "b": "《战国策·赵策》"}, {"t": "刘表新亡。", "b": "宋·司马光《资治通鉴》"}, {"t": "新来与世界为缘。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "新霁", "t": "新晴"}, {"w": "新军", "t": "新投充的兵"}, {"w": "新化", "t": "新经教化"}, {"w": "新立", "t": "新登上君位"}, {"w": "新好", "t": "新结交的好友。"}]}, {"meaning": "指刚收获的粮食或蔬菜等。", "cites": [{"t": "天子尝新。", "b": "《礼记》"}]}, {"meaning": "朝代名 。汉王莽初封新都侯,初始元年(公元八年)代汉称帝,国号新,建都长安(今陕西西安)。更始元年(公元23年)为绿林农民起义军所灭。"}, {"meaning": "柴薪", "cites": [{"t": "百姓斩木艾新而各取富焉。", "b": "《马王堆汉墓帛书》"}]}, {"meaning": "新的人或事物。", "cites": [{"t": "温故而知新。", "b": "《论语》"}, {"t": "即其新。", "b": "唐·韩愈《原毁》"}, {"t": "不图其新。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2995wx','韵','1','yùn','音','13','','[{"pinyin": "yùn", "defs": [{"meaning": "(形声。从音,员(匀)声。本义:和谐悦耳的声音)。"}, {"meaning": "同本义。", "cites": [{"t": "余韵徐歇。", "b": "宋·苏轼《石钟山记》"}, {"t": "短笛无声,寒砧不韵。", "b": "《西游记》"}], "words": [{"w": "韵悠悠", "t": "声音悠扬。"}]}, {"meaning": "美,标致。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2996wx','意','1','yì','心','13','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。从心从音。本义:心志。心意)。"}, {"meaning": "同本义。", "cites": [{"t": "意,志也。", "b": "《说文》"}, {"t": "心之所谓意。", "b": "《春秋繁露·循天之道》"}, {"t": "今者项庄拔剑舞,其意常在沛公也。", "b": "《史记·项羽本纪》"}, {"t": "通其意。", "b": "汉·贾谊《过秦论》"}, {"t": "中有真意。", "b": "晋·陶渊明《饮酒》"}, {"t": "不快我意。", "b": "明·魏禧《大铁椎传》"}, {"t": "无意则已。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "蔡伦立意造纸。", "b": "《齐民要术》"}, {"t": "醉翁之意不在酒。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "其意深长。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "意志;愿望。亦引申为志向。", "cites": [{"t": "明君在上,便僻不能食其意。", "b": "《管子·君臣下》"}], "words": [{"w": "意缓心劳", "t": "冀求不执着;三心二意"}, {"w": "意足心满", "t": "非常满足"}, {"w": "意树", "t": "喻意念。佛教认为人的一切善果、恶果都由意念所生"}, {"w": "意宪", "t": "意志,意思"}, {"w": "意望", "t": "愿望,希望。"}]}, {"meaning": "胸怀;内心。", "cites": [{"t": "除尔贪图,祗慎意业。", "b": "《云门颂》"}], "words": [{"w": "意业", "t": "佛教语。指内心的贪、淫、痴等心理行为"}, {"w": "意气超迈", "t": "器宇轩昂,抱负远大"}, {"w": "意概", "t": "气概,胸怀"}, {"w": "意会", "t": "内心领会。"}]}, {"meaning": "情意;感情。", "cites": [{"t": "醉翁之意不在酒,在乎山水之间也。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "久之,目似瞑,意暇甚。", "b": "《聊斋志异》"}], "words": [{"w": "意蕊横飞", "t": "非常高兴"}, {"w": "意得过", "t": "过意得去"}, {"w": "意孜孜", "t": "情意缠绵"}, {"w": "意不过", "t": "情意上过不去"}, {"w": "意分", "t": "交情,情分"}, {"w": "意好", "t": "感情"}, {"w": "意孜孜", "t": "情意缠绵貌"}, {"w": "意性", "t": "情态"}, {"w": "意情", "t": "情意。"}]}, {"meaning": "意气; 气势。", "cites": [{"t": "意色举止,不异于常。", "b": "《世说新语·雅量》"}], "words": [{"w": "意大", "t": "傲慢"}, {"w": "意小", "t": "小气,气量小"}, {"w": "意局", "t": "气度"}, {"w": "意脉", "t": "气质;情态"}, {"w": "意量", "t": "气度"}, {"w": "意貌", "t": "神色"}, {"w": "意调", "t": "意境"}, {"w": "意界", "t": "意境,境界。"}]}, {"meaning": "意图。", "cites": [{"t": "用君之心,行君之意。", "b": "《楚辞》"}, {"t": "一狼洞其中,意将隧入以攻其后也。", "b": "《聊斋志异·狼三则》"}]}, {"meaning": "神情、态度。", "cites": [{"t": "其一犬坐于前。久之,目似瞑,意暇甚。", "b": "《聊斋志异·狼三则》"}, {"t": "意少舒。", "b": "《虞初新志·秋声诗自序》"}]}, {"meaning": "意料;猜测。", "cites": [{"t": "而小人善意。臣意之也。", "b": "《管子·小问》"}, {"t": "何意致不厚。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "意北亦尚可以。", "b": "宋·文天祥《指南录·后序》"}, {"t": "当其为里正、受扑责时,岂意其至此哉?", "b": "《聊斋志异·促织》"}, {"t": "不意作缘。", "b": "清·周容《芋老人传》"}, {"t": "多以意构。", "b": "蔡元培《图画》"}], "words": [{"w": "意定", "t": "猜定"}, {"w": "意度", "t": "揣测;设想。"}]}, {"meaning": "怀疑。", "cites": [{"t": "于是天子意梁。", "b": "《汉书·梁孝王武传》"}], "words": [{"w": "意意似似", "t": "意意思思。犹犹豫豫;吞吞吐吐"}, {"w": "意疑", "t": "怀疑"}, {"w": "意忌", "t": "疑忌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2997wx','誊','1','téng','言','13','','[{"pinyin": "téng", "defs": [{"meaning": "照原稿抄写清楚。", "cites": [{"t": "謄,迻书也。从言,朕声。", "b": "《说文》。按,謄录字,元代始用之。"}, {"t": "自剪短笺誊断稿,不嫌墨浅字倾欹。", "b": "陆游文"}], "words": [{"w": "誊一遍;誊本", "t": "根据原本抄写的本子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2998wx','粮','1','liáng','米','13','','[{"pinyin": "liáng", "defs": [{"meaning": "(形声。从米,量声。本义:旅行用的干粮;行军作战用的军粮)。"}, {"meaning": "同本义。", "cites": [{"t": "糧,谷食也。", "b": "《说文》"}]}, {"meaning": "桂馥曰:“谷也者,非古训。糧乃行者之干食。”。", "cites": [{"t": "则治其糧与其食。", "b": "《周礼·地官·廪人》。注:“行道曰糧,谓糒也。”"}, {"t": "共其资糧屝屦。", "b": "《左传·僖公四年》。注:“糧谓米粟,行道之食也。”"}, {"t": "兵精粮多。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "多载资粮。", "b": ""}, {"t": "赢粮而景从。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "粮仗", "t": "粮草和兵器"}, {"w": "粮台", "t": "清代经理部队粮饷军需的机构。"}]}, {"meaning": "引申指谷类;粮食。", "cites": [{"t": "在陈绝糧。", "b": "《论语·卫灵公》。释文:“糧,郑本作粻。”"}, {"t": "粻,食米也。", "b": "《说文新附》"}, {"t": "乃裹糇糧。", "b": "《诗·大雅·公刘》。释文:“糧,本亦作粮”。"}, {"t": "韩绝其粮道。", "b": "《史记》"}], "words": [{"w": "粮站;漕粮", "t": "漕运的粮食"}, {"w": "秋粮", "t": "秋季收获的粮食"}, {"w": "粮房书办", "t": "管粮库的小吏。"}]}, {"meaning": "田赋。", "cites": [{"t": "戒州县加收耗粮。", "b": "《宋史·高宗纪》"}], "words": [{"w": "钱粮", "t": "田赋"}, {"w": "完粮", "t": "交纳钱粮"}, {"w": "粮户", "t": "缴纳田赋之民户。方言亦指地主。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('2999wx','数','1','shǔ shù','攵','13','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从攴(pū),娄声。本义:点数;计算)。"}, {"meaning": "同本义。", "cites": [{"t": "數,计也。", "b": "《说文》"}, {"t": "以岁之上下数邦用。", "b": "《周礼·廪人》"}, {"t": "递数之不能终其物。", "b": "《礼记·儒行》"}, {"t": "善数不用筹策。", "b": "《老子》"}, {"t": "珠可历历数也。", "b": "明·魏学洢《核舟记》"}, {"t": "自董卓以来,豪杰并起,跨州连郡者不可胜数。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "从一数到十;数拾", "t": "查点;收拾"}, {"w": "数白道黑", "t": "卖弄口舌"}, {"w": "数白论黄", "t": "计较银钱。白:白银。黄:黄金"}, {"w": "数筹定点", "t": "数筹码计算时间"}, {"w": "数东瓜,道茄子", "t": "尽情谈论各种事情"}, {"w": "数米而炊,称柴而爨", "t": "比喻吝啬之极"}, {"w": "数数儿;数不胜数;数课", "t": "计算并予登记"}, {"w": "数墨", "t": "计算书本上的文字。"}]}, {"meaning": "枚举;列举。", "cites": [{"t": "其余以俭立名,以侈自败者多矣,不可遍数,聊举数人以训汝。", "b": "宋·司马光《训俭示康》"}, {"t": "数吕师孟叔侄为逆。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "不可胜数;历数其罪;数之于前", "t": ""}]}, {"meaning": "数落;责备。", "cites": [{"t": "数,责也。", "b": "《广雅》"}, {"t": "后世其追数吾过乎。", "b": "《列子·周穆五》"}, {"t": "使韩仓数之。", "b": "《战国策·秦策》"}, {"t": "日暮,至豪民第门,捽使跪,数之曰。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "数驳", "t": "方言。责备;教训"}, {"w": "数骂", "t": "数落责骂"}, {"w": "数说;数骂", "t": "责骂"}, {"w": "数让;数道", "t": "责难,责备"}, {"w": "数喇", "t": "数落;数说。"}]}, {"meaning": "诉说,称说。", "cites": [{"t": "故诵数以贯之,思索以通之…", "b": "《荀子·劝学》"}], "words": [{"w": "数贫嘴", "t": "油嘴肖舌;耍嘴皮子"}, {"w": "数黄道黑", "t": "数黄论黑。指说长道短。"}]}]}, {"pinyin": "shù", "defs": [{"meaning": "数目;数量。", "cites": [{"t": "窃怜爱之,愿令得补黑衣之数。", "b": "《战国策·赵策》"}, {"t": "五陵少年争缠头,一曲红绡不知数。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "报数", "t": "报告数目"}, {"w": "数计", "t": "以数字来计算"}, {"w": "数珠儿", "t": "念珠"}, {"w": "可被2除尽的数;自然数、整数、有理数、无理数、实数或复数;基数;单数;复数", "t": ""}]}, {"meaning": "道数,方法。", "cites": [{"t": "故为国之数,务在垦草。", "b": "《商君书》"}]}, {"meaning": "技艺,如博弈的技艺。", "cites": [{"t": "今夫弈之为数,小数也。", "b": "《孟子·告子上》"}]}, {"meaning": "气数;命运。", "cites": [{"t": "卫青不败由天幸,李广无功缘数奇。", "b": "唐·王维《老将行》"}, {"t": "向使三国各爱其地,齐人勿附于秦,刺客不行,良将犹在,则胜负之数,存亡之理,当与秦相较,或未易量。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "数奇", "t": "命运不佳;遭遇不顺"}, {"w": "数命", "t": "命运"}, {"w": "数尽禄终", "t": "死亡"}, {"w": "数劫", "t": "厄运。"}]}, {"meaning": "策略;权术。", "cites": [{"t": "以计求便,以数取利。", "b": "汉·王充《论衡》"}]}, {"meaning": "规律;必然性。", "cites": [{"t": "汉世外戚,自东、西京十有余族,非徒豪横盈极,自取灾故,必于贻衅后主,以至颠败者,其数有可言焉。", "b": "《后汉书》"}]}, {"meaning": "道理。", "cites": [{"t": "夫以疏远与近爱信争,其数不胜也。", "b": "《韩非子》"}]}, {"meaning": "礼数;仪节。", "cites": [{"t": "今嬖宠之丧,不敢择位,而数于守适。", "b": "《左传·庄公十八年》"}]}, {"meaning": "特指方术,如占卜之类。", "cites": [{"t": "数有所不逮,神有所不通。", "b": "《楚辞·卜居》"}], "words": [{"w": "数家", "t": "精于术数的人"}, {"w": "数术", "t": "术数。"}]}, {"meaning": "几个,若干。", "cites": [{"t": "忽逢桃花林,夹岸数百步,中无杂树。", "b": "晋·陶渊明《桃花源记》"}, {"t": "今将军诚能命猛将统兵数万,与豫州协规同力,破操军必矣。", "b": "宋·司马光《资治通鉴》"}], "words": [{"w": "数四", "t": "犹三四,表示为数不多"}, {"w": "数粒", "t": "几粒"}, {"w": "数人;数十,数百,数千,数万;数本", "t": "几棵;几株"}, {"w": "数众", "t": "佛教称其教徒人数为“众”,有若干僧则称若干众"}, {"w": "数武", "t": "几步"}, {"w": "数射", "t": "几射。射:一箭能及的距离"}, {"w": "数家", "t": "几派;几家;几户。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3000wx','煎','1','jiān','灬','13','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。从火,前声。“火”字写在下面时常变形成为四点。本义:煎熬)。"}, {"meaning": "同本义。", "cites": [{"t": "煎,熬也。", "b": "《説文》"}, {"t": "煎,火干也。凡有汁而干谓之煎。", "b": "《方言七》"}, {"t": "帐下烹煎皆美人。", "b": "苏轼《豆粥》"}], "words": [{"w": "煎米", "t": "指熬粥"}, {"w": "煎服", "t": "煎汁服下"}, {"w": "煎盘", "t": "方言。平底锅"}, {"w": "煎豆摘瓜", "t": "喻亲属相残。"}]}, {"meaning": "比喻折磨;使其痛苦。", "cites": [{"t": "渐见愁煎迫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "逆以煎我怀。", "b": ""}], "words": [{"w": "煎熬", "t": "比喻折磨"}, {"w": "煎情", "t": "焦侓的心情。"}]}, {"meaning": "一种烹饪方法。锅里放油加热后,把食物放进去,使表面变成焦黄。", "cites": [{"t": "手团作饼,膏油煎。", "b": "《齐民要术·饼炙》"}], "words": [{"w": "煎点", "t": "油煎的糕点"}, {"w": "煎鱼;煎鸡蛋", "t": ""}]}, {"meaning": "消熔。", "cites": [{"t": "徒恨芳膏,煎灼灯明。", "b": "《后汉书·何顒传》"}], "words": [{"w": "煎蒸", "t": "燃烧而消熔"}, {"w": "煎销", "t": "熔化。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3001wx','塑','1','sù','土','13','','[{"pinyin": "sù", "defs": [{"meaning": "(形声。从土,朔(sù)声。本义:用泥土抟成人物形象)。"}, {"meaning": "同本义。", "cites": [{"t": "明道先生(程颢)坐如泥塑人。", "b": "《二程全书·传闻杂记》"}], "words": [{"w": "塑人;塑像;泥塑;面塑", "t": ""}]}, {"meaning": "呆愣。", "cites": [{"t": "把个公子如同泥塑一般,塑在那里。", "b": "《儿女英雄传》"}]}, {"meaning": "垒砌。", "cites": [{"t": "但奇妙的是在那堂屋的天井边上塑着一个一连有三口锅的长灶头。", "b": "郭沫若《革命春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3002wx','慈','1','cí','心','13','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从心,兹声。本义:慈爱)。"}, {"meaning": "同本义。", "cites": [{"t": "慈,爱也。", "b": "《说文》"}, {"t": "尧不慈舜不孝。", "b": "《庄子·盗跖》"}, {"t": "夫慈者不忍,而惠者好与也。", "b": "《韩非子·内储说上》"}, {"t": "一曰慈幼。", "b": "《周礼·大司徒》。注:“爱幼少也。”"}, {"t": "慈和遍服曰顺。", "b": "《左传·昭公二十八年》。服注:“上爱下曰慈。”"}, {"t": "其次为慈母。", "b": "《礼记·内则》。注:“慈母知其嗜欲者也。”"}, {"t": "慈者,父母之高行也。", "b": "《管子·形势解》"}, {"t": "亲爱利子谓之慈,恻隐怜人谓之慈。", "b": "《贾子道术》"}, {"t": "父母威严而有慈,则子女畏慎而生孝矣。", "b": "《颜氏家训》"}], "words": [{"w": "慈幼", "t": "慈爱幼儿"}, {"w": "慈亲", "t": "慈爱双亲"}, {"w": "慈泪", "t": "父母哀痛子女所流的眼泪。"}]}, {"meaning": "对父母孝敬奉养。", "cites": [{"t": "慈以旨甘。", "b": "《礼记·内则》。注:“爱敬进之也。”"}, {"t": "虽孝子慈孙。", "b": "《孟子》"}, {"t": "不慈孝于父母。", "b": "《国语·齐语》"}, {"t": "事亲则慈孝。", "b": "《庄子·渔父》"}], "words": [{"w": "慈良", "t": "孝顺"}, {"w": "慈孝", "t": "孝敬"}, {"w": "慈命", "t": "对尊上命令的敬称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3003wx','煤','1','méi','火','13','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从火,某声。本义:烟尘)。"}, {"meaning": "指墨。", "cites": [{"t": "中官欲于苑中作墨灶,取西湖九里松作煤。", "b": "宋·陆游《老学庵笔记》"}], "words": [{"w": "煤精", "t": "煤的一种。色黑,质硬,可用以雕刻工艺品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3004wx','煌','1','huáng','火','13','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从火,皇声。“皇”亦兼表字义。本义:光明;光亮)。"}, {"meaning": "同本义。", "cites": [{"t": "煌,煌煇也。", "b": "《说文》"}, {"t": "煌,光也。", "b": "《苍颉篇》"}, {"t": "煌光驰而星流。", "b": "《东京赋》"}, {"t": "煌然而成篇谓之篇。", "b": "姚华《论文后编》"}], "words": [{"w": "煌煌烨烨", "t": "明亮光辉。形容火势旺盛"}, {"w": "煌熠", "t": "光明灿烂"}, {"w": "煌荣", "t": "辉煌"}, {"w": "煌荧", "t": "闪耀"}, {"w": "煌熠", "t": "辉耀"}, {"w": "煌耀", "t": "辉煌。"}]}, {"meaning": "有火光的,闪耀的。", "cites": [{"t": "煌,火状。", "b": "《广韵·唐韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3005wx','满','1','mǎn','氵','13','','[{"pinyin": "mǎn", "defs": [{"meaning": "(形声。本义:填满,布满)。"}, {"meaning": "同本义。", "cites": [{"t": "满,盈溢也。", "b": "《说文》"}, {"t": "无几何而往,则户外之屦满矣。", "b": "《庄子·列御寇》"}, {"t": "荆有云梦,犀兕麋鹿满之。", "b": "《墨子·公输》"}, {"t": "奸邪满侧。", "b": "《韩非子·扬权》"}, {"t": "溪云初起日沉阁,山雨欲来风满楼。", "b": "唐·许浑《咸阳城东楼》"}, {"t": "归来泪满巾。", "b": "宋·张俞《蚕妇》"}, {"t": "黄四娘家花满溪。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "蒌蒿满地。", "b": "宋·苏轼《惠崇春江晚景》"}, {"t": "初闻涕泪满衣裳。", "b": "唐·杜甫《闻官军收河南河北》"}], "words": [{"w": "满口胡柴", "t": "满口胡说"}, {"w": "满坑满谷", "t": "形容积聚得特多"}, {"w": "满面生花", "t": "满面笑容"}, {"w": "满天星", "t": "指眼里冒出许多金星"}, {"w": "满眼", "t": "充满视野"}, {"w": "满堂", "t": "充满堂上"}, {"w": "满衍", "t": "布满平野,遍野"}, {"w": "满肚子", "t": "满肚皮。充满肚皮;充满心中"}, {"w": "满实", "t": "充盈"}, {"w": "满怀信心", "t": "心中充满自信心"}, {"w": "满脸春色", "t": "满脸春风。比喻满脸充满喜悦的笑容"}, {"w": "满听", "t": "满耳"}, {"w": "满溢", "t": "太多而漫出"}, {"w": "满生生", "t": "很满的样子"}, {"w": "满心", "t": "心中充满某种情绪或意愿"}, {"w": "满礼", "t": "满理。充足的理由"}, {"w": "满顶", "t": "不留余地"}, {"w": "满饮", "t": "斟满而饮。"}]}, {"meaning": "足够,达到一定限度。", "cites": [{"t": "虽长不满七尺,而心雄万夫。", "b": "李白《与韩荆州书》"}], "words": [{"w": "满散", "t": "功德圆满时的散斋;为祈祷、祝寿等开设道场,期满结束"}, {"w": "满日", "t": "做工做到规定的年龄期限"}, {"w": "满服", "t": "服丧期满"}, {"w": "满破", "t": "最多;大不了"}, {"w": "满话", "t": "没有回旋余地的话"}, {"w": "拉满弓", "t": "又叫满把。"}]}, {"meaning": "烦闷。", "cites": [{"t": "…欢欣愤满以送之。", "b": "《说苑·善说》"}, {"t": "故烦满而囊缩。", "b": "《素问·热论》"}]}, {"meaning": "饱满;丰满。", "cites": [{"t": "穗阅而青零,多秕而不满。", "b": "《吕氏春秋·审时》"}]}, {"meaning": "郁闷,闷塞不畅。", "cites": [{"t": "必至下胀而上满。", "b": "《老残游记》"}]}, {"meaning": "全,整个。", "cites": [{"t": "满坐寂然。", "b": "《虞初新志·秋声诗自序》"}, {"t": "满坐宾客。", "b": ""}, {"t": "满面尘灰烟火色。", "b": "唐·白居易《卖炭翁》"}, {"t": "满目萧然。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "寂寞空庭春欲晚,梨花满地不开门。", "b": "刘方平《春怨》"}], "words": [{"w": "满不在意", "t": "全然不放在心上,不当一回事"}, {"w": "满天打油飞", "t": "方言。谓到处游荡,没有落脚的地方"}, {"w": "满处", "t": "到处"}, {"w": "满世界", "t": "到处"}, {"w": "满堂", "t": "整个堂上"}, {"w": "满岁", "t": "一年,整年"}, {"w": "满处", "t": "犹到处。"}]}, {"meaning": "自满。", "cites": [{"t": "满招损,谦受益。", "b": "《书·大禹谟》"}, {"t": "克勤于邦,克勤于家,不自满假。", "b": "《书·大禹谟》"}, {"t": "踌躇满志。", "b": "《庄子·养生主》"}], "words": [{"w": "满大", "t": "自满自大"}, {"w": "满招损,谦受益", "t": "自满招致损失,谦虚得到益处"}, {"w": "满假", "t": "自满自大"}, {"w": "满望", "t": "满足所望。"}]}, {"meaning": "中国少数民族名。“满族”。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3006wx','漠','1','mò','氵','13','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从水,莫声。本义:沙漠) 同本义。", "cites": [{"t": "漠,北方流沙也。", "b": "《说文》"}, {"t": "逾陇堆兮渡漠。", "b": "《楚辞·疾世》"}, {"t": "大漠孤烟直,长河落日圆。", "b": "唐·王维《使至塞上》"}], "words": [{"w": "漠北,漠南(蒙古高原大沙漠以南(北)的地区", "t": ""}, {"w": "漠野", "t": "我国北方沙漠地区。"}]}, {"meaning": "淡泊,恬淡,即不追求名利。", "cites": [{"t": "澹而静乎!漠而清乎!调而闲乎!", "b": "《庄子·知北游》"}]}, {"meaning": "冷淡,不关心。", "cites": [{"t": "我而漠然置之。不可言也。", "b": "梁启超《少年中国说》"}], "words": [{"w": "漠如", "t": "犹漠然。冷淡,不关心"}, {"w": "漠置", "t": "漠然置之"}, {"w": "漠尔", "t": "轻视,不在意。"}]}, {"meaning": "空廓,寂静。", "cites": [{"t": "夫虚静恬淡,寂漠无为者,万物之本也。", "b": "《庄子·天道》"}, {"t": "野寂漠其无人。", "b": "《楚辞·远游》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3007wx','滇','1','diān','氵','13','','[{"pinyin": "diān", "defs": [{"meaning": "滇池。", "cites": [{"t": "益州池名。", "b": "《说文》"}]}, {"meaning": "湖名。又称为昆明湖、昆明池、滇南泽。在云南省昆明市西南。"}, {"meaning": "中国云南省的别称。"}, {"meaning": "古国名 。在今云南省东部滇池附近地区。"}, {"meaning": "古族名 。西南夷的一支。战国至秦汉时,分布在今云南滇池附近,中心在今晋宁县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3008wx','源','1','yuán','氵','13','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从水,原声。“原”有表义作用,指水源。本义:水源,源泉。字本作“原”)。"}, {"meaning": "同本义。", "cites": [{"t": "或源也,或委也。", "b": "《礼记·学记》"}, {"t": "祈祀山川百源。", "b": "《礼记·月令》"}, {"t": "犹浊其源而求其清流。", "b": "《礼记·礼乐志》"}, {"t": "岸势犬牙差互,不可知其源。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "源委", "t": "指水的发源和归宿。引申为事情的本末和底细"}, {"w": "源理", "t": "水的本源和支流。"}]}, {"meaning": "来源;根源。", "cites": [{"t": "启生人之耳目,穷法度之本源。", "b": "《旧唐书·儒学传序》"}], "words": [{"w": "源本", "t": "根本"}, {"w": "源由", "t": "根由"}, {"w": "源起", "t": "事物发生的根源。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3009wx','滤','1','lǜ','氵','13','','[{"pinyin": "lǜ", "defs": [{"meaning": "(形声。从水,虑声。本义:用纱、布等过水,使水清洁) 过滤。", "cites": [{"t": "滤,滤水也,一曰洗也,澄也。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3010wx','滥','1','làn','氵','13','','[{"pinyin": "làn", "defs": [{"meaning": "(形声。从水,监声。本义:浮起,浮现)。"}, {"meaning": "同本义。", "cites": [{"t": "滥,泛也。", "b": "《说文》"}, {"t": "江出于岷山,其始出也,其源可以滥觞。", "b": "《荀子·子道》"}, {"t": "滥泉正出。", "b": "《尔雅·释水》"}, {"t": "滥水之潘为渊。", "b": "《列子·黄帝》"}]}, {"meaning": "大水漫出,泛滥。", "cites": [{"t": "大水泛滥郡国十五有余。", "b": "《汉书·谷永传》"}, {"t": "其水阳焊不耗,阴霖不滥。", "b": "《水经注·湿水》"}, {"t": "当尧之时,水逆行,泛滥于中国。", "b": "《孟子·滕文公》"}], "words": [{"w": "泛滥", "t": "江河湖泊的水溢出"}, {"w": "滥泉", "t": "从地下向上涌出的泉水"}, {"w": "滥汜", "t": "泛滥,浮沉。"}]}, {"meaning": "浸渍,泡在水里。", "cites": [{"t": "滥车之水。", "b": "《管子·地图》"}]}, {"meaning": "贪欲;卑污。", "cites": [{"t": "虞公滥于宝于马。", "b": "《吕氏春秋》"}], "words": [{"w": "滥官", "t": "贪官"}, {"w": "滥墨", "t": "指官吏贪财好贿者"}, {"w": "滥溢", "t": "胡作非为。"}]}, {"meaning": "收聚。", "cites": [{"t": "至刑不滥。", "b": "《淮南子·汜论》"}]}, {"meaning": "过度;超过限度;漫无准则。", "cites": [{"t": "生穑省用,不滥其度。", "b": "《周书·程典》"}, {"t": "小人究斯滥矣。", "b": "《论语·卫灵公》"}]}, {"meaning": "虚妄不实。", "cites": [{"t": "不僭不滥。", "b": "《诗·商颂·殷武》"}], "words": [{"w": "滥言", "t": "虚妄不实的言词"}, {"w": "滥词", "t": "虚妄不实的话"}, {"w": "滥套", "t": "指文章中完全抄袭前人,毫无创新之见。"}]}, {"meaning": "用同“烂”。"}, {"meaning": "任意地;肆意地。", "cites": [{"t": "不许滥诛骨肉。", "b": "《资治通鉴》"}]}, {"meaning": "假借为“鉴”。浴盆。", "cites": [{"t": "夫灵公有妻三人,同滥而浴。", "b": "《庄子·则阳》"}, {"t": "钟鼎壶濫。", "b": "《吕氏春秋·节丧》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3011wx','滔','1','tāo','氵','13','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从水,舀(yǎo)声。本义:水势盛大的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "滔,水漫漫大貌。", "b": "《说文》"}, {"t": "滔,漫也。", "b": "《广雅》"}, {"t": "象恭滔天。", "b": "《书·尧典》"}, {"t": "浩浩滔天。", "b": ""}, {"t": "汶水滔滔。", "b": "《诗·齐风·载驱》"}, {"t": "滔滔江汉。", "b": "《诗·小雅·四月》"}, {"t": "洪水滔天,浩浩怀山襄陵。", "b": "《书·益稷》"}], "words": [{"w": "滔涸", "t": "水漫溢与干涸"}, {"w": "滔漭", "t": "水弥漫浩广的样子"}, {"w": "滔滔滚滚,滔漫", "t": "大水漫溢。"}]}, {"meaning": "傲慢,专横霸道。", "cites": [{"t": "士不滥, 官不滔。", "b": "《左传·昭公二十六年》"}], "words": [{"w": "滔德", "t": "倨慢不恭的品格。"}]}, {"meaning": "使大水泛滥。", "cites": [{"t": "舜之时,共工振滔洪水,以薄空桑。", "b": "《淮南子》"}]}, {"meaning": "云集一起地涌往。", "cites": [{"t": "无器而民滔乎前。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3012wx','溪','1','xī','氵','13','','[{"pinyin": "xī", "defs": [{"meaning": "(溪本作谿)。"}, {"meaning": "山间不与外界相通的小河沟。", "cites": [{"t": "嵠,山渎无所通者。", "b": "《说文》"}, {"t": "是故溪狭者速涸。", "b": "《墨子·亲士》"}, {"t": "子越自石溪。", "b": "《左传·文公十六年》。注:“入庸道。”"}, {"t": "振溪通谷,蹇产沟渎。", "b": "司马相如《上林赋》"}], "words": [{"w": "溪步", "t": "水涯与渡船处"}, {"w": "溪径", "t": "小路。引申谓途径。"}]}, {"meaning": "泛指小河流。", "cites": [{"t": "武陵有五溪,谓雄溪 、无溪、酉溪、辰溪其一焉。", "b": "《水经注·沅水》注"}, {"t": "缘溪行,忘路之远近。", "b": "晋·陶渊明《陶渊明集·桃花源记》"}, {"t": "灌水之阳有溪焉,东流入潇水。", "b": "柳宗元《愚溪诗序》"}], "words": [{"w": "溪头", "t": "溪边。"}]}, {"meaning": "没有出口的山沟。", "cites": [{"t": "不临深溪,不知地之厚也。", "b": "《荀子·劝学》"}]}, {"meaning": "古州名 。在湖南省境内。", "cites": [{"t": "以溪、奖、锦三州降楚。", "b": "《读史方舆纪要》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3013wx','溜','1','liū liù','氵','13','','[{"pinyin": "liū", "defs": [{"meaning": "瞟,偷偷地看。", "cites": [{"t": "说着,却把眼溜着金桂一笑。", "b": "《红楼梦》"}]}, {"meaning": "偷偷地拿。", "cites": [{"t": "差人各溜过几件细软东西。", "b": "《醒世恒言》"}]}, {"meaning": "鸣,叫。", "cites": [{"t": "闭凝盼,声声燕语明如剪,呖呖莺声溜的圆。", "b": "清·孔尚任《桃花扇》"}]}]}, {"pinyin": "liù", "defs": [{"meaning": "(形声。从水,留声。本义:水名)。"}, {"meaning": "古水名。又名“潭水”。", "cites": [{"t": "溜水出郁林郡。", "b": "《说文》"}]}, {"meaning": "即今纵贯广西中北部的融江、柳江及黔江。"}, {"meaning": "屋檐滴水处。", "cites": [{"t": "三进及溜,而后视之。", "b": "《左传·宣公二年》"}]}, {"meaning": "某一地点附近的地方。", "cites": [{"t": "这不是咱们这溜儿都装上自来水了吗?", "b": "老舍《龙须沟》"}], "words": [{"w": "这溜儿果树很多", "t": ""}]}, {"meaning": "液体向下流。", "cites": [{"t": "生犹悬水溜,死若波澜停。", "b": "南朝宋·孔欣《置酒高堂上》"}]}, {"meaning": "斜视,瞥,迅速而短暂地看。", "cites": [{"t": "那贾芸一面走,一面拿眼把小红一溜。", "b": "《红楼梦》"}], "words": [{"w": "溜瞅", "t": "斜着眼睛窥视"}, {"w": "溜溜", "t": "瞟,斜视。"}]}, {"meaning": "漫步;游逛。", "cites": [{"t": "在那海棠树边,悄悄溜了三回。", "b": "田间《赶车传》"}]}, {"meaning": "传唤。", "cites": [{"t": "到十六日,叫小厮拿了一个“都督府”的溜子,溜了一班戏子来谢神。", "b": "《儒林外史》"}], "words": [{"w": "溜子", "t": "溜单。注明官衔的帖子。"}]}, {"meaning": "水势迅猛。", "cites": [{"t": "黄河水溜,不是当耍的。", "b": "清·孔尚任《桃花扇》"}], "words": [{"w": "溜道", "t": "湍急的河道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3014wx','漓','1','lí','氵','13','','[{"pinyin": "lí", "defs": [{"meaning": "漓江 。水名,在广西东北部。为桂江上源。同湘江上游间有灵渠(湘桂运河)相通。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3015wx','滚','1','gǔn','氵','13','','[{"pinyin": "gǔn", "defs": [{"meaning": "(形声。从水,衮声。本义:大水奔流貌)。"}, {"meaning": "同本义。", "cites": [{"t": "无边落叶萧萧下,不尽长江滚滚来。", "b": "唐·杜甫《登高》"}], "words": [{"w": "滚滚", "t": "水涌流的样子。"}]}, {"meaning": "连续不断,急速翻腾的样子。", "cites": [{"t": "尘滚滚东向驰去。后遂不复至。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "滚滚滔滔", "t": "不绝的样子"}, {"w": "滚滚当潮", "t": "滚滚当道。相继不断地掌握政权。"}]}, {"meaning": "圆的。", "cites": [{"t": "个个是生青滚壮。", "b": "茅盾《春蚕》"}]}, {"meaning": "滚动,滚转。", "cites": [{"t": "球滚来滚去", "b": ""}, {"t": "譬如甑蒸饭,气从下面滚到上面又滚下,只管在里面滚,便蒸得熟。", "b": "《朱子语类》"}], "words": [{"w": "滚落;滚碌", "t": "滚动"}, {"w": "滚尘", "t": "翻滚的尘土"}, {"w": "滚绣球;滚崖", "t": "从陡峭的岩石上滚下来的一种技巧。"}]}, {"meaning": "液体温度达到沸点以上而翻腾。", "cites": [{"t": "俗以汤之未滚者为盲眼,初滚曰蟹眼,渐大曰鱼眼。", "b": "宋·庞元英《谈薮》"}], "words": [{"w": "水滚了!滚白水", "t": "白开水"}, {"w": "滚汤泼雪", "t": "形容极为容易。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3016wx','溢','1','yì','氵','13','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从水,益声。本作“益”。象水从器皿中漫出。本义:水漫出来)。"}, {"meaning": "同本义。", "cites": [{"t": "溢,器满也。", "b": "《说文》"}, {"t": "溢,盈也。", "b": "《尔雅》"}, {"t": "溢,满也。", "b": "《广雅》。按,过满为溢。"}, {"t": "满而不溢。", "b": "《考经·诸侯》"}, {"t": "东流不溢,孰知其故?", "b": "《楚辞》"}, {"t": "惧满溢。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "溢于辞。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "溢决", "t": "水满破堤"}, {"w": "溢满", "t": "平满。"}]}, {"meaning": "水泛滥成灾,淹没。", "cites": [{"t": "虽有凶旱水溢,民无菜色。", "b": "《礼记》"}], "words": [{"w": "溢涌", "t": "洪水腾涌。"}]}, {"meaning": "过度,过分。", "cites": [{"t": "夫两喜必多溢美之言,两怒必多溢恶之言。", "b": "《庄子》"}], "words": [{"w": "溢羡", "t": "过分的利润"}, {"w": "溢誉", "t": "过度的称誉"}, {"w": "溢恶", "t": "过分指责"}, {"w": "溢利", "t": "过分的利益"}, {"w": "溢分", "t": "过分"}, {"w": "溢美", "t": "过分赞美"}, {"w": "溢望", "t": "过分地希望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3017wx','溯','1','sù','氵','13','','[{"pinyin": "sù", "defs": [{"meaning": "(形声。从水,朔(sù)声。本义:端直地逆流而上)。"}, {"meaning": "同本义。", "cites": [{"t": "逆流而上曰溯洄。", "b": "《尔雅》"}, {"t": "溯洄从之,道阻且长。", "b": "《诗·秦风·蒹葭》"}, {"t": "至于夏水襄陵,沿溯阻绝。", "b": "郦道元《水经注·江水》"}, {"t": "实以四日半溯流流行七百里云。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "溯涉", "t": "逆流跋涉"}, {"w": "溯流", "t": "逆着水流方向"}, {"w": "溯洄", "t": "逆流而上"}, {"w": "溯游", "t": "顺着河流向下。"}]}, {"meaning": "探求。", "cites": [{"t": "由此上溯到一千八百四十年,从那时起,为了反对内外敌人,争取民族独立和人民自由幸福,在历次斗争中牺牲的人民英雄们永垂不朽!", "b": "《人民英雄永垂不朽》"}], "words": [{"w": "溯流穷源", "t": "推寻原委"}, {"w": "溯通", "t": "探求疏通。"}]}, {"meaning": "追念思慕。", "cites": [{"t": "学生虽溯洄思切,自念风尘俗吏,末由再睹仙颜,今何幸于此处相遇。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3018wx','滨','1','bīn','氵','13','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从水,宾声。本义:水边)。"}, {"meaning": "湖、河、海的水边陆地。", "cites": [{"t": "南涧之滨。", "b": "《诗·召南·采蘋》"}, {"t": "率土之滨。", "b": "《诗·小雅·北山》。传:“滨,涯也。”"}, {"t": "海滨广斥。", "b": "《书·禹贡》"}, {"t": "屈原至于江滨。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "湘江之滨;溪滨;滨涯", "t": "水边"}, {"w": "湖滨;海滨", "t": ""}]}, {"meaning": "古州名 。五代周显德三年(公元956年)改赡国军置,治所在渤海(今滨县)。辖境相当于今山东省滨县、沾化、利津和博兴县的一部分。"}, {"meaning": "靠近;临近。", "cites": [{"t": "夫管夷吾射寡人中钩,是以滨于死。", "b": "《国语·齐语》"}, {"t": "至乎章和之初,降者十余万人,议者欲置之滨塞。", "b": "《后汉书·袁安传》"}, {"t": "滨于殆,而有喜。", "b": "刘禹锡《鉴药》"}, {"t": "而邹、鲁滨洙、泗。", "b": "《史记》"}, {"t": "有人滨河而居,习于水。", "b": "《列子·说符》"}], "words": [{"w": "滨海", "t": "靠近海边;沿海"}, {"w": "滨近", "t": "临近,靠近"}, {"w": "滨就", "t": "接近成功。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3019wx','溶','1','róng','氵','13','','[{"pinyin": "róng", "defs": [{"meaning": "(形声。从水,容声。本义:水盛大的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "溶,水盛也。", "b": "《说文》"}, {"t": "体溶溶而东回。", "b": "《楚辞·逢纷》。注:“波貌。”"}], "words": [{"w": "溶溢", "t": "水盛大的样子"}, {"w": "溶溶荡荡", "t": "水波浮动的样子"}, {"w": "溶溶澹澹", "t": "水波盛大起伏的样子"}, {"w": "溶漾", "t": "水波荡漾的样子"}, {"w": "溶瀛", "t": "水势浩大的样子。"}]}, {"meaning": "广大;盛大。", "cites": [{"t": "氛旄溶以天旋兮。", "b": "《后汉书·张衡传》"}]}, {"meaning": "容颜,容貌。", "cites": [{"t": "听言之道,溶若甚醉。", "b": "《韩非子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3020wx','溺','1','nì niào','氵','13','','[{"pinyin": "nì", "defs": [{"meaning": "没入水中。", "cites": [{"t": "嫂溺,则援之以手乎?", "b": "《孟子·离娄上》"}, {"t": "溺死者。", "b": "《吕氏春秋·察今》"}, {"t": "河中溺死。", "b": "《汉书·李广苏建传》"}, {"t": "人马烧溺死者甚众。", "b": "《资治通鉴》"}], "words": [{"w": "溺女", "t": "将刚生下的女婴投入水中淹死"}, {"w": "沉溺", "t": "陷入不良的境地"}, {"w": "溺没", "t": "沉没"}, {"w": "溺溺", "t": "沉没"}, {"w": "溺毙", "t": "淹死。"}]}, {"meaning": "沉湎,无节制。", "cites": [{"t": "困于所溺。", "b": "宋·欧阳修《伶官传·序》"}], "words": [{"w": "溺信", "t": "沉迷"}, {"w": "溺志", "t": "心志沉湎于某种事情"}, {"w": "溺情", "t": "思想感情沉湎于某个方面"}, {"w": "溺意", "t": "心志沉湎于某个方面"}, {"w": "溺心", "t": "潜沉心志"}, {"w": "溺惑", "t": "沉迷;迷信。"}]}, {"meaning": "陷于困境。", "cites": [{"t": "天下溺,援之以道。", "b": "《孟子·离娄上》"}]}, {"meaning": "失职 。如溺职。"}, {"meaning": "假借为“弱”。水浅,意谓水弱不能胜舟。"}]}, {"pinyin": "niào", "defs": [{"meaning": "排泄小便。后来作“尿”。", "cites": [{"t": "宾客饮者醉,更溺睢。(更:轮番。睢:范睢。)", "b": "《史记·范睢蔡泽列传》"}], "words": [{"w": "溺尿", "t": "解小便"}, {"w": "溺溲", "t": "撒尿。"}]}, {"meaning": "人或动物排泄的小便。", "cites": [{"t": "中热,故溺赤也。", "b": "《史记·扁鹊仓公列传》"}, {"t": "矢溺皆闭其中。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "溺盆子", "t": "小便盆"}, {"w": "溺壶", "t": "小便壶"}, {"w": "溺窝子", "t": "尿坑"}, {"w": "溺器", "t": "盛小便的器物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3021wx','粱','1','liáng','米','13','','[{"pinyin": "liáng", "defs": [{"meaning": "(形声。从米,梁省声。本义:植物名。古代指粟的优良品种,子实也称粱,为细粮)。"}, {"meaning": "同本义。", "cites": [{"t": "粱,米名也。", "b": "《说文》。按,即粟也,穈也。芑也。今小米之大而不黏者,其细而粘者谓之秫,古舂粟之率,自粝至于侍御皆言粱也。"}, {"t": "粱,好粟也。", "b": "《三苍》"}, {"t": "粱曰芗萁。又,大夫不食粱。", "b": "《礼记·曲礼》。注:“加食也。”"}, {"t": "夫膏粱之性难正也。", "b": "《国语·晋语》。注:“食之精者。”"}, {"t": "黄鸟黄鸟,无集于桑,无啄我粱。", "b": "《诗·小雅·黄鸟》"}], "words": [{"w": "粱糗", "t": "用稻粱制成的干粮"}, {"w": "粱菽", "t": "米与豆。"}]}, {"meaning": "高粱。"}, {"meaning": "精美的饭食。", "cites": [{"t": "含其粱肉。", "b": "《墨子·公输》"}]}, {"meaning": "又。", "cites": [{"t": "此犹粱肉与糠糟也。", "b": ""}], "words": [{"w": "粱米", "t": "优良的米"}, {"w": "粱饭", "t": "精良的米煮成的饭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3022wx','滩','1','tān','氵','13','','[{"pinyin": "tān", "defs": [{"meaning": "(形声。从水,难声。本义:河道中水浅流急多沙石的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "却放轻舟下急滩。", "b": "《唐崔道融溪夜诗》"}, {"t": "滩,水滩。", "b": "《广韵·平声寒韵》"}]}, {"meaning": "滩头。指江、河、湖、海边水涨淹没、水退显露的淤积平地。", "cites": [{"t": "云低岸花掩,水涨滩草没。", "b": "唐·岑参《江上阻风雨》"}, {"t": "惊起一滩鸥鹭。", "b": "宋·李清照《如梦令》"}]}, {"meaning": "等级。", "cites": [{"t": "这种奴隶叫作“三滩娃子”。滩是等级的意思。管家娃子为头滩,普通娃子为二滩,娃子的娃子为三滩。", "b": "郭沫若《十批判书》"}]}, {"meaning": "用于在平面上成灘的東西。", "cites": [{"t": "鼻子流出一大灘血。", "b": "楊朔《亂人坑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3023wx','慎','1','shèn','忄','13','','[{"pinyin": "shèn", "defs": [{"meaning": "(形声。从心,真声。本义:谨慎;慎重)。"}, {"meaning": "同本义。", "cites": [{"t": "慎,谨也。", "b": "《说文》"}, {"t": "慎,诚也。", "b": "《尔雅》"}, {"t": "慎,德之守也。", "b": "《国语·周语》"}, {"t": "僶勉就善谓之慎。", "b": "《贾子道术》"}, {"t": "慎尔优游。", "b": "《诗·小雅·白驹》"}, {"t": "予慎无罪。", "b": "《诗·小雅·巧言》"}, {"t": "入门主敬,升堂主慎。", "b": "《仪礼·聘礼记》"}, {"t": "此所以学者不可以不深思而慎取之也。", "b": "宋·王安石《游褒禅山记》"}, {"t": "忧懈怠则思慎始而敬终。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "审慎", "t": "周密而谨慎"}, {"w": "失慎", "t": "疏忽"}, {"w": "慎独", "t": "个人闲居独处时,也要小心谨慎,不可有越礼非分的念头"}, {"w": "慎刑", "t": "谨于用刑"}, {"w": "慎行", "t": "行为谨慎"}, {"w": "慎言慎行", "t": "言行都十分小心注意"}, {"w": "慎小事微", "t": "谨慎对待微小的事情"}, {"w": "慎缄", "t": "小心谨慎,不说或少说话"}, {"w": "慎小谨微", "t": "对细小的事也小心对待。"}]}, {"meaning": "警惕。", "cites": [{"t": "载舟覆舟,所宜深慎。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "慎微", "t": "警惕于事物细微之处。"}]}, {"meaning": "与“勿”、“毋”、“莫”等连用表示禁戒,相当于“务必”、“千万”等。", "cites": [{"t": "慎勿学哥舒。", "b": "杜甫《潼关吏》"}, {"t": "多谢后世人,戒之慎勿忘!", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "顺从,顺应;遵循,依顺。", "cites": [{"t": "本察仁义之本,天之意,不可不慎也。", "b": "《墨子·天志中》"}, {"t": "夫侵主而产怨,此失君之所慎也。", "b": "《管子·任法》"}, {"t": "主安近之,则慎比而不邪。", "b": "《荀子·仲尼》"}, {"t": "百官慎职,而莫敢愉綖。", "b": "《吕氏春秋·勿躬》"}, {"t": "不足,此皆所以慎产也。", "b": "《韩非子·外储说右上》"}, {"t": "媚兹一人,应侯慎德。", "b": "《淮南子·缪称》"}], "words": [{"w": "慎比", "t": "顺从亲近"}, {"w": "慎产", "t": "顺其求生的欲望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3024wx','誉','1','yù','言','13','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从言,舆(yù)声。本义:称赞,赞美)。"}, {"meaning": "同本义。", "cites": [{"t": "誉,偁也。", "b": "《说文》"}, {"t": "誉名美也。", "b": "《墨子经》"}, {"t": "状古述今曰誉。", "b": "《周书·谥法》"}, {"t": "君子不以口誉人。", "b": "《礼记·表记》"}, {"t": "佞誉诬谀。", "b": "唐·柳宗元《柳河东集》"}, {"t": "誉之则以为忧。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "誉人", "t": "称赞人"}, {"w": "誉谀", "t": "歌颂阿谀"}, {"w": "誉叹", "t": "赞叹。"}]}, {"meaning": "jǔ。推荐。", "cites": [{"t": "更相荐誉。", "b": "《汉书·贾捐之传》"}, {"t": "而列士不誉。", "b": "《汉书·匡衡传》"}, {"t": "先时荐誉。", "b": "《后汉书·宦者传论》"}]}, {"meaning": "荣誉,美名。", "cites": [{"t": "以永终誉。", "b": "《诗·周颂·振鹭》"}, {"t": "则燕则誉。", "b": "《礼记·射义》。注:“言国安则有名誉。”"}, {"t": "誉辅其赏,毁随其罚。", "b": "《韩非子》"}], "words": [{"w": "誉望", "t": "名望。"}]}, {"meaning": "yǔ。同类。", "cites": [{"t": "交众誉多。", "b": "《管子·明法》"}, {"t": "莫不亲誉。", "b": "《荀子·议兵》"}, {"t": "推类接誉。", "b": "《荀子·臣道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3025wx','塞','1','sāi sài sè','土','13','','[{"pinyin": "sāi", "defs": [{"meaning": "(会意兼形声。从土,塞(xià)声。塞同罅,空隙之义。本义:阻隔;堵住)。"}, {"meaning": "同本义。", "cites": [{"t": "塞,隔也。", "b": "《说文》"}, {"t": "四塞世告至。", "b": "《礼记·名堂位》。注:“四塞,谓夷服、镇服、蕃服在四方为蔽塞者。”"}, {"t": "塞向墐户。", "b": "《诗·豳风》"}, {"t": "从者塞途。", "b": "韩愈《送李愿归盘谷序》"}, {"t": "惩山北之塞,出入之迂也。", "b": "《列子·汤问》"}, {"t": "不宜妄自菲薄,引喻失义,以塞忠谏之路也。", "b": "诸葛亮《出师表》"}], "words": [{"w": "塞耳", "t": "堵住耳朵"}, {"w": "塞绝", "t": "堵塞断绝"}, {"w": "塞噎", "t": "阻塞,哽噎"}, {"w": "塞话", "t": "使人生气的话"}, {"w": "塞狗洞", "t": "把银钱花在无用的地方"}, {"w": "塞除", "t": "堵塞并消除"}, {"w": "塞井夷灶", "t": "填井平灶。谓作好布阵的准备。亦表示决心战斗,义无反顾"}, {"w": "塞井焚舍", "t": "填井烧屋,表示决心死战。"}]}, {"meaning": "填塞;充满。", "cites": [{"t": "志气塞乎天地。", "b": "《孔子·闲居》注:“满也。”"}, {"t": "五味芬芳,以塞其口。", "b": "《荀子·富国》。注:“犹充也。”"}, {"t": "汗牛塞屋,富贵家之书。", "b": "清·袁枚《黄生借书说》"}, {"t": "红女白婆,填塞门户。", "b": "《聊斋志异·促织》"}], "words": [{"w": "箱子不太满,再塞点东西;这房子里居然塞了八辆车", "t": ""}]}, {"meaning": "遏止,禁止。", "cites": [{"t": "善治者塞民以法。", "b": "《商君书·画策》"}], "words": [{"w": "塞默", "t": "犹沉默,不作声"}, {"w": "塞嘿", "t": "塞默。"}]}, {"meaning": "补救;抵偿。", "cites": [{"t": "将欲何施,以塞此名。", "b": "《汉书·于定国传》"}], "words": [{"w": "塞咎", "t": "抵补罪过。"}]}, {"meaning": "搪塞;应付。", "cites": [{"t": "备极护爱,留待限期,以塞官责。", "b": "《聊斋志异·促织》"}], "words": [{"w": "塞白", "t": "拼凑文字搪塞或应付考试。"}]}, {"meaning": "困窘,时运不通。", "cites": [{"t": "孰云时与命,通塞皆自由。", "b": "韩愈《驽骥》"}]}, {"meaning": "诚实。", "cites": [{"t": "仲氏任只,其心塞渊。", "b": "《诗·邶风·燕燕》"}]}]}, {"pinyin": "sài", "defs": [{"meaning": "险要之处;要塞,边塞。", "cites": [{"t": "完要塞。", "b": "《礼记·月令》。注:“边城要害处也。”"}, {"t": "而世主不敢交阳侯之塞。", "b": "《战国策·秦策》。注:“隘处也。”"}, {"t": "山有九塞。", "b": "《吕氏春秋·有始》"}, {"t": "益州险塞,沃野千里,天府之国,高祖因之以成帝业。", "b": "晋·陈寿《三国志·诸葛亮传》"}], "words": [{"w": "边塞", "t": "边疆地区的要塞"}, {"w": "塞守", "t": "占据边界险要处"}, {"w": "塞人", "t": "古代指塞外的游牧民族"}, {"w": "塞徼", "t": "边塞上的碉堡"}, {"w": "塞邦", "t": "塞外之国"}, {"w": "塞色", "t": "塞外的景象"}, {"w": "塞邑", "t": "形势险要的边境城邑"}, {"w": "塞角", "t": "塞外所吹的号角"}, {"w": "塞垣", "t": "本指汉代为抵御鲜卑所设的边塞,后亦指长城;边关城墙。"}]}, {"meaning": "边境。", "cites": [{"t": "筑明堂于塞外。", "b": "《汉书·邓通传》。注:“境外也。”"}, {"t": "塞下秋来风景异,衡阳雁去无留意。", "b": "宋·范仲淹《渔家傲》"}], "words": [{"w": "塞垣", "t": "边境地带"}, {"w": "塞曲", "t": "边远地区的乐曲"}, {"w": "塞氛", "t": "边境上的气氛。指敌方的威胁"}, {"w": "塞关", "t": "边境上的关隘。"}]}, {"meaning": "古代的一种赌博游戏。", "cites": [{"t": "问骰奚事,则博塞以游。", "b": "《庄子·骈拇》"}, {"t": "禁博塞。", "b": "《管子·四时》"}]}, {"meaning": "构筑要塞。", "cites": [{"t": "南朝违约塞雁门,增塘水,治城隍,籍民兵,此何意也?", "b": "宋·苏轼《富郑公神道碑》"}]}, {"meaning": "酬神。", "cites": [{"t": "举春祭,塞久祷。", "b": "《管子·禁藏》"}, {"t": "杀牛塞祷。", "b": "《韩非子·外储说右下》"}, {"t": "诏令太官给塞具。", "b": "《后汉书·曹节传》。李贤注:“塞,报祠也。字当为赛,通也。”"}, {"t": "冬塞祷词。", "b": "班固《汉书·郊祀志》"}], "words": [{"w": "塞具", "t": "祭祀用的器具。"}]}]}, {"pinyin": "sè", "defs": [{"meaning": "实,堵、填充空隙,用于书面词语中。", "cites": [{"t": "刚而塞。", "b": "《书·皋陶谟》"}, {"t": "仲氏任只,其心塞渊。", "b": "《诗·邶风·燕燕》。郑《笺》云:塞,充实也。《说文》:僿,实也。"}, {"t": "志气塞乎天地。", "b": "《礼记·孔子闲居》"}], "words": [{"w": "闭耳塞听;阻塞", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3026wx','寞','1','mò','宀','13','','[{"pinyin": "mò", "defs": [{"meaning": "寂静;无声响。", "cites": [{"t": "巡陆夷之曲衍兮,幽空虚以寂寞。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3027wx','窥','1','kuī','穴','13','','[{"pinyin": "kuī", "defs": [{"meaning": "(形声。从穴,规声。本义:从小孔或缝里看)。"}, {"meaning": "暗中察看。亦泛指观看。", "cites": [{"t": "窥,小视也。", "b": "《说文》"}, {"t": "钻穴隙相窥,逾墙相从。", "b": "《孟子·滕文公下》"}, {"t": "窥见室家之好。", "b": "《论语·子路》"}, {"t": "妻从门间而窥其夫。", "b": "《史记·管晏列传》"}, {"t": "蔽林间窥之。", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "窥觑", "t": "偷看"}, {"w": "窥瞰", "t": "窥探;暗中偷看"}, {"w": "窥欲", "t": "窥伺贪求。"}]}, {"meaning": "观察,侦探。", "cites": [{"t": "窥谷忘反。", "b": "吴均《与朱元思书》"}, {"t": "窥父不在。", "b": "《聊斋志异·促织》"}], "words": [{"w": "窥究", "t": "深究察觉"}, {"w": "窥圃", "t": "窥园。观赏园景"}, {"w": "窥深", "t": "观察深入细致"}, {"w": "窥睹", "t": "观看;观察"}, {"w": "窥览", "t": "阅览;观察。"}]}, {"meaning": "伺机图谋;觊觎。", "cites": [{"t": "禁人之窥伺者。", "b": "清·黄宗羲《原君》"}, {"t": "数通史相窥观。", "b": "《汉书·李广苏建传》"}, {"t": "以窥周室。", "b": "汉·贾谊《过秦论》"}, {"t": "自胡马窥汉去后。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "窥图", "t": "窥探谋算"}, {"w": "窥攻", "t": "伺机进攻"}, {"w": "窥取", "t": "伺机夺取"}, {"w": "窥朝", "t": "窥伺朝廷。"}]}, {"meaning": "观看。", "cites": [{"t": "朝服衣冠,窥镜。", "b": "《战国策·齐策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3028wx','窟','1','kū','穴','13','','[{"pinyin": "kū", "defs": [{"meaning": "(形声。从穴,屈声。本义:土穴)。"}, {"meaning": "同本义。", "cites": [{"t": "窟,兔崛也。", "b": "《说文》。字亦作窟。"}, {"t": "兔之所息谓之窟。", "b": "《小尔雅·广兽》"}, {"t": "兽穴曰窟。", "b": "《通俗文》。按,凡穴土皆曰堀。"}, {"t": "西厌月窟。", "b": "《汉书·扬雄传》"}, {"t": "昔者先王未有官室,冬则居营窟。", "b": "《礼记·礼运》"}], "words": [{"w": "窟弄", "t": "洞;孔"}, {"w": "窟窍", "t": "窟窿;洞"}, {"w": "窟窦", "t": "洞空貌"}, {"w": "窟宠", "t": "窟窿。"}]}, {"meaning": "洞穴。", "cites": [{"t": "狡兔有三窟。", "b": "《战国策·齐策四》"}]}, {"meaning": "又。", "cites": [{"t": "今君有一窟。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "请为君复凿二窟。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "三窟已就。", "b": ""}], "words": [{"w": "石窟;窟穴", "t": "洞穴"}, {"w": "窟窦", "t": "洞穴"}, {"w": "窟窖", "t": "地窖"}, {"w": ":窟居", "t": "谓以洞穴为住所"}, {"w": "窟穴", "t": "动物栖身的洞穴。"}]}, {"meaning": "穴居;作巢。", "cites": [{"t": "狐兔窟于殿傍。", "b": "晋·潘岳《西征赋》"}], "words": [{"w": "窟守", "t": "穴居不出"}, {"w": "窟岩", "t": "岩穴"}, {"w": "窟穴", "t": "做巢;盘踞"}, {"w": "窟宅", "t": "居住;盘踞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3029wx','寝','1','qǐn','宀','13','','[{"pinyin": "qǐn", "defs": [{"meaning": "(形声。从宀,侵声。本义:睡觉)。"}, {"meaning": "同本义。", "cites": [{"t": "寢,卧也。", "b": "《说文》"}, {"t": "寝毋伏。", "b": "《礼记·曲礼上》"}, {"t": "宰于昼寝。", "b": "《论语·公冶长》"}, {"t": "寡人夜者寝而不寐。", "b": "《公羊传·僖公二年》"}, {"t": "暮寝而思之。", "b": "《战国策·齐策》"}, {"t": "元济尚寝。", "b": "《资治通鉴·唐纪》"}, {"t": "寝必重褥。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "既同寝。", "b": "清·魏禧《大铁椎传》"}], "words": [{"w": "寝不成寐", "t": "睡不着。形容心事重"}, {"w": "寝不安席", "t": "睡觉不能安予枕席。形容心事重"}, {"w": "寝卧", "t": "睡眠息止"}, {"w": "寝床", "t": "睡觉用的床"}, {"w": "寝息", "t": "睡卧休息"}, {"w": "寝衾", "t": "泛指睡眠所用之衣物"}, {"w": "寝宿", "t": "睡卧宿息"}, {"w": "寝饭", "t": "睡觉和吃饭"}, {"w": "寝兴", "t": "睡下和起床"}, {"w": "寝膳", "t": "寝食"}, {"w": "寝燕", "t": "亦作“寝宴”。睡卧与休息。"}]}, {"meaning": "卧。", "cites": [{"t": "成子高寝疾,庆遗于请曰:“子之病革矣。”", "b": "《礼记·檀弓》"}], "words": [{"w": "寝石", "t": "卧石,横躺着的石头"}, {"w": "寝伏", "t": "卧伏"}, {"w": "寝兕", "t": "卧着的独角犀。常画于帝王车轮上以壮威"}, {"w": "寝病", "t": "卧病"}, {"w": "寝疾", "t": "卧病"}, {"w": "寝床", "t": "躺卧在床上。"}]}, {"meaning": "寝室、卧室。", "cites": [{"t": "无东西厢有室曰寝。", "b": "《尔雅·释宫》"}, {"t": "然后适小寝。", "b": "《礼记·玉藻》"}], "words": [{"w": "寝户", "t": "寝门。内室的门"}, {"w": "寝所", "t": "犹寝室,住所"}, {"w": "寝幄", "t": "卧室内的帷帐"}, {"w": "寝殿", "t": "帝王的寝宫,卧室"}, {"w": "寝斋;寝庐", "t": "住房。"}]}, {"meaning": "君王的宫室。", "cites": [{"t": "宫人掌王之六寝之修。", "b": "《周礼·官人》"}]}, {"meaning": "宗庙中藏祖先衣冠的后殿。", "cites": [{"t": "寝成孔安。", "b": "《诗·商颂·殷武》"}]}, {"meaning": "帝王陵园中的正殿。", "cites": [{"t": "执爵于太寝。", "b": "《礼记·月令》"}], "words": [{"w": "寝阙", "t": "陵墓"}, {"w": "寝殿", "t": "陵墓的正殿"}, {"w": "寝堂", "t": "帝王陵墓的正殿"}, {"w": "寝陵", "t": "帝王的陵墓。"}]}, {"meaning": "丑陋。", "cites": [{"t": "不以鄙陋寝容。", "b": "《吴越春秋·勾践阴谋外传》"}, {"t": "貌寝陋,不能远视。", "b": "《新唐书·郑注传》"}, {"t": "貌甚寝。", "b": "清·魏禧《大铁椎传》"}, {"t": "武安者,貌寝。", "b": "《史记·魏其安侯传》。韦昭曰:“短小也,丑恶也。”"}], "words": [{"w": "寝小", "t": "丑陋矮小"}, {"w": "寝陋", "t": " 容貌丑陋"}, {"w": "寝侻;寝容", "t": "容貌丑陋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3030wx','谨','1','jǐn','讠','13','','[{"pinyin": "jǐn", "defs": [{"meaning": "(形声。从言,堇(qín)声。本义:谨慎,小心)。"}, {"meaning": "同本义。", "cites": [{"t": "谨,慎也。", "b": "《说文》"}, {"t": "以谨无良。", "b": "《诗·大雅·民劳》"}, {"t": "以谨罔极。", "b": ""}, {"t": "谨畜藏。", "b": "《荀子·王制》"}, {"t": "谨厚以为厚。", "b": "《楚辞·怀沙》"}, {"t": "谨庠序之教。", "b": "《孟子·梁惠王上》"}, {"t": "谨食之。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "不自谨惜。", "b": "清·张廷玉《明史》"}, {"t": "谨护其失。", "b": "清·刘开《问说》"}], "words": [{"w": "谨畏", "t": "小心谨慎"}, {"w": "谨肃", "t": "严谨认真"}, {"w": "谨言", "t": "谨慎说话"}, {"w": "谨厚", "t": "谨慎忠厚"}, {"w": "谨介", "t": "谨慎耿介。"}]}, {"meaning": "恭敬。", "cites": [{"t": "谨斩樊於期头。", "b": "《战国策·燕策》"}, {"t": "谨使臣良。", "b": "《史记·项羽本纪》"}, {"t": "谨诺。", "b": ""}, {"t": "谨奉神稷而以从。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "谨呈", "t": "敬呈"}, {"w": "谨启;谨致谢意;谨祈;谨恪", "t": "谨谨恭敬"}, {"w": "谨白", "t": "敬告,敬启"}, {"w": "谨禀", "t": "禀告"}, {"w": "谨媚", "t": "恭顺柔媚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3031wx','褂','1','guà','衤','13','','[{"pinyin": "guà", "defs": [{"meaning": "中式的单上衣。"}, {"meaning": "古时军装的一种,有罩甲的短袖戎衣。"}, {"meaning": "清代礼服外服的名称。礼服加于袍外称外褂,短的称马褂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3032wx','裸','1','luǒ','衤','13','','[{"pinyin": "luǒ", "defs": [{"meaning": "(形声。从衣,果声。本义:赤身露体)。"}, {"meaning": "同本义。", "cites": [{"t": "臝,袒也。", "b": "《广雅》"}, {"t": "赵简子梦童子裸而转以歌。", "b": "《左传·昭公三十一年》"}, {"t": "其动物宜臝物。", "b": "《周礼·大司徒》"}, {"t": "平怒,乃解衣裸而佐刺船。", "b": "《史记·陈丞相世家》"}, {"t": "其西瓯骆裸国亦称王。", "b": "《史记·南越列传》。索隐:“裸,露形也。”"}, {"t": "或白昼使臝伏。", "b": "《汉书·高五王传》。师古曰:“臝者,露形体也。”"}, {"t": "辄立臝立击鼓。", "b": "《汉书·江都易王非传》"}, {"t": "臝诊其尸。", "b": "《汉书·董贤传》"}], "words": [{"w": "裸衣", "t": "脱衣露体"}, {"w": "裸行", "t": "赤身露体行走"}, {"w": "裸戏", "t": "裸身作戏"}, {"w": "裸形", "t": "裸体"}, {"w": "裸国", "t": "古国名。属不穿衣服的热带民族"}, {"w": "裸尸", "t": "使尸骨暴露于野外"}, {"w": "裸袒", "t": "赤身裸体。"}]}, {"meaning": "露出的身体。", "cites": [{"t": "曹共公闻其骈胁,欲观其裸。", "b": "《左传·僖公二十三年》"}]}, {"meaning": "动植物外面没有毛、羽、鳞、甲或其它东西包裹的。", "cites": [{"t": "地为大矣,而水泉草木毛羽裸鳞未尝息也。", "b": "《吕氏春秋·观表》"}], "words": [{"w": "裸芽", "t": "植物学名词。无鳞叶保护的芽称为裸芽"}, {"w": "裸虫", "t": "指没有羽、毛、鳞、甲的动物。包括有人类、蚯蚓等。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3033wx','福','1','fú','礻','13','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从示,“畐”声。声符亦兼表字义。“畐”,本象形,是“腹”字的初文,上象人首,“田”象腹部之形。腹中的“十”符,表示充满之义,则“畐”有腹满义。“福”“富”互训,以明家富则有福。本义:福气,福运。与“祸”相对)。"}, {"meaning": "古称富贵寿考等齐备为福。与“祸”相对。", "cites": [{"t": "福,祐也。", "b": "《说文》。按,本作祜也。"}, {"t": "安利之谓福。", "b": "贾谊《道德说》"}, {"t": "师其类者谓之福。", "b": "《荀子·天论》"}, {"t": "福者,备也。备者,百顺之名也。", "b": "《礼记·祭统》"}, {"t": "受茲介福。", "b": "《易·晋》"}, {"t": "万福来求。", "b": "《诗·小雅·桑扈》"}, {"t": "降福既多。", "b": "《诗·鲁颂·閟宫》"}, {"t": "全寿富贵之谓福。", "b": "《韩非子·解老》"}, {"t": "祸兮福所倚,福兮祸所伏。", "b": "《老子》"}], "words": [{"w": "福泽", "t": "福分;福气"}, {"w": "福无双降,祸不单行", "t": "好事不多,祸事不少。特指接连遇到不幸"}, {"w": "福缘", "t": "福气"}, {"w": "福寿", "t": "幸福长寿。"}]}, {"meaning": "祭祀用的酒肉。", "cites": [{"t": "为人祭曰致福。", "b": "《礼记·少仪》"}, {"t": "凡祭祀之致福者。", "b": "《周礼·膳夫》。注:“谓诸臣祭祀。进其余肉,归祚于王。”"}], "words": [{"w": "福礼", "t": "祭祀用的供品"}, {"w": "福酒", "t": "祭过神明的酒"}, {"w": "福食", "t": "供祀神用的食物"}, {"w": "福脯", "t": "祭祀用的干肉。"}]}, {"meaning": "赐福,保佑。", "cites": [{"t": "亦其福女。", "b": "《诗·鲁颂·閟宫》"}, {"t": "小信未孚,神弗福也。", "b": "《左传·庄公十年》"}], "words": [{"w": "福田", "t": "佛教认为积善可得福报,犹如种田就会有收获一样"}, {"w": "福柄", "t": "指作威作福的权力"}, {"w": "福神", "t": "能赐人幸福的神灵"}, {"w": "福善祸淫", "t": "赐福给为善的人,降祸给作恶的人。"}]}, {"meaning": "亦作“拂”。行礼。上身稍微前倾,双手重叠在偏右方向上下移动。", "cites": [{"t": "刘姥姥便知是贾母了,忙上来陪着笑,福了几福。", "b": "《红楼梦》"}]}, {"meaning": "(fù)。相称,符合。", "cites": [{"t": "邦福重宝,闻于傍乡。", "b": "《史记·龟策列传》"}, {"t": "仰福帝居,阳曜阴藏。", "b": "张衡《西京赋》"}], "words": [{"w": "福德", "t": "符合道德准则"}, {"w": "福望", "t": "符合众人的愿望。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3034wx','谬','1','miù','讠','13','','[{"pinyin": "miù", "defs": [{"meaning": "(形声。本义:极端错误,非常不合情理)。"}, {"meaning": "同本义。", "cites": [{"t": "谬,狂者之妄言也。", "b": "《说文》"}, {"t": "考之三王而不谬。", "b": "礼记·中庸》"}, {"t": "天下悦之以谬悠之说。", "b": "《庄子》"}, {"t": "解心之谬。", "b": "《庄子·庚桑楚》"}, {"t": "故《易》曰:“差以毫厘,谬以千里。”", "b": "《汉书·司马迁传》"}, {"t": "园喜以谬赏。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "故闻之而不见,虽博必谬。", "b": "《荀子·儒效》"}, {"t": "今言“华”如“华实”之“华”者,盖音谬也。", "b": "王安石《游褒禅山记》"}], "words": [{"w": "谬戾", "t": "荒谬乖僻"}, {"w": "谬谈", "t": "谬语妄说"}, {"w": "谬举", "t": "妄举,举用不适当的人才"}, {"w": "谬种流传", "t": "荒谬错误的文章或议论辗转流传于世。"}]}, {"meaning": "欺诈;迷误。", "cites": [{"t": "谬,欺也。", "b": "《广雅》"}, {"t": "后世之谬其传而莫能名者,何可胜道也哉!", "b": "王安石《游褒神山记》"}, {"t": "秦言不听,谬言:…", "b": "《燕丹子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3035wx','群','1','qún','羊','13','','[{"pinyin": "qún", "defs": [{"meaning": "(形声。从羊,君声。本义:羊群;兽群;人群)。"}, {"meaning": "三个以上的禽兽相聚而成的集体。", "cites": [{"t": "群,辈也。", "b": "《说文》"}, {"t": "兽三为群。", "b": "《国语·周语》"}, {"t": "或群或友。", "b": "《诗·小雅·吉日》"}, {"t": "三百维群。", "b": "《诗·小雅·无羊》"}, {"t": "大夫不掩群。", "b": "《礼记·曲礼》"}, {"t": "群疑满服,众难塞胸。", "b": "诸葛亮《后出师表》"}, {"t": "故近者聚而为群。", "b": "柳宗元《封建论》"}]}, {"meaning": "集团,社会集体。", "cites": [{"t": "又有大者,众群之长又就而听命焉,以安其属。", "b": "唐·柳宗元《封建论》"}], "words": [{"w": "群法", "t": "社会法则"}, {"w": "群治", "t": "对各种社会问题的治理和处置"}, {"w": "群俗", "t": "社会风尚。"}]}, {"meaning": "泛指多数。"}, {"meaning": "指人。", "cites": [{"t": "王为群姓立社,曰大社。", "b": "《礼记》"}]}, {"meaning": "指事物。", "cites": [{"t": "猎者张罗,百兽群拢,或得或失。", "b": "《论衡》"}]}, {"meaning": "聚集;会合,联合。", "cites": [{"t": "而群天下之英杰。", "b": "《荀子·非十二子》"}, {"t": "君子矜而不争,群而不党。", "b": "《论语》"}, {"t": "以避群害。", "b": "明·李渔《闲清偶寄·种植部》"}, {"t": "群聚而笑。", "b": "唐·韩愈《师说》"}, {"t": "群怪聚骂。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "群而不党", "t": "聚集在一起,却不结党"}, {"w": "群曲", "t": "合唱的曲子。大多为一人引端,众人和声"}, {"w": "群行", "t": "结队而行"}, {"w": "群萃", "t": "事业相同的人集聚在一起"}, {"w": "群处", "t": "成群地相处。"}]}, {"meaning": "随俗。", "cites": [{"t": "仆进不能参名于二立,退又不能群彼数子。", "b": "《后汉书》"}]}, {"meaning": "众多。", "cites": [{"t": "愠于群小。", "b": "《诗·邶风·柏舟》"}, {"t": "赵王悉召群臣。", "b": "《史记·廉颇蔺相列传》"}, {"t": "群从所得。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "群响毕绝。", "b": "《虞初新志·秋声诗自序》"}, {"t": "以孤羊投群狼。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "群士", "t": "众官,百官;众学士"}, {"w": "群有", "t": "指万物"}, {"w": "群司", "t": "百官,众官。同群士"}, {"w": "群枉", "t": "众多奸邪的小人"}, {"w": "群英", "t": "众多有才能的人"}, {"w": "群从", "t": "指众子侄辈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3036wx','殿','1','diàn','殳','13','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。本义:击声)。"}, {"meaning": "古代泛指高大的房屋,后专指供奉神佛或帝王受朝理事的大厅。", "cites": [{"t": "殿,堂之高大者也。", "b": "《说文古本考》"}, {"t": "苍鹰搏击于殿上。", "b": "《战国策·魏策》"}, {"t": "王子皇孙,辞楼下殿。", "b": "杜牧《阿房宫赋》"}, {"t": "中绘殿阁,类兰若(佛寺)。", "b": "《聊斋志异》"}, {"t": "有举孝子者先上殿。", "b": "《汉书·黄霸传》"}, {"t": "浮屠北有佛殿一所。", "b": "《洛阳伽蓝记·永宁寺》"}], "words": [{"w": "宫殿", "t": "泛指帝王居住的高大华丽的房屋"}, {"w": "殿陛", "t": "帝王宫殿的台阶。借指朝廷"}, {"w": "殿直", "t": "在宫殿中值勤的人"}, {"w": "殿使", "t": "皇帝派遣的使臣"}, {"w": "殿脚人", "t": "即“殿脚女”。相传隋炀帝巡游江都时,乘龙舟,选美女一千人牵彩缆挽龙舟,号为“殿脚女”"}, {"w": "殿兵", "t": "后军。"}]}, {"meaning": "最后,最下。", "cites": [{"t": "殿,后也。", "b": "《广雅》"}, {"t": "奔而殿。", "b": "《论语·雍也》。集解引马注:“殿在军后。前曰启,后曰殿。”"}, {"t": "大殿。", "b": "《左传·襄公二十三年》。注:“殿,后军也。”"}], "words": [{"w": "殿最", "t": "古代考核政绩或军功的差等,下等称为“殿”,上等称为“最”。"}]}, {"meaning": "镇抚,镇守。", "cites": [{"t": "殿天子之邦。", "b": "《诗·小雅·采菽》"}], "words": [{"w": "殿邦", "t": "安邦定国。"}]}, {"meaning": "定,评定。", "cites": [{"t": "莅之者进不能课其能,退不能殿其不能,才不才一也。", "b": "唐·白居易《江州司马厅记》"}]}, {"meaning": "殿后,压阵。", "cites": [{"t": "孟之反不伐,奔而殿。", "b": "《论语·雍也》"}, {"t": "命李进诚将三千人殿其后。", "b": "《资治通鉴·唐宪宗元和十二年》"}]}, {"meaning": "停,停止。", "cites": [{"t": "依十二章不枉法例决五十七下,罪经释免,须殿三年,殿期已满。", "b": "《元典章新集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3037wx','辟','1','bì pì','辛','13','','[{"pinyin": "bì", "defs": [{"meaning": "(会意。小篆字形,从卩,从辛,从口。“卩”,音jié,甲骨文象人曲膝而跪的样子。“辛”,甲骨文象古代酷刑用的一种刀具。本义:法律,法度)。"}, {"meaning": "同本义。", "cites": [{"t": "辟,法也。从卩、从辛,节制其罪也。从口,用法者也。", "b": "《说文》"}, {"t": "“辟言不信”。(法度之言,而不听信。)", "b": "《诗·小雅·雨无止》"}]}, {"meaning": "君主。", "cites": [{"t": "辟遏有德。", "b": "《汉书·五行志》。注:“天子也。”"}, {"t": "皇王(指周武王)维(语气词)辟。", "b": "《诗经·大雅·文王有责》"}], "words": [{"w": "复辟", "t": ""}]}, {"meaning": "古称官吏。", "cites": [{"t": "厥辟不辟。", "b": "《礼记·坊记》"}, {"t": "三卿一长曰辟。", "b": "《周书·武顺》"}, {"t": "正殿路寝,用朝群辟。", "b": "《文选》"}]}, {"meaning": "罪,罪行。", "cites": [{"t": "言奇者见疑,行殊者得辟。", "b": "《汉书》"}]}, {"meaning": "回避,躲避。", "cites": [{"t": "使咸知王之好恶辟行之。", "b": "《周礼·掌交》"}, {"t": "秦子梁子以公旗辟于下道,是以皆止。", "b": "《左传·庄公九年》"}, {"t": "子曰:贤者辟世,其次辟地,其次辟色,其次辟言。", "b": "《论语·宪问》"}, {"t": "行辟人可也。", "b": "《孟子》"}, {"t": "不辟死伤。", "b": "《荀子·荣辱》"}, {"t": "文王之所辟(后作“避”)风雨也。", "b": "《左传·僖公三十三年》"}, {"t": "高祖尝(曾经)辟吏。", "b": "《史记·张丞相列传》"}], "words": [{"w": "辟邪", "t": "避免或驱除邪恶。"}]}, {"meaning": "征召来授予官职。", "cites": [{"t": "举孝廉,不行,连辟公府,不就。", "b": "《后汉书·张衡传》"}]}]}, {"pinyin": "pì", "defs": [{"meaning": "(形声。从门,辟声。本义:打开,开启)。"}, {"meaning": "同本义。", "cites": [{"t": "辟,开也。", "b": "《说文》"}, {"t": "辟四门。", "b": "《虞书》"}, {"t": "辟户为之乾。", "b": "《易·系辞传》"}, {"t": "唇吻翕辟。", "b": "《聊斋志异·促织》"}, {"t": "语毕而宫门辟。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "辟阖", "t": "开合"}, {"w": "辟翕", "t": "开合"}, {"w": "辟门", "t": "开门。后比喻广开贤路,访求人才"}, {"w": "辟面", "t": "辟头。开头,起首"}, {"w": "辟道", "t": "开道"}]}, {"meaning": "开辟;开拓。", "cites": [{"t": "欲辟土地。", "b": "《孟子·梁惠王上》"}, {"t": "周宣王辟国千里,非贪侵也。", "b": "《盐铁论·地广》"}, {"t": "辟病梅之馆以贮之。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "辟地", "t": "开辟疆域"}, {"w": "辟土", "t": "开拓疆域。"}]}, {"meaning": "驳斥。", "cites": [{"t": "辟邪说,难壬人,不为拒谏。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "辟谣;辟佛", "t": "反佛教,驳斥佛理"}, {"w": "辟驳", "t": "驳斥。"}]}, {"meaning": "开垦。", "cites": [{"t": "农辟地。", "b": "《商君书·弱民》"}, {"t": "隙地未尽辟。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "辟田", "t": "开垦田地。同辟土"}, {"w": "辟治", "t": "开发治理"}, {"w": "辟除", "t": "开垦。"}]}, {"meaning": "屏除;驱除。", "cites": [{"t": "举公义,辟私怨。", "b": "《墨子·尚贤上》"}, {"t": "苟无恒心,放辟邪侈,无为为己。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "辟邪", "t": "屏除邪恶。"}]}, {"meaning": "开阔;宽广。", "cites": [{"t": "不若从炉塘道,稍迂而路辟。", "b": "《徐霞客游记》"}]}, {"meaning": "偏僻。", "cites": [{"t": "秦国辟远。", "b": "《史记·范雎传》"}]}, {"meaning": "邪僻。", "cites": [{"t": "境内之民无辟滛之心。", "b": "《商君书·弱民》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3038wx','障','1','zhàng','阝','13','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从阜,章声。阜,土山。从阜,与高下、险阻有关。本义:阻塞,阻隔)。"}, {"meaning": "同本义。", "cites": [{"t": "障,隔也。", "b": "《说文》"}, {"t": "蕃隔曰障。", "b": "《通俗文》"}, {"t": "陂障九泽。", "b": "《国语·周语》"}, {"t": "障大泽。", "b": "《左传·昭公元年》。服注:“陂障其水也。”"}, {"t": "欲闻枉而恶直言,是障其源而欲其水也。", "b": "《吕氏春秋》"}], "words": [{"w": "障翼", "t": "遮挡掩护"}, {"w": "障距", "t": "阻隔,壅蔽"}, {"w": "障塞", "t": "阻塞不通"}, {"w": "障隔", "t": "阻隔。"}]}, {"meaning": "阻挡;拒绝。", "cites": [{"t": "令而不行,谓之障。", "b": "《管子》"}], "words": [{"w": "障海", "t": "阻挡水流入海"}, {"w": "障壅", "t": "阻挡"}, {"w": "障遏", "t": "阻挡,阻止"}, {"w": "障害", "t": "阻碍,妨碍"}, {"w": "障故", "t": "障碍变故。"}]}, {"meaning": "遮挡;遮蔽。", "cites": [{"t": "而障之以手。", "b": "《淮南子·精神》。注:“蔽也。”"}, {"t": "司徒褚渊入朝,以腰扇障日,祥从侧过,曰:“作如此举止,羞面见人,扇障何益?”", "b": "《南齐书·刘祥传》"}, {"t": "障隙处。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "障日", "t": "遮蔽太阳"}, {"w": "障覆", "t": "遮蔽覆盖"}, {"w": "障蔽", "t": "遮蔽;遮盖"}, {"w": "障袂", "t": "扬袖遮日"}, {"w": "障庇", "t": "遮蔽庇护"}, {"w": "障袖", "t": "以袖遮面。"}]}, {"meaning": "佛教用语。烦恼。", "cites": [{"t": "能碍圣道,说以为障。", "b": "《大乘义章》"}], "words": [{"w": "障恼", "t": "烦恼"}, {"w": "障难", "t": "烦恼苦难"}, {"w": "障盖", "t": "烦恼。"}]}, {"meaning": "古时边塞上险要处用以防捍寇盗而另筑的小城。", "cites": [{"t": "障,小城也。", "b": "《苍颉篇》"}, {"t": "为置吏筑障。", "b": "《汉书·朝鲜王满传》"}, {"t": "居一障间。", "b": "《史记·酷吏传》。正义:“谓塞上要险之处。”"}, {"t": "逾岷越障。", "b": "祢衡《鹦鹉赋》"}, {"t": "登障隧而遥望兮,聊须臾以婆娑。", "b": "班彪《北征赋》"}], "words": [{"w": "障隧", "t": "边塞上的烽火台"}, {"w": "障堡", "t": "边塞险要处的城堡。"}]}, {"meaning": "步障,布帷或屏风。", "cites": [{"t": "梨花园中册作妃,金鸡障下养为儿。", "b": "唐·白居易《胡旋女》"}], "words": [{"w": "障幕", "t": "帷幕。"}]}, {"meaning": "幛子 ,上面题有文字或画有图画的整幅绸布。", "cites": [{"t": "出地标图,临流写障。", "b": "唐·李庾《东都赋》"}, {"t": "手提新画青松障。", "b": "杜甫《题李尊师松树障子歌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3039wx','媳','1','xí','女','13','','[{"pinyin": "xí", "defs": [{"meaning": "儿子的配偶", "words": [{"w": "贤媳", "t": "解释"}, {"w": "童养媳", "t": "解释"}, {"w": "令媳", "t": "尊称别人的儿媳"}, {"w": "小媳", "t": "谦称自己的儿媳"}]}, {"meaning": "弟弟及晚辈亲属之妻", "words": [{"w": "孙媳", "t": ""}, {"w": "弟媳", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3040wx','嫉','1','jí','女','13','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从女,疾声。本义:忌妒才德地位等美好的人)。"}, {"meaning": "同本义。泛指忌妒。", "cites": [{"t": "嫉,妒也。", "b": "《广雅》"}, {"t": "各兴心而嫉妒。", "b": "《楚辞·离骚》"}, {"t": "世溷浊而嫉贤兮,好蔽美而称恶。", "b": ""}, {"t": "众女嫉予之娥眉兮,谣诼谓余以善淫。", "b": ""}], "words": [{"w": "嫉诬", "t": "因嫉妒而诬告"}, {"w": "嫉病", "t": "忌妒指责"}, {"w": "嫉心", "t": "嫉妒之心"}, {"w": "嫉毁", "t": "嫉妒毁谤。"}]}, {"meaning": "憎恨。", "cites": [{"t": "荀卿嫉浊世之政。", "b": "《史记·荀卿列传》"}, {"t": "屈平既嫉之。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "嫉恶", "t": "憎恨邪恶的人。也作疾恶"}, {"w": "嫉邪", "t": "憎恨邪恶"}, {"w": "嫉俗", "t": "憎恨不良的社会习俗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3041wx','嫌','1','xián','女','13','','[{"pinyin": "xián", "defs": [{"meaning": "(形声。从女,兼声。本义:疑惑,怀疑而有可能性)。"}, {"meaning": "同本义。", "cites": [{"t": "嫌,一曰疑也。", "b": "《说文》"}, {"t": "礼者,所以定亲疏,决嫌疑也。", "b": "《礼记·曲礼上》"}, {"t": "使民无嫌。", "b": "《礼记·坊记》"}, {"t": "岂敢有嫌哉?", "b": "《吴越春秋》"}, {"t": "同居长千里,两小无嫌猜。", "b": "李白《长干行》"}, {"t": "卿决疑讼,狱定嫌罪。", "b": "《论衡·案书》"}], "words": [{"w": "嫌间", "t": "因彼此猜疑而产生恶感"}, {"w": "嫌微", "t": "犹嫌疑。"}]}, {"meaning": "避忌。", "cites": [{"t": "贵贱不嫌同号,美恶不嫌同辞。", "b": "《公羊传》"}], "words": [{"w": "嫌难", "t": "因有避忌而为难。"}]}, {"meaning": "厌恶。", "cites": [{"t": "大人故嫌迟。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "嫌择", "t": "嫌弃;不满意"}, {"w": "嫌好道歉", "t": "挑剔;苛求"}, {"w": "嫌贫爱富", "t": ""}]}, {"meaning": "嫌隙,仇怨。", "cites": [{"t": "累百年之欲,易一时之嫌。", "b": "《荀子》"}, {"t": "丈夫以气相许,小嫌不足置胸中。", "b": "《新唐书·尉迟敬德传》"}], "words": [{"w": "使民无嫌;为了避嫌;涉嫌;前嫌尽释", "t": ""}]}, {"meaning": "怨恨。", "cites": [{"t": "若远小嫌,难相违覆。", "b": "《三国志》"}], "words": [{"w": "嫌恨", "t": "怨恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3042wx','嫁','1','jià','女','13','','[{"pinyin": "jià", "defs": [{"meaning": "(形声。从女,家声。本义:女子出嫁)。"}, {"meaning": "同本义(跟“娶”相对)。", "cites": [{"t": "嫁,女适人也。", "b": "《说文》"}, {"t": "归妹。", "b": "《易·序卦》。虞注:“嫁,归也。”"}, {"t": "子嫁反。", "b": "《仪礼·丧服》。虞注:“凡女行于大夫以上曰嫁,行于士庶曰适人。”"}, {"t": "自彼殷商,来嫁于周。", "b": "《诗·大雅·大明》"}, {"t": "共粉饰之,如嫁女床席。", "b": "《史记·滑稽列传》"}], "words": [{"w": "嫁杏", "t": "比喻婚期"}, {"w": "嫁子", "t": "嫁出的女儿;孪生的女儿"}, {"w": "嫁娶", "t": "嫁女与娶妇"}, {"w": "嫁殇", "t": "男子未满十九岁而死,死后女子才嫁之为妻。"}]}, {"meaning": "往,赴。", "cites": [{"t": "列子居郑圃四十年,人无识者,将嫁于卫。", "b": "《列子·天瑞》"}], "words": [{"w": "嫁怨", "t": "转怨于他人"}, {"w": "嫁祸", "t": "将灾祸转移给他人"}, {"w": "嫁罪", "t": "转移罪责"}, {"w": "嫁名", "t": "假借名义"}, {"w": "嫁非", "t": "委过。"}]}, {"meaning": "卖;售。", "cites": [{"t": "以嫁之齐也。", "b": "《战国策·西周策》"}, {"t": "天饥岁荒,嫁妻卖子者,必是家也。", "b": "《韩非子·六反》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3043wx','叠','1','dié','又','13','','[{"pinyin": "dié", "defs": [{"meaning": "(会意。金文字形,象物体叠放在“俎”上。本义:重叠)。"}, {"meaning": "同本义。", "cites": [{"t": "曡,重也,积也。", "b": "《苍颉篇》"}, {"t": "阳始出奥舒、曡。", "b": "《书·太元乐》。注:“积也。”"}, {"t": "虽累叶百叠,而富强相继。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "叠石为山;叠暴", "t": "显露;指人激动时青筋鼓出来"}, {"w": "叠字", "t": "单字的重叠"}, {"w": "叠雪", "t": "重叠飞扬的雪花。"}]}, {"meaning": "振作。", "cites": [{"t": "只好叠着精神,稳着步儿,探着腰儿,挺着胸儿…望前而行。", "b": "《镜花缘》"}]}, {"meaning": "惧怕。", "cites": [{"t": "莫不震叠。", "b": "《诗·周颂·时迈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3044wx','缚','1','fù','纟','13','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝或缠织等有关。尃(fū)声。本义:捆绑)。"}, {"meaning": "同本义。", "cites": [{"t": "缚,束也。", "b": "《说文》"}, {"t": "战之明日,晋襄公缚秦囚。", "b": "《左传·文公二年》"}, {"t": "主缚者亦然,不如所欲,缚时即先折筋骨。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "缚人", "t": "捆绑人"}, {"w": "缚绑", "t": "捆绑"}, {"w": "缚住", "t": "捆住"}, {"w": "缚虎", "t": "捆住猛虎。比喻征服极难征服之人"}, {"w": "缚送", "t": "捆住押送"}, {"w": "缚扎", "t": "捆扎。"}]}, {"meaning": "绳索。", "cites": [{"t": "夜半,童自转,以缚即炉火烧绝之。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "释缚", "t": "解缚。解绳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3045wx','缝','1','féng fèng','纟','13','','[{"pinyin": "féng", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝等有关, 逢声。本义:以针线连缀)。"}, {"meaning": "同本义。", "cites": [{"t": "缝,以针紩衣也。", "b": "《说文》"}, {"t": "缝,合也。", "b": "《广雅》"}, {"t": "缝齐倍要。", "b": "《礼记·玉藻》。注:“紩也。”"}, {"t": "可以缝裳。", "b": "《诗·魏风·葛屦》"}, {"t": "临行密密缝。", "b": "孟郊《游子吟》"}], "words": [{"w": "缝衣", "t": "缝制衣服"}, {"w": "缝刺", "t": "缝纫与刺绣"}, {"w": "缝缉", "t": "缝纫"}, {"w": "缝织", "t": "缝纫编织。"}]}]}, {"pinyin": "fèng", "defs": [{"meaning": "缝合处。", "cites": [{"t": "古者冠缩缝,今也衡缝。", "b": "《礼记·檀弓》"}], "words": [{"w": "衣缝;裤缝;缝际", "t": "缝合之处。"}]}, {"meaning": "罅隙。", "cites": [{"t": "瓦缝参差,多于周身之帛缕。", "b": "杜牧《阿房宫赋》"}], "words": [{"w": "缝罅", "t": "细小的裂痕,破绽"}, {"w": "缝子", "t": "缝隙"}, {"w": "缝开", "t": "裂开。"}]}, {"meaning": "喻言行中出现的漏洞、差错。", "cites": [{"t": "他就寻个缝子,参了一本。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3046wx','缠','1','chán','纟','13','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从糸,廛(chán)声。本义:围绕,缠绕)。"}, {"meaning": "同本义。", "cites": [{"t": "缠,绕也。", "b": "《说文》"}, {"t": "臣有所与供儋缠采薪者九方鄄。", "b": "《淮南子·道应》"}, {"t": "动胃缠缘。", "b": "《史记·扁仓传》。正义:“谓脉缰绕胃也。”"}, {"t": "野田生葡萄,缠绕一支蒿。", "b": "刘禹锡《葡萄歌》"}], "words": [{"w": "缠裹", "t": "缠绕裹束;衣著,装束。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3047wx','缤','1','bīn','纟','13','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从糸(mì),宾声。本义:繁盛,众多)。"}, {"meaning": "同本义。", "cites": [{"t": "芳草鲜美,落英缤纷。", "b": "晋·陶渊明《桃花源记》"}], "words": [{"w": "缤翻", "t": "繁盛的样子。"}]}, {"meaning": "紊乱。", "cites": [{"t": "时缤纷其变易兮。", "b": "《楚辞·屈原·离骚》"}], "words": [{"w": "缤乱", "t": "杂乱"}, {"w": "缤纷", "t": "纷乱的样子;纷飞的样子"}, {"w": "缤缤", "t": "飞的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3048wx','剿','1','chāo jiǎo','刂','13','','[{"pinyin": "chāo", "defs": [{"meaning": "抄袭。", "cites": [{"t": "毋剿说,毋雷同。", "b": "《礼记·曲礼上》"}], "words": [{"w": "剿拾", "t": "袭取"}, {"w": "剿袭", "t": "剽窃人言以为己说。"}]}]}, {"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从刀,巢声。本义:劳累,使辛勤劳累)。"}, {"meaning": "同本义。", "cites": [{"t": "勦,劳也。从力,巢声。", "b": "《说文》"}, {"t": "安用速成其以勦民也。", "b": "《左传·昭公元年》"}, {"t": "今公子苟好勦民以偷乐。", "b": "张衡《东京赋》"}, {"t": "无及于郑而剿民,将焉用之?", "b": "《左传·宣公十二年》"}]}, {"meaning": "灭绝,征剿。", "cites": [{"t": "无用勦绝其命。", "b": "《书·甘誓》"}, {"t": "断勦奸回之偪。", "b": "《后汉书·何敞传》"}, {"t": "剿凶虐兮截海外。", "b": "班固《封燕然山铭》"}], "words": [{"w": "围剿;剿绝", "t": "杀灭;灭绝"}, {"w": "剿洗", "t": "剿灭净尽"}, {"w": "剿杀", "t": "犹剿戮"}, {"w": "剿戮", "t": "戮灭;杀戮"}, {"w": "剿断", "t": "截断,打断"}, {"w": "剿截", "t": "斩断"}, {"w": "剿捕", "t": "讨伐逮捕"}, {"w": "剿擒", "t": "剿捕"}, {"w": "剿荡", "t": "讨伐荡平。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3049wx','静','1','jìng','青','14','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从青,争声。本义:彩色分布适当)。"}, {"meaning": "安静;宁静。", "cites": [{"t": "静言思之。", "b": "《诗·邶风·柏舟》"}, {"t": "宵静女德,以伏蛊慝。", "b": "《国语·晋语》"}, {"t": "本朝不静。", "b": "《吕氏春秋·音律》"}, {"t": "静乃明几。", "b": "《吕氏春秋·审分》"}, {"t": "莫不静好。", "b": "《诗·郑风·女曰鸡鸣》"}, {"t": "清和肃穆,莫不静畅。", "b": "晋·支遁《八关斋会诗序》"}], "words": [{"w": "静雅", "t": "安静"}, {"w": "静鞭", "t": "帝王仪仗的一种,鞭形,振之作响,令人肃静。也叫“鸣鞭”"}, {"w": "静办处", "t": "安静的地方。"}]}, {"meaning": "静止,物体不运动(跟“动”相反)。", "cites": [{"t": "怒则动,动则手足不静。", "b": "《淮南子·本经》"}, {"t": "树欲静而风不止,子欲养而亲不待也。", "b": "《韩诗外传》"}], "words": [{"w": "静物", "t": "静止不动的物体"}, {"w": "静美", "t": "静止形态的美"}, {"w": "静风", "t": "空气无显著的运动"}, {"w": "静海", "t": "平静的海"}, {"w": "静流", "t": "死水。"}]}, {"meaning": "没有声响;寂静。", "cites": [{"t": "茅檐人静。", "b": "陆游《夜闻杜鹃》"}, {"t": "静间按些。", "b": "《楚辞·招魂》"}], "words": [{"w": "静巉巉", "t": "静碜碜,静沉沉。形容沉静、静悄悄"}, {"w": "静荡荡", "t": "寂静空旷的样子"}, {"w": "静室", "t": "静舍。清静的居室。寺院。"}]}, {"meaning": "干净,纯净。", "cites": [{"t": "其告维何,边豆静嘉。", "b": "《诗·大雅·既醉》"}, {"t": "静洁足以享上帝,礼鬼神。", "b": "《淮南子·本经》"}], "words": [{"w": "静扫", "t": "打扫干净"}, {"w": "静青", "t": "纯青"}, {"w": "静嘉", "t": "洁净美好。"}]}, {"meaning": "善。", "cites": [{"t": "东门之栗,有静家室。", "b": "《艺文类聚》引《韩诗》"}]}, {"meaning": "倦怠。", "cites": [{"t": "其静也,日减其所有,而损其所成。", "b": "《太玄》"}]}, {"meaning": "清理;使干净。", "words": [{"w": "静狱", "t": "清理牢中的囚犯"}, {"w": "静室", "t": "清扫居室。"}]}, {"meaning": "使安定。", "cites": [{"t": "大匡用惠,施舍静众。", "b": "《逸周书·大匡》"}], "words": [{"w": "静心", "t": "使心灵安定"}, {"w": "静民", "t": "安定民心"}, {"w": "静边", "t": "安定边境。"}]}, {"meaning": "直言相劝,止人之失。", "cites": [{"t": "陈言而伏,静而正之。", "b": "《礼记·儒行》"}]}, {"meaning": "古州名。"}, {"meaning": "唐置。在今四川省松潘县西南。"}, {"meaning": "辽置。在今辽宁省境。"}, {"meaning": "真情。", "cites": [{"t": "中静不留,裕德无求。", "b": "《管子·势》"}, {"t": "乐由中出,故静;礼自外作,故文。", "b": "《礼记·乐记》"}, {"t": "义而顺,文而静,宽而有辨。", "b": "《礼记·表记》"}, {"t": "饰貌者不情。", "b": "《大戴礼·文王官人》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3050wx','碧','1','bì','石','14','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从玉,从石,白声。本义:青绿色的玉石)。"}, {"meaning": "同本义。", "cites": [{"t": "碧,石之青美者。", "b": "《说文》"}, {"t": "高山,其下多青碧。", "b": "《山海经·西山经》"}]}, {"meaning": "又。", "cites": [{"t": "章峨之山多瑶碧。", "b": ""}, {"t": "昆仑碧树瑶树在其北。", "b": "《淮南子·地形》"}, {"t": "锡碧金银,众色炫耀。", "b": "《汉书·司马相如传》"}], "words": [{"w": "碧卢", "t": "像玉的美石"}, {"w": "碧箫", "t": "用碧玉制的箫"}, {"w": "碧玉椽", "t": "用碧玉做的椽子。"}]}, {"meaning": "指代绿水。", "cites": [{"t": "碧水东流至此回。", "b": "唐·李白《望天门山》"}, {"t": "一碧万顷。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "碧波", "t": "清澄绿色的水波"}, {"w": "碧泱泱", "t": "水流澄绿深广的样子"}, {"w": "碧流", "t": "绿水"}, {"w": "碧漪", "t": "清澈的水波。泛指绿水。"}]}, {"meaning": "青绿色。", "cites": [{"t": "绿碧青丝绳。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "碧峰巉然孤起。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "寒则苍,春则碧。", "b": "王夫人《小云山记》"}], "words": [{"w": "碧香", "t": "本指绿酒的馨,后为酒名"}, {"w": "碧海", "t": "碧绿色的海"}, {"w": "碧芳", "t": "绿叶"}, {"w": "碧城", "t": "传说中仙人居住的地方。"}]}, {"meaning": "青白色,浅蓝色。", "cites": [{"t": "春草碧色,春水渌波。", "b": "江淹《别赋》"}, {"t": "接天连叶无穷碧。", "b": "宋·杨万里《晓出净慈寺送林子芳》"}], "words": [{"w": "碧雾", "t": "青色的云雾"}, {"w": "碧烟", "t": "青色的烟雾"}, {"w": "碧云", "t": "青云;碧空中的云。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3051wx','璃','1','lí','王','14','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从玉,离声。琉璃:光洁如玉的石珠)——见“玻璃”(bōli)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3052wx','赘','1','zhuì','贝','14','','[{"pinyin": "zhuì", "defs": [{"meaning": "(会意。从敖贝。敖犹“放”,贝与财富有关。本义:抵押)。"}, {"meaning": "同本义。", "cites": [{"t": "赘,以物质钱也。", "b": "《说文》"}, {"t": "赘,得也。", "b": "《广雅》。按,以物得钱也。"}, {"t": "卖子与人作奴婢名曰赘子。", "b": "《淮南子·俗》"}, {"t": "间者,数年岁比不登,民待卖爵赘子以接衣食。", "b": "《汉书·严助传》"}], "words": [{"w": "赘子", "t": "旧时穷苦人家把孩子卖给富家做奴婢的,叫做“赘子”。"}]}, {"meaning": "聚会。", "cites": [{"t": "梁王赘其群臣而议其过。", "b": "《说苑》"}], "words": [{"w": "赘聚", "t": "会聚"}, {"w": "赘结", "t": "聚集,集结。"}]}, {"meaning": "连缀,附着。", "cites": [{"t": "君若赘旒然。", "b": "《公羊传·襄公十六年》"}, {"t": "欲赘天下之兵。", "b": "《韩非子·存韩》"}, {"t": "虎贲赘衣。", "b": "班固《西都赋》"}]}, {"meaning": "又如;赘附(依附);赘旒(连缀)。"}, {"meaning": "增添;附加 。如;赘名(附列其名)。"}, {"meaning": "恶的。", "cites": [{"t": "有独见之虑,见赘于人。", "b": "《后汉书》"}]}, {"meaning": "就婚于女家与改为女家姓的男子称为“赘婿”。对男家来说,出去当赘婿称为“出赘”。对女家来说,招女婿称为“招赘”。男子到女家当赘婿称为“入赘”。", "cites": [{"t": "赘而不赎,主家配以女,则谓之赘婿。", "b": "朱骏声《说文通训定声》"}, {"t": "发诸赘婿贾人。", "b": "《史记·始皇纪》"}, {"t": "土将军,你若早破西岐,吾将弱女赘公为婿。", "b": "《封神演义》"}], "words": [{"w": "赘入", "t": "入赘"}, {"w": "赘娶", "t": "入赘"}, {"w": "赘亲", "t": "入赘成亲。"}]}, {"meaning": "颈椎骨。", "cites": [{"t": "肩高于顶,句赘指天。", "b": "《庄子·大宗师》"}]}, {"meaning": "赘瘤;肉瘤。", "cites": [{"t": "赘,属也。横生一肉属着体也。", "b": "《释名》"}, {"t": "具赘卒荒。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "赘疵", "t": "肉瘤。比喻多余无用之物"}, {"w": "赘木", "t": "有赘瘤状物的树木"}, {"w": "赘行", "t": "赘瘤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3053wx','熬','1','áo āo','灬','14','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从火,敖声。本义:煎干;炒干)。"}, {"meaning": "同本义。", "cites": [{"t": "熬,干煎也。", "b": "《说文》"}, {"t": "熬,火干也。以火而干五谷之类。", "b": "《方言七》"}, {"t": "淳熬。", "b": "《礼记·内则》"}, {"t": "设熬。", "b": "《周礼·小祝》"}, {"t": "何物中长食?胡麻慢火熬。", "b": "王建《隐者居》"}], "words": [{"w": "熬谷", "t": "干炒过的谷物"}, {"w": "熬稃", "t": "爆米花。"}]}, {"meaning": "用小火慢煮。", "cites": [{"t": "太宗遣使取熬糖法。", "b": "《新唐书·摩揭陀传》"}], "words": [{"w": "熬粥", "t": "慢火煮粥"}, {"w": "熬汤", "t": "煮物制汤。"}]}, {"meaning": "忍受;忍耐;坚持。", "cites": [{"t": "我心兮煎熬。", "b": "《楚辞·怨上》"}, {"t": "二则口渴难熬。", "b": "《水浒》"}], "words": [{"w": "熬不住", "t": "忍耐不了"}, {"w": "熬不过苦刑", "t": ""}]}]}, {"pinyin": "āo", "defs": [{"meaning": "烹调方法，把蔬菜等放在水里煮", "words": [{"w": "熬白菜", "t": ""}, {"w": "熬豆腐", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3054wx','墙','1','qiáng','土','14','','[{"pinyin": "qiáng", "defs": [{"meaning": "(会意。从啬,从土。“啬”有节俭收藏的意思。垒土为墙,意在收藏。本义:房屋或园场周围的障壁)。"}, {"meaning": "同本义。", "cites": [{"t": "墙,垣蔽也。", "b": "《说文》"}, {"t": "无逾我墙。", "b": "《诗·郑风·将仲子》"}, {"t": "粪土之墙不可圬也。", "b": "《论语·公冶长》"}, {"t": "止如堵墙。", "b": "《尉缭子·战威》"}, {"t": "老翁逾墙走。", "b": "唐·杜甫《石壕吏》诗"}], "words": [{"w": "墙阙", "t": "院落;门庭"}, {"w": "墙宇", "t": "房舍,住宅;喻指人的气度"}, {"w": "墙篱", "t": "藩篱,篱笆"}, {"w": "墙东", "t": "比喻隐居不仕,以避乱世"}, {"w": "墙茨", "t": "墙上生长蒺藜,意欲清除,又恐墙坏家毁。比喻阖门淫乱,家丑难除"}, {"w": "土墙;围墙", "t": ""}]}, {"meaning": "门屏。", "cites": [{"t": "而在萧墙之内也。", "b": "《论语·季氏》。按:萧墙之内,指国君塞门之内,喻内忧"}], "words": [{"w": "萧墙", "t": "古代宫室内当门的小墙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3055wx','墟','1','xū','土','14','','[{"pinyin": "xū", "defs": [{"meaning": "(本作“虚”。形声。从土,虚声。本义:大土山)。"}, {"meaning": "同本义。", "cites": [{"t": "墟土之人大,沙土之人细。", "b": "《孔子家语》"}], "words": [{"w": "墟土", "t": "丘陵之地"}, {"w": "墟垒", "t": "犹堡垒。"}]}, {"meaning": "废址,故城。", "cites": [{"t": "使人之朝为草而国为墟。", "b": "《吕氏春秋·贵直》"}], "words": [{"w": "殷墟;墟棘,墟榛,墟莽", "t": "废墟榛莽;荒野。"}]}, {"meaning": "坟墓。", "cites": [{"t": "墟,墟墓。", "b": "《字汇》"}], "words": [{"w": "墟墓", "t": "墟坟,丘墓,墓地。"}]}, {"meaning": "乡村集市。", "cites": [{"t": "二豪贼劫持反接,布囊其口,去逾四十里之墟所卖之。", "b": "《童区寄传》"}], "words": [{"w": "墟市;墟集", "t": "乡村市集"}, {"w": "墟期,墟日", "t": "市集日。"}]}, {"meaning": "场所。", "cites": [{"t": "古之至人,假道于仁,诧宿于义,以游逍遥之墟。", "b": "《庄子》"}]}, {"meaning": "毁为废墟。", "cites": [{"t": "今万乘之国,墟数于千,不胜而入。", "b": "《墨子》"}]}, {"meaning": "奴役。", "cites": [{"t": "通商而墟五印矣。", "b": "康有为《强学会序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3056wx','嘉','1','jiā','口','14','','[{"pinyin": "jiā", "defs": [{"meaning": "(形声。从壴(zhù),加声。本义:善,美)。"}, {"meaning": "同本义。", "cites": [{"t": "嘉,美也。", "b": "《说文》"}, {"t": "嘉,善也。", "b": "《尔雅》"}, {"t": "孚于嘉。", "b": "《易·随》"}, {"t": "嘉靖殷邦。", "b": "《书·无逸》"}, {"t": "以嘉视亲万民。", "b": "《周礼·大宗伯》"}, {"t": "以嘉石平罢民。—《周礼·大司寇》。注:“文石也。”", "b": ""}, {"t": "稻曰嘉蔬。", "b": "《礼记·曲礼》"}, {"t": "尔有嘉谟嘉猷。", "b": "《礼记·坊记》"}, {"t": "其新孔嘉,其旧如之何?", "b": "《诗·豳风·东山》"}], "words": [{"w": "嘉羞", "t": "美味的食品"}, {"w": "嘉况", "t": "丰厚的赏赐"}, {"w": "嘉言", "t": "善美的言辞"}, {"w": "嘉祉", "t": "美善幸福。"}]}, {"meaning": "幸福;吉祥。", "cites": [{"t": "蒙获嘉瑞,赐兹祉福。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "嘉祥", "t": "吉兆"}, {"w": "嘉娱", "t": "幸福快乐"}, {"w": "嘉气", "t": "瑞气"}, {"w": "嘉福", "t": "幸福美好"}, {"w": "嘉祯", "t": "嘉贞。吉祥的征兆。"}]}, {"meaning": "乐;欢娱。", "cites": [{"t": "以嘉魂魂。", "b": "《礼记·礼运》。注:“乐也。”"}], "words": [{"w": "嘉庆", "t": "值得庆贺的吉祥事"}, {"w": "嘉虞", "t": "欢乐"}, {"w": "嘉慰", "t": "欣慰"}, {"w": "嘉容", "t": "喜悦的神色。"}]}, {"meaning": "赞美,称道、颂扬事物的美好。", "cites": [{"t": "嘉吾子之赐。", "b": "《国语·晋语》"}, {"t": "武帝嘉其义。", "b": "《汉书·李广苏建传》"}, {"t": "嘉其能行古道。", "b": "唐·韩愈《师说》"}, {"t": "上大嘉悦。", "b": "《聊斋志异·促织》"}], "words": [{"w": "嘉纳", "t": "赞许并采纳"}, {"w": "嘉贶", "t": "奖赏"}, {"w": "嘉与", "t": "奖励厚待。"}]}, {"meaning": "之一。(指饮食、婚冠、宾射、飨宴、贺庆等礼)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3057wx','摧','1','cuī','扌','14','','[{"pinyin": "cuī", "defs": [{"meaning": "(形声。从手,崔声。本义:折断)。"}, {"meaning": "同本义。", "cites": [{"t": "先祖于摧。", "b": "《诗·大雅·云汉》"}, {"t": "商旅不行,樯倾楫摧。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "摧折", "t": "折断毁坏"}, {"w": "摧剥", "t": "摧折剥落"}, {"w": "摧烧", "t": "折断而投于火中烧毁。"}]}, {"meaning": "摧毁,破坏,毁坏。", "cites": [{"t": "列缺霹雳,上峦崩摧。", "b": "李白《梦游天姥吟留别》"}], "words": [{"w": "摧坚", "t": "攻破敌人的坚锐部队"}, {"w": "摧坚斩敌", "t": "破阵杀敌"}, {"w": "摧破", "t": "摧陷攻破"}, {"w": "摧逼", "t": "摧残。"}]}, {"meaning": "挫败。", "cites": [{"t": "折锐摧矜。", "b": "《楚辞·忧苦》。注:“挫也。”"}, {"t": "素疾大户兼并,力摧豪强,抚贫弱。", "b": "《明史·海瑞传》"}], "words": [{"w": "摧屈受挫而屈服;摧辱", "t": "挫折羞辱"}, {"w": "摧败", "t": "击破;打败"}, {"w": "摧锋", "t": "挫败敌军的锐气"}, {"w": "摧锋陷阵", "t": "破敌深入。"}]}, {"meaning": "悲痛,哀伤。", "cites": [{"t": "阿母大悲摧。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "摧心", "t": "痛心。非常悲痛"}, {"w": "摧怆", "t": "伤心"}, {"w": "摧圮", "t": "伤痛之极"}, {"w": "摧裂", "t": "极言悲痛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3058wx','赫','1','hè','赤','14','','[{"pinyin": "hè", "defs": [{"meaning": "(会意。从二赤。火赤。本义:泛指赤色)。"}, {"meaning": "红如火烧。亦泛指火红色。", "cites": [{"t": "赫,火赤貌。", "b": "《说文》"}, {"t": "赫如渥赭。", "b": "《诗·邶风·简兮》"}], "words": [{"w": "赫日", "t": "红日"}, {"w": "赫赤", "t": "深红;火红"}, {"w": "赫赤赤", "t": "谓赤红如火"}, {"w": "赫煌", "t": "赤色光明的样子。"}]}, {"meaning": "显耀。", "cites": [{"t": "以赫厥灵。", "b": "《诗·大雅·生民》"}], "words": [{"w": "赫奕", "t": "显耀盛大的样子"}, {"w": "赫剌剌", "t": "威武显赫的样子"}, {"w": "赫耀", "t": "显赫。"}]}, {"meaning": "显盛。", "cites": [{"t": "赫赫楚国,而君临之。", "b": "《国语·楚语》"}], "words": [{"w": "赫奕", "t": "光彩灿烂的样子"}, {"w": "赫奕", "t": "显著盛大的样子"}, {"w": "赫张", "t": "声势盛大的样子。"}]}, {"meaning": "光明。", "cites": [{"t": "赫,明也。", "b": "《小尔雅·广诂》"}], "words": [{"w": "赫戏", "t": "光明显盛的样子"}, {"w": "赫曦", "t": "光明显盛的样子"}, {"w": "赫焕", "t": "光华炫耀的样子"}, {"w": "赫烁", "t": "明亮闪耀的样子。"}]}, {"meaning": "勃然大怒。", "cites": [{"t": "王赫斯怒。", "b": "《诗·大雅·皇矣》"}], "words": [{"w": "赫咤", "t": "愤怒叹息"}, {"w": "赫怒", "t": "愤怒"}, {"w": "赫斯", "t": "帝王盛怒貌。"}]}, {"meaning": "恐吓。", "cites": [{"t": "反予来赫。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "赫诈", "t": "恐吓诈骗。"}]}, {"meaning": "使感到惊奇、震骇或恐怖。", "cites": [{"t": "伐恩恃权,震赫中外。", "b": "《新唐书》"}]}, {"meaning": "分裂,支解。", "cites": [{"t": "凡使十二神追恶凶,赫女躯,拉女干,节解女肉,抽女肺肠。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3059wx','截','1','jié','戈','14','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从戈,雀声。本义:断绝,切断)。"}, {"meaning": "同本义。", "cites": [{"t": "巀,断也。", "b": "《说文》"}, {"t": "截彼淮浦,王师之所。", "b": "《诗·大雅·常武》。笺:“就王师而断之。”"}, {"t": "海外有截。", "b": "《诗·商颂·长发》。笺:“截,整齐也。”疏:“截者,斩断之义,故为齐也。”"}, {"t": "不如截而行。", "b": "《国语·晋语》。注:“旁出为截。”"}, {"t": "截胫剖心。", "b": "《晋书·石季龙截记》"}, {"t": "今犹俎上腐肉,任人脍截耳。", "b": "《世说新语·方正》"}, {"t": "截趾适屦。", "b": "《后汉书·荀爽传》"}], "words": [{"w": "截头", "t": "尽头"}, {"w": "截替", "t": "取代"}, {"w": "截齐", "t": "齐截"}, {"w": "截发留宾", "t": "截发剉荐。指竭尽全力招待客人。"}]}, {"meaning": "拦阻;阻挡。", "cites": [{"t": "截春山以北。", "b": "《穆天子传》。注:“犹阻也。”"}, {"t": "径截辎重。", "b": "李华《吊古战场文》"}], "words": [{"w": "截没", "t": "截留吞没"}, {"w": "截阻", "t": "拦阻"}, {"w": "截途", "t": "当道,拦路"}, {"w": "截杀", "t": "拦住攻杀"}, {"w": "截拿", "t": "截拦捉拿"}, {"w": "截拔", "t": "截留调拔"}, {"w": "截战", "t": "拦住厮杀。"}]}, {"meaning": "直渡;跨越。"}, {"meaning": "购买。", "cites": [{"t": "怕无布绢,将现钱去长街上铺内截。", "b": "元·宫天挺《范张鸣黍》"}]}, {"meaning": "了结。", "cites": [{"t": "钱给了不要紧,该多少我明儿还你就截了。", "b": "清·刘鹗《老残游记》"}], "words": [{"w": "截了", "t": "结了"}, {"w": "截日", "t": "即日。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3060wx','誓','1','shì','言','14','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从言,折声。本义:发誓;立誓)。"}, {"meaning": "同本义。", "cites": [{"t": "誓,以言约束也。", "b": "《说文》。段注:“凡自表不食言之辞皆曰誓,亦约束之意也。”"}, {"t": "约信曰誓。", "b": "《礼记·曲礼》"}, {"t": "予誓,告汝誓命。", "b": "《书·甘誓》。注:“要信也。”"}, {"t": "信誓旦旦,不思其反。", "b": "《诗·卫风·氓》"}, {"t": "司射西面誓之。", "b": "《仪礼·大射仪》。注:“犹告也。”"}, {"t": "而誓之曰:“不及黄泉,无相见也。", "b": "《左传·隐公元年》"}, {"t": "终待说山盟海誓。", "b": "赵长卿《贺新郎》"}, {"t": "不久当还归,誓天不相负。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "为誓与城为殉。", "b": "清·全祖望《梅花岭记》"}, {"t": "至于誓天断发,泣下沾襟,何其衰也。", "b": "宋·欧阳修《新五代史·伶官传·序》"}], "words": [{"w": "誓志", "t": "发誓立志"}, {"w": "誓死不贰", "t": "发誓至死不变心"}, {"w": "誓辞", "t": "立誓的言辞"}, {"w": "誓戒", "t": "誓约警戒"}, {"w": "誓剑", "t": "对着剑发誓;皇帝赠与出巡大臣的宝剑,即后世所称的“上方宝剑”"}, {"w": "誓书铁券", "t": "即“丹书铁券”。古代帝王颁赐功臣的享有免罪等特权的证件。"}]}, {"meaning": "接受爵位。", "cites": [{"t": "凡诸侯之适子,誓于天下,摄其君,则下其君之礼一等。", "b": "《周礼》"}]}, {"meaning": "告诫;告知。", "cites": [{"t": "司射西面誓之曰:“公射大候,大夫射参,士射干。”", "b": "《仪礼·大射仪》。注:“犹告也。”"}, {"t": "惟君有黼裘以誓省。", "b": "《礼记·玉藻》。疏:“告勑也。”"}, {"t": "[五戒]一日誓,用之于军旅。", "b": "《周礼·秋官·士师》"}], "words": [{"w": "誓戒", "t": "约束警戒"}, {"w": "誓民", "t": "告戒吏民"}, {"w": "誓众", "t": "告诫众人。"}]}, {"meaning": "指国与国、人与人之间所订立的誓约;盟约;誓言。", "cites": [{"t": "张陈背誓。", "b": "曹植《五帝诛》"}, {"t": "周武有孟津之誓。", "b": "《左传·昭公四年》"}, {"t": "女子先有誓,老姥岂敢言。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "誓令", "t": "誓言与命令"}, {"w": "誓信", "t": "盟约"}, {"w": "誓书", "t": "盟约"}, {"w": "誓章", "t": "记载有誓词的文件"}, {"w": "誓要", "t": "约盟,盟誓。"}]}, {"meaning": "谨慎。", "cites": [{"t": "曲艺皆誓之,以待又语。", "b": "《礼记·文王世子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3061wx','境','1','jìng','土','14','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从土,竟声。本义:边境,国境)。"}, {"meaning": "同本义。", "cites": [{"t": "境,疆也。", "b": "《说文新附》"}, {"t": "至齐境。", "b": "《吕氏春秋·赞能》"}]}, {"meaning": "字本作“竟”。", "cites": [{"t": "亡不越竟。", "b": "《左传·宣公二年》"}, {"t": "边竟有人焉。", "b": "《庄子·天道》"}, {"t": "其竟关之政尽察。", "b": "《荀子·富国》"}, {"t": "与燕王会境上。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "廉颇送至境。", "b": ""}, {"t": "屯于境上。", "b": "《史记·魏公子列传》"}, {"t": "起视四境。", "b": "宋·苏洵《权书·六国论》"}], "words": [{"w": "出境", "t": "离开国境"}, {"w": "入境", "t": "进入国境"}, {"w": "境宇", "t": "国境,疆土"}, {"w": "境人", "t": "境内之人;本地人"}, {"w": "境头", "t": "结果;亦作“景头”。神佛点化人制造的幻境"}, {"w": "境土", "t": "疆域;领地"}, {"w": "境会", "t": "在边界上聚会。"}]}, {"meaning": "居所,地方。", "cites": [{"t": "结庐在人境,而无车马喧。", "b": "晋·陶潜《饮酒诗》"}, {"t": "士大夫出其境。", "b": "《明史》"}]}, {"meaning": "景象,景物。", "cites": [{"t": "槛外诸境。", "b": "[英]赫胥黎著、严复译《天演论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3062wx','摘','1','zhāi','扌','14','','[{"pinyin": "zhāi", "defs": [{"meaning": "(形声。小篆字形,从手,啻(chì)声。本义:用手采下或取下)。"}, {"meaning": "同本义。", "cites": [{"t": "摘,摭果树实也。", "b": "《说文》"}, {"t": "摘,取也。", "b": "《广雅》"}, {"t": "一摘使瓜好,再摘令瓜稀。", "b": "《新唐书·承天皇帝传》"}, {"t": "以摘之。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "摘而藏之。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "摘胆剜心", "t": "形容杀人者的凶残"}, {"w": "摘肩儿", "t": "摘下肩上的担子"}, {"w": "摘青", "t": "谓果实等未成熟即采摘"}, {"w": "摘瓜抱蔓", "t": "喻一扫而空"}, {"w": "摘桃子", "t": "比喻坐享其成"}, {"w": "摘棉花;摘苹果", "t": ""}]}, {"meaning": "除去,去掉。", "cites": [{"t": "过了三天再不去,叫人来摘门下瓦。", "b": "《儒林外史》"}], "words": [{"w": "把灯泡摘下来;摘帽", "t": "脱下帽子"}, {"w": "摘头", "t": "除去头上首饰"}, {"w": "摘不开", "t": "摆脱不了。"}]}, {"meaning": "摘录。", "cites": [{"t": "寻章摘句老雕虫,晓月当帘挂玉弓。", "b": "唐·李贺《南国》"}], "words": [{"w": "摘句", "t": "摘录文章诗歌之句"}, {"w": "摘钞", "t": "择要抄录"}, {"w": "摘句寻章", "t": "摘取搜寻文章的片断词句。指读书局限于文字的推求。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3063wx','摔','1','shuāi','扌','14','','[{"pinyin": "shuāi", "defs": [{"meaning": "(形声。从手,率声。本义:用力扔在地上)。"}, {"meaning": "同本义。", "cites": [{"t": "盛酒瓮摔做碎瓷瓯。", "b": "元·康进之《李逵负荆》"}, {"t": "小王把书包往地上一摔,气呼呼地走了", "b": ""}], "words": [{"w": "摔丧驾灵", "t": "即摔盆引灵。摔丧:出殡起动棺材时,孝子在棺前摔碎烧纸的瓦盆,也称“摔盆”。驾灵:孝子抬扶灵柩或在灵柩前领路"}, {"w": "摔打", "t": "抓住东西往地上猛扔。"}]}, {"meaning": "跌倒;落下。", "cites": [{"t": "你没摔着么?", "b": "曹禺《雷雨》"}], "words": [{"w": "他摔了好多次,才学会骑自行车;飞机摔下来了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3064wx','撇','1','piē piě','扌','14','','[{"pinyin": "piē", "defs": [{"meaning": "(形声。从手,敝声。本义:抛弃,弃置不顾)。"}, {"meaning": "同本义。", "cites": [{"t": "我弟兄两个,便去镇上撇呵卖药,教使枪棒。", "b": "《水浒传》"}], "words": [{"w": "撇骨池", "t": "寺院中专供抛撒骨灰的池塘"}, {"w": "撇脱些", "t": "方言。行动干净利索,不留痕迹"}, {"w": "撇闪", "t": "丢开"}, {"w": "撇赖", "t": "丢开"}, {"w": "撇吊", "t": "丢开"}, {"w": "撇却", "t": "抛弃;丢开"}, {"w": "撇闪", "t": "抛弃。"}]}, {"meaning": "眼光掠过;匆匆一看。", "cites": [{"t": "怪檀郎转眼偷相撇。", "b": "明·汤显祖《紫钗记》"}]}, {"meaning": "碰触;击。", "cites": [{"t": "时有一书生,又能低头以所葛巾角撇棋也。", "b": "《世说新语·巧艺》刘注引《博物志》"}], "words": [{"w": "撇波", "t": "击波破浪。"}]}, {"meaning": "拂拭,掠过。", "cites": [{"t": "历倒景而绝飞梁兮,浮蠛蠓而撇天。", "b": "《文选·扬雄·甘泉赋》"}]}]}, {"pinyin": "piě", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3065wx','聚','1','jù','耳','14','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。小篆,下面是三个人,表示人多;上面的“取”,作声符。本义:村落)。"}, {"meaning": "同本义。", "cites": [{"t": "聚,会也。", "b": "《说文》。按,邑落曰聚,今曰邨,曰镇,北方曰集皆是。"}, {"t": "一年而所居成聚。", "b": "《史记·五帝纪》"}, {"t": "聚曰序。", "b": "《史记·平帝纪》"}, {"t": "所止聚落化其德。", "b": "《后汉书·王扶传》。注:“小于乡曰聚。”"}, {"t": "乡聚里中人哀而救之。", "b": "刘向《说苑》"}, {"t": "禹无十户之聚,以王诸侯。", "b": "枚乘《上书谏吴王》"}], "words": [{"w": "聚落", "t": "村落里邑,人群聚居的地方。"}]}, {"meaning": "众;集团;一伙。", "cites": [{"t": "我是以有辅氏之聚。", "b": "《左传·成公十三年》"}, {"t": "陈人恃其聚。", "b": "《左传·哀公十七年》"}], "words": [{"w": "聚观", "t": "群聚观看"}, {"w": "聚口", "t": "犹齐声。"}]}, {"meaning": "地名 。在今山西省绛县东南。"}, {"meaning": "会合;聚集。", "cites": [{"t": "而发于众心之所聚。", "b": "《管子·君臣上》"}, {"t": "聚室而谋日。", "b": "《列子·汤问》"}, {"t": "以王命聚之。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "鸣锣聚众。", "b": "《广东军务记》"}, {"t": "聚至百有余乡。", "b": ""}], "words": [{"w": "聚散浮生", "t": "指人生聚散无定。浮生:人活着的时候是虚浮无定的"}, {"w": "聚麀之诮", "t": "比喻和不三不四的女人鬼混在一起,遭人耻笑。麀:母鹿,泛指母兽"}, {"w": "聚寇", "t": "聚集起来的盗寇。"}]}, {"meaning": "积蓄,累积。", "cites": [{"t": "聚菽粟。", "b": "《墨子·尚贤中》"}, {"t": "我今将畜积并聚之于仓廪。", "b": "《荀子·王制》"}], "words": [{"w": "聚沙成塔;聚米", "t": "堆积米粒做成模型以说明军事形势,运筹决策;米堆。形容矮小"}, {"w": "聚货", "t": "聚集货物。"}]}, {"meaning": "征集。", "cites": [{"t": "太医以王命聚之。", "b": "柳宗元《捕蛇者说》"}]}, {"meaning": "使民众聚居。", "cites": [{"t": "大叔完聚。(完;修好城墙。)", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3066wx','慕','1','mù','小','14','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从心,莫声。本义:依恋;向往)。"}, {"meaning": "同本义。", "cites": [{"t": "慕,习也。", "b": "《说文》。按,思也。"}, {"t": "其往也如慕。", "b": "《礼记·檀弓》"}, {"t": "巨室之所慕。", "b": "《孟子·万章》"}, {"t": "人少,则慕父母。", "b": ""}], "words": [{"w": "慕义", "t": "向往正义"}, {"w": "慕向", "t": "思慕向往"}, {"w": "慕企", "t": "企慕,仰慕"}, {"w": "慕位", "t": "思慕权位"}, {"w": "慕尚", "t": "向往推崇"}, {"w": "慕思", "t": "向往;仰慕思念。"}]}, {"meaning": "仰慕;羡慕。", "cites": [{"t": "诱慕于名位。", "b": "《淮南子·原道》。注:“贪也。”"}, {"t": "衡不慕当世。", "b": "《后汉书·张衡传》"}], "words": [{"w": "慕古", "t": "仰慕古人"}, {"w": "慕仰", "t": "仰慕"}, {"w": "慕羡", "t": "羡慕"}, {"w": "慕艳", "t": "艳羡"}, {"w": "慕效", "t": "羡慕仿效"}, {"w": "慕利", "t": "追求财利"}, {"w": "慕蔺", "t": "钦慕贤能的人"}, {"w": "慕化", "t": "仰慕归化"}, {"w": "慕古薄今", "t": "厚古薄今"}, {"w": "慕用", "t": "仰慕信赖"}, {"w": "慕仰", "t": "仰慕。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3067wx','暮','1','mù','日','14','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。从日,莫声。古字作“莫”,像太阳落到草丛中,表示天将晚。“暮”为后起字。本义:日落时,傍晚)。"}, {"meaning": "同本义。", "cites": [{"t": "暮者,晚也。", "b": "《论衡·明雩》"}, {"t": "朝三而暮四。", "b": "《庄子·齐物论》"}, {"t": "恐美人之迟暮。", "b": "《楚辞·离骚》"}, {"t": "旦辞爷娘去,暮宿黄河边。", "b": "《乐府诗集·木兰诗》"}, {"t": "今朝至,暮变。", "b": "《韩非子·难一》"}, {"t": "至莫夜月光明。", "b": "宋·苏轼《石钟山记》"}, {"t": "暮投石壕村,有吏夜捉人。", "b": "唐·杜甫《石壕吏》"}], "words": [{"w": "暮天", "t": "傍晚的天空"}, {"w": "暮雨", "t": "傍晚的雨"}, {"w": "暮途", "t": "傍晚的路程"}, {"w": "暮烟", "t": "傍晚的烟霭"}, {"w": "暮暮", "t": "每天傍晚"}, {"w": "暮鼓", "t": "鼓楼晚间报时的鼓声"}, {"w": "暮暗", "t": "日落天暗。"}]}, {"meaning": "夜晚。", "cites": [{"t": "枝封暮雪。", "b": "沈约《桐赋》"}, {"t": "暮春者,春服既成,冠者五六人。", "b": "《论语》"}], "words": [{"w": "暮月", "t": "一季的末月"}, {"w": "暮末", "t": "犹末世"}, {"w": "暮冬", "t": "冬末。"}]}, {"meaning": "喻指年老,衰老。", "cites": [{"t": "藐是流离,至于暮齿。", "b": "庾信《哀江南赋序》"}], "words": [{"w": "暮老", "t": "指年老"}, {"w": "暮古", "t": "年老糊涂"}, {"w": "暮志", "t": "晚年的志向"}, {"w": "暮耋", "t": "指年老"}, {"w": "暮齿", "t": "晚年"}, {"w": "暮景", "t": "比喻垂老之年。"}]}, {"meaning": "迟;晚。", "cites": [{"t": "夫自念斯,学德未暮。", "b": "《吕氏春秋》"}, {"t": "烈士暮年,壮心不已。", "b": "曹操《步出夏门行》"}], "words": [{"w": "暮迟", "t": "犹言不及时"}, {"w": "暮生", "t": "父亲死后才出生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3068wx','摹','1','mó','手','14','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从手,莫声。本义:临摹,照着样子描画、写字)。"}, {"meaning": "同本义。", "cites": [{"t": "摹,规也。", "b": "《说文》。段注:“摹与模义略同。”"}, {"t": "规摹宏远矣。", "b": "《汉书·高帝纪下》。邓展曰:“若画工规摹物之摹。”"}, {"t": "摹法以中克。", "b": "《太玄法》"}, {"t": "三摹九据。", "b": "《汉书·扬雄传》"}, {"t": "余之手摹也。", "b": "韩愈《画记》"}, {"t": "上见其发秃,又所摹画不能称上意。", "b": "韩愈《毛颖传》"}, {"t": "六朝人尚字学,摹临特盛。", "b": "《琅琊代醉编》"}], "words": [{"w": "摹帖", "t": "摹字。描摹法帖"}, {"w": "摹版", "t": "翻刻的版本"}, {"w": "摹印", "t": "摹拓"}, {"w": "摹肖", "t": "依样复制"}, {"w": "摹勒", "t": "依样描字刻石;描摹勾勒。"}]}, {"meaning": "仿效。", "cites": [{"t": "若是,三代不摹,圣人未可师也。", "b": "范晔《后汉书》"}], "words": [{"w": "摹习", "t": "仿效;学习"}, {"w": "摹勒", "t": "模仿"}, {"w": "摹调", "t": "模仿调弄"}, {"w": "摹袭", "t": "模仿沿袭"}, {"w": "摹窃", "t": "模仿剽窃。"}]}, {"meaning": "描写,描绘。", "cites": [{"t": "谁能摹暂离之状,写永诀之情乎?", "b": "江淹《恨赋》"}], "words": [{"w": "摹画", "t": "描画,描绘"}, {"w": "描摹", "t": "用语言文字表现人或事物的形象、情状、特性等。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3069wx','蔓','1','màn wàn mán','艹','14','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。从艸,曼声。本义:藤蔓,草本蔓生植物的枝茎) 同本义。", "cites": [{"t": "蔓,葛属。", "b": "《说文》"}, {"t": "青树翠蔓。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "丹藤翠蔓。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "蔓广则歧多,歧多则饶子。", "b": "《齐民要术·种瓜》"}, {"t": "兔丝附蓬麻,引蔓故不长。", "b": "杜甫《新婚别》"}]}, {"meaning": "蔓延;滋长。", "cites": [{"t": "野有蔓草。", "b": "《诗·郑风·野有蔓草》。传:“延也。”"}, {"t": "敛蔓于野。", "b": "《诗·唐风·葛生》"}, {"t": "不蔓不枝。", "b": "宋·周敦颐《爱莲说》"}, {"t": "无使滋蔓,蔓,难图也。", "b": "《左传·隐公元年》"}], "words": [{"w": "蔓生", "t": "蔓延生长"}, {"w": "蔓衍", "t": "扩展延伸"}, {"w": "蔓草", "t": "蔓延滋生的草"}, {"w": "蔓连", "t": "延伸串联"}, {"w": "蔓蔓", "t": "滋长延伸的样子。"}]}]}, {"pinyin": "wàn", "defs": [{"meaning": "[方言] 指有较高表演技艺，有广泛影响的演艺明星。亦作\'大腕儿\'。"}]}, {"pinyin": "mán", "defs": [{"meaning": "【蔓菁】 一年生或二年生草本植物,块根肉质。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3070wx','蔑','1','miè','艹','14','','[{"pinyin": "miè", "defs": [{"meaning": "(会意。从苜(mò),从戍。“苜”是眼睛歪斜无神,“戍”是戍守人。合而表示人过于劳倦眼睛歪斜无神。本义:眼睛红肿看不清)。"}, {"meaning": "同本义。", "cites": [{"t": "蔑,目眵也。从目,蔑声。", "b": "《说文》。按,即蔑字"}, {"t": "得目为蔑。", "b": "宋玉《风赋》"}]}, {"meaning": "细小;轻微。", "cites": [{"t": "视日月而知众星之蔑也。", "b": "杨雄《法言·学行》"}], "words": [{"w": "蔑如", "t": "微细;没有什么了不起"}, {"w": "蔑贱", "t": "犹微贱。"}]}, {"meaning": "轻视;轻侮。亦作“懱”。", "cites": [{"t": "国步蔑资。", "b": "《诗·大雅·桑柔》"}, {"t": "岂蔑清庙,惮勅天乎?", "b": "《后汉书·班固传下》"}, {"t": "蔑贞,凶。", "b": "《易·剥卦》"}, {"t": "郑未失周典,王而蔑之,是不明贤也。", "b": "《国语·周语中》"}], "words": [{"w": "蔑辱", "t": "鄙弃凌辱"}, {"w": "蔑杀", "t": "犹灭杀"}, {"w": "蔑侮", "t": "轻视欺侮"}, {"w": "蔑弃", "t": "轻视,鄙弃。"}]}, {"meaning": "灭,消灭。", "cites": [{"t": "唐蔑字明。", "b": "《荀子·议兵》"}, {"t": "而蔑杀其民人。", "b": "《国语·周语》"}]}, {"meaning": "无;没有。", "cites": [{"t": "蔑,无也。", "b": "《小尔雅·广诂》"}, {"t": "丧乱蔑资。", "b": "《诗·大雅·板》"}, {"t": "吾有死而已,吾蔑从之矣。", "b": "《国语·晋语》"}, {"t": "蔑不济也。", "b": "《左传·僖公十年》"}], "words": [{"w": "蔑有", "t": "没有"}, {"w": "蔑须有", "t": "莫须有,没有"}, {"w": "蔑蔑", "t": "犹默默。无声息。"}]}, {"meaning": "以血涂染。引申为污,诬蔑。", "cites": [{"t": "衊,污血也。从血,蔑声。", "b": "《说文》"}, {"t": "少阴所至为悲妄衂衊。", "b": "《素问·六玄正纪大论》。注:“污血亦脂也。”"}, {"t": "污衊宗室。", "b": "《汉书·梁平王襄传》。注:“谓涂染也。”"}, {"t": "又投间蔑污使君。", "b": "高启《书博鸡者事》"}], "words": [{"w": "污蔑", "t": "用不实的言辞冤枉或破坏别人的名誉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3071wx','蔡','1','cài','艹','14','','[{"pinyin": "cài", "defs": [{"meaning": "(形声，祭声。本义:野草)。"}, {"meaning": "同本义。", "cites": [{"t": "蔡,草也。", "b": "《说文》"}, {"t": "蔡,草莽也。", "b": "《楚辞》注"}, {"t": "蔡莽螫刺,昆虫毒噬。", "b": "左思《魏都赋》"}]}, {"meaning": "周代国名,在今河南省上蔡、新蔡等县一带。", "cites": [{"t": "文王子叔度封于汝南上蔡为侯,作乱。周公放之。其子蔡仲成王复封至平侯,徙新蔡,昭侯徙九江下蔡,战国时灭于楚。", "b": "朱骏声《说文通训定声》"}]}, {"meaning": "占卜用的大龟。", "cites": [{"t": "且致大蔡也。", "b": "《左传·襄公二十三年》"}], "words": [{"w": "大蔡", "t": "大龟。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3072wx','蔗','1','zhè','艹','14','','[{"pinyin": "zhè", "defs": [{"meaning": "(形声。从艸,庶声。本义:甘蔗)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3073wx','蔽','1','bì','艹','14','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从艸,敝声。本义:小草)。"}, {"meaning": "遮住,遮掩。", "cites": [{"t": "蔽,蔽蔽小草也。", "b": "《说文》。朱骏声曰:“此字本训盖覆也。”"}, {"t": "蔽,障也,隐也。", "b": "《广雅》"}, {"t": "蒲蔽。", "b": "《周礼·巾车》。注:“车旁御风尘者。”"}, {"t": "乘马其蔽五。", "b": "《管子》。注:“所以捍车马。”"}, {"t": "景以蔽日。", "b": "《淮南子·修务》"}, {"t": "故能蔽不新成。", "b": "《老子》"}, {"t": "旌蔽日兮敌若云。", "b": "楚·屈原《九歌·国殇》"}, {"t": "项伯亦拔剑起舞,常以身翼蔽沛公。", "b": "《史记》"}, {"t": "阴翳蔽日。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "隐蔽", "t": "借旁的事物来遮掩"}, {"w": "屏蔽;蔽天", "t": "遮蔽天空,布满了整个天空。"}]}, {"meaning": "隐藏 蔽林间窥之。——唐·柳宗元《三戒》。", "cites": [{"t": "先生…引蔽驴后。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "蔽贤", "t": "隐蔽贤者,不使上知"}, {"w": "蔽形", "t": "遮掩身体。"}]}, {"meaning": "庇护。", "cites": [{"t": "盖借塞墙为蔽也。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "蔽护", "t": "掩护;庇护"}, {"w": "蔽橹", "t": "古代防御用的大盾"}, {"w": "蔽辜", "t": "抵罪。"}]}, {"meaning": "掩饰。", "cites": [{"t": "廉不蔽恶,耻不从枉。", "b": "《管子·牧民》"}], "words": [{"w": "蔽美", "t": "掩盖他人的美德、长处"}, {"w": "蔽恶", "t": "掩饰过错和坏行为。"}]}, {"meaning": "蒙蔽。", "cites": [{"t": "由此观之,王之蔽甚矣。", "b": "《战国策·齐策》"}, {"t": "屈平疾王听之不聪也,谗谄之蔽明也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "蔽蒙", "t": "蒙蔽;隐瞒"}, {"w": "蔽晦", "t": "蒙蔽。受遮蔽因而不明。"}]}, {"meaning": "概括。", "cites": [{"t": "一言以蔽之。", "b": "《论语·为政》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3074wx','蔼','1','ǎi','艹','14','','[{"pinyin": "ǎi", "defs": [{"meaning": "树木生长繁茂。", "cites": [{"t": "蔼蔼,盛也。", "b": "《广雅》"}, {"t": "蔼,茂盛貌。", "b": "《集韵》"}, {"t": "离芳蔼之方壮兮,余萎约而悲愁。", "b": "《楚辞·宋玉·九辩》。"}], "words": [{"w": "蔼彩", "t": "芳鲜茂盛的样子。"}]}, {"meaning": "盛多的样子。", "cites": [{"t": "蔼蔼、济济,止也。", "b": "《尔雅》"}, {"t": "蔼蔼王多吉士,维君子使,媚于天子。", "b": "《诗·大雅·卷阿》"}, {"t": "才夫蔼蔼而曼着兮。", "b": "《楚辞·逢纷》。注:“盛多貌。”"}, {"t": "郁萧条其幽蔼。", "b": "扬雄《河东赋》"}]}, {"meaning": "和气,态度好。", "cites": [{"t": "笑语蔼然。", "b": "《聊斋志异·王大》。"}], "words": [{"w": "和蔼", "t": "态度温和,容易接近。"}]}, {"meaning": "云气", "cites": [{"t": "悲风徽行轨,倾云结流蔼。", "b": "《文选·陆机·挽歌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3075wx','熙','1','xī','灬','14','','[{"pinyin": "xī", "defs": [{"meaning": "(形声,本义:曝晒;晒太阳)。"}, {"meaning": "同本义。", "cites": [{"t": "熙,燥也。", "b": "《说文》"}, {"t": "仰熙丹崖,俯澡绿水。", "b": "《文选·卢谌·赠刘琨》"}]}, {"meaning": "振兴;兴起。", "cites": [{"t": "允厘百工,庶绩咸熙。", "b": "《书·尧典》"}], "words": [{"w": "熙朝", "t": "使朝廷兴隆"}, {"w": "熙隆", "t": "兴盛,盛隆"}, {"w": "熙国", "t": "振兴国家。"}]}, {"meaning": "嬉戏。", "cites": [{"t": "王笑曰:“圣人非所与熙也。", "b": "《晏子春秋·内篇杂下》"}, {"t": "含哺而熙,鼓腹而游。", "b": "《庄子·马蹄》"}, {"t": "臣不敢以死为熙。", "b": "《淮南子·人间》"}], "words": [{"w": "熙游", "t": "游乐;游戏。"}]}, {"meaning": "光明、明亮。", "cites": [{"t": "熙,光也。", "b": "《尔雅》"}, {"t": "于缉熙敬止。", "b": "《礼记·缁衣》。注:“缉熙皆明也。”大学注:“缉熙,光明也。”"}, {"t": "缉熙单厥心。", "b": "《国语·周语》。注:“熙,光也。”"}, {"t": "呜呼圣皇及圣相,相与煊赫流淳熙。", "b": "李商隐《韩碑》"}], "words": [{"w": "熙皞", "t": "熙熙皞皞。光明祥和"}, {"w": "熙天", "t": "明朗的天空"}, {"w": "熙光", "t": "辉耀"}, {"w": "熙焰", "t": "烈焰。"}]}, {"meaning": "兴盛。", "cites": [{"t": "熙朝之佚事,即衰世之危端。", "b": "王世贞《艺苑卮言》"}], "words": [{"w": "熙盛", "t": "兴隆"}, {"w": "熙朝", "t": "兴盛的朝代。"}]}, {"meaning": "和悦。", "cites": [{"t": "熙熙兮共乐人之臧也。", "b": "《荀子·儒效》。注::和乐之貌。”"}], "words": [{"w": "熙怡", "t": "和悦的样子"}, {"w": "熙治", "t": "清明和乐的时代"}, {"w": "熙笑", "t": "和悦地笑着。"}]}, {"meaning": "幸福;吉祥。", "cites": [{"t": "忽乘青玄,熙事备成。", "b": ""}, {"t": "双桥镇上依然满眼熙和太平之盛。", "b": "茅盾《子夜》"}], "words": [{"w": "熙恬", "t": "愉快安静"}, {"w": "熙然", "t": "和乐的样子。"}]}, {"meaning": "和暖;暖和。", "cites": [{"t": "群山霭遐瞩,绿野布熙阳。", "b": "韦应物《扈亭西陂燕赏》"}], "words": [{"w": "熙阳", "t": "温暖的阳光。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3076wx','蔚','1','wèi yù','艹','14','','[{"pinyin": "wèi", "defs": [{"meaning": "(会意。从艸,尉声。本义:牡蒿)。"}, {"meaning": "同本义 。菊科。一种多年生草本(Artemisia japonica)。全草入药。", "cites": [{"t": "蓼蓼者莪,匪我伊蔚。", "b": "《诗·小雅·蓼莪》"}]}, {"meaning": "病。", "cites": [{"t": "五藏无蔚气。", "b": "《淮南子·俶真》"}], "words": [{"w": "蔚气", "t": "病气。"}]}, {"meaning": "草木茂盛。", "cites": [{"t": "蔚蔚,茂也。", "b": "《广雅·释训》"}, {"t": "茂树荫蔚。", "b": "《文选·班固·西都赋》"}, {"t": "设蔚施伏。", "b": "《淮南子·兵略》"}, {"t": "望之蔚然。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "蔚映", "t": "茂密而相映衬"}, {"w": "蔚生", "t": "草木茂密貌。"}]}, {"meaning": "有文采。", "cites": [{"t": "其文蔚也。", "b": "《易·革卦》"}, {"t": "蔚彼高藻。", "b": "陆机《答贾长渊诗》"}, {"t": "蔚为辞宗。", "b": "《汉书·叙传下》"}], "words": [{"w": "蔚炳", "t": "文采鲜明华美。"}]}, {"meaning": "云气弥漫的。", "cites": [{"t": "荟兮蔚兮。", "b": "《诗·曹风·侯人》。传“荟蔚,云兴貌。”"}], "words": [{"w": "蔚荟", "t": "云雾弥漫貌。"}]}, {"meaning": "盛大。", "cites": [{"t": "古陵蔚起。", "b": "《聊斋志异·促织》"}], "words": [{"w": "蔚跂", "t": "雄浑多姿。"}]}, {"meaning": "聚集。", "cites": [{"t": "六义附庸,蔚成大国。", "b": "《文心雕龙》"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "县名 ,在河北省北部,壶流河斜贯,邻接山西省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3077wx','兢','1','jīng','儿','14','','[{"pinyin": "jīng", "defs": [{"meaning": "(象形。金文字形,象二人头顶重物形。头上戴着重物,故常戒惕小心。本义:小心谨慎的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "战战兢兢,如临深渊,如履薄冰。", "b": "《诗·小雅·小旻》"}], "words": [{"w": "兢惕", "t": "小心谨慎"}, {"w": "兢持", "t": "矜持,拘束"}, {"w": "兢兢切切", "t": "兢兢业业,小心翼翼"}, {"w": "兢危", "t": "戒慎忧惧。"}]}, {"meaning": "强劲。", "cites": [{"t": "尔羊来思,矜矜兢兢,不骞不崩。", "b": "《诗·小雅·无羊》"}], "words": [{"w": "兢兢", "t": "强壮的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3078wx','模','1','mó mú','木','14','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从木,莫声。本义:铸造器物的模子)。"}, {"meaning": "同本义。", "cites": [{"t": "模,法也。", "b": "《说文》。按,水曰法,木曰模,土曰型,金曰镕,竹曰笵。"}, {"t": "缤乎其犹模绣也。", "b": "《书·大传》。注:“模所琢文章之范。”"}, {"t": "授全模于梓匠。", "b": "左思《魏都赋》"}, {"t": "古者铸器,必先用蜡为模。", "b": "赵希鹄《洞天清录》"}], "words": [{"w": "模度", "t": "标准"}, {"w": "模准", "t": "样板,规范"}, {"w": "模宪", "t": "法则。"}]}, {"meaning": "楷式,榜样。特指值得学习的先进人物。", "cites": [{"t": "可为达士模。", "b": "左思《咏史》诗"}], "words": [{"w": "劳模;评模;模楷", "t": "模范,榜样"}, {"w": "模则", "t": "楷模,准则"}, {"w": "模表", "t": "模范,表率"}, {"w": "模范", "t": "榜样,表率。"}]}, {"meaning": "仿效,效法。", "cites": [{"t": "彻书之金简,以身模之焉。", "b": "班固《汉武帝内传》"}], "words": [{"w": "模次", "t": "逐字仿效"}, {"w": "模效", "t": "模仿效法"}, {"w": "模放", "t": "模仿"}, {"w": "模则", "t": "效法"}, {"w": "模造", "t": "依样制造,塑造。"}]}, {"meaning": "照原件描画,临摹。", "cites": [{"t": "善隶书,特工模写。", "b": "《北史》"}], "words": [{"w": "模拓", "t": "把金石等器物上的图画、文字照原样印下来"}, {"w": "模刻", "t": "照原样摹写雕刻"}, {"w": "模象", "t": "描绘形容"}, {"w": "模画", "t": "照事物原貌描画"}, {"w": "模碑", "t": "摹刻有图文的石碑"}, {"w": "模传", "t": "模拓而传播"}, {"w": "模样", "t": "描摹形状情态"}, {"w": "模写", "t": "照原样描绘"}, {"w": "模帖", "t": "照帖摹写"}, {"w": "模山范水", "t": "用文字或图画描绘山水景物。"}]}]}, {"pinyin": "mú", "defs": [{"meaning": "", "words": [{"w": "字模;铜模", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3079wx','槛','1','jiàn kǎn','木','14','','[{"pinyin": "jiàn", "defs": [{"meaning": "槛车;囚车。", "cites": [{"t": "槛,栊也。从木,监声。所以囚罪人之牢也。故囚车曰槛车。", "b": "《说文》"}, {"t": "槛,牢也。今监狱字以监为之。", "b": "《广雅》"}, {"t": "槛,车上施栏,以格猛兽,亦囚禁罪人之车也。", "b": "《释名·释车》"}, {"t": "中尚书宦官槛塞大异。", "b": "《汉书·谷永传》"}, {"t": "乃槛车与王诣长安。", "b": "《汉书·陈馀传》。师古曰:“槛车者,车而为槛形,谓以板四周之,无所通也。”"}], "words": [{"w": "槛车", "t": "四周设有栅栏的车。用以囚禁犯人或装载猛兽"}, {"w": "槛送", "t": "用囚车押送"}, {"w": "槛槛", "t": "车子行进时发出的声音。"}]}, {"meaning": "关牲畜野兽的栅栏。", "cites": [{"t": "一曰圈也。谓所以閑兽。", "b": "《说文》"}], "words": [{"w": "槛羊", "t": "栅栏中的羊"}, {"w": "槛緤", "t": "拴兽的绳索"}, {"w": "槛兽", "t": "笼中之兽。喻失去自由者。"}]}, {"meaning": "栏杆的纵木。", "cites": [{"t": "云攀殿槛。", "b": "《汉书·朱云传》"}]}, {"meaning": "栏杆的横木。", "cites": [{"t": "坐堂伏槛,临曲池些。", "b": "《楚辞·招魂》"}]}, {"meaning": "泛指栏杆。", "cites": [{"t": "阁中帝子今何在?槛外长江空自流。", "b": "王勃《滕王阁序》"}], "words": [{"w": "槛屋", "t": "围有栏杆的房子"}, {"w": "槛窗", "t": "有横直图案的格子窗"}, {"w": "槛花笼鹤", "t": "栏杆里面的花、笼中的鸟。比喻受约束者。"}]}, {"meaning": "捕捉野兽的机具。", "cites": [{"t": "毁坏槛宑。", "b": "《后汉书·法雄传》"}], "words": [{"w": "槛阱", "t": "捕捉野兽的机具和陷坑。"}]}, {"meaning": "四方加板的船。"}, {"meaning": "浴盆。", "cites": [{"t": "同槛而浴。", "b": "《庄子·则阳》"}]}, {"meaning": "以槛车关、载。", "cites": [{"t": "槛送京师。", "b": "《新唐书》"}]}, {"meaning": "禁闭;拘囚。", "cites": [{"t": "群王被囚槛之困,妃主有离绝之哀。", "b": "《晋书》"}]}]}, {"pinyin": "kǎn", "defs": [{"meaning": "", "words": [{"w": "槛外人", "t": "槛:门坎。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3080wx','榴','1','liú','木','14','','[{"pinyin": "liú", "defs": [{"meaning": "(形声。从木,留声。本义:木名。即“石榴”)。"}, {"meaning": "同本义 。一种落叶灌木,开红花,果实球状,内有很多种子,种子上的肉可吃,根和皮可做驱虫药。种子为汉·张骞出使西域时自安石国带回,故名“安石榴”,后略称“石榴”,也简称“榴”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3081wx','榜','1','bǎng bàng','木','14','','[{"pinyin": "bǎng", "defs": [{"meaning": "木片。", "cites": [{"t": "载米三十万斛,钱布数十舫,竖榜为城。", "b": "《资治通鉴》"}]}, {"meaning": "匾额。", "cites": [{"t": "魏时,凌云殿榜未题而匠者误钉之。", "b": "《晋书·王献之传》"}], "words": [{"w": "榜题", "t": "匾额题字"}, {"w": "榜字", "t": "写在匾额上的大字。"}]}, {"meaning": "告示应试取录的名单。", "cites": [{"t": "既而试榜出,时所推誉洞房花烛夜,金榜挂名时。", "b": "汪洙《喜》"}, {"t": "皆不在榜。", "b": "《宋史·选举志》"}], "words": [{"w": "放榜,榜上无名", "t": ""}]}, {"meaning": "公开张贴的名单、文书、告示。", "cites": [{"t": "鲁达看见众人看榜。", "b": "《水浒全传》"}], "words": [{"w": "光荣榜;榜示", "t": "文告,告示。"}]}, {"meaning": "屋栋。", "cites": [{"t": "屋栋谓之甍。注:“今谓之榑,亦谓之檩,又谓之榜。”", "b": "《营造法式》"}]}, {"meaning": "公开张贴文书、告示。", "cites": [{"t": "昨日里胥方到门,手持尺牒榜乡村。", "b": "白居易《新乐府·杜陵叟》"}], "words": [{"w": "榜谕", "t": "发榜下告"}, {"w": "榜募", "t": "张榜招募。"}]}, {"meaning": "题署。", "cites": [{"t": "而州之僧舍无所谓藏经者,独榜其所居室,曰“思无邪斋”。", "b": "宋·苏轼《虔州崇庆禅院新经藏记》"}]}]}, {"pinyin": "bàng", "defs": [{"meaning": "船桨。", "cites": [{"t": "齐吴榜以击汰。", "b": "《楚辞·涉江》。”"}]}, {"meaning": "船。", "cites": [{"t": "榜,船也。", "b": "《广雅》"}, {"t": "催榜渡乌江。", "b": "李贺《歌诗篇》"}]}, {"meaning": "摇船,划船。", "cites": [{"t": "榜人奏采菱之歌。", "b": "张协《七命》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3082wx','榨','1','zhà','木','14','','[{"pinyin": "zhà", "defs": [{"meaning": "压出物体里汁液的器具。", "cites": [{"t": "榨,打油具也。", "b": "《广韵》"}], "words": [{"w": "榨斗", "t": "榨取蔗糖的器具之一"}, {"w": "榨床", "t": "榨糖、榨油等器具的底座"}, {"w": "榨盘", "t": "榨的部件之一。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3083wx','榕','1','róng','木','14','','[{"pinyin": "róng", "defs": [{"meaning": "一种常绿乔木 ,树干分枝多,枝上又长出许多气生根,其向下长入土中形成一支柱,树冠大,叶互生,椭圆形或卵形,花黄色或淡红色,果实倒卵形,黄色或赤褐色。", "cites": [{"t": "榕,木名。", "b": "《玉篇》"}]}, {"meaning": "福建省福州市的别称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3084wx','歌','1','gē','欠','14','','[{"pinyin": "gē", "defs": [{"meaning": "(形声。从欠,哥声。从“欠”,表示与口有关系。本义:唱)。"}, {"meaning": "同本义。", "cites": [{"t": "歌,咏也。", "b": "《说文》"}, {"t": "歌者,长引其声以诵之也。", "b": "《说文系传》"}, {"t": "不鼓缶而歌。", "b": "《易·离》"}, {"t": "歌永言。", "b": "《虞书》"}, {"t": "歌咏其声也,长言也。", "b": "《礼记·乐记》"}, {"t": "曲合乐曰歌,徒歌曰谣。", "b": "《诗·魏风·园有桃》传"}, {"t": "昔者,舜鼓五弦,歌《南风》之诗而天下治。", "b": "《韩非子·外储说左上》"}, {"t": "楚狂接舆歌而过孔子", "b": "《论语·微子》"}, {"t": "乃歌夫“长铗归来”者也。", "b": "《战国策·齐策》"}, {"t": "如优孟摇头而歌,而后可以得志。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "对歌", "t": "一问一答地唱歌"}, {"w": "高歌", "t": "放声歌唱"}, {"w": "歌吹", "t": "歌唱,吹奏"}, {"w": "歌鼓", "t": "歌唱并击鼓"}, {"w": "歌戏", "t": "歌唱嬉戏。"}]}, {"meaning": "歌颂,赞美。", "cites": [{"t": "故近者歌讴而乐之,远者竟竭蹶而趋之。", "b": "《荀子·儒效》"}, {"t": "诗人歌功。", "b": "扬雄《赵充国颂》"}], "words": [{"w": "歌功", "t": "颂扬他人的功德"}, {"w": "歌思", "t": "歌颂思慕"}, {"w": "歌叹", "t": "歌颂赞叹。"}]}, {"meaning": "奏乐;伴奏。", "cites": [{"t": "歌于斯,哭于斯。", "b": "《礼记》"}, {"t": "往往会倚嫔御歌,必为奇巧声动上,由是得幸。", "b": "宋·王谠《唐语林·雅量》"}]}, {"meaning": "又指。", "cites": [{"t": "鸟歌花舞太守醉,明日酒醒春已归。", "b": "宋·欧阳修《丰乐亭游春三首》"}]}, {"meaning": "作歌;作诗。", "cites": [{"t": "夫也不良,歌以讯止。", "b": "《诗·陈风·墓门》"}, {"t": "因为长句,歌以赠之,凡六百一十六言,命曰《琵琶行》。", "b": "唐·白居易《琵琶行(并序)》"}]}, {"meaning": "歌曲;歌词。", "cites": [{"t": "诗言志,歌永言。", "b": "《书·舜典》"}, {"t": "岂无山歌与村笛,呕哑嘲哳难为听。", "b": "白居易《琵琶行》"}], "words": [{"w": "校歌;民歌;国歌;歌头曲尾", "t": "诗歌和散曲联唱的一种歌曲形式"}, {"w": "歌味", "t": "歌曲的风味"}, {"w": "歌儿", "t": "歌曲"}, {"w": "歌章", "t": "歌曲。音乐一曲为一章,故称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3085wx','遭','1','zāo','辶','14','','[{"pinyin": "zāo", "defs": [{"meaning": "(形声。从辵(chuò),曹声。本义:遇见,碰到)。"}, {"meaning": "同本义(多指碰到不幸的事)。", "cites": [{"t": "遭,遇也。", "b": "《说文》"}, {"t": "遭先生于道。", "b": "《礼记·曲礼》。疏:“逢也。”"}, {"t": "未既龀而遭之。", "b": "《国语·郑语》。注:“遇也。”"}, {"t": "遭圣则兴。", "b": "《史记·孝武纪》"}, {"t": "故遭罹而嬴缩。", "b": "班固《幽通赋》"}, {"t": "晏子出,遭之途。", "b": "《史记·管晏列传》"}, {"t": "予在患难中,间以诗记所遭。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "遭伤", "t": "遇死;被害"}, {"w": "遭变", "t": "遇到变故"}, {"w": "遭坏", "t": "遇到山崖或墙壁等的崩塌"}, {"w": "遭险", "t": "遇到危险。"}]}, {"meaning": "受到;遭受。", "cites": [{"t": "轩凡四遭火。", "b": "明·归有光《项脊轩志》"}, {"t": "遭风雨霜露。", "b": "清·洪亮吉《治平篇》"}, {"t": "遭水旱疾疫。", "b": ""}, {"t": "猛虎凭其威,往往遭急缚。", "b": "杜甫《遣兴》"}], "words": [{"w": "遭声气", "t": "遭受舆论谴责"}, {"w": "遭愆", "t": "遭殃;倒霉"}, {"w": "遭了毒手;遭诛", "t": "被杀"}, {"w": "遭谗", "t": "受到谗害"}, {"w": "遭谤", "t": "受到诽谤。"}]}, {"meaning": "际遇,人生中的好运或坏运气。", "cites": [{"t": "书于石,所以贺兹丘之遭也。", "b": "唐·柳宗元文"}, {"t": "遭遁;遭随(遭命和随命的合称)", "b": ""}]}, {"meaning": "次,回。", "cites": [{"t": "虚绕千万遭。", "b": "孟郊《寒地百姓吟》"}], "words": [{"w": "遭把", "t": "一两次;个把次"}, {"w": "在这么多人面前讲话,我还是头一遭", "t": ""}]}, {"meaning": "一圈,一场。", "cites": [{"t": "何不着他委纸领状送去走一遭,不致失误!", "b": "《水浒传》"}], "words": [{"w": "多绕几遭", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3086wx','酵','1','jiào','酉','14','','[{"pinyin": "jiào", "defs": [{"meaning": "(形声。从酉(yǒu),表示与酒有关,孝声。本义:酒母)。"}, {"meaning": "酒滓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3087wx','酷','1','kù','酉','14','','[{"pinyin": "kù", "defs": [{"meaning": "(形声。从酉(yǒu),表示与酒有关,告声。本义:酒味浓;香气浓)。"}, {"meaning": "同本义。", "cites": [{"t": "[酒]酷烈馨香。", "b": "曹植《七启》"}, {"t": "芬芳沤郁,酷烈淑郁。", "b": "司马相如《上林赋》"}]}, {"meaning": "残暴;苛刻。", "cites": [{"t": "课额日以增,官吏日以酷。", "b": "王冕《伤亭户》"}, {"t": "刑罚暴酷,轻绝人命。", "b": "晁错《举贤良对策》"}, {"t": "妃性酷虐,常手镣数人。", "b": "《晋书·贾皇后传》"}], "words": [{"w": "酷滥", "t": "滥用残酷的刑罚"}, {"w": "酷评", "t": "苛刻的评论"}, {"w": "酷惨", "t": "残暴,惨酷"}, {"w": "酷偿", "t": "残酷报复"}, {"w": "酷能", "t": "以严刑酷法为能"}, {"w": "酷吏", "t": "滥用刑法残害人民的官吏。"}]}, {"meaning": "悲惨;痛苦。", "cites": [{"t": "吴人仿子胥之冤酷,皆为立祠。", "b": "《三国志》"}], "words": [{"w": "酷杀", "t": "惨死"}, {"w": "酷裂", "t": "因痛苦而肠断"}, {"w": "酷楚", "t": "痛楚。"}]}, {"meaning": "极,非常。", "cites": [{"t": "酷似其舅。", "b": "《晋书·何无忌传》"}], "words": [{"w": "酷尚", "t": "特别喜好"}, {"w": "酷类", "t": "即酷似,非常相似"}, {"w": "酷痛", "t": "极悲痛"}, {"w": "酷贫", "t": "极其贫困"}, {"w": "酷薄", "t": "极端刻薄。"}]}, {"meaning": "惨痛,痛恨。", "cites": [{"t": "含酷茹恨,彻于心髓。", "b": "《颜氏家训·文章》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3088wx','酿','1','niàng','酉','14','','[{"pinyin": "niàng", "defs": [{"meaning": "(形声。从酉(yǒu),襄声。本义:做酒,酿造)。"}, {"meaning": "同本义。原专指酿酒,后也指利用发酵作用酿造蜜、醋、酱等。", "cites": [{"t": "酿,醖也。作酒曰酿。", "b": "《说文》"}, {"t": "米麦所作曰酿。", "b": "《三苍》"}, {"t": "黑黍舂来酿酒饮。", "b": "唐·曹邺《田家效陶》"}, {"t": "酿泉为酒。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "酝酿", "t": "造酒的发酵过程"}, {"w": "酿米", "t": "酿酒的米"}, {"w": "酿具", "t": "酿酒的器具"}, {"w": "酿秫", "t": "用秫黍酿酒"}, {"w": "酿制", "t": "酿造"}, {"w": "酿糯", "t": "以糯米酿酒。"}]}, {"meaning": "酝酿,逐渐形成。", "cites": [{"t": "早难道救冤反把冤酿。", "b": "朱寉《十五贯、廉访》"}], "words": [{"w": "酿雪", "t": "空中水蒸气逐渐凝聚而形成为雪"}, {"w": "酿寒", "t": "逐渐酿成寒冷的天气"}, {"w": "酿祸", "t": "酿成祸患"}, {"w": "酿乱", "t": "酿成祸乱。"}]}, {"meaning": "娇宠。", "cites": [{"t": "素日皆是你们这些人把他酿坏了,到这步田地还来解劝", "b": "《红楼梦》"}]}, {"meaning": "酒。", "cites": [{"t": "伶人倾家酿。", "b": "《晋书·何充传》"}], "words": [{"w": "佳酿", "t": "好酒"}, {"w": "酿肆", "t": "酒坊;酒店。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3089wx','酸','1','suān','酉','14','','[{"pinyin": "suān", "defs": [{"meaning": "(形声。从酉(yǒu),“酉”是汉字部首之一。从“酉”,与酒、酪等有关。本义:醋)。"}, {"meaning": "像醋一样的气味或味道。", "cites": [{"t": "杏子还没熟,太酸", "b": ""}], "words": [{"w": "酸辛", "t": "酸味和辣味"}, {"w": "酸苦", "t": "酸味和苦味"}, {"w": "酸醨", "t": "味酸而薄的酒。"}]}, {"meaning": "杂剧脚色之一,主要扮演青年文人,因此亦用作对文人的蔑称。", "cites": [{"t": "“孤”谓官;“酸”谓秀士。凡称“酸”,谓正末扮秀士当场也。", "b": "清·焦循《剧说》"}]}, {"meaning": "酸类物质名 。能与碱反应生成盐的一种化合物(如盐酸、硫酸或苯甲酸);如溶于水,则其水溶液呈酸味,能使石蕊试纸变红,与某些金属(如铁,锌,锡)反应放出氢气;一种含氢化合物(HX),在水溶液中产生水合氢离子(如H3O+)和阴离子X-,强酸(如硝酸、盐酸或三氯醋酸)的稀溶液电离程度基本完全,弱酸(如醋酸或苯甲酸)的电离度可能只有百分之一,极弱的酸(如氢氰酸或硼酸)的电离度远小于百分之一。"}, {"meaning": "寒酸;迂腐。形容读书人的贫寒。", "cites": [{"t": "要当啖公八百里,豪气一洗儒生酸。", "b": "宋·苏轼《约公择饮是日大风》"}, {"t": "来回顾影,文魔秀士,风欠酸丁。", "b": "元·王实甫《西厢记》"}], "words": [{"w": "酸丁", "t": "对贫寒的读书人的贬称"}, {"w": "酸子", "t": "对文人、书生的蔑称"}, {"w": "酸款", "t": "装模作样地款待人"}, {"w": "酸论", "t": "陈腐的论调"}, {"w": "酸文假醋", "t": "假斯文"}, {"w": "酸黄韭烂豆腐", "t": "讥笑读书人的话"}, {"w": "酸寒", "t": "形容穷读书人的生活言行窘困的样子"}, {"w": "酸士", "t": "酸丁"}, {"w": "酸不溜丢", "t": "形容文人的迂腐"}, {"w": "酸迂", "t": "酸腐,迂腐。"}]}, {"meaning": "悲痛。", "cites": [{"t": "日磾观状,益增酸哽。", "b": "北齐·朱敬范《朱岱林墓志铭》"}, {"t": "对酒不能言,感慨怀酸辛。", "b": "晋·阮籍《咏怀》"}, {"t": "妻乃轻服诣(董)卓门,跪自陈情,辞甚酸怆。", "b": "《后汉书·皇甫规妻传》"}], "words": [{"w": "酸怆", "t": "哀伤悲痛"}, {"w": "酸咽", "t": "悲伤哭泣而抽咽起来"}, {"w": "酸恨", "t": "悲痛遗憾"}, {"w": "酸伤", "t": "伤心。"}]}, {"meaning": "因男女关系而引起的嫉妒。", "cites": [{"t": "苦尤娘赚入大观园,酸凤姐大闹宁国府。", "b": "《红楼梦》"}], "words": [{"w": "酸风", "t": "比喻醋意"}, {"w": "酸眉苦脸", "t": "形容又嫉妒又苦恼的神色。"}]}, {"meaning": "酸痛,因疾病或疲劳引起的筋肉微痛而无力的感觉。", "cites": [{"t": "山高谷深,不觉脚酸。", "b": "《乐府诗集·陇头流水歌辞》"}, {"t": "四肢酸重。", "b": "《晋书·皇甫谧传》"}], "words": [{"w": "酸哀", "t": "酸痛无力。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3090wx','碟','1','dié','石','14','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从石,枼(yè)声。本义:盛食品的小盘) 同本义 。如:碗碟;碟酌(酒菜;酒席);碟大碗小,磕着碰着了(比喻人多事杂,容易发生摩擦)。又:用作量词。如:一碟瓜子。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3091wx','碱','1','jiǎn','石','14','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(“碱”为“鹼”的俗字。“鹼”已简化为硷。而礆、鹻、堿、鹹、礆为过去俗用过的杂字)。"}, {"meaning": "盐鹵。", "cites": [{"t": "鹹,北方味也。从鹵,咸声。", "b": "《说文》"}, {"t": "润下作鹹。", "b": "《书·洪范》"}, {"t": "以鹹养脉。", "b": "《周礼·疡医》"}, {"t": "在味为鹹。", "b": "《素问·阳阴应象大论》"}, {"t": "鹹音有二:音咸者,润下之味;音减者,盐土之名。后人作鹼、作鹻,是矣。", "b": "《本草纲目》"}]}, {"meaning": "含氢氧根的化合物的统称。今作“碱”。又专指纯碱。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3092wx','碳','1','tàn','石','14','','[{"pinyin": "tàn", "defs": [{"meaning": "一种主要呈四价的非金属元素,存在于自然界中(如以金刚石和石墨形式),是煤、石油、沥青、石灰石和其他碳酸盐以及一切有机化合物的成分 ——元素符号C。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3093wx','磁','1','cí','石','14','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从石,兹声。本义:磁石。也指磁性)。"}, {"meaning": "地名 。治所在今河北省磁县。辖境相当今河北省邯郸、磁县、武安等市、县地。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3094wx','愿','1','yuàn','心','14','','[{"pinyin": "yuàn", "defs": [{"meaning": "(形声。从页(xié),原声。古时“愿、願”各有本义。“愿”义为谨慎,“願”义为“大头”) 谨慎;老实,质朴。", "cites": [{"t": "愿,谨也。", "b": "《说文》"}, {"t": "思厚不爽曰愿。", "b": "《周书·谥法》"}, {"t": "无利于上谓之愿。", "b": "《韩非子·诡使》"}, {"t": "愿而恭。", "b": "《书·皋谟》。郑注:“谓容貌恭正。”"}, {"t": "则莫能以愿中。", "b": "《考工记·弓人》"}, {"t": "上愿纠暴。", "b": "《周礼·大司寇》"}, {"t": "大府召视儿,幼愿耳。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "愿恭", "t": "恭谨"}, {"w": "愿款", "t": "诚挚"}, {"w": "愿法", "t": "执法恭谨"}, {"w": "愿敏", "t": "朴实敏悟"}, {"w": "愿婉", "t": "朴实恭顺"}, {"w": "愿懿", "t": "朴实诚实"}, {"w": "愿民", "t": "朴实善良之民。"}]}, {"meaning": "大头。", "cites": [{"t": "願,大头也。从頁,原声。宋公孙願绎字硕父。", "b": "《说文》"}]}, {"meaning": "假借为“愿”。愿心,旧时祈祷神佛所许下的酬谢。", "cites": [{"t": "言願以为质。", "b": "《大戴礼记·官人》"}, {"t": "众僧祝愿。", "b": "《晋书》"}], "words": [{"w": "愿力", "t": "佛家语。指誓愿的力量"}, {"w": "愿行", "t": "佛家语。誓愿与修行"}, {"w": "愿谓", "t": "向神佛祈求并说出自己的意愿。"}]}, {"meaning": "心愿;愿望。", "cites": [{"t": "果不如先愿。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "富贵非吾愿,帝乡不可期。", "b": "晋·陶潜《归去来兮辞》"}, {"t": "又乖恳愿。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "情愿。", "cites": [{"t": "愿为市鞍马,从此替爷征。", "b": "《木兰诗》"}, {"t": "管仲曾西之所不为也,而子为我愿之乎?", "b": "《孟子》"}], "words": [{"w": "愿蠲顶踵", "t": "愿意舍身"}, {"w": "心甘情愿;愿与人民共患难", "t": ""}]}, {"meaning": "希望。", "cites": [{"t": "愿伯具言臣之不敢倍德也。", "b": "《史记·项羽本纪》"}, {"t": "孝成王使括…为将,括母…愿勿遣。(愿勿遣,希望不要派遣赵括为将。)", "b": "汉·刘向《列女传》"}, {"t": "愿以闻于官。(希望把这件事报告官府。闻,使上级听见,报告上级。)", "b": "唐·柳宗元《童区寄传》"}, {"t": "愿天下有情人都成眷属。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "愿你快乐;愿那位最好的人取胜", "t": ""}]}, {"meaning": "仰慕。", "cites": [{"t": "名声日闻,天下愿。", "b": "《荀子·王制》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3095wx','需','1','xū','雨','14','','[{"pinyin": "xū", "defs": [{"meaning": "(会意。从雨而声。“需”指遇雨,停在那里等待。本义:等待)。"}, {"meaning": "同本义。", "cites": [{"t": "需,须也。", "b": "《易·需》。传:“需者,待也。”"}, {"t": "聂许闻之需役。", "b": "《庄子·大宗师》"}, {"t": "九江需次今几年,去去渌水依红莲。", "b": "宋·楼钥《送袁恭安赴江州节推》"}, {"t": "略举数端,以需善择。", "b": "清·包世臣《文谱》"}], "words": [{"w": "需次", "t": "候补官员依照资历补缺"}, {"w": "需铨", "t": "等待铨选录用。"}]}, {"meaning": "需要。", "cites": [{"t": "零星需用亦在账房内开销。", "b": "《红楼梦》"}], "words": [{"w": "按需分配;必需;需用", "t": "需要的用度。"}]}, {"meaning": "索取。", "cites": [{"t": "只为前日毛延寿,指写丹青,遍需金帛。", "b": "明·陈玉阳《昭君出塞》"}, {"t": "需,索也。", "b": "《古今韵会举要》"}], "words": [{"w": "需勒", "t": "勒索。"}]}, {"meaning": "迟疑;观望。", "cites": [{"t": "率故多尤,需为事贼。", "b": "《文心雕龙》"}], "words": [{"w": "需缓", "t": "迟缓"}, {"w": "需滞", "t": "授职后迟迟不能赴任。"}]}, {"meaning": "应该;必然。", "cites": [{"t": "儒者本无所谓教,达而在上,穷而在下,需不能出此范围。", "b": "清·王韬《原道》"}], "words": [{"w": "需要", "t": ""}]}, {"meaning": "需用的东西。", "cites": [{"t": "与民均纳供需。", "b": "《元史·成宗纪二》"}], "words": [{"w": "军需", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3096wx','辖','1','xiá','车','14','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从车,害声。本义:大车轴头上穿着的小铁棍,可以管住轮子使不脱落)。"}, {"meaning": "同本义。", "cites": [{"t": "辖,键也。", "b": "《说文》"}, {"t": "巾车脂辖。", "b": "《左传·哀公三年》"}, {"t": "轴折鲜联辖。", "b": "韩愈等《征蜀联句》"}]}, {"meaning": "侍卫。", "cites": [{"t": "当了个难的乾清门辖,好容易升了个等儿。", "b": "《儿女英雄传》"}]}, {"meaning": "管辖。", "cites": [{"t": "郯城系沂州辖邑。", "b": "清·黄元鸿《福惠全书》"}], "words": [{"w": "辖押", "t": "管辖看押"}, {"w": "辖下", "t": "统辖之下"}, {"w": "省辖市;直辖", "t": "直接管辖。"}]}, {"meaning": "卡,夹。", "cites": [{"t": "为左右所辖,进退不得。", "b": "《太平广记》"}], "words": [{"w": "辖床", "t": "匣床"}, {"w": "辖手", "t": "夹手。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3097wx','辗','1','niǎn zhǎn','车','14','','[{"pinyin": "niǎn", "defs": [{"meaning": "磙压;碾压。", "cites": [{"t": "夜来城外一尺雪,晓驾炭车辗冰辙。", "b": "唐·白居易《卖炭翁》"}]}]}, {"pinyin": "zhǎn", "defs": [{"meaning": "辗转,也作“展转”。", "cites": [{"t": "悠哉悠哉,辗转反侧。", "b": "《诗·周南·关雎》。郑玄笺:“卧而不周曰辗。”"}]}, {"meaning": "转;回转。", "cites": [{"t": "俯窥辗顾,步步生奇。", "b": "《徐霞客游记》"}], "words": [{"w": "辗动", "t": "转动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3098wx','雌','1','cí','隹','14','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从隹(zhuī),此声。从“隹”,表示与鸟有关。本义:母鸟。引申为母的)。"}, {"meaning": "母鸟,能产卵的鸟。", "cites": [{"t": "听凤皇之鸣,以别十二律,其雄鸣为六,雌鸣亦六。", "b": "《吕氏春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3099wx','裳','1','cháng shang','衣','14','','[{"pinyin": "cháng", "defs": [{"meaning": "(形声。从衣,尚声。本义:下衣)。"}, {"meaning": "古人穿的遮蔽下体的衣裙,男女都穿,是裙的一种,不是裤子。", "cites": [{"t": "裳下饰也。", "b": "《左传·昭公十二年》"}, {"t": "黄裳元吉。", "b": "《易·坤》"}, {"t": "绿兮衣兮,绿衣黄裳。", "b": "《诗·邶风·绿衣》"}, {"t": "制芰荷 以为衣兮,集芙蓉以为裳。", "b": "《楚辞·离骚》"}, {"t": "整顿衣裳起敛容。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "裳衣", "t": "裳与衣。泛指衣服"}, {"w": "裳服", "t": "衣服"}, {"w": "裳裾", "t": "衣襟。"}]}, {"meaning": "泛指衣服。", "cites": [{"t": "脱我战时袍,著我旧时裳。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "裳袂", "t": "衣袖"}, {"w": "裳裙", "t": "衣襟。"}]}]}, {"pinyin": "shang", "defs": [{"meaning": "——用于“衣裳”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3100wx','颗','1','kē','页','14','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从页(xié),果声。从“页”,表示与头有关。(kě) 本义:小头) 引申指颗粒状物。", "cites": [{"t": "颗,小头也。", "b": "《说文》"}, {"t": "翠叶轻拢豆颗匀。", "b": "元好问《未开海棠》"}], "words": [{"w": "颗盐", "t": "俗称“粒盐”。一种粗盐"}, {"w": "颗子", "t": "方言。指小米。"}]}, {"meaning": "多用于圆形或粒状物。", "cites": [{"t": "北土通呼物一凷改为一颗。", "b": "《颜氏家训》。按,如米粒珠子皆是。"}], "words": [{"w": "三颗黄豆;两颗绿豆", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3101wx','瞅','1','chǒu','目','14','','[{"pinyin": "chǒu", "defs": [{"meaning": "[方言] 看;望", "words": [{"w": "瞅瞅", "t": "看望与关怀"}, {"w": "瞅了一眼;瞅见", "t": "看见"}, {"w": "瞅空", "t": "看机会，找闲空"}, {"w": "瞅睬", "t": "答理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3102wx','墅','1','shù','土','14','','[{"pinyin": "shù", "defs": [{"meaning": "田庐;村舍。田间土舍。", "cites": [{"t": "剧哉边海民,寄身于草墅。", "b": "曹植《泰山梁甫行》"}]}, {"meaning": "别馆;在本宅之外营建的田庄园林。", "cites": [{"t": "又于土山营墅,楼馆竹林甚盛。", "b": "《晋书·谢安传》"}], "words": [{"w": "别墅", "t": "在郊区或风景区供游玩休养的园林房屋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3103wx','嗽','1','sòu','口','14','','[{"pinyin": "sòu", "defs": [{"meaning": "(形声。从口,欶(shuò)声。本义:咳嗽) 同本义。", "cites": [{"t": "嗽,咳嗽。", "b": "《玉篇》"}, {"t": "冬季有嗽,上气疾。", "b": "《周礼》"}, {"t": "他干嗽了几声", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3104wx','踊','1','yǒng','足','14','','[{"pinyin": "yǒng", "defs": [{"meaning": "(形声。从足,勇声。从足,表示脚的动作行为。本义:往上跳)。"}, {"meaning": "同本义。", "cites": [{"t": "踊,跳也。", "b": "《说文》"}, {"t": "踊,上也。", "b": "《广雅》"}, {"t": "曲踊三百。", "b": "《左传·僖公二十八年》"}, {"t": "三踊于幕庭。", "b": "《左传·哀公八年》"}, {"t": "踊于柸而窥客。", "b": "《公羊传·成公二年》"}, {"t": "跛者不踊。", "b": "《礼记·丧服四制》"}], "words": [{"w": "踊骇", "t": "惊扰跳跃"}, {"w": "踊跳", "t": "跳跃"}, {"w": "踊身", "t": "纵身。"}]}, {"meaning": "登,登上。", "cites": [{"t": "景公为路寝之台,成,而不踊焉。", "b": "《晏子春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3105wx','蜻','1','qīng','虫','14','','[{"pinyin": "qīng", "defs": [{"meaning": "蜻蜓。", "cites": [{"t": "海上之人有好蜻者,每居海上,从蜻游,蜻之至者有百数而不止,前后左右尽蜻也。", "b": "《吕氏春秋·精谕》"}], "words": [{"w": "蜻蜓撼石柱", "t": "比喻力量小却想动摇大东西,不自量力"}, {"w": "蜻蜓吃尾巴", "t": "比喻自己吃自己。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3106wx','蜡','1','là zhà','虫','14','','[{"pinyin": "là", "defs": [{"meaning": "动物、矿物或植物所产生的油质,具有可塑性,能燃能熔,不溶于水,是一羟基醇或固醇的脂肪酸酯。", "cites": [{"t": "蜡烛有心还惜别,替人垂泪到天明。", "b": "杜牧《赠别》"}], "words": [{"w": "蜡圆", "t": "蜡丸"}, {"w": "蜡弹", "t": "蜡丸,用蜡封裹的密件"}, {"w": "蜡查(蜡埚,蜡滓白蜡(虫蜡)或黄蜡(蜂蜡)的渣滓)", "t": ""}]}, {"meaning": "蜡烛的简称。", "cites": [{"t": "蜡炬成灰泪始干。", "b": "李商隐《无题》"}], "words": [{"w": "蜡火", "t": "蜡烛火"}, {"w": "蜡烟", "t": "蜡烛的烟"}, {"w": "蜡红", "t": "烛花"}, {"w": "蜡香", "t": "蜡烛燃点时产生的气味"}, {"w": "蜡光", "t": "烛光。"}]}]}, {"pinyin": "zhà", "defs": [{"meaning": "古代祭名。周朝年终大祭万物。", "cites": [{"t": "天子大蜡八。", "b": "《礼记·郊特性》"}], "words": [{"w": "蜡腊", "t": "岁终祭祀"}, {"w": "蜡坛", "t": "蜡祭之坛"}, {"w": "蜡宾", "t": "年终祭祀的助祭人"}, {"w": "蜡索", "t": "犹蜡祭"}, {"w": "蜡祠", "t": "蜡祭用的祠堂"}, {"w": "蜡宫", "t": "供蜡祭用的宫室"}, {"w": "蜡月", "t": "指周历十二月"}, {"w": "蜡日", "t": "年终蜡祭八神之日"}, {"w": "蜡祭", "t": "祭名。年终合祭万物之神。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3107wx','蝇','1','yíng','虫','14','','[{"pinyin": "yíng", "defs": [{"meaning": "多指苍蝇。动物名。属昆虫类中的双翅类。", "cites": [{"t": "上无枝上蜩,下无盘中蝇。", "b": "唐·韩愈《秋怀诗》"}], "words": [{"w": "蝇头小楷", "t": "非常小的正楷毛笔字"}, {"w": "蝇头细批", "t": "用小字密密批注"}, {"w": "蝇附狗偷", "t": "比喻依附低俗下作的行径"}, {"w": "蝇营", "t": "如蝇到处营钻。比喻赢小利而不休"}, {"w": "蝇名蜗利", "t": "苍蝇头般的微名,蜗牛角样的小利。比喻微不足道的名利"}, {"w": "蝇利", "t": "比喻微小的利益"}, {"w": "蝇头小字", "t": "指极小的字"}, {"w": "蝇声蛙噪", "t": "苍蝇、青蛙无休止地叫。比喻低劣的、无病呻呤的诗文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3108wx','蜘','1','zhī','虫','14','','[{"pinyin": "zhī", "defs": [{"meaning": "节肢动物，身体圆形或长圆形，分头胸和腹两部，有触须和脚四对。肛门分泌的黏液凝成细丝，用来结网捕食昆虫。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3109wx','蝉','1','chán','虫','14','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从虫,单声。本义:一种昆虫。也称“知了”)。"}, {"meaning": "同本义。节肢动物门,昆虫纲,同翅目,蝉科,蝉属。", "cites": [{"t": "蝉,以旁鸣者。", "b": "《说文》。按,尔雅谓之蜩,今苏俗谓之知了。"}, {"t": "寒蝉鸣。", "b": "《礼记·夏小正》"}, {"t": "清风半夜鸣蝉。", "b": "宋·辛弃疾《西江月》"}], "words": [{"w": "寒蝉", "t": "秋天天冷时的蝉。"}]}, {"meaning": "连续不断。", "cites": [{"t": "蝉联陵丘。", "b": "左思《吴都赋》。注:“不绝貌。”"}], "words": [{"w": "蝉联", "t": "连续不断"}, {"w": "婵嫣", "t": "连属,连绵不断。"}]}]}]','jingmo-wenyan');
