INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3112wx','赚','1','zhuàn zuàn','贝','14','','[{"pinyin": "zhuàn", "defs": [{"meaning": "(形声。从贝,兼声。从贝,与财富有关。本义:指买卖得盈利)。"}, {"meaning": "同本义。", "cites": [{"t": "我也许过他二十两银子,只恨他没本事赚我的钱。", "b": "《警世通言》"}], "words": [{"w": "赚手", "t": "获利"}, {"w": "赚得", "t": "获得 "}, {"w": "赚钱", "t": "获取利润"}, {"w": "赚得不少;迅速赚一笔现金;每出售一桶可赚五元钱", "t": ""}]}, {"meaning": "赢得;获得。", "cites": [{"t": "西州客,心边赚得,一味春偏。", "b": "元·刘敏中《凤凰台上忆吹箫》"}], "words": [{"w": "赚杀", "t": "赢得,博得。"}]}, {"meaning": "出错误。", "cites": [{"t": "讶,赚矣!此辟谷药也。", "b": "徐铉《稽神录拾遗》"}, {"t": "然已只在康庄大道中,决不赚入蹊曲径矣。", "b": "王阳明《传习录·答聂文蔚》"}]}, {"meaning": "耽误;错过。", "cites": [{"t": "向日我一时见不到,赚了你终身。", "b": "《醒世恒言》"}]}, {"meaning": "诳骗;欺哄。", "cites": [{"t": "吕布赚开城门,杀将进来了!", "b": "《全图绣像三国演义》"}, {"t": "当时亲见元帅命中军去赚刘豫。", "b": "《说岳全传》"}], "words": [{"w": "赚虎离山", "t": "比喻施用计谋骗对方离开其所凭借的有利位置"}, {"w": "赚铜钱", "t": "骗钱"}, {"w": "赚漏", "t": "骗取"}, {"w": "赚辞", "t": "骗人的话"}, {"w": "赚哄", "t": "欺骗"}, {"w": "赚人", "t": "欺骗人。"}]}]}, {"pinyin": "zuàn", "defs": [{"meaning": "", "words": [{"w": "赚法", "t": "骗人的手法"}, {"w": "赚杀", "t": "诳骗杀害"}, {"w": "赚啜", "t": "哄骗"}, {"w": "赚得", "t": "骗取。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3113wx','锹','1','qiāo','钅','14','','[{"pinyin": "qiāo", "defs": [{"meaning": "挖土或铲其他东西的器具。", "words": [{"w": "铁锹", "t": ""}, {"w": "锹钁", "t": "锹镢。锹和镢头"}, {"w": "锹撅", "t": "比喻逼迫、摧残他人的手段"}]}, {"meaning": "用锹挖掘。", "words": [{"w": "锹掘", "t": "比喻逼迫、摧残他人的手段"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3114wx','锻','1','duàn','钅','14','','[{"pinyin": "duàn", "defs": [{"meaning": "(形声。从金,段声。本义:打铁)。"}, {"meaning": "同本义。", "cites": [{"t": "锻,小冶也。", "b": "《说文》。按,熔铸金为冶,以金入火焠而椎之为小冶。”"}, {"t": "锻练之吏。", "b": "《后汉书·韦彪传》"}]}, {"meaning": "锤击。", "cites": [{"t": "其父谓其子曰:“取石来锻之”。", "b": "《庄子·列御寇》"}]}, {"meaning": "锻铁用的砧石。", "cites": [{"t": "涉渭为乱,取厉取锻。", "b": "《诗·大雅·公刘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3115wx','镀','1','dù','钅','14','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。从金,度声。本义:以金属附着到别的金属或物体表面)。"}, {"meaning": "利用化学、机械或电镀的方法使一种金属附着在别的金属或物体的表面上。", "cites": [{"t": "假金只用真金镀,若是真金不镀金。", "b": "唐·李绅《答章孝标》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3116wx','舞','1','wǔ','夕','14','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从舛(chuǎn),两足相背。古舞字象人执牛尾而舞之形。本义:舞蹈)。"}, {"meaning": "同本义。", "cites": [{"t": "舞,动其容也。", "b": "《礼记·乐记》"}, {"t": "乐容曰舞", "b": "蔡邕《月令章句》"}], "words": [{"w": "舞旋", "t": "旋转的舞蹈;耍弄,舞弄"}, {"w": "舞判", "t": "装扮钟馗、判官等形象的舞蹈"}, {"w": "芭蕾舞;歌舞", "t": "唱歌和舞蹈的合称"}, {"w": "舞局", "t": "舞会"}, {"w": "舞咏", "t": "舞蹈歌咏"}, {"w": "舞头", "t": "领舞者"}, {"w": "舞天", "t": "古代东方部族祭天之舞"}, {"w": "舞妓", "t": "以歌舞娱人的妓女"}, {"w": "集体舞", "t": ""}]}, {"meaning": "钟体的顶部。", "cites": [{"t": "钲上谓之舞。", "b": "《考工记·凫氏》"}]}, {"meaning": "跳舞。", "cites": [{"t": "请以剑舞。", "b": "《史记·项羽本纪》"}, {"t": "项庄拔剑舞。", "b": ""}, {"t": "项伯亦拔剑起舞。", "b": ""}, {"t": "留连戏蝶时时舞。", "b": "唐·杜甫《江畔独步寻花》"}], "words": [{"w": "舞马", "t": "令马按节拍舞蹈"}, {"w": "舞钟馗", "t": "扮作钟馗舞蹈"}, {"w": "舞跃", "t": "拜舞欢跃"}, {"w": "舞鸡", "t": "鸡鸣起舞"}, {"w": "舞裀", "t": "供舞蹈用的地毯"}, {"w": "舞象", "t": "学象舞。会舞蹈的象"}, {"w": "舞判", "t": "扮作判官或钟馗舞蹈"}, {"w": "舞抃", "t": "飞舞跃跃。"}]}, {"meaning": "玩弄。", "cites": [{"t": "舞智以御人。", "b": "《史记·张汤列传》"}], "words": [{"w": "舞旋", "t": "玩弄;折腾"}, {"w": "舞手", "t": "耍弄手段"}, {"w": "舞文弄法", "t": "玩弄文字,曲解法律"}, {"w": "舞文巧诋", "t": "玩弄文字,诋毁构陷"}, {"w": "舞弄文墨", "t": "舞文弄墨。玩弄法律条文,曲解其意。"}]}, {"meaning": "鼓舞,振奋。", "cites": [{"t": "敌存而惧,敌去而舞。", "b": "柳宗元《敌戒》"}]}, {"meaning": "弄,抚弄。", "cites": [{"t": "众邻居一齐上前,替他抹胸口,插背心,舞了半日,渐渐喘息过来,眼睛明亮,不疯了。", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3117wx','舔','1','tiǎn','舌','14','','[{"pinyin": "tiǎn", "defs": [{"meaning": "(形声。从舌,忝声。本义:以舌取食)。"}, {"meaning": "同本义 。", "words": [{"w": "舔舕", "t": "吐出舌头的样子"}, {"w": "舔粥碗;舔干净;舔邮票;舔笔", "t": ""}]}, {"meaning": "使…湿润 。", "words": [{"w": "舔舔嘴唇", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3118wx','稳','1','wěn','禾','14','','[{"pinyin": "wěn", "defs": [{"meaning": "(形声。从禾,隐省声。“禾”与粮食有关,有了粮食,心就安定了。本义:安定,平稳)。"}, {"meaning": "同本义。", "cites": [{"t": "地名破冢,真破冢而出,行人安稳,布帆无恙。", "b": "《世说新语·排调》"}], "words": [{"w": "安稳", "t": "稳当;平稳"}, {"w": "稳拍拍", "t": "稳稳当当"}, {"w": "稳惬", "t": "稳定使满意"}, {"w": "稳善", "t": "安稳美好"}, {"w": "稳脚", "t": "犹稳步"}, {"w": "稳疾", "t": "安稳而快速"}, {"w": "稳平", "t": "平稳。"}]}, {"meaning": "妥帖;稳妥。", "cites": [{"t": "还须奏过了朝廷,才为稳便。", "b": "明·罗懋登《三宝太监西洋记通俗演义》"}], "words": [{"w": "工稳", "t": "工整而妥贴"}, {"w": "稳顺", "t": "妥帖和谐"}, {"w": "稳约", "t": "稳妥而有准绳"}, {"w": "稳善", "t": "妥善。作为隐语,指打劫"}, {"w": "稳吃三注", "t": "指轻而易举地得到全部收获"}, {"w": "稳协", "t": "工稳而协调。"}]}, {"meaning": "蹂谷聚。即蹂践聚集的谷粒,使谷壳和米分开。", "cites": [{"t": "稳,持谷聚。", "b": "《广韵》。按:周祖谟校勘记:“持”为“治”。民国《续修盐城县志》:“稻秕稃聚者谓之稳。《玉篇》‘稳’字训‘蹂谷聚’。今谓稻中秕稃扬之使聚者曰稳子,又曰偃子。”"}]}, {"meaning": "诱使人暂缓行动。", "cites": [{"t": "他俩个把我稳在这里,推买东西去了。", "b": "秦简夫《东堂老》"}]}, {"meaning": "忍受(如困苦或艰难)而不动摇、屈服或退让。", "cites": [{"t": "我为甚不敢明闻,肋底下插柴自稳。", "b": "关汉卿《救风尘》"}]}, {"meaning": "搞端正。", "cites": [{"t": "战袍待稳,絮重更熏香。", "b": "《敦煌曲校录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3119wx','熏','1','xūn xùn','灬','14','','[{"pinyin": "xūn", "defs": [{"meaning": "(俗作燻。会意。金文,上面象火烟冒出,中间是烟突(本古“窗”字),两点表示烟苔,下面是火焰。合起来是烟突冒烟。本义:火烟向上冒)。"}, {"meaning": "同本义。", "cites": [{"t": "熏,火烟上出也。", "b": "《说文》。俗字作燻。"}, {"t": "炎炎,熏也。", "b": "《尔雅》"}, {"t": "金炉扬熏。", "b": "陶弘景《许长史旧馆坛碑》"}], "words": [{"w": "熏天", "t": "上蒸而弥漫于天"}, {"w": "熏烝", "t": "热气升腾。"}]}, {"meaning": "烧灼,火烫。", "cites": [{"t": "我心惮暑,忧心如熏。", "b": "《诗·大雅·云汉》"}], "words": [{"w": "熏土", "t": "用杂草、落叶、稻杆等熏烧泥土。亦指熏烧过的泥土。"}]}, {"meaning": "熏制;焙制。", "cites": [{"t": "穹窒熏鼠,塞向墐户。", "b": "《诗·豳风·七月》"}], "words": [{"w": "熏穴", "t": "烟熏洞穴"}, {"w": "熏烧", "t": "烟熏火烧"}, {"w": "熏鱼;熏肉;墙熏黑了", "t": ""}]}, {"meaning": "气体侵袭;侵染。", "cites": [{"t": "鄣气昼熏体。", "b": "鲍照《苦热行》"}], "words": [{"w": "熏天", "t": "一用于形容气势极盛;或用于形容气味浓重。"}]}, {"meaning": "用言语、行动逐渐影响、说服人。", "cites": [{"t": "众口熏天。", "b": "《吕氏春秋·离谓》。注:“感动也。有始东南曰熏风。”"}, {"t": "欲以熏轑天下。", "b": "《汉书·杜钦传》"}], "words": [{"w": "熏心", "t": "迷住了心窍"}, {"w": "熏天赫地", "t": "形容气焰炽盛,威势逼人"}, {"w": "熏浸", "t": "熏陶浸染。"}]}, {"meaning": "以香料涂身。", "cites": [{"t": "方将坐足下三浴而三熏之。", "b": "韩愈《答吕毉山人书》"}], "words": [{"w": "薰香;薰沐", "t": ""}]}, {"meaning": "黄昏。", "cites": [{"t": "至熏夕,极欢而去。", "b": "《后汉书·赵壹传》"}], "words": [{"w": "熏夕", "t": "黄昏。"}]}, {"meaning": "温和,和暖。", "cites": [{"t": "熏风自南至,吹我池上林。", "b": "白居易《首夏南池独酌》"}]}, {"meaning": "和悦的样子。", "cites": [{"t": "公尸来止熏熏。", "b": "《诗·大雅·凫鷖》"}]}]}, {"pinyin": "xùn", "defs": [{"meaning": "", "words": [{"w": "炉子安上烟筒,就不至于熏着了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3120wx','箕','1','jī ji','竹','14','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从竹,其声。本义:簸箕,扬米去糠的器具)。"}, {"meaning": "同本义。", "cites": [{"t": "箕,簸也。", "b": "《说文》"}, {"t": "以箕自乡而报之。", "b": "《礼记·曲礼》。注:“箕去弃物。”"}, {"t": "良弓之子,必学为箕。", "b": "《礼记·学记》"}], "words": [{"w": "箕帚", "t": "簸箕和扫帚。借指家务"}, {"w": "箕裘", "t": "簸箕和皮袍。借指祖先的事业与遗产"}, {"w": "箕舌", "t": "指簸箕底伸展向前之广处,其状如舌"}, {"w": "箕敛", "t": "以箕收取。苛敛民财。"}]}, {"meaning": "畚箕。用竹篾、柳条等制成的清除垃圾的器具。", "cites": [{"t": "箕,箕帚也。", "b": "《广韵》"}, {"t": "凡为长者粪之礼,必加帚于箕上。", "b": "《礼记·曲礼》"}], "words": [{"w": "箕畚", "t": "畚箕"}, {"w": "箕帚", "t": "畚箕与扫帚"}, {"w": "箕扫", "t": "箕帚。扫除之具"}, {"w": "箕扫", "t": "指执箕清扫"}, {"w": "箕帚妾", "t": "持箕帚的奴婢,借作妻妾之谦称。"}]}, {"meaning": "星宿名 ,指箕宿,二十八宿之一。东方青龙七宿的末一宿。有星四颗。", "cites": [{"t": "维南有箕,不可以簸扬。", "b": "《诗·小雅·大东》"}], "words": [{"w": "箕尾", "t": "二十八宿之一,青龙七宿的末一宿"}, {"w": "箕水豹", "t": "二十八宿中的箕宿星。"}]}, {"meaning": "箕踞 。古人席地而坐,伸开两腿坐着,形状如簸箕。", "cites": [{"t": "坐毋箕。", "b": "《礼记·曲礼》。疏:“谓舒展两足,状如箕舌也。”"}], "words": [{"w": "箕张", "t": "谓两旁伸张开去如簸箕形"}, {"w": "箕坐", "t": "箕倨,箕踞。叉开腿坐着。"}]}]}, {"pinyin": "ji", "defs": [{"meaning": "——见“簸箕”(bòji)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3121wx','算','1','suàn','竹','14','','[{"pinyin": "suàn", "defs": [{"meaning": "(会意。从竹,从具。“竹”跟算筹有关,“具”表示齐备。本义:计算)。"}, {"meaning": "同本义。", "cites": [{"t": "算,数也。", "b": "《说文》"}, {"t": "无算爵。", "b": "《仪礼·乡饮酒礼》"}, {"t": "亲则月算如邦人。", "b": "《仪礼·丧服记》"}, {"t": "明衣不在算。", "b": "《仪礼·士丧礼》"}, {"t": "有算为之节文也。", "b": "《礼记·檀弓下》"}, {"t": "何足算也?", "b": "《论语·子路》"}, {"t": "只恐把铁棍子打完了,也算不到这笔帐上来。", "b": "《儒林外史》"}], "words": [{"w": "算还", "t": "结算支付"}, {"w": "算尽镏铢", "t": "极微小的数量也要算"}, {"w": "算来", "t": "计算起来"}, {"w": "算刻", "t": "犹计算"}, {"w": "算定", "t": "经过计算而确定或断定"}, {"w": "算程", "t": "计算路程。"}]}, {"meaning": "推测;料想。", "cites": [{"t": "杜郎俊赏,算而今,重到须惊。", "b": "宋·姜夔《扬州慢》"}, {"t": "我算你今天一定会来", "b": ""}], "words": [{"w": "算来", "t": "推测起来"}, {"w": "算应", "t": "算定;料定。"}]}, {"meaning": "作数,承认其有效力。", "cites": [{"t": "你算是个甚么东西?", "b": "《儒林外史》"}], "words": [{"w": "说了算", "t": ""}]}, {"meaning": "归;属于;当作;认作。", "cites": [{"t": "你也算贫贱之交了。", "b": "《红楼梦》"}], "words": [{"w": "功劳算你的;算作", "t": "当作"}, {"w": "算事", "t": "应作的头等大事。"}]}, {"meaning": "计谋;谋划。", "cites": [{"t": "自长非所增,自短非所损,算之所亡,若何?", "b": "《列子·力命》"}, {"t": "荐勋祖庙,享号中宗。算计见效,优于孝文。", "b": "《后汉书·崔骃传》附崔寔《政论》"}], "words": [{"w": "算计弗通", "t": "考虑不周;谋划失误"}, {"w": "算度", "t": "分析,判断"}, {"w": "算略", "t": "谋略"}, {"w": "算划", "t": "计划,谋划"}, {"w": "算部", "t": "指寿命"}, {"w": "算发", "t": "年龄不大而白发多。"}]}, {"meaning": "数目;数额。", "cites": [{"t": "人畜无算。", "b": "《交史·崔浩传》"}], "words": [{"w": "算子", "t": "算筹。常用以计数或占卜"}, {"w": "算子般", "t": "如同算筹丢在桌上一般"}, {"w": "算筹", "t": "旧时计算数目所用器物之一种,其制甚古,以竹木或厚纸等为之,上记数字,用以布算"}, {"w": "算禄", "t": "寿数和禄位。"}]}, {"meaning": "计算用的筹码。", "cites": [{"t": "一人执算以从之。", "b": "《仪礼·乡射礼》"}, {"t": "算,长尺二寸。", "b": "《礼记·投壷》"}], "words": [{"w": "算子", "t": "竹制的筹"}, {"w": "算囊,算袋", "t": "旧时百官贮放笔砚等的袋子"}, {"w": "算器", "t": "贮放算筹的器皿;竹器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3122wx','箩','1','luó','竹','14','','[{"pinyin": "luó", "defs": [{"meaning": "(形声。从竹,罗声。本义:竹制的盛器,多方底圆口)。"}, {"meaning": "同本义。", "cites": [{"t": "箩,箕也。", "b": "《广雅·释器》"}, {"t": "所以注斛,陈魏宋楚之间谓之箩。", "b": "《方言》五"}], "words": [{"w": "箩斗", "t": "即箩兜。箩筐"}, {"w": "箩兜", "t": "箩筐"}, {"w": "箩头", "t": "即箩筐"}, {"w": "箩担", "t": "挑有箩筐的担子"}, {"w": "箩筛", "t": "竹编的筛子。"}]}, {"meaning": "箩筛 。一种专供筛粉状物质或过滤流质的器具,底部比筛子密,用绢或细铜丝等材料做成。"}, {"meaning": "量词。", "cites": [{"t": "桐膏千箩,蜡千斤,茧丝千两。", "b": "清·唐甄《潜书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3123wx','管','1','guǎn','竹','14','','[{"pinyin": "guǎn", "defs": [{"meaning": "(形声。从竹,官声。本义:一种类似于笛的管乐器。后泛指管乐器)。"}, {"meaning": "中国古代的一种管乐器,起初用玉制成,改用竹,有六孔,长一尺。后泛指管乐器。", "cites": [{"t": "管,如箎,六孔,十二月之音,物开地牙,故谓之管。", "b": "《说文》"}, {"t": "箫管备举。", "b": "《诗·周颂·有瞽》"}, {"t": "建钟鼓,列管弦。", "b": "《淮南子·原道》。注:“管,箫也。”"}, {"t": "主人下马客在船,举酒欲饮无管弦。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "今王鼓乐于此,百姓闻王钟鼓之声,管籥之音。", "b": "《孟子·梁惠王下》"}], "words": [{"w": "管色", "t": "管类乐器"}, {"w": "管儿", "t": "指笛子之类的管乐器"}, {"w": "管弦", "t": "用管乐器弦乐器演奏的音乐"}, {"w": "管说", "t": "管窥之说"}, {"w": "管音", "t": "管乐器的声音。"}]}, {"meaning": "古称钥匙。", "cites": [{"t": "郑人使我掌其北门之管,若潜师以来,国可得也。", "b": "《左传·僖公三十二年》"}, {"t": "管库之士。", "b": "《礼记·檀弓下》"}, {"t": "慎管籥。", "b": "《礼记·月令·孟冬》"}, {"t": "每薄暮下管键,矢溺皆闭其中,与饮食之气相薄。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "管键", "t": "指钥匙与锁"}, {"w": "管钥", "t": "钥匙。"}]}, {"meaning": "笔管。后称笔为管。", "cites": [{"t": "嗟夫!当时余心之悲,盖不能以寸管形容之。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "管城子", "t": "笔的别称。又称管城、管城公、管城君、管城侯"}, {"w": "管城颖", "t": "犹笔颖。指笔头"}, {"w": "管毫", "t": "指笔"}, {"w": "管翰", "t": "笔。泛指文字笔墨"}, {"w": "管彤", "t": "赤管笔。"}]}, {"meaning": "(guān)。官吏。", "cites": [{"t": "则足以补管之不善政。", "b": "《管子·小匡》"}]}, {"meaning": "馆舍。", "cites": [{"t": "管人为客三日具沐,五日具浴。", "b": "《仪礼·聘礼》"}]}, {"meaning": "管理。", "cites": [{"t": "李兑管赵,囚主父于沙丘。", "b": "《史记·范雎列传》"}, {"t": "如今叫我管天王堂。", "b": "《水浒》"}], "words": [{"w": "经管", "t": "经营管理"}, {"w": "接管", "t": "接收并管理"}, {"w": "管摄", "t": "管理统率"}, {"w": "管领", "t": "管理,统领"}, {"w": "管勾", "t": "掌管,管理"}, {"w": "管屯", "t": "管理田庄"}, {"w": "管办", "t": "经管办理"}, {"w": "管主", "t": "主管;掌管。"}]}, {"meaning": "管教。", "cites": [{"t": "这孩子没管好", "b": ""}], "words": [{"w": "管照", "t": "照管。"}]}, {"meaning": "管辖、控制。", "cites": [{"t": "这个市管九个县", "b": ""}, {"t": "又敦煌郡大众殷,制御西域,管辖万里,为军国之本。", "b": "《晋书·凉武昭王传》"}], "words": [{"w": "管勾", "t": "管理"}, {"w": "管拘", "t": "犹管束"}, {"w": "管着", "t": "管教"}, {"w": "管头", "t": "管束别人的人。"}]}, {"meaning": "保证;包管。", "cites": [{"t": "今日既有书来,陛下宽心,微臣管送陛下还阳,重登玉阙。", "b": "《西游记》十一"}], "words": [{"w": "管取", "t": "管保;包管;照顾,照管"}, {"w": "管情", "t": "管请。包管,保证"}, {"w": "管成", "t": "管保;保证"}, {"w": "管取", "t": "管保;肯定"}, {"w": "管许", "t": "包管。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3124wx','箫','1','xiāo','艹','14','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从竹,肃声。从竹,与乐器有关。本义:洞箫,竹制的管乐器)。"}, {"meaning": "同本义 。管乐器名,古代的排箫是许多管子排在一起的,后世用一根管子。竖着吹的叫洞箫。", "cites": [{"t": "箫,参差管乐也。象凤之翼。", "b": "《说文》"}, {"t": "箫管弦歌。", "b": "《周礼·小师》。注:“编小竹。”"}, {"t": "若风之过箫。", "b": "《淮南子·齐俗》"}, {"t": "箫,编竹为之。长尺五寸。", "b": "《五经通义》"}, {"t": "秦地吹箫女,湘波鼓瑟妃。", "b": "唐·韩愈《梁国惠康公主挽歌》"}, {"t": "箫韶以随。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "箫韶", "t": "大磬。泛指乐器;又指舜的乐曲。借指乐声"}, {"w": "箫笛", "t": "箫与笛。泛指管乐器。"}]}, {"meaning": "弓的末端。", "cites": [{"t": "右执箫,南扬弓。", "b": "《仪礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3125wx','舆','1','yú','臼','14','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从车,舁(yú)声。本义:车厢)。"}, {"meaning": "同本义。", "cites": [{"t": "舆,车舆也。", "b": "《说文》。按,车中受物之处。"}, {"t": "舆人为车。", "b": "《考工记》"}, {"t": "木材…曲者宜为轮,直者宜为舆。", "b": "《潜夫论》"}]}, {"meaning": "车辆,尤指马车。", "cites": [{"t": "困于金舆。", "b": "《易·困》"}, {"t": "今乘舆已驾矣。", "b": "《孟子》"}, {"t": "虽有舟舆,无所乘之。", "b": "《老子》"}], "words": [{"w": "舆士", "t": "车夫"}, {"w": "舆服", "t": "车子和衣冠的总称"}, {"w": "舆几", "t": "车子与几案"}, {"w": "舆马", "t": "车马"}, {"w": "舆轮", "t": "车轮"}, {"w": "舆骑", "t": "车骑"}, {"w": "舆帅", "t": "主管兵车的官吏"}, {"w": "舆薪", "t": "车子、柴木等大东西。喻指显而易见的东西。"}]}, {"meaning": "古地名 。汉置,属临淮郡,东汉改属广陵郡,南朝宋并入江都县。故城在今江苏省江都县西。"}, {"meaning": "大众。", "cites": [{"t": "舆,多也。", "b": "《广雅》"}, {"t": "皂臣舆。", "b": "《左传·昭公七年》。服注:“众也。”"}], "words": [{"w": "舆情不洽", "t": "众人反映不好"}, {"w": "舆议咸冤", "t": "众人都认为冤枉"}, {"w": "舆望", "t": "众望。"}]}, {"meaning": "共同抬。", "cites": [{"t": "遂舆机而往。", "b": "《礼记·曾子问》"}, {"t": "舆豭从之。", "b": "《左传·哀公十五年》"}], "words": [{"w": "舆机", "t": "置尸于机上抬之。机,抬尸之床。用指出殡。"}]}, {"meaning": "乘坐。", "cites": [{"t": "舆轿而隃岭。", "b": "《汉书·严助传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3126wx','僚','1','liáo','亻','14','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从人,尞(liáo)声。本义:官,官职)。"}, {"meaning": "同本义。", "cites": [{"t": "百僚师师。", "b": "《书·皋陶谟》"}, {"t": "百僚是试。", "b": "《诗·小雅·大东》"}, {"t": "世胄蹑高位,英俊沉下僚。", "b": "左思《咏史》"}], "words": [{"w": "僚吏", "t": "僚属。属官部下"}, {"w": "僚佐", "t": "僚属,部下"}, {"w": "僚侍", "t": "侍臣"}, {"w": "僚故", "t": "故吏"}, {"w": "僚品", "t": "众官"}, {"w": "僚俊", "t": "才能杰出的属官。"}]}, {"meaning": "古代一种服苦役的官奴。", "cites": [{"t": "隶臣僚,僚臣仆。", "b": "《左传·昭公七年》"}], "words": [{"w": "僚朴", "t": "同主之仆"}, {"w": "僚隶", "t": "僚与隶,皆为服苦役的罪人。"}]}, {"meaning": "一起作官的人。", "cites": [{"t": "僚友称其弟也。", "b": "《礼记·曲礼》"}, {"t": "显誉成于僚友。", "b": "《后汉书·郑玄传》"}], "words": [{"w": "同僚", "t": "同在一个单位任职的官吏"}, {"w": "僚列", "t": "同僚"}, {"w": "僚寀", "t": "同僚,百官"}, {"w": "僚谊", "t": "官吏之间的情、友谊。"}]}, {"meaning": "(liǎo) 美好。", "cites": [{"t": "僚,好貌。", "b": "《说文》。段注:“《诗·陈风》:皎人僚兮。传曰:‘好貌。’此僚之本义也。自借为同寮字而本义废矣。”"}]}, {"meaning": "美好,敏慧。", "cites": [{"t": "月出皎兮,佼人僚兮。", "b": "《诗·陈风·月出》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3127wx','僧','1','sēng','亻','14','','[{"pinyin": "sēng", "defs": [{"meaning": "(形声。从人,曾声。本义:和尚)。"}, {"meaning": "同本义 指出家修行的男性佛教徒,俗称“和尚”,梵语“僧伽(samgha)”的省称。", "cites": [{"t": "僧言古壁佛画好,以火来照所见稀。", "b": "韩愈《山石》"}], "words": [{"w": "僧行", "t": "僧众"}, {"w": "僧众", "t": "僧人:和尚;佛教徒"}, {"w": "僧录司", "t": "明清时期管理佛门事务的机构"}, {"w": "僧雏", "t": "年龄小的僧人"}, {"w": "僧寮", "t": "僧人居住的房屋"}, {"w": "僧居", "t": "僧人的居室,寺院"}, {"w": "僧衲", "t": "僧衣"}, {"w": "僧靿袜儿", "t": "僧人穿的长筒袜"}, {"w": "僧正", "t": "管理众僧之官"}, {"w": "僧官", "t": "管理僧人、寺庙的官吏"}, {"w": "僧纲", "t": "管理佛教的官"}, {"w": "僧腊", "t": "指僧人受戒后的年龄。又称法腊"}, {"w": "僧伽梨", "t": "僧服大衣名。为袈裟的一种。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3128wx','鼻','1','bí','鼻','14','','[{"pinyin": "bí", "defs": [{"meaning": "(会意。从自,从畀(bì),“畀”又兼作声符。“自”是“鼻”的本字,作“自己”用后,另造了“鼻”字。“畀”是给予、付与的意思。合起来表示一呼一吸,自相给予。本义:鼻子)。"}, {"meaning": "同本义。呼吸兼嗅觉的器官。", "cites": [{"t": "鼻,主臭者也。", "b": "《说文》"}, {"t": "天食人以五气从鼻入,地食人以五味从口入。", "b": "《老子》"}, {"t": "鼻出入气高而有窍,又,鼻者,肺之使。", "b": "《白虎通》"}, {"t": "肤灭鼻。", "b": "《易·噬》。虞注:“艮为鼻。”"}, {"t": "鼻辨芬芳腥臊。", "b": "《荀子·荣辱》"}]}, {"meaning": "初始,发端。", "cites": [{"t": "鼻,始也。兽之初生谓之鼻,梁益之间谓鼻为初,或谓之祖。", "b": "《方言十三》"}, {"t": "有周氏之婵嫣兮,或鼻祖于汾隅。", "b": "《汉书·扬雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3129wx','魄','1','bó pò tuò','鬼','14','','[{"pinyin": "bó", "defs": [{"meaning": "形容拍击声。", "cites": [{"t": "竹外麦烟愁漠漠,短翅啼禽飞魄魄。", "b": "唐·陆龟蒙《春思二首》"}]}]}, {"pinyin": "pò", "defs": [{"meaning": "(形声。从鬼,白声。从鬼的字,常与灵魂、鬼怪有关。本义:阴神,迷信的人指依附于人的身体而存在的精神)。"}, {"meaning": "同本义,有别于可游离于人体之外的魂。", "cites": [{"t": "魄,阴神也。", "b": "《说文》"}, {"t": "人生始化曰魄。", "b": "《左传·昭公七年》。注:“形也,既生魄,阳曰魂。疏:附形之灵为魄。”"}, {"t": "其魄兆于民矣。魄意之精也。", "b": "《国语·晋语》"}, {"t": "魄也者,鬼之盛也。", "b": "《礼记·祭义》。注:“耳目之聪明为魄。”"}, {"t": "忽魂悸以魄动。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "魂魄", "t": "迷信者指附在人体内可以游离出去的精神"}, {"w": "心魄", "t": "心灵"}, {"w": "丧魂落魄;魄荡魂飞", "t": "魄散魂消、魄散魂飞等都形容惊恐万状"}, {"w": "魄心", "t": "灵魂。"}]}, {"meaning": "引申为人的形体。", "cites": [{"t": "人之精气曰魂,形体曰之魄。", "b": "《太平御览》引《礼记外传》"}]}, {"meaning": "月出月没的微光。", "cites": [{"t": "惟三月哉生魄。", "b": "《书·康诰》"}, {"t": "月未望则载魄于西,既望则终魄于东。", "b": "《法言·五百》"}], "words": [{"w": "魄蜍", "t": "传说月亮中的蟾蜍"}, {"w": "魄宝", "t": "魄渊。月亮"}, {"w": "魄兔", "t": "传说中指月中的兔。"}]}, {"meaning": "糟粕,酒滓。", "cites": [{"t": "然则君之所读者,古人之糟魄已夫!", "b": "《庄子·天道》"}]}]}, {"pinyin": "tuò", "defs": [{"meaning": "——“落魄”的“魄”的又音。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3130wx','魅','1','mèi','鬼','14','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。从鬼,未声。本义:迷信传说中的精怪) 同本义。", "cites": [{"t": "木魅山鬼,野鼠城狐,风嗥雨啸,昏见晨趋。", "b": "鲍照《芜城赋》"}], "words": [{"w": "魑魅", "t": "传说中指山林里能害人的妖怪"}, {"w": "鬼魅", "t": "鬼怪"}, {"w": "魅虚", "t": "老怪鬼魅名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3131wx','貌','1','mào','豸','14','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从豹省,皃(mào)声。本作“皃”,从“人白”,象人面形。儿,古文“人”字。本义:面容,相貌,容貌)。"}, {"meaning": "同本义(外在的仪表,生就的形象)。", "cites": [{"t": "皃,颂仪也。", "b": "《说文》。按,面之神气曰颂,面之形状曰皃。"}, {"t": "夫皃情之华也。", "b": "《国语·晋语》"}, {"t": "貌思恭。", "b": "《论语》。皇疏:“动容谓之皃。”"}, {"t": "貌耸神溢。", "b": "唐·李朝威《柳毅传》"}, {"t": "人之貌有与也。", "b": "《庄子·养生主》"}, {"t": "子产蹴然改容更貌。", "b": "《庄子·德充符》"}, {"t": "貌甚寝。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "貌团团", "t": "形容面容姣圆、丰润的样子"}, {"w": "貌侵", "t": "容貌丑陋"}, {"w": "貌妍", "t": "容貌美丽"}, {"w": "貌寝", "t": "相貌丑陋、消瘦"}, {"w": "貌状", "t": "外貌;形象"}, {"w": "貌容", "t": "容貌"}, {"w": "貌色", "t": "容貌"}, {"w": "貌肖", "t": "形貌相似。"}]}, {"meaning": "外表的形象,外观。", "cites": [{"t": "貌恭而心不服。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "貌为风厉", "t": "表面上做出严厉的样子"}, {"w": "全貌", "t": "事物的全部情况;全部面貌"}, {"w": "貌似", "t": "面貌相似。或指事物外表相似而内在不同。"}]}, {"meaning": "神态,面部神情。", "cites": [{"t": "貌若男子所以恭敬,妇人之所以姣好也。", "b": "《说苑·脩文》"}, {"t": "貌若甚戚者。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "貌禅", "t": "面部表情如僧徒入神。形容入神的样子。"}]}, {"meaning": "细微的丝。", "cites": [{"t": "简孚有众,惟貌有稽。", "b": "《书·吕刑》。《说文》引作“帷緢。”"}]}, {"meaning": "表面上。", "cites": [{"t": "北虽貌敬,实则愤怒。", "b": "宋·文天祥《后序》"}], "words": [{"w": "貌受", "t": "表面上接受"}, {"w": "貌是情非", "t": "表面做的与心里想的完全两样"}, {"w": "貌离神合", "t": "表面上不同而实质上一致"}, {"w": "貌合神离", "t": "表面上关系很亲密而实际上怀有二心。同貌合心离"}, {"w": "貌敬", "t": "容貌恭敬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3132wx','膜','1','mó','月','14','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从肉,莫声。本义:生物体内部的薄皮形组织)。"}, {"meaning": "同本义。", "cites": [{"t": "熏于肓膜,散于胸服。", "b": "《素问·痹论》"}], "words": [{"w": "耳膜;竹膜;细胞膜;鼓膜", "t": ""}]}]}]','jingmo-wenyan');
