('3133wx','膊','1','bó bo','月','14','','[{"pinyin": "bó", "defs": [{"meaning": "上肢，近肩的部分", "words": [{"w": "膊子", "t": "膀子,胳膊"}, {"w": "赤膊", "t": "光膀子"}]}]}, {"pinyin": "bo", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3134wx','膀','1','bǎng bàng pāng páng','月','14','','[{"pinyin": "bǎng", "defs": [{"meaning": "(形声。从肉,旁声。本义:肩膀)。"}, {"meaning": "同本义。", "cites": [{"t": "十分腰围膀阔。", "b": "《水浒传》"}], "words": [{"w": "膀阔腰圆;腰细膀宽", "t": ""}]}, {"meaning": "兽类或家畜腿的上部或前肢和躯干相连的部分。", "cites": [{"t": "肉则羊膀豕胁,脂肤相半。", "b": "《初学记》"}]}, {"meaning": "鸟类等的翅膀。"}]}, {"pinyin": "bàng", "defs": [{"meaning": "——“吊膀子”(diàobàngzi)(方言。调情)。"}]}, {"pinyin": "pāng", "defs": [{"meaning": "浮肿。", "cites": [{"t": "我头脸也膀了,腰腿也断了。", "b": "《野叟曝言》"}]}, {"meaning": "指。", "cites": [{"t": "这王簪儿登时把那付奴脸,膀的有房梁高,也不搽脸了。", "b": "《金瓶梅词话》"}]}]}, {"pinyin": "páng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3135wx','鲜','1','xiān xiǎn','鱼','14','','[{"pinyin": "xiān", "defs": [{"meaning": "(会意。从鱼,从羊。“鱼”表类属,“羊”表味美。本义:鱼名。出貉国)。"}, {"meaning": "假借为鱻。鲜鱼,活鱼。", "cites": [{"t": "冬宜鲜羽。", "b": "《礼记·内则》。注:“生鱼也。”"}, {"t": "治大国若烹小鲜。", "b": "《老子》。河上公注:“鲜,鱼。”"}, {"t": "调鼎他年事,妙手看烹鲜。", "b": "宋·张元干《水调歌头》"}, {"t": "冬宜鲜羽。", "b": "《礼记》"}], "words": [{"w": "鲜眼", "t": "像鱼那样的圆眼"}, {"w": "鱼鲜;海鲜;鲜脍", "t": "切细的鲜鱼肉"}, {"w": "鲜鳞", "t": "活鱼"}, {"w": "鲜羽", "t": "活鱼和活鸟。"}]}, {"meaning": "鲜美的食物。", "cites": [{"t": "惟君用鲜。", "b": "《左传·襄公三十年》"}, {"t": "荐鲜知路近,省敛觉年丰。", "b": "唐玄宗《幸凤泉汤》"}], "words": [{"w": "时鲜;尝鲜;鲜肥", "t": "鱼肉类美味肴馔"}, {"w": "鲜食", "t": "鲜活的食品"}, {"w": "鲜杀", "t": "活杀的猎物。"}]}, {"meaning": "新鲜。", "cites": [{"t": "炰鳖鲜鱼。", "b": "《诗·大雅·韩奕》"}, {"t": "芳草鲜美。", "b": "晋·陶渊明《桃花源记》"}, {"t": "鱼腊鲜兽皆如初。", "b": "《仪礼》"}, {"t": "根色鲜泽。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "屡见不鲜;数见不鲜;鲜食", "t": "新鲜的食品"}, {"w": "鲜兽", "t": "新杀的禽兽。"}]}, {"meaning": "鲜明;明洁,洁净。", "cites": [{"t": "衣服常鲜于我。", "b": "《汉书·广川惠王越传》"}], "words": [{"w": "鲜色", "t": "清新美丽的颜色"}, {"w": "鲜新", "t": "清新。"}]}, {"meaning": "味美。", "cites": [{"t": "饫肥鲜者。", "b": "明·刘基《卖柑者言》"}, {"t": "无鲜肥滋味。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "鲜爽", "t": "鲜美爽口"}, {"w": "鲜脆", "t": "鲜美脆嫩"}, {"w": "鲜香", "t": "鲜美芳香。"}]}, {"meaning": "夭折的,早死的。", "cites": [{"t": "葬鲜者自西门。", "b": "《左传·昭公五年》"}]}]}, {"pinyin": "xiǎn", "defs": [{"meaning": "非常少,很不多。", "cites": [{"t": "靡不有初,鲜克有终。", "b": "《诗·大雅·荡》"}, {"t": "原小则鲜。", "b": "《史记·货殖列传》"}, {"t": "以约失之者鲜矣(由于俭约而犯过失的人很少)。", "b": "宋·司马光《训俭示康》"}, {"t": "菊之爱,陶后鲜有闻。", "b": "宋·周敦颐《爱莲说》"}, {"t": "鲜不疫矣。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "鲜薄", "t": "微少"}, {"w": "鲜言", "t": "寡言"}, {"w": "鲜胄", "t": "后代少"}, {"w": "鲜浅", "t": "浅鲜"}, {"w": "鲜乏", "t": "缺乏"}, {"w": "鲜少", "t": "很少。"}]}, {"meaning": "缺少;不足。", "cites": [{"t": "既无叔伯,终鲜兄弟。", "b": "李密《陈情表》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3136wx','疑','1','yí','疋','14','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。小篆字形。从子止匕,矢声。止,不通。子,幼子。幼子多惑。本义:怀疑)。"}, {"meaning": "同本义。", "cites": [{"t": "疑,惑也。", "b": "《说文》"}, {"t": "三军既惑且疑,则诸侯之难至矣。", "b": "《孙子·谋攻》"}, {"t": "时至而疑。", "b": "《周书·王佩》"}, {"t": "疑邻人之父。", "b": "《韩非子·说难》"}, {"t": "吾尝疑乎是。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "疑是地上霜。", "b": "唐·李白《静夜思》"}, {"t": "自疑身外。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "汝腹中之物,佘疑其女也。", "b": "林觉民《与妻书》"}], "words": [{"w": "疑思", "t": "疑虑"}, {"w": "疑影", "t": "怀疑;疑团"}, {"w": "疑猜", "t": "怀疑猜测"}, {"w": "疑龊", "t": "疑惑"}, {"w": "疑狐", "t": "怀疑;狐疑"}, {"w": "疑念", "t": "因怀疑而思索"}, {"w": "疑踪", "t": "可疑之处"}, {"w": "疑结", "t": "犹疑团"}, {"w": "疑阻", "t": "埋伏"}, {"w": "疑冢", "t": "疑墓"}, {"w": "疑敌", "t": "迷惑敌人"}, {"w": "疑人", "t": "怀疑他人"}, {"w": "疑揣", "t": "怀疑猜测"}, {"w": "疑惑", "t": "怀疑,不相信。"}]}, {"meaning": "迷惑,犹豫不定。", "cites": [{"t": "疑行无成,疑事无功。", "b": "《商君书》"}, {"t": "盛容服而饰辩说,以疑当世之法,而人主之心。", "b": "《韩非子·五蠹》"}], "words": [{"w": "疑阻", "t": "埋伏"}, {"w": "疑冢", "t": "疑墓"}, {"w": "疑敌", "t": "迷惑敌人"}, {"w": "疑人", "t": "用以迷惑敌人的草人"}, {"w": "疑军", "t": "疑兵,虚张声势以迷惑敌人的军阵。"}]}, {"meaning": "猜度;估计。", "cites": [{"t": "内有疑妻之妾。", "b": "《管子·君臣下》"}, {"t": "臣疑其君,无不危国。", "b": "《史记·李斯列传》"}, {"t": "不以公卿为宾,而以大夫为宾,为疑也。", "b": "《礼记·燕义》"}], "words": [{"w": "疑词", "t": "不确切的言词"}, {"w": "疑罪", "t": "证据不足,难以量刑之罪。"}]}, {"meaning": "疑问。", "cites": [{"t": "其妻献疑。", "b": "《列子·汤问》"}, {"t": "无以致疑。", "b": "清·刘开《问说》"}, {"t": "则无疑也。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "疑碍", "t": "疑问;问题"}, {"w": "疑事", "t": "难以辨别的事"}, {"w": "疑法", "t": "疑难案件。"}]}, {"meaning": "怪异。引申为责怪。", "cites": [{"t": "壶浆远见候,疑我与时乖。", "b": "晋·陶潜《饮酒》"}], "words": [{"w": "疑诟", "t": "责骂。"}]}, {"meaning": "类似;好像。", "cites": [{"t": "用志不分,乃疑于神。", "b": "《列子》张湛注:“分犹散,意专则与神相似者也。”"}, {"t": "山重水复疑无路,柳暗花明又一村。", "b": "宋·陆游《游山西村》"}], "words": [{"w": "疑论", "t": "疑似的言论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3137wx','孵','1','fū','子','14','','[{"pinyin": "fū", "defs": [{"meaning": "(形声。从卵,孚声。本义:鸟类伏在卵上,使卵内的胚胎发育成雏鸟)", "words": [{"w": "孵卵器", "t": ""}, {"w": "孵小鸡", "t": "用孵化法使蛋成为幼仔。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3138wx','馒','1','mán','饣','14','','[{"pinyin": "mán", "defs": [{"meaning": "一种用发面蒸成的食品，圆形或长方形，无馅。本有馅,后北方称无馅的为馒头,有馅的为包子"}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3139wx','裹','1','guǒ','衣','14','','[{"pinyin": "guǒ", "defs": [{"meaning": "(形声。从衣,果声。本义:包,缠)。"}, {"meaning": "同本义。", "cites": [{"t": "裹,缠也。", "b": "《说文》"}, {"t": "朱三百,裹。", "b": "《穆天子传》"}, {"t": "富之以国裹。", "b": "《管子·君臣》。注:“谓财货所苞裹而藏也。”"}, {"t": "无不裹也。", "b": "《吕氏春秋·本生》。注:“犹囊也。”"}, {"t": "绿叶紫裹。", "b": "宋玉《高唐赋》"}, {"t": "濯颖散裹。", "b": "郭璞《江赋》"}, {"t": "乃取蒙冲头舰十艘,载燥荻枯柴,灌油其中,裹以帷幕。", "b": "《资治通鉴》"}, {"t": "伤者手为裹创,死者厚棺殓,酹醊而哭之。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "裹束", "t": "包裹束缚"}, {"w": "裹足", "t": "包裹足部。亦作“果足”:盘缠,盘费"}, {"w": "裹革", "t": "马革裹尸。"}]}, {"meaning": "携带。", "cites": [{"t": "吾闻开元中,下天富蕃,号为理平,踵千里者不裹粮。", "b": "唐·孙樵《书褒城驿壁》"}], "words": [{"w": "裹粮策马", "t": "携带粮食,鞭赶马匹。形容忠义之士踊跃参军的情景"}, {"w": "裹持", "t": "包裹挟持,犹携带。"}]}, {"meaning": "停止。", "cites": [{"t": "却宾客以业诸侯,使天下之士退而不敢西向,裹足不入秦,此所谓藉寇兵而赍盗粮者也。", "b": "秦·李斯《谏逐客书》"}], "words": [{"w": "裹足", "t": "形容有所顾虑而止步"}, {"w": "裹足不前", "t": "缠住脚不前进。形容有所顾虑而止步不敢向前。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3140wx','敲','1','qiāo','攴','14','','[{"pinyin": "qiāo", "defs": [{"meaning": "(形声。从攴,高声。攴,pū,轻击。象手(又)拿小棍轻击的样子。本义:敲击,叩打)。"}, {"meaning": "同本义。", "cites": [{"t": "敲,击头也。", "b": "《说文》"}, {"t": "夺之杖以敲之。", "b": "《左传·定公二年》。释文:“击声也。”"}, {"t": "下见共王五伯,将敲其头矣。", "b": "《吕氏春秋·当务》"}, {"t": "僧敲月下门。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "欲着敲字。", "b": ""}, {"t": "作推敲之势。", "b": ""}, {"t": "作敲字佳矣。", "b": ""}, {"t": "敲剥天下。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "敲扑", "t": "拷打"}, {"w": "敲丝", "t": "银子。古时银锭上面都敲有圆纹,故称"}, {"w": "敲枰", "t": "下棋"}, {"w": "敲翻", "t": "打断。"}]}, {"meaning": "短杖式的刑具。", "cites": [{"t": "执敲扑而鞭笞天下。", "b": "汉·贾谊《过秦论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3141wx','豪','1','háo','豕','14','','[{"pinyin": "háo", "defs": [{"meaning": "(形声。从豕(shǐ),猪,高省声。本义:豪猪)。"}, {"meaning": "同本义 。哺乳动物,全身黑色,自肩部以后长着许多长而硬的棘毛。棘毛如刺,黑白相间。穴居,昼伏夜出。也称箭猪。", "cites": [{"t": "豪,豪豕鬣如笔管者,出南郡。", "b": "《说文》。俗字作“毫”。"}, {"t": "鹿台之山,其兽多白豪。", "b": "《山海经·西山经》"}, {"t": "豪,猪也。", "b": "《玉篇》"}], "words": [{"w": "豪毛", "t": "豪猪身上的长而末端尖细的毛"}, {"w": "豪豨", "t": "豪彘。豪猪。"}]}, {"meaning": "动物长而细的毛。", "cites": [{"t": "天下莫大于秋豪之末,而大山为小。", "b": "《庄子·齐物论》"}, {"t": "此其比万物也,不似豪末之在于马体乎?", "b": "《庄子·秋水》"}, {"t": "百姓有非理者如豪末。", "b": "《荀子·王霸》"}, {"t": "察分秋豪。", "b": "《淮南子·修务》"}, {"t": "豪羊。", "b": "《穆天子传》。注:“似髦牛,又豪马、豪牛。注:“豪犹髭也。”"}, {"t": "病有在毫毛腠理之间。", "b": "《素问·刺要论》。注:“毛之长者曰豪。”"}]}, {"meaning": "具有高超才能与品德的人。", "cites": [{"t": "德千人者谓之豪。", "b": "《鹖冠子·博选》"}, {"t": "百人者谓之豪。", "b": "《淮南子·泰族》"}, {"t": "关中贤豪知与不知,闻其声,争交欢解。", "b": "《史记·游侠列传》"}, {"t": "以为豪。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "豪雄", "t": "英雄豪杰"}, {"w": "豪俊", "t": "才智、勇力出众的人"}, {"w": "英豪;文豪;豪彦", "t": "才智过人之士"}, {"w": "豪烈", "t": "刚正有为、勇于任事的人。"}]}, {"meaning": "英雄。", "cites": [{"t": "三蜀之豪,时来时往。", "b": "左思《蜀都赋》"}]}, {"meaning": "旧指有钱有势或依仗权势横行不法的人。", "cites": [{"t": "是儿少秦武阳二岁,而讨杀二豪,岂可近耶?", "b": "柳宗元《童区寄传》"}], "words": [{"w": "土豪;豪士;豪奴", "t": "依仗主人权势横行不法的奴仆"}, {"w": "豪党", "t": "地方上有势力而结党横行乡里的人"}, {"w": "豪子", "t": "豪家子弟。"}]}, {"meaning": "山名。即崤。"}, {"meaning": "姓。宋代有豪彦。"}, {"meaning": "巨大的,势力强大的。", "cites": [{"t": "或耕豪民之田,见税什五。", "b": "《汉书·食货志》"}], "words": [{"w": "豪姓;豪客", "t": ""}]}, {"meaning": "强横。", "cites": [{"t": "豪贼劫持。", "b": "唐·柳宗元《童区寄传》"}, {"t": "计杀二贼。", "b": ""}, {"t": "骄豪而多怨。", "b": "宋·苏轼《教战守》"}, {"t": "豪有力者。", "b": "《明史》"}], "words": [{"w": "豪猾", "t": "强横而不驯服"}, {"w": "豪奸", "t": "强横邪恶"}, {"w": "豪吞", "t": "强横地侵占"}, {"w": "豪武", "t": "强横勇武。"}]}, {"meaning": "豪放,豪迈;气度宽广、不拘小节。", "cites": [{"t": "平原君之游,徒豪举耳。", "b": "《史记·魏公子列传》"}], "words": [{"w": "豪纵", "t": "豪放不羁;强横放纵"}, {"w": "豪放不羁", "t": "意气奔放,不受束缚"}, {"w": "豪士", "t": "豪放任侠之士"}, {"w": "豪上", "t": "豪爽,无拘束"}, {"w": "豪句", "t": "豪放的诗文。"}]}, {"meaning": "奢侈;豪华。", "cites": [{"t": "近世寇莱公豪侈冠一时,然功业大……", "b": ""}]}, {"meaning": "——宋·司马光《训俭示康》。", "words": [{"w": "豪荡", "t": "任侠而不拘礼法"}, {"w": "豪俊", "t": "豪华美丽"}, {"w": "豪宴", "t": "豪奢的宴席"}, {"w": "豪忲", "t": "过度奢侈、浪费"}, {"w": "豪恣", "t": "放肆、蛮横。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3142wx','膏','1','gāo gào','月','14','','[{"pinyin": "gāo", "defs": [{"meaning": "(形声。从肉,高声。从肉,表示与肉体有关。本义:溶化的油脂,无角动物的油脂)。"}, {"meaning": "同本义。", "cites": [{"t": "膏,肥也。", "b": "《说文》。按,膏者,脂也。凝者曰脂,释者曰膏。"}, {"t": "无角者膏。", "b": "《大戴礼记·易本命》"}, {"t": "膏者,神之液也。", "b": "《春秋·玄命苞》"}, {"t": "内热溲膏。", "b": "《庄子·则阳》"}, {"t": "膏之下。", "b": "《左传·成公十年》。注:“心下为膏。”"}, {"t": "雉膏不食。", "b": "《易·鼎》"}, {"t": "自伯之东,首如飞蓬。岂无膏沐,谁适为容?", "b": "《诗·卫风·伯兮》"}, {"t": "实以薪草,膏油灌其中。", "b": "《三国志·周瑜传》"}, {"t": "根之茂者其实遂,膏之沃者其光晔。", "b": "韩愈《答李翊书》"}], "words": [{"w": "膏液", "t": "动植物体内或植物果实内的油脂"}, {"w": "膏泽脂香", "t": "指油脂类的化妆品"}, {"w": "膏髓", "t": "脂膏与骨髓"}, {"w": "膏馥", "t": "膏脂的香味。"}]}, {"meaning": "肥肉。", "cites": [{"t": "《诗》云:“既醉以酒,既饱以德。”言饱乎仁义也,所以不愿人之膏粱之味也。", "b": "《孟子·告子上》"}], "words": [{"w": "膏鲜", "t": "指鱼肉一类食物"}, {"w": "膏蟹", "t": "食用蟹的一种"}, {"w": "膏肉", "t": "泛指脂肉。"}]}, {"meaning": "特指油灯。", "cites": [{"t": "养其根而竢其实,加其膏而希其光。", "b": "唐·韩愈《答李翊书》"}], "words": [{"w": "膏明", "t": "灯火照明"}, {"w": "膏映", "t": "谓灯光照射"}, {"w": "膏晷", "t": "灯光与日影。"}]}, {"meaning": "古代医学称心尖脂肪为“膏”。", "cites": [{"t": "疾不可为也,在肓之上,膏之下,攻之不可,达之不及,药不至焉,不可为也!", "b": "《左传·成公十年》"}], "words": [{"w": "膏肓", "t": "指心灵深处。古代医学称心尖脂肪为膏,心脏与隔膜之间的隔膜为肓。"}]}, {"meaning": "肥沃。", "cites": [{"t": "膏壤二千里。", "b": "《史记·齐太公世家》"}, {"t": "膏田满野。", "b": "仲长统《昌言·理论》"}], "words": [{"w": "膏脉;膏土", "t": "肥沃的土壤"}, {"w": "膏田", "t": "良田。肥沃的田"}, {"w": "膏畴", "t": "肥沃的田地"}, {"w": "膏壤", "t": "肥沃的土地。"}]}, {"meaning": "甘美。", "cites": [{"t": "故天降膏露,地出醴泉。", "b": "《礼记·礼运》"}], "words": [{"w": "膏露", "t": "甘露"}, {"w": "膏泉", "t": "甘泉"}, {"w": "膏乳", "t": "比喻甜美的果汁与山泉。"}]}]}, {"pinyin": "gào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3143wx','遮','1','zhē','辶','14','','[{"pinyin": "zhē", "defs": [{"meaning": "(形声。从辵(chuò),庶声。本义:阻挡;拦阻)。"}, {"meaning": "同本义(使不通过,使中途停止)。", "cites": [{"t": "陈王出,遮道而呼涉。", "b": "《史记·陈涉世家》"}, {"t": "子不遮乎亲,臣不遮乎君。", "b": "《吕氏春秋》"}, {"t": "遮豪民于道。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "遮影", "t": "遮挡;遮蔽"}, {"w": "遮止", "t": "阻止,拦阻"}, {"w": "遮迭", "t": "遮挡;招架"}, {"w": "遮路", "t": "阻塞道路"}, {"w": "遮遏", "t": "阻止;阻挡。"}]}, {"meaning": "掩蔽。", "cites": [{"t": "千呼万唤始出来,犹抱琵琶半遮面。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "遮嚣", "t": "掩饰;隐瞒"}, {"w": "遮堂", "t": "屏门"}, {"w": "遮说", "t": "曲为说辞,以为掩饰"}, {"w": "遮障", "t": "遮挡;遮蔽"}, {"w": "遮蒙", "t": "覆盖;蒙住"}, {"w": "遮隔", "t": "遮蔽阻隔"}, {"w": "遮前掩后", "t": "说话藏头露尾,欲言又止。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3144wx','腐','1','fǔ','肉','14','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从肉,府声。本义:腐烂变质)。"}, {"meaning": "同本义。", "cites": [{"t": "腐,烂也。", "b": "《说文》"}, {"t": "腐,败也。", "b": "《广雅》"}, {"t": "人死,五藏腐朽。", "b": "汉·王充《论衡·订鬼篇》"}, {"t": "流水不腐。", "b": "《吕氏春秋·尽数》"}, {"t": "肉腐出虫,鱼枯生蠹。", "b": "《荀子·劝学》"}], "words": [{"w": "腐散", "t": "腐烂消散"}, {"w": "腐坏", "t": "腐烂损坏"}, {"w": "腐秽", "t": "腐烂肮脏"}, {"w": "腐浊", "t": "腐臭浑浊。"}]}, {"meaning": "拍;击。", "cites": [{"t": "此臣之日夜切齿腐心也,乃今得闻教!", "b": "《史记·刺客传》"}]}, {"meaning": "指思想或文章陈旧、古板。", "cites": [{"t": "为天下安用腐儒?", "b": "《史记·黥布列传》"}], "words": [{"w": "腐板", "t": "迂腐古板"}, {"w": "腐俗", "t": "陈腐庸俗"}, {"w": "腐音", "t": "陈腐的音调"}, {"w": "腐局", "t": "陈腐的观念。"}]}, {"meaning": "气味恶臭。", "cites": [{"t": "流水不腐。", "b": "《吕氏春秋·尽数》"}]}, {"meaning": "宫刑。", "cites": [{"t": "死罪欲腐者许之。", "b": "《汉书·景帝纪》。注:“宫刑也。”"}], "words": [{"w": "腐史", "t": "指《史记》。因作者司马迁是在受了腐刑的情况下完成这本书的"}, {"w": "腐夫", "t": "宦官,太监。即受宫刑的人"}, {"w": "腐罪", "t": "应受腐刑之罪"}, {"w": "腐身", "t": "遭受腐刑的身躯"}, {"w": "腐庸", "t": "指太监。太监腐身而为庸仆。故称"}, {"w": "腐人", "t": "因受刑或饥寒而死于监狱的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3145wx','瘩','1','dá da','疒','14','','[{"pinyin": "dá", "defs": [{"meaning": "瘩背"}]}, {"pinyin": "da", "defs": [{"meaning": "一方面指皮肤上突起或肌肉上结成的小硬块，另一方面也指人思想上的矛盾、疑虑、问题等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3146wx','瘟','1','wēn','疒','14','','[{"pinyin": "wēn", "defs": [{"meaning": "(形声。从疒(chuáng),昷(wēn)声。本义:瘟疫) 同本义。", "cites": [{"t": "前日被瘟官打的棒疮…好不疼痛!", "b": "清·张南庄《何典》"}], "words": [{"w": "瘟官", "t": "害人的官"}, {"w": "瘟瘴", "t": "瘟疫"}, {"w": "瘟瘴", "t": "即瘟疫"}, {"w": "瘟君", "t": "又叫瘟鬼,瘟神爷。即指瘟神"}, {"w": "瘟气", "t": "瘟疠之气。"}]}, {"meaning": "(像得了瘟病似的)神情呆滞、没有生气的。", "cites": [{"t": "从此王胡瘟头瘟脑的许多日。", "b": "鲁迅《阿Q正传》"}]}, {"meaning": "愚笨的。", "cites": [{"t": "为什么这一回偏如此其瘟?", "b": "《大波》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3147wx','瘦','1','shòu','疒','14','','[{"pinyin": "shòu", "defs": [{"meaning": "(形声。从疒(chuáng),叟声。从疒,表明与疾病有关。本义:肌肉不丰满)。"}, {"meaning": "同本义 。与“胖”、“肥”相对。", "cites": [{"t": "瘦,臞也。", "b": "《说文》。"}, {"t": "毁瘠羸瘦。", "b": "《孝经》"}, {"t": "久则瘦臞腐败。", "b": "《周礼·廛人》注"}, {"t": "有书生避雨檐下,衣湿袖单,影乃益瘦。", "b": "清·周容《芋老人传》"}], "words": [{"w": "瘦怯", "t": "瘦弱;瘦削"}, {"w": "瘦怯怯", "t": "瘦弱的样子"}, {"w": "瘦亭亭", "t": "亦作“瘦棱楼”。十分瘦削的样子"}, {"w": "瘦岩岩", "t": "纤细瘦削的样子"}, {"w": "瘦恹恹", "t": "瘦厌厌。形容瘦弱消瘦"}, {"w": "瘦伶伶", "t": "形容瘦的样子"}, {"w": "瘦伶仃", "t": "十分瘦弱的样子"}, {"w": "瘦客", "t": "消瘦衰弱之人"}, {"w": "瘦悴", "t": "消瘦憔悴"}, {"w": "瘦容", "t": "消瘦的容的样子。"}]}, {"meaning": "细小;不茁壮。", "cites": [{"t": "落松满地金钗瘦,远树黏天菌子孤。", "b": "杨万里《刘村渡》"}], "words": [{"w": "瘦硬", "t": "细瘦而坚硬"}, {"w": "瘦果", "t": "干果的一种,比较小。如白头翁,向日葵等。"}]}, {"meaning": "形容削直、突兀。", "cites": [{"t": "路转山腰未足移,水清石瘦便能奇。", "b": "宋·苏轼《与毛令方尉游西菩提寺》"}], "words": [{"w": "瘦石", "t": "峭削之石"}, {"w": "瘦筇", "t": "指手杖。筇竹,节高干细,可作手杖"}, {"w": "瘦脊", "t": "山势尖削"}, {"w": "瘦鹤", "t": "即鹤。以其嘴长直、脚细长故云。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3148wx','辣','1','là','辛','14','','[{"pinyin": "là", "defs": [{"meaning": "(形声。从辛,剌(là)省声。本义:辛味)。"}, {"meaning": "同本义。姜、蒜、辣椒等带刺激性的味道。", "cites": [{"t": "辢,辛也。", "b": "《广雅》"}, {"t": "辛甚曰辣。", "b": "《通俗文》"}, {"t": "江南曰辣,中国曰辛。", "b": "《声类》"}], "words": [{"w": "酸甜苦辣;辣菜根子", "t": "辣菜的根很辣,喻非常泼辣"}, {"w": "辣拐子", "t": "辣手的家伙。骂人的话。"}]}, {"meaning": "高温,酷热。", "cites": [{"t": "太阳辣得如火烧,庄稼晒得枯焦焦。", "b": "《白族民歌集》"}]}, {"meaning": "辣味刺激。", "cites": [{"t": "辣椒虽辣,辣不死人。", "b": "鲁迅《伪自由书》"}], "words": [{"w": "切葱头辣眼睛", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3149wx','彰','1','zhāng','彡','14','','[{"pinyin": "zhāng", "defs": [{"meaning": "(会意兼形声。从彡从章,章亦声。章,显著;彡(shān),加上修饰。本义:明显,显著)。"}, {"meaning": "同本义。", "cites": [{"t": "彰,文彰也。", "b": "《说文》"}, {"t": "彰,明也。", "b": "《广雅·释诂四》"}, {"t": "彰厥有常。", "b": "《书·皋陶谟》"}, {"t": "义理之道彰。", "b": "《吕氏春秋·怀宠》"}, {"t": "嘉言孔彰。", "b": "《书·伊训》"}, {"t": "顺风而呼,声非加疾也,而闻者彰。", "b": "《荀子·劝学》"}, {"t": "得势益彰。", "b": "《史记·货殖列传》"}, {"t": "何忧令名不彰邪?", "b": "《世说新语·自新》"}], "words": [{"w": "彰弥", "t": "更加显著;越发暴露"}, {"w": "彰明昭著", "t": "彰明较著。形容非常显明"}, {"w": "彰著", "t": "明显;显著。"}]}, {"meaning": "文采美盛鲜明。", "cites": [{"t": "圣谟洋洋,嘉言孔彰。", "b": "《书·伊训》"}], "words": [{"w": "彰显", "t": "昭著的事实"}, {"w": "彰施", "t": "明施。"}]}, {"meaning": "表扬,表彰。", "cites": [{"t": "彰善瘅恶,树之风声。", "b": "《书·毕命》"}], "words": [{"w": "彰往考来", "t": "彰明往事,考察未来"}, {"w": "彰宣", "t": "显扬,宣示"}, {"w": "彰扬", "t": "宣扬;传扬。"}]}, {"meaning": "揭示,表露。", "cites": [{"t": "责攸之、瑀、允等之慢,以彰其咎。", "b": "诸葛亮《出师表》"}], "words": [{"w": "彰败", "t": "揭破;败露"}, {"w": "彰明", "t": "颁示;昭示"}, {"w": "彰闻", "t": "广为传闻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3150wx','竭','1','jié','立','14','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从立,曷声。本义:背举;用肩背负)。"}, {"meaning": "同本义。", "cites": [{"t": "五行之动,迭相竭也。", "b": "《礼记·礼运》。注:“犹负戴也。”"}]}, {"meaning": "干涸;枯竭。", "cites": [{"t": "伊洛竭而夏亡。", "b": "《国语·周语》。注:“涸也。”"}, {"t": "渊泉不能竭。", "b": "《淮南子·说林》"}, {"t": "竭泽而渔。", "b": "《淮南子·本经》"}], "words": [{"w": "竭涸", "t": "干涸无水"}, {"w": "枯竭", "t": "水源干涸。"}]}, {"meaning": "穷尽。", "cites": [{"t": "再而衰,三而竭。", "b": "《左传·庄公十年》"}, {"t": "彼竭我盈。", "b": ""}, {"t": "庶竭驽钝。", "b": "《三国志·诸葛亮传》"}, {"t": "竭其庐之入。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "于是众人竭力挠之。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "人道竭矣。", "b": "《礼记·大传》。注:“尽也。”"}, {"t": "齐明而不竭。", "b": "《荀子·脩身》。注:“不穷也。”"}], "words": [{"w": "耗竭", "t": "消耗净尽"}, {"w": "竭蹶", "t": "资产匮乏"}, {"w": "竭志殚力", "t": "用尽了意志和力量"}, {"w": "竭诚尽瘁", "t": "尽心尽力。"}]}, {"meaning": "亡;失去。", "cites": [{"t": "唇竭则齿寒。", "b": "《庄子》"}]}, {"meaning": "败坏;毁灭。", "cites": [{"t": "且律竭先,盈而以竭。", "b": "《左传·宣公十二年》。注:“败也。”"}, {"t": "耳目淫则竭。", "b": "《淮南子》。高诱注:“竭,灭也”。"}]}, {"meaning": "悉;全。", "cites": [{"t": "诸侯之病竭至,以待桓公。", "b": "《管子·大匡》"}], "words": [{"w": "竭绝", "t": "完全;到底。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3151wx','端','1','duān','立','14','','[{"pinyin": "duān", "defs": [{"meaning": "(形声。从立,耑(duān)声。本义:站得直)。"}, {"meaning": "同本义。", "cites": [{"t": "端,直也。", "b": "《说文》。按:“立容直也。”"}, {"t": "端,正也。", "b": "《广雅·释诂一》"}, {"t": "以端其位。", "b": "《礼记·祭义》"}, {"t": "端行颐霤如矢。", "b": "《礼记·王藻》"}, {"t": "振书端书于君前。", "b": "《礼记·曲礼》"}], "words": [{"w": "端行", "t": "端正身躯而快步行走"}, {"w": "端拱", "t": "端正身子拱手"}, {"w": "端伟", "t": "笔直壮大"}, {"w": "端端", "t": "端正;不倾斜"}, {"w": "端身", "t": "摆正身体。"}]}, {"meaning": "端正。引申为正直。", "cites": [{"t": "水至平,端不倾。", "b": "《荀子·成相》"}, {"t": "选天下之端士。", "b": "汉·贾谊《治安策》"}], "words": [{"w": "不端", "t": "不正派"}, {"w": "好端端的", "t": "好好儿的"}, {"w": "端一", "t": "端庄娴静"}, {"w": "端士", "t": "端人;正直的人"}, {"w": "正派;端楷", "t": "字写得工整"}, {"w": "端悫", "t": "端正笃实。悫:诚笃。"}]}, {"meaning": "事物的一头或一方面。", "cites": [{"t": "虽人有百手,手有百指,不能指其一端。", "b": "《虞初新志·秋声诗自序》"}, {"t": "东坡右手执卷端。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "两端,末端;笔端;尖端;大端", "t": "重要方面"}, {"w": "极端;顶端;扁担的两端", "t": ""}]}, {"meaning": "首;顶端。", "cites": [{"t": "常视松端日,每稽潭上烟。", "b": "宋·梅尧臣《昭亭别施度支》"}]}, {"meaning": "头绪。", "cites": [{"t": "多端寡要(要领),好谋无决。", "b": "《三国志·郭嘉传》"}], "words": [{"w": "端序", "t": "头绪;条理。"}]}, {"meaning": "事由;原委。", "cites": [{"t": "祸集非无端。", "b": "西晋·陆机《君子行》"}], "words": [{"w": "端原", "t": "原委;根由"}, {"w": "端本澄源", "t": "犹言正本清源"}, {"w": "争端;衅端", "t": ""}]}, {"meaning": "周代礼服。", "cites": [{"t": "宗庙之事,如会同,端章甫(章甫:古代礼帽),愿为小相焉。", "b": "《论语·先进》"}, {"t": "其齐服,有玄端素端。", "b": "《周礼》"}], "words": [{"w": "端衣", "t": "古代一种礼服。多用于丧祭场合"}, {"w": "端衰", "t": "古丧服上衣"}, {"w": "端冕", "t": "玄衣和大冠。古代帝王和贵族的礼服。"}]}, {"meaning": "办法。", "cites": [{"t": "今有难,无他端,而欲赴秦军,譬若以肉投馁虎,何功之有哉。", "b": "《史记·魏公子列传》"}]}, {"meaning": "究竟;到底。", "cites": [{"t": "这话原不须提了,总来该是夫妻,颠来倒去,自然凑着,不该是夫妻,便说合了,端只要分张。", "b": "《醉醒石》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3152wx','旗','1','qí','方','14','','[{"pinyin": "qí", "defs": [{"meaning": "同本义。", "cites": [{"t": "旗,熊旗五游,以象罚星,士卒以为期。", "b": "《说文》"}, {"t": "熊虎曰旗。", "b": "《广雅》"}, {"t": "师都建旗。", "b": "《周礼·春官》"}, {"t": "熊虎为旗及国之大阅。", "b": "《周礼·司常》"}, {"t": "望其旗靡。", "b": "《曹刿论战》"}]}, {"meaning": "泛指各种旗帜。", "cites": [{"t": "斩木为兵,揭竿为旗。", "b": "贾谊《过秦论》"}, {"t": "以为旗章。", "b": "《礼记·月令》"}, {"t": "旗所以立兵也,所以利兵也,所以偃兵也。", "b": "《管子·兵法》"}], "words": [{"w": "旗纛", "t": "古代军队和仪仗队用的大旗"}, {"w": "旗牌", "t": "担任传递号令等的武吏"}, {"w": "旗鼓", "t": "指枪棒等武艺的架式、门户"}, {"w": "旗头", "t": "旗手"}, {"w": "旗麾", "t": "将旗。"}]}, {"meaning": "内蒙古自治区的行政区划单位,相当于县。"}, {"meaning": "假借为“箕”。箕宿。二十八星宿之一。", "cites": [{"t": "寿于旗翼。", "b": "《荀子·富国》"}]}, {"meaning": "号令。", "cites": [{"t": "昔舜欲旗古今而不成。", "b": "《吕氏春秋·谕大》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3153wx','精','1','jīng','米','14','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从米,青声。本义:挑选过的好米,上等细米)。"}, {"meaning": "同本义。", "cites": [{"t": "精,择也。", "b": "《说文》"}, {"t": "鼓筴播精。", "b": "《庄子·人间世》"}, {"t": "食不厌精。", "b": "《论语》"}], "words": [{"w": "精凿", "t": "舂过的净米"}, {"w": "精粲", "t": "精米。"}]}, {"meaning": "精气。", "cites": [{"t": "祓除其心精也。", "b": "《国语·周语》"}, {"t": "精也者,气之精者也,气道乃生。", "b": "《管子·内业》"}, {"t": "天地之精。", "b": "《吕氏春秋·慎行论》"}, {"t": "二者用精至矣。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "精秀", "t": "精华灵秀之气"}, {"w": "精气命脉神", "t": "生命与血汗。比喻辛苦"}, {"w": "精血", "t": "精气和血液"}, {"w": "精胆", "t": "精气"}, {"w": "精耀", "t": "精气。"}]}, {"meaning": "精神;精力。", "cites": [{"t": "人死精亡而形存。", "b": "《论衡·论死》"}], "words": [{"w": "精采", "t": "精神,有活力"}, {"w": "精舍", "t": "学舍、书斋,聚徒讲学的地方"}, {"w": "精思", "t": "精力和思虑。"}]}, {"meaning": "精液。", "cites": [{"t": "男女构精。", "b": "《易·系辞》"}], "words": [{"w": "精子;精虫", "t": ""}]}, {"meaning": "精灵;灵魂。", "cites": [{"t": "血,气之精也;志,意之荣也。", "b": "《荀子·赋》"}, {"t": "精交接以来往兮。", "b": "宋玉《神女赋》"}], "words": [{"w": "精爽", "t": "灵魂"}, {"w": "精魄", "t": "精神魂魄"}, {"w": "精胆", "t": "魂魄,胆量。"}]}, {"meaning": "花。", "cites": [{"t": "将击芙蓉之精。", "b": "《文选·宋玉·风赋》"}]}, {"meaning": ""}, {"meaning": "星。", "cites": [{"t": "辩方位而正则,五精帅而来摧。", "b": "张衡《东京赋》"}]}, {"meaning": "日月之光。", "cites": [{"t": "精行四时。", "b": "《吕氏春秋·圜道》。高诱注:“精,日月之光明也。”"}]}, {"meaning": "水晶。", "cites": [{"t": "哀牢国出水精琉璃。", "b": "《后汉书·西南夷传》"}]}, {"meaning": ""}, {"meaning": "实情。", "cites": [{"t": "窈兮冥兮,其中有精,其精甚真,其中有信。", "b": "《老子·二十一章》"}, {"t": "瑕适皆见,精也。", "b": "《管子·水地》"}]}, {"meaning": "性情。", "cites": [{"t": "术顺墨而精杂汙,横行天下,虽达四方,人莫不贱。", "b": "《荀子·修身》"}, {"t": "心精好恶,于事验,谓之性。", "b": "《潜夫论·梦列》"}]}, {"meaning": "细致,精密。", "cites": [{"t": "精思傅会,十年乃成。", "b": "范晔《后汉书》"}], "words": [{"w": "精切", "t": "精确切当"}, {"w": "精造", "t": "精工制造"}, {"w": "精敏", "t": "精细敏捷"}, {"w": "精鉴", "t": "精细鉴别"}, {"w": "精审", "t": "精确详实"}, {"w": "精的", "t": "精确"}, {"w": "精备", "t": "精密详尽。"}]}, {"meaning": "纯洁;纯净。", "cites": [{"t": "精铜铸成。", "b": "《后汉书·张衡传》"}], "words": [{"w": "精楚", "t": "精美,精致漂亮"}, {"w": "精比", "t": "精纯细密"}, {"w": "精真", "t": "精粹纯真"}, {"w": "精诣", "t": "精到。谓学养精粹。"}]}, {"meaning": "精诚,专一。", "cites": [{"t": "中不精者心不治。", "b": "《管子·心术》"}, {"t": "心意不精。", "b": "《淮南子·修务》"}, {"t": "夫精念存想。", "b": "汉·王充《论衡》"}], "words": [{"w": "精勤", "t": "专心勤奋"}, {"w": "精虔", "t": "精心虔诚;诚心诚意"}, {"w": "精志", "t": "至诚的心志"}, {"w": "精信", "t": "精诚信实。"}]}, {"meaning": "清朗;光明。", "cites": [{"t": "日月光精。", "b": "《汉书·李寻传》"}], "words": [{"w": "精芒", "t": "光芒"}, {"w": "精晃晃", "t": "形容光亮"}, {"w": "精朗", "t": "明亮"}, {"w": "精全美玉", "t": "比喻纯洁完美的人或事物"}, {"w": "精剋", "t": "廉明克己"}, {"w": "精廉", "t": "清廉"}, {"w": "精息", "t": "明白"}, {"w": "精色", "t": "鲜明的色泽"}, {"w": "精沐", "t": "清明。清察明审"}, {"w": "精尽", "t": "明察详尽。"}]}, {"meaning": "锐利。", "cites": [{"t": "兵精粮多。", "b": "《资治通鉴》"}, {"t": "兵精足用。", "b": ""}, {"t": "精兵皆在。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "精手", "t": "精锐的兵卒"}, {"w": "精甲", "t": "精锐的军队"}, {"w": "精劲", "t": "精良锐利;精悍勇猛"}, {"w": "精勇", "t": "精强勇敢;精锐的士兵"}, {"w": "精强", "t": "精明高强"}, {"w": "精刻", "t": "精明能干"}, {"w": "精乖", "t": "聪明乖觉"}, {"w": "精记", "t": "精明强记。"}]}, {"meaning": "精妙,隐微奥妙。", "cites": [{"t": "其知弥精。", "b": "《吕氏春秋》"}, {"t": "精思附会。(精思:精妙构思。傅会:即附会,铺排开进行组织结构文章。)", "b": "《后汉书·张衡传》"}], "words": [{"w": "精阐", "t": "精妙的阐发"}, {"w": "精通;精言", "t": "精妙的言辞"}, {"w": "精理", "t": "精微的义理"}, {"w": "精趣", "t": "精妙的意趣"}, {"w": "精义入神", "t": "精研微妙的义理,进入神妙的境界。"}]}, {"meaning": "甚,很。", "cites": [{"t": "自蔽之精者。", "b": "《吕氏春秋·勿躬》。注:“甚也。”"}], "words": [{"w": "精湿", "t": "很湿,湿得很厉害"}, {"w": "精熟", "t": "十分熟练。"}]}, {"meaning": "深到;精通。", "cites": [{"t": "于是集谢庄少年之精技击者。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "习无不精。", "b": ""}], "words": [{"w": "精习", "t": "精深,熟悉"}, {"w": "精博", "t": "精深广博"}, {"w": "精究", "t": "精心研究"}, {"w": "精洽", "t": "精深广博。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3154wx','粹','1','cuì suì','米','14','','[{"pinyin": "cuì", "defs": [{"meaning": "(形声。从米,卒声。本义:精米)。"}, {"meaning": "同本义。", "cites": [{"t": "播精而择粹。", "b": "《天工开物》"}]}, {"meaning": "不含添加、替代或异质物质的;纯的。", "words": [{"w": "粹毛", "t": "纯色的毛"}, {"w": "粹正", "t": "纯正"}, {"w": "粹然", "t": "纯正的样子。"}]}]}, {"pinyin": "suì", "defs": [{"meaning": "", "words": [{"w": "粹析", "t": "破碎折断。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3155wx','歉','1','qiàn','欠','14','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从欠,兼声。本义:吃不饱)。"}, {"meaning": "同本义。", "cites": [{"t": "歉,食不满也。", "b": "《说文》"}, {"t": "健儿立霜雪,腹歉衣裳单。", "b": "李商隐《行次西郊作诗》"}]}, {"meaning": "收成不好。", "cites": [{"t": "一谷不升曰歉。", "b": "《广雅》"}], "words": [{"w": "歉荒", "t": "歉收;灾荒"}, {"w": "歉俭", "t": "荒歉"}, {"w": "歉薄", "t": "收成微薄。"}]}, {"meaning": "惭愧。对不住人的心情。", "cites": [{"t": "俯仰谬恩方自歉。", "b": "王安石《酬吴季野见寄》"}], "words": [{"w": "抱歉", "t": "心中不安,觉着对不住别人"}, {"w": "道歉;歉惜", "t": "遗憾与惋惜。"}]}, {"meaning": "少;不足。", "cites": [{"t": "歉,少也。", "b": "《广雅》"}, {"t": "主信爱之则谨慎而歉。", "b": "《荀子·仲尼》"}], "words": [{"w": "歉绌", "t": "短缺、不足。"}]}, {"meaning": "谦逊。", "cites": [{"t": "主信爱之则谨慎而歉。", "b": "《荀子·仲尼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3156wx','弊','1','bì','廾','14','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。字本作“獘”,从犬,敝声。从犬,表示被狗扑倒或遭狗咬而倒下。讹变为“弊”。本义:仆,向前倒下)。"}, {"meaning": "仆;向前倒下。", "cites": [{"t": "獘,?顿仆也。", "b": "《说文》"}, {"t": "射之獘一人。", "b": "《礼记·檀弓》"}, {"t": "质明,弊旗,诛后至者。", "b": "《周礼·大司马》"}]}, {"meaning": "倒毙;死亡。同“毙”。", "cites": [{"t": "以弊于鄢。", "b": "《国语·楚语》"}], "words": [{"w": "弊仆", "t": "倒毙。"}]}, {"meaning": "遮盖,遮挡。", "cites": [{"t": "八曰官计以弊邦治。", "b": "《周礼·大宰》"}, {"t": "凡庶民之狱讼以邦成弊之。", "b": "《周礼·司寇》"}, {"t": "见知不悖于前,赏罚不弊于后。", "b": "《韩非子·难一》"}]}, {"meaning": "判决,决定。", "cites": [{"t": "弊御于诸侯。", "b": "《史记·范蔡传》。索隐:“断也。”"}], "words": [{"w": "弊狱", "t": "判罪"}, {"w": "弊谋", "t": "决策。"}]}, {"meaning": "弊病,弊害。", "cites": [{"t": "举先王之政,以兴利除弊。", "b": "宋·王安石《答司马谏议书》"}, {"t": "皆指目(指责)朝政之弊。", "b": "《旧唐书·黄巢传》"}], "words": [{"w": "弊孔", "t": "产生弊害的漏洞"}, {"w": "弊象", "t": "弊病的迹象"}, {"w": "弊绝风清", "t": "形容社会风气特别好,贪污舞弊等坏事完全灭绝。"}]}, {"meaning": "坏,低劣。", "cites": [{"t": "变更天下之弊法。", "b": "宋·王安石《上皇帝万言书》"}], "words": [{"w": "弊事", "t": "恶事"}, {"w": "弊人", "t": "卑鄙的人。"}]}, {"meaning": "衰落,疲惫。", "cites": [{"t": "今三分天下,益州疲弊。", "b": "诸葛亮《出师表》"}, {"t": "率疲弊之卒,将数百之众。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "弊世", "t": "衰世"}, {"w": "弊民", "t": "疲惫之民。"}]}, {"meaning": "破旧,破损。", "cites": [{"t": "及期而往,告之曰:帝许我罚有罪矣,弊于韩。", "b": "《左传·僖公十年》"}, {"t": "岁时更续共其弊车。", "b": "《周礼·巾车》"}, {"t": "舌弊口,犹将无益也。", "b": "《荀子·正论》"}, {"t": "数十年之后,甲兵顿弊。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "弊席", "t": "破旧的草席"}, {"w": "弊帚千金", "t": "家有破旧的扫帚,犹自以价值千金。比喻各人珍惜自己的器物,或比喻人无自知之明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3157wx','熄','1','xī','火','14','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从火,息声。本义:火熄灭)。"}, {"meaning": "同本义。", "cites": [{"t": "熄,畜火也。从火,息声。亦曰灭火。", "b": "《说文》。按,蓄与灭一义之引申。"}], "words": [{"w": "熄火罐头", "t": "指能降伏擒拿凡人的法宝"}, {"w": "熄火;熄灯", "t": "灭灯"}, {"w": "火势已熄", "t": ""}]}, {"meaning": "消亡;平息;止。", "cites": [{"t": "安居而天下熄。", "b": "《孟子·滕文公下》"}, {"t": "王者之迹熄而诗亡。", "b": "《孟子·离娄下》"}], "words": [{"w": "熄讼", "t": "平息争议。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3158wx','熔','1','róng','火','14','','[{"pinyin": "róng", "defs": [{"meaning": "(熔为鎔的俗字。形声。从火,容声。本义:用高温使固体物质转变为液态) 同本义。", "cites": [{"t": "鎔,冶器法也。", "b": "《说文》"}, {"t": "用讫再火令药熔。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "熔炼", "t": "熔化炼制;喻培养"}, {"w": "熔造", "t": "将固体熔化后,再铸造新的器物"}, {"w": "熔铄", "t": "熔化金属。"}]}, {"meaning": "铸造器物的模子。", "cites": [{"t": "犹金之在鎔,惟冶者之所为。", "b": "《汉书·董仲舒传》"}, {"t": "冶熔吹炭。", "b": "《汉书·食货志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3159wx','煽','1','shān','火','14','','[{"pinyin": "shān", "defs": [{"meaning": "(形声。从火,扇声。本义:火炽盛) 同本义。", "cites": [{"t": "傓,炽盛也。从人,扇声。", "b": "《说文》"}, {"t": "艳妻煽方处。", "b": "《诗·小雅·十月之交》。按,傓、煽皆后出字,皆因诗辞而制也。鲁诗:阎妻扇方处,是本字。"}, {"t": "火井沉荧于幽泉,高焰飞煽于天垂。", "b": "左思《蜀都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3160wx','潇','1','xiāo','氵','14','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从水,萧声。本义:水清而深的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "潇者,水清深也。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3161wx','漆','1','qī','氵','14','','[{"pinyin": "qī", "defs": [{"meaning": "(形声。从水,桼声。本义:漆水)。"}, {"meaning": "同本义。古水名。"}, {"meaning": "渭水支流,今名漆水河。发源于陕西麟游县西,东南流至武功县西,注入渭水。"}, {"meaning": "在陕西省邠县西,流注泾水。"}, {"meaning": "石川河上源之一。发源于陕西铜川市北,南流至耀县与沮水合为石川河,又南流至高陵县东注入渭水。"}, {"meaning": "油漆树 。一种漆树科落叶乔木,从其树皮可割取天然漆。"}, {"meaning": "油漆 用漆树汁制成的涂料。", "cites": [{"t": "鱼盐漆丝。", "b": "《史记·货殖列传》"}]}, {"meaning": "漆器。", "cites": [{"t": "器用瓷漆。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "数词。", "cites": [{"t": "夕见漆十士。", "b": "《墨子·贵义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3162wx','漱','1','shù','氵','14','','[{"pinyin": "shù", "defs": [{"meaning": "形声。# 同本义。", "cites": [{"t": "漱,盪口也。", "b": ""}, {"t": "咸盥漱。", "b": "《礼记·内则》"}, {"t": "凡内外,鸡初鸣,咸盥漱。", "b": "《礼·内则》"}], "words": [{"w": "漱盂", "t": "盛漱口水的器皿"}, {"w": "漱流", "t": "以流水漱口。比喻隐居生活"}, {"w": "漱盥", "t": "漱口盥洗。"}]}, {"meaning": "洗涤。", "cites": [{"t": "冠带垢,和灰清漱。", "b": "《礼记·内则》"}], "words": [{"w": "漱涤", "t": "洗涤"}, {"w": "漱澣", "t": "洗涤"}, {"w": "漱浣", "t": "洗涤"}, {"w": "漱濯", "t": "洗涤。"}]}, {"meaning": "冲刷;冲荡。", "cites": [{"t": "悬泉瀑布,飞漱其间。", "b": "郦道元《水经注·江水》"}, {"t": "善沟者水漱之。", "b": "《考工记·匠人》"}, {"t": "石泉漱琼瑶。", "b": "左思《招隐诗》"}, {"t": "沈液漱陈根。", "b": "张协《杂诗》"}], "words": [{"w": "漱石", "t": "冲刷岩石"}, {"w": "漱石枕流", "t": "枕石漱流。比喻士人的隐居生活"}, {"w": "漱玉", "t": "形容山泉激石,飞流溅白,晶莹如玉"}, {"w": "漱啮", "t": "侵蚀,冲荡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3163wx','漂','1','piāo piǎo piào','氵','14','','[{"pinyin": "piāo", "defs": [{"meaning": "(形声。从水,票声。本义:浮,浮流)。"}, {"meaning": "同本义。", "cites": [{"t": "漂,浮也。", "b": "《说文》"}, {"t": "血流漂杵。", "b": "《伪书武成》"}, {"t": "漂通川之碄碄。", "b": "张衡《思玄赋》"}, {"t": "流血漂橹。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "漂泼", "t": "漂泊"}, {"w": "漂泛", "t": "浮舟而行,随波飘流"}, {"w": "漂拔", "t": "漂浮拔起"}, {"w": "漂海", "t": "漂浮于海上"}, {"w": "漂橹", "t": "漂浮船桨"}, {"w": "漂激", "t": "漂流激动"}, {"w": "漂杵", "t": "浮起舂杵。形容恶战流血之多。"}]}, {"meaning": "漂泊。流浪在外,东奔西走。", "cites": [{"t": "辞浮漂而不归。", "b": "陆机《文赋》"}], "words": [{"w": "漂寄", "t": "暂时寄居"}, {"w": "漂汩", "t": "漂浪,漂荡,漂薄,漂逢,漂零,漂泊"}, {"w": "漂沉", "t": "漂泊沉沦"}, {"w": "漂沦", "t": "漂泊流落"}, {"w": "漂寓", "t": "湮泊寄居"}, {"w": "漂泼", "t": "漂泊,行止不定。"}]}, {"meaning": "吹;使飘荡。", "cites": [{"t": "风其漂女。", "b": "《诗·郑风·萚兮》"}], "words": [{"w": "漂曳", "t": "飘摆,摇曳"}, {"w": "漂沫", "t": "谓泡沫飘飞"}, {"w": "漂沸", "t": "飘动;飘流"}, {"w": "漂落", "t": "漂零沦落"}, {"w": "漂零", "t": "飘落,坠落"}, {"w": "飘遥", "t": "随风摇动"}, {"w": "漂荡", "t": "飘飞;飘扬"}, {"w": "漂洒", "t": "漂零洒落。"}]}, {"meaning": "摇动;摇荡。", "cites": [{"t": "漂昆侖。", "b": "扬雄《长杨赋》。注:“摇荡之也。”"}], "words": [{"w": "漂摇", "t": "动荡不安。"}]}, {"meaning": "迅速;快疾。", "cites": [{"t": "迅漂巧兮。", "b": "王褒《洞箫赋》"}], "words": [{"w": "漂疾", "t": "水流急涌快速。"}]}]}, {"pinyin": "piǎo", "defs": []}, {"pinyin": "piào", "defs": [{"meaning": "古水名。", "cites": [{"t": "又南有山,漂水出焉。", "b": "《山海经》"}]}, {"meaning": "没付欠账。", "cites": [{"t": "上仔客人个当,一千多局账漂下来。", "b": "《孽海花》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3164wx','漫','1','màn','氵','14','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。从水,曼声。本义:水过满向外流)。"}, {"meaning": "同本义。", "cites": [{"t": "诸山崩,鸿水溢。", "b": "《三国志·吴主传》"}, {"t": "譬如写水著地,正自纵横流漫,略无正方圆者。", "b": "《世说新语·文学》"}, {"t": "渐见江势阔,行嗟水流漫。", "b": "宋之问《自湘源至潭州衡山县》"}], "words": [{"w": "漫溢", "t": "水满向外流"}, {"w": "漫口", "t": "堤岸被水冲溃"}, {"w": "水漫金山;漫溃", "t": "水涨破堤而出"}, {"w": "漫泄", "t": "水满外流"}, {"w": "漫流", "t": "水势很大的河流"}, {"w": "漫然", "t": "浩大的样子"}, {"w": "漫滋", "t": "形容水涨溢漫延"}, {"w": "漫衍", "t": "泛滥。"}]}, {"meaning": "充满;遍,周遍。", "cites": [{"t": "亭东自足下皆云漫。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "漫天彻地", "t": "弥漫天空,充满地面。形容势头极大"}, {"w": "漫山", "t": "满山,遍山"}, {"w": "漫天盖地", "t": "遍布天地之间"}, {"w": "漫野", "t": "遍野"}, {"w": "漫荡荡", "t": "遍布的样子。"}]}, {"meaning": "隔。", "cites": [{"t": "你这不去,惹的大的们恼了,这才“漫墙撩胳膊,丢开手”了。", "b": "《醒世姻缘传》"}]}, {"meaning": "污;玷污。", "cites": [{"t": "又欲以其辱行漫我。(辱行:坏品行)", "b": "《庄子·让王》"}]}, {"meaning": "放纵;散漫;不受约束。", "cites": [{"t": "公漫久矣。", "b": "欧阳修《新唐书》"}], "words": [{"w": "漫家", "t": "不受门户限制的学派"}, {"w": "漫天要价", "t": "无限度地乱要价。"}]}, {"meaning": "长的样子;辽远的样子。", "cites": [{"t": "别日何易会日难,山川悠远路漫漫。", "b": "三国魏·曹丕《燕歌行》"}], "words": [{"w": "漫远", "t": "漫长遥远"}, {"w": "漫长", "t": "长得没有尽头的"}, {"w": "路漫漫;夜漫漫", "t": ""}]}, {"meaning": "模糊。", "cites": [{"t": "其远古刻尽漫失。", "b": "姚鼐《登泰山记》"}], "words": [{"w": "漫失", "t": "模糊剥蚀"}, {"w": "漫略", "t": "文辞模糊简略"}, {"w": "漫暗", "t": "模糊不清"}, {"w": "漫剥", "t": "因剥蚀脱落而模糊不清。"}]}, {"meaning": "随便;随意。", "cites": [{"t": "漫卷诗书喜欲狂。", "b": "唐·杜甫《闻官军收河南河北》"}], "words": [{"w": "漫然", "t": "随便的样子"}, {"w": "漫抄", "t": "随手写录"}, {"w": "漫书", "t": "随意书写"}, {"w": "漫言", "t": "随便地说"}, {"w": "漫叩", "t": "随便发问"}, {"w": "漫识", "t": "随手记载"}, {"w": "漫题", "t": "信手书写的文字。"}]}, {"meaning": "徒然。", "cites": [{"t": "漫劳车马驻江干。", "b": "杜甫《宾至》"}]}, {"meaning": "遍;普遍。", "cites": [{"t": "漫撒子(种籽)。", "b": "《齐民要术》"}]}, {"meaning": "都;全。", "cites": [{"t": "漫不敢可否事。", "b": "胡铨《上高宗封事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3165wx','滴','1','dī','氵','14','','[{"pinyin": "dī", "defs": [{"meaning": "(形声。从水,啇(dí)声。本义:液体一点一点落下来。成语:滴水成冰) 同本义。", "cites": [{"t": "滴,水注也。", "b": "《说文》"}, {"t": "若何滴滴。", "b": "《列子·力命》"}, {"t": "临岐别数子,握手泪再滴。", "b": "唐·杜甫《发同谷县》"}], "words": [{"w": "滴沥", "t": "水下滴"}, {"w": "滴溜", "t": "涓滴的水"}, {"w": "滴水", "t": "滴下来的水"}, {"w": "滴溜当啷", "t": "不断下滴的样子。"}]}, {"meaning": "水点;点点下落的液体 。如:水滴;雨滴。也用以形容像水滴那样圆的物体。如:滴子(垂珠)。"}, {"meaning": "多用于颗粒状滴下的液体。", "cites": [{"t": "十日不饮一滴浆。", "b": "王建《伤邻家鹦鹉词》"}], "words": [{"w": "洒下几滴眼泪", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3166wx','漾','1','yàng','氵','14','','[{"pinyin": "yàng", "defs": [{"meaning": "古水名。漾水。"}, {"meaning": "汉水上流,源出陕西省宁羌县北潘冢山。"}, {"meaning": "即今嘉陵江上源的西汉水。", "cites": [{"t": "漾,漾水。出陇西相氐道,东至武都为汉。", "b": "《说文》"}]}, {"meaning": "水动荡。水面上起波纹;有细浪起伏。", "cites": [{"t": "涟漪繁波漾。", "b": "谢惠连《泛南湖至石帆》"}], "words": [{"w": "漾驰", "t": "水流平缓。"}]}, {"meaning": "抛掷;丢弃。", "cites": [{"t": "把一大块石头漾在奉符县河里。", "b": "《喻世明言》"}], "words": [{"w": "漾开", "t": "抛开;离开"}, {"w": "漾砖", "t": "投掷砖块。"}]}, {"meaning": "水流长。", "cites": [{"t": "川既漾而济深。", "b": "汉·王粲《登楼赋》"}], "words": [{"w": "漾漭", "t": "漫溢广远的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3167wx','演','1','yǎn','氵','14','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从水,寅声。本义:水长流)。"}, {"meaning": "同本义。", "cites": [{"t": "演,长流也。", "b": "《说文》"}, {"t": "南国风光当世少,西陵演浪过江难。", "b": "李白《代封人寄翁参枢先輩》"}, {"t": "子未闻杨都之巨伟也,左沧海,右岷山,龟鸟津其落,江汉演其源。", "b": "《艺文类聚》"}]}, {"meaning": "水流经地下。", "cites": [{"t": "演以潜沫,浸以绵雒。", "b": "《文选·左思·蜀都赋》。刘逵注:“水潜行曰演。此二水伏流,故曰‘演以潜沫’。”"}]}, {"meaning": "延展。", "cites": [{"t": "演,延也,言蔓延而广也。", "b": "《释名·释言语》"}, {"t": "留侯演成。", "b": "班固《西都赋》"}, {"t": "有所摇演。", "b": "马融《长笛赋》"}], "words": [{"w": "演延", "t": "绵延,广远"}, {"w": "演迤", "t": "绵延不绝貌"}, {"w": "演溢", "t": "蔓延满溢。"}]}, {"meaning": "湿润。", "cites": [{"t": "夫水土演而民用也。", "b": "《国语·周语》"}]}, {"meaning": "推演。", "cites": [{"t": "于是敷演旧章,奏而改焉。", "b": "《三国志·高堂隆传》"}, {"t": "敷演皇极,流化万里。", "b": "《三国志·胡综传》"}], "words": [{"w": "演禽星", "t": "占卜的一种,以星禽推知人事吉凶"}, {"w": "演证", "t": "推演证明"}, {"w": "演绎法", "t": "即演绎推理。"}]}, {"meaning": "传布。", "cites": [{"t": "主公,若演真经,须寻佛地。", "b": "《西游记》"}], "words": [{"w": "演迤", "t": "流布;流传"}, {"w": "演法", "t": "谓传布教义的方式"}, {"w": "演教", "t": "传布教化或指传布佛教教义"}, {"w": "演迪", "t": "谓继承推广。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3168wx','漏','1','lòu','氵','14','','[{"pinyin": "lòu", "defs": [{"meaning": "(形声。从水,屚(lòu)声。本义:漏壶的简称。古代滴水计时的仪器)。"}, {"meaning": "同本义。", "cites": [{"t": "漏尽钟鸣,箭驰风追。", "b": "《马稚暨妻张氏墓志》"}, {"t": "漏,以铜受水,刻节。", "b": "《说文》。按:这就是铜壶滴漏的“漏”。"}, {"t": "晷漏肃唱。", "b": "《文选·左思·魏都赋》"}, {"t": "漏刻,谓以筒受水,刻节,昼夜百刻也。", "b": "《华严经音义下引文字集略》"}], "words": [{"w": "漏下", "t": "漏刻的水面已经下落"}, {"w": "漏永更长", "t": "比喻深夜"}, {"w": "漏尽钟鸣", "t": "黎明时分"}, {"w": "漏夜", "t": "深夜"}, {"w": "漏板", "t": "古代报更用的铜板"}, {"w": "漏刻", "t": "古计时器。"}]}, {"meaning": "孔隙,孔穴;漏洞。", "cites": [{"t": "禹耳参漏。", "b": "《淮南子·修务》"}], "words": [{"w": "漏目", "t": "漏洞"}, {"w": "漏眼", "t": "漏洞,毛病"}, {"w": "漏窗", "t": "具有各种漏空图案的窗孔"}, {"w": "漏风掌", "t": "漏风的巴掌。五指分开的巴掌。"}]}, {"meaning": "时刻,时间。", "cites": [{"t": "二岁余,贤传漏在殿下。", "b": "《汉书·佞幸传·董贤》。注:“传漏,奏时刻。”"}]}, {"meaning": "臭味。", "cites": [{"t": "马黑脊而般臂,漏。", "b": "《礼记·内则》"}]}, {"meaning": "房顶漏雨。", "cites": [{"t": "床头屋漏无干处,雨脚如麻未断绝。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "漏天", "t": "如天泻漏"}, {"w": "漏屋", "t": "漏雨的房屋。"}]}, {"meaning": "泄露;泄密。", "cites": [{"t": "今为人主而漏其群臣之语。", "b": "《韩非子》"}], "words": [{"w": "漏师", "t": "泄漏军中的机密大事"}, {"w": "漏语", "t": "泄漏机密"}, {"w": "漏露", "t": "泄露"}, {"w": "漏信", "t": "走漏消息。"}]}, {"meaning": "遗漏;疏忽。", "cites": [{"t": "号为罔漏吞舟之鱼。", "b": "班固《汉书》"}], "words": [{"w": "漏刃", "t": "从刀下漏过"}, {"w": "漏名", "t": "谓在贺新天子即位的册牒上的漏署姓名"}, {"w": "漏略", "t": "遗漏疏忽"}, {"w": "漏逸", "t": "遗漏阙失"}, {"w": "漏迹", "t": "遗漏的痕迹"}, {"w": "漏夺", "t": "漏脱。"}]}, {"meaning": "诱骗;引诱。", "cites": [{"t": "因此特说些风话,漏你下手。", "b": "《水浒传》"}]}, {"meaning": "遮,藏。", "cites": [{"t": "当初也无定无媒证,做的来藏头漏影。", "b": "元·佚名《鸳鸯被》"}]}, {"meaning": "狭小。", "cites": [{"t": "虽隐於穷阎漏屋。", "b": "《荀子·儒效》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3169wx','慢','1','màn','忄','14','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。从心,曼声。本义:轻慢;对人无礼貌)。"}, {"meaning": "同本义。", "cites": [{"t": "慢,一曰不畏也。", "b": "《说文》"}, {"t": "慢,惰也。", "b": "《广雅》"}, {"t": "我远而慢之。", "b": "《左传·襄公三十一年》"}, {"t": "可敬不可慢。", "b": "《礼记·缁衣》"}, {"t": "而长不简慢矣。", "b": "《吕氏春秋·处方》"}, {"t": "君使民慢,乱将作矣。", "b": "《左传·庄公八年》"}, {"t": "敬贤者存,慢贤者亡。", "b": "《荀子·君子》"}, {"t": "荆成王慢焉。", "b": "《吕氏春秋·上德》"}, {"t": "其慢若彼之甚也;见贤人若此其肃也。", "b": "《庄子·则阳》"}, {"t": "管家,实是多慢了你。", "b": "《儒林外史》"}], "words": [{"w": "慢骂", "t": "信口乱骂"}, {"w": "慢亵", "t": "慢待;招待不周"}, {"w": "慢狎", "t": "轻侮"}, {"w": "慢视", "t": "轻视"}, {"w": "慢公", "t": "怠忽公务"}, {"w": "慢令", "t": "轻慢上司的命令"}, {"w": "慢心", "t": "轻慢之心。"}]}, {"meaning": "怠慢。", "cites": [{"t": "责攸之、伟、允等之慢。", "b": "诸葛亮《出师表》"}], "words": [{"w": "慢客", "t": "怠慢客人。"}]}, {"meaning": "欺骗。", "cites": [{"t": "田驷东慢齐侯,南欺荆王。", "b": "《韩非子·说林上》"}]}, {"meaning": "涂抹。", "cites": [{"t": "郢人垩慢其鼻端。", "b": "《庄子·徐无鬼》"}]}, {"meaning": "懒惰。", "cites": [{"t": "慢,惰也。", "b": "《说文》"}, {"t": "政宽则民慢,慢则纠之以猛。", "b": "《左传·昭公二十年》"}, {"t": "啴谐慢易。", "b": "《礼记·乐记》"}], "words": [{"w": "慢憧", "t": "懈怠动摇"}, {"w": "慢志", "t": "怠懈的心智"}, {"w": "慢官", "t": "闲散的官职。"}]}, {"meaning": "不及时,迟了。", "cites": [{"t": "不及时日,渴葬也;不及时而不日,慢葬也。", "b": "《公羊传·隐公三年》"}]}, {"meaning": "从慢走引申为缓慢。", "cites": [{"t": "叔马慢忌,叔发罕异。", "b": "《诗·郑风·大叔于田》"}, {"t": "轻拢慢捻抹复挑。", "b": "白居易《琵琶行》"}], "words": [{"w": "慢慢交", "t": "慢慢地;不着急"}, {"w": "慢腾斯礼", "t": "慢条斯理;慢腾腾,不慌不忙的样子"}, {"w": "慢板", "t": "戏曲中缓慢的曲调"}, {"w": "慢慢", "t": "缓慢;犹言缓一缓"}, {"w": "慢节奏", "t": "乐曲中的缓慢节奏"}, {"w": "慢药", "t": "药性发作缓慢的毒药"}, {"w": "慢声", "t": "缓慢悠扬的音乐"}, {"w": "慢工出巧匠", "t": "谓慢而细致的操作能培养出精巧的匠师"}, {"w": "慢工出细货", "t": "缓慢的操作会产生出精巧的产品来。"}]}, {"meaning": "骄傲;傲慢。", "cites": [{"t": "上慢下暴。", "b": "《易·系辞上》"}], "words": [{"w": "慢世", "t": "傲世,玩世不恭"}, {"w": "慢词", "t": "不恭敬的言词"}, {"w": "慢书", "t": "侮辱性的书简。"}]}, {"meaning": "生疏。", "cites": [{"t": "那张清原来只有飞石打将的本事,枪法上却慢。", "b": "《水浒传》"}], "words": [{"w": "慢仗", "t": "武艺不精,本领不强。"}]}, {"meaning": "徒然。", "cites": [{"t": "麒麟慢有擎天才,怎出军师妙计中。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3170wx','慷','1','kāng','忄','14','','[{"pinyin": "kāng", "defs": [{"meaning": "(形声。从心,康声。本义:情绪激昂)。"}, {"meaning": "同本义。", "cites": [{"t": "慨当以慷,忧思难忘。", "b": "曹操《短歌行》"}], "words": [{"w": "慷惋", "t": "愤激怨恨"}, {"w": "慷忾", "t": "慷慨。意气高昂"}, {"w": "慷慨赴死", "t": "意气激昂,不畏死难"}, {"w": "慷他人之慨", "t": "慷慨他人的财物来作自己的人情。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3171wx','寨','1','zhài','宀','14','','[{"pinyin": "zhài", "defs": [{"meaning": "(形声。从木,赛省声。本义:防卫所用的木栅)。"}, {"meaning": "同本义。", "cites": [{"t": "敌军已近寨。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "寨中人踡伏。", "b": ""}, {"t": "借寨墙为蔽。", "b": ""}]}, {"meaning": "多指四面环围的驻军处,营垒。", "cites": [{"t": "时巴山陈定亦拥兵立寨。", "b": "《陈书》"}], "words": [{"w": "寨落", "t": "有栅栏或围墙的村落"}, {"w": "寨垛", "t": "寨墙上的垛口"}, {"w": "寨屋", "t": "营房。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3172wx','赛','1','sài','贝','14','','[{"pinyin": "sài", "defs": [{"meaning": "(形声。从贝,塞省声。本义:行祭礼以酬神)。"}, {"meaning": "同本义。", "cites": [{"t": "冬赛祷祠。", "b": "《史记·封禅书》。索隐:“赛谓报神福也。”"}, {"t": "朝析暮赛依巫口。", "b": "白居易《新乐府·黑潭龙》"}], "words": [{"w": "赛文", "t": "古代因年谷丰收为酬神而作的祭文"}, {"w": "赛还", "t": "祭祀还愿"}, {"w": "赛愿", "t": "祭神还愿"}, {"w": "赛神", "t": "祭祀以报答神明"}, {"w": "赛馔", "t": "祭神的食品"}, {"w": "赛宝", "t": "供祭宝物"}, {"w": "赛祷", "t": "祭祀酬神。"}]}, {"meaning": "比试。", "cites": [{"t": "与孝文往复赌赛。", "b": "《北史·魏任城王澄传》"}], "words": [{"w": "赛球;赛斗", "t": "比赛"}, {"w": "赛灯", "t": "赛花灯"}, {"w": "赛锦标社", "t": "竞技场"}, {"w": "赛饭", "t": "比赛酒量大小"}, {"w": "赛花灯", "t": "元宵节前后展出各种彩灯比美。"}]}, {"meaning": "胜过;如同。", "cites": [{"t": "国貌天香无物赛。", "b": "杜安世《玉楼春》"}], "words": [{"w": "赛过", "t": "方言。远比;比如"}, {"w": "赛月明", "t": "类似夜战中的信号弹"}, {"w": "赛香炉", "t": "意为风景秀丽,赛过了庐山上的香炉峰"}, {"w": "赛阎罗", "t": "铁面无私赛过阎王"}, {"w": "赛盖", "t": "胜过;比得上"}, {"w": "赛强如", "t": "胜过"}, {"w": "赛例", "t": "榜样,可以相比之例。"}]}, {"meaning": "完毕,了结。", "cites": [{"t": "自赛了儿婚女嫁,却归来林下。", "b": "马致远《新水令》套曲"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3173wx','寡','1','guǎ','宀','14','','[{"pinyin": "guǎ", "defs": [{"meaning": "少;缺少。", "cites": [{"t": "寡,少也。", "b": "《说文》"}, {"t": "曹操比于袁绍,则名微而众寡。", "b": "《三国志·诸葛亮传》"}, {"t": "不患寡而患不均。", "b": "《论语·季氏》"}], "words": [{"w": "寡尤", "t": "少犯错误"}, {"w": "寡功", "t": "功效少"}, {"w": "寡见", "t": "见识少"}, {"w": "寡交", "t": "与人交往少。"}]}, {"meaning": "孤独;孤单。", "cites": [{"t": "寡,独也。", "b": "《广雅·释诂三》"}, {"t": "生成及彊而寡。", "b": "《左传·襄公二十七年》"}, {"t": "南面称寡。", "b": "《吕氏春秋·士容》"}, {"t": "自谓孤寡。", "b": "《老子》"}], "words": [{"w": "寡老", "t": "孤独的老人"}, {"w": "寡孤", "t": "孤独,孤寂"}, {"w": "寡女", "t": "独居无偶的妇女"}, {"w": "寡立", "t": "犹独立;孤单"}, {"w": "寡草", "t": "孤生的草。"}]}, {"meaning": "倒霉;不吉利。", "cites": [{"t": "今早空肚皮进城,就吃了这一肚寡气。", "b": "《古今小说·沈小霞相会出师表》"}]}, {"meaning": "淡而无味。", "cites": [{"t": "清汤寡水", "b": ""}]}, {"meaning": "寡妇,丈夫死去后还未再嫁的女人。", "cites": [{"t": "哀鳏寡(此指老而无夫的女人);恤孤独。", "b": "《战国策·齐策》"}, {"t": "无夫曰寡。", "b": "《释名》"}, {"t": "爰及矜人,哀此鳏寡。", "b": "《诗·小雅·鸿雁》"}, {"t": "行人驻足听,寡妇起彷徨。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "鳏寡", "t": ""}]}, {"meaning": "(会意。金文字形,从“宀”(mián),从“页”(xié),是一个人独处屋下的形象。本义:古代妇人丧夫,男子无妻或丧偶,都叫寡)。"}, {"meaning": "同本义。", "cites": [{"t": "凡无妻无夫通谓之寡。", "b": "《小尔雅·广义》"}, {"t": "齐崔杼生成及强而寡(此指丧偶的男人)。", "b": "《左传·襄公二十七年》"}], "words": [{"w": "寡夫", "t": "无妻的男子"}, {"w": "寡汉", "t": "没有配偶的男子"}, {"w": "寡处", "t": "无偶独居"}, {"w": "寡鹤", "t": "失偶的鹤"}, {"w": "寡鹄", "t": "失偶的天鹅。"}]}, {"meaning": "减少。", "cites": [{"t": "轻则寡谋。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "寡过", "t": "减少过失。"}]}, {"meaning": "舍弃。", "cites": [{"t": "使干将寡刺而更击,蛢舍鹊而射雁,则下射无失矣。", "b": "《论衡·书解》"}]}, {"meaning": "丧失配偶。", "cites": [{"t": "卓王孙有女文君,新寡。", "b": "《史记·司马相如传》"}]}, {"meaning": "后渐以专指妇人丧夫。", "cites": [{"t": "是时,卓王孙有女文君新寡,好音,故相如缪与令相重而以琴心挑之。", "b": "《汉书·司马相如传上》"}]}, {"meaning": "古代王侯的谦称。", "cites": [{"t": "寡人非能好先王之乐也,直好世俗之乐耳。", "b": "《孟子·梁惠王下》"}, {"t": "寡君闻吾子将步师出于敝邑,敢犒从者。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "寡君", "t": "古代臣子对别国称自己国君的谦称"}, {"w": "寡臣", "t": "古代国君自称的谦词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3174wx','察','1','chá','宀','14','','[{"pinyin": "chá", "defs": [{"meaning": "(形声。从宀(mián),祭声。本义:观察;仔细看)。"}, {"meaning": "同本义。", "cites": [{"t": "察,复审也。", "b": "《说文》"}, {"t": "览察草木。", "b": "《楚辞·离骚》"}, {"t": "纤微皆审谓之察。", "b": "贾谊《道术》"}, {"t": "察其所以然。", "b": "《吕氏春秋·本味》"}, {"t": "微察公子,公子颜色愈和。", "b": "《史记·魏公子列传》"}, {"t": "徐而察之,则山下皆石穴罅。", "b": "宋·苏轼《石钟山记》"}], "words": [{"w": "观察", "t": "仔细察看客观事物或现象"}, {"w": "觉察", "t": "发觉,看出来。"}]}, {"meaning": "明察,知晓。", "cites": [{"t": "小大之狱,虽不能察,必以情。", "b": "《左传·庄公十年》"}, {"t": "故察己则可以人。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "察士", "t": "能明察事理的人"}, {"w": "察议", "t": "察明情节而议定处分。通常指过失较轻者。"}]}, {"meaning": "调查;考察。", "cites": [{"t": "夫传言不可以不察。", "b": "《吕氏春秋·察传》"}], "words": [{"w": "察勘", "t": "实地调查"}, {"w": "察访", "t": "详细调查。"}]}, {"meaning": "分辨。", "cites": [{"t": "观物弗之察矣。", "b": "《礼记·礼器》。注:“犹分辨也。”"}, {"t": "视之可察 。", "b": "《淮南子·说林》。注:“别也。”"}, {"t": "尝百草之实,察酸苦之味。", "b": "《新语·道基》"}]}, {"meaning": "考察后予以推举,举荐。", "cites": [{"t": "乃察举吾弟。", "b": "《史记·刺客传》。索隐:“犹选之也。”"}, {"t": "察臣孝廉。", "b": "晋·李密《陈情表》"}], "words": [{"w": "察举", "t": "选举,选拔"}, {"w": "察廉", "t": "举廉"}, {"w": "察选", "t": "察举。选拔。"}]}, {"meaning": "明显;精明。", "cites": [{"t": "水至清则无鱼,人至察则无徒。", "b": "东方朔《答客难》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3175wx','蜜','1','mì','虫','14','','[{"pinyin": "mì", "defs": [{"meaning": "(形声。从虫,宓(mì)声。本义:蜂蜜,蜜蜂采取花液酿成的甜汁)。"}, {"meaning": "同本义。", "cites": [{"t": "蜜为蜂液,食蜜少多,则令人毒。", "b": "汉·王充《论衡》"}], "words": [{"w": "蜜勺", "t": "蜜酒"}, {"w": "蜜供", "t": "涂有蜜汁的糕点"}, {"w": "蜜酒", "t": "以蜂蜜酿造而成的酒"}, {"w": "蜜浆", "t": "以蜂蜜制作的饮料"}, {"w": "蜜饵", "t": "在米面中加蜜调制而成的糕饼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3176wx','寥','1','liáo','宀','14','','[{"pinyin": "liáo", "defs": [{"meaning": "假借为“赖”。凭依;聊赖。", "cites": [{"t": "上下不相宁,吏民不相寥。", "b": "《淮南子·兵略》。按,与国策民无所聊。"}]}, {"meaning": "(本作廫。形声。从宀(mián),本义:空虚;寂静)。"}, {"meaning": "同本义。", "cites": [{"t": "廫,空虚也。字亦作寥。", "b": "《说文》"}, {"t": "乃入于寥天。", "b": "《庄子·大宗师》"}, {"t": "犹焦明已翔乎寥廓。", "b": "司马相如《难蜀父老》"}, {"t": "今欲使天下寥廓之上。", "b": "《汉书·邹阳传》"}, {"t": "寂兮寥兮,独立而不改。", "b": "《老子》"}, {"t": "恣心目之寥朗。", "b": "孙绰《游天台山赋》"}], "words": [{"w": "寥朗", "t": "空虚明朗"}, {"w": "寥天", "t": "道教的所谓虚无之境。即太虚"}, {"w": "寥廓", "t": "空虚"}, {"w": "寥然", "t": "寂静的样子"}, {"w": "寥寥", "t": "空寂;孤单"}, {"w": "寥阒", "t": "寂静"}, {"w": "寥天一", "t": "清静无为的人入于寂寥,和无形的天合而为一。"}]}, {"meaning": "冷清,冷落,寂寞。", "cites": [{"t": "寥落悲前事,支离笑此生。", "b": "唐·戴叔伦《除夜宿石头驿》"}], "words": [{"w": "寥萧;寥落", "t": "荒凉冷落"}, {"w": "寥寞", "t": "冷清;孤单。"}]}, {"meaning": "稀少,稀稀拉拉。", "cites": [{"t": "晓星正寥落。", "b": "谢元暉《京路夜发诗》"}], "words": [{"w": "寥梢", "t": "亦作“寥稍”。稀少"}, {"w": "寥寥", "t": "形容数量很少。"}]}, {"meaning": "深远。", "cites": [{"t": "寥,深也。", "b": "《广雅》"}], "words": [{"w": "寥邈", "t": "高远;遥远。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3177wx','谭','1','tán','讠','14','','[{"pinyin": "tán", "defs": [{"meaning": "(形声。从言,覃声。本义:同“谈”,说)。"}, {"meaning": "同本义。", "cites": [{"t": "夫子何不谭我于王。", "b": "《庄子·则阳》"}], "words": [{"w": "谭笑", "t": "谈笑"}, {"w": "谭艺", "t": "谈论文学艺术"}, {"w": "谭说", "t": "议论;谈论"}, {"w": "谭吐", "t": "说话时的措词和态度"}, {"w": "谭助", "t": "谈资"}, {"w": "谭言微中", "t": "说话隐微曲折而切中事理。"}]}, {"meaning": "绵延相及。", "cites": [{"t": "不称而祀谭,次祖。犯诅渝盟,伤言。", "b": "《管子》"}]}, {"meaning": "宏大,广大。", "cites": [{"t": "富恭有本能图,修业居久而谭。", "b": "《大戴礼记》。王聘珍解诂:“《广韵》:‘谭,大也。’业安于久而自大也。”"}]}, {"meaning": "同“谈”。言论。", "cites": [{"t": "此老生之常谭。", "b": "陈寿《三国志》"}]}, {"meaning": "古代国名 。在今山东省济南市东龙山镇附近。公元前684年为齐所灭。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3178wx','肇','1','zhào','聿','14','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从攴,肇(zhào)省声。从攴(pū),与打击有关。本义:击)。"}, {"meaning": "同本义。", "cites": [{"t": "肇,击也。", "b": "《说文》"}]}, {"meaning": "创建。", "cites": [{"t": "肇我邦予有夏。", "b": "《书·仲虺之诰》"}, {"t": "乃穆考文王,肇国在西地。", "b": "《书·酒诰》"}], "words": [{"w": "肇台", "t": "始建功业"}, {"w": "肇国", "t": "创建国家。"}]}, {"meaning": "矫正。", "cites": [{"t": "端木肇末。", "b": "《国语·齐语》"}]}, {"meaning": "引起;引发;招惹。", "cites": [{"t": "各界同乡会深恐人杂肇衅。", "b": "杨尘因《民潮七日记》"}], "words": [{"w": "肇衅", "t": "挑起事端"}, {"w": "肇乱", "t": "引起动乱。"}]}, {"meaning": "开始,最初。", "cites": [{"t": "肇建帝业,开国有晋。", "b": "张华《大会歌》"}, {"t": "顾自自国肇造,变乱纷乘。", "b": "孙文《黄花冈七十二烈士事略序》。"}], "words": [{"w": "肇判", "t": "开始分辨;始有区别"}, {"w": "肇造", "t": "初造,始建"}, {"w": "肇创", "t": "初创"}, {"w": "肇兴", "t": "始兴;初起"}, {"w": "肇称", "t": "始称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3179wx','褐','1','hè','衤','14','','[{"pinyin": "hè", "defs": [{"meaning": "(形声。从衣,曷声。本义:用粗麻织成的袜子)。"}, {"meaning": "同本义。", "cites": [{"t": "褐,编枲袜。", "b": "《说文》。段玉裁注:“取未绩之麻,编之为足衣,如今草鞵之类。”"}]}, {"meaning": "指粗布或粗布衣;最早用葛、兽毛,后通常指大麻、兽毛的粗加工品,古时贫贱人穿。", "cites": [{"t": "无衣无褐,何以卒岁。", "b": "《诗·豳风·七月》。郑玄笺:“褐,毛布也。”"}, {"t": "从者衣褐。", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "褐巾", "t": "用粗布缝成的头巾"}, {"w": "褐衣", "t": "粗布衣。借指平民"}, {"w": "褐衫", "t": "粗布衣"}, {"w": "褐夫", "t": "穿粗布衣服的人。指贫贱的人。"}]}, {"meaning": "卑贱的人。", "cites": [{"t": "旨酒一盛兮,余与褐之父睨之。", "b": "《左传·哀公十三年》。杜预注:“褐,寒贱之人。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3180wx','褪','1','tuì tùn','衤','14','','[{"pinyin": "tuì", "defs": [{"meaning": "脱落，脱去：梅子褪花时，直与黄梅接。褪装。兔子正褪毛。"}, {"meaning": "颜色消退或消失：褪色。颜色褪尽。"}]}, {"pinyin": "tùn", "defs": [{"meaning": "(形声。从衣,退声。这个后起字,解作卸衣、花谢、色减、退却。本义:卸衣)。"}, {"meaning": "同本义。", "cites": [{"t": "褪,卸衣也。", "b": "《韵会》"}, {"t": "那更梅花褪。", "b": "赵长卿《点绛唇》"}], "words": [{"w": "褪落", "t": "卸脱。"}]}, {"meaning": "消除。", "cites": [{"t": "春事阑珊,山村未褪寒。", "b": "陆游《蔬饭》"}]}, {"meaning": "凋萎。", "cites": [{"t": "梅子褪花时,直与黄梅接。", "b": "宋·辛弃疾《生查子》"}]}, {"meaning": "解除。", "cites": [{"t": "说着,就把弹弓褪下来,递将过去。", "b": "《儿女英雄传》"}]}, {"meaning": "宽缓。", "cites": [{"t": "消瘦休文,顿觉青衫褪。", "b": "宋·赵鼎《点绛唇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3181wx','谱','1','pǔ','讠','14','','[{"pinyin": "pǔ", "defs": [{"meaning": "(形声。从言,普声。本义:记载事物类别或系统的书)。"}, {"meaning": "同本义。", "cites": [{"t": "谱,牒也。", "b": "《广雅》"}, {"t": "谱,籍录也。", "b": "《说文新附》。朱骏声曰:“桓君山云,太史公三代世表,旁行斜上,普效周谱,是谱之名起于周代也。”"}, {"t": "十二曰谱系,以纪世施继序。", "b": "《旧唐书·经籍志上》"}], "words": [{"w": "食谱;歌谱;谱学", "t": "研究氏族或宗族世系的学科"}, {"w": "谱录", "t": "用谱表的方式记录世系"}, {"w": "家谱;棋谱", "t": ""}]}, {"meaning": "符号或文字列记乐歌的音节、声调,以便奏唱的籍录。", "cites": [{"t": "自历代至于本朝,雅乐皆先制乐章而后成谱,崇宁以后乃先制谱后命词。", "b": "《宋史·乐志》"}], "words": [{"w": "简谱;五线谱;工尺谱;乐谱", "t": ""}]}, {"meaning": "按照事物的类别或系统编排记录。", "cites": [{"t": "谱,布也。布列见其事也,亦曰绪也,主绪人世类相继如统绪也。", "b": "《释名》"}, {"t": "自殷以前诸侯不可得而谱。", "b": "《史记·三代世表》"}, {"t": "谱汝诸孙中。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "谱列", "t": "按照事物的系统和类别编排"}, {"w": "谱注", "t": "记叙记载"}, {"w": "谱状", "t": "记载家族及历史的书籍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3182wx','隧','1','suì','阝','14','','[{"pinyin": "suì", "defs": [{"meaning": "(形声。从阜(fù),遂声。阜指土山,从阜的字有的与建筑有关。本义:墓道,古墓中运送棺材到墓室的通道)。"}, {"meaning": "同本义。", "cites": [{"t": "以度为丘隧。", "b": "《周礼·冢人》"}, {"t": "上数幸嶷第,宋长宁陵隧道出第前路,上曰“我便是入他家墓内寻人。", "b": "《南史·豫章文献王嶷传》"}], "words": [{"w": "隧户", "t": "墓道的门"}, {"w": "隧口", "t": "墓道的入口处。"}]}, {"meaning": "地道。", "cites": [{"t": "君何患焉?若阙地及泉,隧而相见,其谁曰不然?", "b": "《左传·隐公元年》"}, {"t": "请隧弗许。", "b": "《左传·僖公二十五年》。注:“阙地通路曰隧。”"}], "words": [{"w": "隧洞", "t": "隧道"}, {"w": "隧埒", "t": "深沟与高墩"}, {"w": "隧炭", "t": "填在隧道中的炭。"}]}, {"meaning": "车辆或人畜通行的道路。", "cites": [{"t": "大风有隧。", "b": "《诗·大雅·桑柔》"}, {"t": "山无蹊隧。", "b": "《庄子·马蹄》"}, {"t": "连大车以塞隧。", "b": "《左传·襄公十八年》"}, {"t": "出入不当门隧。", "b": "《礼记·曲礼上》"}]}, {"meaning": "人体血气津液等运行分泌的通道。", "cites": [{"t": "五藏之道,皆出于经隧,以行血气。", "b": "《素问》"}]}, {"meaning": "钟上受敲击而洼下的地方。", "cites": [{"t": "凫氏为钟…于上之攠谓之隧。", "b": "《周礼》"}]}, {"meaning": "远郊之地。", "cites": [{"t": "鲁人三郊三隧。", "b": "《史记》"}]}, {"meaning": "周代郊外的一种行政区划。五县为隧。", "cites": [{"t": "令隧正纳郊保,奔火所。", "b": "《左传》"}], "words": [{"w": "隧正", "t": "一隧之长。"}]}, {"meaning": "烽火亭。", "cites": [{"t": "欲起亭隧。", "b": "《汉书·西域传下》"}, {"t": "登障隧而遥望兮,聊须臾以婆娑。", "b": "《文选·班彪·北征赋》"}, {"t": "修障隧备塞之具。", "b": "《汉书·匈奴传赞》"}]}, {"meaning": "旋转。", "cites": [{"t": "若磨石之隧。", "b": "《庄子》"}]}, {"meaning": "钻进地道,钻洞。", "cites": [{"t": "一狼洞其中,意将隧入以攻其后也。", "b": "《聊斋志异·狼三则》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3183wx','嫩','1','nèn','女','14','','[{"pinyin": "nèn", "defs": [{"meaning": "(形声。从女,敕声。本义:物初生时的柔弱娇嫩状)。"}, {"meaning": "同本义。", "cites": [{"t": "萝短未中揽,葛嫩不任牵。", "b": "萧衍《游钟山大爱敬寺》"}], "words": [{"w": "嫩萼;嫩蕊", "t": "含苞欲放的花"}, {"w": "嫩箭", "t": "兰花新抽的花茎"}, {"w": "嫩叶", "t": ""}]}, {"meaning": "指事物尚处在开始或轻微的状态。", "cites": [{"t": "桂花养魄嫩寒生。", "b": "柳贯《中秋待月不见》"}, {"t": "春禽处处讲新声,烟草欣欣贺嫩晴。", "b": "杨万里《春暖郡圃散策》"}], "words": [{"w": "嫩晴;嫩水", "t": "春水"}, {"w": "嫩凉", "t": "微凉;初凉"}, {"w": "嫩风", "t": "微风"}, {"w": "嫩约", "t": "不坚牢的信约"}, {"w": "嫩日", "t": "不强烈的阳光。"}]}, {"meaning": "不老练;缺乏实际经验。", "cites": [{"t": "[梁忠信]工画山水,体近高克明而笔墨差嫩。", "b": "郭若虚《图画见闻志》"}], "words": [{"w": "资格嫩;干这种事情他还是一个嫩手", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3184wx','翠','1','cuì','羽','14','','[{"pinyin": "cuì", "defs": [{"meaning": "(形声。从羽,卒声。本义:翠鸟)。"}, {"meaning": "鸟名,翠鸟。又专指雌性的翠鸟。", "words": [{"w": "翠以羽自残", "t": "翡翠鸟因羽色之美而被残杀。比喻人因有才而遭嫉害"}, {"w": "翠毛", "t": "翠鸟的羽毛"}, {"w": "翠羽", "t": "翠鸟的羽毛。古代多用作饰物"}, {"w": "翠禽", "t": "翠鸟。"}]}, {"meaning": "青、绿、碧之类的颜色。", "cites": [{"t": "两个黄鹂鸣翠柳,一行白鹭上青天。", "b": "杜甫《绝句(其三)》"}, {"t": "青树翠蔓。", "b": "柳宗元《至小丘西小石潭记》"}], "words": [{"w": "翠樾埭", "t": "绿荫覆盖的堤坝"}, {"w": "翠筠", "t": "绿竹"}, {"w": "翠微", "t": "青葱的山色"}, {"w": "翠屏", "t": "山名。亦指山色苍翠如屏"}, {"w": "翠羽", "t": "青绿色的鸟羽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3185wx','熊','1','xióng','灬','14','','[{"pinyin": "xióng", "defs": [{"meaning": "(形声。从能,炎省声。能,“熊”。本义:动物名)。"}, {"meaning": "属于食肉目熊科(Ursidae)的一种大型笨重的哺乳动物。", "cites": [{"t": "熊兽似豕,山居各蛰。", "b": "《说文》"}, {"t": "熊虎丑,其子狗。又罴如熊,黄白文。", "b": "《尔雅》"}, {"t": "黄能入于寝门。", "b": "《国语·晋语》。字误能,按,罴即熊类之大而猛者,能拔树木,今俗谓之人熊。"}]}, {"meaning": "古代以熊皮为饰的箭靶。", "cites": [{"t": "有熊侯。", "b": "《仪礼·乡射礼》"}], "words": [{"w": "熊侯", "t": "饰以熊皮的箭靶。"}]}, {"meaning": "古州名。", "cites": [{"t": "熊、谷二州在度内,不取,敦邻好也。", "b": "《新唐书》"}]}, {"meaning": "雄性。", "cites": [{"t": "及赞戎律,熊武斯裁。", "b": "《北史·羊祉传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3186wx','凳','1','dèng','几','14','','[{"pinyin": "dèng", "defs": [{"meaning": "凳子。"}, {"meaning": "床前踏具。", "cites": [{"t": "床凳之凳,晋已有此器。", "b": "宋·吴曾《能改斋漫录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3187wx','骡','1','luó','马','14','','[{"pinyin": "luó", "defs": [{"meaning": "动物名。骡子 。哺乳纲,奇蹄目,马科。", "cites": [{"t": "驘,驴父马母。", "b": "《说文》"}, {"t": "同驽驘与乘驵兮。", "b": "《楚辞·九叹·忧苦》。注:“马母騼父生子曰驘。”"}], "words": [{"w": "骡纲", "t": "驮载商旅货物结队而行的骡群"}, {"w": "骡驴", "t": "骡和驴,比喻平庸的人;兽名,俗称“四不像”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3188wx','缩','1','suō','纟','14','','[{"pinyin": "suō", "defs": [{"meaning": "(形声。从糸(mì),宿声。糸,细丝,与绳索有关。本义:捆束)。"}, {"meaning": "同本义。", "cites": [{"t": "其绳则直,缩版以载。", "b": "《诗·大雅·緜》"}, {"t": "缩,乱也。", "b": "《说文》。朱曰:“许书之乱字皆治也,理也。此说解及尔雅之乱,正谓治理。”"}, {"t": "磬阶闲缩霤。", "b": "《仪礼·乡饮酒礼》"}, {"t": "十纯则缩而委之。", "b": "《仪礼·乡射礼·大射仪》"}, {"t": "绞横三缩一。", "b": "《仪礼·士丧礼》"}, {"t": "冠缩缝。", "b": "《礼记·檀弓》"}, {"t": "布绞缩者一。", "b": "《礼记·丧大纪》"}]}, {"meaning": "收缩。", "cites": [{"t": "论战斗之事,则缩颈而股慄。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "缩栗", "t": "冷缩颤栗"}, {"w": "缩气", "t": "收敛气焰"}, {"w": "缩瑟", "t": "瑟缩。畏缩貌"}, {"w": "缩首", "t": "点头。"}]}, {"meaning": "退缩;退,减。", "cites": [{"t": "是日风静,舟行颇迟,又秋深潦缩,故得尽见杜老所谓“幸有舟楫迟,得尽所历妙”也。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "缩恧", "t": "因羞惭而畏惧瑟缩。恧,惭"}, {"w": "缩伏", "t": "畏惧屈服"}, {"w": "缩退", "t": "畏缩退却"}, {"w": "缩栗", "t": "形容畏惧颤朒;枝叶枯萎。"}]}, {"meaning": "亏欠,不足。", "cites": [{"t": "由是以天下公赋为人君私藏,有司不复得窥其多少,校其赢缩。", "b": "《资治通鉴·唐·大历十四年》"}], "words": [{"w": "缩囊", "t": "日渐贫困"}, {"w": "缩腹", "t": "忍受饥饿。"}]}, {"meaning": "滤酒去渣。", "cites": [{"t": "缩酌用茅,明酌也。", "b": "《礼记·郊特牲》"}], "words": [{"w": "缩酒", "t": "古代祭祀时,捆束包茅立于前,灌酒于茅束,酒渗而下,视为神饮,名为缩酒,一说为滤酒去掉渣滓。"}]}, {"meaning": "取,采取。", "cites": [{"t": "若于目观则美,缩于财用则匮,是聚民利以自封而瘠民出,胡美之焉。", "b": "《国语·楚语》"}], "words": [{"w": "缩弗转", "t": "方言。收不回"}, {"w": "缩屋称贞", "t": "称颂人在妇女有危难时,能守礼而不加侵犯凌辱之词。按:缩屋而继之,指薪尽,又拆取屋木以继。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3189wx','慧','1','huì','心','15','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从心,彗声。本义:聪明,有才智)。"}, {"meaning": "同本义。", "cites": [{"t": "慧,儇也。", "b": "《说文》"}, {"t": "知或谓之慧。", "b": "《方言》三"}]}, {"meaning": "注:“慧,儇,皆意精明。”。", "cites": [{"t": "亟见窕察谓之慧。", "b": "《贾子道术》"}, {"t": "柔质受谏曰慧。", "b": "《周书·谥法》"}, {"t": "周子有兄而无慧。", "b": "《左传·成公十八年》"}, {"t": "而慧者不以藏书箧。", "b": "《韩非子·喻老》"}], "words": [{"w": "慧侠", "t": "有才华,有胆略"}, {"w": "慧给", "t": "聪敏而有口才"}, {"w": "慧种", "t": "优良的天赋秉性"}, {"w": "慧黠", "t": "聪敏机智"}, {"w": "慧美", "t": "聪明美丽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3190wx','撵','1','niǎn','扌','15','','[{"pinyin": "niǎn", "defs": [{"meaning": "(形声。从手,辇声。本义:驱逐)。"}, {"meaning": "同本义。", "cites": [{"t": "你趁早与我出去,我不着丫头撵你。", "b": "《金瓶梅》"}], "words": [{"w": "撵山", "t": "闯山,在山上转"}, {"w": "撵逐", "t": "驱逐"}, {"w": "撵他下台;撵蹿", "t": "赶走"}, {"w": "把孩子撵回屋;把猪撵进圈;你不好好干活,老板会撵你;把人撵走", "t": ""}]}, {"meaning": "催。", "cites": [{"t": "贾母亦知因贾政一人在所致,酒过三巡,便撵贾政去歇息。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3191wx','撕','1','sī','扌','15','','[{"pinyin": "sī", "defs": [{"meaning": "(形声。从手,斯声。“斯”也有表意作用,“劈开”。本义:扯裂)。"}, {"meaning": "同本义。", "cites": [{"t": "晴雯果然接过来,“嗤”的一声,撕了两半。", "b": "《红楼梦》"}], "words": [{"w": "把纸撕成条儿;把墙上的标语撕下来;把一张报纸撕成两半;上衣在钉子上撕了一个口子;撕打", "t": "撕搏。扭扯殴打"}, {"w": "撕罗", "t": "亦作:“撕逻”。排解"}, {"w": "撕捋", "t": "分解,排解"}, {"w": "撕剥", "t": "撕烂,扯碎。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3192wx','撒','1','sā sǎ','扌','15','','[{"pinyin": "sā", "defs": [{"meaning": "抛开;放开。", "cites": [{"t": "说着先就撒马前去。", "b": "《红楼梦》"}], "words": [{"w": "撒开", "t": "张开,放开;撇开,散开"}, {"w": "撒口", "t": "放松口气"}, {"w": "撒开鸭子", "t": "放开腿脚"}, {"w": "撒步", "t": "放开脚步"}, {"w": "撒鸭子", "t": "放开脚步快走"}, {"w": "撒花开顶", "t": "头破血流"}, {"w": "撒嘴", "t": "松开口"}, {"w": "撒脱", "t": "洒脱"}, {"w": "撒撇", "t": "撒开;回避。"}]}, {"meaning": "放;排泄。", "cites": [{"t": "只在佛殿后撒尿撒屎。", "b": "《水浒全传》"}], "words": [{"w": "撒溲", "t": "小便"}, {"w": "小孩把尿撒得到处都是", "t": ""}]}, {"meaning": "塞;系。", "cites": [{"t": "那孙大圣早已知二魔化在葫芦里面,却将他紧紧拴扣停当,撒在腰间。", "b": "《西游记》"}]}, {"meaning": "弯着。", "cites": [{"t": "和尚见他的兵器被人吃住了,咬住牙,撒着腰,往后一拽。", "b": "《儿女英雄传》"}]}, {"meaning": "结成。", "cites": [{"t": "你也见过一个千金小姐和强盗撒对儿的么?", "b": "《儿女英雄传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "sǎ", "defs": [{"meaning": "(形声。从手,散声。字本从米,殺声。本义:散布)。"}, {"meaning": "同本义。", "cites": [{"t": "撒,散之也。", "b": "《集韵》"}, {"t": "星如撒沙出。", "b": "韩愈《月蚀诗效玉川子作》"}], "words": [{"w": "撒帐", "t": "旧婚俗。夫妻对拜后即坐于床上,由专人撒金钱、瓜子和红枣,表示多子多孙"}, {"w": "撒漫", "t": "大手大脚,大方"}, {"w": "撒泼", "t": "抛撒;撒落"}, {"w": "撒枯", "t": "散布干肥"}, {"w": "撒星", "t": "散布的火星。"}]}, {"meaning": "插;塞进。", "cites": [{"t": "那呆子把钉钯撒在腰里。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3193wx','撩','1','liáo liǎo liào liāo','扌','15','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从手,尞(liáo)声。本义:整理)。"}, {"meaning": "同本义。", "cites": [{"t": "撩,理也。", "b": "《说文》"}, {"t": "理乱谓之撩。", "b": "《通俗文》"}], "words": [{"w": "撩治", "t": "处理,料理"}, {"w": "撩理", "t": "整理;照料;逗引"}, {"w": "撩虎须", "t": "捋虎须。指冒犯虎威,担受风险。"}]}, {"meaning": "挑,拨。", "cites": [{"t": "凡人取果,宜待熟时,不撩自落。", "b": "《北齐书·陆法和传》"}], "words": [{"w": "撩斗", "t": "挑弄招惹"}, {"w": "撩虎须", "t": "撩拨虎须。比喻冒险"}, {"w": "撩蜂吃螫", "t": "撩蜂剔蝎。比喻挑逗恶人,自招祸害"}, {"w": "撩火加油", "t": "火上加油"}, {"w": "撩云拨雨", "t": "调弄风情。"}]}, {"meaning": "引申为挑逗,招引,逗引。", "cites": [{"t": "屡撩之。", "b": "《聊斋志异·促织》"}]}, {"meaning": "又。", "cites": [{"t": "试以猪鬣撩虫须。", "b": ""}], "words": [{"w": "撩理", "t": "逗引"}, {"w": "撩惹", "t": "挑引"}, {"w": "撩斗", "t": "撩逗。撩拨;挑逗。"}]}]}, {"pinyin": "liǎo", "defs": [{"meaning": "", "words": [{"w": "撩浅", "t": "谓挖去淤积的泥沙"}, {"w": "撩湖", "t": "谓挖去湖中的淤泥。"}]}]}, {"pinyin": "liào", "defs": [{"meaning": "放,丢。", "cites": [{"t": "她这样想着,忍不住叹一口气,随手拎起这件衣服往地上的箱子里一撩。", "b": "茅盾《委曲》"}], "words": [{"w": "撩开", "t": "甩掉"}, {"w": "撩开手", "t": "撒手。喻断绝关系"}, {"w": "撩荒", "t": "抛荒。"}]}]}, {"pinyin": "liāo", "defs": [{"meaning": "揭起,向上掀起", "words": [{"w": "撩窗帘", "t": ""}, {"w": "撩衣", "t": "掀起衣襟"}, {"w": "撩牙", "t": "启齿"}, {"w": "开口)", "t": ""}, {"w": "撩天", "t": "朝天"}]}, {"meaning": "用手舀水浇洒", "words": [{"w": "在沟里撩水洗手", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3194wx','趣','1','cù qù','走','15','','[{"pinyin": "cù", "defs": [{"meaning": "(古通“促”)。"}, {"meaning": "督促;催促。", "cites": [{"t": "趣,疾也。从走,取声。", "b": "《说文》"}, {"t": "趣其稼事。", "b": "《周礼·县止》"}, {"t": "趣民收敛。", "b": "《礼记·月令》"}, {"t": "趣为我语。", "b": "《汉书·周勃传》"}, {"t": "趣赵兵亟入关。", "b": "《史记·陈涉世家》"}, {"t": "王夫人又趣使大臣立栗姬为皇后。", "b": "《汉书·外戚传上》"}], "words": [{"w": "趣使", "t": "督促"}, {"w": "趣董", "t": "催促"}, {"w": "趣督", "t": "督促。"}]}, {"meaning": "赶快;从速。", "cites": [{"t": "趣执之,无使得遁。", "b": "《明史·海瑞传》"}], "words": [{"w": "趣装", "t": "速整行装"}, {"w": "趣袭", "t": "急袭,快速攻击。"}]}]}, {"pinyin": "qù", "defs": [{"meaning": "(形声。从走,取声。本义:急,赶快) 同本义。", "cites": [{"t": "趣,疾也。", "b": "《说文》"}, {"t": "若不趣降汉,汉今虏若,若非汉敌也。", "b": "《史记》"}]}, {"meaning": "催促;督促。", "cites": [{"t": "趣其稼事。", "b": "《周礼·县正》"}, {"t": "趣民收敛。", "b": "《礼记·月令》"}, {"t": "趣为我语。", "b": "《汉书·周勃传》"}, {"t": "督趣司隶。", "b": "《汉书·翟方进传》"}, {"t": "巫妪何久也?弟子趣之。", "b": "褚少孙《西门豹治邺》"}]}, {"meaning": "趋向;奔向。", "cites": [{"t": "左右趣之。", "b": "《诗·大雅·棫朴》"}, {"t": "来朝趣马。", "b": "《诗·大雅·棫》"}, {"t": "汝先观吾趣。", "b": "《列子·汤问》"}], "words": [{"w": "趋时", "t": "努力与当时的形势、环境及条件相适应"}, {"w": "趣向", "t": "向往;趋附。"}]}, {"meaning": "赶上。", "cites": [{"t": "富在俭力趣时,不在岁司羽鸠也。", "b": "《盐铁论》"}], "words": [{"w": "趣走", "t": "奔走;行走"}, {"w": "趣役", "t": "奔走服侍。"}]}, {"meaning": "取笑;打趣。", "cites": [{"t": "众人便知他趣白日间湘云醉卧的事。", "b": "《红楼梦》"}]}, {"meaning": "旨趣;意思。", "cites": [{"t": "趣舍不同。", "b": "《庄子·齐物论》"}, {"t": "以博其趣。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "趣寄", "t": "趣向,志向"}, {"w": "趣识", "t": "旨趣见识。"}]}, {"meaning": "乐趣;兴趣。", "cites": [{"t": "园日涉以成趣。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "趣势", "t": "趣味"}, {"w": "欢乐之趣;异趣;养趣;趣向", "t": "兴味"}, {"w": "趣兴", "t": "乐趣;兴致。"}]}, {"meaning": "作为。", "cites": [{"t": "见其趣如是,作《憎王孙》云。", "b": "柳宗元《憎王孙文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3195wx','趟','1','tāng tàng','走','15','','[{"pinyin": "tāng", "defs": [{"meaning": "踩,踏。", "cites": [{"t": "大洋马一纵一纵的趟起漫天尘土。", "b": "徐光耀《平原烈火》"}]}]}, {"pinyin": "tàng", "defs": [{"meaning": "(形声。从走,尚声。本义:次,回)。"}, {"meaning": "遍,次。专指走动的次数。", "cites": [{"t": "我看你白跑这一趟。", "b": "《白雪遗音》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3196wx','撑','1','chēng','扌','15','','[{"pinyin": "chēng", "defs": [{"meaning": "(形声。从手,掌声。本义:支撑,支持)。"}, {"meaning": "同本义。", "cites": [{"t": "天津流水波赤血,白骨相撑如乱麻。", "b": "李白《扶风豪士歌》"}], "words": [{"w": "用两手撑着下巴;撑扶", "t": "支撑扶持"}, {"w": "撑天拄地", "t": "喻顶天立地。"}]}, {"meaning": "维持,保持。", "cites": [{"t": "他死活也得把这个门面撑着", "b": ""}, {"t": "两场球下来,他恐怕撑不住了", "b": ""}], "words": [{"w": "撑场面;撑持", "t": ""}]}, {"meaning": "积攒;购买。", "cites": [{"t": "我儿花衣裳、头面,多末勿算多,撑得来也勿容易。", "b": "《海上孽梅花》"}]}, {"meaning": "撑臂。如:角撑。也指支拄物。如:给草堆打个撑。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3197wx','撮','1','cuō zuǒ','扌','15','','[{"pinyin": "cuō", "defs": [{"meaning": "(形声。从手,最声。本义:用手指抓取粒状物)。"}, {"meaning": "用三指取物;抓取。", "cites": [{"t": "撮,四圭也,一曰两指撮也。", "b": "《说文》"}, {"t": "量多少者不失圭撮。", "b": "《汉书·律历志上》"}, {"t": "鸱鸺夜撮蚤。", "b": "《庄子·秋水》"}], "words": [{"w": "撮一点儿盐;撮药", "t": "抓药"}, {"w": "撮土", "t": "抓一把土"}, {"w": "撮拾", "t": "撮取"}, {"w": "撮台子", "t": "拾掇桌子。"}]}, {"meaning": "聚合;聚拢。", "cites": [{"t": "撮冀州之众。", "b": "《后汉书·袁绍传》"}, {"t": "我这里正项钱粮,兀自起解不足,东那西撮。", "b": "《水浒传》"}]}, {"meaning": "提,拎。"}, {"meaning": "容量单位,等于一升的千分之一——用于可用手或工具撮取的粉粒状物。", "cites": [{"t": "量之所起起于粟。六粟为一圭,十圭为一撮,十撮为一抄,十抄为一勺,十勺为一合,十合为一升,十升为一斗,十斗为一斛。", "b": "《孙子算经·上》"}]}]}, {"pinyin": "zuǒ", "defs": [{"meaning": "", "words": [{"w": "一撮儿毛;剃去一卷,留下一撮", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3198wx','撬','1','qiào','扌','15','','[{"pinyin": "qiào", "defs": [{"meaning": "(形声。从手,毳(cuì)声。本义:翘起。举起)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3199wx','播','1','bō','扌','15','','[{"pinyin": "bō", "defs": [{"meaning": "(形声。从手,番声。本义:撒种)。"}, {"meaning": "同本义。", "cites": [{"t": "播,种也。", "b": "《说文》"}, {"t": "其始播百谷。", "b": "《诗·豳风 ·七月》"}, {"t": "播时百谷,", "b": "《书·舜典》"}, {"t": "周弃能播殖百谷蔬。", "b": "《国语·郑语》"}], "words": [{"w": "条播;夏播;播田", "t": "种田;种植"}, {"w": "播植", "t": "播种;种植"}, {"w": "播谷", "t": "播种谷物。"}]}, {"meaning": "散布开去,散布得开而远;传布。", "cites": [{"t": "播于诸侯。", "b": "《左传·昭公四年》"}, {"t": "道大名播。", "b": "柳宗元《三戒》"}], "words": [{"w": "广播;播音;播名", "t": "传扬名声。"}]}, {"meaning": "分佈;散布。", "cites": [{"t": "又北播为九河。", "b": "《书·禹贡》"}, {"t": "播余香而莫闻。", "b": "张衡《思玄赋》"}, {"t": "蒸灵液以播云。", "b": "《文选·嵇康·琴赋》"}], "words": [{"w": "播糠眯目", "t": "撒布糠屑,以迷人目。比喻外物虽小,加在自己身上,会伤害本性"}, {"w": "播洒", "t": "洒水喷地"}, {"w": "播馨", "t": "散布芳香。"}]}, {"meaning": "逃亡。", "cites": [{"t": "身播国屯。", "b": "《后汉书·献帝纪》"}, {"t": "成公播荡。", "b": "《左传·襄公二十五年》。注:“流移失所。”"}], "words": [{"w": "播越", "t": "到处流亡"}, {"w": "播奔", "t": "奔逃。"}]}, {"meaning": "迁徙。", "cites": [{"t": "彼凌江而建国,始播迁于吾祖。", "b": "庾信《哀江南赋》"}], "words": [{"w": "播迁", "t": "迁徙,迁移"}, {"w": "播徙", "t": "流亡迁移。"}]}, {"meaning": "背弃,舍弃。", "cites": [{"t": "播规矩以背度兮,错权衡而任意。", "b": "刘向《思古》"}], "words": [{"w": "播弃", "t": "抛弃,背弃。"}]}, {"meaning": "摇动;簸扬。", "cites": [{"t": "播鼗武入于汉。", "b": "《论语·微子》"}, {"t": "鼓筴播精。", "b": "《庄子·人间世》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3200wx','擒','1','qín','扌','15','','[{"pinyin": "qín", "defs": [{"meaning": "(形声。从手,禽声。本义:捕捉。古籍本作“禽”)。"}, {"meaning": "同本义。", "cites": [{"t": "射人先射马,擒贼先擒王。", "b": "杜甫《前出塞》诗之六"}], "words": [{"w": "擒捕", "t": "捕捉"}, {"w": "擒捉", "t": "捕捉"}, {"w": "擒讨", "t": "擒获处治。"}]}, {"meaning": "捉拿。", "cites": [{"t": "大敌之擒也。", "b": "《墨子·公输》"}, {"t": "被擒不速死。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "擒捉", "t": "捉拿"}, {"w": "擒生", "t": "活捉敌人"}, {"w": "擒捽", "t": "捉拿,逮捕。"}]}, {"meaning": "拿。", "cites": [{"t": "肩上虽挑却柴担,手里兀自擒着书本。", "b": "《喻世明言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3201wx','墩','1','dūn','土','15','','[{"pinyin": "dūn", "defs": [{"meaning": "(形声。从土,敦声。本义:土堆)。"}, {"meaning": "同本义。", "cites": [{"t": "墩,平地有堆。", "b": "《说文》"}, {"t": "冶城访古迹,犹有谢安墩。", "b": "李白《登金陵冶城西北谢安墩诗》"}], "words": [{"w": "挖塘取土,垒土为墩;土墩;墩台", "t": "高一些的土堆台;报警台。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3202wx','撞','1','zhuàng','扌','15','','[{"pinyin": "zhuàng", "defs": [{"meaning": "(形声。从手,童声。本义:撞击)。"}, {"meaning": "同本义。", "cites": [{"t": "撞,丮捣也。", "b": "《说文》。字亦作揰,作摐。"}, {"t": "善待问者如撞钟。", "b": "《礼记·学记》。犹击也。"}, {"t": "摐金鼓。", "b": "司马相如《子虚赋》"}, {"t": "撞洪钟。", "b": "张衡《东京赋》"}, {"t": "亚父受玉斗,置之地,拔剑撞而破之。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "樊哙侧其盾以撞。", "b": ""}, {"t": "东野不回头,有如寸莛撞巨钟。", "b": "韩愈《醉留东野》"}, {"t": "便将头往隔断板上乱撞,撞的披头散发。", "b": "《红楼梦》"}], "words": [{"w": "撞跌", "t": "撞头跺脚"}, {"w": "撞木", "t": "敲击钟磬之木"}, {"w": "撞舂", "t": "撞击;冲击"}, {"w": "撞筵", "t": "撞钟的木枝。"}]}, {"meaning": "遇上,碰到。", "cites": [{"t": "我待要赶时,不想撞着哥哥贺知章。", "b": "乔吉《金钱记》"}, {"t": "今日清明佳节,出门闪步一回,却好撞着风雨。", "b": "《长生殿》"}, {"t": "麴义引军直冲到后军,正撞着赵云。", "b": "《全图绣像三国演义》"}], "words": [{"w": "撞见;撞客;撞遇", "t": "碰见"}, {"w": "撞破", "t": "撞见败露。"}]}, {"meaning": "栽,跌。", "cites": [{"t": "扑通的撞下马来。", "b": "《水浒全传》"}]}, {"meaning": "闯,猛冲或突然直下。", "cites": [{"t": "山背后撞出一彪人马。", "b": "《水浒全传》"}], "words": [{"w": "撞尸", "t": "骂人话。指东跑西荡"}, {"w": "撞祸", "t": "闯祸;惹祸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3203wx','撤','1','chè','扌','15','','[{"pinyin": "chè", "defs": [{"meaning": "(形声。从手,(chè)声。本义:撤去)。"}, {"meaning": "同本义。", "cites": [{"t": "撤屏视之,一人、一桌、一椅、一扇、一抚尺而已。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "撤酒席;撤火", "t": "撤去炉火"}, {"w": "撤帘", "t": "帝制时代,由太后代天子执政,叫垂帘。还政天子,称撤帘"}, {"w": "撤案", "t": "撤去餐具。"}]}, {"meaning": "撤回,使退出。", "cites": [{"t": "斩四门首事各一人,即撤围。", "b": "清·邵长蘅《青门剩稿·阎典史传》"}], "words": [{"w": "撤备", "t": "撤去守备的军队"}, {"w": "撤警", "t": "撤去警备的军队。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3204wx','增','1','zēng','土','15','','[{"pinyin": "zēng", "defs": [{"meaning": "(形声。从土,曾声。字本作“曾”。本义:增多)。"}, {"meaning": "同本义。", "cites": [{"t": "增,益也。", "b": "《说文》"}, {"t": "增,加也。", "b": "《广雅·释诂一》"}, {"t": "鹰鸢犹以山为卑而增巢其上。", "b": "《荀子·法行》"}, {"t": "残高增下。", "b": "《淮南子·本经》"}, {"t": "山不加增。", "b": "《列子·汤问》"}, {"t": "增脚气病。", "b": "唐·柳宗元《柳河东集》"}, {"t": "止增笑耳。", "b": "《聊斋志异·狼三则》"}, {"t": "乃增损。", "b": "蔡元培《图画》"}, {"t": "旧时栏楯,亦遂增胜。", "b": "明·归有光《项脊轩志》"}, {"t": "言其户口,则视三十年以前增五倍焉。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "增年", "t": "加寿;年龄增加"}, {"w": "增增", "t": "众多的样子"}, {"w": "增奉", "t": "增加俸禄"}, {"w": "增拓", "t": "增加,扩充"}, {"w": "增息", "t": "谓增多人丁"}, {"w": "增累", "t": "增加,累积"}, {"w": "增损", "t": "增加或减少"}, {"w": "增广", "t": "增加,扩大"}, {"w": "增置", "t": "增添,添设"}, {"w": "增防", "t": "增强防守。"}]}, {"meaning": "厌恶。", "cites": [{"t": "帝式是增。", "b": "《墨子·非命下》。毕沅云:“增、憎字通。”"}, {"t": "不惧季氏增邑不隐讳之害,独畏答懿子极言之罪,何哉?", "b": "《论衡》"}]}, {"meaning": "扩大。", "cites": [{"t": "增其旧制。", "b": "宋·范仲淹《岳阳楼记》"}]}, {"meaning": "夸大,夸张。", "cites": [{"t": "患言事增其实。", "b": "王充《论衡》"}]}, {"meaning": "山名 。在今内蒙古自治区与陕西省交界处。", "cites": [{"t": "司马彪曰:增山者,上郡之别名也。", "b": "《水经注·河水三》"}]}, {"meaning": "高。", "cites": [{"t": "夫鸢鹊遭害,则仁鸟增逝", "b": "班固《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3205wx','撰','1','zhuàn','扌','15','','[{"pinyin": "zhuàn", "defs": [{"meaning": "(形声。从手,巽(xùn)声。本义:写作,纂集成整体)。"}, {"meaning": "同本义。", "cites": [{"t": "隐士休歌紫芝曲,词人解撰河清颂。", "b": "杜甫《洗兵马》"}, {"t": "撰长书以为贽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "撰文", "t": "写文章"}, {"w": "撰次", "t": "写作;记述"}, {"w": "撰刻", "t": "撰写而勒刻"}, {"w": "撰修", "t": "书写。编撰"}, {"w": "撰碑", "t": "撰写碑文。"}]}, {"meaning": "纂集。", "cites": [{"t": "顷撰其遗文,都为一集。", "b": "曹丕《与吴质书》"}], "words": [{"w": "撰具", "t": "编成"}, {"w": "撰定", "t": "编定;写定"}, {"w": "撰造", "t": "创作;编制。"}]}, {"meaning": "制造。", "cites": [{"t": "乃采凫氏,撰鸣钟,火天地之炉,扇阴阳之炭。", "b": "李白《化城寺大钟铭》"}]}, {"meaning": "建造。", "cites": [{"t": "撰得绝似,但欠鸡鸣犬吠耳。", "b": "罗大经《鹤林玉露》"}]}, {"meaning": "拿住,持。", "cites": [{"t": "撰杖屦。", "b": "《礼记·曲礼》。注:“犹持也。”"}, {"t": "撰余辔兮高驼翔。", "b": "屈原《九歌》"}]}, {"meaning": "数  指天地阴阳等自然现象的变化规律。", "cites": [{"t": "阴阳合德,而刚柔有体,以体天地之撰。", "b": "《易·系辞下》"}]}, {"meaning": "才具,才干。", "cites": [{"t": "三子者之撰。", "b": "《论语·先进》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3206wx','聪','1','cōng','耳','15','','[{"pinyin": "cōng", "defs": [{"meaning": "(形声。从耳,总声。本义:听力好)。"}, {"meaning": "同本义。", "cites": [{"t": "聪,察也。", "b": "《说文》"}, {"t": "听曰聪。", "b": "《书·洪范》"}, {"t": "闻审谓之聪。", "b": "《管子·宙合》"}, {"t": "耳彻为聪。", "b": "《庄子·外物》"}, {"t": "尚寐无聪。", "b": "《诗·王风·兔爰》"}], "words": [{"w": "聪耳", "t": "听觉灵敏的耳朵。"}]}, {"meaning": "明察。指耳闻声音而心能辨别其是真假。", "cites": [{"t": "耳不能两听而聪。", "b": "《荀子·劝学》"}, {"t": "屈平疾王听之不聪也。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "聪察", "t": "擅长审辨"}, {"w": "聪察轩昂", "t": "明察真伪,仪态不凡"}, {"w": "聪听", "t": "明于听取;明于辨察。"}]}, {"meaning": "聪明,有才智。", "cites": [{"t": "听曰聪,聪者,能闻事而审其意也。", "b": "《春秋繁露·五行五事》"}, {"t": "瞻今已八岁,聪慧可爱。", "b": "《三国志·诸葛亮传》"}, {"t": "聪者不得用其诈。", "b": "《韩非子·有度》"}, {"t": "不聪敬止。", "b": "《诗·周颂·敬之》"}], "words": [{"w": "聪哲", "t": "聪明多智"}, {"w": "聪明自误", "t": "天资聪明的人,反被聪明所误"}, {"w": "聪智", "t": "指聪明而有才智。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3207wx','鞋','1','xié','革','15','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从革,圭声。皮革鞋的材料。“圭、鞋”古音相近。本义:鞋子) 同本义。", "cites": [{"t": "鞵,生革醍也。", "b": "《说文》。字亦作鞋"}, {"t": "古人以草为屦,皮为履,后唐马周始以麻为之,即鞋也。", "b": "《说郛》引唐·留存《事始·鞋》"}], "words": [{"w": "鞋扇", "t": "鞋面"}, {"w": "鞋脚", "t": "小妾第一次拜见长妻时所敬赠的见面礼:亲手做的针线活;也指鞋袜"}, {"w": "鞋脚钱", "t": "跑腿钱"}, {"w": "雨鞋;皮鞋;布鞋;鞋鞢", "t": "造鞋时所用的木制鞋型。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3208wx','鞍','1','ān','革','15','','[{"pinyin": "ān", "defs": [{"meaning": "(形声。从革,安声。本义:马鞍) 同本义。", "cites": [{"t": "鞌,鞁具也。", "b": "《说文》"}, {"t": "令皆下马解鞍。", "b": "《汉书·李广传》"}, {"t": "投鞌高如城者数所。", "b": "《汉书·韩安国传》"}, {"t": "汉王下马踞鞍而问。", "b": "《史记·留侯世家》。"}], "words": [{"w": "鞍桥", "t": "指马鞍。因马鞍的形状像桥而得名"}, {"w": "鞍辔", "t": "骑马的用具。鞍为坐具,辔为控马的缰束。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3209wx','蕉','1','jiāo qiáo','艹','15','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从艸,焦声。本义:生麻。麻未沤称蕉)。"}, {"meaning": "同本义。", "cites": [{"t": "覆之以蕉。", "b": "《列子·周穆王》"}], "words": [{"w": "蕉布", "t": "蕉麻纤维织成的布"}, {"w": "蕉衣", "t": "麻布制的衣服"}, {"w": "蕉衫", "t": "用麻布缝制的衣衫。"}]}]}, {"pinyin": "qiáo", "defs": [{"meaning": "柴。", "cites": [{"t": "覆之以蕉。", "b": "《列子》。殷敬顺释文:“蕉,与樵同。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3210wx','蕊','1','ruǐ','艹','15','','[{"pinyin": "ruǐ", "defs": [{"meaning": "(形声。从艸,惢(suǒ,suī)声。本义:花蕊,植物的生殖器官)。"}, {"meaning": "同本义。", "cites": [{"t": "蕊,聚也。", "b": "《苍颉篇》"}, {"t": "蕊,华也。", "b": "《广雅》"}, {"t": "贯薜荔之落蕋。", "b": "《楚辞·离骚》"}], "words": [{"w": "蕊香", "t": "花蕊的芬芳"}, {"w": "蕊黄", "t": "古代妇女装饰面容时,以黄点额,其形似花蕊,故名蕊黄。"}]}, {"meaning": "花苞。", "cites": [{"t": "嫩蕊商量细细开。", "b": "杜甫《江畔独步寻花七绝句》"}]}, {"meaning": "草木丛生貌。", "cites": [{"t": "蕊,草木丛生貌。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3211wx','蔬','1','shū','艹','15','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从艸,疏声。本义:蔬菜) 同本义。", "cites": [{"t": "蔬,菜也。", "b": "《说文新附》。先秦无“蔬”字,用“疏”表示。“蔬”是汉魏间字。"}, {"t": "令发五苑之蓏、蔬、枣、栗,足以活民。", "b": "《韩非子·外储说右下》"}, {"t": "八曰臣妾,聚敛疏材。", "b": "《周礼·太宰》。注:“疏材,百草根实可食者。”"}, {"t": "饭疏食。", "b": "《论语》。孔注:“菜食也。”"}, {"t": "能植百谷百蔬。", "b": "《国语·鲁语》"}, {"t": "菜谓之蔬。", "b": "《小尔雅》"}, {"t": "迁淳安知县。布袍脱粟,令老仆艺蔬自给。", "b": "《明史·海瑞传》"}], "words": [{"w": "蔬菲", "t": "指果菜类粗食"}, {"w": "蔬笋", "t": "蔬菜和笋"}, {"w": "蔬饭", "t": "蔬菜饭食。指粗食"}, {"w": "蔬蓏", "t": "蔬菜瓜果"}, {"w": "蔬蔌", "t": "蔬菜之统称"}, {"w": "蔬圃", "t": "菜园"}, {"w": "蔬茹", "t": "蔬菜。"}]}, {"meaning": "种菜。", "cites": [{"t": "有松可荫,有地可蔬。", "b": "清·顾炎武《复庵记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3212wx','蕴','1','yùn','艹','15','','[{"pinyin": "yùn", "defs": [{"meaning": "(形声。从艸,蕴(yùn) 声。本义:积聚,蓄藏)。"}, {"meaning": "同本义。", "cites": [{"t": "蘊,积也。", "b": "《说文》"}]}, {"meaning": "字亦作“蕴”。", "cites": [{"t": "蘊,聚也。", "b": "《广雅》"}, {"t": "芟夷蘊崇之。", "b": "《左传·隐公六年》"}, {"t": "蓄而弗治将蘊。", "b": "《左传·昭公二十五年》"}, {"t": "而以是相蕴。", "b": "《庄子·齐物论》"}, {"t": "我心蕴结兮。", "b": "《诗·桧风·素冠》"}, {"t": "蕴利生孽,姑使无蕴乎。", "b": "《左传·昭公十年》"}], "words": [{"w": "蕴积", "t": "蕴藏;积聚"}, {"w": "蕴哲", "t": "蓄藏智慧"}, {"w": "蕴艺", "t": "藏蓄的才华。"}]}, {"meaning": "包藏;包含。", "cites": [{"t": "万物尽然,而以是相蕴。", "b": "《庄子》"}]}, {"meaning": "乱麻。", "cites": [{"t": "[里媪] 即束蕴请火去妇之家,曰:“吾犬争肉相杀,请火治之。”", "b": "《韩诗外传》"}]}, {"meaning": "佛教语意为荫覆 。也译作“阴”,如佛经以色、受、想、行、藏为五阴,也作五蕴。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3213wx','横','1','héng hèng','木','15','','[{"pinyin": "héng", "defs": [{"meaning": "(形声。从木,黄声。本义:门框下部的横木)。"}, {"meaning": "同本义。", "cites": [{"t": "横,闲木也。", "b": "《说文》。字亦作桁。"}, {"t": "以横为之。", "b": "《诗·陈风·横门之下》"}], "words": [{"w": "横轼", "t": "古代车前供人凭倚的横木。"}]}, {"meaning": "侧,旁边。", "cites": [{"t": "时横隤以阳遂。", "b": "王褒《洞箫赋》。注:“旁决貌。”"}], "words": [{"w": "横头", "t": "正面两侧的位置,或长方形物体较短两侧的位置"}, {"w": "横屋", "t": "正屋前两侧的房屋"}, {"w": "横道", "t": "旁道"}, {"w": "横逸", "t": "犹旁出,旁行。"}]}, {"meaning": "古代负有督察记录权责的官员,可以入人于罪者。", "cites": [{"t": "下有五横,以揆其官。", "b": "《管子·君臣》"}]}, {"meaning": "地理上指东西向。与“纵”相对。", "cites": [{"t": "横田其亩。", "b": "《韩诗南山》。传:“东西曰横。”"}, {"t": "不别横与纵。", "b": "《楚辞·沈江》。注:“纬曰横。”"}, {"t": "纵横间之。", "b": "《淮南子·览冥》"}, {"t": "坐横弓。", "b": "《仪礼·大射仪》。注:“南踣弓也。\\""}, {"t": "曰从与横。", "b": "《太玄卷·七玄莹》。注:“东西曰横。”"}], "words": [{"w": "横织", "t": "纵横交织"}, {"w": "横厉", "t": "纵横凌厉,形容气势强盛"}, {"w": "横驱", "t": "纵横驰驱"}, {"w": "横驱别骛", "t": "纵横奔驰。"}]}, {"meaning": "跟地面平行的。", "cites": [{"t": "横柯上蔽。", "b": "吴均《与朱元思书》"}], "words": [{"w": "横枝", "t": "主干上横长的树枝,比喻正宗以外旁衍的支派"}, {"w": "横軃", "t": "横躺而睡着"}, {"w": "横堑", "t": "与前方平行的濠沟"}, {"w": "横卷", "t": "左右两端有轴的横幅书画。"}]}, {"meaning": "自左到右或自右到左。", "cites": [{"t": "横执之。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "横无际涯。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "横有八荒。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "横卧一楫。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "横头", "t": "在方桌筵席上,主席两侧的位置"}, {"w": "横川", "t": "数字三的隐语"}, {"w": "横字", "t": "横行的字"}, {"w": "横阵", "t": "横排的阵势。"}]}, {"meaning": "广,宽广。", "cites": [{"t": "广为横。", "b": "《史记·周本纪》正义"}], "words": [{"w": "横广", "t": "广阔;广大"}, {"w": "横沙", "t": "广阔的沙漠"}, {"w": "横制", "t": "广泛控制"}, {"w": "横览", "t": "广泛观察"}, {"w": "横赐", "t": "帝王对臣民广施赏赐。"}]}, {"meaning": "横陈。", "cites": [{"t": "有神十人,各曰女娲之肠,横道而处。", "b": "《山海经·大荒西经》"}], "words": [{"w": "横刀", "t": "横陈佩刀"}, {"w": "横天", "t": "横陈天空"}, {"w": "横身", "t": "插身,插手"}, {"w": "横江", "t": "横陈江上"}, {"w": "横路", "t": "横陈道中"}, {"w": "横经", "t": "横陈经籍。"}]}, {"meaning": "横渡;横越。", "cites": [{"t": "乃帅群臣横大河。", "b": "《汉书·扬雄传上》"}], "words": [{"w": "横厉", "t": "横越;横渡"}, {"w": "横截", "t": "横渡"}, {"w": "横天", "t": "横越天空"}, {"w": "横江", "t": "横越江上"}, {"w": "横绝", "t": "横越;横度"}, {"w": "横霄", "t": "横越天空。"}]}, {"meaning": "充满;遮盖。", "cites": [{"t": "以横于天下。", "b": "《礼记·孔子闲居》。注:“充也。”"}, {"t": "横被四表。", "b": "《后汉书·冯异传》"}, {"t": "号以立横。", "b": "《礼记·乐记》"}], "words": [{"w": "横世", "t": "充满世间"}, {"w": "横出", "t": "充分表露;洋溢"}, {"w": "横流", "t": "充盈;遍布"}, {"w": "横滋", "t": "四处滋长。"}]}, {"meaning": "交错,错杂。", "cites": [{"t": "禁野之横行径逾者。", "b": "《周礼·野庐氏》。注:“妄行田中。”"}], "words": [{"w": "横飞", "t": "交错飞行"}, {"w": "横落", "t": "交错落下。"}]}, {"meaning": "姓。"}]}, {"pinyin": "hèng", "defs": [{"meaning": "横暴;放纵。", "cites": [{"t": "处士横议,以待我以横逆,横政之所出,横民之所止。", "b": "《孟子》。按,皆纵恣悍厉之谓。"}, {"t": "横行天下。", "b": "《荀子·修身》。注:“不顺理而行也。”"}, {"t": "东夷横畔。", "b": "扬雄《长杨赋》。注:“自纵也。”"}, {"t": "以威力相胁曰横。", "b": "《汉书·彭宠传》注"}], "words": [{"w": "蛮横;横政", "t": "暴政"}, {"w": "横侈", "t": "专横放纵"}, {"w": "横虐", "t": "专横肆虐"}, {"w": "横逆", "t": "横暴不顺理"}, {"w": "横逞", "t": "放纵恣肆"}, {"w": "横施", "t": "肆意施加"}, {"w": "横议", "t": "恣肆批评"}, {"w": "横杀", "t": "肆意杀戳。"}]}, {"meaning": "祸害。", "cites": [{"t": "谓为三横。", "b": "《世说新语·自新》"}, {"t": "三横唯余其一。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3214wx','槽','1','cáo','木','15','','[{"pinyin": "cáo", "defs": [{"meaning": "(形声。从木,曹声。本义:四边高起,中间凹入的畜兽饮食器具)。"}, {"meaning": "同本义。", "cites": [{"t": "骈死于槽枥之间。", "b": "唐·韩愈《杂说》"}, {"t": "又尝梦三马同食一槽。", "b": "《晋书·宣帝纪》"}], "words": [{"w": "马槽;猪槽;槽头", "t": "马厩,马圈"}, {"w": "槽子", "t": "槽;养牲口的槽"}, {"w": "槽道", "t": "牲口槽;规矩。"}]}, {"meaning": "表面上比较大比较长的凹痕。", "cites": [{"t": "于木槽中下水,脚蹋十遍。", "b": "《齐民要术·种红蓝花栀子》"}], "words": [{"w": "溜槽;键槽;槽牙", "t": "臼齿的俗称。"}]}, {"meaning": "沟槽数。"}, {"meaning": "旧时把仰瓦铺在两椽中间,从梁上到檐口的一溜屋瓦叫一槽瓦。"}, {"meaning": "大小大致相同而同在一槽吃食的一批猪叫一槽猪。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3215wx','樱','1','yīng','木','15','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从木,婴声。本义:木名。即“樱桃树”)。"}, {"meaning": "同本义。泛指其树、其花、其果。"}, {"meaning": "樱桃花。", "cites": [{"t": "尚疑樱欲吐,已怪菊成漂。", "b": "王安石《雨中》"}], "words": [{"w": "樱桃", "t": "借指美人的小口,谓其红润如樱桃"}, {"w": "樱桃九熟", "t": "骨牌戏用语,指两张地牌,一张么四共九点红点"}, {"w": "樱笋", "t": "樱桃与春笋"}, {"w": "樱笋年光", "t": "指阳春三月"}, {"w": "樱笋时", "t": "樱桃与春笋上市的时候。指农历三月"}, {"w": "樱桃宴", "t": "科举时代庆贺新进士及第的宴席"}, {"w": "樱唇", "t": "喻指女子小而红润的嘴唇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3216wx','橡','1','xiàng','木','15','','[{"pinyin": "xiàng", "defs": [{"meaning": "栎树的别名。", "cites": [{"t": "柞之实谓之橡。", "b": "《小尔雅》"}, {"t": "栎有两种:一种不结实者,…一种结实者,其名曰栩,其实为橡。", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3217wx','樟','1','zhāng','木','15','','[{"pinyin": "zhāng", "defs": [{"meaning": "常绿乔木 ,叶卵形,夏季开黄白色小花,果实黑色,大如豌豆,木质坚固细致,有香气,做成箱柜,可以防蠹虫。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3218wx','橄','1','gǎn','木','15','','[{"pinyin": "gǎn", "defs": [{"meaning": "油橄榄，也叫\\"齐墩果\\"。常绿小乔木，开白花。果实黑色，可生吃，可榨油（橄榄油）。欧美等国使用它的枝叶（橄榄枝）作为和平的象征。"}, {"meaning": "橄榄树，我国特产。常绿乔木，羽状复叶，开白花。果实长圆形，绿色，叫\\"青果\\"，可吃也供药用。种子可以榨油，树脂可供药用。", "cites": [{"t": "华大妈也黑着眼眶，笑嘻嘻的送出茶碗茶叶来，加上一个橄榄，老栓便去冲了水。--鲁迅《药》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3219wx','敷','1','fū','攵','15','','[{"pinyin": "fū", "defs": [{"meaning": "(形声。从攴(pū),表示与动作有关。“搏”是“布列”的意思,在字中也具有表意作用。本义:施予;给予)。"}, {"meaning": "同本义。", "cites": [{"t": "勘定厥功,用敷遗后人休。", "b": "《书·康王之诰》"}, {"t": "敷政优优,百禄是道。", "b": "《诗·商颂·长发》"}, {"t": "舜不忍伐,而敷之文德。", "b": "皮日休《原弈》"}], "words": [{"w": "敷民", "t": "施于人民。敷:布施"}, {"w": "敷施", "t": "布施"}, {"w": "敷锡", "t": "施赐"}, {"w": "敷教", "t": "布施教化。"}]}, {"meaning": "铺展;铺开。", "cites": [{"t": "禹敷土,随山刊木,奠高山大川。", "b": "《书·禹贡》"}, {"t": "牖间南向,敷重篾席。", "b": "《书·顾命》"}, {"t": "敷宴席。", "b": "《穆天子传》"}, {"t": "离城三里,止营傅陈。", "b": "《汉书·陈汤传》。师古曰:“傅,读曰敷。敷,布也。”"}]}, {"meaning": "搽,涂上。", "cites": [{"t": "头上周围一转的短发…越显得面如敷粉,唇若施脂。", "b": "《红楼梦》"}], "words": [{"w": "敷粉;敷药", "t": ""}]}, {"meaning": "(bù)。宣告;陈述。", "cites": [{"t": "不能敷扬五教,翼赞日月。", "b": "《后汉书·张网传》"}, {"t": "善敷者辞殊而义显。", "b": "《文心雕龙·鎔裁》"}], "words": [{"w": "敷布", "t": "陈述"}, {"w": "敷文", "t": "铺陈文藻"}, {"w": "敷畅", "t": "敷陈发扬"}, {"w": "敷奏", "t": "敷陈上奉"}, {"w": "敷释", "t": "铺叙阐释"}, {"w": "敷布", "t": "叙陈。"}]}, {"meaning": "开。", "cites": [{"t": "用花者取花初敷时。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "敷英", "t": "开花"}, {"w": "敷秀", "t": "敷英;敷披。开放"}, {"w": "敷荣", "t": "繁荣;开花"}, {"w": "敷华", "t": "开花。"}]}, {"meaning": "足,够。", "cites": [{"t": "以二十余人而居屋十间,食田一顷,即量腹而食,度足而居,吾以知其必不敷矣。", "b": "清·洪亮吉《治平篇》"}], "words": [{"w": "入不敷出;敷余", "t": "多余;多出。"}]}, {"meaning": "分布;散布。", "cites": [{"t": "敷时绎思,我徂维求定。", "b": "《诗·周颂·赍》"}], "words": [{"w": "敷芬", "t": "发散香气"}, {"w": "敷条", "t": "展枝"}, {"w": "敷闻", "t": "使名声远扬"}, {"w": "敷兴", "t": "广布而使人高兴。"}]}, {"meaning": "生长。", "cites": [{"t": "筱簜既敷,厥草惟夭,厥木惟乔。", "b": "《书·禹贡》"}]}, {"meaning": "(fù)。附着。", "cites": [{"t": "郭门在外为衡,以两木当门,凿其木,维敷上堞。", "b": "《墨子·备城门》"}]}, {"meaning": "普遍。", "cites": [{"t": "敷天之下。", "b": "《诗·周颂·般》"}], "words": [{"w": "敷求", "t": "广求;遍求"}, {"w": "敷洽", "t": "广布"}, {"w": "敷寻", "t": "广泛寻访"}, {"w": "敷广", "t": "广泛传播"}, {"w": "敷光", "t": "普照。"}]}, {"meaning": "浅薄。", "cites": [{"t": "末学敷浅,诚所未详。", "b": "顾野王《上呈启》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3220wx','豌','1','wān','豆','15','','[{"pinyin": "wān", "defs": [{"meaning": "一年生或二年生草本植物，结荚果。嫩荚和种子可食。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3221wx','飘','1','piāo','风','15','','[{"pinyin": "piāo", "defs": [{"meaning": "(形声。从风,票声。本义:旋风;暴风) 同本义。", "cites": [{"t": "飘,回风也。…盘旋而起。", "b": "《说文》"}, {"t": "少阳所至为飘风。", "b": "《素问·六元正纪论》"}, {"t": "回风为飘。", "b": "《尔雅》"}, {"t": "其为飘风。", "b": "《诗·小雅·何人斯》"}, {"t": "飘至风起。", "b": "《汉书·蒯通传》"}, {"t": "飘风不终朝。", "b": "《老子》。注:“飘风,疾风也。”"}], "words": [{"w": "飘风", "t": "旋风"}, {"w": "飘骤", "t": "疾风骤雨。比喻事物突然骤起"}, {"w": "飘风骤雨", "t": "突然而来的旋风暴雨。比喻不能长久。"}]}, {"meaning": "飘扬,飞扬。", "cites": [{"t": "飘如游云,矫若惊龙。", "b": "《世说新 语·容止》"}, {"t": "山河破碎风飘絮。", "b": "宋·文天祥《过零丁洋》"}], "words": [{"w": "飘姚", "t": "飘动的样子。即飘摇"}, {"w": "飘瓦", "t": "飞起的瓦片"}, {"w": "飘袖", "t": "衣袖随风飘扬。形容雪花飞舞的样子"}, {"w": "飘旋", "t": "飞舞"}, {"w": "飘逝", "t": "飞逝"}, {"w": "飘翔", "t": "飞翔,高飞"}, {"w": "飘登", "t": "飞升"}, {"w": "飘絮", "t": "随风飞舞的柳絮"}, {"w": "飘瞥", "t": "雪花飞舞的样子。"}]}, {"meaning": "落。", "cites": [{"t": "一春梦雨常飘瓦,尽日灵风不满旗。", "b": "唐·李商隐《重过圣女祠》"}], "words": [{"w": "飘瓦", "t": "自屋顶落下的瓦片。比喻意外的灾祸"}, {"w": "飘坠", "t": "飘零,落下"}, {"w": "飘堕", "t": "飘失,坠落"}, {"w": "飘殚", "t": "凋落"}, {"w": "飘淋", "t": "流泻。"}]}, {"meaning": "流离,浮荡。", "cites": [{"t": "飘零何所似,天地一沙鸥。", "b": "杜甫《旅夜书怀》"}], "words": [{"w": "飘兀", "t": "随波飘离"}, {"w": "飘泊", "t": "随水飘流。比喻流离失所"}, {"w": "飘流", "t": "比喻四处流浪"}, {"w": "飘洒", "t": "流荡;浪荡"}, {"w": "飘零书剑", "t": "形容古代文人游学四方,到处漂泊"}, {"w": "飘寄", "t": "飘流寄寓。即飘泊"}, {"w": "飘寓", "t": "飘泊旅寄"}, {"w": "飘萍", "t": "随风飘荡的浮萍。比喻飘泊不定。"}]}, {"meaning": "吹。", "cites": [{"t": "人多私铸。[钱]稍就薄小,乃至风飘水浮。", "b": "《北史·杨侃传》"}], "words": [{"w": "飘英", "t": "风吹拂着兵器上的饰物"}, {"w": "飘翥", "t": "被风吹飞"}, {"w": "飘飘", "t": "风吹的样子。"}]}, {"meaning": "迅疾。", "cites": [{"t": "圣人则不可以飘矣。", "b": "《吕氏春秋·观表》"}], "words": [{"w": "飘迅", "t": "快速;短促"}, {"w": "飘逸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3222wx','醋','1','cù','酉','15','','[{"pinyin": "cù", "defs": [{"meaning": "(形声。从酉(yǒu),声。从“酉”,表示与酒有关。本义:用酒或酒糟发酵制成的一种酸味调料)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3223wx','醇','1','chún','酉','15','','[{"pinyin": "chún", "defs": [{"meaning": "(形声。本义:酒味浓厚)。"}, {"meaning": "同本义。", "cites": [{"t": "醇,厚也。", "b": "《说文》"}, {"t": "买二石醇醪。", "b": "《汉书·爰盎传》"}, {"t": "春醴惟醇。", "b": "张衡《东京赋》"}, {"t": "醉醇醲而饫肥鲜者。", "b": "刘基《卖柑者言》"}], "words": [{"w": "醇醨", "t": "味道浓厚的美酒叫做醇,味道淡薄的叫做醨"}, {"w": "醇醪", "t": "纯厚的美酒"}, {"w": "醇味", "t": "美酒味"}, {"w": "醇旨", "t": "酒味淳厚甘美。"}]}, {"meaning": "淳朴;质朴。", "cites": [{"t": "至于移风易俗,黎民醇厚。", "b": "《汉书·景帝纪赞》"}, {"t": "古者人醇工庞。", "b": "《淮南子·泛论》。注:“醇厚不虚华也。”"}], "words": [{"w": "醇固", "t": "真纯贞固"}, {"w": "醇正", "t": "淳厚端正"}, {"w": "醇和", "t": "淳朴和善。"}]}, {"meaning": "无杂质。", "cites": [{"t": "惟厥攸居,政事惟醇。", "b": "《书·说命中》"}, {"t": "河龙供鲤醇牺牲。", "b": "《汉书·礼乐志》。颜师古注:“醇,谓色不杂也。”"}, {"t": "以贤则君有醇固之茂焉。", "b": "《三国志·何夔传》"}, {"t": "其皆醇也,然后肆焉。", "b": "韩愈《答李诩书》"}], "words": [{"w": "醇壹", "t": "纯厚专一"}, {"w": "醇备", "t": "精粹完美"}, {"w": "醇粹", "t": "纯一不杂。"}]}, {"meaning": "任何一类在结构上类似乙醇的化合物 ,可看作烃的羟基衍生物,并按照羟基的数目而分类(如一元醇、二元醇、三元醇和多元醇)或者按照分子的结构而分类。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3224wx','醉','1','zuì','酉','15','','[{"pinyin": "zuì", "defs": [{"meaning": "(会意。从酉(yǒu),从卒。“酉”表示酒,“卒”表示终结。酒喝到不能再喝的时候,就醉了。本义:醉酒)。"}, {"meaning": "同本义(饮酒过量,神志不清)。", "cites": [{"t": "醉,酒卒也。各卒其度量,不至于乱也。一曰酒溃也。", "b": "《说文》。"}, {"t": "既醉而出,并受其福。", "b": "《诗·小雅·宾之初筵》"}, {"t": "对饮酒醉。", "b": "唐·柳宗元《童区寄传》"}, {"t": "醉里吴音相媚好。", "b": "宋·辛弃疾《清平乐·村居》"}, {"t": "沉醉不知归路。", "b": "宋·李清照《如梦令》"}, {"t": "醉能同其乐,醒能述以文者。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "苍颜白发,頺然乎其间者,太守醉也。", "b": ""}, {"t": "醉醇醲。", "b": "明·刘基《卖柑者言》"}, {"t": "酉,为酒所酣曰醉。", "b": "《洪武正韵》"}], "words": [{"w": "醉是醒时言", "t": "醉后说的常是真心话"}, {"w": "醉饱", "t": "酒足饭饱"}, {"w": "醉沈", "t": "指酒后所作的书画"}, {"w": "醉魔咕咚", "t": "醉呼呼"}, {"w": "醉兴勃勃", "t": "醉后神情亢奋"}, {"w": "醉呼卢", "t": "醉呼呼睡大觉"}, {"w": "醉沉沉", "t": "沉醉的样子。"}]}, {"meaning": "用酒浸制的。", "cites": [{"t": "瓮中取醉蟹,最忌用灯。", "b": "《闲情偶寄》"}], "words": [{"w": "醉蟹", "t": "酒渍的螃蟹"}, {"w": "醉虾", "t": ""}]}, {"meaning": "沉酣入迷;爱好。", "cites": [{"t": "目断南浦云,心醉东郊柳。", "b": "《送赵六贞固》"}], "words": [{"w": "醉乡砚田", "t": "沉缅于美酒与文墨之间"}, {"w": "醉飞吟盏", "t": "在喝酒的同时作诗"}, {"w": "醉侯", "t": "称喜欢喝酒而又有酒量的人"}, {"w": "醉翁", "t": "喜好喝酒的老人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3225wx','磕','1','kē','石','15','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从石hé声。本义:石声或鼓声) 同本义。"}, {"meaning": "石头撞击声。", "cites": [{"t": "磕,石声。", "b": "《说文》"}]}, {"meaning": "物相碰声。", "cites": [{"t": "榜舫兮下流,东注兮磕磕。", "b": "汉·王褒《九怀尊嘉》"}], "words": [{"w": "磕擦擦", "t": "形容物体磨擦碰撞声或马蹄声"}, {"w": "磕磕", "t": "物相碰声"}, {"w": "磕扑扑", "t": "急促的脚步声。"}]}, {"meaning": "眯稳莸犊痴渡鄙H磕叉(磕叉叉;磕擦。砍砸斩杀声)。"}, {"meaning": "碰击,碰撞。", "cites": [{"t": "云缠风束乱敲磕。", "b": "杜牧《大雨行》"}], "words": [{"w": "磕打", "t": "捶打;比喻折磨"}, {"w": "磕开", "t": "击开;撞开"}, {"w": "磕撞", "t": "碰撞,撞击"}, {"w": "磕竹", "t": "用两块瓢形的竹、木片占卜吉凶"}, {"w": "磕牙料嘴", "t": "斗嘴,耍嘴皮子"}, {"w": "磕绊", "t": "由说话引起的争端冲突。"}]}, {"meaning": "(kè)。用上下牙咬有壳的或硬的东西。", "cites": [{"t": "黛玉磕着瓜子儿,只管抿着嘴儿笑。", "b": "《红楼梦》"}]}, {"meaning": "叩头,旧时的跪拜礼。", "cites": [{"t": "爹!就这样跪着磕吧,别换衣服啦。", "b": "曹禺《北京人》"}], "words": [{"w": "磕头礼拜", "t": "叩头行礼"}, {"w": "磕扑", "t": "双膝同时着地的声音。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3226wx','磊','1','lěi','石','15','','[{"pinyin": "lěi", "defs": [{"meaning": "(会意。从三石。“三”非确数,表示很多。本义:石头多) 众石累积。", "cites": [{"t": "磊,众石也。", "b": "《说文》。字亦作礧。"}, {"t": "水玉磊砢。", "b": "司马相如《上林赋》。注:“魁礨貌。”"}, {"t": "石磊磊兮葛蔓蔓。", "b": "《楚辞》"}, {"t": "磊砢相扶。", "b": "王逸《鲁灵光殿赋》"}], "words": [{"w": "磊砢", "t": "磊珂。众多委积,众多委积的石头"}, {"w": "磊块", "t": "众石累积"}, {"w": "磊磊", "t": "山石很多的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3227wx','磅','1','bàng páng','石','15','','[{"pinyin": "bàng", "defs": [{"meaning": "300克到1070克范围内各种不同的重量单位名称之一。"}, {"meaning": "从前用过的重量名称,现只理论上存在,每磅等于5760格令或373克。"}, {"meaning": "现时讲英语民族普遍使用的重量名称,每磅等于7000格令或453克。"}, {"meaning": "衡量印刷字体大小的单位,约等于七十二分之一英寸。"}]}, {"pinyin": "páng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3228wx','碾','1','niǎn','石','15','','[{"pinyin": "niǎn", "defs": [{"meaning": "(形声。从石,展声。本义:磙压;碾轧)。"}, {"meaning": "同本义。", "cites": [{"t": "碾,所以轹物器也。", "b": "《集韵》"}], "words": [{"w": "碾米;碾轧", "t": "磙压"}, {"w": "碾械", "t": "木制者称“檑木”,石制者称“礌石”。战时从高处推下打击敌人。"}]}, {"meaning": "碾磨。", "cites": [{"t": "小娥旋拂碾新茶。", "b": "司空图《暮春对柳》"}]}, {"meaning": "用于使谷物等破碎、去皮或使场地、道路等变平的工具。", "cites": [{"t": "遂教民为碾。", "b": "《魏书·崔亮传》"}], "words": [{"w": "水碾;石碾;汽碾;碾台", "t": "碾盘"}, {"w": "碾船", "t": "碾药的器具。即药碾子"}, {"w": "碾房", "t": "碾谷磨面的屋子或作坊"}, {"w": "碾窝", "t": "即碾房。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3229wx','震','1','zhèn','雨','15','','[{"pinyin": "zhèn", "defs": [{"meaning": "(形声。从雨,辰声。雷、雨常常并作,故从雨。本义:雷,疾雷)。"}, {"meaning": "同本义。", "cites": [{"t": "震,劈历振物者。", "b": "《说文》"}, {"t": "三月癸酉,大雨震电。", "b": "《春秋》。孔颖达疏:“何休云:震,雷也。电,霆也。”。"}], "words": [{"w": "震震", "t": "雷、鼓、车、马等所发出的巨响"}, {"w": "震厉", "t": "雷声"}, {"w": "震霆", "t": "轰雷,响雷"}, {"w": "震雷", "t": "响雷"}, {"w": "震响", "t": "震雷似的响声。"}]}, {"meaning": "八卦之一。雷之象。", "cites": [{"t": "万物出乎震。震,东方也。", "b": "《易·说卦》。"}], "words": [{"w": "震宫", "t": "东方"}, {"w": "震方", "t": "震位,震维。东方"}, {"w": "震区", "t": "东方。"}]}, {"meaning": "威势;威严。", "cites": [{"t": "夫兵戢而时动,动则威,观则玩,玩则无震。", "b": "《国语·周语上》"}, {"t": "畏君之震。", "b": "《左传·成公二年》。"}], "words": [{"w": "震灼", "t": "威势极盛"}, {"w": "震肃", "t": "因慑于威势而肃然。"}]}, {"meaning": "震动,物体自身动荡或使物体动荡。", "cites": [{"t": "后数日驿至,果地震陇西。", "b": "《后汉书·张衡传》"}, {"t": "雷奔电泄,震天动地。", "b": "《水经注·河水》"}, {"t": "以类天之震曜杀戮也。", "b": "《汉书·刑法志》"}, {"t": "震惊朕师。", "b": "《书·舜典》"}, {"t": "余威震于殊俗。", "b": "汉·贾谊《过秦论》"}, {"t": "内地为之震。", "b": "清·邵长蘅《青门剩稿》。"}], "words": [{"w": "震掉", "t": "颤动"}, {"w": "震域", "t": "地震波及的范围"}, {"w": "震裂", "t": "物体因受震动而裂开"}, {"w": "震主之威", "t": "指人威势极为盛大,使君王畏忌不安。"}]}, {"meaning": "震惊;惊惧;使惊惧。", "cites": [{"t": "愿承闲而自察兮,心震悼而不敢。", "b": "《楚辞·九章·抽思》"}, {"t": "簿者数内大使以震其君。", "b": "《韩非子·八奸》"}, {"t": "权以示群下,莫不响震失色。", "b": "《资治通鉴》。"}], "words": [{"w": "震汗", "t": "因惊惧而颤抖出汗"}, {"w": "震怖", "t": "惊恐"}, {"w": "震悸", "t": "惊怖恐惧"}, {"w": "震慑", "t": "震惧。形容极害怕。"}]}, {"meaning": "心动;激动。", "cites": [{"t": "若听乐而震,观美而眩,患莫甚焉。", "b": "《国语·周语下》。"}], "words": [{"w": "震怜", "t": "动情怜恤。"}]}, {"meaning": "振兴;振奋。", "cites": [{"t": "莫不震叠。", "b": "《诗·周颂·时迈》"}, {"t": "滞久而不震,生乃不殖。", "b": "《国语》。"}], "words": [{"w": "震奋", "t": "振作奋发"}, {"w": "震发", "t": "奋发,奋起"}, {"w": "震激", "t": "振作激发。"}]}, {"meaning": "怒。", "cites": [{"t": "震于廷。", "b": "《太玄·释》。范望注:“震,怒也。”。"}], "words": [{"w": "震恚", "t": "大怒,盛怒"}, {"w": "震扑", "t": "怒而攻打"}, {"w": "震愤", "t": "大怒。"}]}, {"meaning": "地震。", "cites": [{"t": "八月丁酉,南宫极震。", "b": "《左传·昭公二十三年》"}, {"t": "震之所在。(地震所在的方位。)", "b": "《后汉书·张衡传》。"}], "words": [{"w": "震中;震波;震级", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3230wx','霄','1','xiāo','雨','15','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从雨;肖声。本义:米雪)。"}, {"meaning": "同本义。", "cites": [{"t": "霄,雨霓为宵。", "b": "《说文》"}, {"t": "雨霓为霄雪。", "b": "《国语·齐语》。注:“冰雪杂下者谓之霄。”"}, {"t": "风助霄仍汹。", "b": "《和吴冲卿雪诗》"}], "words": [{"w": "霄雪", "t": "下霰。"}]}, {"meaning": "高空稀薄游动的云。", "cites": [{"t": "霄,日旁气也。", "b": "《汉书·扬雄传》注"}, {"t": "霄,摩天赤气也。", "b": "《后汉书·仲长统传》注"}, {"t": "霄,云也。", "b": "《后汉书·张衡传》注"}, {"t": "气似天霄。", "b": "木华《海赋》"}, {"t": "腾虹扬霄。", "b": "郭璞《江赋》"}]}, {"meaning": "云际;天空。", "cites": [{"t": "乘云陵霄。", "b": "《淮南子·原道》"}, {"t": "霄霭而晻暖。", "b": "王逸《鲁灵光殿赋》"}, {"t": "森然千霄。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "凌霄之志;九霄;霄外", "t": "云霄之外,天外"}, {"w": "霄衢", "t": "天路。"}]}, {"meaning": "夜晚。", "cites": [{"t": "有众日并出,有昼盲,有霄见。", "b": "《吕氏春秋·明理》"}, {"t": "霄涉颍与楚人盟。", "b": "《左传》"}]}, {"meaning": "消灭;消失。", "cites": [{"t": "霄尽,荡也。顺长,治也。", "b": "《墨子·经说上》"}, {"t": "忽不悟其所舍,怅神霄而蔽光。", "b": "曹植《洛神赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3231wx','霉','1','méi','雨','15','','[{"pinyin": "méi", "defs": [{"meaning": "在各类有机物及活植物上通常在表面由真菌如白粉菌科和霜霉菌科形成的白色生长物。"}, {"meaning": "面垢黑。", "cites": [{"t": "徾,中久雨青黑。", "b": "《说文》"}, {"t": "颜徾黧以沮败兮。", "b": "《楚辞·刘向·九叹逢纷》"}, {"t": "尧瘦臞,舜徾黑。", "b": "《淮南子·脩务》"}], "words": [{"w": "霉瘠", "t": "黑而瘦"}, {"w": "霉黧", "t": "形容面垢黑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3232wx','瞒','1','mán','目','15','','[{"pinyin": "mán", "defs": [{"meaning": "(形声。本义:眼睑低。闭目貌)。"}, {"meaning": "同本义。", "cites": [{"t": "瞒,平目也。", "b": "《说文》"}, {"t": "酒食声色之中,则瞒瞒然。", "b": "《荀子》"}], "words": [{"w": "瞒瞒", "t": "闭目貌。"}]}, {"meaning": "隐藏实情。", "cites": [{"t": "什么事瞒的过我?", "b": "《红楼梦》"}], "words": [{"w": "瞒产", "t": "隐瞒产量"}, {"w": "瞒落", "t": "隐瞒留下"}, {"w": "瞒藏", "t": "隐匿"}, {"w": "瞒天瞒地", "t": "犹言瞒上欺下"}, {"w": "瞒昧", "t": "隐瞒欺骗"}, {"w": "瞒瞒昧昧", "t": "隐瞒欺骗。"}]}, {"meaning": "欺骗(瞒当谩讲,是晚起字)。", "cites": [{"t": "我把你个泼猴!你瞒谁哩?", "b": "《西游记》"}], "words": [{"w": "瞒唬", "t": "欺骗吓唬"}, {"w": "瞒心", "t": "昧着良心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3233wx','题','1','tí','页','12','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从页(xié),是声。页,头。本义:额头)。"}, {"meaning": "同本义。", "cites": [{"t": "题,额也。", "b": "《说文》"}, {"t": "雕题交趾。", "b": "《礼记·王制》"}, {"t": "赤眉圆题。", "b": "《汉书·司马相如传》"}, {"t": "夫加之以衡扼,齐之以月题。", "b": "《庄子·马蹄》。释文引司马崔云:“月题,马额上当颅如月形者也。”"}, {"t": "文题白身,名曰孟极。", "b": "《山海经·北山经》"}, {"t": "雕题黑齿。", "b": "《楚辞·招魂》"}, {"t": "连缓耳,琐雕题。", "b": "《后汉书·杜笃传》"}]}, {"meaning": "《雕题交阯》——《后汉书·南蛮西南夷传》。", "words": [{"w": "题注", "t": "以头额撞击"}, {"w": "黑牛白题", "t": "黑牛白额。"}]}, {"meaning": "物品的前端或顶端  堂高数仞,榱题数尺。——《孟子》。", "words": [{"w": "榱题", "t": "屋檐的椽头。榱,椽子。"}]}, {"meaning": "题目;标题。", "cites": [{"t": "臣尝私习此赋,请试他题。", "b": "脱脱等《宋史》"}], "words": [{"w": "试题", "t": "考试时让应考者作答的问题"}, {"w": "题头", "t": "标题,篇目"}, {"w": "题意", "t": "题目的旨意"}, {"w": "题号", "t": "标题名称"}, {"w": "题位", "t": "题目的要求,作文的规则。"}]}, {"meaning": "书签;标签。", "cites": [{"t": "委之在深箧,蠹鱼坏其题。", "b": "唐·李白《感兴八首》"}]}, {"meaning": "标志。", "cites": [{"t": "欲垦荒田,先立表题。", "b": "《晋书》"}]}, {"meaning": "奏章。明、清两代公文用语之一。又指上奏 。", "words": [{"w": "题参", "t": "参奏;奏本弹劾"}, {"w": "题本", "t": "上奏章"}, {"w": "题估", "t": "清代公文用语"}, {"w": "题奏", "t": "题本用奏本"}, {"w": "题留", "t": "清代公文用语"}, {"w": "题补", "t": "清代公文用语"}, {"w": "题销", "t": "上奏报销"}, {"w": "题请", "t": "上奏呈请。"}]}, {"meaning": "书写;题署。", "cites": [{"t": "题名其上。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "题赞", "t": "在书画上题写几句有关的话或留作纪念的话"}, {"w": "题款", "t": "署名或题字在书画上"}, {"w": "题诗", "t": "作诗。题在书画,器物或墙壁之上"}, {"w": "题叶", "t": "在叶上题诗"}, {"w": "题署(签署,书写文书封筒;题壁(在壁上题诗写字))", "t": ""}]}, {"meaning": "谈及。", "cites": [{"t": "且把闲话休题。", "b": "《水浒传》"}], "words": [{"w": "休题旧事;题说", "t": "说起。"}]}, {"meaning": "品评;评论。", "cites": [{"t": "一经品题,便作佳士。", "b": "李白《与韩荆州书》"}], "words": [{"w": "题拂", "t": "评论,标榜"}, {"w": "题品", "t": "品评。也作题评"}, {"w": "题评", "t": "品评。同题品。"}]}, {"meaning": "鸣;叫。", "cites": [{"t": "遍青山,题经子杜鹃。", "b": "明·汤显祖《牡丹亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3234wx','暴','1','bào pù','日','15','','[{"pinyin": "bào", "defs": [{"meaning": "显露;暴露。", "cites": [{"t": "暴于南荣。", "b": "《史记·司马相如传》"}, {"t": "今我使二国暴骨。", "b": "《左传·宣公十二年》"}, {"t": "尸捐不收,骨暴不葬。", "b": "《论衡·祸虚》"}, {"t": "其所摧败,功亦足以暴于天下矣。", "b": "司马迁《报任安书》"}], "words": [{"w": "暴师", "t": "驻扎在野外的军队"}, {"w": "暴骸", "t": "暴露尸骸"}, {"w": "暴骨", "t": "暴露尸骨"}, {"w": "暴尸", "t": "暴露尸骸。"}]}, {"meaning": "糟蹋,损害。", "cites": [{"t": "田不以礼,曰暴天物。", "b": "《礼记》"}], "words": [{"w": "自暴自弃;以众暴寡;暴殄轻生", "t": "肆意践踏,轻视生命"}, {"w": "暴殄", "t": "残害自然。"}]}, {"meaning": "欺凌。", "cites": [{"t": "自是之后,以强陵弱,以众暴寡。", "b": "《庄子·盗跖》"}], "words": [{"w": "暴陵", "t": "欺压凌辱。"}]}, {"meaning": "徒手搏。", "cites": [{"t": "不敢暴虎,不敢冯河。", "b": "《诗·小雅》"}]}, {"meaning": "凶恶,残暴。", "cites": [{"t": "伐无道,诛暴秦。", "b": "《史记·陈涉世家》"}], "words": [{"w": "暴人", "t": "凶恶残暴的人"}, {"w": "暴兵", "t": "暴虐的军士"}, {"w": "暴敌", "t": "凶暴的敌人"}, {"w": "暴豪", "t": "凶暴强横。"}]}, {"meaning": "急骤;猛烈。", "cites": [{"t": "终风且暴。", "b": "《诗·邶风·终风》"}, {"t": "飘风(暴风)暴雨为民害。", "b": "《管子·小问》"}], "words": [{"w": "暴雷;暴洪;暴暴", "t": "急速兴起的样子"}, {"w": "暴水", "t": "洪水。"}]}, {"meaning": "脾气过分急躁。", "cites": [{"t": "性行暴如雷。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "虫暴怒。", "b": "《聊斋志异·促织》"}], "words": [{"w": "脾气暴;粗暴", "t": "鲁莽;暴躁"}, {"w": "暴气", "t": "暴躁的脾气"}, {"w": "暴跳如雷", "t": ""}]}, {"meaning": "突然;猝然。", "cites": [{"t": "今暴得大名,不祥。", "b": "《史记·项羽本纪》"}, {"t": "矜(自负)壮士暴死。", "b": "唐·柳宗元《敌戒》"}, {"t": "屠暴起。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "暴卒", "t": "突然死亡"}, {"w": "暴忽", "t": "快速;飘忽"}, {"w": "暴亡", "t": "突然死亡"}, {"w": "暴崩", "t": "突然死亡"}, {"w": "暴富", "t": "突然发财。"}]}, {"meaning": "急剧地。", "words": [{"w": "暴跌;暴落;暴习", "t": "很快熟悉。"}]}]}, {"pinyin": "pù", "defs": [{"meaning": "(会意。古文从日,麃声。从日出艹米。本义:晒)。"}, {"meaning": "同本义。", "cites": [{"t": "暴,日干也。曝,俗。", "b": "《广韵》"}, {"t": "暴,晒也。", "b": "《小尔雅》"}, {"t": "书暴诸日。", "b": "《考工记》"}, {"t": "一日暴之。", "b": "《孟子》"}, {"t": "暴于南荣。", "b": "《史记·司马相如传》。索隐:“偃卧日中也。”"}, {"t": "今我使二国暴骨。", "b": "《左传·宣公十二年》"}, {"t": "言日中时必须暴晒,不尔者,失其时也。", "b": "《颜氏家训·书证》"}], "words": [{"w": "一暴十寒;暴炙", "t": "日晒火烤"}, {"w": "暴背", "t": "曝背;晒背"}, {"w": "暴浣", "t": "曝晒洗涤。"}]}, {"meaning": "暴露;显露。", "cites": [{"t": "暴霜露,斩荆棘,以有尺寸之地。", "b": "宋·苏洵《六国论》"}, {"t": "是以蓼州周公,忠义暴于朝廷,赠谥美显荣于身后。", "b": "明·张溥《五人墓碑记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3235wx','瞎','1','xiā','目','15','','[{"pinyin": "xiā", "defs": [{"meaning": "(形声。从目,害声。本义:一目失明)。"}, {"meaning": "同本义。", "cites": [{"t": "吾闻瞎儿一泪,信乎?", "b": "《资治通鉴》。胡三省注:“瞎,一目盲也。”"}]}, {"meaning": "双目失明。", "cites": [{"t": "盲人骑瞎马,夜半临深池。", "b": "《世说新语》"}], "words": [{"w": "瞎生", "t": "旧称以卜卦算命为业的盲人。"}]}, {"meaning": "形容糊涂,不明事理。", "cites": [{"t": "这呆子!石头又不是人,又不会说话,又不会还礼,唱他喏怎的,可不是个瞎帐。", "b": "《西游记》"}], "words": [{"w": "瞎账", "t": "傻瓜,糊涂虫"}, {"w": "瞎屡生", "t": "佛教语。指最愚蠢的人"}, {"w": "瞎驴", "t": "比喻最愚蠢的人。"}]}, {"meaning": "虚构;捏造。", "cites": [{"t": "小珍哥是瞎神捣鬼,捕影捉风的。", "b": "《醒世姻缘传》"}], "words": [{"w": "瞎神捣鬼", "t": "比喻瞎说"}, {"w": "瞎蒙", "t": "蒙骗;欺蒙。"}]}, {"meaning": "盲目地;胡乱地。", "cites": [{"t": "我的四奶奶,你可千万别瞎聊啊,你要我的脑袋搬家是怎的?", "b": "老舍《龙须沟》"}], "words": [{"w": "瞎头子", "t": "无头绪;没头没脑"}, {"w": "瞎来来", "t": "胡搅蛮缠"}, {"w": "瞎淘淘", "t": "瞎说;胡说。"}]}, {"meaning": "徒然;白白地。", "cites": [{"t": "孩子,你干吗要替人家瞎卖命呢?", "b": "田汉《江村小景》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3236wx','嘻','1','xī','口','15','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从口,喜声。本义:叹词。表示赞叹、悲叹或惊惧)。"}, {"meaning": "表示悲痛、或斥责。", "cites": [{"t": "譆,痛也。从言,喜声。字亦作嘻。", "b": "《说文》"}, {"t": "譆,善哉技。", "b": "《庄子·齐物论》。李注:“叹气也。”"}, {"t": "俯而应之曰譆。", "b": "《文选·七启》。注:“古譆嘻通。”"}, {"t": "夫子曰嘻、嘻。", "b": "《礼记·檀弓》。注:“发痛语首之声。”"}, {"t": "国氏曰嘻。", "b": "《列子·天瑞》。注:“哀痛之声。”"}, {"t": "古人以俭为美德,今人乃以俭相诟病,嘻,异哉!", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "嘻!谁要你的臭钱!", "t": ""}]}, {"meaning": "表示赞叹。", "cites": [{"t": "嘻,善哉! 技盖至此乎!", "b": "《庄子·养生主》"}, {"t": "嘻,技亦灵怪矣哉!", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "嘻!多坚强的人!嘻嗟", "t": "慨叹"}, {"w": "嘻叹", "t": "慨叹。"}]}, {"meaning": "笑,喜笑。", "cites": [{"t": "人嘻鬼嘻。", "b": "《太玄经·乐》"}], "words": [{"w": "嘻天哈地", "t": "形容大声嘻笑"}, {"w": "嘻笑怒骂", "t": "指嬉戏、欢笑、愤怒、詈骂等不同的情绪表现"}, {"w": "嘻嘻", "t": "欢笑的样子;喜悦的样子。"}]}, {"meaning": "强笑,苦笑。", "cites": [{"t": "因嘻笑曰。", "b": "《汉书·灌夫传》。注:“强笑也。”"}, {"t": "相视而嘻。", "b": "《史记·廉颇蔺相如列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3237wx','嘶','1','sī','口','15','','[{"pinyin": "sī", "defs": [{"meaning": "(形声。从口,斯声。本义:声音沙哑)。"}, {"meaning": "同本义。", "cites": [{"t": "莽为人,…露眼赤睛,大声而嘶。", "b": "《汉书·王莽传》"}], "words": [{"w": "嘶嚷", "t": "吵闹"}, {"w": "嘶嗄", "t": "沙哑"}, {"w": "嘶喝", "t": "声音沙哑无力"}, {"w": "嘶竭", "t": "沙哑得发不出声"}, {"w": "嘶丑", "t": "沙哑粗浊"}, {"w": "嘶涩", "t": "沙哑干涩"}, {"w": "声嘶力竭", "t": ""}]}, {"meaning": "虫鸟声凄切幽咽的。", "cites": [{"t": "独在中庭倚闲树,乱蝉嘶噪欲黄昏。", "b": "唐·元稹《哭子》"}], "words": [{"w": "嘶嗌", "t": "凄切幽咽"}, {"w": "嘶啭", "t": "凄凉宛转。"}]}, {"meaning": "牲畜鸣叫。亦特指马发出高而拖长的、典型的鸣叫声。", "cites": [{"t": "嘶,马鸣也。", "b": "《玉篇》"}, {"t": "其日牛马嘶,新妇入青庐。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "嘶风", "t": "马迎风嘶叫"}, {"w": "嘶号", "t": "马引声长鸣"}, {"w": "嘶战", "t": "嘶叫战栗"}, {"w": "嘶声", "t": "马鸣声"}, {"w": "嘶噪", "t": "鸣声喧杂"}, {"w": "人喊马嘶", "t": ""}]}, {"meaning": "发声凄楚哽噎。", "cites": [{"t": "嘶酸雏雁失群夜,断绝胡儿恋母声。", "b": "唐·李颀《听董大弹胡茄声兼语弄寄房给事》"}], "words": [{"w": "嘶酸", "t": "发声凄楚。"}]}, {"meaning": "歌吟。", "cites": [{"t": "去年西京寺,众伶集讲筵。能嘶《竹枝词》,供养绳床禅。", "b": "唐·孟郊《教坊歌儿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3238wx','嘲','1','cháo zhāo','口','15','','[{"pinyin": "cháo", "defs": [{"meaning": "(形声。从口,朝声。本义:嘲笑)。"}, {"meaning": "同本义。", "cites": [{"t": "以至于杂以嘲戏。", "b": "曹丕《典论·论文》"}], "words": [{"w": "冷嘲热讽;嘲问", "t": "带讽刺地问"}, {"w": "嘲戏", "t": "嘲弄嬉戏。"}]}, {"meaning": "唱,按音律发声。", "cites": [{"t": "因使元翌等嘲,以酒为韵。", "b": "《北史·薛孝通传》"}], "words": [{"w": "嘲歌", "t": "信口唱歌"}, {"w": "嘲风弄月", "t": "吟咏清风。"}]}]}, {"pinyin": "zhāo", "defs": [{"meaning": "勾引。", "cites": [{"t": "妇人在家,别无事干,一日三餐吃了饭,打扮光鲜,只在门前帘儿下站着,常把眉目嘲人,双睛传意。", "b": "《金瓶梅》"}], "words": [{"w": "嘲汉子的班头", "t": "勾引男子的能手"}, {"w": "嘲惹", "t": "挑逗;撩拨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3239wx','嘹','1','liáo','口','15','','[{"pinyin": "liáo", "defs": [{"meaning": "声音清脆悠扬", "words": [{"w": "嘹朗", "t": "嘹亮"}, {"w": "嘹唳", "t": "清脆的鸣声"}, {"w": "嘹乱", "t": "形容声音响亮而又嘈杂"}, {"w": "嘹嘈", "t": "笛声;声音响亮而喧闹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3240wx','影','1','yǐng','彡','15','','[{"pinyin": "yǐng", "defs": [{"meaning": "(形声。从彡,景声。彡(shān),毛饰花边形。本义:影子;因挡住光线而投射的暗影)。"}, {"meaning": "同本义。", "cites": [{"t": "影,形影。", "b": "《广韵》"}, {"t": "犹表之与影。", "b": "《吕氏春秋·功名》"}, {"t": "吾日悠悠惭于影。", "b": "《淮南子·修务》"}]}, {"meaning": "字本作“景”。", "cites": [{"t": "二子乘舟,汛汛其影。", "b": "《诗·邶风·二子乘舟》。疏:“景,指舟影。”"}, {"t": "罔两问于景。", "b": "《淮南子·道应》"}, {"t": "正日景以求地中。", "b": "《周礼·大司徒》。释文:“景,本或作影。”"}, {"t": "影布石上,佁然不动。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "影灯", "t": "点火取影的彩灯"}, {"w": "影不离灯", "t": "紧密地连在一起"}, {"w": "影形不离", "t": "形影不离。比喻关系密切"}, {"w": "影柱", "t": "古代测日影、定时刻的表柱。引申指法规、标准"}, {"w": "影表", "t": "即圭表。为古代测度日影的天文仪器"}, {"w": "影子花", "t": "影踪"}, {"w": "影兆", "t": "踪影"}, {"w": "影附", "t": "谓如影附形"}, {"w": "影神", "t": "迷信谓人影有神灵主之,故称"}, {"w": "影从", "t": "如影随形。形容迅速依附、追随"}, {"w": "影影", "t": "身影"}, {"w": "影踪", "t": "身影,踪迹"}, {"w": "湖光塔影;影娥池", "t": "汉代未央宫中池名。本凿以玩月,后以指清澈鉴月的水池。"}]}, {"meaning": "图绘的佛像或人物肖像。", "cites": [{"t": "三有佛影,焕若真容,相好具足,俨然如在。", "b": "唐·玄奘《大唐西域记》"}, {"t": "毁神影,坏屋舍。", "b": "《南史》"}, {"t": "写了武松乡贯年甲,貌相模样,画影图形,出三千贯信赏钱。", "b": "《水浒传》"}], "words": [{"w": "影身", "t": "画像"}, {"w": "影图", "t": "画像"}, {"w": "影殿", "t": "寺庙中供奉神佛的殿堂"}, {"w": "影室", "t": "影堂。寺庙道观供奉佛祖、尊师真影之处"}, {"w": "影神", "t": "指遗像;画像。"}]}, {"meaning": "假冒。", "cites": [{"t": "虽有富户,或投名于势要,以求影庇。", "b": "《旧五代史·唐庄宗纪》"}], "words": [{"w": "影射", "t": "假冒他人字号、招牌;以假充真"}, {"w": "影庇", "t": "将户籍或土地财产虚挂在权势人家名下,以逃避徭役税收"}, {"w": "影占", "t": "虚占人户或财产,使逃避赋役、税收。"}]}, {"meaning": "隐藏。", "cites": [{"t": "只见对面松林里影着一个人在那里舒头探脑价望。", "b": "《水浒传》"}], "words": [{"w": "影着", "t": "隐着;藏着"}, {"w": "影射", "t": "暗中耍手腕。"}]}, {"meaning": "照射。", "cites": [{"t": "朵朵祥光捧圣,影遍了世界。", "b": "《西游记》"}]}, {"meaning": "晃动。", "cites": [{"t": "先把拳头虚影一影,便转身,却先飞起左脚,踢中了。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3241wx','踢','1','tī','足','15','','[{"pinyin": "tī", "defs": [{"meaning": "用脚特别是足尖触击(打)。", "cites": [{"t": "踢,以足蹴物。", "b": "《正字通》"}]}, {"meaning": "这个“踢”是近代的新字。", "words": [{"w": "踢弄", "t": "百戏技艺中以手足为主的杂技"}, {"w": "踢箭", "t": "北方的游戏,即南方的踢毽子"}, {"w": "踢飞脚", "t": "两脚相继踢起,高与头齐"}, {"w": "踢天弄井", "t": "上天入地的捣乱"}, {"w": "踢斛淋尖", "t": "官吏溢收农民税粮的方法。"}]}, {"meaning": "剔除;排除 。", "words": [{"w": "踢脱", "t": "除籍。妓女从良"}, {"w": "踢荡", "t": "挥霍,糟蹋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3242wx','踏','1','tà tā','足','15','','[{"pinyin": "tà", "defs": [{"meaning": "(形声。从足,沓(tà)声。本义:足着地;踩 )。"}, {"meaning": "同本义。", "cites": [{"t": "踏,足著地也。", "b": "《玉篇》"}, {"t": "足踏使坚平。", "b": "《齐民要术·种葵》"}, {"t": "鸡子圆转不止,便下床以屐齿踏之。", "b": "《晋书·王述传》"}], "words": [{"w": "踏步不前;踏雪", "t": "在雪地上行走"}, {"w": "把火踏灭;踏踏", "t": "马蹄声,也作蹋蹋"}, {"w": "踏破菜园", "t": "吃素的人,破了荤戒"}, {"w": "踏蹑", "t": "织布时踩踏织机的踏板。"}]}, {"meaning": "边走边唱;打拍。", "cites": [{"t": "到明辛苦无处说,齐声腾踏牵船歌。", "b": "唐·王建《水夫谣》"}], "words": [{"w": "踏场", "t": "按照乐调节拍舞蹈"}, {"w": "踏臂", "t": "连臂而歌,踏地打节拍"}, {"w": "踏蹄", "t": "歌舞时以足踏地为节。"}]}, {"meaning": "吞咽。", "cites": [{"t": "县官踏飧去,簿吏复登堂。", "b": "唐·李贺《感讽五首》"}]}, {"meaning": "蹬。", "cites": [{"t": "娇儿恶卧踏里裂。", "b": "唐·杜甫《茅屋为秋风所破歌》"}]}, {"meaning": "鞋。", "cites": [{"t": "朔音悲嘒管,瑶踏动芳尘。", "b": "温庭筠《观舞妓》"}]}]}, {"pinyin": "tā", "defs": [{"meaning": "落下", "words": [{"w": "蹋顿", "t": "跌倒"}, {"w": "蹋衍", "t": "指斜平的下坡路"}]}, {"meaning": "下垂", "words": [{"w": "蹋翼", "t": "耷拉着翅膀。颓丧无所作为的样子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3243wx','踩','1','cǎi','足','15','','[{"pinyin": "cǎi", "defs": [{"meaning": "用脚登在上面，踏", "words": [{"w": "踩油门", "t": ""}, {"w": "踩水", "t": "一种直立水中的泳姿"}]}, {"meaning": "走,行走", "words": [{"w": "踩软索", "t": "走绳。演员在悬空的绳索上来回走动,并表演各种动作"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3244wx','踪','1','zōng','足','15','','[{"pinyin": "zōng", "defs": [{"meaning": "(形声。从足,从(宗)声。本义:脚印,踪迹)。"}, {"meaning": "同本义。", "cites": [{"t": "草合人踪断,尘浓鸟迹深。", "b": "李白《谒老君庙》"}, {"t": "千山鸟飞绝,万径人踪灭。", "b": "柳宗元《江雪》"}, {"t": "访其遗踪。", "b": "宋·苏轼《石钟山记》"}, {"t": "绝无踪响。", "b": "《聊斋志异·促织》"}, {"t": "胆寒潜踪。", "b": "《广东军务记》"}], "words": [{"w": "踪尘", "t": "尘世的事情"}, {"w": "踪绪", "t": "踪迹,头绪"}, {"w": "踪响", "t": "踪迹和声响"}, {"w": "踪辙", "t": "踪迹。"}]}, {"meaning": "事物的痕迹。", "cites": [{"t": "翠华一去寂无踪,玉楼歌吹,声断己随风。", "b": "《鹿虔扆·临江仙》"}], "words": [{"w": "踪由", "t": "事情的始末"}, {"w": "跟踪", "t": ""}]}, {"meaning": "追随。", "cites": [{"t": "朕欲远追周文,近踪光武,使宗庙有太山之安。", "b": "《晋书·刘曜载书》"}, {"t": "质菲薄而难踪,心恬愉而去惑。", "b": "《隋书》"}], "words": [{"w": "踪行", "t": "跟着走。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3245wx','蝶','1','dié','虫','15','','[{"pinyin": "dié", "defs": [{"meaning": "昆虫，翅膀阔大，颜色美丽，静止时四翅竖立在背部，吸花蜜，种类很多", "words": [{"w": "蝶子", "t": "蝴蝶"}, {"w": "蝶羽", "t": "蝶翅。指蝴蝶"}, {"w": "蝶翎", "t": "蝶翅"}, {"w": "蝶裙", "t": "绣有簇蝶的裙"}, {"w": "蝶魂", "t": "蝶魄。比喻梦中超脱飘逸的心境"}, {"w": "蝶影", "t": "蝴蝶的身影"}, {"w": "蝶戏", "t": "谓蝴蝶飞舞嬉戏"}, {"w": "蝶意莺情", "t": "比喻爱恋春色的情意"}, {"w": "蝶舞", "t": "比喻荡子之流嫖妓。"}, {"w": "蝶泳", "t": "游泳的一种姿势，亦是游泳项目之一，形似蝶飞"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3246wx','蝴','1','hú','虫','15','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从虫,胡声。本义:蝴蝶:虫名。种类很多)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3247wx','蝠','1','fú','虫','15','','[{"pinyin": "fú", "defs": [{"meaning": "蝙蝠。", "cites": [{"t": "蝙蝠,服翼也。从虫,畐声。", "b": "《说文》"}, {"t": "蝙蝠伏匿,故夜食。", "b": "《孝经·援神契》。按,形绝类鼠,肉翅与足相连,夜捉蚊蚋食之,俗言老鼠所化也。"}, {"t": "燕避戊巳,蝠伏庚申。", "b": "《续博物志》"}]}, {"meaning": "泛指所有属于翼手目的许多种哺乳动物,尤指哺乳类中唯一真正能飞的动物。"}, {"meaning": "(fù)。毒蛇,通称蝮蛇,多居湿地。", "cites": [{"t": "蝠蛇其心,纵毒不辜。", "b": "《后汉书·崔琦传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3248wx','蝎','1','xiē','虫','15','','[{"pinyin": "xiē", "defs": [{"meaning": "毒虫名。也称“钳蝎”。节肢动物门,蜘蛛纲,蜘蛛亚纲,蝎目。", "cites": [{"t": "蝎,蝤蛴也。从虫,曷声。", "b": "《说文》"}, {"t": "虽蝎焉避之。", "b": "《国语·晋语》"}, {"t": "虽蝎谮之。", "b": "《国语·鲁语》"}], "words": [{"w": "蝎梢", "t": "蝎子的尾巴"}, {"w": "蝎蝎螫螫", "t": "比喻在小事情上过分关心或怜惜"}, {"w": "蝎子", "t": "钳蝎;钳蝎之子"}, {"w": "蝎唇", "t": "状如蝎子嘴的酒器"}, {"w": "蝎子妈", "t": "方言。比喻最恶毒、惹不得的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3249wx','蝌','1','kē','虫','15','','[{"pinyin": "kē", "defs": [{"meaning": "蛙或蟾蜍的幼体，黑色，身体椭圆，有长尾，生活在水中，最后变成蛙或蟾蜍。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3250wx','蝗','1','huáng','虫','15','','[{"pinyin": "huáng", "defs": [{"meaning": "蝗虫 。种类很多。一般指飞蝗,常成群飞翔。又名蚂蚱。吃麦、稻、玉蜀黍等禾苗,是农业上的主要害虫之一。", "cites": [{"t": "蝗,螽也。从虫,皇声。", "b": "说文》"}, {"t": "蝗螟农夫得而杀之。", "b": "《吕氏春秋》"}], "words": [{"w": "蝗螟", "t": "蝗与螟。庄稼的两种害虫"}, {"w": "蝗螽", "t": "即蝗虫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3251wx','蝙','1','biān','虫','15','','[{"pinyin": "biān", "defs": [{"meaning": "具有飞翔能力的哺乳动物。头部和躯干像老鼠，四肢和尾部之间有皮质的膜，夜间在空中飞翔，视力很弱，靠本身发出的超声定位来引导飞行。"}, {"meaning": "一种袖口小、腋下部位特大的上衣。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3252wx','嘿','1','hēi mò','口','15','','[{"pinyin": "hēi", "defs": [{"meaning": "(形声。从口,黑声。本义:叹词,表示招呼、赞叹或惊异) 同本义。"}, {"meaning": "用于歌曲中,常叠用,无明确的意义。"}, {"meaning": "咳嗽。", "cites": [{"t": "嘿,咳也。", "b": "《集韵》"}]}]}, {"pinyin": "mò", "defs": [{"meaning": "", "words": [{"w": "嘿然不言", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3253wx','嘱','1','zhǔ','口','15','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(形声。从口,属声。本义:嘱托,叮嘱)。"}, {"meaning": "同本义。", "cites": [{"t": "去时嘱我。", "b": "晋·干宝《搜神记》"}, {"t": "嘱学使俾入邑庠。(嘱咐考试官让成名进县学学习。学使,提督学政即学台,是专管教育和考试的官。俾,使。邑庠,县学,庠,学校。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "嘱板", "t": "嘱其牵扳。"}]}, {"meaning": "嘱托。", "cites": [{"t": "一生不爱嘱人事,嘱即直须为生死。", "b": "唐·孟郊《伤时》"}], "words": [{"w": "嘱致", "t": "嘱托致意"}, {"w": "嘱寄", "t": "嘱托寄命"}, {"w": "嘱请", "t": "嘱托请求。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3254wx','幢','1','chuáng zhuàng','巾','15','','[{"pinyin": "chuáng", "defs": [{"meaning": "(形声。从巾,童声。本义:古时作为仪仗用的一种旗帜)。"}, {"meaning": "量词。俗称房屋或楼房一所为一幢。"}]}, {"pinyin": "zhuàng", "defs": [{"meaning": "张挂在舟、车上的帷幔。", "cites": [{"t": "抚鸿幢,御矰缴,方舟并驾,俛仰极乐。", "b": "《后汉书》"}]}, {"meaning": "愚昧无知。", "cites": [{"t": "是故君先立于仁,则大夫忠而士信,民敦,工璞,商悫,女憧,妇空空。七者,教之志也。", "b": "《大戴礼记》"}], "words": [{"w": "幢愚", "t": "愚昧"}, {"w": "憧憧", "t": "憨愚无知的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3255wx','墨','1','mò','土','15','','[{"pinyin": "mò", "defs": [{"meaning": "(会意兼形声。从土,从黑,黑亦声。本义:书画所用的黑色颜料,用松烟等原料制成)。"}, {"meaning": "同本义。", "cites": [{"t": "墨,书墨也。", "b": "《说文》"}, {"t": "舐笔和墨。", "b": "《庄子·田子方》"}, {"t": "史占墨。", "b": "《周礼·占人》"}, {"t": "致其墨。", "b": "《周礼·卜师》。注:“熟灼之,明其兆。”"}], "words": [{"w": "墨丸", "t": "古墨的一种"}, {"w": "墨本", "t": "碑帖的拓本"}, {"w": "墨工", "t": "制墨的工匠"}, {"w": "墨妆", "t": "脸部以墨化妆"}, {"w": "墨路", "t": "墨线。"}]}, {"meaning": "指诗文或书画。", "cites": [{"t": "墨客降席,再拜稽首。", "b": "扬雄《长杨赋》"}], "words": [{"w": "墨君竹", "t": "墨绘之竹"}, {"w": "文墨;遗墨;墨兵", "t": "指史书;指书画诗文"}, {"w": "墨妙", "t": "精妙的文章、书法和绘画"}, {"w": "墨帖", "t": "法帖。指名家法书的拓本或印本。"}]}, {"meaning": "绳墨。木工用以校正曲直的墨斗线。", "cites": [{"t": "墨丈寻常之间。", "b": "《国语·周语》"}, {"t": "物仰其墨。", "b": "《太玄·法》。注:“谓绳墨也。”"}], "words": [{"w": "墨斗", "t": "木工画直线的工具"}, {"w": "墨路", "t": "墨线。木工画在木料上用以校正曲直的线。"}]}, {"meaning": "中国古代五刑之一。刺刻面额,染以黑色,作为惩罚的标记。商周叫“墨刑”,秦汉叫“黥刑”。", "cites": [{"t": "墨者,墨其额也。", "b": "《白虎通·五刑》"}, {"t": "墨罪五百。", "b": "《周礼·司刑》。注:“黥也。先刻其面,以墨窒之。”"}]}, {"meaning": "绳索。", "cites": [{"t": "徽以纠墨。", "b": "扬雄《解嘲》"}]}, {"meaning": "黑色。", "cites": [{"t": "墨,黑也。", "b": "《广雅·释器》"}, {"t": "面深墨。", "b": "《孟子·滕文公上》"}, {"t": "臣观吴王之色类有大忧。", "b": "《国语·吴语》。注:“传曰:‘肉食者无墨。’今吴王有墨。墨,黑气也。”"}, {"t": "其色墨。", "b": "明·魏学洢《核舟记》"}, {"t": "俄倾风定云墨色。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "墨以葬文公。", "b": "《左传·僖公三十二年》"}, {"t": "于是始墨。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "墨绖", "t": "黑色的丧服"}, {"w": "墨面", "t": "形容面容黑瘦"}, {"w": "墨玉", "t": "黑色玉石"}, {"w": "墨衣", "t": "黑衣,指丧服"}, {"w": "墨灰", "t": "黑灰色。"}]}, {"meaning": "贪污,不廉洁。", "cites": [{"t": "贪以败官为墨。", "b": "《左传·昭公十四年》"}, {"t": "墨者多自免去。", "b": "清·张廷玉等《明史》"}], "words": [{"w": "墨臣", "t": "贪赃不法的臣子"}, {"w": "墨吏", "t": "贪官污吏。"}]}, {"meaning": "不语。", "cites": [{"t": "故口可劫而使墨云。", "b": "《荀子·解蔽》"}, {"t": "孔静幽墨,冤结纡轸兮。", "b": "《史记·屈原贾生列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3256wx','镇','1','zhèn','钅','15','','[{"pinyin": "zhèn", "defs": [{"meaning": "(形声。从金,真声。本义:对物体施加压力)。"}, {"meaning": "同本义。", "cites": [{"t": "镇,博压也。", "b": "《说文》"}, {"t": "王执镇圭。", "b": "《周礼·大宗伯》"}, {"t": "镇圭尺有二寸,天子守之。", "b": "《考工记·玉人》"}, {"t": "而镇其浮。", "b": "《国语·楚语》"}, {"t": "系方绝,又重镇之。", "b": "枚乘《上书谏吴王》"}, {"t": "为资币、瑞节以镇之。", "b": "《国语》。"}], "words": [{"w": "镇在五台山下;镇笮", "t": "压住"}, {"w": "镇迮", "t": "压榨"}, {"w": "镇石", "t": "压物的石块"}, {"w": "镇犀", "t": "用犀牛角制的用具"}, {"w": "镇帷犀", "t": "挂在帷帐四角防止牵动的犀角。"}]}, {"meaning": "镇服。", "cites": [{"t": "子以君命镇抚敝邑。", "b": "《国语·鲁语》"}, {"t": "因请立张耳为赵王,以镇抚其国。", "b": "《史记》"}, {"t": "夫内诚不解,形谍成光,以外镇人心。", "b": "《庄子·列御寇》。"}], "words": [{"w": "镇魇法", "t": "害人的法术"}, {"w": "镇宅", "t": "迷信者用某种法术符咒压邪,保家宅平安"}, {"w": "镇唬", "t": "威吓"}, {"w": "镇遏", "t": "镇压遏阻。"}]}, {"meaning": "压制,用武力限制 。", "cites": [{"t": "治讼若此为务,助豪猾而镇贫弱也。", "b": "《潜夫论》"}], "words": [{"w": "镇绥", "t": "镇压平定"}, {"w": "镇讨", "t": "镇压讨伐。"}]}, {"meaning": "抑制。", "cites": [{"t": "愿摇起而横奔兮,览民尤以自镇。", "b": "《楚辞·九章·抽思》。"}], "words": [{"w": "镇浮", "t": "抑制轻浮"}, {"w": "镇止", "t": "抑止"}, {"w": "镇神头势", "t": "即镇神头。下围棋的一种战术。乙方投三六路攻四四路时,甲方用五六路抑制它。"}]}, {"meaning": "安定;安抚。", "cites": [{"t": "镇,安也。", "b": "《广雅》"}, {"t": "镇定大事。", "b": "《国语·晋语》"}, {"t": "镇国家,抚百姓。", "b": "《史记》。"}], "words": [{"w": "镇心", "t": "静心,安定心神"}, {"w": "镇安", "t": "安定,镇定"}, {"w": "镇宁", "t": "安定"}, {"w": "镇靖", "t": "安定,安抚"}, {"w": "镇国", "t": "使国家安定。"}]}, {"meaning": "镇守,驻守。", "cites": [{"t": "留五百人镇之。", "b": "《资治通鉴·唐纪》。"}], "words": [{"w": "镇脊", "t": "镇守屋脊,以驱邪魔"}, {"w": "镇边关;镇辑", "t": "镇守安抚。"}]}, {"meaning": "压东西的重物。", "cites": [{"t": "白玉兮为镇,疏石兰兮为芳。", "b": "《楚辞·九歌·湘夫人》"}]}, {"meaning": "古代在边境驻兵戍守称为镇。镇将管理军务,有的也兼理民政。宋初废。", "cites": [{"t": "唐初,兵之戍边者,大曰军,小曰守捉,曰城,曰镇,而总之者曰道。", "b": "《新唐书·兵志》。"}], "words": [{"w": "镇军", "t": "古代将军名号;清代总兵的俗称"}, {"w": "镇城", "t": "负责城防的军事长官"}, {"w": "镇台", "t": "清代总兵。"}]}, {"meaning": "集镇,市镇 。宋以后称县以下的小商业都市,现多为基层行政单位。", "cites": [{"t": "民聚不成县而有税课者,则为镇或以官监之。", "b": "宋·高承《事物纪原》。"}], "words": [{"w": "村镇", "t": "村庄和小市镇"}, {"w": "镇集", "t": "镇市。都指集镇"}, {"w": "镇店", "t": "方言。集镇。"}]}, {"meaning": "古称一方的主山为镇。", "cites": [{"t": "四镇五岳。", "b": "《周礼·大司乐》"}]}, {"meaning": "重要或险要的地方。", "cites": [{"t": "白帝高为三峡镇,瞿唐险过百牢关。", "b": "杜甫诗"}]}, {"meaning": "明、清时军队的编制单位。清末编练新军,也称为镇 。一镇统步队两协,马炮队各一标,二辎队各一营,以及军乐队等。"}, {"meaning": "根本;基础。", "cites": [{"t": "然则士民者,乃国家之镇也;谷帛者,乃士民之命也。", "b": "魏·高堂隆《切谏增崇宫室疏》"}]}, {"meaning": "常;永久。", "cites": [{"t": "莫言春稍晚,自有镇开花。", "b": "唐·褚亮《咏花烛》。"}], "words": [{"w": "镇长", "t": "经常;常"}, {"w": "镇常", "t": "经常"}, {"w": "镇驻", "t": "长存。"}]}, {"meaning": "整,全。", "cites": [{"t": "青塚镇野,黑山驾空。", "b": "宋·王元之《北狄来朝颂》。"}], "words": [{"w": "镇日镇夜", "t": "整日整夜,日日夜夜"}, {"w": "镇日", "t": "整天"}, {"w": "镇日价", "t": "整天。价,助词。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3257wx','镐','1','gǎo hào','钅','15','','[{"pinyin": "gǎo", "defs": [{"meaning": "镐头 。俗称“十字镐”。"}]}, {"pinyin": "hào", "defs": [{"meaning": "(形声。从金,高声。本义:温器)。"}, {"meaning": "同本义。", "cites": [{"t": "镐,温器也。", "b": "《说文》"}]}, {"meaning": "镐京。古都名。西周国都,在今陕西西安西南。", "cites": [{"t": "王在在镐。", "b": "《诗·小雅·鱼藻》"}], "words": [{"w": "镐洛", "t": "镐京与洛阳的并称。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3258wx','镑','1','bàng','钅','15','','[{"pinyin": "bàng", "defs": [{"meaning": "形声。从金,旁声。英国、埃及、爱尔兰等的本位货币，一镑合 100 便士。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3259wx','靠','1','kào','非','15','','[{"pinyin": "kào", "defs": [{"meaning": "(形声。从非,告声。从“非”,表示相违背。本义:相背)。"}, {"meaning": "相依。", "cites": [{"t": "靠,相违也。", "b": "《说文》。段玉裁注:“今俗谓相依曰靠,古人谓相背曰靠。”"}]}, {"meaning": "仰仗,依赖。", "cites": [{"t": "不可只靠一言半句,海上单方,便以为足。", "b": "宋·朱熹《答吴伯起书》"}], "words": [{"w": "靠傍", "t": "依靠,靠山"}, {"w": "靠托", "t": "倚仗;依靠"}, {"w": "靠天", "t": "不靠人力,依赖天命。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3260wx','稽','1','jī qǐ','禾','15','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从禾(jī),象树木曲头止住不上长的样子,从尤,旨声。本义:停留;阻滞)。"}, {"meaning": "同本义。引申为囤积。", "cites": [{"t": "稽,留止也。", "b": "《说文》"}, {"t": "司稽,察留连不时去者。", "b": "《周礼·司稽》注"}, {"t": "秦之水泔最而稽。", "b": "《管子·水地》"}, {"t": "令出而不稽。", "b": "《管子·君臣上》"}, {"t": "稽市物。", "b": "《汉书·食货志》。注:“贮滞也。”"}], "words": [{"w": "稽欠", "t": "滞留拖欠"}, {"w": "稽身", "t": "拖住身子"}, {"w": "稽留", "t": "在外久留"}, {"w": "稽诣", "t": "停顿"}, {"w": "稽固", "t": "稽留停滞。"}]}, {"meaning": "延迟。", "cites": [{"t": "明晨炊米尽,吾起不容稽。", "b": "陆游《冬夜不寐》"}, {"t": "稽废时月。", "b": "《后汉书·列女传》"}], "words": [{"w": "稽迟", "t": "延误推迟"}, {"w": "稽延", "t": "迟延。"}]}, {"meaning": "考核;核查。", "cites": [{"t": "稽其功绪。", "b": "《周礼·宫正》。注:“犹考也。”"}, {"t": "稽其成败兴坏之理。", "b": "《汉书·司马迁传》"}], "words": [{"w": "稽度", "t": "考核衡量"}, {"w": "稽古", "t": "考察研习古代的事理"}, {"w": "稽备", "t": "查核完备。"}]}, {"meaning": "计算。", "cites": [{"t": "简稽乡民。", "b": "《周礼·大司马》。注:“犹计也。”"}], "words": [{"w": "稽算", "t": "核计;核算"}, {"w": "稽盘", "t": "稽查盘算。"}]}, {"meaning": "治理。", "cites": [{"t": "若稽田,既勤敷菑。", "b": "《书·梓材》。蔡沈集传:“稽,治也。”"}]}, {"meaning": "至;到。", "cites": [{"t": "再拜稽首。", "b": "《礼记·射义》"}], "words": [{"w": "稽颡", "t": "旧时父母死,行丧礼时跪拜宾客,以额触地的礼节。颡:额头"}, {"w": "稽天", "t": "至于天际。形容势大。"}]}, {"meaning": "卜问。", "cites": [{"t": "七稽疑。", "b": "《书·洪范》"}], "words": [{"w": "稽疑", "t": "用卜筮决断疑事"}, {"w": "稽问", "t": "卜问。"}]}, {"meaning": "指摘;非难。", "cites": [{"t": "妇姑不相说(悦),则反唇而相稽。", "b": "《汉书》"}]}]}, {"pinyin": "qǐ", "defs": [{"meaning": "叩头至地。", "cites": [{"t": "至地曰稽颡,下衡曰稽首。", "b": "《荀子·大略》"}, {"t": "再拜稽首。", "b": "《礼记·射义》"}, {"t": "吊者致命,主人哭拜,稽颡成踊。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "稽拜", "t": "叩拜"}, {"w": "稽颡", "t": "古代一种跪拜礼,屈膝下拜,以额触地,表示极度的虔诚"}, {"w": "稽颡膜拜", "t": "古代行稽颡礼后,又举手加额,长跪而拜,表示极度恭敬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3261wx','稻','1','dào','禾','15','','[{"pinyin": "dào", "defs": [{"meaning": "(形声。从禾,舀(yǎo)声。本义:水稻) 同本义。", "cites": [{"t": "其谷宜稻。", "b": "《周礼·职方氏》"}, {"t": "浸彼稻田。", "b": "《诗·小雅·白华》"}]}, {"meaning": "一种一年生的草本植物,在温暖气候下广泛栽培,种子用作人类主食,谷壳和其它副产品可饲养家畜,稻秆用来造纸。分水稻和旱稻,通常指水稻。子实叫谷子,碾制去壳后叫大米。有糯稻、粳稻、籼稻之分。古以粘者为稻,不粘者为粳。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3262wx','黎','1','lí','黍','15','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从黍,利省声。本义:黍胶。以黍米制成。古代用以粘履)。"}, {"meaning": "假借为“齐”。众多,数目很多。", "cites": [{"t": "民靡有黎,具祸以烬。", "b": "《诗·大雅·桑柔》"}, {"t": "黎,众也。", "b": "《尔雅》"}, {"t": "黎民于变时雍。", "b": "《书·尧典》。传:“众也。”"}, {"t": "以能保我子孙黎民。", "b": "《礼记·大学》。注:“众也。”"}, {"t": "觉悟黎烝。", "b": "《汉书·司马相如传》。注:“黎烝,众庶也。”"}, {"t": "黎民不饥不寒。", "b": "《孟子·梁惠王上》。又如:黎庶(民众;百姓);黎氓(黎民,人民);黎甿(黎民,人民);黎首(黎民·黔首)"}]}, {"meaning": "颜色黑中带黄。", "cites": [{"t": "土青曰黎。似黎草色也。则谓借为藜。", "b": "《释名》"}, {"t": "今王播弃黎老。", "b": "《国语·吴语》。注:“东棃寿征也。”"}, {"t": "厥土青黎。", "b": "《书·禹贡》"}, {"t": "面目黎黑。", "b": "司马迁《史记》"}]}, {"meaning": "老,年纪大", "cites": [{"t": "黎,老也。", "b": "《方言十二》"}], "words": [{"w": "黎老", "t": "老人。"}]}, {"meaning": "粘 。古时用黍米打糨子,用来粘鞋子。", "cites": [{"t": "古人作履,粘以黍米,谓之黎。", "b": "宋·罗愿《尔雅翼》"}]}, {"meaning": "比及,等到。", "cites": [{"t": "黎明,围宛城三匝。", "b": "《史记·高祖本纪》"}]}, {"meaning": "古诸侯国名 ,在今山西黎城,一说在今长治西南。", "cites": [{"t": "黎侯寓于卫。", "b": "《诗·邶风·式微》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3263wx','稿','1','gǎo','禾','15','','[{"pinyin": "gǎo", "defs": [{"meaning": "(形声。从禾,高声。本义:禾秆)。"}, {"meaning": "禾秆,谷类植物的茎杆。也作“稾”。", "cites": [{"t": "稾,秆也。", "b": "《说文》"}, {"t": "民惊走持稾。", "b": "《汉书·五行志》"}, {"t": "又出稾税。", "b": "《书·禹贡传》"}, {"t": "茭稾。", "b": "《汉书·赵安国传》"}, {"t": "今又盛寒,马无稿草。", "b": "《资治通鉴》"}, {"t": "愿令民得入田,毋收稾稾为禽兽食。", "b": "《史记·萧相国世家》"}, {"t": "(皋涂之山)有草焉,其状如稾茇,其叶如葵而赤黄,名曰无条,可以毒鼠。", "b": "《山海经·西山经》"}], "words": [{"w": "稿本", "t": "香草名。一年生,根可入药"}, {"w": "稿茇", "t": "香草名。即稾本"}, {"w": "稿稾", "t": "指点燃后供照明用的草、麻"}, {"w": "稿荐", "t": "用稻草编成的垫褥"}, {"w": "稿苗", "t": "枯槁的禾苗"}, {"w": "稿人", "t": "稻草人。"}]}, {"meaning": "诗文、图画等草底。亦指写成的文章、著作。", "cites": [{"t": "怀王使屈原造为宪令,屈原属草稿未定,上官大夫见而欲夺之,屈原不与。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "文稿", "t": "文章、公文的草稿"}, {"w": "稿副", "t": "底稿"}, {"w": "稿案", "t": "公文案牍;亦作“文案师爷”。为主官管理文秘事务的慕僚"}, {"w": "稿书", "t": "草稿、初稿。"}]}, {"meaning": "箭杆。", "cites": [{"t": "特箭稾而茎立兮,独聆风于极危。", "b": "汉·马融《长笛赋》"}], "words": [{"w": "稿草", "t": "草稿。初写出的文稿"}, {"w": "稿定", "t": "撰定文稿。"}]}, {"meaning": "干枯。", "cites": [{"t": "弃其本者,荣其稿矣。", "b": "《说苑·建本》"}], "words": [{"w": "稿芼", "t": "枯干的草茎。"}]}, {"meaning": "样子;模样。", "cites": [{"t": "我看见哥儿的这个形容身段,言谈举动,怎么就和当儿国公爷一个稿子。", "b": "《红楼梦》"}]}, {"meaning": "叙说;论辈分。用同“搞”。", "cites": [{"t": "该咱老爷儿们稿一稿咧!我且问你:你们认得不认得?", "b": "清·文康《儿女英雄传》"}]}, {"meaning": "(kào)。以酒肉等饮食慰劳。", "cites": [{"t": "稿人奄八人,女稿每奄二人。", "b": "《周礼·地官·叙官》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3264wx','稼','1','jià','禾','16','','[{"pinyin": "jià", "defs": [{"meaning": "(形声。从禾,家声。本义:种植五谷)。"}, {"meaning": "同本义。", "cites": [{"t": "不稼不穑。", "b": "《诗·魏风·伐檀》"}, {"t": "巫载民不稼不穑食也。", "b": "《山海经·大荒南经》"}, {"t": "宜稼于田。", "b": "《仪礼·少牢礼》"}, {"t": "后稷教民稼穑,树艺五谷。", "b": "《孟子·滕文公上》"}], "words": [{"w": "稼桑", "t": "栽种桑树的一种方法。即斩下桑的枝叶而加以种植"}, {"w": "稼事", "t": "农田耕种的事物"}, {"w": "稼政", "t": "修封疆、开沟洫、教民种植五谷等事"}, {"w": "稼器", "t": "农具。"}]}, {"meaning": "从事农业生产。", "cites": [{"t": "好稼者众矣。", "b": "《荀子·解蔽》"}]}, {"meaning": "禾所结的果实。", "cites": [{"t": "稼,禾之秀实为稼,茎节为禾。", "b": "《说文》。朱骏声曰:“在野曰稼。”"}, {"t": "九月筑城圃,十月纳禾稼。", "b": "《诗·豳风·七月》"}, {"t": "简稼器。", "b": "《周礼·遂大夫》"}]}, {"meaning": "谷物;庄稼。", "cites": [{"t": "稼生于野,而藏于仓。", "b": "《吕氏春秋》"}, {"t": "主人东皋上,时稼绕茅屋。", "b": "唐·王维《宿郑州》"}, {"t": "伤稼乎。", "b": "唐·李朝威《柳毅传》"}, {"t": "一亩之稼。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "共说今年秋稼好,碧湖红稻鲤鱼肥。", "b": "清·郑燮《喜雨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3265wx','箱','1','xiāng','竹','15','','[{"pinyin": "xiāng", "defs": [{"meaning": "(形声。从竹,相声。本义:车箱)。"}, {"meaning": "同本义。", "cites": [{"t": "箱,大车牝服也。", "b": "《说文》"}, {"t": "不以服箱。", "b": "《诗·小雅·大东》。传:“箱,大车之箱也。”"}, {"t": "乃求万斯箱。", "b": "《诗·小雅·甫田》"}, {"t": "絷騕裹以服箱。", "b": "张衡《思玄赋》。注:“箱,大车也。”"}, {"t": "尔乃乘露箱,御良马。", "b": "晋·夏侯湛《猎兔赋》"}]}, {"meaning": "厢房,古代居室前堂两旁的房屋,也称“个”或“序”", "cites": [{"t": "篬,序也。", "b": "《埤苍》"}, {"t": "公揖,退于箱。", "b": "《仪礼·公食礼》。注:“东夹之前俟事之处。”"}, {"t": "俟几俟于东箱。", "b": "《仪礼·觐礼》。注:“东夹之前相翔待事之处。”"}, {"t": "西箱踟蹰。", "b": "王逸《鲁灵光殿赋》。注:“西序也。”"}]}, {"meaning": "旁", "cites": [{"t": "两箱悬崖数万仞,窥不见底。", "b": "《水经注》"}]}, {"meaning": "靠近城的地区", "cites": [{"t": "而城箱内外,义民不下四万,实不忍委之于贼,惟有竭力固守待援。", "b": "清·魏源《圣武记》"}]}, {"meaning": "箱”字汉以前无箧笥之称。盛物的箱笼,有盖有底的方形盛物器。", "cites": [{"t": "箱帘六七十。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "开箱睹黑裘。", "b": "杜甫《村雨》"}, {"t": "十指不动衣盈箱。", "b": "王建《当窗织》"}], "words": [{"w": "箱钱", "t": "嫖妓的花费"}, {"w": "箱匣", "t": "盛物的器具"}, {"w": "箱箧", "t": "方形与矩形的盛物竹器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3266wx','篓','1','lǒu','竹','15','','[{"pinyin": "lǒu", "defs": [{"meaning": "(形声。从竹,娄声。本义:篾篓) 同本义。盛东西的器具,用竹或荆条等编成。", "cites": [{"t": "篾篓挑将水边货。", "b": "唐彦谦《蟹》"}], "words": [{"w": "字纸篓", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3267wx','箭','1','jiàn','竹','15','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从竹,前声。本义:竹名。箭竹)。"}, {"meaning": "同本义。", "cites": [{"t": "箭,矢竹也。", "b": "《说文》"}, {"t": "其利金锡竹箭。", "b": "《周礼·职方氏》"}, {"t": "东南之美者,有会稽之竹箭焉。—《尔雅·释地》", "b": ""}, {"t": "如竹箭之有筠也。", "b": "《礼记·礼器》"}, {"t": "箭筹八十。", "b": "《仪礼·乡射礼记》"}], "words": [{"w": "箭笋", "t": "箭竹嫩笋"}, {"w": "箭茁", "t": "笋芽"}, {"w": "箭萌", "t": "小笋"}, {"w": "箭筠子竹", "t": "一种竹棍子"}, {"w": "箭笄", "t": "竹制的簪子。"}]}, {"meaning": "搭在弓弩上发射的竹制武器。", "cites": [{"t": "自关而东谓之矢,关西曰箭。", "b": "《方言九》"}, {"t": "吾奈无箭何?", "b": "《韩非子·十过》"}, {"t": "急湍甚箭。", "b": "吴均《与朱元思书》"}, {"t": "行人弓箭各在腰。", "b": "唐·杜甫《兵车行》"}, {"t": "船往如箭。", "b": "《资治通鉴》"}], "words": [{"w": "箭羽", "t": "箭上的羽毛"}, {"w": "箭衣", "t": "古代弓箭手穿的衣服。后来成为一种长礼服"}, {"w": "箭壶", "t": "盛箭的囊袋"}, {"w": "箭袖", "t": "又名马蹄袖。一种便于射箭的袖口,上面较长可以盖住手,下面较短。"}]}, {"meaning": "古代置计时器漏壶下用以指示时刻之物。", "cites": [{"t": "寒更传晓箭,清镜览衰颜。", "b": "王维《冬晚对雪忆胡处士家》"}], "words": [{"w": "箭水", "t": "漏壶的水"}, {"w": "箭刻", "t": "箭漏的刻度"}, {"w": "箭漏", "t": "古代计时器。漏壶"}, {"w": "箭滴", "t": "漏箭随水浮沉,不断移动。滴:漏壶滴水。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3268wx','篇','1','piān','竹','15','','[{"pinyin": "piān", "defs": [{"meaning": "(形声。从竹,扁声。本义:竹简)。"}, {"meaning": "同本义;简册。古代文章写在竹简上,为保持前后完整,用绳子或皮条编集在一起称为“篇”。", "cites": [{"t": "篇,书也。…谓书于简册可编者也。", "b": "《说文》"}, {"t": "著文为篇。", "b": "《论衡·书说》"}, {"t": "著之于篇。", "b": "《汉书·公孙宏传》"}, {"t": "故事绝于常篇。", "b": "《游天台山赋》"}], "words": [{"w": "篇翰", "t": "篇章;篇简"}, {"w": "篇卷", "t": "指书籍"}, {"w": "篇册", "t": "犹书籍"}, {"w": "篇典", "t": "典籍"}, {"w": "篇秩", "t": "书籍的篇卷"}, {"w": "篇次", "t": "谓书籍中篇章的顺序。"}]}, {"meaning": "特指诗歌、辞赋等文艺著作。", "cites": [{"t": "管仲相齐,造《轻重》之篇。", "b": "《论衡·案书》"}, {"t": "一篇之中三致志焉。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "篇咏", "t": "诗歌著作"}, {"w": "篇翰", "t": "一般指诗文"}, {"w": "篇句", "t": "犹章句"}, {"w": "篇技", "t": "谓创作诗文的才能。"}]}, {"meaning": "曲艺名词。东北二人转所用,指各类内容的固定唱词,可随机穿插入段子中,用以状人、绘景、描声、形物 。如“美人篇”、“袍带篇”、“山景篇”等。"}, {"meaning": "一件文艺作品。", "cites": [{"t": "著《论衡》八十五篇,二十余万言。", "b": "《后汉书·王充传》"}, {"t": "《山海经》十三篇,《国朝》七卷。", "b": "《汉书·艺文志》"}, {"t": "世无一卷,吾有百篇。", "b": "《论衡·自纪》"}], "words": [{"w": "一篇文章;几篇恐怖故事", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3269wx','僵','1','jiāng','亻','15','','[{"pinyin": "jiāng", "defs": [{"meaning": "(形声。从人,畺(jiāng)声。本义:仰面向后倒下)。"}, {"meaning": "同本义。", "cites": [{"t": "僵,偾也。", "b": "《说文》"}, {"t": "鲍叔御公子小白僵。", "b": "《吕氏春秋·贵卒》。注:“偃也。”"}, {"t": "佯僵而弃酒。", "b": "《史记·苏秦传》。注:“仆也。”"}, {"t": "即诈僵仆阳病。", "b": "《汉书·梁平王襄传》"}, {"t": "僵仆烦愦。", "b": "唐·柳宗元《柳河东集》"}, {"t": "偃仰僵仆。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "僵死", "t": "倒地死去;倒地死去的人"}, {"w": "僵伏", "t": "倒地而死"}, {"w": "僵毙", "t": "倒下死亡。"}]}, {"meaning": "死去。", "cites": [{"t": "伶悝僵。", "b": "《吕氏春秋·贵卒》。注:“毙也。”"}], "words": [{"w": "僵仆", "t": "死去"}, {"w": "僵坠", "t": "死亡坠下"}, {"w": "僵槁", "t": "枯死"}, {"w": "僵落", "t": "枯死后落下"}, {"w": "僵踞", "t": "坐着僵死。"}]}, {"meaning": "僵硬。难以活动。", "cites": [{"t": "癫疾始作,先反僵。", "b": "《灵枢经·癫狂》"}, {"t": "岁寒虫僵。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "僵立", "t": "直立不动"}, {"w": "僵冷", "t": "僵硬冰冷"}, {"w": "僵燥", "t": "失去水分而硬化。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3270wx','躺','1','tǎng','身','15','','[{"pinyin": "tǎng", "defs": [{"meaning": "(形声。从身,尚声。本义:平卧)。"}, {"meaning": "同本义。", "cites": [{"t": "这无耻的畜生想必是躺尸了。", "b": "清·忧患余生《邻女语》"}], "words": [{"w": "躺在床上;躺着歇歇;躺尸", "t": "詈词。指睡觉"}, {"w": "躺桥", "t": "方言。睡觉。"}]}, {"meaning": "死的婉辞。", "cites": [{"t": "先母躺了下来,还是很热闹的。", "b": "《二十年目睹之怪现状》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3271wx','僻','1','pì','亻','15','','[{"pinyin": "pì", "defs": [{"meaning": "(形声。从人,辟声。本义:退避;回避) 同本义。", "cites": [{"t": "僻,辟也。…《诗》曰:“宛如左僻。”", "b": "《说文》"}]}, {"meaning": "偏僻;偏远;很少有人去的。", "cites": [{"t": "虽僻远其何伤。", "b": "《楚辞·涉江》"}, {"t": "而荆僻也。", "b": "《吕氏春秋·慎行》"}, {"t": "浔阳地僻无音乐。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "僻路", "t": "偏僻的小路"}, {"w": "僻壤", "t": "偏僻的地方"}, {"w": "僻小", "t": "偏僻狭小"}, {"w": "僻穴", "t": "偏僻的洞穴"}, {"w": "僻陋", "t": "偏僻简陋"}, {"w": "僻巷", "t": "偏僻小巷"}, {"w": "僻净", "t": "偏僻清静。"}]}, {"meaning": "邪僻。", "cites": [{"t": "民之多僻。", "b": "《诗·大雅·板》"}], "words": [{"w": "僻王", "t": "邪僻不正的国君"}, {"w": "僻邪", "t": "邪恶"}, {"w": "僻事", "t": "邪僻之事"}, {"w": "僻淫", "t": "邪避淫佚"}, {"w": "僻乱", "t": "邪僻反常,不合正道"}, {"w": "僻诡", "t": "邪避诡诈"}, {"w": "僻错", "t": "邪僻乖张。"}]}, {"meaning": "受宠爱的人。", "cites": [{"t": "便僻好色。", "b": "《韩非子·八奸》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3272wx','德','1','dé','彳','15','','[{"pinyin": "dé", "defs": [{"meaning": "(形声。从彳(chì),惪(dé)声。从“彳”,表示与行走有关。本义:登高,攀登)。"}, {"meaning": "同本义。", "cites": [{"t": "德,升也。", "b": "《说文》"}, {"t": "君子德车。", "b": "《易·剥》虞本。按,与剥庐对文。登也,升。君子以顺德,亦本字。"}]}, {"meaning": "感激。", "cites": [{"t": "然则德我乎。", "b": "《左传·成公三年》"}]}, {"meaning": "取得,获得。", "cites": [{"t": "善者吾善之,不善者吾亦善之,德善。信者吾信之,不信者吾亦信之,德信。", "b": "《老子·四十九章》"}, {"t": "是故用财不费,民德不劳。", "b": "《墨子·节用上》"}]}, {"meaning": "道德,品行。", "cites": [{"t": "德,德行。", "b": "《篇海类编》"}, {"t": "德行,内外之称,在心为德,施之为行。", "b": "《周礼·地官》注"}, {"t": "德何如可以王矣?", "b": "《孟子·梁惠王上》"}, {"t": "六三德。正直、刚克、柔克也。", "b": "《书·洪范》。注:“至德,敏德,孝德也。”"}, {"t": "孤不度德量力,欲信大义于天下。", "b": "《三国志·诸葛亮传》"}, {"t": "无德不贵,无能不官。", "b": "《荀子·王制》"}], "words": [{"w": "德薄", "t": "德行浅薄"}, {"w": "德望", "t": "品德与名誉"}, {"w": "德器", "t": "德行器量"}, {"w": "德被四方", "t": "品德高尚,满布天下"}, {"w": "德薄望浅", "t": "谦词。品德低下,名望轻微"}, {"w": "德门", "t": "能恪遵礼教道德的人家"}, {"w": "德誉", "t": "道德声誉"}, {"w": "德馨", "t": "道德芳馨"}, {"w": "德艺", "t": "道德与才艺"}, {"w": "德操", "t": "道德操行。"}]}, {"meaning": "恩惠;恩德。", "cites": [{"t": "是不敢倍德畔施。", "b": "《战国策·秦策》。注:“恩也。”"}, {"t": "愿伯具言臣之不敢倍德也。", "b": "《史记·项羽本纪》"}], "words": [{"w": "德施", "t": "恩惠;恩泽"}, {"w": "德惠", "t": "德泽恩惠。"}]}, {"meaning": "福。", "cites": [{"t": "百姓之德也。", "b": "《礼记·哀公问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3273wx','艘','1','sōu','舟','15','','[{"pinyin": "sōu", "defs": [{"meaning": "(形声。从舟,叟声。《说文》从木。本义:船的总称)。"}, {"meaning": "海中大船。", "cites": [{"t": "艘,海大舡也。", "b": "《艺文类聚》"}]}, {"meaning": "用于船只计数。", "cites": [{"t": "乃取蒙冲斗舰十艘,载燥荻枯柴,灌油其中。", "b": "《资治通鉴》"}], "words": [{"w": "两艘油船;三艘巡洋舰", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3274wx','膝','1','xī','月','15','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从肉,桼(qī)声。本义:膝头) 大腿和小腿相连关节的前部。通称膝盖。", "cites": [{"t": "今之君子,进人若将加诸膝,退人若将队诸渊。", "b": "《礼记》"}], "words": [{"w": "膝馒头", "t": "膝盖"}, {"w": "膝下荒凉", "t": "指无子女"}, {"w": "膝踝", "t": "膝盖与足踝"}, {"w": "膝拐", "t": "方言。膝盖的别称"}, {"w": "膝弯", "t": "膝关节向后弯曲的部分。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3275wx','膛','1','táng','月','15','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从肉,堂声。本义:胸腔)。"}, {"meaning": "同本义。", "cites": [{"t": "休便要斩首开膛。", "b": "纪君祥《赵氏孤儿》"}], "words": [{"w": "开膛", "t": "剖开胸腔。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3276wx','鲤','1','lǐ','鱼','15','','[{"pinyin": "lǐ", "defs": [{"meaning": "鲤鱼。", "cites": [{"t": "鲤,鱣也。从鱼,里声。", "b": "《说文》。按,鱣者大鱼,似鱏而短,即今之寻黄鱼,非鲤也。"}, {"t": "必河之鲤。", "b": "《诗·陈风·衡门》"}]}, {"meaning": "一种软鳍淡水鱼,素栖于池塘或缓流中,主要吃植物性食物,可长得相当大,有时能活得很长,原为亚洲产物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3277wx','鲫','1','jì','鱼','15','','[{"pinyin": "jì", "defs": [{"meaning": "鲫鱼,亦称“鲋” 。鱼名,体侧扁,中稍高,头部尖,尾部较窄。背面青褐色,腹面银灰色。生活在淡水中。方言又称“鲫瓜子”、“鲫瓜儿”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3278wx','熟','1','shóu shú','灬','15','','[{"pinyin": "shóu", "defs": [{"meaning": "——口语,义同“熟”（shú）。"}]}, {"pinyin": "shú", "defs": [{"meaning": "(形声。从火,孰(shú)声。本作“孰”。“熟”是后起字。本义:煮熟,食物烹煮到可吃的程度)。"}, {"meaning": "同本义。", "cites": [{"t": "熟治万物。", "b": "《礼记·礼运》。疏:“谓烹煮。”"}, {"t": "宰夫胹熊蹯不熟。", "b": "《左传·宣公二年》"}], "words": [{"w": "熟末", "t": "指煮得烂熟的食物"}, {"w": "熟切店", "t": "卖熟肉的店铺"}, {"w": "熟水", "t": "开水"}, {"w": "熟献", "t": "指烹熟的上献祭品。"}]}, {"meaning": "谷物、水果或微生物等成熟。", "cites": [{"t": "秋,大熟,未收。", "b": "《书·金滕》"}, {"t": "五谷熟而民人育。", "b": "《孟子·滕文公上》"}, {"t": "瓜熟蒂落。", "b": "张君房《云笈七签》"}, {"t": "稻有七月熟者,有八九月熟者,有十月熟者谓之晚稻。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "早熟;熟岁", "t": "谷熟之岁"}, {"w": "熟颗", "t": "指成熟的粮食颗粒。"}]}, {"meaning": "成熟。", "cites": [{"t": "夫仁,亦在乎熟之而已矣。", "b": "《孟子·告子上》"}, {"t": "功成业熟也何难。", "b": "庐肇《成名后作》"}]}, {"meaning": "熟悉。", "cites": [{"t": "胡不谋之人心以熟吾道?", "b": "柳宗元《断刑论下》"}, {"t": "无他,但手熟尔。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "熟娴", "t": "即“娴熟”。熟练"}, {"w": "熟嘴", "t": "油嘴;贫嘴"}, {"w": "纯熟", "t": "很熟练"}, {"w": "熟精", "t": "熟悉精通"}, {"w": "熟会", "t": "熟练"}, {"w": "熟溜", "t": "熟练貌"}, {"w": "熟口", "t": "娴于唱曲的人。"}]}, {"meaning": "有收成;丰收。", "cites": [{"t": "天之道出阳为煖以生之,出阴为清以成之,是故非薰也不能有育,非薰也不能有熟,岁之精也。", "b": "汉·董仲舒《春秋繁露·煖燠孰多》"}], "words": [{"w": "熟年", "t": "丰年"}, {"w": "熟岁", "t": "丰年"}, {"w": "熟荣", "t": "丰收。"}]}, {"meaning": "熟悉。", "cites": [{"t": "此论不可不熟。", "b": "《吕氏春秋·重已》。注:“犹知也。”"}, {"t": "而敬亭耳剽口熟,从委巷活套中来者,无不与宁南意合。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "熟口", "t": "熟悉演唱的人"}, {"w": "熟间", "t": "熟悉的行业"}, {"w": "熟精", "t": "熟悉精通"}, {"w": "熟脚", "t": "熟悉情况的人"}, {"w": "熟落", "t": "熟悉"}, {"w": "熟会", "t": "熟悉"}, {"w": "熟晓", "t": "十分了解"}, {"w": "熟滑", "t": "熟悉"}, {"w": "熟分", "t": "熟悉;相熟"}, {"w": "熟狎", "t": "过分亲昵、随便"}, {"w": "熟不讲礼", "t": "熟人不必计较礼数。"}]}, {"meaning": "精审,仔细。", "cites": [{"t": "凡闻言必熟论,其于人必验之以理。", "b": "《吕氏春秋·察传》"}, {"t": "愿大王熟察,少加怜焉。", "b": "汉·邹阳《狱中上梁王书》"}], "words": [{"w": "熟念", "t": "反覆斟酌,仔细考虑"}, {"w": "熟视", "t": "细看"}, {"w": "熟味", "t": "仔细体会"}, {"w": "熟筹", "t": "仔细筹划"}, {"w": "熟算", "t": "深入细致地谋划"}, {"w": "熟寻", "t": "仔细探索"}, {"w": "熟议", "t": "仔细计议"}, {"w": "熟耕", "t": "精耕"}, {"w": "熟计", "t": "周密地谋划。"}]}, {"meaning": "表示程度深。", "cites": [{"t": "守门卒方熟寐,尽杀之。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "熟卧", "t": "熟睡"}, {"w": "熟寐", "t": "熟睡"}, {"w": "熟寝", "t": "熟睡"}, {"w": "醉熟", "t": "沉醉"}, {"w": "熟暑", "t": "酷暑"}, {"w": "熟红", "t": "深红。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3279wx','摩','1','mó mā','手','15','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从手,麻声。本义:摩擦,磨蹭)。"}, {"meaning": "擦，蹭，接触。", "cites": [{"t": "摩,研也。", "b": "《说文》"}, {"t": "刮摩之工。", "b": "《考工记》"}, {"t": "鎋击摩车而相过。", "b": "《战国策·齐策》"}, {"t": "人肩摩。", "b": "《战国策·秦策》"}, {"t": "濯手以摩之,去其皱。", "b": "《礼记·内则》"}], "words": [{"w": "摩戛", "t": "摩擦。也作磨戛"}, {"w": "摩厉", "t": "磨物使锐。引申有磨炼、钻研的意思"}, {"w": "摩肩接毂", "t": "肩挨着肩,车子擦着车子"}, {"w": "摩肩", "t": "肩挨着肩"}, {"w": "摩拭", "t": "揩擦。"}]}, {"meaning": "迫近,接近。", "words": [{"w": "摩近", "t": "接近"}, {"w": "摩垒", "t": "迫近敌垒"}, {"w": "摩霄", "t": "接近云天,冲天。"}]}, {"meaning": "磨砺。", "cites": [{"t": "阴阳相摩,天地相荡。", "b": "《礼记·乐记》"}, {"t": "是故刚柔相摩,八卦相荡。", "b": "《易·系辞上》"}]}, {"meaning": "磨炼。", "cites": [{"t": "反己而不穷,循古而不摩。", "b": "《庄子·徐无鬼》"}]}, {"meaning": "磨灭。", "cites": [{"t": "古者富贵而名摩灭,不可胜记。", "b": "《汉书·司马迁传》"}], "words": [{"w": "摩牙", "t": "磨其牙使之锐利"}, {"w": "摩灭", "t": "磨损消灭,消亡"}, {"w": "摩砻", "t": "犹磨光。"}]}, {"meaning": "切磋;研究。", "cites": [{"t": "刚柔相摩。", "b": "《易·系辞上》"}, {"t": "相观而善之谓摩。", "b": "《礼记·学记》"}], "words": [{"w": "观摩", "t": "观看成绩,交流经验,互相学习"}, {"w": "摩切", "t": "切磋琢磨"}, {"w": "摩研", "t": "切磋研究"}, {"w": "摩拟", "t": "比拟研究。"}]}, {"meaning": "抚摸。", "cites": [{"t": "摩顶受戒。", "b": "《西游记》"}], "words": [{"w": "摩拊", "t": "抚摩;安抚"}, {"w": "摩捋", "t": "顺手抚摩"}, {"w": "摩触", "t": "抚摩;摸索"}, {"w": "摩按", "t": "按摩。"}]}]}, {"pinyin": "mā", "defs": [{"meaning": "用手轻按着并一下一下地抚摩。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3280wx','褒','1','bāo','衣','15','','[{"pinyin": "bāo", "defs": [{"meaning": "(形声。从衣,保声。本义:衣襟宽大)。"}, {"meaning": "同本义。", "cites": [{"t": "褒,衣博裙。", "b": "《说文》"}, {"t": "岂必褒衣博带,句襟委章甫哉?", "b": "《淮南子·泛论》"}], "words": [{"w": "褒袖", "t": "宽大的袖子"}, {"w": "褒衣博带", "t": "大衣服,宽带子。是古代儒者所穿的衣服。"}]}, {"meaning": "嘉奖,表扬。", "cites": [{"t": "非敢褒其可褒,而贬其可贬也。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "褒赞", "t": "赞扬称美"}, {"w": "褒显", "t": "褒扬。称美显扬"}, {"w": "褒赏", "t": "奖赏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3281wx','瘪','1','biē biě','疒','15','','[{"pinyin": "biē", "defs": [{"meaning": "用同“憋”。闷。", "cites": [{"t": "既然要钱,为什么不说明,叫我瘪了两三个月呢?", "b": "《官场现形记》"}]}]}, {"pinyin": "biě", "defs": [{"meaning": "引申为气馁。", "cites": [{"t": "他先还强,看见我是三分局的,他瘪了。", "b": "张天翼《夏夜梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3282wx','瘤','1','liú','疒','15','','[{"pinyin": "liú", "defs": [{"meaning": "瘤子,身体组织增生形成的赘生物,多由刺激或微生物寄生而起。分癌瘤、肉瘤、淋巴瘤、血管瘤、脂瘤和骨瘤等。", "cites": [{"t": "瘤,肿也。从疒,留声。", "b": "《说文》"}, {"t": "肉凸曰瘤。", "b": "《通俗文》"}, {"t": "瘤,息肉也。", "b": "《声类》"}, {"t": "瘤,小肿也。", "b": "《三苍》"}], "words": [{"w": "瘤牛;瘤赘", "t": "体表或筋骨间增生的肉疙瘩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3283wx','瘫','1','tān','疒','15','','[{"pinyin": "tān", "defs": [{"meaning": "(形声。从疒,难声。疒(chuáng),与疾病有关。本义:瘫痪,指肌体不能随意运动,也比喻机构不能正常运转) 同本义", "words": [{"w": "瘫风", "t": "谓风瘫"}, {"w": "瘫缓", "t": "瘫痪"}, {"w": "瘫废", "t": "风瘫残废"}, {"w": "瘫睡", "t": "谓躺卧"}, {"w": "瘫倒", "t": "倒下难以动弹"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3284wx','凛','1','lǐn','冫','15','','[{"pinyin": "lǐn", "defs": [{"meaning": "(形声。从仌(bīng)冰。禀(bǐng)声。本义:剌骨的寒冷)。"}, {"meaning": "同本义。", "cites": [{"t": "癛,寒也。从欠,廩声。字亦作凛。又作懔。", "b": "《说文》"}, {"t": "其性为凛。", "b": "《素问·五运行大论》。注:“寒也。肾之性也。”"}, {"t": "寒则凛冻。", "b": "《风俗通·究通》"}, {"t": "凛凛寒风升。", "b": "潘岳《悼亡诗》"}, {"t": "凛秋暑退,熙春寒往。", "b": "潘岳《闲居赋》"}], "words": [{"w": "凛冽", "t": "非常寒冷"}, {"w": "凛栗", "t": "因寒冷而颤抖"}, {"w": "凛秋", "t": "寒冷的秋天"}, {"w": "凛气", "t": "寒气"}, {"w": "凛寒", "t": "寒冷。"}]}, {"meaning": "严肃而可敬畏。", "cites": [{"t": "凛者,颜色惧貌。", "b": "《埤苍》"}, {"t": "凛凛四百余兆之国民。", "b": "梁启超《少年中国说》"}], "words": [{"w": "凛凛敛敛", "t": "威严而使人敬畏的样子"}, {"w": "凛如", "t": "严肃"}, {"w": "凛严", "t": "严肃"}, {"w": "凛畏", "t": "敬畏"}, {"w": "凛如", "t": "令人敬畏"}, {"w": "凛严", "t": "敬畏的样子。"}]}, {"meaning": "畏惧。", "cites": [{"t": "凛乎其不可留也。", "b": "苏轼《后赤壁赋》"}], "words": [{"w": "凛畏", "t": "畏惧"}, {"w": "凛栗", "t": "恐惧;惊恐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3285wx','颜','1','yán','页','15','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从页,彦(yàn)声。从页(xié),与头有关。本义:印堂)。"}, {"meaning": "印堂,两眉之间。", "cites": [{"t": "颜,眉目之间也。", "b": "《说文》。段玉裁注:“各本作眉目之间,浅人妄增字耳,今正。眉与眉之间不名颜。…颜为眉间,医经所谓阙,道书所谓上丹田,相书所谓中正印堂也。”"}]}, {"meaning": "额头。", "cites": [{"t": "高祖为人,隆准而龙颜。", "b": "班固《汉书》"}], "words": [{"w": "颜角", "t": "额角"}, {"w": "颜题", "t": "古代头巾覆额面部分。"}]}, {"meaning": "面容,脸色。", "cites": [{"t": "有女同车,颜如舜华。", "b": "《诗·郑风》"}], "words": [{"w": "颜状", "t": "容颜状貌"}, {"w": "颜厚", "t": "面有惭色,难为情"}, {"w": "颜貌", "t": "容貌。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3286wx','毅','1','yì','殳','15','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从殳,“殳”指兵器。本义:意志坚强、果断)。"}, {"meaning": "同本义。", "cites": [{"t": "毅,有决也。", "b": "《说文》"}, {"t": "毅,强而能断也。", "b": "《论语·泰伯》"}, {"t": "刚、毅、木、讷近仁。", "b": "《论语·子路》"}, {"t": "士不可以不弘毅,任重而道远。", "b": "《论语·泰伯》"}, {"t": "性严毅。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "毅武", "t": "刚强勇武"}, {"w": "毅烈", "t": "刚毅节烈。"}]}, {"meaning": "坚决。", "cites": [{"t": "心毅,则憎心见于下。", "b": "《韩非子·八说》"}, {"t": "杀敌为果,致果为毅。", "b": "《左传》"}], "words": [{"w": "毅色", "t": "严肃坚决的神态。"}]}, {"meaning": "残忍,残酷。", "cites": [{"t": "强忍犯义,毅也。", "b": "《国语·楚语下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3287wx','糊','1','hú hū hù','米','15','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从米,胡声。本义:同“餬”。稠粥) 同本义。", "cites": [{"t": "日用面一斗为糊,以供缄封。", "b": "唐·冯贽《云仙杂记》引《宣武盛事》"}]}, {"meaning": "用粥填塞。比喻勉强维持生活。", "cites": [{"t": "今既糊口无以至来秋,来秋或复不熟,将如之何?", "b": "《魏书》"}]}]}, {"pinyin": "hū", "defs": [{"meaning": "涂抹或粘合使封闭起来"}]}, {"pinyin": "hù", "defs": [{"meaning": "像粥一样的食物", "words": [{"w": "面糊", "t": ""}]}, {"meaning": "欺骗，蒙混，敷衍", "words": [{"w": "糊弄", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3288wx','遵','1','zūn','辶','15','','[{"pinyin": "zūn", "defs": [{"meaning": "(形声。从辵(chuò),尊声。本义:顺着,沿着) 同本义。", "cites": [{"t": "遵,循也。", "b": "《说文》"}, {"t": "遵大路兮。", "b": "《诗·郑风·遵大路》"}, {"t": "女执懿筐,遵彼微行。", "b": "《诗·豳风·七月》"}, {"t": "遵四时以叹逝,瞻万物而思纷。", "b": "陆机《文赋》"}, {"t": "遵江夏以流亡。", "b": "屈原《九章》"}], "words": [{"w": "遵依", "t": "遵照"}, {"w": "遵巡", "t": "顺着;沿着"}, {"w": "遵序", "t": "依次,顺着次序"}, {"w": "遵时", "t": "顺应时势"}, {"w": "遵海", "t": "沿着海岸"}, {"w": "遵陆", "t": "沿着陆路。"}]}]}]','jingmo-wenyan');
