('3289wx','憋','1','biē','心','15','','[{"pinyin": "biē", "defs": [{"meaning": "(形声。从心,敝声。本义:性急)。"}, {"meaning": "同本义。", "cites": [{"t": "憋,曰性急。", "b": "《集韵》"}], "words": [{"w": "憋懯", "t": "亦作“憋怤”。急性"}, {"w": "憋肠", "t": "急性子"}, {"w": "憋古", "t": "性格暴烈、古怪、不合时宜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3290wx','潜','1','qián','氵','15','','[{"pinyin": "qián", "defs": [{"meaning": "(形声。本义:没入水中,而且在水下活动)。"}, {"meaning": "同本义。", "cites": [{"t": "潜,涉水也。", "b": "《说文》。朱骏声按:没水以涉曰潜。"}, {"t": "潜龙。", "b": "《易·乾龙》"}, {"t": "潜虽伏矣。", "b": "《诗·小雅·正月》"}, {"t": "游鱼潜绿水。", "b": "曹植《情诗》"}, {"t": "沈潜相克。", "b": "《书·洪范》"}, {"t": "潜龙腾渊。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "潜水", "t": ""}]}, {"meaning": "隐藏。", "cites": [{"t": "潜服贼器不入宫。", "b": "《周礼·阍人》"}, {"t": "潜醢以食夏后。", "b": "《左传·昭公二十九年》"}, {"t": "日星隐耀,山岳潜形。", "b": "范仲淹《岳阳楼记》"}, {"t": "胆寒潜踪。", "b": "《广东军务记》又"}, {"t": "潜避两炮台中。", "b": ""}], "words": [{"w": "潜晦", "t": "潜藏养晦。又指隐藏才能"}, {"w": "潜德", "t": "韬养隐藏的内涵、美德"}, {"w": "潜逸", "t": "隐逸"}, {"w": "潜户", "t": "隐藏的洞穴"}, {"w": "潜包,潜苞", "t": "包藏"}, {"w": "潜光", "t": "隐藏光彩"}, {"w": "潜名", "t": "隐姓埋名。"}]}, {"meaning": "埋葬。", "cites": [{"t": "西望大泽,后稷所潜也。", "b": "《山海经》"}]}, {"meaning": "暗流。", "cites": [{"t": "东望泑泽,河水所潜也。", "b": "《山海经》"}], "words": [{"w": "潜演", "t": "水在地下流动"}, {"w": "潜源", "t": "潜伏着的水源。"}]}, {"meaning": "测量;探测。"}, {"meaning": "深;沉。", "cites": [{"t": "夫雷霆必发,而潜底震动。", "b": "汉·王褒《四子讲德论》"}], "words": [{"w": "潜林", "t": "高深的树林"}, {"w": "潜深", "t": "幽深隐蔽"}, {"w": "潜渫", "t": "深浚"}, {"w": "潜寐", "t": "深眠"}, {"w": "潜运", "t": "深谋"}, {"w": "潜润", "t": "深深沾惠。"}]}, {"meaning": "秘密地;暗中。", "cites": [{"t": "同恶潜谋。", "b": "《周书·文政》"}, {"t": "于是潜行而去。", "b": "《战国策·秦策》"}, {"t": "随风潜入夜。", "b": "唐·杜甫《春夜喜雨》"}, {"t": "多潜易之。", "b": "清·方苞《狱中杂记》"}, {"t": "封奏时潜易。", "b": ""}], "words": [{"w": "潜地", "t": "偷偷地"}, {"w": "潜息", "t": "悄悄止息"}, {"w": "潜目", "t": "偷看"}, {"w": "潜使", "t": "秘密出使"}, {"w": "潜师", "t": "秘密出兵"}, {"w": "潜逸", "t": "秘密逃跑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3291wx','澎','1','péng','氵','15','','[{"pinyin": "péng", "defs": [{"meaning": "(形声。从水,彭声。本义:波涛发出冲击声)。"}, {"meaning": "迸发。", "cites": [{"t": "一个女人家有甚么胆气,小的到他门上澎出几句闲话,他怕族人知道,他自然给小的百十两银子,买告小的。", "b": "《醒世姻缘传》"}], "words": [{"w": "澎澎", "t": "象声词"}, {"w": "澎澎渤渤", "t": "蓬勃,旺盛。"}]}, {"meaning": "古县名。", "cites": [{"t": "澎,县名,在东海。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3292wx','潮','1','cháo','氵','15','','[{"pinyin": "cháo", "defs": [{"meaning": "(形声。从水,朝声。本义:海水的涨落)。"}, {"meaning": "同本义。", "cites": [{"t": "潮,水朝宗于海。", "b": "《说文》"}, {"t": "牛女为江潮。", "b": "《春秋·元命苞》"}, {"t": "水朝夕而至曰潮。", "b": "《初学记卷六水》"}, {"t": "有江盗百艘,张帜乘潮,阑入内地。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "大潮,小潮;低潮;退潮;落潮", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3293wx','潭','1','tán xún','氵','15','','[{"pinyin": "tán", "defs": [{"meaning": "(形声。从水,覃声。本义:水名)。"}, {"meaning": "同本义 。在广西境内,即今柳江。", "cites": [{"t": "潭,水。出武陵镡成玉山,东入郁林。", "b": "《说文》"}]}, {"meaning": "深水池。", "cites": [{"t": "潭,渊也。", "b": "广雅·释水》"}, {"t": "泝江潭兮。", "b": "《楚辞·九章·抽思》。注:“潭,渊也。楚人名渊曰潭。”"}, {"t": "崖冈潭渊。", "b": ""}, {"t": "文选·左思·吴都赋》", "b": ""}, {"t": "随山疏濬潭。", "b": "谢灵运《述祖德诗》"}, {"t": "下见小潭。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "潭中鱼可百许头。", "b": ""}, {"t": "潭西南而望。", "b": ""}, {"t": "坐潭上。", "b": ""}], "words": [{"w": "潭心", "t": "潭底,渊底"}, {"w": "潭石", "t": "深谷里的岩石"}, {"w": "潭影", "t": "潭中的光影"}, {"w": "潭府", "t": "深渊"}, {"w": "潭渊", "t": "深渊。"}]}, {"meaning": "古州名 。治所在今湖南省长沙市。", "cites": [{"t": "潭州,汉曰长沙国,隋曰潭州,唐因之,亦曰长沙郡,领长沙等县五,今长沙府。", "b": "《读史方舆纪要》"}]}, {"meaning": "深;深邃。", "cites": [{"t": "潭根之毋伐。", "b": "《管子·侈靡》"}, {"t": "潭思浑天。", "b": "《汉书·扬雄传下》"}], "words": [{"w": "潭潭", "t": "水深的样子"}, {"w": "潭奥", "t": "深隐的内室"}, {"w": "潭思", "t": "深思"}, {"w": "潭井", "t": "深井。"}]}]}, {"pinyin": "xún", "defs": [{"meaning": "水边;水边深处。", "cites": [{"t": "轻鸿戏江潭,孤雁集洲沚。", "b": "南朝宋·鲍照《赠傅都曹别》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3294wx','鲨','1','shā','鱼','15','','[{"pinyin": "shā", "defs": [{"meaning": "鲨鱼 ,亦称“鲛”。包括大约225种食肉性的板鳃亚纲鱼类,主要生活于热带与亚热带的海洋中,具纺锤形的身躯和歪形尾以及坚硬的通常是灰色的皮肤,皮肤上有大量的瘤子,显得很粗糙,吻部突出于嘴的前边,两边都有鳃孔,雄鱼有鳍脚和伸长的腹鳍。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3295wx','澳','1','ào','氵','15','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。从水,奥声。(yù)本义:水边地)。"}, {"meaning": "港湾,海边弯曲可以停船的地方。", "cites": [{"t": "无港澳以容舟楫。", "b": "《宋史·河渠志》"}], "words": [{"w": "澳闸", "t": "拦河水闸。"}]}, {"meaning": "澳水 。今俗名凉河,在今河南省泌阳县,为泌阳河支流。"}, {"meaning": "澳大利亚的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3296wx','潘','1','pān','氵','15','','[{"pinyin": "pān", "defs": [{"meaning": "古水名。"}, {"meaning": "在河南省荥阳县境。"}, {"meaning": "在浙江省绍兴市境,后堙。或以为是今运河经绍兴的一段河道。"}, {"meaning": "约在山东省淄博市一带,或以为是淄水。"}, {"meaning": "山名。在广东省茂名市。"}, {"meaning": "古州名。"}, {"meaning": "治所在今广东省茂名市。"}, {"meaning": "在今四川省松潘县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3297wx','澈','1','chè','氵','15','','[{"pinyin": "chè", "defs": [{"meaning": "(形声。从水,本义:水清)。"}, {"meaning": "同本义。", "cites": [{"t": "澈,水澄也。", "b": "《玉篇》"}, {"t": "白石粼粼。", "b": "《诗·唐风·扬之水》。传:“粼粼,清澈也。”"}, {"t": "林虚星华映,水澈霞光净。", "b": "唐·骆宾王《夏日游德州赠高四》"}, {"t": "清潭镜澈。", "b": "《水经注》"}], "words": [{"w": "清澈", "t": "水清而透明"}, {"w": "澈底", "t": "水清可见底"}, {"w": "澈亮", "t": "清澈明亮"}, {"w": "澈漠", "t": "清澈。"}]}, {"meaning": "清朗。", "cites": [{"t": "露凝无游氛,无高风景澈。", "b": "晋·陶潜《和郭主簿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3298wx','澜','1','lán','氵','15','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从水,阑(lán)声。本义:大波浪)。"}, {"meaning": "同本义。", "cites": [{"t": "澜,大波也。", "b": "《说文》"}, {"t": "大波为澜,小波为沦。", "b": "《尔雅》"}, {"t": "天下安澜。", "b": "《四子讲德论》"}, {"t": "观水有术,必观其澜。", "b": "《孟子·尽心上》"}, {"t": "回狂澜于既倒。", "b": "韩愈《进学解》"}, {"t": "至若春和景明,波澜不惊。", "b": "《岳阳楼记》"}], "words": [{"w": "狂澜;巨澜;澜倒波随", "t": "犹言随波逐流。比喻言行无标准"}, {"w": "澜澳", "t": "水曲"}, {"w": "波澜", "t": "波涛"}, {"w": "推波助澜", "t": ""}]}, {"meaning": "波纹。", "cites": [{"t": "风行水波成文曰澜。", "b": "《释名》"}, {"t": "珠玉潜水,而澜表方圆。", "b": "《文心雕龙·隐秀》"}], "words": [{"w": "死水微澜;安澜", "t": "河流平静,没有泛滥现象"}, {"w": "微澜", "t": "小波纹"}, {"w": "澜清", "t": "清澄如水。"}]}, {"meaning": "兴起波澜。", "cites": [{"t": "若流波之将澜。", "b": "宋玉《神女赋》"}], "words": [{"w": "澜翻", "t": "水势翻腾"}, {"w": "澜澜", "t": "泪涌下的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3299wx','澄','1','chéng dèng','氵','15','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从水,登声。本义:水静而清)。"}, {"meaning": "同本义。", "cites": [{"t": "澄,水清定也。", "b": "《集韵》"}, {"t": "澄,水静而清也。", "b": "《增韵》"}, {"t": "水色澄碧。", "b": "黄肇敏《黄山纪游》"}], "words": [{"w": "澄水", "t": "清澈而平静无波的水"}, {"w": "澄江", "t": "清澄明澈的江水"}, {"w": "澄泉", "t": "清泉"}, {"w": "澄酒", "t": "清酒,淡酒。"}]}, {"meaning": "清澈,透明。", "cites": [{"t": "心澄体静。", "b": "徐干《中论》"}]}, {"meaning": "又如 :澄空(晴朗无云的天空);澄明(澄澈明洁)。"}, {"meaning": "静,宁静。", "cites": [{"t": "公退则敛膝澄坐以养心。", "b": "方孝儒《静斋记》"}], "words": [{"w": "澄凝", "t": "沉静的"}, {"w": "澄谧", "t": "清静"}, {"w": "澄宁", "t": "清静安定。"}]}, {"meaning": "水名。"}, {"meaning": "即今浙江省台州地区的灵江。"}, {"meaning": "海南岛上南渡江的支流,在澄迈县境。"}]}, {"pinyin": "dèng", "defs": [{"meaning": "", "words": [{"w": "把水澄清了;澄汰", "t": "澄去泥滓;汰除沙砾。多用于指甄别、挑选"}, {"w": "澄结", "t": "沉积"}, {"w": "澄沙汰砾", "t": "除去杂质,使之纯洁。"}]}]}]','jingmo-wenyan');
