('3300wx','懂','1','dǒng','忄','15','','[{"pinyin": "dǒng", "defs": [{"meaning": "了解，明白", "words": [{"w": "懂行", "t": "对某一种业务熟悉,了解情况"}, {"w": "懂得", "t": "谓了解其事或其意"}, {"w": "懂事", "t": "了解别人的意图或明白事理的"}, {"w": "懂门路", "t": "[方言]对某种事物有较深的了解"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3301wx','憔','1','qiáo','忄','15','','[{"pinyin": "qiáo", "defs": [{"meaning": "(会意。从心,焦声。本义:憔悴,瘦弱萎靡的样子。也泛指折磨困苦) 同本义。", "cites": [{"t": "顦,面焦枯小也。从面焦,焦亦声。", "b": "《说文》"}, {"t": "而日以憔悴。", "b": "《国语·吴语》"}, {"t": "身憔悴而考且。", "b": "《楚辞·离世》"}, {"t": "顦妍太息。", "b": "《汉书·外戚传》"}], "words": [{"w": "憔瘁", "t": "黄瘦,瘦损。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3302wx','懊','1','ào','忄','15','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。从心,奥声。本义:失悔,认识到错了而烦恼) 同本义。", "cites": [{"t": "门生惊懊者累日。", "b": "《晋书·王羲之传》"}, {"t": "垂头视之,如有懊丧竟。", "b": "《世说新语·言语》"}], "words": [{"w": "懊叹", "t": "悔恨而叹息"}, {"w": "懊憹", "t": "懊恼;烦闷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3303wx','憎','1','zēng','忄','15','','[{"pinyin": "zēng", "defs": [{"meaning": "(形声。从心,曾声。本义:憎恨厌恶) 同本义。", "cites": [{"t": "憎,恶也。", "b": "《说文》"}, {"t": "憎而知其善。", "b": "《礼记·曲礼》"}, {"t": "盗憎主人。", "b": "《国语·晋语》"}, {"t": "秦甚憎齐。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "憎人", "t": "可憎恶的人"}, {"w": "憎妒", "t": "憎恨妒忌"}, {"w": "憎命", "t": "憎恶命运"}, {"w": "憎毒", "t": "憎恨痛恨"}, {"w": "憎恨", "t": "厌恶怨恨"}, {"w": "憎毁", "t": "憎恶诋毁"}, {"w": "憎爱", "t": "憎恨与喜爱"}, {"w": "憎怜", "t": "憎爱"}, {"w": "憎丑", "t": "憎恶。憎恨厌恶"}, {"w": "憎愤", "t": "犹愤恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3304wx','额','1','é','页','15','','[{"pinyin": "é", "defs": [{"meaning": "(形声。从页(xié),客声。从“页”,表示与头有关。本义:额头,脑门)。"}, {"meaning": "同本义。", "cites": [{"t": "頟,颡也。从页,各声。字亦作额。", "b": "《说文》"}, {"t": "封说为龙頟侯。", "b": "《汉书·卫青传》"}, {"t": "龙额。", "b": "《汉书·景武昭宣元成功臣表》"}], "words": [{"w": "额颅", "t": "额头,前额"}, {"w": "额颅盖", "t": "前额"}, {"w": "额花", "t": "妇女用来贴在额上的以纸、绢、玉等做成的装饰花"}, {"w": "额黄", "t": "六朝至唐时的妇女,喜欢在额间涂上黄颜色作为装饰,称为额黄。也称“额山”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3305wx','翩','1','piān','羽','15','','[{"pinyin": "piān", "defs": [{"meaning": "(形声。从羽,扁声。本义:疾飞的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "翩,疾飞也。", "b": "《说文》"}, {"t": "翩扇不富。", "b": "《易·泰卦》"}, {"t": "翩彼飞鴞。", "b": "《诗·鲁颂·泮水》"}, {"t": "众鸟翩翻。", "b": "汉·张衡《西京赋》"}], "words": [{"w": "翩联", "t": "共飞的样子;联翩;结姻"}, {"w": "翩飞", "t": "轻快地飞舞"}, {"w": "翩旋", "t": "轻快地飞舞。"}]}, {"meaning": "轻舞,飘扬。", "words": [{"w": "翩翻", "t": "飘动、摇曳的样子"}, {"w": "翩连", "t": "飘扬不断"}, {"w": "翩绵", "t": "飘忽连绵。"}]}, {"meaning": "动作轻疾或体态生动。", "cites": [{"t": "翩若惊鸿。", "b": "三国魏·曹植《洛神赋》"}], "words": [{"w": "翩幡", "t": "行动轻疾。"}]}, {"meaning": "风流潇洒貌。", "cites": [{"t": "妹发垂垂弟貌翩。", "b": "梁启超《饮冰室诗话》"}]}, {"meaning": "反貌。", "cites": [{"t": "翩其反矣。", "b": "《诗·小雅·角弓》"}], "words": [{"w": "翩反", "t": "相反。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3306wx','褥','1','rù','衤','15','','[{"pinyin": "rù", "defs": [{"meaning": "(形声。从衣,辱声。本义:坐卧的垫具) 同本义。", "cites": [{"t": "褥,荐也。", "b": "《三苍》"}, {"t": "寝必重褥。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "褥甸", "t": "小的褥子,供坐卧"}, {"w": "坐褥;褥垫;褥席", "t": "坐卧用的垫具或席具"}, {"w": "褥子;褥位", "t": "铺有锦褥的座位"}, {"w": "褥草", "t": "一种主要的垫料。如稿杆、草皮等;也指垫料的别名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3307wx','谴','1','qiǎn','讠','15','','[{"pinyin": "qiǎn", "defs": [{"meaning": "(形声。本义:责备,斥责)。"}, {"meaning": "同本义。", "cites": [{"t": "谴,谪问也。", "b": "《说文》"}, {"t": "谴,呵也。", "b": "《苍颉篇》"}, {"t": "畏此谴怒。", "b": "《诗·小雅·小明》"}, {"t": "闻而谴友。", "b": "《孔子家语·五行》"}, {"t": "某时有客过而予汝金,因谴之。", "b": "《韩非子·外储说左上》"}, {"t": "前者,失救泾河老龙,获谴于我皇后帝。", "b": "《西游记》"}], "words": [{"w": "谴谪", "t": "责备"}, {"w": "谴斥", "t": "受责备"}, {"w": "谴告", "t": "谴责警告"}, {"w": "谴呵", "t": "谴责申叱"}, {"w": "谴咎", "t": "谴责罪过"}, {"w": "谴怒", "t": "怒责。"}]}, {"meaning": "旧时官吏被贬或谪戍。", "cites": [{"t": "又不得已而谴,则为之择地而居。", "b": "刘禹锡《上杜司徒书》"}], "words": [{"w": "谴谪", "t": "官吏因罪降级,调往边远地方"}, {"w": "谴客", "t": "被贬谪的人"}, {"w": "谴域", "t": "谪迁之地"}, {"w": "谴逐", "t": "贬谪放逐。"}]}, {"meaning": "罪过。", "cites": [{"t": "臣有大谴。", "b": "《北史·李彪传》"}, {"t": "欲以改正思谴,除凶致吉。", "b": "《后汉书·蔡邕传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3308wx','鹤','1','hè','鸟','15','','[{"pinyin": "hè", "defs": [{"meaning": "(形声。从鸟,隺(hè)声。本义:鹤科各种类鸟的统称,皆为大型涉禽)同本义 ,包括一小组体高的涉禽,外形如鹭但构造较接近于秧鸡,通常大于鹭,与鹭不同的是有分裂的颅骨,羽毛更紧密,部分秃顶,嘴较钝并在近中央处有较大鼻孔,后趾向上抬起。", "cites": [{"t": "鹤,似鹄长喙。", "b": "《广韵》"}, {"t": "鹤鸣于九皋。", "b": "《诗·小雅·鹤鸣》"}, {"t": "腾群鹤于瑶光。", "b": "《楚辞·刘向·九叹·远游》"}], "words": [{"w": "鹤音", "t": "鹤鸣声"}, {"w": "鹤侣", "t": "鹤的伴侣"}, {"w": "鹤唳", "t": "鹤鸣"}, {"w": "鹤胫", "t": "鹤的小腿"}, {"w": "鹤语", "t": "鹤的叫声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3309wx','憨','1','hān','心','15','','[{"pinyin": "hān", "defs": [{"meaning": "(形声。从心,敢声。《说文》作“戆”。本义:痴呆,傻气)。"}, {"meaning": "同本义。", "cites": [{"t": "狂惑戆陋之人。", "b": "《荀子·儒效》。按,字亦作“憨”。"}], "words": [{"w": "憨虫", "t": "傻瓜"}, {"w": "憨子", "t": "傻子"}, {"w": "憨砖", "t": "笨蛋;傻瓜"}, {"w": "憨哥", "t": "傻小子"}, {"w": "憨头狼", "t": "傻小子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3310wx','慰','1','wèi','心','15','','[{"pinyin": "wèi", "defs": [{"meaning": "(形声。从心,尉声。本义:安慰)。"}, {"meaning": "同本义。", "cites": [{"t": "慰,安也。", "b": "《说文》"}, {"t": "有子七人,莫慰母心。", "b": "《诗·邶风·凯风》"}, {"t": "以慰长想。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "慰留不允。", "b": "清·张廷玉《明史》"}], "words": [{"w": "慰眼", "t": "观赏,饱眼福"}, {"w": "劝慰", "t": "劝解安慰"}, {"w": "自慰", "t": "自己安慰自己"}, {"w": "抚慰", "t": "安慰"}, {"w": "慰存", "t": "安抚慰问"}, {"w": "慰唁", "t": "安慰勉励"}, {"w": "慰喭", "t": "对遭丧事者的慰问;安慰,慰勉"}, {"w": "慰肃", "t": "慰问;整肃"}, {"w": "慰纳", "t": "安抚招纳或接纳。"}]}, {"meaning": "居住。", "cites": [{"t": "慰,居也。", "b": "《玉篇》"}]}, {"meaning": "问。", "cites": [{"t": "时时慰风俗,往往出东田。", "b": "李白诗"}]}, {"meaning": "愤怒。", "cites": [{"t": "慰,一曰恚怒也。", "b": "《说文》"}]}, {"meaning": "段玉裁注:《小雅》:“以慰我心。”毛曰:“慰,怨也。”《韩诗》作以愠我心。愠恚也。"}, {"meaning": "心安。", "cites": [{"t": "夫妻心稍慰。", "b": "《聊斋志异·促织》"}, {"t": "吾心甚慰。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "欣慰", "t": "喜欢而心安"}, {"w": "慰姁", "t": "宽厚和悦"}, {"w": "慰释", "t": "宽慰;宽解"}, {"w": "慰情聊胜天", "t": ""}]}, {"meaning": "抑郁 。"}, {"meaning": "病。", "cites": [{"t": "贪财而取慰,贪权而取竭。", "b": "《庄子·盗跖》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3311wx','劈','1','pī pǐ','刀','15','','[{"pinyin": "pī", "defs": [{"meaning": "(形声。从刀,辟声。本义:破开;分割)。"}, {"meaning": "同本义。", "cites": [{"t": "劈,破也。", "b": "《说文》"}, {"t": "劈,分也。", "b": "《广雅》"}, {"t": "劈,剖也。", "b": "《埤苍》"}, {"t": "以刀劈狼首。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "劈心", "t": "剖心"}, {"w": "劈半儿", "t": "分做两半"}, {"w": "劈拉", "t": "成八字分开"}, {"w": "劈笺", "t": "裁纸"}, {"w": "劈空", "t": "划破长空。"}]}, {"meaning": "正对着; 冲着。", "cites": [{"t": "便把鱼汁劈脸泼将去,淋那酒保一身。", "b": "《水浒传》"}, {"t": "劈胸只一提,丢翻在雪地上。", "b": ""}], "words": [{"w": "劈心", "t": "对准心口"}, {"w": "劈腰", "t": "当腰,正对着腰"}, {"w": "劈脊", "t": "正对着脊背"}, {"w": "劈口", "t": "正对着嘴"}, {"w": "劈头劈脸", "t": "正对着头和脸而来"}, {"w": "劈先里", "t": "首先;开头"}, {"w": "劈头", "t": "立即;马上"}, {"w": "劈空", "t": "突然;忽然。"}]}, {"meaning": "辨。", "cites": [{"t": "举其理,则皆谟明渊沉,剖微穷深,劈析是非,校度古今。", "b": "唐·柳宗元《答问》"}]}]}, {"pinyin": "pǐ", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3312wx','履','1','lǚ','尸','15','','[{"pinyin": "lǚ", "defs": [{"meaning": "(会意。小篆字,从尸,即人;从彳(chì),表示与行走有关。履在战国以前一般只作动词用。一般用“屦”称鞋子。用“鞋”是唐以后的事了。本义:践踏)。"}, {"meaning": "同本义。", "cites": [{"t": "履霜,履虎尾。", "b": "《易·坤》"}, {"t": "可以履霜。", "b": "《诗·魏风·葛屦》"}, {"t": "履蒯席。", "b": "《礼记·玉藻》"}, {"t": "地履其黄。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "足之所履。", "b": "《庄子·养生主》"}], "words": [{"w": "履危", "t": "蹈践高危之处"}, {"w": "履亩", "t": "勘查田亩"}, {"w": "履虎尾", "t": "踩踏虎尾"}, {"w": "履迹", "t": "踏着前人的足迹"}, {"w": "履霜", "t": "踩踏霜地。比喻由眼下迹象而警戒未来"}, {"w": "涉水如履平地;履冰", "t": "行于冰上"}, {"w": "履冰狐", "t": "踏冰而过的狐狸"}, {"w": "履坦", "t": "行于坦途"}, {"w": "履虚", "t": "行于虚空之中"}, {"w": "履薄行走", "t": "于薄冰上。"}]}, {"meaning": "穿鞋。", "cites": [{"t": "自履藤鞋收石蜜。", "b": "唐·李贺《南园》"}]}, {"meaning": "登位。", "cites": [{"t": "履其位而不履其事。", "b": "《礼记·表记》"}, {"t": "履至尊。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "履任", "t": "到任,就任"}, {"w": "履位", "t": "就位。"}]}, {"meaning": "实行。", "cites": [{"t": "处其位而不履其事,则乱也。", "b": "《礼记》"}], "words": [{"w": "履善", "t": "行善"}, {"w": "履蹈", "t": "实行"}, {"w": "履中", "t": "实行中庸之道"}, {"w": "履谦", "t": "行谦让之德"}, {"w": "履经", "t": "行邪道。"}]}, {"meaning": "开始担任职务。", "cites": [{"t": "将履新任。", "b": "清·张廷玉《明史》"}], "words": [{"w": "履任", "t": "上任,就职"}, {"w": "履端", "t": "开头。"}]}, {"meaning": "鞋。", "cites": [{"t": "履,足所依也。", "b": "《说文》。按,古曰舄,曰屦,汉以后曰履。今曰鞵。此字本训践。转注为所以践之具也。"}, {"t": "丝作之者谓之履。", "b": "《方言四》"}, {"t": "脱履户外。", "b": "《列子·黄帝》"}, {"t": "衣敝履空。", "b": "《汉书·鲍宣传》"}, {"t": "不辨衣履。", "b": "清·周容《芋老人传》"}, {"t": "蹑丝履。", "b": "宋·司马光《训俭示康》"}, {"t": "衣履天下。", "b": "《史记·货殖列传》"}, {"t": "孺子,下取履。", "b": "《史记·留侯世家》"}, {"t": "郑人有欲买履者。", "b": "《韩非子·外储说左上》"}, {"t": "脱丝履。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "革履", "t": "皮鞋"}, {"w": "履屐", "t": "鞋"}, {"w": "履带", "t": "鞋和衣带"}, {"w": "履组", "t": "鞋带"}, {"w": "履靸", "t": "指鞋。"}]}, {"meaning": "足。", "cites": [{"t": "顿履随疏节,低鬟逐上声。", "b": "庾信《和咏舞》"}]}, {"meaning": "领土,疆土。", "cites": [{"t": "赐我先君履,东至于海,西至于河。", "b": "《左传·僖公四年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3313wx','豫','1','yù','豕','15','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从象,予声。本义:大象)。"}, {"meaning": "同本义。", "cites": [{"t": "豫,象之大者。", "b": "《说文》"}, {"t": "豫焉若冬涉川。", "b": "《老子》。范应元注:“豫,象属。”"}]}, {"meaning": "地名。豫州,古九州之一 。其地包括今河南省和湖北省北部。", "cites": [{"t": "指通豫南。", "b": "《列子·汤问》"}]}, {"meaning": "今河南省的简称 。因古为豫州地而得名。"}, {"meaning": "假借为“娱”。快乐。", "cites": [{"t": "豫,乐也。", "b": "《尔雅》"}, {"t": "豫,悦豫也。", "b": "《易·豫卦》释文。郑注:“豫,喜豫说乐之貌也。”"}, {"t": "心中和悦谓之豫。", "b": "《珠丛》"}, {"t": "何问之不豫也?", "b": "《庄子·应帝王》"}, {"t": "夫子若有不豫色然。", "b": "《孟子·公孙丑下》。注:“颜色不悦也。”"}, {"t": "说豫娩泽。", "b": "《荀子·礼论》。注:“豫,乐也。”"}, {"t": "致令皇帝受惊,圣躬不豫,实属罪大恶极。", "b": "《痛史》"}], "words": [{"w": "豫附", "t": "心悦诚服而来归附。"}]}, {"meaning": "安乐;舒服。", "cites": [{"t": "或乃奢侈逸豫,务广第宅。", "b": "《汉书·成帝纪》"}]}, {"meaning": "出游 ,特指皇上秋日出巡。", "cites": [{"t": "度秋豫以收成。", "b": "张衡《东京赋》"}]}, {"meaning": "游乐,嬉戏。", "cites": [{"t": "逸豫可以亡身。", "b": "欧阳修《新五代史》"}], "words": [{"w": "豫怠", "t": "逸乐怠惰。"}]}, {"meaning": "参与。", "cites": [{"t": "豫,与“與”通。", "b": "《正韵》"}, {"t": "楚灵会申,亦来豫盟。", "b": "《后汉书·乐夷传》"}], "words": [{"w": "豫政", "t": "参与政事。"}]}, {"meaning": "", "cites": [{"t": "真像个豫逃兵火的样子。", "b": "《洪秀全演义》"}]}, {"meaning": "预先,事先", "cites": [{"t": "重门击柝,以待暴客,盖取诸豫。", "b": "《易·系辞下》"}], "words": [{"w": "豫先", "t": "预先,早先"}, {"w": "豫言", "t": "预先说尚未发生的事"}, {"w": "豫防", "t": "事先防范"}, {"w": "豫见", "t": "事情还未发生就预先知道"}, {"w": "豫知", "t": "预先知晓。"}]}, {"meaning": "乐意。", "cites": [{"t": "将相和则士豫附。", "b": "班固《汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3314wx','缭','1','liáo','纟','15','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从糸(mì),表示与丝有关尞(liáo)声。本义:缠绕)。"}, {"meaning": "同本义。", "cites": [{"t": "缭,缠也。", "b": "《说文》"}, {"t": "再缭四寸。", "b": "《礼记·玉藻》。疏:“绕也。”"}, {"t": "弗缭。", "b": "《仪礼·乡饮酒礼》。注:“犹紾也。”"}, {"t": "肠纷纭以缭转兮。", "b": "《楚辞·怨思》"}, {"t": "缭之兮杜衡。", "b": "屈原《九歌·湘夫人》"}, {"t": "林麓薮泽陂池连乎蜀汉,缭以周墙,四百余里。", "b": "《后汉书》"}], "words": [{"w": "缭肘", "t": "即“镣ń”。囚禁犯人的脚镣、手铐"}, {"w": "缭绕", "t": "缠绕"}, {"w": "缭纠", "t": "缠绕相连貌。"}]}, {"meaning": "围绕;绕道而行。", "cites": [{"t": "矜纠收缭之属。", "b": "《荀子·议兵》。注:“缭绕,言委曲也。”"}, {"t": "每一门内,四缭连屋。", "b": "《聊斋志异·金和尚》"}], "words": [{"w": "缭曲", "t": "迂回曲折;婉转含蓄"}, {"w": "缭眺", "t": "谓声清而长。"}]}, {"meaning": "祭祀名。", "cites": [{"t": "八月缭祭。", "b": "《周礼·大祝》。司农注:“以手纵持肺本,循之至于末,乃绝以祭也。”"}], "words": [{"w": "缭祭", "t": "周礼九祭之一。祭以左手纵持肺根,右手取肺尖,缭绕使断,取以为祭,故称。"}]}, {"meaning": "假借为“撩”。撩乱,纷乱。", "cites": [{"t": "缭乱边愁听不尽。", "b": "唐·王昌龄《从军行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3315wx','撼','1','hàn','扌','16','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从手,感声。本义:摇动;动摇) 同本义。", "cites": [{"t": "撼,动也。", "b": "《广雅》"}, {"t": "蚍蜉撼大树,可笑不自量。", "b": "韩愈《调张籍》"}, {"t": "撼山易,撼岳家军难。", "b": "《宋史·岳飞传》"}], "words": [{"w": "撼落", "t": "摇落"}, {"w": "撼摇", "t": "摇动,动摇"}, {"w": "撼顿", "t": "摇动,颠踬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3316wx','擂','1','léi lèi','扌','16','','[{"pinyin": "léi", "defs": [{"meaning": "(形声。从手,雷声。(léi)本义:研磨)。"}]}, {"pinyin": "lèi", "defs": [{"meaning": "", "words": [{"w": "打擂", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3317wx','操','1','cāo','扌','16','','[{"pinyin": "cāo", "defs": [{"meaning": "(形声。从手,(sào)声。本义:拿着,握在手里)。"}, {"meaning": "同本义。", "cites": [{"t": "操,把持也。", "b": "《说文》"}, {"t": "操右契。", "b": "《礼记·曲礼》"}, {"t": "不学操缦。", "b": "《礼记·学记》"}, {"t": "盖以操之为巳蹙矣。", "b": "《公羊传·庄公三十年》"}, {"t": "操蛇之神闻之。", "b": "《列子·汤问》"}, {"t": "大王来何操?", "b": "《史记·项羽本纪》"}], "words": [{"w": "可操左券;同室操戈", "t": "兄弟相残或内部纷争"}, {"w": "操刀", "t": "持刀;执刀。"}]}, {"meaning": "引申为掌握。", "cites": [{"t": "操杀生之柄。", "b": "《韩非子·定法》"}], "words": [{"w": "操券", "t": "有把握成功"}, {"w": "操总", "t": "掌握要领。"}]}, {"meaning": "从事。", "cites": [{"t": "邑有成名者,操童子业,久不售。", "b": "《聊斋志异·促织》"}], "words": [{"w": "操职", "t": "任事"}, {"w": "操切从事", "t": "做事急躁。"}]}, {"meaning": "操练。", "cites": [{"t": "操千曲而后晓声。", "b": "《文心雕龙·知音》"}], "words": [{"w": "出操", "t": "出去操练。"}]}, {"meaning": "弹奏。", "cites": [{"t": "(孔明)凭栏而坐,焚香操琴。", "b": "《三国演义》"}], "words": [{"w": "操琴;操鼓;操弦", "t": "弹奏。"}]}, {"meaning": "品行;德行。", "cites": [{"t": "夫何执操之不固。", "b": "《楚辞·谬谏》。注:“志也。”"}, {"t": "虽贾人,有贤操。", "b": "《汉书·张汤传》"}], "words": [{"w": "操尚", "t": "品行志节"}, {"w": "操学", "t": "操行与学问。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3318wx','擅','1','shàn','扌','16','','[{"pinyin": "shàn", "defs": [{"meaning": "(形声。从手,亶(dǎn)声。本义:独揽,专权)。"}, {"meaning": "同本义。", "cites": [{"t": "擅,专也。", "b": "《说文》。按,谓媾壹也。"}, {"t": "权臣擅命也。", "b": "《诗·狡童序》"}, {"t": "擅将其兵。", "b": "《史记·魏豹彭越传》"}, {"t": "今乱世之君臣,区区然皆擅一国之利。", "b": "《商君书·修权》"}], "words": [{"w": "擅恣", "t": "专权放肆"}, {"w": "擅政", "t": "独揽朝政"}, {"w": "擅柄", "t": "独揽权柄"}, {"w": "擅朝", "t": "独揽朝政。"}]}, {"meaning": "占有,据有。", "cites": [{"t": "方五百里,赵独擅之。", "b": "《战国策·秦策》"}], "words": [{"w": "擅宠", "t": "专宠,特受宠信"}, {"w": "擅利", "t": "独占利益"}, {"w": "擅市", "t": "独占市场"}, {"w": "擅夕", "t": "独占宠爱"}, {"w": "擅兵", "t": "掌握兵权"}, {"w": "擅爱", "t": "独占宠爱"}, {"w": "擅声", "t": "享有名声"}, {"w": "擅名", "t": "享有名声。"}]}, {"meaning": "压倒,胜过。", "cites": [{"t": "画手看前辈,吴生远擅场。", "b": "杜甫《冬日洛城》"}], "words": [{"w": "文章擅天下", "t": ""}]}, {"meaning": "善于,专长于。", "cites": [{"t": "文擅彫龙。", "b": "《文选·宣德皇后令》"}], "words": [{"w": "不擅辞令;擅业", "t": "擅长某种学业。"}]}, {"meaning": "让位。", "cites": [{"t": "尧舜擅让,是虚言也。", "b": "《荀子·正论》"}], "words": [{"w": "擅让", "t": "禅让。"}]}, {"meaning": "自作主张;随意。", "cites": [{"t": "擅入他部者,辄收。", "b": "《墨子·号令》"}], "words": [{"w": "擅干", "t": "任意胡行"}, {"w": "擅便", "t": "擅自作主"}, {"w": "擅开", "t": "擅自革除"}, {"w": "擅言", "t": "随便说话"}, {"w": "擅造", "t": "冒昧地拜访。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3319wx','燕','1','yān yàn','灬','16','','[{"pinyin": "yān", "defs": [{"meaning": "古国名。"}, {"meaning": "周代诸侯国名。本作:匽、郾。姬姓;周召公之后,世称北燕,拥有今河北省北部和辽宁省西端,建都蓟(今北京)。战国时成为七雄之一。后灭于秦。", "cites": [{"t": "燕赵韩魏。", "b": "《战国策·齐策》"}, {"t": "欲亡赵走燕。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "燕畏赵。", "b": ""}, {"t": "燕赵之君。", "b": "宋·苏洵《六国论》"}, {"t": "燕赵之收藏,韩魏之经营,齐楚之精英。(互文,收藏、经营、精英均指金玉珍宝。)", "b": "唐·杜牧《阿房宫赋》"}, {"t": "燕地寒,花朝节后,余寒犹厉。(燕,古代燕国,这里指北京地区。)", "b": "明·袁宏道《满井游记》"}]}, {"meaning": "周代诸侯国名。姞姓;开国君主伯倏。在今河南省延津县东北。"}, {"meaning": "五代初,刘守光据幽州(今河北省北部)所建国。", "cites": [{"t": "方其系燕父子以组。", "b": "宋·欧阳修《新五代史·伶官传》"}, {"t": "燕王,吾所立。(燕王,指燕王刘守光的父亲刘仁恭。)", "b": "宋·欧阳修《伶官传序》"}]}, {"meaning": "河北省的别称 。周时为北燕旧地。也指河北省北部。"}, {"meaning": "山名,燕山 ,在河北省和北京市。"}, {"meaning": "姓。"}]}, {"pinyin": "yàn", "defs": [{"meaning": "(象形。甲骨文字形,像燕子形。小篆字形。上像头、嘴,“口”像身体,“北”像两翅,“火”像尾巴。本义:燕子)。"}, {"meaning": "同本义。", "cites": [{"t": "燕燕于飞。", "b": "《诗·邶风·燕燕》"}, {"t": "来降燕乃睇。", "b": "《夏小正》"}, {"t": "燕雁代飞。", "b": "《淮南子·地形》"}, {"t": "燕巢于飞。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "谁家新燕啄春泥。", "b": "唐·白居易《钱塘湖春行》"}, {"t": "归燕略无三月事。", "b": "宋·洪迈《容斋续笔》"}], "words": [{"w": "燕侣莺俦", "t": "比喻夫妻和美"}, {"w": "燕贺", "t": "燕雀相贺。用作新屋落成及升官等喜事的贺词"}, {"w": "燕子", "t": "家燕的通称"}, {"w": "燕户", "t": "燕巢"}, {"w": "燕儿", "t": "雏燕;燕子"}, {"w": "燕尾", "t": "燕子的尾羽"}, {"w": "燕雨", "t": "有燕子绕飞其间的小雨"}, {"w": "燕泥", "t": "燕子筑巢所衔的泥;燕巢上的泥;燕子衔泥筑巢"}, {"w": "燕室", "t": "燕巢。比喻家国"}, {"w": "燕处焚巢", "t": "燕子处在焚烧着的窝里。比喻处境非常危险。"}]}, {"meaning": "白颈鸦。", "cites": [{"t": "燕,白颈鸟。", "b": "《尔雅》"}, {"t": "白项而群飞者谓之燕鸟。", "b": "《小尔雅》。按,大于雅鸟而小于慈鸟。"}]}, {"meaning": "假借为“安”。安逸;安乐。", "cites": [{"t": "虞吉有它不燕。", "b": "《易·中孚》"}, {"t": "燕笑语兮。", "b": "《诗·小雅·蓼萧》"}, {"t": "吉甫燕喜。", "b": "《诗·小雅·六月》"}, {"t": "燕坐于华堂之上。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "燕户", "t": "闲君之室"}, {"w": "燕休", "t": "闲居;休息"}, {"w": "燕令", "t": "帝王退朝闲居时所发的命令"}, {"w": "燕宇", "t": "供休息用的屋宇"}, {"w": "燕安", "t": "安宁太平;心神安定"}, {"w": "燕安鸩毒", "t": "沉溺于安逸享乐,犹如饮毒酒自杀"}, {"w": "燕私", "t": "闲居休息"}, {"w": "燕坐", "t": "安坐;闲坐"}, {"w": "燕居", "t": "退朝而处;闲居"}, {"w": "燕安", "t": "安适满足"}, {"w": "燕祉", "t": "安乐幸福"}, {"w": "燕笑", "t": "犹欢笑"}, {"w": "燕尔新婚", "t": "和谐的新婚"}, {"w": "燕适", "t": "安适"}, {"w": "燕燕", "t": "安适的样子;和乐的样子"}, {"w": "燕誉", "t": "安乐。"}]}, {"meaning": "亵渎;轻慢。", "cites": [{"t": "宋音燕女溺志。", "b": "《礼记·乐志》"}, {"t": "燕朋逆其师。", "b": ""}], "words": [{"w": "燕诬", "t": "信口开河,说话轻慢"}, {"w": "燕朋", "t": "轻慢朋友"}, {"w": "燕辟", "t": "谓轻慢老师为讲解深义而作的浅近比喻"}, {"w": "燕亵", "t": "亲昵猥亵。"}]}, {"meaning": "宴饮;宴请。", "cites": [{"t": "嘉宾式宴以敖。", "b": "《诗·小雅·鹿鸣》"}, {"t": "燕乐之钟磬。", "b": "《仪礼·燕礼》"}, {"t": "则王以息燕。", "b": "《考工记·梓人》"}], "words": [{"w": "燕豆", "t": "古代宴饮时盛食品的器具"}, {"w": "燕狎", "t": "宴饮"}, {"w": "燕客", "t": "宴请宾客"}, {"w": "燕俎", "t": "宴饮。亦宴席。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3320wx','蕾','1','lěi','艹','16','','[{"pinyin": "lěi", "defs": [{"meaning": "(形声。从艸,雷声。本义:含苞未放的花朵) 同本义", "words": [{"w": "花蕾", "t": ""}, {"w": "蓓蕾", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3321wx','薯','1','shǔ','艹','16','','[{"pinyin": "shǔ", "defs": [{"meaning": "薯类作物的统称。", "cites": [{"t": "藷藇,署预也。", "b": "《广雅》。王念孙曰:“今之山药也。根大,故谓之藷藇"}, {"t": "景山,其上多藷藇。", "b": "《北山经》。藷与藇同。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3322wx','薛','1','xuē','艹','16','','[{"pinyin": "xuē", "defs": [{"meaning": "一种草本植物,即“赖蒿”。", "cites": [{"t": "薛、莎、青薠(fán)。", "b": "司马相如《子虚赋》"}]}, {"meaning": "用莎草编制的雨衣。"}, {"meaning": "春秋时国名 。战国时为齐所灭。地在今山东省滕县南。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3323wx','薇','1','wēi','艹','16','','[{"pinyin": "wēi", "defs": [{"meaning": "草名,又名“大巢菜” 。一种一年生或二年生草本植物(Vicia sepium),花紫红色,结寸许长扁荚,中有种子五六粒,可吃。又名“野豌豆”。", "cites": [{"t": "采薇而食之。", "b": "《史记·伯夷传》"}, {"t": "采薇而食者。", "b": "明·顾炎武《复庵记》"}, {"t": "知君秉性甘薇蕨,暇日相思还杖藜。", "b": "方文《访姚若侯山中不值留此》"}], "words": [{"w": "薇藿", "t": "薇,菜名,又名野豌豆;藿为豆叶。指贫者所吃的食物。"}]}, {"meaning": "指蔷薇。", "cites": [{"t": "碧脑浮冰,红薇染露。", "b": "宋·周密《天香》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3324wx','擎','1','qíng','手','16','','[{"pinyin": "qíng", "defs": [{"meaning": "举。", "cites": [{"t": "与翠叶并擎。", "b": "明·李渔《亲情偶寄·种植部》"}], "words": [{"w": "擎赍", "t": "拿着"}, {"w": "擎奇", "t": "举,持"}, {"w": "擎拳", "t": "举拳"}, {"w": "众擎易举", "t": ""}]}, {"meaning": "执持。", "cites": [{"t": "今朝擎剑去,何日刺蛟回?", "b": "李贺《送秦光禄北征诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3325wx','薪','1','xīn','艹','16','','[{"pinyin": "xīn", "defs": [{"meaning": "同本义。", "cites": [{"t": "薪,荛也。", "b": "《说文》"}, {"t": "收秩薪柴。", "b": "《礼记·月令》。注:“大者可析谓之薪。”"}, {"t": "薪蒸材木。", "b": "《周礼·委人》。注:“粗者曰薪,细者曰蒸。”"}, {"t": "以薪以蒸。", "b": "《诗·小雅·无羊》"}, {"t": "农夫得居装而卖其薪荛。", "b": "《管子·轻重甲》"}, {"t": "某有负薪之忧。", "b": "《礼记·曲礼》"}, {"t": "毁伤其薪木。", "b": "《孟子》"}, {"t": "顾野有麦场,场主积薪其中。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "薪火", "t": "柴火"}, {"w": "薪桂", "t": "薪贵于桂。形容柴火昂贵"}, {"w": "薪柴", "t": "柴火"}, {"w": "薪樵", "t": "柴火。"}]}, {"meaning": "可以劈开来用的粗大木柴。", "cites": [{"t": "明足察秋毫之末,而不见舆薪。", "b": "《孟子·梁惠王上》"}, {"t": "卖炭翁,伐薪烧炭南山中。", "b": "唐·白居易《卖炭翁》"}, {"t": "负薪刍助之。", "b": "《资治通鉴·唐纪》"}, {"t": "抱薪救火。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "薪采", "t": "采樵,砍柴"}, {"w": "薪桂", "t": "薪贵于桂。比喻物价昂贵"}, {"w": "薪蒸", "t": "木材"}, {"w": "薪火相传", "t": "木柴虽有烧尽的时候,但火却可以传衍不息。比喻为师徒以道术递相传授不绝,或种族血统及文化精神之绵衍无尽。"}]}, {"meaning": "取以为薪;打柴。", "cites": [{"t": "今遣此力,助汝薪水之劳。", "b": "南朝梁·肖统《陶渊明传》"}], "words": [{"w": "薪采", "t": "打柴"}, {"w": "薪苏", "t": "樵采。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3326wx','薄','1','báo bó bò','艹','16','','[{"pinyin": "báo", "defs": [{"meaning": "土地含养分少,不肥沃的。", "cites": [{"t": "地薄,寡于积聚。", "b": "《史记·货殖列传》"}], "words": [{"w": "土地薄;薄田", "t": "不肥沃的田地。"}]}]}, {"pinyin": "bó", "defs": [{"meaning": "(形声。从芔,溥(pǔ)声。本义:草木丛生处)。"}, {"meaning": "同本义。", "cites": [{"t": "薄,林薄也。", "b": "《说文》"}, {"t": "草丛生为薄。", "b": "《广雅》"}, {"t": "列新雉于林薄。", "b": "《汉书·扬雄传》"}, {"t": "隐于榛薄之中。", "b": "《淮南子·原道》。注:“深草曰薄。”"}, {"t": "露申辛夷,死林薄兮。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "薄草", "t": "丛生之草。"}]}, {"meaning": "养蚕的工具;帘子。", "cites": [{"t": "高门悬薄(帘子)。", "b": "《庄子·达生》"}, {"t": "勃以织曲薄为生。", "b": "《史记·周勃世家》"}, {"t": "薄器不成内。", "b": "《荀子·礼论》。注:“竹苇之器。”"}, {"t": "蚕宫生蚕著薄(养蚕的器具)上。", "b": "《宋书·礼志一》"}], "words": [{"w": "薄曲", "t": "养蚕的器具。多用竹篾或苇篾编制。"}]}, {"meaning": "迫近;接近。", "cites": [{"t": "腥臊并御,芳不得薄兮。", "b": "《楚辞·屈原·涉江》"}, {"t": "雷风相薄。", "b": "《易·说卦》"}, {"t": "外薄四海。", "b": "《书·益稷》"}, {"t": "薄而观之。", "b": "《左传·僖公二十三年》"}, {"t": "今会日薄矣。", "b": "《国语·吴语》"}, {"t": "寒暑未薄而疾。", "b": "《荀子·天论》"}, {"t": "薄暮冥冥,虎啸猿啼。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "薄夜", "t": "薄暮,逼近夜晚。即黄昏"}, {"w": "薄海", "t": "逼近于海,指从京师而至四方的海边。比喻地域的广大"}, {"w": "薄晚", "t": "薄暮,傍晚"}, {"w": "日薄西山;薄海同欢", "t": ""}]}, {"meaning": "搏击;拍;击。", "cites": [{"t": "击之若雷,薄之若风。", "b": "《淮南子·兵略》"}], "words": [{"w": "薄狩", "t": "搏兽;打猎"}, {"w": "薄伐", "t": "讨伐"}, {"w": "薄触", "t": "搏击冲突。"}]}, {"meaning": "减少,减损,减轻。", "cites": [{"t": "薄赋敛,广畜积,以实仓廪。", "b": "汉·晁错《论贵粟疏》"}, {"t": "薄滋味。", "b": "《礼记·月令》"}], "words": [{"w": "薄征", "t": "减轻租税"}, {"w": "薄敛", "t": "减轻赋税"}, {"w": "薄收", "t": "减产,收成不好"}, {"w": "薄刑", "t": "轻刑。"}]}, {"meaning": "轻视,看不起。", "cites": [{"t": "而夫婿乐逸,为婢仆所惑,日以厌薄。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "厚此薄彼;薄慢", "t": "怠慢"}, {"w": "薄情", "t": "不念情义。多用于男女情爱"}, {"w": "薄悻", "t": "薄情;负心"}, {"w": "薄待", "t": "轻视;亏待。"}]}, {"meaning": "侵入;混杂。", "cites": [{"t": "矢溺皆闭其中,与饮食之气相薄。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "停止;依附。", "cites": [{"t": "去乡离家兮徕远客,超逍遥兮今焉薄。", "b": "《楚辞·宋王·九辩》"}, {"t": "凌阳侯之泛滥兮,忽翱翔之焉薄。", "b": "《楚辞·屈原·哀郢》"}, {"t": "心憧憧若涉大川,遭风而未薄。", "b": "《盐铁论·刺复》"}]}, {"meaning": "物体扁平,与“厚”相对。", "cites": [{"t": "战战兢兢,如临深渊,如履薄冰。", "b": "《诗·小雅》"}, {"t": "或厚或薄。", "b": "《荀子·富国》"}, {"t": "太古薄葬,棺厚三尺,衣衾三领。", "b": "《荀子·正论》"}]}, {"meaning": "引申为微小,少。", "cites": [{"t": "德薄而位尊…", "b": "《易·系辞》"}, {"t": "事力劳而供奉薄。", "b": "《韩非子·五蠹》"}], "words": [{"w": "薄仪", "t": "微少的礼物"}, {"w": "薄具", "t": "略微具备"}, {"w": "薄艺", "t": "小技能"}, {"w": "薄寒", "t": "微寒。"}]}, {"meaning": "不浓;淡薄。", "cites": [{"t": "莫辞酒味薄。", "b": "杜甫《羌村》"}, {"t": "贵贱情何薄。", "b": "《孔雀东南飞》"}], "words": [{"w": "薄妆", "t": "薄面。淡妆"}, {"w": "薄蚀", "t": "日月掩食而无光"}, {"w": "薄眉", "t": "淡扫蛾眉,用浅黛画的眉毛。"}]}, {"meaning": "指人心、世道、纲纪等衰微轻薄;不庄重。", "cites": [{"t": "为人薄行,有俊才。", "b": "刘义庆《世说新语·文学》"}], "words": [{"w": "薄德", "t": "菲德,道德不厚;缺德"}, {"w": "薄相", "t": "轻薄之相。有捉弄、玩弄的意思。"}]}, {"meaning": "虚假刻薄,不厚道。", "cites": [{"t": "商君,其天资刻薄人也。", "b": "《史记·商君传》"}], "words": [{"w": "薄夫", "t": "刻薄的人"}, {"w": "薄心肠", "t": "言待人寡恩无义。"}]}]}, {"pinyin": "bò", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3327wx','颠','1','diān','页','16','','[{"pinyin": "diān", "defs": [{"meaning": "(形声。从页(xié),真声。本义:头顶)。"}, {"meaning": "同本义。", "cites": [{"t": "颠,顶也。", "b": "《说文》"}, {"t": "班序颠毛。", "b": "《国语·齐语》"}, {"t": "诲于华颠胡老。", "b": "《后汉书·蔡邕传》"}], "words": [{"w": "颠毛", "t": "头发"}, {"w": "颠顶", "t": "头顶"}, {"w": "颠童", "t": "形容老人头发稀少。"}]}, {"meaning": "泛指物体的顶部。", "words": [{"w": "颠日", "t": "天日,天空的太阳"}, {"w": "颠杪", "t": "顶端末梢"}, {"w": "颠委", "t": "指水的上源和下游。"}]}, {"meaning": "马的额头。", "cites": [{"t": "有车邻邻,有马白颠。", "b": "《诗·秦风·车邻》"}]}, {"meaning": "本,始。", "cites": [{"t": "聊书其颠委以为之记。", "b": "清·王士祯《西城别墅记》"}]}, {"meaning": "古县名 。指滇池县,西汉置。治所在今云南省晋宁县东。两汉为益州郡治所。"}, {"meaning": "“颠”假借为“蹎”。仆倒,倒下。", "cites": [{"t": "人亦有言,颠沛之揭。", "b": "《诗·大雅·荡》"}, {"t": "颠越不恭。", "b": "《书·盘庚中》"}, {"t": "造次必如是,颠沛必于是。", "b": "《论语·里仁》"}, {"t": "危而不持,颠而不扶。", "b": "《论语·季氏》"}, {"t": "杜回踬而颠。", "b": "《左传·宣公十五年》"}], "words": [{"w": "颠踬", "t": "被东西绊倒。比喻坎坷不顺利"}, {"w": "颠不刺", "t": "颠倒;风流"}, {"w": "颠头播脑", "t": "摇头晃脑。形容得意的样子。"}]}, {"meaning": "上下倒置。", "cites": [{"t": "颠之倒之。", "b": "《诗·齐风·东方未明》"}]}, {"meaning": "又。", "cites": [{"t": "倒之颠之。", "b": ""}], "words": [{"w": "颠蹶", "t": "颠倒失次"}, {"w": "颠错", "t": "颠倒错乱"}, {"w": "颠趾", "t": "颠倒失所。"}]}, {"meaning": "疯狂,发疯,发狂", "cites": [{"t": "闻客语声知贵贱,持花歌咏似狂颠。", "b": "唐·张籍《罗道士》"}], "words": [{"w": "颠狂", "t": "木指精神失常,引申为放荡不羁"}, {"w": "颠劣", "t": "颠狂顽劣。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3328wx','翰','1','hàn','羽','16','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从羽,倝(gàn)声。本义:天鸡,也叫锦鸡或山鸡)。"}, {"meaning": "同本义。", "cites": [{"t": "翰,天鸡,赤羽也。", "b": "《说文》"}, {"t": "蜀人以文翰;文翰者,若皋鸡。", "b": "《逸周书·王会》"}], "words": [{"w": "翰音", "t": "鸟的叫声上达于天,而鸟仍旧在地。比喻居非其位而声过其实。"}]}, {"meaning": "长而硬的鸟羽。", "cites": [{"t": "鸡曰翰音。", "b": "《礼记·曲礼》。注:“犹长也。”按,鸟羽之长而劲者为翰,高飞持之,亦所以卫体。"}], "words": [{"w": "翰毛", "t": "羽毛"}, {"w": "翰翮", "t": "犹羽翼。"}]}, {"meaning": "长毛。", "cites": [{"t": "犬色更赤,有长翰。", "b": "汉·刘向《列仙传》"}, {"t": "故藉翰林以为主人。", "b": "《文选·扬雄·长杨赋》。李善注引《说文》曰:“长老者曰翰。”"}]}, {"meaning": "(gàn)。草木的茎干,引申为骨干,维护者,支持者。", "cites": [{"t": "之屏之翰,百辟为害。", "b": "《诗·小雅·桑扈》"}, {"t": "四方攸同,王后维翰。", "b": "《诗·大雅·文王有声》"}, {"t": "大邦维屏,大宗维翰。", "b": "《诗·大雅·板》"}]}, {"meaning": "高飞。", "cites": [{"t": "王旅啴啴,如飞如翰。", "b": "《诗·大雅·常武》"}], "words": [{"w": "翰飞", "t": "高飞"}, {"w": "翰登", "t": "以虚声而登高位。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3329wx','噩','1','è','口','16','','[{"pinyin": "è", "defs": [{"meaning": "惊愕", "words": [{"w": "噩迕", "t": "惊遇"}, {"w": "噩异", "t": "惊异"}]}, {"meaning": "凶恶", "words": [{"w": "噩神", "t": "凶神"}]}, {"meaning": "严肃;严正", "words": [{"w": "噩噩", "t": "严肃切直"}, {"w": "噩厉", "t": "严肃,严厉"}]}, {"meaning": "淳朴", "words": [{"w": "噩噩", "t": "谔谔,正言谏诤貌"}, {"w": "噩噩浑浑", "t": "质朴忠厚"}]}, {"meaning": "肥腴貌", "words": [{"w": "噩噩", "t": "肥腴貌"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3330wx','橱','1','chú','木','16','','[{"pinyin": "chú", "defs": [{"meaning": "(形声。从木,厨声。本义: 放置东西的家具)同本义", "words": [{"w": "橱子", "t": "放置衣物的柜子"}, {"w": "橱簏", "t": "指装书用的橱箱"}, {"w": "衣橱", "t": ""}, {"w": "碗橱儿", "t": ""}, {"w": "壁橱", "t": ""}, {"w": "书橱", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3331wx','橙','1','chéng','木','16','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从木,登声。本义:果树名,果实叫橙子)。"}, {"meaning": "同本义 。常绿乔木,叶子椭圆形,果实叫橙子,球形、皮黄赤色、味甜,皮可入药。"}, {"meaning": "橙色 ,红和黄之间的颜色。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3332wx','橘','1','jú','木','16','','[{"pinyin": "jú", "defs": [{"meaning": "(形声。 从木, 矞(yù)声。 本义: 橘树。果实也称“橘”) 同本义  几种球形或近球形的热带或亚热带产的果实之一, 实际上是浆果, 有微红黄色的革质芳香果皮,含有许多油腺, 广泛应用在糖果、 点心、 蜜饯和烹调方面, 通常有甜味或酸味, 多汁可食的果肉含矿物质和维生素C。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3333wx','整','1','zhěng','攵','16','','[{"pinyin": "zhěng", "defs": [{"meaning": "(会意兼形声。从攴(pū)从束从正,正亦声。攴是敲打,束是约束,使之归于正。合起来表示整齐。本义:整齐)。"}, {"meaning": "同本义。", "cites": [{"t": "整,齐也。", "b": "《说文》"}, {"t": "整设于屏外。", "b": "《礼记·月令》。注:“整,正列也。”"}, {"t": "以乱易整,不武。", "b": "《左传·僖公三十年》"}], "words": [{"w": "整娖", "t": "整齐,条理分明"}, {"w": "整立", "t": "整齐地矗立"}, {"w": "整扮", "t": "打扮整齐"}, {"w": "整设", "t": "整齐阵列"}, {"w": "整蔚", "t": "整齐而华丽。"}]}, {"meaning": "端正,端庄。", "cites": [{"t": "王夷甫容貌整丽,妙于谈玄。", "b": "《世说新语》"}], "words": [{"w": "整心", "t": "正心,端正思想"}, {"w": "整秀", "t": "端庄俊秀"}, {"w": "整身", "t": "身体端正,穿戴整齐"}, {"w": "整美", "t": "端正美好。"}]}, {"meaning": "整个;完整;全部在内。", "cites": [{"t": "小姐越发闷上加闷,整日眉头不展。", "b": "《儒林外史》"}], "words": [{"w": "十二点整;整夜不眠;整年;整月;整一", "t": "统一。"}]}, {"meaning": "整理;整治。", "cites": [{"t": "整法度。(整顿法令制度。)", "b": "《后汉书·张衡传》"}, {"t": "整羁鞘。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "整旅", "t": "整顿军队"}, {"w": "整比", "t": "整理排比"}, {"w": "整弁", "t": "整冠"}, {"w": "整休", "t": "一面整顿,一面休息"}, {"w": "整次", "t": "整理编次"}, {"w": "整抖", "t": "整理"}, {"w": "整束", "t": "整理收拾"}, {"w": "整兵", "t": "整饬军队。"}]}, {"meaning": "修补,修理。", "cites": [{"t": "庆基殿如的有损漏,只令三司差官整补,不得理为劳绩。", "b": "宋·欧阳修《论罢修奉先寺等状》"}], "words": [{"w": "整刷", "t": "整治刷新"}, {"w": "整拾", "t": "整修,收拾。"}]}, {"meaning": "准备。", "cites": [{"t": "到那日,也少不的要整两席齐整酒席,…你与我料理料理。", "b": "《金瓶梅》"}], "words": [{"w": "整制", "t": "备办;操办"}, {"w": "整驾", "t": "备好车马,准备出发。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3334wx','融','1','róng','虫','16','','[{"pinyin": "róng", "defs": [{"meaning": "(形声。从鬲,虫省声。鬲(lì),古代一种烹饪器,与鼎相似。本义:炊气上升)。"}, {"meaning": "同本义。", "cites": [{"t": "融融者皆趣热之士,其得炉冶之门者,惟夹炭之子。", "b": "《晋书》"}]}, {"meaning": "融化;消溶。", "cites": [{"t": "融而为川渎。", "b": "孙绰《游天台山赋》"}], "words": [{"w": "融流", "t": "融化流动"}, {"w": "融陶", "t": "熔化陶冶"}, {"w": "融液", "t": "融化成液体"}, {"w": "融释", "t": "消失;化解"}, {"w": "融蚀", "t": "消磨;侵蚀"}, {"w": "融炼", "t": "熔化锤炼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3335wx','瓢','1','piáo','瓜','16','','[{"pinyin": "piáo", "defs": [{"meaning": "瓠的一种。也称“葫芦”。", "cites": [{"t": "瓢,蠡也。从瓠省,票声。", "b": "《说文》"}, {"t": "瓢,瓠勺也。", "b": "《三苍》"}, {"t": "一瓢饮。", "b": "《论语》"}], "words": [{"w": "瓢冠", "t": "瓜瓢形的僧帽"}, {"w": "瓢堂", "t": "简陋的堂室。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3336wx','醒','1','xǐng','酉','16','','[{"pinyin": "xǐng", "defs": [{"meaning": "(形声。从酉,星声。酉(yǒu)与酒有关。本义:酒醒)。"}, {"meaning": "同本义。", "cites": [{"t": "醒能述以文。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "今宵酒醒何处。", "b": "宋·柳永《雨霖铃》"}], "words": [{"w": "醒酒石", "t": "可以醒酒的石头"}, {"w": "醒酒汤", "t": "可以醒酒的羹汤"}, {"w": "醒药", "t": "醒酒的药"}, {"w": "醒狂", "t": "不醉而狂。"}]}, {"meaning": "睡眠状态结束或尚未睡着。", "cites": [{"t": "既而儿醒。", "b": "《虞初新志·秋声诗自序》"}, {"t": "夫亦醒。", "b": ""}, {"t": "大儿醒。", "b": ""}, {"t": "大儿初醒声。", "b": ""}], "words": [{"w": "醒睡", "t": "睡眠中保持警觉,不沉睡"}, {"w": "醒困", "t": "消除困倦"}, {"w": "醒松", "t": "惺松。刚苏醒的样子"}, {"w": "醒觉", "t": "由睡眠或昏迷而苏醒。"}]}, {"meaning": "消除。", "cites": [{"t": "等她气醒了,再回家来。", "b": "周立波《山乡巨变》"}]}, {"meaning": "用同“擤”。", "cites": [{"t": "摸出手帕醒鼻涕。", "b": "巴金《电》"}], "words": [{"w": "醒鼻涕", "t": "擤鼻涕。"}]}, {"meaning": "明白;明显。", "cites": [{"t": "童奶奶道:“这话我不醒的。”", "b": "《醒世姻缘传》"}], "words": [{"w": "醒醒白白", "t": "明明白白"}, {"w": "醒豁", "t": "清醒,明白"}, {"w": "醒眼", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3337wx','霍','1','huò','雨','16','','[{"pinyin": "huò", "defs": [{"meaning": "(会意。从雨。俗省作“霍”。本义:鸟疾飞时发出的声音。后描述门、水等响声)同本义。", "cites": [{"t": "靃,飞声也。雨而双飞者,其声靃然。", "b": "《说文》"}, {"t": "磨刀霍霍向猪羊。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "霍落", "t": "象声词"}, {"w": "霍濩", "t": "水流声"}, {"w": "霍嚓", "t": "象声词。"}]}, {"meaning": "引申为疾速。", "cites": [{"t": "霍然病已。", "b": "枚乘《七发》"}, {"t": "翕赫脗霍。", "b": "扬雄《甘泉赋》"}], "words": [{"w": "霍奕", "t": "奔驰的样子"}, {"w": "霍绎", "t": "形容急速分散飞走"}, {"w": "霍霍眨眨", "t": "闪闪烁烁"}, {"w": "霍脗", "t": "疾速的样子。"}]}, {"meaning": "大山围绕着小山之称。", "cites": [{"t": "大山宫小山,霍。", "b": "《尔雅》。郭璞注:“宫,谓围绕之。”"}]}, {"meaning": "霍乱,即中医上泛指具有剧烈吐泻、腹痛等症的急性胃肠病。", "cites": [{"t": "仲氏又发霍,洞下忽焉甚。", "b": "梅尧臣诗"}]}, {"meaning": "山名。"}, {"meaning": "在河南省临汝县西南30公里。"}, {"meaning": "在安徽省霍山县。"}, {"meaning": "即衡山,在湖南省衡山县西。"}, {"meaning": "古国名 。周武王弟叔处的封地,故城在今山西省霍县西南。"}, {"meaning": "豆叶,嫩时可食。", "cites": [{"t": "使奴从宾客,将酒霍肉。", "b": "《汉书·鲍宣传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3338wx','霎','1','shà','雨','16','','[{"pinyin": "shà", "defs": [{"meaning": "(从雨,妾声。本义:小雨)。"}, {"meaning": "同本义。"}, {"meaning": "很短时间;瞬间。", "cites": [{"t": "小街上霎时间沉寂起来。", "b": "《梁生宝买稻种》"}], "words": [{"w": "霎那间", "t": "片刻间"}, {"w": "霎时间", "t": "极短时间。"}]}, {"meaning": "用同“闸”。水闸。", "cites": [{"t": "泾水内旧有石霎,以堰水入白渠溉田。", "b": "清·顾炎武《天下郡国利病书》"}]}, {"meaning": "用同“眨”。眼睛闭上又立刻睁开。", "cites": [{"t": "像对着我们霎眼。", "b": "刘复《敲冰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3339wx','辙','1','zhé','车','16','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。从车,徹(chè)省声。本义:车迹,车轮碾过的痕迹)。"}, {"meaning": "同本义。", "cites": [{"t": "下,视其辙;登,轼而望之。", "b": "《左传·庄公十年》"}, {"t": "晓驾炭车辗冰辙。", "b": "《卖炭翁》"}]}, {"meaning": "车子。", "cites": [{"t": "会使辙交驰,北邀当国去相见。", "b": "文天祥《指南录后序》"}], "words": [{"w": "辙印", "t": "车子行驶的痕迹"}, {"w": "辙迹", "t": "车子行驶的痕迹。"}]}, {"meaning": "道路。", "cites": [{"t": "欲驾巾车归去,有豺狼当辙。", "b": "宋·胡铨《好事近》"}], "words": [{"w": "辙轨", "t": "轨道。"}]}, {"meaning": "途径;门路;路数,路子。", "cites": [{"t": "总会旧辙,创立新意。", "b": "隋·潘徽《韵纂序》"}], "words": [{"w": "没辙", "t": "没有办法。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3340wx','冀','1','jì','八','16','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从北,异(yì)声。本义:冀州。古九州之一)。"}, {"meaning": "同本义。", "cites": [{"t": "冀,北方州也。", "b": "《说文》"}, {"t": "两河间曰冀州。", "b": "《尔雅·释地》"}, {"t": "河内曰冀州。", "b": "《周礼·职方氏》。朱骏声曰:“地亘今盛京直隶山西、河南各府州,淮南地形,正中冀州,曰中土。”"}, {"t": "惟彼陶唐,有此冀方。", "b": "《书·五子之歌》。孔传:“陶唐帝尧氏,都冀州,统天下四方。”"}]}, {"meaning": "古代国名。在今山西省河津县东北。"}, {"meaning": "河北省的简称。"}, {"meaning": "假借为“觊”。希望,期望。", "cites": [{"t": "吾冀而朝夕修我。", "b": "《国语·鲁语》"}, {"t": "冀至珠庭焉。", "b": "《史记·孝武纪》"}, {"t": "释其耒而守株,冀复得兔。", "b": "《韩非子·五蠹》"}, {"t": "冀三横唯余其一。", "b": "《世说新语·自新》"}, {"t": "冀君实或见恕。", "b": "宋·王安石《答司马谏议书》"}, {"t": "冀缓急或可救。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "冀其成功;希冀;冀图、冀愿", "t": "希图;希望;企望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3341wx','餐','1','cān','飠','16','','[{"pinyin": "cān", "defs": [{"meaning": "(形声。从食,(cán)声。本义:吃)。"}, {"meaning": "同本义。", "cites": [{"t": "餐,吞也。", "b": "《说文》"}, {"t": "餐,食也。", "b": "《广雅》"}, {"t": "相谒而餐。", "b": "《方言一》。注:“昼饭为餐,晚饭为飧。”"}, {"t": "彼君子兮,不素餐兮。", "b": "《诗·魏风·伐檀》"}, {"t": "列侯幸得赐餐钱奉邑。", "b": "《汉书·高帝纪》"}], "words": [{"w": "进餐;会餐;野餐;就餐;聚餐;餐玉", "t": "吞食玉屑。古时认为服食玉屑可以延寿。"}]}, {"meaning": "吞食。", "cites": [{"t": "此甘餐毒药,戏猛兽之爪牙也。", "b": "汉·枚乘《七发》"}]}, {"meaning": "饮食,食物。", "cites": [{"t": "令其裨将传餐。", "b": "《汉书·韩信传》"}, {"t": "以一壶餐得士二人。", "b": "《战国策·中山策》"}], "words": [{"w": "餐卫", "t": "指饮食调养"}, {"w": "早中晚三餐;素餐;中餐;西餐;夜餐", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3342wx','嘴','1','zuǐ','口','16','','[{"pinyin": "zuǐ", "defs": [{"meaning": "(嘴,本作觜。嘴是后起的累增字。形声。从口,觜(zuǐ)声。本义:同“觜”。猫头鹰之类头上的毛角)。"}, {"meaning": "同本义。", "cites": [{"t": "觜,鸱旧头上角觜。或作嘴。", "b": "《集韵》"}]}, {"meaning": "鸟嘴。", "cites": [{"t": "(二郎)又变了一只朱绣顶的灰鹤,伸着一个长嘴,与一把尖头铁钳子相似,径来吃这水蛇。", "b": "《西游记》"}]}, {"meaning": "中古时期,嘴引申指人或动物的口腔器官。", "cites": [{"t": "有一鱼,可长丈余,粗细大于臂…嘴尖,状如鲟鱼。", "b": "唐·王度《古镜记》"}, {"t": "他嘴头子又来得,左话右转,右话左转,翻蛆搭舌头的侪是他说话分。", "b": "《何典》"}], "words": [{"w": "嘴片子", "t": "嘴皮子。嘴唇"}, {"w": "嘴瓜", "t": "嘴部附近的部位"}, {"w": "嘴皮", "t": "嘴唇"}, {"w": "嘴壳子", "t": "指鸟喙"}, {"w": "嘴犄角", "t": "嘴角"}, {"w": "嘴筒", "t": "嘴巴"}, {"w": "嘴卢都", "t": "撅着嘴,鼓着嘴。"}]}, {"meaning": "从鸟嘴外形突出引申出表示物体的突出部分。", "cites": [{"t": "两盘一山嘴,转出东南。", "b": "《徐霞客游记·粤西游日记》"}], "words": [{"w": "山嘴;瓶嘴;茶壶嘴", "t": ""}]}, {"meaning": "说话。", "cites": [{"t": "要你们去献殷勤塌嘴?", "b": "《西游记》"}, {"t": "真真这凤丫头越发贫嘴了。", "b": "《红楼梦》"}], "words": [{"w": "嘴喳喳", "t": "多嘴"}, {"w": "嘴花捩撇", "t": "能说会道"}, {"w": "嘴巴巴的", "t": "叽叽喳喳的"}, {"w": "嘴舌", "t": "口舌争执"}, {"w": "嘴打人", "t": "话说得生硬,厉害,刺伤人"}, {"w": "嘴呐", "t": "说话吞吞吐吐"}, {"w": "嘴抹儿", "t": "指口才,说话的能力"}, {"w": "嘴骨弄", "t": "多言多语"}, {"w": "嘴强", "t": "能说会道"}, {"w": "嘴钝", "t": "话说迟钝;不善言辞"}, {"w": "嘴短", "t": "形容话说不响"}, {"w": "嘴清舌白", "t": "话说得明确清楚"}, {"w": "嘴甜心苦", "t": "出言和善而居心狠毒"}, {"w": "嘴痒", "t": "一有说话的机会就要说,不说觉得不痛快。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3343wx','踱','1','duó','足','16','','[{"pinyin": "duó", "defs": [{"meaning": "慢步行走。", "cites": [{"t": "鲁智深离了僧房,信步踱出山门外。", "b": "《水浒全传》"}], "words": [{"w": "踱来踱去;踱方步;踱走", "t": "踱步,走慢步,慢步走。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3344wx','蹄','1','tí','足','16','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从足,ń声。本义:牛、马、猪、羊等有蹄类哺乳动物足趾前部的典型角质覆盖物,以将趾的末端几乎全部包裹住,又指有角质保护物的脚)。"}, {"meaning": "同本义。", "cites": [{"t": "马候蹄。", "b": "《谷梁传·昭公八年》。释文:“蹄,马足也。”"}, {"t": "马蹄可以践霜雪。", "b": "《庄子·马蹄》"}, {"t": "驴不胜怒蹄之。(蹄,用如动词:踢。)", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "牛蹄;马蹄;猪蹄;蹄涔", "t": "留有牛马脚迹的小池塘"}, {"w": "蹄洼", "t": "留有蹄迹的小水塘"}, {"w": "蹄道", "t": "有着兽蹄鸟迹的走道"}, {"w": "蹄蚤", "t": "蹄趾与脚爪"}, {"w": "蹄书", "t": "诏令;诏书。因用赫蹄纸书写,故称。"}]}, {"meaning": "指牲口 。", "words": [{"w": "蹄尾", "t": "泛指禽兽"}, {"w": "蹄腿", "t": "牲畜的腿部"}, {"w": "蹄躈", "t": "古时用以计算牲畜的头数。"}]}, {"meaning": "兔网,捕兔的工具。", "cites": [{"t": "蹄者所以在兔,得兔而忘蹄。", "b": "《庄子·外物》"}], "words": [{"w": "蹄筌", "t": "蹄和筌。蹄是捕兔器,筌是捕鱼器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3345wx','蹂','1','róu','足','16','','[{"pinyin": "róu", "defs": [{"meaning": "(形声。从足,柔声。本义:践踏)。"}, {"meaning": "同本义。", "cites": [{"t": "蹂,履也。", "b": "《广雅》"}, {"t": "蹂,蹂践,蹋也。", "b": "《玉篇》"}, {"t": "余骑相蹂践争项王。", "b": "《史记·项羽本纪》"}], "words": [{"w": "蹂若", "t": "蹂践、蹂蹈、践踏"}, {"w": "蹂蹈", "t": "践踏"}, {"w": "蹂踏", "t": "犹踩踏"}, {"w": "蹂抑", "t": "践踏压制"}, {"w": "蹂促", "t": "犹践踏。"}]}, {"meaning": "欺压、侵凌;侵袭。", "cites": [{"t": "蹂强翼弱,名四驰也。", "b": "戴良《李促宾像赞》"}], "words": [{"w": "蹂藉", "t": "侵害;侵扰"}, {"w": "蹂剔", "t": "侵害。"}]}, {"meaning": "揉擦", "cites": [{"t": "或簸或蹂。", "b": "《诗·大雅·生民》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3346wx','蟆','1','má','虫','16','','[{"pinyin": "má", "defs": [{"meaning": "蛤蟆", "cites": [{"t": "旁一蟆。", "b": "《聊斋志异·促织》"}], "words": [{"w": "蟆入草间", "t": ""}, {"w": "蟆更", "t": "虾蟆更的简称"}, {"w": "蟆蝈", "t": "方言。即青蛙"}, {"w": "蟆衣草", "t": "车前草的别名"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3347wx','螃','1','páng','虫','16','','[{"pinyin": "páng", "defs": [{"meaning": "蟹的俗称。海洋食肉性、具粗状宽大之甲壳类的任一种。", "cites": [{"t": "时值香橙螃蟹月，景当新酒菊花天。--明·徐元《八义记》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3348wx','器','1','qì','口','16','','[{"pinyin": "qì", "defs": [{"meaning": "(会意。从犬。《说文》:“象器之口,犬所以守之。”器物很多,用狗看守。本义:器具)。"}, {"meaning": "同本义。", "cites": [{"t": "器,皿也。", "b": "《说文》。段注:“器乃凡器统称。”"}, {"t": "天下神器。", "b": "《老子》"}, {"t": "形乃谓之器。", "b": "《易·系辞》"}, {"t": "物周为器。", "b": "《周书·宝典》"}, {"t": "其贡器物。", "b": "《周礼·大行人》"}, {"t": "夫冰炭不同器而久。", "b": "《韩非子·显学》"}, {"t": "作为食器。斩山木而财之。", "b": "《韩非子·十过》"}, {"t": "守圉之器。", "b": "《墨子·公输》"}, {"t": "肖于器邪。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "盆器倾侧。", "b": "《虞初新志·秋声诗自序》"}, {"t": "尽一器。", "b": "清·周容《芋老人传》"}, {"t": "器贡(宗庙的器具。九贡之一);器车(器指银瓮丹甑等,车指山车之类。都在太平盛世出现,故象征祥瑞);器小(容器狭小)器备(器物,器具)", "b": ""}]}, {"meaning": "才能。", "cites": [{"t": "庙堂之器。", "b": "明·刘基《卖柑者言》"}, {"t": "器能(器量才能);器分(人所具有的资质和才能);器志(才识和志向);器尚(才具,节操)", "b": ""}]}, {"meaning": "人才。", "cites": [{"t": "大器晚成。", "b": "《老子》"}, {"t": "先自治而后治人之称大器。", "b": "《法言·先知》"}]}, {"meaning": "重视。", "cites": [{"t": "先主器之", "b": "《三国志·诸葛亮传》"}, {"t": "朝廷器之。", "b": "《后汉书》"}, {"t": "器任(重视任用);器待(谓器重而礼遇之);器爱(器重而爱护);器遇(器重而厚待)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3349wx','噪','1','zào','口','16','','[{"pinyin": "zào", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "words": [{"w": "噪呤", "t": "鸣叫"}, {"w": "噪天", "t": "鸟名。即云雀。"}]}, {"meaning": "大声喧嚷。", "cites": [{"t": "以毁谤言之,贞良见妒,高奇见噪。", "b": "汉·王充《论衡》"}], "words": [{"w": "噪逐", "t": "叫骂驱逐"}, {"w": "噪儿巴喝", "t": "方言。哇啦哇啦乱嚷"}, {"w": "噪呼", "t": "喧哗叫嚷"}, {"w": "噪喧", "t": "喧闹"}, {"w": "噪刺刺", "t": "沸沸扬扬"}, {"w": "噪嘴", "t": "多嘴"}, {"w": "噪噪", "t": "乱嚷嚷;议论纷纷"}, {"w": "噪噪切切", "t": "弦乐器大弦和小弦发出不同的声音。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3350wx','鹦','1','yīng','鸟','16','','[{"pinyin": "yīng", "defs": [{"meaning": "鸟名,鹦鹉。俗称“鹦哥”。", "cites": [{"t": "雨细花零鹦语切,愁肠千万结。", "b": "前蜀·魏承班《谒金门》"}], "words": [{"w": "鹦哥帻", "t": "色彩红似鹦哥嘴的头巾"}, {"w": "鹦舌", "t": "鹦鹉之舌。比喻伶牙利齿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3351wx','赠','1','zèng','贝','16','','[{"pinyin": "zèng", "defs": [{"meaning": "(形声。从贝,曾声。从贝,表示与财富有关。本义:赠送)。"}, {"meaning": "同本义。", "cites": [{"t": "赠,玩好相送也。", "b": "《说文》"}, {"t": "何以赠之。", "b": "《诗·秦风·渭阳》"}, {"t": "凡赠币无常。", "b": "《仪礼·既夕礼》。注:“玩好曰赠。”"}, {"t": "赠禭所以送死也。", "b": "《荀子·大略》"}, {"t": "以公命赠孟明。", "b": "《左传·僖公三十三年》"}, {"t": "赠大珠四枚。", "b": "《汉书·李广苏建传》"}, {"t": "歌以赠之。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "赠谥美显。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "赠赆", "t": "赠送给远行人的路费"}, {"w": "赠仪", "t": "赠送的礼物"}, {"w": "赠策", "t": "赠物以表示心意"}, {"w": "赠诗", "t": "互相酬答"}, {"w": "赠我药石", "t": "比喻感谢别人以忠言规劝自己"}, {"w": "转赠", "t": "把收到的礼物赠送给别人"}, {"w": "捐赠", "t": "馈赠。赠送。"}]}, {"meaning": "送走;逐去。", "cites": [{"t": "以赠恶梦。", "b": "《周礼·春官·占梦》"}], "words": [{"w": "赠恨", "t": "向人诉说别离的遗憾心情"}, {"w": "赠傩", "t": "古代送走疫鬼的一种仪式。"}]}, {"meaning": "追赠,赐死者以官爵或荣誉称号。", "cites": [{"t": "子熙卒,遗戒不求赠谥。", "b": "《魏书·韩子熙传》"}, {"t": "步夫人卒,追赠皇后。", "b": "《三国志·吴主传》"}, {"t": "赠太子太保。", "b": "《明史》"}], "words": [{"w": "赠谥", "t": "帝王和大臣死后,依其生前功绩赐赠称号"}, {"w": "赠公", "t": "帝王时代称官员已死的父亲为赠公"}, {"w": "追赠", "t": "在人死后授予某种称号"}, {"w": "赠官", "t": "古代朝廷对功臣的先人或本人死后追封爵位官职"}, {"w": "赠典", "t": "古代朝廷推恩重臣,把官爵授给官员已死父母及祖先的典礼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3352wx','默','1','mò','黑','16','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从犬,黑声。本义:狗突然窜出追人)。"}, {"meaning": "闭口不说话。", "cites": [{"t": "恭默思道。", "b": "《书·说命》"}, {"t": "默而识之。", "b": "《论语》"}, {"t": "或默或语。", "b": "《易·系辞》"}, {"t": "三年默以思道。", "b": "《国语·楚语》"}, {"t": "我不欲战而能默。", "b": "《左传·昭公十五年》"}, {"t": "默坐低双眉。", "b": "白居易《移家入新宅》"}], "words": [{"w": "默然不语", "t": "静默而不作声"}, {"w": "默默无言", "t": "沉默不语。"}]}, {"meaning": "幽静。", "cites": [{"t": "默顺风以偃仰兮。", "b": "《楚辞·惜贤》。注:“寂也。”"}]}, {"meaning": "不廉洁,贪污。", "cites": [{"t": "贪以败官为默,杀人不忌为贼。", "b": "《孔子家语·正论》"}]}, {"meaning": "冒,涌。", "cites": [{"t": "宋江听罢愕然,默上心来,便道:“你既有这个活佛罗汉在彼,何不早说,与俺等同去参礼,求问前程。”", "b": "《水浒传》"}]}, {"meaning": "私下; 暗中。", "cites": [{"t": "故能默契如此。", "b": "朱弁《曲洧旧闻》"}], "words": [{"w": "默化", "t": "于无形之中感化"}, {"w": "默存", "t": "指形体不动而神游。后用为遇事默记之意"}, {"w": "默识", "t": "领悟暗记在心中。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3353wx','黔','1','qián','黑','16','','[{"pinyin": "qián", "defs": [{"meaning": "(形声。从黑,今声。本义:黑色) 同本义。", "cites": [{"t": "黔,黎也。从黑,今声。秦谓民为黔首,谓黑发也,同谓之黎民。", "b": "《说文》"}, {"t": "以为黔首则。", "b": "《礼记·祭义》"}, {"t": "邑中之黔。", "b": "《左传·襄公十六年》"}], "words": [{"w": "黔口", "t": "黑嘴巴"}, {"w": "黔黑", "t": "深黑"}, {"w": "黔丑", "t": "污黑丑陋。"}]}, {"meaning": "晒黑,染黑,熏黑。", "cites": [{"t": "乌不日黔而黑。", "b": "《庄子·天运》"}, {"t": "或黔其庐。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "黔突", "t": "本指烟囱熏黑,也用以称烟囱"}, {"w": "黔突暖席", "t": "烟囱变黑,坐席变为温暖。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3354wx','镜','1','jìng','钅','16','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从金,竟声。本义:照形取影的器具)。"}, {"meaning": "同本义  古镜以铜或铁铸,也有用玉的,盘状,正面磨光发亮,背面有纹饰。", "cites": [{"t": "镜,鉴也。", "b": "《玉篇》"}, {"t": "镜,景也。", "b": "《说文》"}, {"t": "明镜者可以察形也。", "b": "《大戴礼记·保傅》"}, {"t": "以镜考己行。", "b": "《汉书·谷永传》"}, {"t": "窥镜而自视。", "b": "《战国策·齐策》"}, {"t": "对镜帖花黄。", "b": "《乐府诗集·木兰诗》"}, {"t": "不知明镜里。", "b": "唐·李白《秋浦歌》"}, {"t": "如镜之新开。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "镜袱", "t": "盖住镜面的布帛帘子"}, {"w": "镜心", "t": "镜子的中心"}, {"w": "镜月", "t": "镜中之花,水中之月"}, {"w": "镜花", "t": "镜中的花影。"}]}, {"meaning": "照。", "cites": [{"t": "镜于水,见面之容。", "b": "《墨子》"}, {"t": "不自镜见。", "b": "《汉书·杜邺传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3355wx','赞','1','zàn','贝','16','','[{"pinyin": "zàn", "defs": [{"meaning": "(会意本义:进财货以求谒见)。"}, {"meaning": "同本义。", "cites": [{"t": "赞,见也。", "b": "《说文》。按,玉帛雉羔雁之属皆贝类。贝者,佐见之具。"}, {"t": "进见以见为礼也。", "b": "《说文》锴注"}], "words": [{"w": "赞谒", "t": "进见"}, {"w": "赞献", "t": "进献祭品"}, {"w": "赞见", "t": "进见。"}]}, {"meaning": "导引。", "cites": [{"t": "太史赞王,王敬从之。", "b": "《国语》"}], "words": [{"w": "赞引", "t": "引导"}, {"w": "赞见", "t": "引见"}, {"w": "赞谕", "t": "引导教谕。"}]}, {"meaning": "辅佐,佐助。", "cites": [{"t": "赞,佐也。", "b": "《小尔雅·广诂》"}, {"t": "益赞于禹曰。", "b": "《书·大禹谟》"}, {"t": "主人之赞者西面北上。", "b": "《仪礼·乡饮酒礼》"}, {"t": "卿大夫赞君。", "b": "《礼记·明堂位》"}, {"t": "子若能以忠信赞君。", "b": "《国语·晋语》"}, {"t": "赞帷幄之谋。", "b": "南朝梁·丘迟《与陈伯之书》"}, {"t": "此天以卿二人赞孤也!", "b": "《资治通鉴》"}, {"t": "赞军校尉。(武官名,相当于参谋。)", "b": ""}], "words": [{"w": "赞善", "t": "官名。唐始置,为太子属官,掌司从、辅佐"}, {"w": "赞元理化", "t": "辅佐皇帝推行德化"}, {"w": "赞翼", "t": "辅助"}, {"w": "赞赞", "t": "努力帮助。"}]}, {"meaning": "称颂;赞美。", "cites": [{"t": "自赞于平原君。", "b": "《史记·平原君虞卿列传》"}, {"t": "心计交赞之。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "赞拜", "t": "臣子朝拜皇帝时,赞礼的人在旁唱礼"}, {"w": "盛赞", "t": "极力称赞"}, {"w": "赞尚", "t": "看重别人的长处并加以称扬。"}]}, {"meaning": "告诉;介绍。", "cites": [{"t": "公子引侯生坐上坐,遍赞宾客。", "b": "《史记·魏公子列传》"}]}, {"meaning": "明白。", "cites": [{"t": "总百氏,赞篇章。", "b": "《汉书》"}], "words": [{"w": "赞阅", "t": "明察历练。"}]}, {"meaning": "参与。", "cites": [{"t": "子夏之徒不能赞一辞。", "b": "《史记》"}], "words": [{"w": "赞议", "t": "参议"}, {"w": "赞决", "t": "参与决策。"}]}, {"meaning": "选拔。", "cites": [{"t": "命太尉赞桀俊,遂贤良,举长大。", "b": "《礼记·月令》"}]}, {"meaning": "司仪。", "cites": [{"t": "伊陟赞于巫咸。", "b": "《书·咸有一德》"}, {"t": "将闾曰:“阙廷之礼,吾未尝敢不从宾赞也。”", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "赞仪", "t": "司礼之人"}, {"w": "赞撤", "t": "古代祭祀完毕,大祝帮助小祝撤去祭器。"}]}, {"meaning": "称赞;颂扬。", "cites": [{"t": "进不党以赞己,退不黩于庸人。", "b": "《后汉书》"}, {"t": "下诏褒赞。", "b": "《三国志·许褚传》"}], "words": [{"w": "赞述", "t": "欣赏他人的美善而加以称扬。"}]}, {"meaning": "辅佐,帮助。", "cites": [{"t": "幽赞天地。", "b": "汉《白石神君碑》"}, {"t": "幽赞神明。", "b": "汉《孔庙置守庙百石卒史碑》"}, {"t": "赞拜王庭。", "b": "汉《山阳太守祝睦后碑》"}]}, {"meaning": "佛经中佛教徒歌颂教主释迦牟尼及其他佛陀的文辞。", "cites": [{"t": "是夜黄昏,僧徒礼赞,螺呗间作,渤海命军侯悉擒械之来。", "b": "宋·孙光宪《北梦琐言》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3356wx','穆','1','mù','禾','16','','[{"pinyin": "mù", "defs": [{"meaning": "(形声。本义:禾名)。"}, {"meaning": "同本义。", "cites": [{"t": "穆,禾也。", "b": "《说文》。段玉裁注:“盖禾有名穆者也。”"}]}, {"meaning": "古时宗庙制度,父居左为昭,子居右为穆。参见“昭穆”。", "cites": [{"t": "辩庙祧之昭穆。", "b": "《周礼·小宗伯》。注:“父曰昭,子曰穆。”"}]}, {"meaning": "代指右边。", "cites": [{"t": "只见贾府人分了昭穆,排班立定。", "b": "《红楼梦》"}], "words": [{"w": "昭穆", "t": "左边和右边。"}]}, {"meaning": "恭敬。", "cites": [{"t": "于穆清庙。", "b": "《诗·周颂·清庙》"}, {"t": "穆穆皇皇。", "b": "《诗·大雅·假乐》"}, {"t": "我其为王穆卜。", "b": "《书·金滕》。传:“敬也。”"}], "words": [{"w": "肃穆", "t": "严肃恭敬"}, {"w": "静穆", "t": "安静庄严"}, {"w": "穆穆", "t": "端庄恭敬"}, {"w": "穆穆纯纯", "t": "恭敬诚恳的样子。"}]}, {"meaning": "壮美。", "cites": [{"t": "穆穆文王。", "b": "《诗·大雅·文王》"}, {"t": "天子穆穆。", "b": "《礼记·曲礼》"}], "words": [{"w": "穆穆", "t": "端庄盛美的样子"}, {"w": "穆行", "t": "美行"}, {"w": "穆如", "t": "和美的样子"}, {"w": "穆若", "t": "和美的样子。"}]}, {"meaning": "肃静。", "cites": [{"t": "于是吴王穆然。", "b": "《论衡·非有先生论》。注:“犹默静思貌也。”"}], "words": [{"w": "穆静", "t": "安靖"}, {"w": "穆然", "t": "静思的样子"}, {"w": "穆穆", "t": "宁静;静默。"}]}, {"meaning": "淳和,温和。", "cites": [{"t": "穆如清风。", "b": "《诗·大雅·烝民》"}], "words": [{"w": "穆远", "t": "淳和深远"}, {"w": "穆耀", "t": "祥和光明。"}]}, {"meaning": "和睦。", "cites": [{"t": "而与夏侯尚不穆。", "b": "《三国志·苟彧传》"}], "words": [{"w": "穆清", "t": "和睦清明"}, {"w": "穆亲", "t": "和睦相亲"}, {"w": "穆畅", "t": "清和畅美。"}]}, {"meaning": "纯正。", "cites": [{"t": "布德执义曰穆。", "b": "《周书·谥法》。注:“纯也。”"}], "words": [{"w": "穆羽", "t": "声细如五音之羽,穆然相和。"}]}, {"meaning": "深远;幽微。", "cites": [{"t": "穆眇眇之无垠兮,莽芒芒之无仪。", "b": "《楚辞》"}]}, {"meaning": "清彻。", "cites": [{"t": "天色澄穆,亦惟此时也。", "b": "宋·苏轼《答王敏仲》"}]}, {"meaning": "和睦。", "cites": [{"t": "周公穆康叔,管蔡则流言。", "b": "曹植《豫章行》"}]}, {"meaning": "不语。", "cites": [{"t": "于是吴王穆然,俛而深惟。", "b": "东方朔《非有先生论》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3357wx','篮','1','lán','竹','16','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从竹,监声。本义:篮子,有提梁的竹制盛器。也有用藤条、柳条等编制而成的)。"}, {"meaning": "同本义。", "cites": [{"t": "篮,大篝也。", "b": "《说文》"}, {"t": "篮,筐也。", "b": "《广雅·释器》"}], "words": [{"w": "篮儿", "t": "篮子"}, {"w": "竹篮;提篮", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3358wx','篡','1','cuàn','竹','16','','[{"pinyin": "cuàn", "defs": [{"meaning": "(形声。从竹,算声。本义:非法地夺取)。"}, {"meaning": "同本义。", "cites": [{"t": "自关而西,秦晋之间,凡取物而逆谓之篡。", "b": "《方言》一"}, {"t": "且如人有财,见篡于盗。", "b": "王安石《原过》"}, {"t": "豪民子闻难,鸠宗族僮奴百许人,欲要篡以归。", "b": "高启《书博鸡者事》"}], "words": [{"w": "篡逆", "t": "用强力夺取君位的叛逆"}, {"w": "篡取", "t": "夺取"}, {"w": "篡事", "t": "篡夺之事。"}]}, {"meaning": "特指臣子夺取君位。", "cites": [{"t": "及王莽篡位,歆为国师。", "b": "《汉书·刘歆传》"}], "words": [{"w": "篡臣", "t": "篡夺君权之臣"}, {"w": "篡杀", "t": "弑君而夺其位"}, {"w": "篡弑", "t": "犹篡杀"}, {"w": "篡绝", "t": "篡夺君位而绝其后。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3359wx','篷','1','péng','竹','16','','[{"pinyin": "péng", "defs": [{"meaning": "(形声。从竹,逢声。本义:车船等用以遮蔽风雨和阳光的设备。用篾席或布制成)。"}, {"meaning": "同本义。", "cites": [{"t": "篛篷覆之。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "篷舟", "t": "篷船"}, {"w": "篷船", "t": "有篷盖的船"}, {"w": "篷厂", "t": "棚子,棚盖"}, {"w": "篷声", "t": "雨落船篷之声"}, {"w": "篷庐", "t": "像篷盖似的屋子"}, {"w": "篷底", "t": "船篷之下。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3360wx','篱','1','lí','竹','16','','[{"pinyin": "lí", "defs": [{"meaning": "(形声。从竹,离声。本义:篱笆)。"}, {"meaning": "同本义。用竹、苇或树枝等编成的蔽障物,以保护场地。也说“笆篱”。", "cites": [{"t": "采菊东篱下,悠然见南山。", "b": "晋·陶潜《饮酒》"}, {"t": "庭中始为篱。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "樊篱", "t": "篱笆"}, {"w": "篱子", "t": "即篱笆"}, {"w": "篱花", "t": "篱菊。篱下的菊花"}, {"w": "篱门", "t": "竹篱的门"}, {"w": "篱陌", "t": "篱边和田头"}, {"w": "篱垣", "t": "用竹篱做成的墙垣"}, {"w": "篱根", "t": "竹篱近地处。"}]}, {"meaning": "笊(zhào)篱  ,用竹蔑、柳条、铁丝编成的杓形用具,能漏水,用来在汤里捞东西。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3361wx','儒','1','rú','亻','16','','[{"pinyin": "rú", "defs": [{"meaning": "(形声。从人, 需声。本义: 术士)。"}, {"meaning": "同本义。春秋时从巫、史、祝、卜中分化出来的、熟悉诗书礼乐而为贵族服务的人。", "cites": [{"t": "儒,术士之称。", "b": "《说文》"}, {"t": "通天地之人曰儒。", "b": "《法言·君子》"}, {"t": "能说一经者为儒生。", "b": "《论衡·超奇》"}, {"t": "儒浩居而自顺者也。", "b": "《墨子·非儒下》"}, {"t": "四曰儒,以道得民。", "b": "《周礼·太宰》"}, {"t": "儒之言优也和也,言能安人能服人也。", "b": "《礼记·儒行》"}], "words": [{"w": "儒师;儒仙", "t": ""}]}, {"meaning": "儒生。中国哲学家孔子的门徒、学生; 孔子学说的信徒。", "cites": [{"t": "女为君子儒,无为小人儒。", "b": "《论语·雍也》"}], "words": [{"w": "儒效", "t": "儒者的效用,儒学的功效"}, {"w": "儒素", "t": "儒者的素行"}, {"w": "儒侠", "t": "儒生和游侠"}, {"w": " 儒素", "t": "儒者的素质,谓符合儒家思想的品格德行"}, {"w": " 儒吏", "t": "儒生出身的吏员"}, {"w": " 儒先", "t": "儒生"}, {"w": " 儒效", "t": "儒者的作用;儒学的效用"}, {"w": " 儒流", "t": "儒士之辈。"}]}, {"meaning": "旧时对学者或读书人的称呼。", "cites": [{"t": "是儒墨之分也。", "b": "《荀子·礼论》"}, {"t": "儒者所争,尤在于名实。", "b": "宋·王安石《答司马谏议书》"}, {"t": "谈笑有鸿儒,往来无白丁。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "儒馆", "t": "文臣的居处"}, {"w": "儒巾", "t": "古代读书人所戴的一种头巾"}, {"w": "儒户", "t": "读书人的户籍"}, {"w": "儒冠", "t": "古代儒生带的帽子"}, {"w": "儒俊", "t": "才智出众的儒士"}, {"w": "儒修", "t": "才能出众的儒士"}, {"w": "儒服", "t": "儒衣,古代儒者的服饰"}, {"w": "儒官", "t": "古代掌管学务的官员或官学教师。"}]}, {"meaning": "懦弱。", "cites": [{"t": "劳苦之事,则偷儒转脱。", "b": "《荀子·脩身》"}], "words": [{"w": "儒柔,儒弱", "t": "柔弱,文弱"}, {"w": "儒缓", "t": "柔弱,宽柔"}, {"w": "儒懦", "t": "柔弱,不刚强。"}]}, {"meaning": "愚昧无知的。", "cites": [{"t": "儒,愚也。", "b": "《广雅》"}]}, {"meaning": "缓慢。", "cites": [{"t": "儒,此言圣人之动静、开阖、诎信、…取与之必因于时也。", "b": "《管子》"}], "words": [{"w": "儒厚", "t": "温文厚重"}, {"w": "儒输", "t": "迂缓迟钝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3362wx','邀','1','yāo','辶','16','','[{"pinyin": "yāo", "defs": [{"meaning": "(形声。从辵,敫声。本义:迎候)。"}, {"meaning": "同本义。", "cites": [{"t": "邀相见。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "邀我至田家。", "b": "唐·孟浩然《过故人庄》"}, {"t": "北邀当国者。", "b": "宋·文天祥《指南录·后序》"}, {"t": "邀见讲钧礼。", "b": "清·周容《芋老人传》"}], "words": [{"w": "邀接", "t": "迎接"}, {"w": "邀迓", "t": "迎请"}, {"w": "邀迎", "t": "迎合。"}]}, {"meaning": "逢,遇到。", "cites": [{"t": "邀殊宠,一枝已傍日边红。", "b": "清·洪昇《长生殿》"}], "words": [{"w": "邀世", "t": "逢世"}, {"w": "邀乐", "t": "遇到欢乐"}, {"w": "邀天晴", "t": "逢天晴"}, {"w": "邀幸", "t": "侥幸,幸运。"}]}, {"meaning": "阻拦;截击。", "cites": [{"t": "又怕山北诸州出兵,邀其归路而击之。", "b": "《新编五代史平话》"}], "words": [{"w": "邀截", "t": "阻截"}, {"w": "邀留", "t": "婉称被俘获"}, {"w": "邀勒", "t": "遮拦;阻挡"}, {"w": "邀丐", "t": "阻截索求"}, {"w": "邀伏", "t": "设伏兵拦 击"}, {"w": "邀劫", "t": "拦路抢劫。"}]}, {"meaning": "请求;谋求。", "cites": [{"t": "吾乘时邀幸,得为吏部尚书。", "b": "《魏书·崔亮传》"}], "words": [{"w": "邀恩", "t": "清代对年过八旬而未录取的考生赐赏举人称号"}, {"w": "邀名", "t": "求取好的名声。"}]}, {"meaning": "要挟。", "cites": [{"t": "邀其上者。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "邀君", "t": "要挟君主"}, {"w": "邀勒", "t": "强迫;逼勒"}, {"w": "邀胁", "t": "要挟;威胁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3363wx','衡','1','héng','彳','16','','[{"pinyin": "héng", "defs": [{"meaning": "(形声。从角,从大,行声。本义:绑在牛角上的横木)。"}, {"meaning": "同本义。一说穿于牛鼻的横木。", "cites": [{"t": "秋而载尝,夏而福衡。", "b": "《诗·鲁颂》。毛传:“福衡,设牛角以福之也。”"}, {"t": "衡,牛触,横大木其角。", "b": "《说文》。徐锴注:“谓牛好抵触,以木阑制之也。”"}]}, {"meaning": "车辕前端的横木。", "cites": [{"t": "加之以衡扼。", "b": "《庄子·马蹄》。释文:“衡,辕前横木缚轭者也。”"}, {"t": "则见其倚于衡也。", "b": "《论语·卫灵公》。皇疏:“衡,车衡,轭也。”"}, {"t": "枉玉衡于炎火兮。", "b": "《楚辞·刘向·九叹·远逝》"}], "words": [{"w": "衡辀", "t": "车辕与辕前横木"}, {"w": "衡轸", "t": "辕前横木与车后横木"}, {"w": "衡盖", "t": "车辕前端的横木和车上的伞盖。亦借指车。"}]}, {"meaning": "秤杆,秤。", "cites": [{"t": "衡不同于轻重。", "b": "《韩非子·扬权》"}], "words": [{"w": "衡石", "t": "泛指称重量的器物"}, {"w": "衡库", "t": "称与仓库"}, {"w": "衡玑", "t": "即天平"}, {"w": "衡鉴", "t": "衡器和镜子"}, {"w": "衡权", "t": "称物之具。"}]}, {"meaning": "衡山的简称 。此山系五岳之一,在今湖南省中东部。"}, {"meaning": "水名。衡水的省称。", "cites": [{"t": "求思望襄澨,叹息对衡渚。", "b": "刘义恭《艳歌行》"}]}, {"meaning": "称量。", "cites": [{"t": "衡,加重于其一旁,必捶。", "b": "《孟子·惠王上》"}, {"t": "犹衡之于轻重也。", "b": "《礼记·经解》。注:“衡,称也。”"}, {"t": "为之权衡以称之,则并与权衡而窃之。", "b": "《庄子·胠箧》"}]}, {"meaning": "衡量;评定。", "cites": [{"t": "衡之于左右。", "b": "《淮南子·主述训》"}], "words": [{"w": "衡文", "t": "品评文章,指主持科举考试"}, {"w": "衡定", "t": "评定"}, {"w": "衡校", "t": "品评考核"}, {"w": "衡鉴", "t": "品评,鉴别。"}]}, {"meaning": "横。与“纵”相对。", "cites": [{"t": "衡,横也。", "b": "《广雅》"}, {"t": "衡门之下。", "b": "《诗·陈风·衡门》。传:“衡门,横木为门。”"}, {"t": "外连衡而斗诸侯。", "b": "贾谊《过秦论》"}, {"t": "倚一衡木。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "衡陈", "t": "横向排列"}, {"w": "横纵", "t": "纵横"}, {"w": "衡缩", "t": "纵横。"}]}, {"meaning": "平正 。如;衡言(平正之言);衡虚(平正而清虚);衡仪(公平的法则)。"}, {"meaning": ",梗塞、不顺。", "cites": [{"t": "衡于虑。", "b": "《孟子·告子下》"}, {"t": "一人衡行于天下,武王耻之。", "b": "《孟子·梁惠王下》"}, {"t": "不官而衡至者,君子慎之。", "b": "《荀子·致仕》"}, {"t": "有勇力者聚徒而衡击。", "b": "汉·贾谊《论积贮疏》"}, {"t": "衡流而方羊。", "b": "《左传·哀公十七年》"}, {"t": "古者冠缩缝,今也衡缝。", "b": "《礼记·檀弓上》"}, {"t": "以能合从,又善连衡。", "b": "《荀子·赋》"}, {"t": "非有分于纵横之党。", "b": "《韩非子·五蠹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3364wx','膨','1','péng','月','16','','[{"pinyin": "péng", "defs": [{"meaning": "体积或长度增大", "words": [{"w": "膨脝", "t": "肚子胀的样子。"}, {"w": "膨张", "t": "同“膨胀”"}, {"w": "膨涨", "t": "同“膨胀”"}, {"w": "膨膨", "t": "气满鼓胀的样子。"}, {"w": "膨化", "t": "指谷物等在受热、受压时突然减压而膨胀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3365wx','雕','1','diāo','隹','16','','[{"pinyin": "diāo", "defs": [{"meaning": "(形声。从隹(zhuī),周声。从“隹”,表示与鸟类有关。本义:大型猛禽。日间活动的大猛禽(鹰科)力大身大,形态优美,视力敏锐,飞行力强。也叫“鹫”)。"}, {"meaning": "同本义。", "cites": [{"t": "流之为雕。", "b": "《书·太古誓》"}, {"t": "是必射雕者也。", "b": "《史记·李将军列传》"}, {"t": "其状如雕而有角。", "b": "《山海经·南山经》"}, {"t": "回看射雕处,千里暮云平。", "b": "唐·王维《观猎》"}], "words": [{"w": "雕悍", "t": "凶悍如雕"}, {"w": "雕鸷", "t": "凶猛如雕"}, {"w": "雕鹗", "t": "雕和鶚。均为善飞的鸷鸟。比喻人雄放劲健的才力"}, {"w": "金雕;海雕;坐山雕", "t": ""}]}, {"meaning": "碉堡。", "cites": [{"t": "依山居止,累石为室。", "b": "《后汉书》。唐·李贤注:“今彼土夷人呼为‘雕’也。”"}]}, {"meaning": "治玉", "cites": [{"t": "玉栉雕矢磬。", "b": "《考工记·总目》。谓治玉工也。"}, {"t": "雕玉仍几。", "b": "《书·顾命》"}], "words": [{"w": "雕人", "t": "治玉摩骨的人。"}]}, {"meaning": "引申为雕刻。", "cites": [{"t": "下雕辇于东厢。", "b": "张衡《东京赋》"}, {"t": "执雕虎而试象兮。", "b": "《后汉书·张衡传》"}, {"t": "雕琉璃于翠楣。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "雕虫", "t": "雕虫技。比喻细小不足道的技能"}, {"w": "雕甍", "t": "有浮雕做装饰的屋脊。甍:屋脊"}, {"w": "雕漆", "t": "在器物上涂厚漆,待半干后雕刻各种花纹的一种特种工艺"}, {"w": "雕青", "t": "用针在人体上雕刺各种花纹图形,然后涂上青色。亦称文身"}, {"w": "雕甍绣栏", "t": "以浮雕装饰的屋脊,颜色各异的栏杆。"}]}, {"meaning": "用彩画装饰", "cites": [{"t": "峻宇雕墙。", "b": "《书·五子之歌》"}, {"t": "晋灵公不君,厚敛以雕墙。", "b": "《左传·宣公二年》"}, {"t": "今有璞玉于此,虽万镒,必使玉人雕琢之。", "b": "《孟子·梁惠王下》"}, {"t": "右雕几。", "b": "《周礼·春官·司几筵》"}, {"t": "左鸟号之雕弓,右夏服之劲箭。", "b": "《汉书·司马相如传上》"}, {"t": "秦穆公衡雕戈出见使者。", "b": "《国语·晋语》"}], "words": [{"w": "雕梁画柱", "t": ""}]}, {"meaning": "“凋”的古字。凋零。", "cites": [{"t": "寒则雕,热则脩。", "b": "《吕氏春秋》"}, {"t": "民力雕尽。", "b": "《国语·周语》"}]}, {"meaning": "凶猛。", "cites": [{"t": "而民雕捍少虑,有鱼盐枣栗之饶。", "b": "《史记》"}]}, {"meaning": "", "cites": [{"t": "岭峤微草,凌冬不雕。", "b": "宋·沈括《梦溪笔谈·采草药》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3366wx','鲸','1','jīng','鱼','16','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从鱼,京声。本义:鲸鱼) 同本义 哺乳动物,生活在海洋中,胎生,外形如大鱼,体长可达30米,是现在世界上最大的动物,前肢形成鳍,后肢完全退化,尾巴变成尾鳍,鼻孔在头的上部,用肺呼吸。肉可食,脂肪可制油,用于医药和其他工业", "words": [{"w": "蓝鲸", "t": ""}, {"w": "抹香鲸", "t": ""}, {"w": "长须鲸", "t": ""}, {"w": "鲸文", "t": "古代钱币名。汉时所铸,上面有鱼形,亦称轻影钱"}]}, {"meaning": "大;巨大", "words": [{"w": "鲸川", "t": "大江、大河"}, {"w": "鲸浪", "t": "巨浪"}, {"w": "鲸浦", "t": "大海"}, {"w": "鲸寇", "t": "大盗"}, {"w": "鲸钟", "t": "古大钟"}, {"w": "鲸谿", "t": "大海"}, {"w": "鲸猾", "t": "大猾徒"}, {"w": "鲸舟", "t": "大船"}, {"w": "鲸音", "t": "洪亮之声"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3367wx','磨','1','mó mò','石','16','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从石,麻声。本义:磨治石器)。"}, {"meaning": "同本义。", "cites": [{"t": "如切如磋,如琢如磨。", "b": "《诗·卫风·淇奥》"}, {"t": "切磋琢磨,乃成宝器。", "b": "《论衡·量知》"}, {"t": "不曰坚乎,磨而不磷。", "b": "《论语·阳货》"}], "words": [{"w": "切磋琢磨", "t": "加工骨称“切”,加工象牙称“磋”,加工玉称“琢”,加工石称“磨”"}, {"w": "磨渲", "t": "磨治"}, {"w": "磨拭", "t": "琢磨"}, {"w": "磨琢", "t": "犹琢磨"}, {"w": "磨斫", "t": "雕琢;雕饰。"}]}, {"meaning": "用磨料磨物体使光滑、锋利或达到其他目的。", "cites": [{"t": "小弟闻姊来,磨刀霍霍向猪羊。", "b": "《木兰诗》"}], "words": [{"w": "磨镜石", "t": "传说轩辕氏铸镜时用以磨镜的石头"}, {"w": "磨刀雨", "t": "即磨刀水"}, {"w": "磨刀水", "t": "旧指农历五月十三日所下的雨"}, {"w": "磨刀霍霍", "t": "磨刀声"}, {"w": "磨袭砥砺", "t": "四种质地和颜色不同的磨石。"}]}, {"meaning": "磨炼。", "cites": [{"t": "大开明堂受朝贺,诸侯剑佩鸣相磨。", "b": "韩愈《石鼓歌》"}, {"t": "人之于文学也,犹玉之于琢磨也。", "b": "《荀子·大略》"}], "words": [{"w": "磨涅", "t": "磨砺熏染,经得起考验"}, {"w": "磨厉", "t": "磨练"}, {"w": "磨揉", "t": "磨练"}, {"w": "磨盾", "t": "犹磨练。"}]}, {"meaning": "研讨;观摩。", "cites": [{"t": "人之于文学也,犹玉之于琢磨也。", "b": "《荀子·大略》"}], "words": [{"w": "磨切", "t": "切磋;探讨"}, {"w": "磨究", "t": "研讨究竟"}, {"w": "磨砻", "t": "切磋;磨练"}, {"w": "磨砻浸灌", "t": "切磋浸染"}, {"w": "磨砻镌切", "t": "磨砺切磋。"}]}, {"meaning": "磨灭;泯灭。", "cites": [{"t": "人生一世,其久几何,吾立子名,百世不磨。", "b": "唐·韩愈《送穷文》"}]}]}, {"pinyin": "mò", "defs": [{"meaning": "磨子。", "cites": [{"t": "以磨碎物亦曰磨。", "b": "朱骏声《说文通训定声》"}, {"t": "作牛便推磨。", "b": "王安石《拟寒山拾得》"}], "words": [{"w": "磨石", "t": "研碎粮食的石制工具"}, {"w": "磨心", "t": "石磨中心"}, {"w": "磨牛", "t": "转磨之牛。比喻愚鲁"}, {"w": "磨室", "t": "即磨坊"}, {"w": "电磨;水磨", "t": ""}]}, {"meaning": "碾轧土地。", "cites": [{"t": "我们耕田磨地的女子,对个皮鞋托托响、油头油脸的香港人全不合适。", "b": "陈残云《香飘四季》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3368wx','瘾','1','yǐn','疒','16','','[{"pinyin": "yǐn", "defs": [{"meaning": "(形声。从疒(chuáng),隐声。本义:不良的癖好)。"}, {"meaning": "同本义。", "cites": [{"t": "洋烟瘾发之人,涕洢交流,遍身瘫软。", "b": "曾国藩《劝诫营官》"}], "words": [{"w": "瘾民", "t": "吸鸦片成瘾的人"}, {"w": "烟瘾;酒瘾", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3369wx','瘸','1','qué','疒','16','','[{"pinyin": "qué", "defs": [{"meaning": "本谓手或脚偏废的病。后特指腿脚有病,行步不平衡", "words": [{"w": "瘸汉", "t": "瘸子;跛子"}, {"w": "瘸狼渴疾", "t": "跌跌撞撞急行貌"}]}, {"meaning": "变成残废"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3370wx','凝','1','níng','冫','16','','[{"pinyin": "níng", "defs": [{"meaning": "(会意。古冰字,从水,从疑。疑,止也。疑亦声。本义:结冰)。"}, {"meaning": "同本义。", "cites": [{"t": "凝,水坚也。", "b": "《说文》"}, {"t": "凝,定也。", "b": "《广雅》"}, {"t": "肤如凝脂。", "b": "《诗·卫风·硕人》"}, {"t": "凝土以为器。", "b": "《考工记》"}, {"t": "天气严疑之气。", "b": "《礼记·乡饮酒义》"}, {"t": "霜锷水凝。", "b": "枚乘《七命》"}, {"t": "幕中草檄(xì)砚水凝。", "b": "唐·岑参《走马川行》"}], "words": [{"w": "凝寒", "t": "寒冷冻结"}, {"w": "凝冰", "t": "冰;结冰"}, {"w": "凝雨", "t": "雪"}, {"w": "凝涸", "t": "冻结"}, {"w": "凝霜", "t": "凝结成霜。"}]}, {"meaning": "凝聚;积聚。", "cites": [{"t": "沙石凝积,地势无所宜。", "b": "《盐铁论·轻重》"}, {"t": "瀚海阑干百丈冰,愁云惨淡万里凝。", "b": "岑参《白雪歌送武判官归京》"}], "words": [{"w": "油还没凝住;水凝成了冰;凝合", "t": "聚拢集结"}, {"w": "凝情", "t": "凝聚愁情"}, {"w": "凝图", "t": "收聚天下图书"}, {"w": "凝尘", "t": "积聚的尘土"}, {"w": "凝蹇", "t": "凝结"}, {"w": "凝露", "t": "凝结的露珠;凝聚成露;凝结着露珠"}, {"w": "凝心", "t": "专心;一心一意"}, {"w": "凝玩", "t": "专心观赏把玩"}, {"w": "凝念", "t": "沉思;专心思考"}, {"w": "凝待", "t": "专心等待"}, {"w": "凝睛", "t": "眼不转睛"}, {"w": "凝意", "t": "意念专注。"}]}, {"meaning": "集中;注目;注视。", "cites": [{"t": "用志不分、乃凝于神。", "b": "《庄子·达生》"}, {"t": "凝听翔立。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "凝盼", "t": "注视"}, {"w": "凝目", "t": "注目;凝视"}, {"w": "凝眺", "t": "注目远望"}, {"w": "凝眼", "t": "注目"}, {"w": "凝瞳", "t": "注目。"}]}, {"meaning": "停止;静止。", "cites": [{"t": "舟凝滞于水滨,车逶迟于山侧。", "b": "江淹《别赋》"}], "words": [{"w": "凝坐", "t": "静坐"}, {"w": "凝停", "t": "静止;停滞"}, {"w": "凝绝", "t": "停止;中断"}, {"w": "凝族", "t": "冕旒静止不动。形容帝王态度肃穆专注"}, {"w": "凝澹", "t": "静止。"}]}, {"meaning": "稳重;庄重。", "cites": [{"t": "器量宏大,风度端凝。", "b": "清·徐珂《清稗类钞·容止类》"}], "words": [{"w": "凝正", "t": "稳重端庄"}, {"w": "凝厚", "t": "稳重敦厚"}, {"w": "凝直", "t": "庄重而正直"}, {"w": "凝峻", "t": "庄重严峻"}, {"w": "凝特", "t": "庄重严肃,与众不同"}, {"w": "凝简", "t": "庄重而朴实"}, {"w": "凝旷", "t": "端庄旷达"}, {"w": "凝稳", "t": "端庄稳重。"}]}, {"meaning": "徐缓。", "cites": [{"t": "缓歌慢舞凝丝竹。", "b": "白居易《长恨歌》"}], "words": [{"w": "凝笳", "t": "徐缓幽咽的笳声"}, {"w": "凝净", "t": "平缓明静。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3371wx','辨','1','biàn','辛','16','','[{"pinyin": "biàn", "defs": [{"meaning": "(形声。从刀,辡(biǎn)声。本义:判别,区分,辨别)。"}, {"meaning": "同本义。", "cites": [{"t": "辨,判也。", "b": "《说文》"}, {"t": "辨,别也。", "b": "《小尔雅》"}, {"t": "辨方正位。", "b": "《周礼·天官》"}, {"t": "辨是与非。", "b": "《易·系辞下》"}, {"t": "目辨白黑美恶,耳辨音声清浊。", "b": "《荀子·荣辱》"}, {"t": "不辨牛马。", "b": "《庄子·秋水》"}, {"t": "男女辨姓。", "b": "《左传·昭公元年》"}, {"t": "双兔傍地走,安能辨我是雄雌。", "b": "《乐府诗集·木兰诗》"}], "words": [{"w": "明辨是非;辨白", "t": "分辨清楚"}, {"w": "辨色", "t": "辨别物色。"}]}, {"meaning": "口头上争论。", "cites": [{"t": "吾闻穷巷多怪,曲学多辨。", "b": "《商君书·更法》"}, {"t": "传曰:析辞而为察,言物而为辨,君子贱之。", "b": "《荀子·解蔽》"}, {"t": "分争辨讼,非礼不决。", "b": "《礼记·曲礼上》"}, {"t": "故略上报,不复一一自辨。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "辨士", "t": "善辩的说客"}, {"w": "辨给", "t": "口才敏捷,能言善辨"}, {"w": "辨驳", "t": "根据事理加以反驳。"}]}, {"meaning": "颁布。", "cites": [{"t": "吏以文法教训辨告,勿笞辱。", "b": "《汉书·高帝纪下》"}, {"t": "辨社诸侯,出门见之,著以为戒。", "b": "《汉书·王莽传上》"}], "words": [{"w": "辨告", "t": "古代官吏将所订法律颁布告知民众。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3372wx','辩','1','biàn','辛','16','','[{"pinyin": "biàn", "defs": [{"meaning": "(形声。从言,辡(biǎn)声。本义:辩论,申辩)。"}, {"meaning": "同本义。", "cites": [{"t": "辩,治也。", "b": "《说文》"}, {"t": "辩其狱讼。", "b": "《周礼·乡士》"}, {"t": "分争辩讼。", "b": "《礼记·曲礼》"}, {"t": "辩者言之信。", "b": "《韩非子·八经》"}, {"t": "勿辩乃司。", "b": "《书·酒诰》"}, {"t": "孔子东游,见两小儿辩斗。", "b": "《列子·汤问》"}, {"t": "狼亦巧辩不已以求胜。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "辩证;辩日", "t": "古代传说辩论太阳离地球远近的故事。"}]}, {"meaning": "分别,辨别", "cites": [{"t": "辩其功苦。", "b": "《国语·齐语》"}, {"t": "若白墨之于目辩。", "b": "《淮南子·滫务》"}, {"t": "目能辩色,耳能辩声。", "b": "东汉·仲长统《昌言·理乱》"}], "words": [{"w": "辩章", "t": "辨别彰明。同辨章"}, {"w": "辩析", "t": "辨别分析"}, {"w": "明辩是非;辩白", "t": "申辩明白。同辨白。"}]}, {"meaning": "治理,办理。", "cites": [{"t": "辩治百官,领理万事。", "b": "《淮南子·泰族》"}]}, {"meaning": "有口才,善言辞。", "cites": [{"t": "子言非不辩也。", "b": "《韩非子·五蠹》"}], "words": [{"w": "辩武", "t": "善辞令的人。即辩士"}, {"w": "辩人", "t": "善于辞令的人。如说客之流"}, {"w": "辩捷", "t": "能言善辩,口才敏捷"}, {"w": "辩口", "t": "口才便捷,善于辩论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3373wx','糙','1','cāo','米','16','','[{"pinyin": "cāo", "defs": [{"meaning": "(形声。从米,造声。本义:没有精碾的粗米)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3374wx','糖','1','táng','米','16','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从米,唐声。本义:食用糖及糖制食品的统称)。"}, {"meaning": "食糖。古代以麦作饴,即麦芽糖。后多用甘蔗、甜菜等制糖。", "cites": [{"t": "糖,饴也。", "b": "《广韵》"}, {"t": "更添糖,拼折本,供他几碗。", "b": "宋·史浩《粉蝶儿·咏圆子》"}], "words": [{"w": "红糖;白糖;冰糖;糖餔", "t": "一种甜饼"}, {"w": "糖霜", "t": "细白沙糖"}, {"w": "糖馈", "t": "一种甜饼。也作馈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3375wx','糕','1','gāo','米','16','','[{"pinyin": "gāo", "defs": [{"meaning": "用米粉或面粉搀和其他材料蒸制或烘烤而成的食品", "words": [{"w": "蛋糕", "t": ""}, {"w": "糕点", "t": "以糊状面团焙制的甜味食品"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3376wx','燃','1','rán','火','16','','[{"pinyin": "rán", "defs": [{"meaning": "(形声。从火,然声。“然”有表意作用。本作“然”。“燃”是后起字。本义:燃烧)。"}, {"meaning": "同本义。", "cites": [{"t": "煮豆燃豆萁,豆在釜中泣。", "b": "曹植《七步诗》"}], "words": [{"w": "燃藜图", "t": "劝人勤学苦读的画"}, {"w": "燃灰", "t": "死灰复燃"}, {"w": "燃灼", "t": "燃烧;烧灼"}, {"w": "燃顶", "t": "以香火烧灼头顶,表示虔诚。"}]}, {"meaning": "引火点着。", "cites": [{"t": "……开枪者、燃炮者、……络绎相属。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "燃放", "t": "点燃鞭炮等使其爆炸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3377wx','濒','1','bīn','氵','16','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从水,频声。本义:水边) 同本义。", "cites": [{"t": "是故昔者舜耕于历山,陶于河濒。", "b": "《墨子·尚贤》"}, {"t": "行举濒河之郡。", "b": "《汉书·成帝纪》。师古曰:“滨,水涯也。”"}, {"t": "濒海之观毕至。", "b": "《汉书·贾山传》"}]}, {"meaning": "靠近;临近。", "cites": [{"t": "濒南山,近夏阳。", "b": "《汉书·地理志》"}], "words": [{"w": "濒危;濒近;濒于", "t": "亦作“濒於”。指临近某种坏的遭遇。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3378wx','澡','1','zǎo','氵','16','','[{"pinyin": "zǎo", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "澡,洒手也。", "b": "《说文》"}, {"t": "澡葛綕带。", "b": "《仪礼·士虞礼》"}, {"t": "日三澡漱,然后饮食。", "b": "《魏书》"}]}, {"meaning": "后泛指洗涤。", "cites": [{"t": "常以月旦祓龟,洗以清水澡之。", "b": "《史记·龟策传》"}], "words": [{"w": "澡沐", "t": "沐浴"}, {"w": "澡雪", "t": "洗清"}, {"w": "澡瓶", "t": "寺庙里供僧人洗涤用的水瓶"}, {"w": "澡刷", "t": "洗刷"}, {"w": "澡涤", "t": "洗刷。引申指辨白冤屈。"}]}, {"meaning": "洗澡或浸泡。", "cites": [{"t": "儒有澡身而浴德。", "b": "《礼记·儒行》"}, {"t": "时天暑热,植因呼常从取水自澡讫,傅粉。", "b": "《三国志·王粲传》"}], "words": [{"w": "澡形,澡身", "t": "洗身使洁净。引申为修持操行"}, {"w": "澡洗", "t": "沐浴;盥洗"}, {"w": "澡浴", "t": "洗澡"}, {"w": "澡濯", "t": "洗澡。"}]}, {"meaning": "改过。", "cites": [{"t": "澡雪垢滓矣。", "b": "马融《长笛赋》"}], "words": [{"w": "澡心", "t": "改过自新"}, {"w": "澡祓", "t": "洗刷辨明"}, {"w": "澡雪", "t": "改正;洗雪"}, {"w": "澡荡", "t": "洗除。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3379wx','激','1','jī','氵','16','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。本义:水势受阻遏后腾涌或飞溅)。"}, {"meaning": "同本义。", "cites": [{"t": "激,水碍袤疾波也。", "b": "《说文》"}, {"t": "激而行之,可使在山。", "b": "《孟子》"}, {"t": "激水之疾,至于漂石者,势也。", "b": "《孙子·势》"}, {"t": "泉水激石。", "b": "吴均《与朱元思书》"}], "words": [{"w": "激激", "t": "急流声;水势湍急的样子"}, {"w": "激浪", "t": "怒涛"}, {"w": "激射", "t": "喷射,冲击。"}]}, {"meaning": "鼓动人心,使有所感发。", "cites": [{"t": "激而发之。", "b": "唐·柳宗元《柳河东集》"}, {"t": "激于义而死。", "b": "明·张溥《五人墓碑记》"}, {"t": "激众愤。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "激烦", "t": "麻烦"}, {"w": "激作", "t": "振奋激励"}, {"w": "激拔", "t": "激励提拔"}, {"w": "激奖", "t": "激励劝勉"}, {"w": "激聒", "t": "嘟囔"}, {"w": "激激聒聒", "t": "嘟嘟囔囔。"}]}, {"meaning": "迅疾;猛烈。", "cites": [{"t": "比如顺风而呼,声非加疾,其势激也。", "b": "《史记·游侠列传》"}], "words": [{"w": "激水", "t": "湍急的水流"}, {"w": "激矢", "t": "急飞的箭"}, {"w": "激合", "t": "迅速集合"}, {"w": "激迫", "t": "急迫"}, {"w": "激辞", "t": "激烈的言辞。"}]}, {"meaning": "高亢;激昂。", "cites": [{"t": "振声激扬。", "b": "《后汉书·张衡传》"}], "words": [{"w": "激卬", "t": "振奋昂扬"}, {"w": "激楚", "t": "声音高亢凄凉;又为古代歌曲名"}, {"w": "激抗", "t": "高亢"}, {"w": "激壮", "t": "激昂雄壮"}, {"w": "激宕", "t": "激越跌荡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3380wx','懒','1','lǎn','忄','16','','[{"pinyin": "lǎn", "defs": [{"meaning": "(形声。从心,赖声。本义:懒惰)。"}, {"meaning": "同本义。", "cites": [{"t": "懒,懈也。怠也。一曰卧也。", "b": "《说文》。字亦作懒。"}, {"t": "吾少懒学问,晚成人。", "b": "《宋书·范晔传》"}], "words": [{"w": "懒待", "t": "没有精神和兴致"}, {"w": "懒怠", "t": "懒于做某种事"}, {"w": "懒得", "t": "不想,不情愿"}, {"w": "懒残和尚煨芋", "t": "唐衡狱寺和尚明瓒禅师,性子懒惰,常吃别人剩食,因号懒残。李泌在寺里夜读访他时,他正在牛粪中煨芋,并送半个芋头给李,叫他小心不要多讲话,去做十年宰相。后果如其言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3381wx','憾','1','hàn','忄','16','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从心,感声。本义:遗憾,不快,不满)。"}, {"meaning": "同本义(先秦古书一般用“憾”,汉代以后多用“恨”)。", "cites": [{"t": "憾,恨也。", "b": "《广雅》"}, {"t": "以其私憾。", "b": "《左传·宣公二年》"}, {"t": "不可使多畜憾。", "b": "《左传·文公十四年》"}, {"t": "敝之而无憾。", "b": "《论语·公冶长》"}, {"t": "人犹有所憾。", "b": "《礼记·中庸》"}, {"t": "无憾而后即安。", "b": "《国语·鲁语下》"}, {"t": "是使民养生丧死无憾也。", "b": "《孟子·梁惠王上》"}, {"t": "志恨憾而不逞兮。", "b": "《楚辞·严忌哀时命》"}, {"t": "降而不憾。", "b": "《左传·隐公三年》"}, {"t": "死无余憾。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "憾悔", "t": "悔恨"}, {"w": "憾惜", "t": "遗憾惋惜"}, {"w": "憾轲", "t": "境遇不顺。"}]}, {"meaning": "怨恨。", "cites": [{"t": "请君释憾于宋,敝邑为道。", "b": "《左传·隐公五年》"}, {"t": "一言之憾。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "憾怨", "t": "怨恨"}, {"w": "憾恨", "t": "怨恨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3382wx','懈','1','xiè','忄','16','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从心,解声。本义:松懈)。"}, {"meaning": "同本义。", "cites": [{"t": "懈,怠也。", "b": "《说文》"}, {"t": "夙夜匪懈。", "b": "《孝经》"}, {"t": "为民兴利除害而不懈。", "b": "《淮南子》"}, {"t": "然侍卫之臣不懈于内。", "b": "诸葛亮《出师表》"}, {"t": "懈怠则思慎始而敬终。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "懈懈", "t": "怠惰;懒散"}, {"w": "懈厥操觚", "t": "怠慢从事"}, {"w": "懈忒", "t": "懈怠失误"}, {"w": "懈沮", "t": "懈怠沮丧"}, {"w": "懈意", "t": "懈怠之心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3383wx','窿','1','lóng','穴','16','','[{"pinyin": "lóng", "defs": [{"meaning": "高起;突出", "words": [{"w": "窿穹", "t": "高大的样子"}]}, {"meaning": "用同“癃”", "words": [{"w": "窿笃", "t": "严重的肢体麻痹"}]}, {"meaning": "[方言]煤矿坑道", "words": [{"w": "窿工", "t": ""}, {"w": "清理废窿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3384wx','壁','1','bì','土','16','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从土,辟声。本义:墙壁)。"}, {"meaning": "同本义。", "cites": [{"t": "壁,垣也。", "b": "《说文》"}, {"t": "壁亦土也。", "b": "《风俗通》"}, {"t": "观壁垒于北落兮。", "b": "张衡《思玄赋》"}, {"t": "家徒四壁立。", "b": "《汉书·司马相如传》"}, {"t": "徘徊四顾,见虫伏壁上。", "b": "《聊斋志异·促织》"}], "words": [{"w": "壁有耳", "t": "指机密容易泄露,说话不可不慎。同“隔墙有耳”"}, {"w": "壁中书", "t": "汉武帝时,鲁恭王为扩建其宫室而坏孔子故居,在夹壁墙中得古文《尚书》、《礼记》、《春秋》、《论语》、《孝经》等,凡数十卷,都是周时的古文写的,晋人称为科斗文。今《说文》中所收古文,大部分是依据壁中书"}, {"w": "壁观", "t": "面壁;又指一意禅观,心如墙壁,一切妄想不能侵入。"}]}, {"meaning": "军营;军营的围墙。", "cites": [{"t": "及楚击秦,诸将皆从壁上观。", "b": "《史记·项羽本纪》"}, {"t": "帝(刘邦)晨驰入韩信、张耳壁,夺之军。", "b": "汉·班固《高帝纪上》"}], "words": [{"w": "壁死", "t": "死于营垒之中"}, {"w": "壁门", "t": "军营大门。"}]}, {"meaning": "陡峭的山崖。", "cites": [{"t": "山四面峭壁拔起。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "绝壁;峭壁;壁立千仞", "t": "形容山崖陡峻。"}]}, {"meaning": "二十八宿之一,是北方七宿之一。"}, {"meaning": "边,面。", "cites": [{"t": "一壁道与红娘:看哥哥行问汤药去也。", "b": "元·王实甫《西厢记》"}], "words": [{"w": "壁厢", "t": "边,旁。"}]}, {"meaning": "驻扎。", "cites": [{"t": "魏王恐,使人出晋鄙,留军壁邺。", "b": "《史记·魏公子列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3385wx','避','1','bì','辶','16','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从辵(chuò),辟声。本义:躲开,回避)。"}, {"meaning": "同本义。", "cites": [{"t": "避,回也。", "b": "《说文》"}, {"t": "避,去也。", "b": "《苍颉篇》"}, {"t": "无乃实有所避。", "b": "《国语·周语》"}, {"t": "自云先世避秦时乱。", "b": "晋·陶渊明《桃花源记》"}, {"t": "有书生避雨檐下。", "b": "清·周容《芋老人传》"}], "words": [{"w": "避风雨;避秦", "t": "秦时苛政扰民,人民纷纷逃避而隐居"}, {"w": "避言", "t": "言语谨慎,避免说错话"}, {"w": "避宅", "t": "到处躲藏,不住在家里。"}]}, {"meaning": "离去。", "cites": [{"t": "左右攘辟。", "b": "《礼记·曲礼》。注:“疏远也。”"}, {"t": "桓公避席再拜。", "b": "《吕氏春秋·直谏》。注:“下席也。”"}], "words": [{"w": "避地", "t": "离去,迁居他处以避祸。或指隐遁"}, {"w": "避趋", "t": "离开与接近"}, {"w": "避境", "t": "避离某地,不入其境。"}]}, {"meaning": "逊让 如:避让(谦让;辞让);避贤(让贤);避荣(辞让荣华);避路(让路)。"}, {"meaning": "隐藏。", "cites": [{"t": "避吾亲。", "b": "《史记·袁盎晁错传》。索隐:“隐也。”"}, {"t": "潜避两炮台中。", "b": "《广州军务记》"}], "words": [{"w": "避迹", "t": "隐匿"}, {"w": "避风头", "t": "见形势不利就躲起来。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3386wx','缰','1','jiāng','纟','16','','[{"pinyin": "jiāng", "defs": [{"meaning": "马缰绳。", "cites": [{"t": "缰,马绁也。", "b": "《说文》"}, {"t": "缰,疆也,系之使不得出疆限也。", "b": "《释名·释车》"}, {"t": "青骢白马紫丝缰。", "b": "《乐府诗集》"}], "words": [{"w": "脱缰;信马由缰", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3387wx','缴','1','jiǎo zhuó','纟','16','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关。敫(jī)声。①(zhuó)本义:系在箭上的生丝绳,射鸟用。②缴绕:缠绕,纠缠不清)。"}, {"meaning": "缠绕。", "cites": [{"t": "名家苛察缴绕。", "b": "《汉书·司马相如传》。注:“犹缠绕也。”"}, {"t": "年事渐蹉跎,世缘方缴绕。", "b": "白居易《早梳头诗》"}], "words": [{"w": "缴臁", "t": "绑脚布"}, {"w": "缴壁", "t": "墙帏"}, {"w": "缴绕", "t": "纷乱,纠缠"}, {"w": "缴消", "t": "公事办理完毕后消清手续"}, {"w": "缴缠", "t": "纠缠;缠绕。"}]}, {"meaning": "扭动;搅动。", "cites": [{"t": "用右手向下,把身倒缴着,却把左手拔住上截,把腰只一趁,将那株绿杨树带根拔起。", "b": "《水浒传》"}]}]}, {"pinyin": "zhuó", "defs": [{"meaning": "生丝线。", "cites": [{"t": "缴,生丝缕也。", "b": "《说文》"}]}, {"meaning": "系在箭上的生丝绳。", "cites": [{"t": "思援弓缴而射之。", "b": "《孟子·告子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3388wx','戴','1','dài','戈','17','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。本义:增益)。"}, {"meaning": "同本义。", "cites": [{"t": "分物得增益曰戴。", "b": "《说文》。段玉裁注:“引申之凡加于上皆曰戴。”"}]}, {"meaning": "古国名。故址在今河南省民权县东。", "cites": [{"t": "宋人、蔡人、卫人伐戴。", "b": "《春秋》"}]}, {"meaning": "加在头、颈、面、肩上、胸上。", "cites": [{"t": "戴,覆也。", "b": "《尔雅》"}, {"t": "日抱戴。", "b": "《孝经·援神契》。注:“在上曰戴。”"}, {"t": "戴胜降于桑。", "b": "《礼记·月令》"}, {"t": "垂发戴白。", "b": "《后汉书·邓禹传》。注:“戴白,父母也。”"}, {"t": "颁白者(老人)不负戴于道路矣。", "b": "《孟子·梁惠王上》"}, {"t": "无戴其苍,地履其黄。", "b": "清·梁启超《饮冰室合集》"}, {"t": "戴朱缨宝饰之帽。", "b": "明·宋濂《送东阳马生序》"}, {"t": "闻喜宴独不戴花。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "戴笠", "t": "戴斗笠"}, {"w": "戴头识脸", "t": "有身分,有面子;很有派头"}, {"w": "戴巾的", "t": "指士大夫阶级"}, {"w": "戴假发;戴耳环;戴金戒指;戴盆", "t": "将盆覆戴在头上"}, {"w": "披星戴月", "t": "顶着星星和月亮"}, {"w": "戴白", "t": "满头都是斑白的发丝。形容人老"}, {"w": "她洗了手套,发现它们戴不上了", "t": ""}]}, {"meaning": "拥护,从各方面给予支持。", "cites": [{"t": "庶民不忍,欣戴武王。", "b": "《国语·周语上》"}], "words": [{"w": "爱戴;戴情", "t": "感激他人的诚意"}, {"w": "戴仰", "t": "拥戴仰望"}, {"w": "拥戴", "t": "拥护推戴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3389wx','擦','1','cā','扌','17','','[{"pinyin": "cā", "defs": [{"meaning": "(形声。从手,察声。本义:摩擦)。"}, {"meaning": "同本义。", "cites": [{"t": "那块铁…擦擦儿筋伤!", "b": "《西游记》"}], "words": [{"w": "擦背", "t": "方言。搓澡"}, {"w": "擦肩", "t": "肩膀相摩"}, {"w": "擦拳磨掌", "t": "即“摩拳擦掌”。形容打斗前情绪激愤的样子。"}]}, {"meaning": "揩,拭。", "cites": [{"t": "擦抹桌椅。", "b": "《红楼梦》"}], "words": [{"w": "他用手帕擦鼻子;擦脸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3390wx','藉','1','jí jiè','艹','17','','[{"pinyin": "jí", "defs": [{"meaning": "践踏;欺凌。", "cites": [{"t": "藉贫孱者。", "b": "明·高启《书博鸡者事》"}, {"t": "杀夫子者无罪,藉夫子者不禁。", "b": "《吕氏春秋》"}]}, {"meaning": "进贡。", "cites": [{"t": "无以藉君,与君相忆也。", "b": "南朝梁·吴均《续齐谐记》"}]}, {"meaning": "登记;记。", "cites": [{"t": "藉长幼贫氓之数。", "b": "《晏子春秋》"}]}, {"meaning": "杂乱。", "cites": [{"t": "公门少推恕,鞭朴恣狼藉。", "b": "柳宗元《田家》"}]}, {"meaning": ""}, {"meaning": "藉田 。古代天子、诸侯征用民力耕种的田。", "cites": [{"t": "天子为藉千亩,诸侯为藉百亩。", "b": "《礼记》"}]}, {"meaning": "耕种藉田。", "cites": [{"t": "古之必藉千亩者,礼之饰也。", "b": "唐·柳宗元《非国语上》"}]}, {"meaning": "势位。", "cites": [{"t": "因传柄移藉,使杀生之机、夺予之要在大臣,如是者侵。", "b": "《韩非子》"}]}]}, {"pinyin": "jiè", "defs": [{"meaning": "(形声,从艸,籍声。本义:作衬垫的东西)。"}, {"meaning": "同本义。", "cites": [{"t": "藉,祭藉也。", "b": "《说文》。按,藉之为言席也。"}, {"t": "藉用苇席。", "b": "《仪礼·士虞礼》"}, {"t": "藉乃燔林。", "b": "《列子·黄帝》"}, {"t": "缫藉九寸。", "b": "《周礼·大行人》"}, {"t": "藉用白茅,无咎。", "b": "《易·大过》"}, {"t": "执玉,其有藉者则裼,无藉者则袭。", "b": "《礼记·曲礼》"}]}, {"meaning": "衬垫。", "cites": [{"t": "死者相藉。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "藉茅", "t": "用茅草垫祭品。表示对神的敬意"}, {"w": "藉草枕块", "t": "古时居丧的一种礼节,子从父、母丧时起至下葬一段时间,要睡干草、枕土块,以示哀思"}, {"w": "藉子", "t": "小儿卧处垫的防尿布。"}]}, {"meaning": "坐卧其上。", "cites": [{"t": "藉萋萋之纤草。", "b": "王绰《游天台山赋》。注:“以草荐地而坐曰藉。”"}], "words": [{"w": "藉槀", "t": "坐于草垫之上。"}]}, {"meaning": "抚慰。", "cites": [{"t": "白头无籍在,朱绂有哀怜。", "b": "杜甫《送韦书记赴安西》"}], "words": [{"w": "慰藉", "t": "安慰"}, {"w": "藉在", "t": "依赖,慰藉。"}]}, {"meaning": "“借”的繁体字。", "cites": [{"t": "空籍五岁矣。", "b": "《史记·陈杞世家》。《索隐》曰:“一云:‘籍,借也,谓借失国之后年为五年。’”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3391wx','鞠','1','jū','革','17','','[{"pinyin": "jū", "defs": [{"meaning": "(形声。从革,匊(jú)声。从“革”,表示与皮革有关。本义:古时一种用来踢打玩耍的皮球。最早是结毛而成。后来用毛充填皮囊而成,宋代以后才有充气的皮球)。"}, {"meaning": "同本义。", "cites": [{"t": "鞠,蹋鞠也。", "b": "《说文》"}, {"t": "蹋鞠黄帝所作或曰起战国时。", "b": "贾谊《新书》注"}, {"t": "穿域蹋鞠。", "b": "《史记·卫将军传》。索隐:“鞠戏以皮为之,中实以毛,蹴蹋为戏也。”"}], "words": [{"w": "鞠室", "t": "蹴鞠之所"}, {"w": "鞠场", "t": "毬场"}, {"w": "鞠戏", "t": "古代踢球的游戏"}, {"w": "鞠院", "t": "古球场,有围墙。"}]}, {"meaning": "抚养;生育。", "cites": [{"t": "母兮鞠我。", "b": "《诗·小雅·蓼莪》"}], "words": [{"w": "鞠养", "t": "抚养"}, {"w": "鞠育", "t": "教育抚育。"}]}, {"meaning": "匐匍。", "cites": [{"t": "块兮鞠,当道宿。", "b": "《楚辞》"}]}, {"meaning": "爱。", "cites": [{"t": "鞠爱过于所生。", "b": "《世说新语》"}]}, {"meaning": "审讯或审查。", "cites": [{"t": "令鞠治之。", "b": "《史记·李斯列传》"}, {"t": "鞠狱不实。", "b": "《汉书·景武昭宣元成功臣表》"}, {"t": "今遣廷史与郡鞠狱。", "b": "《汉书·刑法志》。李奇云:鞠,穷也,狱事穷竟也。"}], "words": [{"w": "鞠理", "t": "审理"}, {"w": "鞠治", "t": "问罪"}, {"w": "鞠按", "t": "审问,查证"}, {"w": "鞠治", "t": "审问定罪。"}]}, {"meaning": "告诫,警告。", "cites": [{"t": "陈师鞠旅。", "b": "《诗·小雅·采芑》"}], "words": [{"w": "鞠凶", "t": "告凶,预示灾祸"}, {"w": "鞠旅陈师", "t": "领兵布阵;兴兵。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3392wx','藏','1','cáng zàng','艹','17','','[{"pinyin": "cáng", "defs": [{"meaning": "(形声,臧声。本义:把谷物保藏起来)。"}, {"meaning": "储积,收藏。", "cites": [{"t": "农夫春耕夏耘,秋敛冬藏。", "b": "《墨子·三辩》"}, {"t": "子不闻藏书者乎?", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "矿藏;收藏", "t": "收集保藏。"}]}, {"meaning": "隐匿。", "cites": [{"t": "藏,匿也。", "b": "《说文新附》"}, {"t": "慢藏海盗。", "b": "《易·系辞上》"}, {"t": "即藏其尸,持童抵主人所。", "b": "唐·柳宗元《童区寄传》"}, {"t": "见瓶水之冰,而知天下之寒,鱼鳖之藏也。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "藏掩", "t": "遮盖,隐瞒"}, {"w": "藏拙", "t": "因怕丢丑而不显露自己的技能和意见"}, {"w": "藏娇", "t": "把娇娃藏起来。指娶妾别居"}, {"w": "藏名", "t": "隐匿名声。"}]}]}, {"pinyin": "zàng", "defs": [{"meaning": "收藏财物的府库。", "cites": [{"t": "五曰府,掌官契以治藏。", "b": "《周礼·天官·宰夫》。治藏,藏文书器物。"}, {"t": "晋侯之竖头须,守藏者也。", "b": "《左传·僖公二十四年》"}, {"t": "宝藏兴焉。", "b": "《礼记·中庸》"}, {"t": "俄而范氏之藏大火。", "b": "《列子·黄帝》"}, {"t": "太宗尝发宝藏,令诸女择取之。", "b": "《宋史·太宗七女传》"}], "words": [{"w": "藏吏", "t": "负责宫内府库的官吏"}, {"w": "库藏", "t": "仓库"}, {"w": "藏户", "t": "仓库的出入口"}, {"w": "藏府", "t": "公家的府库。"}]}, {"meaning": "内脏", "cites": [{"t": "酒练五藏。", "b": "汉·枚乘《七发》"}, {"t": "五味者何?曰:五藏。", "b": "《管子·水地》"}, {"t": "百骸九窍六藏。", "b": "《庄子·齐物论》"}, {"t": "吸新吐故以练藏。", "b": "《汉书·王吉传》"}]}, {"meaning": "臟是后起的分别字,以别于“宝藏”的“藏”。", "words": [{"w": "藏府", "t": "人体内脏器官的总称。同脏腑。"}]}, {"meaning": "佛教或道教的经典的总称。", "cites": [{"t": "为景灵使,阅道藏。", "b": "《宋史·王钦若传》"}], "words": [{"w": "藏主", "t": "主持佛事的当家和尚"}, {"w": "三藏", "t": "佛经经典分为经、律、论三个部分,总称“三藏”"}, {"w": "道藏", "t": "道教书籍的总汇"}, {"w": "释藏", "t": "佛教经典的总汇。"}]}, {"meaning": "宝藏。", "cites": [{"t": "只道他掘了藏,原来却做了这样生意,故此有钱。", "b": "《醒世恒言》"}]}, {"meaning": "藏族 。中国少数民族之一。分布于西藏和四川、青海、甘肃等省的部分地区。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3393wx','藐','1','miǎo','艹','17','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从艸,貌声。本义:小,幼稚)。"}, {"meaning": "同本义。", "cites": [{"t": "孤女藐焉始孩。", "b": "潘岳《寡妇赋》"}], "words": [{"w": "藐孤", "t": "弱小的孤儿"}, {"w": "藐躬", "t": "孱弱的躯体"}, {"w": "藐然", "t": "幼小的样子"}, {"w": "藐藐", "t": "幼小的样子。"}]}, {"meaning": "远。", "cites": [{"t": "藐蔓蔓之不可量兮,缥绵绵之不可纡。", "b": "《楚辞·九章·悲回风》"}]}, {"meaning": "轻视。", "cites": [{"t": "曰:“以是藐诸孤辱在大夫,其若之何?”", "b": "《左传·僖公九年》"}, {"t": "说大人则藐之。", "b": "《孟子·尽心下》"}], "words": [{"w": "藐法;藐视;藐玩", "t": "轻视玩忽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3394wx','檬','1','méng','木','17','','[{"pinyin": "méng", "defs": [{"meaning": "——见“柠檬”(níngméng)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3395wx','檐','1','yán','木','17','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从木,詹(zhān)声。本义:屋檐)。"}, {"meaning": "同本义。", "cites": [{"t": "复庙重檐。", "b": "《礼记·明堂位》。注:“重檐,重承壁材也。”"}, {"t": "榆柳荫后檐,桃李罗堂前。", "b": "晋·陶潜《归园田居》"}, {"t": "檐牙高啄(檐牙:屋顶伸出的边沿。高啄:像鸟向高处啄食一样)。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "檐石", "t": "屋檐下的石板"}, {"w": "檐宇", "t": "屋檐"}, {"w": "檐花", "t": "靠近屋檐下边开的花"}, {"w": "檐板", "t": "屋檐板"}, {"w": "檐阴", "t": "屋檐下阳光不到处"}, {"w": "檐梁", "t": "檐下的屋梁"}, {"w": "檐帷", "t": "檐下的帘幕"}, {"w": "檐楣", "t": "屋檐"}, {"w": "檐马", "t": "也称风铃,铁马"}, {"w": "檐铁", "t": "挂在屋檐下的风铃。"}]}, {"meaning": "某些器物上形状像屋檐的部分。", "cites": [{"t": "时逆帽檐风刮顶,旋呵鞭手冻粘须。", "b": "唐·杜荀鹤《早发》"}], "words": [{"w": "帽檐儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3396wx','檀','1','tán','木','17','','[{"pinyin": "tán", "defs": [{"meaning": "(形声。从木,亶(dǎn)声。本义:木名。古书中称檀的木很多,时无定指。常指豆科的黄檀,紫檀(即红木);榆科的青檀)。"}, {"meaning": "同本义。", "cites": [{"t": "檀,檀木也。", "b": "《说文》"}, {"t": "坎坎伐檀兮。", "b": "《诗·魏风·伐檀》"}], "words": [{"w": "檀车", "t": "古代车子多用檀木为之,故称"}, {"w": "檀板", "t": "乐器名。檀木制的拍板"}, {"w": "檀柘", "t": "檀树与柘树"}, {"w": "檀桐", "t": "檀木与桐木"}, {"w": "檀槽", "t": "檀木制成的琵琶、琴等弦乐器上架弦的槽格。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3397wx','礁','1','jiāo','石','17','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从石,焦声。本义:江海中隐现于水面上下的岩石。如暗礁)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3398wx','磷','1','lín','石','17','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从石,粦(lìn)声。本义:薄石)一种氮族非金属多价元素,原子序数15,广泛存在于它的各种化合物中 ——元素符号P。"}, {"meaning": "磷磷,形容岩石、水明净。", "cites": [{"t": "泛泛东流水,磷磷水中石。", "b": "刘桢《赠从弟三首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3399wx','霜','1','shuāng','雨','17','','[{"pinyin": "shuāng", "defs": [{"meaning": "(形声。从雨,相声。本义:在气温降到摄氏零度以下时,近地面空气中水汽的白色结晶)。"}, {"meaning": "同本义。", "cites": [{"t": "霜,露所凝也。士气津液从地而生,薄以寒气则结为霜。", "b": "《说文》"}, {"t": "霜者,天之所以杀也。", "b": "《汉书·董仲舒传》"}, {"t": "履霜坚冰至。", "b": "《易·坤》"}, {"t": "白露为霜。", "b": "《诗·秦风·蒹葭》"}, {"t": "羌管悠悠霜满地,人不寐,将军白发征夫泪。", "b": "宋·范仲淹《渔家傲》"}, {"t": "每寒夜起立,振衣裳,甲上冰霜迸落,铿然有声。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "霜雪", "t": "比喻高洁清白"}, {"w": "霜瓦", "t": "覆盖着白霜的瓦片"}, {"w": "霜旦", "t": "下霜的早晨"}, {"w": "霜甲", "t": "沾着霜的战甲"}, {"w": "霜衣", "t": "寒衣"}, {"w": "霜妃", "t": "指霜"}, {"w": "霜序", "t": "霜降的时序"}, {"w": "霜信", "t": "寒霜将来的信息。也为雁的别名"}, {"w": "霜砧", "t": "寒秋时节的捣衣声"}, {"w": "霜草", "t": "因霜害而枯萎的草;草名,也叫“相思草”"}, {"w": "霜气", "t": "寒霜"}, {"w": "霜鸟", "t": "指在秋冬或日暮时的乌鸦"}, {"w": "霜雪", "t": "霜和雪;比喻心志清纯洁净"}, {"w": "霜雾", "t": "寒气"}, {"w": "霜黄", "t": "指树叶遭受伤害而枯黄的颜色。"}]}, {"meaning": "年岁,年岁的代称。犹言秋。", "cites": [{"t": "客舍并州己十霜,归心日夜忆咸阳。", "b": "贾岛《渡桑乾》"}]}, {"meaning": "如霜的粉末。", "cites": [{"t": "冰盘若琥珀,何以糖霜美?", "b": "苏轼《送金山乡僧归蜀》"}]}, {"meaning": "譬喻白色。", "cites": [{"t": "徒霜镜中发,羞彼鹤上人。", "b": "唐·李白《古风》之四"}], "words": [{"w": "霜毫", "t": "白毫毛笔"}, {"w": "霜鬓", "t": "耳边白发"}, {"w": "霜毛", "t": "形容洁白的羽毛;比喻白发"}, {"w": "霜衣", "t": "形容白鸟的羽毛"}, {"w": "霜色", "t": "白色"}, {"w": "霜侵", "t": "指白发渐渐增多"}, {"w": "霜翎", "t": "白色的羽毛"}, {"w": "霜絮", "t": "白棉絮"}, {"w": "霜蓬", "t": "喻白发"}, {"w": "霜须", "t": "形容须白如霜。"}]}, {"meaning": "比喻高洁。", "cites": [{"t": "心懔懔以怀霜,志眇眇而临云。", "b": "晋·陆机《文赋》"}], "words": [{"w": "霜操", "t": "指高洁的操持"}, {"w": "霜女", "t": "指梅花。比喻其高洁。"}]}, {"meaning": "譬喻冷酷、严峻。", "cites": [{"t": "王思远恒如怀冰,暑月亦有霜气。", "b": "《南史·陆慧晓传》"}], "words": [{"w": "霜法", "t": "严厉的法禁"}, {"w": "霜典", "t": "严厉的法典"}, {"w": "霜威", "t": "指寒霜肃杀的威力;比喻严厉的威势"}, {"w": "霜烈", "t": "比喻严厉"}, {"w": "霜台", "t": "御史台的别称。御史掌职弹劾,为风霜之任,故称。也称“霜署”。"}]}, {"meaning": "譬喻锋利。", "cites": [{"t": "钢镞润,霜刃染。", "b": "左思《吴都赋》"}], "words": [{"w": "霜刀", "t": "指锋利雪亮的刀"}, {"w": "霜刃", "t": "锋利雪亮的刀刃"}, {"w": "霜爪", "t": "指锐利的爪子"}, {"w": "霜矛", "t": "指锋利雪亮的矛"}, {"w": "霜戈", "t": "指锋利雪亮的戈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3400wx','霞','1','xiá','雨','17','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从雨,叚(xiá)声。本义:早晚的彩云) 同本义。", "cites": [{"t": "霞,赤云气也。", "b": "《说文新附》"}, {"t": "落霞与孤鹜齐飞,秋水共长天一色。", "b": "王勃《滕王阁序》"}, {"t": "云霞明灭。", "b": "唐·李白《梦游天姥吟留别》"}, {"t": "失向来之烟霞。", "b": ""}, {"t": "云霞掩映。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "霞举飞升", "t": "道教指修行得道者可由云霞托拥,飞升天界;亦指腾云驾雾"}, {"w": "云霞", "t": "云彩"}, {"w": "霞彩", "t": "云霞的彩光。"}]}, {"meaning": "指像霞一样美丽的光彩。", "cites": [{"t": "瑶波逐穴开,霞石触峰起。", "b": "南朝宋·鲍照《登庐山望石门》"}], "words": [{"w": "霞石", "t": "赤色的岩石"}, {"w": "霞帔", "t": "道家的一种贵重服装,类似披肩,文有霞彩。"}]}, {"meaning": "遥远。", "cites": [{"t": "载营魄而登霞兮,掩浮云而上征。", "b": "《楚辞·屈原·远游》"}, {"t": "霞区两借寇,贪泉一举巵。", "b": "南朝梁·何逊《哭吴兴柳恽》"}], "words": [{"w": "霞志", "t": "高远的志向"}, {"w": "霞区", "t": "边远之地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3401wx','瞭','1','liǎo liào','目','17','','[{"pinyin": "liǎo", "defs": [{"meaning": "(形声。从目,尞(liáo)声。本义:眼珠明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "胸中正,则眸子瞭焉。", "b": "《孟子·离娄上》"}, {"t": "眡瞭三百人。", "b": "《周礼》"}], "words": [{"w": "瞭眊", "t": "眼睛明净与浑浊"}, {"w": "瞭然", "t": "眼明貌。"}]}]}, {"pinyin": "liào", "defs": [{"meaning": "", "words": [{"w": "瞭哨", "t": "望风"}, {"w": "瞭见", "t": "望见"}, {"w": "瞭风", "t": "望风"}, {"w": "瞭高", "t": "在高处瞭望。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3402wx','瞧','1','qiáo','目','17','','[{"pinyin": "qiáo", "defs": [{"meaning": "(形声。从目,焦声。本义:眼昏花) 同本义。", "cites": [{"t": "覩文籍则目瞧,脩揖让则变伛,袭章服则转筋,谭礼典则齿龋。", "b": "三国魏·嵇康《难自然好学论》"}]}, {"meaning": "偷看。", "cites": [{"t": "什么人敢来瞧俺脚色?", "b": "《警世通言》"}], "words": [{"w": "瞧女人", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3403wx','瞬','1','shùn','目','17','','[{"pinyin": "shùn", "defs": [{"meaning": "(形声。从目,舜声。本义:眨眼)。"}, {"meaning": "同本义。", "cites": [{"t": "尔先学不瞬,而后可言射矣。", "b": "《列子·汤问》"}], "words": [{"w": "一瞬", "t": "一眨眼工夫。"}]}, {"meaning": "眼珠转动。", "cites": [{"t": "直视,不能瞬。", "b": "张机《金匮要略》"}]}, {"meaning": "惊恐。同“眴”。", "cites": [{"t": "适见豚子食于其死母者,少焉眴若,皆亲之而走。", "b": "《庄子》。陆德明释文:“眴若,本亦作‘瞬’。司马云:惊貌。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3404wx','瞳','1','tóng','目','17','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。从目,童声。本义:瞳孔)。"}, {"meaning": "同本义  俗称“瞳仁”。眼珠中心虹膜上一个可收缩的孔。", "cites": [{"t": "瞳,目珠子也。", "b": "《玉篇》"}, {"t": "舜目盖重瞳子。", "b": "《史记·项羽本纪》"}], "words": [{"w": "瞳子", "t": "虹膜中心的小圆孔"}, {"w": "瞳神", "t": ""}]}, {"meaning": "看见。", "cites": [{"t": "大嫂兜出檐口放,上瞳格子下瞳人。", "b": "《中国歌谣资料》。原注:“瞳,看见。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3405wx','瞩','1','zhǔ','目','17','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(形声。从目,属声。本义:注视,瞩目)。"}, {"meaning": "同本义。", "cites": [{"t": "眺瞩中原。", "b": "《晋书·桓温传》"}], "words": [{"w": "瞩盼", "t": "注视"}, {"w": "瞩视", "t": "注视。"}]}, {"meaning": "见;看见。", "cites": [{"t": "此其下无地而上无天,听焉无闻,视焉无瞩。", "b": "《淮南子》"}, {"t": "有冢嶙嶙,有池渊渊,不瞩其人,唯余苍烟。", "b": "宋·沈辽《零陵先贤赞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3406wx','瞪','1','dèng','目','17','','[{"pinyin": "dèng", "defs": [{"meaning": "睁大眼睛直视。", "cites": [{"t": "瞪,直视貌。", "b": "《广韵》"}, {"t": "文瞪眸不转。", "b": "《晋书·郭文传》"}, {"t": "齐首目以瞪眄。(眄:斜视)", "b": "王延寿《鲁灵光殿赋》"}], "words": [{"w": "瞪目", "t": "睁大眼睛直视"}, {"w": "瞪瞪", "t": "睁大眼睛直视的样子;发呆的样子。"}]}, {"meaning": "用力睁大。", "cites": [{"t": "瞪,怒目直视貌。", "b": "《玉篇》"}, {"t": "往往瞪视而诟詈之。", "b": "《宋史·盛度传》"}], "words": [{"w": "瞪瞢", "t": "视而不见的样子"}, {"w": "瞪愕", "t": "张目吃惊的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3407wx','曙','1','shǔ','日','17','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从日,署声。本义:天刚亮时) 同本义。", "cites": [{"t": "曙,东方明也。", "b": "《玉篇》"}, {"t": "思不眠以至曙。", "b": "《楚辞·悲回风》"}, {"t": "自昏达日曙,目不交睫。", "b": "《聊斋志异·促织》"}], "words": [{"w": "曙天", "t": "黎明时的天空"}, {"w": "曙日", "t": "朝阳"}, {"w": "曙月", "t": "晓月"}, {"w": "曙更", "t": "黎明的更柝声"}, {"w": "曙角", "t": "拂晓的号角声"}, {"w": "曙河", "t": "拂晓的银河"}, {"w": "曙星", "t": "拂晓之星。多指启明星"}, {"w": "曙风", "t": "晓风。"}]}, {"meaning": "天亮,破晓。", "cites": [{"t": "鸡鸣外欲曙,新妇起严妆。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3408wx','蹋','1','tà','足','17','','[{"pinyin": "tà", "defs": [{"meaning": "践踏;踩。", "cites": [{"t": "蹋,践也。", "b": "《说文》"}, {"t": "蹋,履也。", "b": "《广雅·释诂一》"}]}, {"meaning": "字亦作“踏”。", "cites": [{"t": "舞辄数十人相随,蹋地为节。", "b": "《后汉书·东夷传》"}]}, {"meaning": "踢。", "cites": [{"t": "王傅萨都喇以足蹋人而死。", "b": "《续资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3409wx','蹈','1','dǎo','足','17','','[{"pinyin": "dǎo", "defs": [{"meaning": "(形声。从足,舀(yǎo)声。本义:踩,踏)。"}, {"meaning": "同本义(往往有冒险的意味)。", "cites": [{"t": "蹈,践也。", "b": "《说文》"}, {"t": "蹈,履也。", "b": "《广雅》"}, {"t": "足之蹈之。", "b": "《孟子》"}, {"t": "蹈腾昆仑。", "b": "《淮南子·原道》。注:“蹑也。”"}, {"t": "至人潜行不窒,蹈火不热。", "b": "《庄子·达生》"}, {"t": "羸兵为人马所蹈藉。", "b": "《资治通鉴》"}, {"t": "蹈死不顾。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "蹈火", "t": "踩火"}, {"w": "蹈藉", "t": "践踏"}, {"w": "蹈跃", "t": "践踏奔跳"}, {"w": "蹈冰", "t": "踏冰。"}]}, {"meaning": "顿足踏地。", "cites": [{"t": "发扬蹈历之己蚤。", "b": "《史记·乐书》。正义:“顿足蹋地也。”"}], "words": [{"w": "手舞足蹈;蹈舞", "t": "手舞足蹈,表示欢乐"}, {"w": "蹈咏", "t": "舞蹈和吟唱。"}]}, {"meaning": "遵循。", "cites": [{"t": "后之君子,蹈常而习故。", "b": "苏轼《伊尹论》"}], "words": [{"w": "蹈矩", "t": "投身;依托"}, {"w": "蹈节", "t": "克守节操"}, {"w": "蹈节死义", "t": "遵守节操,为正义而死。"}]}, {"meaning": "实行。", "cites": [{"t": "一理长成,遽躬蹈之。", "b": "清·袁枚《祭妹文》"}, {"t": "而蹈之者常十之八九。", "b": "清·刘开《问说》"}], "words": [{"w": "蹈险", "t": "经历危险"}, {"w": "蹈义", "t": "履行正义"}, {"w": "蹈道", "t": "履行正道。"}]}, {"meaning": "朝某方向走;行。", "cites": [{"t": "故无首虏之获,无蹈难之赏。", "b": "《荀子·儒效》"}], "words": [{"w": "蹈难", "t": "身赴危难"}, {"w": "蹈敌", "t": "赴敌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3410wx','螺','1','luó','虫','17','','[{"pinyin": "luó", "defs": [{"meaning": "(又作蠃。形声。从虫,累声。本义:凡软体动物腹足类,被有旋线的硬壳都叫螺,种类繁多)。"}, {"meaning": "同本义。", "cites": [{"t": "蠃,蜾蠃也。", "b": "《说文》。俗字作螺。"}, {"t": "离…为蠃。", "b": "《易·说卦》"}, {"t": "其民必移就蒲蠃于东海之滨。", "b": "《国语·吴语》。注:“蚌蛤之属。”"}, {"t": "冠无觚蠃之理。", "b": "《淮南子·本经》"}, {"t": "螺,蚌属。", "b": "《广韵》"}, {"t": "舟形似螺,沈行海底。", "b": "王嘉《拾遗记·秦始皇》"}], "words": [{"w": "螺填", "t": "即螺钿"}, {"w": "螺壳", "t": "海螺的外壳"}, {"w": "螺壳钱", "t": "螺壳所制的货币"}, {"w": "螺蚌", "t": "螺与蚌。亦泛指有贝壳的软体动物"}, {"w": "螺甸", "t": "即螺钿"}, {"w": "螺栓帽", "t": "即螺丝帽。也称螺母"}, {"w": "螺舟", "t": "传说形状似螺、能潜行海底的船"}, {"w": "螺首", "t": "刻在桃苻上端的螺形图案"}, {"w": "螺钿", "t": "将螺壳磨治使薄,嵌于雕镂及髹漆的器具上,以作装饰,称为螺钿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3411wx','蟋','1','xī','虫','17','','[{"pinyin": "xī", "defs": [{"meaning": "蟋蟀的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3412wx','蟀','1','shuài','虫','17','','[{"pinyin": "shuài", "defs": [{"meaning": "蟋蟀。", "cites": [{"t": "秋蟀载吟,竞鸣机杼。", "b": "《徐州刺史侯安都德政碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3413wx','嚎','1','háo','口','17','','[{"pinyin": "háo", "defs": [{"meaning": "(形声。从口,豪声。本义:吼叫;鸣叫)。"}, {"meaning": "同本义。", "cites": [{"t": "昼夜风不止,寒树嚎未休。", "b": "梅尧臣《宁陵阻风雨寄都下亲旧》"}], "words": [{"w": "嚎啸", "t": "呼啸"}, {"w": "鸡嚎天欲白", "t": ""}]}, {"meaning": "大声哭喊。同“号”。", "cites": [{"t": "终日嚎而嗌不嗄。", "b": "《老子》"}], "words": [{"w": "嚎呼", "t": "大声哭叫呼唤"}, {"w": "嚎咷", "t": "嚎啕。大声哭"}, {"w": "嚎嚷", "t": "号哭叫嚷"}, {"w": "嚎天动地", "t": "嚎天喊地。大声哭叫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3414wx','赡','1','shàn','贝','17','','[{"pinyin": "shàn", "defs": [{"meaning": "(形声。从贝,詹(zhān)声。本义:供给)。"}, {"meaning": "同本义。", "cites": [{"t": "皆以赡给九族,赏赐军士。", "b": "《晋书·羊祜传》"}], "words": [{"w": "赡家", "t": "养家"}, {"w": "赡育", "t": "赡养抚育"}, {"w": "赡身", "t": "养活自身"}, {"w": "赡私", "t": "赡养身家"}, {"w": "赡用", "t": "供给费用"}, {"w": "赡老", "t": "供养老人。"}]}, {"meaning": "周济;帮助。", "cites": [{"t": "缉盗贼,赡穷困。", "b": "清·黄钧宰《金壶浪墨》"}], "words": [{"w": "赡族义田", "t": "以谷租收入救济本家、同族的田地"}, {"w": "赡账", "t": "资助救济"}, {"w": "赡恤", "t": "救济,抚恤"}, {"w": "赡助", "t": "救济帮助"}, {"w": "赡遗", "t": "周济,赠送"}, {"w": "赡济", "t": "资助;救济。"}]}, {"meaning": "充满。", "cites": [{"t": "故川源不能实漏卮,山海不能赡溪壑。", "b": "《盐铁论·本议》"}]}, {"meaning": "足;充足;足够;才情丰富;满足。", "cites": [{"t": "此惟救死而不赡(这里“不赡”等于说“来不及”),奚暇治礼义哉!", "b": "《孟子·梁惠王上》"}], "words": [{"w": "赡足", "t": "充足"}, {"w": "赡学", "t": "饱学"}, {"w": "赡闻", "t": "见闻丰富"}, {"w": "赡智", "t": "足智多谋"}, {"w": "赡墨", "t": "内容丰富的诗文"}, {"w": "赡畅", "t": "形容诗文内容丰富"}, {"w": "赡蔚", "t": "形容文辞丰美"}, {"w": "赡裕", "t": "丰富,充裕"}, {"w": "赡富", "t": "丰富。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3415wx','穗','1','suì','禾','17','','[{"pinyin": "suì", "defs": [{"meaning": "(会意。从禾,惠声。稻麦等禾本科植物的花或果实聚生在茎上顶端部分。亦泛指穗状花实)。"}, {"meaning": "同本义。", "cites": [{"t": "赪茎素毳,并柯共穗之瑞。", "b": "《曲水诗序》。注;“共穗,嘉禾了。”"}, {"t": "彼黍离离,彼稷之穗。", "b": "《诗·王风·黍离》"}, {"t": "彼有滞穗。", "b": "《诗·小雅·甫田》"}], "words": [{"w": "穗肥", "t": "禾谷作物幼穗分化期施用的追肥,可使幼穗有充足养分,穗大粒多,增加产量"}, {"w": "麦穗", "t": ""}]}, {"meaning": "烛花或灯花。", "cites": [{"t": "时复见残灯,和烟坠金穗。", "b": "韩偓《懒卸头》"}]}, {"meaning": "中国广州市的别称 。古代传说中有五仙人乘五色羊执六穗至此,故称其为“穗”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3416wx','魏','1','wèi','鬼','17','','[{"pinyin": "wèi", "defs": [{"meaning": "阙宫门的台观。", "cites": [{"t": "乃县治象之法于象魏。", "b": "《周礼·太宰》"}, {"t": "魏阙之高。", "b": "《淮南子·本经》"}, {"t": "是以来仪集羽族于观魏。", "b": "汉·班固《典引》"}], "words": [{"w": "象魏", "t": "古代宫门外的阙门"}, {"w": "魏观", "t": "即魏阙、魏象。"}]}, {"meaning": "古国名。"}, {"meaning": "西周时分封的诸侯国。姬姓。在今山西芮城县北。公元前661年被晋献公攻灭,把它封给毕万。"}, {"meaning": "战国七雄之一。开国君主魏文侯(名斯)是毕万后代,和赵韩一起瓜分晋国。公元前403年被周威烈王承认为诸侯。建都安邑(今山西夏县西北)。", "cites": [{"t": "韩魏闻之。", "b": "《战国策·齐策》"}, {"t": "不敢加兵谋魏。", "b": "《史记·魏公子列传》"}, {"t": "灭韩亡魏。", "b": "《战国策·魏策》"}, {"t": "韩魏灭亡。", "b": ""}]}, {"meaning": "三国之一 。公元220—265,曹丕所建,拥有今黄河流域各省和湖北、安徽、江苏北部、辽宁中部。", "cites": [{"t": "无论魏晋。", "b": "晋·陶渊明《桃花源记》"}, {"t": "魏晋氏以下。", "b": "唐·柳宗元《柳河东集》"}]}, {"meaning": "朝代名。"}, {"meaning": "隋末农民起义领袖李密所建国号。"}, {"meaning": "古郡名。", "cites": [{"t": "魏郡,县十八。", "b": "《汉书》"}]}, {"meaning": "今县名 。在河北省南部有魏县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3417wx','簧','1','huáng','竹','17','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从竹,黄声。本义:乐器中用以发声的薄片)。"}, {"meaning": "同本义。", "cites": [{"t": "簧,笙中簧也。", "b": "《说文》"}, {"t": "并坐鼓簧。", "b": "《诗·秦风·车邻》"}, {"t": "调竽笙竾簧。", "b": "《礼记·月令》"}, {"t": "愿假簧以舒忧兮。", "b": "《楚辞·忧苦》"}], "words": [{"w": "簧言", "t": "簧片振鸣。比喻动听的乐声;欺人的谎言"}, {"w": "簧口", "t": "如簧之口。多借指馋言"}, {"w": "簧口利舌", "t": "形容善于言辞,多含贬义。"}]}, {"meaning": "笙,竽。", "cites": [{"t": "簧,笙、竽皆谓之簧。", "b": "《正字通》"}, {"t": "左执簧。", "b": "《诗·王风·扬之水》"}]}, {"meaning": "动听的语言。", "cites": [{"t": "巧言如簧。", "b": "《诗·小雅·巧言》"}, {"t": "使天下簧鼓,以奉不及之法。", "b": "《庄子·骈拇》"}], "words": [{"w": "簧言", "t": "谎言"}, {"w": "簧鼓", "t": "蛊惑;煽动"}, {"w": "簧惑", "t": "比喻以巧言迷惑人"}, {"w": "簧诱", "t": "用巧言诱惑欺骗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3418wx','簇','1','cù','竹','17','','[{"pinyin": "cù", "defs": [{"meaning": "(形声。从竹,族声。本义:小竹丛生)。"}, {"meaning": "同本义。", "cites": [{"t": "簇,小竹丛生也。", "b": "《正字通》"}]}, {"meaning": "丛集;聚集。", "cites": [{"t": "律中太簇,言万物始簇而生。", "b": "《史记·独断》"}, {"t": "微微风簇浪,散作满河星。", "b": "查慎行《舟夜书所见》"}], "words": [{"w": "簇集", "t": "聚集"}, {"w": "簇带", "t": "簇戴。成簇插载"}, {"w": "簇合", "t": "集合,围拢"}, {"w": "簇行", "t": "积叠陈列果物于盘上。"}]}, {"meaning": "相当于“丛”密集的或长在一块儿但不粘在一起的一丛。", "cites": [{"t": "桃花一簇开无主。", "b": "杜甫《江畔独步寻花七绝句》"}], "words": [{"w": "一簇鲜花;一簇红霞;一簇房屋", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3419wx','繁','1','fán pó','糸','17','','[{"pinyin": "fán", "defs": [{"meaning": "字本作“緐”.马头上的饰物.同本义。", "cites": [{"t": "緐,马髦饰也。", "b": "《说文》。段玉裁注:“引申为緐多。又俗改其字作繁,俗形行而本形废,引申之义行而本义废矣。”"}]}, {"meaning": "众多。", "cites": [{"t": "正月繁霜,我心忧伤。", "b": "《诗·小雅·正月》"}, {"t": "奉之弥繁。", "b": "宋·苏洵《权书·六国论》"}, {"t": "善始者始繁,克终者盖寡。", "b": "唐·魏征《谏太宗十思疏》"}], "words": [{"w": "繁剧", "t": "事务繁重"}, {"w": "繁伙", "t": "众多"}, {"w": "繁星", "t": "众多的星星"}, {"w": "繁霜", "t": "浓霜,借喻为白色"}, {"w": "繁言", "t": "多言"}, {"w": "繁虑", "t": "很多的忧虑。"}]}, {"meaning": "复杂。", "cites": [{"t": "见简即用,见繁即变,此乃通术也。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "繁务", "t": "杂事"}, {"w": "繁句", "t": "凡句子中,文法结构比较复杂的,称为繁句"}, {"w": "繁思", "t": "繁杂的思绪。"}]}, {"meaning": "茂盛。", "cites": [{"t": "佳木秀而繁阴。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "繁昌", "t": "形容草木茂盛;形容国家或家族等繁荣昌盛"}, {"w": "繁盛", "t": "繁荣而兴盛;繁多而茂盛。意同繁茂"}, {"w": "繁庑", "t": "形容草木茂盛;泛指兴盛。"}]}, {"meaning": "繁殖,繁衍。", "cites": [{"t": "保你这一庄人家,子孙繁衍,六畜安生。", "b": "《西游记》"}], "words": [{"w": "繁息", "t": "孳生,生长。"}]}]}, {"pinyin": "pó", "defs": [{"meaning": "白色。", "cites": [{"t": "公乘侈舆、服繁驵驱之。", "b": "《晏子春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3420wx','徽','1','huī','彳','17','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,微省声。本义:三纠绳)。"}, {"meaning": "同本义。", "cites": [{"t": "徽,三股绳也。", "b": "《说文》"}, {"t": "系用徽纆。", "b": "《易·坎》。刘注:“三股为徽。”"}]}, {"meaning": "绳索。", "cites": [{"t": "免于徽索。", "b": "《汉书·扬雄传》。注:“绳也。”"}], "words": [{"w": "徽索", "t": "徽绳。捆绑俘虏、罪人的绳索"}, {"w": "徽纆", "t": "绳索;捆绑"}, {"w": "徽缠", "t": "绳索。亦比喻束缚,牵累"}, {"w": "徽绳", "t": "徽索。指捆绑罪人的绳索。"}]}, {"meaning": "琴徽,系琴弦的绳。", "cites": [{"t": "今夫弦者,高张急徽,追趋逐耆,则坐者不期而附矣。", "b": "《汉书·扬雄传》"}]}, {"meaning": "后亦指七弦琴琴面十三个指示音节的标识。", "cites": [{"t": "弦以园客之丝,徽以钟山之玉。", "b": "嵇康《琴赋》"}]}, {"meaning": "旗帜。", "cites": [{"t": "易服色,殊徽号。", "b": "《礼记·大传》"}]}, {"meaning": "绑腿布。", "cites": [{"t": "徽,袤幅也。", "b": "《说文》。段玉裁注:“即《诗》之邪幅也。”"}]}, {"meaning": "美好;善良。", "cites": [{"t": "徽,善也。", "b": "《尔雅·释诂》"}], "words": [{"w": "徽睇", "t": "美丽的眼睛"}, {"w": "徽绩", "t": "美好的功绩"}, {"w": "徽徽", "t": "美好的样子"}, {"w": "徽显", "t": "善美显著。"}]}, {"meaning": "停止;静止。", "cites": [{"t": "悲风徽行轨,倾云结流蔼。", "b": "陆机《挽歌诗》"}]}, {"meaning": "束缚;捆绑。", "cites": [{"t": "徽以纠墨。", "b": "扬雄《解嘲》"}], "words": [{"w": "徽束;徽猛", "t": "束缚猛兽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3421wx','爵','1','jué','爫','17','','[{"pinyin": "jué", "defs": [{"meaning": "(象形。甲骨文字形,象古代饮酒器。本义:古代酒器。青铜制)。"}, {"meaning": "盛酒的礼器,形似雀,青铜制,有流、两柱、三足,用以温酒或盛酒,盛行于殷代和西周初期。", "cites": [{"t": "爵,礼器也。象爵之形,中有鬯酒,又持之也。", "b": "《说文》"}, {"t": "实二爵。", "b": "《仪礼·特牲礼》"}, {"t": "殷以斝,周以爵。", "b": "《仪礼·明堂位》"}, {"t": "洗爵奠斝。", "b": "《诗·大雅·行苇》"}, {"t": "虢公请器,王与之爵。", "b": "《左传·庄公二十一年》"}]}, {"meaning": "爵位,爵号,官位。", "cites": [{"t": "王者之制禄爵。", "b": "《礼记·王制》"}, {"t": "受爵不让。", "b": "《诗·小雅·角弓》"}, {"t": "请卖爵子。", "b": "引汉·贾谊《论积贮疏》"}, {"t": "爵通侯。", "b": "《汉书·李广苏建传》"}, {"t": "高爵显位。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "爵人", "t": "有爵位吃俸禄的人"}, {"w": "爵敕", "t": "分封爵位的敕书"}, {"w": "爵谥", "t": "爵位和谥号"}, {"w": "爵号", "t": "爵位的名号"}, {"w": "爵等", "t": "爵位的等级。"}]}, {"meaning": "一种鸟,赤黑色。", "cites": [{"t": "我有好爵,吾与尔靡之。", "b": "《易·中孚》"}], "words": [{"w": "爵跃", "t": "如雀之跳跃。表示欣喜之极"}, {"w": "爵踊", "t": "足不离地而跳"}, {"w": "爵钗", "t": "雀形的发钗"}, {"w": "爵韦", "t": "赤黑色的韦"}, {"w": "爵室", "t": "古代船上的远望室。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3422wx','朦','1','méng','月','17','','[{"pinyin": "méng", "defs": [{"meaning": "(形声。从月,蒙声。本义:月不明)。"}, {"meaning": "同本义。", "cites": [{"t": "朦,月朦朦也。", "b": "《说文新附》"}, {"t": "空架鼓,枉悬钟,绘壁尘多彩象朦。", "b": "《西游记》"}], "words": [{"w": "朦朦", "t": "微明的样子。"}]}, {"meaning": "迷糊,迷惘。", "cites": [{"t": "空架鼓,枉悬钟,绘壁尘多彩象朦。", "b": "《西游记》"}], "words": [{"w": "朦朦", "t": "迷惘的样子"}, {"w": "朦里朦胧", "t": "迷迷糊糊,不真切,不明了。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3423wx','臊','1','sào sào','月','17','','[{"pinyin": "sào", "defs": [{"meaning": "(形声。从肉(月),(sào)声。本义:腥臊) 同本义。", "cites": [{"t": "臊,豕膏臭也。", "b": "《说文》"}, {"t": "犬赤股而躁臊。", "b": "《周礼·内饔》"}, {"t": "其臭臊。", "b": "《素问·金匮真言论》"}, {"t": "露申辛夷死林薄兮,腥臊并御芳不得薄兮。", "b": "《楚辞·涉江》"}, {"t": "狗若如此,其肉臊恶。", "b": "《礼记·内则》疏"}, {"t": "鼻辨芬芳腥臊。", "b": "《荀子·荣辱》"}], "words": [{"w": "腥臊", "t": "动物体上散发的一种难闻的气味。也比喻为臭恶的小人"}, {"w": "臊腥", "t": "臭恶的气味"}, {"w": "臊秽", "t": "腥臭肮脏的气味"}, {"w": "臊根", "t": "男性生殖器"}, {"w": "臊膻", "t": "腥膻之气。"}]}, {"meaning": "丑恶的。", "cites": [{"t": "臊声布于朝野。", "b": "《北史·抱老寿传》"}, {"t": "其政腥臊。", "b": "《国语·周语上》"}], "words": [{"w": "臊声", "t": "丑闻"}, {"w": "臊子", "t": "臭货。"}]}]}, {"pinyin": "sào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3424wx','鳄','1','è','鱼','17','','[{"pinyin": "è", "defs": [{"meaning": "热带和亚热带水域的几种大型厚皮长体的水栖爬行动物,组成鳄属和一或两个近缘属 ,包括某些贪婪的种类(如尼罗鳄或东亚和太平洋岛屿的巨型河口湾鳄。)这些种类都会毫不迟疑地袭击人类", "words": [{"w": "鳄海", "t": "有鳄鱼出没的海滨"}]}, {"meaning": "钝吻鳄的俗称 。两种属于钝吻鳄属的爬行动物之一", "words": [{"w": "扬子鳄", "t": ""}, {"w": "密河鳄", "t": "密西西比河鳄"}]}, {"meaning": "宽吻鳄的俗称", "words": [{"w": "眼镜鳄", "t": ""}]}]}]','jingmo-wenyan');
