INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3426wx','辫','1','biàn','辛','17','','[{"pinyin": "biàn", "defs": [{"meaning": "交织,编结。也作“编”。", "cites": [{"t": "辮,交也。", "b": "《说文》"}, {"t": "织绳曰辮。", "b": "《通俗文》"}, {"t": "女子头发辫而不垂。", "b": "《梁书·西北诸戎传》"}], "words": [{"w": "辫发", "t": "将头发编成辫子;用作满族代称"}, {"w": "辫髻", "t": "编发成辫,再盘成髻。"}]}, {"meaning": "发辫。分股编紧的头发。", "cites": [{"t": "解辫请职。", "b": "南朝齐·丘迟《与陈伯之书》"}], "words": [{"w": "梳小辫儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3427wx','赢','1','yíng','贝','17','','[{"pinyin": "yíng", "defs": [{"meaning": "(会意。从贝,从贏,赢(yíng)省声。贝,古货币,与财富买卖有关。本义:有余)。"}, {"meaning": "同本义。", "cites": [{"t": "赢,贾有余利也。", "b": "《说文》"}, {"t": "贾而欲赢而恶嚣乎。", "b": "《左传·昭公元年》"}, {"t": "鬻者兼赢。", "b": "张衡《西京赋》"}, {"t": "仓廥空虚,而群县无复赢畜以待用。", "b": "元·吴莱《欧阳氏急就章解后序》"}], "words": [{"w": "赢衍", "t": "丰盈;盈余"}, {"w": "赢财", "t": "余财"}, {"w": "赢畜", "t": "多余财物的积蓄"}, {"w": "赢副", "t": "多余的东西"}, {"w": "赢绌", "t": "盈余和亏损"}, {"w": "赢落", "t": "帐外结余"}, {"w": "赢费", "t": "积余和耗费"}, {"w": "赢数", "t": "余数"}, {"w": "赢阙", "t": "赢余和短缺"}, {"w": "赢粮", "t": "余粮;粮食有余"}, {"w": "赢缩", "t": "有余和不足"}, {"w": "赢藏", "t": "蓄藏的余财。"}]}, {"meaning": "宽缓;松懈。", "cites": [{"t": "大夫君子,昭假无赢。", "b": "《诗·大雅·云汉》。《说文》:“赢,缓也。”"}, {"t": "严断刑,天地始肃,不可以赢。", "b": "《礼记·月令》"}]}, {"meaning": "充裕 。赢获(丰富。充实);赢储(充裕的准备)。"}, {"meaning": "经商盈利。", "cites": [{"t": "赢钱的都已溜回家去睡钱。", "b": "《官场现形记》"}], "words": [{"w": "赢绌", "t": "赢与亏"}, {"w": "赢得猫儿亏了牛", "t": "比喻因小失大"}, {"w": "赢钱", "t": ""}]}, {"meaning": "博赛获胜。与输相对。", "cites": [{"t": "傻大舅输家,没心绪,吃了两碗,便有些醉意,嗔着两个娈童只赶着赢家不理输家了。", "b": "《红楼梦》"}], "words": [{"w": "赢家", "t": "游戏、赌赛等中获胜的一方。"}]}, {"meaning": "天文上五星趋舍而前为赢,退舍为缩。", "cites": [{"t": "岁星赢缩,以其舍命国…其趋舍而前曰赢,退舍曰缩。", "b": "《史记》"}], "words": [{"w": "赢缩", "t": "天文学上称岁星的运行较历法所算超前为赢;落后为缩。"}]}, {"meaning": "博取,获得。", "cites": [{"t": "赢得青楼薄幸名。", "b": "杜牧《遣怀》"}]}, {"meaning": "来得及。", "cites": [{"t": "有时连写也写不赢。", "b": "郭沫若《集外·我的作诗的经过》"}]}, {"meaning": "担。", "cites": [{"t": "赢粮而景从。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "做买卖所获得的利润。", "cites": [{"t": "人有挟仕而商,赋之州县,而倍责赢入,以肥其家。", "b": "元·姚燧《送李茂卿序》"}], "words": [{"w": "赢入", "t": "赢利收入"}, {"w": "赢金", "t": "指经营所获之利"}, {"w": "赢啬", "t": "赢余和不足"}, {"w": "赢赀", "t": "赢余的资金"}, {"w": "赢羡", "t": "赢余;余剩"}, {"w": "赢亏", "t": "赢余和亏损。"}]}, {"meaning": "古邑名 。在今山东省莱芜县西北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3428wx','糟','1','zāo','米','17','','[{"pinyin": "zāo", "defs": [{"meaning": "(形声。从米,曹声。从米,与制酒有关。本义:古指未漉清的带滓的酒。后指酒渣)。"}, {"meaning": "同本义。", "cites": [{"t": "糟,酒滓也。", "b": "《说文》"}, {"t": "共后之致饮于宾客之礼醫酏糟。", "b": "《周礼·酒正》。注:“糟,醫酏之不醫者,醫者曰清。”"}, {"t": "稻醴清糟。", "b": "《礼记·内则》。注:“糟,醇也。”"}, {"t": "邻有糠糟。", "b": "《墨子·公输》"}, {"t": "梁肉之与糠糟。", "b": ""}, {"t": "何不餔其糟。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "糟鼻子", "t": "酒糟鼻;红鼻子"}, {"w": "糟油", "t": "加入甜糟或酒糟调制的油。用来浇拌凉菜或做醮食用"}, {"w": "糟魄", "t": "酒滓。同“糟粕”"}, {"w": "糟坛", "t": "饮酒聚会的地方。即“酒坛”"}, {"w": "糟头", "t": "酒鬼,斥骂喜饮酒的人。"}]}, {"meaning": "以酒或酒糟渍物。", "cites": [{"t": "公不见肉糟淹更堪久邪?", "b": "《晋书·孔群传》"}], "words": [{"w": "糟鱼", "t": "腌后用酒糟渍之,再经烹烧而成的鱼"}, {"w": "糟腌", "t": "糟淹,糟醃。用酒或糟加上盐及其他调味品腌制食品。"}]}, {"meaning": "俗称事物败坏为糟。", "cites": [{"t": "这事更糟了,怎么和尚脑袋上长出辫子来呢?", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3429wx','糠','1','kāng','米','17','','[{"pinyin": "kāng", "defs": [{"meaning": "(形声。从米,康声。本义:从稻、麦等谷皮上脱下的皮、壳)。"}, {"meaning": "本作“穅”,“康”。谷的外壳。", "cites": [{"t": "邻有糠槽而欲窃之。", "b": "《墨子·公输》"}]}, {"meaning": "又。", "cites": [{"t": "此犹梁肉之与糠糟也。", "b": ""}], "words": [{"w": "糠菜半年粮;糠覈", "t": "糠中的粗屑。形容粗糙的饭食"}, {"w": "糠粞", "t": "谷皮碎米。指粗劣的粮食"}, {"w": "糠灯", "t": "一种照明用具。以苏子油渣杂粟糠抟在蓬梗上点燃。旧时吉林民间多用之。"}]}, {"meaning": "小麦种子、黑麦种子或其他禾谷的碎裂皮层,从籽粒上分离出来,特别用于家畜饲料。", "cites": [{"t": "糠和米本是相依倚,被簸扬作两处飞。", "b": "《琵琶记·糟糠自厌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3430wx','燥','1','sào zào','火','17','','[{"pinyin": "sào", "defs": [{"meaning": "快。", "cites": [{"t": "从此以后,匡超人的肉和豆腐都卖得生意又燥,不到日中就卖完了,把钱拿来家伴着父亲。", "b": "《儒林外史》"}]}]}, {"pinyin": "zào", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义(没有水分或水分很少)。", "cites": [{"t": "燥,干也。", "b": "《说文》"}, {"t": "火就燥。", "b": "《易·文言传》"}, {"t": "燥,焦也。", "b": "《释名》"}, {"t": "唇焦口燥呼不得。", "b": "唐·杜甫《茅屋为秋风所破歌》"}, {"t": "燥荻枯柴。", "b": "《资治通鉴》"}], "words": [{"w": "燥吻", "t": "干燥的嘴唇"}, {"w": "燥坼", "t": "干燥坼裂"}, {"w": "燥劲", "t": "干燥强劲"}, {"w": "燥刚", "t": "干燥刚劲"}, {"w": "燥气", "t": "干燥之气"}, {"w": "燥急", "t": "干渴得利害"}, {"w": "燥渴", "t": "口渴。"}]}, {"meaning": "焦急,焦躁。", "cites": [{"t": "往往燥心污笔。", "b": "宋·刘克庄《江西诗派小序》"}], "words": [{"w": "燥暴", "t": "暴躁;急躁"}, {"w": "燥灼", "t": "焦急如焚"}, {"w": "燥急", "t": "焦躁不安。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3431wx','懦','1','nuò','忄','17','','[{"pinyin": "nuò", "defs": [{"meaning": "(形声。从心,需声。本义:胆小,含有软弱之意;弱)。"}, {"meaning": "同本义。", "cites": [{"t": "懦,驽弱者也。", "b": "《说文》"}, {"t": "少懦于诸侯。", "b": "《国语·晋语》"}, {"t": "而性懦愚,沉于国家大事,开罪于先生。", "b": "《战国策·齐策》"}, {"t": "宫之奇之为人也,懦而不能强谏。", "b": "《左传·僖公二年》"}, {"t": "众皆笑其懦,不青坚守。", "b": "《三国演义》"}, {"t": "懦者必怒。", "b": "唐·韩愈《原毁》"}]}, {"meaning": "又。", "cites": [{"t": "懦者必悦。", "b": ""}], "words": [{"w": "懦小", "t": "懦弱胆小"}, {"w": "懦弛", "t": "软弱懈怠"}, {"w": "懦退", "t": "软弱畏缩"}, {"w": "懦恧", "t": "软弱"}, {"w": "懦软", "t": "软弱"}, {"w": "懦庸", "t": "软弱庸陋"}, {"w": "懦谨", "t": "胆小谨慎"}, {"w": "懦善", "t": "软弱善良"}, {"w": "懦衿", "t": "文弱书生。"}]}, {"meaning": "幼小。", "cites": [{"t": "还是我年懦,容得你。", "b": "《西游记》"}]}, {"meaning": "懦夫,软弱无能的人。", "cites": [{"t": "声节哀有余,夫何激衰懦。", "b": "唐·杜甫《舟中苦热遣怀》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3432wx','豁','1','huō huó huò','谷','17','','[{"pinyin": "huō", "defs": [{"meaning": "空缺;露出缺口;缺损", "words": [{"w": "豁齿", "t": "牙齿残缺脱落"}, {"w": "豁牙锯齿", "t": "器物边口残破缺损,形同锯齿"}, {"w": "豁牙", "t": "器物边口的残破处"}]}, {"meaning": "裂开;割裂", "words": [{"w": "豁口截舌", "t": "撕开嘴巴,截去舌头。意为命人住嘴"}]}, {"meaning": "舍弃,狠心付出某种代价", "words": [{"w": "豁出性命", "t": ""}, {"w": "豁脱", "t": "豁出;花费"}, {"w": "豁撒", "t": "抛撒;挥霍"}, {"w": "豁平", "t": "舍弃"}]}, {"meaning": "[方言] 跨", "words": [{"w": "豁上马背", "t": "跨上马背"}]}, {"meaning": "[方言] 指草和庄稼混长在一起,把土地糟蹋了", "words": [{"w": "地豁了", "t": "地被长在庄稼中的草糟蹋了"}]}]}, {"pinyin": "huó", "defs": [{"meaning": "饮酒时的一种博戏。两人同时喊数并伸出拳指,以所喊数目与双方伸出拳指之和数相符者为胜,败者罚饮"}]}, {"pinyin": "huò", "defs": [{"meaning": "(形声。从谷,害声。本义:前后相通的山谷) 同本义。", "cites": [{"t": "豁,通谷也。", "b": "《说文》"}, {"t": "豁险吞若巨防。", "b": "左思《蜀都赋》"}, {"t": "谽豁。", "b": "《史记·司马相如传》。郭注:“涧谷之形容也。”司马彪注:“空虚也。”"}], "words": [{"w": "长豁", "t": "长而通畅的山谷。"}]}, {"meaning": "开阔;开通。", "cites": [{"t": "开南端之豁达。", "b": "何晏《景福殿赋》注:“门通。”"}, {"t": "豁然开朗。", "b": "陶潜《桃花源记》"}, {"t": "其壑北向颇豁。", "b": "《徐霞客游记·滇游日记》"}], "words": [{"w": "豁落", "t": "广大开通的样子"}, {"w": "豁尔", "t": "开阔;开朗"}, {"w": "豁眼", "t": "开阔视野"}, {"w": "豁如", "t": "开阔;旷达;阔大。"}]}, {"meaning": "豁达;大度。", "cites": [{"t": "意豁如也。", "b": "《史记·高祖纪》。服注:“达也。”"}], "words": [{"w": "豁豁", "t": "胸怀坦荡、开朗"}, {"w": "豁绰", "t": "豁达宽厚"}, {"w": "豁荡", "t": "豁达"}, {"w": "豁落", "t": "豁达大方。"}]}, {"meaning": "空;空虚。", "cites": [{"t": "则耳豁极。", "b": "《吕氏春秋·适音》。注:“虚也。”"}], "words": [{"w": "豁关", "t": "空虚防守不严的关口。"}]}, {"meaning": "消散。", "cites": [{"t": "集若霞布,散若云豁。", "b": "郭璞《江赋》"}], "words": [{"w": "云豁", "t": "云彩消散。"}]}, {"meaning": "使某人免罪或免除(处罚)。", "words": [{"w": "豁宿", "t": "免除值夜"}, {"w": "豁除", "t": "免除"}, {"w": "豁略", "t": "免除"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3433wx','臀','1','tún','月','17','','[{"pinyin": "tún", "defs": [{"meaning": "屁股。", "cites": [{"t": "臀,尻也。", "b": "《声类》"}, {"t": "姤臀元肤,困。臀困于株木。", "b": "《易·夬》"}, {"t": "故名之曰黑臀。", "b": "《国语·周语》"}], "words": [{"w": "臀杖", "t": "刑罚名。打屁股。"}]}, {"meaning": "器物底部,底。", "cites": [{"t": "其臀一寸,其实一豆。", "b": "《周礼·考工记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3434wx','臂','1','bei bì','月','17','','[{"pinyin": "bei", "defs": [{"meaning": "——见“胳臂”(gēbei)。"}]}, {"pinyin": "bì", "defs": [{"meaning": "(形声。从肉,辟声。本义:胳膊)。"}, {"meaning": "胳臂。", "cites": [{"t": "臂,手上也。", "b": "《说文》"}, {"t": "肱谓之臂。", "b": "《广雅·释亲》"}, {"t": "肩臂。", "b": "《仪礼·少牢礼》。注:“肱骨。”"}, {"t": "奋袖出臂。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "臂缚", "t": "古时缚在两臂以抵御兵刃的铠甲。也称“臂手”"}, {"w": "臂纱", "t": "缠手臂的纱布。"}]}, {"meaning": "动物的前肢。", "cites": [{"t": "滑水其中多水马,其状如马文臂。", "b": "《山海经·北山经》。注:“前脚也。”"}, {"t": "以汝为虫臂乎?", "b": "《庄子·大宗师》"}], "words": [{"w": "长臂猿;螳臂当车;臂臑", "t": "牲畜前体的中下部。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3435wx','翼','1','yì','羽','17','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从羽,異(yì)声。《说文》小篆从飞,異声。本义:翅膀)。"}, {"meaning": "同本义。", "cites": [{"t": "翼,翅也。", "b": "《说文》"}, {"t": "六足四翼。", "b": "《战国策·楚策》"}, {"t": "三年不翅,将以长羽翼。", "b": "《韩非子·喻老》"}, {"t": "南方有比翼鸟焉。", "b": "《尔雅》"}, {"t": "振鳞奋翼。", "b": "宋玉《高唐赋》"}], "words": [{"w": "翼虎", "t": "添上翅膀的老虎"}, {"w": "翼张", "t": "如鸟展翅。形容分布的样子"}, {"w": "翼膀", "t": "翅膀"}, {"w": "翼翮", "t": "翅膀。"}]}, {"meaning": "鸟的翅膀。", "cites": [{"t": "明夷于飞,垂其翼。", "b": "《易·明夷》"}]}, {"meaning": "昆虫的翅膀。", "cites": [{"t": "以翼鸣者。", "b": "《周礼》"}]}, {"meaning": "一个队形(如战线、散兵线、行进纵队)左侧或右侧。", "cites": [{"t": "韩、魏翼而击之。", "b": "《韩非子·十过》"}], "words": [{"w": "从左右两翼夹攻敌人;翼室", "t": "路寝旁的左右室。路寝为天子或诸侯的正室"}, {"w": "翼卫", "t": "辅翼护卫。"}]}, {"meaning": "辅助。", "cites": [{"t": "予欲左右民,汝翼。", "b": "《书·益稷》"}], "words": [{"w": "翼扶", "t": "辅佐,扶助"}, {"w": "翼助", "t": "辅助"}, {"w": "翼佐", "t": "辅佐"}, {"w": "翼善", "t": "辅助善行"}, {"w": "翼辅", "t": "辅佐"}, {"w": "翼成", "t": "辅助完成,助成"}, {"w": "翼宣", "t": "辅助并加以发扬"}, {"w": "翼亮", "t": "辅佐并发扬光大"}, {"w": "翼戴", "t": "辅助拥戴。"}]}, {"meaning": "遮护。", "cites": [{"t": "鸟覆翼之。", "b": "《诗·大雅·生民》"}, {"t": "项伯亦拔剑起舞,常以身翼蔽沛公,庄不得击。", "b": "《史记·项羽本纪》"}], "words": [{"w": "翼瓦", "t": "屋瓦整齐铺列,如鸟翼相覆"}, {"w": "翼蔽", "t": "像鸟用翅膀那样遮黄海掩护"}, {"w": "翼卵", "t": "以翼覆卵。喻抚育。"}]}, {"meaning": ",第二天。", "cites": [{"t": "越翼日乙丑,王崩。", "b": "《书·顾命》"}, {"t": "王翼日乃瘳。", "b": "《书·金滕》"}, {"t": "翼日进宰,宰见其小,怒呵成。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3436wx','骤','1','zhòu','马','17','','[{"pinyin": "zhòu", "defs": [{"meaning": "(形声。从马,聚声。本义:马奔驰)。"}, {"meaning": "同本义。", "cites": [{"t": "骤,马疾步也。", "b": "《说文》"}, {"t": "车骤徒趋。", "b": "《周礼·大司马》"}, {"t": "步及骤处兮。", "b": "《楚辞·招魂》。注:“走也。”"}, {"t": "车驱而驺(骤)。", "b": "《礼记·曲礼》"}, {"t": "驾彼四骆,载骤骎骎。", "b": "《诗·小雅·四牡》"}], "words": [{"w": "骤骥", "t": "疾驰的骏马。"}]}, {"meaning": "使马奔驰。", "cites": [{"t": "遇春骤马追到,便活擒于马上。", "b": "《英烈传》"}], "words": [{"w": "骤马", "t": "策马奔驰。"}]}, {"meaning": "泛指奔驰。", "cites": [{"t": "麋鹿见之快骤。", "b": "《庄子》"}]}, {"meaning": "迅疾,猛快。", "cites": [{"t": "杞伯于是骤朝于晋。", "b": "《左传·成公十八年》"}, {"t": "飘风不终朝,骤雨不终日。", "b": "《老子》二十章"}, {"t": "骤雨初歇。", "b": "宋·柳永《雨霖铃》"}, {"t": "骤视之。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "骤膺", "t": "迅速接受"}, {"w": "骤雨", "t": "暴雨"}, {"w": "骤步", "t": "快走"}, {"w": "骤进", "t": "快速前进"}, {"w": "骤淹", "t": "迅速消失"}, {"w": "骤兴", "t": "迅速兴起"}, {"w": "骤断", "t": "迅速决断。"}]}, {"meaning": "突然。", "cites": [{"t": "倘魏兵骤至,四面围定,将何策保之?", "b": "《失街亭》"}], "words": [{"w": "骤见", "t": "突然相见"}, {"w": "骤面", "t": "突然见面"}, {"w": "天气骤变;狂风骤起;骤寒", "t": "天气突然变冷。"}]}, {"meaning": "屡次。", "cites": [{"t": "宣子骤谏。", "b": "《左传·宣公二年》"}], "words": [{"w": "骤胜", "t": "屡胜"}, {"w": "骤战", "t": "屡战"}, {"w": "骤谏", "t": "屡次进谏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3437wx','藕','1','ǒu','艹','18','','[{"pinyin": "ǒu", "defs": [{"meaning": "莲的地下茎,肥大有节,中间有管状小孔,可以吃,也可作中药。", "cites": [{"t": "莲实与藕。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "藕心", "t": "古代钱币名称,汉时所铸,四方而有孔,形似破藕"}, {"w": "藕灰", "t": "藕色"}, {"w": "藕合", "t": "藕荷"}, {"w": "藕荷", "t": "浅紫而略带红的颜色"}, {"w": "藕色", "t": "浅灰而略带红的颜色"}, {"w": "藕花", "t": "即荷花。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3438wx','鞭','1','biān','革','18','','[{"pinyin": "biān", "defs": [{"meaning": "(形声。从革,便声。本义:皮制的马鞭)。"}, {"meaning": "同本义  泛指鞭子。", "cites": [{"t": "鞭,驱也。", "b": "《说文》"}, {"t": "其左执鞭弭。", "b": "《国语·晋语》"}, {"t": "虽鞭之长,不及马腹。", "b": "《左传·宣公十五年》"}, {"t": "北市买长鞭。", "b": "《乐府诗集·木兰诗》"}, {"t": "骏马不劳鞭。", "b": "唐·李白《赠友人》"}], "words": [{"w": "鞭影", "t": "马鞭的影子。后以比喻警戒策勉"}, {"w": "鞭镫", "t": "马鞭与马镫"}, {"w": "鞭弭", "t": "马鞭和弓。"}]}, {"meaning": "竹根。", "cites": [{"t": "新鞭暗入庭,初长两三茎。", "b": "张蠙《新竹》"}], "words": [{"w": "鞭笋", "t": "植物名。指竹子的根茎生长于地下"}, {"w": "鞭茁", "t": "初生的鞭笋。"}]}, {"meaning": "打马。泛指鞭打。", "cites": [{"t": "使造父操右革而鞭笞之。", "b": "《韩非子·外储说右下》"}], "words": [{"w": "鞭牛", "t": "鞭打春牛以示迎春"}, {"w": "鞭石", "t": "用鞭击石"}, {"w": "鞭草", "t": "以鞭击草"}, {"w": "鞭楚", "t": "用黄荆木条鞭打人。"}]}, {"meaning": "古刑名。鞭笞罪人的刑罚。", "cites": [{"t": "乃掘楚平王墓,出其尸,鞭之三百,然后曰。", "b": "《史记·伍子胥列传》"}], "words": [{"w": "鞭尸", "t": "以鞭抽打尸体。指严厉责罚已死的罪人"}, {"w": "鞭墓", "t": "即鞭尸"}, {"w": "鞭刑", "t": "古时用鞭子抽打犯人的刑法。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3439wx','藤','1','téng','艹','18','','[{"pinyin": "téng", "defs": [{"meaning": "(形声。从艹,滕声。本义:木本蔓生植物的枝茎) 同本义。", "cites": [{"t": "石角钩衣破,藤枝刺眼新。", "b": "杜甫《奉陪郑驸马韦曲》"}, {"t": "丹藤翠蔓。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "交加之藤。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "藤杯", "t": "滕制的酒杯。也特指酒杯藤的花,因可当作酒杯用而得名"}, {"w": "藤子", "t": "某些植物的匍匐茎或攀援茎,可编制器物"}, {"w": "藤牌", "t": "藤制的盾牌"}, {"w": "藤鼓", "t": "鼓的一种。由藤蒙皮制成"}, {"w": "藤轮", "t": "藤制的靠枕"}, {"w": "藤萝", "t": "紫藤的通称"}, {"w": "藤纸", "t": "古时用藤皮造的纸"}, {"w": "藤椅;藤床;藤篮;葡萄藤;瓜藤;爬藤", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3440wx','覆','1','fù','覀','18','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。覆盖,復声。本义:翻转,倾覆)。"}, {"meaning": "同本义。", "cites": [{"t": "见若覆夏屋者矣。", "b": "《礼记·檀弓》。注:“谓茨瓦也。”"}, {"t": "载舟覆舟,所宜深慎。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "覆舟斟寻。", "b": "《楚辞·天问》"}, {"t": "覆杯水于坳堂之上。", "b": "《庄子·逍遥游》"}, {"t": "虽天地覆坠。", "b": "《庄子·德充符》"}, {"t": "前车覆,后车诫。", "b": "《汉书·贾谊传》"}], "words": [{"w": "覆盆", "t": "翻扣的盆子。比喻蒙冤不能辩白"}, {"w": "覆手", "t": "把手反转过来。比喻事情容易办到"}, {"w": "覆杯", "t": "倒置的杯子;倾杯畅饮"}, {"w": "覆水", "t": "已倒出的水。喻事已成定局"}, {"w": "覆篑", "t": "倒一筐土"}, {"w": "覆醢", "t": "倒去肉酱"}, {"w": "覆酱烧薪", "t": "极言著作无价值或不受重视"}, {"w": "覆瓶", "t": "喻著作毫无价值,不被重视。"}]}, {"meaning": "覆盖;遮蔽。", "cites": [{"t": "庑下一生伏案卧,文方成草。公阅毕,即解貂覆生,为掩户。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "以衾拥覆,久而乃和。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "被覆", "t": "遮盖;蒙"}, {"w": "覆荐", "t": "覆盖铺垫"}, {"w": "覆罩", "t": "覆盖笼罩"}, {"w": "覆裹", "t": "覆盖包裹"}, {"w": "覆墓", "t": "把土覆在墓上。也指扫墓"}, {"w": "覆帱", "t": "遮盖。"}]}, {"meaning": "颠覆;灭亡。", "cites": [{"t": "括既行,代廉颇三十余日,赵兵果败,括死军覆。", "b": "汉·刘向《列女传》"}], "words": [{"w": "覆邦", "t": "亡国"}, {"w": "覆亡", "t": "灭亡"}, {"w": "覆陈", "t": "覆军败阵,败仗"}, {"w": "覆军", "t": "覆灭全军"}, {"w": "覆族", "t": "灭族"}, {"w": "覆国", "t": "亡国"}, {"w": "覆师", "t": "覆灭全军。"}]}, {"meaning": "保护;庇护。", "cites": [{"t": "诞置之寒冰,鸟覆翼之。", "b": "《诗·大雅·生民》"}], "words": [{"w": "覆庇", "t": "关怀;照顾;袒护;包庇"}, {"w": "覆庇", "t": "庇护;保佑"}, {"w": "覆荫", "t": "庇护"}, {"w": "覆帱", "t": "犹覆被。谓施恩,加惠"}, {"w": "覆露", "t": "荫庇。"}]}, {"meaning": "(fū)。孵化。", "cites": [{"t": "卵待覆二十日而后能为雏。", "b": "《春秋繁露·实性》"}]}, {"meaning": "还,返回。", "cites": [{"t": "终日乾乾,反覆道也。", "b": "《易·乾卦》"}, {"t": "赏赐决于外,不从中覆也。", "b": "《汉书·冯唐传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3441wx','瞻','1','zhān','目','18','','[{"pinyin": "zhān", "defs": [{"meaning": "(形声。从目,詹(zhān)声。本义:向远处或向高处看)。"}, {"meaning": "同本义。", "cites": [{"t": "瞻,临视也。", "b": "《说文》"}, {"t": "瞻,视也。", "b": "《尔雅》"}, {"t": "瞻望弗及。", "b": "《诗·邶风·燕燕》"}, {"t": "瞻彼日月。", "b": "《诗·邶风·雄雉》"}, {"t": "瞻前而顾后兮。", "b": "《楚辞·离骚》。注:“观也。”"}, {"t": "不狩不猎,胡瞻尔庭有悬狟兮?", "b": "《诗·魏风·伐檀》"}, {"t": "乃瞻衡宇,载欣载奔。", "b": "晋·陶潜《归去来兮辞》"}, {"t": "乃瞻衡宇。", "b": ""}, {"t": "细瞻景状。", "b": "《聊斋志异·促织》"}], "words": [{"w": "观瞻", "t": "外观和对外观发生的反应"}, {"w": "高瞻远瞩;瞻略", "t": "谋略;智谋"}, {"w": "瞻眄", "t": "观看,察看"}, {"w": "瞻相", "t": "观察"}, {"w": "瞻视", "t": "观看;顾盼"}, {"w": "瞻察", "t": "观察"}, {"w": "瞻览", "t": "观看,观览。"}]}, {"meaning": "仰慕。", "cites": [{"t": "维此惠君,民人所瞻。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "瞻谒", "t": "瞻仰晋见"}, {"w": "瞻迎", "t": "瞻仰欢迎"}, {"w": "瞻奉", "t": "恭敬侍奉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3442wx','蹦','1','bèng','足','18','','[{"pinyin": "bèng", "defs": [{"meaning": "双脚并拢跳。泛指跳跃;乱动", "words": [{"w": "蹦跶", "t": "奔跑跳动"}, {"w": "蹦跳", "t": "双脚离开地面地向前跳跃"}]}, {"meaning": "[方言]决裂"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3443wx','嚣','1','xiāo','口','18','','[{"pinyin": "xiāo", "defs": [{"meaning": "(会意。从棘,从页。棘(jí),众口。页,人头。表示众口喧嚣。本义:喧哗,声音响而闹哄)。"}, {"meaning": "同本义。", "cites": [{"t": "嚣,嚣声也。气出头上。", "b": "《说文》"}, {"t": "禁其门嚣者。", "b": "《周礼·司武虎》"}, {"t": "在陈而嚣。", "b": "《左传·成公十六年》"}, {"t": "湫隘嚣尘。", "b": "《左传·昭公三年》"}, {"t": "而以金石匏竹之昌大嚣庶为乐。", "b": "《国语·楚语》"}, {"t": "选徒嚣嚣。", "b": "《诗·小雅·车攻》"}, {"t": "甚嚣,且尘上矣。", "b": "《左传·成公十六年》"}, {"t": "叫嚣乎东西,隳突乎南北。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "嚣争", "t": "吵闹;争夺"}, {"w": "嚣湫", "t": "尘嚣渊隘"}, {"w": "嚣鄙", "t": "喧闹鄙俗"}, {"w": "嚣号", "t": "喧嚷。"}]}, {"meaning": "害臊;害羞。", "cites": [{"t": "店主起来作揖,说与谭绍闻道喜,绍闻嚣的耳朵稍都是红的。", "b": "《歧路灯》"}]}, {"meaning": "轻浮;轻薄。", "cites": [{"t": "形色嚣然,自矜得遇滋甚。", "b": "《三国志》"}], "words": [{"w": "嚣幸", "t": "轻怠"}, {"w": "嚣了头", "t": "薄了面子;搁不住脸。"}]}, {"meaning": "饥饿。", "cites": [{"t": "农业有废,百姓嚣然。", "b": "《三国志》"}], "words": [{"w": "嚣然", "t": "饥饿的样子。"}]}, {"meaning": "嚣张;强悍。", "cites": [{"t": "秦恶其嚣而坑儒,师吏以重抑之。", "b": "《宋讼》"}], "words": [{"w": "嚣然", "t": "神态轻狂、高傲的样子"}, {"w": "嚣威", "t": "指母亲对子女凶悍暴虐的态度。"}]}, {"meaning": "悠闲自得。", "cites": [{"t": "嚣然而乐世。", "b": "《南轩记》"}], "words": [{"w": "嚣人", "t": "闲人"}, {"w": "嚣嚣", "t": "自得无欲的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3444wx','镰','1','lián','钅','18','','[{"pinyin": "lián", "defs": [{"meaning": "(形声。从金,廉声。本义:农具名。即“镰刀”)。"}, {"meaning": "同本义。", "cites": [{"t": "镰,锲也。", "b": "《说文》"}, {"t": "刈钩自关而西或谓之镰。", "b": "《方言五》"}], "words": [{"w": "佩镰;两刃镰;开镰收割的季节,村里人都很忙", "t": ""}]}, {"meaning": "锋利的棱角。", "cites": [{"t": "凡箭镞胡合嬴者四镰。", "b": "《方言九》。注:“棱也。”"}], "words": [{"w": "镰利", "t": "比喻议论或笔锋锐利如镰刀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3445wx','翻','1','fān','羽','18','','[{"pinyin": "fān", "defs": [{"meaning": "(形声。从羽,番声。本义:鸟飞)。"}, {"meaning": "同本义。", "cites": [{"t": "青菰临水映,白鸟向山翻。", "b": "王维《辋川闲居》"}], "words": [{"w": "翻泊", "t": "或飞或止"}, {"w": "翻翔", "t": "翻飞,飞翔"}, {"w": "翻簸", "t": "飞驰。"}]}, {"meaning": "翻转;翻腾。", "cites": [{"t": "波翻晓霞影。", "b": "李白《姑熟十咏》"}], "words": [{"w": "翻滚滚", "t": "上下急速滚动的样子"}, {"w": "翻海", "t": "形容声响如海浪翻腾"}, {"w": "翻雪", "t": "形容白浪翻滚"}, {"w": "翻扑", "t": "翻腾。"}]}, {"meaning": "反转,倾倒,变动位置。", "cites": [{"t": "钿头银篦击节碎,白色罗裙翻酒污。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "多少好汉被蒙汗酒麻翻了。", "b": "《水浒传》"}], "words": [{"w": "翻席", "t": "吃完一席,再到他处吃另一席"}, {"w": "翻台", "t": "嫖客在一妓院宴毕,再到另一妓院饮宴"}, {"w": "翻手", "t": "翻转手掌。形容时光迅速或处事轻便。"}]}, {"meaning": "演唱;演奏。", "cites": [{"t": "八百里分麾下炙,五十弦翻塞外声。", "b": "宋·辛弃疾《破阵子》"}], "words": [{"w": "翻出", "t": "演奏。"}]}, {"meaning": "表示转折,相当于“反而”、“却”。", "cites": [{"t": "秦人半作燕地囚,胡马翻衔洛阳草。", "b": "唐·李白《猛虎行》"}], "words": [{"w": "翻调", "t": "反正。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3446wx','鳍','1','qí','鱼','18','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从鱼,耆声。本义:鱼类和某些其他水生动物的类似翅或桨的附肢)。"}, {"meaning": "起着推进、平衡及导向的作用。按其所在部位,可分为背鳍、臀鳍、尾鳍、胸鳍和腹鳍。", "words": [{"w": "鳍棘", "t": "支撑鱼鳍薄膜的棘刺状硬骨。又叫鳍鬣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3447wx','鹰','1','yīng','鸟','18','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从鸟。本义:鹰属的各种鸟) 同本义 许多白天活动的隼形目(Falconiformes)隼亚目(Falcones)猛禽,是鹰科(Accipitridae)部分种类鸟的通称,一般指鹰属各种鸟。", "cites": [{"t": "鹰翅疾如风,鹰爪利如锥。", "b": "唐·白居易《放鹰》"}], "words": [{"w": "鹰鸷", "t": "猛禽"}, {"w": "鹰人", "t": "驯鹰的人"}, {"w": "鹰师", "t": "训练老鹰的人"}, {"w": "鹰架", "t": "用竹木制成、用来提取重物的支架;亦指老鹰栖立的架子"}, {"w": "鹰拿燕雀", "t": "比喻容易攫取捕捉"}, {"w": "鹰觑鹘望", "t": "形容眼光如鹰鹘般锐利。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3448wx','瀑','1','bào pù','氵','18','','[{"pinyin": "bào", "defs": [{"meaning": "(形声。从火,虹声。本义:爆烈)。"}, {"meaning": "急雨,暴风雨。", "cites": [{"t": "瀑,疾雨也。《诗》曰:“终风且瀑”。", "b": "《说文》"}]}, {"meaning": "水名。明、清时名宽门、豹河,今名瀑河 。在河北省东北部,发源于平泉县北,南流经宽城入滦河。"}, {"meaning": "一种烹调法。将肉食切好,用开水略煮或用热油快煎,以便食用。今作“爆”。", "cites": [{"t": "煮瀑得熟,也得充饥。", "b": "《水浒传》"}]}]}, {"pinyin": "pù", "defs": [{"meaning": "(形声。从水,暴声,(bào)本义:急雨) 瀑布。", "cites": [{"t": "瀑,疾雨也。", "b": "《说文》"}, {"t": "终风且瀑。", "b": "《诗·邶风·终风》"}], "words": [{"w": "瀑水", "t": "谓瀑布"}, {"w": "瀑泉", "t": "瀑布"}, {"w": "瀑流", "t": "瀑布"}, {"w": "瀑溜", "t": "瀑布"}, {"w": "瀑练", "t": "瀑布。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3449wx','襟','1','jīn','衤','18','','[{"pinyin": "jīn", "defs": [{"meaning": "(形声。从衣,禁声。本义:古代指衣的交领)。"}, {"meaning": "同本义。后指衣的前幅。", "cites": [{"t": "泣下沾襟。", "b": "宋·欧阳修《新五代史·伶官传》"}], "words": [{"w": "襟袂", "t": "襟袖。衣襟和衣袖"}, {"w": "襟带", "t": "衣襟和腰带"}, {"w": "襟卫", "t": "襟带周卫"}, {"w": "襟子", "t": "衣襟"}, {"w": "襟儿", "t": "衣襟。"}]}, {"meaning": "裹杂;混合。", "cites": [{"t": "将零头的三百八十匹,又选自己营中老疲病马五百余匹,襟在里头。叫几个军士赶着。", "b": "清·素庵主人《睢阳忠毅录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3450wx','璧','1','bì','玉','18','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从玉,辟声。本义:平而圆,中心有孔的玉)。"}, {"meaning": "同本义。", "cites": [{"t": "璧,瑞玉环也。", "b": "《说文》"}, {"t": "肉倍好谓之璧。", "b": "《尔雅·释器》。注:“肉边好孔。玉人,璧好三寸。”"}, {"t": "璧者,方中圆外。", "b": "《白虎通》"}, {"t": "宏璧。", "b": "《书·顾命》。郑注:“大璧,度尺二寸。”"}, {"t": "以苍璧礼天。", "b": "《周礼·大宗伯》"}, {"t": "如圭如璧。", "b": "《诗·卫风·淇奥》"}, {"t": "愿以十五城请易璧。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "相如奉璧奏秦王。", "b": ""}], "words": [{"w": "璧不可以防寒", "t": "比喻物品虽然贵重,但无实际的用处"}, {"w": "璧雍", "t": "璧堂。古代天子所设的太学。外形好像圆璧,周围以水绕之。"}]}, {"meaning": "玉的通称。", "cites": [{"t": "柱以白璧,砌以青玉。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "璧玉", "t": "上等美玉"}, {"w": "璧散", "t": "古玉爵名。为祭祈时所用的礼器"}, {"w": "璧人", "t": "仪容美好的人"}, {"w": "璧门", "t": "用玉装饰的门。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3451wx','戳','1','chuō','戈','18','','[{"pinyin": "chuō", "defs": [{"meaning": "(形声。从戈,翟(dí)声。本义:用锐器的尖端刺击)。"}, {"meaning": "同本义。", "cites": [{"t": "戳,枪戳也。", "b": "《篇海类篇》"}, {"t": "众强盗拚命死战,戳伤了几个庄客。", "b": "《醒世恒言》"}], "words": [{"w": "戳伤;戳舌", "t": "搬弄是非,挑拨"}, {"w": "戳弄", "t": "摆布,捉弄"}, {"w": "戳背脊", "t": "背后指责讥笑"}, {"w": "戳纱", "t": "一种特殊的刺绣品"}, {"w": "戳锅漏", "t": "方言。指暗中捣鬼的人"}, {"w": "戳无路儿", "t": "捣鬼,无中生有的挑拨"}, {"w": "戳腿", "t": "拳脚套式之一"}, {"w": "戳包儿", "t": "掉包,暗中掉换某物。"}]}, {"meaning": "用指头指点。", "cites": [{"t": "向他头上戳了一指头。", "b": "《红楼梦》"}], "words": [{"w": "戳点", "t": "用指尖指点"}, {"w": "戳指", "t": "伸出指头指着。"}]}, {"meaning": "刺激。", "cites": [{"t": "一句话戳了他娘的心。", "b": "《红楼梦》"}]}, {"meaning": "竖立的;站的。", "cites": [{"t": "两边一色戳灯,照如白昼。", "b": "《红楼梦》"}], "words": [{"w": "戳灯", "t": "长柄、有底座,既可竖立又可扛着行走的一种灯笼。"}]}, {"meaning": "图章,印记。", "cites": [{"t": "上有销号小戳。", "b": "清·黄六鸿《福惠全书》"}], "words": [{"w": "条戳;手戳;邮戳;戳灯", "t": "旧时书有姓氏或其他印记以标志门第的灯笼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3452wx','孽','1','niè','子','19','','[{"pinyin": "niè", "defs": [{"meaning": "(形声。从子,薛声。从子,与子孙有关。本义:庶出的,宗法制度下指家庭的旁支)。"}, {"meaning": "同本义。", "cites": [{"t": "孽,庶子也。", "b": "《说文》。段注:“凡木萌旁出皆曰蘖,人之支子曰孽,其义略同。”"}, {"t": "商君者,魏之庶孽公子也。", "b": "《史记·商君书》"}, {"t": "独孤臣孽子(孤立之臣,庶出之子),其操心也危,其虑患也深,故达(通达事理)。", "b": "《孟子·尽心上》"}], "words": [{"w": "孽长子,孽子", "t": "庶子,非正妻所生之子"}, {"w": "孽出", "t": "庶出"}, {"w": "孽孙", "t": "庶出之孙"}, {"w": "孽庶", "t": "即孽子。"}]}, {"meaning": "庶子,妾所生的儿子。", "cites": [{"t": "从君东西南北,则是臣仆庶孽之事也。", "b": "《公羊传》"}]}, {"meaning": "罪,罪恶,罪行,严重的罪过。", "cites": [{"t": "衅孽外乘。", "b": "清·周容《芋老人传》"}, {"t": "天作孽,犹可违。(违:逃避。)", "b": "《孟子》"}], "words": [{"w": "罪孽;余孽;冤孽;孽愆", "t": "罪过。"}]}, {"meaning": "妖孽;灾害。", "cites": [{"t": "下民之孽,匪降自天。", "b": "《诗·小雅·十月之交》"}, {"t": "心和而出,且为声为名,为妖为孽。", "b": "《庄子·人间世》"}, {"t": "蕴利生孽。", "b": "《左传·昭公十年》"}], "words": [{"w": "孽牙", "t": "孽芽。祸端,灾祸的苗头"}, {"w": "造孽;妖孽;孽畜", "t": "造孽的畜生"}, {"w": "孽债", "t": "造孽的罪责。"}]}, {"meaning": "忤逆,不孝顺。", "cites": [{"t": "子爱利亲谓之孝,反孝为孽。", "b": "《新书·道术》"}]}, {"meaning": "危害,害。", "cites": [{"t": "圣贤之后,反而孽民。", "b": "《吕氏春秋·遇合》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3453wx','警','1','jǐng','言','19','','[{"pinyin": "jǐng", "defs": [{"meaning": "(会意。从言,从敬,敬亦声。本义:戒敕)。"}, {"meaning": "同本义。", "cites": [{"t": "警,戒也。", "b": "《说文》"}, {"t": "正岁,则以法警戒群吏。", "b": "《周礼·宰夫》"}, {"t": "所以警众也。", "b": "《礼记·文王世子》"}, {"t": "乃一篇之警策。", "b": "《文赋》"}, {"t": "今年或者大警晋也。", "b": "《左传·宣公十二年》"}, {"t": "以警其余。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "警告;警励", "t": "告诫策励"}, {"w": "警迹人", "t": "元代被列入盗贼户籍的人"}, {"w": "警鼓", "t": "报警之鼓"}, {"w": "警动", "t": "使人警觉悚动"}, {"w": "警新", "t": "警策动人,语意新颖"}, {"w": "警众", "t": "使众人警觉"}, {"w": "警省", "t": "警觉省悟。"}]}, {"meaning": "戒备;防备。", "cites": [{"t": "军卫不彻,警也。", "b": "《左传·宣公十二年》"}], "words": [{"w": "警巡", "t": "警戒巡视"}, {"w": "警跸", "t": "古代为皇帝出行清道,严加戒备,断绝行人"}, {"w": "警惧", "t": "警戒恐惧"}, {"w": "警边", "t": "警戒边境。"}]}, {"meaning": "惊恐;惊动。", "cites": [{"t": "节循虚而警立。", "b": "《文选·陆机·叹逝赋》。注:“警犹惊也。”"}], "words": [{"w": "警动", "t": "惊动;惊恐"}, {"w": "警唬", "t": "吓唬,恐吓。"}]}, {"meaning": "警报。", "cites": [{"t": "盗贼之警。", "b": "宋·苏轼《教战守》"}, {"t": "每有警。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "示警;告警;火警", "t": ""}]}, {"meaning": "敏悟。", "cites": [{"t": "太祖少机警,有权数。(少:少年。)", "b": "《三国志·武帝纪》"}], "words": [{"w": "警彗", "t": "机灵敏慧"}, {"w": "警黠", "t": "警捷。机警敏捷"}, {"w": "警省", "t": "佛教用语。彻悟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3454wx','蘑','1','mó','艹','19','','[{"pinyin": "mó", "defs": [{"meaning": "担子菌纲,伞菌科。许多膨大而复杂的气生肉质真菌子实体。"}, {"meaning": "故意纠缠。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3455wx','藻','1','zǎo','艹','19','','[{"pinyin": "zǎo", "defs": [{"meaning": "(形声。从艸,澡声。本义:藻类植物,古专指水藻)。"}, {"meaning": "同本义 。隐花植物的一大类,没有根、茎、叶等部分的区别,有叶绿素可以自己制造养料,种类很多,海水和淡水里都有。", "cites": [{"t": "薄采其藻。", "b": "《诗·鲁颂·泮水》"}, {"t": "蘋蘩蕰藻之菜。", "b": "《左传·隐公三年》。注:“聚藻也。”"}, {"t": "于以采藻,于彼行潦。", "b": "《诗·召南·采蘋》"}], "words": [{"w": "藻火", "t": "水藻和火焰。古时官吏绣在官服上的图案。"}]}, {"meaning": "泛指水草。", "cites": [{"t": "水中藻行交横。", "b": "苏轼《志林》"}], "words": [{"w": "藻川", "t": "长有绿色水藻的河川"}, {"w": "藻花", "t": "水边泽草所开的花"}, {"w": "金鱼藻;狸藻等", "t": ""}]}, {"meaning": "词藻,华丽的文辞。", "cites": [{"t": "攦藻如春华。", "b": "班固《答宾戏》"}], "words": [{"w": "藻拔", "t": "文采出众"}, {"w": "藻朗", "t": "文辞清明"}, {"w": "藻咏", "t": "以华美文辞咏诵。指诗文而言"}, {"w": "藻雅", "t": "文辞典雅。"}]}, {"meaning": "文采。", "cites": [{"t": "华藻繁缛。", "b": "曹植《七启》"}], "words": [{"w": "藻采", "t": "文采,辞采"}, {"w": "藻思", "t": "做文章的才思。"}]}, {"meaning": "", "cites": [{"t": "天子玉藻。", "b": "《礼记·玉藻》"}, {"t": "婴用一藻玉瘗。", "b": "《山海经·中山经》"}]}, {"meaning": "华美。", "cites": [{"t": "敷藻翰之陪鳃。", "b": "潘岳《射雉赋》"}], "words": [{"w": "藻仗", "t": "文彩华美的仪仗"}, {"w": "藻幄", "t": "美丽的篷帐"}, {"w": "藻翰", "t": "美丽的羽毛。比喻华丽的文辞"}, {"w": "藻盖", "t": "华美的篷盖"}, {"w": "藻翘", "t": "色彩华丽的羽毛。"}]}, {"meaning": "修饰文章。", "cites": [{"t": "土木形骸,不自藻饰。", "b": "房玄龄《晋书》"}], "words": [{"w": "藻饰", "t": "把文章加以修改润色。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3456wx','攀','1','pān','手','19','','[{"pinyin": "pān", "defs": [{"meaning": "(形声。从手,樊声。本义:拉,牵)。"}, {"meaning": "同本义。", "cites": [{"t": "攀,引也。", "b": "《广雅》"}, {"t": "右手攀右趾。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "攀恋", "t": "攀住车辕,恋恋不舍"}, {"w": "攀辕", "t": "拉住车把。"}]}, {"meaning": "攀援,指用握住或抓住某物的方法爬或登。", "cites": [{"t": "将士皆攀木援崖,鱼贯而进。", "b": "《三国志·邓艾传》"}, {"t": "攀草牵棘,…石崖侧削则援崖。", "b": "《徐霞客游记·游黄山记》"}], "words": [{"w": "攀引", "t": "攀援"}, {"w": "攀延", "t": "攀附他物延伸"}, {"w": "攀沿", "t": "犹攀缘"}, {"w": "攀云", "t": "攀附青云而上升。后比喻仕进"}, {"w": "攀倚", "t": "攀援依傍"}, {"w": "攀进", "t": "攀缘行进。"}]}, {"meaning": "指跟地位高的人结亲戚或拉关系;高攀。", "cites": [{"t": "两府攀陪十五年,郡中甘雨幕中莲。", "b": "唐·罗隐《乌程》"}], "words": [{"w": "攀教", "t": "高攀求教"}, {"w": "攀风", "t": "比喻结交比自己高一等的人"}, {"w": "攀亲托熟", "t": "认作亲戚熟友。"}]}, {"meaning": "攀比。", "cites": [{"t": "窃攀屈宋宜方驾,恐与齐梁作后尘。", "b": "杜甫《戏为六绝句》"}], "words": [{"w": "攀引", "t": "犹攀比"}, {"w": "攀追", "t": "攀比追随;攀高追远。"}]}, {"meaning": "依附。", "cites": [{"t": "逊小心谨慎,徒以攀附至贵显。", "b": "《宋史·张逊传》"}], "words": [{"w": "攀依", "t": "攀附,依附"}, {"w": "攀陪", "t": "依附"}, {"w": "攀违", "t": "谦词,谓有违于依附"}, {"w": "攀鳞", "t": "比喻依附帝王以成功名。"}]}, {"meaning": "牵涉;牵扯。", "cites": [{"t": "此人曾攀下王子服等四人,我已拿下廷尉。", "b": "《三国演义》"}], "words": [{"w": "攀指", "t": "诬供牵连"}, {"w": "攀染", "t": "诬供牵连"}, {"w": "攀连", "t": "诬供牵连"}, {"w": "攀诬", "t": "犯人诬供以牵连他人"}, {"w": "攀害", "t": "诬供陷害。"}]}, {"meaning": "追;赶。", "cites": [{"t": "燕、许有作,方欲上攀秦、汉。", "b": "章炳麟《国故论衡·论式》"}]}, {"meaning": "摘取。", "cites": [{"t": "攀桃李兮不忍别,送爱子兮沾罗裙。", "b": "南朝梁·江淹《别赋》"}, {"t": "唐昌玉蕊花,攀玩众所争。", "b": "白居易《白牡丹和钱学士作》"}], "words": [{"w": "攀玩", "t": "折取玩赏"}, {"w": "攀搴", "t": "折取。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3457wx','曝','1','bào pù','日','19','','[{"pinyin": "bào", "defs": [{"meaning": "使感光纸或摄影胶片感光。"}]}, {"pinyin": "pù", "defs": [{"meaning": "(形声。从日,暴声。字本作“暴”,小篆字形,从日,从出,从廾，从米。会合表示把米拿到阳光下照晒。廾(gǒng),两手捧物。本义:晒)。"}, {"meaning": "同本义。", "cites": [{"t": "曝沙之鸟,呷浪之鳞。", "b": "明·袁宏道《满井游记》"}, {"t": "冬曝其日。", "b": "晋·陶渊明《自祭文》"}], "words": [{"w": "一曝十寒", "t": ""}, {"w": "曝衣", "t": "晒衣服"}, {"w": "曝罟", "t": "晒网"}, {"w": "曝射", "t": "曝晒照射"}, {"w": "曝书", "t": "晒书"}, {"w": "曝阳", "t": "晒太阳"}, {"w": "曝场", "t": "曝晒粮食的场地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3458wx','蹲','1','dūn cún','足','19','','[{"pinyin": "dūn", "defs": [{"meaning": "(形声。从足,尊声。本义:坐)。"}, {"meaning": "同本义。", "cites": [{"t": "蹲,坐也。", "b": "《广韵》"}, {"t": "蹲,踞也。", "b": "《说文》"}, {"t": "蹲乎会稽。", "b": "《庄子·外物》"}, {"t": "熊罴对我蹲。", "b": "曹操《苦寒行》"}], "words": [{"w": "蹲夷", "t": "蹲踞,踞坐。"}]}, {"meaning": "虚坐。屈两膝如坐,臀部不着地。", "cites": [{"t": "蹲右足。", "b": "黄淳耀《李龙眠画罗汉记》"}], "words": [{"w": "树底下蹲着一个人;蹲身", "t": "屈腿下蹲"}, {"w": "蹲足", "t": "屈膝下跪"}, {"w": "蹲步", "t": "蹲身纵步"}, {"w": "蹲坐", "t": "蹲身而坐。"}]}, {"meaning": "控制或延缓植物生长。", "cites": [{"t": "让小麦下边几个节不拔得那么快,蹲一蹲,长硬实粗壮。", "b": "李准《参观》"}]}]}, {"pinyin": "cún", "defs": [{"meaning": "“蹲蹲”,舞的样子。", "cites": [{"t": "坎坎鼓我,蹲蹲舞我。", "b": "《诗·小雅·出车》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3459wx','蹭','1','cèng','足','19','','[{"pinyin": "cèng", "defs": [{"meaning": "(形声。从足,曾声。本义:摩擦)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3460wx','蹬','1','dēng dèng','足','19','','[{"pinyin": "dēng", "defs": [{"meaning": "踩;踏。", "cites": [{"t": "蹬,履也。", "b": "《广雅》"}, {"t": "功蹬王府。", "b": "《槀长蔡湛颂》"}, {"t": "唿喇一声蹬倒八卦炉,往外就走。", "b": "《西游记》"}], "words": [{"w": "蹬空", "t": "踏空"}, {"w": "蹬脱", "t": "踢开;甩脱,抛开"}, {"w": "蹬足", "t": "以足顿地"}, {"w": "蹬踏", "t": "登;蹬上高处。"}]}]}, {"pinyin": "dèng", "defs": [{"meaning": "马镫。", "cites": [{"t": "[婆利国王]带金装剑,偏坐金高坐,以银蹬支足。", "b": "《南史》"}]}, {"meaning": "梯道。", "cites": [{"t": "蹬倚绝壁,壁石皆崆峒,木根穿隙缘窍。", "b": "《徐霞客游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3461wx','巅','1','diān','山','19','','[{"pinyin": "diān", "defs": [{"meaning": "(形声。从山,颠声。本义:山顶)。"}, {"meaning": "同本义。", "cites": [{"t": "巅,山顶也。", "b": "《广韵》"}, {"t": "首阳之巅。", "b": "《诗·唐风·采苓》。集传:“巅,山顶也。”"}, {"t": "西当太白有鸟道,可以横绝峨眉巅。", "b": "唐·李白《蜀道难》"}], "words": [{"w": "山巅;巅崖", "t": "山顶悬崖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3462wx','簸','1','bǒ bò','竹','19','','[{"pinyin": "bǒ", "defs": [{"meaning": "(形声。从箕,皮声。本义:用簸箕盛粮食等上下颠动,扬去糠粃尘土等物)。"}, {"meaning": "同本义。", "cites": [{"t": "簸,扬米去糠也。", "b": "《说文》"}, {"t": "维南有箕,不可以簸扬。", "b": "《诗·小雅·大东》"}, {"t": "或舂或揄,或簸或蹂。", "b": "《诗·大雅·生民》"}], "words": [{"w": "簸秕,簸扬糠秕", "t": "扬米去糠,糠在米上"}, {"w": "簸箩", "t": "盛物的竹筐。"}]}, {"meaning": "摇动;颠动。", "cites": [{"t": "宫殿摆簸。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "颠簸;簸行", "t": "摇摆不定的步行。"}]}]}, {"pinyin": "bò", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3463wx','簿','1','bù','竹','19','','[{"pinyin": "bù", "defs": [{"meaning": "(形声。从竹,溥(pǔ)声。本义:登记事物的册子)。"}, {"meaning": "同本义。", "cites": [{"t": "上问上林尉诸禽兽簿。(上:皇上;上林尉:官名。)", "b": "《史记·张释之传》"}], "words": [{"w": "练习薄;账簿;簿籍", "t": "财物出纳的账册"}, {"w": "簿钞", "t": "簿牒;簿籍文书。"}]}, {"meaning": "文书。", "cites": [{"t": "儒生所短,不徒以不晓簿书。", "b": "《论衡·谢短》"}], "words": [{"w": "簿责", "t": "以文牍相责"}, {"w": "簿牒", "t": "文书"}, {"w": "簿历", "t": "履历记录"}, {"w": "簿牍", "t": "文书。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3464wx','蟹','1','xiè','虫','19','','[{"pinyin": "xiè", "defs": [{"meaning": "螃蟹。", "cites": [{"t": "蠏,有二敖、八足、旁行、非蛇鲹之穴无所庇。", "b": "《说文》"}, {"t": "离为蟹,外刚而内柔也。", "b": "《易·说卦》"}, {"t": "蟹六跪而二螯。", "b": "《荀子·劝学》"}, {"t": "蟹白栗黄。", "b": "《聊斋志异·促织》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3465wx','颤','1','chàn zhàn','页','19','','[{"pinyin": "chàn", "defs": [{"meaning": "颤抖,发抖。", "cites": [{"t": "那手早颤起来,不敢打到第二下。", "b": "《范进中举》"}], "words": [{"w": "发颤;颤悠", "t": "形容颤抖摇晃"}, {"w": "颤悠悠", "t": "颤抖摇晃的样子。"}]}, {"meaning": "惧怕,惊恐。", "cites": [{"t": "越国之士,可谓颤矣。", "b": "《墨子·兼爱下》"}], "words": [{"w": "颤恐", "t": "惊恐"}, {"w": "颤钦钦", "t": "因惊恐而颤抖。"}]}]}, {"pinyin": "zhàn", "defs": [{"meaning": "(形声。从页(xié),亶(dǎn)声。从“页”与头有关。本义:头摇动不定) 发抖;颤动。", "cites": [{"t": "暴戾顽贪,无下颤恐而患之。", "b": "《吕氏春秋》"}], "words": [{"w": "打颤", "t": "发抖"}, {"w": "寒颤", "t": "寒战"}, {"w": "冷颤", "t": "冷战"}, {"w": "颤栗", "t": "发抖;哆嗦"}, {"w": "颤欣欣", "t": "战兢兢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3466wx','靡','1','mí mǐ','非','19','','[{"pinyin": "mí", "defs": [{"meaning": "水边,河岸。", "cites": [{"t": "明月珠子,玓瓅江靡。", "b": "《史记·司马相如列传》"}]}, {"meaning": "浪费。", "cites": [{"t": "而百姓靡于外。", "b": "《战国策·秦策》"}, {"t": "国家靡敝。", "b": "《礼记·少仪》。疏:“谓财物糜散凋敝。”"}, {"t": "不随俗靡。", "b": "宋·司马光《训俭示康》"}, {"t": "靡之者。", "b": "汉·贾谊《论积贮疏》"}], "words": [{"w": "奢靡;靡货", "t": "奢侈品"}, {"w": "靡靡", "t": "华丽而堂皇"}, {"w": "靡丽", "t": "奢华,美盛。"}]}, {"meaning": "消失。", "cites": [{"t": "喧杂杂鸟声多,静悄悄人事靡。", "b": "《西游记》"}], "words": [{"w": "靡散", "t": "消灭"}, {"w": "靡碎", "t": "散碎。"}]}, {"meaning": "烂。", "cites": [{"t": "子胥靡。", "b": "《庄子·胠箧》"}]}, {"meaning": "切磋,研究。", "cites": [{"t": "身日进于仁义而不自知也者,靡使然也。", "b": "《荀子·性恶》"}]}, {"meaning": "摩擦,接触。", "cites": [{"t": "喜则交颈相靡。", "b": "《庄子·马蹄》"}]}]}, {"pinyin": "mǐ", "defs": [{"meaning": "(形声。从非,麻声(mǐ)。本义:无;没有)。"}, {"meaning": "同本义 。", "cites": [{"t": "靡,无也。", "b": "《尔雅》"}, {"t": "靡室靡家。", "b": "《诗·小雅·采薇》"}, {"t": "靡日不思。", "b": "《诗·邶风·泉水》"}, {"t": "靡不有初。", "b": "《战国策·秦策》"}, {"t": "靡计不施。", "b": "《聊斋志异·促织》"}, {"t": "靡不毕现。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "靡有孑遗", "t": "没有遗漏,一点儿不剩。"}]}, {"meaning": "散乱;顺风倒下。", "cites": [{"t": "望其旗靡。", "b": "《左传·庄公十年》"}, {"t": "左右皆靡。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "汉军皆披靡、分散之貌。", "b": "《史记》"}, {"t": "利夫秋豪害靡国家。", "b": "《荀子·大略》。注:“披靡也。”"}, {"t": "虫尽靡。", "b": "《聊斋志异·促织》"}], "words": [{"w": "风靡;委靡;披靡,靡拉", "t": "毁损破坏"}, {"w": "靡披", "t": "草木随风所至,无不倒伏"}, {"w": "靡徙", "t": "失正,抑退的样子"}, {"w": "靡敝", "t": "衰败,败坏"}, {"w": "靡然", "t": "随风披靡的样子。"}]}, {"meaning": "细腻;细密。", "cites": [{"t": "靡颜腻理。", "b": "《楚辞·招魂》"}], "words": [{"w": "靡密(细密,细致):靡曼(肌理柔腻细致", "t": ""}, {"w": "靡颜腻理", "t": "形容美人容颜姣妍,肌肤细腻。"}]}, {"meaning": "华丽,美好。", "cites": [{"t": "不侈于后世,不靡于万物。", "b": "《庄子·天下》"}], "words": [{"w": "靡曼", "t": "柔弱,柔美,华丽。"}]}, {"meaning": "缓。", "cites": [{"t": "行迈靡靡。", "b": "《诗·王风·黍离》"}], "words": [{"w": "靡迤", "t": "小步而行"}, {"w": "靡靡", "t": "迟缓的样子;柔和的乐音。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3467wx','癣','1','xuǎn','疒','19','','[{"pinyin": "xuǎn", "defs": [{"meaning": "由真菌(尤其是发癣菌属和小孢子菌属)所引起的人类和家畜皮肤、毛发或趾(指)甲的接触性传染病,特征为皮肤有环形脱色斑,覆以疱疹及鳞屑。", "cites": [{"t": "其中是多豪鱼…可以已白癣。", "b": "《山海经》"}], "words": [{"w": "癣疥", "t": "皮肤病。癣与疥"}, {"w": "癣驳", "t": "斑驳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3468wx','瓣','1','bàn','瓜','19','','[{"pinyin": "bàn", "defs": [{"meaning": "(形声。从瓜,辡(biǎn)声。本义:瓜类的籽)。"}, {"meaning": "同本义。", "cites": [{"t": "瓣,瓜中实也。", "b": "《说文》"}, {"t": "瓠栖瓣。", "b": "《尔雅》。按,今曰瓜子仁。"}, {"t": "水中有甘蔗,及梅李核瓜瓣。", "b": "南朝宋·谢惠连《祭古冢文》"}]}, {"meaning": "瓜果的分瓤。", "cites": [{"t": "朱橘香苞数瓣分。", "b": "元稹《贬江陵途中寄乐天》"}], "words": [{"w": "橘瓣,瓜瓣", "t": ""}]}, {"meaning": "植物的种子、果实或球茎可以分开的片状物。", "cites": [{"t": "面如桃瓣,目若秋波。", "b": "《红楼梦》"}], "words": [{"w": "豆瓣;蒜瓣", "t": ""}]}, {"meaning": "用于花瓣、叶片或种子、果实、球茎分开的小块儿。", "cites": [{"t": "种柳,先于土坑中置蒜一瓣,甘草一寸,永不生虫。", "b": "《格物粗谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3469wx','羹','1','gēng','羊','19','','[{"pinyin": "gēng", "defs": [{"meaning": "(会意。从羔,从美。古人的主要肉食是羊肉,所以用“羔”“美”会意,表示肉的味道鲜美。用肉或菜调和五味做成的带汁的食物。《说文》:“五味和羹。”按:上古的“羹”,一般是指带汁的肉,而不是汤。“羹”表示汤的意思,是中古以后的事情)。"}, {"meaning": "调和五味的汤。", "cites": [{"t": "一箪食,一豆羹,得之则生,弗得则死。", "b": "《孟子·告子上》"}, {"t": "(颖考叔)对曰:“小人有母,皆尝小人之食矣,未尝君之羹,请以遗之。”", "b": "《左传·隐公元年》"}]}, {"meaning": "煮熟带汁的蔬菜也叫羹。", "cites": [{"t": "藜藿之羹。", "b": "《韩非子·五蠹》"}], "words": [{"w": "菜羹", "t": "煮熟的菜,加上米屑,古代贫者所食"}, {"w": "羹食", "t": "羹汤和饭"}, {"w": "羹粥", "t": "菜羹和稀饭"}, {"w": "羹藜", "t": "煮野菜羹。泛指饮食粗劣。"}]}, {"meaning": "汤。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3470wx','鳖','1','biē','鱼','19','','[{"pinyin": "biē", "defs": [{"meaning": "(形声。从鱼,敝声。本义:甲鱼,一种爬行动物,俗称“团鱼”) 同本义 属于龟鳖目、鳖科,中国特产的一种软壳水龟,分布于中国南北各地,多栖于池沼、河沟、稻田中,肉味鲜美,一般认为是补品。", "cites": [{"t": "江汉之鱼鳖鼋鼍为天下富。", "b": "《墨子·公输》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3471wx','爆','1','bào','火','19','','[{"pinyin": "bào", "defs": [{"meaning": "(形声。从火,暴声。本义:炸裂发声)。"}, {"meaning": "同本义。", "cites": [{"t": "爆,灼也。", "b": "《说文》"}, {"t": "火爆声。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "车胎爆了;爆烈", "t": "猛烈爆炸"}, {"w": "爆响", "t": "突然而猛裂地发出声响。"}]}, {"meaning": "燃着。", "cites": [{"t": "湿薪未爆先烟。", "b": "宋·范成大《苦雨》"}]}, {"meaning": "突出来;鼓起。", "cites": [{"t": "满额爆出了青筋。", "b": "茅盾《子夜》"}]}, {"meaning": "火烧物声。", "cites": [{"t": "叵堪朋娄多,沸耳作惊爆。", "b": "唐·韩愈《答柳柳州食虾蟆》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3472wx','疆','1','jiāng','田','19','','[{"pinyin": "jiāng", "defs": [{"meaning": "(指事。从土,从弓,从畺(jiāng,田界)。从“弓”,表示以弓记步,即以弓来丈量土地。本义:田界)。"}, {"meaning": "同本义。", "cites": [{"t": "畺,界也。从田,三其界画也。指事。", "b": "《说文》"}, {"t": "疆埸有瓜。", "b": "《诗·小雅·信南山》"}, {"t": "有掌疆。", "b": "《周礼·夏官》"}], "words": [{"w": "疆陇", "t": "田界"}, {"w": "疆畛", "t": "地界;界限"}, {"w": "疆畎", "t": "指田地,垄亩沟渠。"}]}, {"meaning": "引申为国界、边界。", "cites": [{"t": "出疆必请。", "b": "《礼记·曲礼》"}, {"t": "固封疆。", "b": "《礼记·月令》"}], "words": [{"w": "疆宇", "t": "疆界的四陲。引申为国土"}, {"w": "疆吏", "t": "驻防边疆的官吏"}, {"w": "疆事", "t": "边疆的事故。多指边界的冲突、争执而言"}, {"w": "疆略", "t": "疆界;境界"}, {"w": "疆圻", "t": "疆界。"}]}, {"meaning": "疆域。", "cites": [{"t": "制其畿疆而沟封之。", "b": "《周礼·大司徒》"}, {"t": "禳于畺及郊。", "b": "《周礼·肆师》。注:“五百里。”按,王畿界也。"}], "words": [{"w": "疆易", "t": "疆土,领土"}, {"w": "疆壤", "t": "地域"}, {"w": "疆地", "t": "疆土,领土。"}]}, {"meaning": "止境;穷尽。", "cites": [{"t": "以逞无疆之欲。", "b": "《左传·成公二年》"}], "words": [{"w": "疆理", "t": "境界;界限"}, {"w": "疆顿", "t": "停留不能前进。"}]}, {"meaning": "划定界限。", "cites": [{"t": "先王疆理天下。", "b": "《左传·成公二年》"}], "words": [{"w": "疆里", "t": "界限,指定的范围。"}]}, {"meaning": "强大;强盛。", "cites": [{"t": "管仲去鲁入齐,鲁弱而齐疆。", "b": "《风俗通义·穷通》"}], "words": [{"w": "疆固", "t": "强盛坚固"}, {"w": "疆毅", "t": "刚强坚毅"}, {"w": "疆直", "t": "刚强正直。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3473wx','鬓','1','bìn','髟','20','','[{"pinyin": "bìn", "defs": [{"meaning": "(形声。从髟(biāo),宾声。“髟”,意思是头发长。“髟”的字多与毛发有关。本义:颊发。两颊两旁近耳的头发) 同本义。", "cites": [{"t": "鬓,颊发也。", "b": "《说文》"}, {"t": "美鬓长大则贤。", "b": "《国语·晋语》"}, {"t": "连发曰鬓。", "b": "《释名》"}, {"t": "两鬓苍苍十指黑。", "b": "唐·白居易《卖炭翁》"}, {"t": "少小离家老大回,乡音无改鬓毛衰。", "b": "唐·贺知章《回乡偶书》"}], "words": [{"w": "鬓影", "t": "面颊两旁近耳的头发"}, {"w": "鬓发霜侵", "t": "鬓发花白。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3474wx','壤','1','rǎng','土','20','','[{"pinyin": "rǎng", "defs": [{"meaning": "(形声。从土,襄(xiāng)声。本义:柔土,即经耕作的土地)。"}, {"meaning": "土壤。", "cites": [{"t": "壤,柔土也。", "b": "《说文》"}, {"t": "凡穿地四尺,为壤五尺,为坚三尺。", "b": "《九章算法》。按,息土曰壤,筑土曰坚。"}, {"t": "厥土惟白壤。", "b": "《书·禹贡》"}, {"t": "深耕细锄,厚加粪壤。", "b": "《论衡·率性》"}], "words": [{"w": "壤坟", "t": "柔细肥沃,适于耕种的土地"}, {"w": "壤芥", "t": "泥土和小草"}, {"w": "沃壤", "t": ""}]}, {"meaning": "泛指泥土。", "cites": [{"t": "夫太山不辞壤石。", "b": "《说文·尊贤》"}], "words": [{"w": "霄壤;壤力", "t": "地力"}, {"w": "壤未", "t": "地下"}, {"w": "壤水", "t": "地下水;泉水"}, {"w": "壤室", "t": "土室;土屋"}, {"w": "壤陛", "t": "土做的台阶"}, {"w": "天壤之别", "t": ""}]}, {"meaning": "也指一般的土地。", "cites": [{"t": "东据成皋之险,割膏腴之壤。", "b": "李斯《谏逐客书》"}, {"t": "遂率子孙荷担者三夫,叩石垦壤。", "b": "《列子·汤问》"}], "words": [{"w": "壤地", "t": "泛称土地或国土"}, {"w": "壤策", "t": "土地政策。"}]}, {"meaning": "地区。", "cites": [{"t": "文王以百里之壤而臣诸侯。", "b": "《史记·平原君虞卿列传》"}], "words": [{"w": "穷乡僻壤", "t": ""}]}, {"meaning": "数词。十秭为壤。又以万万秭为壤。亦泛指大数。", "cites": [{"t": "凡大数之法,万万曰亿,万万亿曰兆,万万兆曰京,万万京曰陔,万万陔曰秭,万万秭曰壤。", "b": "《孙子算经》"}]}, {"meaning": "丰收。", "cites": [{"t": "畏垒大壤。", "b": "《庄子·庚桑楚》"}]}, {"meaning": "毗连;连接。", "cites": [{"t": "且夫韩、魏之所以重畏秦者,为与秦接境壤界也。", "b": "《史记》"}]}, {"meaning": "凿地出土。", "cites": [{"t": "其日有食之何也?吐者外壤,食者内壤,阙然不见其壤,有食之者也。", "b": "《谷梁传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3475wx','馨','1','xīn','香','20','','[{"pinyin": "xīn", "defs": [{"meaning": "(形声。从香,殸声。殸,籀文“磬”(qìng)。本义:芳香,散布很远的香气)。"}, {"meaning": "同本义。", "cites": [{"t": "馨,香之远闻者也。", "b": "《说文》"}, {"t": "其德足以昭其馨香。", "b": "《国语·周语》"}, {"t": "丹木五岁五味乃馨成。", "b": "《山海经·西山经》"}, {"t": "尔酒既清,尔淆既馨。", "b": "《诗·大雅·凫鷖》。毛传:“馨,香之远闻也。”"}, {"t": "惟吾德馨。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "馨烈", "t": "芳香浓烈"}, {"w": "馨逸", "t": "香气洋溢;芳香远播。"}]}, {"meaning": "比喻声誉流芳后世。", "cites": [{"t": "化盛隆周,垂馨千祀。", "b": "《晋书》"}]}, {"meaning": "有赞美的意思。后来多“宁馨”(如此,这样) 连用。", "cites": [{"t": "为问中华学道者,几人雄猛得宁馨。", "b": "刘禹锡《赠日本僧智藏》"}], "words": [{"w": "宁馨儿", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3476wx','耀','1','yào','羽','20','','[{"pinyin": "yào", "defs": [{"meaning": "(形声。从光,翟(dí)声。本义:照耀)。"}, {"meaning": "同本义。", "cites": [{"t": "耀,照也。", "b": "《说文》"}, {"t": "焜燿寡人之望。", "b": "《左传·昭公三年》"}, {"t": "以淳耀燿大。", "b": "《国语·郑语》"}, {"t": "星耀而玄运。", "b": "《淮南子·览冥》"}, {"t": "光远而自他有耀者也。", "b": "《左传》"}], "words": [{"w": "耀目晶光", "t": "光彩夺目"}, {"w": "耀夜", "t": "萤火虫的别名"}, {"w": "耀芒", "t": "光芒照射"}, {"w": "耀采", "t": "光彩照耀"}, {"w": "耀亮", "t": "照亮"}, {"w": "耀燿", "t": "光辉照耀。"}]}, {"meaning": "炫耀。", "cites": [{"t": "耀明于子。", "b": "唐·柳宗元《柳河东集》"}], "words": [{"w": "夸耀;耀师", "t": "显示军队的威力;光荣出师"}, {"w": "耀名", "t": "炫示虚名。"}]}, {"meaning": "显示;显耀。", "cites": [{"t": "耀灵。", "b": "《后汉书·张衡传》。注:“日也。”"}, {"t": "耀德不观兵。", "b": "《国语·周语》"}, {"t": "耀威中威。", "b": "张衡《东京赋》"}], "words": [{"w": "耀颖", "t": "聪明过人"}, {"w": "耀武", "t": "显示武力。"}]}, {"meaning": "光芒,光辉。", "cites": [{"t": "日星隐耀。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "耀耀", "t": "光明的样子"}, {"w": "耀蝉", "t": "以飞蝉多投明,故于夜间燃火可以捕蝉。比喻天子招致贤士,必先自明其德"}, {"w": "耀光", "t": "光彩。"}]}, {"meaning": "古州名 。治所在今陕西省耀县。"}, {"meaning": "县名 在陕西省中部。1913年由耀州改县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3477wx','躁','1','zào','足','20','','[{"pinyin": "zào", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "躁,疾也。", "b": "《说文》。字亦作躁。"}, {"t": "羽杀则躁。", "b": "《考工记·矢人》。按,今字作躁。"}, {"t": "躁者不静。", "b": "《管子·心术》"}, {"t": "巽为躁卦。", "b": "《易·说卦》"}, {"t": "震为决躁。", "b": ""}, {"t": "处必掩身毋躁。", "b": "《礼记·月令》。注:“动也。”"}, {"t": "狗赤股而躁。", "b": "《礼记·内则》。注:“举动急疾。”"}, {"t": "言未及之而言谓之躁。", "b": "《论语》。郑注:“不安静也。”"}, {"t": "重为轻根,静为躁君。", "b": "《韩非子·喻老》"}], "words": [{"w": "躁暴", "t": "暴躁;急躁"}, {"w": "躁妄", "t": "急躁轻率"}, {"w": "躁忿", "t": "急躁易怒"}, {"w": "躁扰", "t": "急躁好动"}, {"w": "躁静", "t": "急躁与宁静"}, {"w": "躁率", "t": "急躁轻率。"}]}, {"meaning": "急疾;迅速。", "cites": [{"t": "脉三动而躁。", "b": "《素问·平人气象论》"}, {"t": "人迎躁盛,喘息气逆。", "b": "《素问》"}], "words": [{"w": "躁速", "t": "迅速"}, {"w": "躁疾", "t": "迅速;急躁"}, {"w": "躁盛", "t": "脉博的跳动疾速有力。"}]}, {"meaning": "浮躁;不专一。", "cites": [{"t": "好变动民曰躁。", "b": "《周书·谥法》"}, {"t": "离位之谓躁。", "b": "《韩非子·喻老》"}, {"t": "蟹六跪而二螯…用心躁也。", "b": "《荀子·劝学》"}], "words": [{"w": "躁易", "t": "浮躁,轻佻"}, {"w": "躁戾", "t": "浮躁暴戾"}, {"w": "躁气", "t": "浮躁的气质。"}]}]}]','jingmo-wenyan');
