('3478wx','蠕','1','rú','虫','20','','[{"pinyin": "rú", "defs": [{"meaning": "虫类爬行的样子;微动貌", "words": [{"w": "蠕活", "t": "慢慢地活动"}, {"w": "蠕蜚", "t": "指爬行和飞翔的昆虫"}, {"w": "蠕簇", "t": "蠕动聚集"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3479wx','嚼','1','jiáo jiào jué','口','20','','[{"pinyin": "jiáo", "defs": [{"meaning": "(形声。从口,爵声。本义:以牙磨碎食物)。"}, {"meaning": "同本义。", "cites": [{"t": "嚼,削也。", "b": "《释名》"}, {"t": "嚼,噬嚼也。", "b": "《玉篇》"}], "words": [{"w": "嚼蜡", "t": "多指文章或讲话没有滋味,没有意思"}, {"w": "嚼吞", "t": "咀嚼吞食"}, {"w": "嚼咽", "t": "咀嚼吞咽"}, {"w": "嚼头(经得起咀嚼的厚味(多用比喻义))", "t": ""}]}, {"meaning": "剥蚀、蛀蚀、冲蚀或冰川侵蚀。", "cites": [{"t": "水嚼沙洲树出根。", "b": "宋·真山民《朱溪涧》"}]}, {"meaning": "干杯。", "cites": [{"t": "复嚼者,京都饮酒相强之辞也。", "b": "《续汉书·五行志》"}, {"t": "解姊子负解之势,与人饮,使之嚼。非其任疆必灌之。", "b": "《史记》"}]}]}, {"pinyin": "jiào", "defs": [{"meaning": "——“倒嚼”(dǎojiào):即牛羊等动物的反刍。"}]}, {"pinyin": "jué", "defs": [{"meaning": "义同“嚼(jiáo),用于某些复合词和成语。", "cites": [{"t": "嚼,噬嚼也。", "b": "《玉篇》"}, {"t": "咀啮曰嚼。", "b": "《通俗文》"}, {"t": "牛曰齝。", "b": "《尔雅·释兽》。注:“食之已久,复出嚼之。”"}], "words": [{"w": "咀嚼;嚼血", "t": "嚼唇出血"}, {"w": "过屠门而大嚼", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3480wx','嚷','1','rǎng rāng','口','20','','[{"pinyin": "rǎng", "defs": [{"meaning": "叫喊声。", "cites": [{"t": "只觉得耳朵边满是嘈杂的嚷。", "b": "鲁迅《故事新编》"}]}, {"meaning": "吵闹", "words": [{"w": "嚷嚷刮刮", "t": "吵吵嚷嚷"}, {"w": "嚷聒", "t": "嚷刮,嚷闹,嚷嚷。吵闹"}, {"w": "嚷乱", "t": "吵闹;捣乱"}]}, {"meaning": "叫喊", "words": [{"w": "嚷喝", "t": "大声吆喝"}]}, {"meaning": "责备;训斥", "words": [{"w": "嚷骂", "t": "大声责骂"}]}, {"meaning": "[方言]呼唤"}]}, {"pinyin": "rāng", "defs": [{"meaning": "叫嚷；吵闹"}, {"meaning": "声张，传扬;把消息、事情等传出去"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3481wx','巍','1','wēi','山','20','','[{"pinyin": "wēi", "defs": [{"meaning": "(形声。从山,魏声。本义:高大) 同本义。", "cites": [{"t": "巍,高也。", "b": "《说文》"}, {"t": "巍巍乎尧舜之有天下也。", "b": "《论语·泰伯》。集解:“巍巍者,高大也。”"}, {"t": "崛巍巍而特秀。", "b": "《文选·嵇康·琴赋》"}], "words": [{"w": "巍科", "t": "高级的科举高试"}, {"w": "巍廓", "t": "高大开阔"}, {"w": "巍耸", "t": "高耸"}, {"w": "巍蟠", "t": "高大而盘曲"}, {"w": "巍崇", "t": "高大"}, {"w": "巍张", "t": "高大宽阔"}, {"w": "巍峻", "t": "高峻"}, {"w": "巍冠", "t": "高冠"}, {"w": "巍奕", "t": "高大"}, {"w": "巍怪", "t": "高大奇特。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3482wx','籍','1','jí','竹','20','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从竹,耤(jí)声。古书以竹制成,故从“竹”。本义:登记册,户口册)。"}, {"meaning": "同本义。", "cites": [{"t": "籍,簿书也。", "b": "《说文》"}, {"t": "乃以九畿之籍。", "b": "《周礼·大司马》"}, {"t": "掌邦国宾客之体籍。", "b": "《周礼·小行人》。注:“名位尊卑之书。”"}, {"t": "非礼也勿籍。", "b": "《左传·成公二年》"}, {"t": "今荆州非少人也,而著籍者寡。", "b": "诸葛亮《论游户自实》"}, {"t": "宫观之籍。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "籍口", "t": "户口"}, {"w": "籍戎", "t": "编入军籍"}, {"w": "籍地", "t": "官宦门第"}, {"w": "削籍", "t": "官吏被革职,在官籍中除名"}, {"w": "除籍", "t": "于簿籍中除名。"}]}, {"meaning": "泛指书,成册的著作。", "cites": [{"t": "诸侯恶其害己也,而皆去其籍。", "b": "《孟子·万章下》"}, {"t": "五代时始印五经,已后典籍皆为版本。", "b": "《梦溪笔谈·活板》"}, {"t": "由是文籍生焉。", "b": "萧统《文选序》"}], "words": [{"w": "籍图", "t": "文籍图书"}, {"w": "书籍;古籍;经籍;典籍", "t": ""}]}, {"meaning": "代表个人的身份;代表个人对国家、组织的隶属关系。", "cites": [{"t": "玉郎会此通仙籍,忆向天街问紫芝。", "b": "李商隐《重过圣女祠》"}], "words": [{"w": "军籍;党籍;外籍;客籍;团籍;队籍", "t": ""}]}, {"meaning": "籍贯。", "cites": [{"t": "顷小儿回籍应举。", "b": "张居正《答应天巡抚宋阳山书》"}], "words": [{"w": "回籍;原籍", "t": ""}]}, {"meaning": "征籍。中国古代各种捐税的统称。", "cites": [{"t": "实亩实籍。", "b": "《诗·大雅·韩奕》"}], "words": [{"w": "籍税", "t": "征收租税"}, {"w": "籍赋", "t": "赋税"}, {"w": "籍敛", "t": "征收田税"}, {"w": "籍求", "t": "敛取"}, {"w": "籍取", "t": "敛取;征收"}, {"w": "籍兵", "t": "征集兵士。"}]}, {"meaning": "门籍,一种写有当事人姓名的小牌子。", "cites": [{"t": "光夫人显及诸女皆通籍长信宫", "b": "《汉书·魏相传》"}]}, {"meaning": "又。", "cites": [{"t": "汉代有事需要出入宫门者,皆有门籍悬于宫门,以备案验", "b": ""}]}, {"meaning": "登记。", "cites": [{"t": "籍吏民。(籍,登记。登记官吏、人民,就是造花名册、户籍册等。)", "b": "《史记·项羽本纪》"}], "words": [{"w": "籍名", "t": "登记籍贯名字"}, {"w": "籍没", "t": "登记并没收所有的财产"}, {"w": "籍夫", "t": "登记征用民夫"}, {"w": "籍田", "t": "藉田。古代天子亲耕之田。以所获祭祀宗庙,并寓劝农之意。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3483wx','鳞','1','lín','鱼','20','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从鱼,粦(lìn)声。本义:鱼甲)。"}, {"meaning": "同本义。", "cites": [{"t": "鳞,鱼甲也。", "b": "《说文》"}, {"t": "鳞罗布烈。", "b": "扬雄《羽猎赋》"}, {"t": "鳞浪层层。", "b": "明·袁宏道《满井游记》"}, {"t": "鳞爪飞扬。", "b": "清·梁启超《饮冰室合集·文集》"}, {"t": "朱鳞大鬣。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "鳞爪", "t": "喻残存、零碎或无足轻重之物"}, {"w": "鳞沦", "t": "水纹相次连接的样子"}, {"w": "鳞接", "t": "密接如鱼鳞"}, {"w": "鳞萃", "t": "荟萃如鱼鳞。"}]}, {"meaning": "鳞片状物。", "cites": [{"t": "鳞,甲也。", "b": "《广雅》"}, {"t": "其动物宜鳞物。", "b": "《周礼·大司徒》"}]}, {"meaning": "鱼的代称。", "cites": [{"t": "鳞集仰流。", "b": "司马相如《难蜀父老》。注:“鳞集,相次也。”"}, {"t": "呷浪之鳞。", "b": "明·袁宏道《满井游记》"}, {"t": "锦鳞游泳。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "鳞族", "t": "鱼类"}, {"w": "鳞羽", "t": "泛指鱼类和鸟类"}, {"w": "鳞物", "t": "指鱼类"}, {"w": "鳞鸿杳绝", "t": "杳无音信"}, {"w": "鳞集仰流", "t": "鱼群迎向上游。比喻四方之民慕德来归。"}]}, {"meaning": "有鳞动物的总称。", "cites": [{"t": "鳞虫三百六十而龙为之长。", "b": "《孔子家语·执辔》"}, {"t": "介鳞夏食冬蛰。", "b": "《易·主命》"}], "words": [{"w": "鳞介", "t": "泛指有鳞片介甲的水生动物"}, {"w": "鳞虫", "t": "有鳞的动物。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3484wx','魔','1','mó','鬼','20','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从鬼,麻声。本义:“魔罗”的略称。佛教把一切扰乱身心、破坏行善、妨碍修行的心理活动均称为“魔”)。"}, {"meaning": "同本义。", "cites": [{"t": "我自降魔转法轮。", "b": "王安石《南乡子》"}], "words": [{"w": "病魔;魔道", "t": "佛家语。指天魔邪鬼活动的境域"}, {"w": "魔女", "t": "魔界的女人"}, {"w": "魔劫", "t": "命中注定的灾难"}, {"w": "魔事", "t": "佛教指成道的障碍"}, {"w": "魔天", "t": "魔道的天界"}, {"w": "魔心", "t": "邪恶之心"}, {"w": "魔浆", "t": "指酒。佛教认为饮酒不能修成正果。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3485wx','糯','1','nuò','米','20','','[{"pinyin": "nuò", "defs": [{"meaning": "酒的别称。", "cites": [{"t": "金荷,斟香糯。", "b": "汤显祖《牡丹亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3486wx','灌','1','guàn','氵','20','','[{"pinyin": "guàn", "defs": [{"meaning": "(形声。从水,雚(guàn)声。本义:灌水)。"}, {"meaning": "同本义。", "cites": [{"t": "灌,灌水也。出庐江雩娄北入淮。", "b": "《说文》"}]}, {"meaning": "灌水,源出河南省商城县南,东北经固始县西南曰曲河,北合史河流入淮水。"}, {"meaning": "丛生的树木。", "cites": [{"t": "灌木,丛木。又,木族生为灌。", "b": "《尔雅》"}, {"t": "灌,丛也。", "b": "《小尔雅》"}, {"t": "集于灌木。", "b": "《诗·周南·葛覃》"}, {"t": "而灌木丛林,蒙茸山麓,未经删治如今者,则无疑也。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "灌木;灌莽;灌丛", "t": ""}]}, {"meaning": "浇;灌溉。", "cites": [{"t": "灌,浇也,渍也。", "b": "《广韵》"}, {"t": "时雨降矣,而犹浸灌。", "b": "《庄子·逍遥游》"}, {"t": "以筒水灌之始出,状极俊健。", "b": "《聊斋志异·促织》"}, {"t": "引河水灌民田。", "b": "《史记·西门豹列传》"}], "words": [{"w": "灌植", "t": "浇水培植"}, {"w": "灌濡", "t": "浇灌润泽"}, {"w": "灌渎", "t": "灌溉用的小沟渠"}, {"w": "灌畦", "t": "灌溉种菜"}, {"w": "灌蔬", "t": "栽培菜蔬。"}]}, {"meaning": "流注。", "cites": [{"t": "秋水时至,百川灌河。", "b": "《庄子·秋水》"}], "words": [{"w": "灌溢", "t": "流布"}, {"w": "灌澍", "t": "灌注,流泻"}, {"w": "灌洗", "t": "冲洗。"}]}, {"meaning": "强行使喝下。", "cites": [{"t": "不能饮者以筒灌其中。", "b": "《韩非子·说疑》"}], "words": [{"w": "灌米汤", "t": "恭维"}, {"w": "灌口", "t": "方言。给牲口灌药用的器具。"}]}, {"meaning": "古代祭祀的一种形式。斟酒浇地以求神降临。", "cites": [{"t": "子曰:“禘,自既灌而往者,吾不欲观之矣。”", "b": "《论语·八佾》"}, {"t": "灌用郁鬯。", "b": "《礼记·礼器》"}], "words": [{"w": "灌地", "t": "洒酒于地,求神降临。"}]}, {"meaning": "浇铸。", "cites": [{"t": "烁一鼎之铜,以灌一钱之形,不能成一鼎。", "b": "汉·王充《论衡·奇怪》"}], "words": [{"w": "灌辟", "t": "冶铸,冶炼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3487wx','譬','1','pì','言','20','','[{"pinyin": "pì", "defs": [{"meaning": "(形声。从言,辟声。本义:譬如,比喻) 同本义。", "cites": [{"t": "譬,喻也。", "b": "《说文》"}, {"t": "譬彼舟流。", "b": "《诗·小雅·小弁》"}, {"t": "能近取譬。", "b": "《论语》"}, {"t": "臣窃为公譬可也。", "b": "《战国策·齐策》"}], "words": [{"w": "譬如", "t": "举例以比喻"}, {"w": "譬犹", "t": "譬诸。譬若。譬如"}, {"w": "譬况", "t": "比喻形容"}, {"w": "譬谕", "t": "比喻。"}]}, {"meaning": "晓谕,使人知晓。", "cites": [{"t": "又譬诸外戚。", "b": "《后汉书》。注:“譬,晓谕也。”"}], "words": [{"w": "譬称", "t": "用譬喻的言辞解说"}, {"w": "譬类", "t": "以类相比喻。"}]}, {"meaning": "明白,晓得。", "cites": [{"t": "言之者虽诚,而闻之未譬。", "b": "《后汉书》。注:“譬,犹晓也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3488wx','蠢','1','chǔn','虫','21','','[{"pinyin": "chǔn", "defs": [{"meaning": "(形声。本义:昆虫慢慢地爬行)。"}, {"meaning": "同本义。", "cites": [{"t": "蠢,虫动也。", "b": "《说文》"}, {"t": "蠢尔蛮荆。", "b": "《诗·小雅·采芑》"}, {"t": "今王室实蠢蠢焉。", "b": "《左传·昭公二十四年》"}, {"t": "万物蠢生。", "b": "左思《吴都赋》"}], "words": [{"w": "蠢动;蠢蠢", "t": "蠕动的样子。"}]}, {"meaning": "愚蠢;愚昧。", "cites": [{"t": "时人愚蠢,不知相绳责也。", "b": "汉·王充《论衡》"}], "words": [{"w": "蠢坌", "t": "蠢笨"}, {"w": "蠢虫", "t": "糊涂虫"}, {"w": "蠢左", "t": "愚蠢的帮手"}, {"w": "蠢臭", "t": "愚蠢的气味"}, {"w": "蠢顽", "t": "愚蠢顽劣"}, {"w": "蠢愚", "t": "愚蠢"}, {"w": "蠢宝", "t": "犹蠢货"}, {"w": "蠢类", "t": "愚蠢的一伙。"}]}, {"meaning": "笨拙;粗俗。", "cites": [{"t": "蠢身躯似水牛。", "b": "高安道《哨遍·嗓淡行院》"}], "words": [{"w": "蠢堆堆", "t": "形容笨拙粗壮"}, {"w": "蠢躁", "t": "笨拙急躁。"}]}, {"meaning": "不谦逊。", "cites": [{"t": "蠢,不逊也。", "b": "《尔雅·释训》"}]}, {"meaning": "小貌。谓少量聚居。", "cites": [{"t": "百蛮蠢居,仞彼方徼。", "b": "《后汉书》。李贤注:“蠢,小貌也”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3489wx','霸','1','bà','雨','21','','[{"pinyin": "bà", "defs": [{"meaning": "(形声。从月。①(pò)本义:阴历每月之初始见的月光。这个意义又写作“魄”。②古代诸侯之长)。"}, {"meaning": "假借为伯。指古代诸侯联盟的盟主。", "cites": [{"t": "霸者,伯也,行方伯之职。", "b": "《白虎通》"}, {"t": "管仲以其君霸。", "b": "《孟子·公孙丑上》"}, {"t": "霸者,长也。言为诸侯之长。", "b": "《孟子·离娄·丁音》"}, {"t": "五霸不同法而霸。", "b": "《商君书·更汉》"}], "words": [{"w": "春秋五霸;霸王请客;强留", "t": "歇后语。"}]}, {"meaning": "依仗权势或实力横行一方的人。", "cites": [{"t": "薛家系金陵一霸。", "b": "曹雪芹《红楼梦》"}], "words": [{"w": "渔霸;恶霸", "t": ""}]}, {"meaning": "称霸。", "cites": [{"t": "共工氏之霸九州也。", "b": "《礼记·祭法》"}, {"t": "遂霸有天下。", "b": "《史记·项羽本纪》"}], "words": [{"w": "各霸一方;独霸天下;霸道", "t": "指行事蛮不讲理。"}]}, {"meaning": "霸占。", "cites": [{"t": "硬把桦林山这座天生天化的东西霸成他自己的家产。", "b": "《吕梁英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3490wx','露','1','lù lòu','雨','21','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从雨,路声。本义:露水)。"}, {"meaning": "靠近地面的水蒸气，夜间遇冷凝结成的小水球。", "cites": [{"t": "露,润泽也。", "b": "《说文》。段注:“泽与露叠韵。五经通义曰:和气津凝为露。蔡邕月令曰:露者,阴之液也。按,露之言胪也。故凡陈列表见于外曰露。”朱曰:“士气津液从地而兴,若薄以寒气,即结而为霜。”"}, {"t": "阳气胜则散为雨露。", "b": "《多戴礼记·曾子天圆》"}, {"t": "白露为霜。", "b": "《诗·秦风·蒹葭》"}]}, {"meaning": "又。", "cites": [{"t": "白露未已。", "b": ""}, {"t": "朝露待日晞。", "b": "《乐府诗集·长歌行》"}, {"t": "人生如朝露。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "雨露", "t": "雨和露。比喻恩惠"}, {"w": "露草", "t": "沾露的草;植物名"}, {"w": "露师", "t": "军队蒙受风霜雨露,住宿在外"}, {"w": "露水姻缘", "t": "短暂的、不正当的男妇关系。"}]}, {"meaning": "水气。", "cites": [{"t": "白露横江。", "b": "苏轼《赤壁赋》"}]}, {"meaning": "道路。", "cites": [{"t": "微君之故,胡为乎中露。", "b": "《诗·邶风·式微》"}, {"t": "朝群臣于露门。", "b": "《周书·武帝纪上》"}]}, {"meaning": "显露;显现在外。", "cites": [{"t": "今乐远出以露威灵。", "b": "《文选·扬雄·长杨赋》"}, {"t": "都邑露。", "b": "《荀子·富国》。注:“谓无城郭墙垣。”"}, {"t": "乃露布上书。", "b": "《后汉书·李云传》。注:“露布,谓不封也。”"}, {"t": "止露尻尾。", "b": "《聊斋志异·狼三则》"}, {"t": "袒胸露乳。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "赤身露体;藏头露尾;抛头露面;露白", "t": "财宝被人看见"}, {"w": "露天生意", "t": "摆摊卖货"}, {"w": "露堂", "t": "室外;露天"}, {"w": "露止", "t": "栖宿在屋外或野外"}, {"w": "露立", "t": "露天站立"}, {"w": "露布", "t": "指不封口的公文或布告。"}]}, {"meaning": "滋润。", "cites": [{"t": "英英白云,露彼菅茅。", "b": "《诗·小雅·白华》"}]}, {"meaning": "庇护。", "cites": [{"t": "智子之道善矣,是先生覆露子也。", "b": "《国语》"}]}, {"meaning": "败坏。", "cites": [{"t": "勿使有所壅闭湫底,以露其体。", "b": "《左传》"}]}]}, {"pinyin": "lòu", "defs": [{"meaning": "", "words": [{"w": "露刃", "t": "刀剑出鞘"}, {"w": "露光;露相;露白", "t": "露于外。白:银子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3491wx','霹','1','pī','雨','21','','[{"pinyin": "pī", "defs": [{"meaning": "雷电轰击", "words": [{"w": "霹雳琴", "t": "用雷火焚烧过的枯桐做的琴"}, {"w": "霹雳闪电", "t": "使人胆战心惊"}, {"w": "霹雳火", "t": "急击的雷火,比喻急躁暴烈的性格"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3492wx','躏','1','lìn','足','21','','[{"pinyin": "lìn", "defs": [{"meaning": "(形声。从足,蔺(lìn)声。本义:使力的碾踏)。"}, {"meaning": "同本义。", "cites": [{"t": "躏玄鹤,乱昆鸡。", "b": "司马相如《上林赋》"}, {"t": "百姓奔走相蹂躏。", "b": "《汉书·王商传》"}], "words": [{"w": "躏践", "t": "踩踏;践踏"}, {"w": "躏蹂", "t": "踩踏"}, {"w": "躏藉", "t": "踩踏;践踏。"}]}, {"meaning": "欺压;伤害。", "cites": [{"t": "太后…恐百岁后为唐宗室躏藉无死所。", "b": "《新唐书·武后传》"}], "words": [{"w": "躏蹂", "t": "摧残"}, {"w": "躏跞", "t": "迫害"}, {"w": "躏轹", "t": "蹂躏"}, {"w": "躏蹙", "t": "摧残"}, {"w": "躏藉", "t": "压迫,伤害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3493wx','黯','1','àn','黑','21','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从黑,音声。本义:深黑色)。"}, {"meaning": "同本义。", "cites": [{"t": "黯,深黑色也。", "b": "《说文》"}, {"t": "黯,黑也。", "b": "《广雅》"}, {"t": "黯然而黑。", "b": "《史记·孔子世家》"}, {"t": "花过而采,则根色黯恶,此其效也。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "黯然", "t": "黑暗的样子。泛指黑色。"}]}, {"meaning": "昏暗,暗淡无光。", "cites": [{"t": "使史黯往观焉。", "b": "《淮南子·主术》"}, {"t": "后面也照见了丁字街头破匾上“古囗亭口”这四个黯淡的金字。", "b": "鲁迅《药》"}], "words": [{"w": "黯淡", "t": "昏暗不光明的样子。"}]}, {"meaning": "心神沮丧的样子。", "cites": [{"t": "黯然销魂者,惟别而已矣。", "b": "江淹《江文通集》"}], "words": [{"w": "黯然欲绝", "t": "形容极其伤感的情状。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3494wx','髓','1','suǐ','骨','21','','[{"pinyin": "suǐ", "defs": [{"meaning": "(形声。从骨,随省声。本义:骨中的凝脂)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3495wx','赣','1','gàn gòng','贝','21','','[{"pinyin": "gàn", "defs": [{"meaning": "(形声。从“贝”,表示与财物有关。①(gòng) 本义:赐给。②水名。也称赣江)。"}, {"meaning": "赣江,在江西省。", "cites": [{"t": "今赣人敖仓,予人河水,饥而餐之,渴而饮之。", "b": "《淮南子·精神》"}]}, {"meaning": "江西省的别称 ,因赣江纵贯本省而得名。"}]}, {"pinyin": "gòng", "defs": [{"meaning": "赐给。", "cites": [{"t": "赣,赐也。", "b": "《说文》"}, {"t": "一朝用三千钟赣。", "b": "《淮南子·要略》。高诱注:“钟,十斛也;赣,赐也。一朝赐群臣之费三万斛也。”"}, {"t": "今赣人敖仓,予人河水,饥而餐之,渴而饮之。", "b": "《淮南子·精神》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3496wx','囊','1','náng nāng','口','22','','[{"pinyin": "náng", "defs": [{"meaning": "(形声。大篆字形象两头扎起的口袋。本义:有底的口袋)。"}, {"meaning": "同本义。", "cites": [{"t": "囊,橐也。", "b": "《说文》"}, {"t": "括囊。", "b": "《易·坤》。疏:“所以贮物。”"}, {"t": "于橐于囊。", "b": "《诗·大雅·公刘》。传:“小曰橐,大曰囊。”"}, {"t": "所载不过囊衣。", "b": "《汉书·王吉传》。注:“有底曰囊,无底曰橐。”"}, {"t": "药囊提轲。", "b": "《战国策·燕策》"}, {"t": "先生如其指,内狼于囊。", "b": "马中锡《中山狼传》"}, {"t": "置书囊中。", "b": "唐·李朝威《柳毅传》"}, {"t": "锥之处囊中。", "b": "《史记·平原君虞卿列传》"}, {"t": "盛以锦囊。", "b": "宋·欧阳修《伶官传·序》"}], "words": [{"w": "囊橐", "t": "口袋;代指财物"}, {"w": "囊空羞涩", "t": "兜内无钱"}, {"w": "囊橐充盈", "t": "腰包钱足"}, {"w": "囊橐萧瑟", "t": "口袋中无钱"}, {"w": "囊锥露颖", "t": "比喻显露才华"}, {"w": "囊中术", "t": "指智谋"}, {"w": "囊辎", "t": "行李"}, {"w": "囊底", "t": "袋子里面"}, {"w": "囊空", "t": "袋中无钱"}, {"w": "囊涩", "t": "身无分文"}, {"w": "囊书", "t": "囊中书札。"}]}, {"meaning": "用口袋装。", "cites": [{"t": "策蹇驴,囊图书。", "b": "马中锡《中山狼传》"}]}, {"meaning": "又。", "cites": [{"t": "试再囊之。", "b": ""}], "words": [{"w": "囊米", "t": "装入口袋的米"}, {"w": "囊琴", "t": "装琴入袋"}, {"w": "囊载", "t": "装入囊中运走"}, {"w": "囊扑", "t": "把人装入袋中打死"}, {"w": "囊土", "t": "以袋盛土。"}]}, {"meaning": "覆盖;蒙住。", "cites": [{"t": "布囊其口。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "囊吞", "t": "囊括蚕食"}, {"w": "囊首", "t": "用袋蒙头致死"}, {"w": "囊奏", "t": "囊封,封事"}, {"w": "囊括四海", "t": "统一全国;包罗天下。"}]}]}, {"pinyin": "nāng", "defs": [{"meaning": "", "words": [{"w": "囊膪", "t": "猪的乳部肥而松软的肉。"}]}, {"meaning": "", "words": [{"w": "囊揣", "t": "虚弱，懦弱；"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3497wx','镶','1','xiāng','钅','22','','[{"pinyin": "xiāng", "defs": [{"meaning": "(形声。从金,襄声。本义:瓤子)。"}, {"meaning": "铸铜铁器模型的瓤子。", "cites": [{"t": "镶,作型中肠也。", "b": "《说文》"}]}, {"meaning": "古兵器名。", "cites": [{"t": "手持白头镶。", "b": "晋·张华《博陵王宫侠曲二首》"}]}, {"meaning": "镶嵌物相嵌或相配合。", "cites": [{"t": "单拿了一双老年四楞象牙镶金的筷子给刘姥姥。", "b": "《红楼梦》"}], "words": [{"w": "镶滚", "t": "在衣服边缘加一道边;女服加宽边叫镶,加窄边叫滚。"}]}, {"meaning": "俗称修补其缺处。", "cites": [{"t": "今市肆有补齿,一云镶齿,如生。", "b": "清·叶名沣《桥西杂记》"}], "words": [{"w": "镶牙", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3498wx','瓤','1','ráng','瓜','22','','[{"pinyin": "ráng", "defs": [{"meaning": "(形声。从瓜,襄(xiāng)声。本义:瓜类的肉)。"}, {"meaning": "同本义。", "cites": [{"t": "瓤肉莹白如冰雪。", "b": "唐·白居易《荔枝图序》"}]}, {"meaning": "浑浊的。", "cites": [{"t": "独你老人家的酒,我可不敢动他。回来又是怎么晃瓤了、温毛了,我又不会喝那东西,我也不懂。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3499wx','罐','1','guàn','缶','23','','[{"pinyin": "guàn", "defs": [{"meaning": "(形声。从缶(fǒu),雚声。从“缶”,表示与瓦器有关。本义:用陶或金属制成的汲水器、容器)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3500wx','矗','1','chù','目','24','','[{"pinyin": "chù", "defs": [{"meaning": "(会意。从三直。本义:直立) 同本义。", "cites": [{"t": "五步一楼,十步一阁,……矗不知其几千万落。", "b": "杜牧《阿房宫赋》"}, {"t": "释宫斯阐,上矗星斗。", "b": "舒元舆《唐鄂州永兴县重岩寺碑铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3501wx','乂','1','yì','丿','2','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。从丿从乂相交。又作“刈”。本义:割草或收割谷类植物)。"}, {"meaning": "同本义。", "cites": [{"t": "乂,芟草也。", "b": "《说文》"}]}, {"meaning": "治理;安定。", "cites": [{"t": "乂,治也。", "b": "《尔雅》"}, {"t": "有能俾乂。", "b": "《书·尧典》"}, {"t": "保国乂民。", "b": "《汉书·武五子传》"}, {"t": "朝野安乂。", "b": "《北史》"}], "words": [{"w": "乂安", "t": "太平无事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3502wx','乜','1','miē niè','乙','2','','[{"pinyin": "miē", "defs": [{"meaning": "眼睛眯成一条缝。", "cites": [{"t": "良材在烟榻上坐了,乜着眼又说道。", "b": "茅盾《霜叶红似二月花》"}], "words": [{"w": "乜斜", "t": "也作“乜邪”。眼睛眯成一条缝斜视"}, {"w": "乜嬉", "t": "眼略眯斜视。"}]}, {"meaning": "眯着眼斜视着。", "cites": [{"t": "鬼祟醉眼乜斜。", "b": "关汉卿《望江亭》"}], "words": [{"w": "乜嘢", "t": "什么事。"}]}]}, {"pinyin": "niè", "defs": [{"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3503wx','兀','1','wū wù','儿','3','','[{"pinyin": "wū", "defs": [{"meaning": "——“兀秃”wūtu:同“乌涂”wūtu。"}]}, {"pinyin": "wù", "defs": [{"meaning": "(指事。从一,在人上。人头上一横,表示高平。本义:高耸特出的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "兀,高而上平也。", "b": "《说文》"}, {"t": "何时眼前突兀见此屋。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "兀岸", "t": "直耸挺拔"}, {"w": "兀嵝", "t": "险峻。"}]}, {"meaning": "光秃(如毛发)的。", "cites": [{"t": "蜀山兀。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "兀首", "t": "头发脱落。"}]}, {"meaning": "茫然无知。", "cites": [{"t": "临文乍了了,彻卷兀若天。", "b": "柳宗元《读书》"}], "words": [{"w": "兀兀陶陶", "t": "醉酒"}, {"w": "兀楞楞", "t": "痴呆。"}]}, {"meaning": "独立。", "cites": [{"t": "焉有翡翠横肩,援琴合膝,而能兀焉自立者也?", "b": "清·吴从先《金小品传》"}]}, {"meaning": "动摇,摇晃。", "cites": [{"t": "兀其根本而能全于长世者也。", "b": "《后汉书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3504wx','弋','1','yì','弋','3','','[{"pinyin": "yì", "defs": [{"meaning": "(象形。甲骨文字形。本义:小木桩。今字作“杙”)。"}, {"meaning": "同本义。", "cites": [{"t": "以钩弋压下枝,令着地。", "b": "《齐民要术》"}]}, {"meaning": "指禽鸟。", "cites": [{"t": "十二月,鸣弋。弋也者,禽也。", "b": "《大戴礼记》"}]}, {"meaning": "姓氏。", "cites": [{"t": "美孟弋矣。", "b": "《诗·傭风·桑柔》"}]}, {"meaning": "射。用带绳子的箭射猎。", "cites": [{"t": "戈,缴射也。", "b": "《玉篇》"}, {"t": "弋凫与雁。", "b": "《诗·郑风·女曰鸡鸣》。疏:“弋,谓以绳系矢而射之也。”"}, {"t": "公弋取彼在穴。", "b": "《易·小过卦》。虞注:“弋,矰缴射。”"}, {"t": "夫弓弩毕弋机变之知。", "b": "《庄子·佉箧》"}, {"t": "善弋者下鸟乎百仞之上。", "b": "《吕氏春秋·功名》。注:“弋,缴射之也。”"}], "words": [{"w": "弋射", "t": "射鸟。"}]}, {"meaning": "黑色。", "cites": [{"t": "身衣弋绨。", "b": "《汉书·文帝纪》"}], "words": [{"w": "弋祶", "t": "黑色粗厚的丝织物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3505wx','孑','1','jié','子','3','','[{"pinyin": "jié", "defs": [{"meaning": "(象形。小篆字形,象人缺右臂形。本义:缺少右臂)。"}, {"meaning": "同本义。", "cites": [{"t": "孑,无右臂也。", "b": "《说文》"}]}, {"meaning": "孤单,单独。", "cites": [{"t": "胡有孑然其效戎翟也。", "b": "《国语·周语》"}, {"t": "何孤行之茕茕兮,孑不群而介立。", "b": "张衡《思玄赋》"}], "words": [{"w": "孑居", "t": "孑栖。独居"}, {"w": "孑弦", "t": "单弦"}, {"w": "孑轮", "t": "一辆车。"}]}, {"meaning": "剩余。", "cites": [{"t": "孑,余也。", "b": "《方言二》"}], "words": [{"w": "孑黎", "t": "遗民;残存的百姓"}, {"w": "孑余", "t": "剩余;残余。"}]}, {"meaning": "特立,出众。多指才能、人品等。", "cites": [{"t": "孑,俊也。", "b": "《方言二》"}, {"t": "孑孑干旄。", "b": "《诗·鄘风·干旄》"}], "words": [{"w": "孑杰", "t": "卓立,特出"}, {"w": "孑然", "t": "特立;又指孤立,孤单。"}]}, {"meaning": "戟。古代的一种兵器。", "cites": [{"t": "楚武王荆尸,授师孑焉,以伐随。", "b": "《左传·庄公四年》。杜预注:“尸,陈也。荆亦楚也,更为楚陈兵之法。扬雄《方言》:‘孑者,戟也。’”"}]}]}]','jingmo-wenyan');
