('3506wx','孓','1','jué','子','3','','[{"pinyin": "jué", "defs": [{"meaning": "(jiéjué)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3507wx','幺','1','yāo','幺','3','','[{"pinyin": "yāo", "defs": [{"meaning": "小;幼小。", "cites": [{"t": "幺,小也。象子初生之形。俗字作么。", "b": "《说文》"}, {"t": "不长曰幺。", "b": "《通俗文》"}, {"t": "幺麽皆微小之称也。", "b": "《汉书·叙传注》"}], "words": [{"w": "幺微", "t": "微小"}, {"w": "幺店", "t": "幺店子。路边的小店。"}]}, {"meaning": "细。", "cites": [{"t": "熠熠宵行,虫之微么;出自腐草,烟若散熛。", "b": "晋·郭璞《尔雅图赞》"}], "words": [{"w": "幺微", "t": "细微"}, {"w": "幺蔑", "t": "细微"}, {"w": "幺么", "t": "细小"}, {"w": "幺魔", "t": "微小,细微"}, {"w": "幺小", "t": "微小"}, {"w": "幺末", "t": "细微"}, {"w": "幺算", "t": "细致的考虑"}, {"w": "幺袅", "t": "柔条摆动的样子"}, {"w": "幺弱", "t": "瘦小赢弱"}, {"w": "幺弦", "t": "幺弦。琵琶的第四弦,借指琵琶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3508wx','亓','1','qí','二','4','','[{"pinyin": "qí", "defs": [{"meaning": "“其”的古字。", "cites": [{"t": "身死国亡,为天下笑,子亓慎之。", "b": "《墨子》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3509wx','韦','1','wéi','韦','4','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从舛(chuǎn),舛像两脚相对形。意为违背。囗声。韋是違的初字。本义:违背) 同本义。", "cites": [{"t": "韦,相背也。……经传多以违为之。", "b": "《说文》"}, {"t": "五音六律,依韦响昭。", "b": "《汉书·礼乐志》"}]}, {"meaning": "熟皮,去毛熟治的皮革。", "cites": [{"t": "兽皮之韦可以束枉。戾相违背,故借以为皮韦。按,熟曰韦,生曰革。", "b": "朱骏声《说文通训定声》"}, {"t": "韦,柔皮也。", "b": "《字林》"}, {"t": "凡兵事韦弁服。", "b": "《周礼·司服》"}, {"t": "韦藩木楗以过于朝。", "b": "《国语·晋语》。注:“韦藩,韦蔽前后。”"}, {"t": "乘韦先牛十二。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "韦弁", "t": "古冠名。皮帽"}, {"w": "韦柔", "t": "性格软弱"}, {"w": "韦带", "t": "以韦皮为带,无饰,古代未仕者之服饰"}, {"w": "韦裳", "t": "熟皮制的衣裳。"}]}, {"meaning": "皮绳。", "cites": [{"t": "无待韦弦。", "b": "《王文宪集序》。注:“韦,皮绳也。”"}], "words": [{"w": "韦布", "t": "韦带布衣;借指普通百姓"}, {"w": "韦弦", "t": "皮绳和弓弦。前者柔韧,后者坚直,比喻缓急。也比喻箴规,矫治"}, {"w": "韦编", "t": "古代用竹简写书,然后用韦皮编联起来,称为韦编。后世用为一般古籍的代称。"}]}, {"meaning": "计算圆周的量词", "cites": [{"t": "是日大风,拔甘泉畤中大木十韦以上。", "b": "《汉书·成帝纪》"}]}, {"meaning": "古国名 ,豕韦的简称。春秋时卫地。故址在今河南省滑县境内。", "cites": [{"t": "韦顾既伐,昆吾夏桀。", "b": "《诗·商颂·长发》"}]}, {"meaning": "韦伯的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3510wx','廿','1','niàn','廾','4','','[{"pinyin": "niàn", "defs": [{"meaning": "二十。后也大写作“念”。", "cites": [{"t": "三月念六。", "b": "清·林觉民《与妻书》"}, {"t": "廿二日天稍和。", "b": "明·袁宏道《满井游记》"}, {"t": "经廿年。", "b": "[英]赫胥黎著、严复译《天演论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3511wx','丏','1','miǎn','一','4','','[{"pinyin": "miǎn", "defs": [{"meaning": "(象形。本义:遮蔽) 同本义;看不见。", "cites": [{"t": "丏,不见也。", "b": "《说文》"}, {"t": "象人头上有物蔽之之形。", "b": "林义光《文源》"}]}, {"meaning": "避箭的短墙。", "cites": [{"t": "丏,避箭短墙也。", "b": "《字汇·一部》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3512wx','卅','1','sà','十','4','','[{"pinyin": "sà", "defs": [{"meaning": "三十。", "cites": [{"t": "卅,三十并也。", "b": "《说文》。一般写作“卅”。"}, {"t": "说文云:“卅,三十也。”今作卅,直以三十字。", "b": "《广韵》"}, {"t": "是当前之所见,经廿年、卅年而革焉可也。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "五卅运动", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3513wx','仄','1','zè','人','4','','[{"pinyin": "zè", "defs": [{"meaning": "(会意。小篆字形象人侧身在山崖洞穴里的形状。本义:倾斜)。"}, {"meaning": "同本义。", "cites": [{"t": "仄,侧倾也。", "b": "《说文》"}, {"t": "行山者仄輮。", "b": "《周礼·考工记·车人》"}, {"t": "众畏其口,见之仄目。", "b": "《汉书·息夫躬传》"}, {"t": "日极则仄,月满则亏。", "b": "《管子·白心》"}, {"t": "每旦视朝,日仄乃罢。", "b": "《后汉书·光武纪》"}], "words": [{"w": "仄歪", "t": "方言。倾斜摇晃"}, {"w": "仄日", "t": "夕阳,斜阳"}, {"w": "仄席", "t": "不敢正座,侧身坐在席上。形容忧心的样子"}, {"w": "仄起", "t": "倾斜突起"}, {"w": "仄目", "t": "斜着眼看"}, {"w": "仄步", "t": "行走歪斜貌。"}]}, {"meaning": "内心不安。", "cites": [{"t": "衷怀歉仄,自叹无缘。", "b": "《红楼梦》"}], "words": [{"w": "仄悚", "t": "恐惧不安"}, {"w": "仄兀", "t": "歉疚不安。"}]}, {"meaning": "狭窄。", "cites": [{"t": "险道倾仄,且驰且射。", "b": "《汉书》"}], "words": [{"w": "人多地仄;仄小", "t": "狭小,窄小"}, {"w": "仄陋", "t": "狭窄简陋"}, {"w": "仄狭", "t": "狭窄"}, {"w": "仄径", "t": "狭窄的小路"}, {"w": "仄道", "t": "狭窄的小路"}, {"w": "仄仄", "t": "狭窄。"}]}, {"meaning": "社会地位或政治地位低下的。", "cites": [{"t": "明明扬仄陋。", "b": "《书·尧典》"}], "words": [{"w": "仄微", "t": "卑贱,社会地位低。"}]}, {"meaning": "旁边。", "cites": [{"t": "若子之材,可优游都城而取卿相,何必勒功昆山之仄。", "b": "《汉书·段会宗传》"}, {"t": "行山者仄輮。", "b": "《周礼·考工记·车人》"}, {"t": "罢退外亲及旁仄素餐之人。", "b": "《汉书·鲍宣传》。颜师古云:“仄,古侧字也。”"}], "words": [{"w": "仄足", "t": "侧足"}, {"w": "仄室", "t": "侧室。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3514wx','厄','1','è','厂','4','','[{"pinyin": "è", "defs": [{"meaning": "(厂卩会意。“厂”象山崖,“卩”象人在崖洞下卷曲身子不得伸展。本义:困厄,遭遇困境) 同本义。", "cites": [{"t": "戹,隘也。从户,乙声,字亦作厄。", "b": "《说文》"}, {"t": "厄,困也。", "b": "《苍颉篇》"}, {"t": "厄难,勤苦之事也。", "b": "《诗·谷风》笺"}, {"t": "能济其厄涣。", "b": "《易·解注》"}, {"t": "仲尼厄而作《春秋》。", "b": "司马迁《报任安书》"}], "words": [{"w": "厄气", "t": "倒霉气"}, {"w": "厄难", "t": "困苦;遭遇不幸"}, {"w": "厄困", "t": "艰难窘迫"}, {"w": "厄苦", "t": "困苦"}, {"w": "厄急", "t": "艰难急迫。"}]}, {"meaning": "为难;迫害。", "cites": [{"t": "两贤岂相厄哉?", "b": "《史记·季布栾布列传》"}], "words": [{"w": "厄日", "t": "遭灾受难之日。"}]}, {"meaning": "灾难。", "cites": [{"t": "能济其厄。", "b": "西晋·左思《魏都赋》"}], "words": [{"w": "厄劫", "t": "危难,灾难"}, {"w": "厄会", "t": "众灾会合"}, {"w": "厄害", "t": "危难祸害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
