INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3517wx','仂','1','lè','亻','4','','[{"pinyin": "lè", "defs": [{"meaning": "(仂、扐同字)余数,零数。", "cites": [{"t": "凡数之余谓之扐。", "b": "《玉篇》"}, {"t": "仂,礼:“祭用数之仂。”", "b": "《广韵》"}, {"t": "丧用三年之仂。", "b": "《礼记·王制》"}], "words": [{"w": "仂句", "t": "长句子中包含的短句。旧称子句。现多称之谓词组"}, {"w": "仂词", "t": "词组。"}]}]}]','jingmo-wenyan');
