('3518wx','兮','1','xī','八','4','','[{"pinyin": "xī", "defs": [{"meaning": "啊  古代诗辞赋中的助词。", "cites": [{"t": "葛之覃兮,施于中谷。", "b": "《诗·周南·葛覃》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3519wx','刈','1','yì','刂','4','','[{"pinyin": "yì", "defs": [{"meaning": "(本作乂。形声。从刀,乂(yì)声。本作“义”。本义:割草)。"}, {"meaning": "同本义。", "cites": [{"t": "刈,断也。又,杀也。", "b": "《广雅》"}, {"t": "是刈是擭。", "b": "《诗·周南·葛覃》"}, {"t": "腰镰刈葵藿,倚杖牧鸡豚。", "b": "鲍照《代东武呤》"}], "words": [{"w": "刈获", "t": "收割;收获"}, {"w": "刈熟", "t": "指收割庄稼。"}]}, {"meaning": "杀。", "cites": [{"t": "而又刈亡之。", "b": "《国语·吴语》"}, {"t": "及后世贪者之用兵也,以刈百姓。", "b": "《大戴礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3520wx','爻','1','yáo','爻','4','','[{"pinyin": "yáo", "defs": [{"meaning": "(象形。本义:组成八卦的长短横道。卦的变化取决于爻的变化,故爻表示交错和变动的意义) 同本义。", "cites": [{"t": "爻,交也。象易六爻,头交也。", "b": "《说文》。按,乂,古文五,二五天地之数。会意。凡从爻之字,皆错杂意。"}, {"t": "道有变动,故曰爻。", "b": "《易·系辞下》"}], "words": [{"w": "爻分", "t": "交错分开"}, {"w": "爻错", "t": "交叉错杂。"}]}, {"meaning": "《周易》中组成卦的符号。 “—”为阳爻,“--”为阴爻。每三爻合成一卦,可得八卦;两卦(六爻)相重则得六十四卦,称为别卦。爻含有交错和变化之意。", "cites": [{"t": "六爻熟透,八卦精通。——《梼杌闲评——明珠缘》", "b": ""}, {"t": "爻者,言乎变者也。", "b": "《易·系辞上》"}], "words": [{"w": "爻律", "t": "变动音律"}, {"w": "爻象", "t": "《周易》中六爻相交成卦所表示的事物形象;形迹。"}]}, {"meaning": "爻辞的省称。", "cites": [{"t": "虽抱《中孚》爻,犹劳见锦诗。", "b": "南朝宋·谢灵运《初发石首城》"}], "words": [{"w": "爻画", "t": "指《易》卦"}, {"w": "爻系", "t": "爻辞"}, {"w": "爻辞", "t": "说明《易》六十四卦各爻象的文辞"}, {"w": "爻变", "t": "变卦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3521wx','卞','1','biàn','卜','4','','[{"pinyin": "biàn", "defs": [{"meaning": "法,法度。", "cites": [{"t": "卞,法也。", "b": "《玉篇》"}, {"t": "率循大卞。", "b": "《书·顾命》"}]}, {"meaning": "古地名 。春秋时鲁邑,汉置卞县,后魏废。故址在今山东泗水县东。"}, {"meaning": "急躁。", "cites": [{"t": "庄公卞急而好洁。", "b": "《左传·定公三年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3522wx','闩','1','shuān','门','4','','[{"pinyin": "shuān", "defs": [{"meaning": "(指事。从门,“一”象门闩形。本义:门上的横插) 同本义。", "cites": [{"t": "闩,门横关也。", "b": "范成大《桂海虞衡志·杂志》"}], "words": [{"w": "上闩;门闩", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3523wx','讣','1','fù','讠','4','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从言,卜声。 本义:报丧 。通告某人逝世的消息) 同本义。", "cites": [{"t": "凡讣于其君,曰:“君之臣某死。”", "b": "《礼记·杂记上》"}], "words": [{"w": "讣报", "t": "讣告"}, {"w": "讣帖", "t": "报丧的帖子"}, {"w": "讣电", "t": "报丧的电报"}, {"w": "讣音", "t": "报丧的信息或文告。"}]}, {"meaning": "报丧的文字。", "cites": [{"t": "祸丁舅氏,漂沦海沂,捧讣号呼,匍匐增悲。", "b": "唐·柳宗元《虞鸣鹤诔》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3524wx','尹','1','yǐn','尸','4','','[{"pinyin": "yǐn", "defs": [{"meaning": "(会意。甲骨文字形。左边一竖表示笔,右边是“又”(手),象手拿笔,以表示治事。本义:治理) 同本义。", "cites": [{"t": "尹,治也。", "b": "《说文》"}, {"t": "以尹天下。", "b": "《左传·定公四年》"}], "words": [{"w": "尹京", "t": "治理京畿"}, {"w": "尹祭", "t": "古代用于祭祀的切割方正的干肉。"}]}, {"meaning": "旧时官名。", "cites": [{"t": "令尹子文,三仕为令尹,无喜色。", "b": "《论语·公冶长》"}, {"t": "不以非郑尹。", "b": "唐·柳宗元《柳河东集》"}, {"t": "拥至尹前。", "b": "宋·胡仔《苕溪渔隐丛话》"}, {"t": "有卿尹。", "b": "清·周容《芋老人传》"}], "words": [{"w": "府尹;京兆尹;尹氏", "t": "官名。掌管册命臣工之事"}, {"w": "尹寺", "t": "宦官"}, {"w": "尹长", "t": "官长。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3525wx','夬','1','guài','大','4','','[{"pinyin": "guài", "defs": [{"meaning": "六十四卦之一,乾下兑上。", "cites": [{"t": "夬,决也,刚决桑也。", "b": "《易·夬》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3526wx','爿','1','pán','爿','4','','[{"pinyin": "pán", "defs": [{"meaning": "劈成片的竹木等。", "cites": [{"t": "爿,判木也。从反片。指事。", "b": "《说文》"}], "words": [{"w": "柴爿,竹爿", "t": ""}]}, {"meaning": "用于田地等,相当于“块”。", "cites": [{"t": "听说踏满一爿田就要一块多钱!", "b": "茅盾《秋收》"}]}, {"meaning": "用于整体的部分,相当于“边”、“段儿”、“截儿”等。", "cites": [{"t": "走上前一斧,将荷香砍做两半爿。", "b": "《说岳全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3527wx','毋','1','wú','毋','4','','[{"pinyin": "wú", "defs": [{"meaning": "(形声。“母”省声。毋、母古本为一字,后分化禁止之词,乃加一画以别之。本义:表示禁止的词。相当于莫、勿、不要)。"}, {"meaning": "同本义。", "cites": [{"t": "毋,止之也。", "b": "《说文》"}, {"t": "毋,止之辞。", "b": "《广韵》"}, {"t": "毋者,禁之也。", "b": "《论衡·谴告》"}, {"t": "毋不敬。", "b": "《礼记·曲礼上》"}, {"t": "毋吾以也。", "b": "《论语·先进》"}, {"t": "毋从俱死。", "b": "《史记·项羽本纪》"}, {"t": "毋内诸侯。", "b": ""}, {"t": "毋妄发。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "毋多谈。", "b": ""}], "words": [{"w": "毋或", "t": "不可"}, {"w": "毋多", "t": "不作他计"}, {"w": "毋己", "t": "不得,不能"}, {"w": "毋违", "t": "不得违误"}, {"w": "毋令逃逸;毋自欺", "t": ""}]}, {"meaning": "无。", "cites": [{"t": "身自持筑臿,胫毋毛。", "b": "《史记·秦始皇纪》"}], "words": [{"w": "毋害", "t": "无比。"}]}, {"meaning": "相当于“没有谁”或“没有人”。", "cites": [{"t": "毋敢夜行。", "b": "《史记》"}]}, {"meaning": "用于句首。", "cites": [{"t": "毋宁使人谓子,子实生我。", "b": "《左传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3528wx','邗','1','hán','阝','5','','[{"pinyin": "hán", "defs": [{"meaning": "水名,即邗沟,又名邗江、邗溟沟 。春秋时吴王夫差为争霸中原,在江淮间开凿的一条古运河名。"}, {"meaning": "邗江 ,县名,在江苏。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3529wx','邛','1','qióng','阝','5','','[{"pinyin": "qióng", "defs": [{"meaning": "故地名。邛城。", "cites": [{"t": "邛,邛地在济阴县。从邑,工声。按汉书外戚侯表,邛城属济阴,此地字盖城字之误。…在今山东东昌府。", "b": "《说文通训定声》"}]}, {"meaning": "中国古州名 。汉置临邛县,南朝梁改置邛州。唐初治所在今邛崃东南的依政,显庆中移治临邛(今邛崃)。在今四川省成都市西南。"}, {"meaning": "山名。即邛崃山 。在四川省荥经县西。", "cites": [{"t": "匪其止共,维王之邛。", "b": "《诗·小雅·巧言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3530wx','艽','1','jiāo','艹','5','','[{"pinyin": "jiāo", "defs": [{"meaning": "——“秦艽”(qínjiāo):草名。龙胆科。多年生草本,根入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3531wx','艿','1','nǎi rèng','艹','5','','[{"pinyin": "nǎi", "defs": [{"meaning": "——见“芋艿”(yùnǎi):即芋头。"}]}, {"pinyin": "rèng", "defs": [{"meaning": "乱草;杂草。", "cites": [{"t": "艿,艿草也。从草,乃声。…字亦作芿。", "b": "《说文》"}, {"t": "藉艿燔林。", "b": "《列子·黄帝》"}], "words": [{"w": "艿稗", "t": "泛指杂草。亦以喻芜杂的事物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3532wx','札','1','zhá','木','5','','[{"pinyin": "zhá", "defs": [{"meaning": "(形声。从木,札声。本义:古代用来写字的小木片)。"}, {"meaning": "同本义。", "cites": [{"t": "札,牒也。", "b": "《说文》"}, {"t": "皆一札十行,细书成文。", "b": "《后汉书·循吏传》"}, {"t": "卿有札书。", "b": "《汉书·郊祀志上》"}, {"t": "上令尚书给笔札。", "b": "《汉书·司马相如传上》"}, {"t": "上许,令尚书给笔札。", "b": "《史记·司马相如列传》"}, {"t": "郡国诸户口黄籍,籍皆用一尺二寸札,已在官役者载名。", "b": "《太平御览》"}]}, {"meaning": "引申为书信。", "cites": [{"t": "客从远方来,遗我一书札。", "b": "《古诗十九首》"}], "words": [{"w": "札帙", "t": "犹书函、书套"}, {"w": "札诲", "t": "赐函教诲。旧时书信套语"}, {"w": "札翰", "t": "书信。"}]}, {"meaning": "疫病。也指遭瘟疫死亡。", "cites": [{"t": "大札则不举。", "b": "《周礼》"}, {"t": "土气和,亡札厉。", "b": "《列子》"}], "words": [{"w": "札荒", "t": "瘟疫与灾荒"}, {"w": "札丧", "t": "因疫病死亡"}, {"w": "札厉", "t": "因疫病死亡"}, {"w": "札瘟", "t": "因疫疠、疾病而死"}, {"w": "札手风", "t": "手张开而不能自由伸缩的一种病。亦比喻醒态。"}]}, {"meaning": "拔出;拔除。", "cites": [{"t": "毫末不札,将寻斧柯。", "b": "《孔子家语》"}]}, {"meaning": "夭死。", "cites": [{"t": "疠疾不降,民不夭札。", "b": "《左传》"}]}, {"meaning": "刺。", "cites": [{"t": "语来言去各仇恨,棒迎拐架当心札。", "b": "《西游记》"}]}, {"meaning": "", "cites": [{"t": "刽子手将一把铁笊篱,在油锅里捞,…又奏道:“和尚身微骨嫩,俱札化了。”", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3533wx','叵','1','pǒ','口','5','','[{"pinyin": "pǒ", "defs": [{"meaning": "(会意。“可”字的反写。本义:不可)。"}, {"meaning": "同本义。", "cites": [{"t": "叵,不可也。", "b": "《三苍》。按,从反可,指事。"}, {"t": "怀故叵新欢。", "b": "谢灵运诗"}], "words": [{"w": "居心叵测;叵信", "t": "不可信"}, {"w": "叵奈", "t": "怎奈;无奈。"}]}, {"meaning": "遂,便,于是。", "cites": [{"t": "超欲因此叵平诸国。", "b": "《后汉书·班超传》。注:“犹逐也。”"}, {"t": "帝知其终不为用,叵欲讨之。", "b": "《后汉书·隗嚣传》"}]}, {"meaning": "多,甚", "cites": [{"t": "其是非叵缪于圣人。", "b": "《汉书·司马迁传赞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3534wx','匝','1','zā','匚','5','','[{"pinyin": "zā", "defs": [{"meaning": "周,环绕一周叫一匝。", "cites": [{"t": "帀,周也。从反帀而帀也。", "b": "《说文》。按,字亦作通,俗误作匝。"}, {"t": "就,帀也。", "b": "《周礼·典瑞》注。疏:“一采为一币,五采则五币。”"}, {"t": "周,币也。", "b": "《礼记·檀弓》注"}, {"t": "匝城兵士。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "绕树三匝;在门前绕了三匝;五匝;沿鼎壁游了一匝", "t": ""}]}, {"meaning": "遍;次。", "cites": [{"t": "帀,徧也。", "b": "《广雅》"}, {"t": "增光遂净手同进忠到方丈来,持香到禅座前,插在炉内拜三匝。", "b": "明·佚名《梼杌闲评》"}]}, {"meaning": "环绕。", "cites": [{"t": "水匝隍堑,于城东北合为一渎。", "b": "《水经注·河水》"}], "words": [{"w": "匝栏", "t": "围栏。"}]}, {"meaning": "笼罩,烟雾等弥漫着。", "cites": [{"t": "长雾匝高林。", "b": "鲍照《日落望江赠荀丞》"}]}, {"meaning": "遍;完满;周全。", "cites": [{"t": "不匝旬而得异地者二。", "b": "柳宗元《铕鉧潭西小丘记》"}], "words": [{"w": "匝年", "t": "满一年"}, {"w": "匝旬", "t": "满十天"}, {"w": "匝时", "t": "满一季"}, {"w": "匝岁", "t": "满一年"}, {"w": "匝地氍毹", "t": "遍地铺着毛毯"}, {"w": "匝洽", "t": "遍及。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3535wx','丕','1','pī','一','5','','[{"pinyin": "pī", "defs": [{"meaning": "(形声。从一,不声。本义:大) 同本义。", "cites": [{"t": "丕,大也。", "b": "《说文》"}, {"t": "未丕扬先帝之盛功。", "b": "《汉书·匡衡传》"}, {"t": "太医令吉丕。", "b": "《后汉书·耿秉传》"}, {"t": "昧旦丕显。", "b": "《左传·昭公三年》"}, {"t": "弼我丕丕基。", "b": "《书·大诰》"}], "words": [{"w": "丕变", "t": "大变"}, {"w": "丕训", "t": "伟大而可为法则的言论"}, {"w": "丕烈", "t": "伟大的功业"}, {"w": "丕业", "t": "伟大的事业"}, {"w": "丕绩", "t": "伟大的功绩"}, {"w": "丕显", "t": "伟大而显明"}, {"w": "丕丕基", "t": "极伟大的帝王家业。指帝王之位。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3536wx','匜','1','yí','匚','5','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从匚(fāng),也声。匚,受物之器。本义:古代盥洗时舀水用的器具,形状像瓢) 同本义", "words": [{"w": "匜水", "t": "以匜盛水。也指匜中的水"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3537wx','劢','1','mài','力','5','','[{"pinyin": "mài", "defs": [{"meaning": "努力,尽力。", "cites": [{"t": "劢,勉力也。", "b": "《说文》"}, {"t": "用劢相我国家。", "b": "《书·立政》。传:“用勉强治我国家。”疏:“使勉力治我国家。”"}, {"t": "如彼老马,心念超腾,道路崎岖,劢不可能。", "b": "明·刘基《春夜》"}]}]}]','jingmo-wenyan');
