INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3539wx','叱','1','chì','口','5','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从口,匕(bǐ)声。本义:大声呵斥)。"}, {"meaning": "同本义。", "cites": [{"t": "叱,呵也。", "b": "《说文》"}, {"t": "大呵为叱。", "b": "《苍颉篇》"}, {"t": "迮而吐之曰叱。", "b": "《通俗文》"}, {"t": "手剑而叱之。", "b": "《公羊传·庄公十二年》"}, {"t": "大儿初醒,夫叱大儿声。", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "叱咤", "t": "怒喝"}, {"w": "叱教", "t": "严格指教"}, {"w": "叱辱", "t": "斥责侮辱。"}]}, {"meaning": "呼喊;吆喝。", "cites": [{"t": "回车叱牛牵向北。", "b": "白居易《卖炭翁》"}], "words": [{"w": "叱名", "t": "呼名,报名"}, {"w": "叱令", "t": "喝令"}, {"w": "叱叫", "t": "大声呼喝"}, {"w": "叱嚷", "t": "叫嚷。"}]}, {"meaning": "斥声或叫声。", "cites": [{"t": "喑恶叱咤。", "b": "《史记·淮阴侯传》"}], "words": [{"w": "叱叱", "t": "呼喝声;大声指责的声音"}, {"w": "叱咄", "t": "怒斥声。"}]}]}]','jingmo-wenyan');
