INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3542wx','仕','1','shì','亻','5','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。从人,从士。本义:做官)。"}, {"meaning": "同本义。", "cites": [{"t": "学而优则仕。", "b": "《论语·子张》"}, {"t": "常经典籍为业,未遑仕进之事。", "b": "《后汉书·崔骃传》"}, {"t": "申子请仕其从兄官。", "b": "《韩非子·外储说左上》"}, {"t": "不仕无义。", "b": "《论语·微子》"}, {"t": "使天下仕者皆欲立于王之朝。", "b": "《孟子·梁惠王上》"}, {"t": "时墨者东郭先生将北适中山以干仕。", "b": "马中锡《中山狼传》"}, {"t": "乙先得举,登仕路,闻甲落魄,笑不顾,交以绝。", "b": "清·周容《芋老人传》"}], "words": [{"w": "仕官", "t": "就任官职"}, {"w": "仕途经济", "t": "通过“学而优则仕”的道路去做官"}, {"w": "仕止", "t": "出仕或隐退"}, {"w": "仕路", "t": "升官之路。"}]}, {"meaning": "从事;做事。", "cites": [{"t": "滔滔江、汉,南国之纪;尽瘁以仕,宁莫我有。", "b": "《诗·小雅·四月》"}]}, {"meaning": "学习政事,见习试用。", "cites": [{"t": "仕,学也。", "b": "《说文》。段玉裁注:“古义宦训仕,仕训学。”。朱曰:“犹今言试用也。”"}]}, {"meaning": "审察。检查。", "cites": [{"t": "弗躬弗亲,庶民弗信;弗问弗仕,勿罔君子。", "b": "《诗·小雅·节南山》"}]}, {"meaning": "职位。", "cites": [{"t": "或著显绩而婴时戮,或有大才而无贵仕,皆扬清风于上烈,垂令闻而不已。", "b": "晋·潘岳《西征赋》"}]}, {"meaning": "古代四民之一。指以道艺、武勇谋求仕进的人。", "cites": [{"t": "丰水有芑,武王岂不仕。", "b": "《诗·大雅·文王有声》"}, {"t": "此非能仕之所耻也。", "b": "《韩非子·说难》"}, {"t": "有仕于此,而子悦之。", "b": "《孟子·公孙丑下》"}], "words": [{"w": "仕子", "t": "泛指文人、学子"}, {"w": "仕林", "t": "士大夫阶层。"}]}, {"meaning": "官宦,官员。", "cites": [{"t": "仕女往住夜游。", "b": "孟元老《东京梦华录》"}], "words": [{"w": "仕版", "t": "官员的花名册"}, {"w": "仕户", "t": "官宦人家"}, {"w": "仕子", "t": "有官职的人"}, {"w": "仕籍", "t": "旧指记载官吏名籍的簿册。亦借指仕途,官场"}, {"w": "仕门", "t": "仕宦之家"}, {"w": "仕流", "t": "一般的官属"}, {"w": "仕家", "t": "官宦之家"}, {"w": "仕禄", "t": "官职,职务。"}]}, {"meaning": "事情。", "cites": [{"t": "增无易之仕。", "b": "王充《论衡》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3543wx','仟','1','qiān','亻','5','','[{"pinyin": "qiān", "defs": [{"meaning": "(会意。从人,从千。本义:古代军制,千人之长)。"}, {"meaning": "同本义。", "cites": [{"t": "蹑足行伍之间,絻仰仟佰之中。", "b": "《史记》。司马贞索隐:“仟佰,谓千人百人之长也。”"}]}, {"meaning": "“千”的大写。多用于记帐、汇款等书写金额的场合。", "cites": [{"t": "有仟佰之得。", "b": "《汉书·食货志上》。师古曰:“仟谓千钱也。”"}], "words": [{"w": "仟佰", "t": "千钱与百钱。借指利息,盈余。"}]}, {"meaning": "田间小道。", "cites": [{"t": "众庶街巷有马,仟佰之间成群。", "b": "《汉书·食货志上》"}], "words": [{"w": "仟佰", "t": "田间小道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3544wx','仡','1','yì','亻','5','','[{"pinyin": "yì", "defs": [{"meaning": "壮勇。", "cites": [{"t": "仡然从乎赵盾而入。", "b": "《公羊传》"}], "words": [{"w": "仡勇", "t": "壮勇,英武"}, {"w": "仡然", "t": "壮勇的样子"}, {"w": "仡仡", "t": "勇壮的样子。"}]}, {"meaning": "耸立。", "cites": [{"t": "崇墉仡仡。", "b": "《诗·大雅·皇矣》"}], "words": [{"w": "仡仡", "t": "高耸的样子"}, {"w": "仡立", "t": "直立不动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3545wx','仫','1','mù','亻','5','','[{"pinyin": "mù", "defs": [{"meaning": "中国少数民族，分布于广西壮族自治区。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3546wx','仞','1','rèn','亻','5','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从人,刃声。本义:古代长度单位。周制八尺,汉制七尺)。"}, {"meaning": "同本义。", "cites": [{"t": "仞,伸臂一寻八尺也。", "b": "《说文》"}]}, {"meaning": "按,诸说不一。", "cites": [{"t": "筑宫仞有三尺。", "b": "《礼记·祭义》"}, {"t": "深八尺谓之洫,深二仞谓之浍。", "b": "《考工记·匠人》"}, {"t": "太行、王屋二山,方七百里,高万仞。", "b": "《列子·汤问》"}, {"t": "一片孤城万仞山。", "b": "唐·王之涣《凉州词》"}, {"t": "夫子之墙数仞。", "b": "《论语·子张》"}]}, {"meaning": "春秋时楚地名,在今湖北省十堰市东。", "cites": [{"t": "子越自石溪,子贝自仞以伐庸。", "b": "《左传》"}]}, {"meaning": "用同“刃”。锋刃,借指刀剑之类的兵器。", "cites": [{"t": "仞,通作刃。", "b": "《正字通》"}]}, {"meaning": "测量深度。", "cites": [{"t": "计丈数,揣高卑,度厚薄,仞沟洫。", "b": "《左传》"}]}, {"meaning": "“认”的古字。"}, {"meaning": "承认。", "cites": [{"t": "公理者,犹云众所同仞之界域。", "b": "章炳麟《四惑论》"}]}, {"meaning": "认为,当作。", "cites": [{"t": "非其事者勿仞也…。仞人之事者败。", "b": "《淮南子·人间》"}, {"t": "惟通州五代所置,向无郡名,政和末,始赐名静海,史家遂误仞改州为郡矣。", "b": "清·钱大昕《廿二史考异》"}]}, {"meaning": "", "cites": [{"t": "是故百姓冬不仞寒,夏不仞暑,作疾病死者,不可胜计也。", "b": "《墨子》"}]}, {"meaning": "柔软而坚固。", "cites": [{"t": "巩用黄牛之革。", "b": "《易·革》。三国魏·王弼注:“牛之革坚仞不可变也。”"}]}, {"meaning": "满,充满。", "cites": [{"t": "虚宫馆而勿仞。", "b": "司马相如《上林赋》"}, {"t": "充仞其中者。", "b": "司马相如《子虚赋》"}], "words": [{"w": "仞积", "t": "堆满。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3547wx','卮','1','zhī','厄','5','','[{"pinyin": "zhī", "defs": [{"meaning": "古代一种盛酒器。圆形。容量四升。", "cites": [{"t": "赐之卮酒。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "奉卮酒为寿。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "与半卮酒。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "卮酒安足辞。", "b": ""}], "words": [{"w": "举厄", "t": "举起酒器。"}]}, {"meaning": "支离的。", "cites": [{"t": "卮言日出,和以天倪。", "b": "《庄子·寓言》"}], "words": [{"w": "卮言", "t": "支离而无统绪或随人妄言,既无主见,也无立场的、随和人意的言论"}, {"w": "卮辞", "t": "随和人意,无主见之词。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3548wx','氐','1','dī dǐ','氏','5','','[{"pinyin": "dī", "defs": [{"meaning": "低,低下", "cites": [{"t": "封君皆氐首仰给焉。", "b": "《汉书·食货志下》。师古曰:“氐首,犹俯首也。”"}]}, {"meaning": "中国古代的一个少数民族 ,居住在今西北一带,东晋时建立过前秦(在今黄河流域)、后凉(在今西北)。", "cites": [{"t": "自彼氐羌。", "b": "《诗·商颂·殷武》"}]}, {"meaning": "星名 ,二十八宿之一。氐宿,东方苍龙七宿的第三宿。有星四颗。也称“天根”。"}]}, {"pinyin": "dǐ", "defs": [{"meaning": "根本。", "cites": [{"t": "尹氏大师,维周之氐。", "b": "《诗·小雅·节南山》"}, {"t": "氐,本也。", "b": "《说文》。按,柢之古文。蔓根曰根,直根曰氐。"}, {"t": "氐,柢也。", "b": "《广雅·释言》"}, {"t": "固其氐也。", "b": "《太玄卷六坚》。注:“氐,本根也。”"}]}, {"meaning": "至,抵达", "cites": [{"t": "氐者言万物皆至也。", "b": "《史记·律书》"}]}, {"meaning": "停止。", "cites": [{"t": "进不氐,立不让。", "b": "《马王堆汉墓帛书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3549wx','犰','1','qiú','犭','5','','[{"pinyin": "qiú", "defs": [{"meaning": "哺乳动物，身体分前、中、后三段，头尾及胸部都有鳞片，腹部有毛，穴居土中，善于掘土。昼伏夜出，吃果、菜、蚊、蚯蚓等。肉可食，鳞甲可制提篮等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3550wx','刍','1','chú','刀','5','','[{"pinyin": "chú", "defs": [{"meaning": "(象形兼会意。甲骨文字形,从又(手)从草,表示以手取草。俗作芻。本义:割草)。"}, {"meaning": "同本义。", "cites": [{"t": "芻,刈草也。象包束草之形。", "b": "《说文》。按,象断草包束以饮马牛者也。"}, {"t": "七曰刍粖之式。", "b": "《周礼·太宰》"}, {"t": "淫刍荛者。", "b": "《左传·昭公十三年》"}, {"t": "禁刍牧采樵。", "b": "《左传·昭公六年》"}, {"t": "刍莝养马。", "b": "《越绝书·外传本事》"}], "words": [{"w": "刍牧", "t": "割草放牧。"}]}, {"meaning": "用草喂牲口。", "cites": [{"t": "刍之三月。", "b": "《周礼·地官·充人》"}], "words": [{"w": "刍养", "t": "饲养。"}]}, {"meaning": "喂牲畜的草。", "cites": [{"t": "食以刍叔。", "b": "《庄子·列御寇》"}, {"t": "馈之刍米。", "b": "《左传·僖公二十九年》"}, {"t": "民争负薪刍助之。", "b": "《资治通鉴》"}, {"t": "卒有取民麻一缕以束刍者,立斩以徇。", "b": "《宋史》"}], "words": [{"w": "刍菽", "t": "饲养牛马 的草料"}, {"w": "刍粟", "t": "粮草"}, {"w": "刍薪", "t": "柴草"}, {"w": "刍藁", "t": "饲养牲畜的干草"}, {"w": "刍豆", "t": "草和豆"}, {"w": "刍茭", "t": "干草"}, {"w": "刍粮", "t": "刍食,刍粟,粮草"}, {"w": "刍厩", "t": "饲料屋"}, {"w": "刍灵", "t": "用茅草扎成的人马"}, {"w": "刍藁", "t": "干草"}, {"w": "刍菽", "t": "刍豆。"}]}, {"meaning": "谷类植物的茎杆。"}, {"meaning": "割草的人。", "cites": [{"t": "陛下不废刍言,则端士贤者必当自效。", "b": "《旧唐书》"}]}, {"meaning": "吃草的牲口。", "cites": [{"t": "民食刍豢。", "b": "《庄子·齐物论》"}], "words": [{"w": "刍豢", "t": "指牛羊猪狗。牛羊食草,称刍;犬豕食谷,称豢。也泛指祭祀用的牺牲。"}]}]}]','jingmo-wenyan');
