INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3552wx','邙','1','māng','阝','5','','[{"pinyin": "māng", "defs": [{"meaning": "古邑名 。也作“亡”、“芒”。在今河南省洛阳市北。"}, {"meaning": "山名 。在今河南省洛阳市北。山连偃师、巩县、孟津3县地,绵亘400余里。山上多古代帝王陵墓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3553wx','汀','1','tīng','氵','5','','[{"pinyin": "tīng", "defs": [{"meaning": "(形声。从水,丁声。本义:水平)。"}, {"meaning": "同本义。", "cites": [{"t": "汀,平也。", "b": "《说文》。段玉裁注:“谓水之平也。水平谓之汀,因之洲渚之平谓之汀。”徐锴注:“水岸平处。”"}]}, {"meaning": "水边平滩。", "cites": [{"t": "岸芷汀兰。", "b": "宋·范仲淹《岳阳楼记》"}], "words": [{"w": "汀渚", "t": "水中小洲或水边平地"}, {"w": "汀葭", "t": "水边的芦苇"}, {"w": "汀喷", "t": "水涯,水滨。"}]}, {"meaning": "河流名。汀江 。在福建省西南部。"}, {"meaning": "古州名 。唐置。故州治在福建省长汀县。辖境约当今福建省汀江、九龙溪流域。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3554wx','讦','1','jié','讠','5','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从言,干声。本义:攻击别人的短处或揭发别人的阴私) 同本义。", "cites": [{"t": "讦,面相斥罪相告讦也。", "b": "《说文》"}, {"t": "恶讦以为直者。", "b": "《论语》。皇疏:“谓面发人之阴私也。”"}, {"t": "所上者,告讦也。", "b": "《汉书·贾谊传》"}, {"t": "吏民相告讦。", "b": "《汉书·赵广汉传》"}], "words": [{"w": "讦发", "t": "揭发,揭露"}, {"w": "讦告", "t": "揭发控告"}, {"w": "讦奏", "t": "揭发上奏"}, {"w": "讦调", "t": "揭露他人的隐私和短处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3555wx','讧','1','hòng','讠','5','','[{"pinyin": "hòng", "defs": [{"meaning": "(形声。从言,工声。本义:溃败)。"}, {"meaning": "同本义。", "cites": [{"t": "讧,瞆也。", "b": "《说文》"}, {"t": "蟊贼内讧。", "b": "《诗·大雅·召旻》"}], "words": [{"w": "讧柿", "t": "经过加工处理后由涩变甜变软的柿子"}, {"w": "讧溃", "t": "毁败。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3556wx','讪','1','shàn','讠','5','','[{"pinyin": "shàn", "defs": [{"meaning": "(形声。从言,山声。本义:毁谤)。"}, {"meaning": "同本义。", "cites": [{"t": "讪,谤也。与姗略同。", "b": "《说文》"}, {"t": "讪,诽毁也。", "b": "《苍颉篇》"}, {"t": "恶居下流而讪上者。", "b": "《论语》"}, {"t": "居下而讪上,处贫而非富。", "b": "《盐铁论·地广》"}, {"t": "有谏而无讪。", "b": "《礼记·少仪》"}], "words": [{"w": "讪上", "t": "毁谤在上位的人"}, {"w": "讪议", "t": "毁谤议论"}, {"w": "讪刺", "t": "毁谤讽刺。"}]}, {"meaning": "讥刺,挖苦。", "cites": [{"t": "见朝廷有所任使,非其资序,则相议而讪之。", "b": "王安石《上仁宗皇帝言事书》"}, {"t": "偏加些恶谑毒讪。", "b": "清·孔尚任《桃花扇》"}], "words": [{"w": "讪人", "t": "让人下不了台;小看人"}, {"w": "讪语", "t": "说讽剌话"}, {"w": "讪嘴", "t": "斗嘴"}, {"w": "讪侮", "t": "讥笑轻侮"}, {"w": "讪诮", "t": "讥笑嘲讽"}, {"w": "讪驳", "t": "讥笑批驳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3557wx','讫','1','qì','讠','5','','[{"pinyin": "qì", "defs": [{"meaning": "(形声。从言,乞声。从“言”,表示本与言语有关。本义:绝止;完毕)。"}, {"meaning": "同本义。", "cites": [{"t": "讫,止也。", "b": "《说文》"}, {"t": "毋讫籴。", "b": "《谷梁传·僖公九年》"}, {"t": "天既讫我殷命。", "b": "《书·西伯戡黎》。传:“天既毕讫殷之王命。”"}, {"t": "典狱非讫于威,惟讫于富。", "b": "《书·吕刑》。传:“非绝于威,惟绝于富。”"}, {"t": "讫不肯拜使者。", "b": "《汉书·西域传上》"}, {"t": "言讫。", "b": "唐·李朝威《柳毅传》"}, {"t": "用讫。", "b": "宋·沈括《梦溪笔谈·活板》"}, {"t": "言讫不见。", "b": "清·魏禧《大铁椎传》"}, {"t": "讫籴(终止籴粮);讫毕(完毕);讫竟(终止;了结);讫成(完成);讫工(讫功。竣工);讫情尽意(尽量满足自己的情感和心意);讫尽(一点不剩,穷尽)", "b": ""}]}, {"meaning": "到,至。", "cites": [{"t": "声教讫于四海。", "b": "《书·禹贡》"}, {"t": "讫今(至今);讫至(到,至)", "b": ""}]}, {"meaning": "尽;都。", "cites": [{"t": "民讫自若。", "b": "《书·秦誓》"}, {"t": "洁者,言阳气布畅,万物讫出,始洁之矣。", "b": "《后汉书·礼仪志上》"}]}, {"meaning": "毕竟;终究。", "cites": [{"t": "而康居骄黠,讫不肯拜使者。", "b": "《汉书·西域传》"}]}, {"meaning": "用在动词后表示动作已经完成。相当于“了”。", "cites": [{"t": "李大于郑县令面上打讫一拳,有伤。", "b": "沈仲纬《刑统赋疏》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3558wx','尻','1','kāo','尸','5','','[{"pinyin": "kāo", "defs": [{"meaning": "臀部。", "cites": [{"t": "身已半入,止露尻尾。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "尻间", "t": "屁股;臀部"}, {"w": "尻包儿", "t": "屁股。"}]}, {"meaning": "指男子对女子发生性行为。", "cites": [{"t": "你尻过多少个娘们?", "b": "周立波《暴风骤雨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3559wx','阡','1','qiān','阝','5','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从阜,千声。“阜”土山。与土有关。本义:田间南北向的小路)。"}, {"meaning": "同本义。", "cites": [{"t": "阡,路东西为陌,南北为阡。", "b": "《说文新附》"}, {"t": "阡,阡陌。", "b": "《广韵》"}, {"t": "为田开阡陌封疆,而赋税平。", "b": "《史记·商君列传》"}, {"t": "阡陌交通,鸡犬相闻。", "b": "晋·陶渊明《桃花源记》"}]}, {"meaning": "通往坟墓的小道。", "cites": [{"t": "哀挽青门去,新阡绛水遥。", "b": "杜甫《敌武卫将军挽词》之三"}]}, {"meaning": "泛指田间小路。", "cites": [{"t": "驱牛向东阡。", "b": "柳宗元《田家》"}, {"t": "要什么素车白马,断送出古陌荒阡。", "b": "元·关汉卿《窦娥冤》"}], "words": [{"w": "阡陇", "t": "田间高地"}, {"w": "阡塍", "t": "田埂。"}]}, {"meaning": "道路。", "cites": [{"t": "阡,路亦曰阡。", "b": "《增韵》"}, {"t": "越陌度阡,枉用相存。", "b": "曹操《短歌行》"}, {"t": "野径既盘纡,荒阡亦交互。", "b": "南朝梁·沈约《宿东园》"}]}, {"meaning": "坟墓。", "cites": [{"t": "其子修始克表于其阡。", "b": "欧阳修《沋冈阡表》"}], "words": [{"w": "阡原", "t": "墓地"}, {"w": "阡兆", "t": "墓地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3560wx','尕','1','gǎ','小','5','','[{"pinyin": "gǎ", "defs": [{"meaning": "[方]∶小——爱称,用于姓、名、排行等之前", "words": [{"w": "尕娃", "t": ""}, {"w": "尕蒋", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3561wx','弁','1','biàn','廾','5','','[{"pinyin": "biàn", "defs": [{"meaning": "古时的一种官帽,通常配礼服用(吉礼之服用冕)。赤黑色布做叫爵弁,是文冠;白鹿皮做的叫皮弁,是武冠。后泛指帽子。", "cites": [{"t": "覍,冠也。周曰覍,殷曰吁,夏曰收。", "b": "《说文》。俗作卞。凡大夫以上服冕,士弁,制如冕爵。"}, {"t": "弁者,古冠之大称。委貌缁布曰冠。", "b": "《周礼·弁师》注"}, {"t": "皮弁。", "b": "《仪礼·士冠礼》。服注:“以白鹿皮为冠。”"}, {"t": "弁,周冠名。", "b": "《广韵》"}, {"t": "突而弁兮。", "b": "《诗·小雅·甫田》"}, {"t": "王与大夫尽弁。", "b": "《书·金縢》。传:“弁,皮弁。”"}, {"t": "不说(tuō,脱掉)弁而死于崔氏。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "弁师", "t": "周礼官名。为夏官的属官。掌管帝王的冕服及等制"}, {"w": "弁冕", "t": "古时的礼帽。吉礼之服用冕,通常礼服用弁;又比喻首领、魁首。"}]}, {"meaning": "古时男子年满二十加冠称弁,以示成年。", "cites": [{"t": "未几见兮,突而弁兮。", "b": "《诗·齐风 ·甫田》"}], "words": [{"w": "弁丁", "t": "苦力,役夫。"}]}, {"meaning": "加冠头。", "cites": [{"t": "各立序论,以弁其端。", "b": "《唐诗品汇·总序》"}], "words": [{"w": "弁琼", "t": "指镶在马冠上的美玉。"}]}, {"meaning": "放在前面。", "cites": [{"t": "乃书是言以弁君为诗之端。", "b": "清·龚自珍《送徐铁生序》"}], "words": [{"w": "弁首", "t": "卷首,前言"}, {"w": "弁端", "t": "卷首"}, {"w": "弁语", "t": "弁言"}, {"w": "弁论", "t": "犹弁言。"}]}, {"meaning": "急。", "cites": [{"t": "予甚弁焉。", "b": "《汉书·王莽传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3562wx','驭','1','yù','马','5','','[{"pinyin": "yù", "defs": [{"meaning": "(会意。从又,从马。又,手。用手驾御马匹。本义:驾御车马)。"}, {"meaning": "同本义。", "cites": [{"t": "驭,使马也。驭,古文御。", "b": "《广韵》"}, {"t": "驭者,操辔也。", "b": "《管子·形势解》"}, {"t": "王良造父者,善服驭者也。", "b": "《荀子·王霸》。注:“驭,与御同也。”"}, {"t": "东野子之善驭乎?", "b": "《荀子·哀公》"}, {"t": "予临兆民,懔乎若朽索之驭六马。", "b": "《书·五子之歌》"}], "words": [{"w": "驭夫", "t": "古官名。掌管驾驭车"}, {"w": "驭吏", "t": "驾驭车马的役吏"}, {"w": "驭人", "t": "驾车马的人。"}]}, {"meaning": "控制,制约。", "cites": [{"t": "廪藏虚罄,难用驭远。", "b": "《宋书·后废帝纪》"}], "words": [{"w": "驭远", "t": "控制远邦"}, {"w": "驭教", "t": "掌握教化"}, {"w": "驭控", "t": "驾驭控制。"}]}, {"meaning": "统治;治理。", "cites": [{"t": "尉佗曾驭国,翁仲久游泉。", "b": "唐·沈佺期《度安海人入龙编》"}], "words": [{"w": "驭宇", "t": "帝王统治天下。同御宇"}, {"w": "驭宝", "t": "统治国家"}, {"w": "驭历", "t": "统治天下"}, {"w": "驭俗", "t": "整治习俗"}, {"w": "驭外", "t": "办理外交。"}]}, {"meaning": "驾车的人。", "cites": [{"t": "颜回为驭,子贡为右。", "b": "《庄子》"}]}, {"meaning": "马;车驾。", "cites": [{"t": "风为驭,雷为车,无辙迹,有烟霞。", "b": "《隋书·音乐志中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3563wx','匡','1','kuāng','匚','6','','[{"pinyin": "kuāng", "defs": [{"meaning": "(形声。从匚(fāng),表示与筐器有关,王声。本义:盛东西的方形竹器)。"}, {"meaning": "“筐”的古字。容器名。", "cites": [{"t": "匡,饭器,也。", "b": "《说文》"}, {"t": "既齐既稷,既匡既勑。", "b": "《诗·小雅·楚茨》"}, {"t": "蚕则绩而蟹有匡。", "b": "《礼记·檀弓》"}]}, {"meaning": "“框”的古字。边框;围子;框框。", "cites": [{"t": "行人夜宿墙匡月。", "b": "韦庄《秦妇吟》"}], "words": [{"w": "匡子", "t": "框子。"}]}, {"meaning": "“眶”的古字。眼眶。", "cites": [{"t": "刺匡上陷骨中脉,为漏为盲。", "b": "《素问》"}]}, {"meaning": "春秋时齐国简册名。", "cites": [{"t": "《管子》有《大匡》、《中匡》、《小匡》三篇", "b": ""}]}, {"meaning": "螃蟹的背壳。", "cites": [{"t": "海岛有蟹,其匡宛具一人面。", "b": "《拜经楼诗话》"}]}, {"meaning": "古地名。"}, {"meaning": "春秋时卫地,在今河南省长垣县西南。"}, {"meaning": "春秋时郑地。在今河南省扶沟县。"}, {"meaning": "山名,即江西省的庐山。"}, {"meaning": "纠正,匡正。", "cites": [{"t": "善则赏之,过则匡之。", "b": "《左传·襄公十四年》"}, {"t": "一匡天下。", "b": "《史记·货殖列传》"}, {"t": "今范中行氏之臣,不能匡相其君。", "b": "《国语·晋语九》"}], "words": [{"w": "匡言", "t": "匡正的言论"}, {"w": "匡弼", "t": "匡正辅助"}, {"w": "匡救", "t": "匡正挽救"}, {"w": "匡翼", "t": "匡正辅助"}, {"w": "匡邪", "t": "纠正邪恶。"}]}, {"meaning": "拯救。", "cites": [{"t": "匡乏困,救灾患。", "b": "《左传·成公十八年》"}], "words": [{"w": "匡危", "t": "拯救危难"}, {"w": "匡立", "t": "拯救国家,建立大业"}, {"w": "匡攘", "t": "拯救国家,驱逐敌人"}, {"w": "匡困", "t": "救助贫困"}, {"w": "匡时", "t": "挽救艰危的时局"}, {"w": "匡难", "t": "匡救国家的灾难。"}]}, {"meaning": "帮助;辅助,辅佐。", "cites": [{"t": "上匡天子。", "b": "《三国志》"}], "words": [{"w": "匡济之才", "t": "辅助、保全江山社稷的才能"}, {"w": "匡辅", "t": "帮助;辅佐"}, {"w": "匡君救国", "t": "扶助君王,辅佐国政"}, {"w": "匡尧", "t": "辅佐明君。"}]}, {"meaning": "弯曲。", "cites": [{"t": "则轮虽敝不匡。", "b": "《周礼·考工记》"}]}, {"meaning": "亏损。", "cites": [{"t": "日困而还,月盈而匡。", "b": "《国语》"}]}, {"meaning": "料定;料想。", "cites": [{"t": "你就匡我养不住,生起外心来了。", "b": "《二刻拍案惊奇》"}]}, {"meaning": "恐惧。", "cites": [{"t": "年虽大杀,众不匡惧。", "b": "《礼记·礼器》。郑玄注:“匡,犹恐也。”"}]}, {"meaning": "方正;端正。", "cites": [{"t": "匡坐至夜分。", "b": "李白《赠何七判官昌浩》"}], "words": [{"w": "匡坐", "t": "正坐,端坐"}, {"w": "匡士", "t": "正直的读书人"}, {"w": "匡床", "t": "文正宽大的床;安适的床"}, {"w": "匡勑", "t": "正直谨慎。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3564wx','耒','1','lěi','耒','6','','[{"pinyin": "lěi", "defs": [{"meaning": "(象形。古代的一种翻土农具,形如木叉,上有曲柄,下面是犁头,用以松土,可看作犁的前身。“耒”是汉字部首之一,从“耒”的字,与原始农具或耕作有关。本义:古代的一种农具,形状像木叉) 同本义。", "cites": [{"t": "耒,手耕曲木也。", "b": "《说文》"}, {"t": "天子亲载耒耜。", "b": "《礼记·月令》。注:“耒耜之上曲也。”"}, {"t": "耒耨之所刺。", "b": "《庄子·胠箧》。李注:“耜柄也,犁也。”"}, {"t": "耜其柄,耜其刃。", "b": "《后汉书·章帝纪》"}, {"t": "身执耒臿。", "b": "《韩非子·五蠹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3565wx','玎','1','dīng','王','6','','[{"pinyin": "dīng", "defs": [{"meaning": "玉类器物撞击时发出的声音。", "cites": [{"t": "玎,玉声也。", "b": "《说文》"}], "words": [{"w": "玎玎;玎琅;玎当;玎当响", "t": "比喻很有名声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3566wx','玑','1','jī','王','6','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从玉, 幾(jī)声。本义:不圆的珠子)。"}, {"meaning": "同本义。", "cites": [{"t": "璣,珠不圆者也。", "b": "《说文》"}, {"t": "厥篚元纁玑组。", "b": "《书·禹贡》"}, {"t": "傅玑之珥。", "b": "《史记·李斯传》"}, {"t": "爱已之一苍璧小玑。", "b": "《吕氏春秋·重已》"}, {"t": "赬丹明玑。", "b": "左思《吴都赋》"}, {"t": "瑇瑁珠玑。", "b": "《史记·货殖列传》"}], "words": [{"w": "玑镜", "t": "以有光的大珠制成的镜子;也指明镜。用以赞美他人的鉴识能力"}, {"w": "玑贝", "t": "珍珠宝贝;比喻佳作。"}]}, {"meaning": "玑衡,古代的一种天文仪器。", "cites": [{"t": "在璿玑玉衡。", "b": "《虞书》"}, {"t": "玑为转运。", "b": "《北堂书钞引书大传》"}, {"t": "玑衡(“璇玑玉衡”的省称。古代观测天体的仪器)", "b": ""}]}, {"meaning": "北斗的第三星。", "cites": [{"t": "文仰陟天玑。", "b": "《宋文皇帝元皇后哀策》"}], "words": [{"w": "玑璇", "t": "北斗七星中的星名。璇是其中第二星,玑是其中第三星,今称“天玑”,合称“璇玑”"}, {"w": "玑衡", "t": "星名。指北斗七星中的天玑与玉衡。也用以称观测天文的仪器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3567wx','邢','1','xíng','阝','6','','[{"pinyin": "xíng", "defs": [{"meaning": "古国名 。姬姓。公元前11世纪周公之子所封的诸侯国。在今河北省邢台市境。公元前662年,齐桓公曾迁邢于夷仪(今山东省聊城西南)。公元前635年为卫所灭。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3568wx','圩','1','wéi xū','土','6','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从土,于声。本义:低洼区防水护田的土堤)。"}, {"meaning": "同本义 。长江中游地区称为垸,统称“圩垸”。", "cites": [{"t": "圩,圩岸。", "b": "《字汇》"}], "words": [{"w": "圩丁", "t": "修筑圩田的人"}, {"w": "圩户", "t": "耕种圩田的农户"}, {"w": "圩防", "t": "堤坊,堤堰"}, {"w": "圩长", "t": "主管圩田堤防事务的人"}, {"w": "圩埂", "t": "围人的堤堰"}, {"w": "圩墙", "t": "用土石筑成的围绕村镇的墙。"}]}, {"meaning": "筑圩防水。", "cites": [{"t": "近水居民,又从而圩之田之,而向日受水之区,十去其七八矣。", "b": "《湖广水利论》"}]}]}, {"pinyin": "xū", "defs": [{"meaning": "", "words": [{"w": "赶圩", "t": "赶集"}, {"w": "圩埠", "t": "市集码头。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3569wx','圬','1','wū','土','6','','[{"pinyin": "wū", "defs": [{"meaning": "(形声。从木,亏(yú)声。“亏”即古“于”字。本义:抹子,涂墙的工具)镘子,泥瓦工人用来涂抹墙的抹子。", "cites": [{"t": "豫让刃其杇。", "b": "《战国策·赵策》"}], "words": [{"w": "圬人", "t": "圬者。泥瓦匠人。"}]}, {"meaning": "抹墙。", "cites": [{"t": "圬之为技,贱且劳者也。", "b": "韩愈《圬者王承福传》"}], "words": [{"w": "圬墁(镘)(涂饰墙壁,粉刷)", "t": ""}]}, {"meaning": "低洼的。", "cites": [{"t": "南峰中圬而平,其前峰为落雁,多松桧,亦曰松桧峰。", "b": "屈大钧《登华山记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3570wx','圭','1','guī','土','6','','[{"pinyin": "guī", "defs": [{"meaning": "(会意。“从重土”。本义:古玉器名。长条形,上端作三角形,下端正方。中国古代贵族朝聘、祭祀、丧葬时以为礼器。依其大小,以别尊卑。又作珪)。"}, {"meaning": "同本义。", "cites": [{"t": "瑞贽珪者兑上。", "b": "《白虎通》"}, {"t": "孰为珪璋。", "b": "《庄子·马蹄》。李注:“锐上方下曰珪。”"}, {"t": "以青圭礼东方。", "b": "《周礼·大宗伯》。注:“圭锐象春物初生。”"}, {"t": "司马牛致其邑与珪焉。", "b": "《左传·哀公十四年》。注:“守邑符信。”"}, {"t": "圭币(帛)俎豆(均为祭器)。", "b": "《汉书·郊祀志上》"}], "words": [{"w": "圭瑞", "t": "古代诸侯所执的玉制符信"}, {"w": "圭壁", "t": "古代王侯朝聘、祭祀时所用的贵重玉器。"}]}, {"meaning": "古代测日影的仪器“圭表”的部件。在石座上平放着的尺叫圭,南北两端立着的标杆叫表,根据日影的长短可以测定节气和一年时间的长短。", "cites": [{"t": "每每“亲星圭尺,躬察仪漏,目尽毫厘,心穷筹策。”", "b": "《祖冲之》"}], "words": [{"w": "圭臬", "t": ""}]}, {"meaning": "中国古代较小的容量单位。", "cites": [{"t": "圭撮涉于贫友,吝情动于颜色。", "b": "南朝梁·范缜《神灭论》"}], "words": [{"w": "圭勺", "t": "圭与勺。都是容量单位的名称"}, {"w": "圭撮", "t": "古代小单位的量名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3571wx','扦','1','qiān','扌','6','','[{"pinyin": "qiān", "defs": [{"meaning": "扦子,金属、竹等制成的针状物或主要部分是针状的器物"}, {"meaning": "[方言] 插入", "words": [{"w": "扦实", "t": "证实"}, {"w": "扦门", "t": ""}]}, {"meaning": "[方言] 修剪", "words": [{"w": "扦果枝", "t": ""}, {"w": "扦棉枝", "t": ""}]}]}]','jingmo-wenyan');
