('3572wx','圪','1','gē','土','6','','[{"pinyin": "gē", "defs": [{"meaning": "——如:圪登登(牙打颤的声音);圪吵(争吵,议论);。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3573wx','圳','1','zhèn','土','6','','[{"pinyin": "zhèn", "defs": [{"meaning": "(会意。从土,从川。川,水流。本义:田间水沟) 同本义 。多用于地名,如深圳,圳口,都在广东省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3574wx','圹','1','kuàng','土','6','','[{"pinyin": "kuàng", "defs": [{"meaning": "(形声。从土,广声。本义:墓穴)。"}, {"meaning": "同本义。", "cites": [{"t": "圹,堑穴也。", "b": "《说文》"}, {"t": "入圹。", "b": "《周礼·方相氏》。注:“穿地中也。”"}, {"t": "望其圹皋如也。", "b": "《荀子·大略》。注:“丘垅。”"}, {"t": "若从柩,及圹,皆执绋。", "b": "《礼记·夏官·方相氏》"}], "words": [{"w": "圹穴", "t": "墓穴"}, {"w": "圹兆", "t": "墓穴的范围。"}]}, {"meaning": "原野。", "cites": [{"t": "兽之走圹也。", "b": "《孟子·离娄上》"}, {"t": "以处圹埌之野。", "b": "《庄子·应帝王》。崔注:“犹旷荡也。”"}], "words": [{"w": "圹野", "t": "原野"}, {"w": "圹埌", "t": "原野空旷的样子。"}]}, {"meaning": "荒废。", "cites": [{"t": "敬谋无圹,敬事无圹,敬吏无圹,敬众无圹,敬敌无圹,夫是之谓五无圹。", "b": "《荀子·议兵》"}, {"t": "五世圹僚,自我节候。", "b": "《汉书·韦玄成传》"}, {"t": "不失天时,毋圹地利。", "b": "《管子·七法》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3575wx','扪','1','mén','扌','6','','[{"pinyin": "mén", "defs": [{"meaning": "(形声。从手,门声。本义:执持)。"}, {"meaning": "同本义。", "cites": [{"t": "扪,抚持也。", "b": "《说文》"}, {"t": "莫扪朕舌。", "b": "《诗·大雅·抑》。注:“扪,持也。”"}], "words": [{"w": "扪舌", "t": "握住舌头,使不能说话"}, {"w": "扪虱", "t": "捉住虱子"}, {"w": "扪月", "t": "捉月。"}]}, {"meaning": "抚摸。", "cites": [{"t": "乃扪足曰:“虏中吾指。”", "b": "《史记·高祖本纪》。索隐:“扪,摸也。”"}, {"t": "必先扪而循之。", "b": "《素问·离合真邪论》。注:“扪,谓手摸。”"}, {"t": "以手扪之。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "扪心", "t": "抚摸胸口"}, {"w": ";扪心自揣", "t": "按着胸口自我估量"}, {"w": "扪循", "t": "按摩"}, {"w": "扪摸", "t": "触摸;摸索"}, {"w": "扪腹", "t": "抚摸腹部"}, {"w": "扪索", "t": "摸索,寻求"}, {"w": "扪足", "t": "以手摸足"}, {"w": "扪参", "t": "抚摸参宿"}, {"w": "扪天", "t": "摸天。极言其高"}, {"w": "扪膝", "t": "摸膝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3576wx','圮','1','pǐ','土','6','','[{"pinyin": "pǐ", "defs": [{"meaning": "(形声。从土,己声。本义:毁;塌坏;坍塌)。"}, {"meaning": "同本义。", "cites": [{"t": "圮,毁也。", "b": "《说文》"}, {"t": "祖乙圮于耿。", "b": "《书·序》。传:“河水所毁曰圮。”"}, {"t": "覩有黎之圮坟。", "b": "《思玄赋》"}, {"t": "方命毁族。", "b": "《虞书·尧典》"}], "words": [{"w": "圮泐", "t": "石头毁坏开裂"}, {"w": "圮剥", "t": "毁分;毁坏剥蚀"}, {"w": "圮族", "t": "毁害种类"}, {"w": "圮坏", "t": "毁坏"}, {"w": "圮废", "t": "毁弃,荒废"}, {"w": "圮坏", "t": "坍塌"}, {"w": "圮倾", "t": "坍塌,倾颓"}, {"w": "圮毁", "t": "坍塌毁坏"}, {"w": "圮下", "t": "地面塌陷而形成的低洼"}, {"w": "圮缺", "t": "倾毁,残缺。"}]}, {"meaning": "断绝。", "cites": [{"t": "故宗绪中圮。", "b": "《东京赋》。注:“绝也。”"}], "words": [{"w": "圮绝", "t": "断绝"}, {"w": "圮隔", "t": "隔绝"}, {"w": "圮纽", "t": "谓不能维系。"}]}, {"meaning": "倾覆。", "cites": [{"t": "由我则固,不由我则圮。", "b": "柳宗元《梓人传》"}]}, {"meaning": "伤害。", "cites": [{"t": "圮剥至亲。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
