INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3579wx','芍','1','què sháo','艹','6','','[{"pinyin": "què", "defs": [{"meaning": "古代淮水流域最著名的水利工程。相传系春秋楚相孙叔敖所凿,在今安徽寿县东。又名‘期思陂’。"}]}, {"pinyin": "sháo", "defs": [{"meaning": "多年生草本植物，羽状复叶，小叶卵形或披针形。夏初开大花，供观赏，根可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3580wx','芄','1','wán','艹','6','','[{"pinyin": "wán", "defs": [{"meaning": "多年蔓生草本植物，断之有白汁，可食。叶对生，心脏形。花白色，有紫色斑点。茎、叶和种子均可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3581wx','芨','1','jī','艹','6','','[{"pinyin": "jī", "defs": [{"meaning": "堇草,即陆英 。忍冬科,灌木状草本、野生。全草治跌打损伤,故又称接骨草", "words": [{"w": "芨芨草", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3582wx','芑','1','qǐ','艹','6','','[{"pinyin": "qǐ", "defs": [{"meaning": "一种良种谷子,白芑 。也叫白粱粟。", "cites": [{"t": "芑,白苗。", "b": "《尔雅》"}, {"t": "芑,白苗嘉谷也。", "b": "《说文》"}, {"t": "维糜维芑。", "b": "《诗·大雅·生民》"}]}, {"meaning": "有机化合物环己间二烯的简称 。分子式 C6H8。"}, {"meaning": "野菜之一种,味苦。"}, {"meaning": "木名,枸杞。", "cites": [{"t": "其下多荆芑。", "b": "《山海经·东山经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3583wx','芎','1','xiōng','艹','6','','[{"pinyin": "xiōng", "defs": [{"meaning": "多年生草本植物，羽状复叶，白色，果实椭圆形。产于中国四川和云南省。全草有香气，地下茎可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3584wx','芗','1','xiāng','艹','6','','[{"pinyin": "xiāng", "defs": [{"meaning": "谷香。", "cites": [{"t": "芗,谷气也。", "b": "《说文新附》"}, {"t": "黍曰芗合,粱曰芗萁。", "b": "《礼记·曲礼下》"}, {"t": "炷芗于手项以送公葬者凡百余人。", "b": "《司马温公神道碑》"}]}, {"meaning": "用以调味的香草。", "cites": [{"t": "雏烧,雉,芗无蓼。", "b": "《礼记》。郑玄注:“苏荏之属也。”"}], "words": [{"w": "芗脯", "t": "把猪羊放在小鼎中烹煮,使它香美。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3585wx','亘','1','gèn','二','6','','[{"pinyin": "gèn", "defs": [{"meaning": "连绵不断,伸展开去。", "cites": [{"t": "亘,通也。", "b": "《广韵》"}, {"t": "旌旗亘千里。", "b": "《北史·隨本纪》"}, {"t": "广数十亩,楼宇连亘。", "b": "《聊斋志异·狐嫁女》"}, {"t": "其水之大,倍石渠三之一,亘石为底,达于两涯", "b": "唐·柳宗元《石涧记》"}], "words": [{"w": "连亘", "t": "绵连"}, {"w": "亘带", "t": "绵延"}, {"w": "亘绝", "t": "绵延阻绝。"}]}, {"meaning": "横贯;在空间横过或伸过去。", "cites": [{"t": "这亘古未有的壮举,像一柄锋利的匕首,直刺不共戴天的死敌。", "b": "《刑场上的婚礼》"}, {"t": "看桥亘长虹。", "b": "清·沈暭旦《摸鱼子》"}], "words": [{"w": "亘屏", "t": "横亘的屏障"}, {"w": "亘舒", "t": "横空舒展"}, {"w": "亘隔", "t": "横亘阻隔。"}]}, {"meaning": "穷尽,终;贯串。", "cites": [{"t": "亘万古犹一日。", "b": "明·黄宝《贾谊新书序》"}], "words": [{"w": "亘天", "t": "漫天;连天"}, {"w": "亘地", "t": "遍地"}, {"w": "亘年", "t": "历年"}, {"w": "亘代", "t": "亘古。"}]}]}]','jingmo-wenyan');
