INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3588wx','戍','1','shù','戈','6','','[{"pinyin": "shù", "defs": [{"meaning": "(会意。从人持戈。甲骨文字形,象人负戈守卫边疆。本义:防守边疆)。"}, {"meaning": "同本义。", "cites": [{"t": "戍,守边也。", "b": "《说文》。按,伐者左人右戈,人持戈也。戍者,下人上戈,人何戈也。"}, {"t": "武王立重泉之戍。", "b": "《管子·地数》"}, {"t": "彼其之子,不与我戍申。", "b": "《诗·王风·扬之水》"}, {"t": "二世元年七月,发闾左适戍渔阳。", "b": "《史记·陈涉世家》"}], "words": [{"w": "戍人", "t": "古代守边军士的通称"}, {"w": "戍守", "t": "守卫"}, {"w": "戍客", "t": "离开家乡戍守边境的人"}, {"w": "戍逻", "t": "守边巡逻"}, {"w": "戍役", "t": "戍边的军士"}, {"w": "戍将", "t": "戍守边境的将领。"}]}, {"meaning": "驻守。", "cites": [{"t": "三男邺城戍。", "b": "杜甫《石壕吏》"}, {"t": "僵卧孤村不自哀,尚思为国戍轮台。", "b": "宋·陆游《十一月四日风雨大作》"}], "words": [{"w": "戍鼓", "t": "驻边军士所击的鼓声"}, {"w": "戍主", "t": "古代驻守一地的长官"}, {"w": "戍堡", "t": "边防驻军的营垒、城堡"}, {"w": "戍御", "t": "防守御敌。"}]}, {"meaning": "守边的士兵。", "cites": [{"t": "乃归诸侯之戍。", "b": "《左传·定公元年》"}], "words": [{"w": "戍傜", "t": "兵役及劳役"}, {"w": "戍屋", "t": "戍卒屋舍"}, {"w": "戍妇", "t": "戍卒的妻子"}, {"w": "戍歌", "t": "戍卒唱的歌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
