INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3592wx','曳','1','yè','曰','6','','[{"pinyin": "yè", "defs": [{"meaning": "(会意。从申,从丿,丿(yì)亦声。申,伸展。本义:拖,牵引)。"}, {"meaning": "同本义。", "cites": [{"t": "曳,臾曳也。", "b": "《说文》。臾曳:束缚捽摔之意。"}, {"t": "车轮曳踵。", "b": "《礼记·曲礼》"}, {"t": "武举前曳踵。", "b": "《仪礼·士相见礼》。注:“古文作抽。”"}, {"t": "曳彗星之皓旰兮。", "b": "《楚辞·怨思》。注:“引也。”"}, {"t": "曳笏却立。", "b": "唐·柳宗元《柳河东集》"}, {"t": "负箧曳屣。", "b": "明·宋濂《送东阳马生序》"}, {"t": "曳屋许许声。(曳屋,指众人把被火烧着的房子拉倒。许许声,指拉倒房子时众人一齐用力的呼哧声。)", "b": "《虞初新志·秋声诗自序》"}], "words": [{"w": "弃甲曳兵;曳尾泥涂", "t": "比喻污秽卑鄙的行为"}, {"w": "曳步", "t": "脚步轻缓挪移"}, {"w": "曳脚慢坡(斜坡):曳布拖麻(曳布披麻披麻带孝", "t": ""}, {"w": "曳开", "t": "迈开;拉开"}, {"w": "曳兵弃甲", "t": "拖着兵器,丢掉铠甲。形容打败仗逃跑时的狼狈相。"}]}, {"meaning": "穿着。", "cites": [{"t": "子有衣裳,弗曳弗娄。", "b": "《诗·唐风》。孔颖达疏:“娄、曳俱是著衣之事。”"}, {"t": "骄侈不循法度,伎妾数百,曳罗纨,甘粱肉,放于声乐以自娱。", "b": "《新唐书》"}], "words": [{"w": "曳缟", "t": "穿白绢衣服"}, {"w": "曳娄", "t": "穿戴。"}]}, {"meaning": "率领。", "cites": [{"t": "孙子命章子曳兵与燕兵对阵。", "b": "《乐毅图齐平话》"}]}, {"meaning": "困顿,精力衰竭。", "cites": [{"t": "贫而不衰, 贱而不恨, 年虽疲曳, 犹庶几名贤之风。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
