('3597wx','钇','1','yǐ','钅','6','','[{"pinyin": "yǐ", "defs": [{"meaning": "一种三价金属元素,通常包括在稀土金属中,因为它在化学上与稀土相似,且与稀土在一些矿石(如硅铍钇矿、磷钇矿、钇铌钽铁矿、黑稀金矿)中共存 ——元素符号Y。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3598wx','缶','1','fǒu','缶','6','','[{"pinyin": "fǒu", "defs": [{"meaning": "(象形。甲骨文字形,上面是“午”字,即“杵”。下面是“缶”的本体。“杵”是棒子,可用来制坯。“缶”又是秦乐器,“杵”可以敲击成曲。本义:瓦器, 圆腹小口,用以盛酒浆等)。"}, {"meaning": "盛酒浆的瓦器。大腹小口,有盖。也有铜制的。", "cites": [{"t": "缶,瓦器所以盛酒浆,秦人鼓之以节歌。象形。", "b": "《说文》"}, {"t": "盎谓之缶。", "b": "《尔雅》"}, {"t": "贰用缶。", "b": "《易·坎》"}, {"t": "以二缶钟惑。", "b": "《庄子·天地》。按,钟聚也。"}, {"t": "有孚盈缶。", "b": "《易·比》。郑注:“汲器。”"}, {"t": "坎其击缶。", "b": "《诗·陈风·宛丘》"}, {"t": "击瓮叩缶。", "b": "《史记·李斯传》"}, {"t": "五献之尊,门外缶,门内壶。", "b": "《礼记·礼器》"}]}, {"meaning": "汲水的瓦器。", "cites": [{"t": "具绠缶,备水器。", "b": "《左传·襄公九年》"}]}, {"meaning": "一种古容量单位,等于十六斗。一说三十二斗。", "cites": [{"t": "薮二有半谓之缶,缶二谓之钟。", "b": "《小尔雅》"}], "words": [{"w": "缶米", "t": "一缶的米。即十六斗米。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3599wx','氘','1','dāo','气','6','','[{"pinyin": "dāo", "defs": [{"meaning": "氢的同位素,其原子量为普通轻氢的二倍,少量的存在于天然水中,用于核反应,并在化学和生物学的研究工作中作示踪原子 ——亦称“重氢”,元素符号D。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3600wx','氖','1','nǎi','气','6','','[{"pinyin": "nǎi", "defs": [{"meaning": "一种无色无嗅的惰性气体元素,原子序数10,存在于空气中,按体积计含量约占千分之二,可由液态空气分离得到,在真空管内发出淡红色辉光,用于电灯中 ——元素符号Ne。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3601wx','牝','1','pìn','牜','6','','[{"pinyin": "pìn", "defs": [{"meaning": "(形声。从牛,匕(bǐ)声。依甲骨文,“匕”为雌性动物的标志。本义:雌性的禽兽)。"}, {"meaning": "同本义。", "cites": [{"t": "牝,畜母也。", "b": "《说文》"}, {"t": "利牝马之贞。", "b": "《易·坤》"}, {"t": "畜牝牛,吉。", "b": "《易·离》"}, {"t": "牝鸡之晨,惟家之索。", "b": "《书·牧誓》"}], "words": [{"w": "牝朝", "t": "唐人称武后当政为牝朝"}, {"w": "牝牡", "t": "雌雄两性。"}]}, {"meaning": "泛指阴性的事物。", "cites": [{"t": "谿谷为牝。", "b": "《大戴礼记·本命》"}, {"t": "肾者,牝藏也。", "b": "《素问·水热穴论》"}, {"t": "牝常以静胜牡。", "b": "《老子》"}]}, {"meaning": "锁孔。", "cites": [{"t": "键,牡;闭,牝也。", "b": "《礼记》。?"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3602wx','伎','1','jì','亻','6','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从人,支声。本义:党与,同党的人)。"}, {"meaning": "同本义。", "cites": [{"t": "伎,与也。", "b": "《说文》。段玉裁注:“《舁部》曰:‘与者,党与也。’此伎之本义也。”"}]}, {"meaning": "歌女,舞女。", "cites": [{"t": "伎女楼上,坐而择食。", "b": "《洛阳伽蓝记》卷四城西"}, {"t": "凄凉蜀故伎,来舞魏宫前。", "b": "刘禹锡《蜀先主庙》"}], "words": [{"w": "伎人", "t": "女歌舞艺人"}, {"w": "伎女", "t": "古代指女歌舞艺人。"}]}, {"meaning": "泛指歌舞表演。", "cites": [{"t": "杂伎,艺以为珩。", "b": "张衡《思玄赋》。旧注:“手仗曰伎。”"}], "words": [{"w": "伎船", "t": "以歌舞色相为业的游船"}, {"w": "伎乐", "t": "古代俳优所奏的音乐"}, {"w": "伎伎", "t": "形容奔走的样子。"}]}, {"meaning": "技艺,本领。", "cites": [{"t": "无他伎。", "b": "《书·秦誓》"}, {"t": "案谨募选阅材伎之士。", "b": "《荀子·王制》"}, {"t": "故圣人之处世,不逆有伎能之士。", "b": "《淮南子·道应》"}, {"t": "积财千万,不如薄伎在身。", "b": "《颜氏家训·勉学》"}, {"t": "卜者,世之余伎也。", "b": "唐·柳宗元《非国语上·卜》"}, {"t": "通天地而不通人曰伎。", "b": "《法言·君子》"}], "words": [{"w": "伎痒", "t": "极想施展本领;动心"}, {"w": "伎力", "t": "技能与勇力。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3603wx','伛','1','yǔ','亻','6','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从人,区声。本义:背曲) 同本义。", "cites": [{"t": "伛,曲也。", "b": "《广雅》"}, {"t": "苦水所,多尩与伛人。", "b": "《吕氏春秋·尽数》"}, {"t": "良雌伛伏,体方就成。", "b": "《论衡·论死》"}, {"t": "伛偻提携。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "伛兜面孔", "t": "指面孔凹凸不平"}, {"w": "伛伏", "t": "曲背俯伏"}, {"w": "伛步", "t": "弯腰曲身行走"}, {"w": "伛伸", "t": "驼背"}, {"w": "伛背", "t": "驼背"}, {"w": "伛伛", "t": "背曲的样子。"}]}, {"meaning": "弯腰 (表示恭敬)。", "cites": [{"t": "形容鬼看见,忙伛去将他一把拿住,思量拉他上船。", "b": "《何典》"}, {"t": "一命而偻,再命而伛,三命而俯,循墙而走。", "b": "《左传》"}]}, {"meaning": "(yù)。爱抚;抚育。", "cites": [{"t": "以下伛拊人之民。", "b": "《庄子·人间世》"}, {"t": "伛伏其子。", "b": "《新论·贪爱》"}], "words": [{"w": "伛拊", "t": "怜爱抚养"}, {"w": "伛翼", "t": "鸟以翼覆盖掩护。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3604wx','伢','1','yá','亻','6','','[{"pinyin": "yá", "defs": [{"meaning": "方言。小孩。"}, {"meaning": "小孩儿。"}, {"meaning": "小孩儿。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3605wx','佤','1','wǎ','亻','6','','[{"pinyin": "wǎ", "defs": [{"meaning": "佤族的简称 。亦称“佧瓦族”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3606wx','仵','1','wǔ','亻','6','','[{"pinyin": "wǔ", "defs": [{"meaning": "等同;匹敌。", "cites": [{"t": "以坚白同异之辩相訾,以觭偶不仵之辞相应。", "b": "《庄子·天下》"}]}, {"meaning": "违背。", "cites": [{"t": "自用则不虚,不虚则仵于物矣。", "b": "《管子》"}]}, {"meaning": "用同“捂”。用手遮盖住。", "cites": [{"t": "只在二门外仵着脸,脱脱的哭起来。", "b": "《西游记》"}]}, {"meaning": "五。", "cites": [{"t": "檀越元囿鸾施地仵拾亩。", "b": "北魏《敬史君碑》"}]}, {"meaning": "古代士兵五人为伍。", "cites": [{"t": "重振威仪,再排队仵。", "b": "《敦煌变文》"}]}, {"meaning": "仵人。亦称以代人殓葬为业的人。", "cites": [{"t": "天明就要入殓,只怕被仵作看出破绽来了。", "b": "《金瓶梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3607wx','伥','1','chāng','亻','6','','[{"pinyin": "chāng", "defs": [{"meaning": "(形声。从人,长声。本义:狂)。"}, {"meaning": "同本义。", "cites": [{"t": "伥,狂也。俗字作猖。", "b": "《说文》"}, {"t": "何桀纠之昌披兮。(以昌为之。)", "b": "《离骚》"}, {"t": "号为“伥子”。", "b": "《资治通鉴》。胡三省注:“伥,狂。”"}]}, {"meaning": "旧指为盗贼察情探路的人。也指助纣为虐的恶人。", "cites": [{"t": "其为响马贼之伥无疑。", "b": "清·酉阳《女盗侠传》"}]}, {"meaning": "无所适从。又称伥伥。", "cites": [{"t": "人无法则伥伥然。", "b": "《荀子·修身》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3608wx','伧','1','cāng chen','亻','6','','[{"pinyin": "cāng", "defs": [{"meaning": "(形声。从人,仓声。本义:粗俗) 同本义。", "cites": [{"t": "原来这子房也是个伧头。", "b": "元·尚仲贤《气英布》"}], "words": [{"w": "伧荒", "t": "人物鄙陋、未受教育,地域荒远、交通不便"}, {"w": "伧头", "t": "粗俗、鄙陋之人"}, {"w": "伧夫", "t": "粗野、鄙贱、缺乏教养的人。也作“伧父”"}, {"w": "伧重", "t": "粗重而鄙野。"}]}]}, {"pinyin": "chen", "defs": [{"meaning": "——“寒伧”,即“寒碜”:。"}, {"meaning": "丑陋;难看。"}, {"meaning": "丢脸,不体面。"}, {"meaning": "讥笑,揭人短。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3609wx','伉','1','kàng','亻','6','','[{"pinyin": "kàng", "defs": [{"meaning": "(形声。从人,亢声。本义:匹敌,相当)。"}, {"meaning": "同本义。", "cites": [{"t": "天下莫之能伉。", "b": "《战国策·秦策一》"}, {"t": "已不能庇其伉俪。", "b": "《左传·成公十一年》。注:“敌也。”"}, {"t": "弃其伉俪妃嫔。", "b": "《国语·周语》。注:“对也。”"}, {"t": "可与乎比伉。", "b": "《后汉书·张衡传》。注:“偶也。”"}], "words": [{"w": "伉合", "t": "匹敌相等而配合。"}]}, {"meaning": "对敌,抵挡。", "cites": [{"t": "养及亲者,身伉其难。", "b": "《吕氏春秋·士节》"}], "words": [{"w": "伉礼", "t": "彼此以平等的礼节相对待。同“抗礼”"}, {"w": "伉衡", "t": "势均力敌,不相上下。同“抗衡”。"}]}, {"meaning": "高大,高尚。", "cites": [{"t": "乃立皋门,皋门有伉。", "b": "《诗·大雅·緜》"}], "words": [{"w": "伉行", "t": "行为高洁;高洁的品德。"}]}, {"meaning": "刚直。", "cites": [{"t": "子路性鄙,好勇力,志伉直。", "b": "《史记·仲尼弟子列传》"}], "words": [{"w": "伉健", "t": "刚强健壮"}, {"w": "伉侠", "t": "刚直仗义"}, {"w": "伉直", "t": "刚强正直。"}]}, {"meaning": "强健。", "cites": [{"t": "先郡国吏三百石,伉健习骑射者皆从军。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "伉王", "t": "英明勇健的君王"}, {"w": "伉壮", "t": "健壮。"}]}, {"meaning": "骄傲。", "cites": [{"t": "太子轻而庶子伉。", "b": "《韩非子·亡征》"}], "words": [{"w": "伉厉", "t": "高傲严厉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3610wx','伫','1','zhù','亻','6','','[{"pinyin": "zhù", "defs": [{"meaning": "(会意。从人,从宁(zhù)。宁,堆积物。人在堆积物旁。本义:久立)。"}, {"meaning": "同本义。", "cites": [{"t": "悔相道之不察兮,延伫乎吾将反。", "b": "《楚辞·离骚》"}, {"t": "伫盘桓而且俟。", "b": "班固《幽通赋》"}, {"t": "玉阶空伫立,宿鸟归飞急。", "b": "唐·李白《菩萨蛮》"}], "words": [{"w": "伫见", "t": "久立视看"}, {"w": "伫眙", "t": "久立注视"}, {"w": "伫轴", "t": "久立盼望而辗转思念"}, {"w": "伫盼", "t": "久立远望"}, {"w": "伫望", "t": "久立而远望。"}]}, {"meaning": "企盼;等待。", "cites": [{"t": "梦寐伫归舟,释我吝与劳。", "b": "南朝宋·谢灵运《酬从弟惠连》"}], "words": [{"w": "虚伫", "t": "虚心等待"}, {"w": "伫迟", "t": "企望;等待"}, {"w": "伫望", "t": "等候,盼望。"}]}, {"meaning": "停止,停留。", "cites": [{"t": "临津不得济,伫楫阻风波。", "b": "《文选·谢惠连·西陵遇风献康乐》"}], "words": [{"w": "伫足", "t": "止步"}, {"w": "伫思", "t": "凝思"}, {"w": "伫听", "t": "凝神倾听。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3611wx','囟','1','xìn','囗','6','','[{"pinyin": "xìn", "defs": [{"meaning": "(象形。或从肉,宰声。本义:连合胎儿或新生儿颅顶盖各骨间的膜质部) 同本义。", "cites": [{"t": "夹囟曰角。", "b": "《礼记·内则》注"}], "words": [{"w": "囟门口", "t": "囱门。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3612wx','汆','1','cuān','水','6','','[{"pinyin": "cuān", "defs": [{"meaning": "引申为把东西丢到水里或人钻入水中。", "cites": [{"t": "所以才几天就搁下来了,眼睁睁汆了它妈一大堆钱进去。", "b": "沙汀《淘金记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3613wx','刖','1','yuè','刂','6','','[{"pinyin": "yuè", "defs": [{"meaning": "(形声。从刀,月声。本义:断足。古代的一种酷刑) 同本义。", "cites": [{"t": "刖,绝也。", "b": "《说文》"}, {"t": "刖,断也。", "b": "《广雅》。假借为“蚏”"}, {"t": "蚏,断足之刑也。", "b": "《说文》"}, {"t": "刖五百。", "b": "《周礼·司刑》。注:“断足也。周改髌作刖。”"}, {"t": "刖强鉏。", "b": "《左传·庄公十六年》"}, {"t": "昔卞和献宝,楚王刖之。", "b": "《史记》"}], "words": [{"w": "刖足", "t": "古代一种酷刑,砍掉脚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3614wx','夙','1','sù','夕','6','','[{"pinyin": "sù", "defs": [{"meaning": "(会意。夕是夜间,丮(jí)表示以手持物。天不亮就起来做事情,表示早。所以除了早晨的意义外,还有早起劳作,以示恭敬的意思。本义:早晨)。"}, {"meaning": "同本义。", "cites": [{"t": "夙,早敬也。", "b": "《说文》"}, {"t": "夙夜在公。", "b": "《诗·召南·小星》"}, {"t": "岂不夙夜,谓行多露。", "b": "《诗·召南·行露》"}, {"t": "夙夜惟寅。", "b": "《书·舜典》"}, {"t": "夙兴。", "b": "《仪礼·士昏礼》"}, {"t": "策蹇驴,囊图书,夙行失道,望尘惊悸。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "夙兴", "t": "早起"}, {"w": "夙宵", "t": "朝夕,日夜。"}]}, {"meaning": "旧;平素。", "cites": [{"t": "虞虽为上公,天性节约,…远近豪俊,夙僭奢者,莫不改,而归心焉。", "b": "《后汉书·刘虞传》"}, {"t": "良觌违夙愿,含凄向寥廓。", "b": "唐·杜甫《昔游》"}], "words": [{"w": "夙话", "t": "老话;旧话"}, {"w": "夙好", "t": "老交情"}, {"w": "夙契", "t": "老朋友"}, {"w": "夙憾", "t": "旧恨;旧怨"}, {"w": "夙觏", "t": "旧友。觏:老朋友"}, {"w": "夙分", "t": "旧缘,往世的缘分"}, {"w": "夙素", "t": "平日的心愿"}, {"w": "夙心", "t": "平素的心愿"}, {"w": "夙志", "t": "平素的志愿"}, {"w": "夙尚", "t": "平素的志愿或心愿。"}]}, {"meaning": "前,早年。", "cites": [{"t": "乩仙批了,死者冯渊与薛蟠原系夙孽,今狭路相遇,原因了结。", "b": "《红楼梦》"}, {"t": "仗策相从似夙因,草堂促膝意相亲。", "b": "清·黄景仁《夜宿西山下偕冯九健一》"}], "words": [{"w": "夙世", "t": "前生,前世"}, {"w": "夙根", "t": "佛家称前世的修行根底"}, {"w": "夙世之因", "t": "前世的缘分。"}]}, {"meaning": "早。", "cites": [{"t": "大夫夙退,无使君劳。", "b": "《诗·卫风·硕人》"}, {"t": "痛灵根之夙损,怨具尔之多丧。", "b": "晋·陆机《以逝赋》"}], "words": [{"w": "夙殒", "t": "早谢,早死"}, {"w": "夙办", "t": "及早办理"}, {"w": "夙就", "t": "早成;早熟。"}]}, {"meaning": "肃敬。", "cites": [{"t": "履帝武敏歆,攸介攸止,载震载夙,载生载育,时维后稷。", "b": "《诗·大雅·生民》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3615wx','旮','1','gā','日','6','','[{"pinyin": "gā", "defs": [{"meaning": "角落墙～旯子。屋～旯儿。"}, {"meaning": "偏僻的地方岩～旯子～旯儿。"}, {"meaning": "角落。偏僻狭窄的地方。", "cites": [{"t": "解扣松裙，在炕旮旯里换上。--《儿女英雄传》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3616wx','刎','1','wěn','刂','6','','[{"pinyin": "wěn", "defs": [{"meaning": "(形声。从刀,勿声。本义:割脖子)。"}, {"meaning": "同本义。", "cites": [{"t": "刎,刭也。", "b": "《说文新附》"}, {"t": "卒相与欢,为刎颈之交。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "种霸越而灭吴兮,终刎颈于属镂。", "b": "刘基《述志赋》"}], "words": [{"w": "自刎", "t": "割颈部自杀"}, {"w": "刎脰", "t": "刎颈。割脖子,自杀。"}]}, {"meaning": "割断。", "cites": [{"t": "刎,断也。", "b": "《博雅》"}, {"t": "刎,亡粉切,割也。", "b": "《玉篇》"}, {"t": "马前不得进,后不得退,遂避而逸,因下抽刀而刎其脚。", "b": "《韩非子·外储说右下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3617wx','犷','1','guǎng','犭','6','','[{"pinyin": "guǎng", "defs": [{"meaning": "(形声。从犬,广声。本义:犬凶恶,凶猛)。"}, {"meaning": "同本义。", "cites": [{"t": "犷,犬犷犷不可附也。", "b": "《说文》"}, {"t": "犷彼淮夷。", "b": "《韩诗·泮水》"}, {"t": "犷犷亡秦。", "b": "《汉书》"}, {"t": "犷,猛也。", "b": "《后汉书·光武纪》注"}, {"t": "犷,恶也。", "b": "《汉书·段颎传》注"}], "words": [{"w": "犷兽", "t": "凶猛的野兽"}, {"w": "犷狉", "t": "凶猛野蛮"}, {"w": "犷恶", "t": "凶猛,凶恶"}, {"w": "犷戾", "t": "凶暴而乖张"}, {"w": "犷狠", "t": "横暴凶狠"}, {"w": "犷暴", "t": "凶暴"}, {"w": "犷犷", "t": "凶暴;凶恶。"}]}, {"meaning": "粗野。", "cites": [{"t": "且临守偏海,政移犷俗。", "b": "《后汉书·祭肜传》"}], "words": [{"w": "犷语", "t": "粗野的语言"}, {"w": "犷卤", "t": "粗野愚钝"}, {"w": "犷顽", "t": "粗野不驯"}, {"w": "犷锐", "t": "粗野好斗。"}]}, {"meaning": "强悍,强壮凶悍。", "cites": [{"t": "年十五,犷悍无赖,犯法当死,变姓柳,之盱眙市中为人说书。", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "犷野", "t": "强悍野蛮"}, {"w": "犷横", "t": "凶悍蛮横"}, {"w": "犷俗", "t": "犷悍的习俗"}, {"w": "犷敌", "t": "强敌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3618wx','犸','1','mǎ','犭','6','','[{"pinyin": "mǎ", "defs": [{"meaning": "——“猛犸”(měngmǎ):一种古脊椎动物,像现代的象,全身有长毛,已绝种。也叫“毛象”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3619wx','舛','1','chuǎn','夕','6','','[{"pinyin": "chuǎn", "defs": [{"meaning": "(会意。小篆字形,是两只方向相反的脚,合起来表示相违背的意思。本义:相违背,颠倒)。"}, {"meaning": "同本义。", "cites": [{"t": "舛,对卧也。", "b": "《说文》段注:“谓人与人相对而休也,相背,犹相对也。”"}, {"t": "本末舛逆。", "b": "贾谊《治安策》"}, {"t": "雄见诸子,各以其知舛驰。", "b": "《汉书·扬雄传》"}], "words": [{"w": "舛驰", "t": "异道而驰;交互"}, {"w": "舛令", "t": "违命"}, {"w": "舛午", "t": "抵触;违背。"}]}, {"meaning": "错乱。", "cites": [{"t": "此臣所谓舛也。", "b": "《汉书·贾谊传》"}], "words": [{"w": "舛讹", "t": "差错;错误"}, {"w": "舛差", "t": "差误;差错"}, {"w": "舛误", "t": "差错;错误。"}]}, {"meaning": "不幸。", "cites": [{"t": "时运不齐,命途多舛。", "b": "王勃《滕王阁序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3620wx','凫','1','fú','几','6','','[{"pinyin": "fú", "defs": [{"meaning": "动物名。俗名野鸭 。鸟纲,雁鸭目,雁鸭科。体长60余厘米,喙宽而扁平且短,除繁殖期外,都过群集生活。", "cites": [{"t": "凫,水鸭也。", "b": "《广韵》"}]}, {"meaning": "另一说凫是“家鸭”。", "words": [{"w": "凫雏", "t": "幼凫"}, {"w": "凫雁", "t": "野鸭与大雁"}, {"w": "凫胫", "t": "野鸭的小腿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3621wx','邬','1','wū','阝','6','','[{"pinyin": "wū", "defs": [{"meaning": "古地名。"}, {"meaning": "春秋郑邑,后入周。在今河南省偃师县西南。"}, {"meaning": "春秋晋地,在今山西省介休县东北。", "cites": [{"t": "司马弥牟为邬大夫。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3622wx','饧','1','xíng','饣','6','','[{"pinyin": "xíng", "defs": [{"meaning": "用麦芽或谷芽熬成的饴糖。", "cites": [{"t": "泼火雨初晴。草色青青。傍檐垂柳卖春饧。", "b": "宋·李彭老《浪淘沙》"}, {"t": "湖鱼香胜肉,官酒重于饧。", "b": "唐·刘禹锡《历阳书事》"}], "words": [{"w": "饧糟", "t": "熬麦芽糖剩下的渣子"}, {"w": "饧饼", "t": "一种糖饼"}, {"w": "饧粥", "t": "甜粥"}, {"w": "饧蜜", "t": "糖蜜"}, {"w": "饧糖", "t": "麦芽糖"}, {"w": "饧桃", "t": "甜桃。"}]}, {"meaning": "形容眼色朦胧。", "cites": [{"t": "八戒饧眼偷看,你道他怎生打扮。", "b": "《西游记》"}, {"t": "只觉口齿缠绵,眉眼愈加饧涩,忙伏侍他睡下。", "b": "《红楼梦》"}], "words": [{"w": "饧涩", "t": "精神涣散,眼色朦胧"}, {"w": "饧眼", "t": "脒着眼睛,朦胧而视。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3623wx','汕','1','shàn','氵','6','','[{"pinyin": "shàn", "defs": [{"meaning": "鱼游水。", "cites": [{"t": "汕,鱼游水貌。从水,山声。", "b": "《说文》"}, {"t": "南有嘉鱼,烝然汕汕。", "b": "《诗·小雅·南有嘉鱼》"}], "words": [{"w": "汕汕", "t": "鱼游水的样子。"}]}, {"meaning": "骗人,诱人上当。", "cites": [{"t": "作成圈套儿来汕你的。", "b": "《儿女英雄传》"}]}, {"meaning": "鱼梁 ,用木桩、柴枝或编网等制成篱笆或栅栏,置于河流、潮水中或出海口处用以捕鱼。", "cites": [{"t": "罳谓之汕。", "b": "《尔雅·释器》"}]}, {"meaning": "汕头的简称,在广东省东部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3624wx','汔','1','qì','氵','6','','[{"pinyin": "qì", "defs": [{"meaning": "水干涸。", "cites": [{"t": "汔,水涸也。", "b": "《说文》"}, {"t": "汔渊剖珠,倾岩刊玉。", "b": "晋·葛洪《抱朴子》"}]}, {"meaning": "尽;完成。", "cites": [{"t": "汔,尽也。", "b": "《广雅》"}, {"t": "壮狡汔尽穷屈。", "b": "《吕氏春秋·听言》"}, {"t": "汔尽(竭尽);汔事(完事)", "b": ""}]}, {"meaning": "几乎,差不多。", "cites": [{"t": "民亦劳止,汔可小康。", "b": "《诗·大雅·民劳》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3625wx','汐','1','xī','氵','6','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从水,夕声。本义:晚潮)。"}, {"meaning": "同本义。", "cites": [{"t": "潮汐去还,谁所节度?", "b": "北齐·颜之推《颜氏家训》"}, {"t": "会夏旱水涸沙涨,有汐无潮。", "b": "清·魏源《圣武记》"}], "words": [{"w": "汐潮", "t": "白天涨落的叫潮,晚上涨落的叫汐。"}]}, {"meaning": "水名 。在河南省登封县。", "cites": [{"t": "汐,水名,出阳城山。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3626wx','汲','1','jí','氵','6','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。从水,及声。本义:从井里打水,取水)。"}, {"meaning": "同本义。", "cites": [{"t": "汲,引水于井也。", "b": "《说文》"}, {"t": "汲,取也。", "b": "《广雅》"}, {"t": "可用汲。", "b": "《易·井》"}, {"t": "而出溉汲。", "b": "《吕氏春秋·慎行论》"}, {"t": "而谷汲者。", "b": "《韩非子·五蠹》"}, {"t": "每汲用。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "有泉可汲。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "汲古", "t": "钻研古书,如汲水于井"}, {"w": "汲水", "t": "引水;取水。"}]}, {"meaning": "牵引。", "cites": [{"t": "凡任,索约,大汲其版,谓之无任。", "b": "《周礼·考工记·匠人》"}]}, {"meaning": "引导。", "cites": [{"t": "汲郑伯。", "b": "《谷梁传·襄公十年》"}], "words": [{"w": "汲善", "t": "引人向善。"}]}, {"meaning": "用同“急”。急剧。", "cites": [{"t": "不汲汲于富贵。", "b": "《汉书·扬雄传》"}], "words": [{"w": "汲汲忙忙", "t": "十分急迫繁忙"}, {"w": "汲汲营营", "t": "急迫追求的样子。"}]}, {"meaning": "中国县名 。在河南省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3627wx','汜','1','sì','氵','6','','[{"pinyin": "sì", "defs": [{"meaning": "由干流分出又汇合到干流的水。", "cites": [{"t": "汜,水别复入水也。从水,巳声。", "b": "《说文》"}, {"t": "江有汜,之子归,不我以。", "b": "《诗·召南·江有汜》"}]}, {"meaning": "不流通的水沟。", "cites": [{"t": "穷渎,汜。", "b": "《尔雅·释丘》。郭璞注:“水无所通者。”"}]}, {"meaning": "水名 。源出河南省方山,在荥阳县境注入黄河。", "cites": [{"t": "汜水,源出方山。", "b": "《读史方舆纪要》"}]}, {"meaning": "水边。", "cites": [{"t": "出自汤谷,次于蒙汜。", "b": "《楚辞》"}]}]}]','jingmo-wenyan');
