INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3629wx','忖','1','cǔn','忄','6','','[{"pinyin": "cǔn", "defs": [{"meaning": "(形声。从心,寸声。本义:思量,揣度)。"}, {"meaning": "同本义。", "cites": [{"t": "忖,测度也。", "b": "《珠丛》"}, {"t": "予忖度之。", "b": "《诗·小雅·巧言》"}], "words": [{"w": "忖思", "t": "思量"}, {"w": "忖势", "t": "分析研究,衡量情势"}, {"w": "忖夺", "t": "犹忖度。"}]}, {"meaning": "除。", "cites": [{"t": "故以成之数忖该之积如法为一寸,则黄钟之长也。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
