('3630wx','忏','1','chàn','忄','6','','[{"pinyin": "chàn", "defs": [{"meaning": "(形声。从心,懺(xiān)声。本义:忏悔,自陈懊悔) 同本义。", "cites": [{"t": "[法]佐愕然愧忏。", "b": "《晋书·佛图澄传》"}], "words": [{"w": "忏礼", "t": "忏悔礼拜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3631wx','讴','1','ōu','讠','6','','[{"pinyin": "ōu", "defs": [{"meaning": "(形声。从言,区(ōu)声。本义:无伴奏;齐声歌唱)。"}, {"meaning": "同本义。", "cites": [{"t": "讴,齐歌也。", "b": "《说文》"}, {"t": "齐讴楚声。", "b": "曹植诗"}, {"t": "皆讴歌思东归。", "b": "《楚辞·大招》"}, {"t": "筑者讴曰:“泽门之皙,实兴我役。”", "b": "《左传·襄公十七年》"}, {"t": "薛谭学讴于秦青。", "b": "《列子·汤问》"}, {"t": "昔日王豹处于淇,而河西善讴", "b": "《孟子·告子下》"}, {"t": "故近者歌讴而乐之。", "b": "《荀子·议兵》"}], "words": [{"w": "讴者", "t": "讴歌的人"}, {"w": "讴咏", "t": "讴歌吟咏"}, {"w": "讴诵", "t": "歌讼"}, {"w": "讴谣", "t": "唱歌區。"}]}, {"meaning": "歌颂;赞颂。", "cites": [{"t": "民讴思之。", "b": "《苗防备览·李瑜》"}]}, {"meaning": "歌曲。", "cites": [{"t": "京洛出名讴。", "b": "曹植《箜篌引》"}, {"t": "于是有赵代之讴。", "b": "《汉书·艺文志》"}], "words": [{"w": "讴谣", "t": "歌谣"}, {"w": "吴讴;越讴;采莲讴", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3632wx','讵','1','jù','讠','6','','[{"pinyin": "jù", "defs": [{"meaning": "曾。", "cites": [{"t": "尔祭讵几时,朔望忽复尽。", "b": "晋·潘岳《悼亡诗》"}]}, {"meaning": "如果。", "cites": [{"t": "讵非圣人必偏而后可。", "b": "《国语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3633wx','祁','1','qí','礻','6','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从邑,示声。右耳旁是“邑”的变形。从邑的字往往与区域有关。本义:地名)。"}, {"meaning": "县名。", "cites": [{"t": "太原县。", "b": "《说文》。为今山西省祁县"}, {"t": "分祁氏之田,以为七县。", "b": "《左传》"}]}, {"meaning": "安徽省祁门县的简称。"}, {"meaning": "湖南省祁阳县的简称。"}, {"meaning": "大。", "cites": [{"t": "其祁孔有。", "b": "《诗·小雅·吉日》"}, {"t": "资冬祁寒。", "b": "《礼记·缁衣》"}], "words": [{"w": "祁寒", "t": "严寒"}, {"w": "祁哀", "t": "大哀。"}]}, {"meaning": "众多的样子。", "cites": [{"t": "春日迟迟,采蘩祁祁。", "b": "《诗·豳风·七月》"}], "words": [{"w": "祁祁", "t": "众多的样子;舒缓的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3634wx','讷','1','nè','讠','6','','[{"pinyin": "nè", "defs": [{"meaning": "(会意。从言,从内。表示有话在肚里,难以说出来。本义:语言迟钝) 同本义。也作“呐”。", "cites": [{"t": "讷,言难也。", "b": "《说文》。按,当为呐之或体。"}, {"t": "论物明辨谓之辩,反辩为讷。", "b": "《贾子道术》"}, {"t": "君子欲讷于言而敏于行。", "b": "《论语·里仁》"}, {"t": "广讷口少言。", "b": "《史记·李将军列传》"}], "words": [{"w": "讷口", "t": "言语迟钝;口齿笨拙"}, {"w": "讷涩", "t": "言语艰难笨拙"}, {"w": "讷直", "t": "言语迟钝,品格正直"}, {"w": "讷钝", "t": "言语迟钝"}, {"w": "讷言", "t": "言谈迟钝。"}]}, {"meaning": "结结巴巴地说。", "cites": [{"t": "只听得差拨口里讷出一句“高太尉”三个字来。", "b": "《水浒全传》"}]}, {"meaning": "忍而少言。", "cites": [{"t": "能威能怀,能辨能讷。", "b": "三国魏·刘劭《人物志·体别》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3635wx','聿','1','yù','聿','6','','[{"pinyin": "yù", "defs": [{"meaning": "(指事。从聿一一者,牍也。秦以后皆作筆。本义:毛笔。笔的本字,秦以后始加竹作笔)同本义。", "cites": [{"t": "聿,所以书也。楚谓之聿,吴谓之不律,燕谓之弗。", "b": "《说文》"}], "words": [{"w": "舌聿", "t": "即“口笔”。用口所说的,用笔所写的。"}]}, {"meaning": "古汉语助词,用在句首或句中。", "cites": [{"t": "无念尔祖,聿修厥德。", "b": "《诗·大雅·文王》"}, {"t": "聿,循也。", "b": "《后汉书·傅毅传》注"}], "words": [{"w": "聿女", "t": "养女"}, {"w": "聿遵", "t": "遵循。聿,发语词"}, {"w": "聿追", "t": "聿本助词。后人往往训聿为述,因以“聿追”谓追述先人德业。"}]}, {"meaning": "轻快。", "cites": [{"t": "武骑聿皇。", "b": "《汉书·扬雄传上》"}], "words": [{"w": "聿皇", "t": "轻快的样子"}, {"w": "聿役", "t": "动的样子"}, {"w": "聿越", "t": "迅速地跨越。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3636wx','艮','1','gěn gèn','艮','6','','[{"pinyin": "gěn", "defs": [{"meaning": "指食物不易咬动或嚼烂"}, {"meaning": "[方言] [人]坦率直言"}, {"meaning": "[方言] 言语率直无曲折"}, {"meaning": "[衣服] 朴素"}, {"meaning": "不松脆", "words": [{"w": "艮萝卜", "t": ""}]}]}, {"pinyin": "gèn", "defs": [{"meaning": "止;静止。", "cites": [{"t": "泉可艮,九天之上,九天之下,何所不艮?", "b": "清·恽敬《艮泉图咏记》"}]}, {"meaning": "坚固;坚硬。", "cites": [{"t": "艮,坚也。", "b": "《广雅》"}]}, {"meaning": "艰难。", "cites": [{"t": "象艮有守。", "b": "《太玄·守》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3637wx','厾','1','dū','厶','6','','[{"pinyin": "dū", "defs": [{"meaning": "表示人称代词的多数。犹“们”。", "cites": [{"t": "你厾两个老人家。", "b": "《缀白裘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3638wx','阱','1','jǐng','阝','6','','[{"pinyin": "jǐng", "defs": [{"meaning": "(形声。从阜(fù),表示与地形地势的高低上下有关,井声。本义:陷阱,为捕捉野兽的坑)。"}, {"meaning": "同本义。", "cites": [{"t": "阱,陷也。", "b": "《说文》"}, {"t": "使入陷阱。", "b": "《汉书·食货志下》。师古曰:“阱,穿地以陷兽也。”"}, {"t": "春令为阱获沟渎之利于民者。", "b": "《周礼·雍氏》"}, {"t": "罟获陷阱。", "b": "《礼记·中庸》"}, {"t": "猛虎落陷阱。", "b": "李白《君马黄》"}], "words": [{"w": "猛虎落阱;阱鄂", "t": "捕野兽的陷坑和笼子"}, {"w": "阱机", "t": "本指捕捉动物的陷阱。喻指陷害别人的计谋。"}]}, {"meaning": "设陷阱捕兽。", "cites": [{"t": "釜兵阱兽,固不久就毙。", "b": "《明清史资料丙编》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3639wx','阮','1','ruǎn','阝','6','','[{"pinyin": "ruǎn", "defs": [{"meaning": "(形声。从阜(fù),元声。本义:五阮关)。"}, {"meaning": "同本义。", "cites": [{"t": "阮,代郡五阮关也。", "b": "《说文》。按,亦曰五原关"}, {"t": "流民欲入五阮关者,勿苟留。", "b": "《汉书·成帝纪》"}, {"t": "秦九原郡,武帝元朔二年更名。", "b": "《地理志·五原郡》注"}]}, {"meaning": "殷商国名 。在今甘肃省泾川县,为周文王所灭。", "cites": [{"t": "阮,国名。今陕西平凉府泾州是也。", "b": "《字汇》"}, {"t": "侵阮徂共。", "b": "《诗·大雅·皇矣》"}, {"t": "侵自阮疆。", "b": ""}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3640wx','阪','1','bǎn','阝','6','','[{"pinyin": "bǎn", "defs": [{"meaning": "(形声,从阜,反声。本义:山坡)。"}, {"meaning": "同本义。", "cites": [{"t": "阪,坡者曰阪。一曰泽障,一曰山胁。从阜,反声。字亦作坂。", "b": "《说文》"}, {"t": "阪有桑。", "b": "《诗·秦风 ·车邻》"}, {"t": "瞻彼阪田。", "b": "《诗·小雅·正月》"}, {"t": "阪险原隰。", "b": "《吕氏春秋·孟春》。注:“阪险,倾危也。”"}, {"t": "为阪生。", "b": "《易·说卦虞本》。注:“陵阪也。”"}, {"t": "阪尹。", "b": "《书·立政》。郑注:“其长居险,故言阪尹。”"}], "words": [{"w": "阪田", "t": "山坡上瘠薄的田地。"}]}, {"meaning": "山腰小道。", "cites": [{"t": "朝辞羊肠阪,夕望贝丘郭。", "b": "唐·刘长卿《奉和李大夫同吕评事太行苦热行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3641wx','丞','1','chéng','一','6','','[{"pinyin": "chéng", "defs": [{"meaning": "(会意。甲骨文字形,上面象两只手,下面象人掉在陷阱里,合起来表示救人于陷阱之中。(zhěng)本义:拯救)。"}, {"meaning": "接受、秉承。", "cites": [{"t": "前疑后丞。", "b": "《孝经·谏诤章》注"}, {"t": "于是丞上指,请造白金及五铢钱。", "b": "《史记·酷吏列传》"}]}, {"meaning": "古官名。"}, {"meaning": "传说为帝王的四辅之一,是辅佐帝王的最高官吏。"}, {"meaning": "佐官名。秦始置。汉以后,中央和地方官吏的副职有大理丞、府丞、县丞等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3642wx','妁','1','shuò','女','6','','[{"pinyin": "shuò", "defs": [{"meaning": "媒人。", "cites": [{"t": "妁,媒也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3643wx','牟','1','móu mù','牛','6','','[{"pinyin": "móu", "defs": [{"meaning": "(会意。小篆字形。从牛,从厶。厶象气从口出。本义:牛叫声)。"}, {"meaning": "同本义。", "cites": [{"t": "牟,牛鸣也。", "b": "《说文》"}, {"t": "牟然而鸣。", "b": "柳宗元《牛赋》"}], "words": [{"w": "野牛牟牟地叫", "t": ""}]}, {"meaning": "力求得到;目的在于。", "cites": [{"t": "游居厚养,牟食之民也。", "b": "《韩非子》"}], "words": [{"w": "牟利", "t": ""}]}, {"meaning": "等同。", "cites": [{"t": "德牟往初,功无与二。", "b": "《汉书·司马相如传·封禅书》"}]}, {"meaning": "大麦。", "cites": [{"t": "贻(送)我来(小麦)牟。", "b": "《诗·周颂·思文》"}]}, {"meaning": "瞳人。", "cites": [{"t": "尧、舜参牟子。", "b": "《荀子·非相》"}]}, {"meaning": "假借为“眉”。眉毛,眉寿。", "cites": [{"t": "天与厥福,永享牟寿。", "b": "《鲁相韩勅造孔庙礼器碑》"}]}, {"meaning": "釜属瓦器皿。", "cites": [{"t": "敦、牟、巵、匜。", "b": "《礼记·内则》"}]}, {"meaning": "大麦。", "cites": [{"t": "贻我来牟,帝命率育。", "b": "《诗·周颂·思文》"}]}, {"meaning": "岑牟,古代鼓角吏所戴的帽子。", "cites": [{"t": "更著岑牟单绞之服。", "b": "《后汉书·祢衡传》"}]}, {"meaning": "姓。"}]}, {"pinyin": "mù", "defs": [{"meaning": "——“牟平”(Mùpíng):县名。今在山东省东部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3644wx','纡','1','yū','纟','6','','[{"pinyin": "yū", "defs": [{"meaning": "(形声。从糸(mì),于声。本义:屈曲;曲折)。"}, {"meaning": "同本义。", "cites": [{"t": "纡,绌也,一曰萦也。", "b": "《说文》"}, {"t": "中弱则纡。", "b": "《考工记·矢人》。注:“曲也。”"}, {"t": "连行纡行。", "b": "《周礼·梓人》"}, {"t": "盘纡刻俨。", "b": "《淮南子·本经》"}, {"t": "水澹澹而盘纡兮。", "b": "宋玉《高唐赋》"}, {"t": "中弱则纡,中强则扬。", "b": "《周礼》"}], "words": [{"w": "纡远", "t": "曲折遥远"}, {"w": "纡曲", "t": "迂回曲折"}, {"w": "纡折", "t": "迂回曲折"}, {"w": "纡余", "t": "迂回曲折"}, {"w": "纡行", "t": "曲折而行。"}]}, {"meaning": "萦绕回旋。", "cites": [{"t": "水澹澹而盘纡兮,洪波淫淫之溶旐。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "纡回", "t": "屈曲回旋。也作“迂回”"}, {"w": "纡轸", "t": "盘旋曲折,乘车前往,未达目的而还"}, {"w": "纡鉷", "t": "迂回"}, {"w": "纡险", "t": "盘曲险阻"}, {"w": "纡错", "t": "迂回交错"}, {"w": "纡萦", "t": "山水回环旋绕。"}]}, {"meaning": "佩戴。", "cites": [{"t": "我待纡双绶,遗我星星发。", "b": "李贺《感讽五首》"}], "words": [{"w": "纡金拖紫", "t": "佩带金银珠宝,穿着绫罗绸缎"}, {"w": "纡紫", "t": "系佩紫绶,指居高位的人"}, {"w": "纡朱拖紫", "t": "比喻人的地位高显尊贵"}, {"w": "纡青拖禁", "t": "比喻地位显贵"}, {"w": "纡青", "t": "佩带青绶。作高官。"}]}, {"meaning": "系结。", "cites": [{"t": "绾黄纡紫。", "b": "清·周容《芋老人传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3645wx','纣','1','zhòu','纟','6','','[{"pinyin": "zhòu", "defs": [{"meaning": "驾车马后部的革带。", "cites": [{"t": "纣,马緧也。从糸,肘省声。", "b": "《说文》"}, {"t": "车纣,自关而东,周、洛、韩、汝、颍而东谓之鞧,或谓之曲绹,或谓之曲纶;自关而西谓之纣。", "b": "扬雄《方言》"}]}, {"meaning": "商代最末的君主名,史称纣王。历史上有名的暴君。", "cites": [{"t": "桀纣贵为天子。", "b": "《吕氏春秋·功名》。注:“贱仁多累曰纣。”"}, {"t": "残义损善曰纣。", "b": "蔡邕《独断》"}, {"t": "以同言楚威王于侧纣之间。", "b": "《战国策·秦策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3646wx','纥','1','gē hé','纟','6','','[{"pinyin": "gē", "defs": [{"meaning": "—— 如:纥地(笑的声音);纥刺星(骂人的话。魔星,灾星)。"}]}, {"pinyin": "hé", "defs": [{"meaning": "下等丝。", "cites": [{"t": "给,大丝。", "b": "《集韵》"}]}, {"meaning": "回纥 。古代民族名。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3647wx','纨','1','wán','纟','6','','[{"pinyin": "wán", "defs": [{"meaning": "细致洁白的薄绸。", "cites": [{"t": "纨,素也。从系,丸声,谓白致缯,今之细生绢也。", "b": "《说文》"}, {"t": "下宫糅罗纨。", "b": "《战国策·齐策》"}, {"t": "寄言纨袴与膏粱:莫效此儿形状!", "b": "《红楼梦》"}], "words": [{"w": "纨袖", "t": "白练衣袖"}, {"w": "纨质", "t": "白皙细洁,如纨素之质。多形容妇女美质"}, {"w": "纨绮", "t": "精美的丝织品。"}]}, {"meaning": "纨扇,细绢扇。", "cites": [{"t": "两路绿杨藏乳燕,行人避暑扇摇纨。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
