INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3650wx','抟','1','tuán','扌','7','','[{"pinyin": "tuán", "defs": [{"meaning": "(形声。从手,专声。本义:把东西捏聚成团)。"}, {"meaning": "同本义。", "cites": [{"t": "抟,圜也。", "b": "《说文》。《韵会》引《说文》:“抟,以手圜之也。”"}, {"t": "毋抟饭。", "b": "《礼记·曲礼上》"}, {"t": "俊鹘抟水禽。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "抟铸", "t": "团捏铸造"}, {"w": "抟弄", "t": "摆弄"}, {"w": "抟黍", "t": "捏黍成圆形"}, {"w": "抟饭", "t": "捏饭成团"}, {"w": "抟食", "t": "手捏饭团而食"}, {"w": "抟人", "t": "抟土作人"}, {"w": "抟沙", "t": "捏沙成团。比喻聚而易散"}, {"w": "抟泥", "t": "捏弄泥团,以为器皿。喻粗陋。"}]}, {"meaning": "集聚。", "cites": [{"t": "亲友如抟沙,放手还复散。", "b": "宋·苏轼《二公再和亦再答之》"}], "words": [{"w": "抟力", "t": "集聚力量"}, {"w": "抟国", "t": "聚集国力"}, {"w": "抟结", "t": "集聚凝结"}, {"w": "抟抟", "t": "凝聚如团貌"}, {"w": "抟聚", "t": "集聚"}, {"w": "抟据", "t": "堆积成团。"}]}, {"meaning": "鸟类向高空盘旋飞翔。", "cites": [{"t": "鹏之徙于南冥也,水击三千里,抟扶摇而上者九万里。", "b": "《庄子·逍遥游》"}, {"t": "抟飞出南皮。", "b": "《文选·范云·赠王中书诗》。注引《庄子》司马注:“抟,圜也。周飞而上,若扶摇也。”"}], "words": [{"w": "抟云", "t": "鼓动翅膀直上青云"}, {"w": "抟风", "t": "鹏鸟鼓动翅膀、结聚风力而乘风上飞"}, {"w": "抟空", "t": "盘旋于高空"}, {"w": "抟翼", "t": "振翅高飞"}, {"w": "抟鹏", "t": "盘旋在高空的鹏鸟"}, {"w": "抟跃", "t": "抟风飞跃"}, {"w": "抟摇", "t": "乘风。"}]}, {"meaning": "圆。", "cites": [{"t": "小首而长,抟身而鸿,若是者谓之鳞属。", "b": "《周礼·考工记·梓人》"}, {"t": "曾枝剡棘,圆果抟兮。", "b": "《楚辞·屈原·橘颂》"}], "words": [{"w": "抟抟", "t": "圆圆的样子"}, {"w": "抟廉", "t": "圆润而锐利。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3651wx','抔','1','póu','扌','7','','[{"pinyin": "póu", "defs": [{"meaning": "(本作“捊”。形声。从手,不声。本义:用手捧)同本义。", "cites": [{"t": "污尊而抔饮。", "b": "《礼记·礼运》。注:“手掬之也。”"}], "words": [{"w": "抔饮", "t": "以手掬水而饮"}, {"w": "抔土", "t": "抓土;一捧之土。极言甚少。"}]}, {"meaning": "相当于“捧”、“把”、“握”。", "cites": [{"t": "假令愚民取长陵一抔土,陛下何以加其法乎。", "b": "《史记·张释之冯唐列传》"}, {"t": "黄花冈上一抔土。", "b": "孙文《黄花冈七十二烈士事略》序"}], "words": [{"w": "一抔米", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3652wx','圻','1','qí yín','土','7','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从土,斤声。《说文》中与“垠”同字。本读yǐn。本义:边际)。"}, {"meaning": "畿,京畿。古称天子直辖之地。亦指京城所领的地区。", "cites": [{"t": "矧惟若畴圻父。", "b": "《书·酒诰》。郑注:“谓司马主封畿之事。”"}, {"t": "且昔天子之地一圻。", "b": "《左传·襄公二十五年》"}], "words": [{"w": "圻父", "t": "古官名。掌封畿内军事"}, {"w": "圻甸", "t": "天子的领地,天子之地方千里,千里之内谓之“圻甸”"}, {"w": "圻郊", "t": "都邑的郊野。"}]}, {"meaning": "疆界;地域。", "cites": [{"t": "万千里曰王圻。", "b": "《周书·职方》。注:“界也。”"}, {"t": "今土数圻。", "b": "《左传·昭公三十三年》"}, {"t": "化协殊裔,风衍遐圻。", "b": "晋·陆机《辩亡论上》"}]}, {"meaning": "曲岸。通“碕。", "cites": [{"t": "汤泉发云潭,焦烟起石圻。", "b": "鲍照《苦热行》"}, {"t": "圻岸屡崩奔。", "b": "谢灵运《入彭蠡湖口》"}], "words": [{"w": "圻岸", "t": "曲岸。"}]}]}, {"pinyin": "yín", "defs": [{"meaning": "边际。", "cites": [{"t": "四达无境,通于无圻。", "b": "《淮南子·倏真》"}]}]}]','jingmo-wenyan');
