('3656wx','抃','1','biàn','扌','7','','[{"pinyin": "biàn", "defs": [{"meaning": "鼓掌。", "cites": [{"t": "帝喾乃令人抃。", "b": "《吕氏春秋·古乐》"}, {"t": "喟仰抃而抗首。", "b": "成公子安《啸赋》"}]}, {"meaning": "击;搏。"}, {"meaning": "顿,踏。", "cites": [{"t": "百兽率舞而抃足。", "b": "成公子安《啸赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3657wx','抉','1','jué','扌','7','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从手,夬(guài)声。本义:挑出,挖出)。"}, {"meaning": "同本义。", "cites": [{"t": "抉,挑也。", "b": "《说文》"}, {"t": "抉人之口。", "b": "《荀子》"}, {"t": "抉吾眼。", "b": "《史记·伍胥传》"}, {"t": "因自皮面抉眼,自屠出肠。", "b": "《战国策·韩策二》"}], "words": [{"w": "抉目", "t": "挖出眼睛"}, {"w": "抉眼", "t": "挖出眼珠"}, {"w": "抉耳", "t": "挖清耳朵"}, {"w": "抉发", "t": "发掘"}, {"w": "抉微", "t": "谓发掘事物的隐微。"}]}, {"meaning": "挑开;撬开。", "cites": [{"t": "郰人纥抉之以出门者。", "b": "《左传·襄公十年》。注:“撅也。”"}], "words": [{"w": "抉关", "t": "撬开城门或关口的大门"}, {"w": "抉拾", "t": "古代射箭用具。抉,即扳指,戴于右指上,用以钩弦。拾,即皮护臂。"}]}, {"meaning": "掰,用手指使分开。", "cites": [{"t": "那半个一人抉一块儿,分着吃了。", "b": "《新儿女英雄传》"}]}, {"meaning": "挑选;选取。", "cites": [{"t": "先生之作,遇景入咏,不拘奇抉异。", "b": "皮日休《郢州孟亭记》"}], "words": [{"w": "抉剔", "t": "摘取剔出"}, {"w": "抉撾", "t": "抉择;择取"}, {"w": "抉摘", "t": "选取,揭发"}, {"w": "抉搜", "t": "搜求挑取"}, {"w": "抉挑", "t": "挑动。"}]}, {"meaning": "扳指 。古代射箭时套在右手拇指上,用以钩弦。", "cites": [{"t": "百夫抉拾。", "b": "《国语·吴语》"}, {"t": "矰弋抉拾。", "b": "《周礼·缮人》"}]}]}]','jingmo-wenyan');
