INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3660wx','邯','1','hán','阝','7','','[{"pinyin": "hán", "defs": [{"meaning": "古地名。", "cites": [{"t": "赵邯郸县。从邑,甘声。", "b": "《说文》。朱曰:“今直隶广平府邯郸县,甘地有邯山。"}, {"t": "进至邯郸。", "b": "《后汉书·光武纪》。注:“邯,山名。郸,尽也。邯山至此而尽。城郭字皆从邑,因以名焉。”"}], "words": [{"w": "邯郸丽步", "t": "赵地美女的优美舞蹈"}, {"w": "邯郸梦", "t": "又称“黄梁梦”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3661wx','芸','1','yún yùn','艹','7','','[{"pinyin": "yún", "defs": [{"meaning": "(形声。从艸,云声。本义:香草名,也叫“芸香”)。"}, {"meaning": "同本义,多年生草本植物,其下部为木质,故又称芸香树。叶互生,羽状深裂或全裂,花黄色,香气浓郁,可入药。", "cites": [{"t": "芸,芸草也,似目宿。", "b": "《说文》"}, {"t": "芸草可以死复生。", "b": "《淮南子·王说》"}, {"t": "阳华之芸。", "b": "《吕氏春秋·本味》。注:“芳菜也。”"}, {"t": "芸始生。", "b": "《礼记·月令》"}, {"t": "元载末年,造芸辉堂于私第。芸辉,香草名也。", "b": "唐·苏鹗《杜阳杂编》"}], "words": [{"w": "芸帙", "t": "书籍。因芸香可驱蠹虫,书卷中多置之,故名。同“芸编”"}, {"w": "芸窗", "t": "书斋。古人藏书用芸香避蠹虫,故借芸以称书斋"}, {"w": "芸草", "t": "芸香"}, {"w": "芸编", "t": "指书籍。芸,香草,置书页内可以辟蠹,故称"}, {"w": "芸馆", "t": "书斋"}, {"w": "芸签", "t": "书签。亦借指书籍"}, {"w": "芸扃", "t": "藏书处。"}]}, {"meaning": "除掉杂草。同“耘”。", "cites": [{"t": "植其仗而芸。", "b": "《论语·微子》"}, {"t": "先雨芸耨。", "b": "《管子·小匡》"}, {"t": "父子夫妇终年耕芸。", "b": "《汉书·王莽传》"}], "words": [{"w": "芸夫", "t": "即农夫"}, {"w": "芸锄", "t": "芸鉏。芟刈;耕耘"}, {"w": "芸耨", "t": "耘耨。除草;耕种。"}]}, {"meaning": "芸苔 ,二年生草本植物,又叫“油菜”,花黄色,种子可榨油。"}]}, {"pinyin": "yùn", "defs": [{"meaning": "", "words": [{"w": "芸黄", "t": "草木枯黄的样子。"}]}]}]','jingmo-wenyan');
