INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3665wx','芷','1','zhǐ','艹','7','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从艸,止声。本义:白芷,香草名,也叫“辟芷”。中医学上以根入药) 同本义。", "cites": [{"t": "岸芷汀兰,郁郁青青。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "芷若", "t": "香草名。即白芷与杜若。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3666wx','芮','1','ruì','艹','7','','[{"pinyin": "ruì", "defs": [{"meaning": "(形声。从艸,内声。本义:芮芮。草初生的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "芮芮,草生貌。", "b": "《说文》"}]}, {"meaning": "小的。", "cites": [{"t": "蕞芮于城隅者,百不处一。", "b": "《文选·潘岳·西征赋》"}]}, {"meaning": "柔软。", "cites": [{"t": "不食谷食,不衣芮温。", "b": "《吕氏春秋·必已》"}]}, {"meaning": "陈奇猷校释:“此‘芮温’当从《释名》之义。‘不衣芮温’,谓不衣细软温暖之衣。”。"}, {"meaning": "结在盾上的丝带。"}, {"meaning": "水湾之内", "cites": [{"t": "芮鞫之即。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "芮鞫", "t": "指水湾。水湾之内称芮,水湾之外称鞫。"}]}, {"meaning": "古国名 。周初姬姓诸侯国之一,在今陕西省大荔县南。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
