INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3668wx','芼','1','mào','艹','7','','[{"pinyin": "mào", "defs": [{"meaning": "菜 。指可供食用的野菜或水草。", "cites": [{"t": "芼,草覆蔓也。从艸,毛声。", "b": "《说文》"}, {"t": "铡芼置于豆南。", "b": "《仪礼·特牲礼》。注:“菜也。”"}, {"t": "芼菜者,菜是地之毛。", "b": "《礼记·少牢礼》疏"}, {"t": "雉兔皆有芼。", "b": ""}, {"t": "礼记·内则》。注:“谓菜芼也。”", "b": ""}], "words": [{"w": "芼羹", "t": "用菜和肉做成的羹。"}]}, {"meaning": "用手指或指尖采摘。", "cites": [{"t": "参差荇菜,左右芼之。", "b": "《诗·周南·关雎》"}]}]}]','jingmo-wenyan');
