('3670wx','苁','1','cōng','艹','7','','[{"pinyin": "cōng", "defs": [{"meaning": "寄生植物\\"草苁蓉\\"和\\"肉苁蓉\\"的统称。草苁蓉亦称\\"列当\\"；肉苁蓉茎和叶黄褐色，茎可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3671wx','芩','1','qín','艹','7','','[{"pinyin": "qín", "defs": [{"meaning": "黄芩。", "cites": [{"t": "芩,芩草也。", "b": "《说文》"}, {"t": "食野之芩。", "b": "《诗·小雅·鹿鸣》"}]}, {"meaning": "古书上指芦苇一类的植物。多年生草本植物,叶子对生,披针形,开淡紫色花。根黄色,中医入药,有清热祛湿等作用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3672wx','芪','1','qí','艹','7','','[{"pinyin": "qí", "defs": [{"meaning": "“黄芪”的简称 ,是黄芪属多年草本植物,奇数羽状复叶,小叶卵形,花黄色,果为荚果,其根入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3673wx','芡','1','qiàn','艹','7','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从艸,欠声。本义:水生植物。又名鸡头)。"}, {"meaning": "即“芡实”,俗称“鸡头”。", "cites": [{"t": "芡,鸡头也。", "b": "《说文》"}, {"t": "按,花似鸡冠,实苞如鸡首,故名。生于池沼中的一种一年生大水草,体表有刺,叶圆而大,浮于水面,花茎伸长于水面上,顶生一花,紫色,浆果球形,果内胚乳白粉质,可食用。如:芡珠(芡的子实)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3674wx','芟','1','shān','艹','7','','[{"pinyin": "shān", "defs": [{"meaning": "(会意。从殳(shū)。殳,兵器。以殳除草。本义:铲除杂草)。"}, {"meaning": "同本义。", "cites": [{"t": "芟,刈草也。", "b": "《说文》"}, {"t": "尝之日,涖卜来岁之芟。", "b": "《周礼·肆师》"}, {"t": "芟蕰崇之。", "b": "《左传·隐公六年》"}, {"t": "载芟载柞。", "b": "《诗·周颂·载芟》。注:“除草曰芟。”"}], "words": [{"w": "芟夷", "t": "除草,割草"}, {"w": "芟荑", "t": "同“芟夷”。刈除"}, {"w": "芟柞", "t": "指耕作"}, {"w": "芟翦", "t": "芟剪。剪除;修剪"}, {"w": "芟薙", "t": "刈除"}, {"w": "芟柞", "t": "割除草木"}, {"w": "芟秽", "t": "割除杂草。后用以比喻除去祸害。"}]}, {"meaning": "斩杀;消灭;清除。", "cites": [{"t": "芟野菼。", "b": "《淮南子·本经》。注:“杀也。”"}, {"t": "今操芟夷大难,略已平矣。", "b": "《资治通鉴》"}], "words": [{"w": "芟讨", "t": "讨灭敌人"}, {"w": "芟锄", "t": "除去,铲除"}, {"w": "芟刈", "t": "割,引申为杀戮"}, {"w": "芟夷", "t": "铲除;除草;亦指杀戮"}, {"w": "芟定", "t": "平定。"}]}, {"meaning": "大镰刀。", "cites": [{"t": "权节其用,耒、耜、耞、芟。", "b": "《国语·齐语》"}], "words": [{"w": "芟割", "t": "用镰刀收割。"}]}]}]','jingmo-wenyan');
