INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3678wx','杌','1','wù','木','7','','[{"pinyin": "wù", "defs": [{"meaning": "树木无枝丫", "words": [{"w": "杌樗", "t": "光秃的臭椿树"}]}, {"meaning": "浑然无知", "words": [{"w": "杌杌", "t": "痴。呆貌"}]}, {"meaning": "摇,动摇", "cites": [{"t": "扬翠叶,杌紫茎。", "b": "《史记·司马相如列传》"}], "words": [{"w": "杌坐儿", "t": "小凳子"}, {"w": "杌床", "t": "用绳编制的轻便坐具"}]}, {"meaning": "小矮凳", "words": [{"w": "杌坐儿", "t": "小凳子"}, {"w": "杌床", "t": "用绳编制的轻便坐具"}]}, {"meaning": "砍树剩余的桩子", "cites": [{"t": "杌,刊余木。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3679wx','杓','1','biāo sháo','木','7','','[{"pinyin": "biāo", "defs": [{"meaning": "斗杓 古代对北斗七星柄部的三颗星——玉衡(北斗五,大熊座ε)、开阳(北斗六、大熊座ζ)和摇光(北斗七,大熊座η)的称呼。"}, {"meaning": "独木小桥。", "cites": [{"t": "杓,以横木渡于溪涧之上,但使人迹可通也。", "b": "韩拙《论人物桥杓四时之景》"}]}]}, {"pinyin": "sháo", "defs": [{"meaning": "杓子。", "cites": [{"t": "将行于杯杓。", "b": "《汉书·息夫躬传》"}, {"t": "徐以杓酌油沥之,自钱孔入,而钱不湿。", "b": "宋·欧阳修《卖油翁》"}], "words": [{"w": "杓棒", "t": "头部像勺子样弯曲的击球棍"}, {"w": "杓口", "t": "烹饪技术"}, {"w": "杓俫", "t": "骂人的话。蠢货,傻瓜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3680wx','杞','1','qǐ','木','7','','[{"pinyin": "qǐ", "defs": [{"meaning": "(形声。从木,己声。本义:木名,枸杞)。"}, {"meaning": "同本义。茄科,落叶小灌木。浆果卵圆形,红色。果实、根皮(地骨皮)可入药。", "cites": [{"t": "杞,枸杞也。", "b": "《说文》"}, {"t": "南山有杞。", "b": "《诗·小雅·南山有台》"}, {"t": "我有圃生之杞乎。", "b": "《左传·昭公十二年》"}, {"t": "千村万落生荆杞。", "b": "唐·杜甫《兵车行》"}], "words": [{"w": "杞狗", "t": "谓枸杞所化之犬"}, {"w": "杞楠", "t": "二木名。杞与楠,皆佳木。"}]}, {"meaning": "古国名 。公元前11世纪周分封的诸侯国。公元前445年为楚所灭。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3681wx','杈','1','chā chà','木','7','','[{"pinyin": "chā", "defs": [{"meaning": "(形声。从木,叉声。本义:树干的分枝或树枝的分岔)。"}, {"meaning": "同本义。", "cites": [{"t": "杈,杈枝也。", "b": "《说文》"}, {"t": "江东谓树枝为桠杈。", "b": "《方言》"}, {"t": "突杈枒而皆折,又有触邪之气也。", "b": "杜甫《雕赋》"}], "words": [{"w": "杈桠", "t": "杈丫;杈儿。树的分枝。"}]}]}, {"pinyin": "chà", "defs": []}]','jingmo-wenyan');
