INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3685wx','邳','1','pī','阝','7','','[{"pinyin": "pī", "defs": [{"meaning": "古国名。", "cites": [{"t": "邳,奚仲之后,汤左相仲虺所封,国在鲁薛县。", "b": "《说文》"}, {"t": "商有姺邳,盖仲虺之裔为乱者,国灭,武王复封其后于邳,为薛侯。", "b": "《左传·昭公元年》"}]}, {"meaning": "古州名 。北周置。治所在下邳(今江苏省睢宁北)。"}, {"meaning": "大。", "cites": [{"t": "棂栏邳张。", "b": "何晏《景福殿赋》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3686wx','矶','1','jī','石','7','','[{"pinyin": "jī", "defs": [{"meaning": "水边突出的岩石或石滩。", "cites": [{"t": "钓矶平可坐,苔磴滑难步。", "b": "孟浩然《经七里滩》"}, {"t": "舟过矶。(指澎浪矶。)", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "矶沚", "t": "水边石滩与水中小洲"}, {"w": "矶嘴", "t": "指水边突出的大石的顶端。"}]}, {"meaning": "(形声。从石,幾声。本义:大石激水) 水冲击岩石。引申为激怒,触犯。", "cites": [{"t": "亲之过小而怨,是不可矶也。", "b": "《孟子·告子下》"}], "words": [{"w": "矶激", "t": "冲击上涌;激荡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3687wx','奁','1','lián','大','7','','[{"pinyin": "lián", "defs": [{"meaning": "古代盛梳妆用品的匣子。", "cites": [{"t": "弹棋始自魏宫内用妆奁戏。", "b": "《世说新语·巧艺》"}, {"t": "凝走弄香奁,拔脱金屈戌。", "b": "李商隐《骄儿诗》"}], "words": [{"w": "妆奁", "t": "香奁。放梳妆用品的器具。"}]}, {"meaning": "泛指盛放器物的匣子。", "cites": [{"t": "…并两部书,茶奁、茶杯而已。", "b": "《红楼梦》"}], "words": [{"w": "一奁饭", "t": "一盒饭"}, {"w": "茶奁", "t": "茶壶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3688wx','豕','1','shǐ','豕','7','','[{"pinyin": "shǐ", "defs": [{"meaning": "(象形。甲骨文字形,象猪形,长吻,大腹,四蹄,有尾。本义:猪)同本义。", "cites": [{"t": "豕,彘也。", "b": "《说文》"}, {"t": "六畜蕃息豚豕猪。", "b": "《急就篇》。颜注:“豕者,彘之总名也。”"}, {"t": "有豕白蹢。", "b": "《诗·小雅·渐渐之石》"}, {"t": "豕首纵目。", "b": "《楚辞·大招》"}, {"t": "有读史记者曰:“晋师三豕涉河。”子夏曰:“非也,是己亥也。夫己与三相近,豕与亥相似。”", "b": "《吕氏春秋·察传》"}], "words": [{"w": "豕心", "t": "豕贪食,用以比喻贪婪无厌之心"}, {"w": "豕仙", "t": "战国时朔人献给燕昭王大豕,此豕年岁已有一百二十年,故称豕仙"}, {"w": "豕牢", "t": "养猪的房舍"}, {"w": "豕突", "t": "象野猪一样奔跑乱窜"}, {"w": "豕首", "t": "猪头似的脸形。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3689wx','忒','1','tè tuī','心','7','','[{"pinyin": "tè", "defs": [{"meaning": "(形声。从心,弋(yì)声。本义:差误) 同本义 (侧重不符合客观实际)。", "cites": [{"t": "忒,更也。", "b": "《说文》"}, {"t": "忒,差也。", "b": "《广雅》"}, {"t": "故日月不过,而四时不忒。", "b": "《易·豫》"}, {"t": "春秋匪解,享祀不忒。", "b": "《诗·鲁颂·閟宫》"}, {"t": "淑人君子,其仪不忒。", "b": "《诗·曹风·鸤鸠》"}, {"t": "忒,差也。", "b": "《广雅·释诂四》"}, {"t": "昊天不忒。", "b": "《诗·大雅·抑》"}, {"t": "常德不忒。", "b": "《老子》第二十八章"}], "words": [{"w": "差忒", "t": "差错。"}]}]}, {"pinyin": "tuī", "defs": [{"meaning": "", "words": [{"w": "人忒多;风忒大;这房子忒小", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3690wx','欤','1','yú','欠','7','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从欠,与声。欠,与出气有关。本义:表感叹、反诘、疑问语气)。"}, {"meaning": "表疑问语气。", "cites": [{"t": "能者用而智者谋,彼其智者欤?", "b": "柳宗元《梓人传》"}]}, {"meaning": "表感叹语气。", "cites": [{"t": "无怀氏之民欤!葛天氏之民欤!", "b": "晋·陶潜《五柳先生传》"}]}, {"meaning": "表反诘语气。", "cites": [{"t": "子非三闾大夫欤?", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3691wx','轫','1','rèn','车','7','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从车,刃声。本义:支住车轮使其不能转动的木头)。"}, {"meaning": "同本义。", "cites": [{"t": "轫,碍车也。", "b": "《说文》"}, {"t": "车不发轫。", "b": "《淮南子·兵略》。注:“车下支。”"}, {"t": "朝发轫于苍梧兮,夕吾至乎县圃。", "b": "《楚辞·离骚》"}]}, {"meaning": "古时的一种长度单位。", "cites": [{"t": "掘井九轫而不及泉。", "b": "《孟子》"}]}, {"meaning": "车轮。", "cites": [{"t": "水渐轫以凝冱。", "b": "《文选》。李善注引颜延年《篡要解》曰:“车轮谓之轫。”"}]}, {"meaning": "柔弱;懒散。"}, {"meaning": "柔软而坚固。", "cites": [{"t": "凡用兵者攻坚则轫。", "b": "《管子·制分》"}]}, {"meaning": "引申为阻止。", "cites": [{"t": "陛下尝轫车于赵矣。", "b": "《战国策·秦策》。注:“轫车,止仕也。”"}, {"t": "遂以头轫乘舆轮。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3692wx','迓','1','yà','辶','7','','[{"pinyin": "yà", "defs": [{"meaning": "(形声。从言(chuò),牙声。本义:迎接)。"}, {"meaning": "同本义。", "cites": [{"t": "迓,迎也。古本皆作讶。", "b": "《尔雅》"}, {"t": "子迓续乃命于天。", "b": "《书·盘庚》"}, {"t": "弗迓克奔。", "b": "《书·牧誓》"}, {"t": "迓晋侯于新宫。", "b": "《左传·成公十三年》"}], "words": [{"w": "有失迎迓", "t": ""}]}, {"meaning": "溜走。", "cites": [{"t": "何曾敢与他和尚争锋,望着直南下便迓。", "b": "金·董解元《西厢记诸宫调》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3693wx','邶','1','bèi','阝','7','','[{"pinyin": "bèi", "defs": [{"meaning": "古国名 。周武王封殷纣王之子武庚于此,约相当于今河南省淇县以北,汤阴县东南一带地方。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3694wx','忐','1','tǎn','心','7','','[{"pinyin": "tǎn", "defs": [{"meaning": "心神不安。", "cites": [{"t": "忐，忐忑，心虚也，怯也，惧也。--《五音集韵·感韵》", "b": ""}, {"t": "不免脚儿跌，口儿嗟，意儿中忐忑，心儿里怯。--洪昻《长生殿》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3695wx','卣','1','yǒu','卜','7','','[{"pinyin": "yǒu", "defs": [{"meaning": "(象形。本义:古代一种酒器,椭圆形) 同本义 。青铜制,椭圆口,深腹,圈足,有盖和提梁。也有作圆筒形的,器形变化较多。用以盛酒。盛行于商代和西周初期。", "cites": [{"t": "卣,中尊也。", "b": "《尔雅》"}, {"t": "以秬鬯二卣。", "b": "《书·洛诰》"}, {"t": "秬鬯一卣,圭瓒副焉。", "b": "《三国演义》"}, {"t": "用赍尔秬鬯一卣。", "b": "《书·文侯之命》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3696wx','邺','1','yè','阝','7','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。从邑,业声。本义:邺城) 同本义 。古地名。春秋齐桓公始筑城。秦置县。三国·魏为邺都。晋避怀帝讳,改为监漳。此后,历为前秦、后赵、东魏、北齐的首都。隋复为邺县,宋废。故址在今河北省监漳县西,河南省安阳市北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3697wx','旰','1','gàn','日','7','','[{"pinyin": "gàn", "defs": [{"meaning": "(形声。从日,干声。本义:天晚) 同本义。", "cites": [{"t": "旰,晚也。", "b": "《说文》"}, {"t": "日旰君勤。", "b": "《左传·昭公十二年》"}, {"t": "日旰不召,而射鸿于囿。", "b": "《左传·襄公十四年》"}, {"t": "当陛下旰食宵衣之日,是微臣输肝写胆之时。", "b": "《白氏长庆集·杭州刺史谢上表》"}], "words": [{"w": "旰食", "t": "因事忙而晚食。喻国事繁忙。"}]}]}]','jingmo-wenyan');
