INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3703wx','呃','1','è e','口','7','','[{"pinyin": "è", "defs": [{"meaning": "鸡叫声或笑声。", "cites": [{"t": "呝,喔也。从口,戹声。字亦作呃。", "b": "《说文》"}]}, {"meaning": "“按:呝喔双声连语。状鸡之声。”。", "cites": [{"t": "良游呝喔。", "b": "潘岳《射雉赋》"}], "words": [{"w": "呃喔", "t": "禽鸟鸣声"}, {"w": "呃呃", "t": "亦作呝呝。笑声"}, {"w": "呃吓", "t": "笑声。"}]}, {"meaning": "气逆作声。打嗝。", "cites": [{"t": "咳逆为病,古谓之哕,近谓之呃。", "b": "朱震亨《丹溪心法》"}]}]}, {"pinyin": "e", "defs": [{"meaning": "", "words": [{"w": "红霞映山崖呃!", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3704wx','旸','1','yáng','日','7','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从日,昜(yáng)声。本义:日出)。"}, {"meaning": "同本义。", "cites": [{"t": "旸,日出也。", "b": "《说文》"}, {"t": "曰旸谷。", "b": "《书·尧典》。传:“明也。”"}, {"t": "旸谷搏桑在东方。", "b": "《淮南子·地形》"}], "words": [{"w": "旸谷", "t": "古称日出之处。"}]}, {"meaning": "太阳。", "cites": [{"t": "薄吹消春冻,新旸破晓晴。", "b": "蔡襄《自渔梁驿至衢州大雪有怀》"}], "words": [{"w": "旸乌", "t": "太阳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3705wx','吡','1','bǐ pǐ','口','7','','[{"pinyin": "bǐ", "defs": [{"meaning": "诋毁。", "cites": [{"t": "中德也者,有以自好也,而吡其所不为者也。", "b": "《庄子·列御寇》"}]}, {"meaning": "比较", "cites": [{"t": "异类不吡,说在量。", "b": "《墨子》。高亨校诠:吡读为比,较也"}]}, {"meaning": "——用于有机化学的外语音译字。", "cites": [{"t": "吡啶", "b": ""}]}]}, {"pinyin": "pǐ", "defs": [{"meaning": "诋毁;斥责。", "cites": [{"t": "中德也者,有以自好也,而吡其所不为者也。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3706wx','町','1','dīng tīng','田','7','','[{"pinyin": "dīng", "defs": [{"meaning": "——“畹町”(Wǎndīng):镇名。在云南省德宏傣族景颇族自治州西南部。"}]}, {"pinyin": "tīng", "defs": [{"meaning": "(形声。从田,丁声。本义:田界,田间小路)。"}, {"meaning": "同本义。", "cites": [{"t": "町,田践处曰町。", "b": "《说文》"}], "words": [{"w": "町畦", "t": "田界;界域;界限;蹊径,途径。"}]}, {"meaning": "古代地积单位名。", "cites": [{"t": "町原防,牧隰皋,井衍沃。", "b": "《左传·襄公二十五年》"}]}, {"meaning": "田地;田亩 。", "words": [{"w": "町崖", "t": "田区崖岸"}]}, {"meaning": "日本的一种长度单位 ,1町=119码或1公里=9.167町。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3707wx','虬','1','qiú','虫','7','','[{"pinyin": "qiú", "defs": [{"meaning": "古代传说中的有角的龙。", "cites": [{"t": "虯,龙子有角者。从虫,按,俗字作“虬。", "b": ""}, {"t": "有鳞曰蛟龙,有翼曰应龙,有角曰虯龙,无角曰螭龙。", "b": "《广雅·释鱼》。按,龙“雄有角,雌无角,龙子一角者蛟,两角者虯,无角者螭也。”"}, {"t": "母龙曰蛟,子曰虯,其状鱼身如蛇尾,皮有珠。", "b": "《抱朴子》"}, {"t": "驾青虬兮骖白螭。", "b": "屈原《涉江》"}], "words": [{"w": "虬立", "t": "如虬龙般耸立。形容恣态骁勇矫健"}, {"w": "虬虎", "t": "龙和虎。比喻英雄豪士"}, {"w": "虬柱", "t": "雕绘虬龙的柱子"}, {"w": "虬龙片甲", "t": "虬龙是罕见的动物,虽是一片鳞甲,也很难得。比喻贵重的物品。"}]}, {"meaning": "盘曲,卷曲的样子。", "cites": [{"t": "弓欺猿臂秋无力,剑泣虬髯晓有霜。", "b": "罗邺《老将》"}], "words": [{"w": "虬眉", "t": "卷曲的眉毛"}, {"w": "虬髯", "t": "卷曲的胡须"}, {"w": "虬文", "t": "纠绕盘曲的花纹"}, {"w": "虬屈", "t": "盘屈纠结的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3708wx','呗','1','bài bei','口','7','','[{"pinyin": "bài", "defs": [{"meaning": "佛教经文中的赞偈,为梵语pāthaka(呗匿)音译之略。印度谓以短偈形式赞唱宗教颂歌。后泛指赞颂佛经或诵经声。", "cites": [{"t": "天竺方俗,凡是歌咏法言,皆称为“呗”。至于此土咏经则称为转读,歌赞则号为梵呗。", "b": "南朝梁·慧皎《高僧传·经师论》"}], "words": [{"w": "呗佛", "t": "诵经礼佛"}, {"w": "呗音", "t": "诵经声"}, {"w": "呗唱", "t": "唱偈颂经"}, {"w": "呗偈", "t": "赞唱颂偈"}, {"w": "呗声", "t": "诵经唱偈声"}, {"w": "呗赞", "t": "赞颂佛的功德。"}]}]}, {"pinyin": "bei", "defs": []}]','jingmo-wenyan');
