INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3712wx','帏','1','wéi','巾','7','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从巾,韦声。“巾”与丝织品有关。本义:佩带的香囊)。"}, {"meaning": "同本义。", "cites": [{"t": "帏,囊也。", "b": "《说文》"}, {"t": "苏粪壤以充帏兮,谓申椒其不芳。", "b": "《楚辞》"}]}, {"meaning": "帐子;幔幕。", "cites": [{"t": "帏,一说单帐也。", "b": "《广韵》"}, {"t": "帷屏无彷彿。", "b": "《文选·潘岳·悼亡诗》"}, {"t": "如素车白马帷盖之张。", "b": "《文选·枚乘·七发》"}], "words": [{"w": "帏盖", "t": "帏幕和篷盖"}, {"w": "帏幔", "t": "帐幕"}, {"w": "帏箔,帏薄", "t": "帐幕和帘子"}, {"w": "帏帘", "t": "帐幕"}, {"w": "帏幌", "t": "帷幌"}, {"w": "帏帐", "t": "惟帐"}, {"w": "帏室", "t": "张挂帷幔的内室"}, {"w": "帏屏", "t": "亦指寝息之所"}, {"w": "帏帽", "t": "帷帽"}, {"w": "帏幄", "t": "帐幔,帐幕;军队的帐幕,借指指挥中心;内庭,内室。"}]}, {"meaning": "裙正面的一幅。", "cites": [{"t": "王使妇人不帏而噪之。", "b": "《国语》。韦昭注:“裳正幅曰帏。”"}]}, {"meaning": "遮蔽。", "cites": [{"t": "其人无衣与裳,惟以布一幅束其阴,上体以被一方,帏而裹之。", "b": "《徐霞客游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3713wx','岐','1','qí','山','7','','[{"pinyin": "qí", "defs": [{"meaning": "(会意。从山,从枝省,支亦声。本义:古地名。陕西岐山县。又山名)。"}, {"meaning": "岐山 。因山有两枝,故名。岐山在今陕西省岐山县东北。上古称“岐”。", "cites": [{"t": "王用享于岐山。", "b": "《易·升》"}], "words": [{"w": "岐阳", "t": "岐山的南边;旧县名"}, {"w": "岐周", "t": "西周。周初立国于岐山,所以称岐周。"}]}, {"meaning": "物的分支或事有分歧。", "cites": [{"t": "即歧趾而胪情。", "b": "张衡《思玄赋》"}], "words": [{"w": "岐路", "t": "岔路"}, {"w": "三岐路口;岐首", "t": "两个头"}, {"w": "岐旁", "t": "岔路,两通的道路"}, {"w": "岐路人", "t": "宋代称民间卖艺的人。也作岐路或路岐人。"}]}, {"meaning": "崎岖。", "cites": [{"t": "汝阴太守曹武,思所以获免,阴蒙避迴，岐岖自列。", "b": "陆机《谢平原内史表》"}]}, {"meaning": "踮起脚跟。", "cites": [{"t": "诞实匍匐,克岐克嶷。", "b": "《诗·大雅·生民》"}]}]}]','jingmo-wenyan');
