INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3715wx','岘','1','xiàn','山','7','','[{"pinyin": "xiàn", "defs": [{"meaning": "小而险峻的山。", "cites": [{"t": "苕递陟陉岘。", "b": "谢灵运《从斤竹涧越岭溪行》。李善注:《声类》曰:“岘,山岭小高也”"}]}, {"meaning": "山名,岘山。"}, {"meaning": "在湖北省襄阳。又名岘首山。"}, {"meaning": "在江苏省丹徒县东南。也名兽窟。因建藏寺于此山,又名九华山。"}, {"meaning": "在浙江省东阳县南。又名双岘。"}, {"meaning": "在浙江省吴兴县南,本名显山,以唐庙讳改为岘山。"}, {"meaning": "在浙江省长兴县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3716wx','岑','1','cén','山','7','','[{"pinyin": "cén", "defs": [{"meaning": "(形声。从山,今声。本义:小而高的山)。"}, {"meaning": "同本义。", "cites": [{"t": "岑,山小而高也。", "b": "《说文》"}, {"t": "可使高于岑楼。", "b": "《孟子》。注:“岑楼,山之锐岭者。”按,谓山之层叠似楼也。”"}, {"t": "未始离于岑。", "b": "《庄子·徐无鬼》。注:“岸也。”"}, {"t": "饮青岑之王醴兮。", "b": "张衡《思玄赋》"}, {"t": "托九成之孤岑兮。", "b": "马融《长笛赋》"}], "words": [{"w": "岑嶅", "t": "多小石的山"}, {"w": "岑立", "t": "如山耸立。"}]}, {"meaning": "古国名。", "cites": [{"t": "岑,国名。…今梁国有岑亭。", "b": "《正字通》"}]}, {"meaning": "高。", "cites": [{"t": "古观岑且寂,幽人情自怡。", "b": "皮日休《三宿神景宫》"}], "words": [{"w": "岑楼", "t": "高楼"}, {"w": "岑锐", "t": "山高锐的样子。"}]}, {"meaning": "山石险峻的。", "cites": [{"t": "触岑石兮。", "b": "《楚辞·逢纷》"}], "words": [{"w": "岑石", "t": "高锐的山石"}, {"w": "岑峭", "t": "陡峭险峻。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3717wx','岚','1','lán','山','7','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从山,葻(lǎn)声。本义:山林中的雾气) 同本义。", "cites": [{"t": "未夜青岚入,先秋白露团。", "b": "白居易《新栽竹》"}], "words": [{"w": "岚气", "t": "山中雾气"}, {"w": "岚光", "t": "山间雾气经日光照射而发出的光彩"}, {"w": "岚峰", "t": "雾气缭绕的山峰"}, {"w": "岚雾", "t": "山中雾气"}, {"w": "岚霭", "t": "山中的云雾。岚,山林中的雾气。霭,云气。"}]}]}]','jingmo-wenyan');
