INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3721wx','钊','1','zhāo','钅','7','','[{"pinyin": "zhāo", "defs": [{"meaning": "(会意。从刀从金。表示用刀削金属。本义:磨损;削损)。"}, {"meaning": "同本义。", "cites": [{"t": "钊,刓也。", "b": "《说文》。承培元引经证例:“刓,…谓摩去器芒角也。”"}]}, {"meaning": "用勇气、精神或希望鼓舞。", "cites": [{"t": "门沆砀,驾以猋。俯下士,无不钊。", "b": "明·宋濂《补雩坛祝舞歌辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3722wx','钋','1','pō','钅','7','','[{"pinyin": "pō", "defs": [{"meaning": "化学性质类似于碲和铋的一种放射性金属元素。它存在于沥青铀矿及其他含铀矿物中,也存在于镭-铅废渣中及废氡管内,而在核反应堆中用中子轰击铋则可以生产大量的钋 。——元素符号Po。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3723wx','钌','1','liǎo liào','钅','7','','[{"pinyin": "liǎo", "defs": [{"meaning": "一种硬而脆呈浅灰色的多价稀有金属元素,是铂族金属中的一员 ——元素符号Ru。"}]}, {"pinyin": "liào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3724wx','迕','1','wǔ','辶','7','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从辵(chuò),午声。本义:相逢;相遇)。"}, {"meaning": "同本义。", "cites": [{"t": "迕,遇也。", "b": "《玉篇》"}, {"t": "王甫时出,与蕃相迕。", "b": "《后汉书·陈蕃传》"}]}, {"meaning": "违反;违背。", "cites": [{"t": "倒道而言,迕道而说者,人之所治也,安能治人?", "b": "《庄子》"}, {"t": "上下相反,好恶乘迕。", "b": "《汉书·食货志上》"}]}, {"meaning": "交错;夹杂。", "cites": [{"t": "百年三万日,老病常居半。其间迕忧乐,歌笑杂悲欢。", "b": "宋·苏轼《乔太傅见和复次韵答之》"}]}, {"meaning": "触犯。", "cites": [{"t": "公貌宽而内忌,不亮吾忠,而吾数以至言忤之。", "b": "《资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3725wx','氙','1','xiān','气','7','','[{"pinyin": "xiān", "defs": [{"meaning": "一种重的、无色惰性气体元素,存在于空气中,其量按体积计约占二千万分之一,也存在于温泉的气体中,从液态空气中与氪一起被分离得到,用于闸流管和特殊电灯中 ——元素符号Xe。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3726wx','氚','1','chuān','气','7','','[{"pinyin": "chuān", "defs": [{"meaning": "氢的放射性同位素,原子量为普通氢的三倍,半衰期12.5年,蜕变时放出β射线后形成质量数为三的氦。用中子轰击锂可产生氚 ——元素符号3H或T。"}]}]','jingmo-wenyan');
