INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3728wx','佞','1','nìng','亻','7','','[{"pinyin": "nìng", "defs": [{"meaning": "(会意。从女,信省。本义:用花言巧语谄媚) 同本义。", "cites": [{"t": "佞,巧谄高材也。", "b": "《说文》"}, {"t": "佞,巧也。", "b": "《广雅》"}, {"t": "佞,谄也。", "b": "《韩诗外传》"}, {"t": "佞之见佞,果丧其田。", "b": "《国语·晋语》"}, {"t": "为人佞巧。", "b": "《史记·周本纪》"}, {"t": "以邪导人谓之佞。", "b": "《盐铁论·刺议》"}, {"t": "焉用佞。", "b": "《论语·公冶长》"}, {"t": "非佞折狱,惟良折狱。", "b": "《书·吕刑》"}, {"t": "非佞誉诬谀之徒。", "b": "唐·柳宗元《答韦中立论师道书》"}], "words": [{"w": "佞王", "t": "奸佞"}, {"w": "佞巧", "t": "谄佞巧诈"}, {"w": "佞感", "t": "谄佞,媚惑"}, {"w": "佞道", "t": "谄佞邪恶之术"}, {"w": "佞兑", "t": "谄谀取悦"}, {"w": "佞禄", "t": "以谄谀取媚而获得利禄"}, {"w": "佞色", "t": "谄媚的表情"}, {"w": "佞恶", "t": "谄媚邪恶"}, {"w": "佞口", "t": "谗佞人之口;利口;巧嘴"}, {"w": "佞舌", "t": "巧嘴;巧舌"}, {"w": "佞言", "t": "逢迎讨好的话"}, {"w": "佞给", "t": "巧言善辩"}, {"w": "佞慧", "t": "善于阿谀奉承而又狡黠。"}]}, {"meaning": "巧言谄媚的人。", "cites": [{"t": "全望陛下亲贤远佞,以调天和,以安黎庶。", "b": "《英烈传》"}], "words": [{"w": "奸佞", "t": ""}]}, {"meaning": "有才智。", "cites": [{"t": "寡人不佞。", "b": "《左传·成公十三年》"}], "words": [{"w": "不佞", "t": "没有才智,多用为谦词。"}]}, {"meaning": "伪善的。", "cites": [{"t": "佞哀诈立,实非本怀。", "b": "《北史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3729wx','邱','1','qiū','阝','7','','[{"pinyin": "qiū", "defs": [{"meaning": "地名用字。", "cites": [{"t": "邱,地名。", "b": "《说文》"}]}, {"meaning": "孔子名丘,因避讳,清雍正三年上谕除四书五经外,凡遇“丘”字,并加“阝”旁为“邱” 。"}, {"meaning": "不好。", "cites": [{"t": "要好勿会好,要邱也勿会邱。", "b": "《海上花列传》"}, {"t": "说你品行实在邱。", "b": "华广生《白雪遗音》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3730wx','攸','1','yōu','攵','7','','[{"pinyin": "yōu", "defs": [{"meaning": "(会意。从攴(pū),从人水省。表示人扶杖走水路。本义:水流的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "攸,行水也,从攴,从人,水省。", "b": "《说文》。段玉裁注:“水之安行为攸。”"}, {"t": "水行攸攸也。", "b": "《六书故》引唐本说文"}]}, {"meaning": "安闲。", "cites": [{"t": "主人攸尔而笑曰。", "b": "《汉书·叙传》"}], "words": [{"w": "攸游", "t": "安闲从容,自得其乐的样子"}, {"w": "攸乐", "t": "闲适安乐"}, {"w": "攸心", "t": "心性弛放。"}]}, {"meaning": "长远。", "cites": [{"t": "令德攸兮宣重光。", "b": "汉《冀州从事张表碑》"}, {"t": "极攸远索。", "b": "《司农刘夫人碑》"}], "words": [{"w": "攸长", "t": "长远"}, {"w": "攸隔", "t": "远隔"}, {"w": "攸远", "t": "遥远,辽远。"}]}, {"meaning": "迅疾。", "cites": [{"t": "攸然而失。", "b": "《孟子·万章上》"}], "words": [{"w": "攸然", "t": "迅疾的样子"}, {"w": "攸攸", "t": "迅疾的样子;急速的样子。"}]}, {"meaning": "放在动词之前,构成名词性词组,相当于“所”。", "cites": [{"t": "攸,所也。", "b": "《尔雅》"}, {"t": "君子有所攸往。", "b": "《易·坤》"}, {"t": "乃尔攸闻。", "b": "《书·多方》"}, {"t": "攸馘安安。", "b": "《诗·大雅·皇矣》"}, {"t": "未有攸底。", "b": "《左传·昭公二十六年》"}]}, {"meaning": "攸县 ,汉置。故治在今湖南攸县东。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3731wx','佚','1','yì','亻','7','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从人,失声。本义:隐逸的人)。"}, {"meaning": "同本义。", "cites": [{"t": "佚民者,独乐其身之民也。", "b": "朱骏声《说文通训定声》"}], "words": [{"w": "佚老", "t": "隐逸的老人"}, {"w": "佚民", "t": "遁世隐居的人。"}]}, {"meaning": "行列,通佾。", "cites": [{"t": "其佚则接芬错芳。", "b": "《古文苑·扬雄·蜀都赋》"}]}, {"meaning": "不当行为;过失。", "cites": [{"t": "惟予一人有佚罚。", "b": "《书·盘庚上》"}]}, {"meaning": "散失。", "cites": [{"t": "宣帝之时,得佚《尚书》及《易》、《礼》各一篇。", "b": "《论衡》"}, {"t": "惟予一人有佚罚。", "b": "《书·盘庚上》。传:“佚,失也。”"}, {"t": "牛马畜兽有郊佚者,取之不诘。", "b": "《逸周书》"}], "words": [{"w": "佚名;佚书", "t": "散失的书籍"}, {"w": "佚文", "t": "散失的文句、篇章"}, {"w": "佚本", "t": "散失的本子"}, {"w": "佚史", "t": "散失、隐没的或正史以外的史事"}, {"w": "佚失", "t": "散失;失落"}, {"w": "佚存", "t": "散失而复得以保存"}, {"w": "佚事", "t": "散失沦没而为世人所不知的事迹,多未经史书正式记载"}, {"w": "佚闻", "t": "散失、隐没而不为世人所知晓的传说,多未见于正式记载。"}]}, {"meaning": "弃用;逃亡。", "cites": [{"t": "遗佚而不怨,厄穷而不悯。", "b": "《孟子》。朱熹注:遗佚,放弃也"}, {"t": "其佚获奈何?", "b": "《公羊传·成公二年》。注:“佚获者,已获而逃亡也。”"}, {"t": "身不佚者志不广。", "b": "《荀子·宥坐》"}], "words": [{"w": "佚志", "t": "逃亡的意向"}, {"w": "佚马", "t": "逸马。逃逸的马。"}]}, {"meaning": "放荡;放纵。", "cites": [{"t": "乐骄乐,乐佚游,乐宴乐,损矣。", "b": "《论语》。邢昺疏:乐佚游者,谓好出入不节也。"}, {"t": "男女淫佚。", "b": "《汉书》"}], "words": [{"w": "佚行", "t": "淫行"}, {"w": "佚君", "t": "淫佚之君。"}]}, {"meaning": "安逸。", "cites": [{"t": "佚,乐也。", "b": "《广雅》"}, {"t": "骨体肤理好愉佚。", "b": "《荀子·性恶》。注:“佚与逸同。”"}, {"t": "乐佚游。", "b": "《论语·季氏》"}, {"t": "舍佚而为劳。", "b": "《荀子·尧问》"}, {"t": "安于佚乐。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "佚志", "t": "安逸图乐的心志"}, {"w": "佚道", "t": "使人民安逸的办法"}, {"w": "佚乐", "t": "放逸游乐。"}]}, {"meaning": "美丽。", "cites": [{"t": "那娘娘生得来仙姿佚貌,说不尽幽闲窈窕。", "b": "清·洪《长生殿》"}], "words": [{"w": "佚女", "t": "美丽的女子。"}]}]}]','jingmo-wenyan');
