('3733wx','佟','1','tóng','亻','7','','[{"pinyin": "tóng", "defs": [{"meaning": "姓", "cites": [{"t": "佟,姓也。《北燕录》有辽东佟万,以文章知名。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3734wx','佗','1','tuó tuō','亻','7','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从人,它声。本义:负荷) 同“驮”。负有重担或负载。", "cites": [{"t": "佗,负何也。", "b": "《说文》"}, {"t": "以一马自佗负三十日食。", "b": "《汉书·赵充国传》"}], "words": [{"w": "佗负", "t": "驮负,载负。"}]}, {"meaning": "佗背(驼背)。"}]}, {"pinyin": "tuō", "defs": [{"meaning": "拖。", "cites": [{"t": "因以醮酒佗发,求之三宿而得。", "b": "《史记·龜策列传》"}], "words": [{"w": "佗发", "t": "披发。"}]}, {"meaning": "表示远指,别的,其他的。", "cites": [{"t": "制,岩邑也,虢叔死焉,佗邑唯命。", "b": "《左传·隐公元年》"}, {"t": "此无佗故也。", "b": "《大戴礼·礼察》"}, {"t": "佗日指动,必食异物。", "b": "《史记·郑世家》"}], "words": [{"w": "佗人", "t": "别人"}, {"w": "佗日", "t": "他日;往日;将来的某一天"}, {"w": "佗方", "t": "他方;他乡"}, {"w": "佗生", "t": "他生,来生"}, {"w": "佗年", "t": "他年,将来"}, {"w": "佗志", "t": "异心"}, {"w": "佗故", "t": "他故,别的原因。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3735wx','伽','1','gā jiā qié','亻','7','','[{"pinyin": "gā", "defs": [{"meaning": "镭和其他一些放射性元素的原子放出的射线，应用于工业和医学等领域。"}]}, {"pinyin": "jiā", "defs": [{"meaning": "加速度单位“伽里略”的简称,等于1厘米/秒2。尤指重力加速度单位。"}]}, {"pinyin": "qié", "defs": [{"meaning": "(形声。从人,加声。翻译佛经多用为人名,故从“人”)。"}, {"meaning": "梵语僧加蓝摩的略称，佛教寺院的通称", "cites": [{"t": "我不如走到伽蓝殿中,问个终生的吉凶。", "b": "《英烈传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3736wx','彷','1','fǎng páng','彳','7','','[{"pinyin": "fǎng", "defs": [{"meaning": "相当。", "cites": [{"t": "夫人太虑过,小生空妄想,郎才女貌合相彷。", "b": "《西厢记》"}, {"t": "关将军美形状,张将军猛势状,再何势得相彷。", "b": "元·关汉卿《西蜀梦》"}]}, {"meaning": ""}]}, {"pinyin": "páng", "defs": [{"meaning": "(形声。从彳(chì),方声。彳,小步走。《玉篇》:“彷,彷徨也。”双音词“彷徨”又写作“方皇”、“仿偟”、“旁皇”,意为游移不定、盘旋。“彷”又构成“彷徉”。本义:徘徊、游荡)。"}, {"meaning": "同本义。", "cites": [{"t": "惟彷徨瞻顾,寻所逐者。", "b": "《聊斋志异·促织》"}], "words": [{"w": "彷洋", "t": "俳徊,遨游。"}]}, {"meaning": "芒然失据的样子。", "cites": [{"t": "行人驻足听,寡妇起彷徨。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "芒然彷徨乎尘垢之外,逍遥乎无为之业。", "b": "《庄子·大宗师》"}]}]}]','jingmo-wenyan');
