('3737wx','佘','1','shé','人','7','','[{"pinyin": "shé", "defs": [{"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3738wx','佥','1','qiān','人','7','','[{"pinyin": "qiān", "defs": [{"meaning": "(会意。从亼,从吅,从从。亼(jí),集合。吅(xuān)、从,都表示人多。本义:皆,咸) 同本义。", "cites": [{"t": "佥,皆也。", "b": "《说文》"}, {"t": "佥曰:“于,鲧哉!”", "b": "《书·尧典》"}], "words": [{"w": "佥言", "t": "皆云;都说。"}]}, {"meaning": "众人;大家。", "cites": [{"t": "佥荅何忧。", "b": "《楚辞·天问》。注:“众也。”"}, {"t": "佥,夥也。", "b": "《方言十二》"}], "words": [{"w": "佥言", "t": "众人的意见"}, {"w": "佥望", "t": "众望"}, {"w": "佥谋", "t": "众人筹划"}, {"w": "佥议", "t": "众人公开评议。"}]}, {"meaning": "连枷,打谷的农具。", "cites": [{"t": "《方言》“佥”郭璞注:“今连枷,所以打谷者。”", "b": ""}]}, {"meaning": "用同“签”。签署。", "cites": [{"t": "汝等各自佥名,共成此事。", "b": "《三国演义》"}], "words": [{"w": "佥押", "t": "在文书上签名画押表示负责"}, {"w": "佥押房", "t": "官员批阅公文,签字画押的地方。现称办公室"}, {"w": "佥解", "t": "签署押解"}, {"w": "佥票", "t": "签票"}, {"w": "佥名", "t": "签名"}, {"w": "佥判", "t": "签判;签名并作判词"}, {"w": "佥尾", "t": "在文书末尾签名表示负责。"}]}, {"meaning": "调动官职,多指升职。", "cites": [{"t": "除佥杭州判官。", "b": "《清平山堂话本》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3739wx','孚','1','fū fú','子','7','','[{"pinyin": "fū", "defs": [{"meaning": "孵化", "cites": [{"t": "孚,卵孚也。", "b": "《说文》。徐锴曰:“鸟抱,恒以爪覆其卵也。”。又如:孚育(孵化);孚乳(孵化生育);孚化(孵化);孚萌(孵育滋生)"}]}, {"meaning": "谷粒的壳。", "cites": [{"t": "苟本正,则华英必得其节,以秀孚矣。", "b": "《大戴礼·少间》"}], "words": [{"w": "孚甲", "t": "谷壳。"}]}]}, {"pinyin": "fú", "defs": [{"meaning": "相信;信任。", "cites": [{"t": "孚,一曰信也。", "b": "《说文》"}, {"t": "孚,信也。", "b": "《尔雅》"}, {"t": "中孚信也。", "b": "《易·杂卦传》。徐锴曰:“鸟之孚卵,皆如其期不失信也。”"}, {"t": "五辞简孚。", "b": "《书·吕刑》"}, {"t": "万邦作孚。", "b": "《诗·大雅·文王》"}, {"t": "此世所谓上下相孚也。", "b": "明·宗臣《报刘一丈书》"}], "words": [{"w": "孚佑", "t": "信任而佑助。"}]}, {"meaning": "为人所信服,使信任。", "cites": [{"t": "小信未孚,神弗福也。", "b": "《左传·庄公十年》"}], "words": [{"w": "深孚众望;名孚众望", "t": ""}]}, {"meaning": "“俘”的古字。俘获;俘虏。", "cites": [{"t": "孚人万三千八十一人。", "b": "《小盂鼎》"}]}, {"meaning": "草木种子分裂发芽。", "cites": [{"t": "柳稊。稊也者,发孚也。", "b": "《大戴礼·夏小正》"}], "words": [{"w": "孚甲", "t": "植物种子的外壳。引申为萌发,萌生"}, {"w": "孚笋", "t": "新竹、幼竹。"}]}, {"meaning": "浮露。", "cites": [{"t": "孚尹旁达,信也。", "b": "《礼记·聘义》"}]}, {"meaning": "信用;信誉。", "cites": [{"t": "成王之孚,下土之式。", "b": "《诗·大雅·下武》"}], "words": [{"w": "孚信", "t": "信用;信誉"}, {"w": "孚感", "t": "精诚感通"}, {"w": "孚释", "t": "恳切的解释"}, {"w": "孚洽", "t": "诚恳融洽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3740wx','豸','1','zhì','豸','7','','[{"pinyin": "zhì", "defs": [{"meaning": "本指长脊兽,如猫、虎之类。引申为无脚的虫,体多长,如蚯蚓之类。", "cites": [{"t": "有足谓之虫,无足谓之豸。", "b": "《尔雅》"}], "words": [{"w": "豸豸", "t": "兽背隆长的样子。"}]}, {"meaning": "解决。", "cites": [{"t": "使子逞其志,庶有豸乎。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3741wx','坌','1','bèn','土','7','','[{"pinyin": "bèn", "defs": [{"meaning": "尘埃。", "cites": [{"t": "霏霏散浮烟,霭霭集微坌。", "b": "元好问《戊戌十月山阳雨夜》"}], "words": [{"w": "微坌", "t": "微尘。"}]}, {"meaning": "指尘土飞扬着落在物体上。", "cites": [{"t": "逆风扬尘,尘不及彼,还坌己身。", "b": "《四十二章经》"}], "words": [{"w": "坌并", "t": "飞扬洒落"}, {"w": "坌起", "t": "飞起,扬起。"}]}, {"meaning": "聚集;合。", "cites": [{"t": "敌四万众坌集,傅城而阵。", "b": "《宋史·种世衡传》"}], "words": [{"w": "坌沓", "t": "会合,聚合。"}]}, {"meaning": "粗笨。", "cites": [{"t": "我似那灵禽在后,你这等笨鸟先飞。", "b": "元·关汉卿《陈母教子》"}]}, {"meaning": "也说“笨鸟先飞”、“夯雀儿先飞”。", "cites": [{"t": "咱们家没人,俗话说的,“夯雀儿先飞”,省的“临时丢三落四的不齐全,令人笑话。", "b": "《红楼梦》"}], "words": [{"w": "坌工", "t": "粗活,笨重的劳动"}, {"w": "坌鸟先飞", "t": "笨鸟先飞,喻笨人做事比人先动手。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3742wx','肟','1','wò','月','7','','[{"pinyin": "wò", "defs": [{"meaning": "主要由羟胺与醛和酮作用得到的一类化合物 其特征是具有>C=NOH基,其中异亚硝基取代了羰基中的氧。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3743wx','邸','1','dǐ','阝','7','','[{"pinyin": "dǐ", "defs": [{"meaning": "(形声。从邑,氐(dǐ)声。本义:战国时诸侯或朝见皇帝时在京城的住所。泛指官员办事或居住的处所)。"}, {"meaning": "同本义。", "cites": [{"t": "邸,属国舍也。", "b": "《说文》"}, {"t": "舍燕邸。", "b": "《汉书·卢绾传》。注:“诸侯王及诸郡朝宿之馆,在京师者谓之邸。”"}], "words": [{"w": "邸城", "t": "古代在京师为郡国诸侯或外藩君主朝觐起居所建的小城。"}]}, {"meaning": "止,到。", "cites": [{"t": "自中山西邸瓠口为渠。", "b": "《史记·河渠书》"}, {"t": "邸余车兮方林。", "b": "《楚辞·屈原·涉江》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3744wx','奂','1','huàn','大','7','','[{"pinyin": "huàn", "defs": [{"meaning": "互易", "cites": [{"t": "奂,取奂也。", "b": "《说文》"}]}, {"meaning": "呼唤", "cites": [{"t": "唤,呼也。古通作“奂”", "b": "《说文新附》"}]}, {"meaning": "盛大;众多。", "cites": [{"t": "奂,众多也。", "b": "《玉篇》"}, {"t": "可以知古,可以察今,奂然而与民壹始。", "b": "《大戴礼记·四代》"}, {"t": "奂,盛也。", "b": "《汉书·韦元成传》注"}], "words": [{"w": "奂然", "t": "盛大的样子"}, {"w": "奂衍", "t": "众多散布的样子"}, {"w": "奂烂", "t": "繁盛的样子。"}]}, {"meaning": "文彩鲜明的", "cites": [{"t": "美哉奂焉。", "b": "《礼记·檀弓》"}], "words": [{"w": "奂奂", "t": "文彩灿烂的样子"}, {"w": "奂若", "t": "色彩鲜明的样子。"}]}, {"meaning": "悠闲的,涣散的", "cites": [{"t": "伴奂尔游矣。", "b": "《诗·大雅·卷阿》"}, {"t": "君臣上下之际,奂然有离德者也。", "b": "《韩诗外传·卷三》"}, {"t": "业集累积,奂衍于其侧。", "b": "《文选·嵇康·琴赋》"}], "words": [{"w": "奂衍", "t": "满布的样子。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3745wx','劬','1','qú','力','7','','[{"pinyin": "qú", "defs": [{"meaning": "慰劳,犒赏,送礼物给。", "cites": [{"t": "食子者,三年而出,见于公宫则劬。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3746wx','狄','1','dí','犭','7','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从犬,亦声。本义:我国古代北部的一个民族)。"}, {"meaning": "同本义 中国古代民族名。分赤狄、白狄、长狄诸部,各有支系。因其主要居住在北方,故通称为北狄。又指秦汉以后,狄或北狄曾是中国中原人对北方各民族的泛称。", "cites": [{"t": "戎狄怀之。", "b": "《国语·晋语》"}, {"t": "夷狄益甚。", "b": "《史记·货殖列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
