INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3748wx','鸠','1','jiū','鸟','7','','[{"pinyin": "jiū", "defs": [{"meaning": "(形声。从鸟,九声。本义:鸟名)。"}, {"meaning": "鸠鸽科的鸟的泛称。", "cites": [{"t": "鸠,鹘鸠也。", "b": "《说文》"}, {"t": "维鸠居之。", "b": "《诗·召南·鹊巢》"}, {"t": "维鸠盈之。", "b": ""}, {"t": "维鸠方之。", "b": ""}]}, {"meaning": "一种行于沙中的运载工具。", "cites": [{"t": "水用舟,陆用车,涂用楯,沙用鸠,山用欙。", "b": "《吕氏春秋》"}]}, {"meaning": "聚集,使聚在一起。", "cites": [{"t": "鸠,聚也。", "b": "《尔雅》"}, {"t": "共工方鸠僝功。", "b": "《书·尧典》。传:“聚也。”"}, {"t": "以鸠其民。", "b": "《左传·隐公八年》"}, {"t": "鸠宗族僮奴。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "鸠工", "t": "招集劳工"}, {"w": "鸠民", "t": "聚集安定百姓"}, {"w": "鸠率", "t": "聚合率合"}, {"w": "鸠采", "t": "搜集"}, {"w": "鸠聚", "t": "聚集。"}]}, {"meaning": "使安定。", "cites": [{"t": "若鸠楚竟,敢不听命?", "b": "《左传·定公四年》"}, {"t": "内抚凋残,外鸠离散。", "b": "三国魏·张既《答文帝问苏则》"}]}, {"meaning": "度量;计算。", "cites": [{"t": "度三林,鸠薮泽。", "b": "《左传·襄公二十五年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3749wx','邹','1','zōu','阝','7','','[{"pinyin": "zōu", "defs": [{"meaning": "古国名 。春秋时叫“邾国”,又称“邾娄国”。战国时,鲁穆公将其改称为“邹国”。汉置邹县,属鲁国,在今山东省。唐为邹县,历代因之,明清时皆属兖州府。", "cites": [{"t": "邹,鲁县古邾国,帝颛顼之后所封。", "b": "《说文》。朱按,曹姓。邹者,邾娄之合音,战国时穆公改号邾娄为邹,后为楚所灭,若今济南府邹平县之邹。"}, {"t": "邹人与楚人战。", "b": "《孟子·梁惠王上》"}]}, {"meaning": "又。", "cites": [{"t": "邹敌楚战。", "b": ""}]}, {"meaning": "", "cites": [{"t": "邹忌讽齐王纳谏。(邹忌,齐国人,善鼓琴,有辩才。曾为齐相,封成侯。讽:用含蓄的话劝告或讽喻。纳:采纳,接受。谏:对君主,尊长进行劝告。)", "b": "《战国策·齐策》"}, {"t": "邹君海滨。(邹海滨先生。邹鲁,字海滨。他早期追随孙中山先生革命,后来反对三大政策,成为西山会议派的领袖。君,表示尊称。)", "b": "孙文《序》"}], "words": [{"w": "邹马", "t": "汉邹阳和司马相如并称"}, {"w": "邹子", "t": "指战国齐人邹衍。"}]}, {"meaning": "小;狭小的。", "cites": [{"t": "邹,狭小之言也。", "b": "《释名》"}], "words": [{"w": "邹查", "t": "小语声,悄悄话"}, {"w": "邹搜", "t": "气势不开阔。"}]}, {"meaning": "货物质量低劣的。", "cites": [{"t": "今人言物之不佳或薄小者曰邹。", "b": "《直语补正》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
