INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3751wx','饩','1','xì','饣','7','','[{"pinyin": "xì", "defs": [{"meaning": "(形声。从食,气声。字本作“氣”。本义:赠送人的谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "常从容上席,资饩甚厚。", "b": "《北史》"}], "words": [{"w": "饩食", "t": "米粮等食物。"}]}, {"meaning": "活的牲口。", "cites": [{"t": "脯资饩牵。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "饩羊", "t": "用为祭品的羊"}, {"w": "饩牵", "t": "活牲口。"}]}, {"meaning": "生肉。", "cites": [{"t": "出牲饩以劳师。", "b": "《旧五代史》"}], "words": [{"w": "饩牢", "t": "屠宰过的牲口"}, {"w": "饩馈", "t": "生肉与粮食。"}]}, {"meaning": "给养;俸禄。", "cites": [{"t": "生二人,公与之饩。", "b": "《国语》"}], "words": [{"w": "饩廪", "t": "粮食之类的生活物资"}, {"w": "饩稍", "t": "每月领的俸粮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3752wx','饪','1','rèn','饣','7','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从食,壬(rén)声。本义:做饭做菜) 同本义。", "cites": [{"t": "饪,大熟也。", "b": "《说文》"}, {"t": "餁,熟也。", "b": "《广雅》"}, {"t": "烹饪也。", "b": "《易·鼎》"}, {"t": "失饪不食。", "b": "《论语》"}], "words": [{"w": "失饪", "t": "烹调失当"}, {"w": "饪鼎", "t": "烹饪的鼎"}, {"w": "饪熟", "t": "烹调。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3753wx','饫','1','yù','饣','7','','[{"pinyin": "yù", "defs": [{"meaning": "吃饱。", "cites": [{"t": "饫,食过多。", "b": "《玉篇》"}, {"t": "饫,饱也,厌也。", "b": "《广雅》"}, {"t": "犀箸厌饫久未下,鸾刀缕切空纷纶。", "b": "杜甫《丽人行》"}, {"t": "饫肥之肠。", "b": "明·刘基《卖柑者言》"}]}, {"meaning": "又。", "cites": [{"t": "饫肥鲜者。又如:饫闻(厌闻。所闻过多而感厌倦之意)", "b": ""}]}, {"meaning": "赐。", "cites": [{"t": "饫,赐也。", "b": "《广韵》"}], "words": [{"w": "饫赐", "t": "赏赐丰足。"}]}, {"meaning": "饫礼,站立行礼。", "cites": [{"t": "夫礼之立成者为饫,昭明大节而已。", "b": "《国语·周语下》"}], "words": [{"w": "饫歌", "t": "行饫礼时所唱的歌诗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3754wx','饬','1','chì','饣','7','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从人,从力,食声。本义:修整,整治)。"}, {"meaning": "同本义。", "cites": [{"t": "饬,致坚也。", "b": "《说文》"}, {"t": "周军饬垒。", "b": "《国语·吴语》。注:“治也。”"}, {"t": "饬曲岸之际。", "b": "《淮南子·本纪》"}, {"t": "戎车既饬。", "b": "《诗·小雅·六月》"}], "words": [{"w": "整饬;饬装", "t": "整备行装"}, {"w": "饬兵", "t": "整顿军队。"}]}, {"meaning": "告诫", "cites": [{"t": "信饬百官,众功皆兴。", "b": "《史记·五帝本纪》"}, {"t": "修德束躬,以自申饬,所以检其邪心,守其正意也。", "b": "《说苑·修文》"}, {"t": "双饬众官,各慎其职。", "b": "《汉书·五行志上》"}, {"t": "欲令戒饬。", "b": "《汉书·杨恽传》"}], "words": [{"w": "饬厉", "t": "告诫勉励。也作敕厉"}, {"w": "饬勉", "t": "告诫勉励。"}]}, {"meaning": "谨慎;恭敬。", "cites": [{"t": "饬者,谨也,敬也。", "b": "《匡缪正俗》八"}], "words": [{"w": "饬备", "t": "谨慎防备"}, {"w": "饬愿", "t": "谨慎诚实。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3755wx','亨','1','hēng','亠','7','','[{"pinyin": "hēng", "defs": [{"meaning": "(象形。金文字形,象盛祭品之器形。小篆作“亳”,隶书写作“亨”、“享”,三字其实是同一个字。本义:献。引申义:通达)。"}, {"meaning": "同引申义。", "cites": [{"t": "品物咸亨。", "b": "《易·坤卦》"}], "words": [{"w": "亨达", "t": "通达顺利"}, {"w": "亨屯", "t": "通达与困厄"}, {"w": "亨泰", "t": "亨通安泰"}, {"w": "亨运", "t": "亨通的世运"}, {"w": "亨畅", "t": "通畅;昭明。"}]}, {"meaning": "顺利,有利于取得成功。", "cites": [{"t": "夫修道者,度其时而动。动而不时,焉得亨乎?", "b": "《后汉书》"}, {"t": "我心终不死,金石贯以诚。此诚患不立,虽困道亦亨。", "b": "唐·元稹《思归乐》"}]}, {"meaning": "电感实用单位亨利的简称。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3756wx','庑','1','wǔ','广','7','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从广,无声。从广(yǎn),与房屋有关。本义:堂下周围的廊屋)。"}, {"meaning": "同本义。", "cites": [{"t": "庑,堂下周屋。", "b": "《说文》"}, {"t": "居庑下,为人赁舂。", "b": "《后汉书·梁鸿传》"}, {"t": "合百草兮实庭,建芳馨兮庑门。", "b": "《楚辞》"}, {"t": "庑下一生伏案卧。", "b": "清·方苞《左忠毅公逸事》"}]}, {"meaning": "泛指房屋。", "cites": [{"t": "居大庑之下。", "b": "《史记》"}], "words": [{"w": "盖庑", "t": "盖屋"}, {"w": "计殿", "t": "有四坡略呈弯曲的屋面的房子。"}]}, {"meaning": "廊。", "cites": [{"t": "庙中空无所有,唯一黑漆棺停庑下。", "b": "《夜谭随录》"}]}, {"meaning": "屋檐。", "cites": [{"t": "檐,其名有十四…十一曰庑。", "b": "李诫《营造法式》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3757wx','庋','1','guǐ','广','7','','[{"pinyin": "guǐ", "defs": [{"meaning": "置放器物的架子。", "cites": [{"t": "见床内小板庋上,乌纱帽存。", "b": "宋·洪迈《夷坚志·蔡河秀才》"}], "words": [{"w": "庋阁", "t": "搁置器物的架子。"}]}, {"meaning": "搁置,放置。", "cites": [{"t": "经尊道则尊,有合严庋宾(即置)。", "b": "元·柳贯《尊经堂》"}], "words": [{"w": "庋架", "t": "置放架上"}, {"w": "庋置", "t": "搁置。"}]}, {"meaning": "收藏。", "cites": [{"t": "若业为吾所有,必高束焉,庋藏焉。", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "庋掌", "t": "收藏、管理"}, {"w": "庋间", "t": "储藏室"}, {"w": "庋藏", "t": "收藏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3758wx','疔','1','dīng','疒','7','','[{"pinyin": "dīng", "defs": [{"meaning": "病名,即疔疮 。一般发于颜面及手足等部位,根深形小,其状如钉,故名", "words": [{"w": "红丝疔", "t": ""}, {"w": "蛇头疔", "t": ""}]}]}]','jingmo-wenyan');
