INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3760wx','肓','1','huāng','月','7','','[{"pinyin": "huāng", "defs": [{"meaning": "(形声。从肉,亡声。本义:心脏与横隔膜之间的部位。中医认为这是药力达不到的部位) 同本义。", "cites": [{"t": "肓,心下鬲上也。", "b": "《说文》"}, {"t": "居肓之上膏之下。", "b": "《左传·成公十年》。注:“鬲也。按:心下膏,膏下肓,肓下鬲。”"}], "words": [{"w": "病入膏肓", "t": "古代医学称心尖的脂肪为膏。病极严重,难以医治。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3761wx','闱','1','wéi','门','7','','[{"pinyin": "wéi", "defs": [{"meaning": "(形声。从门,韦声。本义:古代宫室、宗庙的旁侧小门)。"}, {"meaning": "同本义。", "cites": [{"t": "闱,宫中之门也。", "b": "《说文》"}, {"t": "使其属守王闱。", "b": "《周礼·保氏》"}, {"t": "闱门,如今东西掖门。", "b": "《仪礼·士虞礼记》注"}], "words": [{"w": "闱闼", "t": "宫中小门"}, {"w": "闱门", "t": "古代宫室、宗庙的旁侧小门。"}]}, {"meaning": "后妃居处。", "cites": [{"t": "后正位宫闱,同体天王。", "b": "《后汉书》"}]}, {"meaning": "父母居室。", "cites": [{"t": "眷恋庭闱。", "b": "晋·束晳《补亡诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3762wx','闳','1','hóng','门','7','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从门,厷(gōng)声。本义:巷门)。"}, {"meaning": "同本义。", "cites": [{"t": "闳,巷门也。", "b": "《说文》"}, {"t": "入于闳。", "b": "《左传·成公十七年》"}, {"t": "及闳中。", "b": "《左传·昭公二十年》。注:“曲门中。”"}], "words": [{"w": "闳门", "t": "皇门。古代天子、诸侯等宫殿的左门。"}]}, {"meaning": "大,宏大。", "cites": [{"t": "其器圆以闳。", "b": "《礼记·月令》"}, {"t": "其语闳大不经,必先验小物。", "b": "《史记·孟子荀卿列传》"}, {"t": "闳言崇议。", "b": "《汉书·扬雄传下》"}], "words": [{"w": "闳言", "t": "博大的言论"}, {"w": "闳闳", "t": "宏大的样子"}, {"w": "闳诞", "t": "闳大荒诞,大而无当"}, {"w": "闳丽", "t": "宏伟壮丽。"}]}, {"meaning": "宽广,博大。", "cites": [{"t": "布濩闳泽。", "b": "司马相如《上林赋》"}, {"t": "人则乡唐虞之闳道。", "b": "《汉书·张山拊传》"}], "words": [{"w": "闳耀", "t": "广大光耀"}, {"w": "闳旷", "t": "宽宏豁达"}, {"w": "闳豁", "t": "宽敞"}, {"w": "闳廓", "t": "博大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3763wx','闵','1','mǐn','门','7','','[{"pinyin": "mǐn", "defs": [{"meaning": "(形声。从门,文声。本义:吊唁)。"}, {"meaning": "同本义。", "cites": [{"t": "闵,吊者在门也。", "b": "《说文》"}]}, {"meaning": "怜恤,哀怜。", "cites": [{"t": "闵予小子,遭家不造。", "b": "《诗·周颂·闵予小子》"}], "words": [{"w": "闵察", "t": "怜悯审察"}, {"w": "闵悼", "t": "怜恤哀悼"}, {"w": "闵悔", "t": "怜恤而痛悔"}, {"w": "闵笑", "t": "怜悯嘲笑。"}]}, {"meaning": "勉。黾勉。", "cites": [{"t": "予惟用闵于天越民。", "b": "《书·君奭》"}], "words": [{"w": "闵免", "t": "勤免不息。同黾勉。也作闵勉。"}]}, {"meaning": "忧虑。", "cites": [{"t": "宋人有闵其苗之不长而揠之者。", "b": "《孟子·公孙丑上》"}, {"t": "闵闵焉如农夫之望岁。", "b": "《左传·昭公三十二年》"}], "words": [{"w": "闵凶", "t": "忧伤的事。常指父母之丧"}, {"w": "闵悔", "t": "伤痛后悔"}, {"w": "闵急", "t": "令人担忧的严重情势。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3764wx','羌','1','qiāng','八','7','','[{"pinyin": "qiāng", "defs": [{"meaning": "(会意兼形声。从人,从羊,羊亦声。本义:羌族,古代西部民族之一)。"}, {"meaning": "同本义。", "cites": [{"t": "西戎牧羊人也。", "b": "《说文》"}, {"t": "庸蜀羌髳。", "b": "《书·牧誓》"}]}, {"meaning": "中国少数民族。主要聚居在四川省茂汶县、汶川县、松潘县境内。"}, {"meaning": "西戎 。中国古代西部的民族,分布在今甘肃、青海、四川一带,以游牧为主;和汉族杂处的部分羌人,逐渐从事农耕,与汉族融合。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3765wx','炀','1','yáng yàng','火','7','','[{"pinyin": "yáng", "defs": [{"meaning": "熔炼金属。", "cites": [{"t": "以一铁范…密布字印…持就火炀之。", "b": "宋·沈括《梦溪笔谈·活板》"}]}]}, {"pinyin": "yàng", "defs": [{"meaning": "(形声。从火,昜(yáng)声。本义:烘烤)。"}, {"meaning": "同本义。", "cites": [{"t": "古者民不知衣服,夏多积薪,冬则炀之。", "b": "《庄子》"}]}, {"meaning": "向火(取暖);烤火。", "cites": [{"t": "炀,炙燥也。", "b": "《说文》"}, {"t": "冬则羊裘解札,短褐不掩形而炀灶口。", "b": "《淮南子》"}, {"t": "若灶则不然,前之人炀,则后之人无从见也。", "b": "《战国策》"}]}, {"meaning": "炽热。", "cites": [{"t": "观天火之炎炀兮,听大壑之波声。", "b": "汉·东方朔《七谏》"}], "words": [{"w": "炀火", "t": "烈火"}, {"w": "炀旱", "t": "炎热干旱"}, {"w": "炀炀", "t": "火盛的样子"}, {"w": "炀和", "t": "融和;暖和。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3766wx','沣','1','fēng','氵','7','','[{"pinyin": "fēng", "defs": [{"meaning": "沣沛,雨水多的样子。", "cites": [{"t": "一奏之,有云从西北起;再奏之,暴雨亟至,大雨沣沛。", "b": "汉·应劭《风俗通》"}]}, {"meaning": "古水名 。源出陕西省咸阳市南秦岭,北流注入渭水。", "cites": [{"t": "漆沮既从,沣水攸同。", "b": "《书·禹贡》"}]}, {"meaning": "周代地名 。在今陕西省户县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3767wx','沅','1','yuán','氵','7','','[{"pinyin": "yuán", "defs": [{"meaning": "水名 。在湖南省西部。源出贵州省云雾山,上游称清水江,流经湖南,最后注入洞庭湖。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3768wx','沔','1','miǎn','氵','7','','[{"pinyin": "miǎn", "defs": [{"meaning": "水名 。汉水上源,在陕西省西南部。"}, {"meaning": "古州名。"}, {"meaning": "西魏置,北周废,故址在今湖北省汉川县东南。"}, {"meaning": "隋置。故治即今湖北省沔阳县。"}, {"meaning": "唐武德四年置,后废。故治即今湖北省武汉市汉阳区及汉阳县地。"}, {"meaning": "宋开禧三年平吴曦后置。故治在今陕西省略阳县。"}, {"meaning": "县名 。1964年改作勉县,在陕西省。"}, {"meaning": "水流满的样子。", "cites": [{"t": "沔彼流水,朝宗于海。", "b": "《诗·小雅·沔水》"}], "words": [{"w": "沔沔", "t": "水满荡漾的样子。"}]}, {"meaning": "沉迷。", "cites": [{"t": "流沔沉佚,遂往不返。", "b": "《史记·乐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3769wx','沤','1','ōu òu','氵','7','','[{"pinyin": "ōu", "defs": [{"meaning": "水中浮泡。", "cites": [{"t": "去年重阳不可说,南城夜半千沤发。", "b": "苏轼《九日黄楼作》"}]}, {"meaning": "水名 。耒水上源之一。发源于湖南省桂东县北,西南流入桂阳县(今汝城县)境后折而西流,至黄草坪与耒水南源会合。"}, {"meaning": "水鸟名。", "cites": [{"t": "海上之人有好沤鸟者,每旦之海上,从沤鸟游,沤鸟之至者百住而不止。", "b": "《列子·黄帝篇》"}]}]}, {"pinyin": "òu", "defs": [{"meaning": "长时间地浸泡。", "cites": [{"t": "沤,久渍也。", "b": "《说文》"}, {"t": "东门之池,可以沤麻。", "b": "《诗·陈风·东门之池》"}], "words": [{"w": "沤麻池", "t": "沤麻的水池"}, {"w": "沤纻", "t": "亦作“沤苎”。沤麻"}, {"w": "沤罨", "t": "长时间地浸泡并覆以泥,使之腐烂"}, {"w": "沤营", "t": "水浸茅草使柔韧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3770wx','沌','1','dùn zhuàn','氵','7','','[{"pinyin": "dùn", "defs": [{"meaning": "愚昧无知", "words": [{"w": "沌沌", "t": "昏昧无知的样子"}, {"w": "沌乱", "t": "混乱"}]}]}, {"pinyin": "zhuàn", "defs": [{"meaning": "水名 。在湖北省。上游为东荆河,至汉阳县沌口注入长江。", "cites": [{"t": "沌,水名,在江夏。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3771wx','沏','1','qī','氵','7','','[{"pinyin": "qī", "defs": [{"meaning": "用沸水冲、泡。", "cites": [{"t": "紫鹃,把你们的好茶沏碗我喝。", "b": "《红楼梦》"}], "words": [{"w": "我沏一杯茶", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3772wx','沚','1','zhǐ','氵','7','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从水,止声。本义:水中的小洲) 同本义。", "cites": [{"t": "小渚曰沚。", "b": "《说文》"}, {"t": "淹低沚兮京沚。", "b": "《楚辞·陶壅》。注:“京沚即高洲也。”"}, {"t": "宛在水中沚。", "b": "《诗·秦风·蒹葭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3773wx','汩','1','gǔ yù','氵','7','','[{"pinyin": "gǔ", "defs": [{"meaning": "(形声。从水,曰(yuè)声。本义:治水,疏通)。"}, {"meaning": "同本义。", "cites": [{"t": "汩,治水也。", "b": "《说文》"}, {"t": "决汩九川。", "b": "《国语·周语》"}, {"t": "不住汩鸿,师何以尚之?", "b": "《楚辞·屈原·天问》"}], "words": [{"w": "汩鸿", "t": "治理洪水"}, {"w": "汩越", "t": "治理。"}]}, {"meaning": "弄乱;扰乱。", "cites": [{"t": "我闻在昔,鲧洪水,汩陈其五行。", "b": "《书·洪范》"}, {"t": "与汩俱出。", "b": "《庄子·达生》"}], "words": [{"w": "汩乱", "t": "扰乱,混乱"}, {"w": "汩湮", "t": "惑乱湮灭"}, {"w": "汩陈", "t": "错乱陈列"}, {"w": "汩和", "t": "扰乱和气"}, {"w": "汩泥", "t": "搅浑泥沙。"}]}, {"meaning": "淹没;湮灭。", "cites": [{"t": "羲和,羲和,汝奚汩没于荒淫之波?", "b": "李白《日出入行》"}], "words": [{"w": "汩灭", "t": "形迹、印象等消灭;磨灭"}, {"w": "汩漱", "t": "淹没冲刷"}, {"w": "汩暗", "t": "湮没不明。"}]}, {"meaning": "汩都都(水流声);汩碌碌(象声词。多形容转动声)。"}]}, {"pinyin": "yù", "defs": [{"meaning": "疾行。", "cites": [{"t": "汩余若将不及兮,恐年岁之不吾与。", "b": "《楚辞》。王逸注:“汩,去貌,疾若水流也。”"}], "words": [{"w": "汩汩", "t": "水急流的样子"}, {"w": "汩徂", "t": "疾行"}, {"w": "汩话", "t": "水疾流的样子"}, {"w": "汩流", "t": "急流"}, {"w": "汩越", "t": "水涌的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3774wx','汨','1','mì','氵','7','','[{"pinyin": "mì", "defs": [{"meaning": "水名 。源出湘赣交界处,为汨罗江的上游。经古罗城又称罗水(一说汨水与罗水合流),下称汨罗江。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3775wx','沂','1','yí','氵','7','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从水,斤声。本义:沂水。古水名)。"}, {"meaning": "同本义。"}, {"meaning": "源出山东省曲阜县东南的尼山,西流至滋阳县合于泗水。"}, {"meaning": "大沂河古又称沂水。源出山东省的沂山,南流经沂水县、临沂县、郯城县境入江苏省。"}, {"meaning": "山名。又称东泰山 。在山东省沂水县北,临朐县南。"}, {"meaning": "古州名 。州治在今山东省临沂县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3776wx','汾','1','fén','氵','7','','[{"pinyin": "fén", "defs": [{"meaning": "水名,即汾河 。在山西省中部。长七百一十六公里,为黄河第二大支流。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3777wx','沨','1','fēng','氵','7','','[{"pinyin": "fēng", "defs": [{"meaning": "象声词，形容水声。形容乐声宛转悠扬。", "cites": [{"t": "大声沨沨，震摇六合，如乾之动，如雷之发。--宋·石介《庆历圣德诗》", "b": ""}]}, {"meaning": "宏大的声音。"}, {"meaning": "水声。", "cites": [{"t": "沨，水声。--《玉篇》", "b": ""}]}, {"meaning": "风声。", "cites": [{"t": "空谷来风，有气沨沨。--宋·司马光《潜虚》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3778wx','汴','1','biàn','氵','7','','[{"pinyin": "biàn", "defs": [{"meaning": "古水名 古称卞水,指今河南省 荥阳县西南索河。隋开通济渠,中间自今荥阳至开封的一段就是原来的汴水。"}, {"meaning": "古州名 。北周改梁州置。治所在浚仪(今开封市)。五代梁建都于此,升为开封府。五代·晋、汉、周以及北宋也以为都。常称汴梁,又称汴京。今为开封市的简称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3779wx','汶','1','mén wèn','氵','7','','[{"pinyin": "mén", "defs": [{"meaning": "心中昏暗不明"}]}, {"pinyin": "wèn", "defs": [{"meaning": "水名。"}, {"meaning": "今大汶水,又称“大汶河”,发源于山东省莱芜县北,古代本经东平县至梁山东南,流入济水。今主流西注东平湖,北入黄河。", "cites": [{"t": "浮于汶,达于济。", "b": "《书·禹贡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3780wx','沆','1','hàng','氵','7','','[{"pinyin": "hàng", "defs": [{"meaning": "大泽。", "cites": [{"t": "齐人谓湖曰沆。", "b": "郭缘生《述征记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3781wx','沩','1','wéi','氵','7','','[{"pinyin": "wéi", "defs": [{"meaning": "水名 。在湖南省宁乡县西,东北流注入湘江。", "cites": [{"t": "沩,水名,在新阳。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3782wx','泐','1','lè','氵','7','','[{"pinyin": "lè", "defs": [{"meaning": "石头因风化遇水而形成的裂纹。", "cites": [{"t": "泐,水石之理也。", "b": "《说文》"}]}, {"meaning": "裂开;解裂。", "cites": [{"t": "石有时以泐,水有时以凝,有时以泽,此天时也。", "b": "《周礼·考工记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3783wx','怃','1','wǔ','忄','7','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从心,无声。本义:抚爱)。"}, {"meaning": "同本义。", "cites": [{"t": "怃,爱也。", "b": "《说文》"}, {"t": "怃,抚也。", "b": "《尔雅》"}]}, {"meaning": "哀怜 。"}, {"meaning": "怅然失意的样子。", "cites": [{"t": "应之者咸怃然。", "b": "唐·柳宗元《柳河东集》"}, {"t": "君怃然曰。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "怃然", "t": "失意;不痛快。"}]}, {"meaning": "惊愕的样子。", "cites": [{"t": "表怃然为骇。", "b": "《后汉书》"}]}, {"meaning": "媚好的样子。", "cites": [{"t": "又为妇画眉,长安中传张京兆眉怃。", "b": "《汉书·张敞传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3784wx','怄','1','òu','忄','7','','[{"pinyin": "òu", "defs": [{"meaning": "逗弄。", "cites": [{"t": "老太太也会怄他,时常他弄了东西来孝敬,究竟又吃不多儿。", "b": "《红楼梦》"}]}, {"meaning": "嘲笑。", "cites": [{"t": "奴才们背地里还怄姑娘不害羞。", "b": "《儿女英雄传》"}], "words": [{"w": "你别故意怄我;怄人", "t": "使人生气,不愉快。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3785wx','忡','1','chōng','忄','7','','[{"pinyin": "chōng", "defs": [{"meaning": "(形声。从心,中声。忧愁的样子) 同本义。", "cites": [{"t": "忡,忧也。", "b": "《说文》"}, {"t": "忧心有忡。", "b": "《诗·邶风·击鼓》"}, {"t": "忧心忡忡。", "b": "《诗·召南·草虫》"}, {"t": "极劳心兮忡忡。", "b": "《楚辞·云中君》"}], "words": [{"w": "忡然", "t": "忧愁的样子"}, {"w": "忡怅", "t": "忧伤惆怅。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3786wx','忤','1','wǔ','忄','7','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从心,午声。本义:抵触,不顺从)。"}, {"meaning": "同本义。", "cites": [{"t": "复忤宾客。", "b": "唐·李朝威《柳毅传》"}, {"t": "触忤当死。", "b": "清·张廷玉《明史》"}], "words": [{"w": "忤权", "t": "不屈服于权贵"}, {"w": "忤物", "t": "触犯人;与人不合"}, {"w": "忤怨", "t": "抵触而生怨"}, {"w": "忤恨", "t": "违逆;反对"}, {"w": "忤意", "t": "违逆心意"}, {"w": "忤嫚", "t": "忤慢。违抗怠慢"}, {"w": "忤触", "t": "触犯"}, {"w": "忤鳞", "t": "直言犯上。"}]}, {"meaning": "触动。", "cites": [{"t": "临风悼亡,忤愁心,匹鸟河洲上。", "b": "明·汪道昆《洛水悲》"}]}, {"meaning": "交错。", "cites": [{"t": "阴阳散忤。", "b": "《春秋元命包》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3787wx','忾','1','kài','忄','7','','[{"pinyin": "kài", "defs": [{"meaning": "(形声。从心,气声。 本义:叹息,感慨)。"}, {"meaning": "同本义。", "cites": [{"t": "忾,大息也。", "b": "《说文》"}, {"t": "忾我寤叹。", "b": "《诗·曹风·下泉》"}, {"t": "忾然心有闻乎其叹息之声。", "b": "《礼记·祭义》"}, {"t": "见魏武帝遗令,忾然叹息,伤怀者久之。", "b": "《文选·陆机·吊魏武帝文》"}]}, {"meaning": "愤恨,愤怒。", "cites": [{"t": "诸侯敌王所忾而献其功。", "b": "《左传·文公四年》"}], "words": [{"w": "忾敌", "t": "同仇敌忾"}, {"w": "忾愤", "t": "愤怒,愤恨。"}]}, {"meaning": "满。", "cites": [{"t": "身以及身,子以及子,妃以及妃,君行此三者,则忾乎天下矣。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3788wx','怅','1','chàng','忄','7','','[{"pinyin": "chàng", "defs": [{"meaning": "(形声。从心,长声。本义:因失意而不痛快) 同本义。", "cites": [{"t": "恨,望恨也。", "b": "《说文》"}, {"t": "陈涉少时,尝与人佣耕,辍耕之垄上,怅恨久之:“苟富贵,无相忘。”", "b": "《史记·陈涉世家》"}, {"t": "怅寥廓,向苍茫大地,谁主沉浮。", "b": "毛泽东《沁园春·长沙》"}], "words": [{"w": "惆怅", "t": "伤感;失意"}, {"w": "怅况", "t": "恍惚"}, {"w": "怅触", "t": "惆怅感触。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3789wx','忻','1','xīn','忄','7','','[{"pinyin": "xīn", "defs": [{"meaning": "(形声。从心,斤声。本义:启发)。"}, {"meaning": "同本义。", "cites": [{"t": "忻,闿也。", "b": "《说文》"}, {"t": "善者,忻民之善,闭民之恶。", "b": "《司马法》"}, {"t": "姜原出野,见巨人迹,心忻然说,欲践之。", "b": "《史记·周本纪》"}]}, {"meaning": "明察。", "cites": [{"t": "忻,察也。", "b": "《玉篇》"}]}, {"meaning": "假借为“欣”。心喜。", "cites": [{"t": "姜原出野,见巨人迹,心忻然悦。", "b": "《史记·周本纪》"}, {"t": "忻忻然常自以为治。", "b": "《淮南子·览冥》。注:“得意之貌也。”"}], "words": [{"w": "忻幸", "t": "欣幸,欣喜而庆幸"}, {"w": "忻悦", "t": "欣喜"}, {"w": "忻然", "t": "喜悦貌;愉快貌"}, {"w": "忻慰", "t": "欣慰"}, {"w": "忻戚", "t": "悲喜"}, {"w": "忻悚", "t": "喜悦与惶恐。"}]}]}]','jingmo-wenyan');
