('3791wx','怆','1','chuàng','忄','7','','[{"pinyin": "chuàng", "defs": [{"meaning": "(形声。从心,仓声。本义:悲伤)。"}, {"meaning": "同本义。", "cites": [{"t": "怆,伤也。", "b": "《说文》"}, {"t": "怆,悲也。", "b": "《广雅》"}, {"t": "必有悽怆之心。", "b": "《礼记·祭义》"}], "words": [{"w": "怆慌", "t": "悲伤慌张"}, {"w": "怆惶", "t": "悲切惊惶"}, {"w": "怆恻", "t": "悲伤ň恻"}, {"w": "怆怆", "t": "悲痛哀伤"}, {"w": "怆悢", "t": "悲愤忧伤。"}]}]}]','jingmo-wenyan');
