('3793wx','忸','1','niǔ','忄','7','','[{"pinyin": "niǔ", "defs": [{"meaning": "(形声。从心,丑声。本义:羞惭的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "忸,惭也。", "b": "《集韵》"}, {"t": "颜厚有忸怩。", "b": "《书·五子之歌》"}], "words": [{"w": "忸忸怩怩", "t": "羞愧的样子"}, {"w": "忸恨", "t": "愧恨。"}]}, {"meaning": "习惯。", "cites": [{"t": "忸之以庆赏。", "b": "《荀子·议兵》"}], "words": [{"w": "忸忖", "t": "习以为常。也作忸忖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3794wx','诂','1','gǔ','讠','7','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。从言,从古,古亦声。本义:用通行的话解释古代语言文字或方言字义) 同本义。", "cites": [{"t": "诂,训故言也。", "b": "《说文》"}]}, {"meaning": "后汉桓谭传郑兴传注皆引说文、训古言也。", "cites": [{"t": "诂者,古也。古今异言,通之使人知也。", "b": "《毛诗·周南·关睢》诂训传疏"}, {"t": "诂,训故言也。", "b": "《后汉书·桓谭传》注"}, {"t": "雄少而好学,不为章句,训诂通而已,博览无所不见。", "b": "《汉书·扬雄传》"}], "words": [{"w": "诂解", "t": "用当代语言解释古语"}, {"w": "诂训", "t": "解释古书的文义。也用以指古言古义。同故训。"}]}, {"meaning": "古言古义;词语的意义。", "cites": [{"t": "同字而异诂,同辞而异义。", "b": "陆游《万卷楼记》"}], "words": [{"w": "诂释", "t": "古言古语的解释。"}]}]}]','jingmo-wenyan');
