('3795wx','诃','1','hē','讠','7','','[{"pinyin": "hē", "defs": [{"meaning": "（訶）。"}, {"meaning": "〔～子〕青果,常绿乔木，果实像橄榄，可入药。亦称“藏（。"}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3796wx','诅','1','zǔ','讠','7','','[{"pinyin": "zǔ", "defs": [{"meaning": "(形声。从言,且(jū)声。本义:诅咒)。"}, {"meaning": "同本义。", "cites": [{"t": "诅,詶也。", "b": "《说文》"}, {"t": "否则厥口诅祈。", "b": "《书·无逸》。疏:“请神加殃谓之诅。”"}, {"t": "以诅射颍考叔者。", "b": "《左传·隐公十一年》"}, {"t": "出此三物,以诅尔斯。", "b": "《诗·小雅·巧言》"}, {"t": "一人祝之,一国诅之,一祝不胜万诅,国亡,不亦宜乎?", "b": "《论衡》"}], "words": [{"w": "诅让", "t": "咒骂责备"}, {"w": "诅詈", "t": "诅咒;咒骂"}, {"w": "诅恨", "t": "诅咒怨恨"}, {"w": "诅书", "t": "诅咒的文字"}, {"w": "诅魇", "t": "用诅咒来害人"}, {"w": "诅祝", "t": "祈求鬼神加害于敌对之人"}, {"w": "诅师", "t": "巫师"}, {"w": "诅楚文", "t": "又称“诅楚”。指秦王祈求天神克楚兵,收复其边城。"}]}, {"meaning": "盟誓,特指就小事或往事起誓。", "cites": [{"t": "掌盟诅。", "b": "《周礼》。郑玄注:“盟诅,主于要誓,大事曰盟,小事曰诅。”"}], "words": [{"w": "诅盟", "t": "誓约"}, {"w": "诅誓", "t": "盟誓。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3797wx','诋','1','dǐ','讠','7','','[{"pinyin": "dǐ", "defs": [{"meaning": "(形声。从言,氐(dǐ)声。本义:诬蔑,毁谤)。"}, {"meaning": "同本义。", "cites": [{"t": "诋,毁也。", "b": "《广雅·释诂二》"}, {"t": "诋毁也,辱也。", "b": "《汉书·刘向传》注"}, {"t": "历诋公卿大臣。", "b": "《汉书·息夫躬传》"}, {"t": "虽有诋讦之民,无所依矣。", "b": "《墨子·修身》"}], "words": [{"w": "诋诟", "t": "诬蔑;毁谤"}, {"w": "诋讦", "t": "诋毁攻击"}, {"w": "诋辱", "t": "毁谤侮辱。"}]}, {"meaning": "谴责。", "cites": [{"t": "露表告将入关,因诋宦竖柄朝,垢蠹纪纲。", "b": "《新唐书》"}]}, {"meaning": "骂。", "cites": [{"t": "弟闻得世兄也诋尽流俗,性情中另有一番见解。", "b": "《红楼梦》"}, {"t": "诋大酋当死。", "b": "宋·文天祥《指南录·后序》"}]}, {"meaning": "欺。", "cites": [{"t": "朔擅诋欺天子从官,当弃市。", "b": "《汉书》"}]}, {"meaning": "抵赖,抵讳。用同“抵”。", "cites": [{"t": "上责(史)万岁,万岁诋谰。", "b": "《资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3798wx','诌','1','zhōu','讠','7','','[{"pinyin": "zhōu", "defs": [{"meaning": "信口胡说,编瞎话。", "cites": [{"t": "出个题目,让我诌去;诌了来,替我改正。", "b": "《红楼梦》"}], "words": [{"w": "诌谎", "t": "说谎"}, {"w": "顺诌", "t": "顺嘴胡编乱造"}, {"w": "诌诗", "t": "信口乱凑的诗。"}]}, {"meaning": "固执任性。", "cites": [{"t": "好诌孩子,别要睡倒。起来往后头去。", "b": "《醒世姻缘传》"}], "words": [{"w": "诌札", "t": "凶狠;顽劣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3799wx','诏','1','zhào','讠','7','','[{"pinyin": "zhào", "defs": [{"meaning": "(会意兼形声。从言从召,召亦声。“言”是言论,“召”是召唤。本义:告知,告诉)。"}, {"meaning": "同本义 。先秦没有此字,秦汉才出现,多用于上告下。", "cites": [{"t": "诏,告也。", "b": "《说文新附》"}, {"t": "负剑辟咡诏之,出入有诏于国。", "b": "《礼记·曲礼》"}, {"t": "上诏书者。", "b": "蔡邕《独断》。注:“诏,诰也。有三品。”"}, {"t": "以诏后世。", "b": "《穆天子传》"}, {"t": "于是上乃使使持节诏将军。", "b": "《史记·绛侯周勃世家》"}, {"t": "集谢庄少年之精技击者而诏之曰。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "诏众", "t": "告诉众人"}, {"w": "诏赞", "t": "告知和赞助。"}]}, {"meaning": "教导;告诫。", "cites": [{"t": "夫为人父者,必能诏其子。", "b": "《庄子·盗跖》"}, {"t": "多分其教诏。", "b": "《吕氏春秋·审分》"}], "words": [{"w": "诏导", "t": "教导"}, {"w": "诏诲", "t": "告诫教导"}, {"w": "诏侑", "t": "劝告"}, {"w": "诏志", "t": "教导立身养志"}, {"w": "诏相", "t": "教导行大礼的言行。"}]}, {"meaning": "皇帝下达命令。", "cites": [{"t": "诏使儒卿。", "b": "《汉书·李广苏建传》"}, {"t": "优诏奖瑞。", "b": "《明史》"}, {"t": "诏赐抚臣。", "b": "《聊斋志异·促织》"}], "words": [{"w": "诏求", "t": "皇帝下令征求"}, {"w": "诏征", "t": "皇帝下令征召"}, {"w": "诏选", "t": "皇帝下令任命"}, {"w": "诏用", "t": "皇帝下令任用。"}]}, {"meaning": "征召。", "cites": [{"t": "明诏期,前后农夫,以时均修焉,…。", "b": "《管子》"}], "words": [{"w": "诏期", "t": "征召的日期。"}]}, {"meaning": "召见。", "cites": [{"t": "诏伊尹于亳(bó)郊兮。", "b": "《后汉书·冯衍传》"}]}, {"meaning": "宣扬。", "cites": [{"t": "未可明诏大号。", "b": "龚自珍《病梅馆记》"}]}, {"meaning": "报告。", "cites": [{"t": "按周礼诸职凡言诏者,皆下告上之辞。", "b": "朱骏声《说文通训定声》"}, {"t": "不以诏。", "b": "《礼记·檀弓》"}, {"t": "虽诏于天子无北面。", "b": "《礼记·学记》"}, {"t": "故礼有摈诏。", "b": "《礼记·礼器》"}, {"t": "诏西皇使涉予。", "b": "《楚辞·离骚》"}]}, {"meaning": "诏书,皇帝颁发的命令文告。", "cites": [{"t": "上尊号王为秦皇。命为制,令为诏。", "b": "《史记·秦始皇本纪》"}, {"t": "非有诏不得上。", "b": "《战国策·燕策》"}, {"t": "诏即下。", "b": "清·梁启超《谭嗣同传》"}, {"t": "捧诏恸哭。", "b": ""}, {"t": "出密诏示之。", "b": ""}], "words": [{"w": "下诏", "t": "颁发诏书"}, {"w": "诏板", "t": "即诏书"}, {"w": "诏记", "t": "皇帝的手令"}, {"w": "诏条", "t": "诏书中所列的条文"}, {"w": "诏黄", "t": "以黄色纸书写发布的诏令。"}]}, {"meaning": "古代西南少数民族首领的称号。", "cites": [{"t": "南诏蛮,本乌蛮之别种也,姓蒙氏。蛮谓王为“诏”,自言哀牢之后。", "b": "《旧唐书》"}], "words": [{"w": "诏家", "t": "古代少数民族首领的称号。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3800wx','诒','1','yí dài','讠','7','','[{"pinyin": "yí", "defs": [{"meaning": "（詒）。"}, {"meaning": "传给：～训。"}, {"meaning": "赠与，给与：“～尔多福。”。"}]}, {"pinyin": "dài", "defs": [{"meaning": "（詒）。"}, {"meaning": "欺诈：骨肉相～。～骗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3801wx','孜','1','zī','子','7','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从攴(pū),子声。攴,击打。不断敲击自己,才能努力不懈,故从攴。本义:双音词“孜孜”,勤勉、努力不懈的样子)。"}, {"meaning": "同本义。常叠用。亦作孳孳。", "cites": [{"t": "孜,汲汲也。", "b": "《说文》"}, {"t": "孜孜无怠。", "b": "《周书》"}, {"t": "子思日孜孜。", "b": "《皋·陶谟》"}, {"t": "群公孜孜。", "b": "《汉书·成帝纪》"}, {"t": "圣上犹孜孜靡忒。", "b": "何晏《景福殿赋》"}, {"t": "孜孜焉,唯进修是急。", "b": "清·刘开《问说》"}], "words": [{"w": "孜孜不已", "t": "孜孜不懈。勤奋努力,不知疲倦"}, {"w": "孜孜汲汲", "t": "勤勉不懈,心情急切。"}]}, {"meaning": "高兴的样子。", "cites": [{"t": "只见他喜孜孜俏脸儿笑捻。", "b": "《元曲选·白朴·东墙记剧五》"}], "words": [{"w": "乐孜孜;美孜孜", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3802wx','陇','1','lǒng','阝','7','','[{"pinyin": "lǒng", "defs": [{"meaning": "(形声。从阜(fù),表示与地势的高低上下有关,龙声。本义:古地名。在今甘肃东部)。"}, {"meaning": "即陇山。绵延于陕西、甘肃交界的地方。", "cites": [{"t": "陇,天水大阪也。", "b": "《说文》。沈涛注:“今本合三处互订,古本当作‘陇山,天水阪、大阪也。’”"}]}, {"meaning": "田埂。", "cites": [{"t": "席陇亩而荫庇。", "b": "《战国策·赵策三》"}, {"t": "然羽非有尺寸,乘势起陇亩之中。", "b": "《史记·项羽本纪赞》"}], "words": [{"w": "陇邱", "t": "田垄;土丘"}, {"w": "陇亩", "t": "田野,田亩。"}]}, {"meaning": "凑起,集合。", "cites": [{"t": "洪涟陇蹙。", "b": "鲍照《登大雷岸与妹书》"}]}, {"meaning": "盛,多。", "cites": [{"t": "日中而阳陇为重阳。", "b": "《灵枢·营卫生会》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3803wx','陀','1','tuó','阝','7','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从阜(fù),它声。从阜,与山有关。本义:倾斜不平的样子) 同本义。", "cites": [{"t": "罢池陂陀,下属江河。", "b": "汉·司马相如《子虚赋》"}]}, {"meaning": "山冈。", "cites": [{"t": "藉草各小憩,侧身复登陀。", "b": "元·袁桷《次韵伯宗同行至上都》"}]}, {"meaning": "团状物。", "cites": [{"t": "把棍子望小妖头上砑了一砑,可怜就砑得像个肉陀。", "b": "《西游记》"}]}, {"meaning": "沙陀的简称。", "cites": [{"t": "陀,沙陀,后唐始兴之地。", "b": "《正字通》"}]}, {"meaning": "形容数量很少。", "cites": [{"t": "黄菊东篱栽数科,野菜西山锄几陀。", "b": "元·曾瑞《端正好》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3804wx','陂','1','bēi pí pō','阝','7','','[{"pinyin": "bēi", "defs": [{"meaning": "(形声。从阜,皮声。字亦作坡。本义:山坡;斜坡)。"}, {"meaning": "同本义。", "cites": [{"t": "陂,阪也。", "b": "《说文》"}, {"t": "百姓曼衍淫荒之陂。", "b": "《淮南子·俶真》"}, {"t": "陂南陂北鸦阵黑,舍西舍东枫叶赤。", "b": "宋·陆游《思故山》"}]}, {"meaning": "池塘。", "cites": [{"t": "毋漉陂池。", "b": "《礼记·月令》。注:“畜水曰陂。”"}, {"t": "陂唐污庳。", "b": "《国语·周语》"}, {"t": "夫寻常之污,不能溉陂泽。(小水坑里的水,不能灌满大的池泽。)", "b": "《盐铁论·贫富》"}], "words": [{"w": "陂塘", "t": "水塘"}, {"w": "陂池", "t": ""}]}, {"meaning": "湖泊。", "cites": [{"t": "十顷之陂。", "b": "《淮南子·说林》"}, {"t": "后又穿长安城,引内沣水注第中大陂以行船。", "b": "《汉书》"}]}, {"meaning": "边际;旁边。", "cites": [{"t": "彼泽(水聚集的地方)之陂,有蒲与荷。", "b": "《诗·陈风·泽陂》"}, {"t": "故滨于东海之陂。", "b": "《国语·越语》。注:“崖也。”"}, {"t": "腾雨师,洒路陂(旁)。", "b": "《汉书·礼乐志》"}]}]}, {"pinyin": "pí", "defs": [{"meaning": "——“黄陂”(Huángpí):县名,在湖北。"}]}, {"pinyin": "pō", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3805wx','陉','1','xíng','阝','7','','[{"pinyin": "xíng", "defs": [{"meaning": "山脉中断的地方。", "cites": [{"t": "山绝陉。", "b": "《尔雅·释山》。注:“连山中断绝。”"}, {"t": "盘互长干有绝陉,并包佳丽入江亭。", "b": "宋·王安石《雨花台》"}, {"t": "赵(希)与之陉,合军曲阳,攻取丹丘、华阳、鸱之塞。", "b": "《史记·赵世家》。集解:“常山有井陉,中山有苦陉。”"}, {"t": "太行山首始于河内,北至幽州,凡有八陉,是山凡中断皆曰陉。", "b": "《述征记》"}], "words": [{"w": "陉岘", "t": "山谷与山岭"}, {"w": "陉阻", "t": "断崖险碍的地方。"}]}, {"meaning": "灶边承放器物处的形状、样子。", "cites": [{"t": "祀灶之礼,设主于灶陉。", "b": "《礼记·月令》郑玄注"}]}, {"meaning": "斜坡。", "cites": [{"t": "膺峭袘,腹陉阻。", "b": "马融《长笛赋》"}]}, {"meaning": "古地名。"}, {"meaning": "春秋楚地,在河南省郾城县境。"}, {"meaning": "战国韩地,在今山西省曲沃县境。"}, {"meaning": "春秋周地,在今河南省沈阳县西北三十里。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3806wx','妍','1','yán','女','7','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。小篆字形。从女,幵(jiān)声。本义:巧慧)。"}, {"meaning": "同本义。", "cites": [{"t": "妍,技也。一曰慧也。", "b": "《说文》。按,慧巧之意。"}], "words": [{"w": "妍手", "t": "妙手。"}]}, {"meaning": "美丽。", "cites": [{"t": "浪迹无妍蚩。", "b": "江淹《杂体诗》。注:“犹美恶也。”"}, {"t": "妍蚩好恶,可得而言。", "b": "陆机《文赋序》"}, {"t": "日高日上,日上日妍。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "妍花", "t": "娇美的花"}, {"w": "妍森", "t": "美丽茂盛"}, {"w": "妍度", "t": "美丽的外表"}, {"w": "妍芳", "t": "美丽的花卉"}, {"w": "妍状", "t": "美丽的形态"}, {"w": "妍美", "t": "美丽"}, {"w": "妍倩", "t": "美丽"}, {"w": "妍影", "t": "美丽的影像"}, {"w": "妍丑", "t": "美和丑"}, {"w": "妍柔", "t": "美丽的风光。"}]}, {"meaning": "美好。", "cites": [{"t": "面丑心妍,利居众后,责在人先。", "b": "唐·韩愈《送穷文》"}], "words": [{"w": "妍好", "t": "美好"}, {"w": "妍妙", "t": "美好"}, {"w": "妍和", "t": "美好和煦"}, {"w": "妍姿", "t": "美好的姿容"}, {"w": "妍容", "t": "美好的容貌"}, {"w": "妍淑", "t": "美好"}, {"w": "妍森", "t": "美好繁盛"}, {"w": "妍语", "t": "美好的话语"}, {"w": "妍洁", "t": "美好洁净"}, {"w": "妍泽", "t": "美好润泽"}, {"w": "妍稳", "t": "美好妥贴"}, {"w": "妍谈", "t": "美好的谈论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3807wx','妩','1','wǔ','女','7','','[{"pinyin": "wǔ", "defs": [{"meaning": "(形声。从女,无声。本义:媚)。"}, {"meaning": "同本义。", "cites": [{"t": "妩,媚也。", "b": "《说文》"}]}, {"meaning": "美女。", "cites": [{"t": "妩,美女。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3808wx','妪','1','yǔ yǔ','女','7','','[{"pinyin": "yǔ", "defs": [{"meaning": "以体相温。", "cites": [{"t": "羽者妪伏。", "b": "《淮南子·原道》。注:“以气剖卵也。”"}, {"t": "煦妪覆育万物。", "b": "《礼记·乐记》。注:“气曰煦,体曰妪。”"}, {"t": "柳下惠妪不逮门之女。", "b": "《诗·巷伯传》"}, {"t": "太子曰:颜子缩屋称贞,柳下妪而不乱,未若此翁白首不娶者也。", "b": "《北齐书》"}], "words": [{"w": "妪伏", "t": "鸟类以体孵卵。"}]}, {"meaning": "养育;抚育。", "cites": [{"t": "以声华呕符妪掩万民百姓。", "b": "《淮南子》"}], "words": [{"w": "妪育", "t": "生育抚养"}, {"w": "妪煦", "t": "生养覆育"}, {"w": "妪拊", "t": "抚恤。"}]}]}, {"pinyin": "yǔ", "defs": [{"meaning": "(形声。从女,区声。本义:母亲,妈妈)。"}, {"meaning": "同本义。", "cites": [{"t": "妪,母也。", "b": "《说文》"}, {"t": "老妪夜哭。", "b": "《史记》"}, {"t": "东海莫贤知其母,延年兄弟五人皆有吏材,至大官。东海号曰:“万石严妪”。", "b": "《汉书》"}]}, {"meaning": "老年妇女。", "cites": [{"t": "妪,今俗称老妇曰妪。", "b": "《正字通》"}, {"t": "颜夫人者,妪盈女也,国色也。", "b": "《公羊传》"}]}, {"meaning": "妇女的通称。", "cites": [{"t": "从少妪三十。", "b": "《南史·邓郁传》"}, {"t": "家有老妪,尝居于此。", "b": "明·归有光《项脊轩志》"}, {"t": "独与妪居。", "b": "清·周容《芋老人传》"}]}, {"meaning": "又。", "cites": [{"t": "命妪煮芋。", "b": ""}, {"t": "乃火尔妪。", "b": ""}, {"t": "妪煮芋进。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3809wx','妣','1','bǐ','女','7','','[{"pinyin": "bǐ", "defs": [{"meaning": "(形声。从女,比声。本义:母亲)。"}, {"meaning": "母亲的通称。", "cites": [{"t": "母为妣。", "b": "《尔雅·释亲》。疏:“妣,媲也,媲匹于父。”"}, {"t": "遇其妣。", "b": "《易·小过》"}]}, {"meaning": "已故的母亲。", "cites": [{"t": "妣,殁母也。", "b": "《说文》"}, {"t": "百姓如丧考妣。", "b": "《虞书》"}, {"t": "以享先妣。", "b": "《周礼·大司乐》"}, {"t": "王母曰皇祖妣。", "b": "《礼记·曲礼下》"}, {"t": "先妣抚之甚厚。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "妣考", "t": "亡母与亡父"}, {"w": "先妣;如丧考妣", "t": ""}]}, {"meaning": "祖母和祖母辈以上的女性祖先。", "cites": [{"t": "似绩妣祖。", "b": "《诗·小雅·斯干》"}], "words": [{"w": "妣祖", "t": "先妣和先祖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3810wx','妊','1','rèn','女','7','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从女,壬声。) 同本义。", "cites": [{"t": "妊,孕也。", "b": "《说文》"}, {"t": "今诸怀妊者。", "b": "《后汉书·章帝纪》"}], "words": [{"w": "妊娘", "t": "孕妇"}, {"w": "妊身", "t": "怀孕"}, {"w": "妊娠", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3811wx','妗','1','jìn','女','7','','[{"pinyin": "jìn", "defs": [{"meaning": "舅母。舅父的妻子。", "cites": [{"t": "儿少受舅妗抚育,尚无寸报。", "b": "《聊斋志异·公孙九娘》"}], "words": [{"w": "舅妗;妗娘", "t": "妗子,舅母"}, {"w": "妗妗", "t": "妗子,舅母"}, {"w": "妗奶奶", "t": "对父辈舅母的称呼"}, {"w": "妗婆", "t": "父亲或母亲的舅母,即舅婆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3812wx','妫','1','guī','女','7','','[{"pinyin": "guī", "defs": [{"meaning": "姓", "cites": [{"t": "妫,虞舜居妫汭,因以为氏。", "b": "《说文》"}]}, {"meaning": "即妫水 。中国山西省西南部的一条小河,向西流入黄河"}, {"meaning": "古州名。辖境相当于今河北省赤城、怀来等地"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3813wx','妞','1','niū','女','7','','[{"pinyin": "niū", "defs": [{"meaning": "[方言] 女孩子", "cites": [{"t": "这人叫黑妞,是白妞的妹子。", "b": "《老残游记》"}, {"t": "这小妞带点子这个干么呀?卖唱的?", "b": "杨沫《青春之歌》"}], "words": [{"w": "妞儿", "t": "女儿；女孩子"}, {"w": "傻妞", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3814wx','姒','1','sì','女','7','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从女,以声。本义:古代兄弟之妻年长者)。"}, {"meaning": "同本义。古以兄妻为姒,弟妻为娣;相谓亦曰姒。弟妻称兄妻为姒。", "cites": [{"t": "娣妇谓长妇为姒妇。", "b": "《尔雅·释亲》"}, {"t": "吾不以妾为姒。", "b": "《左传·成公十一年》。注:“昆弟之妻,相谓为姒。”"}, {"t": "少妇谓长妇曰姒,言其先来已所当法似也。", "b": "《释名·释亲属》"}], "words": [{"w": "姒娣", "t": "妯娌"}, {"w": "姒妇", "t": "古代弟之妻称兄之妻为姒妇。"}]}, {"meaning": "古代同夫诸妾称长者曰姒,幼者曰娣。", "cites": [{"t": "女子同出,谓先生为姒,后生为娣。", "b": "《尔雅·释亲》。郭璞注:“同出,谓俱嫁事一夫。”"}]}, {"meaning": "古时称姊为姒。", "cites": [{"t": "鲁公乘姒者,鲁公乘子皮之姒也。", "b": "汉·刘向《列女传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3815wx','妤','1','yú','女','7','','[{"pinyin": "yú", "defs": [{"meaning": "——“婕妤”(jiéyú):汉代宫中女官名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3816wx','邵','1','shào','阝','7','','[{"pinyin": "shào", "defs": [{"meaning": "古地名。", "cites": [{"t": "邵,晋邑也。", "b": "《说文》"}, {"t": "戌郫邵。", "b": "《左传·襄公二十三年》"}]}, {"meaning": "春秋晋邑。在今河南省济源县西,山西省垣曲县东。后魏改为邵郡,后周改为邵州。"}, {"meaning": "古州名 。相当于今福建省邵武县等地。"}, {"meaning": "古郡名 。即邵陵郡,相当于今湖南省邵阳市及新邵、邵阳等县地。"}, {"meaning": "水名 。邵水发源龙山。西流会桐江、檀江,在湖南省宝庆县东注入资水。"}, {"meaning": "姓(《汉书》作“召”)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3817wx','劭','1','shào','力','7','','[{"pinyin": "shào", "defs": [{"meaning": "高尚;美好。", "cites": [{"t": "邵,高也。从卩,召声。", "b": "《说文》"}, {"t": "劭,美也。又高也。", "b": "《小尔雅》"}, {"t": "董仲舒之才之邵也。", "b": "《法言·修身》"}, {"t": "年弥高而德弥劭。", "b": "扬雄《法言·孝至》"}], "words": [{"w": "年高德劭;劭美", "t": "美好"}, {"w": "劭令", "t": "完善美好。"}]}, {"meaning": "(形声。从力,召声。本义:勉励) 同本义。", "cites": [{"t": "先帝劭农,薄其租税。", "b": "《汉书·成帝纪》"}], "words": [{"w": "劭农", "t": "劝农"}, {"w": "劭劝", "t": "劝勉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3818wx','刭','1','jǐng','刂','7','','[{"pinyin": "jǐng", "defs": [{"meaning": "(形声。从刀,巠声。本义:砍头;割颈) 同本义。", "cites": [{"t": "刭,刑也。", "b": "《说文》。段注:“刭,谓断头也。”"}, {"t": "刭而独鹿弃之法。", "b": "《荀子·成相》"}, {"t": "北乡自刭。", "b": "《史记·魏公子列传》"}, {"t": "果北乡自刭。", "b": ""}, {"t": "句卑布裳,刭而裹之,藏其身,而以其首免。", "b": "《左传·定公四年》。杜预注:“司马已死,刭取其首。”"}, {"t": "是岁,入有自刭死以其头献者。", "b": "《韩非子·内储说上》"}], "words": [{"w": "刭拔", "t": "刭杀"}, {"w": "刭杀", "t": "斩杀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3819wx','甬','1','yǒng','用','7','','[{"pinyin": "yǒng", "defs": [{"meaning": "(形声。从兯(hàn),用声。小篆字形。兯,象花蓓蕾之形。①本义:草木花结蓓蕾的样子。②钟柄)。"}, {"meaning": "古代钟柄名。", "cites": [{"t": "甬本是钟,乃后人用字变迁,缩小其义为钟柄。", "b": "杨树达《积微居小学述林》"}]}, {"meaning": "甬江 。在浙江,流过宁波。"}, {"meaning": "宁波市的别称 。因境内有甬江而得名。"}, {"meaning": "古斗斛一类量器。", "cites": [{"t": "谷口铜甬,容十斗,重四十斤。", "b": "《集古录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3820wx','邰','1','tái','阝','7','','[{"pinyin": "tái", "defs": [{"meaning": "古国名。", "cites": [{"t": "按,尧封稷于邰,而国姜姓他处,至武王又封神农后于焦。邰在今陕西乾州武功县南在今陕西省武功县西南。", "b": ""}], "words": [{"w": "邰弃", "t": "即后稷。古代周族始祖。传说有邰氏之女姜嫄见上帝足迹而履其拇,怀孕而生。"}]}, {"meaning": "地名。也作“台” 。在今山东省费县南。", "cites": [{"t": "莒人伐我东鄙,围邰。", "b": "《谷梁传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3821wx','纭','1','yún','纟','7','','[{"pinyin": "yún", "defs": [{"meaning": "(形声。从糸(mì),云声。双音词“纷纭”。本义:多盛的样子) 同本义。", "cites": [{"t": "纭,数乱也。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3822wx','纰','1','pī pí','纟','7','','[{"pinyin": "pī", "defs": [{"meaning": "疏忽;谬误。", "cites": [{"t": "五者一物纰缪。", "b": "《礼记·大传》"}], "words": [{"w": "纰越", "t": "过失,错误"}, {"w": "纰妄", "t": "谬误虚妄"}, {"w": "纰戾", "t": "讹错;不合情理"}, {"w": "纰乱", "t": "错乱"}, {"w": "纰僻", "t": "错误。"}]}, {"meaning": "已故的母亲。", "cites": [{"t": "自伤纪考纰。", "b": "《金广延母徐氏纪产碑》"}]}]}, {"pinyin": "pí", "defs": [{"meaning": "(形声。从糸,比声。本义:缘饰;边缘) 同本义。", "cites": [{"t": "从糸,比声。谓氐所制毛布。", "b": "《说文》。按,此字本当训“缘”也。"}, {"t": "纰,缘也。", "b": "《广雅》"}, {"t": "缟冠素纰。", "b": "《礼记·玉藻》。注:“边缘也。”"}]}, {"meaning": "在衣冠或旗帜上镶边。", "cites": [{"t": "纰,饰也。", "b": "《尔雅》"}, {"t": "素丝纰之。", "b": "《诗·鄘风·干旄》"}, {"t": "纰以爵韦六寸。", "b": "《礼记·杂记》。注:“在旁曰纰。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3823wx','纴','1','rèn','纟','7','','[{"pinyin": "rèn", "defs": [{"meaning": "织布帛的纱缕。", "cites": [{"t": "纴,机缕也。", "b": "《说文》"}, {"t": "织纴组紃。", "b": "《礼记·内则》"}, {"t": "执针织纴,皆百人。", "b": "《左传·成公二年》"}, {"t": "妇人不得纺绩织纴。", "b": "《汉书·严助传》"}]}, {"meaning": "指纺织。", "cites": [{"t": "侍儿五三,可充纴织;家僮数四,足代耕耘。", "b": "《北史·萧大圜传》"}]}, {"meaning": "缯帛。", "cites": [{"t": "其妇女庄栉织纴皆取成于婢仆。", "b": "《晋书》"}]}, {"meaning": "穿,引。", "cites": [{"t": "石斛数条,去根如筒子,一边纴入耳中。", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3824wx','纶','1','lún guān','纟','7','','[{"pinyin": "lún", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,仑(lún)声。本义:青丝绶带,古代官吏系印所用)。"}, {"meaning": "同本义。", "cites": [{"t": "纶,青丝绶也。", "b": "《说文》。按,秦汉百石官佩此绶,非经纬织成,但合青丝绳辫纠之者,所谓宛转绳也。"}, {"t": "其出如纶。", "b": "《礼记·缁衣》。注:“今有秩啬夫所佩也。”"}, {"t": "五两之纶。", "b": "《法言·孝至》。注:“如青丝绳也。”"}], "words": [{"w": "纶巾", "t": "古时以青丝带编成的头巾"}, {"w": "纶连", "t": "由丝绶编结而成的网状物"}, {"w": "纶组节约", "t": "古时葬礼以丝绵裹尸,再以丝带缠束。"}]}, {"meaning": "钓鱼竿上的丝线。", "cites": [{"t": "翠纶桂耳,反所以失鱼。", "b": "《文心雕龙·情采》"}], "words": [{"w": "纶返", "t": "收回钓丝"}, {"w": "纶竿", "t": "钓鱼竿。"}]}, {"meaning": "地名 。春秋虞邑。在今河南省虞城县东南三十里。"}, {"meaning": "整理丝线。", "cites": [{"t": "之子于钓,言论之绳。", "b": "《诗·小雅·采绿》"}], "words": [{"w": "纶经", "t": "经纶。整理丝缕。"}]}, {"meaning": "治理。", "cites": [{"t": "经纶世务者,窥谷忘反。", "b": "《与朱元思书》"}], "words": [{"w": "经纶", "t": "筹画治理。"}]}, {"meaning": "姓。"}]}, {"pinyin": "guān", "defs": [{"meaning": "用青丝带做的头巾。", "cites": [{"t": "羽扇纶巾,谈笑间,樯橹灰飞烟灭。", "b": "宋·苏轼《念奴娇·赤壁怀古》"}], "words": [{"w": "纶羽", "t": "头戴纶巾,手执羽扇。多形容飘逸潇洒或儒雅风流的风度。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3825wx','纾','1','shū','纟','7','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从糸(mì),予声。本义:延缓)。"}, {"meaning": "同本义。", "cites": [{"t": "纾,缓也。", "b": "《说文》"}, {"t": "彼交匪纾。", "b": "《诗·小雅·采菽》"}, {"t": "以纾楚国之难。", "b": "《左传·庄公三十年》"}, {"t": "姑纾死焉。", "b": "《左传·文公十六年》"}, {"t": "民急矣,姑从楚以纾吾民。", "b": "《左传·襄公八年》"}], "words": [{"w": "纾缓", "t": "宽缓;使宽缓"}, {"w": "纾回", "t": "缓慢曲折。"}]}, {"meaning": "宽缓;宽松。", "cites": [{"t": "民力稍纾,得以尽于田亩。", "b": "《宋史·李蘩传》"}], "words": [{"w": "纾放", "t": "抒发宽解"}, {"w": "纾宽", "t": "宽舒。"}]}, {"meaning": "解除;排除。", "cites": [{"t": "可以纾忧。", "b": "《左传·成公十六年》"}, {"t": "是崇皞济而脩祀纾祸也。", "b": "《左传·僖公二十一年》"}, {"t": "众谓予一行为可以纾祸。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "纾难", "t": "解除国难"}, {"w": "纾泄", "t": "解除发散"}, {"w": "纾祸", "t": "解除祸患"}, {"w": "纾忧", "t": "解除忧患。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3826wx','玮','1','wěi','王','8','','[{"pinyin": "wěi", "defs": [{"meaning": "美丽的玉。", "cites": [{"t": "玮,美玉。", "b": "《集韵》"}]}, {"meaning": "皮绳", "cites": [{"t": "晋阳佩玮,西门带弦。", "b": "《汉故谷城长荡阴令张君表颂》"}]}, {"meaning": "赞美。", "cites": [{"t": "梁惠王玮其照乘之珠,齐威王答以四臣。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
