('3833wx','盂','1','yú','皿','8','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从皿,于声。皿表示器皿。本义:盛饮食或其他液体的圆口器皿)。"}, {"meaning": "同本义。", "cites": [{"t": "盂,饮器也。", "b": "《说文》"}, {"t": "置守宫盂下。", "b": "《汉书·东方朔传》"}, {"t": "操一豚蹄,酒一盂。", "b": "《史记·滑稽列传》"}], "words": [{"w": "盂方水方", "t": "水因器成形。喻上行下效"}, {"w": "钵盂", "t": "古代和尚用的饭碗"}, {"w": "痰盂", "t": "盛痰用的器皿。"}]}, {"meaning": "盛饭的器皿。", "cites": [{"t": "上尝使诸数家射覆,置守宫盂下,射之,皆不能中。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3834wx','忝','1','tiǎn','小','8','','[{"pinyin": "tiǎn", "defs": [{"meaning": "(形声。从心,天声。本义:羞辱,愧对;辱)。"}, {"meaning": "同本义。", "cites": [{"t": "忝,辱也。", "b": "《说文》"}, {"t": "无忝祖考。", "b": "《书·君牙》"}, {"t": "辟不辟,忝厥祖。", "b": "《书·太甲上》。传:“忝,辱也。”"}, {"t": "无忝尔所生。", "b": "《诗·小雅·小宛》"}, {"t": "二十忝科名。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "有忝", "t": "有愧于;有辱。"}]}, {"meaning": "荣幸——用作谦词。", "words": [{"w": "忝列门墙;忝在知交", "t": ""}]}, {"meaning": "挺起;凸出。", "cites": [{"t": "假僧接刀在手,解开衣服,忝起胸膛,将左手抹腹,右手持刀,唿喇的响一声,把腹皮剖开。", "b": "《西游记》"}]}, {"meaning": "表示愧于进行某事 ——用作谦词。", "cites": [{"t": "臣忝当大任,义在安国。", "b": "陈寿《三国志》"}], "words": [{"w": "忝眷;忝居", "t": ""}]}]}]','jingmo-wenyan');
