('3840wx','拈','1','niān','扌','8','','[{"pinyin": "niān", "defs": [{"meaning": "(形声。从手,占声。本义:用指取物)。"}, {"meaning": "同本义。", "cites": [{"t": "拈,揶也。", "b": "《说文》"}, {"t": "拈,持也。", "b": "《广雅》"}, {"t": "女何蚩而三招子。", "b": "《列子·汤问》。注:“拈,指取物也。”"}, {"t": "我二人拈阄,拈着的先去。", "b": "《三国演义》"}], "words": [{"w": "拈毫", "t": "拿笔。借指写作或绘画"}, {"w": "拈团儿", "t": "拈阄"}, {"w": "拈撮", "t": "用指头取物"}, {"w": "拈周试晬", "t": "抓周。小儿周岁从罗列的多种物品中拈取,旧俗以为可预测未来的性情志趣"}, {"w": "拈酒", "t": "唐代口语。拿起酒杯吃酒。"}]}]}]','jingmo-wenyan');
