('3841wx','垆','1','lú','土','8','','[{"pinyin": "lú", "defs": [{"meaning": "黑色坚实的土壤。", "cites": [{"t": "垆,刚土也。从土,卢声。", "b": "《说文》"}, {"t": "埴垆用豕。", "b": "《周礼·草人》"}, {"t": "垆土人大。", "b": "《淮南子·地形》"}, {"t": "下土坟垆。", "b": "《书·禹贡》"}], "words": [{"w": "垆土", "t": "黑色坚硬而质粗不粘的土壤。"}]}, {"meaning": "古时酒店里安放酒瓮的土台子。", "cites": [{"t": "诣道边酒垆。", "b": "《南史·谢几卿传》"}, {"t": "垆边人似月,皓腕凝霜雪。", "b": "唐·韦庄《菩萨蛮》"}]}]}]','jingmo-wenyan');
