INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3845wx','拊','1','fǔ','扌','8','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从手,付声。本义:抚摸)。"}, {"meaning": "同本义。", "cites": [{"t": "拊,揗也。", "b": "《说文》。段注:“揗者,摩也。古作‘拊揗’,今作‘抚循’,古今字也。尧典曰:“击石拊石”,拊轻击重,故分言之。”。"}, {"t": "主拊其背曰:“行矣!”", "b": "《汉书·外戚传上》"}], "words": [{"w": "拊扪", "t": "抚摸"}, {"w": "抚式", "t": "用手按车板。"}]}, {"meaning": "拊掌:拍手。表示惊讶,恼怒或欢喜。", "cites": [{"t": "阿母大拊掌:“不图子自归!”", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "拊手", "t": "拍手;鼓掌"}, {"w": "拊心", "t": "抚胸;拍胸"}, {"w": "拊髀", "t": "拍大腿"}, {"w": "拊床", "t": "拍床"}, {"w": "拊背", "t": "轻拍肩背"}, {"w": "拊嗟", "t": "拍手嗟叹"}, {"w": "拊噪", "t": "拍手欢呼"}, {"w": "拊翼", "t": "拍打翅膀。"}]}, {"meaning": ""}, {"meaning": "体恤抚慰。", "cites": [{"t": "王巡三军,拊而勉之。", "b": "《左传·宣公十二年》"}, {"t": "勉慰痍伤,拊巡饥渴。", "b": "颜延之《阳给事诔》"}], "words": [{"w": "拊爱", "t": "爱抚"}, {"w": "拊绥", "t": "安抚"}, {"w": "抚揖", "t": "抚慰揖安"}, {"w": "拊恤", "t": "抚恤"}, {"w": "拊循", "t": "安抚,抚慰"}, {"w": "拊视", "t": "抚爱照顾"}, {"w": "拊劳", "t": "慰劳。"}]}, {"meaning": "抚摸。", "cites": [{"t": "视不得其所坚,而得其所白者,无坚也;拊不得其所白,而得其所坚[者],无白也。", "b": "《公孙龙子·坚白论》"}]}]}]','jingmo-wenyan');
