('3852wx','坳','1','ào','土','8','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。从土,幼声。本义:低凹的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "下者飘转沉塘坳。", "b": "杜甫《茅屋为秋风所破歌》"}], "words": [{"w": "坳窊", "t": "地面的低洼处"}, {"w": "坳堂", "t": "堂上的低洼处"}, {"w": "坳洼", "t": "地面的低洼处。"}]}, {"meaning": "山间的平地。", "cites": [{"t": "下至山坳,瞑色已合。", "b": "《徐霞客游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3853wx','耶','1','yē yé','耳','8','','[{"pinyin": "yē", "defs": [{"meaning": "耶稣或耶稣教的简称。", "cites": [{"t": "佛生最先,孔次之,耶又欢之。", "b": "谭嗣同《仁学》"}]}]}, {"pinyin": "yé", "defs": [{"meaning": "(形声。从耳,邑(右耳旁是“邑”的变形)声。不详) 本义:句末语气词。相当于“吗”或“呢”。", "cites": [{"t": "为一郎僮耶。", "b": "唐·柳宗元《童区寄传》"}, {"t": "史公果死耶。", "b": "清·全祖望《梅花岭记》"}, {"t": "抑未死耶。", "b": ""}, {"t": "岂可近耶。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "不久死耶。", "b": ""}, {"t": "捋虎须耶。", "b": ""}, {"t": "过实耶。", "b": "清·周容《芋老人传》"}, {"t": "猎虫所耶。", "b": "《聊斋志异·促织》"}, {"t": "人诟詈耶。", "b": "《明史》"}]}, {"meaning": "父亲", "cites": [{"t": "今人不以贵贱呼父皆为耶,盖传袭已久矣。", "b": "宋·程大昌《演繁露》"}, {"t": "军书十二卷,卷卷有耶名。", "b": "《古文苑·木兰诗》"}, {"t": "耶娘妻子走相送,尘埃不见咸阳桥。", "b": "杜甫《兵车行》"}, {"t": "耶耶(父亲;祖父);耶娘(父母。后多作“爷娘”)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3854wx','苷','1','gān','艹','8','','[{"pinyin": "gān", "defs": [{"meaning": "甘草。", "cites": [{"t": "苷,甘草也。从艸,从甘,会意。甘亦声。", "b": "《说文》"}, {"t": "美丹,甘草也。", "b": "《广雅》"}, {"t": "甘草主生肉之药。", "b": "《淮南子·览冥》"}]}, {"meaning": "即糖苷 。天然存在的或人工合成的糖缩醛衍生物(如花色苷、苦杏仁苷等);经水解作用(如酶或酸作用)产生两个或两个以上的糖分子结合而成的双糖、多糖也称糖苷。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3855wx','苯','1','běn','艹','8','','[{"pinyin": "běn", "defs": [{"meaning": "无色、挥发、可燃的毒性液体芳烃C6H6,遇火燃烧。商品是从煤的炼焦(如从焦炉气的轻油中)或从某些石油馏份通过催化脱氢获得,主要用于有机合成。"}]}]','jingmo-wenyan');
