INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3857wx','茏','1','lóng','艹','8','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从艸,龙声。本义:草名。即“荭花”。蓼类植物) 同本义。", "cites": [{"t": "其山之浅,有茏与斥。", "b": "《管子·地员》"}]}, {"meaning": "形容草木青翠茂盛。也作“葱茏”。", "cites": [{"t": "譬若周云之茏苁。", "b": "《淮南子·俶真》"}], "words": [{"w": "茏茸", "t": "丛聚的样子"}, {"w": "茏苁", "t": "丛聚的样子。同“茏葱”"}, {"w": "葱茏", "t": "草木茂盛的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3858wx','苫','1','shān shàn','艹','8','','[{"pinyin": "shān", "defs": [{"meaning": "(形声。占声。本义:用茅草编成的覆盖物)。"}, {"meaning": "同本义。", "cites": [{"t": "苫,盖也。", "b": "《说文》"}, {"t": "白盖谓之苫。", "b": "《尔雅》。注:“白茅苫。今江东呼为盖。”李注:“编菅茅以盖屋者曰苫。”"}, {"t": "寝苫。", "b": "《仪礼·既夕礼》"}, {"t": "乃祖吾离被苫盖。", "b": "《左传·襄公十四年》"}], "words": [{"w": "草苫子;苫宇", "t": "草庐"}, {"w": "苫茨", "t": "茅草盖的屋顶"}, {"w": "苫盖", "t": "茅草编的覆盖物。亦特指草衣、茅屋"}, {"w": "苫蓑", "t": "茅草所编用以遮雨的覆盖物"}, {"w": "苫褐", "t": "草衣。"}]}, {"meaning": "古代居丧时,孝子睡的草垫子。", "cites": [{"t": "寝苫枕草。", "b": "《左传·襄公十七年》"}], "words": [{"w": "苫条", "t": "毡条"}, {"w": "苫块", "t": "“寝苫枕块”的略语。古礼,父母死后,儿子要睡草荐,枕土块"}, {"w": "苫次", "t": "指居亲丧。即在苫、寝苫"}, {"w": "苫席", "t": "用麦杆或茅草编的粗席。常垫于褥下或用于居丧"}, {"w": "苫庐", "t": "古代在亲丧中所居之室"}, {"w": "苫壤", "t": "苫席与土块。指居亲丧中。"}]}]}, {"pinyin": "shàn", "defs": [{"meaning": "编茅盖屋。", "cites": [{"t": "刈茅苫鹿屋,插棘护鸡栖。", "b": "宋·陆游《幽居岁莫》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3859wx','苜','1','mù','艹','8','','[{"pinyin": "mù", "defs": [{"meaning": "多年生草本植物，叶子长圆形，花紫色，结荚果，可以喂牲口，做肥料。嫩苗可食。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3860wx','苴','1','jū zū','艹','8','','[{"pinyin": "jū", "defs": [{"meaning": "(形声。从艸,且声。本义:鞋底的草垫,用以垫鞋底)。"}, {"meaning": "同本义。", "cites": [{"t": "冠虽敝不以苴履。", "b": "《汉书》"}]}, {"meaning": "青麻的子实。", "cites": [{"t": "七月食瓜,八月断壶。九月叔苴,采荼薪樗,食我农夫。", "b": "《诗·幽风·七月》"}]}]}, {"pinyin": "zū", "defs": [{"meaning": "", "words": [{"w": "苴稭", "t": "古代祭祀时用作陈列祭品的草席。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3861wx','苒','1','rǎn','艹','8','','[{"pinyin": "rǎn", "defs": [{"meaning": "(形声。从艸,冉(rǎn)声。苒苒:草茂盛的样子)。"}, {"meaning": "时间逐渐逝去。", "cites": [{"t": "荏苒冬春谢。", "b": "《悼亡诗》。注:“岁月流貌。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
