INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3864wx','苻','1','fú','艹','8','','[{"pinyin": "fú", "defs": [{"meaning": ",芦苇杆里的薄膜。", "cites": [{"t": "芦苻之厚,通于无垠。", "b": "《淮南子·俶真》"}]}, {"meaning": "符契。", "cites": [{"t": "即上尚书,参以苻验。", "b": "汉《史晨乡孔庙后碑》"}, {"t": "精通皓穹,三纳苻银。", "b": "汉《李翕析里桥郙阁颂》"}]}, {"meaning": "符命,预言未来的神秘文书。", "cites": [{"t": "运天苻命。", "b": "汉《北军中侯郭仲奇碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3865wx','苓','1','líng','艹','8','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从艸,令声。本义:植物名。苓耳,即卷耳)。"}, {"meaning": "药草名。茯苓、猪苓皆简称苓。茯苓是寄生于松树根下的一种菌类植物。猪苓是枫树苓,生于枫根下的一种植物。二者均可入药。", "cites": [{"t": "苓,卷耳也。", "b": "《说文》"}, {"t": "失时者苓落。", "b": "《汉书·叙传》"}, {"t": "山有榛,隰有苓。", "b": "《诗·邶风·简兮》"}], "words": [{"w": "苓龟", "t": "中药名。即茯苓。因上等茯苓乌龟状而得名。"}]}, {"meaning": "零落。同“零”。", "cites": [{"t": "得气者蕃滋,失时者苓落。", "b": "《汉书·叙传上》"}], "words": [{"w": "苓落", "t": "草木凋落。同“零落”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3866wx','茚','1','yìn','艹','8','','[{"pinyin": "yìn", "defs": [{"meaning": "很易聚合的一种烃类液体  C9H8,由煤焦油蒸馏或石油裂解制得,主要用于制备树脂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3867wx','茆','1','máo mǎo','艹','8','','[{"pinyin": "máo", "defs": [{"meaning": "茅草", "cites": [{"t": "覆之以茆。", "b": "明·刘基《诚意伯刘文成公文集》"}]}]}, {"pinyin": "mǎo", "defs": [{"meaning": "莼菜 。睡莲科。一种多年生水生草本植物。", "cites": [{"t": "薄采其茆。", "b": "《诗·鲁颂·泮水》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3868wx','茑','1','niǎo','艹','8','','[{"pinyin": "niǎo", "defs": [{"meaning": "寄生木 。本草学家指桑寄生科桑寄生属和檞寄生属植物。前者寄生于山茶科、壳斗科等树上,后者寄生于檞、榆、桦等多种阔叶树上。枝茎可入药。"}]}]','jingmo-wenyan');
