INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3870wx','茔','1','yíng','艹','8','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从土,荧(yíng)省声。本义:墓地)。"}, {"meaning": "同本义。", "cites": [{"t": "茔,墓也。", "b": "《说文》"}, {"t": "茔,墓地。", "b": "《玉篇》"}, {"t": "茔,葬地也。", "b": "《广雅》"}, {"t": "赐茔杜东。", "b": "《汉书·张安世传》。注:“冢地也。”"}, {"t": "太皇太后诏外家王氏田非冢茔,皆以赋贫民。", "b": "《汉书》"}], "words": [{"w": "茔树", "t": "墓地上的树木,多为松柏等。"}]}, {"meaning": "坟。", "cites": [{"t": "先茔在杭。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "用黄土封茔;茔户", "t": "受官府之命专事看守坟茔的民户"}, {"w": "茔墓", "t": "坟墓。"}]}, {"meaning": "埋葬。", "cites": [{"t": "未欲茔于他山,就瘗于西垒之根。", "b": "宋·侯延庆《退斋笔录》"}], "words": [{"w": "茔葬", "t": "丧葬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3871wx','茕','1','qióng','艹','8','','[{"pinyin": "qióng", "defs": [{"meaning": "回旋着飞。", "cites": [{"t": "茕,回飞也。从凡,煢省声。鸟回转疾飞曰茕。", "b": "《说文》"}]}, {"meaning": "孤独,无兄弟。", "cites": [{"t": "无虐茕独。", "b": "《书·洪范》。传:“单无兄弟也。”"}, {"t": "哀此茕独。", "b": "《诗·小雅·正月》"}, {"t": "夫何茕独而不余听。", "b": "《离骚》。注:“孤也。”"}], "words": [{"w": "茕子", "t": "孤儿"}, {"w": "茕孑", "t": "孤单"}, {"w": "茕困", "t": "孤苦"}, {"w": "茕妻", "t": "寡妇"}, {"w": "茕疚", "t": "因孤单而感忧伤"}, {"w": "茕居", "t": "寡居。"}]}, {"meaning": "悲愁。", "cites": [{"t": "神茕茕以遥思兮,…。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3872wx','茀','1','fú','艹','8','','[{"pinyin": "fú", "defs": [{"meaning": "野草塞路。", "cites": [{"t": "茀,草多也。从艸,弗声。字亦作芾。", "b": "《说文》"}, {"t": "道茀不可行。", "b": "《国语·周语》"}], "words": [{"w": "茀茀", "t": "草木茂盛的样子"}, {"w": "茀杂", "t": "草木杂乱的样子。"}]}, {"meaning": "(bó)。突然。", "cites": [{"t": "兽死不择音,气息茀然。", "b": "《庄子·人间世》"}]}, {"meaning": "拔除。", "cites": [{"t": "茀厥丰草,种之黄茂。", "b": "《诗·大雅·生民》"}]}, {"meaning": "古称富贵寿考为福。", "cites": [{"t": "茀禄尔康矣。", "b": "《诗·大雅·春阿》"}]}, {"meaning": "引棺的绳索——通“绋”。", "cites": [{"t": "始用葛茀。", "b": "《左传·宣公八年》"}]}, {"meaning": "(bèi)。彗星。", "cites": [{"t": "政急则出蚤,政缓则出晚,政绝不行,则伏不见而为彗茀。", "b": "《汉书·李寻传》"}], "words": [{"w": "星茀", "t": "彗星。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3873wx','苕','1','sháo tiáo','艹','8','','[{"pinyin": "sháo", "defs": [{"meaning": "——如“红苕”。甘薯的别名。"}]}, {"pinyin": "tiáo", "defs": [{"meaning": "(形声。从艸,召声。本义:陵苕。亦名“凌霄”、“紫葳”。“蔓生草”)。"}, {"meaning": "同本义。", "cites": [{"t": "苕,苕草也。", "b": "《说文》"}, {"t": "邛有旨苕。", "b": "《诗·陈风·东门之枌》"}, {"t": "苕之华。", "b": "《诗·小雅·苕之华》"}]}, {"meaning": "紫葳科落叶木质藤本,借气根攀附在其他物上。花冠漏斗状钟形,大而鲜艳,橘红色,栽培供观赏,花入药,破血去瘀。", "words": [{"w": "苕华", "t": "花名。即凌霄花"}, {"w": "苕荣", "t": "陵苕花。亦喻容貌之美"}, {"w": "苕颖", "t": "草花和禾穗。亦泛指植物的花、穗及其茎。"}]}, {"meaning": "苕菜,即紫云英 。豆科。一二年生草本。为优良的绿肥作物,也作蔬菜和家畜饲料。"}, {"meaning": "本作“芀”。芦苇的花。苕杆可为帚。", "cites": [{"t": "茢,苕帚,所以扫不祥。", "b": "《周礼·夏宫下·戎右》郑注"}, {"t": "系之苇苕。", "b": "《荀子·劝学》"}, {"t": "或苕发颖。", "b": "陆机《文赋》"}], "words": [{"w": "苕折", "t": "苇苕断折。比喻寄身之地易遭危险"}, {"w": "苕帚", "t": "用苇花编成的扫把。旧说可以除不祥。"}]}, {"meaning": "水名 。", "words": [{"w": "苕水", "t": "水名在今陕西省境内在今浙江省境内"}, {"w": "苕溪", "t": "水名。有二源:出浙江天目山之南者为东苕,出天目山之北者为西苕。两溪合流,由小梅、大浅两湖口注入太湖。夹岩多苕,秋后花飘水上如飞雪,故名"}]}, {"meaning": "高、远  。", "words": [{"w": "苕亭", "t": "高耸的样子"}, {"w": "苕苕", "t": "很高的样子;很远的样子。通“迢迢”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3874wx','枥','1','lì','木','8','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从木,厉声。本义:喂马的槽)。"}, {"meaning": "同本义。", "cites": [{"t": "养马器也。", "b": "《方言五》枥注"}, {"t": "老骥伏枥,志在千里。", "b": "汉·曹操《步出夏门行》"}, {"t": "骈死于槽枥之间。", "b": "唐·韩愈《杂说》"}], "words": [{"w": "枥马", "t": "拴在马槽上马"}, {"w": "枥厩", "t": "饲马器和养马房"}, {"w": "枥骥", "t": "俯首马槽上的骏马。"}]}, {"meaning": "马房。", "cites": [{"t": "气劳者,缓系之枥上。", "b": "《齐民要术·养牛马驴骡》"}]}, {"meaning": "古书上指栎树。", "cites": [{"t": "时见松枥皆十围。", "b": "唐·韩愈《山石》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3875wx','枇','1','pí','木','8','','[{"pinyin": "pí", "defs": [{"meaning": "食器。", "cites": [{"t": "杵以梧,枇以桑,长三尺。", "b": "《礼记·杂记让》"}]}, {"meaning": "用篦子梳发。", "cites": [{"t": "头不枇沐,体生疮肿。", "b": "《后汉书·济北惠王寿传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3876wx','杪','1','miǎo','木','8','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从木,少声。本义:树枝的细梢)。"}, {"meaning": "同本义。", "cites": [{"t": "杪,木标末也。", "b": "《说文》"}, {"t": "树锋曰杪。", "b": "《通俗文》"}, {"t": "偃蹇杪颠。", "b": "司马相如《上林赋》"}, {"t": "或在木杪。", "b": "清·纪昀《阅微草堂笔记》"}], "words": [{"w": "杪颠", "t": "树木末梢"}, {"w": "杪头", "t": "树梢。"}]}, {"meaning": "末尾,时间上的终止。", "cites": [{"t": "必于岁之杪。", "b": "《礼记·王制》"}], "words": [{"w": "岁杪", "t": "年尾"}, {"w": "杪春", "t": "暮春"}, {"w": "杪秋", "t": "晚秋"}, {"w": "杪冬", "t": "暮冬"}, {"w": "杪岁", "t": "岁末"}, {"w": "杪节", "t": "候之末。"}]}, {"meaning": "微小;细微。", "cites": [{"t": "阔略杪小之礼。", "b": "《后汉书·冯衍传》"}], "words": [{"w": "杪小", "t": "细小,微小"}, {"w": "杪杪", "t": "谓渺小"}, {"w": "杪忽", "t": "极小的量度单位"}, {"w": "杪黍", "t": "形容极其细微。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3877wx','杳','1','yǎo','木','8','','[{"pinyin": "yǎo", "defs": [{"meaning": "(会意。上为“木”,下为“日”,表示太阳落在树木下,天色已昏暗。本义:昏暗)。"}, {"meaning": "同本义。", "cites": [{"t": "杳,冥也。", "b": "《说文》"}, {"t": "杳旭卉兮。", "b": "扬雄《甘泉赋》。注:“深远也。”"}, {"t": "独驰思乎杳冥。", "b": "傅毅《舞赋》"}, {"t": "杳冥冥兮羌昼晦,东风飘兮神灵雨。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "杳杳冥冥", "t": "昏暗幽远"}, {"w": "杳蒙", "t": "迷茫,模糊不清。"}]}, {"meaning": "幽深。", "cites": [{"t": "眴兮杳杳,孔静幽默。", "b": "《楚辞·屈原·九章·怀沙》"}], "words": [{"w": "杳杳", "t": "幽暗深远的样子"}, {"w": "杳然", "t": "幽深的样子"}, {"w": "杳昧", "t": "深幽隐晦。"}]}, {"meaning": "渺茫;深远;高远。", "cites": [{"t": "杳不知所之也。(杳,深远没有尽头,这里表听不到声音,今有成语:“杳无音信”。之:到。)", "b": "唐·杜牧《阿房宫赋》"}, {"t": "奇秀深杳。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "杳远", "t": "渺茫遥远。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3878wx','枧','1','jiǎn','木','8','','[{"pinyin": "jiǎn", "defs": [{"meaning": "引水的竹、木管子。", "cites": [{"t": "溪面只消横一枧,水从空里过如飞。", "b": "宋·杨万里《桑茶坑道中》"}], "words": [{"w": "香枧", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3879wx','杵','1','chǔ','木','8','','[{"pinyin": "chǔ", "defs": [{"meaning": "(形声。从木,午声。本义:舂米的棒槌)。"}, {"meaning": "同本义。", "cites": [{"t": "杵,舂杵也。", "b": "《说文》"}, {"t": "断木为杵,掘地为臼。", "b": "《易·系辞》传"}], "words": [{"w": "杵臼交", "t": "不嫌贫贱的交情"}, {"w": "杵臼", "t": "杵与臼"}, {"w": "杵头", "t": "杵。"}]}, {"meaning": "筑墙、筑堤时,用来填实泥土的棒槌。", "cites": [{"t": "筑谓之杵。", "b": "《广雅》"}, {"t": "杵以梧。", "b": "《礼记·杂记》"}], "words": [{"w": "杵声", "t": "筑城填土的杵槌声"}, {"w": "杵木", "t": "筑土的木槌。"}]}, {"meaning": "古代的一种棒形兵器。形如杵。"}, {"meaning": "捣,砸。", "cites": [{"t": "傲童不讴歌,舂筑者不相杵。", "b": "《新书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3880wx','枨','1','chéng','木','8','','[{"pinyin": "chéng", "defs": [{"meaning": "木柱。", "cites": [{"t": "枨,杖也。", "b": "《说文》"}]}, {"meaning": "古时门两旁所竖的木柱,用以防车过触门。亦称枨臬。", "cites": [{"t": "枨谓之楔。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3881wx','枞','1','cōng zōng','木','8','','[{"pinyin": "cōng", "defs": [{"meaning": "枞树。常绿乔木,又叫冷杉 。果实椭圆形,暗紫色。木材供制器具,又可做建筑材料。", "cites": [{"t": "枞,松叶柏身木也。从木,从声。", "b": "《说文》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zōng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3882wx','枋','1','fāng','木','8','','[{"pinyin": "fāng", "defs": [{"meaning": "枋树。木名。", "cites": [{"t": "枋,枋木也。可作车,从木,方声。", "b": "《说文》"}, {"t": "我决起而飞,枪榆枋。", "b": "《庄子·逍遥游》"}], "words": [{"w": "枋榆", "t": "枋树与榆树。"}]}, {"meaning": "筑堤堰用的大木桩。", "cites": [{"t": "后背洪枋巨堰,深渠高堤者也。", "b": "《水经注》"}]}, {"meaning": "泛指木棒。", "cites": [{"t": "突然,他抓起一根短短的木枋,站起来,走到柜台边。", "b": "谭秀牧《失去的黑金刚》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3883wx','杻','1','chǒu niǔ','木','8','','[{"pinyin": "chǒu", "defs": [{"meaning": "古代刑具,手铐之类", "words": [{"w": "杻械", "t": "杻镣。脚镣手铐"}, {"w": "杻锁", "t": "手铐与项锁。"}]}]}, {"pinyin": "niǔ", "defs": [{"meaning": "(形声。从木,丑声。本义:木名。檍树) 同本义。", "cites": [{"t": "山有栲,隰有杻。", "b": "《诗·唐风·山有枢》。朱熹集传:“叶似杏而尖,白色,皮正赤,其理多曲少直,材可为弓弩干者也。”"}, {"t": "杻,檍。", "b": "《尔雅》。注:“关西呼杻子,一名土橿。”"}, {"t": "其上多杻。", "b": "《西山径·英山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3884wx','杷','1','bà pá','木','8','','[{"pinyin": "bà", "defs": [{"meaning": "碎土、平地的农具", "words": [{"w": "杷头", "t": "杷除去柄的部分"}, {"w": "杷车", "t": "攻城用的抛石车"}]}]}, {"pinyin": "pá", "defs": [{"meaning": "(形声。从木,巴声。(bà)本义:农具名) 一种有齿和长柄的农具。用以耙梳、聚拢,多用竹、木或铁等制成。", "cites": [{"t": "杷,收麦器。", "b": "《说文》"}, {"t": "屈竹作杷,削治鹿卢。", "b": "汉·王褒《僮约》"}]}, {"meaning": "发掘。"}, {"meaning": "——见“枇杷”(pípa)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3885wx','杼','1','zhù','木','8','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从木,予声。本义:织布机的梭子)。"}, {"meaning": "同本义。", "cites": [{"t": "杼,机之持纬者。", "b": "《说文》。今以梭为之。"}, {"t": "杼柚其空。", "b": "《诗·小雅·大东》"}, {"t": "此织生自蚕茧,成于机杼。(机杼,泛指织布的工具。)", "b": "《后汉书·列女传》"}, {"t": "一人又告之曰:“曾参杀人!”其母惧,投杼逾墙而走。", "b": "《战国策》"}], "words": [{"w": "杼柚", "t": "杼轴。梭子和筘。比喻诗文的组织、构思"}, {"w": "杼梭", "t": "织机的梭子。指织造。"}]}, {"meaning": "土木工程中的泥工。", "cites": [{"t": "杼、柚,作也。东齐土作谓之杼,木作谓之柚。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3886wx','矸','1','gān','石','8','','[{"pinyin": "gān", "defs": [{"meaning": "采矿过程(开拓、掘进、剥离、回采)中,从井下或露天矿场开采出的或混入矿石中的岩石，煤～子。"}, {"meaning": "矸石的通称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3887wx','砀','1','dàng','石','8','','[{"pinyin": "dàng", "defs": [{"meaning": "有花纹的石头。", "cites": [{"t": "砀,文石也。从石,昜声。", "b": "《说文》"}, {"t": "梁国砀。", "b": "《汉书·地理志》。注:“山出文石,在今河南归德府。”"}, {"t": "君看石芒砀,掩泪悲千古。", "b": "李白《丁都护歌》"}], "words": [{"w": "芒砀", "t": "形容山石大而多"}, {"w": "砀基", "t": "用有花纹的石头造的墙基。"}]}, {"meaning": "砀山(山名),在安徽省砀山县东南。"}, {"meaning": "突然。", "cites": [{"t": "肱砀骇以奋肆。", "b": "马融《长笛赋》。注:“突也。”"}], "words": [{"w": "砀骇", "t": "突然跌起。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3888wx','刳','1','kū','刂','8','','[{"pinyin": "kū", "defs": [{"meaning": "(形声。从刀,夸声。本义:剖,剖开)。"}, {"meaning": "同本义。", "cites": [{"t": "刳,判也。", "b": "《说文》"}, {"t": "刲之刳之。", "b": "《礼记·内则》"}, {"t": "刳剔孕妇。", "b": "《伪泰誓》"}, {"t": "引刀自刳其腹。", "b": "王充《论衡》"}], "words": [{"w": "刳割", "t": "剖割"}, {"w": "刳木", "t": "剖凿大木,使其中空"}, {"w": "刳肝", "t": "剖挖肝脏"}, {"w": "刳胎", "t": "剖割孕妇胎儿。"}]}, {"meaning": "挖,挖空。", "cites": [{"t": "刳木为舟,剡木为楫。", "b": "《易·系辞下》"}], "words": [{"w": "刳心", "t": "挖出心脏"}, {"w": "刳腔", "t": "挖空的腹腔。"}]}, {"meaning": "杀,割。", "cites": [{"t": "刳白马而盟。", "b": "《史记·苏秦列传》"}], "words": [{"w": "刳羊", "t": "古时外交结盟时杀羊宣誓"}, {"w": "刳割", "t": "切割。"}]}, {"meaning": "洗除,消除。", "cites": [{"t": "夫道,覆载万物者也,洋洋乎大哉!君子不可以不刳心焉。", "b": "《庄子》"}]}, {"meaning": "遭受残害。", "cites": [{"t": "江东新刳于兵,郡旱,饥民交走死无吊。", "b": "唐·韩愈《曹成王碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3889wx','奄','1','yǎn','大','8','','[{"pinyin": "yǎn", "defs": [{"meaning": "突然地。", "cites": [{"t": "奄忽灭没。", "b": "马融《长笛赋》。注:“奄遽也。”"}], "words": [{"w": "奄然", "t": "突然;悄然"}, {"w": "奄至", "t": "急速来到。"}]}, {"meaning": "气息微弱的样子。", "cites": [{"t": "奄,息也。", "b": "《方言》十"}, {"t": "奄息葱极。", "b": "《汉书·司马相如传》。注:“奄然休息也。”"}, {"t": "神奄留。", "b": "《汉书·礼乐志》。按,安也。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3890wx','瓯','1','ōu','瓦','8','','[{"pinyin": "ōu", "defs": [{"meaning": "(形声。从瓦,区(ōu)声。本义:盆盂类瓦器)。"}, {"meaning": "同本义。", "cites": [{"t": "瓯,小盆也。", "b": "《说文》"}, {"t": "流丸止于瓯臾。", "b": "《荀子·大略》"}, {"t": "我国家犹若金瓯,无一伤缺。", "b": "《南史·朱异传》"}], "words": [{"w": "瓯杓", "t": "瓦盆和木瓢。"}]}, {"meaning": "杯;盅。", "cites": [{"t": "超宗既坐,饮酒数瓯。", "b": "《南齐书·谢超宗传》"}], "words": [{"w": "茶瓯;酒瓯;瓯臾", "t": "瓯与臾。比喻地面凹陷不平之处"}, {"w": "瓯窭", "t": "狭小的高地"}, {"w": "瓯抠", "t": "凹凸不平。形容相貌奇异。"}]}, {"meaning": "古代地名 。故地在今浙江省温州市。"}, {"meaning": "古水名,即永宁江,今称瓯江 ,浙江省第二大河,上源龙泉溪,经温州市入东海。瓯亦为温州市的别称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3891wx','殁','1','mò','歹','8','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从歺(è),(mò)声。歺残骨,与死亡有关。本义:死)。"}, {"meaning": "同本义。", "cites": [{"t": "殁,终也。", "b": "《广雅·释诂四》"}, {"t": "伯乐既殁兮。", "b": "《史记·屈原贾生列传》"}, {"t": "管仲殁矣。", "b": "《国语·晋语四》"}, {"t": "少者殁而长者存。", "b": "韩愈《祭十二郎文》"}], "words": [{"w": "既殁", "t": "既已死亡"}, {"w": "殁世", "t": "终生;终其一生;去世"}, {"w": "殁命", "t": "舍命,拚死"}, {"w": "殁齿", "t": "没齿,终生。"}]}, {"meaning": "消灭。", "cites": [{"t": "道逢匈奴骑兵,皆为所殁。", "b": "《后汉书》"}]}, {"meaning": "隐没;沦没。", "cites": [{"t": "神女殁幽境,汤池流大川。", "b": "唐·李白《安州应城玉女汤作》"}]}]}]','jingmo-wenyan');
