INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3893wx','轭','1','è','车','8','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从车,厄声。本义:驾车时套在牲口脖子上的曲木) 同本义。", "cites": [{"t": "轭,辕前也。", "b": "《说文》。段注:“辕前者,谓衡也。”"}, {"t": "楔貌如軶。", "b": "《仪礼·既夕礼》"}, {"t": "三公奉軶持纳。", "b": "《荀子·正论》"}, {"t": "牵牛(牵牛星)不负轭。", "b": "《古诗十九首》"}]}, {"meaning": "束缚。", "cites": [{"t": "君以名桎臣,官以名轭民,父以名压子。", "b": "谭嗣同《仁学界说二十七界说》"}]}, {"meaning": "控制。", "cites": [{"t": "意大利之大部被轭于奥国。", "b": "梁启超《国家思想变迁异同论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3894wx','郅','1','zhì','阝','8','','[{"pinyin": "zhì", "defs": [{"meaning": "郁郅(Yùzhì)。古县名。", "cites": [{"t": "北地郁致县。从邑,至声。", "b": "《说文》"}]}, {"meaning": "在今甘肃省庆阳县境。"}, {"meaning": "大。", "cites": [{"t": "文王改制,爰周郅隆。", "b": "司马相如《封禅文》"}], "words": [{"w": "郅隆", "t": "昌盛,隆盛"}, {"w": "郅偈", "t": "高耸矗立的样子"}, {"w": "郅治", "t": "最完善的政治。也指太平盛世。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3895wx','鸢','1','yuān','鸟','8','','[{"pinyin": "yuān", "defs": [{"meaning": "动物名。又名“老鹰” 。属于鹰科的一种小型的鹰,有长而狭的翼,分叉很深的尾,薄弱的喙,两足只适于攫取昆虫和小爬行动物,也吃腐食烂肉,以善于在天上做优美持久的翱翔著称。", "cites": [{"t": "鸢飞戾天者,望峰息心。", "b": "南朝梁·吴均《与朱元思书》"}], "words": [{"w": "鸢肩", "t": "指上耸似鸢的肩膀"}, {"w": "鸢蹲", "t": "蹲伏如鸢。比喻怀才而贫困踬伏"}, {"w": "鸢飞鱼跃", "t": "比喻化育流行,万物各得其所"}, {"w": "鸢肩羔膝", "t": "耸肩屈膝。形容卑微的样子"}, {"w": "鸢肩鹄颈", "t": "耸肩伸颈。形容伏案冥思苦想之状。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3896wx','盱','1','xū','目','8','','[{"pinyin": "xū", "defs": [{"meaning": "睁大眼睛。", "cites": [{"t": "盱,张目也。从目,于声。", "b": "《说文》"}, {"t": "乃盱衡而诰曰。", "b": "左思《魏都赋》。注:“举眉大视也。”"}, {"t": "盱盱然。", "b": "《荀子·非十二子》"}, {"t": "盱衡厉色,振扬武器。", "b": "《汉书·王莽传》"}], "words": [{"w": "盱目(张目),盱盱(张目直视", "t": ""}, {"w": "盱视", "t": "张目直视。"}]}, {"meaning": "睁开眼睛向上看;仰望。", "cites": [{"t": "盱,仰目也。", "b": "《龙龛手鉴》"}], "words": [{"w": "盱眙", "t": "张目向上看"}, {"w": "盱睢", "t": "张目仰视。"}]}, {"meaning": "扩大。", "cites": [{"t": "又广盱营表,发人冢墓,断截骸骨,暴扬尸柩。", "b": "《汉书·谷永传》"}, {"t": "云何其盱。", "b": "《诗·小雅·何人斯》"}]}]}]','jingmo-wenyan');
