('3905wx','旻','1','mín','日','8','','[{"pinyin": "mín", "defs": [{"meaning": "(形声。从日,文声。本义:秋天)。"}, {"meaning": "同本义。", "cites": [{"t": "旻,秋天也。", "b": "《说文》"}, {"t": "钦若旻天。", "b": "《书·尧典》"}, {"t": "号泣于旻天。", "b": "《孟子·舜往于田》"}, {"t": "旻无疾威。", "b": "《诗·小雅·雨无止》"}, {"t": "不吊旻天。", "b": "《书·多士》"}, {"t": "旻天兮清朗。", "b": "王逸《哀岁》"}], "words": [{"w": "旻宇", "t": "秋天"}, {"w": "旻序", "t": "秋为旻天,故称秋季为“旻序”"}, {"w": "旻云", "t": "秋天的云。"}]}, {"meaning": "天空。", "cites": [{"t": "茫茫大块,悠悠高旻。", "b": "陶渊明《自祭文》"}], "words": [{"w": "天旻;旻天", "t": "泛指天"}, {"w": "旻穹", "t": "苍天"}, {"w": "旻苍", "t": "苍天,上苍。"}]}, {"meaning": "忧患。", "cites": [{"t": "化未期月,遘此竺旻。", "b": "汉·《平与令薛君碑》"}]}]}]','jingmo-wenyan');
