('3924wx','岿','1','kuī','山','8','','[{"pinyin": "kuī", "defs": [{"meaning": "(形声。从山,归声。本义:小山丛列)。"}, {"meaning": "同本义。", "cites": [{"t": "山小而众,岿。", "b": "《尔雅·释山》"}]}, {"meaning": "高峻独立的。", "cites": [{"t": "唯巨石岿然挺立耳。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "岿然独存", "t": "坚固独存而屹立不摇的样子"}, {"w": "岿然不动;岿崎", "t": "山势险峻的样子"}, {"w": "岿嶻", "t": "高峻。"}]}, {"meaning": "高大。", "cites": [{"t": "岿岿穹崇。", "b": "《文选·王延寿·鲁灵光赋》"}, {"t": "而灵光岿然独存。", "b": "《文选·王延寿·鲁灵光殿赋序》"}], "words": [{"w": "岿嵬", "t": ""}]}]}]','jingmo-wenyan');
