('3927wx','帙','1','zhì','巾','8','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从巾,失声。本义:包书套子,用布帛制成)。"}, {"meaning": "同本义。", "cites": [{"t": "帙,书衣也。", "b": "《说文》。今人谓之函。"}, {"t": "合为三帙,三十卷。", "b": "唐·陆德明《经典释文序》"}], "words": [{"w": "帙帷", "t": "包书的布套。"}]}, {"meaning": "书;书的卷册、卷次。", "cites": [{"t": "聚帙数万,多朱黄涂乙处。", "b": "宋·叶适《京西运判方公神道碑》"}, {"t": "诗赋篇帙繁多,不入《诗经》,而自为—略。", "b": "清·章学诚《校雠通义·补校“汉艺文志”》"}], "words": [{"w": "道帙", "t": "道家的书"}, {"w": "一帙", "t": "一册书;一套书。"}]}, {"meaning": "整理书籍。", "cites": [{"t": "书乱谁能帙,杯干自可添。", "b": "杜甫《晚晴》"}]}]}]','jingmo-wenyan');
