('3933wx','剀','1','kǎi','刂','8','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从刀,豈声。本义:大镰) 同本义。", "cites": [{"t": "剀,大镰也。切地以芟刈者,亦名鉊。字亦作鐖。", "b": "《说文》"}, {"t": "鐖凿棘矜也。", "b": "《史记·淮南衡山传》"}]}, {"meaning": "磨,磨刀。", "cites": [{"t": "剀…一曰摩也。", "b": "《说文》"}, {"t": "剀,磨也。", "b": "《广雅》"}]}, {"meaning": "规劝,讽喻。", "cites": [{"t": "言古以剀今,讽刺也。", "b": "《周礼》注"}], "words": [{"w": "言古以剀今;剀拂", "t": "劝戒匡正"}, {"w": "剀讽", "t": "讽喻。"}]}, {"meaning": "杀;砍。", "cites": [{"t": "郡王这里是帝辇之下…如何胡乱剀得人?", "b": "《警世通言》"}]}, {"meaning": "中肯,切实。", "cites": [{"t": "其辞恳直剀。", "b": "《元史·朵罗台传》"}], "words": [{"w": "剀直", "t": "恳切直率"}, {"w": "剀切", "t": "与事理完全吻合"}, {"w": "剀到", "t": "切实周到"}, {"w": "剀易", "t": "切实平易"}, {"w": "剀挚", "t": "恳切真挚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3934wx','帔','1','pèi','巾','8','','[{"pinyin": "pèi", "defs": [{"meaning": "(形声。从巾,皮声。巾,裹头或缠束、覆盖用的织物。本义:裙)。"}, {"meaning": "同本义。", "cites": [{"t": "弘农谓裙帔也。", "b": "《说文》"}]}, {"meaning": "一种类似僧人袈裟的衣服。", "cites": [{"t": "其服黄帔,乃是古贤之衣。", "b": "《笑道论》"}]}]}]','jingmo-wenyan');
