INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3936wx','沓','1','dá tà ta','水','8','','[{"pinyin": "dá", "defs": [{"meaning": "借指叠起来的纸张或薄的东西。", "cites": [{"t": "此诗今在案沓卷中。", "b": "宋·俞文豹《吹剑录》"}]}]}, {"pinyin": "tà", "defs": [{"meaning": "(会意。从水,从曰。说话多象水流。曰,说。本义:话多)。"}, {"meaning": "同本义。", "cites": [{"t": "沓,语多沓沓也。", "b": "《说文》"}, {"t": "噂沓背憎", "b": "《诗·小雅·十月之交》"}], "words": [{"w": "沓舌", "t": "多舌,多话"}, {"w": "沓沓", "t": "语多的样子。"}]}, {"meaning": "众多;重叠。", "cites": [{"t": "香炉瀑布遥相望,回崖沓嶂凌苍苍。", "b": "李白《庐山谣寄卢侍御虚舟》"}], "words": [{"w": "重沓", "t": "重复繁冗"}, {"w": "沓飒(群舞的样子),沓合(重叠", "t": ""}, {"w": "沓障", "t": "沓嶂。重重叠叠的山峰"}, {"w": "沓拖", "t": "相重的样子。"}]}, {"meaning": "会合,合。", "cites": [{"t": "天何所沓?十二焉分?", "b": "《楚辞·屈原·天问》"}]}, {"meaning": "在行进中击鼓。", "cites": [{"t": "沓鼓扬钲,南庭朔方知远近?", "b": "明·汤显祖《紫箫记》"}]}]}, {"pinyin": "ta", "defs": [{"meaning": "——见“疲沓”（píta）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3937wx','囹','1','líng','囗','8','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从囗(wéi),表示与被围有关。令声。本义:囹圄(yǔ):监狱) 同本义。", "cites": [{"t": "囹,狱也。", "b": "《说文》"}, {"t": "囹圄,周之狱名也。", "b": "《华严音义》引《说文》"}, {"t": "省囹圄。", "b": "《礼记·月令》。注:“所以禁守系者,若今之别狱矣。”"}, {"t": "囹,领也,圄,御也,领录囚徒禁御之也。", "b": "《释名》"}, {"t": "囹,令也,圄,与也。言令人幽闭思愆,改恶为善因原之也。", "b": "《风俗通》"}, {"t": "下险疑坠井,守官类拘囹。", "b": "唐·韩愈《答张彻》"}, {"t": "屏医却药疾良已,破械空囹盗自消。", "b": "宋·陆游《晚凉述怀》"}], "words": [{"w": "囹圉", "t": "牢狱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3938wx','罔','1','wǎng','冂','8','','[{"pinyin": "wǎng", "defs": [{"meaning": "(形声。从网,亡声。本义:渔猎用的网)。"}, {"meaning": "同本义。同“网”。", "cites": [{"t": "[伏羲]作结绳而为罔罟,以佃以渔,盖取诸离。", "b": "《易·系辞下》"}, {"t": "死于罔罟。", "b": "《庄子·逍遥游》"}, {"t": "列卒满泽,罘罔弥山。", "b": "《汉书·司马相如列传》"}, {"t": "是罔民也。", "b": "《孟子·梁惠王上》"}, {"t": "罔民而可为也。", "b": ""}], "words": [{"w": "罔置", "t": "泛指捕猎的网具"}, {"w": "罔罟", "t": "渔猎时所用的罗网"}, {"w": "罔罗", "t": "渔猎所用的网。同罗网。"}]}, {"meaning": "法网。", "cites": [{"t": "天之降罔,维其优矣。", "b": "《诗·大雅》"}]}, {"meaning": "迷惑。失意", "cites": [{"t": "学而不思则罔。", "b": "《论语·为政》"}, {"t": "罔流涕以聊虑兮,惟著意而得之。", "b": "《楚辞·宋玉·九辩》"}, {"t": "罔然若酲,朝罢夕倦。", "b": "《文选·张衡·东京赋》"}, {"t": "秦人逄氏有子,少而惠,及壮而有迷罔之疾。", "b": "《列子·周穆王》"}], "words": [{"w": "罔殆", "t": "迷惘模糊"}, {"w": "罔罔", "t": "惘惘,惶惶。心神不定的样子"}, {"w": "罔然", "t": "即惘然。失意的样子;心中若有所失的样子;犹茫然、恍惚不解的样子"}, {"w": "罔两", "t": "心神恍惚,无所依据。"}]}, {"meaning": "结网。", "cites": [{"t": "罔薛荔兮为帷,擗蕙榜兮既张。", "b": "《楚辞》。王逸注:“罔,结也;结薜荔为帷帐。”"}]}, {"meaning": "诬,无中生有。", "cites": [{"t": "衣服在躬,而不知其名为罔。", "b": "《礼记·少仪》"}, {"t": "罔上害民。", "b": "《风俗通义·过誉》"}], "words": [{"w": "罔利", "t": "渔利"}, {"w": "罔贪", "t": "奸诈贪婪。"}]}, {"meaning": "欺骗;蒙蔽。", "cites": [{"t": "自古谗言罔行,君臣、父子、夫妇、昆弟之间,皆不能免。", "b": "《金瓶梅》"}], "words": [{"w": "罔上", "t": "欺骗君上"}, {"w": "罔主", "t": "欺骗君主"}, {"w": "罔民", "t": "欺骗陷害百姓"}, {"w": "罔冒", "t": "欺骗冒充"}, {"w": "罔辟", "t": "欺骗君主"}, {"w": "罔惑", "t": "欺枉蛊惑"}, {"w": "罔渎", "t": "欺枉轻慢"}, {"w": "罔人", "t": "欺骗、欺诈他人"}, {"w": "罔己", "t": "受人欺骗陷害。"}]}, {"meaning": "表示禁止或劝阻,相当于“别”、“不要”。", "cites": [{"t": "罔失法度,罔游于逸,罔淫于乐。又:罔违道以干百姓之誉。", "b": "《书·大禹谟》"}]}, {"meaning": "无;没有。", "cites": [{"t": "以谨罔极。", "b": "《诗·大雅·民劳》"}, {"t": "罔敷求先王。", "b": "《诗·大雅·抑》"}, {"t": "罔,无也。", "b": "《尔雅·释言》"}, {"t": "君罔谓汝何之。", "b": "《楚辞·九章·惜诵》"}, {"t": "罔有不韪。", "b": ""}, {"t": "上罔显于羲皇。", "b": "扬雄《剧秦美新》"}, {"t": "罔不因势象形。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "罔瞻冠服", "t": "比喻没有见过汉人"}, {"w": "罔恤民隐", "t": "不管百姓的隐忧"}, {"w": "罔生", "t": "苟活"}, {"w": "罔死", "t": "白白地死"}, {"w": "罔伏", "t": "无所藏匿"}, {"w": "罔莫", "t": "无不"}, {"w": "罔恤", "t": "无忧无虑"}, {"w": "罔知", "t": "不知"}, {"w": "罔顾", "t": "不顾。"}]}, {"meaning": "不。", "cites": [{"t": "世人罔究壶中景,象外春光亿万年。", "b": "《西游记》"}], "words": [{"w": "罔已", "t": "犹不尽"}, {"w": "罔既", "t": "不尽"}, {"w": "罔效", "t": "不能报效"}, {"w": "罔措", "t": "不知所措;无所适从"}, {"w": "罔替", "t": "不更换;不废除"}, {"w": "罔惑", "t": "不惑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3939wx','钍','1','tǔ','钅','8','','[{"pinyin": "tǔ", "defs": [{"meaning": "一种放射性的四价金属元素,以化合物的形式存在于矿物内(例如独居石和钍石),通常与稀土金属连系在一起,主要作为质量数为232的同位素,半衰期为1.39×1010年,放射出α粒子而形成新钍1 ——元素符号Th。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3940wx','钎','1','qiān','钅','8','','[{"pinyin": "qiān", "defs": [{"meaning": "钎子 。打凿孔眼的工具,常用于采掘工程。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3941wx','钏','1','chuàn','钅','8','','[{"pinyin": "chuàn", "defs": [{"meaning": "臂镯的古称。俗称镯,镯子。用珠子或玉石等穿起来做成的镯子。", "cites": [{"t": "环臂谓之钏。", "b": "《通俗文》"}], "words": [{"w": "钏臂", "t": "臂镯、手镯。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3942wx','钒','1','fán','钅','8','','[{"pinyin": "fán", "defs": [{"meaning": "一种灰色或白色的、有延展性的多价金属元素,它耐空气、海水、碱腐蚀并还原氢氟酸以外的酸。它主要用作钒钢的成分  ——元素符号V。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3943wx','钕','1','nǚ','钅','8','','[{"pinyin": "nǚ", "defs": [{"meaning": "稀土族的一种淡黄色三价金属元素,主要和铈、镧及镨一起存在于独居石矿砂中,生成粉红色的盐,主要用其氧化物给玻璃和瓷器上紫色,原子序数60 ——元素符号Nd。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3944wx','钗','1','chāi','钅','8','','[{"pinyin": "chāi", "defs": [{"meaning": "(形声。从金,叉声。本义:古代妇女的一种首饰,形似叉,用金、玉、铜等制作 )。"}, {"meaning": "同本义。", "cites": [{"t": "钗,笄属。", "b": "《说文新附》。徐铉曰:“本只作叉,此字后人所加。”"}, {"t": "钿合金钗寄将去。", "b": "唐·白居易《长恨歌》"}], "words": [{"w": "钗钏", "t": "泛指妇女的饰物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3945wx','邾','1','zhū','阝','8','','[{"pinyin": "zhū", "defs": [{"meaning": "古国名。", "cites": [{"t": "邾,周武王时所封曹姓国也。始封之君曰侠,为鲁附庸。从邑,朱声。", "b": "《说文》"}]}, {"meaning": "在今山东邹县。"}, {"meaning": "古邑名 。战国楚地,楚宣王灭邾国,迁其君于此,故名。在今湖北省黄冈县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3946wx','迮','1','zé','辶','8','','[{"pinyin": "zé", "defs": [{"meaning": "迫;逼迫。", "cites": [{"t": "迮,迫也。从辵,乍声。", "b": "《说文》"}, {"t": "邻舍比里,共相压迮。", "b": "《后汉书·陈忠传》"}]}, {"meaning": "压;榨。", "cites": [{"t": "迮取汁,如饴饧。", "b": "《齐民要术》"}]}, {"meaning": "狭窄。", "cites": [{"t": "山道迮狭,前后不得相救。", "b": "《三国志·张飞传》"}]}, {"meaning": "仓促。", "cites": [{"t": "今若是迮而与季子国,季子犹不受也。", "b": "《公羊传·襄公二十九年》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
