INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3948wx','竺','1','zhú','竹','8','','[{"pinyin": "zhú", "defs": [{"meaning": "(形声。从二,竹声。本义:竹)。"}, {"meaning": "同本义。", "cites": [{"t": "竺,竹也。", "b": "《广雅》。王念孙疏证:“竺、竹同声字。方言有重轻,故又谓竹为竺也。”"}]}, {"meaning": "印度古译名“天竺”的简称。", "cites": [{"t": "双匣犹传竺国经。", "b": "林景熙《梦中作》"}], "words": [{"w": "竺经", "t": "佛经"}, {"w": "竺国", "t": "天竺。古印度的别称"}, {"w": "竺域", "t": "指天竺。即今印度"}, {"w": "竺土", "t": "指天竺国。指古印度。"}]}, {"meaning": "山名 ,在浙江省杭州市西灵隐山飞来峰之南,分上中下三天竺,俗称三竺。", "cites": [{"t": "朝游三竺,暮宿两峰。", "b": "《西湖佳话》"}]}, {"meaning": "古代的一种乐器。", "cites": [{"t": "高渐离击竺。", "b": "《战国策·燕策》"}, {"t": "非丝非竺。", "b": "宋·欧阳修《醉翁亭记》"}]}, {"meaning": "与佛教、佛典有关的。", "cites": [{"t": "闲吟竺仙偈,清绝过于玉。", "b": "前蜀·贯休《夜雨》"}], "words": [{"w": "竺法", "t": "佛法"}, {"w": "竺乾", "t": "佛,佛法"}, {"w": "竺书", "t": "佛书;佛经"}, {"w": "竺学", "t": "佛学"}, {"w": "竺教", "t": "又称“佛乾氏”。即佛教。"}]}]}]','jingmo-wenyan');
