INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3950wx','佶','1','jí','亻','8','','[{"pinyin": "jí", "defs": [{"meaning": "正。", "cites": [{"t": "佶,正也。从人,吉声。", "b": "《说文》"}]}, {"meaning": "健壮。", "cites": [{"t": "四牡既佶。", "b": "《诗·小雅·六月》"}], "words": [{"w": "佶傈", "t": "慓悍雄壮的样子。"}]}]}]','jingmo-wenyan');
