INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3952wx','佰','1','bǎi','亻','8','','[{"pinyin": "bǎi", "defs": [{"meaning": "(会意。从人,百声。“百”又兼表字义。本义:百人之长)。"}, {"meaning": "古代军队中统率百人的长官。", "cites": [{"t": "佰,相什佰也。", "b": "《说文》"}]}, {"meaning": "古代军队编制单位,十人为什,百人为佰。"}, {"meaning": "“百”的大写。", "cites": [{"t": "有仟佰之得。", "b": "《汉书·食货志上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3953wx','侑','1','yòu','亻','8','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从人,有声。本义:劝食)。"}, {"meaning": "同本义。", "cites": [{"t": "以为酒食,以享以祀,以妥以侑,以介景福。", "b": "《诗·小雅·楚茨》"}], "words": [{"w": "侑劝", "t": "劝人吃喝"}, {"w": "侑食", "t": "劝食,侍奉尊长进食"}, {"w": "侑酒", "t": "劝酒;为饮酒者助兴。"}]}, {"meaning": "配享;从祀。", "cites": [{"t": "少师佐成祖,为靖难首勋,侑享太庙。", "b": "《帝京景物略》"}], "words": [{"w": "侑祠", "t": "配享,以后死的功臣、贤哲附祭于祖庙"}, {"w": "侑饷", "t": "配享"}, {"w": "侑坐", "t": "配坐。"}]}]}]','jingmo-wenyan');
