INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3955wx','臾','1','yú','臼','8','','[{"pinyin": "yú", "defs": [{"meaning": "(会意。《说文》:“从申,从乙。”不详。双音词“须臾”,片刻,一会儿)捆住拖拉。", "cites": [{"t": "极天云一线异色,须臾成五彩。", "b": "清·姚鼐《登泰山记》"}]}, {"meaning": "善。", "cites": [{"t": "臾,善也。", "b": "《集韵》"}]}, {"meaning": "肥沃的", "cites": [{"t": "郡县上臾之壤,守之若干。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3956wx','岱','1','dài','山','8','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从山,代声。本义:泰山的别称。也叫“岱宗”、“岱岳”。)。"}, {"meaning": "同本义。", "cites": [{"t": "岱,太山也。从山,代声。", "b": "《说文》。朱按,在今山东泰安府泰安县北。"}, {"t": "河东岱。", "b": "《尔雅》。按,此言岱与华岳恒衡为五镇之一也。"}, {"t": "则有九镇。又泰山为东岳。", "b": "《周礼·职方式》。按,此言岱与华霍恒嵩为五岳之长也。唐虞则言四岳,霍即衡山。"}, {"t": "东方为岱宗者,言万物更相代于东方也。", "b": "《白虎通·巡狩》"}, {"t": "太山王者告代之处,为五岳之宗,故曰岱宗。", "b": "《后汉书·安帝纪》注"}, {"t": "古树森齐,聒聒幽禽鸣远岱。", "b": "《西游记》"}], "words": [{"w": "岱斗", "t": "泰山、北斗"}, {"w": "岱舆", "t": "传说中的海上仙山。"}]}, {"meaning": "古国名 。在今河北省蔚县东北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3957wx','侗','1','dòng tóng tǒng','亻','8','','[{"pinyin": "dòng", "defs": [{"meaning": "诚实忠厚。"}]}, {"pinyin": "tóng", "defs": [{"meaning": "幼稚无知。", "cites": [{"t": "狂而不直,侗而不愿。", "b": "《论语·泰伯》"}], "words": [{"w": "倥侗", "t": "蒙昧无知。"}]}, {"meaning": "样子轻佻。", "cites": [{"t": "毋侗好轶。", "b": "《史记》"}]}, {"meaning": "幼童,未成年的男性。", "cites": [{"t": "侗,未成器之人。", "b": "《集韵》"}, {"t": "在后之侗,敬迓天威。", "b": "《书·顾命》"}]}]}, {"pinyin": "tǒng", "defs": [{"meaning": "长大;直。", "cites": [{"t": "侗,大貌。从人,同声。", "b": "《说文》"}, {"t": "侗,状也。", "b": "《方言十二》。按,谓壮也。"}], "words": [{"w": "侗长", "t": "长大"}, {"w": "侗侗", "t": "长大的样子。"}]}, {"meaning": "通达无障碍。", "cites": [{"t": "能侗然乎?", "b": "《庄子》。郭象注:“无节碍也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3958wx','侃','1','kǎn','亻','8','','[{"pinyin": "kǎn", "defs": [{"meaning": "刚直,刚强正直。", "cites": [{"t": "侃然正色,论前世事。", "b": "欧阳修《与高司谏书》"}], "words": [{"w": "侃直", "t": "刚正;梗直"}, {"w": "侃然", "t": "刚直貌。"}]}, {"meaning": "和乐的样子。", "cites": [{"t": "我徒侃尔,乐亦在而。", "b": "《汉书·韦贤传》"}], "words": [{"w": "侃然", "t": "和乐的样子"}, {"w": "侃尔", "t": "和乐的样子。"}]}, {"meaning": "海阔天空地瞎扯。", "cites": [{"t": "隔墙酬和都瞎侃。", "b": "王实甫《西厢记》"}], "words": [{"w": "侃直", "t": "直抒己见,无所避忌"}, {"w": "别侃了", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3959wx','侏','1','zhū','亻','8','','[{"pinyin": "zhū", "defs": [{"meaning": "短小。", "cites": [{"t": "侏,短也。", "b": "《广雅·释诂》"}, {"t": "侏儒不可使援。", "b": "《国语·晋语》"}], "words": [{"w": "侏优", "t": "侏儒与优伶。"}]}, {"meaning": "侏侏 ,无所知的样子。", "cites": [{"t": "修侏侏,比于朱儒。", "b": "《太玄经·童》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3960wx','侩','1','kuài','亻','8','','[{"pinyin": "kuài", "defs": [{"meaning": "牙侩。两伙人之间的中间人或代理人等。", "cites": [{"t": "合市人也。", "b": "《声类》"}, {"t": "子货金钱千贯,节驵侩。", "b": "《汉书·货殖列传》。注:“合会二家交易者。”"}], "words": [{"w": "市侩;侩父", "t": "伢侩"}, {"w": "侩佞", "t": "指唯利是图的奸佞小人。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3961wx','佻','1','tiāo','亻','8','','[{"pinyin": "tiāo", "defs": [{"meaning": "(形声。从人,兆声。本义:轻薄,言语举止随便,不庄重) 同本义。", "cites": [{"t": "佻,愉也。", "b": "《说文》"}, {"t": "视民不佻。", "b": "《诗·小雅·鹿鸣》"}, {"t": "佻,偷也。", "b": "《尔雅》"}, {"t": "奸人为佻。", "b": "《国语·周语》"}, {"t": "雄鸠之鸣逝兮,予犹恶其佻巧。", "b": "《楚辞·离骚》"}, {"t": "险躁佻反覆,谓之“智”。", "b": "《韩非子·诡使》"}], "words": [{"w": "佻巧", "t": "轻薄取巧"}, {"w": "佻脱", "t": "轻佻草率"}, {"w": "佻率", "t": "轻薄草率"}, {"w": "佻横", "t": "轻薄骄横"}, {"w": "佻险", "t": "轻薄阴险"}, {"w": "佻轻", "t": "刻薄轻率"}, {"w": "佻环", "t": "轻薄浪荡"}, {"w": "佻狡", "t": "轻浮而狡滑"}, {"w": "佻侻", "t": "轻率简单"}, {"w": "佻急", "t": "轻躁,轻率急躁"}, {"w": "佻谬", "t": "轻率荒谬。"}]}, {"meaning": "窃取。", "cites": [{"t": "而卻至佻天之功以为己力,不亦难乎?", "b": "《国语·周语中》"}, {"t": "或佻窃虚名,而躬自为之。", "b": "《抱扑子·外篇·刺骄》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3962wx','佾','1','yì','亻','8','','[{"pinyin": "yì", "defs": [{"meaning": "古时乐舞的行列。", "cites": [{"t": "佾,舞行列也。", "b": "《说文新附》"}, {"t": "舞夏公六佾、侯四佾。", "b": "《谷梁传》"}, {"t": "佾,列也。", "b": "《广雅》"}, {"t": "八佾以舞大夏。", "b": "《礼记·祭统》"}, {"t": "八佾舞于庭。", "b": "《论语》"}], "words": [{"w": "佾舞", "t": "排列成行,纵横人数相同的古代舞蹈。按西周奴隶制等级规定,天子用八佾,六十四个;诸侯用六佾,三十六人"}, {"w": "佾生", "t": "佾舞生,乐舞生。清代孔庙中担任祭祀乐舞的人员。文的执羽旄,武的执十戚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3963wx','侪','1','chái','亻','8','','[{"pinyin": "chái", "defs": [{"meaning": "(形声。从人,齐声。本义:同辈,同类的人) 同本义。又称:侪辈。", "cites": [{"t": "侪,等輩也。", "b": "《说文》"}, {"t": "侪,耦也。", "b": "《汉书·扬雄传》注"}, {"t": "吾侪小人。", "b": "《左传·宣公十一年》"}, {"t": "晋郑同侪。", "b": "《左传·僖公二十三年》"}, {"t": "故先王之喜怒皆得其侪焉。", "b": "《礼记·乐记》。注:“犹輩类。”"}, {"t": "文王犹用众,况吾侪乎?", "b": "《左传·成公二年》"}, {"t": "此故吾侪同说书者也,今富贵若此!", "b": "清·黄宗羲《柳敬亭传》"}], "words": [{"w": "同侪", "t": "同辈的人。"}]}, {"meaning": "一起。", "cites": [{"t": "长幼侪居。", "b": "《列子·汤问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3964wx','佼','1','jiǎo','亻','8','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从人,交声。本义:美好)。"}, {"meaning": "同本义。", "cites": [{"t": "佼人僚兮。", "b": "《诗·陈风·月出》。朱注:“佼人,美人也。”释文:“佼,本作姣。”"}, {"t": "君子由之佼以好。", "b": "《荀子·成相》注:“佼,亦好也。”"}, {"t": "养壮佼。", "b": "《礼记·月令》。注:“谓形容佼好。”"}, {"t": "量之无佼民之辞。", "b": "《孔子家语·入官》。注:“犹好也。”"}, {"t": "面目佼好则使之。", "b": "《墨子·尚贤中》"}, {"t": "陈平贫而饮食不足,貌体佼好。", "b": "《论衡·骨相》"}, {"t": "侗长佼好。", "b": "《论衡·上世之人》"}, {"t": "卿所谓铁中铮铮,庸中佼佼者也。", "b": "《后汉书·刘盆子传》。李贤注:“言佼佼者,凡佣之人稍为胜也。”"}], "words": [{"w": "佼人", "t": "美人"}, {"w": "佼好", "t": "美好"}, {"w": "佼易", "t": "美好和气"}, {"w": "佼健", "t": "美好和善。"}]}, {"meaning": "狡诈的。", "cites": [{"t": "而燕雀佼之,以为不能与之争于宇宙之间。", "b": "《淮南子·览冥》"}, {"t": "好佼反而行私请。", "b": "《管子·七臣七主》。注:“谓很诈也。”"}], "words": [{"w": "佼诡", "t": "狡诈诡谲"}, {"w": "佼黠", "t": "狡猾奸诈。"}]}, {"meaning": "挠,扰。", "cites": [{"t": "草木不摇,而燕雀佼之。", "b": "《淮南子·览冥》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3965wx','佯','1','yáng','亻','8','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从人,羊声。本义:假装) 同本义。", "cites": [{"t": "张仪佯去秦。", "b": "《史记·屈原贾生列传》"}, {"t": "佯为予赵城。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "乡民佯败。", "b": "《广东军务记》"}], "words": [{"w": "佯讶", "t": "假装吃惊"}, {"w": "佯推死", "t": "装死"}, {"w": "佯打耳睁", "t": "装聋作哑,心不在焉"}, {"w": "佯佯不睬", "t": "故作轻慢,不予理睬"}, {"w": "佯长", "t": "扬长。大模大样"}, {"w": "佯常", "t": "佯长"}, {"w": "佯呆", "t": "假装麻木迟钝;假装痴笨"}, {"w": " 佯北", "t": "假装败退"}, {"w": "佯败", "t": "诈败, 假装失败。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3966wx','侬','1','nóng','亻','8','','[{"pinyin": "nóng", "defs": [{"meaning": "(形声。从人,农声。本义:我)。"}, {"meaning": "同本义。", "cites": [{"t": "人道横江好,侬道横江恶。", "b": "唐·李白《横江词》"}], "words": [{"w": "侬阿", "t": "我"}, {"w": "侬家", "t": "我"}, {"w": "侬辈", "t": "我等。"}]}, {"meaning": "古时吴越一带称他人为“侬”。", "cites": [{"t": "鸡亭故侬去,九里新侬还。", "b": "《乐府诗集》"}]}, {"meaning": "人。泛指一般人。", "cites": [{"t": "鸡亭故侬去,九里新侬还。", "b": "《寻阳乐》"}, {"t": "赫赫盛阳月,无侬不握扇。", "b": "《乐府诗集》"}]}, {"meaning": "侬人,在广西云南交界地区居住的壮族。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3967wx','帛','1','bó','巾','8','','[{"pinyin": "bó", "defs": [{"meaning": "(形声。从巾,白声。甲骨文字形,上面是“白”字,下面是“巾”字。本义:丝织品的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "王所赐金帛,归尽藏之。", "b": "汉·刘向《列女传》"}, {"t": "大帛之冠。", "b": "《左传·闵公二年》"}, {"t": "执玉帛者万国。 ", "b": "《淮南子·原道》"}, {"t": "孤执皮帛。", "b": "《周礼·大宗伯》"}, {"t": "礼云礼云,玉帛云乎哉?", "b": "《论语·阳货》"}, {"t": "乃丹书帛曰:“陈胜王。”", "b": "《史记·陈涉世家》"}, {"t": "瓦缝参差,如周身之帛缕。", "b": "杜牧《阿房宫赋》"}, {"t": "牺牲玉帛,弗敢加也,必以信。", "b": "《左传·庄公十年》"}], "words": [{"w": "布帛", "t": "棉织品和丝织品的总称"}, {"w": "玉帛;财帛;帛召", "t": "写在帛上的诏书"}, {"w": "帛画", "t": "画在丝织物上的图画。"}]}, {"meaning": "指帛书。", "cites": [{"t": "简蠹帛裂,三写易字。", "b": "《文心雕龙》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3968wx','阜','1','fù','阜','8','','[{"pinyin": "fù", "defs": [{"meaning": "(象形。甲骨字形,像山崖边的石磴形。用以表示地势或升降等意义。阜作左边偏旁,楷书写成阝。本义:土山)。"}, {"meaning": "同本义。", "cites": [{"t": "阜,大陆也。山无石者,象形。", "b": "《说文》"}, {"t": "无石曰阜。", "b": "《广雅·释丘》"}, {"t": "如山如阜,如冈如陵。", "b": "《诗·小雅·天保》"}, {"t": "诸象以鼻破阜。", "b": "牛肃《纪闻》"}], "words": [{"w": "阜陵", "t": "丘陵"}, {"w": "阜陆", "t": "高地"}, {"w": "阜丘", "t": "土山"}, {"w": "阜垤", "t": "小土丘"}, {"w": "土阜", "t": "土山。"}]}, {"meaning": "泛指山。", "cites": [{"t": "有物于此,生于山阜,处于室堂。", "b": "《荀子·赋》"}], "words": [{"w": "阜颠", "t": "山顶"}, {"w": "阜积", "t": "堆积如山。"}]}, {"meaning": "丰富;富有。", "cites": [{"t": "是时世平道治,民物阜康。", "b": "晋·常璩《华阳国志》"}], "words": [{"w": "阜财", "t": "财富殷盛"}, {"w": "阜康", "t": "富庶安康"}, {"w": "阜货", "t": "财货盛多。"}]}, {"meaning": "高。", "cites": [{"t": "泛泛淇右,有堂孔阜。", "b": "元·虞集《赋卫节妇王妇人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3969wx','侔','1','móu','亻','8','','[{"pinyin": "móu", "defs": [{"meaning": "(形声。从人,牟声。本义:等同;齐等;相等)。"}, {"meaning": "同本义。", "cites": [{"t": "侔,齐等也。", "b": "《说文》"}, {"t": "侔也者,比辞而俱行也。", "b": "《墨子·小取》"}, {"t": "权之以眡其轻重之侔也。", "b": "《考工记·轮人》"}, {"t": "疏数必侔。", "b": "《考工记·弓人》"}, {"t": "畸于人而侔于天。", "b": "《庄子·大宗师》。司马注:“等也。”"}, {"t": "智侔则有数者禽无数。", "b": "《淮南子》"}], "words": [{"w": "侔尊", "t": "等尊,齐尊"}, {"w": "侔德", "t": "德业相等"}, {"w": "侔名", "t": "齐名;名望相等"}, {"w": "侔迹", "t": "与他人的行为、业迹相等"}, {"w": " 侔拟", "t": "拟,比。"}]}, {"meaning": "谋取;求。", "cites": [{"t": "静默以侔免。", "b": "《管子·宙合》。注:“取也。”"}], "words": [{"w": "侔利", "t": "谋取利益。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3970wx','徂','1','cú','彳','8','','[{"pinyin": "cú", "defs": [{"meaning": "(形声。从彳(chì)且声。从“彳”,表示与行走有关。本义:往;去)。"}, {"meaning": "同本义。", "cites": [{"t": "徂,往也。", "b": "《尔雅》"}, {"t": "汝徂征。", "b": "《书·大禹谟》"}, {"t": "胤后承王命徂征。", "b": "《书·胤征》"}, {"t": "自我徂尔。", "b": "《诗·卫风·氓》"}, {"t": "我征徂西。", "b": "《诗·小雅·小明》"}], "words": [{"w": "徂川", "t": "流去的河水"}, {"w": "徂徕", "t": "往复"}, {"w": "徂征", "t": "前往征讨。"}]}, {"meaning": "及,至。", "cites": [{"t": "后先相继,自夏徂秋。", "b": "李渔《闲情偶寄·种植部》"}, {"t": "自堂徂基,自羊徂牛。", "b": "《诗·周颂·丝衣》"}]}, {"meaning": "行,行走。", "cites": [{"t": "思无邪,思马斯徂。", "b": "《诗·鲁颂·駉》"}]}, {"meaning": "死亡。", "cites": [{"t": "二十有八载,放勋乃徂落,百姓如丧考妣。", "b": "《孟子·万章上》"}, {"t": "于嗟徂兮,命之衰矣!", "b": "《史记·伯夷列传》"}], "words": [{"w": "徂殁", "t": "死亡"}, {"w": "徂落", "t": "死亡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3971wx','刽','1','guì','刂','8','','[{"pinyin": "guì", "defs": [{"meaning": "割断,砍断。", "cites": [{"t": "刽,断也。从刀,会声。今大辟刑人之隶。俗语谓之刽子手。", "b": "《说文》"}, {"t": "刽刖困于赤绂。", "b": "京房本《易·困》"}, {"t": "刽子磨旗提刀,押正旦带枷上。", "b": "《窦娥冤》"}], "words": [{"w": "刽子", "t": "执行死刑的人"}, {"w": "刽伍", "t": "刽子手之辈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3972wx','郄','1','xì','阝','8','','[{"pinyin": "xì", "defs": [{"meaning": "(同“郤”。也作“隙”)。"}, {"meaning": "空隙;裂缝。", "cites": [{"t": "郄,同隙。", "b": "《正字通》"}, {"t": "刺郄中大脉,令人仆,脱色。", "b": "《素问》"}]}, {"meaning": "古地名。", "cites": [{"t": "郤,地名。晋大夫叔虎邑。或作郄。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3973wx','怂','1','sǒng','心','8','','[{"pinyin": "sǒng", "defs": [{"meaning": "(形声。从心,从声。本义:惊慌)。"}, {"meaning": "同本义。", "cites": [{"t": "怂,惊也。", "b": "《说文》"}, {"t": "将乍往而未半,怵悼慄而怂兢。", "b": "《文选·张衡·西京赋》"}], "words": [{"w": "怂兢", "t": "惊惧。"}]}, {"meaning": "怂恿。", "cites": [{"t": "提学御史房寰恐见纠擿,欲先发,给事中钟宇淳复怂惥,寰再上疏丑诋。", "b": "《明史·海瑞传》"}], "words": [{"w": "怂恧", "t": "从旁鼓动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3974wx','籴','1','dí','米','8','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从入,从米,翟声。本义:买进粮食) 同本义 (跟“粜”相对)。", "cites": [{"t": "你来籴米,将银子来我秤。", "b": "《陈州粜米》"}], "words": [{"w": "籴米", "t": "买米"}, {"w": "籴粜", "t": "粮食的买进和卖出。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3975wx','瓮','1','wèng','瓦','8','','[{"pinyin": "wèng", "defs": [{"meaning": "(形声。从瓦,公声。本义:陶制盛器,小口大腹)。"}, {"meaning": "同本义。", "cites": [{"t": "罋,汲缾也。", "b": "《说文》"}, {"t": "瓮,瓶也。", "b": "《广雅·释器》"}, {"t": "罋,瓶也。", "b": ""}]}, {"meaning": "按,“瓶”是汲水器,不是今天的所谓瓶。", "cites": [{"t": "抱甕而出灌。", "b": "《庄子·天地》。释文:“甕,字亦作瓮。”"}], "words": [{"w": "瓮水", "t": "一瓮所装的水"}, {"w": "瓮问", "t": "瓮下"}, {"w": "瓮牖", "t": "以破瓮为窗,指贫寒之家"}, {"w": "瓮头春", "t": "酒瓮的口"}, {"w": "瓮天蠡海", "t": "自瓮窥天,以瓢测海。喻识见知浅。"}]}, {"meaning": "汲水罐。", "cites": [{"t": "井谷射鲋,瓮敝漏。", "b": "《易·井》"}]}, {"meaning": "盛酒浆的坛。", "cites": [{"t": "宋襄公葬其夫人,醯醢百瓮。", "b": "《礼记》"}]}, {"meaning": "大水缸。", "cites": [{"t": "四渎之浊,不方瓮水之清。", "b": "晋·葛洪《抱朴子》"}]}, {"meaning": "装于瓮中。", "cites": [{"t": "好事者信之,没日至,或取以酿酒,或开禊泉茶馆,或瓮而卖及馈送有司。", "b": "清·张岱《陶庵梦忆》"}]}, {"meaning": "使声音变沉。", "cites": [{"t": "野水吞人面,青山瓮马声。", "b": "《随园诗话》引春台《塞外》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3976wx','戗','1','qiāng qiàng','戈','8','','[{"pinyin": "qiāng", "defs": [{"meaning": "冲突,决裂。", "cites": [{"t": "两个说戗了,揪着领子,一顿乱打。", "b": "《儒林外史》"}]}]}, {"pinyin": "qiàng", "defs": [{"meaning": "撑,支撑。", "cites": [{"t": "用把椅子戗在背后。", "b": "老舍《骆驼祥子》"}], "words": [{"w": "戗柱", "t": "从旁支撑房屋的木柱"}, {"w": "戗住墙;戗劲;戗得住", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3977wx','肼','1','jǐng','月','8','','[{"pinyin": "jǐng", "defs": [{"meaning": "一种无色发烟的、具有腐蚀性和强还原性的液体化合物NH2NH2,它是比氨弱的碱,通常由水合肼脱水制得,主要用作火箭和喷气发动机的燃料部分,用在制备盐(如硫酸盐)及有机衍生物中。"}]}]','jingmo-wenyan');
