('3979wx','肽','1','tài','月','8','','[{"pinyin": "tài", "defs": [{"meaning": "酰胺之一 。它是由两个或多个氨基酸通过一个氨基酸的氨基与另一个氨基酸的羧基结合而成。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3980wx','肱','1','gōng','月','8','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从肉,厷(gōng)声。本义:上臂,手臂由肘到肩的部分)。"}, {"meaning": "同本义 后多引伸泛指洛膊。", "cites": [{"t": "肘臂节也。", "b": "《说文》。段注:“厷与臂之节曰肘,股与胫之节曰膝。《深衣》支‘胳之高下,可以运肘。袂之长短,反诎之及肘。’注云:‘肘当臂中为节,臂骨上下各二寸。’按:上谓厷,下谓臂匑也。”"}, {"t": "麾之以肱,毕来既升。", "b": "《诗·小雅·元差别》。朱熹集注:“但以手麾之,使来则毕来,使升则既升也。”"}, {"t": "曲肱而枕之。", "b": "《论语》"}]}, {"meaning": "比喻帝王的卿佐。", "cites": [{"t": "洸洸司徒公,天子股与肱。", "b": "唐·韩愈诗"}, {"t": "股肱之臣", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3981wx','肫','1','zhūn','月','8','','[{"pinyin": "zhūn", "defs": [{"meaning": "面颊。", "cites": [{"t": "肫,面颊也。", "b": "《说文》"}, {"t": "肫,俗谓之两颧也。", "b": "朱骏声《说文通训定声》"}]}, {"meaning": "臀。", "cites": [{"t": "胯大肫高,决片牛唇口,粗能饮村酒。", "b": "《刘知远诸宫调》"}]}, {"meaning": "恳切,真挚。", "cites": [{"t": "夫焉有所倚,肫肫其仁,渊渊其渊,浩浩其天。", "b": "《礼记·中庸》"}], "words": [{"w": "肫切", "t": "真诚恳切"}, {"w": "肫宏", "t": "诚挚而宽宏"}, {"w": "肫肫", "t": "诚恳"}, {"w": "肫肫煦煦", "t": "形容恳挚而热忱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3982wx','剁','1','duò','刂','8','','[{"pinyin": "duò", "defs": [{"meaning": "斫,砍。", "cites": [{"t": "无声细下飞碎雪,有骨已剁觜春葱。", "b": "唐·杜甫《阌乡姜七少府设绘戏赠长歌》"}, {"t": "你便剁做我七八段,也是去不得了。", "b": "《水浒传》"}], "words": [{"w": "把柳条剁成三段;剁肉馅;剁鲊", "t": "该死的,挨刀的。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3983wx','迩','1','ěr','辶','8','','[{"pinyin": "ěr", "defs": [{"meaning": "(形声。从辵(chuò),尔声。本义:近)。"}, {"meaning": "同本义。", "cites": [{"t": "迩,近也。", "b": "《说文》"}, {"t": "柔远能迩。", "b": "《虞书》"}, {"t": "父母孔迩。", "b": "《诗·周南·汝坟》"}, {"t": "节远迩之期也。", "b": "《礼记·郊特性》"}, {"t": "戎事不迩女器。", "b": "《左传·僖公二十二年》"}, {"t": "既而敌行益迩。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "举类迩而见义远。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "迩来", "t": "近来"}, {"w": "遐迩", "t": "远近"}, {"w": "迩人", "t": "近人;亲近的人"}, {"w": "迩日", "t": "近日;近来"}, {"w": "迩年", "t": "犹近年"}, {"w": "迩狭", "t": "近"}, {"w": "迩时", "t": "近时,近来。"}]}, {"meaning": "浅。", "cites": [{"t": "维迩言是听,维迩言是争。", "b": "《诗·小雅·小旻》"}], "words": [{"w": "迩文", "t": "浅近的文章。"}]}, {"meaning": "接近。", "cites": [{"t": "公正则不迩谗邪。", "b": "韩愈《释言》"}], "words": [{"w": "迩月", "t": "接近一个月的时间"}, {"w": "迩续", "t": "犹接近。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3984wx','郇','1','huán xún','阝','8','','[{"pinyin": "huán", "defs": [{"meaning": "姓", "cites": [{"t": "郇,姓。出绛州。", "b": "《广韵》"}]}]}, {"pinyin": "xún", "defs": [{"meaning": "周朝国名 。姬姓。周文王子封于此。春秋时为晋地。在今山西临猗县南。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3985wx','狙','1','jū','犭','8','','[{"pinyin": "jū", "defs": [{"meaning": "猕猴。", "cites": [{"t": "众狙皆怒。", "b": "《庄子·齐物论》"}], "words": [{"w": "狙狯", "t": "猿猴一类的野兽"}, {"w": "狙杙", "t": "系猴的木桩;谓猴椽木"}, {"w": "狙猿", "t": "猿猴。"}]}, {"meaning": "窥伺;伏伺。", "cites": [{"t": "从狙而好小察。", "b": "《管子·七臣七主》"}], "words": [{"w": "狙刺", "t": "伏伺行刺"}, {"w": "狙狙", "t": "伺察的样子"}, {"w": "狙候", "t": "伏伺;觊觎"}, {"w": "狙觑", "t": "窥视"}, {"w": "狙缚", "t": "伺伏擒缚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3986wx','狎','1','xiá','犭','8','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从犬,甲声。从犬,犬善与人玩耍。本义:驯犬)。"}, {"meaning": "同本义。", "cites": [{"t": "狎,犬可习也。", "b": "《说文》"}, {"t": "故欲以刑罚慈民,辟其犹以鞭狎狗也,虽久弗亲矣。", "b": "《新书》"}]}, {"meaning": "驯养。", "cites": [{"t": "夫龙之为虫也,柔可狎而骑也。", "b": "《韩非子》"}, {"t": "驯乌逐饭磬,狎兽绕禅林。", "b": "南朝陈·沈炯诗"}], "words": [{"w": "狎兽", "t": "驯顺之兽。"}]}, {"meaning": "亲昵,亲近而不庄重。", "cites": [{"t": "稍近,益狎。", "b": "唐·柳宗元《三戒》"}, {"t": "而狎风雨。", "b": "宋·苏轼《教战守》"}, {"t": "自此狎媟无间。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "狎而不甘问焉。", "b": "清·刘开《问说》"}], "words": [{"w": "狎游", "t": "嬉戏亲昵"}, {"w": "狎浪", "t": "淫秽放浪"}, {"w": "狎侮", "t": "轻慢;侮辱"}, {"w": "狎熟", "t": "亲昵、熟悉"}, {"w": "狎慢", "t": "亲热轻慢"}, {"w": "狎媟", "t": "亲昵而近于放荡"}, {"w": "狎笑", "t": "亲昵嬉笑。"}]}, {"meaning": "亲近;接近。", "cites": [{"t": "狎习于乱而容于治,故郑人不能归。", "b": "《韩非子·南面》"}, {"t": "见齐衰者,虽狎,必变。", "b": "《论语·乡党》"}], "words": [{"w": "狎弄", "t": "亲近戏弄"}, {"w": "狎近", "t": "亲近"}, {"w": "狎异", "t": "亲近异常。"}]}, {"meaning": "不重视或不注意。", "cites": [{"t": "礼,君不使无耻,不近刑人,不狎敌,不迩怨。", "b": "《谷梁传·襄公二十九年》"}], "words": [{"w": "狎侮", "t": "轻视;忽视"}, {"w": "狎敌", "t": "轻敌"}, {"w": "狎视", "t": ""}]}, {"meaning": "交替。", "cites": [{"t": "自无令王,诸侯逐进,狎主齐盟,其又可壹乎?", "b": "《左传·昭公元年》。杜预注:“强弱无常,故更主盟。”"}], "words": [{"w": "狎主", "t": "交替主持。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3987wx','狍','1','páo','犭','8','','[{"pinyin": "páo", "defs": [{"meaning": "狍子。鹿的一种。", "cites": [{"t": "钩吾之山,有兽焉,名曰狍鴞。", "b": "《山海经·北山经》"}, {"t": "那些野鸡、獐、狍各样野味,分些给他们就是了。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3988wx','狒','1','fèi','犭','8','','[{"pinyin": "fèi", "defs": [{"meaning": "兽名。狒狒。", "cites": [{"t": "如何顾洄老钓徒,笑人不监狒被格。", "b": "清·孙枝蔚《次韵答莫大岸见嘲》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3989wx','咎','1','jiù','口','8','','[{"pinyin": "jiù", "defs": [{"meaning": "(会意。从人,从各。从“各”,表示相违背。违背人的心愿。本义:灾祸,灾殃)。"}, {"meaning": "同本义。", "cites": [{"t": "咎,灾也。", "b": "《说文》"}, {"t": "弃宝者必离其咎。", "b": "《吕氏春秋·侈乐》。注:“殃也。”"}, {"t": "嗟苦先生,独离此咎。", "b": "贾谊《吊屈原赋》"}], "words": [{"w": "咎征", "t": "天降灾祸的征验"}, {"w": "咎有应得", "t": "罹祸受罚是由于自己的原因,完全应得的"}, {"w": "咎戒", "t": "上天所降的灾祸与警告。"}]}, {"meaning": "过失,罪过。", "cites": [{"t": "无咎者,善补过也。", "b": "《易·系辞》"}, {"t": "其作汝用咎。", "b": "《书·洪范》。疏:“咎是过之别名。”"}, {"t": "微我有咎。", "b": "《诗·小雅·伐木》"}, {"t": "以彰其咎。", "b": "诸葛亮《出师表》"}], "words": [{"w": "咎戾", "t": "罪过"}, {"w": "咎责", "t": "罪责,罪过"}, {"w": "咎省", "t": "引过反省"}, {"w": "咎累", "t": "罪过的牵累"}, {"w": "咎过", "t": "过错"}, {"w": "咎恶", "t": "罪恶。"}]}, {"meaning": "责备,追究罪过。", "cites": [{"t": "楚人既咎。", "b": "《史记·屈原贾生列传》"}, {"t": "咎其欲出者。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "咎罪", "t": "怪罪"}, {"w": "咎毁", "t": "归咎怪罪,诋毁"}, {"w": "既往不咎;自咎", "t": ""}]}, {"meaning": "憎恶。", "cites": [{"t": "殷始咎周。", "b": "《书·西伯戡黎》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3990wx','炙','1','zhì','火','8','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意。从肉从火。小篆字形,肉在火上烤。本义:烧烤,把去毛的兽肉串起来在火上薰烤)。"}, {"meaning": "同本义。", "cites": [{"t": "炙,炮肉也。从肉,在火上。", "b": "《说文》。按,炮当作灼。"}, {"t": "火傍作庶为炙字,凡傅于火曰燔,母之而加于火曰炙,裹而烧者曰炮。柔者炙之,乾者燔之。", "b": "《颜氏家训》"}, {"t": "毋嘬炙。", "b": "《礼记·曲礼》。疏:“火灼曰炙。”"}, {"t": "以烹以炙。", "b": "《礼记·礼运》"}, {"t": "置匕首鱼炙之腹中。", "b": "《史记·刺客传》"}, {"t": "有兔斯首,燔之炙之。", "b": "《诗·小雅·瓠叶》"}, {"t": "饮醇酒,炙肥牛。", "b": "《乐府诗集·西门行》"}], "words": [{"w": "炙煿", "t": "烤爆。比喻受折磨"}, {"w": "炙肉", "t": "烤肉"}, {"w": "炙羊", "t": "烤羊肉"}, {"w": "炙鼠", "t": "烤鼠"}, {"w": "炙鱼", "t": "烧鱼。"}]}, {"meaning": "烧灼人体。", "cites": [{"t": "翼侯炙。", "b": "《韩非子·难言》"}, {"t": "炙胡巫上林中。", "b": "《汉书·戾太子传》。注:“烧也。”"}, {"t": "而况于亲炙之者乎。", "b": "《孟子》"}], "words": [{"w": "炙面", "t": "烧灼面孔"}, {"w": "炙灼", "t": "烧灼。"}]}, {"meaning": "曝晒。", "cites": [{"t": "野人有快炙背而美芹子者,欲献之至尊。", "b": "《与山巨源绝交书》"}], "words": [{"w": "炙灼", "t": "曝晒"}, {"w": "炙浪", "t": "烤人的热浪"}, {"w": "炙阳", "t": "让太阳曝晒。"}]}, {"meaning": "受熏陶。", "cites": [{"t": "久仰芳名,无由亲炙。", "b": "《红楼梦》"}]}, {"meaning": "中药炮制法之一。把药材与液汁辅料同炒,使辅料渗入药材之内。", "cites": [{"t": "炙甘草八分。", "b": "《红楼梦》"}]}, {"meaning": "烤熟的肉食。", "cites": [{"t": "把吃剩的残羹冷炙,翻的各处都是。", "b": "《官场现形记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3991wx','枭','1','xiāo','木','8','','[{"pinyin": "xiāo", "defs": [{"meaning": "(会意。从鸟,头在木上。本义:指一种恶鸟,捕捉后悬头树上以示众)。"}, {"meaning": "猫头鹰。", "cites": [{"t": "枭,不孝鸟也。日至捕枭磔之,从枭头在木上。", "b": "《说文》"}, {"t": "用一枭破镜。", "b": "《汉书·郊祀志》。注:“孟康曰,枭鸟食母,破镜兽食父,黄帝欲绝其类,使百吏祠皆用之。如淳曰,汉五月五日作枭羹以赐百官。”"}, {"t": "为枭为鸱。", "b": "《诗·大雅·瞻卬》"}, {"t": "射游枭。", "b": "《汉书·司马相如传》"}, {"t": "鸱枭群翔。", "b": "《汉书·郊祀志》"}, {"t": "枭鸣松桂枝。", "b": "唐·白居易《凶宅》诗"}], "words": [{"w": "枭奴", "t": "凶狠的奴仆"}, {"w": "枭獍", "t": "枭镜。相传枭为食母恶鸟,獍为食父恶兽。比喻凶恶忘恩的人。"}]}, {"meaning": "“枭”假借为“骁”,最勇健。", "cites": [{"t": "且太子所与俱诸将,皆尝与上定天下枭将也。", "b": "《史记·留侯世家》"}, {"t": "为天下枭。", "b": "《淮南子·原道》。注:“雄也。”"}, {"t": "枭为最勇健也。", "b": "《汉书·张良传》注"}, {"t": "枭犹胜也。犹六博得枭则胜。", "b": "《后汉书·张衡传》注"}, {"t": "刘备,天下枭雄。", "b": "《资治通鉴》"}], "words": [{"w": "枭恶", "t": "勇猛凶恶"}, {"w": "枭张", "t": "猖狂;放肆"}, {"w": "枭将;枭骑", "t": "勇猛健壮的骑兵。"}]}, {"meaning": "悬头示众。", "cites": [{"t": "枭故塞王欣头。", "b": "《汉书·高帝纪》。注:“悬首于木上。”"}, {"t": "枭俊禽敌之臣。", "b": "《汉书·陈汤传》"}, {"t": "幸而破绍,枭其二子。", "b": "曹操《让县自明本志令》"}], "words": [{"w": "枭示", "t": "枭斩。砍头悬挂示众"}, {"w": "枭夷", "t": "诛杀净尽"}, {"w": "枭除", "t": "诛杀清除。"}]}, {"meaning": "淆乱。", "cites": [{"t": "饰邪说,文奸言,以枭乱天下。", "b": "《荀子·非十二子》"}]}, {"meaning": "昭示;宣布。", "cites": [{"t": "可再作一判文,以枭秦桧父子夫妇之过。", "b": "《说岳全传》"}]}, {"meaning": "挡;推。", "cites": [{"t": "岳大爷又把枪轻轻一举,将梁王的刀枭过一边。", "b": "《说岳全传》"}]}, {"meaning": "撩。", "cites": [{"t": "枭开帐子,让张聋子亲自来看。", "b": "《官场现形记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3992wx','饯','1','jiàn','饣','8','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从食,戋(qiān)声。本义:设酒食送行)。"}, {"meaning": "同本义。", "cites": [{"t": "餞,送去食也。", "b": "《说文》"}, {"t": "饯,送行馈饥也。", "b": "《字林》"}, {"t": "饮饯于祢。", "b": "《诗·邶风·泉水》"}, {"t": "乃饯。", "b": "《仪礼·士虞礼记》"}, {"t": "季文子饯之。", "b": "《左传·成公八年》"}, {"t": "郑六卿饯宣子于郊。", "b": "《左传·昭公十六年》"}], "words": [{"w": "饯路", "t": "外出时所给予的馈赠"}, {"w": "饯花会", "t": "为花举行的饯别会"}, {"w": "饯席", "t": "饯别的酒席"}, {"w": "饯客", "t": "设酒为客人饯行。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3993wx','饴','1','yí','饣','8','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从食,台(yí)声。本义:饴糖,用麦芽制成的糖) 同本义。", "cites": [{"t": "饴,米煎也。", "b": "《说文》"}, {"t": "饴,畅也。", "b": "《广雅》"}, {"t": "枣栗饴蜜。以甘之。", "b": "《礼记·内则》"}, {"t": "甘如饴蜜。", "b": "《论衡·本性》"}], "words": [{"w": "饴浆", "t": "用米及麦芽为原料而制成的糖浆"}, {"w": "饴蜜", "t": "饴糖与蜂蜜"}, {"w": "饴饧", "t": "饴和饧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3994wx','冽','1','liè','冫','8','','[{"pinyin": "liè", "defs": [{"meaning": "寒冷。亦作“洌”。", "cites": [{"t": "有冽氿泉,无浸获薪。", "b": "《诗·小雅·大东》"}, {"t": "秋风冽冽,白露为朝霜。", "b": "左思《杂诗》"}], "words": [{"w": "冽冽", "t": "寒冷的样子"}, {"w": "冽风", "t": "寒风"}, {"w": "冽厉", "t": "寒冷而猛烈。"}]}, {"meaning": "清澄。", "cites": [{"t": "下见小潭,水尤清冽。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "冽香", "t": "清香"}, {"w": "冽泉", "t": "清泉"}, {"w": "清冽", "t": "清澈。"}]}]}]','jingmo-wenyan');
