INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3996wx','庖','1','páo','广','8','','[{"pinyin": "páo", "defs": [{"meaning": "(形声。从广(yǎn),包声。广,表示房屋。本义:厨房)。"}, {"meaning": "同本义。", "cites": [{"t": "庖,厨也。", "b": "《说文》"}, {"t": "徒御不惊,大庖不盈。", "b": "《诗·小雅·车攻》"}, {"t": "庖有肥肉。", "b": "《孟子·梁惠王上》"}, {"t": "客逾庖而宴。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "庖鼎", "t": "厨房里烹调的器具"}, {"w": "庖厨", "t": "厨房"}, {"w": "庖屋", "t": "厨房"}, {"w": "庖宰", "t": "受宰于厨房"}, {"w": "庖突", "t": "厨房的烟囱"}, {"w": "庖廪", "t": "厨房和粮仓。"}]}, {"meaning": "厨师。", "cites": [{"t": "良庖岁更刀。", "b": "《庄子·养生主》"}]}, {"meaning": "又。", "cites": [{"t": "庖丁为文惠君解牛。", "b": ""}, {"t": "三为充君之庖。", "b": "《礼记·王制》"}], "words": [{"w": "庖人", "t": "周礼官名。天官之属,掌膳食。泛指厨师"}, {"w": "庖正", "t": "掌理膳食的长官"}, {"w": "庖丁解牛", "t": "喻神妙的技艺的典型"}, {"w": "庖宰", "t": "庖厨。厨工"}, {"w": "庖阎", "t": "厨工和守门人。"}]}, {"meaning": "烹调。", "cites": [{"t": "东坡以烹龙庖凤之手。", "b": "杨万里《西溪先生和陶诗序》"}], "words": [{"w": "庖馔", "t": "烹调"}, {"w": "庖脍", "t": "指脍、炙佳肴"}, {"w": "庖霜", "t": "细切的鱼肉片。因色白如霜,故称"}, {"w": "庖膳", "t": "膳食"}, {"w": "庖炙", "t": "烧烤肉"}, {"w": "庖正", "t": "掌管饮食官"}, {"w": "庖羞", "t": "喻执政之臣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3997wx','疠','1','lì','疒','8','','[{"pinyin": "lì", "defs": [{"meaning": "恶疮;麻风。", "cites": [{"t": "疠,恶疾也。", "b": "《说文》"}, {"t": "伯牛有疾,先儒以为疠也。", "b": "《论语》"}, {"t": "已大风挛踠瘘疠。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "疠风", "t": "麻风病"}, {"w": "疠人", "t": "患染恶疾的人"}, {"w": "疠痎", "t": "恶性疟疾。"}]}, {"meaning": "疫病 ［pestilence］。", "cites": [{"t": "四时皆有疠疾。", "b": "《周礼·疾医》"}, {"t": "天有菑疠。", "b": "《左传·哀公六年》"}], "words": [{"w": "疠疾", "t": "疠瘥。疫病"}, {"w": "疠气", "t": "能致疫病的恶气"}, {"w": "疠疫", "t": "瘟疫"}, {"w": "疠役", "t": "流行性传染病。即瘟疫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3998wx','疝','1','shàn','疒','8','','[{"pinyin": "shàn", "defs": [{"meaning": "心腹气痛。", "cites": [{"t": "疝,腹痛也。从疒,山声。", "b": "《说文》"}, {"t": "腹痛不得大小便,病名曰疝。", "b": "《素问·长俠节论》"}, {"t": "五藏六府疝十六病四十卷。", "b": "《汉书·艺文志》。注:“心腹气病。”"}], "words": [{"w": "疝瘕", "t": "病名,腹中气郁积结块所致。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('3999wx','疡','1','yáng','疒','8','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从疒(chuáng),昜(yáng)声。本义:痈疮) 同本义。", "cites": [{"t": "疡,头创也。", "b": "《说文》"}, {"t": "头有创曰疡。", "b": "《释名》"}, {"t": "庀疡者造焉。", "b": "《周礼·医师》。注:“身伤曰疡。”"}, {"t": "骨干疡为微。", "b": "《尔雅》"}, {"t": "头有创则沐,身有疡则浴。", "b": "《礼记》"}], "words": [{"w": "疡子", "t": "泛指疮"}, {"w": "疡痍", "t": "痈疮、创伤"}, {"w": "疡医", "t": "周代医官之一。后世指治疮伤的外科医生。"}]}, {"meaning": "破损,溃烂。", "cites": [{"t": "皮肤疡溃。", "b": "《素问·风论》"}], "words": [{"w": "胃溃疡;疡溃", "t": "破损溃烂"}, {"w": "疡微", "t": "溃疡。喻腐朽现象。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4000wx','兖','1','yǎn','亠','8','','[{"pinyin": "yǎn", "defs": [{"meaning": "中国水名。", "cites": [{"t": "河东郡垣县,“有王屋山,兖水出”。", "b": "《续汉书·郡国志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4001wx','妾','1','qiè','女','8','','[{"pinyin": "qiè", "defs": [{"meaning": "(会意。从辛,从女。甲骨文字形上面是“ň”(qiān)字,即古代刑刀,表示有罪,受刑。下面是“女”字。合而表示有罪的女子。本义:女奴)。"}, {"meaning": "同本义。", "cites": [{"t": "妾,有罪女子给事者。", "b": "《说文》"}, {"t": "八月臣妾。", "b": "《周礼·太宰》"}, {"t": "纳女工妾三十人。", "b": "《国语·晋语》"}, {"t": "臣妾逋逃。", "b": "《书·费誓》"}]}, {"meaning": "妻子之外另娶的女人。", "cites": [{"t": "《春秋传》曰:“女为人妾,妾不娉也。”", "b": "《说文》"}, {"t": "梁嬴孕卜曰:将生一男一女。男为人臣,女为人妾。故名,男曰圉,女曰妾。", "b": "《左传·僖公十七年》"}, {"t": "得妾以其子。", "b": "《易·鼎》"}, {"t": "兑为妾。", "b": "《易·说卦传》"}, {"t": "聘则为妻,奔则为妾。", "b": "《礼记·内则》"}, {"t": "有妻有妾。", "b": "《礼记·曲礼》"}, {"t": "毋以妾为妻。", "b": "《谷梁传》"}, {"t": "复问其妾。", "b": "《战国策·齐策》"}, {"t": "妾得无随乎。", "b": "汉·刘向《列女传》"}, {"t": "遂宠妾媵。清·周容《芋老人传》", "b": ""}], "words": [{"w": "妾媵", "t": "随嫁的人;泛指妾"}, {"w": "妻妾", "t": "妻与妾"}, {"w": "妾妃", "t": "姬妾"}, {"w": "妾侍", "t": "姬妾侍女之辈"}, {"w": "妾妇", "t": "小妻;侧室。"}]}, {"meaning": "旧时妇女自称的谦词。", "cites": [{"t": "妾不堪驱使,徒留无所施。", "b": "古乐府《孔雀东南飞》"}, {"t": "妾事其父。", "b": "汉·刘向《列女传》"}, {"t": "妾闻志士不饮盗泉之水。", "b": "《后汉书·列女传》"}, {"t": "必以告妾。", "b": "清·林觉民《与妻书》"}, {"t": "妾愿随君行》", "b": ""}], "words": [{"w": "妾人", "t": "女子谦卑的自称"}, {"w": "妾身", "t": "旧时女子谦称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4002wx','劾','1','hé','力','8','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从力,亥声。本义:审理,判决)。"}, {"meaning": "同本义。", "cites": [{"t": "劾,法有辜也。", "b": "《说文》"}, {"t": "上其鞫劾文辞。", "b": "《书·吕刑》传"}]}, {"meaning": "疏:“汉世问罪谓之鞫,断狱谓之劾。”。", "words": [{"w": "劾死", "t": "判决死罪"}, {"w": "劾治", "t": "审理治罪"}, {"w": "劾按", "t": "审理核实罪状"}, {"w": "劾捕", "t": "审查其罪,加以逮捕"}, {"w": "劾验", "t": "审理查验。"}]}, {"meaning": "检举揭发罪状。", "cites": [{"t": "劾大不敬。", "b": "《汉书·李广苏建传》"}, {"t": "遣其劾帅。", "b": "清·梁启超《谭嗣同传》"}, {"t": "齐康所劾。", "b": "《明史》"}, {"t": "戴凤翔劾瑞。", "b": ""}, {"t": "弹劾不避权贵。", "b": "《金史·雷渊传》"}], "words": [{"w": "弹劾;劾状", "t": "弹劾,举发罪状"}, {"w": "劾奏", "t": "检举或弹劾其罪状。"}]}, {"meaning": "检举揭发的文书。", "cites": [{"t": "滂睹时方艰,知意不行,因投劾去。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4003wx','炜','1','huī wěi','火','8','','[{"pinyin": "huī", "defs": [{"meaning": "光;光辉", "words": [{"w": "炜如", "t": "有光彩的样子"}, {"w": "炜然", "t": "有光彩的样子"}, {"w": "炜发", "t": "火光迸发"}, {"w": "炜煜", "t": "辉煌显耀"}, {"w": "炜煌", "t": "辉煌"}]}]}, {"pinyin": "wěi", "defs": [{"meaning": "(形声。从火,韦声。本义:火光明亮)。"}]}]','jingmo-wenyan');
