INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4009wx','泔','1','gān','氵','8','','[{"pinyin": "gān", "defs": [{"meaning": "淘米水,洗过米的水。", "cites": [{"t": "周谓潘曰泔。从水,甘声,淅米汁也。", "b": "《说文》"}, {"t": "有水浊如泔。", "b": "苏轼《东湖》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4010wx','沭','1','shù','氵','8','','[{"pinyin": "shù", "defs": [{"meaning": "水名。", "cites": [{"t": "沭,沭水也。青州浸。从水,术声。", "b": "《说文》。朱按,出今山东沂州府沂水县北沂山,流入江苏沭阳县界下流入海。"}, {"t": "其浸沂沭。", "b": "《周礼·职方式》"}]}, {"meaning": "发源于山东省南部沂山南麓,与沂水平行,经莒县南流入江苏省,经江苏入海。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4011wx','泷','1','lóng shuāng','氵','8','','[{"pinyin": "lóng", "defs": [{"meaning": "湍急的流水。", "cites": [{"t": "中夜前泷吼。", "b": "清·魏源《阳朔舟行》"}], "words": [{"w": "泷船", "t": "在急流中行驶的船。"}]}, {"meaning": "古水名  。即今山东省孝妇河。"}]}, {"pinyin": "shuāng", "defs": [{"meaning": "水名。即今武水,又名武溪 ,源出湖南省临武县境,流入广东省,经乐昌县至韶关市,与浈水合为北江,又至三水,与西江相通。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4012wx','泸','1','lú','氵','8','','[{"pinyin": "lú", "defs": [{"meaning": "古水名。泸水,又名泸江水 。指今金沙江在四川宜宾与云南四川交界处的一段。", "cites": [{"t": "故五月渡泸,深入不毛。", "b": "诸葛亮《出师表》"}]}, {"meaning": "古州名 。南朝梁大同中置。治所在江阳(今四川省泸州市)。1913年废,改为县。1950年泸县城区设市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4013wx','泱','1','yāng','氵','8','','[{"pinyin": "yāng", "defs": [{"meaning": "(形声。从水,央声。本义:水面广阔的)。"}, {"meaning": "同本义。", "cites": [{"t": "泱,滃也。", "b": "《说文》"}, {"t": "瞻波洛矣,维水泱泱。", "b": "《诗·小雅·瞻波洛矣》"}, {"t": "云山苍苍,江水泱泱。", "b": "宋·范仲淹《严先生祠堂记》"}], "words": [{"w": "泱漭", "t": "广大无涯际的样子。"}]}, {"meaning": "气魄宏大的。", "cites": [{"t": "宅大齐之墟,振泱之风。", "b": "《晋书·齐王冏传》"}], "words": [{"w": "泱泱大国", "t": ""}]}, {"meaning": "流;淌。", "cites": [{"t": "泱泱,流也。", "b": "《广雅》"}, {"t": "那佛祖轻轻用力撑开,只见上溜头泱下一个死尸。", "b": "《西游记》"}], "words": [{"w": "泱荡", "t": "荡漾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4014wx','泅','1','qiú','氵','8','','[{"pinyin": "qiú", "defs": [{"meaning": "(会意。从水,囚声。本义:游水) 游泳。", "cites": [{"t": "汓,浮行水上也。", "b": "《说文》"}, {"t": "习于水,勇于泅。", "b": "《列子·黄帝》"}], "words": [{"w": "泅儿", "t": "善游水的少年"}, {"w": "泅浮", "t": "游泳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4015wx','泗','1','sì','氵','8','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从水,四声。本义:泗水)。"}, {"meaning": "同本义。", "cites": [{"t": "泗滨浮磬。", "b": "《书·禹贡》"}, {"t": "宣公夏滥于泗渊。", "b": "《国语·鲁语》"}]}, {"meaning": "鼻涕。", "cites": [{"t": "泗,涕泗也。", "b": "《广韵》"}, {"t": "涕泗滂沱。", "b": "《诗·陈风·泽陂》。传:“自目曰涕,自鼻曰泗。”"}, {"t": "悲泗淋漓,诚怛人心。", "b": "李朝威《柳毅传》"}, {"t": "面缚两降将,跪城下说降,涕泗交颐。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "泗涕", "t": "鼻液"}, {"w": "泗涕", "t": "鼻涕和眼泪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4016wx','泠','1','líng','氵','8','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从水,令声。本义:水名,泠水)。"}, {"meaning": "同本义。即安徽的“青戈江”。", "cites": [{"t": "泠,泠水,出丹阳宛陵西北入江。", "b": "《说文》。按,亦名清水,今之清弋江也。"}]}, {"meaning": "艺人。", "cites": [{"t": "晋侯…见钟仪…,问其族,对曰:“泠人也。”", "b": "《左传·成公九年》"}], "words": [{"w": "泠人", "t": "伶人。古代乐人。"}]}, {"meaning": "清凉;冷清。", "cites": [{"t": "子能使子野尽为泠风乎?", "b": "《吕氏春秋·任地》"}, {"t": "愿乘泠风去,直出浮云间。", "b": "李白《登太白峰》"}], "words": [{"w": "泠冽", "t": "清凉,凉爽"}, {"w": "泠然", "t": "寒凉;清凉"}, {"w": "泠风", "t": "小风;和风。"}]}, {"meaning": "清澈。", "cites": [{"t": "泠泠七弦上,静听松风寒。", "b": "唐·刘长卿《听弹琴》"}], "words": [{"w": "泠波", "t": "清澈的水波。"}]}, {"meaning": "轻妙的样子。", "cites": [{"t": "列子御风而行,泠然善也。", "b": "《庄子·齐物论》。注:“轻妙之貌。”"}], "words": [{"w": "泠然", "t": "轻妙的样子。"}]}, {"meaning": "落。", "cites": [{"t": "同僚涕泠。", "b": "《冀州从事郭君碑》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4017wx','泺','1','luò','氵','8','','[{"pinyin": "luò", "defs": [{"meaning": "古水名。", "cites": [{"t": "泺,泺水,齐鲁间水也。从水,乐声。", "b": "《说文》"}, {"t": "公会齐侯于泺。", "b": "《左传·桓公十八年》"}]}, {"meaning": "源出今山东济南市西南,北流至泺口入古济水(此段古济水即今黄河)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4018wx','泖','1','mǎo','氵','8','','[{"pinyin": "mǎo", "defs": [{"meaning": "湖名。又名三泖  。在上海市青浦西南,松江西和金山西北,现已淤为平地。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4019wx','泫','1','xuàn','氵','8','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从水,玄声。本义:水珠下滴)。"}, {"meaning": "同本义。", "cites": [{"t": "泫,湝流也。", "b": "《说文》"}, {"t": "花上露犹泫。", "b": "《文选诗》"}, {"t": "孔子泫然流涕。", "b": "《礼记·檀弓》"}, {"t": "譬之桂生高岭,云露方得泫其花。", "b": "《西游记》"}, {"t": "花上露犹泫。", "b": "谢灵运《从斤竹涧越岭溪行》"}], "words": [{"w": "泫露", "t": "滴落,降露。"}]}, {"meaning": "流泪。", "cites": [{"t": "遗迹余文,触目增泫。", "b": "《陈书》"}, {"t": "相与泫然。", "b": "顾炎武《复庵记》"}], "words": [{"w": "泫目", "t": "使眼流泪。"}]}, {"meaning": "露珠晶莹的样子。", "cites": [{"t": "斐斐气幕岫,泫泫露盈条。", "b": "《文选·谢惠连文》"}], "words": [{"w": "泫泫", "t": "露珠晶莹的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4020wx','泮','1','pàn','氵','8','','[{"pinyin": "pàn", "defs": [{"meaning": "(形声。从水,半声。本义:古代天子诸侯举行宴会或作为学宫的宫殿 。也称泮宫)。"}, {"meaning": "同本义 。西南为水,东北为墙,一半有水,一半无水。", "cites": [{"t": "泮,诸侯饷射之宫。西南为水,东北为墙。", "b": "《说文》"}, {"t": "泮宫,周学也。", "b": "《礼记·明堂位》"}], "words": [{"w": "泮宫", "t": "泮宇。西周诸侯所设大学"}, {"w": "泮乡", "t": "学宫"}, {"w": "泮池", "t": "泮水。学宫前的水池。"}]}, {"meaning": "岸;水边。", "cites": [{"t": "隰则有泮。", "b": "《诗·卫风·氓》"}], "words": [{"w": "泮岸", "t": "畔岸,边际。"}]}, {"meaning": "冰雪融解。", "cites": [{"t": "迨冰未泮。", "b": "《诗·邶风·匏有苦叶》"}], "words": [{"w": "泮涣", "t": "融解;涣散"}, {"w": "泮冻", "t": "解冻。"}]}, {"meaning": "分离。", "cites": [{"t": "其脆易泮。", "b": "《老子·六十四章》"}], "words": [{"w": "泮合", "t": "判合。配合;两半相合"}, {"w": "泮坼", "t": "碎裂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4021wx','沱','1','tuó','氵','8','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从水,它声。本义:江水支流的通名)。"}, {"meaning": "同本义。", "cites": [{"t": "沱,江别流也。", "b": "《说文》"}], "words": [{"w": "沱汜", "t": "泛指江水支流。"}]}, {"meaning": "可以停船的水湾 。多用于地名。四川省有朱家沱、石盘沱等。"}, {"meaning": "沱江 。长江的支流,在四川省。"}, {"meaning": "恸哭的,泪如雨下的。", "cites": [{"t": "出涕沱若,戚嗟若。", "b": "《易·离》"}]}, {"meaning": "大雨瓢泼的样子。", "cites": [{"t": "噫欠为飘风,濯手大雨沱。", "b": "唐·韩愈《读东方朔杂事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4022wx','泯','1','mǐn','氵','8','','[{"pinyin": "mǐn", "defs": [{"meaning": "(形声。从水,民声。本义:灭,尽) 同本义。", "cites": [{"t": "泯然众人。", "b": "宋·王安石《伤仲永》"}], "words": [{"w": "泯灭,泯没", "t": ""}]}, {"meaning": "乱;混乱。", "cites": [{"t": "王室之乱,靡邦不泯。", "b": "陆机《答贾长渊》"}], "words": [{"w": "泯杂", "t": "混杂;乱杂"}, {"w": "泯泯", "t": "纷乱的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4023wx','泓','1','hóng','氵','8','','[{"pinyin": "hóng", "defs": [{"meaning": "(形声。从水,弘声。本义:水深而广)。"}, {"meaning": "同本义。", "cites": [{"t": "泓澄渊潫。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "泓泓", "t": "水深的样子"}, {"w": "泓洄", "t": "水深而回旋的样子"}, {"w": "泓净", "t": "水深且清。"}]}, {"meaning": "潭。也泛指塘、湖。", "cites": [{"t": "留斩泓下蛟,莫试街中狗。", "b": "唐·元稹《说剑》"}, {"t": "望泓面有烟云之气,飞走不定。", "b": "明·陆容《菽园杂记》"}]}, {"meaning": "古水名 。在今河南省柘城县西北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4024wx','泾','1','jīng','氵','8','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从水,巠声。本义:泾水)。"}, {"meaning": "同本义。", "cites": [{"t": "泾,泾水也。", "b": "《说文》"}, {"t": "雍州其川,泾汭。", "b": "《周礼·职方氏》"}, {"t": "泾以渭浊。", "b": "《诗·邶风·谷风》"}]}, {"meaning": "古州名 。故地在今甘肃省泾川县。"}, {"meaning": "县名 。在安徽省东南部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4025wx','怙','1','hù','忄','8','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从心,古声。本义:依仗,凭借)。"}, {"meaning": "同本义。", "cites": [{"t": "怙,恃也。", "b": "《说文》"}, {"t": "无父何怙,无母何恃。", "b": "《诗·小雅·蓼莪》"}, {"t": "怙其俊才。", "b": "《左传·宣公十五年》"}, {"t": "怙势作威。", "b": "柳宗元《封建论》"}], "words": [{"w": "怙气", "t": "仗持勇气"}, {"w": "怙终", "t": "仗恃作恶,终不悔改"}, {"w": "怙势", "t": "倚恃权势"}, {"w": "怙险", "t": "凭恃险固。"}]}, {"meaning": "父母的合称。", "cites": [{"t": "孩失其怙,幼丧所亲;旁无弟兄,藐然一身。", "b": "白居易《寄乌江十五兄文》"}]}, {"meaning": "父亲。", "cites": [{"t": "怙、恃二字,分言之,父曰怙,母曰恃…合言之,父母通谓之怙。", "b": "《正字通》"}, {"t": "六岁失怙恃,不为兄嫂所容。", "b": "《聊斋志异·珠儿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4026wx','怵','1','chù','忄','8','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从心,术声。本义:恐惧,害怕)。"}, {"meaning": "同本义。", "cites": [{"t": "怵,恐也。", "b": "《说文》"}, {"t": "怵,惧也。", "b": "《广雅》"}, {"t": "劳形怵心者也。", "b": "《庄子·应帝王》"}, {"t": "怵悼栗而耸兢。", "b": "张衡《西京赋》"}, {"t": "皆有怵惕恻隐之心。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "怵栗", "t": "恐惧"}, {"w": "怵悸", "t": "恐惧心跳"}, {"w": "怵怵", "t": "戒惧、警惕的样子。"}]}, {"meaning": "伤心。", "cites": [{"t": "心怵而奉之以礼。", "b": "《礼记·祭统》"}, {"t": "是以君子不怵乎好,不迫乎恶。", "b": "《管子·心术上》"}, {"t": "人迫于恶,则失其所好;怵于好,则忘其所恶,非道也。", "b": ""}, {"t": "得于好恶,怵于淫物,而后变乱。", "b": "《韩非子·解老》"}, {"t": "怵迫之徒,或趋西东。", "b": "《文选·贾谊·鹏鸟赋》。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
