INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4028wx','怛','1','dá','忄','8','','[{"pinyin": "dá", "defs": [{"meaning": "(形声。从心,旦声。本义:痛苦)。"}, {"meaning": "同本义。", "cites": [{"t": "怛,憯也。从心,旦声。", "b": "《说文》"}, {"t": "怛,痛也。", "b": "《方言一》"}, {"t": "疾痛惨怛,未尝不呼父母也。", "b": "《史记·屈原贾生列传》"}, {"t": "悲泗淋漓,诚怛人心。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "忧伤。", "cites": [{"t": "怛,忧也。", "b": "《广雅》"}, {"t": "怛怛,忧也。", "b": "《释训》"}, {"t": "中心怛兮。", "b": "《诗·桧风·匪风》"}, {"t": "劳心怛怛。", "b": "《诗·齐风·甫田》"}], "words": [{"w": "怛恻", "t": "忧伤"}, {"w": "怛然", "t": "忧虑,不放心的样子"}, {"w": "怛伤", "t": "悲伤"}, {"w": "怛惋", "t": "悲伤。"}]}, {"meaning": "畏惧;惊恐。", "cites": [{"t": "叱!避!无怛化!", "b": "《庄子·大宗师》"}, {"t": "怛然内热。", "b": "《列子·黄帝》"}, {"t": "群犬垂涎,扬尾皆来,其人怒;怛之。", "b": "唐·柳宗元《三戒·临江之麋》"}], "words": [{"w": "怛突", "t": "忐忑,惊惧"}, {"w": "怛怖", "t": "恐惧"}, {"w": "怛惕", "t": "惊惧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4029wx','怏','1','yàng','忄','8','','[{"pinyin": "yàng", "defs": [{"meaning": "(形声。从心,央声。《说文》:“不服怼(duì)也”。本义:不满意、不服气的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "怏,心不服也。", "b": "《说文》"}]}, {"meaning": "郁郁不乐。", "cites": [{"t": "辛垣衍怏然不悦。", "b": "《战国策》"}], "words": [{"w": "怏恨", "t": "怨恨"}, {"w": "怏悒", "t": "郁郁不乐的样子"}, {"w": "怏闷", "t": "郁闷"}, {"w": "怏怅", "t": "抱歉。"}]}, {"meaning": "勉强;强求。", "cites": [{"t": "怏他一路上汤风打浪。", "b": "元·关汉卿《拜月亭》"}, {"t": "无夜无明怏着也。", "b": "《牡丹亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4030wx','怍','1','zuò','忄','8','','[{"pinyin": "zuò", "defs": [{"meaning": "惭愧。", "cites": [{"t": "怍,惭也。从心,作省声。", "b": "《说文》。按,乍声。"}, {"t": "容无怍。", "b": "《礼记·曲礼》"}, {"t": "孝子临尸而不怍。", "b": "《礼记·祭义》"}, {"t": "灵公心怍焉。", "b": "《公羊传·宣公六年》"}, {"t": "自憎惭怍。", "b": "《聊斋志异·促织》"}]}, {"meaning": "面色改变。", "cites": [{"t": "颜色毋怍。", "b": "《管子·弟子职》。注:“谓变其容貌。”"}, {"t": "将即席,容毋怍。", "b": "《礼记·曲礼》"}]}]}]','jingmo-wenyan');
