INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4033wx','怫','1','fèi fú','忄','8','','[{"pinyin": "fèi", "defs": [{"meaning": "愤怒。", "cites": [{"t": "我怫然而怒。", "b": "《庄子·德充符》"}], "words": [{"w": "怫然", "t": "愤怒的样子"}, {"w": "怫恕", "t": "愤怒"}, {"w": "怫恚", "t": "愤怒。"}]}, {"meaning": "(bèi)。违反,逆乱。", "cites": [{"t": "五家之文怫异,维太初之元论。", "b": "《史记·太史公自序》"}, {"t": "知权者不以常人怫吾虑。", "b": "柳宗元《断刑论》"}], "words": [{"w": "怫志", "t": "逆乱的心志。"}]}]}, {"pinyin": "fú", "defs": [{"meaning": "(形声。从心,弗声。本义:抑郁;心情不舒畅)。"}, {"meaning": "同本义。", "cites": [{"t": "怫,郁也。", "b": "《说文》"}, {"t": "怫,郁也,心不安也。", "b": "《字林》"}, {"t": "太后怫郁泣血。", "b": "《汉书·邹阳传》"}]}, {"meaning": "我心何怫郁。——曹操《苦寒行》。", "words": [{"w": "怫郁", "t": "忧郁"}, {"w": "怫忾", "t": "气郁满的样子。"}]}, {"meaning": "(bó)。突然。", "cites": [{"t": "谓己謏人,则怫然作色。", "b": "《庄子·天地》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4034wx','怿','1','yì','忄','8','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从心,睪(yì)声。本义:喜悦) 同本义。", "cites": [{"t": "怿,悦也。", "b": "《说文新附》"}, {"t": "怿,悦也,乐也。", "b": "《广韵》"}, {"t": "说怿女美。", "b": "《诗·邶风·静女》"}, {"t": "辞之怿矣。", "b": "《诗·大雅·板》。传:“怿,悦也。”"}, {"t": "是故其成也怿。", "b": "《礼记·文王世子》。注:“怿,悦怿。”"}, {"t": "上不怿。", "b": "《汉书·萧何传》。师古曰:“怿,悦也。”"}, {"t": "于是秦王不怿,为一击缶。", "b": "《史记》"}], "words": [{"w": "怿怿", "t": "欢乐的样子。"}]}, {"meaning": "悦服。", "cites": [{"t": "怿,服也。", "b": "《尔雅》。郭璞注:皆谓喜而服从"}], "words": [{"w": "怿悦", "t": "使心情怡悦。"}]}, {"meaning": "更改。", "cites": [{"t": "怿,改也。自山而东,或曰悛,或曰怿。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4035wx','宕','1','dàng','宀','8','','[{"pinyin": "dàng", "defs": [{"meaning": "洞穴;洞屋。", "cites": [{"t": "宕,过也。一曰洞屋。从宀,碭省声。", "b": "《说文》。按,字从宀,洞屋当为本训。洞屋者,四围无障蔽之谓。"}]}, {"meaning": "穿过;通过。", "cites": [{"t": "邗子寻犬,宕入仙穴。", "b": "《列仙传》"}]}, {"meaning": "引申为流荡;游荡。", "cites": [{"t": "回过曰宕。", "b": "《通俗文》"}, {"t": "长狄兄弟三人佚宕中国。", "b": "《谷梁传·文公十一年》"}, {"t": "借问叹者谁,言是宕子妻。", "b": "曹植《怨歌行》"}], "words": [{"w": "宕子", "t": "荡子。到处流浪的人"}, {"w": "宕宕", "t": "无定止的样子"}, {"w": "宕落", "t": "流动而富于变化。"}]}, {"meaning": "放纵,不受约束。", "cites": [{"t": "性豪宕,不拘细行。", "b": "《金史·姬汝作传》"}], "words": [{"w": "宕往", "t": "豪爽不羁"}, {"w": "宕迈", "t": "放逸豪爽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4036wx','穹','1','qióng','穴','8','','[{"pinyin": "qióng", "defs": [{"meaning": "(形声。从穴,弓声。本义:穷尽)。"}, {"meaning": "同本义。", "cites": [{"t": "穹,穷也。从穴,弓声。", "b": "《说文》"}], "words": [{"w": "穹窒", "t": "完全堵塞。"}]}, {"meaning": "高。", "cites": [{"t": "郁并起而穹崇。", "b": "司马相如《长门赋》"}], "words": [{"w": "穹枝", "t": "犹高枝"}, {"w": "穹穹", "t": "高大的样子"}, {"w": "穹官", "t": "高官"}, {"w": "穹居", "t": "高大的住所"}, {"w": "穹宫", "t": "高大的宫室,祠堂。"}]}, {"meaning": "大。", "cites": [{"t": "穹,大也。", "b": "《尔雅·释诂》。注:“穹隆亦为大也。”"}, {"t": "穹崖巨谷。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "穹石", "t": "大岩石"}, {"w": "穹穹", "t": "高而大貌"}, {"w": "穹龟", "t": "大龟。"}]}, {"meaning": "中间隆起的拱形。亦代指天空。", "cites": [{"t": "以念穹苍。", "b": "《诗·大雅·桑柔》"}, {"t": "穹苍,苍天也。", "b": "《尔雅·释天》"}, {"t": "洒扫穹窒。", "b": "《诗·豳风·东山》。笺:“穹窒,鼠穴也。”"}], "words": [{"w": "穹隆", "t": "形容天的形状,中央高而四周下垂的形状"}, {"w": "穹窿垂像", "t": "天象"}, {"w": "苍穹;穹天", "t": "天空"}, {"w": "穹旻", "t": "即天"}, {"w": "穹昊", "t": "上天"}, {"w": "穹灵", "t": "上天的神灵"}, {"w": "穹玄", "t": "苍天。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4037wx','宓','1','mì','宀','8','','[{"pinyin": "mì", "defs": [{"meaning": "安宁。", "cites": [{"t": "宓,安也。", "b": "《说文》。段注:“此字经典作密。”"}, {"t": "宓穆休于太祖之下。", "b": "《淮南子》"}]}, {"meaning": "秘密,不公开。", "cites": [{"t": "豺牙宓厉,虺毒潜吹。", "b": "庾信《哀江南赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4038wx','诓','1','kuāng','讠','8','','[{"pinyin": "kuāng", "defs": [{"meaning": "(形声。从言,匡声。本义:欺骗)。"}, {"meaning": "同本义。", "cites": [{"t": "乃求壮士得霍人解扬,字子虎,诓楚,令宋毋降。", "b": "《史记·郑世家》"}], "words": [{"w": "我哪能诓你", "t": ""}]}, {"meaning": "骗取。", "cites": [{"t": "你常是赖了人钱,诓了人钞,苦了人物。", "b": "《雍熙乐府·一枝花》"}]}, {"meaning": "哄。", "cites": [{"t": "她又不得不止哭去诓孩子。", "b": "巴金《灭亡·八日》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4039wx','诔','1','lěi','讠','8','','[{"pinyin": "lěi", "defs": [{"meaning": "(形声。从言,耒声。本义:叙述死者生前事迹,表示哀悼,亦即为谥法所本。仅用于上对下)同本义,即今之致悼辞。", "cites": [{"t": "诔,谥也。从言,耒声。累列生时行迹,读之以作谥者。", "b": "《说文》"}, {"t": "六曰诔。", "b": "《周礼·大祝》"}, {"t": "幼不诔长。", "b": "《礼记·曾子问》"}, {"t": "诔者,道死人之志也。", "b": "《墨子·鲁问》"}, {"t": "孔丘卒,公诔之。", "b": "《左传》"}, {"t": "鲁君的嬖人死,鲁君为之诔。", "b": "《墨子》"}]}, {"meaning": "哀悼死者的文章。", "cites": [{"t": "遗之日读诔。", "b": "《周礼·大史》"}], "words": [{"w": "诔文", "t": "悼词。亦简称“诔”"}, {"w": "诔赞", "t": "列叙死者生平事迹,并且赞美其德行的文辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4040wx','诖','1','guà','讠','8','','[{"pinyin": "guà", "defs": [{"meaning": "形声。从言,圭(guī)声。本义:贻误(连累)。"}, {"meaning": "同本义。", "cites": [{"t": "诖,误也。", "b": "《说文》"}, {"t": "诖误吏民", "b": "《汉书·文帝纪》"}, {"t": "夫不顾社稷之长利,而听须臾之说,诖误人主者,无过于此者矣。", "b": "《战国策·韩策》"}], "words": [{"w": "诖误", "t": "欺蒙牵连他人犯罪"}, {"w": "诖注", "t": "错误地记载"}, {"w": "诖乱", "t": "使迷惑混乱"}, {"w": "诖谬", "t": "谬误。"}]}, {"meaning": "欺骗。", "cites": [{"t": "诖,欺也。", "b": "《广雅》"}, {"t": "诖乱天下,欲危社稷。", "b": "《史记·吴王濞列传》"}], "words": [{"w": "诖墨", "t": "欺蒙毁谤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4041wx','诘','1','jié','讠','8','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从言,吉声。本义:询问,追问)。"}, {"meaning": "同本义。", "cites": [{"t": "诘,问也。", "b": "《说文》"}, {"t": "度作刑以诘四方。", "b": "《书·吕刑》"}, {"t": "五曰刑典以诘邦国。", "b": "《周礼·大宰》"}, {"t": "毅诘之曰。", "b": "唐·李朝威《柳毅传》"}, {"t": "直诘袁曰。", "b": "清·梁启超《谭嗣同传》"}, {"t": "终不敢诘。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "反诘", "t": "反问"}, {"w": "究诘", "t": "追问究竟"}, {"w": "诘询", "t": "追问,询问"}, {"w": "诘辩", "t": "刨根问底。"}]}, {"meaning": "责备;质问。", "cites": [{"t": "诘,责也。", "b": "《广雅》"}, {"t": "诘奸慝。", "b": "《左传·昭公十四年》"}, {"t": "仲冬之月…农有不收藏积聚者,马牛畜兽有放佚者,敢之不诘。", "b": "《礼记·月令》"}], "words": [{"w": "诘逐", "t": "斥责并驱逐"}, {"w": "诘斥", "t": "斥责"}, {"w": "诘让", "t": "责斥;责让。"}]}, {"meaning": "查究;究办。", "cites": [{"t": "访缉纠诘。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "诘诈", "t": "查究奸诈之事"}, {"w": "诘诛", "t": "问罪并惩罚"}, {"w": "诘盗", "t": "究办强盗"}, {"w": "诘禁", "t": "按禁令查办。"}]}, {"meaning": "曲折。", "cites": [{"t": "研桑不能数其诘屈。", "b": "《晋书·卫恒传》"}], "words": [{"w": "诘曲", "t": "屈曲,曲折"}, {"w": "诘屈", "t": "弯曲,曲折"}, {"w": "诘诎", "t": "弯曲,曲折;抑郁,艰涩。"}]}, {"meaning": "整治。", "cites": [{"t": "制军诘禁。", "b": "《周礼·大司马》。注:“犹穷治也。”"}, {"t": "子盍诘盗。", "b": "《左传·襄公二十一年》"}], "words": [{"w": "诘戎治兵", "t": "整治军事"}, {"w": "诘武", "t": "治兵"}, {"w": "诘兵", "t": "整治兵器。"}]}, {"meaning": "明。", "cites": [{"t": "诘,《小尔雅》:“诘朝,旦明也。”", "b": "清·王玉树《说文拈字》"}], "words": [{"w": "诘旦", "t": "明天早晨"}, {"w": "诘晨", "t": "明朝,明晨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4042wx','戾','1','lì','户','8','','[{"pinyin": "lì", "defs": [{"meaning": "(会意。从犬,从户。犬从关着的门中挤出,必曲其身。本义:弯曲)。"}, {"meaning": "同本义。", "cites": [{"t": "戾,曲也。从犬,出户下身曲戾也。", "b": "《说文》"}, {"t": "饮必小咽,端直无戾。", "b": "《吕氏春秋》"}], "words": [{"w": "戾契", "t": "曲折辗转。"}]}, {"meaning": "至,到达。", "cites": [{"t": "翰飞戾天。", "b": "《诗·小雅·四月》"}, {"t": "鲁侯戾止。", "b": "《诗·鲁颂·泮水》"}, {"t": "戾于敝邑。", "b": "《国语·鲁语上》"}, {"t": "古者天灾降戾。", "b": "《国语·周语下》"}, {"t": "鸢飞戾天者。", "b": "吴均《与朱元思书》"}], "words": [{"w": "戾止", "t": "来临"}, {"w": "戾于", "t": "至于。"}]}, {"meaning": "违背,违反。", "cites": [{"t": "如子之说,文虽相反,义不相戾。", "b": "唐·韩愈《论语笔解》"}, {"t": "举事戾苍天。", "b": "《淮南子·览冥训》"}]}, {"meaning": "破裂 ［break;split］。", "cites": [{"t": "曲得其宜，无所击戾。", "b": "《淮南子·主术训》。注：“戾，破也。”"}]}, {"meaning": "扭转。", "cites": [{"t": "戾翳旋把,萦随所历。", "b": "潘岳《射雉赋》"}]}, {"meaning": "乖张;违逆。", "cites": [{"t": "戾,乖背也。", "b": "《字林》"}, {"t": "降此大戾。", "b": "《诗·小雅·节南山》"}, {"t": "又仰而呼天曰:“何为使至此极戾也?", "b": "柳宗元《天说》"}, {"t": "果敢而很,猛贪而戾。", "b": "《荀子·荣辱》"}], "words": [{"w": "乖戾", "t": "别扭,不合情理"}, {"w": "戾沓", "t": "乖戾多言"}, {"w": "戾悖", "t": "乖戾背离"}, {"w": "戾谬", "t": "乖谬。"}]}, {"meaning": "暴戾。", "cites": [{"t": "诛严不为戾。(戾残暴。)", "b": "《韩非子·五蠹》"}], "words": [{"w": "戾气", "t": "暴戾之气"}, {"w": "戾虫", "t": "老虎的别名。以虎性暴戾凶猛,故名"}, {"w": "戾夫", "t": "凶恶的人;暴戾之心"}, {"w": "戾行", "t": "砥砺操行。"}]}, {"meaning": "劲疾,猛烈。", "cites": [{"t": "劲风戾而吹帷。", "b": "晋·潘岳《秋兴赋》"}]}, {"meaning": "贪婪凶猛。", "cites": [{"t": "悍戾贪肆。", "b": "《新唐书·杨于陵传》"}]}, {"meaning": "安定,静止。", "cites": [{"t": "民之未戾,职盗为寇。", "b": "《诗·大雅·桑柔》"}]}, {"meaning": "蒙受屈辱或受到的贬抑。", "cites": [{"t": "其敢干大礼以自取戾。", "b": "《左传》"}]}, {"meaning": "罪恶,罪行。", "cites": [{"t": "余,罪戾之人也。", "b": "《国语》"}], "words": [{"w": "罪戾", "t": "罪过;罪恶。"}]}, {"meaning": "祸患。", "cites": [{"t": "天降灾戾。", "b": "《汉书·食货志下》"}]}, {"meaning": "疫病。", "cites": [{"t": "疾菑戾疫。", "b": "《墨子·尚同中》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
