INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4045wx','郓','1','yùn','阝','8','','[{"pinyin": "yùn", "defs": [{"meaning": "古地名。", "cites": [{"t": "郓,河内沁水乡。从邑,军声。", "b": "《说文》"}]}, {"meaning": "春秋鲁有二郓邑:一在今山东省沂水县北。公元前616年,季孙行父所筑。鱼莒屡次争夺,称“东郓”。一在今山东省郓城县东。公元前588年鲁成公所筑,称“西郓”。"}]}]','jingmo-wenyan');
