INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4047wx','祆','1','xiān','礻','8','','[{"pinyin": "xiān", "defs": [{"meaning": "祆教,拜火教 。波斯人琐罗亚斯特所创立,崇拜火,南北朝时传入中国。今印度、伊朗还有信徒。", "cites": [{"t": "祆,故神也。", "b": "《说文新附》"}], "words": [{"w": "袄庙", "t": "拜火教的庙宇"}, {"w": "祆祠", "t": "祆教祭祀火神的寺院。"}]}, {"meaning": "关中称天为祆。", "cites": [{"t": "祆,关中谓天为祆。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4048wx','祎','1','yī','礻','8','','[{"pinyin": "yī", "defs": [{"meaning": "(形声。从示,韦声。本义:美好) 同本义  (多用于人名)。", "cites": [{"t": "汉帝之德,俟其祎而。", "b": "张衡《东京赋》"}], "words": [{"w": "祎隋", "t": "逶迤。从容自得的样子"}, {"w": "祎祎", "t": "美好。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4049wx','祉','1','zhǐ','礻','8','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从示,止声。本义:福) 同本义。", "cites": [{"t": "祉,福也。", "b": "《说文》"}, {"t": "祉,禄也。", "b": "《左传·哀公九年》"}, {"t": "畴离祉。", "b": "《易·否》"}, {"t": "既多受祉。", "b": "《诗·小雅·六月》"}, {"t": "谓其能以嘉祉殷富生物也。", "b": "《国语·周语》"}, {"t": "维祉冠存已。", "b": "《汉书·王莽传》"}, {"t": "用锡尔祉。", "b": "《后汉书·宋宏传》。注:“谓福庆也。”"}], "words": [{"w": "祉祚", "t": "福禄;幸福"}, {"w": "祉祥", "t": "吉祥"}, {"w": "祉祐", "t": "福祐"}, {"w": "祉禄", "t": "福禄"}, {"w": "祉福", "t": "幸福。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4050wx','祇','1','qí','礻','8','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从示,氏声。本义:地神)。"}, {"meaning": "同本义。", "cites": [{"t": "祇,地祇也。", "b": "《说文》"}, {"t": "天神曰灵,地神曰祇。", "b": "《尸子》"}, {"t": "修礼地祇,谒款天神。", "b": "《史记·司马相如列传》"}, {"t": "祷尔于上下神祇。", "b": "《论语·述而》"}], "words": [{"w": "神祇", "t": "天神和地神"}, {"w": "祇园", "t": "祇洹,祇林,祇苑。祇树园。印度佛教圣地之一。后用为佛寺的代称。"}]}, {"meaning": "病患。", "cites": [{"t": "坎不盈,祇既平,无咎。", "b": "《易·坎》"}, {"t": "壹者之来,俾我祇也。", "b": "《诗·小雅·何人斯》"}]}, {"meaning": "盛大。", "cites": [{"t": "相次我师经此过,好将诚意至疧迎。", "b": "《大唐三藏取经诗话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4051wx','诛','1','zhū','讠','8','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从言,朱声。本义:声讨、谴责)。"}, {"meaning": "同本义。", "cites": [{"t": "诛,讨也。", "b": "《说文》"}, {"t": "诛,代。诛犹责也。", "b": "《白虎通》"}, {"t": "诛以驭其过。", "b": "《周礼·太宰》"}, {"t": "诛求无厌。", "b": "《左传·襄公三十一年》"}, {"t": "齿路马有诛。", "b": "《礼记·曲礼》。注:“罚也。”"}, {"t": "得志于诸侯,而诛无理,曹其首也。", "b": "《左传·僖公二十三年》"}, {"t": "于予与何诛?", "b": "《论语·公冶长》"}, {"t": "甚悖逆不轨,宜诛讨之日久矣。", "b": "汉·桓宽《盐铁论·本议》"}], "words": [{"w": "诛放", "t": "责斥其罪并予以放逐"}, {"w": "诛远", "t": "斥退疏远"}, {"w": "诛惩", "t": "声讨惩处"}, {"w": "诛心", "t": "揭露、指责人的用心。"}]}, {"meaning": "杀戮。夺去生命。", "cites": [{"t": "立诛杀曹无伤。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "诛有功之人。", "b": ""}, {"t": "不诛之则为乱。", "b": "《吕氏春秋·慎行论》"}, {"t": "广德素闻超在鄯善诛灭虏使,大惶恐。", "b": "《后汉书·班超梁慬传》"}, {"t": "能诛戮清流之朋,莫如唐昭宗之世。", "b": "宋·欧阳修《朋党论》"}, {"t": "不当诛之。", "b": "清·黄宗羲《原君》"}, {"t": "既而以吴民之乱请于朝,按诛五人。", "b": "张溥《五人墓碑记》"}, {"t": "以诛奸贼。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "诛论", "t": "以罪论死"}, {"w": "诛流", "t": "杀戮和流放"}, {"w": "诛害", "t": "杀害"}, {"w": "诛赦", "t": "杀戮与赦免。"}]}, {"meaning": "治罪,惩罚。", "cites": [{"t": "诛严不为戾。", "b": "《韩非子·五蠹》"}]}, {"meaning": "又。", "cites": [{"t": "夫离法者罪,而诸先生以文学取;犯禁者诛,而群侠以私剑养。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "而诛罚不必其后也。", "b": ""}, {"t": "故卒不加诛。", "b": "汉·刘向《列女传》"}, {"t": "原情定过,赦事诛意。", "b": "《后汉书·霍胥传》"}], "words": [{"w": "诛意", "t": "惩罚、制裁其心意。指加罪于人,不论其事迹、行事,只寻究其动机或心意"}, {"w": "诛恶", "t": "惩治作恶者"}, {"w": "诛率", "t": "惩治首恶。"}]}, {"meaning": "要求;索取。", "cites": [{"t": "诛屡于徒人费,弗得。", "b": "《左传·庄公八年》"}, {"t": "人人自制,是以贪财诛利,不畏死亡。", "b": "《资治通鉴》"}, {"t": "诛求无时。", "b": "《左传·襄公三十一年》"}], "words": [{"w": "诛敛", "t": "搜刮财货,横征暴敛"}, {"w": "诛求无厌", "t": "勒索、榨取没有满足的时候"}, {"w": "诛攫", "t": "需索攫取。"}]}, {"meaning": "讨伐。", "cites": [{"t": "诛暴秦。", "b": "《史记·陈涉世家》"}, {"t": "下无倍畔之心,下无诛伐之志。", "b": "汉·贾谊《治安策》"}], "words": [{"w": "诛暴讨逆", "t": "讨伐凶恶叛逆的人"}, {"w": "诛国", "t": "被讨伐的国家"}, {"w": "诛讨", "t": "讨伐"}, {"w": "诛叛", "t": "讨伐叛逆。"}]}, {"meaning": "铲除。", "cites": [{"t": "宁诛锄草茅以力耕乎?", "b": "屈原《卜居》"}], "words": [{"w": "诛茅", "t": "剪除茅草。"}]}, {"meaning": "记述。", "cites": [{"t": "吾以为古之善者则诛之,今之善者则作之,欲善之益多也。", "b": "《墨子》"}]}]}]','jingmo-wenyan');
