('4052wx','诜','1','shēn','讠','8','','[{"pinyin": "shēn", "defs": [{"meaning": "众多的样子。", "cites": [{"t": "甡甡其鹿。", "b": "《诗·大雅·桑柔》。段注:“其字或作诜诜,或作侁侁,或作駪駪,或作莘莘,皆假借也。”"}], "words": [{"w": "诜诜", "t": "众多的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4053wx','诟','1','gòu','讠','8','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从言,后声。本义:耻辱) 同本义。", "cites": [{"t": "詬,謑詬耻也。", "b": "《说文》"}, {"t": "常以儒相詬病。", "b": "《礼记·儒行》"}, {"t": "余不忍其詬。", "b": "《左传·昭公二十年》"}, {"t": "诟,耻辱也。", "b": "《玉篇》"}, {"t": "诟莫大于宫刑。", "b": "司马迁《报任安书》"}, {"t": "公以晋诟语之。", "b": "《左传》"}], "words": [{"w": "诟耻", "t": "耻辱"}, {"w": "诟丑", "t": "耻辱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4054wx','诠','1','quán','讠','8','','[{"pinyin": "quán", "defs": [{"meaning": "(形声。从言,全声。本义:详细解释,阐明事理)。"}, {"meaning": "同本义。", "cites": [{"t": "诠,具也。", "b": "《说文》"}, {"t": "释言曰诠。", "b": "《通俗文》"}, {"t": "就也。诠言者谓譬类人事相解喻也。", "b": "《淮南子·诠言》注"}], "words": [{"w": "诠言", "t": "阐明事物意义、诠释人世真理的言论"}, {"w": "诠证", "t": "依据事实加以解说"}, {"w": "诠疏", "t": "诠释疏解"}, {"w": "诠明", "t": "解释、说明"}, {"w": "诠旨", "t": "阐明要旨"}, {"w": "诠表", "t": "解释与表达"}, {"w": "诠发", "t": "解释发明。"}]}, {"meaning": "道理;事物的规律。", "cites": [{"t": "发必中诠,言必合数。", "b": "《淮南子》"}, {"t": "一品之中,略以世代为先后,不以优劣为诠次。", "b": "钟嵘《诗品》"}], "words": [{"w": "诠次", "t": "次第;层次。也指选择和编排"}, {"w": "诠序", "t": "有条理有次序"}, {"w": "诠补", "t": "编次和补齐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4055wx','诣','1','yì','讠','8','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从言,旨声。本义:前往,去到)。"}, {"meaning": "同本义。", "cites": [{"t": "诣,候至也。", "b": "《说文》"}, {"t": "诣,进也。", "b": "《小尔雅》"}, {"t": "未得诣前。", "b": "《汉书·杨王孙传》。注:至也。”"}, {"t": "诣,至也。", "b": "《苍颉篇》"}, {"t": "吏遂缚诣县。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "先主遂诣亮。", "b": "《三国志·诸葛亮传》"}, {"t": "及郡下,诣太守,说如此。", "b": "晋·陶渊明《桃花源记》"}, {"t": "元济诣京师。", "b": "《资治通鉴·唐纪》"}, {"t": "与鲁肃俱诣孙权。", "b": "《资治通鉴》"}], "words": [{"w": "诣阙", "t": "亲自到达宫廷"}, {"w": "诣门", "t": "上门,登门。"}]}, {"meaning": "晋谒;造访。古代到朝廷或上级、尊长处去之称。", "cites": [{"t": "及郡下,诣太守,说如此。", "b": "《桃花源记》"}, {"t": "后数岁,买臣随上计吏为卒,将重车至长安,诣阙上书,书久不报。", "b": "《汉书·朱买臣传》"}], "words": [{"w": "诣谒", "t": "前往谒见;造访"}, {"w": "诣阁", "t": "前往朝廷官署"}, {"w": "诣阙", "t": "赴朝堂"}, {"w": "诣见", "t": "前往诣见。"}]}, {"meaning": "符合。", "cites": [{"t": "若执事之言政,诣理切情。", "b": "唐·刘禹锡《答饶州元使君书》"}], "words": [{"w": "诣实", "t": "符合实际"}, {"w": "诣理", "t": "合理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4056wx','诤','1','zhēng zhèng','讠','8','','[{"pinyin": "zhēng", "defs": [{"meaning": "假借为“争”。争论;争讼。", "cites": [{"t": "王凤为平理诤讼。", "b": "《后汉书·刘玄传》"}, {"t": "诤,讼也。", "b": "《苍颉篇》"}, {"t": "彼诚以天下之必无仙,而我独以实有而与之诤,诤之弥久,而彼执之弥回。", "b": "晋·葛洪《抱朴子》"}], "words": [{"w": "诤讼", "t": "争论"}, {"w": "诤论", "t": "争论"}, {"w": "诤薮", "t": "争讼的渊薮"}, {"w": "诤辞", "t": "争讼之辞"}, {"w": "诤诉", "t": "诉讼。"}]}, {"meaning": "争奇;竞争。", "cites": [{"t": "虽时时与师友有诤有讲,然师友总不以我为嫌者,知我无诤心也,彼此各求以自得也。", "b": "明·李贽《与河南吴中丞书》"}], "words": [{"w": "诤治", "t": "竞相采取治国之道"}, {"w": "诤心", "t": "争高低之心"}, {"w": "诤竞", "t": "竞争。"}]}, {"meaning": "争夺。", "cites": [{"t": "有两虎诤人而斗者。", "b": "《战国策·秦策二》"}, {"t": "阘茸勇敢于饕诤。", "b": "《晋书·王沈传》"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "(形声。从言,争声。因与言论有关,故从言。“诤”字本作“争”,“诤”是后起字,意思是强谏。用则可生,不用则死,程度比“谏”重。本义:直言规劝) 同本义(尤指友谊诚挚的劝告)。", "cites": [{"t": "诤,谏也。", "b": "《广雅》"}, {"t": "士有诤友,则身不离于令名。", "b": "《孝经·谏诤》"}], "words": [{"w": "默诤", "t": "背地里直言劝告"}, {"w": "诤谏", "t": "以直言劝止他人的过失"}, {"w": "诤臣", "t": "能谏诤的臣子"}, {"w": "诤戒", "t": "告诫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4057wx','诧','1','chà','讠','8','','[{"pinyin": "chà", "defs": [{"meaning": "(形声。从言,宅声。本义:夸耀)。"}, {"meaning": "同本义。", "cites": [{"t": "狐貉安能诧緼袍。", "b": "陆游《纵笔》"}]}, {"meaning": "惊讶,觉着奇怪。", "cites": [{"t": "魏子详瞩既毕,诧曰:“嘻,技亦灵怪矣哉!”", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "诧为奇事", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4058wx','诨','1','hùn','讠','8','','[{"pinyin": "hùn", "defs": [{"meaning": "(形声。从言,军声。本义:开玩笑的话) 同本义", "words": [{"w": "诨话", "t": "开玩笑的话"}, {"w": "诨语", "t": "逗趣的话"}, {"w": "诨官", "t": "乐官"}, {"w": "诨耍", "t": "打诨耍笑"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4059wx','诩','1','xǔ','讠','8','','[{"pinyin": "xǔ", "defs": [{"meaning": "(形声。从言,羽声。本义:说大话,夸耀)。"}, {"meaning": "同本义。", "cites": [{"t": "诩,大言也。", "b": "《说文》"}, {"t": "合同主诩。", "b": "《礼记·少仪》"}, {"t": "尚泰奢,丽夸诩。", "b": "《汉书·扬雄传》"}, {"t": "儒行之对,多所诩张,非俭让之德也。", "b": "明·高拱《本语》"}, {"t": "墙头山自好,何必诩神仙。", "b": "清·黄遵宪《闭关》"}, {"t": "意气扬扬,若自矜诩。", "b": "方苞《狱中杂记》"}], "words": [{"w": "诩张", "t": "夸张。"}]}, {"meaning": "普及。", "cites": [{"t": "德发扬,诩万物。", "b": "《礼记·礼器》"}], "words": [{"w": "诩扬", "t": "发扬;张大。"}]}, {"meaning": "假借为“妩”。妩媚。", "cites": [{"t": "不闻犯齐牧,犹闻画眉诩。", "b": "《次韵寄晃以道》"}], "words": [{"w": "诩畜", "t": "媚好,妩媚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4060wx','戕','1','qiāng','戈','8','','[{"pinyin": "qiāng", "defs": [{"meaning": "(会意。从戈,从爿。戈,古代用以横击、钩杀的重要武器。爿(pán),劈开的竹木片。本义:残杀、杀害)。"}, {"meaning": "同本义。", "cites": [{"t": "戕汝家矣。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "自戕", "t": "自杀"}, {"w": "戕虐", "t": "残暴;残害"}, {"w": "戕杀", "t": "残杀,损伤。"}]}, {"meaning": "伤害。", "cites": [{"t": "戕身损寿。", "b": "《亢仓子·用道》"}], "words": [{"w": "戕扰", "t": "伤害骚扰"}, {"w": "戕生", "t": "伤害生命"}, {"w": "戕夷", "t": "伤害摧残"}, {"w": "戕伐", "t": "伤害;自残,指“纵欲”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4061wx','孢','1','bāo','子','8','','[{"pinyin": "bāo", "defs": [{"meaning": "某些植物和低等动物产生的有繁殖作用或休眠作用的细胞。离开母体后能形成新的个体。"}, {"meaning": "通过孢子繁殖的一类植物,含菌、藻、苔、藓、蕨类等。"}, {"meaning": "苔藓植物孢子体顶端产生孢子的膨大部分。成熟时开裂，散出孢子。"}, {"meaning": "植物产生孢子的细胞或器官。有些植物有大、小孢子囊之分。大孢子囊产生个体较大而数量很少的大孢子，由它们发育成雌配子体；小孢子囊产生小而多的小孢子，由它们发育成雄配子体。"}, {"meaning": "无性生殖的一种方式。母体产生孢子，孢子不经结合，直接形成新个体。如孢子植物和原生动物门孢子虫的生殖方式。"}, {"meaning": "指植物世代交替中，产生孢子的植物体。孢子体一般具有二倍数的染色体。"}, {"meaning": "植物生活史中具有二倍数染色体的植物体时期。如蕨类植物从合子形成到孢子母细胞的产生为孢子体世代。又称无性世代。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4062wx','亟','1','jí qì','二','8','','[{"pinyin": "jí", "defs": [{"meaning": "(会意。甲骨文字形,是“亟”(古極字)字的初文。中间是一个站着的人,上面一横表示“极于顶”,下面一横表示“极于踵。”金文繁化字形,与小篆的写法相似。本义:极点,尽头) 快速;迅速(含有急迫之意)。", "cites": [{"t": "亟,急也。", "b": "《广雅》"}, {"t": "亟其乘屋。", "b": "《诗·豳风·七月》"}, {"t": "小饭而亟之。", "b": "《礼记·少仪》"}, {"t": "欲霸之亟成。", "b": "《战国策·宋策》"}, {"t": "亟言之。", "b": "《左传·昭公二十一年》"}, {"t": "君亟定变法之虑。", "b": "《商君书·更法》"}, {"t": "经始勿亟,庶民子来。", "b": "《孟子·梁惠王上》"}, {"t": "趣赵兵亟入关。", "b": "《史记·陈涉世家》"}, {"t": "亟请广州府余暨南、番二县代求解免。", "b": "《广东军务记》"}], "words": [{"w": "亟欲;亟盼;亟肄", "t": "加紧训练"}, {"w": "亟务", "t": "紧要之事。"}]}]}, {"pinyin": "qì", "defs": [{"meaning": "", "words": [{"w": "亟叹", "t": "屡次感叹"}, {"w": "亟请", "t": "多次请求。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4063wx','陔','1','gāi','阝','8','','[{"pinyin": "gāi", "defs": [{"meaning": "(形声。从阜,亥声。从“阜”,表示与地形、地势的高低上下有关。本义:台阶的层次) 同本义。", "cites": [{"t": "陔,阶次也。", "b": "《说文》"}, {"t": "泰一坛三陔。", "b": "《汉书·郊祀志》。注:“重也。”"}]}, {"meaning": "又如三陔坛(三重坛)。"}, {"meaning": "田埂。", "cites": [{"t": "循彼南陔,言采其兰。", "b": "晋·束皙《补亡诗·南陔》"}], "words": [{"w": "南陔", "t": "南边的田埂。"}]}, {"meaning": "古乐章《陔夏》的省称。", "cites": [{"t": "宾出,奏《陔》。", "b": "《仪礼·乡饮酒礼》"}], "words": [{"w": "陔鼓", "t": "奏《陔夏》时伴奏之鼓。"}]}, {"meaning": ""}, {"meaning": "八极,极远的地方。", "cites": [{"t": "灵凤所以晨起丹穴,夕萃轩丘,日未移晷,周 章九陔。", "b": "《抱朴子·广譬》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4064wx','妲','1','dá','女','8','','[{"pinyin": "dá", "defs": [{"meaning": "女子人名用字", "words": [{"w": "妲己", "t": "商纣的宠妃。有苏氏女。周武王灭商时被杀。"}]}]}]','jingmo-wenyan');
