INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4066wx','姗','1','shān','女','8','','[{"pinyin": "shān", "defs": [{"meaning": "讥讽,诽谤。此义通“讪”。", "cites": [{"t": "姗,诽也。从女,删省声。与讪略同。", "b": "《说文》"}, {"t": "自任私智,姗笑之代。", "b": "《汉书·异姓诸侯王表奏》"}, {"t": "显恐 天下学士姗己。", "b": "《汉书·石显传》"}], "words": [{"w": "姗谤", "t": "讥笑诽谤"}, {"w": "姗议", "t": "诽议"}, {"w": "姗诮", "t": "讥刺"}, {"w": "姗笑", "t": "讥笑,嘲笑"}, {"w": "姗侮", "t": "讪笑侮辱,讥笑轻慢。"}]}, {"meaning": "缓步的样子。", "cites": [{"t": "偏何姗姗其来迟!", "b": "《汉书·孝武李夫人传》"}, {"t": "便姗嬖屑。", "b": "司马相如《子虚赋》。注:“衣曳地貌。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4067wx','帑','1','tǎng','巾','8','','[{"pinyin": "tǎng", "defs": [{"meaning": "古时收藏钱财的府库。", "cites": [{"t": "帑,金币所藏也。从巾,奴声。", "b": "《说文》"}, {"t": "库藏曰帑。", "b": "《通俗文》"}, {"t": "人食不足,而帑藏殷积。", "b": "《后汉书》"}], "words": [{"w": "帑实", "t": "府库中的财物"}, {"w": "帑廪", "t": "国库与粮仓"}, {"w": "帑廥", "t": "国家储藏金币和粮食的府库"}, {"w": "帑藏", "t": "国库"}, {"w": "帑储", "t": "府库储积"}, {"w": "帑簿", "t": "国库登记财物的帐簿"}, {"w": "帑银", "t": "国库中的银子。"}]}, {"meaning": "指国家库藏的金帛。", "cites": [{"t": "虚费府帑。", "b": "《汉书·匈奴传》"}], "words": [{"w": "国帑", "t": "国家的公款"}, {"w": "帑金", "t": "钱币。多指国库所藏。"}]}, {"meaning": "裹金帛的囊。", "cites": [{"t": "行帑无寸金,卫兵不宿饱。", "b": "《旧唐书》"}]}, {"meaning": "藏匿。", "cites": [{"t": "帑金帛舍。", "b": "《晋书音义》"}], "words": [{"w": "帑屋", "t": "帑舍。贮藏金银的库房"}, {"w": "帑帛", "t": "库藏的丝织品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4068wx','弩','1','nǔ','弓','8','','[{"pinyin": "nǔ", "defs": [{"meaning": "(形声。从弓,奴声。本义:用械发箭的弓)。"}, {"meaning": "同本义。", "cites": [{"t": "弩,弓有臂者。", "b": "《说文》"}, {"t": "夫弩弱而矢高者,激于风也。", "b": "《韩非子·难势》"}, {"t": "魏氏之武卒…操十二石之弩。", "b": "《荀子·议兵》"}, {"t": "强弩之末。", "b": "《资治通鉴》"}, {"t": "伏弩射杀。", "b": "《汉书·李广苏建传》"}, {"t": "良将劲弩。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "连弩", "t": "数矢并发的弓"}, {"w": "弩门", "t": "蒙语称弓"}, {"w": "万弩齐发;弩力", "t": "弩弓的射力"}, {"w": "弩子", "t": "弩弓"}, {"w": "弩牙", "t": "弩机钩弦的部件"}, {"w": "弩末", "t": "强紧之末"}, {"w": "弩栝", "t": "弩弓用以发射弓箭的机栝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4069wx','孥','1','nú','子','8','','[{"pinyin": "nú", "defs": [{"meaning": "(形声。从子,奴声。本义:儿子)。"}, {"meaning": "同本义。", "cites": [{"t": "独携三尺琴,笑别妻与孥。", "b": "宋·秦观《赠张潜道》"}]}, {"meaning": "妻子与儿女的统称。", "cites": [{"t": "泽梁无禁,罪人不孥。", "b": "《孟子·梁惠王》"}]}, {"meaning": "以为奴婢。", "cites": [{"t": "予则孥戮汝。", "b": "《书·甘誓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4070wx','驽','1','nú','马','8','','[{"pinyin": "nú", "defs": [{"meaning": "(形声。从马,奴声。本义:劣马)。"}, {"meaning": "同本义。", "cites": [{"t": "驽骏杂而不兮兮。", "b": "东方朔《七谏·哀命》"}], "words": [{"w": "驽猥", "t": "劣马"}, {"w": "驽蹇", "t": "劣马"}, {"w": "驽驾", "t": "驽乘。劣马所驾之车"}, {"w": "驽薾", "t": "瘦弱之马"}, {"w": "驽良", "t": "驽马和良马。"}]}, {"meaning": "才能低劣。", "cites": [{"t": "相如虽驽,独畏廉将军哉?", "b": "《史记·廉颇蔺相如列传》"}], "words": [{"w": "驽将", "t": "才能低劣的将领"}, {"w": "驽钝", "t": "平庸低下"}, {"w": "驽禍", "t": "低下无能之才"}, {"w": "驽下", "t": "资质迟钝,才能低下"}, {"w": "驽庸", "t": "才智低下"}, {"w": "驽懦", "t": "驽钝懦弱。"}]}, {"meaning": "跑不快;劣。", "cites": [{"t": "驽马十驾,功在不舍。", "b": "《荀子》"}]}]}]','jingmo-wenyan');
