('4072wx','迦','1','jiā','辶','8','','[{"pinyin": "jiā", "defs": [{"meaning": "译音字", "words": [{"w": "迦罗沙曳", "t": "袈裟"}, {"w": "迦罗", "t": "佛祖诞生地“迦维罗卫”的省称"}, {"w": "迦蓝", "t": ""}, {"w": "迦箅香", "t": "藿香"}, {"w": "迦南", "t": "伽南香。沉香的别名"}, {"w": "迦持", "t": "佛教戒律"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4073wx','迨','1','dài','辶','8','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从辵(chuò),台声。本义:及,到)。"}, {"meaning": "同本义。", "cites": [{"t": "迨至菡萏成花。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "迨及", "t": "达到。"}]}, {"meaning": "等到。", "cites": [{"t": "迨诸父异爨。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "迨至", "t": "及至,等到"}, {"w": "迨闻", "t": "等到听说"}, {"w": "迨后", "t": "等到。"}]}, {"meaning": "趁;乘。", "cites": [{"t": "请迨其未毕隐(阵)而击之。", "b": "《公羊传·僖公二十二年》"}], "words": [{"w": "迨吉", "t": "男婚女嫁皆合时宜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4074wx','绀','1','gàn','纟','8','','[{"pinyin": "gàn", "defs": [{"meaning": "红青,微带红的黑色。", "cites": [{"t": "绀,帛深青扬赤色。", "b": "《说文》"}, {"t": "绀,青色。", "b": "《广雅》"}, {"t": "君子不以绀緅饰。", "b": "《论语》。集解:“绀緅紫玄之类。”"}], "words": [{"w": "绀发", "t": "深青透红的头发。相传如来的头发为绀琉璃色"}, {"w": "绀珠", "t": "绀色的珠。相传唐朝宰相张说有绀珠一颗,持观后能记事不忘,因名记事珠。后以喻博记"}, {"w": "绀碧", "t": "天青色;深青透红色"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4075wx','绁','1','xiè','纟','8','','[{"pinyin": "xiè", "defs": [{"meaning": "绳索。", "cites": [{"t": "绁,系也。从系,世声。字亦作絏。", "b": "《说文》"}, {"t": "绁,索也。", "b": "《广雅》"}, {"t": "虽在缧绁之中。", "b": "《论语》"}, {"t": "以桳榈大绁系石以为矴(碇)。", "b": "陈寿《三国志》"}]}, {"meaning": "牵引牲畜的绳索。", "cites": [{"t": "臣负羁绁,从君巡于天下。(羁:马笼头)", "b": "《左传·僖公二十四年》"}]}, {"meaning": "系、拴或捆绑。", "cites": [{"t": "绁子婴于轵(zhǐ)涂(途)。", "b": "张衡《东京赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4076wx','绂','1','fú','纟','8','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关。本义:系印章或佩玉用的丝带。绂的颜色依官位品级而不同)。"}, {"meaning": "同本义。", "cites": [{"t": "降尊就卑,怀玺藏绂。", "b": "《文选·张衡·西京赋》"}, {"t": "授单于印绂。", "b": "《汉书·匈奴传下》"}]}, {"meaning": "古代作祭服的蔽膝 。缝于长衣之前。为祭服的服饰。周制帝王、诸侯及诸国的上卿皆着朱绂。", "cites": [{"t": "朱绂方来。", "b": "《易·困卦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4077wx','驷','1','sì','马','8','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从马,四声。本义:同驾一辆车的四匹马。或驾四马之车)。"}, {"meaning": "同本义。", "cites": [{"t": "驷,马一乘也。", "b": "《说文》。徐锴曰:“四马也。”"}, {"t": "驷,四马一乘也。", "b": "《玉篇》"}, {"t": "驷介旁旁。", "b": "《诗·郑风·清人》"}, {"t": "结驷千乘。", "b": "《庄子·人间世》"}, {"t": "齐景公有马千驷。", "b": "《论语·季氏》"}, {"t": "齐王闻之,君臣恐惧遣太傅赍黄金千斤,文东二驷,服剑一封书谢孟尝君。", "b": "《战国策·齐策》"}], "words": [{"w": "上驷", "t": "最好的驾四马之车"}, {"w": "驷牡", "t": "同驾一车的四匹公马"}, {"w": "驷马之门", "t": "能容驷马高车通过的大门。借指显贵"}, {"w": "驷介", "t": "由四匹披甲战马拉的车"}, {"w": "驷铁", "t": "驾一车的四匹赤黑马"}, {"w": "驷骊", "t": "驾一车的四匹深黑色马"}, {"w": "驷骐", "t": "架一车的四匹骐马"}, {"w": "驷车", "t": "驷马所拉之车"}, {"w": "驷盖", "t": "驷车"}, {"w": "驷黄", "t": "驾一车的四匹黄骍马。"}]}, {"meaning": "马。", "cites": [{"t": "三年之丧,二十五月而毕。若驷之过隙,然而遂之,则是无穷也。", "b": "《荀子·礼论》"}]}, {"meaning": "古星名 。亦作“天驷”、“天龙”。", "cites": [{"t": "月在天驷。", "b": "《国语·周语下》"}], "words": [{"w": "驷房", "t": "房星。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4078wx','驸','1','fù','马','8','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从马,付声。副马。本义:驾副车或备用的马)。"}, {"meaning": "同本义。", "cites": [{"t": "驸,副马也。", "b": "《说文》。桂馥注:“副马也者,《后汉书·鲁恭传》:‘赐驸马从驾’。注云:‘驸,副也,非正所乘,皆为副。’"}, {"t": "驸马都尉。", "b": "《汉书·百官公卿表上》"}]}, {"meaning": "又指驾副车的马。"}, {"meaning": "车厢外的立木。引申为辅助。", "cites": [{"t": "乃斩其仆,车之左驸,马之左骖,以徇三军。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4079wx','绉','1','zhòu','纟','8','','[{"pinyin": "zhòu", "defs": [{"meaning": "细葛布。", "cites": [{"t": "绉,絺之细也。从糸,刍声。", "b": "《说文》"}, {"t": "蒙彼绉絺。", "b": "《诗·鄘风·君子偕老》。传:“霑之靡者为绉。”"}], "words": [{"w": "绉絺", "t": "精细的葛布。"}]}, {"meaning": "绉缩,使起折痕。", "cites": [{"t": "风乍起,吹绉一池春水。", "b": "五代·冯延己《谒金门》"}], "words": [{"w": "绉纹", "t": "蹙皱的细纹"}, {"w": "绉巴巴", "t": "形容衣服、纸张、皮肤等发皱"}, {"w": "绉漫漫", "t": "形容布满皱纹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4080wx','绌','1','chù','纟','8','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从糸(mì),出声。本义:深红色)。"}, {"meaning": "同本义。", "cites": [{"t": "绌,绛也。", "b": "《说文》"}, {"t": "却冠林绌。", "b": "《史记·赵世家》"}]}, {"meaning": "不足。", "cites": [{"t": "然,其短长优绌,不尽出于一轨。", "b": "清·冯俊《谋臣论》"}, {"t": "我们山西没有外销的款子,所以有些事情绌于经费,都不能办。", "b": "《官场现形记》"}], "words": [{"w": "相形见绌", "t": ""}]}, {"meaning": "屈服;制服。", "cites": [{"t": "范雎绌白起,公孙弘抑董仲舒,此同朝共君宠禄争故耶?", "b": "《潜夫论·贤难》"}]}, {"meaning": "废除;贬退。", "cites": [{"t": "不孝者,君绌以爵。", "b": "《礼记·王制》"}, {"t": "世子学老子者则绌儒学,儒学亦绌老子。", "b": "《史记·老子列传》"}, {"t": "屈平既绌,其后秦欲伐齐,齐与楚从亲。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "绌臣", "t": "被放逐的臣子"}, {"w": "绌约", "t": "黜退而穷困"}, {"w": "绌陟", "t": "升降,同黜陟。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4081wx','驿','1','yì','马','8','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从马,睪(yì)声。本义:古代供传递公文或传送消息用的马)。"}, {"meaning": "同本义。", "cites": [{"t": "驿,置骑也。", "b": "《说文》"}, {"t": "即孟子置郵,所谓遽也。", "b": ""}, {"t": "馹为传车,驿为马骑。", "b": ""}, {"t": "楚子乘驿。", "b": "《左传·文公十六年》"}, {"t": "使驿谒诸王。", "b": "《左传·襄公二十七年》"}, {"t": "后数日驿至。", "b": "《后汉书·张衡传》"}]}, {"meaning": "驿站。", "cites": [{"t": "驿外断桥边,寂寞开无主。", "b": "陆游《卜算子·咏梅》"}], "words": [{"w": "驿递夫马", "t": "驿马"}, {"w": "驿马星", "t": "星相家的迷信说法,若占卜得驿马星,表示将远行、赴任、移居"}, {"w": "驿吏", "t": "管理驿站的官吏"}, {"w": "驿亭", "t": "古代作为行旅中途休息住宿的处所"}, {"w": "驿书", "t": "以驿马传送的文书"}, {"w": "驿馆", "t": "旅馆,驿舍"}, {"w": "驿骑", "t": "乘驿马传递文书的使者。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4082wx','骀','1','dài tái','马','8','','[{"pinyin": "dài", "defs": [{"meaning": "舒缓放荡。常作“骀荡”。", "cites": [{"t": "舞丝千丈飏晴光,骀青春无际。", "b": "宋·赵善扛《烛影摇红》"}]}]}, {"pinyin": "tái", "defs": [{"meaning": "(形声。从马,台声。本义:劣马)。"}, {"meaning": "同本义。", "cites": [{"t": "骀,驽马。", "b": "《广韵》"}], "words": [{"w": "驽骀", "t": "劣马。比喻低下的庸才。"}]}, {"meaning": "比喻庸才。", "cites": [{"t": "驱奔效驾,先辍于羸骀。", "b": "庾信《代人乞致仕表》"}]}, {"meaning": "马嚼子脱落。", "cites": [{"t": "骀,马衔脱也。", "b": "《说文》"}]}, {"meaning": "践踏。", "cites": [{"t": "兵相骀藉。", "b": "《史记·天官书》"}, {"t": "更相骀藉。", "b": "《后汉书·冯衍传》"}], "words": [{"w": "骀藉", "t": "践踏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4083wx','甾','1','zāi zī','田','8','','[{"pinyin": "zāi", "defs": [{"meaning": "有机化合物的一类 ,广泛存在于动植物体内。胆固醇和很多种激素(如性激素),都属于甾类化合物。"}]}, {"pinyin": "zī", "defs": [{"meaning": "古代一种盛酒浆的陶器。", "cites": [{"t": "甾,东楚名缶曰甾。", "b": "《说文》"}]}, {"meaning": "水名", "cites": [{"t": "嵎夷既略,淮、甾其道。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
