('4084wx','珏','1','jué','王','9','','[{"pinyin": "jué", "defs": [{"meaning": "双玉,二玉相合为一珏。", "cites": [{"t": "珏,二玉相合为一珏。", "b": "《说文》"}, {"t": "翁伯以礼玉十珏以授仙童。", "b": "《太平广记》引《仙传拾遗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4085wx','珐','1','fà','王','9','','[{"pinyin": "fà", "defs": [{"meaning": "一种涂料，涂在金属制品的表面作为装饰，又可防锈。用石英、硼砂、玻璃粉等加入溶剂、乳浊剂和着色剂等制成。常用于制证章、奖章等。砝琅制品\\"景泰蓝\\"是我国特有的工艺产品之一。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4086wx','珂','1','kē','王','9','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从玉,可声。本义:似玉的美石。白玛瑙)。"}, {"meaning": "同本义 。珂珮(朝官衣服上的玉带);珂雪(形容如白玉般洁白);珂声(马勒上珂饰的声响)。"}, {"meaning": "马笼头上的装饰。", "cites": [{"t": "文轩树羽盖,乘马鸣玉珂。", "b": "张华《轻薄编》"}], "words": [{"w": "珂月", "t": "嵌在马头笼辔上的月形饰物"}, {"w": "珂马", "t": "珂即马笼头上的玉饰,因称人所乘之马为珂马。"}]}]}]','jingmo-wenyan');
