INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4095wx','挝','1','wō zhuā','扌','9','','[{"pinyin": "wō", "defs": [{"meaning": "——“老挝”（Lǎowō）:亚洲一国名。"}]}, {"pinyin": "zhuā", "defs": [{"meaning": "敲打,击。", "cites": [{"t": "令鼓吏挝鼓。", "b": "《三国演义》"}], "words": [{"w": "挝打", "t": "殴打"}, {"w": "挝捶", "t": "鞭打"}, {"w": "挝挞", "t": "鞭挞"}, {"w": "挝筑", "t": "鞭打"}, {"w": "挝鼓", "t": "击鼓"}, {"w": "挝阖", "t": "敲门。"}]}, {"meaning": "贴;靠。", "cites": [{"t": "一个死人身上,也没个忌讳,就脸挝着脸儿哭,倘或口里恶气扑着你怎的!", "b": "《金瓶梅词话》"}]}, {"meaning": "摘。", "cites": [{"t": "那分府看见他戴了方巾,说道:“衙门寻商,从来没有生监充当的,你怎么戴这个帽子!左右的!挝去了!一条链子锁起来!", "b": "《儒林外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4096wx','垣','1','yuán','土','9','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从土,亘(xuān)声。本义:矮墙,也泛指墙)。"}, {"meaning": "同本义。", "cites": [{"t": "垣,墙也。", "b": "《说文》"}, {"t": "既勤垣墉。", "b": "《书·梓材》。马注:“卑曰垣,高曰墉。”"}, {"t": "周垣之高八尺。", "b": "《墨子·备城门》"}, {"t": "尽毁其馆之垣。", "b": "《左传·襄公三十一年》"}, {"t": "为家不治垣产。", "b": "《汉书·萧何传》"}], "words": [{"w": "垣衣", "t": "生在墙垣上的苔"}, {"w": "垣堵", "t": "墙"}, {"w": "垣屋", "t": "有围墙的房室;围墙和房屋。"}]}, {"meaning": "城墉 。后叫省城为省垣。"}, {"meaning": "官署的代称。", "cites": [{"t": "花隐掖垣暮,啾啾栖鸟过。", "b": "杜甫《春宿左省诗》"}]}, {"meaning": "筑墙围绕。", "cites": [{"t": "天云垣其既立兮,家愿得乎双逞。", "b": "《三国演义》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4097wx','挞','1','tà','扌','9','','[{"pinyin": "tà", "defs": [{"meaning": "(形声。从手,达声。本义:用鞭子或棍子打)。"}, {"meaning": "同本义。", "cites": [{"t": "挞,乡饮酒,罚不敬,挞其背也。", "b": "《说文》"}, {"t": "掌其比觵挞罚之事。", "b": "《周礼·闾胥》。注:“扑也。”"}, {"t": "而挞其怠慢者。", "b": "《周礼·小胥》"}, {"t": "而挞之流血。", "b": "《礼记·内则》"}, {"t": "斫挞无伤痛。", "b": "《列子·黄帝》"}, {"t": "鞭挞黎庶令人悲。", "b": "唐·高适《封丘作》"}], "words": [{"w": "鞭挞", "t": "鞭打"}, {"w": "挞市", "t": "在市朝上受到鞭打的刑罚"}, {"w": "挞辱", "t": "鞭打侮辱"}, {"w": "挞笞", "t": "用鞭和竹板子打"}, {"w": "挞讯", "t": "拷问"}, {"w": "挞通", "t": "打通"}, {"w": "挞架", "t": "打架。"}]}, {"meaning": "拍打。", "cites": [{"t": "便脱下鞋底,将字迹挞没了。", "b": "《古今小说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4098wx','垤','1','dié','土','9','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从土,至声。本义:蚂蚁做窝时堆在穴口的小土堆;小土堆)同本义。", "cites": [{"t": "蚍蜉其场谓之坻,或谓之垤。", "b": "《方言》十一"}, {"t": "鹳鸣于垤。", "b": "《诗·豳风·东山》"}, {"t": "百年炊未熟,一垤蚁追奔。", "b": "宋·黄庭坚《次韵子瞻赠王定国》"}], "words": [{"w": "垤堄", "t": "积土成堆"}, {"w": "丘垤", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4099wx','赳','1','jiū','走','9','','[{"pinyin": "jiū", "defs": [{"meaning": "(形声。从走,丩(jiū)声。本义:威武雄壮的样子) 同本义。", "cites": [{"t": "赳,轻劲有才力也。", "b": "《说文》"}, {"t": "赳,材也。", "b": "《广雅》"}, {"t": "赳赳武夫。", "b": "《诗·召南·兔罝》。传:“武貌。”"}, {"t": "赳赳,武也。", "b": "《尔雅》"}, {"t": "沛艾赳嗅。", "b": "《史记·司马相如传》。集解:“申颈低卬也。”"}, {"t": "又一日赳然有阵大风,从东南来,刮得山谷震动。", "b": "《女仙外史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4100wx','贲','1','bēn bì','贝','9','','[{"pinyin": "bēn", "defs": [{"meaning": "急走;逃亡。", "cites": [{"t": "虎贲三千人。", "b": "《孟子·尽心下》"}, {"t": "卫士旅贲。", "b": "《汉书·百官公卿表》"}, {"t": "下比周贲溃以离上矣。(比周:勾结)", "b": "《荀子·强国》"}], "words": [{"w": "贲溃", "t": "奔走溃散。"}]}, {"meaning": "奔流。", "cites": [{"t": "蚕珥丝而商絃绝,贲星坠而渤海决。", "b": "《淮南子·天文》"}], "words": [{"w": "贲星", "t": "流星。"}]}, {"meaning": "虎贲:勇士。", "cites": [{"t": "令贲士主将皆听城鼓之音而出。", "b": "《墨子·备梯》"}], "words": [{"w": "贲士", "t": "敏捷善战的勇士"}, {"w": "贲石", "t": "指古代勇士孟贲和石蕃"}, {"w": "贲育", "t": "指古代勇士孟贲和夏育。"}]}]}, {"pinyin": "bì", "defs": [{"meaning": "(形声。从贝,卉声。本义:装饰,打扮) 装饰,修饰。", "cites": [{"t": "贲,饰也。", "b": "《说文》"}, {"t": "贲者,饰也。", "b": "《易·序卦》传"}, {"t": "皎皎白驹,贲然来思。", "b": "《诗·小雅·白驹》"}], "words": [{"w": "贲饰", "t": "装饰;文饰"}, {"w": "贲如", "t": "装饰华美的样子。"}]}, {"meaning": "颜色斑杂不纯。", "cites": [{"t": "贲如濡如。", "b": "《易·贲卦》。傅氏云:“贲,古斑字,文章貌。”"}], "words": [{"w": "贲华", "t": "开出多彩的花。"}]}, {"meaning": "华美;光彩貌。", "cites": [{"t": "贲,美也。", "b": "《广雅》"}, {"t": "用宏兹贲。", "b": "《书·盘庚》"}], "words": [{"w": "贲赍", "t": "盛美的赏赐"}, {"w": "贲然", "t": "光彩的样子。"}]}]}]','jingmo-wenyan');
