('4103wx','郝','1','hǎo','阝','9','','[{"pinyin": "hǎo", "defs": [{"meaning": "古乡名。", "cites": [{"t": "郝,右扶风鄠乡盩室县。从邑,赤声。", "b": "《说文》。朱曰:“在今陕西西安府。”"}]}, {"meaning": "在今陕西省周至县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4104wx','垧','1','shǎng','土','9','','[{"pinyin": "shǎng", "defs": [{"meaning": ",各地不同。在东北合1公顷,等于1万平方米,或15亩;西北地区约合3亩或5亩。", "cites": [{"t": "若不把南篱下的三垧地赎出来呀,明年连种的地也还没有了呢!", "b": "《一层楼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4105wx','垓','1','gāi','土','9','','[{"pinyin": "gāi", "defs": [{"meaning": "(形声。从土,亥声。本义:八极之内的广大土地)。"}, {"meaning": "同本义。", "cites": [{"t": "垓,兼该八极地也。", "b": "《说文》。字亦作畡。"}, {"t": "天子居九垓之田。", "b": "《国语·周语》"}, {"t": "设于无垓坫之宇。", "b": "《淮南子·俶真》。注:“垓坫,垠堮也。”"}, {"t": "上畅九垓,下埏八埏(yán八方极远之地)。", "b": "《史记·司马相如列传》"}, {"t": "道出一原,通九门,散六衢,设于无垓坫之宇", "b": "《淮南子·俶真》"}], "words": [{"w": "垓埏", "t": "天地的边际"}, {"w": "垓坫", "t": "边际"}, {"w": "垓极", "t": "荒远之处。"}]}, {"meaning": "域;界限。", "cites": [{"t": "重垠累垓。", "b": "扬雄《卫尉箴》"}]}, {"meaning": "数词。古代数目名,108。", "cites": [{"t": "京垓年岁之中,每每员舆(指地球)正不知几移几换而成此最后之奇。", "b": "[英]赫胥黎著,严复译《天演论》"}], "words": [{"w": "京垓", "t": "旧说十亿为兆,十兆为京,十京为垓。指亿万年悠长岁月"}, {"w": "垓垓", "t": "形容杂草丛生的样子"}, {"w": "垓垓攘攘", "t": "极多而纷乱。"}]}, {"meaning": "战地,阵地。", "cites": [{"t": "天罗地网漫山布,齐举刀兵大会垓。", "b": "《西游记》"}]}, {"meaning": "台阶,级层。", "cites": [{"t": "三垓上列,四陛旁升。", "b": "《北齐书·祭祀志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4106wx','挦','1','xián','扌','9','','[{"pinyin": "xián", "defs": [{"meaning": "拔;扯。", "cites": [{"t": "再多说,我把你这胡子还挦了呢!", "b": "《红楼梦》"}, {"t": "果然自己一把一把将那头发大绺挦将下来。", "b": "《醒世姻缘传》"}], "words": [{"w": "挦剥", "t": "拔毛剥皮"}, {"w": "挦毛;挦扯;挦鸡毛", "t": ""}]}, {"meaning": "引用、摘录或抄录(某人的文章或诗名)。", "cites": [{"t": "古书东移西掇,挦补成章。", "b": "《辍耕录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4107wx','垠','1','yín','土','9','','[{"pinyin": "yín", "defs": [{"meaning": "(形声。从土,艮(gèn)声。本义:边际,尽头)。"}, {"meaning": "同本义。", "cites": [{"t": "纷其无垠。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "一望无垠;垠崖", "t": "悬崖;边际。"}]}, {"meaning": "岸,水边的陆地。", "cites": [{"t": "其垠则有天琛水怪,鲛人之室。", "b": "木华《海赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4108wx','茜','1','qiàn xī','艹','9','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从艸,西声。本义:草名) 即“茜草”(Rubia cordifolia)。", "cites": [{"t": "茜,茅蒐也。字亦作蒨。", "b": "《说文》"}, {"t": "若千亩巵茜。", "b": "《史记·货殖列传》。徐广曰:“一名红蓝其花,染缯亦黄也。”"}]}, {"meaning": "按,一种茜草属多年生草本,茎方形,有逆刺,叶4枚轮生,长卵形或长心脏形,有叶柄,花小,淡黄白色,果实球形,熟果黑色,可食,根可制染料和入药。"}, {"meaning": "大红色。", "cites": [{"t": "茜袖捧琼姿,皎日丹霞起。", "b": "唐·李商隐《和郑愚赠汝阳王孙家筝妓》"}], "words": [{"w": "茜纱", "t": "红纱"}, {"w": "茜衫", "t": "红色的衣衫"}, {"w": "茜红", "t": "绛红色"}, {"w": "茜罗", "t": "绛红色的薄丝织品"}, {"w": "茜裙", "t": "红色的裙子"}, {"w": "茜绶", "t": "红色的印绶。譬喻官爵尊贵。"}]}, {"meaning": "染红。", "cites": [{"t": "谁家茜草茜的,也会落色来。", "b": "《醒世姻缘传》"}]}]}, {"pinyin": "xī", "defs": [{"meaning": "用于外国妇女名字的译音用字。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4109wx','荚','1','jiá','艹','9','','[{"pinyin": "jiá", "defs": [{"meaning": "(形声。从艸,夹声。本义:“荚果”的简称)。"}, {"meaning": "同本义。豆科植物的长角果或蓇葖,为单片或有两个以上果片(如蒴果)。", "cites": [{"t": "荚,草实也。", "b": "《说文》"}, {"t": "豆角谓之荚。", "b": "《广雅》"}, {"t": "得时之菽,其荚二七,以为族。", "b": "《吕氏春秋·审时》"}, {"t": "其植物宜荚物。", "b": "《周礼·大司徒》。注:“荠荚王棘之属。”"}], "words": [{"w": "豆荚;皂荚;结荚;荚物", "t": "植物果实的一种名称。凡草木结实时,有狭长的果皮包裹着,至成熟时,皮自破裂而籽出者,统称荚物"}, {"w": "荚钱", "t": "榆荚钱的简称,又名五分钱。"}]}, {"meaning": "某些树木的翅果。", "cites": [{"t": "榆荚还飞买笑钱。", "b": "李商隐《和人题真娘墓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4110wx','荑','1','tí yí','艹','9','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从艸,夷声。本义:茅草的嫩芽)。"}, {"meaning": "同本义,引申之为草木嫩芽。", "cites": [{"t": "荑,荑草也。", "b": "《说文》。按,茅之初生也。"}, {"t": "自牧归荑。", "b": "《诗·邶风·静女》"}, {"t": "手如柔荑,肤如凝脂。", "b": "《诗·卫风·硕人》"}, {"t": "五谷者,种之美者也;苟为不熟,不如荑稗。", "b": "《孟子·告子上》"}, {"t": "荑者,茅始熟中穰也,既白且滑。", "b": "《风俗通》"}], "words": [{"w": "荑英", "t": "新生的草"}, {"w": "荑杨", "t": "新生的杨树。"}]}, {"meaning": "草名。一种像稗子的草。", "cites": [{"t": "炳复次禁枯树,树即生荑。", "b": "《后汉书·方术传》"}, {"t": "生繁华于枯荑。", "b": "《晋书·元帝纪》"}], "words": [{"w": "荑枯", "t": "即“枯杨生稊”之意。喻绝处逢生;起死回生"}, {"w": "荑稗", "t": "荑、稗为二草名,似禾,实比谷小,亦可食。"}]}, {"meaning": "发芽。", "cites": [{"t": "草陆生曰荑。", "b": "《通俗文》"}, {"t": "陵罔掇丹荑。", "b": "郭璞《游仙诗》"}, {"t": "原隰荑绿柳,墟囿散红桃。", "b": "《文选·谢灵运·从游京口北固应诏一首》"}]}]}, {"pinyin": "yí", "defs": [{"meaning": "割去田地里的野草。", "cites": [{"t": "凡稼泽,夏以殄草而芟荑之。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4111wx','贳','1','shì','贝','9','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从贝,世声。本义:借,借贷)。"}, {"meaning": "同本义。", "cites": [{"t": "贳,贷也。", "b": "《说文》。受者曰赊,予者曰贳。"}, {"t": "则赊贳而予之。", "b": "《周礼·司市》"}, {"t": "民无贷(钱),则赊贳而予之。", "b": "《周礼·司市》郑注"}], "words": [{"w": "贳代", "t": "借贷"}, {"w": "贳贷", "t": "借贷;赊欠。"}]}, {"meaning": "赊欠。", "cites": [{"t": "县官无钱,从民贳马。", "b": "《史记·汲郑列传》"}, {"t": "常从王媪、武负贳酒。", "b": "《史记·高祖本纪》"}], "words": [{"w": "贳酒", "t": "赊酒"}, {"w": "贳账", "t": "赊账。"}]}, {"meaning": "租佃,租赁。", "cites": [{"t": "乃贳贷陂田千余顷。", "b": "《汉书·宁成传》。注:“假取之也。”"}], "words": [{"w": "贳钱", "t": "租金"}, {"w": "贳廛", "t": "租地。"}]}, {"meaning": "抵押。", "cites": [{"t": "蜀江吴水不通潮,曾共黄垆贳紫貂。", "b": "清·王士祯《遥送魏推官赴成都》"}]}, {"meaning": "买。", "cites": [{"t": "余乃就火炙衣,贳烧酒饮五杯乃行。", "b": "《徐霞客游记》"}]}, {"meaning": "赦免,宽纵。", "cites": [{"t": "因贳其罪。", "b": "《汉书·张敞传》"}, {"t": "不贳不忍。", "b": "《国语·吴语》。注:“赦也。”"}, {"t": "遂贳宽。", "b": "《汉书·刘向传》"}], "words": [{"w": "贳赦", "t": "赦免其罪"}, {"w": "贳过", "t": "宽恕过错"}, {"w": "贳患", "t": "免除祸患"}, {"w": "贳忍", "t": "宽恕容忍"}, {"w": "贳死", "t": "免死。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4112wx','荜','1','bì','艹','9','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。本义:用荆条竹木之类编成的篱笆)。"}, {"meaning": "同本义。", "cites": [{"t": "筚,荆竹织门也。亦作荜。", "b": "《玉篇》"}, {"t": "荜露兰蒌,以处草莽。", "b": "《史记·楚世家》。裴驷集解引服虔:“荜露,柴车素木也。”"}]}, {"meaning": "豆名。", "cites": [{"t": "土贡:火筋、荜豆、澡豆。", "b": "《新唐书·地理志一》"}], "words": [{"w": "荜路", "t": "柴草"}, {"w": "荜门", "t": "用荆竹和树枝所编成的门"}, {"w": "荜路蓝缕", "t": "柴车和破衣,形容创业的艰辛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4113wx','莒','1','jǔ','艹','9','','[{"pinyin": "jǔ", "defs": [{"meaning": "芋头 一种芋属植物。"}, {"meaning": "古邑名 。一为春秋时齐邑,在莒县;一为春秋时周邑(其地未详)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4114wx','茼','1','tóng','艹','9','','[{"pinyin": "tóng", "defs": [{"meaning": "一年生或二年生草本植物，叶互生，长形羽状分裂，花黄色或白色，瘦果有棱，茎叶嫩时可食，亦可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4115wx','茴','1','huí','艹','9','','[{"pinyin": "huí", "defs": [{"meaning": "茴香。", "cites": [{"t": "茴,茴香。", "b": "《玉篇》"}, {"t": "蘹香,北人呼为茴香,声相近也。", "b": "《本草纲目》引苏颂《图经本草》"}]}, {"meaning": "该种植物种子,常用作香料。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4116wx','茱','1','zhū','艹','9','','[{"pinyin": "zhū", "defs": [{"meaning": "ａ．落叶小乔木，结长椭圆形核果，红色，味酸，可入药。通称\\"山茱萸\\"；ｂ．落叶乔木，果实红色，可入药。通称\\"吴茱萸\\"；ｃ．落叶乔木，枝上有刺，羽状复叶，果实红色、球形，可入药，可提制芳香油。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4117wx','莛','1','tíng','艹','9','','[{"pinyin": "tíng", "defs": [{"meaning": "草茎,草本植物支持第二代分支、叶或其他附属物的部分。", "cites": [{"t": "莛,《说文》曰:“茎也”。东方朔曰:“以莛撞钟”,言其声不可发也。", "b": "《玉篇》"}]}, {"meaning": "棍棒。用同“梃”。", "cites": [{"t": "铸铜为钟,削木为莛,以莛叩钟,则铿然而鸣。", "b": "宋·欧阳修《钟莛说》"}]}, {"meaning": "根,枝。", "cites": [{"t": "有草一莛,孺子折之有余,数十数百万莛,壮夫莫谁何焉。", "b": "清·谭嗣同《论事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4118wx','荞','1','qiáo','艹','9','','[{"pinyin": "qiáo", "defs": [{"meaning": "荞麦  。一年生草本植物,茎略带红色,叶互生,三角状心脏形,有长柄,花白色或淡粉色,瘦果三角形,子实磨成粉供食用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4119wx','茯','1','fú','艹','9','','[{"pinyin": "fú", "defs": [{"meaning": "［茯灵］寄生在松树根上的一种菌类植物，现可人工培植。团块状，像番薯，外皮黑褐色，有皱纹，内部白色或粉红色，有红筋。包含松根的叫茯神。供药用，也可食用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4120wx','荏','1','rěn','艹','9','','[{"pinyin": "rěn", "defs": [{"meaning": "(形声。从艸,任声。本义:植物名,即白苏。一年生草本,有芳香)。"}, {"meaning": "同本义。", "words": [{"w": "荏油", "t": "用荏草籽实所榨的油。"}]}, {"meaning": "卧席。", "cites": [{"t": "文公弁荏席。", "b": "《淮南子·说山》"}]}, {"meaning": "柔弱;怯弱。", "cites": [{"t": "内荏。", "b": "《汉书·翟方进传》。注:“屈桡也。”"}, {"t": "色厉而内荏。", "b": "《论语·阳货》"}, {"t": "谌荏弱而难持!", "b": "《楚辞·九章·哀郢》"}], "words": [{"w": "荏染", "t": "柔弱的样子。"}]}, {"meaning": "大的。", "cites": [{"t": "艺之荏菽。", "b": "《诗·大雅·生民》"}], "words": [{"w": "荏菽", "t": "大豆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4121wx','荇','1','xìng','艹','9','','[{"pinyin": "xìng", "defs": [{"meaning": "荇菜。一种多年生水生草本,具心形叶和香蕉似簇生块茎。茎细长,节上生根,沉没水中。叶对生,漂浮水面。夏秋开黄花。嫩茎可食,全草入药", "words": [{"w": "荇叶", "t": "荇菜；亦指南北朝宋时铸钱币名"}, {"w": "荇带", "t": "荇菜在水中如带状"}, {"w": "荇藻", "t": "荇叶"}, {"w": "荇花", "t": "荇菜的花"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4122wx','荃','1','quán','艹','9','','[{"pinyin": "quán", "defs": [{"meaning": "(形声。从艸,全声。本义:香草名,即荪)。"}, {"meaning": "香草名。即“菖蒲”,又名“荪”。古用以比喻君主。", "cites": [{"t": "荃不揆余之中情兮。", "b": "《离骚》。注:“香草也。”"}, {"t": "荃者,所以在鱼得鱼而忘荃。", "b": "《庄子·外物》。释文:“香草也。”"}, {"t": "荃蕙蔽匿兮,胡久而不芳?", "b": "柳宗元《吊屈原文》"}], "words": [{"w": "荃宰", "t": "指君臣"}, {"w": "荃荪", "t": "香草。古代常用以喻贤良的人"}, {"w": "荃察", "t": "旧时书信中常用为希望对方鉴谅的敬辞"}, {"w": "荃芜", "t": "香草名。"}]}, {"meaning": "细切的腌芥菜。", "cites": [{"t": "荃,芥脃也。从草,全声。谓以芥为斋、鲜脃也。", "b": "《说文》"}]}, {"meaning": "捕鱼具。", "cites": [{"t": "荃者所以在鱼,得鱼而忘荃。", "b": "《庄子·外物》"}], "words": [{"w": "荃蹄", "t": "鱼苟和兔网。"}]}, {"meaning": "细布。", "cites": [{"t": "繇王闽侯亦遣建荃。", "b": "《汉书·景十三王传》"}], "words": [{"w": "荃宰", "t": "喻君臣"}, {"w": "荃察", "t": "荃,指国君;察,明察。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4123wx','荟','1','huì','艹','9','','[{"pinyin": "huì", "defs": [{"meaning": "(形声。从芔,会声。本义:草多的样子) 同本义。", "cites": [{"t": "荟,草多貌。", "b": "《说文》"}, {"t": "荟兮蔚兮。", "b": "《诗·曹风·候人》"}, {"t": "山林翳荟,必谨覆索之,此伏奸之所藏处也。", "b": "《孙子·行军》"}, {"t": "潜荟葱茏。", "b": "郭璞《江赋》"}], "words": [{"w": "荟蔚", "t": "草木茂盛的样子"}, {"w": "荟郁", "t": "草木繁盛的样子"}, {"w": "荟翳", "t": "指枝叶繁茂隐翳的草木。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4124wx','荀','1','xún','艹','9','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从艸,旬声。本义:传说中的草名)。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4125wx','茗','1','míng','艹','9','','[{"pinyin": "míng", "defs": [{"meaning": "(形声。从艸,名声。本义:早采的为“茶”,晚采的为“茗”。后泛指茶)。"}, {"meaning": "同本义。", "cites": [{"t": "晚采者为茗。", "b": "《封氏闻见记》"}], "words": [{"w": "茗纹", "t": "茶"}, {"w": "茗旗", "t": "初生的茶芽"}, {"w": "茗地", "t": "栽种茶树的地方"}, {"w": "茗舌", "t": "茶芽。谓茶芽嫩如雀舌者"}, {"w": "茗花", "t": "茶树开的花。"}]}, {"meaning": "指用茶叶泡制、烹制或煎制的饮料。", "cites": [{"t": "泉而茗者(名词。用如动词:喝茶)。", "b": "明·袁宏道《满井游记》"}, {"t": "下饮,便问人云:“此为茶,为茗?", "b": "《世说新语·纰漏》"}, {"t": "渴饮茗汁。", "b": "《洛阳伽蓝记·正觉寺》"}], "words": [{"w": "茗谈", "t": "饮茶并小叙"}, {"w": "茗汁", "t": "茶水"}, {"w": "茗柯", "t": "指茶"}, {"w": "茗饮", "t": "饮茶;茶。"}]}, {"meaning": "假借为“酩”。酩酊,大醉的样子。", "cites": [{"t": "山公时一醉,径造高阳池。日莫倒载归,茗艼无所知。", "b": "《世说新语·任诞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4126wx','荠','1','jì qí','艹','9','','[{"pinyin": "jì", "defs": [{"meaning": "指荠菜。", "cites": [{"t": "荠麦弥望。", "b": "宋·姜夔《扬州慢》词"}, {"t": "荠麦青青。", "b": ""}, {"t": "其甘如荠。", "b": "《诗·邶风·谷风》"}]}]}, {"pinyin": "qí", "defs": [{"meaning": "——见“荸荠”（bíqi）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4127wx','茭','1','jiāo','艹','9','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从草,交声。本义:蔬类植物)。"}, {"meaning": "喂牲口的干草。", "cites": [{"t": "茭,干刍。", "b": "《说文》"}, {"t": "峙乃刍茭。", "b": "《书·费誓》"}, {"t": "民茭牧其中耳。", "b": "《史记·河渠书》"}], "words": [{"w": "茭牧", "t": "收刈牧草及放养牲畜"}, {"w": "茭草", "t": "茭刍。作饲料的干草。"}]}, {"meaning": "篾缆,即用薄竹片或芦苇编成的大索。", "cites": [{"t": "搴长茭兮沈美玉。", "b": "《史记·河渠书》。"}, {"t": "搴长茭兮沉美玉。", "b": "《汉书·沟洫志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4128wx','茨','1','cí','艹','9','','[{"pinyin": "cí", "defs": [{"meaning": "(形声。从艸,次声。本义:用芦苇、茅草盖屋顶) 同本义。", "cites": [{"t": "茨,以茅苇盖屋。", "b": "《说文》"}, {"t": "环堵之室,茨以生草。", "b": "《庄子·让王》"}]}, {"meaning": "用芦苇、茅草盖的屋顶。", "cites": [{"t": "尧之王天下也,茅茨不剪,采椽不斫。", "b": "《韩非子·五蠹》"}], "words": [{"w": "茨宇", "t": "茅屋"}, {"w": "茨竹", "t": "用茅草和竹子搭盖的房子"}, {"w": "茨檐", "t": "茅舍,民房。"}]}, {"meaning": "蒺藜。", "cites": [{"t": "墙有茨,不可埽也。", "b": "《诗·鄘风·墙有茨》"}, {"t": "楚楚者茨,言抽其棘。", "b": "《诗·小雅·楚茨》"}], "words": [{"w": "茨门", "t": "茅草,芦苇所做的门"}, {"w": "茨棘", "t": "茅草与荆棘。比喻荒野。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4129wx','垩','1','è','土','9','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从土,亚声。本义:白色土,可用来粉饰墙壁) 同本义。", "cites": [{"t": "垩,白涂也。", "b": "《说文》"}, {"t": "大次之山,其阳多垩。", "b": "《山海经·西山经》。注:“垩似土,色甚白。”"}, {"t": "其土则丹青赭垩。", "b": "司马相如《子虚赋》"}, {"t": "天子诸侯黝垩。", "b": "《谷梁传·庄公二十三年》"}]}, {"meaning": "用白色涂料粉刷墙壁。", "cites": [{"t": "垩,涂也。", "b": "《广雅·释室》"}, {"t": "垩墁。", "b": "《后汉书·尹敏传》"}, {"t": "其祧则守祧黝垩之。", "b": "《周礼·司祧》"}], "words": [{"w": "垩帚", "t": "粉刷墙壁的工具"}, {"w": "垩室", "t": "古时居丧者居住的屋子,四壁用白泥粉刷"}, {"w": "垩车", "t": "服丧者乘坐的涂白色的车"}, {"w": "垩涂", "t": "涂饰"}, {"w": "垩庐", "t": "垩室。"}]}]}]','jingmo-wenyan');
