('4130wx','荥','1','xíng','艹','9','','[{"pinyin": "xíng", "defs": [{"meaning": "荥阳"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4131wx','荦','1','luò','艹','9','','[{"pinyin": "luò", "defs": [{"meaning": "(形声。从牛,劳省声。本义:杂色的牛)。"}, {"meaning": "同本义。", "cites": [{"t": "荦,驳牛也。", "b": "《说文》"}, {"t": "黄白杂谓之驳荦。", "b": "《通俗文》"}, {"t": "斯为朽关键,怒荦抉以入。", "b": "陆龟蒙《杂讽》"}]}, {"meaning": "古地名 。在今河南省淮阳县西北。"}, {"meaning": "明显,分明。", "cites": [{"t": "此其荦荦大者。", "b": "《史记·天官书》。索隐:“事之分明也。”"}], "words": [{"w": "荦然", "t": "明显的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4132wx','荨','1','qián xún','艹','9','','[{"pinyin": "qián", "defs": [{"meaning": "多年生草本植物，叶卵形，对生，开穗状小花，茎、叶生细毛，皮肤接触时会引起刺痛，茎皮纤维可以做纺织原料，亦可做麻绳"}]}, {"pinyin": "xún", "defs": [{"meaning": "一种过敏性皮疹,俗称风疹疙疸"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4133wx','荩','1','jìn','艹','9','','[{"pinyin": "jìn", "defs": [{"meaning": "进用。后引申为忠诚。", "cites": [{"t": "王之荩臣,无念尔祖。", "b": "《诗·大雅·文王》"}], "words": [{"w": "荩臣", "t": "忠臣"}, {"w": "荩言", "t": "忠言"}, {"w": "荩谋", "t": "竭忠尽善的谋略"}, {"w": "荩猷", "t": "荩谋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4134wx','剋','1','kēi','刂','9','','[{"pinyin": "kēi", "defs": [{"meaning": "[口语] 骂,严厉地斥责", "words": [{"w": "剋毒", "t": "狠毒"}]}, {"meaning": "[口语] 打", "words": [{"w": "剋架", "t": "打架"}]}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4135wx','荪','1','sūn','艹','9','','[{"pinyin": "sūn", "defs": [{"meaning": "(形声。从艸,孙声。本义:香草。一种芳香植物。亦名“荃”) 同本义。", "cites": [{"t": "薜荔拍兮蕙绸,蒸挠兮兰桂。", "b": "《楚辞·九歌·湘君》"}], "words": [{"w": "荪壁", "t": "以荪草装饰墙壁"}, {"w": "荪桡", "t": "用荪草做的船桨"}, {"w": "荪美", "t": "如香草之类。喻美德。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4136wx','茹','1','rú','艹','9','','[{"pinyin": "rú", "defs": [{"meaning": "(形声。从艸,如声。本义:吃)。"}, {"meaning": "同本义。", "cites": [{"t": "茹,食也。吴越之间,凡贪饮食者谓之茹。", "b": "《方言》。注:“今俗呼能粗食者为茹。”"}, {"t": "舜之饭糗茹草也,若将终身焉。", "b": "《孟子·尽心下》"}, {"t": "饮其血,茹其毛。", "b": "《礼记·礼运》"}, {"t": "柔则茹之。", "b": "《诗·大雅·庶民》"}, {"t": "柔亦不茹。", "b": ""}, {"t": "回之家贫,唯不饮酒不茹荤者数月矣。", "b": "《庄子·人间世》"}, {"t": "茹啖其草木荑实。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "茹荤饮酒", "t": "吃肉喝酒"}, {"w": "茹毛", "t": "太古时人们连毛带血捕食禽兽"}, {"w": "茹草", "t": "吃草"}, {"w": "茹恨", "t": "饮恨,含恨"}, {"w": "茹素", "t": "吃素食,不吃鱼肉等荤腥"}, {"w": "茹菜", "t": "吃蔬菜"}, {"w": "茹荤", "t": "本指吃葱韭等辛辣的蔬菜。后指吃鱼肉等"}, {"w": "茹薇", "t": "采食野菜"}, {"w": "茹斋", "t": "吃素食。"}]}, {"meaning": "喂。", "cites": [{"t": "茹,饭牛也。", "b": "《玉篇》"}]}, {"meaning": "贪;恣。", "cites": [{"t": "茹,贪也。", "b": "《广雅》"}, {"t": "茹,恣也。", "b": "《广韵》"}]}, {"meaning": "包含。", "cites": [{"t": "茹古涵今,无有端涯。", "b": "唐·皇甫湜《韩文公墓铭》"}], "words": [{"w": "茹内", "t": "容纳"}, {"w": "茹古涵今", "t": "犹言博古通今。"}]}, {"meaning": "猜想。", "cites": [{"t": "我心匪鉴,不可以茹。", "b": "《诗·邶风·柏舟》"}]}, {"meaning": "包,围裹。", "cites": [{"t": "十月初冻尚暖,未须茹瓮;…", "b": "《齐民要术》"}]}, {"meaning": "杂揉。", "cites": [{"t": "辰放氏作,时多阴风,乃教民搴木茹皮以御风霜。", "b": "宋·罗泌《路史》"}]}, {"meaning": "估计;猜度。"}, {"meaning": "塞。", "cites": [{"t": "诸船人行船、茹船、写漏、安标宿止不如法,…笞五十。", "b": "《唐律疏议》"}]}, {"meaning": "腐烂。", "cites": [{"t": "以茹鱼去蝇。", "b": "《吕氏春秋·功名》"}], "words": [{"w": "茹鱼", "t": "腐败发臭的鱼。"}]}, {"meaning": "蔬菜的总称。", "cites": [{"t": "白露之茹。", "b": "枚乘《七发》"}, {"t": "菜茹有畦。", "b": "《汉书·食货志上》"}]}, {"meaning": "植物的地下部分的真根、球根、块根或其他变茎 。 如: 拔茅连茹。"}, {"meaning": "柔软。", "cites": [{"t": "茹,柔也。", "b": "《玉篇》"}, {"t": "揽茹蕙以掩涕兮,沾余襟之浪浪。", "b": "《楚辞·离骚》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4137wx','荬','1','mǎi','艹','9','','[{"pinyin": "mǎi", "defs": [{"meaning": "——“苣荬菜”(qǔmǎicài):一种野生的多年生草本植物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4138wx','荮','1','zhòu','艹','9','','[{"pinyin": "zhòu", "defs": [{"meaning": "用草包裹。", "cites": [{"t": "荮,草包物也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4139wx','柰','1','nài','木','9','','[{"pinyin": "nài", "defs": [{"meaning": "木名。与“林檎”同类。", "cites": [{"t": "柰,果木名。", "b": "《广韵》"}], "words": [{"w": "柰园", "t": "种植柰树之园。"}]}, {"meaning": "茉莉,茉莉花。", "cites": [{"t": "茉莉为常绿灌木…北土曰柰。", "b": "徐珂《清稗类钞·植物类》"}, {"t": "代", "b": ""}]}, {"meaning": "奈何,如何。", "cites": [{"t": "然则柰何?", "b": "《荀子·强国》"}, {"t": "骓不逝兮可柰何,虞兮柰若何!", "b": "史记·项羽本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4140wx','栉','1','zhì','木','9','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从木,节声。本义:梳子、篦子的总称)同本义。", "cites": [{"t": "栉,梳比之总名也。", "b": "《说文》。疏:“比密曰栉,尤密者曰茝。”"}, {"t": "奠纚笄栉于筵南端。", "b": "《仪礼·士冠礼》"}, {"t": "恶笄者,栉笄也。", "b": "《仪礼·丧服礼》。注:“以栉之木为笄或曰棒笄。”"}, {"t": "其崇如墉,其比如栉。", "b": "《诗·周颂·良耜》"}, {"t": "妻执巾栉。", "b": "《庄子·寓言》"}], "words": [{"w": "栉佩", "t": "梳理用品和佩饰"}, {"w": "栉珥", "t": "梳篦和耳饰"}, {"w": "栉栉", "t": "形容排比繁密"}, {"w": "栉密", "t": "形密集排列如梳齿。"}]}, {"meaning": "用梳子梳头发。", "cites": [{"t": "今俟罪浔阳,除盥栉食寝外无余事。", "b": "白居易《与元九书》"}], "words": [{"w": "栉工", "t": "旧时称专替人梳头理发的人"}, {"w": "栉束", "t": "梳理挽结头发"}, {"w": "栉冠", "t": "梳头戴帽"}, {"w": "栉掠", "t": "梳妆"}, {"w": "栉梳", "t": "梳理"}, {"w": "栉发", "t": "梳理头发。"}]}, {"meaning": "清除。", "cites": [{"t": "栉垢爬痒,民获苏醒。", "b": "韩愈《试大理评事王君墓志铭》"}], "words": [{"w": "栉剔", "t": "清除,清剿"}, {"w": "栉垢爬痒", "t": "去脏抓痒。喻清除邪恶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4141wx','柯','1','kē','木','9','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从木,可声。本义:斧柄)。"}, {"meaning": "同本义。", "cites": [{"t": "柯,斧柄也。", "b": "《说文》"}, {"t": "柯,柄也。", "b": "《广雅》"}, {"t": "今若大其柯。", "b": "《国语·晋语》"}, {"t": "伐柯如何?匪斧不克。", "b": "《诗·豳风·伐柯》。毛传:“柯,斧柄也。”"}], "words": [{"w": "柯斧", "t": "喻法规"}, {"w": "柯长三尺", "t": ""}]}, {"meaning": "古长三尺之称。引申为法则。", "cites": [{"t": "柯,法也。", "b": "《尔雅》"}], "words": [{"w": "柯亭", "t": "法则、法度。"}]}, {"meaning": "树枝。", "cites": [{"t": "横柯上蔽。", "b": "《艺文类聚·吴均·与朱元思书》"}], "words": [{"w": "柯枝", "t": "枝条"}, {"w": "柯条", "t": "枝条"}, {"w": "柯叶", "t": "枝叶"}, {"w": "柯干", "t": "枝干。"}]}, {"meaning": "柯属植物的泛称。常绿乔木,实为长卵形,外有硬壳。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4142wx','柘','1','zhè','木','9','','[{"pinyin": "zhè", "defs": [{"meaning": "柘树 。落叶灌木或乔木,树皮灰褐色,有长刺,叶子卵形或椭圆形,花小,排列成头状花序,果实球形。叶子可以喂蚕,木材中心为黄色,质坚而致密,是贵重的木料。"}, {"meaning": "唐教坊舞曲《柘枝舞》的省称。", "cites": [{"t": "柘因零落难重舞,莲为单开不并头。", "b": "《警世通言》"}], "words": [{"w": "柘袖", "t": "柘枝舞者的衣袖"}, {"w": "柘舞", "t": "柘枝。即柘枝舞"}, {"w": "柘枝花帽", "t": "舞柘枝时所带的帽子。"}]}, {"meaning": "甘蔗。", "cites": [{"t": "有柘浆些。", "b": "《楚辞·招魂》。王夫之云:“柘,与蔗通。”"}, {"t": "泰尊柘浆析朝酲。", "b": "《汉书·礼乐志》"}, {"t": "诸柘巴苴。", "b": "司马相如《子虚赋》"}]}, {"meaning": "注:“诸柘,甘蔗也。”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4143wx','栊','1','lóng','木','9','','[{"pinyin": "lóng", "defs": [{"meaning": "(形声。从木,龙声,与下形上声的龒别。本义:养禽兽的笼槛)。"}, {"meaning": "同本义。", "cites": [{"t": "栊,槛也。", "b": "《说文》"}, {"t": "栊所以盛禽兽栏槛也。今囚栊字当作此。", "b": "《三苍》"}, {"t": "顺栊槛以俯抑。", "b": "祢衡《鹦鹉赋》"}]}, {"meaning": "窗框格;分隔并支撑窗玻璃的细木条。", "cites": [{"t": "无奈夜长人不寐,数声和月到帘栊。", "b": "李煜《捣练子》"}], "words": [{"w": "窗栊", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4144wx','柩','1','jiù','木','9','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。从木,从匚(fāng),盛东西的筐器,久声。本义:装有尸体的棺材)。"}, {"meaning": "同本义。", "cites": [{"t": "柩,棺也。", "b": "《说文》。"}, {"t": "古文湨字从匚久,后世又加木旁耳,虚者为棺,实者为柩。", "b": "《尔雅》"}, {"t": "先迁柩于庙。", "b": "《谷梁传·宣公八年》"}, {"t": "崩薨,柩之为言究也,久也,不复变也。", "b": "《白虎通》"}, {"t": "在床曰尸,在棺曰柩。", "b": "《礼记·曲礼》"}], "words": [{"w": "运柩;枢榇", "t": "装有尸体的棺材"}, {"w": "柩尸", "t": "指灵柩"}, {"w": "柩室", "t": "停放灵柩之室"}, {"w": "柩路", "t": "载灵柩之车"}, {"w": "柩殡", "t": "谓停放灵柩。"}]}, {"meaning": "铭,汉时谓刻在石碑上的字为柩。", "cites": [{"t": "设敖置铭。", "b": "《周礼》。贾公彦疏:铭所以表柩,故汉时谓铭为柩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4145wx','枰','1','píng','木','9','','[{"pinyin": "píng", "defs": [{"meaning": "(形声。从木,平声。本义:木名。即平仲)。"}, {"meaning": "木名。", "cites": [{"t": "沙棠栎槠,华枫枰栌。", "b": "《文选·司马相如·上林赋》。郭璞注:“枰,平仲木也。”"}]}, {"meaning": "下各种棋用的棋盘。", "cites": [{"t": "思不出乎一枰。", "b": "韦昭《博弈论》"}], "words": [{"w": "枰棋", "t": "谓棋局。喻局势。"}]}, {"meaning": "独坐的板床。", "cites": [{"t": "枰,平也,以板作之,其体平正也。", "b": "《释名》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4146wx','栌','1','lú','木','9','','[{"pinyin": "lú", "defs": [{"meaning": "柱头承托栋梁的短木。即欂栌、斗栱。", "cites": [{"t": "不可以为栌楝。", "b": "《淮南子·修务》"}, {"t": "标栋欂栌,以相支持。", "b": "《淮南子·本经》"}]}, {"meaning": "黄栌 。一种落叶灌木。花黄绿色,叶子秋天变成红色。木材黄色,可制器具,也可做染料。", "cites": [{"t": "华枫枰栌。", "b": "《汉书·司马相如传上》。注:“栌,今黄栌木也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4147wx','柙','1','xiá','木','9','','[{"pinyin": "xiá", "defs": [{"meaning": "(古文象形。从木,甲声。本义:关兽的木笼)。"}, {"meaning": "同本义。", "cites": [{"t": "柙,槛也,以藏虎兕。", "b": "《说文》"}, {"t": "虎兕出于柙。", "b": "《论语·季氏》"}, {"t": "实则禽槛豕匣也。", "b": "《菩提寺疏》"}, {"t": "杨幺虽有忠义之心,其余虎性岂能易驯?幸得入柙,留之必遗后患。", "b": "《后水浒传》"}], "words": [{"w": "柙板", "t": "一种刑具"}, {"w": "柙床", "t": "扣住重犯手脚的睡床。"}]}, {"meaning": "箱匣。", "cites": [{"t": "柙而藏之,不敢用也。", "b": "《庄子·刻意》"}, {"t": "君子纯终领闻,蠢迪检柙。", "b": "《法言·序》"}], "words": [{"w": "柙匮", "t": "箱柜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4148wx','枵','1','xiāo','木','9','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从木,号声。本义:木根)。"}, {"meaning": "假借为虚。虚枵一声之转。空虚。", "cites": [{"t": "岁在星纪,而淫于玄枵。玄枵,虚中也。", "b": "《左传·襄公二十八年》"}], "words": [{"w": "枵朽", "t": "空虚腐朽"}, {"w": "枵如", "t": "空虚的样子"}, {"w": "枵枵", "t": "空虚的样子"}, {"w": "枵虚", "t": "空虚。"}]}, {"meaning": "布类的丝缕稀疏而薄。", "cites": [{"t": "又有蕉纱,乃闽中取芭蕉皮析缉为之,轻细之甚,值贱而质枵,不可为衣也。", "b": "《天工开物》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4149wx','柚','1','yòu zhú','木','9','','[{"pinyin": "yòu", "defs": [{"meaning": "一种圆头柑桔属植物 (Citrus grandis),常绿乔木,叶大而阔,花白色,果实大,圆形或扁圆形,皮厚,果味酸甜。产于我国南部地区。亦指其果实,又名“文旦”,通称“柚子”。"}]}, {"pinyin": "zhú", "defs": [{"meaning": "筘 。织机上用来绕经纱的圆轴。古时用“杼柚”指织布机。", "cites": [{"t": "小东大东,杼柚其空。", "b": "《诗·小雅·大东》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4150wx','枳','1','zhǐ','木','9','','[{"pinyin": "zhǐ", "defs": [{"meaning": "枸橘,又称“臭橘”。", "cites": [{"t": "枳木似橘。从木,只声。", "b": "《说文》"}, {"t": "殷以椇。", "b": "《礼记·明堂位》。注:“椇之言枳椇也。谓曲桡之也。”"}, {"t": "楗六枳而为篱兮。", "b": "《后汉书·冯衍传》。注:“枳,芬木也。”"}, {"t": "橘逾淮而北为枳。", "b": "《周礼·考工记·序宫》"}]}, {"meaning": "一种耐寒的中国落叶橘树,有三小叶的叶片,果实小有芳香,很酸。广泛栽种作为观赏叶或作为绿篱,尤其作为砧木以芽接各种食用的柑桔。"}, {"meaning": "古县名 。战国时楚有枳邑,汉置枳县,属巴郡。故地在今四川省涪陵县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4151wx','柞','1','zhà zuò','木','9','','[{"pinyin": "zhà", "defs": [{"meaning": "水名 。汉水支流。", "cites": [{"t": "旬水又东,南迳旬阳县,与柞水合。水西出柞溪。", "b": "《水经注》"}]}]}, {"pinyin": "zuò", "defs": [{"meaning": "栎的通称 。栎属的乔木或灌木。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4152wx','柝','1','tuò','木','9','','[{"pinyin": "tuò", "defs": [{"meaning": "(形声。从木,橐声。本义:巡夜打更用的梆子)。"}, {"meaning": "同本义。", "cites": [{"t": "夕击柝而比之。", "b": "《周礼·天官·宫正》"}, {"t": "鲁击柝闻于邾。", "b": "《左传·哀公七年》"}, {"t": "抱关击柝而不以为寡。", "b": "《荀子·荣辱》"}, {"t": "大夫击门,士击柝。", "b": "《谷梁传·庄公二十五年》。范宁注:“柝,两木相击。”"}, {"t": "朔气传金柝。", "b": "《乐府诗集·木兰诗》"}, {"t": "留击柝者。", "b": "《资治通鉴·唐纪》"}], "words": [{"w": "柝击", "t": "击柝巡夜"}, {"w": "柝汲", "t": "巡夜和汲水。泛指劳作。"}]}, {"meaning": "开拓。", "cites": [{"t": "廓四方,柝八极。", "b": "《淮南子·原道》"}, {"t": "武皇帝攘四夷广土柝境,面数千里。", "b": "《潜夫论·救边》"}], "words": [{"w": "柝境", "t": "开拓境域。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4153wx','栀','1','zhī','木','9','','[{"pinyin": "zhī", "defs": [{"meaning": "栀子树，常绿灌木，夏季开白色香花，供观赏。果实也叫\\"栀子\\"或\\"黄栀子\\"，供药用或做黄色染料。木材坚实，可作雕刻用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4154wx','柢','1','dǐ','木','9','','[{"pinyin": "dǐ", "defs": [{"meaning": "(形声。从木,氐(dǐ)声。本义:树根,根柢)。"}, {"meaning": "同本义。特指直根。", "cites": [{"t": "柢,本也。", "b": "《尔雅·释言》"}, {"t": "柢也者,本之所以建生也。", "b": "《韩非子·解老》"}, {"t": "蟠木根柢。", "b": "《汉书·邹阳传》"}]}, {"meaning": "又。", "cites": [{"t": "素无根柢之容。", "b": ""}, {"t": "是谓深根、固柢,长生、久视之道也。", "b": "《老子》"}]}, {"meaning": "比喻事物的本源或基础。", "cites": [{"t": "后来村里的青年女人又要追问根柢了。", "b": "茅盾《残冬》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4155wx','栎','1','lì yuè','木','9','','[{"pinyin": "lì", "defs": [{"meaning": "即“麻栎”。通称“柞树”。", "cites": [{"t": "栎,栎木也。", "b": "《说文》"}, {"t": "山有苞栎。", "b": "《诗·秦风·晨风》"}, {"t": "白于之山,下多栎檀。", "b": "《山海经·西山经》"}, {"t": "槠栎草斗之实。", "b": "明·刘基《诚意伯刘文成公文集》"}]}, {"meaning": "一种落叶乔木,花黄褐色,果实叫橡子或橡斗。木材坚硬,可制家具,供建筑。树皮可鞣皮或做染料。叶子可喂柞蚕。另有一种栓皮栎,树皮质地轻软,富有弹性,是制造软木的主要原料。", "cites": [{"t": "山有苞栎,隰有六駮。", "b": "《诗·秦风·晨风》"}], "words": [{"w": "栎散", "t": "栎木一类无用的木料"}, {"w": "栎樗", "t": "比喻无用之材。作为才质不好的谦词。"}]}, {"meaning": "栏杆之类。", "cites": [{"t": "建章宫后阁重栎中,有物出焉。", "b": "《史记》"}]}, {"meaning": "古都邑名,春秋时郑国别都 ,在今河南省禹县。"}, {"meaning": "刮;敲;搏击。", "cites": [{"t": "嫂厌叔,叔与客来,嫂详为羹尽,栎釜,宾客以故去。", "b": "《史记·楚元王世家》"}, {"t": "栎雌妒异,倏来忽往。", "b": "潘岳《射雉赋》"}]}, {"meaning": "啮咬。", "cites": [{"t": "以牙栎之,裁断皮出血。", "b": "《艺文类聚》引《广志》"}]}]}, {"pinyin": "yuè", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4156wx','枸','1','gōu gǒu jǔ','木','9','','[{"pinyin": "gōu", "defs": [{"meaning": "盘错的树根。", "cites": [{"t": "故枸木必将待櫽栝烝矫然后直。", "b": "《荀子·性恶》"}, {"t": "有木,青叶紫茎,…,下有九枸,其实如麻,其叶如芒。", "b": "《山海经》"}]}, {"meaning": "弯曲。", "cites": [{"t": "故枸木必将待櫽括烝矫然后直。", "b": "《荀子·性恶》"}]}]}, {"pinyin": "gǒu", "defs": []}, {"pinyin": "jǔ", "defs": [{"meaning": "植物名,即蒌叶。", "cites": [{"t": "南山有枸。", "b": "《诗·小雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4157wx','柈','1','pán','木','9','','[{"pinyin": "pán", "defs": [{"meaning": "盛物之器", "cites": [{"t": "以金柈貯槟榔一斛次进之。", "b": "《南史·刘穆之传》"}], "words": [{"w": " 柈飧", "t": "盘中的熟食"}, {"w": "柈馔", "t": "盘中的食物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4158wx','柁','1','tuó','木','9','','[{"pinyin": "tuó", "defs": [{"meaning": "房架前后两个柱之间的大横梁。", "cites": [{"t": "柁檩椽架全被烟火蒸气熏得油黑油黑的。", "b": "浩然《艳阳天》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4159wx','枷','1','jiā','木','9','','[{"pinyin": "jiā", "defs": [{"meaning": "(形声。从木,加声。本义:连枷。脱粒用的农具)。"}, {"meaning": "同本义(农具名)。", "cites": [{"t": "枷,加也。加杖于柄头,以过穗而出其谷也。", "b": "《释名·释器用》"}]}, {"meaning": "刑具名 。旧时一种方形木质项圈,在东方国家使用,以套住脖子,有时还套住双手,作为惩罚。", "cites": [{"t": "枷,枷锁。", "b": "《广韵》"}, {"t": "凡死罪枷而拳,流罪枷而梏。", "b": "《隋书·刑法志》"}], "words": [{"w": "枷杻", "t": "刑具。木枷和手铐"}, {"w": "枷梢", "t": "刑具。枷板"}, {"w": "枷棒", "t": "枷和木杖"}, {"w": "枷楔", "t": "上枷和楔手指的刑罚。"}]}, {"meaning": "支持或置物的用具,衣架。", "cites": [{"t": "男女不杂坐,不同椸(yí,衣架)枷。", "b": "《礼记·曲礼上》"}]}, {"meaning": "枷住,上枷。", "cites": [{"t": "枷天狗,緤坟羊。", "b": "马融《广成颂》"}], "words": [{"w": "枷号", "t": "把木枷枷上,标明罪状,号令示众"}, {"w": "枷示", "t": "上枷示众"}, {"w": "枷杖", "t": "上枷并杖责"}, {"w": "枷革", "t": "处于枷刑并予革职。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4160wx','柽','1','chēng','木','9','','[{"pinyin": "chēng", "defs": [{"meaning": "木名。河柳,即柽柳。一种落叶小乔木,老枝红色,叶子像鳞片,夏秋两季开花,花淡红色,结蒴果。能耐碱抗旱,适于造防沙林。枝干可编筐,枝叶可入药。也叫三春柳或红柳。"}, {"meaning": "古地名 。春秋宋邑。故址在今河南省淮阳县西北。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4161wx','剌','1','lá là','刂','9','','[{"pinyin": "lá", "defs": [{"meaning": "割开;划开", "words": [{"w": "手剌破了", "t": ""}]}]}, {"pinyin": "là", "defs": [{"meaning": "(会意。从束,从刀。本义:乖戾;违背)"}, {"meaning": "同本义", "cites": [{"t": "愎佷遂过曰剌。", "b": "《周书·谥法》"}, {"t": "不乖剌。", "b": "《礼记·礼运》注"}, {"t": "至少卿乃教以 推贤进士,无乃与仆私心剌谬乎!", "b": "司马迁《报任安书》"}], "words": [{"w": "剌戾", "t": "违逆"}, {"w": "剌谬", "t": "违背；悖谬"}]}, {"meaning": "邋遢", "words": [{"w": "剌塔", "t": "剌搭,剌达,剌答。邋塔"}, {"w": "剌塌醉", "t": "大醉；烂醉"}, {"w": "剌撒", "t": "拉屎撒尿，也作“剌剌撒撒”。舒展,宽松"}]}, {"meaning": "辣辣。形容燥热", "words": [{"w": "剌剌", "t": "也作“辣辣”。象声词。咬牙声"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4162wx','酊','1','dīng dǐng','酉','9','','[{"pinyin": "dīng", "defs": [{"meaning": "“酊剂”的省称", "words": [{"w": "大黄酊", "t": ""}, {"w": "碘酊", "t": ""}]}]}, {"pinyin": "dǐng", "defs": [{"meaning": "形容大醉。"}]}]','jingmo-wenyan');
