INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4165wx','砗','1','chē','石','9','','[{"pinyin": "chē", "defs": [{"meaning": "软体动物，比蛤蜊大，有的长达一米，生活在热带海中，介壳略呈三角形，可做器物和装饰品，肉可食。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4166wx','砘','1','dùn','石','9','','[{"pinyin": "dùn", "defs": [{"meaning": "播种后用石砘子压实松土", "words": [{"w": "砘车", "t": "以圆石为轮的碾地农具"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4167wx','砒','1','pī','石','9','','[{"pinyin": "pī", "defs": [{"meaning": "“砷”的旧称。"}, {"meaning": "砒霜,砷的氧化物,有的地区叫红矾。是无臭无味的白色粉末,有时略带黄色或红色,有剧毒,可做杀虫剂。", "cites": [{"t": "我叫他买砒的时候,只说为毒老鼠,所以他不知道。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4168wx','斫','1','zhuó','斤','9','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从斤,石声。斤,斧属。本义:斧刃)。"}, {"meaning": "同本义。", "cites": [{"t": "斧以金为斫。", "b": "《墨子》"}]}, {"meaning": "大锄。", "cites": [{"t": "二月冰解地干,烧而耕之,仍即下水,十日块既散液,持木斫平之,纳种如前法。", "b": "《齐民要术》"}]}, {"meaning": "用刀、斧等砍劈。", "cites": [{"t": "因拔刀斫前奏案。", "b": "宋·司马光《资治通鉴》"}, {"t": "斫而为琴,弦而鼓之。", "b": "明·刘基《郁离子·千里马篇》"}, {"t": "斫直、删密、锄正。", "b": "清·龚自珍《病梅馆记》"}, {"t": "挥刀奋斫所当无不披靡。(奋斫:尽力砍杀)", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "斫旗", "t": "砍倒彩旗"}, {"w": "斫柴", "t": "砍柴"}, {"w": "斫柴囡", "t": "砍柴的小孩"}, {"w": "斫木", "t": "被砍削的树"}, {"w": "斫刈", "t": "砍杀"}, {"w": "斫地", "t": "砍地。表示气愤"}, {"w": "斫伐", "t": "砍伐。"}]}, {"meaning": "攻击。", "cites": [{"t": "先期率步骑万人夜斫敌营。", "b": "《宋史》"}], "words": [{"w": "斫营", "t": "偷袭敌营;劫营"}, {"w": "斫丧", "t": "催残;伤害。"}]}, {"meaning": "击。", "cites": [{"t": "白昼入乐府攻射官寺,缚束长吏子弟,斫破器物。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4169wx','砭','1','biān','石','9','','[{"pinyin": "biān", "defs": [{"meaning": "(形声。从石,乏声。本义:治病刺穴的石针)。"}, {"meaning": "同本义。", "cites": [{"t": "砭,以石刺病也。", "b": "《说文》"}, {"t": "其病皆为痈疡,其治宜砭石。", "b": "《素问·异法方宜论》"}], "words": [{"w": "砭割", "t": "用石针治病。比喻忍痛除恶。"}]}, {"meaning": "古代用石针扎皮肉治病。后用金属针以治病,也称“砭”。", "cites": [{"t": "风上逆,砭头血可愈。", "b": "《新唐书·则天武皇后传》"}], "words": [{"w": "砭磨", "t": "用石针刺磨患处。引申为救时除弊"}, {"w": "砭熨", "t": "用石针刺穴,用药物熨贴患处。指救治病痛。"}]}, {"meaning": "救治。", "cites": [{"t": "士病吾能砭。", "b": "王安石《舟中望九华山》"}], "words": [{"w": "砭俗", "t": "救治庸俗。"}]}, {"meaning": "刺。", "cites": [{"t": "其气栗冽,砭人肌骨。", "b": "欧阳修《秋声赋》"}], "words": [{"w": "砭骨", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4170wx','砜','1','fēng','石','9','','[{"pinyin": "fēng", "defs": [{"meaning": "以有磺酰基并通常借助硫与两个碳原子连结(如与两个烃基或一个简单的二价基)为特征的一类有机化合物,一般是结晶状稳定化合物,可由有机硫化物的氧化或其他方法制得。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4171wx','奎','1','kuí','大','9','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从大,圭声。从“大”,表示与人有关。本义:两髀之间)。"}, {"meaning": "同本义。胯。", "cites": [{"t": "奎,两髀之间。", "b": "《说文》。段注:“奎与胯双声。”"}, {"t": "奎踽盘桓。", "b": "《文选·张衡·西京赋》"}, {"t": "奎蹄曲隈,乳间股脚,自以为安室利处。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "奎蹄", "t": "股间和蹄边,比喻狭小的地方"}, {"w": "奎踽", "t": "举足,开步"}, {"w": "奎蹄", "t": "比喻狭小的境地。"}]}, {"meaning": "星宿名。奎宿,二十八宿之一,西方白虎七宿的第一宿,有星十六颗。", "cites": [{"t": "西方十六星,象两髀,故曰奎。", "b": "《庄子·天文书》"}], "words": [{"w": "奎壁", "t": "二十八宿中奎宿与壁宿的并称。旧谓二宿主文运,故常用以比喻文苑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4172wx','耷','1','dā','耳','9','','[{"pinyin": "dā", "defs": [{"meaning": "大耳朵。", "cites": [{"t": "耷,大耳也。", "b": "《玉篇》"}]}, {"meaning": "下垂。", "cites": [{"t": "春兰一下子耷下脸来。", "b": "梁斌《播火记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4173wx','虺','1','huī huǐ','虫','9','','[{"pinyin": "huī", "defs": [{"meaning": "累得患了病的样子", "cites": [{"t": "陟彼崔嵬,我马虺隤", "b": "《诗·周南·卷耳》"}]}]}, {"pinyin": "huǐ", "defs": [{"meaning": "(形声。从虫,兀(wù)声。本义:蜥蜴)。"}, {"meaning": "同本义。", "cites": [{"t": "胡为虺蜴。", "b": "《诗·小雅·正月》。陆疏:“一名蝾螈,水蜴也。或谓之号蟪,或谓之蛇毉。”"}, {"t": "为虺弗摧。", "b": "《国语·吴语》"}], "words": [{"w": "虺易", "t": "蜥蜴"}, {"w": "虺蜓", "t": "蜥蜴和壁虎"}, {"w": "虺蜥", "t": "蜥蜴。"}]}, {"meaning": "毒蛇,俗你土虺蛇,大毒蛇。泛指蛇类。", "cites": [{"t": "虺,蛇属,细颈大头,色如绶文,大者长七八尺。", "b": "《字汇》"}, {"t": "维虺维蛇。", "b": "《诗·小雅·斯干》"}, {"t": "虺,蝰地。", "b": "《广雅》"}, {"t": "雄虺九首。", "b": "《楚辞·天问》"}, {"t": "王虺骞只。", "b": "《楚辞·大招》"}], "words": [{"w": "虺豺", "t": "泛指毒蛇猛兽"}, {"w": "虺蛇", "t": "毒蛇。亦喻恶人"}, {"w": "虺民", "t": "毒蛇似的人"}, {"w": "虺螫", "t": "毒蛇咬"}, {"w": "虺蛇入梦", "t": "生女的徵兆"}, {"w": "虺皮", "t": "蛇皮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4174wx','殂','1','cú','歹','9','','[{"pinyin": "cú", "defs": [{"meaning": "(形声。从歹(è),且声。从“歹”,表示与死亡有关。本义:死亡) 同本义。", "cites": [{"t": "殂,往死也。", "b": "《说文》"}, {"t": "帝乃殂落。", "b": "《书·舜典》。传:殂落,死也。”"}, {"t": "放勋乃殂落。", "b": "《孟子·万章上》"}, {"t": "先帝创业未半而中道崩殂。", "b": "诸葛亮《出师表》"}], "words": [{"w": "殂谢", "t": "死亡"}, {"w": "殂夭", "t": "夭亡"}, {"w": "殂化", "t": "逝世"}, {"w": "殂没", "t": "死亡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4175wx','殇','1','shāng','歹','9','','[{"pinyin": "shāng", "defs": [{"meaning": "(形声。从歺(è),伤省声。“歺”是剔肉剩下的骨头,与“死”有关。本义:未成年而死)。"}, {"meaning": "同本义。亦称“殇折”、“殇夭”。", "cites": [{"t": "殇,不成人也。", "b": "《说文》"}, {"t": "年十九至十六为长殇,十五至十二为中殇,十一至八岁为下殇,不满八岁以下为无服之殇。", "b": "《仪礼·丧服传》"}, {"t": "未家短折曰殇。", "b": "《周礼·谥法》"}, {"t": "固知一死生为虚诞,齐彭殇为亡作。", "b": "晋·王羲之《兰亭集序》"}], "words": [{"w": "殇折,殇夭", "t": "夭折。"}]}, {"meaning": "未成年而死的人。亦称“殇子”。", "cites": [{"t": "病变而药不变,向之寿民,今为殇子矣。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "殇服", "t": "古代为殇亡者居丧的服制"}, {"w": "殇宫", "t": "殇者的灵魂。"}]}, {"meaning": "死在外面的人;战死者。", "cites": [{"t": "无主之鬼谓之殇。", "b": "《小尔雅》"}, {"t": "禁迁葬者与嫁殇者。", "b": "《周礼·媒氏》。注:“谓嫁死人也。今时娶会是也。”"}, {"t": "投躯报明主,身死为国殇。", "b": "鲍照《代出自蓟北门行》"}], "words": [{"w": "国殇", "t": "为国牺牲死于战场的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4176wx','殄','1','tiǎn','歹','9','','[{"pinyin": "tiǎn", "defs": [{"meaning": "(形声。歺(è),剔解后的残骨。隶变人“歹”。从“歺”多与死亡有关。本义:断绝;竭尽)。"}, {"meaning": "同本义。", "cites": [{"t": "殄,尽也。", "b": "《说文》"}, {"t": "余风未殄。", "b": "《书·毕命》"}, {"t": "邦国殄瘁。", "b": "《诗·大雅·瞻卬》"}, {"t": "败国尽民。", "b": "《左传·宣公二年》"}, {"t": "丁殄地财。", "b": "《淮南子·本经》"}], "words": [{"w": "殄瘁", "t": "困穷;贫病"}, {"w": "殄绝", "t": "灭绝"}, {"w": "殄世", "t": "绝嗣。"}]}, {"meaning": "消灭。", "cites": [{"t": "自王泽殄,风人辍采。", "b": "《文心雕龙·明诗》"}, {"t": "武殄暴逆。", "b": "《史记·秦始皇本纪》"}], "words": [{"w": "殄平", "t": "消灭"}, {"w": "殄熄", "t": "消灭;息灭"}, {"w": "殄灭", "t": "消灭;灭绝"}, {"w": "殄夷", "t": "杀尽"}, {"w": "殄歼", "t": "歼灭。"}]}, {"meaning": "昏迷 。", "words": [{"w": "殄靡", "t": "靡费。"}]}, {"meaning": "美好;善。", "cites": [{"t": "燕婉之求,籧篨不殄。", "b": "《诗·邶风·新台》"}], "words": [{"w": "殄沌", "t": "杂乱不分貌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4177wx','殆','1','dài','歹','9','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从歹(è),台声。本义:危险)。"}, {"meaning": "同本义。", "cites": [{"t": "殆,危也。", "b": "《说文》"}, {"t": "民今方殆,视民梦梦", "b": "《诗·小雅·正月》"}, {"t": "亦曰殆哉。", "b": "《书·秦誓》。传:“危殆。”"}, {"t": "晋有三不殆。", "b": "《左传·昭公四年》。注:“危也。”"}, {"t": "兵殆于垂沙。", "b": "《荀子·议兵》。注:“谓危亡也。”"}, {"t": "知己知彼,百战不殆。", "b": "《孙子·谋攻》"}, {"t": "三守不完,则国危身殆。", "b": "《韩非子·三守》"}, {"t": "备危恐殆,急置太子,祸乃无从起。", "b": "《韩非子·扬权》"}, {"t": "此二者,殆物也。", "b": "《韩非子·忠孝》"}], "words": [{"w": "殆危", "t": "危险。"}]}, {"meaning": "困乏;疲惫。", "cites": [{"t": "以有涯隨无涯,殆已。", "b": "《庄子·养生主》。向注:“疲困之谓也。”"}, {"t": "日将暮,步履颇殆,休于路侧。", "b": "《聊斋志异》"}]}, {"meaning": "假借为“怠”。懒惰。", "cites": [{"t": "周行而不殆。", "b": "《老子·二十五章》"}, {"t": "受命不殆。", "b": "《诗·商颂·玄鸟》"}, {"t": "滋敝邑休殆。", "b": "《左传·昭公五年》"}, {"t": "学而不思则罔,思而不学则殆。", "b": "《论语·为政下》"}]}, {"meaning": "表推测,相当于“大概”、“几乎”。", "cites": [{"t": "殆于不可。", "b": "《孟子》"}, {"t": "沛公殆天授。", "b": "《史记·留侯世家》"}, {"t": "殆有神护者。", "b": "明·归有光《项脊轩志》"}, {"t": "游历殆遍。", "b": "宋·沈括《梦溪笔谈》"}, {"t": "扬州城下,进退不由,殆例送死。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "敌人伤亡殆尽;殆其", "t": "大概"}, {"w": "殆庶", "t": "庶几,近似。"}]}, {"meaning": "表示范围,相当于“仅仅”、“只”。", "cites": [{"t": "此殆空言,非至计也。", "b": "《汉书·赵充国传》。颜师古注:“殆,仅也。”"}]}, {"meaning": "表示肯定,相当于“当然”、“必定”。", "cites": [{"t": "(彼)投吾所忌,用吾所长,是殆益敌资而遗敌胜耳,不可不察。", "b": "宋·辛弃疾《美芹十论》"}]}, {"meaning": "表示时间,相当于“将”、“将要”。", "cites": [{"t": "女心伤悲,殆及公子同归。", "b": "《诗·豳风·七月》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4178wx','轱','1','gū','车','9','','[{"pinyin": "gū", "defs": [{"meaning": "车的前胡 。车辕前端下垂的木棍,停车时靠它拄地以保持车厢平衡", "words": [{"w": "轱轮", "t": "车轮子"}, {"w": "轱轳", "t": "车轮子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4179wx','轲','1','kē','车','9','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从车,可声。本义:接轴车)。"}, {"meaning": "同本义。", "cites": [{"t": "轲,接轴车也。", "b": "《说文》"}]}, {"meaning": "专指古代孟子名。", "cites": [{"t": "孟子名轲字子舆。", "b": "《史记·孟子传》正义"}, {"t": "方今太平日无事,柄任儒术崇丘轲。", "b": "《石鼓歌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4180wx','轳','1','lu','车','9','','[{"pinyin": "lu", "defs": [{"meaning": "——见“辘轳”(lùlu)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4181wx','轶','1','yì','车','9','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从车,失声。本义:超车)。"}, {"meaning": "同本义。引申为超越。", "cites": [{"t": "轶,车相出也。", "b": "《说文》。段注:“车之后进突于前也。”"}, {"t": "轶云雨于太半。", "b": "班固《西都赋》"}, {"t": "轶,过也。", "b": "《广雅》"}, {"t": "轶鸡于姑苏。", "b": "《淮南子·览冥》。注:“自后过前曰轶。”"}, {"t": "超轶绝尘。", "b": "《庄子·徐无鬼》。成疏:“轶,过也。”"}, {"t": "轶五帝之遐迹兮,蹑三皇之高踪。", "b": "《汉书·扬雄传上》"}], "words": [{"w": "轶轨", "t": "超越"}, {"w": "轶超;轶越", "t": "超越;超过"}, {"w": "轶资", "t": "超越一般的资格。"}]}, {"meaning": "突击。", "cites": [{"t": "惧其侵轶我也。", "b": "《左传·隐公九年》"}], "words": [{"w": "轶犯", "t": "侵犯。"}]}, {"meaning": "水满出。", "cites": [{"t": "入于河,轶为荥。", "b": "《汉书·地理志上》"}]}, {"meaning": "散失。", "cites": [{"t": "《书》缺有闲矣,其轶乃时时见于他说。", "b": "《史记·五帝本纪赞》"}, {"t": "睹轶诗,可异焉。", "b": "《史记·伯夷列传》"}], "words": [{"w": "轶诗", "t": "指未编入“诗经”中的诗篇。也作“逸诗”"}, {"w": "轶义", "t": "散失了的理论和主张。"}]}, {"meaning": "车轮辗地的痕迹;车辙。", "cites": [{"t": "伏式结轶。", "b": "《史记》"}, {"t": "结轶于道。", "b": "《史记·孝文本纪》"}, {"t": "主者循轶之途也。", "b": "《战国策·齐策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4182wx','轸','1','zhěn','车','9','','[{"pinyin": "zhěn", "defs": [{"meaning": "(形声。从车。本义:车箱底部后面的横木)。"}, {"meaning": "同本义。", "cites": [{"t": "轸,车后横木也。", "b": "《说文》"}, {"t": "六分其广,以一为之轸围。", "b": "《考工记·舆人》"}, {"t": "舆下四面材合而收舆谓之轸,亦谓之收,独以为舆后横者,失其传也。", "b": "《考工记图》"}]}, {"meaning": "车的通称。", "cites": [{"t": "丙子,诏六军发轸。", "b": "《魏书》"}]}, {"meaning": "弦乐器上系弦线的小柱。可转动以调节弦的松紧。", "cites": [{"t": "以轸调声。", "b": "《魏书·乐志》。"}], "words": [{"w": "轸琴", "t": "拨弄瑶琴。"}]}, {"meaning": "田间道路。", "cites": [{"t": "以翔虚无之轸。", "b": "《淮南子·要略》"}, {"t": "含酸赴轸。", "b": "谢灵运《登临海峤初发疆中作》。李善注:“轸,当为畛。”"}, {"t": "连轸距阡陌。", "b": "阮籍《咏怀》。注:“轸,当为畛。”"}]}, {"meaning": "方形。", "cites": [{"t": "轸,方也。", "b": "《广雅》。"}], "words": [{"w": "轸石", "t": "方形的石头"}, {"w": "轸丘", "t": "方形山丘"}, {"w": "轸方", "t": "谓如轸木那样方正。"}]}, {"meaning": "悲痛。", "cites": [{"t": "出国门而轸怀兮。", "b": "屈原《九章》。"}], "words": [{"w": "轸恤", "t": "深切挂念和抚恤"}, {"w": "轸惜", "t": "悲痛惋惜"}, {"w": "轸悼", "t": "悲伤悼念。"}]}]}]','jingmo-wenyan');
