('4184wx','毖','1','bì','比','9','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从比,必声。本义:谨慎)。"}, {"meaning": "同本义。", "cites": [{"t": "毖,慎也。", "b": "《说文》"}, {"t": "汝劼毖殷献臣。", "b": "《书·酒诰》"}, {"t": "予其惩而毖后患。", "b": "《诗·周颂·小毖》"}], "words": [{"w": "毖重", "t": "慎重"}, {"w": "毖慎", "t": "慎重。"}]}, {"meaning": "假借为“泌”。泉水涌流的样子。", "cites": [{"t": "毖比泉水。", "b": "《诗·邶风·泉水》"}, {"t": "温泉毖涌而自浪。", "b": "左思《魏都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4185wx','觇','1','chān','见','9','','[{"pinyin": "chān", "defs": [{"meaning": "(形声。从见,占声。本义:暗中察看)。"}, {"meaning": "同本义。", "cites": [{"t": "觇,窥也。", "b": "《说文》"}, {"t": "公使觇之,信。", "b": "《国语·晋语六》"}, {"t": "晋人之觇宋者返。", "b": "《礼记·檀弓下》"}, {"t": "其兄掩户而入觇之。", "b": "《淮南子·俶真训》"}, {"t": "忽闻门外虫鸣,惊起觇视,蜿然尚在。", "b": "《聊斋志异·促织》"}], "words": [{"w": "觇听", "t": "窥看偷听"}, {"w": "觇视", "t": "窥视"}, {"w": "觇窥", "t": "暗中察看。"}]}, {"meaning": "窥探,侦察。", "cites": [{"t": "予更欲一觇北,归而求救国之策。", "b": "宋·文天祥《指南录后序》"}]}]}]','jingmo-wenyan');
