INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4188wx','眄','1','miǎn','目','9','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从目,丏(miǎn)声。)本义:斜视。"}, {"meaning": "同本义。", "cites": [{"t": "眄,目偏合也。", "b": "《说文》。按,目一闭一开审谛而视也。一曰袤视也。"}, {"t": "旁视曰眄。", "b": "《苍颉篇》"}, {"t": "一眄而已。", "b": "《列子·黄帝》"}, {"t": "兴眄眄。", "b": "《淮南子·览冥》。注:“视无智巧貌也。”"}, {"t": "虽羿、逢蒙不能眄睨也。", "b": "《庄子·山木》"}, {"t": "众莫不按剑相眄者。", "b": "《史记·邹阳列传》"}, {"t": "引壶觞以自酌,眄庭柯以怡颜。", "b": "陶潜《归去来辞》"}], "words": [{"w": "眄眄", "t": "无知的样子;斜视的样子"}, {"w": "眄眩", "t": "目昏晕"}, {"w": "眄视", "t": "斜着眼看"}, {"w": "眄睨", "t": "斜视。表示轻慢"}, {"w": "眄视指使", "t": "目光斜视,随手指点。形容神态骄傲。"}]}, {"meaning": "看,望。", "cites": [{"t": "俯眄流波欲寄词。", "b": "李冶《感兴》"}], "words": [{"w": "眄望", "t": "观看"}, {"w": "眄伺", "t": "窥探;侦伺。"}]}]}]','jingmo-wenyan');
