('4191wx','郢','1','yǐng','阝','9','','[{"pinyin": "yǐng", "defs": [{"meaning": "古邑名。", "cites": [{"t": "郢,故楚都,在郡江陵北十里。从邑,呈声。", "b": "《说文》。朱按,在今湖北荆州府江陵县北,楚武王自丹阳、今宜昌府归州徒此。"}]}, {"meaning": "春秋战国时楚国都城。在今湖北省江陵县纪南城。"}, {"meaning": "汉县名 。故址在今湖北省江陵县东北,纪南城东南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4192wx','眇','1','miǎo','目','9','','[{"pinyin": "miǎo", "defs": [{"meaning": "(会意兼形声。从目,从少,少亦声。本义:一只眼小)。"}, {"meaning": "同本义。", "cites": [{"t": "眇,一目小也。", "b": "《说文》"}, {"t": "眇能视,跛能履。", "b": "《易·履》"}]}, {"meaning": "又指小目。"}, {"meaning": "引申眼睛失明,或一目失明。", "cites": [{"t": "生而眇者不识日。", "b": "苏轼《日喻》"}, {"t": "见一先生,眇一目,跛一足。", "b": "明·罗贯中《全图绣像三国演义》"}], "words": [{"w": "眇视", "t": "偏盲,用一只眼看。"}]}, {"meaning": "高远;久远。", "cites": [{"t": "不厌深眇而已矣。", "b": "《庄子·庚桑楚》"}, {"t": "彼王者不然;仁眇天下,义眇天下,威眇天下。", "b": "《荀子·王制》"}, {"t": "眇不知其所蹠。", "b": "《楚辞·九章》"}], "words": [{"w": "眇漫", "t": "辽远无际的样子"}, {"w": "眇眇", "t": "辽远;高远"}, {"w": "眇绵", "t": "辽远;高远;幽远"}, {"w": "眇觌", "t": "远视"}, {"w": "眇视", "t": "远望;眯着眼看"}, {"w": "眇默", "t": "悠远;空寂"}, {"w": "眇邈", "t": "久远;遥远"}, {"w": "眇冥", "t": "长逝"}, {"w": "眇茫", "t": "渺茫。"}]}, {"meaning": "细小;微末。", "cites": [{"t": "察于微眇。", "b": "《管子·水池》"}, {"t": "眇乎小哉!", "b": "《庄子·德充符》"}, {"t": "起教于微眇。", "b": "《汉书·贾谊传》"}], "words": [{"w": "眇小", "t": "微小;指形的样子矮小瘦弱"}, {"w": "眇末", "t": "细小;琐屑"}, {"w": "眇么", "t": "微小"}, {"w": "眇生", "t": "渺小的芸芸众生"}, {"w": "眇薄", "t": "姿质菲薄"}, {"w": "眇眇", "t": "孤单无依的样子。"}]}, {"meaning": "精微,奥妙。", "cites": [{"t": "美要眇兮宜脩。", "b": "《楚辞·湘君》"}, {"t": "虽户说以眇论,终不能化。", "b": "《史记·货殖列传序》"}]}, {"meaning": "谛视;眯着眼睛看。", "cites": [{"t": "离娄眇目于豪分。", "b": "《汉书·叙传上》"}], "words": [{"w": "眇眡", "t": "仔细观看"}, {"w": "眇暚", "t": "视的样子"}, {"w": "眇绵", "t": "远视的样子"}, {"w": "眇视", "t": "远望;眯着眼看。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4193wx','眊','1','mào','目','9','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从目,毛声。本义:眼睛失神,看不清楚)。"}, {"meaning": "同本义。", "cites": [{"t": "眊,目少精也。", "b": "《说文》"}, {"t": "胸中不正,则眸子眊焉。", "b": "《孟子·离娄上》。注:“眊者,蒙蒙目不明之貌。”"}, {"t": "愦眊不知所为。", "b": "《汉书·息夫躬传》"}, {"t": "厥咎眊。", "b": "《汉书·五行志》"}], "words": [{"w": "眊目", "t": "眊眼。昏花的眼睛"}, {"w": "眊眩", "t": "眼睛迷乱失神"}, {"w": "眊昏", "t": "眼力昏花。"}]}, {"meaning": "昏聩;惑乱。", "cites": [{"t": "眊荒。", "b": "《书·吕刑》"}, {"t": "哀夫老眊孤寡鳏独。", "b": "《汉书·武帝纪》"}], "words": [{"w": "眊悖", "t": "昏聩惑乱"}, {"w": "眊弱", "t": "昏聩懦弱"}, {"w": "眊然", "t": "昏聩糊涂貌"}, {"w": "眊乱", "t": "昏聩惑乱"}, {"w": "眊荒", "t": "昏聩;糊涂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4194wx','眈','1','dān','目','9','','[{"pinyin": "dān", "defs": [{"meaning": "(形声。从目,冘(yín)声。本义:眈眈。注视的样子)。"}, {"meaning": "虎视;雄视。", "cites": [{"t": "眈,视近而志远也。从目,冘声。", "b": "《说文》"}, {"t": "虎视眈眈。", "b": "《易·颐》。马注:“虎不眎貌。”"}, {"t": "眈眈,视也。", "b": "《广雅》"}, {"t": "眈眈,威视之貌。", "b": "《汉书·叙传》注。按,训下视者,紞为组下垂,耽为耳下垂,故眈为目下视也。"}, {"t": "眈,虎视也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4195wx','禺','1','yú yù','忄','9','','[{"pinyin": "yú", "defs": [{"meaning": "区域。", "cites": [{"t": "是为十禺。", "b": "《管子·侈靡》"}]}, {"meaning": "山名 。在今浙江德清西南。", "cites": [{"t": "汪罔氏之君,守封禺之山。", "b": "《史记》"}]}, {"meaning": "旧时称日近中午为禺,约在上午九时至十一时。", "cites": [{"t": "治平元年,常州日禺时,天有大声如雷。", "b": "《梦溪笔谈》"}], "words": [{"w": "禺谷", "t": "禺渊。古代传说日落的地方"}, {"w": "禺中", "t": "将近中午。"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "(象形。小篆字形,象沐猴形。本义:兽名,一种猴) 同本义。", "cites": [{"t": "禺,母猴属,头似鬼。似猕猴而大,赤目长尾,亦曰沐猴。", "b": "《说文》"}, {"t": "有兽焉,其状如禺而自耳。", "b": "《山海经》。郭璞注:“禺似猕猴而长,赤目长尾。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4196wx','哂','1','shěn','口','9','','[{"pinyin": "shěn", "defs": [{"meaning": "微笑。", "cites": [{"t": "夫子何哂由也?", "b": "《论语·先进》"}], "words": [{"w": "聊博一哂;哂然", "t": "笑貌"}, {"w": "哂笑", "t": "微笑"}, {"w": "哂存", "t": "笑纳"}, {"w": "哂收", "t": "笑纳。"}]}, {"meaning": "讥笑。", "cites": [{"t": "童奴哂笑妻子骂,一字不给饥寒驱。", "b": "戴表元《少年行》"}], "words": [{"w": "哂笑", "t": "讥笑"}, {"w": "哂谑", "t": "调笑;戏谑。"}]}]}]','jingmo-wenyan');
