('4197wx','咴','1','huī','口','9','','[{"pinyin": "huī", "defs": [{"meaning": "1.〈拟声〉骡马的叫声＞战马～～。"}, {"meaning": "2.〈动〉喝斥＞他～了一声。"}, {"meaning": "骡马等叫声。"}, {"meaning": "象声词,形容马叫的声音。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4198wx','曷','1','hé','曰','9','','[{"pinyin": "hé", "defs": [{"meaning": "何,什么。", "cites": [{"t": "曷,何也。", "b": "《说文》"}, {"t": "呜呼!曷归?", "b": "《五·五子之歌》"}, {"t": "汝曷弗告朕?", "b": "《书·盘庚上》"}, {"t": "曷云能来?", "b": "《诗·邶风·雄雉》"}, {"t": "曷至哉?", "b": "《诗·王风·君子于役》"}, {"t": "亦曷故哉?", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "曷故", "t": "何故"}, {"w": "曷胜", "t": "何胜"}, {"w": "曷尝", "t": "何尝。"}]}, {"meaning": "怎么;为什么。", "cites": [{"t": "曷不委心任去留。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "曷为", "t": "为何;为什么"}, {"w": "曷苦", "t": "怎么样;怎样。"}]}, {"meaning": "为什么不,何不?——常含有劝告的意思。", "cites": [{"t": "此地不久必大乱,不可留也,曷避之?", "b": "清·王士禛《池北偶谈》"}]}, {"meaning": "加强反问语气,相当于“岂”,“难道”。", "cites": [{"t": "礼云礼云,曷其然哉?", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4199wx','昴','1','mǎo','日','9','','[{"pinyin": "mǎo", "defs": [{"meaning": "星名。", "cites": [{"t": "昴,白虎宿星。从日,卯声。", "b": "《说文》。按,西方宿,六星,其形促聚。"}, {"t": "维参与昴。", "b": "《诗·召南·小星》"}]}, {"meaning": "二十八宿之一,西方白虎七宿的第四宿。有星四颗。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4200wx','昱','1','yù','日','9','','[{"pinyin": "yù", "defs": [{"meaning": "明天。", "cites": [{"t": "昱,明日也。从日,立声。", "b": "《说文》。段玉裁注:“凡经传子史,翌日字皆昱日之假借,翌与昱同立声,故相借。”"}], "words": [{"w": "昱日", "t": "明天。"}]}, {"meaning": "照耀。", "cites": [{"t": "日以昱乎昼,月以昱乎夜。", "b": "《太玄·告》"}]}, {"meaning": "光辉灿烂的,明亮而闪闪发光的。", "cites": [{"t": "焜昱错眩。", "b": "《淮南子·本经》"}, {"t": "后一日不亡,帝一日不得亲政。则此七年者,月之朗于夜,非日之昱于昼也。", "b": "王夫之《宋论·哲宗》"}], "words": [{"w": "昱昱,昱耀", "t": "明亮"}, {"w": "昱奕", "t": "明盛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4201wx','昵','1','nì','日','9','','[{"pinyin": "nì", "defs": [{"meaning": "(形声。从日,尼声。字又作“暱”。从日,匿(nì)声。本义:亲近,亲昵) 同本义。", "cites": [{"t": "暱,日近也。", "b": "《说文》"}, {"t": "暱,近也。", "b": "《尔雅》。孙注:“亲之近也。”"}, {"t": "无自暱焉。", "b": "《诗·小雅·菀柳》"}, {"t": "官不及私昵。", "b": "《书·说命中》"}, {"t": "昵比罪人。", "b": "《书·泰誓中》"}, {"t": "王胡之与无忌长甚相昵,胡之尝共游。", "b": "《世说新语·仇隙》"}], "words": [{"w": "昵交", "t": "亲近的朋友"}, {"w": "昵侍", "t": "近侍,亲侍"}, {"w": "昵就", "t": "亲近;亲昵"}, {"w": "昵友", "t": "亲密的朋友"}, {"w": "昵比", "t": "亲近勾结"}, {"w": "昵好", "t": "亲善"}, {"w": "昵近", "t": "亲近"}, {"w": "昵狎", "t": "亲近;亲狎"}, {"w": "昵依", "t": "偎依"}, {"w": "昵道", "t": "近路;捷径。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4202wx','咦','1','yí','口','9','','[{"pinyin": "yí", "defs": [{"meaning": "表示感叹,相当于“啊”。", "cites": [{"t": "咦!正是:…,英雄气概等时休。", "b": "《西游记》"}]}, {"meaning": "表示嘲讽、鄙夷。", "cites": [{"t": "咦!不害臊!要是让你回去,只怕连你还烧在里头呢!", "b": "《老残游记》"}]}, {"meaning": "歌曲中的衬字。", "cites": [{"t": "冒着那个风雪呀,送上前线咦呀嗨。", "b": "歌剧《刘胡兰》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
