INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4205wx','畎','1','quǎn','田','9','','[{"pinyin": "quǎn", "defs": [{"meaning": "(象形。从田,犬声。本义:田间水沟)。"}, {"meaning": "同本义。", "cites": [{"t": "畎,水小流也。象形。古文从田,川声。篆文从田,犬声。", "b": "《说文》"}, {"t": "居于畎亩之中。", "b": "《庄子·让王》"}], "words": [{"w": "畎田", "t": "在田中开小水沟"}, {"w": "畎遂", "t": "田中小水沟"}, {"w": "畎浍", "t": "田间水沟"}, {"w": "畎渎", "t": "田间沟渠"}, {"w": "畎陇", "t": "田间垄沟。"}]}, {"meaning": "疏通。", "cites": [{"t": "畎引江海以灌田。", "b": "顾炎武《天下郡国利病书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4206wx','毗','1','pí','比','9','','[{"pinyin": "pí", "defs": [{"meaning": "(形声。从田,比声。本义:人脐)。"}, {"meaning": "人的肚脐。"}, {"meaning": "春秋时鲁国城邑名。", "cites": [{"t": "五年,春,城毗。", "b": "《春秋》"}]}, {"meaning": "辅助,从旁协助。", "cites": [{"t": "辅毗安顺。", "b": "《太尉刘宽碑》"}, {"t": "为国毗辅。", "b": "《绥民校尉熊君碑》"}], "words": [{"w": "毗助", "t": "毗佐、毗奉、毗辅、毗翼。辅助"}, {"w": "毗益", "t": "辅助;助益"}, {"w": "毗赞", "t": "辅佐;襄助。"}]}, {"meaning": "附和。", "cites": [{"t": "天之方懠,无所夸毗。", "b": "《诗·大雅》。朱熹集传:“夸,大也;毗,附也。”"}]}, {"meaning": "增益。", "cites": [{"t": "轧言及政事,多所毗补。", "b": "《后汉书·明德马皇后纪》"}]}]}]','jingmo-wenyan');
