('4207wx','呲','1','cī','口','9','','[{"pinyin": "cī", "defs": [{"meaning": "〖口语〗申斥,斥责。", "cites": [{"t": "呲,苛也。 ", "b": "《说文》 "}, {"t": "呲其所不为者也。 ", "b": "《庄子·列御寇》"}], "words": [{"w": "挨了一顿呲", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4208wx','胄','1','zhòu','月','9','','[{"pinyin": "zhòu", "defs": [{"meaning": "(形声。“胄”古有两个字。小篆字形从肉,由声。本义:头盔)。"}, {"meaning": "同本义。", "cites": [{"t": "胄,兜鍪也。从月,由声。", "b": "《说文》"}, {"t": "离为甲胄。", "b": "《易·说卦》"}, {"t": "惟甲胄起戎。", "b": "《书·伪说命》"}, {"t": "贝胄朱綅。", "b": "《诗·鲁颂·閟宫》"}, {"t": "献甲者执胄。", "b": "《礼记·曲礼》"}, {"t": "左右免胄而下。", "b": "《左传·僖公三十三年》"}, {"t": "冠軸(胄)带剑。", "b": "《荀子·议兵》"}, {"t": "铠胄皆镔铁。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "甲胄", "t": ""}]}, {"meaning": "古代称帝王或贵族的后代。", "cites": [{"t": "刘公乃帝室之胄,德广才高,可领徐州。", "b": "《全图绣像三国演义》"}, {"t": "帝室之胄。", "b": "《三国志·诸葛亮传》"}, {"t": "王室之胄。", "b": "《资治通鉴》"}], "words": [{"w": "胄子", "t": "帝王或贵族的长子"}, {"w": "胄监", "t": "国子监"}, {"w": "胄阀", "t": "家世门第。"}]}, {"meaning": "泛指世系。", "cites": [{"t": "岂孤人之能胄。", "b": "《遂志赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4209wx','畋','1','tián','田','9','','[{"pinyin": "tián", "defs": [{"meaning": "(会意。从攴(pū)田。“攴”表示手的动作。本义:打猎)。"}, {"meaning": "同本义。", "cites": [{"t": "畋,取禽兽也。", "b": "《广韵》"}, {"t": "畋于有洛之表。", "b": "《书·五子之歌》"}, {"t": "以畋于云梦。", "b": "《吕氏春秋·直谏》"}, {"t": "与使者出畋。", "b": "司马相如《子虚赋》"}, {"t": "外绝畋猎之源。", "b": "魏征《士渐不克终疏》"}], "words": [{"w": "畋弋", "t": "打猎"}, {"w": "畋犬", "t": "猎犬"}, {"w": "畋狩,畋猎", "t": "打猎"}, {"w": "畋马", "t": "用于打猎的马匹"}, {"w": "畋游", "t": "畋猎游乐"}, {"w": "畋渔", "t": "打猎和捕鱼。"}]}, {"meaning": "平田;耕种。", "cites": [{"t": "畋,平田也。", "b": "《说文》"}, {"t": "今尔尚尔宅,畋尔田。", "b": "《书·多方》"}, {"t": "孙权自十数年以来,大畋江北,缮治甲兵。", "b": "《三国志·齐王芳纪注》"}], "words": [{"w": "畋食", "t": "谓以耕营田地为生。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4210wx','畈','1','fàn','田','9','','[{"pinyin": "fàn", "defs": [{"meaning": "平畴,成片的田。", "cites": [{"t": "畈哩,田野间。", "b": "清·范寅《越谚》"}, {"t": "畈,田畈,平畴也。", "b": "《字汇》"}]}, {"meaning": "如白水畈(在湖北省)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4211wx','虼','1','gè','虫','9','','[{"pinyin": "gè", "defs": [{"meaning": "昆虫，赤褐色，善跳跃，寄生在人畜的身体上，吸血液，能传染鼠疫等疾病。", "cites": [{"t": "他会变苍蝇、蚊子、虼蚤。--《西游记》", "b": ""}]}, {"meaning": "虼蚤脸儿，好大面皮虼蚤的脸很小，喻人微言轻，没面子。"}, {"meaning": "虼蚤性，比喻暴跳的脾气。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4212wx','虻','1','méng','虫','9','','[{"pinyin": "méng", "defs": [{"meaning": "虻科的各种大而强壮、飞行迅速的双翅蝇。成虫像蝇,生活在草丛,吮吸人兽的血液。", "cites": [{"t": "蝱,啮牛飞虫也。从双虫,亡声。", "b": ""}, {"t": "博牛之蝱不可以破虮虱。", "b": "《史记》"}], "words": [{"w": "虻蚊", "t": "蚊虻"}, {"w": "虻翅", "t": "指刚萌生的极为细小的树叶。如虻之翅,故称。"}]}, {"meaning": "迅疾。"}]}]','jingmo-wenyan');
