INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4215wx','哕','1','yuě huì','口','9','','[{"pinyin": "yuě", "defs": [{"meaning": "打呃。", "cites": [{"t": "中央生湿…在变动为哕。", "b": "《素问》"}]}, {"meaning": "引申为欲言又止的样子。", "cites": [{"t": "幽穷共谁语,思想甚含哕。", "b": "唐·韩愈《送文畅帅北游》"}], "words": [{"w": "哕咽", "t": "气窒塞不通"}, {"w": "哕噫", "t": "打呃;打嗝儿。"}]}, {"meaning": "呕吐。亦指呕吐物。", "cites": [{"t": "你们快去烧些盐白汤,等我灌下肚去,把他哕出来。", "b": "《西游记》"}], "words": [{"w": "哕出许多清痰;哕吐", "t": "呕吐"}, {"w": "哕心沥血", "t": "呕心沥血"}, {"w": "哕逆", "t": "恶心干呕"}, {"w": "哕饭", "t": "经细嚼后吐出之饭。"}]}, {"meaning": "唾骂;唾弃。", "cites": [{"t": "秦人皆哕其名。", "b": "清·钱谦益文"}], "words": [{"w": "哕骂", "t": "唾骂。"}]}, {"meaning": "唾,用力吐唾沫。", "cites": [{"t": "计氏望着那养娘,稠稠的唾沫,猛割丁向脸上哕了一口。", "b": "《醒世姻缘传》"}]}]}, {"pinyin": "huì", "defs": [{"meaning": "有节奏的铃声"}, {"meaning": "光明的样子"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4216wx','剐','1','guǎ','刂','9','','[{"pinyin": "guǎ", "defs": [{"meaning": "(形声。从刀,咼(kuā)声。本义:割肉离骨)。"}, {"meaning": "同本义。古时分割人体的酷刑。凌迟的俗称。", "cites": [{"t": "合拟凌迟,押赴市曹中,钉上木驴,剐一百二十刀处死。", "b": "元·关汉卿《窦娥冤》"}]}, {"meaning": "被尖锐的东西划破。", "cites": [{"t": "我只是让车剐了一下。", "b": "《一件珍贵的衬衫》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4217wx','郧','1','yún','阝','9','','[{"pinyin": "yún", "defs": [{"meaning": "古国名。", "cites": [{"t": "郧,汉南之国也。", "b": "《说文》"}]}, {"meaning": "在今湖北省安陆县。春秋时为楚所灭。"}, {"meaning": "古地名。"}, {"meaning": "春秋卫地。故城在今江苏省如皋县。"}, {"meaning": "春秋吴地,在今江苏省如皋县东。"}]}]','jingmo-wenyan');
