INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4219wx','囿','1','yòu','囗','9','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从囗(wéi),有声。“囗”表示范围和区域。本义:古代帝王养禽兽的园林)。"}, {"meaning": "同本义。", "cites": [{"t": "囿,苑有垣也。", "b": "《说文》"}, {"t": "有垣曰苑,无垣曰囿。", "b": "《字林》"}, {"t": "囿有林池,从从木有介。", "b": "《国语·周语》"}, {"t": "王在灵囿。", "b": "《诗·大雅·灵台》"}, {"t": "古谓之囿,汉家谓之苑。", "b": "《周礼·囿人》疏"}, {"t": "启县囿卖酒,游人沓至。", "b": "洪迈《夷坚丁志》"}], "words": [{"w": "囿苑", "t": "饲养禽兽的园囿"}, {"w": "囿人", "t": "官名。主管苑囿禽兽"}, {"w": "囿游", "t": "帝王的离宫别苑。"}]}, {"meaning": "泛指四周有栏挡的菜园、果园。", "cites": [{"t": "[正月]囿有韭。", "b": "《大戴礼记》"}]}, {"meaning": "事物的萃聚之所。", "cites": [{"t": "游乎六艺之囿,驰骛乎仁义之涂。", "b": "汉·司马相如《上林赋》"}]}, {"meaning": "拘泥。", "cites": [{"t": "识不通广曰囿,犹言拘墟也。", "b": "《正字通》"}], "words": [{"w": "囿于成见;囿于一隅", "t": ""}]}]}]','jingmo-wenyan');
