('4250wx','郜','1','gào','阝','9','','[{"pinyin": "gào", "defs": [{"meaning": "古国名。", "cites": [{"t": "郜,周文王子所封国。从邑,告声。", "b": "《说文》"}]}, {"meaning": "在今山东省成武县东南。春秋时为宋所灭。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4251wx','秕','1','bǐ','禾','9','','[{"pinyin": "bǐ", "defs": [{"meaning": "中空或不饱满的谷粒。", "cites": [{"t": "秕,不成粟也。从禾,比声。", "b": "《说文》"}, {"t": "用秕稗也。", "b": "《左传·定公十年》。注:“谷不成者。今苏俗呼谷不充者曰瘪谷,盖即此字。字亦以粃为之。”"}], "words": [{"w": "秕稗", "t": "秕与稗。喻败坏无用之物"}, {"w": "秕蠹", "t": "瘪谷和蠹虫。比喻不良、有害之物"}, {"w": "秕粮", "t": "稗草。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4252wx','秭','1','zǐ','禾','9','','[{"pinyin": "zǐ", "defs": [{"meaning": "万亿。", "cites": [{"t": "“秭,数亿至万曰秭”。", "b": "《说文》"}]}, {"meaning": "十亿。", "cites": [{"t": "秭,数也。", "b": "《尔雅》。郭璞注:“今以十亿为秭。”"}]}, {"meaning": "千亿。", "cites": [{"t": "《广韵》:“秭,千亿也。”", "b": ""}, {"t": "《风俗通》:“千生万,万生亿,亿生兆,兆生京,京生秭。”", "b": ""}]}, {"meaning": "中国物理学会的大小数命名法中用来表示1015数值的字 。现在用国际制词头“拍它”,简作“拍”,符号P。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4253wx','竽','1','yú','竹','9','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从竹,于声。从竹的字有时与乐器有关。本义:古簧管乐器。形似笙而略大) 同本义 。战国时盛行于民间。", "cites": [{"t": "竽,竹三十六簧也。", "b": "《说文》。按,管乐也。"}, {"t": "调竽奇声以耳异。", "b": "《荀子·正名》"}], "words": [{"w": "竽瑟", "t": "竽与瑟"}, {"w": "竽籁", "t": "指笙和箫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4254wx','笈','1','jí','竹','9','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从竹,及声。本义:竹书箱)。"}, {"meaning": "同本义。多用竹、藤编织,用以放置书籍、衣巾、药物等。", "cites": [{"t": "极,驴上负也。从木,及声,读若急,字亦作笈。", "b": "《说文》"}, {"t": "负笈从师。", "b": "《史记·苏秦传》"}, {"t": "笈,谓学士所以负书箱。", "b": "《周处风土记》"}], "words": [{"w": "笈囊", "t": "笈与囊。"}]}, {"meaning": "书籍;典籍。", "cites": [{"t": "山坛毛公蜕,古笈灵威守。", "b": "清·王识禛诗"}], "words": [{"w": "孤本秘笈", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4255wx','笃','1','dǔ','竹','9','','[{"pinyin": "dǔ", "defs": [{"meaning": "(形声。从马,竹声。本义:马行迟顿)。"}, {"meaning": "同本义。", "cites": [{"t": "笃,马行顿迟也。", "b": "《说文》"}, {"t": "笃癃无家属。", "b": "《后汉书·先武纪》。注引《尔雅》曰:“笃,困也。”"}], "words": [{"w": "笃么", "t": "笃笃末末,笃笃寞寞。转来转去,徘徊不前。"}]}, {"meaning": "忠实,不虚伪。", "cites": [{"t": "朋友不笃,非孝也。", "b": "《吕氏春秋·孝行》"}, {"t": "慎思之,明辨之,笃行之。", "b": "《礼记·中庸》"}, {"t": "笃公刘。", "b": "《诗·大雅·公刘》"}, {"t": "尧九男,皆益笃。", "b": "《史记·五帝纪》"}], "words": [{"w": "笃人", "t": "忠实厚道的人"}, {"w": "笃仁", "t": "笃实而仁厚"}, {"w": "笃亮", "t": "笃实亮直"}, {"w": "笃美", "t": "笃实美善"}, {"w": "笃敏", "t": "诚笃而敏锐"}, {"w": "笃教", "t": "竭诚于教化"}, {"w": "笃烈", "t": "诚厚刚正。"}]}, {"meaning": "厚。", "cites": [{"t": "笃,厚也。", "b": "《尔雅·释诂》"}, {"t": "硕大且笃。", "b": "《诗·唐风·椒聊》"}, {"t": "予嘉乃德,日笃不忘。", "b": "《书·微子之命》"}]}, {"meaning": "切实;确凿。", "cites": [{"t": "论笃是与,君子者乎?", "b": "《论语·先进》"}], "words": [{"w": "笃论", "t": "确当的言论"}, {"w": "笃见", "t": "确切的见解。"}]}, {"meaning": "深厚。", "cites": [{"t": "仆道不笃,业甚浅近。", "b": "唐·柳宗元《答韦中立论师道书》"}], "words": [{"w": "笃好", "t": "交情深厚"}, {"w": "笃正", "t": "纯厚正直"}, {"w": "笃古", "t": "纯厚古朴;好古"}, {"w": "笃至", "t": "深厚到了极点"}, {"w": "笃尚", "t": "纯厚高尚"}, {"w": "笃恭", "t": "纯厚恭敬。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4256wx','俦','1','chóu','亻','9','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从人,寿声。本义:伴侣)。"}, {"meaning": "同本义。", "cites": [{"t": "俦,侣也。", "b": "《玉篇》"}, {"t": "无介俦。", "b": "扬雄《太玄》卷六剧"}]}, {"meaning": "注:“俦,匹也。”。", "cites": [{"t": "命俦啸侣。", "b": "曹植《洛神赋》"}], "words": [{"w": "俦侣", "t": "朋友,伴侣"}, {"w": "俦匹", "t": "伴侣"}, {"w": "俦伴", "t": "伴侣,同伴。"}]}, {"meaning": "同类,辈。", "cites": [{"t": "俦善博惠。", "b": "《鬼谷子·中经》"}, {"t": "我闻今相国昆山顾秉谦者,严相国俦也。", "b": "侯方域《马伶传》"}], "words": [{"w": "俦类", "t": "同辈"}, {"w": "俦俪", "t": "同一品类。同辈"}, {"w": "俦伍", "t": "同类之人;同等之人。"}]}, {"meaning": "表示疑问,相当于“谁”。", "cites": [{"t": "使见善不明,用心不刚,俦克尔。", "b": "《法言·修身》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4257wx','俨','1','yǎn','亻','9','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从人,严声。本义:恭敬;庄重)。"}, {"meaning": "同本义。", "cites": [{"t": "俨,敬也。", "b": "《尔雅·释诂》"}, {"t": "俨若思。", "b": "《礼记·曲礼》。注:“矜庄貌。”"}, {"t": "望之俨然。", "b": "《论语》"}, {"t": "汤禹俨而求合兮。", "b": "《离骚》。注:“敬也。”"}, {"t": "仆夫俨其正策兮。", "b": "《思元赋》"}, {"t": "俨乎其若思。", "b": "唐·韩愈《朱文公校昌黎先生集》"}], "words": [{"w": "俨束", "t": "庄重而不放任"}, {"w": "俨重", "t": "庄重"}, {"w": "俨雅", "t": "恭敬庄重"}, {"w": "俨格", "t": "庄严恭敬"}, {"w": "俨俨", "t": "庄严貌。"}]}, {"meaning": "美艳。", "cites": [{"t": "有美一人,硕大且俨。", "b": "《诗·陈风》"}]}, {"meaning": "宛如,十分像。", "cites": [{"t": "是那处曾相见?相看俨然。", "b": "汤显祖《牡丹亭》"}], "words": [{"w": "俨尔", "t": "真切、逼真的样子;宛如。"}]}, {"meaning": "昂首。", "cites": [{"t": "俨,昂头也。", "b": "《说文》"}, {"t": "若俨见旒,若俯见冕。", "b": "唐·来鹄《圣政纪颂》"}]}, {"meaning": "整理,使整齐。", "cites": [{"t": "惊起俨衣冠,拜舞苍台破。", "b": "宋·王元之《七夕》"}], "words": [{"w": "俨存", "t": "很分明地保存、存在。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4258wx','俅','1','qiú','亻','9','','[{"pinyin": "qiú", "defs": [{"meaning": "恭顺的样子。", "cites": [{"t": "俅,冠饰貌。从人,求声。诗曰:弁服俅俅。", "b": "《说文》"}, {"t": "载弁俅俅。", "b": "《诗·周南·丝衣》"}]}, {"meaning": "戴。", "cites": [{"t": "俅,戴也。", "b": "《尔雅》"}]}, {"meaning": "用同“救”。", "cites": [{"t": "当贫贱或急难时,资人俅援。", "b": "俞文豹《吹剑录全编》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4259wx','俪','1','lì','亻','9','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从人,丽声。字即丽的或体。本义:配偶)同本义。", "cites": [{"t": "俪,耦也。", "b": "《广雅》"}, {"t": "弃其伉俪妃嫔。", "b": "《国语·周语》"}, {"t": "鸟兽犹不失俪,子将若何?", "b": "《左传·成公十一年》"}], "words": [{"w": "伉俪", "t": "夫妻"}, {"w": "俪祉", "t": "向他人夫妇祝福之辞"}, {"w": "俪影", "t": "夫妇二人的身影;称人夫妇之合影。"}]}, {"meaning": "相称;对仗,对偶。", "cites": [{"t": "安可以俪王公而著风烈也。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "文以耦俪为主;骈俪", "t": "文章的对偶句法"}, {"w": "俪巧", "t": "对偶精巧"}, {"w": "俪句", "t": "对偶的句子"}, {"w": "俪体", "t": "对偶的文体。"}]}, {"meaning": "并列,比。", "cites": [{"t": "凤凰不能与之俪。", "b": "刘安《淮南子》"}]}, {"meaning": "成对的,成双的。", "cites": [{"t": "主人酬宾,束帛俪皮。", "b": "《仪礼·士冠礼》"}, {"t": "束帛、俪皮,如纳吉礼。", "b": "《仪礼·士昏礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4260wx','叟','1','sōu sǒu','又','9','','[{"pinyin": "sōu", "defs": [{"meaning": "叟叟:淘米声。", "cites": [{"t": "释之叟叟,烝之浮浮。", "b": "《诗·大雅·生民》"}]}]}, {"pinyin": "sǒu", "defs": [{"meaning": "(会意。本作“叜”。意谓手拿火把在室内搜索。本义:求)搜索;搜查。", "cites": [{"t": "叜,老也。从又从灾。", "b": "《说文》。朱骏声注:“(叟)即搜之古文。从又持火,屋下索物也。会意。”"}, {"t": "合群叟。", "b": "《国语·齐语》"}]}, {"meaning": "“叟”。假借为“傁”,老的男人。也用作对老年男子的尊称。", "cites": [{"t": "王曰叟。", "b": "《孟子·梁惠王上》。注:“叟,长老之称。”"}, {"t": "叟何人耶?", "b": "《庄子·在宥》"}, {"t": "河曲智叟笑而止之。", "b": "《列子·汤问》"}, {"t": "河曲智叟亡以应。", "b": ""}, {"t": "叟,不远千里而来,亦将有以利吾国乎?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "老叟;童叟无欺", "t": ""}]}, {"meaning": "叟族 中国汉至六朝时,对今甘肃东南部、四川西部、云南东部、贵州西部等地区部分少数民族的泛称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4261wx','垡','1','fá','土','9','','[{"pinyin": "fá", "defs": [{"meaning": "耕地翻土。", "cites": [{"t": "余期报恩后,谢病老耕垡。", "b": "唐·韩愈《送文畅师北游》"}], "words": [{"w": "垡子地", "t": "方言。经翻耕的土地。"}]}, {"meaning": "翻耕过的土块。", "cites": [{"t": "逆垡掷豆,然后劳之。", "b": "《齐民要术·大豆》"}], "words": [{"w": "垡头", "t": "方言。土块。"}]}]}]','jingmo-wenyan');
