INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4264wx','俚','1','lǐ','亻','9','','[{"pinyin": "lǐ", "defs": [{"meaning": "(形声。从人,里声。本义:聊赖)。"}, {"meaning": "同本义,赖以生活或依靠的事物。", "cites": [{"t": "俚,聊也。", "b": "《说文》。按,聊者,赖也。"}, {"t": "夫婢妾贱人,感概而自杀,非能勇也,其画无俚之至耳。", "b": "《汉书·李布栾布田叔传》"}]}, {"meaning": "中国古代少数民族之一 。东汉至隋唐屡见于史籍,常与僚并称,主要分布在今广东西南沿海及广西东南等地。少数移入桂西。"}, {"meaning": "粗俗。", "cites": [{"t": "非鄙俚之言所能具。", "b": "左思《魏都赋》"}], "words": [{"w": "俚室", "t": "贫贱之家"}, {"w": "俚人", "t": "粗俗之人"}, {"w": "俚率", "t": "粗俗直率"}, {"w": "俚浅", "t": "粗俗浅陋。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
