INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4266wx','俑','1','yǒng','亻','9','','[{"pinyin": "yǒng", "defs": [{"meaning": "(形声。从人,甬(yǒng)声。本义:古代陪葬用的偶人,一般为木制或陶制。因象人。故从人) 同本义。", "cites": [{"t": "俑,木人。送葬设关,而能跳踊,故名之。", "b": "《埤苍》"}, {"t": "俑有面目机发,似于生人。", "b": "《通典》引《礼记》"}, {"t": "孔子谓为刍灵者善,谓为俑者不仁,殆于用人乎哉。", "b": "《礼记·檀弓》"}], "words": [{"w": "陶俑;武士俑", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4267wx','俟','1','qí sì','亻','9','','[{"pinyin": "qí", "defs": [{"meaning": "——“万俟”(Mòqí):复姓。"}]}, {"pinyin": "sì", "defs": [{"meaning": "(形声。从人,矣声。本义:大) 同本义。", "cites": [{"t": "俟,大也。", "b": "《说文》"}, {"t": "儷儷俟俟,或群或友。", "b": "《诗·小雅·吉日》"}]}, {"meaning": "等待。", "cites": [{"t": "静女其姝,俟我于城隅。", "b": "《诗·邶风·静女》"}, {"t": "俟于门外。", "b": "《仪礼·士昏礼》"}, {"t": "如其礼乐,以俟君子。", "b": "《论语·先进》"}, {"t": "故君子居易以俟命,小人行险以徼幸。", "b": "《礼记·中庸》"}, {"t": "故为之说,以俟夫观人风者得焉。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "俟命", "t": "等待命令"}, {"w": "俟吉", "t": "等待吉日"}, {"w": "俟候", "t": "等待;等候"}, {"w": "俟时", "t": "等待时机"}, {"w": "俟望", "t": "等待盼望"}, {"w": "俟嗣", "t": "等待继位"}, {"w": "俟河之清", "t": "等待黄河水清,比喻希望不可能实现。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4268wx','逅','1','hòu','辶','9','','[{"pinyin": "hòu", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,后声。邂逅:未相约而遇见)——“邂逅”(xièhòu):不期而遇。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4269wx','徇','1','xùn','彳','9','','[{"pinyin": "xùn", "defs": [{"meaning": "(形声。从彳(chì),旬声。“彳”与行有关。本义:迅速,敏捷) 同本义。", "cites": [{"t": "侚,疾也。从人,旬声,字亦误作徇。", "b": "《说文》"}, {"t": "黄帝幼而徇齐。", "b": "《史记·五帝纪》。集解:“疾也,失之。”"}, {"t": "年逾五十则聪明思虑徇通矣。", "b": "《墨子》"}], "words": [{"w": "徇通", "t": "敏捷通达"}, {"w": "徇智", "t": "敏慧"}, {"w": "徇齐", "t": "疾速。"}]}, {"meaning": "巡行。", "cites": [{"t": "王乃徇师而誓。", "b": "《书·泰誓中》"}, {"t": "将兵徇蕲以东。", "b": "《史记·陈涉世家》"}], "words": [{"w": "徇铺", "t": "巡查街市里巷"}, {"w": "徇察", "t": "巡行察访。"}]}, {"meaning": "巡行示众。", "cites": [{"t": "杀颠颉以徇于师。", "b": "《左传·僖公二十八年》"}, {"t": "以徇三军。", "b": "《史记·司马穰苴传》"}, {"t": "徇诸市。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "徇首", "t": "传首示众"}, {"w": "徇罚", "t": "示众处罚。"}]}, {"meaning": "对众宣示。", "cites": [{"t": "遂斩队长二人以徇。", "b": "《史记》"}], "words": [{"w": "徇众", "t": "示众。"}]}, {"meaning": "顺从、依从。", "cites": [{"t": "知县又徇了顾佥事人情。", "b": "《古今小说》"}], "words": [{"w": "徇世", "t": "随顺世俗"}, {"w": "徇庇", "t": "徇私包庇"}, {"w": "徇物", "t": "曲从世俗"}, {"w": "徇俗", "t": "顺随时俗。"}]}, {"meaning": "舍身。", "cites": [{"t": "陛下舍万乘之躯,而徇小义,古人所不取也。", "b": "《三国演义》"}], "words": [{"w": "徇名", "t": "舍身以求名"}, {"w": "徇利", "t": "不惜身以求利"}, {"w": "徇命", "t": "捐躯。"}]}, {"meaning": "炫耀;夸示。", "cites": [{"t": "徇蹲鸱之沃,则以为世济阳九。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "徇陈", "t": "遍示列队部伍"}, {"w": "徇铎", "t": "振铎以警众。"}]}, {"meaning": "谋求。", "cites": [{"t": "今不恤士卒而徇其私,非社稷之臣。", "b": "《史记》"}], "words": [{"w": "徇情枉法", "t": "为私情而违法"}, {"w": "徇私偏向", "t": "曲从私情,偏袒一方。"}]}]}]','jingmo-wenyan');
