INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4272wx','俞','1','yú','人','9','','[{"pinyin": "yú", "defs": [{"meaning": "(会意。从亼(jí),从舟,从刂,刂水也。”本义与造船有关,不详)古代挖空树木做船。", "cites": [{"t": "俞,空中木为舟也。", "b": "《说文》。段玉裁注:空中木者,舟之始"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4273wx','郗','1','xī','阝','9','','[{"pinyin": "xī", "defs": [{"meaning": "春秋周邑名 。故地在今河南省沁阳县。", "cites": [{"t": "郗,己姓。《说文》云:“周邑。”野王西北。", "b": "宋·罗泌《路史》"}]}, {"meaning": "姓。晋有郗超。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4274wx','俎','1','zǔ','人','9','','[{"pinyin": "zǔ", "defs": [{"meaning": "(指事兼形声。小篆字形。《说文》“从半肉在且上。”且,祭祀所用的礼器。本义:供祭祀或宴会时用的四脚方形青铜盘或木漆盘,常陈设牛羊肉)。"}, {"meaning": "同本义。", "cites": [{"t": "为俎孔硕。", "b": "《诗·小雅·楚茨》"}, {"t": "鸟兽之肉,不登于俎。", "b": "《左传·隐公五年》"}, {"t": "祭操俎。", "b": "《山海经·海外西经》"}, {"t": "俎豆之事。", "b": "《论语·卫灵公》"}, {"t": "庖人虽不治疱,尸祝不越樽俎而代之矣。", "b": "《庄子·逍遥游》"}], "words": [{"w": "俎几", "t": "俎形如几,故称。古代祭祀、燕飨时所用的礼器"}, {"w": "俎拒", "t": "俎足中央的横木"}, {"w": "俎味", "t": "祭祀用食品。"}]}, {"meaning": "古代割肉用的砧板。多木制,也有青铜铸的,大方形,两端有足。", "cites": [{"t": "如今人方为刀俎,我为鱼肉。(俎,切肉的砧板。)", "b": "《史记·项羽本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4275wx','郤','1','xì','阝','9','','[{"pinyin": "xì", "defs": [{"meaning": "(形声。从邑,谷(què)声。本义:晋国大夫叔虎的封地。在今山西沁水下游一带)。"}, {"meaning": "同本义。", "cites": [{"t": "郤,晋大夫叔虎邑也。", "b": "《说文》"}, {"t": "郤乡在河内。", "b": "《声类》"}], "words": [{"w": "郤诜丹桂", "t": "亦作“郤桂”、“郤诜枝”。晋郤诜举贤良对策为天下第一,自视为“桂林之一枝,昆山之片王。后喻科举及第。"}]}, {"meaning": "假借为“隙”。空隙;裂缝。", "cites": [{"t": "若白驹之过郤。", "b": "《庄子》"}, {"t": "相见于郤地曰会。", "b": "《礼记·曲礼》"}], "words": [{"w": "郤穴", "t": "孔穴"}, {"w": "郤地", "t": "两国交界之地。即国境线。"}]}, {"meaning": "隔阂。", "cites": [{"t": "今者有小人之言,令将军与臣有郤。", "b": "《史记·项羽本纪》"}, {"t": "与红阳侯有郤。", "b": "《汉书·孙宝传》。师古曰:“郤,与隙同。”"}]}, {"meaning": "小恙,不舒适。", "cites": [{"t": "玉体有所郤。", "b": "《战国策·赵策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4276wx','爰','1','yuán','爫','9','','[{"pinyin": "yuán", "defs": [{"meaning": "(会意。甲骨文字形。象两手相援引,中间一画表示瑗玉。本义:引,援引)。"}, {"meaning": "同本义。也作“援”。", "cites": [{"t": "绵诸乞爰。", "b": "《史记》"}]}, {"meaning": "曰;称为。", "cites": [{"t": "土爰称穑。", "b": "《书·洪范》"}]}, {"meaning": "改易;更换。", "cites": [{"t": "既爰宅于兹,重我民,无尽刘。", "b": "《书·盘庚上》"}], "words": [{"w": "爰颁", "t": "另行颁布"}, {"w": "爰田", "t": "变更旧日田土所有制,以公田赏赐众人。也称“辕田”"}, {"w": "爰居", "t": "迁居。"}]}, {"meaning": "于;从。", "cites": [{"t": "爰兹发迹,断蛇奋旅。", "b": "《汉书》"}]}, {"meaning": "于是。", "cites": [{"t": "乐土乐土,爰得我所。", "b": "《诗·魏风·硕鼠》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4277wx','郛','1','fú','阝','9','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从邑,孚(fú)声。从“邑”表示与城郭有关。本义:外城,古代指城圈外围的大城) 同本义。", "cites": [{"t": "郛,郭也。字亦作垺。", "b": "《说文》"}, {"t": "城卫楚丘之郛。", "b": "《左传·僖公十二年》"}, {"t": "城成郛。", "b": "《左传·襄公十五年》"}, {"t": "伐宋,入其郛。", "b": "《左传·隐公五年》"}], "words": [{"w": "郛郭", "t": "外城。比喻保障。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4278wx','瓴','1','líng','瓦','9','','[{"pinyin": "líng", "defs": [{"meaning": "(形声。从瓦,令声。从“瓦”,表示与陶器有关。本义:一种盛水的瓶子)。"}, {"meaning": "同本义。", "cites": [{"t": "今夫救火者,汲水而趋之,或以瓮瓴,或以盆盂。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4279wx','胨','1','dòng','月','9','','[{"pinyin": "dòng", "defs": [{"meaning": "蛋白胨的简称 。由蛋白部分水解生成的各种衍生物之一。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4280wx','胪','1','lú','月','9','','[{"pinyin": "lú", "defs": [{"meaning": "(形声。从肉,盧声。本义:皮)。"}, {"meaning": "同本义。", "cites": [{"t": "胪,皮也。", "b": "《说文》"}, {"t": "胪革充盈。", "b": "《礼记·礼运》。疏:“革外之薄皮。”"}]}, {"meaning": "额头。", "cites": [{"t": "七液洞流冲胪问。", "b": "《黄庭内景经》。务成子注:“胪间两眉间,谓额也。”"}]}, {"meaning": "陈述。", "cites": [{"t": "胪,叙也。", "b": "《尔雅》"}, {"t": "胪于郊祀。", "b": "《史记·六国年表》。索隐:“陈也。”"}], "words": [{"w": "胪叙", "t": "依次陈述"}, {"w": "胪陈", "t": "一一陈述"}, {"w": "胪情", "t": "陈情。"}]}, {"meaning": "报告。", "cites": [{"t": "风听胪言于市。", "b": "《国语·晋语》。注:“传也。”"}, {"t": "大行设九宾胪句。", "b": "《汉书·叔孙通传》"}], "words": [{"w": "胪传", "t": "对下传告"}, {"w": "胪句", "t": "犹胪传"}, {"w": "胪唱", "t": "宋以后科举考试,进士殿试毕,按曰第唱名传呼召见。"}]}, {"meaning": "祭。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4281wx','胛','1','jiǎ','月','9','','[{"pinyin": "jiǎ", "defs": [{"meaning": "肩胛", "words": [{"w": "胛子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4282wx','胂','1','shèn','月','9','','[{"pinyin": "shèn", "defs": [{"meaning": "一类由砷化三氢衍生出来的强毒性有机化合物的任何一种,类似于胺和膦。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4283wx','胙','1','zuò','月','9','','[{"pinyin": "zuò", "defs": [{"meaning": "(形声。从肉,乍声。本义:祭祀用的肉)。"}, {"meaning": "同本义。", "cites": [{"t": "胙,祭福肉也。", "b": "《说文》"}, {"t": "夏曰福胙。", "b": "《尔雅》"}, {"t": "王使宰孔赐齐侯胙。", "b": "《左传·僖公九年》"}, {"t": "彻王之胙俎。", "b": "《周礼·膳夫》。注:“主人饮食之俎皆为胙俎。”"}, {"t": "祝凫已疵献胙。", "b": "《管子·小问》"}, {"t": "太子祭于曲沃,归胙于公。", "b": "《左传·僖公四年》"}, {"t": "将军胙土分茅。(古代帝王分封诸侯,用五色土筑坛,一方一色,分封某方的诸侯,就用白茅包取某方的土,连同祭肉授给他,这就叫做“胙土分茅”。)", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "胙肉", "t": "祭祀时供神的肉"}, {"w": "胙侑", "t": "赐以祭肉,赠以束帛,表示亲近"}, {"w": "胙余", "t": "古称祭祀完毕后所余的酒肉"}, {"w": "胙席", "t": "祭祀的酒席。"}]}, {"meaning": "台阶。", "cites": [{"t": "登自胙阶。", "b": "《荀子·哀公》。注:“胙与阼同。”"}, {"t": "践胙之初。", "b": "汉《费亭侯曹腾碑阴》"}], "words": [{"w": "胙阶", "t": "大堂前东边的台阶。古代天子、诸侯、大夫、士,宾主相见,以东阶为主人迎宾登堂之地。"}]}, {"meaning": "赐与;分封。", "cites": [{"t": "考绩有成,符策乃胙。", "b": "《隶续》"}], "words": [{"w": "胙侑", "t": "赐以祭肉,赠以束帛,表示亲近。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4284wx','胍','1','guā','月','9','','[{"pinyin": "guā", "defs": [{"meaning": "主要在甜菜汁、野豌豆苗或胚鸡中发现的一种极容易潮解的晶体碱NH=C(NH2)2,它由鸟嘌呤氧化生成,但工业上常常是用二氰二胺与硝酸铵反应制得,其盐用于有机合成及医药中,其有机衍生物用作橡胶硫化促进剂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4285wx','胗','1','zhēn','月','9','','[{"pinyin": "zhēn", "defs": [{"meaning": "嘴唇溃疡。", "cites": [{"t": "胗,唇疡也。籀文从疒。", "b": "《说文》"}, {"t": "胗,肿也。", "b": "《三苍》"}, {"t": "胗,创也。", "b": "《广雅》"}, {"t": "中唇为胗。", "b": "宋玉《风赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4286wx','胝','1','zhī','月','9','','[{"pinyin": "zhī", "defs": [{"meaning": "手脚掌上的厚皮,俗称茧子。", "cites": [{"t": "胝,腄也。", "b": "《说文》"}, {"t": "胝,胼胝。", "b": "《玉篇》"}, {"t": "胝,皮厚也。", "b": "《广韵》"}, {"t": "耕耘树艺,手足胼胝。", "b": "《荀子·子道》"}, {"t": "百胝存楚,居今观古,曾何足云。", "b": "《百辟劝进笺》"}], "words": [{"w": "胝趼", "t": "茧子"}, {"w": "胝皱", "t": "皮肉因生茧而皱缩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4287wx','朐','1','qú','月','9','','[{"pinyin": "qú", "defs": [{"meaning": "屈曲的干肉。", "cites": [{"t": "以脯朐置者,左朐右末。", "b": "《礼记》"}]}, {"meaning": "古县名 。秦置。在今江苏省连云港市西南锦屏山侧。梁于其地置招远县。东魏又改招远县为朐县。"}, {"meaning": "弯曲。", "cites": [{"t": "朐,引申为凡屈曲之。", "b": "段玉裁《说文解字注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4288wx','胫','1','jìng','月','9','','[{"pinyin": "jìng", "defs": [{"meaning": "(形声。从肉,巠声。本义:小腿)。"}, {"meaning": "同本义。", "cites": [{"t": "胫,胻也。", "b": "《说文》"}, {"t": "以杖叩其胫。", "b": "《论语》。皇疏:“脚胫也。膝上曰股,膝下曰胫。”"}, {"t": "有赤胫之民。", "b": "《山海经·海内经》"}, {"t": "闻苦脚胫寒泄。", "b": "《汉书·赵充国传》"}, {"t": "析才士之胫。", "b": "《淮南子·俶真》"}], "words": [{"w": "胫无毛", "t": "形容奔走辛劳之甚"}, {"w": "胫大于股", "t": "言本小末大。旧时喻臣下的力量大于君上"}, {"w": "胫衣", "t": "套裤。"}]}, {"meaning": "泛指人或禽兽的腿。", "cites": [{"t": "方首,长胫,意似良。(胫,人的小腿,也指禽兽昆虫的腿,这里指蟋蟀的腿。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "胫毛", "t": "谓物之细微者。犹言一丝一毫,多指个人得失。"}]}, {"meaning": "小腿骨,脊椎动物膝盖以下的前方骨头。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4289wx','鸨','1','bǎo','鸟','9','','[{"pinyin": "bǎo", "defs": [{"meaning": "鸟名。头小颈长。鸨科中型和大型狩猎鸟类,与鹤形目的鹤和秧鸡有亲缘关系,比雁略大,背上有黄褐色和黑色斑纹,不善于飞,而善于走", "words": [{"w": "鸨行", "t": "鸨鸟的羽茎"}, {"w": "鸨奥", "t": "鸨鸟的脾脏与小肠"}, {"w": "鸨合", "t": "鸨与他鸟相合。比喻男女淫乱"}]}, {"meaning": "旧时的老妓女", "words": [{"w": "鸨妓", "t": "老妓女"}, {"w": "鸨儿", "t": "指鸨母,开妓院的女人。即妓女的养母"}, {"w": "鸨公", "t": "对鸨母丈夫的戏称"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4290wx','匍','1','pú','勹','9','','[{"pinyin": "pú", "defs": [{"meaning": "a.爬，手足并行，如\\"匍匍前进\\"；b.竭力，如\\"凡民有丧，匍匍救之\\"；c.趴，如\\"有些植物的茎匍匍在地面上\\"。", "cites": [{"t": "幸主者出，南面召见，则惊走匍匐阶下。--明·宗臣《报刘一丈书》", "b": ""}]}]}]','jingmo-wenyan');
