INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4294wx','狩','1','shòu','犭','9','','[{"pinyin": "shòu", "defs": [{"meaning": "(形声。从犬,守声。“犬”是狩猎的助手,故从犬。本义:冬季打猎)。"}, {"meaning": "同本义。", "cites": [{"t": "狩,犬田也。", "b": "《说文》"}, {"t": "明夷于南狩。", "b": "《易》。按,田必有犬,故从犬。”"}, {"t": "岁终田猎曰狩。", "b": "《易·荀》注"}, {"t": "冬猎为狩。", "b": "《尔雅》"}, {"t": "狩者何?田狩也。", "b": "《公羊传·桓公四年》"}, {"t": "冬大阅以狩。", "b": "《汉书·刑法志》"}, {"t": "狩于中山。", "b": "《列子·黄帝》。注:“火田为狩”"}, {"t": "春蒐,夏苗,秋狝,冬狩。", "b": "《左传·隐公五年》"}], "words": [{"w": "狩田", "t": "冬季打猎"}, {"w": "狩地", "t": "古代天子、诸侯冬猎之地。"}]}, {"meaning": "打猎。", "cites": [{"t": "不狩不猎,胡瞻尔庭有县貆兮?", "b": "《诗·魏风·伐檀》"}], "words": [{"w": "冬狩;狩人", "t": "猎人"}, {"w": "狩取", "t": "捕捉。"}]}, {"meaning": "古代帝王巡察诸侯或地方官治理的地方。", "cites": [{"t": "天王狩于河阳。", "b": "《左传·僖公二十八年》"}, {"t": "犹豫不敢断,因狩执君王。", "b": "曹操《薤露》"}], "words": [{"w": "巡狩", "t": "帝王出巡。"}]}]}]','jingmo-wenyan');
