INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4299wx','饷','1','xiǎng','饣','9','','[{"pinyin": "xiǎng", "defs": [{"meaning": "(形声。左形右声。本义:给在田间里劳动的人送饭)。"}, {"meaning": "同本义。", "cites": [{"t": "餉,饟也。", "b": "《说文》"}, {"t": "餉,餉馈。", "b": "《广韵》"}, {"t": "饟,周人谓餉曰饟。", "b": "《说文》"}, {"t": "饟,馈也。", "b": "《尔雅》"}, {"t": "种饟粮食。", "b": "《汉书·食货志下》"}, {"t": "輓车奉饟者。", "b": "《汉书·严助传》"}, {"t": "为雇耕佣,凭种餉。", "b": "《后汉书·章帝纪》。注:“餉,粮也,古餉字。”"}, {"t": "数声牛上笛,何处饷田归?", "b": "前蜀·韦庄《纪村事》"}], "words": [{"w": "饷田", "t": "送饭到田头"}, {"w": "饷人", "t": "送饭食的人"}, {"w": "饷馌", "t": "往田头送饭。"}]}, {"meaning": "招待,供给或提供。", "cites": [{"t": "有童子以黍肉饷。", "b": "《孟子·滕文公下》"}, {"t": "幼弟不饷。", "b": "《韩非子·五蠹》"}], "words": [{"w": "饷客", "t": "以饮食招待客人"}, {"w": "饷宾", "t": "以食物招待宾客。"}]}, {"meaning": "吃饭,进餐。", "cites": [{"t": "是故求其诚者,非归饷也不可。", "b": "《韩非子·外储说左上》"}]}, {"meaning": "赠送。", "cites": [{"t": "以诗赋饷孙权。", "b": "胡冲《吴历》"}], "words": [{"w": "饷亿", "t": "赠送,补给"}, {"w": "饷献", "t": "馈赠奉献。"}]}, {"meaning": "军粮及军队的俸給。", "cites": [{"t": "老弱转饷。", "b": "《汉叔· 严助传》"}, {"t": "丁壮苦军旅,老弱罢转饷。", "b": "《史記·高祖本紀》"}, {"t": "饷无所出。", "b": "清·邵長蘅《青门剩稿》"}], "words": [{"w": "饷馈", "t": "军队的粮食"}, {"w": "饷米", "t": "军队食用的米"}, {"w": "饷事", "t": "掌管军粮之事。"}]}, {"meaning": "食物。", "cites": [{"t": "吾见子有饥色,为子取饷,子何嫌哉?", "b": "《吴越春秋》"}]}, {"meaning": "一会儿,不多久的时間。後作“晌”。", "cites": [{"t": "虽有一饷乐,有如聚飞蚊。", "b": "唐·韩愈《醉贈张秘书》"}]}]}]','jingmo-wenyan');
