INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4302wx','胤','1','yìn','月','9','','[{"pinyin": "yìn", "defs": [{"meaning": "(会意。从肉,从八,从幺。肉表示血统关系,幺表示重迭,八表示延长。合起来表示后代。本义:子孙相承) 同本义。", "cites": [{"t": "胤,子孙相承续也。", "b": "《说文》"}, {"t": "予乃胤保大相东土。", "b": "《书·洛浩》"}, {"t": "胤,继也。", "b": "《尔雅》"}, {"t": "胤殷周之失业。", "b": "《剧秦美新》"}]}, {"meaning": "子孙,后裔,子嗣,后嗣。", "cites": [{"t": "胤子朱启明。", "b": "《书·尧典》"}, {"t": "夫许,太岳之胤也。", "b": "《左传·隐公十一年》"}, {"t": "周公之胤。", "b": "《左传·僖公二十四年》"}, {"t": "永锡祚胤。", "b": "《诗·大雅·既醉》"}], "words": [{"w": "胤子", "t": "子嗣;嗣子"}, {"w": "胤息", "t": "子息;子嗣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4303wx','孪','1','luán','子','9','','[{"pinyin": "luán", "defs": [{"meaning": "双生,俗称双胞胎。", "cites": [{"t": "孪,一乳两子也。", "b": "《说文》"}, {"t": "凡人兽乳而双生,谓之孪生。", "b": "《方言三》"}, {"t": "兄弟不孪。", "b": "《太玄·元掜》"}, {"t": "夫孪子之相似者,唯其母知之而已。", "b": "《战国策》"}], "words": [{"w": "孪子", "t": "双生子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4304wx','娈','1','luán','女','9','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从女,羉(luán)声。本义:爱好。假借义:美好) 同假借义。", "cites": [{"t": "娈,好也。", "b": "《广雅》"}, {"t": "娈彼诸姬。", "b": "《诗·邶风·泉水》"}, {"t": "静女其娈,贻我彤管。", "b": "《诗·邶风·静女》。毛传:“既有静德,又有美色。”"}], "words": [{"w": "娈婉", "t": "美好的样子"}, {"w": "娈宠", "t": "男子以色事人的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4305wx','弈','1','yì','廾','9','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从攻(gǒng),亦声。本义:下棋) 同本义。", "cites": [{"t": "弈,围棋也。", "b": "《说文》"}, {"t": "棋局谓之弈。", "b": "《小尔雅》"}, {"t": "视君不如弈棋。", "b": "《左传·襄公二十五年》"}, {"t": "今夫弈之为数。", "b": "《孟子》"}, {"t": "使弈秋诲二人弈。", "b": "《孟子·告子上》"}], "words": [{"w": "弈思", "t": "下棋的思路。"}]}, {"meaning": "古代指围棋。", "cites": [{"t": "不有博弈者乎?", "b": "《论语·阳货》"}, {"t": "射者中,弈者胜。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "弈局", "t": "棋局,棋盘"}, {"w": "弈具", "t": "指棋盘,棋子"}, {"w": "弈枰", "t": "棋盘"}, {"w": "弈楸", "t": "棋盘"}, {"w": "弈谱", "t": "棋谱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4306wx','奕','1','yì','大','9','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从大,亦声。本义:大)。"}, {"meaning": "同本义。", "cites": [{"t": "奕,大也。", "b": "《说文》"}, {"t": "往小来奕。", "b": "《太玄·格》"}, {"t": "四壮奕奕。", "b": "《诗·小雅·车攻》"}, {"t": "奕奕梁山。", "b": "《诗·大雅·韩奕》"}, {"t": "伯夷相唐,尚父宾周。受氏胙国,重光奕休。", "b": "宋·王安石《祭吕侍读文》"}]}, {"meaning": "美的。", "cites": [{"t": "自关而西,凡美容谓之奕。", "b": "《方言》"}, {"t": "万舞有奕。", "b": "《诗·商颂·那》"}]}, {"meaning": "累,重。", "cites": [{"t": "是仆与君奕世为通好也。", "b": "《世说新语·言语》"}], "words": [{"w": "奕世簪缨", "t": "子孙世代都为显宦贵族"}, {"w": "奕世", "t": "累世,代代"}, {"w": "奕代", "t": "奕世,累世"}, {"w": "奕叶", "t": "累世,代代。"}]}, {"meaning": "光明。", "cites": [{"t": "故其华表则镐镐铄铄,赫奕章灼,若日明之丽天也。", "b": "三国魏·何晏《景福殿赋》"}], "words": [{"w": "奕奕", "t": "光明的样子;亮光闪动的样子"}, {"w": "奕赫", "t": "光显的样子。"}]}, {"meaning": "世,时代。", "cites": [{"t": "使如来福业,不坠于今奕。", "b": "北周·王妙晖《造释迦像记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4307wx','庥','1','xiū','广','9','','[{"pinyin": "xiū", "defs": [{"meaning": "覆盖。", "cites": [{"t": "庥,荫也。", "b": "《释言》"}], "words": [{"w": "庥映", "t": "遮盖。"}]}, {"meaning": "庇护。", "cites": [{"t": "武当建天玄宝殿,以报神庥。", "b": "《英烈传》"}], "words": [{"w": "庥庇", "t": "荫庇,庇护"}, {"w": "庥荫", "t": "保护;福祐。"}]}]}]','jingmo-wenyan');
