INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4309wx','疣','1','yóu','疒','9','','[{"pinyin": "yóu", "defs": [{"meaning": "皮肤病名。", "cites": [{"t": "肬,赘也。从肉,尤声。", "b": "《说文》"}, {"t": "肬,肿也。", "b": "《广雅》"}, {"t": "今学曾未如肬赘。", "b": "《荀子·宥坐》。注:“结肉。”"}]}, {"meaning": "用同“尤”。怨恨,归咎;过失。", "cites": [{"t": "三皇之时,食肉衣皮,巢居穴处,以崇质朴,岂复须章黼之冠,曲裘之饰哉。然其人称有德,而孰疣之。", "b": "汉·牟融《理惑论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4310wx','疥','1','jiè','疒','9','','[{"pinyin": "jiè", "defs": [{"meaning": "疥疮,一种皮肤病,非常刺痒,是疥虫寄生而引起的。又名“疥癣”。", "cites": [{"t": "疥,搔也。", "b": "《说文》"}], "words": [{"w": "疥癣之疾", "t": "本指疥与癣两种皮肤病,喻作为害不很大的祸患"}, {"w": "疥搔", "t": "疥疮"}, {"w": "疥癞", "t": "疥疮和头癣。"}]}, {"meaning": "隔日疟。", "cites": [{"t": "齐侯疥,遂痁。", "b": "《左传》。孔颖达疏:“疥当为痎,痎是小疟,痁是大疟。”"}]}]}]','jingmo-wenyan');
