INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4312wx','庠','1','xiáng','广','9','','[{"pinyin": "xiáng", "defs": [{"meaning": "(形声。从广(yǎn),羊声。“广”与房屋有关。本义:古代地方学校)。"}, {"meaning": "殷、周时的学校。", "cites": [{"t": "痒,礼官养老,夏曰校,殷曰庠,周曰序。", "b": "《说文》"}, {"t": "殷曰序,周曰庠。", "b": "《孟子·滕文公上》"}, {"t": "庠序,官也。", "b": "《尔雅·释官》"}, {"t": "有虞氏养国老于上庠,养庶老于下庠。", "b": "《礼记》。郑玄注:“上庠,右学,大学也,在西郊。下庠,左学,小学也,在国中王宫之东。”"}]}, {"meaning": "古代的乡学。", "cites": [{"t": "主人拜迎宾于庠门之外。", "b": "《礼记·乡饮酒义》。注:“乡学也。”"}, {"t": "庠之制有堂有室也。", "b": "《仪礼·乡射礼》注"}, {"t": "党有庠。", "b": "《仪礼·学记》。注:“五百家为党,庾氏谓夏殷礼非周法。又,王制、内则、周人养庶老于虞庠。虞庠在国之西郊。此国学之小学,即辟雍也。”"}, {"t": "俾入邑庠。", "b": "《聊斋志异·促织》"}, {"t": "还是在庠?还是在监?", "b": "《玉娇梨》"}], "words": [{"w": "庠士", "t": "在学生员"}, {"w": "庠老", "t": "古代对地方学官的敬称。"}]}, {"meaning": "教养;教导。", "cites": [{"t": "庠者养也,校者教也,序者射也。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4313wx','竑','1','hóng','立','10','','[{"pinyin": "hóng", "defs": [{"meaning": "量度。", "cites": [{"t": "竑,量度也。", "b": "《玉篇》"}, {"t": "故竑其幅广,以为之弱。", "b": "《周礼·考工记·轮人》"}]}, {"meaning": "强壮的。", "cites": [{"t": "竑,《韵笺》曰:盖强壮之谓。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4314wx','彦','1','yàn','彡','9','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声.小篆字形。从彣(wén),厂(hǎn)声。彣,有文采。本义:有才学的人)贤士。才德出众的人;贤才;俊才。", "cites": [{"t": "产,美士有彣也。", "b": "《说文》"}, {"t": "美士为彦。", "b": "《尔雅》"}, {"t": "人之彦圣。", "b": "《礼记·大学》"}, {"t": "彼其之子,邦之彦兮。", "b": "《诗·郑风·羔裘》"}], "words": [{"w": "彦哲", "t": "贤智之士"}, {"w": "彦圣", "t": "善美明达,亦指善美明达之士"}, {"w": "俊彦", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4315wx','飒','1','sà','风','9','','[{"pinyin": "sà", "defs": [{"meaning": "(形声。从风,立声。本义:风声) 同本义。", "cites": [{"t": "飒,翔风也。", "b": "《说文》"}, {"t": "飒飒,风也。", "b": "《广雅》"}, {"t": "风飒飒兮木萧萧。", "b": "《楚辞·九歌》"}, {"t": "有风飒然而至。", "b": "宋玉《风赋》"}], "words": [{"w": "飒飖", "t": "大风"}, {"w": "飒飒;飒剌剌", "t": "形容风的声音。"}]}, {"meaning": "狂风拉物。", "cites": [{"t": "梦初回,燕尾翻风,乱飒起湘帘翠。", "b": "明·汤显祖《牡丹亭》"}]}, {"meaning": "凋零;衰落。", "cites": [{"t": "岁聿忽其云暮, 庭草飒以萎黄。", "b": "梁·陆倕《思田赋》"}]}, {"meaning": "飞舞。", "cites": [{"t": "飒沓矜。", "b": "鲍昭《飞鹤赋》。又如:飒沓(群飞的样子;众盛的样子);飒纚(长袖飞舞的样子)"}]}, {"meaning": "风微过。", "cites": [{"t": "徐行时若风飒芙蓉。", "b": "《敦煌变文集》"}]}, {"meaning": "衰老。", "cites": [{"t": "知己犹未极,鬓毛飒已苍。", "b": "岑参《岑嘉州诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4316wx','闼','1','tà','门','9','','[{"pinyin": "tà", "defs": [{"meaning": "(形声。从门,达声。本义:小门)。"}, {"meaning": "同本义。", "cites": [{"t": "哙乃排闼直入。", "b": "《汉书·樊哙传》"}], "words": [{"w": "窗户闼", "t": "窗户上的小门"}, {"w": "闼门", "t": "小门。"}]}, {"meaning": "门内。", "cites": [{"t": "在我闼兮,履我发兮。", "b": "《诗·齐风·东方之日》"}]}, {"meaning": "门楼上的小屋。", "cites": [{"t": "上飞闼而仰眺。", "b": "张衡《西京赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4317wx','闾','1','lǘ','门','9','','[{"pinyin": "lǘ", "defs": [{"meaning": "(形声。从门,吕声。本义:里巷的大门)。"}, {"meaning": "同本义。", "cites": [{"t": "闾,里门也。", "b": "《说文》"}, {"t": "二大夫出,相与踦闾而语。", "b": "《公羊传》"}, {"t": "便旋闾阎。", "b": "张衡《西京赋》"}, {"t": "门闾无关。", "b": "《吕氏春秋·仲夏》"}, {"t": "发闾左戍渔阳九百人。", "b": "《汉书·陈胜传》"}], "words": [{"w": "倚闾而望;闾阋", "t": "指内部斗争"}, {"w": "闾墓", "t": "里巷和墓道的大门"}, {"w": "闾闬", "t": "里巷的门。"}]}, {"meaning": "里巷。", "cites": [{"t": "闾,里也。", "b": "《广雅·释宫》"}, {"t": "魏文侯过段干木之闾而轼之。", "b": "《吕氏春秋·期贤》"}, {"t": "违郢都之旧闾兮。", "b": "《楚辞·刘向·九叹·思古》"}], "words": [{"w": "闾吏", "t": "里巷小吏"}, {"w": "闾陌", "t": "里巷"}, {"w": "闾社", "t": "闾里乡社"}, {"w": "闾肆", "t": "街市。"}]}, {"meaning": "中国古代以二十五家为闾。", "cites": [{"t": "令五家为比,使之相保,五比为闾,使之相爱。", "b": "《周礼·大司徒》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4318wx','闿','1','kǎi','门','9','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从门,豈声。本义:开门;开)。"}, {"meaning": "同本义。", "cites": [{"t": "闿,开也,", "b": "《说文》"}, {"t": "开户,楚谓之闿。", "b": "《方言六》"}, {"t": "今欲与汉闿大关。", "b": "《汉书·匈奴传》"}], "words": [{"w": "闿关", "t": "开关"}, {"w": "闿拓", "t": "开展"}, {"w": "闿门", "t": "敞开门"}, {"w": "闿置", "t": "开设"}, {"w": "闿彻", "t": "开通"}, {"w": "闿阖", "t": "开合。"}]}, {"meaning": "开阔;明朗。", "cites": [{"t": "闿,明也。", "b": "《广雅》"}], "words": [{"w": "闿明", "t": "开阔明朗"}, {"w": "闿爽", "t": "开朗"}, {"w": "闿敏", "t": "开朗聪敏"}, {"w": "闿疏", "t": "开朗通达。"}]}, {"meaning": "和乐。", "cites": [{"t": "昆虫闿怿,回首面内。", "b": "《汉书·司马相如传》。又如:闿悦(欢乐);闿怿(和乐的样子);闿悌(和易近人)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4319wx','阂','1','hé','门','9','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从门,亥声。(ài)本义:从门外关门)。"}, {"meaning": "阻隔,不畅通;妨碍。", "cites": [{"t": "不令有所拘阂而已。", "b": "《后汉书·虞诩传》"}, {"t": "学而不思,则疑阂实繁。", "b": "《抱朴子·博喻》"}], "words": [{"w": "阂滞", "t": "阻碍"}, {"w": "阂目", "t": "视线被山所遮蔽"}, {"w": "阂绝", "t": "隔绝,不相通"}, {"w": "阂窒", "t": "阻塞"}, {"w": "阂山", "t": "为山所阻隔"}, {"w": "阂塞", "t": "阻隔不通。"}]}, {"meaning": "止。", "cites": [{"t": "厥形虽大,斯脚则企,跳步雀踊,踵不阂也。", "b": "晋·郭璞《山海经图赞》"}]}, {"meaning": "限制。", "cites": [{"t": "阂,限也。", "b": "《小尔雅·广言》"}, {"t": "恢万里使无阂,通亿载而为津。", "b": "晋·陆机《文赋》"}, {"t": "世岂乏材,阂于资格故也。", "b": "《金史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4320wx','羑','1','yǒu','八','9','','[{"pinyin": "yǒu", "defs": [{"meaning": "向好的方向诱导。", "cites": [{"t": "诞受羑若。", "b": "《书·康王之浩》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4321wx','迸','1','bèng','辶','9','','[{"pinyin": "bèng", "defs": [{"meaning": "(从辵,并声。“辵”(chuò)意思是在路上行走。本义:奔散,走散)。"}, {"meaning": "同本义。", "cites": [{"t": "督将迸走,死伤过半。", "b": "《三国志·满宠传》"}], "words": [{"w": "迸豆之疾", "t": "像豆子倒入锅内时乱迸那样快"}, {"w": "迸窜", "t": "逃窜"}, {"w": "迸逸", "t": "逃窜。"}]}, {"meaning": "涌出;喷射。", "cites": [{"t": "银瓶乍破水浆迸。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "迸泉", "t": "涌出的泉水"}, {"w": "迸撺", "t": "喷涌飞溅"}, {"w": "迸放", "t": "喷射发出。"}]}, {"meaning": "爆开,断裂。", "cites": [{"t": "打得眼棱缝裂,乌珠迸出。", "b": "《水浒传》"}], "words": [{"w": "迸穴", "t": "迸裂而成的洞穴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4322wx','籼','1','xiān','米','9','','[{"pinyin": "xiān", "defs": [{"meaning": "籼稻 一种一年生的禾草,水稻的一种,米粒细而长,在温暖气候下广泛栽培,种子用作人类食物,谷壳和其他副产品可饲养家畜,稻杆用来造纸。", "cites": [{"t": "籼似粳而粒小,始自闽入,得种于占城国。", "b": "《本草纲目》"}], "words": [{"w": "灿稻", "t": "水稻品种之一。稻株比粳稻稍高,分蘖力强,但杆软易倒伏。米粒细长,无粘性。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4323wx','酋','1','qiú','酉','9','','[{"pinyin": "qiú", "defs": [{"meaning": "(会意。小篆字形。《说文》:“从酉,水半见于上。”金文中“酉”象酒坛形。因为是陈酒,酒与酒糟下沉,上面“八”象水形。本义:陈酒,久酿之酒)。"}, {"meaning": "同本义。", "cites": [{"t": "酋,绎酒也。从酉,水半见于上。礼有大酋,掌酒官也。", "b": "《说文》。"}], "words": [{"w": "酋腊", "t": "极熟的酒"}]}, {"meaning": "古代称从事与酒有关工作的人。"}, {"meaning": "大酋。", "cites": [{"t": "乃命大酋,秫稻必齐,曲蘖必时。", "b": "《吕氏春秋·仲冬》"}]}, {"meaning": "掌酒的女奴。", "cites": [{"t": "妇人以为舂酋。", "b": "《墨子》"}]}, {"meaning": "部落的首领。也为魁帅的通称。", "cites": [{"t": "二贵酋名。", "b": "宋·文天祥《指南录后序》"}, {"t": "诋大酋当死。", "b": ""}, {"t": "与贵酋处二十日。", "b": ""}], "words": [{"w": "匪酋;贼酋;敌酋", "t": "敌人的头子"}, {"w": "酋渠", "t": "部落的首领"}, {"w": "酋领", "t": "部落的首领。"}]}, {"meaning": "假借为“猷”。功业。", "cites": [{"t": "似先公酋矣。", "b": "《诗·大雅·卷阿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4324wx','炳','1','bǐng','火','9','','[{"pinyin": "bǐng", "defs": [{"meaning": "(形声。从火,丙声。本义:光明,明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "炳,明也。", "b": "《说文》"}, {"t": "其文炳也。", "b": "《易·革》"}, {"t": "炳炳,明也。", "b": "《广雅》"}, {"t": "大汉之文章炳然与三代同风 。", "b": "班固《两都赋》"}], "words": [{"w": "炳著", "t": "光明显著"}, {"w": "炳焕", "t": "光明显耀"}, {"w": "炳映", "t": "光芒照耀"}, {"w": "炳然", "t": "光明、明白的样子"}, {"w": "炳耀", "t": "光耀明亮。"}]}, {"meaning": "点燃。", "cites": [{"t": "古人思炳烛夜游。", "b": "《与吴质书》"}, {"t": "炳烛之明,熟与昧行乎。", "b": "刘向《说苑》"}], "words": [{"w": "炳烛", "t": "点燃烛火以照明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4325wx','炻','1','shí','火','9','','[{"pinyin": "shí", "defs": [{"meaning": "介于陶器和瓷器之间的一种陶瓷制品。产品如砂锅、水缸和耐酸陶瓷等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4326wx','炽','1','chì','火','9','','[{"pinyin": "chì", "defs": [{"meaning": "(会意。从火,戠(zhí)声。本义:火旺)。"}, {"meaning": "同本义。引申为凶猛,激烈;气焰高涨。", "cites": [{"t": "炽,盛也。", "b": "《说文》"}, {"t": "三月而炽之。", "b": "《考工记·钟氏》"}, {"t": "环顾国内,贼氛方炽。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "炽火", "t": "炽燎。烈火"}, {"w": "炽焰", "t": "烈焰"}, {"w": "炽火", "t": "燃点灯烛"}, {"w": "炽腾", "t": "火势猛烈,火苗上窜。"}]}, {"meaning": "兴盛,昌盛。", "cites": [{"t": "齐虽炽盛,不如如此。", "b": "《论衡·艺增》"}], "words": [{"w": "炽昌", "t": "昌盛"}, {"w": "炽富", "t": "昌盛富足"}, {"w": "炽茂", "t": "茂盛"}, {"w": "炽发", "t": "勃发。"}]}, {"meaning": "烹煮。", "cites": [{"t": "钟氏染羽,以朱湛丹秫,三月而炽之。", "b": "《周礼·考工记·钟氏》"}, {"t": "湛炽必洁。", "b": "《礼记·月令》"}, {"t": "畅草可以炽酿。", "b": "《论衡·异虚》"}], "words": [{"w": "炽爨", "t": "烧煮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4327wx','炯','1','jiǒng','火','9','','[{"pinyin": "jiǒng", "defs": [{"meaning": "(形声。从火,冋(jiǒng)声。本义:光明,光亮)。"}, {"meaning": "同本义。", "cites": [{"t": "炯、光也。", "b": "《说文》"}, {"t": "炯,明也。", "b": "《苍颉篇》"}, {"t": "皦日炯晃于绮疏。", "b": "孙绰《游天台山赋》"}, {"t": "又申之以炯戎。", "b": "班固《幽通赋》"}, {"t": "向炯烛而背白日。", "b": "葛洪《抱朴子》"}], "words": [{"w": "炯介", "t": "光明刚正"}, {"w": "炯心", "t": "光明的心地"}, {"w": "炯炯", "t": "光明,光亮"}, {"w": "炯晃", "t": "光耀明朗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4328wx','烀','1','hū','火','9','','[{"pinyin": "hū", "defs": [{"meaning": "用少量的水,盖紧锅盖,加热,半蒸半煮,把食物弄熟", "words": [{"w": "烀白薯", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4329wx','炷','1','zhù','火','9','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从火,主声。本作“主”。本义:灯蕊)。"}, {"meaning": "同本义。", "cites": [{"t": "尝夜宿民家,遇灯炷尽,主人将续之,无逸抽佩刀断带为炷。", "b": "《新唐书》"}]}, {"meaning": "烛;灯;灯笼。", "cites": [{"t": "其母梦神官持炷送一儿至,曰:“善视之,防七十二难也。”", "b": "《郭新楷传》"}]}, {"meaning": "点燃。", "cites": [{"t": "午梦初回理旧琴;竹炉重炷海南沉。", "b": "陆游《夏日杂题》"}], "words": [{"w": "炷香", "t": "烧香;燃香。口语指一枝香的略称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4330wx','烃','1','tīng','火','9','','[{"pinyin": "tīng", "defs": [{"meaning": "碳氢化合物,只含有碳和氢的一大类有机化合物之一,它包括烷烃、烯烃、炔烃的成员、脂环烃(如环状萜烯烃及甾族化合物)和芳香烃(如苯、萘、联苯),在许多情况中它们存在于石油、天然气、煤和沥青中。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4331wx','洱','1','ěr','氵','9','','[{"pinyin": "ěr", "defs": [{"meaning": "湖名。古称叶榆泽。在云南省大理市﹑洱源县间。因其形如耳得名。西汇点苍山麓诸水，冲积为肥沃的大理平原。北纳西洱河，流出大理市，汇合漾濞江，注入澜沧江。有\\"三岛\\"﹑\\"四洲\\"﹑\\"九曲\\"之胜，是著名风景区。"}, {"meaning": "1.古水名。源出今河南省内乡县熊耳山，东南流注于渦水。2.即洱海。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4332wx','洹','1','huán','氵','9','','[{"pinyin": "huán", "defs": [{"meaning": "古水名 。在河南省北境,今名安阳河。源出林县,东流经安阳市到内黄县入卫河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4333wx','洧','1','wěi','氵','9','','[{"pinyin": "wěi", "defs": [{"meaning": "古水名 。源出河南登封县阳城山,东南流至新郑县与溱水合,至西华县入颍水。", "cites": [{"t": "洧,水名。在郑。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4334wx','洌','1','liè','氵','9','','[{"pinyin": "liè", "defs": [{"meaning": "清澄。", "cites": [{"t": "洌,水清也。从水,列声。", "b": "《说文》"}, {"t": "泉香而酒洌。", "b": "《醉翁亭记》"}, {"t": "洌风过而增悲哀。", "b": "《文选·宋玉·高唐赋》"}, {"t": "水尤清洌。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "泉香而酒洌。", "b": "宋·欧阳修《醉翁亭记》"}], "words": [{"w": "洌风", "t": "寒风"}, {"w": "洌清", "t": "清沏的样子。"}]}, {"meaning": "寒冷。", "cites": [{"t": "玄泉洌清。", "b": "张衡《思玄赋》"}, {"t": "洌寒、泉食。", "b": "《易·井》"}], "words": [{"w": "洌风", "t": "寒风"}, {"w": "虎啸风洌;洌洌", "t": "寒冷的样子"}, {"w": "洌气", "t": "寒气"}, {"w": "洌清", "t": "寒凉的样子。"}]}, {"meaning": "假借为“捩”。拗折。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4335wx','浃','1','jiā','氵','9','','[{"pinyin": "jiā", "defs": [{"meaning": "(形声。从水,夹声。本义:湿透)。"}, {"meaning": "同本义。", "cites": [{"t": "汗出浃背。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "汗流浃背;浃髓沦肌,浃髓沧肤,浃沦肌髓", "t": "深入骨髓,浸透肌肤;喻感受深切。"}]}, {"meaning": "通达,理解。", "cites": [{"t": "其所以贯理焉,虽亿万已不足以浃万物之变,与愚者若一。", "b": "《荀子》"}]}, {"meaning": "整个儿的。", "cites": [{"t": "浃辰之间而楚克其三都。", "b": "《左传·成公九年》"}], "words": [{"w": "浃岁", "t": "一整年"}, {"w": "浃时", "t": "一季"}, {"w": "浃月", "t": "一个月"}, {"w": "浃辰", "t": "十二天"}, {"w": "浃旬", "t": "一旬,十天。"}]}, {"meaning": "融洽。", "cites": [{"t": "其岁九月,人吏浃和。", "b": "唐·韩愈《新修滕王阁记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4336wx','洇','1','yīn','氵','9','','[{"pinyin": "yīn", "defs": [{"meaning": "水名。", "cites": [{"t": "洇,水也。", "b": "《说文》"}]}, {"meaning": "亦指水流。", "cites": [{"t": "[汜人]因撰《风光词》曰:“…迷千里兮涵洇湄,晨陶陶兮暮熙熙”。", "b": "唐·沈亚之《湘中怨解》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4337wx','洄','1','huí','氵','9','','[{"pinyin": "huí", "defs": [{"meaning": "(会意。从水回,回亦声。本义:逆流而上)。"}, {"meaning": "同本义。", "cites": [{"t": "洄,溯洄也。", "b": "《说文》"}, {"t": "逆流而上曰泝洄。", "b": "《尔雅·释水》"}, {"t": "溯洄从之,道阻且长。", "b": "《诗·秦风·蒹葭》"}, {"t": "浔阳五溪水,沿洄直入巫山里。", "b": "李白《送别》"}], "words": [{"w": "洄沿", "t": "洄,逆流而上;沿,顺流而下"}, {"w": "洄游", "t": "同回游。"}]}, {"meaning": "追溯往昔。", "cites": [{"t": "游今洄古,可以鉴矣。", "b": "《契丹国志·契丹国初兴本末》"}, {"t": "学生虽溯洄思切,自念风尘俗吏,未由再睹仙颜,今何幸于此处相遇!", "b": "《红楼梦》"}]}, {"meaning": "回旋的水,作圆周运动的水流。", "cites": [{"t": "管弦声沸兴方来,池面波溶返照洄。", "b": "陆采《怀香记》"}]}, {"meaning": "湖名 。在湖北省襄阳县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4338wx','洙','1','zhū','氵','9','','[{"pinyin": "zhū", "defs": [{"meaning": "古水名。", "cites": [{"t": "洙水出泰山盖临乐山,北入泗。从水,朱声。", "b": "《说文》"}]}, {"meaning": "源出今山东省新泰县东北,折西南与泗水合流。后世上源在泰安县东南改道西流合入汶水,今为小汶河上游,已与泗水隔绝。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4339wx','涎','1','xián','氵','9','','[{"pinyin": "xián", "defs": [{"meaning": "(形声。从水,延声。本义:唾沫,口水)。"}, {"meaning": "同本义。", "cites": [{"t": "涎,小儿唾也。", "b": "《三苍》"}, {"t": "喷浪飞唌(涎)。", "b": "郭璞《江赋》"}, {"t": "群犬垂涎。", "b": "柳宗元《三戒》"}], "words": [{"w": "口角流涎;垂涎三尺", "t": ""}]}, {"meaning": "粘液。", "cites": [{"t": "咳则腰背相引而痛,甚则咳涎。", "b": "《素问》"}]}, {"meaning": "流口水。", "cites": [{"t": "见元妃痰塞口涎,不能言语。", "b": "《红楼梦》"}]}, {"meaning": "贪羡,贪图。", "cites": [{"t": "主人涎我色,奸我,不从,则鞭挞之。", "b": "清·袁枚《新齐谐》"}], "words": [{"w": "涎利", "t": "贪图利益。"}]}, {"meaning": "嬉笑貌。", "cites": [{"t": "呸!好不识羞的涎脸!", "b": "《西厢记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4340wx','洎','1','jì','氵','9','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从水,自声。本义:往锅里添水)。"}, {"meaning": "同本义。", "cites": [{"t": "洎,灌釜也。", "b": "《说文》"}, {"t": "洎镬水。", "b": "《周礼·士师》。注:“增其沃汁。”"}, {"t": "水而洎之。", "b": "《史记·封禅书》"}, {"t": "市丘之鼎以烹鸡,多洎之则淡而不可食,少洎之则焦而不熟。", "b": "《吕氏春秋·应言》"}]}, {"meaning": "浸润。", "cites": [{"t": "越之水,浊重而洎。 ", "b": " 《管子·水地》"}]}, {"meaning": "及,到达。", "cites": [{"t": "洎乎晚节,秽乱春宫。", "b": "骆宾王《为徐敬业讨武氏檄》"}]}, {"meaning": "等到。", "cites": [{"t": "洎牧以谗诛,邯郸为郡,惜其用武不终也。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "自古洎今", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4341wx','洫','1','xù','氵','9','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从水,血声。本义:古井田制,成与成之间的水道。田间的水沟)。"}, {"meaning": "同本义。", "cites": [{"t": "洫,田间水道也。", "b": "《说文》"}, {"t": "方十里为成,成间宽八尺,深八尺,谓之洫。此井田之制。", "b": "《考工记·匠人》"}, {"t": "百夫有洫,洫上有涂。此乡遂之制。", "b": "《周礼·遂人》"}]}, {"meaning": "泛指河渠。", "cites": [{"t": "昱乃上作方梁石洫,水常饶足。", "b": "《后汉书》"}]}, {"meaning": "护城河。", "cites": [{"t": "经城洫。", "b": "张衡《西京赋》"}, {"t": "揣高卑,度厚薄,仞沟洫,物土方…以令役于诸侯。", "b": "《左传》"}]}, {"meaning": "小水。", "cites": [{"t": "大达无畛,不要止洫。", "b": "《太玄·达》"}]}, {"meaning": "古水名 。即今贯河北省东北部的滦河,上源在内蒙,古称“闪电河”。"}, {"meaning": "空出,使空虚。", "cites": [{"t": "是以长者断之,短者续之,满者洫之,虚者实之。", "b": "《管子》"}]}, {"meaning": "败坏。", "cites": [{"t": "与世偕行而不替,所行之备而不洫。", "b": "《庄子》"}]}, {"meaning": "昏惑,迷乱。", "cites": [{"t": "其厌也如缄,以言其老洫也。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4342wx','浍','1','huì kuài','氵','9','','[{"pinyin": "huì", "defs": [{"meaning": "河名,浍河 。源出河南省,流经安徽省北部,上游为东沙河和包河,在临涣汇合后,向东南流经固镇、边城,又向东流至五河县北与沱河汇合,最后流注洪泽湖。"}]}, {"pinyin": "kuài", "defs": [{"meaning": "(形声。从水,会声。(huì)本义:水名。也称浍河。源出河南省,流入安徽省) 田的排水沟。", "cites": [{"t": "以浍写水。", "b": "《周礼·稻人》。注:“田尾去水大沟。”"}, {"t": "而深山卡谷之水,四面而出,沟渠浍川,十百相通。", "b": "宋·王安石《上杜学士言开河书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4343wx','洮','1','táo','氵','9','','[{"pinyin": "táo", "defs": [{"meaning": "(形声。从水,兆声。本义:洮水)。"}, {"meaning": "同本义。", "cites": [{"t": "洮,洮水出陇西临洮,东北入河", "b": "《说文》"}]}, {"meaning": "在甘肃省西南部,黄河上游支流,源出甘肃、青海边境的西倾山东麓,东流到岷县折向北,经临洮县到毛帘峡附近入黄河。长500余公里。通称洮河。"}, {"meaning": "古地名。"}, {"meaning": "春秋时曹地。", "cites": [{"t": "盟于洮。", "b": "《春秋·僖公八年》。注:“曹地,在今山东曹州府。”"}]}, {"meaning": "故址在今山东省鄄城西。"}, {"meaning": "春秋时鲁地。", "cites": [{"t": "公会杞伯姬于洮。", "b": "《左传·庄公二十七年》。注:“鲁地。”"}]}, {"meaning": "故址在今山东省泗水县境。"}, {"meaning": "冲洗。", "cites": [{"t": "王乃洮頮水。", "b": "《书·顾命》"}, {"t": "所以洮汰涤荡至意,使之无凝竭底滞捲握而不散也。", "b": "《淮南子·要略》"}, {"t": "解释先圣之积结,洮汰学者之累惑。", "b": "《后汉书·陈元传》"}], "words": [{"w": "洮頮", "t": "盥洗"}, {"w": "洮盥", "t": "盥洗"}, {"w": "洮洮", "t": "形容人品高洁。"}]}, {"meaning": "打捞。", "cites": [{"t": "他们第二天清早便在辽河一带洮河,想洮得你的尸首。", "b": "郭沫若《星空》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4344wx','洵','1','xún','氵','9','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从水,旬声。本义:水名) 同本义。"}, {"meaning": "源出秦岭南麓沙罗幛,南流到两河关纳乾佑河,在旬阳县入汉水。长百余公里。"}, {"meaning": "假借为“恂”。诚然,确实。", "cites": [{"t": "洵有情兮。", "b": "《诗·陈风·宛丘》"}, {"t": "洵美且异。", "b": "《诗·邶风·静女》"}, {"t": "功有九转之妙,洵为希世奇珍。", "b": "《镜花缘》"}], "words": [{"w": "洵足", "t": "实在值得。"}]}, {"meaning": "流。", "cites": [{"t": "请无瘠色,无洵涕。", "b": "《国语·鲁语下》"}], "words": [{"w": "洵涕", "t": "默默地流泪。洵,通“泫”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4345wx','浒','1','hǔ xǔ','氵','9','','[{"pinyin": "hǔ", "defs": [{"meaning": "(形声。从水,许声。本义:水边,指离水稍远的岸上平地)。"}, {"meaning": "同本义。", "cites": [{"t": "岸上平地,去水稍远者名浒。", "b": "《尔雅·释丘》"}, {"t": "绵绵葛藟,在河之浒。", "b": "《诗·王风·葛藟》"}, {"t": "万人凿盘石,无由达江浒。", "b": "李白《丁都护歌》"}], "words": [{"w": "河浒", "t": "黄河边。"}]}, {"meaning": "淮水溢出的小水。", "cites": [{"t": "淮为浒。", "b": "《尔雅》。郭璞注:“皆大水溢出,别为小水之名。”"}]}, {"meaning": "浒浒,伐木声。", "cites": [{"t": "伐木浒浒。", "b": "《诗·小雅》"}]}]}, {"pinyin": "xǔ", "defs": [{"meaning": "", "words": [{"w": "浒墅关;浒浦", "t": "在江苏省常熟市东北长江岸边。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4346wx','浔','1','hǎixún xún','氵','9','','[{"pinyin": "hǎixún", "defs": [{"meaning": "海寻的旧称。"}]}, {"pinyin": "xún", "defs": [{"meaning": "水体边缘的陆地(如海边、河边)。", "cites": [{"t": "浔,厓深也。", "b": "《说文》"}, {"t": "浔,厓也。", "b": "《广雅》"}, {"t": "故虽游于江浔海裔。", "b": "《淮南子·原道》。注:“厓也。”"}, {"t": "弭节乎江浔。", "b": "枚乘《七发》"}, {"t": "吴蜀成婚此水浔,明珠步障屋黄金。", "b": "《三国演义》"}, {"t": "故虽游于江浔海裔。", "b": "《淮南子》"}], "words": [{"w": "浔涘", "t": "水边。"}]}, {"meaning": "浔阳是江西九江市的别名 。九江市的一段长江叫浔阳江。该市有浔阳楼。"}, {"meaning": "水名。"}, {"meaning": "浔水,在山东省莒县东南,西南流注入沭水。"}, {"meaning": "浔江,在广西东部,即西江中游桂平县至梧州市段的别称。"}, {"meaning": "海洋测量中计算水深的单位 。1浔=1.852米。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4347wx','浕','1','jìn','氵','9','','[{"pinyin": "jìn", "defs": [{"meaning": "中国水名。"}, {"meaning": "在湖北省枣阳县境。又名少河,与白水合流后,又名滚河。西入襄阳县,合唐河,注入汉水。", "cites": [{"t": "浕,水名。在襄阳。", "b": "《集韵》"}]}, {"meaning": "在陕西省勉县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4348wx','洳','1','rù','氵','9','','[{"pinyin": "rù", "defs": [{"meaning": "低湿的地方。"}, {"meaning": "水名。通称“洳河” 源出北京市密云县,南流至河北省三河县北之洳口入泃河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4349wx','恸','1','tòng','忄','9','','[{"pinyin": "tòng", "defs": [{"meaning": "(形声。从心,动声。本义:大哭) 同本义。", "cites": [{"t": "颜回死,子哭之恸。", "b": "《论语·先进》"}, {"t": "我歌诚自恸,非独为君悲。", "b": "柳宗元《哭连州凌员外司马》"}], "words": [{"w": "恸绝", "t": "哭晕倒。"}]}, {"meaning": "极其悲痛。", "cites": [{"t": "君与康先生捧诏恸哭。", "b": "梁启超《谭嗣同传》"}], "words": [{"w": "恸切", "t": "悲痛之极"}, {"w": "恸泣", "t": "悲痛哭泣"}, {"w": "恸怛", "t": "惨痛"}, {"w": "恸恨", "t": "极度地悲恨"}, {"w": "恸悼", "t": "悲痛伤悼"}, {"w": "恸醉", "t": "痛饮而醉"}, {"w": "恸怀", "t": "沉痛怀念。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4350wx','恓','1','xī qī xù','忄','9','','[{"pinyin": "xī", "defs": [{"meaning": "〔～～〕忙碌不安，如“圣人～～忧世。”。"}, {"meaning": "〔～惶〕a.烦恼，如“不信好人言，果有～～事”；ｂ．匆忙劳碌，如“～～戎旅下，蹉跎淮海滨”。"}]}, {"pinyin": "qī", "defs": [{"meaning": "悲伤难过。"}]}, {"pinyin": "xù", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4351wx','恹','1','yān','忄','9','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从心,厌声。本义:精神不振的样子)。"}, {"meaning": "微弱。", "cites": [{"t": "僧体枯瘦,气息恹然,渐无生气。", "b": "清·葆光子《物妖志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4352wx','恫','1','dòng tōng','忄','9','','[{"pinyin": "dòng", "defs": [{"meaning": "恐惧。", "cites": [{"t": "惠于宗公,神罔时怨,神网时恫。", "b": "《诗·大雅·思齐》"}, {"t": "国大乱,百姓恫恐。", "b": "《史记·燕世家》"}], "words": [{"w": "恫震", "t": "震惊"}, {"w": "恫恐", "t": "恐惧"}, {"w": "恫惧", "t": "恐惧"}, {"w": "恫胁", "t": "恐吓威胁"}, {"w": "恫骇", "t": "恐吓,吓唬"}, {"w": "恫喝(—hè)(恐吓)", "t": ""}]}]}, {"pinyin": "tōng", "defs": [{"meaning": "悲痛;伤心。", "cites": [{"t": "恫,痛也。", "b": "《说文》"}, {"t": "乃奉其恫。", "b": "《书·盘庚上》"}, {"t": "神罔时恫。", "b": "《诗·大雅·思齐》"}, {"t": "哀恫中国。", "b": "《诗·大雅·思柔》"}, {"t": "国大乱,百姓恫恐。", "b": "《史记·燕世家》"}], "words": [{"w": "恫怨", "t": "哀痛怨恨"}, {"w": "恫悔", "t": "痛悔"}, {"w": "恫忧", "t": "悲痛忧伤"}, {"w": "恫瘝", "t": "恫矜,恫鳏。病痛,疾苦。"}]}, {"meaning": "呻吟。", "cites": [{"t": "今痛而呻者,江南俗谓之呻唤,关中俗谓之呻恫。", "b": "唐·颜师古《匡谬正俗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4353wx','恺','1','kǎi','忄','9','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从心,豈声。本义:欢乐,和乐)。"}, {"meaning": "同本义。", "cites": [{"t": "恺,乐也。", "b": "《说文》。按,豈,愷实同一字。"}, {"t": "中心物恺。", "b": "《庄子·天道》。又如:恺悌(和乐平易,平易近人。也作恺弟,岂弟);恺恻(和乐恻隐);恺豫(和乐)"}]}, {"meaning": "明。", "cites": [{"t": "夫不勤勤则前人不当,不恳恳则觉德不恺。", "b": "《文选·扬雄·剧秦美新》"}]}, {"meaning": "假借为“凯”。军队胜利后所奏之乐。", "cites": [{"t": "王师大献,则令奏恺乐。", "b": "《周礼·大司乐》。郑玄注:“恺乐,献功之乐。”"}, {"t": "秋七月丙申,振旅,恺以入于晋。", "b": "《左传·僖公二十八年》。杜预注:“恺。乐也。”"}, {"t": "徐方一战收,振旅已奏恺。", "b": "张翥《后出军》"}], "words": [{"w": "恺歌", "t": "军队胜利归来所唱的歌"}, {"w": "恺乐", "t": "战胜归来所奏的乐歌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4354wx','恻','1','cè','忄','9','','[{"pinyin": "cè", "defs": [{"meaning": "(形声。从心,则声。本义:悲痛)。"}, {"meaning": "同本义。", "cites": [{"t": "恻,痛也。", "b": "《说文》"}, {"t": "恻,悲也。", "b": "《广雅》"}, {"t": "井渫不食,为我心恻。", "b": "《易·井》"}, {"t": "朕恻焉不忍闻。", "b": "《汉书·淮南宪王钦传》"}, {"t": "岂有肯加恻隐于细民?", "b": "《汉书·鲍宣传》"}], "words": [{"w": "凄恻", "t": "哀伤;悲痛"}, {"w": "恻痛", "t": "忧伤,悲痛。"}]}, {"meaning": "恳切。", "words": [{"w": "恻恻", "t": "诚恳;恳切。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4355wx','恂','1','xún','忄','9','','[{"pinyin": "xún", "defs": [{"meaning": "(形声。从心,旬声。本义:相信,信任)。"}, {"meaning": "同本义。", "cites": [{"t": "恂,信心也。", "b": "《说文》"}, {"t": "恂,信也。", "b": "《方言一》"}, {"t": "为下国恂蒙。", "b": "《大戴礼记·卫将军文子》"}, {"t": "且恂士师之言可也。", "b": "《列子·周穆王》"}]}, {"meaning": "诚信。", "cites": [{"t": "迪知忱恂于九德之行。", "b": "《书·立政》"}]}, {"meaning": "恐惧。", "cites": [{"t": "木处则惴慄恂惧。", "b": "《庄子·齐物论》"}], "words": [{"w": "恂慄", "t": "恐惧战慄"}, {"w": "恂惧", "t": "恐惧。"}]}, {"meaning": "严肃恭谨。", "cites": [{"t": "恂恂如也。", "b": "《论语》"}, {"t": "恂,栗也。", "b": "《礼记·大学》。注:“字或作峻。言其容貌严栗也。”"}, {"t": "参为人矜严,好修容仪,进退恂恂。", "b": "《汉书·冯参传》"}], "words": [{"w": "恂恂自下", "t": "谦虚有礼,不以地位之高而自居"}, {"w": "恂实", "t": "恭顺朴实"}, {"w": "恂谨", "t": "恭顺谨慎。"}]}, {"meaning": "畅通。", "cites": [{"t": "思虑恂达,耳目聪明。", "b": "《庄子》"}], "words": [{"w": "恂达", "t": "通达。"}]}, {"meaning": "的确;确实。", "cites": [{"t": "为下国恂蒙。", "b": "《大戴礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4356wx','恪','1','kè','忄','9','','[{"pinyin": "kè", "defs": [{"meaning": "(形声。从心,各声。本义:谨慎、恭敬)。"}, {"meaning": "同本义。", "cites": [{"t": "愙,敬也。", "b": "《说文》"}, {"t": "敬恪恭俭。", "b": "《鲁峻碑》"}, {"t": "追存二代三恪之礼。", "b": "《孔子庙碑》"}, {"t": "恪,恭也。", "b": "《字林》"}, {"t": "严威俨恪。", "b": "《礼记·祭义》"}], "words": [{"w": "恪忠", "t": "恭敬忠诚"}, {"w": "恪恭", "t": "恭敬,恭谨"}, {"w": "恪虔", "t": "恭敬虔诚"}, {"w": "恪敬", "t": "谨慎,恭敬。"}]}, {"meaning": "庄严。", "cites": [{"t": "容止严恪,须眉甚伟。", "b": "汉·应劭《风俗通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4357wx','恽','1','yùn','忄','9','','[{"pinyin": "yùn", "defs": [{"meaning": "敦厚。", "cites": [{"t": "恽,重厚也。", "b": "《说文·心部》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4358wx','宥','1','yòu','宀','9','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从宀(mián),有声。“宀”表示房屋。本义:广厦容人曰宥)。"}, {"meaning": "宽仁;宽待。", "cites": [{"t": "宥,宽也。", "b": "《说文》"}, {"t": "宥,宽也。", "b": "《国语·周语》"}, {"t": "闻在宥天下,不闻治天下也。", "b": "《庄子·在宥》"}, {"t": "知其冤而宥其失。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "宥世", "t": "以宽仁之政治理国家"}, {"w": "宥德", "t": "宽仁之德。"}]}, {"meaning": "宽恕。", "cites": [{"t": "天尊岂可违天擅杀,望天尊暂宥。——《梼杌闲评——明珠缘》", "b": ""}, {"t": "中间驰至九天,以告上帝。帝知其冤,而宥其失,前所谴责,因而获免。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "宥免", "t": "宥恕,宥赦,宥过。宽恕别人的过错"}, {"w": "宥愆", "t": "宽恕罪过。"}]}, {"meaning": "赦免。", "cites": [{"t": "宥,赦也。", "b": "《广雅》"}, {"t": "流宥五刑。", "b": "《虞书》。马注:“宽也。”"}, {"t": "掌三刺、三宥、三赦之法。", "b": "《周礼·司刺》"}, {"t": "犯臣姬昌罪犯忤君,赦宥免死,暂居里。", "b": "《封神演义》"}, {"t": "君子以赦过宥罪。", "b": "《易·解》。孔颖达疏:“宥谓宽宥,罪谓故犯,过轻则赦,罪重则宥,皆解缓之义也。”"}], "words": [{"w": "宥善", "t": "赦免善良的人"}, {"w": "宥罪", "t": "赦免罪过"}, {"w": "宥释", "t": "赦免释放。"}]}, {"meaning": "宏深;深邃。", "cites": [{"t": "夙夜基命宥密。", "b": "《诗·周颂·昊天有成命》"}], "words": [{"w": "宥地", "t": "机要之地"}, {"w": "宥密", "t": "深密;机密"}, {"w": "宥弼", "t": "形容职司机密、重要。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4359wx','扃','1','jiōng','户','9','','[{"pinyin": "jiōng", "defs": [{"meaning": "(形声。从户,冋(jiǒng)声。本义:从外面关门的门闩)。"}, {"meaning": "同本义。", "cites": [{"t": "扃,外闭之关也。", "b": "《说文》"}, {"t": "入户奉扃。", "b": "《礼记·曲礼》"}, {"t": "固扃鐍。", "b": "《庄子·胠箧》"}, {"t": "应门闭兮禁闼扃。", "b": "《汉书·外戚传》"}, {"t": "固扃鐍。", "b": "清·黄宗羲《原君》"}], "words": [{"w": "扃关", "t": "门闩"}, {"w": "扃鐍", "t": "门窗或箱箧上的关锁。"}]}, {"meaning": "车上用来固定武器和插旗的横木。", "cites": [{"t": "脱扃。", "b": "《左传·宣公十二年》。注:“车上兵阑。”服注:“横木校轮间,一曰车前横木也。”"}, {"t": "旗不脱扃,结驷方蕲。", "b": "张衡《西京赋》"}]}, {"meaning": "鼎上贯穿两耳的横杠。", "cites": [{"t": "扃,鼎扃。以木贯鼎,所以闭鼎者。", "b": "《正字通》"}, {"t": "庙门容大扃七个。", "b": "《考工记·匠人》"}, {"t": "设扃鼎。", "b": "《仪礼·士冠礼》"}, {"t": "左人抽扃鼎。", "b": "《仪礼·士虞礼》"}]}, {"meaning": "上闩、关门。", "cites": [{"t": "扃牖而居。(关着门窗呆在里面,关闭。牖,窗户。)", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "扃门", "t": "关门"}, {"w": "扃户", "t": "闭户"}, {"w": "扃闭", "t": "关闭"}, {"w": "扃试", "t": "指科举时代考生各闭一室应答试题"}, {"w": "扃绢", "t": "拘禁,羁绊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4360wx','衲','1','nà','衤','9','','[{"pinyin": "nà", "defs": [{"meaning": "僧徒的衣服,常用许多碎布补缀而成,因即以为僧衣的代称。", "cites": [{"t": "自出家来长自在,缘身一衲一绳休。", "b": "白居易《赠僧自远禅师》"}], "words": [{"w": "衲子", "t": "衲为僧衣。故借称僧徒为衲子"}, {"w": "衲衣", "t": "僧衣"}, {"w": "衲袄", "t": "和尚所穿的大袖上衣"}, {"w": "衲裙", "t": "僧人的衣裳"}, {"w": "衲帛", "t": "丝织物品。"}]}, {"meaning": "僧徒自称或代称。", "cites": [{"t": "老衲供茶碗,斜阳送客舟。", "b": "戴叔伦《题横山寺》"}], "words": [{"w": "老衲;衲子", "t": "指僧徒"}, {"w": "衲衣", "t": "代称僧人"}, {"w": "衲师", "t": "僧侣"}, {"w": "衲徒", "t": "僧人,僧众"}, {"w": "衲僧", "t": "和尚,僧人。"}]}, {"meaning": "缝补,补缀。", "cites": [{"t": "拘挛补衲,蠹文已甚。", "b": "钟嵘《诗品诗》"}], "words": [{"w": "衲裰", "t": "布块补缀成的短袍"}, {"w": "纳头", "t": "用破布补缀而成的布片子;补丁很多的衣服"}, {"w": "衲帛", "t": "织绣"}, {"w": "衲被", "t": "曾经补缀的被子"}, {"w": "衲衣", "t": "衲头。补缀过的衣服。泛指破旧衣服"}, {"w": "衲袍", "t": "用碎布料缝缀的袍服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4361wx','衽','1','rèn','衤','9','','[{"pinyin": "rèn", "defs": [{"meaning": "(形声。从衣,壬声(rén)。本义:衣襟)。"}, {"meaning": "同本义。", "cites": [{"t": "衽二尺有五寸。", "b": "《仪礼·丧服记》"}, {"t": "再拜稽首以衽受。", "b": "《公羊传·昭公二十五年》"}, {"t": "楚必敛衽而朝。", "b": "《汉书·张良传》"}], "words": [{"w": "衽左", "t": "左衽。我国古代某些少数民族的服装,前襟向左掩,异于中原一带的右衽。用以指受外族的统治"}, {"w": "衽服", "t": "左衽之服。指少数民族的服装"}, {"w": "衽发 ", "t": "披发左衽。指古代中原地区以外少数民族的装束。"}]}, {"meaning": "指床草席。", "cites": [{"t": "御衽于奥。", "b": "《仪礼·士昏礼》。注:“卧席也。”"}, {"t": "衽席床第。", "b": "《周礼·王府》"}], "words": [{"w": "衽席", "t": "床褥与莞簟"}, {"w": "衽席之上", "t": "比喻安全舒适的地方。"}]}, {"meaning": "袖子。", "cites": [{"t": "衽,袖也。", "b": "《广雅》"}, {"t": "文伯引衽攘捲而亲馈之。", "b": "《列女传》"}]}, {"meaning": "下裳。", "cites": [{"t": "终岁御,衣衽不敝。", "b": "《周礼》。郑玄注:“衽谓裳也。”"}]}, {"meaning": "古时连接棺盖与棺木的木楔,两头宽中间窄。汉代名为小腰,插入棺口两旁的坎中,使盖与棺身密合。", "cites": [{"t": "君盖用漆,三衽三束。", "b": "《仪礼·丧大记》"}]}, {"meaning": "睡卧。", "cites": [{"t": "故得病寝衽,畏惧鬼至。", "b": "汉·王充《论衡·订鬼篇》"}], "words": [{"w": "衽金革", "t": "以兵器、甲胄为卧席。形容时刻保持警惕,随时准备迎敌。"}]}, {"meaning": "整理衣襟。", "cites": [{"t": "正冠则缨绝,衽襟则时见。", "b": "《新序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4362wx','衿','1','jīn','衤','9','','[{"pinyin": "jīn", "defs": [{"meaning": "(形声。从衣,今声。本义:古代衣服的交领)。"}, {"meaning": "同本义。", "cites": [{"t": "泣下沾衿。", "b": "《汉书·李广苏建传》"}, {"t": "落衿袖间。", "b": "《聊斋志异·促织》"}], "words": [{"w": "青衿", "t": "青领"}, {"w": "衿喉", "t": "衣领和咽喉。比喻险要之地"}, {"w": "衿褵", "t": "衿襘。施衿结褵。古代女子出嫁时,由母亲将佩巾系上女儿领衿的一种礼节。"}]}, {"meaning": "专指古代读书人穿的衣服。", "cites": [{"t": "青青子衿,悠悠我心。", "b": "《诗·郑风》。毛传:“青衿,青领也,学子之所服。”"}]}, {"meaning": "秀才。", "cites": [{"t": "合城绅衿都来吊唁。", "b": "《儒林外史》"}]}, {"meaning": "结上带子,以带束衣。", "cites": [{"t": "皆衿甲面缚。", "b": "《左传》"}], "words": [{"w": "衿甲", "t": "穿着盔甲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4363wx','袂','1','mèi','衤','9','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。从衣,夬(guài)声。本义:衣袖) 同本义。", "cites": [{"t": "捐余袂兮江中,遗余褋兮澧浦。", "b": "《楚辞·九歌湘夫人》"}, {"t": "攘袂群起。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "袂接肩摩", "t": "形容人多"}, {"w": "袂云汗雨", "t": "极言行人之多"}, {"w": "袂裾", "t": "襟袖。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4364wx','祛','1','qū','礻','9','','[{"pinyin": "qū", "defs": [{"meaning": "祭神以求去祸除灾。", "cites": [{"t": "祛,去也。", "b": "《广韵·释诂二》"}, {"t": "惑祛吝亦泯", "b": "《文选·殷仲文南州桓公九井作诗》"}], "words": [{"w": "祛邪", "t": "驱除邪恶"}, {"w": "祛退", "t": "驱除"}, {"w": "祛逐", "t": "驱逐邪妖、灾异"}, {"w": "祛褪", "t": "驱除"}, {"w": "祛机", "t": "驱除机心"}, {"w": "祛蠹除奸", "t": "驱除祸害,消除奸佞。"}]}, {"meaning": "消散。", "cites": [{"t": "权舆天地未祛,睢睢盱盱。", "b": "汉·扬雄《剧秦美新》"}], "words": [{"w": "祛累", "t": "谓解除尘俗的牵累"}, {"w": "祛练神明", "t": "佛教语。修智慧,断烦恼。意谓去除尘念,修炼智慧,便可成佛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4365wx','祜','1','hù','礻','9','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从示,古声。本义:福;大福) 同本义", "words": [{"w": "祜休", "t": "吉庆,幸福美善"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4366wx','祓','1','fú','礻','9','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从“示”,表示与祭神有关。本义:古代为除灾求福而举行的一种仪式)。"}, {"meaning": "同本义。", "cites": [{"t": "祓,除恶祭也。", "b": "《说文》"}, {"t": "祓,祭也。", "b": "《尔雅·释天》"}, {"t": "祓禳于四方。", "b": "《左传·昭公十八年》"}, {"t": "王其祗祓监农不易。", "b": "《国语·周语》"}, {"t": "帝祓霸上。", "b": "《汉书·外戚传上》"}], "words": [{"w": "祓楔", "t": "古代春秋两季在水边举行的祈求福佑的祭礼"}, {"w": "祓禳", "t": "除凶之祭"}, {"w": "祓殡", "t": "祭于殡以除凶邪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4367wx','祚','1','zuò','礻','9','','[{"pinyin": "zuò", "defs": [{"meaning": "(形声。从示,乍声。本义:福;福运)。"}, {"meaning": "同本义。", "cites": [{"t": "若能类善物,以混厚民人者,必有章誉蕃育之祚。", "b": "《国语》"}, {"t": "今当祚永运隆之日,太平无为之世。", "b": "《红楼梦》"}, {"t": "真主已出,隋祚不长。", "b": "《隋唐演义》"}], "words": [{"w": "祚长", "t": "福运久长"}, {"w": "祚薄", "t": "福分微薄"}, {"w": "祚土", "t": "福地;疆土"}, {"w": "祚胤", "t": "福运及于后代子孙"}, {"w": "祚庆", "t": "福祐。"}]}, {"meaning": "帝位。", "cites": [{"t": "往者王莽作逆,汉祚中缺。", "b": "《东都赋》"}]}, {"meaning": "赐福。", "cites": [{"t": "天祚明德。", "b": "《左传》"}, {"t": "皇天嘉之,祚以天下。", "b": "《国语》"}, {"t": "今吾兄嗣位未几,辄思篡汉,皇天必不祚尔!", "b": "《全图绣像三国演义》"}], "words": [{"w": "祚土", "t": "封赐土邑"}, {"w": "祚命", "t": "上天赐福。"}]}, {"meaning": "保佑。", "cites": [{"t": "祚灵主以元吉。", "b": "《文选》"}]}, {"meaning": "流传。", "cites": [{"t": "传祚万世。", "b": "《晋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4368wx','诮','1','qiào','讠','9','','[{"pinyin": "qiào", "defs": [{"meaning": "(形声。从言,肖声。《说文》:作“谯”。本义:责备)。"}, {"meaning": "同本义。", "cites": [{"t": "诮,呵也。", "b": "《龙龛手鉴》"}, {"t": "丈人归,酒醒而诮其子。", "b": "《吕氏春秋·疑似》"}], "words": [{"w": "诮责", "t": "责备;谴责"}, {"w": "诮诘", "t": "责问"}, {"w": "诮噪", "t": "谴责和讥刺"}, {"w": "诮让", "t": "责问"}, {"w": "诮斥", "t": "斥责"}, {"w": "诮项", "t": "指樊哙在鸿门宴上斥责项羽之事。"}]}, {"meaning": "嘲讽。", "cites": [{"t": "列壑争讥,攒峰竦诮。", "b": "孔稚圭《北山移文》"}], "words": [{"w": "诮谤", "t": "讥诮毁谤"}, {"w": "讥诮", "t": "冷言冷语地讥讽"}, {"w": "诮骂", "t": "讥笑谩骂"}, {"w": "诮讽", "t": "讥笑讽刺"}, {"w": "诮戏", "t": "嘲笑逗乐"}, {"w": "诮辱", "t": "讥讽侮辱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4369wx','祗','1','zhī','礻','9','','[{"pinyin": "zhī", "defs": [{"meaning": "(形声。从示,氐(dǐ)声。本义:恭敬) 同本义。", "cites": [{"t": "祗,敬也。", "b": "《说文》"}, {"t": "日尹祗敬六德。", "b": "《书·皋陶谟》"}, {"t": "上帝是祗。", "b": "《诗·商颂·长发》"}, {"t": "中和祗庸孝友。", "b": "《周礼·大司乐》"}, {"t": "祗,祗敬也。", "b": "《广雅》"}, {"t": "父不慈,子不祗,兄不友,弟不共,不相及也。", "b": "《左传》"}], "words": [{"w": "祗候人", "t": "在官府执役的小官史"}, {"w": "祗候", "t": "恭敬侍候"}, {"w": "祗请", "t": "恭敬邀请"}, {"w": "祗若", "t": "恭敬顺从“祇”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4370wx','祢','1','mí','礻','9','','[{"pinyin": "mí", "defs": [{"meaning": "古代军旅之事,常载神主而行,随行神主称弥。", "cites": [{"t": "侯氏裨冕,释历于祢。", "b": "《仪礼》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4371wx','诰','1','gào','讠','9','','[{"pinyin": "gào", "defs": [{"meaning": "(形声。从言,告声。本义:告诉)。"}, {"meaning": "同本义,上告下曰诰。", "cites": [{"t": "诰,告也。", "b": "《说文》。段注:“以言告人,古用此字,今则用告字。以此诰为上告下之字。”"}, {"t": "按,上告下之义,古用诰,秦复造诏安当之。", "b": "《说文通训定声》"}, {"t": "伊尹申诰于王。", "b": "《书·太甲下》"}, {"t": "后以施命诰四方。", "b": "《易·姤》"}, {"t": "告上曰告,发下曰诰。", "b": "《列子·杨朱》注"}, {"t": "雅告奥义。", "b": "《书·序》"}, {"t": "诰誓不及五帝。", "b": "《荀子·大略》。注:“诰誓以言辞相诫约也。”"}, {"t": "至秦又造诏字以当之。", "b": "《书·大诰》释文"}], "words": [{"w": "诰命夫人", "t": "特指受封赠的夫人"}, {"w": "诰授", "t": "以诰命授与"}, {"w": "诰文", "t": "帝王的祷告文字。"}]}, {"meaning": "告诫;劝勉。", "cites": [{"t": "近臣谏,远臣谤,舆人诵,以自诰也。", "b": "《国语·楚语上》"}], "words": [{"w": "诰毖", "t": "告诫"}, {"w": "诰教", "t": "告诫教育。"}]}, {"meaning": "告诫之文。帝王任命或封赠的文书 。古者上下有诰,秦废古制称制、诏。唐称制不称诰。宋始以诰命庶官,凡追赠大臣、贬谪有罪、赠封其祖父妻室,不宜于廷者,皆用诰,通谓之制。", "cites": [{"t": "一品至五品,皆授以诰命,六品至九品,皆授以敕命。", "b": "《清会典事例》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4372wx','诳','1','kuáng','讠','9','','[{"pinyin": "kuáng", "defs": [{"meaning": "(形声。从言,狂声。本义:欺骗,迷惑) 同本义(隐瞒事实真相迷惑人)。", "cites": [{"t": "诳,欺也。", "b": "《说文》"}, {"t": "诳,诳惑也。", "b": "《玉篇》"}, {"t": "幼子常视无诳。", "b": "《礼记·曲礼》"}, {"t": "以诳刘子。", "b": "《国语·周语》"}, {"t": "齐田单后与骑劫战,果设诈诳燕军。", "b": "《史记·乐毅列传》"}, {"t": "民疾其态,天子诳之。", "b": "《国语·晋语二》"}, {"t": "将军纪信乃乘王驾,诈为汉王,诳楚,楚皆呼万岁。", "b": "《史记·高祖本纪》"}], "words": [{"w": "诳驾", "t": "因失陪而向客人说的道歉的话"}, {"w": "诳谬", "t": "狂妄荒谬"}, {"w": "诳上", "t": "欺骗君上、尊长"}, {"w": "诳世", "t": "欺骗世人"}, {"w": "诳动", "t": "欺骗煽动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4373wx','鸩','1','zhèn','鸟','9','','[{"pinyin": "zhèn", "defs": [{"meaning": "(形声。从鸟。本义:传说中的一种毒鸟,用它的羽毛泡的酒,喝了能毒死人)。"}, {"meaning": "同本义。", "cites": [{"t": "吾令鸩为媒兮,鸩告余以不好。", "b": "《楚辞·离骚》。"}], "words": [{"w": "鸩羽", "t": "鸩之羽毛"}, {"w": "鸩翼", "t": "鸩羽。"}]}, {"meaning": "用鸩的羽毛泡成的毒酒。", "cites": [{"t": "宴安鸩毒,不可怀也。", "b": "《左传·闵公元年》。"}], "words": [{"w": "鸩酒", "t": "毒酒"}, {"w": "鸩醴", "t": "毒酒"}, {"w": "饮鸩止渴", "t": ""}]}, {"meaning": "以毒酒害人。", "cites": [{"t": "晋人执卫成公,归之于周,使医鸩之,不死。", "b": "《国语·鲁语上》。"}], "words": [{"w": "鸩杀", "t": "以药酒毒死人"}, {"w": "鸩死", "t": "鸩杀"}, {"w": "鸩弑", "t": "以毒酒毒死帝王。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4374wx','昶','1','chǎng','日','9','','[{"pinyin": "chǎng", "defs": [{"meaning": "白天时间长的。", "cites": [{"t": "昶,日长也。", "b": "《说文新附》"}]}, {"meaning": "舒畅,通畅。", "cites": [{"t": "譬犹众目营方,则天纲自昶。", "b": "《文选·陆机·五等论》。《广雅》云:昶,通也。"}, {"t": "固以和昶而足耽矣。", "b": "嵇康《琴赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4375wx','郡','1','jùn','阝','9','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。从邑,君声。从“邑”,表示与行政区域有关。本义:古代的行政区域)。"}, {"meaning": "同本义。", "cites": [{"t": "郡,周制,天子地方千里,分为百县,县有四郡,故春秋传曰,上大夫受县,下大夫受郡是也。至秦初置三十六郡,以监其县。", "b": "《说文》。朱骏声曰:汉又增四十六郡,二十一国,凡郡国一百有三,古者县大郡小,秦以后郡大县小。"}, {"t": "及郡下。", "b": "晋·陶渊明《桃花源记》"}, {"t": "谪守巴陵郡。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "从郡城就童子试归。", "b": "清·周容《芋老人传》"}, {"t": "自郡城走数十里。", "b": ""}], "words": [{"w": "郡属", "t": "郡守的属员"}, {"w": "郡廨", "t": "郡府"}, {"w": "郡朝", "t": "郡署的厅事。亦指郡守"}, {"w": "郡章", "t": "郡太守的印玺"}, {"w": "郡倅", "t": "郡佐。郡守的副职。"}]}, {"meaning": "英国和爱尔兰的领土区划分之一,构成为行政、司法和政治目的而设立的主要单位,包括以前盎格鲁撒克逊的郡和其它从未成为郡的地区。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4376wx','咫','1','zhǐ','口','9','','[{"pinyin": "zhǐ", "defs": [{"meaning": "(形声。从尺,只声。本义:古代长度名,周制八寸,合今制市尺六寸二分二厘) 同本义。", "cites": [{"t": "中妇人手长八寸谓之咫,周尺也。", "b": "《说文》"}, {"t": "天威不违颜咫尺。", "b": "《左传·僖公九年》"}, {"t": "吾不能行也咫。", "b": "《国语·晋语》"}, {"t": "是知无咫。", "b": "《国语·楚语》。注:“言少也。”"}], "words": [{"w": "咫尺之书", "t": "书信。"}]}, {"meaning": "比喻距离很近。", "cites": [{"t": "晋视道如咫。", "b": "《周书·太子》。注:“喻近。”"}, {"t": "不亏其身,不损其形,可谓孝矣。君子无行咫步而忘之。", "b": "《吕氏春秋》"}], "words": [{"w": "咫步", "t": "短距离"}, {"w": "咫见", "t": "短浅的见识"}, {"w": "咫书", "t": "咫尺之书"}, {"w": "咫尺千里", "t": "谓虽近在咫尺,却似远隔千里。形容行路之难;也形容相见之难"}, {"w": "咫只天颜", "t": "咫尺颜。咫尺威颜。比喻离天子容颜极近。亦指天子之颜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4377wx','弭','1','mǐ','弓','9','','[{"pinyin": "mǐ", "defs": [{"meaning": "(形声。从弓,耳声。本义:角弓,末端用骨做装饰的弓)。"}, {"meaning": "同本义。", "cites": [{"t": "弭,弓无缘,可以解辔纷者。", "b": "《说文》。按,以骨饰两头,不缴束,不漆。"}, {"t": "若不获命,其左执鞭弭,右属櫜鞬,以与君周旋。", "b": "《左传·僖公二十三年》"}]}, {"meaning": "弓梢的弯曲处。", "cites": [{"t": "象引鱼服。", "b": "《诗·小雅·采薇》"}, {"t": "桦皮装弓,两端骨弭。", "b": "《南史》"}], "words": [{"w": "弭头", "t": "弓的下端。"}]}, {"meaning": "止息;中断。", "cites": [{"t": "不可弭忘。", "b": "《诗·小雅·沔水》"}, {"t": "祸至今未弭。", "b": "《国语·周语下》"}, {"t": "众不可弭。", "b": "《国语·晋语二》"}, {"t": "于是乎弭其百苛。", "b": "《国语·楚语下》"}, {"t": "子其弭口无言。", "b": "《战国策·秦策二》"}, {"t": "吾能弭谤矣。", "b": "《国语·周语上》"}], "words": [{"w": "弭息", "t": "平息,止息"}, {"w": "弭兵", "t": "息兵;停止战争"}, {"w": "弭戢", "t": "止息,收敛"}, {"w": "弭节", "t": "驻节,停车;少停"}, {"w": "弭宁", "t": "平息。"}]}, {"meaning": "顺从。", "cites": [{"t": "城邑莫不望风弭从。", "b": "《后汉书》"}], "words": [{"w": "弭耳受教", "t": "驯服;服帖"}, {"w": "弭从", "t": "服从,顺从。"}]}, {"meaning": "消除。", "cites": [{"t": "春招弭,以除疾病。", "b": "《周礼·春官·男巫》"}], "words": [{"w": "弭盗无方", "t": "除盗无方"}, {"w": "弭患无形", "t": "在祸患尚未形成之前就予以消除"}, {"w": "弭难", "t": "消除灾难。"}]}, {"meaning": "安抚,安定。", "cites": [{"t": "春招弭以除疾病。", "b": "《周礼·春官·男巫》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4378wx','牁','1','kē','爿','9','','[{"pinyin": "kē", "defs": [{"meaning": "——“牂牁”(Zāngkē):古水名;古地名(亦作“牂柯”。船只停泊时用以系缆绳的木桩)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4379wx','胥','1','xū','月','9','','[{"pinyin": "xū", "defs": [{"meaning": "(形声。从肉,疋(shū)声。本义:蟹酱)。"}, {"meaning": "同本义。", "cites": [{"t": "胥,蟹醢也。", "b": "《说文》"}, {"t": "青州之蟹胥。", "b": "《周礼·庖人》注"}, {"t": "蟹胥,取蟹藏之,使骨头解胥胥然也。", "b": "《释名》"}, {"t": "共祭祀之好胥。", "b": "《周礼》"}]}, {"meaning": "片刻,一会儿。", "cites": [{"t": "胡蝶胥也。", "b": "《列子·天瑞》"}, {"t": "胡蝶胥也化而为虫。", "b": "《庄子》"}]}, {"meaning": "古代官府中的小吏;特指古代掌管捕捉盗贼的小官吏", "cites": [{"t": "里胥猾黠。", "b": "《聊斋志异·促织》"}, {"t": "就老胥而问。", "b": "清·方苞《狱中杂记》"}, {"t": "部中老胥。", "b": ""}, {"t": "胥某谓曰。", "b": ""}, {"t": "胥某笑曰。", "b": ""}], "words": [{"w": "胥里", "t": "乡里小吏"}, {"w": "胥役", "t": "胥吏与差役"}, {"w": "胥靡", "t": "刑徒"}, {"w": "胥祝", "t": "司祭的小吏"}, {"w": "胥耆", "t": "老吏"}, {"w": "胥师", "t": "管市场的小吏。"}]}, {"meaning": "有才智的人。", "cites": [{"t": "胥,十有二人;徒,百有二十人。", "b": "《周礼》"}]}, {"meaning": "古代乐官。", "cites": [{"t": "小胥大胥。", "b": "《礼记·王制》。注:“皆乐官属也。”"}, {"t": "大胥是敛,众胥佐之。", "b": "《礼记》"}], "words": [{"w": "胥人", "t": "古代乐官。"}]}, {"meaning": "相互。", "cites": [{"t": "以比追胥之事。", "b": "《周礼·士师》"}, {"t": "兄弟昏姻,无胥远矣。", "b": "《诗·小雅·角弓》"}], "words": [{"w": "胥命", "t": "诸侯相见,约言不誓"}, {"w": "胥溺", "t": "相继沉没"}, {"w": "胥译", "t": "互译,翻译"}, {"w": "胥怨", "t": "互怨。"}]}, {"meaning": "都;皆。", "cites": [{"t": "尔之教矣,民胥效矣。", "b": "《诗·小雅·角弓》"}]}, {"meaning": "等待。", "cites": [{"t": "胥与公往见之。", "b": "《史记·扁仓传》"}, {"t": "胥令而动者也。", "b": "《管子·君臣》"}, {"t": "太后盛怒而胥之。", "b": "《史记·赵世家》"}]}, {"meaning": "看,观察。", "cites": [{"t": "胥后令。", "b": "《史记·廉颇蔺相如传》"}, {"t": "将胥有所定也。", "b": "《管子·大匡》"}, {"t": "于胥斯原,既庶既繁。", "b": "《诗·大雅·公刘》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4380wx','陛','1','bì','阝','9','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从阜,坒(bì)声。从“阜”,表示与地形地势的高低上下有关。本义:帝王宫殿的台阶)。"}, {"meaning": "同本义。", "cites": [{"t": "陛,升高阶也。", "b": "《说文》。按,天子之陛九级。"}, {"t": "举杰压陛,诛讥罢只。", "b": "《楚辞·大招》"}, {"t": "陛者,皆闻焉。", "b": "《汉书·五行志》。注:“谓执兵列于陛侧者。”"}, {"t": "大王陛下。", "b": "《汉书·高帝纪》。按,臣与至尊言不敢指斥,故呼在陛下者告之。"}, {"t": "陛高二尺五,广长各三尺,远广各六尺。", "b": "《墨子·备城门》"}, {"t": "至陛下,秦武阳色变振恐,群臣怪之。", "b": "《战国策·燕策》"}], "words": [{"w": "陛卫", "t": "帝王身边的卫士"}, {"w": "陛槛", "t": "宫殿台阶两旁的栏杆"}, {"w": "陛兵", "t": "皇宫前殿陛两旁的警卫士兵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4381wx','陟','1','zhì','阝','9','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意。甲骨文字形。从阜,从步。左边是山坡,右边是两只向上的脚,表示由低处向高处走。本义:由低处向高处走;升;登高)。"}, {"meaning": "同本义,与“降”相对。", "cites": [{"t": "陟,登也。", "b": "《说文》"}, {"t": "陟,陞也。", "b": "《尔雅》"}, {"t": "陟降庭止。", "b": "《诗·周颂·闵予小子》"}, {"t": "汝陟帝位。", "b": "《虞书》"}, {"t": "省幽明以黜陟。", "b": "张衡《东京赋》"}, {"t": "陟彼崔嵬。", "b": "《诗·周南·卷耳》"}, {"t": "人陟降大艰。", "b": "柳宗元《井铭并序》"}], "words": [{"w": "陟屺", "t": "登屺山。比喻思念母亲。屺,无草木的山"}, {"w": "陟岵", "t": "登岵山。比喻思念父亲。岵,草木繁茂的山。"}]}, {"meaning": "登程,上路。", "cites": [{"t": "若升高,必自下;若陟遐,必自迩。", "b": "《书·太甲下》"}], "words": [{"w": "陟遐", "t": "远行"}, {"w": "陟卓", "t": "远行"}, {"w": "陟涉", "t": "跋涉。"}]}, {"meaning": "晋升。", "cites": [{"t": "陟罚臧否,不宜异同。(臧,善。否,恶。臧否,奖善惩恶。臧、否,这里都是动词。)", "b": "诸葛亮《出师表》"}], "words": [{"w": "陟罚", "t": "提拔与惩罚"}, {"w": "陟黜", "t": "进用与贬黜"}, {"w": "陟劝", "t": "提升与奖励"}, {"w": "陟明", "t": "进用贤明。"}]}, {"meaning": "升遐,升天。", "cites": [{"t": "惟新陟王,毕协赏罚。", "b": "《书·康王之诰》"}], "words": [{"w": "陟配", "t": "天子升天后,于祭天时配享。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4382wx','娅','1','yà','女','9','','[{"pinyin": "yà", "defs": [{"meaning": "(形声。从女,亚声。本义:连襟,姊妹之夫相互的称谓) 同本义 。姐妹二人的丈夫互相称娅。", "cites": [{"t": "两婿相谓为娅。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4383wx','姮','1','héng','女','9','','[{"pinyin": "héng", "defs": [{"meaning": "神话中的月中女神。", "cites": [{"t": "羿请不死之药于西王母，姮姮窃以奔月。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4384wx','娆','1','ráo rǎo','女','9','','[{"pinyin": "ráo", "defs": [{"meaning": "柔弱。", "cites": [{"t": "娆,弱也。", "b": "《广雅》"}]}, {"meaning": "妍媚。", "cites": [{"t": "看红装素裹,分外妖娆。", "b": "毛泽东《沁园春·雪》"}], "words": [{"w": "妖娆", "t": "妩媚多姿"}, {"w": "娇娆", "t": "柔美妩媚。"}]}]}, {"pinyin": "rǎo", "defs": [{"meaning": "(形声。从女,尧声。本义:烦扰;扰乱)。"}, {"meaning": "同本义。", "cites": [{"t": "娆,苛也。", "b": "《说文》"}, {"t": "娆,烦也。亦恼也。", "b": "《纂文》"}, {"t": "除苛解娆。", "b": "《汉书·晁错传》"}, {"t": "其神不娆。", "b": "《淮南子·原道》"}, {"t": "伤死者其鬼娆。", "b": "《淮南子·俶真》"}], "words": [{"w": "娆乱", "t": "扰乱"}, {"w": "娆固", "t": "扰乱蛊惑"}, {"w": "娆害", "t": "捣乱破坏"}, {"w": "娆败", "t": "扰乱破坏"}, {"w": "娆恼", "t": "烦忧。"}]}, {"meaning": "戏弄。", "cites": [{"t": "娆,戏弄也。", "b": "《说文》"}]}, {"meaning": "生气。", "cites": [{"t": "娆,恼也。", "b": "唐·玄应《一切经音义》"}]}, {"meaning": "琐碎。", "cites": [{"t": "娆,苛也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4385wx','姝','1','shū','女','9','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从女,朱声。本义:美好) 同本义。", "cites": [{"t": "姝,女子也。", "b": "《说文》"}, {"t": "姝,好貌也。", "b": "《字林》"}, {"t": "静女其姝。", "b": "《诗·邶风·静女》"}], "words": [{"w": "姝好", "t": "姿态美好"}, {"w": "姝妖", "t": "美丽妖艳"}, {"w": "姝美", "t": "美丽"}, {"w": "姝惠", "t": "美丽聪慧"}, {"w": "姝姝", "t": "美好的样子;顺从的样子"}, {"w": "姝貌", "t": "姝颜。美丽的容貌"}, {"w": "姝丽", "t": "容貌美丽"}, {"w": "姝艳", "t": "美丽"}, {"w": "姝秀", "t": "秀丽。"}]}, {"meaning": "美女。", "cites": [{"t": "使君遣吏往,问是谁家姝。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "姝丽", "t": "美女"}, {"w": "姝娈", "t": "美女"}, {"w": "姝好", "t": "美女"}, {"w": "姝子", "t": "美女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4386wx','姣','1','jiāo','女','9','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从女,交声。本义:修长美丽)。"}, {"meaning": "同本义。", "cites": [{"t": "姣,好也。", "b": "《说文》。段玉裁注:“姣谓容体壮大之好也。”徐灏笺:“凡从交声之字其义多为长…壮佼亦谓其壮而高长,非谓大也。”"}, {"t": "弃位而姣,不可为贞。", "b": "《左传·襄公九年》"}, {"t": "灵偃蹇兮姣服。", "b": "《楚辞·东方太一》"}, {"t": "古者桀纣长巨姣美,天下之杰也。", "b": "《荀子·非相》"}, {"t": "前有楼阙轩辕,后有长姣美人。", "b": "《史记》"}]}, {"meaning": "容貌美好的。", "cites": [{"t": "娇丽施只。", "b": "《大招》"}, {"t": "公姣且丽。", "b": "《吕氏春秋·达郁》"}, {"t": "左右言其姣好。", "b": "《汉书·东方朔传》。注:“美丽也。”"}], "words": [{"w": "姣艳", "t": "美好艳丽"}, {"w": "姣娥", "t": "美貌的女子"}, {"w": "姣姬", "t": "美女"}, {"w": "姣人", "t": "美人"}, {"w": "姣色", "t": "美色"}, {"w": "姣冶", "t": "美丽"}, {"w": "姣妙", "t": "美妙"}, {"w": "姣服", "t": "谓服饰华美"}, {"w": "姣怯怯", "t": "娇弱"}, {"w": "姣羞", "t": "妩媚害羞"}, {"w": "姣弱", "t": "娇嫩细弱"}, {"w": "姣滴滴", "t": "娇媚"}, {"w": "姣贵", "t": "娇贵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4387wx','姘','1','pīn','女','9','','[{"pinyin": "pīn", "defs": [{"meaning": "(形声。从女,并声。本义:非夫妻男女同居)。"}, {"meaning": "同本义。", "cites": [{"t": "汉律齐人通妻婢曰姘。", "b": "《说文》"}, {"t": "男女私合曰姘。", "b": "《苍颉篇》"}], "words": [{"w": "姘合", "t": "男女私相结合"}, {"w": "姘人", "t": "和非夫妻关系的人同居。"}]}, {"meaning": "去掉"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4388wx','姹','1','chà','女','9','','[{"pinyin": "chà", "defs": [{"meaning": "(形声。从女,宅声。本义:少女) 少女;美女。", "cites": [{"t": "奼,少女也。", "b": "《说文》"}, {"t": "河间姹女工数钱。", "b": "《汉书·五行志》"}], "words": [{"w": "姹女", "t": "美女。道教指水银。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4389wx','怼','1','duì','心','9','','[{"pinyin": "duì", "defs": [{"meaning": "(形声。从心,对声。本义:怨恨) 同本义。", "cites": [{"t": "怼,怨也。", "b": "《说文》"}, {"t": "怼,恨也。", "b": "《广雅·释诂四》"}, {"t": "以死谁怼。", "b": "《左传·僖公二十四年》"}, {"t": "力尽则怼。", "b": "《谷梁传·庄公三十一年》"}, {"t": "以怼父母。", "b": "《孟子》"}, {"t": "怼以手自捣。", "b": "《汉书·外戚传》"}], "words": [{"w": "怼恨", "t": "怨恨"}, {"w": "怼憾", "t": "怨恨"}, {"w": "怼怨", "t": "怨恨"}, {"w": "怼怒", "t": "怨怒"}, {"w": "怼笔", "t": "出于怨恨的记载。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4390wx','羿','1','yì','羽','9','','[{"pinyin": "yì", "defs": [{"meaning": "鸟张翅旋风而上。", "cites": [{"t": "羿,羽之羿风。", "b": "《说文》。段玉裁注:谓抟扶摇而上之状"}]}, {"meaning": "唐尧时的射师。", "cites": [{"t": "自开辟以来,太阳星原有十,后被羿善开弓,射落九乌坠地,止存金乌一星。", "b": "《西游记》"}], "words": [{"w": "羿弓", "t": "羿的弓矢所及"}, {"w": "羿妃", "t": "指神话中羿妻嫦娥"}, {"w": "羿毙十日", "t": "指羿射日的传说。"}]}, {"meaning": "夏时有穷氏国君。", "cites": [{"t": "羿犹不悛,将归自田,家众杀而亨之。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4391wx','炱','1','tái','火','9','','[{"pinyin": "tái", "defs": [{"meaning": "烟尘。烟气凝积而成的黑灰。俗称烟子。", "cites": [{"t": "炱,灰炱煤也。从火,台声。", "b": "《说文》"}, {"t": "积烟为炱煤。", "b": "《通俗文》"}, {"t": "埃(炱)不漫。", "b": "《列子·黄帝》"}], "words": [{"w": "煤炱", "t": "亦作“炲煤”。煤灰"}, {"w": "炱朽", "t": "因长期被烟熏而腐烂。"}]}, {"meaning": "黑色。", "cites": [{"t": "肾风之状…其色炱。", "b": "《素问·风论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4392wx','矜','1','guān jīn qín','矛','9','','[{"pinyin": "guān", "defs": [{"meaning": "无妻的老人。也泛指无妻的人。", "cites": [{"t": "少而无父者谓之孤;老而无子者谓之独;老而无妻者谓之矜;老而无夫者谓之寡。", "b": "《礼记·王制》"}, {"t": "爰及矜人,哀此鳏寡。", "b": "《诗·小雅·鸿雁》"}, {"t": "不侮矜寡。", "b": "《诗·大雅·烝民》"}, {"t": "养孤老,食常疾,收矜寡。", "b": "《管子·幼官》"}, {"t": "有矜在民间,曰虞舜。", "b": "《史记·五帝本纪》"}, {"t": "善者必先乎矜寡孤独。", "b": "《说苑·修文》"}], "words": [{"w": "矜人", "t": "贫苦可怜的人"}, {"w": "矜寡", "t": "同“鳏寡”。"}]}]}, {"pinyin": "jīn", "defs": [{"meaning": "自夸;自恃。", "cites": [{"t": "矜,大也。", "b": "《广雅》"}, {"t": "不矜而庄。", "b": "《礼记·表礼》。注:“谓自尊大也。”"}, {"t": "不可以矜而祗取忧也。", "b": ""}, {"t": "矜其伐而耻其功。", "b": ""}, {"t": "矜之者何?犹曰莫我若也。", "b": "《公羊传·僖公九年》"}, {"t": "不敢矜其善。", "b": "《韩非子·说疑》"}, {"t": "矜功不立。", "b": "《战国策·齐策》"}, {"t": "以矜气作之。", "b": "唐·柳宗元《柳河东集》"}, {"t": "以此自矜。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "自矜", "t": "自恃"}, {"w": "矜功", "t": "自夸功勋"}, {"w": "矜伐", "t": "恃功自夸"}, {"w": "矜尚", "t": "骄尊夸耀,争出人上"}, {"w": "矜饰", "t": "骄夸虚饰"}, {"w": "矜宠", "t": "仗恃有宠而骄。"}]}, {"meaning": "怜悯;同情。", "cites": [{"t": "矜,惜也。", "b": "《小尔雅》"}, {"t": "爰及矜人。", "b": "《诗·小雅·鸿雁》"}, {"t": "矜此劳人。", "b": "《诗·小雅·巷伯》"}, {"t": "见人之厄则矜之。", "b": "《公羊传·宣公十五年》。注:“闵也。”"}, {"t": "哀矜庶戮之不辜。", "b": "《书·吕刑》"}, {"t": "予惟率肆矜尔。", "b": "《书多士》"}, {"t": "矜,惜也。", "b": "《小尔雅》"}, {"t": "爰及矜人。", "b": "《诗·小雅·鸿雁》"}, {"t": "矜此劳人。", "b": "《诗·小雅·巷伯》"}, {"t": "见人之厄则矜之。", "b": "《公羊传·宣公十五年》。注:“闵也。”"}, {"t": "哀矜庶戮之不辜。", "b": "《书·吕 刑》"}, {"t": "予惟率肆矜尔。", "b": "《书多士》"}, {"t": "天矜于民。", "b": "《书·泰誓》"}], "words": [{"w": "矜爱", "t": "同情怜爱"}, {"w": "矜哀", "t": "怜悯爱惜"}, {"w": "矜念", "t": "怜悯思念"}, {"w": "矜愍", "t": "矜悯。怜悯;怜惜。"}]}, {"meaning": "注重;崇尚。", "cites": [{"t": "故人矜节行。", "b": "贾谊《陈政事疏》"}], "words": [{"w": "矜式", "t": "尊敬而效法"}, {"w": "矜全", "t": "爱护成全"}, {"w": "矜名", "t": "崇尚名声"}, {"w": "矜谑", "t": "崇尚戏谑。"}]}, {"meaning": "(形声。从矛,令声。作从今者误。(qín)本义:矛柄)。"}, {"meaning": "骄傲。", "cites": [{"t": "虫翘然矜鸣,似报主知。", "b": "《聊斋志异》"}], "words": [{"w": "矜浮", "t": "骄矜浮躁"}, {"w": "矜大", "t": "骄傲自大"}, {"w": "矜物", "t": "骄傲而瞧不起别人"}, {"w": "矜侉", "t": "骄傲自大"}, {"w": "矜前", "t": "炫夸从前的名声"}, {"w": "矜负", "t": "高傲而自负。"}]}, {"meaning": "端庄;庄重。", "cites": [{"t": "君子矜而不争。", "b": "《论语》"}, {"t": "古之矜也廉", "b": ""}], "words": [{"w": "矜庄", "t": "端庄稳重"}, {"w": "矜严", "t": "庄重威严"}, {"w": "矜容", "t": "端庄的容态"}, {"w": "矜饬", "t": "端庄严整"}, {"w": "矜厉", "t": "庄重严厉"}, {"w": "矜肃", "t": "庄重严肃。"}]}, {"meaning": "谨守,慎重。", "cites": [{"t": "参为人矜严,好修容仪。", "b": "《汉书·冯参传》"}, {"t": "矜行以事君。", "b": "《大戴礼记·小辨》。注:“慎也。伪旅獒,不矜细行。”"}], "words": [{"w": "矜奋", "t": "谨持奋勉"}, {"w": "矜峻", "t": "谨严"}, {"w": "矜裁", "t": "拘谨克制"}, {"w": "矜炼", "t": "谨严而精炼"}, {"w": "矜谨", "t": "矜持拘谨。"}]}, {"meaning": "苦,穷困。", "cites": [{"t": "矜其血气,以规法度。", "b": "《庄子》。郭庆藩集释:“矜其血气,犹孟子言:苦其心志也。矜者,苦也。”"}]}, {"meaning": "凶危,危险。", "cites": [{"t": "曷予靖之,居以凶矜。", "b": "《诗·小雅》。毛传:“矜,危也。”郑玄笺:“居我以凶危之地。”"}]}, {"meaning": "急遽,暴躁乖戾 。 如:矜肆(骄纵放肆);矜纠收缭(暴躁乖戾)。"}]}, {"pinyin": "qín", "defs": [{"meaning": "(形声。从矛,今声。本义:矛柄) 同本义。", "cites": [{"t": "徂耰棘矜。", "b": "汉·贾谊《新书·过秦论上》"}, {"t": "矛,其柄谓之矜。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4393wx','绔','1','kù','纟','9','','[{"pinyin": "kù", "defs": [{"meaning": "(形声。从糸,夸声。本义:套裤)。"}, {"meaning": "同本义。", "cites": [{"t": "绔,胫衣也。", "b": "《说文》。段注:“今所谓套袴也。”"}, {"t": "绔,跨也,两股各跨别也。", "b": "《释名·释衣服》"}, {"t": "身衣羊裘皮绔。", "b": "《后汉书·马援传》"}]}, {"meaning": "绊络。", "cites": [{"t": "绔白虎。", "b": "司马相如《上林赋》。注:“谓绊络之也。”"}, {"t": "不禁火,民安作,平生无襦今五绔。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4394wx','骁','1','xiāo','马','9','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从马,尧声。本义:强壮的马) 同本义。", "cites": [{"t": "料武艺,品骁腾。", "b": "南朝宋·颜延之《赭白马赋》"}], "words": [{"w": "骁腾", "t": "骏马奔腾"}, {"w": "骁艺", "t": "马戏"}, {"w": "骁骑营", "t": "古代禁军营名。"}]}, {"meaning": "勇捷。", "cites": [{"t": "吴耿骁将,云集四境。", "b": "《后汉书·隗嚣传》"}, {"t": "虽骁勇,不可独任。", "b": "《三国志·袁绍传》"}], "words": [{"w": "骁烈", "t": "勇猛刚烈"}, {"w": "骁雄", "t": "勇猛雄武"}, {"w": "骁暴", "t": "勇猛凶暴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4395wx','骅','1','huá','马','9','','[{"pinyin": "huá", "defs": [{"meaning": "骏马名。", "cites": [{"t": "骅,骅骝,骏马。", "b": "《玉篇》"}, {"t": "骅骝开道路,鹰隼出风尘。", "b": "杜甫《奉简高三十五使君》"}]}]}]','jingmo-wenyan');
