INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4397wx','绛','1','jiàng','纟','9','','[{"pinyin": "jiàng", "defs": [{"meaning": "(形声。从糸(mì)。本义:大红色) 同本义。", "cites": [{"t": "绛,大赤也。", "b": "《说文》"}, {"t": "纁谓之绛。凡九旗之帛皆用绛。", "b": "《广雅》"}, {"t": "绛树在其南。", "b": "《淮南子·地形》"}, {"t": "纶组紫绛。", "b": "左思《吴都赋》"}, {"t": "绛皓驳色。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "绛帐", "t": "绛帏。红色帷帐;对师长之尊称"}, {"w": "绛脂", "t": "大红胭脂"}, {"w": "绛纱", "t": "红色的纱帐"}, {"w": "绛帻", "t": "大红色头巾。代指宫中侍卫人员"}, {"w": "绛节", "t": "红色符节。"}]}, {"meaning": "古都名。春秋晋地。", "cites": [{"t": "绛人也。", "b": "《国语·晋语》。注:“晋国都,在今山西绛县。”"}], "words": [{"w": "绛人", "t": "绛县的老人"}, {"w": "绛侯", "t": "指汉高祖刘邦的大臣周勃,他以功封绛侯,在铲除诸吕中起了重大作用"}, {"w": "绛老", "t": "本指春秋晋国绛县的老人,后泛指高寿的老年人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4398wx','骈','1','pián','马','9','','[{"pinyin": "pián", "defs": [{"meaning": "(形声。从马,并声。本义:两马并驾一车)。"}, {"meaning": "同本义。", "cites": [{"t": "骈,驾二马也。", "b": "《说文》"}, {"t": "然后得乘饰车骈马。", "b": "《尚书大传》"}, {"t": "骈驰翼驱。", "b": "嵇康《琴赋》"}], "words": [{"w": "骈马", "t": "二马并驾的车。"}]}, {"meaning": "并列。", "cites": [{"t": "骈死于槽枥之间。", "b": "唐·韩愈《马说》"}, {"t": "骈部曲。", "b": "班固《东都赋》"}], "words": [{"w": "骈集", "t": "肩并肩聚集"}, {"w": "骈田", "t": "并列连属。也作骈填,骈阗"}, {"w": "骈字", "t": "两字组成的词语,包括合义复词和衍声复词。如天地、自然、仿佛等"}, {"w": "骈化", "t": "并列化生。"}]}, {"meaning": "并联;合并。", "cites": [{"t": "曹共公闻其骈胁。", "b": "《左传·僖公二十三年》"}], "words": [{"w": "骈然", "t": "连接的样子"}, {"w": "骈胁", "t": "肋骨连接在一起"}, {"w": "骈骨", "t": "两骨相连"}, {"w": "骈干", "t": "胁骨相连"}, {"w": "骈石", "t": "两两相连的石头"}, {"w": "骈合", "t": "合并。"}]}, {"meaning": "胼胝,手掌脚底上的硬皮。", "cites": [{"t": "是故禹稷骈踬。", "b": "《孟子·滕文公下》"}]}, {"meaning": "文体名。见“骈文”（piánwén）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4399wx','耖','1','chào','耒','10','','[{"pinyin": "chào", "defs": [{"meaning": "在耕、耙地以后用的一种把土弄得更细的农具。", "cites": [{"t": "东阡西陌水潺湲,扶耖泥涂未得闲。", "b": "清·圣祖《题·耕图》"}]}, {"meaning": "用耖弄细土块。", "cites": [{"t": "耖,重耕田也。", "b": "《行韵》"}], "words": [{"w": "耖田;耖地", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4400wx','挈','1','qiè','手','10','','[{"pinyin": "qiè", "defs": [{"meaning": "契约,书契。", "cites": [{"t": "今内史稻田租挈重。", "b": "《汉书·沟洫志》"}, {"t": "书挈所录帝王遗事。", "b": "卫觊《魏受禅表》"}]}, {"meaning": "(形声。本义:提起)。"}, {"meaning": "同本义。", "cites": [{"t": "挈,县持也。", "b": "《说文》"}, {"t": "挈,提也。", "b": "《广雅》"}, {"t": "若挈裘领。", "b": "《荀子·劝学》"}, {"t": "挈壶氏。", "b": "《周礼》"}, {"t": "班白不提挈。", "b": "《礼记·王制》"}, {"t": "信挈其手。", "b": "《汉书·韩信传》"}, {"t": "龙尾车者,河滨挈水之器也。", "b": "《农政全书》"}], "words": [{"w": "挈瓶", "t": "谓提瓶汲水"}, {"w": "挈领", "t": "提起衣领"}, {"w": "提纲挈领;挈壶", "t": "悬壶"}, {"w": "挈辔", "t": "县辔。"}]}, {"meaning": "带领。", "cites": [{"t": "挈国之辞也。", "b": "《谷梁传·宣公十一年》"}, {"t": "挈其妻子以奔曹。", "b": "《谷梁传·襄公二十七年》"}, {"t": "元兵哨马报知蛮子海牙,他便挈兵而待。", "b": "《英烈传》"}, {"t": "挈家侨居邑东。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "喊一声,都拖男挈女,呼弟呼兄,一齐跑来。", "b": "《西游记》"}], "words": [{"w": "挈家", "t": "携家带眷"}, {"w": "挈累", "t": "携带家室"}, {"w": "挈眷", "t": "携带家眷"}, {"w": "挈囊", "t": "古代尚书携带的紫色袷囊称挈囊,因而也称掌文书之官为挈囊"}, {"w": "挈带", "t": "带领"}, {"w": "挈引", "t": "带领引导"}, {"w": "挈领", "t": "带领。"}]}, {"meaning": "提携。", "cites": [{"t": "况以两贤王左提右挈,而责杀王,灭燕易矣。", "b": "《汉书》"}], "words": [{"w": "挈带", "t": "提携"}, {"w": "挈扶", "t": "提携扶助"}, {"w": "挈提", "t": "提携,扶植"}, {"w": "挈维", "t": "提携护持"}, {"w": "挈携", "t": "提携;携带"}, {"w": "挈持", "t": "扶持。"}]}, {"meaning": "刻。", "cites": [{"t": "旦算祀于挈龟。", "b": "《汉书·叙传上》"}]}, {"meaning": "刀刻。", "cites": [{"t": "廷尉挈令。", "b": "《汉书·张汤传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4401wx','珥','1','ěr','王','10','','[{"pinyin": "ěr", "defs": [{"meaning": "中国古代的珠玉耳饰。", "cites": [{"t": "珥,珠在珥也。耳珰垂珠者曰珥。", "b": "《苍颉篇》。按,玉之似珠圆者。”"}, {"t": "傅玑之珥。", "b": "《史记·李斯传》"}, {"t": "设笄珥。", "b": "《列子·周穆王》"}]}, {"meaning": "日、月两旁的光晕,即位于太阳或月亮两侧并凸向太阳或月亮的光弧,与虹的片段相似,与晕相切。", "cites": [{"t": "月晕有两珥,白虹贯之。", "b": "《隋书》"}]}, {"meaning": "即日珥。", "cites": [{"t": "珥,气在日两旁之名也。珥,耳也,言似人耳之在两旁也。", "b": "《释名·释天》"}]}, {"meaning": "剑鼻。", "cites": [{"t": "抚长剑兮玉珥。", "b": "屈原《楚辞》"}]}, {"meaning": "贯耳。", "cites": [{"t": "神人珥两黄蛇。", "b": "《山海经·大荒东经》。注:“以蛇贯耳也。”"}], "words": [{"w": "珥貂", "t": "帽旁插貂尾为饰,借指做贵官"}, {"w": "珥笔", "t": "珥彤。入朝的官员帽插笔,以便随时记录。"}]}, {"meaning": "戴;插。", "cites": [{"t": "七叶珥汉貂。", "b": "左思《咏史诗》"}], "words": [{"w": "珥笔", "t": "史官。谏官或近臣侍从,把笔插在帽子上,以便随肘记录。"}]}, {"meaning": "古祭礼杀牲取血,以涂祭社器。", "cites": [{"t": "以岁时序其祭祀及其祈珥。", "b": "《周礼·春官·肆师》"}, {"t": "常珥于社稷,祈于五祀。", "b": "《周礼·夏官·小子》"}]}]}]','jingmo-wenyan');
