INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4416wx','埙','1','xūn','土','10','','[{"pinyin": "xūn", "defs": [{"meaning": "(形声。从土,熏声。本义:古代用陶土烧制的一种吹奏乐器,大小如鹅蛋,六孔,顶端为吹口。又叫“陶埙”) 同本义 。也有用石、骨、象牙制成的。", "cites": [{"t": "壎,乐器也。以土为之,六孔。", "b": "《说文》。字亦作塤。"}, {"t": "埙箫管。", "b": "《周礼·小师》。注:“大如雁卵。”"}, {"t": "调竽笙壎箎。", "b": "《礼记·月令》"}, {"t": "伯氏吹壎,仲氏吹箎。", "b": "《诗·小雅·何人斯》"}, {"t": "如壎如箎。", "b": "《诗·大雅·板》。注:“其声平下,与箎相谐。”"}, {"t": "礼乐壎坎音也。", "b": "《白虎通》"}, {"t": "凡六孔,上一、前三、后二。", "b": "《新定三礼图·投壶图·埙》"}], "words": [{"w": "埙箎", "t": "埙为土制乐器,篪为竹制乐器,埙篪合奏声音和谐。后用以表示兄弟和睦,也代指兄弟。"}]}]}]','jingmo-wenyan');
