INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4418wx','挹','1','yì','扌','10','','[{"pinyin": "yì", "defs": [{"meaning": "舀;酌。把液体盛出来。", "cites": [{"t": "挹,抒也。从手,邑声。", "b": "《说文》"}, {"t": "凡以器斟酌于水谓之挹。", "b": "《珠丛》"}, {"t": "弟子挹水而注之。", "b": "《荀子·宥坐》。注:“酌也。”"}, {"t": "维北有斗,不可以挹酒浆。", "b": "《诗·小雅·大东》"}, {"t": "法流湛寂,挹之莫测其源。", "b": "《西游记》"}], "words": [{"w": "挹受", "t": "汲取,承受"}, {"w": "挹盈", "t": "舀取盈满的液体"}, {"w": "挹酌", "t": "汲取"}, {"w": "挹彼注此(兹)(将彼器的液体倾注于此器", "t": ""}, {"w": "挹盈注虚", "t": "取有余以补不足"}, {"w": "挹掬", "t": "捧取"}, {"w": "挹斗扬箕", "t": "谓徒有虚名。"}]}, {"meaning": "引;牵引。", "cites": [{"t": "左挹浮丘袖,右拍洪崖肩。", "b": "晋·郭璞《游仙诗》"}, {"t": "接倾城之貌,挹希世之人。", "b": "《警世通言》"}], "words": [{"w": "挹胜", "t": "收取胜景"}, {"w": "挹慕", "t": "牵念,羡慕。"}]}, {"meaning": "抑制住。", "cites": [{"t": "富有四海,守之以谦,此所谓挹而损之之道也。", "b": "《荀子·宥坐》"}, {"t": "而久自挹损。", "b": "《三国志·诸葛亮传》"}, {"t": "情存损挹。", "b": "《后汉书·光武帝纪下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4419wx','耆','1','qí','耂','10','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。《说文》:“从老省,旨声。”形旁本是“老”,为了文字结构匀称,省略了一部分。本义:老)。"}, {"meaning": "古称六十岁曰耆。亦泛指寿考。", "cites": [{"t": "耆,老也。", "b": "《说文》"}, {"t": "六十曰耆。", "b": "《礼记·曲礼》"}, {"t": "耆老皆朝于庠。", "b": "《礼记·王制》"}, {"t": "耆耋好礼。", "b": "《礼记·射仪》"}, {"t": "俾尔耆而艾。", "b": "《诗·鲁颂·閟宫》"}], "words": [{"w": "耆艾", "t": "老人的通称"}, {"w": "耆叟", "t": "老叟"}, {"w": "耆寿耇老", "t": "长寿老人"}, {"w": "耆耇", "t": "老年人。耆为六十岁、耇为九十岁。"}]}, {"meaning": "强横的。", "cites": [{"t": "耆,强也。", "b": "《广雅》"}, {"t": "不懦不耆。", "b": "《左传·昭公二十三年》。注:“彊也。”"}], "words": [{"w": "耆帅", "t": "强横拔扈,作乱造反的将帅。"}]}, {"meaning": "（shì）。爱好。", "cites": [{"t": "五方之民,言语不通,耆欲不同。", "b": "《周礼·秋官·大行人》"}, {"t": "鸱鸮耆鼠。", "b": "《老子·齐物论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4420wx','耄','1','mào','耂','10','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从老,毛声。本义:年老)。"}, {"meaning": "同本义。古称大约七十至九十岁的年纪。", "cites": [{"t": "匪我言耄。", "b": "《诗·大雅·板》"}, {"t": "亦聿既耄。", "b": "《诗·大雅·抑》"}, {"t": "老夫耄矣,无能为也。", "b": "《左传·隐公四年》"}], "words": [{"w": "耄儿", "t": "老人和儿童"}, {"w": "耄年", "t": "老年"}, {"w": "耄老", "t": "老年,老年人"}, {"w": "耄荒", "t": "年老"}, {"w": "耄学", "t": "年耄硕学之士"}, {"w": "耄聩", "t": "年老糊涂"}, {"w": "耄勤", "t": "年老倦勤"}, {"w": "耄期", "t": "高年"}, {"w": "耄耋", "t": "八十岁的年龄;高龄,高寿"}, {"w": "耄儒", "t": "老儒。"}]}, {"meaning": "年老昏乱。", "cites": [{"t": "耄期倦于勤。", "b": "《书·大禹谟》"}], "words": [{"w": "耄思", "t": "思绪纷乱"}, {"w": "耄耄", "t": "纷乱貌"}, {"w": "耄乱", "t": "谓年老昏乱的人"}, {"w": "耄夫", "t": "年老昏庸之人"}, {"w": "耄昏", "t": "年老昏愦"}, {"w": "耄聩", "t": "年老糊涂"}, {"w": "耄朽", "t": "老朽;衰老"}, {"w": "耄衰", "t": "衰老。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4421wx','埒','1','liè','土','10','','[{"pinyin": "liè", "defs": [{"meaning": "(形声。从土，寽lǚ声。本义:矮墙)。"}, {"meaning": "同本义;特指马射场四周的土围墙。", "cites": [{"t": "埒,卑垣也。", "b": "《说文》"}, {"t": "山上有水埒。", "b": "《尔雅》。注:“有停泉。”"}, {"t": "弓如明月对堋,马似浮云向埒。", "b": "庾信《三月三日华林园马射赋》"}, {"t": "济(王济)好马射,买地作埒。", "b": "《世说新语》"}], "words": [{"w": "埒垣", "t": "围墙。"}]}, {"meaning": "山上的水流。", "cites": [{"t": "一源分为四埒,注于山下。", "b": "《列子·汤问》"}]}, {"meaning": "界限;边际。", "cites": [{"t": "水潦所还埒邱。", "b": "《尔雅·释丘》。注:“丘边有界,埒水绕环之。”按,埒有人为之者,有地自然者,皆曰埒。”"}], "words": [{"w": "埒亩", "t": "田亩。"}]}, {"meaning": "等同;并立;相比。", "cites": [{"t": "故吴诸侯也,以即山铸钱,富埒天子。", "b": "《史记·平准书》"}], "words": [{"w": "埒名", "t": "齐名"}, {"w": "埒美", "t": "比美;媲美"}, {"w": "埒略", "t": "比较区分。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4422wx','捋','1','luō lǚ','扌','10','','[{"pinyin": "luō", "defs": [{"meaning": "(形声。从手,寽(lǚ)声。“寽”,以五指持物,在字中表意。本义:手握着东西向一端抹取)。"}, {"meaning": "同本义。", "cites": [{"t": "武松捋起双袖,握起尖刀。", "b": "《水浒传》"}]}, {"meaning": "堆,垒。", "cites": [{"t": "这边堆着木料——檩子、柱子和椽子。那边捋着从各社员家收集的干土坯。——柳青《创业史》", "b": ""}]}]}, {"pinyin": "lǚ", "defs": [{"meaning": "(形声。从手,寽(lǚ)声。“寽”,以五指持物。本义:用手指顺着抹过去,使物体顺溜或干净)。"}, {"meaning": "同本义。", "cites": [{"t": "敢捋虎须。", "b": "清·纪昀《阅微草堂笔记》"}, {"t": "下担捋髭须。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "捋胡须;捋虎须", "t": "捋须。喻撩拨强有力者,谓冒风险"}, {"w": "捋须钱", "t": "敲诈来的钱"}, {"w": "捋顺了毛", "t": "顺首性子来"}, {"w": "捋闸下水", "t": "船舶超载"}, {"w": "捋舌捌哥", "t": "口舌伶俐。"}]}, {"meaning": "梳理;整理。", "cites": [{"t": "李世丹沉默了,心里好像塞了一团头发,扎扎挠挠,乱乱糟糟,裹不住,也捋不清。", "b": "浩然《艳阳天》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4423wx','贽','1','zhì','贝','10','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从贝,执声。从贝,与财富有关。本义:古时初次求见人时所送的礼物,见面礼) 同本义。", "cites": [{"t": "交贽往来。", "b": "《左传·成公十二年》"}, {"t": "出疆必执质(贽)。", "b": "《孟子》"}, {"t": "三帛、二生、一死贽。", "b": "《虞书》"}, {"t": "男贽,大者玉帛,小者禽鸟,以章物也;女贽,不过榛粟枣脩,以告虔也。", "b": "《左传·庄公二十四年》"}, {"t": "撰长书以为贽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "贽币", "t": "见面礼"}, {"w": "贽敬", "t": "备礼物来拜见,以表示敬重"}, {"w": "贽然", "t": "站立不动的样子"}, {"w": "贽宝", "t": "献赠的宝物"}, {"w": "贽献", "t": "献赠的礼物"}, {"w": "贽礼", "t": "见面礼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4424wx','垸','1','yuàn','土','10','','[{"pinyin": "yuàn", "defs": [{"meaning": "湖南、湖北等地,在沿江、湖地带围绕房屋、田地等修建的堤坝样防水建筑物 。通称“垸子”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4425wx','捃','1','jùn','扌','10','','[{"pinyin": "jùn", "defs": [{"meaning": "拾,捡", "words": [{"w": "捃刀", "t": "拾取麦穗的农具"}, {"w": "捃拾", "t": "拾取；收集"}, {"w": "捃收", "t": "收集"}]}, {"meaning": "取", "words": [{"w": "捃采", "t": "采集"}, {"w": "招摭", "t": "采取；拾取当道者之言隋声附和"}, {"w": "捃摘", "t": "采集,摘取"}]}, {"meaning": "指收集材料以打击别人。引申指弹劾", "words": [{"w": "捃摭", "t": "指搜罗材料以打击别人"}, {"w": "捃诬", "t": "搜罗材料加以诬陷"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4426wx','盍','1','hé','皿','10','','[{"pinyin": "hé", "defs": [{"meaning": "(会意。本作“盇”,从血,从大。段玉裁《说文解字注》:“皿中有血而上覆之,覆必大于下,故从大。”本义:覆盖) 合。", "cites": [{"t": "盍簪喧枥马,列炬散林鸦。", "b": "杜甫《杜位宅守岁》"}], "words": [{"w": "盍簪", "t": "友人聚会;朋友"}, {"w": "盍朋簪", "t": "朋友聚会"}, {"w": "盍彻", "t": "施行仁政。"}]}, {"meaning": "何不(盍是“何不”的合音)。", "cites": [{"t": "盍,何不也。", "b": "《玉篇》"}, {"t": "盍请济师于王?", "b": "《左传·桓公十一年》"}, {"t": "子盍从众?", "b": "《左传·成公六年》"}, {"t": "子盍诘盗?", "b": "《左传·襄公二十一年》"}, {"t": "盍杀我?", "b": "《国语·晋语一》"}, {"t": "盍反其本。", "b": "《孟子·梁惠王上》"}, {"t": "祭酒计甚善,王盍用之?", "b": "《新唐书》"}, {"t": "盍驰往油画院。", "b": "清·薛福成《观巴黎油画记》"}]}, {"meaning": "为何;什么;怎么。", "cites": [{"t": "盍不为行?", "b": "《庄子·盗跖》"}], "words": [{"w": "盍如", "t": "何如。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4427wx','荸','1','bí','艹','10','','[{"pinyin": "bí", "defs": [{"meaning": "多年生草本植物，通常栽培在水田里。其地下茎也叫荸荠，扁圆形，皮赤褐色或黑褐色，肉白色，可食。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4428wx','莆','1','pú','艹','10','','[{"pinyin": "pú", "defs": [{"meaning": "水草名。即“蒲草 ”。", "cites": [{"t": "咸播秬黍,莆雚是营。", "b": "《楚辞·天问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4429wx','莳','1','shì shí','艹','10','','[{"pinyin": "shì", "defs": [{"meaning": "移栽。", "cites": [{"t": "莳,更别种也。从草,时声。", "b": "《说文》"}, {"t": "莳,种也。", "b": "《广雅》。按,分秧匀插莳。"}, {"t": "播时百谷,以时为之。", "b": "《虞书》"}, {"t": "秧根未牢莳未匝,照管鹅儿与雏鸭。", "b": "杨万里《插秧歌》"}], "words": [{"w": "莳秧", "t": "插秧。"}]}, {"meaning": "栽种。", "cites": [{"t": "庐下莳杂花。", "b": "王夫之《小云山记》"}], "words": [{"w": "莳树", "t": "栽树。"}]}]}, {"pinyin": "shí", "defs": [{"meaning": "多年生草本植物，果实椭圆形，可做香料，亦称‘小茴香’。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4430wx','莴','1','wō','艹','10','','[{"pinyin": "wō", "defs": [{"meaning": "一年生或二年生草本植物，茎和嫩叶都是普通的蔬菜。分叶用和茎用两种，叶用的亦称\\"生菜\\"；茎用的亦称\\"莴笋\\"。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4431wx','莪','1','é','艹','10','','[{"pinyin": "é", "defs": [{"meaning": "莪蒿(多年生草本植物。叶像针,花黄绿色,生在水边。嫩茎叶可作蔬菜。也叫萝、萝蒿、廪蒿,俗称抱娘蒿)。", "cites": [{"t": "莪,萝莪蒿属,从草,我声。", "b": "《说文》"}, {"t": "菁菁者莪,在彼中阿。", "b": "《诗·小雅·菁菁者莪》"}]}, {"meaning": "蘑菇的别名。", "cites": [{"t": "中原呼菌为蘑菇,又为莪。", "b": "王祯《农书·百谷谱·蔬属》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4432wx','莠','1','yǒu','艹','10','','[{"pinyin": "yǒu", "defs": [{"meaning": "(形声。从艸,秀声。恶草的通称,常用以比喻恶人、俚人)。"}, {"meaning": "草名,即“狗尾草” 。一年生草本植物,样子很像谷子。", "cites": [{"t": "莠,禾粟下扬生莠。", "b": "《说文》。按,禾粟之穗,生而未成,坠地生莠。今之狗尾草,即董蓈也。"}, {"t": "惟莠骄骄。", "b": "《诗·齐风·甫田》"}]}, {"meaning": "品质坏的、不好的人。", "cites": [{"t": "好言自口,莠言自口。", "b": "《诗·小雅·正月》"}], "words": [{"w": "良莠不齐", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4433wx','莓','1','méi','艹','10','','[{"pinyin": "méi", "defs": [{"meaning": "苔藓。蔷薇科悬钩子属、蛇莓属植物的泛称  。灌木或多年生草本。果实可食", "words": [{"w": "草莓", "t": ""}, {"w": "蛇莓", "t": ""}, {"w": "莓苔", "t": "青苔。即苔莓"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4434wx','莜','1','yóu','艹','10','','[{"pinyin": "yóu", "defs": [{"meaning": "一年生草本植物，种子可磨成面供食用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4435wx','莅','1','lì','艹','10','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从艸,位声。从立,隶声。本义:走到近处察看)。"}, {"meaning": "同本义。", "cites": [{"t": "涖,视也。", "b": "《尔雅》"}, {"t": "宿眂涤濯,莅玉鬯。", "b": "《周礼·春官》"}]}, {"meaning": "治理;统治;管理。", "cites": [{"t": "刁莅事三年。", "b": "《韩非子·十过》"}, {"t": "楚庄王莅政三年。", "b": "《韩非子·喻老》"}, {"t": "莅中国而抚四夷也。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "莅官", "t": "官员到任"}, {"w": "莅会", "t": "到会"}, {"w": "莅政", "t": "莅正。掌管政事"}, {"w": "莅民", "t": "管理百姓。"}]}, {"meaning": "来;到。", "cites": [{"t": "方叔莅止,其车三千。", "b": "《诗·小雅·采芑》"}, {"t": "今年蒞淮海。", "b": "王禹偁《扬州寒食赠屯田张员外》"}, {"t": "故君子不得已而临莅天下。", "b": "《庄子·在宥》"}, {"t": "矜庄以莅之。", "b": "《荀子·非相》"}, {"t": "以道莅天下,其鬼不神。", "b": "《老子》"}, {"t": "吾子将莅之。", "b": "《仪礼·士冠礼》"}], "words": [{"w": "莅止", "t": "来到"}, {"w": "莅临", "t": "亲自到达。多指为政者或上级官吏的到来。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4436wx','荼','1','shū tú','艹','10','','[{"pinyin": "shū", "defs": [{"meaning": "玉板,古朝会时所执。", "cites": [{"t": "天子御珽,诸侯御荼,大夫服笏,礼也。", "b": "《荀子·大略》"}]}]}, {"pinyin": "tú", "defs": [{"meaning": "(形声。从艸,余声。本义:一种苦菜)。"}, {"meaning": "同本义。苣菜属和莴苣属植物。", "cites": [{"t": "荼,苦菜。", "b": "《尔雅·释草》"}, {"t": "谁谓荼苦?", "b": "《诗·邶风·谷风》。传:“荼,苦菜也。”"}], "words": [{"w": "荼蓼", "t": "荼是苦菜,蓼是辛菜。皆是秽草。也用以形容处境的艰辛"}, {"w": "荼荠", "t": "荼、荠皆菜名。荼味苦,荠味甘,因以“荼荠”喻小人与君子。"}]}, {"meaning": "白色。", "cites": [{"t": "荼首之孙。", "b": "《管子》"}]}, {"meaning": "刘绩补注:“荼首,白首也。”。"}, {"meaning": "杂草。", "cites": [{"t": "其镈斯赵,以薅荼蓼。", "b": "《诗·周颂》"}]}, {"meaning": "", "cites": [{"t": "况在秦陇荼炭之余,直是老臣尽效之会。", "b": "《魏书·卢水胡沮渠蒙逊传》"}, {"t": "天子悼兆民之荼炭。", "b": "东魏《敬史君碑》"}], "words": [{"w": "荼炭", "t": "比喻极度痛苦。通“涂炭”。"}]}, {"meaning": "借。", "cites": [{"t": "荼,借也。", "b": "《广雅》。王念孙疏证:“荼盖赊之借字,赊荼古音相近。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4437wx','莩','1','fú piǎo','艹','10','','[{"pinyin": "fú", "defs": [{"meaning": "莩草 。禾本科。多年生草本。茎细长,高一米许。叶片扁平,条状披针形。", "cites": [{"t": "莩,莩草也。", "b": "《说文》张舜徽注:"}, {"t": "“莩此草生湖地,色淡白,可以盖屋,湖、湘间平野亦多有之。”", "b": ""}]}, {"meaning": "植物茎杆里的白膜或种子的外皮。", "cites": [{"t": "朱实虽先熟,琼莩纵早开,流莺故犹在,争得讳含来。", "b": "唐·李商隐《百果嘲樱桃》"}], "words": [{"w": "莩甲", "t": "种子脱去皮壳而萌发。"}]}]}, {"pinyin": "piǎo", "defs": [{"meaning": "", "cites": [{"t": "狗彘食人食而不知检,涂有饿莩而不知发。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "饿莩", "t": "饿死的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4438wx','荽','1','sui','艹','10','','[{"pinyin": "sui", "defs": [{"meaning": "—“芫荽”（yánsui）:一年生草本植物,通称“香菜”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
