INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4440wx','荻','1','dí','艹','10','','[{"pinyin": "dí", "defs": [{"meaning": "多年生草本植物,生在水边,叶子长形,似芦苇,秋天开紫花。", "cites": [{"t": "浔阳江头夜送客,枫叶荻花秋瑟瑟。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "荻画", "t": "用荻杆在地上画画写字"}, {"w": "荻竹", "t": "即荻"}, {"w": "荻苗", "t": "荻的花穗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4441wx','莘','1','shēn xīn','艹','10','','[{"pinyin": "shēn", "defs": [{"meaning": "众多的样子。", "cites": [{"t": "莘莘征夫。", "b": "《国语·晋语》。注:“莘莘,众多。”"}, {"t": "莘莘将将。", "b": "枚乘《七发》。注:“莘莘,多貌也。”"}, {"t": "祸之长也兹莘。", "b": "《庄子·徐无鬼》。释文引李注:“莘,多也。”"}], "words": [{"w": "莘莘", "t": ""}]}, {"meaning": "长。", "cites": [{"t": "有莘其尾。", "b": "《诗·小雅·鱼藻》。毛传: 莘, 长貌。"}]}, {"meaning": "姓。"}]}, {"pinyin": "xīn", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4442wx','莎','1','shā suō','艹','10','','[{"pinyin": "shā", "defs": [{"meaning": "莎鸡,虫名。即“纺织娘”。别名为“莎虫”。学名“螽斯”。", "cites": [{"t": "六月莎鸡振羽。", "b": "《诗·豳风·七月》"}]}]}, {"pinyin": "suō", "defs": [{"meaning": "(形声。从艸,沙声。本义:草名。香附子)。"}, {"meaning": "同本义。", "cites": [{"t": "莎,镐侯也。", "b": "《说文》。亦名沙隨,一名地毛,其实附根而生,谓之缇。即今香附子。"}, {"t": "薜莎青薠。", "b": "《汉书·司马相如传》"}, {"t": "青鞦莎靡。", "b": "潘岳《射雉赋》"}, {"t": "田无立禾,路无莎薠。", "b": "《淮南子·览冥》"}], "words": [{"w": "莎池", "t": "周围长有莎草的水池"}, {"w": "莎岸", "t": "长着莎草的岸边"}, {"w": "莎洲", "t": "长有莎草的水洲"}, {"w": "莎香", "t": "莎草的香气"}, {"w": "莎庭", "t": "长满莎草的庭院"}, {"w": "莎径", "t": "长满莎草的小路"}, {"w": "莎阶", "t": "长满莎草的台阶"}, {"w": "莎台", "t": "长着莎草的楼台。"}]}, {"meaning": "花叶脱落,凋谢。", "cites": [{"t": "尔杞未棘,尔菊未莎,其如予何,其如予何。", "b": "唐·陆龟蒙《杞菊赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4443wx','莞','1','guān guǎn wǎn','艹','10','','[{"pinyin": "guān", "defs": [{"meaning": "(形声。从艸,完声。本义:俗名水葱、席子草。亦指用莞草织的席子)。"}]}, {"pinyin": "guǎn", "defs": [{"meaning": "——“东莞”(Dōngguǎn):市名,在广东省东江下游。"}]}, {"pinyin": "wǎn", "defs": [{"meaning": "微笑。", "cites": [{"t": "浙酒二樽,少助待客之需。希莞纳,幸甚。", "b": "《金瓶梅》"}], "words": [{"w": "莞纳", "t": "笑纳"}, {"w": "莞收", "t": "笑着收下。"}]}, {"meaning": "胃的内腔。", "cites": [{"t": "寒气在胃莞。", "b": "《武威汉代医简》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4444wx','莨','1','láng làng liáng','艹','10','','[{"pinyin": "láng", "defs": [{"meaning": "狼尾草 。一种多年生草本植物。秋冬茎顶抽紫黑色具刚毛穗状圆锥花序,形似狼尾。嫩时作饲料。", "cites": [{"t": "莨,莨草也。从草,良声。", "b": "《说文》"}, {"t": "其卑湿则生藏莨。", "b": "《史记·司马相如传》"}], "words": [{"w": "莨尾", "t": "植物名。即狗尾草"}, {"w": "莨莠", "t": "莨和莠,是两种野草。常用以喻邪恶之人,或用以指杂草丛生的地方。"}]}]}, {"pinyin": "làng", "defs": []}, {"pinyin": "liáng", "defs": [{"meaning": "——“薯莨”(shǔliáng):薯蓣科多年生缠绕藤本。地下具块茎,内含胶质,可作染料。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4445wx','鸪','1','gū','鸟','10','','[{"pinyin": "gū", "defs": [{"meaning": "“鹧鸪”(zhègū):鸟名。“鹁鸪”(bógū):鸟名。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4446wx','莼','1','chún','艹','10','','[{"pinyin": "chún", "defs": [{"meaning": "莼菜。亦名“水葵” 。一种水生植物,飘浮叶的上面呈橄榄绿色,下面红色,所有水下部分都有一层凝结胶质覆盖。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4447wx','栲','1','kǎo','木','10','','[{"pinyin": "kǎo", "defs": [{"meaning": "木名。即山樗。常绿乔木,叶子长圆状,披针形,果实球形,表面有短刺,木材坚硬细密,可做轮轴等,树皮含鞣酸,可制染料与栲胶。", "cites": [{"t": "山有栲,隰有杻。", "b": "《诗·唐风·山有枢》"}]}]}]','jingmo-wenyan');
