INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4450wx','桓','1','huán','木','10','','[{"pinyin": "huán", "defs": [{"meaning": "(形声。从木,亘(xuān)声。本义:表柱。古代立在驿站、官署等建筑物旁作标志的木柱,后称华表)。"}, {"meaning": "同本义,后也泛指寺、墓、桥梁等用作表识或其他用途的柱子。", "cites": [{"t": "桓,亭邮表也。", "b": "《说文》"}, {"t": "三家视桓楹。", "b": "《礼记·檀弓》。注:“四植谓之桓。”"}, {"t": "公执桓圭。", "b": "《周礼·大宗伯》。注:“双植谓之桓。桓宫室之象,所以安其上也。”"}], "words": [{"w": "桓楹", "t": "古代天子,诸侯葬时下棺所植的大柱子"}, {"w": "桓表", "t": "即华表。"}]}, {"meaning": "木名。即无患木 。叶似柳,皮黄白色。"}, {"meaning": "水名。即今白龙江 。发源于甘肃省西倾山。"}, {"meaning": "大。", "cites": [{"t": "玄王桓拨。", "b": "《诗·商颂·长发》。传:“大也。”"}], "words": [{"w": "桓蒲", "t": "祭祀用的大蒲席"}, {"w": "桓拨", "t": "谓大治。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4451wx','桡','1','ráo','木','10','','[{"pinyin": "ráo", "defs": [{"meaning": "曲木;木头弯曲;泛指弯曲。", "cites": [{"t": "桡,曲木。从木,荛声。", "b": "《说文》"}, {"t": "栋桡。", "b": "《易·大过》"}, {"t": "竿木桡。", "b": "《列子·汤问》"}, {"t": "桡之以视其鸿杀之称也。", "b": "《考工记·矢人》"}], "words": [{"w": "桡木", "t": "曲木。使木弯曲"}, {"w": "桡曲", "t": "弯曲曲木。"}]}, {"meaning": "屈服。", "cites": [{"t": "重死持义而不桡,是士君子之勇也。", "b": "《荀子》"}], "words": [{"w": "桡辞", "t": "屈服的言词。"}]}, {"meaning": "屈弱,削弱。", "cites": [{"t": "上已桡功臣。", "b": "《史记·萧相国世家》"}, {"t": "汉王恐忧,与郦食其谋桡楚权。", "b": "《史记·留侯世家》"}], "words": [{"w": "桡败", "t": "挫败"}, {"w": "桡折", "t": "摧折。"}]}, {"meaning": "柔弱长艳。", "cites": [{"t": "柔桡嫚嫚,妩媚纤弱。", "b": "司马相如《上林赋》"}]}, {"meaning": "船桨。", "cites": [{"t": "夫七尺之桡而制船之左右者,以木为资。", "b": "《淮南子·主术》"}, {"t": "舟人依命,将船放到亭边,停桡稳缆。", "b": "《警世通言》"}, {"t": "楫谓之桡。", "b": "《方言·九》"}, {"t": "薜荔柏兮蕙绸,荪桡兮兰旌。", "b": "《楚辞·湘君》。王逸注:“桡,船小楫也。”"}], "words": [{"w": "桡楫", "t": "船桨"}, {"w": "桡贩子", "t": "受雇为人划桨的船工。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4452wx','桎','1','zhì','木','10','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从木,至声。本义:古代拘系罪人的木制脚镣) 同本义。", "cites": [{"t": "桎,足械也。", "b": "《说文》。在手曰梏。"}, {"t": "九家坎为桎梏。", "b": "《易·说卦》。注:“手足各一木也。”"}, {"t": "利用刑人,用说桎梏。", "b": "《易·蒙》"}, {"t": "中罪桎梏。", "b": "《周礼·秋官·掌囚》。郑玄注:“在手曰梏,在足曰桎。”"}, {"t": "命有司省囹圄,去桎梏。", "b": "《吕氏春秋·仲春》"}], "words": [{"w": "桎拲", "t": "刑具。拲,两手手铐。"}]}, {"meaning": "给脚带上刑具。", "cites": [{"t": "帝乃梏之疏属之山,桎其右足。", "b": "《山海经·海内北经》"}]}, {"meaning": "束缚,约束。", "cites": [{"t": "指与物化而不以心稽,故其灵台一而不桎。", "b": "《庄子·达生》"}, {"t": "儒学自桎。", "b": "《晋书》"}], "words": [{"w": "桎槛", "t": "囚禁,囚于槛车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4453wx','桢','1','zhēn','木','10','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从木,贞声。本义:木名,即女贞)。"}, {"meaning": "同本义。", "cites": [{"t": "桢,刚木也。", "b": "《说文》"}, {"t": "文欀桢橿。", "b": "左思《吴都赋》。注:“桢、橿,二木名。”"}, {"t": "又东二百里,曰太山,上多金玉、桢木。", "b": "《山海经》"}]}, {"meaning": "古代筑墙时竖立在两端的木柱。", "cites": [{"t": "桢,干也。", "b": "《尔雅》。舍人注:“桢,正也。筑墙所立两木也。”按,植于两端者曰桢,植于两边者曰干。"}, {"t": "维周之桢。", "b": "《诗·大雅·文王》"}], "words": [{"w": "桢干", "t": ""}]}, {"meaning": "支柱,主干。", "cites": [{"t": "峙乃桢干。", "b": "《书·费誓》传:“题曰桢。”"}], "words": [{"w": "桢臣", "t": "栋梁之臣"}, {"w": "桢材", "t": "干才"}, {"w": "桢固", "t": "支柱;骨干。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4454wx','桤','1','qī','木','10','','[{"pinyin": "qī", "defs": [{"meaning": "桤树 。桤木属的一种落叶乔木,叶长椭圆形,边缘有稀疏锯齿,柔荑花序,雌雄同株,果穗悬垂,木材坚韧,产于中国四川、贵州和陕西。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4455wx','梃','1','tǐng tìng','木','10','','[{"pinyin": "tǐng", "defs": [{"meaning": "棍棒。", "cites": [{"t": "梃,杖也。", "b": "《广雅·释器》。朱骏声曰:“竹曰竿,草曰莛,木曰梃。”"}, {"t": "杀人以梃与刃,有以异乎?", "b": "《孟子·梁惠王上》"}], "words": [{"w": "梃刃", "t": "棍棒与刀"}, {"w": "梃棒", "t": "棍棒"}, {"w": "梃击", "t": "用棍棒殴击。"}]}, {"meaning": "指门框、窗框或门扇、窗扇两侧直立的边框 。", "words": [{"w": "门梃;窗梃", "t": ""}]}, {"meaning": "竿状物的计量单位,相当于“杆”、“支”。", "cites": [{"t": "甘蔗百梃。", "b": "《魏书》"}]}]}, {"pinyin": "tìng", "defs": [{"meaning": "屠宰猪后,为了除毛,在猪的腿上割一个口子,用铁棍贴着腿皮往里捅,再往里吹气,使猪皮绷紧。"}, {"meaning": "往猪皮内捅的铁棍。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4456wx','栝','1','guā kuò','木','10','','[{"pinyin": "guā", "defs": [{"meaning": "箭末扣弦处。", "cites": [{"t": "其发若机栝。", "b": "《庄子·齐物论》"}, {"t": "故铭其栝曰:“肃慎氏之贡矢。”", "b": "《国语·鲁语下》"}], "words": [{"w": "箭栝", "t": ""}]}, {"meaning": "栝蒌 。即栝楼。"}]}, {"pinyin": "kuò", "defs": [{"meaning": "箭末扣弦处。", "cites": [{"t": "弓无弦,箭无栝。", "b": "《乐府诗集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4457wx','桕','1','jiù','木','10','','[{"pinyin": "jiù", "defs": [{"meaning": "乌桕 。一种落叶乔木,叶子互生,略呈菱形,秋天变红,花单性,雌雄同株,种子的外面有白蜡层,用来制造蜡烛。叶子可以做黑色染料。树皮、叶均可入药,有解毒、利尿等作用。"}, {"meaning": "桕脂。", "cites": [{"t": "阶走枫林叶,窗催桕烛花。", "b": "宋·慕容百才诗"}]}, {"meaning": "旧式门上合榫的槽。", "cites": [{"t": "两个正是推门入桕。", "b": "《警世通言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4458wx','桁','1','háng héng','木','10','','[{"pinyin": "háng", "defs": [{"meaning": "古代用于加在囚犯颈部的一种木刑具", "words": [{"w": "桁杨刀锯", "t": "各种刑具"}]}, {"meaning": "浮桥", "words": [{"w": "浮桥", "t": "浮桥"}]}]}, {"pinyin": "héng", "defs": [{"meaning": "梁上或门框、窗框等上的横木。", "cites": [{"t": "屋桁,屋横木也。", "b": "《玉篇》"}, {"t": "桁梧复叠。", "b": "《文选·曹植·洛神赋》。注:“桁,梁上所施也。”"}], "words": [{"w": "桁架", "t": ""}]}, {"meaning": "葬具。长而矮的木几,用来摆设陪葬的明器,埋入圹内。", "cites": [{"t": "皆木桁,久之。", "b": "《礼仪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4459wx','桧','1','guì huì','木','10','','[{"pinyin": "guì", "defs": [{"meaning": "即圆柏 。一种常绿乔木(Sabina chinensis或Juniperus chinensis),叶有鳞形和刺形两种,雌雄异株,果实球形,木材桃红色、有香气。"}]}, {"pinyin": "huì", "defs": [{"meaning": "", "words": [{"w": "秦桧", "t": ""}]}]}]','jingmo-wenyan');
