INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4463wx','栩','1','xǔ','木','10','','[{"pinyin": "xǔ", "defs": [{"meaning": "(形声。从木,羽声。亦称“杼”。本义:即柞木) 同本义。", "cites": [{"t": "集于苞栩。", "b": "《诗·唐风·鸨羽》"}]}, {"meaning": "栩栩。", "cites": [{"t": "栩栩然胡蝶也。", "b": "《庄子·齐物论》"}, {"t": "一枕香迷,蝶栩向西园,余情更苦。", "b": "周保绪《玉京秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4464wx','逑','1','qiú','辶','10','','[{"pinyin": "qiú", "defs": [{"meaning": "(形声。从辵(chuò),求声。本义:聚合)。"}, {"meaning": "同本义。", "cites": [{"t": "逑,敛聚也。", "b": "《说文》"}, {"t": "惠此中国,以为民逑。", "b": "《诗·大雅·民劳》"}]}, {"meaning": "匹配。", "cites": [{"t": "有虞信莫京兮,余可以以为逑。", "b": "明·方孝儒《静学斋赋》"}]}, {"meaning": "配偶。", "cites": [{"t": "窈窕淑女,君子好逑。", "b": "《诗·周南·关雎》"}], "words": [{"w": "逑匹", "t": "配偶"}, {"w": "逑耦", "t": "匹偶,搭档。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4465wx','逋','1','bū','辶','10','','[{"pinyin": "bū", "defs": [{"meaning": "(形声。从辵(chuò),甫声。逋的原始意义是奴隶逃亡。本义:逃亡,逃跑)。"}, {"meaning": "同本义。", "cites": [{"t": "逋,亡也。", "b": "《说文》"}, {"t": "乃惟四方之多罪逋逃,是崇是长。", "b": "《书·牧誓》"}, {"t": "于伐殷逋播臣。", "b": "《书·大诰》"}, {"t": "为天下逋逃主。", "b": "《书·武臣》"}, {"t": "六年其逋。", "b": "《左传·僖公十五年》"}, {"t": "狼失声而逋。", "b": "明·马中锡《中山狼传》"}], "words": [{"w": "逋臣", "t": "逃亡的大臣"}, {"w": "逋逃薮", "t": "逃亡的罪犯或流亡者聚集的地方"}, {"w": "逋客", "t": "逃亡的人;避世的人。"}]}, {"meaning": "拖欠,欠税。", "cites": [{"t": "逋租宿债勿复收。", "b": "沈约《宋书》"}], "words": [{"w": "逋债", "t": "拖延付债"}, {"w": "逋租", "t": "拖欠租税。"}]}, {"meaning": "懈怠;拖延。", "cites": [{"t": "久逋王命。", "b": "房玄龄《晋书·蔡谟传》"}], "words": [{"w": "逋壅", "t": "拖延积压"}, {"w": "逋慢", "t": "怠慢不敬;不遵法令。"}]}, {"meaning": "逃亡者。", "cites": [{"t": "可以怀远,可以柔逋。", "b": "《晋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4466wx','彧','1','yù','彡','10','','[{"pinyin": "yù", "defs": [{"meaning": "趣味高雅的,谈吐文雅的,有文采,有教养。", "cites": [{"t": "彧,文也。", "b": "《广雅》"}, {"t": "夏伯之乐舞谩彧。", "b": "《书·大传》。注:“长貌。言万物之滋曼彧然也。”"}]}, {"meaning": "茂盛。", "cites": [{"t": "疆场翼翼,黍稷彧彧。", "b": "《诗·小雅·信南山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4467wx','鬲','1','gé lì','鬲','10','','[{"pinyin": "gé", "defs": [{"meaning": "横隔膜。", "cites": [{"t": "食饮不下,鬲塞不通。", "b": "《素问·风论篇》"}], "words": [{"w": "针鬲", "t": "用针刺横膈膜"}, {"w": "鬲要", "t": "膈腰。指心胸"}, {"w": "鬲肝", "t": "膈和肝。"}]}, {"meaning": "大车轭。", "cites": [{"t": "鬲长六尺。", "b": "《周礼·考工记》。孙诒让正义:“鬲,即槅之借字。”"}]}, {"meaning": "县名 。汉置。在今山东省德州市东南。"}, {"meaning": "。发源于河北,流入山东。"}, {"meaning": "阻隔。", "cites": [{"t": "鬲闭门户,毋得擅上。", "b": "《汉书·五行志中》"}, {"t": "别异蛮夷,鬲绝器物。", "b": "《汉书·南越王赵佗传》"}], "words": [{"w": "鬲闭", "t": "隔离闭塞"}, {"w": "鬲咽", "t": "因消化器官阻塞而下咽困难"}, {"w": "鬲塞", "t": "阻塞"}, {"w": "鬲蔽", "t": "阻隔"}, {"w": "鬲绝", "t": "隔断"}, {"w": "鬲子", "t": "格子。"}]}]}, {"pinyin": "lì", "defs": [{"meaning": "(象形。金文字形,象饮食器具形。本义:古代炊器。用于烧煮或烹炒的锅,特指类似于鼎状的炊具) 同本义。", "cites": [{"t": "古鼎中有三足皆空,中可容物者,所谓鬲也。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "鬲如", "t": "形状突起高绝如鬲鼎的样子。"}]}]}]','jingmo-wenyan');
