INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4471wx','厝','1','cuò','厂','10','','[{"pinyin": "cuò", "defs": [{"meaning": "(形声。从厂(hǎn),昔声。“厂”,象山崖形。本义:磨刀石)。"}, {"meaning": "同本义。一说相当于现在的金刚钻。", "cites": [{"t": "厝,厉石也。", "b": "《说文》。"}, {"t": "佗山之石,可以为厝。", "b": "《诗·小雅·鹤鸣》"}]}, {"meaning": "安置,措置。", "cites": [{"t": "故书则必如将废厝。", "b": "《考工记·梓人》"}, {"t": "抱火厝积薪之下。", "b": "《汉书·贾谊传》"}, {"t": "帝感其诚,命夸娥氏二子负二山,一厝朔东,一厝雍南。", "b": "《列子·汤问》"}], "words": [{"w": "厝顿", "t": "处置;安顿"}, {"w": "厝生", "t": "安身;谋生"}, {"w": "厝火燎原", "t": "放火燎原,喻小乱子酿成大祸患。"}]}]}]','jingmo-wenyan');
