INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4475wx','砺','1','lì','石','10','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从石,厉声。本义:粗磨刀石) 同本义。", "cites": [{"t": "阴山多砺石。", "b": "《山海经·中山经》"}, {"t": "刀砺。", "b": "《礼记·内则》"}, {"t": "金就砺则利。", "b": "《荀子·劝学》"}], "words": [{"w": "砺石", "t": "可作磨刀石和石磨的一种粗石;泛指粗石"}, {"w": "砺砥", "t": "磨刀石。"}]}, {"meaning": "引申为磨。", "cites": [{"t": "胜自砺剑。", "b": "《史记·伍子胥列传》"}], "words": [{"w": "砺剑", "t": "磨剑"}, {"w": "砺砥", "t": "磨刀石"}, {"w": "砺戈秣马", "t": "磨戈喂马"}, {"w": "砺兵", "t": "磨快兵器。"}]}, {"meaning": "钻研;磨炼。", "cites": [{"t": "纪僧珍砥节砺行,终始无瑕。", "b": "《史通·品藻》"}, {"t": "钻砺过分,则神疲而气衰。", "b": "《文心雕龙·养气》"}]}, {"meaning": "又如;砺淬(刻苦磨炼);砺志(励志;锐意)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4476wx','砧','1','zhēn','石','10','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从石,占声。本义:捣衣石)。"}, {"meaning": "同本义。", "cites": [{"t": "秋至式清砧。", "b": "杜甫《捣衣》"}], "words": [{"w": "砧杵", "t": "捣衣石和棒槌"}, {"w": "砧石", "t": "捣衣石"}, {"w": "砧声", "t": "捣衣声。又指。"}]}, {"meaning": "切物用的砧板。", "cites": [{"t": "加以砧斧。", "b": "韩愈《元和圣德》"}, {"t": "饿猫临鼠穴,馋犬舐鱼砧。", "b": "唐·卢延让逸句"}], "words": [{"w": "砧几", "t": "砧板"}, {"w": "砧臼", "t": "砧板和石臼。"}]}, {"meaning": "捣草石。", "cites": [{"t": "砧,农家捣草石。", "b": "《正字通》"}]}, {"meaning": "泛指物体下部的垫基。", "cites": [{"t": "造门砧之制,长三尺五寸。", "b": "《营造法式》"}]}, {"meaning": "捣衣声。", "cites": [{"t": "月明遥听远村砧。", "b": "唐·刘沧《秋日山寺怀友人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4477wx','砷','1','shēn','石','10','','[{"pinyin": "shēn", "defs": [{"meaning": "一种三价和五价的非金属元素,旧称“砒”。通常呈金属的铁灰色,结晶形,性脆。砷常小量地被掺入合金(如用于制造子弹的砷-铅合金),其化合物主要用于制造毒剂(如杀虫剂)、药物和玻璃 ——元素符号As。"}]}]','jingmo-wenyan');
