INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4480wx','砥','1','dǐ','石','10','','[{"pinyin": "dǐ", "defs": [{"meaning": "(形声。从石,氐(dǐ)声。本义:质地很细的磨刀石)同本义。", "cites": [{"t": "则字平如砥。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "砥石", "t": "磨刀石"}, {"w": "砥磨", "t": "在磨刀石上磨。"}]}, {"meaning": "引申为磨。", "cites": [{"t": "晋人已胜智氏,归而缮甲砥兵。", "b": "汉·刘向《说苑》"}], "words": [{"w": "砥刃", "t": "磨利兵器"}, {"w": "砥钝", "t": "磨钝成利"}, {"w": "缮甲砥兵", "t": ""}]}]}]','jingmo-wenyan');
