('4481wx','砣','1','tuó','石','10','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从石,它声。砖。也作“堶”)。"}, {"meaning": "碾砣,碾盘上的石轮。", "cites": [{"t": "砣,碾轮石也。", "b": "《字汇》"}]}, {"meaning": "古时用作抛掷游戏的砖块。"}, {"meaning": "用砣子打磨玉器。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4482wx','剞','1','jī','刂','10','','[{"pinyin": "jī", "defs": [{"meaning": "刻镂的刀具。", "cites": [{"t": "剞,剞曲刀也。从刀,奇声。", "b": "《说文》"}, {"t": "般倕弃其剞劂兮。", "b": "《汉书·扬雄传》"}, {"t": "公输王尔无错其剞削锯。", "b": "《淮南子·本经》"}, {"t": "握剞劂而不用兮,操规矩而无所施。", "b": "《楚辞·哀时命》"}], "words": [{"w": "剞劂", "t": "刻刀。引申为刻印书籍。"}]}, {"meaning": "抢劫,劫奇。", "cites": [{"t": "刦剞熊罴之室,剽掠虎豹之落。", "b": "晋·左思《吴都赋》。李善注:“剞,亦刦也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4483wx','砻','1','lóng','石','10','','[{"pinyin": "lóng", "defs": [{"meaning": "磨。", "cites": [{"t": "磨砻底厉。", "b": "《汉书·枚乘传》"}, {"t": "钝金必将待砻厉然后利。", "b": "《荀子·性恶》"}, {"t": "造兹宝刀,既砻既砺。", "b": "曹植《宝刀铭》"}], "words": [{"w": "砻刻", "t": "磨光雕琢"}, {"w": "砻淬", "t": "磨炼刀刃,比喻刻苦锻炼"}, {"w": "砻琢", "t": "磨炼"}, {"w": "砻斫", "t": "磨和砍削"}, {"w": "砻错", "t": "磨治;磨炼;切磋研讨。"}]}, {"meaning": "用砻脱出稻谷的壳。", "cites": [{"t": "凡既砻,则风扇以去糠秕。", "b": "《天工开物》"}], "words": [{"w": "砻坊;砻糠", "t": ""}]}, {"meaning": "磨石。", "cites": [{"t": "凡稻去壳用砻。", "b": "宋应星《天工开物》"}], "words": [{"w": "砻砺", "t": "磨石。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4484wx','轼','1','shì','车','10','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从车,式声。本义:设在车箱前面供人凭倚的横木) 同本义。", "cites": [{"t": "轼,车前也。", "b": "《说文》。按,车阑上之木。周于舆外者,在前曰轼,在旁曰骑。"}, {"t": "冯轼下齐七十余城。", "b": "《汉书·郦食其传》"}, {"t": "下视其辙,登轼而望之。", "b": "《左传·庄公十年》"}], "words": [{"w": "登轼", "t": "爬上车厢前的横木"}, {"w": "轼櫃", "t": "固定在车厢前横木上的小柜"}, {"w": "轼车", "t": "在车上凭轼致敬。"}]}]}]','jingmo-wenyan');
