INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4486wx','辂','1','lù','车','10','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从车,各声。本义:绑在车辕上用来牵引车子的横木)。"}, {"meaning": "同本义。", "cites": [{"t": "辂,车軨前横木也。", "b": "《说文》。按,人挽之车施辂,与驾牛马者不同。"}, {"t": "当前辂。", "b": "《仪礼·既夕礼》。注:“辕缚所以属引。”"}, {"t": "脱輓辂。", "b": "《史记·刘敬传》。索隐:“鹿车前横木。”"}]}, {"meaning": "引申为古代的大车,多指帝王用的。", "cites": [{"t": "大辂、次辂。", "b": "《书·顾命》"}, {"t": "辂车十五乘。", "b": "《国语·晋语》"}, {"t": "乘殷之辂。", "b": "《论语》"}], "words": [{"w": "辂车", "t": "天子的乘车"}, {"w": "辂马", "t": "天子乘车之驾马"}, {"w": "辂车衮冕", "t": "大车与礼服。"}]}, {"meaning": "拉车。", "cites": [{"t": "服牛辂马。", "b": "《管子·小匡》"}]}, {"meaning": "假借为“络”。用网状物兜住头。", "cites": [{"t": "服牛辂马。", "b": "《管子·小匡》"}]}]}]','jingmo-wenyan');
