('4491wx','虔','1','qián','虍','10','','[{"pinyin": "qián", "defs": [{"meaning": "(会意。从虍,文声。虍(hū),虎头。本义:虎行走的样子)。"}, {"meaning": "同本义。引申为勇武、强固。", "cites": [{"t": "虔,虎行皃。", "b": "《说文》"}, {"t": "有虔秉钺。", "b": "《诗·商颂·长发》"}]}, {"meaning": "诚敬;诚心。", "cites": [{"t": "以告虔也。", "b": "《左传·庄公二十四年》"}, {"t": "虔卜于先君也。", "b": "《左传·成公十二年》"}, {"t": "纠虔天刑。", "b": "《国语·鲁语》"}, {"t": "薛姨妈笑道:“果然如此,算我的孝心虔了。”", "b": "《红楼梦》"}], "words": [{"w": "虔谢", "t": "真诚地感谢"}, {"w": "虔恳", "t": "诚恳祈求"}, {"w": "虔洁", "t": "诚实而纯洁"}, {"w": "虔肃", "t": "诚实而严肃"}, {"w": "虔恭", "t": "诚敬。"}]}, {"meaning": "杀戳。", "cites": [{"t": "虔,杀也。秦晋之北,鄙谓贼为虔。", "b": "《方言》一"}, {"t": "虔刘我边陲。", "b": "《左传·成公十三年》"}, {"t": "席卷虔刘。", "b": "左思《魏都赋》"}], "words": [{"w": "虔刘", "t": "杀戳。"}]}]}]','jingmo-wenyan');
