INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4496wx','眩','1','xuàn huàn','目','10','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从目,玄声。本义:眼花,看不清)。"}, {"meaning": "同本义。", "cites": [{"t": "眩,目无常主也。", "b": "《说文》"}, {"t": "眩,视不明也。", "b": "《苍颉篇》"}, {"t": "靡瞻不眩。", "b": "《汉书·元帝纪》。注:“视乱也。”"}, {"t": "目眩眩兮寤终朝。", "b": "《楚辞·逢尤》。注:“视貌。”"}, {"t": "目眩良久。", "b": "《战国策·燕策》"}], "words": [{"w": "眩瞀", "t": "眼睛昏花,视物不明"}, {"w": "眩精", "t": "眩目;耀眼"}, {"w": "眩晃", "t": "耀眼"}, {"w": "眩眼", "t": "光芒耀眼"}, {"w": "眩移", "t": "目夺神移"}, {"w": "眩顿", "t": "眼花体乏。"}]}, {"meaning": "迷惑;迷乱。引申为欺骗。", "cites": [{"t": "眩,乱也。", "b": "《广雅》"}, {"t": "眩,惑也。", "b": "《释言》"}, {"t": "敬大臣则不眩。", "b": "《礼记·中庸》。疏:“亦惑也。”"}, {"t": "善眩人。", "b": "《史记·大宛传》。索隐:“变化惑人也。”"}, {"t": "俗儒不达时宜,好是古非今,使人眩于名实。", "b": "《汉书》"}], "words": [{"w": "眩真", "t": "迷惑真性;以假乱真"}, {"w": "眩晃", "t": "迷惑"}, {"w": "眩视惑听", "t": "迷惑人的视听。"}]}, {"meaning": "光耀。", "cites": [{"t": "扬精华以眩耀兮。", "b": "《楚辞·惜贤》。注:“光貌。”"}], "words": [{"w": "眩奇", "t": "炫耀新奇"}, {"w": "眩眩", "t": "明亮光耀貌"}, {"w": "眩耀", "t": "光彩夺目。"}]}]}, {"pinyin": "huàn", "defs": [{"meaning": "幻术;戏法", "words": [{"w": "眩人", "t": "魔术师"}, {"w": "眩形", "t": "幻术,变戏法"}, {"w": "眩师", "t": "魔术师"}, {"w": "眩者", "t": "变戏法的人"}]}]}]','jingmo-wenyan');
