INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4502wx','晏','1','yàn','日','10','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从日,安声。本义:晴朗)。"}, {"meaning": "同本义。", "cites": [{"t": "晏,天清也。", "b": "《说文》"}, {"t": "晏,明也。", "b": "《小尔雅》"}, {"t": "于是天清日晏。", "b": "杨雄《羽猎赋》。注:“无云之处也。”"}, {"t": "鶤日知晏阴蜡知雨。", "b": "《淮南子·缪称》。注:“无云也。”"}, {"t": "日出清济为晏。", "b": "《汉书·郊祀志上集》注"}], "words": [{"w": "晏日", "t": "晴天"}, {"w": "晏阴", "t": "晴阴"}, {"w": "晏温", "t": "天气晴暖。"}]}, {"meaning": "(ān)。平静;安逸。", "cites": [{"t": "以定晏阴之所成。", "b": "《礼记·月令》。注:“安也。阴称,晏。”"}, {"t": "而海内晏如。", "b": "《汉书·诸侯王表》。注:“安然也。”"}, {"t": "言笑晏晏。", "b": "《诗·卫风·氓》"}, {"t": "河清海晏,大德宽仁。", "b": "《西游记》"}], "words": [{"w": "晏安", "t": "平静;安逸"}, {"w": "晏如", "t": "安坐;闲坐"}, {"w": "晏居", "t": "闲居;安居"}, {"w": "晏室", "t": "闲居之室;私室。"}]}, {"meaning": "(gàn)。迟。", "cites": [{"t": "冉子退潮,子曰:“何晏也?”。", "b": "《论语·子路》。皇疏:“晏,晚也。”"}, {"t": "二子待君,曰晏。", "b": "《吕氏春秋·慎小》。高诱注:“晏,暮也。”"}, {"t": "及年岁之未晏兮。", "b": "《楚辞·离骚》"}, {"t": "你们今天怎么回来得这样晏?", "b": "巴金《家》"}], "words": [{"w": "晏眠", "t": "迟睡"}, {"w": "晏然", "t": "迟迟;迟缓的样子"}, {"w": "晏灯", "t": "长明灯;终夜不熄的灯。"}]}, {"meaning": "(ān)。温和;和柔。", "cites": [{"t": "言笑晏晏,信誓旦旦。", "b": "《诗·卫风·氓》。传:“晏晏,和柔也。”"}, {"t": "粲也晏也。", "b": "扬雄《法言·孝至》。李轨注:“晏,和柔。”"}, {"t": "冻登赤天,晏入玄泉。", "b": "汉·扬雄《太玄》"}], "words": [{"w": "晏阴", "t": "柔和之阴,微阴。"}]}, {"meaning": "鲜艳;华美。", "cites": [{"t": "羔裘晏兮,三英粲兮。", "b": "《诗·郑风·羔裘》"}], "words": [{"w": "晏灿", "t": "明朗。"}]}]}]','jingmo-wenyan');
