INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4513wx','蚧','1','jiè','虫','10','','[{"pinyin": "jiè", "defs": [{"meaning": "蛤蚧 。爬行动物,壁虎科。头大,尾灰色,有红色斑点,中医用作强壮剂。"}, {"meaning": "介壳虫 。蚧总科。成虫极小,雌虫无翅,雄虫有前翅一对,体背有蜡质硬壳或蜡质覆盖。种类很多,大多是果树、林木及农作物的害虫,如吹绵蚧、梨园蚧等。"}]}]','jingmo-wenyan');
