INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4515wx','圄','1','yǔ','囗','10','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从囗(wéi),吾声。“囗”,“围”的本字,表示限制在某个范围。本义:囚禁)。"}, {"meaning": "同本义。", "cites": [{"t": "圄,守之也。", "b": "《说文》"}, {"t": "子越又恶之,乃以若敖氏之族,圄伯嬴于轑阳而杀之。", "b": "《左传·僖公四年》"}]}, {"meaning": "守御。", "cites": [{"t": "告以理则不可,说以义则不听,王非战国守圄之具,其何以当之?", "b": "《战国策》。高诱注:“圄亦守。”"}]}, {"meaning": "监狱。", "cites": [{"t": "省囹圄。", "b": "《礼记·月令》。注:“所以禁守系者,若今之别狱矣。”"}, {"t": "拘者满圄,怨者满朝。", "b": "《晏子春秋》"}], "words": [{"w": "圄犴", "t": "牢狱"}, {"w": "圄空", "t": "牢空着"}, {"w": "圄囹", "t": "同“囹圄”。监狱。"}]}]}]','jingmo-wenyan');
