INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4517wx','唏','1','xī','口','10','','[{"pinyin": "xī", "defs": [{"meaning": "发笑。", "cites": [{"t": "夸父揶揄愚公唏。", "b": "陈士芑《甲辰二十八初度自述一百韵》"}], "words": [{"w": "唏唏", "t": "笑声。"}]}, {"meaning": "哀叹。", "cites": [{"t": "纣为象箸而箕子唏。", "b": "《淮南子》"}, {"t": "女仰天而唏。", "b": "苏曼殊《天涯红泪记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4518wx','盎','1','àng','皿','10','','[{"pinyin": "àng", "defs": [{"meaning": "(形声。从皿,央声。本义:腹大口小的盛物洗物的瓦盆)。"}, {"meaning": "同本义。", "cites": [{"t": "盎,盆也。", "b": "《说文》"}, {"t": "盎谓之缶。", "b": "《尔雅》"}, {"t": "盎中无斗米储。", "b": "《乐府诗集·东门行》"}], "words": [{"w": "盎盂相敲", "t": "比喻家庭口角。"}]}, {"meaning": "盎齐(浊酒)的省称。", "cites": [{"t": "三曰盎齐。", "b": "《周礼·酒正》"}]}, {"meaning": "充溢。", "cites": [{"t": "其生色也睟然,见于面,盎于背。", "b": "《孟子·尽心上》"}], "words": [{"w": "兴趣盎然;盎盎", "t": "洋溢的样子,充盈的样子"}, {"w": "盎溢", "t": "充盈洋溢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4519wx','唑','1','zuò','口','10','','[{"pinyin": "zuò", "defs": [{"meaning": "氮杂茂 。一大类有机化合物的任何一个,这类化合物的特点是含有五元环,环中至少含两个杂原子,其中一个是氮原子。与吖嗪类一样,这类化合物也可以再分成若干个小类(如二唑类、三唑类、噻唑类)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
