INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4521wx','崃','1','lái','山','10','','[{"pinyin": "lái", "defs": [{"meaning": "山名,亦名邛崃山 。在今四川省西部岷江和大渡河之间。", "cites": [{"t": "东北四十里,曰崃山…崃山,邛崃山也。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4522wx','罡','1','gāng','罒','10','','[{"pinyin": "gāng", "defs": [{"meaning": "北斗星的斗柄。", "cites": [{"t": "罡星煞曜降凡世,天蓬丁甲离青穹。", "b": "《水浒传》"}], "words": [{"w": "罡星", "t": "古星名。系北斗七星的斗柄"}, {"w": "罡星煞曜", "t": "天罡星和地煞星"}, {"w": "罡斗", "t": "天罡北斗。"}]}, {"meaning": "山冈,在较平坦地区的一块显著的高地。", "cites": [{"t": "裴渊《广州记》曰:“城北有尉他墓,墓后有大罡,谓之马鞍罡。”", "b": "《水经注·泿水》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4523wx','罟','1','gǔ','罒','10','','[{"pinyin": "gǔ", "defs": [{"meaning": "(形声。从网,古声。本义:网) 同本义。网的总称。引申为法网。", "cites": [{"t": "罟,网也。", "b": "《说文》"}, {"t": "畏此罪罟。", "b": "《诗·小雅·小明》"}, {"t": "里革断其罟而弃之。", "b": "《国语·鲁语上》"}, {"t": "不违农时,谷不可胜食也;数(罟不入洿池,鱼鳖,不可胜也。)", "b": "《孟子·梁惠王上》"}], "words": [{"w": "罟罟", "t": "亦作“罟姑”。宋元时蒙古族妇女所戴的一种冠名"}, {"w": "罟戈", "t": "捕鱼捉鸟的工具"}, {"w": "罟网", "t": "泛指鱼网。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4524wx','峪','1','yù','山','10','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从山,谷(yù)声。本义:山谷)。"}, {"meaning": "同本义。", "cites": [{"t": "你可便久镇着南边,夹山的那峪前,统领着军健,相持的那地面。", "b": "元·李直夫《虎头牌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4525wx','觊','1','jì','见','10','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从见,岂声。本义:希望得到) 同本义。", "cites": [{"t": "自毁齿已上,父兄鬻卖,以觊其利。", "b": "柳宗元《童区寄传》"}, {"t": "觊乎异日,得夷平民,然后裹足西向。", "b": "刘禹锡《上杜司徒书》"}], "words": [{"w": "觊幸", "t": "希望能侥幸得到"}, {"w": "觊望", "t": "非分的希望"}, {"w": "觊欲", "t": "非分的希求与贪欲"}, {"w": "觊夺", "t": "希图攘夺"}, {"w": "觊欲", "t": "企图"}, {"w": "觊利", "t": "企求利益。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4526wx','赅','1','gāi','贝','10','','[{"pinyin": "gāi", "defs": [{"meaning": "(形声。从贝,亥声。本义:完备)。"}, {"meaning": "同本义。", "cites": [{"t": "百骸、九窍、六藏,赅而存焉。", "b": "《庄子·齐物论》"}, {"t": "此书引据赅洽。", "b": "《四库全书·农书提要》"}], "words": [{"w": "言简意赅;赅简", "t": "齐备而扼要"}, {"w": "赅综", "t": "齐备而有条贯。"}]}, {"meaning": "奇,非常,不平常。也作“荄”。", "cites": [{"t": "刑德奇赅之数。", "b": "《淮南子·兵略》"}], "words": [{"w": "奇赅", "t": "奇侅。不寻常。"}]}, {"meaning": "货,贝。", "cites": [{"t": "赅,贝也,货也。", "b": "《篇海类编》"}]}, {"meaning": "具备,拥有。", "cites": [{"t": "百骸、九窍、六藏,赅而存焉。", "b": "《庄子·齐物论》"}], "words": [{"w": "赅存", "t": "都具有。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4527wx','钰','1','yù','钅','10','','[{"pinyin": "yù", "defs": [{"meaning": "珍宝。", "cites": [{"t": "钰,宝也。", "b": "《五音集韵》"}]}, {"meaning": "坚硬的金属。", "cites": [{"t": "钰,坚金。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4528wx','钲','1','zhēng','钅','10','','[{"pinyin": "zhēng", "defs": [{"meaning": "古代乐器名。形如钤,有柄可执,行军时用。", "cites": [{"t": "钲,铙也,似铃,柄上下通。", "b": "《说文》"}, {"t": "钲,铃也。", "b": "《广雅·释器》"}, {"t": "司铎授钲。", "b": "《东京赋》"}, {"t": "方叔率止,钲人伐鼓。", "b": "《诗·小雅·采芑》"}], "words": [{"w": "钲鼓", "t": "古时行军击钲使士兵肃静,击鼓使士兵前进。后用钲鼓为军事的代称"}, {"w": "钲歌", "t": "即铙歌,军乐"}, {"w": "钲人", "t": "掌管鸣钲击鼓之事的官吏"}]}, {"meaning": "钟身正面的上部。", "cites": [{"t": "于上谓之鼓,鼓上谓之钲,钲上谓之舞。", "b": "《周礼·考工记》。孙诒让正义:“程瑶田云:‘鼓上,为钟体之上段正面也,谓之钲。’”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4529wx','钴','1','gǔ','钅','10','','[{"pinyin": "gǔ", "defs": [{"meaning": "一种硬而银白色的二价和三价金属元素,有磁性,与铁和镍属同一族,通常和镍或铜或以天然的镍铁合金形式(如陨石)或以结合成矿物的形式共存,是动植物营养物中必不可少的微量元素,用于生产磁性合金和抗磨蚀及抗高温的硬质合金 ——元素符号 Co。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4530wx','钵','1','bō','钅','10','','[{"pinyin": "bō", "defs": [{"meaning": "(形声。从金,本声。僧人的食器)。"}, {"meaning": "僧侣所用的食具,像碗,底平,口略小。", "cites": [{"t": "吾一瓶一钵足矣。", "b": "清·彭端淑《为学一首示子侄》"}], "words": [{"w": "钵盂", "t": "佛家语。是僧侣的覆钟状饮食器皿"}, {"w": "钵多罗", "t": "佛家语。僧侣的食器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4531wx','钹','1','bó','钅','10','','[{"pinyin": "bó", "defs": [{"meaning": "铜质圆形的乐器,中心鼓起,两片相击作声 。古称“铜钹”、“铜盘”。初流行西域,南北朝时传至内地。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4532wx','钺','1','yuè','钅','10','','[{"pinyin": "yuè", "defs": [{"meaning": "(戉,形声。本义:古代兵器,青铜或铁制成,形状像板斧而较大)。"}, {"meaning": "同本义。", "cites": [{"t": "戉,大斧也。", "b": "《说文》"}, {"t": "王左杖黄戉。", "b": "《书·牧誓》。传引《六韬》:“大柯斧重八斤,一名天戉,经传皆以铖为之。”"}, {"t": "钺,车銮声也。", "b": "《说文》。伟借为戉。"}, {"t": "一人冕执钺。", "b": "《书·顾命》"}, {"t": "授铖四七。", "b": "张衡《东京赋》"}, {"t": "斧钺汤镬。", "b": "《汉书·李广苏建传》"}, {"t": "碧汉中百十队翔鸾振羽,黄旌白钺。——《梼杌闲评——明珠缘》", "b": ""}], "words": [{"w": "钺钺", "t": "车铃声。也作“哕哕”"}, {"w": "钺斧", "t": "圆刃大斧"}, {"w": "钺下", "t": "书笺开头表示尊敬的套语。在主管将帅的指挥之下。"}]}, {"meaning": "星名。钺星,即天枪三星,也称天钺。", "cites": [{"t": "辛酉,月行在东井钺星南八寸。", "b": "《南齐书·天文志上》"}]}, {"meaning": "“戉”另见yuè。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4533wx','钽','1','tǎn','钅','10','','[{"pinyin": "tǎn", "defs": [{"meaning": "一种具有光泽的铂灰色硬质延性金属元素,熔点极高,主要是五价,可耐多数化学药品的侵蚀,但氢氟酸例外 ——元素符号Ta。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4534wx','钼','1','mù','钅','10','','[{"pinyin": "mù", "defs": [{"meaning": "一种金属元素。硬的银白色结晶,用来生产特种钢,也用在电器工业中 ——元素符号Mo。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4535wx','钿','1','diàn tián','钅','10','','[{"pinyin": "diàn", "defs": [{"meaning": "衬垫。", "cites": [{"t": "莲花衔青雀,宝粟钿金虫。", "b": "吴均诗"}]}, {"meaning": "在木器上或漆器上用螺壳镶嵌的花纹。"}]}, {"pinyin": "tián", "defs": [{"meaning": "(形声。从金,田声。本义:金花。多指妇女首饰)。"}, {"meaning": "用金翠珠宝等制成的花朵形首饰。", "cites": [{"t": "钿晕罗衫色似烟。", "b": "白居易《燕子楼》"}], "words": [{"w": "钿朵", "t": "用金银贝玉等做成的花朵形饰物"}, {"w": "钿钗", "t": "金花、金钗等妇女首饰"}, {"w": "钿璎", "t": "金花、贝片、珠玉等饰物"}, {"w": "钿波", "t": "金光闪闪的水波。"}]}, {"meaning": "贴在鬓颊上的花形薄金片,也称花钿。", "words": [{"w": "钿黛", "t": "花钿和螺黛"}, {"w": "钿蝉", "t": "蝉形金花"}, {"w": "钿窝", "t": "面颊贴花钿处"}, {"w": "钿头", "t": "花钿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4536wx','铀','1','yóu','钅','10','','[{"pinyin": "yóu", "defs": [{"meaning": "锕系的一种具有银的光泽、重的放射性多价金属元素,原子序数92,富集于沥青铀矿、钾钒铀矿和钙铀云母中。用于提供铀的轻同位素235以及制备钚 ——元素符号U。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4537wx','铂','1','bó','钅','10','','[{"pinyin": "bó", "defs": [{"meaning": "一种银白色的贵金属元素,化学性质稳定,用于耐腐蚀的化学仪器等。通称“白金” ——元素符号Pt。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4538wx','铄','1','shuò','钅','10','','[{"pinyin": "shuò", "defs": [{"meaning": "(形声。从金,乐声。本义:熔化)。"}, {"meaning": "同本义。", "cites": [{"t": "铄,销金也。", "b": "《说文》"}, {"t": "流金铄石些。", "b": "《楚辞·招魂》"}, {"t": "夫铄金在炉,庄蹻不顾。", "b": "《盐铁论·诏圣》"}, {"t": "大热铄石流金。", "b": "《淮南子·诠言训》"}, {"t": "人无筋骨之强,爪牙之利,故割革而为甲,铄铁而为刃。", "b": "《淮南子·兵略》"}], "words": [{"w": "铄金", "t": "销熔金属"}, {"w": "铄石流金", "t": "使金石熔化。比喻酷热。同“流金铄石”"}, {"w": "铄化", "t": "熔化"}, {"w": "铄金点玉", "t": "熔化金属,玷污美玉。"}]}, {"meaning": "销毁。", "cites": [{"t": "彼人含其明,则天下铄矣。", "b": "《庄子·胠箧》"}], "words": [{"w": "铄绝竽瑟", "t": "完全销毁乐器。"}]}, {"meaning": "削弱。", "cites": [{"t": "秦先得齐宋,则韩氏铄,韩氏铄则楚孤而受兵也。", "b": "《战国策》"}]}, {"meaning": "渗入。", "cites": [{"t": "仁义礼智,非由外铄我也,我固有之也。", "b": "《孟子·告子上》"}]}, {"meaning": "明亮,光明。", "cites": [{"t": "故其华表则镐镐铄铄,赫奕章灼若日月之丽天也。", "b": "魏·何晏《景福殿赋》"}], "words": [{"w": "铄亮", "t": "非常明亮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4539wx','铆','1','mǎo','钅','10','','[{"pinyin": "mǎo", "defs": [{"meaning": "(卯为铆的本字) 卯,榫。", "cites": [{"t": "一铆顶一楔。", "b": "《中国谚语资料》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4540wx','铈','1','shì','钅','10','','[{"pinyin": "shì", "defs": [{"meaning": "稀土族中丰度最高的元素,原子序数58,以化合状态存在于独居石、铈硅石和其他稀土矿中;色泽与铁相似,但质软,有展性和延性;用钢刮擦时冒火花,制成作火石用的引火铁合金(如供打火机用) ——元素符号Ce。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4541wx','铉','1','xuàn','钅','10','','[{"pinyin": "xuàn", "defs": [{"meaning": "(形声。从金,玄声。本义:举鼎的器具)。"}, {"meaning": "同本义 。横贯鼎两耳以举鼎的木棍。或为钩状,金属制,以提鼎两耳。", "cites": [{"t": "铉,举鼎具也。易谓之铉,礼谓之鼎。", "b": "《说文》"}, {"t": "黄耳金铉,利贞。", "b": "《易·鼎》。孔颖达疏:铉,所以贯鼎而举之也。"}]}, {"meaning": "比喻三公等重臣。", "cites": [{"t": "且麟阁之臣,尚有位不及铉。", "b": "江淹《为萧骠骑让封第二表》"}], "words": [{"w": "铉台", "t": "本以台鼎喻三公之位,又易鼎为“铉”字,指丞相职位"}, {"w": "铉司", "t": "重臣。"}]}, {"meaning": "弓弦", "cites": [{"t": "矛戟折,环铉绝。", "b": "《战国策·齐策五》"}]}, {"meaning": "琴弦,乐器上发声的线", "cites": [{"t": "生小弄冰铉,未拨先怜。", "b": "明·顾众《浪淘沙·闺思》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4542wx','铊','1','tā','钅','10','','[{"pinyin": "tā", "defs": [{"meaning": "一种稀少而分布广泛的金属元素,外表与锡相似,但在空气中其表层容易形成为氧化物,展性如铅,但较软,产状以化合物形态见于少数矿物(例如硒铊银铜矿和红铊矿)内,毒性极大,主要以化合物的形式应用 ——元素符号Tl。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4543wx','铋','1','bì','钅','10','','[{"pinyin": "bì", "defs": [{"meaning": "硬而脆的三价的金属元素,原子序数83 ——元素符号Bi。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4544wx','铌','1','ní','钅','10','','[{"pinyin": "ní", "defs": [{"meaning": "一种具有极亮光泽的铂灰色韧性金属元素,主要为五价,产于铌铁矿及其他各种稀有矿物中;但总是伴随着钽(因为它们化学性质十分类似),钽可作为副产品被从中分离出来。铌主要用于合金中(如不锈钢中,少量的铌可防止晶间腐蚀) ——元素符号Nb。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4545wx','铍','1','pī pí','钅','10','','[{"pinyin": "pī", "defs": [{"meaning": "兵器。双刃刀。一说是大矛。", "cites": [{"t": "抽剑刺王,铍交于胸。", "b": "《左传·昭公二十七年》"}]}, {"meaning": "假借为“颇”。偏,不平正。", "cites": [{"t": "吏谨将之无铍滑。", "b": "《荀子·成相》"}]}]}, {"pinyin": "pí", "defs": [{"meaning": "钢灰色、轻、坚硬、质脆而有毒的二价金属元素,具有高电导率且X射线对它有高的贯穿能力,以化合物形式存在,可以从它的化合物还原生产(如通过电解),主要用在合金中做硬化剂(如与铜),在X射线管中用作窗并且在核反应堆中用作慢化剂和反射层 ——元素符号Be。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4546wx','䥽','1','','金','10','','[]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4547wx','铎','1','duó','钅','10','','[{"pinyin": "duó", "defs": [{"meaning": "(形声。本义:大铃)。"}, {"meaning": "同本义。", "cites": [{"t": "铎,大铃也。军法五人为伍,五伍为两,两司马执铎。", "b": "《说文》"}, {"t": "徇以木铎。", "b": "《周礼·小宰》"}, {"t": "告寡人以事者,击铎是也。", "b": "《淮南子·泛论》"}], "words": [{"w": "铎语", "t": "祭祀神灵时,用铎声节歌舞以祭"}, {"w": "铎头瘟", "t": "呆瘟神。"}]}, {"meaning": "挂在牛马颈下或屋檐下的小铃。", "cites": [{"t": "宝铎含风,响出天外。", "b": "《洛阳伽蓝记》"}]}, {"meaning": "刺;啄。", "cites": [{"t": "你还把热舌头铎我!", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4548wx','氩','1','yà','气','10','','[{"pinyin": "yà", "defs": [{"meaning": "一种无色、无臭的惰性气体元素,存在于空气中,占空气体积的0.94%,亦存在于火山气体中,从液态空气分离获得。主要用于金属加工和电弧焊接时作为保护性气氛,还用于白炽电灯和荧光灯泡、充气电子管以及盖革计数管作填充气体 ——元素符号为A或Ar。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4549wx','氤','1','yīn','气','10','','[{"pinyin": "yīn", "defs": [{"meaning": "ａ．烟云弥漫，如\\"灵山多秀色，空水共氤氤\\"；ｂ．中国哲学术语，指万物由相互作用而变化生长。", "cites": [{"t": "灵山多秀色，空水共氤氲。--唐·张九龄《湖口望庐山瀑布泉》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4550wx','氦','1','hài','气','10','','[{"pinyin": "hài", "defs": [{"meaning": "化学元素名。一种极轻的无色惰性气态元素,是所有气体中最难液化的,存在于整个宇宙中,但只在某些天然气中含有在经济上值得提取的量,主要用于填充飞艇和气球 ——元素符号He。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4551wx','毪','1','mú','毛','10','','[{"pinyin": "mú", "defs": [{"meaning": "中国西藏出产的一种羊毛织品。即毪子。", "cites": [{"t": "温暖的阳光,请别藏进云霄;穿破毪衫的人,要你来温暖。", "b": "《中国歌谣资料》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4552wx','舐','1','shì','舌','10','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从舌,氏声。本义:以舌舔物) 同本义。", "cites": [{"t": "舐笔和墨,在外者半。", "b": "《庄子·田子方》"}], "words": [{"w": "舐毫", "t": "古代传说雌兔用舌头舔舐雄兔的毛而怀孕"}, {"w": "舐笔", "t": "用舌头舔笔"}, {"w": "舐犊", "t": "老牛以舌舔小牛。比喻父母笃爱子女"}, {"w": "舐糠及米", "t": "舐食米糠后,续食糠内之米。比喻由外而内,逐渐蚕食"}, {"w": "舔足", "t": "吻舔人足"}, {"w": "火苗儿舐着锅底", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4553wx','秣','1','mò','禾','10','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从禾,末声。本义:喂马的谷饲料) 同本义(如干草、植物、谷草)。", "cites": [{"t": "骥病思偏秣。", "b": "杜甫《敬简王明府》"}, {"t": "七日刍秣之式。", "b": "《周礼·天官》"}], "words": [{"w": "刍秣", "t": "刍为喂牛羊的草饲料;秣为喂马的谷饲料。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4554wx','秫','1','shú','禾','10','','[{"pinyin": "shú", "defs": [{"meaning": "(象形。从古文术,加禾。本义:谷物之有粘性者。也指不粘者)。"}, {"meaning": "同本义。", "cites": [{"t": "秫,稷之黏者也。", "b": "《说文》"}, {"t": "稻黍秫稷粟麻秔。", "b": "《急就篇》"}, {"t": "染羽以朱湛丹秫。盖有赤白二种。今北地谓高粱之粘者为秫,秫亦胡秫。", "b": "《考工记·钟氏》"}, {"t": "春秫作美酒,酒熟吾自斟。", "b": "陶渊明《和郭主簿》"}], "words": [{"w": "秫田", "t": "种植黏粟之田"}, {"w": "秫酒", "t": "用秫酿成的酒"}, {"w": "秫蘖", "t": "制酒用的糯黍与曲"}, {"w": "秫稻", "t": "即糯稻"}, {"w": "秫谷", "t": "黍米"}, {"w": "秫黍", "t": "高粱。"}]}, {"meaning": "长针。", "cites": [{"t": "黑齿雕题,鳀冠秫缝。", "b": "《战国策·赵策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4555wx','盉','1','hé','皿','10','','[{"pinyin": "hé", "defs": [{"meaning": "古器名  。青铜制,圆口,深腹,三足。为酒水调和之器,用以节制酒之浓淡。盛行于商代和西周初期。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4556wx','笄','1','jī','竹','10','','[{"pinyin": "jī", "defs": [{"meaning": "(形声本义:古代盘头发或别住帽子用的簪子) 同本义。", "cites": [{"t": "笄,簪也。", "b": "《说文》"}, {"t": "皮弁笄。爵弁笄。", "b": "《仪礼·士冠礼》"}, {"t": "中国冠笄。", "b": "《淮南子·齐俗》"}, {"t": "玉笄綦会此冤弁之笄也。", "b": "张衡《东京赋》"}, {"t": "节纵笄总。", "b": "《礼记·内则》"}, {"t": "栉设笄。", "b": "《仪礼·士冠礼》"}, {"t": "折委笄,此男子安发之笄也。", "b": "《国语·晋语》"}, {"t": "君子偕老,副笄六珈。?", "b": ""}, {"t": "设笄珥,衣阿锡。", "b": "《列子·周穆王》"}], "words": [{"w": "笄珈", "t": "原指妇人首饰。亦代指妇女"}, {"w": "笄珥", "t": "古代妇女常用以装饰发耳的饰件"}, {"w": "笄导", "t": "即簪导。一种首饰。用以束发。"}]}, {"meaning": "指女子十五岁成年。亦特指成年之礼。", "cites": [{"t": "字而笄之。", "b": "《公羊传·僖公九年》"}, {"t": "既笄而孕", "b": "《国语·郑语》。注:“女十五而笄。”"}], "words": [{"w": "笄女", "t": "指成年的女儿"}, {"w": "笄年", "t": "女子盘发插笄的年龄;成年"}, {"w": "笄冠", "t": "女子加笄,男子加冠,指成年。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4557wx','笕','1','jiǎn','见','10','','[{"pinyin": "jiǎn", "defs": [{"meaning": "引水的长竹管,安在檐下或田间。", "cites": [{"t": "家家争调水,曲笕引修竹。", "b": "黄遵宪《游箱根》"}], "words": [{"w": "笕水", "t": "用连接的长竹管引来的水。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4558wx','笊','1','zhào','竹','10','','[{"pinyin": "zhào", "defs": [{"meaning": "用竹篾、柳条、铅丝等编成的一种杓形用具，能漏水，可以在汤水里捞东西"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4559wx','笏','1','hù','竹','10','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从竹,勿声。本义:古代朝见时大臣所执的竹板,用以记事)。"}, {"meaning": "手板。"}, {"meaning": "笏板。古代君臣在朝廷上相见时手中所拿的狭长板子,按品第分别用玉、象牙或竹制成,以为指画及记事之用。", "cites": [{"t": "笏,礼玉藻。笏天子以球王;诸侯以象,大夫以鱼须文竹、士竹、本象可也。", "b": "《说文》"}, {"t": "荐笏言于卿士。", "b": "唐·柳宗元《柳河东集》"}, {"t": "曳笏却立。", "b": ""}, {"t": "持一象笏互。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "笏击", "t": "用笏板扑击"}, {"w": "笏囊", "t": "盛笏板的袋子"}, {"w": "笏帛", "t": "盛笏的袋"}, {"w": "笏板", "t": "即笏,手板。"}]}, {"meaning": "旧时戏班用来写戏目供人点戏用的手板也称“笏”。", "cites": [{"t": "只见一个掌班拿着一本戏单,一个牙笏。", "b": "《红楼梦》"}]}, {"meaning": "金银的计算单位。铸金银成笏形,一枚为一笏。", "cites": [{"t": "众情危惧,共请主人,愿以白金十笏赎之。", "b": "五代·刘崇远《金华子杂编》"}]}, {"meaning": "指成锭的东西。", "cites": [{"t": "[魏]禧乃检箧中,得笔二管、墨一笏赠之。", "b": "清·温睿临《南疆逸史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4560wx','笆','1','bā','竹','10','','[{"pinyin": "bā", "defs": [{"meaning": "(形声。从竹,巴声。本义:竹名。即棘竹)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4561wx','俸','1','fèng','亻','10','','[{"pinyin": "fèng", "defs": [{"meaning": "(形声。从人,奉声。本义:俸禄,薪俸。旧官吏所得的薪金)。"}, {"meaning": "同本义。", "cites": [{"t": "立名誉,以取尊官厚俸。", "b": "《韩非子·奸劫弑臣》"}], "words": [{"w": "厚俸;俸钱", "t": "官吏所得的薪金"}, {"w": "俸饷", "t": "官兵的俸禄和粮饷"}, {"w": "俸薪", "t": "年俸和月薪。"}]}, {"meaning": "旧指官吏任职的年资。", "cites": [{"t": "俸,俸秩。", "b": "《广韵》"}, {"t": "俸满,一齐转了员外。", "b": "《儒林外史》"}], "words": [{"w": "俸满", "t": "官吏任职满一定年限后,依例升调"}, {"w": "俸深;俸浅", "t": "官吏担任某一职务时间较短,资历较浅。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4562wx','倩','1','qiàn qìng','亻','10','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从人,青声。本义:古代男子的美称) 同本义。", "cites": [{"t": "倩,人字也。从人,青声。汉有东方曼倩,萧长倩。", "b": "《说文》"}, {"t": "倩,士之美称。", "b": "《汉书·朱邑传》注"}, {"t": "昔陈平虽贤,须魏倩而后进。", "b": "《汉书·朱邑传》"}]}, {"meaning": "含笑的样子。", "cites": [{"t": "巧笑倩兮。", "b": "《诗·卫风·硕人》"}], "words": [{"w": "倩笑", "t": "女子美好的笑声或笑容"}, {"w": "倩倩", "t": "笑容"}, {"w": "倩语", "t": "女子娇好的语声。"}]}, {"meaning": "泛指姿容美好。", "cites": [{"t": "披颜争倩倩,逸足竞骎骎。", "b": "杜甫《风疾舟中伏枕书怀诗》"}, {"t": "如倩女之靧面。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "倩倩", "t": "美好的样子"}, {"w": "倩巧", "t": "艳丽纤巧"}, {"w": "倩服", "t": "华丽的服装"}, {"w": "倩俊", "t": "俊美"}, {"w": "倩女", "t": "美丽的少女。"}]}, {"meaning": "疾速 。"}]}, {"pinyin": "qìng", "defs": [{"meaning": "借助。", "cites": [{"t": "汝倩人邪?", "b": "《三国志》"}]}, {"meaning": "借。", "cites": [{"t": "书寄两三番,得见艰难。再倩霜毫,写下乔公案。", "b": "《金瓶梅》"}]}, {"meaning": "旧称女婿,女儿的丈夫。", "cites": [{"t": "倩可承家如有子,俸能给祭胜无官。", "b": "明·杨基《怀万郎中伯玉》"}]}, {"meaning": "指仆人。", "cites": [{"t": "顷小儿回籍应举,自行顾倩。", "b": "明·张居正《答应天巡抚宋阳山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4563wx','俵','1','biào','亻','10','','[{"pinyin": "biào", "defs": [{"meaning": "散发;分给", "words": [{"w": "俵子", "t": "散发给僧、道等人的赴斋凭证"}, {"w": "俵施", "t": "分发施舍"}]}, {"meaning": "显扬;表彰", "words": [{"w": "俵著", "t": "表彰,显扬"}, {"w": "俵扬", "t": "宣扬,张扬"}]}]}]','jingmo-wenyan');
