('4564wx','偌','1','ruò','亻','10','','[{"pinyin": "ruò", "defs": [{"meaning": "——用同“喏(nuò)”。表示提醒注意。", "cites": [{"t": "偌,那不是哥哥和妈妈么!", "b": "茅盾《过年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4565wx','俳','1','pái','亻','10','','[{"pinyin": "pái", "defs": [{"meaning": "(形声。从人,非声。本义:杂戏,滑稽剧)。"}, {"meaning": "同本义。", "cites": [{"t": "俳,戏也。…亦曰优,曰倡。", "b": "《说文》"}, {"t": "俳,优乐也。", "b": "《三苍》"}, {"t": "是时二世在甘泉,方作觳抵优俳之观。", "b": "《史记·李斯列传》"}], "words": [{"w": "俳舞", "t": "杂戏歌舞。"}]}, {"meaning": "伶人。指以舞乐杂戏为业的人。", "cites": [{"t": "击鼓歌咏作俳倡。", "b": "《汉书·霍光传》"}, {"t": "谐笑类俳倡。", "b": "汉·班固《汉书·枚乘传》"}], "words": [{"w": "俳倡", "t": "俳优,伶人"}, {"w": "俳长", "t": "俳优的头目"}, {"w": "俳子", "t": "俳优之子"}, {"w": "俳儿", "t": "俳优。亦指俳优之子。"}]}, {"meaning": "诙谐。", "cites": [{"t": "好为俳谐杂说,人多爱押之。", "b": "《北史·李文博传》"}], "words": [{"w": "俳笑", "t": "戏笑"}, {"w": "俳谑", "t": "戏言。俗称开玩笑"}, {"w": "俳体", "t": "又称俳谐体。形式上出奇弄巧,或涉于游戏讥笑"}, {"w": "俳说", "t": "戏笑嘲谑的言辞。"}]}, {"meaning": "安排。用同“排”。", "cites": [{"t": "后日我家俳酒馔。", "b": "《敦煌变文集》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4566wx','俶','1','chù tì','亻','10','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从人,叔声。经传皆以淑为之。本义:善;美好)。"}, {"meaning": "同本义。", "cites": [{"t": "俶,善也。", "b": "《说文》"}, {"t": "有俶其城。", "b": "《诗·大雅·崧高》"}], "words": [{"w": "俶辰", "t": "良辰"}, {"w": "俶灵", "t": "天赋的聪明才智"}, {"w": "俶献", "t": "古时把应时珍美新物献给国君。"}]}, {"meaning": "厚。", "cites": [{"t": "俶,厚也。俶甚者,厚甚也。平地七尺雪,厚莫甚于此矣。", "b": "王引之《经义述闻·公羊传》"}]}, {"meaning": "奇异。", "cites": [{"t": "俶傥瑰玮。", "b": "司马相如《子虚赋》"}], "words": [{"w": "俶奇", "t": "奇异"}, {"w": "俶诡", "t": "奇异滑稽"}, {"w": "俶乱", "t": "诡奇杂乱。"}]}, {"meaning": "开始。", "cites": [{"t": "令终有俶。", "b": "《诗·大雅·既醉》"}, {"t": "俶拢天经。", "b": "《书·伪允征》"}, {"t": "燕与羞俶。", "b": "《仪礼·聘礼》"}], "words": [{"w": "俶扰", "t": "开始扰乱"}, {"w": "俶载", "t": "始事,开始从事某种工作"}, {"w": "俶俶", "t": "初受上天福佑。"}]}, {"meaning": "作,建造。", "cites": [{"t": "有俶其城。", "b": "《诗·大雅·菘高》"}], "words": [{"w": "俶建", "t": "建造,建立。"}]}, {"meaning": "整理。", "cites": [{"t": "占既吉而无悔兮,简元辰而俶装。", "b": "《后汉书·张衡传》"}, {"t": "夕饮饯以俶装,旦出宿而言辞。", "b": "《宋书·谢灵运传》"}], "words": [{"w": "俶装", "t": "出门远行前,整理准备行装。"}]}]}, {"pinyin": "tì", "defs": [{"meaning": "俶傥。", "cites": [{"t": "俶,或作倜。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4567wx','倬','1','zhuō','亻','10','','[{"pinyin": "zhuō", "defs": [{"meaning": "高大;显著。", "cites": [{"t": "倬,箸大也。从人,卓声。", "b": "《说文》。按,当训大也。"}, {"t": "倬彼昊天。", "b": "《诗·大雅·甫田》"}], "words": [{"w": "倬尔", "t": "高大的样子"}, {"w": "倬诡", "t": "超绝奇特"}, {"w": "倬立", "t": "卓立,昂然而立。"}]}, {"meaning": "俊俏。", "cites": [{"t": "倬眉浓翠,怎不交人醉?", "b": "宋·张元干《点绛唇》"}], "words": [{"w": "倬俏", "t": "放荡风流"}, {"w": "倬峭", "t": "漂亮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4568wx','倏','1','shū','亻','10','','[{"pinyin": "shū", "defs": [{"meaning": "(形声。从犬,攸(yōu)声。本义:犬疾行) 同本义。", "cites": [{"t": "倏,走也。", "b": "《说文》"}, {"t": "辰倏忽其不再。", "b": "《汉书·序传》。注:“倏忽,疾也。”"}, {"t": "鹰犬倏眒(shēn,疾速)。", "b": "左思《蜀都赋》"}]}, {"meaning": "疾速。", "cites": [{"t": "儵,疾也。", "b": "《广雅》"}, {"t": "儵然而往。", "b": "《庄子·太宗师》"}, {"t": "往来儵忽。", "b": "《楚辞·招魂》。注:“疾貌。”"}, {"t": "别卿以来,倏焉二载。", "b": "《魏书·崔挺传》"}], "words": [{"w": "倏易", "t": "急速地变化"}, {"w": "倏霍", "t": "急速的样子"}, {"w": "倏闪", "t": "顷刻;霎那间"}, {"w": "倏忽", "t": "一眨眼;忽然"}, {"w": "倏尔", "t": "转眼之间"}, {"w": "倏瞬", "t": "一瞬间。"}]}, {"meaning": "忽然。", "cites": [{"t": "倏而黄烟四起。", "b": "周密《观潮》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4569wx','恁','1','nèn','心','10','','[{"pinyin": "nèn", "defs": [{"meaning": "(形声。从心,任声。本义:思;念) 同本义。", "cites": [{"t": "宜亦勤凭旅力,以充厥道。", "b": "班固《典引》"}], "words": [{"w": "恁约", "t": "思忖,思量。"}]}, {"meaning": "多见于早期白话。", "cites": [{"t": "恁不去出力,息生教娘娘和番?", "b": "马志远《汉宫秋》"}], "words": [{"w": "恁儿", "t": "您儿子。"}]}, {"meaning": "这样;那样。", "cites": [{"t": "君非我,任功名意气莫恁徘徊。", "b": "辛弃疾《沁园春》"}], "words": [{"w": "恁般", "t": "恁的。这样;如此"}, {"w": "恁地", "t": "如此,这样"}, {"w": "恁样", "t": "如此,这般"}, {"w": "恁么", "t": "这样,如此。"}]}, {"meaning": "这,那。", "cites": [{"t": "早知恁般么,恨当初不把雕鞍锁。", "b": "柳永《定风波》"}], "words": [{"w": "恁时", "t": "那时候。"}]}, {"meaning": "怎,怎么。", "cites": [{"t": "却恁地教什么人在间壁吱吱的哭,搅俺弟兄们吃酒。", "b": "《水浒全传》"}]}, {"meaning": "任凭。", "cites": [{"t": "花布恁商营。", "b": "费信《星槎胜览》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4570wx','倭','1','wō','亻','10','','[{"pinyin": "wō", "defs": [{"meaning": "(形声。从人,委声。本义:古称日本) 人种名。中国于汉、魏、晋、南北朝时称日本为倭。其后倭和与日本两名并称", "words": [{"w": "倭傀", "t": "古代的丑女"}, {"w": "倭奴", "t": "中国旧称日本为倭奴"}, {"w": "倭刀", "t": "古时日本所制的佩刀,以锋利著称"}, {"w": "倭股", "t": "日本产的缎子"}, {"w": "倭国", "t": "中国史书中日本的古称"}, {"w": "倭夷", "t": "日本海盗"}]}, {"meaning": "矮的,个子不高的", "words": [{"w": "倭狐猴", "t": ""}]}, {"meaning": "短的", "words": [{"w": "倭刀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4571wx','倪','1','ní','亻','10','','[{"pinyin": "ní", "defs": [{"meaning": "(形声。从人,“兒”(ní)声。本义:小孩)。"}, {"meaning": "同本义。", "cites": [{"t": "反其旄倪。", "b": "《孟子·梁惠王下》"}, {"t": "垂髫之倪。", "b": "《旧唐书·玄宗本纪》"}], "words": [{"w": "倪子", "t": "方言。儿子"}, {"w": "倪倪", "t": "幼弱。"}]}, {"meaning": "涯际;边际。", "cites": [{"t": "绝境胜无倪,归途兴不尽。", "b": "钱起《自终南山晚归》"}], "words": [{"w": "端倪", "t": "事情的眉目;头绪"}, {"w": "倪露", "t": "露出端倪。"}]}, {"meaning": "端;头绪。", "cites": [{"t": "不知端倪。", "b": "《庄子·大宗师》"}, {"t": "乾端坤倪,轩豁呈露。", "b": "韩愈《南海神庙碑》"}]}, {"meaning": "老人齿落复生的齿  皆黄耄倪齿也。——《列女传·鲁季敬姜》。"}, {"meaning": "斜视。", "cites": [{"t": "龟俯者灵…左倪不类,右倪不若。", "b": "《尔雅·释鱼》注:“倪与睨同。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4572wx','俾','1','bǐ','亻','10','','[{"pinyin": "bǐ", "defs": [{"meaning": "(形声。从人,卑声。本义:门役) 同本义。", "cites": [{"t": "俾,门侍人。", "b": "《说文》"}, {"t": "俾,职也。俾为门侍人。", "b": "《释言》"}, {"t": "有能俾。", "b": "《书·尧典》"}, {"t": "罔不率俾。", "b": "《书·君》"}]}, {"meaning": "使,把。", "cites": [{"t": "俾尔单厚。", "b": "《诗·小雅·天保》"}, {"t": "俾也可忘。", "b": "《诗·邶风·日月》"}, {"t": "苟入狱,不问罪之有无…俾困苦不堪。", "b": "清·方苞《狱中杂记》"}, {"t": "又嘱学使俾入邑庠。", "b": "《聊斋志异·促织》"}], "words": [{"w": "俾夜作昼", "t": "把夜晚当作白天,形容夜以继日地工作"}, {"w": "俾昼作夜", "t": "把白昼当成夜晚,形容不分昼夜地寻欢作乐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4573wx','倜','1','tì','亻','10','','[{"pinyin": "tì", "defs": [{"meaning": "a.超然或特出的样子；b.疏远的样子。", "cites": [{"t": "俄而天下倜然举去桀纣而犇汤武。--《荀子》", "b": ""}]}, {"meaning": "洒脱，不拘束。", "cites": [{"t": "古者富贵而名磨灭，不可胜记，唯倜傥非常之人称焉。--司马迁《报任安书》", "b": ""}, {"t": "诸仁者于此见得倜傥分明。--《五灯会元》", "b": ""}]}, {"meaning": "品行豪迈,不拘细节。", "cites": [{"t": "耽字彦道，少有才气，倜傥不羁，为士类所称。--《晋书》", "b": ""}]}, {"meaning": "豪迈萧洒,饱有才学,卓越不凡;出众。", "cites": [{"t": "先生这等翩然而来,真是侗傥不群。 -- 《儿女英雄传》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4574wx','隼','1','sǔn','隹','10','','[{"pinyin": "sǔn", "defs": [{"meaning": "(指事。据小篆,从隹(zhuī)一。“隹”是汉字部首之一,短尾鸟的总称。“一”表示这种鸟的标识。本义:一种凶猛的鸟) 同本义  隼科(Falconidae)的各种鹰,特征是有长的翼,嘴短而宽,上嘴弯曲并有齿状凸起。飞得很快,它们通常突然从空中冲向猎物处猎取食物。", "cites": [{"t": "有隼集于陈侯之庭而死。", "b": "《国语·鲁语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4575wx','隽','1','juàn jùn','隹','10','','[{"pinyin": "juàn", "defs": [{"meaning": "(会意。从隹(zhuī,短尾鸟),从弓。“弓”用来射鸟。本义:鸟肉肥美,味道好)。"}, {"meaning": "同本义。也指美味。", "cites": [{"t": "隽,肥肉也。", "b": "《说文》"}]}, {"meaning": "泛指肥美之肉,美味。", "cites": [{"t": "爱滑卷青绡,香袅冰丝细。山人隽味。", "b": "宋·李彭老《摸鱼儿》"}], "words": [{"w": "隽语", "t": "意味深远的语句"}, {"w": "隽德", "t": "德行崇高深厚"}, {"w": "隽壮", "t": "优美雄健"}, {"w": "隽洁", "t": "优美简洁"}, {"w": "隽蔚", "t": "意味深长。"}]}, {"meaning": "古时以小鸟为射的,射中为隽。", "cites": [{"t": "得隽为雄,唯能是与。", "b": "唐·元稹《观兵部马射赋》"}]}, {"meaning": "科举时代喻称考中。", "cites": [{"t": "名高场屋已得隽,世有龙门今复登。", "b": "宋·欧阳修《送徐生之渑池》"}]}, {"meaning": "姓。"}]}, {"pinyin": "jùn", "defs": [{"meaning": "优秀,才智出众。", "cites": [{"t": "有三隽才。", "b": "《左传·哀公十五年》"}, {"t": "进用英隽。", "b": "《汉书·礼乐志》"}, {"t": "隽乂英旄。", "b": "枚乘《忘忧馆柳赋》"}], "words": [{"w": "隽良", "t": "英俊良贤"}, {"w": "隽材", "t": "杰出的才干"}, {"w": "隽武", "t": "雄俊威武"}, {"w": "隽拔", "t": "英俊超群"}, {"w": "隽辅", "t": "杰出的辅佐者。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4576wx','倌','1','guān','亻','10','','[{"pinyin": "guān", "defs": [{"meaning": "(会意。从人,从官,官亦声。本义:主管驾车的小臣)。"}, {"meaning": "同本义。", "cites": [{"t": "倌,小臣。", "b": "《说文》"}, {"t": "命彼倌人。", "b": "《诗·鄘风·定之方中》。传:“倌人,主驾者,盖掌巾车脂辖之事。”"}], "words": [{"w": "倌人", "t": "古代主管驾车的小臣;清时苏沪一带对妓女的称呼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4577wx','倥','1','kōng','亻','10','','[{"pinyin": "kōng", "defs": [{"meaning": "(形声。从人,空声。本义:倥侗(kōngtóng):蒙昧,无知)同本义", "cites": [{"t": "天降生民,倥侗颛蒙。", "b": "《法言·序》"}], "words": [{"w": "倥蒙", "t": "蒙昧无知"}]}, {"meaning": "绷着[脸]", "words": [{"w": "倥脸", "t": "拉着脸"}, {"w": "绷着脸)", "t": ""}, {"w": "倥偬", "t": "事情急迫匆忙"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4578wx','臬','1','niè','自','10','','[{"pinyin": "niè", "defs": [{"meaning": "箭靶。", "cites": [{"t": "臬,射准的也。", "b": "《说文》"}]}, {"meaning": ";引申为目标;准则。", "cites": [{"t": "所发无臬。", "b": "张衡《东京赋》"}], "words": [{"w": "臬极", "t": "准则;标准。"}]}, {"meaning": "古代测日影的标杆。", "cites": [{"t": "陈圭置臬,瞻星揆地。", "b": "《石阙铭·序》"}]}, {"meaning": "刑法;法度。", "cites": [{"t": "王曰:“外事,汝陈时臬,司师兹殷罚有伦。”", "b": "《书·康诰》"}]}, {"meaning": "终极。", "cites": [{"t": "其深不测,其广无臬。", "b": "汉·王粲《游海赋》"}]}, {"meaning": "安装在船侧用以支架橹的木桩。", "cites": [{"t": "如人摇橹,臬为之碍故也。", "b": "宋·沈括《梦溪笔谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4579wx','皋','1','gāo háo','白','10','','[{"pinyin": "gāo", "defs": [{"meaning": "(形声。白形本声。湖边的地得日光最早。本义:泽边地。“臯”为“皋”的俗字)。"}, {"meaning": "同本义。泛指岸边,水旁陆地。", "cites": [{"t": "皋,此字当训泽边地也。从白。白者,日未出时,初生微光也。圹野得日光最早,故从白,从本声。俗字作臯。", "b": "朱骏声《说文通训定声》"}, {"t": "牧隰皋。", "b": "《左传·襄公二十五年》"}, {"t": "亭皋千里。", "b": "司马相如《上林赋》"}, {"t": "河溢皋陆。", "b": "《史记·孝武纪》"}, {"t": "江皋河濒。", "b": "《史记·贾山传》"}, {"t": "步余马兮山皋,邸余车兮方林。", "b": "《楚辞·屈原·涉江》"}], "words": [{"w": "皋渚", "t": "水边地"}, {"w": "皋陆", "t": "水边平地"}, {"w": "皋隰", "t": "水边低湿地"}, {"w": "皋浒", "t": "高岸和水边"}, {"w": "皋壤", "t": "泽边洼地"}, {"w": "皋兰", "t": "生于水泽边的兰草。"}]}, {"meaning": "沼泽。", "cites": [{"t": "鹤鸣于九皋,声闻于野。", "b": "《诗·小雅·鹤鸣》"}, {"t": "江皋河濒,虽有恶种,无不猥大。", "b": "《汉书·贾山传》"}], "words": [{"w": "皋泽", "t": "沼泽地带"}, {"w": "皋薮", "t": "水草丛生的沼泽地带"}, {"w": "皋壤", "t": "泽边之地"}, {"w": "皋原", "t": "沼泽和原野"}, {"w": "皋圃", "t": "池泽园圃。"}]}, {"meaning": "水田。", "cites": [{"t": "耕东皋之沃壤兮。", "b": " 《文选·潘岳·秋兴赋》"}]}, {"meaning": "高地。", "cites": [{"t": "登东皋以舒啸,临清流而赋诗。", "b": "陶潜《归去来兮辞》"}]}, {"meaning": "皋比。虎皮;古人坐虎皮讲学。后因以指讲席。", "cites": [{"t": "公子偃……自雩门窃出,蒙皋比而先犯之。", "b": "《左传·庄公十年》"}, {"t": "今夫佩虎符坐皋比者洸洸乎干城之具也,果能授孙、吴之略耶?", "b": "明·刘基《卖柑者言》"}, {"t": "余两幼儿曰橙曰陶,丈为启蒙,设皋比焉。", "b": "清·龚自珍《哭郑八丈》诗自注"}]}, {"meaning": "与下卑相对。"}, {"meaning": "(jiù)。罪过。", "cites": [{"t": "鲁人之皋,数年不觉,使我高蹈。", "b": "《左传·哀公二十一年》"}]}]}, {"pinyin": "háo", "defs": [{"meaning": "号叫。", "cites": [{"t": "来瞽令皋舞。", "b": "《周礼·春官》"}]}, {"meaning": "又。", "cites": [{"t": "诏来瞽皋舞。", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4580wx','郫','1','pí','阝','10','','[{"pinyin": "pí", "defs": [{"meaning": "春秋晋邑 。故地在今河南省济源市西。"}, {"meaning": "县名 。古郫邑。秦置县,在今四川省成都市西郫县。"}, {"meaning": "江名 。岷江支流,从灌县分支,经过郫县,到成都市南与锦江合流。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4581wx','倨','1','jù','亻','10','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从人,居声。本义:傲慢)。"}, {"meaning": "同本义。", "cites": [{"t": "倨,不逊也。", "b": "《说文》"}, {"t": "游毋倨。", "b": "《礼记·曲礼》。疏:“慢也。”"}, {"t": "嫂何前倨而后恭也。", "b": "《战国策·秦策》"}, {"t": "与其倨也宁句。", "b": "《大戴礼记·曾子立事》。按,凡侈曰倨,敛曰句。"}, {"t": "体倨固而心执诈。", "b": "《脩身》"}], "words": [{"w": "倨忽", "t": "傲慢而疏忽"}, {"w": "倨倨", "t": "一无思虑、神色傲慢的样子;盛服的样子"}, {"w": "倨见", "t": "傲慢地接见或往见"}, {"w": "倨侮", "t": "傲慢自大。"}]}, {"meaning": "直而折曲。", "cites": [{"t": "倨中矩,句中钩。", "b": "《礼记·乐记》"}], "words": [{"w": "倨句", "t": "器物弯曲的形状。曲度较小的叫倨,大的叫句"}, {"w": "倨佝", "t": "倨拘。弯曲的,句为甚曲"}, {"w": "倨立", "t": "立而不正,前倾侧倚。"}]}, {"meaning": "凭倚。", "cites": [{"t": "老聃方将倨堂而应。", "b": "《庄子·天运》"}, {"t": "沛公方倨床从两女子洗足。", "b": "《史记·郦生陆贾列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4582wx','衄','1','nǜ','血','10','','[{"pinyin": "nǜ", "defs": [{"meaning": "鼻出血。", "cites": [{"t": "衄,鼻出血也。从血,丑声。", "b": "《说文》。俗字作衂"}, {"t": "春不鼽衄。", "b": "《素问·金匮真言论》"}, {"t": "此人奉使出门,卒尔鼻衄。", "b": "《大庄严论经》"}]}, {"meaning": "畏缩。", "cites": [{"t": "未战而退,先自摧衄,亦古之所忌。", "b": "《晋书》"}]}, {"meaning": "挫折;挫伤;失败。", "cites": [{"t": "莫不衂锐挫铓。", "b": "左思《吴都赋》"}, {"t": "流闻东军失备,师徒小衄。", "b": "曹植《求自试表》"}], "words": [{"w": "衄折", "t": "失败,挫败"}, {"w": "衄挫", "t": "衄折"}, {"w": "衄痍", "t": "创伤"}, {"w": "衄锐", "t": "挫其锋锐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4583wx','颀','1','qí','页','10','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从页(xié),斤声。从页,与“头”有关。本义:头俊美)。"}, {"meaning": "同本义。", "cites": [{"t": "颀,头佳貌。", "b": "五代·徐锴《说文系传》"}]}, {"meaning": "（kěn）。诚恳。", "cites": [{"t": "颀乎其至也。", "b": "《礼记·檀弓上》"}]}, {"meaning": "坚韧。", "cites": [{"t": "是故輈欲颀典。", "b": "《周礼·考工记·輈人》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4584wx','徕','1','lái lài','彳','10','','[{"pinyin": "lái", "defs": [{"meaning": "(古来字。形声。从彳(chì),表示与行走有关,来声。本义:到来,与“往”相对)。"}, {"meaning": "同本义。", "cites": [{"t": "天马徕,从西极。", "b": "《汉书》"}, {"t": "氐羌徕服。", "b": "《汉书·武帝纪》"}], "words": [{"w": "徕下", "t": "下来"}, {"w": "徕臣", "t": "前来臣服"}, {"w": "徕服", "t": "徕臣"}, {"w": "徕祗", "t": "前来致敬"}, {"w": "徕孙", "t": "玄孙的儿子。"}]}, {"meaning": "招来;使之来。", "cites": [{"t": "徕三晋之民,而使之事本。(三晋:赵、韩、魏三国。事本:从事农业。)", "b": "《商君书》"}], "words": [{"w": "徕人", "t": "戏剧中扮演仆役的角色。"}]}]}, {"pinyin": "lài", "defs": [{"meaning": "劝勉。", "cites": [{"t": "于是高祖引[刘孝]孙、[张胄玄]等,亲自劳徕。", "b": "《隋书·律历志中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4585wx','舫','1','fǎng','舟','10','','[{"pinyin": "fǎng", "defs": [{"meaning": "船夫,舟子。", "cites": [{"t": "舫,舟师也。明堂、月令曰:舫人,习水者,从舟,从方,会意。方亦声。", "b": "《说文》。今以榜为之。"}], "words": [{"w": "舫人", "t": "船夫,舟子,舟人。"}]}, {"meaning": "船。后泛指小船。", "cites": [{"t": "舫,舟也。", "b": "《尔雅》"}, {"t": "舫,船也。", "b": "《广雅》"}, {"t": "青雀白鹄舫,四角龙子幡。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "东船西舫悄无言,唯见江心秋月白。", "b": "唐·白居易《琵琶行(并序)》"}], "words": [{"w": "舫艇", "t": "小舟。"}]}, {"meaning": "并连起来的两船。", "cites": [{"t": "连舟曰舫。", "b": "《通俗文》"}, {"t": "舫船载卒。", "b": "《史记·张仪传》。索隐:“并两船也。”"}], "words": [{"w": "舫舟", "t": "并合两艘小船来载人。也作“方舟”"}, {"w": "舫船", "t": "并合的两艘船。即舫舟。也称“方舟”。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4586wx','釜','1','fǔ','金','10','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从金省,父声。本义:古炊器。敛口圜底,或有二耳。其用于鬲,置于灶,上置甑以蒸煮。盛行于汉代。有铁制的,也有铜或陶制的)。"}, {"meaning": "同本义。", "cites": [{"t": "萁在釜下燃,豆在釜中泣。", "b": "曹植《七步诗》"}], "words": [{"w": "釜中生鱼", "t": "釜鱼甑尘,釜中已生出鱼来。谓生活清贫,断炊已久"}, {"w": "釜鱼假息", "t": "比喻不能久存"}, {"w": "釜底游魂", "t": "比喻行将灭亡、苟延残喘的人"}, {"w": "釜鬲", "t": "陶制炊器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4587wx','奚','1','xī','大','10','','[{"pinyin": "xī", "defs": [{"meaning": "(会意。据甲骨文,左为手(爪),右为绳索捆着的人。本义:奴隶,又专指女奴)。"}, {"meaning": "同本义。", "cites": [{"t": "凡奚隶聚而出入者,则司牧之。", "b": "《周礼·秋官·禁暴氏》。孙诒让正义:“奚为女奴,隶为男奴也。”"}, {"t": "酒人奄十人,女酒三十人,奚三百人。", "b": "《周礼·天官》"}], "words": [{"w": "奚女", "t": "婢女"}, {"w": "奚奴", "t": "女奴。今泛指奴仆"}, {"w": "奚童", "t": "奚僮。未成年男仆"}, {"w": "奚隶", "t": "男女奴隶。"}]}, {"meaning": "大腹。", "cites": [{"t": "奚,大腹也。从大,籀文系省声。", "b": "《说文》"}, {"t": "晋祁奚。", "b": "《左传》"}], "words": [{"w": "奚奚", "t": "大腹便便的样子。"}]}, {"meaning": "什么,何。", "cites": [{"t": "奚取焉。", "b": "唐·韩愈《朱文公校昌黎先生集》"}, {"t": "复奚疑。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "为我属地,我自济之,与俄奚涉焉?", "b": "《清史稿》"}], "words": [{"w": "奚如", "t": "何如"}, {"w": "奚距", "t": "何尝。"}]}, {"meaning": "哪个。", "cites": [{"t": "奚方能已之乎?", "b": "《列子》"}]}, {"meaning": "因何缘故。", "cites": [{"t": "骨肉奚无情?", "b": "《卖女行》"}], "words": [{"w": "奚而", "t": "犹为何;如何"}, {"w": "奚似", "t": "奚若。何似"}, {"w": "奚如", "t": "如何,怎样。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4588wx','衾','1','qīn','衣','10','','[{"pinyin": "qīn", "defs": [{"meaning": "(从衣,今声。本义:被子) 同本义。", "cites": [{"t": "衾,大被。", "b": "《说文》。段注:“寝衣为小被(夹被),则衾是大被(棉被)。”"}, {"t": "抱衾与椆。", "b": "《诗·召南·小星》"}, {"t": "缁衾赬里,无紞。", "b": "《仪礼·士丧礼》"}, {"t": "衣衾多少厚薄多少之数。", "b": "《荀子·礼论》"}, {"t": "布衾多年冷似铁。", "b": "唐·杜甫《茅屋为秋风所破歌》诗"}, {"t": "狐裘不暖锦衾薄。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "以衾拥覆。", "b": "明·宋濂《送东阳马生序》"}, {"t": "生则同衾,死则同穴。", "b": "《西厢记》"}], "words": [{"w": "衾褥", "t": "殓尸用的被褥"}, {"w": "衾衽", "t": "指被与席。一说为枕席之间"}, {"w": "衾枕", "t": "被与枕"}, {"w": "衾绸", "t": "被;一说为大被和床帐"}, {"w": "衾影无愧", "t": "暗中不做亏心事。后人引喻人在私生活中无败坏德行的事"}, {"w": "衾衣", "t": "被子和衣服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4589wx','胯','1','kuà','月','10','','[{"pinyin": "kuà", "defs": [{"meaning": "(形声。从肉,夸声。本义:两股之间) 同本义。", "cites": [{"t": "胯,股也。", "b": "《说文》。段注:“合两股言曰胯。”"}, {"t": "出我胯下。", "b": "《史记·淮阴侯传》"}, {"t": "[李逵]要奔城边劈门,被燕青抱住腰胯。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
