INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4595wx','朕','1','zhèn','月','10','','[{"pinyin": "zhèn", "defs": [{"meaning": "缝隙。", "cites": [{"t": "舟之缝理曰朕。", "b": "戴震《考工记图·函人注》"}, {"t": "视其朕,欲其直也。", "b": "《周礼·考工记》"}]}, {"meaning": "征兆;先兆。", "cites": [{"t": "体尽无穷,而游无朕。", "b": "《庄子·应帝王》"}, {"t": "变化之朕焉。", "b": "《鬼谷子》。"}], "words": [{"w": "朕兆", "t": "征兆;预兆"}, {"w": "朕垠", "t": "征兆,迹象"}, {"w": "朕迹", "t": "征兆;痕迹。"}]}, {"meaning": "我。秦以前,不论尊卑,皆自称朕。", "cites": [{"t": "朕,我也。", "b": "《说文》"}, {"t": "朕,我也。", "b": "《尔雅》"}, {"t": "汝能庸命巽朕位。", "b": "《书·尧典》"}, {"t": "无废朕命。", "b": "《诗·大雅·韩奕》"}, {"t": "朕皇考曰伯庸。", "b": "《楚辞·离骚》"}, {"t": "古者尊卑共称朕。", "b": "蔡邕《独断》"}, {"t": "回朕车以复路兮,及行迷之未远。", "b": "《楚辞·离骚》。"}], "words": [{"w": "朕皇考", "t": "我的已故父亲的名字。"}]}, {"meaning": "皇帝的自称。秦灭六国以后,天子始自称朕。", "cites": [{"t": "朕位几不保。", "b": "清·梁启超《谭嗣同传》"}, {"t": "朕非约耳。", "b": "《明史》"}]}, {"meaning": "又。", "cites": [{"t": "朕今病久。", "b": ""}, {"t": "朕不自谨惜。", "b": ""}, {"t": "使朕能出御便殿。。", "b": ""}], "words": [{"w": "朕躬", "t": "我,我身。多用于天子自称"}, {"w": "朕违", "t": "帝王称自己的过错。"}]}]}]','jingmo-wenyan');
