INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4599wx','玺','1','xǐ','玉','10','','[{"pinyin": "xǐ", "defs": [{"meaning": "(形声。从玉,尔声。本义:印章。古时尊卑通用。自秦以后,多指帝王印玺)同本义。", "cites": [{"t": "璽,王者印也。所以主土。从土,爾声。籀文从玉。", "b": "《说文》"}, {"t": "货贿用玺节。", "b": "《周礼·掌节》"}, {"t": "玺书追而与之。", "b": "《左传·襄公二十九年》"}, {"t": "始皇九年四月,缪毐矫王御玺及太后玺作乱。", "b": "《史记·秦始皇本纪》"}, {"t": "皇太子妃玺,以黄金,方一寸,龟钮。", "b": "《隋书·礼仪》"}, {"t": "玉玺不缘归日角,锦帆应是到天涯。", "b": "李商隐《隋宫》"}], "words": [{"w": "玺册", "t": "玺策。玉玺和册命文书"}, {"w": "玺封", "t": "盖上玺印的文书封口。"}]}]}]','jingmo-wenyan');
