INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4606wx','逖','1','tì','辶','10','','[{"pinyin": "tì", "defs": [{"meaning": "远,不近 。", "words": [{"w": "逖闻", "t": "逖听。在远处听到。表示恭敬"}, {"w": "逖远", "t": "遥远"}, {"w": "逖慕", "t": "仰慕,仰望思慕。表示恭敬。"}]}, {"meaning": "使之远离。", "cites": [{"t": "我则致天之罚,离逖尔土。", "b": "《书·多方》"}]}, {"meaning": "治。", "cites": [{"t": "敬服王命,以绥四国,纠逖王慝。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4607wx','桀','1','jié','木','10','','[{"pinyin": "jié", "defs": [{"meaning": "鸡栖的木桩。", "cites": [{"t": "鸡栖于桀。", "b": "《诗·王风·君子于役》"}]}, {"meaning": "小木桩。", "cites": [{"t": "城希裾门而直桀。", "b": "《墨子》"}]}, {"meaning": "杰出的人才。", "cites": [{"t": "选士厉兵,简练桀俊。", "b": "《礼记·月令》"}], "words": [{"w": "桀俊", "t": "才能出众的人"}, {"w": "桀士", "t": "杰出的人。"}]}, {"meaning": "特出,高出。", "cites": [{"t": "邦之桀兮。", "b": "《诗·卫风·伯兮》"}, {"t": "初之列士桀大夫,慎言知行。", "b": "《墨子·非命中》"}, {"t": "与其桀相而谋。", "b": "《墨子·耕柱》"}, {"t": "此小人之桀雄也,不可不诛也。", "b": "《荀子·宥坐》"}, {"t": "人主贤则豪桀归之。", "b": "《吕氏春秋·功名》"}, {"t": "杰然特起。", "b": "唐·柳宗元《至小丘西小石潭记》"}, {"t": "气杰旺。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "桀异", "t": "特出优异"}, {"w": "桀立", "t": "耸立"}, {"w": "桀出", "t": "突然出,高出"}, {"w": "桀木", "t": "高大的树。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4608wx','袅','1','niǎo','衣','9','','[{"pinyin": "niǎo", "defs": [{"meaning": "以系带系马。代称马名。", "cites": [{"t": "裊,以组带马也。", "b": "《说文》。段玉裁注：“《百官志》注曰:‘秦爵二十等…三曰簪裊,御驷马者。’”"}], "words": [{"w": "袅蹏", "t": "袅蹄,铸金成马蹄形。因借指金银"}, {"w": "袅驃", "t": "古骏马名"}, {"w": "袅骖", "t": "小马的别名。一说古骏马名。即袅驃。"}]}, {"meaning": "缭绕;缠绕。", "cites": [{"t": "台上炉香袅翠烟。", "b": "王明清《挥尘后录》"}], "words": [{"w": "袅脚", "t": "绕腿布"}, {"w": "袅丝", "t": "香灰的别称"}, {"w": "袅篆", "t": "指香的烟缕。"}]}, {"meaning": "吹拂。", "cites": [{"t": "荷花落兮江色秋,秋风袅兮夜悠悠。", "b": "李白《悲清秋赋》"}]}, {"meaning": "柔弱细长的样子。", "cites": [{"t": "披迳怜深沉,攀条惜杳袅。", "b": "南朝·陈·江总《游西霞寺》"}], "words": [{"w": "袅娉", "t": "袅娜娉婷。女子姿态美好的样子"}, {"w": "袅嫋", "t": "纤长柔美的样子。"}]}]}]','jingmo-wenyan');
