INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4611wx','栾','1','luán','木','10','','[{"pinyin": "luán", "defs": [{"meaning": "木名。也叫“栾华”、“灯笼树” 。无患子科。落叶乔木,羽状复叶,小叶卵形,花淡黄色,圆锥花序,结蒴果,长椭圆形。种子圆形黑色,叶子含鞣质,可制栲胶。花可提黄色染料,又可入药。"}, {"meaning": "拱,建筑物立柱和横梁之间成弓形的承重结构。", "cites": [{"t": "结重栾以相承。", "b": "张衡《西京赋》。注:“柱上曲木,两头受栌者。”"}], "words": [{"w": "栾拱", "t": "屋架中承受梁木的曲木"}, {"w": "栾栌", "t": "屋中柱顶承梁之木,曲者为栾,直者为栌。"}]}, {"meaning": "双生子。", "cites": [{"t": "薛公知之,故与二栾博。", "b": "《韩非子·外储说右上》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4612wx','挛','1','luán','手','10','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从手,羉(luán)声。本义:维系,牵系)。"}, {"meaning": "同本义。", "cites": [{"t": "挛,係也。", "b": "《说文》"}, {"t": "有孚挛如。", "b": "《易·小畜》。马注:“连也。”"}], "words": [{"w": "挛缀", "t": "联结"}, {"w": "挛结", "t": "纠结"}, {"w": "挛牵", "t": "牵制;束缚"}, {"w": "挛索", "t": "系绳"}, {"w": "挛格", "t": "捆缚;束缚。"}]}, {"meaning": "抽搐,痉挛;手足蜷曲不能伸直。", "cites": [{"t": "痿躄为挛。", "b": "《素问·疏五过论》"}, {"t": "筋散则不挛,故辛可以养筋。", "b": "宋·王安石《洪范传》"}], "words": [{"w": "挛曲", "t": "蜷曲"}, {"w": "挛卧", "t": "蜷曲而卧"}, {"w": "挛屈", "t": "蜷曲。"}]}]}]','jingmo-wenyan');
