('4617wx','疽','1','jū','疒','10','','[{"pinyin": "jū", "defs": [{"meaning": "中医指一种毒疮", "words": [{"w": "疽疣", "t": "毒疮和赘疣"}, {"w": "疽食", "t": "疮毒侵蚀肌肉。比喻祸患蔓延"}, {"w": "疽肠", "t": "犹言狠毒的心肠"}, {"w": "疽肿", "t": "局部皮肤肿胀坚硬的毒疮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4618wx','痈','1','yōng','疒','10','','[{"pinyin": "yōng", "defs": [{"meaning": "(形声。从疒(chuáng),雍声。本义:中医指恶性脓疮)。"}, {"meaning": "同本义。", "cites": [{"t": "佗以为肠痈。", "b": "《后汉书·华佗传》"}], "words": [{"w": "痈肿", "t": "痈疽"}, {"w": "痈疮", "t": "很大的毒疮"}, {"w": "痈囊", "t": "痈肿。"}]}, {"meaning": "鼻疾,不知香臭。", "cites": [{"t": "鼻不知香臭曰痈。", "b": "汉·王充《论衡·别通》"}]}]}]','jingmo-wenyan');
