INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4620wx','痂','1','jiā','疒','10','','[{"pinyin": "jiā", "defs": [{"meaning": "痂皮;疮壳。", "cites": [{"t": "痂,疥也。从疒,加声。", "b": "《说文》"}, {"t": "痂,创也。", "b": "《广雅》。按,今谓疮所脱之鳞为痂。"}, {"t": "刘邕嗜食痂。", "b": "《南史》"}, {"t": "数日,疮痂尽脱。", "b": "《聊斋志异·翩翩》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4621wx','痉','1','jìng','疒','10','','[{"pinyin": "jìng", "defs": [{"meaning": "风强病。也称“痉挛”。", "cites": [{"t": "痉,彊急也。", "b": "《说文》"}], "words": [{"w": "痉风", "t": "痉挛,风病"}, {"w": "痉病", "t": "风强病,痉挛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4622wx','衮','1','gǔn','衣','10','','[{"pinyin": "gǔn", "defs": [{"meaning": "(衮为衮的俗字。形声。从衣,公声。本义:画龙于衣。也指古代帝王或三公(古代最高的官)穿的礼服)。"}, {"meaning": "同本义。"}, {"meaning": "中国古代天子祭祀时所穿的绣有龙的礼服。", "cites": [{"t": "衮,天子享先王。卷龙绣于下常。幅一龙,蟠阿上乡(向)。", "b": "《说文》"}, {"t": "王之吉服,享先王则衮冕。", "b": "《周礼·司服》。司农注:“衮衣,卷龙衣也。”"}, {"t": "我觏之子,衮衣绣裳。", "b": "《诗·豳风·九罭》"}]}, {"meaning": "(罭(yù)九罭:捕捉小鱼的细网)。", "cites": [{"t": "吾有布衣之心,子有衮冕之志,各从所好,不亦善乎?", "b": "《后汉书·孔僖传》"}]}, {"meaning": "古代上公穿的礼服,绣有龙纹。龙首向下,与天子礼服有别。后世称三公为衮。", "cites": [{"t": "服衮而朝。", "b": "《后汉书·张衡传》"}]}, {"meaning": "指天子。", "cites": [{"t": "弘纲既整,衮阙以补。", "b": "汉·蔡邕《胡公碑》"}], "words": [{"w": "衮职", "t": "指君主的职位"}, {"w": "衮阙", "t": "喻君主的过失。"}]}, {"meaning": "指三公。", "cites": [{"t": "七在卿校,殊位特进;五登衮职,弭难入宁。", "b": "《后汉书·僖賜传》"}]}, {"meaning": "(弭:止息;入,安定。)。", "words": [{"w": "衮命", "t": "三公的职位"}, {"w": "衮司", "t": "指三公的职位"}, {"w": "衮华", "t": "借指三公的职位"}, {"w": "衮职", "t": "古代指三公的职位;亦借指三公。"}]}, {"meaning": "后多作“滚”。滚;滚动。", "cites": [{"t": "大孩儿闹攘攘,小孩儿衮球嬉嬉。", "b": "宋·佚名《大唐三藏取经诗话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4623wx','凋','1','diāo','冫','10','','[{"pinyin": "diāo", "defs": [{"meaning": "(形声。从仌(bīng),周声。“仌”,冻的意思。本义:草木衰落)。"}, {"meaning": "同本义。", "cites": [{"t": "凋,半伤也。", "b": "《说文》"}, {"t": "凋,伤也。", "b": "《广雅》"}, {"t": "为其凋荣也。", "b": "《战国策·秦策》"}, {"t": "卉既凋而已育。", "b": "《思元赋》。注:“落也。”"}], "words": [{"w": "凋萎", "t": "凋谢枯萎。植物的茎叶,因蒸散水分过多,补充不及,组织呈萎缩现象,不能保持固有的形状"}, {"w": "凋瘁", "t": "衰败枯萎"}, {"w": "凋霜", "t": "因霜冻而受到损伤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4624wx','颃','1','háng','页','10','','[{"pinyin": "háng", "defs": [{"meaning": "颈项。", "cites": [{"t": "亢,人颈也。或作颃。", "b": "《说文》"}]}, {"meaning": "鸟向下飞。", "cites": [{"t": "燕燕于飞,颉之颃之。", "b": "《诗·邶风》。毛传:飞而上曰颉,飞而下曰颃"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4625wx','恣','1','zì','心','10','','[{"pinyin": "zì", "defs": [{"meaning": "(形声。从心,次声。本义:放纵)。"}, {"meaning": "同本义。", "cites": [{"t": "恣,纵也。", "b": "《说文》"}, {"t": "所以禁民使不得自恣也。", "b": "《淮南书》。注:“放也。”"}, {"t": "遥荡恣雎。", "b": "《庄子·大宗师》。李注:“自得貌。”"}, {"t": "无正而恣雎。", "b": "《荀子·解蔽》"}, {"t": "而无道者之恣行。", "b": "《吕氏春秋·禁塞》"}, {"t": "纵情性,安恣睢禽兽之行。", "b": "《荀子·非十二子》"}, {"t": "有无下而不恣睢。", "b": "《史记·李斯传》"}, {"t": "人生老大须恣意,看君解作一身事。", "b": "李白《赋得还山吟送沈四山人》"}, {"t": "恃恩自恣。", "b": "宋·王谠《唐语林·雅量》"}], "words": [{"w": "恣逆", "t": "肆意篡逆"}, {"w": "恣逞", "t": "任意放肆"}, {"w": "恣横", "t": "放肆专横"}, {"w": "恣逸", "t": "放纵"}, {"w": "恣睢", "t": "放纵暴戾"}, {"w": "恣横", "t": "放纵专横"}, {"w": "恣擅", "t": "放肆专擅"}, {"w": "恣骜", "t": "放肆傲慢。"}]}, {"meaning": "听任;任凭。", "cites": [{"t": "恣君之所使。", "b": "《战国策·赵策》"}, {"t": "犹金之在炉,恣冶之所以铸。", "b": "《管子·任法》"}, {"t": "且乱军余党,恣为暴虐。", "b": "董解元《西厢记诸宫调》"}], "words": [{"w": "恣听", "t": "听任。"}]}, {"meaning": "更迭。", "cites": [{"t": "恣,代也。", "b": "《方言》"}], "words": [{"w": "恣作", "t": "交替而作。"}]}, {"meaning": "肆意;尽情。", "cites": [{"t": "过秦、汉之故都,恣观终南、嵩、华之高。", "b": "苏辙《上枢密韩太尉书》"}], "words": [{"w": "恣诡", "t": "奔放奇异"}, {"w": "恣饮", "t": "畅饮;痛饮"}, {"w": "恣游", "t": "纵屈游览;纵情游荡"}, {"w": "恣夸", "t": "奢侈无度。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4626wx','旆','1','pèi','方','10','','[{"pinyin": "pèi", "defs": [{"meaning": "(形声。本义:古代旐旗末端形如燕尾的垂旒飘带)。"}, {"meaning": "同本义。", "cites": [{"t": "旆,继旐之帛也。", "b": "《说文》"}, {"t": "白旆央央。", "b": "《诗·小雅·六月》"}], "words": [{"w": "旆旆", "t": "旗旒下垂的样子;生长茂盛的样子。"}]}, {"meaning": "泛指旌旗。", "cites": [{"t": "白旆,殷旌也。", "b": "《释名·释兵》"}, {"t": "拔旆投衡。", "b": "《左传·宣公十二年》。注:“大旗也。”"}, {"t": "亡大旆之左旃。", "b": "《左传·僖公二十六年》"}], "words": [{"w": "旆旃;旆旌", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4627wx','旄','1','máo mào','方','10','','[{"pinyin": "máo", "defs": [{"meaning": "同本义。", "cites": [{"t": "旄,幢也。", "b": "《说文》。本用妈犛牛尾,注于旗之竿首,故曰旄。后又用羽,或兼用氂与羽焉。"}, {"t": "右秉白旄。", "b": "《书·牧誓》"}, {"t": "建彼旄矣。", "b": "《诗·小雅·出车》"}, {"t": "见羽旄之美。", "b": "《孟子》"}, {"t": "总光耀之采旄。", "b": "《史记·司马相如传》"}, {"t": "乐师有旄舞。", "b": "《周礼·旄人》"}, {"t": "上将拥旄西出征。", "b": "岑参《轮台歌》"}], "words": [{"w": "旄钺", "t": "本为旗帜和兵器。代指军权"}, {"w": "旄麾", "t": "即旌麾。帅旗"}, {"w": "旄象", "t": "饰以象牙的旌旗。"}]}, {"meaning": "牦牛尾 。古代常作饰物。", "cites": [{"t": "羽旄齿革。", "b": "《国语·晋语》"}], "words": [{"w": "旄羽", "t": "牦牛尾和雉羽"}, {"w": "旄狄", "t": "即旄羽"}, {"w": "旄端", "t": "尾端。"}]}, {"meaning": "牦牛。", "cites": [{"t": "骍旄之盟。", "b": "《左传·襄公十年》"}], "words": [{"w": "旄尘", "t": "牦牛和尘"}, {"w": "旄毡", "t": "用牦牛毛制成的毛织品"}, {"w": "旄牛", "t": "即牦牛。"}]}, {"meaning": "旄丘。前高后低的山丘。", "cites": [{"t": "旄丘之葛兮。", "b": "《诗·邶风·旄丘》。传:“前高后下曰旄丘。”"}], "words": [{"w": "旄敦", "t": "旄丘与敦丘。"}]}, {"meaning": "", "cites": [{"t": "粪除其颠旄。", "b": "《管子·小匡》"}, {"t": "旄丘之葛兮,何诞之节兮。", "b": "《诗·邶风·旄丘》"}]}]}, {"pinyin": "mào", "defs": [{"meaning": "年老。", "cites": [{"t": "反其旄倪。", "b": "《孟子·梁惠王下》"}], "words": [{"w": "旄倪", "t": "老人和幼儿"}, {"w": "旄期", "t": "老年。"}]}, {"meaning": "眼睛昏花。", "cites": [{"t": "旄不知人。", "b": "《战国策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4628wx','旃','1','zhān','方','10','','[{"pinyin": "zhān", "defs": [{"meaning": "(形声,本义:赤色的曲柄旗)。"}, {"meaning": "同本义。", "cites": [{"t": "旃,旗曲柄也。周礼曰:“通帛为旃。", "b": "《说文》"}, {"t": "通帛为旃。通以赤色为之。", "b": "《释名·释兵》"}, {"t": "置旃以为辕门。", "b": "《谷梁传·昭公八年》"}]}, {"meaning": "亦泛指旌旗。", "cites": [{"t": "收功单于旃。", "b": "晋·陆机《饮马长城窟行》"}], "words": [{"w": "旃帛", "t": "红旗"}, {"w": "旃旌", "t": "泛指赤色旗帜"}, {"w": "旃戎", "t": "军旅。"}]}, {"meaning": "毛织品", "cites": [{"t": "不知其可以为旃也。", "b": "《淮南子·齐俗》"}, {"t": "被旃裘。", "b": "《史记·匈奴传》"}, {"t": "旃毛并咽之。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "旃席", "t": "毡帐"}, {"w": "旃衣", "t": "以毛毡等制成的衣服"}, {"w": "旃车", "t": "毡篷车"}, {"w": "旃席", "t": "毡席;毛毡。"}]}, {"meaning": "之、焉二字的合读。", "cites": [{"t": "上慎旃哉,犹来无止。", "b": "《诗·魏风·陟岵》。马瑞辰通释:“之、旃一声之转,又为‘之焉’之合声,故旃训‘之’,又训‘焉’。”"}], "words": [{"w": "勉旃", "t": "希望你奋发有为。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4629wx','阃','1','kǔn','门','10','','[{"pinyin": "kǔn", "defs": [{"meaning": "(形声。从门,困声。本义:门槛)。"}, {"meaning": "同本义。", "cites": [{"t": "阃以内者寡人制之。", "b": "《史记·冯唐传》"}, {"t": "无阃外之非仪也。", "b": "《孔子家语·本命》"}]}, {"meaning": "特指城门的门槛。", "cites": [{"t": "送迎不越阃。", "b": "李延寿《南史》"}], "words": [{"w": "阃阈", "t": "门限;门槛"}, {"w": "阃奥", "t": "门户。引申为要塞。"}]}, {"meaning": "指郭门。", "cites": [{"t": "阃以内者,寡人制之,阃以外者,将军制之。", "b": "《史记·张释之冯唐列传》"}], "words": [{"w": "阃外", "t": "本指城郭之外,引申为担任要职的人"}, {"w": "阃外之寄", "t": "战地指挥调度"}, {"w": "阃外将军", "t": "在都城以外领兵作战的将军。"}]}, {"meaning": "借指领兵在外的将帅或外任的大臣。", "cites": [{"t": "即具以北虚实告东西二阃。", "b": "宋·文天祥《指南录后序》"}], "words": [{"w": "阃望", "t": "将帅的威望"}, {"w": "阃幄", "t": "将帅的帐幕"}, {"w": "阃幕", "t": "将帅的府署"}, {"w": "阃帅", "t": "地方上的军事长官。"}]}, {"meaning": "妇女居住的地方,闺门,指妇女的居处。", "cites": [{"t": "内言不出于阃。", "b": "《礼记》"}], "words": [{"w": "阃令", "t": "阃:闺门。妻子的命令"}, {"w": "阃闱", "t": "妇女所居的内室。即壸闱。"}]}, {"meaning": "妻室;女人。", "cites": [{"t": "昔阃能臻是,今阃或过之。", "b": "《镜花缘》"}], "words": [{"w": "阃范", "t": "女子的风范;妇德"}, {"w": "阃德", "t": "妇德。阃指妇人居住的内室,故称妇德为阃德"}, {"w": "阃仪", "t": "妇女的容止"}, {"w": "阃政", "t": "妻子主持的家政。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4630wx','阄','1','jiū','门','10','','[{"pinyin": "jiū", "defs": [{"meaning": "写上字或画上记号的小纸团,供赌胜负或决定事情时抓取", "words": [{"w": "抓阄", "t": ""}, {"w": "纸阄", "t": ""}, {"w": "阄儿", "t": "即“阄”"}, {"w": "钻阄", "t": "抓阄"}]}, {"meaning": "拈阄,抓阄", "words": [{"w": "阄开", "t": "以抓阄的方式分开"}, {"w": "阄题", "t": "以抓阄确定题目"}, {"w": "阄定", "t": "用抓阄的办法定"}, {"w": "阄戏", "t": "抓阄游戏"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4631wx','訚','1','yín','言','10','','[{"pinyin": "yín", "defs": [{"meaning": "中正,和悦。", "cites": [{"t": "与上大夫言,訚訚如也。", "b": "《论语》"}], "words": [{"w": "訚訚", "t": "中正和敬的样子"}, {"w": "訚訚衍衍", "t": "中正和悦的样子。又称“訚訚侃侃”"}, {"w": "訚訚恻恻", "t": "和悦恳切的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4632wx','阆','1','làng','门','10','','[{"pinyin": "làng", "defs": [{"meaning": "门高大。", "cites": [{"t": "閬,门高也。从门,良声。", "b": "《说文》"}, {"t": "闶阆其寥廓兮。", "b": "《汉书·扬雄传》。注:“闶阆,空虚也。”"}], "words": [{"w": "阆阙", "t": "高大的门阙"}, {"w": "阆阆", "t": "高大的样子。"}]}, {"meaning": "空旷。", "cites": [{"t": "郭外为之土阆。", "b": "《管子·度地》。注:“空旷也。”"}], "words": [{"w": "闶阆", "t": "建筑物中空阔的部分。"}]}, {"meaning": "隍,无水的城壕。", "cites": [{"t": "城外为之郭,郭外为之土阆。", "b": "《管子》"}, {"t": "胞有重阆。", "b": "《庄子·外物》。注:“阆谓隍,又为朗。”"}]}, {"meaning": "阆风巅的省称 ,山名。传说中神仙居住的地方,在昆仑之巅,又称“阆风岑”、“阆风”、“阆邱”、“阆风台”、“阆山”等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4633wx','恙','1','yàng','心','10','','[{"pinyin": "yàng", "defs": [{"meaning": "(形声。从心,羊声。本义:担忧)。"}, {"meaning": "同本义。", "cites": [{"t": "何恙不已。", "b": "《史记》"}]}, {"meaning": "疾病。", "cites": [{"t": "当年秦大爷患恙,在我家庄上,住了年余,怎说不认得?", "b": "《隋唐演义》"}, {"t": "君其专精神,微恙不足论。", "b": "秦观《答文潜病中见寄》"}], "words": [{"w": "贱恙", "t": ""}]}]}]','jingmo-wenyan');
