INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4635wx','朔','1','shuò','月','10','','[{"pinyin": "shuò", "defs": [{"meaning": "(会意。从月,从屰,屰(nì)亦声。本义:农历每月初一)。"}, {"meaning": "同本义。", "cites": [{"t": "朔,月一日始苏也。", "b": "《说文》。按,凡月与日同经度不同纬度则为合朔,同经度又同纬度即为日蚀。计173日有奇。"}, {"t": "朔,月初之名也。", "b": "《释名》"}, {"t": "月言朔。", "b": "《白虎通·四时篇》"}, {"t": "朔月奠。", "b": "《仪礼·士丧礼》。注:“朔月,月朔也。”"}, {"t": "朔月辛卯。", "b": "《诗·小雅·十月之交》"}, {"t": "初,薙发令下,诸生许用德者以闰六月朔,县明太祖御容明伦堂,率众拜且苦。", "b": "清·邵长蘅《阎典史传》"}], "words": [{"w": "朔参官", "t": "能在朔日朝参的官员"}, {"w": "朔望之礼", "t": "指初一、十五到祀堂祭祀的礼节"}, {"w": "朔望之辰", "t": "农历每月初一、十五的时候"}, {"w": "朔晦", "t": "朔日和晦日"}, {"w": "朔法", "t": "确定朔日的方法"}, {"w": "朔数", "t": "从第一年正月初一到第二年正月初一"}, {"w": "朔食", "t": "古礼之一。帝王及贵族每月初一所备较平日丰盛的膳食"}, {"w": "朔旦", "t": "旧历每月初一。"}]}, {"meaning": "朔政,历政,指中国古代帝王每年冬季发布来年十二个月的政事于诸侯,诸侯亦于月初告祖庙,受而行之。", "cites": [{"t": "颁告朔于邦国。", "b": "《周礼》"}]}, {"meaning": "凌晨,清晨。", "cites": [{"t": "朝菌不知晦朔,蟪蛄不知春秋。", "b": "《庄子》"}]}, {"meaning": "初,始。", "cites": [{"t": "皆从其朔。", "b": "《礼记·礼运》"}]}, {"meaning": "北方。", "cites": [{"t": "城彼朔方。", "b": "《诗·小雅·出车》"}, {"t": "平在朔易。", "b": "《书·尧典》"}, {"t": "朔,北方也。", "b": "《尔雅》"}], "words": [{"w": "朔风凛凛", "t": "北风寒冷"}, {"w": "朔北", "t": "长城以北"}, {"w": "朔土", "t": "北方地区"}, {"w": "朔垂", "t": "西北边远地区"}, {"w": "朔门", "t": "北方边境之地"}, {"w": "朔庭", "t": "北方异族政权"}, {"w": "朔客", "t": "北方边地的将领"}, {"w": "朔气", "t": "北方之寒气"}, {"w": "朔野", "t": "北方荒野之地"}, {"w": "朔雪", "t": "北方的雪。"}]}, {"meaning": "车辕。一说,车上的旗。", "cites": [{"t": "月之旦为朔,车之輈亦谓之朔,名齐实异,所宜辨也。", "b": "《西京杂记》"}]}, {"meaning": "生,出现。", "cites": [{"t": "天地虹洞,固无端涯,大明生东,月朔西陂。", "b": "《后汉书》"}]}, {"meaning": "每月初省视。", "cites": [{"t": "乃召昆吾冶而铭之金版,藏府而朔之。", "b": "《逸周书》"}]}]}]','jingmo-wenyan');
