('4636wx','郸','1','dān','阝','10','','[{"pinyin": "dān", "defs": [{"meaning": "—地名用字。“邯郸”。", "cites": [{"t": "郸,邯郸县,从邑,单声。", "b": "《说文》"}]}, {"meaning": "在河北省。“郸城”,县名,在河南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4637wx','烜','1','xuǎn','火','10','','[{"pinyin": "xuǎn", "defs": [{"meaning": "(形声。从火,亘(yuán)声。本义:火旺)。"}, {"meaning": "同本义。", "cites": [{"t": "烜,火盛貌。", "b": "《玉篇》"}], "words": [{"w": "烜烈", "t": "火盛。"}]}, {"meaning": "显著,显赫。", "cites": [{"t": "赫兮烜兮,威仪也。", "b": "《尔雅》"}], "words": [{"w": "烜卓", "t": "卓著"}, {"w": "烜奕", "t": "显赫"}, {"w": "烜然", "t": "显赫的样子。"}]}, {"meaning": "曝晒;晒干。", "cites": [{"t": "雨以润之,日以烜之。", "b": "《易·说卦》"}]}, {"meaning": "照亮。", "cites": [{"t": "他又不通过名目,把小李村围住,烜天地烧着草垛。", "b": "《刘知远诸宫调》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4638wx','烨','1','yè','火','10','','[{"pinyin": "yè", "defs": [{"meaning": "火盛,明亮,引伸为光辉灿烂。", "cites": [{"t": "烨烨震电。", "b": "《诗·小雅·十日之交》"}], "words": [{"w": "烨然", "t": "光彩鲜明的样子"}, {"w": "烨烨", "t": "明亮;灿烂;鲜明"}, {"w": "烨烁", "t": "光耀"}, {"w": "烨煜", "t": "光华闪烁的;乐音繁盛"}, {"w": "烨赫", "t": "辉煌显赫"}, {"w": "烨熠", "t": "光耀。"}]}]}]','jingmo-wenyan');
