('4640wx','烊','1','yáng yàng','火','10','','[{"pinyin": "yáng", "defs": [{"meaning": "(形声。从火,羊声。本义:金属熔化)。", "cites": [{"t": "半霎功夫,墨盒里冒白气,下半边已烊了。", "b": "《老残游记》"}], "words": [{"w": "烊铜热铁", "t": "烧热的铜铁器具。借指地狱中烙烫之类的刑具。"}]}]}, {"pinyin": "yàng", "defs": [{"meaning": "——见“打烊”(dǎyàng)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4641wx','剡','1','shàn yǎn','刂','10','','[{"pinyin": "shàn", "defs": [{"meaning": "水名,即剡溪。在浙江省曹娥江上游。", "cites": [{"t": "明月照我影,送我至剡溪。", "b": "唐·李白《梦游天姥吟留别》诗"}]}]}, {"pinyin": "yǎn", "defs": [{"meaning": "(形声。从刀,炎声。本义:削)。"}, {"meaning": "削;削尖。", "cites": [{"t": "剡,锐利也。", "b": "《说文》"}, {"t": "古者剡耜而耕。", "b": "《淮南子·泛论》"}, {"t": "曾枝剡棘。", "b": "《楚辞·橘颂》"}, {"t": "刳木为舟,剡木为楫。", "b": "《易·系辞下》"}], "words": [{"w": "剡章", "t": "削牍写成奏章。泛指写奏章"}, {"w": "剡麻", "t": "缀缉麻缕。"}]}, {"meaning": "举,举起。", "cites": [{"t": "视可,司间,案欲剡其胫而以蹈秦之腹也。", "b": "《荀子》"}]}, {"meaning": "锐利。", "cites": [{"t": "曾枝剡棘,圆果搏兮。", "b": "《楚辞》"}], "words": [{"w": "剡利", "t": "锐利"}, {"w": "剡耜", "t": "锋利的耒耜"}, {"w": "剡剡", "t": "锐利貌"}, {"w": "剡锋", "t": "锐利的锋刀"}, {"w": "剡注", "t": "古代五射之一。"}]}]}]','jingmo-wenyan');
