INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4643wx','烬','1','jìn','火','10','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从火,尽声。本义:物体燃烧后的剩余)。"}, {"meaning": "同本义。", "cites": [{"t": "请收合余烬。", "b": "《左传·成公二年》"}, {"t": "烛烬夜有数升。", "b": "《北史·吕思礼传》"}], "words": [{"w": "灰烬;余烬;烬灰", "t": "灰烬"}, {"w": "烬骨", "t": "骨灰。"}]}, {"meaning": "残余、剩余或残迹。", "cites": [{"t": "民靡有黎,具祸以烬。", "b": "《诗·大雅·桑柔》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4644wx','涑','1','sù','氵','10','','[{"pinyin": "sù", "defs": [{"meaning": "水名。涑水 。在山西省西南部,源出绛县太阴山,流经闻喜、临猗,至永济县西南入黄河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4645wx','浯','1','wú','氵','10','','[{"pinyin": "wú", "defs": [{"meaning": "水名 。在山东省东部。源出沂山东麓,东北流经安丘、诸城两县境入潍河。"}, {"meaning": "山名 。在山东省莒县北,又名巨平山、壶山。", "cites": [{"t": "浯水注之。水出浯山,世谓之巨平山也。", "b": "《水经注》"}]}, {"meaning": "古地名。即“苍梧” 。在今广西境内。", "cites": [{"t": "以像湡、浯。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4646wx','涞','1','lái','氵','10','','[{"pinyin": "lái", "defs": [{"meaning": "指涞水,又名拒马河,发源于河北省涞源县。", "cites": [{"t": "涞,水。起北地广昌,东入河。", "b": "《说文》"}]}, {"meaning": "流动性的厘米·克·秒制单位;泊(粘滞性单位)的倒数。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4647wx','涟','1','lián','氵','10','','[{"pinyin": "lián", "defs": [{"meaning": "小波,风吹水面所形成的波纹。", "cites": [{"t": "河水清且涟漪。", "b": "《诗·魏风·伐檀》"}], "words": [{"w": "涟猗", "t": "波纹,小水波。"}]}, {"meaning": "水名。"}, {"meaning": "在江苏省涟水县北,一名涟河。"}, {"meaning": "在湖南省中部,源出新邵县,东流经湘乡,至湘潭注入湘江。"}, {"meaning": "泪流不断的样子。", "cites": [{"t": "不见复关,泣涕涟涟。", "b": "《诗·魏风·氓》"}, {"t": "中心孔悼,涕泪涟湎。", "b": "王粲《赠蔡子笃》"}], "words": [{"w": "涟如", "t": "涟洳,涟湎。泪涕交流的样子"}, {"w": "涟落", "t": "泪珠下滴"}, {"w": "涟涟", "t": "泪流不止的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4648wx','娑','1','suō','女','10','','[{"pinyin": "suō", "defs": [{"meaning": "(形声。从女,沙声。本义:起舞的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "娑,舞也。", "b": "《说文》。"}, {"t": "子仲之子,婆娑其下。", "b": "《诗·陈风·东门之枌》"}]}, {"meaning": "漂动、轻扬的样子。", "cites": [{"t": "脩初服之娑娑兮,长余之参参。", "b": "《后汉书·张衡传·思玄赋》"}], "words": [{"w": "娑娑", "t": "漂扬的样子。"}]}, {"meaning": "挑逗。", "cites": [{"t": "闹清明莺声婉啭,荡花枝蝶翅蹁跹,舞东风剪尾娑人。", "b": "元·无名氏《焚儿救母》"}], "words": [{"w": "娑人", "t": "挑逗人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4649wx','涅','1','niè','氵','10','','[{"pinyin": "niè", "defs": [{"meaning": "(形声。从水,从土,曰声。本义:可做黑色染料的矾石)。"}, {"meaning": "同本义。", "cites": [{"t": "涅,黑土在水中者也。", "b": "《说文》"}, {"t": "女床之山,其阴多石涅。", "b": "《西山经》"}, {"t": "今以涅染缁,则黑于涅。", "b": "《淮南子·俶真》"}], "words": [{"w": "涅石", "t": "黑矾石,可为染料。"}]}, {"meaning": "黑泥。", "cites": [{"t": "蓬生麻中,不扶而直,白沙在涅,与之俱黑。", "b": "《荀子》"}]}, {"meaning": "古代河流名 。在今山西、河南、广东都有涅水。"}, {"meaning": "染黑。", "cites": [{"t": "涅而不缁。", "b": "《论语·阳货》"}], "words": [{"w": "涅齿", "t": "染黑牙齿"}, {"w": "涅污", "t": "染污。"}]}, {"meaning": "纹身。", "cites": [{"t": "是主家私自黥涅。", "b": "范成大《清远店诗·序》"}], "words": [{"w": "涅墨", "t": "在人身上刺字或刺成图案,再涂以墨"}, {"w": "涅手", "t": "在手臂上刺字涂墨"}, {"w": "涅文", "t": "纹身的文字或图案"}, {"w": "涅面", "t": "在脸上刺字或刺图案。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4650wx','涠','1','wéi','氵','10','','[{"pinyin": "wéi", "defs": [{"meaning": "混浊的积水。", "cites": [{"t": "世细各乘运,湍涠亦腾声。", "b": "唐·韩愈、孟郊《城南联句》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
