('4652wx','涓','1','juān','氵','10','','[{"pinyin": "juān", "defs": [{"meaning": "(形声。从水,肙(yuān)声。本义:细小的水流)。"}, {"meaning": "同本义。", "cites": [{"t": "涓,小流也。", "b": "《说文》"}, {"t": "涓流泱瀼。", "b": "木华《海赋》"}, {"t": "商攉涓浍。", "b": "郭璞《江赋》"}, {"t": "泉涓涓而始流。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "涓浍", "t": "细小的水流;卑微的地位"}, {"w": "涓浅", "t": "指水流又细又浅"}, {"w": "涓细", "t": "水流细小"}, {"w": "涓尘", "t": "细水与微尘。"}]}, {"meaning": "水名。"}, {"meaning": "源出今山东省诸城县西南,北注入潍水。"}, {"meaning": "湘江支流。源出衡山北麓,北流至湘潭县注入湘江。"}, {"meaning": "选择。", "cites": [{"t": "涓吉日,陟中坛,即帝位,改正朔。", "b": "左思《魏都赋》"}], "words": [{"w": "涓辰", "t": "选择吉日良辰"}, {"w": "涓吉", "t": "选择大吉的日子"}, {"w": "涓日", "t": "涓吉"}, {"w": "涓选", "t": "选择,选取。"}]}, {"meaning": "清除;洗刷。", "cites": [{"t": "乃兄其涓人畴。", "b": "《国语·吴语》"}], "words": [{"w": "涓人", "t": "古代宫中担任洒扫清洁的人"}, {"w": "涓洁", "t": "洁净清洁。"}]}, {"meaning": "比喻很小、微小或细小。", "cites": [{"t": "重露成涓滴,稀量乍有无。", "b": "杜甫《倦夜》"}], "words": [{"w": "涓然", "t": "流泪的样子"}, {"w": "涓波", "t": "微波。比喻微小事物"}, {"w": "涓毫", "t": "喻微末"}, {"w": "涓壤", "t": "涓埃。喻微末。"}]}]}]','jingmo-wenyan');
