INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4654wx','涔','1','cén','氵','10','','[{"pinyin": "cén", "defs": [{"meaning": "(形声。从水,岑(cēn)声。本义:连续下雨,积水成涝)。"}, {"meaning": "同本义。", "cites": [{"t": "涔,渍也。", "b": "《说文》"}, {"t": "夫牛蹄之涔,不能生鳝鲔。", "b": "《淮南子·泛论》"}], "words": [{"w": "涔旱", "t": "涝灾与旱灾。"}]}, {"meaning": "路上的积水。", "cites": [{"t": "牛蹄之涔,无尺之鲤。", "b": "《淮南子·俶真》"}], "words": [{"w": "涔蹄", "t": "积水的蹄迹"}, {"w": "涔水", "t": "雨后积水。"}]}, {"meaning": "雨多,涝渍。", "cites": [{"t": "宫池涔则溢。", "b": "《淮南子·说林》"}], "words": [{"w": "涔云", "t": "含雨的浓云"}, {"w": "涔滴", "t": "一点点地流淌。"}]}, {"meaning": "泪落不止的样子。", "cites": [{"t": "涔泪犹在袂。", "b": "江淹《赠别》"}], "words": [{"w": "涔泪", "t": "流下的眼泪。"}]}]}]','jingmo-wenyan');
