('4657wx','浣','1','huàn','氵','10','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从水,完声。本义:洗衣服)。"}, {"meaning": "同本义。", "cites": [{"t": "浣,濯衣垢也。", "b": "《说文》"}, {"t": "竹喧归浣女,莲动下渔舟。", "b": "王维《山居秋暝》"}], "words": [{"w": "浣衣", "t": "洗衣"}, {"w": "浣拭", "t": "洗涤擦拭"}, {"w": "浣染", "t": "洗染。"}]}, {"meaning": "洗涤,涤除。", "cites": [{"t": "湔浣肠胃。", "b": "《史记·扁鹊仓公列传》"}], "words": [{"w": "浣雪", "t": "洗刷罪名。"}]}, {"meaning": "唐代定制,官吏十天一次休息、沐浴,每月分为上浣、中浣、下浣,后来借做上旬、中旬、下旬的别称。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4658wx','浚','1','jùn xùn','氵','10','','[{"pinyin": "jùn", "defs": [{"meaning": "(形声。从水,雋(jùn)声。本义:从水中挹取)。"}, {"meaning": "同本义。", "cites": [{"t": "浚,抒也。", "b": "《说文》。段玉裁注:“抒者,挹也,取诸水中也。”"}]}, {"meaning": "疏浚;深挖。", "cites": [{"t": "封十有二山,浚川。", "b": "《书·舜典》"}, {"t": "冬,浚洙。", "b": "《春秋·庄公九年》"}, {"t": "浚之者何?深也。", "b": "《公羊传·庄公九年》"}, {"t": "浚沟渠。", "b": "《汉书·赵充国传》"}, {"t": "浚其源泉。", "b": "唐·魏征《谏太宗十思疏》"}, {"t": "浚吴淞白茆。", "b": "清·张廷玉《明史》"}], "words": [{"w": "浚池", "t": "挖掘或疏通护城河"}, {"w": "浚治", "t": "疏浚"}, {"w": "浚流", "t": "疏浚河流"}, {"w": "浚泻", "t": "疏浚使排泄。"}]}, {"meaning": "压榨,取出汁水或内含物。", "cites": [{"t": "浚民之膏济以实之。", "b": "《国语·晋语》"}], "words": [{"w": "浚削", "t": "榨取;搜刮"}, {"w": "浚财", "t": "搜刮钱财。"}]}, {"meaning": "深。", "cites": [{"t": "浚恒。", "b": "《易·恒传》"}, {"t": "莫浚匪泉。", "b": "《诗·小雅·小弁》"}, {"t": "冬,浚洙。", "b": "《左传·庄公九年》"}], "words": [{"w": "浚谷", "t": "深谷"}, {"w": "浚堑", "t": "深沟"}, {"w": "浚窥", "t": "深入窥察"}, {"w": "浚泽", "t": "深泽"}, {"w": "浚照", "t": "水深而明澈"}, {"w": "浚流", "t": "深流。"}]}, {"meaning": "古水名 。今湮。故渎在今河南省开封市北。"}, {"meaning": "春秋时卫邑,故址在今河南省濮阳县境。"}]}, {"pinyin": "xùn", "defs": [{"meaning": "县名  在河南省安阳地区。"}]}]','jingmo-wenyan');
