('4663wx','悌','1','tì','忄','10','','[{"pinyin": "tì", "defs": [{"meaning": "(形声。从心,弟声。本义:敬爱兄长) 同本义。亦泛指敬重长上。", "cites": [{"t": "孝悌之义。", "b": "《孟子·梁惠王上》"}, {"t": "悌,善兄弟也。", "b": "《说文》"}, {"t": "弟爱兄谓之悌。", "b": "贾谊《道术》"}], "words": [{"w": "悌达", "t": "悌顺。敬爱和顺。"}]}, {"meaning": "和易 。", "words": [{"w": "恺悌", "t": "和乐平易"}, {"w": "悌睦", "t": "和睦。"}]}, {"meaning": "用同“体”。亲近 。", "words": [{"w": "悌己人", "t": "亲信"}, {"w": "悌友", "t": "兄弟姊妹间亲密和睦。"}]}]}]','jingmo-wenyan');
