('4664wx','悛','1','quān','忄','10','','[{"pinyin": "quān", "defs": [{"meaning": "(形声。本义:停止)。"}, {"meaning": "同本义。", "cites": [{"t": "悛,止也。", "b": "《说文》"}, {"t": "长恶不悛。", "b": "《左传·隐公六年》"}, {"t": "康犹不悛。", "b": "《左传·成公十三年》"}, {"t": "其有悛乎?", "b": "《国语》"}]}, {"meaning": "悔改;改变。", "cites": [{"t": "悛,更也。", "b": "《广雅·释诂三》"}, {"t": "亦无悛容。", "b": "《左传·襄公七年》"}, {"t": "为是悛而止。", "b": "《左传·昭公九年》"}, {"t": "过而不悛。", "b": "《韩非子·难四》"}], "words": [{"w": "怙恶不悛;悛志", "t": "悔改之意"}, {"w": "悛改", "t": "后悔而改过"}, {"w": "悛心", "t": "悔改之心"}, {"w": "悛革", "t": "悔改"}, {"w": "悛悟", "t": "悔悟"}, {"w": "悛悔", "t": "悔改;悔悟"}, {"w": "悛容", "t": "悔改的表情"}, {"w": "悛移", "t": "悔改"}, {"w": "悛惕", "t": "悔悟戒惧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4665wx','宸','1','chén','宀','10','','[{"pinyin": "chén", "defs": [{"meaning": "(形声。从宀(mián),辰声。从“宀”,表示与房屋有关。本义:屋檐)。"}, {"meaning": "同本义。", "cites": [{"t": "宸,屋宇也。", "b": "《说文》"}, {"t": "而为敝邑宸宇。", "b": "《国语·越语》。注:“屋霤。”"}, {"t": "消雰埃于中宸。", "b": "张衡《西京赋》。注:“天地之交宇也。”"}], "words": [{"w": "宸宇", "t": "屋檐。比喻庇荫。"}]}, {"meaning": "又深又大的房屋。", "cites": [{"t": "宸,贾逵曰:室之奥者。", "b": "《玉篇》"}]}, {"meaning": "帝王的住处。", "cites": [{"t": "宸扉既辟。", "b": "王勃《九成宫颂》"}], "words": [{"w": "宸扉", "t": "宫门。"}]}, {"meaning": "帝王、王位的代称。", "cites": [{"t": "后有一行小字:“某年某月日,书赐荣国公贾源”,又有“万机宸翰之宝”。", "b": "《红楼梦》。注:翰,墨迹,书法。"}], "words": [{"w": "宸游", "t": "旧称皇帝出游"}, {"w": "宸极", "t": "北极星,喻帝王。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4666wx','窈','1','yǎo','穴','10','','[{"pinyin": "yǎo", "defs": [{"meaning": "(形声。从穴,幼声。本义:幽深,深远)。"}, {"meaning": "同本义。", "cites": [{"t": "窈,深远也。", "b": "《说文》"}, {"t": "窈,深也。", "b": "《广雅》"}, {"t": "窈兮冥兮。", "b": "《老子》。王注:“深远之叹。”"}, {"t": "窈冥昼晦。", "b": "《史记·项羽记》"}, {"t": "至道之精,窈窈冥冥。", "b": "《庄子·在宥》"}, {"t": "由山上五六里,有穴窈然。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "窈杳", "t": "幽远的样子"}, {"w": "窈纠", "t": "幽深曲折"}, {"w": "窈悠", "t": "深远的样子"}, {"w": "窈陷", "t": "深凹"}, {"w": "窈妙", "t": "精微,幽远"}, {"w": "窈冥", "t": "深远难测"}, {"w": "窈坳", "t": "幽怨"}, {"w": "窈郁", "t": "幽深的样子"}, {"w": "窈丽", "t": "幽深而秀丽"}, {"w": "窈蔼", "t": "深远;幽暗"}, {"w": "窈停", "t": "深目高鼻的样子"}, {"w": "窈深", "t": "幽深;深邃"}, {"w": "窈黑", "t": "深邃幽暗"}, {"w": "窈然", "t": "深远的样子;幽深的样子"}, {"w": "窈蔚", "t": "幽深繁茂。"}]}, {"meaning": "幽静。", "cites": [{"t": "高堂俨象设,禅室各深窈。", "b": "苏轼《与客游道场何山得写字》"}], "words": [{"w": "窈寞", "t": "幽静"}, {"w": "窈峭", "t": "高峻峭拨。"}]}, {"meaning": "昏暗。", "cites": [{"t": "天窈窈而昼阴。", "b": "司马相如《长门赋》。《说文》:“杳,冥也,当以杳为正字,窈通字。”"}, {"t": "窈霭潇湘空。", "b": "江淹《杂体诗》"}], "words": [{"w": "窈昧", "t": "幽暗"}, {"w": "窈窈", "t": "深冥的样子;幽暗的样子。"}]}, {"meaning": "美好。", "cites": [{"t": "月华临夜空,青山窈多姿。", "b": "清·吴光《泊湘口二妃庙是萧湘二水会处》"}], "words": [{"w": "窈妙", "t": "美好"}, {"w": "窈纠", "t": "形容步履舒缓,体态优美"}, {"w": "窈娜", "t": "形容体态柔美"}, {"w": "窈娆", "t": "轻柔细长的样子"}, {"w": "窈眇", "t": "美妙,美好。"}]}, {"meaning": "(yōu)。隐蔽,隐微。", "cites": [{"t": "可以阴,可以阳;可以窈,可以明。", "b": "《淮南子·道应》。俞樾云:“窈,读为幽。”"}, {"t": "扬沙石,窈冥昼晦。", "b": "《史记·项羽本纪》"}]}]}]','jingmo-wenyan');
