('4667wx','剜','1','wān','刂','10','','[{"pinyin": "wān", "defs": [{"meaning": "(形声。从刀,宛声。本义:挖)。"}, {"meaning": "同本义。", "cites": [{"t": "韩当急为脱去温衣,用力剜出箭头。", "b": "明·罗贯中《全图绣像三国演义》"}], "words": [{"w": "剜野菜;剜补", "t": "挖出错字,补上正字"}, {"w": "剜挑", "t": "抠挖"}, {"w": "剜改", "t": "挖出错字,改成正字"}, {"w": "剜肉医疮", "t": "比喻只顾眼前之急,不惜采用有害之法。"}]}, {"meaning": "以刀子等除去。", "cites": [{"t": "剜,削也。", "b": "《说文新附》"}, {"t": "剜,刻削也。", "b": "《广韵》"}], "words": [{"w": "剜肉生(做,成,补)疮(本想割肉医疮,但被割之处反成新疮比喻行事只顾一面,结果与预想适得其反)", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4668wx','诹','1','zōu','讠','10','','[{"pinyin": "zōu", "defs": [{"meaning": "(形声。从言,取声。本义:咨询;询问)。"}, {"meaning": "同本义(征求关于祭祀、征伐或行政管理方面的意见)。", "cites": [{"t": "诹,聚谋也。", "b": "《说文》"}, {"t": "诹,谋也。", "b": "《尔雅》"}, {"t": "周爰咨诹。", "b": "《诗·小雅·皇皇者华》"}, {"t": "咨事为诹。", "b": "《左传·襄公四年》"}, {"t": "咨才为诹。", "b": "《国语·鲁语》"}, {"t": "以咨诹善道。", "b": "诸葛亮《出师表》"}], "words": [{"w": "诹访", "t": "咨询"}, {"w": "诹咨", "t": "询问"}, {"w": "诹询", "t": "咨询。"}]}, {"meaning": "挑选。", "cites": [{"t": "特牲馈食之礼,不诹日。", "b": "《仪礼》"}], "words": [{"w": "诹日", "t": "诹吉。选择吉日。"}]}, {"meaning": "商议。", "cites": [{"t": "预柬凡十有八人,德棻为先进,故类例多所诹定。", "b": "《新唐书》"}], "words": [{"w": "诹治", "t": "商议治理"}, {"w": "诹度", "t": "商议斟酌"}, {"w": "诹谋", "t": "谋议;商议。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4669wx','冢','1','zhǒng','冖','10','','[{"pinyin": "zhǒng", "defs": [{"meaning": "(形声。从宀(mì),豕(chù)声。冖,表地覆盖。将死者覆盖于墓中,故从冖。本义:高而大的坟)。"}, {"meaning": "同本义。", "cites": [{"t": "冢,高坟也。", "b": "《说文》"}, {"t": "掌公墓之地。", "b": "《周礼·冢人》"}, {"t": "冢,秦晋之间或谓之陇。", "b": "《方言十三》"}, {"t": "乃立冢土。", "b": "《诗·大雅·緜》。传:“大社也。”即祭土神的高大土坛。"}, {"t": "项羽烧秦宫室,掘始皇帝冢。", "b": "《史记·高祖本纪》"}, {"t": "其下两冢。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "野冢", "t": "荒郊野外的乱坟"}, {"w": "疑冢", "t": "古代富贵之家所设的假坟,为的是与真坟相混,不让后人认出真坟"}, {"w": "冢人", "t": "古代管理墓葬的官吏"}, {"w": "冢土", "t": "墓土;又指大社,天子祭神的地方"}, {"w": "冢田", "t": "墓地"}, {"w": "冢宅", "t": "坟墓,坟地"}, {"w": "冢舍", "t": "墓旁守丧人的住所。"}]}, {"meaning": "山顶。", "cites": [{"t": "山顶,冢。", "b": "《尔雅》"}, {"t": "华山冢也。", "b": "《山海经·西山经》。注:“冢者,神鬼之所居也。”"}, {"t": "百川沸腾,山冢崒崩。", "b": "《诗·小雅·十月之交》。郑玄注:“山顶曰冢。”"}, {"t": "夜防抄盗保深山,朝望烟尘上高冢。", "b": "元稹《蛮子朝》"}]}, {"meaning": "大的;地位高的。", "cites": [{"t": "冢,大也。", "b": "《尔雅》"}, {"t": "冢者,大也。", "b": "《白虎通》"}, {"t": "我友邦冢君。", "b": "《书·牧誓》"}, {"t": "乃立天官冢宰。", "b": "《周礼》"}, {"t": "王乃召冢卿。", "b": "《周书·大匡》"}, {"t": "冢子则太牢。", "b": "《礼记·内则》"}], "words": [{"w": "冢臣", "t": "大臣;朝廷重臣"}, {"w": "冢司", "t": "宰相的别称"}, {"w": "冢祀", "t": "古代天子在宗庙里举行的大祭礼"}, {"w": "冢卿", "t": "上卿,孤卿"}, {"w": "冢君", "t": "大君,对列国君主的敬称。"}]}, {"meaning": "嫡生的。正宗的,不是旁支的。", "cites": [{"t": "冢嫡欲废夺,骨肉相忧疑。", "b": "白居易《答四皓庙》"}], "words": [{"w": "冢嫡", "t": "嫡长子"}, {"w": "冢子", "t": "长子"}, {"w": "冢息", "t": "长子"}, {"w": "冢孙", "t": "嫡长孙"}, {"w": "冢妇", "t": "嫡长子之妻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4670wx','诼','1','zhuó','讠','10','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从言,豖(chù)声。本义:造谣,谗谤) 同本义。", "cites": [{"t": "众女嫉余之蛾眉兮,谣诼谓余以善淫。", "b": "《楚辞》"}, {"t": "被诼谮兮虚获尤。", "b": "王逸《九思·逢尤》"}], "words": [{"w": "诼潜", "t": "造谣诬陷"}, {"w": "诼谣", "t": "毁谤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4671wx','袒','1','tǎn','衤','10','','[{"pinyin": "tǎn", "defs": [{"meaning": "(形声。从衣,旦声。本义:绽开)。"}, {"meaning": "同本义。", "cites": [{"t": "袒,衣缝解也。", "b": "《说文》"}]}, {"meaning": "脱去上衣,露出身体的一部分。", "cites": [{"t": "乃右肉袒于庙门之东。", "b": "《仪礼·遂觏礼》"}, {"t": "劳毋袒。", "b": "《礼记·曲礼》"}, {"t": "袒右。", "b": "《史记·陈涉世家》"}, {"t": "袒胸露乳。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "袒臂", "t": "袒露胳膊。表示奋发、激昂或愿意归降"}, {"w": "袒肉", "t": "脱去上衣,裸露肢体。古人谢罪或祭礼时的一种表示"}, {"w": "袒肩", "t": "袒膊。袒露右肩"}, {"w": "袒开", "t": "袒露解开。"}]}, {"meaning": "古代行礼时脱去上衣的左袖,露出裼衣。", "cites": [{"t": "于是汉王为义帝发丧,袒而大哭。", "b": "《汉书·高帝纪》"}], "words": [{"w": "袒左", "t": "古代行礼时,袒出上衣之左袖,以左袖插入前襟之右,而露出裼衣,或袒所有衣服之左袖,而露出左臂。古代凡礼事皆左袒"}, {"w": "袒免亲", "t": "指五服以外的远亲"}, {"w": "袒哭", "t": "袒左痛哭。古代哀悼死者的一种表示"}, {"w": "袒裘", "t": "谓在君之侧袒出正服、裼衣、皮衣的左袖而露出中衣。是一种违礼不敬之举"}, {"w": "袒裼", "t": "脱去上衣左袖,露出内衣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4672wx','袢','1','fán pàn','衤','10','','[{"pinyin": "fán", "defs": [{"meaning": "夏天穿的白色内衣。", "cites": [{"t": "袢,无色也。从衣,半声。", "b": "《说文》。朱骏声曰:“袢当为里衣之称。里衣素无色,当暑用絺袢,即绉絺也。”"}, {"t": "蒙彼縐絺,是绁袢也。", "b": "《诗·鄘风·君子偕老》"}]}]}, {"pinyin": "pàn", "defs": [{"meaning": ""}]}]','jingmo-wenyan');
