('4673wx','祯','1','zhēn','礻','10','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从示,贞声。从示,与祯祥灾祸有关。本义:吉祥) 同本义。", "cites": [{"t": "祯,祥也。", "b": "《说文》"}, {"t": "必有祯祥。", "b": "《礼记·中庸》"}, {"t": "祯,福也。", "b": "《字林》"}, {"t": "迄用有成,维周之祯。", "b": "《诗·周颂·维清》"}], "words": [{"w": "祯祥", "t": "吉祥的征兆"}, {"w": "祯泰", "t": "吉祥安定"}, {"w": "祯符", "t": "祥瑞;吉兆"}, {"w": "祯祺", "t": "吉祥。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4674wx','诿','1','wěi','讠','10','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从言,委声。本义:累;烦劳)。"}, {"meaning": "同本义。", "cites": [{"t": "诿,累也。", "b": "《说文》"}]}, {"meaning": "委托;连累。", "cites": [{"t": "诿者,托也。", "b": "《汉书·贾谊传》注"}], "words": [{"w": "诿托", "t": "委托;付托"}, {"w": "诿属", "t": "委托嘱咐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4675wx','谀','1','yú','讠','10','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从言,臾声。本义:奉承,谄媚) 同本义。", "cites": [{"t": "谀,谄也。", "b": "《说文》"}, {"t": "不择是非而言谓之谀。", "b": "《庄子·渔夫》"}, {"t": "以不善和人者谓之谀。", "b": "《荀子·脩身》"}, {"t": "从命病君谓之谀。", "b": "《说苑·臣术》"}, {"t": "官盛则近谀。", "b": "唐·韩愈《师说》"}, {"t": "诬谀之徒。", "b": "唐·柳宗元《柳河东集》"}, {"t": "谄谀之臣。", "b": "明·归有光《项脊轩志》"}], "words": [{"w": "谀墓之金", "t": "为人作墓志所得的报酬"}, {"w": "谀颂", "t": "阿谀奉承"}, {"w": "谀悦", "t": "谄媚;奉承"}, {"w": "谀墓", "t": "指替人作墓志阿谀死者"}, {"w": "谀佞", "t": "惯于用花言巧语阿谀谄媚的人"}, {"w": "谀言", "t": "谄媚的言语。"}]}, {"meaning": "谄媚的话。", "cites": [{"t": "唯囿是恢,唯谀是信。", "b": "《汉书·韦贤传》"}], "words": [{"w": "谀史", "t": "有溢美之辞的史传。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4676wx','谂','1','shěn','讠','10','','[{"pinyin": "shěn", "defs": [{"meaning": "(形声。从言,念声。本义:规谏)。"}, {"meaning": "同本义。", "cites": [{"t": "谂,深谏也。", "b": "《说文》"}, {"t": "昔辛伯谂周桓公。", "b": "《左传·闵公二年》"}, {"t": "使吾无忘谂。", "b": "《国语·鲁语》"}, {"t": "使果敢者谂之。", "b": "《国语·晋语》"}]}, {"meaning": "告诉。", "cites": [{"t": "世忠以书来谂,飞复曰:“均为国家,何分彼此?”", "b": "《宋史》"}]}, {"meaning": "思念。", "cites": [{"t": "岂不怀归,是用作歌,将母来谂。", "b": "《诗·小雅·四牡》"}, {"t": "为我得法,使有司藏之,使吾无忘谂。", "b": "《国语·鲁语上》"}]}, {"meaning": "知悉。", "cites": [{"t": "我谂知这几日相思滋味。", "b": "王实甫《西厢记》"}], "words": [{"w": "谂知", "t": "知悉。"}]}, {"meaning": "躲闪,鱼惊走。", "cites": [{"t": "故龙以为畜而鱼鲔不谂。", "b": "《孔子家语·礼运》"}]}, {"meaning": "详尽。", "cites": [{"t": "觉我形秽,自知既谂,而不敢不勉,以期无玷于知己。", "b": "明·陈子壮《与孔玉横少宗伯》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4677wx','谄','1','chǎn','讠','10','','[{"pinyin": "chǎn", "defs": [{"meaning": "(形声。从言,臽(xiàn)声。本义:谄媚,曲意迎合 ) 同本义。", "cites": [{"t": "贫而无谄,富而无骄。", "b": "《论语·学而》"}, {"t": "胁肩谄笑,病于夏畦。", "b": "《孟子·滕文公下》"}, {"t": "不幸吕师孟构恶于前,贾余庆献谄于后。", "b": "宋·文天祥《指南录·后序》"}], "words": [{"w": "谄臣", "t": "逢迎谄媚的臣子"}, {"w": "谄言", "t": "谄媚的话。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4678wx','谇','1','suì','讠','10','','[{"pinyin": "suì", "defs": [{"meaning": "(形声。从言,卒声。本义:责骂)。"}, {"meaning": "同本义。", "cites": [{"t": "谇,让也。", "b": "《说文》"}, {"t": "立而谇语。", "b": "《汉书·贾谊传》"}, {"t": "察士无凌谇之事。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "谇语", "t": "骂人话"}, {"w": "谇辱", "t": "辱骂"}, {"w": "谇骂", "t": "责骂。"}]}, {"meaning": "劝告;谏诤。", "cites": [{"t": "謇朝谇而夕替。", "b": "《离骚》"}]}, {"meaning": "责问;用责备的口气问。", "cites": [{"t": "立而谇语。", "b": "《汉书·贾谊传》"}, {"t": "察士无凌谇之事。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "谇候", "t": "讯问"}, {"w": "谇诟", "t": "责难辱骂。"}]}, {"meaning": "古乐章的尾声。相当于“乱”。", "cites": [{"t": "谇曰:“已矣,国其莫吾知兮,子独台郁其谁语!”", "b": "《汉书·贾谊传》。颜师古注:“张晏曰:谇,《离骚》下章乱也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4679wx','屐','1','jī','尸','10','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从履(鞋子)省,支声。本义:木屐,一种笨重的木底鞋)。"}, {"meaning": "同本义。", "cites": [{"t": "木屐也。", "b": "《三苍》"}, {"t": "以屐,为服。", "b": "《庄子·天下》。李注:“木曰屐者。”按,雨行所以践泥。"}, {"t": "介子推抱树烧死,晋文公伐以制屐也。", "b": "《庄子·异苑》"}, {"t": "脚着谢公屐,身登青云梯。", "b": "李白《梦游天姥吟留别》"}, {"t": "蹑屐登崖。", "b": "明·刘基《诚意伯刘文成公文集》"}], "words": [{"w": "屐子", "t": "木鞋"}, {"w": "屐齿", "t": "屐底的齿"}, {"w": "屐声", "t": "脚步声"}, {"w": "屐履间", "t": "履屐间"}, {"w": "屐响", "t": "木屐的响声。"}]}, {"meaning": "泛指鞋。", "cites": [{"t": "佳处径须携杖去,能消几平生屐?", "b": "辛弃疾《满江红》"}], "words": [{"w": "草屐;屐履;锦屐", "t": ""}]}]}]','jingmo-wenyan');
