INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4681wx','陬','1','zōu','阝','10','','[{"pinyin": "zōu", "defs": [{"meaning": "(形声。从阜(fù),取声。“阜”是土山,与区域有关。本义:山的角落)。"}, {"meaning": "同本义。", "cites": [{"t": "陬,阪隅也。", "b": "《说文》"}, {"t": "陬,角也。", "b": "《广雅》"}, {"t": "在陵之诹。", "b": "《补亡诗》"}, {"t": "五岳之土…若在陬,陵之阳。", "b": "《管子》"}, {"t": "归路意昏,落日在岭陬。", "b": "杨万里《次日醉归》"}]}, {"meaning": "隅,。", "words": [{"w": "陬隅", "t": "室内西南角"}, {"w": "陬维", "t": "边隅,角隅。"}]}, {"meaning": "春秋鲁地。在今山东曲阜东南。", "cites": [{"t": "孔子生鲁昌平乡陬邑。", "b": "《史记》"}]}, {"meaning": "边远偏僻的地方。", "cites": [{"t": "其荒陬谲诡。", "b": "左思《吴都赋》"}, {"t": "监土木于僻陬,绝交通于首善。", "b": "《新罗马》"}], "words": [{"w": "陬隧", "t": "边邑的通道"}, {"w": "陬澨", "t": "僻远处"}, {"w": "陬邑", "t": "边远乡邑"}, {"w": "陬芒", "t": "边远偏僻之地。"}]}]}]','jingmo-wenyan');
