('4682wx','勐','1','měng','力','10','','[{"pinyin": "měng", "defs": [{"meaning": "勇猛。", "cites": [{"t": "勐,勇猛也。又严也;亦害也,恶也。与猛义同。", "b": "《五音类聚》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4683wx','奘','1','zàng zhuǎng','大','10','','[{"pinyin": "zàng", "defs": [{"meaning": "健壮。", "cites": [{"t": "秦晋之间,凡人之大谓之奘,或谓之壮。", "b": "《方言》"}]}]}, {"pinyin": "zhuǎng", "defs": [{"meaning": "粗而大。", "cites": [{"t": "奘,驵大也。从大,从壯。会意。壯亦声。", "b": "《说文》"}, {"t": "奘,驵也。", "b": "《尔雅》。注:“犹粗也。”"}, {"t": "手足比毛更奘,星星眼窟明明。", "b": "《西游记》"}], "words": [{"w": "那根棍子一头奘一头细", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4684wx','牂','1','zāng','爿','10','','[{"pinyin": "zāng", "defs": [{"meaning": "母羊。", "cites": [{"t": "牂,牝羊也。从羊,爿声。", "b": "《说文》"}, {"t": "牂羊坟首。", "b": "《诗·小雅·苕之华》"}], "words": [{"w": "牂羊", "t": "母羊"}, {"w": "牂羝不辨", "t": "分不清母羊和公羊。形容愚昧无知。"}]}, {"meaning": "茂盛。", "cites": [{"t": "东门之杨,其叶牂牂。", "b": "《诗·陈风·东门之杨》"}]}, {"meaning": "强壮。", "cites": [{"t": "敦牂岁:岁阴在午,星居酉。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4685wx','蚩','1','chī','虫','10','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从虫,之声。本义:蚩虫)。"}, {"meaning": "同本义。", "cites": [{"t": "蚩,蚩虫也。", "b": "《说文》"}]}, {"meaning": "痴呆,愚蠢。", "cites": [{"t": "蚩,痴也。", "b": "《释名》"}, {"t": "儿大黠宗室无蚩者。", "b": "《后汉书·刘盆子传》"}], "words": [{"w": "蚩骏", "t": "痴呆笨拙"}, {"w": "蚩伫", "t": "鲁钝庸劣"}, {"w": "蚩人", "t": "愚人"}, {"w": "蚩蚩蠢蠢", "t": "愚笨蠢动的样子。"}]}, {"meaning": "丑陋;丑恶。", "cites": [{"t": "孰知辨其蚩妍。", "b": "《后汉书·张壹传》"}], "words": [{"w": "蚩妍", "t": "丑与美。同媸妍"}, {"w": "蚩鄙", "t": "粗野拙劣。"}]}, {"meaning": "欺侮。", "cites": [{"t": "蚩眩边鄙。", "b": "张衡《西京赋》。注:“侮也。”"}], "words": [{"w": "蚩辱", "t": "侮辱;欺压"}, {"w": "蚩弄", "t": "犹侮弄。"}]}, {"meaning": "讥笑。", "cites": [{"t": "蚩,笑也。", "b": "《苍颉篇》"}, {"t": "他日与蒙会,又蚩辱之。", "b": "《三国志·吕蒙传》"}, {"t": "终蚩弄而交泄兮,虽近习而不亲。", "b": "阮籍《猕猴赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4686wx','陲','1','chuí','阝','10','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从阜,垂声。假借为垂,俗用为边境字。本义:边疆)。"}, {"meaning": "同本义。", "cites": [{"t": "陲,边也。", "b": "《广韵》"}, {"t": "虔刘我边陲。", "b": "《左传·成公十三年》"}, {"t": "连兵于边陲。", "b": "《史记·律书》"}], "words": [{"w": "边陲", "t": "边境。"}]}, {"meaning": "边缘。", "cites": [{"t": "独我恶水浊,凿井庭之陲。", "b": "唐·姚合《街西居三首》"}]}, {"meaning": "流传。也作“垂”。", "cites": [{"t": "大义箸明,陲于后嗣。", "b": "李斯《泰山刻石》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4687wx','姬','1','jī','女','10','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。本义:上古母系社会流传下来的一种姓氏)。"}, {"meaning": "水名。相传为黄帝所居。", "cites": [{"t": "黄帝以姬水成,炎帝以姜水成。", "b": "《国语·晋语》"}]}, {"meaning": "黄帝的姓。", "cites": [{"t": "黄帝君姬水,以为姓。", "b": "《说文》"}, {"t": "昔少典,取于有峤氏,生黄帝炎帝,黄帝以姬水成,炎帝以姜水成,成而异德,故黄帝为姬,炎帝为姜。", "b": "《国语·晋语》。按,轩辕子二十五人,惟青阳与仓林氏得姓姬。"}, {"t": "尧立后稷以为大农,姓之曰姬氏。", "b": "《史记·三代世表》。按,姬姜为古大姓,姬本黄帝裔,故尧赐姓姬也。"}]}, {"meaning": "古代称帝王的妾。", "cites": [{"t": "毋曰薄姬。", "b": "《汉书·文帝纪》。注:“内宫也。”"}, {"t": "王姬、徐姬、蔡姬。", "b": "《史记·齐世家》。索隐:“众妾之总称。此名之不正者。”"}, {"t": "宠姬郑袖。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "侍姬;姬人", "t": "妾"}, {"w": "姬侍", "t": "侍妾"}, {"w": "姬妾", "t": "妾"}, {"w": "姬媵", "t": "妾"}, {"w": "姬仆", "t": "家妓;婢妾。"}]}, {"meaning": "古代中国对妇人的美称。", "cites": [{"t": "妖姬静女。", "b": "清·侯方域《壮悔堂文集》"}], "words": [{"w": "艳姬;仙姬", "t": ""}]}, {"meaning": "美女的代称。", "cites": [{"t": "于是庄王弃其秦姬越女,罢钟鼓之乐。", "b": "《吴越春秋》"}]}, {"meaning": "周朝的代称。周人为姬姓,故以之相代。", "cites": [{"t": "姬汉旧邦。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "姬周", "t": "周朝"}, {"w": "姬汉", "t": "周朝和汉朝"}, {"w": "姬刘", "t": "周朝和汉朝"}, {"w": "姬姜", "t": "春秋时,周王室姓姬,齐国姓姜,二姓常通婚姻,因以“姬姜”为贵族妇女之称。泛指美女。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4688wx','娠','1','shēn','女','10','','[{"pinyin": "shēn", "defs": [{"meaning": "怀孕。", "cites": [{"t": "娠,女妊身动也。春秋传曰:“后缗方娠。”", "b": "《说文》"}, {"t": "怀胎为娠。", "b": "《一切经音义》"}, {"t": "昔者大任娠文王。", "b": "《国语·晋语》。注:“娠,有身也。”"}, {"t": "已而有娠。", "b": "《汉书·高帝纪上》"}], "words": [{"w": "有娠", "t": "怀孕。"}]}, {"meaning": "含;孕育。", "cites": [{"t": "水娠黄金山空青,丹砂晨暾朱夜明。", "b": "苏轼《桂酒颂》"}]}, {"meaning": "女奴。", "cites": [{"t": "娠,宫婢女隶谓之娠。", "b": "《说文》"}]}, {"meaning": "养马的人。", "cites": [{"t": "燕齐之间养马者谓之娠。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4689wx','娌','1','lǐ','女','10','','[{"pinyin": "lǐ", "defs": [{"meaning": "双,二。", "cites": [{"t": "娌,耦也。", "b": "《方言》"}]}, {"meaning": "——见“妯娌”(zhóuli)(兄弟之妻的合称)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4690wx','娉','1','pìn pīng','女','10','','[{"pinyin": "pìn", "defs": [{"meaning": "(形声。从女,甹(pīng)声。本义:问名。古代婚礼“六礼”之一。即男方请媒人问女方名字和出生年月日)。"}, {"meaning": "同本义。", "cites": [{"t": "娉,问也。", "b": "《说文》"}, {"t": "婚姻娉内送逆无礼。", "b": "《荀子·富国》。注:“问名也。”"}], "words": [{"w": "娉命", "t": "婚约。即订婚"}, {"w": "娉财", "t": "行聘礼时所赠财物"}, {"w": "娉币", "t": "行聘礼时所致币帛财物"}, {"w": "娉内", "t": "娉纳。古代婚礼中的问名、纳币。"}]}, {"meaning": "娶。", "cites": [{"t": "婚姻娉内。", "b": "《荀子·富国》"}, {"t": "再奉朝娉。", "b": "《樊敏碑》"}], "words": [{"w": "娉会", "t": "聘妻。"}]}]}, {"pinyin": "pīng", "defs": [{"meaning": "", "words": [{"w": "娉婷袅娜", "t": "形容女子姿态柔美"}, {"w": "娉娉", "t": "轻盈美好的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4691wx','娲','1','wā','女','10','','[{"pinyin": "wā", "defs": [{"meaning": "古神女名 。古代神话中的女娲、女帝王。", "cites": [{"t": "娲,古之神圣女化万物者也。从女,咼声。", "b": "《说文》。按,女娲在大庭柏皇前,亦古皇之号,非必妇人也。"}, {"t": "女娲氏练五色石以补天阙。", "b": "《列子·汤问》"}], "words": [{"w": "娲皇", "t": "女娲氏。古女帝王。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4692wx','娩','1','miǎn','女','10','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从女,免声。本义:生孩子) 同本义。", "cites": [{"t": "娩以连卷兮。", "b": "《文选·张衡·思玄赋》。旧注引纂要:“齐人谓生子曰娩。”"}], "words": [{"w": "娩身", "t": "分娩,生小孩"}, {"w": "娩息", "t": "产育,蕃殖"}, {"w": "娩乳", "t": "妇人产子"}, {"w": "娩娠", "t": "分娩"}, {"w": "娩难", "t": "分娩。旧时分娩为妇女的灾难"}, {"w": "娩怀", "t": "分娩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4693wx','娴','1','xián','女','10','','[{"pinyin": "xián", "defs": [{"meaning": "(形声。从女,闲声。本义:文雅;柔美文静,庄重不轻浮) 同本义。", "cites": [{"t": "嫺,雅也。", "b": "《说文》"}, {"t": "嫺雅,犹沈静也。", "b": "《后汉书·马援传》注"}, {"t": "若夫青琴、宓妃之徒,绝殊离俗,妖冶娴都。", "b": "张衡《上林赋》"}, {"t": "或骨体娴丽。", "b": "《论衡·定贤》"}, {"t": "夫何美女之娴妖,红颜晔而流光。", "b": "曹植《静思赋》"}], "words": [{"w": "娴婉", "t": "文雅美丽"}, {"w": "娴丽", "t": "优雅美丽。"}]}, {"meaning": "熟悉(掌握得熟練自如)。", "cites": [{"t": "今邊兵惟習馬耳,未娴山战、林战、谷战之道也。", "b": "《明史 戚繼光传》"}, {"t": "這花生,已弃詩书而娴韜略。", "b": "《畫图緣》"}, {"t": "娴于辭令。", "b": "《史記賈屈原賈生列传》"}], "words": [{"w": "娴熟", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4694wx','娣','1','dì','女','10','','[{"pinyin": "dì", "defs": [{"meaning": "(会意。从女,弟声。古代剥削阶级的妇女出嫁时随嫁的女子)。"}, {"meaning": "古代姐妹共嫁一夫,幼为娣,长为姒。", "cites": [{"t": "娣姒妇者,弟长也。", "b": "《仪礼·丧服子夏传》"}], "words": [{"w": "娣姒", "t": "妯娌"}, {"w": "娣侄", "t": "古代诸侯的女儿出嫁,从嫁共事一夫的妹妹和侄女。"}]}, {"meaning": "古代诸妾中的年幼者。", "cites": [{"t": "娣,女弟也。", "b": "《说文》"}, {"t": "女子同出谓后生内娣。", "b": "《尔雅·释亲》"}, {"t": "诸娣从之。", "b": "《诗·大雅·韩奕》。释文:“妻之女弟为娣。”"}, {"t": "众媵姪娣之多。", "b": "《诗·召南·鹊巢传》"}], "words": [{"w": "娣姒", "t": "古女同夫诸妾互称,年长的为姒,年幼的为娣。"}]}, {"meaning": "姐姐对妹妹的称呼。", "cites": [{"t": "姊娣悉慕媖娴,妪媪咸仰慧德。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4695wx','娓','1','wěi','女','10','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从女,尾声。本义:顺从)。"}, {"meaning": "同本义。", "cites": [{"t": "娓,顺也。", "b": "《说文》"}, {"t": "娓,从也。", "b": "《广韵》"}]}, {"meaning": "努力。", "cites": [{"t": "娓,勉也。", "b": "《字汇》"}]}, {"meaning": "美,漂亮。", "cites": [{"t": "娓,美也。", "b": "《玉篇》"}]}, {"meaning": "不倦的。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4696wx','婀','1','ē','女','10','','[{"pinyin": "ē", "defs": [{"meaning": "姿态轻盈柔美。", "cites": [{"t": "四角龙子幡，婀娜随风转。--《玉台新咏·古诗为焦仲卿妻作》", "b": ""}, {"t": "华容婀娜，令我忘餐。--曹植《洛神赋》", "b": ""}, {"t": "杨柳婀娜多姿，可谓妩媚极了。--陶铸《松树的风格》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
