INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4698wx','逡','1','qūn','辶','10','','[{"pinyin": "qūn", "defs": [{"meaning": "(形声。从辵(chuò) 。本义:徘徊的样子)。"}, {"meaning": "复,往来。", "cites": [{"t": "逡,复也。", "b": "《说文》。徐灏注笺:“复训往来。往来即逡巡意。”"}]}, {"meaning": "退让。", "cites": [{"t": "有功者上,无功者下,则群臣逡。", "b": "《汉书·公孙宏传》"}]}, {"meaning": "退却,打仗时军队向后撤。", "cites": [{"t": "逡巢逗穴,命淮、汝戈船,遏其还径。", "b": "《宋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4699wx','绠','1','bǐng gěng','纟','10','','[{"pinyin": "bǐng", "defs": [{"meaning": "轮辐近轴处向外突出的部分。", "cites": [{"t": "绠,车轮也。", "b": "《类篇·系部》"}]}]}, {"pinyin": "gěng", "defs": [{"meaning": "(形声。从糸(mì),更声。本义:井绳)。"}, {"meaning": "同本义。", "cites": [{"t": "绠,汲井索也。", "b": "《说文》"}, {"t": "具绠缶。", "b": "《左传·襄公九年》"}, {"t": "绠短者,不可以汲深。", "b": "《庄子·至乐》"}], "words": [{"w": "绠缶", "t": "汲水的绳索和器具"}, {"w": "绠短绝泉", "t": "绠短汲深。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4700wx','骊','1','lí','马','10','','[{"pinyin": "lí", "defs": [{"meaning": "深黑色的马。", "cites": [{"t": "骊,马深黑色。从马,丽声。", "b": "《说文》"}, {"t": "有骊有黄。", "b": "《诗·鲁颂·駉》"}, {"t": "戎事乘骊。", "b": "《礼记·檀弓》"}, {"t": "盗骊。", "b": "《穆天子传》"}, {"t": "四骊济济,垂辔沵沵。", "b": "《诗·齐风·载驱》"}], "words": [{"w": "骊歌", "t": "告别的歌。“骊驹之歌”的简称"}, {"w": "骊驹", "t": "纯黑色的马;逸“诗”篇名"}, {"w": "骊黄", "t": "黑马和黄马。"}]}, {"meaning": "古邑名 。在今陕西省临潼县。周初骊戎所居,秦置骊邑。北宋时改称临潼。"}, {"meaning": "黑色。", "cites": [{"t": "骊,黑也。", "b": "《小尔雅》"}, {"t": "白马从骊驹。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "骊马", "t": "黑色的马;齐驱并驾的马"}, {"w": "骊龙", "t": "古代传说中颔下有珠的黑龙"}, {"w": "骊珠", "t": "宝珠。传说出于骊龙颔下"}, {"w": "骊驹", "t": "黑色的小马。"}]}, {"meaning": "附丽;并列,用两匹马驾车。", "cites": [{"t": "骊马二驷。(并驾之马八匹。)", "b": "《汉书·王莽传》"}], "words": [{"w": "骊驾", "t": "车马并排而行"}, {"w": "骊马", "t": "齐驱并驾的马。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4701wx','绡','1','xiāo','纟','10','','[{"pinyin": "xiāo", "defs": [{"meaning": "(形声。从糸,肖声。本义:生丝或以生丝织成的薄绸子) 同本义。", "cites": [{"t": "绡,生丝也。", "b": "《说文》"}, {"t": "绡幕鲁也。", "b": "《礼记·檀弓》"}, {"t": "曳雾绡之轻裾。", "b": "曹植《洛神赋》"}, {"t": "泉室潜织而卷绡。", "b": "左思《吴都赋》"}, {"t": "半匹红绡一丈绫,系向牛头充炭直。", "b": "白居易《卖炭翁》"}, {"t": "红绡不知数。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "紫鹃放下绡帐,移灯掩门而去。", "b": "《红楼梦》"}], "words": [{"w": "绡巾", "t": "丝巾,薄纱巾"}, {"w": "绡衣", "t": "用绫绡制成的衣裳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4702wx','骋','1','chěng','马','10','','[{"pinyin": "chěng", "defs": [{"meaning": "(形声。从马,甹(píng)声。本义:纵马向前奔驰)。"}, {"meaning": "同本义。", "cites": [{"t": "骋,直驰也。", "b": "《说文》"}, {"t": "林楚怒马,及衢而骋。", "b": "《左传·定公八年》"}, {"t": "乘骐骥以驰骋兮。", "b": "《楚辞·离骚》"}], "words": [{"w": "驰骋", "t": "骑马奔驰"}, {"w": "骋鹜", "t": "奔走驰骋"}, {"w": "骋步", "t": "驰步快走。"}]}, {"meaning": "放任,放纵。", "cites": [{"t": "故其与万物接也,至无而供其求,时骋而要其宿。", "b": "《庄子·天地》"}], "words": [{"w": "骋心", "t": "恣意,快心"}, {"w": "骋快", "t": "放纵"}, {"w": "骋情", "t": "纵情。"}]}, {"meaning": "古州名 。唐置。在今四川省屏山县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4703wx','绥','1','suí','纟','10','','[{"pinyin": "suí", "defs": [{"meaning": "(会意。从糸(mì),从妥,“糸”与丝织品、绳索有关。“妥”表妥当、平安。合起来表示有了这绳索,人就稳妥了。本义:借以登车的绳索)。"}, {"meaning": "同本义。", "cites": [{"t": "绥,车中把也。", "b": "《说文》"}, {"t": "负良绥君升所用、又、以散绥升。", "b": "《礼记·少仪》"}, {"t": "子良授太子绥。", "b": "《左传·哀公二年》"}, {"t": "《论语·乡党》说:孔子“升车必正立执绥。”", "b": "《我国古代的车马》"}], "words": [{"w": "执绥", "t": "挽住车中绳索"}, {"w": "绥绳", "t": "执以登车的绳索。"}]}, {"meaning": "上古五服之一 。古代王畿外围,每五百里为一区划,按距离的远近分为五等地带,叫“五服”。其名称为侯服、甸服、绥服、要服、荒服。服,服事天子。"}, {"meaning": "绥江 。在福建省西部。"}, {"meaning": "旧绥远省略称 。1928年设省,1954年撤销。"}, {"meaning": "绥州,古州名 。西魏置,在今陕西省绥德县。"}, {"meaning": "安抚人心以保持平静。", "cites": [{"t": "惠此中国,以绥四方。", "b": "《诗·大雅·民劳》"}, {"t": "绥之斯来,动之斯和。", "b": "《论语·子张》"}, {"t": "时军司马班超留于寘,绥集诸国。", "b": "《后汉书·西域传·序》"}], "words": [{"w": "绥民", "t": "安定人民"}, {"w": "绥安", "t": "安定"}, {"w": "绥定", "t": "安定"}, {"w": "绥纳", "t": "安抚接纳"}, {"w": "绥驭", "t": "安抚控制"}, {"w": "绥养", "t": "安定抚养"}, {"w": "绥御", "t": "安抚统治"}, {"w": "绥服", "t": "安定顺服"}, {"w": "绥集", "t": "安辑,安抚和合"}, {"w": "绥宁", "t": "安定。"}]}, {"meaning": "临阵退军,向后撤。", "cites": [{"t": "秦以胜归,我何以报,乃皆出战,交绥。", "b": "《左传·文公十二年》"}]}, {"meaning": "制止;止。", "cites": [{"t": "使民以劝,绥谤言,足以补官之不善政。", "b": "《国语·齐语》"}]}, {"meaning": "舒缓的。", "cites": [{"t": "绥,舒也。", "b": "《广雅》。王念孙疏证:“绥者,安之舒也。”"}]}, {"meaning": "平安;安好;安泰。", "cites": [{"t": "绥绥兮其有文章也。熙熙兮其乐人之臧也。", "b": "《荀子·儒效》"}], "words": [{"w": "顺颂时绥", "t": "书信用语。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4704wx','绦','1','tāo','纟','10','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从糸(mì),条声。或从糸,攸(yōu)声。本义:用丝编织的带子或绳子) 同本义。", "cites": [{"t": "绦旋光堪摘,轩楹势可呼。", "b": "杜甫《画鹰》"}], "words": [{"w": "玉绦环;彩绦", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4705wx','绨','1','tí tì','纟','10','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从糸(mì),弟声。本义:古代一种粗厚光滑的丝织品) 同本义。", "cites": [{"t": "绨,厚缯也。", "b": "《说文》"}, {"t": "鲁梁之民俗为绨。", "b": "《管子·轻重丁》"}, {"t": "取绨袍赐之。", "b": "《史记·范雎蔡泽传》"}, {"t": "赤绨绿缯。", "b": "《汉书·匈奴传》"}, {"t": "衣绨履革。", "b": "《汉书·贡禹传》"}, {"t": "身衣弋绨、绨锦。", "b": "《汉书·文帝纪赞》"}], "words": [{"w": "绨几", "t": "铺上绨锦的几案"}, {"w": "绨衣", "t": "粗厚的绘衣"}, {"w": "绨阜", "t": "黑色粗厚的绘衣"}, {"w": "绨纨", "t": "厚薄丝织物的统称"}, {"w": "绨袠", "t": "亦作“绨帙”。缯制的书卷封套。因亦作书卷的代称"}, {"w": "绨缯", "t": "粗厚的丝织品。"}]}]}, {"pinyin": "tì", "defs": [{"meaning": "丝织物类名 。一般用化学纤维卡丝作经,棉纱作纬。采用平纹组织。质地较绸厚实,表面较绸粗糙。多经染色,作服装或被面用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4706wx','骎','1','qīn','马','10','','[{"pinyin": "qīn", "defs": [{"meaning": "见“骎骎”", "cites": [{"t": "骎,马行疾也。", "b": "《说文》"}, {"t": "骎骎,疾也。", "b": "《广雅》"}], "words": [{"w": "骎寻", "t": "渐进的样子"}, {"w": "骎淫", "t": "逐渐蔓延开来"}]}, {"meaning": "逐渐", "words": [{"w": "骎寻", "t": "渐进的样子"}, {"w": "骎淫", "t": "逐渐蔓延开来"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4707wx','邕','1','yōng','邑','10','','[{"pinyin": "yōng", "defs": [{"meaning": "(会意。从川,从邑。水流(川)围困城邑。本义:四方被水环绕的都邑)。"}, {"meaning": "同本义。"}, {"meaning": "古地名,即邕州 ,在广西南部,约相当于今南宁市及邕宁、武鸣、隆安…等县地。"}, {"meaning": "广西壮族自治区南宁市的简称。"}, {"meaning": "和睦。", "cites": [{"t": "上元甲子,肃邕永享。", "b": "《汉书》"}, {"t": "君臣邕穆。", "b": "《晋书·乐志下》"}, {"t": "将何以光赞时邕。", "b": "《宋书·礼志》"}], "words": [{"w": "邕邕", "t": "和乐的样子"}, {"w": "邕穆", "t": "和谐的样子"}, {"w": "邕睦", "t": "和睦,和洽"}, {"w": "邕熙", "t": "和睦兴盛"}, {"w": "邕文", "t": "雍容大雅的文章。"}]}]}]','jingmo-wenyan');
