INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4709wx','彗','1','huì','彐','11','','[{"pinyin": "huì", "defs": [{"meaning": "(会意。甲骨文象扫竹之形,本是象形字。小篆增加“又”(手),构成了会意字。本义:扫帚)。"}, {"meaning": "同本义。", "cites": [{"t": "彗,埽竹也。", "b": "《说文》"}, {"t": "国中以策彗卹勿驱。", "b": "《礼记·曲礼》"}, {"t": "拥彗先驱。", "b": "《史记·孟荀传》"}, {"t": "忽若彗泛画涂。", "b": "《汉书·王褒传》"}, {"t": "太公拥彗。", "b": "《汉书·高帝纪》"}], "words": [{"w": "彗汜画涂", "t": "以帚扫秽,以刀划泥。比喻极其容易。"}]}, {"meaning": "彗星的简称。", "cites": [{"t": "彗所以除旧布新也。", "b": "《左传·昭公十七年》"}, {"t": "彗星者,天之旗也。", "b": "《河图帝通纪》"}], "words": [{"w": "彗光", "t": "彗星的光束"}, {"w": "彗孛", "t": "彗星和孛星"}, {"w": "彗孛干犯", "t": "彗星侵犯"}, {"w": "彗勃", "t": "即彗孛。彗星和孛星。"}]}, {"meaning": "扫;拂。", "cites": [{"t": "戈铤彗云。", "b": "班固《东都赋》"}]}, {"meaning": "在阳光下曝晒。", "cites": [{"t": "日中不彗,是谓失时。", "b": "《六韬》"}]}, {"meaning": "聪慧的", "cites": [{"t": "淮南王有女陵,彗有口辨。", "b": "《史记·淮南衡山列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4710wx','耜','1','sì','耒','11','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从耒,以声。耒(lěi),翻土的工具。本义:古代农具名,耒耜的主要部件,似锹) 耒下端铲土的部分,装在犁上,用以翻土。", "cites": [{"t": "字亦作耜。", "b": ""}, {"t": "耜,来下剌臿也。古以木为之,后世以金。", "b": "《六书故》"}, {"t": "斵木为耜。", "b": "《易·系辞》"}, {"t": "禹亲自操耜。", "b": "《庄子·天下》"}, {"t": "古者剡耜而耕。", "b": "《淮南子·泛率》"}, {"t": "脩来耜。", "b": "《礼记·月令》"}]}, {"meaning": "民无悬耜,野无奥草。——《国语·周语中》。韦昭注:“入土曰耜,耜柄曰耒。”。"}, {"meaning": "引申为以耜铲土。", "cites": [{"t": "薙氏掌杀草…冬日至而耜之。", "b": "《周礼·薙氏》"}]}]}]','jingmo-wenyan');
