INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4712wx','舂','1','chōng','臼','11','','[{"pinyin": "chōng", "defs": [{"meaning": "把东西放在石臼或钵里捣去皮壳或捣碎。", "cites": [{"t": "舂,捣粟也。", "b": "《说文》"}, {"t": "城曰舂。", "b": "《后汉书·明帝纪》"}, {"t": "水舂河漕。", "b": "《后汉书·西羌传》。注:“即水碓也。”"}], "words": [{"w": "舂堂", "t": "又叫舂塘。舂谷的木槽"}, {"w": "舂谷", "t": "舂捣谷物"}, {"w": "舂揄", "t": "指舂米。捣米于臼曰舂,自臼取出曰揄。"}]}, {"meaning": "冲击。", "cites": [{"t": "舂其喉以戈,杀之。", "b": "《史记·鲁周公世家》"}, {"t": "舂,撞也。以舂筑地为节也。", "b": "《释名》"}], "words": [{"w": "舂击", "t": "冲击"}, {"w": "舂撞", "t": "冲撞;冲击。"}]}, {"meaning": "臼。", "cites": [{"t": "刚勇有力,能举石舂。", "b": "《聊斋志异》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4713wx','琏','1','liǎn','王','11','','[{"pinyin": "liǎn", "defs": [{"meaning": "宗庙中盛黍稷的器皿。", "cites": [{"t": "曰:“何器也?”曰:“瑚琏也。”", "b": "《论语·公冶长》"}]}, {"meaning": "连接。", "cites": [{"t": "又宏琏以丰敞。", "b": "何晏《景福殿赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4714wx','琇','1','xiù','王','11','','[{"pinyin": "xiù", "defs": [{"meaning": "次于玉的美石。", "cites": [{"t": "彼都人士,充耳琇实。", "b": "《诗·小雅》"}, {"t": "我友于征,彼郑之子,如琇如英,德音孔明。", "b": "唐·肖颖士《江有枫》"}]}]}]','jingmo-wenyan');
