INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4717wx','埴','1','zhí','土','11','','[{"pinyin": "zhí", "defs": [{"meaning": "细腻的黄粘土。", "cites": [{"t": "埴,黏土也。从土,直声。", "b": "《说文》"}, {"t": "厥土赤埴坟。", "b": "《书·禹贡》"}, {"t": "博埴之工二。", "b": "《考工记》"}, {"t": "我善治埴。", "b": "《庄子·马蹄》"}, {"t": "若玺之抑埴。", "b": "《淮南子·齐俗》"}, {"t": "桴木负埴,载流于。", "b": "《湘源二妃庙碑》"}]}, {"meaning": "土地。", "cites": [{"t": "埴索涂,冥行而己矣。", "b": "《法言·修身》"}]}]}]','jingmo-wenyan');
