INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4724wx','赧','1','nǎn','赤','11','','[{"pinyin": "nǎn", "defs": [{"meaning": "(形声。从赤,(fú)声。脸红,故从赤。本义:因惭愧而脸红)。"}, {"meaning": "同本义。", "cites": [{"t": "大赧而归,填恨低首。", "b": "柳宗元《乞巧文》"}, {"t": "鬼即赧愧而退。", "b": "刘义庆《幽明录》"}, {"t": "自为乳儿,长者加以金银华美之服,辄羞赧弃去之。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "赧颜", "t": "羞惭脸红;惭愧"}, {"w": "赧愧", "t": "羞惭。"}]}, {"meaning": "忧惧。", "cites": [{"t": "夫子践位则退,自退则敬,否则赧。", "b": "《国语·楚语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4725wx','埤','1','pí pì','土','11','','[{"pinyin": "pí", "defs": [{"meaning": "城上女墙,上有孔穴,可以窥外。", "cites": [{"t": "举兵伐曹、五鹿,及反郑之埤,东卫之亩,胜荆人于城濮。", "b": "《商君书·赏刑》"}]}, {"meaning": ""}, {"meaning": "低下。", "cites": [{"t": "其流也埤下。", "b": "《荀子·宥坐》"}]}, {"meaning": "操行鄙陋。", "cites": [{"t": "不恤其文是以终身不免埤污傭俗。", "b": "《荀子·非相》"}]}, {"meaning": "(形声。从土,卑声。本义:增加) 同本义。", "cites": [{"t": "埤,增也。", "b": "《说文》"}, {"t": "政事一埤益我。", "b": "《诗·邶风·北门》"}, {"t": "政事一埤遗我。", "b": ""}], "words": [{"w": "埤助", "t": "助益;帮助"}, {"w": "埤益", "t": "大大增加"}, {"w": "埤遗", "t": "厚加。"}]}]}, {"pinyin": "pì", "defs": [{"meaning": "城上的矮墙。", "cites": [{"t": "掖垣竹埤梧十寻。", "b": "杜甫《题省中院壁》"}]}]}]','jingmo-wenyan');
