('4731wx','掬','1','jū','扌','11','','[{"pinyin": "jū", "defs": [{"meaning": "两手相合捧物。", "cites": [{"t": "受珠玉者以掬。", "b": "《礼记·曲礼》。释文:“两手曰掬。”"}, {"t": "舟中之指可掬也。", "b": "《左传·宣公十二年》。注:“两手可掬。”"}], "words": [{"w": "以手掬水;掬示", "t": "捧出来示众,昭示。"}]}, {"meaning": "撅;翘起。", "cites": [{"t": "八戒采着马,掬着嘴,摆着耳朵。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4732wx','鸷','1','zhì','鸟','11','','[{"pinyin": "zhì", "defs": [{"meaning": "(会意。从鸟,从执,执亦声。本义:凶猛的鸟,如鹰、雕等) 同本义。", "cites": [{"t": "鸷,击杀鸟也。", "b": "《说文》"}, {"t": "鸷虫攫搏不程勇者。", "b": "《礼记·儒行》。注:“猛鸟猛兽也。”"}, {"t": "鸷鸟之不群兮。", "b": "《离骚》"}, {"t": "养鸷非玩形,所资击鲜力。", "b": "唐·刘禹锡《养鸷词》"}], "words": [{"w": "鸷腾", "t": "如鸷鸟飞腾"}, {"w": "鸷鸟累百,不如一鹗", "t": "比喻百名诸侯不如天子一人"}, {"w": "鸷视", "t": "如同鸷鸟视物,目光很锐敏。"}]}, {"meaning": "凶猛;残暴。", "cites": [{"t": "而便捷猛鸷终弗逮。", "b": "清·徐珂《清稗类钞·战事类》"}]}, {"meaning": "又。", "cites": [{"t": "猱进鸷击。", "b": ""}, {"t": "鸷兽毅虫,倨牙黔口。", "b": "《后汉书》"}], "words": [{"w": "鸷忍", "t": "形容凶猛残忍"}, {"w": "鸷眭", "t": "形容眼神凶恶"}, {"w": "鸷愎", "t": "残忍刚愎。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4733wx','掖','1','yē yè','扌','11','','[{"pinyin": "yē", "defs": [{"meaning": "塞进。", "cites": [{"t": "你来把我这边的被掖掖罢。", "b": "《红楼梦》"}], "words": [{"w": "把被角掖好", "t": ""}]}, {"meaning": "藏。", "cites": [{"t": "黛玉微微的点头,便掖在袖里。", "b": "《红楼梦》"}]}, {"meaning": "插入腰带。", "cites": [{"t": "说着,掖上那把刀,迈步出门,往外就走。", "b": "《儿女英雄传》"}]}]}, {"pinyin": "yè", "defs": [{"meaning": "用手扶着别人的胳膊。", "cites": [{"t": "掖,以手持人臂投地也。从手,夜声。", "b": "《说文》"}, {"t": "二礼从国子巡城掖以赴外。", "b": "《左传·僖公二十五年》"}, {"t": "余掖杀国子。", "b": "《左传·僖公二十五年》"}, {"t": "掖以赴外杀之。", "b": ""}], "words": [{"w": "掖进", "t": "扶持推进。"}]}, {"meaning": "扶助;提携。", "cites": [{"t": "故作是诗以诱掖其君也。", "b": "《诗·陈风·衡门》序"}], "words": [{"w": "奖掖", "t": ""}]}, {"meaning": "胳肢窝", "cites": [{"t": "掖,一曰臂下也。", "b": "《说文》"}, {"t": "衣逢掖之衣。", "b": "《礼记·儒行》"}, {"t": "张掖郡。", "b": "《汉书·地理志下》。集注引应劭:“张国臂掖,故曰张掖也。”"}, {"t": "千羊之皮,不如一狐之掖。", "b": "《史记·商君列传》"}]}, {"meaning": "宫殿正门两旁小门“掖门”的简称。", "cites": [{"t": "入未央宫掖门。", "b": "《汉书·高后纪》。师古曰:“掖门,非正门而在两旁,若人之臂掖也。”"}], "words": [{"w": "掖门", "t": "宫殿正门两旁的边门"}, {"w": "掖垣", "t": "皇宫的旁垣"}, {"w": "掖庭", "t": "宫中旁舍,妃嫔居住的地方"}, {"w": "掖殿", "t": "宫中旁殿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4734wx','捽','1','zuó','扌','11','','[{"pinyin": "zuó", "defs": [{"meaning": "揪持头发。", "cites": [{"t": "捽,持头发也。从手,卒声。", "b": "《说文》"}, {"t": "捽胡投何罗殿下。", "b": "《汉书·金日磾传》"}, {"t": "不使捽抑而刑之也。", "b": "《汉书·贾谊传》"}, {"t": "捽博其颊。", "b": "《汉书·王尊传》"}, {"t": "詈侮捽搏。", "b": "《荀子·正论》"}, {"t": "拔剑以刺王子庆忌,王子庆忌捽之,投之于江。", "b": "《吕氏春秋》"}]}, {"meaning": "泛指揪住。", "cites": [{"t": "捽下提殴之。", "b": "明·高启《书博鸡者事》"}, {"t": "捽使跪。", "b": ""}], "words": [{"w": "小孩儿捽住妈妈的衣服;捽着他胳膊就往外走;捽引", "t": "揪拉"}, {"w": "捽抑", "t": "揪住往下按"}, {"w": "捽拽", "t": "揪住拖拽"}, {"w": "捽挽", "t": "揪拉"}, {"w": "捽搏", "t": "揪打;捕捉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4735wx','掊','1','póu pǒu','扌','11','','[{"pinyin": "póu", "defs": [{"meaning": "(形声。从手,咅(pǒu)声。本义:用五指扒土)。"}, {"meaning": "同本义。", "cites": [{"t": "掊,杷也。今盐官入水取盐为掊。(字亦作刨,作抔)", "b": "《说文》"}, {"t": "见地如钩状,掊视得鼎。", "b": "《汉书·郊祀志上》。注:“谓手杷土也。”"}], "words": [{"w": "掊土得鼎", "t": ""}]}, {"meaning": "聚敛;搜括。", "cites": [{"t": "俗吏不知方,掊克乃为材。", "b": "宋·王安石《兼并》"}], "words": [{"w": "掊克", "t": "聚敛;搜括"}, {"w": "掊昌", "t": "聚敛贪昌"}, {"w": "掊聚", "t": "聚敛;搜括"}, {"w": "掊取", "t": "搜括。"}]}]}, {"pinyin": "pǒu", "defs": [{"meaning": "击;抨击。", "cites": [{"t": "勾践终掊而杀之。", "b": "《战国策·秦策》"}], "words": [{"w": "掊攻", "t": "抨击。"}]}, {"meaning": "击破。", "cites": [{"t": "吾为其无用而掊之。", "b": "《庄子·逍遥游》。司马注:“击破也。”"}], "words": [{"w": "掊斗折衡", "t": "毁弃斗和秤。反映道教顺应自然毁弃礼法的虚无观点。"}]}, {"meaning": "以手捧物。"}, {"meaning": "仆倒。", "cites": [{"t": "乃顾麾左右戟者掊兵罢去。", "b": "《史记·吕太后本纪》"}]}]}]','jingmo-wenyan');
