INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4743wx','掇','1','duō duo','扌','11','','[{"pinyin": "duō", "defs": [{"meaning": "(形声。本义:拾取)。"}, {"meaning": "同本义。", "cites": [{"t": "掇,拾取也。", "b": "《说文》"}, {"t": "患至掇也。", "b": "《易·讼》"}, {"t": "承蜩犹掇之也。", "b": "《庄子·达生》"}, {"t": "览取挢掇。", "b": "《淮南子·要略》"}, {"t": "成益惊喜,掇置笼中。", "b": "《聊斋志异·促织》"}], "words": [{"w": "掇撷", "t": "采摘,拾取"}, {"w": "掇桂", "t": "折桂"}, {"w": "掇蜂", "t": "喻离间骨肉。"}]}, {"meaning": "挪;搬取。", "cites": [{"t": "旁边只有一块大石头,掇将过来告了门。", "b": "《水浒传》"}], "words": [{"w": "掇盆;掇床", "t": ""}]}, {"meaning": "选取。", "cites": [{"t": "但二月草已芽,八月苗未枯,采掇者易辨识耳。", "b": "宋·沈括《梦溪笔谈·采草药》"}, {"t": "凡所著述五十八篇,掇其切于世事者著于传云。", "b": "《汉书·贾谊传》"}], "words": [{"w": "掇采", "t": "选取,搜集"}, {"w": "掇录", "t": "选录。"}]}, {"meaning": "端。", "cites": [{"t": "且向店里掇条凳子,坐了两个时辰。", "b": "《水浒传》"}], "words": [{"w": "掇臀捧屁", "t": "掇:端、捧之意。形容诌媚者的丑态。"}]}]}, {"pinyin": "duo", "defs": [{"meaning": "——见“撺掇”(cuānduo)、“掂掇”(diānduo)。"}]}]','jingmo-wenyan');
