INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4745wx','聃','1','dān','耳','11','','[{"pinyin": "dān", "defs": [{"meaning": "耳长大。", "cites": [{"t": "聃耳属肩,绮眉覆颧。", "b": "宋·苏轼《补禅月罗汉赞》"}]}, {"meaning": "吐舌的,伸出舌头状。", "cites": [{"t": "老子惊怪,故吐舌聃然,遂有老聃之号。", "b": "《太平广记》引葛洪《神仙传》"}]}, {"meaning": "古国名。", "cites": [{"t": "故封建亲戚以蕃屏周。管、蔡…聃…文之昭也。", "b": "《左传》"}]}, {"meaning": "人名用字。老聃,即老子,姓李名耳,春秋末年思想家,道家创始人。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4746wx','菁','1','jīng','艹','11','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从艸,青声。本义:韭菜花)。"}, {"meaning": "同本义。", "cites": [{"t": "菁,韭华(花)也。", "b": "《说文》"}, {"t": "其实菁菹。", "b": "《周礼·醢人》。司农曰:“非菹也。”"}, {"t": "以西菁菹。", "b": "《仪礼·公食礼》。注:“萱菁也。”"}]}, {"meaning": "泛指盛开的花。", "cites": [{"t": "秋兰茝蕙,江离载菁。", "b": "《文选·宋玉·高唐赋》"}], "words": [{"w": "菁菁者莪", "t": "原是《诗经·小雅》的篇名,此诗赞美培育人材,后世遂用来比喻乐育英才。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4747wx','萁','1','qí','艹','11','','[{"pinyin": "qí", "defs": [{"meaning": "豆秸。", "cites": [{"t": "萁,豆茎也。从艸,其声。", "b": "《说文》"}, {"t": "种一顷豆,落而为萁。", "b": "《汉书·杨恽传》"}, {"t": "炊萁燧火。", "b": "《淮南子·时则》"}], "words": [{"w": "萁秆", "t": "大豆的茎。晒干后可作燃料"}, {"w": "萁豆相煎", "t": "比喻骨肉自相残杀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4748wx','菘','1','sōng','艹','11','','[{"pinyin": "sōng", "defs": [{"meaning": "(形声。从艸,松声。本义:蔬菜名,又分为白菜、青菜、黄芽菜数种) 同本义 。十字花科。二年生草本栽培植物,变种甚多,通常称为白菜。是一种由野生的欧洲植物衍生而来的多叶的栽培植物,其特点是茎短,其上簇生着许多通常是绿色的叶片,形成紧密的球形头状结构,用作蔬菜。色白的叫“白菜”,淡黄的叫“黄芽菜”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4749wx','堇','1','jǐn','土','11','','[{"pinyin": "jǐn", "defs": [{"meaning": "假借为“仅”。少的。", "cites": [{"t": "堇堇物之所有。", "b": "《史记·货殖列传》"}, {"t": "豫章出黄金,然堇堇。", "b": "《汉书·地理志下》"}]}, {"meaning": "菜名。堇菜属植物泛称的略称。", "cites": [{"t": "堇,堇草也。根如荠,叶如细柳,蒸食之甘。", "b": "《说文》"}, {"t": "堇荁枌榆。", "b": "《礼记·内则》"}], "words": [{"w": "三色堇", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4750wx','萘','1','nài','艹','11','','[{"pinyin": "nài", "defs": [{"meaning": "一种结晶状芳香烃 。分子式C10H8,有一种特殊臭味,是煤焦油中最丰富的成分,通常由蒸馏煤焦油和从焦炉煤气回收制得,由两个稠合的苯环构成。主要用作有机合成的原料及用作熏蒸剂(如卫生球中)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4751wx','萋','1','qī','艹','11','','[{"pinyin": "qī", "defs": [{"meaning": "(形声。从艸,妻声。本义:草茂盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "萋,草盛也。", "b": "《说文》"}, {"t": "中庭萋兮鲜草生。", "b": "《汉书·外戚传》"}], "words": [{"w": "萋迷", "t": "草丛生茂密,造成视线阻隔。也指景象模糊不清"}, {"w": "萋芊", "t": "草木茂密的样子"}, {"w": "萋蒨", "t": "荫蔽;深密"}, {"w": "萋翳", "t": "茂密;荫蔽。"}]}, {"meaning": "花纹交错的样子。", "cites": [{"t": "萋兮斐兮。", "b": "《诗·小雅·巷伯》"}], "words": [{"w": "萋斐", "t": "萋菲。花纹交错的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4752wx','菽','1','shū','艹','11','','[{"pinyin": "shū", "defs": [{"meaning": "豆类的总称。", "cites": [{"t": "尗,豆也。象菽豆生之形也。", "b": "《说文》。按,象戴种而出之形,下其根也。一,地也。指事。"}, {"t": "菽草之难杀者也。", "b": "《汉书·五行志》"}, {"t": "菽者稼最强。古谓之尗,汉谓之豆,今字作菽。菽者,众豆之总名。然大豆曰菽,豆苗曰霍,小豆则曰荅。”", "b": ""}]}, {"meaning": "——《春秋·考异郵》。", "cites": [{"t": "中原有菽,小民采之。", "b": "《诗·小雅·小宛》"}, {"t": "俗孝家家供菽水。", "b": "陆游《湖堤暮归》"}], "words": [{"w": "菽水", "t": "指豆和水,指菲薄的饮食,形容生活的清苦;指晚辈对长辈的奉养"}, {"w": "菽水藜藿", "t": "粗茶淡饭。藜藿:野菜;豆叶"}, {"w": "菽乳", "t": "即豆腐"}, {"w": "菽麦", "t": "大豆和麦"}, {"w": "菽麦不分", "t": "豆、麦不分。亦指是非、好坏不分。"}]}]}]','jingmo-wenyan');
