('4763wx','菹','1','zū','艹','11','','[{"pinyin": "zū", "defs": [{"meaning": "(形声。从艸,沮(jū)声。本义;腌菜)。"}, {"meaning": "同本义。", "cites": [{"t": "菹,酢菜也。", "b": "《说文》。字亦作葅。"}, {"t": "水草之菹。", "b": "《礼记·祭统》"}, {"t": "七菹。", "b": "《周礼·醢人》"}, {"t": "馈食之豆,其实葵菹", "b": "《周礼》"}], "words": [{"w": "菹醢", "t": "盐腌的野菜、肉酱"}, {"w": "菹酱", "t": "葅酱。酱菜。"}]}, {"meaning": "枯干的草。", "cites": [{"t": "请君伐菹薪,煮沸水为盐。", "b": "《管子·轻重甲》"}], "words": [{"w": "菹笠", "t": "用茅草编织的笠"}, {"w": "菹薪", "t": "枯槁的草木;柴草。"}]}, {"meaning": "肉酱。", "cites": [{"t": "麋鹿为菹。", "b": "《礼记·内则》"}], "words": [{"w": "菹脍", "t": "鱼肉酱"}]}, {"meaning": "水草丛生的沼泽地。", "cites": [{"t": "纽菹之兽。", "b": "《穆天子传》。注:“吴人呼田猎茸草地曰菹。”"}], "words": [{"w": "菹泽", "t": "水草繁茂的沼泽地"}, {"w": "菹薮", "t": "水草繁茂的湖泽。"}]}, {"meaning": "古代一种酷刑,把人剁成肉酱。", "cites": [{"t": "菹其骨肉于市。", "b": "《汉书·刑法志》"}]}]}]','jingmo-wenyan');
