INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4765wx','菅','1','jiān','艹','11','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。从艸,官声。本义:菅茅)。"}, {"meaning": "同本义 。一种多年生草本植物(Themeda giganteavar.villosa),叶子细长而尖,花绿色,结颖果,褐色。", "cites": [{"t": "白华菅兮,白茅束兮。", "b": "《诗·小雅·白华》"}], "words": [{"w": "菅茅", "t": "茅草的一种"}, {"w": "菅菲", "t": "菅履,草鞋"}, {"w": "菅筲", "t": "用菅草编的盛饭器"}, {"w": "菅荐", "t": "草席。"}]}, {"meaning": "也表示茅草的统称。", "cites": [{"t": "虽有丝、麻,无弃菅、蒯。", "b": "《左传·成公九年》"}], "words": [{"w": "菅蒯", "t": "茅草之类,可编绳索;亦指草鞋。"}]}, {"meaning": "中国古地名 。春秋宋地。在今山东单县北。", "cites": [{"t": "公败宋师于菅。", "b": "《春秋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4766wx','菀','1','wǎn yù','艹','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "茂盛的样子。", "cites": [{"t": "菀彼桑柔。", "b": "《诗·大雅·桑柔》。传:“菀,茂貌。”"}, {"t": "有菀其特。", "b": "《诗·小雅·正月》"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "茂盛。", "cites": [{"t": "菀彼桑柔,其下侯旬。", "b": "《诗·大雅·桑柔》"}], "words": [{"w": "菀枯", "t": "草木的茂盛与枯萎。比喻人的荣辱、优劣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4767wx','萦','1','yíng','艹','11','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从糸(mì),荧(yíng)省声。糸,细丝。本义:回旋缠绕)。"}, {"meaning": "同本义。", "cites": [{"t": "萦,收卷也。", "b": "《说文》"}, {"t": "收绩曰萦。", "b": "《通俗文》"}, {"t": "萦,绕也。", "b": "《广韵》"}, {"t": "葛藟萦之。", "b": "《诗·周南·寥木》"}, {"t": "百步九折萦岩峦。", "b": "李白《蜀道难》"}, {"t": "峻赠怪石列,崎岖曲道萦。", "b": "《西游记》"}], "words": [{"w": "萦抱", "t": "环抱"}, {"w": "萦环", "t": "环绕;佩带环饰"}, {"w": "萦萦", "t": "缠绕的样子。"}]}, {"meaning": "弯曲。", "cites": [{"t": "断梗桔槎无拍处,一川寒碧自萦回。", "b": "宋·朱熹《偶题》"}], "words": [{"w": "萦薄", "t": "草木丛生的弯曲地带。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4768wx','菰','1','gū','艹','11','','[{"pinyin": "gū", "defs": [{"meaning": "植物名 。即茭白。禾本科,菰属。一种多年水生高秆的禾草类植物,茎中因寄生菌的作用而形成笋状结构,称茭白笋,可供食用", "words": [{"w": "菰稗", "t": "茭白和稗子"}, {"w": "菰首", "t": "即茭白"}, {"w": "菰苇", "t": "指茭白和苇"}]}, {"meaning": "", "words": [{"w": "草菰", "t": ""}, {"w": "香菰", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4769wx','菡','1','hàn','艹','11','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从苃，函声。菡萏。本义荷花)。"}, {"meaning": "古人称未开的荷花为菡萏,即花苞。", "cites": [{"t": "迨至菡萏成花。--明·李渔《闲情偶寄·种植部》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4770wx','梵','1','fàn','木','11','','[{"pinyin": "fàn", "defs": [{"meaning": "(形声。从林,凡声。本义:梵梵:草木茂盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "梵,即芃之俗体。", "b": "清·钮树玉《说文新附考》"}]}, {"meaning": "梵语Brahmā音译词“梵摩”、“婆罗贺摩”、“梵览摩”之省,意为“清净”、“寂静”。", "cites": [{"t": "净修梵行。", "b": "《妙法莲花经》"}], "words": [{"w": "梵心", "t": "清净之心"}, {"w": "梵志", "t": "以清静为志"}, {"w": "梵门", "t": "清净的法门"}, {"w": "梵事", "t": "清净的佛事。"}]}, {"meaning": "诵经声。", "cites": [{"t": "午梵隔云知有寺,夕阳归去不逢僧。", "b": "宋·王安石《游钟山四首》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4771wx','梿','1','lián','木','11','','[{"pinyin": "lián", "defs": [{"meaning": "古书上说的一种丛生的树。 "}, {"meaning": "一种用来拍打谷物使脱粒的农具。 "}, {"meaning": "一种用来拍打谷物使脱粒的农具。 "}, {"meaning": "楼阁边相连的小屋。 "}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4772wx','梏','1','gù','木','11','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从木,告声。本义:木手铐)。"}, {"meaning": "同本义。", "cites": [{"t": "梏,手械也。", "b": "《说文》"}, {"t": "命有司省囹圄,去桎梏。", "b": "《吕氏春秋·仲春》"}, {"t": "在足曰桎,在手曰梏。", "b": "《易·蒙》疏"}, {"t": "甫愍然为之改容,乃得并解桎梏。", "b": "《汉书·范滂传》"}, {"t": "凡囚者,上罪梏拲(两手关械)而桎,中罪桎梏,下罪梏。", "b": "《周礼·秋官·掌囚》"}], "words": [{"w": "梏桎", "t": "即桎梏。束缚手足的刑具"}, {"w": "梏掠", "t": "用刑拷问"}, {"w": "梏拲", "t": "古代刑具,也指械系。"}]}, {"meaning": "为了防牛触人而套在牛角上的横木。字本作告。", "cites": [{"t": "告,牛触人,角箸横木,所以告人也。", "b": "《说文》"}]}, {"meaning": "戴上手铐。也泛指械系,拘系。", "cites": [{"t": "执而梏之。", "b": "《左传·成公十七年》"}, {"t": "主梏扑者亦然。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "监禁。", "cites": [{"t": "帝乃梏之疏属之山(疏属:山名)。", "b": "《山海经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4773wx','觋','1','xí','见','11','','[{"pinyin": "xí", "defs": [{"meaning": "男巫师,以装神弄鬼替人祈祷为职业的人,男称“觋”(或“祝”,女称“巫”)。", "cites": [{"t": "则觋之妄者,又何以为宝。", "b": "柳宗元《非国语下》"}, {"t": "话说男觋女巫,自古有之。汉时谓之“下神”,唐世呼为“见鬼人”。", "b": "《初刻拍案惊奇》"}], "words": [{"w": "觋女", "t": "巫婆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4774wx','桴','1','fú','木','11','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从木,孚(fú)声。本义:房屋的二梁)。"}, {"meaning": "同本义。", "cites": [{"t": "桴,栋名。", "b": "《说文》"}, {"t": "栋谓之桴。", "b": "《尔雅·释宫》。注:“屋稳。”"}, {"t": "桴,极也。", "b": "《字林》。按,凡五架屋,正中曰栋,亦曰阿,次曰俘,亦曰梁。"}, {"t": "重桴乃饰。", "b": "何晏《景福殿赋》。注:“重栋也。”"}, {"t": "荷栋柎而高骧。", "b": "东汉·班固《西都赋》"}], "words": [{"w": "桴栋", "t": "栋梁。"}]}, {"meaning": "小的竹、木筏子。", "cites": [{"t": "乘桴浮于海。", "b": "《论语·公冶长》。皇疏:“桴者,编竹木也。大曰筏,小曰桴。”"}, {"t": "乘桴济河。", "b": "《国语·齐语》。注:“小泭曰桴。”"}], "words": [{"w": "桴木", "t": "木筏"}, {"w": "桴人", "t": "船夫"}, {"w": "桴筏", "t": "竹、木筏"}, {"w": "桴槎", "t": "木筏。"}]}, {"meaning": "鼓槌。", "cites": [{"t": "[却克]左并辔,右援桴而鼓。", "b": "《左传·成公二年》"}], "words": [{"w": "桴革", "t": "鼓锤与战甲"}, {"w": "桴鼓", "t": "鼓锤与鼓。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4775wx','桷','1','jué','木','11','','[{"pinyin": "jué", "defs": [{"meaning": "方形的椽子。", "cites": [{"t": "细木为桷。", "b": "韩愈《进学解》"}], "words": [{"w": "桷杙", "t": "木椽、木桩之类的木料。"}]}, {"meaning": "指横平可作桷的树枝。", "cites": [{"t": "鸿渐于木,或得其桷。", "b": "《易·渐》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4776wx','梓','1','zǐ','木','11','','[{"pinyin": "zǐ", "defs": [{"meaning": "(形声。从木,宰省声。本义:木名,即梓树)。"}, {"meaning": "同本义 。一种原产中国的梓树属落叶乔木,高6—9米,叶对生,宽卵形,先端尖。大的圆锥花序,顶生,黄白色,略带紫色斑点,蒴果长丝状,种子扁平,木材可供建筑及制作木器用。", "cites": [{"t": "梓,楸也。", "b": "《说文》"}, {"t": "树之榛栗,椅、桐、梓、漆。", "b": "《诗·鄘风·定之方中》"}, {"t": "江南出楠梓。", "b": "《史记·货殖列传》"}], "words": [{"w": "美国梓;海地梓;四川梓", "t": ""}]}, {"meaning": "制作木器的人。", "cites": [{"t": "攻木之工,轮、舆、弓、炉、匠、车、梓。", "b": "《周礼·考工记》"}], "words": [{"w": "梓人", "t": "古代木工的一种"}, {"w": "梓匠", "t": "两种木工。梓,梓人,造器具;匠,匠人,主建筑"}, {"w": "梓师", "t": "古代梓人之长"}, {"w": "梓器", "t": "木工所制的器具。"}]}, {"meaning": "雕刻印书的木版。", "cites": [{"t": "闻以华严合论梓行,此希有功德也。", "b": "张居正《答奉常陆五台书》"}], "words": [{"w": "梓人", "t": "指印刷业的刻版工人"}, {"w": "梓行", "t": "刻版印行"}, {"w": "梓刻", "t": "雕版,表示书将印行。"}]}, {"meaning": "故乡的代称。桑梓的简称  因为古代宅旁常栽的树,是梓和桑。", "cites": [{"t": "吾不爱锦衣,荣归夸梓里。", "b": "刘迎《题刘德文戏彩堂》"}], "words": [{"w": "梓里", "t": "故乡"}, {"w": "梓乡", "t": "故乡。"}]}, {"meaning": "刻板,付印。", "cites": [{"t": "故归梓删去。", "b": "宋应星《天工开物序》"}]}, {"meaning": "又。", "cites": [{"t": "其友涂伯聚为之梓行。", "b": ""}], "words": [{"w": "付梓", "t": "付印。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4777wx','棁','1','zhuō','木','11','','[{"pinyin": "zhuō", "defs": [{"meaning": "木杖。", "cites": [{"t": "棁,木杖也。", "b": "《说文》"}, {"t": "手持三尺棁仗,坐大营门,以杖捶地大骂。", "b": "《后汉书·文苑传》"}], "words": [{"w": "棁杖", "t": "长而大的木杖。"}]}, {"meaning": "梁上的短柱。", "cites": [{"t": "以瑟瑟为殿柱,水精、琉璃为棁。", "b": "《新唐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4778wx','桫','1','suō','木','11','','[{"pinyin": "suō", "defs": [{"meaning": "木名。桫椤。", "cites": [{"t": "古人藏书,多用芸香,即今之七里香也。匣柜须用楸、梓、杉、桫之类,忌油松,内不用漆。", "b": "《芸窗类记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4779wx','棂','1','líng','木','11','','[{"pinyin": "líng", "defs": [{"meaning": "窗户或栏杆上雕有花纹的格。", "cites": [{"t": "櫺,楯间子也。", "b": "《说文》"}, {"t": "曲棂激鲜飙。", "b": "江淹《拟许征君诗》"}], "words": [{"w": "棂角", "t": "窗格的拐角"}, {"w": "棂轩", "t": "有窗格的长廊"}, {"w": "棂床", "t": "有栏槛的床"}, {"w": "棂槛", "t": "栏杆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4780wx','啬','1','sè','口','11','','[{"pinyin": "sè", "defs": [{"meaning": "(会意。甲骨文字形,象粮食收入谷仓形。小篆从来回,“来”是小麦,“回”(lǐng)是仓库。本义:收获谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "(嗇)此字本训当为收谷,即穑之古文也。转注为爱濇之义,或借为濇。", "b": "朱骏声《说文通训定声》"}, {"t": "腊之祭也,主先啬而祭司啬也。", "b": "《礼记·郊特牲》"}, {"t": "啬夫承命。", "b": "《仪礼·觐礼》"}, {"t": "王狩,啬人不从。", "b": "《仪礼·夏小正》。按,重农事也。"}, {"t": "主人出,写啬于房。", "b": "《仪礼·特牲礼》。注:“啬者,农力之成功。”"}, {"t": "主先啬而祭司啬也。", "b": "《礼记·郊特牲礼》。疏:“种曰稼,敛曰啬。”"}, {"t": "舍我啬事。", "b": "《史记·殷本纪》"}, {"t": "啬黍。", "b": "《仪礼·少牢礼》。注:“收敛曰啬。”"}, {"t": "服田力啬。", "b": "《汉书·成帝纪》"}], "words": [{"w": "啬事", "t": "农事"}, {"w": "啬夫", "t": "农夫,同穑夫,穑人"}, {"w": "啬黍", "t": "收获的黍稷。"}]}, {"meaning": "爱惜。", "cites": [{"t": "啬,爱濇也。", "b": "《说文》"}, {"t": "治人事天,莫若啬。", "b": "《老子》"}, {"t": "凡事之本,必先治身,啬其大宝。", "b": "《吕氏春秋·先己"}], "words": [{"w": "吝啬", "t": "过分爱惜自己的财物"}, {"w": "啬神", "t": "爱惜精神"}, {"w": "啬气", "t": "爱惜保养元气"}, {"w": "啬养", "t": "犹保养。"}]}, {"meaning": "节省;节俭。", "cites": [{"t": "少费谓之啬。", "b": "《韩非子·解老》"}], "words": [{"w": "啬夫", "t": "俭省节用的人。"}]}, {"meaning": "吝啬,悭啬。", "cites": [{"t": "夫小人之性,衅于勇,啬于祸。", "b": "《左传·襄公二十六年》。注:“贪也。”"}, {"t": "晚节啬。", "b": "《史记·五宗世家》"}, {"t": "啬,贪也。凡贪而不施,或曰之啬。", "b": "《方言十》"}, {"t": "仲啬于财。", "b": "《战国策·韩策》"}], "words": [{"w": "啬后", "t": "迷信。指上天吝啬给人的寿命,使之早死"}, {"w": "啬克", "t": "亦作“啬刻”。吝啬,刻薄"}, {"w": "啬吝", "t": "亦作“啬恡。吝啬"}, {"w": "啬细", "t": "吝啬,小气。"}]}, {"meaning": "闭塞不通。", "cites": [{"t": "诊其脉时,切之,肾脉也,啬而不属。", "b": "《史记·扁鹊仓公传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4781wx','郾','1','yǎn','阝','11','','[{"pinyin": "yǎn", "defs": [{"meaning": "古县名 。古郾子国地,战国属魏,秦置郾县。故城在今河南省郾城县南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4782wx','匮','1','kuì','匚','11','','[{"pinyin": "kuì", "defs": [{"meaning": "(形声。从匚(fāng),表示与盛放东西有关,贵声。(guì)本义:柜子)。"}, {"meaning": "运装土的畚", "cites": [{"t": "纲纪咸张,成在一匮。", "b": "《汉书·王莽传上》"}, {"t": "孔子曰:“辟如为山,未成一匮。止,吾止也。”", "b": "《汉书·礼乐志》"}]}, {"meaning": "缺乏,空乏。", "cites": [{"t": "匱,乏也。", "b": "《广雅》"}, {"t": "财财不匮。", "b": "《礼记·月令仲秋》"}, {"t": "其财匮。", "b": "《礼记·乐记》"}, {"t": "虞不出财财匮少。", "b": "《史记·货殖列传》"}, {"t": "财匮少而山泽不辟矣。", "b": ""}], "words": [{"w": "匮竭", "t": "穷尽,缺乏财货"}, {"w": "匮粮", "t": "缺乏粮食"}, {"w": "匮少", "t": "缺少"}, {"w": "匮饿", "t": "缺粮饥饿"}, {"w": "匮矮", "t": "缺粮饥饿"}, {"w": "匮阕", "t": "缺乏。"}]}, {"meaning": "", "cites": [{"t": "貴而不傲,富而不骄,两而不爭,闻而不遥,远而不绝,穷而不匮者鲜矣。", "b": "《逸周书》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4783wx','敕','1','chì','攵','11','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从攴(pū),束声。本义:告诫,嘱咐)。"}, {"meaning": "同本义。", "cites": [{"t": "敕,诫也。", "b": "《说文》"}, {"t": "敕天之命。", "b": "《虞书》"}], "words": [{"w": "敕晓", "t": "告戒晓谕"}, {"w": "敕谕天下", "t": "朝廷告谕全国"}, {"w": "敕戒", "t": "警戒,教诫。"}]}, {"meaning": "整治;整饬。", "cites": [{"t": "既匡既敕。", "b": "《诗·小雅·楚茨》"}, {"t": "君子以明罚勅法。", "b": "《易·噬嗑》"}, {"t": "敕身齐戒。", "b": "《汉书·礼乐志》"}, {"t": "惧余身之未敕。", "b": "《后汉书·张衡传》"}], "words": [{"w": "敕法", "t": "整饬法令"}, {"w": "敕设", "t": "整饬周备。"}]}, {"meaning": "皇帝,帝王自上命下之词(汉时凡尊长或官长告诫子孙或僚属,皆称敕。南北朝以后专指皇帝诏书)。", "cites": [{"t": "手把文书口称敕,回车叱牛牵向北。", "b": "白居易《卖炭翁》"}], "words": [{"w": "敕书", "t": "皇帝行文给臣僚的文书"}, {"w": "敕命", "t": "皇帝颁赐爵位或物品的诏命"}, {"w": "敕符", "t": "书有皇帝命令的凭证。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4784wx','豉','1','chǐ','豆','11','','[{"pinyin": "chǐ", "defs": [{"meaning": "用煮熟的大豆或小麦发酵后制成。有咸、淡二种。供调味用。淡的也可入药", "words": [{"w": "豉酒", "t": "用豆豉浸渍的酒,可供药用"}, {"w": "豉羹", "t": "即豆豉"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4785wx','鄄','1','juàn','阝','11','','[{"pinyin": "juàn", "defs": [{"meaning": "古地名。"}, {"meaning": "春秋卫邑。汉为鄄城县。在今山东省鄄城北旧城。"}, {"meaning": "周邑。", "cites": [{"t": "王使刘子复之,盟于鄄而入。", "b": "《左传》"}]}]}]','jingmo-wenyan');
