INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4787wx','酚','1','fēn','酉','11','','[{"pinyin": "fēn", "defs": [{"meaning": "由羟基与芳香环(苯环)直接相连而成的化合物总称。大多数为无色晶体,难溶于水。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4788wx','戛','1','jiá','戈','11','','[{"pinyin": "jiá", "defs": [{"meaning": "(会意。从首(shǒu),头,从戈。合起来指杀头的兵器。①本义:戟,一种兵器②敲击,弹奏)。"}, {"meaning": "轻轻地敲打。", "cites": [{"t": "戛击鸣球。", "b": "《书·益稷》"}], "words": [{"w": "戛玉敲金", "t": "形容声调铿锵悦耳"}, {"w": "戛击", "t": "敲击"}, {"w": "戛玉", "t": "敲击玉片。"}]}, {"meaning": "刮,用刀去掉某物。", "cites": [{"t": "铁线弓戛平其面。", "b": "《天工开物》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4789wx','硎','1','xíng','石','11','','[{"pinyin": "xíng", "defs": [{"meaning": "(形声。从石,刑声。本义:磨刀石)。"}, {"meaning": "同本义。", "cites": [{"t": "刀刃若新发于硎。", "b": "《庄子·养生主》"}, {"t": "胡不砺刃于硎以待?", "b": "明·马中锡《中山狼传》"}]}, {"meaning": "盛食物的器皿。", "cites": [{"t": "衣布褐,饭土硎。", "b": "《盐铁论》"}]}, {"meaning": "用同“型”。仪型;式样。", "cites": [{"t": "毋劳逖听,请从近硎。", "b": "明·钱肃乐《两试序》"}]}, {"meaning": "磨。", "cites": [{"t": "斩材窾坚,液矿硎鋩。", "b": "唐·刘禹锡《天论上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4790wx','硭','1','máng','石','11','','[{"pinyin": "máng", "defs": [{"meaning": "一种白色或无色结晶体，成分是硫酸钠，医药上用作泻剂，是化工、玻璃、造纸工业的原料。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4791wx','硒','1','xī','石','11','','[{"pinyin": "xī", "defs": [{"meaning": "一种非金属的有毒元素,与硫、碲有关联并在化学方面与它们相似,以同素异形体存在。主要用于光电池、整流器和其他电子装置中 ——元素符号Se。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4792wx','硖','1','xiá','石','11','','[{"pinyin": "xiá", "defs": [{"meaning": "两山间的溪谷。", "cites": [{"t": "硖深仰面窥天细,路险行吟得句奇。", "b": "《三宝太监西洋记通俗演义》"}, {"t": "淮水又北径山硖中。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4793wx','硗','1','qiāo','石','11','','[{"pinyin": "qiāo", "defs": [{"meaning": "(形声。从石,尧声。本义:土地坚硬而瘠薄)。"}, {"meaning": "同本义。", "cites": [{"t": "硗,磐石也。字亦作墝。", "b": "《说文》"}, {"t": "则地有肥硗。", "b": "《孟子》。注:“薄也。”"}, {"t": "瘠硗之地。", "b": "《国语·楚语》"}], "words": [{"w": "硗薄", "t": "土地坚硬而不肥沃"}, {"w": "硗瘠", "t": "土地坚硬而贫瘠"}, {"w": "硗秃", "t": "贫瘠多石不生草木之地。"}]}, {"meaning": "坚硬。", "cites": [{"t": "田者争处墝埆。", "b": "《淮南子·原道》"}, {"t": "物坚硬谓之硗埆。", "b": "《通俗文》"}], "words": [{"w": "硗确", "t": "坚石;多石而坚硬的路。"}]}, {"meaning": "薄的。", "cites": [{"t": "形细翼硗轻巧,灭灯扑烛投明。", "b": "《西游记》"}]}, {"meaning": "坚硬的石头。", "cites": [{"t": "硗,乃石之坚者。", "b": "承培元《广说文答问疏证》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4794wx','硐','1','dòng','石','11','','[{"pinyin": "dòng", "defs": [{"meaning": "——通“洞”、“峒”。用于山洞、窑洞。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4795wx','硇','1','náo','石','11','','[{"pinyin": "náo", "defs": [{"meaning": "矿物，黄白色粉末或块状，味辛咸，是氯化铵的天然产物。工业上用来制干电池，焊接金属。医药上可做祛痰剂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4796wx','硌','1','gè luò','石','11','','[{"pinyin": "gè", "defs": [{"meaning": "触着凸起的东西觉得不舒服或受到损伤。", "cites": [{"t": "这条石子路真硌脚", "b": ""}], "words": [{"w": "硌脚;硌牙", "t": "牙齿被硬物垫磨、损伤。"}]}]}, {"pinyin": "luò", "defs": [{"meaning": "大石。", "cites": [{"t": "上无草木,而多硌石。", "b": "《山海經》"}]}, {"meaning": "坚硬。", "cites": [{"t": "是故不欲禄禄若玉,硌硌若石。", "b": "《老子》"}]}, {"meaning": "用同“摞”。重叠堆起。", "cites": [{"t": "他却搬张桌子,又硌张椅子,坐在上面。", "b": "《儿女英雄传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4797wx','鸸','1','ér','鸟','11','','[{"pinyin": "ér", "defs": [{"meaning": "鸟纲，鸸鹋科。体形似鸵鸟而较小，高约5米。主食植物，常4-6只结群生活。产于澳大利亚和塔斯马尼亚的草原和沙漠地区。可人工饲养，取用羽毛。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4798wx','瓠','1','hù','瓜','11','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从瓜,夸声。本义:瓠瓜) 同本义 。一年生草本植物,爬蔓,夏开白花,果实长圆形,嫩时可吃", "words": [{"w": "瓠齿", "t": "整齐、洁白的牙齿"}, {"w": "瓠肥", "t": "又白又胖"}, {"w": "瓠脯", "t": "干菜的一种。即瓠子干"}, {"w": "瓠犀", "t": "瓠瓜的子。因排列整齐,色泽洁白,所以常用来比喻美人的牙齿。也作瓠栖"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4799wx','匏','1','páo','勹','11','','[{"pinyin": "páo", "defs": [{"meaning": "(会意。《说文》:“从包从瓠省。包,取其可包藏物也。”按:“瓠”(hù)葫芦。省:即省形,选取“瓠”字形体的一部分“夸”,与“包”会合成义。本义:葫芦的一种,即匏瓜)。"}, {"meaning": "同本义。", "cites": [{"t": "匏,瓠也。", "b": "《说文》"}, {"t": "匏有苦叶。", "b": "《诗·邶风·匏有苦叶》"}, {"t": "吾岂匏瓜也哉?", "b": "《论语·阳货》"}, {"t": "其器陶匏。", "b": "《汉书·郊祀志下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4800wx','厩','1','jiù','厂','11','','[{"pinyin": "jiù", "defs": [{"meaning": "(形声。古文字中,“厂”(hǎn)与“广”常常通用,都表示与房舍、居住有关。本义:马圈,马棚)。"}, {"meaning": "同本义。", "cites": [{"t": "厩,马舍也。", "b": "《说文》"}, {"t": "六系为厩,厩一仆夫,计马二百十六匹也。", "b": "《周礼·校人》"}, {"t": "新延厩。", "b": "《左传·庄公二十九年》"}, {"t": "厩焚。", "b": "《论语》"}, {"t": "狗马实外厩。", "b": "《战国策·齐策四》"}, {"t": "厩中仆马。", "b": "明·宗臣《报刘一丈书》"}, {"t": "所立厩中。", "b": ""}], "words": [{"w": "厩长", "t": "掌管马厩的官吏"}, {"w": "厩苑", "t": "养马场"}, {"w": "厩率", "t": "马夫"}, {"w": "厩副", "t": "马厩的副职官长"}, {"w": "厩圉", "t": "马棚"}, {"w": " 厩闲", "t": "马房。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4801wx','龚','1','gōng','龙','11','','[{"pinyin": "gōng", "defs": [{"meaning": "(“供”的古字。形声。从龙,共声。本义:供给"}, {"meaning": "同本义。", "cites": [{"t": "龚,给也。", "b": "《说文》。段玉裁注:《系部》曰:给,相足也。此与《人部》供音义同。今供广而龚废也。"}, {"t": "龚工氏之子曰句龙。", "b": "《孔子家语·五帝》"}, {"t": "奉职输赋,进比蕈人,无敢不龚。", "b": "柳宗元《武冈铭》"}]}, {"meaning": "恭敬。", "cites": [{"t": "象龚滔天。师古注:貌象恭敬,过恶漫天。", "b": "《汉书·王尊传》"}], "words": [{"w": "龚行", "t": "恭敬的行为。"}]}, {"meaning": "奉,奉行。", "cites": [{"t": "龚,奉也。", "b": "《玉篇》"}, {"t": "今予维龚行天之罚。", "b": "《书·甘誓》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4802wx','殒','1','yǔn','歹','11','','[{"pinyin": "yǔn", "defs": [{"meaning": "(形声。从歺(“歹”是隶楷写法),员声。歺(è),剔肉残余的骨头,常与“死亡”有关。本义:死亡)。"}, {"meaning": "同本义。", "cites": [{"t": "殒,没也。", "b": "《一切经音义》引《声类》"}, {"t": "殒,字书作陨,同于敏反。", "b": "《一切经音义三》"}, {"t": "妻子颠殒。", "b": "《后汉书·隗嚣传》"}, {"t": "未尝殒于城中。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "殒亡", "t": "灭亡"}, {"w": "殒骨", "t": "亡躯"}, {"w": "殒没", "t": "死亡"}, {"w": "殒逝", "t": "丧亡;逝世"}, {"w": "殒谢", "t": "谢世,死亡。"}]}, {"meaning": "坠落。", "cites": [{"t": "列星殒坠。", "b": "《荀子·赋》"}, {"t": "殒越为期。", "b": "任昉《为齐明帝让宣城郡公第一表》"}, {"t": "禹为天子,而启为嗣,持禹之功而不殒。", "b": "汉·刘向《列女传》"}], "words": [{"w": "殒越", "t": "坠落;毁败"}, {"w": "殒涕", "t": "殒泣。落泪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4803wx','殓','1','liàn','歹','11','','[{"pinyin": "liàn", "defs": [{"meaning": "(形声。字本作“敛”。从歹,佥(qiān)声。从“歹”,表示与死亡有关。本义:装殓。给尸体穿衣下棺) 同本义。", "cites": [{"t": "殓,殡殓。", "b": "《广韵》"}, {"t": "殓不凭其棺,窆不临其穴。", "b": "唐·韩愈《祭十二郎文》"}, {"t": "死者厚棺殓。", "b": "清·邵长蘅《青门剩稿》"}, {"t": "今予殓汝葬汝。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "大殓", "t": "丧礼中入棺、钉棺盖"}, {"w": "殡殓", "t": "入殓和出殡"}, {"w": "成殓", "t": "入殓。把死者放进棺材。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4804wx','殍','1','piǎo','歹','11','','[{"pinyin": "piǎo", "defs": [{"meaning": "(形声。从歹,孚声。歹(è)。列骨之残。此部之字多与死、不吉祥等义有关。本义:饿死后无人收尸的人) 同本义。", "cites": [{"t": "野有饿殍。", "b": "《盐铁论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4805wx','赉','1','lài','贝','11','','[{"pinyin": "lài", "defs": [{"meaning": "(形声。从贝,来声。本义:赏赐)。"}, {"meaning": "同本义。", "cites": [{"t": "赉,赐也。", "b": "《说文》"}, {"t": "予其大赉汝。", "b": "《商君·汤誓》"}, {"t": "赉,大封于庙也。赉,予也。", "b": "《诗·赉序》"}, {"t": "徂赉孝孙。", "b": "《诗·小雅·楚茨》"}, {"t": "赉我思成。", "b": "《诗·商颂·烈祖》"}, {"t": "周有大赉,善人是富。", "b": "《论语》"}, {"t": "抚军亦厚赉成名。", "b": "《聊斋志异·促织》"}], "words": [{"w": "赉假", "t": "古代帝王下诏赐给假期"}, {"w": "赉赏", "t": "赏赐"}, {"w": "赉奖", "t": "奖赏,赏赐"}, {"w": "赉赐", "t": "赏赐"}, {"w": "赉功", "t": "赏赐有功者。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4806wx','雩','1','yú','雨','11','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从雨,亏(于)声。本义:古代为求雨而举行的祭祀) 同本义。", "cites": [{"t": "雩,夏祭乐于赤帝,以祈甘雨也。", "b": "《说文》"}, {"t": "则帅巫而舞雩。", "b": "《周礼·司巫》"}, {"t": "大雩者何,旱祭也。", "b": "《公羊传·桓公五年》。注:“使童男女各八人舞而呼雨,故谓之雩。”"}, {"t": "雩而雨,何也?曰,无何也,犹不雩而雨也。", "b": "《荀子·天论》"}], "words": [{"w": "雩宗", "t": "设祭坛祭水旱"}, {"w": "雩祭", "t": "求雨祭祀"}, {"w": "雩敛", "t": "向人民征收祈雨祭礼所需的费用"}, {"w": "雩坛", "t": "求雨的祭坛。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4807wx','辄','1','zhé','车','11','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。本义:车箱左右板上端向外翻出的部分,亦称“车耳”)。"}, {"meaning": "同本义。"}, {"meaning": "专擅,独断专行,专权。", "cites": [{"t": "辄,专辄也。", "b": "《广韵》"}, {"t": "辄,遇事既然也。皆倚恃妄作之意。", "b": "《韵会》"}, {"t": "臣辄敕主者及黄门令罢爽羲训吏兵,以就第。", "b": "《三国志》"}, {"t": "甘受专辄之罪。", "b": "《晋书·刘弘传》"}], "words": [{"w": "辄代", "t": "擅自替代"}, {"w": "辄行", "t": "辄自行使"}, {"w": "辄尔", "t": "任意"}, {"w": "辄悔", "t": "擅自反悔;随便反悔。"}]}, {"meaning": "立即;就。", "cites": [{"t": "饮少辄醉。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "故有所览辄省记。(因为迫切的要读书,又得不到书,所以有看过的就记在心里。所览,所看过的书。辄,副词,立即,就。省记,用心记住。省,深思。)", "b": "清·袁枚《黄生借书说》"}], "words": [{"w": "辄议蠲除", "t": "马上商议取消或废除"}, {"w": "辄造", "t": "就来造访;冒然造访"}, {"w": "辄斩", "t": "就杀;立即斩杀。"}]}, {"meaning": "总是,每次。", "cites": [{"t": "每冒风驰行,未百步辄返。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "动辄得咎", "t": ""}]}, {"meaning": "则。", "cites": [{"t": "地方百里之增减,辄为粟百八十万石。", "b": "《汉书·食货志》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4808wx','堑','1','qiàn','土','11','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从土,斩声。本义:护城河,壕沟)。"}, {"meaning": "同本义。", "cites": [{"t": "堑,防也。", "b": "《说文》"}, {"t": "堑山堙谷。", "b": "《史记·秦本纪》。索引:绕城水也。"}, {"t": "深堑而守。", "b": "《史记·高祖纪》"}, {"t": "隤墙填堑。", "b": "《史记·司马相如传》"}], "words": [{"w": "堑渊", "t": "沟壑深潭"}, {"w": "堑垒", "t": "深壕与堡垒"}, {"w": "堑坎", "t": "深坑"}, {"w": "堑谷", "t": "沉陷的坑谷"}, {"w": "天堑", "t": ""}]}, {"meaning": "挖掘。", "cites": [{"t": "环而堑之。", "b": "《左传》。注:“沟堑也。”"}, {"t": "厕足而堑之。", "b": "《庄子·外物》。释文:“掘也。”"}]}]}]','jingmo-wenyan');
