('4809wx','眭','1','suī','目','11','','[{"pinyin": "suī", "defs": [{"meaning": "姓", "cites": [{"t": "眭,姓也。出赵郡。", "b": "《广韵·支韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4810wx','眦','1','zì','目','11','','[{"pinyin": "zì", "defs": [{"meaning": "(形声。从目,此声。本义:眼角)。"}, {"meaning": "同本义。", "cites": [{"t": "眥,目厓也。", "b": "《说文》"}, {"t": "拭眥扬眉而望之。", "b": "《列子·汤问》"}, {"t": "目赤痛眥疡。", "b": "《素问·气交变大论》"}, {"t": "瞋目视项王,头发上指,目眦尽裂。", "b": "《史记·项羽本纪》"}]}, {"meaning": "眼眶。", "cites": [{"t": "中必决眦。", "b": "司马相如《子虚赋》"}], "words": [{"w": "眦裂", "t": "张目怒视,眼眶破裂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4811wx','啧','1','zé','口','11','','[{"pinyin": "zé", "defs": [{"meaning": "大呼,大声喊叫。", "cites": [{"t": "啧,大呼也。从口,责声。", "b": "《说文》。字亦作赜。按,大呼者唶字之训。此字当训争言也。"}]}, {"meaning": "争辩。", "cites": [{"t": "啧有烦言。", "b": "《左传·定公四年》"}, {"t": "啧然而不类。", "b": "《荀子·正名》"}, {"t": "啧啧怒语,与人相拒。", "b": "汉·蔡邕《短人赋》"}], "words": [{"w": "啧言", "t": "责备的议论"}, {"w": "啧室", "t": "多人集议之处。"}]}, {"meaning": "事物的幽深、细微处。", "cites": [{"t": "故愚者之言,芴然而粗,啧然而不", "b": "《荀子·正名》"}]}, {"meaning": "鸟声。多叠用。", "cites": [{"t": "啧啧野田雀,不知躯体微。", "b": "唐·储光羲《野田黄雀行》"}]}, {"meaning": "表示赞叹。", "cites": [{"t": "那女子毫无羞怒之色,倒把王庆赞道:“啧,啧,好拳腿!”", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4812wx','晡','1','bū','日','11','','[{"pinyin": "bū", "defs": [{"meaning": "(形声。从日,甫声。本义:申时(等于现在下午三时至五时))。"}, {"meaning": "申时,即午后三时至五时。", "cites": [{"t": "脯时,门坏。元济于城上请罪,进城梯而下之。", "b": "《资治通鉴·唐纪》"}, {"t": "贺发,晡时至定陶。", "b": "汉·班固《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4813wx','晤','1','wù','日','11','','[{"pinyin": "wù", "defs": [{"meaning": "(形声。从日,吾声。“日”表日光。本义:聪明,明白) 同本义。", "cites": [{"t": "晤,明也。", "b": "《说文》。段玉裁注:“晤者,启之明也。”"}, {"t": "真宗英晤之主。", "b": "《宋史·真宗纪赞》"}, {"t": "少秀晤,能治《尚书》、《左氏春秋》。", "b": "《新唐书》"}]}, {"meaning": "觉悟,受启发而明白。", "cites": [{"t": "病深理方晤,悔至心自烧。", "b": "孟郊《寿安西渡奉别郑相公》"}, {"t": "侍中以才晤之奇,飞芳晋牒。", "b": "唐·李俨《道因法师碑》"}, {"t": "即晤三空。", "b": ""}]}, {"meaning": "与…相遇;见面。", "cites": [{"t": "彼美淑晤。", "b": "《诗·陈风·东门之池》"}, {"t": "卿卿如晤。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "晤君", "t": "面见君主;看见君王"}, {"w": "晤教", "t": "当面聆听教诲的谦辞"}, {"w": "晤会", "t": "晤对。会面"}, {"w": "晤叙", "t": "见面叙谈"}, {"w": "晤言", "t": "见面谈话;当面谈话"}, {"w": "晤别", "t": "见面告别。"}]}, {"meaning": "对,面对。", "cites": [{"t": "可以晤歌。", "b": "《诗·陈风·东门之池》。传:“晤,遇也。”笺:“晤,犹对也。”"}], "words": [{"w": "晤歌", "t": "相对而歌。"}]}, {"meaning": "温暖之意。", "cites": [{"t": "你不穿,且待老猪穿一穿,试试新,晤晤脊背。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4814wx','眺','1','tiào','目','11','','[{"pinyin": "tiào", "defs": [{"meaning": "(形声。从目,兆声。本义:斜视)。"}, {"meaning": "同本义。", "cites": [{"t": "眺,目不正也。", "b": "《说文》"}, {"t": "袤眺旁剔。", "b": "晋·潘岳《射雉赋》"}, {"t": "流目眺夫衡阿兮。", "b": "张衡《思玄赋》"}]}, {"meaning": "往远处看。", "cites": [{"t": "高望而远眺。", "b": "《孔子家语·辨乐》"}, {"t": "眺莲花诸峰。", "b": "《徐霞客游记·游黄山记》"}, {"t": "再眺山下。", "b": ""}, {"t": "倾耳聆波澜,举目眺岖嵌。", "b": "谢灵运《登池上楼》"}], "words": [{"w": "眺注", "t": "犹言凝神远望"}, {"w": "眺瞻", "t": "远望"}, {"w": "眺瞩", "t": "登高远望。"}]}, {"meaning": "跳。", "cites": [{"t": "老生这两日耳热眼眺,好不放心也啊!", "b": "明·朱有炖《清河县继母大贤》"}]}, {"meaning": "眼睛。", "cites": [{"t": "这须发倒翻,双眺凶睅。", "b": "清·佚名《亡国恨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4815wx','眵','1','chī','目','11','','[{"pinyin": "chī", "defs": [{"meaning": "眼汁,俗称眼屎 。眼部分泌物。", "cites": [{"t": "两目眵昏。", "b": "韩愈文"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4816wx','眸','1','móu','目','11','','[{"pinyin": "móu", "defs": [{"meaning": "(形声。从目,牟声。本义:瞳人,眼珠)。"}, {"meaning": "同本义。", "cites": [{"t": "眸,目童子也。", "b": "《说文新附》"}, {"t": "胸中正,则眸子瞭焉。", "b": "《孟子·离娄上》"}, {"t": "清之为明,杯水见眸子。", "b": "《淮南子·说山》"}, {"t": "回眸一笑百媚生。", "b": "白居易《长恨歌》"}], "words": [{"w": "眸子", "t": "瞳人。泛指眼睛"}, {"w": "眸瞯", "t": "瞳人和眼白。"}]}, {"meaning": "低目谨视。", "cites": [{"t": "非目益明也,眸而见之也。", "b": "《荀子·大略》"}], "words": [{"w": "眸瞩", "t": "定睛注视。"}]}]}]','jingmo-wenyan');
