INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4818wx','喏','1','nuò rě','口','11','','[{"pinyin": "nuò", "defs": [{"meaning": "[方言] 使人注意自己所指事物"}]}, {"pinyin": "rě", "defs": [{"meaning": "唱喏。古代作揖致敬时口中同时发出的声音。", "cites": [{"t": "先君言,旧制,朝参,拜舞而已。政和以后,增以喏。然绍兴中,予造朝,已不复喏矣。", "b": "宋·陆游《老学庵笔记》"}]}]}]','jingmo-wenyan');
