INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4821wx','勖','1','xù','力','11','','[{"pinyin": "xù", "defs": [{"meaning": "勉力;勉励。", "cites": [{"t": "勖,勉也。从力,冒声。", "b": "《说文》"}, {"t": "夫子勖哉。", "b": "《书·牧誓》"}, {"t": "以勖寡人。", "b": "《诗·邶风·燕燕》。传:“勖,勉也。”"}, {"t": "勖帅以敬先妣之嗣。", "b": "《仪礼·士昏礼》"}, {"t": "亦勖而已。", "b": "《法言·孝至》"}, {"t": "奋忠毅之操,躬史鱼之节,董臣严纲,勖臣懦弱。", "b": "《后汉书》"}, {"t": "讲制艺乡绅勖后进。", "b": "《官场现形记》"}, {"t": "以国人之读兹编者勖。", "b": "孙文《黄花冈七十二烈士事略·序》"}], "words": [{"w": "勖助", "t": "勖勉,帮助"}, {"w": "勖率", "t": "勉力遵循"}, {"w": "勖厉,勖励", "t": "勉励。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4822wx','晞','1','xī','日','11','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从日,希声。本义:晒干)。"}, {"meaning": "同本义。", "cites": [{"t": "晞,日干也。", "b": "《说文》"}, {"t": "匪阳不晞。", "b": "《诗·小雅·湛露》"}, {"t": "发晞用象栉。", "b": "《礼记·玉藻》"}, {"t": "晞尔发兮阳之阿。", "b": "《楚辞·少司令》"}, {"t": "白露未晞。", "b": "《诗·秦风·蒹葭》"}, {"t": "青青园中葵,朝露待日晞。", "b": "《乐府诗集·长歌行》"}, {"t": "琼蚌晞曜以莹珠。", "b": "郭璞《江赋》"}], "words": [{"w": "晞发", "t": "把洗净的头发晒干"}, {"w": "晞解", "t": "因日晒而消除"}, {"w": "晞灭", "t": "受日照而消失"}, {"w": "晞露", "t": "日晒使露水蒸发"}, {"w": "晞土", "t": "干土"}, {"w": "晞块", "t": "干土。"}]}, {"meaning": "晓,天刚明。", "cites": [{"t": "东方未晞。", "b": "《诗·齐风·东方未明》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4823wx','唵','1','ǎn','口','11','','[{"pinyin": "ǎn", "defs": [{"meaning": "[方言] 把手里握着的粒状或粉末状的东西塞进嘴里"}, {"meaning": "——佛教咒语的发声字 。为婀、乌、莽三字合成", "words": [{"w": "唵字咒语", "t": "佛教语。“唵”字包括有所谓摄伏的作用,据说行此法时,可使一切诸天龙神听从指挥"}]}]}]','jingmo-wenyan');
