INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4825wx','冕','1','miǎn','冂','11','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从月(mào),免声。“月是蛮夷及小儿的头衣”,“免”是“冕”的本字。本义:古代帝王、诸侯及卿大夫所戴的礼帽)。"}, {"meaning": "同本义。", "cites": [{"t": "冕,大夫以上冠也。", "b": "《说文》"}, {"t": "故天子袾裷衣冕,诸侯玄裷衣冕。", "b": "《荀子·富国》"}, {"t": "虽有轩冕之赏弗能劝。", "b": "《庄子·胠箧》"}, {"t": "古之王者,冕而前旒。", "b": "《淮南子·主术训》"}, {"t": "服冕乘轩。", "b": "《左传·哀公十五年》"}], "words": [{"w": "冠冕", "t": "古代帝王、官员戴的帽子"}, {"w": "冕弁", "t": "冕和弁。均为古代帝王、诸侯、卿、大夫所戴的礼帽"}, {"w": "冕版", "t": "冕顶之板"}, {"w": "冕服", "t": "古代大夫以上的礼冠与服饰"}, {"w": "冕冠", "t": "古代帝王、诸侯及卿大夫之礼帽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4826wx','啭','1','zhuàn','口','11','','[{"pinyin": "zhuàn", "defs": [{"meaning": "转折发声。", "cites": [{"t": "初仅 ho—ho 地略作尝试,试啭一二遍后始见调匀。", "b": "郭沫苦《归去来·鸡之归去来》"}]}, {"meaning": "鸟鸣。", "cites": [{"t": "雁儿高啭,唤来彩云游天际。", "b": "郭小川《春暖花开》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4827wx','畦','1','qí','田','11','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从田,圭声。本义:田畦。一说五十亩为畦)。"}, {"meaning": "同本义。", "cites": [{"t": "畦,田五十亩曰畦。", "b": "《说文》"}, {"t": "病于夏畦。", "b": "《孟子》。刘注;“今俗以二十五亩为小畦,五十亩为大畦。”"}, {"t": "[子贡]见一丈人方将为圃畦。", "b": "《庄子》"}, {"t": "一畦之间。", "b": "宋·沈括《梦溪笔谈》"}]}, {"meaning": "亦用作田地的量词。", "cites": [{"t": "千畦姜韭。", "b": "《史记·货殖列传》"}, {"t": "一两畦菜地。", "b": "茅盾《送考》"}]}, {"meaning": "分畦种植。", "cites": [{"t": "畦留夷与揭车兮,杂杜衡与芳芷。", "b": "《楚辞》"}, {"t": "堂下可以畦,呼童对经始。", "b": "唐·杜甫《种莴苣》诗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4828wx','趺','1','fū','足','11','','[{"pinyin": "fū", "defs": [{"meaning": "脚背。", "cites": [{"t": "摩趺,攘臂以游其间。", "b": "欧阳修《送方希则序》"}], "words": [{"w": "趺踝", "t": "脚背和踝骨。指趺坐。"}]}, {"meaning": ""}, {"meaning": "脚。", "cites": [{"t": "昧爽窗前,双趺独立。", "b": "《刻兵略纂闻述》"}], "words": [{"w": "趺迹", "t": "脚。"}]}, {"meaning": "山脚。", "cites": [{"t": "桥在山趺之次,故流颇急。", "b": "清·平云《孤儿记》"}]}, {"meaning": "足迹。", "cites": [{"t": "在南安十四年,每执书就明,倚立庭砖,岁久双趺隐然。", "b": "《宋史》"}]}, {"meaning": "碑下的石座。", "cites": [{"t": "趺上不得过四尺。", "b": "封演《封氏闻见记·碑碣》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4829wx','啮','1','niè','口','11','','[{"pinyin": "niè", "defs": [{"meaning": "(会意。从口,从齿。表示咬。本字从齿,(qì)声。本义:用嘴咬)。"}, {"meaning": "同本义。", "cites": [{"t": "囓,噬也。", "b": "《说文》。字亦作啮。鸟曰啄,兽曰囓。"}, {"t": "武卧啮雪。", "b": "《汉书·李广苏建传》"}, {"t": "众蛇竞来,啮索且断。", "b": "《后汉书·费长房传》"}, {"t": "勚感涕,因啮指流血。", "b": "《新唐书·李勚传》"}, {"t": "以啮人,无御之者。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "啮指", "t": "咬指头。形容极为痛心"}, {"w": "啮咬", "t": "啃咬。比喻折磨"}, {"w": "啮啃", "t": "啃咬"}, {"w": "啮齿", "t": "咬牙切齿"}, {"w": "啮噬", "t": "咬嚼"}, {"w": "啮心", "t": "比喻痛苦至极"}, {"w": "啮雪吞毡", "t": "比喻为坚持气节而过艰苦的生活"}, {"w": "啮臂", "t": "咬臂出血;以示诚信和坚决。"}]}, {"meaning": "侵蚀。", "cites": [{"t": "水皆啮石出。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "汉水啮古根。", "b": "李白《金陵白下亭留别》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4830wx','跄','1','qiāng qiàng','足','11','','[{"pinyin": "qiāng", "defs": [{"meaning": "(形声。从足,仓声。本义:行走有节奏的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "跄,动也。", "b": "《说文》"}, {"t": "巧趋跄兮,射则臧兮。", "b": "《诗·齐风·猗嗟》"}, {"t": "跄捍凌越。", "b": "傅毅《舞赋》。注:“马走疾之貌。”"}]}, {"meaning": "跄跄。", "cites": [{"t": "跄跄,动也。", "b": "《尔雅》"}, {"t": "济济跄跄。", "b": "《诗·小雅·楚茨》"}, {"t": "跄跄济济。", "b": "《诗·大雅·公刘》。笺:“士大夫之威仪也。”"}, {"t": "朝庭之美,济济跄跄。", "b": "《荀子·大略》。注:“有行列貌。”"}, {"t": "鸟兽跄跄。", "b": "《虞书》"}, {"t": "笙镛以间,鸟兽跄跄。", "b": "《书·益稷》"}, {"t": "凤鸟跄跄,匪尧之庭。", "b": "《法言·问明》"}, {"t": "天子穆穆,诸侯皇皇,大夫济济,士跄跄。", "b": "《礼记·曲礼》"}]}]}, {"pinyin": "qiàng", "defs": [{"meaning": "走。也作“蹡”。", "cites": [{"t": "蹡,走也。或从仓。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4831wx','蚶','1','hān','虫','11','','[{"pinyin": "hān", "defs": [{"meaning": "动物名。俗叫瓦垄子或瓦楞子,又叫魁蛤 ,蚶属的软体动物,介壳厚,稍呈心脏形,自壳顶出隆起的放射纵线四十多条,像瓦垄。生活在浅海泥沙中,肉味鲜美。通称“蚶子”。", "cites": [{"t": "[何胤]疑食蚶蛎。", "b": "《南齐书·周颗传》"}], "words": [{"w": "蚶菜", "t": "赤贝的一种"}, {"w": "蚶酱", "t": "蚶肉制成的酱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4832wx','蛄','1','gū gǔ','虫','11','','[{"pinyin": "gū", "defs": [{"meaning": "蝼蛄。", "cites": [{"t": "蛄,蝼蛄也。", "b": "《说文·虫部》"}, {"t": "嘹嘹湿蛄声,咽源惊溅起。", "b": "唐·李贺《昌谷诗》"}]}]}, {"pinyin": "gǔ", "defs": [{"meaning": "——见“蝲蛄”(làgǔ)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4833wx','蛎','1','lì','虫','11','','[{"pinyin": "lì", "defs": [{"meaning": "蛎鹬。鸟名 。喙和足红色,头、颈、上胸和上背羽毛黑色,下背至尾基以及下体皆白色,尾羽其余部分黑色。常活动于海滨沙滩上,觅食软体动物、甲壳类和蠕虫等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4834wx','蛆','1','jū qū','虫','11','','[{"pinyin": "jū", "defs": [{"meaning": "——“蝍蛆”(jiéjū):蟋蟀或蜈蚣的别称。"}]}, {"pinyin": "qū", "defs": [{"meaning": "", "words": [{"w": "蛆心狡肚", "t": "坏心肠"}, {"w": "蛆心", "t": "坏心肠"}, {"w": "蛆蝇", "t": "蛆虫和苍蝇"}, {"w": "蛆扒", "t": "搅粪蛆的无齿耙。比喻无端惹事、挑拨是非之人"}, {"w": "蛆皮", "t": "谓渺小无用的东西。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4835wx','蚰','1','yóu','虫','11','','[{"pinyin": "yóu", "defs": [{"meaning": "节肢动物，像蜈蚣而略小，黄褐色，触角和脚很长，毒颚很大，栖息房屋内外阴湿处。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4836wx','蛊','1','gǔ','虫','11','','[{"pinyin": "gǔ", "defs": [{"meaning": "(会意。从虫,从皿。本义: 人肚子里的寄生虫)。"}, {"meaning": "同 本 义。", "cites": [{"t": "蛊,腹中虫也。", "b": "《说文》"}, {"t": "掌除毒蛊。", "b": "《周礼·秋官·庶氏》"}], "words": [{"w": "蛊慝", "t": "蛊虫引起的祸害"}, {"w": "蛊证", "t": "腹内生虫的病"}, {"w": "蛊毒", "t": "蛊虫之毒。"}]}, {"meaning": "传说中一种人工培育的毒虫。", "cites": [{"t": "江南数郡有畜蛊者,主人行之以杀人,行食饮中,人不觉也。", "b": "《舆地志》"}], "words": [{"w": "蛊蛊", "t": "传说人工培育的蛊虫"}, {"w": "蛊主", "t": "传说饲养蛊虫的人。"}]}, {"meaning": "谷类中蛀虫所化的蛾。", "cites": [{"t": "谷之飞,亦为蛊。", "b": "《左传·昭公六年》"}], "words": [{"w": "蛊蛊", "t": "粮食中蛀虫所化的蛾。"}]}, {"meaning": "指淫邪之事。", "cites": [{"t": "关其门户,用止狂蛊。", "b": "《太玄经》"}]}, {"meaning": "(gù)。故事,旧事,旧业。", "cites": [{"t": "乃命五史以书五帝之蛊事。", "b": "《尚书大传》"}]}, {"meaning": "诱惑;迷乱。", "cites": [{"t": "楚令尹子元欲蛊文夫人。", "b": "《左传·庄公二十八年》"}, {"t": "孔某(指孔丘)盛容脩饰以蛊世。", "b": "《墨子·非儒下》"}, {"t": "糜费产业,蛊惑士女。", "b": "南朝梁·刘勰《灭惑论》"}], "words": [{"w": "蛊丧", "t": "惑乱丧失"}, {"w": "蛊溺", "t": "惑乱沉迷"}, {"w": "蛊伪", "t": "蛊惑诈伪"}, {"w": "蛊诱", "t": "迷惑引诱。"}]}, {"meaning": "用符咒之术毒害人。", "cites": [{"t": "因诬言欲作蛊道祝诅,以菟为厌胜之术。", "b": "《后汉书·清何王庆传》"}], "words": [{"w": "蛊毒", "t": "毒害。用毒药害人,使人不自知"}, {"w": "蛊道", "t": "指巫蛊咒诅之术。"}]}, {"meaning": "疾病久治难愈。", "cites": [{"t": "晋胥克有蛊疾,郤缺为政。", "b": "《左传·宣公八年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4837wx','圉','1','yǔ','囗','11','','[{"pinyin": "yǔ", "defs": [{"meaning": "同本义。", "cites": [{"t": "圉,囹圉,所以拘罪人也。", "b": "《说文》"}, {"t": "圉,禁也。", "b": "《尔雅》"}, {"t": "不圉我哉!", "b": "《周书·宝典》。注:“圉,禁也。”"}, {"t": "终莫之圉。", "b": "《太玄·卷三疆》。注:“圉,止也。”"}, {"t": "守圉之国,用盐独甚。", "b": "《管子·轻重甲》"}, {"t": "其来不可圉。", "b": "《庄子》"}]}, {"meaning": "养马。", "cites": [{"t": "不有行者,谁扞牧圉?", "b": "《左传》"}]}, {"meaning": "(yù)。抵挡,防御。", "cites": [{"t": "然不能以此圉鬼神之诛。", "b": "《墨子·明鬼下》"}, {"t": "其来不可圉。", "b": "《庄子·缮性》"}, {"t": "瘖者可使守圉。", "b": "《淮南子·主术》"}]}, {"meaning": "监狱。", "cites": [{"t": "小圉不下十数。", "b": "银雀山汉墓竹简《尉缭子》"}], "words": [{"w": "圉空", "t": "圄空,牢空着。"}]}, {"meaning": "养马的地方。"}, {"meaning": "养马的人。", "cites": [{"t": "马有圉,牛有牧。", "b": "《左传·昭公七年》"}], "words": [{"w": "圉人", "t": "《周礼》官名。掌管养马放牧等事;泛称养马的人"}, {"w": "圉牧", "t": "饲养牛马的人。"}]}, {"meaning": "边境。", "cites": [{"t": "孔棘我圉。", "b": "《诗·大雅·桑柔》"}, {"t": "亦聊以固吾圉也。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4838wx','蚱','1','zhà','虫','11','','[{"pinyin": "zhà", "defs": [{"meaning": "昆虫，身体绿色或褐色，触角短，不能远飞，对农作物有害。", "cites": [{"t": "蚱蜢，草上虫也。--《六书正伪》", "b": ""}]}, {"meaning": "又如：蚱虫(即蚱蜢)；蚱蜢竹(竹的一种)。"}]}]','jingmo-wenyan');
