INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4840wx','蛏','1','chēng','虫','11','','[{"pinyin": "chēng", "defs": [{"meaning": "蛏子 。双壳纲竹蛏科(Solenidae)海产贝类。软体动物。介壳两扇,形状狭而长,外面蛋黄色,里面白色,生活在近岸的海水里,也可人工养殖,肉味鲜美。有缢蛏、竹蛏等种类。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4841wx','蚴','1','yòu','虫','11','','[{"pinyin": "yòu", "defs": [{"meaning": "某些寄生蠕虫的幼虫,如“胞蚴”、“毛蚴”", "words": [{"w": "蚴虬", "t": "龙形蜿曲的样子"}, {"w": "蚴蜕", "t": "蜂的一种"}, {"w": "蚴", "t": "龙爬行的样子。屈曲行动的样子。同“蚴虬”"}]}]}]','jingmo-wenyan');
