INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4845wx','啐','1','cuì qi','口','11','','[{"pinyin": "cuì", "defs": [{"meaning": "惊愕时所发出的声音。", "cites": [{"t": "啐,惊也。从口,卒声。", "b": "《说文》。按,惊声也"}], "words": [{"w": "啐啄", "t": "雏鸡欲出时以嘴吮卵壳声为啐,母鸡欲使小鸡出壳而吃壳为啄。"}]}, {"meaning": "饮;尝。", "cites": [{"t": "啐,尝也。", "b": "《广雅》"}, {"t": "席末坐,啐酒。", "b": "《仪礼·乡射礼》"}, {"t": "主人皆啐之。", "b": "《礼记·杂记》"}], "words": [{"w": "啐酒", "t": "啐饮。啐醴。古代酒礼。祭毕饮福酒"}, {"w": "啐尝", "t": "品尝。"}]}]}, {"pinyin": "qi", "defs": [{"meaning": "表示唾弃 、斥丽或辱骂。", "cites": [{"t": "啐!这算得什么?", "b": ""}, {"t": "李逵道:啐,原来是梦,却也快当!", "b": "《水浒全传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4846wx','唼','1','shà','口','11','','[{"pinyin": "shà", "defs": [{"meaning": "水鸟或鱼吃食。", "cites": [{"t": "凫雁皆唼夫粱藻兮。", "b": "《楚辞·九辩》"}], "words": [{"w": "唼唼", "t": "水鸟或鱼的吃食声。"}]}, {"meaning": "泛指吃,咬。", "cites": [{"t": "唼,咬也。", "b": "《玉篇》"}], "words": [{"w": "唼啑", "t": "鱼或水鸟进食"}, {"w": "唼食", "t": "咬;吞食"}, {"w": "唼啮", "t": "啃咬"}, {"w": "唼嗍", "t": "吃食。"}]}, {"meaning": "饮牲血。", "cites": [{"t": "与高帝唼血而盟。", "b": "《汉书·王陵传》"}]}]}]','jingmo-wenyan');
