INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4848wx','啖','1','dàn','口','11','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从口,炎声。本义:吃,咬着吃硬的或囫囵吞整的食物)。"}, {"meaning": "同本义。", "cites": [{"t": "啖,噍啖也。", "b": "《说文》"}, {"t": "啖,食也。", "b": "《广雅》"}, {"t": "啖啖常欲人之有。", "b": "《荀子·王霸》。注:“并吞之貌。”"}, {"t": "啖函启化。", "b": "《太玄·玄莹》。注:“含也。”"}, {"t": "樊哙覆其盾于地,加彘肩上,拔剑切而啖之。", "b": "《史记·项羽本纪》"}, {"t": "日啖荔枝三百颗,不辞长作岭南人。", "b": "宋·苏轼《食荔枝二首》"}, {"t": "茹啖其草木之荑实。", "b": "明·刘基《苦斋记》"}], "words": [{"w": "啖蔗", "t": "吃甘蔗,愈吃愈甜。比喻渐入佳境"}, {"w": "啖啖", "t": "贪吃的样子"}, {"w": "啖指咬舌", "t": "恐惧不敢多言的样子。"}]}, {"meaning": "给吃。", "cites": [{"t": "吉妇取枣以啖吉。", "b": "《汉书·王吉传》"}, {"t": "先生…又何吝一躯啖我而全微命乎?", "b": "明·马中锡《中山狼传》"}, {"t": "将炙啖朱亥。", "b": "唐·李白《侠客行》"}], "words": [{"w": "啖养", "t": "饲养"}, {"w": "啖虎", "t": "餵虎。"}]}, {"meaning": "用饵或好象用饵勾引;引诱。", "cites": [{"t": "啖以利,因袭攻武关,破之。", "b": "《史记·高祖本纪》"}], "words": [{"w": "啖围", "t": "紧紧包围;引诱并包围"}, {"w": "啖以重利", "t": ""}]}]}]','jingmo-wenyan');
