INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4854wx','啜','1','chuò chuài','口','11','','[{"pinyin": "chuò", "defs": [{"meaning": "(形声。本义:尝、喝)。"}, {"meaning": "同本义。", "cites": [{"t": "啜,尝也。", "b": "《说文》"}, {"t": "君子啜其羹。", "b": "《荀子·非相》"}, {"t": "君子啜菽饮水,非愚也。", "b": "《荀子·天论》"}, {"t": "搏之不解,一啜而散。", "b": "枚乘《七发》"}, {"t": "饮于土塯,啜于土形。", "b": "《墨子·节用中》"}, {"t": "子饭一盂,子啜一觞。", "b": "唐·韩愈《送穷文》"}, {"t": "众人皆醉,何不餔其糟而啜其醨?", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "啜茗", "t": "品茶"}, {"w": "啜饮", "t": "饮;喝"}, {"w": "啜哺", "t": "饮食;吃喝"}, {"w": "啜息", "t": "饮食休息"}, {"w": "啜食", "t": "犹言吃喝"}, {"w": "啜汁", "t": "喝汤。比喻乘机邀功或沾光吃闲饭"}, {"w": "啜人贼", "t": "犹害人精。啜人,谓吸人精血"}, {"w": "啜吒", "t": "形容吞咽之声"}, {"w": "啜英咀华", "t": "比喻品赏、体味诗文的精华。"}]}]}, {"pinyin": "chuài", "defs": [{"meaning": "复姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4855wx','帻','1','zé','巾','11','','[{"pinyin": "zé", "defs": [{"meaning": "(形声。从巾,责声。本义:头巾)。"}, {"meaning": "同本义(包裹着头,中间露出头发,帻前高后低,然后加冠)。", "cites": [{"t": "元帝额有壮发,不欲使人见,始进帻服之。", "b": "蔡邕《独断》"}, {"t": "文武官皆免冠著帻。", "b": "《晋书·舆服志》"}], "words": [{"w": "丧帻;帻梁", "t": "古代包头的头巾。"}]}, {"meaning": "犹冠。类似帽子的东西。", "cites": [{"t": "乃有秋花实,全如鸡帻丹。", "b": "宋·梅尧臣《鸡冠》"}], "words": [{"w": "帻巾", "t": "头巾。"}]}]}]','jingmo-wenyan');
