INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4862wx','赇','1','qiú','贝','11','','[{"pinyin": "qiú", "defs": [{"meaning": "行贿。", "cites": [{"t": "赇,以财物枉法相谢也。从贝,求声。", "b": "《说文》"}, {"t": "尊私行以贰主威,行赇纳以疑法。", "b": "《韩非子·八法》"}], "words": [{"w": "赇纹", "t": "纳贿"}, {"w": "赇赂", "t": "贿赂"}, {"w": "赇吏", "t": "贿赂官吏"}, {"w": "赇託", "t": "贿赂请托"}, {"w": "赇纳", "t": "赇贿;贿赂。"}]}, {"meaning": "受贿。", "cites": [{"t": "官暗而吏赇,故冤不得直也。", "b": "《齐东野语》"}, {"t": "墨吏以赇亡,战士以勇殒。", "b": "《杂说》"}]}, {"meaning": "贿赂,用来买通别人的财物。", "cites": [{"t": "吏坐受赇枉法。", "b": "《汉书·刑法志》"}, {"t": "诬守纳己赇。", "b": "明·高启《书博鸡者事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4863wx','赈','1','zhèn','贝','11','','[{"pinyin": "zhèn", "defs": [{"meaning": "(形声。从贝,辰声。本义:救济) 同本义 。本作“振”。", "cites": [{"t": "战士以奉,饥民以赈。", "b": "《盐铁论》"}, {"t": "悉府库以赈之。", "b": "清·洪亮吉《治平篇》。"}], "words": [{"w": "赈给", "t": "救济;赈济"}, {"w": "赈田", "t": "专为赈济饥荒之用的田地"}, {"w": "赈贷", "t": "救助、救济"}, {"w": "赈荒", "t": "赈济遭荒灾民"}, {"w": "赈物", "t": "赈济的物品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4864wx','赊','1','shē','贝','11','','[{"pinyin": "shē", "defs": [{"meaning": "(形声。从贝,佘(shē)声。本义:赊欠)。"}, {"meaning": "同本义。"}, {"meaning": "买货延期交款。", "cites": [{"t": "赊,贳买也。", "b": "《说文》"}]}, {"meaning": "段注:“贳买者,在彼为贳,在我则为赊也。”。", "cites": [{"t": "赊,不交钱而贾曰赊。", "b": "《字汇》"}, {"t": "凡赊者祭祀无过旬日。", "b": "《周礼·泉府》"}, {"t": "他游到夜间,赊了两碗酒,喝下肚去。", "b": "《阿Q正传》"}], "words": [{"w": "赊贷", "t": "出借财物给人,准予借者缓期偿还"}, {"w": "赊头", "t": "欠帐的期限"}, {"w": "赊钱", "t": "所欠的贷款"}, {"w": "赊券", "t": "欠帐的字据。"}]}, {"meaning": "卖物延期收款。", "cites": [{"t": "少年来酤者,皆赊与之。", "b": "《后汉书·刘盆子传》"}], "words": [{"w": "赊卖", "t": "买卖货物时,卖方延期收款"}, {"w": "赊得不如现得", "t": "比喻眼前的好处最实惠。"}]}, {"meaning": "借。", "cites": [{"t": "且就洞庭赊月色,将船买酒白云边。", "b": "李白《陪族叔刑部侍郎晔及中书贾舍人至游洞庭》"}]}, {"meaning": "宽恕,饶恕。", "cites": [{"t": "金鸡忽放赦,大辟得宽赊。", "b": "李白《秦女休行》"}]}, {"meaning": "遥远。", "cites": [{"t": "北海虽赊,扶摇可接。", "b": "王勃《滕王阁序》"}, {"t": "坐到三更尽,归仍万里赊。", "b": "唐·戎昱《桂州腊夜》"}], "words": [{"w": "赊僻", "t": "偏远"}, {"w": "赊远", "t": "赊遥。久远;遥远"}, {"w": "赊促", "t": "远近;缓急。"}]}, {"meaning": "长;久。", "cites": [{"t": "古木卧平沙,摧残岁月赊。", "b": "王泠然《古木卧平沙》"}], "words": [{"w": "赊愿", "t": "宿愿。"}]}, {"meaning": "多,繁多。", "cites": [{"t": "胡马迎风起恨赊。", "b": "朗士元《闻吹扬叶者》"}], "words": [{"w": "赊望", "t": "过高的愿望。"}]}, {"meaning": "迟缓。", "cites": [{"t": "节候看应晚,心期卧亦赊。", "b": "唐·韩翃《酬程延秋夜即事见赠》"}], "words": [{"w": "赊迟", "t": "延缓;拖延"}, {"w": "赊缓", "t": "迟缓;缓慢。"}]}, {"meaning": "渺茫。", "cites": [{"t": "物土南州异,关河北信赊。", "b": "唐·张说《岳州作》"}]}, {"meaning": "极端。", "cites": [{"t": "自怯春寒苦,那堪禁火赊。", "b": "唐·李商隐《寒食行次冷泉驿》"}]}, {"meaning": "为数很少的。", "cites": [{"t": "商颜暮雪逢人少,邓鄙春泥见驿赊。", "b": "韩愈《次邓州界》"}]}, {"meaning": "奢侈。", "cites": [{"t": "楚楚衣服,戒在穷赊。", "b": "《后汉书·仲长统传》"}], "words": [{"w": "穷赊", "t": "极端奢侈。"}]}, {"meaning": "宽松;松缓。", "cites": [{"t": "带赊衣改制。", "b": "刘禹锡《武陵书怀》"}]}, {"meaning": "稀少。", "cites": [{"t": "惟愁面会赊。", "b": "钱起《送费秀才归衡州》"}]}, {"meaning": "作语助。同“啊”。", "cites": [{"t": "昨日紫姑神去也,今朝青鸟使来赊。", "b": "李商隐《昨日》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4865wx','铑','1','lǎo','钅','11','','[{"pinyin": "lǎo", "defs": [{"meaning": "一种银白色的坚硬而有延性的金属元素,原子序数45,为一种铂族金属,主要呈三价,常温时耐酸和耐其它腐蚀剂的侵蚀 ——元素符号Rh。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4866wx','铒','1','ěr èr','钅','11','','[{"pinyin": "ěr", "defs": [{"meaning": "稀土族中的一种三价金属元素,原子序数68,原子量167.26,比重9.051,不溶于水,溶于酸,于1400—1500°C熔融,质软,它和钇一起共存 ——元素符号Er。"}]}, {"pinyin": "èr", "defs": [{"meaning": "钩。", "cites": [{"t": "铒,钩也。", "b": "《玉篇》"}]}, {"meaning": "钩形饰物。", "cites": [{"t": "蜀王慕公,使使致扇铒微饷,不受。", "b": "李贽《续藏书》"}]}]}]','jingmo-wenyan');
