('4867wx','铗','1','jiá','钅','11','','[{"pinyin": "jiá", "defs": [{"meaning": "(形声。从金,夹声。本义:铁钳)。"}, {"meaning": "剑。", "cites": [{"t": "带长铗之陆离兮。", "b": "《楚辞·涉江》"}]}, {"meaning": "剑柄。", "cites": [{"t": "长铗归来乎!", "b": "《战国策·齐策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4868wx','铙','1','náo','钅','11','','[{"pinyin": "náo", "defs": [{"meaning": "乐器名。", "cites": [{"t": "铙,小钲也。军法。卒长执铙。从金,尧声。", "b": "《说文》"}, {"t": "铙,铃也。", "b": "《广雅》"}, {"t": "以金铙止鼓。", "b": "《周礼·鼓人》。注:如铃无舌、有秉,执而鸣之,以止击鼓。”"}, {"t": "辨鼓铎镯铙之用。", "b": "《周礼·大司马》。司农注:“读如讙哓之哓。”"}]}, {"meaning": "铜制圆形的乐器,常和钹配合演奏。如;铙歌(军中乐歌;泛指军歌);铙挽(铙歌和挽歌)。"}, {"meaning": "扰乱。", "cites": [{"t": "万物无足以铙心者,故静也。", "b": "《庄子·天道》"}]}, {"meaning": "喧嚣。", "cites": [{"t": "今年尚可后年铙。", "b": "《后汉书·五行志一》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4869wx','铟','1','yīn','钅','11','','[{"pinyin": "yīn", "defs": [{"meaning": "一种软的有延展性的易熔银白色金属元素,原子序数49,不易失去光泽,与铝和镓类似,主要是三价,在闪锌矿和其他矿石中有很小量存在,主要作飞机用的涂敷铅的银轴承的镀层 ——元素符号In。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4870wx','铠','1','kǎi','钅','11','','[{"pinyin": "kǎi", "defs": [{"meaning": "(形声。从金,豈声。本义:用以护身的铠甲战衣)同本义(用金属薄片缀成)。", "cites": [{"t": "铠,甲也。", "b": "《说文》。段注:“古曰甲,汉人曰铠。”"}, {"t": "古用皮,谓之甲,今用金,谓之铠。", "b": "《周礼·考士记》疏"}, {"t": "禁民不得挟弩铠。", "b": "《汉书·王莽传》"}, {"t": "其铠胄精良。", "b": "《新唐书·吐蕃传》"}, {"t": "铠胄皆镔铁。", "b": "《阎典史传》"}], "words": [{"w": "铠马", "t": "铠甲和战马。披有铠甲的战马。也称“铁马”"}, {"w": "铠骑", "t": "穿铠甲的骑兵"}, {"w": "铠胄", "t": "铠甲和头盔"}, {"w": "铠袄", "t": "铠甲袍袄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4871wx','铡','1','zhá','钅','11','','[{"pinyin": "zhá", "defs": [{"meaning": "(形声。从金,则声。从金,表示是金属制品。本义:铡刀) 同本义 。古谓之鈇,今谓之铡。也用作刑具。", "cites": [{"t": "将铜铡来,切了你那颅头。", "b": "元·李直夫《虎头牌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4872wx','铢','1','zhū','钅','11','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从金,朱声。从“金”与货币有关。本义:古代重量单位,二十四铢为一两)。"}, {"meaning": "同本义。", "cites": [{"t": "虽分国如锱铢。", "b": "《礼记·儒行》"}]}, {"meaning": "现代泰国基本货币单位。", "cites": [{"t": "铢,权十分黍之重也。", "b": "《说文》"}]}, {"meaning": "钝,不锋利。", "cites": [{"t": "其兵戈铢而无刃。", "b": "《淮南子·齐俗》"}]}, {"meaning": "细微。", "cites": [{"t": "陛下铢分邪正,升黜分明,天下幸甚。", "b": "《辽史》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4873wx','铣','1','xiǎn xǐ','钅','11','','[{"pinyin": "xiǎn", "defs": [{"meaning": "(形声。从金,先声。本义:富有光泽的金属)。"}, {"meaning": "富有光泽的金属。", "cites": [{"t": "金之泽者。", "b": "《说文》"}, {"t": "绝泽谓之铣。", "b": "《尔雅》。注:“即美金,最有光泽也。”"}, {"t": "而玦之金铣者。", "b": "《国语·晋语》"}, {"t": "黄离踵曜,太阳分铣树之辉。", "b": "唐·王勃《乾元殿颂序》"}], "words": [{"w": "铣泽", "t": "光泽"}, {"w": "铣树", "t": "闪烁金光之树。"}]}, {"meaning": "小凿。"}, {"meaning": "古代用金装饰两端的弓。", "cites": [{"t": "一员员顶梁靠柱,持铣拥旌。", "b": "《西游记》"}], "words": [{"w": "铣珧", "t": "宝弓。"}]}]}, {"pinyin": "xǐ", "defs": [{"meaning": "用一种能旋转的圆形多刃刀具切削金属工件", "words": [{"w": "铣削", "t": ""}, {"w": "铣刀", "t": ""}]}, {"meaning": "在铣床上加工金属工件", "words": [{"w": "铣削", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4874wx','铤','1','dìng tǐng','钅','11','','[{"pinyin": "dìng", "defs": [{"meaning": "铜铁矿石。", "cites": [{"t": "铤,铜铁朴也。", "b": "《说文》"}]}, {"meaning": "铜铁质的坯料。", "cites": [{"t": "金铤,许叔重注《淮南子》云:“铤者,金银铜等未成器,铸作片,名曰铤。”", "b": "《一切经音义》"}]}, {"meaning": "熔铸成条块等固定形状的金银,其重数两至数十两不等。", "cites": [{"t": "旧例银每铤五十两,其直百贯。", "b": "《金史》"}]}, {"meaning": "锭子,纺车或纺纱机上绕纱的机件。", "cites": [{"t": "摇车转铤,而纺于竹管之上。", "b": "《天工开物》"}]}]}, {"pinyin": "tǐng", "defs": [{"meaning": "(形声。从金,廷声。本义:未经冶铸的铜铁。读dìng)。"}, {"meaning": "快跑的样子。", "words": [{"w": "铤走", "t": "快跑"}, {"w": "铤鹿", "t": "疾奔之鹿。"}]}, {"meaning": "空;尽。", "cites": [{"t": "铤,尽也。物空尽者曰铤。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4875wx','铧','1','huá','钅','11','','[{"pinyin": "huá", "defs": [{"meaning": "锹,人力翻土农具的一种", "words": [{"w": "铧锹", "t": "锹"}, {"w": "铧觜", "t": "铧状的堤坝"}]}, {"meaning": "安装在犁上用来破土的铁片", "words": [{"w": "铧犁", "t": "铧和犁的并称"}, {"w": "铧式犁", "t": "犁的一种"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4876wx','铨','1','quán','钅','11','','[{"pinyin": "quán", "defs": [{"meaning": "(形声。从金,全声。本义:称重量的器具,即秤)。"}, {"meaning": "同本义。", "cites": [{"t": "铨,衡也。", "b": "《说文》"}, {"t": "称谓之铨。", "b": "《广雅·释器》"}, {"t": "夫挈轻重不失铢两,圣人弗用,而县之乎铨衡。", "b": "《淮南子·齐俗训》"}], "words": [{"w": "铨衡", "t": ""}]}, {"meaning": "指古代史书中解说、评议一类的文字。", "cites": [{"t": "后之史家,或谓之论,或谓之序,或谓之铨,或谓之评。", "b": "宋·郑樵《通志》"}]}, {"meaning": "称量;衡量;鉴别。", "cites": [{"t": "无铨度天下之众寡。", "b": "《国语·吴语》。注:“称也。”"}, {"t": "考量以铨。", "b": "《汉书·王莽传》"}], "words": [{"w": "铨次", "t": "衡量而排定次序。也作“诠次”"}, {"w": "铨序", "t": "评论文章的品第序次"}, {"w": "铨判", "t": "审度判断"}, {"w": "铨材", "t": "衡量才能。"}]}, {"meaning": "根据资格条件选授官职。", "cites": [{"t": "而翁长铨。", "b": "明·崔铣《洹词·记王忠肃公翱三事》"}], "words": [{"w": "铨除", "t": "量才授官"}, {"w": "铨考", "t": "考量选用"}, {"w": "铨序", "t": "按照官吏的才能功绩,确定官位的等级升降"}, {"w": "铨授", "t": "量才授官"}, {"w": "铨补", "t": "考量才能以补官职。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4877wx','铩','1','shā','钅','11','','[{"pinyin": "shā", "defs": [{"meaning": "长刃矛,古代的一种兵器。", "cites": [{"t": "不敌于鉤戟长铩也。", "b": "《汉书·陈胜项藉传》。注:“铍也。”"}, {"t": "鉏耰棘矜,非铦于钩戟长铩也。", "b": "汉·贾谊《过秦论》"}]}, {"meaning": "铍有镡。", "cites": [{"t": "铩,铍有镡也。", "b": "五代·徐锴《说文系传》"}]}, {"meaning": "摧残;伤害。", "cites": [{"t": "铩羽暴鳞,复见翻跃。", "b": "鲍照《拜侍郎上疏》"}], "words": [{"w": "铩羽", "t": "毛羽伤残,不能高飞。比喻人受摧残而失志"}, {"w": "铩翼", "t": "羽毛摧败,不能高飞"}, {"w": "铩翅", "t": "折翅"}, {"w": "铩翮", "t": "即铩羽"}, {"w": "铩羽暴鳞", "t": "铩羽涸鳞。毛羽伤残,鱼池水干。比喻不得志,处境极为困难。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4878wx','铪','1','hā','钅','11','','[{"pinyin": "hā", "defs": [{"meaning": "化学元素名,化学上与锆非常相似的一种灰色高熔点四价金属元素,它存在于大多数锆矿中,由于它容易发射电子而很有用处(如用作白炽灯的灯丝) ——元素符号Hf。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4879wx','铫','1','diào yáo','钅','11','','[{"pinyin": "diào", "defs": [{"meaning": "[方言] 煎药或烧水用的器具,形状像比较高的壶,口大有盖,旁边有柄,用沙土或金属制成", "words": [{"w": "沙铫儿", "t": ""}, {"w": "药铫儿", "t": ""}]}]}, {"pinyin": "yáo", "defs": [{"meaning": "大锄。", "cites": [{"t": "耕考必有一耒、一耜、一铫。", "b": "《管子》"}], "words": [{"w": "铫耨", "t": "铫和耨。种田的用具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4880wx','铬','1','gè','钅','11','','[{"pinyin": "gè", "defs": [{"meaning": "一种蓝白色多价金属元素,原子序数24,通常制得的铬,质硬且脆,抗腐蚀,只以化合状态存在。主要以铬铁矿形式存在,用铝热法、硅热法或电解法将它从矿石中分离出,主要用于合金(如供铬钢用的铬铁合金或如镍铬电阻合金)及电镀(如汽车减震器和内部装璜以及切削工具) ——元素符号Cr。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4881wx','铮','1','zhēng zhèng','钅','11','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从金,争声。本义:金属相击声) 同本义。", "cites": [{"t": "铮,金声也。", "b": "《说文》"}, {"t": "冲牙铮鎗。", "b": "潘岳《藉田赋》。注:“玉声。”"}, {"t": "铮鏦然有京都声。", "b": "唐·白居易《琵琶行(并序)》"}, {"t": "繁华远容绮,铮鏦美金错。", "b": "王禹偁《酬种放征君一百韵》"}, {"t": "却好那一鞭打将下来,正在刀口上,铮地一声响,火光迸散。", "b": "《水浒传》"}], "words": [{"w": "铮枪", "t": "玉相撞击声"}, {"w": "铮鏦", "t": "争枞。形容金属触击声。"}]}]}, {"pinyin": "zhèng", "defs": [{"meaning": "", "words": [{"w": "玻璃擦得铮亮", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4882wx','铯','1','sè','钅','11','','[{"pinyin": "sè", "defs": [{"meaning": "碱金属族的一种银白色、质软、易展性的金属元素,是已知的最电正性元素;通常与铷和锂共存(如铯榴石中),尤以其化合物和合金形式用于电子管和光电池中 ——元素符号Cs。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4883wx','铰','1','jiǎo','钅','11','','[{"pinyin": "jiǎo", "defs": [{"meaning": "剪刀,亦称铰刀。", "cites": [{"t": "欲将鬃鬣重剪裁,乞借新成利铰刀。", "b": "曹唐《病马》"}, {"t": "铰,即今妇功缝人所用者,俗呼剪手。", "b": "《正字通》"}]}, {"meaning": "钉铰,即补钉。又为铜匠之称。", "cites": [{"t": "铰,今凡刀柄、鞍首皆有钉铰。", "b": "《正字通》"}]}, {"meaning": "金属装饰。", "cites": [{"t": "宝铰星缠,镂章霞布。", "b": "《文选·颜延之·赭白马赋》"}]}, {"meaning": "铰链。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4884wx','铱','1','yī','钅','11','','[{"pinyin": "yī", "defs": [{"meaning": "银白色硬脆很重的铂族金属元素, 主要价态是三价和四价, 通常以与铂或锇的天然合金存在于铱锇矿中, 在常温下耐多种化学侵蚀, 专用于硬化铂合金, 适用于外科仪器, 电气和其他科学仪器, 宝石和金笔尖  ——元素符号 Ir。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4885wx','铳','1','chòng','钅','11','','[{"pinyin": "chòng", "defs": [{"meaning": "斧头上受柄的孔。", "cites": [{"t": "铳,斧穿也。", "b": "《集韵》"}]}, {"meaning": "金属制的打眼器具,即铳子。"}, {"meaning": "用铳射击。", "cites": [{"t": "不许说我回来过,说了张少爷会一枪铳了你。", "b": "沈从文《大小阮》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4886wx','铵','1','ǎn','钅','11','','[{"pinyin": "ǎn", "defs": [{"meaning": "由氨衍生的一种离子NH4,也叫“铵根” 。在化合物中的地位相当于具有一价金属性质的离子", "words": [{"w": "氯化铵", "t": ""}, {"w": "硫酸铵", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4887wx','铷','1','rú','钅','11','','[{"pinyin": "rú", "defs": [{"meaning": "一个质地柔软具有银白色光泽的碱金属元素,原子序数37,以化合物状态少量地存在于许多矿物、矿泉水以及许多植物的灰中,通常伴有更少量的铯,金属铷由电解或化学还原铷的化合物制得,它剧烈地使水分解,在空气中可自燃 ——元素符号Rb。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4888wx','氪','1','kè','气','11','','[{"pinyin": "kè", "defs": [{"meaning": "一种无色惰性气体元素,它存在于空气中,以体积计,在空气中占百万分之一 ——元素符号Kr。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4889wx','牾','1','wǔ','牜','11','','[{"pinyin": "wǔ", "defs": [{"meaning": "相逢。", "cites": [{"t": "重华不可牾兮,孰知余之从容。", "b": "《史记·屈原贾生列传》"}]}, {"meaning": "背逆。", "cites": [{"t": "牾,逆也。", "b": "《说文》"}, {"t": "自郡吏以下皆畏避之,莫敢与牾。", "b": "《汉书·严延年传》"}], "words": [{"w": "抵牾", "t": "矛盾。也作牴牾"}, {"w": "牾逆", "t": "违逆,触犯。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
