INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4891wx','秾','1','nóng','禾','11','','[{"pinyin": "nóng", "defs": [{"meaning": "(形声。从禾,农声。本义:花木繁盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "秾,花木厚。", "b": "《广韵》"}, {"t": "一枝秾艳露凝香,云雨巫山枉断肠。", "b": "唐·李白《清平调》"}], "words": [{"w": "秾李", "t": "繁盛的李花"}, {"w": "秾秀", "t": "繁花"}, {"w": "秾花", "t": "盛开的花"}, {"w": "秾华", "t": "繁盛艳丽的花朵"}, {"w": "秾密", "t": "花木繁多茂密"}, {"w": "秾茂", "t": "繁盛浓密"}, {"w": "秾繁", "t": "浓密繁盛。"}]}, {"meaning": "艳丽;华丽。", "cites": [{"t": "看婿颜美玉,妇色秾桃。", "b": "明·杨珽《龙膏记·偿缘》"}], "words": [{"w": "秾秀", "t": "艳丽秀美"}, {"w": "秾纤", "t": "艳丽纤巧"}, {"w": "秾丽", "t": "艳丽"}, {"w": "秾致", "t": "浓艳致密"}, {"w": "秾秾", "t": "艳美的样子"}, {"w": "秾饰", "t": "浓妆;盛装"}, {"w": "秾桃", "t": "艳美的桃花"}, {"w": "秾李", "t": "华美的李花"}, {"w": "秾花", "t": "美艳丰腴。"}]}, {"meaning": "丰硕;丰满;肥大;肥胖。", "cites": [{"t": "秾不短,纤不长。", "b": "宋玉《神女赋》"}], "words": [{"w": "秾纤", "t": "肥瘦。"}]}, {"meaning": "浓;深。", "cites": [{"t": "知君却是为情秾,怕见此花撩动。", "b": "苏轼《瑞香花》"}], "words": [{"w": "秾芳", "t": "浓郁的芳香"}, {"w": "秾郁", "t": "浓厚;盛美。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4892wx','逶','1','wēi','辶','11','','[{"pinyin": "wēi", "defs": [{"meaning": "(形声。从辵(chuò),委声。本义:弯曲而绵延不断的样子) 同本义。", "cites": [{"t": "逶,逶迆,袤去之貌。", "b": "《说文》"}, {"t": "望旧邦兮路逶随。", "b": "《楚辞·九思·逢尤》"}]}, {"meaning": "秩如:逶随(迂曲遥远的样子);逶丽(曲折盘旋的样子)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4893wx','笺','1','jiān','竹','11','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。从竹,戋(jiān)声。本义:注释) 同本义。", "cites": [{"t": "笺,表识书也。…字亦作牋。", "b": "《说文》"}, {"t": "笺,书也。", "b": "《广雅》"}, {"t": "郑子诸经皆谓之“注”,此言笺者……记识其事,故称为“笺”。", "b": "孔颖达《毛诗正义》"}], "words": [{"w": "笺释", "t": "犹笺注"}, {"w": "笺疏", "t": "笺注"}, {"w": "笺训", "t": "笺注训释。"}]}, {"meaning": "注释的文字。", "cites": [{"t": "笺注纷罗,颠倒是非。", "b": "韩愈《施先生墓铭》"}], "words": [{"w": ";笺记", "t": "古文体名。"}]}, {"meaning": "名片;名刺。", "cites": [{"t": "亲友投笺互拜。", "b": "明·田汝成《熙朝乐事》"}]}]}]','jingmo-wenyan');
