('4896wx','笪','1','dá','竹','11','','[{"pinyin": "dá", "defs": [{"meaning": "鞭打。", "cites": [{"t": "笪,笞也。", "b": "《说文》。笪者可以挞人之物。"}], "words": [{"w": "笪笞", "t": "笞挞,鞭打。"}]}, {"meaning": "竹箬。", "cites": [{"t": "笪,箬也。", "b": "《一切经音义》引《说文》"}], "words": [{"w": "笪屋", "t": "用粗竹席铺盖的屋。"}]}, {"meaning": "拉船用的索子。", "cites": [{"t": "百丈者,牵船篾,内地谓之笪。", "b": "元·周密《齐东野语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4897wx','笮','1','zé zuó','竹','11','','[{"pinyin": "zé", "defs": [{"meaning": "屋上的箔席。用竹或苇编成,铺在瓦下椽上。", "cites": [{"t": "笮,迫也。在瓦之下,棼上。", "b": "《说文》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zuó", "defs": [{"meaning": "竹索。拉船的ň。", "cites": [{"t": "筰,筊也。从竹,作声。竹索也。", "b": "《说文》"}, {"t": "负笮引文舟,饥渴常不饱。", "b": "南朝宋·谢灵运《折杨柳行》"}], "words": [{"w": "笮桥", "t": "用竹索编织而成的架空吊桥。"}]}, {"meaning": "竹竿。", "cites": [{"t": "人未学曰矇,矇者,竹木之类也…不入师门,无经传之教,以郁朴之实,不晓礼义,立之朝廷,植笮树表之类也,其何益哉?", "b": "汉·王充《论衡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4898wx','笠','1','lì','竹','11','','[{"pinyin": "lì", "defs": [{"meaning": "(形声。从竹,立声。本义:笠帽,用竹箬或棕皮等编制而成)。"}, {"meaning": "同本义,也叫“斗笠”。", "cites": [{"t": "笠,簦无柄也。", "b": "《说文》"}, {"t": "簦谓之笠。", "b": "《广雅》"}, {"t": "何蓑何笠。", "b": "《诗·小雅·无羊》"}, {"t": "台笠缁撮。", "b": "《诗·小雅·都人士》"}], "words": [{"w": "笠子", "t": "箬笠"}, {"w": "笠蓑", "t": "斗笠与蓑衣"}, {"w": "笠毂", "t": "古代撑在兵车上的笠帽"}, {"w": "笠檐", "t": "指笠帽周围下覆冒出的部分。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4899wx','笥','1','sì','竹','11','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从竹,司声。本义:一种盛饭食或衣物的竹器)。"}, {"meaning": "同本义。", "cites": [{"t": "笥,盛食器也。", "b": "《说文》"}, {"t": "不见辒车,见有奉笥而与李氏语者。", "b": "《韩非子·内储说上》"}, {"t": "晔为市吏,馈饵一笥,帝德之不忘。", "b": "《后汉书·酷吏传》"}, {"t": "王以巾笥而藏之庙堂之上。", "b": "《庄子·秋水》"}], "words": [{"w": "笥箧", "t": "竹制的匣子。"}]}, {"meaning": "铠甲一类的防护物。", "cites": [{"t": "材官驺发,矢道同的,则匈奴之革笥木荐弗能支也。", "b": "《汉书》"}]}, {"meaning": "装;藏。", "cites": [{"t": "今夫考居室必以闳门丰屋为美,笥衣裳必以文章遒泽为甲。", "b": "唐·刘禹锡《论书》"}]}]}]','jingmo-wenyan');
