('4900wx','笤','1','tiáo','竹','11','','[{"pinyin": "tiáo", "defs": [{"meaning": "笤帚 。", "words": [{"w": "笤把,笤篱", "t": "即笤帚"}, {"w": "笤帚星", "t": "扫帚星。彗星的俗称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4901wx','笳','1','jiā','竹','11','','[{"pinyin": "jiā", "defs": [{"meaning": "(形声。从竹,加声。本义:胡笳)。"}, {"meaning": "中国古代北方民族的一种吹奏乐器,似笛。通常称“胡笳”  。胡人卷芦叶为笳,吹以作乐,后以竹为管,饰以桦皮,上有三孔,两端加角。", "cites": [{"t": "刁斗笳吹。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "笳角", "t": "胡笳与号角。系北方少数民族的军中乐器"}, {"w": "笳鼓", "t": "胡笳与胡鼓"}, {"w": "笳吟", "t": "胡笳吹奏;笳声萦回。"}]}, {"meaning": "古代妇女使用的发簪。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4902wx','笾','1','biān','竹','11','','[{"pinyin": "biān", "defs": [{"meaning": "竹豆。古代用竹编成的食器,形状如豆,祭祀燕享时用来盛果实、干肉。", "cites": [{"t": "籩,竹豆也。从竹,邊声。", "b": "《说文》"}, {"t": "掌笾之之宾。", "b": "《周礼·笾人》"}, {"t": "笾祭。", "b": "《仪礼·祝赞》。注:枣栗之祭 。”"}, {"t": "品其百笾。", "b": "《国语·周语》"}, {"t": "晋侯享之,有加笾。", "b": "《左传·昭公六年》"}, {"t": "将以实笾豆奉祭祀,供宾客乎?", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "笾人", "t": "周礼官名。天官之属。掌四笾之实,以供王祭祀燕享之用"}, {"w": "笾豆", "t": "古代祭祀燕享时所用的器皿。笾盛桃梅,豆盛肉酱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4903wx','笞','1','chī','竹','11','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从竹,台声。本义:用竹板、荆条击) 用鞭、杖、竹板抽打。", "cites": [{"t": "笞,击也。", "b": "《说文》"}, {"t": "笞者可以教之也。", "b": "《汉书·刑法志》"}, {"t": "捶笞膑脚。", "b": "《荀子·正论》"}], "words": [{"w": "笞楚", "t": "笞是竹片,楚是荆条。用竹片荆条等物责打"}, {"w": "笞挞", "t": "用板子、棍子拷打"}, {"w": "笞服", "t": "拷打而使屈服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4904wx','偾','1','fèn','亻','11','','[{"pinyin": "fèn", "defs": [{"meaning": "(形声。从人,贲声。本义:僵仆)。"}, {"meaning": "同本义。", "cites": [{"t": "偾,僵也。", "b": "《说文》"}, {"t": "牛虽瘠,偾于豚上,其畏不死。", "b": "《左传·昭公十三年》。注:“偾,仆也。”"}, {"t": "一死一生,一偾一起。", "b": "《庄子·天运》"}], "words": [{"w": "偾仆", "t": "倒仆"}, {"w": "偾踣", "t": "僵仆"}, {"w": "偾蹶", "t": "颠仆。"}]}, {"meaning": "覆,翻倒在地。", "cites": [{"t": "郑伯之车偾于济。", "b": "《左传·隐公三年》"}], "words": [{"w": "偾辕", "t": "覆车,喻失败"}, {"w": "偾辙", "t": "覆辙,喻失败。"}]}, {"meaning": "覆败。", "cites": [{"t": "偾军之将,蒙朝廷待以不死。", "b": "《醒世姻缘传》"}], "words": [{"w": "偾师", "t": "偾军。使军队覆败"}, {"w": "偾败", "t": "覆没"}, {"w": "偾将", "t": "败军之将。"}]}, {"meaning": "毁坏;败坏。", "cites": [{"t": "此谓一言偾事。", "b": "《礼记·大学》"}], "words": [{"w": "偾裂", "t": "毁败朝政。"}]}, {"meaning": "死;僵毙。", "cites": [{"t": "此伍子胥所以偾于吴世也。", "b": "《汉书》"}]}, {"meaning": "动,亢奋。", "cites": [{"t": "张脉偾兴,外强中奸。", "b": "《左传·僖公十五年》"}], "words": [{"w": "偾升", "t": "蓬勃上升"}, {"w": "偾张", "t": "扩张突起"}, {"w": "偾发", "t": "激动而奋起"}, {"w": "偾兴", "t": "形容兴奋紧张的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4905wx','偃','1','yǎn','亻','11','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从人,匽(yàn)声。本义:仰卧;仰)。"}, {"meaning": "同本义。", "cites": [{"t": "偃,僵也。", "b": "《说文》。按,伏而覆曰仆,仰而倒曰偃。"}, {"t": "偃,仰也。", "b": "《广雅》"}, {"t": "与一人俱毙,偃,且射子鉏。", "b": "《左传·定公八年》"}, {"t": "迎风则偃,背风则仆。", "b": "《吴越春秋》"}, {"t": "须臾祭毕,倦而偃。——《钟馗传——捉鬼传、平鬼传》", "b": ""}, {"t": "或息偃在床。", "b": "《诗·小雅·北山》"}], "words": [{"w": "偃腹", "t": "仰腹而卧"}, {"w": "偃寝", "t": "仰卧;躺下"}, {"w": "偃斧", "t": "仰斧。指堆土为坟,坟顶窄狭如仰斧形状。"}]}, {"meaning": "停止;停息。", "cites": [{"t": "反而定三革,偃五兵,合天下,立声乐。", "b": "《荀子》"}, {"t": "两君偃兵接好,日中为期。", "b": "《国语·吴语》"}, {"t": "盗贼皆偃,工贾竞臻。", "b": "徐陵《广州刺史欧阳頠德政碑》"}], "words": [{"w": "偃武", "t": "停息武备"}, {"w": "偃革", "t": "停止战争"}, {"w": "偃戢", "t": "停息"}, {"w": "偃鼓", "t": "停敲战鼓。指罢战"}, {"w": "偃兵", "t": "停战。"}]}, {"meaning": "倒下;倒伏。", "cites": [{"t": "天大雷电以风,木尽偃。", "b": "《书·金鰧》"}, {"t": "东面偃旌。", "b": "《仪礼·乡射礼》"}, {"t": "草上之风必偃。", "b": "《论语》"}], "words": [{"w": "偃倒", "t": "倒伏"}, {"w": "偃草", "t": "风吹草倒。"}]}, {"meaning": "厕所。", "cites": [{"t": "观室者,周于寝庙,又适其偃焉。", "b": "《庄子·庚桑楚》"}]}, {"meaning": "古地名 。在今山东省费县南。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4906wx','偕','1','xié','亻','11','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从人,皆声。本义:共同在一起)同本义。", "cites": [{"t": "偕,俱也。", "b": "《说文》"}, {"t": "与雨偕也。", "b": "《左传·庄公七年》"}, {"t": "夙夜必偕。", "b": "《诗·魏风·陟岵》"}, {"t": "故由由然与之偕而不自失焉。", "b": "《孟子·公孙丑上》"}, {"t": "俄人偕英、法、美三国合兵犯天津。", "b": "《清史稿·奕山传》"}, {"t": "偕数友出。", "b": "明·袁宏道《满井游记》"}, {"t": "即偕洋商。", "b": "《广东军务记》"}]}, {"meaning": "一同;一起。", "cites": [{"t": "宜言饮酒,与子偕老。", "b": "《诗·郑风·女日鸡鸣》"}, {"t": "与子偕行。", "b": "《诗·秦风·无衣》"}, {"t": "客不得已与偕行。", "b": "明·魏禧《大铁椎传》"}], "words": [{"w": "偕隐", "t": "同居山林,不求官禄"}, {"w": "偕作", "t": "一起行动"}, {"w": "偕适", "t": "同趋一个方向"}, {"w": "偕生之疾", "t": "与生俱来的病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4907wx','偈','1','jì jié','亻','11','','[{"pinyin": "jì", "defs": [{"meaning": "佛经中的唱词 。偈陀之省", "words": [{"w": "偈颂", "t": "偈文,偈句,偈言,偈语,偈诵。均为梵语“偈佗”。即佛经中的唱颂词"}]}]}, {"pinyin": "jié", "defs": [{"meaning": "勇武。", "cites": [{"t": "其人晖且偈。", "b": "汉·扬雄《太玄·阙》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4908wx','傀','1','kuǐ','亻','11','','[{"pinyin": "kuǐ", "defs": [{"meaning": "(形声。从人,鬼声。本义:伟;大)。"}, {"meaning": "同本义。", "cites": [{"t": "傀,伟也。", "b": "《说文》"}, {"t": "达生之情者傀。", "b": "《庄子·列御寇》"}], "words": [{"w": "傀然", "t": "魁梧貌"}, {"w": "傀俄", "t": "魁伟貌"}, {"w": "傀卓", "t": "卓异。"}]}, {"meaning": "奇异。", "cites": [{"t": "大傀异灾。", "b": "《周礼·大司乐》"}], "words": [{"w": "傀奇", "t": "奇异。亦指奇异之物"}, {"w": "傀怪", "t": "奇特怪异"}, {"w": "傀异", "t": "奇异"}, {"w": "傀伟", "t": "奇特。"}]}]}]','jingmo-wenyan');
