INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4910wx','偻','1','lóu lǚ','亻','11','','[{"pinyin": "lóu", "defs": [{"meaning": "——见“佝偻”(gōulóu)。"}]}, {"pinyin": "lǚ", "defs": [{"meaning": "(形声。从人,娄声。本义:弯腰)。"}, {"meaning": "同本义。", "cites": [{"t": "偻,尩也。", "b": "《说文》。按,《白虎通》:周公背偻是为强后。此字本训背曲。"}, {"t": "偻者不袒。", "b": "《礼记·问丧》"}, {"t": "见疴偻者。", "b": "《庄子·达生》"}, {"t": "行步俯偻。", "b": "《汉书·蔡义传》"}, {"t": "再命而偻。", "b": "《左传·昭公七年》"}, {"t": "偻巫跛觋。", "b": "《荀子·王制》"}, {"t": "正考父一命而伛(曲背),再命而偻(弯腰),三命而俯,循墙而走,孰敢不轨!", "b": "《庄子·列御寇》"}, {"t": "同行则偻身自卑。", "b": "《后汉书·邓后传》"}], "words": [{"w": "偻背", "t": "弓着背"}, {"w": "偻偻", "t": "弓身貌。形容恭顺"}, {"w": "偻行", "t": "曲背而行。形容衰老"}, {"w": "偻步", "t": "驼着背走路"}, {"w": "偻人", "t": "曲背的人。借指老人"}, {"w": "偻身", "t": "弯下身子"}, {"w": "偻俯", "t": "弯下身子,表示恭敬。"}]}, {"meaning": "泛指弯曲。", "cites": [{"t": "虽有圣人之知,未能偻指也。", "b": "《荀子·儒效》"}]}, {"meaning": "驼背的人。", "cites": [{"t": "伛偻提携,往来而不绝者,滁人游也。", "b": "欧阳修《醉翁亭记》"}, {"t": "齐使秃者御秃者,使眇者御眇者,使跛者御跛者,使偻者御偻者。", "b": "《谷梁传》"}]}, {"meaning": "疾速,速度快。", "cites": [{"t": "夫人不偻,不可使入。", "b": "《公羊传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4911wx','皑','1','ái','白','11','','[{"pinyin": "ái", "defs": [{"meaning": "(形声。从白,豈声。字亦作溰。本义:霜雪洁白) 洁白。", "cites": [{"t": "皑,霜雪之白也。", "b": "《说文》"}, {"t": "漂积雪之皑皑兮。", "b": "刘歆《遂初赋》"}, {"t": "浩浩皑皑。", "b": "枚乘《七发》。注:“高白之貌。”"}, {"t": "皑如山上雪。", "b": "古乐府《白头吟》。"}], "words": [{"w": "皑白;皑雪", "t": "白雪。比喻素服。"}]}]}]','jingmo-wenyan');
