('4912wx','皎','1','jiǎo','白','11','','[{"pinyin": "jiǎo", "defs": [{"meaning": "(形声。从白,交声。本义:洁白明亮)。"}, {"meaning": "同本义。", "cites": [{"t": "皎,月之白也。", "b": "《说文》"}, {"t": "月出皎兮。", "b": "《诗·陈风·月出》"}, {"t": "皎皎白驹。", "b": "《诗·小雅·白驹》"}], "words": [{"w": "皎亮", "t": "洁白光明"}, {"w": "皎晶", "t": "洁白晶莹"}, {"w": "皎然", "t": "明亮洁白的样子"}, {"w": "皎日", "t": "明亮的太阳"}, {"w": "皎月", "t": "明月。"}]}, {"meaning": "光照耀。", "cites": [{"t": "明月皎夜光,促织鸣东壁。", "b": "《古诗十九首》"}, {"t": "月皎露华窗影细,风送菊香粘绣袂。", "b": "后蜀·顾《玉楼春》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4913wx','鸻','1','héng','鸟','11','','[{"pinyin": "héng", "defs": [{"meaning": "动物名。又名千鸟 。鸻科的许多海岸栖息鸟之一,它与鹬不同的是有一短的、尖端硬的嘴,通常较肥壮,结构较细密,常到平原、高山草地和海滨等处,大多群居和迁徙,包括若干十分著名的小鸟(如剑鸻)和一些大的类型(如黑腹鸻、金鸻、小嘴鸻等),是重要的狩猎鸟。", "cites": [{"t": "鸻,荒鸟也。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
