INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4934wx','鸾','1','luán','鸟','11','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从鸟,羉(luán)声。本义:鸟名。凤凰的一种。雄性的长生鸟)。"}, {"meaning": "同本义。", "cites": [{"t": "鸾,赤神灵之精也。", "b": "《说文》"}]}, {"meaning": "又。", "cites": [{"t": "赤色,五采,鸡形,鸣中五音。", "b": ""}, {"t": "周成王时氐羌献鸾鸟。", "b": "《周书·王会》。注:“大于凤。”"}, {"t": "鸾鸟,凤皇属也。", "b": "《广雅》"}, {"t": "离为鸾。", "b": "《春秋元命苞》"}, {"t": "女床之山,有鸟名曰鸾鸟。", "b": "《山海经·西山经》"}, {"t": "鸣女床之鸾鸟,舞丹穴之凤凰。", "b": "张衡《东京赋》"}], "words": [{"w": "鸾俦", "t": "佳侣。鸾凤凰一类的神鸟"}, {"w": "鸾帚", "t": "用鸾尾制成的拂尘供仙人所用"}, {"w": "鸾皇", "t": "鸾和皇,都是凤凰之类的神鸟。皇,通凰"}, {"w": "鸾鸟", "t": "神鸟名。凤凰之属"}, {"w": "鸾凤", "t": "鸾鸟和凤凰。比喻贤能,俊美或良善的人"}, {"w": "鸾音鹤信", "t": "鸾鹤传来的音信。指上天的信息。"}]}, {"meaning": "指车衡上的金属铃。", "cites": [{"t": "君子至止,鸾声将将。", "b": "《诗·小雅·庭燎》"}]}, {"meaning": "", "cites": [{"t": "四牡彭彭,八鸾锵锵。", "b": "《诗·大雅·丞民》"}, {"t": "锡、鸾、和铃,昭其声也。", "b": "《左传·桓公二年》"}], "words": [{"w": "鸾带", "t": "缀有小铃铛的带子"}, {"w": "鸾仗", "t": "装饰有金属铃的帝王坐车"}, {"w": "鸾车", "t": "装有金铃的车子。行走时声如鸾鸣。"}]}, {"meaning": "有鸾饰的车子。", "cites": [{"t": "后会鸾驾反旆,群虏寇攻。", "b": "陈琳《为袁绍檄豫州文》"}, {"t": "天子居青阳左个,乘鸾辂,驾苍龙。", "b": "《逸周书·月令》"}, {"t": "鸾车速风电,龙马无鞭策。", "b": "李白《草创大还赠柳官迪》"}], "words": [{"w": "鸾辂", "t": "帝王的车驾。同鸾路"}, {"w": "鸾路", "t": "即鸾辂"}, {"w": "鸾軿", "t": "贵族妇女乘坐的有帷幕的车。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4935wx','孰','1','shú','子','11','','[{"pinyin": "shú", "defs": [{"meaning": "(会意。小篆字形。左上是“享”,左下是“羊”,表示食物是羊肉;右边是“丮”(jí),表示手持。合起来表示手持熟食来吃。本义:熟,煮熟)。"}, {"meaning": "同本义。“熟”的古字。", "cites": [{"t": "孰,食饪也。", "b": "《说文》。字亦作熟。"}, {"t": "宰夫胹熊蹯不孰。", "b": "《左传·宣公二年》"}], "words": [{"w": "孰烂", "t": ""}]}, {"meaning": "成熟。", "cites": [{"t": "寒暑和节,而五谷以时孰。", "b": "《荀子·富国》"}, {"t": "腥其俎,孰其俎。", "b": "《礼记·礼运》"}, {"t": "五谷时孰。", "b": "《礼记·乐记》"}, {"t": "群生而万民殖,五谷孰而草木茂。", "b": "《汉书·董仲舒传》"}]}, {"meaning": "庄稼丰收;五谷有收成。", "cites": [{"t": "夫妇节而天地和,风雨节而五谷孰,衣服节而肌肤和。", "b": "《墨子》"}]}, {"meaning": "缜密,仔细,周详。", "cites": [{"t": "臣恐天下之议君,愿孰察之。", "b": "《商君书·更法》"}, {"t": "兼权之,孰计之。", "b": "《荀子·不苟》"}, {"t": "宁孰谏。", "b": "《礼记·内则》"}, {"t": "凡虑事欲孰。", "b": "《荀子·议兵》。注:“谓精审。”"}, {"t": "思之未孰。", "b": "《周髀算经》"}, {"t": "唯大王与群臣孰计议之。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "明日,徐公来,孰视之,自以为不如。", "b": "《战国策·齐策》"}], "words": [{"w": "孰复", "t": "反复思虑"}, {"w": "孰虑", "t": "计虑周祥"}, {"w": "孰视", "t": "细看"}, {"w": "孰计", "t": "考虑缜密周到"}, {"w": "孰论", "t": "仔细辨析"}, {"w": "孰察", "t": "仔细观察。"}]}, {"meaning": "谁,哪个人或哪些人。", "cites": [{"t": "孰不可忍也。", "b": "《论语》"}, {"t": "人非生而行之者,孰能无惑?", "b": "唐·韩愈《师说》"}, {"t": "孰知赋敛之毒有甚是蛇者乎!", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "孰能当之;孰胜孰负;孰何", "t": "谁何"}, {"w": "孰与", "t": "与谁"}, {"w": "孰谁", "t": "何人。"}]}, {"meaning": "一组中的哪一个或哪几个。", "cites": [{"t": "吾与徐公孰美?", "b": "《战国策·齐策》"}, {"t": "百姓孰敢不箪食壶浆以迎将军者乎?", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "孰是孰非", "t": ""}]}, {"meaning": "什么。", "cites": [{"t": "与其杀是人也,宁可得此国也,甚孰利乎?", "b": "《国语·越语》"}, {"t": "孰明之,由封建而明之也。", "b": "唐·柳宗元《封建论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4936wx','庹','1','tuǒ','广','11','','[{"pinyin": "tuǒ", "defs": [{"meaning": "成人两臂左右平伸时两手之间的距离,约合五尺。", "cites": [{"t": "庹,两腕引长谓之庹。", "b": "《字汇补》"}]}, {"meaning": "成人两臂左右平伸时两手之间的距离。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4937wx','庾','1','yǔ','广','11','','[{"pinyin": "yǔ", "defs": [{"meaning": "(形声。从广(yǎn),臾声。广,依山崖建成的房子。从“广”与房屋有关。本义:露天的谷堆)。"}, {"meaning": "同本义。", "cites": [{"t": "钉头磷磷,多于在庾之粟粒。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "庾积", "t": "露天储积之谷物。"}]}, {"meaning": "储存水路转运粮食的仓库。", "cites": [{"t": "粟粮漕庾,不下十万。", "b": "《战国策》"}]}, {"meaning": "泛指粮库。", "cites": [{"t": "钉头磷磷,多于在庾之粟粒。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "庾司", "t": "宋代管理粮仓的机构"}, {"w": "庾曹", "t": "管理仓廪之曹司"}, {"w": "庾吏", "t": "古代管粮仓的小官"}, {"w": "庾廪", "t": "粮食。"}]}, {"meaning": "量词。古代量名,容二斗四升 。一说十六斗为一庾。", "cites": [{"t": "粟五千庾。", "b": "《左传》。杜预注:“庾,十六斗,凡八千斛。”"}]}, {"meaning": "大庾岭的简称。", "cites": [{"t": "湘瑟声沉,庾梅信断。", "b": "宋·秦观《青门饮》"}], "words": [{"w": "庾岭", "t": "为五岭之一,在江西省大庾县南。岭上多植梅树,故又称“梅岭”。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4938wx','痔','1','zhì','疒','11','','[{"pinyin": "zhì", "defs": [{"meaning": "痔疮。", "cites": [{"t": "痔,后病也。从疒,寺声。", "b": "《说文》"}, {"t": "肠澼为痔。", "b": "《素问·生气通天论》"}, {"t": "与人有痔病者。", "b": "《庄子·人间世》"}, {"t": "又疥且痔。", "b": "宋玉《登徒子好色赋》"}, {"t": "子岂治其痔邪,何得车之多也?", "b": "《庄子·列御寇》"}], "words": [{"w": "痔疾", "t": "痔疮"}, {"w": "痔病", "t": "痔疮。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4939wx','痍','1','yí','疒','11','','[{"pinyin": "yí", "defs": [{"meaning": "创伤。", "cites": [{"t": "楚子郑师败绩。败者称师,楚何以不称师?王痍也。王痍者何?伤乎矢也。", "b": "《公羊传》"}, {"t": "痍痏(创伤。多指战乱所造成的);痍毁(创伤;破坏)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4940wx','疵','1','cī','疒','11','','[{"pinyin": "cī", "defs": [{"meaning": "(形声。从疒(chuáng),此声。本义:小毛病)。"}, {"meaning": "同本义。", "cites": [{"t": "疵,病也。", "b": "《说文》"}, {"t": "言乎其小疵也。", "b": "《易·系辞》"}, {"t": "不吹毛而求小疵。", "b": "《韩非子》"}], "words": [{"w": "疵瘕", "t": "腹疾。"}]}, {"meaning": "引申为过失;缺点。", "cites": [{"t": "知我国有疵。", "b": "《书·大诰》"}], "words": [{"w": "疵吝", "t": "缺点。疵也作玼"}, {"w": "瑕疵", "t": "小毛病、过失"}, {"w": "疵弊", "t": "缺点或过失。"}]}, {"meaning": "灾祸。", "cites": [{"t": "鬼神为之疵疠。", "b": "《谷梁传序》"}], "words": [{"w": "疵疠", "t": "灾害、疾疫"}, {"w": "疵疫", "t": "灾害疫病。"}]}, {"meaning": "痛。", "cites": [{"t": "走的我口干舌苦,眼晕头疵,我可也把不住抹泪揉眵。", "b": "元·杨显之《潇湘风》"}]}, {"meaning": "挑剔,非议,诋毁。", "cites": [{"t": "疵,毁也。", "b": "《集韵·纸韵》"}, {"t": "正义直指,举人之过,非毁疵也。", "b": "《荀子·不苟》"}, {"t": "大化陵迟,而诋疵先主。", "b": "《后汉书·李固传》"}], "words": [{"w": "疵毛", "t": "吹毛求疵,挑毛拣刺"}, {"w": "疵陋", "t": "见闻浅陋而好非议。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4941wx','翊','1','yì','羽','11','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从羽,立声。本义:飞的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "翊,飞貌。", "b": "《说文》"}]}, {"meaning": "明日(年)。", "cites": [{"t": "越若翊辛丑,诸生庶民大和会。", "b": "《汉书·王莽传上》。颜师古云:“翊,明也。”"}], "words": [{"w": "翊日", "t": "明日。"}]}, {"meaning": "辅佐。", "cites": [{"t": "翊赞季兴。", "b": "《三国志·吕凯传》"}, {"t": "左内史更名左冯翊。", "b": "《汉书》"}], "words": [{"w": "翊天", "t": "辅佐天子"}, {"w": "翊戴", "t": "拥戴辅弼"}, {"w": "翊卫", "t": "辅佐护卫"}, {"w": "翊化", "t": "辅佐教化"}, {"w": "翊佐", "t": "辅佐"}, {"w": "翊亮", "t": "辅佐"}, {"w": "翊从", "t": "护卫随从。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4942wx','旌','1','jīng','方','11','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。本义:古代用牦牛尾或兼五采羽毛饰竿头的旗子)。"}, {"meaning": "同本义。", "cites": [{"t": "旌,游车载旌析羽。", "b": "《说文》"}, {"t": "位所谓緌有虞氏旌也。", "b": "《礼记·明堂位》"}, {"t": "建旌提鼓。", "b": "《国语·吴语》"}], "words": [{"w": "旌旄", "t": "古代用牦牛尾与羽毛装饰的军旗,或代指各种旗帜"}, {"w": "旌羽", "t": "旌旗。因有羽饰,故称。"}]}, {"meaning": "古代旗的总称。", "cites": [{"t": "旌蔽日兮敌若云。", "b": "《楚辞·九歌·国殇》"}, {"t": "旌麾南指,刘琮束手。", "b": "《资治通鉴》"}], "words": [{"w": "旌旃", "t": "泛指旗帜"}, {"w": "旌幡", "t": "泛指旗帜"}, {"w": "旌帜", "t": "旗帜"}, {"w": "旌幢", "t": "旗幡"}, {"w": "旌头", "t": "旗杆顶端的矛头。"}]}, {"meaning": "旌节,古代使者所持的节。", "cites": [{"t": "王婆道:“眼望旌节至,耳听到消息。”", "b": "《金瓶梅》"}]}, {"meaning": "表彰。", "cites": [{"t": "旌其所为。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "旌书", "t": "表彰的文书"}, {"w": "旌善", "t": "表彰善人善事"}, {"w": "旌表节烈", "t": "表彰节妇烈女"}, {"w": "旌典", "t": "朝廷表彰的恩典。"}]}, {"meaning": "识别。", "cites": [{"t": "诚应宠赏,以旌其美。", "b": "曹操《表论田畴功》"}], "words": [{"w": "旌别", "t": "识别;区别。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4943wx','旎','1','nǐ','方','11','','[{"pinyin": "nǐ", "defs": [{"meaning": "(形声。双音词“旖(qí)旎”,本为旌旗随风飘扬的样子,引申为柔美的样子)——见“旖旎”(yǐnǐ):柔和美好。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4944wx','袤','1','mào','衣','11','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从衣,矛声。本义:纵长或南北距离的长度)。"}, {"meaning": "同本义。", "cites": [{"t": "南北曰袤,东西曰广。", "b": "《说文》"}, {"t": "天地之广袤。", "b": "《周髀算经》"}, {"t": "广袤可千里。", "b": "班固《汉书》"}, {"t": "子何不受地?从某至某,广袤六里。", "b": "《史记·楚世家》"}, {"t": "延袤万余里。", "b": "《史记·蒙怡列传》"}, {"t": "广袤丰杀,一称心力。", "b": "白居易《庐山草堂记》"}], "words": [{"w": "广袤", "t": "广指横长或东西距离,袤指纵长或南北距离"}, {"w": "袤延", "t": "延袤。伸展延续"}, {"w": "袤远", "t": "宽广辽远"}, {"w": "袤广", "t": "宽广"}, {"w": "袤僻", "t": "宽广而荒僻。"}]}, {"meaning": "泛指长度。", "cites": [{"t": "周袤数百里。", "b": "扬雄《羽猎赋序》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4945wx','阇','1','dū shé','门','11','','[{"pinyin": "dū", "defs": [{"meaning": "城门上的台。", "words": [{"w": "阇台", "t": "城门上的台。"}]}, {"meaning": "泛指台。", "cites": [{"t": "阇谓之台。", "b": "《尔雅》"}, {"t": "西夷气如室屋,南夷气如阇台。", "b": "《晋书》"}]}]}, {"pinyin": "shé", "defs": [{"meaning": "", "words": [{"w": "阇王", "t": "佛家语。人名。阿阇世王的略称。又称“阇世”"}, {"w": "阇利", "t": "佛家语。梵语jala的音译。水的异名"}, {"w": "阇提", "t": "佛家语。梵语Jāti的音译。花名。即“金钱花”"}, {"w": "阇维", "t": "佛家语。指僧死后加以火化"}, {"w": "阇婆隶", "t": "佛教用语。饿鬼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4946wx','阈','1','yù','门','11','','[{"pinyin": "yù", "defs": [{"meaning": "门槛。", "cites": [{"t": "阈,门榍也。", "b": "《说文》"}, {"t": "阈,门限也。", "b": "《玉篇》"}, {"t": "柣谓之阈。", "b": "《尔雅》。注:“阈,门限。”"}, {"t": "不践阈。", "b": "《礼记·曲礼》"}, {"t": "宾入不中门,不履阈。", "b": "《礼记·玉藻》"}, {"t": "见兄弟不踰阈。", "b": "《左传·僖公二十二年》"}, {"t": "思不出乎门阈。", "b": "《汉书·王莽传》"}, {"t": "仍增崖而衡阈。", "b": "《后汉书·班固传》"}, {"t": "立不中门,行不履阈。", "b": "《论语·乡党》"}], "words": [{"w": "阈闱", "t": "妇女所居的内室。"}]}, {"meaning": "门户;门口。", "cites": [{"t": "仰瞻城阈,俯惟阙庭。", "b": "三国魏·曹植《应诏》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4947wx','阉','1','yān','门','11','','[{"pinyin": "yān", "defs": [{"meaning": "(会意。从门,从奄,奄亦声。本义:被阉割的人。古代常用来看守宫门) 同本义。"}, {"meaning": "特指宦官。", "cites": [{"t": "逆阉防伺甚严,虽家仆不得近。", "b": "方苞《左忠毅公逸事》"}], "words": [{"w": "阉君", "t": "主领宫内太监的官"}, {"w": "阉奴", "t": "指太监"}, {"w": "阉竖", "t": "太监的贱称。竖,供役使的人"}, {"w": "阉党", "t": "依附阉官太监而结成的党派"}, {"w": "阉官", "t": "由太监充任官员的贱称"}, {"w": "阉竖", "t": "太监的贱称"}, {"w": "阉儿", "t": "蔑称宦官"}, {"w": "阉寺", "t": "宦官"}, {"w": "阉使", "t": "出使的太监"}, {"w": "阉狗", "t": "骂太监的话"}, {"w": "阉尹", "t": "太监头头。"}]}, {"meaning": "阉割。", "cites": [{"t": "宦官悉用阉人。", "b": "《后汉书》"}], "words": [{"w": "阉侍", "t": "被阉过的奴仆。也称阉奴、阉阍"}, {"w": "阉洁", "t": "割除动物的睾丸或卵巢。"}]}]}]','jingmo-wenyan');
