INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4949wx','阋','1','xì','门','11','','[{"pinyin": "xì", "defs": [{"meaning": "(会意。从門(斗),从兒,兒亦(ní)声。兒,善讼者。本义:不和,争吵) 同本义。", "cites": [{"t": "鬩,恒讼也。", "b": "《说文》"}, {"t": "兄弟阋于墙,外御其务(侮)。", "b": "《诗·小雅·常棣》"}, {"t": "兄弟谗阋。", "b": "《国语·周语》"}, {"t": "兄弟阋于墙,外御其务。", "b": "《诗·小雅·常棣》"}], "words": [{"w": "阋讼", "t": "兄弟或家人相争讼"}, {"w": "阋墙", "t": "在墙内争吵。指兄弟失和"}, {"w": "阋墙谇帚", "t": "内部争吵不和。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4950wx','阍','1','hūn','门','11','','[{"pinyin": "hūn", "defs": [{"meaning": "(形声。从門,昏声。“昏”亦兼表字义。本义:守门人)。"}, {"meaning": "同本义。", "cites": [{"t": "阍,常以昏闭门隶也。", "b": "《说文》"}, {"t": "艮为阍寺。", "b": "《易·说卦传》"}, {"t": "阍者,守门之贱者也。", "b": "《礼记·祭统》"}, {"t": "阍门者,寺人也。", "b": "《谷梁传·襄公二十九年》"}], "words": [{"w": "阍者", "t": "守门的人"}, {"w": "阍人", "t": "守门人"}, {"w": "阍媪", "t": "守门人的妻子。"}]}]}]','jingmo-wenyan');
