('4951wx','阏','1','è yān','门','11','','[{"pinyin": "è", "defs": [{"meaning": "阻塞。", "cites": [{"t": "阏,遮拥也。从门,於声。", "b": "《说文》"}], "words": [{"w": "阏塞", "t": "壅塞,阻塞"}, {"w": "阏往", "t": "阻止放逸的意念和行为"}, {"w": "阏绝", "t": "阻断,杜绝"}, {"w": "阏积", "t": "阻滞积聚。"}]}, {"meaning": "遏止;抑制。", "cites": [{"t": "民气郁阏而滞著。", "b": "《吕氏春秋·古乐》"}], "words": [{"w": "阏制", "t": "遏制"}, {"w": "阏密", "t": "禁绝"}, {"w": "阏抑", "t": "抑制。"}]}, {"meaning": "门扇;闸板。", "cites": [{"t": "开通沟渎,起水门提阏,凡数十处。", "b": "《汉书·召信臣传》"}]}]}, {"pinyin": "yān", "defs": []}]','jingmo-wenyan');
