INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4955wx','敝','1','bì','攵','11','','[{"pinyin": "bì", "defs": [{"meaning": "同本义。", "cites": [{"t": "敝,一曰败衣。", "b": "《说文》"}, {"t": "苟有衣必见其敝。", "b": "《礼记·缁衣》。郑训败衣。"}, {"t": "邻有敝舆而欲窃之。", "b": "《孙子·谋攻》"}, {"t": "侯生摄敝衣冠。", "b": "《史记·魏公子列传》"}, {"t": "余则缊袍敝衣处其间。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "敝鼓丧豚", "t": "击破鼓,宰杀猪以求神治病。指徒费而无益"}, {"w": "敝帷不弃", "t": "不轻易丢弃破旧的帷幕"}, {"w": "敝衣", "t": "破旧衣服。"}]}, {"meaning": "疲惫,困乏,衰败。", "cites": [{"t": "还师以敝楚。", "b": "《左传·襄公九年》。注:“疲也。”"}, {"t": "土敝则草木不长。", "b": "《史记·乐书》"}, {"t": "曹操之众远来疲敝。", "b": "《资治通鉴》"}, {"t": "吏民凋敝。", "b": "《汉书·张敞传》"}], "words": [{"w": "敝卒", "t": "疲惫的士卒"}, {"w": "敝敝", "t": "疲困的样子。"}]}, {"meaning": "失败。", "cites": [{"t": "敝于韩。", "b": "《左传·僖公二年》。注:“败也。”"}]}, {"meaning": "弃。", "cites": [{"t": "冠而敝之。", "b": "《礼记·郊特牲礼》。释文:“弃也。”"}]}, {"meaning": "损害。", "cites": [{"t": "因人之力而敝之,不仁。", "b": "《左传·僖公三十年》"}, {"t": "盖供过求,时价劣经价,则供者必受敝,受敝则迁。", "b": "清·梁启超《生计学学说沿革小史》"}]}]}]','jingmo-wenyan');
