INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4963wx','渍','1','zì','氵','11','','[{"pinyin": "zì", "defs": [{"meaning": "(本义:短时间浸泡)。"}, {"meaning": "同本义。", "cites": [{"t": "渍,沤也。", "b": "《说文》"}, {"t": "剥削淹渍以为菹。", "b": "《诗·楚茨》笺"}, {"t": "水浸曰渍。", "b": "《通俗文》"}]}, {"meaning": "《神农》、《后稷》藏种之方,煮马屎以渍种者。——《论语·商虫》。", "cites": [{"t": "净淘种子,渍经三宿。", "b": "贾思勰《齐民要术》"}], "words": [{"w": "渍酒", "t": "浸泡在酒里"}, {"w": "渍痕", "t": "水侵蚀的污迹"}, {"w": "渍渍", "t": "满是汗水或泪水的样子。"}]}, {"meaning": "染。", "cites": [{"t": "钟氏染羽以朱湛丹秫,三月而炽之,淳而渍之。", "b": "《周礼·考工记·钟氏》"}], "words": [{"w": "渍浸", "t": "浸染。"}]}, {"meaning": "沾染。", "cites": [{"t": "飞毛遍绿野,洒血渍芳丛。", "b": "杜淹《咏寒食斗鸡应秦王教》"}], "words": [{"w": "渍污", "t": "污染。"}]}, {"meaning": "染。", "cites": [{"t": "以视孤寡老弱之渍病,穷困颜色愁悴不赡者,心身自食之。", "b": "《吕氏春秋》"}], "words": [{"w": "渍病", "t": "染病。"}]}, {"meaning": "陷入。", "cites": [{"t": "行而供冀,非渍淖也;行而俯项,非击戾也。", "b": "《荀子》"}], "words": [{"w": "渍淖", "t": "陷入泥沼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4964wx','渚','1','zhǔ','氵','11','','[{"pinyin": "zhǔ", "defs": [{"meaning": "(形声。从水,者声。本义:古水名。渚水)。"}, {"meaning": "水中的小洲。", "cites": [{"t": "小洲曰渚。", "b": "《说文》引《尔雅》。传:“渚,小洲也。”"}, {"t": "两涘渚涯之间。", "b": "《庄子·秋水》"}, {"t": "渠弭于有渚。", "b": "《国语·齐语》"}, {"t": "夕弭节兮北渚。", "b": "《楚辞·湘君》"}, {"t": "乘鄂渚而反顾兮。", "b": "《楚辞·涉江》"}, {"t": "江有渚,之子归,不我与。", "b": "《诗·召南·江有渚》"}, {"t": "避渚洲。", "b": "宋·文天祥《后序》"}], "words": [{"w": "渚牙", "t": "洲上初生的草芽"}, {"w": "渚田", "t": "小洲上的田"}, {"w": "渚烟", "t": "笼罩在小洲上的烟雾"}, {"w": "渚泽", "t": "洲中积水的洼地。"}]}, {"meaning": "水边。", "cites": [{"t": "汛洲清川渚,遥望高山阴。", "b": "晋·陆机《豫章行》"}], "words": [{"w": "渚莲", "t": "水边荷花"}, {"w": "渚宫", "t": "春秋楚国的宫名。故址在今湖北省江陵县。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4965wx','淇','1','qí','氵','11','','[{"pinyin": "qí", "defs": [{"meaning": "水名。又名“淇河”。", "cites": [{"t": "淇,淇水出河内共北山,东入河,或曰出隆虑西山。", "b": "《说文》"}]}, {"meaning": "按,古为黄河支流,自河南省林县东南曲折流至今汲县东北淇门镇南入黄河。"}, {"meaning": "古州名 。今县名。在河南省。"}, {"meaning": "山名 。又名“北山”、“大号山”、“沮洳山”等,为淇水所出。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4966wx','淅','1','xī','氵','11','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从水,析声。本义:淘。", "cites": [{"t": "淅,洒米也。", "b": "《说文》"}, {"t": "淅,洒也。", "b": "《广雅》"}, {"t": "淅米而储之。", "b": "《淮南子·兵略》"}, {"t": "祝淅米于堂。", "b": "《仪礼·士丧礼》"}, {"t": "矛头淅米剑头炊。", "b": "《晋书》"}], "words": [{"w": "淅米", "t": "淘米"}, {"w": "淅玉", "t": "淘净的米"}, {"w": "淅二泔", "t": "第二道淘米水"}, {"w": "淅箕", "t": "竹过滤器。"}]}, {"meaning": "淘过的米,洗后控去水的米。", "cites": [{"t": "孔子之去齐,接淅而行。", "b": "《孟子·万章下》"}]}, {"meaning": "水名 。一名析水,通称淅水,又称“淅川”、“淅河”。发源于河南省卢氏县,至渐川县双河镇附近入丹江。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4967wx','淞','1','sōng','氵','11','','[{"pinyin": "sōng", "defs": [{"meaning": "水气凝结成的冰花。", "cites": [{"t": "园林初日静无风,雾淞花开处处同。", "b": "宋·曾巩《雾淞》"}]}, {"meaning": "中国江名 。淞江,通称“吴淞江”。发源于太湖,到上海跟黄浦江合流入长江。", "cites": [{"t": "淞,水名,在吴。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4968wx','渎','1','dòu dú','氵','11','','[{"pinyin": "dòu", "defs": [{"meaning": "本义: 洞; 穴。", "cites": [{"t": "[郑伯有] 晨, 自墓门之渎入。", "b": "《左传》。杜预注:“墓门,郑城门。”"}]}]}, {"pinyin": "dú", "defs": [{"meaning": "(形声。从水,卖声。本义:水沟,水渠)。"}, {"meaning": "同本义。又特指邑中的沟。", "cites": [{"t": "渎,沟也。一曰邑中沟。", "b": "《说文》"}, {"t": "坎为沟渎。", "b": "《易·读卦》"}, {"t": "开其渎。", "b": "《荀子·脩身》"}, {"t": "彼寻常之ň渎兮。", "b": "《史记·屈原贾生列传》。索隐:“小渠也。”"}, {"t": "掌沟渎浍池之禁。", "b": "《周礼·雍氏》"}, {"t": "有决渎于殷周之世者,必为汤武笑矣。", "b": "《韩非子·五蠹》"}], "words": [{"w": "渎田", "t": "开沟渠而溉田。"}]}, {"meaning": "大川。", "cites": [{"t": "江淮河济为四渎。", "b": "《尔雅》"}, {"t": "再三渎。", "b": "《易·蒙》"}], "words": [{"w": "四渎", "t": "长江、黄河、淮水、济水。"}]}, {"meaning": "轻慢;不敬。", "cites": [{"t": "渎货无厌。", "b": "《左传·昭公十三年》"}, {"t": "不亦渎姓矣乎。", "b": "《国语·周语》"}], "words": [{"w": "渎奏", "t": "臣子向皇帝启奏时用的谦辞"}, {"w": "渎宸聪", "t": "谦辞。意为冒犯皇帝。宸:王位、帝王的代称"}, {"w": "渎控", "t": "轻率提出控诉"}, {"w": "渎慢,渎亵", "t": "轻慢,亵渎"}, {"w": "渎聒", "t": "轻慢多话。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4969wx','涿','1','zhuō','氵','11','','[{"pinyin": "zhuō", "defs": [{"meaning": "水滴。", "cites": [{"t": "涿,流下滴也。", "b": "《说文》。段玉裁注:“今俗谓一滴为一涿,音如笃,即此字也。”"}]}, {"meaning": "水名 。源出河北省涿鹿县涿鹿山。"}, {"meaning": "涿州。", "cites": [{"t": "与蚩尤战于涿鹿之野。", "b": "《庄子·盗跖》。涿州属河北省。汉置涿县,为涿郡治所,唐改范阳县,明为涿州,1913年复改涿县,现又改为涿州"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4970wx','淖','1','nào','氵','11','','[{"pinyin": "nào", "defs": [{"meaning": "(形声。从水,卓声。本义:泥沼;深泥,烂泥)。"}, {"meaning": "同本义。", "cites": [{"t": "淖,泥也。", "b": "《说文》"}, {"t": "天雨淖。", "b": "《汉书·韦元成传》"}, {"t": "世沉淖而难论兮。", "b": "《楚辞·怨世》"}, {"t": "和泥曰淖。", "b": "《通俗文》"}, {"t": "有淖于前,乃皆左右相违于淖。", "b": "《左传·成公十六年》"}, {"t": "濯淖污泥之中。", "b": "《资治通鉴·汉纪》"}], "words": [{"w": "淖泞", "t": "泥烂滑溜"}, {"w": "淖湴", "t": "淤泥"}, {"w": "淖污", "t": "泥水混浊"}, {"w": "淖田", "t": "烂泥田"}, {"w": "淖潦", "t": "烂泥积水。"}]}, {"meaning": "流体。", "cites": [{"t": "漆淖水淖,合两淖则为蹇。", "b": "《吕氏春秋》"}]}, {"meaning": "湿润。", "cites": [{"t": "淖乎如在于海。", "b": "《管子·内业》。"}, {"t": "淖,湿也。", "b": "《广雅》"}], "words": [{"w": "淖泽", "t": "湿润。"}]}, {"meaning": "柔和。", "cites": [{"t": "夫水,淖弱以清。", "b": "《管子·水地》"}, {"t": "嘉荐普淖。", "b": "《仪礼·少牢礼》。注:“和也。”"}], "words": [{"w": "淖溺", "t": "柔软"}, {"w": "淖糜", "t": "烂糊粥"}, {"w": "淖泞", "t": "泥泞。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4971wx','挲','1','shā suō','手','11','','[{"pinyin": "shā", "defs": [{"meaning": "“挓挲”(zhāshā):手、头发、树枝等张开。"}]}, {"pinyin": "suō", "defs": [{"meaning": "抚摩。", "cites": [{"t": "挱,手梛挱也。", "b": "《玉篇》"}, {"t": "共饭不泽手。", "b": "《礼记·曲礼上》。注:“泽,梛莎也。”雷浚曰:“梛莎即搓挪。”"}], "words": [{"w": "摩挲", "t": "以手抚摸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4972wx','淠','1','pì','氵','11','','[{"pinyin": "pì", "defs": [{"meaning": "古水名。"}, {"meaning": "在河南省潢州县东,又名“白露河”或“白鹭河”,北流注入淮河。"}, {"meaning": "在安徽省西部。源出霍山县南,北流经六安县,至正阳关入淮河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4973wx','涸','1','hé','氵','11','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从水,固声。本义:失去水而干枯)。"}, {"meaning": "同本义。", "cites": [{"t": "涸,竭也。", "b": "《尔雅·释诂》"}, {"t": "仲秋之月…水始涸。", "b": "《礼记·月令》"}, {"t": "商涸旱。", "b": "《吕氏春秋·慎大》。注:“涸,枯也。”"}, {"t": "兀若枯木,豁若涸流。", "b": "陆机《文赋》"}], "words": [{"w": "涸辙", "t": "鱼在干涸的车辙中。比喻处于困境之中,急待救援"}, {"w": "涸泽", "t": "干涸的沼泽;抽干沼泽的水"}, {"w": "涸流", "t": "枯竭的水流"}, {"w": "涸溜", "t": "干枯的小水流。"}]}, {"meaning": "竭;尽。", "cites": [{"t": "措国于不倾之地,积于不涸之仓,藏于不竭之府。", "b": "《管子·牧民》"}], "words": [{"w": "涸思干虑", "t": "犹言绞尽脑汁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4974wx','渑','1','miǎn shéng','氵','11','','[{"pinyin": "miǎn", "defs": [{"meaning": "地名，在中国河南省。"}]}, {"pinyin": "shéng", "defs": [{"meaning": "古水名 。源出今山东省淄博市东北,西北流至博兴东南入时水。时水的下游。亦称“渑水”。", "cites": [{"t": "有酒如渑,有肉如陵。", "b": "《左传·昭公十二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4975wx','淦','1','gàn','氵','11','','[{"pinyin": "gàn", "defs": [{"meaning": "(也作汵)。"}, {"meaning": "水渗入船中。", "cites": [{"t": "淦,水入船中也。", "b": "《说文》。段玉裁注:“水入船中,必由朕(舟缝)而入。淦者,浸淫随理之意。”"}]}, {"meaning": "涂泥。", "cites": [{"t": "淦,泥也。", "b": "《说文》。段玉裁注:“谓涂泥也。”"}]}, {"meaning": "河工术语。大溜;激溜 。又河流中泓,由于河底坎坷不平,激溜成浪,起伏甚大者,在黄河下游,也称为淦。"}, {"meaning": "淦水,在江西省境 。源出清江县东南离山,北流经紫淦山入赣江。"}, {"meaning": "船舱中的水。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4976wx','淝','1','féi','氵','11','','[{"pinyin": "féi", "defs": [{"meaning": "淝河。也叫淝水 。源出安徽省合肥市西北。分为二支:一支东南流,注入巢湖;一支西流至寿县,又西北经八公山南入淮河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4977wx','淬','1','cuì','氵','11','','[{"pinyin": "cuì", "defs": [{"meaning": "(形声。从水,卒声。本义:盛水以供淬火的器具) 同本义。", "cites": [{"t": "淬,灭火器也。", "b": "《说文》。按,贮水以焠刃之器,其实焠、淬同字,刃出于火,故从火。"}]}, {"meaning": "淬火。", "cites": [{"t": "得赵人徐夫人之匕首,取之百金,使二以药淬之。", "b": "《战国策·燕策》"}, {"t": "火与水合为淬。", "b": "《汉书·天文志》"}, {"t": "以药淬之。", "b": "《史记·刺客传》"}], "words": [{"w": "淬淬黑", "t": "如钢铁淬过火一样的颜色"}, {"w": "淬砺", "t": "淬火磨砺。比喻人刻苦锻炼;勤勉奋发"}, {"w": "淬刃", "t": "刀刃淬火。"}]}, {"meaning": "磨。", "words": [{"w": "淬镜", "t": "磨镜"}, {"w": "淬磨", "t": "磨砺;磨炼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4978wx','涪','1','fú','氵','11','','[{"pinyin": "fú", "defs": [{"meaning": "水名 。在四川省中部,源出松潘县,东南流经平武、绵阳、三台、遂宁、潼南、至合川县入嘉陵江。"}, {"meaning": "古州名  。故治所在今四川省涪陵市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4979wx','淙','1','cóng','氵','11','','[{"pinyin": "cóng", "defs": [{"meaning": "(形声。从水,宗声。本义:流水声) 同本义。", "cites": [{"t": "淙,水声也。", "b": "《说文》"}, {"t": "深大壑与沃焦。", "b": "郭璞《江赋》"}], "words": [{"w": "淙潺", "t": "水流声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4980wx','涫','1','guàn','氵','11','','[{"pinyin": "guàn", "defs": [{"meaning": "沸滚。", "cites": [{"t": "涫,沸也。从水,官声。", "b": "《说文》。俗字作滚。"}, {"t": "肠如涫汤。", "b": "《史记·龟策传》"}, {"t": "汤泉涫沸,洪波漂厉。", "b": "三国魏·刘邵《赵都赋》"}, {"t": "涫涫纷纷,孰知其形。", "b": "《荀子·解蔽》"}], "words": [{"w": "涫汤", "t": "沸滚的水"}, {"w": "涫沸", "t": "沸腾;混乱"}, {"w": "涫涫", "t": "沸腾貌。"}]}, {"meaning": "假借为“盥”。盥洗。", "cites": [{"t": "进涫漱巾栉。", "b": "《列子·黄帝》"}], "words": [{"w": "涫潄", "t": "盥漱。亦指盥漱用的水。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4981wx','渌','1','lù','氵','11','','[{"pinyin": "lù", "defs": [{"meaning": "清澈。", "cites": [{"t": "渌水荡漾清猿啼。", "b": "唐·李白《梦游天姥吟留别》"}], "words": [{"w": "渌水", "t": "清澈的水"}, {"w": "渌池", "t": "清澈的池塘"}, {"w": "渌洄", "t": "清澈回旋的水"}, {"w": "渌浆", "t": "清水"}, {"w": "渌老", "t": "眼睛的俗称。"}]}, {"meaning": "水名。湘江支流。发源于江西萍乡,西流经湖南醴陵,至株洲南渌口注入湘江。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4982wx','淄','1','zī','氵','11','','[{"pinyin": "zī", "defs": [{"meaning": "中国水名。"}, {"meaning": "今山东省内的淄河。源出莱芜县东北,流经临淄市东,过广饶县境,汇合小清河入海。"}, {"meaning": "山东省新泰县的羊流河。"}, {"meaning": "中国古州名 。隋置,治所在今山东省淄博市。"}, {"meaning": "黑色", "cites": [{"t": "不曰白乎?涅尔不淄。", "b": "《史记·孔子世家》"}, {"t": "化白于泥淄。", "b": "《太玄·更》"}, {"t": "在涅贵不淄。", "b": "崔瑗《座右铭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4983wx','惬','1','qiè','忄','11','','[{"pinyin": "qiè", "defs": [{"meaning": "(形声。从心,匧(qiè)声。本义:快意,满足) 同本义。", "cites": [{"t": "愜,快也。从心,匧声。今字作惬,左形右声。", "b": "《说文》"}, {"t": "未有愜志。", "b": "《汉书·文帝纪》"}, {"t": "惬心者贵当。", "b": "陆机《文赋》"}, {"t": "思意不惬。", "b": "《世说新语·文学》"}], "words": [{"w": "惬乎人心", "t": "大快人心"}, {"w": "惬志", "t": "称心满足"}, {"w": "惬快", "t": "称心,满足"}, {"w": "惬素", "t": "快心"}, {"w": "惬望", "t": "欢欣观看。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4984wx','悻','1','xìng','忄','11','','[{"pinyin": "xìng", "defs": [{"meaning": "(形声。从心,幸声。本义:恼怒的样子) 同本义。", "cites": [{"t": "谏于君而不受,则怒,悻悻然见于面。", "b": "《孟子·公孙丑下》"}], "words": [{"w": "悻动", "t": "怒形于色。"}]}, {"meaning": "刚直。", "cites": [{"t": "荡莽很悻,道之非耶?", "b": "唐·柳宗元《东明张先生墓志》"}], "words": [{"w": "悻直", "t": "刚直;亦指刚愎固执"}, {"w": "悻切", "t": "刚直。"}]}, {"meaning": "固执。", "cites": [{"t": "仄闻长者言,悻直非养寿。", "b": "宋·苏轼诗"}], "words": [{"w": "悻直", "t": "固执,任性。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4985wx','悱','1','fěi','忄','11','','[{"pinyin": "fěi", "defs": [{"meaning": "想说而说不出的样子。", "cites": [{"t": "不愤不启,不悱不发。", "b": "《论语·述而》"}], "words": [{"w": "悱悱", "t": "抑郁于心而未能表达貌"}, {"w": "悱发", "t": "欲说而不能,有待别人开导启发。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4986wx','惝','1','tǎng','忄','11','','[{"pinyin": "tǎng", "defs": [{"meaning": "(形声。从心,尚声。本义:怅惘)。"}, {"meaning": "同本义。", "cites": [{"t": "客出而君惝然若有亡也。", "b": "《庄子·则阳》"}], "words": [{"w": "惝怳、惝恍", "t": "惆怅,失意;伤感"}, {"w": "惝悢", "t": "惆怅悲哀"}, {"w": "惝惝", "t": "怅怅,惆怅自失的样子"}, {"w": "惝然", "t": "怅惘的样子;失意的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4987wx','惘','1','wǎng','忄','11','','[{"pinyin": "wǎng", "defs": [{"meaning": "(形声。从心;罔声。本义:失意) 同本义。", "cites": [{"t": "惘,怅然失志貌。", "b": "《正字通》"}, {"t": "恺惘然自失。", "b": "《世说新语·汰侈》"}], "words": [{"w": "惘惘", "t": "遑遽而无所适从;伤感;失意;迷迷糊糊"}, {"w": "惘惑", "t": "迷惑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4988wx','悸','1','jì','忄','11','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从心,季声。本义:害怕,心惊肉跳) 同本义。", "cites": [{"t": "悸,心动也。", "b": "《说文》"}, {"t": "惶悸兮失气。", "b": "《楚辞·悼乱》。注:“惧也。”"}, {"t": "忽魂悸以魄动。", "b": "李白《梦游天姥吟留别》"}, {"t": "夙行失道,望尘惊悸。", "b": "马中锡《中山狼传》"}], "words": [{"w": "心有余悸;悸震", "t": "震惊"}, {"w": "悸颤", "t": "怕得发抖"}, {"w": "悸心", "t": "心怀恐惧"}, {"w": "悸怖", "t": "恐惧"}, {"w": "悸恐", "t": "犹惶恐"}, {"w": "悸悚", "t": "恐惧"}, {"w": "悸罔", "t": "惊恐迷乱。"}]}, {"meaning": "心悸病。", "cites": [{"t": "使我至今病悸。", "b": "《汉书·田延年传》"}, {"t": "太师王舜自莽篡位后病悸,寝剧,死。", "b": "《汉书·王莽传中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4989wx','惆','1','chóu','忄','11','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从心,周声。本义:失意)。"}, {"meaning": "同本义。", "cites": [{"t": "惆,失意也。", "b": "《说文》"}, {"t": "惆然不嗛。", "b": "《荀子·礼论》。注:“怅然也。”"}, {"t": "心惆焉而自伤。", "b": "陆机《叹逝赋》"}], "words": [{"w": "惆然", "t": "失意的样子"}, {"w": "惆惋", "t": "伤感惋惜。"}]}]}]','jingmo-wenyan');
