INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4991wx','惇','1','dūn','忄','11','','[{"pinyin": "dūn", "defs": [{"meaning": "(形声。本义:敦厚,笃实)。"}, {"meaning": "同本义。", "cites": [{"t": "惇,厚也。", "b": "《说文》"}, {"t": "惇大成裕。", "b": "《书·洛诰》"}, {"t": "惇德允元。", "b": "《书·舜典》"}, {"t": "惇叙九族。", "b": "《书·皋陶谟》"}, {"t": "守学弥惇。", "b": "《国语·晋语四》"}, {"t": "惟戾以惇谨复终相位。", "b": "《汉书·公孙弘传》"}], "words": [{"w": "惇大", "t": "敦厚宽大"}, {"w": "惇谨", "t": "惇厚谨慎"}, {"w": "惇朴", "t": "仁厚朴实"}, {"w": "惇厚", "t": "笃实宽厚"}, {"w": "惇惇", "t": "仁厚的样子。"}]}, {"meaning": "诚信。", "cites": [{"t": "惇,信也。燕曰惇。", "b": "《方言·七》"}]}, {"meaning": "崇尚; 重视。", "cites": [{"t": "惇信明义,崇德报功。", "b": "《书·武成》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4992wx','惮','1','dá dàn','忄','11','','[{"pinyin": "dá", "defs": [{"meaning": "使惊恐。", "cites": [{"t": "则虽有疾风,亦弗之能惮矣。", "b": "《周礼》"}]}]}, {"pinyin": "dàn", "defs": [{"meaning": "(形声。从心,单声。本义:畏难,怕麻烦)。"}, {"meaning": "同本义。", "cites": [{"t": "岂敢惮行?", "b": "《诗·小雅·ń蛮》"}, {"t": "何惮于病?", "b": "《左传·僖公七年》"}, {"t": "过则勿惮改。", "b": "《论语·学而》"}, {"t": "何许子之不惮烦?", "b": "《孟子·滕文公上》"}, {"t": "小人而无忌惮也。", "b": "《礼记·中庸》"}, {"t": "以缚即炉火烧绝之,虽疮手勿惮。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "肆无忌惮;惮劳", "t": "害怕劳苦"}, {"w": "惮惮", "t": "忧惧惶恐"}, {"w": "惮烦", "t": "畏惧烦琐。"}]}, {"meaning": "憎恶;忌恨。", "cites": [{"t": "权内惮羽,外欲以为己功,笺与曹公,乞以讨羽自效。", "b": "《三国志·吴主传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4993wx','窕','1','tiǎo','穴','11','','[{"pinyin": "tiǎo", "defs": [{"meaning": "(形声。从穴,兆声。本义:深邃)。"}, {"meaning": "同本义。", "cites": [{"t": "窕,深肆也。", "b": "《说文》"}, {"t": "充盈大宇而不窕。", "b": "《荀子·赋》"}, {"t": "入小而不偪,处大而不窕。", "b": "《淮南子》"}], "words": [{"w": "窕邃", "t": "幽深的样子"}, {"w": "窕窕", "t": "幽深的样子。"}]}, {"meaning": "未充满;间隙。", "cites": [{"t": "七者布诸天下而不窕,内诸寻常之室而不塞。", "b": "《大戴礼记》"}]}, {"meaning": "细;小。", "cites": [{"t": "夫天子省风以作乐, 小者不窕。", "b": "《汉书》"}]}, {"meaning": "虚浮不实。", "cites": [{"t": "语言辨,听之说(悦),不度于义,谓之窕言。", "b": "《韩非子》"}]}, {"meaning": "美;美色。", "cites": [{"t": "不至于窕冶。", "b": "《荀子·礼论》"}, {"t": "窕美也。美状为窕。", "b": "《方言二》"}], "words": [{"w": "窕窈", "t": "窈窕;美貌"}, {"w": "窕儇", "t": "美貌,轻佻。"}]}, {"meaning": "淫;过分 。", "words": [{"w": "窕名", "t": "虚名"}, {"w": "窕言", "t": "虚假不实之言"}, {"w": "窕货", "t": "来路不正的货物。"}]}, {"meaning": "过剩的,多余的。", "cites": [{"t": "充盈大宇而不窕,入郄穴而不逼者与?", "b": "《荀子》"}]}, {"meaning": "优美、雅致和高贵的 。", "words": [{"w": "窈窕", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4994wx','谌','1','chén','讠','11','','[{"pinyin": "chén", "defs": [{"meaning": "相信。", "cites": [{"t": "谌,诚谛也。", "b": "《说文》"}, {"t": "天难谌斯。", "b": "《诗·大雅·大明》"}, {"t": "天难谌,命靡常。", "b": "《书·咸有一德》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4995wx','谏','1','jiàn','讠','11','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从言,柬声。本义:直言规劝)。"}, {"meaning": "同本义。", "cites": [{"t": "谏,证也。", "b": "《说文》"}, {"t": "谏者,正也。", "b": "《楚辞·七谏序》"}, {"t": "谏,犹正也。以道正人行。", "b": "周礼·司谏》注"}, {"t": "掌谏五恶。", "b": "《周礼·保氏》。注:“以礼义正之。”"}, {"t": "三谏不从。", "b": "《公羊传·庄公二十四年》"}, {"t": "宫之奇之为人也,懦而不能强谏。", "b": "《左传·僖公二年》"}, {"t": "保氏常谏王恶。", "b": "《周礼·地官》"}, {"t": "大臣强谏。", "b": "《战国策·赵策》"}, {"t": "扶苏以数谏。", "b": "《史记·陈涉世家》"}, {"t": "忠谏之路。", "b": "诸葛亮《出师表》"}, {"t": "不为拒谏。", "b": "宋·王安石《游褒禅山记》"}], "words": [{"w": "谏阻纳质", "t": "指周瑜直言规劝阻止孙权以其子给曹操为人质"}, {"w": "谏鼓", "t": "朝廷设置供人民进谏时击用的鼓。又名“朝鼓”。"}]}, {"meaning": "匡正;挽回。", "cites": [{"t": "悟已往之不谏,知来者之可追。实迷途其未远,觉今是而昨非。", "b": "晋·陶潜《归去来兮辞》"}]}, {"meaning": "离间。", "cites": [{"t": "郭开受谏,李牧就诛。", "b": "唐·皮日休《忧赋》"}]}, {"meaning": "谏官。", "cites": [{"t": "避人焚谏草,骑马欲鸡栖。", "b": "杜甫《晚出左掖》"}], "words": [{"w": "谏垣", "t": "谏官的衙署;指朝中大臣及幕僚百官"}, {"w": "谏草", "t": "谏官的奏稿"}, {"w": "谏院", "t": "谏官的衙署"}, {"w": "谏议大夫", "t": "古官名。简称“谏议”。掌管谏诤及议论。"}]}, {"meaning": "间谍。", "cites": [{"t": "设谏以纲独为,举错以观奸动。", "b": "《韩非子·八经》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4996wx','扈','1','hù','户','11','','[{"pinyin": "hù", "defs": [{"meaning": "(形声。从邑,户声。从“邑”,表示与城廓或行政区有关。本义:古国名。在今陕西户县)。"}, {"meaning": "同本义。", "cites": [{"t": "夏后同姓所封,与启战于甘者,在鄠有扈谷甘亭。", "b": "《说文》"}, {"t": "有扈。", "b": "《书·甘誓序》。释文:“国名。”"}, {"t": "夏有观扈。", "b": "《左传·昭公元年》"}]}, {"meaning": "侍从,养马的仆役。", "cites": [{"t": "厮役扈养。", "b": "《公羊传·宣公十二年》"}], "words": [{"w": "扈养", "t": "马夫、炊事等仆从人员"}, {"w": "扈隶", "t": "跟随亲王的臣隶。"}]}, {"meaning": "随从;护卫。后多指随侍帝王。", "cites": [{"t": "百官从驾,谓之扈从,或曰护之借字。", "b": "《封氏闻见记》"}], "words": [{"w": "扈行", "t": "随从皇帝出行"}, {"w": "扈侍", "t": "随侍帝王"}, {"w": "扈狩", "t": "随从帝王逃难的婉词"}, {"w": "扈游", "t": "随从皇帝出游。"}]}, {"meaning": "救护;爱护。", "cites": [{"t": "数枝花纇小,愁杀扈芳人。", "b": "唐·陆龟蒙《早春》"}]}, {"meaning": "止,制止。", "cites": [{"t": "扈民无淫者也。", "b": "《左传》"}]}, {"meaning": "广大。", "cites": [{"t": "以储与扈冶。", "b": "《淮南子·要略》"}, {"t": "尔母扈扈尔。", "b": "《礼记·檀弓》"}], "words": [{"w": "扈扈", "t": "广而大"}, {"w": "扈冶", "t": "广大"}, {"w": "扈楼", "t": "大楼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4997wx','皲','1','jūn','皮','11','','[{"pinyin": "jūn", "defs": [{"meaning": "手足的皮肤冻裂", "words": [{"w": "皲瘃", "t": "皮肤受严寒而坼裂成疮。即冻疮"}, {"w": "皲坼", "t": "皲裂"}, {"w": "皲皱", "t": "粗糙开裂"}, {"w": "皲手茧足", "t": "手皲裂,足生茧"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4998wx','谑','1','xuè','讠','11','','[{"pinyin": "xuè", "defs": [{"meaning": "(形声。从言,虐声。本义:尽兴地游乐)。"}, {"meaning": "同本义。", "cites": [{"t": "谑,戏也。", "b": "《说文》"}, {"t": "谑,浪笑。", "b": "《尔雅》"}, {"t": "善戏谑兮,不为虐兮。", "b": "《诗·卫风·淇奥》"}, {"t": "此乃今之轻薄子,好作谑词,嘲乡里之类,为一乡所疾苦者。", "b": "《朱子全书》"}, {"t": "陈王昔时宴平乐,斗酒十千姿欢谑。", "b": "李白《将进酒》"}], "words": [{"w": "谑亲", "t": "闹新房"}, {"w": "姿欢谑", "t": "尽情地欢乐游玩。"}]}, {"meaning": "取笑作乐。", "cites": [{"t": "伊其相谑。", "b": "《汉书·地理志》。注:“戏言也。”"}, {"t": "调笑来相谑。", "b": "李白《陌上桑》"}, {"t": "嗜酒善谑,而好为诗。", "b": "《宋史》"}], "words": [{"w": "谑戏", "t": "调笑戏弄"}, {"w": "谑剧", "t": "调笑嬉戏"}, {"w": "谑浪", "t": "戏谑放荡"}, {"w": "谑嘲", "t": "戏谑嘲弄"}, {"w": "谑弄", "t": "戏谑嘲弄"}, {"w": "谑词", "t": "开玩笑的话。"}]}, {"meaning": "喜乐。", "cites": [{"t": "无然谑谑。", "b": "《诗·大雅·板》。传:“喜乐貌。”"}, {"t": "陈王昔时宴平乐,斗酒十千恣欢谑。", "b": "唐·李白《将进酒》"}], "words": [{"w": "谑谑", "t": "喜乐的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('4999wx','裆','1','dāng','衤','11','','[{"pinyin": "dāng", "defs": [{"meaning": "(形声。从衣,当声。本义:两裤腿相连的地方)。"}, {"meaning": "同本义。"}, {"meaning": "两条裤腿缝相接触的接口部分。", "cites": [{"t": "裆,穷袴也。今以袴有当而旁开者为裆。", "b": "《六书故》"}, {"t": "独不见群虱之处禈中,…动不敢出禈(裤子)裆。", "b": "阮籍《大人先生传》"}], "words": [{"w": "横裆;直裆;裤裆", "t": ""}]}, {"meaning": "坎肩儿,背心 。"}, {"meaning": "裤。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5000wx','袷','1','jiá jié qiā','衤','11','','[{"pinyin": "jiá", "defs": [{"meaning": "双层的(衣被等)。", "cites": [{"t": "御袷衣。--《文选·潘岳·秋兴赋》", "b": ""}, {"t": "怅卧新春白袷衣，白门寥落意多违。-- 唐·李商隐《春雨》", "b": ""}]}, {"meaning": "又如夹衣(双层的衣服。指有里、有面的衣服)；夹衫(双层的衣服)；夹布子(月经带)；夹被摩疼(喻指没有抓住要害)。"}, {"meaning": "夹裙。", "cites": [{"t": "著我绣夹裙。--《玉台新咏·古诗为焦仲卿妻作》", "b": ""}]}, {"meaning": "朝成绣夹裙。"}]}, {"pinyin": "jié", "defs": [{"meaning": "古代交叠于胸前的衣领。"}]}, {"pinyin": "qiā", "defs": [{"meaning": "无领大衣；中国维吾尔和塔吉克等民族的对襟长袍。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5001wx','裉','1','kèn','衤','11','','[{"pinyin": "kèn", "defs": [{"meaning": "上衣在腋下的接缝部分。", "cites": [{"t": "身上穿着缕金百蝶穿花大红洋窄裉袄。", "b": "《红楼梦》"}], "words": [{"w": "抬裉", "t": "上衣从肩头到腋下的尺寸"}, {"w": "煞裉", "t": "把裉缝上。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5002wx','谒','1','yè','讠','11','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。从言,曷(hé)声。本义:禀告,陈述)。"}, {"meaning": "同本义。", "cites": [{"t": "谒,白也。", "b": "《说文》"}, {"t": "谒,告也。", "b": "《尔雅》"}, {"t": "摈者谒诸天子。", "b": "《仪礼·觐礼》"}, {"t": "能典谒矣。", "b": "《礼记·曲礼》"}, {"t": "惟我郑国之有请谒焉。", "b": "《左传·隐公十一年》"}, {"t": "不谒而归。", "b": "《国语·晋语》"}, {"t": "臣请谒其故。", "b": "《战国策》"}], "words": [{"w": "谒急", "t": "告急"}, {"w": "谒言", "t": "进谏。"}]}, {"meaning": "告发;检举。", "cites": [{"t": "伍、官、连、县而邻,谒过赏,失过诛。", "b": "《韩非子·八经》"}], "words": [{"w": "谒过", "t": "揭发罪过。"}]}, {"meaning": "请;请求。", "cites": [{"t": "微太子言,臣愿得谒之。", "b": "《战国策·燕策》"}], "words": [{"w": "谒告", "t": "告假"}, {"w": "谒归", "t": "告假归里"}, {"w": "谒浆", "t": "乞求茶水。"}]}, {"meaning": "进见。", "cites": [{"t": "谒,访也。", "b": "《增韵》"}, {"t": "越日偃师谒见王。", "b": "《列子·汤问》"}, {"t": "父利其然也,日扳仲永环谒于邑人,不使学。(环谒,四处拜访)。", "b": "宋·王安石《伤仲永》"}, {"t": "乡人子谒余。", "b": "明·宋濂《送东阳马生序》"}, {"t": "谒伊藤氏。", "b": "清·梁启超《谭嗣同传》"}, {"t": "台谒当以属礼。", "b": "《明史》"}], "words": [{"w": "谒索", "t": "探望;借拜访之机索取财物"}, {"w": "谒帝台", "t": "进见皇帝或权贵。喻指求官显达"}, {"w": "谒选", "t": "官员到吏部等候选派"}, {"w": "谒刺", "t": "谒见人时所用的名刺"}, {"w": "谒禁", "t": "禁止人来进见"}, {"w": "谒托", "t": "投见求托。"}]}, {"meaning": "到某人的陵墓表示敬意。", "cites": [{"t": "城外有新坟者,即往拜扫。禁中亦出车马诣道者院谒坟。", "b": "宋·孟元老《东京梦华录》"}], "words": [{"w": "谒坟", "t": "拜谒坟墓"}, {"w": "谒圣、簪花", "t": "考取秀才后,由教官率领到孔庙行礼,叫谒圣。新秀才披红,头插两朵金花,叫簪花"}, {"w": "谒庙", "t": "进庙拜神。"}]}, {"meaning": "名剌。", "cites": [{"t": "怀谒诣辞。", "b": "宋·刘攽《贺知府某侍读启》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5003wx','谔','1','è','讠','11','','[{"pinyin": "è", "defs": [{"meaning": "(形声。从言,咢声。本义:正直的话)同本义。", "cites": [{"t": "咢,讼也。字亦作諤。", "b": "《说文》"}, {"t": "咢咢黄发。", "b": "《汉书·韦贤传》。注:“直言也。”"}, {"t": "臣无蹇谔之节,而有狂瞽之言,不能以尸伏谏,偷生苟活,诚惭圣朝。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5004wx','谕','1','yù','讠','11','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从言,俞声。本义:旧时上告下的通称。也指告诉)。"}, {"meaning": "同本义。", "cites": [{"t": "谕,告也。", "b": "《说文》"}, {"t": "以谕九税之利。", "b": "《周礼·掌交》"}, {"t": "讶士掌四方之狱讼,谕罪刑于邦国。", "b": "《周礼·秋官》"}], "words": [{"w": "谕葬", "t": "圣上发旨的葬仪"}, {"w": "面谕;谕知", "t": "告谕而使人知晓。"}]}, {"meaning": "明白、懂得。", "cites": [{"t": "谕,晓也。", "b": "《广雅》"}, {"t": "教之以事而谕诸德者也。", "b": "《周礼·师氏》注"}, {"t": "其言多当矣,而未谕也。", "b": "《荀子·儒效》"}, {"t": "又不能谕其内志。", "b": "《汉书·文帝纪》"}, {"t": "先生坐!何至于此!寡人谕矣。", "b": "《战国策·魏策》"}]}, {"meaning": "旧时用指上对下的文告、指示。", "cites": [{"t": "这可得便来谕,着魏子英拿沙龙。", "b": "《小五义》"}], "words": [{"w": "来谕;手谕;赐谕", "t": ""}]}, {"meaning": "告诫的言辞。"}, {"meaning": "比喻。", "cites": [{"t": "请以市谕,市朝则满,夕则虚。", "b": "《战国策》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5005wx','谖','1','xuān','讠','11','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从言,爰(yuán)声。本义:欺诈,欺骗)。"}, {"meaning": "同本义。", "cites": [{"t": "谖,诈也。", "b": "《说文》"}, {"t": "谖,欺也。", "b": "《广雅》"}, {"t": "则上诈缓而弃其信。", "b": "《汉书·艺文志》"}, {"t": "虚造诈谖之策。", "b": "《汉书·息夫躬传》"}], "words": [{"w": "谖言", "t": "华而不实的言辞。"}]}, {"meaning": "忘记,忘却,遗忘。", "cites": [{"t": "有匪君子,终不可谖兮。", "b": "《诗·卫风·淇奥》"}, {"t": "焉得谖草,言树之背。", "b": "《诗·卫风·伯兮》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5006wx','谗','1','chán','讠','11','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从言,毚(chán)声。本义:说别人的坏话) 同本义。", "cites": [{"t": "谗,谮也。", "b": "《说文》"}, {"t": "谗,诞也。", "b": "《韩诗外传》"}, {"t": "谗口嚣嚣。", "b": "《诗·小雅·十月之交》"}, {"t": "败言为谗。", "b": "《左传·昭公五年》"}, {"t": "谗鼎之铭。", "b": "《左传·昭公三年》。服注:“疾谗之鼎。”"}, {"t": "取彼谗人。", "b": "《后汉书·马援传》"}, {"t": "屈平属草稿未定,上官大夫见而欲夺之,屈平不与。因谗之曰…", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "谗谤", "t": "诋毁,诽谤"}, {"w": "谗言冷语", "t": "毁谤、讥刺的冷言冷语。"}]}, {"meaning": "说别人坏话的人。", "cites": [{"t": "谗与佞,俱小人也。", "b": "《论衡·答佞》"}], "words": [{"w": "谗人", "t": "喜欢恶意攻击、陷害贤良的人"}, {"w": "谗夫", "t": "谗害他人的人。"}]}, {"meaning": "谗言,陷害别人的坏话。", "cites": [{"t": "乱之又生,君子信谗。", "b": "《诗·小雅·巧言》"}, {"t": "采苓,刺晋献公也。献公好听谗焉。", "b": "《诗·唐风·采苓序》"}, {"t": "安帝信谗,无辜死者多。", "b": "《后汉书·五行志》"}]}, {"meaning": "又。", "cites": [{"t": "去国怀乡,忧谗畏讥。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "洎李牧以谗诛。", "b": "宋·苏洵《六国论》"}], "words": [{"w": "谗箭", "t": "谗言伤人像箭那样,说它既锐利又难以防备"}, {"w": "谗阅", "t": "互相毁谤、争斗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5007wx','谙','1','ān','讠','11','','[{"pinyin": "ān", "defs": [{"meaning": "(形声。从言,音声。本义:熟悉)。"}, {"meaning": "同本义。", "cites": [{"t": "谙,悉也。", "b": "《说文》"}, {"t": "江南好,风景旧曾谙。", "b": "白居易《忆江南》"}, {"t": "协久在中朝,谙练旧事。", "b": "《晋书·刁协传》"}, {"t": "故谙事识体者,善权轻重。", "b": "《晋书·刑法志》"}, {"t": "未谙姑食性,先遣小姑尝。", "b": "王建《淅嫁娘》。"}], "words": [{"w": "谙悉", "t": "熟知"}, {"w": "谙练", "t": "熟知,有经验。"}]}, {"meaning": "熟记。", "cites": [{"t": "其陵树株蘖,皆谙其数。", "b": "《后汉书·虞延传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5008wx','谛','1','dì','讠','11','','[{"pinyin": "dì", "defs": [{"meaning": "(形声。从言,帝声。本义:细察;详审)。"}, {"meaning": "同本义。", "cites": [{"t": "谛,审也。从言,帝声,字亦作諦。", "b": "《说文》"}, {"t": "军当远出,卿诸人好谛其事。", "b": "《三国志》"}]}, {"meaning": "明白;了解。", "cites": [{"t": "或有未谛,循循诱之。", "b": "鲁迅《且介亭杂文》"}]}, {"meaning": "详细,仔细。", "cites": [{"t": "当时乍见惊心目,凝视谛听殊未足。", "b": "白居易《霓裳羽衣舞歌》"}, {"t": "审谛之,短小,黑赤色,顿非前物。", "b": "《聊斋志异·促织》"}], "words": [{"w": "谛听", "t": "仔细地听。"}]}, {"meaning": "佛教名词。谓真实无谬的道理。", "cites": [{"t": "实义是谛义、真义、如义、不颠倒义、无虚诳义。", "b": "《大毗婆沙论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5009wx','谝','1','piǎn','讠','11','','[{"pinyin": "piǎn", "defs": [{"meaning": "花言巧语。", "cites": [{"t": "谝,便巧言也。", "b": "《说文》"}, {"t": "惟截截善谝言。", "b": "《书·泰誓》"}, {"t": "友谝佞。", "b": "《论语》"}]}, {"meaning": "欺骗;诈骗。", "cites": [{"t": "指山盟是谝,则不如剪发然香竟儿远。", "b": "元·汤氏《赠王观音奴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5010wx','逯','1','lù','辶','11','','[{"pinyin": "lù", "defs": [{"meaning": "随意行走。", "cites": [{"t": "浑然而往,逯然而来。", "b": "《淮南子》"}]}, {"meaning": "群众。", "cites": [{"t": "冲心幽被,奖逯无偏。", "b": "南朝齐·王僧令《皇太子释奠会》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5011wx','郿','1','méi','阝','11','','[{"pinyin": "méi", "defs": [{"meaning": "古地名 。春秋周邑。在今陕西省眉县东北。也作眉县。", "cites": [{"t": "郿,右扶风县。", "b": "《说文》"}, {"t": "王饯于郿。", "b": "《诗·大雅·崧高》"}]}, {"meaning": "春秋鲁邑 。在今山东省东平县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5012wx','隈','1','wēi','阝','11','','[{"pinyin": "wēi", "defs": [{"meaning": "(形声。从阜(fù),畏声。本义:山或水弯曲的地方)。"}, {"meaning": "水流弯曲处。", "cites": [{"t": "田者不侵畔,渔者不侵隈。", "b": "《淮南子》。高诱注:“隈,曲深处,鱼所聚也。”"}]}, {"meaning": "水涯。", "cites": [{"t": "凭高望之阳隈,体川陆之污隆。", "b": "《文选·潘岳·西征赋》。李善注:“隈,崖也。”"}]}, {"meaning": "泛指弯曲处。"}, {"meaning": "曲深处。", "cites": [{"t": "奎蹏曲隈,乳间股脚,自以为安室利处。", "b": "《庄子·徐无鬼》"}]}, {"meaning": "弓把两边的弯曲处。", "cites": [{"t": "大射正执弓,以袂顺左右隈,上再下壹,右执弣,左执箫,以授公,公亲揉之。", "b": "《仪礼》"}]}, {"meaning": "指角或角落。", "cites": [{"t": "考之四隈。", "b": "左思《魏都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5013wx','粜','1','tiào','米','11','','[{"pinyin": "tiào", "defs": [{"meaning": "(会意兼形声。从出,从糶,糶亦声。糶(tiào),谷。本义:卖出谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "粜,出谷也。", "b": "《说文》"}, {"t": "物踊腾粜。", "b": "《史记·平淮书》"}, {"t": "贩谷粜千钟。", "b": "《史记·货殖传》"}, {"t": "二月卖新丝,五月粜新谷。", "b": "唐·聂夷中《咏田家》"}]}, {"meaning": "泛指出卖。", "cites": [{"t": "想那粜风月的女娘,似饥狼饿狼。", "b": "《雍熙乐府》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5014wx','隍','1','huáng','阝','11','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从阜(fù),表示与地形地势的高低上下有关,皇声。本义:没有水的护城壕) 同本义。", "cites": [{"t": "隍,城池也,有水曰池,无水曰隍。", "b": "《说文》"}, {"t": "城复干隍。", "b": "《易·泰》"}], "words": [{"w": "隍陴", "t": "城壕与女墙"}, {"w": "隍阱", "t": "城壕、陷坑"}, {"w": "隍堑", "t": "城壕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5015wx','隗','1','kuí wěi','阝','11','','[{"pinyin": "kuí", "defs": [{"meaning": "姓。"}]}, {"pinyin": "wěi", "defs": [{"meaning": "高峻的样子。", "cites": [{"t": "隗,高也。", "b": "《玉篇》"}]}, {"meaning": "古国名 。地在今湖北省秭归县东。", "cites": [{"t": "楚人灭隗。", "b": "《公羊传》"}]}, {"meaning": "倒塌。", "cites": [{"t": "有客乘之,隗若山颓。", "b": "《酒赞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5016wx','婧','1','jìng','女','11','','[{"pinyin": "jìng", "defs": [{"meaning": "苗条美好。", "cites": [{"t": "婧,妍婧也。", "b": "《思玄赋》注引说文"}, {"t": "舒妙婧之纤腰兮,扬杂错之袿徽。", "b": "《文选·张衡·思玄赋》"}]}, {"meaning": "女子贞洁。", "cites": [{"t": "婧,女贞也。", "b": "《集韵》"}]}, {"meaning": "女子人名用字。", "cites": [{"t": "婧,齐相管仲妾也。", "b": "《列女传》"}]}]}]','jingmo-wenyan');
