('5019wx','娼','1','chāng','女','11','','[{"pinyin": "chāng", "defs": [{"meaning": "指从事歌舞的女艺人。娼,本作倡", "words": [{"w": "娼女", "t": "歌舞女艺人"}, {"w": "娼优", "t": "从事歌舞的艺人"}]}, {"meaning": "娼妓", "words": [{"w": "私娼", "t": ""}, {"w": "土娼", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5020wx','婢','1','bì','女','11','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从女,卑声。本义:旧社会里被迫受剥削阶级役使的女子)。"}, {"meaning": "古代罪人的眷属没入宫为婢,后通称受役使的女子。", "cites": [{"t": "婢,女之卑者也。", "b": "《说文》"}, {"t": "使婢子侍执巾栉。", "b": "《左传·僖公二十二年》。注:“婢子,妇人之卑称也。”"}, {"t": "使吾二婢子夹我。", "b": "《礼记·檀弓》。注:“妾也。”"}, {"t": "父母有婢子。", "b": "《礼记·内则》。注:“所通贱人之子。”"}, {"t": "先大母婢也。", "b": "明·归有光《项脊轩志》"}, {"t": "为婢仆所惑。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "婢婿", "t": "与婢女私通的人"}, {"w": "婢妾", "t": "妾与使女。"}]}, {"meaning": "古代妇女的谦称。", "cites": [{"t": "自世妇以下自称曰婢子。", "b": "《礼记·曲礼》。注:“婢之言卑也。”"}]}]}]','jingmo-wenyan');
