('5024wx','翌','1','yì','羽','11','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从羽,立声。本义:明(天,年)) 同本义。", "cites": [{"t": "若翌日癸巳。", "b": "《汉书》"}], "words": [{"w": "翌年", "t": "明年"}, {"w": "翌晨", "t": "次日早晨。"}]}, {"meaning": "辅佐,从旁给予帮助。", "cites": [{"t": "三辅九翌,为世亿龄。", "b": "清·廖文锦《路史节读》"}]}, {"meaning": "翅膀。", "cites": [{"t": "噑堂陛,布翌伏地而死。", "b": "《晏子春秋》。于省吾证:“古昱日及羽翼字本均作翌,此云‘布翌’,乃古字之仅存者。”"}], "words": [{"w": "翌室", "t": "犹翼室"}, {"w": "翌翌", "t": "翼翼。恭敬的样子"}, {"w": "翌戴", "t": "翼戴。辅佐拥戴。"}]}]}]','jingmo-wenyan');
