INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5029wx','绮','1','qǐ','纟','11','','[{"pinyin": "qǐ", "defs": [{"meaning": "(形声。从糸(mì),奇声。糸,细丝,与丝织品有关。本义:细绫,有花纹的丝织品)。"}, {"meaning": "同本义。", "cites": [{"t": "绮,文缯也。", "b": "《说文》"}, {"t": "织作冰纨绮绣纯丽之物。", "b": "《汉书·地理志》"}, {"t": "在于绮襦纨绔之间。", "b": "《汉书·序传》"}, {"t": "缃绮为下裙。", "b": "《乐府诗集·陌上桑》"}]}, {"meaning": "又。", "cites": [{"t": "紫绮为上襦。", "b": ""}, {"t": "遍身罗绮者。", "b": "宋·张俞《蚕妇》"}], "words": [{"w": "绮縠", "t": "有花纹的丝质衣裳"}, {"w": "绮缟", "t": "文绘和细绘,为上等的丝织衣料"}, {"w": "绮绘", "t": "有美丽文彩的丝织品"}, {"w": "绮绣", "t": "彩色丝织品。"}]}, {"meaning": "光彩。", "cites": [{"t": "流绮星连。", "b": "《七命》。注:“光色也。”"}], "words": [{"w": "绮合", "t": "各色锦绮会合在一起。比喻文采灿烂"}, {"w": "绮云", "t": "美丽如绮的彩云。"}]}, {"meaning": "华丽;美丽。", "cites": [{"t": "绮室。", "b": "《后汉书·宦者传》。注:“室之丽者。”"}], "words": [{"w": "绮楼娃", "t": "画楼上的美女"}, {"w": "绮文", "t": "彩纹,色泽美丽的花纹"}, {"w": "绮户", "t": "彩饰华丽的门户。也喻富贵之家"}, {"w": "绮札", "t": "文辞华美的书信"}, {"w": "绮衣", "t": "华丽的衣服。"}]}, {"meaning": "精妙;精美。", "cites": [{"t": "新诗绮语亦安用?相与变灭随东风。", "b": "苏轼《登州海市》"}], "words": [{"w": ";骑语", "t": "美妙的语句"}, {"w": "绮筵", "t": "丰盛精美的筵席"}, {"w": "绮席", "t": "绮筵。"}]}, {"meaning": "纵横交错。", "cites": [{"t": "疆场绮分。", "b": "班固《东都赋》"}], "words": [{"w": "绮陌", "t": "纵横交错的道路。"}]}]}]','jingmo-wenyan');
