INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5033wx','绲','1','gǔn','纟','11','','[{"pinyin": "gǔn", "defs": [{"meaning": "织成的带子。", "cites": [{"t": "绲,织带也。从糸,昆声。", "b": "《说文》"}, {"t": "竹闭绲縢。", "b": "《诗·秦风·小戎》。传:“绳也。”"}, {"t": "绲带。", "b": "《后汉书·南匈奴传》。注:“织成布也。”"}]}, {"meaning": ""}, {"meaning": "帝王及公侯的礼服。", "cites": [{"t": "当穷台绲,松侨协轨。", "b": "汉《领校巴郡太守樊敏碑》"}]}, {"meaning": "衮职,三公之职。", "cites": [{"t": "维时假阶,将受绲职。", "b": "汉《卫尉卿方碑》"}]}, {"meaning": "(kūn)。后代子孙。", "cites": [{"t": "于是刊碑,以示后绲。", "b": "汉《绥民校尉熊君碑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5034wx','骓','1','zhuī','马','11','','[{"pinyin": "zhuī", "defs": [{"meaning": "毛色苍白相杂的马。", "cites": [{"t": "骓,马苍黑杂毛也。从马,隹声。", "b": "《说文》"}, {"t": "苍白杂毛骓。", "b": "《尔雅·释畜》"}, {"t": "有骓有駓。", "b": "《诗·鲁颂·駉》"}, {"t": "三青马三骓。", "b": "《山海经·大荒东经》"}, {"t": "骏马名骓。", "b": "《汉书·项籍传》"}, {"t": "力拔山兮气盖世,时不利兮骓不逝。", "b": "《史记·项羽本纪》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5035wx','绶','1','shòu','纟','11','','[{"pinyin": "shòu", "defs": [{"meaning": "(形声。从糸(mì),受声。本义:丝带。古代用以系佩玉、官印等。绶带的颜色常用以标志不同的身分与等级) 同本义。", "cites": [{"t": "绶,绂维也。", "b": "《说文》"}, {"t": "绂谓之绶。", "b": "《小尔雅》。按,绶者,组带之大名。"}, {"t": "掌帷幕幄帟绶之事。", "b": "《周礼·幕人》。司农注:“组绶所以系帷也。”"}, {"t": "天子佩白玉而玄组绶。", "b": "《礼记·玉藻》"}, {"t": "古者君佩玉,尊卑有序。及秦,以采组连结于繸,谓之绶。", "b": "《董巴舆服志》"}, {"t": "守邸与共食,食且饱,少见其绶。", "b": "《汉书·朱买臣传》"}, {"t": "怀黄金之印,结紫绶于要。", "b": "《史记·范睢蔡泽列传》"}], "words": [{"w": "绶带", "t": "系印信用的佩带"}, {"w": "绶笥", "t": "盛印绶的箱箧"}, {"w": "绶囊", "t": "古代官吏系在腰间盛绶的口袋"}, {"w": "绶花", "t": "花名。蔓生如绶,故名。"}]}]}]','jingmo-wenyan');
