('5036wx','绺','1','liǔ','纟','11','','[{"pinyin": "liǔ", "defs": [{"meaning": "丝缕编成的线。", "cites": [{"t": "上有仙人长命绺,中看玉女迎欢绣。", "b": "唐·沈佺期《七夕曝衣篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5037wx','绻','1','quǎn','纟','11','','[{"pinyin": "quǎn", "defs": [{"meaning": "(形声。从糸,卷声。古作“卷”。本义:屈曲)。"}, {"meaning": "收缩。", "cites": [{"t": "兵横行天下而无所绻,威服四方而无所诎。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5038wx','绾','1','wǎn','纟','11','','[{"pinyin": "wǎn", "defs": [{"meaning": "(形声。从糸(mì),官声。本义:系)。"}, {"meaning": "盘绕,系结。", "cites": [{"t": "范进一面自绾了头发,一面向郎中借了一盆水洗洗脸。", "b": "《儒林外史》"}], "words": [{"w": "绾合", "t": "结合,系在一起"}, {"w": "绾发", "t": "束发,结发。比喻少年"}, {"w": "绾髻", "t": "束发编结为髻"}, {"w": "绾角儿", "t": "古时孩童束发为两髻,形状如角,因以借指童年"}, {"w": "绾束", "t": "缠缚"}, {"w": "绾约", "t": "绾束,盘绕成结。"}]}, {"meaning": "系念;挂念。", "cites": [{"t": "长安陌上无穷树,唯有垂杨绾别离。", "b": "唐·刘禹锡《杨柳枝词九首》"}]}, {"meaning": "总管。", "cites": [{"t": "奉阳君专权擅势,蔽欺先王,独擅绾事。", "b": "《史记》"}]}, {"meaning": "贯通;联系。", "cites": [{"t": "北邻乌桓、夫余,东绾秽貉、朝鲜、真番之利。", "b": "《史记》"}]}, {"meaning": "将物件穿上洞挂起来。", "cites": [{"t": "湘云便取了诗题,用针绾在墙上。", "b": "《红楼梦》"}]}, {"meaning": "发髻儿或花结儿。", "cites": [{"t": "一串歌珠清润,绾结玉连环。", "b": "宋·张炎《甘州》"}]}, {"meaning": "绛色;浅绛色。", "cites": [{"t": "绾,恶也,绛也。", "b": "《说文》。段玉裁改为“恶降也”。注曰:“谓绛色之恶者也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5039wx','骖','1','cān','马','11','','[{"pinyin": "cān", "defs": [{"meaning": "(形声。从马,参声。本义:独辕车所驾的三匹马)。"}, {"meaning": "同本义。", "cites": [{"t": "骖,驾三马也。", "b": "《说文》"}, {"t": "载骖载驷。", "b": "《诗·小雅·采菽》"}], "words": [{"w": "骖驾", "t": "三匹马驾的车子。"}]}, {"meaning": "驾车时在两边的马。", "cites": [{"t": "两骖如舞。", "b": "《诗·郑风·大叔于田》"}, {"t": "两骖列,两服入厩。", "b": "《荀子·哀公》"}, {"t": "左骖殪兮右刃伤。", "b": "《楚辞·九歌·国殇》"}, {"t": "停骖遥望独徘徊。", "b": "《三国演义》"}], "words": [{"w": "骖服", "t": "驾车的马匹。在两旁的称骖马,在中间驾车辕的称服马"}, {"w": "骖靳", "t": "比喻先后相随。"}]}, {"meaning": "乘。驾驭。", "cites": [{"t": "而使职骖乘。", "b": "《左传·文公十八年》。注:“陪乘也。”"}], "words": [{"w": "骖仆", "t": "陪乘之人和仆从。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5040wx','缁','1','zī','纟','11','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从糸(mì),甾(zī)声。糸,细丝,可以染上各种颜色。本义:帛黑色) 同本义。", "cites": [{"t": "缁,帛黑色也。", "b": "《说文》"}, {"t": "缁衣之宜兮。", "b": "《诗·郑风·缁衣》"}, {"t": "天雨,解素衣,衣缁衣而反。", "b": "《韩非子·说林下》"}, {"t": "素衣虽成缁,不为京路尘。", "b": "陆游《自小云顶上云顶寺》"}], "words": [{"w": "缁布", "t": "黑色的布帛"}, {"w": "缁衣", "t": "本为古代用黑色的布帛做的朝服,后借以泛称黑色衣服;僧尼所穿青黑色的衣服"}, {"w": "缁林", "t": "僧人聚集之处。缁,指僧人穿的黑色衣服。"}]}, {"meaning": "僧侣。", "cites": [{"t": "游食缁黄,往来寄宿。", "b": "《聊斋志异》"}], "words": [{"w": "缁锡", "t": "僧人"}, {"w": "缁子", "t": "和尚"}, {"w": "缁林", "t": "僧界,僧众"}, {"w": "缁徒", "t": "僧侣。"}]}, {"meaning": "黑色僧服。亦指僧侣或作僧侣。", "cites": [{"t": "自此更姓改名,削发披缁,去了。", "b": "《儒林外史》"}], "words": [{"w": "缁服", "t": "僧服"}, {"w": "缁衲", "t": "僧衣。借指僧侣"}, {"w": "缁锡", "t": "僧衣锡杖。僧人所用。"}]}]}]','jingmo-wenyan');
