INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5043wx','琵','1','pí','比','12','','[{"pinyin": "pí", "defs": [{"meaning": "有四根弦的弹拨乐器，下部椭圆形，上部有长柄，头部弯曲。中国的一种四弦乐器,弹奏如吉他,其主要部分大如诗琴,颈部有琴柱12个以上,伸入主体部分的琵琶,是在西汉\\"裁筝筑\\"的基础上逐步发展起来的。它从西汉试制,历东汉、魏晋、至隋唐,基本定型。它在汉末魏初始获\\"枇杷\\"名。魏晋时,因\\"枇杷\\"二字音,改名\\"琵琶\\"。"}, {"meaning": "诗篇名。", "cites": [{"t": "为君翻作《琵琶行》。--唐·白居易《琵琶行(并序)》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5044wx','琶','1','pá','王','12','','[{"pinyin": "pá", "defs": [{"meaning": "(形声。《说文新附》:“琵琶也。”)——见“琵琶”(pípa)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5045wx','琪','1','qí','王','12','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从玉,其声。本义:美玉的一种) 同本义。", "cites": [{"t": "璂琪,玉属也。", "b": "《穆天子传》"}, {"t": "会五采玉璂。", "b": "《周礼·弁师》。注:“綦结也。皮弁之缝。每贯结五采玉十二以为饰。谓之綦。”"}], "words": [{"w": "琪块", "t": "美玉。比喻珍贵之物"}, {"w": "琪琚", "t": "玉佩。亦指玉佩相击声,比喻美妙的言辞"}, {"w": "琪花", "t": "仙境中玉树之花;莹洁如玉的花"}, {"w": "琪花瑶草", "t": "仙境中的花草,其美如玉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5046wx','瑛','1','yīng','王','12','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从玉,英声。本义:玉光)。"}, {"meaning": "同本义。", "cites": [{"t": "瑛,玉光也。", "b": "《说文》"}]}, {"meaning": "似玉的美石。", "cites": [{"t": "于惟懿主,瑛瑶其质。", "b": "曹植《平原懿公主诔》"}], "words": [{"w": "瑛琭", "t": "瑛瑜、瑛瑶。美玉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5047wx','琦','1','qí','王','12','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从玉,奇声。本义:美玉) 同本义。", "cites": [{"t": "沟浍之中,无宵朗之琦。", "b": "《抱朴子·博喻》"}], "words": [{"w": "琦玮", "t": "美玉名。"}]}, {"meaning": "非常美好。", "cites": [{"t": "琦赂宝货。", "b": "《后汉书·仲长统传》"}], "words": [{"w": "琦行", "t": "高尚的行为"}, {"w": "琦赂", "t": "珍贵的财物"}, {"w": "琦玩", "t": "珍奇玩赏物。"}]}, {"meaning": "奇异。", "cites": [{"t": "玩琦辞。", "b": "《荀子·非十二子》"}], "words": [{"w": "琦巧", "t": "奇巧;巧技"}, {"w": "琦珍", "t": "奇异的珍宝"}, {"w": "琦辞", "t": "奇异的言辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5048wx','琥','1','hǔ','王','12','','[{"pinyin": "hǔ", "defs": [{"meaning": "虎符。", "cites": [{"t": "琥,发兵瑞玉。", "b": "《说文》"}]}, {"meaning": "瑞玉,古代的一种形似老虎的礼器。"}]}]','jingmo-wenyan');
