('5049wx','琨','1','kūn','王','12','','[{"pinyin": "kūn", "defs": [{"meaning": "美玉。", "cites": [{"t": "琨,石之美者。从玉,昆声。", "b": "《说文》"}, {"t": "献环琨与琛缡兮,申厥好以玄黄。", "b": "汉·张衡《思玄赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5050wx','靓','1','jìng liàng','青','12','','[{"pinyin": "jìng", "defs": [{"meaning": "召见;邀请。也作“请”。", "cites": [{"t": "靓,召也。", "b": "《说文》"}, {"t": "靓,呼也。", "b": "《广雅》。按,史记、汉书多以请为之。"}]}, {"meaning": "妆饰艳丽。", "cites": [{"t": "靓妆刻蚀。", "b": "司马相如《上林赋》"}, {"t": "昭君丰容靓饰,光明汉宫。", "b": "《后汉书》"}]}, {"meaning": "淑静。", "cites": [{"t": "淡乎若深渊之靓。", "b": "《汉书·贾谊传》"}, {"t": "意态闲且靓,气若兰蕙芳。", "b": "元·贡师泰《拟古二首》"}]}, {"meaning": "幽静。", "cites": [{"t": "神眇眇兮密靓处,君不御兮谁为荣?", "b": "《汉书·外戚传下》"}, {"t": "澹虖若深渊之靓。", "b": "《汉书·贾谊传》"}, {"t": "稍暗暗而靓深。", "b": "扬雄《甘泉赋》"}]}]}, {"pinyin": "liàng", "defs": [{"meaning": "", "words": [{"w": "靓姐", "t": ""}]}]}]','jingmo-wenyan');
