('5051wx','琰','1','yǎn','王','12','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从玉,炎声。本义:美玉名) 同本义。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5052wx','琮','1','cóng','王','12','','[{"pinyin": "cóng", "defs": [{"meaning": "(形声。从玉,宗声。本义:瑞玉)同本义。", "cites": [{"t": "大琮尺二寸,射四寸。", "b": "《考工记·玉人》。按,琮形八角,径八寸,角各出二寸。”"}, {"t": "以黄琮礼地。", "b": "《周礼·大宗伯》。注:“琮八方,象地。”"}, {"t": "聘于夫人用璋,享用琮。", "b": "《仪礼·聘礼》"}], "words": [{"w": " 琮玺;琮璧", "t": "玉制礼器。亦指珍贵的物品"}, {"w": "琮璜", "t": "琮与璜,皆庙堂玉器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5053wx','琯','1','guǎn','王','12','','[{"pinyin": "guǎn", "defs": [{"meaning": "古乐器名。用玉制成,六孔,像笛。", "cites": [{"t": "琯,古者玉琯以玉。", "b": "《说文》"}, {"t": "西王母来献其白琯。", "b": "《大戴礼记·少间》注:“琯,所以候气。”"}, {"t": "朱丝玉柱罗象筵,飞琯促弦舞少年。", "b": "梁武帝《白紵辞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5054wx','琬','1','wǎn','王','12','','[{"pinyin": "wǎn", "defs": [{"meaning": "一种上端浑圆而无棱角的圭。", "cites": [{"t": "玉琬徒见传,交友义渐疏。", "b": "南朝·鲍照《拟古八首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5055wx','琛','1','chēn','王','12','','[{"pinyin": "chēn", "defs": [{"meaning": "(形声。从玉,罙声。本义:珍宝)。"}, {"meaning": "同本义。常作贡物。", "cites": [{"t": "琛,宝也。", "b": "《说文新附》"}, {"t": "来献其琛。", "b": "《诗·鲁颂·泮水》"}, {"t": "献琛执贽。", "b": "张衡《东京赋》"}, {"t": "其琛赂则琨瑶之阜。", "b": "左思《吴都赋》"}], "words": [{"w": "琛贡", "t": "珍宝贡品"}, {"w": "琛宝", "t": "珠宝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5056wx','琚','1','jū','王','12','','[{"pinyin": "jū", "defs": [{"meaning": "古人佩带的一种玉,系在珩和璜之间。", "cites": [{"t": "琚,琼琚。从玉,居声。", "b": "《说文》"}, {"t": "琚瑀以杂之。", "b": "《大戴礼记·保傅》"}, {"t": "投我以木瓜,报之以琼琚。", "b": "《诗·卫风·木瓜》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5057wx','辇','1','niǎn','车','12','','[{"pinyin": "niǎn", "defs": [{"meaning": "(会意。从车,两“夫”(男子)并行,拉车前进。本义:古时用人拉或推的车)。"}, {"meaning": "同本义。", "cites": [{"t": "輦,挽车也。", "b": "《说文》"}, {"t": "与其輂辇。", "b": "《周礼·乡师》。注:“人挽行。”"}, {"t": "我任我辇。", "b": "《诗·小雅·黍苗》"}, {"t": "以乘车辇其母。", "b": "《左传·庄公十二年》"}, {"t": "辇重如役。", "b": "《左传·襄公十年》"}, {"t": "恃辇而行。", "b": "《战国策·赵策》"}, {"t": "扶辇下除。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "辇车", "t": "古代用人挽拉的辎重车;古代宫中用的一种便车,多用人挽拉"}, {"w": "辇舆", "t": "用人拉车;人抬的车,即后世轿子"}, {"w": "辇夫", "t": "车夫"}, {"w": "辇道", "t": "车道。"}]}, {"meaning": "借指京城。", "cites": [{"t": "子弟生长京辇。", "b": "陈琳《为袁绍上书》"}], "words": [{"w": "辇洛", "t": "京洛。指京都"}, {"w": "辇毂", "t": "代指京城。"}]}, {"meaning": "拉车。", "cites": [{"t": "天子召诸侯,诸侯辇舆就马。", "b": "《荀子·大略》"}], "words": [{"w": "辇土", "t": "用手拉车运送泥土"}, {"w": "辇运", "t": "车运,拉车运输"}, {"w": "辇重", "t": "挽引重车。"}]}, {"meaning": "乘车。", "cites": [{"t": "王子皇孙,辞楼下殿,辇来于秦。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "辇从", "t": "同车的随从。"}]}, {"meaning": "载运;运送。", "cites": [{"t": "辇金输虏庭。", "b": "陆游《闻虏乱次前辈韵》"}], "words": [{"w": "辇送", "t": "运送"}, {"w": "辇致", "t": "送达"}, {"w": "辇运", "t": "运输。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5058wx','鼋','1','yuán','黽','12','','[{"pinyin": "yuán", "defs": [{"meaning": "动物名,亦称“绿团鱼”,俗称“癞头鼋” ,爬行纲,鳖科。吻突而短,长不及眼径的一半。脚上有较宽的蹼。", "cites": [{"t": "鱼鳖鼋鼍。", "b": "《墨子·公输》"}], "words": [{"w": "鼋鼎", "t": "烹鼋的鼎"}, {"w": "鼋鼍", "t": "大鼋与鼍龙"}, {"w": "鼋桥", "t": "以鼋鼍为桥梁。形容帝王出驾行列之盛大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5059wx','揳','1','xiē','扌','12','','[{"pinyin": "xiē", "defs": [{"meaning": "把楔子、钉子等锤打到物体里面。", "cites": [{"t": "要往墙上揳钉子,比往木头上揳个钉子花费的力气要大得多。", "b": "郭澄清《大刀记》"}], "words": [{"w": "往墙上揳个钉子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5060wx','堞','1','dié','土','12','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从土。葉(yè)声。本义:城墙上如齿状的矮墙) 同本义。", "cites": [{"t": "堞,城上女垣也。", "b": "《说文》。按,古城用土,加以砖墙,为之射墙也,亦谓之陴,或谓之陴倪。"}, {"t": "傅于堞。", "b": "《左传·襄公六年》"}], "words": [{"w": "雉堞;城堞", "t": ""}]}]}]','jingmo-wenyan');
