INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5062wx','揸','1','zhā','扌','12','','[{"pinyin": "zhā", "defs": [{"meaning": "用手指抓东西。", "cites": [{"t": "但其时国家制度未定,文官未免图私,征税增耗,问事罚赎,一味揸钱。", "b": "清·东鲁古狂生《醉醒石》"}], "words": [{"w": "揸钱", "t": "抓钱;捞钱。"}]}, {"meaning": "把手指伸张开。", "cites": [{"t": "李后恍惚之间,见黄贵妃站在面前,便怒从心上起,恶向胆边生,赶上前揸开五指,把黄贵妃一个巴掌。", "b": "明·周清源《西湖二集》"}], "words": [{"w": "揸沙", "t": "张开;伸直"}, {"w": "揸开五个指头", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5063wx','揠','1','yà','扌','12','','[{"pinyin": "yà", "defs": [{"meaning": "(形声。从手,匽(yán)声。本义:拔起)。"}, {"meaning": "同本义。", "cites": [{"t": "揠,拔也。", "b": "《说文》"}, {"t": "拔心曰揠。", "b": "《小尔雅·广物》"}, {"t": "宋人有闵其苗之不长而揠之者,芒芒然归。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "揠苗助长", "t": ""}]}, {"meaning": "提拔。", "cites": [{"t": "德与琼素不相下,一旦揠之在上,则必争。", "b": "《宋书·岳飞传》"}]}, {"meaning": "抓着马鞍。", "cites": [{"t": "杀得曹操盔斜发乱,发甲捶胸,揠鞍吐血。", "b": "《老残游记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5064wx','堙','1','yīn','土','12','','[{"pinyin": "yīn", "defs": [{"meaning": "(形声。从土,垔(yīn)声。《说文》本作“垔”,从土,西声。本义:堵塞)。"}, {"meaning": "同本义。", "cites": [{"t": "垔,塞也。", "b": "《说文》。字俗作堙,作陻。"}, {"t": "井堙木刊。", "b": "《左传·襄公二十五年》"}, {"t": "堕高堙庳。", "b": "《国语·周语》"}, {"t": "夷灶堙井。", "b": "《国语》"}], "words": [{"w": "堙圮", "t": "堵塞毁坏"}, {"w": "堙窒", "t": "堵塞"}, {"w": "堙绝", "t": "堵塞断绝"}, {"w": "堙塞", "t": "堵塞。"}]}, {"meaning": "泯灭;埋没。", "cites": [{"t": "绝后无主堙替隶圉。", "b": "《国语·周语下》。韦昭注:“堙,没也。”"}, {"t": "金玉本光莹,浮沙岂能堙。", "b": "宋·王安石《东方朔》"}], "words": [{"w": "堙灭", "t": "埋没"}, {"w": "堙昧", "t": "埋没不显。"}]}, {"meaning": "废置,败落。", "cites": [{"t": "不若堙穴伏。", "b": "《韩非子·八说》"}, {"t": "堙灭而不称者,不可胜数也。", "b": "《史记·司马相如列传》"}], "words": [{"w": "堙陵", "t": "废置,败落。"}]}, {"meaning": "为攻城而堆的土山。", "cites": [{"t": "地狭而人众者,则筑大堙以临之。", "b": "《尉缭子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5065wx','趄','1','jū qiè qie','走','12','','[{"pinyin": "jū", "defs": [{"meaning": "阻隔。", "cites": [{"t": "经匣…上用趄尘盝顶,陷顶开带,四角打卯。", "b": "《营造法式》"}]}]}, {"pinyin": "qiè", "defs": [{"meaning": "倾斜。", "cites": [{"t": "宋江已有八分酒,脚步趄了,只顾踏去。", "b": "《水浒全传》"}], "words": [{"w": "趄趄", "t": "侧身而行,恭敬趋奉貌"}, {"w": "趄趄趔趔", "t": "步履歪斜的样子。"}]}, {"meaning": "斜靠,身斜。", "cites": [{"t": "席上正喧哗,不道玉人低趄。", "b": "元·王实甫《西厢记》"}], "words": [{"w": "趄着身子", "t": ""}]}]}, {"pinyin": "qie", "defs": [{"meaning": "——见“趔趄”（lièqie）。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5066wx','揖','1','yī','扌','12','','[{"pinyin": "yī", "defs": [{"meaning": "(形声。从手,咠(qì)声。本义:拱手行礼)。"}, {"meaning": "同本义。", "cites": [{"t": "自家拜揖,愿求恩官高姓大名。", "b": "《水浒全传》"}], "words": [{"w": "揖客", "t": "长揖不拜之客;向客拱手为礼"}, {"w": "揖游", "t": "古代行礼时依礼仪进退俯仰。"}]}, {"meaning": "让出,逊主。", "cites": [{"t": "公惟国家之统,揖大福大恩,事事谦让,动而固辞。", "b": "《汉书》"}], "words": [{"w": "揖让", "t": "揖逊。宾主相见的礼仪;禅让。让位于贤"}, {"w": "揖盗开门", "t": "比喻接纳坏人,自取其祸。"}]}, {"meaning": "专一。", "cites": [{"t": "普天之下,搏心揖志。", "b": "《史记·秦始皇本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5067wx','颉','1','jié xié','页','12','','[{"pinyin": "jié", "defs": [{"meaning": "——“仓颉”(Cāngjié):上古人名,相传他创造中国文字。"}]}, {"pinyin": "xié", "defs": [{"meaning": "颈项僵直的。", "cites": [{"t": "颉,直项也。从頁,吉声。", "b": "《说文》"}, {"t": "王公大人有严志颉颃之行。", "b": "《淮南书》"}, {"t": "邹衍以颉亢而取世资。", "b": "《汉书·扬雄传》"}, {"t": "长短颉喔百疾。", "b": "《吕氏春秋》"}], "words": [{"w": "颉佷", "t": "强项凶狠。"}]}, {"meaning": "鸟飞而下。", "cites": [{"t": "燕燕于飞,颉之颃之。", "b": "《诗·邶风·燕燕》"}], "words": [{"w": "颉杭", "t": "上下飞动"}, {"w": "颉滑", "t": "错乱"}, {"w": "颉地颃空", "t": "借措建筑物的构件有的向下,有的向上。"}]}, {"meaning": "有花纹的缯。", "cites": [{"t": "男女椎髻,穿绿颉布短衫。", "b": "元·汪大渊《岛夷志略》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
