INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5070wx','耋','1','dié','耂','12','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从老,至声。本义:年老。古指七、八十岁的年纪,泛指老年) 同本义。", "cites": [{"t": "年八十曰耊。字亦作耋。", "b": "《说文》"}, {"t": "则大耋之嗟。", "b": "《易·离》。马注:“七十曰耋。”"}, {"t": "使率一二耋老而绥焉。", "b": "《公羊传·宣公十二年》"}, {"t": "耆耋好礼。", "b": "《礼记·射义》"}], "words": [{"w": "耋老", "t": "年老;老年人"}, {"w": "耋吏", "t": "老吏"}, {"w": "耋耄", "t": "高寿"}, {"w": "耋寿", "t": "指高寿的人;老人"}, {"w": "耋耄之年", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5071wx','揄','1','yú','扌','12','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从手,俞声。本义:引;挥动)。"}, {"meaning": "同本义。", "cites": [{"t": "揄,引也。", "b": "《说文》"}, {"t": "神之揄临坛宇。", "b": "《汉书·郊祀志》"}, {"t": "被发揄袂。", "b": "《庄子·渔夫》"}, {"t": "御者因揄刀而劓美人。", "b": "《韩非子》"}, {"t": "孙子曰:鼓而坐之,十而揄之。", "b": "《孙膑兵法》"}], "words": [{"w": "揄兵", "t": "引兵"}, {"w": "揄袂", "t": "挥动衣袖。"}]}, {"meaning": "出,拿出。", "cites": [{"t": "使言之而非也,虽在卿相人君,揄策于庙堂之上,未必可用。", "b": "《淮南子·主术》"}]}]}]','jingmo-wenyan');
