INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5073wx','蛰','1','zhé','虫','12','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。从虫,执声。本义:动物冬眠,藏起来不食不动)。"}, {"meaning": "同本义。", "cites": [{"t": "蛰,藏也。", "b": "《说文》"}, {"t": "蛰,静也。", "b": "《尔雅》"}, {"t": "蛰虫始振。", "b": "《吕氏春秋·孟春》"}, {"t": "龙蛇之蛰,以存身也。", "b": "《易·系辞下》。虞注:“蛰,潜藏也。”"}], "words": [{"w": "蛰地", "t": "谓潜藏在地下。"}]}, {"meaning": "虫类伏藏洞穴不出。", "cites": [{"t": "掌攻蛰兽。", "b": "《周礼·穴氏》"}], "words": [{"w": "蛰户", "t": "动物藏伏的洞穴。"}]}, {"meaning": "喻潜藏而未披露。", "cites": [{"t": "久蛰之人心。", "b": "孙文《黄花冈七十二烈士事略序》"}]}]}]','jingmo-wenyan');
