INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5076wx','揆','1','kuí','扌','12','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从手,癸声。本义:测量方位)。"}, {"meaning": "同本义。", "cites": [{"t": "揆,度也。", "b": "《说文》"}, {"t": "揆之以日,作于楚室。", "b": "《诗·鄘风·定之方中》"}, {"t": "初率其辞而揆其方。", "b": "《易·系辞》"}, {"t": "南北之揆七同也。", "b": "《国语·周语》"}]}, {"meaning": "揆度,大致估量现实状况。", "cites": [{"t": "皇览揆予初度兮,肇锡予以嘉名。", "b": "《楚辞·离骚》"}, {"t": "凡圣人见祸福也,亦揆端推类。", "b": "《论衡·实知》"}, {"t": "揆其所以,虽未必尽由于此,亦不可不以为戒。", "b": "《镜花缘》"}], "words": [{"w": "揆格", "t": "对客观事物的量度推究"}, {"w": "揆量", "t": "审度"}, {"w": "揆端", "t": "估量事物的端倪"}, {"w": "揆抚", "t": "审度省察"}, {"w": "揆德", "t": "度量人的品德。"}]}, {"meaning": "管理;掌管。", "cites": [{"t": "[尧]举八恺使主后土,以揆百事,莫不时序,地平天成。", "b": "《左传》"}], "words": [{"w": "揆持", "t": "掌管;管理。"}]}, {"meaning": "灭;破。", "cites": [{"t": "靖郭君大怒,曰:“刬而类,揆吾家。”", "b": "《吕氏春秋》"}]}, {"meaning": "准则;原则。", "cites": [{"t": "先圣后圣,其揆一也。", "b": "《孟子·离娄下》"}], "words": [{"w": "千载一揆", "t": ""}]}, {"meaning": "事务;政事。", "cites": [{"t": "纳于百揆,百揆时叙。", "b": "《书·舜典》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5077wx','掾','1','yuàn','扌','12','','[{"pinyin": "yuàn", "defs": [{"meaning": "(形声。从手,彖(tuàn)声。本义:古代副官、佐吏的通称) 同本义。", "cites": [{"t": "为沛主吏掾。", "b": "《汉书·萧何传》。注:“正曰掾,副曰属。”"}, {"t": "方进为相,与御史大夫孔光共遣掾行视。", "b": "《汉书·翟方进传》"}], "words": [{"w": "掾史", "t": "掾曹。官名。分曹治事。多由长官自行辟举"}, {"w": "掾佐", "t": "佐助的官吏"}, {"w": "掾属", "t": "佐治的官吏"}, {"w": "掾吏", "t": "官府中佐助官吏的通称。"}]}, {"meaning": "佐助。", "cites": [{"t": "掾,缘也。", "b": "《说文》。朱骏声曰:“掾,本训当为佐助之谊,故从手。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5078wx','聒','1','guō','耳','12','','[{"pinyin": "guō", "defs": [{"meaning": "(形声。从耳,本义:吵扰,声音高响或嘈杂)。"}, {"meaning": "同本义。", "cites": [{"t": "聒,欢语也。", "b": "《说文》"}, {"t": "聒,扰乱耳孔也。", "b": "《苍颉篇》"}, {"t": "聒而与之语。", "b": "《左传·襄公二十六年》。疏:“声乱叫谓之聒。”"}, {"t": "今汝聒聒。", "b": "《书·盘庚》。传:“无知之貌。”"}, {"t": "鸲鹆鸣兮聒余。", "b": "《楚辞·疾世》。注:“多声乱耳为聒。”"}, {"t": "日长思睡不可得,遭尔聒聒何时停?", "b": "宋·欧阳修《鸣鸠》"}], "words": [{"w": "聒吵", "t": "又作“吵聒”、“聒炒”。吵闹,吵嚷"}, {"w": "聒聒", "t": "象声词。杂乱喧吵的声音"}, {"w": "聒杀", "t": "形容非常嘈杂、喧闹"}, {"w": "聒天", "t": "声音响彻云天"}, {"w": "聒账", "t": "众声喧扰,通宵达旦。"}]}, {"meaning": "频繁地称说。", "cites": [{"t": "虽欲强聒,终必不蒙见察,故略上报,不复一一自辨。", "b": "宋·王安石《答司马谏议书》"}], "words": [{"w": "聒絮", "t": "絮叨;啰嗦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5079wx','葑','1','fēng fèng','艹','12','','[{"pinyin": "fēng", "defs": [{"meaning": "蔬菜名。", "cites": [{"t": "葑,须从也。从艸,封声。字亦作蘴、作菘。", "b": "《说文》"}, {"t": "采葑采菲。", "b": "《诗·邶风·谷风》"}]}, {"meaning": "即芜菁,又名蔓菁。一种一年或二年生草本植物,十字花科。"}]}, {"pinyin": "fèng", "defs": [{"meaning": "菰根,即茭白根。", "cites": [{"t": "四面湖泽,皆是菰葑。", "b": "《晋书·毛璩传》"}], "words": [{"w": "葑田", "t": "长满菰根的水田;在沼泽上,以木作架,上铺泥土,作为种植水生植物的农田,叫葑田,也叫架田"}, {"w": "葑炉", "t": "用葑田泥土制成的炉子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5080wx','葚','1','shèn rèn','艹','12','','[{"pinyin": "shèn", "defs": [{"meaning": "桑树的果实  通常暗紫色,浆果状,酸味适中,可食。", "cites": [{"t": "葚,桑实也。从草,甚声。字亦作椹。", "b": "《说文》"}, {"t": "于嗟鸠兮,无食桑葚。", "b": "《诗·卫风·氓》"}]}]}, {"pinyin": "rèn", "defs": [{"meaning": "“桑葚儿”（sāngrènr）:桑葚,桑树的果实,味甜可食。"}]}]','jingmo-wenyan');
