INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5082wx','靸','1','sǎ','革','12','','[{"pinyin": "sǎ", "defs": [{"meaning": "古代小儿穿的鞋子。前帮深而覆脚,无后帮。形制与之类似的拖鞋也叫“靸”。", "cites": [{"t": "靸,小儿履也。从革,及声。", "b": "《说文》"}, {"t": "靸,履也。", "b": "《广雅》"}, {"t": "靸鞮卬角褐袜巾。", "b": "《急就篇》"}], "words": [{"w": "草靸;宝靸;靸鞵", "t": "无跟鞋,拖鞋"}, {"w": "靸拔", "t": "鞋后跟上的襻子,拔鞋时用"}, {"w": "靸袋", "t": "箭袋。"}]}, {"meaning": "低下的物品。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5083wx','葳','1','wēi','艹','12','','[{"pinyin": "wēi", "defs": [{"meaning": "1.草木茂盛枝叶下垂的样子。"}, {"meaning": "2.玉竹，也作\\"萎蕤\\"。草的一种。地下茎为竹鞭状肉质根茎，可供药用。"}, {"meaning": "葳蕤。", "cites": [{"t": "上葳蕤而防露兮。--《楚辞·七谏·初放》", "b": ""}, {"t": "羽盖葳蕤。--张衡《东京赋》", "b": ""}, {"t": "葳蕤自生光。--《玉台新咏·古诗为焦仲卿妻作》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5084wx','葺','1','qì','艹','12','','[{"pinyin": "qì", "defs": [{"meaning": "(形声。从艸,揖省声。本义:用茅草盖屋)。"}, {"meaning": "同本义。", "cites": [{"t": "葺,茨也。", "b": "《说文》"}, {"t": "葺覆也。", "b": "《广雅》"}, {"t": "葺屋参分。", "b": "《考工记·匠人》"}, {"t": "芷葺兮荷屋。", "b": "《楚辞·湘夫人》"}], "words": [{"w": "葺茅", "t": "用茅草覆盖"}, {"w": "葺屋", "t": "草屋;修缮房屋。"}]}, {"meaning": "修理房屋。", "cites": [{"t": "葺其墙屋。", "b": "《左传·昭公二十三年》"}, {"t": "缮完葺墙,以待宾客。", "b": "《左传·襄公三十一年》"}, {"t": "汉陛秦除,莫不葺复。", "b": "沈炯《太极殿铭序》"}, {"t": "尝加营葺。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "余稍为修葺。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "又。", "cites": [{"t": "复葺南阁子。", "b": ""}], "words": [{"w": "葺治", "t": "修建"}, {"w": "葺理", "t": "修理"}, {"w": "葺缮", "t": "修补;修缮。"}]}, {"meaning": "修饰。", "cites": [{"t": "然皆句读不葺之诗尔。", "b": "李清照《词论》"}]}, {"meaning": "重叠;累积。", "cites": [{"t": "鱼葺鳞以自别兮。", "b": "《楚辞·悲回风》"}, {"t": "葺鳞镂甲。", "b": "左思《吴都赋》"}, {"t": "葺袭(重叠的样子)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5085wx','葸','1','xǐ','艹','12','','[{"pinyin": "xǐ", "defs": [{"meaning": "(形声。从什,思声。本义:畏惧的样子) 同本义。", "cites": [{"t": "慎而无礼则葸。", "b": "《论语·泰伯》"}], "words": [{"w": "畏葸不前;葸葸", "t": "畏惧的样子;小心谨慎的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5086wx','萼','1','è','艹','12','','[{"pinyin": "è", "defs": [{"meaning": "动植物身体上的结构 ,花萼,包在花瓣外面的一圈绿色叶状薄片,花开时托着花瓣", "words": [{"w": "萼跗", "t": "萼,花萼,跗,花萼房。比喻兄弟"}, {"w": "萼绿君", "t": "茉莉花的别名"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5087wx','葆','1','bǎo','艹','12','','[{"pinyin": "bǎo", "defs": [{"meaning": "(形声。保声。本义:草木茂盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "葆,草盛貌。", "b": "《说文》"}, {"t": "头如蓬葆。", "b": "《汉书·燕刺王旦传》"}]}, {"meaning": "珍贵。", "cites": [{"t": "天子之葆龟也。", "b": "《史记·乐书》"}, {"t": "天之降葆命。", "b": "《史记·周公世家》"}, {"t": "取而保祠之。", "b": "《史记·留侯世家》"}], "words": [{"w": "葆龟", "t": "即宝龟。占卜的用具"}, {"w": "葆爱", "t": "珍爱;珍视。"}]}, {"meaning": "丛生的枝、芽。", "cites": [{"t": "得时之稻,大本而茎葆。", "b": "《吕氏春秋》"}]}, {"meaning": "车盖。", "cites": [{"t": "垂翟葆,建羽旗。", "b": "张衡《西京赋》"}], "words": [{"w": "葆车", "t": "有五彩羽毛编成车盖的坐车"}, {"w": "葆羽", "t": "仪仗名。以鸟羽为饰。"}]}, {"meaning": "保持;保护;守卫。", "cites": [{"t": "小城不自守通者,尽葆其老弱粟米畜产。", "b": "《墨子·号令》"}, {"t": "人貌而天,虚缘而葆真。", "b": "《庄子·田子方》"}, {"t": "五粟之土,干而不格,湛而不泽,无高下葆泽以处,是谓粟土。", "b": "《管子·地员》"}], "words": [{"w": "永葆青春", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5088wx','葩','1','pā','艹','12','','[{"pinyin": "pā", "defs": [{"meaning": "(形声。上形,下声。《说文》:“华也。” 华,“花”的古字。本义:草木的花)。"}, {"meaning": "同本义。", "cites": [{"t": "葩,华也。", "b": "《说文》。按:“谓花之丽采美盛。”"}, {"t": "葩取其盛貌也。", "b": "《声类》"}, {"t": "若众葩敷,荣曜春风。", "b": "张衡《西京赋》"}, {"t": "群葩当令时,只在花开之数日。", "b": "明·李渔《闲情偶寄·种植部》"}], "words": [{"w": "葩卉", "t": "花卉"}, {"w": "葩蘤", "t": "花"}, {"w": "奇葩异草;葩华", "t": "花。"}]}, {"meaning": "车盖上面的金饰。"}, {"meaning": "华丽;华美。", "cites": [{"t": "《易》奇而法,《诗》正而葩。", "b": "韩愈《进学解》"}], "words": [{"w": "葩华", "t": "鲜艳的样子"}, {"w": "葩藻", "t": "华丽,华美。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5089wx','葶','1','tíng','艹','12','','[{"pinyin": "tíng", "defs": [{"meaning": "一年生草本植物，果实椭圆形。种子黑褐色，可入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5090wx','蒌','1','lóu','艹','12','','[{"pinyin": "lóu", "defs": [{"meaning": "蒌蒿 ,又称“白蒿”。多年生草本植物,多生水滨,高四五尺。", "cites": [{"t": "蒌,蒌草也。", "b": "《说文》"}, {"t": "言刈其蒌。", "b": "《诗·召南·汉广》"}]}, {"meaning": "蒌叶 。一种缠绕的胡椒。在东南亚,人们当刺激性的咀嚼物用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5091wx','萱','1','xuān','艹','12','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从艸,宣声。本义:萱草。一种草本植物,传说可以使人忘忧)。"}, {"meaning": "古称母亲居室为萱堂,后因以萱为母亲或母亲居处的代称。", "cites": [{"t": "北堂有萱兮,何以忘忧?", "b": "《红楼梦》"}], "words": [{"w": "萱辰", "t": "母亲的生日"}, {"w": "萱亲", "t": "母亲的别称"}, {"w": "萱草", "t": "借指母亲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5092wx','戟','1','jǐ','戈','12','','[{"pinyin": "jǐ", "defs": [{"meaning": "(会意。从戈,从榦(gàn)省。本义:古代兵器。青铜制,将矛、戈合成一体,既能直刺,又能横击)。"}, {"meaning": "同本义 。一种可勾可刺的兵器, 出现于商、周,盛行于战国、汉晋各代。戟是一种分枝状兵器。", "cites": [{"t": "戟,有枝兵也。…今字误作戟。", "b": "《说文》"}, {"t": "戟广寸有半。", "b": "《考工记·冶氏》。注:“今三锋戟也。”"}, {"t": "修我矛戟。", "b": "《诗·秦风·无衣》"}, {"t": "交戟之卫士。", "b": "《史记·项羽本纪》"}, {"t": "刀戟纵横。", "b": "《广东军务记》"}], "words": [{"w": "戟戈", "t": "戟和戈,泛指兵器"}, {"w": "戟盾", "t": "戟和盾"}, {"w": "戟牙", "t": "戟上横出的刃"}, {"w": "戟吏", "t": "仪仗中持戟的人。"}]}, {"meaning": "伸出食指和中指来指人。", "cites": [{"t": "拱此而揖人,人莫不喜;戟此而詈人,人莫不怒。", "b": "宋·苏轼《后怪石供》"}], "words": [{"w": "戟手", "t": "伸出食指和中指指人,其状似戟,表示愤怒或勇武的情状。"}]}, {"meaning": "刺激。", "cites": [{"t": "其根辛苦,戟人咽喉。", "b": "《本草纲目·大戟》"}], "words": [{"w": "戟口", "t": "刺口,唇受刺激如戟刺"}, {"w": "戟喉", "t": "喉受刺激。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5093wx','葭','1','jiā xiá','艹','12','','[{"pinyin": "jiā", "defs": [{"meaning": "初生的芦苇。", "cites": [{"t": "非有葭莩之亲,鸿毛之重。", "b": "《汉书·中山靖王传》"}, {"t": "沙洲葭苇。", "b": "宋·陆游《过小孤山大孤山》"}], "words": [{"w": "葭草", "t": "初生的芦苇"}, {"w": "葭蓬", "t": "芦苇与蓬草"}, {"w": "葭灰", "t": "苇膜烧得的灰。常用来标志、预测节气"}, {"w": "葭莩", "t": "原为芦苇里的白色薄膜,后常来指代:友谊;交情;亲戚;亲眷。"}]}, {"meaning": "乐器名。", "cites": [{"t": "发引和,校鸣葭。", "b": "《文选·张衡·西京赋》"}]}]}, {"pinyin": "xiá", "defs": [{"meaning": "荷叶。", "cites": [{"t": "荷,芙渠,其茎茄,其叶葭。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5094wx','楮','1','chǔ','木','12','','[{"pinyin": "chǔ", "defs": [{"meaning": "(形声。从木,者声。本义:楮树,叶似桑,皮可以造纸)。"}, {"meaning": "同本义 。可制纸。", "words": [{"w": "楮叶", "t": "楮树的叶"}, {"w": "楮鸡", "t": "楮树上所寄生的木耳。"}]}, {"meaning": "纸的代称。", "cites": [{"t": "即连楮为巨幅,广二丈,大书一“屈”字。", "b": "高启《书博鸡者事》"}], "words": [{"w": "楮知白", "t": "纸的别名"}, {"w": "楮先生", "t": "纸的别名"}, {"w": "楮墨", "t": "纸与墨。也是诗文和书画的代称"}, {"w": "楮生", "t": "纸的别名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5095wx','棼','1','fén','木','12','','[{"pinyin": "fén", "defs": [{"meaning": "栋(屋的正梁),阁楼的栋。", "cites": [{"t": "棼,复屋栋也。从林,分声。", "b": "《说文》。按,从林者,从二木也。复屋故从二木为意。复屋者,如苏俗所云,阁不可居,重屋如楼可居。"}]}, {"meaning": "阁楼。", "cites": [{"t": "棼,阁也。", "b": "《广雅》"}], "words": [{"w": "棼橹", "t": "楼橹。古时军中用以了望敌军的无顶盖高台。"}]}, {"meaning": "麻布。", "cites": [{"t": "素车,棼蔽。", "b": "《周礼·春官·巾车》"}]}, {"meaning": "(wěn)。纷乱,紊乱。众多错杂的。", "cites": [{"t": "犹治丝而棼之也。", "b": "《左传·隐公四年》"}]}, {"meaning": "又。", "cites": [{"t": "治丝而益棼之。", "b": ""}, {"t": "泯泯棼棼。", "b": "《书·吕刑》"}], "words": [{"w": "棼然", "t": "扰乱;纷乱"}, {"w": "棼丝", "t": "乱丝"}, {"w": "棼烟", "t": "缭乱的烟雾"}, {"w": "棼错", "t": "纷杂错乱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5096wx','椟','1','dú','木','12','','[{"pinyin": "dú", "defs": [{"meaning": "(形声。从木,卖声。本义:木柜,木匣)。"}, {"meaning": "同本义。", "cites": [{"t": "龟玉毁于椟中。", "b": "《论语·季氏》"}], "words": [{"w": "椟玉", "t": "收藏在匣中的美玉"}, {"w": "椟匮", "t": "匣柜"}, {"w": "椟栌", "t": "汲水器具"}, {"w": "椟丸", "t": "古代盛箭的器具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5097wx','棹','1','zhào','木','12','','[{"pinyin": "zhào", "defs": [{"meaning": "(形声。从木,卓声。本义:长的船桨)。"}, {"meaning": "同本义。", "cites": [{"t": "桂棹兮兰枻。", "b": "《楚辞·九歌·湘君》"}], "words": [{"w": "棹竿", "t": "竹竿制作的船桨。"}]}, {"meaning": "泛指船桨。", "cites": [{"t": "短棹沿洄野兴浓。", "b": "陆游《泛舟》"}], "words": [{"w": "短棹", "t": "短把的船桨。"}]}, {"meaning": "指船。", "cites": [{"t": "发战棹东下。", "b": "《宋史·太祖本纪》"}, {"t": "春歌弄明月,归棹落花前。", "b": "徐彦伯《采莲曲》"}], "words": [{"w": "棹夫", "t": "船夫"}, {"w": "棹郎", "t": "船夫"}, {"w": "棹楫", "t": "船桨"}, {"w": "棹影", "t": "船影。"}]}, {"meaning": "划。", "cites": [{"t": "或命巾车,或棹孤舟。", "b": "晋·陶潜《归去来兮辞》"}], "words": [{"w": "棹船", "t": "划船"}, {"w": "棹力", "t": "船桨划水之力"}, {"w": "棹舟", "t": "划船"}, {"w": "棹卒", "t": "操棹行船的兵士。"}]}]}]','jingmo-wenyan');
