INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5099wx','棰','1','chuí','木','12','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从木,垂声。本义:短木棍)。"}, {"meaning": "同本义。", "cites": [{"t": "一尺之棰。", "b": "《庄子·天下》"}, {"t": "身体痛,则谓鬼持棰杖殴击。", "b": "王充《论衡·订鬼》"}], "words": [{"w": "棰革", "t": "杖鞭"}, {"w": "棰楚", "t": "杖刑。"}]}, {"meaning": "鞭子,马鞭。", "cites": [{"t": "季氏负箠谢过。", "b": "《公羊传·昭公三十一年》"}, {"t": "其次关木索,被箠楚。", "b": "《汉书·司马迁传》"}, {"t": "手苦于箠辔。", "b": "《汉书·王吉传》"}], "words": [{"w": "棰策", "t": "鞭子"}, {"w": "棰楚", "t": "鞭杖之类刑具。"}]}, {"meaning": "敲打。", "cites": [{"t": "棰楚之下,何求而不得?", "b": "《汉书·路温舒传》"}], "words": [{"w": "棰杖", "t": "用杖责打"}, {"w": "棰顿", "t": "捶敲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5100wx','赍','1','jī','贝','12','','[{"pinyin": "jī", "defs": [{"meaning": "拿东西给人,送给。", "cites": [{"t": "齌,持遗也。从貝,齊声。俗字作賫。", "b": "《说文》"}, {"t": "共其财用之币齌。", "b": "《周礼·外府》"}, {"t": "设道齌之奠。", "b": "《周礼·小祝》。注:“犹送也。”"}, {"t": "受其将币之齌。", "b": "《周礼·小宗伯》"}, {"t": "又齌皮、马。", "b": "《仪礼·聘礼记》"}, {"t": "王何不以地齌周最。", "b": "《战国策·西周策》"}, {"t": "赍钱三百万。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "赍助", "t": "接济;资助"}, {"w": "赍赏", "t": "赏赐"}, {"w": "赍钱", "t": "持赠金钱"}, {"w": "赍盗粮", "t": "赠送粮食给盗寇。"}]}, {"meaning": "携带;持。", "cites": [{"t": "行者齎。", "b": "《汉书·食货志》。注:“谓将衣食之具以自随也。”"}, {"t": "齎盗粮。", "b": "《荀子·大略》"}, {"t": "赍黄金千斤。", "b": "《战国策·齐策四》"}, {"t": "赍叶入市。", "b": "三国魏·邯郸淳《笑林》"}], "words": [{"w": "赍酒", "t": "携酒,带酒"}, {"w": "赍带", "t": "携带"}, {"w": "赍排", "t": "置办安排"}, {"w": "赍刺", "t": "持名片往谒。"}]}, {"meaning": "怀抱着。", "cites": [{"t": "赍志没地,长怀无己。", "b": "江淹《恨赋》"}], "words": [{"w": "赍志", "t": "心怀大志"}, {"w": "赍志而殁", "t": "心怀未遂的志愿死去"}, {"w": "赍子", "t": "男性生殖器。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5101wx','椋','1','liáng','木','12','','[{"pinyin": "liáng", "defs": [{"meaning": "椋子树，乔木。叶似柿叶。果实小圆，青色，成熟时黑色。木质坚硬。"}, {"meaning": "鸟类的一科，喜群飞，食种子和昆虫，有的善于模仿别的鸟叫。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5102wx','椁','1','guǒ','木','12','','[{"pinyin": "guǒ", "defs": [{"meaning": "(形声。从木。本义:棺材外面套的大棺) 同本义。", "cites": [{"t": "椁,葬有木郭也。", "b": "《说文》"}, {"t": "不树者无椁。", "b": "《周礼·地官·闾师》"}, {"t": "汤母曰:“汤为天子大臣,被污恶言而死,何厚葬乎!”载以牛车,有棺无椁。", "b": "《史记·张汤列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5103wx','椪','1','pèng','木','12','','[{"pinyin": "pèng", "defs": [{"meaning": "常绿小乔木,叶片小,椭圆形,花白色,果实大,皮橙黄色,汁多味甜。"}]}]','jingmo-wenyan');
