INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5107wx','覃','1','qín tán','覀','12','','[{"pinyin": "qín", "defs": [{"meaning": "姓。"}]}, {"pinyin": "tán", "defs": [{"meaning": "意味深长。", "cites": [{"t": "覃,长味也。", "b": "《说文》。段玉裁注:“此与酉部醰,音同义近。”"}]}, {"meaning": "长,悠长。", "cites": [{"t": "葛之覃兮。", "b": "《诗·周南·葛覃》"}], "words": [{"w": "覃恩", "t": "深厚广大的恩惠。"}]}, {"meaning": "蔓延,延伸,延伸到。", "cites": [{"t": "覃及鬼方。", "b": "《诗·大雅·荡》"}, {"t": "葛之覃兮,施于中谷。", "b": "《诗·王风·葛覃》"}], "words": [{"w": "覃覃", "t": "延展的样子。"}]}, {"meaning": "深入地。", "cites": [{"t": "研精覃思。", "b": "《书·孔安国序》"}, {"t": "扬雄覃思。", "b": "《汉书·叙传上》"}], "words": [{"w": "覃思", "t": "深思,深入而周详地思考。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5108wx','酤','1','gū','酉','12','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从酉(yǒu),古声。从“酉”,表示与酒有关。本义:一夜酿成的酒)。"}, {"meaning": "同本义。", "cites": [{"t": "酤,一宿酒也。", "b": "《说文》"}], "words": [{"w": "清酤", "t": "一夜酿成的美酒"}, {"w": "酤酿", "t": "酿酒出售。"}]}, {"meaning": "泛指酒。", "cites": [{"t": "既载清酤。", "b": "《诗·商颂·烈祖》"}], "words": [{"w": "清酤", "t": "薄酒。"}]}, {"meaning": "买,买酒。", "cites": [{"t": "无酒酤我。", "b": "《诗·小雅·伐木》。注:“酤,一说,一宿酒,即速熟之酒。"}, {"t": "高祖每酤留饮,酒讐数倍。", "b": "《史记·高祖纪》"}, {"t": "酒酤于市,果止于梨、栗、枣、柿之类。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "酤榷", "t": "官府专卖酒类。酤:通“沽”。买酒或卖酒"}, {"w": "酤酒", "t": "买酒或卖酒"}, {"w": "酤买", "t": "买酒。"}]}, {"meaning": "卖酒。", "cites": [{"t": "出于屠酤之肆。", "b": "《淮南子·泛论》"}, {"t": "周丘者,下邳人也,亡命吴,酤酒无行。", "b": "《史记·吴王濞传》"}, {"t": "宋人有酤酒者,为器甚洁清,置表甚长,而酒酸不售。", "b": "《晏子春秋·问上》"}], "words": [{"w": "酤坊", "t": "酒店"}, {"w": "酤家", "t": "酒家,酒店"}, {"w": "酤肆", "t": "酒肆;酒店"}, {"w": "酤卖", "t": "出卖酒类等。"}]}]}]','jingmo-wenyan');
