INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5112wx','厥','1','jué','厂','12','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从厂(hǎn,山崖),欮(jué)声。本义:石块) 同本义。", "cites": [{"t": "厥,发石也。", "b": "《说文》"}, {"t": "相柳之所,抵厥为泽谿。", "b": "《山海经·海外北经》"}, {"t": "熒惑厥弛。", "b": "《汉书·李寻传》"}, {"t": "和之璧,井里之厥也,玉人琢之,为天子宝。", "b": "《荀子》"}]}, {"meaning": "病名。指突然昏倒、手足逆冷等症。", "cites": [{"t": "凝于足者为厥。", "b": "《素问·六节藏象论》。注:“谓足逆冷也。”"}], "words": [{"w": "厥冷", "t": "指突然晕倒或手足逆冷"}, {"w": "厥逆", "t": "指突然晕倒或手足厥冷;久久的头痛。"}]}, {"meaning": "磕头;触碰。", "cites": [{"t": "若崩厥角稽首。", "b": "《孟子》"}], "words": [{"w": "角犀厥地;厥角", "t": "叩头。"}]}, {"meaning": "短,缺。", "cites": [{"t": "是以汤武至尊严,不失肃祗;舜在假典,顾省厥遗。", "b": "《史记》"}]}, {"meaning": "其;他的;她的。", "cites": [{"t": "思厥先祖父。", "b": "宋·苏洵《六国论》"}, {"t": "将尽厥职焉。", "b": "明·顾炎武《复庵记》"}], "words": [{"w": "厥父;厥疾不疗;厥幸", "t": "其罪"}, {"w": "厥罪惟均", "t": "其罪行是一样的。"}]}, {"meaning": "它的;他们的;它们的。", "cites": [{"t": "方命厥后。", "b": "《诗·商颂·玄鸟》"}], "words": [{"w": "厥后", "t": ""}]}, {"meaning": "因而,因此,于是。", "cites": [{"t": "左丘失明,厥有《国语》。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5113wx','殚','1','dān','歹','12','','[{"pinyin": "dān", "defs": [{"meaning": "(形声。从歹(è),单声。本义:用尽,竭尽)。"}, {"meaning": "同本义。", "cites": [{"t": "殚,极尽也。从歹,单声。", "b": "《说文》"}, {"t": "殚,尽也。", "b": "《广雅》"}, {"t": "殚所未见。", "b": "张衡《西京赋》"}, {"t": "穆穆之礼殚。", "b": "张衡《东京赋》"}, {"t": "相为殚智竭力。", "b": "《吕氏春秋·本味》"}, {"t": "殚天下之财。", "b": "《汉书·杜钦传》"}, {"t": "犹未殚于《九章》。", "b": "《楚辞·忧苦》"}, {"t": "彦博以爱国故,耗思殚神。", "b": "《唐书·温彦博传》"}, {"t": "殚其地之出,竭其庐之入。(殚、竭同义,尽也。)。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "不可殚言。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "殚心竭力", "t": "用尽心思,竭尽心力"}, {"w": "殚虑", "t": "竭尽智虑"}, {"w": "殚形", "t": "使人和物的状貌完全显现出来。"}]}, {"meaning": "灭;尽;毙。", "cites": [{"t": "单(殚)毙其死。", "b": "《左传·襄公二十七年》"}, {"t": "鸟兽殚。", "b": "张衡《西京赋》"}, {"t": "池中鱼为之殚。", "b": "《淮南子·说山》"}], "words": [{"w": "殚残", "t": "毁坏灭绝"}, {"w": "殚闷", "t": "气绝昏倒。"}]}, {"meaning": "畏惧。", "cites": [{"t": "六师发逐,百兽骇殚。", "b": "汉·班固《西都赋》"}]}, {"meaning": "病;祸。", "cites": [{"t": "斩艾百姓,殚尽大半。", "b": "《淮南子·览冥》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5114wx','殛','1','jí','歹','12','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从歹,亟声。从“歹”(è),表示与死亡有关。本义:诛,杀死)。"}, {"meaning": "同本义。", "cites": [{"t": "殛,诛也。", "b": "《说文》"}, {"t": "明神殛之。", "b": "《左传·襄公十一年》"}, {"t": "有夏多罪,天命殛之。", "b": "《书·汤誓》"}, {"t": "乃殛鲧于羽山。", "b": "《史记·夏本纪》"}, {"t": "愿丞相思舜帝殛鲧用禹之义。", "b": "《三国演义》"}], "words": [{"w": "雷殛", "t": ""}]}, {"meaning": "惩罚。", "cites": [{"t": "爽惟天其罚殛我,我其不怨。", "b": "《书·康诰》"}], "words": [{"w": "殛罚", "t": "惩罚。"}]}, {"meaning": "流放,放逐", "cites": [{"t": "我不负神兮,神何殛我越荒州?", "b": "汉·蔡琰《胡笳十八拍》"}]}]}]','jingmo-wenyan');
