INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5119wx','椠','1','qiàn','木','12','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从木,斩声。本义:书板,古代削木为牍,没有书写过的素牍叫椠)。"}, {"meaning": "同本义。", "cites": [{"t": "椠,牍朴也。从木,斩声。谓未书之版长三尺,其小者曰札曰牒。", "b": "《说文》"}, {"t": "怀铅握椠。", "b": "《西京杂记》"}], "words": [{"w": "椠工", "t": "刻字工"}, {"w": "椠刻", "t": "刊刻"}, {"w": "椠匠", "t": "刻字匠人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5120wx','辍','1','chuò','车','12','','[{"pinyin": "chuò", "defs": [{"meaning": "(形声。本义:中途停止,废止)。"}, {"meaning": "同本义。", "cites": [{"t": "辍车小缺复合者。", "b": "《说文》"}, {"t": "君子不为小人之匈匈也辍行。", "b": "《荀子·天论》"}, {"t": "陈涉少时,尝与人佣耕,辍耕之垄上,怅恨久之。", "b": "《史记·陈涉世家》"}], "words": [{"w": "辍斤", "t": "停止挥斧。比喻没有伙伴,就不再施展技艺"}, {"w": "辍朝", "t": "暂停中止朝见"}, {"w": "辍耕陇上", "t": "停止耕作,在田中高地休息。"}]}, {"meaning": "放下,舍弃。", "cites": [{"t": "偶命厨者进芋,辍箸叹曰…", "b": "周容《芋老人传》"}], "words": [{"w": "辍己", "t": "舍己"}, {"w": "辍弃", "t": "抛弃"}, {"w": "辍食弃餐", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5121wx','辎','1','zī','车','12','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从车,甾(zī)声。本义:古代一种有帷盖的大车。又称“辎车”)。"}, {"meaning": "同本义。", "cites": [{"t": "辎车,载辎重卧息其中之车也。", "b": "《释名·释车》"}, {"t": "辎,载衣物车,前后皆蔽,若今库车有邸曰辎,无邸曰軿,軿车有衣蔽,无后辕,其有后辕者,谓之辎也。", "b": "《字林》"}, {"t": "辎,軿车前衣车后也。从车,甾声。", "b": "《说文》。按,軿车前有衣,辎车前后皆有衣。"}, {"t": "蔽前后谓之辎,载物必重谓之重,人挽以行谓之辇,一物也。", "b": "《左传·宣公十二年》疏"}, {"t": "终日不离其缁重。", "b": "张衡《东京赋》。注:“辎重,有衣车也。”"}, {"t": "乡师车辎造修文具,其缮何若?", "b": "《管子》"}], "words": [{"w": "辎车", "t": "外面罩有车篷、布帘的车子"}, {"w": "辎軿", "t": "指在车箱四周设有布帘屏蔽的车子"}, {"w": "辎骑", "t": "载着物质的车骑。"}]}, {"meaning": "行军时运输部队携带的物资。", "cites": [{"t": "隧路亟,行辎治,此司空之官也。", "b": "《淮南子》"}], "words": [{"w": "辎粮", "t": "军用钱粮;军需"}, {"w": "辎囊", "t": "随军所携带的私人用品袋,指其随军所带的物资。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5122wx','斐','1','fěi','文','12','','[{"pinyin": "fěi", "defs": [{"meaning": "(形声。从文,非声。从“文”,表示与文饰、彩饰有关。本义:五色相错的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "斐,分别文也。", "b": "《说文》"}, {"t": "君子豹变,其文斐也。", "b": "《易·革》"}, {"t": "有斐君子。", "b": "《礼记·大学》。注:“有文章貌也。”"}, {"t": "斐然成章。", "b": "《论语》"}, {"t": "萋兮斐兮。", "b": "《诗·小雅·巷伯》"}]}]}]','jingmo-wenyan');
