('5127wx','戢','1','jí','戈','12','','[{"pinyin": "jí", "defs": [{"meaning": "收藏。", "cites": [{"t": "载戢干戈。", "b": "《诗·周颂·时迈》"}, {"t": "夫兵戢而时动。", "b": "《国语·周语》"}, {"t": "夫兵戢而时动,动则威。", "b": "《国语·周语》"}], "words": [{"w": "戢刃", "t": "收起刀剑等利器"}, {"w": "戢戢", "t": "聚集"}, {"w": "戢载", "t": "收集装载"}, {"w": "戢藏", "t": "收藏。"}]}, {"meaning": "引申指停止战争。", "cites": [{"t": "弗戢,将自焚。", "b": "《左传·隐公四年》"}], "words": [{"w": "戢戈", "t": "息兵"}, {"w": "戢兵", "t": "停用兵器,禁用武力"}, {"w": "戢武", "t": "息兵。"}]}, {"meaning": "收敛。", "cites": [{"t": "戢,敛也。", "b": "《小尔雅》"}, {"t": "戢其左翼。", "b": "《诗·小雅·鸳鸯》"}, {"t": "不戢不难。", "b": "《诗·小雅·桑扈》"}, {"t": "翼翼归鸟,戢羽寒条。", "b": "陶渊明《归鸟》"}], "words": [{"w": "戢鳞", "t": "敛鳞。鱼止息不游。比喻怀志坐待时机"}, {"w": "戢羽", "t": "敛翅止飞"}, {"w": "戢身", "t": "敛迹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5128wx','喋','1','dié zhá','口','12','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从口,葉(yè)声。本义:喋喋:形容说话多)。"}, {"meaning": "同本义。常叠用。", "cites": [{"t": "喋,便语也。", "b": "《玉篇》"}, {"t": "岂效此啬夫喋喋利口捷口哉?", "b": "《汉书·张释之传》"}], "words": [{"w": "喋聒", "t": "多言扰耳;噜嗦。"}]}, {"meaning": "踏,蹈。", "cites": [{"t": "然已席卷千里,南面称孤,喋血乘胜日有闻矣。", "b": "《史记·魏豹彭越列传》。"}, {"t": "今已诛诸吕,新喋血京师。", "b": "《汉书·文帝纪》。颜师古注:本字当作蹀。蹀,谓履涉之耳。"}], "words": [{"w": "喋盟", "t": "歃血盟誓。"}]}]}, {"pinyin": "zhá", "defs": [{"meaning": "", "words": [{"w": "唼喋;喋呷", "t": "水鸟或鱼类聚食的样子"}, {"w": "喋噏", "t": "聚食的样子。"}]}]}]','jingmo-wenyan');
