INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5133wx','晷','1','guǐ','日','12','','[{"pinyin": "guǐ", "defs": [{"meaning": "(形声。从日,咎声。本义:日影)。"}, {"meaning": "同本义。", "cites": [{"t": "晷,日景也。", "b": "《说文》"}, {"t": "白日未及移其晷,己狝其什七八。", "b": "汉·张衡《西京赋》"}, {"t": "相持既久,日晷渐移。", "b": "马中锡《中山狼传》"}], "words": [{"w": "晷昃", "t": "日影偏西"}, {"w": "晷曜", "t": "圭表上投射的日影"}, {"w": "晷仪", "t": "测日影以定时刻的仪器"}, {"w": "晷景", "t": "晷表之投影;日影"}, {"w": "晷柱", "t": "晷表。"}]}, {"meaning": "日光;亮光。", "cites": [{"t": "辉光所烛,万里同晷。", "b": "《汉书·李寻传》"}, {"t": "月晷呈祥。", "b": "《宋书·谢庄传》"}, {"t": "春来多困,正晷移帘影,银屏深闭。", "b": "宋·柴望《念奴娇》"}]}, {"meaning": "白昼。", "cites": [{"t": "究晷系夜,钓于台下。", "b": "晋·王嘉《拾遗记》"}]}, {"meaning": "比喻光阴,时间。", "cites": [{"t": "寸晷惟宝,岂无玙璠。", "b": "晋·潘正叔《赠陆机出为吴王郎中令》"}]}, {"meaning": "(玙璠:美玉)。", "cites": [{"t": "日无暇晷", "b": ""}, {"t": "命下,遂缚以出,不羁晷刻。", "b": "方苞《狱中杂记》"}], "words": [{"w": "晷刻", "t": "片刻"}, {"w": "晷候", "t": "片刻"}, {"w": "晷暇", "t": "片刻空闲"}, {"w": "余晷", "t": ""}]}, {"meaning": "日晷,按照日影测定时间的仪器,也叫“日规”。", "cites": [{"t": "以冬至之后,立晷侧影,准度日月星。", "b": "《晋书·鲁胜传·正天论》"}], "words": [{"w": "晷表", "t": "日晷上的标竿"}, {"w": "晷刻", "t": "日晷和刻漏"}, {"w": "晷漏", "t": "晷与漏"}, {"w": "晷度", "t": ""}]}, {"meaning": "轨道。", "cites": [{"t": "应天顺民,五星同晷。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5134wx','喈','1','jiē','口','12','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从口,皆声。本义:鸟鸣声)。"}, {"meaning": "同本义。", "cites": [{"t": "喈,鸟鸣声也。", "b": "《说文》"}, {"t": "鸡鸣喈喈。", "b": "《诗·郑风·风雨》"}, {"t": "鶬鶊兮喈喈。", "b": "《楚辞·悼乱》"}]}, {"meaning": "风雨疾速的样子。", "cites": [{"t": "北风其喈,雨雪其霏。", "b": "《诗·邶风·北风》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5135wx','跖','1','zhí','足','12','','[{"pinyin": "zhí", "defs": [{"meaning": "(形声。从足,石声。本义:脚掌) 同本义。", "cites": [{"t": "跖,足下也。", "b": "《说文》"}, {"t": "善学者若齐王之食鸡也,必食其跖数千而后足。", "b": "《吕氏春秋》"}]}, {"meaning": "踏,踩。", "cites": [{"t": "跖劲弩。", "b": "《史记》"}, {"t": "蹠达膝。", "b": "《淮南子·脩务》"}, {"t": "上无凌虚之巢,下无跖实之蹊。", "b": "张协《七命》"}], "words": [{"w": "跖实", "t": "兽足踏地。"}]}, {"meaning": "跳跃。", "cites": [{"t": "跖魂负沴。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5136wx','跗','1','fū fú','足','12','','[{"pinyin": "fū", "defs": [{"meaning": "脚背。", "cites": [{"t": "蹶泥则没足灭跗。", "b": "《庄子·秋水》"}], "words": [{"w": "跗注", "t": "古代的一种长兵服。"}]}, {"meaning": "物体的足部", "cites": [{"t": "朱跗黄实,蓄殖果木,不如三土以十分之六。", "b": "《管子·地员》"}], "words": [{"w": "鼓跗", "t": "鼓架。"}]}, {"meaning": "花萼。", "cites": [{"t": "衔素蕊于青跗。", "b": "南朝齐·沈约《郊居赋》"}], "words": [{"w": "跗萼", "t": "花萼与子房。亦指花朵"}, {"w": "跗萼联芳", "t": "比喻兄弟均贵显荣耀。"}]}]}, {"pinyin": "fú", "defs": [{"meaning": "手足伏地。同“匐”。", "cites": [{"t": "匐,《说文》:“伏地也。”或作跗。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
