INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5144wx','蛭','1','zhì','虫','12','','[{"pinyin": "zhì", "defs": [{"meaning": "蚂蟥。环节动物。体一般长而扁平,略似蚯蚓,前后各有一个吸盘。生活在淡水或湿润处,能吸人畜的血。", "cites": [{"t": "蛭,虮也。从虫,至声。", "b": "《说文》"}, {"t": "楚惠王食寒菹而得蛭,遂吞之,久病心腹之疾皆愈。", "b": "《贾子春秋》"}, {"t": "蛭之性食血,惠王殆有积血也。", "b": "《论衡·福虚》"}, {"t": "弥六合,泽万物,而虾与蛭不离尺水。", "b": "柳宗元《晋问》"}], "words": [{"w": "蛭虮", "t": "水蛭"}, {"w": "蛭蝚", "t": "水蛭。一名至掌"}, {"w": "蛭类", "t": "动物学名词。"}]}, {"meaning": "小山丘", "cites": [{"t": "人莫迹于山,而迹于蛭。", "b": "《淮南子·人间》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
