INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5150wx','蛟','1','jiāo','虫','12','','[{"pinyin": "jiāo", "defs": [{"meaning": "(形声。从虫,交声。本义:古代传说中能发水的一种龙)。"}, {"meaning": "同本义。", "cites": [{"t": "蛟,龙之属也。池鱼,满三千六百,蛟来为之长,能率鱼飞置笱水中,即蛟去。", "b": "《说文》"}, {"t": "其中有虎蛟。注:“蛟似蛇四足,龙属。”", "b": ""}, {"t": "母龙曰蛟。", "b": "《抱朴子》"}, {"t": "义兴水中有蛟。(蛟,这里指鼍,鳄一类的动物。)", "b": "《世说新语·自新》"}], "words": [{"w": "蛟虬", "t": "蛟与虬。虬:古代传说中一种有角的小龙。亦泛指水族"}, {"w": "蛟螭", "t": "蛟龙。螭:传说为蛟龙之属的一种动物"}, {"w": "蛟兕", "t": "蛟龙与兕牛。"}]}, {"meaning": "又有古书说是无角龙。", "cites": [{"t": "蛟,龙属。无角曰蛟。", "b": "《韵会》"}, {"t": "乘六蛟兮蜿蝉。", "b": "《楚辞·守志》。注:“龙无角曰蛟。”"}]}, {"meaning": "又指小龙或母龙。", "cites": [{"t": "麾蛟龙使梁津兮,诏西皇使涉予。", "b": "《楚辞》。王逸注:“小曰蛟,大曰龙。”"}]}, {"meaning": "鲨鱼。", "cites": [{"t": "胁蛟犀兕,坚若金石。", "b": "《商君书·弱民》"}, {"t": "自寻阳浮江,亲射蛟江中。", "b": "《汉书·武帝纪》"}], "words": [{"w": "蛟革", "t": "鲨鱼皮"}, {"w": "蛟胎", "t": "用鲨鱼皮制成的剑鞘"}, {"w": "蛟鱼", "t": "传说中的人鱼。"}]}]}]','jingmo-wenyan');
