('5154wx','啾','1','jiū','口','12','','[{"pinyin": "jiū", "defs": [{"meaning": "小儿声。", "cites": [{"t": "啾,小儿声也。", "b": "《说文》"}]}, {"meaning": "众声杂沓。", "words": [{"w": "啾疾", "t": "指鸟儿失偶时的鸣叫;小病"}, {"w": "啾喧", "t": "犹喧嚣"}, {"w": "啾号", "t": "杂乱地鸣叫"}, {"w": "啾嘈", "t": "喧杂细碎的声音"}, {"w": "啾哗", "t": "喧闹。"}]}, {"meaning": "歌吟声。", "cites": [{"t": "夫啾发投曲,感耳之声。", "b": "《文选·班固·答宾戏》"}]}]}]','jingmo-wenyan');
