INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5156wx','喑','1','yīn','口','12','','[{"pinyin": "yīn", "defs": [{"meaning": "(形声。从口,音声。本义:小儿哭泣不止)。"}, {"meaning": "同本义。", "cites": [{"t": "喑,宋齐谓儿泣不止曰喑。", "b": "《说文》"}]}, {"meaning": "恚怒声。相当于“嗯”。", "cites": [{"t": "徐郎见言,大怒:“喑,我教你去捉太公,主将倒来取救兵!”", "b": "《武王伐纣平话》"}], "words": [{"w": "喑哑叱咤", "t": "发怒喝叫声"}, {"w": "喑呜叱", "t": "呵叱怒喝。"}]}, {"meaning": "缄默不语。", "cites": [{"t": "九州生气恃风雷,万马齐喑究可哀。", "b": "清·龚自珍《己亥杂诗》"}], "words": [{"w": "喑气", "t": "不吭声;不说话"}, {"w": "喑畏", "t": "畏惧不敢出言。"}]}, {"meaning": "嗓子哑,不能出声;失音。", "cites": [{"t": "遂称风疾,喑不能言。", "b": "《后汉书·袁闳传》"}, {"t": "此譬犹瘖者而使为行人,聋者而使为乐师。", "b": "《墨子》"}, {"t": "虽有舜禹之智,吟而不言,不如喑聋之指麾也。", "b": "《史记》"}], "words": [{"w": "喑涩", "t": "沙哑干涩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5157wx','嗟','1','jiē','口','12','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从口,差声。本义:叹词。表示忧感)。"}, {"meaning": "感叹声。", "cites": [{"t": "嗟叹使心伤。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "嗟乎,师道之不传也久矣。", "b": "唐·韩愈《师说》"}, {"t": "嗟乎!…非此之由乎。", "b": "清·刘开《问说》"}, {"t": "嗟夫,谁知吾卒先汝。", "b": "清·林觉民《与妻书》"}], "words": [{"w": "嗟乎", "t": "嗟呼。表示感叹"}, {"w": "嗟讶", "t": "感叹,惊叹"}, {"w": "嗟异", "t": "感叹称异"}, {"w": "嗟悼", "t": "哀叹,悲悼。"}]}, {"meaning": "表示呼唤。", "cites": [{"t": "嗟,我士,听无哗。", "b": "《书·秦誓》"}], "words": [{"w": "嗟来", "t": "来,语助"}, {"w": "嗟来之食;嗟嗟", "t": "表示招呼。"}]}, {"meaning": "叹息。", "cites": [{"t": "忽魂悸以魄动,怳惊起而长嗟。", "b": "李白《梦游天姥吟留别》"}], "words": [{"w": "嗟呀", "t": "叹息"}, {"w": "嗟咨", "t": "慨叹"}, {"w": "嗟怨", "t": "悲叹;怨恨"}, {"w": "嗟伤", "t": "叹息伤感。"}]}, {"meaning": "赞叹。", "cites": [{"t": "见其所为文,嗟赏之。", "b": "《宋史·王质传》"}], "words": [{"w": "嗟仰", "t": "赞叹景仰"}, {"w": "嗟尚", "t": "赞叹嘉尚"}, {"w": "嗟赞", "t": "赞叹"}, {"w": "嗟异", "t": "赞叹称异。"}]}]}]','jingmo-wenyan');
