INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5186wx','锏','1','jiǎn jiàn','钅','12','','[{"pinyin": "jiǎn", "defs": [{"meaning": "古代兵器,鞭类 。长而无刃,有四棱,上端略小,下端有柄。", "cites": [{"t": "三股叉,四楞锏,耀日争光。", "b": "元·关汉卿《单刀会》"}]}]}, {"pinyin": "jiàn", "defs": [{"meaning": "车轴上的铁条,用以减少轴与毂之间的摩擦。", "cites": [{"t": "膏锏有余,则车轻人。", "b": "《吴子·治兵》"}]}]}]','jingmo-wenyan');
