INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5191wx','掣','1','chè','手','12','','[{"pinyin": "chè", "defs": [{"meaning": "(形声。从手,制声。本义:牵引,拉)。"}, {"meaning": "同本义。", "cites": [{"t": "掣,拽也。", "b": "《经典释文》"}, {"t": "见舆曳,其牛掣。", "b": "《易·睽》"}, {"t": "流火掣空飞。", "b": "袁宏道《雪夜感怀同黄道元作》"}, {"t": "纷纷暮雪下辕门,风掣红旗冻不翻。", "b": "唐·岑参《白雪歌送武判官归京》"}], "words": [{"w": "掣后腿;掣手;掣脱", "t": "决裂;弄僵"}, {"w": "掣撰", "t": "掣曳,牵引之意。"}]}, {"meaning": "抽;拔。", "cites": [{"t": "羲之密从后掣其笔不得。", "b": "《晋书·王献之传》"}], "words": [{"w": "掣签", "t": "清代制度,候补的地方官吏抽签确定任职省分。具备一定条件的,可以自选省分,称“指分”"}, {"w": "掣兵", "t": "抽调兵马"}, {"w": "掣开", "t": "抽出"}, {"w": "掣身", "t": "抽身。"}]}]}]','jingmo-wenyan');
