INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5199wx','鹄','1','gǔ hè hú','鸟','12','','[{"pinyin": "gǔ", "defs": [{"meaning": "目标,目的。", "cites": [{"t": "此其鹄惟在于刑,其刑惟在于任威斩断,而五官之大法无与焉。", "b": "章炳麟《商鞅》"}]}]}, {"pinyin": "hè", "defs": [{"meaning": "鸟名。鹤科各种禽类的泛称。", "cites": [{"t": "夫鹄不日浴而白,乌不日黔而黑。", "b": "《庄子·天运》"}, {"t": "越鸡不能伏鹄卵。", "b": "《庄子·庚桑楚》"}, {"t": "王昭楚妃,千里别鹄。", "b": "嵇康《琴赋》"}, {"t": "大仪鹄发。", "b": "《后汉书·吴良传赞》"}]}]}, {"pinyin": "hú", "defs": [{"meaning": "(形声。从鸟,告声。本义:鸟名。指鸿鹄,又名“黄鹄”,俗称天鹅)。"}, {"meaning": "同本义。", "cites": [{"t": "青雀白鹄舫。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "脱笼之鹄。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "鹄卵", "t": "天鹅蛋"}, {"w": "鹄韵鹄鹄", "t": "天鹅的鸣叫声"}, {"w": "鹄子", "t": "幼鹄。"}]}, {"meaning": "古地名。在今山西省闻喜县附近。", "cites": [{"t": "素衣朱绣,从子于鹄。", "b": "《诗·唐风》。毛传:“鹄,曲沃邑也。”"}]}, {"meaning": "治理象牙。", "cites": [{"t": "象谓之鹄。", "b": "《尔雅》。郭璞注:“鹄,治朴之名。”"}]}, {"meaning": "大。", "cites": [{"t": "鹄乎其羞用智虑也。", "b": "《吕氏春秋·下贤》"}]}]}]','jingmo-wenyan');
