INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5202wx','黍','1','shǔ','黍','12','','[{"pinyin": "shǔ", "defs": [{"meaning": "(形声。从禾,雨省声。本义:植物名。亦称“稷”、“糜子”)。"}, {"meaning": "古代专指一种子实叫黍子的一年生草本植物 。其子实煮熟后有粘性,可以酿酒、做糕等。", "cites": [{"t": "黍,禾属而黏者也。", "b": "《说文》。按,今北方谓之黄米。"}, {"t": "天子乃以雏尝黍。", "b": "《礼记·月令》。注:“黍火谷。”"}, {"t": "黍白芗合。", "b": "《礼记·曲礼》"}, {"t": "无食我黍。", "b": "《诗·魏风·硕鼠》"}, {"t": "止子路宿,杀鸡为黍而食之。", "b": "《论语·微子》"}], "words": [{"w": "黍离", "t": "喻覆没;衰败。西周亡后,周大夫过故宗庙官室,只见满目黍离,十分荒凉"}, {"w": "黍酒", "t": "用黍酿制的酒"}, {"w": "黍醅", "t": "同黍酒"}, {"w": "黍月霍", "t": "一种杂有黍米的肉羹"}, {"w": "黍谷生春", "t": "比喻厄运有了好的转机。"}]}, {"meaning": "糜稷一类草本植物。", "cites": [{"t": "麦行千里不见土,连山没云皆种黍。", "b": "宋·王安石《后元丰行》"}]}, {"meaning": "古时建立度量衡的依据。", "cites": [{"t": "舟首尾长约八分有奇,高可二黍许。", "b": "《虞初新志·魏学洢·核舟记》"}]}, {"meaning": "黄米做的饭。", "cites": [{"t": "其镶伊黍。", "b": "《诗·周颂·良耜》"}], "words": [{"w": "杀鸡为黍", "t": ""}]}]}]','jingmo-wenyan');
