INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5205wx','筚','1','bì','竹','12','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从竹,毕声。本义:用竹子编成的篱笆)。"}, {"meaning": "同本义。", "cites": [{"t": "筚,藩落也。", "b": "《说文》"}, {"t": "筚,篱也。", "b": "《广雅》"}, {"t": "筚门圭窦之人。", "b": "《左传·襄公十年》。注:“柴门也。”"}], "words": [{"w": "筚门", "t": "荆竹编成的门。又称柴门。常用以喻指贫户居室"}, {"w": "筚路", "t": "柴车。多以荆竹编织,简陋无饰。"}]}, {"meaning": "泛指用竹子、荆条等织成的器物。", "cites": [{"t": "筚路蓝缕,以启山林。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5206wx','筵','1','yán','竹','12','','[{"pinyin": "yán", "defs": [{"meaning": "(形声。从竹,延声。本义:竹席)。"}, {"meaning": "古时铺在地上供人坐的垫底的竹席,古人席地而坐,设席每每不止一层。紧靠地面的一层称筵,筵上面的称席。", "cites": [{"t": "筵亦席也。铺陈曰筵,藉之曰席。", "b": "《周礼》郑玄注"}], "words": [{"w": "筵几", "t": "座席和几案"}, {"w": "筵第", "t": "筵席和床铺。"}]}, {"meaning": "席位。", "cites": [{"t": "张筵列鼎。", "b": "清·周容《芋老人传》"}], "words": [{"w": "筵席", "t": "酒宴时的座位和陈设"}, {"w": "筵羞", "t": "酒宴美食。"}]}, {"meaning": "铺设坐席。", "cites": [{"t": "主人筵于户西。", "b": "《仪礼·士冠礼》"}], "words": [{"w": "筵床", "t": "铺设席子的坐榻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5207wx','筌','1','quán','竹','12','','[{"pinyin": "quán", "defs": [{"meaning": "捕鱼器 。竹制,有逆向钩刺。亦为钓鱼用具的统称。", "cites": [{"t": "夹潀罗筌。", "b": "郭璞《江赋》"}], "words": [{"w": "筌箵", "t": "捕鱼用的竹编盛器"}, {"w": "筌鱼", "t": "捕鱼"}, {"w": "筌拾", "t": "犹收录。"}]}, {"meaning": "香草。", "cites": [{"t": "君看孤松树,…既可习为饱,亦可薰为筌。", "b": "元稹《和乐天感鹤》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5208wx','傣','1','dǎi','亻','12','','[{"pinyin": "dǎi", "defs": [{"meaning": "(形声。从人,泰声。本义:傣族,我国少数民族名) 同本义  中国的一个少数民族。古代或称掸、金齿、白衣、白夷、摆夷等。人口约83.9万(1982)。主要分布在云南省的德宏、西双版纳、耿马、孟连等地。语言属汉藏语系僮侗语族傣语支。多事农业,善植水稻。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5209wx','傈','1','lì','亻','12','','[{"pinyin": "lì", "defs": [{"meaning": "本作“栗”。古代制作庙堂神主所用的栗木。", "cites": [{"t": "傈,古庙主木用栗,未用称傈为庙主者。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5210wx','舄','1','xì','臼','12','','[{"pinyin": "xì", "defs": [{"meaning": "重木底鞋(古时最尊贵的鞋,多为帝王大臣穿)。", "cites": [{"t": "舄,履也。", "b": "《广雅》"}, {"t": "赤舄几几。", "b": "《诗·豳风·狼跋》"}, {"t": "舄,以木置履下,干腊不畏泥湿也。", "b": "晋·崔豹《古今注》"}, {"t": "屦人掌王及王后之服屦,为赤舄黑舄。", "b": "《周礼·天官》"}], "words": [{"w": "舄履", "t": "复底厚履。"}]}, {"meaning": "泛指鞋。", "cites": [{"t": "发棺视之,止衣舄而已。", "b": "《太平广记》"}], "words": [{"w": "舄履", "t": "即履舄。鞋的通称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5211wx','牍','1','dú','片','12','','[{"pinyin": "dú", "defs": [{"meaning": "(形声。从片,卖声。“片”,本指木头竖剖成的一半。古时用木片作书写材料。故从“片”。本义:古代写字用的木片,也称木简)。"}, {"meaning": "同本义。", "cites": [{"t": "牍,书版也。长一尺,既书曰牍,未书曰椠。", "b": "《说文》"}, {"t": "与人尺牍。", "b": "《史记·陈遵传》"}, {"t": "削牍为疏。", "b": "《史记·游侠原涉传》。注:“木简也。”"}, {"t": "吏乃书牍背示之。", "b": "《史记·周勃传》"}, {"t": "握牍持笔。", "b": "杨修《答临淄侯笺》"}], "words": [{"w": "牍背", "t": "狱吏于书板背面书写文句。后用为遭受冤狱的典实。"}]}, {"meaning": "引申为公文。", "cites": [{"t": "无丝竹之乱耳,无案牍之劳形。", "b": "唐·刘禹锡《陋室铭》"}], "words": [{"w": "牍尾", "t": "文书的末端"}, {"w": "牍书", "t": "官署文书。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5212wx','傥','1','tǎng','亻','12','','[{"pinyin": "tǎng", "defs": [{"meaning": "(形声。从人,党声。本义: 洒脱不拘,不拘于俗)。"}, {"meaning": "同本义。", "cites": [{"t": "赞陈汤傥荡。", "b": "《汉书·傅常郑甘陈段传》。注:“无行检也。”"}, {"t": "貌若傥荡不备。", "b": "《汉书·史丹传》"}], "words": [{"w": "倜傥", "t": "洒脱;不拘束。"}]}, {"meaning": "怅然自失,恍惚。", "cites": [{"t": "文候傥然,终日不言。", "b": "《庄子·田子方》"}], "words": [{"w": "傥然", "t": "失志的样子"}, {"w": "傥莽", "t": "怅然自失。"}]}, {"meaning": "表示假设,相当于“倘若”、“如果”。", "cites": [{"t": "傥所谓天道,是邪?非邪?", "b": "《史记·伯夷传》"}], "words": [{"w": "傥若;傥使", "t": ""}]}, {"meaning": "偶然,意外地。", "cites": [{"t": "况荣宠贵盛,傥来物也,可恃以凌人乎。", "b": "欧阳修《新唐书》。又如:傥来(意外得来);傥然(偶然;侥幸)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5213wx','傧','1','bīn','亻','12','','[{"pinyin": "bīn", "defs": [{"meaning": "(形声。从人,宾声。本义:接引客人)。"}, {"meaning": "同本义。", "cites": [{"t": "傧,导也。", "b": "《说文》"}]}, {"meaning": "字亦作擯。注:“出接宾曰摈。”。", "cites": [{"t": "摈者,请期。", "b": "《仪礼·士冠礼》。注:“在主人曰摈,在客曰介。”"}, {"t": "卿为上摈,大夫为承摈,士为绍摈。", "b": "《仪礼·聘礼》"}, {"t": "若有祭祀、宾客、丧纪,则摈。", "b": "《周礼·天官·内小臣》"}, {"t": "掌九仪之宾客摈相之礼。", "b": "《周礼·秋官·司仪》。注:“出接宾曰摈,入诏礼曰相。”"}], "words": [{"w": "傧士", "t": "引导初为士者进见于王"}, {"w": "傧相", "t": "迎宾称傧,赞礼称相。"}]}, {"meaning": "陈列,摆。", "cites": [{"t": "傧尔笾豆。", "b": "《诗·小雅·常棣》"}]}, {"meaning": "排斥,抛弃。", "cites": [{"t": "傧厥亲。", "b": "《逸周书》"}, {"t": "诸儒生相与排傧,不容于齐。", "b": "《汉书·主父偃传》"}]}, {"meaning": "尊敬。", "cites": [{"t": "山川,所以傧鬼神也。", "b": "《礼记·礼运》"}]}, {"meaning": "迎接客人的人。", "cites": [{"t": "其摈于天子也。", "b": "《礼记·曲礼下》。疏:“摈,谓天子接宾客之人也。”"}, {"t": "桓公令傧者延而上。", "b": "《管子·小问》"}, {"t": "傧者以告列子。", "b": "《庄子·列御寇》"}], "words": [{"w": "傧相", "t": "婚礼中陪伴新郎新娘的男子和女子 摈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5214wx','遑','1','huáng','辶','12','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从辵(chuò),皇声。本义:急迫)。"}, {"meaning": "同本义。", "cites": [{"t": "墨子遑遑,闵世也。", "b": "《盐铁论·散不足》"}], "words": [{"w": "遑急", "t": "急迫不安"}, {"w": "遑遽", "t": "急迫不安,恐惧慌张。"}]}, {"meaning": "恐惧。", "cites": [{"t": "权于是大怒,手剑欲击之,侍坐者莫不遑遽。", "b": "《三国志·虞翻传》"}, {"t": "戚戚然以至于死,此天民之遑遽者也。", "b": "《列子·杨朱》"}, {"t": "满堂变容,迥遑如失。", "b": "谢庄《月赋》"}, {"t": "仲达闻阵而惕惕,子丹望风而遑遑!", "b": "明·梦觉道人《三刻拍案惊奇》"}]}, {"meaning": "空闲;闲暇。", "cites": [{"t": "遑,暇也。", "b": "《玉篇》"}, {"t": "何斯违斯?莫敢或遑。", "b": "《诗·召南·殷其雷》"}, {"t": "自朝至于日中昃,不遑暇食,用咸和万民。", "b": "《书·无逸》。孔颖达疏:遑,亦暇也。重言之者,古人自有复语。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5215wx','傩','1','nuó','亻','12','','[{"pinyin": "nuó", "defs": [{"meaning": "(形声。从人,难声。本义:步行有节度)。"}, {"meaning": "同本义。", "cites": [{"t": "巧笑之傩,佩玉之傩。", "b": "《诗·卫风·竹竿》"}]}, {"meaning": "指古迎神赛会。", "cites": [{"t": "乡人傩,朝服而立于阼阶。(阼:古指东面的台阶。)", "b": "《论语·乡党》"}], "words": [{"w": "傩祓", "t": "驱除疫鬼,祓除灾邪"}, {"w": "傩逐", "t": "驱除疫鬼仪式中所唱的歌"}, {"w": "傩鼓", "t": "驱除疫鬼仪式中敲击的鼓声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5216wx','遁','1','dùn','辶','12','','[{"pinyin": "dùn", "defs": [{"meaning": "(形声。从辵(chuò),盾声。本义:逃避)。"}, {"meaning": "同本义。", "cites": [{"t": "遁,迁也。", "b": "《说文》"}, {"t": "遁,避也。", "b": "《广雅·释诂三》"}, {"t": "遁,犹回避也。", "b": "《后汉书·杜林传》注"}, {"t": "阳遁而不能蒸。", "b": "《国语·周语》"}, {"t": "平当逡遁有耻。", "b": "《汉书·隽疏干薛平传赞》"}], "words": [{"w": "遁隐", "t": "避世隐居"}, {"w": "遁天", "t": "逃遁天理,违背自然"}, {"w": "遁命", "t": "逃避任命"}, {"w": "遁俗", "t": "犹言逃避世俗"}, {"w": "遁避", "t": "犹逃避。"}]}, {"meaning": "逃跑,逃走。", "cites": [{"t": "一曰逃也。", "b": "《说文》"}, {"t": "晋将遁矣。", "b": "《国语·楚语》"}, {"t": "敌弃炮仓皇遁。", "b": "清·徐珂《清稗类钞·战事类》"}, {"t": "虎大骇,远遁。", "b": "唐·柳宗元《三戒》"}], "words": [{"w": "遁世离群", "t": "逃离人世,过隐居生活"}, {"w": "遁亡", "t": "逃亡"}, {"w": "遁退", "t": "逃跑退却"}, {"w": "遁奔", "t": "逃奔。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5217wx','徨','1','huáng','彳','12','','[{"pinyin": "huáng", "defs": [{"meaning": "心神不安的。", "cites": [{"t": "侧焉徨徨商去留。--龚自珍《尊隐》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5218wx','媭','1','xū','女','12','','[{"pinyin": "xū", "defs": [{"meaning": "古代楚人对姐姐的称谓。", "cites": [{"t": "贾侍中说:楚人谓姊为媭。", "b": "《说文》"}]}, {"meaning": "女子人名用字。", "cites": [{"t": "媭,女字也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5219wx','畲','1','shē shé','田','12','','[{"pinyin": "shē", "defs": [{"meaning": "火耕，焚烧田地里的草木，用草木灰做肥料的耕作方法。", "cites": [{"t": "新畴复应畬。--陶渊明《和刘柴桑》", "b": ""}]}, {"meaning": "又如：畬种山林。"}, {"meaning": "火耕地，指粗放耕种的田地。", "cites": [{"t": "长刀短笠去烧畬畬。--刘禹锡《竹枝词》", "b": ""}]}, {"meaning": "又如：畬刀；畬田；畬耕(指用刀耕火种的方法耕种田地)。"}, {"meaning": "中国少数民族，主要分布于福建省、浙江省。"}]}, {"pinyin": "shé", "defs": [{"meaning": "1.姓。唐代有畲钦。见《通志．氏族五》。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5220wx','弑','1','shì','弋','12','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从杀,式声。本义:古代统治阶级称子杀父、臣杀君为“弑”)同本义。", "cites": [{"t": "弑,臣杀君也。", "b": "《说文》"}, {"t": "凡自虐其君曰弑,自外曰戕。", "b": "《左传·宣公十八年》"}, {"t": "放弑其君则残之。", "b": "《周礼·大司马》"}, {"t": "君臣未尝相弑也。", "b": "《礼记·明堂位》"}, {"t": "万乘之国弑其君者,必千乘之家。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "弑虐", "t": "指弑君"}, {"w": "弑君;弑母", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5221wx','颌','1','gé hé','页','12','','[{"pinyin": "gé", "defs": [{"meaning": "姓。"}]}, {"pinyin": "hé", "defs": [{"meaning": "多数脊椎动物构成口腔上下部的骨骼和肌肉组织。上部称上颌;下部称下颌,俗称“下巴”。", "cites": [{"t": "颔、颐,颌也。南楚谓之颔,秦晋谓之颌。颐,其通语也。", "b": "《方言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5222wx','翕','1','xī','羽','12','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从羽,合声。本义:闭合;收拢)。"}, {"meaning": "同本义。", "cites": [{"t": "蝘之兴,五日翕。", "b": "《夏小正》。按,飞起也。"}, {"t": "翕如也。", "b": "《论语》。皇疏:“习也。”"}, {"t": "伐翕伐张。", "b": "《荀子·议兵》"}, {"t": "唯南有箕,载翕其舌。", "b": "《诗·小雅·大东》"}, {"t": "将欲翕之,必固张之。", "b": "《韩非子·喻老》"}, {"t": "唇吻翕辟,不知何词。", "b": "《聊斋志异·促织》"}], "words": [{"w": "翕翼", "t": "合翼"}, {"w": "翕敛", "t": "收敛;收缩。"}]}, {"meaning": "聚集。", "cites": [{"t": "翕集家门,倾动人物。", "b": "《世说新语·排调》"}], "words": [{"w": "翕集", "t": "聚集"}, {"w": "翕翕", "t": "和合的样子"}, {"w": "翕聚", "t": "会聚。"}]}, {"meaning": "变动。", "cites": [{"t": "宇宙翕变,草木增荣。", "b": "李白《天长节度使鄂州刺史韦公德政碑》"}]}, {"meaning": "和好;一致。", "cites": [{"t": "兄弟既翕,和乐且湛。", "b": "《诗·小雅·常棣》"}, {"t": "君民翕然,倚以致平。", "b": "王安石《知人》"}], "words": [{"w": "翕合", "t": "协调一致"}, {"w": "翕应", "t": "谓相互响应"}, {"w": "翕绎", "t": "声音和谐相续。"}]}, {"meaning": "盛。", "cites": [{"t": "翕,盛也。", "b": "《广韵》"}], "words": [{"w": "翕如", "t": "指各种乐器同时演奏的盛况"}, {"w": "翕习", "t": "威盛的样子?。"}]}, {"meaning": "迅疾。", "cites": [{"t": "往来翕忽。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "翕欻", "t": "快速"}, {"w": "翕忽", "t": "形容疾速的样子"}, {"w": "翕习", "t": "疾快的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5223wx','釉','1','yòu','采','12','','[{"pinyin": "yòu", "defs": [{"meaning": "(形声。从采(biàn),由声。采象兽指爪分别之形。义为分辨。本义:是覆盖在陶器表面的玻璃质薄层) 同本义", "words": [{"w": "彩釉", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5224wx','鹆','1','yù','鸟','12','','[{"pinyin": "yù", "defs": [{"meaning": "鸟名。鸲鹆。又叫“八哥儿”。", "cites": [{"t": "啼鹆无知惊好梦,舞鸡有意报残钟。——《梼杌闲评。——明珠缘》", "b": ""}], "words": [{"w": "鹆歌", "t": "八哥儿的欢叫声"}, {"w": "鹆眼", "t": "八哥儿眼"}, {"w": "鹆研", "t": "有八哥儿眼的砚台。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5225wx','舜','1','shùn','夕','12','','[{"pinyin": "shùn", "defs": [{"meaning": "(象形。小篆字形。从舛(chuǎn),也象蔓连向背之形,舛亦声。本义:一种蔓草)。"}, {"meaning": "同本义。", "cites": [{"t": "舜,舜草也。楚谓之葍,秦谓之蔓,蔓地连华,象形。", "b": "《说文》"}]}, {"meaning": "假借为“蕣”。木槿。", "cites": [{"t": "有女同车,颜如舜华。", "b": "《诗·郑风·有女同车》"}], "words": [{"w": "舜华,舜英", "t": "木槿花"}, {"w": "舜颜", "t": "美如木槿花的容貌。"}]}, {"meaning": "中国传说中父系氏族社会后期部落联盟领袖 。姚姓,有虞氏,名重华,史称虞舜。相传因四岳推举,尧命他摄政。他巡行四方,除去鲧、共工、饯兜和三苗等四人。尧去世后继位,又咨询四岳,挑选贤人治理民事,并选拔治水有功的禹为继承人。", "cites": [{"t": "春风杨柳万千条,六亿神州尽舜尧。", "b": "毛泽东《送瘟神》"}], "words": [{"w": "舜恩", "t": "像古代圣君虞舜那样的浩荡恩惠"}, {"w": "舜韶", "t": "传说虞舜所作之乐"}, {"w": "舜跖分路", "t": "善恶不同"}, {"w": "舜巡", "t": "对皇帝巡行的美称。传说舜曾南巡至苍梧。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5226wx','貂','1','diāo','豸','12','','[{"pinyin": "diāo", "defs": [{"meaning": "(形声。从豸(zhì),召声。本义:哺乳动物。又称“貂鼠”。体细长,色黄或紫黑,种类很多) 同本义。", "cites": [{"t": "即解貂覆生。", "b": "清·方苞《左忠毅公逸事》"}, {"t": "金张藉旧业,七叶珥汉貂。", "b": "左思《咏史》"}], "words": [{"w": "貂珥", "t": "喻显贵"}, {"w": "貂扇", "t": "用貂尾做的扇子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5227wx','腈','1','jīng','月','12','','[{"pinyin": "jīng", "defs": [{"meaning": "指以三价氮基N≡为特征的一类化合物 ,并可从含氧酸得到,其法是从含氧酸的铵盐中完全除去水的成分;通常指以氰基为特征的化合物(如乙腈,苯腈),可从羧酸或它的酰胺得到,完全水解时产生酸。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5228wx','腌','1','yān ā','月','12','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从肉,奄声。本义:用盐浸渍食物)。"}, {"meaning": "同本义。", "cites": [{"t": "腌,渍肉也。", "b": "《说文》"}, {"t": "腌,酢,淹肉也。字亦作醃。", "b": "《苍颉篇》"}], "words": [{"w": "腌腊肉;腌陈", "t": "盐渍久贮的食物"}, {"w": "腌肉", "t": "指用盐浸渍肉块"}, {"w": "腌胙", "t": "盐腌的胙肉"}, {"w": "腌造", "t": "用盐或酱等浸渍加工鱼肉蔬菜瓜果等"}, {"w": "腌菜", "t": "用盐浸渍的蔬菜"}, {"w": "腌藏", "t": "腌渍储藏"}, {"w": "腌腊", "t": "把鱼、肉等用盐浸渍,然后风干、熏干。亦指腌制后风干的鱼、肉、鸡、鸭等。"}]}, {"meaning": "变咪。", "cites": [{"t": "兄长,已定这鱼腌了,不中仁兄吃。", "b": "《水浒传》"}]}]}, {"pinyin": "ā", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5229wx','腓','1','féi','月','12','','[{"pinyin": "féi", "defs": [{"meaning": "胫骨后的肉,即腿肚子。", "cites": [{"t": "腓大于股,难以趣走。", "b": "《韩非子》"}]}, {"meaning": "疾病。", "cites": [{"t": "毒泾尚多死,渡泸宁具腓。", "b": "南朝宋·鲍照《代苦热行》"}]}, {"meaning": "弊端。", "cites": [{"t": "十年执政虽咸腓,发廪有议常坚持。", "b": "元·许有壬《哀弃儿》"}]}, {"meaning": "古代剔除膝盖骨或断足的酷刑。", "cites": [{"t": "腓者,脱其膑也。", "b": "汉·班固《白虎通·五刑》"}], "words": [{"w": "腓辟", "t": "削去膝盖骨酷刑。"}]}, {"meaning": "病害;枯萎。多指草木。", "cites": [{"t": "秋日凄凄,百卉具腓。", "b": "《诗·小雅·四月》"}, {"t": "大漠穷秋塞草腓,孤城落日斗兵稀。", "b": "唐·高适《燕歌行》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5230wx','腆','1','tiǎn','月','12','','[{"pinyin": "tiǎn", "defs": [{"meaning": "(形声。从肉(月),典声。本义:丰厚)。"}, {"meaning": "同本义。", "cites": [{"t": "腆,设膳腆腆多也。", "b": "《说文》"}, {"t": "腆,厚也。", "b": "《小尔雅》"}, {"t": "自洗腆。", "b": "《书·酒诰》"}]}, {"meaning": "注:“善也。”。", "cites": [{"t": "不腆敝邑,为从者之淹。", "b": "《左传·僖公三十二年》"}], "words": [{"w": "腆仪", "t": "厚礼"}, {"w": "腆厚", "t": "丰厚"}, {"w": "腆赠", "t": "厚赠"}, {"w": "腆盛", "t": "丰盛。"}]}, {"meaning": "平善;美好。", "cites": [{"t": "不腆先君之祧。", "b": "《仪礼·聘礼》。注:“犹善也。”"}, {"t": "腆,美也。", "b": "《广雅》"}, {"t": "寡君有不腆之酒。", "b": "《仪礼·燕礼》"}, {"t": "币必诚,辞无不腆。", "b": "《礼记·郊特性》"}], "words": [{"w": "腆养", "t": "善养。"}]}, {"meaning": "厚颜,厚着脸皮 。", "words": [{"w": "腆冒", "t": "厚颜冒昧。"}]}, {"meaning": "惭愧 。", "words": [{"w": "腆然", "t": "羞涩"}, {"w": "腆愧", "t": "羞愧"}, {"w": "腆嘿", "t": "羞愧不语"}, {"w": "腆汗", "t": "因羞惭而出汗"}, {"w": "腆面", "t": "面有羞愧之色"}, {"w": "腆瞢", "t": "惭愧的样子"}, {"w": "腆颜", "t": "面带羞愧之色"}, {"w": "腼腆事仇", "t": "指不知羞耻地侍奉敌人。"}]}, {"meaning": "胸部或腹部向前挺出。", "cites": [{"t": "屠户横披了衣服,腆着肚子去了。", "b": "《儒林外史》"}], "words": [{"w": "腆胸;腆肚子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5231wx','腴','1','yú','月','12','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从肉,臾声。本义:腹下的肥肉)。"}, {"meaning": "同本义。", "cites": [{"t": "腴,腹下肥也。", "b": "《说文》"}, {"t": "君子不食圂腴。", "b": "《礼记·少仪》"}]}, {"meaning": "又。", "cites": [{"t": "冬右腴。", "b": ""}, {"t": "桀纣之君,垂腴尺余。", "b": "《论衡·语增》"}]}, {"meaning": "猪狗的肠子。"}, {"meaning": "油脂。", "cites": [{"t": "稻粱之味,甘而多腴。", "b": "《论衡》"}]}, {"meaning": "肥胖;脂肪多;肥美。", "cites": [{"t": "食止一日,膳无鲜腴。", "b": "《南史》"}]}, {"meaning": "丰裕。", "cites": [{"t": "处腴能约。", "b": "《晋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5232wx','腑','1','fǔ','月','12','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从肉,府声。本义:腑脏)。"}, {"meaning": "中医以胃、胆、膀胱、三焦、大小肠的总称 。亦泛指内脏器官。", "cites": [{"t": "六府。谓大肠、小肠、胃、膀胱、三焦、胆也。府者,为五藏宫府也。俗字作腑。", "b": "《白虎通·性情》"}], "words": [{"w": "腑脏", "t": "中医对人体内部器官的总称。"}]}]}]','jingmo-wenyan');
