INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5234wx','腱','1','jiàn','月','12','','[{"pinyin": "jiàn", "defs": [{"meaning": "(形声。从肉,建声。本义:肌腱)。"}, {"meaning": "特指供食用的蹄筋。", "cites": [{"t": "肥牛之腱,臑若芳些。", "b": "《楚辞·招魂》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5235wx','鱿','1','yóu','鱼','12','','[{"pinyin": "yóu", "defs": [{"meaning": "鱼名。鱿鱼也叫\\"柔鱼\\"。软体动物，形状略像乌贼，但体稍长，尾端两鳍相合呈菱形，体白色，有淡褐色斑点。生活在海洋中。肉可吃。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5236wx','鲀','1','tún','鱼','12','','[{"pinyin": "tún", "defs": [{"meaning": "鱼名,河鲀,河豚 。体圆,头部扁,至尾渐细,背面苍黑,有浓黑斑纹,腹面白,无鳞,体大者长二尺许,四五月间产卵,此时卵巢及肝皆含剧毒,栖近海。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5237wx','鲂','1','fáng','鱼','12','','[{"pinyin": "fáng", "defs": [{"meaning": "魚名。鳊鱼的古称。", "cites": [{"t": "其钓维何,维鲂及鱮。", "b": "《诗·小雅·采绿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5238wx','颍','1','yǐng','页','12','','[{"pinyin": "yǐng", "defs": [{"meaning": "(形声。从水,顷声。本义:水名。颍河,淮河最大的支流)。"}, {"meaning": "同本义。", "cites": [{"t": "颍,颍水,出颍州阳城乾山东入淮。", "b": "《说文》"}]}, {"meaning": "发源于河南省登封县,至安徽流入淮河。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5239wx','猢','1','hú','犭','12','','[{"pinyin": "hú", "defs": [{"meaning": "猴 。灵长类中除了人以外的成员", "words": [{"w": "猢狲王", "t": "猢狲大王。戏称蒙馆先生。猢狲,猴子,喻指顽皮的学童"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5240wx','猹','1','chá zhā','犭','12','','[{"pinyin": "chá", "defs": [{"meaning": "野兽名。像獾,喜欢吃瓜。"}]}, {"pinyin": "zhā", "defs": [{"meaning": "一种獾形野生动物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5241wx','猥','1','wěi','犭','12','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从犬,畏声。本义:狗叫声) 同本义。", "cites": [{"t": "猥,犬吠声。", "b": "《说文》"}]}, {"meaning": "许多,众多。", "cites": [{"t": "以人猥计其野。", "b": "《管子·八观》。注:“众也。”"}, {"t": "山水猥至。", "b": "《长笛赋》。注:“多也。”"}], "words": [{"w": "猥多", "t": "众多;繁多"}, {"w": "猥盛", "t": "众多"}, {"w": "猥众", "t": "众多"}, {"w": "猥滥", "t": "多而滥"}, {"w": "猥集", "t": "多而集中"}, {"w": "猥闶", "t": "高大的建筑物重叠。形容其多。"}]}, {"meaning": "害怕。", "cites": [{"t": "待要自己赶来擒捉,一来也被打得着实有些狼狈,二来也被这个母大虫打得猥了。他虽前世是个狐精转化,那狐狸毕竟也还怕那老虎。", "b": "《醒世姻缘传》"}]}, {"meaning": "谦词,等于说“辱”,指降低身分,用于他人对自己的行动。", "cites": [{"t": "猥自枉屈。", "b": "诸葛亮《出师表》"}]}, {"meaning": "假借为“委”。委曲;积聚。", "cites": [{"t": "兼受其猥。", "b": "《汉书·五行志》"}, {"t": "今猥被以大罪,恐其遂畔。", "b": "《汉书·王莽传》"}, {"t": "科别其条,勿猥勿并。", "b": "《汉书·董仲舒传》"}], "words": [{"w": "猥计", "t": "总计"}, {"w": "猥集", "t": "聚集。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5242wx','飓','1','jù','风','12','','[{"pinyin": "jù", "defs": [{"meaning": "发生在大西洋西部和西印度群岛一带的强烈的热带海洋风暴，夏秋季多发，风力常达十级以上，同时伴有暴雨，可造成灾害。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5243wx','觞','1','shāng','角','12','','[{"pinyin": "shāng", "defs": [{"meaning": "(形声。从角,傷(shāng)省声。金文从“爵”。本义:古代盛酒器) 同本义。", "cites": [{"t": "觞,爵实曰觞,虚曰觯。", "b": "《说文》"}, {"t": "请行觞。", "b": "《礼记·投壶》"}, {"t": "引壶觞以自酌,眄庭柯以怡颜。", "b": "晋·陶渊明《归去来兮辞》"}], "words": [{"w": "觞勺", "t": "指觞与勺。都是盛酒器"}, {"w": "觞令", "t": "即酒令。今俗谓猜拳、划拳"}, {"w": "觞豆", "t": "酒器与笾豆。皆为饮食的用具。借喻饮食"}, {"w": "觞爵", "t": "酒器"}, {"w": "觞觥", "t": "泛指酒器"}, {"w": "觞酌", "t": "饮酒器。"}]}, {"meaning": "向人敬酒。", "cites": [{"t": "管仲觞桓公。", "b": "《吕氏春秋》"}, {"t": "觞酒豆肉。", "b": "《礼记·表记》"}, {"t": "王觞将军。", "b": "《战国策·秦策》"}, {"t": "楚王觞之。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "觞客", "t": "宴飨宾客"}, {"w": "觞奠", "t": "酹酒祭奠"}, {"w": "觞祝", "t": "敬酒祝愿"}, {"w": "觞行", "t": "行觞,传杯。"}]}, {"meaning": "饮,喝。", "cites": [{"t": "一觞一咏,亦足以畅叙幽情。", "b": "王羲之《兰亭集序》"}], "words": [{"w": "觞歌", "t": "饮酒放歌"}, {"w": "觞弊", "t": "饮酒时以为笑乐"}, {"w": "觞燕", "t": "酒宴;饮宴"}, {"w": "觞饮", "t": "执杯而饮"}, {"w": "觞次", "t": "宴饮之所。"}]}, {"meaning": "宴请。", "cites": [{"t": "[楚襄王]谓宋玉曰:“寡人欲觞群臣,何以娱之?”", "b": "傅毅《舞赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5244wx','觚','1','gū','角','12','','[{"pinyin": "gū", "defs": [{"meaning": "(形声。从角,瓜声。本义:中国古代盛行于商代和西周的一种酒器,用青铜制成,口作喇叭形,细腰,高足,腹部和足部各有四条棱角,容量3升,一说是2升)。"}, {"meaning": "同本义。", "cites": [{"t": "觚,乡饮酒之爵也。一曰觞受三升者谓之觚。", "b": "《说文》"}, {"t": "二觚。", "b": "《仪礼·特牲礼记》。注:“爵一升,觚二升,觯三升,角四升,散五升。”"}, {"t": "执觞觚杯豆而不醉。", "b": "《大戴礼记·曾子事父母》"}, {"t": "坐取觚洗。", "b": "《仪礼·燕礼》"}, {"t": "子曰:“觚不觚,觚哉!觚哉!”", "b": "《论语·雍也》"}, {"t": "左边几上文王鼎箸香盒,右边几上汝窑美人觚。", "b": "《红楼梦》"}], "words": [{"w": "觚不觚", "t": "觚不成其为觚。形容似像而又不像的意思"}, {"w": "千盅百觚;美人觚", "t": "饰有美人图案的饮酒器。"}]}, {"meaning": "古代一种写字用的木板。", "cites": [{"t": "或操觚以率尔,或含毫而邈然。", "b": "晋·陆机《文赋》"}], "words": [{"w": "操觚", "t": "意即拿木简写文章"}, {"w": "觚牍", "t": "竹简木札。古代用以写字,也指书信"}, {"w": "觚简", "t": "古代书写用的木简。借指书籍。"}]}, {"meaning": "有棱角的器物。", "cites": [{"t": "破觚而为圜。", "b": "《史记·酷吏传》。索隐:“觚八棱有隅者。”汉书注:“方也。”"}]}, {"meaning": "法。", "cites": [{"t": "自削以觚。", "b": "《太玄·大》。注:“法也。”"}], "words": [{"w": "绳之以觚", "t": "犹绳之以法。"}]}, {"meaning": "剑柄。", "cites": [{"t": "操其觚,招其末,则庸人能以制胜。", "b": "《淮南子·主术》"}], "words": [{"w": "操其觚", "t": "抓住剑柄"}, {"w": "剑觚", "t": "剑柄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5245wx','猱','1','náo','犭','12','','[{"pinyin": "náo", "defs": [{"meaning": "兽名 。猿属。身体便捷,善攀援。又名“狨”或“猕猴”。", "cites": [{"t": "毋教猱升木。", "b": "《诗·小雅·角弓》"}], "words": [{"w": "猱升", "t": "猿猱上树。比喻像猿猴似地轻捷攀登 “惚”。"}]}, {"meaning": "形容轻捷、轻快。", "cites": [{"t": "猱进鸷击。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "猱进", "t": "轻捷地前进"}, {"w": "猱援", "t": "轻捷攀援"}, {"w": "猱狞", "t": "轻捷勇猛。"}]}]}]','jingmo-wenyan');
