('5246wx','颎','1','jiǒng','页','12','','[{"pinyin": "jiǒng", "defs": [{"meaning": "光;明亮", "words": [{"w": "颎耀", "t": "光耀"}, {"w": "颎光", "t": "光明"}, {"w": "颎颎", "t": "光亮的样子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5247wx','飧','1','sūn','飠','12','','[{"pinyin": "sūn", "defs": [{"meaning": "(会意。从夕,从食。晚上吃的食品。本义:晚上的饭食)。"}, {"meaning": "同本义。", "cites": [{"t": "飧,餔也。", "b": "《说文》"}, {"t": "吾小人辍飧饔以劳吏者,且不得暇。", "b": "柳宗元《种树郭橐驼传》"}], "words": [{"w": "飧饔", "t": "晚饭和早饭。"}]}, {"meaning": "熟食。", "cites": [{"t": "不素飧兮。", "b": "《诗·魏风·伐檀》。传:“熟食曰飧。”"}, {"t": "飧五牢。", "b": "《周礼·掌客》。注:“客始至致,小礼也。”"}, {"t": "宰夫朝服设飧。", "b": "《仪礼·聘礼》。注:“食不备礼曰飧。”"}, {"t": "飧有陪鼎。", "b": "《左传·昭公五年》"}, {"t": "盘飧市远无兼味,樽酒家贫只旧醅。", "b": "杜甫《客至》"}], "words": [{"w": "飧牵", "t": "熟食和牲口。"}]}, {"meaning": "吃晚饭。", "cites": [{"t": "贤者与民并耕而食,饔飧而治。", "b": "《孟子·滕文公上》赵岐《注》、朱熹《集注》并云:“饔飧,熟食也;朝曰饔,夕曰飧。”此处作动词。"}]}, {"meaning": "用水泡饭。", "cites": [{"t": "君未覆手,不敢飧。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
