INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5250wx','亵','1','xiè','亠','12','','[{"pinyin": "xiè", "defs": [{"meaning": "(形声。从衣,执声。本义:贴身的内衣) 同本义 。也指家居所穿的便服。", "cites": [{"t": "亵,私服也。", "b": "《说文》"}, {"t": "思有短褐之亵。", "b": "班固《汉书》"}, {"t": "季康子之母死,陈亵衣。", "b": "《礼记·檀弓下》"}], "words": [{"w": "亵衣", "t": "私服,家居的便服"}, {"w": "亵绊", "t": "内衣"}, {"w": "亵服", "t": "家居所穿的便服"}, {"w": "亵裘", "t": "平时家居所穿的皮衣。"}]}, {"meaning": "轻慢,轻佻地亲近。", "cites": [{"t": "亵,狎也。", "b": "《广雅》"}, {"t": "祭服敝则焚之。", "b": "《礼记·曲礼上》。注:“不欲人亵之。”"}, {"t": "亵玩焉。(玩弄。亵:亲近而不庄重。焉:这里相当于现代语的“啊”、“呀”)。", "b": "宋·周敦颐《周元公集·爱莲说》"}, {"t": "有亵众圣,甚非尊贤之理。", "b": "《封神演义》"}], "words": [{"w": "亵体", "t": "不体面"}, {"w": "亵尊", "t": "降低身分"}, {"w": "猥亵", "t": "淫乱;下流行为"}, {"w": "亵狎", "t": "轻慢玩弄"}, {"w": "亵人", "t": "轻慢无礼的人。"}]}, {"meaning": "亲近;得宠的。", "cites": [{"t": "廷臣辨之于朝,亵臣争之于旁。", "b": "唐·孙樵《武皇遗剑录》"}, {"t": "调也,君之亵臣也。", "b": "《礼记·檀弓下》"}], "words": [{"w": "亵人", "t": "宠幸的人"}, {"w": "亵臣", "t": "亲近宠幸的臣子"}, {"w": "亵近", "t": "亲近宠幸"}, {"w": "亵玩", "t": "亲近而玩弄"}, {"w": "亵御", "t": "亲近侍从的人。"}]}, {"meaning": "肮脏。", "cites": [{"t": "亵衣衾,不见里。", "b": "《礼记》"}], "words": [{"w": "亵器", "t": "指大小便所用的器具;化妆、梳洗、沐浴用的器具"}, {"w": "亵语", "t": "污秽的语言。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5251wx','脔','1','luán','肉','12','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从肉。羉(luán)声。本义:小块肉)。"}, {"meaning": "同本义。", "cites": [{"t": "一曰切肉,脔也。", "b": "《说文》"}, {"t": "嘬谓一举尽脔。", "b": "《礼记·曲记》注"}, {"t": "尝一脔肉,而知一镬之味。", "b": "《淮南子·说林训》"}], "words": [{"w": "脔脔", "t": "切成小块的肉"}, {"w": "脔脍", "t": "切成块的鱼肉。"}]}, {"meaning": "切肉成块。", "cites": [{"t": "脔,臞也。", "b": "《说文》"}, {"t": "棘人脔脔兮。", "b": "《诗·桧风·素冠》"}, {"t": "取新鲤鱼,去鳞讫则脔。", "b": "《齐民要术·作鲊》"}, {"t": "未受牺牛大羹之和,久在煎熬脔割之间。", "b": "《后汉书·边让传》"}], "words": [{"w": "脔制", "t": "分割而制伏之"}, {"w": "脔割", "t": "分割;切碎"}, {"w": "脔股", "t": "谓割股疗疾以示虔敬"}, {"w": "脔身", "t": "分割身体。"}]}]}]','jingmo-wenyan');
