INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5253wx','痣','1','zhì','疒','12','','[{"pinyin": "zhì", "defs": [{"meaning": "皮肤上一种先天性的色素沉着区。", "cites": [{"t": "痣,黑子。", "b": "《广韵》"}, {"t": "初,贵嫔生而有赤痣在左臂,治之不灭。", "b": "《梁书·高祖丁贵嫔传》"}], "words": [{"w": "痣疣", "t": "痣和疣。都是赘生在皮肤上的不痛不痒的小疙瘩。比喻多余而无用的东西。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5254wx','痨','1','láo','疒','12','','[{"pinyin": "láo", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,劳声。本义:积劳瘦削)。"}, {"meaning": "劳损病。", "cites": [{"t": "疲,今人以积劳瘦削为痨病。", "b": "《正字通》"}], "words": [{"w": "痨怯", "t": "虚劳"}, {"w": "痨伤", "t": "犹劳伤。"}]}]}]','jingmo-wenyan');
