INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5256wx','痞','1','pǐ','疒','12','','[{"pinyin": "pǐ", "defs": [{"meaning": "(形声。从疒(chuáng),否声。本义:病名。胸中懑闷结块)。"}, {"meaning": "同本义。", "cites": [{"t": "痞,痛也。", "b": "《说文》。按,腹内结滞而痛。"}], "words": [{"w": "痞利", "t": "痞结又下痢"}, {"w": "痞气", "t": "脾脏郁结成块的病。即慢性脾脏肿大"}, {"w": "痞疾", "t": "腹内郁结成块的病"}, {"w": "痞硬", "t": "中医谓郁结成硬块"}, {"w": "痞胀", "t": "郁结胀闷"}, {"w": "痞结", "t": "腹内郁结成块;喻阻塞不通"}, {"w": "痞塞", "t": "郁结,阻滞不通"}, {"w": "痞满", "t": "郁结懑闷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5257wx','痤','1','cuó','疒','12','','[{"pinyin": "cuó", "defs": [{"meaning": "痈。", "cites": [{"t": "痤,小肿也。从疒,坐声。", "b": "《说文》"}, {"t": "金星之山多天婴,可以已痤。", "b": "《山海经·中山经》"}], "words": [{"w": "痤疽", "t": "犹痈疽,毒疮"}, {"w": "痤人", "t": "患痈疮的人"}, {"w": "痤然", "t": "像痈疽似的"}, {"w": "痤睢", "t": "痤疽。"}]}, {"meaning": "疖子。", "cites": [{"t": "郁乃痤。", "b": "《素问·生桉通天论》。注:“色赤瞋愤,内蕴血脓,形小而大如酸枣,或如气豆,此皆阳气内郁所为。”"}], "words": [{"w": "痤赘", "t": "小疖。比喻小祸害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5258wx','痫','1','xián','疒','12','','[{"pinyin": "xián", "defs": [{"meaning": "俗称羊痫风、羊癫风、羊角风 。中枢神经系统的一种疾病。患此病的人,常突然倒地,口吐涎沫,手足痉挛,口里发出羊豕的叫声。", "cites": [{"t": "心脉满大,痫瘛筋挛。", "b": "《素问》"}], "words": [{"w": "痫眩", "t": "因癫痫发作而眩晕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5259wx','痧','1','shā','疒','12','','[{"pinyin": "shā", "defs": [{"meaning": "中医称霍乱、中暑、肠炎等急性病,又名“痧气”、“痧胀”。", "cites": [{"t": "他两个又在路上中了暑,发了痧,不能赶路。", "b": "《文明小史》"}]}, {"meaning": "疹子 。指皮肤出现红点如粟、以指循皮肤稍有阻碍的疹点。清·邵新甫在《临证指南医案》按语中说:“痧者,疹之通称,有头粒如粟。”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5260wx','赓','1','gēng','贝','12','','[{"pinyin": "gēng", "defs": [{"meaning": "(形声。从贝,庚声。本义:连续,继续)。"}, {"meaning": "同本义。", "cites": [{"t": "乃赓载歌曰:“元首明哉,股肱良哉,庶事康哉。", "b": "《书·益稷》"}], "words": [{"w": "赓扬", "t": "继续"}, {"w": "赓载", "t": "相续而成"}, {"w": "赓咏", "t": "相继咏和"}, {"w": "赓衍", "t": "延续演变"}, {"w": "赓飏", "t": "飞扬轻举连续而歌。"}]}, {"meaning": "酬答、应和。", "cites": [{"t": "赖有西邻好诗句,赓酬终日自忘饥。", "b": "宋·张耒《张右史集·屋东》"}], "words": [{"w": "赓和", "t": "唱和;酬谢、赠答之意"}, {"w": "赓歌", "t": "作歌唱和;连续不断的歌声,表示欢乐"}, {"w": "赓酬", "t": "作诗相唱和、赠答。"}]}, {"meaning": "赔偿。", "cites": [{"t": "智者有什倍人之功,愚者有不赓本之事。", "b": "《管子·国蓄》"}], "words": [{"w": "赓本", "t": "抵偿成本。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5261wx','竦','1','sǒng','立','12','','[{"pinyin": "sǒng", "defs": [{"meaning": "(会意。从立,从束。立,站着。束,约束。本义:肃敬;恭敬)。"}, {"meaning": "同本义。", "cites": [{"t": "竦,敬也。", "b": "《说文》。段注:“敬者,肃也。”"}, {"t": "巫从旁望空代祝,唇吻翕辟,不知何词。各各竦立以听。", "b": "《聊斋志异·促织》"}], "words": [{"w": "竦然", "t": "肃然起敬的样子"}, {"w": "竦听", "t": "肃然敬听"}, {"w": "竦立", "t": "恭敬的站着"}, {"w": "竦敬", "t": "肃然起敬"}, {"w": "竦惧", "t": "肃立惶恐。"}]}, {"meaning": "(企立,伸长脖子、提起脚跟站着)。", "cites": [{"t": "寡人将竦意而览焉。", "b": "《汉书·东方朔传》"}, {"t": "竦余身而顺止兮。", "b": "《后汉书·张衡传》"}, {"t": "士卒皆山东人,竦而望归。", "b": "《汉书·韩王信传》"}, {"t": "夫临搏而企竦,闻乐而窃者,或有赏音而识道也。", "b": "《文选·曹植·求自试表》"}], "words": [{"w": "竦首", "t": "抬头"}, {"w": "竦企", "t": "引领举踵以待"}, {"w": "竦耳", "t": "竖起耳朵。"}]}, {"meaning": "耸立。", "cites": [{"t": "水何澹澹,山岛竦峙。", "b": "《乐府诗集·曹操·步出夏门行》"}], "words": [{"w": "竦杰", "t": "高高地耸立"}, {"w": "竦立", "t": "竖立"}, {"w": "竦峙", "t": "耸立,高耸峙立"}, {"w": "竦拔", "t": "高耸挺拔"}, {"w": "竦峭", "t": "高峻;陡峭"}, {"w": "竦竦", "t": "高耸貌"}, {"w": "竦垒", "t": "耸立叠起"}, {"w": "竦石", "t": "耸立的石头"}, {"w": "竦秀", "t": "挺拔秀丽;庄重文雅。"}]}, {"meaning": "往上跳。", "cites": [{"t": "若士举臂而竦身,遂入云中。", "b": "《淮南子·道应》"}, {"t": "举戈林竦,挥锋电灭。", "b": "《文选·木华·海赋》"}, {"t": "我很想借此算是竦身一摇,将悲哀摆脱。", "b": "《为了忘却的纪念》"}], "words": [{"w": "竦身", "t": "耸身。纵身向上跳"}, {"w": "竦辔", "t": "纵辔。谓骑马。"}]}, {"meaning": "振动;振作。", "cites": [{"t": "夫周秦之末,三五之隆,已尝专意散财,厚爵禄,竦精神,举天下以求之矣。", "b": "《汉书》"}], "words": [{"w": "竦神", "t": "振作精神"}, {"w": "竦健", "t": "振奋强健"}, {"w": "竦动", "t": "抖动;震动。"}]}, {"meaning": "执;握。", "cites": [{"t": "竦长剑兮拥幼艾,荪独宜兮为民正。", "b": "《楚辞·屈原·九歌·少司命》"}], "words": [{"w": "竦剑", "t": "仗剑;持剑。"}]}, {"meaning": "恐惧。", "cites": [{"t": "竦,惧也。", "b": "《尔雅·释诂》"}, {"t": "不戁(nǎn恐惧)不竦,百禄是总。", "b": "《诗·商颂·长发》"}, {"t": "弃甲负弩,战竦而却。", "b": "《韩非子·初见秦》"}, {"t": "怒形则千里竦,威振则万物伏。", "b": "《汉书·李广传》"}, {"t": "他们走不上二三十步远,忽听得背后“哑”…的一声大叫;两个人都竦然的回过头。", "b": "鲁迅《药》"}, {"t": "即拜(班)伯为定襄太守,定襄闻伯素贵,年少,自请治剧,畏其下车作威,吏民竦息。", "b": "《汉书·叙传》"}], "words": [{"w": "竦息", "t": "恐惧不安的样子"}, {"w": "竦动", "t": "惊动"}, {"w": "竦然", "t": "惊惧的样子。"}]}]}]','jingmo-wenyan');
