INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5263wx','啻','1','chì','口','12','','[{"pinyin": "chì", "defs": [{"meaning": "(形声。从口,帝声。本义:仅仅,只有) 同本义 。——常用在表示疑问或否定的字后,组成“不啻”,“匪啻”,“奚啻”等词,在句中起连接或比况作用", "words": [{"w": "不啻如此", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5264wx','颏','1','kē ké','页','12','','[{"pinyin": "kē", "defs": [{"meaning": "下颌下方或下颌支之间的表面,通称“下巴”。", "cites": [{"t": "颏,颐下也。", "b": "《玉篇》"}, {"t": "我手承颏肘拄座。", "b": "韩愈《记梦》"}], "words": [{"w": "颏颐", "t": "下巴和腮帮子"}, {"w": "颏颔", "t": "下巴"}, {"w": "颏颊", "t": "脸面,面子。"}]}]}, {"pinyin": "ké", "defs": [{"meaning": "", "words": [{"w": "红点颏,蓝点颏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5265wx','鹇','1','xián','鸟','12','','[{"pinyin": "xián", "defs": [{"meaning": "(形声。从鸟,闲声。本义:鸟名。鹇属各种鸟的通称。通指白鹇) 同本义 。产于中国南部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5266wx','阑','1','lán','门','12','','[{"pinyin": "lán", "defs": [{"meaning": "同本义。引申为栏杆。", "cites": [{"t": "阑,门遮也。", "b": "《说文》"}, {"t": "虽仪之所甚愿为门阑之厮者,亦无先大王。", "b": "《史记·楚世家》"}, {"t": "今公之牛马老于阑牢,不胜服也。", "b": "《晏子春秋·内篇谏下》"}, {"t": "门阑多喜色,女婿近乘龙。", "b": "杜甫《李监宅》"}, {"t": "怒发冲冠,凭阑处,潇潇雨歇。", "b": "宋·岳飞《满江红》"}], "words": [{"w": "阑槛", "t": "栏杆"}, {"w": "阑楯", "t": "栏杆"}, {"w": "阑牢", "t": "围着栅栏用来饲养牛马的地方"}, {"w": "阑圈", "t": "家畜饲养圈。"}]}, {"meaning": "环状物。", "cites": [{"t": "你看月阑,明日敢有风也。", "b": "元·王实甫《西厢记》"}]}, {"meaning": "画的圈儿。", "cites": [{"t": "张千,取石灰来,在阶下画个阑儿。", "b": "元·李行道《灰阑记》"}]}, {"meaning": "残;将尽。", "cites": [{"t": "白露凝兮岁将阑。", "b": "《宋孝武宣贵妃诛》"}, {"t": "夜阑卧听风吹雨。", "b": "宋·陆游《十一月四日风雨大作》"}, {"t": "林黛玉到四更将阑,方渐渐的睡去。", "b": "《红楼梦》"}], "words": [{"w": "阑暑", "t": "指暑气将尽的夏末"}, {"w": "阑单", "t": "精疲力尽的样子"}, {"w": "岁阑;夜阑人静;阑夕", "t": "夜晚。"}]}, {"meaning": "阻隔。", "cites": [{"t": "有河山以阑之,有周韩而间之。", "b": "《战国策·魏策三》"}]}, {"meaning": "衰退;衰落;消沉。", "cites": [{"t": "白发满头归得也,诗情酒兴渐阑珊。", "b": "白居易《咏怀》"}], "words": [{"w": "阑珊", "t": "衰减"}, {"w": "阑散", "t": "消沉。"}]}, {"meaning": "妄,擅自。", "cites": [{"t": "阑入尚方掖门。", "b": "《汉书·成帝纪》。注:“无符籍妄入宫曰阑。”"}], "words": [{"w": "阑入", "t": "妄入,擅自进入"}, {"w": "阑出", "t": "妄出,未得许可而擅自出去。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5267wx','阒','1','qù','门','12','','[{"pinyin": "qù", "defs": [{"meaning": "寂静。", "cites": [{"t": "林塘闻寂偏宜夜,烟火稀疏便似村。", "b": "《曲江夜思》"}], "words": [{"w": "阒静", "t": "寂静"}, {"w": "阒无人声", "t": "静得没有一点人声"}, {"w": "阒寥", "t": "寂静"}, {"w": "阒黑", "t": "漆黑。"}]}, {"meaning": "空虚。", "cites": [{"t": "窥其户,阒其无人。", "b": "《易·丰》"}], "words": [{"w": "阒旷", "t": "空阔"}, {"w": "阒如", "t": "空虚"}, {"w": "阒其无人", "t": "空荡荡无人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5268wx','阕','1','què','门','12','','[{"pinyin": "què", "defs": [{"meaning": "(形声。从门,癸(guǐ)声。本义:祭事结束而闭门)。"}, {"meaning": "同本义。引申为止息;终了。", "cites": [{"t": "阕,事已闭门也。", "b": "《说文》"}, {"t": "瞻彼阕者,虚室生白,吉祥止止。", "b": "《庄子·人间世》"}, {"t": "繁肴既阕,亦有寒羞。", "b": "张协《七命》"}]}, {"meaning": "尽;无剩余。", "cites": [{"t": "俾民心阕。", "b": "《诗·小雅·节南山》"}, {"t": "物物卬市,日阙亡储。", "b": "《汉书》。颜师古注:“阕,尽也。日阕,言当日即尽,不蓄积也。”"}]}, {"meaning": "旧指服丧期满。", "cites": [{"t": "于是三年礼阕,乃相与刊勒金石。", "b": "《山阳太守祝睦后碑》"}]}, {"meaning": "乐终。", "cites": [{"t": "阕,曲终为阕。", "b": "《古今韵会举要》"}, {"t": "主人答拜,乐阕。", "b": "《仪礼》"}]}, {"meaning": "乐曲。", "cites": [{"t": "歌数阕。", "b": "《史记·留侯世家》"}, {"t": "曲终阕尽,余弦更兴。", "b": "汉·马融《长笛赋》"}, {"t": "歌曲以阕为称。", "b": "宋·吴曾《能改斋漫录》"}]}, {"meaning": "乐一遍为一阕。", "cites": [{"t": "昔葛天氏之乐,三人操牛尾投足以歌八阕。", "b": "《吕氏春秋》"}]}, {"meaning": "空隙。", "cites": [{"t": "瞻彼阕者,虚室生白。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5269wx','粞','1','xī','米','12','','[{"pinyin": "xī", "defs": [{"meaning": "碎米。", "cites": [{"t": "碓下糠粞幸不乏,何妨相倚过余生。", "b": "陆游《老鸡》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5270wx','遒','1','qiú','辶','12','','[{"pinyin": "qiú", "defs": [{"meaning": "(形声。从辵(chuò),酋(qiú)声。本义:迫近)。"}, {"meaning": "同本义。", "cites": [{"t": "遒,迫也。", "b": "《说文》"}, {"t": "遒相迫些。", "b": "《楚辞·招魂》"}, {"t": "岁忽忽而遒尽兮,恐余寿之弗将。", "b": "《楚辞·九辩》"}], "words": [{"w": "遒尽", "t": "迫近于尽头。"}]}, {"meaning": "终竟;完尽。", "cites": [{"t": "肮脏仪刑在,惊呼岁月遒。", "b": "宋·苏轼《滕达道挽词二首》"}, {"t": "敷政优优,百禄是遒。", "b": "《诗·商颂·长发》"}], "words": [{"w": "遒变", "t": "骤变。"}]}, {"meaning": "急迫。也作“迺”。", "cites": [{"t": "遒,急也。", "b": "广雅·释诂一》"}], "words": [{"w": "遒迫", "t": "迫逐"}, {"w": "遒忽", "t": "匆遽;急速"}, {"w": "遒进", "t": "骤进,大有长进"}, {"w": "遒捷", "t": "短促急骤。"}]}, {"meaning": "强劲;强健;有力。", "cites": [{"t": "鳞鳞夕云起,猎猎晚风遒。", "b": "南朝宋·鲍照《上浔阳还都道中》"}], "words": [{"w": "遒文", "t": "文笔强劲有力"}, {"w": "遒逸", "t": "形容文章内容、词藻的强健奔放"}, {"w": "遒紧", "t": "形容诗文的刚健严谨"}, {"w": "遒丽", "t": "指书、画、语、文的强劲富丽。"}]}, {"meaning": "刚强。", "cites": [{"t": "库狄干鲜卑老公,斛律金敕勒老公,并性遒直,终不负汝。", "b": "《北史》"}]}, {"meaning": "坚固。", "cites": [{"t": "周公东征,四国是遒。", "b": "《诗·豳风》"}]}, {"meaning": "美好。", "cites": [{"t": "遒文丽藻,方驾曹王俊迈,联横许郭。", "b": "刘孝林《广绝交论》"}], "words": [{"w": "遒泽", "t": "美好而有光泽"}, {"w": "遒雅", "t": "美好风雅;不粗鄙"}, {"w": "遒旨", "t": "超逸的意旨。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5271wx','孳','1','zī','子','12','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从子,兹声。子,小孩子,是生殖的结果。本义:繁殖,生息)。"}, {"meaning": "同本义。", "cites": [{"t": "孳,汲汲生也。", "b": "《说文》"}, {"t": "孳,蕃也。", "b": "《声类》"}, {"t": "鸟兽孳尾。", "b": "《书·尧典》。传:“乳化曰孳。”"}, {"t": "其民孳阜无数。", "b": "《列子·汤问》"}]}, {"meaning": "增长。", "cites": [{"t": "以其有传类番孳之祥。", "b": "《周礼·天官·内宰》注"}, {"t": "孳荫万物。", "b": "《汉书·律历志上》"}, {"t": "孳货盐田。", "b": "鲍照《芜城赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5272wx','焯','1','chāo zhuō','火','12','','[{"pinyin": "chāo", "defs": [{"meaning": "把蔬菜放在开水里略微一煮就拿出来", "words": [{"w": "焯菠菜", "t": ""}]}]}, {"pinyin": "zhuō", "defs": [{"meaning": "明亮。", "cites": [{"t": "焯,明也。从火卓声。《周书》", "b": ""}]}, {"meaning": "曰:“焯见三有俊心。”——《说文》。", "cites": [{"t": "焯见三有俊心。", "b": "《书·立政》"}]}, {"meaning": "明彻;显明。", "cites": [{"t": "焯烁其陂。", "b": "扬雄《羽猎赋》"}, {"t": "公至无名臣,熏勋德焯著。", "b": "《大都路都总管姚公神道碑》"}], "words": [{"w": "焯著", "t": "显明;显著"}, {"w": "焯烁", "t": "光彩闪烁的样子"}, {"w": "燃然", "t": "昭著的样子"}, {"w": "焯焯", "t": "显著;昭然。"}]}, {"meaning": "照耀。", "cites": [{"t": "留得天章焯云汉。", "b": "《圆明园词》"}], "words": [{"w": "焯辉", "t": "光耀"}, {"w": "焯耀", "t": "光耀;昭著。"}]}, {"meaning": "火烧。", "cites": [{"t": "错蓍焯龟,比光道也。", "b": "《太玄·童》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5273wx','焜','1','kūn','火','12','','[{"pinyin": "kūn", "defs": [{"meaning": "明亮。", "cites": [{"t": "焜,煌也。从火,昆声。", "b": "《说文》"}, {"t": "焜耀寡人之望。", "b": "《左传·昭公三年》。服注:“明也。”"}], "words": [{"w": "焜燿", "t": "光彩夺目"}, {"w": "焜昱", "t": "光辉灿烂。"}]}, {"meaning": "色衰的样子。", "cites": [{"t": "焜黄华叶衰。", "b": "《文选·古辞长歌行》。注:“色衰貌也。”"}], "words": [{"w": "焜黄", "t": "色衰的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5274wx','焙','1','bèi','火','12','','[{"pinyin": "bèi", "defs": [{"meaning": "微火烘烤。", "cites": [{"t": "夜火焙茶香。", "b": "白居易《题施山人野居》"}], "words": [{"w": "焙炙", "t": "烘烤"}, {"w": "焙火", "t": "焙烘的火力"}, {"w": "焙茶", "t": "烘制茶叶"}, {"w": "焙烘", "t": "烘烤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5275wx','焱','1','yàn','火','12','','[{"pinyin": "yàn", "defs": [{"meaning": "光华,光焰。", "cites": [{"t": "焱,光华也。", "b": "《说文》"}, {"t": "日暾暾其西舍兮,阳焱焱而复顾。", "b": "《楚辞》"}, {"t": "纷翼翼以徐戾兮,焱回回其扬灵。", "b": "《文选·张衡·思玄赋》"}], "words": [{"w": "焱飞", "t": "火花飞舞的样子"}, {"w": "焱悠", "t": "火花飘舞"}, {"w": "焱焰", "t": "火焰"}, {"w": "焱焱", "t": "光采闪耀的样子"}, {"w": "焱攸", "t": "焱悠"}, {"w": "焱炎", "t": "形容太阳的光和热"}, {"w": "焱烘烘", "t": "火炽热的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5276wx','鹈','1','tí','鸟','12','','[{"pinyin": "tí", "defs": [{"meaning": "属于鹈鹕属的大型全蹼足的鸟。体长约二米,羽多白色,翼大,嘴长,嘴下有一个皮质的囊,可用以兜食鱼类。性喜群居,栖息在沿海湖沼河川地带。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5277wx','湛','1','zhàn','氵','12','','[{"pinyin": "zhàn", "defs": [{"meaning": "(形声。从水,甚声。本义:清澈透明)。"}, {"meaning": "同本义。", "cites": [{"t": "水木湛清华。", "b": "谢混《游西池》"}], "words": [{"w": "湛明", "t": "清滢明亮"}, {"w": "湛冽", "t": "清冽"}, {"w": "湛波", "t": "清波"}, {"w": "湛清", "t": "清澈"}, {"w": "湛然", "t": "清澈的样子"}, {"w": "湛湛", "t": "清明澄澈的样子。"}]}, {"meaning": "露厚重。", "cites": [{"t": "石林湛雨气,山月连阳晖。", "b": "清·谢芳连《孟夏山中晚坐》"}], "words": [{"w": "湛露", "t": "重露。"}]}, {"meaning": "深;深沉。", "cites": [{"t": "眼睛暴湛,牙齿横生。", "b": "《封神演义》"}], "words": [{"w": "湛浮", "t": "沉浮"}, {"w": "湛湛", "t": "水深的样子;深切的样子"}, {"w": "湛恩", "t": "深恩"}, {"w": "湛恩汪秽", "t": "恩泽深厚。"}]}, {"meaning": "饱满;盈满。", "cites": [{"t": "湛湛江水兮上有枫,目极千里兮伤春心。", "b": "《楚辞》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5278wx','渫','1','xiè','氵','12','','[{"pinyin": "xiè", "defs": [{"meaning": "淘,淘去泥污。", "cites": [{"t": "渫,除去也。从水,枼声。", "b": "《说文》"}, {"t": "井渫不食,为我心恻。", "b": "《易·井》"}]}, {"meaning": "排出气体或液体。", "cites": [{"t": "渫之以尾闾。", "b": "《文选·江赋》"}]}, {"meaning": "泄漏。", "cites": [{"t": "泰和二年,上以弥封官渫语于举人,敕自今女直司则用右选汉人封,汉人司则以女直司封。", "b": "《金史》"}]}, {"meaning": "散布;消散。", "cites": [{"t": "富人有爵,农民有钱,粟有所渫。", "b": "《汉书》"}], "words": [{"w": "渫云", "t": "飘散的云"}, {"w": "渫雨", "t": "飘洒的雨。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5279wx','湮','1','yān','氵','12','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从水,垔(yīn)声。本义:埋没,不被人所知道)。"}, {"meaning": "同本义。", "cites": [{"t": "始丧乱后,典章湮散。", "b": "《新唐书·魏征传》"}], "words": [{"w": "湮没不彰", "t": "埋没不显著"}, {"w": "湮佚", "t": "埋设,散失"}, {"w": "湮沉", "t": "湮沈;湮泯;湮昧;湮埋。埋没。"}]}, {"meaning": "淤塞;填塞;堵塞。", "cites": [{"t": "郁湮不育。", "b": "《左传·昭公二十九年》。注:“湮,塞也。”"}, {"t": "昔老禹之湮洪水,决江河。", "b": "《庄子》"}], "words": [{"w": "湮塞", "t": "堵塞。"}]}, {"meaning": "液体着物向四处散开。后作“洇(yīn)”。", "cites": [{"t": "绢布上写字,用姜汁磨及粉,则不湮开。", "b": "《物类相感志》"}]}, {"meaning": "水名 。伊水支流。在今河南省登封县西。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5280wx','湎','1','miǎn','氵','12','','[{"pinyin": "miǎn", "defs": [{"meaning": "(形声。从水,面声。本义:沉迷于酒)。"}, {"meaning": "同本义。", "cites": [{"t": "湎,沈于酒也。", "b": "《说文》"}, {"t": "罔敢湎于酒。", "b": "《书·酒诰》。郑注:“饮酒齐色曰湎。”"}, {"t": "天不湎尔以酒。", "b": "《诗·大雅·荡》"}, {"t": "湎于酒。", "b": "《谷梁传》"}], "words": [{"w": "湎淫", "t": "沉溺于酒色。"}]}, {"meaning": "沈迷,沈溺(因过度爱好而难以舍弃)。", "cites": [{"t": "故多言而类,圣人也,少言而法,君子也;多言无法,而流湎然,虽辩,小人也。", "b": "《荀子·非十二子》"}, {"t": "国家喜音湛湎,则语之非乐非命。", "b": "《墨子·鲁命》"}]}, {"meaning": "背,背向。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5281wx','湜','1','shí','氵','12','','[{"pinyin": "shí", "defs": [{"meaning": "水清的", "words": [{"w": "湜湜", "t": "水清澈的样子"}]}, {"meaning": "清廉的样子"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5282wx','渭','1','wèi','氵','12','','[{"pinyin": "wèi", "defs": [{"meaning": "古州名。"}, {"meaning": "北魏庄帝置。清代为巩昌府,治所在今甘肃省陇西县西南。"}, {"meaning": "辽置,在今辽宁省黑山县境。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5283wx','湍','1','tuān','氵','12','','[{"pinyin": "tuān", "defs": [{"meaning": "(形声。从水,耑(zhuān)声。本义:水势急速) 同本义。", "cites": [{"t": "湍,疾濑也。", "b": "《说文》"}, {"t": "水湍悍", "b": "《史记·河渠书》。集解:“疾也。”"}, {"t": "长濑湍流。", "b": "《楚辞·抽思》"}, {"t": "稻生于水,而不能生于湍濑之流。", "b": "《淮南子·说山》。注“急水也。”"}], "words": [{"w": "湍水", "t": "急流的水"}, {"w": "湍悍", "t": "水势急猛"}, {"w": "湍急", "t": "水势急速"}, {"w": "湍泷", "t": "形容水流急疾"}, {"w": "湍涛", "t": "激荡的水流"}, {"w": "湍瀑", "t": "水流急溅貌。"}]}, {"meaning": "急流的水。", "cites": [{"t": "急湍甚箭。", "b": "吴均《与朱元思书》"}], "words": [{"w": "急湍", "t": "急流"}, {"w": "湍洑", "t": "急流形成的旋涡"}, {"w": "湍渚", "t": "急流中的小洲"}, {"w": "湍鸣", "t": "急流的响声"}, {"w": "湍驶", "t": "急速的流水"}, {"w": "湍激", "t": "水流猛急"}, {"w": "湍波", "t": "急流的水。"}]}, {"meaning": "冲刷;冲击。", "cites": [{"t": "道果便近,而水湍石,不可漕。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5284wx','湫','1','jiǎo jiū qiū','氵','12','','[{"pinyin": "jiǎo", "defs": [{"meaning": "[地势]低下;低洼", "cites": [{"t": "湫宅闭门,不有椒房之势。", "b": "扬雄《法言》"}], "words": [{"w": "湫窄", "t": "低温狭小,谦称自己居处贫窘"}, {"w": "湫仄", "t": "低下狭窄"}, {"w": "湫阨", "t": "低小狭小"}, {"w": "湫凹", "t": "低洼"}, {"w": "湫居", "t": "低矮的住房"}]}]}, {"pinyin": "jiū", "defs": [{"meaning": "", "words": [{"w": "湫然", "t": "清静的样子。"}]}]}, {"pinyin": "qiū", "defs": [{"meaning": "水潭。", "cites": [{"t": "湫,湫隘下也。从水,秋声。春秋传曰:晏子之宅湫隘。", "b": "《说文》。按,训为下湿也。”"}, {"t": "湫隘嚣尘。", "b": "《左传·昭公三年》。注:“下也。”"}], "words": [{"w": "湫泊", "t": "水潭"}, {"w": "湫水", "t": "潭水。"}]}, {"meaning": "洞穴。", "cites": [{"t": "此之谓定性于大湫。", "b": "《吕氏春秋·审分》"}]}, {"meaning": "凝集;积滞。", "cites": [{"t": "勿使有所壅闭湫底。", "b": "《左传·昭公元年》。注:“集也。”"}], "words": [{"w": "湫底", "t": "积滞不畅"}, {"w": "湫淤", "t": "积滞不通。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5285wx','溲','1','sōu','氵','12','','[{"pinyin": "sōu", "defs": [{"meaning": "(形声。从水,叟声。本义:用水调和)。"}, {"meaning": "同本义。", "cites": [{"t": "溲,浸沃也。", "b": "《说文》"}, {"t": "溲,水调粉面也。", "b": "《正字通》"}, {"t": "今苏俗言溲粉、溲面皆是。", "b": "《说文通训定声》"}, {"t": "明齐溲酒。", "b": "《仪礼·士虞礼》"}], "words": [{"w": "溲面", "t": "以水拌面。"}]}, {"meaning": "淘洗。", "cites": [{"t": "析薪溲米。", "b": "《聊斋志异》"}], "words": [{"w": "溲箕", "t": "竹编的淘米用具。"}]}, {"meaning": "排泄大小便。", "cites": [{"t": "湛至朝堂,遗失溲便,因自陈疾笃,不能复任朝,事遂罢之。", "b": "《后汉书·张湛传》"}, {"t": "臣闻昔者大任娠文王不变,少溲于豕牢,而得文王不加疾焉。", "b": "《国语》"}, {"t": "臣意诊之,曰:“涌疝也,令人不得前后溲。”", "b": "《史记·扁鹊仓公列传》。司马贞索隐:“前溲谓小便;后溲,大便也。”"}], "words": [{"w": "溲血", "t": "尿血;便血"}, {"w": "溲恶", "t": "小便与大便"}, {"w": "溲溺", "t": "撒尿"}, {"w": "溲膏", "t": "排泄膏状小便"}, {"w": "溲器", "t": "尿器。"}]}, {"meaning": "吐血。", "cites": [{"t": "溲血死。", "b": "《史记》"}]}, {"meaning": "排泄精液。", "cites": [{"t": "内热溲膏是也。", "b": "《庄子》"}]}, {"meaning": "尿。", "cites": [{"t": "至其矢溲,亦亲候其时节颜色所下。", "b": "欧阳修《海陵许氏南园记》"}]}, {"meaning": "像尿一样的液体。", "cites": [{"t": "地溲,沟涧流水。", "b": "《本草纲目》"}]}, {"meaning": "淘米声。", "cites": [{"t": "叟,叟叟,淅米声。通作“溲”。", "b": "《集韵》"}]}, {"meaning": "溲水 ,源出今湖北省枣阳县东北山,流经河南省桐柏县,至唐县入澧河,又名“秋河”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5286wx','湟','1','huáng','氵','12','','[{"pinyin": "huáng", "defs": [{"meaning": "水名  。在青海省东部,源出海晏县包呼图山,东南流经湟源县、西宁市,至甘肃省兰州市西达家川入黄河。", "cites": [{"t": "湟,湟水也。出金城临羌塞外,东入河。", "b": "《说文》"}]}, {"meaning": "城池。", "cites": [{"t": "湟池纡曲。", "b": "枚乘《七发》。注:“城池也。”"}], "words": [{"w": "湟潦", "t": "低洼积水处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5287wx','溆','1','xù','氵','12','','[{"pinyin": "xù", "defs": [{"meaning": "水名 。古名序水,溆水,溆浦,溆川。又名双龙江。源出湖南省溆浦县东南山中,西北流,至溆浦县城东南,又折向西流入沅江。", "cites": [{"t": "入溆浦余儃佪兮,迷不知吾所如。", "b": "《楚辞·屈原·涉江》"}]}, {"meaning": "水边。", "cites": [{"t": "长飚落江树,秋月照沙溆。", "b": "南朝梁·何逊《赠江长史别》"}, {"t": "追欢于林溆之地。", "b": "清·吴锡麒《游西山记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5288wx','湲','1','yuán','氵','12','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从水,爰(yuán)声。双音词“潺湲”,水慢慢流动的样子) 见“潺湲”(chányuán)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5289wx','湔','1','jiān','氵','12','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。从水,前声。本义:水名。湔水,在四川)。"}, {"meaning": "用水洗。", "cites": [{"t": "湔,濯也。", "b": "《三苍》"}, {"t": "湔,洒也。", "b": "《广雅》"}, {"t": "谁道湔裙人远。", "b": "王沂孙《南浦·春水》"}, {"t": "湔浣肠胃,漱涤五藏。", "b": "《史记》"}], "words": [{"w": "湔除", "t": "洗去污秽"}, {"w": "湔汰", "t": "洗涤"}, {"w": "湔刷", "t": "洗刷"}, {"w": "湔拂", "t": "清洗、涤除。"}]}, {"meaning": "洗雪(耻辱);清除(过失、罪责等)。", "cites": [{"t": "近降赦恩,谋反大逆,皆蒙湔雪。", "b": "《金史·张特立传》"}], "words": [{"w": "湔雪", "t": "洗刷罪名,昭雪冤屈"}, {"w": "湔改", "t": "洗去罪责,悔过自新"}, {"w": "湔贷", "t": "洗罪赎罪"}, {"w": "湔洒", "t": "洗刷,洗雪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5290wx','湉','1','tián','氵','12','','[{"pinyin": "tián", "defs": [{"meaning": "——“澶湉”（chántián）:形容水流平静。", "cites": [{"t": "澶湉漠而无涯。", "b": "《文选·左思·吴都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5291wx','渥','1','wò','氵','12','','[{"pinyin": "wò", "defs": [{"meaning": "(形声。从水,屋声。本义:沾润)。"}, {"meaning": "同本义。", "cites": [{"t": "渥,沾也。", "b": "《说文》"}, {"t": "既优既渥。", "b": "《诗·小雅·信南山》"}, {"t": "其形渥。", "b": "《易·鼎》。注:“沾濡也。”"}], "words": [{"w": "渥汗", "t": "指感受风寒的病人,服药后盖上棉被出汗"}, {"w": "渥润", "t": "润泽。"}]}, {"meaning": "剭诛。古代诛杀贵族在屋内行刑,不暴露于市。", "cites": [{"t": "鼎折足,覆公餗,其形渥,凶。", "b": "《易·鼎卦幄》"}]}, {"meaning": "光泽。", "cites": [{"t": "颜如渥丹。", "b": "《诗·秦风·终南》。又如:渥然(色泽红润貌);渥耀(普照);渥丹(润泽的朱砂。形容颜色红润);渥须(美须)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5292wx','湄','1','méi','氵','12','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从水,眉声。本义:岸边,水与草交接的地方) 同本义。", "cites": [{"t": "湄,水草交为湄。", "b": "《说文》"}, {"t": "所谓伊人,在水之湄。", "b": "《诗·秦风·蒹葭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5293wx','滁','1','chú','氵','12','','[{"pinyin": "chú", "defs": [{"meaning": "水名 。在安徽省东部。源出肥东县东北,折而东流,经滁县至江苏省六合县注入长江。本作“涂”,唐人改作“滁”。"}, {"meaning": "古州名 。在安徽省东部,滁河流域,邻接江苏省,津浦铁路纵贯。特产“滁菊”、“滁州竹篮”。境内琅琊山风景幽美,为游览胜地。", "cites": [{"t": "环滁皆山也。", "b": "欧阳修《醉翁亭记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5294wx','愠','1','yùn','忄','12','','[{"pinyin": "yùn", "defs": [{"meaning": "(形声。从心,昷(wēn)声。本义:含怒,生气)。"}, {"meaning": "同本义。", "cites": [{"t": "愠,怒也。", "b": "《说文》"}, {"t": "愠,恨。", "b": "《苍颉篇》"}, {"t": "舞斯愠。", "b": "《礼记·檀弓》。注;“犹怒也。”"}, {"t": "愠而不出。", "b": "《左传·襄公二十三年》"}, {"t": "忧心悄悄,愠于群小。", "b": "《诗·邶风·柏舟》"}, {"t": "人不知而不愠,不亦君子乎。", "b": "《论语》"}], "words": [{"w": "愠怍", "t": "愠怒"}, {"w": "愠恚", "t": "怨恨恼怒。"}]}, {"meaning": "羞,害羞。", "cites": [{"t": "引得些鸳鸯儿交颈和鸣,忽的见了,愠的面赤,兜的心疼。", "b": "元·关汉卿《金线池》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5295wx','惺','1','xīng','忄','12','','[{"pinyin": "xīng", "defs": [{"meaning": "聪明。", "cites": [{"t": "骨谗犹可忏,舌惺岂不悔。", "b": "明·袁宏道《靳尚祠》"}], "words": [{"w": "惺惺惜惺惺", "t": "聪明人爱惜聪明人。意谓性格、才能或境遇相同的相互爱惜、同情。"}]}, {"meaning": "领会。", "cites": [{"t": "俺如今已惺,也学的寡情。", "b": "明·冯惟敏《朝天子》"}], "words": [{"w": "惺悟", "t": "领会。"}]}, {"meaning": "清醒。", "cites": [{"t": "一声寒雁叫,唤起未惺人。", "b": "《五灯会元》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5296wx','愦','1','kuì','忄','12','','[{"pinyin": "kuì", "defs": [{"meaning": "闷,烦乱。", "cites": [{"t": "心烦愦兮意无聊。", "b": "王逸《九思·逢尤》"}], "words": [{"w": "愦愦", "t": "混乱不安;糊涂"}, {"w": "愦乱", "t": "昏乱不安,忧思烦乱"}, {"w": "愦闹", "t": "混乱喧闹"}, {"w": "愦毒", "t": "因中毒而烦乱。"}]}, {"meaning": "昏乱,神志不清。", "cites": [{"t": "则固僵仆烦愦。", "b": "唐·柳宗元《柳河东集》"}, {"t": "愦于忧。", "b": "《战国策·齐策四》"}], "words": [{"w": "愦眊", "t": "昏昧糊涂"}, {"w": "愦耄", "t": "昏乱糊涂"}, {"w": "愦慢", "t": "昏庸怠慢"}, {"w": "愦瞀", "t": "昏乱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5297wx','惴','1','zhuì','忄','12','','[{"pinyin": "zhuì", "defs": [{"meaning": "(形声。从心,耑(zhuān)声。本义:忧愁恐惧) 同本义。", "cites": [{"t": "惴,忧惧也。", "b": "《说文》"}, {"t": "惴,忧也。", "b": "《广雅》"}, {"t": "人皆惴恐。", "b": "《汉书·宁成传》"}, {"t": "惴惴其栗。", "b": "《诗·秦风·黄鸟》"}, {"t": "惴惴,惧也。", "b": "《尔雅》"}, {"t": "小恐惴惴。", "b": "《庄子·齐物论》"}, {"t": "自返而不缩,虽褐宽博,吾不惴焉。", "b": "《孟子·公孙丑》"}, {"t": "屯田数十万,堤防常慴惴。", "b": "杜牧《感怀诗一首》"}], "words": [{"w": "惴怯", "t": "胆怯,恐惧"}, {"w": "惴畏", "t": "畏惧"}, {"w": "惴恐", "t": "恐惧"}, {"w": "惴息", "t": "害怕得不敢喘息"}, {"w": "惴惕", "t": "恐惧,忧戚"}, {"w": "惴悸", "t": "惊惧。"}]}]}]','jingmo-wenyan');
