INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5299wx','愎','1','bì','忄','12','','[{"pinyin": "bì", "defs": [{"meaning": "(会意。从心,复声。本义:不听从) 同本义。", "cites": [{"t": "贪愎喜利,则灭国杀身之本也。", "b": "《韩非子·十过》"}, {"t": "知伯贪而愎,故韩魏反而丧之。", "b": "《左传·哀公二十七年》"}], "words": [{"w": "刚愎", "t": "倔强固执,不接受别人的意见"}, {"w": "愎很", "t": "固执,任性"}, {"w": "愎戾", "t": "愎类。固执乖僻。"}]}, {"meaning": "拒绝。", "cites": [{"t": "愎谏而好胜。", "b": "《韩非子·亡征》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5300wx','愔','1','yīn','忄','12','','[{"pinyin": "yīn", "defs": [{"meaning": "(形声。从心,音声。双音词“愔愔”。本义:安静和悦的样子) 同本义。", "cites": [{"t": "愔愔琴德,不可测兮。", "b": "嵇康《琴赋》"}], "words": [{"w": "愔愔", "t": "幽深的样子;悄寂的样子"}, {"w": "愔翳", "t": "深静的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5301wx','喾','1','kù','口','12','','[{"pinyin": "kù", "defs": [{"meaning": "传说中的古代帝王名,即五帝之一的高辛氏。", "cites": [{"t": "帝喾高辛者,黄帝之曾孙也。", "b": "《史记·五帝本纪》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5302wx','寐','1','mèi','宀','12','','[{"pinyin": "mèi", "defs": [{"meaning": "(形声。本义:睡着)。"}, {"meaning": "同本义。", "cites": [{"t": "寐,卧也。", "b": "《说文》"}, {"t": "夙兴夜寐。", "b": "《诗·卫风·氓》"}, {"t": "耿耿不寐。", "b": "《诗·邶风·柏舟》"}, {"t": "归寝不寐。", "b": "《国语·晋语》"}, {"t": "寡人夜者寝而不寐。", "b": "《公羊传·僖公二年》"}, {"t": "门卒方熟寐。", "b": "《资治通鉴·唐纪》"}, {"t": "人不寐。", "b": "宋·范仲淹《渔家傲》"}, {"t": "子灿寐而醒。", "b": "明·魏禧《大铁椎传》"}, {"t": "乃悟前狼假寐。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "夜不能寐;梦寐(睡梦)以求;寐息(睡眠;卧息", "t": ""}, {"w": "寐寤", "t": "睡眠和觉醒"}, {"w": "寐觉", "t": "睡醒。"}]}, {"meaning": "死。", "cites": [{"t": "潜寐黄泉下,千载永不寐。", "b": "《古诗十九首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5303wx','谟','1','mó','讠','12','','[{"pinyin": "mó", "defs": [{"meaning": "(形声。从言,莫声。本义:计谋,谋略) 同本义。", "cites": [{"t": "遂献宏谟。", "b": "陆机《辩亡论下》"}, {"t": "谟,谋也。", "b": "《尔雅·释诂》"}, {"t": "周爰谘谟。", "b": "《淮南子·脩务》"}], "words": [{"w": "谟士", "t": "有才略的人。同谋士"}, {"w": "谟臣", "t": "即谋臣"}, {"w": "谟训", "t": "谋议和教训。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5304wx','扉','1','fēi','户','12','','[{"pinyin": "fēi", "defs": [{"meaning": "(形声。从户,非声。从“户”表示与门户有关。本义:门扇)。"}, {"meaning": "同本义。", "cites": [{"t": "扉,户扇也。", "b": "《说文》"}, {"t": "阖谓之扉。", "b": "《尔雅》"}, {"t": "阖东扉。", "b": "《仪礼·士丧礼》"}, {"t": "子尾抽桷击扉。", "b": "《左传·襄公二十八年》"}, {"t": "且蜀兵应者,皆准备归计,其父母妻子依扉而望。", "b": "《三国演义》"}, {"t": "夜深静卧百虫绝,清月出岭光入扉。", "b": "宋·陆游《绯桃开小酌》"}], "words": [{"w": "柴扇;荆扉", "t": ""}]}, {"meaning": "引申为屋舍。", "cites": [{"t": "寄卧郊扉久。", "b": "马戴《灞上秋居》"}]}, {"meaning": "像门扇的东西。", "cites": [{"t": "窗扉多是缘琉璃,亦皆达照。", "b": "《西京杂记》"}]}]}]','jingmo-wenyan');
