INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5306wx','裎','1','chéng chěng','衤','12','','[{"pinyin": "chéng", "defs": [{"meaning": "裸体,没有穿衣服或脱去衣服的情状。", "cites": [{"t": "裎,但也。从衣,呈声。", "b": "《说文》"}, {"t": "裎,袒也。", "b": "《广雅》"}, {"t": "裎,裸也。", "b": "《后汉书·马融传》注"}, {"t": "虽袒裼裸裎于我侧。", "b": "《孟子》"}, {"t": "秦人捐甲徒裎以趋敌,左挈人头,右挟生虏。", "b": "《战国策》"}]}, {"meaning": "系玉佩的带子。", "cites": [{"t": "佩紟谓之裎。", "b": "《方言》。郭璞注:“所以系玉佩带也。”"}]}]}, {"pinyin": "chěng", "defs": [{"meaning": "古代的一种对襟单衣。"}]}]','jingmo-wenyan');
