('5310wx','谠','1','dǎng','讠','12','','[{"pinyin": "dǎng", "defs": [{"meaning": "(形声。从言,党声。本义:正直) 同本义。", "cites": [{"t": "吾久不见班生,今日复闻谠言。", "b": "《汉书·叙传》"}], "words": [{"w": "谠言", "t": "正直美善的言论"}, {"w": "谠直", "t": "正直。亦指正直的人"}, {"w": "谠论", "t": "正直美善的议论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5311wx','幂','1','mì','巾','12','','[{"pinyin": "mì", "defs": [{"meaning": "(形声。从巾,冥声。本义:盖东西用的巾)。"}, {"meaning": "同本义。", "cites": [{"t": "大巾谓之幂。", "b": "《小尔雅·广诂》"}, {"t": "幂人,掌共巾幂。", "b": "《周礼·天官·幂人》。注:“共巾,可以覆物。”"}, {"t": "幂用锡若絺。", "b": "《仪礼·大射礼》。注:“幂,覆尊巾也。”"}, {"t": "幂用疏布。", "b": "《仪礼·既夕礼》"}, {"t": "簠有盖幂。", "b": "《仪礼·公食大夫礼》"}], "words": [{"w": "幂首", "t": "古代妇女障面的一种头巾"}, {"w": "幂人", "t": "《周礼》官名。掌共巾幂"}, {"w": "幂篱", "t": "古代少数民族的一种头巾。"}]}, {"meaning": "云南少数民族计算布帛的单位。"}, {"meaning": "用布覆盖。", "cites": [{"t": "祭祀,以疏布巾幂八尊。", "b": "《周礼·天官》"}], "words": [{"w": "幂历", "t": "分布覆被的样子;弥漫笼罩的样子。"}]}, {"meaning": "遮;蒙。", "cites": [{"t": "幂窗用纸。", "b": "白居易《庐山草堂记》"}]}, {"meaning": "涂刷。", "cites": [{"t": "葺墙幂室,房庑杂袭。", "b": "左思《魏都赋》"}]}]}]','jingmo-wenyan');
