INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5313wx','谥','1','shì','讠','12','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从言,益声。用言论给予褒贬,故从言。本作“諡”。本义:古代皇帝、贵族、大臣、杰出官员或其它有地位的人死后所加的带有褒贬意义的称号) 同本义。", "cites": [{"t": "谥,行之迹也。", "b": "《北堂书钞》引《说文》"}, {"t": "谥者,别尊卑,彰有德也。", "b": "《白虎通》"}, {"t": "先王谥以尊名。", "b": "《礼记·表记》"}, {"t": "诔生时所行为之谥。", "b": "《论衡·道应》"}, {"t": "增谥美显,荣于身后。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "谥法", "t": "由主祭者将名号赠给死者,以表彰他一生的功业"}, {"w": "谥宝", "t": "古代帝王寝墓中,刻有帝后谥号的玺印"}, {"w": "谥谱", "t": "记载谥号的谱牒"}, {"w": "谥名", "t": "谥号。"}]}, {"meaning": "授与,加封;尤指死后追封。", "cites": [{"t": "幸德谥为洞箫兮。", "b": "王褒《洞箫赋》"}, {"t": "身死无名,谥为至愚,耻及父母,为天下笑。", "b": "《史记·司马相如列传》"}], "words": [{"w": "谥告", "t": "赠谥的文告"}, {"w": "谥典", "t": "赠谥的典礼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5314wx','谧','1','mì','讠','12','','[{"pinyin": "mì", "defs": [{"meaning": "(形声。本义:安静) 同本义(指环境的安静,没有动荡,没有骚扰)。", "cites": [{"t": "谧,静语也,一曰无声也。", "b": "《说文》"}, {"t": "其化清谧。", "b": "《素问·气交变大论》。注:“谧,静也。”"}, {"t": "其政谧。", "b": "《五常正大论》。注:“谧,静也。”"}, {"t": "海表谧然。", "b": "《三国志·东夷传》"}, {"t": "四海谧然,宇内晏清。", "b": "《魏书·于栗忠传》"}, {"t": "内外寂谧。", "b": "《汉武帝内传》"}], "words": [{"w": "谧然", "t": "平静的样子"}, {"w": "谧宁", "t": "宁静"}, {"w": "谧尔", "t": "安静的样子"}, {"w": "谧谧", "t": "沉寂的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5315wx','遐','1','xiá','辶','12','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从辵(chuò),叚(xiá)声。本义:远)。"}, {"meaning": "同本义。", "cites": [{"t": "遐,远也。", "b": "《说文新附》"}, {"t": "若陟遐,必自迩。", "b": "《书·太甲》"}, {"t": "是以遐方疏俗,殊邻绝党之域,自上仁所不化,茂德所不绥,莫不蹻足抗首,请献厥珍。", "b": "汉·扬雄《长杨赋》"}, {"t": "矫首而遐观。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "有艳淑女在闺房,室迩人遐在我傍。", "b": "《警世通言》"}, {"t": "地遐怪物聚,寺古深殿存。", "b": "宋·范祖禹《资州路东津寺》"}], "words": [{"w": "遐僻", "t": "偏远"}, {"w": "遐宣", "t": "远远宣扬"}, {"w": "遐方", "t": "远方"}, {"w": "遐布", "t": "传播到远处。"}]}, {"meaning": "长久,久远。", "cites": [{"t": "降尔遐福,维日不足。", "b": "《诗·小雅·天保》"}, {"t": "入觐展遐恋,临轩慰来思。", "b": "唐·德宗《送徐州张建封还镇》"}], "words": [{"w": "遐福", "t": "久远之福"}, {"w": "遐祉", "t": "永远长保的福祉。"}]}, {"meaning": "又长又大。", "cites": [{"t": "爰有遐狄,镣质轮菌,坐高门之侧堂,彰圣主之威神。", "b": "《文选·何晏·景福殿赋》"}], "words": [{"w": "遐志", "t": "远大的志向"}, {"w": "遐愁", "t": "深长的愁绪。"}]}, {"meaning": "疏远。", "cites": [{"t": "毋金玉尔音,而有遐心。", "b": "《诗·小雅·白驹》。朱熹集传:“毋贵重尔之音声,而有远我之心。”"}], "words": [{"w": "遐弃", "t": "疏远抛弃"}, {"w": "遐遗", "t": "疏远遗弃。"}]}, {"meaning": "前人;以往。", "cites": [{"t": "遵许郭之遐轨。", "b": "《晋书》"}, {"t": "仰天民之高衢兮,慕在昔之遐轨。", "b": "汉·阮瑀《纪征赋》"}], "words": [{"w": "遐轨", "t": "古人的遗迹;前人之法度"}, {"w": "遐籍", "t": "古代的典籍。"}]}, {"meaning": "远去。", "cites": [{"t": "俟阊风而西遐,致恭祀乎高祖。", "b": "《文选·张衡·东京赋》"}], "words": [{"w": "遐升", "t": "死亡的婉称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5316wx','孱','1','càn chán','子','12','','[{"pinyin": "càn", "defs": [{"meaning": "[方言]∶软弱无能的人(骂人话) "}]}, {"pinyin": "chán", "defs": [{"meaning": "(会意。从尸,犹从屋省,本义:狭窄)。"}, {"meaning": "同本义。", "cites": [{"t": "孱,迮也,", "b": "《说文》"}, {"t": "孱,窄也。", "b": "《集韵》"}]}, {"meaning": "浅陋,低劣。", "cites": [{"t": "术学肤孱。", "b": "宋祁《授龙图阁谢恩表》"}]}, {"meaning": "形容谨小慎微的样子。", "cites": [{"t": "君子博学而孱守之。", "b": "《大戴礼记·曾子立事》"}]}, {"meaning": "懦弱。", "cites": [{"t": "若素名勇,徒能藉贫孱者耳。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "孱夫", "t": "懦弱的人"}, {"w": "孱王", "t": "懦弱的君王。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5317wx','弼','1','bì','弓','12','','[{"pinyin": "bì", "defs": [{"meaning": "同本义。", "cites": [{"t": "弼,辅也。", "b": "《说文》。按,当训弓辅也。"}]}, {"meaning": "辅佐君王的大臣。", "cites": [{"t": "柱石之臣,宜民辅弼。(左称辅,右称弼。)", "b": "《后汉书·伏湛传》"}, {"t": "梦帝赉予良弼。", "b": "《书·说命上》"}, {"t": "一日去良弼,如亡左右手。", "b": "《新唐书》"}]}, {"meaning": "辅助,特指臣下辅佐君王。", "cites": [{"t": "择其能正色。弼违。", "b": "《晋书·武帝纪》"}, {"t": "能弼宁晋室,辅予一人。", "b": "《晋书·元帝纪》"}, {"t": "予违汝弼。", "b": "《书·益稷》"}, {"t": "建立辅弼。", "b": "曹操《求言令》"}], "words": [{"w": "辅弼", "t": "辅佐"}, {"w": "弼匡", "t": "辅佐改正"}, {"w": "弼教", "t": "辅助教化。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5318wx','巽','1','xùn','巳','12','','[{"pinyin": "xùn", "defs": [{"meaning": "(会意。小篆。从丌)。"}, {"meaning": "同本义。", "cites": [{"t": "巽,具也。", "b": "《说文》"}]}, {"meaning": "消散。", "cites": [{"t": "巽,散也,物皆生布散也。", "b": "《释名·释天》"}]}, {"meaning": "八卦之一。代表风。", "cites": [{"t": "巽为木,为风。", "b": "《易·说卦》"}], "words": [{"w": "巽地", "t": "吉利的地方"}, {"w": "巽二郎", "t": "传说中的风神"}, {"w": "巽二", "t": "古时传说中的风神名。《易·说卦》有“巽为木,为风”,故名。"}]}, {"meaning": "卑顺;怯懦。", "cites": [{"t": "童蒙之吉,顺以巽也。", "b": "《易·蒙》。孔颖达疏引褚氏曰:“顺者心不违也,巽者外迹相卑下也。”"}], "words": [{"w": "巽顺", "t": "卑顺、顺从"}, {"w": "巽词", "t": "巽辞。委婉的言词"}, {"w": "巽与", "t": "顺从,附和。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5319wx','骘','1','zhì','马','12','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从马,陟声。本义:公马)。"}, {"meaning": "同本义。", "cites": [{"t": "骘,牡马也。", "b": "《说文》"}, {"t": "牡曰骘。", "b": "《尔雅·释畜》"}, {"t": "骘,雄也。", "b": "《广雅》"}], "words": [{"w": "騲骘", "t": "雌马和公马。"}]}, {"meaning": "安定。", "cites": [{"t": "惟天阴骘下民,相协厥居。", "b": "《书·洪范》。孔传:“骘,定也。夫不言而默定下民。”"}]}, {"meaning": "评定;评论。", "cites": [{"t": "迩之进退者,岂以二子而骘是非乎?", "b": "唐·范摅《云溪友议》"}], "words": [{"w": "评骘", "t": "评论"}, {"w": "骘是非", "t": "评定是非。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5320wx','媪','1','ǎo','女','12','','[{"pinyin": "ǎo", "defs": [{"meaning": "(形声。从女,昷(wēn)声。本义:对老年妇女的敬称)。"}, {"meaning": "同本义。", "cites": [{"t": "白发谁家翁媪。", "b": "辛弃疾《清平乐》"}, {"t": "老臣窃以为媪之爱燕后,贤于长安君。", "b": "《战国策·赵策》"}], "words": [{"w": "媪妪", "t": "年老的妇女。"}]}, {"meaning": "对妇女的通称。", "cites": [{"t": "昂年五岁,乳媪(奶母)携抱匿于庐山。", "b": "《南史·袁昂传》"}]}, {"meaning": "母亲。", "cites": [{"t": "卫君自请薄媪。", "b": "《韩非子·外储说右上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5321wx','媛','1','yuán yuàn','女','12','','[{"pinyin": "yuán", "defs": [{"meaning": "——“婵媛”(chányuán)。"}, {"meaning": "姿态美好。"}, {"meaning": "牵连,相连。"}]}, {"pinyin": "yuàn", "defs": [{"meaning": "美女。", "cites": [{"t": "媛,美女也,人所援也。从女,从爰,爰,于也。", "b": "《说文》"}, {"t": "美女为媛。", "b": "《尔雅》"}], "words": [{"w": "媛女", "t": "美女"}, {"w": "媛德", "t": "女子的美德。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5322wx','婷','1','tíng','女','12','','[{"pinyin": "tíng", "defs": [{"meaning": "(形声。从女,亭声。本义:美好的样子)。"}, {"meaning": "颜色和悦。", "cites": [{"t": "婷,和色也。", "b": "《玉篇》"}]}, {"meaning": "优美、雅致 。", "words": [{"w": "婷婷袅袅", "t": "形容女子体态柔美轻盈"}, {"w": "婷娉", "t": "体态美好;又指美女。"}]}]}]','jingmo-wenyan');
