INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5324wx','翚','1','huī','羽','12','','[{"pinyin": "huī", "defs": [{"meaning": "振翅疾飞。", "cites": [{"t": "翚,大飞也。", "b": "《说文》"}, {"t": "翚,习也。", "b": "《方言》"}, {"t": "若夫游鹬高翚,绝翚逾斥。", "b": "《文选·张衡·西京赋》"}]}, {"meaning": "舞动", "cites": [{"t": "翚终葵,扬关斧。", "b": "《后汉书·马融传》"}]}, {"meaning": "锦鸡。", "cites": [{"t": "伊、洛而南,素质、五采皆备成章曰翚。", "b": "《尔雅》。郭璞注:翚亦雉属。言其毛色光鲜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5325wx','皴','1','cūn','皮','12','','[{"pinyin": "cūn", "defs": [{"meaning": "皮肤坼裂。", "cites": [{"t": "皴,皮细起也。", "b": "《字略》"}], "words": [{"w": "皴劈", "t": "粗皱龟裂"}, {"w": "孩子的手皴了", "t": ""}]}, {"meaning": "打皱;皱缩。", "cites": [{"t": "客皴眉而俯,不复抽言。", "b": "宋·盛均《真龙对》"}], "words": [{"w": "几天没洗澡,满身是皴了", "t": ""}]}, {"meaning": "中国画的一种技法,用淡干墨涂染以表现山石纹理,峰峦折痕及树身表皮的脉络、形态 。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5326wx','婺','1','wù','女','12','','[{"pinyin": "wù", "defs": [{"meaning": "星名。即婺女,二十八宿之一,玄武七宿的第三宿。", "cites": [{"t": "婺,婺女,星名。", "b": "《广韵·遇韵》"}]}, {"meaning": "水名,乐安江上游,别称“婺江” 在江西省婺源县西南。"}, {"meaning": "古州名。隋开皇十三年由吴州更名,治所在今浙江省金华县。", "cites": [{"t": "君居东婺我西湖。", "b": "《和姜梅山》"}]}, {"meaning": "不顺从。", "cites": [{"t": "婺,不繇也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5327wx','骛','1','wù','马','12','','[{"pinyin": "wù", "defs": [{"meaning": "(形声。从马,敄(wù)声。本义:纵横奔驰)。"}, {"meaning": "同本义。泛指疾驰。", "cites": [{"t": "代御执辔持策,则马咸骛矣。", "b": "《韩非子·外储说右下》"}], "words": [{"w": "骛驰", "t": "车马奔驰"}, {"w": "骛行", "t": "驰行"}, {"w": "骛神", "t": "驰神"}, {"w": "骛置", "t": "急驰传递"}, {"w": "骛骛", "t": "奔腾的样子。"}]}, {"meaning": "追求;强求。也作“务”。", "cites": [{"t": "病学者厌卑近而骛高远,卒无成焉。", "b": "脱脱《宋史》"}], "words": [{"w": "好高骛远;骛利", "t": "求利"}, {"w": "骛名", "t": "追求名誉"}, {"w": "骛奇", "t": "猎奇"}, {"w": "骛华", "t": "追求华丽"}, {"w": "骛新", "t": "追求时髦。"}]}, {"meaning": "迅速。", "cites": [{"t": "肝脉骛暴。", "b": "《素问·大奇论》"}], "words": [{"w": "骛骤", "t": "迅疾行进"}, {"w": "骛驶", "t": "疾速奔驰"}, {"w": "骛扬", "t": "迅疾浮游。"}]}]}]','jingmo-wenyan');
