INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5329wx','缃','1','xiāng','纟','12','','[{"pinyin": "xiāng", "defs": [{"meaning": "浅黄色。", "cites": [{"t": "缃绮为下裙。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "缃苞", "t": "浅黄色的苞"}, {"w": "缃裙", "t": "浅黄色的裙子"}, {"w": "缃素", "t": "浅黄色书卷的代称"}, {"w": "缃绮", "t": "淡黄色的丝织品。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5330wx','缄','1','jiān','纟','12','','[{"pinyin": "jiān", "defs": [{"meaning": "(形声。糸糸(mì)，表示与线丝有关,咸声。本义：(捆东西的绳索))。"}, {"meaning": "同本義。", "cites": [{"t": "缄,束篋也。", "b": "《説文》"}, {"t": "缄,索也。", "b": "《广雅》"}, {"t": "则必摂缄滕。", "b": "《庄子·胠篋》。释文:“绳也。”"}, {"t": "使客子解篋缄未已。", "b": "《汉书·外戚传》。注:“束篋之绳也。”"}, {"t": "摄缄縢。", "b": "清·黄宗羲《明夷待访录·原君》"}], "words": [{"w": "缄縢", "t": "绳索。"}]}, {"meaning": "信件。", "cites": [{"t": "开缄见手扎,一纸十三行。", "b": "白居易《初与元九别后忽梦见之》"}], "words": [{"w": "缄书", "t": "书信"}, {"w": "缄愁", "t": "写信給人,倾訴相思之苦"}, {"w": "缄題", "t": "信函的封端。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5331wx','彘','1','zhì','彑','12','','[{"pinyin": "zhì", "defs": [{"meaning": "(象形。小篆字形。矢声,其余象猪头、脚。本义:彘本指大猪,后泛指一般的猪)。"}, {"meaning": "同本义。", "cites": [{"t": "彘,豕也。后蹏废谓之彘。", "b": "《说文》"}, {"t": "彘,猪也。", "b": "《小尔雅》"}, {"t": "食黍与彘。", "b": "《礼记·月令》。注:“水畜也。”"}, {"t": "彘者,北方之牲也。", "b": "《贾子胎教》"}, {"t": "竹山有兽焉,名曰毫彘。", "b": "《西山经》。注:“貆猪也。吴楚呼鸾猪。”"}, {"t": "故明主表信,如曾子杀彘也。", "b": "《韩非子·外储说左上》"}, {"t": "鸡豚狗彘。", "b": "《孟子·梁惠王上》"}, {"t": "赐之彘肩。", "b": "《史记·项羽本纪》"}]}, {"meaning": "又。", "cites": [{"t": "与一生彘肩。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "加彘肩上。", "b": ""}], "words": [{"w": "彘狗不如;如彘牢;猪圈),(彘肩(即肘子作为食物的猪腿的最上部分", "t": ""}, {"w": "彘肩斗酒", "t": "形容英雄豪壮之气。"}]}, {"meaning": "地名,故址在今山西霍县东北。", "cites": [{"t": "三年,乃流王[厉王]于彘。", "b": "《国语》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5332wx','缇','1','tí','纟','12','','[{"pinyin": "tí", "defs": [{"meaning": "(形声。从糸(mì),是声。本义:红黄色,丹黄色)。"}, {"meaning": "同本义。", "cites": [{"t": "缇,帛丹黄色。", "b": "《说文》"}, {"t": "缇,赤也。", "b": "《广雅》"}, {"t": "缇十重。", "b": "《后汉书·应劭传》。注:“赤色缯也。”"}, {"t": "赤缇用羊。", "b": "《周礼·草人》。注:“縓色也。”"}, {"t": "四曰缇齐。", "b": "《周礼·酒正》。注:“成而红赤。如今下酒也。”"}, {"t": "为治斋宫河上,张缇降帷。", "b": "《史记·滑稽列传》"}]}, {"meaning": "橘红色的丝织物。", "cites": [{"t": "缇骑按剑而前,问“谁为哀者?”", "b": "张溥《五人墓碑记》"}], "words": [{"w": "缇", "t": "赤色厚缯"}, {"w": "缇绣", "t": "赤缯与文绣"}, {"w": "缇袭", "t": "什袭。用赤色缯把物品重重包裹起来。"}]}, {"meaning": "莎草的籽实。", "cites": [{"t": "细茎有三棱,实在茎端,其色赤缇,故曰缇矣。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5333wx','缈','1','miǎo','纟','12','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从糸(mì),眇(miǎo)声)。"}, {"meaning": "——“缥缈”(piáomiǎo):隐隐约约,若有若无。亦作“飘渺”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5334wx','缌','1','sī','纟','12','','[{"pinyin": "sī", "defs": [{"meaning": "制作丧服的细麻布 。凡疏远的亲属、亲戚都服缌麻", "words": [{"w": "缌服", "t": "丧服名。为五服中最轻的一种,为期三月"}, {"w": "缌麻", "t": "古代用细麻布制成的丧服"}]}, {"meaning": "古代丧服名。五种丧服之最轻者,以细麻布为孝服,服丧三个月", "words": [{"w": "缌麻服", "t": "指为期三个月的丧服"}, {"w": "缌麻丧", "t": "古代丧服名。五服中之最轻者"}, {"w": "缌衰", "t": "古代为诸侯之丧服"}]}, {"meaning": "较为疏远的亲属关系", "words": [{"w": "缌亲", "t": "较为疏远的亲属关系"}, {"w": "缌功", "t": "缌麻与小功。旧时五种丧服中最轻的两种,由亲缘较疏者服之"}, {"w": "缌免", "t": "缌服与免服,均为丧服之轻者。借指关系疏远的族人"}, {"w": "缌服", "t": "缌麻服。多指关系较远的族亲"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5335wx','缑','1','gōu','纟','12','','[{"pinyin": "gōu", "defs": [{"meaning": "姓 。周卿士食采于缑,因以为氏。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5336wx','缒','1','zhuì','纟','12','','[{"pinyin": "zhuì", "defs": [{"meaning": "(形声。从糸(mì),追声。本义:糸在绳子上放下去)。"}, {"meaning": "同本义。", "cites": [{"t": "缒,以绳有所悬也。", "b": "《说文》"}, {"t": "夜缒纳师。", "b": "《左传·襄公十九年》"}, {"t": "子占使师夜缒而登。", "b": "《左传·昭公十九年》"}, {"t": "[烛之武]夜缒而出。", "b": "《左传·僖公三十年》"}, {"t": "敌兵攻城,纲身督战,募壮士缒城而下。", "b": "《宋史》"}], "words": [{"w": "缒关", "t": "从关门旁缘绳而下"}, {"w": "缒城", "t": "由城上以绳索垂至平地,缘之而下。"}]}, {"meaning": "绳索。", "cites": [{"t": "登者六十人,缒绝,师鼓噪,城上之人亦噪。", "b": "《左传》"}], "words": [{"w": "缒绝", "t": "绳断"}, {"w": "系缒", "t": "系结绳索。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5337wx','缗','1','mín','纟','12','','[{"pinyin": "mín", "defs": [{"meaning": "(形声。又作“緍”。从糸(mì),昏声。本义:钓鱼绳)。"}, {"meaning": "同本义。", "cites": [{"t": "其钓维何?维丝伊缗。", "b": "《诗·召南·何彼秾矣》"}], "words": [{"w": "振缗", "t": "挥动钓丝"}, {"w": "缗纶", "t": "钓鱼用的丝线。"}]}, {"meaning": "古代穿铜钱的绳子。", "cites": [{"t": "贾人缗线。", "b": "《史记》"}], "words": [{"w": "缗钱", "t": "用丝线串起来的钱"}, {"w": "缗繦", "t": "穿钱的绳子。引申为钱。"}]}, {"meaning": "古国名 。夏时之缗国,春秋时属宋,汉置东湣县,故址在今山东省金乡县东北。"}, {"meaning": "用于成串的铜钱,每串一千文。", "cites": [{"t": "钱千万缗。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "钱十万缗", "t": ""}]}, {"meaning": "安装。", "cites": [{"t": "言缗之丝。", "b": "《诗·大雅·抑》"}], "words": [{"w": "缗丝", "t": "安装弦线。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5338wx','飨','1','xiǎng','飠','12','','[{"pinyin": "xiǎng", "defs": [{"meaning": "(会意兼形声。从食,从乡,乡亦声。本义:乡人相聚宴饮)。"}, {"meaning": "同本义。", "cites": [{"t": "飨,乡人饮酒也。", "b": "《说文》"}, {"t": "飨,歆飨。", "b": "《广韵》"}, {"t": "尚蚃。", "b": "《仪礼·少牢馈食礼》"}, {"t": "将弗克飨为人而已。", "b": "《国语·晋语一》"}, {"t": "君其飨之。", "b": "《国语·晋语四》"}, {"t": "先祭而后飨。", "b": "《淮南子·说山》"}, {"t": "朋酒斯飨,曰杀羔羊。", "b": "《诗·豳风》。毛传:“飨,乡人饮酒也。”"}]}, {"meaning": "设盛宴待宾客。", "cites": [{"t": "钟鼓既没,一朝飨之。", "b": "《诗·小雅·彤弓》"}, {"t": "及飨日,帷诸门左。", "b": "《左传·昭公二十七年》"}, {"t": "夫人姜氏飨齐侯。", "b": "《谷梁传·庄公四年》。注:“飨,食也,两君相见之礼。”"}, {"t": "飨礼九献。", "b": "《周礼·大行人》"}, {"t": "壹食再飨。", "b": "《仪礼·聘礼》"}, {"t": "而后飨冠者。", "b": "《礼记·曾子问》"}], "words": [{"w": "飨客;以飨群臣;飨日", "t": "宴请之日"}, {"w": "飨赐", "t": "宴请宾客"}, {"w": "飨会", "t": "宴会。"}]}, {"meaning": "祭献。", "cites": [{"t": "[曹丕]遂统甲兵三十万,南巡沛国谯县,大飨先茔。", "b": "《三国演义》"}], "words": [{"w": "飨牢", "t": "祭献神灵或祖先的牺牲"}, {"w": "飨坟", "t": "用酒食祭扫坟茔。"}]}, {"meaning": "用酒食慰劳。", "cites": [{"t": "旦日飨士卒。", "b": "《史记·项羽本纪》"}], "words": [{"w": "飨士", "t": "以酒饭款待兵士。"}]}, {"meaning": "享受", "cites": [{"t": "子,周公之孙也,多飨大利,犹思不义。", "b": "《左传·哀公十五年》"}, {"t": "王飨礼,命之宥。", "b": "《左传·僖公二十五年》"}, {"t": "飨德怀恩。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "飨国", "t": "国君在位期间。同享国"}, {"w": "飨福", "t": "享受福祉。即享福"}, {"w": "以飨读者;飨国", "t": "享国"}, {"w": "飨年", "t": "统治国家的年数。"}]}, {"meaning": "接受酒食。", "cites": [{"t": "神飨而民听。", "b": "《国语·周语上》"}, {"t": "飨,受食亦曰飨。", "b": "清·朱骏声《说文通训定声》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5339wx','耢','1','lào','耒','13','','[{"pinyin": "lào", "defs": [{"meaning": "农具名。又名“耱”或“盖” 。用荆条或藤条编成的长方形农具,用来平整地面和松土保墒。", "cites": [{"t": "橯,摩田器。或从耒。", "b": "《集韵》"}]}, {"meaning": "用耢平整土地。", "cites": [{"t": "耖之然后耢之。", "b": "清·倪倬《农雅·释器》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5340wx','瑚','1','hú','王','13','','[{"pinyin": "hú", "defs": [{"meaning": "(形声。从玉,胡声。从玉,表示质美似玉。本义:珊瑚)。"}, {"meaning": "同本义。", "cites": [{"t": "瑚,珊瑚也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5341wx','瑁','1','mào','王','13','','[{"pinyin": "mào", "defs": [{"meaning": "天子所执的玉,用以合诸侯的圭,覆于圭上,故谓称为瑁。"}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5342wx','瑜','1','yú','王','13','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从玉,俞声。本义:美玉)。"}, {"meaning": "同本义。", "cites": [{"t": "瑾瑜,美玉也。", "b": "《说文》"}, {"t": "世子佩瑜玉。", "b": "《礼记·玉藻》"}, {"t": "无所用之,碧瑜粪土也。", "b": "《淮南子·缪称》"}], "words": [{"w": "瑜玉", "t": "美玉"}, {"w": "瑜珉", "t": "瑜,美玉;珉,似玉之石。比喻真伪、优劣"}, {"w": "瑜珥", "t": "女子耳上的装饰品"}, {"w": "瑜佩", "t": "玉佩。亦借指戴玉佩的人。"}]}, {"meaning": "玉的光彩。比喻优点。亦形容美好。", "cites": [{"t": "象载瑜。", "b": "《汉书·礼乐志》。注:“美貌也。”"}], "words": [{"w": "瑜百瑕一", "t": "比喻优点多而缺点少"}, {"w": "瑜瑕", "t": "比喻优劣好坏"}, {"w": "瑜璟", "t": "玉的光采。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5343wx','瑗','1','yuàn','王','13','','[{"pinyin": "yuàn", "defs": [{"meaning": "大孔璧。", "cites": [{"t": "瑗,大也璧也。人君上除陛以相引。从玉,爰声。", "b": "《说文》"}, {"t": "问士以璧,召人以瑗。", "b": "《荀子·聘人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5344wx','瑄','1','xuān','王','13','','[{"pinyin": "xuān", "defs": [{"meaning": "古代祭天用的璧。", "cites": [{"t": "璧,大六寸谓之瑄。", "b": "《尔雅》"}, {"t": "瑄,璧六寸也。", "b": "《说文》"}, {"t": "有司奉瑄玉。", "b": "《史记·孝武本纪》"}], "words": [{"w": "瑄玉", "t": "古代祭天用的大璧。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5345wx','瑕','1','xiá','王','13','','[{"pinyin": "xiá", "defs": [{"meaning": "(形声。从玉,叚(xiá)声。本义:玉上的斑点)。"}, {"meaning": "同本义。", "cites": [{"t": "瑕,玉小赤也。", "b": "《说文》"}, {"t": "赤瑕驳榮。", "b": "司马相如《子虚赋》。注:“赤玉也。”"}, {"t": "江珠瑕英。", "b": "左思《蜀都赋》"}, {"t": "深瑕而泽。", "b": "《考工记·弓人》"}, {"t": "璧有瑕,请指示王。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "瑕不掩瑜。", "b": "《礼记·聘义》"}], "words": [{"w": "瑕适", "t": "玉上的斑痕。比喻缺失。"}]}, {"meaning": "比喻人或事物显露出来的缺陷、缺点或小毛病。", "cites": [{"t": "心苟无瑕,何恤乎无家!", "b": "《左传·闵公元年》"}, {"t": "善言无瑕讁。", "b": "《老子》"}, {"t": "德音不瑕。", "b": "《诗·豳风·狼跋》"}, {"t": "弃瑕录用。", "b": "南朝梁·丘迟《与陈伯之书》"}], "words": [{"w": "瑕瑜", "t": "比喻人的短处和长处。"}]}, {"meaning": "裂缝;罅隙。", "cites": [{"t": "凡相胶…深瑕而泽,紾而博廉。", "b": "《周礼》"}], "words": [{"w": "瑕缝", "t": "裂缝;裂隙。"}]}, {"meaning": "引申为空虚、空子。", "cites": [{"t": "攻坚则韧,乘瑕则神。", "b": "《管子》"}], "words": [{"w": "瑕隙", "t": "可乘的间隙,嫌隙?。"}]}, {"meaning": "带红色的玉。", "cites": [{"t": "于近则有瑕英菌芝,玉石江珠。", "b": "扬雄《蜀都赋》"}]}, {"meaning": "指出缺点、毛病。引申为怪罪。", "cites": [{"t": "惟我知女,女专利而不厌,予取予求,不女疵瑕也。", "b": "《左传》"}], "words": [{"w": "瑕訾", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5346wx','遨','1','áo','辶','13','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从辵,敖声。辵,甲骨文象人足在路上行走,后演为走之旁。本义:遨游;游遨) 同本义。同“敖”。", "cites": [{"t": "从庐遨兮栖迟。", "b": "《楚辞·疾世》"}, {"t": "犹从牧儿遨。", "b": "《后汉书·刘盆子传》"}, {"t": "博鸡者遨于市。", "b": "高启《书博鸡者事》"}], "words": [{"w": "遨乐", "t": "游乐"}, {"w": "遨逸", "t": "遨游放逸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5347wx','骜','1','ào','马','13','','[{"pinyin": "ào", "defs": [{"meaning": "(形声。从马,敖声。本义:好马,良马) 同本义。", "cites": [{"t": "良马期乎千里,不期乎骥骜。", "b": "《吕氏春秋·察今》。注:“千里马也。王者乘之游敖,因曰骥骜也。”"}], "words": [{"w": "骜放", "t": "任性傲物。"}]}, {"meaning": "放纵奔驰。", "cites": [{"t": "服偃蹇以低昂兮,骖连蜷以骄骜。", "b": "《楚辞·远游》"}]}, {"meaning": "骄傲。", "cites": [{"t": "士骜爵禄者,固轻其主。", "b": "《吕氏春秋·下贤》"}, {"t": "夫智伯之为人也,好利而骜愎。", "b": "《韩非子·十过》"}, {"t": "始皇刚暴而骜狠。", "b": "《抱朴子·极言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5348wx','韫','1','yùn','韦','13','','[{"pinyin": "yùn", "defs": [{"meaning": "蕴葳;包含。", "cites": [{"t": "韫,裹也。", "b": "《广雅》?"}, {"t": "韫于荆石。", "b": "《汉书·叙传上》"}, {"t": "石韫玉而山晖。", "b": "陆机《文赋》"}], "words": [{"w": "韫藏", "t": "蓄积而未显露"}, {"w": "韫椟", "t": "隐藏其才不为世用。或指隐藏其才以待时;也指深闺中的才女"}, {"w": "韫愚", "t": "愚笨的样子"}, {"w": "韫椟而藏", "t": "比喻为才不为世用。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5349wx','髡','1','kūn','髟','13','','[{"pinyin": "kūn", "defs": [{"meaning": "(形声 。(kūn)从髟(biāo),与毛发有关,兀(wù)声。本义:古代一种剃去头发的刑罚)。"}, {"meaning": "同本义。", "cites": [{"t": "髡,剃发也。", "b": "《说文》"}, {"t": "髡者,使守积。", "b": "《周礼·掌戮》"}, {"t": "辩通凿颠者髡。", "b": "刘向《列女传》"}, {"t": "接舆髡兮。", "b": "《楚辞·屈原·涉江》"}, {"t": "乃髡钳季布。", "b": "《史记·季布栾布列传》"}], "words": [{"w": "髡刖", "t": "古代刑罚,去发称髡,断足称刖"}, {"w": "髡钳", "t": "古代刑罚,去发为髡,用铁束颈为钳"}, {"w": "髡发", "t": "剃去头发"}, {"w": "髡首", "t": "剃光头发,光头"}, {"w": "髡人", "t": "被剃去头发的罪人"}, {"w": "髡头", "t": "光头。同髡首。"}]}, {"meaning": "剪去树枝。", "cites": [{"t": "十年以后,髡一树,得一载,岁髡二百树,五年一周。", "b": "《齐民要术》"}]}]}]','jingmo-wenyan');
