INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5351wx','鄢','1','yān','阝','13','','[{"pinyin": "yān", "defs": [{"meaning": "古邑名。"}, {"meaning": "春秋楚别都,汉惠帝时改为宜城,在今湖北省宜城县。"}, {"meaning": "春秋莒邑。又名鄢陵、安陵,在今山东省沂水县境。"}, {"meaning": "周国名 。春秋时为郑所灭,改名鄢陵,在今河南省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
