INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5353wx','趑','1','zī','走','13','','[{"pinyin": "zī", "defs": [{"meaning": "趑趄。", "cites": [{"t": "一人荷锄，万夫趑趄。--张载《剑阁铭》", "b": ""}, {"t": "彼则趑趄于卿士之门，我则婆娑于圣贤之域。--皇浦湜《谕业》", "b": ""}, {"t": "陈顼因循伪业，自擅金陵，屡遣丑徒，趑趄江北。--《隋书》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5354wx','摅','1','shū','扌','13','','[{"pinyin": "shū", "defs": [{"meaning": "抒发;表达。", "cites": [{"t": "摅,张也。", "b": "《广雅》"}, {"t": "摅之无穷。", "b": "《史记·司马相如列传》。李隐:“摅,张舒也。”"}, {"t": "摅书明指以示之。", "b": "《淮南子·脩务》。注:“摅,抒也。”"}, {"t": "心犹凭而未摅。", "b": "张衡《西京赋》"}, {"t": "摅怀旧之蓄念。", "b": "《后汉书·班彪传上》"}, {"t": "摅之罔极。", "b": "《后汉书·和熹邓皇后纪》"}, {"t": "摅怀旧之蓄念,发思古之幽情。", "b": "班固《西都赋》"}], "words": [{"w": "摅愤", "t": "抒发积愤"}, {"w": "摅怀", "t": "抒发情怀"}, {"w": "摅意", "t": "抒发情感"}, {"w": "摅吐", "t": "抒发吐露"}, {"w": "摅抱", "t": "抒发胸怀"}, {"w": "摅情", "t": "抒发情怀"}, {"w": "摅散", "t": "舒散,抒发,消释"}, {"w": "摅颂", "t": "抒发歌颂之情。"}]}, {"meaning": "散布。", "cites": [{"t": "故摅道以被民而民弗从者,诚心弗施也。", "b": "刘安《淮南子》"}]}, {"meaning": "舒展。", "cites": [{"t": "卒不能摅首尾,奋翼鳞。", "b": "《文选·班固·答宾戏》"}]}, {"meaning": "撕。", "cites": [{"t": "我将衫儿摅下一块来。", "b": "元·杨暹《西游记》"}]}, {"meaning": "传播。", "cites": [{"t": "将以识往行,摅无穷,使本支百代,不忘先人之不陨其名也。", "b": "《唐西台舍人赠泗洲剌史徐府君碑》"}]}, {"meaning": "腾跃。", "cites": [{"t": "仆夫俨其正策兮,八乘摅而超骧。", "b": "张衡《思玄赋》"}], "words": [{"w": "龙摅", "t": "龙腾。"}]}]}]','jingmo-wenyan');
