INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5356wx','蜇','1','zhē zhé','虫','13','','[{"pinyin": "zhē", "defs": [{"meaning": "毒虫叮刺。", "cites": [{"t": "苦咸酸辛,虽蜇吻裂鼻,缩舍涩齿,而咸有笃好之者。", "b": "唐·柳宗元《读韩愈所著毛颖传后题》"}], "words": [{"w": "蜇杀", "t": "毒虫叮咬致死"}, {"w": "蝎子蜇人;蜇螫", "t": "毒蛇咬。"}]}, {"meaning": "刺痛;刺伤。", "cites": [{"t": "乡豪取而尝之,蜇于口,惨于腹。", "b": "《列子》"}], "words": [{"w": "切洋葱蜇眼睛;蜇鼻", "t": "刺激鼻子而感到微痛。"}]}, {"meaning": "折磨;毒害;苦楚。", "cites": [{"t": "如来!我师徒受了万蜇千魔,自东土拜到此处,蒙如来吩咐传经。", "b": "《西游记》"}]}]}, {"pinyin": "zhé", "defs": [{"meaning": "", "words": [{"w": "海蜇;蜇花", "t": "指海蜇腹下的众多的脚。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5357wx','搋','1','chuāi','扌','13','','[{"pinyin": "chuāi", "defs": [{"meaning": "藏物于怀。", "cites": [{"t": "只见陶铁僧栾了四五十钱,鹰觑鹘望,看布帘里面,约莫没人见,把那见钱怀中便搋。", "b": "《警世通言》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5358wx','搪','1','táng','扌','13','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从手,唐声。本义:张)。"}, {"meaning": "同本义。", "cites": [{"t": "搪,张也。", "b": "《方言十三》。郭注:“谓彀张也。”"}]}, {"meaning": "抵挡。", "cites": [{"t": "斗不数合,小龙委实难塘。", "b": "《西游记》。又如:搪不住风雨;搪拒(抵御,抗拒);搪撑(牴触);搪报(紧急军情报告);搪撞(冲撞,冒犯);搪击(抗击);搪突(冒犯;抵触;接触)"}]}, {"meaning": "骗取,混。", "cites": [{"t": "搪得几碗酒吃。", "b": "明·冯梦龙《警世通言》"}, {"t": "那厮一地里去塘酒吃,只是搬是弄非。", "b": "《水浒传》"}]}, {"meaning": "荡;划。", "cites": [{"t": "只见那只船搪将开去。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5359wx','搐','1','chù','扌','13','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从手,畜声。本义:牵动,抽缩)。"}, {"meaning": "退缩。", "cites": [{"t": "我有刀来你有枪,前前搐搐不成像。", "b": "清·蒲松龄《聊斋俚曲集》"}]}]}]','jingmo-wenyan');
