INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5361wx','搠','1','shuò','扌','13','','[{"pinyin": "shuò", "defs": [{"meaning": "戳,刺。", "cites": [{"t": "林冲举手,肐察的一枪,先搠倒差拨。", "b": "《水浒传》"}], "words": [{"w": "搠杀", "t": "刺死"}, {"w": "搠番", "t": "刺倒;扎倒。"}]}, {"meaning": "插。", "cites": [{"t": "只见女墙边虚搠旌旗,无人守护。", "b": "《三国演义》"}]}, {"meaning": "用力推。", "cites": [{"t": "那妇人将盘一搠,且不收拾。", "b": "《初刻拍案惊奇》"}]}, {"meaning": "寻访。", "cites": [{"t": "捞水底月觅衣食,如投吕先生访故友,似寻吴文政搠如相知。", "b": "元·郑廷玉《金凤钗》"}]}, {"meaning": "蘸;沾。", "cites": [{"t": "只拣那卖不去的菜叶儿,将来煨熟了,又不要蘸盐搠酱,只吃一碗淡粥。", "b": "元·秦简夫《东堂老》"}]}, {"meaning": "搠渰  亦作“塑渰”。装痴作呆。", "cites": [{"t": "你妆憨,咱塑渰,影羞惭。", "b": "元·曾瑞《骂玉郎过感皇恩采茶歌·风情》曲"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5362wx','摈','1','bìn','扌','13','','[{"pinyin": "bìn", "defs": [{"meaning": "排斥;弃绝。", "cites": [{"t": "摈,相排斥也。", "b": "《玉篇》"}, {"t": "贤者摈于朝。", "b": "《淮南子·说林训》"}, {"t": "六国从亲以摈秦。", "b": "《战国策·赵策》"}, {"t": "已摈忧患寻常事,留得豪情作楚囚。", "b": "恽代英《狱中诗》"}], "words": [{"w": "摈兑", "t": "除掉;以命换命"}, {"w": "摈落", "t": "排去,弃而不用"}, {"w": "摈压", "t": "受到排斥压迫。"}]}, {"meaning": "导引宾客。", "cites": [{"t": "宗人摈。", "b": "《仪礼·有司彻》"}, {"t": "君召使摈,色勃如也。", "b": "《论语·乡党》"}, {"t": "掌九仪之宾客摈相之礼。", "b": "《周礼·司仪》"}, {"t": "凡四方之使者,大客则摈。", "b": "《周礼·小行人》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5363wx','彀','1','gòu','弓','13','','[{"pinyin": "gòu", "defs": [{"meaning": "张满弓。", "cites": [{"t": "彀,张弩也。", "b": "《说文》"}, {"t": "彀弓弩,持满。", "b": "《汉书·周亚夫传》"}, {"t": "羿之教人射,必志于彀。", "b": "《孟子·告子上》"}]}, {"meaning": "箭靶。", "cites": [{"t": "羿有以感弓矢,故彀可得而中也。", "b": "《管子·小称》"}]}, {"meaning": "目标,目的。", "cites": [{"t": "夫言行者,以功用为之的彀者也。", "b": "《韩非子·问辩》"}]}, {"meaning": "程式。", "cites": [{"t": "诗虽不入彀,而笔力甚雅,每出人意表。", "b": "刘献廷《广阳杂记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5364wx','毂','1','gū gǔ','殳','13','','[{"pinyin": "gū", "defs": [{"meaning": "轱辘"}]}, {"pinyin": "gǔ", "defs": [{"meaning": "(形声。从车 。本义: 车轮中心的圆木, 周围与车辐的一端相接, 中有圆孔, 可以插轴)。"}, {"meaning": "同本义。", "cites": [{"t": "操吴戈兮被犀甲,车错毂兮短兵接。", "b": "《楚辞·屈原·国殇》"}]}, {"meaning": "泛指车。", "cites": [{"t": "转毂百数(百数:指数量多)。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5365wx','搦','1','nuò','扌','13','','[{"pinyin": "nuò", "defs": [{"meaning": "(形声。从手,弱声。本义:用力按压)。"}, {"meaning": "同本义。", "cites": [{"t": "搦,按也。", "b": "《说文》"}, {"t": "桡之。", "b": "《考工记·弓人》。注:“桡搦其干。”"}, {"t": "搦秦起赵。", "b": "左思《魏都赋》"}]}, {"meaning": "拿或握在手中。", "cites": [{"t": "舟子于是搦棹。", "b": "郭璞《江南赋》"}], "words": [{"w": "搦管;搦掉", "t": ""}]}, {"meaning": "挑斗;惹。", "cites": [{"t": "又下将战书来,搦俺十八路诸侯相持。", "b": "元·郑光祖《三战吕布》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5366wx','搡','1','sǎng','扌','13','','[{"pinyin": "sǎng", "defs": [{"meaning": "用力推使力～。将他～了个跟头。", "cites": [{"t": "被丁言志搡了一交。--《儒林外史》", "b": ""}, {"t": "伊…装好一碗饭，搡在七斤的面前。--鲁迅《呐喊》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5367wx','蓁','1','zhēn','艹','13','','[{"pinyin": "zhēn", "defs": [{"meaning": "草茂盛的样子。", "cites": [{"t": "蓁,草盛貌。", "b": "《说文》"}, {"t": "百谷蓁蓁。", "b": "《文选·班固·东都赋》"}], "words": [{"w": "蓁薮", "t": "草木生长茂盛的沼泽。指荒芜之地。"}]}, {"meaning": "丛生的草木。", "cites": [{"t": "逃于深蓁。", "b": "《庄子·徐无鬼》"}, {"t": "蝮蛇蓁蓁。", "b": "《楚辞·招魂》"}], "words": [{"w": "蓁子", "t": "榛子"}, {"w": "蓁莽", "t": "杂乱丛生的草木"}, {"w": "蓁菅", "t": "丛生的茅草。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5368wx','戡','1','kān','戈','13','','[{"pinyin": "kān", "defs": [{"meaning": "(形声。从戈,甚声。本义:刺杀)。"}, {"meaning": "同本义。", "cites": [{"t": "戡,刺也。", "b": "《说文》。字亦作勘。"}, {"t": "西伯既戡黎。", "b": "《书·西伯戡黎》"}]}, {"meaning": "用武力平定。", "cites": [{"t": "戡,克也。", "b": "《尔雅》"}, {"t": "兴元戡难功。", "b": "《旧唐书·陆贽传》"}], "words": [{"w": "戡夷", "t": "平定,征讨使服从"}, {"w": "戡平叛乱;戡殄", "t": "平定歼灭"}, {"w": "戡复", "t": "犹言中兴。平定叛乱"}, {"w": "戡剪", "t": "平定剪除"}, {"w": "戡戮", "t": "平定诛戮"}, {"w": "戡济", "t": "戡定。平定。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5369wx','蓍','1','shī','艹','13','','[{"pinyin": "shī", "defs": [{"meaning": "蓍草 。古代常以其茎用作占卜。", "cites": [{"t": "蓍,蒿属。从草,耆声。生千岁三百茎。", "b": "《说文》"}, {"t": "蓍,百年一本生百茎。", "b": "《尚书大传》"}, {"t": "幽赞于神明而生蓍。", "b": "《易·说卦传》"}, {"t": "冽彼下泉,浸彼苞蓍。", "b": "《诗·曹风·下泉》"}, {"t": "成天下之亹亹者,莫大乎著龟。", "b": "《龟·系辞》"}], "words": [{"w": "蓍龟", "t": "蓍草和龟甲。古时用以占卜"}, {"w": "蓍蔡", "t": "指卜筮。蓍草与大龟,是占卜吉凶的用具"}, {"w": "蓍簪", "t": "用蓍草茎做成的簪子"}, {"w": "蓍艾", "t": "蓍草与艾草"}, {"w": "蓍草", "t": "即蓍。古代用以占卜的草。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5370wx','鄞','1','yín','阝','13','','[{"pinyin": "yín", "defs": [{"meaning": "古地名。春秋时属越,即今浙江省鄞县。"}, {"meaning": "边际;界限。引申指形体,躯体。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5371wx','靳','1','jìn','革','13','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从革,斤声。从“革”,表示与皮革有关。本义:套在辕马胸部的皮革,也用作辕马的代称)。"}, {"meaning": "同本义。", "cites": [{"t": "靳,当膺也。", "b": "《说文》"}, {"t": "吾从子,如骖之靳。", "b": "《左传·定公九年》。注:“车中马也。言如骖马之首,当服马之靳,相随从也。”"}], "words": [{"w": "靳令", "t": "靳固,确定。指严格执行法令"}, {"w": "靳道", "t": "同“劲道”。指面觔吃起来有韧性。喻性格柔中有刚。"}]}, {"meaning": "游环 。在马服背上的皮环,骖马的外辔穿过它,以便起到控制骖马奔离车辕的作用。", "cites": [{"t": "弸辕谓之靳。", "b": "《广雅》"}]}, {"meaning": "吝惜。", "cites": [{"t": "悔不小靳,可至千万。", "b": "《后汉书·崔石传》"}], "words": [{"w": "靳惜", "t": "靳啬。吝啬,小气"}, {"w": "靳色", "t": "吝惜的脸色"}, {"w": "靳固", "t": "吝惜固执"}, {"w": "靳令", "t": "严格执行法令"}, {"w": "靳道", "t": "韧性"}, {"w": "靳而不与", "t": ""}]}, {"meaning": "讥笑。", "cites": [{"t": "宋公靳之。", "b": "《左传·庄公十一年》。杜预注:“戏而相愧曰靳。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5372wx','蓐','1','rù','艹','13','','[{"pinyin": "rù", "defs": [{"meaning": "(形声。从艸,辱声。本义:陈草复生)。"}, {"meaning": "同本义。", "cites": [{"t": "蓐,陈草复生也。", "b": "《说文》。徐锴系传:“陈根更生繁缛也。…言草繁多也。”"}]}, {"meaning": "草席;草垫。", "cites": [{"t": "蓐谓之兹。", "b": "《尔雅》。注;“兹者,蓐席也。”"}, {"t": "左追蓐。", "b": "《左传·宣公十二年》。注:“在左者追求草蓐为宿备。”疏:“蓐,谓卧土之草。”"}, {"t": "范乃令军中蓐食。", "b": "《后汉书·廉范传》"}], "words": [{"w": "蓐母", "t": "产婆,接生婆"}, {"w": "蓐妇", "t": "产妇;生产之妇女"}, {"w": "蓐劳", "t": "中医病名。此病因产时不顺,疲累过度,产后气血衰弱,调养失宜,导致虚邪侵入,阴虚成劳"}, {"w": "蓐食", "t": "早晨未起身,在床席上进餐。谓早餐时间很早。"}]}, {"meaning": "坐卧时铺在床椅上面的垫子,褥子。", "cites": [{"t": "有重疾,卧蓐七年。", "b": "《后汉书·赵岐传》"}]}, {"meaning": "蚕蔟。用麦秆等做成,蚕在上面做茧。", "cites": [{"t": "蓐,蔟也。", "b": "《说文》"}]}, {"meaning": "古国名 。地在汾水流域,春秋时为晋国所灭。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5373wx','蓦','1','mò','艹','13','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从马,莫声。本义:骑)。"}, {"meaning": "同本义。", "cites": [{"t": "蓦,上马也。", "b": "《说文》"}, {"t": "蓦六駮。", "b": "左思《吴都赋》"}]}, {"meaning": "冒;冲(上来)。", "cites": [{"t": "杨雄看了那妇人,一时蓦上心来。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5374wx','鹋','1','miáo','鸟','13','','[{"pinyin": "miáo", "defs": [{"meaning": "鹋鹩莺属的一种鸟。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5375wx','蒽','1','ēn','艹','13','','[{"pinyin": "ēn", "defs": [{"meaning": "结晶三环烃  C6H4(CH)2C6H4,其纯品为白色带紫色荧光,在蒸馏煤焦油最后阶段得到,用作发光材料(如在闪烁计数器中),特别是用于涂层(如用于吸收紫外光)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5376wx','蓓','1','bèi','艹','13','','[{"pinyin": "bèi", "defs": [{"meaning": "蓓蕾的简称。含苞未开放的花。", "cites": [{"t": "金蓓锁春寒,恼人香未展。", "b": "宋·黄庭坚《戏咏腊梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5377wx','蓖','1','bì','艹','13','','[{"pinyin": "bì", "defs": [{"meaning": "草本植物。种子叫蓖麻子，榨的油可做泻药或润滑油。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5378wx','蓊','1','wěng','艹','13','','[{"pinyin": "wěng", "defs": [{"meaning": "草木蓬勃茂盛的样子。", "cites": [{"t": "蓊,蓊郁,草木盛貌。", "b": "《广韵》"}, {"t": "蓊茸萧瑟。", "b": "《文选·左思·吴都赋》"}], "words": [{"w": "蓊茸", "t": "茂盛的样子"}, {"w": "蓊蓊", "t": "草木繁盛茂密的样子"}, {"w": "蓊蔚", "t": "草木繁盛茂密的样子"}, {"w": "蓊茂", "t": "草木茂盛的样子"}, {"w": "蓊秽", "t": "草木茂盛的样子"}, {"w": "蓊蔼", "t": "形容草木郁茂"}, {"w": "蓊蔚洇润", "t": "茂盛润泽的样子"}, {"w": "蓊茸", "t": "密盛的样子"}, {"w": "蓊荟", "t": "草木繁密的样子"}, {"w": "蓊萲", "t": "形容草木茂密多荫"}, {"w": "蓊濛", "t": "浓郁。"}]}, {"meaning": "蒜、韭菜、油菜等生花的茎。", "cites": [{"t": "蓊,薹也。", "b": "《广雅》。王念孙疏证:“今世通谓草心抽茎作华者为薹矣。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5379wx','蒯','1','kuǎi','艹','13','','[{"pinyin": "kuǎi", "defs": [{"meaning": "蒯草 。多年生草本植物,叶条形,花褐色。生长在水边或阴湿的地方,茎可编席,也可造纸。", "cites": [{"t": "虽有丝麻,无弃菅蒯。", "b": "《左传·成公九年》"}], "words": [{"w": "蒯席", "t": "蒯草编的席"}, {"w": "蒯履", "t": "用蒯草打的草鞋。"}]}, {"meaning": "古地名 。春秋周畿内地,在今河南省洛阳市西南。"}, {"meaning": "用指甲挠。", "cites": [{"t": "我绰着经儿,只望着他那痒处替他蒯。", "b": "《醒世恒言》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5380wx','蓟','1','jì','艹','13','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从艸,魝jiè声。本义:蓟属植物的泛称)。"}, {"meaning": "古州名 。唐开元十八年置。治所在渔阳(今天津市蓟县)。"}, {"meaning": "古县名。"}, {"meaning": "蓟县。秦置。治所在今北京城西南。"}, {"meaning": "县名。在天津市北部,邻接北京市和河北省。秦置无终县,隋改渔阳县,明入蓟州,1913年改为蓟县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5381wx','蓑','1','suō','艹','13','','[{"pinyin": "suō", "defs": [{"meaning": "(象形。从艸,衰声。古文上象笠,中象人面,下象衰形。字亦作“蓑”。“蓑”是后起字。本义:雨具名。即蓑衣) 同本义。", "cites": [{"t": "衰,草雨衣也。秦谓之萆。", "b": "《说文》。字亦作蓑。"}, {"t": "何蓑何笠。", "b": "《诗·小雅·无羊》"}, {"t": "橐车载蓑笠。", "b": "《仪礼·既夕礼》"}, {"t": "被蓑以当铠鑐。", "b": "《管子·禁藏》"}, {"t": "地里还有工作的农民,披着蓑戴着笠。", "b": "《春》"}], "words": [{"w": "蓑笠", "t": "蓑衣和斗笠"}, {"w": "蓑褐", "t": "蓑衣短褐。比喻衣着粗劣"}, {"w": "蓑翁", "t": "穿蓑衣的老人。指渔翁。"}]}, {"meaning": "用草覆盖;掩。", "cites": [{"t": "仲几之罪何?不蓑城也。", "b": "《公羊传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5382wx','蒿','1','hāo','艹','13','','[{"pinyin": "hāo", "defs": [{"meaning": "(形声。从艸,高声。本义:草名。有白蒿、青蒿、牡蒿、臭蒿等多种。特指青蒿)。"}, {"meaning": "即青蒿。", "cites": [{"t": "呦呦鹿鸣,食野之蒿。", "b": "《诗·小雅·鹿鸣》"}]}, {"meaning": "用同“薅”。", "cites": [{"t": "我把花子腿砸折了,把淫妇鬓毛都蒿净了。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
