('5386wx','蒡','1','bàng','艹','13','','[{"pinyin": "bàng", "defs": [{"meaning": "——“牛蒡”(niúbàng):多年生草本植物,心脏形叶夏季开紫红色小花,果实瘦小。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5387wx','蒹','1','jiān','艹','13','','[{"pinyin": "jiān", "defs": [{"meaning": "初生的芦苇。", "words": [{"w": "蒹葭", "t": "蒹:未曾秀穗的芦荻；葭:初生的芦苇。两者都是常见的贱值水草"}, {"w": "蒹葭倚玉", "t": "因为芦苇与玉树贵贱悬殊,后用以比喻人与人对比不相称"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5388wx','蒴','1','shuò','艹','13','','[{"pinyin": "shuò", "defs": [{"meaning": "果实的一种类型 。干燥裂开性的、结许多子的果实,通常由两个或更多心皮组成,成熟时种子通过气孔或荚片燥裂而释放出来。通称“槊果”。", "cites": [{"t": "结蒴似荞麦蒴而圆,中有小子,如油子大。", "b": "《救荒本草》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5389wx','蒗','1','làng','艹','13','','[{"pinyin": "làng", "defs": [{"meaning": "—— “宁蒗”(Nínglàng):彝族自治县,在云南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5390wx','蓥','1','yíng','艹','13','','[{"pinyin": "yíng", "defs": [{"meaning": "琢磨使发光。亦作“莹”。", "cites": [{"t": "莹,磨也。", "b": "《广雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5391wx','颐','1','yí','页','13','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从页(xié),臣(yí)声。臣,面颊,繁化作“颐”。本义:下巴) 同本义。", "cites": [{"t": "颐,颌也。", "b": "《方言十》"}, {"t": "颐,或曰辅车,或曰牙车,或曰颊车。", "b": "《释名》"}, {"t": "后稷岐颐自求。", "b": "《春秋元命苞》"}, {"t": "端行颐霤如矢。", "b": "《礼记·玉藻》"}, {"t": "手指颐指。", "b": "《庄子·天地》"}, {"t": "擢项颐。", "b": "《汉书·东方朔传》"}, {"t": "彖曰:“颐中有物曰噬嗑。”", "b": "《易·噬嗑》"}, {"t": "大耳横颐方面相,肩查腹满身躯胖。", "b": "《西游记》"}, {"t": "方额广颐。", "b": "《新唐书》"}], "words": [{"w": " 颐腮", "t": "头颅"}, {"w": "颐脱", "t": "下颚骨脱臼"}, {"w": " 颐溜", "t": "俯身伸首平视, 下巴如屋溜下垂。形容礼敬的样子。"}]}, {"meaning": "保养。", "cites": [{"t": "颐者,养也。", "b": "《易·序卦》"}, {"t": "百年曰期颐。", "b": "《礼记·曲礼》"}, {"t": "恶饮食乎陋巷兮,亦足以颐神而保年。", "b": "唐·韩愈《闵己赋》"}], "words": [{"w": "颐志", "t": "养志"}, {"w": "颐育", "t": "养育"}, {"w": "颐神", "t": "保养精神"}, {"w": "颐爱", "t": "保养爱惜"}, {"w": "颐贤", "t": "培养人才"}, {"w": "颐养精神", "t": "保养元气"}, {"w": "颐身", "t": "保养身心"}, {"w": "颐年", "t": "保养延年"}, {"w": "颐老", "t": "养老"}, {"w": "颐养天年", "t": "保养年寿"}, {"w": "颐神养性", "t": "保养精神元气。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5392wx','楔','1','xiē','木','13','','[{"pinyin": "xiē", "defs": [{"meaning": "(形声。从木,契(qì)声。本义:楔子,上粗下锐的小木橛)。"}, {"meaning": "同本义。", "cites": [{"t": "楔,櫼也。", "b": "《说文》"}, {"t": "复楔齿缀足。", "b": "《礼记·檀弓》"}, {"t": "大者以为舟航柱梁,小者以为楫楔。", "b": "《淮南子》"}], "words": [{"w": "木楔,竹楔", "t": ""}]}, {"meaning": "楔形物。", "cites": [{"t": "楔貌如轭上两末。", "b": "《仪礼·既夕礼》"}], "words": [{"w": "光楔;雷楔", "t": ""}]}, {"meaning": "门两旁的木柱。", "cites": [{"t": "枨谓之楔。", "b": "《尔雅》。注:“门两旁木。”"}]}, {"meaning": "把楔形物插入或捶打到物体里面。", "cites": [{"t": "楔齿用角柶。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "楔齿", "t": "古时人初死,用柶撑其齿使不闭合,以便于饭含柶礼器"}, {"w": "墙上楔个钉子;建筑工人把木隔板楔在顶部的结构上", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5393wx','楠','1','nán','木','13','','[{"pinyin": "nán", "defs": [{"meaning": "(形声。从木,南声。本义:楠木)同本义。樟科,常绿乔木。木材纹理细密,质地坚硬,富有香味,是建筑和制器具的贵重木材。", "cites": [{"t": "时珍曰:南方之木,故字从南。", "b": "《本草纲目》"}, {"t": "文梓楩楠。", "b": "《墨子·公输》"}, {"t": "江南出楠梓。", "b": "《史记·货殖列传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5394wx','楂','1','chá zhā','木','13','','[{"pinyin": "chá", "defs": [{"meaning": "水中木筏。", "cites": [{"t": "穷岸有盘楂。", "b": "何逊《度连圻》"}]}, {"meaning": ""}]}, {"pinyin": "zhā", "defs": [{"meaning": "果木名 ,指蔷薇科山楂、野山楂一类的植物。果实红色、味酸,可食,也可入药。", "cites": [{"t": "云山得伴松桧老,霜雪自困楂梨粗。", "b": "宋·苏轼《四月十一日初食荔枝》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5395wx','楝','1','liàn','木','13','','[{"pinyin": "liàn", "defs": [{"meaning": "楝树 。俗名“苦楝子”。亚洲的一种速生的小乔木。两回羽状复叶大,花芳香、紫色、簇生而开展,果光滑、黄色。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5396wx','楫','1','jí','木','13','','[{"pinyin": "jí", "defs": [{"meaning": "(形声短的船桨)。"}, {"meaning": "同本义。短曰楫,长曰楫。", "cites": [{"t": "棹,短曰楫,长曰棹。", "b": "《韵会》"}, {"t": "楫,舟擢也。", "b": "《说文》"}, {"t": "桧楫桧舟。", "b": "《诗·卫风·竹竿》"}, {"t": "楫齐扬以容与兮。", "b": "《楚辞·哀郢》。注:“船櫂也。”"}, {"t": "亡维楫。", "b": "《汉书·贾谊传》"}]}, {"meaning": "泛指船桨。", "cites": [{"t": "假舟楫者,非能水也,而绝江河。", "b": "《荀子·劝学》"}, {"t": "樯倾楫摧。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "横卧一楫。", "b": "明·魏学洢《核舟记》"}, {"t": "楫左右舟子各一人。", "b": ""}], "words": [{"w": "中流击楫;舟楫;楫子", "t": "船桨"}, {"w": "楫橹", "t": "桨与橹"}, {"w": "楫櫂", "t": "船桨。"}]}, {"meaning": "船。", "cites": [{"t": "通民楫,而阻夷船之闯入者。", "b": "梁延《夷氛闻记》"}], "words": [{"w": "闄櫂", "t": "船"}, {"w": "楫师", "t": "船工。"}]}, {"meaning": "划。", "cites": [{"t": "淠彼泾舟,烝徒楫之。", "b": "《诗·大雅·稢朴》"}, {"t": "一手附舟傍,一手楫水而至岸也。", "b": "明·费信《星槎胜览》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5397wx','楸','1','qiū','木','13','','[{"pinyin": "qiū", "defs": [{"meaning": "落叶乔木,干高叶大,夏天开黄绿色细花,木材质地致密,可做器具。", "cites": [{"t": "揪,梓也。", "b": "《说文》"}, {"t": "望长楸而太息兮。", "b": "《楚辞·哀郢》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5398wx','椴','1','duàn','木','13','','[{"pinyin": "duàn", "defs": [{"meaning": "椴树属植物的泛称 。本属在中国有三十余种。落叶乔木,像白杨,木材细致,可以制造蒸笼、铅笔和火柴等", "words": [{"w": "大叶椴", "t": ""}, {"w": "华椴", "t": ""}, {"w": "黔椴", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5399wx','槌','1','chuí','木','13','','[{"pinyin": "chuí", "defs": [{"meaning": "(形声。从木,追声。本义:槌子,敲击工具) 同本义。", "cites": [{"t": "凿所以入木者,槌叩之也。", "b": "汉·王充《论衡》"}], "words": [{"w": "鼓槌;槌杵", "t": "棒槌"}, {"w": "槌砧", "t": "铁锤和铁砧"}, {"w": "槌轮", "t": "用竹木做成载人或运货的车子"}, {"w": "槌棒", "t": "敲打用的木棒。"}]}, {"meaning": "捶打;敲击。", "cites": [{"t": "阿母得闻之,槌床便大怒。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "收得馥大儿,槌折两脚。", "b": "《三国志·袁绍传》注"}], "words": [{"w": "槌心", "t": "自槌胸脯"}, {"w": "槌牛", "t": "击杀牛"}, {"w": "槌胸踏地", "t": "捶胸顿足"}, {"w": "槌鼓", "t": "击鼓"}, {"w": "槌毁", "t": "抨击诋毁"}, {"w": "槌击", "t": "敲击"}, {"w": "槌枪", "t": "古兵器名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5400wx','楯','1','dùn shūn','木','13','','[{"pinyin": "dùn", "defs": [{"meaning": "(形声。从木,盾声。①(shǔn)本义:栏干的横木。②引申义:通“盾”。盾牌) 同引申义。", "cites": [{"t": "楚人有鬻楯与矛者。", "b": "《韩非子·难一》"}, {"t": "左执楯而导之。", "b": "《新唐书》"}]}]}, {"pinyin": "shūn", "defs": [{"meaning": "栏杆的横木。", "cites": [{"t": "楯类腾龙。", "b": "何晏《景福殿赋》"}, {"t": "又杂植兰桂竹木于庭,旧时栏楯,亦逆增胜。", "b": "明·归有光《项脊轩志》"}]}, {"meaning": "泛指栏杆。", "cites": [{"t": "奔星更于闺闼,宛虹拖于楯轩。", "b": "《史记·司马相如列传》"}], "words": [{"w": "楯柱", "t": "殿前栏槛柱子"}, {"w": "楯轩", "t": "指有栏杆的长廊或小室"}, {"w": "楯梯", "t": "古代攻城的长梯"}, {"w": "楯楹", "t": "栏杆和楹柱"}, {"w": "楯槛", "t": "楯栏。栏杆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5401wx','皙','1','xī','白','13','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从白,析声。日光具有“白色”之义。本义:皮肤白净)。"}, {"meaning": "同本义(白得雅气,好看)。", "cites": [{"t": "皙,人色白也。", "b": "《说文》"}, {"t": "扬且之皙也。", "b": "《诗·鄘风·君子偕老》"}, {"t": "其民皙而瘠。", "b": "《周礼·大司徒》"}, {"t": "白皙疏眉目。", "b": "《汉书·霍光传》"}, {"t": "为人洁白皙。", "b": "《乐府诗集·陌上桑》"}, {"t": "人间好妙年,不必须白皙。", "b": "杜甫《送李校书二十六韵》"}, {"t": "吴儿多白皙,好为荡舟剧。", "b": "李白《越女词》"}], "words": [{"w": "皙皙", "t": "形容清秀白净。"}]}, {"meaning": "白色。", "cites": [{"t": "有先登者,臣从之,皙帻而衣狸制。", "b": "《左传·定公九年》。杜预注:“皙,白也。”"}], "words": [{"w": "皙人", "t": "白种人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5402wx','榈','1','lǘ','木','13','','[{"pinyin": "lǘ", "defs": [{"meaning": "——见“棕榈”(zōnglǘ)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5403wx','槎','1','chá zhà','木','13','','[{"pinyin": "chá", "defs": [{"meaning": "用刀斧砍斫。", "cites": [{"t": "山不槎蘖,泽不伐夭。", "b": "《国语·鲁语上》"}]}, {"meaning": "树木的枝桠。", "words": [{"w": "槎牙", "t": "亦作“槎桠”。错杂、参差不齐的样子;又指枝叉"}, {"w": "槎丫", "t": "槎砑。本指树枝的分叉,也指怪石歧出的状态。"}]}]}, {"pinyin": "zhà", "defs": [{"meaning": "斫、斜砍。", "cites": [{"t": "且夫山不槎蘖,泽不伐天。", "b": "《国语·鲁语上》"}], "words": [{"w": "槎山", "t": "劈山开路"}, {"w": "槎孽", "t": "砍伐幼林。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5404wx','榉','1','jǔ','木','13','','[{"pinyin": "jǔ", "defs": [{"meaning": "榉树 。一种榆科落叶乔木(Zelkova schneideriana),叶互生、排为两行、椭圆状卵形、单锯齿,花单性、雌雄同株,坚果小、球形,木材坚实,为上等家具用材,还供建筑、造船用,分布于中国、日本、朝鲜。", "cites": [{"t": "榉树,山中处处有之,皮似檀槐,叶如栎槲。", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5405wx','楦','1','xuàn','木','13','','[{"pinyin": "xuàn", "defs": [{"meaning": "(楥俗作楦)木制的鞋楦子。", "cites": [{"t": "楥,履法也。从木,爰声。", "b": "《说文》。字亦作楦。苏俗谓之楦头。削木如履,置履中使履成如式。平直不皴。"}], "words": [{"w": "楦排", "t": "鞋楦"}, {"w": "楦头", "t": "制鞋用的木制模型。"}]}, {"meaning": "将物体的中空部分填实或撑大。", "cites": [{"t": "譬如贼偷和狗咬,他凭楦得大肚饱。", "b": "刘大白《田主来》"}], "words": [{"w": "楦麒麟", "t": "谓虚有其表"}, {"w": "楦酿", "t": "谓杂凑,凑搭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5406wx','楣','1','méi','木','13','','[{"pinyin": "méi", "defs": [{"meaning": "(形声。从木,眉声。本义:屋檐口椽端的横板)。"}, {"meaning": "同本义。", "cites": [{"t": "楣,屋边联也。齐谓之檐,楚谓之梠,秦谓之楣。", "b": "《说文》。徐锴曰:“按尔雅,‘楣谓之梁’谓门上横梁也。”"}, {"t": "阳气见于眉(楣)宇之间。", "b": "枚乘《七发》。按,以屋之近前下垂处,喻额前也。"}, {"t": "主人阼阶上当楣。", "b": "《仪礼·乡饮礼》"}, {"t": "公当楣北乡皆是也。", "b": "《仪礼·公食礼》"}, {"t": "苍藤蔽檐楣,楚楚干云势。", "b": "明·袁宏道《十景园小集》"}]}, {"meaning": "也指门框上的横木。也叫“门楣”。", "cites": [{"t": "蜗舍入门楣触额", "b": "陆游《夏雨叹》"}, {"t": "雕琉璃于翠楣。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "楣机", "t": "比喻关键、重要之处。"}]}, {"meaning": "房屋的横梁,即二梁。", "cites": [{"t": "楣谓之梁。", "b": "《尔雅》。注:“门户上横梁。”"}, {"t": "剪屏柱楣。", "b": "《仪礼·丧服传》。注:“柱楣所谓梁闇。”"}, {"t": "盘山越岭,接栋连楣。", "b": "王勃《大观阁序》"}], "words": [{"w": "楣梁", "t": "房屋的次梁"}, {"w": "楣栋", "t": "屋的正梁和次梁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5407wx','楹','1','yíng','木','13','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从木,盈声。本义:厅堂前部的柱子)。"}, {"meaning": "同本义。", "cites": [{"t": "楹,柱也。", "b": "《说文》"}, {"t": "旅楹有闲。", "b": "《诗·商颂·殷武》"}, {"t": "刮楹达乡。", "b": "《礼记·明堂位》"}, {"t": "丹桓宫楹。", "b": "《春秋·庄公二十三年》"}], "words": [{"w": "楹柱", "t": "厅堂前部的柱子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5408wx','椽','1','chuán','木','13','','[{"pinyin": "chuán", "defs": [{"meaning": "(形声。从木,彖(tuàn)声。本义:承屋瓦的圆木) 同本义。", "cites": [{"t": "椽,榱也。", "b": "《说文》"}, {"t": "以大宫之椽归,为卢门之椽。", "b": "《左传·桓公十四年》"}, {"t": "采椽不斫。", "b": "《韩非子·五蠹》"}, {"t": "架梁之椽,多于机上之工女。", "b": "杜牧《阿房宫赋》"}, {"t": "不数岁,田百顷,楼阁万椽,牛羊蹄躈各千计。", "b": "《聊斋志异·促织》"}], "words": [{"w": "椽杙", "t": "椽子和小木桩"}, {"w": "椽桷", "t": "承屋瓦用的圆木与方木。圆的叫椽,方的叫桷。泛指椽子"}, {"w": "椽笔", "t": "大笔"}, {"w": "椽栋", "t": "椽子与正梁。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5409wx','裘','1','qiú','衣','13','','[{"pinyin": "qiú", "defs": [{"meaning": "(形声。从衣,求声。本义:皮衣。古代“求”、“裘”同字)。"}, {"meaning": "同本义。", "cites": [{"t": "裘,皮衣也。", "b": "《说文》"}, {"t": "裘所以佐女功助温也。", "b": "《白虎通·衣裳》"}, {"t": "掌为大裘", "b": "《周礼·司裘》。注:“大裘,黑羔裘。”"}, {"t": "世以为裘者。", "b": "《淮南子·泛论》。注:“裘孤之属也。”"}, {"t": "良治之子,必学为裘。", "b": "《礼记·学记》"}, {"t": "冬日麑裘。", "b": "《韩非子·五蠹》"}, {"t": "狐裘不暖。", "b": "唐·岑参《白雪歌送武判官归京》"}, {"t": "裘葛之遗。", "b": "明·宋濂《送东阳马生序》"}, {"t": "裘马过世家。", "b": "《聊斋志异·促织》"}], "words": [{"w": "裘马甚都", "t": "车马衣裘十分华美"}, {"w": "裘膻", "t": "裘皮和膻气。代指清兵"}, {"w": "狐裘;裘氏", "t": "周礼官名。制皮衣的工匠"}, {"w": "裘冕", "t": "上古帝王祭天时所穿戴的衣冠。"}]}, {"meaning": "古代制皮工匠的一种。"}, {"meaning": "假借为“求”。求取。", "cites": [{"t": "熊罴是裘。", "b": "《诗·小雅·大东》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5410wx','剽','1','piāo','刂','13','','[{"pinyin": "piāo", "defs": [{"meaning": "(形声。从力,票声。本义:抢劫)。"}, {"meaning": "同本义。", "cites": [{"t": "勡,劫人也。", "b": "《说文》。按,古书多以剽为之。"}, {"t": "白昼大都之中,勡吏而夺之金。", "b": "《汉书·贾谊传》"}, {"t": "俱攻剽为群盗。", "b": "《史记·酷吏传》。索隐:劫也。"}], "words": [{"w": "剽掠", "t": "抢劫;掠夺"}, {"w": "剽攻", "t": "抢劫;掠夺"}, {"w": "剽拂", "t": "劫掠"}, {"w": "剽夺", "t": "掳掠"}, {"w": "剽虏", "t": "掳掠"}, {"w": "剽伤", "t": "掠夺残害。"}]}, {"meaning": "窃取,抄袭。", "cites": [{"t": "惟古于词必己出,降而不能乃剽贼。", "b": "韩愈《南阳樊绍述墓志铭》"}], "words": [{"w": "剽拾", "t": "犹抄袭"}, {"w": "剽剥", "t": "抄袭窃取"}, {"w": "剽掇", "t": "抄袭,摘录"}, {"w": "剽夺", "t": "抄袭"}, {"w": "剽裂", "t": "摘抄;窃取"}, {"w": "剽贼", "t": "抄袭"}, {"w": "剽缀", "t": "抄袭拼凑"}, {"w": "剽拟", "t": "抄袭摹拟"}, {"w": "剽摸", "t": "抄袭模仿。"}]}, {"meaning": "浮,浮流。", "cites": [{"t": "五剽之状。", "b": "《管子·地员》"}]}, {"meaning": "轻捷。", "cites": [{"t": "钟其中者谓之剽。", "b": "《尔雅》。孙注:“声轻痴。”"}, {"t": "且其人剽悍。", "b": "《汉书·陈汤传》"}], "words": [{"w": "剽迫", "t": "轻疾。"}]}, {"meaning": "轻浮,轻薄。", "cites": [{"t": "其俗剽轻,易发怒,地薄,寡于积聚。", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5411wx','甄','1','zhēn','瓦','13','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从瓦。从“瓦”与陶器有关。本义:制做陶器的转轮)。"}, {"meaning": "同本义。", "cites": [{"t": "如泥之在钧,唯甄者之所为。", "b": "《汉书·董仲舒传》"}, {"t": "若金受范,若埴(陶土)在甄。", "b": "晋·潘尼《释奠颂》"}, {"t": "甄陶品类。", "b": "《后汉书》"}]}, {"meaning": "军了的左右两翼。", "cites": [{"t": "使将军李恒督左甄,许朝督右甄。", "b": "房玄龄《晋书·周访传》"}]}, {"meaning": "制作陶器。", "cites": [{"t": "既陶既甄。", "b": "《文选·张华·女史箴》。"}, {"t": "甄工(甄者。制陶工人)", "b": ""}, {"t": "甄土(揉捏泥土)", "b": ""}, {"t": "甄冶(烧制陶器和熔炼金属。比喻造就人才)", "b": ""}]}, {"meaning": "甄别,鉴别。", "cites": [{"t": "甄无名之士于草莱,指未剖之璞于丘园。", "b": "《抱朴子》。"}, {"t": "甄升(甄别提升、晋升)", "b": ""}, {"t": "甄免(甄别。免除)", "b": ""}, {"t": "甄采(鉴别采用,选择采用)", "b": ""}]}, {"meaning": "审定,审察 。如。", "cites": [{"t": "甄正(犹审定)", "b": ""}, {"t": "甄收(审核录用)", "b": ""}, {"t": "甄访(查访)", "b": ""}, {"t": "甄引(审察引用)", "b": ""}, {"t": "甄事(审察事理)", "b": ""}]}, {"meaning": "选拔。", "cites": [{"t": "山涛作冀州,甄拔三十余人。", "b": "李白《与韩荆州书》。"}]}, {"meaning": "昭显;表彰。", "cites": [{"t": "甄勒勋绩,永昭于后。", "b": "《成皋令任君碑》。"}]}, {"meaning": "造就,培养。", "cites": [{"t": "臣里闾孤贱,才无可甄。", "b": "任昉《为范始兴作求立太宰碑表》。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5412wx','酮','1','tóng','酉','13','','[{"pinyin": "tóng", "defs": [{"meaning": "一类有机化合物(如丙酮) ,其特征是含有与两个碳原子相连接的羰基,这两个碳原子通常包含在两个烃基中(如在通式RCOR中)或者包含在一个二价基中,酮与醛相似,但不如醛活泼。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5413wx','酰','1','xiān','酉','13','','[{"pinyin": "xiān", "defs": [{"meaning": "有机化合物的一类,是脂肪酸的结构式中除羟基时所余下的原子团,通式是R·CO-,也叫“酰基”,旧称“醯”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5414wx','酯','1','zhǐ','酉','13','','[{"pinyin": "zhǐ", "defs": [{"meaning": "水解时产生一种有机酸(或无机酸)和一种醇(或酚)的化合物 ,即使十分挥发通常也是芳香液体,存在于香精油中的和合成的(尤指供人造果精用的)羧酸酯是以COOR基为特征的。"}]}]','jingmo-wenyan');
