INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5416wx','蜃','1','shèn','虫','13','','[{"pinyin": "shèn", "defs": [{"meaning": "(形声。从虫,辰声。本义:大蛤)。"}, {"meaning": "同本义。", "cites": [{"t": "蜃,雉入海化为蜃。", "b": "《说文》"}, {"t": "蜃,大蛤也。", "b": "《周礼·掌蜃》注"}, {"t": "小曰蛤,大曰蜃。皆介物,蚌类也。", "b": "《国语·晋语》注"}, {"t": "旦瓯文蜃。", "b": "《周书·王会》"}, {"t": "激女之山多蜃珧。", "b": "《东山经》"}, {"t": "春献鳖蜃。", "b": "《周礼·天官·鳖人》"}], "words": [{"w": "蜃蛤", "t": "大蛤和蛤蜊"}, {"w": "蜃窗", "t": "大蛤壳磨薄后镶嵌以透明的窗子"}, {"w": "蜃珧", "t": "蚌蛤之属"}, {"w": "蜃贝", "t": "贝壳的一种,可作饰物"}, {"w": "蜃醢", "t": "以蚌蛤类肉制成的酱。"}]}, {"meaning": "古祭器。画有蜃形的漆尊。", "cites": [{"t": "凡山川四方,用蜃。", "b": "《周礼·春官·鬯人》"}], "words": [{"w": "蜃器", "t": "以蜃贝为饰的祭器。"}]}, {"meaning": "指蜃灰。用蜃壳烧成的灰。", "cites": [{"t": "白蜃。", "b": "《考工记·匠人》。注:“灰也。”"}], "words": [{"w": "蜃壁", "t": "以蜃灰涂抹的墙壁,取其洁白而去湿"}, {"w": "蜃灶", "t": "煮盐的灶"}, {"w": "蜃墙", "t": "有蜃灰粉制过的墙壁。"}]}, {"meaning": "传说中的蛟属。能吐气成海市蜃楼。亦指海市蜃楼。", "cites": [{"t": "鹭涛清彻,蜃阁化城重。", "b": "杨巨源《供奉定法师归安南》"}], "words": [{"w": "蜃楼", "t": "古人称蜃气变幻成的楼阁"}, {"w": "蜃气", "t": "海面风平浪静时出现在远方的幻像,实由光折射而成。古人误以为是蜃所吐之气"}, {"w": "蜃阁", "t": "虚幼的空中楼阁景象"}, {"w": "蜃市", "t": "海市"}, {"w": "蜃女", "t": "神话中的龙女。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5417wx','碛','1','qì','石','16','','[{"pinyin": "qì", "defs": [{"meaning": "浅水中的沙石;沙石浅滩。", "cites": [{"t": "碛,水渚有石者。", "b": "《说文》"}, {"t": "碛,水中沙也。", "b": "《三苍》"}, {"t": "吴越谓之濑,中国谓之碛。", "b": "《汉书·元帝纪》注"}, {"t": "玩其碛砾而不窥玉渊者。", "b": "左思《吴都赋》"}], "words": [{"w": "碛沙", "t": "水中沙堆"}, {"w": "碛砾", "t": "浅水中的沙石;沙石浅滩"}, {"w": "碛路", "t": "多沙石的道路"}, {"w": "碛块", "t": "沙石。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5418wx','碓','1','duì','石','13','','[{"pinyin": "duì", "defs": [{"meaning": "用于去掉稻壳的脚踏驱动的倾斜的锤子,落下时砸在石臼中,去掉稻谷的皮。", "cites": [{"t": "因延力借身重以践碓,而利十倍。", "b": "《新论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5419wx','硼','1','péng','石','13','','[{"pinyin": "péng", "defs": [{"meaning": "三价高熔点非金属元素。在自然界中,硼只以其化合物形式存在着(像在硼砂、硼酸中,在植物和动物中只存在有痕量的硼),通常由电解熔融的氟硼酸钾和氯化钾或热还原它的其他化合物(如氧化硼)制得,它主要用于冶金(如为了增加钢的硬度)及核子学中,因为它吸收中子能力强 ——元素符号B。"}]}]','jingmo-wenyan');
