INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5422wx','碇','1','dìng','石','13','','[{"pinyin": "dìng", "defs": [{"meaning": "停船时沉入水底用以稳定船身的石块或系船的石礅。", "cites": [{"t": "至操寨边,瑜命下碇石。", "b": "《三国演义》"}], "words": [{"w": "碇石", "t": "稳定船身的石块或系船的石礅"}, {"w": "碇铁", "t": "系船于碇石的铁索"}, {"w": "下碇", "t": ""}]}, {"meaning": "任何一种像锚那样用来把船固定在一个地方的东西(如石头或水泥块)。"}, {"meaning": "船停泊,下碇。", "cites": [{"t": "是日六月晦,无月,碇宿大海中。", "b": "苏轼《东坡志林》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5423wx','碜','1','chěn','石','13','','[{"pinyin": "chěn", "defs": [{"meaning": "食物里夹着沙子的", "words": [{"w": "牙碜", "t": "食物夹着沙子,嚼起来牙齿不舒服"}, {"w": "眼碜", "t": ""}]}, {"meaning": "丑;难堪", "words": [{"w": "寒碜", "t": "丑陋；难看"}, {"w": "碜事", "t": "丑事"}]}, {"meaning": "用同“惨”", "words": [{"w": "碜可可", "t": "凄惨可怕的样子"}]}, {"meaning": "很。表示深度加深", "words": [{"w": "碜大", "t": "特别大；这么大"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5424wx','鹌','1','ān','鸟','13','','[{"pinyin": "ān", "defs": [{"meaning": "一种迁徙性雉类鸟，长约18厘米，棕黑色而有黄色斑点，尾短，不善飞， 体形像小鸡，头小尾短，羽毛赤褐色，杂有暗黄色条纹。吃谷类和杂草种子。雄的好斗。现已人工饲养，肉、卵供食用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5425wx','辏','1','còu','车','13','','[{"pinyin": "còu", "defs": [{"meaning": "(形声。从车,奏声。本义:车轮上的辐条集中于觳上)。"}, {"meaning": "同本义。", "cites": [{"t": "辐辏而轮转,出入更卷舒。", "b": "《参同契》"}]}, {"meaning": "聚集。", "cites": [{"t": "四方辐辏。", "b": "《汉书·叔孙通传》。师古曰:“辏,聚也,言如车辐之聚于毂也。”"}], "words": [{"w": "辏集", "t": "聚集;稠密"}, {"w": "辏合", "t": "凑合;聚集"}, {"w": "辏泊", "t": "聚集。"}]}]}]','jingmo-wenyan');
