INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5428wx','訾','1','zī zǐ','言','13','','[{"pinyin": "zī", "defs": [{"meaning": "衡量;计量。", "cites": [{"t": "息耗减损通于不訾。", "b": "《淮南子·原道》"}, {"t": "訾功丈而知人数。", "b": "《吕氏春秋·知度》。注:“相也。”"}, {"t": "訾相其质,足以比成事,诚可立而授之。", "b": "《国语·齐语》"}], "words": [{"w": "訾粟", "t": "度量粟米"}, {"w": "訾计", "t": "估量计算"}, {"w": "訾相", "t": "衡量省视"}, {"w": "訾省", "t": "计算、察核财物。"}]}, {"meaning": "考虑;希求。", "cites": [{"t": "心悁忿而不訾前后者,可亡也。", "b": "《韩非子》"}, {"t": "不訾重器,毋訾衣服成器。", "b": "《礼记·少仪》"}], "words": [{"w": "訾问", "t": "考虑、过问。"}]}, {"meaning": "放纵。", "cites": [{"t": "离纵而跂訾者也。", "b": "《荀子·非十二子》"}, {"t": "小谨者无成功,訾行者不容于众。", "b": "《淮南子》"}]}, {"meaning": "钱财。", "cites": [{"t": "家訾累数巨万矣。", "b": "《史记》"}, {"t": "以訾为骑郎。", "b": "《史记·张释之传》"}, {"t": "以訾助边。", "b": "《盐铁论·击之》"}], "words": [{"w": "訾用", "t": "资产财用"}, {"w": "訾算", "t": "钱财数目。指买官的钱;用钱来计算"}, {"w": "訾产", "t": "资产,财产。"}]}, {"meaning": "古地名 。在今河南省巩县西南。", "cites": [{"t": "夏,四月,乙酉,单子取訾。", "b": "《左传》"}]}, {"meaning": "疾病。", "cites": [{"t": "岁凶,庸人訾厉,多死丧。", "b": "《管子·入国》"}], "words": [{"w": "訾厉", "t": "疾病,灾害。"}]}, {"meaning": "缺点。", "cites": [{"t": "故子之所刺于礼者,亦非礼之訾也。", "b": "《礼记·檀弓下》"}], "words": [{"w": "訾缺", "t": "过错与缺失。"}]}]}, {"pinyin": "zǐ", "defs": [{"meaning": "(形声。从言,此声。本义:毁谤,非议)。"}, {"meaning": "同本义。", "cites": [{"t": "訾,訾訾不思称意也。从言,此声。", "b": "《说文》"}, {"t": "四制訾之者,是不知礼之所由生也。", "b": "《礼记·丧服》。注:“口毁曰訾。”"}, {"t": "不訾小忿。", "b": "《左传·昭公二十一年》"}, {"t": "公子沓訾之。", "b": "《吕氏春秋·审应》。注:“毁也。”"}, {"t": "訾行者不容于众。", "b": "《淮南子·泛论》"}, {"t": "诋訾今古。", "b": "《战国策·魏策》"}, {"t": "故小谨者无成功,訾行者不容于众。", "b": "《淮南子·汜论训》"}], "words": [{"w": "訾美", "t": "毁誉"}, {"w": "訾怨", "t": "诽谤怨恨"}, {"w": "訾病", "t": "提出他人缺失而加以讥评,非议"}, {"w": "訾短", "t": "非议,诋毁。"}]}, {"meaning": "厌恶;极其讨厌并憎恶。", "cites": [{"t": "訾食者不肥体。", "b": "《管子》"}], "words": [{"w": "訾食", "t": "厌食"}, {"w": "訾怨", "t": "厌恨。"}]}, {"meaning": "指责。", "cites": [{"t": "夫名盛则责望备,实不副则訾咎深。", "b": "《新唐书》"}], "words": [{"w": "訾戈", "t": "痛骂弋猎的人"}, {"w": "訾咎", "t": "指责非难"}, {"w": "訾屈", "t": "责骂。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5429wx','粲','1','càn','米','13','','[{"pinyin": "càn", "defs": [{"meaning": "(形声。从米,(cán)声。本义:上等白米)。"}, {"meaning": "同本义;又指美食。", "cites": [{"t": "还予授子之粲兮。", "b": "《诗·郑风·缁衣》"}]}, {"meaning": "露齿笑。", "cites": [{"t": "军人粲然皆笑。", "b": "《谷梁传·昭公四年》"}], "words": [{"w": "以博一粲", "t": ""}]}, {"meaning": "鲜明的样子。", "cites": [{"t": "粲,文也。", "b": "《广雅》"}, {"t": "粲,鲜也。", "b": "《释言》"}, {"t": "如此粲者何。", "b": "《诗·唐风·绸缪》"}, {"t": "粲粲衣服。", "b": "《诗·小雅·大东》。传:“鲜盛貌。”"}, {"t": "角枕粲文茵,锦衾烂长筵。", "b": "《世说新语·排调》"}], "words": [{"w": "粲花", "t": "形容言谈生动优美,如百花灿烂"}, {"w": "粲粲", "t": "鲜明的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5430wx','虞','1','yú','虍','13','','[{"pinyin": "yú", "defs": [{"meaning": "(形声。从虍(hū),吴声。虍,虎头。本义:神话传说中的兽名。即“驺虞”)。"}, {"meaning": "同本义。", "cites": [{"t": "虞,驺虞,白虎黑文,尾长于身,仁兽,食自死之肉。", "b": "《说文》"}, {"t": "虞者,囿之司兽者也。", "b": "《贾子礼》"}, {"t": "即鹿无虞。", "b": "《易·屯》"}, {"t": "于嗟乎驺虞。", "b": "《诗·召南》"}]}, {"meaning": "古代掌管山泽鸟兽的官吏。", "cites": [{"t": "询于八虞。", "b": "《国语·晋语》"}]}, {"meaning": "借指有关这方面的知识。", "cites": [{"t": "虞而出之。", "b": "《史记·货殖列传》"}]}, {"meaning": "又。", "cites": [{"t": "虞不出则财匮。", "b": ""}, {"t": "到了二十多岁,学问成了,一切兵、农、礼、乐、工、虞、水、火之事,他提了头就知道尾。", "b": "《儒林外史》"}, {"t": "虞人导前,鹰犬罗后。", "b": "马中锡《中山狼传》"}], "words": [{"w": "虞旗", "t": "又叫“虞旌”。虞人在汇集所获物时所用的旗帜"}, {"w": "虞罗", "t": "原指掌山泽之虞人所张设的网罗"}, {"w": "虞人", "t": "古官名。掌管山泽苑囿的官"}, {"w": "虞师", "t": "古官名。掌管山泽之官"}, {"w": "虞官", "t": "古代掌管山泽苑囿的官吏。"}]}, {"meaning": "古代一种祭祀名。既葬而祭叫虞,有安神之意。", "cites": [{"t": "有司以几筵舍奠于墓左,反,日中而虞。", "b": "《左传》"}], "words": [{"w": "虞歌", "t": "即虞殡"}, {"w": "虞殡", "t": "送葬歌曲"}, {"w": "虞祭", "t": "祭名。葬后所行安神的祭名"}, {"w": "虞主", "t": "虞祭时所立的神主。"}]}, {"meaning": "朝代名。帝舜有天下之号。", "cites": [{"t": "始于虞夏。", "b": "清·黄宗羲《原君》"}]}, {"meaning": "又。", "cites": [{"t": "唐虞之世。", "b": ""}, {"t": "虞夏以来。", "b": "《史记·货殖列传》"}], "words": [{"w": "虞廷百兽率舞", "t": "传说尧任用舜时,凤凰飞来,百兽在宫廷前起舞。比喻太平盛世"}, {"w": "虞书", "t": "《尚书》的一个组成部分。相传记载着唐尧、虞舜、夏禹等的事迹"}, {"w": "虞唐", "t": "指上古人民康乐、政治清明的理想时代。"}]}, {"meaning": "古国名。"}, {"meaning": "舜之先封于虞,故城在今山西省平陆县东北。"}, {"meaning": "夏禹封舜子商均于虞,为今河南省虞城县。"}, {"meaning": "山名。"}, {"meaning": "猜度;料想。", "cites": [{"t": "用戒不虞。", "b": "《诗·大雅·抑》"}, {"t": "不虞齐赵无兵援,将死城崩国已亡。", "b": "《秦倂六国平话》"}, {"t": "君处北海,寡人处南海,唯是风马牛不相及也。不虞君之涉吾地也,何故?", "b": "《左传·僖公四年》"}], "words": [{"w": "虞度", "t": "谋虑。"}]}, {"meaning": "忧虑;忧患。", "cites": [{"t": "等狄爷兵来,随军而进,方保无虞。", "b": "《八洞天》"}, {"t": "戎狄弃甲而远遁,朝廷高枕而无虞。", "b": "唐·韩愈《与凤翔邢尚书书》"}]}, {"meaning": "准备,防范。", "cites": [{"t": "以虞待不虞者。", "b": "《孙子·谋攻》"}], "words": [{"w": "虞卒", "t": "古代帝王狩猎时,担任围合禽兽的士兵"}, {"w": "虞旅", "t": "守猎之军卒。"}]}, {"meaning": "企望;期待。", "cites": [{"t": "且日虞四邑之至也。", "b": "《左传》"}], "words": [{"w": "虞心", "t": "希冀之心;侥幸之心。"}]}, {"meaning": "贻误;欺诈。", "cites": [{"t": "我无尔诈,尔无我虞。", "b": "《左传》"}]}, {"meaning": "惊。", "cites": [{"t": "悔吝者忧虞之象也。", "b": "《易·系辞上》"}]}, {"meaning": "", "cites": [{"t": "虞,安也。", "b": "《广雅》"}, {"t": "虞吉。", "b": "《易·中孚》"}, {"t": "虞于湛乐。", "b": "《国语·周语》"}, {"t": "故许由虞乎颍阳。", "b": "《吕氏春秋·慎人》"}, {"t": "三虞。", "b": "《逸周书·丰谋》。注:“虞,乐也。”"}, {"t": "合好效欢虞泰一。", "b": "《汉书·礼乐志》"}, {"t": "虞说耳目。", "b": "《汉书·王褒传》"}], "words": [{"w": "虞心", "t": "怡悦心情"}, {"w": "虞说", "t": "娱悦"}, {"w": "虞乐", "t": "娱乐"}, {"w": "虞欢", "t": "娱欢。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
