INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5433wx','韪','1','wěi','韦','13','','[{"pinyin": "wěi", "defs": [{"meaning": "(形声。从是,韦声。本义:是;对)。"}, {"meaning": "同本义。", "cites": [{"t": "韪,是也。", "b": "《说文》"}, {"t": "犯五不韪。", "b": "《左传·隐公十一年》"}, {"t": "君子韪之。", "b": "《左传·昭公二十年》"}, {"t": "人韪其言。", "b": "《明史》"}], "words": [{"w": "冒天下大不韪", "t": "这里的“不韪”是“罪”,“反国家罪”的意思。"}]}, {"meaning": "善。", "cites": [{"t": "京室密清,罔有不韪。", "b": "《文选·东京赋》"}]}, {"meaning": "美好。", "cites": [{"t": "故开元、天宝间,播兄弟七人皆擢进士第,衣冠光韪。", "b": "《新唐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5434wx','嗷','1','áo','口','13','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从口,敖声。本义:哀鸣声)。"}, {"meaning": "同本义。", "cites": [{"t": "嗷,众口愁也。", "b": "《说文》"}, {"t": "鸿雁于飞,哀鸣嗷嗷。", "b": "《诗·小雅·鸿雁》"}], "words": [{"w": "嗷然", "t": "大喊大叫的样子。"}]}, {"meaning": "叫呼声;喧杂声。", "cites": [{"t": "声嗸儗以寂寥兮。", "b": "《楚辞·惜贤》。注:“呼声也。”"}, {"t": "谗口嗸嗸。", "b": "《汉书·刘向传》。注:“众声也。”"}], "words": [{"w": "嗷嘈", "t": "吵闹"}, {"w": "嗷骚", "t": "喧扰,不平静。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5435wx','嗉','1','sù','口','13','','[{"pinyin": "sù", "defs": [{"meaning": "许多鸟类的食管的扩大部分,形成一个小囊,用来贮存食物,并对其初步浸解。", "cites": [{"t": "岂无鵰,嗉中食饱不肯搏。", "b": "唐·白居易《秦吉了》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5436wx','睨','1','nì','目','13','','[{"pinyin": "nì", "defs": [{"meaning": "(形声。从目,兒(ní)声。本义:斜视)。"}, {"meaning": "同本义。", "cites": [{"t": "睨,视也。", "b": "《说文》"}, {"t": "余与褐之父睨之。", "b": "《左传·哀公十三年》"}, {"t": "睨而视之。", "b": "《礼记·中庸》"}, {"t": "虽羿逢蒙不能眄睨也。", "b": "《庄子·山水》"}, {"t": "相如持其璧睨柱。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "卖油翁释担而立,睨之,久而不去。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "睨注", "t": "斜着眼睛注视"}, {"w": "睨笑", "t": "斜视而笑"}, {"w": "睨视", "t": "斜视,旁视;傲视。"}]}, {"meaning": "视。", "cites": [{"t": "旨酒一盛兮,余与褐之父睨之。", "b": "《左传·哀公十三年》"}, {"t": "陟升皇之赫戏兮,忽临睨夫旧乡。", "b": "《楚辞·离骚》。玉逸注:“睨,视也。”"}]}, {"meaning": "顾视,回视。"}, {"meaning": "寻视。", "cites": [{"t": "虑也者,以其知有求也,而不必得之,若睨。", "b": "《墨子》"}]}, {"meaning": "偏斜。", "cites": [{"t": "日方中方睨,物方生方死。", "b": "《庄子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5437wx','睢','1','huī suī','目','13','','[{"pinyin": "huī", "defs": [{"meaning": "仰视的样子。", "cites": [{"t": "睢,仰目也,从目,隹声。", "b": "《说文》"}, {"t": "暴戾恣睢。", "b": "《史记·伯夷传》"}, {"t": "万众睢睢。", "b": "《汉书·五行志》"}], "words": [{"w": "睢盱", "t": "睁眼仰视的样子"}, {"w": "睢睢", "t": "仰视的样子。"}]}]}, {"pinyin": "suī", "defs": [{"meaning": "(形声。从目,隹(zhuī)声。本义:仰视) 同本义。", "cites": [{"t": "睢,仰目也。", "b": "《说文》"}, {"t": "暴戾恣睢。", "b": "《史记·伯夷传》。正义:“仰白目怒貌也。”"}, {"t": "万众睢睢。", "b": "《汉书·五行志》。注:“仰目视貌也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5438wx','雎','1','jū','隹','13','','[{"pinyin": "jū", "defs": [{"meaning": "(形声。从隹(zhuī),短尾鸟,且声。本义:雎鸠,即鱼鹰)。"}, {"meaning": "同本义 。鹗科的一种鸟,上体深褐色,下体大部纯白,常活动于水边,捕食水中的鱼。", "cites": [{"t": "关关雎鸠,在河之洲。", "b": "《诗·周南》"}]}, {"meaning": "水名 。在湖北省中部偏西。与漳水汇合为沮漳河,于江陵西入长江。"}]}]','jingmo-wenyan');
