INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5444wx','嗔','1','chēn tián','口','13','','[{"pinyin": "chēn", "defs": [{"meaning": "(形声。从口,真声。本义:发怒;生气)。"}, {"meaning": "同本义。也作“謓”。", "cites": [{"t": "謓,恚也。", "b": "《说文》"}]}]}, {"pinyin": "tián", "defs": [{"meaning": "(形声。从口,真声。本义:盛大。同“阗”) 同“阗”。盛大。", "cites": [{"t": "嗔,盛气也。从口,真声。", "b": "《说文》"}, {"t": "盛气颠(嗔)实。", "b": "《礼记·玉藻》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5445wx','嗝','1','gé','口','13','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从口,鬲(gé)声。本义:禽鸟鸣声)。"}, {"meaning": "同本义。", "cites": [{"t": "嗝,雉鸣也。", "b": "《玉篇》"}, {"t": "嗝,鸡鸣。", "b": "《字汇》"}], "words": [{"w": "嗝报", "t": "鸡鸣报晓。"}]}, {"meaning": "气逆作声 。亦叫“打嗝儿”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5446wx','戥','1','děng','戈','13','','[{"pinyin": "děng", "defs": [{"meaning": "戥子 。叫“戥秤”。一种小秤,用来称贵重物品,如金银药品,最大单位是两", "words": [{"w": "戥头", "t": "戥子的分量"}]}, {"meaning": "用戥子称东西", "words": [{"w": "戥耗", "t": "用戥子称量的差额"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5447wx','嗄','1','shà á','口','13','','[{"pinyin": "shà", "defs": [{"meaning": "声音嘶哑的。", "cites": [{"t": "终日嚎而嗌不嗄。", "b": "《老子》"}], "words": [{"w": "嗄哑,嗄嘶", "t": "嗓音嘶哑。"}]}, {"meaning": "什么 ——表示否定。", "cites": [{"t": "我要丢个干干净,看你嗄法把我治。", "b": "清·蒲松龄《聊斋俚曲集》"}]}, {"meaning": "旧时仆役对主人、下级对上级的应诺声。", "cites": [{"t": "“带进来”。两边军士应一声“嗄”,即将牛皋推至面前。", "b": "《说岳全传》"}]}]}, {"pinyin": "á", "defs": [{"meaning": "(á)。表示省悟或惊奇。", "cites": [{"t": "嗄!难道这里是没有地方官的么?", "b": "宋·佚名《新编五代史平话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5448wx','煦','1','xù','灬','13','','[{"pinyin": "xù", "defs": [{"meaning": "(形声。从火,昫(xū)声。本义:温暖;暖和)。"}, {"meaning": "同本义。", "cites": [{"t": "煦,蒸也。一曰赤貌。一曰温润也。", "b": "《说文》"}, {"t": "煦,温也。", "b": "《广韵》"}, {"t": "煦而为阳春,散而为霖雨。", "b": "宋·王禹偁《送柴侍御赴阙序》"}, {"t": "晨烟暮霭,春煦秋阳。", "b": "颜延之《陶征士诔》"}], "words": [{"w": "煦风", "t": "暖风;和风"}, {"w": "煦润", "t": "温暖滋润。"}]}, {"meaning": "和乐的样子。", "cites": [{"t": "伤夷受煦。", "b": "柳宗元《为裴中丞贺克东平赦表》"}], "words": [{"w": "煦愉", "t": "温煦,和悦"}, {"w": "煦濡", "t": "温和;惠爱。"}]}, {"meaning": "日出时的霞光。", "cites": [{"t": "景光之人煦若射。", "b": "《墨子·经说下》"}]}, {"meaning": "恩惠。", "cites": [{"t": "堂侄余庆,承煦绍宗。", "b": "唐玄宗《诫励宗室诏》"}]}, {"meaning": "受雇为人劳动。", "cites": [{"t": "故姜牙卖煦无所售,而见师于文武。", "b": "晋·葛洪《抱朴子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5449wx','暄','1','xuān','日','13','','[{"pinyin": "xuān", "defs": [{"meaning": "(形声。从日,宣声。本义:温暖)。"}, {"meaning": "同本义。", "cites": [{"t": "其性为暄。", "b": "《素问·五运行大论》"}, {"t": "叙温郁则寒谷成暄,论严苦则春丛零叶。", "b": "刘峻《广绝交论》"}], "words": [{"w": "喧和", "t": "温暖和畅"}, {"w": "暄风", "t": "和风,春风"}, {"w": "暄妍", "t": "天气暖和,景色明媚。"}]}]}]','jingmo-wenyan');
