('5451wx','暌','1','kuí','日','13','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从日,癸声。本义:日落)。"}, {"meaning": "同本义。", "cites": [{"t": "暌,日入也。", "b": "《古今韵会举要》"}]}, {"meaning": "分离,隔开。", "cites": [{"t": "伊余本羁客,重暌复心赏。", "b": "何逊《入西塞示南府同僚》"}], "words": [{"w": "暌违", "t": "分离;不在一起"}, {"w": "暌阻", "t": "阔别;离别"}, {"w": "暌间", "t": "离间;使分离。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5452wx','跬','1','kuǐ','足','13','','[{"pinyin": "kuǐ", "defs": [{"meaning": "(形声。从足, 圭声。本义: 古代的半步) 古时称人行走, 举足一次为跬, 举足两次为步, 故半步叫“跬”。", "cites": [{"t": "故不积跬步,无以至千里。", "b": "《荀子·劝学》"}], "words": [{"w": "跬行", "t": "举足而行"}, {"w": "跬步", "t": "半步;跨一脚;举步;迈步。"}]}]}]','jingmo-wenyan');
