INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5454wx','跸','1','bì','足','13','','[{"pinyin": "bì", "defs": [{"meaning": "(从足,毕声。本义:帝王出行时开路清道,禁止他人通行)。"}, {"meaning": "同本义。", "cites": [{"t": "出称警入言。", "b": "《汉书·梁孝王武传》"}, {"t": "大祭祀、丧祀之事,设门燎,跸宫门庙门。", "b": "《周礼》"}], "words": [{"w": "跸路", "t": "跸道。帝王出行时所经过的道路。清理道路,禁止百姓通行"}, {"w": "跸声", "t": "清道的吆喝声。"}]}, {"meaning": "指帝王出行的车驾。", "cites": [{"t": "县人来,闻跸,匿桥下。", "b": "《史记》"}], "words": [{"w": "驻跸", "t": "指帝王出行沿途暂住。"}]}]}]','jingmo-wenyan');
