('5458wx','跻','1','jī','足','13','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从足,齐声。本义:升,登)。"}, {"meaning": "同本义。", "cites": [{"t": "跻,登也。", "b": "《说文》"}, {"t": "跻于九陵,勿逐。", "b": "《易·震》"}, {"t": "跻彼公堂,称彼兕觥。", "b": "《诗·豳风·七月》"}, {"t": "跻踬连绝。", "b": "王褒《洞箫赋》"}], "words": [{"w": "跻踬", "t": "或上或下"}, {"w": "跻览", "t": "登高眺望"}, {"w": "跻险", "t": "登上高险处"}, {"w": "跻登", "t": "攀登;登上"}, {"w": "跻峰造极", "t": "登上山峰绝顶。"}]}, {"meaning": "晋升。", "cites": [{"t": "大事于大庙,跻僖公,逆祀也。", "b": "《左传·文公二年》"}], "words": [{"w": "跻陟", "t": "晋升,升迁"}, {"w": "跻升", "t": "升迁。"}]}, {"meaning": "下坠。", "cites": [{"t": "今尔无指告予颠跻。", "b": "《书·微子》"}]}]}]','jingmo-wenyan');
