INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5464wx','畹','1','wǎn','田','13','','[{"pinyin": "wǎn", "defs": [{"meaning": "古代地积单位。说法不一,一说30亩为一畹,一说12亩为一畹。", "cites": [{"t": "余既滋兰之九畹兮。", "b": "《离骚》。王逸注:“十二亩曰畹。”"}]}, {"meaning": "泛指花圃或园地。", "cites": [{"t": "右则疏圃曲池,下畹高堂。", "b": "晋·左思《魏都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5465wx','蛹','1','yǒng','虫','13','','[{"pinyin": "yǒng", "defs": [{"meaning": "动物学名词。指完全变态的昆虫。", "cites": [{"t": "蛹,茧虫也。从虫,甬声。", "b": "《说文》。按,凡虫成茧后,体在中曰蛹,蚕其一也。"}]}, {"meaning": "亦指蚕蛹。", "cites": [{"t": "蛹以为母,蛾以为父。", "b": "《荀子·蚕赋》"}], "words": [{"w": "蛹卧", "t": "蚕蛹蜷伏茧中。比喻隐居不出"}, {"w": "蛹壳", "t": "蛹羽化后剩下的外壳"}, {"w": "蛹期", "t": "完全变态类的昆虫,在幼虫变化成蛹、蛹变为成虫以前的一段时期。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5466wx','嗣','1','sì','口','13','','[{"pinyin": "sì", "defs": [{"meaning": "(形声。从册,从口,司声。册,帝王对臣下封土授爵的文书。口,下令。甲骨文从大,从子,从册,会意。大子,即嫡长子。本义:诸侯传位给嫡长子)。"}, {"meaning": "同本义。", "cites": [{"t": "嗣,诸侯嗣国也。", "b": "《说文》"}, {"t": "舜让于德,弗嗣。", "b": "《书·舜典》"}, {"t": "将使嗣位。", "b": "《书·舜典序》"}], "words": [{"w": "嗣王", "t": "继位之王"}, {"w": "嗣君", "t": "继位的君主"}, {"w": "嗣主", "t": "继位的国君"}, {"w": "嗣位", "t": "继承君位"}, {"w": "嗣皇", "t": "继位的帝王"}, {"w": "嗣圣", "t": "新继位的皇帝"}, {"w": "嗣临", "t": "继登皇位。"}]}, {"meaning": "继承;接续。", "cites": [{"t": "嗣,继也。", "b": "《尔雅》"}, {"t": "禹乃嗣兴。", "b": "《书·洪范》。传:“继也。”"}, {"t": "其弟嗣书。", "b": "《左传·襄公二十五年》"}, {"t": "太史书曰:“崔杼弑其君。”崔子杀之。其弟嗣书,而死者二人。", "b": "《左传·襄公二十五年》"}, {"t": "今吾嗣为之十二年,几死者数矣。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "嗣位", "t": "继承君位"}, {"w": "嗣产", "t": "继承子产的事业"}, {"w": "嗣徽", "t": "继承善美的德行"}, {"w": "嗣守", "t": "继承并遵守和保存"}, {"w": "嗣芳", "t": "承继前贤者"}, {"w": "嗣承", "t": "继承"}, {"w": "嗣封", "t": "承袭先人而受封"}, {"w": "嗣统", "t": "继承皇位"}, {"w": "嗣武二祖", "t": "继承汉高祖、汉光武二祖的事业"}, {"w": "嗣音", "t": "继续传其音信"}, {"w": "嗣事", "t": "继续从事"}, {"w": "嗣奉", "t": "继前人而敬受。"}]}, {"meaning": "主持,掌管。", "cites": [{"t": "阳人有夏商之嗣典,有周室之师旅。", "b": "《国语·晋语四》"}, {"t": "若天之嗣,其事不可识,百姓浅然不识其邻。", "b": "《荀子·哀公》"}, {"t": "远近高下,各得其嗣。", "b": "《管子·版法》"}]}, {"meaning": "君位或职位的继承人。", "cites": [{"t": "今又不礼于卫之嗣。", "b": "《左传·昭公七年》。注:“新君也。”"}, {"t": "祁奚请老,晋侯问嗣焉。", "b": "《左传·襄公三年》"}, {"t": "及长当就国也。(王)立嗣子融从长请车骑。", "b": "《汉书·淳于长传》"}], "words": [{"w": "嗣子", "t": "帝王或诸侯的嫡子"}, {"w": "嗣孙", "t": "承嗣的子孙"}, {"w": "嗣体", "t": "承嗣之人"}, {"w": "嗣适", "t": "承嗣的嫡子。"}]}, {"meaning": "后代。", "cites": [{"t": "夫晋侯非嗣也,而得其位。", "b": "《国语·周语上》"}, {"t": "此君婆娑,政坐宦薄,著书未成,嗣息中绝。", "b": "明·王世贞《与俞仲蔚书》"}, {"t": "尝有壹男子,然无一日之命,至今无以讬嗣续,恨痛常在心目。", "b": "唐·柳宗元《与杨京光凭书》"}], "words": [{"w": "后嗣;嗣人", "t": "子孙"}, {"w": "嗣胤", "t": "子孙后代"}, {"w": "嗣息", "t": "子孙"}, {"w": "嗣继", "t": "子孙"}, {"w": "嗣续", "t": "子孙世代继承。"}]}, {"meaning": "次,第二的。", "cites": [{"t": "载燔载烈,以兴嗣岁。", "b": "《诗·大雅·生民》"}], "words": [{"w": "嗣岁", "t": "来年。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
