('5471wx','嗌','1','ài yì','口','13','','[{"pinyin": "ài", "defs": [{"meaning": "咽喉塞住。", "cites": [{"t": "嗌,噎也…秦晋或曰嗌。", "b": "《方言》"}, {"t": "嗌不容粒。", "b": "《谷梁传·昭公十九年》。"}], "words": [{"w": "嗌喉", "t": "上吊身亡。"}]}]}, {"pinyin": "yì", "defs": [{"meaning": "咽喉。", "cites": [{"t": "咽,又谓之嗌,气所流通,厄要之处也。", "b": "《释名》"}, {"t": "食之已嗌痛。", "b": "《山海经·北山经》"}, {"t": "使我嗌疾而腰急。", "b": "《列子·汤问》"}, {"t": "嗌于面尘,身无膏泽。", "b": "《素问》"}]}, {"meaning": "喻指交通要道。", "cites": [{"t": "嗌者,扼也,扼要之处也。", "b": "《说文解字注》"}]}]}]','jingmo-wenyan');
