('5488wx','锢','1','gù','钅','13','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从金,固声。本义:用熔化的金属堵塞空隙)。"}, {"meaning": "同本义。", "cites": [{"t": "锢,铸塞也。", "b": "《说文》。徐锴曰:“铸铜铁以塞隙也。”"}, {"t": "釭锏键钻冶锢鐈。", "b": "《急就篇》"}, {"t": "冶铜锢其内。", "b": "《汉书·贾山传》"}], "words": [{"w": "锢露", "t": "亦作锢路。用熔化的金属堵塞金属物品的漏洞"}, {"w": "锢南山", "t": "用铜铁熔液堵塞的南山。比喻胸中郁结不消的块垒。"}]}, {"meaning": "禁闭;禁锢。", "cites": [{"t": "(巫臣)遂奔晋,……子反请以重币锢之。", "b": "《左传·成公二年》"}, {"t": "可是在中国,那时是确无写处的,禁锢得比罐头还严密。", "b": "《为了忘却的记念》"}, {"t": "锢诏狱,昼夜搒讯。", "b": "《明史·海瑞传》"}], "words": [{"w": "锢党", "t": "遭禁锢的朋党成员"}, {"w": "锢钥", "t": "禁锢锁闭。"}]}, {"meaning": "疾病经久不治的", "cites": [{"t": "失今不治,必为锢疾。", "b": "《汉书·贾谊传》。师古曰:“锢疾,坚久之疾。”"}], "words": [{"w": "锢病", "t": "经久难治的疾病。"}]}]}]','jingmo-wenyan');
