INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5493wx','雉','1','zhì','隹','13','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从隹,矢声。隹(zhuī),短尾鸟的总称。本义:野鸡)。"}, {"meaning": "同本义。", "cites": [{"t": "雉有十四种。", "b": "《说文》"}, {"t": "雉者,野鸟。", "b": "《尚书大传》"}, {"t": "雉,耿介之鸟也。", "b": "《韩诗章句》"}, {"t": "离为雉。", "b": "《易·说卦》"}, {"t": "凡挚士雉谓其守介节。交有时,别有伦也。", "b": "《礼记·曲礼》"}, {"t": "雄雉于飞。", "b": "《诗·邶风·雄雉》"}, {"t": "无雉兔鲋鱼。", "b": "《墨子·公输》"}], "words": [{"w": "雉尾扇", "t": "野鸡尾部羽毛制作的扇子。亦为仪仗之一"}, {"w": "雉尾", "t": "皇帝坐朝时左右侍从所执的用野鸡尾羽制的扇障"}, {"w": "雉经", "t": "吊死;上吊。"}]}, {"meaning": "古代计算城墙面积的单位 。长三丈、高一丈为一雉。", "cites": [{"t": "五楮而雉。", "b": "《公羊传·定公十二年》"}, {"t": "都城过百雉。", "b": "《左传·隐公元年》。注:“三堵曰雉。”"}, {"t": "王宫门阿之制五雉。", "b": "《考工记·匠人》。注:“长三尺高一丈。”"}]}, {"meaning": "城墙。", "cites": [{"t": "出没眺楼雉。", "b": "谢朓《和王著作八公山》"}]}]}]','jingmo-wenyan');
