INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5498wx','稗','1','bài','禾','13','','[{"pinyin": "bài", "defs": [{"meaning": "(形声。从禾,卑声。本义:稻田里的一种杂草) 稗草。一年生禾草(Echinochloa crusgalli),叶似稻,节间无毛,杂生于稻田中,有害于稻子的生长。", "cites": [{"t": "稗,禾别也。", "b": "《说文》"}, {"t": "用秕稗也。", "b": "《左传·定公十年》。注:“草之似谷者。”"}, {"t": "不如夷稗。", "b": "《孟子》"}, {"t": "养稊(tí一种形似稗的草)稗者伤禾稼。", "b": "王符《潜夫论》"}], "words": [{"w": "稗秕", "t": "稗,稻田杂草;秕,中空或不饱满的谷粒。"}]}, {"meaning": "形容小;非正统的。", "cites": [{"t": "稗,小也。", "b": "《广雅》"}, {"t": "盖出于稗官。", "b": "《汉书·艺文志》。注:“偶语为稗。”按:亦别种非正之意。故小贩亦谓之稗贩。"}, {"t": "蒙正起稗贩,因缘戚里得官。", "b": "《宋史·高若讷传》"}, {"t": "汝来床前,为说稗官野史可喜可愕之事,聊资一欢。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "稗官", "t": "古代的小官名。因稗官也收集民间故事小说,后沿以称小说家"}, {"w": "稗官野史", "t": "略称稗史。泛称记载轶闻琐事的文字"}, {"w": "稗政", "t": "指不良的政治措施。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5499wx','稔','1','rěn','禾','13','','[{"pinyin": "rěn", "defs": [{"meaning": "(形声。从禾,念声。本义:庄稼成熟)。"}, {"meaning": "同本义。", "cites": [{"t": "稔,谷熟也。", "b": "《说文》"}, {"t": "不稔于岁。", "b": "《国语·吴语》。注:“熟也。”"}, {"t": "岁比登稔。", "b": "《后汉书·明帝纪》"}, {"t": "吴兴频岁失稔。", "b": "《南史·顾宪之传》"}], "words": [{"w": "稔岁", "t": "禾谷丰收的年岁"}, {"w": "稔收", "t": "犹丰收"}, {"w": "稔泰", "t": "谓年岁丰登,天下太平。"}]}, {"meaning": "事物积久养成。", "cites": [{"t": "夏殷之朝适穷,桀纣之恶适稔。", "b": "《论衡·偶会》"}], "words": [{"w": "稔戾", "t": "积罪"}, {"w": "稔奸", "t": "谓一向通奸"}, {"w": "稔恶", "t": "罪恶深重"}, {"w": "稔恶不悛", "t": "长期作恶而不悔改"}, {"w": "稔恶盈贯", "t": "谓所积罪恶之多,达于极点"}, {"w": "稔恶藏奸", "t": "长期作恶,包藏祸心"}, {"w": "稔祸", "t": "酿祸"}, {"w": "稔乱", "t": "酿祸"}, {"w": "稔寇", "t": "恶贯满盈的敌人。"}]}, {"meaning": "熟悉。", "cites": [{"t": "水穴石中,莫稔所去。", "b": "《徐霞客游记·浙游日记》"}], "words": [{"w": "稔悉", "t": "熟悉"}, {"w": "素稔", "t": ""}]}, {"meaning": "年,年度。", "cites": [{"t": "稔,年也。", "b": "《广雅·释诂》"}, {"t": "不可以五稔。", "b": "《左传·僖公二年》"}, {"t": "鲜不五稔。", "b": "《国语·晋语》"}, {"t": "不三稔矣。", "b": "《国语·郑语》。"}]}, {"meaning": ""}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5500wx','筠','1','jūn yún','竹','13','','[{"pinyin": "jūn", "defs": [{"meaning": "古州名  。"}, {"meaning": "唐武德七年置。以地产筠篁得名。辖境约当今江西省高安、上高、新昌等县地。"}, {"meaning": "唐羁縻州,其地即今四川省南部的筠连县。"}]}, {"pinyin": "yún", "defs": [{"meaning": "(形声。从竹,均声。本义:竹子的青皮;竹皮)。"}, {"meaning": "同本义。", "cites": [{"t": "筠,竹皮之美质也。", "b": "《广韵》"}, {"t": "手握青筠之杖。", "b": "王嘉《拾遗记》"}, {"t": "其在人也,如竹箭之有筠也。", "b": "《礼记》。郑玄注:“筠,竹之青皮也。”"}, {"t": "绮窗唱和,指花月为题,绣阁论情,对松筠为誓。", "b": "《警世通言》"}], "words": [{"w": "筠管", "t": "竹管"}, {"w": "筠筒", "t": "竹筒"}, {"w": "筠窗", "t": "竹窗"}, {"w": "筠梯", "t": "竹梯"}, {"w": "筠席", "t": "竹席"}, {"w": " 筠床", "t": "竹床"}, {"w": " 筠纸扇", "t": "竹柄纸扇"}, {"w": " 筠帘", "t": "竹帘。"}]}, {"meaning": "竹子的别称。", "cites": [{"t": "目才到三眠半月强,即时懒意满筠筐。", "b": "清·周煌《吴兴蚕词》"}, {"t": "黛叶轻筠绿,金花笑菊秋。", "b": "唐·钱起《赋得池上丁香树》"}], "words": [{"w": "筠溪", "t": "竹丛中的流水"}, {"w": "筠斑", "t": "斑竹"}, {"w": "筠廊", "t": "竹丛中的回廊"}, {"w": "筠筒", "t": "竹筒"}, {"w": "筠管", "t": "竹管,多用以指笔"}, {"w": "筠笼", "t": "覆罩在香炉上的竹笼。"}]}, {"meaning": "竹制的笛类管乐器。", "cites": [{"t": "窃闻平阳击石,山谷为之调;大禹吹筠,风云为之动。", "b": "北周·庾信《赵国公集序》"}]}]}]','jingmo-wenyan');
