INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5502wx','筮','1','shì','竹','13','','[{"pinyin": "shì", "defs": [{"meaning": "(会意。从竹,从巫。“竹”表草木,“巫”表占卜者。本义:古代用蓍(shī)草占卜的一种迷信活动称“筮”)同本义。", "cites": [{"t": "筮,易卦用蓍也。", "b": "《说文》"}, {"t": "筮于庙门。", "b": "《仪礼·士冠礼》"}, {"t": "筴为筮。", "b": "《礼记·曲礼》"}, {"t": "尔卜尔筮。", "b": "《诗·卫风·氓》"}, {"t": "卜之,不吉;筮之,吉。", "b": "《左传·僖公四年》"}], "words": [{"w": "筮卜", "t": "用蓍草及龟甲占卜吉凶"}, {"w": "筮仕", "t": "初次出仕做官。古人将出仕必先占吉凶,后因称出来作官为出仕"}, {"w": "筮验", "t": "占筮的证验"}, {"w": "筮短龟长", "t": "龟卜较筮占灵验"}, {"w": "筮人", "t": "掌卜筮的人;司占卦的人"}, {"w": "筮问", "t": "卜问"}, {"w": "筮决", "t": "以筮卜决定"}, {"w": "筮宅", "t": "埋葬时,筮卜坟墓位置的适当与否"}, {"w": "筮氏", "t": "卜筮者"}, {"w": "筮日", "t": "行卜筮礼仪之当日。"}]}]}]','jingmo-wenyan');
