INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5505wx','牒','1','dié','片','13','','[{"pinyin": "dié", "defs": [{"meaning": "(会意。从片,葉(yè)声。古时木片也常用作书写材料,故从“片”。本义:简札)。"}, {"meaning": "同本义。古代书写用的木片或竹片。", "cites": [{"t": "版,札也。", "b": "《说文》。按,小简曰牒,大简曰册。薄者曰牒,厚者曰牍。"}, {"t": "受牒而退。", "b": "《左传·昭公二十五年》"}, {"t": "截以为牒。", "b": "《汉书·路温舒传》"}, {"t": "王牒石记。", "b": "左思《吴都赋》"}], "words": [{"w": "金牒;玉牒", "t": ""}]}, {"meaning": "特指谱籍。", "cites": [{"t": "余读牒记。", "b": "《史记·三代世表》。索隐:“记系谥之书,以牒为之。”"}], "words": [{"w": "谱牒;家牒", "t": ""}]}, {"meaning": "通常由官方颁发的证明某事的文件。", "cites": [{"t": "昨夜军牒来,电兵万五千。", "b": "唐·李商隐《行次西郊作》"}], "words": [{"w": "通牒;牒文", "t": "公文;文书"}, {"w": "牒旨", "t": "命令"}, {"w": "牒署", "t": "办理;管理。"}]}, {"meaning": "书籍,簿册。", "cites": [{"t": "壮志异时 (将来) 开史牒。", "b": "宋·王安石《送江宁彭给事赴阙》"}, {"t": "其高第者上名牒。", "b": "《后汉书·质帝纪》"}]}, {"meaning": "讼辞,状子。"}]}]','jingmo-wenyan');
