INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5509wx','愆','1','qiān','心','13','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从心,衍声。本义:过错;罪过)。"}, {"meaning": "同本义。", "cites": [{"t": "愆,过也。", "b": "《说文》"}, {"t": "失所为愆。", "b": "《左传·哀公十六年》"}, {"t": "不愆不忘。", "b": "《诗·大雅·假乐》"}, {"t": "街亭之役,咎由马谡,而君引愆。", "b": "《三国志·诸葛亮传》"}], "words": [{"w": "愆锁", "t": "罪锁"}, {"w": "愆戾", "t": "过失;罪咎"}, {"w": "愆尤", "t": "过失,罪咎"}, {"w": "愆忒", "t": "差错"}, {"w": "愆罪", "t": "罪咎,罪过"}, {"w": "愆殃", "t": "过失,罪恶"}, {"w": "愆负", "t": "过失"}, {"w": "愆过", "t": "罪恶,罪过。"}]}, {"meaning": "超过;延误。", "cites": [{"t": "愆期。", "b": "《易·归妹》"}, {"t": "冬无愆阳。", "b": "《左传·昭公四年》"}, {"t": "不愆于素。", "b": "《左传·宣公十一年》"}, {"t": "匪我愆期。", "b": "《诗·卫风·氓》"}], "words": [{"w": "愆亢", "t": "久旱"}, {"w": "愆阳", "t": "阳气过盛"}, {"w": "愆晴", "t": "久雨未晴"}, {"w": "愆程", "t": "误了预定的旅程"}, {"w": "愆悬", "t": "失期不至"}, {"w": "愆候", "t": "失时"}, {"w": "愆素", "t": "越过原来计划。"}]}, {"meaning": "失掉,丧失。", "cites": [{"t": "王昏不若,用愆厥位。", "b": "《左传·昭公二十六年》"}, {"t": "天时有愆伏。", "b": "宋·沈括《梦溪笔谈》"}], "words": [{"w": "愆德隳好", "t": "丧失道义,破坏友好"}, {"w": "愆伏", "t": "阴阳失调"}, {"w": "愆和", "t": "失和。"}]}, {"meaning": "亏,损。", "cites": [{"t": "不愆不忘,率由旧章。", "b": "《诗·大雅·假乐》"}, {"t": "苟伤廉而愆义。", "b": "陆机《文赋》"}]}]}]','jingmo-wenyan');
