INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5515wx','貉','1','háo hé','豸','13','','[{"pinyin": "háo", "defs": [{"meaning": "—— 义同“貉”(hé)。"}]}, {"pinyin": "hé", "defs": [{"meaning": "(形声。从豸(zhì),长脊的野兽,各声。本义:一种野兽,通称“貉子”,也叫“狸”)。"}, {"meaning": "同本义  食肉目犬科的一种动物(Nyctereutes procyonoides),产地包括中、日、朝和乌苏里边区。有三个亚种,产于中国东北、华北、华中、东南和西南各省区,是著名的毛皮兽,它的毛皮被称为貉子皮或貉绒。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5516wx','颔','1','hàn','页','13','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从页(xié),含声。从“页”,表示与头有关。本义:下巴颏)。"}, {"meaning": "同本义。", "cites": [{"t": "颔,含也,口含物之车也。", "b": "《释名》"}, {"t": "颐,或曰颔车。", "b": "《释名·释形体》"}, {"t": "绝其颔。", "b": "《公羊传·宣公六年》"}, {"t": "夫千金之珠,必在九重之渊,而骊龙颔下。", "b": "《庄子·列御寇》"}, {"t": "生燕颔虎颈,飞而食肉,此万里侯相也。", "b": "《后汉书·班超传》"}, {"t": "相逢应不识,满颔白髭须。", "b": "白居易《东南行》"}], "words": [{"w": "颔车", "t": "齿下骨的别名"}, {"w": "颔雪", "t": "颔下的白须"}, {"w": "颔颏", "t": "下巴。"}]}, {"meaning": "位于颈的前上方,相当于颏部的下方,结喉的上方。", "cites": [{"t": "热争则腰痛,不可用俯仰,腹满泄,两颔痛。", "b": "《素问·刺热篇》"}]}, {"meaning": "点头。", "cites": [{"t": "逆于门者,颔之而己。", "b": "《左传·襄公二十六年》"}, {"t": "但微颔之。", "b": "宋·欧阳修《归田录》"}], "words": [{"w": "颔首;颔头", "t": "点头"}, {"w": "颔命", "t": "接受旨意。"}]}, {"meaning": "摇动 。如;颔颐(动动腮巴)。"}]}]','jingmo-wenyan');
