INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5523wx','媵','1','yìng','女','13','','[{"pinyin": "yìng", "defs": [{"meaning": "(形声。从女,朕(zhèn)声。本义:指随嫁,陪送出嫁)。"}, {"meaning": "同本义。", "cites": [{"t": "媵御馂。", "b": "《仪礼·士昏礼》。注:“古者嫁女,必娣姪从之,谓之媵。”"}, {"t": "以媵秦穆姬。", "b": "《左传·僖公五年》"}]}, {"meaning": "相送;致送。", "cites": [{"t": "媵,送也。", "b": "《尔雅》"}, {"t": "媵布席于奥。", "b": "《仪礼·士昏礼》。注:“媵,送也。”"}, {"t": "媵觚于宾。", "b": "《仪礼·燕礼》。注;“媵,送也。”"}, {"t": "鱼鳞鳞兮来媵予。", "b": "《楚辞·九歌·河伯》"}, {"t": "媵有莘之妇。", "b": "《楚辞·天问》"}]}, {"meaning": "古代嫁女时随嫁或陪嫁的人。", "cites": [{"t": "从衣文之媵七十人。", "b": "《韩非子·外储》"}]}, {"meaning": "小妻。", "cites": [{"t": "且买妾纳媵,因聘为资。", "b": "南朝梁·沈约《秦弹王源》"}], "words": [{"w": "媵侍", "t": "妾和婢"}, {"w": "媵御", "t": "姬妾"}, {"w": "媵嬖", "t": "宠妾。"}]}, {"meaning": "庶贱者,服役的女人。", "cites": [{"t": "媵人持汤沃灌。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "媵婢", "t": "侍婢"}, {"w": "媵母", "t": "普通妇女。"}]}]}]','jingmo-wenyan');
