INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5525wx','鲅','1','bà','鱼','13','','[{"pinyin": "bà", "defs": [{"meaning": "马鲛属(Scomberomorus)几种鲭的任一种 。也称“马鲛鱼”。体侧扁,长达1米多。银灰色,具暗色横纹或斑点。常群集作远程洄游。中国沿海均产。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5526wx','鲆','1','píng','鱼','13','','[{"pinyin": "píng", "defs": [{"meaning": "鲆科比目鱼 ,体形侧扁,两眼都在身体的左侧,有眼的一侧灰褐色或深褐色,无眼一侧白色,常见的有牙鲆、斑鲆等。"}]}]','jingmo-wenyan');
