INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5529wx','稣','1','sū','禾','13','','[{"pinyin": "sū", "defs": [{"meaning": "(形声。从禾,鱼声。“苏”的本字。艸、禾义通。“稣”常用为“苏醒”义)。"}, {"meaning": "", "cites": [{"t": "稣,把取禾若也。", "b": "《说文》。段玉裁改为“杷取禾若也”,并注:“杷,各本作把,今正。禾若散乱,杷而取之,不当言把也。"}]}, {"meaning": "转意为死而复生,苏醒,复活。今作“苏”。", "cites": [{"t": "留尸十日,平旦喉中有声如雨,俄而稣活", "b": "《法苑珠林》"}]}, {"meaning": "“穌”另见sū(苏)。"}]}]','jingmo-wenyan');
