INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5531wx','鲐','1','tái','鱼','13','','[{"pinyin": "tái", "defs": [{"meaning": "鲐鱼,也称鲭、油筒鱼、青花鱼 。见于大多数暖海区的小型鲭科鱼(Pneumatopphorus grex)。背青腹白,体侧上部有深蓝色波状条纹。生活在海中,黄海、渤海盛产", "words": [{"w": "鲐文", "t": "鲐鱼样的斑纹"}]}, {"meaning": "代称老年人", "words": [{"w": "鲐颜", "t": "老迈的容颜"}, {"w": "鲐稚", "t": "老幼"}, {"w": "鲐叟", "t": "老人"}, {"w": "鲐背", "t": "背上生鲐鱼般的斑纹"}]}]}]','jingmo-wenyan');
