INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5535wx','觥','1','gōng','角','13','','[{"pinyin": "gōng", "defs": [{"meaning": "(形声。从角,黄声。俗从光声。本义:中国古代用兽角制的酒器,后也有用木或铜制的) 同本义。", "cites": [{"t": "觵,兕牛角可以饮者也。", "b": "《说文》"}, {"t": "我姑酌彼兕觥。", "b": "《诗·周南·卷耳》。传:“角爵也。”"}], "words": [{"w": "觥爵", "t": "盛酒的器皿"}, {"w": "觥筹", "t": "酒器和酒令筹"}, {"w": "觥盏", "t": "酒杯"}, {"w": "觥盂", "t": "酒器。"}]}, {"meaning": "大,丰盛。", "cites": [{"t": "觥饭不及壶食。", "b": "《国语·越语》"}, {"t": "觥羊之义。", "b": "扬雄《太玄·毅》"}], "words": [{"w": "觥羊", "t": "大羊"}, {"w": "觥饭", "t": "丰盛的饭菜"}, {"w": "觥责", "t": "大加指责。"}]}, {"meaning": "刚直、壮健的样子。", "cites": [{"t": "关中觥觥郭子横。", "b": "《后汉书·郭宪传》。注:“刚直之貌。”"}]}]}]','jingmo-wenyan');
