('5537wx','馐','1','xiū','饣','13','','[{"pinyin": "xiū", "defs": [{"meaning": "本字为“羞”。精美的食品。", "cites": [{"t": "酒既行,珍肴杂错,入口甘芳,并异常馐。", "b": "《聊斋志异》"}], "words": [{"w": "馐膳", "t": "饭菜"}, {"w": "馐馔", "t": "珍肴美味"}, {"w": "馐错", "t": "珍馐海错。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5538wx','鹑','1','chún','鸟','13','','[{"pinyin": "chún", "defs": [{"meaning": "鹌鹑的简称 。古称羽毛无斑者为鹌,有斑者为鹑。后混称为鹌鹑。欧洲、亚洲和非洲的一种迁徙性雉类猎鸟,约18厘米长,上部棕黑色而有皮黄斑点,喉部呈黑白二色,胸部为发红色的皮黄色,腹部呈白色。", "cites": [{"t": "不狩不猎,胡瞻尔庭有悬鹑兮。", "b": "《诗·魏风·伐檀》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5539wx','亶','1','dǎn dàn','亠','13','','[{"pinyin": "dǎn", "defs": [{"meaning": "(形声。本义:谷多)。"}, {"meaning": "同本义。", "cites": [{"t": "亶,多谷也。", "b": "《说文》"}, {"t": "择三有事,亶侯多藏。", "b": "《诗·小雅·十月之交》"}]}, {"meaning": "厚道;忠实。", "cites": [{"t": "亶,信也;又,诚也。", "b": "《尔雅》"}, {"t": "不实于亶。", "b": "《诗·大雅·板》"}], "words": [{"w": "亶厚", "t": "忠厚,淳厚"}, {"w": "亶诚", "t": "真诚。"}]}, {"meaning": "姓。"}]}, {"pinyin": "dàn", "defs": [{"meaning": "仅,只。", "cites": [{"t": "非亶倒县(悬)而已。", "b": "《汉书·贾谊传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5540wx','瘃','1','zhú','疒','13','','[{"pinyin": "zhú", "defs": [{"meaning": "冻疮。", "cites": [{"t": "将军士寒,手足皲瘃。", "b": "《汉书》"}, {"t": "穷腊一尺雪,跨春气逾严,童仆苦病瘃,庭户无与杴。", "b": "宋·梅尧臣《对残雪怀欧阳永叔》"}]}, {"meaning": "瘃坠(瘃堕)。"}, {"meaning": "冻而凝结。", "cites": [{"t": "迨至蒙古入杭,群驱北徒,瘃足堕指,啼饥僦食于原野。", "b": "王夫之《宋论》"}], "words": [{"w": "瘃脯", "t": "腊肉"}, {"w": "瘃鱼", "t": "鱼类腊制品"}, {"w": "瘃腊", "t": "鱼肉类腊制品。"}]}]}]','jingmo-wenyan');
