INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5542wx','痼','1','gù','疒','13','','[{"pinyin": "gù", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关。固声。“固”(顽固)也具有表意作用。本义:疾病经久难愈的)。"}, {"meaning": "同本义。", "cites": [{"t": "痼,久病也。", "b": "《玉篇》"}, {"t": "邓太后以皇子胜有痼疾。", "b": "《后汉书·周章传》"}], "words": [{"w": "痼瘵", "t": "积久难治的病。亦指患痼疾的人。"}]}, {"meaning": "引申为根深蒂固的,难改变的。", "cites": [{"t": "烟霞成痼癖,声价藉巢由。", "b": "元·潘音《反北山嘲》"}], "words": [{"w": "痼习;痼癖", "t": "不能改掉的积习。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5543wx','痿','1','wěi','疒','13','','[{"pinyin": "wěi", "defs": [{"meaning": "神经系疾病。筋肉萎缩,不能举动。", "cites": [{"t": "痿,痺也。", "b": "《说文》"}, {"t": "大经空虚发为肌痺,传为脉痿。", "b": "《素问·痿论》"}, {"t": "即位,痿痺。", "b": "《汉书·哀帝纪赞》"}], "words": [{"w": "痿弱", "t": "肢体萎缩软弱"}, {"w": "痿症", "t": "阳痿"}, {"w": "痿症;痿疾", "t": "身体某部分萎缩或失去机能的病。特指阳痿"}, {"w": "痿病", "t": "肢体动作不便的病"}, {"w": "痿废", "t": "痿缩残废"}, {"w": "萎痹", "t": "肢体麻木不能动作的病"}, {"w": "痿蹶", "t": "指双足麻痹,无法行动"}, {"w": "痿不忘起", "t": "身体麻痹行动不便的人也不忘起行。"}]}]}]','jingmo-wenyan');
