('5544wx','瘐','1','yǔ','疒','13','','[{"pinyin": "yǔ", "defs": [{"meaning": "忧郁", "words": [{"w": "瘐瘐", "t": "忧郁之病"}, {"w": "瘐困", "t": "疲乏"}]}, {"meaning": "囚犯在狱中因饥寒致病", "words": [{"w": "瘐弊", "t": "囚犯病困"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5545wx','瘁','1','cuì','疒','13','','[{"pinyin": "cuì", "defs": [{"meaning": "(形声。从疒(chuáng),卒声。从“疒”,表示与疾病有关。本义:困病)。"}, {"meaning": "同本义。", "cites": [{"t": "顇,病也。", "b": "《尔雅》"}, {"t": "邦国殄顇。", "b": "《汉书·王莽传》"}], "words": [{"w": "瘁音", "t": "疲病衰弱的声音"}, {"w": "瘁瘁", "t": "疲病的样子。"}]}, {"meaning": "劳累。", "cites": [{"t": "生我劳瘁。", "b": "《诗·小雅·蓼莪》"}, {"t": "使人心瘁。", "b": "《高唐赋》"}], "words": [{"w": "瘁瘅", "t": "劳累痛苦"}, {"w": "瘁心", "t": "犹苦心;劳心"}, {"w": "瘁志", "t": "谓苦心劳神,一意于某事。"}]}, {"meaning": "忧愁;悲伤。", "cites": [{"t": "登高远望,使人心瘁。", "b": "宋玉《高唐赋》"}], "words": [{"w": "瘁瘁", "t": "忧愁貌"}, {"w": "瘁貌", "t": "忧愁容"}, {"w": "瘁慑", "t": "忧伤屈服貌。"}]}, {"meaning": "憔悴;枯槁。", "cites": [{"t": "仆夫况瘁。", "b": "《诗·小雅·出车》"}], "words": [{"w": "瘁貌", "t": "使面容憔悴"}, {"w": "瘁赧", "t": "憔悴赧然"}, {"w": "瘁景", "t": "萧条的景象"}, {"w": "瘁索", "t": "犹萧索;萧瑟。"}]}, {"meaning": "毁;损坏。", "cites": [{"t": "瘁万物以如归,运大泽而若漏。", "b": "《海潮赋》"}]}]}]','jingmo-wenyan');
