('5547wx','麂','1','jǐ','鹿','13','','[{"pinyin": "jǐ", "defs": [{"meaning": "麂子 ,像鹿,比鹿小,毛黄黑色,雄的有很短的角,皮可做鞋面、手套等,肉可以吃", "words": [{"w": "麂眼", "t": "形状如麂眼的篱格"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5548wx','裔','1','yì','衣','13','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。衣袖。也指衣裳的前襟。本义:衣服的边缘)。"}, {"meaning": "同本义 。也泛指边沿。", "cites": [{"t": "麋何食兮庭中,蛟何为兮水裔。", "b": "《楚辞》"}], "words": [{"w": "裔邑", "t": "边地。"}]}, {"meaning": "边远的地方。", "cites": [{"t": "流四凶族…投诸四裔。", "b": "《左传》"}], "words": [{"w": "裔民", "t": "流放边地的凶恶之民。"}]}, {"meaning": "边远地区的民族。", "cites": [{"t": "裔不谌夏,夷不乱华。", "b": "《左传》"}], "words": [{"w": "裔不谋夏", "t": "夷狄不可侵乱华夏。"}]}, {"meaning": "后代。", "cites": [{"t": "功加于时,德垂后裔。", "b": "《书·微子之命》"}, {"t": "谓我诸戎,是四岳之裔胄也。", "b": "《左传·襄公十四年》"}, {"t": "裔,苗裔。", "b": "《广韵》"}, {"t": "访后裔。", "b": "《新唐书·李白传》"}], "words": [{"w": "裔胄", "t": "后代的子孙"}, {"w": "裔子", "t": "后代子孙"}, {"w": "裔姓", "t": "同姓后代。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5549wx','歆','1','xīn','欠','13','','[{"pinyin": "xīn", "defs": [{"meaning": "飨,嗅闻 。古指祭祀时鬼神享受祭品的香气。", "cites": [{"t": "其香始升,上帝居歆。", "b": "《诗·大雅》"}], "words": [{"w": "歆享", "t": "歆止,歆飨。神灵享受供物"}, {"w": "歆嗅", "t": "歆飨"}, {"w": "歆尝", "t": "神灵享用祭品。"}]}, {"meaning": "动。", "cites": [{"t": "无然歆羡。", "b": "《诗·大雅·皇矣》。朱熹集传:“歆,欲之动也。”"}, {"t": "以弗无子,履帝武敏歆。", "b": "《诗·大雅·生民》"}], "words": [{"w": "歆动", "t": "触动;惊动。"}]}, {"meaning": "贪图;羡慕。", "cites": [{"t": "若易中下,楚必歆之。", "b": "《国语·楚语上》"}], "words": [{"w": "歆美", "t": "钦羡赞美"}, {"w": "歆淫", "t": "纵乐"}, {"w": "歆叹", "t": "钦羡赞叹。"}]}, {"meaning": "悦服;欣喜。", "cites": [{"t": "以言德于民,民歆而德之,则归心焉。", "b": "《国语·周语下》"}], "words": [{"w": "歆服", "t": "欣喜悦服"}, {"w": "歆快", "t": "喜悦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5550wx','旒','1','liú','方','13','','[{"pinyin": "liú", "defs": [{"meaning": "旗子下边悬垂的饰物。", "cites": [{"t": "旗十有二旒。", "b": "《礼记》。又如:旒旌(有垂旒的旌旗);旒缀(旌旗的垂饰。系结于旌旗之上。喻附属);旒苏(旒旗的垂饰)"}]}, {"meaning": "古代皇帝礼帽前后的玉串。", "cites": [{"t": "天子玉藻,十有二旒。", "b": "《礼记·玉藻》"}], "words": [{"w": "旒纩;旒紞", "t": "冕冠上悬垂的玉串"}, {"w": "旒扆", "t": "借称帝王。扆为帝王座位后的屏风。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5551wx','雍','1','yōng','隹','13','','[{"pinyin": "yōng", "defs": [{"meaning": "水被壅塞而成的池沼。", "cites": [{"t": "振鹭于飞,于彼西雍。", "b": "《诗·周颂·振鹭》"}, {"t": "毋雍泉。", "b": "《谷梁传·僖公九年》。释文:“雍,塞也。”"}, {"t": "今臣雍阏不得闻。", "b": "《汉书·中山靖王胜传》。师古曰:“雍读曰壅。雍,塞也。”"}]}, {"meaning": "古天子祭祀宗庙毕撤俎豆时所奏的乐章,亦用为撤膳时之乐。", "cites": [{"t": "三家者以《雍》彻。", "b": "《论语》"}]}, {"meaning": "和谐;和睦。", "cites": [{"t": "雍睦亲族。", "b": "《新五代史》"}], "words": [{"w": "雍熙于变", "t": "和谐兴盛,国家稳定"}, {"w": "雍恬", "t": "和洽安乐"}, {"w": "雍雍", "t": "声音和谐;鸟和鸣声"}, {"w": "雍齿封侯", "t": "不计宿怨的典故。"}]}, {"meaning": "", "cites": [{"t": "维尘雍兮。", "b": "《诗·小雅·无将大车》。释文:“雍,字亦作壅。”"}, {"t": "雍以沙幕。", "b": "《汉书·匈奴传赞》"}, {"t": "上下雍隔故也。", "b": "《后汉书·梁冀传》"}], "words": [{"w": "雍防", "t": "壅土堵防"}, {"w": "雍害", "t": "阻挠妨害"}, {"w": "雍遏", "t": "阻塞,壅塞"}, {"w": "雍蔽", "t": "蒙蔽;隔绝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5552wx','阖','1','hé','门','13','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从门,盍声。本义:门扇)。"}, {"meaning": "同本义。", "cites": [{"t": "阖,门扇也。", "b": "《说文》"}, {"t": "外阖不闭。", "b": "《荀子·儒效》。注:“阖,门扇也。”"}], "words": [{"w": "阖扇", "t": "门扇。"}]}, {"meaning": "盖墙用的草帘子。", "cites": [{"t": "茨墙则剪阖。", "b": "《周礼》"}]}, {"meaning": "关闭。", "cites": [{"t": "是故阖户谓之坤。", "b": "《易·系辞上》。虞注:“阖,闭翕也。”"}, {"t": "欲阖口而无言兮。", "b": "《楚辞·东方朔·七谏谬谏》"}, {"t": "当且阖閤,勿有所问。", "b": "《汉书·孙宝传》"}, {"t": "阖门善俟。", "b": "明·高启《书博鸡者事》"}, {"t": "以可阖门。", "b": "明·归有光《项脊轩志》"}, {"t": "阖门投火死。", "b": "清·邵长衡《青门剩稿》"}], "words": [{"w": "阖眼;阖户", "t": "闭户,关门"}, {"w": "阖闭", "t": "闭合"}, {"w": "阖棺", "t": "盖棺"}, {"w": "阖辟", "t": "开关"}, {"w": "阖开", "t": "开合。"}]}, {"meaning": "符合", "cites": [{"t": "意者臣愚而不阖于王心邪?", "b": "《战国策·秦策三》"}], "words": [{"w": "阖心", "t": "符合心意。"}]}, {"meaning": "全,总。", "cites": [{"t": "今或至阖郡而不荐一人。", "b": "《汉书·武帝纪》"}], "words": [{"w": "阖属", "t": "所有属下"}, {"w": "阖座", "t": "满座人"}, {"w": "阖朝", "t": "全朝"}, {"w": "阖门百口", "t": "全家所有的成员。"}]}, {"meaning": "为什么不,何不。", "cites": [{"t": "夫子阖行邪?", "b": "《庄子·天地》"}]}, {"meaning": "为何,为什么;怎么", "cites": [{"t": "阖不亦问是已,奚惑然为。", "b": "《庄子·徐无鬼》"}, {"t": "桓公谓鲍叔牙曰:“阖不起为寡人寿乎?”", "b": "《管子·小称》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5553wx','阗','1','tián','门','13','','[{"pinyin": "tián", "defs": [{"meaning": "(形声。从门,真声。本义:盛;大) 同本义。也作“阗阗”。", "cites": [{"t": "阗,盛貌。", "b": "《说文》"}, {"t": "怒涛泼地轰雷阗。", "b": "黄遵宪《宫本鸭北索题晁山图》"}], "words": [{"w": "阗阗", "t": "状声词。常用以形容鼓声、车声。也形容某些盛大壮阔的场景。"}]}, {"meaning": "充满;填塞。", "cites": [{"t": "宾客阗门。", "b": "《史记·汲郑列传》"}], "words": [{"w": "阗溢", "t": "充满,盈满"}, {"w": "阗噎", "t": "盈满,满溢"}, {"w": "阗门", "t": "充塞门庭"}, {"w": "阗拥", "t": "充塞拥挤"}, {"w": "阗塞", "t": "拥塞"}, {"w": "阗咽", "t": "堵塞;拥挤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5554wx','阙','1','quē què jué','门','13','','[{"pinyin": "quē", "defs": [{"meaning": "缺点;错误。", "cites": [{"t": "次之又不能拾遗补阙。", "b": "汉·司马迁《报任少卿书》"}, {"t": "裨补阙洞。", "b": "诸葛亮《出师表》"}], "words": [{"w": "阙败", "t": "因失误而把事情搞糟"}, {"w": "阙政", "t": "有毛病的政治措施"}, {"w": "阙失", "t": "失误;错误。"}]}, {"meaning": "豁口,空缺。", "cites": [{"t": "昔者女娲氏练五色石以补其阙。", "b": "《列子·汤问》"}, {"t": "自三峡七百里中,两岸连山,略无阙处。", "b": "《水经注》"}], "words": [{"w": "阙陷", "t": "凹陷。"}]}, {"meaning": "削减;毁坏。", "cites": [{"t": "又欲阙翦我公室,倾覆我社稷。", "b": "《左传·成公十三年》"}, {"t": "阙更减赋,尽休力役。", "b": "《汉书》"}], "words": [{"w": "阙翦", "t": "毁坏。"}]}, {"meaning": "空缺;缺少。也作“缺”。", "cites": [{"t": "三纲之道,天地之纪,毋乃有阙?", "b": "《三国演义》"}], "words": [{"w": "阙遗", "t": "缺少;遗漏"}, {"w": "阙少", "t": "缺少"}, {"w": "阙遗", "t": "缺少;遗漏"}, {"w": "阙少", "t": "缺少"}, {"w": "阙笔", "t": "缺笔画"}, {"w": "阙漏", "t": "空隙"}, {"w": "阙略", "t": "缺漏。"}]}, {"meaning": "欠,应给而不给。", "cites": [{"t": "逃死阙税,取于居者,一室空而四邻亦尽。", "b": "《新唐书》"}]}, {"meaning": "挖。", "cites": [{"t": "若阙地及泉。", "b": "《左传·隐公元年》"}, {"t": "阙为深沟。", "b": "《国语·吴语》"}]}, {"meaning": "姓。"}]}, {"pinyin": "què", "defs": [{"meaning": "(形声。本义:古代宫殿、祠庙或陵墓前的高台,通常左右各一,台上起楼观。二阙之间有道路)。"}, {"meaning": "同本义。", "cites": [{"t": "阙,门观也。", "b": "《说文》。徐锴曰:“以其阙然为道,谓之阙。以其上可远观,谓之观。”"}, {"t": "挑兮达兮,在城阙兮。", "b": "《诗·郑风·子衿》"}, {"t": "萧丞相营作未央宫,立东阙、北阙、前殿、武库、太仓。", "b": "《史记·高祖纪》"}, {"t": "伏阙上平黎策。", "b": "清·张廷玉《明史》"}], "words": [{"w": "城阙", "t": "城门两边的瞭望台"}, {"w": "阙竦", "t": "高耸如阙门"}, {"w": "阙下", "t": "宫阙之下。"}]}, {"meaning": "石阙。神庙、坟墓之前砌立的石雕。", "cites": [{"t": "音尘绝,西风残照,汉家陵阙。", "b": "唐·李白《忆秦娥》"}], "words": [{"w": "太室阙;高颐阙", "t": ""}]}, {"meaning": "帝王居地的统称。", "cites": [{"t": "诣阙止书,书久不报。", "b": "《汉书·朱买臣传》"}]}]}, {"pinyin": "jué", "defs": [{"meaning": "去除。", "cites": [{"t": "以待会而考之,亡者阙之。", "b": "《周礼》"}]}, {"meaning": "挖掘。", "cites": [{"t": "若阙地及泉。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5555wx','羧','1','suō zuī','羊','13','','[{"pinyin": "suō", "defs": [{"meaning": "碳酸失去氢氧原子团而成的一价复基,即原子团-COOH ——化学名字用词", "words": [{"w": "羧基", "t": "碳酸失去氢氧原子团而成的一价复基,化学符号-COOH。"}]}]}, {"pinyin": "zuī", "defs": [{"meaning": "羊羧:古时冉駹族的羊毛织品。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5556wx','豢','1','huàn','豕','13','','[{"pinyin": "huàn", "defs": [{"meaning": "(形声。从豕(shǐ,猪),帣(juàn)声。本义:设围栏以谷物养猪)。"}, {"meaning": "同本义。", "cites": [{"t": "豢,以谷圈养豕也。", "b": "《说文》"}, {"t": "夫豢豕为酒。", "b": "《礼记·乐记》"}, {"t": "案刍豢。", "b": "《礼记·月令》"}, {"t": "掌豢祭祀。", "b": "《周礼·槁人》"}], "words": [{"w": "豢圉", "t": "饲养牛马的地方。"}]}, {"meaning": "泛指喂养;饲养。", "cites": [{"t": "凡畜养禽兽,皆曰豢。", "b": "《正字通》"}, {"t": "古者畜龙,故国有豢龙氏,有御龙氏。", "b": "《左传·昭公二十九年》"}], "words": [{"w": "豢池", "t": "养鱼池"}, {"w": "豢牢", "t": "兽圈"}, {"w": "豢畜", "t": "犹豢养"}, {"w": "豢圉", "t": "养牛马的地方"}, {"w": "豢牺", "t": "喂养牲畜。"}]}, {"meaning": "以利益为饵来引诱人为其服务,任其宰割。", "cites": [{"t": "豢文臣帷幄无谋,豢武夫疆场不猛。", "b": "孔尚任《桃花扇》"}]}, {"meaning": "贪图。", "cites": [{"t": "豢于游戏酒食之间。", "b": "宋·苏轼《教战守》"}, {"t": "而豢于富贵,安于顺境。", "b": "俞文豹《吹剑三录》"}]}, {"meaning": "以谷类饲养的家畜,如猪、狗。以别于吃草的牛、羊。", "cites": [{"t": "民食刍豢。", "b": "《庄子·齐物论》"}], "words": [{"w": "刍豢", "t": "刍,指吃草牲 口;豢,指吃谷物的牲 口,如犬,豕"}, {"w": "豢牢", "t": "泛指家畜"}, {"w": "豢龙", "t": "古代名马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5557wx','粳','1','jīng','米','13','','[{"pinyin": "jīng", "defs": [{"meaning": "(形声。从禾,亢声,或从更声。本义:粳稻,稻之不黏者。今指介于籼稻、糯稻之间的一种晚稻品种,米粒短而粗,米质黏性较强,胀性小) 同本义。", "cites": [{"t": "秔,稻属。", "b": "《说文》"}, {"t": "秔,不黏稻也。", "b": "《声类》"}, {"t": "更为秔稻。", "b": "《汉书·沟洫志》"}, {"t": "水澍稉。", "b": "左思《魏都赋》"}, {"t": "粳香等炊玉,韭美胜炮羔。", "b": "陆游《新凉》"}]}]}]','jingmo-wenyan');
