INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5567wx','溱','1','qín zhēn','氵','13','','[{"pinyin": "qín", "defs": [{"meaning": "地名用字", "words": [{"w": "溱潼（Qíntóng）", "t": "镇名,在江苏。"}]}]}, {"pinyin": "zhēn", "defs": [{"meaning": "古水名。"}, {"meaning": "源自湖南省临武县南,北流会武溪水,遂通称武水,下流合连江为北江,又合桂水(西江)为珠江,入海。", "cites": [{"t": "溱水,出桂阳临武入汇。从水,秦声。", "b": "《说文》"}]}, {"meaning": "源出河南省密县东北,东南流会洧水为双洎河,东流入贾鲁河。", "cites": [{"t": "溱与洧,方涣涣兮。", "b": "《诗·郑风·溱洧》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
