INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5571wx','溥','1','pǔ','氵','13','','[{"pinyin": "pǔ", "defs": [{"meaning": "(形声。左形,右声。本义:水之大,泛指广大)。"}, {"meaning": "同本义。", "cites": [{"t": "溥,大也。", "b": "《说文》"}, {"t": "溥之而横溥四海。", "b": "《礼记·祭义》"}, {"t": "泛滥溥漠。", "b": "马融《长笛赋》"}, {"t": "瞻彼溥原。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "溥洽", "t": "广博周遍"}, {"w": "溥大", "t": "广大"}, {"w": "溥将", "t": "广大。"}]}, {"meaning": "普遍的。", "cites": [{"t": "溥天之下,莫非王土。", "b": "《诗·小雅·北山》"}, {"t": "溥溥如天。", "b": "《礼记·中庸》"}], "words": [{"w": "溥畅", "t": "普及流畅"}, {"w": "溥博", "t": "普遍而广大"}, {"w": "溥天", "t": "遍天下"}, {"w": "溥泛", "t": "普遍,广泛"}, {"w": "溥遍", "t": "普遍。"}]}, {"meaning": "水涯,水边。", "cites": [{"t": "储与乎大溥,聊浪乎宇内。", "b": "《汉书·扬雄传上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5572wx','溧','1','lì','氵','13','','[{"pinyin": "lì", "defs": [{"meaning": "古水名。"}, {"meaning": "在今江苏省溧阳县。源出安徽省芜湖市,经高淳县入境。也称“陵水”,一名“濑水”,又名“永阳江”。"}, {"meaning": "即今湖北省随州市的溧河。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5573wx','溽','1','rù','氵','13','','[{"pinyin": "rù", "defs": [{"meaning": "(形声。从水,辱声。本义:湿热)。"}, {"meaning": "同本义。", "cites": [{"t": "溽,湿暑也。", "b": "《说文》"}, {"t": "土润溽暑。", "b": "《礼记·月令》。注;“润溽谓涂湿也。”"}], "words": [{"w": "溽夏", "t": "湿热的夏天"}, {"w": "溽景", "t": "溽暑的烈日"}, {"w": "溽蒸", "t": "溽热,湿热"}, {"w": "溽润", "t": "湿润"}, {"w": "溽露", "t": "繁多的露水。"}]}, {"meaning": "味浓厚,尤指美味。", "cites": [{"t": "其居处不淫,其饮食不溽。", "b": "《礼记·儒行》"}]}, {"meaning": "古水名,溽水。在今江苏省溧阳县。", "cites": [{"t": "己酉,天子饮于溽水之上。", "b": "《穆天子传》"}]}]}]','jingmo-wenyan');
