INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5576wx','溷','1','hùn','氵','13','','[{"pinyin": "hùn", "defs": [{"meaning": "(“混”的异体字) (形声。从水,圂(hùn)声。本义:混浊)。"}, {"meaning": "同本义。", "cites": [{"t": "溷,浊也。", "b": "《广雅·释诂三》"}, {"t": "刚柔分动。", "b": "《易·噬嗑卦》。注:“不溷乃明。”"}, {"t": "天气溷浊。", "b": "《汉书·翼奉传》"}, {"t": "桥内峡中有池一圆,近流水而不溷。", "b": "《徐霞客游记·滇游日记》"}], "words": [{"w": "溷然", "t": "污浊貌"}, {"w": "溷秽", "t": "肮脏污浊"}, {"w": "溷汁", "t": "污水;粪汁"}, {"w": "溷浊", "t": "肮脏。"}]}, {"meaning": "混乱。", "cites": [{"t": "世溷浊而嫉贤兮。", "b": "《楚辞·离骚》"}, {"t": "事类溷错,易为轻重。", "b": "《后汉书·陈宠传》"}], "words": [{"w": "溷杀", "t": "混杀一通;乱杀一气"}, {"w": "溷淆", "t": "溷肴,混乱,杂乱"}, {"w": "溷乱", "t": "混乱"}, {"w": "溷溷", "t": "乱;混浊。"}]}, {"meaning": "腐败。", "cites": [{"t": "谓随、夷溷兮,…。", "b": "《汉书·贾谊传》"}]}, {"meaning": "厕所。", "cites": [{"t": "落于粪溷之中。", "b": "《南史·范缜传》"}, {"t": "中丞匿于溷藩。", "b": "明·张溥《五人墓碑记》"}], "words": [{"w": "溷厕", "t": "厕所"}, {"w": "溷轩,溷厕,溷藩", "t": "厕所"}, {"w": "溷鼠", "t": "厕所里的老鼠。"}]}, {"meaning": "污秽物,粪便。", "cites": [{"t": "如此人材真屈辱,名花落溷恨难平。", "b": "秋瑾《精卫石》"}]}, {"meaning": "苟且过活,混日子。", "cites": [{"t": "亮今年本无甚事,但随分溷过,时节亦殊不觉。", "b": "陈亮《与陈君举》"}]}]}]','jingmo-wenyan');
