INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5578wx','滫','1','xiǔ','氵','13','','[{"pinyin": "xiǔ", "defs": [{"meaning": "淘米水。", "cites": [{"t": "兰根与白芷,渐之滫中。", "b": "《史记》"}], "words": [{"w": "滫瀡", "t": "淘米水。"}]}, {"meaning": "小便。", "cites": [{"t": "兰槐之根是为芷,其渐之滫,君子不近,庶人不服。", "b": "《荀子·劝学》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5579wx','溴','1','xiù','氵','13','','[{"pinyin": "xiù", "defs": [{"meaning": "一种主要为一价和七价的非金属元素,属卤素,通常为深红色的腐蚀性有毒液体,释放出难闻的红棕色刺激性蒸气,在自然界仅以化合状态微量地存在于海水中及很多盐湖、盐水及盐矿中 ——元素符号为 Br。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5580wx','滏','1','fǔ','氵','13','','[{"pinyin": "fǔ", "defs": [{"meaning": "古水名。即今滏阳河。源出河北省磁县西北石鼓山。", "cites": [{"t": "滏水出焉。", "b": "《山海经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5581wx','滃','1','wēng wěng','氵','13','','[{"pinyin": "wēng", "defs": [{"meaning": "滃江 ,水名。在广东。"}]}, {"pinyin": "wěng", "defs": [{"meaning": "大水沸涌的样子。", "cites": [{"t": "水耗初而釜治,火增壮而力均,滃嘈杂而廉清,信净美而甘分。", "b": "宋·苏轼《菜羹赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5582wx','滦','1','luán','氵','13','','[{"pinyin": "luán", "defs": [{"meaning": "水名,古名“濡水” 。在河北省东北部。发源于沽源县,上游北流入内蒙,名“闪电河”,又折向东南流入河北省,始称“滦河”,经滦平、承德、迁西、滦县入渤海。"}, {"meaning": "滦州 。五代的契丹分平州地置,因滦河得名。治所在义丰(今滦县),辖境相当于今河北省滦县、乐亭等县地。"}, {"meaning": "县名  。在河北省东部,京沈铁路和滦河经过县内。契丹置滦州,治所在义丰。公元1913年改为义丰县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5583wx','溏','1','táng','氵','13','','[{"pinyin": "táng", "defs": [{"meaning": "(形声。从水,唐声。本义:水池) ", "words": [{"w": "溏泺", "t": "池塘湖泊"}]}, {"meaning": "未凝固的,像糊状的", "words": [{"w": "溏泻", "t": "轻度腹泻"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5584wx','滂','1','pāng','氵','13','','[{"pinyin": "pāng", "defs": [{"meaning": "(形声。从水,旁声。本义:大水涌流)。"}, {"meaning": "同本义。", "cites": [{"t": "滂,沛也。", "b": "《说文》"}, {"t": "涕泗滂沱。", "b": "《诗·陈风·泽陂》"}, {"t": "观其两旁,则滂渤怫郁。", "b": "枚乘《七发》"}, {"t": "姱修滂浩。", "b": "《楚辞·大招》"}], "words": [{"w": "滂人", "t": "古时掌理池泽资源的官吏"}, {"w": "滂浩", "t": "水广大的样子"}, {"w": "滂流", "t": "大水盛流的样子"}, {"w": "滂溏", "t": "水流广大的样子"}, {"w": "滂滂", "t": "水流大的样子。"}]}, {"meaning": "倾盆大雨的。", "cites": [{"t": "滂濞沆溉。", "b": "《史记·司马相如传》"}], "words": [{"w": "滂霈", "t": "雨大的样子"}, {"w": "滂沲;滂澍", "t": "大雨"}, {"w": "滂泽", "t": "大雨。"}]}, {"meaning": "广大。", "cites": [{"t": "福滂洋。", "b": "《汉书·礼乐志》。注:“饶广也。”"}], "words": [{"w": "滂沲", "t": "广大的样子;充溢的样子"}, {"w": "滂洋", "t": "众多而广大"}, {"w": "滂浩", "t": "广大。"}]}, {"meaning": "旺盛的。", "cites": [{"t": "月丽于毕,俾滂沱矣。", "b": "《论衡·说日》"}], "words": [{"w": "滂洋", "t": "丰饶广阔。"}]}, {"meaning": "浇灌。", "cites": [{"t": "吾盗天地之时利,云雨之滂润,山泽之产育,以生吾禾。", "b": "《列子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5585wx','滓','1','zǐ','氵','13','','[{"pinyin": "zǐ", "defs": [{"meaning": "(形声。从水,宰声。本义:液体里下沉的杂质)。"}, {"meaning": "同本义。", "cites": [{"t": "滓,淀也。", "b": "《说文》。泥之黑者为滓,字亦作淄。"}, {"t": "化白于泥淄。", "b": "《太玄·更》。注:“黑也。”"}, {"t": "脉不粘肤,食不留滓。", "b": "刘峻《送橘启》"}, {"t": "滓方:以集诸滓,制如涤方,受五升。", "b": "唐·陆羽《茶经》"}], "words": [{"w": "滓方", "t": "收集茶叶渣的器具"}, {"w": "滓脚", "t": "渣子,渣末。"}]}, {"meaning": "用同“汁”。", "cites": [{"t": "行到灶前毛器具,目滓流落拭卖干。", "b": "《中国歌谣资料·福建歌谣》。原注:“目滓,眼泪。滓当‘汁’之声转。”"}]}, {"meaning": "污浊。", "cites": [{"t": "皦然泥而不滓者。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "滓敝", "t": "肮脏破烂"}, {"w": "滓淤", "t": "污泥;污浊的东西"}, {"w": "滓尘", "t": "污浊的尘世"}, {"w": "滓窳", "t": "污浊。"}]}, {"meaning": "沾污。", "cites": [{"t": "血滓太阿铓,看腥污髑髅囊。", "b": "郑若庸《玉玦记》"}], "words": [{"w": "滓污", "t": "污染"}, {"w": "滓秽太清", "t": "使天空受到污染。比喻玷污清明。"}]}, {"meaning": "污染;玷污。", "cites": [{"t": "司马太傅(道子)斋中夜坐,于时天月明净,都无纤翳,太傅叹以为隹。谢景重在座,答曰:“意谓乃不如微云点缀。”太傅因戏谢曰:“卿居心不净,乃复强欲滓秽太清耶?”", "b": "《世说新语·言语》"}, {"t": "岂可使芳杜厚颜,薜荔无耻,碧岭再辱,丹崖重滓!", "b": "《北山移文》"}], "words": [{"w": "滓秽", "t": "玷污。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5586wx','溟','1','míng','氵','13','','[{"pinyin": "míng", "defs": [{"meaning": "(形声。从水,冥声。本义:小雨濛濛)。"}, {"meaning": "同本义。", "cites": [{"t": "溟,小雨溟溟也。", "b": "《说文》"}, {"t": "密雨溟沐。", "b": "杨雄《太玄·少》。注:“雨之细者称溟沐。”"}], "words": [{"w": "溟沐", "t": "细雨的样子。"}]}, {"meaning": "暗昧,不明事理。", "cites": [{"t": "礼义廉耻不设,万民莫相侵暴虐,犹在于混溟之中也。", "b": "《文子·下德》"}]}, {"meaning": "海。", "cites": [{"t": "或倒景于重溟。", "b": "孙绰《游天台山赋》。注:“谓海也。”"}, {"t": "地势极而南溟深。", "b": "王勃《滕王阁序》"}], "words": [{"w": "东溟;溟岛", "t": "海中的小岛"}, {"w": "溟渤", "t": "传说中的“溟海”、“渤海”。泛指大海。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5587wx','滪','1','yù','氵','13','','[{"pinyin": "yù", "defs": [{"meaning": "——“滟滪堆”(Yǎnyù Duī):长江瞿塘峡口的巨石。1958年整治航道时炸平。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5588wx','愫','1','sù','忄','13','','[{"pinyin": "sù", "defs": [{"meaning": "诚意,真情实意。", "cites": [{"t": "披腹心,见情愫。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5589wx','慑','1','shè','忄','13','','[{"pinyin": "shè", "defs": [{"meaning": "(形声。从心,聂声。本义:恐惧)。"}, {"meaning": "同本义。", "cites": [{"t": "慑,失气也。", "b": "《说文》"}, {"t": "柔气不慑。", "b": "《礼记·乐记》。注:“犹恐惧也。”"}, {"t": "则志不慑。", "b": "《礼记·曲礼》。注:“犹怯惑也。”"}, {"t": "不至于隘慑伤生。", "b": "《荀子·礼论》"}, {"t": "贼连毙者三,气慑,扬帆去。", "b": "邵长蘅《阎典史传》"}, {"t": "使其心志安于斩刈杀伐之际而不慑。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "慑怯", "t": "畏惧"}, {"w": "慑气", "t": "因畏惧而屏住气息"}, {"w": "慑息", "t": "因害怕而不敢出声"}, {"w": "慑慑", "t": "有所畏惧而丧失勇气"}, {"w": "慑惮", "t": "畏惧忌惮"}, {"w": "慑怖", "t": "恐惧"}, {"w": "慑畏", "t": "畏惧"}, {"w": "慑愕", "t": "惊讶"}, {"w": "慑栗", "t": "恐惧战栗。"}]}, {"meaning": "威胁。", "cites": [{"t": "威动天地,声慑四海。", "b": "《淮南子·汜沦》"}], "words": [{"w": "慑服", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5590wx','慊','1','qiàn qiè','忄','13','','[{"pinyin": "qiàn", "defs": [{"meaning": "(形声。从心,兼声。(xián)本义:嫌疑)。"}, {"meaning": "同本义。", "cites": [{"t": "贵不慊于上者。", "b": "《礼记·坊记》"}, {"t": "婾得避慊之便。", "b": "《汉书·赵充国传》"}]}, {"meaning": "不足的。", "cites": [{"t": "慊,贫也。", "b": "《广雅》"}, {"t": "吾何慊乎哉?", "b": "《孟子·公孙丑下》"}, {"t": "宫室舆服,盖慊如也。", "b": "陆机《辩亡论》"}], "words": [{"w": "慊如", "t": "不足的样子"}, {"w": "慊然", "t": "不满足的样子"}, {"w": "慊慊", "t": "心不满足、心有嫌恨的样子。"}]}, {"meaning": "恨的,不满的。", "cites": [{"t": "贵不慊于上。", "b": "《礼记·坊记》。注:“慊,恨不满之貌也。”"}, {"t": "衣若县衰而意不慊。", "b": "《淮南子·齐俗》"}], "words": [{"w": "慊苦", "t": "遗憾怨苦"}, {"w": "慊恨", "t": "怨恨;遗憾。"}]}, {"meaning": "快心,满意。", "cites": [{"t": "行有不慊于心。", "b": "《孟子·公孙丑上》"}]}]}, {"pinyin": "qiè", "defs": [{"meaning": "", "words": [{"w": "慊心", "t": "快意;满意"}, {"w": "慊意", "t": "满意"}, {"w": "慊足", "t": "满足。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5591wx','鲎','1','hòu','鱼','13','','[{"pinyin": "hòu", "defs": [{"meaning": "鲎鱼。亦称中国鲎、东方鲎 。剑尾亚纲,特别是鲎目节肢动物的通称。有一个宽的新月形的头胸甲,在背面有一对大的复眼及两单眼,腹面生出六对步足,中部具一口,有一短小的腹部,腹部与头胸甲有关节相接,腹节愈合成一片,游泳足上附着扁平叶片状鳃,有一长而硬的可动关节的尾剑", "words": [{"w": "鲎帆", "t": "鲎鱼的脊背"}, {"w": "鲎杓", "t": "用鲎壳制成的杓子"}, {"w": "鲎媚", "t": "鲎鱼的别名"}, {"w": "鲎樽", "t": "用鲎壳制成的酒杯"}]}, {"meaning": "[方言] 虹的别称"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5592wx','骞','1','qiān','马','13','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从马,寒省声。本义:马腹病,指腹部亏损低陷)。"}, {"meaning": "同本义。", "cites": [{"t": "骞,马腹垫也。", "b": "《说文》。谓马腹低陷不充垫者,下也。"}, {"t": "闵子骞名损,或曰即左襄廿三传之闵子马。", "b": "《史记·弟子传》"}, {"t": "骞,马腹垫也。臣锴曰:腹病骞损。《诗》曰:“不骞不亏”。古人名损字骞。", "b": "五代·徐锴《说文系传》"}]}, {"meaning": "也指其他动物的肚腹低陷。", "cites": [{"t": "小体骞腹若是者,谓之羽属。", "b": "《周礼·考工记·梓人》。按,鸟形如孵,胸满而复陷。"}], "words": [{"w": "骞腹", "t": "马腹低陷。"}]}, {"meaning": "跛足。", "cites": [{"t": "尔羊来思,矜矜兢兢,不骞不崩。", "b": "《诗·小雅·无羊》"}]}, {"meaning": "惊惧。", "cites": [{"t": "人灵骞都野,鳞翰耸渊丘。", "b": "《文选·颜延年诗》"}]}, {"meaning": "延误。", "cites": [{"t": "惟昔李骞期。", "b": "刘越石《扶风歌》"}], "words": [{"w": "骞期", "t": "失期,约期而失信。"}]}, {"meaning": "损坏;亏损 。", "cites": [{"t": "不骞不崩。", "b": "《诗·小雅·天保》"}, {"t": "外无骞污之名。", "b": "《汉书·晁错传》"}], "words": [{"w": "骞污", "t": "亏损污辱"}, {"w": "骞崩", "t": "亏损坍圮"}, {"w": "骞短", "t": "亏损缺少。"}]}, {"meaning": "拔取。", "cites": [{"t": "非有斩将骞旗之实也。", "b": "《汉书·杨仆传》"}]}, {"meaning": "高举;飞起。", "cites": [{"t": "骞,飞也。", "b": "《广雅》"}, {"t": "王虺骞只。", "b": "《楚辞·大招》。注:“骞,举头貌也。”"}], "words": [{"w": "骞翥", "t": "展翅高飞的样子"}, {"w": "骞举", "t": "飞扬的样子"}, {"w": "骞骞", "t": "飞翔的样子;恣意放肆的样子"}, {"w": "骞腾", "t": "飞腾。"}]}, {"meaning": "过,误。", "cites": [{"t": "长夜漫兮,永思骞兮。", "b": "《荀子·正名》"}, {"t": "惟昔李骞期,寄在匈奴庭。", "b": "刘琨《扶风歌》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5593wx','窦','1','dòu','穴','13','','[{"pinyin": "dòu", "defs": [{"meaning": "(形声。从穴,卖声。本义:孔穴)。"}, {"meaning": "同本义。", "cites": [{"t": "窦,空也。", "b": "《说文》"}, {"t": "穿窦窖。", "b": "《礼记·月令》。注:“入地隋曰窦。”"}, {"t": "顺人情之大窦也。", "b": "《礼记·礼运》。注:“孔穴也。”"}, {"t": "在刑部狱,见死而由窦出者日三四人。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "窦径", "t": "洞穴和小路。"}]}, {"meaning": "门旁小户。", "cites": [{"t": "筚门闺窦之人而皆陵其上。", "b": "《左传》。杜预注:“闺窦,小户;穿壁为户,上锐下方,状如圭也。”"}]}, {"meaning": "泛指简陋门户。", "cites": [{"t": "荣族子敝,小随母养于宗中,及十二,自窦而走,至大街。", "b": "明·冯梦龙《智囊补》"}]}, {"meaning": "水沟,阴沟。", "cites": [{"t": "宫中之窦,其崇三尺。", "b": "《周礼》"}, {"t": "王闻变,易敝衣,匿水窦中,久而得之。", "b": "宋·周密《齐东野语》"}]}, {"meaning": "水道口。", "cites": [{"t": "不见四窦者,四窦,五岳之匹。", "b": "《周礼·春官·大宗伯》郑注"}, {"t": "窦,水沟口也。", "b": "五代·徐锴《说文解字系传》"}, {"t": "泽居苦水者,买庸而决窦。", "b": "《韩非子·五蠹》"}]}, {"meaning": "古州名。", "cites": [{"t": "窦州,汉苍梧郡地,唐武德五年置南扶州,贞观八年曰窦州。", "b": "清·顾祖禹《读史方舆纪要》"}]}, {"meaning": "溃决;穿通。", "cites": [{"t": "不防川,不窦泽。", "b": "《国语》。韦昭注:“窦,决也。”"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5594wx','窠','1','kē','穴','13','','[{"pinyin": "kē", "defs": [{"meaning": "(形声。从穴,果声。本义:筑在地洞里的鸟窝)。"}, {"meaning": "同本义。", "cites": [{"t": "窠,空也。一曰鸟巢也。空中曰窠,树上曰巢。", "b": "《说文》"}, {"t": "鸟鸢争食雀争窠。", "b": "白居易《问鹤》"}]}, {"meaning": "其他动物的巢穴。", "cites": [{"t": "鸠犬竟同窠。", "b": "周昂一《边俗诗》"}, {"t": "穴宅奇兽,窠宿异禽。", "b": "左思《蜀都赋》"}], "words": [{"w": "窠窟", "t": "动物栖身之所"}, {"w": "窠穴", "t": "鸟兽藏身之所。常喻指坏人聚居、活动的地方"}, {"w": "窠子", "t": "私娼的俗称"}, {"w": "窠棚", "t": "窝棚。"}]}, {"meaning": "人安居或聚会的处所。", "cites": [{"t": "抛却山中诗酒窠。", "b": "辛弃疾《鹧鸪天·三山道中》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5595wx','窣','1','sū','穴','13','','[{"pinyin": "sū", "defs": [{"meaning": "从穴中突然钻出来,引申为纵跃。", "cites": [{"t": "如闭目窣身入水,顷刻间耳。", "b": "宋·孔平仲《谈苑》"}]}, {"meaning": "拂。", "cites": [{"t": "垂露竹粘蝉落壳,窣云松载鹤栖巢。", "b": "唐·杜荀鹤《赠元上人》"}]}, {"meaning": "下垂 。如窣:窣静(幽寂;寂静);窣云(浮云)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5596wx','裱','1','biǎo','衤','13','','[{"pinyin": "biǎo", "defs": [{"meaning": "装潢书画的俗称。用纸、布或丝织物做衬托,衬糊在书画下面把书画等粘糊起来", "words": [{"w": "裱背", "t": "装潢字画"}, {"w": "裱工", "t": "裱褙书画的工匠"}, {"w": "裱手", "t": "裱褙的技艺"}]}, {"meaning": "用纸糊饰屋子的内部或物件", "words": [{"w": "裱糊店", "t": "经营裱糊业的店铺"}, {"w": "裱糊匠", "t": "以裱糊为业的工人"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5597wx','褚','1','chǔ zhě zhǔ','衤','13','','[{"pinyin": "chǔ", "defs": [{"meaning": "姓。"}]}, {"pinyin": "zhě", "defs": [{"meaning": "古代称兵卒。", "cites": [{"t": "褚,卒也。", "b": "《说文》。徐灏曰:“卒谓之褚者,因其着赭衣而名之也。”"}], "words": [{"w": "褚伍", "t": "褚五。泛指军队;行伍。"}]}]}, {"pinyin": "zhǔ", "defs": [{"meaning": "把丝棉装入衣服。", "cites": [{"t": "褚,一曰装衣。", "b": "《说文》"}, {"t": "置荀罃褚中。", "b": "《左传·成公三年》"}, {"t": "以锦装衣曰褚。", "b": "《汉书·南粤王传》注"}, {"t": "褚,装衣也。", "b": "《玉篇》"}]}, {"meaning": "储藏", "cites": [{"t": "取我衣冠而褚之。", "b": "《左传·襄公三十年》"}]}, {"meaning": "丝绵衣服。", "cites": [{"t": "上褚五十衣,中褚三十衣,下褚二十衣遗王。", "b": "《汉书·南越王赵佗传》"}], "words": [{"w": "褚衣", "t": "绵衣。"}]}, {"meaning": "囊,袋。", "cites": [{"t": "有商人置诸褚中,展转入东林。", "b": "《南史》"}], "words": [{"w": "褚橐", "t": "褚囊。盛书的袋子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5598wx','裨','1','bì pí','衤','13','','[{"pinyin": "bì", "defs": [{"meaning": "弥补;补助。", "cites": [{"t": "裨,接益也。", "b": "《说文》"}, {"t": "若以同裨同。", "b": "《国语·郑语》。注:“益也。”"}, {"t": "裨辅先君、裨诸侯之阙。", "b": "《国语·晋语》。注:“补也。”"}, {"t": "必能裨补阙漏,有所广益。", "b": "诸葛亮《出师表》"}], "words": [{"w": "裨正", "t": "裨补匡正"}, {"w": "裨益", "t": "补益;益处。"}]}]}, {"pinyin": "pí", "defs": [{"meaning": "(形声。从衣,卑声。本义:古代祭祀大夫所穿的一种次等礼服) 同本义。", "cites": [{"t": "裨,衣别也。", "b": "《说文》"}, {"t": "侯氏裨冕。", "b": "《仪礼·觐礼》。注:“天子六服,大裘为上,其余为裨,以事尊卑服之,而诸侯亦服焉。”"}, {"t": "裨冕鴵搢笏。", "b": "《礼记·乐记》。注:“衣衮之属也。”"}, {"t": "裨冕以朝。", "b": "《礼记·玉藻》"}], "words": [{"w": "裨衣", "t": "古代帝王所穿的次等礼服;又诸侯的礼服也叫裨衣"}, {"w": "裨冕", "t": "着裨衣,戴冕。古代诸侯卿大夫朝觐或祭祀时所穿冕服的通称。与衮冕或上一等冕服相对而言。"}]}, {"meaning": "副佐。", "cites": [{"t": "豫州授以裨师。", "b": "《文选·为袁绍檄》"}], "words": [{"w": "裨师", "t": "一部分军队。即偏师"}, {"w": "裨附", "t": "裨辅。辅佐"}, {"w": "裨赞", "t": "辅助"}, {"w": "裨属", "t": "佐属"}, {"w": "裨将军", "t": "副将军。"}]}, {"meaning": "引申为小。", "cites": [{"t": "于是有裨海王不之。", "b": "《史记·孟荀传》"}, {"t": "得右贤裨王十余人。", "b": "《汉书·卫青传》"}], "words": [{"w": "裨王", "t": "汉时称匈奴的小王"}, {"w": "裨海", "t": "小海"}, {"w": "裨贩", "t": "小贩。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5599wx','裾','1','jū','衤','13','','[{"pinyin": "jū", "defs": [{"meaning": "衣服的前后襟。", "cites": [{"t": "裾,衣袌也。从衣,居声。", "b": "《说文》"}, {"t": "裾,衣之前襟也。今苏俗曰大襟。", "b": "《说文通训定声》"}, {"t": "楚庄王裾衣博袍。", "b": "《淮南子·齐俗》"}]}, {"meaning": "傲慢。", "cites": [{"t": "彼浩裾自顺,不可以教下。", "b": "《晏子春秋·外篇》"}, {"t": "其流也埤下,裾拘必循其理,似义。", "b": "《荀子·宥坐》"}, {"t": "[赵禹]为人廉裾。", "b": "《汉书·赵禹传》。颜师古注:“裙亦傲也。”"}]}]}]','jingmo-wenyan');
