('5601wx','禊','1','xì','礻','13','','[{"pinyin": "xì", "defs": [{"meaning": "古代于春秋两季在水边举行的一种祭礼。", "cites": [{"t": "武帝禊霸上还。", "b": "《史记》"}], "words": [{"w": "禊日", "t": "禊事活动之日"}, {"w": "禊祭", "t": "古人在春秋二季所举行的临水祓除不详的祭事。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5602wx','谩','1','mán màn','讠','13','','[{"pinyin": "mán", "defs": [{"meaning": "(形声。从言,曼声。本义:瞒哄;欺骗)。"}, {"meaning": "同本义。", "cites": [{"t": "谩,欺也。", "b": "《说文》"}, {"t": "虔儇,慧也。秦谓之谩。", "b": "《方言一》"}, {"t": "偝则谩之。", "b": "《荀子·非相》。注:“谩,欺毁也。”"}, {"t": "是面谩也。", "b": "《汉书·匈奴传》"}], "words": [{"w": "谩欺", "t": "欺骗,诈骗"}, {"w": "谩语", "t": "谎言,说谎"}, {"w": "谩上不谩下", "t": "能欺骗上级,但不能欺骗众人"}, {"w": "谩辞", "t": "欺诳的言辞"}, {"w": "谩言", "t": "讲假话。"}]}, {"meaning": "抵赖。", "cites": [{"t": "民或祝诅上,以相约结而后相谩,吏以为大逆。", "b": "《史记·孝文本纪》"}]}]}, {"pinyin": "màn", "defs": [{"meaning": "毁谤;谩骂。", "cites": [{"t": "乡则不若,偝则谩之,是人之二必穷也。", "b": "《荀子·非相》"}, {"t": "媠谩亡状。", "b": "《汉书·两龚传》"}]}, {"meaning": "莫,不要。", "cites": [{"t": "谩叹息,谩悒怏。", "b": "金·董解元《西厢记诸宫调》"}], "words": [{"w": "谩言", "t": "休说"}, {"w": "谩道", "t": "休说,别说"}, {"w": "谩且", "t": "休得,莫。"}]}, {"meaning": "轻慢,对人不尊重。", "cites": [{"t": "轻谩宰相。", "b": "《汉书·翟方进传》"}, {"t": "故桀纣暴谩。", "b": "《汉书·董仲舒传》"}, {"t": "长书有誖谩。", "b": "《汉书·外戚传》"}], "words": [{"w": "谩君", "t": "轻慢、失礼之君"}, {"w": "谩书", "t": "态度轻慢的文书。"}]}, {"meaning": "不切实,散漫。", "cites": [{"t": "太谩,愿闻其要。", "b": "《庄子·天道》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5603wx','谪','1','zhé','讠','13','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。从言,啻(chì)声。本义:有意指摘,责备)。"}, {"meaning": "同本义。", "cites": [{"t": "谪,罚也。", "b": "《说文》"}, {"t": "罚罪者曰谪。", "b": "《通俗文》"}, {"t": "国子谪我。", "b": "《左传·成公十七年》"}, {"t": "则自取谪于日月之灾。", "b": "《左传·昭公七年》"}, {"t": "善言无瑕谪。", "b": "《老子》"}, {"t": "穷年不相谪发。", "b": "《列子·力命》"}, {"t": "公会齐侯于泺,遂及文姜如齐。齐侯通焉。公谪之。", "b": "《左传·桓公十八年》"}, {"t": "室人交遍谪我。", "b": "《诗·邶风·北门》"}], "words": [{"w": "谪疑", "t": "指摘怀疑"}, {"w": "谪我", "t": "谴责我"}, {"w": "谪骂", "t": "责骂"}, {"w": "谪谴", "t": "谴责"}, {"w": "众口交谪", "t": ""}]}, {"meaning": "降职并外放。", "cites": [{"t": "谊既以谪去,意不自得。", "b": "《汉书·贾谊传》"}, {"t": "谪守巴陵郡。", "b": "范仲淹《岳阳楼记》"}, {"t": "只因劝酒蟠桃会,误犯天条谪翠微。", "b": "《封神演义》"}], "words": [{"w": "谪降", "t": "降级下放到边远地方"}, {"w": "谪发", "t": "发配边疆"}, {"w": "谪官", "t": "谪宦。谪吏。被贬降的官吏。"}]}, {"meaning": "被罚戍边的罪人。", "cites": [{"t": "徙谪实之初县。", "b": "《史记·秦始皇本纪》"}]}, {"meaning": "缺点;过失。", "cites": [{"t": "善言无瑕谪。", "b": "《老子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5604wx','媾','1','gòu','女','13','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从女,冓(góu)声。本义:交互为婚姻,亲上结亲)。"}, {"meaning": "同本义。", "cites": [{"t": "媾,重婚也。", "b": "《说文》"}, {"t": "今将婚媾以从秦。", "b": "《国语·晋语》"}]}, {"meaning": "恢复亲善友好的关系,讲和,交好。", "cites": [{"t": "媾,和好也。", "b": "《正字通》"}, {"t": "无益也,不如发重使为媾。", "b": "《史记·平原君虞卿列传》"}, {"t": "楼缓言不媾,来年秦复攻,王得无更割其内而媾!", "b": "《战国策·赵策》"}], "words": [{"w": "媾和", "t": ""}]}, {"meaning": "厚爱,宠爱。", "cites": [{"t": "彼其之了,不遂其媾。", "b": "《诗·曹风·侯人》"}]}]}]','jingmo-wenyan');
