INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5608wx','嫔','1','pín','女','13','','[{"pinyin": "pín", "defs": [{"meaning": "(形声。从女,宾声。本义:帝王的女儿出嫁)。"}, {"meaning": "同本义。", "cites": [{"t": "嫔,服也。谓服事人者。", "b": "《说文》"}, {"t": "嫔妇也。", "b": "《尔雅》"}, {"t": "厘降二女于妫汭,嫔于虞。", "b": "《书·尧典》"}, {"t": "七月嫔妇。", "b": "《周礼·大宰》"}]}, {"meaning": "跟从。", "cites": [{"t": "日嫔月随。", "b": "《太玄·从》"}]}, {"meaning": "帝王诸侯的姬妾。", "cites": [{"t": "九妃六嫔。", "b": "《国语·齐语》"}, {"t": "妃嫔媵嫱,王子皇孙。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "嫔妃", "t": "帝王的女官和侍妾"}, {"w": "嫔媵", "t": "嫔妾"}, {"w": "嫔御", "t": "古代帝王、诸侯的侍妾与宫女"}, {"w": "嫔娥", "t": "宫中的姬妾与宫女"}, {"w": "嫔妾", "t": "宫嫔、侍妾"}, {"w": "嫔妓", "t": "姬妾与歌舞女艺人。"}]}, {"meaning": "对亡妻的美称。", "cites": [{"t": "生曰妻,死曰嫔。", "b": "《礼记·曲礼》"}, {"t": "婉彼幽闲女,作嫔君子室。", "b": "颜延之《秋胡诗》"}]}, {"meaning": "众多。", "cites": [{"t": "嫔然成行。", "b": "《汉书·王莽传》"}], "words": [{"w": "嫔然", "t": "众多的样子。"}]}]}]','jingmo-wenyan');
