INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5610wx','缙','1','jìn','纟','13','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关。晋声。本义:赤色帛) 同本义。", "cites": [{"t": "缙,帛赤色也。", "b": "《说文》"}, {"t": "缙云氏有不才子礼有缙缘。", "b": "《左传·文公十八年》"}, {"t": "缙绅而无钩带矣。", "b": "《荀子·礼论》"}, {"t": "其语不经见,缙绅者弗道。", "b": "《汉书·郊祀志上》"}], "words": [{"w": "缙绅便览", "t": "古代的官吏名录"}, {"w": "缙云", "t": "黄帝时官名。黄帝以云名官,夏官为缙云氏,因以为族氏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5611wx','缜','1','zhěn','纟','13','','[{"pinyin": "zhěn", "defs": [{"meaning": "(形声。从糸(mì),真声。糸,细丝。本义:细致)。"}, {"meaning": "同本义。", "cites": [{"t": "缜密以栗。", "b": "《礼记·聘义》"}, {"t": "累居显职,性缜密,未尝言禁中事。", "b": "《南史》"}, {"t": "两崖石壁宛转,色转缜润。", "b": "《徐霞客游记》"}], "words": [{"w": "缜密行藏", "t": "小心谨慎,行踪机密"}, {"w": "缜致", "t": "细密"}, {"w": "缜匝", "t": "周密"}, {"w": "缜润", "t": "细密润泽。"}]}, {"meaning": "黑。", "cites": [{"t": "缜,黑也。", "b": "《广雅·释器》。"}], "words": [{"w": "缜发", "t": "黑发。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5612wx','缛','1','rù','纟','13','','[{"pinyin": "rù", "defs": [{"meaning": "(形声。从糸(mì),辱声。本义:繁密的彩饰)。"}, {"meaning": "同本义。", "cites": [{"t": "缛,繁采色也。", "b": "《说文》"}, {"t": "绸缪缛绣。", "b": "左思《吴都赋》"}], "words": [{"w": "缛旨", "t": "繁饰的文旨"}, {"w": "缛丽", "t": "繁饰华丽"}, {"w": "缛绣", "t": "彩色繁丽,有如锦绣。"}]}, {"meaning": "烦琐;对…阐述过详。", "cites": [{"t": "文有粗缛。", "b": "《周礼·大宗伯》注"}], "words": [{"w": "缛礼烦仪", "t": "烦琐的礼仪"}, {"w": "繁文缛节", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5613wx','辔','1','pèi','车','13','','[{"pinyin": "pèi", "defs": [{"meaning": "(会意。从丝,从軎。从丝,与绳索有关。軎:wèi,套在车轴末端的金属制圆筒状物,上有穿口,用以纳辖。本义:驾驭牲口用的缰绳)。"}, {"meaning": "同本义。", "cites": [{"t": "辔,马縻也。", "b": "《说文》"}, {"t": "执辔如组。", "b": "《诗·邶风·简兮》"}, {"t": "执策分辔。", "b": "《礼记·曲礼》。疏:“御马索也。”"}, {"t": "公子执辔愈恭。", "b": "《史记·魏公子列传》"}, {"t": "或揽辔寒帷。", "b": "清·周容《芋老人传》"}], "words": [{"w": "辔勒", "t": "控制马的缰绳和口勒"}, {"w": "辔衔", "t": "马缰绳和马嚼子"}, {"w": "辔策", "t": "御马的缰绳和马鞭"}, {"w": "辔靷", "t": "御马的缰绳和引车前行的皮带。"}]}, {"meaning": "喻法令 。从辔(遵循法令)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5614wx','骝','1','liú','马','13','','[{"pinyin": "liú", "defs": [{"meaning": "黑鬣、黑尾巴的红马。泛指骏马", "words": [{"w": "骝驹", "t": "赤身黑鬣的马"}, {"w": "骝驳", "t": "马的毛色有黄有白。指毛色不纯"}, {"w": "骝马", "t": "黑鬣、黑尾的红马"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5615wx','缟','1','gǎo','纟','13','','[{"pinyin": "gǎo", "defs": [{"meaning": "((gǎo)形声。从糸(mì),表示与线丝有关,高声。本义:细白的生绢) 同本义。", "cites": [{"t": "缟,鲜色也。", "b": "《说文》。按,鲜色当作鲜巵。熟帛曰练,生帛曰缟。"}, {"t": "厥篚元纤缟。", "b": "《书·禹贡》。传:“白缯。”"}, {"t": "与之缟带。", "b": "《左传·襄公二十九年》"}, {"t": "缯之精者曰缟。", "b": "《小尔雅》"}, {"t": "鲁人身善织屦,妻善织缟。", "b": "《韩非子·说林上》"}, {"t": "乘坚策肥,履丝曳缟。", "b": "晁错《论贵粟疏》"}, {"t": "曹操之众,远来疲敝,闻追豫州,轻骑一日一夜行三百余里,此所谓“强弩之末势不能穿鲁缟”者也。", "b": "《资治通鉴》"}], "words": [{"w": "缟袂", "t": "白色绢衣。用以喻白海棠"}, {"w": "缟衣綦巾", "t": "白绢上衣与浅绿色围裙。古时女子所服"}, {"w": "缟冠", "t": "白色生绢制的帽子"}, {"w": "缟练", "t": "白绢。"}]}, {"meaning": "白色。", "cites": [{"t": "其上台观皆金玉,其上禽兽皆纯缟。", "b": "《列子·汤问》"}, {"t": "缟,素也。", "b": "《小尔雅·广诂》"}, {"t": "缟衣綦巾。", "b": "《诗·郑风·出其东门》"}, {"t": "兵皆缟素。", "b": "《汉书·高帝纪》。注:“白也。”"}, {"t": "天下缟素。", "b": "《战国策·魏策》"}, {"t": "帝缟素避正殿。", "b": "《后汉书·顺帝纪》"}, {"t": "眄隰则万顷同缟,瞻山则千岩俱白。", "b": "南朝宋·谢惠连《雪赋》"}], "words": [{"w": "缟巾", "t": "白色头巾"}, {"w": "缟带", "t": "白色的绢带。喻指雪的洁白"}, {"w": "缟羽", "t": "白羽"}, {"w": "缟衣", "t": "白色男服"}, {"w": "缟武", "t": "白色帽檐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5616wx','缡','1','lí','纟','13','','[{"pinyin": "lí", "defs": [{"meaning": "用丝装饰鞋头。", "cites": [{"t": "缡,以丝介履也。", "b": "《说文》。段玉裁注:“介者画也,谓以丝介画履间为饰也"}]}, {"meaning": "古时妇女系在身前的大佩巾。", "cites": [{"t": "亲结其缡。", "b": "《诗·豳风·东山》"}], "words": [{"w": "结缡", "t": "古称女子出嫁。"}]}, {"meaning": "带子 。指系冠的带子。", "cites": [{"t": "缡,婑也。", "b": "《尔雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5617wx','缢','1','yì','纟','13','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从糸(mì),益声。从糸,与丝绳有关。本义:吊死)。"}, {"meaning": "同本义。", "cites": [{"t": "缢,绞也。", "b": "《说文》。段注:“绞缢必两股辫为之。…缢死必两股为之,以其直悬也,故亦谓之经”"}, {"t": "十四年春,孔达缢而死。", "b": "《左传·宣公十四年》"}, {"t": "莫敖缢于荒谷。", "b": "《左传·桓公十三年》"}, {"t": "自缢于庭树。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "缢死", "t": "用绳索,布条等套绕颈上挂于高处气绝而死。也称吊死"}, {"w": "缢鬼", "t": "吊死者的鬼魂。"}]}, {"meaning": "用绳子勒颈绝气而死。", "cites": [{"t": "缢而弑之。", "b": "《左传·昭公元年》"}, {"t": "缢即气绝。", "b": "清·方苞《狱中杂记》"}, {"t": "缢加别械。", "b": ""}], "words": [{"w": "缢杀", "t": "勒人之颈使之死。"}]}]}]','jingmo-wenyan');
