INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5620wx','耥','1','tǎng','耒','14','','[{"pinyin": "tǎng", "defs": [{"meaning": "又名“稻耥”、“耥耙”、“耘耥” 。用于水稻田中的耕耘农具,耥体为屐形木块或木框,置有耙齿,用于推耥穴,行间草泥,使之溷溺。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5621wx','璈','1','áo','王','14','','[{"pinyin": "áo", "defs": [{"meaning": "古乐器名。", "cites": [{"t": "灵璈清以集鸾。", "b": "袁桷《桐柏观赋》"}], "words": [{"w": "璈管", "t": "弦管。指美乐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5622wx','瑶','1','yáo','王','14','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。从玉,本义:似玉的美石)。"}, {"meaning": "同本义。亦泛指美玉。", "cites": [{"t": "瑶,石之美者。", "b": "《说文》"}, {"t": "赂以瑶瓮。", "b": "《左传·昭公七年》"}, {"t": "瑶爵。", "b": "《周礼·内宰》"}, {"t": "厥贡惟金三品,瑶琨、", "b": "《书·禹贡》。孔传:“瑶、琨皆美玉。”"}, {"t": "何以舟之, 维玉及瑶。", "b": "《诗·大雅·公刘》"}], "words": [{"w": "瑶琴", "t": "用美玉装饰的琴,泛指精美贵重的乐器"}, {"w": "瑶佩", "t": "美玉制成的佩饰"}, {"w": "瑶华", "t": "美玉。"}]}, {"meaning": "瑶族 的简称。主要居住在中国西南部、泰国北部、老挝和北部湾等地山区的一个民族。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5623wx','瑭','1','táng','王','14','','[{"pinyin": "táng", "defs": [{"meaning": "一种玉。", "cites": [{"t": "瑭碧坚忍之类,犹可刻镂,以成器用。", "b": "《淮南子》。高诱注:“唐碧,石似玉。唐与瑭通。”"}]}]}]','jingmo-wenyan');
