('5624wx','獒','1','áo','犬','14','','[{"pinyin": "áo", "defs": [{"meaning": "一种高大、凶猛、垂耳、短毛的家犬,主要用于看门或警戒。", "cites": [{"t": "公嗾夫獒焉,明搏而杀之。", "b": "《左传·宣公二年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5625wx','觏','1','gòu','见','14','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从见,冓(gōu)声。本义:遇,遇见;看见)。"}, {"meaning": "同本义。", "cites": [{"t": "觏,遇见也。", "b": "《说文》"}, {"t": "亦既觏止。", "b": "《诗·召南·草虫》"}, {"t": "我觏之子。", "b": "诗·豳风·伐柯》"}, {"t": "乃觏于京。", "b": "《诗·大雅·公刘》"}, {"t": "忧心悄悄,愠于群小。觏闵既多,受侮不少。", "b": "《诗·邶风·柏舟》"}], "words": [{"w": "觏闵", "t": "遭遇不幸"}, {"w": "觏晤", "t": "会面"}, {"w": "觏面", "t": "见面"}, {"w": "觏止", "t": "相遇。"}]}, {"meaning": "构成", "cites": [{"t": "郇瑕氏土薄水浅,其恶易觏。", "b": "《左传·成公六年》"}], "words": [{"w": "觏恶", "t": "构成疾疢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5626wx','慝','1','tè','心','14','','[{"pinyin": "tè", "defs": [{"meaning": "(会意。从匿,从心。匿(nì),隐藏。把心隐藏起来,存有邪念。本义:邪恶,恶念)。"}, {"meaning": "同本义。", "cites": [{"t": "崇谗慝也。", "b": "《尔雅》。释文:“慝,言隐匿其情以饰非。”"}, {"t": "察军慝。", "b": "《周礼·环人》。注:“慝,阴奸也。”"}, {"t": "于是展氏有隐慝焉。", "b": "《左传·僖公十五年》。注:“阴恶,非法所得。”"}, {"t": "日入慝作。", "b": "《左传·昭公二十五年》。注:“奸恶也。”"}, {"t": "匡邦国而观其慝。", "b": "《周礼·匡人》。注:“奸伪之恶也。”"}, {"t": "天子端然少旁求,股肱耳目皆奸慝。", "b": "唐·刘叉《雪车》"}], "words": [{"w": "慝人", "t": "邪恶的人"}, {"w": "慝作", "t": "奸恶之人乘机而起"}, {"w": "慝伪", "t": "奸伪"}, {"w": "慝礼", "t": "不正之礼。"}]}, {"meaning": "灾害。", "cites": [{"t": "以伏蛊慝。", "b": "《国语》"}]}, {"meaning": "恶人;坏人。", "cites": [{"t": "如此,则国平而民无慝矣。", "b": "《管子》"}]}, {"meaning": "阴气。", "cites": [{"t": "唯正月之朔,慝未作。", "b": "《左传》注:“慝,阴气也。”疏:“人情爱阳而恶阴,故谓阴为慝。”"}]}, {"meaning": "瘴气蛊毒之类。", "cites": [{"t": "道地慝。", "b": "《周礼·土训》。注:“地慝,若障蛊然也。”司农注:“地所生恶物害人者。若虺蝮之属。”"}]}, {"meaning": "禁讳的语言。", "cites": [{"t": "掌道方慝,以诏辟忌,以知地俗。", "b": "《周礼》。郑玄注:“方慝,四方言语所恶也。”"}]}, {"meaning": "差错。", "cites": [{"t": "有过慝之度。", "b": "《国语》"}]}, {"meaning": "变更,差错", "cites": [{"t": "之死矢靡慝。", "b": "《诗·鄘风·伯舟》"}, {"t": "岂曰不极?伊胡为慝!", "b": "《诗·大雅·瞻卬》"}, {"t": "有过慝之度。", "b": "《国语·周语下》"}, {"t": "人用侧颇辟,民用僭慝。", "b": "《汉书·王嘉传》。颜师古云:“慝,恶也。”"}]}, {"meaning": "隐藏。", "cites": [{"t": "隐慝良道,而不相教诲。", "b": "《墨子·尚贤下》"}, {"t": "朔而月见东方,谓之仄慝。", "b": "《汉书·五行志下之下》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5627wx','嫠','1','lí','女','14','','[{"pinyin": "lí", "defs": [{"meaning": "寡妇(上古时期,寡可指寡妇和寡夫,而嫠只指寡妇)。", "cites": [{"t": "嫠也何害,先夫当之矣。", "b": "《左传·襄公二十五年》"}, {"t": "舞幽壑之潜蛟,泣孤舟兮嫠妇。", "b": "苏轼《赤壁赋》"}], "words": [{"w": "嫠人", "t": "寡妇"}, {"w": "嫠家", "t": "寡妇自称"}, {"w": "嫠妇", "t": "寡妇"}, {"w": "嫠节", "t": "寡妇的名节"}, {"w": "嫠独", "t": "寡妇和鳏夫"}, {"w": "嫠忧", "t": "喻忧国"}, {"w": "嫠辍纬", "t": "忧国心切。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5628wx','韬','1','tāo','韦','14','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从韦,舀(yǎo)声。韦,熟皮。本义:剑套)。"}, {"meaning": "同本义。", "cites": [{"t": "韬,剑衣也。", "b": "《说文》"}]}, {"meaning": "装弓的袋子。", "cites": [{"t": "韬,弓衣也。", "b": "陆德明《经典释文》"}]}, {"meaning": "用兵的计谋。", "cites": [{"t": "不劳孙子法,自得太公韬。", "b": "李德裕《李文饶集》"}], "words": [{"w": "韬钤", "t": "用兵的谋略"}, {"w": "韬略", "t": "指军事上的谋略。"}]}, {"meaning": "掩藏。", "cites": [{"t": "韬舌辱壮志,叫阍无助声。", "b": "杜牧《感怀诗一首》"}], "words": [{"w": "韬光晦迹,韬光讳彩", "t": "收敛锋芒;隐藏踪迹"}, {"w": "韬日", "t": "日光隐藏"}, {"w": "韬世", "t": "比喻度量之大,足以容世"}, {"w": "韬光", "t": "收敛光彩,比喻人怀才不露"}, {"w": "韬沉", "t": "隐逸"}, {"w": "韬含", "t": "谙记,熟诸"}, {"w": "韬表", "t": "弥封书表"}, {"w": "韬面", "t": "遮面。"}]}, {"meaning": "纳弓于弓袋。", "cites": [{"t": "韬,弓藏也。", "b": "《广雅·释器》"}], "words": [{"w": "韬弓", "t": "纳弓入弓套。"}]}, {"meaning": "包容。", "cites": [{"t": "有韬世之量。", "b": "潘岳《寡妇赋》"}], "words": [{"w": "韬世", "t": "度量大"}, {"w": "韬合", "t": "包容切合"}, {"w": "韬涵", "t": "包含。"}]}, {"meaning": "宽;缓。", "cites": [{"t": "[梁元帝] 常言:“我韬于文士,愧于武夫。”", "b": "《资治通鉴》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5629wx','叆','1','ài','厶','14','','[{"pinyin": "ài", "defs": [{"meaning": "云盛的样子。", "cites": [{"t": "云覆日为叆叇。", "b": "《通俗文》"}, {"t": "叆叇云布。", "b": "木华《海赋》。"}], "words": [{"w": "叆叇", "t": "浓云密布的样子;又指昏暗不明的样子"}, {"w": "叆叆", "t": "浓郁盛多的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5630wx','髦','1','máo','髟','14','','[{"pinyin": "máo", "defs": [{"meaning": "(会意。从髟(biāo),从毛。髟,长发下垂的样子。本义:毛发中的长毫)。"}, {"meaning": "同本义。", "cites": [{"t": "髦,发中毫者也。", "b": "唐·玄应《一切经音义》"}, {"t": "髦,发也。", "b": "《说文》。按,汉书所谓壮发。"}, {"t": "如狸而有髦。", "b": "《山海经·南山经》"}]}, {"meaning": "某些哺乳动物颈部周围生长的又长又密的毛。", "cites": [{"t": "乘髦马。", "b": "《礼记·曲礼》"}]}, {"meaning": "刘海。", "cites": [{"t": "髧彼两髦。", "b": "《诗·鄘风·柏舟》。注:“髦者,发至眉。子事父母之饰。”"}]}, {"meaning": "", "cites": [{"t": "取其…髦牛,以此巴蜀殷富。", "b": "《史记·西南夷列传》"}]}, {"meaning": "", "cites": [{"t": "建云髦启雄芒。", "b": "张协《七命》"}]}, {"meaning": "英俊。", "cites": [{"t": "髦,俊也。", "b": "《尔雅》"}, {"t": "誉髦斯士。", "b": "《诗·大雅·思齐》"}, {"t": "烝我髦士。", "b": "《诗·小雅·甫田》"}, {"t": "髦士攸宜。", "b": "《仪礼·士冠礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5631wx','摽','1','biāo biào','扌','14','','[{"pinyin": "biāo", "defs": [{"meaning": "挥之使去。", "cites": [{"t": "摽使者出诸大门之外。", "b": "《孟子》"}]}, {"meaning": "抛弃。", "cites": [{"t": "已盟,曹子摽剑而去之。", "b": "《公羊传·庄公十三年》"}]}]}, {"pinyin": "biào", "defs": [{"meaning": "捶胸;击。", "cites": [{"t": "摽,击也。从手,票声。字亦作抛。", "b": "《说文》"}, {"t": "寤辟有摽。", "b": "《诗·柏舟》"}, {"t": "长木之斃,无不摽也。", "b": "《左传·哀公十二年》"}], "words": [{"w": "摽辟", "t": "捶胸。"}]}, {"meaning": "落下。", "cites": [{"t": "摽有梅,其实七兮。", "b": "《诗·召南·摽有梅》"}], "words": [{"w": "摽落", "t": "落下"}, {"w": "摽梅", "t": "梅子成熟而落下,比喻女子应当结婚的年龄。"}]}, {"meaning": "捆绑或互相缠绕在一起 。如:把口袋摽在车架子上。引申为结合。如:大伙摽成了一股劲;他们老摽在一起。"}]}]','jingmo-wenyan');
