('5633wx','撂','1','liào','扌','14','','[{"pinyin": "liào", "defs": [{"meaning": "(形声。从手,略声。本义:撇开,搁下,丢开)。"}, {"meaning": "同本义。", "cites": [{"t": "难道我上学去,撂得你们冷清了不成?", "b": "《红楼梦》"}]}, {"meaning": "放,丢。", "cites": [{"t": "我的东西还没处撂呢?", "b": "《红楼梦》"}], "words": [{"w": "撂担子", "t": "丢下担子"}, {"w": "撂过手", "t": "放过不问"}, {"w": "撂开手", "t": "分手;撒手不管"}, {"w": "撩东挝西", "t": "乱拉乱扔。"}]}]}]','jingmo-wenyan');
