('5635wx','撄','1','yīng','扌','14','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从手,婴声。本义:扰乱,干扰)。"}, {"meaning": "同本义。", "cites": [{"t": "不以人物利害相撄。", "b": "《庄子·庚桑楚》"}], "words": [{"w": "撄宁", "t": "外物的扰乱"}, {"w": "撄心", "t": "扰乱心神。"}]}, {"meaning": "缠绕。", "cites": [{"t": "勿挠勿撄,万物将自称。", "b": "《淮南子》。高诱注:“撄,缨也。”"}], "words": [{"w": "撄城", "t": "环城"}, {"w": "撄挽", "t": "纠缠。"}]}, {"meaning": "触犯。", "cites": [{"t": "杀害既多,必撄鬼神之怒。", "b": "《绿野仙踪》"}], "words": [{"w": "撄怒", "t": "触怒"}, {"w": "撄拂", "t": "触犯,拂逆"}, {"w": "撄鳞", "t": "喻触怒帝王。"}]}, {"meaning": "触。", "cites": [{"t": "事势至此,陛下且忍之,不可撄其锋也。", "b": "《三国演义》"}], "words": [{"w": "撄宁", "t": "接触外物而不为所动,保持心神宁静"}, {"w": "撄锋", "t": "触碰锋镝。"}]}, {"meaning": "向…挑战或撩斗。", "cites": [{"t": "虎负嵎,莫之敢撄。", "b": "《孟子》"}]}]}]','jingmo-wenyan');
