('5637wx','踅','1','xué','足','14','','[{"pinyin": "xué", "defs": [{"meaning": "盘旋。", "cites": [{"t": "四野风来,左右乱踅。", "b": "《西厢记》"}], "words": [{"w": "踅蹬", "t": "人上马时即打旋。"}]}, {"meaning": "转,折身转去。", "cites": [{"t": "顾大嫂一踅,踅下亭心边去。", "b": "《水浒全传》"}], "words": [{"w": "踅入", "t": "转入;迈进"}, {"w": "踅身", "t": "转身"}, {"w": "踅转", "t": "折回;折转。"}]}, {"meaning": "来回走。", "cites": [{"t": "顾大嫂拿了两把大刀在堂前踅。", "b": "《水浒全传》"}, {"t": "这婆子正开门,在茶局子里整理茶锅,张见西门庆踅过几遍。", "b": "《金瓶梅》"}], "words": [{"w": "踅来踅去", "t": "来回走动。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5638wx','摭','1','zhí','扌','14','','[{"pinyin": "zhí", "defs": [{"meaning": "(形声。从手,庶声。字又作“拓”,从手,石声。本义:有选择的拾取)。"}, {"meaning": "同本义。", "cites": [{"t": "拓,拾也。陈、宋语。", "b": "《说文》"}, {"t": "摭,取也。", "b": "《方言一》"}, {"t": "有顺而摭也。", "b": "《礼记·礼器》"}, {"t": "乃摭于鱼腊俎。", "b": "《仪礼·有司彻》"}, {"t": "犹拾遗于涂,摭弃于野。", "b": "《论衡·逢遇》"}, {"t": "摭紫贝,搏耆龟。", "b": "张衡《西京赋》"}]}, {"meaning": "选取,摘取。", "cites": [{"t": "摭我华而不食我实。", "b": "《法言·问明》"}, {"t": "往往摭《离骚》文而反之。", "b": "《汉书·扬雄传》"}], "words": [{"w": "摭华", "t": "采摘其文章辞藻"}, {"w": "摭裂", "t": "采摘细碎"}, {"w": "摭实", "t": "摘取事实;据实。"}]}, {"meaning": "搜集。", "cites": [{"t": "摭其阴事以奏之,太祖遂疑之。", "b": "《旧五代史》"}], "words": [{"w": "摭采", "t": "搜集采用。"}]}]}]','jingmo-wenyan');
