INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5642wx','綦','1','qí','糸','14','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从糸,其声。糸(mì),细丝。从糸的字多与丝缕布帛有关。本义:苍灰色)。"}, {"meaning": "同本义。", "cites": [{"t": "綥,帛苍艾色。", "b": "《说文》"}, {"t": "缟衣綦巾。", "b": "《诗·郑风·出其东门》。传:“苍艾色女服也。”"}, {"t": "四人綦弁。", "b": "《书·顾命》"}, {"t": "世子佩瑜玉而綦组绶。", "b": "《礼记·玉藻》"}], "words": [{"w": "綦巾", "t": "青白色的女服,古代未嫁女子所服"}, {"w": "綦弁", "t": "古代苍灰色的皮冠。一说为赤黑色的皮冠。"}]}, {"meaning": "鞋带。", "cites": [{"t": "夏葛履…,组綦系于踵。", "b": "《仪礼·士丧礼》"}]}, {"meaning": "标准。", "cites": [{"t": "如是则下仰上以义矣,是綦定也。", "b": "《荀子》"}]}, {"meaning": "基本。", "cites": [{"t": "如是则下仰上以义矣。是綦定也。", "b": "《荀子·王霸》"}]}, {"meaning": "顶点,终了。", "cites": [{"t": "目欲綦色,耳欲綦声。", "b": "《荀子·王霸》"}]}]}]','jingmo-wenyan');
