('5651wx','蔟','1','cù','艹','14','','[{"pinyin": "cù", "defs": [{"meaning": "蚕蔟,供蚕作茧的东西。用稻麦杆等堆聚而成。", "cites": [{"t": "蔟,行蚕蓐。", "b": "《说文》"}, {"t": "帅导群妾,咸循蚕蔟。", "b": "扬雄《元后诔》"}]}, {"meaning": "巢。", "cites": [{"t": "读为爵蔟之蔟,谓巢也。", "b": "《周礼·哲蔟氏司农注》"}], "words": [{"w": "柴蔟", "t": ""}]}, {"meaning": "聚集,堆积。", "cites": [{"t": "律中太蔟。", "b": "《礼记·月令》"}, {"t": "野绿蔟草树,眼界蚕秦原。", "b": "唐·白居易《游悟真寺诗》"}]}, {"meaning": "簇拥。", "cites": [{"t": "众官蔟张松见刘璋。", "b": "《三国志平话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5652wx','蔺','1','lìn','艹','14','','[{"pinyin": "lìn", "defs": [{"meaning": "一种多年生草本植物,也称马蔺 ,根茎粗,叶线形,花蓝紫色。叶坚韧,可系物,又可造纸。根可制刷子。", "cites": [{"t": "蔺,莞属,从草,閵声。", "b": "《说文》"}, {"t": "蔺席。", "b": "《急就篇》"}]}, {"meaning": "假借为“棱”。", "cites": [{"t": "具蔺石。", "b": "《汉书·晁错传》。如淳注:“城上雷石也。”"}]}, {"meaning": "车轮碾压。", "cites": [{"t": "徒车之所蔺轹。", "b": "《汉书·司马相如传》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
