INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5657wx','斡','1','wò','斗','14','','[{"pinyin": "wò", "defs": [{"meaning": "(形声。从斗,倝（gàn）声。本义:勺把)。"}, {"meaning": "同本义。", "cites": [{"t": "斡,蠡柄也。", "b": "《说文》。段玉裁注:“判瓠为瓢以为勺,必执其柄而后可以挹物。执其柄则运旋在我,故谓之斡。”"}]}, {"meaning": "古小车轮。", "cites": [{"t": "斡…扬雄杜林说皆以为轺车轮斡也。", "b": "《说文》。段玉裁注:“轺车者,小车也。小车之轮曰斡,亦取善转运之意。”"}]}, {"meaning": "旋转。", "cites": [{"t": "斡,转也。", "b": "《广雅·释诂四》"}, {"t": "斡弃周鼎。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "斡旋天地", "t": "转变世界"}, {"w": "斡流", "t": "流转"}, {"w": "斡运", "t": "旋转运行"}, {"w": "斡维", "t": "运转的枢纽"}, {"w": "斡萦", "t": "旋转;运转"}, {"w": "斡转", "t": "运转。"}]}, {"meaning": "挑,负。", "cites": [{"t": "也强如提关列窖,也强如斡担挑箩。", "b": "元·杨显之《酷寒亭》"}]}]}]','jingmo-wenyan');
