INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5659wx','蓼','1','liǎo lù','艹','14','','[{"pinyin": "liǎo", "defs": [{"meaning": "蓼属植物的泛称 。一年生或多年生草本植物,花小,白色或浅红色,生长在水边或水中。叶味辛,可用以调味。"}, {"meaning": "春秋古国名。"}, {"meaning": "在今河南省唐河县西南。"}, {"meaning": "今河南省固始县东北有蓼城冈,即古蓼国之地。"}, {"meaning": "古县名 。南朝梁置。在今河南省固始县。"}, {"meaning": "姓。"}]}, {"pinyin": "lù", "defs": [{"meaning": "形容植物高大。", "cites": [{"t": "蓼蓼者莪。", "b": "《诗·小雅·蓼萧》"}], "words": [{"w": "蓼蓼", "t": "长大的样子"}, {"w": "蓼萧", "t": "指君王恩泽及于四海。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5660wx','榛','1','zhēn','木','14','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从木,秦声。本义:植物名。一种落叶灌木或小乔木)。"}, {"meaning": "同本义。", "cites": [{"t": "榛,榛木也。", "b": "《说文》"}, {"t": "山有榛。", "b": "《诗·邶风·简兮》"}, {"t": "女贽不过榛栗枣。", "b": "《左传·庄公二十四年》"}], "words": [{"w": "榛林", "t": "榛木林。"}]}, {"meaning": "榛果。"}, {"meaning": "丛生的树木。", "cites": [{"t": "木丛生曰榛。", "b": "《广雅》"}, {"t": "隐于榛薄之中。", "b": "淮南子·原道训》。注:“聚木曰榛,深草曰薄。”。"}], "words": [{"w": "榛林", "t": "亦指丛林"}, {"w": "榛迷", "t": "杂林丛生"}, {"w": "榛株", "t": "丛木的根株。"}]}, {"meaning": "草木丛生的样子  。", "cites": [{"t": "榛卉(杂生的花草);榛曲(草木丛生的幽僻之处);榛杞(泛指丛生的灌木);榛草(丛生的杂草)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5661wx','榧','1','fěi','木','14','','[{"pinyin": "fěi", "defs": [{"meaning": "木名。香榧,也叫“野杉”  。果实叫榧子", "words": [{"w": "榧子儿你嗒嗒", "t": "给你个榧子吃吃。榧子,指用拇指和中指相捻作声,这是苏、皖一带戏弄别家话中有错的动作。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5662wx','榻','1','tà','木','14','','[{"pinyin": "tà", "defs": [{"meaning": "(形声。从木,(tà)声。本义:狭长而较矮的床形坐具)。"}, {"meaning": "同本义。", "cites": [{"t": "移我琉璃榻。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "蕃在郡不接宾客,唯稚来特设一榻,去则悬之。", "b": "《后汉书·徐稚传》"}, {"t": "一榻。", "b": "清·周容《芋老人传》"}, {"t": "对坐榻上。", "b": "清·梁启超《谭嗣同传》"}, {"t": "喜置围榻上。", "b": "《聊斋志异·促织》"}], "words": [{"w": "榻登", "t": "厚毯。置于大床前,上榻上,用以登床"}, {"w": "榻布", "t": "质料粗厚的布"}, {"w": "竹榻;藤榻", "t": ""}]}, {"meaning": "几案。", "cites": [{"t": "乃独引肃还,合榻对饮。", "b": "《三国志·鲁肃传》"}]}, {"meaning": "睡。", "cites": [{"t": "舍间离此不远,何不草榻一宵?", "b": "《镜花缘》"}]}]}]','jingmo-wenyan');
