INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5664wx','榭','1','xiè','木','14','','[{"pinyin": "xiè", "defs": [{"meaning": "建在高土台或水面(或临水)上的木屋。", "cites": [{"t": "湖旁筑几条长堤,堤上百步一亭,五十步一榭。", "b": "《隋唐演义》"}, {"t": "楼观亭榭。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "舞榭歌台。", "b": "宋·辛弃疾《永遇乐》"}], "words": [{"w": "歌台舞榭", "t": ""}]}, {"meaning": "古代指无室的厅堂。也为藏器或讲军习武的处所。", "cites": [{"t": "将谋于榭。", "b": "《左传》"}]}]}]','jingmo-wenyan');
