INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5666wx','榱','1','cuī','木','14','','[{"pinyin": "cuī", "defs": [{"meaning": "即椽,放在檩上支持屋面和瓦片的木条。", "cites": [{"t": "秦名为屋椽,周谓之榱,齐鲁谓之桷。", "b": "《说文》"}, {"t": "栋折榱崩。", "b": "《左传·襄公三十一年》"}, {"t": "仰见榱栋,俯见几筵。", "b": "《新序·杂事四》"}], "words": [{"w": "榱桷", "t": "房上的椽子。桷:方形的椽子"}, {"w": "榱楹", "t": "椽子;柱子。楹:厅堂的前柱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5667wx','槁','1','gǎo','木','14','','[{"pinyin": "gǎo", "defs": [{"meaning": "(形声。从木,高声。本义:草木枯干)。"}, {"meaning": "同本义。", "cites": [{"t": "槀,木枯也。", "b": "《说文》"}, {"t": "离为科上槁。", "b": "《易·说卦传》"}, {"t": "形固可使如槁木。", "b": "《庄子·齐物论》"}, {"t": "虽有槁暴。", "b": "《荀子·劝学》"}, {"t": "草木摇落,时槁悴兮。", "b": "《楚辞·九叹·远逝》"}, {"t": "则苗槁矣。", "b": "《孟子·梁惠王上》"}, {"t": "及以燕赵起而攻之,若振槁然。", "b": "《荀子·王霸》"}, {"t": "其子趋而往视之,苗则槁矣。", "b": "《孟子·公孙丑上》"}, {"t": "举若振槁。", "b": "《史记·礼书》。索隐:“干叶也。”"}], "words": [{"w": "槁干", "t": "枯干。引申为贫穷"}, {"w": "槁腐", "t": "枯朽"}, {"w": "槁败", "t": "干枯衰败"}, {"w": "槁落", "t": "枯落"}, {"w": "败槁布地;槁箨", "t": "干枯的笋壳"}, {"w": "槁枲", "t": "干枯的麻秆。"}]}, {"meaning": "羸瘦;憔悴。", "cites": [{"t": "颜色憔悴,形容枯槁。", "b": "《史记·屈原列传》"}, {"t": "槁项黄馘者,商之所短也。", "b": "《庄子·列御寇》"}], "words": [{"w": "槁面", "t": "憔悴衰老的面容"}, {"w": "槁颈", "t": "羸瘦的样子"}, {"w": "槁悴", "t": "枯萎;憔悴"}, {"w": "槁瘠", "t": "枯瘦。"}]}, {"meaning": "死亡。", "cites": [{"t": "文山负其马,立槁,至今马冢尚在。", "b": "明·高攀龙《三时记》"}], "words": [{"w": "槁死", "t": "枯死;困死"}, {"w": "槁丧", "t": "灭亡。"}]}, {"meaning": "(kǎo)。击。", "cites": [{"t": "颎如槁石火。", "b": "潘岳《河阳县诗》"}]}, {"meaning": "(kào)。以酒肉等饮食慰劳。"}, {"meaning": "撑船的竿。", "cites": [{"t": "槁工楫师,选 自闽禺。", "b": "左思《吴都赋》"}]}]}]','jingmo-wenyan');
