('5669wx','槠','1','zhū','木','14','','[{"pinyin": "zhū", "defs": [{"meaning": "槠树 。常绿乔木,初夏开黄绿色花。木材坚硬,可用来盖房子或造船。", "cites": [{"t": "沙堂栎槠。", "b": "司马相如《上林赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5670wx','榷','1','què','木','14','','[{"pinyin": "què", "defs": [{"meaning": "(形声。从木,寉（hè）声。本义:独木桥)。"}, {"meaning": "同本义。", "cites": [{"t": "榷,水榷横木,所以渡者也。", "b": "《说文》。按:两头聚石,以木横架之,故亦名石杠。”"}, {"t": "榷,独梁也。", "b": "《广雅·释室》"}, {"t": "独木之桥曰榷。", "b": "《初学记》"}]}, {"meaning": "税。", "cites": [{"t": "其擅加杂榷,率一切宜停。", "b": "《文献通考》"}]}, {"meaning": "专营,专卖。", "cites": [{"t": "初榷酒酤。", "b": "《汉书·武帝纪》"}, {"t": "自以为国家兴榷筦之利。", "b": "《汉书·车千秋传》。注:“榷,谓专其利使入官也。”"}], "words": [{"w": "榷茶", "t": "由官方专卖茶叶,以独占其利"}, {"w": "榷货", "t": "由官方专卖货物而享专利"}, {"w": "榷酤", "t": "由官方专利卖酒"}, {"w": "榷盐", "t": "由官方专卖食盐。"}]}, {"meaning": "真实。", "cites": [{"t": "乐天知命,榷乎其不可拔也。", "b": "《玄儒先生娄寿碑》"}]}]}]','jingmo-wenyan');
