INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5672wx','酽','1','yàn','酉','14','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从酉(yǒu),严声。“酉”与有酒有关。本义:指茶、酒等饮料味厚)。"}, {"meaning": "同本义。", "cites": [{"t": "酒酽春浓琼草齐。", "b": "曹唐《小游仙诗》"}], "words": [{"w": "酽酒", "t": "味醇的酒"}, {"w": "酽茶", "t": "浓茶"}, {"w": "酽酸", "t": "浓浓的酸味"}, {"w": "酽酢", "t": "浓醋"}, {"w": "酽醋", "t": "浓醋。"}]}, {"meaning": "颜色深。", "cites": [{"t": "北宋院本画,用笔工致,傅色明酽。", "b": "《西清笔记》"}], "words": [{"w": "酽紫", "t": "深紫色。"}]}, {"meaning": "厉害,剧烈。", "cites": [{"t": "只是他赌的不酽。", "b": "《歧路灯》"}], "words": [{"w": "酽冷", "t": "酷寒,严寒"}, {"w": "酽冽", "t": "浓烈"}, {"w": "酽寒", "t": "酷寒,严寒"}, {"w": "酽酽", "t": "很浓;程度深。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5673wx','酶','1','méi','酉','14','','[{"pinyin": "méi", "defs": [{"meaning": "很大一类复杂的蛋白质物质  ,在促进可逆反应(如水解和氧化)方面起着像催化剂一样的作用。在许多工业过程中是有用的(如发酵、皮革鞣制及干酪生产)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5674wx','酹','1','lèi','酉','14','','[{"pinyin": "lèi", "defs": [{"meaning": "将酒倒在地上,表示祭奠或立誓。", "cites": [{"t": "人生如梦,一樽还酹江月。", "b": "苏轼《念奴娇·赤壁怀古》"}, {"t": "酹而哭者。", "b": "《明史》"}], "words": [{"w": "酹地", "t": "祭奠时以酒洒地"}, {"w": "酹酒", "t": "把酒洒在地上"}, {"w": "酹觞", "t": "把酒洒在地上时所用的酒杯。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5675wx','厮','1','sī','厂','14','','[{"pinyin": "sī", "defs": [{"meaning": "(从广,斯声。广(yǎn),就山崖作成的房子。厂(hǎn)山石之崖。“斯”也有表义作用。《汉书·严助传》“厮舆之卒”。颜师古注:“厮,析薪者。”“斯、析”都有“劈开”义。本义:古代干粗活的男性奴隶或仆役;服杂役者)。"}, {"meaning": "同本义。", "cites": [{"t": "厮徒十万。", "b": "《史记·苏秦传》。正义:“谓炊烹供养杂役。”"}, {"t": "厮舆之卒。", "b": "《汉书·严助传》。注:“析薪者也。”"}, {"t": "厮役扈养,死者数百人。", "b": "《公羊传·宣公十二年》"}, {"t": "料大王之卒,悉之不过三十万,而厮徒在其中矣。", "b": "《战国策·韩策》"}]}, {"meaning": "古时指无身分或下贱的人。", "cites": [{"t": "原来我的丈夫也吃这厮杀了。", "b": "《京本通俗小说·错斩崔宁》"}, {"t": "张教头那厮,三回五次托人情去说…,越不肯应承。", "b": "《水浒传》"}], "words": [{"w": "这厮;那厮;厮儿", "t": "家伙;小男孩;小子"}, {"w": "厮佣", "t": "雇工"}, {"w": "厮仆", "t": "仆役,佣人"}, {"w": "厮波", "t": "专在酒楼、妓院等娱乐场所侍客索钱的闲汉。"}]}, {"meaning": "相互。", "cites": [{"t": "莲子与人长厮类,无好意,年年苦在中心里。", "b": "宋·欧阳修《渔家傲》"}, {"t": "德安云梦人,初参妙喜…,喜曰:“我闻你安州人善厮扑,是否?”", "b": "《五灯会元·善真禅师》"}], "words": [{"w": "厮共", "t": "共同"}, {"w": "厮勾", "t": "互相接近;相亲相爱"}, {"w": "厮称", "t": "相称"}, {"w": "厮闹", "t": "吵闹;相互戏弄、胡闹"}, {"w": "厮说", "t": "彼此说长道短"}, {"w": "厮替", "t": "相互更替"}, {"w": "厮抬厮敬", "t": "互相抬举,互相尊敬"}, {"w": "厮朴行", "t": "专门从事相扑的团体"}, {"w": "厮丢厮打", "t": "互相打斗"}, {"w": "厮遮拦", "t": "相拦阻,阻挡"}, {"w": "厮合燥", "t": "厮合造。混闹,胡闹"}, {"w": "厮棵", "t": "拉扯,拽"}, {"w": "厮揾", "t": "依偎,挨靠。"}]}, {"meaning": "役使。", "cites": [{"t": "厮征伯侨而役羡门兮,属岐伯使尚方。", "b": "《史记·司马相如列传》"}]}, {"meaning": "分散,分开。", "cites": [{"t": "乃厮二渠,以引其河。", "b": "《史记·河渠书》"}, {"t": "蹂尸舆厮,系累老弱。", "b": "《汉书·扬雄传下》"}, {"t": "乃厮二渠,以引其河。", "b": "《新唐书·李频传》"}], "words": [{"w": "厮留", "t": "前后分离,不相衔接。"}]}]}]','jingmo-wenyan');
