INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5677wx','碴','1','chā chá','石','14','','[{"pinyin": "chā", "defs": [{"meaning": "剃后残余或复生的短毛发;胡子丛生的样子", "words": [{"w": "胡子拉碴", "t": "形容满脸胡子未加修饰。"}]}]}, {"pinyin": "chá", "defs": [{"meaning": "小碎块", "words": [{"w": "冰碴", "t": ""}, {"w": "玻璃碴", "t": ""}]}, {"meaning": "器物破口上的残缺部分。", "cites": [{"t": "崭新黑漆的车,把头折了一段,秃碴碴的露着两块白木碴儿,非常的不调和,难看。", "b": "老舍《骆驼祥子》"}]}, {"meaning": "皮肤被碎玻璃、瓷片等划破"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5678wx','碣','1','jié','石','14','','[{"pinyin": "jié", "defs": [{"meaning": "山高耸的;高大的。", "cites": [{"t": "碣以崇山。", "b": "《汉书·扬雄传》"}]}, {"meaning": "高大的岩石。", "cites": [{"t": "碣,特立之石也。东海有碣石山。", "b": "《说文》"}, {"t": "夹右碣石。", "b": "《书·禹贡》。传:“海畔山。”"}]}, {"meaning": "圆顶的石碑。", "cites": [{"t": "封禅丘兮建隆碣。", "b": "《后汉书·窦宪传》"}], "words": [{"w": "碣子", "t": "墓碣"}, {"w": "碣文", "t": "镌刻在碑石上的文字"}, {"w": "残碑断碣", "t": ""}]}, {"meaning": "碣石的省称 。碣石,古山名。在河北省昌黎县西北。", "cites": [{"t": "东临碣石。", "b": "曹操《观沧海》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5679wx','碲','1','dì','石','14','','[{"pinyin": "dì", "defs": [{"meaning": "一种与硒和硫有关的半金属元素,它们的化学性质相似 ——元素符号 Te。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5680wx','磋','1','cuō','石','14','','[{"pinyin": "cuō", "defs": [{"meaning": "(形声。从石,差声。本义:①失足跌倒。见《广韵》。②把骨、角制成器物)。"}, {"meaning": "磨治象牙。泛指磨治器物。", "cites": [{"t": "治象牙曰磋。", "b": "《广韵》"}, {"t": "骨谓之切,象谓之磋,玉谓之琢,石谓之磨。", "b": "《尔雅》"}, {"t": "切磋琢磨,乃成宝器。", "b": "《论衡·量知》"}, {"t": "如切如磋。", "b": "《诗·卫风·淇奥》"}], "words": [{"w": "磋磨", "t": "磨治器物"}, {"w": "磋琢", "t": "磨治雕琢"}, {"w": "磋切", "t": "摩擦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5681wx','臧','1','cáng zāng','臣','14','','[{"pinyin": "cáng", "defs": [{"meaning": "收藏", "cites": [{"t": "臧于理宫。", "b": "《汉书·礼乐志》。师古曰:“古书怀藏之字本皆作臧,汉书例为臧耳。”"}, {"t": "繁启蕃长于春夏,畜积收臧于秋冬。", "b": "《荀子·天论》"}], "words": [{"w": "臧去", "t": "密藏,珍藏。去,弆的省文,即密藏。"}]}]}, {"pinyin": "zāng", "defs": [{"meaning": "(形声。从臣,戕(qiāng)声。臣,奴隶。本义:男奴隶)。"}, {"meaning": "同本义。", "cites": [{"t": "臧与谷二人相马牧羊", "b": "《庄子·骈拇》"}], "words": [{"w": "臧聚", "t": "仆隶役夫"}, {"w": "臧获", "t": "古代对奴婢的贱称"}, {"w": "臧仆", "t": "精选和训练驾御帝王所乘五辂的役夫,使皆善其事。"}]}, {"meaning": "成功。", "cites": [{"t": "执事顺成为臧,逆为否。", "b": "《左传》"}]}, {"meaning": "赃物。", "cites": [{"t": "家尽没入偿臧。", "b": "《史记·王温舒传》"}, {"t": "盗有臧者罚。", "b": "《盐铁论·刑德》。注:“臧同赃。”"}, {"t": "其羞辱甚于贪污坐臧。", "b": "《汉书·伊赏传》"}]}, {"meaning": "古地名 。故地在今陕西省渭水附近。"}, {"meaning": "贪污;行贿。", "cites": [{"t": "其羞辱甚于贪污坐臧。", "b": "《汉书·尹赏传》"}, {"t": "毁则者为贼,掩贼者为臧,窃宝者为宄,用宄之财者为奸。", "b": "《国语·鲁语上》"}], "words": [{"w": "臧汗", "t": "贪污"}, {"w": "臧物", "t": "赃物"}, {"w": "臧贿", "t": "贪污受贿"}, {"w": "臧赂", "t": "贿赂"}, {"w": "臧罪", "t": "贪污受贿之罪。"}]}, {"meaning": "认为好,满意。", "cites": [{"t": "陟罚臧否,不宜异同。", "b": "诸葛亮《出师表》"}]}, {"meaning": "好的,美好的,善良的。", "cites": [{"t": "不忮不求,何用不臧?", "b": "《诗·邶风·雄雉》"}], "words": [{"w": "臧不", "t": "善恶"}, {"w": "臧贬", "t": "褒贬,品评高下。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5682wx','豨','1','xī','豕','14','','[{"pinyin": "xī", "defs": [{"meaning": "古代楚人对小猪的称谓。", "cites": [{"t": "豨,《字书》云:“东方名豕也。”", "b": "《尔雅》"}]}, {"meaning": "象声词。表示叹息声。", "cites": [{"t": "妃呼豨!秋风肃肃晨风颸，东方须臾高知之", "b": "《乐府诗集·鼓吹曲辞一》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5683wx','殡','1','bìn','歹','14','','[{"pinyin": "bìn", "defs": [{"meaning": "(形声。从歹,宾声。“歹”,本作“歺”,音è,隶变以后成为“歹”。汉字部首之一。从“歹”的字多与死、坏或不吉祥等义有关。本义:停柩待葬)。"}, {"meaning": "同本义。", "cites": [{"t": "殡,死在棺,将迁葬柩,宾遇之。", "b": "《说文》"}, {"t": "于我殡。", "b": "《论语·乡党》"}, {"t": "晋文公卒,庚辰,将殡于曲沃。", "b": "《左传·僖公三十二年》"}, {"t": "死者殡在屋内。", "b": "《北史·高丽传》"}], "words": [{"w": "殡宫", "t": "古代称下葬前临时安置灵柩的地方"}, {"w": "殡阶", "t": "西阶。周代人停灵柩于西阶之上,犹宾礼也"}, {"w": "殡棺", "t": "入殓而未葬的灵柩。"}]}, {"meaning": "泛指丧葬事务。", "cites": [{"t": "道秩长殡,法筵久埋。", "b": "孙稚圭《北山移文》"}], "words": [{"w": "殡丧", "t": "泛指丧葬之事"}, {"w": "殡服", "t": "在殡殓时穿的丧服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5684wx','霆','1','tíng','雨','14','','[{"pinyin": "tíng", "defs": [{"meaning": "(形声。从雨,廷声。“霆、電”实同一词,后来岐为二义,其声曰霆,其光曰電。轻雷或无电,疾雷必有电,故霆的本义:为疾雷,为霹雳)。"}, {"meaning": "同本义。", "cites": [{"t": "霆,雷余声也", "b": "《说文》"}, {"t": "疾雷为霆。", "b": "《尔雅·释天》"}, {"t": "如雷如霆。", "b": "《诗·大雅·常武》"}, {"t": "若疾霆转雷而激迅风也。", "b": "《文选·张衡·东京赋》"}, {"t": "畏之如雷霆。", "b": "《左传·襄公十四年》"}, {"t": "千雷万霆。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "霆激", "t": "雷霆激发。形容来势凶猛;比喻迅速快捷"}, {"w": "霆击", "t": "快速攻击,如雷霆一般迅疾。"}]}, {"meaning": "闪电。", "cites": [{"t": "疾雷不及塞耳,疾霆不暇掩目。", "b": "《淮南子》"}]}, {"meaning": "震动。", "cites": [{"t": "天冬雷,地冬霆,草木夏落而秋荣。", "b": "《管子》。尹知章注:“霆,震。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5685wx','霁','1','jì','雨','14','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从雨,齐声。本义:雨止)。"}, {"meaning": "同本义。", "cites": [{"t": "霁,雨止也。", "b": "《说文》"}, {"t": "曰霁。", "b": "《书·洪范》。郑注:“兆之光明如雨止。”"}, {"t": "旬日不霁。", "b": "《汉书·沟洫志》"}], "words": [{"w": "霁雨", "t": "雨停"}, {"w": "霁后", "t": "雨停后"}, {"w": "雪霁", "t": ""}]}, {"meaning": "雨后或雪后转晴。", "cites": [{"t": "霜雪不霁。", "b": "《淮南子·本经》"}, {"t": "复道行空,不霁何虹?", "b": "唐·杜牧《阿房宫赋》"}, {"t": "夜雪初霁。", "b": "宋·姜夔《扬州慢》"}], "words": [{"w": "霁日", "t": "雨后见日的晴朗天气"}, {"w": "霁朝", "t": "雨后初晴的早晨"}, {"w": "霁景", "t": "雨后鲜明的景色"}, {"w": "霁青", "t": "陶瓷色名。如雨后晴空的青色。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5686wx','辕','1','yuán','车','14','','[{"pinyin": "yuán", "defs": [{"meaning": "(形声。从车,袁声。本义:车辕子,车前驾牲口的直木)。"}, {"meaning": "同本义。", "cites": [{"t": "辕,辀也。", "b": "《说文》。按,大车、柏车、羊车皆左右两木,曰辕,其形直。一牛在辕间;田车、兵车、乘车皆居中。一木穹隆而上,曰辀,其形曲。"}, {"t": "今夫大车之辕挚,谓辕卑也。", "b": "《考工记·辀人》"}, {"t": "凡为辕,三其轮崇。", "b": "《周礼·考工记·车人》"}, {"t": "令尹南辕返旆。", "b": "《左传·宣公十二年》"}], "words": [{"w": "辕轭(车前驾牲口的直木和套在牲口脖子上的曲木借指车子)辕缚(指辂木因其缚于辕上,故名)", "t": ""}]}, {"meaning": "古代帝王外出止宿时,于险阻处置车为屏藩,又仰两车使辕对峙如门,称辕门。", "cites": [{"t": "置旃以为辕门。", "b": "《谷梁传·昭公八年》"}, {"t": "设车宫辕门。", "b": "《周礼》"}], "words": [{"w": "辕垣", "t": "官署。"}]}, {"meaning": "后指军营之门或行馆,即长官战场司令部或官方的衙署。", "cites": [{"t": "吕奉先射戟辕门,曹孟德败师淯水。", "b": "《三国演义》"}, {"t": "城中有何新闻?抚军在辕否?", "b": "沈浮《浮生六记》"}], "words": [{"w": "辕门抄", "t": "清朝督抚官署抄寄属下州、府、县的公文或情报。后改为木板印刷。"}]}, {"meaning": "古地名 。在今山东省禹城县境内。"}, {"meaning": "姓 。春秋陈有辕涛涂。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5687wx','蜚','1','fēi fěi','虫','14','','[{"pinyin": "fēi", "defs": [{"meaning": "(形声。从虫,非声。①(fěi)本义:一种有害的小飞虫②(fēi)通“飞”。鸟飞) 通“飞”。飞翔。", "cites": [{"t": "三年不蜚,蜚将冲天。", "b": "《史记·楚世家》"}, {"t": "一体花纹如彩画,满身锦绣若蜚英。", "b": "《西游记》"}, {"t": "夏,蝗从东方来,蜚蔽天。", "b": "《汉书·王莽传下》"}], "words": [{"w": "蜚英", "t": "飞花"}, {"w": "蜚集", "t": "飞翔集结"}, {"w": "高蜚", "t": "高高飞翔;飞得很高"}, {"w": "蜚翔", "t": "飞行翱翔。"}]}]}, {"pinyin": "fěi", "defs": [{"meaning": "(形声。从虫,非声。本义:昆虫名。草螽)。"}, {"meaning": "同本义。", "cites": [{"t": "秋,有蜚,为灾也", "b": "《左传·庄公二十九年》"}]}, {"meaning": "传说中的灾兽。", "cites": [{"t": "太山上多金玉桢木。有兽焉,其状如牛而白首,一目而蛇尾,其名曰蜚。", "b": "《山海经》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5688wx','裴','1','péi','衣','14','','[{"pinyin": "péi", "defs": [{"meaning": "(形声。从衣,非声。本义:长衣下垂的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "裴,长衣貌。", "b": "《说文》"}, {"t": "衯衯裶裶。", "b": "司马相如《子虚赋》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5689wx','翡','1','fěi','羽','14','','[{"pinyin": "fěi", "defs": [{"meaning": "赤羽雀。", "cites": [{"t": "翡,赤羽雀也。出郁林,从羽,非声。雄赤曰翡,雌青曰翠。", "b": "《说文》"}, {"t": "翡大于燕,小于乌,腰身通黑,惟胸、前背、翼后有赤毛也;翠通身青黄,惟六翮上毛长寸余,其飞,即羽鸣翠翠翡翡,因以名焉。", "b": "《南方异物志》"}, {"t": "饰以翡翠。", "b": "《汉书·贾山传》"}, {"t": "请挟弹怀丸游水上,弹翡燕小鸟。", "b": "《管子》"}, {"t": "雄赤曰翡,雌青曰翠,出郁林。", "b": "唐·玄应《一切经音义》"}]}, {"meaning": "可作装饰品的翡翠羽毛。", "cites": [{"t": "翡帷翠帐,饰高堂些。", "b": "《楚辞·招魂》"}]}]}]','jingmo-wenyan');
