INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5692wx','睿','1','ruì','目','14','','[{"pinyin": "ruì", "defs": [{"meaning": "(会意。《说文》:“ 从目,从谷省。空虚的山洼,有畅通义。‘目’的作用是明察。合起来表示‘明智’、‘智慧’”。本义:通达;明智) 同本义。", "cites": [{"t": "叡,深明也,通也。", "b": "《说文》"}, {"t": "睿,智也,明也,圣也。", "b": "《玉篇》"}, {"t": "子羽睿敏。", "b": "《左传·哀公十一年》"}, {"t": "睿而为愚者也。", "b": "柳宗元《愚溪诗序》"}, {"t": "德幼而叡齐。", "b": "《大戴礼记·五帝》"}], "words": [{"w": "睿圣", "t": "聪明通达,明晓事理"}, {"w": "睿日", "t": "神圣的太阳"}, {"w": "睿化", "t": "圣明的教化"}, {"w": "睿祖", "t": "神圣的祖先"}, {"w": "睿姿", "t": "指圣明的资质"}, {"w": "睿思", "t": "圣明的思虑"}, {"w": "睿性", "t": "圣明的天性"}, {"w": "睿岳", "t": "比喻深广的恩德"}, {"w": "睿明", "t": "智慧;明智。"}]}]}]','jingmo-wenyan');
