INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5694wx','睽','1','kuí','目','14','','[{"pinyin": "kuí", "defs": [{"meaning": "(形声。从目,癸声。本义:两眼不看一地方) 斜视。", "cites": [{"t": "睽,目少精也。", "b": "《广苍》"}, {"t": "睽,目不相视也。", "b": "《说文》"}]}, {"meaning": "目不相视,即二目不能集中视线同视一物。"}, {"meaning": "分离;背离。", "cites": [{"t": "睽者,乖也。", "b": "《易·序卦》"}, {"t": "睽,外也。", "b": "《易·杂卦》"}, {"t": "睽孤见豕负涂。", "b": "《汉书·五行志》。注:“睽孤乖剌之意也。”"}, {"t": "归妹之睽。", "b": "《左传·僖公十五年》。注:“乖离之象。”"}, {"t": "曩者胶漆契,迩来云雨睽。", "b": "白居易《伤友》"}], "words": [{"w": "睽违", "t": "分离;不在一起"}, {"w": "睽离", "t": "阔别"}, {"w": "睽别", "t": "分离,离别"}, {"w": "睽阻", "t": "离别阻隔"}, {"w": "睽隔", "t": "别离,分隔"}, {"w": "睽阔", "t": "久别;远别"}, {"w": "睽阕", "t": "分离隔断"}, {"w": "睽离", "t": "分离;离散。"}]}, {"meaning": "违背,不合。", "cites": [{"t": "守失其微,天下孤睽。", "b": "扬雄《法言》"}]}]}]','jingmo-wenyan');
