INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5715wx','嘘','1','xū shī','口','14','','[{"pinyin": "xū", "defs": [{"meaning": "(形声。从口,虚声。本义:缓缓吐气;呵气)。"}, {"meaning": "同本义。", "cites": [{"t": "嘘,吹也。", "b": "《说文》"}, {"t": "出气缓曰嘘。", "b": "《声类》"}, {"t": "仰天而嘘。", "b": "《庄子·齐物论》"}, {"t": "嘘为雨露,噫为风雷。", "b": "刘禹锡《天论下》"}, {"t": "龙嘘气成云。", "b": "韩愈《杂说》"}], "words": [{"w": "嘘咈", "t": "呼吸;呼气与吸气"}, {"w": "嘘吸", "t": "吐纳呼吸"}, {"w": "嘘呵", "t": "形容风扬火气;呵气使暖"}, {"w": "嘘咻", "t": "形容喘气的样子"}, {"w": "嘘歙", "t": "呼吸。"}]}, {"meaning": "叹息。", "cites": [{"t": "长嘘吸以于悒兮,涕横集而成行。", "b": "《楚辞·刘向·九叹·忧苦》"}, {"t": "言未卒,因嘘唏服臆。", "b": "《史记·扁鹊佳》"}, {"t": "魂梦天涯无暂歇,枕上长嘘。", "b": "《敦煌曲子词》"}], "words": [{"w": "嘘欷", "t": "哀叹抽泣声"}, {"w": "嘘嗟", "t": "嗟叹"}, {"w": "嘘叹", "t": "叹息。"}]}]}, {"pinyin": "shī", "defs": [{"meaning": "", "words": [{"w": "嘘!别把大娘吵醒了!;嘘!你不要胡说!;嘘,你有啥高招!", "t": ""}]}]}]','jingmo-wenyan');
