('5719wx','嘤','1','yīng','口','14','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从口,婴声。双音词“嘤嘤”。本义:鸟鸣声)。"}, {"meaning": "同本义。", "cites": [{"t": "嘤,鸟鸣也。", "b": "《说文》"}, {"t": "鸟鸣嘤嘤。", "b": "《诗·小雅·伐木》"}, {"t": "山鹊兮嘤嘤。", "b": "《楚辞·悼乱》"}, {"t": "好鸟相鸣,嘤嘤成韵。", "b": "《艺文类聚·吴均·与朱元思书》"}], "words": [{"w": "嘤呦", "t": "鸟鸣"}, {"w": "嘤鸟", "t": "鸣声相和之鸟"}, {"w": "嘤声", "t": "鸟和鸣声。"}]}, {"meaning": "哽塞;哽咽。多含有抽泣、哭鼻子之意。", "cites": [{"t": "贪水者,脉必厥,其声嘤,咽喉塞。", "b": "汉·张仲景《伤寒论》"}], "words": [{"w": "嘤噯", "t": "啼泣"}, {"w": "嘤唔", "t": "细弱哀怨之声。"}]}]}]','jingmo-wenyan');
