('5725wx','幔','1','màn','巾','14','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。从巾,曼声。巾,丝麻织品。本义:帐幕,帐幔)。"}, {"meaning": "同本义。", "cites": [{"t": "幔,幕也…蔽在上曰幔,在旁曰帷。", "b": "《说文》"}, {"t": "幔幕帷盖,三军之用。", "b": "《墨子·非攻》"}], "words": [{"w": "幔亭", "t": "张挂帐幕围成的亭子"}, {"w": "幔屋", "t": "帐篷"}, {"w": "幔幕,幔帷,幔城", "t": "张帷幔围绕如城,故称“幔城”"}, {"w": "幔室", "t": "用帷幕围成的房间。"}]}, {"meaning": "以布帛制成,遮蔽门窗等用的帘子。", "cites": [{"t": "乘幔不举。", "b": "《国语·晋语》。注:“幔,车无文也。”"}], "words": [{"w": "幔子", "t": ""}]}, {"meaning": "指古时酒店的招子。", "cites": [{"t": "酒幔高楼一百家,宫前杨柳寺前花。", "b": "唐·王建《宫前早春》"}]}]}]','jingmo-wenyan');
