('5728wx','赙','1','fù','贝','14','','[{"pinyin": "fù", "defs": [{"meaning": "拿钱财帮助别人办理丧事。", "cites": [{"t": "赙,以财助丧也。", "b": "《玉篇》"}, {"t": "车马曰賵,货财曰赙。", "b": "《公羊传·隐公元年》"}, {"t": "知死者赠,知生者赙。", "b": "《仪礼·既夕礼》"}, {"t": "吊丧弗能赙。", "b": "《礼记·曲礼上》"}, {"t": "赙绢千匹。", "b": "《后汉书·杜诗传》"}], "words": [{"w": "赙遗", "t": "赠送财物助人治丧"}, {"w": "赙赐", "t": "赏赐财物助办丧事"}, {"w": "赙诔", "t": "赙赠和诔文"}, {"w": "赙补", "t": "赠送丧家财物以助其不足"}, {"w": "赙祭", "t": "赠送财物以祭死者"}, {"w": "赙礼", "t": "给丧家送的礼物"}, {"w": "赙金", "t": "助人办丧事的钱"}, {"w": "赙布", "t": "送给丧家的财帛"}, {"w": "赙賵", "t": "送给丧家的车马财物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5729wx','罂','1','yīng','缶','14','','[{"pinyin": "yīng", "defs": [{"meaning": "大腹小口的瓦器。或作“甇”。", "cites": [{"t": "罂,缶也。", "b": "《说文》"}, {"t": "自关而西,晋之旧都,河汾之间,其大者谓之,其中者谓之;自关而东,赵魏之郊,谓之瓮,或谓之罂。", "b": "《方言五》"}, {"t": "用瓦木罂,容十升以上者,五十步而十,盛水且用之。", "b": "《墨子》"}], "words": [{"w": "罂盎", "t": "泛指盛酒器"}, {"w": "罂瓶", "t": "泛指盛酒器。"}]}, {"meaning": "泛指小口大腹的瓶。", "cites": [{"t": "火药三百罂。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "罂缶", "t": "大腹小口的瓶。"}]}, {"meaning": "植物名 。罂粟科,罂粟属,二年生草本,高约 1.5米。"}]}]','jingmo-wenyan');
