('5732wx','鹘','1','gǔ hú','鸟','14','','[{"pinyin": "gǔ", "defs": [{"meaning": "鸟名。似山鹊而小，短尾，青黑色。"}]}, {"pinyin": "hú", "defs": [{"meaning": "鸷鸟名。即隼 。部分隼属动物的旧称。", "cites": [{"t": "山上栖鹘。", "b": "宋·苏轼《石钟山记》"}, {"t": "俊鹘抟水禽。", "b": "宋·陆游《过小孤山大孤山》"}, {"t": "山中栖鹘。", "b": ""}], "words": [{"w": "鹘雕", "t": "即斑鸠"}, {"w": "鹘人", "t": "饲养猎鹰的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5733wx','锲','1','qiè','钅','14','','[{"pinyin": "qiè", "defs": [{"meaning": "(形声。从金,契(qì)声。本义:镰刀) 同本义。", "cites": [{"t": "锲,镰也。", "b": "《说文》"}, {"t": "刎镰,一曰小镰,南方用以乂谷。", "b": "《六书故》引蜀本》"}, {"t": "刈钩,自关而西,或谓之锲。", "b": "《方言五》"}], "words": [{"w": "锲刀", "t": "镰刀。"}]}, {"meaning": "假借为“洯”。用刀子刻。", "cites": [{"t": "锲其轴。", "b": "《左传·定公四年》。注:“刻也。”"}, {"t": "锲而舍之,朽木不折。", "b": "《荀子·劝学》"}]}, {"meaning": "又。", "cites": [{"t": "锲而不舍。", "b": ""}]}, {"meaning": "截断。", "cites": [{"t": "尽借邑人之车,锲其轴,麻约而归之。", "b": "《左传》"}]}]}]','jingmo-wenyan');
