INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5735wx','锶','1','sī','钅','14','','[{"pinyin": "sī", "defs": [{"meaning": "属于碱土族的一种银白色、软而且有延展性和韧性的二价金属元素,仅以组合物的形式、尤其是作为菱锶矿和天青石而存在,通常是由电解它的融熔的氯化物或者用铝加热还原它的氧化物而制得,在空气中变为淡黄,能产生使火焰和焰火组分染上绯红色的化合物 ——元素符号Sr。"}]}]','jingmo-wenyan');
