('5739wx','镁','1','měi','钅','14','','[{"pinyin": "měi", "defs": [{"meaning": "系一种银白色光泽的、有延展性的二价金属元素。主要通过电解含氯化镁的熔融盐或热还原氧化镁方法制取 ——元素符号Mg。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5740wx','镂','1','lòu','钅','14','','[{"pinyin": "lòu", "defs": [{"meaning": "(形声。从金,娄声。本义:可供雕刻的坚铁)。"}, {"meaning": "金刚钻。", "cites": [{"t": "厥贡璆、铁、银、镂、砮磬。", "b": "《书·禹贡》。孔传:“镂,刚铁。”"}]}, {"meaning": "釜,烹饪用的锅。", "cites": [{"t": "镂,釜也。", "b": "《说文》"}]}, {"meaning": "孔穴。", "cites": [{"t": "生禹于石纽,虎鼻大耳,两耳参镂。", "b": "《宋书》"}]}, {"meaning": "雕刻。", "cites": [{"t": "锲而不舍,金石可镂。", "b": "《荀子·劝学》"}, {"t": "器不彤镂。", "b": "《左传·哀公元年》"}, {"t": "流苏金镂鞍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "镂冰", "t": "于冰上雕刻。比喻徒劳而无功"}, {"w": "镂板", "t": "本指雕刻以印书的木板,引申为雕板印刷"}, {"w": "镂花", "t": "雕刻花纹"}, {"w": "镂金", "t": "雕刻金箔用为装饰"}, {"w": "镂象", "t": "雕刻象牙为饰的车子。"}]}, {"meaning": "凿通。", "cites": [{"t": "镂灵山,梁孙原。", "b": "《汉书·司马相如传下》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
