INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5746wx','箸','1','zhù','竹','14','','[{"pinyin": "zhù", "defs": [{"meaning": "(形声。从竹,者声。本义:筷子。又作“筯”) 同本义。", "cites": [{"t": "羹之有菜者用梜。", "b": "《礼记·曲礼》。注:“今人或谓箸为梜。”"}, {"t": "纣为象箸,而箕子唏。", "b": "《史记·十二诸侯年表》"}, {"t": "停杯投箸不能食。", "b": "唐·李白《行路难》"}, {"t": "辍箸叹曰。", "b": "清·周容《芋老人传》"}]}, {"meaning": "又。", "cites": [{"t": "亦辍箸曰。", "b": ""}]}, {"meaning": "又。", "cites": [{"t": "独一箸间。", "b": ""}], "words": [{"w": "长箸", "t": "较长的筷子"}, {"w": "箸长碗短", "t": "比喻餐具凌乱不齐"}, {"w": "箸筩", "t": "盛筷子的竹筒"}, {"w": "箸子", "t": "筷子。"}]}, {"meaning": "显明;显示。", "cites": [{"t": "知命者也,箸是者也。", "b": "《荀子·非十二子》"}, {"t": "霸者之善箸焉。", "b": "《荀子·强国》"}, {"t": "致忠信,箸仁义。", "b": "《荀子·王霸》"}]}, {"meaning": "撰写,写作", "cites": [{"t": "箸《论衡》八十五篇,二十余万言。", "b": "《后汉书》"}, {"t": "及稍定汉诸仪法,皆叔孙生为太常所论著也。", "b": "《史记》"}], "words": [{"w": "箸录", "t": "记载;记录"}, {"w": "箸论", "t": "著作,论述"}, {"w": "箸撰", "t": "撰述;写成的作品。"}]}]}]','jingmo-wenyan');
