('5747wx','箬','1','ruò','竹','14','','[{"pinyin": "ruò", "defs": [{"meaning": "竹笋壳。", "cites": [{"t": "箬,楚谓竹皮曰箬。", "b": "《说文》"}], "words": [{"w": "箬壳", "t": "笋壳;笋皮。"}]}, {"meaning": "箬叶,箬竹的叶子。", "cites": [{"t": "中轩敞者为舱,蒻篷覆之。", "b": "魏学洢《核舟记》"}], "words": [{"w": "箬篷", "t": "用箬叶编的船篷"}, {"w": "箬篓", "t": "用箬竹编的篓"}, {"w": "箬包船", "t": "一种头部尖狭,船顶上包有穹形箬篷以蔽烈日、雨雪的船"}, {"w": "箬粽", "t": "用箬竹叶包的粽子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5748wx','箅','1','bì','竹','14','','[{"pinyin": "bì", "defs": [{"meaning": "蒸锅中的竹屉。后指有空隙而能起间隔作用的器具。", "cites": [{"t": "箅,所以蔽甑底者也。从竹,畀声。", "b": "《说文》。按,甑以蒸饭,底有七穿以竹席蔽之。"}, {"t": "敝箅不能救盐池之碱,阿胶不能止黄河之浊。", "b": "北周·庾信《哀江南赋》"}]}]}]','jingmo-wenyan');
