('5756wx','儆','1','jǐng','亻','14','','[{"pinyin": "jǐng", "defs": [{"meaning": "(形声。从人,敬声。本义:警戒,戒备)。"}, {"meaning": "同本义。", "cites": [{"t": "儆,戒也。", "b": "《说文》"}, {"t": "儆,备也。", "b": "《后汉书·东平宪王苍传》注"}, {"t": "使府人库人各儆其事。", "b": "《左传·昭公十八年》"}, {"t": "令司官、巷伯儆宫。", "b": "《左传·襄公九年》"}], "words": [{"w": "儆悟", "t": "儆醒。儆戒,醒悟"}, {"w": "儆守", "t": "戒备防守"}, {"w": "儆惧", "t": "戒惧;警惕和畏惧"}, {"w": "儆懔", "t": "戒惧"}, {"w": "儆戢", "t": "戒惧而有所收敛"}, {"w": "儆儆", "t": "不安的样子"}, {"w": "儆动", "t": "戒惧不安"}, {"w": "儆畏", "t": "警惕和畏惧;戒惧。"}]}, {"meaning": "告诫;警告。", "cites": [{"t": "夜儆百工。", "b": "《国语·鲁语》"}, {"t": "乃儆公仲之行。", "b": "《战国策·韩策》"}, {"t": "所以儆人臣也。", "b": "《孔子家语·五仪》"}, {"t": "在军,无日不讨军实而申儆之。", "b": "《左传·宣公十二年》"}, {"t": "宜杀一儆百。", "b": "龚自珍《送钦差大臣侯官林公序》"}]}, {"meaning": "警报,紧急情况。", "cites": [{"t": "若今时儆跸。", "b": "《周礼·夏官·隸仆》"}], "words": [{"w": "儆急", "t": "紧急,一般指军情。"}]}]}]','jingmo-wenyan');
