('5760wx','僮','1','tóng zhuàng','亻','14','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。从人,童声。本义:未成年的人)。"}, {"meaning": "同本义。", "cites": [{"t": "僮,未冠也。", "b": "《说文》。按:“十九以下,八岁以上也。”"}, {"t": "僮子备官,而未之闻邪。", "b": "《国语·鲁语》"}, {"t": "为两郎僮。", "b": "唐·柳宗元《童区寄传》"}, {"t": "孰若为一郎僮耶。", "b": ""}, {"t": "与其杀是僮。", "b": ""}, {"t": "不当为僮。", "b": ""}], "words": [{"w": "僮子", "t": "童子。指未成年的人"}, {"w": "僮女", "t": "童女,少女"}, {"w": "僮男", "t": "童男,少年"}, {"w": "僮儿", "t": "男孩"}, {"w": "僮谣", "t": "即童谣。"}]}, {"meaning": "奴婢。", "cites": [{"t": "而卓王孙家僮数百人。", "b": "《史记·司马相如传》"}, {"t": "今民卖僮者。", "b": "《汉书·贾谊传》"}], "words": [{"w": "僮使", "t": "奴婢"}, {"w": "僮奴", "t": "奴仆"}, {"w": "僮史", "t": "仆隶"}, {"w": "僮役", "t": "仆役"}, {"w": "僮牧", "t": "犹僮仆"}, {"w": "僮指", "t": "称僮仆,奴婢"}, {"w": "僮客", "t": "奴仆"}, {"w": "僮娃", "t": "指童婢。"}]}, {"meaning": "无知。", "cites": [{"t": "僮昏不可使谋。", "b": "《国语·晋语》"}], "words": [{"w": "僮昏", "t": "昏愦无知。亦指昏愦无知的人"}, {"w": "僮蒙", "t": "昏昧不明事理。"}]}]}, {"pinyin": "zhuàng", "defs": [{"meaning": "中国少数民族壮族的“壮”的原字,1965年改“僮”为“壮”。"}]}]','jingmo-wenyan');
