('5766wx','膈','1','gé','月','14','','[{"pinyin": "gé", "defs": [{"meaning": "隔膜", "words": [{"w": "膈言", "t": "肺腑之言"}, {"w": "膈肢", "t": "用手探入腋下使发痒而笑"}, {"w": "膈噎", "t": "中医指胸腹胀痛、下咽困难、常打嗝等症状"}, {"w": "膈臆", "t": "肺俯,肝胆。比喻内心"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5767wx','膑','1','bìn','月','14','','[{"pinyin": "bìn", "defs": [{"meaning": "特指古代一种剔掉膝盖骨的酷刑。", "cites": [{"t": "髕罚之属五百。", "b": "《汉书·刑罚志》"}, {"t": "周改膑作刖。", "b": "《周礼·司刑》注"}, {"t": "放膑者,脱去人之膑也。", "b": "《书·刑德》"}, {"t": "孙子膑脚。", "b": "汉·司马迁《报任少卿书》"}], "words": [{"w": "膑辟", "t": "古代断足的酷刑"}, {"w": "膑脚", "t": "砍去膝盖骨及以下的酷刑"}, {"w": "膑罚", "t": "剔去膝盖骨的酷刑。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5768wx','鲑','1','guī huá xié','鱼','14','','[{"pinyin": "guī", "defs": [{"meaning": "鱼名。鲑鱼 。属于鲑科(Salmonidae)的若干种鱼的共同名称。它们生活在北大西洋和北太平洋的近海水域,繁殖期上溯到内陆江河产卵。"}]}, {"pinyin": "huá", "defs": [{"meaning": "古代传说中的一种有翼发光的飞鱼。", "cites": [{"t": "又东南二百里曰子桐之山,子桐之水出焉。而西流注于余如之泽。其中多鲑鱼,其状如鱼而鸟翼,出入有光,其音如鸳鸯,见则天下大旱。", "b": "《山海经》"}]}, {"meaning": "一种鲤科鱼 。体延长,侧扁,银灰色,侧线上方有一纵行黑斑,脊鳍、尾鳍和体侧均有小黑斑,吻尖突。生活在淡水中,分布于东亚——亦称“花鲑”。"}]}, {"pinyin": "xié", "defs": [{"meaning": "鱼类菜肴的总称。", "cites": [{"t": "谁谓庾郎贫,食鲑尝有二十七种。", "b": "《南史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5769wx','鲔','1','wěi','鱼','14','','[{"pinyin": "wěi", "defs": [{"meaning": "鲟鱼和鳇鱼的古称。", "cites": [{"t": "鲔鱼,色青黑,头小而尖,似铁兜鍪,口在颔下,其甲可以磨姜,大者不过七八尺。大者为王鲔,小者为叔鲔。", "b": "三国吴·陆机《毛诗草木鸟兽虫鱼疏》"}]}, {"meaning": "鲔鱼 。体呈纺锤形,背蓝黑色,腹灰白,背鳍和臀鳍后面各有七或八个小鳍。生活在热带海洋,吃小鱼等动物。"}, {"meaning": "白鲟的古称。又名象鱼、剑鱼、琴鱼 。鱼纲白鲟科。体呈梭形,裸露无鳞,无骨板。深灰色或浅灰色。头大,口大眼小,吻突出呈剑状,长如象鼻。鳃盖膜发达,如象耳。为中国特产。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5770wx','鲚','1','jì','鱼','14','','[{"pinyin": "jì", "defs": [{"meaning": "鱼名,亦作鮆 。体狭而扁,头小,口大,脊鳍短,臀鳍甚长,生活在近海,春季上溯于江河而产卵。太湖中亦有产者,全体银白色,亦名“刀鱼”、“鲚刀鱼”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5771wx','鲛','1','jiāo','鱼','14','','[{"pinyin": "jiāo", "defs": [{"meaning": "动物名。海中鲨鱼", "words": [{"w": "鲛函", "t": "用鲛鱼皮所做的铠甲"}, {"w": "鲛革", "t": "鲛鱼皮制的革"}, {"w": "鲛鳄", "t": "鲨鱼与鳄鱼"}, {"w": "鲛绡", "t": "鲛人织的绡"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5772wx','鲟','1','xún','鱼','14','','[{"pinyin": "xún", "defs": [{"meaning": "鲟鱼 。属于鲟属(Acipenser)和其他有关属的各种通常是大型的硬鳞鱼,广泛分布于北温带的淡水或咸水水域中,体形细长,有歪形尾,延长的头部下面有一个可伸缩的无齿的嘴", "words": [{"w": "鲟嘴", "t": "鲟鱼的嘴"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5773wx','獐','1','zhāng','犭','14','','[{"pinyin": "zhāng", "defs": [{"meaning": "野兽名 。像鹿,比鹿小,头上无角,有长牙露出嘴外。皮可以做衣服。也叫“牙獐”。", "cites": [{"t": "吾今日围猎,欲射“马”,误中一“獐”。", "b": "《全图绣像三国演义》"}], "words": [{"w": "獐猫", "t": "貌似猫头的獐子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5774wx','觫','1','sù','角','14','','[{"pinyin": "sù", "defs": [{"meaning": "恐惧颤抖的样子", "words": [{"w": "觫觫", "t": "恐惧的样子"}, {"w": "觳觫", "t": "因恐惧而发抖的样子"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5775wx','雒','1','luò','隹','14','','[{"pinyin": "luò", "defs": [{"meaning": "鸟名 。忌欺,即“鵋鶀”。", "cites": [{"t": "雒,鵋鶀也。怪鸱。", "b": "《说文》。今称鸺鶹,也叫横纹小鴞"}], "words": [{"w": "雒诵", "t": "反复诵读。"}]}, {"meaning": "白鬃的黑马。"}, {"meaning": "净古都邑名 。今址河南省洛阳。汉光武建都改名雒阳。"}, {"meaning": "古地名。西汉时置为雒县。自古为争蜀的战略要地。三国时刘备即因破雒城而得成都 。今址四川省广汉县北。"}, {"meaning": "印烙", "cites": [{"t": "烧之,剔之,刻之,雒之。", "b": "《庄子》"}]}, {"meaning": "用网状物兜住头。", "cites": [{"t": "烧之、剔之、刻之、雒之。", "b": "《庄子·马蹄》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5776wx','夤','1','yín','夕','14','','[{"pinyin": "yín", "defs": [{"meaning": "恭敬。", "cites": [{"t": "夤,敬惕也。从夕,寅声。", "b": "《说文》。按,即寅之别体。因寅为借义所专,别制此字。"}], "words": [{"w": "夤畏", "t": "敬畏"}, {"w": "夤亮", "t": "恭敬信奉。"}]}, {"meaning": "夹脊肉。", "cites": [{"t": "艮其限,列其夤。", "b": "《易·艮》。马注:“夹脊肉也。”"}]}, {"meaning": "远处。", "cites": [{"t": "九州之外,乃有八夤。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5777wx','馑','1','jǐn','饣','14','','[{"pinyin": "jǐn", "defs": [{"meaning": "(形声。从食,堇(qín)声。本义:蔬菜和野菜都吃不上)。"}, {"meaning": "同本义。", "cites": [{"t": "馑,蔬不熟曰馑。", "b": "《说文》"}, {"t": "可食之菜,皆不熟为馑。", "b": "《尔雅·释天》李注"}, {"t": "或纷扰之际,或荒馑之余;威惠所加,罔不和辑。", "b": "唐·白居易《除李逊京兆尹制》"}]}, {"meaning": "谷物欠收。", "cites": [{"t": "一谷不收谓之馑,二谷不收谓之旱。", "b": "《墨子·七患》"}, {"t": "二谷不升谓之饥,三谷不升谓之馑。", "b": "《谷梁传·襄公二十四年》"}]}, {"meaning": "饿死。饿死的人。", "cites": [{"t": "夫饿馑流隶,饥寒道路,思有短褐之袭,檐石之蓄。", "b": "《文选·班彪·王命论》"}]}, {"meaning": "缺乏。", "cites": [{"t": "多者不独衍,少者不独馑。", "b": "《盐铁论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5778wx','銮','1','luán','金','14','','[{"pinyin": "luán", "defs": [{"meaning": "(形声。从金,羉(luán)声。本义:古时皇帝车驾所用的铃)。"}, {"meaning": "古代皇帝车的仪铃,安装在轭首或车衡上方。上部一般为扁圆形的铃,铃内有弹丸,铃上有辐射状的镂孔。下部为长方形的座;座的两面常有钉孔。西周时开始流行。", "cites": [{"t": "人君乘车四马四镳八銮,铃象鸾,鸟声,和则敬也。", "b": "《说文》"}, {"t": "升车则有銮和之音。", "b": "《礼记·经解》"}, {"t": "銮声哕哕。", "b": "《东京赋》"}], "words": [{"w": "銮刀", "t": "系有响铃的刀子"}, {"w": "銮辂", "t": "装饰有响铃的车子"}, {"w": "銮音", "t": "响铃的声音"}, {"w": "銮声", "t": "铃声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5779wx','塾','1','shú','土','14','','[{"pinyin": "shú", "defs": [{"meaning": "(形声。从土,孰声。本义:古时门内东西两侧的堂屋)。"}, {"meaning": "宫门外两侧房屋,为臣僚等候朝见皇帝之处。", "cites": [{"t": "先辂在左塾之前,次辂右塾之前。", "b": "《书·顾命》"}]}, {"meaning": "古时又指门内东西两侧的屋。", "cites": [{"t": "春,[将]出民,里胥平旦于右塾,邻长坐于[左]塾,毕出然后归,夕亦如之。", "b": "《汉书·食货志上》"}]}, {"meaning": "旧时私人设立的学校。", "cites": [{"t": "老人邻有西塾,闻其师为弟子说前代事。", "b": "清·周容《芋老人传》"}]}, {"meaning": "射垛,箭靶。", "cites": [{"t": "使长安中官署及天下乡亭皆画伯升象于塾,旦起射之。", "b": "《后汉书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5780wx','麽','1','mó','麻','14','','[{"pinyin": "mó", "defs": [{"meaning": "细小,也合称幺麽", "words": [{"w": "麽虫", "t": "细小的虫"}, {"w": "麽人", "t": "小人,奸邪之人"}, {"w": "麽麽", "t": "微细的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5781wx','瘌','1','là','疒','14','','[{"pinyin": "là", "defs": [{"meaning": "痛。", "cites": [{"t": "瘌,楚人谓药毒曰痛瘌。从疒,剌声。", "b": "《说文》"}, {"t": "瘌,痛也。凡饮药傅药而毒,南楚之外谓之瘌。", "b": "《方言三》"}]}, {"meaning": "瘌痢,疥疮。俗称头生恶疮,使发秃者为瘌,或作“癞”。", "cites": [{"t": "瘌,疥也。", "b": "《集韵》"}], "words": [{"w": "瘌子", "t": "淮汉一带称因头生疮而发秃的人为瘌子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5782wx','瘊','1','hóu','疒','14','','[{"pinyin": "hóu", "defs": [{"meaning": "病毒感染，在皮肤上长出无痛痒的小疙瘩。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5783wx','瘘','1','lòu','疒','14','','[{"pinyin": "lòu", "defs": [{"meaning": "颈肿大的病。即颈部淋巴结核。", "cites": [{"t": "合水多鰧鱼,状如鳜…食者不痈,可以瘘。", "b": "《山海经》。郭璞注:“瘘,痈属也。”"}]}, {"meaning": "瘘管 。人或动物体深部脓肿,体表或脏器之间形成的管道。病灶分泌物由此管流出。", "cites": [{"t": "瘘,即漏也。经年成漏者,在颈则曰瘰瘘,在痔则曰痔瘘。", "b": "明·楼英《医学纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5784wx','瘙','1','sào','疒','14','','[{"pinyin": "sào", "defs": [{"meaning": "古代指疥疮。", "cites": [{"t": "瘙,疮瘙。", "b": "《广韵》"}], "words": [{"w": "瘙疳", "t": "疮名。性病的一种。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5785wx','廖','1','liào','广','14','','[{"pinyin": "liào", "defs": [{"meaning": "古国名。", "cites": [{"t": "南阳郡,县三十六:…湖阳[县],故廖国也。", "b": "《汉书》"}]}, {"meaning": "", "cites": [{"t": "廖,人姓也。古今人表廖叔安。", "b": "《说文新附》。按,以国为氏。"}]}, {"meaning": "假借为“寥”。空旷。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5786wx','韶','1','sháo','音','14','','[{"pinyin": "sháo", "defs": [{"meaning": "(形声。从音,召声。本义:传说中的虞舜时代的乐曲名)。"}, {"meaning": "传说舜所作的乐曲名。", "cites": [{"t": "韶,虞舜乐也。", "b": "《说文》"}, {"t": "箫韶九成。", "b": "《虞书》"}, {"t": "九韶之舞。", "b": "《周礼·大司乐》"}, {"t": "舞(韶)歌(武),使人之心庄。", "b": "《荀子·乐论》"}], "words": [{"w": "韶武", "t": "韶,虞舜之乐;武,武王之乐"}, {"w": "韶虞", "t": "舜乐。"}]}, {"meaning": "古乐的通称。", "cites": [{"t": "韶,夏、商乐皆有韶名。韶者,乐之通名也。", "b": "《正字通》"}]}, {"meaning": "美好。", "cites": [{"t": "昭,美也。", "b": "《集韵》"}, {"t": "韶颜稚齿。", "b": "蒋防《霍小玉传》"}, {"t": "东皇去后韶华尽。", "b": "戴叔伦《暮春感怀》"}, {"t": "何其轩轩韶举。", "b": "《世说新语·容止》"}, {"t": "暮春美景,风云韶丽。", "b": "简文帝《答湘东王书》"}], "words": [{"w": "韶令", "t": "美好良善"}, {"w": "韶曼", "t": "美色。韶、曼都是美的意思"}, {"w": "韶华", "t": "春光。美好的时光;指人的青春年华"}, {"w": "韶颜", "t": "美好的容貌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5787wx','旖','1','yǐ','方','14','','[{"pinyin": "yǐ", "defs": [{"meaning": "1.柔和美丽的样子风光～旎。2.旌旗随风飘扬的样子彩旗～旎。", "cites": [{"t": "旖旎从风。--《史记·司马相如列传》", "b": ""}, {"t": "顾青翠之茂叶，繁旖旎之弱条。--成公绥《木兰赋》", "b": ""}, {"t": "说不尽软玉温香，娇柔旖旎。--《梼杌闲评--明珠缘》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5788wx','膂','1','lǚ','月','14','','[{"pinyin": "lǚ", "defs": [{"meaning": "(形声。从肉,旅声。本义:脊梁骨) 同本义。", "cites": [{"t": "膂,篆文吕从肉,从旅。", "b": "《说文》"}, {"t": "今命尔予翼,作股肱心膂。", "b": "《书·君牙》"}, {"t": "而使内处心膂,外总兵权。", "b": "《文选·庾亮让中书令表》注引贾逵《国语》注:“膂,脊也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5789wx','阚','1','kàn','门','14','','[{"pinyin": "kàn", "defs": [{"meaning": "望。", "cites": [{"t": "阚,望也。从门,敢声。望或倚门倚闾,故从门。字亦作瞰,作矙。", "b": "《说文》"}, {"t": "阚,视也。", "b": "《广雅》"}, {"t": "俯阚海湄。", "b": "嵇康《琴赋》"}], "words": [{"w": "俯阚", "t": "俯览,向下看。"}]}, {"meaning": "探望,看望。", "cites": [{"t": "禹于是疏河决江,十年未阚其家。", "b": "《尸子·君治》"}]}, {"meaning": "古地名 。在今山东省汶上县。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5790wx','鄯','1','shàn','阝','14','','[{"pinyin": "shàn", "defs": [{"meaning": "鄯善。古西域国名。", "cites": [{"t": "鄯善,西胡国也。", "b": "《说文》。按,本西域楼兰国,汉昭帝元凤四年诛其王更名。"}]}, {"meaning": "原名楼兰。汉昭帝元凤改楼兰为鄯善。故城在今新疆鄯善县东南。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5791wx','鲞','1','xiǎng','鱼','14','','[{"pinyin": "xiǎng", "defs": [{"meaning": "干鱼;腊鱼。", "cites": [{"t": "石首鲞,食之消瓜成水。", "b": "晋·王羲之《杂帖五》"}], "words": [{"w": "鲞鹤", "t": "即勒鱼做成的鱼干"}, {"w": "鲞铺", "t": "卖干鱼、腌腊食品的店铺。"}]}, {"meaning": "腌腊食品。", "cites": [{"t": "凤姐儿听说,依言夹些茄鲞,送入刘姥姥口中。", "b": "《红楼梦》"}], "words": [{"w": "鲞腊", "t": "干腊鱼肉。"}]}]}]','jingmo-wenyan');
