INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5795wx','糁','1','sǎn shēn','米','14','','[{"pinyin": "sǎn", "defs": [{"meaning": "米粒;饭粒。", "cites": [{"t": "厨乏聚蝇之糁。", "b": "《续传灯录》"}], "words": [{"w": "糁粒", "t": "米粒。"}]}, {"meaning": "以米和羹。", "cites": [{"t": "七日不食,藜羹不糁。", "b": "刘向《说苑·杂言》"}]}, {"meaning": "洒,散落。", "cites": [{"t": "六街惊糁,阿香车里行雷。", "b": "《三宝太监西洋记通俗演义》"}], "words": [{"w": "糁盘", "t": "宋代风俗,除夕祭祀祖先及百神,在庭院架松柴齐屋,举火焚之。"}]}, {"meaning": "涂抹;粘。", "cites": [{"t": "左刻“清风徐来,水波不兴”,石青糁之。", "b": "明·魏学洢《核舟记》"}]}]}, {"pinyin": "shēn", "defs": [{"meaning": "谷类磨成的碎粒。", "cites": [{"t": "一人一碗玉茭、高粱糁糊糊,里边煮着几块山药。", "b": "《结婚现场会》"}], "words": [{"w": "玉米糁;糁盆", "t": "以麻籸为燃料的照明火盆;旧俗岁时送神或祠祭、燕设,燃火于门外以祀神,兼取旺盛之相,亦谓之籸盆,燃料不限于麻籸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5796wx','槊','1','shuò','木','14','','[{"pinyin": "shuò", "defs": [{"meaning": "(形声。从木,朔声。本义:古代兵器,即长杆矛) 同“矟”。长杆矛。", "cites": [{"t": "此非孟德之困于周郎者乎?…酾酒临江,横槊赋诗,固一世之英雄,而今安在哉?", "b": "宋·苏轼《前赤壁赋》"}]}]}]','jingmo-wenyan');
