INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5800wx','潢','1','huáng','氵','14','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从水,黄色。本义:积水池)。"}, {"meaning": "同本义。", "cites": [{"t": "潢,积水池也。", "b": "《说文》"}, {"t": "潢汙行潦之水。", "b": "《左传·隐公三年》。注:“蓄水谓之潢。”"}, {"t": "犹塞川原而为潢污也。", "b": "《国语·周语》。注:“大曰潢,小曰污。”"}, {"t": "盗弄陛下之兵于潢池中耳。", "b": "《汉书·龚遂传》"}], "words": [{"w": "潢汙", "t": "积水的低洼地"}, {"w": "潢洋", "t": "水流深广、宽阔的样子"}, {"w": "潢井", "t": "沼泽低洼地带"}, {"w": "潢潦", "t": "地上流淌的雨水。"}]}, {"meaning": "港汊。", "cites": [{"t": "海道多潢,犹陆地多歧。", "b": "清·朱彝尊《日下旧闻补遗》"}]}, {"meaning": "古水名。"}, {"meaning": "潢河,即今天的辽宁省西拉木伦河。"}, {"meaning": "潢水,俗呼小黄河,源出湖北麻城,东流经河南入淮。"}, {"meaning": "染纸。", "cites": [{"t": "潢,染书也。故唐有妆潢匠。", "b": "《广韵》引《释名》"}], "words": [{"w": "潢纸", "t": "染纸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5801wx','漕','1','cáo','氵','14','','[{"pinyin": "cáo", "defs": [{"meaning": "(形声。从水,曹声。本义:通过水道运送粮食) 同本义。", "cites": [{"t": "漕,水转谷也。一曰人之所乘及船也。", "b": "《说文》。按,车运谷曰转,水运谷曰漕。"}, {"t": "漕转山东粟。", "b": "《史记·平准书》"}, {"t": "转漕给军。", "b": "《史记·萧相国世家》"}, {"t": "穿漕渠通渭。", "b": "《汉书·武帝纪》"}, {"t": "岁漕关东谷。", "b": "《汉书·食货志》"}, {"t": "关东漕粟。", "b": "《史记·河渠记》"}], "words": [{"w": "漕船", "t": "运输官粮的船只"}, {"w": "漕粮", "t": "清初自山东、河南、江苏、安徽、浙江、湖北、湖南、奉天等省征纳白米,转运京师,叫做“漕粮”。"}]}, {"meaning": "可供运输的河道。", "cites": [{"t": "今日听了这些话,心里方才水落归漕。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5802wx','滹','1','hū','氵','14','','[{"pinyin": "hū", "defs": [{"meaning": "滹沱 。水名,即滹沱河,在河北省西部。亦作滹沲", "words": [{"w": "滹沱麦饭", "t": "称粥或麦饭为“滹沱饭”或“滹沱麦饭”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5803wx','漯','1','lěi luò tà','氵','14','','[{"pinyin": "lěi", "defs": [{"meaning": "古水名。又名治水 。上游为今桑干河、中段为永定河、下游为海河之河流。发源于山西省神池县东,向东流经河北省至天津入海。"}]}, {"pinyin": "luò", "defs": []}, {"pinyin": "tà", "defs": [{"meaning": "漯河,古水名 ,在山东省。"}]}]','jingmo-wenyan');
