INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5806wx','潴','1','zhū','氵','14','','[{"pinyin": "zhū", "defs": [{"meaning": "(形声。从水,猪声。本义:水停聚的地方) 同本义。", "cites": [{"t": "以潴畜水。", "b": "《周礼·地官·稻人》"}], "words": [{"w": "潴泺", "t": "湖泊。"}]}, {"meaning": "蓄积。", "cites": [{"t": "渚水潴涨,方广数里。", "b": "《水经注》"}], "words": [{"w": "潴水", "t": "蓄水"}, {"w": "潴泄", "t": "蓄水和放水"}, {"w": "潴畜,潴蓄", "t": "指蓄洪贮水"}, {"w": "潴溉", "t": "蓄聚灌溉。"}]}, {"meaning": "指水停聚。", "cites": [{"t": "[星宿海] 流出复潴,曰哈剌海。", "b": "《宋史》"}], "words": [{"w": "潴淤", "t": "停聚淤泥"}, {"w": "潴潦", "t": "聚汇的水;停积的水。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5807wx','漪','1','yī','氵','14','','[{"pinyin": "yī", "defs": [{"meaning": "(形声。从水,猗(yī)声。本义:水的波纹)。"}, {"meaning": "同本义。", "cites": [{"t": "风值水而漪生,日薄山而岚出。", "b": "袁宏道《叙呙氏家绳集》"}], "words": [{"w": "漪如", "t": "水波潋滟貌"}, {"w": "漪涣", "t": "指粼粼波光"}, {"w": "漪流", "t": "微波起伏的流水"}, {"w": "漪沦", "t": "微波"}, {"w": "漪漪", "t": "水波荡漾貌"}, {"w": "漪澜", "t": "水波。"}]}, {"meaning": "岸边。", "cites": [{"t": "子胥即止芦之漪。", "b": "《吴越春秋》"}]}, {"meaning": "水波动。", "cites": [{"t": "激水不漪,槁木无阴,自然之势也。", "b": "《文心雕龙》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5808wx','漉','1','lù','氵','14','','[{"pinyin": "lù", "defs": [{"meaning": "使干涸,竭尽。", "cites": [{"t": "漉,浚也。从水,鹿声。", "b": "《说文》"}, {"t": "毋漉陂池。", "b": "《礼记·月令》。释文:“渴也。”"}, {"t": "林焚池漉。", "b": "王充《论衡》"}], "words": [{"w": "漉池", "t": "使池水干涸"}, {"w": "漉汔", "t": "使干涸竭尽。"}]}, {"meaning": "水漫漫地渗下。", "cites": [{"t": "漉汁洒地,白汗交流。", "b": "《战国策·楚策》"}, {"t": "滋液渗漉。", "b": "《卦禅文》"}], "words": [{"w": "漉血", "t": "流血,洒血"}, {"w": "漉湿", "t": "淋湿。"}]}, {"meaning": "山脚。", "cites": [{"t": "其林其漉,其槐其楝。", "b": "《管子·地员》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5809wx','漳','1','zhāng','氵','14','','[{"pinyin": "zhāng", "defs": [{"meaning": "水名。", "cites": [{"t": "漳,浊漳,出上党长子鹿谷山东入清漳。", "b": "《说文》"}, {"t": "清漳,出沾山大要谷北入河。", "b": "《说文》"}]}, {"meaning": "即漳水有二源:一称浊漳水,发源于山西省长子县,东北流至襄垣县北,东南流入河南省林县北界,与清漳水合;一称清漳水,发源于山西省昔阳县南,南流入河南省林县北界,与浊漳水合。"}, {"meaning": "古州名 。唐垂拱二年置,治所在福建省漳浦县,乾元初,移治龙溪,即今漳州市。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5810wx','漩','1','xuán','氵','14','','[{"pinyin": "xuán", "defs": [{"meaning": "(形声。从水,旋声。本义:回旋的水流) 同本义。", "cites": [{"t": "水理漩洑,鹏风翱翔。", "b": "唐·司空图《诗品》"}], "words": [{"w": "漩纹", "t": "回环的纹路。"}]}, {"meaning": "水流旋转。", "cites": [{"t": "龙归窟穴深潭漩,蜃作波涛古岸鐀。", "b": "唐·元稹《遭风二十韵》"}], "words": [{"w": "漩涡", "t": "水盘旋貌"}, {"w": "漩澓", "t": "水旋转回流。"}]}]}]','jingmo-wenyan');
