INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5812wx','潍','1','wéi','氵','14','','[{"pinyin": "wéi", "defs": [{"meaning": "水名。今称潍河 。在山东省东部,源出五莲县西南箕屋山,北流经诸城、高密等县,至昌邑县入莱州湾。", "cites": [{"t": "潍,潍水。出瑯邪箕屋山,东入海,徐州浸。《夏书》曰:“潍、淄其道。”", "b": "《说文》"}]}, {"meaning": "古州名。又县名 。即今山东省潍县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5813wx','慵','1','yōng','忄','14','','[{"pinyin": "yōng", "defs": [{"meaning": "(形声。从心,庸声。本义:懒惰,懒散)。"}, {"meaning": "同本义。", "cites": [{"t": "行旅畏威慵举步,佳人怕热懒登台。", "b": "《封神演义》"}], "words": [{"w": "慵妆媚态", "t": "因困倦懒梳妆而显出的娇媚姿态"}, {"w": "慵妆髻", "t": "比较随便地挽成的偏垂发髻"}, {"w": "慵困", "t": "懒散困倦"}, {"w": "慵眠", "t": "睡懒觉"}, {"w": "慵馋", "t": "好吃懒做"}, {"w": "慵来妆", "t": "古时女子一种娇媚的梳妆。"}]}, {"meaning": "用同“庸”。平庸,庸俗。", "cites": [{"t": "恐失英雄手,反惹慵夫刻画舟。", "b": "李开先《宝剑记》"}], "words": [{"w": "慵人", "t": "庸夫,平庸的人。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5814wx','搴','1','qiān','手','14','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从手,寒省声。本义:拔取)。"}, {"meaning": "同本义。", "cites": [{"t": "搴,取也。", "b": "《广韵》"}, {"t": "搴旗四麾。", "b": "《后汉书·杜笃传》"}, {"t": "斩将搴旗之士。", "b": "《史记·刘敬叔孙通传》"}, {"t": "寡人不席而坐地,二三子莫席,而子独搴草而坐之,何也?", "b": "《晏子春秋》"}, {"t": "搴大旗者。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "搴旗", "t": "拔取敌人军旗"}, {"w": "搴须", "t": "拔胡须"}, {"w": "搴条", "t": "拔取树枝。"}]}, {"meaning": "采摘。", "cites": [{"t": "搴芙蓉兮木末。", "b": "《楚辞·九歌·湘君》"}], "words": [{"w": "搴芳", "t": "采摘花草"}, {"w": "搴取", "t": "采摘"}, {"w": "搴采", "t": "采摘"}, {"w": "搴撷", "t": "采摘"}, {"w": "搴揽", "t": "摘取,采取。"}]}, {"meaning": "举。", "cites": [{"t": "士大夫虽也搴着大旗拥护精神文明。", "b": "朱自清《航船中的文明》"}]}, {"meaning": "撩起。", "cites": [{"t": "搴裳访古。", "b": "卢照邻《释疾文》"}], "words": [{"w": "搴涉", "t": "提衣涉水"}, {"w": "搴裳", "t": "犹褰裳。提起衣裳"}, {"w": "搴帷", "t": "撩起帷幕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5815wx','窨','1','xūn yìn','穴','14','','[{"pinyin": "xūn", "defs": [{"meaning": ",用于窨茶叶。把茉莉花等放在茶叶中,使茶叶染上花的香味。"}]}, {"pinyin": "yìn", "defs": [{"meaning": "(形声。从穴,音声。本义:地下室,地窖) 同本义。又称地窨子,地下室。", "cites": [{"t": "窨,地室也。", "b": "《说文》。徐锴曰:“今旧京谓地窖臧酒为窨。”"}, {"t": "蚕室,窨室也。", "b": "《后汉书·光武纪下》注"}, {"t": "三之日,纳于凌阴(窨)。", "b": "《诗·豳风·七月》"}]}, {"meaning": "窖藏;深藏。", "cites": [{"t": "趁墟窨酒担,跳月竹枝声。", "b": "清·赵翼《送人赴黔》"}], "words": [{"w": "窨藏", "t": "挖窖埋藏"}, {"w": "窨酒", "t": "在地窖里藏过的酒。"}]}, {"meaning": "思忖;揣度。", "cites": [{"t": "曾窨约,细评薄,将业兵功非小可。", "b": "元·马谦斋《柳营曲》"}], "words": [{"w": "窨忖", "t": "思忖;揣度"}, {"w": "窨附", "t": "思忖;揣度。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5816wx','寤','1','wù','宀','14','','[{"pinyin": "wù", "defs": [{"meaning": "同本义。", "cites": [{"t": "寤,寐觉而有言曰寤。", "b": "《说文》"}, {"t": "窈窕淑女,寤寐求之。", "b": "《诗·周南·关雎》"}], "words": [{"w": "寤言", "t": "醒后说话"}, {"w": "寤寐", "t": "指醒时和睡时"}, {"w": "寤宿", "t": "醒而卧;躺卧"}, {"w": "寤怀", "t": "睡不着而怀念"}, {"w": "寤辟", "t": "醒来以手拍胸"}, {"w": "寤叹", "t": "睡不着而叹息"}, {"w": "寤迁", "t": "刚刚醒来就迁移"}, {"w": "寤觉", "t": "睡醒。"}]}, {"meaning": "觉悟,认识到。", "cites": [{"t": "静言思之,寤擗有摽。", "b": "《诗·邶风·柏舟》"}, {"t": "而心尚未寤也。", "b": "《史记·李斯列传》"}, {"t": "身死东城,尚不觉寤。", "b": "《汉书·陈胜项籍传赞》"}, {"t": "欲一言而寤。", "b": "《淮南子·要略》"}, {"t": "哲王又不寤。", "b": "《楚辞·离骚》"}, {"t": "别为《音图》,用祛未寤。", "b": "郭璞《尔雅序》"}], "words": [{"w": "寤然", "t": "醒悟貌"}, {"w": "寤移", "t": "使觉悟而转变。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5817wx','綮','1','qǐ qìng','糸','14','','[{"pinyin": "qǐ", "defs": [{"meaning": "细密的缯帛。", "cites": [{"t": "綮,致缯也。", "b": "《说文》。段玉裁注:“凡细腻曰致。”"}]}, {"meaning": "戟衣。綮戟,古代官吏出行时前导的仪仗。也作“棨”。", "cites": [{"t": "如今百脚旗用以前导者,即有衣之戟谓之棨也。", "b": "朱骏声《说文通训定声》"}]}]}, {"pinyin": "qìng", "defs": [{"meaning": "——“肯綮”(kěnqìng):。"}, {"meaning": "筋肉结节处。"}, {"meaning": "喻事物的关键。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5818wx','谮','1','zèn','讠','14','','[{"pinyin": "zèn", "defs": [{"meaning": "(形声。从言,赞(zǎn)声。本义:无中生有地说人坏话) 同本义。", "cites": [{"t": "谮,谗也。", "b": "《玉篇》"}, {"t": "彼谮人者,谁适与谋?", "b": "《诗·小雅·巷伯》"}, {"t": "夫人谮公于齐侯。", "b": "《公羊传·庄公元年》。注:“如其事曰诉,加诬曰谗。”"}, {"t": "浸润之谮。", "b": "《论语·颜渊》"}, {"t": "处非道之位,被众口之谮。", "b": "《韩非子·奸劫弑臣》"}, {"t": "[牛金星]因谮其(李岩)欲反。", "b": "《明史》"}], "words": [{"w": "遭谮", "t": "遭到诽谤谗害"}, {"w": "谮语", "t": "谗言;说别人的坏话"}, {"w": "谮人", "t": "诬谗他人"}, {"w": "谮害", "t": "进谗言伤害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5819wx','褡','1','dā','衤','14','','[{"pinyin": "dā", "defs": [{"meaning": "横褡;小被。", "cites": [{"t": "褡,横褡,小被。", "b": "《广韵》"}]}, {"meaning": "衣服破旧的。", "cites": [{"t": "褡,衣敝也。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5820wx','褙','1','bèi','衤','14','','[{"pinyin": "bèi", "defs": [{"meaning": "古代中国的短外衣", "words": [{"w": "褙子", "t": "背子。一种由半臂或中单演变而成的上衣。始于唐,宋代男女皆穿,因使用和时间的不同,其形式变化甚多"}, {"w": "褙褡", "t": "无袖的上衣。俗称背心"}]}, {"meaning": "把布或纸一层一层地粘在一起", "words": [{"w": "褙裱", "t": "裱褙"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5821wx','褓','1','bǎo','衤','14','','[{"pinyin": "bǎo", "defs": [{"meaning": "(形声。从衣,保声。本义:婴儿的被子) 包裹婴儿的布或被。", "cites": [{"t": "緥,小儿衣也。", "b": "《说文》"}, {"t": "裼,褓也。", "b": "《诗·小雅·斯干》传"}, {"t": "但视褓中儿。", "b": "刘绩《征夫》"}], "words": [{"w": "褓乳", "t": "婴儿在襁褓中喂奶"}, {"w": "褓中儿", "t": "指婴儿"}, {"w": "褓衣", "t": "婴儿衣"}, {"w": "褓被", "t": "小儿被。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5822wx','褛','1','lǚ','衤','14','','[{"pinyin": "lǚ", "defs": [{"meaning": "(形声。从衣,娄声。本义:衣襟。《说文》:“衽也。”《方言》:“褛谓之衽。”郭璞注:“衣襟也。”)——“褴褛”:衣服破烂。也作蓝缕。又作褛裂(衣服破裂。褛为衣襟开口,所以形容衣服破裂)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5823wx','褊','1','biǎn pián','衤','14','','[{"pinyin": "biǎn", "defs": [{"meaning": "(形声。从衣,扁声。本义:衣带或衣服狭小)。"}, {"meaning": "同本义。", "cites": [{"t": "褊,衣小也。", "b": "《说文》"}, {"t": "带其褊矣。", "b": "《左传·昭公元年》"}, {"t": "衣不得褊。", "b": "王充《论衡》"}], "words": [{"w": "褊衫", "t": "袈裟"}, {"w": "褊衣", "t": "狭小的紧身衣。"}]}, {"meaning": "狭小。", "cites": [{"t": "以敝邑褊小,不足以容从者。", "b": "《左传·昭公元年》"}], "words": [{"w": "褊能", "t": "能力不足"}, {"w": "褊小", "t": "狭小。指地域、车船等不宽大。"}]}, {"meaning": "气量狭小;急躁。", "cites": [{"t": "维是褊心,是以为刺。", "b": "《诗·卫风·葛履》"}, {"t": "然卓性刚而褊。", "b": "《三国志·吕布传》"}], "words": [{"w": "褊迫", "t": "气量小;性子急"}, {"w": "褊心", "t": "心地狭窄"}, {"w": "褊忌", "t": "心胸狭小。"}]}]}, {"pinyin": "pián", "defs": [{"meaning": "衣小。", "cites": [{"t": "褊,衣小也。", "b": "《说文》"}, {"t": "褊,狭也。", "b": "《小尔雅》"}, {"t": "万人蒙之而不褊。", "b": "《淮南子·主术》"}, {"t": "包众容易谓之裕,反裕为褊。", "b": "《贾子道术》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5824wx','谯','1','qiáo qiào','讠','14','','[{"pinyin": "qiáo", "defs": [{"meaning": "城门上的望楼。", "cites": [{"t": "与战谯门中。", "b": "《汉书·陈胜传》"}, {"t": "早听得谯楼禁鼓,却转初更。", "b": "《水浒传》"}]}, {"meaning": "谯鼓(谯楼更鼓);谯橹(城门上的守望楼);谯阁(即谯楼)。"}, {"meaning": "瞭望。", "cites": [{"t": "独守丞与战谯门中。", "b": "《汉书·陈胜传》"}]}, {"meaning": "责备。", "cites": [{"t": "乡人谯之弗为动。", "b": "《韩非子·五蠹》"}]}, {"meaning": "姓。"}]}, {"pinyin": "qiào", "defs": [{"meaning": "责备;谴责。", "cites": [{"t": "谯娆,譊也。从言,焦声。", "b": "《说文》"}, {"t": "谯,呵也。", "b": "《广雅》"}, {"t": "誚让项羽。", "b": "《史记·樊哙传》。索隐:“责也。”"}, {"t": "不谯呵。", "b": "《史记·万石张叔传》"}, {"t": "另足荡游不作,老者谯之。", "b": "《管子·揆度》"}], "words": [{"w": "谯呵", "t": "大骂;申斥"}, {"w": "谯励", "t": "督责勉励"}, {"w": "谯怒", "t": "怒斥"}, {"w": "谯谕", "t": "责问并使晓谕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5825wx','谰','1','lán','讠','14','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从言,阑(lán)声。本义:抵赖)。"}, {"meaning": "同本义。", "cites": [{"t": "谰,诋谰也。", "b": "《说文》。按,以言抵阑,犹今言抵赖也。"}, {"t": "王阳病抵谰置辞。", "b": "《汉书·梁共王灵传》。注:“诬讳也。”"}, {"t": "亮谰辞曰:“囚等畏死,见诬耳。”", "b": "《新唐书》"}]}, {"meaning": "诬赖,诬陷。", "cites": [{"t": "诘其名实,观其离合,则是非之情,不可以相谰已。", "b": "董仲舒《春秋繁露》"}]}, {"meaning": "欺骗。", "cites": [{"t": "满谰诬天。", "b": "《汉书·谷永传》。注:“谓欺罔也。”"}, {"t": "使者十辈临按,余庆谩谰。", "b": "《新唐书·儒学传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5826wx','谲','1','jué','讠','14','','[{"pinyin": "jué", "defs": [{"meaning": "欺骗;诈骗。", "cites": [{"t": "譎,权诈也。", "b": "《说文》"}, {"t": "譎,欺也。", "b": "《广雅》"}, {"t": "而奸臣犹有所谲其辞矣。", "b": "《韩非子·定法》"}, {"t": "此人臣之所以谲主便私也。", "b": "《韩非子·孤愤》"}], "words": [{"w": "谲主", "t": "欺诳主上"}, {"w": "谲诳", "t": "欺诈诳骗"}, {"w": "谲数", "t": "诈术。"}]}, {"meaning": "判断,判别。", "cites": [{"t": "若夫谲德而定次,量能而授官。", "b": "《荀子·儒效》"}]}, {"meaning": "诡诈。", "cites": [{"t": "晋文公谲而不正。", "b": "《论语》"}], "words": [{"w": "谲计", "t": "奸计;诡计"}, {"w": "谲怪", "t": "诡谲狡诈"}, {"w": "谲数", "t": "诡谲的权术"}, {"w": "谲诡", "t": "怪异;变化多端。"}]}, {"meaning": "怪异。", "cites": [{"t": "瑰异谲诡。", "b": "张衡《东京赋》"}, {"t": "瑰姿谲起。", "b": "傅毅《舞赋》"}, {"t": "虚无谲诡,此乱道之根也。", "b": "王符《潜夫论》"}], "words": [{"w": "谲怪", "t": "奇特怪异"}, {"w": "谲觚", "t": "奇诡不正"}, {"w": "谲诡", "t": "怪诞,变化莫测"}, {"w": "谲诡不经", "t": "荒唐离奇而不合常理。也称怪诞不经。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5827wx','暨','1','jì','日','14','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从旦,既声。本义:太阳初升略现)。"}, {"meaning": "同本义。", "cites": [{"t": "暨,日颇见也。", "b": "《说文》。段玉裁注:“颇,头偏也。头偏则不能全见其面,故谓事之略然者曰颇,日颇见者,见而不全也。”"}]}, {"meaning": "和,与。", "cites": [{"t": "广州府余暨、南、番二县。", "b": "《广东军务记》"}], "words": [{"w": "李先生暨夫人", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5828wx','屣','1','xǐ','尸','14','','[{"pinyin": "xǐ", "defs": [{"meaning": "鞋子。", "cites": [{"t": "屣,履也。", "b": "《广雅》"}, {"t": "贫贱尔何忧,弃去如脱屣。", "b": "宋·苏轼《巫山》"}, {"t": "负箧曳屣。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "屣敝", "t": "破鞋。喻指无价值之物品"}, {"w": "屣脱", "t": "脱下鞋子"}, {"w": "屣履", "t": "拖着鞋子走路。"}]}, {"meaning": "穿着拖鞋走。", "cites": [{"t": "衣不及带,屣履出迎。", "b": "《后汉书·崔骃传》"}]}]}]','jingmo-wenyan');
