INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5830wx','嫣','1','yān','女','14','','[{"pinyin": "yān", "defs": [{"meaning": "(形声。从女,焉声。本义:美好的样子)。"}, {"meaning": "笑容美好。", "cites": [{"t": "嫣,巧笑态也。", "b": "《正字通》"}]}, {"meaning": "身材高大而美丽。", "cites": [{"t": "嫣,长美的样子。", "b": "《玉篇》"}], "words": [{"w": "嫣妍", "t": "美好的样子。"}]}, {"meaning": "颜色浓艳。", "cites": [{"t": "日斜柳暗花嫣。", "b": "冯延已《三台令》"}], "words": [{"w": "姹紫嫣红", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5831wx','嫱','1','qiáng','女','14','','[{"pinyin": "qiáng", "defs": [{"meaning": "(形声。从女,墙省声。本义:古代宫廷里地位次于妃的女官) 同本义。", "cites": [{"t": "宿有妃嫱嫔御焉。", "b": "《左传·哀公元年》"}, {"t": "备嫔嫱焉。", "b": "《国语·晋语》。注:“妇官也。”"}, {"t": "妃嫔媵嫱,王子皇孙。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "嫱媛", "t": "姬妾"}, {"w": "嫱施", "t": "古美女毛嫱、西施的并称。"}]}]}]','jingmo-wenyan');
