INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5833wx','嫦','1','cháng','女','14','','[{"pinyin": "cháng", "defs": [{"meaning": "后比喻美女。", "cites": [{"t": "羿请不死之药于西王母，嫦娥窃之以奔月。--《搜神记》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5834wx','嫚','1','mān màn','女','14','','[{"pinyin": "mān", "defs": [{"meaning": "[方言] 对女孩子的昵称", "words": [{"w": "小嫚", "t": ""}, {"w": "嫚子", "t": ""}]}]}, {"pinyin": "màn", "defs": [{"meaning": "(形声。从女,曼声。本义:轻侮,侮辱) 同本义。", "cites": [{"t": "嫚,侮嫚也。", "b": "《说文》"}, {"t": "陛下嫚而侮人。", "b": "《汉书·高帝纪》"}, {"t": "接遇肃正谓之敬,反敬为嫚。", "b": "《贾子道术》"}, {"t": "嫚令谨诛贼也。", "b": "《荀子·宥坐》"}], "words": [{"w": "嫚骂", "t": "恁意辱骂。又作谩骂"}, {"w": "嫚言", "t": "轻侮的言辞"}, {"w": "嫚易", "t": "轻侮,欺侮"}, {"w": "嫚逆", "t": "轻侮悖逆"}, {"w": "嫚辱", "t": "轻慢侮辱"}, {"w": "嫚书", "t": "轻侮的书信"}, {"w": "嫚侮", "t": "轻蔑侮辱"}, {"w": "嫚惰", "t": "轻慢,懒散"}, {"w": "嫚语", "t": "嫚辞,轻侮的言辞。"}]}, {"meaning": "假借为“慢”。怠慢,懈怠;迟缓。", "cites": [{"t": "其言僣嫚于鬼神。", "b": "《晏子春秋·外篇·重而异者》"}, {"t": "刑蕃而民愈嫚。", "b": "《汉书·刑法志》"}, {"t": "颂职解嫚。", "b": "《汉书·薛宣传》"}, {"t": "而职事不嫚。", "b": "《淮南子·主术》"}], "words": [{"w": "嫚臧", "t": "财物收藏不密,引起他人盗窃之念。泛指财物"}, {"w": "嫚令", "t": "法令松弛"}, {"w": "嫚法", "t": "法纪松弛"}, {"w": "嫚游", "t": "犹漫游。随意遨游。"}]}, {"meaning": "傲慢。", "cites": [{"t": "嫚生乎小人。", "b": "《淮南子·缪称》"}], "words": [{"w": "嫚戾", "t": "傲慢乖戾。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5835wx','嫘','1','léi','女','14','','[{"pinyin": "léi", "defs": [{"meaning": "姓。", "cites": [{"t": "嫘,姓也。黄帝娶于西陵氏之女,是为嫘祖。嫘祖好远游,死于道,后人祀以为行神。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5836wx','嫡','1','dí','女','14','','[{"pinyin": "dí", "defs": [{"meaning": "(形声。从女,啇(dí)声。本义:奴隶社会、封建社会中的正妻)。"}, {"meaning": "同本义。", "cites": [{"t": "齐公族多宠,嫡庶并行。", "b": "《列子·力命》"}], "words": [{"w": "嫡庶不分", "t": "妻妾亲疏不分"}, {"w": "嫡出", "t": "正妻所生"}, {"w": "嫡室", "t": "正妻"}, {"w": "嫡礼相待", "t": "像正妻一般对待。"}]}, {"meaning": "正妻生的长子称嫡子,省称“嫡”。", "cites": [{"t": "君家名父子,为晦翁嫡传。", "b": "戴复古《石屏集》"}], "words": [{"w": "嫡孙", "t": "嫡长孙"}, {"w": "嫡庶", "t": "嫡子与庶子;正妻与妾"}, {"w": "嫡妇", "t": "嫡长子之妻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5837wx','鼐','1','nài','鼎','14','','[{"pinyin": "nài", "defs": [{"meaning": "(形声。从鼎,乃声。本义:大鼎) 同本义。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5838wx','翟','1','dí zhái','羽','14','','[{"pinyin": "dí", "defs": [{"meaning": "翟羽 。古代乐舞所执雉羽。", "cites": [{"t": "舞人十六,执羽翟,以四为列。", "b": "《新唐书》"}]}, {"meaning": "姓。"}]}, {"pinyin": "zhái", "defs": [{"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5839wx','瞀','1','mào','目','14','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从目,敄(wù)声。本义:眼睛昏花)。"}, {"meaning": "同本义。", "cites": [{"t": "予少而游于六合之内,予适有瞀病。", "b": "《庄子·徐无鬼》"}, {"t": "昏瞀垫溺。", "b": "《书·益稷传》。疏:“眩惑之意。”"}], "words": [{"w": "瞀眩", "t": "眼花头晕;迷糊"}, {"w": "瞀瞑", "t": "目眩昏晕;晕厥。"}]}, {"meaning": "乱;错乱。", "cites": [{"t": "中闷瞀瞀忳忳。", "b": "屈原《惜诵》"}], "words": [{"w": "瞀见", "t": "愚昧错乱的见解。"}]}, {"meaning": "愚昧无知貌。", "cites": [{"t": "世俗之沟犹瞀儒。", "b": "《荀子·非十二子》"}], "words": [{"w": "瞀儒", "t": "愚昧无知的儒生。"}]}, {"meaning": "俯视,低目谨视。", "cites": [{"t": "瞀,低目谨视也。", "b": "《说文》"}, {"t": "汤又因瞀光而谋。", "b": "《庄子·让王》"}, {"t": "怨咽对风景,闷瞀守闺闼。", "b": "南朝宋·鲍照《绍古辞七首》"}], "words": [{"w": "好,我瞀我妹妹去", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5840wx','鹜','1','wù','鸟','14','','[{"pinyin": "wù", "defs": [{"meaning": "(形声。从鸟,敄(wù)声。本义:野鸭)。"}, {"meaning": "同本义。", "cites": [{"t": "鹜,野凫也。", "b": "《太平御览》引《说文》"}, {"t": "庶人之挚匹。", "b": "《礼记·曲礼下》。疏引李巡:“凫,家鸭名;鹜,野鸭名。”"}, {"t": "邹穆公有令,食凫鴈者必以粃。", "b": "贾谊《春秋》"}, {"t": "落霞与孤鹜齐飞,秋水共长天一色。", "b": "唐·王勃《滕王阁序》"}]}, {"meaning": "家鸭。", "cites": [{"t": "寨中人又鹜伏焉。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "鹜列", "t": "如鸭排列成行"}, {"w": "鹜舲", "t": "鹜形的小舟"}, {"w": "鹜溏", "t": "大便水粪青黑如鸭粪的一种病症"}, {"w": "鹜没", "t": "如鸭潜没水中。"}]}, {"meaning": "游水。", "cites": [{"t": "领水兵十余人,鹜水直抵南岸。", "b": "清·吴趼人《痛史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5841wx','骠','1','biāo piào','马','14','','[{"pinyin": "biāo", "defs": [{"meaning": "“黄骠马”(chuángbiāomǎ)。一种黄毛夹杂着白点子的马。"}]}, {"pinyin": "piào", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5842wx','缥','1','piāo piǎo','纟','14','','[{"pinyin": "piāo", "defs": [{"meaning": "飞扬。", "cites": [{"t": "凤缥缥其高逝兮。", "b": "《汉书·贾谊传》"}, {"t": "片片征云,五色旌旗缥缈。", "b": "《封神演义》"}], "words": [{"w": "缥缥", "t": "飘飘。轻举的样子"}, {"w": "缥乎", "t": "缥缈,缥缥。隐隐约约,若有若无。"}]}]}, {"pinyin": "piǎo", "defs": [{"meaning": "(形声。从糸,票声。糸(mì),细丝。本义:丝织物淡青色)。"}, {"meaning": "同本义。", "cites": [{"t": "缥,帛青白色也。", "b": "《说文》"}, {"t": "水皆缥碧,千丈见底。", "b": "吴均《与朱元思书》"}], "words": [{"w": "缥帙", "t": "浅青色的书衣。泛指书卷"}, {"w": "缥缃", "t": "书卷之别称。淡青色的帛为缥,淡黄色的帛为缃"}, {"w": "缥囊", "t": "浅青色的书袋"}, {"w": "缥瓦", "t": "琉璃瓦"}, {"w": "缥酒", "t": "酒名,一种绿色而微白的美酒"}, {"w": "缥粉", "t": "淡青色的粉末"}, {"w": "缥醪", "t": "酒名,一种浅青色的美酒"}, {"w": "缥玉", "t": "浅青色的玉"}, {"w": "缥色", "t": "淡青色"}, {"w": "缥瓷", "t": "清青色酒瓶"}, {"w": "缥被", "t": "淡青色的被"}, {"w": "缥带", "t": "淡青色的带子"}, {"w": "缥碧", "t": "浅青色。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5843wx','缦','1','màn','纟','14','','[{"pinyin": "màn", "defs": [{"meaning": "(形声。从糸(mì),曼声。从糸,与丝织品有关。本义:无花纹的丝织品)。"}, {"meaning": "同本义。", "cites": [{"t": "缦,绘无文也。", "b": "《说文》"}, {"t": "庶人衣缦。", "b": "《春秋·繁露》"}, {"t": "乘缦不举。", "b": "《国语·晋语》"}, {"t": "廊腰缦回。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "缦布", "t": "粗朴的布帛"}, {"w": "缦帛", "t": "没有文采的布帛"}, {"w": "缦胡", "t": "武士所系的素色无纹的缨带"}, {"w": "缦阁", "t": "用布帛搭成的楼阁。"}]}, {"meaning": ",宽缓;惰慢。", "cites": [{"t": "缦,缓缦。", "b": "《广韵》"}, {"t": "缦者,窖者、密者。", "b": "《庄子·齐物论》。注:“宽心也。”"}, {"t": "礼缓缓兮。", "b": "《尚书大传》"}]}, {"meaning": "注:“教化广远也。”。", "words": [{"w": "缦缦", "t": "沮丧的样子"}, {"w": "坚缦", "t": "步履坚定而缓慢。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5844wx','缧','1','léi','纟','14','','[{"pinyin": "léi", "defs": [{"meaning": "(形声。从糸(mì),表示与绳索有关,累声。本义:黑索) 同本义。", "cites": [{"t": "虽在缧絏之中。", "b": "《论语·公冶长》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5845wx','缨','1','yīng','纟','14','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从糸,婴声。本义:系在脖子上的帽带)。"}, {"meaning": "同本义。", "cites": [{"t": "缨,冠系也。", "b": "《说文》"}, {"t": "鲜冠组缨,绛衣博袍。", "b": "《墨子·公孟》"}, {"t": "正冠而缨绝。", "b": "《庄子·让王》"}, {"t": "沧浪之水清兮,可以濯吾缨。", "b": "《楚辞·渔父》"}, {"t": "戴朱缨宝饰之帽。", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "缨冠", "t": "把帽带连同帽子一齐加于头上。形容极为急迫,来不及整束。"}]}, {"meaning": "套马的革带,驾车用。引申指绳索。", "cites": [{"t": "咸龙旂而繁缨。", "b": "张衡《东京赋》。薛注:“缨,马鞅也。”"}, {"t": "鞶厉游缨。", "b": "《左传·桓公二年》。注:“缨,在马膺前如索帬。”"}, {"t": "以缨拾矢可也。", "b": "《礼记·曲礼下》。注:“缨,缨卷也。”"}], "words": [{"w": "缨缴", "t": "被系有绳子的箭所射中"}, {"w": "缨铰", "t": "捆绑人的绳子与枷锁。比喻拘限。"}]}, {"meaning": "缠绕、系牵", "cites": [{"t": "而不缨垢氛。", "b": "谢灵运《述祖德》。李善注:“缨,绕也。”"}], "words": [{"w": "缨情", "t": "犹系心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5846wx','骢','1','cōng','马','14','','[{"pinyin": "cōng", "defs": [{"meaning": "青白杂毛的马。今名菊花青马。", "cites": [{"t": "骢,马青白杂毛也。从马,悤声。", "b": "《说文》"}, {"t": "踯躅青骢马,流苏金镂鞍。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "骢马", "t": "青毛与白毛相间,淡青色的马。"}]}, {"meaning": "泛指马。", "cites": [{"t": "闻道乘骢发,沙边待至今。", "b": "杜甫诗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5847wx','缪','1','miào miù móu','纟','14','','[{"pinyin": "miào", "defs": [{"meaning": "姓。"}]}, {"pinyin": "miù", "defs": [{"meaning": "纰缪;错误。", "cites": [{"t": "多辞缪说,不耕而食,不织而衣。", "b": "《庄子·盗跖》"}], "words": [{"w": "缪舛", "t": "舛错,谬误"}, {"w": "缪戾", "t": "错舛,违背"}, {"w": "缪悠", "t": "妄诞不经"}, {"w": "缪说", "t": "荒谬错误的言论"}, {"w": "缪妄", "t": "荒缪无稽。"}]}, {"meaning": "穆然,静思。", "cites": [{"t": "孔子有所缪然思焉。", "b": "《孔子家语·辨乐》"}]}, {"meaning": "虔诚。", "cites": [{"t": "太公召公乃缪卜。", "b": "《史记·鲁周公世家》"}]}, {"meaning": "诈伪。", "cites": [{"t": "故相如缪与令相重。", "b": "《史记·司马相如列传》"}], "words": [{"w": "缪数", "t": "诈伪之术"}, {"w": "缪丑", "t": "宋秦桧之谥。借指奸佞。"}]}, {"meaning": "绞结。", "cites": [{"t": "其妻鲁人也,衣衰而缪緻。", "b": "《礼记·檀弓下》"}, {"t": "即自缪死。", "b": "《汉书·外戚传下》"}]}, {"meaning": "合力,并力。", "cites": [{"t": "昔我先君穆公及楚成王是(寔)缪力同心,两邦若壹,绊以婚姻。", "b": "秦·《诅楚文》"}]}, {"meaning": "缭绕。", "cites": [{"t": "缪绕玉绥。", "b": "《汉书·司马相如列传》"}]}]}, {"pinyin": "móu", "defs": [{"meaning": "(形声。从系(mì),本义:绸缪,缠绕)。"}, {"meaning": "(缠绵)。"}, {"meaning": "麻十束为缪。", "cites": [{"t": "缪,枲之十絜也。", "b": "《说文》。段玉裁注:枲即麻也,十絜犹十束也"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5848wx','缫','1','sāo','纟','14','','[{"pinyin": "sāo", "defs": [{"meaning": "煮茧抽丝。", "cites": [{"t": "夫人蚕缫,以为衣服。", "b": "《孟子·滕文公》"}], "words": [{"w": "缫车", "t": "缫丝用的器具"}, {"w": "缫盆", "t": "浸茧的盆。"}]}, {"meaning": "文彩;修饰。", "cites": [{"t": "五采缫,十有二就。皆五采,玉十有二,玉笄,朱紘。", "b": "《周礼·夏官·弁师》"}]}, {"meaning": "“繰”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5849wx','耦','1','ǒu','耒','15','','[{"pinyin": "ǒu", "defs": [{"meaning": "(形声。从耒,禺(yù或ǒu)声。耒(lěi),翻土工具。本义:二人并肩耕地)。"}, {"meaning": "同本义。", "cites": [{"t": "耦,耒广五寸为伐,二伐为耦。", "b": "《说文》"}, {"t": "十千维耦。", "b": "《诗·周颂·噫嘻》"}, {"t": "譬如农夫作耦。", "b": "《国语·吴语》"}, {"t": "禹见耕者耦立而式。", "b": "《荀子·大略》"}, {"t": "长沮、桀溺耦而耕。", "b": "《论语·微子》"}]}, {"meaning": "遇,逢。", "cites": [{"t": "燕成双,鸾对影,耦新知。", "b": "宋·孙光宪《酒泉子》"}]}, {"meaning": "双数,成对。", "cites": [{"t": "阳卦奇,阴卦耦。", "b": "《易系辞下》"}], "words": [{"w": "耦语", "t": "两个相对私语。同偶语"}, {"w": "耦俱无猜", "t": "两者均无疑恨"}, {"w": "耦立", "t": "犹对偶"}, {"w": "耦丽,耦俪", "t": "对耦的文辞。"}]}, {"meaning": "躯体。", "cites": [{"t": "南郭子綦隐机而坐,仰天而嘘,嗒焉似丧其耦。", "b": "《庄子》"}]}, {"meaning": "双,两个一组。", "cites": [{"t": "射者三耦。", "b": "《左传·襄公二十九年》"}, {"t": "耦俱无猜。", "b": "《左传·僖公九年》"}, {"t": "嗒焉似丧其耦。", "b": "《庄子·齐物论》"}]}, {"meaning": "和谐的;合。", "cites": [{"t": "齐心耦意。", "b": "严复《论中国之阻力与离心力》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5850wx','耧','1','lóu','耒','15','','[{"pinyin": "lóu", "defs": [{"meaning": "(形声。从耒,(lěi),娄声。从“耒”。表示与原始农具有关。本义:下种用的农具名,即“耧车”)同本义", "words": [{"w": "耧犁", "t": "即耧车"}, {"w": "耧锄", "t": "一种翻松土壤用的农具"}, {"w": "耧播", "t": "用耧车播种"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5851wx','瑾','1','jǐn','王','15','','[{"pinyin": "jǐn", "defs": [{"meaning": "(形声。从玉,堇(qín)声。本义:美玉)。"}, {"meaning": "同本义。", "cites": [{"t": "瑾瑜美玉也。", "b": "《说文》"}, {"t": "瑾瑜匿瑕。", "b": "《左传》"}, {"t": "捐赤瑾于中庭。", "b": "《楚辞·愍命》"}, {"t": "怀瑾握瑜。", "b": "《史记·屈原贾生列传》"}], "words": [{"w": "瑾瑜", "t": "瑾瑶。二美玉名。泛指美玉"}, {"w": "瑾瑕", "t": "瑾,美玉;瑕,有疵的玉。比喻美丑,优劣。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5852wx','璜','1','huáng','王','15','','[{"pinyin": "huáng", "defs": [{"meaning": "(形声。从玉,黄声。本义:半壁形的玉) 同本义。", "cites": [{"t": "璜,半璧也。", "b": "《说文》"}, {"t": "以元璜礼北方。", "b": "《周礼·大宗伯》"}, {"t": "夏后氏之璜。", "b": "《左传·定公四年》。注:“美玉名。”"}, {"t": "下有双璜冲牙。", "b": "《大戴礼记·保傅》"}, {"t": "璜台十成。", "b": "《楚辞·天问》"}], "words": [{"w": "璜佩", "t": "泛指玉佩"}, {"w": "璜台", "t": "用玉石装饰的楼台。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5853wx','璀','1','cuǐ','王','15','','[{"pinyin": "cuǐ", "defs": [{"meaning": "(形声。从玉,崔声。本义:璀璨:玉石有光泽,色彩鲜明) 同本义。", "cites": [{"t": "琪树璀璨而垂珠。", "b": "孙绰《游天台山赋》"}], "words": [{"w": "璀采", "t": "色彩鲜明"}, {"w": "璀璀", "t": "鲜明的样子"}, {"w": "璀错", "t": "文饰繁杂的样子"}, {"w": "璀玮", "t": "华丽。"}]}, {"meaning": "玉名。", "cites": [{"t": "璀,玉名。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5854wx','璎','1','yīng','王','15','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从玉,婴声。本义:似玉的美石) 同本义。", "cites": [{"t": "璎,璎琅,石似玉也。", "b": "《玉篇》"}, {"t": "璎,璎珞。", "b": "《广韵》"}, {"t": "即解颈众宝珠璎珞,价直百千两金而以与之。", "b": "《妙法莲华经普门品》"}], "words": [{"w": "璎珠", "t": "玉珠。用作饰物"}, {"w": "璎玑", "t": "珠玑。形容珍贵。"}]}]}]','jingmo-wenyan');
