INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5856wx','璋','1','zhāng','王','15','','[{"pinyin": "zhāng", "defs": [{"meaning": "(形声。从玉,章声。本义:古玉器名,形状象半个圭) 同本义。", "cites": [{"t": "璋,剡上为圭,半圭为璋。", "b": "《说文》"}, {"t": "秉璋以酢。", "b": "《书·顾命》"}, {"t": "大宗执璋。", "b": "《礼记·祭统》"}, {"t": "以赤璋礼南方。", "b": "《周礼·大宗伯》"}, {"t": "白玉不毁,孰为圭璋。", "b": "《庄子·马蹄》"}], "words": [{"w": "璋瓒", "t": "古代祭祀时打鬯酒的玉器,以璋为柄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5857wx','璇','1','xuán','王','15','','[{"pinyin": "xuán", "defs": [{"meaning": "(形声。从玉,旋声。本义:美玉)。"}, {"meaning": "同本义。", "cites": [{"t": "璿,美玉也。", "b": "《说文》"}, {"t": "天子之瑶:玉果、璇、珠、烛银、黄金之膏。", "b": "《穆天子传》"}, {"t": "桀作璇室、象廊,纣为倾官、鹿台。", "b": "《三国志·杨阜传》"}], "words": [{"w": "璇室", "t": "璇室。玉饰的宫室。一说能旋转的宫室;亦指传说中仙人的居所"}, {"w": "璇花", "t": "如玉的白花。比喻雪花。"}]}, {"meaning": "次于玉的石头。", "cites": [{"t": "璇,美石次玉。", "b": "《说文》"}, {"t": "若不能用玉,可用白璇珠。", "b": "《晋书》"}], "words": [{"w": ";璇玉(美玉一说次于玉的美石)璇源(琁源产珠的水流;亦指皇族)", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5858wx','奭','1','shì','大','15','','[{"pinyin": "shì", "defs": [{"meaning": "(会意兼形声。从大,从皕,皕亦声。皕(bì),二百,表示多。本义:盛)。"}, {"meaning": "同本义。", "cites": [{"t": "奭,盛也。", "b": "《说文》。按,此燕召公名。"}, {"t": "尔百姓其亦有安处,在彼宜在天命,囗及恻兴乱予保奭其介。", "b": "《逸周书》。朱右曾校释:“奭,盛”。# 赤色 [red]"}, {"t": "路车有奭。", "b": "《诗·小雅·采芑》"}, {"t": "帓郃有奭,以作六师。", "b": "《诗·小雅·瞻彼洛矣》"}]}, {"meaning": "突然或逐渐消失状;消散的样子。", "cites": [{"t": "然四解。", "b": "《庄子·秋水》"}], "words": [{"w": "奭然", "t": "消散的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5859wx','髯','1','rán','髟','15','','[{"pinyin": "rán", "defs": [{"meaning": "(形声。从髟,冉声。髟(biāo),长发下垂的样子。本义:两颊上的长须)。"}, {"meaning": "同本义;也泛指胡须。", "cites": [{"t": "髥,颊须也。从须从冄,会意,冄亦声。字亦作髥。", "b": "《说文》"}, {"t": "奋髥抵几。", "b": "《汉书·朱博传》。注:“颊毛也。”"}, {"t": "中峨冠而多髯者为东坡。", "b": "清·魏学洢《核舟记》"}], "words": [{"w": "髯夫", "t": "指脸上多须的人"}, {"w": "髯公", "t": "指年长多须的人"}, {"w": "髯奴", "t": "指多须的奴仆"}, {"w": "髯佛", "t": "称仁慈多须的人"}, {"w": "髯胡", "t": "须髯和颌下的垂肉"}, {"w": "髯翁", "t": "指年老多须的人"}, {"w": "髯须", "t": "指胡子"}, {"w": "髯髯然", "t": "髯须动摇的样子"}, {"w": "白发苍髯", "t": ""}]}, {"meaning": "须多或须长的人。", "cites": [{"t": "羽美须髯,故亮谓之髯。", "b": "《三国志》"}]}, {"meaning": "动物的须。", "cites": [{"t": "[上申之山] 其鸟多当扈,其状如雉,以其髯飞。", "b": "《山海经·西山经》。郭璞注:“髯,咽下须也。”"}]}, {"meaning": "蟒蛇。", "cites": [{"t": "越人得髯蛇以为上肴。", "b": "《淮南子·精神》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5860wx','髫','1','tiáo','髟','15','','[{"pinyin": "tiáo", "defs": [{"meaning": "(形声。从髟,召声,髟(biāo)头发下垂的样子。本义:小孩的下垂头发) 古时候小孩前额下垂的头发,引伸以指童年。", "cites": [{"t": "黄发垂髫,并怡然自乐。", "b": "陶潜《桃花源记》"}], "words": [{"w": "髫稚", "t": "幼童;幼稚"}, {"w": "髫草", "t": "指小儿,幼童"}, {"w": "髫儿", "t": "幼童,小孩"}, {"w": "髫岁", "t": "幼年,童年"}, {"w": "髫发", "t": "小儿垂发。引申为童年之称"}, {"w": "髫齿", "t": "幼年,童年"}, {"w": "髫龀", "t": "幼年"}, {"w": "髫辫", "t": "指童年。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5861wx','撷','1','xié','扌','15','','[{"pinyin": "xié", "defs": [{"meaning": "(形声。从手,颉(xié)声。本义:采摘)。"}, {"meaning": "同本义。", "cites": [{"t": "放翁日婆娑其间,掇其香以嗅,撷其颖以玩。", "b": "宋·陆游《东篱记》"}], "words": [{"w": "撷了泮芹", "t": "考中;入学"}, {"w": "撷芳", "t": "采摘花草"}, {"w": "撷取精华", "t": ""}]}, {"meaning": "把衣襟掖在腰带上以兜东西。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5862wx','撅','1','juē','扌','15','','[{"pinyin": "juē", "defs": [{"meaning": "用手把东西拨在一起。", "cites": [{"t": "撅,以手有所杷也。", "b": "《说文》"}]}, {"meaning": "拔起。", "cites": [{"t": "不涉不撅。", "b": "《礼记·内则》"}, {"t": "草木根荄浅,未必撅也。飘风兴,暴雨坠,则撅必先矣。", "b": "《韩诗外传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5863wx','赭','1','zhě','赤','15','','[{"pinyin": "zhě", "defs": [{"meaning": "红土。", "cites": [{"t": "赭,赤土也。", "b": "《说文》"}, {"t": "偷长以赭污其衣裙。", "b": "《汉书·张敞传》"}, {"t": "其土则丹青赭垩。", "b": "《文选·司马相如·子虚赋》"}], "words": [{"w": "赭垩", "t": "红土与白土。"}]}, {"meaning": "赤红如赭土的颜料,古人用以饰面。", "cites": [{"t": "赫如渥赭,公言赐爵。", "b": "《诗·邶风·简兮》"}]}, {"meaning": "“赭衣”的简称。", "cites": [{"t": "田叔钳赭,志于夷戮。", "b": "《宋书》"}], "words": [{"w": "赭徒", "t": "囚徒,犯人。因身穿赭衣,故称。"}]}, {"meaning": "山名 。在浙江省萧山县东北。山石呈赭色,故名。"}, {"meaning": "染成红色。", "cites": [{"t": "或赭其垣。", "b": "清·薛福成《观巴黎油画记》"}], "words": [{"w": "赭红袍", "t": "血溅衣袍,使成红色。比喻战斗激烈"}, {"w": "赭面", "t": "以赤色涂脸。亦指以赤色涂红的脸"}, {"w": "赭颜", "t": "因酒醉而脸红。"}]}, {"meaning": "因羞愧而脸红。", "cites": [{"t": "人戏称曰:“公之《春秋》,亦权倚阁乎?”秩色颇赭。", "b": "宋·彭乘《墨客挥犀》"}]}, {"meaning": "红色、赤红色。", "cites": [{"t": "赭,赤也。", "b": "《广雅·释器》"}, {"t": "桃汤赭鞭。", "b": "《汉书·王莽传》。师古曰:“赭,赤也。”"}], "words": [{"w": "赭袍", "t": "红袍"}, {"w": "赭衣", "t": "古时囚犯穿赤褐色衣,因以赭衣代称囚犯"}, {"w": "赭黄", "t": "天然的褐铁矿"}, {"w": "赭鞭", "t": "赤色的鞭"}, {"w": "赭衣塞路", "t": "比喻犯罪的人很多"}, {"w": "赭红、赭赤", "t": "红褐色。"}]}, {"meaning": "赤裸。", "cites": [{"t": "群饮源槁,回食野赭。", "b": "唐·柳宗元《晋问》"}]}]}]','jingmo-wenyan');
