('5866wx','撙','1','zǔn','扌','15','','[{"pinyin": "zǔn", "defs": [{"meaning": "抑制;挫折。", "cites": [{"t": "不卹是非然不然之情,以相荐撙。", "b": "《荀子》"}], "words": [{"w": "撙绌", "t": "撙诎。节制;谦逊"}, {"w": "撙节", "t": "抑制;节制"}, {"w": "撙衔", "t": "控制马勒,让马驯服"}, {"w": "撙御", "t": "撙衔。"}]}, {"meaning": "节省。", "cites": [{"t": "节饮食,撙衣服,则财用足。", "b": "《管子·五辅》"}], "words": [{"w": "撙用", "t": "节约用度"}, {"w": "撙度", "t": "节约用度"}, {"w": "撙制", "t": "节制,减省"}, {"w": "撙约", "t": "节俭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5867wx','撺','1','cuān','扌','15','','[{"pinyin": "cuān", "defs": [{"meaning": "[方言] 抛;扔", "words": [{"w": "撺箱", "t": "抛箱。宋元官府用箱子接纳状纸,告状人把状纸投入箱中,称撺箱"}]}, {"meaning": "匆匆忙忙地做"}, {"meaning": "长出", "words": [{"w": "撺茎", "t": "拔节"}]}, {"meaning": "怂恿,唆使别人去干坏事", "words": [{"w": "撺哄", "t": "怂恿,哄骗"}]}, {"meaning": "[方言] 发怒,发脾气", "words": [{"w": "他撺儿了", "t": ""}]}, {"meaning": "紧握。用同“攥”", "words": [{"w": "撺拳拢袖", "t": ""}]}, {"meaning": "跳。用同“蹿”", "words": [{"w": "撺行", "t": "奔跑"}]}, {"meaning": "逃走;乱跑", "words": [{"w": "撺行", "t": "奔跑"}]}, {"meaning": "用同“汆”。把食物放到沸水里稍微煮一下就捞出", "words": [{"w": "撺香螺", "t": ""}, {"w": "撺小鸡", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5868wx','墀','1','chí','土','15','','[{"pinyin": "chí", "defs": [{"meaning": "(形声。从土,犀(xī)声。本义:古代殿堂上经过涂饰的地面)。"}, {"meaning": "同本义。", "cites": [{"t": "墀,涂地也。", "b": "《说文》"}, {"t": "以丹漆地,故称丹墀。", "b": "《汉典职仪》"}, {"t": "故愿一登文石之陛,涉赤墀之涂。", "b": "《汉书》"}]}, {"meaning": "台阶上面的空地。也指台阶。", "cites": [{"t": "青琐丹墀。", "b": "《文选·张衡·西京赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5869wx','聩','1','kuì','耳','15','','[{"pinyin": "kuì", "defs": [{"meaning": "先天性耳聋。后泛指耳聋。", "cites": [{"t": "聩,生而聋也。从耳,贵声。", "b": "《说文》"}, {"t": "蕲州庞君安常善医则聩。", "b": "《东坡志林》"}, {"t": "聋聩不可使听。", "b": "《国语·晋语四》"}], "words": [{"w": "聩眊", "t": "耳聋眼花。引申为昏聩。"}]}, {"meaning": "昏聩,不明事理。", "cites": [{"t": "近愚则聩。", "b": "皮日休《耳箴》"}, {"t": "开聋启聩。", "b": "孔尚任《桃花扇》"}], "words": [{"w": "聩聩", "t": "胡涂无知,不明事理。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5870wx','觐','1','jìn','见','15','','[{"pinyin": "jìn", "defs": [{"meaning": "(形声。从见,堇(qín)声。本义:古代诸侯秋天朝见帝王)。"}, {"meaning": "朝见。"}, {"meaning": "诸侯秋季朝见天子或朝拜圣地。", "cites": [{"t": "诸侯秋朝曰觐。劳王事。", "b": "《说文》"}, {"t": "觐,见也。", "b": "《尔雅》"}, {"t": "秋见曰觐。", "b": "《周礼·大宗伯》"}, {"t": "天子当依而立,诸侯北面而见天子曰觐。", "b": "《礼记·曲礼》"}, {"t": "韩侯秋见天子曰觐。", "b": "《诗·大雅·韩奕》"}, {"t": "秋觐以比邦国之功。", "b": "《周礼》"}]}, {"meaning": "泛指诸侯朝见天子。", "cites": [{"t": "扶病觐。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "觐见三宫", "t": "指朝见太皇太后、太后及皇帝"}, {"w": "觐饷", "t": "觐见与饷宴"}, {"w": "觐岁", "t": "岁时朝觐"}, {"w": "觐岳", "t": "朝拜祭祀山岳"}, {"w": "觐礼", "t": "古代诸侯秋天朝见天子的仪式。"}]}, {"meaning": "进见,访谒。", "cites": [{"t": "宣子私觐于子产。", "b": "《左传·昭公十六年》"}], "words": [{"w": "觐接", "t": "谒见身分地位较高者以接近之"}, {"w": "觐省", "t": "探望双亲"}, {"w": "觐会", "t": "会见。"}]}]}]','jingmo-wenyan');
