INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5875wx','蕨','1','jué','艹','15','','[{"pinyin": "jué", "defs": [{"meaning": "蕨菜。", "cites": [{"t": "蕨,鳖也。从艸,厥声。", "b": "《说文》"}]}, {"meaning": "按,初生如蒜苗,无叶,端似鳖脚,故名,亦似小儿拳,故曰拳菜,紫黑色。”。", "cites": [{"t": "蕨,山菜也。周秦曰蕨,齐鲁曰鳖。", "b": "《齐民要术·蕨》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5876wx','蕤','1','ruí','艹','15','','[{"pinyin": "ruí", "defs": [{"meaning": "(形声。上形,下声。本义:草木花下垂) 同本义。", "cites": [{"t": "蕤,草木华垂貌。", "b": "《说文》"}]}, {"meaning": "衣服帐幔或其他物体上的悬垂饰物。", "cites": [{"t": "妾有绣腰襦,葳蕤自生光。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}, {"t": "大白冠、缁布之冠皆不蕤。", "b": "《礼记》"}]}, {"meaning": "花。", "cites": [{"t": "争抱寒柯看玉蕤。", "b": "苏轼《南乡子》"}]}, {"meaning": "花蕊。", "cites": [{"t": "此酒乃以百花之蕤,万木之汁,加以麟髓凤乳酿成。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5877wx','蕞','1','zuì','艹','15','','[{"pinyin": "zuì", "defs": [{"meaning": "战国时秦地 。在今陕西省临潼县东北。", "cites": [{"t": "蕞,地名。在秦,一曰在新丰。", "b": "《集韵》"}]}, {"meaning": "小的。", "cites": [{"t": "蕞,小貌。", "b": "《广韵》"}, {"t": "夫以蕞尔之驱,攻之者非一涂。", "b": "嵇康《养生论》"}], "words": [{"w": "蕞尔小邦", "t": "形容地域极小的国家"}, {"w": "蕞眇", "t": "短小,矮小。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5878wx','蕺','1','jí','艹','15','','[{"pinyin": "jí", "defs": [{"meaning": "又叫\\"鱼腥草\\"。多年生草本，有腥味，茎上有节，花小而密。全草可供药用。嫩茎与叶可作蔬菜。"}]}]','jingmo-wenyan');
