('5879wx','瞢','1','méng','目','15','','[{"pinyin": "méng", "defs": [{"meaning": "(会意。小篆字形。本义:目不明)。"}, {"meaning": "同本义。", "cites": [{"t": "甘枣之山有草焉,名曰萚,可以已瞢。(已:治好)", "b": "《山海经·中山经》"}], "words": [{"w": "瞢眊", "t": "形容老眼昏花"}, {"w": "瞢眩", "t": "昏乱;头昏眼花。"}]}, {"meaning": ""}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5880wx','蕃','1','bō fān fán','艹','15','','[{"pinyin": "bō", "defs": [{"meaning": "——吐蕃(Tǔbō)  我国古代少数民族。"}]}, {"pinyin": "fān", "defs": [{"meaning": ""}, {"meaning": "篱落;屏障。", "cites": [{"t": "四国于蕃,四方于宣。", "b": "《诗·大雅·崧高》"}, {"t": "夫蕃篱之鶠,岂能与之料天地之高哉?", "b": "宋玉《对楚王问》"}], "words": [{"w": "蕃蔽", "t": "屏障"}, {"w": "蕃篱", "t": "篱笆。引申为屏障。"}]}, {"meaning": "藩屏;捍卫。", "cites": [{"t": "故封建亲戚以蕃屏周。", "b": "《国语·楚语下》"}], "words": [{"w": "蕃杆", "t": "藩屏;护卫"}, {"w": "蕃辅", "t": "捍卫辅助"}, {"w": "蕃宣", "t": "本指藩篱与垣墙。引申为藩屏护卫"}, {"w": "蕃卫", "t": "捍卫。"}]}, {"meaning": "颊侧。", "cites": [{"t": "蕃者,颊侧也。", "b": "《灵枢经》。张志聪注:“蕃蔽在外。”"}]}, {"meaning": ""}]}, {"pinyin": "fán", "defs": [{"meaning": "同本义。", "cites": [{"t": "蕃,草茂也。", "b": "《说文》"}, {"t": "蕃衍盈升。", "b": "《诗·唐风·椒聊》"}, {"t": "庶草蕃庑。", "b": "《书·洪范》。传:“滋也。”"}, {"t": "繁启蕃长于春夏,畜积收藏于秋冬。", "b": "《荀子·天论》"}, {"t": "客莆田徐生为予三致其种,种之,生且蕃。", "b": "徐光启《甘薯疏序》"}], "words": [{"w": "蕃茂", "t": "草木繁盛"}, {"w": "蕃茏", "t": "草木繁盛"}, {"w": "蕃华", "t": "盛开的花。比喻青春年华。"}]}, {"meaning": "众多。", "cites": [{"t": "水陆草木之花,可爱者甚蕃。", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "蕃多", "t": "繁多"}, {"w": "蕃庶", "t": "众多"}, {"w": "蕃祉", "t": "多福,福泽深厚。"}]}, {"meaning": "白色。", "cites": [{"t": "周人黄马蕃鬣。", "b": "《礼记·明堂位》"}], "words": [{"w": "蕃马", "t": "白马"}, {"w": "蕃发", "t": "白发。"}]}, {"meaning": "繁殖;增长。", "cites": [{"t": "以蕃鸟兽。", "b": "《周礼·大司徒》"}, {"t": "其生不蕃。", "b": "《左传·僖公二十三年》"}, {"t": "蕃货长财,以佐助边费。", "b": "桓宽《盐铁论》"}], "words": [{"w": "蕃孕", "t": "蕃衍孳息,生息孕育"}, {"w": "蕃育", "t": "孳生长育"}, {"w": "蕃息", "t": "繁盛生长。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5881wx','蕲','1','qí','艹','15','','[{"pinyin": "qí", "defs": [{"meaning": "古州名 。北周始置,治所在齐昌(今湖北省蕲春县)。"}, {"meaning": "疆界。", "cites": [{"t": "跨天下而无蕲。", "b": "《荀子·儒效》"}]}, {"meaning": "祈求。", "cites": [{"t": "不蕲畜乎樊中。", "b": "《庄子·养生主》"}, {"t": "所以蕲有道行有义者。", "b": "《吕氏春秋·振乱》"}, {"t": "蕲胜于人。", "b": "唐·韩愈《朱文公校昌黎先生集》"}]}, {"meaning": "又。", "cites": [{"t": "蕲至于古之立言者。", "b": ""}], "words": [{"w": "蕲求", "t": "祈求。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5882wx','赜','1','zé','贝','15','','[{"pinyin": "zé", "defs": [{"meaning": "(形声。从匜(yí),责声。匜,下巴。本义:深奥,玄妙) 同本义。", "cites": [{"t": "圣人有以见天下之赜。", "b": "《易·系辞上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5883wx','槿','1','jǐn','木','15','','[{"pinyin": "jǐn", "defs": [{"meaning": "木名,即木槿 。锦葵科,落叶灌木。夏秋开花,花有白、紫、红诸色,朝开暮闭,栽培供观赏,兼作绿篱。花、皮可入药。茎的纤维可造纸。", "cites": [{"t": "颜如花落槿,鬓似雪飘蓬。", "b": "五代·张正见《白头吟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5884wx','樯','1','qiáng','木','15','','[{"pinyin": "qiáng", "defs": [{"meaning": "(形声。从木,墙省声。本义:桅杆)。"}, {"meaning": "同本义。", "cites": [{"t": "樯,杋柱也。", "b": "《埤苍》"}, {"t": "樯倾楫摧。", "b": "范仲淹《岳阳楼记》"}], "words": [{"w": "樯竿", "t": "船桅杆"}, {"w": "帆樯如林", "t": ""}]}, {"meaning": "借指船只。", "cites": [{"t": "灵樯千艘,雷辎万乘。", "b": "《宋书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5885wx','槭','1','qì','木','15','','[{"pinyin": "qì", "defs": [{"meaning": "木名 。槭属各种落叶乔木或灌木的泛称,其特征是对生单叶,掌状分裂,具有两个长翅的果实,木材坚韧。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5886wx','樗','1','chū','木','15','','[{"pinyin": "chū", "defs": [{"meaning": "臭椿", "words": [{"w": "樗栎", "t": "臭椿与柞树。比喻无用之材。多用于自谦之辞。也作樗材"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5887wx','樘','1','chēng táng','木','15','','[{"pinyin": "chēng", "defs": [{"meaning": "支柱。", "cites": [{"t": "樘,柱也。", "b": "《说文》"}]}]}, {"pinyin": "táng", "defs": [{"meaning": "(形声。从木,堂声。本义:门或窗的框子) 同本义 。如:门樘、窗樘。又作量词。门扇、窗扇、门框、窗框一副称一樘。如:一樘玻璃门。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5888wx','樊','1','fán','木','15','','[{"pinyin": "fán", "defs": [{"meaning": "(形声,棥声。“棥”意思是篱笆,在字中也具有表意作用。本义:篱笆)。"}, {"meaning": "同本义。", "cites": [{"t": "营营青蝇,止于樊。", "b": "《诗·小雅·青蝇》"}, {"t": "折柳樊圃。", "b": "《诗·齐风·东方未明》"}, {"t": "庄周游于雕陵之樊。", "b": "《庄子·山木》"}], "words": [{"w": "樊棘", "t": "荆棘篱笆"}, {"w": "樊鹿", "t": "樊篱中的鹿"}, {"w": "樊圃", "t": "有篱的园圃。"}]}, {"meaning": "关鸟兽的笼子。", "cites": [{"t": "泽雉十步一啄,百步一饮,不蕲畜乎樊中。", "b": "《庄子·养生主》"}], "words": [{"w": "樊槛", "t": "囚笼。"}]}, {"meaning": "领域;范围。", "cites": [{"t": "盖学虽粗涉其樊,其为说不能无弊而已。", "b": "清·方苞《内阁中书刘君墓表》"}]}, {"meaning": "旁,边际。", "cites": [{"t": "夏则休乎山樊。", "b": "《庄子·则阳》"}]}, {"meaning": "古地名。"}, {"meaning": "春秋周京都辖邑,一名阳樊,在今河南省济源县东南。"}, {"meaning": "樊城的简称。其城在湖北省襄樊市。"}, {"meaning": "筑篱围绕。", "cites": [{"t": "折柳樊圃,狂夫瞿瞿。", "b": "《诗·齐风·东方未明》"}]}, {"meaning": "纷杂。", "cites": [{"t": "樊然淆乱。", "b": "《庄子·齐物论》"}], "words": [{"w": "樊乱", "t": "樊然。纷乱"}, {"w": "樊萦", "t": "纷绕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5889wx','槲','1','hú','木','15','','[{"pinyin": "hú", "defs": [{"meaning": "即柞栎 。一种栎属落叶乔木,叶大,互生,阔倒卵形,粗缘,雌雄同株,花单性,雄花柔荑花序,雌花穗较短,坚果卵球形,壳斗杯状,材质坚硬,树皮及叶可作药用,分布于中国、朝鲜和日本。"}]}]','jingmo-wenyan');
