INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5891wx','醅','1','pēi','酉','15','','[{"pinyin": "pēi", "defs": [{"meaning": "(形声。从酉,咅(pǒu)声。从“酉”的字多与酒或因发酵而制成的食物有关。本义:醉饱)。"}, {"meaning": "同本义。", "cites": [{"t": "醅,醉饱也。", "b": "《说文》"}]}]}]','jingmo-wenyan');
