('5892wx','靥','1','yè','面','15','','[{"pinyin": "yè", "defs": [{"meaning": "(形声。从面,厌声。本义:面颊上的微涡)。"}, {"meaning": "同本义。", "cites": [{"t": "态生两靥之愁,娇袭一身之病。", "b": "《红楼梦》"}], "words": [{"w": "酒靥;笑靥;靥脯", "t": "颊边的酒窝。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5893wx','魇','1','yǎn','鬼','15','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从鬼,厌声。本义:梦中遇可怕的事而呻吟、惊叫)。"}, {"meaning": "同本义。", "cites": [{"t": "犹疑在波涛,怵惕梦成魇。", "b": "韩愈《陪杜侍御游湘西两寺独宿》"}], "words": [{"w": "魇魔", "t": "梦魇"}, {"w": "魇梦", "t": "恶梦"}, {"w": "魇语", "t": "讲梦话。"}]}, {"meaning": "迷糊;迷惑。", "cites": [{"t": "原来那师父被妖术魇住,不能行走,心上明白,只是口眼难开。", "b": "《西游记》"}], "words": [{"w": "魇魔法", "t": "魇魅"}, {"w": "魇镇", "t": "用咒语和法术镇压降伏邪祟的一种巫术"}, {"w": "魇样", "t": "以前把“魔术”、“妖法”、“预言”等都称为“魇样法”,即使用法术以幻象迷惑人"}, {"w": "魇住", "t": "睡梦中感到身不能动,口不能言,常发生惊叫现象"}, {"w": "魇祟", "t": "用妖术使人迷乱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5894wx','餍','1','yàn','飠','15','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从食,厌声。本义:吃饱)。"}, {"meaning": "同本义。", "cites": [{"t": "其良人出,则必餍酒肉而后反(返)。", "b": "《孟子》"}], "words": [{"w": "餍饫", "t": "饱食。也作厌饫"}, {"w": "餍饱", "t": "吃饱"}, {"w": "餍足", "t": "吃饱,饱足;满足。"}]}, {"meaning": "使满足。", "cites": [{"t": "苟为后义而先利,不夺不餍。", "b": "《孟子》"}], "words": [{"w": "餍服", "t": "使人完全信服"}, {"w": "餍见", "t": "饱见,多见"}, {"w": "餍禄", "t": "享受厚禄。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5895wx','磔','1','zhé','石','15','','[{"pinyin": "zhé", "defs": [{"meaning": "古代祭祀时分裂牲畜肢体。", "cites": [{"t": "磔,辜也。", "b": "《说文》。从桀,石声。刳鸡胸、腹而张之,令其干枯不收。故从桀"}, {"t": "磔,张也。", "b": "《广雅》"}, {"t": "旁磔。", "b": "《礼记·月令》。注:“攘也。”"}, {"t": "祭风曰磔。", "b": "《尔雅》。李注:“以牲头蹄及皮破之以祭。”"}, {"t": "[季春之月]九门磔攘。", "b": "《礼记·月令》。孙希旦集解:“磔,磔裂牲体也。”"}]}, {"meaning": "汉字书法之一,右下方的捺笔。", "cites": [{"t": "刮视字棱,相其波磔,似是八分书耳。", "b": "《阅微草堂笔记》"}]}, {"meaning": "鸟鸣声,同“吱吱”。", "cites": [{"t": "磔磔云霄间。", "b": "宋·苏轼《石钟山记》"}]}]}]','jingmo-wenyan');
