INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5901wx','觑','1','qù','见','15','','[{"pinyin": "qù", "defs": [{"meaning": "(形声。从见,虚声。本义:窥视,偷偷地看)。"}, {"meaning": "同本义。", "cites": [{"t": "狙击秦皇帝。", "b": "《史记·留侯世家》。以狙为之,字亦作觑。"}], "words": [{"w": "觑探", "t": "探看"}, {"w": "觑了她一眼", "t": ""}]}, {"meaning": "把眼睛眯成一条细缝。", "cites": [{"t": "刘姥姥也觑着眼看,口里不住地念佛。", "b": "《红楼梦》"}]}, {"meaning": "仔细瞄准。", "cites": [{"t": "花荣搭上箭,曳满弓,觑得亲切,望空中只一箭射去。", "b": "《水浒全传》"}]}, {"meaning": "离,距。", "cites": [{"t": "因而忧闷成疾,昼夜无眠;眼见的觑天远,入地近,无那活的人也。", "b": "《东堂老》楔子》"}]}, {"meaning": "瞧;看。", "cites": [{"t": "雯清说罢话,只把眼儿觑定彩云,看她怎么样。", "b": "《孽海花》"}], "words": [{"w": "觑绝", "t": "看了;看罢。"}]}]}]','jingmo-wenyan');
