INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5903wx','瞋','1','chēn','目','15','','[{"pinyin": "chēn", "defs": [{"meaning": "(形声。从目,真声。本义:睁大眼睛)。"}, {"meaning": "同本义。", "cites": [{"t": "瞋,张目也。", "b": "《说文》"}, {"t": "羽瞋目叱之。", "b": "《汉书·项籍传》"}, {"t": "画出瞋目而不见丘山。", "b": "《庄子·秋水》"}, {"t": "按剑瞋目。", "b": "《庄子·盗跖》"}], "words": [{"w": "瞋眸", "t": "瞪大眼珠。"}]}, {"meaning": "怒;生气。", "cites": [{"t": "瞋,怒也。", "b": "《广韵》"}, {"t": "炙手可热势绝伦,慎莫近前丞相瞋。", "b": "杜甫《丽人行》"}], "words": [{"w": "瞋怪", "t": "责怪"}, {"w": "瞋目大叱", "t": "怒目喝斥。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5904wx','瞑','1','míng','目','15','','[{"pinyin": "míng", "defs": [{"meaning": "闭上眼睛。", "cites": [{"t": "瞑,翕目也。", "b": "《说文》"}, {"t": "然后得瞑些。", "b": "《楚辞·招魂》"}, {"t": "据槁梧而瞑。", "b": "《庄子·德充符》"}, {"t": "迅雷不及掩耳,迅電不及瞑目。", "b": "《六韬·龙韬·军势》"}, {"t": "内怀殷忧,则达旦不瞑。", "b": "嵇康《养生论》"}, {"t": "目似瞑。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "瞑目蹲身", "t": "闭上眼睛,身体后蹲;起跳前的动作"}, {"w": "瞑睫", "t": "合目"}, {"w": "瞑坐", "t": "闭目静坐"}, {"w": "瞑拜", "t": "闭目合掌行跪拜礼以示虔诚。"}]}, {"meaning": "睡觉,打瞌睡。", "cites": [{"t": "神农隐几阖户昼瞑。", "b": "《庄子·知北游》"}, {"t": "内怀殷忧,则达旦不瞑。", "b": "嵇康《养生论》"}]}, {"meaning": "昏暗。", "cites": [{"t": "瞑目。", "b": "《素问·气厥论》"}], "words": [{"w": "瞑瞑", "t": "昏暗迷乱的样子"}, {"w": "瞑眴", "t": "昏乱貌"}, {"w": "瞑卧", "t": "昏睡。"}]}, {"meaning": "眼睛昏花的。", "cites": [{"t": "臣耳目聋瞑,不能自励。", "b": "房玄龄《晋书》"}], "words": [{"w": "瞑然", "t": "模模糊糊地"}, {"w": "瞑士", "t": "盲人"}, {"w": "瞑臣", "t": "春秋晋盲乐师师旷的自称。"}]}]}]','jingmo-wenyan');
