INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5906wx','噎','1','shā yē','口','15','','[{"pinyin": "shā", "defs": [{"meaning": "亦作“傻”。极,非常。", "cites": [{"t": "老汉庄中田土甚广,客户噎少。", "b": "《刘知远诸宫调》"}]}, {"meaning": "亦作“煞”。虽然。", "cites": [{"t": "这书房里往日噎曾来,不曾见这般物事。", "b": "金·董解元《西厢记诸宫调》"}]}]}, {"pinyin": "yē", "defs": [{"meaning": "(形声。从口,壹(yī)声。本义:食物堵住喉咙)。"}, {"meaning": "同本义。", "cites": [{"t": "噎,饭窒也。", "b": "《说文》"}, {"t": "塞喉曰噎。", "b": "《通俗文》"}, {"t": "行迈靡靡,中心如噎。", "b": "《诗·王风·黍离》"}], "words": [{"w": "噎塞", "t": "消化系统通道受阻"}, {"w": "噎呕", "t": "喉塞作呕。"}]}, {"meaning": "哽咽。", "cites": [{"t": "[张氏]梦神人以宿生事责之曰:“明当死雷斧下”。觉而大恐,流泪悲噎。", "b": "宋·洪迈《夷坚甲志》"}], "words": [{"w": "噎噎咽咽", "t": "断断续续的哽咽声。"}]}]}]','jingmo-wenyan');
