('5907wx','噶','1','gá','口','15','','[{"pinyin": "gá", "defs": [{"meaning": "译音用字", "words": [{"w": "噶布伦,噶伦", "t": "原西藏地方政府的主要官员"}, {"w": "萨噶达娃节", "t": "藏族地区纪念释迦牟尼诞生的节日"}, {"w": "噶厦", "t": "原西藏地方政府,1959年西藏叛乱事件发生后解散"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5908wx','颙','1','yóng','页','15','','[{"pinyin": "yóng", "defs": [{"meaning": "(形声。从页(xié),禺(yù)声。页,头。本义:大头) 同本义。", "cites": [{"t": "颙,大头也。", "b": "《说文》"}]}, {"meaning": "形容大的样子。", "cites": [{"t": "四牡修广,其大有颙。", "b": "《诗·小雅·六月》"}]}, {"meaning": "温和肃敬的样子。", "cites": [{"t": "有孚颙若。", "b": "《易·观》。马注:“敬也。”虞注:“君德有威容貌。”"}, {"t": "颙颙夘夘。", "b": "《诗·大雅·卷阿》"}, {"t": "颙候来报,以慰我思。", "b": "辽·李良嗣《与李处温使为辽内应书》"}], "words": [{"w": "颙俟", "t": "颙候;颙竢。恭敬地等候"}, {"w": "颙祈", "t": "恭敬地祈求"}, {"w": "颙颙夘夘", "t": "肃敬轩昂的样子。"}]}]}]','jingmo-wenyan');
