INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5911wx','踔','1','chuō','足','15','','[{"pinyin": "chuō", "defs": [{"meaning": "践踏。"}, {"meaning": "跳,跳跃。", "cites": [{"t": "踔攳枝。", "b": "《后汉书·马融传》。注:“跳也。”"}, {"t": "煮头,三日三夕不烂,头踔出汤中。", "b": "干宝《搜神记》"}, {"t": "若鸟之摩空,猿之踔虚,似非手足之灵所能及也。", "b": "《徐霞客游记》"}], "words": [{"w": "踔虚", "t": "谓在空中腾跃"}, {"w": "踔跃", "t": "跳跃"}, {"w": "踔掉", "t": "摇晃,摆动。"}]}, {"meaning": "逾越,走过。", "cites": [{"t": "踔宇宙而遗俗兮。", "b": "《后汉书·蔡邕传》"}, {"t": "日夜踔数舍,冒没于凶党中。", "b": "宋·苏舜卿语"}], "words": [{"w": "踔绝", "t": "卓越出众"}, {"w": "踔远", "t": "相去辽远"}, {"w": "踔厉风发", "t": "形容议论精辟浑厚,如风势的强劲有力"}, {"w": "踔越", "t": "超越,胜过。"}]}, {"meaning": "跛行 。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5912wx','踝','1','huái','足','15','','[{"pinyin": "huái", "defs": [{"meaning": "(形声。从足,果声。本义:小腿与脚之间左右两侧突起部分)。"}, {"meaning": "同本义 ,在足和小腿之间的关节,相当于前臂腕关节,马的跗关节,在人类构成屈戌关节,位于上方的胫、腓骨和下方的距骨间。", "cites": [{"t": "踝,足踝也。从足,果声。谓足左右隆然圆起者。", "b": "《说文》"}], "words": [{"w": "内踝;外踝;踝胫", "t": "踝骨与胫骨"}, {"w": "踝拐", "t": "方言。踝骨"}, {"w": "踝子骨", "t": "方言。踝骨。内踝和外踝的统称。"}]}, {"meaning": "脚跟。", "cites": [{"t": "负绳及踝以应直。", "b": "《礼记·深衣》。注:“跟也。”"}], "words": [{"w": "负绳及踝", "t": "将绳带系于脚跟。"}]}]}]','jingmo-wenyan');
