INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5915wx','踬','1','zhì','足','15','','[{"pinyin": "zhì", "defs": [{"meaning": "(形声。从足,质声。绊倒与足有关,故从足。本义:被绊倒)。"}, {"meaning": "同本义。", "cites": [{"t": "踬,蛤也。", "b": "《说文》"}, {"t": "驰趣期而赴踬。", "b": "马融《长笛赋》"}, {"t": "杜回踬而颠。", "b": "《左传·宣公十五年》"}, {"t": "不踬于山,而踬于垤。", "b": "《韩非子·六反》"}]}, {"meaning": "跌倒,摔倒。", "cites": [{"t": "举之过一钧,则踬仆矣。", "b": "《论衡·命禄》"}, {"t": "踬踣者屡。", "b": "孙文《序》"}], "words": [{"w": "踬朴", "t": "跌倒"}, {"w": "踬踣", "t": "跌倒"}, {"w": "踬顿", "t": "失足跌倒"}, {"w": "踬蹶", "t": "踬踣。踬颠。绊倒。"}]}, {"meaning": "遭受挫折。", "cites": [{"t": "僧孺硕学,而中年遭踬。", "b": "《南史·王僧孺传》"}]}, {"meaning": "碍,阻碍。", "cites": [{"t": "踬于中道。", "b": "《清光禄大夫礼部尚书李公墓志铭》"}], "words": [{"w": "踬顿", "t": "受到阻碍而停顿不前"}, {"w": "踬阂", "t": "颠踬阻碍而进退不得。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
