INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5919wx','踞','1','jù','足','15','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从足,居声。本义:蹲坐)。"}, {"meaning": "同本义。", "cites": [{"t": "踞,蹲也。", "b": "《说文》。按,踞为居的俗字。"}, {"t": "皆踞转而鼓瑟。", "b": "《左传·襄公二十四年》"}, {"t": "释甲执冰而踞。", "b": "《左传·襄公二十五年》"}, {"t": "钟山龙盘,石头虎踞。此帝王之宅。", "b": "《太平御览》"}], "words": [{"w": "踞炉炭上", "t": "蹲在炭炉上。比喻处于危险的境地"}, {"w": "踞蹲", "t": "蹲坐"}, {"w": "踞伏", "t": "蹲伏。"}]}, {"meaning": "伸开腿坐。", "cites": [{"t": "沛公方踞床,使两女子洗足。", "b": "《史记·高祖本纪》"}, {"t": "箕踞见贾。", "b": "《汉书·陆贾传》。师古曰:“箕踞,谓伸其两脚而坐。”"}], "words": [{"w": "踞门限;踞厕", "t": "张开两腿,坐在床边。"}]}, {"meaning": "倚,依靠。", "cites": [{"t": "据渭踞泾。", "b": "张衡《西京赋》"}, {"t": "兹郑踞辕而歌。", "b": "《韩非子·外储说右下》"}], "words": [{"w": "踞觚", "t": "倚着灶角。"}]}, {"meaning": "傲慢。", "cites": [{"t": "乃用妇人之言,何有踞肆于朝?", "b": "《汉书·叙传上》"}, {"t": "反赂遗而尚踞敖。", "b": "《盐铁论·结和》"}, {"t": "捐贫贱之故旧,轻人士而踞傲也,骄人也。", "b": "《抱朴子·行品》"}, {"t": "单于骄踞,自比冒顿。", "b": "《后汉书·南匈奴传》"}], "words": [{"w": "踞肆", "t": "骄傲放肆"}, {"w": "踞慢", "t": "傲慢不恭"}, {"w": "踞嫚", "t": "踞慢"}, {"w": "踞见", "t": "踞坐而见客。形容待人傲慢。"}]}]}]','jingmo-wenyan');
