('5930wx','嘬','1','chuài zuō','口','15','','[{"pinyin": "chuài", "defs": [{"meaning": "大口吞食", "words": [{"w": "嘬嘬", "t": "疾食貌"}, {"w": "嘬嘬", "t": "吞食"}]}, {"meaning": "叮,咬", "words": [{"w": "嘬樘", "t": "咬,叮"}]}]}, {"pinyin": "zuō", "defs": [{"meaning": "(形声。从口,最声。本义:吸吮)。"}, {"meaning": "同本义。", "cites": [{"t": "于是乃相与聚嘬其母(体)而食之。", "b": "《韩非子·说林下》"}, {"t": "狐狸食之,蝇蚋姑嘬之。", "b": "《孟子·滕文公上》"}], "words": [{"w": "嘬奶;嘬柿子", "t": ""}]}, {"meaning": "一口吃下去。", "cites": [{"t": "毋嘬炙。", "b": "《礼记·曲礼》"}], "words": [{"w": "嘬炙", "t": "一口把大块烤肉吞食下去"}, {"w": "嘬嘬", "t": "贪食的样子"}, {"w": "嘬兵", "t": "大举兴兵。嘬,贪食。"}]}]}]','jingmo-wenyan');
