INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5938wx','颛','1','zhuān','页','15','','[{"pinyin": "zhuān", "defs": [{"meaning": "善良。", "cites": [{"t": "猛兽食颛民。", "b": "《淮南子》"}], "words": [{"w": "颛愚", "t": "忠厚善良"}, {"w": "颛醇", "t": "善良淳朴。"}]}, {"meaning": "顽愚。", "cites": [{"t": "某比兴非工,颛蒙有素。", "b": "李商隐《献侍郎钜鹿公启》"}], "words": [{"w": "颛庸", "t": "愚昧平庸"}, {"w": "颛颛", "t": "愚昧无知的样子"}, {"w": "颛蒙", "t": "愚昧"}, {"w": "颛甿", "t": "愚昧的乡下人。"}]}, {"meaning": "专门。", "cites": [{"t": "彭祖安乐各颛门教授。", "b": "《汉书·儒林严彭祖传》"}, {"t": "相国产颛兵秉政。", "b": "《汉书·高后纪》"}, {"t": "兼业颛利。", "b": "《汉书·货殖列传》"}]}, {"meaning": "专擅", "cites": [{"t": "颛妄言。", "b": "《史记·陈涉世家》"}, {"t": "颛作威福庙堂之上。", "b": "《汉书·诸侯王表》"}, {"t": "光颛权自恣。", "b": "《汉书·苏武传》"}], "words": [{"w": "颛政", "t": "独揽政权"}, {"w": "颛国", "t": "把持国政"}, {"w": "颛权", "t": "独揽大权"}, {"w": "颛事", "t": "独自处理事情。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5939wx','幞','1','fú','巾','15','','[{"pinyin": "fú", "defs": [{"meaning": "古代男子用的一种头巾。也称“幞头”(古人以皂绢三尺裹发,有四带,二带系脑后垂之,二带反系头上,令曲折附项,故称“幞头”)。", "cites": [{"t": "高幞广带。", "b": "《古今小说》"}, {"t": "门前小鬼,折臂膊不显狰狞,殿上判官,无幞头不成礼数。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5940wx','幡','1','fān','巾','15','','[{"pinyin": "fān", "defs": [{"meaning": "(形声。从巾,番声。本义:擦拭写字板的布)。"}, {"meaning": "同本义。", "words": [{"w": "幡布", "t": "抹布。"}]}, {"meaning": "用竹竿等直着挂的长条形旗子。泛指旗帜。", "cites": [{"t": "青崔白鹄舫,四角龙子幡。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "幡幢", "t": "作为仪仗用的旗帜"}, {"w": "幡信", "t": "题表官号以为符信的旗帜"}, {"w": "幡旆", "t": "旗帜之类"}, {"w": "幡旄", "t": "旌旗的羽毛饰"}, {"w": "幡麾", "t": "指挥用的幡旗。"}]}, {"meaning": "冠上的巾饰。", "cites": [{"t": "却非冠,制似长冠,下促。宫殿门吏仆射冠之。负赤幡,青翅燕尾,诸仆射幡皆如之。", "b": "《后汉书》"}]}, {"meaning": "长幅下垂的旗。", "cites": [{"t": "垂绛幡之素蜺兮,载云气而上浮。", "b": "《史记·司马相如列传》"}], "words": [{"w": "举幡", "t": ""}]}, {"meaning": "变动;反覆;翻转,翻腾。", "cites": [{"t": "既而幡然改曰:与我处畎亩之中。", "b": "《孟子·万章上》"}, {"t": "君子之学如蜕,幡然迁之。", "b": "《荀子·大略》"}, {"t": "幡比翄回集,贰双飞常羊。", "b": "《汉书》"}], "words": [{"w": "幡幡", "t": "翻动的样子"}, {"w": "幡纚", "t": "飞扬的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5941wx','嶙','1','lín','山','15','','[{"pinyin": "lín", "defs": [{"meaning": "1.山石一层层的重叠不平怪石～峋。"}, {"meaning": "2.形容人瘦削瘦骨～峋。"}, {"meaning": "山势起伏不平貌。", "cites": [{"t": "浅山嶙嶙，乱石矗矗。--欧阳修《盘车图》", "b": ""}]}, {"meaning": "形容山石峻峭、重叠。", "cites": [{"t": "岭巆嶙峋，洞无涯兮。--《汉书·扬雄传》", "b": ""}, {"t": "海之波澜，山之嶙峋。--司空图《诗品》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5942wx','嶝','1','dèng','山','15','','[{"pinyin": "dèng", "defs": [{"meaning": "小山坡。", "cites": [{"t": "嶝,小坂也。", "b": "《玉篇·山部》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5943wx','骺','1','hóu','骨','15','','[{"pinyin": "hóu", "defs": [{"meaning": "骨骺 长骨两端膨大部分。长骨有一体和两端,体叫骨干,两端叫骨骺,骨骺上有关节面和邻近的骨构成关节。", "cites": [{"t": "骺,骨端谓之骺。", "b": "《类篇》"}]}, {"meaning": "骨或木制的箭镞。", "cites": [{"t": "骺,骨镞。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5944wx','骼','1','gé','骨','15','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从骨,各声。本义:禽兽之骨。引申为“人或动物的骨骼”)。"}, {"meaning": "骨头。", "cites": [{"t": "骼,禽兽之骨曰骼。", "b": "《说文》"}, {"t": "骼,腰骨也。", "b": "《埤苍》"}, {"t": "掩骼埋胔。", "b": "《礼记·月令》"}]}, {"meaning": "死人的骨头,枯骨。", "cites": [{"t": "[孟春之月]掩骼埋胔。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5945wx','骸','1','hái','骨','15','','[{"pinyin": "hái", "defs": [{"meaning": "(形声。从骨,亥声。本义:胫骨,小腿骨)。"}, {"meaning": "同本义。", "cites": [{"t": "骸,胫骨也。", "b": "《说文》。段玉裁注:“《骨空论》曰:‘膝解为骸关,侠膝之骨为连骸。’然则正谓胫骨为骸矣。”"}, {"t": "骸下为辅,辅上为腘。", "b": "《素问》"}, {"t": "析骸而炊之。", "b": "《公羊传·宣公十五年》"}, {"t": "[相马]臂欲大而短,骸欲小而长。", "b": "《齐民要术》"}]}, {"meaning": "骨,尸骨。", "cites": [{"t": "即如忠烈遗骸。", "b": "清·全祖望《梅花岭记》"}], "words": [{"w": "尸骸;骸炭", "t": "骨灰"}, {"w": "骸筋", "t": "筋骨"}, {"w": "骸骼", "t": "尸骨。"}]}, {"meaning": "身体。", "cites": [{"t": "有七尺之骸,手足之异,戴发含齿,倚有趣者,谓之人。", "b": "《列子·黄帝》"}], "words": [{"w": "残骸;病骸", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5946wx','镊','1','niè','钅','15','','[{"pinyin": "niè", "defs": [{"meaning": "镊子。", "cites": [{"t": "镊,摄取发也。", "b": "《释名·释首饰》"}, {"t": "愿戢子之手,摄子之镊。", "b": "晋·左思《白发赋》"}]}, {"meaning": "古簪端垂锦。", "cites": [{"t": "后床帷陈设故旧,钗镊十余枚。", "b": "《南齐书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5947wx','镉','1','gé','钅','15','','[{"pinyin": "gé", "defs": [{"meaning": "一种锡白色可延展的有毒二价金属元素,能高度磨光,当受弯曲时会发出破裂声。产于硫镉矿,也以少量含于锌矿石中,可作为副产品提取。主要为保护铁板、钢板做电镀及制造金属轴承之用 ——元素符号Cd。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5948wx','镌','1','juān','钅','14','','[{"pinyin": "juān", "defs": [{"meaning": "(形声。从金,隽(juàn)声。①本义:破木之器。②凿,刻)。"}, {"meaning": "用凹线、凹面或点雕刻。", "cites": [{"t": "镌山石。", "b": "《淮南子·本经》"}], "words": [{"w": "镌功", "t": "刻石记功"}, {"w": "镌题", "t": "在金石器物上刻写"}, {"w": "镌错", "t": "雕刻磋磨"}, {"w": "镌石", "t": "刻石。"}]}, {"meaning": "降职。", "cites": [{"t": "扰民及不实乾镌罚。", "b": "宋史·食货志》"}], "words": [{"w": "镌罚", "t": "降职惩罚"}, {"w": "镌级", "t": "降低官阶"}, {"w": "镌责", "t": "降级追究责任。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5949wx','镍','1','niè','钅','15','','[{"pinyin": "niè", "defs": [{"meaning": "近似银白色、硬而有延展性并具有铁磁性的金属元素,它能够高度磨光和抗腐蚀。主要用于合金(如镍钢和镍银)及用作催化剂(如拉内镍,尤指用作氢化的催化剂) ——元素符号Ni。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5950wx','镏','1','liú liù','钅','15','','[{"pinyin": "liú", "defs": [{"meaning": "杀戮。", "cites": [{"t": "镏,杀也。", "b": "《说文》"}]}, {"meaning": "镏金。", "cites": [{"t": "尊天二十四像,穆肃慈猛,相具神足,衣冠法故,范镏质良。", "b": "明·刘侗、于奕正《帝京景物略》"}]}, {"meaning": "姓。"}]}, {"pinyin": "liù", "defs": [{"meaning": "釜,古代的炊事用具,相当于现在的锅。", "cites": [{"t": "梁州谓釜曰镏。", "b": "《集韵》"}], "words": [{"w": "手镏", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5951wx','镒','1','yì','钅','15','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从金,益声。本义:古代的重量单位,二十两或二十四两为一镒)同本义。", "cites": [{"t": "黄金四十镒。", "b": "《国语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5952wx','镓','1','jiā','钅','15','','[{"pinyin": "jiā", "defs": [{"meaning": "一种稀有蓝白色三价金属元素,在低温时硬而脆,而一超过室温就熔融。它凝固时膨胀,通常是作为从铝土矿中提取铝或从锌矿石中提取锌时的副产物得到的 ——元素符号Ga。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5953wx','镔','1','bīn','钅','15','','[{"pinyin": "bīn", "defs": [{"meaning": "冶炼质量很高的金属铁。", "cites": [{"t": "三尺镔刀耀雪光。", "b": "洪昇《长生殿》"}]}, {"meaning": "精炼铁,即熟铁或锻铁。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5954wx','稷','1','jì','禾','15','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从禾,畟(cè)声。表示与农作物有关。本义:稷谷)。"}, {"meaning": "植物名。我国古老的食用作物,即粟。一说为不粘的黍。又说为高粱。", "cites": [{"t": "稷,齌也。五谷之长。", "b": "《说文》"}, {"t": "黍稷无成。", "b": "《国语·晋语》。注:“粱也。”按,千谷粟三者为黍,稷稻梁之大名。梁则今小米子之大而不黏者,与稷别。"}, {"t": "黏者为黍,不黏者为稷。", "b": "《本草纲目》"}, {"t": "稷,粟也。", "b": "《尔雅·释草》注"}, {"t": "稷,今人谓之高粱。", "b": "《广雅疏证》"}], "words": [{"w": "稷食", "t": "稷米煮的饭。泛指粗粝的饭"}, {"w": "稷饭", "t": "以稷谷为饭"}, {"w": "稷馈", "t": "古代以稷为主的祭礼。"}]}, {"meaning": "引申为庄稼和粮食的总称。", "cites": [{"t": "彼黍离离,彼稷之苗。", "b": "《诗·王风·黍离》"}, {"t": "桑竹垂余荫,菽稷时时艺。", "b": "陶潜《桃花源诗》"}, {"t": "黍稷重穋,禾麻菽麦。", "b": "《诗·豳风·七月》"}], "words": [{"w": "稷黍", "t": "泛指五谷"}, {"w": "稷事", "t": "播利五谷的事"}, {"w": "稷神", "t": "五谷神。"}]}, {"meaning": "五谷之神。古代以稷为百谷之长,因此帝王奉祀为谷神。", "cites": [{"t": "社稷依明主,安危托妇人。", "b": "戎昱《咏史》"}], "words": [{"w": "稷狐", "t": "五谷庙中的狐狸。比喻君侧奸臣"}, {"w": "稷祠", "t": "古代稷神的祠堂"}, {"w": "稷庙", "t": "古代稷神的庙宇。"}]}, {"meaning": "古地名。"}, {"meaning": "春秋时齐地,故地在今山东省淄博市。"}, {"meaning": "春秋时晋地,故地在今山西省稷山。"}, {"meaning": "春秋时楚地,故地在今河南省桐柏县。"}, {"meaning": "春秋时宋地,故地在今河南省商丘。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5955wx','箴','1','zhēn','竹','15','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从竹,咸声。本义:缝衣用的工具"}, {"meaning": "同本义。", "cites": [{"t": "衣裳破绽,纫箴请补缀。", "b": "《礼记》。"}], "words": [{"w": "箴缕", "t": "针线"}, {"w": "箴末", "t": "喻微细"}, {"w": "箴管", "t": "指缝缀之事"}, {"w": "箴盥", "t": "古代妇女承姑奉盥,视为箴规。"}]}, {"meaning": "文体的一种,以规戒为表达的主题。", "cites": [{"t": "箴顿挫而清壮。", "b": "晋·陆机《文赋》。"}], "words": [{"w": "箴铭", "t": "文体名。箴是规戒性的韵文;铭在古代常刻在器物上或碑石上,兼用于规戒、褒赞。"}]}, {"meaning": "规劝,告诫。", "cites": [{"t": "贤袭人娇嗔箴宝玉,俏平儿软语救贾琏。", "b": "《红楼梦》。"}], "words": [{"w": "箴谏", "t": "劝谏别人改正过失"}, {"w": "箴砭", "t": "指出并纠正错误"}, {"w": "箴规", "t": "劝谏,规戒"}, {"w": "箴诫", "t": "规劝告诫"}, {"w": "箴诲", "t": "规劝教训"}, {"w": "箴训", "t": "箴戒;规训。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5956wx','篑','1','kuì','竹','15','','[{"pinyin": "kuì", "defs": [{"meaning": "(形声。从竹,贵声。本义:盛土的竹筐) 同本义。", "cites": [{"t": "为山九仞,功亏一篑。", "b": "《书·旅獒》"}], "words": [{"w": "篑笼", "t": "运土用的竹具。如挑筐"}, {"w": "功亏一篑", "t": "比喻做事只差最后一点力量而未能完成。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5957wx','篁','1','huáng','竹','15','','[{"pinyin": "huáng", "defs": [{"meaning": "竹田,竹园。", "cites": [{"t": "篁,竹田也。", "b": "《说文》"}, {"t": "蓟丘之植,植于汶篁。", "b": "《战国策·燕策》。裴骃集解引徐广曰:“竹田曰篁。”"}]}, {"meaning": "竹丛;竹林。", "cites": [{"t": "余处幽篁兮终不见天。", "b": "《楚辞·山鬼》"}, {"t": "篁竹之中。", "b": "《汉书·严助传》"}], "words": [{"w": "篁阵", "t": "竹林"}, {"w": "篁迳", "t": "竹林中的小路"}, {"w": "篁路", "t": "竹林中的路"}, {"w": "篁筱", "t": "泛指密密的竹林。"}]}, {"meaning": "竹名。", "cites": [{"t": "隔篁竹闻水声。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "篁筱", "t": "篁竹和筱竹"}, {"w": "篁笋", "t": "一种笋名。"}]}]}]','jingmo-wenyan');
