INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5959wx','篆','1','zhuàn','竹','15','','[{"pinyin": "zhuàn", "defs": [{"meaning": "(形声。从竹,彖(tuàn)声。从竹,与简册有关。本义:即篆书。汉字的一种书体,通常包括大篆、小篆,一般指小篆)。"}, {"meaning": "同本义。", "cites": [{"t": "篆,引书也。谓引笔而箸之于竹帛。", "b": "《说文》。故史籀所作为大篆,李斯所作为小篆,又有以摹印者为缪篆。其实许君所云八体,唐元度所云十体,下至韦绩所云五十六种云,梦英所云十八种书,皆得之篆也。"}, {"t": "鸟书篆素。", "b": "左思《吴都赋》。注:“篆书于素也。”"}, {"t": "用篆章一。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "篆炉", "t": "有篆字形图案的香炉"}, {"w": "篆体", "t": "篆字的书体。汉字书体的一种"}, {"w": "篆虫", "t": "篆书"}, {"w": "篆题", "t": "用篆书所写的字"}, {"w": "篆隶", "t": "篆书和隶书"}, {"w": "篆记", "t": "篆体印章。"}]}, {"meaning": "官印的代称。", "cites": [{"t": "妻孥从饿死,敢爱黄金篆。", "b": "唐·刘叉《饿咏》"}, {"t": "轻骑而先,二十六日入泰州,未视篆,借郡中敢死士及部押使臣效用。", "b": "岳琦《金蛇粹编》"}], "words": [{"w": "篆文", "t": "篆体字"}, {"w": "篆注", "t": "对篆字的注解"}, {"w": "篆籀", "t": "篆文和籀文。"}]}, {"meaning": "官职。", "cites": [{"t": "明官多缺,以经历署篆。", "b": "《徐霞客游记》"}]}, {"meaning": "特指用篆体字书写。", "cites": [{"t": "太一装以宝,列仙篆其文。", "b": "唐·韩愈·孟郊《赠剑客李园联句》"}], "words": [{"w": "篆素", "t": "写篆书于素帛"}, {"w": "篆额", "t": "用篆字书写碑额"}, {"w": "篆书", "t": "写篆字。"}]}, {"meaning": "雕刻。", "cites": [{"t": "爱美人之容貌兮,香培玉篆。", "b": "《红楼梦》"}]}, {"meaning": "引申为铭刻。", "cites": [{"t": "深情已篆中心,今已人禽异类,姻好何可复圆?", "b": "《聊斋志异》"}, {"t": "才微往彦,遇倍昔时,仰戴恩荣,已增铭篆。", "b": "唐·顾云《谢徐学士启》"}], "words": [{"w": "篆铭", "t": "铭刻,比喻牢记在心。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5960wx','牖','1','yǒu','片','15','','[{"pinyin": "yǒu", "defs": [{"meaning": "(会意。从片户甫。片,锯开的木片,“户”指窗。先秦多用牖,窗少见。本义:窗户) 同本义。", "cites": [{"t": "牖,穿壁以木为交窗也。", "b": "《说文》。段注:“交窗者,以木横直为之,即今之窗也。在墙曰牖,在屋曰窗。”"}, {"t": "宗室牖下。", "b": "《诗·召南·采》"}, {"t": "众美人把四周窗牖俱开。", "b": "《隋唐演义》"}, {"t": "然陈涉瓮牖绳枢之子。", "b": "汉·贾谊《过秦论》"}, {"t": "扃牖而居。", "b": "明·归有光《项脊轩志》"}, {"t": "牖其前以通明。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "牖下", "t": "家中。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5961wx','儋','1','dān dàn','亻','15','','[{"pinyin": "dān", "defs": [{"meaning": "担(擔)的古字。肩荷、用肩挑。", "cites": [{"t": "令婢路上担粪。", "b": "《世说新语·规箴》"}], "words": [{"w": "儋石", "t": "容器名。儋容一石;一说二石为儋。也作担石,檐石"}, {"w": "儋负", "t": "担负。肩挑背负"}, {"w": "儋何", "t": "担荷。肩负责任。"}]}, {"meaning": "抬。二人用肩扛。", "cites": [{"t": "上人著百尺楼上,儋梯而去。", "b": "《世说新语·黜免》"}]}, {"meaning": "古州名 。汉置儋耳郡,唐改为儋州。民国设县。旧治所在今海南省儋县西北。"}, {"meaning": "儋县 ,在海南省的西北部。人口71万(1991年)。"}]}, {"pinyin": "dàn", "defs": [{"meaning": "成担货物的计量单位。", "cites": [{"t": "儋石不储,饥寒交至。", "b": "晋·陶潜《劝农》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5962wx','徵','1','zhǐ','彳','15','','[{"pinyin": "zhǐ", "defs": [{"meaning": "古代五声音阶“宫商角徵羽”的第四音。相当于工尺谱上的“六”,现在简谱上的“5”。", "cites": [{"t": "徵,五声之一,弦用五十四丝,其声清。", "b": "《正字通》"}], "words": [{"w": "徵羽", "t": "宫、商、角、徵、羽五声音节中的后两音。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5963wx','磐','1','pán','石','15','','[{"pinyin": "pán", "defs": [{"meaning": "(形声。从石,般声。本义:纡回层叠的山石,巨石) 同本义。", "cites": [{"t": "竭磐石。", "b": "木华《海赋》"}]}, {"meaning": "字亦作“盤”。", "cites": [{"t": "磐,大石。", "b": "《广韵》"}, {"t": "此所谓盘石之宗也。", "b": "《史记·孝文纪》"}, {"t": "国安于盤石。", "b": "《荀子·富国》"}], "words": [{"w": "磐陀石", "t": "不平的石头"}, {"w": "磐固", "t": "如磐石般稳固"}, {"w": "磐磨", "t": "大石,磨。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5964wx','虢','1','guó','虍','15','','[{"pinyin": "guó", "defs": [{"meaning": "(形声。从虎,寽(lǚ)声。本义:虎所抓画之迹)。"}, {"meaning": "同本义。", "cites": [{"t": "虢,虎所攫画明文也。", "b": "《说文》"}]}, {"meaning": "周代国名。有东、西、南、北四虢。"}, {"meaning": "东虢。周文王弟虢叔所封之地,在今河南省荥阳,公元前767年为郑所灭。"}, {"meaning": "西虢,周文王弟虢仲的封地,在今陕西省宝鸡县东,公元前665年为秦所灭。"}, {"meaning": "南虢,周平王东迁,西虢徙于上阳,称南虢,春秋时灭于晋。"}, {"meaning": "北虢。虢仲后代的封地,在今山西省平陆县。", "cites": [{"t": "谚所谓“辅车相依,唇亡齿寒”者,其虞虢之谓也。", "b": "《左传·僖公五年》"}]}, {"meaning": "唐代州名 。地在今河南省灵宝县。"}, {"meaning": "猛烈;暴烈。", "cites": [{"t": "设以虢猛绝伦之将,而遇快枪精炮,不能不殒于飞铅之下。", "b": "清·薛福成《枪炮说》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5965wx','鹞','1','yào','鸟','15','','[{"pinyin": "yào", "defs": [{"meaning": "雀鹰的俗称。古名“鹬子”、“笼脱”,今通称“鹞鹰”、鹞子 。形体像鹰而比鹰小,背灰褐色,以小鸟、小鸡为食", "words": [{"w": "鹞坊", "t": "唐代宫廷饲养鹞的官署"}, {"w": "鹞琴", "t": "装在纸鹞上、放出时发声的竹簧琴"}, {"w": "鹞雏", "t": "幼鹞"}]}, {"meaning": "鹰科,鹞属各种鸟的通称", "words": [{"w": "白尾鹞", "t": ""}, {"w": "鹊鹞", "t": ""}, {"w": "白头鹞", "t": ""}]}]}]','jingmo-wenyan');
