('5966wx','膘','1','biāo','月','15','','[{"pinyin": "biāo", "defs": [{"meaning": "肥肉。", "cites": [{"t": "膘,牛胁后髀前合革肉也。从肉,票声。", "b": "《说文》"}, {"t": "自膘而射之。", "b": "《诗·车攻传》"}, {"t": "马无他损,特膘稍落,微磨破耳。(特:仅仅,只。)", "b": "李新《与冯德夫》"}], "words": [{"w": "膘肥体壮", "t": "形容牲畜肥壮结实"}, {"w": "膘息", "t": "指牲畜的肥硕处。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5967wx','滕','1','téng','水','15','','[{"pinyin": "téng", "defs": [{"meaning": "(形声。从水,朕(zhèn)声。本义:水向上腾涌)。"}, {"meaning": "同本义。", "cites": [{"t": "滕,水超涌也。", "b": "《说文》"}, {"t": "百川沸滕。", "b": "《诗·小雅·十月之交》"}, {"t": "滕,《诗》曰:“百川沸滕”。水上涌也。", "b": "《玉篇》"}]}, {"meaning": "引申为张口说话。", "cites": [{"t": "滕口说也。", "b": "《易·咸》"}, {"t": "范君独判于心,不畏滕口。", "b": "唐·韦瓘《宣州南陵县大农陂记》"}], "words": [{"w": "滕口", "t": "张口放言。"}]}, {"meaning": "西周分封的侯国名。", "cites": [{"t": "春秋滕侯,文王子叔绣之后。国在今山东衮州府滕县。", "b": "朱骏声《说文通训定声》"}]}, {"meaning": "在今山东省滕县一带。"}, {"meaning": "县名 。在山东省。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5968wx','鲠','1','gěng','鱼','15','','[{"pinyin": "gěng", "defs": [{"meaning": "(形声。从鱼(或从骨),更声。本义:鱼骨,鱼刺)。"}, {"meaning": "同本义。", "cites": [{"t": "鲠,鱼骨也。", "b": "《说文》"}], "words": [{"w": "如鲠在喉,不吐不快", "t": ""}]}, {"meaning": "病患,祸害。", "cites": [{"t": "除鲠而避强。", "b": "《国语·晋语》。注:“害也。”"}], "words": [{"w": "鲠慰", "t": "悒郁中得到安慰。"}]}, {"meaning": "假借为“骾”。鱼刺卡在喉咙里。", "cites": [{"t": "骾,食骨留咽中也。", "b": "《说文》"}, {"t": "鱼去乙。", "b": "《礼记·内则》。注:“食之鲠人。”"}], "words": [{"w": "他被鱼刺鲠住了", "t": ""}]}, {"meaning": "阻塞;堵塞。", "cites": [{"t": "楚师屠汉卒,睢河鲠其流。", "b": "《文选·刘孝标·辨命论》"}]}]}]','jingmo-wenyan');
