('5970wx','鲢','1','lián','鱼','15','','[{"pinyin": "lián", "defs": [{"meaning": "鲢鱼 ,头小鳞细,腹部色白,体侧扁", "words": [{"w": "鲢子", "t": "白鲢"}, {"w": "鲢胖头", "t": "方言。花鲢,也称黑鲢"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5971wx','鲣','1','jiān','鱼','15','','[{"pinyin": "jiān", "defs": [{"meaning": "鲣鱼 。几种鲣的任何一种(例如鲣属Katsuwonus),身体呈纺锤形,大部分无鳞,腹白,背苍黑。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5972wx','鲥','1','shí','鱼','15','','[{"pinyin": "shí", "defs": [{"meaning": "鲥魚 。鲱科鱼,体侧扁,长70厘米,银白色,分布于中国、朝鲜、菲律宾沿海,是一种名贵食用鱼。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5973wx','鲧','1','gǔn','鱼','15','','[{"pinyin": "gǔn", "defs": [{"meaning": "鱼名。古书上指一种大鱼。", "cites": [{"t": "马鲛,青斑色,无鳞有齿,又名章鮌。", "b": "明·屠本畯《闽中海错疏·鳞下》"}]}, {"meaning": "古人名,夏禹的父亲。", "cites": [{"t": "禹之父曰鲧。", "b": "《史记》"}]}]}]','jingmo-wenyan');
