INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5976wx','獠','1','lǎo liáo','犭','15','','[{"pinyin": "lǎo", "defs": [{"meaning": "即僚 。中国古族名。分布在今广东、广西、湖南、四川、云南、贵州等地区。亦泛指南方各少数民族。"}, {"meaning": "詈词。古时北方人骂南方人的话。", "cites": [{"t": "你这獠子,好不达时务。", "b": "《古今小说》"}]}]}, {"pinyin": "liáo", "defs": [{"meaning": "夜猎。亦泛指打猎。", "cites": [{"t": "獠,猎也。从犬,尞声。", "b": "《说文》"}, {"t": "宵田为獠。", "b": "《尔雅》"}, {"t": "獠猎毕戈。", "b": "《管子》"}, {"t": "将飨獠者。", "b": "左思《蜀都赋》"}, {"t": "于是乃相与獠于蕙圃。", "b": "司马相如《子虚赋》"}], "words": [{"w": "獠猎", "t": "打猎"}, {"w": "獠者", "t": "獠徒。打猎的人"}, {"w": "獠杀", "t": "捕杀;杀害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5977wx','觯','1','zhì','角','15','','[{"pinyin": "zhì", "defs": [{"meaning": "古时饮酒用的器皿。青铜制。形似尊而小,或有盖。", "cites": [{"t": "尊者举觯,卑者举角。", "b": "《礼记·礼器》"}]}]}]','jingmo-wenyan');
