INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5979wx','馔','1','zhuàn','饣','15','','[{"pinyin": "zhuàn", "defs": [{"meaning": "(形声。从食,巽(xùn)声。本义:陈设或准备食物)。"}, {"meaning": "同本义。", "cites": [{"t": "巽,具也。", "b": "《说文》。馔为巽的或体。"}, {"t": "馔撰,具也。", "b": "《广雅》"}, {"t": "具馔于西塾。", "b": "《仪礼·士冠礼》。注:“陈也。”"}, {"t": "馔于东方。", "b": "《仪礼·聘礼》"}], "words": [{"w": "馔珍", "t": "摆设精美珍贵的食物"}, {"w": "馔具", "t": "陈设食物的餐具。"}]}, {"meaning": "吃喝;给吃喝。", "cites": [{"t": "有酒食,先生馔。", "b": "《论语·为政》"}], "words": [{"w": "馔宾", "t": "款待宾客。"}]}, {"meaning": "一般的食品、食物。", "cites": [{"t": "掌其厚薄之齐,以共王之四饮三酒之馔。", "b": "《周礼·天官》"}, {"t": "豫章王嶷盛馔享宾。", "b": "《南史·虞悰传》"}, {"t": "钟鼓馔玉不足贵,但愿长醉不复醒。", "b": "李白《将进酒》"}], "words": [{"w": "馔玉", "t": "精美珍贵的食品"}, {"w": "馔脯", "t": "美食"}, {"w": "馔饮", "t": "饮食"}, {"w": "馔羞", "t": "美食。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5980wx','麾','1','huī','麻','15','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从毛,麻声。本义:古代供指挥用的旌旗)。"}, {"meaning": "指挥,下命令行动。", "cites": [{"t": "麾,指麾。", "b": "《玉篇》"}], "words": [{"w": "麾军", "t": "指挥军队"}, {"w": "麾众", "t": "指挥大众。"}]}, {"meaning": "", "cites": [{"t": "王左杖黄钺,右秉白旄以麾。", "b": "《书·牧誓》"}, {"t": "瑕叔盈又以蝥弧(蝥弧,郑伯旗名)登,周麾而呼曰:“君登矣!”", "b": "《左传·隐公十一年》"}, {"t": "魏其侯去,麾灌夫出。", "b": "《史记·魏其武安侯列传》"}, {"t": "庄王亲自手旌,左右麾军。", "b": "《新序·杂事四》"}], "words": [{"w": "麾去", "t": "撤掉;退掉"}, {"w": "麾动", "t": "作圆圈式的挥动"}, {"w": "麾日", "t": "比喻扭转乾坤。也作挥日"}, {"w": "麾叱", "t": "挥手喝叱。同挥叱"}, {"w": "麾扫", "t": "挥毛扫纸。指写诗作文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5981wx','廛','1','chán','广','15','','[{"pinyin": "chán", "defs": [{"meaning": "(会意。从广里八土。本义:古代城市平民一户人家所居的房地)。"}, {"meaning": "同本义。", "cites": [{"t": "廛,二亩半一家之居也。", "b": "《说文》。按,八者,别也。在里曰廛,在野曰庐。"}, {"t": "廛,民居区域之称。", "b": "《周礼·廛人》注》"}, {"t": "愿受一廛而为氓。", "b": "《孟子·滕文公上》"}, {"t": "闲廛未尽居也。", "b": "清·洪亮吉《治平篇》"}]}, {"meaning": "假借为“缠”。束,捆。", "cites": [{"t": "不稼不穑,胡取禾三百廛兮?", "b": "《诗·魏风·伐檀》"}]}]}]','jingmo-wenyan');
