INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5983wx','瘼','1','mò','疒','15','','[{"pinyin": "mò", "defs": [{"meaning": "(形声。从疒(chuáng),莫声。本义:病,疾病)。"}, {"meaning": "同本义。", "cites": [{"t": "瘼,病也。", "b": "《说文》"}, {"t": "乱离瘼矣,爰其适归。", "b": "《诗·小雅·四月》。毛传:“瘼,病。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5984wx','瘢','1','bān','疒','15','','[{"pinyin": "bān", "defs": [{"meaning": "创伤或疮疖等愈后的疤痕。", "cites": [{"t": "瘢,痍也。从疒,般声。", "b": "《说文》"}, {"t": "瘢,痕也。", "b": "《苍颉篇》"}, {"t": "视其面,果有瘢。", "b": "《汉书·朱博传》"}], "words": [{"w": "瘢疣", "t": "瘢痕和赘疣"}, {"w": "瘢夷", "t": "创伤。"}]}, {"meaning": "皮肤上的斑点。", "cites": [{"t": "两边腮上微微的几点雀瘢。", "b": "《红楼梦》"}], "words": [{"w": "瘢迹", "t": "瘢痕;痕迹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5985wx','瘠','1','jí','疒','15','','[{"pinyin": "jí", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,脊声。本义:身体瘦弱)。"}, {"meaning": "同本义。或作“膌”。", "cites": [{"t": "牛虽瘠,偾于豚上,其畏不死?", "b": "《左传·昭公十三年》"}, {"t": "宋崇门之巷人服丧而毁甚瘠。", "b": "《韩非子·内储说上》"}, {"t": "长短丰瘠。", "b": "清·薛福成《观巴黎油画记》"}, {"t": "老年如脊牛。", "b": "清·梁启超《饮冰室合集》"}], "words": [{"w": "瘠弱", "t": "瘦弱;衰弱"}, {"w": "瘠疲", "t": "瘦弱疲惫"}, {"w": "瘠色", "t": "容貌忧戚憔悴"}, {"w": "瘠牛偾豚", "t": "瘦瘠的牛仆倒在小猪身上,小猪必死。比喻无德的大国权势虽衰,欺凌羸弱的小国,小国也会灭亡。"}]}, {"meaning": "贫困。", "cites": [{"t": "夫民殷国弱,民瘠国强者,未之有也。", "b": "《三国志·陆逊传》"}], "words": [{"w": "瘠馁", "t": "贫困饥饿"}, {"w": "瘠贫", "t": "贫困"}, {"w": "瘠亡", "t": "贫穷衰亡。"}]}, {"meaning": "瘠薄,不肥沃。", "cites": [{"t": "处沃土则逸,处瘠土则劳。", "b": "张衡《西京赋》"}], "words": [{"w": "瘠土", "t": "瘠地。贫瘠不肥沃的土地"}, {"w": "瘠田", "t": "瘠薄而不肥沃的田地"}, {"w": "瘠卤", "t": "盐碱地。贫瘠的土地"}, {"w": "瘠硗", "t": "多石不肥沃的土地"}, {"w": "瘠壤", "t": "瘠土。"}]}, {"meaning": "菲薄;简约。", "cites": [{"t": "送死不忠厚,不敬文,谓之瘠。", "b": "《荀子·礼论》"}], "words": [{"w": "瘠墨", "t": "俭约,刻薄。因墨家尚俭、薄葬,故有此称。"}]}, {"meaning": "腐肉;腐烂的尸体。", "cites": [{"t": "稼亡三分之一,而非有故盖积也,则道有损瘠矣。", "b": "《管子》。王念孙杂志:“损当为捐。”"}]}]}]','jingmo-wenyan');
