INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5997wx','澍','1','shù','氵','15','','[{"pinyin": "shù", "defs": [{"meaning": "(形声。从水,尌(shù)声。本义:及时雨) 同本义。", "cites": [{"t": "澍,时雨也。", "b": "《说文》"}, {"t": "群生澍濡。雨润万物名曰澍。", "b": "司马相如《难蜀父老文》"}, {"t": "连获甘澍,岁时丰稔。", "b": "《后汉书·段熲传》"}], "words": [{"w": "澍雨", "t": "及时雨"}, {"w": "澍降", "t": "降雨"}, {"w": "澍霖", "t": "及时雨。"}]}, {"meaning": "降。", "cites": [{"t": "未及还宫而澍雨。", "b": "《后汉书》"}], "words": [{"w": "澍雨", "t": "降雨。"}]}, {"meaning": "雨水滋润。", "cites": [{"t": "若春雨之灌万物也,浑然而流,沛然而施,无地而不澍。", "b": "刘安《淮南子·泰族》"}], "words": [{"w": "澍泽", "t": "沾濡滋润。亦指滋润万物的及时雨"}, {"w": "澍濡", "t": "雨水滋润万物。引申指善施恩泽,或指承受恩泽。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5998wx','澌','1','sī','氵','15','','[{"pinyin": "sī", "defs": [{"meaning": "(形声。从水,斯声。本义:水尽)。"}, {"meaning": "同本义。", "cites": [{"t": "澌,水索也。", "b": "《说文》。徐锴系传:“索,尽也。”"}]}, {"meaning": "引申为凡物竭尽之称。消亡。", "cites": [{"t": "使举国之少年而亦为老大也,则吾中国为过去之国,其澌亡可翘足而待也。", "b": "清·梁启超《饮冰室合集·文集》"}], "words": [{"w": "澌灭", "t": "消灭干净"}, {"w": "澌流", "t": "流淌,流水"}, {"w": "澌亡", "t": "灭绝消亡"}, {"w": "澌泯", "t": "消失"}, {"w": "澌涣", "t": "消散"}, {"w": "澌静", "t": "消失而归于平静。"}]}, {"meaning": "解冻时河中流动的冰块。", "cites": [{"t": "候吏还白,河水流澌,无船,不可济。", "b": "《后汉书·王霸传》"}]}, {"meaning": "死尸。", "cites": [{"t": "出见负豕于涂,腐澌于沟,不以为凶者,洿辱自在彼人,不着己之身也。", "b": "《论衡》"}]}, {"meaning": "泛指冰。", "cites": [{"t": "喜轻澌初绽微和渐入。", "b": "宋·杜安世《折红梅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('5999wx','潸','1','shān','氵','15','','[{"pinyin": "shān", "defs": [{"meaning": "(形声。从水,散省声。本义:流泪的样子) 同本义。", "cites": [{"t": "潸,涕流貌。", "b": "《说文》"}, {"t": "流涕长潸。", "b": "《史记·扁仓传》"}, {"t": "潸焉出涕。", "b": "《诗·小雅·大东》"}], "words": [{"w": "潸泫", "t": "潸然,潸潸。泪流不止的样子。"}]}, {"meaning": "流泪。", "cites": [{"t": "肠断离家泪暗潸。", "b": "清·湘灵子《轩亭冤·哭墓》"}], "words": [{"w": "潸慨", "t": "流泪感叹"}, {"w": "潸泪", "t": "流泪。"}]}, {"meaning": "泪水。", "cites": [{"t": "茵席留余潸。", "b": "陆游《楼上醉书》"}], "words": [{"w": "潸流", "t": "泪水流淌。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6000wx','潦','1','láo lǎo lào liáo','氵','15','','[{"pinyin": "láo", "defs": [{"meaning": "水名。即“涝水” 。在今陕西省户县境,北入渭河。"}]}, {"pinyin": "lǎo", "defs": [{"meaning": "雨水盛大的样子。", "cites": [{"t": "水潦降,不献鱼鳖。", "b": "《礼记》"}], "words": [{"w": "潦浸", "t": "指大雨泛滥成灾"}, {"w": "潦潦", "t": "雨大水流的样子"}, {"w": "潦雨", "t": "大雨"}, {"w": "潦水", "t": "雨后的积水。"}]}, {"meaning": "雨后积水。", "cites": [{"t": "潦水尽而寒潭清。", "b": "唐·王勃《滕王阁序》"}, {"t": "秋深潦缩。", "b": "宋·陆游《过小孤山大孤山》"}]}]}, {"pinyin": "lào", "defs": [{"meaning": "水淹没;雨多。", "cites": [{"t": "潦,雨水大皃。", "b": "《说文》"}, {"t": "禹之时,十年九潦,", "b": "《庄子·秋水》"}], "words": [{"w": "潦旱", "t": "谓水涝与干旱"}, {"w": "潦灾", "t": "水灾"}, {"w": "潦岁", "t": "水涝之年。"}]}]}, {"pinyin": "liáo", "defs": [{"meaning": "水名。"}, {"meaning": "今辽宁省的辽河。"}, {"meaning": "江西省修水的支流南潦河、北潦河。"}, {"meaning": "河南省白河的支流。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6001wx','潲','1','shào','氵','15','','[{"pinyin": "shào", "defs": [{"meaning": "[方言] 一种猪饲料,用泔水、米糠、野菜、剩饭等煮成", "cites": [{"t": "潲,豕食。", "b": "《广韵》"}]}, {"meaning": "雨斜落下来", "words": [{"w": "东边潲雨", "t": ""}]}, {"meaning": "[方言] 洒水"}, {"meaning": "[方言] 往后挣挫", "cites": [{"t": "[骡子]一见炮就往后潲,怎么也套不上去。", "b": "魏巍《东方》"}]}]}]','jingmo-wenyan');
