INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6004wx','潼','1','tóng','氵','15','','[{"pinyin": "tóng", "defs": [{"meaning": "(形声。从水,童声。本义:潼水)。"}, {"meaning": "同本义。"}, {"meaning": "在四川省梓潼县境内,南流注入垫江。", "cites": [{"t": "潼,潼水也,出广汉梓潼北界,南入垫江。", "b": "《说文》"}]}, {"meaning": "在安徽省五河县境。"}, {"meaning": "在陕西省潼关县境。"}, {"meaning": "关隘名 。在陕西省潼关县。", "cites": [{"t": "马超、成宜,同恶相济,滨据河潼,求逞所欲。", "b": "《文选·潘勖·册魏公九钖文》"}]}, {"meaning": "云起的样子。引申为盛多。", "cites": [{"t": "潼滃蔚荟,林木来会,津液下降,流潦霈。", "b": "汉·焦赣《易林》"}]}, {"meaning": "高貌。", "cites": [{"t": "沫潼潼而高厉。", "b": "宋玉《高唐赋》"}]}]}]','jingmo-wenyan');
