INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6006wx','憬','1','jǐng','忄','15','','[{"pinyin": "jǐng", "defs": [{"meaning": "觉悟。", "cites": [{"t": "憬,觉悟也。从心,景声。", "b": "《说文》"}], "words": [{"w": "憬悟", "t": "醒悟。"}]}, {"meaning": "远行地。", "cites": [{"t": "憬彼淮夷。", "b": "《诗·鲁颂·泮水》"}], "words": [{"w": "憬彼", "t": "遥远的样子"}, {"w": "憬憬", "t": "遥远的样子。"}]}, {"meaning": "远。", "cites": [{"t": "荒憬尽怀忠,梯航已自通。", "b": "贺知章诗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6007wx','憧','1','chōng','忄','15','','[{"pinyin": "chōng", "defs": [{"meaning": "(形声。从心,童声。本义:心神不定)。"}, {"meaning": "同本义。", "cites": [{"t": "憧,意不定也。", "b": "《说文》"}, {"t": "憧憧往来。", "b": "《易·咸》"}, {"t": "心憧憧若涉大川,遭风而未薄。", "b": "《盐铁论》"}]}, {"meaning": "愚笨的。", "cites": [{"t": "作起不敬以欺惑憧愚。", "b": "《大戴礼记·千乘》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6008wx','寮','1','liáo','宀','15','','[{"pinyin": "liáo", "defs": [{"meaning": "(形声。从宀(mián),表示与房屋有关,尞(liáo)声。本义:小窗)。"}, {"meaning": "同本义。", "cites": [{"t": "寮,穿也。", "b": "《说文》"}, {"t": "寮,小窗也。", "b": "《苍颉篇》"}, {"t": "交绮豁以疏寮。", "b": "张衡《西京赋》"}, {"t": "皦日笼光于绮寮。", "b": "左思《魏都赋》"}, {"t": "原来是大人家,有两层窗寮,外面为窗,里面为寮。", "b": "《金瓶梅词话》"}]}, {"meaning": "假借为“僚”。百官;官吏。后多作“僚”。", "cites": [{"t": "同官为寮,吾尝同寮,敢不尽心乎?", "b": "《左传·文公七年》"}, {"t": "今吾子之教官寮。", "b": "《国语·鲁语》"}, {"t": "勿寮勿从。", "b": "《国语·晋语》"}], "words": [{"w": "寮佐", "t": "僚属佐吏"}, {"w": "寮寀", "t": "百官。同僚寀"}, {"w": "寮人", "t": "做官的人,官员"}, {"w": "寮庶", "t": "百官,众官"}, {"w": "寮位", "t": "官位"}, {"w": "寮吏", "t": "属吏"}, {"w": "寮司", "t": "各衙署长官"}, {"w": "寮属", "t": "僚属;属官。"}]}, {"meaning": "民族名 。老挝国内的主要民族。泰国北部及东北部也有寮人。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6009wx','窳','1','yǔ','穴','15','','[{"pinyin": "yǔ", "defs": [{"meaning": "凹陷;低下。", "cites": [{"t": "生而首上圩顶,故因名丘云。", "b": "《史记》"}], "words": [{"w": "窳儿", "t": "山顶上的缺口"}, {"w": "窳下", "t": "凹陷;低下"}, {"w": "窳隆", "t": "凹凸;卑和高"}, {"w": "窳曲", "t": "塌陷歪斜的样子。"}]}, {"meaning": "疵病;粗劣。", "cites": [{"t": "俗不偷薄,器不行窳。", "b": "《新唐书》"}], "words": [{"w": "窳陋", "t": "粗劣简陋"}, {"w": "窳薄", "t": "粗劣;浅陋。"}]}, {"meaning": "败坏,腐败。", "cites": [{"t": "天下一大器也,用之久,则必弊窳残缺。", "b": "元·郝经《玄政议》"}], "words": [{"w": "窳敝", "t": "腐败;调敝"}, {"w": "窳弱", "t": "衰弊。"}]}, {"meaning": "懒惰。", "cites": [{"t": "爱子不惰食,惰民不窳,而庸民无所于农,是必农。", "b": "《商君书》"}], "words": [{"w": "窳怠", "t": "懒惰;懈怠"}, {"w": "窳农", "t": "惰农。"}]}, {"meaning": "羸弱。", "cites": [{"t": "赢窳则寿命短。", "b": "《论衡》"}], "words": [{"w": "窳陋", "t": "羸弱。"}]}, {"meaning": "谓器中空空。", "cites": [{"t": "囊橐罄留储,釜甑恒若窳。", "b": "明·刘基《久雨坏墙园蔬尽压怅然成诗》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6010wx','谳','1','yàn','讠','15','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从言,献声。本义:审判定罪)。"}, {"meaning": "同本义。", "cites": [{"t": "主谳者。", "b": "清·方苞《狱中杂记》"}, {"t": "主谳者亦各罢去", "b": ""}], "words": [{"w": "谳词", "t": "结案定罪的文书"}, {"w": "谳治", "t": "审理案件"}, {"w": "谳平", "t": "审议,平议刑狱"}, {"w": "谳事", "t": "审理案件"}, {"w": "谳囚", "t": "审讯犯人"}, {"w": "谳案", "t": "审理定案。"}]}, {"meaning": "将案情上报;请示。", "cites": [{"t": "若州郡县所不能决者,谳之廷尉。", "b": "《晋书·姚兴载记》"}], "words": [{"w": "谳奏", "t": "将案情向朝廷上报或请示"}, {"w": "谳文", "t": "向上司申报的议刑公文。"}]}, {"meaning": "判明。", "cites": [{"t": "向使刺谳其诚伪,考正其曲直,原始而求其端,则刑礼之用判然离矣。", "b": "《驳复仇议》"}]}, {"meaning": "案件。", "cites": [{"t": "[定国] 冬月请治谳,饮酒益精明。", "b": "《汉书》"}], "words": [{"w": "谳牍", "t": "判案的案卷。"}]}, {"meaning": "犯人的供词。", "cites": [{"t": "拷治榜掠,无所得谳。", "b": "清·严有禧《漱华随笔·姜熊狱》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6011wx','褴','1','lán','衤','15','','[{"pinyin": "lán", "defs": [{"meaning": "(形声。从衣,监声。本义:无缘饰的破旧短衣) 无边饰的衣服。", "cites": [{"t": "褴,裯谓之褴褛。褴,无缘也。", "b": "《说文》"}, {"t": "几人贫衣被丑敝,或谓之褴褛,故《左传》曰,筚路褴褛,以启山林,殆谓此也。", "b": "扬雄《方言三》"}, {"t": "无缘之衣谓之褴。", "b": "扬雄《方言四》"}]}, {"meaning": "又。", "cites": [{"t": "楚谓无缘之衣谓之褴,紩衣谓之褛。", "b": ""}]}]}]','jingmo-wenyan');
