('6012wx','褟','1','tā','衤','15','','[{"pinyin": "tā", "defs": [{"meaning": "贴身的衣衫：汗～儿。"}, {"meaning": "在衣边上缝（花边）：～花边儿。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6013wx','褫','1','chǐ','衤','15','','[{"pinyin": "chǐ", "defs": [{"meaning": "(形声。从衣,虒(sī)声。本义:夺去衣服)。"}, {"meaning": "同本义。", "cites": [{"t": "终朝三褫。", "b": "《易·讼》"}, {"t": "念解佩而褫绅。", "b": "《雪赋》"}, {"t": "乃褫豪民衣自衣。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "褫衿", "t": "剥去衣冠。旧时生员等犯罪,必先由学官褫夺衣冠,革除功名之后,才能动刑拷问。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6014wx','谵','1','zhān','讠','15','','[{"pinyin": "zhān", "defs": [{"meaning": "多言。", "cites": [{"t": "耄喜谵谆语,衰常踸踔行。", "b": "宋·陆游《霜晴》"}], "words": [{"w": "谵谆", "t": "叨唠。"}]}, {"meaning": "说胡话,特指病中说胡话。", "cites": [{"t": "谵妄烦乱,啼笑骂詈。", "b": "李时珍《本草纲目·序例上》"}], "words": [{"w": "谵言", "t": "病中的胡言乱语。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6015wx','熨','1','yùn yù','火','15','','[{"pinyin": "yùn", "defs": [{"meaning": "(形声。从火,尉(yù)声。本义:用金属器具加热,按压衣服,使之平贴)。"}, {"meaning": "同本义。", "cites": [{"t": "衣裳不整,伏床熨之。", "b": "《南史》"}], "words": [{"w": "熨衣", "t": "烫平衣服。"}]}, {"meaning": "紧贴。", "cites": [{"t": "以身熨之。", "b": "《世说新语》"}], "words": [{"w": "熨贴", "t": "贴切;妥帖。"}]}, {"meaning": "用药热敷。", "cites": [{"t": "汤熨之所及。", "b": "《韩非子·喻老》"}]}]}, {"pinyin": "yù", "defs": [{"meaning": "a.用字、用词合适，恰当，妥帖；b.心情安宁、舒畅；c.方言，事情完全办妥。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6016wx','屦','1','jù','尸','15','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从履(鞋子)省,娄声。本义:用麻、葛等制成的单底鞋) 同本义。后泛指鞋。", "cites": [{"t": "屦,履也。", "b": "《说文》。段注:“今时所谓履者,自汉以前皆名屦。”"}, {"t": "掌王及后之服屦。", "b": "《周礼·屦人》"}, {"t": "共其资粮屝屦。", "b": "《左传·僖公四年》。疏:“丝作之曰履,麻作之曰屝,粗者谓之屦。”"}, {"t": "纠纠葛屦,可以履霜。", "b": "《诗·魏风·葛屦》"}], "words": [{"w": "屦贱踊贵(因受刖刑而断足的人多,鞋没有了,售价低贱;然而购踊(假脚)的人多,踊价一时暴涨", "t": ""}, {"w": "屦人", "t": "周礼官名。天官之属,掌管王与后的衣服鞋屦"}, {"w": "屦及剑及", "t": "比喻行动坚决迅速,急起直追"}, {"w": "屦缕", "t": "织屦缉马。"}]}, {"meaning": "践踏。", "cites": [{"t": "身屦典军。", "b": "《史记·季布栾布传》"}, {"t": "屦般首,带修蛇。(般首:指虎一类猛兽。)", "b": "扬雄《羽猎赋》"}], "words": [{"w": "屦企", "t": "踮脚而望"}, {"w": "屦校", "t": "带上脚镣。校:铐足的刑具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6017wx','嬉','1','xī','女','15','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从女,喜声。本义:无拘束地游戏)。"}, {"meaning": "同本义。", "cites": [{"t": "追渔父以同嬉。", "b": "《文选·张衡·归田赋》"}, {"t": "业精于勤荒于嬉。", "b": "韩愈《进学解》"}], "words": [{"w": "嬉娱", "t": "嬉戏娱乐"}, {"w": "嬉弄", "t": "游戏;玩耍;戏弄;玩弄"}, {"w": "嬉宕", "t": "嬉戏游乐"}, {"w": "嬉春", "t": "游乐于春光之中。"}]}, {"meaning": "开玩笑,作弄嘲笑。", "cites": [{"t": "虽嬉笑怒骂之辞,皆可书而诵之。", "b": "《宋史·苏轼传》"}], "words": [{"w": "嬉笑怒骂,皆成文章", "t": "不拘题材形式,任意发挥,皆成妙文。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6018wx','勰','1','xié','力','15','','[{"pinyin": "xié", "defs": [{"meaning": "和谐,协调。", "cites": [{"t": "词必先有调,而后以词填之。词即音也。亦有自度腔者,先随意为长短句,后勰以律。", "b": "况周颐《蕙风词话》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6019wx','戮','1','lù','戈','15','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。本义:斩,杀)。"}, {"meaning": "同本义(表示处以死刑,特指杀死人后陈尸示众)。", "cites": [{"t": "戮,杀也。字亦作剹。", "b": "《说文》"}, {"t": "戮谓膊焚辜肆。", "b": "《周礼·掌戮》注"}, {"t": "防淫除邪,戮之以五刑。", "b": "《荀子·王制》"}, {"t": "俘囚为盗耳,晓当尽戮之。", "b": "《资治通鉴》"}], "words": [{"w": "戮佞", "t": "铲除奸佞"}, {"w": "戮身", "t": "杀身"}, {"w": "戮挫", "t": "诛杀折辱"}, {"w": "戮杀", "t": "杀戮"}, {"w": "戮害", "t": "杀害"}, {"w": "戮罪", "t": "杀戮有罪的人"}, {"w": "戮死", "t": "受戮而死。"}]}, {"meaning": "陈尸示众。", "cites": [{"t": "三奸同罪,请杀其生者,而戮其死者。", "b": "《国语·晋语》。注:“陈尸为戮。”"}], "words": [{"w": "戮尸", "t": "陈尸示众"}, {"w": "戮尸枭首", "t": "斩杀死者的尸体,并砍下他的头颅。"}]}, {"meaning": "惩罚。", "cites": [{"t": "王使执而戮之。", "b": "《国语》"}], "words": [{"w": "戮人", "t": "戮民。受过刑罚的罪人"}, {"w": "戮余", "t": "刑戮之余。指受刑后的余生"}, {"w": "戮死", "t": "受戮而死"}, {"w": "戮辱", "t": "受刑被辱。"}]}, {"meaning": "羞辱。", "cites": [{"t": "不用命戮于社。", "b": "《书·甘誓》"}, {"t": "贾季戮臾骈。", "b": "《左传·文公六年》"}], "words": [{"w": "戮笑", "t": "羞辱讥笑。"}]}, {"meaning": "(形声。本义:并力,合力)同本义。", "cites": [{"t": "勠,并力也。从力,戮声。", "b": "《说文》"}, {"t": "与诸侯戮力同心。", "b": "《国语·齐语》"}, {"t": "勠力同忧。", "b": "《战国策·中山策》"}, {"t": "戮力攻秦。", "b": "《汉书·高帝纪》"}], "words": [{"w": "戮力", "t": ""}]}]}]','jingmo-wenyan');
