INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6021wx','缬','1','xié','纟','15','','[{"pinyin": "xié", "defs": [{"meaning": "中国古代的一种印染方法。", "cites": [{"t": "缬,谓以丝缚缯染之,解丝成文曰缬也。", "b": "唐·玄应《一切经音义》"}], "words": [{"w": "缬帛", "t": "染印彩帛"}, {"w": "夹缬", "t": "唐代的一种印花锦。"}]}, {"meaning": "有花纹的丝织品。", "cites": [{"t": "衣绫绮缬。", "b": "《魏书》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6022wx','缮','1','shàn','纟','15','','[{"pinyin": "shàn", "defs": [{"meaning": "(形声。从糸(mì),善声。本义:修补;修整)。"}, {"meaning": "同本义。", "cites": [{"t": "缮,补也。", "b": "《说文》"}, {"t": "缮完葺墙,以待宾客。", "b": "《左传·襄公三十一年》"}, {"t": "凡治,故造新皆谓之缮也。", "b": "《珠丛》"}, {"t": "缮城郭。", "b": "《左传·襄公三十年》"}], "words": [{"w": "缮治", "t": "修补;整治"}, {"w": "缮完", "t": "修整,营建"}, {"w": "缮饰", "t": "修理整治;修葺装饰"}, {"w": "缮理", "t": "修理;修缮"}, {"w": "缮修", "t": "修缮;修补"}, {"w": "缮造", "t": "修造"}, {"w": "缮性", "t": "涵养本性"}, {"w": "缮葺", "t": "修理房屋、墙垣等。"}]}, {"meaning": "制造;整治。", "cites": [{"t": "缮兵甲,具卒乘。", "b": "《左传·隐公元年》"}], "words": [{"w": "缮甲", "t": "整治武器装备"}, {"w": "缮兵", "t": "整治武备"}, {"w": "缮理", "t": "整治,整顿。"}]}, {"meaning": "工整地抄写。", "cites": [{"t": "然后退扫闲轩,缮写呈上。", "b": "李白《与韩荆州书》"}], "words": [{"w": "缮录", "t": "誊写"}, {"w": "缮发", "t": "抄写后发出。"}]}, {"meaning": "编录文籍。", "cites": [{"t": "于是裂纸数千,缮写其兄里系年貌。", "b": "清·黄宗羲《万里寻兄记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6023wx','缯','1','zēng zèng','纟','15','','[{"pinyin": "zēng", "defs": [{"meaning": "(形声。从糸(mì),曾声。本义:古代对丝织品的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "缯,帛也。", "b": "《说文》"}, {"t": "杂帛曰缯。", "b": "《三苍》"}, {"t": "瘗缯。", "b": "《礼记·礼运》"}, {"t": "赤绨缘缯。", "b": "《汉书·匈奴传》。注:“缯者帛之总名。”"}, {"t": "从弟子女十人所,皆衣缯单衣。", "b": "《史记·滑稽列传》"}, {"t": "灌婴,睢阳贩缯者也。", "b": "《汉书·灌婴传》"}], "words": [{"w": "缯服", "t": "丝织的衣服"}, {"w": "缯絮", "t": "丝絮。也指丝絮作成的棉衣"}, {"w": "缯纩", "t": "丝布与丝棉絮的合称"}, {"w": "缯帛", "t": "丝绸之统称"}, {"w": "缯布", "t": "缯帛布疋。"}]}, {"meaning": "古代射鸟用的箭。", "cites": [{"t": "治其缯缴。", "b": "《战国策·楚策四》"}, {"t": "好弋者先具缴与缯。", "b": "《淮南子·说山》"}, {"t": "缯缴充蹊。", "b": "《三国志·袁绍传注》"}], "words": [{"w": "缯缴", "t": "即矰缴。猎取飞鸟的射具。缴为系在短箭上的丝绳;比喻陷害他人的手段。"}]}, {"meaning": "古国名 。姒姓,相传为夏禹后裔。"}, {"meaning": "姓。"}]}, {"pinyin": "zèng", "defs": [{"meaning": "绑;扎。", "cites": [{"t": "缯丝为弦。", "b": "《新增格古要论·制琴法》"}]}]}]','jingmo-wenyan');
