INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6025wx','畿','1','jī','田','15','','[{"pinyin": "jī", "defs": [{"meaning": "(形声。从田,幾省声。本义:国都四周的广大地区)。"}, {"meaning": "古代王都所领辖的方千里地面。后指京城所管辖的地区。", "cites": [{"t": "畿,天子千里地。以逮近言之则曰畿也。", "b": "《说文》"}, {"t": "邦畿方千里。", "b": "《周礼·大行人》"}, {"t": "方千里曰王畿。", "b": "《周礼·职方式》"}, {"t": "邦畿千里。", "b": "《诗·商颂·玄鸟》"}, {"t": "视学京畿。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "畿尉", "t": "卫戍京城的武官"}, {"w": "畿限", "t": "王畿的界限"}, {"w": "畿甸", "t": "京城效区"}, {"w": "畿兵", "t": "驻京都的士兵。"}]}, {"meaning": "王畿之外的九畿。", "cites": [{"t": "乃以九畿之籍。", "b": "《周礼·大司马》。注:“犹限也。”按,九畿,国畿及侯甸、男采、卫蛮夷也。唐虞称服,周称畿。"}], "words": [{"w": "畿岳", "t": "畿服。天下"}, {"w": "畿疆", "t": "王畿和九畿的疆界"}, {"w": "畿夏", "t": "古指以京畿为中心的我国中原地区。"}]}, {"meaning": "门内;门槛。", "cites": [{"t": "薄送我畿。", "b": "《诗·邶风·谷风》"}]}, {"meaning": "指田野。"}, {"meaning": "西汉末,王莽改国号为新时,长安西市称“畿”。"}]}]','jingmo-wenyan');
