INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6027wx','耨','1','nòu','耒','16','','[{"pinyin": "nòu", "defs": [{"meaning": "(会意。从耒,从辱。耒,翻土的工具。字本作“辱”,从辰,从寸。“辰”表示蜃的贝壳,古代的耕具,“寸”表示用手操作。“辱”借为“耻辱”字,遂产生“耨”字。本义:锄草,耕作)。"}, {"meaning": "同本义。", "cites": [{"t": "人耨必以旱,使地肥而土缓。(以:由于。)", "b": "《吕氏春秋》"}], "words": [{"w": "耨耕", "t": "泛指农活。"}]}, {"meaning": "骂。", "cites": [{"t": "早忘了咒,不记得低低耨。", "b": "《翠裙腰·闺怨》"}]}, {"meaning": "呻吟。", "cites": [{"t": "一个姿情的不休,一个哑声儿厮耨。", "b": "《西厢记》"}]}, {"meaning": "钩儿锄,一种锄草的农具。", "cites": [{"t": "释其锄耨而下泪。", "b": "贾谊《旱云赋》"}]}]}]','jingmo-wenyan');
