INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6034wx','聱','1','áo','耳','16','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从耳敖声。本义:不接受意见)。"}, {"meaning": "同本义。", "cites": [{"t": "聱,不入人语也。", "b": "《广雅》"}, {"t": "彼诮为聱者,为其不相从听。", "b": "元结《自释》"}], "words": [{"w": "聱牙", "t": "乖忤,抵触。亦谓与人意见不同,不随世俗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6035wx','螯','1','áo','虫','16','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从虫,敖声。本义:节肢动物的螯夹)。"}, {"meaning": "节足动物的第一对脚。足端两歧,开合如钳,可取食并作防卫之用。", "cites": [{"t": "蟹六跪而二螯。", "b": "《荀子·劝学》"}], "words": [{"w": "螯胶", "t": "百足蟹所煮成的胶。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6036wx','髻','1','jì','髟','16','','[{"pinyin": "jì", "defs": [{"meaning": "(形声。从髟(biāo),表示与毛发有关,吉声。本义:发髻) 同本义。", "cites": [{"t": "头上倭堕髻。", "b": "《乐府诗集·陌上桑》"}, {"t": "椎髻仰面。", "b": "明·魏学洢《核舟记》"}, {"t": "汝梳双髻(髻,梳在头顶上的发结。)", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "髻珠", "t": "髻上的明珠;比喻主旨、善谛"}, {"w": "髻丫", "t": "盘在头顶左右两侧的发结"}, {"w": "髻根", "t": "发髻盘结如盘根错结"}, {"w": "髻子", "t": "即发髻,头发拖到后面结成一个髻。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6037wx','髭','1','zī','髟','16','','[{"pinyin": "zī", "defs": [{"meaning": "嘴唇上边的短须。", "cites": [{"t": "頾,口上毛也。从须,此声。", "b": "《说文》。字亦作髭。"}, {"t": "至于灵王,生而有髭。", "b": "《左传·昭公二十六年》"}, {"t": "下担捋髭须。", "b": "《乐府诗集·陌上桑》"}, {"t": "微髭。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "髭发", "t": "口上毛叫髭,头上毛叫发。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6038wx','髹','1','xiū','髟','16','','[{"pinyin": "xiū", "defs": [{"meaning": "以漆漆物。", "cites": [{"t": "木器髹者千枚。", "b": "《史记·货殖列传》"}], "words": [{"w": "髹彤", "t": "涂以丹漆"}, {"w": "髹饰", "t": "用赤黑色的油漆涂物为饰"}, {"w": "髹漆", "t": "以漆涂物。"}]}, {"meaning": "——见“竹节虫”(zhújiéchóng)。"}]}]','jingmo-wenyan');
