INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6040wx','熹','1','xī','灬','16','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从火,喜声。本义:烤炙) 同本义。", "cites": [{"t": "熹,炙也。", "b": "《说文》。字亦作熺。"}]}, {"meaning": "炽热。", "cites": [{"t": "熹,热也,炽也。", "b": "《玉篇》"}, {"t": "熺,炽也。", "b": "《广雅》"}, {"t": "熺炭重燔。", "b": "木华《海赋》。注:“炭之有光者也。”"}]}, {"meaning": "亮;光明。", "cites": [{"t": "有时而星熺。", "b": "《管子·侈靡》"}, {"t": "明镫熺炎光。", "b": "《文选·赠五官中郎将诗》"}, {"t": "东暾澹未熹,北吹寒更寂。", "b": "杨万里诗"}], "words": [{"w": "熹微;熹烂", "t": "灿烂的光彩。"}]}]}]','jingmo-wenyan');
