INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6044wx','磬','1','qìng','石','16','','[{"pinyin": "qìng", "defs": [{"meaning": "(象形。甲骨文字形。手又持小槌像击磬的形象。本义:古代乐器。用石或玉雕成。悬挂于架上,击之而鸣)。"}, {"meaning": "同本义。", "cites": [{"t": "磬,乐石也。", "b": "《说文》"}, {"t": "小华之山多磬石。", "b": "《山海经·西山经》"}, {"t": "泗滨浮磬。", "b": "《书·禹贡》"}, {"t": "笙磬同音。", "b": "《诗·小雅·鼓钟》"}, {"t": "依我磬声。", "b": "《诗·商颂·那》"}, {"t": "语寡人以忧者击磬。", "b": "《淮南子·泛论》"}, {"t": "钟磬置于水中。", "b": "宋·苏轼《石钟山记》"}, {"t": "西门豹簪笔磬折,向河立待良久。", "b": "《西门豹治邺》"}], "words": [{"w": "磬人", "t": "负责治磬的官员"}, {"w": "磬工", "t": "负责制磬的官员"}, {"w": "磬色", "t": "玉磬的光彩"}, {"w": "磬师", "t": "古乐官名"}, {"w": "磬管", "t": "两种古乐器名。"}]}, {"meaning": "弯腰。表示谦恭。", "cites": [{"t": "簪笔磬折。", "b": "《史记·滑稽列传》"}], "words": [{"w": "磬折", "t": "弯腰;卑躬屈膝"}, {"w": "磬沼", "t": "形容曲折的池。"}]}, {"meaning": "假借为“骋”。纵马奔驰。", "cites": [{"t": "抑磬控忌,抑纵送忌。", "b": "《诗·郑风·大叔于田》"}]}, {"meaning": "空,尽。", "cites": [{"t": "金积折廉,璧袭无理,磬龟无腹,蓍策日施 。", "b": "《淮南子·览冥》"}]}]}]','jingmo-wenyan');
