('6050wx','薨','1','hōng','艹','16','','[{"pinyin": "hōng", "defs": [{"meaning": "(形声。从死,瞢(méng)省声。本义:古代称诸侯之死。后世有封爵的大官之死也称薨)。"}, {"meaning": "同本义。", "cites": [{"t": "薨,死也。", "b": "《尔雅》"}, {"t": "鲁文公薨,而东门遂镣适立庶。", "b": "《左传·昭公三十二年》"}, {"t": "昭王薨。", "b": "《史记·魏公子列传》"}], "words": [{"w": "薨落", "t": "死的意思。通常指诸侯之死"}, {"w": "薨奄", "t": "指王侯死亡"}, {"w": "薨殁", "t": "指王侯死亡"}, {"w": "薨殂", "t": "指王侯之死"}, {"w": "薨背", "t": "犹薨殂"}, {"w": "薨逝", "t": "犹薨殂"}, {"w": "薨谢", "t": "薨殂。"}]}, {"meaning": "杀害。", "cites": [{"t": "闭太后于后宫,薨怿于下省。", "b": "北魏·杨衒之《洛阳伽蓝记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6051wx','檠','1','qíng','木','16','','[{"pinyin": "qíng", "defs": [{"meaning": "( 形声。从木,敬声。本义:矫正弓弩的器具)。"}, {"meaning": "同本义。", "cites": [{"t": "檠,榜也。…弛弓防损伤,以竹若木辅于里绳约之。", "b": "《说文》"}, {"t": "不能绁檠巧用。", "b": "《诗·角弓》传"}, {"t": "檠不正而可以正弓。", "b": "《淮南子·说山》"}, {"t": "弓待檠而后能调。", "b": "《淮南子·脩务》"}, {"t": "檠弓弩。", "b": "《汉书·苏武传》"}], "words": [{"w": "檠枻", "t": "矫正弓弩的器具"}, {"w": "檠榜", "t": " 矫正弓弩的器具。"}]}, {"meaning": "灯台。", "cites": [{"t": "梦断酒醒山雨绝,笑看饥鼠上灯檠。", "b": "苏轼《侄安节远来夜坐》"}]}, {"meaning": "灯。", "cites": [{"t": "投僧避夜雨,古檠昏无膏。", "b": "王安石《自州追送朱氏女弟》"}]}]}]','jingmo-wenyan');
