INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6057wx','橛','1','jué','木','16','','[{"pinyin": "jué", "defs": [{"meaning": "木橛子,短木桩。", "cites": [{"t": "橜,弋也。从木,厥声。一曰门梱也。", "b": "《说文》"}, {"t": "吾处也,若橜株驹。", "b": "《列子·黄帝》"}, {"t": "作厥(橛)株拘。", "b": "《庄子·达生》。注:“凡竖木而短者,皆得曰 橜。”"}, {"t": "苗高二三尺,每路打橛。", "b": "宋应星《天工开物》"}], "words": [{"w": "橛杙", "t": "木桩"}, {"w": "橛眼", "t": "木桩插入地面留下的孔穴。"}]}, {"meaning": "折断。", "cites": [{"t": "树本浅,根垓不深,未必橛也;飘风起,暴雨至,拔必先矣。", "b": "汉·刘向《说苑》"}]}, {"meaning": "敲,打击。", "cites": [{"t": "以其皮为鼓,橛以雷兽之骨,声五百里,以咸天下。", "b": "《山海经·大荒东经·东海》"}]}]}]','jingmo-wenyan');
