('6058wx','橇','1','qiāo','木','16','','[{"pinyin": "qiāo", "defs": [{"meaning": "(形声。从木,毳(cuì)声。本义:古代在泥路上行走所乘之具)。"}, {"meaning": "同本义。", "cites": [{"t": "陆行乘车,水行乘船,泥行乘橇。", "b": "《史记·夏本纪》。?"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6059wx','樵','1','qiáo','木','16','','[{"pinyin": "qiáo", "defs": [{"meaning": "(形声。从木,焦声。本义:薪柴)。"}, {"meaning": "同本义。", "cites": [{"t": "樵,散木也。", "b": "《说文》"}, {"t": "樵彼桑薪。", "b": "《诗·小雅·白华》"}, {"t": "请无杆采樵者以诱之。", "b": "《左传·醒公十二年》"}, {"t": "樵蒸焜上。", "b": "《汉书·扬雄传》。注:“木薪也。”"}, {"t": "樵苏后炊。", "b": "《史记·淮阴侯传》"}], "words": [{"w": "樵山", "t": "柴薪堆积如山"}, {"w": "樵米", "t": "柴草与粮食"}, {"w": "樵斧", "t": "柴斧"}, {"w": "樵拾", "t": "樵采,采薪"}, {"w": "樵薪", "t": "柴薪"}, {"w": "樵苏", "t": "柴草"}, {"w": "樵担", "t": "柴担子。"}]}, {"meaning": "楼的别名。", "cites": [{"t": "为堑垒木樵。", "b": "《汉书·赵充国传》"}], "words": [{"w": "樵楼", "t": "谯楼"}, {"w": "樵门", "t": "谯楼之门。也泛指城门"}, {"w": "樵鼓", "t": "即谯楼之鼓,用以报更。"}]}, {"meaning": "焚烧。", "cites": [{"t": "焚之者何?樵之也;樵之者何?以火攻也。", "b": "《公羊传》"}]}]}]','jingmo-wenyan');
