('6061wx','橹','1','lǔ','木','16','','[{"pinyin": "lǔ", "defs": [{"meaning": "(形声。从木,鲁声。本义:大盾牌)。"}, {"meaning": "同本义。", "cites": [{"t": "橹,大盾也。", "b": "《说文》"}, {"t": "蒙之以甲以为橹。", "b": "《左传·襄公十年》"}, {"t": "泰山为橹。", "b": "《汉书·司马相如传》"}, {"t": "礼义以为干橹。", "b": "《礼记·儒行》"}, {"t": "流血漂橹。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "橹楯", "t": "大盾"}, {"w": "橹子", "t": "方言。手枪。"}]}, {"meaning": "顶部没有覆盖的远望楼。", "cites": [{"t": "修橹。", "b": "《孙子·谋攻》"}], "words": [{"w": "楼橹", "t": "古时军中用以侦察、防御或攻城的高台"}, {"w": "橹巢", "t": "上古人类的居处。有柴谓橹,在树曰巢"}, {"w": "橹棹", "t": "橹和棹都是划船的工具。"}]}, {"meaning": "比桨长大的划船工具,安在船尾或船旁。", "cites": [{"t": "在旁曰橹。", "b": "《释名》"}], "words": [{"w": "橹人", "t": "船工"}, {"w": "橹声", "t": "摇橹声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6062wx','樽','1','zūn','木','16','','[{"pinyin": "zūn", "defs": [{"meaning": "(形声。从木,尊声。本作“尊”。本义:盛酒器。中国古代的盛酒器具) 同本义。", "cites": [{"t": "有酒盈樽。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "金樽清酒斗十千。", "b": "唐·李白《行路难》"}, {"t": "座上客常满,樽中酒不空。", "b": "《全图绣像三国演义》"}], "words": [{"w": "樽杓", "t": "指饮酒之器"}, {"w": "樽桂", "t": "杯中的桂花酒"}, {"w": "樽酌", "t": "指饮酒之器"}, {"w": "樽酒", "t": "杯酒。"}]}, {"meaning": "往酒器里倒酒。", "cites": [{"t": "少倾,摆出酒席,四位樽酒论文。", "b": "《儒林外史》"}]}, {"meaning": "抑止。", "cites": [{"t": "樽流遁之观。", "b": "《淮南子·要略》。杨树达云:“樽,经传通作撙。”"}], "words": [{"w": "樽约", "t": "谓节约,樽,同“撙”"}, {"w": "樽节", "t": "节省。樽,通“撙”。"}]}]}]','jingmo-wenyan');
