INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6066wx','橐','1','tuó','木','16','','[{"pinyin": "tuó", "defs": [{"meaning": "(形声。从槖省,石声。)。"}, {"meaning": "同本义。", "cites": [{"t": "槖,囊也。", "b": "《说文》。按,小而有底曰橐,大而无底曰囊。"}, {"t": "宁子职纳槖饘焉。", "b": "《左传·僖公二十八年》"}, {"t": "乃裹糇粮,于橐于囊。", "b": "《诗·大雅·公刘》"}, {"t": "负书担橐。", "b": "《战国策·秦策》"}, {"t": "田乞盛阳生橐中,置坐中央。", "b": "《史记·田敬仲完世家》"}, {"t": "卬家将军以为(张)安世本持橐簪笔,事孝武帝数十年。", "b": "《汉书·赵充国传》。颜师古注:“橐,所以盛书也,有底曰囊,无底曰橐。簪笔者,插笔于首。”"}, {"t": "橐金数千。", "b": "清·张廷玉《明史》"}]}, {"meaning": "鼓风吹火器。", "cites": [{"t": "具炉橐,橐以牛皮。", "b": "《墨子·备穴》"}]}, {"meaning": "", "cites": [{"t": "重争士橐。(指依附诸侯或卿大夫。)", "b": "《韩非子·五蠹》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6067wx','翮','1','hé','羽','16','','[{"pinyin": "hé", "defs": [{"meaning": "(形声。从羽,鬲(gé)声。本义:羽毛中间的硬管)。"}, {"meaning": "尾羽或翼羽中那些大而硬的角质空心的羽轴。", "cites": [{"t": "翮,羽茎也。", "b": "《说文》"}, {"t": "羽本谓之翮。", "b": "《尔雅·释器》。郭注:“翮,鸟羽根也。”"}, {"t": "掌以时征羽翮之政于山泽之农。", "b": "《周礼·地官·羽人》"}]}, {"meaning": "羽毛。", "cites": [{"t": "取大鸟翮为两翼。", "b": "《汉书·王莽传下》"}, {"t": "南海则有羽翮齿革。", "b": "《荀子·王制》"}]}, {"meaning": "鸟类。", "cites": [{"t": "肯似林间翮,飞倦始知还。", "b": "胡寅《水调歌头》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6068wx','醛','1','quán','酉','16','','[{"pinyin": "quán", "defs": [{"meaning": "以乙醛为代表的一类很活泼的有机化合物,其特征是具有-CHO基,呈中度氧化态,比伯醇分子少两个氢原子,比羧酸少一个氧原子。"}]}]','jingmo-wenyan');
