('6073wx','赝','1','yàn','贝','16','','[{"pinyin": "yàn", "defs": [{"meaning": "(形声。从贝,雁声。本义:假的,伪造的) 同本义。", "cites": [{"t": "居然见真赝。", "b": "韩愈《酬隹少府》"}], "words": [{"w": "赝钻石;赝作", "t": "伪造。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6074wx','飙','1','biāo','风','16','','[{"pinyin": "biāo", "defs": [{"meaning": "(形声。从风,猋(biāo)声。本义:暴风)。"}, {"meaning": "同本义。", "cites": [{"t": "飙,扶摇风也。", "b": "《说文》。按,回风暴起,从下而上。"}, {"t": "感回飙而将ń。", "b": "马融《长笛赋》"}, {"t": "风发飙拂。", "b": "《汉书·扬雄传》"}, {"t": "飙举电至。(暴风起,闪电到。)", "b": "《盐铁论·世务》"}, {"t": "狂飙为我从天落。", "b": "毛泽东《蝶恋花·从汀州向长沙》"}], "words": [{"w": "狂飙", "t": "急骤的暴风"}, {"w": "清飙;飙忽", "t": "迅急的风"}, {"w": "飙驰", "t": "狂风大作。"}]}, {"meaning": "泛指风。", "cites": [{"t": "常恐秋节至,凉飙夺炎热。", "b": "古乐府《怨歌行》"}], "words": [{"w": "飙车", "t": "御风疾行的车。比喻车行迅速"}, {"w": "飙起", "t": "如风般的快速兴起。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6075wx','殪','1','yì','歹','16','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从歺è,壹声。歹,剔肉残剩的骨头,与“死”有关。本义:死)。"}, {"meaning": "同本义。", "cites": [{"t": "暴逆并殪,以渐冰消。", "b": "《三国演义》"}], "words": [{"w": "殪没", "t": "死亡。"}]}, {"meaning": "杀死。", "cites": [{"t": "左骖殪兮右刃伤。", "b": "《楚辞·九歌》"}, {"t": "殪,杀也。", "b": "《字汇》"}, {"t": "王乃大命文王殪戎殷。", "b": "《书·康诰》"}, {"t": "殪此大兕。", "b": "《诗·大雅·吉日》。传:“殪,壹发而死。”"}, {"t": "殪以为大甲。", "b": "《国语·晋语》。注:“一发而死曰殪。”"}, {"t": "蓺殪仆。", "b": "《汉书·司马相如传》"}, {"t": "遂举手助先生操刃,共殪狼。", "b": "明·马中锡《中山狼传》"}, {"t": "殪一贼。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "殪敌", "t": "将敌人致于死地"}, {"w": "殪仆", "t": "杀伤。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6076wx','霖','1','lín','雨','16','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从雨,林声。本义:久下不停的雨)。"}, {"meaning": "同本义。", "cites": [{"t": "霖,雨三日以往也。", "b": "《说文》"}, {"t": "天之无烈风淫雨。", "b": "《书·大传四》。注:“淫雨谓之霖。”"}, {"t": "凡雨三日以往为霖。", "b": "《左传·隐公九年》"}, {"t": "用汝作霖雨。", "b": "《国语·楚语》"}, {"t": "七月大霖雨者,人怨之所致。", "b": "《汉书·高帝纪》"}, {"t": "动商则秋霖春降。(动商:吹奏商调之曲。)", "b": "成公子安《啸赋》"}], "words": [{"w": "霖雨;霖霖", "t": "形容久雨不停。"}]}, {"meaning": "雨。", "cites": [{"t": "不知短发能多少,一滴秋霖白一茎。", "b": "韩偓《秋霖夜忆家》"}], "words": [{"w": "甘霖", "t": ""}]}, {"meaning": "久雨不止。", "cites": [{"t": "景公之时,霖雨十有七日。", "b": "《晏子春秋·谏》"}, {"t": "日夜霖雨。", "b": "《六韬》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6077wx','霏','1','fēi','雨','16','','[{"pinyin": "fēi", "defs": [{"meaning": "(形声。从雨,非声。本义:雨雪很盛的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "雨雪其霏。", "b": "《诗·邶风·北风》"}], "words": [{"w": "霏雪", "t": "纷飞的雪花"}, {"w": "霏落", "t": "纷纷散落。"}]}, {"meaning": "烟云气很浓密的样子。", "cites": [{"t": "骆驿纵横,烟霏雨散。", "b": "《文选·刘孝标·广绝交论》"}]}, {"meaning": "弥漫的云气。", "cites": [{"t": "若夫日出而林霏开,云归而岩穴瞑,晦明变化者,山间之朝暮也。", "b": "宋·欧阳修《醉翁亭记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6078wx','霓','1','ní','雨','16','','[{"pinyin": "ní", "defs": [{"meaning": "(形声。从雨,兒(ní)声。本义:副虹)。"}, {"meaning": "同本义,即虹的外环。大气中有时跟虹同时出现的一种光的现象,形成的原因和虹相同,只是光线在水珠中的反射比形成虹时多了一次,彩带排列的顺序和虹相反,红色在内,紫色在外。", "cites": [{"t": "霓,屈虹青赤或白色阴气也。", "b": "《说文》。按,雨与日相薄而成光,有雌雄,鲜者为雄虹。暗者为雌霓。"}, {"t": "虹霓也,云雾也,风雨也,四时也,此积气之成乎天者也。", "b": "《列子·无端》"}, {"t": "云披雾裂虹霓断,霹雳掣电捎平岗。", "b": "柳宗元《笼鹰词》"}, {"t": "霓为衣兮风为马。", "b": "唐·李白《梦游天姥吟留别》"}]}, {"meaning": "借指天空,高空。", "cites": [{"t": "羽旄扫霓,云旗拂天。", "b": "班固·《东都赋》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6079wx','錾','1','zàn','金','16','','[{"pinyin": "zàn", "defs": [{"meaning": "小凿,雕凿金石的工具。", "cites": [{"t": "錾,小凿也。从金,从斩,斩亦声。", "b": "《说文》"}, {"t": "鐫谓之錾。", "b": "《广雅·释器》"}, {"t": "用錾揭剥高处。", "b": "宋·李诫《营造法式》"}]}, {"meaning": "雕,刻。", "cites": [{"t": "罗延庆力大无穷,使一杆錾金枪,犹如天神一般。", "b": "《说岳全传》"}], "words": [{"w": "錾字;錾大理石", "t": ""}]}, {"meaning": "磨刀出锋。", "cites": [{"t": "铁棒有打錾。", "b": "《西厢记诸宫调》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6080wx','辚','1','lín','车','16','','[{"pinyin": "lín", "defs": [{"meaning": "发出急速、连续、短促、硬物相撞声,发出格格声。", "cites": [{"t": "车辚辚,马萧萧,行人弓箭各在腰。", "b": "杜甫《兵车行》"}], "words": [{"w": "辚辚", "t": "车行的声音。"}]}, {"meaning": "门下的作为支持物的横木条、石条或金属条。"}, {"meaning": "车轮。", "cites": [{"t": "亡马,不发户辚。", "b": "《淮南子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6081wx','臻','1','zhēn','至','16','','[{"pinyin": "zhēn", "defs": [{"meaning": "(形声。从至,秦声。本义:到,到达)。"}, {"meaning": "同本义。", "cites": [{"t": "臻,至也。", "b": "《说文》"}, {"t": "遄臻于卫。", "b": "《诗·邶风·泉水》"}, {"t": "饥馑荐臻。", "b": "《诗·大雅·云汉》"}, {"t": "丧乱并臻。", "b": "《国语·晋语二》"}, {"t": "舟车所臻,足迹所及,莫不被泽。", "b": "《盐铁论》"}, {"t": "其多少斋僧布施,买金银纸锭,记库焚烧,故有此善果臻身。", "b": "《西游记》。"}], "words": [{"w": "并臻", "t": "同时到来;一齐到达"}, {"w": "渐臻佳境;已臻上乘;日臻便利;臻到", "t": "臻至"}, {"w": "臻备", "t": "谓达到完备的程度。"}]}, {"meaning": "齐全;完备。", "cites": [{"t": "倘或礼物有些不臻,打将起来,我在后面好溜。", "b": "元·佚名《桃花女》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6082wx','遽','1','jù','辶','16','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,本义:送信的快车或快马)。"}, {"meaning": "同本义。", "cites": [{"t": "遽,传也。", "b": "《说文》"}, {"t": "以待达穷者与遽令。", "b": "《周礼·大仆》"}, {"t": "掌邦国传遽之小事。", "b": "《周礼·行夫》。注:“若今时乘传骑驿而使者也。”"}, {"t": "且使遽告于郑。", "b": "《左传·僖公三十三年》。注:“传车。”"}, {"t": "士曰传遽之臣。", "b": "《礼记·玉藻》"}], "words": [{"w": "遽人", "t": "驿卒;传达命令的人"}, {"w": "遽驿", "t": "传车和驿马"}, {"w": "遽传", "t": "驿车和传舍"}, {"w": "遽委", "t": "驿站车马和储存的粮食。"}]}, {"meaning": "乡名 。在今河北省元氏县附近。"}, {"meaning": "立刻;马上。", "cites": [{"t": "遽兴姜戎。", "b": "《左传·僖公三十二》"}, {"t": "北亦未敢遽轻吾国。", "b": "宋·文天祥《指南录后序》"}, {"t": "遽扑之。", "b": "《聊斋志异·促织》"}, {"t": "遽以不变名之。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "遽诺", "t": "马上承诺、答应"}, {"w": "遽理", "t": "马上或很快处理"}, {"w": "遽即", "t": "立即。"}]}, {"meaning": "就,竟。", "cites": [{"t": "岂遽善游哉。", "b": "《吕氏春秋·察今》"}, {"t": "此何遽不能为福乎?", "b": "《淮南子·人间训》"}, {"t": "遽惊谢曰。", "b": "清·周容《芋老人传》"}, {"t": "遽躬蹈之。", "b": "清·袁枚《祭妹文》"}]}, {"meaning": "惊慌。", "words": [{"w": "遽惶", "t": "惶遽,惊慌"}, {"w": "遽惕", "t": "惶恐戒惧"}, {"w": "遽戚", "t": "敬畏的样子"}, {"w": "遽容", "t": "恐惧的脸色。"}]}, {"meaning": "十分贫困,窘迫。", "cites": [{"t": "远近久承公名,令于是大遽,不敢移公。", "b": "《世说新语》"}]}, {"meaning": "急忙,匆忙。", "cites": [{"t": "遽数之不能终其物。", "b": "《礼记·儒行》"}, {"t": "公惧,遽见之。", "b": "《国语·晋语》"}, {"t": "遽契其舟。", "b": "《吕氏春秋·察今》"}, {"t": "遽曰:“为两郎僮,孰若为一郎僮耶?”", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "遽别", "t": "急速分别"}, {"w": "遽步", "t": "急步快走"}, {"w": "遽忙", "t": "匆忙"}, {"w": "遽几", "t": "急切期求"}, {"w": "遽淹", "t": "迅速而逝。"}]}, {"meaning": "快,迅速。", "cites": [{"t": "本乎疾者其势遽,故难得以晓也。", "b": "刘禹锡《天论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6083wx','氅','1','chǎng','毛','16','','[{"pinyin": "chǎng", "defs": [{"meaning": "用鸟类的羽毛缝制成的外衣。"}, {"meaning": "鹙鸟的羽毛。", "cites": [{"t": "尝见王恭乘高舆,被鹤氅裘。", "b": "刘义庆《世说新语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6084wx','瞟','1','piǎo','目','16','','[{"pinyin": "piǎo", "defs": [{"meaning": "斜着眼睛看", "words": [{"w": "瞟闪", "t": "眼光闪烁地斜看"}, {"w": "瞟扫", "t": "斜着眼睛扫视"}, {"w": "瞟眼", "t": "斜着眼看人"}, {"w": "瞟觑", "t": "斜着眼看人"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6085wx','瞠','1','chēng','目','16','','[{"pinyin": "chēng", "defs": [{"meaning": "瞪着眼看。", "cites": [{"t": "瞠,直视也。", "b": "《集韵》"}, {"t": "夫子奔逸绝尘,而回瞠若乎后矣。", "b": "《庄子·田子方》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6086wx','瞰','1','kàn','目','16','','[{"pinyin": "kàn", "defs": [{"meaning": "(形声。从目,敢声。本义:视;看)。"}, {"meaning": "同本义。", "cites": [{"t": "瞰,视也。", "b": "《广雅·释诂一》"}, {"t": "瞰四裔而抗棱。", "b": "《文选·班固·东都赋》"}, {"t": "左瞰暘谷。", "b": "《文选·张衡·东京赋》"}, {"t": "王使人矙夫子。", "b": "《孟子·离娄下》"}, {"t": "瞰帝唐之嵩高兮,脉隆周之大宁。", "b": "《汉书·扬雄》"}, {"t": "俯瞰九江水,旁瞻万里壑。", "b": "元稹《松鹤》"}]}, {"meaning": "从高的地方向下看,俯视。", "cites": [{"t": "瞰临城中。", "b": "《后汉书·光武纪上》注:“俯视日瞰。”"}, {"t": "下瞰峭壑阴森。", "b": "明·徐宏祖《徐霞客游记·游黄山记》"}], "words": [{"w": "瞰视", "t": "俯视"}, {"w": "瞰睨", "t": "俯视,近看"}, {"w": "瞰临", "t": "居高下视。"}]}, {"meaning": "窥视。", "cites": [{"t": "高明之家,鬼瞰其室。", "b": "汉·扬雄《解嘲》"}]}, {"meaning": "远望。", "cites": [{"t": "前瞰大海。", "b": "宋·沈括《梦溪笔谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6087wx','嚄','1','huō huò','口','16','','[{"pinyin": "huō", "defs": [{"meaning": "表示惊讶"}]}, {"pinyin": "huò", "defs": [{"meaning": "叹词,表示惊讶。", "cites": [{"t": "武帝下车泣曰:“嚄!大姊,何藏之深也!”", "b": "《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6088wx','嚆','1','hāo','口','16','','[{"pinyin": "hāo", "defs": [{"meaning": "呼叫。", "cites": [{"t": "吴人谓叫呼为嚆。", "b": "《集韵》"}, {"t": "焉知曾、史之不为桀、跖嚆矢也?", "b": "《庄子·在宥》。成玄英疏:“嚆,箭镞有吼猛声也。”"}], "words": [{"w": "嚆矢", "t": "响箭。喻先声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6089wx','噤','1','jìn','口','16','','[{"pinyin": "jìn", "defs": [{"meaning": "闭口。", "cites": [{"t": "口禁,口闭也。从口,禁声。", "b": "《说文》"}, {"t": "口噤闭而不言。", "b": "《楚辞·思古》"}, {"t": "翅垂口噤心甚劳。", "b": "杜甫《朱凤行》"}], "words": [{"w": "噤声", "t": "闭口不言;不出声或小声"}, {"w": "噤窄", "t": "闷在心里不说"}, {"w": "噤口卷舌", "t": "缄默不言。"}]}, {"meaning": "关闭;封闭。", "cites": [{"t": "有噤门而莫启。", "b": "潘岳《西征赋》"}], "words": [{"w": "噤门", "t": "关门。"}]}, {"meaning": "吃光喝完。", "cites": [{"t": "你过来,这酒我吃不了,咱两个噤了这素子酒吧。", "b": "《金瓶梅》"}]}]}]','jingmo-wenyan');
