('6091wx','蹀','1','dié','足','16','','[{"pinyin": "dié", "defs": [{"meaning": "(形声。从足,葉(yè)声。本义:踏,蹈)。"}, {"meaning": "同本义。", "cites": [{"t": "蹀,履也。", "b": "《广雅》"}, {"t": "罗袜蹑蹀而容兴。", "b": "张衡《南都赋》"}], "words": [{"w": "蹀马", "t": "使马踏脚起舞的演艺"}, {"w": "蹀座", "t": "双足交叠而坐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6092wx','踹','1','chuài','足','16','','[{"pinyin": "chuài", "defs": [{"meaning": "踩;踏;踩踏。", "cites": [{"t": "追者至踹足而怒。", "b": "《淮南子·人间》。注:“跃足也。今苏俗曰跳脚。”"}], "words": [{"w": "踹水", "t": "踏水"}, {"w": "踹浑水", "t": "浑水摸鱼"}, {"w": "踹踏", "t": "踩踏。"}]}, {"meaning": "跟踪寻找。", "cites": [{"t": "只青天白日,府里失盗,外贼从何得来?这还在左右前后踹。", "b": "《三国演义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6093wx','踵','1','zhǒng','足','16','','[{"pinyin": "zhǒng", "defs": [{"meaning": "(形声。从足,重声。本义:追逐)。"}, {"meaning": "同本义。", "cites": [{"t": "踵,追也。从足,重声。一曰往来貌。", "b": "《说文》"}, {"t": "踵二皇之遐武。", "b": "张衡《东京赋》"}, {"t": "踵见仲尼。", "b": "《庄子·德充符》"}, {"t": "有司靡踵。", "b": "《史记·太史公自叙》。索隐曰:“继也。”"}, {"t": "踵,迹也。", "b": "《后汉书·皇后纪》注"}, {"t": "骑者,军之司候也,所以踵败军,绝粮道,击便寇也。", "b": "《六韬·均兵》"}, {"t": "吴踵楚,而疆场无备,邑能无亡乎?", "b": "《左传·昭公二十四年》"}], "words": [{"w": "踵呼", "t": "追随呐喊。"}]}, {"meaning": "跟随。", "cites": [{"t": "步兵踵军后数十万人。", "b": "《汉书·武帝纪》"}], "words": [{"w": "踵至", "t": "接踵而来"}, {"w": "踵蹑", "t": "相继;接连。"}]}, {"meaning": "至;亲到。", "cites": [{"t": "远近闻知,俱踵其门观看。", "b": "《包公案》"}], "words": [{"w": "踵谢", "t": "亲自登门道谢"}, {"w": "踵门", "t": "登门;亲到其门。"}]}, {"meaning": "继承。", "cites": [{"t": "迎新在此岁,惟恐踵前迹。", "b": "柳宗元《田家》"}], "words": [{"w": "踵古", "t": "沿袭古代"}, {"w": "踵迹", "t": "犹继承"}, {"w": "踵美", "t": "谓继承前人的功业、美德"}, {"w": "踵袭", "t": "犹沿袭"}, {"w": "踵续", "t": "连续不断。"}]}, {"meaning": "脚后跟 (书面语词)。亦泛指脚。", "cites": [{"t": "踵,足后曰跟,又谓之踵。踵,钟也。钟,聚也,体之所钟聚也。", "b": "《释名》"}, {"t": "及前王之踵武。", "b": "《离骚》"}, {"t": "车轮曳踵。", "b": "《礼记·曲礼》"}, {"t": "去一以为踵围。", "b": "《考工记·輈人》。注:“后承轸者也。”"}, {"t": "踵狭而舌广。", "b": "《诗·苍伯》笺"}, {"t": "踵门而告文王。", "b": "《孟子》"}, {"t": "生人与死者并踵顶而卧,无可旋避,此所以染者众也。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "举踵", "t": "抬起脚后跟"}, {"w": "接踵", "t": "后面的人的脚尖触到前面人的脚后跟,形容人多接连不断"}, {"w": "踵踵", "t": "来往频繁的样子"}, {"w": "接踵", "t": "踵趾前后相接"}, {"w": "踵头肘见", "t": "鞋跟破裂,衣破裂而使手臂露了出来,形容贫穷者衣着破烂。"}]}]}]','jingmo-wenyan');
