('6094wx','踽','1','jǔ','足','16','','[{"pinyin": "jǔ", "defs": [{"meaning": "一个人独行的样子", "words": [{"w": "踽踽凉凉", "t": "孤独凄凉的样子"}]}, {"meaning": "慢步行走", "words": [{"w": "踽步", "t": "慢步的样子"}, {"w": "踽踽", "t": "小步慢行的样子"}]}, {"meaning": "通“伛”", "words": [{"w": "踽偻", "t": "伛偻"}]}]}]','jingmo-wenyan');
