('6095wx','蹉','1','cuō','足','16','','[{"pinyin": "cuō", "defs": [{"meaning": "(形声。从足,差声。本义:失足,跌跤)。"}, {"meaning": "同本义。", "cites": [{"t": "中坡蹉跎。", "b": "《楚辞·王褒·九怀株昭》。注:“失足。”"}], "words": [{"w": "蹉跌", "t": "跌倒;失误。"}]}, {"meaning": "时光白白过去。", "cites": [{"t": "蹉,蹉跎,失时也。", "b": "《说文新附》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6096wx','蹁','1','pián','足','16','','[{"pinyin": "pián", "defs": [{"meaning": "行走姿态不正貌。", "cites": [{"t": "蹁,足不正也,从足扁声。", "b": "《说文》"}]}, {"meaning": "大腿和小腿相连的关节的前部,通称膝盖。", "cites": [{"t": "膝头曰蹁;蹁,扁也,亦因形而名之也。", "b": "《释名》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6097wx','螨','1','mǎn','虫','16','','[{"pinyin": "mǎn", "defs": [{"meaning": "节肢动物的一类 ,头胸和腹通常是一整块,分节不明显,躯体前端有突出的口器。腹部有足四对。种类繁多,寄生在地下、地上、高山、水中及人或生物体上,传染多种疾病或危害农作物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6098wx','蟒','1','mǎng','虫','16','','[{"pinyin": "mǎng", "defs": [{"meaning": "(形声。从虫,莽声。本义:巨蛇)。"}, {"meaning": "蟒袍的简称。", "cites": [{"t": "上面正居中,悬着荣、宁二祖遗像,皆是披蟒腰玉。", "b": "《红楼梦》"}], "words": [{"w": "蟒绣", "t": "又叫蟒衫,蟒服,蟒衣,即蟒袍;明、清时皇子、亲王、一品至七品官所穿,衣上用金线绣蟒,形状像龙,四爪。蟒数自八至五,按等级区别。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6099wx','螈','1','yuán','虫','16','','[{"pinyin": "yuán", "defs": [{"meaning": "——“蝾螈”(róngyuán):两栖动物。状如蜥蜴,头扁,背黑色,腹红黄色,有黑斑,四肢短,尾侧扁,生活在水中。"}]}]','jingmo-wenyan');
