INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6101wx','螭','1','chī','虫','16','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从虫,离声。本义:传说中的一种没有角的龙) 同本义 。古代建筑或工艺品上常用它的形状作装饰。", "cites": [{"t": "项上带着赤金盘螭璎珞圈。", "b": "《红楼梦》"}], "words": [{"w": "螭头", "t": "古代钟鼎礼器、碑额、殿柱、殿阶及印章等上所刻的螭形花饰"}, {"w": "螭龙", "t": "传说中无角的龙"}, {"w": "螭蟠", "t": "如螭龙盘据"}, {"w": "螭虎", "t": "龙与虎。比喻勇猛的将士。"}]}]}]','jingmo-wenyan');
