INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6104wx','噱','1','jué xué','口','16','','[{"pinyin": "jué", "defs": [{"meaning": "大笑。", "cites": [{"t": "噱,大笑也。", "b": "《说文》"}, {"t": "谈关大噱。", "b": "《汉书·叙传》。注:“噱噱,笑声也。”"}], "words": [{"w": "噱谈", "t": "谈笑"}, {"w": "噱噱", "t": "嘻嘻。笑声"}, {"w": "可发一噱;谈笑大噱", "t": ""}]}, {"meaning": "口腔。", "cites": [{"t": "沈沈容容,遥噱虖紘中。", "b": "扬雄《羽猎赋》"}]}, {"meaning": "》。颜师古注:“口内之上下名为噱,言禽兽奔走倦极,皆遥张噱吐舌于紘罔之中也。”。"}]}, {"pinyin": "xué", "defs": [{"meaning": "", "words": [{"w": "发噱", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6105wx','噬','1','shì','口','16','','[{"pinyin": "shì", "defs": [{"meaning": "(形声。从口,筮(shì)声。本义:咬)。"}, {"meaning": "同本义。", "cites": [{"t": "噬,嗂也。喙也。", "b": "《说文》"}, {"t": "噬嗑食也。", "b": "《易·杂卦》"}, {"t": "国狗之瘈,无不噬也。", "b": "《左传·哀公十二年》"}, {"t": "欋杀援筮(噬)。", "b": "《考工记·梓人》"}, {"t": "虎大骇,远遁;以为且噬己也,甚恐。", "b": "唐·柳宗元《三戒》"}, {"t": "康乃甘心鹰犬,搏噬善类,其罪又浮于高拱。", "b": "《明史·海瑞传》"}], "words": [{"w": "噬指", "t": "畏惧地咬着手指头"}, {"w": "噬脐", "t": "自己用嘴咬肚脐,够不着。比喻后悔不及"}, {"w": "噬犬,噬狗", "t": "凶猛咬人的狗"}, {"w": "噬搏", "t": "咬啮搏击。"}]}, {"meaning": "吞。", "cites": [{"t": "竟横噬于虎口。", "b": "潘岳《西征赋》"}], "words": [{"w": "噬肥混赖", "t": "占了便宜还耍赖"}, {"w": "噬攫", "t": "侵吞掠夺。"}]}, {"meaning": "无义。", "cites": [{"t": "彼君子兮,噬肯适我?", "b": "《诗·唐风·有杕之杜》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6106wx','噫','1','ài yī yì','口','16','','[{"pinyin": "ài", "defs": [{"meaning": "饱食或积食后,胃里的气体从嘴里出来并发出声音", "words": [{"w": "噫气", "t": "气壅塞而得通；吐气"}]}, {"meaning": "呼气;吹气", "words": [{"w": "噫欠", "t": "噫气和打哈欠。泛指吐气"}]}]}, {"pinyin": "yī", "defs": [{"meaning": "(形声。从口,意声。(ài)本义:出气) 感叹声。"}, {"meaning": "表示悲痛或叹息。", "cites": [{"t": "噫!菊之爱,陶后鲜有闻。(噫,感叹词,相当于现代汉语中的“唉”。)", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "噫乎", "t": "表示慨叹"}, {"w": "噫嗟", "t": "表示慨叹"}, {"w": "噫呜", "t": "感慨悲叹貌"}, {"w": "噫嘘", "t": "叹息貌。"}]}, {"meaning": "表示惊异。", "cites": [{"t": "季恬逸道“噫!那里来的这位太太?”", "b": "《儒林外史》"}], "words": [{"w": "噫——怪!这是谁做的饭?;噫嘻吁", "t": "表示惊异或慨叹。"}]}]}, {"pinyin": "yì", "defs": [{"meaning": "表示转折。", "cites": [{"t": "噫,语辞。通作抑。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
