('6109wx','罹','1','lí','罒','16','','[{"pinyin": "lí", "defs": [{"meaning": "忧患;苦难。", "cites": [{"t": "我生之后,逢此百罹。", "b": "《诗·王风·兔·爰》"}]}, {"meaning": "受,遭逢,遭遇。", "cites": [{"t": "无罪者罹其毒。", "b": "清·方苞《狱中杂记》"}, {"t": "远罹构害。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "罹于锋镝", "t": "遭受战争的祸难"}, {"w": "罹兵", "t": "遭受战乱"}, {"w": "罹咎", "t": "遭受祸患。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6110wx','圜','1','huán yuán','囗','16','','[{"pinyin": "huán", "defs": [{"meaning": "(形声。从囗wéi,睘(qióng)声。本义:围绕)同本义", "cites": [{"t": "火似圜。", "b": "《周礼·考工记·画缋》"}, {"t": "动一亲戚,天下圜视而起。", "b": "《汉书·贾谊传》"}, {"t": "圜流九十里。", "b": "《列子·说符》"}, {"t": "欲内圜凿。", "b": "《史记·孟荀传》"}, {"t": "余圜视大骇。", "b": "唐·柳宗元《梓人传》"}], "words": [{"w": "圜山", "t": "环山。"}]}]}, {"pinyin": "yuán", "defs": [{"meaning": "同本义。", "cites": [{"t": "圜,天体也。", "b": "《说文》。按,浑圆为圜,平圆为圆。圆之规为圆。"}, {"t": "圜,天道也。", "b": "《吕氏春秋·圜道》注"}, {"t": "大圜在上。", "b": "《吕氏春秋·序意》。注:“天也。”"}, {"t": "乾为天,为圜。", "b": "《易·说卦》"}, {"t": "圜则九重,孰营度之?", "b": "《楚辞》"}], "words": [{"w": "圜邱", "t": "圜丘"}, {"w": "圜方", "t": "指天地"}, {"w": "圜宰;圜道", "t": "天道。"}]}, {"meaning": "牢狱。", "cites": [{"t": "司圜中士六人。", "b": "《周礼》"}], "words": [{"w": "圜土", "t": "牢狱"}, {"w": "圜扉", "t": "狱门"}, {"w": "圜墙", "t": "牢狱"}, {"w": "圜门", "t": "圆门;狱门。"}]}, {"meaning": "圆。", "cites": [{"t": "圜,一中同长也。", "b": "《墨子·经上》"}, {"t": "刓方以为圜兮。", "b": "《楚辞·九章·怀沙》"}, {"t": "石苍黑色,多平方,少圜(圜:同圆)。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "圜法", "t": "测量圆的方法"}, {"w": "圜率", "t": "圆周率。"}]}, {"meaning": "钱币。", "cites": [{"t": "太公为周立九府圜法:黄金方寸;而重一斤。", "b": "《汉书·食货志下》"}], "words": [{"w": "圜好", "t": "王莽时所造货币上的圆孔"}, {"w": "圜货", "t": "钱币"}, {"w": "圜钱", "t": "古代钱币。"}]}, {"meaning": "圆的,圆形的。", "cites": [{"t": "冬日至于地上之圜丘奏之。", "b": "《周礼·大司乐》"}, {"t": "圜者中规,方者中矩。", "b": "《周礼·考工记》"}, {"t": "何方圜之能周兮,夫孰异道而相安?", "b": "《楚辞》"}], "words": [{"w": "圜陈", "t": "圆形兵阵"}, {"w": "圜冠", "t": "儒者戴的圆形帽子"}, {"w": "圜舍", "t": "圆形小屋。"}]}]}]','jingmo-wenyan');
