('6113wx','镗','1','tāng táng','钅','16','','[{"pinyin": "tāng", "defs": [{"meaning": "钟鼓的声音或敲锣的声音。", "cites": [{"t": "镗,钟鼓之声。从金,堂声。", "b": "《说文》"}, {"t": "击鼓其镗。", "b": "《诗·邶风·击鼓》"}], "words": [{"w": "镗鞳", "t": "钟鼓声"}, {"w": "镗镗", "t": "钟鼓声。"}]}]}, {"pinyin": "táng", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6114wx','镘','1','màn','钅','16','','[{"pinyin": "màn", "defs": [{"meaning": "镘刀 一种扁平的或稍有曲线形状的带柄工具。即抹墙用的抹子。", "cites": [{"t": "镘,铁杇也。从金,曼声或从木。", "b": "《说文》。按,铁者曰镘,木者曰槾,字亦作墁。"}, {"t": "镘谓之杇。", "b": "《尔雅·释宫》"}, {"t": "如何圬者持镘过,已向比邻问子孙。", "b": "宋·晁冲之《伤心》"}]}, {"meaning": "铜钱;钱钞。", "cites": [{"t": "这弟子敲镘儿哩。", "b": "关汉卿《救风尘》"}]}, {"meaning": "涂饰。", "cites": [{"t": "其来仆仆,镘我新屋。", "b": "王安石《新田诗》"}]}]}]','jingmo-wenyan');
