INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6116wx','镛','1','yōng','钅','16','','[{"pinyin": "yōng", "defs": [{"meaning": "古乐器,奏乐时表示节拍的大钟。", "cites": [{"t": "镛,大钟谓之镛。", "b": "《说文》"}, {"t": "笙镛以间。", "b": "《书·益稷》"}, {"t": "虡业维枞,贲鼓维镛。", "b": "《诗·大雅·灵台》"}, {"t": "金次福、鲍廷玺两人领了一班司球的…司镛的、司箫的、司编钟的、司编罄的和六六三十六个佾舞的孩子,进来见了众人。", "b": "《儒林外史》"}], "words": [{"w": "镛石", "t": "大钟和磬两种乐器的并称"}, {"w": "镛鼓", "t": "钟鼓两种乐器的并称。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6117wx','镝','1','dī dí','钅','16','','[{"pinyin": "dī", "defs": [{"meaning": "稀土族的三价金属元素,它形成的化合物属于已知的具有最大磁性的物质之列。其氧化物呈白色,而盐呈微黄色 ——元素符号Dy。"}]}, {"pinyin": "dí", "defs": [{"meaning": "(形声。从金,啇(dí)声。本义:箭的尖头)。"}, {"meaning": "同本义。", "cites": [{"t": "收天下之兵,聚之咸阳,销锋镝。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "锋镝;箭镝;镝矢", "t": "内部有三个小空洞的箭头。射出时会发出响声,因此也叫鸣镝"}, {"w": "镝箭", "t": "即镝矢。"}]}, {"meaning": "箭。", "cites": [{"t": "揽弓捷鸣镝,长驱上南山。", "b": "曹植《名都篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6118wx','镞','1','zú','钅','16','','[{"pinyin": "zú", "defs": [{"meaning": "(形声。从金,族声。本义:箭头) 同本义。", "cites": [{"t": "秦无亡矢遗镞之费,而天下诸侯已困矣。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "利镞", "t": "锋利的箭头。"}]}, {"meaning": "形容箭的轻捷,应声而至。", "cites": [{"t": "所为贵镞矢者,为其应声而至。", "b": "《吕氏春秋》"}]}]}]','jingmo-wenyan');
