('6122wx','憩','1','qì','心','16','','[{"pinyin": "qì", "defs": [{"meaning": "休息。", "cites": [{"t": "憩,息也。", "b": "《尔雅》"}, {"t": "召伯所憩。", "b": "《诗·召南·甘棠》"}, {"t": "策扶老以流憩。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "憩书斋。", "b": "清·袁枚《祭妹文》"}, {"t": "又如:小憩;同作同憩;憩止(歇息,休息);憩休(歇息);憩泊(栖息);憩歇(休息,歇息)", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6123wx','穑','1','sè','禾','16','','[{"pinyin": "sè", "defs": [{"meaning": "(形声。从禾,啬(sè)声。声符有表意作用,见前。本义:收获谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "穑,谷可收曰穑。", "b": "《说文》。按,穑即啬之后出字。"}, {"t": "土爰稼穑。", "b": "《书·洪范》。王肃注:“种之曰稼,敛之曰穑。”"}, {"t": "不稼不穑,胡取禾三百廛兮?", "b": "《诗经·魏风·伐檀》"}], "words": [{"w": "穑民", "t": "农民"}, {"w": "穑地", "t": "农田"}, {"w": "穑臣", "t": "古代称管理农事的大臣"}, {"w": "穑督", "t": "谓督导农事"}, {"w": "穑养", "t": "谓退隐务农。"}]}, {"meaning": "节俭;爱惜。", "cites": [{"t": "贬食省用,务穑劝分。", "b": "《左传·僖公二十一年》。杜预注:“穑,俭也。”"}, {"t": "大国省穑而用之。", "b": "《左传·昭公元年》。注:“爱也。”"}, {"t": "不为大国侮小国,不为众庶侮鳏寡,不为暴势夺穑人黍稷狗彘。", "b": "《墨子·兼爱中》"}]}, {"meaning": "互相钩连。", "cites": [{"t": "树以荆棘,上相穑著者,所以为固也。", "b": "《管子·度地》"}]}, {"meaning": "收获的谷物。", "cites": [{"t": "曾孙之穑,以为酒食。", "b": "《诗·小雅·信南山》"}]}, {"meaning": "谷类植物的穗。", "cites": [{"t": "所艺禾穑特大。", "b": "《徐霞客游记·粤西游日记》"}, {"t": "凡苗吐穑之后,暮夜鬼火游烧,此六灾也。", "b": "《天工开物》"}]}]}]','jingmo-wenyan');
