INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6128wx','篙','1','gāo','竹','16','','[{"pinyin": "gāo", "defs": [{"meaning": "(形声。从竹,高声。从“竹”,表示与竹有关。本义:撑船的竿) 同本义。", "cites": [{"t": "尝发所在竹篙,有一官长连根取之,仍当足,乃超两阶用之。", "b": "《世说新语·政事》"}, {"t": "自忆东吴榜舟日,蓼花沟水半篙强。", "b": "李郢《山行》"}, {"t": "大家跳下船,双喜拔前篙,阿发拔后篙。", "b": "《社戏》"}], "words": [{"w": "篙眼", "t": "篙痕。篙在岸上留下的孔穴"}, {"w": "篙楫", "t": "篙桨等行船的工具"}, {"w": "杉篙", "t": "杉木撑船篙"}, {"w": "篙橹", "t": "撑船摇船的工具"}, {"w": "篙痕", "t": "篙撑船时留下的痕迹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6129wx','盥','1','guàn','皿','16','','[{"pinyin": "guàn", "defs": [{"meaning": "(会意。小篆字形,从臼(jiù),舂米用的器具,从水,从皿(表示与器皿有关)。合起来表示:以手承水冲洗而下流于盘(皿)。本义:洗手)。"}, {"meaning": "同本义。", "cites": [{"t": "盥,澡手也。从臼水临皿。", "b": "《说水》"}, {"t": "奉匜沃盥。", "b": "《左传·僖公二十三年》"}, {"t": "宣子盥而抚之。", "b": "《左传·僖公十九年》"}, {"t": "盥而不荐。", "b": "《易·上观》"}, {"t": "咸盥漱。", "b": "《礼记·内则》"}, {"t": "沐者,去首垢也。洗去足垢,盥去手垢,浴去身垢。", "b": "《论衡·讥日》"}], "words": [{"w": "盥手", "t": "洗手"}, {"w": "盥沐", "t": "洗脸"}, {"w": "盥帨", "t": "洗手后用的擦手布。"}]}, {"meaning": "洗涤。", "cites": [{"t": "述尽心视湯药,饮食心尝而后进,衣不解带不盥栉者累旬。", "b": "《南史·谢裕传》附谢述"}], "words": [{"w": "盥栉", "t": "洗脸梳头;洗理"}, {"w": "盥浣", "t": "洗涤"}, {"w": "盥溉", "t": "洗涤"}, {"w": "盥涤", "t": "洗涤"}, {"w": "盥濯", "t": "洗涤。"}]}, {"meaning": "除;净 );盥涤(清除)。"}, {"meaning": "古代洗手的器皿。", "cites": [{"t": "承姑奉盥,训子停机。", "b": "北周·庾信《周安昌公夫人郑氏墓志铭》"}], "words": [{"w": "盥盆", "t": "盥洗之盆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6130wx','劓','1','yì','刂','16','','[{"pinyin": "yì", "defs": [{"meaning": "(会意。从刀,从鼻。刀割鼻子。本义:劓刑。割鼻的刑罪,古代五刑之一)。"}, {"meaning": "同本义。", "cites": [{"t": "劓罚之属千。", "b": "《书·吕刑》"}], "words": [{"w": "劓鼻", "t": "割掉鼻子的酷刑"}, {"w": "劓刖", "t": "割鼻断足;危殆不安的样子。"}]}, {"meaning": "割除。", "cites": [{"t": "我乃劓殄灭之。", "b": "《书·盘庚中》"}], "words": [{"w": "劓割", "t": "劓剥。残害"}, {"w": "劓除", "t": "削灭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6131wx','翱','1','áo','羽','16','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从羽,皋声。本义:翅膀上下振动而回旋地飞)。"}, {"meaning": "同本义。", "cites": [{"t": "翱,翱翔也。", "b": "《说文》"}, {"t": "思从祥风翱。", "b": "《汉书·王褒传》"}, {"t": "翱翔四海之外。", "b": "《淮南子·览冥》。注:“翼一上一下曰翱。”"}, {"t": "鸟之高飞,翼上下曰翱,直剌不动曰翔。", "b": "《淮南子·俶真》注"}, {"t": "齐子翱翔。", "b": "《诗·齐风·载驱》"}, {"t": "羔裘翱翔。", "b": "《诗·桧风·羔裘》"}, {"t": "逸翮后尘,翱翥先路。", "b": "鲍照《舞鹤赋》"}], "words": [{"w": "翱翥", "t": "飞翔的样子。"}]}, {"meaning": "喻人自由自在地遨游,游乐。", "cites": [{"t": "将翱将翔。", "b": "《诗·郑风·女曰鸡鸣》"}]}]}]','jingmo-wenyan');
