('6133wx','魈','1','xiāo','鬼','16','','[{"pinyin": "xiāo", "defs": [{"meaning": "山魈。山中精怪。", "cites": [{"t": "山精形如小儿,独足向后,夜喜犯人,名曰魈。", "b": "晋·葛洪《抱朴子·登涉》"}], "words": [{"w": "魈魅", "t": "即魈鬼。鬼怪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6134wx','徼','1','jiāo jiǎo jiào yāo','彳','16','','[{"pinyin": "jiāo", "defs": [{"meaning": "窃取,抄袭。", "cites": [{"t": "徼,抄也。", "b": "《广韵》"}, {"t": "恶徼以为知者。", "b": "《论语》。孔注:“抄也。”"}]}]}, {"pinyin": "jiǎo", "defs": [{"meaning": "贪求不止。", "cites": [{"t": "寡君愿徼福于周公鲁公。", "b": "《左传·文公二年》"}, {"t": "患其徼一时之权。", "b": "《史记·匈奴列传》"}], "words": [{"w": "徼伺", "t": "窥视希冀"}, {"w": "徼冀", "t": "希求"}, {"w": "徼觊", "t": "非分希冀"}, {"w": "徼进", "t": "犹侥进。非分求进。"}]}]}, {"pinyin": "jiào", "defs": [{"meaning": "巡查。", "cites": [{"t": "几为巡徼所陵迫死。", "b": "文天祥《指南录后序》"}], "words": [{"w": "徼循", "t": "巡查"}, {"w": "徼道", "t": "巡逻警戒的道路"}, {"w": "徼候", "t": "巡察守候"}, {"w": "徼捕", "t": "巡捕。"}]}, {"meaning": "激发,激励。", "cites": [{"t": "今王诚发士卒佐之以徼其志,重宝以说其心,卑辞以尊其礼,其伐齐必也。", "b": "《史记》"}]}, {"meaning": "边界,边境。", "cites": [{"t": "复寻金沙江,极于牦徼外。", "b": "钱谦益《徐霞客传》"}], "words": [{"w": "徼人", "t": "边民"}, {"w": "缴外", "t": "边界外;国外"}, {"w": "徼亭", "t": "边境哨所"}, {"w": "徼塞", "t": "边塞"}, {"w": "徼障", "t": "边境;边塞。"}]}]}, {"pinyin": "yāo", "defs": [{"meaning": ""}, {"meaning": "招致。", "cites": [{"t": "弗使血食,吾欲与之徼天之衷。", "b": "《国语》"}], "words": [{"w": "徼怨", "t": "招怨"}, {"w": "徼祸", "t": "招致祸害"}, {"w": "徼乱", "t": "谓招致祸乱。"}]}, {"meaning": "求取。", "cites": [{"t": "乃义士且以徼其名,贪夫且以求其赏尔。", "b": "汉·王符《潜夫论》"}], "words": [{"w": "徼天", "t": "求天赐福。犹言天佑"}, {"w": "徼名", "t": "谋求名声"}, {"w": "徼功", "t": "犹求功"}, {"w": "徼求;徼利", "t": "谋利,求利。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6135wx','歙','1','shè xī','欠','16','','[{"pinyin": "shè", "defs": [{"meaning": "县名 。中国安徽省南部的县。徽墨、翕砚为其特产。"}]}, {"pinyin": "xī", "defs": [{"meaning": "吸气或通过呼吸吸入。", "cites": [{"t": "歙,缩鼻也。从欠,翕声。", "b": "《说文》。字亦作噏。"}, {"t": "将欲噏之,必固张之。", "b": "《老子河上本》"}, {"t": "崩腾歙众流,泱漭环中国。", "b": "《三宝太监西洋记通俗演义》"}, {"t": "歙蠡吞沱。", "b": "《石帆铭》"}]}, {"meaning": "收缩,敛息。", "cites": [{"t": "将欲歙之,必固张之。", "b": "《老子》"}, {"t": "开阖张歙。", "b": "《淮南子·本经》"}, {"t": "开闭张歙。", "b": "《淮南子·精神》"}, {"t": "为之以歙,而应之以张。", "b": "《淮南子》"}], "words": [{"w": "歙肩", "t": "耸肩。形容身子微缩,作恐惧、谄媚状。"}]}, {"meaning": "和谐,融洽。", "cites": [{"t": "郡中歙然。", "b": "《汉书·韩延寿传》"}], "words": [{"w": "歙然", "t": "和洽的样子;安定的样子"}, {"w": "歙歙", "t": "无所偏执的样子;投合的样子,朋比为奸的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6136wx','膳','1','shàn','月','16','','[{"pinyin": "shàn", "defs": [{"meaning": "(形声。从肉,善声。本义:饭食) 同本义,一般指肉食。", "cites": [{"t": "膳,具食也。", "b": "《说文》"}, {"t": "膳,肉也。", "b": "《广雅》"}, {"t": "掌王之食饮膳羞。", "b": "《周礼·膳夫》。注:“膳,牲肉也。”"}, {"t": "徧尝膳。", "b": "《仪礼·士相见礼》"}, {"t": "膳于君。", "b": "《礼记·玉藻》。注:“膳,美食也。”"}, {"t": "具太牢以为膳。", "b": "《庄子》"}], "words": [{"w": "早膳;供给膳宿;膳部员外郎", "t": "唐代礼部专管膳食的长官之一"}, {"w": "膳服", "t": "饮食和服用"}, {"w": "膳羞", "t": "美味的食品"}, {"w": "膳饮", "t": "饮食。"}]}, {"meaning": "备置食物。", "cites": [{"t": "其令太官省膳省宰。", "b": "《汉书·宣帝纪》"}], "words": [{"w": "膳府", "t": "宫中贮藏食物的仓库。"}]}, {"meaning": "进献食物。", "cites": [{"t": "宰夫膳稻于粱西。", "b": "《仪礼·公食大夫礼》"}]}, {"meaning": "进食,吃饭。", "cites": [{"t": "公膳,日双鸡。", "b": "《左传》"}], "words": [{"w": "膳堂", "t": "饭堂。"}]}, {"meaning": "烹调,煎和。", "cites": [{"t": "春行羔豚膳膏香。", "b": "《周礼·天官·庖人》"}]}]}]','jingmo-wenyan');
