INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6139wx','鲮','1','líng','鱼','16','','[{"pinyin": "líng", "defs": [{"meaning": "古代传说中的怪鱼。也作“陵鱼”。", "cites": [{"t": "鲮鱼何所?", "b": "《楚辞·天问》"}]}, {"meaning": "鲮鳢,又名穿山甲。", "cites": [{"t": "其形肖鳢,穴陵而居,故曰鲮鳢,而俗称为穿山甲。", "b": "《本草纲目》"}]}, {"meaning": "鲮鱼 ,也叫土鲮鱼,属鲤科鱼类,是我国华南淡水主要养殖鱼种之一,性怕冷。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6140wx','鲱','1','fēi','鱼','16','','[{"pinyin": "fēi", "defs": [{"meaning": "鱼名。也称鰊。一种食用鱼(大西洋鲱Clupea harengus),体长约0.3米,特别盛产于北大西洋温水和较冷水域,成大群游近岸边产卵。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6141wx','鲲','1','kūn','鱼','16','','[{"pinyin": "kūn", "defs": [{"meaning": "(形声。从鱼,昆声。本义:鱼苗的总称)。"}, {"meaning": "同本义 如:鲲鲕(鱼苗;小鱼)。"}, {"meaning": "传说中的一种大鱼。", "cites": [{"t": "北冥有鱼,其名为鲲。", "b": "《庄子·逍遥游》"}], "words": [{"w": "鲲鹏", "t": "古代传说中的大鱼和大鸟"}, {"w": "鲲鹏展翅,九万里,翻动扶摇羊角《庄子》里说,有一种大鱼叫鲲,变成一种大鸟叫鹏,能飞得又高又远九万里九万里的高空,形容飞得极高翻动,卷起扶摇羊角,迅猛回旋的旋风羊角,形状像羊角一样的旋风;鲲化", "t": "鲲鱼化为鹏鸟;比喻人高升"}, {"w": "鲲龙", "t": "传说中的大鱼和蛟龙。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6142wx','鲳','1','chāng','鱼','16','','[{"pinyin": "chāng", "defs": [{"meaning": "鱼名 。形如鳊鱼,体侧扁而高,略呈斜方形,大者长二尺许,体色黄白,背面苍色,头与鳍皆淡黑而多细黑点,腹面色淡,头眼皆小。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6143wx','鲴','1','gù','鱼','16','','[{"pinyin": "gù", "defs": [{"meaning": "黄鲴 ,一种鲤科鱼(Xenocypris argentea),体长大而侧扁,大约30厘米,银白带黄色,口小,生活在河流、湖泊中,吃藻类和其他水生植物。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6144wx','鲵','1','ní','鱼','16','','[{"pinyin": "ní", "defs": [{"meaning": "(形声。从鱼,兒(ní)声。本义:两栖类动物,俗称“娃娃鱼”)。"}, {"meaning": "同本义 。外表类似蜥蜴类,但无鳞片,身体为软和湿润的皮肤所覆盖,生活在潮湿阴暗的地方,以小型动物。", "cites": [{"t": "鲵,剌鱼也。", "b": "《说文》"}, {"t": "鲵大者谓之鰕。", "b": "《尔雅·释鱼》。注:似鲇,四脚,前似弥猴,后似狗。声如小儿啼。大者长七八尺。”"}], "words": [{"w": "鲵鲐", "t": "鲵齿和鲐背"}, {"w": "鲵鱼", "t": "娃娃鱼。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6145wx','鲷','1','diāo','鱼','16','','[{"pinyin": "diāo", "defs": [{"meaning": "鲷科鱼的总称 。身体侧扁,呈长椭圆形,头大口小。生活在海洋中。种类繁多。是我国主要的食用经济鱼类", "words": [{"w": "天笠鲷", "t": ""}, {"w": "红笠鲷", "t": ""}, {"w": "石鲷", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6146wx','鲻','1','zī','鱼','16','','[{"pinyin": "zī", "defs": [{"meaning": "鲻鱼 。属于鲻科(Mugilidae)的一种鱼,产于许多海和河流中,主要生活在岸边,身长可达30至60厘米,具有食用价值。"}]}]','jingmo-wenyan');
