INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6148wx','獭','1','tǎ','犭','16','','[{"pinyin": "tǎ", "defs": [{"meaning": "几种水栖的食鱼鼬科动物的任一种,主要属于几乎全世界都有分布的水獭属。", "cites": [{"t": "獭,如小狗,水居食鱼。从犬,赖声。", "b": "《说文》"}, {"t": "獭祭鱼。", "b": "《吕氏春秋·孟春》"}, {"t": "故为渊殴鱼者,獭也。", "b": "《孟子》"}], "words": [{"w": "獭皮;海獭;獭祭", "t": ""}]}]}]','jingmo-wenyan');
