('6154wx','瘰','1','luǒ','疒','16','','[{"pinyin": "luǒ", "defs": [{"meaning": "中医指结核菌侵入淋巴结，发生核块的病，多在颈部。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6155wx','廪','1','lǐn','广','16','','[{"pinyin": "lǐn", "defs": [{"meaning": "(会意兼象形。从人回,象屋形,中有户牖。又作“廪”。“廪”是俗字。本义:米仓)。"}, {"meaning": "同本义。", "cites": [{"t": "亦有高廪。", "b": "《诗·周颂·丰年》"}, {"t": "盛米曰廩。", "b": "《周礼·廪人》注"}, {"t": "余刀布,有囷廪。", "b": "《荀子·荣辱》。注:“圆曰囷,方曰廪。”"}, {"t": "御廪者,粢盛委之所藏也。", "b": "《公羊传·桓公十四年》"}, {"t": "御廪,夫人八妾所舂米,藏以奉宗庙也。", "b": "《汉书·五行志》"}, {"t": "谷藏曰仓,米藏曰廪。", "b": "《荀子·富国》注"}, {"t": "父母使舜完廪。", "b": "《孟子·万章上》"}, {"t": "管子曰“仓廪实而知礼节。”", "b": "贾谊《论积贮疏》"}], "words": [{"w": "廪囷", "t": "米仓。方的称廪,圆的称囷"}, {"w": "廪粟", "t": "米仓中的粮食"}, {"w": "廪庚", "t": "米仓。"}]}, {"meaning": "泛指粮食仓库。", "cites": [{"t": "昭侯令人复廪。", "b": "《韩非子·内储说下》"}, {"t": "广蓄积,以实仓廪。", "b": "晁错《论贵粟疏》"}]}, {"meaning": "又如廪人(古代管理粮仓的官吏)。"}, {"meaning": "米粟类;粮食。", "cites": [{"t": "坐縻廪粟而不知耻。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "廪禄", "t": "官府供给的俸米和俸钱"}, {"w": "廪库", "t": "粮仓;仓库"}, {"w": "廪庾", "t": "粮仓"}, {"w": "廪饷", "t": "粮饷。"}]}, {"meaning": "俸禄。", "cites": [{"t": "廪食以数百人。", "b": "《韩非子·内诸说上》"}], "words": [{"w": "廪给", "t": "官吏的俸给"}, {"w": "廪秩;廪俸;廪赐", "t": "俸禄和赏赐。"}]}, {"meaning": "“廪生”的简称。", "cites": [{"t": "他家大老那宗笔下,怎得会补起廪来。", "b": "《儒林外史》"}], "words": [{"w": "禀贡", "t": "以禀生的资格做了贡生。"}]}, {"meaning": "林甸。树林与郊野。", "cites": [{"t": "桓公明日弋在廪。", "b": "《管子·戒》"}]}, {"meaning": "收藏;储积。", "cites": [{"t": "廪于肠胃。", "b": "《素问·皮部论》"}, {"t": "群公廪。", "b": "《公羊传·文公十三年》。注:“廪者,连新于陈上,财气半相连耳。”"}], "words": [{"w": "廪收", "t": "收购入仓"}, {"w": "廪藏", "t": "廪蓄。"}]}, {"meaning": "公家发给粮食。", "cites": [{"t": "廪,赐谷也。", "b": "《说文》"}, {"t": "既禀称事。", "b": "《礼记·中庸》"}], "words": [{"w": "廪食", "t": "公家供给粮食"}, {"w": "廪稍", "t": "旧时指公家按时供给的粮食"}, {"w": "廪饩", "t": "旧指由公家供给的粮食之类的生活物资"}, {"w": "廪粟", "t": "同“廪食”。"}]}, {"meaning": "", "cites": [{"t": "可以富安天下,而直为此廪廪也。", "b": "贾谊《论积贮疏》"}], "words": [{"w": "廪廪", "t": "危殆,阽危;惊慌;危惧。"}]}, {"meaning": "寒冷。", "cites": [{"t": "窃独悲此廪秋。", "b": "宋玉《九辩》"}], "words": [{"w": "廪秋", "t": "寒秋"}, {"w": "廪泉", "t": "寒泉。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6156wx','瘿','1','yǐng','疒','16','','[{"pinyin": "yǐng", "defs": [{"meaning": "虫瘿。树木外部隆起如瘤者。", "cites": [{"t": "木有瘿,石有晕,犀有通,以取妍于人,皆物之病也。", "b": "宋·苏轼《答李端叔书》"}], "words": [{"w": "瘿肿", "t": "指虫瘿"}, {"w": "瘿瘤", "t": "指虫瘿"}, {"w": "瘿尊", "t": "瘿杯"}, {"w": "瘿瓢", "t": "瘿木制的瓢"}, {"w": "瘿杯", "t": "瘿木制的杯子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6157wx','瘵','1','zhai','疒','16','','[{"pinyin": "zhai", "defs": [{"meaning": "病。多指痨病。", "cites": [{"t": "念其服劳之久,悯其撄瘵之深。", "b": "宋·王安石《乞退表》"}], "words": [{"w": "瘵鬼", "t": "因患痨病而死者"}, {"w": "瘵疾", "t": "疫病。亦指痨病。"}]}, {"meaning": "疾苦;困顿。", "cites": [{"t": "邦靡有定,士民其瘵。", "b": "《诗·大雅·瞻仰》。又如:瘵瘼(凋敝,衰败)"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6158wx','瘴','1','zhàng','疒','16','','[{"pinyin": "zhàng", "defs": [{"meaning": "(形声。从疒(chuáng),章声。“疒”与疾病有关。本义:瘴气,旧指南方山林间湿热蒸郁致人疾病的气)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6159wx','癃','1','lóng','疒','16','','[{"pinyin": "lóng", "defs": [{"meaning": "足不能行。", "cites": [{"t": "久癃之夫,将息未定,而骤陵百级之梯,其不踬者几希。", "b": "梁启超《关税权问题》"}]}, {"meaning": "小便不利。", "cites": [{"t": "膀胱不利为癃。", "b": "《素问·宣明五气》"}], "words": [{"w": "癃疝", "t": "小便不利,阴囊肿大的病"}, {"w": "癃闭便毒", "t": "中医指小便不通利之病;便毒即性病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6160wx','瘳','1','chōu','疒','16','','[{"pinyin": "chōu", "defs": [{"meaning": "(形声。从“疒”,表示与疾病有关。本义:病愈)。"}, {"meaning": "同本义。", "cites": [{"t": "其伤于缚者,即幸留,病数月乃瘳。", "b": "方苞《狱中杂记》"}], "words": [{"w": "瘳恙", "t": "病愈"}, {"w": "瘳健", "t": "病愈,恢复健康。"}]}, {"meaning": "减损,损失。", "cites": [{"t": "君不度而贺大国之袭,于己也何瘳?", "b": "《国语·晋语二》"}]}]}]','jingmo-wenyan');
