INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6162wx','麇','1','jūn qún','鹿','16','','[{"pinyin": "jūn", "defs": [{"meaning": "古地名。"}, {"meaning": "春秋时麇国之地,在今湖北省郧县西。", "cites": [{"t": "楚子代麇。", "b": "《左传》"}]}, {"meaning": "春秋时楚邑,在今湖南省岳阳东南。", "cites": [{"t": "楚王使由于城麇。", "b": "《左传》"}]}]}, {"pinyin": "qún", "defs": [{"meaning": "成群。", "cites": [{"t": "求诸侯而麇至。", "b": "《左传·昭公五年》。杜预注:“麇,群也。”"}], "words": [{"w": "麇聚", "t": "麇集"}, {"w": "麇至", "t": "成群而来"}, {"w": "麇居", "t": "群居。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6163wx','麈','1','zhǔ','鹿','16','','[{"pinyin": "zhǔ", "defs": [{"meaning": "驼麈 。即“麋鹿”。俗称“四不像”。", "cites": [{"t": "翦旄麈。", "b": "《文选·左思·蜀都赋》"}]}, {"meaning": "麈尾(用麈的尾毛做的拂尘)的省称。", "cites": [{"t": "抱琴不暇抚,挥麈无由停。", "b": "欧阳修《和圣俞聚蚊》"}], "words": [{"w": "挥麈", "t": "挥动麈尾,以掸灰尘"}, {"w": "麈尾", "t": "用麈的尾毛制成的拂麈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6164wx','嬴','1','yíng','女','16','','[{"pinyin": "yíng", "defs": [{"meaning": "姓", "cites": [{"t": "与嬴而不助六国。", "b": "宋·苏洵《六国论》"}, {"t": "嬴,少昊氏之姓。", "b": "《说文》。段玉裁注:“按秦、徐、江、黄、郯、莒皆嬴姓也。”"}], "words": [{"w": "嬴氏", "t": "嬴秦。称秦国或秦王朝"}, {"w": "嬴女", "t": "指传说中的秦穆公之女弄玉。秦,嬴姓,故称秦女为“嬴女”"}, {"w": "嬴项", "t": "嬴秦和项楚的并称"}, {"w": "嬴台", "t": "古代传说中肖史、弄玉所居之凤台。"}]}, {"meaning": "古邑名 。在今山东省莱芜县西北。", "cites": [{"t": "孟子自齐葬于鲁,反于齐,止于嬴。", "b": "《孟子》"}]}, {"meaning": "增益;增加。", "cites": [{"t": "一胜人必嬴。", "b": "《逸周书》"}, {"t": "嬴则兼欺舅与母。", "b": "《史记·苏秦列传》"}, {"t": "是维嬴土之国。", "b": "《山海经·大荒东经》"}]}, {"meaning": "环绕。", "cites": [{"t": "俶真者,穷逐终始之化,嬴垀有无之精。", "b": "《淮南子》"}]}, {"meaning": "余;满。", "cites": [{"t": "与世偃仰,缓急嬴绌。", "b": "《荀子》"}, {"t": "嬴则敖上。", "b": "《荀子·强国》"}, {"t": "曾无我嬴!", "b": "《史记·赵世家》"}], "words": [{"w": "嬴绌", "t": "有余和不足"}, {"w": "嬴储", "t": "剩余,积存。"}]}, {"meaning": "土地肥美。", "cites": [{"t": "有柔仆民,是维嬴土之国。", "b": "《山海经》"}], "words": [{"w": "嬴土", "t": "肥沃的土地。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6165wx','壅','1','yōng','土','16','','[{"pinyin": "yōng", "defs": [{"meaning": "(形声。从土,雍声。本义:塞。阻塞;阻挡)。"}, {"meaning": "同本义。", "cites": [{"t": "壅,障也。", "b": "《广雅》"}, {"t": "雍,隔也。", "b": ""}, {"t": "业贯万世而不壅。", "b": "《淮南子·主术》"}, {"t": "川壅而溃。", "b": "《左传·宣公十二年》"}, {"t": "则民病血壅肿,目不明。", "b": "汉·董仲舒《春秋繁露·五行顺逆》"}], "words": [{"w": "壅防", "t": "堵塞"}, {"w": "壅阻", "t": "堵塞"}, {"w": "壅淤", "t": "淤塞;不流通"}, {"w": "壅闭", "t": "堵塞"}, {"w": "壅肿", "t": "因血管堵塞而引起的肿痛。"}]}, {"meaning": "障蔽;遮盖。", "cites": [{"t": "宣王因以晏首壅塞之。", "b": "《战国策·齐策》。注:“壅,蔽也。”"}, {"t": "其君处壅翳蔽塞,窕邃弗章,倚以陵墓,带以曲房。", "b": "三国魏·阮籍《东平赋》"}], "words": [{"w": "壅劫", "t": "被蒙蔽挟制"}, {"w": "壅君", "t": "受蒙蔽的君王;昏君"}, {"w": "壅围", "t": "遮蔽"}, {"w": "壅翳", "t": "隐蔽;障隔。"}]}, {"meaning": "堆积。", "cites": [{"t": "于是决去壅土,疏导江涛。", "b": "唐·柳宗元《兴州江运记》"}], "words": [{"w": "壅积", "t": "堆积。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6166wx','羲','1','xī','羊','16','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从兮,义(yì)声。本义:气)。"}, {"meaning": "同本义。", "cites": [{"t": "羲,气也。", "b": "《说文》"}]}, {"meaning": "假借用于专名。传说中古代帝王伏羲的简称。", "cites": [{"t": "伏羲氏之有天下也。", "b": "《书·序》"}, {"t": "基隆于羲农,规广于黄唐。", "b": "《文选·班固·答宾戏》"}], "words": [{"w": "羲文", "t": "指伏羲和文王"}, {"w": "羲轩", "t": "指伏羲和轩辕"}, {"w": "羲唐", "t": "指伏羲和尧帝"}, {"w": "羲皇", "t": "指伏羲氏"}, {"w": "羲炎", "t": "指伏羲和炎帝"}, {"w": "羲黄", "t": "指伏羲和黄帝。"}]}, {"meaning": "传说尧时掌天文的官吏羲氏(羲仲和羲叔)的简称。", "cites": [{"t": "羲和盖天地始生主日月者也。", "b": "《山海经·大荒南经》注"}, {"t": "乃命羲和,钦若昊天,…", "b": "《书·尧典》。陆德明释文:“羲、和,马云:‘羲氏掌天官,和氏掌地官,四子掌四时。’”"}]}, {"meaning": "原指神话中太阳御者羲和,后用以指代太阳。", "cites": [{"t": "朱羲将由白。", "b": "郭璞《游仙诗》"}], "words": [{"w": "羲庭", "t": "羲阳。太阳的别称"}, {"w": "羲娥", "t": "日御羲和与月神嫦娥的并称。借指日月;泛指岁月;亦指日夜。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6167wx','糗','1','qiǔ','米','16','','[{"pinyin": "qiǔ", "defs": [{"meaning": "(形声。从米,臭声。本义:炒熟的米麦等谷物)。"}, {"meaning": "同本义。", "cites": [{"t": "糗,熬米麦也。", "b": "《说文》"}, {"t": "糗饵粉飺。", "b": "《周礼·籩人》"}, {"t": "糗一筐。", "b": "《国语·楚语》"}, {"t": "舜之饭糗茹草也。", "b": "《孟子·尽心下》"}], "words": [{"w": "糗芳", "t": "芳香的干粮"}, {"w": "糗糒", "t": "干粮"}, {"w": "糗饵", "t": "将米麦炒熟,捣粉制成的食品。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6168wx','瞥','1','piē','目','16','','[{"pinyin": "piē", "defs": [{"meaning": "(形声。从目,敝声。本义:眼光掠过)。"}, {"meaning": "同本义。", "cites": [{"t": "瞥,过目也,一曰财见也。", "b": "《说文》"}, {"t": "譬之犹一覕也。", "b": "《庄子·徐无鬼》"}, {"t": "游尘外而瞥天兮。", "b": "张衡《思玄赋》"}, {"t": "一鸡瞥来。", "b": "《聊斋志异·促织》"}], "words": [{"w": "他刚要插嘴,妈妈瞥了他一眼;瞥观", "t": "暂观;偶尔阅览。"}]}, {"meaning": "暂现,很快地出现一下。", "cites": [{"t": "瞥若电灭。", "b": "张衡《舞赋》"}], "words": [{"w": "瞥目", "t": "极言时间之短"}, {"w": "瞥映", "t": "暂照"}, {"w": "瞥眼间", "t": "一转眼间。极言时间短暂"}, {"w": "故宫一瞥", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6169wx','甑','1','zèng','瓦','16','','[{"pinyin": "zèng", "defs": [{"meaning": "(形声。从瓦,曾声。从瓦,表示是陶制品。本义:古代炊具,底部有许多透蒸汽的小孔,放在鬲上蒸煮 )。"}, {"meaning": "同本义。", "cites": [{"t": "甑,甗也。", "b": "《说文》"}, {"t": "甑,自关而东谓之甗,或谓之甑。", "b": "《方言》五"}, {"t": "许子以釜甄爨,以铁耕乎?", "b": "《孟子·滕文公上》"}, {"t": "荷甑堕地,不顾而去。", "b": "《后汉书·孟敏传》"}, {"t": "朝甑米空烹芋粥,夜缸油尽点松明。", "b": "宋·陆游《杂题六首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6170wx','燎','1','liáo liǎo liào','火','16','','[{"pinyin": "liáo", "defs": [{"meaning": "放在地上的火炬,大火把。", "cites": [{"t": "夜未央,庭燎之光。", "b": "《诗·小雅·庭燎》。疏:“庭燎者,树之于庭,燎之为明,是烛之大者。“"}, {"t": "火在地曰燎,执之曰烛。", "b": "《仪礼·士丧礼》注"}], "words": [{"w": "燎火", "t": "火炬"}, {"w": "燎炬", "t": "火把"}, {"w": "燎烛", "t": "烛炬。"}]}]}, {"pinyin": "liǎo", "defs": [{"meaning": "(形声。从火,尞(liáo)声。本义:放火焚烧草木)。"}, {"meaning": "同本义。", "cites": [{"t": "燎,放火也。", "b": "《说文》"}, {"t": "燎,烧田也。", "b": "《一切经音义》引《说文》"}, {"t": "燎,烧也。", "b": "《广雅》"}, {"t": "若火之燎于原。", "b": "《书·洛诰》"}, {"t": "燎京薪。", "b": "张衡《西京赋》"}, {"t": "燎之方扬,宁或灭之?", "b": "《诗·小雅·正月》"}]}, {"meaning": "烤炙,烘干,烘烤。", "cites": [{"t": "疑以火自燎。", "b": "《汉书·王莽传》"}, {"t": "光武对灶燎衣。", "b": "《后汉书·冯异传》"}]}, {"meaning": "被火焰烧焦。", "cites": [{"t": "发一灯可燎阿房。", "b": "唐·杜牧《阿房宫赋》"}], "words": [{"w": "燎眉", "t": "火烧眉毛。比喻情况急迫"}, {"w": "燎发;燎毛", "t": ""}]}, {"meaning": "用同“憭”。明白;明了。", "cites": [{"t": "佼人燎兮。", "b": "《诗·陈风·月出》"}], "words": [{"w": "燎悟", "t": "明了,领悟"}, {"w": "燎彻", "t": "了解透彻"}, {"w": "燎燎", "t": "明显"}, {"w": "燎亮", "t": "明白。"}]}]}, {"pinyin": "liào", "defs": [{"meaning": "照明。", "cites": [{"t": "桓公虽不言,若暗夜而烛燎也。", "b": "《吕氏春秋·精谕》"}]}, {"meaning": "夜猎。", "cites": [{"t": "昔有司原氏者,燎猎中野。", "b": "《潜夫论》"}], "words": [{"w": "燎猎", "t": ""}]}, {"meaning": "假借为“尞”。烧柴祭天。", "cites": [{"t": "及百祀之新燎。", "b": "《吕氏春秋·季冬》。注:“燎者,积聚柴薪,置璧与牲于上而燎之。升其烟气。”"}, {"t": "民所燎矣。", "b": "《诗·大雅·旱麓》。释文:“柴祭天也。”"}, {"t": "休之以燎。", "b": "《汉书·司马相如传》。注:“祭天也。”"}, {"t": "燎祭天,报之义也。", "b": "《白虎通·封禅》"}], "words": [{"w": "燎柴", "t": "烧柴祭天"}, {"w": "燎祭", "t": "古代祭祀仪式之一。把玉帛、牺牲放在柴堆上,焚烧祭天"}, {"w": "燎燔", "t": "烧柴而祭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6171wx','燠','1','yù','火','16','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从火,奥(yuè)声。本义:温暖)。"}, {"meaning": "同本义。", "cites": [{"t": "燠,热在中也。", "b": "《说文》"}, {"t": "燠, 煖也。", "b": "《尔雅》"}, {"t": "曰燠。", "b": "《书·洪范》。传:“火气也。”"}, {"t": "安且燠兮。", "b": "《诗·唐风·无衣》"}, {"t": "问衣燠寒。", "b": "《礼记·内则》"}, {"t": "鸟何燠之。", "b": "《楚辞·天问》"}, {"t": "八,庶征:曰雨,曰暘,曰燠,曰寒,曰风,曰时。", "b": "《书·洪范》"}], "words": [{"w": "燠日", "t": "温暖的太阳"}, {"w": "燠沐", "t": "温暖湿润。"}]}, {"meaning": "热。", "cites": [{"t": "若乃炎风之燠,夏日之长,寻头扑面,入袖穿裳。", "b": "《三宝太监西洋记通俗演义》"}], "words": [{"w": "燠疾", "t": "热症"}, {"w": "燠暑", "t": "炎热"}, {"w": "燠蒸", "t": "闷热如蒸"}, {"w": "燠热", "t": "炎热;闷热。"}]}, {"meaning": "使温暖;使热。", "cites": [{"t": "吾言如治疾…凉疾至,燠之。", "b": "清·龚自珍《凉燠》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6172wx','燔','1','fán','火','16','','[{"pinyin": "fán", "defs": [{"meaning": "(形声。从火,番声。本义:焚烧)。"}, {"meaning": "同本义。", "cites": [{"t": "燔,爇也。从火,番声。与焚略同。", "b": "《说文》"}, {"t": "藉芿燔林。", "b": "《列子·黄帝》"}, {"t": "燔之于四通之衢。", "b": "《汉书·东方朔传》。注:“焚烧也。”"}, {"t": "体若燔炭。", "b": "《素问·生气通天论》"}, {"t": "抱木而燔死。", "b": "《庄子·盗跖》"}, {"t": "燔其茏城。", "b": "《史记·平津侯生父传》"}, {"t": "人民饥饿,相燔烧以求食。", "b": "《汉书·宣帝纪》"}, {"t": "燔诗书", "b": "《汉书·儒林传》"}, {"t": "不若燔土。", "b": "宋·沈括《梦溪笔谈·活板》"}], "words": [{"w": "燔燎", "t": "火把"}, {"w": "燔石", "t": "焙烧矿石"}, {"w": "燔刑", "t": "烧人至死的残酷刑罚"}, {"w": "燔燃", "t": "燃烧"}, {"w": "燔销", "t": "烧毁 火烧整只的牲畜。"}]}, {"meaning": "火烧整只的牲畜。", "cites": [{"t": "有免斯首,炮之燔之。", "b": "《诗·小雅·瓠叶》"}, {"t": "为俎孔硕,或燔或炙。", "b": "《诗·小雅·楚茨》"}], "words": [{"w": "燔柴", "t": "将玉帛、牺牲等置于积柴上而焚之以祭天"}, {"w": "燔祀", "t": "焚柴祭祀。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6173wx','燧','1','suì','火','16','','[{"pinyin": "suì", "defs": [{"meaning": "(会意。从火,遂声。本义:古代取火器)。"}, {"meaning": "同本义。", "cites": [{"t": "燧,塞上亭守烽火者。", "b": "《说文》"}, {"t": "燧,以取火于日。", "b": "《玉篇》"}, {"t": "有圣人作,钻燧取火,以化腥臊,而民悦之,使王天下,号之曰燧人氏。", "b": "《韩非子·五蠹》"}, {"t": "钻燧取火。", "b": "《论语·阳货》"}, {"t": "命夙驾载燧。", "b": "《左传·文公十年》"}, {"t": "钻燧取火,以化腥臊。", "b": "《人类的出现》"}, {"t": "幽王为熢燧。", "b": "《史记·周本纪》。正义:“炬火也。”"}], "words": [{"w": "燧(铜)镜(古代用以向日取火)", "t": ""}]}, {"meaning": "火炬之类。", "cites": [{"t": "前驱举燧,后乘抗旌。", "b": "曹植《应诏诗》"}]}, {"meaning": "烽火台。", "cites": [{"t": "南朝自武昌至京口,列置烽燧,此山当是其一也。", "b": "宋·陆游《过小孤山大孤山》"}]}, {"meaning": "古代边防报警的信号。白天放烟告警叫“烽”,夜间举火告警叫“燧”。", "cites": [{"t": "幽王欲悦之,数为举燧火。", "b": "《后汉书·孽嬖传》"}, {"t": "有寇则燃火,举之以相告,曰烽。又多积薪,寇至即燔之望其烟,曰燧。昼则燔燧,夜则举烽。", "b": "《后汉书·光武纪》注"}]}, {"meaning": "守望烽燧的基本组织 。燧是最基本的组织,专司本烽燧的守望职责,设燧长,其秩位相当于亭长。"}, {"meaning": "燃。", "cites": [{"t": "燧松明而识浅,散星宿于亭皋。", "b": "宋·苏轼《中山松胶赋一首》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6174wx','濑','1','lài','氵','16','','[{"pinyin": "lài", "defs": [{"meaning": "从沙石上流过的水。", "cites": [{"t": "濑,水流沙上也。", "b": "《说文》"}, {"t": "石濑兮浅浅。", "b": "《楚辞·九歌·湘君》"}, {"t": "北揭石濑。", "b": "《汉书·司马相如传下》"}, {"t": "溪谷之深,流者安洋;浅多沙石,激扬为濑。", "b": "《论衡》"}]}, {"meaning": "流得很急的水;急流。", "cites": [{"t": "抑淢怒濑,以扬激波。", "b": "《淮南子·本经》"}, {"t": "混涛并濑。", "b": "《文选·左思·吴都赋》"}, {"t": "石濑汤汤。", "b": "《魏都赋》"}, {"t": "涖涖下濑。", "b": "《汉书·司马相如传上》"}, {"t": "何必湘渊与涛濑。", "b": "《汉书·扬雄传上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6175wx','濉','1','suī','氵','16','','[{"pinyin": "suī", "defs": [{"meaning": "水名。"}, {"meaning": "在安徽省北部。东南流入洪泽湖。", "cites": [{"t": "濉、漳、江、汉,楚之望也。", "b": "《韩诗外传》"}]}, {"meaning": "在福建省西部。", "cites": [{"t": "濉江,在[建宁]县治南,本名绥江,以绥成县名。", "b": "《读史方舆纪要·福建四》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6176wx','潞','1','lù','氵','16','','[{"pinyin": "lù", "defs": [{"meaning": "古水名。即今山西浊漳河。", "cites": [{"t": "其浸汾、潞。", "b": "《周礼》"}]}, {"meaning": "假借为“羸”(léi)。瘦弱,疲病。", "cites": [{"t": "士民罢潞,国家空虚。", "b": "《吕氏春秋·不屈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6177wx','澧','1','lǐ','氵','16','','[{"pinyin": "lǐ", "defs": [{"meaning": "澧水  。发源于湖南省西北与湖北省鹤峰县交界处,向东南流经桑植,再向南向东经大庸、慈利、石门、澧县、津市市,再向南流入七里湖、洞庭湖。", "cites": [{"t": "又东至于澧。", "b": "《书·禹贡》。朱曰:“出今湖南澧州永定县西历山,至安乡县会赤沙河入洞庭湖。史记正作醴。”"}]}, {"meaning": "甘美。", "cites": [{"t": "甘露降,澧泉涌。", "b": "《列子·汤问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6178wx','澹','1','dàn tán','氵','16','','[{"pinyin": "dàn", "defs": [{"meaning": "(形声。从水,詹声。本义:水波摇动的样子)。"}, {"meaning": "同本义。", "cites": [{"t": "澹,水摇也。", "b": "《说文》"}, {"t": "徒靡澹淡。", "b": "宋玉《高唐赋》。注:“水波文也。”"}, {"t": "澹淡浮。", "b": "班固《西都赋》。注:“隨风之貌也。”"}, {"t": "澹兮其若海。", "b": "《老子》"}, {"t": "烟波澹荡摇空碧,楼殿参差倚夕阳。", "b": "白居易《西湖晚归回望孤山寺赠诸客》"}], "words": [{"w": "澹澹", "t": "水波摇动的样子"}, {"w": "澹荡", "t": "摇动的样子。"}]}, {"meaning": "淡薄,浅淡", "cites": [{"t": "清澹退静。", "b": "《晋书·华表传》"}, {"t": "塞城朝烟澹。", "b": "唐·杜甫《两当县吴十侍御江上宅》"}]}, {"meaning": "又如;澹月(淡薄的月色);澹云(淡云)。"}, {"meaning": "恬淡。", "cites": [{"t": "澹然离言说,悟悦心自足。", "b": "柳宗元《晨诣超师院读禅经》"}], "words": [{"w": "澹虑", "t": "恬淡的心情"}, {"w": "澹宁", "t": "澹薄。恬淡寡欲"}, {"w": "澹默", "t": "恬淡静默。"}]}, {"meaning": "恬静;安定。", "cites": [{"t": "澹乎若深渊之静。", "b": "汉·贾谊《鹏乌赋》"}]}]}, {"pinyin": "tán", "defs": [{"meaning": "姓。又“澹台”（Tántái）(复姓)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6179wx','澥','1','xiè','氵','16','','[{"pinyin": "xiè", "defs": [{"meaning": "靠陆地的海湾 。渤海湾是大海的一个港汊,故古名勃澥。", "cites": [{"t": "澥,勃澥,海之别名。", "b": "《说文》"}]}, {"meaning": "海。", "cites": [{"t": "湖澥天教十载闲,《玉经》功就胜居澥。", "b": "《送玉海宗师还山》"}], "words": [{"w": "澥宇澥", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6180wx','澶','1','chán','氵','16','','[{"pinyin": "chán", "defs": [{"meaning": "古地名。在今河南濮阳县西南。"}, {"meaning": "北宋和辽订立和约的事件。真宗景德元年（1004），辽入侵宋，宋军在澶州辽宁订立和约。规定宋每年给辽岁币银10万两，绢20万匹。因澶州又称澶渊郡而得名。"}, {"meaning": "水流平静。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6181wx','濂','1','lián','氵','16','','[{"pinyin": "lián", "defs": [{"meaning": "濂水,今名濂江 ,又名安远江,在江西省南部。"}, {"meaning": "姓(濂洛:宋代理学代表人物)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6182wx','褰','1','qiān','衣','16','','[{"pinyin": "qiān", "defs": [{"meaning": "(形声。从衣,寒省声。本义:套裤) 同本义。", "cites": [{"t": "褰,绔也。", "b": "《说文》"}, {"t": "征褰与襦。", "b": "《左传·昭公二十五年》"}, {"t": "振养矜寡,衣之褰襦。", "b": "王安石《潭州新学并序》"}]}, {"meaning": "撩起。", "cites": [{"t": "褰,褰衣。", "b": "《广韵》"}, {"t": "暑无褰裳。", "b": "《礼记·曲礼上》"}, {"t": "与其有事,则褰裳濡足,冠挂不顾。", "b": "《后汉书·崔骃传》"}, {"t": "子惠思我,褰裳涉溱。", "b": "《诗·郑风·褰裳》"}, {"t": "揽辔褰帷。", "b": "清·周容《芋老人传》"}], "words": [{"w": "褰裳避之", "t": "提衣躲避,比喻不愿接近某些人或事,远避之"}, {"w": "褰衣", "t": "提起衣服,揭起衣裳"}, {"w": "褰裳", "t": "提起衣裳。"}]}, {"meaning": "散开。", "cites": [{"t": "自非烟褰雨霁,不辨此远山矣。", "b": "《水经注》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6183wx','寰','1','huán','宀','16','','[{"pinyin": "huán", "defs": [{"meaning": "(形声。从宀mián,睘(qióng)声。本义:王畿,古代帝王京城周围千里以内的地方)。"}, {"meaning": "同本义。", "cites": [{"t": "寰,王者封畿内县也。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6184wx','窸','1','xī','穴','16','','[{"pinyin": "xī", "defs": [{"meaning": "〔～窣〕象声词，形容摩擦等轻微细小的声音。亦作“窸窸窣窣”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6185wx','褶','1','xí zhě','衤','16','','[{"pinyin": "xí", "defs": [{"meaning": "裤褶服中的上衣 。始为左衽骑服,后亦改为右衽,用作常服、朝服", "words": [{"w": "褶衣", "t": "裤褶服中的上衣"}, {"w": "褶裤", "t": "骑服"}]}, {"meaning": "古代的一种便服", "words": [{"w": "褶子", "t": "古代的一种便服。后常专指传统戏装中的一种便服,也作穿蟒袍的衬衣"}]}, {"meaning": "旧时女子的膝袜", "words": [{"w": "褶裤", "t": "旧时女子的膝袜。也称膝裤"}]}]}, {"pinyin": "zhě", "defs": [{"meaning": "(形声。从衣,习(xí)声。本义:衣服折叠而形成的印痕)", "cites": [{"t": "休将包袱做枕头,…我只怕干时节熨不开褶皱。", "b": "《西厢记》"}, {"t": "卷底衣褶中。", "b": "清·魏学洢《核舟记》"}], "words": [{"w": "百褶裙", "t": ""}, {"w": "褶纹", "t": "纹痕"}, {"w": "褶祬", "t": "衣服上的折皱"}, {"w": "褶褶", "t": "皱叠的样子"}, {"w": "褶绉", "t": "衣服上的皱纹"}, {"w": "褶叠", "t": "折叠"}]}, {"meaning": "脸上的皱纹", "words": [{"w": "褶皱", "t": ""}]}]}]','jingmo-wenyan');
