INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6187wx','嬖','1','bì','女','16','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从女,辟声。本义:宠爱) 同本义。", "cites": [{"t": "便嬖,爱也。", "b": "《说文》"}, {"t": "毋以嬖御人疾庄后。", "b": "《礼记·缁衣》"}, {"t": "嬖人之子也。", "b": "《左传·隐公三年》。注:“亲幸也。”"}, {"t": "而嬖是女也。", "b": "《国语·郑语》。注:“以邪僻取爱曰嬖。”"}, {"t": "叔孙还,纳其女于灵公,嬖,生景公。", "b": "《左传·襄公二十五年》"}, {"t": "宋公子地嬖蘧富猎。", "b": "《左传·定公十年》"}]}, {"meaning": "受宠爱的人。", "cites": [{"t": "齐侯好内,多内宠,内嬖如夫人者六人。", "b": "《左传·僖公十七年》"}]}]}]','jingmo-wenyan');
