INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6189wx','隰','1','xí','阝','16','','[{"pinyin": "xí", "defs": [{"meaning": "(形声。阜:土山,与土地有关。本义:低湿之地)。"}, {"meaning": "{同本义}。", "cites": [{"t": "隰,阪下湿也。", "b": "《说文》"}, {"t": "下湿曰隰。", "b": "《尔雅·释地》。李注:“谓土地窊下常阻洳,名为隰也。又,可食者曰原,陂者曰阪,下者曰隰。”"}, {"t": "上平曰原,下平曰隰。", "b": "《公羊传·昭公元年》"}, {"t": "原隰底绩。", "b": "《书·禹贡》"}, {"t": "辨其山林川泽丘陵坟衍原隰之名物。", "b": "《周礼·大司徒》"}, {"t": "牧隰皋。", "b": "《左传·襄公二十五年》。注:“隰皋,水厓下湿。”"}, {"t": "平原之隰。", "b": "《管子·形势》。注:“下泽也。”"}, {"t": "丘隰水潦。", "b": "《淮南子·时则》"}, {"t": "山有榛,隰有苓。", "b": "《诗·邶风·简兮》"}, {"t": "南望原隰。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "隰草", "t": "低湿地方所生长的草"}, {"w": "隰皋", "t": "水边低洼,生长牧草的地方。"}]}, {"meaning": "新开垦的田地。", "cites": [{"t": "千耦其耘,徂隰徂畛。", "b": "《诗·周颂·载芟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6190wx','嬗','1','shàn','女','16','','[{"pinyin": "shàn", "defs": [{"meaning": "自然的演变。", "cites": [{"t": "形气转续,变化而嬗。", "b": "贾谊《鹏鸟赋》"}], "words": [{"w": "嬗迭", "t": "演变。"}]}, {"meaning": "禅位。", "cites": [{"t": "尧嬗以天下。", "b": "《汉书·律历志下》"}]}, {"meaning": "更替。", "cites": [{"t": "五年之间,号令三嬗。", "b": "《史记·秦楚之际月表》"}], "words": [{"w": "嬗代", "t": "嬗更,嬗替,嬗易。更替。"}]}, {"meaning": "传与,传递", "cites": [{"t": "变化而嬗。", "b": "《汉书·贾谊传》。注:“相传与也。”"}, {"t": "以不同形相嬗也。", "b": "《淮南子·精神》。高诱注:“嬗,传也。”"}, {"t": "尧嬗以天下。", "b": "《汉书·律历志下》"}, {"t": "留其人于京师,而无尺土以嬗其子孙。", "b": "龚自珍《答人问关内侯》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6191wx','颡','1','sǎng','页','16','','[{"pinyin": "sǎng", "defs": [{"meaning": "额头。", "cites": [{"t": "颡,额也。从页,桑声。", "b": "《说文》"}, {"t": "中夏谓之额,东齐谓之颡。", "b": "《方計》"}, {"t": "可使过颡。", "b": "《孟子》"}, {"t": "河目龙颡。", "b": "《孔子家语·困誓》"}, {"t": "靥辅在颊则好,在颡则丑。", "b": "刘安《淮南子》"}], "words": [{"w": "颡骨", "t": "额骨"}, {"w": "颡泚", "t": "额上汗淋淋。借指心中惶惶不安"}, {"w": "颡汗", "t": "额头上冒汗。"}]}, {"meaning": "头。", "cites": [{"t": "修鳞脱远枝,巨颡拆老拳。", "b": "唐·杜甫《义鹘》"}]}, {"meaning": "“稽颡”的省称,即叩头、磕头。", "cites": [{"t": "拜稽颡。", "b": "《仪礼·士丧礼》。注:“头触地。”"}, {"t": "再拜颡。", "b": "《左传·昭公二十五年》"}]}]}]','jingmo-wenyan');
