INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6198wx','璪','1','zǎo','王','17','','[{"pinyin": "zǎo", "defs": [{"meaning": "古代皇冠前下垂的装饰,用彩色丝线串玉而成,状如水藻。", "cites": [{"t": "璪,玉饰如水藻之文。从玉,璪声。", "b": "《说文》"}, {"t": "璪火粉米。", "b": "《虞书》。按,此假借为藻。"}, {"t": "祭之日,王被璪以象天,戴冠,璪十有二旒,则天数也。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6199wx','螫','1','shì','虫','17','','[{"pinyin": "shì", "defs": [{"meaning": "毒虫或毒蛇咬刺。", "cites": [{"t": "自后人有为蜂螫者,挪芋梗傅之则愈。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "螫手", "t": "咬手"}, {"w": "螫刺", "t": "扎,刺"}, {"w": "螫毒", "t": "蜂、蝎等以尾针螫刺行毒。比喻毒害"}, {"w": "螫噬", "t": "毒虫刺人和野兽咬人"}, {"w": "螫虫", "t": "尾部有毒针可刺人的虫。"}]}, {"meaning": "因恼怒而加害。", "cites": [{"t": "有刑法而死,无螫毒,故奸人服。", "b": "《韩非子·用人》"}], "words": [{"w": "螫搏", "t": "螫刺和攫取。毒害人民"}, {"w": "螫蝎", "t": "用毒刺刺人的蝎子。比喻可怖的事或狠毒的人。"}]}]}]','jingmo-wenyan');
