INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6203wx','罄','1','qìng','缶','17','','[{"pinyin": "qìng", "defs": [{"meaning": "(形声。本义:器中空)。"}, {"meaning": "同本义。", "cites": [{"t": "罄,器中空也。", "b": "《说文》"}, {"t": "缾之罄矣。", "b": "《诗·小雅·蓼莪》"}, {"t": "罄无不宜。", "b": "《诗·小雅·天保》"}], "words": [{"w": "罄身人", "t": "身无分文的人"}, {"w": "罄然", "t": "空无一物的样子"}, {"w": "罄身", "t": "空着身子。"}]}, {"meaning": "严整。", "cites": [{"t": "师旷罄然。", "b": "《周书·太子晋》"}], "words": [{"w": "罄然", "t": "严肃整饬的样子。"}]}, {"meaning": "用尽;消耗殆尽。", "cites": [{"t": "罄,尽也。", "b": "《尔雅》"}, {"t": "罄南山之竹,书罪未穷。", "b": "《旧唐书·李密传》"}, {"t": "贫亦罄衣装。", "b": "清·方苞《狱中杂记》"}]}, {"meaning": "乐器。", "cites": [{"t": "室如县罄,野无青草。", "b": "《左传·僖公二十六年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6204wx','擢','1','zhuō','扌','17','','[{"pinyin": "zhuō", "defs": [{"meaning": "(形声。从手,翟(dí)声。本义:抽引,拉拔)。"}, {"meaning": "同本义。", "cites": [{"t": "擢,引也。", "b": "《说文》"}, {"t": "擢,拔也。", "b": "《方言二》"}, {"t": "拔根曰擢。", "b": "《小尔雅》"}, {"t": "擢贾之发,以赎贾之罪,尚未足。", "b": "《史记·范雎列传》"}, {"t": "夫十围之木,始生如蘖,足可搔而绝,手可擢而拔。", "b": "枚乘《上书谏吴王》"}, {"t": "卓齿之用齐也,擢湣王之筋,悬之庙梁。", "b": "《韩非子·奸劫弑臣》"}, {"t": "蔚鹅城之南麓,擢仙李之芳根。", "b": "宋·苏轼《惠州李氏潜珍阁铭》"}, {"t": "车上御驰马,蓬中擢舟船。", "b": "汉·王符《潜夫论》"}, {"t": "风起,风起,擢入白擢花里。", "b": "明·刘基《如梦令·题画》"}], "words": [{"w": "擢筋剥肤", "t": "擢筋割骨。犹言抽筋剥皮。比喻剥削深重残酷"}, {"w": "擢发", "t": "拔下头发。"}]}, {"meaning": "选拔。", "cites": [{"t": "擢,今俗凡迁官曰擢。擢,犹升也,进也。", "b": "《正字通》"}], "words": [{"w": "擢佐", "t": "选拔辅佐人才"}, {"w": "擢奇", "t": "选拔奇才"}, {"w": "擢举", "t": "选拔荐举。"}]}, {"meaning": "拔官,提升官职。", "cites": [{"t": "程乌、李育以有才干,皆擢用之。", "b": "《后汉书·公孙述传》"}, {"t": "皇上超擢四品卿衔军机章京。", "b": "梁启超《谭嗣同传》"}, {"t": "时瑞已擢嘉兴通判。", "b": "《明史》"}]}, {"meaning": "又。", "cites": [{"t": "擢瑞户薄主事。", "b": ""}], "words": [{"w": "擢引", "t": "提拔"}, {"w": "擢任", "t": "提拔任用"}, {"w": "擢拔", "t": "提拔"}, {"w": "擢拜", "t": "提拔授官"}, {"w": "擢进", "t": "提拔进用"}, {"w": "擢叙,擢序", "t": "提拔叙用"}, {"w": "擢授", "t": "提升"}, {"w": "擢登", "t": "犹擢升。"}]}, {"meaning": "耸出。", "cites": [{"t": "擢干方数尺,幽姿已苍然。", "b": "韦应物《郡斋移杉》诗"}], "words": [{"w": "擢本", "t": "高耸的样子"}, {"w": "擢拔", "t": "犹耸出,耸拔"}, {"w": "擢削", "t": "耸立突出的样子"}, {"w": "擢干", "t": "谓树干挺生、耸拔。"}]}]}]','jingmo-wenyan');
