('6206wx','鞡','1','la','革','17','','[{"pinyin": "la", "defs": [{"meaning": "——“靰鞡”(wùla):同“乌拉”(wūla)。中国东北地区冬天穿的一种鞋,用皮革制成,里面垫乌拉草。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6207wx','鞬','1','jiān','革','17','','[{"pinyin": "jiān", "defs": [{"meaning": "马上盛弓箭的器具。", "cites": [{"t": "鞬,所以戢弓矢者。", "b": "《说文》"}, {"t": "所以藏弓谓之鞬。", "b": "《方言九》"}, {"t": "鞬,箭服也。", "b": "《后汉书·西羌传》注"}], "words": [{"w": "鞬韔", "t": "弓箭袋"}, {"w": "鞬服", "t": "鞬橐。盛弓箭的器具"}, {"w": "鞬弭", "t": "代指弓箭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6208wx','薷','1','rú','艹','17','','[{"pinyin": "rú", "defs": [{"meaning": "木耳。", "cites": [{"t": "薷,木耳。", "b": "《集韵》"}]}, {"meaning": "用于“香薷”:草名,又名香葇。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6209wx','薰','1','xūn','艹','17','','[{"pinyin": "xūn", "defs": [{"meaning": "(形声。从艸,熏声。本义:蕙草)。"}, {"meaning": "香草名。即“蕙草”,又名“零陵香”。", "cites": [{"t": "薰,香草也。", "b": "《说文》"}, {"t": "薰草,蕙草也。", "b": "《广雅》。按,即今零陵香。"}, {"t": "叶曰薰,根曰薰是也。", "b": "《离骚》王逸注"}, {"t": "一薰一蕕。", "b": "《左传·僖公四年》"}, {"t": "浮山有草焉,名曰薰。麻叶而方茎,赤华而黑实,臭如蘼芜,佩之可以已疠。", "b": "《山海经·西山经》"}, {"t": "腐鼠在坛,烧薰于宫。", "b": "《淮南子·说林》"}], "words": [{"w": "薰莸", "t": "薰和莸。一种香草和一种臭草;比喻美丑、善恶或君子、小人等"}, {"w": "薰燧", "t": "焚烧香草以取香"}, {"w": "薰草", "t": "即蕙草。俗名佩兰。"}]}, {"meaning": "香气、香味。", "cites": [{"t": "陌上草薰", "b": "江淹《别赋》。注:“香气也。”"}], "words": [{"w": "薰薰", "t": "酒器弥漫的样子。"}]}, {"meaning": "以气味或烟气烤制物品", "cites": [{"t": "薰以香,自烧,此用其根也。", "b": "《汉书·龚胜传》"}], "words": [{"w": "薰鱼;薰鸡;薰服", "t": "香熏的衣服。指妓女或妓乐。古代妓女用香薰其服,故名"}, {"w": "薰沐", "t": "薰香和沐浴。表示虔敬。"}]}, {"meaning": "烧灼,熏炙。", "cites": [{"t": "燎薰炉兮炳明烛。", "b": "谢惠连《雪赋》。注:“火烟上出也。”"}, {"t": "薰胥以刑。", "b": "《汉书·叙传》。注:“谓相薰蒸。”"}], "words": [{"w": "薰戒", "t": "焚香斋戒"}, {"w": "薰灼", "t": "用烟、火熏烤"}, {"w": "薰心", "t": "心受熏灼。常形容愁苦。"}]}, {"meaning": "和暖,温和。", "cites": [{"t": "蕙风如薰。", "b": "左思《魏都赋》。注:“风至之貌也。”"}], "words": [{"w": "薰风", "t": "柔和的风。指夏季的南风"}, {"w": "薰薰", "t": "和煦的样子。"}]}, {"meaning": "温和的样子。", "cites": [{"t": "薰然慈仁。", "b": "《庄子·天下》。释义:“温和貌。”"}], "words": [{"w": "薰然", "t": "温和的样子;和顺的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6210wx','藓','1','xiǎn','艹','17','','[{"pinyin": "xiǎn", "defs": [{"meaning": "(形声。从艸,鲜声。本义:苔藓) 同本义。植物学名词。隐花植物的一类,茎叶很小,没有根,生在阴湿的地方", "words": [{"w": "藓苔", "t": "青苔"}, {"w": "藓书", "t": "丛生在岩石上的藓苔,文彩斑驳,有如文字,称为藓书"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6211wx','藁','1','gǎo','艹','17','','[{"pinyin": "gǎo", "defs": [{"meaning": "禾秆。", "cites": [{"t": "儿馁嗔郎罢,妻寒望稾砧。", "b": "宋·唐庚《自笑》"}], "words": [{"w": "藁砧", "t": "稻草与砧板,古代行刑时的用具"}, {"w": "藁人", "t": "用草扎成的人形"}, {"w": "藁秸", "t": "稻、麦等的秆子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6212wx','檄','1','xí','木','17','','[{"pinyin": "xí", "defs": [{"meaning": "(形声。本义:檄文)。"}, {"meaning": "同本义。", "cites": [{"t": "太祖得书,便命移檄。", "b": "《英烈传》"}, {"t": "制府檄下。", "b": "宋·文天祥《指南录后序》"}, {"t": "所有文檄,幕下儒生设意修词(“文檄”即檄文。古代用以征召、晓喻或声讨的文书)。", "b": "清·黄宗羲《柳敬亭传》"}, {"t": "奉檄守御。", "b": "清·方苞《左忠毅公逸事》"}], "words": [{"w": "传檄", "t": "传布檄文"}, {"w": "羽檄", "t": "上插鸟羽的古代征兵军书。"}]}, {"meaning": "泛指信函。", "cites": [{"t": "使君子年善?来檄可求。", "b": "王安石《寄丁中允》"}]}, {"meaning": "用檄文晓谕或声讨。", "cites": [{"t": "按察司行文檄了知县去。", "b": "《儒林外史》"}, {"t": "檄其人士,于政治宗教,皆欲有所更革,顾终不成。", "b": "鲁迅《坟·摩罗诗力说》"}], "words": [{"w": "檄调", "t": "行檄调动"}, {"w": "檄委", "t": "用檄文晓谕、托咐。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6213wx','檩','1','lǐn','木','17','','[{"pinyin": "lǐn", "defs": [{"meaning": "架在房梁上托住椽子的横木。也称“桁条”、“檩条”、“檩子”。", "cites": [{"t": "檩,屋上横木。", "b": "《集韵》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6214wx','懋','1','mào','心','17','','[{"pinyin": "mào", "defs": [{"meaning": "(形声。从心,楙(mào)声。本义:勉励,使人努力上进)。"}, {"meaning": "同本义。", "cites": [{"t": "懋,勉也。", "b": "《说文》"}, {"t": "懋建大命。", "b": "《书·盘庚》"}, {"t": "懋穑劝分,省用足财。", "b": "《国语·晋语四》"}], "words": [{"w": "懋学", "t": "勤学"}, {"w": "懋扬", "t": "努力显扬"}, {"w": "懋敬", "t": "勉励戒慎。"}]}, {"meaning": "极其用力。", "cites": [{"t": "咸懋力以耘耔。", "b": "张衡《东京赋》"}]}, {"meaning": "交易、买卖。", "cites": [{"t": "懋迁有无化居。", "b": "《书·益稷》"}]}, {"meaning": "大;盛大。", "cites": [{"t": "予懋乃德,嘉乃丕绩。", "b": "《书·大禹谟》"}], "words": [{"w": "懋功", "t": "大功"}, {"w": "懋典", "t": "盛典"}, {"w": "懋业", "t": "大业。"}]}, {"meaning": "美好。", "cites": [{"t": "呜呼懋哉。", "b": "《后汉书·章帝纪》。注:“美也。”"}], "words": [{"w": "懋化", "t": "美盛的化育。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6215wx','醢','1','hǎi','酉','17','','[{"pinyin": "hǎi", "defs": [{"meaning": "(形声。从酉。本义:肉酱)。"}, {"meaning": "同本义。", "cites": [{"t": "脯醢菜羹。", "b": "汉·司马光《训俭示康》"}], "words": [{"w": "醢脯", "t": "肉酱和干肉"}, {"w": "醢酱", "t": "肉酱。"}]}, {"meaning": "酱。", "cites": [{"t": "醢,酱也。", "b": "《广雅》"}, {"t": "自酒米至于盐醢百有余品,皆尽时味。", "b": "《魏书》"}, {"t": "凡国家大事、兵农礼乐,以及钱刀醯醢之细,无不经营贯串。", "b": "清·毛奇龄《王君慎斋诗集序》"}]}, {"meaning": "古代一种酷刑,将人剁成肉酱。", "cites": [{"t": "杀梅伯而醢之,杀鬼侯而脯之。", "b": "《吕氏春秋·慎行论》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6216wx','翳','1','yì','羽','17','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从羽,嫛(yī)声。本义:用羽毛做的华盖,舞具)。"}, {"meaning": "同本义。", "cites": [{"t": "翳,华盖也。", "b": "《说文》。朱骏声通训定声:“以羽覆车盖,所谓羽葆幢也。”"}]}, {"meaning": "病证名。"}, {"meaning": "指引起黑睛(角膜)混浊或溃陷的外障眼病以及病变愈后遗留于黑睛的疤痕。"}, {"meaning": "凡眼内、外障眼病所生遮蔽视线影响视力的症状皆可称翳。"}, {"meaning": "遮蔽,掩盖。", "cites": [{"t": "翳,障也。", "b": "《广雅》"}, {"t": "百神翳其备降兮。", "b": "《楚辞·离骚》。注:“翳,蔽也。”"}, {"t": "石嵯以翳日。", "b": "刘向《九叹·远逝》。注:’翳,蔽也。”"}, {"t": "翳,掩也。", "b": "《方言十三》"}, {"t": "一蝉方得美荫而忘其身,螳裔执翳而搏之。", "b": "《庄子·山水》。司马注:“执翳,执草以自翳也。”"}, {"t": "树林阴翳。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "阴翳蔽日。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "翳景", "t": "障蔽日月之光。"}]}, {"meaning": "隐藏,藏匿。", "cites": [{"t": "意者堂下其有翳憎臣者乎?", "b": "《韩非子》"}]}]}]','jingmo-wenyan');
