INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6220wx','龋','1','qǔ','齿','17','','[{"pinyin": "qǔ", "defs": [{"meaning": "龋病。龋齿,即蛀齿。俗称“蛀牙”、“虫牙” 。牙齿因蛀而残缺", "words": [{"w": "龋挛", "t": "牙齿蛀坏,身体蜷曲"}, {"w": "龋痛", "t": "蛀牙痛"}]}, {"meaning": "张开", "words": [{"w": "龋齿笑", "t": "指女子故意装出像牙痛的笑容"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6221wx','龌','1','wò','齿','17','','[{"pinyin": "wò", "defs": [{"meaning": "(形声。从齿,屋声。双音词“龌龊”,本指齿相近,又指拘牵于小节,常用义为肮脏)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6222wx','豳','1','bīn','豕','17','','[{"pinyin": "bīn", "defs": [{"meaning": "古都邑名 。在今陕西郴县", "words": [{"w": "豳州", "t": "州名。西魏时设置,隋废,唐仍为州,开元间改称邠州。即现陕西省邠县"}, {"w": "豳风", "t": "诗经十五国风之一。共有诗七篇,其中多描写农家生活,辛勤力作的情景,是我国最早的田园诗。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6223wx','壑','1','hè','土','17','','[{"pinyin": "hè", "defs": [{"meaning": "(会意。本义:深谷,深沟)。"}, {"meaning": "同本义。", "cites": [{"t": "壑,沟也。", "b": "《说文》"}, {"t": "壑,溪壑也。", "b": "《尔雅·释诂》"}, {"t": "陆峦超壑。", "b": "《文选·张衡·西京赋》"}, {"t": "既窈窕以寻壑。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "林壑尤美。", "b": "宋·欧阳修《醉翁亭记》"}, {"t": "峭壑阴森。", "b": "《徐霞客游记·游黄山记》"}, {"t": "众壑纵横。", "b": ""}, {"t": "如怒涛排壑。", "b": "孙文《序》"}], "words": [{"w": "壑谷", "t": "山谷;两山之间的洼地或水道"}, {"w": "壑口", "t": "豁口,像山谷一样的缺口"}, {"w": "壑子", "t": "豁口;缺口。"}]}, {"meaning": "小河沟;护城河。", "cites": [{"t": "实墉实壑,实亩实籍。", "b": "《诗·大雅·韩奕》。陆德明释文:“壑,城池也。”"}]}, {"meaning": "土坑。", "cites": [{"t": "其亲死,则举而委之于壑。", "b": "《孟子·滕文公上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6224wx','黻','1','fú','黹','17','','[{"pinyin": "fú", "defs": [{"meaning": "(形声。从黹(zhǐ),象缝处纵横交错之形;表示与缝衣或刺绣有关。犮bó。本义:古代礼服上青黑相间的花纹)。"}, {"meaning": "同本义。", "cites": [{"t": "君子至止,黻衣绣裳。", "b": "《诗·秦风·终南》"}], "words": [{"w": "黻衣", "t": "古代礼服的一种。"}]}, {"meaning": "绣有这种花纹的礼服。", "cites": [{"t": "士服(穿)黻,大夫(服)黼。", "b": "刘向《说苑》"}], "words": [{"w": "黻班", "t": "在宫廷中身穿黻衣的朝班行列。指显贵的地位"}, {"w": "黻冕", "t": "古代大夫以上祭祀时所穿的礼服。黻:裤裙。冕:帽子。"}]}, {"meaning": "古代祭服的蔽膝,用熟皮做成。", "cites": [{"t": "衮冕黻珽。", "b": "《左传·桓公二年》"}, {"t": "以黻冕命士会将中军。", "b": "《左传·宣公十六年》"}, {"t": "恶衣服,而致美乎黻冕。", "b": "《论语·泰伯》"}]}, {"meaning": "系印的丝带。", "cites": [{"t": "云装信解黻。", "b": "江淹《杂体·谢光禄庄郊游》"}, {"t": "委荣轻举,投黻如遗。", "b": "汉《繁阳令杨君碑》"}], "words": [{"w": "长黻", "t": "印章上长长的丝带。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6225wx','嚏','1','tì','口','17','','[{"pinyin": "tì", "defs": [{"meaning": "打喷嚏。", "cites": [{"t": "嚏,喷鼻也。", "b": "《玉篇》"}]}, {"meaning": "寤言不寐,愿言则嚏。——《诗·邶风·终风》。"}]}]','jingmo-wenyan');
