INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6227wx','蹑','1','niè','足','17','','[{"pinyin": "niè", "defs": [{"meaning": "(形声。从足,聂声。本义:踩踏,有意识地踩踏)。"}, {"meaning": "同本义。", "cites": [{"t": "蹑,蹈也。", "b": "《说文》"}, {"t": "康子履魏桓子,蹑其踵。", "b": "《战国策·秦策》"}, {"t": "张良、陈平蹑汉王足。", "b": "《史记·淮阴侯列传》"}, {"t": "蹑屐登崖。", "b": "明·刘基《诚意伯刘文成公文集》"}, {"t": "农夫蹑丝履。", "b": "宋·司马光《训俭示康》"}, {"t": "足下蹑丝履。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}]}, {"meaning": "又。", "cites": [{"t": "蹑履相逢迎。", "b": ""}], "words": [{"w": "蹑冻", "t": "踏着未融化的冰雪行路"}, {"w": "蹑球", "t": "踩球"}, {"w": "蹑蹬", "t": "踩踏石级"}, {"w": "蹑级", "t": "顺着台阶逐级上下。"}]}, {"meaning": "登。", "cites": [{"t": "世胄蹑高,英俊沉下僚。", "b": "左思《咏史》"}], "words": [{"w": "飞空蹑壁;蹑级", "t": "逐级提拔"}, {"w": "蹑空", "t": "旧谓得道成仙之人可腾空而行或停留空中"}, {"w": "蹑虚", "t": "凌空"}, {"w": "蹑云", "t": "高耸入云;腾云。"}]}, {"meaning": "穿。", "cites": [{"t": "农夫蹑丝履。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "蹑屐", "t": "拖着木屐;穿着木屐"}, {"w": "蹑蹈", "t": "穿鞋袜。"}]}, {"meaning": "追随;追赶。", "cites": [{"t": "蹑迹披求。(跟随蛤蟆的踪迹,披开丛草寻求。蹑,追踪,披,拨开。)", "b": "《聊斋志异·促织》"}], "words": [{"w": "蹑景", "t": "追赶日影"}, {"w": "蹑追", "t": "跟踪追击"}, {"w": "蹑迹", "t": "追踪;跟踪"}, {"w": "蹑风", "t": "追逐疾风"}, {"w": "蹑捕", "t": "追捕"}, {"w": "蹑逐", "t": "追逐"}, {"w": "蹑寇", "t": "追击敌寇"}, {"w": "蹑击", "t": "追击。"}]}, {"meaning": "古代织布机上用脚踩的两只踏板。", "cites": [{"t": "旧绫机五十综者五十蹑,六十综者六十蹑。", "b": "《傅子》"}]}]}]','jingmo-wenyan');
