INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6229wx','蹊','1','qī xī','足','17','','[{"pinyin": "qī", "defs": [{"meaning": "奇怪,可疑", "cites": [{"t": "宋江见了这个大汉走得蹊跷,慌忙起身赶出茶坊来,跟着那汉走。", "b": "《水浒全传》 "}]}]}, {"pinyin": "xī", "defs": [{"meaning": "(形声。从足,奚声。本作徯。本义:等待)。"}, {"meaning": "小路。亦泛指路。", "cites": [{"t": "蹊,道也。", "b": "《广雅》"}, {"t": "步所由道曰蹊。", "b": "《释名》"}, {"t": "是以间介无蹊。", "b": "马融《长笛赋》"}, {"t": "不识蹊之所由。", "b": "张衡《思玄赋》"}, {"t": "罾缴充蹊,坑阱塞路。", "b": "《三国演义》"}, {"t": "桃李不言,下自成蹊。", "b": "《史记·李将军列传》"}, {"t": "山径之蹊间介,然用之而成路。", "b": "《孟子》"}, {"t": "黄四娘家花满蹊。", "b": "唐·杜甫《江畔独步寻花》"}, {"t": "都邑蹊道居仟一。", "b": "《商君书·算地》"}], "words": [{"w": "蹊磴", "t": "山路上的石级"}, {"w": "蹊路", "t": "小路,狭路。"}]}, {"meaning": "践踏。", "cites": [{"t": "牵牛以蹊人之田。", "b": "《左传·宣公十一年》"}], "words": [{"w": "蹊践", "t": "践踏"}, {"w": "蹊田", "t": "践踏田禾"}, {"w": "蹊田夺牛", "t": "喻指罪轻罚重,从中谋利。"}]}]}]','jingmo-wenyan');
