('6233wx','疃','1','tuǎn','田','17','','[{"pinyin": "tuǎn", "defs": [{"meaning": "禽兽践踏的地方。", "cites": [{"t": "盘桓疃畔峦端路,见一个绕倒忉骚老夫。", "b": "《雍熙乐府》"}]}, {"meaning": "村庄;屯。", "cites": [{"t": "自出城,即黄茅弥望,每十余里,有村疃数家而已。", "b": "宋·陆游《入蜀记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6234wx','螳','1','táng','虫','17','','[{"pinyin": "táng", "defs": [{"meaning": "螳螂的简称。", "cites": [{"t": "螳,螳螂也。", "b": "《说文新附》"}, {"t": "螳螂,有斧虫。", "b": "《玉篇》"}, {"t": "犹螳螂之怒臂以当车轶。", "b": "《庄子·天地》"}, {"t": "睹-蝉方得美荫而忘其身,螳螂执翳而搏之。", "b": "《庄子·山木》"}], "words": [{"w": "螳斧", "t": "指螳螂前足。以其前两足高举如人执斧,故名。亦喻脆弱的武装"}, {"w": "螳螂之卫", "t": "比喻微弱的兵备"}, {"w": "螳臂", "t": "比喻不自量力;微弱之力"}, {"w": "螳轮", "t": "比喻不自量力者"}, {"w": "螳臂拒辙,螳臂当辙,螳臂扼辙", "t": "犹螳臂当车。"}]}]}]','jingmo-wenyan');
