INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6237wx','羁','1','jī','罒','17','','[{"pinyin": "jī", "defs": [{"meaning": "(会意。从网(罒),从革(皮革),从马。合起来表示用皮革制成的网络来把马络住。本义:马笼头)。"}, {"meaning": "同本义。", "cites": [{"t": "红牛缨绂黄金羁。", "b": "韩愈《汴泗交流赠张仆射》"}], "words": [{"w": "羁縻", "t": "羁,马络头;縻,牛紖。喻联络、维系"}, {"w": "羁勒", "t": "马络头。"}]}, {"meaning": "古代女孩留在头顶像马络头一般的头发。", "cites": [{"t": "男角女羁。", "b": "《礼记·内则》"}], "words": [{"w": "男角女羁;羁角", "t": "孩童发髻。又称羁卯,羁贯"}, {"w": "羁贯", "t": "古时儿童发式。"}]}, {"meaning": "套上笼头。", "cites": [{"t": "使麒麟可系而羈兮,岂云异夫犬羊。", "b": "汉·贾谊《吊屈原赋》"}, {"t": "此犹禽鹿,少见驯育,则服从教制,长而见羈,则狂顾頓缨。", "b": "三囯魏·嵇康《与山巨源绝交书》"}]}, {"meaning": "系,捆绑;束缚,拘束。", "cites": [{"t": "仆少负不羈之才。", "b": "司馬遷《报任安书》"}, {"t": "羈鸟恋旧林。", "b": "晋·陶渊明《归去来兮辞》"}, {"t": "顺天府羈候。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "羈靡", "t": "束缚"}, {"w": "羈梏", "t": "束縛"}, {"w": "羈防", "t": "管制防範"}, {"w": "羈軛", "t": "束縛;控制"}, {"w": "羈身", "t": "有事纏身,走不開"}, {"w": "羈滞", "t": "因事牵挂而停留"}, {"w": "羈縻", "t": "拖延;籠絡;纏住。"}]}, {"meaning": "寄居;旅寓。", "cites": [{"t": "为羈终岁,门人谢焉。", "b": "庾信《思旧铭》"}], "words": [{"w": "羈宦", "t": "旅居外地任官"}, {"w": "羈恨", "t": "客居异地的愁苦烦恼"}, {"w": "羈屑", "t": "寄居异地而又身世寒微。"}]}, {"meaning": "停留。", "cites": [{"t": "妾处耳目多,不可久羈,蹈隙当复来。", "b": "《聊斋志异》"}, {"t": "不羈晷刻。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "羈泊", "t": "羁留他乡。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6238wx','罽','1','jì','罒','17','','[{"pinyin": "jì", "defs": [{"meaning": "鱼网。", "cites": [{"t": "罽,鱼网也。", "b": "《说文》"}]}, {"meaning": "羊毛织物。", "cites": [{"t": "鹅毛御腊缝山罽,鸡骨占年拜水神。", "b": "柳宗元《柳州峒氓》"}], "words": [{"w": "罽衣", "t": "毛织物制的衣服"}, {"w": "罽车", "t": "有毛毡帷幕的坐车"}, {"w": "罽茵", "t": "毛毯"}, {"w": "罽毯", "t": "毛毯"}, {"w": "罽幕", "t": "毛毡制的帐幕。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6239wx','罾','1','zēng','罒','17','','[{"pinyin": "zēng", "defs": [{"meaning": "(形声。从四(网),曾声。本义:一种用木棍或竹杆做支架的鱼网) 同本义。", "cites": [{"t": "罾,鱼网也。", "b": "《说文》"}, {"t": "钓饵网罟罾笱之知多,则鱼乱于水矣。", "b": "《庄子·胠箧》"}, {"t": "鸟何萃兮苹中,罾何为兮木上?", "b": "《楚辞·湘夫人》"}], "words": [{"w": "攀罾", "t": "攀拉鱼网"}, {"w": "罾口", "t": "网口"}, {"w": "罾古", "t": "泛指鱼网"}, {"w": "罾笱", "t": "泛指渔具"}, {"w": "罾布", "t": "一种用破罾和绵纱线织成的布。"}]}, {"meaning": "用网捕捞。", "cites": [{"t": "所罾鱼腹中。", "b": "《史记·陈涉世家》"}], "words": [{"w": "罾船", "t": "装有罾网的渔船"}, {"w": "罾罩", "t": "泛指捕鱼的用具。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6240wx','嶷','1','nì yí','山','17','','[{"pinyin": "nì", "defs": [{"meaning": "幼小聪慧。", "cites": [{"t": "诞实匍匐,克岐克嶷。", "b": "《诗·大雅·生民》"}, {"t": "幼儿明嶷。", "b": "《南史·宋江夏王义恭传》"}], "words": [{"w": "嶷嶷", "t": "幼小聪慧的样子"}, {"w": "嶷然", "t": "形容年幼聪慧。"}]}, {"meaning": "高尚;杰出。", "cites": [{"t": "其德嶷嶷。", "b": "《史记·五帝本纪》"}], "words": [{"w": "嶷如", "t": "卓异的样子"}, {"w": "嶷然", "t": "嶷尔。卓异的样子;端庄的样子"}, {"w": "嶷嶷", "t": "道德高尚的样子。"}]}, {"meaning": "高耸。", "cites": [{"t": "世目周侯“嶷如断山”。", "b": "《世说新语·赏誉》"}], "words": [{"w": "嶷岌", "t": "高的样子"}, {"w": "嶷嶷", "t": "高耸的样子。"}]}]}, {"pinyin": "yí", "defs": [{"meaning": "——见“九嶷”(jiǔyí)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6241wx','黜','1','chù','黑','17','','[{"pinyin": "chù", "defs": [{"meaning": "(形声。从黑,出声。本义:黑暗)。"}, {"meaning": "降职或罢免。", "cites": [{"t": "黜,贬下也。", "b": "《说文》"}, {"t": "黜,贬也,下也。", "b": "《玉篇》"}, {"t": "黜陟幽明。", "b": "《虞书》。传:“退其幽者。”"}, {"t": "何以黜朱于朝。", "b": "《左传·襄公二十六年》"}, {"t": "咸黜不端。", "b": "《左传·昭公二十六年》"}, {"t": "台臣惭,追受其牒,为复太守官而黜臧使者。", "b": "高适《书博鸡者事》"}, {"t": "理乱不知,黜涉不闻。", "b": "韩愈《送李愿归盘谷序》"}], "words": [{"w": "罢黜百家;黜落", "t": "罢免,除名"}, {"w": "黜升", "t": "官吏的罢免与升迁"}, {"w": "黜放", "t": "革职放逐。"}]}, {"meaning": "废除;取消。", "cites": [{"t": "汤既黜夏命。", "b": "《书·汤诰序》"}, {"t": "爱季佗而黜仆。", "b": "《左传·文公十八年》"}, {"t": "王黜翟后。", "b": "《国语·周语》"}, {"t": "君将黜嗜欲。", "b": "《庄子·徐无鬼》"}], "words": [{"w": "黜华", "t": "摈除文饰,不事虚华。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6242wx','黝','1','yǒu','黑','17','','[{"pinyin": "yǒu", "defs": [{"meaning": "(形声。从黑,幼声。本义:淡黑色)。"}, {"meaning": "同本义。", "cites": [{"t": "黝,微青黑色。", "b": "《说文》"}, {"t": "黑谓之黝。", "b": "《尔雅》"}, {"t": "其祧则守祧黝垩之。", "b": "《周礼·春官·守祧》"}, {"t": "一命赤袚幽衡,再命赤韨幽衡。", "b": "《礼记·玉藻》。唐·孔颖达疏引孙炎注《尔雅》云:“黝,青黑。”"}, {"t": "阴祀用黝牲,毛之。", "b": "《周礼·地官·牧人》"}], "words": [{"w": "黝牲", "t": "黑色的牲畜"}, {"w": "黝垩", "t": "以黑色和白色作涂饰"}, {"w": "黝犊", "t": "黑色小牛"}, {"w": "黝瘦", "t": "又黑又瘦"}, {"w": "黝绿", "t": "浓绿"}, {"w": "黝泽", "t": "浓黑而有光泽"}, {"w": "黝面", "t": "青黑色脸面。"}]}, {"meaning": "长长的样子。", "cites": [{"t": "浮梁黝以径度,灵台杰其高峙。", "b": "《文选·潘岳·闲居赋》"}]}, {"meaning": "变黑;使发黑。", "cites": [{"t": "铠胄黝锈,枪刀弓矢生疏。", "b": "《歧路灯》"}], "words": [{"w": "黝垩", "t": "涂以黑色和白色"}, {"w": "黝锈", "t": "发黑生锈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6243wx','髁','1','kē','骨','17','','[{"pinyin": "kē", "defs": [{"meaning": "股骨。", "cites": [{"t": "髁,髀骨也。", "b": "《说文》。段玉裁注:“髀骨,犹言骰骨也。”"}]}, {"meaning": "尾骨。", "cites": [{"t": "髁,尻骨。", "b": "《一切经音义》引《三苍篇》"}]}, {"meaning": "踝骨。也作“踝”。", "cites": [{"t": "群儿坌涌,各持砖瓦击其髁…次日,家人寻之归,两足青紫。", "b": "清·纪昀《阅微草堂笔记》"}]}, {"meaning": "膝骨。也 指膝部。", "cites": [{"t": "髁,膝骨。", "b": "《广韵》"}]}]}]','jingmo-wenyan');
