INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6249wx','镧','1','lán','钅','17','','[{"pinyin": "lán", "defs": [{"meaning": "一种银白色的柔软而有展性的三价金属元素,在潮湿空气中迅速失去光泽,生成无色化合物,它存在于稀土矿中,通常把它归在稀土族内,是混合稀土的一种主要成分 ——元素符号La。"}]}]','jingmo-wenyan');
