('6252wx','镫','1','dèng','钅','17','','[{"pinyin": "dèng", "defs": [{"meaning": "古代盛熟食器皿。", "cites": [{"t": "镫,锭也。从金,登声。", "b": "《说文》。按,即登也。古用瓦,后世范金为之,又制此字。”"}, {"t": "执醴授之,执镫。", "b": "《礼记·祭统》。注:“镫,豆下跗也。”"}]}, {"meaning": "马镫。", "cites": [{"t": "镫,鞍镫。", "b": "《广韵》"}]}, {"meaning": "古同“灯”。", "cites": [{"t": "兰膏明烛,华镫错些。", "b": "《楚辞·招魂》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6253wx','罅','1','xià','缶','17','','[{"pinyin": "xià", "defs": [{"meaning": "(形声。从缶(fǒu),虖(hū)声。缶,瓦器。本义:裂,开裂) 同本义。", "cites": [{"t": "罅,裂也。", "b": "《说文》。朱骏声曰:“烧缶善裂,即考工旊人所谓薜也。”"}, {"t": "刘注:“栗皮拆罅而发也。”", "b": ""}, {"t": "当中还罅着几寸宽一个空当儿。", "b": "《老残游记》"}, {"t": "如合掌,中罅。", "b": "《徐霞客游记》"}], "words": [{"w": "罅裂", "t": "开裂"}, {"w": "罅发", "t": "爆裂;开裂。"}]}, {"meaning": "裂缝;缝隙。", "cites": [{"t": "徐而察之,则山下皆石穴罅。", "b": "宋·苏轼《石钟山记》"}, {"t": "多松,生石罅,皆平顶。", "b": "清·姚鼐《登泰山记》"}], "words": [{"w": "罅穴", "t": "缝隙和漏洞"}, {"w": "罅洞", "t": "缝隙和漏洞"}, {"w": "罅隙;罅缝", "t": ""}]}, {"meaning": "漏洞。", "cites": [{"t": "姑且修弊补罅,休劳息困,以与久疲之民相安。", "b": "王守仁《处置平复地方以图久安疏》"}], "words": [{"w": "罅缺", "t": "缺漏。"}]}]}]','jingmo-wenyan');
