INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6259wx','簋','1','guǐ','皿','17','','[{"pinyin": "guǐ", "defs": [{"meaning": "(会意,从竹,从皿,从皀。本义:古代青铜或陶制盛食物的容器,圆口,两耳或四耳)同本义。", "cites": [{"t": "簋,黍稷方器也。", "b": "《说文》"}, {"t": "皆云圆曰簋,谓内圆也。", "b": "《周礼·舍人》注"}, {"t": "二簋可用享。", "b": "《易·损》"}, {"t": "每食四簋。", "b": "《诗·秦风·权舆》"}, {"t": "宰夫设黍稷六簋。", "b": "《仪礼·公食礼》"}, {"t": "陈馈八簋。", "b": "《诗·小雅·伐木》"}, {"t": "鼎簋十有二。", "b": "《周礼·掌客》"}, {"t": "饭土簋。", "b": "《史记·始皇纪》"}, {"t": "臣闻昔者尧有天下,饭于土簋,饮于土簠。", "b": "《韩非子·十过》"}, {"t": "管仲镂簋朱紘,山节藻棁,孔子鄙其小器。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "簋廉", "t": "盛酒的瓦器"}, {"w": "簋实", "t": "置于簋器的黍稷。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6260wx','鼢','1','fén','鼠','17','','[{"pinyin": "fén", "defs": [{"meaning": "也叫\\"盲鼠\\"、\\"地羊\\"。哺乳动物。体胖，尾短，眼小，毛灰褐色。生活在田野里，吃农作物的根和地下茎等。在地下打洞，甚至破坏河堤消灭～鼠。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6261wx','黛','1','dài','黑','17','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从黑,代声。本义:青黑色的颜料。古代女子用以画眉)。"}, {"meaning": "同本义。", "cites": [{"t": "黱,画眉也。从黑,朕声。", "b": "《说文》。锴本作画眉墨。字亦作黛。"}, {"t": "染青石谓之点黛。", "b": "《通俗文》"}, {"t": "黛,代也。灭眉毛去之,以此画代其处也。", "b": "《释名》"}, {"t": "六宫粉黛无颜色。", "b": "唐·白居易《长恨歌》"}, {"t": "西方有石名黛,可代画眉之墨。", "b": "《红楼梦》"}], "words": [{"w": "黛岑", "t": "青黑如黛的山峰"}, {"w": "黛螺", "t": "绘画或画眉所使用的青黑色颜料。"}]}, {"meaning": "青黑色。", "cites": [{"t": "霜皮溜雨四十围,黛色参天二千尺。", "b": "杜甫《古柏行》"}, {"t": "两岸的青山…都装成了深黛的颜色。", "b": "鲁迅《故乡》"}], "words": [{"w": "黛烟", "t": "青黑色的烟"}, {"w": "黛青", "t": "青黑如眉黛"}, {"w": "黛色", "t": "青黑色。"}]}]}]','jingmo-wenyan');
