('6262wx','儡','1','léi lěi','亻','17','','[{"pinyin": "léi", "defs": [{"meaning": "败坏。", "cites": [{"t": "儡,相败也。", "b": "《说文》"}, {"t": "然而不免于儡身。", "b": "《淮南子·俶真》"}], "words": [{"w": "儡亡", "t": "颓丧的样子"}, {"w": "儡然", "t": "破败的样子。"}]}, {"meaning": "疲倦。", "cites": [{"t": "寮位儡其隆替。", "b": "潘岳《西征赋》"}], "words": [{"w": "儡儡", "t": "颓丧失意的样子;衰竭疲惫的样子。"}]}, {"meaning": "羸弱。", "cites": [{"t": "容貌儡以顿悴兮,左右凄其相慜。", "b": "《文选·潘岳·寡妇赋》?"}]}]}, {"pinyin": "lěi", "defs": [{"meaning": "——见“傀儡”(kuǐlěi)。"}]}]','jingmo-wenyan');
