INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6267wx','龠','1','yuè','龠','17','','[{"pinyin": "yuè", "defs": [{"meaning": "(“籥”(yuè)的本字。会意。从品仑。“品”表示乐器的管孔,仑是按顺序排列之义。本义:乐器名)。"}, {"meaning": "古代管乐器像编管之形,似为排箫之前身。", "cites": [{"t": "龠,乐之竹管,三孔,以和众声也。", "b": "《说文》。经传皆以籥为之。"}]}, {"meaning": "量词:量器名。", "cites": [{"t": "量者,龠、合、升、斗、斛也。所以量多少也。本起于黄钟之龠,…合龠为合,十合为升,十升为斗,十斗为斛。", "b": "《汉书·律历志》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6268wx','繇','1','yáo yóu zhòu','糸','17','','[{"pinyin": "yáo", "defs": [{"meaning": "(形声。从系,本义:随从)。"}, {"meaning": "同本义。", "cites": [{"t": "鲁颜无繇。", "b": "《史记·弟子传》"}]}, {"meaning": "动摇。", "cites": [{"t": "我起乎宜阳而触平阳,二日而莫不尽繇。", "b": "《史记》"}]}, {"meaning": "力役,通“徭”。", "cites": [{"t": "繇者揭钁,负笼土。", "b": "《淮南子·精神》。高注:“繇役也。”"}, {"t": "每吴中有大繇役及丧。", "b": "《史记·项羽本纪》"}, {"t": "减太官,省繇赋。", "b": "《汉书·景帝纪》"}, {"t": "又如:繇戍(遣民到边境戍守,服役。同徭戍);繇役(古代百姓为朝庭服劳役的义务。同徭役);繇使(指供力役及为使者);繇赋(徭役和田赋捐税)", "b": ""}]}, {"meaning": "歌谣。", "cites": [{"t": "参人民繇俗。", "b": "《汉书·李寻传》。颜师古云:“繇,读与谣同。”"}], "words": [{"w": "繇俗", "t": "歌谣风俗。"}]}, {"meaning": "古族名 ,秦汉时闽越族分为繇和东越两部。"}, {"meaning": "茂盛;草茂盛。", "cites": [{"t": "厥草惟繇。", "b": "《书·禹贡》"}]}, {"meaning": "远。", "cites": [{"t": "是以繇其期,足以日也。", "b": "《荀子·礼论》"}]}, {"meaning": "姓。"}]}, {"pinyin": "yóu", "defs": [{"meaning": "从,自。", "cites": [{"t": "繇膝以下为揭,繇膝以上为涉。", "b": "《尔雅》"}, {"t": "盖闻天道祸自怨起而福繇德兴。", "b": "《史记·文帝本纪》"}]}, {"meaning": "", "cites": [{"t": "近者陆子优繇。", "b": "《汉书·文帝纪》"}]}, {"meaning": "经。", "cites": [{"t": "所繇适于治之路也。", "b": "《汉书·董仲书传》"}, {"t": "政繇冢宰。", "b": "《汉书·魏相传》。颜师古云:“繇,与由同。”"}, {"t": "繇朐汏輈。", "b": "《左传·昭公二十六年》"}]}]}, {"pinyin": "zhòu", "defs": [{"meaning": "古时占卜的文辞。", "cites": [{"t": "成风闻成季之繇。", "b": "《左传·闵公二年》"}], "words": [{"w": "繇词", "t": "卦兆的占词。繇,通“籀”"}, {"w": "繇文", "t": "占卜的文辞。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6269wx','貘','1','mò','豸','17','','[{"pinyin": "mò", "defs": [{"meaning": "产于南美、中美、马来亚和苏门答腊的几种貘科的大型奇蹄类动物,身体笨重缺毛,鼻吻部延长成为一条灵活的短象鼻,尾退化,四肢短粗,前趾四,后趾三,主要属于夜行性,胆小而温顺,常出没于近水的密林中。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6270wx','邈','1','miǎo','辶','17','','[{"pinyin": "miǎo", "defs": [{"meaning": "(形声。从辵(chuò),貌声。本义:距离遥远)。"}, {"meaning": "同本义,通“藐”。", "cites": [{"t": "振景拔迹,顾邈同列。", "b": "陆机《谢平原内史表》"}, {"t": "互相轩邈。", "b": "吴均《与朱元思书》"}], "words": [{"w": "邈若山河", "t": "形容遥远得如隔山河"}, {"w": "邈绵", "t": "遥远;旷远"}, {"w": "邈廓", "t": "辽阔"}, {"w": "邈远", "t": "遥远"}, {"w": "邈然", "t": "遥远的样子。"}]}, {"meaning": "轻视,小看。", "cites": [{"t": "说大人则邈之。", "b": "《孟子·尽心下》"}], "words": [{"w": "邈视", "t": "藐视。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6271wx','貔','1','pí','豸','17','','[{"pinyin": "pí", "defs": [{"meaning": "又名白罴、白孤、执夷 。传说中的一种野兽,有的说像虎,有的说像熊", "words": [{"w": "貔熊", "t": "古代两种猛兽名。比喻勇猛的将士"}]}]}]','jingmo-wenyan');
