INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6273wx','膻','1','shān','月','17','','[{"pinyin": "shān", "defs": [{"meaning": "(形声。从肉,亶(dǎn)声。本义:羊臊气)。"}, {"meaning": "同本义。亦泛指臊气。", "cites": [{"t": "蚊慕羊肉,羊肉膻也。", "b": "《庄子·综无鬼》"}], "words": [{"w": "膻气", "t": "羊肉的气味"}, {"w": "膻根", "t": "指羊"}, {"w": "膻荤", "t": "指肉类或气味浓烈的食品。也作“荤羶”"}, {"w": "膻芗", "t": "祭祀时焚烧牛羊肠间脂肪所散发出来的气味"}, {"w": "膻腻", "t": "腥膻油腻。"}]}, {"meaning": "类似羊臊气的恶臭。", "cites": [{"t": "王之嫔御,膻恶而不可亲。", "b": "《列子·周穆王》"}], "words": [{"w": "膻腥", "t": "荤腥。亦指鱼肉类食物"}, {"w": "膻秽", "t": "又臭又脏。谓肮脏丑恶。"}]}, {"meaning": "有膻味的兽肉。", "cites": [{"t": "膻,肉膻也。诗曰:膻裼暴虎。", "b": "《说文》"}], "words": [{"w": "膻肉", "t": "羊肉"}, {"w": "膻食", "t": "膻荤。肉类食物"}, {"w": "膻根", "t": "羊及羊肉的别称。"}]}, {"meaning": "五谷的香气。因以指祭祀所用的黍稷等谷物)。"}, {"meaning": "羊油 (弃膻在庭际,双鹊来摇尾。——唐·皮日休《喜鹊》)。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6274wx','臆','1','yì','月','17','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从肉,意声。又作“肊”。本义:胸骨)。"}, {"meaning": "同本义。", "cites": [{"t": "臆,胸骨也。", "b": "《说文》"}]}, {"meaning": "胸部。", "cites": [{"t": "气交愤于胸臆。", "b": "王粲《登楼赋》"}, {"t": "臆,匈也。", "b": "《广雅》"}, {"t": "仪遗忏以臆对。", "b": "《汉书·序传上》"}, {"t": "丹臆兰臆。", "b": "潘岳《射雉赋》"}, {"t": "夜寒衣湿披短蓑,臆穿足裂忍痛何?", "b": "唐·王建《水夫谣》"}], "words": [{"w": "抚臆论心", "t": ""}]}, {"meaning": "意料;推测。", "cites": [{"t": "乃知天下之事,不可尽知,而以臆断之,不可任也。", "b": "《抱朴子》"}, {"t": "请对以臆。", "b": "《史记·贾谊传》"}, {"t": "然而子长少臆中之说。", "b": "《论衡·案书》"}], "words": [{"w": "臆辨", "t": "只凭推测来辨别。"}]}, {"meaning": "主观地。", "cites": [{"t": "妄以臆度。", "b": "清·刘开《问说》"}], "words": [{"w": "臆中", "t": "犹言主观想象"}, {"w": "臆出", "t": "主观所出"}, {"w": "臆见", "t": "亦作“肊见”。主观的看法"}, {"w": "臆决", "t": "主观地决断"}, {"w": "臆定", "t": "主观地断定"}, {"w": "臆算", "t": "主观推算"}, {"w": "臆改", "t": "凭臆测改动文字。"}]}]}]','jingmo-wenyan');
