INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6276wx','鲼','1','fèn','鱼','17','','[{"pinyin": "fèn", "defs": [{"meaning": "鲼科(Myliobatidae)中的几种灵活的大魟鱼 ,长有翅膀似的宽阔的胸鳍,有几种分布很广,尤其分布在暖海域。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6277wx','鲽','1','dié','鱼','17','','[{"pinyin": "dié", "defs": [{"meaning": "比目鱼的一种 ,体形侧扁,两眼均生在身体的右侧,有眼的一侧褐色,无眼的一侧黄色或白色,常见的有星鲽、高眼鲽等。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6278wx','鳀','1','tí','鱼','17','','[{"pinyin": "tí", "defs": [{"meaning": "鱼名。鳀鱼，体稍扁侧，长10厘米左右，银灰色，两侧各有一条银色纵带。眼和口均大。腹部呈圆柱形。生活在海里，可供食用。幼鱼干制品叫\\"海蜓\\"。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6279wx','鳃','1','sāi','鱼','17','','[{"pinyin": "sāi", "defs": [{"meaning": "鱼类吸取水中氧气的器官 。古人言鳃多指鳃盖", "words": [{"w": "鳃心", "t": ""}, {"w": "鳃叶", "t": ""}, {"w": "鳃裂", "t": ""}, {"w": "鳃盖", "t": ""}, {"w": "鳃孔", "t": "鱼鳃的鳃丝"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6280wx','鳅','1','qiū','鱼','17','','[{"pinyin": "qiū", "defs": [{"meaning": "鳅科鱼类的统称 。小型旧大陆淡水鳅科鱼类的任何一种,与鲤科鱼类近缘,但外形和习性与鲇类鱼相似。常见的有泥鳅、沙鳅和长薄鳅等", "words": [{"w": "鳅鱣", "t": "鳅鳝。泥鳅和鳝鱼"}, {"w": "鳅鱽", "t": "泥鳅与刀鱼"}, {"w": "鳅鱼", "t": "即泥鳅"}, {"w": "鳅鳖", "t": "泥鳅与鳖鱼"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6281wx','鳇','1','huáng','鱼','17','','[{"pinyin": "huáng", "defs": [{"meaning": "鲟鳇鱼 。属于鲟科的一种鱼,产于黑龙江、乌苏里江、松花江等处,体长约四米。本属其他各种产于欧、亚一些大河流中,形状像鲟鱼,古名“鳣”。体形为长纺锤状,唇突出,背面色在茶褐与黄灰之间,腹面灰黄,有斜方形硬鳞,尾鳍不正,头有软骨,叫鲟骨,生活在近海", "words": [{"w": "鳇糟", "t": "糟渍的鳇鱼"}, {"w": "鳇冰", "t": "鳇鱼的软骨"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6282wx','鳊','1','biān','鱼','17','','[{"pinyin": "biān", "defs": [{"meaning": "鱼名 ,也称“鲂”。古时“纺”和鳊不分。今指鲤科鳊属鱼。身体侧扁,头尖,尾也小,鳞细,生活在淡水中。又名武昌鱼。"}]}]','jingmo-wenyan');
