INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6284wx','燮','1','xiè','火','17','','[{"pinyin": "xiè", "defs": [{"meaning": "(会意。从言,从又炎。表示用言语调和。本义:协和;调和) 同本义。", "cites": [{"t": "燮友柔克。", "b": "《书·洪范》"}], "words": [{"w": "燮理阴阳", "t": "协调各部门工作"}, {"w": "燮和", "t": "协和;亦指宰相的政务"}, {"w": "燮务", "t": "燮理政务。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6285wx','鹫','1','jiù','鸟','17','','[{"pinyin": "jiù", "defs": [{"meaning": "老雕。", "cites": [{"t": "鹫鸟,黑色,多子。师旷曰,南方有鸟,名曰羌鹫,黄头赤目,五色皆备。", "b": "《说文》"}, {"t": "鹫,雕也。", "b": "《广雅》"}, {"t": "生奇材木箭竿就(鹫)羽。", "b": "《汉书·匈奴传》。注:“大雕也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6286wx','襄','1','xiāng','衣','17','','[{"pinyin": "xiāng", "defs": [{"meaning": "(会意。据金文,“襄”是手拿农具在地里挖一个个小洞,放进种子,再盖土。《说文》称“解衣耕”。本义:解衣耕地)。"}, {"meaning": "同本义。", "cites": [{"t": "襄,汉令:解衣耕谓之襄。", "b": "《说文》"}, {"t": "辟地为襄。", "b": "《周书·谥法》"}]}, {"meaning": "助理,佐治。", "cites": [{"t": "思日赞赞襄哉。", "b": "《书·皋谟》"}, {"t": "必纳王妃,以襄内政。", "b": "《三国演义》"}], "words": [{"w": "襄成", "t": "辅助成为"}, {"w": "襄助", "t": "辅佐;帮助"}, {"w": "襄事", "t": "帮助办事"}, {"w": "襄办", "t": "帮助办理"}, {"w": "襄赞", "t": "辅佐帮助。"}]}, {"meaning": "成就,完成。", "cites": [{"t": "不克襄事。", "b": "《左传·定公十五年》。注:“成也。”"}, {"t": "刘院既知此事颠末,又与公同心,必能共襄大事。", "b": "明·张居正《答王鉴川计贡事利害》"}], "words": [{"w": "襄事", "t": "成事"}, {"w": "共襄义举", "t": ""}]}, {"meaning": "仰,上举。", "cites": [{"t": "汤汤洪水方割,荡荡怀山襄陵,浩浩滔天。", "b": "《书·尧典》"}, {"t": "以乐乘为武襄君。", "b": "《史记·赵世家》。正义:“举也,上也。”"}]}, {"meaning": "驾;驾车的马。", "cites": [{"t": "两服上襄。", "b": "《诗·郑风·大叔于田》"}, {"t": "襄,驾也。", "b": "《尔雅》"}]}, {"meaning": "高的。", "cites": [{"t": "襄岸夷涂。", "b": "《文选·张衡·西京赋》"}], "words": [{"w": "襄岸", "t": "高岸。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6287wx','糜','1','mí méi','米','17','','[{"pinyin": "mí", "defs": [{"meaning": "(形声。从米,麻声。本义:粥) 同本义。", "cites": [{"t": "糜,糁也。", "b": "《说文》"}, {"t": "糜,煮米使糜烂也。", "b": "《释名·释饮食》"}, {"t": "糜,糜粥。", "b": "《广韵》"}, {"t": "粥之稠者曰糜。", "b": "《尔雅·释言》注"}, {"t": "他家但愿富贵,贱妾与君共餔糜。", "b": "古乐府《东门行》"}], "words": [{"w": "糜沸", "t": "比喻世事混乱之甚,如糜粥之沸于釜中"}, {"w": "糜粥", "t": "粥。"}]}, {"meaning": "粉碎,捣烂。", "cites": [{"t": "以糜敝之。", "b": "《荀子·富国》。注:“散也”"}, {"t": "万钧之所压,无不糜灭者,", "b": "贾山《至言》"}], "words": [{"w": "糜没", "t": "粉碎毁灭"}, {"w": "糜灭", "t": "粉碎毁灭"}, {"w": "糜躯", "t": "粉身碎骨,指献出生命"}, {"w": "糜捐", "t": "粉身碎骨,舍弃生命"}, {"w": "糜粉", "t": "粉碎。亦指碎屑。"}]}, {"meaning": "消耗,通“靡”。", "cites": [{"t": "不益于好而糜费功夫。", "b": "《三国志·魏书·卫觊传》"}, {"t": "徒糜弹药。", "b": "清·徐珂《清稗类钞·战事类》"}], "words": [{"w": "糜耗", "t": "糜费"}, {"w": "糜费", "t": "浪费"}, {"w": "糜损", "t": "浪费损耗。"}]}]}, {"pinyin": "méi", "defs": [{"meaning": "一种不粘的黍"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6288wx','縻','1','mí','糸','17','','[{"pinyin": "mí", "defs": [{"meaning": "(形声。从糸(mì),麻声。本义:牛缰绳) 同本义。", "cites": [{"t": "縻,牛辔也。", "b": "《说文》"}, {"t": "縻,牛缰也。", "b": "《苍颉篇》"}, {"t": "马曰羁,牛曰縻。", "b": "应劭《汉官仪》"}, {"t": "羁縻勿绝。", "b": "《史记·史马相如传》"}, {"t": "叟揽縻而对。", "b": "刘禹锡《叹牛》"}], "words": [{"w": "揽縻", "t": "拉着牛鼻绳"}, {"w": "縻粃", "t": "牵牛的缰绳"}, {"w": "縻绠", "t": "牵引的绳子。"}]}, {"meaning": "束缚,拘束。", "cites": [{"t": "是谓縻举。", "b": "《孙子·谋攻》"}, {"t": "辞言无所系縻。", "b": "《韩非子·说难》"}], "words": [{"w": "羁縻", "t": "牵制;笼络"}, {"w": "縻系", "t": "拘禁;捆缚;牵制"}, {"w": "縻职", "t": "被职务牵制束缚"}, {"w": "縻絷", "t": "拘禁"}, {"w": "縻络", "t": "拘囚"}, {"w": "縻军", "t": "指受牵制而不能灵活机动的军队。"}]}, {"meaning": "消耗,通“靡”。", "cites": [{"t": "坐縻廪粟。", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "縻费", "t": "耗费;浪费。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6289wx','膺','1','yīng','月','17','','[{"pinyin": "yīng", "defs": [{"meaning": "(形声。从肉。本义:胸腔,胸)。"}, {"meaning": "同本义。", "cites": [{"t": "膺,胸也。", "b": "《说文》"}, {"t": "无搯膺。", "b": "《国语·鲁语》"}, {"t": "背膺拌合以交痛兮。", "b": "《楚辞·惜诵》"}, {"t": "编愁苦以为膺。", "b": "《楚辞·悲回风》"}, {"t": "无拊膺。", "b": "《孔子家语·子夏问》"}, {"t": "旧事填膺,思之凄梗。", "b": "清·袁枚《祭妹文》"}], "words": [{"w": "膺门", "t": "马的胸膛"}, {"w": "膺臆", "t": "胸臆。多指个人的思想或见解"}, {"w": "义愤填膺", "t": ""}]}, {"meaning": "乳上骨。"}, {"meaning": "胸傍,胸部两侧的肌肉隆起处。", "cites": [{"t": "有病膺肿颈痛胸满腹胀,此为何病?", "b": "《素问》"}], "words": [{"w": "膺中", "t": "胸前两旁高处。"}]}, {"meaning": "心间;胸臆。", "cites": [{"t": "回之为人也,择乎中庸,得一善,则拳拳服膺而弗失之矣。", "b": "《礼记》"}], "words": [{"w": "膺服", "t": "谨记在心;衷心信服"}, {"w": "膺肺", "t": "内心"}, {"w": "膺堂", "t": "心间。"}]}, {"meaning": "担当,接受重任。", "cites": [{"t": "臣有何德何能,敢膺圣眷如此!", "b": "《警世通言》"}], "words": [{"w": "膺天明命", "t": "承受天命"}, {"w": "膺期", "t": "承受期运。指受天命为帝王"}, {"w": "膺运", "t": "膺期"}, {"w": "膺荐", "t": "承受荐举。"}]}, {"meaning": "接受。", "cites": [{"t": "天子受四海之图籍,膺万国之贡珍。", "b": "《后汉书》"}], "words": [{"w": "膺命", "t": "接受天命。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6290wx','癍','1','bān','疒','17','','[{"pinyin": "bān", "defs": [{"meaning": "皮肤上生斑点的病 。亦指皮肤上生的斑点", "words": [{"w": "癍疮", "t": "中医指眼中所生的白翳"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6291wx','麋','1','mí','鹿','17','','[{"pinyin": "mí", "defs": [{"meaning": "(形声。从鹿,米声。本义:兽名。即麋鹿)。"}, {"meaning": "同本义。", "cites": [{"t": "麋,鹿属。从鹿,米声。麋冬至其角。", "b": "《说文》"}, {"t": "夏献麋。", "b": "《周礼·兽人》。疏:“麋是泽解兽”。"}, {"t": "麋何食兮庭中。", "b": "《楚辞·湘妇人》"}], "words": [{"w": "麋裘", "t": "用幼鹿皮制的皮衣"}, {"w": "麋侯", "t": "糜皮箭靶"}, {"w": "麋田", "t": "麋群踩过的田"}, {"w": "麋脯", "t": "干麋肉。"}]}, {"meaning": "眉毛。", "cites": [{"t": "伊尹之状,面无须麋。", "b": "《荀子·非相》"}], "words": [{"w": "麋寿", "t": "眉寿。长寿"}, {"w": "麋首", "t": "长寿的人。"}]}, {"meaning": "水边,岸旁。", "cites": [{"t": "彼何人斯,居河之麋。", "b": "《诗·小雅·巧言》"}, {"t": "余赐女孟诸之麋。", "b": "《左传·僖公二十八年》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6292wx','懑','1','mèn','心','17','','[{"pinyin": "mèn", "defs": [{"meaning": "(会意。从心,从满。满心烦闷。本义:烦闷)。"}, {"meaning": "同本义。", "cites": [{"t": "懑,烦也。", "b": "《说文》"}, {"t": "懑,烦闷。", "b": "《广韵》"}, {"t": "广陵太守陈登得病,胸中烦懑。", "b": "《三国志·华陀传》"}, {"t": "故济北王阿母自言足热而懑。", "b": "《史记·扁鹊仓公列传》"}, {"t": "烦懑不乐。", "b": "清·张廷玉《明史》"}], "words": [{"w": "懑愤金怀", "t": "胸怀郁闷"}, {"w": "懑闷", "t": "烦闷"}, {"w": "懑烦", "t": "烦闷"}, {"w": "懑懑", "t": "烦闷的样子。"}]}, {"meaning": "气愤不平。", "cites": [{"t": "惟烦懑而盈匈。", "b": "《楚辞·哀时命》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6293wx','濡','1','rú','氵','17','','[{"pinyin": "rú", "defs": [{"meaning": "古水名。", "cites": [{"t": "濡,濡水,出涿郡故安,东入涞。", "b": "《说文》"}]}, {"meaning": "在河北省。"}, {"meaning": "尿。", "cites": [{"t": "病方今客肾濡,此所谓“肾痹”也。", "b": "《史记》"}]}, {"meaning": "儒士,学者。", "cites": [{"t": "海内称之曰濡术之宗。", "b": "《济阴太守孟郁修尧庙碑》"}, {"t": "少以濡术。", "b": "《尉卫卿衡方碑》"}]}, {"meaning": "假借为“堧”。空地。", "cites": [{"t": "自以城池道濡麦。", "b": "《鲁相史晨飨孔庙后碑》"}]}, {"meaning": "沾湿。", "cites": [{"t": "不濡其翼。", "b": "《诗·曹风·候人》"}, {"t": "春雨露既濡。", "b": "《礼记·祭义》"}, {"t": "濡濯弃于坎。", "b": "《礼记·丧大记》"}, {"t": "今客贤濡。", "b": "《史记·扁仓传》"}], "words": [{"w": "濡墨挥毫", "t": "用毛笔蘸墨写字或作画"}, {"w": "濡笔", "t": "沾墨于笔"}, {"w": "濡栉", "t": "沾湿梳篦"}, {"w": "濡染", "t": "沾染"}, {"w": "濡缕", "t": "沾湿一缕"}, {"w": "濡褐", "t": "沾湿马衣"}, {"w": "濡溺", "t": "沉浸,沉溺"}, {"w": "濡濡", "t": "湿润;沉湎"}, {"w": "濡渥", "t": "湿润"}, {"w": "濡浃", "t": "沾润"}, {"w": "濡沫", "t": "用唾沫来湿润"}, {"w": "濡沃", "t": "滋润"}, {"w": "濡如", "t": "雨露润滋"}, {"w": "濡化", "t": "滋润化育"}, {"w": "濡泽", "t": "沾、润。"}]}, {"meaning": "迟缓;滞留。", "cites": [{"t": "是何濡滞也。", "b": "《孟子》"}], "words": [{"w": "濡迟", "t": "迟滞;缓慢"}, {"w": "濡需", "t": "苟安一时"}, {"w": "濡迹", "t": "滞留。"}]}, {"meaning": "湿的。", "cites": [{"t": "人涂其体、被濡衣而走火者,左三千人,右三千人。", "b": "《韩非子》"}]}, {"meaning": "缓慢的。", "cites": [{"t": "云精无永滞,水碧岂惭濡?", "b": "南朝梁·江淹《郊外望秋答殷博士》"}]}, {"meaning": "柔顺。", "cites": [{"t": "羔裘如濡。", "b": "《诗·郑风·羔裘》"}, {"t": "以濡弱谦下为表。", "b": "《庄子·天下》"}], "words": [{"w": "濡忍", "t": "柔顺,容忍"}, {"w": "濡弱", "t": "柔弱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6294wx','濮','1','pú','氵','17','','[{"pinyin": "pú", "defs": [{"meaning": "古水名。", "cites": [{"t": "濮,濮水出东郡濮阳,南入钜野。", "b": "《说文》"}, {"t": "桑间濮上之音。", "b": "《礼记·乐记》"}, {"t": "钓于濮水。", "b": "《庄子·秋水》"}]}, {"meaning": "古州名 。隋开皇十六年(公年596年)改濮阳郡置,治所在今山东省鄄城北。辖境相当于今山东省鄄城、范县及河南省濮阳县南部地区。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6295wx','濞','1','bì','氵','17','','[{"pinyin": "bì", "defs": [{"meaning": "——漾濞县，中国云南省的一个县。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6296wx','濠','1','háo','氵','17','','[{"pinyin": "háo", "defs": [{"meaning": "水名 。在安徽省凤阳县东北,有二源:一为东濠水,一为西濠水。皆流入淮水。", "cites": [{"t": "游于濠梁之上。", "b": "《庄子·秋水》。司马注:“水名也。”"}], "words": [{"w": "濠上", "t": "濠水之滨"}, {"w": "濠梁", "t": "濠水上的桥梁。引申指逍遥闲游之地"}, {"w": "濠濮闲想", "t": "相传庄子与惠施优游濠梁之上,又庄子曾钓于濮水,拒绝楚王的聘请,因以濠濮比喻消遥闲居、清淡无为的思绪。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6297wx','濯','1','zhuó','氵','17','','[{"pinyin": "zhuó", "defs": [{"meaning": "(形声。从水,翟(dí)声。本义:洗)。"}, {"meaning": "同本义。", "cites": [{"t": "濯,洒也。", "b": "《广雅》"}, {"t": "视壶濯及豆笾。", "b": "《仪礼·特牲礼》。注:“溉也。”"}, {"t": "王乃淳濯飨醴。", "b": "《国语·周语》。注:“洗也。”"}, {"t": "沧浪之水清兮,可以濯吾缨。", "b": "《楚辞·渔父》"}, {"t": "可以濯罍。", "b": "《诗·大雅·泂酌》"}, {"t": "濯冠沐浴告祭酒,如此至宝存岂多?", "b": "韩愈《石鼓歌》"}, {"t": "濯清莲而不妖。(清莲,清净的水。妖:妖艳,妖媚。)", "b": "宋·周敦颐《爱莲说》"}], "words": [{"w": "濯缨", "t": "洗涤帽带。指避世隐居或清高自守"}, {"w": "濯磨", "t": "洗涤磨炼,以求上进"}, {"w": "濯足", "t": "本谓洗去脚污。后以濯足比喻清除世尘,保持高洁"}, {"w": "濯沐", "t": "洗涤。"}]}, {"meaning": "涤除罪恶。", "cites": [{"t": "今上位者,洒濯其心,壹以待人,轨度其信,可明征也。", "b": "《左传》"}]}, {"meaning": "淋;浇。", "cites": [{"t": "大雨之中,城上军士都濯得眼不能开,头不能仰。", "b": "《荡冠志》"}]}, {"meaning": "拔引。", "cites": [{"t": "以濯船为黄头郎。", "b": "《汉书·鄧通传》"}, {"t": "濯鹢牛首。", "b": "司马相如《上林赋》"}]}, {"meaning": "光明的样子。", "cites": [{"t": "钩膺濯濯。", "b": "《诗·大雅·崧高》"}], "words": [{"w": "濯秀", "t": "明净秀丽。"}]}, {"meaning": "盛大。", "cites": [{"t": "王公伊濯。", "b": "《诗·大雅·文王有声》"}, {"t": "颂声灵,赫而濯。", "b": "《清史稿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6298wx','蹇','1','jiǎn','足','17','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从足,寒省声。本义:跛足)。"}, {"meaning": "同本义。", "cites": [{"t": "蹇,跛也。", "b": "《说文》"}, {"t": "蹇膝伸不屈、易蹇、往蹇来连。", "b": "《素问·骨空论》"}, {"t": "驾蹇驴而无策兮。", "b": "《楚辞·谬谏》"}, {"t": "郤克偻,而鲁使蹇。", "b": "《史记·晋世家》"}, {"t": "策蹇驴,囊图书。", "b": "马中锡《中山狼传》"}, {"t": "红装而蹇者。", "b": "明·袁宏道《满井游记》"}], "words": [{"w": "蹇兔", "t": "不能急走的跛脚兔。比喻弱小者"}, {"w": "蹇驴", "t": "走不快的羸弱之驴"}, {"w": "蹇人上天", "t": "跛子登天。比喻不可能的事。"}]}, {"meaning": "艰阻,不顺利。", "cites": [{"t": "蹇侘傺而含戚。", "b": "《楚辞·九章·哀郢》"}], "words": [{"w": "蹇拙", "t": "艰险;不走运"}, {"w": "蹇蹇", "t": "艰难、不顺遂的样子"}, {"w": "蹇剥", "t": "艰困,比喻时运不好"}, {"w": "蹇步", "t": "行走艰难"}, {"w": "蹇连", "t": "艰难的样子。"}]}, {"meaning": "劣马或跛驴。", "cites": [{"t": "策蹇赴前程。", "b": "唐·孟浩然《唐城馆中早发寄杨使君》"}], "words": [{"w": "蹇味儿", "t": "驴子的别称;蠢驴"}, {"w": "蹇驴一鸣,荒鸡三号", "t": "天亮时。比喻事情见了分晓"}, {"w": "蹇驴", "t": "跛蹇驽弱的驴"}, {"w": "蹇蹄", "t": "劣马"}, {"w": "蹇瘠", "t": "瘦弱的驴马。"}]}, {"meaning": "骑驴。", "cites": [{"t": "红装而蹇者,亦时时有。", "b": "明·袁宏道《满井游记》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6299wx','謇','1','jiǎn','言','17','','[{"pinyin": "jiǎn", "defs": [{"meaning": "(形声。从言,寒省声。本义:口吃) 同本义。", "cites": [{"t": "言不通利谓之謇吃。", "b": "《通俗文》"}, {"t": "因謇而徐言。", "b": "李延寿《北史·李谐传》"}], "words": [{"w": "謇吃", "t": "言语不流利。"}]}, {"meaning": "直言不讳,正直。", "cites": [{"t": "外似謇正,内实谄谀。", "b": "《北史·徐纥传》"}], "words": [{"w": "謇正", "t": "严肃正直"}, {"w": "謇直", "t": "刚正耿直"}, {"w": "謇謇", "t": "忠贞直言的样子;正直的言谈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6300wx','邃','1','suì','辶','17','','[{"pinyin": "suì", "defs": [{"meaning": "(形声。从穴。遂声。“穴”是汉字部首之一。从“穴”的字多与洞穴有关。本义:深远)。"}, {"meaning": "同本义。", "cites": [{"t": "邃,深远也。", "b": "《说文》"}, {"t": "邃,深也。", "b": "《小尔雅》"}, {"t": "闺中既邃远兮。", "b": "《离骚》"}, {"t": "高堂邃宇。", "b": "《楚辞·招魂》"}, {"t": "坐潭上,四面竹树环合,寂寥无人,凄神寒骨,悄怆幽邃。", "b": "唐·柳宗元《至小丘西小石潭记》"}], "words": [{"w": "邃户", "t": "幽深的门户"}, {"w": "邃密", "t": "深宫"}, {"w": "邃宇", "t": "深广的房子"}, {"w": "邃室", "t": "幽深的房间"}, {"w": "邃阁", "t": "深幽的楼阁"}, {"w": "邃殿", "t": "深广的殿堂"}, {"w": "邃路", "t": "漫长的道路"}, {"w": "邃远", "t": "深远"}, {"w": "邃屋", "t": "深幽的房屋"}, {"w": "邃房", "t": "深广的房舍。"}]}, {"meaning": "遥远。", "cites": [{"t": "邃古之前,坤枢未转,英伦诸岛乃属冰天雪海之区。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "邃世", "t": "远世"}, {"w": "邃古", "t": "远古"}, {"w": "邃初", "t": "远古;始初。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6301wx','襁','1','qiǎng','衤','17','','[{"pinyin": "qiǎng", "defs": [{"meaning": "(形声。从衣,强声。本义:婴儿的被子或布幅)。"}, {"meaning": "同本义。", "cites": [{"t": "襁,负儿衣也。", "b": "《说文》"}, {"t": "曾孙虽在襁褓。", "b": "《汉书·宣帝纪》"}, {"t": "夫如是,则四方之民襁负其子而至矣。", "b": "《论语》"}], "words": [{"w": "襁抱", "t": "同襁褓,背婴儿用的布幅或系带"}, {"w": "襁负", "t": "以布幅包裹幼儿于背上"}, {"w": "襁褓物", "t": "指婴儿。"}]}, {"meaning": "古代一种捕捉老虎的器械。", "cites": [{"t": "又有设襁胶布制虎法。", "b": "方以智《物理小识》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6302wx','檗','1','bò','木','17','','[{"pinyin": "bò", "defs": [{"meaning": "木名。即黄檗。也称“黄柏” 。芸香科,落叶乔木,羽状复叶,开黄绿色小花,木材坚硬,茎可制黄色染料,树皮入药。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6303wx','擘','1','bò','手','17','','[{"pinyin": "bò", "defs": [{"meaning": "(形声。从手,辟声。本义:大拇指) 同本义。", "cites": [{"t": "于齐国之士,吾必以仲子为巨擘焉。", "b": "《孟子·滕文公下》"}], "words": [{"w": "擘指", "t": "大拇指。"}]}, {"meaning": "分开;剖裂。", "cites": [{"t": "乃擘青天而飞去。", "b": "唐·李朝威《柳毅传》"}], "words": [{"w": "擘开", "t": "裂开,切开"}, {"w": "擘窠书", "t": "大字的通称口擘窠,原指篆刻印章时加以分格,以便匀排"}, {"w": "擘析", "t": "分析,剖析。"}]}, {"meaning": "拨弹琴弦的指法。用拇指抬弦称擘。引申为弹奏。", "cites": [{"t": "若论弹琴擘阮,前后绝伦。", "b": "董解元《西厢记》"}], "words": [{"w": "擘阮", "t": "谓弹琴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6304wx','孺','1','rú','子','17','','[{"pinyin": "rú", "defs": [{"meaning": "(形声。从子,需声。子,古代指小孩子,不分性别都称子。本义:小孩子,尤指幼儿)。"}, {"meaning": "同本义。", "cites": [{"t": "孺,乳子也。", "b": "《说文》"}, {"t": "孺子早寝晏起。", "b": "《礼记·内则》"}, {"t": "今人乍见孺子。", "b": "《孟子》"}], "words": [{"w": "孺童", "t": "小孩,幼童"}, {"w": "孺弱", "t": "幼弱的孩子"}, {"w": "孺慕", "t": "幼童爱慕父母之情"}, {"w": "孺齿", "t": "幼儿,幼童"}, {"w": "孺儿", "t": "幼儿"}, {"w": "孺子欢", "t": "为使父母欢心,故意装出孩子般的神态动作"}, {"w": "孺月", "t": "分娩后的第一个月"}, {"w": "孺齿", "t": "幼儿。"}]}, {"meaning": "指亲属。", "cites": [{"t": "孺,属也。", "b": "《尔雅》。李注:“骨肉相亲属也。”"}], "words": [{"w": "孺泣", "t": "对父母的哀悼哭泣"}, {"w": "孺止", "t": "敬仰。"}]}, {"meaning": "幼稚,年小。", "cites": [{"t": "公将不利于孺子。", "b": "《书·金縢》。传:“稚也。”"}], "words": [{"w": "孺婴", "t": "孺褓,孺蒙。幼小"}, {"w": "孺年", "t": "幼年,年龄幼小。"}]}, {"meaning": "亲睦。", "cites": [{"t": "和乐且孺。", "b": "《诗·小雅·常棣》"}], "words": [{"w": "孺慕", "t": ""}]}, {"meaning": "生育。", "cites": [{"t": "孺,生也。", "b": "《广雅》"}, {"t": "乌鹊孺。", "b": "《庄子·天运》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6305wx','隳','1','huī','阝','17','','[{"pinyin": "huī", "defs": [{"meaning": "毁坏城墙或山头;毁坏。", "cites": [{"t": "隳名城。", "b": "汉·贾谊《过秦论》"}, {"t": "一夫作难而七庙隳。", "b": ""}], "words": [{"w": "隳堕", "t": "毁坏;动摇"}, {"w": "隳突", "t": "骚扰"}, {"w": "隳圮", "t": "倾坍;倒塌"}, {"w": "隳名", "t": "隐姓埋名。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6306wx','嬷','1','mó','女','17','','[{"pinyin": "mó", "defs": [{"meaning": "老妇。", "cites": [{"t": "这店家老嬷装得花簇簇地,将个盒盘盛了礼物,双手捧着,一径到妙观肆中来。", "b": "《二刻拍案惊奇》"}]}, {"meaning": "母亲。", "cites": [{"t": "后来我掌起门户,他嬷便死了。", "b": "《花月痕》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6307wx','蟊','1','máo','虫','17','','[{"pinyin": "máo", "defs": [{"meaning": "(形声)。"}, {"meaning": "同本义。", "cites": [{"t": "蟊贼蟊疾。", "b": "《诗·大雅·瞻卬》"}], "words": [{"w": "蟊螟", "t": "危害庄稼的两种害虫"}, {"w": "蟊疾", "t": "蟊虫为害。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6308wx','鹬','1','yù','鸟','17','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。从鸟,矞(yù)声。本义:水鸟鹬)。"}, {"meaning": "同本义。", "cites": [{"t": "鹬,翠鸟也。知天将雨。", "b": "《说文》"}, {"t": "知天文者冠鹬。", "b": "《礼记》"}, {"t": "鹬如鹑,色苍嘴长,在泥涂间鹬鹬声,村民云田鸡所化,亦鹌鹑类也。苏秦所谓鹬蚌相持者,即此。", "b": "《本草纲目》"}, {"t": "蚌方出曝,而鹬啄其肉。", "b": "《战国策》"}], "words": [{"w": "鹬鹬", "t": "水鹬鸟的叫声"}, {"w": "鹬冠", "t": "鹬毛冠。古代为天文者之冠。"}]}, {"meaning": "鹬科多数种类鸟的通称 。若干狩猎禽(沙锥属Capella)之一,与丘鹬近似,但较小,有十分细长的嘴,用它插入泥中搜寻蠕虫和其他食物,上体通常杂黑褐色;皮黄色和栗色,尾和体侧具有横斑。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6309wx','鍪','1','móu','金','17','','[{"pinyin": "móu", "defs": [{"meaning": "古代炊器,青铜制,圆底敛口,反唇。流行于汉代。", "cites": [{"t": "鍪,釜也。", "b": "《广雅》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6310wx','鏊','1','ào','金','18','','[{"pinyin": "ào", "defs": [{"meaning": "烙饼用的平底铁锅,俗称鏊子或鏊盘。", "cites": [{"t": "范全在那里叫苦叫屈,如热鏊上蚂蚁,没走一头处。", "b": "《水浒传》"}], "words": [{"w": "鏊砚", "t": "鏊形的砚台。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6311wx','鳌','1','áo','鱼','18','','[{"pinyin": "áo", "defs": [{"meaning": "传说中海里的大龟或大鳖。", "cites": [{"t": "于是女娲炼五色石以补苍天,断鳌足以立四极。", "b": "《淮南子·览里》"}], "words": [{"w": "鳌里夺尊", "t": "做杰出人物中的佼佼者。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6312wx','鬈','1','quán','髟','18','','[{"pinyin": "quán", "defs": [{"meaning": "头发好。引申为美好。", "cites": [{"t": "鬈,发好也。", "b": "《说文》"}, {"t": "卢重环,其人美且鬈。", "b": "《诗·齐风·卢令》。毛传:“鬈,好貌。”"}]}, {"meaning": "卷曲的毛。", "cites": [{"t": "百工商贾不得服长鬈貂。", "b": "《管子》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6313wx','鬃','1','zōng','髟','18','','[{"pinyin": "zōng", "defs": [{"meaning": "某些哺乳动物颈部周围生长的又长又密的毛。", "cites": [{"t": "鬃白似披梁苑雪,颈肥如扑杏园花。", "b": "韦庄《代书寄马诗》"}], "words": [{"w": "鬃帽", "t": "用马、猪等颈毛所制的帽子"}, {"w": "马鬃;猪鬃", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6314wx','瞽','1','gǔ','目','18','','[{"pinyin": "gǔ", "defs": [{"meaning": "(形声。从目,鼓声。本义:瞎眼)。"}, {"meaning": "同本义(虽瞎但有眼珠)。", "cites": [{"t": "瞽,目但有朕也。", "b": "《说文》"}, {"t": "瞽子。", "b": "《书·尧典》。传:“无目曰瞽。”"}, {"t": "瞽者仰视而不见星。", "b": "《荀子·解蔽》"}, {"t": "将衒外以惑愚瞽也。?", "b": "明·刘基《卖柑者言》"}], "words": [{"w": "瞽目", "t": "眼睛瞎;盲人"}, {"w": "瞽者", "t": "眼睛失明的人"}, {"w": "瞽旷", "t": "指师旷"}, {"w": "瞽目先生", "t": "说书盲人。"}]}, {"meaning": "没有识别力。", "cites": [{"t": "未见颜色而言,谡之瞽。", "b": "《论语·季氏》"}, {"t": "是犹蟪蛄不识春秋,朝菌不知晦朔遽以不变名之,真瞽说也。", "b": "[英]赫胥黎著、严复译《天演论》"}], "words": [{"w": "瞽说", "t": "瞎说"}, {"w": "瞽言", "t": ""}]}, {"meaning": "古代乐师。古代以目盲者为乐官,故为乐官的代称。", "cites": [{"t": "瞽奏鼓,啬夫驰,庶人走。", "b": "《书·胤征》"}, {"t": "瞽者无以与平文章之观。", "b": "《庄子·逍遥游》"}]}, {"meaning": "乐器。圆柱形中空,两面蒙皮,击之发声。", "cites": [{"t": "诏来瞽皋舞。", "b": "《周礼·春官·乐师》"}]}]}]','jingmo-wenyan');
