('6315wx','鞯','1','jiān','革','18','','[{"pinyin": "jiān", "defs": [{"meaning": "衬托马鞍的垫子。", "cites": [{"t": "鞯,马鞴具也。", "b": "《说文新附》"}, {"t": "东市买骏马,西市买鞍鞯。", "b": "古乐府《木兰诗》"}], "words": [{"w": "鞍鞯", "t": "衬托马鞍的垫子"}, {"w": "鞯面", "t": "鞍鞯的面料层"}, {"w": "鞯勒", "t": "鞍鞯与笼头"}, {"w": "鞯汗", "t": "鞍鞯。"}]}, {"meaning": "鞍。", "cites": [{"t": "东门人物乱如麻,想见新鞯照路华。", "b": "宋·王安石《次杨乐道韵》"}]}]}]','jingmo-wenyan');
