('6321wx','藠','1','jiào','艹','18','','[{"pinyin": "jiào", "defs": [{"meaning": "藠头,藠子。“即薤”。百合科。多年生草本。鳞茎可作酱菜。", "cites": [{"t": "藠,俗呼薤曰藠子,以薤根白如藠也。", "b": "《正字通》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6322wx','藩','1','fān','艹','18','','[{"pinyin": "fān", "defs": [{"meaning": "(形声。从艸,潘声。本义:篱笆)。"}, {"meaning": "同本义。", "cites": [{"t": "藩,屏也。", "b": "《说文》"}, {"t": "藩,篱也。", "b": "《广雅·释室》"}, {"t": "羝羊触藩。", "b": "《易·大壮卦》"}, {"t": "吴人藩卫侯之舍。", "b": "《左传·哀公十二年》"}, {"t": "而青蝇点素,同兹在藩。", "b": "《后汉书·杨震传》"}], "words": [{"w": "藩屏", "t": "藩篱屏障"}, {"w": "藩柴", "t": "篱笆"}, {"w": "藩架", "t": "篱芭"}, {"w": "藩落", "t": "篱落,篱芭。"}]}, {"meaning": "屏障。", "cites": [{"t": "国有故,则藩塞阻路,而止行者。", "b": "《周礼·夏官》"}, {"t": "乃使蒙恬北筑长城而守藩篱。", "b": "贾谊《过秦论》"}]}, {"meaning": "藩国的君主。", "cites": [{"t": "东平王苍罢归藩。", "b": "《后汉书·明帝纪》"}], "words": [{"w": "藩邸(藩王(亲王)的宅第", "t": ""}, {"w": "藩储", "t": "储君之位。"}]}, {"meaning": "四周有屏围的车叫藩车。简称“藩”。", "cites": [{"t": "以藩载栾盈及其士。", "b": "《左传·襄公十二年》"}]}, {"meaning": "境域,涯际。", "cites": [{"t": "乃使蒙恬北筑长城而守藩篱。", "b": "汉·贾谊《过秦论》"}], "words": [{"w": "藩服", "t": "旧指离开京城最远的边远地区"}, {"w": "藩篱", "t": "指边疆、边界。"}]}, {"meaning": "封建王朝分封的土地。", "cites": [{"t": "天地易兮日月翻,弃万乘兮退守藩。", "b": "《三刻拍案惊奇》"}]}, {"meaning": "护卫;捍卫。", "cites": [{"t": "舍诸边境,使卫藩焉!", "b": "《左传·哀公十六年》"}], "words": [{"w": "藩辅", "t": "捍卫;辅佐"}, {"w": "藩翼", "t": "捍卫"}, {"w": "藩镇", "t": "屏藩镇守。"}]}, {"meaning": "遮蔽;遮掩。", "cites": [{"t": "以相藩饰。", "b": "《荀子·荣辱》"}], "words": [{"w": "藩车", "t": "有帷遮蔽的车子"}, {"w": "藩蔽", "t": "古代用施漆的苇席制成的车蔽。"}]}, {"meaning": "用篱芭等围起来。", "cites": [{"t": "吴人藩卫侯之舍。", "b": "《左传·哀公十二年》"}], "words": [{"w": "藩盾", "t": "用大盾临时构筑的屏藩。"}]}]}]','jingmo-wenyan');
