INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6324wx','蹙','1','cù','足','18','','[{"pinyin": "cù", "defs": [{"meaning": "(形声。从足,戚声。本义:紧迫,急促)。"}, {"meaning": "同本义。", "cites": [{"t": "政事愈蹙。", "b": "《诗·小雅·小明》"}], "words": [{"w": "蹙变", "t": "急速变化。"}]}, {"meaning": "困窘。", "cites": [{"t": "自吾氏三世居是乡,积于今六十岁矣,而乡邻之生日蹙。", "b": "柳宗元《捕蛇者说》"}], "words": [{"w": "蹙迫", "t": "困窘,窘迫"}, {"w": "蹙境", "t": "边境防务窘迫。"}]}, {"meaning": "局促不安的样子。", "cites": [{"t": "蹙然衣粗食恶。", "b": "《荀子》"}], "words": [{"w": "蹙促", "t": "局促不安的样子。"}]}, {"meaning": "聚拢;皱缩。", "cites": [{"t": "举疾首蹙额而相告。", "b": "《孟子》"}], "words": [{"w": "蹙恨", "t": "皱起眉头表示怨恨"}, {"w": "蹙沓", "t": "形容多而密集的样子。"}]}, {"meaning": "逼迫;追逼。", "cites": [{"t": "蹙也百里。", "b": "《诗·大雅·召旻》"}], "words": [{"w": "蹙迫", "t": "逼迫"}, {"w": "蹙促", "t": "逼迫"}, {"w": "蹙击", "t": "迫击;追击。"}]}, {"meaning": "接近;迫近。", "cites": [{"t": "今也日蹙国百里。", "b": "《诗·大雅·召旻》"}], "words": [{"w": "蹙迫", "t": "逼近。"}]}, {"meaning": "缩小;减削。", "words": [{"w": "蹙頞", "t": "缩鼻哭泣"}, {"w": "蹙土", "t": "蹙地。损失国土"}, {"w": "蹙动", "t": "皱缩。"}]}, {"meaning": "踢;踏。", "cites": [{"t": "以足蹙路马刍,有诛。", "b": "《礼记·曲礼上》"}, {"t": "一蹙自造青云,何至于驽马争路。", "b": "《南史·刘穆之传》"}, {"t": "扬鞭一蹙破霜蹄,万骑如风不能及。", "b": "苏轼《申王画马图》"}], "words": [{"w": "蹙鞠", "t": "踢球"}, {"w": "蹙踏", "t": "踢;踩踏。"}]}]}]','jingmo-wenyan');
