INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6326wx','燹','1','xiǎn','火','18','','[{"pinyin": "xiǎn", "defs": [{"meaning": "野火。", "cites": [{"t": "燹,野火也。", "b": "《玉篇》"}], "words": [{"w": "兵燹", "t": "因战争所遭受的焚烧破坏。"}]}, {"meaning": "后专指兵火、战火。", "cites": [{"t": "先圣旧宅,近日亦遭兵燹之厄,可叹也夫!", "b": "宋·庄季裕《鸡肋篇》"}, {"t": "历世既久,悉毁于兵燹;间有遗编,多为世俗秘而藏之。", "b": "宋·张存《重刊"}, {"t": "埤雅序》", "b": ""}, {"t": "久闻离乱今始见,烟火高低变烽燹。", "b": "明·高启《次韵杨孟戴早春见寄》"}]}, {"meaning": "焚烧。", "cites": [{"t": "及闻蕙棺被燹,顿违共穴之情。", "b": "《红楼梦》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6327wx','餮','1','tiè','飠','18','','[{"pinyin": "tiè", "defs": [{"meaning": "贪,贪食。", "cites": [{"t": "斯民乃食餮。", "b": "苏舜钦《悲二字联句》"}, {"t": "天下之民以比三凶,谓之饕餮。", "b": "《左传·文公十八年》。注:“贪财为饕,贪食为餮。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6328wx','瞿','1','qú','目','18','','[{"pinyin": "qú", "defs": [{"meaning": "(会意兼形声。《说文》:“从隹。”隹(zhuī),短尾鸟的总称)。本义:惊视的样子 同本义。", "cites": [{"t": "瞿,隼之视也。", "b": "《说文》"}, {"t": "见似目瞿,闻名心瞿。", "b": "《礼记·杂记》"}, {"t": "瞿大视貌。", "b": "《字林》"}, {"t": "公瞿然失席曰。", "b": "《礼记·檀弓》"}, {"t": "子綦瞿然。", "b": "《庄子·徐无鬼》"}]}, {"meaning": "戟一类的兵器。", "cites": [{"t": "一人冕执瞿,立于西垂。", "b": "《书·顾命》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6329wx','曛','1','xūn','日','18','','[{"pinyin": "xūn", "defs": [{"meaning": "(形声。从日,熏声。本义:日落时的余光)。"}, {"meaning": "同本义。", "cites": [{"t": "一带斜曛归路,晚风料峭怯寒衣。", "b": "清·王宾《江城子·清明》"}], "words": [{"w": "曛曛荡荡", "t": "喻晚霞蔚为壮观"}, {"w": "曛日", "t": "夕阳。"}]}, {"meaning": "傍晚;黄昏。", "cites": [{"t": "一枕高眠到日曛。", "b": "清·张实居《山中即景》"}]}, {"meaning": "曛旭(早晚,朝夕);曛黄(曛暮。黄昏);曛晓(早晚,日夜);曛烟(黄昏时的烟霭)。"}, {"meaning": "昏暗。", "cites": [{"t": "天地曛黑,仰视又无纤云。", "b": "《类说》"}], "words": [{"w": "曛昧", "t": "曛晦。昏暗"}, {"w": "曛黑", "t": "日暮天黑。"}]}, {"meaning": "赤黄色。", "cites": [{"t": "少阴所至为高明焰为曛。", "b": "《素问》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6330wx','颢','1','hào','页','18','','[{"pinyin": "hào", "defs": [{"meaning": "(会意。从景,从页(xié),头。段玉裁《说文解字注》:“景者,日光也。日光白,从景页,言白首也。”本义:头白的样子)。"}, {"meaning": "同本义。因指白头人。引申为白色。", "cites": [{"t": "颢,白貌。", "b": "《说文》"}, {"t": "天白颢颢。", "b": "《楚辞·大招》。洪注:“颢,白貌。”"}], "words": [{"w": "颢露", "t": "白露"}, {"w": "颢魄", "t": "洁白的月色"}, {"w": "颢气", "t": "清新洁白之气。"}]}, {"meaning": "浩大。", "cites": [{"t": "颢,大也。", "b": "《汉书·叙传》注"}], "words": [{"w": "颢颢", "t": "浩大,博大的样子"}, {"w": "颢然", "t": "盛大的样子"}, {"w": "颢汗", "t": "广阔浩大的样子。"}]}, {"meaning": "本指西天,泛指天空。", "cites": [{"t": "超忽荒,", "b": "《汉书·叙传上》"}, {"t": "西方曰颢天。", "b": "《吕氏春秋·有始》。注:“金色白。故曰颢天。又为昊。”"}, {"t": "肇自颢穹生民。", "b": "《汉书·司马相如传》"}], "words": [{"w": "颢天", "t": "西天,西方的天,同昊天"}, {"w": "颢穹", "t": "指天。也作昊穹"}, {"w": "颢苍", "t": "指天。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6331wx','曜','1','yào','日','18','','[{"pinyin": "yào", "defs": [{"meaning": "(形声。从日,翟(dí)声。本义:日光)。"}, {"meaning": "同本义。", "cites": [{"t": "曜,耀也,光明照耀也。", "b": "《释名·释天》"}, {"t": "日出有曜。", "b": "《诗·桧风·羔裘》"}], "words": [{"w": "光曜", "t": ""}]}, {"meaning": "照耀。", "cites": [{"t": "扬晖吐火,曜野蔽泽。", "b": "王粲《羽猎赋》"}], "words": [{"w": "曜煜", "t": "辉耀"}, {"w": "曜仪", "t": "闪耀;光辉的仪容。"}]}, {"meaning": "炫耀;显示。", "cites": [{"t": "若无越,则吾何以春秋耀吾军士?", "b": "《国语》"}], "words": [{"w": "曜甲", "t": "炫耀武力"}, {"w": "曜名", "t": "显耀名声"}, {"w": "曜兵", "t": "曜武。炫耀武力"}, {"w": "曜威", "t": "整饬军旅,炫耀武力。"}]}]}]','jingmo-wenyan');
