('6333wx','蹚','1','tāng','足','18','','[{"pinyin": "tāng", "defs": [{"meaning": "引申为探路。", "cites": [{"t": "等冈野调上伪军去蹚路,重新组织好队伍,继续前进时,提幼虎早已转到前头一个小山梁上了。", "b": "李荣德《大雁山》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6334wx','鹭','1','lù','鸟','18','','[{"pinyin": "lù", "defs": [{"meaning": "鹭科的各种涉禽 ,颈和腿细长,生长在水域附近,以尖锐的嘴捕食水生动物,通常成群营巢于林间", "cites": [{"t": "寀寮雍雍,鸿仪鹭序。", "b": "《禽经》。张华注:“鹭,白鹭也,小不踰大,飞有次序,百官缙绅之象。”"}], "words": [{"w": "鹭羽", "t": "鹭的羽毛。供舞者持用的舞具"}, {"w": "鹭涛", "t": "雪白的波涛。形容白浪之翻滚腾涌如鹭的飞翔"}, {"w": "鹭浮鹤行", "t": "形容脚步轻巧。比喻朝班"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6335wx','蟛','1','péng','虫','18','','[{"pinyin": "péng", "defs": [{"meaning": "螃蟹的一种，身体小，常见的头胸甲略呈方形。螯足无毛，淡红色，步足有毛。穴居海边或江河泥岸，对农作物有害。"}]}]','jingmo-wenyan');
