INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6337wx','蟠','1','pán','虫','18','','[{"pinyin": "pán", "defs": [{"meaning": "盘曲;盘结", "words": [{"w": "蟠木", "t": "指盘曲而难以为器的树木"}, {"w": "蟠龙", "t": "盘旋环绕的龙"}, {"w": "蟠虬", "t": "盘曲的虬龙"}, {"w": "蟠蛇", "t": "盘曲的蛇"}, {"w": "蟠幽", "t": "盘曲幽深"}, {"w": "蟠根", "t": "盘曲的根"}, {"w": "蟠旋", "t": "盘曲回旋"}, {"w": "蟠结", "t": "盘曲纠结"}]}, {"meaning": "遍及;充满", "words": [{"w": "蟠满", "t": "遍及"}, {"w": "充满)", "t": ""}, {"w": "蟠极", "t": "遍及"}, {"w": "蟠泊", "t": "充满"}, {"w": "布满)", "t": ""}, {"w": "蟠胸", "t": "满腹"}, {"w": "蟠礴", "t": "广大无边的样子"}]}]}]','jingmo-wenyan');
