INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6339wx','鹮','1','huán','鸟','18','','[{"pinyin": "huán", "defs": [{"meaning": "构成鹮科的几种与鹭有亲缘关系的涉禽的通称 ,产于东西两半球的温暖地带,以水生动物及两栖动物为食,特征是有一个细长而向下弯的喙。中国常见的有白鹮,少见的有朱鹮。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6340wx','黠','1','xiá','黑','18','','[{"pinyin": "xiá", "defs": [{"meaning": "(形色。从黑,吉声。本义:坚黑色)。"}, {"meaning": "坚。", "cites": [{"t": "黠,坚黑也。", "b": "《说文》"}]}, {"meaning": "狡猾、含有内心险恶、耍弄小聪明来伪装之意。", "cites": [{"t": "以尤桀黠,皆斩之。", "b": "《汉书》"}, {"t": "吏黠不能禁。", "b": "《后汉书·明帝纪》"}, {"t": "黠民共为冠。", "b": "《汉书·匈奴传》"}, {"t": "狼亦黠矣。", "b": "《聊斋志异·狼三则》"}], "words": [{"w": "黠灵", "t": "狡猾"}, {"w": "黠鼠;狡黠的敌人;黠奴", "t": "狡猾的奴婢。"}]}, {"meaning": "聪慧;机伶。", "cites": [{"t": "驱我令去,小黠大痴。", "b": "韩愈《送穷文》"}], "words": [{"w": "黠灵", "t": "聪明"}, {"w": "黠儿", "t": "聪慧的小儿。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6341wx','黟','1','yī','黑','18','','[{"pinyin": "yī", "defs": [{"meaning": "黑木。", "cites": [{"t": "乌木出波斯国。", "b": "《古今注》"}]}, {"meaning": "县名 。在安徽省。"}, {"meaning": "乌黑。", "cites": [{"t": "宜其渥然丹者为槁木,黟然黑者为星星。", "b": "宋·欧阳修《秋声赋》"}], "words": [{"w": "黟然", "t": "颜色乌黑的样子"}, {"w": "黟黑", "t": "乌黑的样子"}, {"w": "黟黟", "t": "形容黑发黑黟黟的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
