INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6343wx','髂','1','qià','骨','18','','[{"pinyin": "qià", "defs": [{"meaning": "髂骨 。骨盆两侧各三块骨中后上方的一块,在人体内,它与坐骨和耻骨连接形成髋臼的一部分,上部宽大,下部狭窄。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6344wx','镬','1','huò','钅','18','','[{"pinyin": "huò", "defs": [{"meaning": "形如大盆,用以煮食物的铁器。", "cites": [{"t": "羊镬豕镬。", "b": "《仪礼·少牢礼》"}, {"t": "省牲镬。", "b": "《周礼·大宗伯》。注:“烹饪器也。”"}, {"t": "掌共鼎镬。", "b": "《周礼·亨人》。注:“所以煮肉及鱼腊之器。”"}, {"t": "尝一脔肉,知一镬之味。", "b": "《淮南子·说山》。注:“无足曰镬。”"}, {"t": "一镬之味。", "b": "《吕氏春秋·察今》"}], "words": [{"w": "镬煮", "t": "放在镬里烹煮。"}]}, {"meaning": "指烹人的刑具。", "cites": [{"t": "有凿颠抽胁镬亨之刑。", "b": "《汉书·刑法志》"}], "words": [{"w": "镬亨", "t": "古代的一种酷刑。把人放在镬中烹煮。亨即烹。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6345wx','镭','1','léi','钅','18','','[{"pinyin": "léi", "defs": [{"meaning": "为碱土族的一个强放射性的金属元素,以化合状态极少量地存在于沥青铀矿、钾钒铀矿以及其他铀矿中,质量数为226的同位素 ——元素符号Ra。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6346wx','镯','1','zhuó','钅','18','','[{"pinyin": "zhuó", "defs": [{"meaning": "钟状的铃,古代军中乐器。", "cites": [{"t": "镯,钲也。从金,蜀声。", "b": "《说文》"}, {"t": "司马执两镯,形如小钟。", "b": "《军法》"}, {"t": "以金镯节鼓。", "b": "《周礼·鼓人》"}]}, {"meaning": "镯子。", "cites": [{"t": "今人名臂环为镯。", "b": "明·陆容《菽园杂记》"}], "words": [{"w": "镯头", "t": "即镯子"}, {"w": "玉镯;银镯", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6347wx','馥','1','fù','香','18','','[{"pinyin": "fù", "defs": [{"meaning": "(形声。从香,复声。本义:香,香气) 同本义。", "cites": [{"t": "秋露重,真珠落袖沾余馥。", "b": "宋·苏轼《千秋岁》"}], "words": [{"w": "馥馥", "t": "形容香气很浓。"}]}, {"meaning": "香气散发。", "cites": [{"t": "风软景和煦,异香馥林塘。", "b": "唐·申欢《兜玄国怀归诗》"}, {"t": "雍容草罢明堂诏,留取天香馥寿宴。", "b": "宋·黄定《鹧鸪天》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6348wx','簟','1','diàn','竹','18','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从竹,覃声。本义:竹席)。"}, {"meaning": "也指用芦苇编制的席。", "cites": [{"t": "君以簟席,大夫以蒲席。", "b": "《礼记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6349wx','簪','1','zān','日','18','','[{"pinyin": "zān", "defs": [{"meaning": "(形声。从竹,賛(zǎn)声。古文字形,象针形头饰形。本义:簪子。古人用来插定发髻或连冠于发的一种长针) 同本义。", "cites": [{"t": "周主亡玉簪,令吏求之,三日不能得也。", "b": "《韩非子》"}, {"t": "白头搔更短,浑欲不胜簪。", "b": "杜甫《春望》"}], "words": [{"w": "簪冕", "t": "冠簪与冕服"}, {"w": "簪绂", "t": "簪,冠簪;绂,丝制的帽带"}, {"w": "簪裾", "t": "古时显贵所穿着的服饰"}, {"w": "簪缨缙绅", "t": "比喻仕宦之人。"}]}, {"meaning": "插戴在头上。", "cites": [{"t": "西门豹簪笔磬折,向河立待良久。", "b": "《史记·滑稽列传》"}, {"t": "乃簪一花。", "b": "宋·司马光《训俭示康》"}], "words": [{"w": "簪朵", "t": "犹簪花,戴花"}, {"w": "簪挂", "t": "簪花挂彩"}, {"w": "簪星曳月", "t": "形容佩带光彩耀眼"}, {"w": "簪冠", "t": "插簪于冠"}, {"w": "簪花", "t": "戴花"}, {"w": "簪菊", "t": "古人习俗,于重阳节插戴菊花以避邪延年。"}]}, {"meaning": "连缀。", "cites": [{"t": "以爵弁服簪裳于衣左。", "b": "《仪礼·士丧礼》"}], "words": [{"w": "簪合", "t": "折簪重合。指女子丧夫后再遇意中人而结为夫妇"}, {"w": "簪蒿席草", "t": "以蒿作簪,以草为席。形容生活艰苦。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6350wx','鼬','1','yòu','鼠','18','','[{"pinyin": "yòu", "defs": [{"meaning": "鼬科部分种类动物的通称 ,躯体细瘦的各种鼬属(Mustela)是小型食肉动物,与水貂和鸡貂有亲缘关系,极活跃,勇猛且嗜血,以幼禽和幼兽,尤其是小鼠、家鼠和其他害兽为食,大多数有赤褐色的毛皮,躯体下半部呈白色或黄色。", "cites": [{"t": "鼬,处处有之。状似鼠而身长尾大,黄色带赤,其气极臊臭。", "b": "《本草纲目》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6351wx','雠','1','chóu','隹','18','','[{"pinyin": "chóu", "defs": [{"meaning": "(形声。从言。雔(chóu)声。本义:应答)。"}, {"meaning": "同本义。", "cites": [{"t": "雠,犹应也。", "b": "《说文》。按,以言相当也。"}, {"t": "雠,对也。", "b": "《三苍》"}, {"t": "无言不雠。", "b": "《诗·大雅·抑》"}, {"t": "忧必雠也。", "b": "《左传·僖公五年》"}, {"t": "著之盘盂,属之雠柞。", "b": "《战国策·赵策一》"}], "words": [{"w": "雠祚", "t": "在筵席上宾主互相敬酒。"}]}, {"meaning": "(为仇的异体字)。"}, {"meaning": "仇恨;仇怨。", "cites": [{"t": "怨偶曰雠。", "b": "《一切经音义》引》《三苍》"}, {"t": "又众兆之所雠。", "b": "《楚辞·惜诵》。注:“大怨曰雠。”"}], "words": [{"w": "雠怨", "t": "仇恨,憎怨"}, {"w": "雠隙", "t": "猜忌、仇恨。"}]}, {"meaning": "仇敌。", "cites": [{"t": "反以我为雠。", "b": "《诗·邶风·谷风》"}, {"t": "祁大夫外举不弃雠,内举不失亲。", "b": "《左传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6352wx','艟','1','chōng','舟','18','','[{"pinyin": "chōng", "defs": [{"meaning": "一种船的船名", "words": [{"w": "艟舻", "t": "战船"}, {"w": "艨艟", "t": "古代战船"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6353wx','鳎','1','tǎ','鱼','18','','[{"pinyin": "tǎ", "defs": [{"meaning": "鳎鱼 。鳎科(Soleidae),嘴小,鼻吻多少突出嘴外,腹鳍缩小或退化,胸鳍和尾鳍也时常如此,鳃孔很小,两只小眼位置很近,这一科包括几种最美味的鱼(如欧洲产的鳎Solea solea),但另外也有一些体形太小、无经济价值的种类。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6354wx','鳏','1','guān','鱼','18','','[{"pinyin": "guān", "defs": [{"meaning": "(形声。从鱼。本义:一种大鱼)。"}, {"meaning": "鱼名,即鲩鲲。又名鳡鱼。", "cites": [{"t": "卫人钓于河,得鳏鱼焉,其大盈车。", "b": "《孔丛子三抗志》"}]}, {"meaning": "死了妻子又未再结婚的男人。", "cites": [{"t": "有鳏在下,曰虞舜。", "b": "《书·尧典》"}, {"t": "老而无妻曰鳏。", "b": "《孟子·梁惠王》"}, {"t": "江子我瑞友知经明道,驰誉中外。后尽弃旧业,鳏居孑然。", "b": "宋·王明清《挥尘录》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6355wx','鳐','1','yáo','鱼','18','','[{"pinyin": "yáo", "defs": [{"meaning": "鳐鱼 鳐科中鳐属(Raja)和近缘各属的任一种鱼。胸鳍高度发达使鱼体呈菱形,被广泛食用,如:灰鳐、猬鳐和棘背鳐。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6356wx','癞','1','lài','疒','18','','[{"pinyin": "lài", "defs": [{"meaning": "(形声。从疒(chuáng),表示与疾病有关,赖声。本义:病名。即“麻疯”)。"}, {"meaning": "麻风病", "words": [{"w": "癞可", "t": "指宋僧祖可。因身披恶疾,故称癞可"}, {"w": "癞菌", "t": "麻风病的病原体"}]}, {"meaning": "[方言] 恶疮;顽癣", "words": [{"w": "癞皮", "t": "身患顽癣,毛秃皮厚"}]}, {"meaning": "脏。", "cites": [{"t": "但凡客商在路,早晚安歇,有两件事免不得,吃癞饭,睡死人床。", "b": "《水浒传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
