('6363wx','懵','1','měng','忄','18','','[{"pinyin": "měng", "defs": [{"meaning": "(形声。从心,瞢声。本义:昏昧无知的样子) 同本义。", "cites": [{"t": "此懵然者为之也。", "b": "沈括《梦溪笔谈》"}], "words": [{"w": "懵钝", "t": "愚鲁迟钝"}, {"w": "懵憧", "t": "糊涂;迷糊"}, {"w": "懵昧", "t": "愚昧。亦用为谦词"}, {"w": "懵懵", "t": "糊里糊涂,模糊不清"}, {"w": "懵头懵脑", "t": "迷迷糊糊。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6364wx','彝','1','yí','彑','18','','[{"pinyin": "yí", "defs": [{"meaning": "(形声。从糸(mì),攻(gǒng)持米,彑(jì)声。为双手捧丝、米奉献神灵。据甲骨文,象双手捧鸡奉献之意。本义:古代祭祀时常用的礼器的总称)。"}, {"meaning": "同本义。", "cites": [{"t": "官司彝器。", "b": "《左传》"}], "words": [{"w": "彝俎", "t": "泛指礼器"}, {"w": "彝鼎", "t": "泛指古代祭祀用的鼎、尊等礼器"}, {"w": "彝斝", "t": "泛指古代祭祀用的酒器"}, {"w": "彝簋", "t": "泛指古代祭祀所用的礼器。"}]}, {"meaning": "常规。", "cites": [{"t": "民之秉彝,好是懿德。", "b": "《诗·大雅》"}]}, {"meaning": "彝族,中国少数民族。"}, {"meaning": "经常。", "cites": [{"t": "皇极之敷言,足彝是训。", "b": "《书·洪范》"}], "words": [{"w": "彝化", "t": "经常的教化"}, {"w": "彝则", "t": "经常的制度,准则"}, {"w": "彝酒", "t": "谓经常饮酒。"}]}]}]','jingmo-wenyan');
