('6367wx','攉','1','huō','扌','19','','[{"pinyin": "huō", "defs": [{"meaning": "反手;手反覆。", "cites": [{"t": "攉,手反覆也。摇手曰挥,反手曰攉。", "b": "《字汇》"}, {"t": "攉,挥攉。", "b": "《玉篇》"}, {"t": "感君三尺铁,挥攉鬼神惊。", "b": "唐·牟融《谢惠剑》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6368wx','攒','1','cuán zǎn','扌','19','','[{"pinyin": "cuán", "defs": [{"meaning": "簇拥;围聚;聚集。", "cites": [{"t": "攒,聚也。", "b": "《广韵》"}, {"t": "攒,族聚也。", "b": "《韵会》"}, {"t": "攒珍宝之玩好。", "b": "张衡《西京赋》"}, {"t": "攒戾莎。", "b": "《汉书·司马相如传上》"}, {"t": "复叠攒仄。", "b": "嵇康《琴赋》"}, {"t": "乡民蚁拥蜂攒,布满山麓。", "b": "《广东军务记》"}], "words": [{"w": "万头攒动;万箭攒心;攒簇", "t": "聚集;簇拥"}, {"w": "攒绕", "t": "聚集围绕"}, {"w": "攒仄", "t": "重叠相连"}, {"w": "攒蛾", "t": "皱眉。"}]}]}, {"pinyin": "zǎn", "defs": [{"meaning": "(形声。从手,赞声。(cuán)本义:聚集)。"}, {"meaning": "积聚,积蓄。", "cites": [{"t": "他攒了些私房。", "b": "《西游记》"}], "words": [{"w": "攒积", "t": "积攒。积聚"}, {"w": "攒粪", "t": "积累粪"}, {"w": "攒钱", "t": "积蓄钱。"}]}, {"meaning": "弯曲,卷曲。", "cites": [{"t": "提其耳而四足攒者良,以长则懒也。", "b": "清·方以智《物理小识》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6369wx','鞲','1','gōu','革','19','','[{"pinyin": "gōu", "defs": [{"meaning": "臂套。用革制成,用以束衣袖,射箭或操作时用。", "cites": [{"t": "鞲,射臂决也。", "b": "《说文》"}, {"t": "袒鞲蔽。", "b": "《史记·张耳陈余传》"}, {"t": "董君绿帻傅鞲。", "b": "《汉书·东方朔传》"}], "words": [{"w": "鞲蔽", "t": "臂套"}, {"w": "鞲扞", "t": "射箭用的皮臂套"}, {"w": "鞲鹰", "t": "蹲在臂套上的苍鹰"}, {"w": "鞲绳", "t": "拴住鞲鹰的绳子。"}]}]}]','jingmo-wenyan');
