('6370wx','鞴','1','bèi','革','19','','[{"pinyin": "bèi", "defs": [{"meaning": "车絥,覆盖在车轼上的一种饰物。", "cites": [{"t": "絥,《说文》:“车絥也”。鞴,絥同。", "b": "《广韵》"}]}, {"meaning": "把鞍辔等套在马身上。装备车马。", "cites": [{"t": "鞴马宿严霜。", "b": "王昌龄《塞上曲》"}], "words": [{"w": "鞴马", "t": "备驾,装备坐骑"}, {"w": "鞴勒", "t": "备马。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6371wx','藿','1','huò','艹','19','','[{"pinyin": "huò", "defs": [{"meaning": "豆叶。嫩时可食。", "cites": [{"t": "豆角谓之荚,其叶谓之藿。", "b": "《广雅·释草》"}, {"t": "食我场藿。", "b": "《诗·小雅·白驹》"}, {"t": "牛藿。", "b": "《仪礼·公食大夫礼记》"}, {"t": "奔蝉不能化藿蠋。", "b": "《庄子·庚桑楚》。注:“豆叶中大青虫也。”"}], "words": [{"w": "藿食", "t": "以豆叶为食物。指吃的东西很粗劣。古代常以藿食者指平民,而以肉食者指贵族"}, {"w": "藿羹", "t": "豆叶煮成的菜羹。指古代平民吃的粗菜"}, {"w": "藿蠋", "t": "生长在豆叶中的大青虫。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6372wx','蘧','1','qú','艹','19','','[{"pinyin": "qú", "defs": [{"meaning": "荷花。", "cites": [{"t": "蘧藕拔,蜃蛤剥。", "b": "张衡《西京赋》。李善注引薛综曰:“蘧,芙蕖。”"}]}, {"meaning": "驿车。", "cites": [{"t": "仁义,先王之蘧庐也。", "b": "《庄子·天运》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6373wx','蘅','1','héng','艹','19','','[{"pinyin": "héng", "defs": [{"meaning": "杜衡(Asarum forbesii)的简称。又名苦叶细辛,南细辛。古称香草 。马兜铃科。多年生草本。花被筒钟状,暗紫色。全草入药,并可提取芳香油。", "cites": [{"t": "蘅,杜蘅,香草。", "b": "《玉篇》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6374wx','麓','1','lù','鹿','19','','[{"pinyin": "lù", "defs": [{"meaning": "(形声。从林,鹿声。本义:生长在山脚的林木)。"}, {"meaning": "同本义。", "cites": [{"t": "麓,林属于山为麓。", "b": "《说文》。 按,山足大林也。"}, {"t": "麓者,林之大者也。", "b": "《水经注·漳水》注"}, {"t": "林麓川泽。", "b": "《礼记·王制》"}, {"t": "掌攻草木及林麓。", "b": "《周礼·柞民》"}, {"t": "林衡每大林麓。", "b": "《周礼》。郑玄注:“竹木生平地曰林,山足曰麓。”"}]}, {"meaning": "古代主管山林苑囿的官吏。", "cites": [{"t": "麓,守山林吏也。", "b": "《说文》"}, {"t": "主将适蝼而麓不闻。", "b": "《国语·晋语》"}]}, {"meaning": "山脚。", "cites": [{"t": "瞻彼旱麓,榛楛济济。", "b": "《诗·大雅·旱麓》"}], "words": [{"w": "山麓", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6375wx','醮','1','jiào','酉','19','','[{"pinyin": "jiào", "defs": [{"meaning": "古冠、婚礼所行的一种简单仪式。尊者对卑者酌酒,卑者接受敬酒后饮尽,不需回敬。", "cites": [{"t": "醮,冠娶礼祭。", "b": "《说文》。按,酌而无酬酢曰醮。"}, {"t": "若不醴则醮用酒。", "b": "《仪礼·士冠礼》"}, {"t": "父亲醮子而命之迎。", "b": "《礼记·昏义》"}], "words": [{"w": "醮辞", "t": "古代举行冠礼时,父亲酌酒使其子饮用时所念的祝辞"}, {"w": "醮醴", "t": "古代冠礼中的一种简单仪节"}, {"w": "醮酒", "t": "奠酒;敬酒"}, {"w": "醮影", "t": "倩影;美丽的影子。"}]}, {"meaning": "祈祷神灵的祭礼,后专指道士、和尚为禳除灾祸所设的道场。", "cites": [{"t": "醮,祭也。", "b": "《广雅》"}, {"t": "醮诸神。", "b": "宋玉《高唐赋》"}, {"t": "益州有金马碧鸡之神,可醮祭而致。", "b": "《汉书·郊祀志》"}, {"t": "专意斋醮。", "b": "清·张廷玉《明史》"}], "words": [{"w": "醮坛", "t": "为祭祀或祈祷神祗所设的台"}, {"w": "醮谢", "t": "设醮祭谢"}, {"w": "醮器", "t": "设醮祭祀或祈祷时所用的法器"}, {"w": "醮事", "t": "道士设坛祈祷作法事。"}]}, {"meaning": "嫁。", "cites": [{"t": "未嫁而丧二夫,故十九犹未醮也。", "b": "《聊斋志异》"}], "words": [{"w": "再醮;改醮", "t": "已婚妇女再嫁"}, {"w": "醮命", "t": "嫁女的使命"}, {"w": "醮妇", "t": "再嫁妇女。"}]}, {"meaning": "独酌而醉。", "cites": [{"t": "主人进酒于客曰酬,客酌主人曰酢,独酌而醉曰醮。", "b": "明·郎瑛《七修类稿》"}]}, {"meaning": "尽,尤指水尽;酒饮尽。", "cites": [{"t": "利爵之不醮也。", "b": "《荀子·礼论》"}]}]}]','jingmo-wenyan');
