INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6379wx','霭','1','ǎi','雨','19','','[{"pinyin": "ǎi", "defs": [{"meaning": "(形声。从雨,谒声。本义:云气)。"}, {"meaning": "同本义。", "cites": [{"t": "倾云结流霭。", "b": "《文选·陆机·挽歌诗三首》"}, {"t": "暮霭沉沉楚天阔。", "b": "柳永《雨霖铃》"}, {"t": "山涤余霭,宇暧微霄。", "b": "陶潜《时运》"}], "words": [{"w": "暮霭", "t": "傍晚的云雾。"}]}, {"meaning": "烟雾;蒸气。", "cites": [{"t": "白云回望合,青霭入看无。", "b": "唐·王维《终南山》"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
