INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6381wx','黼','1','fǔ','黹','19','','[{"pinyin": "fǔ", "defs": [{"meaning": "(形声。从黹(zhǐ),象缝处纵横交错之形;表示与缝衣或刺绣有关。甫声。本义:古代礼服上绣的半黑半白的花纹) 同本义。", "cites": [{"t": "黼,白与黑相次文。", "b": "《说文》"}, {"t": "玄衮及黼。", "b": "《诗·小雅·采菽》"}, {"t": "白与黑谓之黼,黑与青谓之黻。", "b": "《考工记·画缋之事》"}, {"t": "宗彝藻火,粉米黼黻。", "b": "《书·益稷》"}, {"t": "凡祭祀,共黼画组就之物。", "b": "《周礼·天官·典丝》"}]}, {"meaning": "又。", "cites": [{"t": "美者黼绣,是古天子之服。", "b": "《汉书·贾谊传》"}, {"t": "黼衣黻裳不茹荤。", "b": "《荀子·哀公》"}]}]}]','jingmo-wenyan');
