INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6384wx','蹶','1','jué','足','19','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从足,厥声。本义:倒下,跌倒)。"}, {"meaning": "同本义。", "cites": [{"t": "蹶,僵也。", "b": "《说文》"}, {"t": "小人之行,不蹶于山。", "b": "《吕氏春秋·慎行》"}, {"t": "处足则为萎,为蹶。", "b": "《吕氏春秋·尽数》"}, {"t": "毅恐蹶仆地。", "b": "唐·李朝威《柳毅传》。又如:蹶角(额角叩地,表示恭敬诚恳);蹶踬(跌倒,颠仆);蹶躄(颠跌,奔波);蹶踣(颠仆,跌倒);蹶跌(跌倒)"}]}, {"meaning": "折损。", "cites": [{"t": "蹶上将军。", "b": "《史记·孙吴传》。索隐:“毙也。”"}], "words": [{"w": "一蹶不振;蹶衂", "t": "衰败;损伤。"}]}, {"meaning": "疾行,跑。", "cites": [{"t": "臣闻从时者,犹救火追亡人也,蹶而趋之,唯恐弗及。", "b": "《国语·越语》"}]}, {"meaning": "踏;蹈。", "cites": [{"t": "子胥两祛高蹶而出于廷。", "b": "《吕氏春秋·知化》"}], "words": [{"w": "蹶张", "t": "用脚踏来发射强弩"}, {"w": "蹶弩", "t": "用脚踏强弩发箭。"}]}, {"meaning": "挖掘;拔出。", "cites": [{"t": "蹶穴其中。", "b": "《大戴礼·曾子疾病篇》"}, {"t": "是谓蹶其本。", "b": "《左传·襄公十九年》。注:“犹拔也。”"}], "words": [{"w": "蹶拔", "t": "掘取;拔出"}, {"w": "蹶穴", "t": "掘洞穴。"}]}, {"meaning": "竭尽,枯竭。", "cites": [{"t": "财产何得不蹶。", "b": "《汉书·食货志》引汉·贾谊《论积贮疏》"}]}]}]','jingmo-wenyan');
