INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6387wx','蹴','1','cù jiu','足','19','','[{"pinyin": "cù", "defs": [{"meaning": "(形声。从足,就声。本义:踩,踏)。"}, {"meaning": "同本义。", "cites": [{"t": "蹴,蹑也。", "b": "《说文》"}, {"t": "蹴,蹋也。以足逆蹋曰蹴。", "b": "《一切经音义》引说文"}, {"t": "蹴尔而与之,乞人不屑也。", "b": "《孟子·告子上》"}], "words": [{"w": "蹴跑", "t": "践踏"}, {"w": "蹴践", "t": "践踏"}, {"w": "蹴踏", "t": "踩;踏。"}]}]}, {"pinyin": "jiu", "defs": [{"meaning": "——“圪蹴”(gējiu):方言,蹲。"}]}]','jingmo-wenyan');
