INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6390wx','蠖','1','huò','虫','19','','[{"pinyin": "huò", "defs": [{"meaning": "昆虫名。尺蠖的省称 。尺蠖蛾的幼虫,生长在树上,颜色像树皮色,行动时身体一屈一伸地前进。北方称步曲,南方称造桥虫。", "cites": [{"t": "尺蠖,屈伸虫也。从虫,蒦声,一名步屈。", "b": "《说文》"}, {"t": "麋筋斥蠖。", "b": "《考工记·弓人》"}], "words": [{"w": "蠖屈", "t": "形容像尺蠖一样的屈曲之形"}, {"w": "蠖屈不伸", "t": "如尺蠖之屈而不伸。喻人不得志"}, {"w": "蠖屈鼠伏", "t": "形容卑躬屈膝向人讨好的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6391wx','蠓','1','měng','虫','19','','[{"pinyin": "měng", "defs": [{"meaning": "蚋 。主要是蠓科、瘿蚊科和摇蚊科的任何种小双翅蝇,其中很多都咬得人疼痛,并且还有一些是人类和各种其他脊椎动物寄生虫的中间寄生传播者。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6392wx','蟾','1','chán','虫','19','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从虫,詹(zhān)声。本义:蟾蜍(chú)简称“蟾”,即癞哈蟆)。"}, {"meaning": "同本义。", "cites": [{"t": "小蟾徐行腹如鼓。", "b": "元·元好问《蟾池》"}], "words": [{"w": "蟾壶", "t": "古代计时器。一种蟾蜍形的漏壶"}, {"w": "蟾兔", "t": "蟾蜍与玉兔。"}]}]}]','jingmo-wenyan');
