INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6398wx','籀','1','zhòu','竹','19','','[{"pinyin": "zhòu", "defs": [{"meaning": "同本义。", "cites": [{"t": "籀,读书也。", "b": "《说文》"}, {"t": "卜籀云。", "b": "《春秋传》。按,今本《左传》凡卦兆之词皆以繇为之。"}, {"t": "重籀《论语》诸书。", "b": "章炳麟《检论·订孔下》"}, {"t": "睲河海之行、帝王、妃后、臣宰、农工、徒隶之法,无不籀也。", "b": "清·龚自珍《知归子赞》"}], "words": [{"w": "籀读", "t": "诵读"}, {"w": "籀书", "t": "即籀文。"}]}, {"meaning": "抽取;引出。", "cites": [{"t": "挥兔豪而匪固,籀鱼网而终灭。", "b": "唐·李俨《益州多宝寺道因法师碑文》序"}], "words": [{"w": "籀演", "t": "引申;演绎。"}]}, {"meaning": "汉字的一种文体。一名大篆。", "cites": [{"t": "周宣王史名籀,其所著文字曰籀文。亦曰大篆。", "b": "朱骏声《说文通训定声》"}, {"t": "籀,史籀,周太史造大篆。", "b": "《玉篇》"}, {"t": "仇校篆籀,篇章毕觌。", "b": "晋·左思《魏都赋》"}], "words": [{"w": "籀文", "t": "我国古代书体的一种"}, {"w": "籀篆", "t": "古代的一种书体。即大篆。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6399wx','籁','1','lài','竹','19','','[{"pinyin": "lài", "defs": [{"meaning": "(形声。从竹,赖声。本义:古代一种管乐器,三孔)。"}, {"meaning": "同本义。", "cites": [{"t": "吹鸣籁。", "b": "《史记·司马相如传》。集解:“籁,箫也。”"}, {"t": "爽籁发而清风生。", "b": "王勃《滕王阁序》"}], "words": [{"w": "籁竽", "t": "箫与竽,用竹制的管乐器"}, {"w": "籁龠", "t": "古管乐器。籁,三孔;龠,六孔。又指箫。"}]}]}]','jingmo-wenyan');
