INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6401wx','魑','1','chī','鬼','19','','[{"pinyin": "chī", "defs": [{"meaning": "(形声。从鬼,离声。本义:精怪名)。"}, {"meaning": "传说中的山神。", "cites": [{"t": "始经魑魅之涂,卒践无人之境。", "b": "孙绰《游天台山赋》"}], "words": [{"w": "魑魅", "t": "古代传说中山神和精怪,能作祟祸人。泛指坏人"}, {"w": "魑魅魍魉", "t": "本为山怪水神,引申为各式各样的坏人。"}]}]}]','jingmo-wenyan');
