INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6403wx','鳓','1','lè','鱼','19','','[{"pinyin": "lè", "defs": [{"meaning": "鳓鱼 ,身体侧扁,银白色,头小,鳃孔大,无侧线。生活在海中。也叫“鱠(快)鱼”、“白鳞鱼”或“曹白鱼”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6404wx','鳔','1','biào','鱼','19','','[{"pinyin": "biào", "defs": [{"meaning": "鱼鳔 。大多数鱼所具有的一个充有气体的囊,可以胀缩,使鱼能在水中上浮或下沉。有的鱼类的鳔有辅助听觉或呼吸等作用。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6405wx','鳕','1','xuě','鱼','19','','[{"pinyin": "xuě", "defs": [{"meaning": "通称“大头鱼” ,产于北大西洋的冷水域中的一种软鳍鱼(Gadus morrhua),是世界上最主要的食用鱼之一,素栖居比较浅的水域的接近底层部分。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6406wx','鳗','1','mán','鱼','19','','[{"pinyin": "mán", "defs": [{"meaning": "鳗鱼,今俗曰鳗鲡 。构成无足目(Apodes)许多种贪食的细长如蛇的真骨鱼类,皮肤多半是无鳞的和溜光粘滑的,没有骨盆,有时也没有胸鳍,中间鳍全部融合于尾部", "words": [{"w": "河鳗", "t": ""}, {"w": "海鳗", "t": ""}]}, {"meaning": "许多种多少类似真正鳗的细长型鱼类(如合鳃目的鱼)的泛称", "words": [{"w": "电鳗", "t": ""}, {"w": "沙鳗", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6407wx','鳙','1','yōng','鱼','19','','[{"pinyin": "yōng", "defs": [{"meaning": "鱼名,鳙鱼,又名“胖头鱼”、“花鲢”、“黑鲢” ,头很大,生活在淡水中。", "cites": [{"t": "鳙,产于江湖,似鲢而黑,头甚大。俗呼黑鲢,又称鲢胖头。", "b": "徐珂《清稗类钞》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6408wx','麒','1','qí','鹿','19','','[{"pinyin": "qí", "defs": [{"meaning": "(形声。从鹿,其声。《说文》:“仁兽也。”本义:传说中的一种动物,其状如鹿,独角,全身生鳞甲,尾象牛。多用作吉祥的象征。又名“麒麟”,又单称“麟”)。"}, {"meaning": "麒麟。"}, {"meaning": "古代传说以为仁兽、瑞兽,形状像鹿而独角,尾像牛尾。", "cites": [{"t": "麒,仁兽也,麋身,牛尾,一角。", "b": "《说文》"}], "words": [{"w": "麒麟补服", "t": "明清武官的绣有麒麟的服饰"}, {"w": "麒麟不至", "t": "仁兽不现。比喻乱世"}, {"w": "麒麟斗", "t": "麒麟跟麒麟搏斗"}, {"w": "麒麟袍", "t": "袍子上绣有麒麟者"}, {"w": "麒麟门", "t": "上绘蓝色麒麟的官署暖阁后的一道门。"}]}, {"meaning": "喻杰出人物。", "cites": [{"t": "应图求骏马,惊代得麒麟。", "b": "唐·杜甫《上韦左相二十韵》"}], "words": [{"w": "麒麟冢", "t": "名臣贵人的坟墓"}, {"w": "麒麟客", "t": "称有高尚道德的人。"}]}, {"meaning": "汉殿名。", "cites": [{"t": "叔曰:“今朝同上凤凰台。”公即应声答曰:“他年独占麒麟阁”。", "b": "《于谦全传》"}, {"t": "金华玉堂,白虎麒麟。", "b": "班固《西都赋》"}], "words": [{"w": "麒麟阁", "t": "汉代在未央宫中修建的一阁"}, {"w": "麒麟画", "t": "麒麟阁中的功臣画像。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6409wx','鏖','1','áo','金','19','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从金,鏕声。本义:温器)。"}, {"meaning": "假借为熬。苦战。激烈战斗。", "cites": [{"t": "合短兵,鏖皋兰下。", "b": "《汉书·霍去病传》。注:“谓苦击而多杀也。”"}], "words": [{"w": "鏖杀", "t": "杀尽所有的人而不留活口。"}]}, {"meaning": "喧嚷,喧扰。", "cites": [{"t": "市声鏖午枕。", "b": "黄庭坚《仁亭》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6410wx','羸','1','léi','亠','19','','[{"pinyin": "léi", "defs": [{"meaning": "(形声。从羊,本义:瘦弱)。"}, {"meaning": "同本义。", "cites": [{"t": "羸,瘦也。", "b": "《说文》。按,本训当为瘦羊,转而言人耳。"}, {"t": "羸老易子。", "b": "汉·贾谊《论积贮疏》"}, {"t": "皆羸老之卒。", "b": "《资治通鉴·唐纪》"}, {"t": "悉使羸兵负草。", "b": "《资治通鉴》"}]}, {"meaning": "又。", "cites": [{"t": "羸兵为人马所蹈藉。", "b": ""}], "words": [{"w": "羸骖", "t": "瘦弱的马"}, {"w": "羸蹇", "t": "驽弱瘦瘠的驴"}, {"w": "羸驷", "t": "瘦弱的马"}, {"w": "羸骀", "t": "瘦弱驽钝的马。喻才能低下"}, {"w": "羸饿", "t": "瘦瘠饥饿。亦指瘦瘠饥饿的人。"}]}, {"meaning": "疲困。", "cites": [{"t": "身病体羸。", "b": "《礼记·问丧》。释文:“疲也。”"}], "words": [{"w": "羸北", "t": "困败"}, {"w": "羸色", "t": "疲惫的神色"}, {"w": "羸师", "t": "谓藏其精锐而出示疲弱的军队以麻痹敌人。"}]}, {"meaning": "衰弱。", "cites": [{"t": "请羸师以张之。", "b": "《左传·桓公元年》"}, {"t": "此羸者阳也。", "b": "《国语·周语》。注:“弱也。”"}], "words": [{"w": "羸老", "t": "衰弱的老人"}, {"w": "羸病", "t": "衰弱生病"}, {"w": "羸疾", "t": "衰弱生病。"}]}, {"meaning": "低劣。", "cites": [{"t": "小子无谓我老而羸我。", "b": "《淮南子·缪称》。注:“劣人也。”"}], "words": [{"w": "羸钝", "t": "低劣迟钝。"}]}, {"meaning": "缠绕,困住。", "cites": [{"t": "羝羊触藩,羸其角。", "b": "《易·大壮》"}, {"t": "有攸往见凶,羸豕孚蹢躅。", "b": "《易·姤》"}]}]}]','jingmo-wenyan');
