INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6412wx','瀚','1','hàn','氵','19','','[{"pinyin": "hàn", "defs": [{"meaning": "(形声。从水,翰声。本义:瀚海:古代指北方的大海。明代以来指戈壁沙漠)。"}, {"meaning": "同本义 。其含义随时代而变。原指北方的大湖。或指贝加尔湖。唐代是指蒙古高原大沙漠以北及西至今准噶尔盆地一带广大地区的泛称。亦多用为征战、武功等典故。", "cites": [{"t": "校尉羽书飞瀚海,单于猎火照狼山。", "b": "唐·高适《燕歌行》"}]}, {"meaning": "水浩大的样子;广大。", "cites": [{"t": "浩浩瀚瀚。", "b": "《淮南子·俶真》"}], "words": [{"w": "瀚瀚", "t": "广大的样子"}, {"w": "浩瀚", "t": "广大辽阔的样子"}, {"w": "瀚漫", "t": "广大的样子"}, {"w": "瀚浩", "t": "浩瀚。广大的样子。"}]}, {"meaning": "澣。洗涤。", "cites": [{"t": "空负黄花羞短发,寒衣三瀚客心惊。", "b": "清·宋琬诗"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6413wx','瀣','1','xiè','氵','19','','[{"pinyin": "xiè", "defs": [{"meaning": "夜间的水气。", "cites": [{"t": "屈原忧极,故有轻举远游、餐霞饮瀣之赋。", "b": "章学诚《文史通义·质性》"}], "words": [{"w": "瀣沆", "t": "瀣气。夜间的水气。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6414wx','瀛','1','yíng','氵','19','','[{"pinyin": "yíng", "defs": [{"meaning": "(形声。从水,嬴(yíng)声。本义:海)。"}, {"meaning": "同本义。", "cites": [{"t": "瀛,海也。", "b": "《玉篇》"}]}, {"meaning": "小而静的淡水体;池泽。", "cites": [{"t": "飞桥上架汉,缭岸俯视瀛。", "b": "唐·韩愈等《城南联句》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6415wx','襦','1','rú','衤','19','','[{"pinyin": "rú", "defs": [{"meaning": "(形声。从衣,需声。本义:短衣;短袄。襦有单、复。单襦近乎衫,复襦则近袄)。"}, {"meaning": "同本义。", "cites": [{"t": "襦,短衣也。", "b": "《说文》"}, {"t": "袍襦表里曲领群。", "b": "《急就篇》。"}, {"t": "衣不帛襦袴。", "b": "《礼记·内则》"}, {"t": "缃绮为下裙,紫绮为上襦。", "b": "《乐府诗集·陌上桑》"}], "words": [{"w": "短襦;襦袄", "t": "指不能遮蔽到膝盖下的棉袄。即短袄"}, {"w": "襦衣", "t": "短衣;短袄;亦泛指衣服"}, {"w": "襦带", "t": "衬里小袄的带子"}, {"w": "襦袖", "t": "襦袄袖子"}, {"w": "襦裤", "t": "短衣与裤。亦泛指衣服"}, {"w": "襦帼", "t": "妇女的襦袄和首饰"}, {"w": "襦领", "t": "衬里短衣的领子。"}]}, {"meaning": "围嘴、涎巾。", "cites": [{"t": "腻剃新胎发,香绷小绣襦。", "b": "白居易《阿崔》"}]}, {"meaning": "细密的罗网。", "cites": [{"t": "蜡则作罗襦。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6416wx','谶','1','chèn','讠','19','','[{"pinyin": "chèn", "defs": [{"meaning": "(形声。本义:将来能应验的预言、预兆) 同本义", "words": [{"w": "谶兆", "t": "预言吉凶的先兆"}, {"w": "谶记", "t": "预言未来事象的文字图录"}, {"w": "谶书", "t": "预言将来事情的书"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6417wx','襞','1','bì','衣','19','','[{"pinyin": "bì", "defs": [{"meaning": "折叠衣裙。", "cites": [{"t": "固不如襞而幽之离房。", "b": "《汉书·扬雄传》。注:“叠衣也。”"}, {"t": "美襞积以酷烈兮。", "b": "张衡《思玄赋》"}, {"t": "衣襞不县有虫。", "b": "王充《论衡·商虫》"}], "words": [{"w": "襞方(端午节风俗用五色丝缠纸帛折成菱角方片,按一定方位(青、赤、白、黑为四方黄居中央)缀于胸前,以示妇人养蚕之功", "t": ""}, {"w": "襞幅", "t": "折叠布幅为衣裳。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6418wx','骥','1','jì','马','19','','[{"pinyin": "jì", "defs": [{"meaning": "(会意。从马,冀声。按左传,冀之北上,马之所生,是冀亦兼会意。本义:好马;良马)。"}, {"meaning": "同本义。", "cites": [{"t": "骥,千里马也。", "b": "《说文》"}, {"t": "骥不称其力,称其德也。", "b": "《论语·宪问》"}], "words": [{"w": "骥子", "t": "良马;比喻才能特出的人"}, {"w": "骥尾", "t": "千里马的尾巴。比喻追随在德行好、地位高或能力强的人的后面"}, {"w": "骥足", "t": "千里马的脚。比喻高才。"}]}, {"meaning": "比喻杰出的人才。", "cites": [{"t": "世不乏骥,求则可致。", "b": "《晋书·虞预传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6419wx','缵','1','zuǎn','纟','19','','[{"pinyin": "zuǎn", "defs": [{"meaning": "(形声。从糸(mì),赞声。本义:继续,继承)。"}, {"meaning": "同本义。", "cites": [{"t": "缵,继也。", "b": "《说文》"}, {"t": "武王缵太王、王季文王之绪。", "b": "《礼记·中庸》"}, {"t": "载缵武功。", "b": "《诗·豳风·七月》"}, {"t": "奄有下土,缵禹之绪。", "b": "《诗·鲁颂·閟宫》"}], "words": [{"w": "缵绪", "t": "继承前人的事业"}, {"w": "缵续", "t": "继续"}, {"w": "缵业", "t": "继承事业"}, {"w": "缵述", "t": "继承传述"}, {"w": "缵明", "t": "继承而光大之"}, {"w": "缵衍", "t": "继承并发展。"}]}, {"meaning": "用同“纂”。撰写。", "cites": [{"t": "读书以为学,缵言以为文。", "b": "《送陈秀才彤序》"}], "words": [{"w": "缵述", "t": "传述"}, {"w": "缵缉", "t": "缵续。继续。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6420wx','瓒','1','zàn','王','20','','[{"pinyin": "zàn", "defs": [{"meaning": "(形声。从玉,赞声。本义:质地不纯的玉)。"}, {"meaning": "同本义。", "cites": [{"t": "瓒,三玉、二石也。", "b": "《说文》。徐锴系传:“谓五分玉之中二分是石。”"}]}, {"meaning": "古代祭祀时用的玉勺子。", "cites": [{"t": "瑟彼玉瓒,黄流在中。", "b": "《诗·大雅·旱麓》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6421wx','攘','1','rǎng','扌','20','','[{"pinyin": "rǎng", "defs": [{"meaning": "(形声。从手,襄(xiāng)声。本义:推让,退让)。"}, {"meaning": "同本义。", "cites": [{"t": "攘,推也。", "b": "《说文》。谓推手使前拱揖之容也,字亦作儴。"}, {"t": "左右攘辟。", "b": "《礼记·曲礼上》"}, {"t": "小子何敢攘焉。", "b": "《史记·太史公自序》"}, {"t": "随流而攘。", "b": "《汉书·司马相如传》。注:“却退也。”"}, {"t": "盛揖攘之容。", "b": "《汉书·礼乐志》"}, {"t": "合于尧之克攘。", "b": "《汉书·艺文志》"}]}, {"meaning": "排斥,努力消去。", "cites": [{"t": "攘,除也。", "b": "《广韵》"}, {"t": "攘夷狄。", "b": "《公羊传·僖公四年》"}, {"t": "反离谤而见攘。", "b": "《楚辞·七谏·沈江》"}, {"t": "攘白翟之地。", "b": "《国语·齐语》"}, {"t": "攘弃仁义。", "b": "《庄子·胠箧》"}], "words": [{"w": "攘斥", "t": "排斥;驱除"}, {"w": "攘抑", "t": "排除抑止"}, {"w": "攘患", "t": "排除祸患"}, {"w": "攘贪", "t": "排除贪欲"}, {"w": "攘讨", "t": "驱除讨伐"}, {"w": "攘却", "t": "驱除"}, {"w": "攘夷", "t": "攘狄。抗拒异族入侵"}, {"w": "攘狱", "t": "拒捕。"}]}, {"meaning": "止。", "cites": [{"t": "既从竖而横构,亦风除而雨攘。", "b": "南朝梁·沈约《郊居赋》"}]}, {"meaning": "侵略。", "cites": [{"t": "诸侯暴乱,擅相攘伐。", "b": "《庄子·渔父》"}, {"t": "南夷相攘。", "b": "《汉书·严助传》。注:“谓相侵夺也。”"}], "words": [{"w": "攘伐", "t": "侵夺交战"}, {"w": "攘肌及骨", "t": "比喻侵及腹地"}, {"w": "攘争", "t": "争夺"}, {"w": "攘服", "t": "征服"}, {"w": "攘杀", "t": "掠夺毁坏"}, {"w": "攘掊", "t": "掠夺搜括"}, {"w": "攘略", "t": "侵夺"}, {"w": "攘剽", "t": "掠夺。"}]}, {"meaning": "偷,盗窃。", "cites": [{"t": "请损之,丹攘一鸡,以待来年,然后已。", "b": "《孟子·滕文公下》"}], "words": [{"w": "攘盗", "t": "攘窃,盗窃,抢夺"}, {"w": "攘鸡", "t": "偷鸡"}, {"w": "攘取", "t": "窃取;夺取。"}]}, {"meaning": "破坏安宁;骚动。", "cites": [{"t": "心无天游则六凿相攘。", "b": "《庄子·外物》"}], "words": [{"w": "攘扰", "t": "扰乱"}, {"w": "攘攘熙熙", "t": "喧嚷纷杂貌"}, {"w": "攘攘劳劳", "t": "忙乱辛劳"}, {"w": "攘乱", "t": "扰乱。"}]}, {"meaning": "捋起。", "cites": [{"t": "冯妇攘臂下车。", "b": "《孟子·尽心下》"}, {"t": "攘袖见素手。", "b": "魏·曹植《美女篇》"}], "words": [{"w": "攘襟", "t": "攘衽。揭起衣襟"}, {"w": "攘袖", "t": "卷起衣袖"}, {"w": "攘袪", "t": "攘袂。捋上衣袖"}, {"w": "攘肱", "t": "攘臂"}, {"w": "攘卷", "t": "捋袖举拳"}, {"w": "攘手", "t": "攘臂。"}]}, {"meaning": "夺。", "cites": [{"t": "自幼时每争攘饮食。", "b": "《金史》"}]}, {"meaning": "容忍。", "cites": [{"t": "忍尤而攘垢。", "b": "《楚辞·离骚》"}], "words": [{"w": "攘诟", "t": "容忍耻辱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6422wx','蘩','1','fán','艹','20','','[{"pinyin": "fán", "defs": [{"meaning": "白蒿。", "cites": [{"t": "蘩,白蒿也。从草,緐声。", "b": "《说文》"}, {"t": "蘩,皤蒿,又,蘩之丑。秋为蒿。", "b": "《尔雅·释草》。按,今苏俗谓之蓬蒿菜,叶似艾,粗于青蒿,白于众蒿,可为菹。"}, {"t": "于以采蘩,于沼于沚。于以用之,公侯之事。", "b": "《诗·召南·采蘩》"}, {"t": "世上名山无数多,花开花谢蘩还众。", "b": "《西游记》"}]}, {"meaning": "菊科。一至二年生草本,嫩苗可食。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6423wx','蘖','1','niè','艹','20','','[{"pinyin": "niè", "defs": [{"meaning": "(形声。从木,薛声。本义:被砍去或倒下的树木再生的枝芽)。"}, {"meaning": "同本义。", "cites": [{"t": "若颠本之有由蘖。", "b": "《书·盘庚上》"}, {"t": "苞有三蘖。", "b": "《诗·商颂·长发》。朱注:“蘖,旁生萌蘖也。”"}, {"t": "非无萌蘖之生焉。", "b": "《孟子·告子上》"}, {"t": "寻木起于蘖栽。", "b": "《文选·张衡·东京赋》。注:“斩而复生曰蘖。”"}], "words": [{"w": "槎蘖", "t": "砍伐幼林。"}]}, {"meaning": "植物的芽。", "cites": [{"t": "茶之佳品,芽蘖细微,不可多得。", "b": "王观国《学林》"}], "words": [{"w": "蘖芽", "t": "草木萌生的新芽。"}]}, {"meaning": "高。", "cites": [{"t": "宋王筑为蘖台。", "b": "《吕氏春秋·过理篇》"}]}, {"meaning": "生芽的米。", "cites": [{"t": "蘖,芽米也。", "b": "《说文》"}]}, {"meaning": "酿酒的曲。", "cites": [{"t": "以蘖为酒。", "b": "《管子·禁藏》"}], "words": [{"w": "蘖酒", "t": "曲酒"}, {"w": "蘖曲", "t": "酒曲。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6424wx','醴','1','lǐ','酉','20','','[{"pinyin": "lǐ", "defs": [{"meaning": "(形声。从酉(yǒu),豊(lǐ)声。从“酉”,表示与酒有关。本义:甜酒)。"}, {"meaning": "同本义。", "cites": [{"t": "醴,酒一宿孰也。", "b": "《说文》"}, {"t": "醴齐。", "b": "《周礼·酒正》。注:“醴,犹體也。成而汁滓相将如今恬酒矣。”"}, {"t": "或以酏为醴。", "b": "《礼记·内则》"}, {"t": "醴者,稻醴也。", "b": "《礼记·杂记》"}, {"t": "且以酌醴。", "b": "《诗·小雅·吉日》"}, {"t": "为酒为醴。", "b": "《诗·周颂·丰年》"}, {"t": "酒醴异气,饮之皆醉。", "b": "王充《论衡》"}], "words": [{"w": "醴杯", "t": "酒杯"}, {"w": "醴酒", "t": "甜酒"}, {"w": "醴齐", "t": "醴酒,甜酒。"}]}, {"meaning": "甘,甜。", "cites": [{"t": "地出醴泉。", "b": "《礼记·礼运》"}, {"t": "甘雨时降,万物以嘉,谓之醴泉。", "b": "《尔雅》"}, {"t": "醴泉出山。", "b": "《尚书·中候》。注:“醴,甘也。”"}], "words": [{"w": "醴泉侯", "t": "酒的别称"}, {"w": "醴液", "t": "甘美的泉水。"}]}, {"meaning": "礼法,规范、仪式的总称。", "cites": [{"t": "出请醴宾。", "b": "《仪礼·士昏礼》"}, {"t": "若不醴,则醮用酒。", "b": "《仪礼·士冠礼》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6425wx','霰','1','xiàn','雨','20','','[{"pinyin": "xiàn", "defs": [{"meaning": "(形声。从雨,散声。本义:雪珠) 同本义。亦称“雹”。", "cites": [{"t": "夜深烟火灭,霰雪落纷纷。", "b": "白居易《秦中吟》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6426wx','酆','1','fēng','阝','20','','[{"pinyin": "fēng", "defs": [{"meaning": "古地名。酆城。", "cites": [{"t": "酆,周文王所都,在京兆杜陵西南,从邑,丰声。", "b": "《说文》"}, {"t": "毕原酆郇。", "b": "《左传·僖公二十四年》"}, {"t": "康有酆宫之朝。", "b": "《左传·昭公四年》"}]}, {"meaning": "周文王灭崇侯虎后曾都于此。后为周武王之弟的封国。故地在今陕西省户县北。"}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6427wx','矍','1','jué','目','20','','[{"pinyin": "jué", "defs": [{"meaning": "惊惶四顾的或惊视的。", "cites": [{"t": "矍,一曰视遽貌。", "b": "《说文》。徐锴曰:“左右惊顾。”"}, {"t": "震索索,视矍矍。", "b": "《易·震》"}], "words": [{"w": "矍矍", "t": "惊惧四顾的样子;急切的样子;疾视的样子"}, {"w": "矍然", "t": "迫不及待着急的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6428wx','曦','1','xī','日','20','','[{"pinyin": "xī", "defs": [{"meaning": "(形声。从日,羲(xǐ)声。本义:太阳,阳光)。"}, {"meaning": "同本义。", "cites": [{"t": "东曦既驾", "b": "《聊斋志异·促织》"}], "words": [{"w": "曦月", "t": "日月"}, {"w": "曦车", "t": "曦轩。曦和所驾之车。指太阳"}, {"w": "曦景", "t": "阳光"}, {"w": "曦微", "t": "阳光微弱。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6429wx','躅','1','zhú zhuó','足','20','','[{"pinyin": "zhú", "defs": [{"meaning": "足迹。", "cites": [{"t": "躅,蹢躅也。从足,蜀声。", "b": "《说文》。按,迹也。"}, {"t": "三辅谓牛蹄处为躅。", "b": "《一切经音义》引《汉书叙传音义》"}, {"t": "企望尘躅。", "b": "《尔雅序》"}, {"t": "尘游躅于蕙路。", "b": "南朝齐·孔稚珪《北山移文》"}], "words": [{"w": "躅路", "t": "行走的足迹。"}]}, {"meaning": "用于“踯躅”。徘徊不行。", "cites": [{"t": "羸豕孚蹢躅。", "b": "《易·姤》"}], "words": [{"w": "躅踯", "t": "徘徊。"}]}, {"meaning": "践踏;踏踩。", "cites": [{"t": "师旷东躅其足。", "b": "《周书·太子晋》。注:“东躅,蹋也。”"}, {"t": "朝露白如玉,我不敢躅,恐湿我足。", "b": "刘明《鸡鸣一首赠宗文侄》"}], "words": [{"w": "躅躅", "t": "行走的样子"}, {"w": "躅足", "t": "犹跺脚"}, {"w": "躅陆", "t": "顿足跳跃的样子"}, {"w": "躅蹐", "t": "小步行走。"}]}]}, {"pinyin": "zhuó", "defs": [{"meaning": "足迹。", "cites": [{"t": "躅,钲躅也。从足,蜀声。", "b": "《说文》。按,迹也。"}, {"t": "尘游躅于蕙路。", "b": "南朝齐·孔稚圭《北山移文》"}], "words": [{"w": "躅路", "t": "道路。"}]}, {"meaning": "功绩。", "cites": [{"t": "校长程君仲沂及奉职斯校之诸君子,低回遗躅,观感实深。", "b": "梁启超《戴东原图书馆缘起》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6430wx','鼍','1','tuó','黽','20','','[{"pinyin": "tuó", "defs": [{"meaning": "扬子鳄  ,钝吻鳄科的一种爬行动物(Alligator sinensis),产于长江下游,是中国特产。亦称“鼍龙”,俗称“猪婆龙”。", "cites": [{"t": "(鱼鳖鼋鼍。)《墨子·公输》", "b": ""}], "words": [{"w": "鼍更", "t": "鼍的鸣声"}, {"w": "鼍鼓", "t": "鼍皮制成的鼓"}, {"w": "鼍风鱼", "t": "传说中的鼍类动物。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6431wx','巉','1','chán','山','20','','[{"pinyin": "chán", "defs": [{"meaning": "险峻,陡峭。", "cites": [{"t": "循溪行山下,一带峭壁巉崖。", "b": "《徐霞客游记》。又如:巉刻(山峰尖峭,如同刀削一般。比喻说话或文章尖刻);巉峭(高峻陡削)"}]}, {"meaning": "嶙峋突兀。", "cites": [{"t": "乱峰巉似槊,一水淡如油。", "b": "宋·苏轼《壬寓二月寄子由》"}], "words": [{"w": "巉屼", "t": "形容山石突兀重叠。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6432wx','黩','1','dú','黑','20','','[{"pinyin": "dú", "defs": [{"meaning": "(形声。从黑,卖声。本义:污浊)。"}, {"meaning": "同本义。", "cites": [{"t": "黩,握持垢也。", "b": "《说文》。段玉裁注:“垢非可握持之物,而入于握持,是辱也。”"}, {"t": "黩,污也。", "b": "《汉书·谷永传》注"}, {"t": "亟则黩。", "b": "《公羊传·桓公八年》"}], "words": [{"w": "黩昏", "t": "污浊昏乱。"}]}, {"meaning": "轻慢不敬。", "cites": [{"t": "敬而不黩。", "b": "《汉书·郊祀志》"}, {"t": "黩,狎也。", "b": "《广雅·释言》"}], "words": [{"w": "黩慢", "t": "轻浮而不庄重"}, {"w": "黩贱", "t": "轻视"}, {"w": "黩近", "t": "亲近,狎近。"}]}, {"meaning": "引申为黑色的。", "cites": [{"t": "林木为之润黩。", "b": "《文选·左思·吴都赋》。李善注:“黩,黑茂貌。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6433wx','黥','1','qíng','黑','20','','[{"pinyin": "qíng", "defs": [{"meaning": "(会意。从黑,京声。刻其面以墨窒之。字亦作“剠”。本义:古代一种肉刑,墨刑的异称)。"}, {"meaning": "刺字。", "cites": [{"t": "黥,墨刑在面也。", "b": "《说文》"}, {"t": "放黥者马竿人面也。", "b": "《书·刑德》"}], "words": [{"w": "黥首刖足", "t": "刻额染墨,截断双脚"}, {"w": "黥布", "t": "英布,汉高祖的大将、功臣。因犯罪被黥面"}, {"w": "黥首", "t": "汉代刑法之一。其法在罪人额上刻字染墨"}, {"w": "黥面", "t": "在脸上刺字涂墨"}, {"w": "黥徒", "t": "受黥刑的犯人。引申泛指囚徒,罪犯。"}]}, {"meaning": "镌刻。", "cites": [{"t": "声明走百灵,结构黥幽谷。", "b": "清·魏源《白岳东崖》"}]}, {"meaning": "受过黥刑的人。", "cites": [{"t": "自唐失其政,天下乘时,黥髡盗贼。", "b": "《新五代史》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6434wx','黪','1','cǎn','黑','20','','[{"pinyin": "cǎn", "defs": [{"meaning": "浅青黑色。", "cites": [{"t": "黪,浅青黑色也。", "b": "《说文》"}, {"t": "黪,黑也。", "b": "《广雅》"}], "words": [{"w": "黪衣", "t": "浅黑布做的衣服"}, {"w": "黪墨", "t": "淡黑色。特指东西将要腐败变质时的颜色。"}]}]}]','jingmo-wenyan');
