INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6438wx','纂','1','zuǎn','糸','20','','[{"pinyin": "zuǎn", "defs": [{"meaning": "(形声。从糸(mì),算声。本义:赤色的丝带)。"}, {"meaning": "同本义。", "cites": [{"t": "纂,似组而赤。", "b": "《说文》"}, {"t": "锦乡纂组,害女红者也。", "b": "《汉书·景帝纪》"}, {"t": "缕纂以为奉。", "b": "《国语·齐语》"}], "words": [{"w": "纂组", "t": "赤色绶带。亦泛指精美的织锦。"}]}, {"meaning": "收集;汇集。", "cites": [{"t": "纂就前绪,遂成考功。", "b": "《楚辞·天问》"}, {"t": "自结绳之代以及秦事,无不纂录。", "b": "韩愈《毛颖传》"}, {"t": "歌枣下之纂纂。", "b": "潘岳《笙赋》"}], "words": [{"w": "纂言", "t": "纂集言词,而从事述作"}, {"w": "纂论", "t": "聚集众议"}, {"w": "纂纂", "t": "积聚的样子。"}]}, {"meaning": "编撰;编辑。", "cites": [{"t": "今且各纂诗笔,粗为卷第。", "b": "白居易《与元九书》"}, {"t": "要纂三部书嘉惠来学。", "b": "《儒林外史》"}], "words": [{"w": "纂述", "t": "编撰述作"}, {"w": "纂次", "t": "编撰;编排"}, {"w": "纂刻", "t": "编集刊印"}, {"w": "纂集", "t": "编撰汇集。"}]}, {"meaning": "继承。", "cites": [{"t": "纂修其绪。", "b": "《国语·周语上》。注:“纂,继也。”"}, {"t": "纂尧之绪。", "b": "《汉书·叙传》"}, {"t": "况纂帝业而轻天位。", "b": "张衡《东京赋》"}]}]}]','jingmo-wenyan');
