INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6440wx','鼯','1','wú','鼠','20','','[{"pinyin": "wú", "defs": [{"meaning": "鼠名。鼯鼠 。形似松鼠,毛多褐色,尾巴很长,前后肢之间有薄膜,能从树上飞降下来,住在树沿中,昼伏夜出。又名夷由", "words": [{"w": "鼯猱", "t": "鼯鼠和猱猿。比喻南方蛮人"}, {"w": "鼯啸", "t": "鼯鼠呼啸"}, {"w": "鼯技", "t": "雕虫小技。比喻能力极平庸"}, {"w": "鼯鼠之丑", "t": "比喻丑陋低下的才艺"}]}]}]','jingmo-wenyan');
