INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6442wx','鳜','1','guì jué','鱼','20','','[{"pinyin": "guì", "defs": [{"meaning": "即鳜鱼 。中国产的一种美味食用鱼(Siniperca chuatsi),俗名花鲫鱼,亦称“桂鱼”。属鮨科,体侧扁,青黄色或橄褐色,具许多不规则的暗棕色或黑色斑点,背隆起,口大,下颌突出,背鳍一个,鳞细小、圆形,性凶猛,捕食水中鱼虾。", "cites": [{"t": "西塞山前白鹭飞,桃花流水鳜鱼肥。", "b": "唐·张志和《渔歌子》"}]}]}, {"pinyin": "jué", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6443wx','鳝','1','shàn','鱼','20','','[{"pinyin": "shàn", "defs": [{"meaning": "鱼名,又名“黄鳝” 。形状像蛇,身体黄色有黑斑,肉可以吃。属鱼纲合鳃科。栖息池塘、小河、稻田的泥洞或石缝中。", "cites": [{"t": "蟹六跪而二螯,非蛇鳝之穴无可寄托者,用心躁也。", "b": "《荀子·劝学》"}], "words": [{"w": "鳝鱼", "t": "黄鳝"}, {"w": "鳝羹", "t": "以鳝鱼烹成的佳肴"}, {"w": "鳝脯", "t": "鳝鱼干肉"}, {"w": "鳝丝", "t": "鳝鱼切成丝的菜肴。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6444wx','鳟','1','zūn','鱼','20','','[{"pinyin": "zūn", "defs": [{"meaning": "鳟鱼。", "cites": [{"t": "鳟,赤目鱼也。从鱼,尊声。", "b": "《说文》"}, {"t": "鮅鳟。", "b": "《尔雅》。"}]}, {"meaning": "亦称赤眼鳟,红眼鱼。原产于欧洲溪流中的常见鱼(Salmo trutta),现已见于全世界很多地方,绝大部分是留居在清冷的淡水区;由于颜色鲜丽,肉味芳美。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6445wx','獾','1','huān','犭','20','','[{"pinyin": "huān", "defs": [{"meaning": "鼬科哺乳类之獾属(Meles)动物的泛称 。体型粗壮,善掘土,广泛分布于北半球。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6446wx','孀','1','shuāng','女','20','','[{"pinyin": "shuāng", "defs": [{"meaning": "(形声。从女,霜声。本义:丈夫死亡后未再结婚的女人) 同本义。", "cites": [{"t": "邻人京城氏之孀妻有遗男,始龀,跳往助之。", "b": "《列子·汤问》"}], "words": [{"w": "孀居;孤孀", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6447wx','骧','1','xiāng','马','20','','[{"pinyin": "xiāng", "defs": [{"meaning": "腾跃;昂首奔驰。", "cites": [{"t": "骧,马之低卬也。从马、襄声。", "b": "《说文》"}, {"t": "乃奋翅而腾骧。", "b": "张衡《西京赋》。注:“驰也。”"}, {"t": "四骐龙骧。", "b": "左思《吴都赋》"}, {"t": "载车奔兮马繁骧。", "b": "曹植《离友》"}], "words": [{"w": "骧腾", "t": "驰骋。"}]}, {"meaning": "仰;上举。", "cites": [{"t": "臣父骧眉扼腕,恨不从杨涟诸臣后。", "b": "清·彭定求《周端孝先生传》"}], "words": [{"w": "骧首", "t": "抬头。"}]}, {"meaning": "后右足白的马。", "cites": [{"t": "后右足白骧。", "b": "《尔雅·释畜》"}]}, {"meaning": "泛指马。", "cites": [{"t": "《诗》云:“两服,上骧”。注云:“骧,马”。是也。", "b": "司马贞索隐《史记》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6448wx','瓘','1','guàn','王','21','','[{"pinyin": "guàn", "defs": [{"meaning": "古书上指一种玉。", "cites": [{"t": "瓘,玉也。从玉,雚声。", "b": "《说文》"}, {"t": "若我用瓘斝玉瓒,郑必不火。", "b": "《左传·昭公十七年》。注:“圭也。”"}, {"t": "齐陈王瓘字子五。", "b": "《左传·哀公十五年》"}]}]}]','jingmo-wenyan');
