INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6453wx','曩','1','nǎng','日','21','','[{"pinyin": "nǎng", "defs": [{"meaning": "(形声。从日,襄声。本义:以往,过去) 同本义。", "cites": [{"t": "曩,久也。", "b": "《尔雅》"}, {"t": "曩者,尔心或开予。", "b": "《礼记·檀弓》"}, {"t": "曩者,志人而已。", "b": "《左传·襄公二十四年》"}, {"t": "曩而言戏乎。", "b": "《国语·晋语》"}, {"t": "犹有曩之态也。", "b": "《楚辞·惜诵》"}, {"t": "曩令樊郦绛灌。", "b": "《汉书·贾谊传》"}, {"t": "曩与吾祖居者,今其室十无一焉。", "b": "唐·柳宗元《捕蛇者说》"}, {"t": "曩胡公按部。", "b": "清·张廷玉《明史》"}], "words": [{"w": "曩日", "t": "往日,以前"}, {"w": "曩分", "t": "旧日的情分"}, {"w": "曩年", "t": "以前"}, {"w": "曩时", "t": "昔时;往时;以前"}, {"w": "曩贤", "t": "先贤"}, {"w": "曩怀", "t": "昔日之情怀;以前的抱负"}, {"w": "曩体", "t": "以前的体例、规模"}, {"w": "曩古", "t": "古代,往古"}, {"w": "曩列", "t": "旧时的同僚。"}]}]}]','jingmo-wenyan');
