('6460wx','禳','1','ráng','礻','21','','[{"pinyin": "ráng", "defs": [{"meaning": "祭名。祈祷消除灾殃、去邪除恶之祭。", "cites": [{"t": "禳乃入。", "b": "《仪礼·聘礼》。注:“祭名也。”"}, {"t": "齐有彗星,齐侯使禳之。", "b": "《左传·昭公二十六年》"}], "words": [{"w": "禳灾", "t": "禳除灾祸"}, {"w": "禳星", "t": "禳除凶星"}, {"w": "禳解", "t": "向神祈求解除灾祸"}, {"w": "禳保", "t": "祭祀神祖,去邪除恶,求其保护"}, {"w": "禳除", "t": "祭神除灾"}, {"w": "禳避", "t": "祭神避祸"}, {"w": "禳祷", "t": "祭神以消灾祈福。"}]}, {"meaning": "去除。", "cites": [{"t": "[五月五日]采艾以为人,悬门户上,以禳毒气。", "b": "梁宗懔《荆楚岁时记》"}]}]}]','jingmo-wenyan');
