('6462wx','羼','1','chàn','尸','21','','[{"pinyin": "chàn", "defs": [{"meaning": "本义:群羊杂居。", "cites": [{"t": "羼,羊相厠也。从羊,在尸下。尸,屋也。会意。一曰相出前也。", "b": "《说文》"}]}, {"meaning": "混杂。", "cites": [{"t": "他父亲又不肯住在家里,只在都中城外和那些道士们胡羼。", "b": "《红楼梦》"}]}, {"meaning": "引申为搀杂。", "words": [{"w": "羼入", "t": "搀入"}, {"w": "羼名", "t": "混入名藉"}, {"w": "羼和", "t": "把不同的东西掺混在一起。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6463wx','蠡','1','lí lǐ luó','虫','21','','[{"pinyin": "lí", "defs": [{"meaning": "瓠瓢,用葫芦做的瓢。", "cites": [{"t": "以蠡测海。", "b": "《汉书·东方朔传》"}], "words": [{"w": "蠡升", "t": "容量一升的瓢子"}, {"w": "蠡帽", "t": "防矢石的盔帽。其形似瓠瓢,故名"}, {"w": "蠡勺", "t": "一瓢勺"}, {"w": "蠡见", "t": "喻肤浅的见识"}, {"w": "蠡酌管窥", "t": "用瓢量海水,从竹管里看天。比喻见识浅薄,对事物的观察和了解很片面。"}]}]}, {"pinyin": "lǐ", "defs": [{"meaning": "虫蛀木 。引申为器物久磨将断的样子。", "cites": [{"t": "蠡,虫啮木中也。", "b": "《说文》。段玉裁注:“蠡之言剺也,如刀剺物。”"}, {"t": "以追蠡。", "b": "《孟子》"}]}]}, {"pinyin": "luó", "defs": [{"meaning": "蜾蠃。", "cites": [{"t": "谅不登樔而椓蠡兮,得不陈力而相追。", "b": "汉·班昭《东征赋》。注:“蠡与蠃古字通。”"}]}]}]','jingmo-wenyan');
