('6465wx','懿','1','yì','心','22','','[{"pinyin": "yì", "defs": [{"meaning": "(形声。从壹,恣声。“壹”表示专一。本义:美好)。"}, {"meaning": "同本义。", "cites": [{"t": "懿,美也。", "b": "《尔雅》"}, {"t": "好是懿德。", "b": "《诗·大雅·庶民》"}, {"t": "斯则前世之懿事。", "b": "《三国志·吴主传》"}, {"t": "茂学懿文。", "b": "白居易《斐度中书舍人制》"}, {"t": "以就懿德。", "b": "《后汉书·列女传》"}], "words": [{"w": "懿盛", "t": "因皇室宗亲而名位显盛"}, {"w": "懿范", "t": "美好的风范。多用于赞扬妇女美德"}, {"w": "懿明", "t": "德高智明"}, {"w": "懿士", "t": "有美德的人。"}]}]}]','jingmo-wenyan');
