INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6470wx','饕','1','tāo','飠','22','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从食,號(hào)声。本义:极贪欲;极贪财) 同本义。", "cites": [{"t": "饕,贪也。", "b": "《说文》"}, {"t": "贪财为饕,贪食为餮。", "b": "《左传·文公十八年》注"}, {"t": "饕贪而无厌;近利而好得者,可亡也。", "b": "《韩非子·亡征》"}], "words": [{"w": "饕残", "t": "贪婪残酷"}, {"w": "饕淫", "t": "贪婪荒淫"}, {"w": "饕沓", "t": "贪得无厌"}, {"w": "饕湎", "t": "贪酒"}, {"w": "饕餮王孙", "t": "贪吃嗜欲的贵族子弟"}, {"w": "饕餮放横", "t": "贪婪凶恶,横行无忌"}, {"w": "饕戾", "t": "贪戾。"}]}]}]','jingmo-wenyan');
