INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6473wx','镵','1','chán','钅','22','','[{"pinyin": "chán", "defs": [{"meaning": "犁铁,即犁头 。与铧相类而形制不同,锐利厚重,适宜开垦生地。也指装有弯曲长柄的长鑱,用以掘土。", "cites": [{"t": "使史更敝衣,草屦,背筐,手长镵,为除不洁者。", "b": "清·方苞《左忠毅公逸事》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6474wx','穰','1','ráng rǎng','禾','22','','[{"pinyin": "ráng", "defs": [{"meaning": "(形声。从禾,襄(xiāng)声。本义:禾茎中白色柔软的部分。也指瓜果的肉)。"}, {"meaning": "同本义。"}, {"meaning": "丰收。", "cites": [{"t": "世之有饥穰,天之行也,禹汤被之矣。", "b": "汉·贾谊《论积贮疏》"}, {"t": "穰岁之秋。", "b": "《韩非子·五蠹》"}], "words": [{"w": "穰川", "t": "获得丰收的平原地方"}, {"w": "穰岁", "t": "丰年。"}]}, {"meaning": "泛指黍稷稻麦等植物的杆茎。", "cites": [{"t": "烧黍穰。", "b": "贾思勰《齐民要术·种谷》"}], "words": [{"w": "穰子", "t": "刍料;喂牲口的草。"}]}, {"meaning": "饱满的稻粒。", "cites": [{"t": "凡稻最佳者九穰一秕,…则六穰四秕者容有之。", "b": "《天工开物》"}]}, {"meaning": "填,充实。", "cites": [{"t": "心是虚底物,性是里面穰肚馅草。性之理包在心内,到发时却是性底出来。", "b": "《朱子语类》"}]}, {"meaning": "祭名,去邪除恶之祭。", "cites": [{"t": "见道旁有穰田者。", "b": "《史记·滑稽淳于髡传》"}]}]}, {"pinyin": "rǎng", "defs": [{"meaning": "盛多;众多。", "cites": [{"t": "高唐州城池虽小,人稠物穰,军广粮多。", "b": "《水浒全传》"}], "words": [{"w": "穰浩", "t": "众多"}, {"w": "穰穰", "t": "众多。"}]}, {"meaning": "繁荣。", "cites": [{"t": "长安中浩穰,于三辅尤为剧。", "b": "《汉书》"}]}, {"meaning": "兴旺;旺盛。", "cites": [{"t": "汉世之论,自贾谊已繁穰,其次渐与辞赋同流。", "b": "章炳麟《国故论衡·论式》"}]}, {"meaning": "中国物理学会曾作为1018的词头的用字 ——国际制用“艾可萨”,简称“艾”,符号E。"}, {"meaning": "万万秭。", "cites": [{"t": "凡大数之法,万万曰亿,…万万秭曰穰,万万穰曰沟。", "b": "《孙子算经》"}]}, {"meaning": "烦扰", "cites": [{"t": "又不是公事忙,不由咱心绪穰。", "b": "孟汉卿《魔合罗》"}]}, {"meaning": "塞;填塞。", "cites": [{"t": "高抬在衣架上怕吹了颜色,乱穰在包袱中恐剉了折儿。", "b": "王实甫《西厢记》"}]}, {"meaning": "古县名 。战国时楚邑,秦置县,治 所在今河南省邓县。", "cites": [{"t": "其秋,复与秦王会穰。", "b": "《史记·楚世家》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6475wx','饔','1','yōng','飠','22','','[{"pinyin": "yōng", "defs": [{"meaning": "熟食。", "cites": [{"t": "酒车酌礼,方驾授饔。", "b": "张衡《西京赋》"}], "words": [{"w": "饔餐", "t": "饭食。"}]}, {"meaning": "专指早餐。", "cites": [{"t": "贤者与民并耕而食,饔飧而治。", "b": "《孟子·滕文公》。注:“饔飧,熟食也,朝曰饔,夕曰飧。”"}, {"t": "但是贾昌在家,朝饔夕餐,也还成个规矩,口中假意奉承几句。", "b": "《醒世恒言》"}]}, {"meaning": "做饭;烹煮。", "cites": [{"t": "亲二宫之饔膳,致晨昏之定省。", "b": "《汉书·杜周传》"}], "words": [{"w": "饔人", "t": "官名。掌切割烹调之事"}, {"w": "饔夫", "t": "饔子。厨工"}, {"w": "饔膳", "t": "备办酒饭。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6476wx','鬻','1','yù','鬲','22','','[{"pinyin": "yù", "defs": [{"meaning": "(形声。(zhōu)本义:粥。引申为“卖”)。"}, {"meaning": "卖,出售。", "cites": [{"t": "鲋也鬻狱。", "b": "《左传·昭公十四年》"}, {"t": "市贱鬻贵。", "b": "《国语·齐语》"}, {"t": "人争鬻之。", "b": "明·刘基《卖柑者言》"}, {"t": "明告鬻梅者。", "b": "清·龚自珍《病梅馆记》"}], "words": [{"w": "鬻卜", "t": "卖卦"}, {"w": "鬻文", "t": "为人撰写文章而接受酬劳。即“卖文”"}, {"w": "鬻技", "t": "出卖技艺以谋生"}, {"w": "鬻歌", "t": "卖歌,以歌唱谋生"}, {"w": "鬻爵", "t": "出卖官爵。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6477wx','鬟','1','huán','髟','23','','[{"pinyin": "huán", "defs": [{"meaning": "妇女的梳成环形的发卷。", "cites": [{"t": "鬟,总发也。从髟(biāo),睘(qióng)声。", "b": "《说文》。郑珍注:“谓盘鬟如环。”"}, {"t": "香雾云鬟湿,清浑玉臂寒。", "b": "杜甫《月夜》诗"}, {"t": "绿云扰扰,梳晓鬟也。", "b": "唐·杜牧《阿房宫赋》"}, {"t": "风鬟雨鬓。", "b": "唐·李朝威《柳毅传》"}]}, {"meaning": "婢女。", "cites": [{"t": "欲买小鬟试教之,教坊供奉谁知者。", "b": "宋·梅尧臣《听文都知吹箫》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6478wx','趱','1','zǎn','走','23','','[{"pinyin": "zǎn", "defs": [{"meaning": "催促;逼使。", "cites": [{"t": "皂隶挥鞭趱行路,躜尔今朝入关去。", "b": "姚燮《粮船行》"}], "words": [{"w": "趱逼", "t": "催迫"}, {"w": "趱马向前", "t": ""}]}, {"meaning": "赶;加快;加紧。", "cites": [{"t": "长江后浪催前浪,一替新人趱旧人。", "b": "《张协状元》"}], "words": [{"w": "趱工", "t": "赶工、赶活"}, {"w": "趱快", "t": "犹赶快"}, {"w": "趱行", "t": "趱路。赶路"}, {"w": "趱办", "t": "趱干,赶快办理"}, {"w": "趱运", "t": "赶快运送。"}]}, {"meaning": "积蓄。", "cites": [{"t": "你积趱的金银过北斗。", "b": "《陈州粜米》"}], "words": [{"w": "趱足", "t": "积蓄"}, {"w": "趱钱;趱物;趱家私", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6479wx','攫','1','jué','扌','23','','[{"pinyin": "jué", "defs": [{"meaning": "(形声。从手,矍(jué)声。本义:鸟用爪迅速抓取)。"}, {"meaning": "同本义。", "cites": [{"t": "攫,执也。", "b": "《说文》"}, {"t": "鸷虫攫搏。", "b": "《礼记·儒行》"}, {"t": "盗跖弗攫。", "b": "《史记·李斯传》。索隐:“凡鸟翼击物曰搏,足取曰攫。”"}, {"t": "鸟攫其肉。", "b": "《汉书·黄霸传》"}], "words": [{"w": "攫取", "t": "抓取;拿取"}, {"w": "攫捷", "t": "抓取;猎获"}, {"w": "攫啄", "t": "以爪抓取,以嘴啄食"}, {"w": "攫搏", "t": "鸟兽以爪翅猎物"}, {"w": "攫噬", "t": "抓取而吞噬。"}]}, {"meaning": "夺取。", "cites": [{"t": "备兽触攫。", "b": "《周礼·兽人》注"}, {"t": "乳犬攫虎。", "b": "《公羊传·庄公十二年》"}, {"t": "左手攫之,而右手废。", "b": "《庄子·让王》"}], "words": [{"w": "攫攘", "t": "争夺"}, {"w": "攫窃", "t": "窃夺"}, {"w": "攫昼", "t": "白昼抢劫"}, {"w": "攫盗", "t": "盗取,窃取。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6480wx','攥','1','zuàn','扌','23','','[{"pinyin": "zuàn", "defs": [{"meaning": "用手抓住或抓稳。", "cites": [{"t": "一见是宝玉,又惊又喜,又悲又痛,一把死攥住他的手,哽咽了半日。", "b": "《红楼梦》"}], "words": [{"w": "攥手", "t": "抓住手"}, {"w": "手里攥着一把斧子", "t": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6481wx','颧','1','quán','页','23','','[{"pinyin": "quán", "defs": [{"meaning": "颧骨。亦称“颊骨”、“輔骨” 。位于眼的外下方,在颜面部隆起的部分", "words": [{"w": "颧輔", "t": "颧骨和齿床"}, {"w": "颧颊", "t": "借指面容"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6482wx','躜','1','zuān','足','23','','[{"pinyin": "zuān", "defs": [{"meaning": "向上或向前冲。", "cites": [{"t": "上下躜动,像渴望出航。", "b": "《阿尔卑斯山》"}], "words": [{"w": "燕子躜天", "t": ""}]}, {"meaning": "钻,穿。", "cites": [{"t": "母狼躜篱笆——进退两难。——《中国谚语资料》", "b": ""}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6483wx','鼹','1','yǎn','鼠','23','','[{"pinyin": "yǎn", "defs": [{"meaning": "鼹鼠 ,穴居哺乳动物,属鼹科(Talpidae),主要产于欧亚、北美的温带,细小的眼上常蒙着皮肤,小耳隐在毛里,毛皮柔软而有光泽,有坚强善跳的足", "words": [{"w": "鼹鼠饮河", "t": "喻指欲望不大,极易满足"}, {"w": "鼹肠", "t": "田鼠的细小肠子。用以比喻度量狭小"}]}]}]','jingmo-wenyan');
