INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6485wx','麟','1','lín','鹿','23','','[{"pinyin": "lín", "defs": [{"meaning": "(形声。从鹿,粦(lìn)声。本义:大鹿)。"}, {"meaning": "同本义。", "cites": [{"t": "麟,大牝鹿也。", "b": "《说文》"}, {"t": "麐,牝麒也。", "b": "《说文》。朱骏声曰:“经典皆以麟为之。”段曰:“经典无作麐者。”"}, {"t": "射麋脚麟。", "b": "汉·司马相如《子虚赋》"}, {"t": "解罘放麟。", "b": "张衡《东京赋》。薛注:“大鹿曰麟。”"}, {"t": "惧失麟鹿而获艾貑。", "b": "《潜夫论·贤难》"}]}, {"meaning": "麒麟。", "cites": [{"t": "单呼麟者,大牡鹿也;呼麟麟者,仁兽也。麒麟可单呼麟。", "b": "《说文》段注"}, {"t": "西狩获麟。", "b": "《春秋·哀公十四年》"}], "words": [{"w": "凤毛麟角;麟阁", "t": "又称麟台。麒麟阁,汉宣帝时曾在麒麟阁内绘功臣图像,以表其功"}, {"w": "麟趾", "t": "麟足"}, {"w": "麟符", "t": "刻画麟状的信物"}, {"w": "麟游", "t": "麒麟遨游。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6486wx','蠲','1','juān','虫','23','','[{"pinyin": "juān", "defs": [{"meaning": "虫名 。又名“马蠲”、“马陆”。俗称“香油虫”。"}, {"meaning": "除去、驱出、去掉。同“捐”。", "cites": [{"t": "宜弘大务,蠲略细微。", "b": "《后汉书·虑植传》"}, {"t": "十家租税九家毕,虚受吾君蠲免恩。", "b": "白居易《杜陵叟》"}], "words": [{"w": "蠲资", "t": "出资"}, {"w": "蠲恤", "t": "免去劳役赋税等项,并给与安慰或救济"}, {"w": "蠲疴", "t": "除去疾病"}, {"w": "蠲丁", "t": "免除丁口钱"}, {"w": "蠲欠", "t": "免除积欠租税"}, {"w": "蠲平", "t": "消除平息。"}]}, {"meaning": "清除,疏通。", "cites": [{"t": "应时而蠲。", "b": "扬雄《劇秦美新》"}, {"t": "蠲浊而流清。", "b": "柳宗元《永州韦使君新堂记》"}], "words": [{"w": "蠲疏", "t": "清除疏通"}, {"w": "蠲涤", "t": "清除,除去"}, {"w": "蠲荡", "t": "清除;废除。"}]}, {"meaning": "使清洁。", "cites": [{"t": "剖腹以蠲肠。", "b": "《晋书·皇甫谧传》"}], "words": [{"w": "蠲洁", "t": "清洁;明洁"}]}, {"meaning": "明示,显示。", "cites": [{"t": "惠公蠲其大德。", "b": "《左传》"}]}, {"meaning": "择取。", "cites": [{"t": "图厥政,不蠲蒸,天惟降时丧。", "b": "《书·多方》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6487wx','蠹','1','dù','虫','24','','[{"pinyin": "dù", "defs": [{"meaning": "(形声。本义:蛀虫)。"}, {"meaning": "同本义。", "cites": [{"t": "蠹,木中虫。", "b": "《说文》"}, {"t": "掌蠹物。", "b": "《周礼·翦氏》。注:“穿食人器物者,蠹鱼亦是也。”"}, {"t": "树郁则为蠹。", "b": "《吕氏春秋·达郁》。注:“蠹蝎木中之虫也。”"}], "words": [{"w": "蠹役", "t": "欺压百姓的吏役"}, {"w": "蠹怪", "t": "蠹虫的精怪"}, {"w": "蠹薮", "t": "蛀虫聚集的地方"}, {"w": "蠹贼", "t": "蠹,蠹虫;贼,蟊贼"}, {"w": "蠹蝎", "t": "水中的蠹虫"}, {"w": "木蠹;蠹字", "t": "蠹虫所蚀如字的痕迹"}, {"w": "蠹物", "t": "本指穿蚀衣服的蠹虫。引申泛指为害之物。"}]}, {"meaning": "引申以喻侵蚀或消耗国家财富的人或事。", "cites": [{"t": "独是成氏子以蠹贫,以促织富,裘马扬扬。", "b": "《聊斋志异·促织》"}], "words": [{"w": "蠹民", "t": "指害人的人或事物"}, {"w": "蠹政", "t": "害民的政令"}, {"w": "蠹言", "t": "害人的言辞"}, {"w": "蠹役书办", "t": "腐败,刁钻的吏役书办。"}]}, {"meaning": "蛀蚀。", "cites": [{"t": "是勤可以远淫辟地,户枢不蠹,流水不腐。", "b": "宋·罗大经《鹤林玉露补遗》"}], "words": [{"w": "蠹木", "t": "蛀坏的梁木"}, {"w": "蠹心", "t": "蛀蚀内部"}, {"w": "蠹书", "t": "蠹册。被虫蛀坏的书"}, {"w": "蠹国", "t": "侵蚀、危害国家"}, {"w": "蠹朽", "t": "木材被蠹腐烂。"}]}]}]','jingmo-wenyan');
