('6488wx','躞','1','xiè','足','24','','[{"pinyin": "xiè", "defs": [{"meaning": "书卷的杆轴。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6489wx','衢','1','qú','行','24','','[{"pinyin": "qú", "defs": [{"meaning": "(形声。从行,瞿声。行,本义是道路。本义:四通八达的道路)。"}, {"meaning": "同本义。", "cites": [{"t": "衢,四达谓之衢。", "b": "《说文》"}, {"t": "必于四面之衢。", "b": "《大戴礼记·子张问入官》"}, {"t": "何天之衢。", "b": "《易·大畜》"}, {"t": "一兔走衢,万人逐之,一人获之,贪者悉止。", "b": "《三国志》裴松之注"}, {"t": "填街盈衢。", "b": "柳宗元《国子司业阳城遗爱碣》"}, {"t": "街衢相经。", "b": "张衡《西京赋》"}], "words": [{"w": "大衢;长衢;通衢", "t": "四通八达的道路"}, {"w": "衢逵", "t": "道路"}, {"w": "衢处", "t": "处于四通八达之地"}, {"w": "衢国", "t": "地处要冲的国家。"}]}, {"meaning": "树枝交错、分岔。", "cites": [{"t": "宣山,其上有桑焉,大五十尺,其枝四衢。", "b": "《山海经》"}]}, {"meaning": "引申指途径。", "cites": [{"t": "上好羞则民暗饰矣,上好富则民死利矣。二者,乱之衢也。", "b": "《荀子》"}]}, {"meaning": "分岔的道路。"}, {"meaning": "地名 。在浙江省西部。唐置衢州,因境内有三衢山。民国改衢县。今为衢州。"}, {"meaning": "歧,岔。", "cites": [{"t": "行衢道者不至。", "b": "《荀子·劝学》"}, {"t": "千乘衢处壤削太半。", "b": "《管子·国蓄》"}], "words": [{"w": "衢涂;衢道", "t": "歧路,岔路"}, {"w": "衢路", "t": "歧路;岔道。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
