INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6498wx','戆','1','gàng zhuàng','心','25','','[{"pinyin": "gàng", "defs": [{"meaning": "[方言] 鲁莽,冒失", "words": [{"w": "戆言", "t": "言语鲁莽、冒失"}, {"w": "戆激", "t": "鲁莽而激烈"}]}]}, {"pinyin": "zhuàng", "defs": [{"meaning": "愚蠢(侧重于迂直、不知变通)。", "cites": [{"t": "戆,愚也。从心,赣声。", "b": "《说文》"}, {"t": "悍戆好斗。", "b": "《荀子·大略》"}, {"t": "狂惑戆陋之人。", "b": "《荀子·儒效》"}, {"t": "然陵少戆,陈平可以助之。", "b": "《史记·高祖本纪》》"}, {"t": "甚矣,汲黯之戆也。", "b": "《史记·汲郑列传》"}], "words": [{"w": "戆冥", "t": "愚鲁昏昧"}, {"w": "戆士", "t": "愚昧之人"}, {"w": "戆大", "t": "方言。犹傻瓜"}, {"w": "戆陋", "t": "愚昧浅陋"}, {"w": "戆昧", "t": "愚昧"}, {"w": "戆钝", "t": "愚笨。"}]}, {"meaning": "憨厚而刚直。", "cites": [{"t": "益戆由来未觉贤,终须南去吊湘川。", "b": "杜牧《商山富水驿》"}, {"t": "信着俺小叔莽戆多英勇。", "b": "元·佚名《千里独行》"}], "words": [{"w": "戆士", "t": "迂愚而刚直的人"}, {"w": "戆介", "t": "迂直耿介"}, {"w": "戆拙", "t": "迂直诚实。"}]}]}]','jingmo-wenyan');
