('6499wx','爨','1','cuàn','火','30','','[{"pinyin": "cuàn", "defs": [{"meaning": "烧火做饭。", "cites": [{"t": "爨,炊也。", "b": "《广雅》"}, {"t": "取其进火谓之爨,取其气上谓之炊。", "b": "《说文系传》"}, {"t": "许子以釜甑爨,以铁耕乎?", "b": "《孟子·滕文公上》"}], "words": [{"w": "爨人", "t": "爨夫。厨师"}, {"w": "爨室", "t": "厨房"}, {"w": "爨妇", "t": "执炊的女人。"}]}, {"meaning": "烧;烧煮。", "cites": [{"t": "常若微雷响,以草爨之,则烟腾火发。", "b": "《水经注》"}]}, {"meaning": "炉灶。一种土、陶制的厨房炉子、灶。", "cites": [{"t": "翻怜爨下劳薪。", "b": "张炎《风人松》"}], "words": [{"w": "爨下", "t": "灶下"}, {"w": "爨火灶膛里的火;爨烟", "t": "吹烟。"}]}]}]','jingmo-wenyan');
