('6503wx','彳','1','chì','彳','3','','[{"pinyin": "chì", "defs": [{"meaning": "(象形。小篆字字形象“行”,象纵横相交的十字路。“彳”是汉字部首之一,习惯上称为双人旁。从“彳”的字多与行走、行为和道路有关。本义:慢步行走)同本义。", "cites": [{"t": "彳,小步也。象人胫三属相连也。", "b": "《说文》。谓股、胫、足三属。"}, {"t": "彳亍中辍。", "b": "潘岳《射雉赋》"}], "words": [{"w": "彳彳亍亍", "t": "脚步声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6504wx','卬','1','áng yǎng','卩','4','','[{"pinyin": "áng", "defs": [{"meaning": "我。", "cites": [{"t": "招招舟子,人涉卬否。", "b": "《诗·邶风·匏有苦叶》"}]}, {"meaning": "抬起;抬高。", "cites": [{"t": "卬车以其辕表门。", "b": "《谷梁传·昭公八年》范守注"}, {"t": "万物卬贵,过平一钱,则以平贾卖与民。", "b": "《汉书·食货志》"}]}, {"meaning": "激励。", "cites": [{"t": "意慷慨而自卬。", "b": "司马相如《长门赋》"}]}]}, {"pinyin": "yǎng", "defs": [{"meaning": "(“仰”的古字)。"}, {"meaning": "向上;抬头向上。", "cites": [{"t": "卬,望欲有所庶及也。从匕,从卩,会意。", "b": "《说文》"}, {"t": "瞻卬昊天。", "b": "《诗·大雅·云汉》"}, {"t": "卬引弓射。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "卬望", "t": "抬头向上看"}, {"w": "卬首", "t": "抬头"}, {"w": "卬曲", "t": "俯仰,高低。"}]}, {"meaning": "仰仗;依赖。", "cites": [{"t": "上足卬则下可用也。", "b": "《荀子·议兵》"}, {"t": "卬关而攻秦。", "b": "贾谊《过秦论》"}], "words": [{"w": "卬食", "t": "谓依人为生"}, {"w": "卬给", "t": "赖以供给。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6505wx','殳','1','shū','殳','4','','[{"pinyin": "shū", "defs": [{"meaning": "(象形,甲骨文字形,象手持一种长柄勾头似的器具,可以取物,可以打击乐器,后成为兵器。本义:一种用竹或木制成的,起撞击或前导作用的古代兵器)。"}, {"meaning": "同本义。", "cites": [{"t": "殳,以杖殊人也。", "b": "《说文》。段注:“杖者,殳用积竹而无刃”。毛传:“殳长丈二而无刃是也。殊,断也。”"}, {"t": "殳以积竹、八觚,长丈二尺,建于兵车。", "b": "《周礼》"}, {"t": "授旅贲殳。", "b": "《周礼·司戈盾》"}, {"t": "执殳而立于道左。", "b": "《左传·昭公二十三年》"}, {"t": "伯也执殳,为王前驱。", "b": "《诗·卫风·伯兮》"}], "words": [{"w": "殳仗", "t": "古代宫廷中的一种仪仗。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
