('6550wx','讻','1','xiōng','讠','6','','[{"pinyin": "xiōng", "defs": [{"meaning": "(形声。从言,凶声。本义:争辩)。"}, {"meaning": "同本义。", "cites": [{"t": "讻,说也。", "b": "《说文》。六书故引唐本说文,讼也。"}, {"t": "讻,讼也。", "b": "《尔雅》"}, {"t": "听漠漠而以为哅哅。", "b": "《荀子·解蔽》"}, {"t": "穷凶势犹竞,杀伐声更讻。", "b": "宋·曾巩《青云亭闲望》"}, {"t": "不告于讻,在泮献功。", "b": "《诗·鲁颂·泮水》"}, {"t": "辩讼公门之下,讻讻不可胜听。", "b": "《盐铁论》"}], "words": [{"w": "讻讻", "t": "喧扰"}, {"w": "讻动", "t": "喧哗纷扰。"}]}, {"meaning": "恐吓。", "cites": [{"t": "伊等技穷,知讻余不恸,乃赴南关质库。", "b": "清·高绍陈《永清庚年纪略》"}], "words": [{"w": "讻惧", "t": "惊惧不安的样子。"}]}, {"meaning": "祸乱。", "cites": [{"t": "昊天不傭,降此鞠讻。", "b": "《诗·小雅·节南山》"}]}, {"meaning": "兇恶。", "cites": [{"t": "家父作诵,以究王讻。", "b": "《诗·小雅·节南山》"}]}]}]','jingmo-wenyan');
