('6607wx','飏','1','yáng','风','7','','[{"pinyin": "yáng", "defs": [{"meaning": "飞扬;飘扬。", "cites": [{"t": "飏,风所飞扬也。", "b": "《说文》"}, {"t": "风飏电激。", "b": "《汉书·叙传》"}, {"t": "曳红采之流离兮,飏翠气之宛延。", "b": "汉·扬雄《甘泉赋》"}], "words": [{"w": "飏尘", "t": "尘土飞扬"}, {"w": "飏幕", "t": "风吹开帘幕"}, {"w": "飏飏", "t": "飞翔的样子。即翩翩"}, {"w": "飏空", "t": "在空中飘扬"}, {"w": "飏簸", "t": "向上抛撒谷物,以扬出杂物"}, {"w": "飏扇", "t": "古扬谷器。"}]}, {"meaning": "扬举。", "cites": [{"t": "江风飏帆急,山月下楼迟。", "b": "唐·许浑《送客归峡中》"}], "words": [{"w": "飏帆", "t": "船扬帆而进。同扬帆。"}]}, {"meaning": "显扬。", "cites": [{"t": "将美匡丑,对飏休光。", "b": "汉《冀州从事张表碑》"}], "words": [{"w": "飏菁", "t": "显扬华美"}, {"w": "飏荣", "t": "显出美丽"}, {"w": "飏累", "t": "因说好话而受牵连"}, {"w": "飏金", "t": "以金箔装饰佛像。"}]}, {"meaning": "扬声,大声。", "cites": [{"t": "雄朔野以飏声。", "b": "《汉书·叙传》"}], "words": [{"w": "飏言", "t": "扬声大言。同扬言"}, {"w": "飏声", "t": "高声。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6608wx','狃','1','niǔ','犭','7','','[{"pinyin": "niǔ", "defs": [{"meaning": "习惯;习以为常。", "cites": [{"t": "狃,犬性骄也。", "b": "《说文》。锴本作犬性忖。"}, {"t": "狃,狎也。", "b": "《左传·桓公二年》疏引《说文》"}, {"t": "一夫不可狃。", "b": "《左传·僖公十五年》。注:“忖也。”"}, {"t": "狃于奸宄。", "b": "《伪书·君陈》"}, {"t": "将叔无狃,戒其伤女。", "b": "《诗·郑风·大叔于田》"}, {"t": "狃于寒暑之变。", "b": "宋·苏轼《教战守》"}], "words": [{"w": "狃恩", "t": "习于恩宠。即恃恩"}, {"w": "狃狎", "t": "习惯,习熟"}, {"w": "狃泰", "t": "习惯"}, {"w": "狃习", "t": "熟习;习惯。"}]}, {"meaning": "担任。", "cites": [{"t": "日君乏使,使臣狃中军之司马。", "b": "《国语·晋语七》"}]}, {"meaning": "贪图。", "cites": [{"t": "嗛嗛之食,不足狃也。", "b": "《国语·晋语》"}], "words": [{"w": "狃虓", "t": "贪暴。"}]}]}]','jingmo-wenyan');
