INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6614wx','沄','1','yún','氵','7','','[{"pinyin": "yún", "defs": [{"meaning": "水波汹涌回旋。", "cites": [{"t": "沄,转流也。从水,云声。", "b": "《说文》。按,实与澐同字。"}, {"t": "流水兮沄沄。", "b": "《楚辞·哀岁》"}, {"t": "江水大波谓之沄。", "b": "《说文》"}, {"t": "水泫沄而涌涛。", "b": "张衡《思玄赋》"}]}]}]','jingmo-wenyan');
