('6615wx','沘','1','bǐ','氵','7','','[{"pinyin": "bǐ", "defs": [{"meaning": "〔～源〕地名，中国河南省唐河县的旧称。"}, {"meaning": "〔～江〕水名，在中国云南省。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6617wx','汭','1','ruì','氵','7','','[{"pinyin": "ruì", "defs": [{"meaning": "两条水流汇合处。", "cites": [{"t": "汭,水相入也。", "b": "《说文》"}, {"t": "氂降二女于妫汭。", "b": "《书·尧典》。注:“水所入曰汭。”"}, {"t": "令尹子常以舟师及沙汭而还。", "b": "《左传·昭公二七年》"}]}, {"meaning": "河流、湖泊的弯处。", "cites": [{"t": "馆于洛汭。", "b": "《左传·昭公元年》"}, {"t": "虢公败戎于渭汭。", "b": "《左传》。杜预注:“水之隈曲曰汭。”"}]}, {"meaning": "水滨。", "cites": [{"t": "客绝水而来,勿迎之水汭,令半济而击之,利。", "b": "《孙子》。唐·杜牧注:“水内乃汭也,误为内耳。”"}]}, {"meaning": "水流之北。", "cites": [{"t": "弱水既西,泾属渭汭。", "b": "《书·禹贡》。孔传:“水北曰汭。”"}]}, {"meaning": "水名。"}, {"meaning": "在山西省永济县境。西流注于黄河,传说即舜纳二妃处。"}, {"meaning": "在江西铅山县境,为上饶江支流。"}, {"meaning": "泾水支流,发源于宁夏回族自治区泾源县南,至甘肃泾川县流入泾水。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6619wx','沇','1','yǎn','氵','7','','[{"pinyin": "yǎn", "defs": [{"meaning": "〔～水〕济水的别称，古河名，源出中国河南省，流经山东省入渤海。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6620wx','忮','1','zhì','忄','7','','[{"pinyin": "zhì", "defs": [{"meaning": "强悍,凶狠。", "cites": [{"t": "忮,很也。从心,支声。", "b": "《说文》"}, {"t": "忮,恨也。", "b": "《一切经音义》引《说文》"}, {"t": "长安险固,风俗豪忮。", "b": "《资治通鉴》"}], "words": [{"w": "忮毒", "t": "狠毒"}, {"w": "忮横", "t": "忌刻专横"}, {"w": "忮狠", "t": "忌刻狠毒"}, {"w": "忮恶", "t": "狠毒。"}]}, {"meaning": "嫉妒;忌恨。", "cites": [{"t": "不忮不求,何用不臧?", "b": "《诗·邶风·雄雉》"}, {"t": "鞫人忮忒。", "b": "《诗·大雅·瞻卬》"}, {"t": "大勇不忮。", "b": "《庄子·齐物论》"}], "words": [{"w": "忮刻", "t": "忌恨刻毒;刚愎"}, {"w": "忮嫉", "t": "妒忌"}, {"w": "忮忌", "t": "嫉妒"}, {"w": "忮忍", "t": "嫉妒残忍"}, {"w": "忮悍", "t": "嫉妒而凶悍"}, {"w": "忮害", "t": "嫉忌陷害"}, {"w": "忮心", "t": "嫉恨之心。"}]}, {"meaning": "固执。", "cites": [{"t": "巧行居灾,忮辨召患。", "b": "《读史述九章》"}], "words": [{"w": "忮刻", "t": "褊狭刻薄"}, {"w": "忮辩", "t": "强辩。"}]}, {"meaning": "违逆。", "cites": [{"t": "虽有忮心者,不怨飘瓦,天下不忮于众。", "b": "《庄子·达生》。注:“逆也。”"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6621wx','忳','1','tún zhūn dùn','忄','7','','[{"pinyin": "tún", "defs": [{"meaning": "忧郁烦闷：“～郁邑余侘傺兮。”。"}]}, {"pinyin": "zhūn", "defs": [{"meaning": "诚恳的样子：“纷～～之愿忠兮。”。"}]}, {"pinyin": "dùn", "defs": [{"meaning": "〔～～然〕无知的样子，如“不知治乱存亡之所由，～～～犹醉也。”。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6622wx','忺','1','xiān','忄','7','','[{"pinyin": "xiān", "defs": [{"meaning": "欲,想要。", "cites": [{"t": "满地黄花堆积,憔翠损,如今有谁忺摘。", "b": "《声声慢》"}, {"t": "小雨忺晴,坐来池上荷珠碎。", "b": "宋·张元干《点绛唇》词"}]}, {"meaning": "高兴;快乐。", "cites": [{"t": "清游胜,满意忺。", "b": "清·洪昇《长生殿》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6624wx','祃','1','mà','礻','7','','[{"pinyin": "mà", "defs": [{"meaning": "(形声。从示,马声。从示,与祭祀、鬼神有关。本义:行军时在军队驻扎处举行的祭祀) 同本义。", "cites": [{"t": "是类是祃。", "b": "《诗·大雅·皇矣》"}, {"t": "祃于所征之地。", "b": "《礼记·王制》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6625wx','诇','1','xiòng','讠','7','','[{"pinyin": "xiòng", "defs": [{"meaning": "同本义。", "cites": [{"t": "詗,知处告言之。", "b": "《说文》。字亦作侦"}, {"t": "为中诇长安服虔。", "b": "《史记·淮南王传》。注:“侦候之也。”"}, {"t": "反间为詗。", "b": "《汉书》孟康注"}, {"t": "外则合兵势以重将权,罢小臣诇逻边事,行间谍以离其党。", "b": "宋·司马光《涑水记闻》"}], "words": [{"w": "诇逻", "t": "侦察巡逻"}, {"w": "诇察", "t": "侦察"}, {"w": "诇伺", "t": "谍探"}, {"w": "诇问", "t": "侦察探问"}, {"w": "诇探", "t": "侦探"}, {"w": "诇侦", "t": "刺探侦察。"}]}, {"meaning": "求。", "cites": [{"t": "诇诸史乘,历历可稽。", "b": "梁启超文"}], "words": [{"w": "诇药", "t": ""}]}, {"meaning": "明悟。", "cites": [{"t": "今民儇诇智慧,欲自用,不听上,上必且劝之以赏然后可进,又且畏之以罚然后不敢退。", "b": "《韩非子》"}], "words": [{"w": "诇破", "t": "识破。"}]}]}]','jingmo-wenyan');
