INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6627wx','诎','1','qū','讠','7','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从言,出声。本义:言语钝拙)。"}, {"meaning": "同本义。", "cites": [{"t": "诎,辞塞。", "b": "《广韵》"}, {"t": "诎,字从言,当与吃同意。", "b": "《说文通训定声》"}, {"t": "公输盘诎。", "b": "《墨子·公输》"}, {"t": "轻财重士,辩于心而诎于口。", "b": "《史记·李斯列传》"}]}, {"meaning": "尽,穷尽。", "cites": [{"t": "利出于一孔者,其国无敌;出二孔者,其兵不诎;出三孔者,不可以举兵;出四孔者,其国必亡。", "b": "《管子》"}, {"t": "理诎势穷。", "b": "清·林则徐文"}]}, {"meaning": "声音戛然而止貌。", "cites": [{"t": "叩之,其声清越以长,其终诎然。", "b": "《礼记》。孔颖达疏:“诎谓止绝也。”"}]}, {"meaning": "弯曲。", "cites": [{"t": "诎,屈也。", "b": "《广雅·释诂一》"}, {"t": "诎五指而顿之。", "b": "《荀子·劝学》"}, {"t": "诎要桡腘。", "b": "《荀子·富国》"}, {"t": "诎右臂支船。", "b": "明·魏学洢《核舟记》"}], "words": [{"w": "诎伸", "t": "诎申。弯曲与伸直"}, {"w": "诎曲", "t": "诎折。弯曲"}, {"w": "诎体", "t": "弯曲肢体"}, {"w": "诎膝", "t": "下跪"}, {"w": "诎柔", "t": "屈曲柔弱。"}]}, {"meaning": "屈服。", "cites": [{"t": "然而敌国不待试而诎。", "b": "《荀子·议兵》"}, {"t": "诎敌国。", "b": "《战国策·秦策一》"}], "words": [{"w": "诎意", "t": "屈就"}, {"w": "诎志", "t": "曲意迁就"}, {"w": "诎服", "t": "屈服。"}]}, {"meaning": "屈辱;冤屈。", "cites": [{"t": "宋王因怒而诎杀之。", "b": "《吕氏春秋·壅塞》"}], "words": [{"w": "诎身", "t": "降低身分,屈己下人"}, {"w": "诎辱", "t": "委屈和耻辱"}, {"w": "诎容", "t": "屈辱容忍"}, {"w": "诎节", "t": "降低身分,降心相从。"}]}, {"meaning": "（chu）。贬退。", "cites": [{"t": "彼公仲者,秦势能诎之。", "b": "《战国策·韩策三》"}, {"t": "可谓能诎免变化以致之。", "b": "《说苑·敬慎》"}]}, {"meaning": "止。", "cites": [{"t": "叩之其声清越以长,其终诎然,乐也。", "b": "《礼记·聘义》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6628wx','诐','1','bì','讠','7','','[{"pinyin": "bì", "defs": [{"meaning": "(形声。从言,皮声。本义:辩论)。"}, {"meaning": "同本义。", "cites": [{"t": "诐,辩论也。", "b": "《说文》。段玉裁注:“此诐字正义。皮,剥取兽革也。披,析也。凡从皮之字,皆有分析之意,故诐为辩论也。”"}]}, {"meaning": "谄媚。", "cites": [{"t": "险诐阴贼。", "b": "《汉书》"}]}, {"meaning": "(pō)。偏颇,不正。", "cites": [{"t": "不从俗而诐行兮。", "b": "《楚辞·刘向·离世》"}, {"t": "诐辞知其所蔽,淫辞知其所陷,邪辞知其所离。", "b": "《孟子·公孙丑上》"}], "words": [{"w": "诐行", "t": "不正当的行为"}, {"w": "诐辞", "t": "偏颇邪僻的言论。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6629wx','屃','1','xì','尸','7','','[{"pinyin": "xì", "defs": [{"meaning": "壮大的样子。", "cites": [{"t": "苍官屭槐朋在庭,风虫日鸟声嘤咛。", "b": "宋·梅尧臣诗"}], "words": [{"w": "奰屃", "t": "强大有力的样子;蠵龟的别名"}, {"w": "屃护", "t": "犹庇护。"}]}]}]','jingmo-wenyan');
