INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6632wx','阽','1','diàn yán','阝','7','','[{"pinyin": "diàn", "defs": [{"meaning": "(形声。从阜,占声。本义:壁危欲堕)。"}, {"meaning": "同本义。", "cites": [{"t": "阽,壁危也。", "b": "《说文》。王筠句读:“见于群书者,皆但言危,此云壁者,或以其从阜也。”"}]}, {"meaning": "引申为危险。", "cites": [{"t": "阽,危也。", "b": "《广雅》"}], "words": [{"w": "阽切", "t": "危险急迫。"}]}, {"meaning": "病危。", "cites": [{"t": "疾甚谓之阽。", "b": "《小尔雅》。胡承珙义证:“疾甚欲死,如临危欲坠,故谓之阽也。”"}]}, {"meaning": "临近。", "cites": [{"t": "安有为无下阽危者若是而上不惊者?", "b": "汉·贾谊《论积贮疏》"}, {"t": "或阽于死亡。", "b": "《汉书·文帝纪》"}, {"t": "阽危者若是。", "b": "《汉书·食货志》"}, {"t": "阽余身而危死兮。", "b": "《离骚》"}], "words": [{"w": "阽死", "t": "临近死亡。"}]}]}, {"pinyin": "yán", "defs": [{"meaning": "——“阽”(diàn)的又音。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6634wx','阼','1','zuò','阝','7','','[{"pinyin": "zuò", "defs": [{"meaning": "(形声。从阜,乍声。从阜,与建筑有关。本义:大堂前东面的台阶)。"}, {"meaning": "同本义。", "cites": [{"t": "阼,主阶也。", "b": "《说文》。与阶、除同意。"}, {"t": "席主人于阼阶上。", "b": "《仪礼·乡射礼》。注:“东阶也。”"}, {"t": "故冠以阼。", "b": "《礼记·冠义》"}, {"t": "乡人傩,朝服而立于阼阶。", "b": "《论语》"}], "words": [{"w": "阼阶", "t": "东阶。为主人出行立位"}, {"w": "阼席", "t": "主人的席位。"}]}, {"meaning": "借指帝位。天子即位时践阼升殿,因称帝位为阼。", "cites": [{"t": "阼,主也。", "b": "《广雅》。按,天子践阼临祭祀,故国运曰阼。阼,位也,今字亦作祚。"}, {"t": "成王幼,不能莅阼。", "b": "《礼记》"}]}, {"meaning": "国运。也作“祚”。", "cites": [{"t": "王曰:“魏阼所以不长。”谢以为名言。", "b": "《世说新语》"}]}]}]','jingmo-wenyan');
