INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6638wx','纮','1','hóng','纟','7','','[{"pinyin": "hóng", "defs": [{"meaning": "冠冕两旁的带子,下系于颌,上结于呂。", "cites": [{"t": "纮,冠卷也。", "b": "《说文》"}, {"t": "纮,束也,凡笄贯于卷,纮属于笄。", "b": "《广雅·释诂三》"}, {"t": "管仲镂簋而朱纮。", "b": "《礼记·杂记》"}], "words": [{"w": "纮綖", "t": "冠冕。"}]}, {"meaning": "编磐成组的绳子。一说系鼗的绳子。", "cites": [{"t": "鼗倚于颂磬西纮。", "b": "《仪礼·大射礼》。郑玄注:“纮,编磐绳也。”"}]}, {"meaning": "维系。", "cites": [{"t": "招摇乎襄羊,降集乎北纮。", "b": "《史记》。裴纮集解引郭璞曰:“纮,维也。北方之纮曰委羽。”"}]}, {"meaning": "形容中间宽阔。", "cites": [{"t": "[季夏之月]其器圜以闳。", "b": "《礼记》。汉·郑玄注:“闳读如纮,纮谓中宽象土含物。”"}]}, {"meaning": "宏大。", "cites": [{"t": "夫天地之道,至纮以大。", "b": "《淮南子·精神》"}], "words": [{"w": "纮覆", "t": "所覆盖的面积极为广大。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6639wx','驲','1','rì','马','7','','[{"pinyin": "rì", "defs": [{"meaning": "(形声。从马,日声。本义:古代驿站专用的车)。"}, {"meaning": "同本义。后亦指驿马。", "cites": [{"t": "驲,传也。", "b": "《说文》。朱骏声曰:“车曰驲,曰传,马曰驿,曰遞。”"}, {"t": "乘驲而见宣子。", "b": "《左传·襄公二十一年》"}, {"t": "楚子以驲至于罗汭。", "b": "《左传·昭公五年》"}, {"t": "乘驲自下。", "b": "《国语·晋语》"}, {"t": "乘驲而自追晏子。", "b": "《吕氏春秋·士节》"}], "words": [{"w": "驲马", "t": "用来拉驿车的马"}, {"w": "驲讣", "t": "通过驿车急传的讣闻"}, {"w": "驲书", "t": "通过驿车传送的书信"}, {"w": "驲递", "t": "驿车传递"}, {"w": "驲行", "t": "乘驿马疾行。"}]}]}]','jingmo-wenyan');
