('6748wx','驵','1','zǎng','马','8','','[{"pinyin": "zǎng", "defs": [{"meaning": "骏马,好马。", "cites": [{"t": "驵,壮马也。《六书故》引作奘马,从马,且声。", "b": "《说文》"}, {"t": "苏驵军于泥阳。", "b": "《史记·樊郦滕灌列传》。索隐:“驵者,龙马也。”"}, {"t": "同驽骡与乘驵兮。", "b": "《楚辞·九叹·忧苦》"}, {"t": "驵疾(骏马疾驰);驵壮(马健壮);驵卒(马夫);驵骏(马健壮的样子)", "b": ""}]}, {"meaning": "马贩子。泛指市侩。", "cites": [{"t": "节驵侩。", "b": "《汉书·货殖传》"}], "words": [{"w": "驵竖", "t": "市侩的鄙称"}, {"w": "驵牙", "t": "市侩"}, {"w": "驵棍", "t": "市侩恶棍。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6751wx','驺','1','zōu','马','8','','[{"pinyin": "zōu", "defs": [{"meaning": "(形声。从马,刍(chú)声。本义:主驾车马的小吏)。"}, {"meaning": "同本义。", "cites": [{"t": "驺,厩御也。", "b": "《说文》"}, {"t": "命仆及七驺咸驾。", "b": "《礼记·月令》"}, {"t": "于嗟乎驺虞。", "b": "《诗·召南·驺虞》"}, {"t": "孟氏之御驺。", "b": "《左传·襄公二十三年》。疏:“掌马之官,兼掌御事,谓之御驺。”"}, {"t": "武士驺比外郎。", "b": "《汉书·惠帝纪》"}, {"t": "使训群驺知礼。", "b": "《左传》"}], "words": [{"w": "驺卒", "t": "掌管车马的奴仆"}, {"w": "驺御", "t": "驾驭车马的人"}, {"w": "驺皂", "t": "养马驾车的差役。"}]}, {"meaning": "骑士,侍从。", "cites": [{"t": "黄门从官驺蹋踧蕃曰:死老魅!复能损我曹员数,寺我曹禀假不?", "b": "《后汉书》"}], "words": [{"w": "驺骑", "t": "帝王的骑从"}, {"w": "驺哄", "t": "古时官吏出行时,引马喝道的前导"}, {"w": "驺唱", "t": "驺人引马开道的传呼"}, {"w": "驺从", "t": "高官显贵出行时,前导和后从的行从"}, {"w": "驺吏", "t": "骑马的侍从"}, {"w": "驺驭", "t": "驾驭车马的侍从"}, {"w": "驺殿", "t": "随从。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6753wx','绋','1','fú','纟','8','','[{"pinyin": "fú", "defs": [{"meaning": "乱丝。", "cites": [{"t": "绋,乱丝也。从系,弗声。", "b": "《说文》。"}]}, {"meaning": "大绳。", "cites": [{"t": "绋纚维之。", "b": "《诗·小雅·采菽》"}]}, {"meaning": "特指下葬时引柩入穴的绳索。", "cites": [{"t": "绋者,所牵持棺者也。", "b": "《白虎通》"}, {"t": "先君有所助执绋矣。", "b": "《左传·昭公三十年》"}, {"t": "助葬必执绋。", "b": "《礼记·曲礼上》"}]}, {"meaning": "蔽膝。", "cites": [{"t": "绋者,蔽也,行以蔽前。…天子朱绋,诸侯赤绋。", "b": "《白虎通·绋冕》"}]}, {"meaning": "系印章或佩玉的丝带。也代指官印。", "cites": [{"t": "吉疾病,上将使人加绋而封之。", "b": "《汉书·丙吉传》"}], "words": [{"w": "印绋", "t": "印章上的丝带"}, {"w": "释绋", "t": "解开丝带。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6754wx','绐','1','dài','纟','8','','[{"pinyin": "dài", "defs": [{"meaning": "(形声。从糸(mì),台声。本义:破旧的丝)。"}, {"meaning": "同本义。", "cites": [{"t": "绐,丝劳即绐。", "b": "《说文》"}, {"t": "绐,缠也。丝绐则纾而紊绕。", "b": "《广雅》"}, {"t": "丧勤焚缨一绐。", "b": "《逸周书》"}]}, {"meaning": "混乱;丝纤。", "cites": [{"t": "绐,丝绐则纾而紊绕。", "b": "清·朱骏声《说文通训定声》"}]}, {"meaning": "欺诈,哄骗。", "cites": [{"t": "项王至阴陵,迷失道,问一田父,田父绐曰:“左”。", "b": "《史记·项羽本纪》"}]}]}]','jingmo-wenyan');
