INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6786wx','荛','1','ráo yáo','艹','9','','[{"pinyin": "ráo", "defs": [{"meaning": "(形声。从艸,尧声。本义:柴草)。"}, {"meaning": "同本义。", "cites": [{"t": "荛,薪也。", "b": "《说文》"}, {"t": "询于刍荛。", "b": "《诗·板》"}, {"t": "淫刍荛者。", "b": "《左传·昭公十三年》。疏:供然火之草也。"}, {"t": "卖其薪荛。", "b": "《管子·轻重甲》。注:“大曰薪,小曰荛。”"}], "words": [{"w": "荛子", "t": "樵夫。"}]}, {"meaning": "芜菁,菜名。"}, {"meaning": "打柴草。", "cites": [{"t": "童区寄者,郴州荛牧儿也。", "b": "唐·柳宗元《童区寄传》"}], "words": [{"w": "荛牧", "t": "打草与放牧。"}]}]}, {"pinyin": "yáo", "defs": []}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6787wx','茈','1','cí zǐ','艹','9','','[{"pinyin": "cí", "defs": [{"meaning": "——见“凫茈”(fúcí):荸荠。"}]}, {"pinyin": "zǐ", "defs": [{"meaning": "茈草。", "cites": [{"t": "茈,茈草也。从草,此声。", "b": "《说文》"}, {"t": "藐茈草。", "b": "《尔雅》。注:“可以染紫。”"}, {"t": "劳山多茈草。", "b": "《山海经·西山经》"}]}, {"meaning": "可作紫色染料(即紫草。多年生草本植物。暗紫色,含紫草素,可作染料,也可药用。)如:茈萁(草名。一种蕨类植物)。"}, {"meaning": "紫色", "cites": [{"t": "练纂茈之于莱纯锱。", "b": "《管子·轻重丁》"}, {"t": "茈姜蘘荷。", "b": "司马相如《上林赋》"}, {"t": "[竹山]其中多茈羸。", "b": "《山海经》。郝懿行疏:“羸当为蠃,字之讹;茈蠃,紫色蠃也。”"}], "words": [{"w": "茈姜", "t": "初生的嫩姜,都有紫色的芽,所以叫“茈姜”"}, {"w": "茈蠃", "t": "紫色的螺。"}]}]}]','jingmo-wenyan');
