('6789wx','荄','1','gāi','艹','9','','[{"pinyin": "gāi", "defs": [{"meaning": "草根。", "cites": [{"t": "荄,草根也。从荄,亥声。", "b": "《说文》"}, {"t": "荄,根。", "b": "《尔雅》。注:“俗呼韭根为荄。”"}, {"t": "根荄以遂。", "b": "《汉书·礼乐志》"}, {"t": "万物养其根荄。", "b": "《后汉书·鲁恭传》"}, {"t": "还自荄也。", "b": "《太玄·亲》"}], "words": [{"w": "拔荄", "t": ""}]}, {"meaning": "台阶,级层。", "cites": [{"t": "初发乎或围之津涯,荄轸谷分。", "b": "《枚乘·七发》"}]}]}]','jingmo-wenyan');
