INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6883wx','洿','1','wū','氵','9','','[{"pinyin": "wū", "defs": [{"meaning": "(形声。从水,夸声。夸,于声。本义:水不流)。"}, {"meaning": "同本义。", "cites": [{"t": "洿,浊水不流也。", "b": "《说文》"}, {"t": "数罟不入洿池。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "洿池", "t": "水塘"}, {"w": "洿渎", "t": "小水沟。"}]}, {"meaning": "挖掘。", "cites": [{"t": "杀其人,坏其宝;洿其宫而猪焉。", "b": "《礼记·檀弓》"}], "words": [{"w": "洿宫", "t": "掘毁的宅第。"}]}, {"meaning": "衰落。", "cites": [{"t": "俯投迹而世洿,仰洿志而道隆。", "b": "晋·陆云《九悯》"}]}, {"meaning": "沾染;涂染。", "cites": [{"t": "又以墨洿色其周垣。", "b": "《汉书·王莽传》"}], "words": [{"w": "洿染", "t": "污染,传染。"}]}, {"meaning": "池塘,低洼地。", "cites": [{"t": "三代(夏商周)隘辟,厥(其)深洿沮也。", "b": "王充《论衡》"}]}, {"meaning": "低下;低洼。", "cites": [{"t": "九州安错,川谷何洿。", "b": "《楚辞·天问》"}], "words": [{"w": "洿隆", "t": "地势高低"}, {"w": "洿下", "t": "低下"}, {"w": "洿邪", "t": "地势低下"}, {"w": "洿沮", "t": "低洼湿地"}, {"w": "洿隆", "t": "高低"}, {"w": "洿泽", "t": "沼泽。"}]}, {"meaning": "污秽,不廉洁。", "cites": [{"t": "治旧洿。", "b": "《左传·文公六年》"}], "words": [{"w": "洿行", "t": "恶劣下流的品行"}, {"w": "洿泥", "t": "污泥"}, {"w": "洿浊", "t": "污浊,肮脏"}, {"w": "洿泞", "t": "污泥"}, {"w": "洿秽", "t": "污秽"}, {"w": "洿涂", "t": "污泥"}, {"w": "洿沫", "t": "泪流满面。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6885wx','泚','1','cǐ','氵','9','','[{"pinyin": "cǐ", "defs": [{"meaning": "(形声。从水,此声。本义:清澈的样子)。"}, {"meaning": "同本义 。", "cites": [{"t": "泚,清也。", "b": "《说文》"}], "words": [{"w": "清泚", "t": "清澈。"}]}, {"meaning": "鲜明的样子。", "cites": [{"t": "新台有泚,河水弥弥。", "b": "《诗·邶风·新台》"}, {"t": "术假金洞光,景逾瑶台泚。", "b": "宋·赵汝谈《翠蛟亭和巩栗斋韵》"}]}, {"meaning": "冒汗。", "cites": [{"t": "其颡有颡。", "b": "《孟子》"}], "words": [{"w": "泚泚", "t": "汗出貌"}, {"w": "泚颊", "t": "汗流脸颊"}, {"w": "泚颜", "t": "犹汗颜。"}]}]}]','jingmo-wenyan');
