INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6888wx','洸','1','guāng','氵','9','','[{"pinyin": "guāng", "defs": [{"meaning": "水波动荡闪闪发光的。", "cites": [{"t": "洸,水涌光也。从水,从光。会意,光亦声。", "b": "《说文》"}, {"t": "有洸有溃,既诒我肄。", "b": "《诗·邶风·谷风》"}], "words": [{"w": "洸洸;洸朗", "t": "形容水波动荡。"}]}, {"meaning": "威武,表现或显示出有很大权力或很有力气。", "cites": [{"t": "洸洸,武也。", "b": "《尔雅》"}, {"t": "武夫洸洸。", "b": "《诗·大雅·江汉》"}]}, {"meaning": "古水名。也称洸河。", "cites": [{"t": "洸水者,洙水也。", "b": "《水经注·泗水》注"}]}, {"meaning": "自山东省宁阳县东北分汶水,南流至济宁市与洙水交会,南注入泗水。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6889wx','洑','1','fú fù','氵','9','','[{"pinyin": "fú", "defs": [{"meaning": "旋涡。", "cites": [{"t": "又东为净滩,夏水急盛,川多湍洑。", "b": "《水经注·沔水》"}]}, {"meaning": "水名。"}, {"meaning": "洑溪。在今江苏省宜兴县。"}, {"meaning": "洑水,在今湖南省宁远县。"}, {"meaning": "水潜流地下。", "cites": [{"t": "则葱岭河源何以先汇于蒲昌,而又洑绝大山,出于星宿海?", "b": "清·魏源《释道北条弱水黑水》"}]}]}, {"pinyin": "fù", "defs": [{"meaning": "", "words": [{"w": "洑过河去", "t": ""}]}]}]','jingmo-wenyan');
