('6973wx','恧','1','nǜ','心','10','','[{"pinyin": "nǜ", "defs": [{"meaning": "自愧。", "cites": [{"t": "恧,惭也。从心,而声。", "b": "《说文》"}, {"t": "山之东西,自愧曰恧。", "b": "《方言六》"}, {"t": "苟中情之端直兮,莫吾知而不恧。", "b": "《后汉书·张衡传》"}, {"t": "处之不惭恧。", "b": "《汉书·王莽传上》"}, {"t": "内负宿心,外恧良朋。", "b": "嵇康《幽愤歌》"}], "words": [{"w": "恧颜", "t": "惭愧"}, {"w": "恧步", "t": "惶愧却步"}, {"w": "恧怩", "t": "惭愧忸怩"}, {"w": "恧恧", "t": "惭愧的样子"}, {"w": "恧然", "t": "惭愧的样子"}, {"w": "恧缩", "t": "惭愧而畏缩。"}]}]}]','jingmo-wenyan');
