INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('6977wx','辀','1','zhōu','车','10','','[{"pinyin": "zhōu", "defs": [{"meaning": "车辕。", "cites": [{"t": "辀,辕也。", "b": "《说文》。按,大车左右两木直而平者谓之辕,小车居中一木曲而上升谓之辀,故亦曰轩辕,谓其穹隆而高也。"}, {"t": "荐车直东荣,北辀。", "b": "《仪礼·既夕礼》"}]}, {"meaning": "用于大车上的称辕,用于兵车、田车、乘车上的称辀。辀为曲木,一端为方形,置于轴中央,从车底伸出,渐渐隆起,又渐成圆木。木前端置横木,称为“衡”,衡两端作缺月形,夹贴马颈,称为“额”。"}, {"meaning": "泛指车。", "cites": [{"t": "挟辀以走。", "b": "《左传·隐公十一年》"}, {"t": "驾龙辀兮乘雷,载云旗兮委蛇。", "b": "《楚辞》"}], "words": [{"w": "造辀的工匠", "t": ""}]}]}]','jingmo-wenyan');
