('6991wx','晖','1','huī','日','10','','[{"pinyin": "huī", "defs": [{"meaning": "(形声。从日,军声。字本作“晕”。本义:日月周围的光圈)。"}, {"meaning": "日色;阳光。", "cites": [{"t": "晖,光也。", "b": "《说文》"}, {"t": "日月晕于外,其贼在于内。", "b": "《战国策·赵策四》"}, {"t": "朝晖夕阴。", "b": "宋·范仲淹《岳阳楼记》"}, {"t": "照之有余晖,揽之不盈手。", "b": "陆机《拟明月以皎皎》"}], "words": [{"w": "斜晖", "t": ""}]}, {"meaning": "光辉。", "cites": [{"t": "君子之光,其辉吉也。", "b": "《易·未济卦》"}, {"t": "故日月不高,则光晖不赫。", "b": "《荀子·天论》"}, {"t": "名声被后世,光晖重万物。", "b": "《淮南子·览冥》"}, {"t": "阳春布德泽,万物生光晖。", "b": "《文选·古乐府·长歌行》"}], "words": [{"w": "晖光", "t": "光彩;光辉"}, {"w": "晖如", "t": "形容光辉闪耀"}, {"w": "辉煜", "t": "光辉闪耀。"}]}, {"meaning": "琴徽。同“徽”。"}, {"meaning": "光彩照耀。", "cites": [{"t": "不侈于后世,不靡于万物,不晖于数度。", "b": "《庄子·天下》"}, {"t": "唯昆与季,文藻相晖。", "b": "南朝·梁元帝《与萧挹书》"}]}]}]','jingmo-wenyan');
