('7010wx','眚','1','shěng','目','10','','[{"pinyin": "shěng", "defs": [{"meaning": "(形声。从目,生声。本义:眼睛生翳(yì)长膜)。"}, {"meaning": "同本义。", "cites": [{"t": "眚,目病生翳也。", "b": "《说文》。?"}, {"t": "目眚昏花烛穗垂。", "b": "范成大《晚步宣华旧苑》"}], "words": [{"w": "眚目", "t": "眼病之一。眼睛生白翳。"}]}, {"meaning": "削减。", "cites": [{"t": "以荒政十有二,聚万民,……七曰眚礼。", "b": "《周礼·地官·大司徒》"}]}, {"meaning": "过失。", "cites": [{"t": "眚,过也。", "b": "《广韵》"}, {"t": "孤之过也,大夫何罪?且吾不以一眚掩大德。", "b": "《左传·僖公三十三年》"}], "words": [{"w": "眚灾", "t": "亦作“眚烖”。因过失而造成灾害。"}]}, {"meaning": "日食。", "cites": [{"t": "非日月之眚。", "b": "《左传·庄公二十五年》。注:“月侵日为眚。”按,犹目之有翳也。”"}]}, {"meaning": "灾异。", "cites": [{"t": "虞我国眚,窥我利器。", "b": "潘岳《关中》"}]}, {"meaning": "疾苦;病。", "cites": [{"t": "勤恤民隐,而除其眚。", "b": "张衡《东京赋》"}]}]}]','jingmo-wenyan');
