INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7015wx','脩','1','xiū','月','10','','[{"pinyin": "xiū", "defs": [{"meaning": "(形声。从肉,攸(yōu)声。本义:干肉)。"}, {"meaning": "同本义(加姜桂等香料,捶制而成)。", "cites": [{"t": "脩,脯也。", "b": "《说文》"}, {"t": "三问皆脩。", "b": "《周礼·掌客》"}, {"t": "取糗与腶脩。", "b": "《仪礼·有司彻》"}, {"t": "枣栗段脩。", "b": "《礼记·昏义》"}, {"t": "自行束脩以上,吾未尝无诲焉。", "b": "《论语·述而》"}, {"t": "凡肉脩之颁赐,皆掌之。", "b": "《周礼·天官》"}]}, {"meaning": "指学生致教师的酬金。", "cites": [{"t": "小儿跟随肄业,以房资作为脩金。", "b": "《镜花缘》"}], "words": [{"w": "脩脯", "t": "付给教师的酬金"}, {"w": "脩金", "t": "送给老师的酬金。"}]}, {"meaning": "美味的食品。", "cites": [{"t": "祀五帝,则掌百官之誓戒,与其具脩。", "b": "《周礼·大宰》"}, {"t": "脩,爵无数。", "b": "《礼记·乡饮酒义》"}]}, {"meaning": "高;长。", "cites": [{"t": "脩,长也。", "b": "《小尔雅》"}, {"t": "四牡脩广。", "b": "《诗·小雅·六月》"}, {"t": "颈脩七寸。", "b": "《礼记·投壶》"}, {"t": "则及其大脩也。", "b": "《考工记·弓人》。注:“犹久也。”"}, {"t": "朱儒问径天高于脩人。", "b": "《淮南子·说山》。注:“长人也。”"}], "words": [{"w": "脩垌", "t": "遥远的田野"}, {"w": "脩眉", "t": "远山"}, {"w": "脩路", "t": "长路;远道"}, {"w": "脩途", "t": "长途,远路"}, {"w": "脩隔", "t": "遥远而阻隔"}, {"w": "脩久", "t": "长久"}, {"w": "脩长", "t": "长远。"}]}, {"meaning": "美好。", "cites": [{"t": "老冉冉其将至兮,恐脩名之不立。", "b": "屈原《离骚》"}], "words": [{"w": "脩名", "t": "美好的名声"}, {"w": "脩美", "t": "美好"}, {"w": "脩脩", "t": "修长美好貌"}, {"w": "脩善", "t": "行善"}, {"w": "脩态", "t": "美好的姿态。"}]}, {"meaning": "假借为“修”。兴建;兴修。", "cites": [{"t": "郑人脩城。", "b": "《左传》"}, {"t": "脩井也。", "b": "《易·象传》"}], "words": [{"w": "脩文", "t": "兴修文德"}, {"w": "脩营", "t": "修建,营建"}, {"w": "脩业", "t": "建立功业。"}]}, {"meaning": "修理;整修。", "cites": [{"t": "脩我长矛。", "b": "《诗·秦风·无衣》"}, {"t": "脩我甲兵。", "b": ""}, {"t": "脩我矛戟。", "b": ""}], "words": [{"w": "脩同", "t": "修通"}, {"w": "脩完", "t": "修缮完备"}, {"w": "脩奉", "t": "修缮供奉"}, {"w": "脩理", "t": "端谨整饬;整理;整修。"}]}, {"meaning": "治理。", "cites": [{"t": "与其具脩。", "b": "《周礼·太宰》。注:“埽除粪洒。”"}, {"t": "则为主睹懛除。", "b": "《周礼·山虞》。注:“治道路场坛。”"}], "words": [{"w": "脩平", "t": "治理"}, {"w": "脩理", "t": "整治"}, {"w": "脩复", "t": "整治而恢复之"}, {"w": "脩领", "t": "犹言治理"}, {"w": "脩缮", "t": "治理。"}]}, {"meaning": "修养。", "cites": [{"t": "聿脩厥德。", "b": "《诗·大雅·文王》"}], "words": [{"w": "脩己", "t": "自我修养"}, {"w": "脩行", "t": "修养德行"}, {"w": "脩洁,脩志", "t": "培养高尚的志向。"}]}, {"meaning": "学习;研习。", "cites": [{"t": "属脩士。", "b": "《荀子·礼论》。注:“士之进脩者,谓上上也。”"}], "words": [{"w": "脩习", "t": "学习;研习崇尚"}, {"w": "脩学", "t": "研习学业;治学"}, {"w": "脩荡", "t": "学习宣扬。"}]}]}]','jingmo-wenyan');
