INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7077wx','袪','1','qū','衤','10','','[{"pinyin": "qū", "defs": [{"meaning": "(形声。从衣,去声。本义:衣袖)。"}, {"meaning": "同本义。", "cites": [{"t": "祛,衣袂也。", "b": "《说文》"}, {"t": "祛尺二寸。", "b": "《礼记·王藻》。按,析言之,则袖曰袂,袖口曰祛。”"}, {"t": "掺执子之祛兮。", "b": "《诗·郑风·遵大路》"}, {"t": "羔裘豹祛。", "b": "《诗·唐风·羔裘》"}, {"t": "左祛挂于博桑。", "b": "《楚辞·哀时命》"}, {"t": "(晋文公)逾垣而走,(寺人)披斩其袪。", "b": "《左传》"}]}, {"meaning": "撩起。", "cites": [{"t": "黼帐袪而结组兮。", "b": "傅毅《舞赋》。注:“犹举也。”"}], "words": [{"w": "袪衣", "t": "撩起衣服"}, {"w": "袪步", "t": "举衣而行"}, {"w": "袪衣受业", "t": "撩起衣服前往受业。形容虚心求教。"}]}, {"meaning": "摆脱,去掉。", "cites": [{"t": "童蒙赖焉。用袪其蔽。", "b": "蔡邕《郭有道碑文》"}, {"t": "伊余乐好仁,惑袪各亦泯。", "b": "殷仲文《南州桓公九井作》"}], "words": [{"w": "袪除", "t": "除去"}, {"w": "袪痒", "t": "除病"}, {"w": "袪荡", "t": "清除。"}]}, {"meaning": "分开。", "cites": [{"t": "合袪于天地神祗。", "b": "《汉书》"}]}]}]','jingmo-wenyan');
