INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7080wx','祧','1','tiāo','礻','10','','[{"pinyin": "tiāo", "defs": [{"meaning": "(形声。从示,兆声。从“示”与祭祀有关。本义:祀远祖、始祖之庙) 同本义。", "cites": [{"t": "祧,祭也。", "b": "《说文新附》"}, {"t": "祧,祭先祖也。", "b": "《广雅》"}, {"t": "守祧八人,掌先王先公之庙祧。", "b": "《周礼》"}, {"t": "文武为祧,四时祭之而已。", "b": "蔡邕《独断》"}, {"t": "远庙为祧。", "b": "《礼记》"}], "words": [{"w": "祧迁", "t": "把隔了几代的祖宗的神主迁入远祖之庙"}, {"w": "祧庙", "t": "远祖庙。泛指祖庙。"}]}, {"meaning": "迁庙。帝王对世数远隔之祖,依制将其神主迁入远祖之庙,故迁移神主也称祧。", "cites": [{"t": "已祧之主,不得复入太庙。", "b": "《新唐书》"}]}, {"meaning": "超越。", "cites": [{"t": "非先有词而后有唐人之诗,亦不能祧诗而言词。", "b": "清·江顺诒《词学集成》"}]}, {"meaning": "承继为后嗣。", "cites": [{"t": "守器承祧。", "b": "沈约《立太子诏》"}], "words": [{"w": "祧绪", "t": "世代相承的统绪"}, {"w": "祧续", "t": "祧绪。指子孙传宗接代。"}]}, {"meaning": "泛指继承。", "cites": [{"t": "宿草敢祧刘礼部,东南绝学在昆陵。", "b": "清·龚自珍《己亥杂诗三百十五首》"}]}]}]','jingmo-wenyan');
