('7085wx','陴','1','pí','阝','10','','[{"pinyin": "pí", "defs": [{"meaning": "(形声。从阜,卑声。从阜与高下有关,与建筑有关。本义:城上女墙,上有孔穴,可以窥外)。"}, {"meaning": "同本义。", "cites": [{"t": "陴,城上女墙俾倪也。", "b": "《说文》"}, {"t": "抚弦登陴。", "b": "南朝齐·丘迟《与陈伯之书》"}, {"t": "守陴者皆哭。", "b": "《左传·宣公十二年》"}, {"t": "子产授兵登陴。", "b": ""}]}, {"meaning": "假借为“髀”。大腿。", "cites": [{"t": "有鬼投其陴。", "b": "《吕氏春秋·明理》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7086wx','烝','1','zhēng','灬','10','','[{"pinyin": "zhēng", "defs": [{"meaning": "(形声。从火,丞声。本义:火气上行)。"}, {"meaning": "同本义。", "cites": [{"t": "烝,火气上升也。", "b": "《说文》"}, {"t": "阳气俱烝。", "b": "《国语·周语》"}, {"t": "释之叟叟,烝之浮浮。", "b": "《诗·大雅·生民》"}], "words": [{"w": "烝烝", "t": "热气升腾的样子"}, {"w": "烝云", "t": "上腾的云气"}, {"w": "烝濡", "t": "烝腾的湿气"}, {"w": "烝润", "t": "湿热润发。"}]}, {"meaning": "用蒸汽加热", "cites": [{"t": "烝之浮浮。", "b": "《诗·大雅·生民》"}, {"t": "故枸木必将待櫽烝矫然后直。", "b": "《荀子·性恶》"}, {"t": "易牙烝其子首而进之。", "b": "《韩非子·难一》"}, {"t": "桓南郡每见人不快,辄嗔云:“君得哀家梨,当复不烝食不?”", "b": "《世说新语》"}], "words": [{"w": "烝炊", "t": "蒸煮"}, {"w": "烝壶", "t": "蒸熟的葫芦瓜"}, {"w": "烝糕", "t": "以米粉或面粉发酵加糖蒸成的糕。"}]}, {"meaning": "一般指娶父亲的妻妾及兄长的妻妾。", "cites": [{"t": "初,惠公之即位也少,齐人使昭伯烝于宣姜,不可,强之。", "b": "《左传·闵公二年》"}, {"t": "见武媚娘而悦之,遂即东厢烝焉。", "b": "明·周清源《西湖二集》"}], "words": [{"w": "烝淫", "t": "指与母辈通奸的淫行"}, {"w": "烝报", "t": "乱伦之行"}, {"w": "烝弑", "t": "奸淫母辈,残杀君父"}, {"w": "烝乱", "t": "淫乱。"}]}, {"meaning": "用火烘烤。", "cites": [{"t": "枸木必将待櫽栝烝矫燃后直。", "b": "《荀子·性恶》"}]}, {"meaning": "蒸发。", "cites": [{"t": "月丽于上,山烝于下。", "b": "王充《论衡》"}]}, {"meaning": "进;前进。", "cites": [{"t": "烝我髦士。", "b": "《诗·小雅·甫田》"}]}, {"meaning": "众多;众。", "cites": [{"t": "有豕向蹄,烝涉波矣。", "b": "《诗·小雅·渐渐之石》"}, {"t": "天生烝民。", "b": "《孟子·告子》"}], "words": [{"w": "烝人", "t": "民众,百姓"}, {"w": "烝民", "t": "民众,百姓"}, {"w": "烝涉", "t": "成群涉水"}, {"w": "烝庶", "t": "众人,民众"}, {"w": "烝黎", "t": "百姓。"}]}, {"meaning": "美;美好。", "cites": [{"t": "文王烝哉!", "b": "《诗·大雅·文王有声》"}]}]}]','jingmo-wenyan');
