INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7113wx','晢','1','zhé','日','11','','[{"pinyin": "zhé", "defs": [{"meaning": "(形声。从日,折声。本义:明亮;光明)。"}, {"meaning": "同本义。", "cites": [{"t": "晢,昭明也。", "b": "《说文》。"}, {"t": "明星晢晢。", "b": "《诗·陈风·东门之杨》"}, {"t": "其少进也,晢兮若姣姬,扬袂鄣日,而望所思。", "b": "《文选 ·宋玉·高唐赋》"}], "words": [{"w": "晢明", "t": "质明,天刚亮的时候"}, {"w": "晢眇", "t": "光明。谓白昼。"}]}, {"meaning": "明智,明白。", "cites": [{"t": "明作晢,聪作谋。", "b": "《书·洪范》"}, {"t": "明辨,晢也。", "b": "《易·大有》"}, {"t": "晢明行事。", "b": "《仪礼·士冠礼》"}, {"t": "喜怒之如度晢日守也。", "b": "《大戴礼记·文王官人》"}, {"t": "虽司命其不晢。", "b": "张衡《思玄赋》"}, {"t": "明者见于无形,智者虑于未萌,况其昭晢者乎!", "b": "《后汉书》"}], "words": [{"w": "晢晢", "t": "明显。"}]}, {"meaning": "日光。", "cites": [{"t": "桐林带晨霞,石壁映初晢。", "b": "江淹《杂体诗·谢临川游山》"}], "words": [{"w": "晢耀", "t": "光芒闪耀。"}]}]}]','jingmo-wenyan');
