('7243wx','惛','1','hūn','忄','11','','[{"pinyin": "hūn", "defs": [{"meaning": "(形声。从心,昏声。“昏”亦兼表字义。本义:糊涂)。"}, {"meaning": "同本义。", "cites": [{"t": "惛,不憭也。", "b": "《说文》"}, {"t": "惛,痴也。", "b": "《广雅·释诂三》"}, {"t": "皆惛于教。", "b": "《战国策·秦策》"}, {"t": "事有功者必赏,则群臣莫敢饰言以惛主。", "b": "《韩非子·南面》"}, {"t": "心以利倾,智以势惛。", "b": "《晋书·王沉传》"}, {"t": "臣甚惛焉。", "b": "《汉书·刘向传》"}, {"t": "吾惛。", "b": "《孟子·梁惠王上》"}], "words": [{"w": "惛眊", "t": "神智不清,眼睛昏花"}, {"w": "惛耄", "t": "衰老"}, {"w": "惛懵", "t": "昏昧迷矇,模糊不清。"}]}, {"meaning": "心乱。", "cites": [{"t": "以黄金抠者惛。", "b": "《列子·黄帝》"}, {"t": "怒之而观其不惛也。", "b": "《大戴礼记·曾子立事》"}, {"t": "惛然若亡而存。", "b": "《庄子·知北游》"}], "words": [{"w": "惛渎", "t": "惑乱亵渎"}, {"w": "惛乱", "t": "昏乱"}, {"w": "惛沮", "t": "昏乱沮丧"}, {"w": "惛俗", "t": "昏乱的流俗。"}]}, {"meaning": "欺蒙,迷惑。", "cites": [{"t": "事有功者必赏,则群臣莫敢饰言以惛主。", "b": "《韩非子》"}]}]}]','jingmo-wenyan');
