('7312wx','萩','1','qiū','艹','12','','[{"pinyin": "qiū", "defs": [{"meaning": "蒿类植物。", "cites": [{"t": "萩,萧也。", "b": "《说文》"}, {"t": "萧,萩。", "b": "《尔雅》。郭璞注:“即蒿。”"}]}, {"meaning": "假借为“楸”。", "cites": [{"t": "伐雍门之萩。", "b": "《左传·襄公十八年》"}, {"t": "又有萩竹藉田。", "b": "《汉书·东方朔传》"}, {"t": "水居知石鱼波,山居千章之萩。", "b": "《汉书·货殖传》。颜师古注:“萩,即楸树字也。”"}]}, {"meaning": "柴薪。", "cites": [{"t": "当春三月,萩室熯造。", "b": "《管子·禁藏》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7313wx','蒐','1','sōu','艹','12','','[{"pinyin": "sōu", "defs": [{"meaning": "(会意。从艸,从鬼。本指茜草,古人以为人血所生,可以染绛,故从血。本义:茜草) 同本义。", "cites": [{"t": "(厘山)其阳多玉,其阴多蒐。", "b": "《山海经》"}]}, {"meaning": "春天打猎,一说秋天打猎。", "cites": [{"t": "故春蒐,夏苗,秋狝,冬狩。", "b": "《左传·隐公五年》"}, {"t": "秋,蒐于红。", "b": "《谷梁传·昭公八年》"}, {"t": "遂以蒐田。", "b": "《周礼·大司马》。注:“春田为蒐。”"}], "words": [{"w": "蒐田", "t": "春天田猎"}, {"w": "蒐狩", "t": "春猎为蒐,冬猎为狩"}, {"w": "蒐苗", "t": "春猎为蒐,夏猎为苗。泛指狩猎"}, {"w": "蒐畋", "t": "狩猎"}, {"w": "蒐狝", "t": "春猎与秋猎。亦泛指狩猎"}, {"w": "蒐猎", "t": "狩猎。"}]}, {"meaning": "阅兵,检阅。", "cites": [{"t": "蒐乘补卒,秣马利兵。", "b": "《左传·成公十六年》"}], "words": [{"w": "蒐阅", "t": "检阅"}, {"w": "蒐乘", "t": "检阅兵车。"}]}, {"meaning": "隐蔽。", "cites": [{"t": "服谗蒐慝,以诬盛德。", "b": "《左传·文公十八年》"}]}, {"meaning": "求索,寻找。", "cites": [{"t": "故春蒐夏苗,秋蒐冬狩,皆于农隙以讲事也。", "b": "《左传·隐公五年》。杜预注:蒐,索择不孕者。"}, {"t": "春曰苗,秋曰蒐。", "b": "《公羊传·恒公四年》"}, {"t": "秋谓之蒐何蒐?索肥者也。", "b": "《白虎通·田猎》"}, {"t": "于是讲八代之礼,蒐三王之乐。", "b": "《文选·陆机·辩亡论上》"}], "words": [{"w": "蒐采", "t": "搜集"}, {"w": "蒐括", "t": "搜集"}, {"w": "蒐索", "t": "仔细寻找"}, {"w": "蒐讨", "t": "寻究探讨"}, {"w": "蒐阅", "t": "搜罗考核"}, {"w": "蒐猎", "t": "搜求;猎取。"}]}]}]','jingmo-wenyan');
