INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7324wx','椓','1','zhuó','木','12','','[{"pinyin": "zhuó", "defs": [{"meaning": "敲;捶。", "cites": [{"t": "椓,击也。从木,豖声。", "b": "《说文》"}, {"t": "椓,椎也。", "b": "《广雅》"}, {"t": "椓之丁丁。", "b": "《诗·召南·兔罝》"}, {"t": "约之阁阁,椓之橐橐。", "b": "《诗·小雅·斯干》"}], "words": [{"w": "椓壁", "t": "在墙壁上钉桩"}, {"w": "椓船", "t": "钉木桩以拴船"}, {"w": "椓斛", "t": "叩斛。使所盛谷物下陷,以便多盛"}, {"w": "椓蠡", "t": "砸开螺壳,生食其肉。"}]}, {"meaning": "毁坏;伤害。", "cites": [{"t": "民今之无禄,天天是椓。", "b": "《诗·小雅·正月》"}, {"t": "一呷之药,椓我天民。", "b": "《清朝野史大观》"}], "words": [{"w": "椓毁", "t": "毁坏"}, {"w": "椓丧", "t": "遭受伤害"}, {"w": "椓破", "t": "摧残破坏。"}]}, {"meaning": "宫刑。", "cites": [{"t": "杀戮无辜,爱始淫为劓、刵、椓、黥。", "b": "《书·吕刑》。孔传:“截人耳鼻,椓阴黥面。”"}], "words": [{"w": "椓阴", "t": "宫刑"}, {"w": "椓窃", "t": "掩闭女子阴门的宫刑。"}]}, {"meaning": "告发,攻讦。", "cites": [{"t": "卫侯辞以难,太子又使椓之。", "b": "《左传·哀公十七年》。杜预注:“椓,诉。”杨伯峻注:“此言太子庆疾于赵鞅使者前毁谤 中伤其父。”"}]}, {"meaning": "阉人,割了生殖器的男人。"}]}]','jingmo-wenyan');
