('7428wx','湝','1','jiē','氵','12','','[{"pinyin": "jiē", "defs": [{"meaning": "水流动的样子。", "cites": [{"t": "湝,水流湝湝也。从水,皆声。", "b": "《说文》"}, {"t": "淮水湝湝。", "b": "《诗·小雅·钟鼓》"}], "words": [{"w": "湝湝", "t": "水流的样子。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7429wx','渰','1','yǎn','氵','12','','[{"pinyin": "yǎn", "defs": [{"meaning": "(形声。从水,弇(yǎn)声。云、雨相关联,故从水。本义:阴云) 同本义。", "cites": [{"t": "渰,雨云貌。", "b": "《说文》"}, {"t": "有渰凄凄。", "b": "《诗·小雅·大田》。传:“云兴貌。”"}, {"t": "凄风起东谷,有渰兴南岑。", "b": "晋·张协《杂诗》之九"}, {"t": "若逢炎日过嘉苗,有渰?垂祥德所招。", "b": "明·谢谠《四喜记》"}], "words": [{"w": "渰云", "t": "阴云"}, {"w": "渰渰", "t": "云起貌。"}]}, {"meaning": "淹没。", "cites": [{"t": "颇有渰溺,复还守先顿。", "b": "《梁书·曹景宗传》"}, {"t": "纪世雄三万人马,都被河水渰死,一个也没留。", "b": "《英烈传》"}, {"t": "某为水所渰,仓皇中搬家来唐书局,又为皇城司所逐。一家惶惶,不知所之。", "b": "宋·欧阳修《赵唐靖公》"}], "words": [{"w": "渰没", "t": "渰浸、渰溺。淹没"}, {"w": "渰杀", "t": "渰殪。淹死"}, {"w": "渰漏", "t": "犹浸蚀"}, {"w": "渰烂", "t": "因水淹浸而沤烂。"}]}]}]','jingmo-wenyan');
