('7432wx','渟','1','tíng','氵','12','','[{"pinyin": "tíng", "defs": [{"meaning": "水积聚不流。", "cites": [{"t": "渟,止也。", "b": "《广雅·释诂三》"}, {"t": "渟涔障溃。", "b": "《文选·马融·长笛赋》"}], "words": [{"w": "渟洄", "t": "渟滢,渟潆。水回旋不进的样子"}, {"w": "渟洿", "t": "停滞不流的样子"}, {"w": "渟涵", "t": "水积聚;水泽。"}]}, {"meaning": "深 。", "words": [{"w": "渟泓", "t": "积水深的样子。"}]}, {"meaning": "水明静清澈的 。", "words": [{"w": "渟渟", "t": "水平静的样子"}, {"w": "渟澂", "t": "水静而清澈。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7433wx','溠','1','zhā','氵','12','','[{"pinyin": "zhā", "defs": [{"meaning": "水名 。源出湖北省随州市西北,古代东南流会溠水,又南流入溠水;后河道变迁,与溠水分别入溠水。", "cites": [{"t": "溠,水在汉南,荆州浸也。", "b": "《说文·水部》"}]}]}]','jingmo-wenyan');
