INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7437wx','湑','1','xū xǔ','氵','12','','[{"pinyin": "xū", "defs": [{"meaning": "水名 。源出陕西省佛坪县,西流经秦岭之麓,折东南经城固县入汉水。"}]}, {"pinyin": "xǔ", "defs": [{"meaning": "将酒滤清。", "cites": [{"t": "湑,茜酒也。从水,酉声。字亦作醑。", "b": "《说文》"}, {"t": "有酒湑我,无酒酷我。", "b": "《诗·小雅·伐木》"}, {"t": "尔酒既湑。", "b": "《诗·大雅·凫鷖》"}], "words": [{"w": "湑酒", "t": "清酒。"}]}, {"meaning": "清。", "cites": [{"t": "旨酒既湑。", "b": "《仪礼·士冠礼》。注:“清也。”"}, {"t": "尔酒既湑,尔淆伊脯。", "b": "《诗·大雅·凫鷖》"}], "words": [{"w": "湑湑", "t": "水清澈的样子。"}]}, {"meaning": "茂盛。", "cites": [{"t": "裳裳者华,其叶湑兮。", "b": "《诗·小雅·裳裳者华》"}]}, {"meaning": "欢乐。", "cites": [{"t": "酣湑半,八音并。", "b": "左思《吴都赋》。刘逵注:“湑,乐也。”"}]}]}]','jingmo-wenyan');
