INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7446wx','祼','1','guàn','礻','12','','[{"pinyin": "guàn", "defs": [{"meaning": "古代酌酒灌地的祭礼。", "cites": [{"t": "祼,灌祭也。", "b": "《说文》。按:“以酒灌地以请神曰祼。"}, {"t": "以肆献祼享先王。", "b": "《周礼·春官·大宗伯》"}, {"t": "王祼鬯。", "b": "《国语·周语上》"}, {"t": "吾冠必以祼享之礼行之。", "b": "《左传·襄公九年》"}, {"t": "王礼再祼而酢。", "b": "《周礼·秋官·大行人》"}, {"t": "王入太室祼。", "b": "《书·洛诰》"}, {"t": "殷士肤敏,祼将于京。", "b": "《诗·大雅·文王》"}], "words": [{"w": "祼将", "t": "为帝王助祭,行灌鬯之礼"}, {"w": "祼事", "t": "用酒奠祭先人及赐宾客饮之类的事"}, {"w": "祼献", "t": "古代帝王、王后祭祀时,以香酒灌地、以腥熟之食献神的礼仪。亦泛指祼礼"}, {"w": "祼鬯", "t": "古代祭祀仪式。以香酒灌地而告神。"}]}, {"meaning": "对朝见的诸侯行祼礼,以爵酌香酒敬宾客。", "cites": [{"t": "祼圭有瓒,以肆先王,以祼宾客。", "b": "《周礼·青官·典瑞》"}], "words": [{"w": "祼玉", "t": "古代举行禅祭时所用的玉器"}, {"w": "祼圭", "t": "古代玉制酒器。帝王用来盛酒降神或盛宴宾客。"}]}]}]','jingmo-wenyan');
