INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7458wx','缊','1','yūn yùn','纟','12','','[{"pinyin": "yūn", "defs": [{"meaning": "——见 “絪緼”。即“氤氲” (yīn-yū)。"}]}, {"pinyin": "yùn", "defs": [{"meaning": "(形声。从糸(mì),昷(wēn)声。本义:以新绵合旧絮)。"}, {"meaning": "新旧混合的绵絮,乱絮。", "cites": [{"t": "缊,绋也。", "b": "《说文》。谓乱麻。"}, {"t": "衣缊无衣。", "b": "《汉书·东方朔传》。注:“乱絮也。”"}, {"t": "纩为茧,缊为袍。", "b": "《礼记·玉藻》。注:“行谓今之新绵也,缊谓今行及旧絮也。”"}, {"t": "(里母)即束缦请火于亡肉家。", "b": "《汉书·蒯通传》"}], "words": [{"w": "缊褚", "t": "用碎麻或旧絮制的冬衣"}, {"w": "缊褐", "t": "缊袍。泛指贫者所服粗陋冬衣"}, {"w": "缊绪", "t": "缊褚"}, {"w": "缊絑", "t": "缊褚。"}]}, {"meaning": "乱麻。", "cites": [{"t": "缊袍敝衣。(穿着旧袄破衣。名词做动词用。缊,旧絮。敝,破。)", "b": "明·宋濂《送东阳马生序》"}], "words": [{"w": "缊袍(以乱麻为絮的袍子古为贫者所服)缊絮(乱麻旧絮泛指粗陋的衣服)", "t": ""}]}, {"meaning": "动乱,不安,骚乱。", "cites": [{"t": "缊,乱也。", "b": "《广雅》"}, {"t": "齐桓之时缊。", "b": "《法言·孝至》"}]}, {"meaning": "深奥", "cites": [{"t": "乾坤其《易》之缊邪。", "b": "《易·系辞》"}], "words": [{"w": "缊奥", "t": "深奥,奥义。"}]}, {"meaning": "积聚;收藏。", "cites": [{"t": "乾坤其易之缊邪?", "b": "《易·系辞上》"}, {"t": "而以是相缊。", "b": "《庄子·齐物论》。释文:“蕴,本亦作缊。”"}], "words": [{"w": "缊畜", "t": "蕴蓄。含蓄宽容"}, {"w": "缊藉", "t": "蕴藉。含蓄宽容。"}]}]}]','jingmo-wenyan');
