('7475wx','遘','1','gòu','辶','13','','[{"pinyin": "gòu", "defs": [{"meaning": "(形声。从辵(chuò),表示与行走有关,冓(gōu)声。本义:遇,遇见)。"}, {"meaning": "同本义。", "cites": [{"t": "遘,遇也。", "b": "《说文》"}, {"t": "遘厉虐疾。", "b": "《书·金滕》"}, {"t": "夫何予生之不遘时!", "b": "《楚辞·严忌哀时命》"}, {"t": "是疾易传染,遘者虽戚属,不敢同卧起。", "b": "清·方苞《狱中杂记》"}], "words": [{"w": "遘屯", "t": "遭遇困难"}, {"w": "遘时", "t": "逢时,遇到好的机运"}, {"w": "遘难", "t": "遭遇灾难"}, {"w": "遘慝", "t": "遭遇灾祸"}, {"w": "遘愍", "t": "遭遇忧患"}, {"w": "遘时", "t": "遇到好时机"}, {"w": "遘辰", "t": "遇到好时机。"}]}, {"meaning": "构成,造成。", "cites": [{"t": "西京乱无象,豺虎方遘患。", "b": "王粲《七哀诗》"}], "words": [{"w": "遘祸", "t": "构祸,造成灾祸"}, {"w": "遘患", "t": "作乱"}, {"w": "遘扇", "t": "构扇。挑拨煽动。"}]}]}]','jingmo-wenyan');
