('7515wx','觜','1','zī zuǐ','角','13','','[{"pinyin": "zī", "defs": [{"meaning": "即觜宿 三、(猎户座φ&-{2})三颗星", "words": [{"w": "觜觽", "t": "星座名。“觜宿”的早期名称"}, {"w": "觜陬", "t": "十二星次之一。"}]}]}, {"pinyin": "zuǐ", "defs": [{"meaning": "猫头鹰类头上的毛角。", "cites": [{"t": "段玉裁注:“角觜,萑下云:‘毛角’是也。毛角,头上毛似角者也。”", "b": ""}]}, {"meaning": "鸟嘴。", "cites": [{"t": "裂膆破觜。", "b": "潘岳《射雉赋》"}, {"t": "秦政利觜长距,终得擅场。", "b": "《文选·张衡·东京赋》"}, {"t": "觜銛剑戟,爪握刀锥。", "b": "唐·李白《壁画苍鹰赞》"}], "words": [{"w": "觜吻", "t": "某些动物头部向前突出的部分,包括嘴、鼻子等"}, {"w": "觜距", "t": "鸟的喙和爪。比喻捍卫的武力,亦即摧毁敌人的武器。"}]}, {"meaning": "后用以指人的口,字亦作“嘴”。", "cites": [{"t": "覆背腾其喉唇,武人历其觜吻。", "b": "《南齐书·刘休传》"}]}, {"meaning": "形状或作用像嘴的东西。", "cites": [{"t": "以绵幂铛觜瓶口,泻著瓶中。", "b": "《齐民要术》"}]}, {"meaning": "啄。", "cites": [{"t": "无声细下飞啐雪,有骨已剁觜春葱。", "b": "《杜甫语》"}]}, {"meaning": "龇,露。", "cites": [{"t": "獠牙觜出赛银钉。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
