('7549wx','僇','1','lù','亻','13','','[{"pinyin": "lù", "defs": [{"meaning": "行动迟缓。", "cites": [{"t": "僇,痴行僇僇也。", "b": "《说文》"}], "words": [{"w": "僇僇", "t": "迟缓的样子。"}]}, {"meaning": "肃静。", "cites": [{"t": "器成于僇。", "b": "《管子·幼官》"}]}, {"meaning": "侮辱。", "cites": [{"t": "僇越大夫常寿过。", "b": "《史记·楚世家》"}], "words": [{"w": "僇辱", "t": "欺侮凌辱,刑辱"}, {"w": "僇笑", "t": "辱笑;耻笑"}, {"w": "僇尸", "t": "侮辱尸体"}, {"w": "僇谴", "t": "僇辱贬谪。"}]}, {"meaning": "杀戮。", "cites": [{"t": "是以赏于祖而僇于社。", "b": "《墨子·明鬼》"}, {"t": "辟则为天下僇矣。", "b": "《礼记·大学》"}, {"t": "祭兽僇禽。", "b": "《礼记·月令》"}, {"t": "不僇于吏诛,必死于私剑矣。", "b": "《韩非子·孤愤》"}], "words": [{"w": "僇市", "t": "诛戮后陈尸于市"}, {"w": "僇民", "t": "杀戮人民;受过凌辱和刑罚的人"}, {"w": "僇死", "t": "受刑罚而死。"}]}, {"meaning": "火耕。", "cites": [{"t": "春无杀伐,无割大陵,僇大衍,伐大木。", "b": "《管子·七臣七主》"}]}]}]','jingmo-wenyan');
