INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7571wx','廒','1','áo','广','13','','[{"pinyin": "áo", "defs": [{"meaning": "(形声。从广,敖声。本义:粮库) 同本义。", "cites": [{"t": "高下绿苗千顷尽,新陈红粟万廒空。", "b": "唐·许浑《汉水伤稼》"}, {"t": "有一伙有家当囤米的财主,贪那贵价,从家里廒中发出米去。", "b": "明·凌蒙初《三刻拍案惊奇》"}, {"t": "旧毡帽朋友把自己种出来的米送进了万盛米行的廒间。", "b": "叶圣陶《多收了三五斗》"}], "words": [{"w": "廒间", "t": "廒禀;粮仓。"}]}]}]','jingmo-wenyan');
