('7572wx','瘀','1','yū','疒','13','','[{"pinyin": "yū", "defs": [{"meaning": "凝滞。", "cites": [{"t": "瘀,积血也。从疒,於声。", "b": "《说文》"}, {"t": "形销铄而瘀伤。", "b": "《楚辞·九辩》"}], "words": [{"w": "瘀血", "t": "体内某部位血液瘀滞;凝滞不流通的血"}, {"w": "瘀肉", "t": "有病变的肌肉。"}]}, {"meaning": "郁积;停滞。", "cites": [{"t": "伤寒瘀热在里,身必发黄。", "b": "汉·张仲景《伤寒论》"}], "words": [{"w": "瘀疾", "t": "停滞和急趋"}, {"w": "瘀伤", "t": "气血郁积成病。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7573wx','瘅','1','dān dàn','疒','13','','[{"pinyin": "dān", "defs": [{"meaning": "热症;湿热症。", "cites": [{"t": "下民卒瘅。", "b": "《诗·大雅·板》"}], "words": [{"w": "瘅疾", "t": "热病。"}]}]}, {"pinyin": "dàn", "defs": [{"meaning": "病;劳苦。", "cites": [{"t": "瘅,痨病也。从疒,单声。", "b": "《说文》。字亦作“癉”。"}, {"t": "瘅,劳也。", "b": "《尔雅》"}, {"t": "故书货之瘅于民用者。", "b": "《周礼·泉府》"}], "words": [{"w": "瘅疽", "t": "恶疮。俗名对口疽。"}]}, {"meaning": "黄疸病。"}, {"meaning": "厚(与“薄”相对);。", "cites": [{"t": "名曰瘅疟。", "b": "《素问·疟论》"}], "words": [{"w": "瘅暑", "t": "盛热,酷热"}, {"w": "瘅热", "t": "盛热"}, {"w": "瘅疟", "t": "热病名。"}]}, {"meaning": "因劳累致病。", "cites": [{"t": "夫善在必彰者,则恶在所必瘅。", "b": "清·王士禛《居易续谈》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
