INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7578wx','鄣','1','zhāng','阝','13','','[{"pinyin": "zhāng", "defs": [{"meaning": "古邑名 。本为纪国边邑。", "cites": [{"t": "鄣,纪邑也。从邑,章声。", "b": "《说文》"}, {"t": "秋七月,齐人降鄣。", "b": "《春秋·庄公三十年》。杨伯峻注:“鄣,当即《昭十九年传》之纪鄣。纪鄣者,本纪国之鄣邑也。当在今江苏省赣榆旧城北。”"}]}, {"meaning": "古郡名 。秦置。汉为故鄣,属丹阳郡。今浙江省长兴县西南有故鄣城。"}, {"meaning": "阻塞,阻隔。", "cites": [{"t": "自鄣叶。", "b": "三国魏·邯郸淳《笑林》"}, {"t": "以叶自鄣。", "b": ""}]}]}]','jingmo-wenyan');
