INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7583wx','煴','1','yūn yùn','火','13','','[{"pinyin": "yūn", "defs": [{"meaning": "(形声。从火,昷(wēn)声。本义:郁烟,不见火焰的燃烧而产生出来的许多烟)。"}, {"meaning": "同本义。", "cites": [{"t": "煴,郁烟也。", "b": "《说文》"}, {"t": "置煴火。", "b": "《汉书·苏武传》。师古曰:“煴谓聚火无焱者也。”"}, {"t": "天地絪煴。", "b": "《易·系辞下》。班固典引作“烟煴”。"}, {"t": "天雨新晴,北风寒切,是夜必霜。此时放火作煴,少得烟气,则免于霜矣。", "b": "《齐民要术》"}]}, {"meaning": "微火;无焰的火。", "cites": [{"t": "置煴火。", "b": "《汉书·李广苏建传》"}], "words": [{"w": "煴火", "t": "无焰的微火。"}]}, {"meaning": "暖和;温暖。", "cites": [{"t": "狐貉虽煴,不能热无气之人。", "b": "汉·牟融《理惑论》"}, {"t": "机丝润看雨暄风煴。", "b": "明·汤显祖《邯郸梦》"}], "words": [{"w": "煴煴", "t": "热辣辣的。"}]}, {"meaning": "温和;宽容。", "cites": [{"t": "欣煴可安谓之煴,反煴为鸷。", "b": "汉·贾谊《新书》"}], "words": [{"w": "煴恭", "t": "温和恭顺。"}]}]}, {"pinyin": "yùn", "defs": [{"meaning": "用烙铁或熨斗烫平衣物", "cites": [{"t": "煴,以火伸物。", "b": "《集韵》"}], "words": [{"w": "煴斗", "t": "即熨斗。"}]}]}]','jingmo-wenyan');
