INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7600wx','慆','1','tāo','忄','13','','[{"pinyin": "tāo", "defs": [{"meaning": "(形声。从心,舀(yǎo)声。本义:喜悦)。"}, {"meaning": "同本义。", "cites": [{"t": "慆,说也。", "b": "《说文》。字亦作謟。"}, {"t": "师乃慆。", "b": "《尚书大传》。注:“喜也。”"}, {"t": "君子之近琴瑟,以仪节也,非以慆心也。", "b": "《左传》"}]}, {"meaning": "隐藏;掩饰。", "cites": [{"t": "君日不悛,以乐慆忧。", "b": "《左传·昭公三年》"}]}, {"meaning": "怀疑。", "cites": [{"t": "天命不慆久矣,使君亡者,必此众也。", "b": "《左传》"}]}, {"meaning": "用同“叨”。贪。", "cites": [{"t": "不敢慆天之功,以干大赏。", "b": "《资治通鉴》"}]}, {"meaning": "怠惰。", "cites": [{"t": "无从匪彝,无即慆淫。", "b": "《书·汤诰》"}], "words": [{"w": "慆淫", "t": "享乐过度;放纵无度。"}]}]}]','jingmo-wenyan');
