INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7603wx','裼','1','tì xī','衤','13','','[{"pinyin": "tì", "defs": [{"meaning": "婴儿的包被。", "cites": [{"t": "乃生女子,载寝之地,载衣之裼。", "b": "《诗·小雅·斯干》。毛传:“裼,褓也。”"}]}]}, {"pinyin": "xī", "defs": [{"meaning": "脱去衣服露出上身。", "cites": [{"t": "裼,袒也。从衣,易声。", "b": "《说文》"}, {"t": "裼,脱衣见体也。", "b": "《玉篇》"}, {"t": "襢裼暴虎。", "b": "《诗·郑风·大叔于田》"}, {"t": "襢裼,肉袒。", "b": "《尔雅》"}, {"t": "徒裼以趋敌。", "b": "《史记·张仪传》"}, {"t": "闻战,顿足徒裼。", "b": "《战国策·初见秦》"}, {"t": "曹君袒裼而观之。", "b": "《韩非子·十过》"}], "words": [{"w": "袒裼", "t": "袒、裼都指脱去衣服,露出上身,但袒还指脱去衣袖露出上臂,问吉凶露左臂,受刑露右臂"}, {"w": "裼袭", "t": "古行礼时,袒外衣而露裼衣,且不尽覆其裘,谓之裼裘。非盛礼时,以此为敬。"}]}, {"meaning": "脱去外衣露出内衣。", "cites": [{"t": "裼降立。", "b": "《仪礼·聘礼》"}]}, {"meaning": "古代加在裘上面的无袖衣。", "cites": [{"t": "裘之裼也,见美也。", "b": "《礼记·玉藻》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7604wx','禋','1','yīn','礻','13','','[{"pinyin": "yīn", "defs": [{"meaning": "祭名。升烟祭天以求福。", "cites": [{"t": "禋,浩祀也。一曰精意,以享为禋。", "b": "《说文》"}, {"t": "精意以享禋也。", "b": "《国语·周语》"}, {"t": "厥初生民,时维姜嫄。生民如何?克禋克祀,以弗无子。", "b": "《诗·大雅·先民》"}], "words": [{"w": "禋天", "t": "祀天"}, {"w": "禋祀", "t": "古代祭天的一种礼仪。先燔柴升烟,再加牲体或玉帛于柴上焚烧"}, {"w": "禋柴", "t": "燔柴升烟以祭天"}, {"w": "禋礼", "t": "升烟祭天之礼仪。"}]}]}]','jingmo-wenyan');
