('7655wx','酺','1','pú','酉','14','','[{"pinyin": "pú", "defs": [{"meaning": "(形声。从酉(yǒu),甫声。从“酉”与酒有关。本义:聚饮。古指国有喜庆,特赐臣民聚会饮酒) 同本义。", "cites": [{"t": "酺,王德布大饮酒。", "b": "《说文》"}, {"t": "酺五日。", "b": "《汉书·文帝纪》"}], "words": [{"w": "酺燕", "t": "帝王下令准许臣民会聚饮酒为乐"}, {"w": "酺宴", "t": "聚会饮食"}, {"w": "酺会", "t": "聚会饮食"}, {"w": "酺饮", "t": "聚饮"}, {"w": "酺醵", "t": "聚会饮食。出钱为醵,出食为酺。"}]}, {"meaning": "神名。主人物灾害。", "cites": [{"t": "春秋祭酺。", "b": "《周礼·族师》"}], "words": [{"w": "祭", "t": "祭人物灾害之神。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7656wx','酾','1','shāi shī','酉','14','','[{"pinyin": "shāi", "defs": [{"meaning": "——“酾”(shī)的又音。"}]}, {"pinyin": "shī", "defs": [{"meaning": "滤。", "cites": [{"t": "酾,下酒也。一曰醇也。从酉,丽声。", "b": "《说文》"}, {"t": "酾酒有衍。", "b": "《诗·小雅·伐木》。传:“以筐曰酾,以薮曰湑。”"}, {"t": "援乃击牛酾酒,劳飨军士。", "b": "《后汉书·马援传》"}], "words": [{"w": "酾酒", "t": "滤酒。"}]}, {"meaning": "斟。", "cites": [{"t": "酾酒临江,横槊赋诗,固一世之雄也。", "b": "宋·苏轼《前赤壁赋》"}], "words": [{"w": "酾尊", "t": "斟酒。"}]}, {"meaning": "疏导。", "cites": [{"t": "既焚既酾,奇势迭出。", "b": "柳宗元《永州韦使君新堂记》"}], "words": [{"w": "酾沈澹灾", "t": "疏导分散水流以缓和消除灾情"}, {"w": "酾流", "t": "分流,支流"}, {"w": "酾浚", "t": "疏导。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7657wx','酲','1','chéng','酉','14','','[{"pinyin": "chéng", "defs": [{"meaning": "(形声。从酉(yǒu),呈声。“酉”,意思是酒。本义:酒醒后神志不清有如患病的感觉)。"}, {"meaning": "同本义。", "cites": [{"t": "酲,病酒也。", "b": "《说文》"}, {"t": "忧心如酲。", "b": "《诗·小雅·节南山》"}, {"t": "嗅之则使人狂酲。", "b": "《庄子·人间世》"}, {"t": "罔然若酲。", "b": "张衡《东京赋》"}], "words": [{"w": "酲困", "t": "酒后困疲如病"}, {"w": "酲酲", "t": "酒醉昏沉的样子。"}]}, {"meaning": "烦病。", "cites": [{"t": "嘘唏烦酲。", "b": "枚乘《七发》"}, {"t": "酲烦兮海鸟欲飞而无羽翼。", "b": "章炳麟《邹容画像赞》"}]}, {"meaning": "酒醒;清醒。", "cites": [{"t": "酲,一曰醉而觉也。", "b": "《说文》"}, {"t": "酲,醉解也。", "b": "《字林》"}, {"t": "其甘不爽,醉而不酲…", "b": "《文选·张衡·南都赋》"}]}, {"meaning": "酒醉不醒的。", "cites": [{"t": "景公饮酒,酲,三日而后发。", "b": "《晏子春秋》"}]}]}]','jingmo-wenyan');
