('7709wx','夐','1','xiòng','夂','14','','[{"pinyin": "xiòng", "defs": [{"meaning": "假借为“远”。辽远,距离遥远的。", "cites": [{"t": "于嗟夐兮。", "b": "《韩诗·击鼓》"}, {"t": "夐入千乘之国。", "b": "《谷梁传·文公十四年》"}, {"t": "与为夐明。", "b": "《吕氏春秋·尺数》"}, {"t": "夐若千里,人罕造其门。", "b": "《旧五代史》"}], "words": [{"w": "夐远辽远;夐隔", "t": "远隔"}, {"w": "夐寥", "t": "辽远"}, {"w": "夐然", "t": "辽远"}, {"w": "夐阻", "t": "远隔。"}]}, {"meaning": "久远,长久。", "cites": [{"t": "上哉夐昂?其书犹得而修也。", "b": "汉·班固《典引》"}], "words": [{"w": "夐古", "t": "远古"}, {"w": "夐然", "t": "久远。"}]}, {"meaning": "高超。", "cites": [{"t": "杜陵翁独为诗人冠冕者,吐辞不凡,夐出尘表。", "b": "宋·孙奕《履斋示儿编·诗说》"}]}, {"meaning": "高尚。", "cites": [{"t": "介君祠庙在,风义夐难攀。", "b": "清·顾炎武《介休》"}]}, {"meaning": "常常。", "cites": [{"t": "潜心密与造化会,布指夐有精灵随。", "b": "宋·曾巩《送刘医博》"}]}]}]','jingmo-wenyan');
