INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7714wx','廑','1','jǐn qín','广','14','','[{"pinyin": "jǐn", "defs": [{"meaning": "小屋。", "cites": [{"t": "廑,少劣之居。从广,堇声。", "b": "《说文》"}, {"t": "小屋谓之曰廑。", "b": "宋·李诫《营造法式》"}]}, {"meaning": "假借为“仅”。才,只。", "cites": [{"t": "其次廑得舍人。", "b": "《汉书·贾谊传》"}, {"t": "茅焦亦廑脱死。", "b": "《汉书·邹阳传》"}, {"t": "贾廑从旅。", "b": "《汉书·叙传》"}]}, {"meaning": "蒙受;接受。"}]}, {"pinyin": "qín", "defs": [{"meaning": "殷勤。", "cites": [{"t": "广阿之廑。", "b": "《汉书·叙传》"}, {"t": "其廑至矣。", "b": "《汉书·扬雄传下》。颜师古注:“廑,古勤字”"}], "words": [{"w": "廑怀", "t": "廑虑。殷切挂念"}, {"w": "廑念", "t": "殷切关注"}, {"w": "廑注", "t": "廑念。旧时书信中常用之。"}]}, {"meaning": "怀念。", "cites": [{"t": "六宫廑北狩之忧,群臣倡南迁之仪。", "b": "《于谦全传》"}]}]}]','jingmo-wenyan');
