INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7716wx','瘗','1','yì','疒','14','','[{"pinyin": "yì", "defs": [{"meaning": "埋物祭地。", "cites": [{"t": "有年瘗土,无年瘗土。", "b": "《吕氏春秋》。高诱注:“祭土曰瘗。年,谷也。有谷祭土,报其功也。无谷祭土,禳其神也。”"}, {"t": "伊年暮春,将瘗后土。", "b": "汉·扬雄《河东赋》"}], "words": [{"w": "瘗坎", "t": "古代行祭地礼时用以埋牲、玉帛的坑穴"}, {"w": "瘗地", "t": "祭土地神"}, {"w": "瘗玉", "t": "古代祭山礼仪,治礼毕埋玉于坑"}, {"w": "瘗土", "t": "祭土地神"}, {"w": "瘗毛血", "t": "古时祭宗宙和孔庙的一种仪式"}, {"w": "瘗位", "t": "设瘗坎之处"}, {"w": "瘗埋", "t": "古代祭地礼仪之一"}, {"w": "瘗缯", "t": "古代埋缯帛以祭地。"}]}, {"meaning": "埋葬。", "cites": [{"t": "夭赤子于新安,坎路侧而瘗之。", "b": "晋·潘岳《西征赋》"}], "words": [{"w": "瘗土", "t": "用土埋葬"}, {"w": "瘗埋", "t": "埋葬"}, {"w": "瘗葬", "t": "埋葬"}, {"w": "瘗藏", "t": "指殉葬品;埋葬。"}]}, {"meaning": "埋藏;隐藏。", "cites": [{"t": "瘗,藏也。", "b": "《玉篇》"}, {"t": "瘗,幽埋也。", "b": "《说文》"}, {"t": "会人有盗发孝文园瘗钱。", "b": "《史记·酷吏列传》"}, {"t": "瘗,幽隐也。", "b": "《集韵》"}, {"t": "寇准瘗谷敌兵畏。", "b": "魏源《城守篇》"}, {"t": "寇准瘗谷敌兵畏。", "b": "清·魏源《城守篇》"}], "words": [{"w": "瘗钱", "t": "古代葬礼置于墓中陪葬的钱财。"}]}, {"meaning": "坟墓。", "cites": [{"t": "埋我,以竹杖柱于瘗上,若杖折,掘出我。", "b": "晋·干宝《搜神记》"}]}]}]','jingmo-wenyan');
