('7717wx','瘥','1','chài cuó','疒','14','','[{"pinyin": "chài", "defs": [{"meaning": "病除(病已去体;病有好转)。", "cites": [{"t": "患既未瘥,眠也不安。", "b": "《续世说·夙慧》"}], "words": [{"w": "久病初瘥", "t": ""}]}, {"meaning": "治好病。", "cites": [{"t": "泉源沸涌,冬夏汤汤,望之则白气浩然,言能瘥百病云。", "b": "《水经注·沔水》"}]}]}, {"pinyin": "cuó", "defs": [{"meaning": "病;疫病。", "cites": [{"t": "瘥,病也。", "b": "《说文》"}, {"t": "无天昏札瘥之忧。", "b": "《国语·周语》。注:“病也。”"}, {"t": "天方荐瘥。", "b": "《诗·小雅·节南山》"}, {"t": "札瘥夭昏。", "b": "《左传·昭公十九年》。贾注:“小疫曰瘥。”"}], "words": [{"w": "瘥札", "t": "疫病"}, {"w": "瘥瘼", "t": "谓疫病疾苦"}, {"w": "瘥疠", "t": "瘟疫"}, {"w": "瘥昏", "t": "昏忽、迷乱之病。"}]}, {"meaning": "喻指缺点。", "cites": [{"t": "气高或怒张,微疵玉之瘥。", "b": "明·宋濂《潜溪录》"}]}]}]','jingmo-wenyan');
