('7735wx','窭','1','jù','穴','14','','[{"pinyin": "jù", "defs": [{"meaning": "(形声。从穴,娄声。字本作“窶”。“穴”与“宀”相通,都表示与房屋有关。本义:贫穷得无法备礼物。亦泛指贫穷)。"}, {"meaning": "同本义。", "cites": [{"t": "窭,无礼居也。", "b": "《说文》。按,贫居无礼也。俗字作窭"}, {"t": "窭,贫也。", "b": "《尔雅》"}, {"t": "无财备礼曰窭。", "b": "《三苍》"}, {"t": "主人辞以窭。", "b": "《礼记·曲礼》"}, {"t": "又诸儒生多窭人子。", "b": "《汉书·霍光传》"}, {"t": "终窭我贫,莫知我艰。", "b": "《诗·邶风·北门》"}], "words": [{"w": "窭困", "t": "贫乏困苦"}, {"w": "窭人子", "t": "穷苦人家的孩子"}, {"w": "窭贫", "t": "贫穷"}, {"w": "窭艰", "t": "贫穷艰难。"}]}, {"meaning": "破旧。", "cites": [{"t": "衣服窭甚。", "b": "宋·韩淲《涧泉日记》"}], "words": [{"w": "窭甚", "t": "衣服破旧。"}]}]}]','jingmo-wenyan');
