('7766wx','霅','1','zhà','雨','15','','[{"pinyin": "zhà", "defs": [{"meaning": "霅霅。雷电交作。", "cites": [{"t": "霅,霅霅震电兒。", "b": "《说文》"}]}, {"meaning": "引申为震慑。", "cites": [{"t": "天谴不能使霅,而独畏匹夫匹妇之口,何以?", "b": "明·冯梦龙《古今谭概》"}]}, {"meaning": "欢声雷动的样子。", "cites": [{"t": "闻者莫不霅然称快。", "b": "明·田汝成《西湖游览志余》"}]}, {"meaning": "光耀闪烁的样子。", "cites": [{"t": "霅霅前溪白,苍苍后岭巍。", "b": "宋·梅尧臣《明月楼》"}], "words": [{"w": "霅晃", "t": "光明的样子。"}]}, {"meaning": "浙江省湖州市的别称 。因境内有霅溪而得名。又称霅上。"}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7767wx','暵','1','hàn','日','15','','[{"pinyin": "hàn", "defs": [{"meaning": "干旱。", "cites": [{"t": "暵,干也。耕暴田曰暵。易曰:“燥万物者莫暵于离。”", "b": "《说文》"}], "words": [{"w": "暵旱", "t": "干旱;天旱"}, {"w": "暵魃", "t": "即旱魃。传说中谓能造成旱灾的怪物。"}]}, {"meaning": "干枯;萎缩。", "cites": [{"t": "中谷有蓷,暵其干矣。", "b": "《诗·王风·中谷有蓷》"}]}, {"meaning": "热。", "cites": [{"t": "教皇舞帅而舞旱暵之事。", "b": "《周礼·舞帅》。注:“热气也。”"}], "words": [{"w": "暵热", "t": "炎热"}, {"w": "暵赫", "t": "暑气灼人。"}]}, {"meaning": "干涸。", "cites": [{"t": "阴淫为霖,神能散之;下士垫涝,神能暵之。", "b": "苏轼《祈晴风伯》"}]}]}]','jingmo-wenyan');
