INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7771wx','踣','1','bó','足','15','','[{"pinyin": "bó", "defs": [{"meaning": "向前仆倒。", "cites": [{"t": "踣,僵也。", "b": "《说文》"}, {"t": "甲徒狄因以踣河。", "b": "《庄子·外物》"}, {"t": "与晋踣之。", "b": "《左传·襄公十四年》"}, {"t": "神物怪疑,不可胜言,直使人踣焉。", "b": "枚乘《七发》"}, {"t": "一卒持剑刺应元贯胫;胫折踣地。", "b": "清·邵长蘅《青门剩稿》"}]}, {"meaning": "泛指跌倒,摔倒。", "cites": [{"t": "号呼而转徙,饥渴而顿踣。", "b": "唐·柳宗元《捕蛇者说》"}], "words": [{"w": "屡踣屡起;踣顿", "t": "颠仆,跌倒"}, {"w": "踣跌", "t": "跌仆,跌交。"}]}, {"meaning": "陈尸。", "cites": [{"t": "凡杀人者踣诸市,肆之三日。", "b": "《周礼·秋官·掌戮》"}], "words": [{"w": "踣尸", "t": "陈尸"}, {"w": "踣籍", "t": "死伤枕藉。"}]}, {"meaning": "颠覆;灭亡,败亡。", "cites": [{"t": "设用无度国家踣。", "b": "《管子·七臣七主》。注:“谓散亡也。”"}, {"t": "队命亡氏,踣其国家。", "b": "《左传·襄公十一年》"}], "words": [{"w": "踣覆", "t": "倾覆,打倒"}, {"w": "踣国", "t": "颠覆国家。"}]}, {"meaning": "倒毙。", "cites": [{"t": "纣踣于京。", "b": "《国语·鲁语上》"}]}]}]','jingmo-wenyan');
