('7804wx','觭','1','jī','角','15','','[{"pinyin": "jī", "defs": [{"meaning": "像两个角一向上一向下弯的,不对称的。", "cites": [{"t": "觭,角一俯一仰也。从角,奇声。", "b": "《说文》"}, {"t": "荀木其牛觭。", "b": "《易·睽》"}], "words": [{"w": "觭重", "t": "偏重。"}]}, {"meaning": "单独。", "cites": [{"t": "匹马觭轮无反者。", "b": "《汉书·五行志》引《公羊传》。注:“只也。”"}], "words": [{"w": "觭介", "t": "单独,偏于一面。"}]}, {"meaning": "奇怪。", "cites": [{"t": "二曰觭梦。", "b": "《周礼·大卜》"}]}, {"meaning": "获得、得到。", "cites": [{"t": "二曰觭梦。", "b": "《周礼》"}]}]}]','jingmo-wenyan');
