('7808wx','糈','1','xǔ','米','15','','[{"pinyin": "xǔ", "defs": [{"meaning": "粮食。", "cites": [{"t": "糈,粮也。从米,胥声。", "b": "《说文》"}, {"t": "鼠壤有余糈。", "b": "《庄子·天道》。司马注:“粒也。”"}]}, {"meaning": "粮饷。", "cites": [{"t": "然后选取材武之士,务求勇、力、捷、技冠绝侪辈者,三倍其糈。", "b": "《书牍·复太史焦座师》"}]}, {"meaning": "古代祭神用的精米。", "cites": [{"t": "怀椒糈而要之。", "b": "《离骚》。注:“精米所以享神也。”"}, {"t": "夫卜而有不审,不见夺糈。", "b": "《史记·日者传》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7809wx','翦','1','jiǎn','羽','15','','[{"pinyin": "jiǎn", "defs": [{"meaning": "初生的羽毛。", "cites": [{"t": "翦,羽初生也。一曰矢羽。", "b": "《说文》。王筠注:“翦者谓新生之羽,整齐之状也。”段玉裁注:“羽初生如前齐也。前,古之翦字。”"}]}, {"meaning": "剪整齐。", "cites": [{"t": "实始翦商。", "b": "《诗·鲁颂·閟宫》"}, {"t": "翦,齐也。", "b": "《释言》"}, {"t": "茅茨不翦。", "b": "《韩非子·五蠹》"}], "words": [{"w": "翦缀", "t": "裁剪缝纫"}, {"w": "翦发", "t": "修剪头发"}, {"w": "翦灯", "t": "修剪灯芯。后常指夜谈。"}]}, {"meaning": "割截;杀戮。", "cites": [{"t": "不翦其类也。", "b": "《礼记·文王世子》。注:“割截也。”"}], "words": [{"w": "翦刈", "t": "铲除"}, {"w": "翦草除根", "t": "比喻彻底清除,不留后患"}, {"w": "翦翎", "t": "剪除羽翎。常以喻因受羁缚,才能不得伸展"}, {"w": "翦棘", "t": "斩除荆棘。"}]}, {"meaning": "削减。", "cites": [{"t": "毋是翦弃。", "b": "《左传·襄公十四年》。注:“削也。”"}, {"t": "卫人翦夏戊。", "b": "《左传·哀公十一年》。注:“削其爵邑也。”"}, {"t": "其翦以赐诸侯,使臣妾之。", "b": "《左传·宣公十二年》。杜预注:“翦,削也。”"}], "words": [{"w": "翦抑", "t": "削弱;压制"}, {"w": "翦弱", "t": "削弱。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
