('7812wx','熛','1','biāo','火','15','','[{"pinyin": "biāo", "defs": [{"meaning": "火星迸飞,也指迸飞的火焰。", "cites": [{"t": "熛,火飞也。从火,票声。", "b": "《说文》"}, {"t": "火烈熛林。", "b": "左思《吴都赋》"}, {"t": "百尺之宝,以突隙之熛焚。", "b": "《韩非子》"}], "words": [{"w": "熛炭", "t": "燃烧着的炭火。熛:迸飞的火焰"}, {"w": "熛火", "t": "火焰"}, {"w": "熛矢", "t": "带火的箭矢。"}]}, {"meaning": "光。", "cites": [{"t": "海内云蒸,雷动电摽。", "b": "《后汉书》。李贤注:“熛,光也。”"}]}, {"meaning": "暴风。", "cites": [{"t": "雷动熛至,星流霆击。", "b": "《史记·司马相如列传》"}, {"t": "胜广熛起,梁籍扇烈。", "b": "《汉书·叙传下》"}], "words": [{"w": "熛至", "t": "指疾风迅猛来临。比喻来势迅猛。"}]}, {"meaning": "迅疾。", "cites": [{"t": "气冲郁而熛起。", "b": "成公子安《啸赋》"}], "words": [{"w": "熛风", "t": "迅急的风"}, {"w": "熛起", "t": "迅猛而起。"}]}]}]','jingmo-wenyan');
