('7910wx','憺','1','dàn','忄','16','','[{"pinyin": "dàn", "defs": [{"meaning": "安然。", "cites": [{"t": "憺,安也。从心,詹声。与倓略同。", "b": "《说文》"}, {"t": "观者憺兮亡归。", "b": "《楚辞·东君》。注:“安也。”"}], "words": [{"w": "憺憺", "t": "安然,镇静。"}]}, {"meaning": "恬静;清静。", "cites": [{"t": "憺乎自持。", "b": "司马相如《子虚赋》。注:“憺泊,静也。”"}, {"t": "蜂虿螫指而神不能憺。", "b": "《淮南子·俶真》。注:“定也。”"}], "words": [{"w": "憺泊", "t": "澹泊,恬静"}, {"w": "憺然", "t": "安静,恬淡的样子。"}]}, {"meaning": "震动;使人畏惧。", "cites": [{"t": "是以名声暴于夷貉,威棱憺乎邻国。", "b": "《汉书·李广传》"}], "words": [{"w": "憺畏", "t": "畏惧。"}]}]}]','jingmo-wenyan');
