('7911wx','懔','1','lǐn','忄','16','','[{"pinyin": "lǐn", "defs": [{"meaning": "(形声。从心,禀(bǐng)声。本义:危惧,恐惧)。"}, {"meaning": "同本义。", "cites": [{"t": "懔懔焉若恃腐索之扞馬。", "b": "《孔子家语·致思》。注:“戒惧之貌。”"}, {"t": "心懔懔以怀霜。", "b": "陆机《文赋》。注:“危惧貌。”"}, {"t": "懔乎若朽索之驭六马。", "b": "《书·五子之歌》"}], "words": [{"w": "懔然", "t": "危惧的样子;戒惧的样子"}, {"w": "懔厉", "t": "惶恐"}, {"w": "懔忧", "t": "忧惧"}, {"w": "懔懔", "t": "危惧的样子;戒惧的样子。"}]}, {"meaning": "严肃;令人敬畏。", "cites": [{"t": "懔,敬也。", "b": "《广雅》"}, {"t": "廉颇蔺相如虽千载上死人,懔懔恒如有生气。", "b": "《世说新语·品藻》"}], "words": [{"w": "懔惧", "t": "畏惧"}, {"w": "懔畏", "t": "畏惧。"}]}]}]','jingmo-wenyan');
