('7972wx','襕','1','lán','衤','17','','[{"pinyin": "lán", "defs": [{"meaning": "上下衣相连的服装。", "cites": [{"t": "身穿着绿襕,手拿着一管笔。", "b": "孟汉卿《魔合罗》"}], "words": [{"w": "襕衫", "t": "古代士人之服。因其于衫下施横襕为裳,故称"}, {"w": "襕袍", "t": "古代的一种公服。因其于袍下施横襕为裳,故称。明、清时为秀才举人之公服。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('7973wx','襚','1','suì','衤','17','','[{"pinyin": "suì", "defs": [{"meaning": "古吊丧之礼。为死者穿衣。", "cites": [{"t": "襚,衣死人也。从衣,遂声。", "b": "《说文》"}, {"t": "楚使公亲襚。", "b": "《春秋传》"}, {"t": "襚遗也。", "b": "《春秋说题辞》"}], "words": [{"w": "亲襚", "t": "亲手给死者穿衣"}, {"w": "襚敛", "t": "给死者穿衣入棺。"}]}, {"meaning": "向死者赠衣被。", "cites": [{"t": "襚,送也。货财曰赙,车马曰赗,衣衾曰襚。即袭也。", "b": "《广雅》"}], "words": [{"w": "襚礼", "t": "吊丧者赠送死者的衣衾等物"}, {"w": "向襚", "t": "向死者赠衣被"}, {"w": "襚衣", "t": "襚服。赠送给死者的衣服。"}]}, {"meaning": "赠活人衣服。", "cites": [{"t": "今日喜辰,贵姊懋膺洪册,谨上襚三十五条,以陈踊跃之心。", "b": "《西京杂记》"}]}]}]','jingmo-wenyan');
