('8012wx','皦','1','jiǎo','白','18','','[{"pinyin": "jiǎo", "defs": [{"meaning": "光亮洁白。", "cites": [{"t": "皦,玉石之白也。", "b": "《说文》"}, {"t": "皦,明也。", "b": "《方言十二》"}, {"t": "有如皦日。", "b": "《诗·王风·大车》"}, {"t": "譬如玉石,皦然可知。", "b": "《汉书·高闾传》"}], "words": [{"w": "皦日", "t": "明亮的太阳"}, {"w": "皦心", "t": "光明磊落的心胸"}, {"w": "皦白", "t": "洁白"}, {"w": "皦然", "t": "洁白光亮"}, {"w": "皦洁", "t": "明亮洁白。"}]}, {"meaning": "分明;清晰。", "cites": [{"t": "其上不皦,其下不昧。", "b": "《老子》"}], "words": [{"w": "皦如", "t": "清晰;分明。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('8013wx','臑','1','ér nào','月','18','','[{"pinyin": "ér", "defs": [{"meaning": "煮,煮烂。", "cites": [{"t": "肥牛之腱,臑若芳些。", "b": "《楚辞·招魂》"}], "words": [{"w": "臑鳖", "t": "煮烂的鳖肉。"}]}]}, {"pinyin": "nào", "defs": [{"meaning": "人的上肢。亦指臂之羊矢穴臑,臂羊矢也。——《说文》。"}, {"meaning": "按,臂上也。羊豕曰臑,在人曰肱。", "cites": [{"t": "肩臂臑。", "b": "《仪礼·少牢馈食礼》。注:“肱骨。”"}, {"t": "折肩肋肺臑。", "b": "《仪礼·乡射礼记》"}]}, {"meaning": "牲畜前肢的上部。", "cites": [{"t": "取前足臑骨穿佩之。", "b": "《史记·龟策列传》"}]}, {"meaning": "煮。", "cites": [{"t": "鼎臑盈望,致和芳只。", "b": "屈原《大招》"}]}]}]','jingmo-wenyan');
