('8067wx','瀹','1','yuè','氵','20','','[{"pinyin": "yuè", "defs": [{"meaning": "浸渍。", "cites": [{"t": "瀹,渍也。从水,龠声。", "b": "《说文》"}, {"t": "汝齐戒疏蘥而心。", "b": "《庄子·知北游》"}, {"t": "菅筲三,其实皆瀹。", "b": "《仪礼》。贾公彦疏:“筲用菅草,黍稷皆淹而渍之。”"}]}, {"meaning": "煮。", "cites": [{"t": "不如西邻之瀹祭。", "b": "《汉书·郊祀志》。注;“谓瀹煮新菜以祭。”"}, {"t": "以汤煮物曰瀹。", "b": "《通欲文》"}, {"t": "兰台架列排曲瓢卷浆,乃羹乃瀹。", "b": "南朝宋·鲍照《园葵赋》"}], "words": [{"w": "瀹茶", "t": "煮茶"}, {"w": "瀹茗", "t": "煮茶"}, {"w": "瀹祭", "t": "煮新菜以祭祀。"}]}, {"meaning": "疏通水道,使水流通畅。", "cites": [{"t": "禹疏九河,瀹济漯而注诸海。", "b": "《孟子·滕文公上》"}]}, {"meaning": "亦泛指引导使畅通。", "cites": [{"t": "疏瀹五藏,澡雪精神。", "b": "《文心雕龙》"}], "words": [{"w": "瀹疏", "t": "疏浚。"}]}]}]','jingmo-wenyan');
