('8074wx','耰','1','yōu','耒','21','','[{"pinyin": "yōu", "defs": [{"meaning": "古代的一种农具,弄碎土块,平整田地用。", "cites": [{"t": "民以耰鉏櫄梃相挞击,犯法滋蟓,盗贼不胜。", "b": "《汉书》。颜师古注:“耰,摩田之器也。”"}], "words": [{"w": "耰钼", "t": "用来平田松土的农具。"}]}, {"meaning": "锄把。", "cites": [{"t": "鉏耰棘矜,不敌于钩戟长鎩。", "b": "《汉书》颜师古注引服虔曰:“耰,鉏柄也。”"}]}, {"meaning": "用耰松土并使土块细碎。亦指覆种。", "cites": [{"t": "播种而耰之。", "b": "《孟子》"}], "words": [{"w": "耰锄", "t": "犹耡耰。"}]}, {"meaning": "泛指耕种。", "cites": [{"t": "使农不辍耰,工不下机。", "b": "汉·扬雄《长杨赋》"}], "words": [{"w": "耰耦", "t": "泛指从事耕种的人。"}]}]}]','jingmo-wenyan');
