INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('8093wx','躔','1','chán','足','22','','[{"pinyin": "chán", "defs": [{"meaning": "(形声。从足,廛(chán)声。本义:践,践履)。"}, {"meaning": "同本义。", "cites": [{"t": "躔,践也。", "b": "《说文》"}, {"t": "未知英雄之所躔也。", "b": "晋·左思《吴都赋》"}], "words": [{"w": "躔躔的", "t": "快速舞动或转动"}, {"w": "躔陛", "t": "指石级。"}]}, {"meaning": "运行。", "cites": [{"t": "躔,历行也。日运为躔,月运为逡。", "b": "《方言十二》"}, {"t": "躔,行也。", "b": "《广雅》"}, {"t": "日月初躔。", "b": "《汉书·律历志上》"}, {"t": "月躔二十八宿。", "b": "《吕氏春秋·圜道》"}]}, {"meaning": "日月星辰在黄道上运行  如:躔次(日月星辰在运行轨道上的位次);躔度(日月星辰运行的度数)。"}, {"meaning": "麋鹿的足迹。又泛指脚迹,行迹。", "cites": [{"t": "麋其迹躔。", "b": "《尔雅》。注:“脚所践也。”"}, {"t": "或云治蜀,盖以其迹躔焉。", "b": "《路史·循蜚纪》"}]}]}]','jingmo-wenyan');
