('8095wx','龢','1','hé','龠','22','','[{"pinyin": "hé", "defs": [{"meaning": "(通作“和”)。"}, {"meaning": "和谐;协调。", "cites": [{"t": "龢,调也。读与和同。", "b": "《说文》。段玉裁注:“经传多借和为龢。”"}, {"t": "正六律,龢五声,杂八音,养耳之道也。", "b": "《吕氏春秋》"}]}, {"meaning": "和睦。", "cites": [{"t": "其终也,广厚其心,以固龢之。", "b": "《国语》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('8096wx','鳤','1','guǎn','鱼','22','','[{"pinyin": "guǎn", "defs": [{"meaning": "一种鱼 (Ochetobius elongatus),鱼纲,鲤科。体长圆筒形,长约30-60厘米。银白色,鳞小,头小而尖,口端位,无须。主食无脊椎动物和小鱼,为淡水养殖业害鱼。"}]}]','jingmo-wenyan');
