('8097wx','亹','1','mén wěi','亠','22','','[{"pinyin": "mén", "defs": [{"meaning": "水流夹山处。", "cites": [{"t": "亹者,水流夹山,岸若门。", "b": "《晋书·音义上》"}, {"t": "拒浩亹隘。", "b": "《后汉书·马援传》"}]}]}, {"pinyin": "wěi", "defs": [{"meaning": "勤勉不倦。", "cites": [{"t": "亹亹,勉也。", "b": "《尔雅·释诂》"}, {"t": "成天下之亹亹者。", "b": "《易·系辞上》"}, {"t": "亹亹文王。", "b": "《诗·大雅·文王》"}, {"t": "亹亹不舍昼夜。", "b": "《汉书·张敞传》"}], "words": [{"w": "亹斐", "t": "勤勉"}, {"w": "亹亹穆穆", "t": "勤勉庄敬。"}]}, {"meaning": "修养。", "cites": [{"t": "夫是以内亹其性情而外纲其皇极,[其]緼之也有原,其出之也有伦,其究极之也动天地而感鬼神。", "b": "清·魏源《默觚上》"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('8098wx','籥','1','yuè','竹','23','','[{"pinyin": "yuè", "defs": [{"meaning": "假借为“龠”。古管乐器。", "cites": [{"t": "左手执籥。", "b": "《诗·邶风·简兮》"}, {"t": "籥舞笙鼓。", "b": "《诗·小雅·宾之初筵》"}, {"t": "苇籥,伊耆氏之乐也。", "b": "《礼记·明堂位》"}, {"t": "管籥之音。", "b": "《孟子·梁惠王下》"}, {"t": "迟衡山把籥、翟交与这些孩子。", "b": "《儒林外史》"}], "words": [{"w": "籥舞", "t": "文舞。吹籥而舞,舞时依照籥声为节拍"}, {"w": "籥师", "t": "古官名。"}]}, {"meaning": "鼓风吹火的竹器。", "cites": [{"t": "天地之间,其犹橐籥乎?", "b": "《老子》。吴澄注:“橐籥,冶铸所用嘘风炽火之器也。为函以周罩於外者,橐也;为辖以鼓扇子内者,籥也。”"}]}, {"meaning": "锁钥。", "cites": [{"t": "启籥见书。", "b": "《书·金滕》"}, {"t": "诸城门吏,各入请籥,开门已,辄复上籥。", "b": "《墨子》"}], "words": [{"w": "籥牡", "t": "锁闩;锁钥。"}]}]}]','jingmo-wenyan');
