('8582wx','阬','1','kēng','阝','6','','[{"pinyin": "kēng", "defs": [{"meaning": "(坑的异体字)(形声。从阜(fù),表示与地形地势的高低上下有关。亢声。本义:洼地,土坑)。"}, {"meaning": "同本义。", "cites": [{"t": "阬。虚也。", "b": "《尔雅·释诂》。注:“谓阬堑也。”"}, {"t": "弥纶阬泽。", "b": "《后汉书·马融传》。注引《苍颉》:“阬,壑也。”"}, {"t": "在谷满谷,在阬满阬。", "b": "《庄子·天运》"}, {"t": "刘玙兄弟少时为王恺所憎,尝召二人宿,欲默除之。令作阬,阬毕,垂加害矣。", "b": "《世说新语·仇隙》"}], "words": [{"w": "阬阱", "t": "深坑"}, {"w": "阬谷", "t": "沟壑溪谷"}, {"w": "阬泽", "t": "沟壑与大泽"}, {"w": "阬岸", "t": "坑堑,沟壑。"}]}, {"meaning": "掘地采矿之洞穴。", "cites": [{"t": "弛邕州金阬禁。", "b": "《新唐书》"}]}, {"meaning": "活埋。", "cites": [{"t": "已拔,皆阬之。", "b": "《史记·项羽本纪》"}], "words": [{"w": "阬儒", "t": "秦始皇于咸阳活埋儒生460余人。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
