('10018wx','拏','1','ná','手','9','','[{"pinyin": "ná", "defs": [{"meaning": "持拿;执取", "cites": [{"t": "拏,持也。从手,奴声。", "b": "《说文》"}, {"t": "拏,捽也。", "b": "《苍颉篇》"}, {"t": "少年心事当拏云,谁念幽寒坐鸣呃。", "b": "李贺《致酒行》"}, {"t": "有合佥押的文书,拏来我佥押。", "b": "孟汉卿《魔合罗》"}], "words": [{"w": "拏事", "t": "管事;掌权"}, {"w": "拏空", "t": "凌空,抓向空中"}, {"w": "拏手", "t": "作事有把握;擅长"}, {"w": "拏云", "t": "比喻志向远大,本领高强"}, {"w": "拏把", "t": "抓住。"}]}, {"meaning": "搏斗。", "cites": [{"t": "熊虎升而拏攫。", "b": "张衡《西京赋》。注:“相搏持也。”"}], "words": [{"w": "拏战", "t": "搏斗"}, {"w": "拏攫", "t": "搏斗"}, {"w": "拏斗", "t": "争斗。"}]}, {"meaning": "捉拿;捕捉。", "cites": [{"t": "知县把一干拏到的邻舍当厅勘问。", "b": "《水浒传》"}], "words": [{"w": "拏把", "t": "抓住"}, {"w": "拏究", "t": "捉拿查究"}, {"w": "拏访", "t": "捉拿查访"}, {"w": "拏获", "t": "捕获,捉获"}, {"w": "拏人", "t": "犹捕役,捕快。"}]}, {"meaning": "牵连;连结。", "cites": [{"t": "祸拏未解,兵连不息。", "b": "《后汉书·冯衍传》"}], "words": [{"w": "拏兵", "t": "引兵"}, {"w": "拏云攫石", "t": "古树参天,根盘石隙的雄姿。"}]}]}]','jingmo-wenyan');
