INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('10554wx','閤','1','gé','鬥','10','','[{"pinyin": "gé", "defs": [{"meaning": "(形声。从门,合声。本义:旁门,小门)。"}, {"meaning": "同本义。", "cites": [{"t": "閤,门旁户也。", "b": "《说文》"}, {"t": "宫中之门谓之闱,其小者谓之闺,小闺谓之閤。", "b": "《尔雅》"}, {"t": "开东閤。", "b": "《汉书·公孙弘传》。注:“小门也。”按,或言东閤,或言南閤西閤,唐时御便殿曰入閤,谓立仪于前殿,唤仗则自东西閤入也。凡上书言閤下者,犹言门下,谦不敢称正门之下,谓旁之下也,犹言下执事也。"}, {"t": "升降秘阁。", "b": "《陆机诗》。注:“即尚书省也。其字误作止屏之阁。今内阁阁下,字皆误作阁。”"}], "words": [{"w": "閤门", "t": "古代宫殿的侧门"}, {"w": "閤职", "t": "宋代属于閤门的官职。"}]}, {"meaning": ""}, {"meaning": "中央官署名。内阁之略称。", "cites": [{"t": "于是府丞诣閤,博乃见丞掾。", "b": "《汉书·朱博传》"}], "words": [{"w": "閤长", "t": "唐宋时称呼中书省等官署的主事官"}, {"w": "閤署", "t": "官署。"}]}, {"meaning": "楼阁。", "cites": [{"t": "妆閤伎楼何寂寞,柳似舞腰池似镜。", "b": "白居易《两朱阁诗》"}]}, {"meaning": "古代宾馆。", "cites": [{"t": "千金弃不惜,宾客常满閤。", "b": "宋·王安石《韩持国从富并州辟》"}]}, {"meaning": "内室;卧室。", "cites": [{"t": "兰房椒閤夜方开。", "b": "梁元帝《乌栖曲》"}, {"t": "小閤重衾不怕寒。", "b": "白居易《重题》"}], "words": [{"w": "閤正", "t": "对他人妻子的敬称"}, {"w": "閤分", "t": "宋代对妃嫔的称呼。"}]}, {"meaning": "姓。"}]}]','jingmo-wenyan');
