('10613wx','闉','1','yīn','鬥','10','','[{"pinyin": "yīn", "defs": [{"meaning": "瓮城(古代城门外层的曲城)的门。", "cites": [{"t": "闉,城曲重门也。", "b": "《说文》。徐锴系传:“若今门外壅城门也。”"}, {"t": "出其闉誾。", "b": "《诗·郑风·出其东门》"}], "words": [{"w": "闉闍", "t": "瓮城的重门。"}]}, {"meaning": "瓮城或瓮城一带。", "cites": [{"t": "经途延旧轨,登闉访川陆。", "b": "南朝宋·颜延之《登巴陵城楼》"}], "words": [{"w": "闉隍", "t": "城池"}, {"w": "闉池", "t": "干涸的城壕。"}]}, {"meaning": "城。", "cites": [{"t": "南则颓闉废郭。", "b": "清·陈梦雷《又与徐健庵书》"}], "words": [{"w": "闉市", "t": "城市。"}]}, {"meaning": "屈曲。", "cites": [{"t": "闉,曲也。", "b": "《字汇补》"}, {"t": "闉跂支离无脤。", "b": "《庄子·德充符》。司马注:“曲也。”"}], "words": [{"w": "闉扼", "t": "马曲颈脱轭"}, {"w": "闉跂", "t": "脚卷曲,脚尖点地走路。"}]}, {"meaning": "堵塞。", "cites": [{"t": "以共闉圹之蜃。", "b": "《周礼·地官下》"}, {"t": "而相为斥闉之要遮者。", "b": "《淮南子·兵略》"}, {"t": "求闉池者,以火与争鼓闉。", "b": "《墨子》"}], "words": [{"w": "闉厄", "t": "阻塞、艰难。"}]}]}]','jingmo-wenyan');
