('11492wx','痎','1','jiē','疒','11','','[{"pinyin": "jiē", "defs": [{"meaning": "(形声。从手,曷声。本义:高举)。"}, {"meaning": "同本义。", "cites": [{"t": "揭,高举也。", "b": "《说文》"}, {"t": "西柄之揭。", "b": "《诗·小雅·大东》"}, {"t": "修剑揭以低昂。", "b": "张衡《思玄赋》"}, {"t": "揭其剑。", "b": "《战国策·齐策四》"}, {"t": "揭竿为旗", "b": "汉·贾谊《过秦论》"}, {"t": "两竿夹接。", "b": "明·高启《书博鸡者事》"}], "words": [{"w": "揭厉", "t": "高举而扬厉之"}, {"w": "揭鸡肆赦", "t": "在高竿上树起金鸡,宣布大赦。"}]}, {"meaning": "肩负;担;扛。", "cites": [{"t": "负匮揭箧担囊而趋。", "b": "《庄子·胠箧》"}], "words": [{"w": "揭箧", "t": "把箱笼扛走;比喻全部抄袭他人文字。"}]}, {"meaning": "披露;发表;公布。", "cites": [{"t": "会闱揭晓,名次群英。", "b": "李昌祺《前灯余话》"}], "words": [{"w": "揭条", "t": "揭桃。揭调,揭露别人的短处"}, {"w": "揭旧书", "t": "方言。揭老底"}, {"w": "揭极", "t": "揭发恶性的报告"}, {"w": "揭参", "t": "揭发弹劾"}, {"w": "揭黄", "t": "用黄榜公布"}, {"w": "揭载", "t": "刊登;发表"}, {"w": "揭贴", "t": "张贴。"}]}, {"meaning": "掀起; 拿开。", "cites": [{"t": "揭水指路。", "b": "唐·李朝威《柳毅传》"}, {"t": "一个客人便去揭开桶盖。", "b": "《水浒传》"}], "words": [{"w": " 揭白", "t": "旧时人死后,请画师给死人画像。首先要揭去死人脸上蒙的白纸,故名"}, {"w": "揭地掀天", "t": "翻天覆地。"}]}, {"meaning": "露出;向上翘。", "cites": [{"t": "颠沛之揭。", "b": "《诗·大雅·荡》"}, {"t": "唇揭者甚齿塞。", "b": "《战国策》"}]}]}]','jingmo-wenyan');
