('11540wx','菑','1','zī','艹','11','','[{"pinyin": "zī", "defs": [{"meaning": "(形声。从艸,甾(zī)声。荒地,故从艸。本义:古代指初耕的田地)。"}, {"meaning": "同本义。", "cites": [{"t": "菑,不耕田也。", "b": "《说文》。按,古文从田,巛声,小篆又加草耳。不耕田者,不耕而才耕之田也。"}, {"t": "不菑畬。", "b": "《易·无妄》。董遇注:“菑,反草也。”"}, {"t": "田一岁曰菑,二岁曰新田,三岁曰畬。", "b": "《尔雅》"}, {"t": "耕获菑畬,时时利赖其用。", "b": "明·徐光启《甘薯疏序》"}], "words": [{"w": "菑畬", "t": "开垦一年和三年的地"}, {"w": "菑亩", "t": "初耕的田地。"}]}, {"meaning": "直立而枯死的树木。", "cites": [{"t": "其菑其翳。", "b": "《诗·大雅·皇矣》"}, {"t": "周公之状,身如断菑。", "b": "《荀子·非相》"}]}, {"meaning": "开垦;耕耘。", "cites": [{"t": "厥父菑,厥子乃弗肯播。", "b": "《书·大诰》"}], "words": [{"w": "菑畬", "t": "耕耘;又耕稼为民生之本,故以喻事物的根本"}, {"w": "菑攘", "t": "开拓;平定。"}]}]}]','jingmo-wenyan');
