('11692wx','彫','1','diāo','彡','11','','[{"pinyin": "diāo", "defs": [{"meaning": "(雕的异体字)。"}, {"meaning": "雕刻,刻镂。", "cites": [{"t": "彫,琢文也。从彡,周声。", "b": "《说文》"}, {"t": "彫,镂也。", "b": "《释言》"}, {"t": "朽木不可彫也。", "b": "《论语》。"}], "words": [{"w": "彫本", "t": "刻板印刷的书"}, {"w": "彫玉", "t": "刻有花纹的玉石"}, {"w": "彫像", "t": "彫刻的人像。"}]}, {"meaning": "用彩画装饰。", "cites": [{"t": "彫,画也。", "b": "《广雅》"}, {"t": "厚敛以彫墙。", "b": "《左传·宣公二年》。注:“画也。”"}, {"t": "天子彫弓。", "b": "《荀子·大略》"}, {"t": "尻乎彫俎之上。", "b": "《庄子·达生》。释文:“画饰之俎也。”"}], "words": [{"w": "彫弓", "t": "有彩绘的弓"}, {"w": "彫服", "t": "漆绘文采的盛箭器"}, {"w": "彫楹", "t": "刻绘文采的屋柱"}, {"w": "彫云", "t": "彩云。"}]}, {"meaning": "草木衰落;损伤;衰败。", "cites": [{"t": "岁寒,然后知松柏之后彫也。", "b": "《论语·子罕下》"}, {"t": "今宫室崇侈,民力彫尽,怨讟(dú怨恨)并作。", "b": "《左传·昭公八年》"}, {"t": "臣恐民力彫尽,下不堪命也。", "b": "《三国志·栈潜传》"}], "words": [{"w": "彫散", "t": "凋零离散"}, {"w": "彫衰", "t": "凋败。衰败"}, {"w": "彫破", "t": "残破。"}]}, {"meaning": "用同“叼”。用嘴衔住。", "cites": [{"t": "只变作一个饿老鹰,彫了他的衣服。", "b": "《西游记》"}]}]}]','jingmo-wenyan');
