('12492wx','媟','1','xiè','女','12','','[{"pinyin": "xiè", "defs": [{"meaning": "轻侮;不恭敬。", "cites": [{"t": "媟,孈也。", "b": "《说文》"}, {"t": "好媟戏,以故得媟黩贵幸。", "b": "《汉书·枚皋传》"}, {"t": "接遇慎容谓之恭,反恭为媟。", "b": "《新书·道术》"}], "words": [{"w": "媟笑", "t": "戏笑"}, {"w": "媟黩", "t": "媟渎。轻慢;亵狎。"}]}, {"meaning": "过于亲昵而不庄重。", "cites": [{"t": "古者大臣不媟。", "b": "《汉书·贾山传》。师古曰:“媟,狎也。”"}, {"t": "幽王荒废,媟近小人。", "b": "《诗·小雅·宾之初筵序》"}, {"t": "伤之者不敬,吮之者过媟,是以圣贤不为也。", "b": "唐·皮日休《鄙孝议上》"}], "words": [{"w": "媟近", "t": "狎昵;指狎昵亲近的小人"}, {"w": "媟狎", "t": "狎昵;不庄重;淫狎"}, {"w": "媟媟", "t": "媟慢。轻薄,不庄重。"}]}]}]','jingmo-wenyan');
