('12591wx','媿','1','kuì','女','12','','[{"pinyin": "kuì", "defs": [{"meaning": "惭愧", "cites": [{"t": "媿,惭也。从女,鬼声。", "b": "《说文》。"}, {"t": "所以媿厉之也。", "b": "《礼记·聘礼》"}, {"t": "永媿乎道德。", "b": "《庄子·骈拇》"}, {"t": "众人媿之。", "b": "《荀子·儒效》"}], "words": [{"w": "媿切", "t": "使之深深地感到惭愧"}, {"w": "媿色", "t": "惭愧的神色"}, {"w": "媿佩", "t": "对人佩服,自愧不如"}, {"w": "媿怍", "t": "惭愧"}, {"w": "媿赧", "t": "因惭愧而面红耳赤。"}]}, {"meaning": "羞辱。", "cites": [{"t": "媿,耻也。", "b": "《广雅》"}, {"t": "大夫种始谋曰:“昔者吴夫差不顾义而媿吾王。”", "b": "汉·袁康《越绝书》"}]}, {"meaning": "感谢。", "cites": [{"t": "臣常媿其长者,思有以报。", "b": "《新唐书》"}, {"t": "心摇只待东方晓,长媿寒鸡第一声。", "b": "唐·陆龟蒙《自遣》"}]}]}]','jingmo-wenyan');
