('12896wx','揜','1','yǎn','扌','12','','[{"pinyin": "yǎn", "defs": [{"meaning": "捕取;袭取。", "cites": [{"t": "揜,自关以东,取曰揜,一曰覆也。", "b": "《说文》"}, {"t": "诸侯不揜群。", "b": "《礼记·王制》"}, {"t": "揜禽旅。", "b": "《谷梁传·昭公八年》"}, {"t": "揜群雅。", "b": "《史记·司马相如传》"}, {"t": "取之不围泽,不揜群。", "b": "汉·刘向《说苑·修文》"}], "words": [{"w": "揜群", "t": "捕取兽群。"}]}, {"meaning": "遮蔽;掩藏。", "cites": [{"t": "广轮揜坎。", "b": "《礼记·檀弓》"}, {"t": "出入相揜。", "b": "《荀子·富国》"}, {"t": "忽见一个人揜揜缩缩,在那瓜地中。", "b": "《二刻拍案惊奇》"}], "words": [{"w": "揜覆", "t": "遮盖"}, {"w": "揜著", "t": "掩饰自己的坏处,显示自己的好处"}, {"w": "揜眼", "t": "眼罩"}, {"w": "揜匿", "t": "遮掩。"}]}, {"meaning": "承袭。", "cites": [{"t": "教诲开导成王,使谕于道,而能揜迹于文武。", "b": "《荀子·儒效》"}], "words": [{"w": "揜迹", "t": "承袭先辈的事业。"}]}, {"meaning": "夺去。", "cites": [{"t": "见寝石,以为虎也。惧揜其气也。", "b": "《淮南子·泛论》"}]}]}]','jingmo-wenyan');
