INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('13031wx','結','1','jié','糹','12','','[{"pinyin": "jié", "defs": [{"meaning": "(形声。从糸(mì),表示与线丝有关,吉声。本义:用线、绳、草等条状物打结或编织)。"}, {"meaning": "同本义。", "cites": [{"t": "结,缔也。", "b": "《说文》"}, {"t": "带有结。", "b": "《左传·昭公十一年》"}, {"t": "德车结旌。", "b": "《礼记·曲礼》"}, {"t": "善结,无绳钩而不可解。", "b": "《老子》"}, {"t": "民结绳而用之。", "b": "《庄子·胠箧》"}], "words": [{"w": "结缨", "t": "系结帽带"}, {"w": "结网;结缨", "t": "用羽毛编织饰物。"}]}, {"meaning": "结束。", "cites": [{"t": "故君子行思乎其所结。", "b": "刘安《淮南子》"}], "words": [{"w": "结末", "t": "结果;了结"}, {"w": "结了", "t": "妥了,得了,完了"}, {"w": "结煞", "t": "结果,结局"}, {"w": "结绝", "t": "了结,结束。"}]}, {"meaning": "凝结。", "cites": [{"t": "严霜结庭兰。", "b": "《玉台新咏·古诗为焦仲卿妻作》"}], "words": [{"w": "水结成冰;结冰;结露;结涩", "t": "结块阻塞住"}, {"w": "结心", "t": "积聚于心"}, {"w": "结聚", "t": "集结聚合。"}]}, {"meaning": "系;扎缚。", "cites": [{"t": "乃割皮解肌,诀脉结筋。", "b": "《史记·扁鹊仓公列传》"}, {"t": "君结绶兮千里。", "b": "江淹《别赋》"}], "words": [{"w": "结绶", "t": "结系印绶"}, {"w": "结缨", "t": "系好帽带"}, {"w": "结缆", "t": "系舟;停舟"}, {"w": "结缡", "t": "亦作“结缡”。古代女子临嫁时,母为之系结佩巾,以示出嫁后奉事舅姑,好好操持家务。"}]}, {"meaning": "连接。", "cites": [{"t": "子贡相卫而结驷连骑。", "b": "《史记》"}], "words": [{"w": "结阵", "t": "亦作“结陈”。列成队形;结成阵势"}, {"w": "结队", "t": "排成队形"}, {"w": "结寿缘", "t": "旧俗过生日时,将佛豆煮熟分散给众人以祈长寿"}, {"w": "结踪", "t": "脚步相连,前后相随。"}]}, {"meaning": "联结;结合。", "cites": [{"t": "结以恩遇。", "b": "清·梁启超《谭嗣同传》"}], "words": [{"w": "结丝萝", "t": "结亲"}, {"w": "结会", "t": "结缘,因有缘分而相会"}, {"w": "结勾", "t": "勾结"}, {"w": "结掳", "t": "结伙掳掠。"}]}, {"meaning": "建造;构筑。", "cites": [{"t": "结庐在人境。", "b": "晋·陶渊明《饮酒》"}, {"t": "崖穴无结构。", "b": "《左太冲诗》"}], "words": [{"w": "结庐", "t": "造房子。也借指居住"}, {"w": "结宇", "t": "建造屋舍"}, {"w": "结茅", "t": "亦作“结茆”。编茅为屋。即建造简陋的屋舍"}, {"w": "结屋", "t": "构筑屋舍。"}]}, {"meaning": "屈曲;盘旋。", "cites": [{"t": "蚯蚓结。", "b": "《礼记·月令》"}]}, {"meaning": "结交;订立。", "cites": [{"t": "欲结于君。", "b": "《史记·廉颇蔺相如列传》"}, {"t": "结好孙权。", "b": "《三国志·诸葛亮传》"}, {"t": "结反而别。", "b": "《资治通鉴·汉纪》"}, {"t": "自结于东。", "b": "《资治通鉴》"}], "words": [{"w": "结好", "t": "结交通好"}, {"w": "结邻", "t": "相交为邻居友好"}, {"w": "结托", "t": "高攀,托故结识"}, {"w": "结援", "t": "攀附,高攀"}, {"w": "结契", "t": "结交。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('13032wx','絑','1','zhū','糹','12','','[{"pinyin": "zhū", "defs": [{"meaning": "大红色。", "cites": [{"t": "絑,纯赤也。《虞书》丹朱如此。", "b": "《说文》"}, {"t": "而絑弗能统也。", "b": "《淮南子·泰族》。注:“絑尧子也。”按,此字后出。《易》:朱绂方来;《诗》:我朱孔扬。只作朱。盖赤心木引申之义。"}]}]}]','jingmo-wenyan');
