('13033wx','絓','1','guà','糹','12','','[{"pinyin": "guà", "defs": [{"meaning": "茧粗丝。", "cites": [{"t": "絓,茧滓絓头也。从糸,圭声。", "b": "《说文》"}, {"t": "絓,紬也。", "b": "《广雅》"}, {"t": "绛缇絓紬丝絮绵。", "b": "《急就篇》。颜注:“紬之尤粗者曰絓。茧滓所抽也。”"}]}, {"meaning": "悬挂。", "cites": [{"t": "絓,悬也。", "b": "《广雅》"}, {"t": "不絓圣人之罔。", "b": "《汉书·叙传上》"}], "words": [{"w": "高絓", "t": "高高悬挂。"}]}, {"meaning": "绊住;挂碍。", "cites": [{"t": "君闻大鱼乎?网不能止,徼不能絓也,荡而失水,蝼蚁得意也。", "b": "《韩非子·说林下》"}, {"t": "车絓于木而止。", "b": "《史记·齐太公世家》"}], "words": [{"w": "絓阂", "t": "挂碍;牵掣"}, {"w": "絓绝", "t": "绊断。"}]}, {"meaning": "连及;连结。", "cites": [{"t": "心絓结而不解兮。", "b": "《楚辞·哀郢》"}, {"t": "而祸福絓罗。", "b": "《太玄·玄莹》。注:“犹流离也。”"}], "words": [{"w": "絓染", "t": "牵连,连累"}, {"w": "絓误", "t": "因受牵连而失官。"}]}]}]','jingmo-wenyan');
