('13697wx','搉','1','què','扌','13','','[{"pinyin": "què", "defs": [{"meaning": "敲击。", "cites": [{"t": "搉,敲击也。从手,隺声。", "b": "《说文》"}, {"t": "搉其眼以为人彘。", "b": "《汉书·五行志》"}, {"t": "搉击也。", "b": "《广雅·释诂三》"}, {"t": "先是高后鸩杀如意,支断其母戚夫人手足,搉其眼,以为人彘。", "b": "《汉书》。注:“搉,谓敲击去其精也。”"}]}, {"meaning": "研讨。也作“榷”。", "cites": [{"t": "商搉万俗。", "b": "《文选·左思·吴都赋》"}, {"t": "没入辜榷财物。", "b": "《汉书·陈成传》"}, {"t": "多辜榷为奸利者。", "b": "《汉书·翟方进传》"}], "words": [{"w": "搉扬", "t": "商量讨论。"}]}, {"meaning": "专;专卖。", "cites": [{"t": "搉,专也。", "b": "《后汉书·灵帝纪》注"}, {"t": "搉者,独也。", "b": "《史记·没郑传》索隐"}, {"t": "榷酒酤。", "b": "《汉书·武帝纪》"}], "words": [{"w": "搉利", "t": "官府对某些物品实行专卖以获利"}, {"w": "搉沽", "t": "专卖"}, {"w": "搉油", "t": "官府专利卖油"}, {"w": "搉茶", "t": "官府对茶叶的专卖"}, {"w": "搉商", "t": "货物专卖"}, {"w": "搉酤", "t": "官府专利卖酒"}, {"w": "搉管", "t": "主管专卖。"}]}, {"meaning": "较量。", "cites": [{"t": "豪吏猾民,辜而搉之。", "b": "《汉书·王莽传》"}], "words": [{"w": "搉量", "t": "较量。"}]}]}]','jingmo-wenyan');
