('13748wx','閟','1','bì','閠','13','','[{"pinyin": "bì", "defs": [{"meaning": "闭门。", "cites": [{"t": "閟,闭门也。从门,必声。与闭略同。", "b": "《说文》"}, {"t": "闭而以夫人言。", "b": "《左传·庄公十二年》"}, {"t": "閟宫有侐。", "b": "《诗·鲁颂·閟宫》"}, {"t": "见孟仁,从之,閟。", "b": "《左传·庄公三十二年"}, {"t": "视尔不臧,我思不閟。", "b": "《诗·鄘风·载驰》"}]}, {"meaning": "关闭;深闭。", "cites": [{"t": "其病癃閟。", "b": "《素问·五常政大论》。注:“大便干涩不利也。”"}], "words": [{"w": "閟幽", "t": "闭塞幽深"}, {"w": "閟气", "t": "闭住气息"}, {"w": "閟绝", "t": "闭塞隔绝。"}]}, {"meaning": "慎重;珍重。", "cites": [{"t": "天閟毖我成功所。", "b": "《书·大诰》。传:“閟,慎也。”"}], "words": [{"w": "閟重", "t": "慎重"}, {"w": "閟啬", "t": "谨慎珍惜。"}]}]}]','jingmo-wenyan');
