('13878wx','嗛','1','qiān qiǎn xián','口','13','','[{"pinyin": "qiān", "defs": [{"meaning": "谦虚。", "cites": [{"t": "易之嗛嗛。", "b": "《汉书·艺文志》"}, {"t": "思嗛约兮。", "b": "班固《东征赋》"}, {"t": "嗛嗛之德。", "b": "《国语·晋语》"}], "words": [{"w": "嗛小", "t": "谦虚谨慎"}, {"w": "嗛退", "t": "谦逊退让"}, {"w": "嗛约", "t": "谦恭检束"}, {"w": "嗛嗛", "t": "谦逊的样子。"}]}]}, {"pinyin": "qiǎn", "defs": [{"meaning": "猴鼠之类的颊囊。", "cites": [{"t": "[王孙]窃取人食,皆知自实其嗛。", "b": "唐·柳宗元《赠王孙文》"}]}]}, {"pinyin": "xián", "defs": [{"meaning": "用嘴含。", "cites": [{"t": "嗛,口所衔也。从口,兼声。", "b": "《说文》"}, {"t": "景帝恚,心嗛之而未发也。", "b": "《史记·外戚世家》"}, {"t": "而昆莫生,弃于野。乌嗛肉飞其上,狼往乳之。", "b": "《史记·大宛列传》"}]}, {"meaning": "怀恨。", "cites": [{"t": "会袁有豪民尝受守杖,知使者意嗛守,即诬守纳己赇。", "b": "高启《书博鸡者事》"}]}, {"meaning": "歉收;不足。", "cites": [{"t": "一谷不升谓之嗛。", "b": "《谷梁传·襄公二十四年》"}, {"t": "满则虑嗛。", "b": "《荀子·仲尼》"}, {"t": "今谷嗛未报。", "b": "《汉书·郊祀志》"}]}, {"meaning": "谦虚。", "cites": [{"t": "夫大道不称,大辩不言,大仁不仁,大廉不嗛,大勇不忮。", "b": "《庄子·齐物论》"}, {"t": "主信爱之,则谨慎而嗛。", "b": "《荀子·仲尼》"}, {"t": "《易》之嗛嗛。", "b": "《汉书·艺文志》"}]}, {"meaning": "满足;快意", "cites": [{"t": "由俗谓之,道尽嗛矣。", "b": "《荀子·解蔽》"}, {"t": "齐桓公夜半不嗛。", "b": "《战国策·魏策二》"}]}]}]','jingmo-wenyan');
