('14044wx','甃','1','zhòu','瓦','13','','[{"pinyin": "zhòu", "defs": [{"meaning": "以砖瓦砌的井壁。", "cites": [{"t": "甃,井壁也。从瓦,秋声。", "b": "《说文》"}, {"t": "古寺拆为修寨木,荒坟开作甃城砖。", "b": "唐·杜荀鹤《旅泊遇郡中叛乱示同志》"}], "words": [{"w": "甃甓", "t": "井壁"}, {"w": "甃石", "t": "垒石为壁。"}]}, {"meaning": "井。", "cites": [{"t": "自弱涓甃,地幽井谷。", "b": "南朝宋·鲍照《侍郎报满辞阁疏》"}], "words": [{"w": "深甃", "t": "深井。"}]}, {"meaning": "砖。", "cites": [{"t": "垒甃而成楼,十有三重。", "b": "金·董解元《西厢记诸宫调》"}]}, {"meaning": "砌。以砖修井。", "cites": [{"t": "甃,亦治也。以砖垒井,修井之坯,谓之为甃。", "b": "《易·井》孔颖达疏引"}, {"t": "甃无咎。", "b": "《易·井》。干注:“以砖垒井曰甃。”"}]}, {"meaning": "修盖瓦沟;砌垒砖石。", "cites": [{"t": "甃屋行水。", "b": "《管子》"}, {"t": "起百尺琉璃宝殿,甃九层白玉瑶台。", "b": "《醒世恒言》"}], "words": [{"w": "甃石", "t": "砌石;垒石为壁"}, {"w": "甃地", "t": "以砖、石等砌地"}, {"w": "甃城", "t": "筑城;修城"}, {"w": "甃理", "t": "修治。"}]}]}]','jingmo-wenyan');
