INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('14689wx','翣','1','shà','羽','14','','[{"pinyin": "shà", "defs": [{"meaning": "古代棺饰。垂于棺的两旁。", "cites": [{"t": "翣,棺羽饰也。天子八,诸侯六,大夫四,士二。下花。从羽,妾声。", "b": "《说文》"}, {"t": "后之丧持翣。", "b": "《周礼·女御》"}, {"t": "大丧持翣。", "b": "《周礼·御仆》。注:“棺饰也。”"}, {"t": "衣翣柳之材。", "b": "《周礼·缝人》"}, {"t": "设蒌翣。", "b": "《礼记·檀弓》。注:“棺之墙饰。”"}, {"t": "饰棺墙,置翣。", "b": "《礼记·檀弓上》"}], "words": [{"w": "翣柳", "t": "灵柩上的装饰"}, {"w": "翣翣", "t": "古代棺木的装饰。"}]}, {"meaning": "扇。", "cites": [{"t": "大扇谓之翣。", "b": "《小雅·广服》"}, {"t": "杖笠翣。", "b": "《仪礼·既夕礼·燕器》。注:“扇也。”"}, {"t": "被裘而以翣翼。", "b": "《淮南子·说南》。注:“扇也。”"}, {"t": "手无容,不翣也。", "b": "《礼记·少仪》"}]}, {"meaning": "特指古代仪仗中用的大掌扇。", "cites": [{"t": "有翣羽盖。", "b": "《周礼·巾车》。注:“所以御风尘。”"}, {"t": "古者扇翣,皆编次雉羽或尾为之,故于文从羽。", "b": "《宋史·仪卫志》"}]}, {"meaning": "古代钟鼓架上的饰物。", "cites": [{"t": "殷之崇牙,周之璧翣。", "b": "《礼记·明堂位》"}]}]}]','jingmo-wenyan');
