INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('15391wx','隤','1','tuí','阝','14','','[{"pinyin": "tuí", "defs": [{"meaning": "(形声。从阜(fù),贵声。从阜,与山或建筑有关。本义:崩颓;坠下)。"}, {"meaning": "同本义。", "cites": [{"t": "隤,下队也。", "b": "《说文》"}, {"t": "隤铜丸以擿鼓。", "b": "《汉书·史丹传》。师古曰:“隤,下也。”"}, {"t": "障隤处。", "b": "清·邵长蘅《青门剩稿》"}], "words": [{"w": "隤缺", "t": "倒塌崩坏之处"}, {"w": "隤圮", "t": "倒塌;毁坏"}, {"w": "隤陷", "t": "跌倒或掉下"}, {"w": "隤照", "t": "落日,夕照。"}]}, {"meaning": "使。", "cites": [{"t": "苗生叶以上,稍耨陇草。因隤其土以附苗根。", "b": "《汉书·食货志上》"}]}, {"meaning": "败坏。", "cites": [{"t": "李陵既生降,隤其家声。", "b": "司马迁《报任安书》"}, {"t": "士众灭兮名已隤。", "b": "《汉书·苏武传》。师古曰:“隤,坠也。”"}]}, {"meaning": "遗失。", "cites": [{"t": "乐隤心,其如忘,哀缘情而来宅。", "b": "《文选·陆机·叹逝赋》"}]}, {"meaning": "风车的出粮口。", "cites": [{"t": "碓隤扇隤舂簸扬。", "b": "《急就篇》"}]}, {"meaning": "疝气。", "cites": [{"t": "其传为索泽,其传为颓疝。…颓与聩古字通。", "b": "《内经》"}]}, {"meaning": "周邑名 。故城在今河南省获嘉县境。一说在河南省修武县境。", "cites": [{"t": "河内修武有隤城。", "b": "《郡国志》"}]}, {"meaning": "安。", "cites": [{"t": "夫坤,隤然示人简矣。", "b": "《易·系辞下》"}]}]}]','jingmo-wenyan');
