INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('16276wx','穀','1','gǔ','禾','15','','[{"pinyin": "gǔ", "defs": [{"meaning": "木名。又称“楮”,即构树 。落叶乔木。新生枝密披灰色粗毛,具乳汁。叶阔卵形至长圆状卵形,叶端渐尖,全缘或缺裂。初夏开淡绿色小花,雌雄异株。果实圆球形,成熟时鲜红色,皮可制桑皮纸。"}, {"meaning": "(形声。从禾。本义:庄稼和粮食的总称。)。"}, {"meaning": "官俸。古人常以谷物计禄。", "cites": [{"t": "穀禄莫厚焉。", "b": "《荀子·王霸》"}]}, {"meaning": "讣告。", "cites": [{"t": "齐谷王姬之丧,鲁庄公为之大功。或曰鲁嫁,故为之服姊妹服。", "b": "《礼记》"}]}, {"meaning": "古城名。故址在今山东省平阴县西南。春秋齐地。位于齐国西境,为当时交通要地。秦代称为谷城。"}, {"meaning": "“谷2”的繁体字。"}, {"meaning": "善;良。", "cites": [{"t": "穀旦于差(选择),南方之原。", "b": "《诗·陈风·东门之枌》"}]}, {"meaning": "赡养;养着。", "cites": [{"t": "以穀我士女。", "b": "《诗·小雅·甫田》"}], "words": [{"w": "穀马", "t": "喂马"}, {"w": "穀食", "t": "以谷物为食"}, {"w": "穀饱", "t": "以谷食充饥"}, {"w": "穀驽", "t": "以谷物饲养驽马。"}]}, {"meaning": "生;活着。", "cites": [{"t": "穀则异室,死则同穴。", "b": "《诗·王风·大车》"}]}]}]','jingmo-wenyan');
