INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('17950wx','闇','1','àn','門','17','','[{"pinyin": "àn", "defs": [{"meaning": "(形声。从门,音声。本义:闭门)。"}, {"meaning": "同本义。", "cites": [{"t": "闇,闭门也。", "b": "《说文》"}, {"t": "见蔼闇阁读书。", "b": "《梁书·乐蔼传》"}], "words": [{"w": "闇门", "t": "隐蔽的门。"}]}, {"meaning": "蒙蔽;遮蔽。", "cites": [{"t": "桑麻闇日。", "b": "《水经注·江水》"}, {"t": "不下比以闇上。", "b": "《荀子·不苟》。注:“掩上之月也。”"}], "words": [{"w": "闇室", "t": "遮去光线的房间"}, {"w": "闇没", "t": "埋没,掩没。"}]}, {"meaning": "(经传多以闇为之)。", "cites": [{"t": "闇,冥也。", "b": "《小尔雅》"}, {"t": "夏后氏祭其闇。", "b": "《礼记·祭义》"}, {"t": "孝子不服闇。", "b": "《礼记·曲礼》。注:“冥也。”"}, {"t": "彼日月兮闇昧。", "b": "王逸《九思·守志》"}], "words": [{"w": "闇时", "t": "昏暗的时代"}, {"w": "闇昧", "t": "暗淡;指人的隐私。"}]}, {"meaning": "愚昧;糊涂。", "cites": [{"t": "刘璋闇弱。", "b": "《三国志·诸葛亮传》"}, {"t": "下闇则上聋。", "b": "《谷梁传·文公六年》"}], "words": [{"w": "闇惑", "t": "愚昧不明"}, {"w": "闇短", "t": "才识愚劣短浅。"}]}, {"meaning": "昏庸。", "cites": [{"t": "故人主无便嬖左右足信者谓之闇。", "b": "《荀子·君道》"}], "words": [{"w": "闇君", "t": "昏君"}, {"w": "闇王", "t": "昏君。"}]}]}]','jingmo-wenyan');
