('18666wx','矇','1','méng','目','18','','[{"pinyin": "méng", "defs": [{"meaning": "盲,目失明。", "cites": [{"t": "矇,童矇也,一曰不明也。", "b": "《说文》"}, {"t": "矇瞍奏公。", "b": "《诗·大雅·灵台》。传:“有眸子而无见曰矇”"}, {"t": "目有眸无珠子曰矇。", "b": "《字林》"}, {"t": "矇瞍谓之不章。", "b": "《楚辞·怀沙》。注:“盲者也。”"}], "words": [{"w": "蒙瞽", "t": "蒙瞢,蒙叟,均指盲人"}, {"w": "蒙聋", "t": "目不见,耳不闻"}, {"w": "蒙瞀", "t": "目不明"}, {"w": "蒙蒙", "t": "糊涂不明"}, {"w": "蒙腾", "t": "模糊不清。"}]}, {"meaning": "幼稚,暗昧不明。", "cites": [{"t": "乃今日发矇。", "b": "扬雄《长杨赋》。注:“矇与蒙古字通。”"}]}, {"meaning": "指乐官。古代以盲人充任,故名。", "cites": [{"t": "岂其以千乘之相,易淫乐之蒙,必无人焉故也。", "b": "《左传》"}], "words": [{"w": "蒙叟", "t": "蒙瞽。指古代以盲人充任的乐官"}, {"w": "蒙奏", "t": "盲乐师的演奏。"}]}]}]','jingmo-wenyan');
INSERT INTO `dictionary` (`dict_id`,`entry`,`type`,`pinyin`,`radical`,`stroke`,`wubi`,`explain`,`source`) VALUES
('18667wx','繐','1','suì','糹','18','','[{"pinyin": "suì", "defs": [{"meaning": "细而稀疏的麻布。古时多用作丧服。", "cites": [{"t": "繐,细疏布也。从糹,惠声。", "b": "《说文》"}, {"t": "繐衰繐裳。又,请繐衰而环緻。", "b": "《礼记·檀弓》。注:“繐衰,小功之缕,而四升半之衰。”"}, {"t": "不屦繐屦。", "b": "《仪礼·士冠礼》"}, {"t": "菲繐。", "b": "《荀子·礼论》"}], "words": [{"w": "繐裳", "t": "细疏麻布丧服"}, {"w": "繐帷", "t": "繐帐。用细疏麻布缝成的灵帐。"}]}, {"meaning": "用同穗。用丝线等结扎成的穗状下垂的装饰品。", "cites": [{"t": "橙黄的繐子仍旧沉沉地垂下来。", "b": "曹禺《北京人》"}]}]}]','jingmo-wenyan');
