('18923wx','霤','1','liù','雨','18','','[{"pinyin": "liù", "defs": [{"meaning": "屋檐的流水。", "cites": [{"t": "霤,屋下流也。", "b": "《说文》"}, {"t": "晨霤承檐滴。", "b": "潘岳《悼亡诗》"}, {"t": "霤冷冷以夜下兮。", "b": "潘岳《寡妇赋》"}], "words": [{"w": "檐霤", "t": "屋檐水"}, {"w": "晨霤", "t": "早晨的屋檐水。"}]}, {"meaning": "向下流的水。", "cites": [{"t": "泰山之霤穿石。", "b": "《汉书·枚乘传》"}, {"t": "悬霤空中注。", "b": "清·方朝《开先寺观瀑布》"}]}, {"meaning": "承霤 ,指屋檐的接水长槽。", "cites": [{"t": "匿于人家霤槽中。", "b": "宋·陆游《老学庵笔记》"}], "words": [{"w": "霤槽", "t": "即承霤。"}]}, {"meaning": "檐下滴水处。", "cites": [{"t": "设洗篚于祚阶东南,当东霤。", "b": "《仪礼·燕礼》"}]}, {"meaning": "借指屋宇,房屋。", "cites": [{"t": "南房小壇,观绝霤只。", "b": "《楚辞·大招》"}]}]}]','jingmo-wenyan');
