('20143wx','饘','1','zhān','飠','21','','[{"pinyin": "zhān", "defs": [{"meaning": "稠粥。", "cites": [{"t": "饘,糜也。从食,亶声。周谓之糜木,谓之饘。", "b": "《说文》。按,厚者曰饘,稀者曰粥。”"}, {"t": "相谒而食麦饘。", "b": "《方言一》。注:“糜也。”"}, {"t": "宁子职纳橐饘焉。", "b": "《左传·僖公二十八年》"}, {"t": "饥馑仍臻饘蔬糊口。", "b": "崔浩《食经序》"}, {"t": "昔正考父饘粥以糊口。", "b": "宋·司马光《训俭示康》"}]}, {"meaning": "泛指稀饭。", "cites": [{"t": "饘粥之食。", "b": "《礼记·檀弓》"}], "words": [{"w": "饘饘", "t": "稀饭与菜汤"}, {"w": "饘食", "t": "饘粥。都指稀饭"}, {"w": "饘饮", "t": "稀饭与菜汤。"}]}, {"meaning": "煮粥。", "cites": [{"t": "饘于是,粥于是,以饘余口。", "b": "《史记·孔子世家》"}]}, {"meaning": "吃饭。", "cites": [{"t": "野僧早饥不能饘。", "b": "黄庭坚《武昌松风阁》"}]}]}]','jingmo-wenyan');
